INSERT INTO door_catalog VALUES('_alster','!ALSTER.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/!ALSTER.LHA','Children','XIM','Children',NULL,'/*/sNT\eVOLUTION',NULL,'/ __ \__ \ ______\ ____ _ \__ \ ______ \_  > / / / / / / _/ / _/ _/_/ / / / / _/ / / // / \/\/\/\__/\___/\/ \___/\/\/\__/\___/\/\/ \/',replace('  __________________________________________\n / __ \__ \ ______\ ____ _ \__ \ ______ \_  >\n/ / / / / / _/ / _/ _/_/ / / / / _/ / / // /\n\/\/\/\__/\___/\/ \___/\/\/\__/\___/\/\/ \/\n  -*- iNDEPENDENT cONNECTION pRESENTS -*-\n                #18.12.1995# \n    This tool starts only for NEWUSERS /X\n            bY /*/sNT\eVOLUTION\n[viRTUAL tHEATRE]----------[viRTUAL tHEATRE]\n','\n',char(10)),'NEWUSERPW.TXT',replace('~f\n~CC_pW            \n\n\n\n                    This is the ... XxXxX ... BBS \n  \n\n            It is not for commercial use through other people\n          and not for selling and advertisements of any products.\n  \n\n           This BBS is only for information around --> AMIGA  <--\n  \n             __________________________________________________ \n             }--------->  No illegal Stuff allowed  <---------{\n             \n\n             This BBS runs with a registered AMIEXPRESS V4.xx\n      Copyright 1994 Light Speed Technologies , All rights reserved.\n\n\n','\n',char(10)),NULL,'auto-added',39859,6,0,NULL,NULL,'alster_2','scan',1780048351);
