INSERT INTO door_catalog VALUES('_d_calc','-D-CALC.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/-D-CALC.LHA',NULL,'XIM','______    ________.  /\    ______.__________',NULL,'VASCAL/DLT',NULL,'\____ \/\/  _  /  ¦_/\/\/\/ ___/ ¦  \  __  / ¦:  /   //    /\  ¦ \_ \\  /  \     \\/  \/ ¦______/_______/_____/___\____/__¦___/____\',replace('______    ________.  /\    ______.__________\n\____ \/\/  _  /  ¦_/\/\/\/ ___/ ¦  \  __  /\n¦:  /   //    /\  ¦ \_ \\  /  \     \\/  \/\n¦______/_______/_____/___\____/__¦___/____\\n+-------------(bRinGs  ToDaY)-----------mk-+\n       CALCULATOR V1.0 by VASCAL/DLT\n+------------------------------------------+\n','\n',char(10)),'CALC.DOC',replace('                                    /\                .__\n    ___________________________    /  \_______________|  \_____________\n    \         \          /    /___/    \          /   |   \    __     /\n     \______   \   ___  /__  /    \____/_____    /_   |    \    \    /\n      |    /    \  \   /  / /     |    |   _/___/ |   _     \    \__/\n      |         /        /        |    |   \      |   |      \    \\n      |________/\_______/\_______/|____|\___.     |___|      /_____\\n                                            |_____|D! |_____/\n                           \n                ->  SYSTEM INFO V 1.0 BY VASCAL/DELIGHT  <-\n              -> BREAK AWAY BBS +49-471-503758 DELIGHT EHQ <-\n                       -> RELEASE DATE IS 12-21-93 <-\n       \n  \n  \nPurpose:\n~~~~~~~~\n        This door is - as you can see on the name - an online calc-\n        ulator door for Amiexpress. Well what is it good for ? In \n        my opinion there are a lot of situations, e.g. if you want\n        to calculate your credits or ratio ..... well there are no  \n        limitations set - just test it out 8-) !        \n \n \nRequirement:\n~~~~~~~~~~~~\n        Any Amiga Modell\n        Any Amiexpress version\n        Any Amount of RAM\n        Any Workbench Version\n \n \nInstallation:\n~~~~~~~~~~~~~\n        Make sure RPSTART is started. Copy all files into the dirs\n        they are supported from me.\n\n\n        AMIEX V1.XX :\n                     Install the same way described in the AMIEX V2.XX \n                     Section.\n \n        AMIEX V2.XX :\n                     ADD to your bbs:commands/CustomCommands\n\n---------------( cut here )-------------------\n\n*CALC      RM050DOORS:CALCULATOR/CALC.REXX\n\n---------------( cut here )-------------------\n\n        AMIEX V3.XX :\n                     Simply move the ICON CALC.INFO to your \n                     BBS:COMMANDS/BBSCMD directory.\n   \n        \n   \nHistory:\n~~~~~~~~\n        V1.0: First release\n \n \n \nBugreport:\n~~~~~~~~~~\n        If you find any bugs in this Util contact me (VASCAL) at my BBS\n        THE BREAK AWAY BBS -> 49-471-503758.\n  \n  \n          \nDisclaimer:\n~~~~~~~~~~~\n        This DOOR is CALLWARE that means if you install it call my BBS and \n        say HELLO and upload something hehehe 8-)\n  \n  \n  \nThanx:\n~~~~~~\n        Thanx must this time go to mOGUE/$CEPTIC for the nice \n        MENU ascii\n  \n  \n       \nGreets:\n~~~~~~~\n        SCAN: OK OK I WILL USE YOUR ASCII`S 8-)\n        BLACKBIRD: HEY - DELIGHT IS BACK TO KICK AND I`M IMPROVING\n                   AS WELL HEHE ...\n        BREAKER: C U NEXT WEEK AND DON`T FORGET TO ASK THOSE GUYS \n                 FOR THE NEW HD - YOU KNOW I REALLY NEED IT.\n        POWELL: HEY YOU ARE UPLODING RIGHT NOW - IN THIS SECOND - \n                YOU ARE BEAMING ME UP THE NEW AMBERMOON AND I`M\n                JUST GREETING YOU HEHE KEEP ON UPLOADING - DON`T \n                STOP HONEY GIMME MORE 8-)\n        DR.RAM: WELL HAD NO CHANCE TO CHAT WITH YOU.\n        WARLORD: WHERE`S YOUR THANX FOR THE AMIEX AREXX COMMANDS\n                 FILE ?? HEHE\n        DAZE: WHY ARE YOU READING THIS?? NO PANIC I`LL SEND THAT \n              MODEM THIS OR NEXT WEEK\n        PALLADIN: DIDN`T HEAR ANYTHING FROM YOU FOR SOOOO LONG.\n\n        ALL TRADERS I KNOW: CALL MY BBS AND SAY HELLO HEHEHE\n\n\nLast words:\n~~~~~~~~~~~\n        This door is an AREXX door but it is pretty fast - even on an \n        easy 68000. If you don`t think so just by an 680X0 and don`t\n        blame me !\n\nVery last words:\n~~~~~~~~~~~~~~~~\n        Contact me on ma BBS if you want to become a beta tester\n \n\nContact me on my bbs:  \n~~~~~~~~~~~~~~~~~~~~~\n                                                                .________ \n  _______________________________  ______________________ ._____|       / \n  \___________      \_______     \/           _______    \|     |      /  \n    |        |     _/      |    _/     |______/     |     \     !     /   \n    |               \            \      ____)/_     _      \          \   \n    |        |       \     |      \    |       \    |       \   |      \  \n    |________.       /_____|       \____________\   |________\__|       \ \n    ---------|______/------|________\-----/_________|--------sLa|________\\n                                                                          \n       ø dELIGHt eHq ø         .__________              ._________        \n         ______________________|         /______________|        /        \n         \________    \       /\        /____    \      |       /sTAFf:   \n           /     |     \     /  \      /    |     \     |      / vASCAl & \n          /      _      \             /     _      \___       /   sCAn  & \n         /       |       \           /      |       \  \     /   cYCLONe&  \n        /        |________\___/\____/       |________\      /    sEahAwK         \n       /_________|----------------/_________|--\___________/ øaMIGA oNLY ø\n                   49-471-503758                                          \n','\n',char(10)),NULL,NULL,10431,7,0,NULL,NULL,NULL,'scan',1780048351);
INSERT INTO door_catalog VALUES('_d_dor11','-D-DOR11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/-D-DOR11.LHA',NULL,'XIM','______    ________.  /\    ______.__________',NULL,'vASCAL/dLT',NULL,'\____ \/\/  _  /  |_/\/\/\/ ___/ |  \  __  / |:  /   //    /\  | \_ \\  /  \     \\/  \/ |______/_______/_____/___\____/__|___/____\',replace('______    ________.  /\    ______.__________\n\____ \/\/  _  /  |_/\/\/\/ ___/ |  \  __  /\n|:  /   //    /\  | \_ \\  /  \     \\/  \/\n|______/_______/_____/___\____/__|___/____\\n+-------------(bRinGs  ToDaY)-----------mk-+\n      dOOR-mENU v.1.1 by vASCAL/dLT\n','\n',char(10)),'DOOR.DOC',replace('                                    /\                .__\n    ___________________________    /  \_______________|  \_____________\n    \         \          /    /___/    \          /   |   \    __     /\n     \______   \   ___  /__  /    \____/_____    /_   |    \    \    /\n      |    /    \  \   /  / /     |    |   _/___/ |   _     \    \__/\n      |         /        /        |    |   \      |   |      \    \\n      |________/\_______/\_______/|____|\___.     |___|      /_____\\n                                            |_____|D! |_____/\n                           \n                  ->  DOOR MENU V1.1 BY VASCAL/DELIGHT  <-\n              -> BREAK AWAY BBS +49-471-503758 DELIGHT EHQ <-\n                       -> RELEASE DATE IS 12-26-93 <-\n       \n  \n  \nPurpose:\n~~~~~~~~\n        This door shows you all available DOORS. It first checks\n        the user`s accesslevel, then it displays the DOORMENU\n        that you want the user to see.\n                \n \n \nRequirement:\n~~~~~~~~~~~~\n        Any Amiga Modell\n        Any Amiexpress version\n        Any Amount of RAM\n\n \n \nInstallation:\n~~~~~~~~~~~~~\n        Make sure RPSTART is started. Copy all files into the dir\n        DOORS:DOOR/\n        Check if you have the librarys supported in the libs: dir if \n        not copy them into it.\n        Load your prefered Editor ( Cygnus ed 8-) ) and edit the \n        USRDOORS.TXT and the SYSDOORS.TXT files.\n        Now i have installed a config file called "DOORS:DOOR/DOOR.CFG"\n        - it just has to contain one thing - the access level of the \n        USERS that shall see the "SYSDOORS.TXT" file. All USERS which`s\n        accesslevel is below that will see the text "USRDOORS.TXT".\n        \n        AMIEX V1.XX :\n                     Install the same way described in the AMIEX V2.XX \n                     Section.\n \n        AMIEX V2.XX :\n                     ADD to your bbs:commands/CustomCommands\n\n---------------( cut here )-------------------\n\n*DOORS     RM050DOORS:DOOR/DOOR.REXX\n*OPEN      RM050DOORS:DOOR/DOOR.REXX\n\n---------------( cut here )-------------------\n\n        AMIEX V3.XX :\n                     Simply move the ICON DOORS.INFO and/or OPEN.INFO\n                     to your BBS:COMMANDS/BBSCMD directory.\n   \n        \n   \nHistory:\n~~~~~~~~\n        V1.0: 12-12-93 First release\n        V1.1: Included Config file\n              Improved the output style\n              Now it tells the callerslog that the user used this door\n      \n \nBugreport:\n~~~~~~~~~~\n        If you find any bugs in this Util contact me (VASCAL) at my BBS\n        THE BREAK AWAY BBS -> 49-471-503758.\n  \n  \n          \nDisclaimer:\n~~~~~~~~~~~\n        This DOOR is CALLWARE that means if you install it call my BBS and \n        say HELLO and upload something hehehe 8-)\n  \n  \n  \nThanx:\n~~~~~~\n        Thanx must go to sCAN/dELIGHT for the nice DOORS ascii\n  \n  \n       \nGreets:\n~~~~~~~ SHORT GREETS THIS TIME - \n        SYSOPS: USE THIS DOOR AND GIMME A DIZZY\n        TRADERS: CALL MY BBS AND BEAM S.TH. UP\n        THE REST: GREET ME BACK - WHERE EVER YOU ARE\n	\n\nLast words:\n~~~~~~~~~~~\n        This door is an AREXX door but it is pretty fast - even on an \n        easy 68000.\n\nVery last words:\n~~~~~~~~~~~~~~~~\n        Contact me on ma BBS if you want to become a beta tester\n \n\nContact me on my bbs:  \n~~~~~~~~~~~~~~~~~~~~~\n                                                                .________ \n  _______________________________  ______________________ ._____|       / \n  \___________      \_______     \/           _______    \|     |      /  \n    |        |     _/      |    _/     |______/     |     \     !     /   \n    |               \            \      ____)/_     _      \          \   \n    |        |       \     |      \    |       \    |       \   |      \  \n    |________.       /_____|       \____________\   |________\__|       \ \n    ---------|______/------|________\-----/_________|--------sLa|________\\n                                                                          \n       ø dELIGHt eHq ø         .__________              ._________        \n         ______________________|         /______________|        /        \n         \________    \       /\        /____    \      |       /sTAFf:   \n           /     |     \     /  \      /    |     \     |      / vASCAl & \n          /      _      \             /     _      \___       /   sCAn  & \n         /       |       \           /      |       \  \     /   cYCLONe&  \n        /        |________\___/\____/       |________\      /    sEahAwK         \n       /_________|----------------/_________|--\___________/ øaMIGA oNLY ø\n                   49-471-503758                                          \n','\n',char(10)),NULL,NULL,7371,5,0,NULL,NULL,NULL,'scan',1780048351);
INSERT INTO door_catalog VALUES('_d_inf21','-D-INF21.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/-D-INF21.LHA','Avail','XIM','Avail',NULL,'vASCAL/dLT',NULL,'\____ \/\/  _  /  |_/\/\/\/ ___/ |  \  __  / |:  /   //    /\  | \_ \\  /  \     \\/  \/ |______/_______/_____/___\____/__|___/____\',replace('______    ________.  /\    ______.__________\n\____ \/\/  _  /  |_/\/\/\/ ___/ |  \  __  /\n|:  /   //    /\  | \_ \\  /  \     \\/  \/\n|______/_______/_____/___\____/__|___/____\\n+-------------(bRinGs  ToDaY)-----------mk-+\n|  sYSTEM iNFO v.2.1 by vASCAL/dLT fOR /X  |\n+------------------------------------------+\n','\n',char(10)),'INFO.DOC',replace('                                    /\                .__\n    ___________________________    /  \_______________|  \_____________\n    \         \          /    /___/    \          /   |   \    __     /\n     \______   \   ___  /__  /    \____/_____    /_   |    \    \    /\n      |    /    \  \   /  / /     |    |   _/___/ |   _     \    \__/\n      |         /        /        |    |   \      |   |      \    \\n      |________/\_______/\_______/|____|\___.     |___|      /_____\\n                                            |_____|D! |_____/\n                           \n                ->  SYSTEM INFO V 2.1 BY VASCAL/DELIGHT  <-\n              -> BREAK AWAY BBS +49-471-503758 DELIGHT EHQ <-\n                       -> RELEASE DATE IS 01-30-94 <-\n       \n  \n  \nPurpose:\n~~~~~~~~\n        This is the best information door ever made for /X !\n        Shows you 1. your hardware configurations\n                  2. your software configurations\n                  3. your personal stats\n\n \nRequirement:\n~~~~~~~~~~~~\n        Any Amiga Modell\n        Any Amiexpress version\n        Any Workbench Version\n \n \nInstallation:\n~~~~~~~~~~~~~\n        Make sure RPSTART is started. Copy all files into the dirs\n        they are supported from me. Make sure the commands that are\n        supported in the c dir are existing. If not copy the \n        supported files into your c: directory.\n\n\n        AMIEX V1.XX :\n                     Install the same way described in the AMIEX V2.XX \n                     Section.\n \n        AMIEX V2.XX :\n                     ADD to your bbs:commands/CustomCommands\n\n---------------( cut here )-------------------\n\n*I         RM050DOORS:INFO/INFO.REXX\n*INFO      RM050DOORS:INFO/INFO.REXX\n\n---------------( cut here )-------------------\n\n        AMIEX V3.XX :\n                     Simply move the ICON INFO.INFO and/or I.INFO\n                     to your BBS:COMMANDS/BBSCMD directory.\n   \n        \n   \nHistory:\n~~~~~~~~\n        V1.0: First release\n        V1.1: Some features added - internal release\n        V2.0: Totaly recoded - now shows hard&software configs\n              lotsa new features\n        V2.1: Added new topic - now also shows you your personal\n              stats - little bug was: didn`t show you the hd`s with\n              wb3.1 format so updated the archive with a new command\n              so it will run ok now ;) (tHANX fOR bUGREPORTING !)\n \n \nBugreport:\n~~~~~~~~~~\n        If you find any bugs in this Util contact me (VASCAL) at my BBS\n        THE BREAK AWAY BBS -> 49-471-503758.\n  \n  \n          \nDisclaimer:\n~~~~~~~~~~~\n        This DOOR is CALLWARE that means if you install it call my BBS and \n        say HELLO and upload something hehehe 8-)\n  \n  \n  \nThanx:\n~~~~~~  This time again i have to thank scan for his nice STATS ascii.\n        But thanx must go to a guy as wel that reported me a bug and \n        gave me a little hint , but i`m very sorry that i have forfotten\n        your name ;)\n  \n       \nGreets:\n~~~~~~~ Well actually i don`t know whom to greet this time , so i wont\n        write special personal greets in here this time , just a quick \n        note - hy to all the delight members and hy to all sysops out there\n        and hy to all traders out there and hy to all the rest of the world !\n        And of course hy to my dog hehehe\n \n        \n \n        AND JUST AGAIN: CALL MA BBS AND TELL ME WHAT YA THINK `BOUT THIS\n\n\nLast words:\n~~~~~~~~~~~\n        This door is an AREXX door but it is pretty fast - even on an \n        easy 68000. If you don`t think so just buy an 680X0 and don`t\n        blame me !\n\nVery last words:\n~~~~~~~~~~~~~~~~\n        Contact me on ma BBS if you want to become a beta tester\n \n\nContact me on my bbs:  \n~~~~~~~~~~~~~~~~~~~~~\n                                                                .________ \n  _______________________________  ______________________ ._____|       / \n  \___________      \_______     \/           _______    \|     |      /  \n    |        |     _/      |    _/     |______/     |     \     !     /   \n    |               \            \      ____)/_     _      \          \   \n    |        |       \     |      \    |       \    |       \   |      \  \n    |________.       /_____|       \____________\   |________\__|       \ \n    ---------|______/------|________\-----/_________|--------sLa|________\\n                                                                          \n       ø dELIGHt eHq ø         .__________              ._________        \n         ______________________|         /______________|        /        \n         \________    \       /\        /____    \      |       /sTAFf:   \n           /     |     \     /  \      /    |     \     |      / vASCAl & \n          /      _      \             /     _      \___       /   sCAn  & \n         /       |       \           /      |       \  \     /   cYCLONe&  \n        /        |________\___/\____/       |________\      /    sEahAwK         \n       /_________|----------------/_________|--\___________/ øaMIGA oNLY ø\n                   49-471-503758 zYXEL 16.8oo bAUD !                                         \n','\n',char(10)),NULL,'auto-added',72113,11,1,'AVAIL','Doors/AVAIL','eqx_si23','scan',1780048351);
INSERT INTO door_catalog VALUES('_j_lcv30','-J-LCV30.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/-J-LCV30.LHA','stripp','XIM','_______._____  /\_________:_________________',NULL,'iRoNCoDE!',NULL,'\____  |  | ¬\/  _______  ____/  .___/  ___/ /   |  |  |   \___  ¬\/   |  ¬\  |__|_  _)__ \  ____|____  /____  /\  _|_  /____  /___  /',replace('_______._____  /\_________:_________________\n\____  |  | ¬\/  _______  ____/  .___/  ___/\n/   |  |  |   \___  ¬\/   |  ¬\  |__|_  _)__\n\  ____|____  /____  /\  _|_  /____  /___  /\n+\/---------\/-----\/--\/÷e÷\/-----\/----\/+\n  -LASTCALLER- V3.0 · WRITTEN BY iRoNCoDE!  \n  BEST DESIGN AND MOST FUNCTIONS EVER MADE\n','\n',char(10)),'LASTCV30.DOC',replace('\n******************************************************************************\n*                                                                            *\n*                              LASTCALLER                                    *\n*                             >----------<                                   *\n*                             Version  3.0                                   *\n*                                                                            *\n*                     Written by : iRoNCoDE/jUSTiCE              [28-NOV-93] *\n*                                                                            *\n******************************************************************************\n\n\nI.   INTRODUCTION\n-----------------\n\n     LASTCALLER is a last caller /X-utility that shows the ten last callers\n     on the system.\n     You can use it with every number of nodes (1..X).\n     The bulletin it creates, looks like this:\n\n\n ______  /\________________  _______/\  _____________________________________\n \    / /  \    __        / / _    /  \ \     /     /   ________   \     _  /\n /   /\/ _| \___  \   \__/ /  |___/ _| \/    /\    /\   __/\   /   /\___  \/\n/   /  \ \_  \ /   \   \Mb/   |   | \_  \   /  \  /  \  |   \  \   \   /   \\n\_______\_/   \____/    \ \_______|_/    \______\_____\______\ |\___\______/\n*--------/_____\--|______\---------/______\--------------/_____|------------\n \n nODE cALLER nAME          lOCATION/gROUP          tIME  aCTIONS  uL-K dL-K\n.---- -------------------- ----------------------- ----- -------- ---- -----. \n| 00  rIsK                 -*- MYSTIC -*-          13:02 >·····S<    0    0 |\n: 01  OCH                  world, universe         12:59 >···D·S<    0    4 !\n  00  CORONER/JUSTICE        Kick me Randy !       12:53 >·····S<    0    0 :\n  00  BISHOP               911 IS A JOKE!!         12:31 >H·····<    0    0 :\n  01  AIRFORCE/JUSTICE     wElCoME 2 bIEL-bIENNE!  12:00 >·····S<    0    0 :\n  00  ICE TE/\             => CLASSIC 1993 <=      12:02 >···U··< 2345    0 :\n  00  Fury                 ^o^ ALPHA FLIGHT ^o^    11:47 >···D·S<    0  661 :\n: 00  STYLE                >-P÷R÷O÷D÷I÷G÷Y-<       10:36 >·····S<    0    0  \n¡ 00  CORONER/JUSTICE        Kick me Randy !       07:44 >·····S<    0    0 :\n| 00  DUNHILL              CH                      07:14 >···D·S<    0 1647 |\n`---------------------------------------------------------------------------''\n.---------------------------------------------------------------------------.\n| <C> lOSS cARRIER <P> oP pAGE   <U> uPLOAD    <D> dOWNLOAD  <N> nEW uSER   |\n| <H> pASS hACKED  <S> fILE sCAN <u> uL fAILED <d> dL fAILED <s> Ul sKIPPED |\n+---------------------------------------------------------------------------+\n| <102> cALLERS < 22> mBYTES uPLOAD <-:[ 26-NOV-93 ]:-> < 35> mBYTES dNLOAD |\n| <161> cALLERS < 32> mBYTES uPLOAD <-:[ yESTERDAY ]:-> < 55> mBYTES dNLOAD |\n`------------------------:[ lASTCALLER V3.0 wRITTEN bY iRONCODE/jST^pDY ]:--''\n\n\nII.   REQUIREMENTS\n------------------\n\n      LASTCALLER runs on every AMIGA (68000-68040).\n      The AmiExpress Callerslog is needed because all informations are\n      pulled from it to create the bulletin, so this option will need\n      to be turned on and active in your AmiExpress configuration file.\n\nIII.  USAGE\n-----------\n      First COPY the file STRIPP (founded in the c-directory of that pack)\n      to your own C: directroy. (this is a VERY fast Data-reader written\n      in assembler, to give the right and FAST POWER for that tool!!!)\n\n      Then you have to COPY all LIBRARIES founded in the libs of the pack.\n      \n      You have to run it after each logout from a user. \n      You have different configuration files (for every active node ONE!)\n\n      LASTCV30.EXE <witch config-file>\n      means:\n      LASTCV30.EXE 0 \n      this command takes the config-file ''S:LASTCV30.CONFIG0''\n      LASTCV30.EXE 1\n      this command takes the config-file ''S:LASTCV30.CONFIG1''\n      ...and so on....!\n\n      the config-files look like this:\n\n      LASTCV30.CONFIG0\n      ----------------\n\n========[! CUT HERE !]=======================================================\nBBS:NODE0/CALLERSLOG ; INPUT-FILE (CALLERSLOG OF THE NODE)\nBBS:BULL10.TXT       ; OUTPUT-FILE (BULLETIN TO SHOW)\nBBS:                 ; MAIN_PATH FROM YOUR AMIEXXPRESS\n========[! CUT HERE !]=======================================================\n      \n\n      LASTCV30.CONFIG1\n      ----------------\n\n========[! CUT HERE !]=======================================================\nBBS:NODE1/CALLERSLOG ; INPUT-FILE (CALLERSLOG OF THE NODE)\nBBS:BULL10.TXT       ; OUTPUT-FILE (BULLETIN TO SHOW)\nBBS:                 ; MAIN_PATH FROM YOUR AMIEXXPRESS \n========[! CUT HERE !]=======================================================\n\n      ...and so on....!\n\n\nIV.   HISTORY\n-------------\n\n      version 1.0  (intern)   - 03.DEC.1992\n      version 1.05 (alpha)    - 15.JAN.1993\n      version 1.15 (alpha)    - 28.FEB.1993\n      version 2.0  (beta)     - 17.JUL.1993\n      \n      VERSION 3.0  (release!) - 28.NOV.1993\n\n\n      FOR BUGS-REPORT.... CALL MY BBS ! NUP : FUCK\n\n      [ CASTLE ROCK BBS ] - [ JUSTICE WHQ  ] - [ +41-31-879-2167 ]\n                          & [ PRODIGY CHHQ ] - [ +41-31-879-2168 ] \n\n      [ AMIGA & SEGA & SNES ] - [ SYSOP    : iRoNCoDE/jUSTiCE    ]\n                                [ COSYSOPS : ICE TE/\ - CLASSIC! ]\n                                [               STYLE - PRODIGY  ]\n                                [            DIGITAL EXPRESSION  ]\n                                [              RANDY - JUSTICE   ]       \n\n\n                     --------------------------------\n                     | A JUSTICE PRODUCTION IN 1993 |\n                     --------------------------------\n  \n     \nV.    CALL OUR BOARDS:\n----------------------\n\n\n             /\_ __ /\_  /\   /\___ _/\__ __/\___/\ /\_ __/\___ _/\\n            /  \Y  \\  \/  Y\/  \  Y   \ Y    \___//  \Y  \ \  Y   \\n           /    :   /   \  :/     _·   / |   _/___/    :  /    ·   /\n          /  _/ ·  /    /  .\_    \___/  :__/ Y  /   \   /   \____/\n          \_/ \ . /    /    / \    \/    ·\/  : /     \_/  ___/_ __\n           /   \  \        /   \    \     /   . \       Y\   \/ Y /\n          /        \      /         /     \      \      ·/      ·/\n          \  ______/\  __/\______  /\_____/\______\___  /\____  /\n-==========\/========\/==========\/===================\/=->F&A\/===============-\n             .!cAlL aNd eXpLoRe nOw oUr fInEsT eLiTe bOaRdS!.\n\n                 CASTLE ROCK        [WHQ]  +41-31-879-2167\n                 WASTED TIME        [SFHQ] +358-0-505-3101\n                 SIN DECADE         [GHQ]  +49-6145-3-1844\n\n            .!oR cAlL tHe oFfIcIaL JUSTiCE dIsTrIbUtIoN sIde!.\n\n               FATAL ILLUSION         [GHQ]  +49-7665-95294\n               DOPE HOUSE/FAIRLIGHT   [SHQ]  +46-8-603-1041\n               SUSPERIA               [DEN]  +45-4-34-34-236\n\n-==============================================================================-\n[EOF]\n','\n',char(10)),NULL,NULL,93225,7,0,NULL,NULL,NULL,'scan',1780048351);
