INSERT INTO door_catalog VALUES('_u_mbm10','-U-MBM10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/-U-MBM10.LHA','MB-MAKER','XIM','MB-MAKER',NULL,NULL,NULL,'=====/ / /  \/ / / /_ \__ \  ____ \/ /=== ::::/ / / / / / / / / /  _/\  /   / /_::: :::/ / / / / / / / __/ / / / / / / / /:::',replace('      ______  ____/\______________  /\\n=====/ / /  \/ / / /_ \__ \  ____ \/ /===\n::::/ / / / / / / / / /  _/\  /   / /_:::\n:::/ / / / / / / / __/ / / / / / / / /:::\n:::\__/\/ /\/\__/\__/\/\/\  /\__/\__/::::\n========\/======[Present]=\/=============\n   MSGBASE MAKER V1.0 PUBLiC - /X UTiL\n=========================================\n.:::[ pASSED tRU'' tHE gATEZ oF X-ZiLe! ]:::.\n','\n',char(10)),'MB-MAKER.guide',replace('@database uNiVeRSaL DoCuMeNtS\n\n@node MAIN "Another Quality Product of -*- UNiVERSAL -*- !"\n\n               ________________________________________________\n              /  /  /     /  /  /  /__   /__  \\   ______   /  /\n             /  /  /  /  /  /  /  /  /  /    _/\\    /     /  /__\n            /  /  /  /  /  /  /  /  ___/  /  / /   /  /  /  /  /\n            \\____/__/__/__/_____/_____/__/__/_____/_____/_____/\n                                                     \n                      -//-    P R E S E N T S   -//- \n\n        ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n                MSG-BASE MAKER V1.0 PUBLIC BY MiCROBYTE !!!\n\n        ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n                        @{" -//-  Introduction  -//- " Link Introduction}\n                        @{" -//-      Usage     -//- " Link Installation}\n                        @{" -//-     History    -//- " Link History}\n                        @{" -//-    Greetings   -//- " Link Greetings}\n                        @{" -//-    Universal   -//- " Link Universal}\n@endnode\n@node Introduction "Introduction"\n\n                  ----------[ iNTRODUCTiON ]-----------\n\n  MSG-Base Maker is a /X Util.\n\nFeatures:\n\n  - Increase your Msgbase with a lot of messages!! (kind of a fake msgbase)\n\n  - Very usefull for sysops who had lost their msgbase and don''t want\n    to start back with message number 1 !\n\n  - No more configfile needed.\n\n  - To make 1000 messages, it will take +- 25 secs on my 2000/30...\n    dunno the speed on other processors... (seems a bit slow)\n\n\n\n\n                              @{"  MAiN MENU  " Link MAIN}\n@endnode\n@node Installation "Installation"\n\n                     ----------[ USAGE ]-----------   \n\n - USAGE: MB-MAKER {CONFERENCEPATH} {# OF MESSAGES}\n\n   {CONFERENCEPATH} = The Conference Path to the msgbase\n                      Ex. BBS:Conf2/\n\n   {# OF MESSAGES}  = The amount of messages you want to be created\n                      Ex. 1500\n\n\n\n   NOTE: Please make sure you have already entered 1 message!!\n         The Next release will have fixed this, but therefor I\n         have to recode the damn thing..\n\n\n\n\n                              @{"  MAiN MENU  " Link MAIN}\n@endnode\n@node History "History"\n\n                     ----------[ HiSTORY ]-----------\n\n  V 1.0ß       : First Release.\n\n  V 1.0 Public : - Added arguments instead of a configfile                   \n                 - Optimized a bit...\n                 - Will try to speed up the util...\n\n\n\n\n\n\n\n\n\n\n\n\n                               @{"  MAiN MENU  " Link MAIN}\n@endnode\n@node Greetings "Greetings"\n\n                ----------[ GREETS FLOW OUT 2 ]-----------\n\n\n               STERNONE . ULI . DAMiEN . FRANKY . TCB . ZACK\n\n                       And all the others I know......\n\n\n\n\n\n\n\n\n\n\n\n\n\n                               @{"  MAiN MENU  " Link MAIN}\n@endnode\n@node Universal "Universal 1996"\n\n                   ----------[ UNiVERSAL iS ]-----------\n\n  UNiVERSAL is the new name of S.U.C.K.\n\n  More info given in the nxt releases.\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                               @{"  MAiN MENU  " Link MAIN}\n@endnode\n@database uNiVeRSaL DoCuMeNtS\n\n@node MAIN "Another Quality Product of -*- UNiVERSAL -*- !"\n\n               ________________________________________________\n              /  /  /     /  /  /  /__   /__  \\   ______   /  /\n             /  /  /  /  /  /  /  /  /  /    _/\\    /     /  /__\n            /  /  /  /  /  /  /  /  ___/  /  / /   /  /  /  /  /\n            \\____/__/__/__/_____/_____/__/__/_____/_____/_____/\n                                                     \n                      -//-    P R E S E N T S   -//- \n\n        ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n                MSG-BASE MAKER V1.0 PUBLIC BY MiCROBYTE !!!\n\n        ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n                        @{" -//-  Introduction  -//- " Link Introduction}\n                        @{" -//-      Usage     -//- " Link Installation}\n                        @{" -//-     History    -//- " Link History}\n                        @{" -//-    Greetings   -//- " Link Greetings}\n                        @{" -//-    Universal   -//- " Link Universal}\n@endnode\n@node Introduction "Introduction"\n\n                  ----------[ iNTRODUCTiON ]-----------\n\n  MSG-Base Maker is a /X Util.\n\nFeatures:\n\n  - Increase your Msgbase with a lot of messages!! (kind of a fake msgbase)\n\n  - Very usefull for sysops who had lost their msgbase and don''t want\n    to start back with message number 1 !\n\n  - No more configfile needed.\n\n  - To make 1000 messages, it will take +- 25 secs on my 2000/30...\n    dunno the speed on other processors... (seems a bit slow)\n\n\n\n\n                              @{"  MAiN MENU  " Link MAIN}\n@endnode\n@node Installation "Installation"\n\n                     ----------[ USAGE ]-----------   \n\n - USAGE: MB-MAKER {CONFERENCEPATH} {# OF MESSAGES}\n\n   {CONFERENCEPATH} = The Conference Path to the msgbase\n                      Ex. BBS:Conf2/\n\n   {# OF MESSAGES}  = The amount of messages you want to be created\n                      Ex. 1500\n\n\n\n   NOTE: Please make sure you have already entered 1 message!!\n         The Next release will have fixed this, but therefor I\n         have to recode the damn thing..\n\n\n\n\n                              @{"  MAiN MENU  " Link MAIN}\n@endnode\n@node History "History"\n\n                     ----------[ HiSTORY ]-----------\n\n  V 1.0ß       : First Release.\n\n  V 1.0 Public : - Added arguments instead of a configfile                   \n                 - Optimized a bit...\n                 - Will try to speed up the util...\n\n\n\n\n\n\n\n\n\n\n\n\n                               @{"  MAiN MENU  " Link MAIN}\n@endnode\n@node Greetings "Greetings"\n\n                ----------[ GREETS FLOW OUT 2 ]-----------\n\n\n               STERNONE . ULI . DAMiEN . FRANKY . TCB . ZACK\n\n                       And all the others I know......\n\n\n\n\n\n\n\n\n\n\n\n\n\n                               @{"  MAiN MENU  " Link MAIN}\n@endnode\n@node Universal "Universal 1996"\n\n                   ----------[ UNiVERSAL iS ]-----------\n\n  UNiVERSAL is the new name of S.U.C.K.\n\n  More info given in the nxt releases.\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                               @{"  MAiN MENU  " Link MAIN}\n@endnode\n','\n',char(10)),NULL,'auto-added',19479,1,0,NULL,NULL,'u_mbm10','scan',1780048351);
INSERT INTO door_catalog VALUES('187_kb1','187-KB1.LZH','~/Code/amiexpress_doors/Archives/AmiExpress/187-KB1.LZH',NULL,'XIM','____________________________________________',NULL,NULL,'187','____  ____  ______ ____________     _______ \_ ¡ /\__/\ \__  / \_ ____/\ ! \¡Mg!\_ ___/ ¡ | \_/\_/   / /   /\__/   (_  \    / ¡__',replace('____________________________________________\n____  ____  ______ ____________     _______ \n\_ ¡ /\__/\ \__  / \_ ____/\ ! \¡Mg!\_ ___/ \n ¡ | \_/\_/   / /   /\__/   (_  \    / ¡__  \n | | / __ \  / /  _/ ¡    _/ ¡   \__/  !  \ \n !_! \/__\/ (_/   \__!    \__!____/\______/ \n         IS BRINGING YOU TODAY ....         \n--------------------------------------------\n   KickBoxing (The Art Of Fighting) V1.0\n The Ultimate Online Game For Ami-Express!\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 19:00:03  ON NODE: 1\n','\r',char(13)),'\n',char(10)),NULL,NULL,23596,29,0,NULL,NULL,NULL,'scan',1780048351);
INSERT INTO door_catalog VALUES('1i_log12','1I_LOG12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/1I_LOG12.LHA',NULL,'XIM','LOGOFF1.2',NULL,'STEVE/IBB','1I','When you type ''G'' the door will ask you if you want to logoff Y/N, you are also able to write a message to next user..',replace('     LOGOFF 1.0 BY STEVE/IBB & DR. G/IBB\nWhen you type ''G'' the door will ask you if\nyou want to logoff Y/N, you are also able\nto write a message to next user..\n','\n',char(10)),'LOGOFF1.2.DOC',replace('\n                 LOGOFF 1.0 BY STEVE/IBB & DR. G/IBB\n                 ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nHi folks! Just a quick doc for this little new door. We coded our personal\nlogoff door but it hadn''t to be spreaded ...then we decided that maybe\nsomeone could be interested in it..so enjoy!\nI think everybody is able to install a door but for those really lame guyz\nhere''s the string to insert in the BBS.CMD\n\n      DOOR SIZE IS: 10824 BYTES ! DON''T USE IT IF LONGER OR SHORTER !\n\n---------  CUT HERE !--------------         \n\n*G        XM001DOORS:LOGOFF1.2\n\n---------  CUT HERE !--------------\n\nPS: THIS IS AN AMIEXP. DOOR, NOT BUILT IN AREXX BUT PURE C LANGUAGE !\n\nWhen you type ''G'' the door will ask you if you want to logoff: \ntyping ''N'' you''ll return to the system\ntyping ''Y'' you''ll get a nice NO CARRIER 8)\ntyping ''R'' you''ll be able to write some bullshits for the next user.\nThe resulting file is stored in S: named ''LogOffUserMessy''.\n\nSee ya in the next doc 8) or catch ya in chat somewhere!\nFor any bug report or possible improvement feel free to contact us at:\n\n        THE HOUSE -> ITALIAN BAD BOYS EUROPEAN HQ <- +39-40-395286\n        ~~~~~~~~~\n        DIGITSTAR -> ITALIAN BAD BOYS ITALIAN  HQ <- +39-40-632561\n        ~~~~~~~~~\nor:\n\n  =========================================================================\n  =                                                                       =\n  =                   LEFT OF CENTER : 718-381-7504                       =\n  = HB9DHG''S  [PC] : +41-91-685110     2ND BLACK FOREST   : 904-729-3091  =\n  = TIDIRIUM       : +39-11-5620380        XEDOS [PC ONLY]: 39-6-5098177  =\n  =                                                                       =\n  =========================================================================\n\nfor mail swapping or donations write to:\n\n                             IBB (E$G)\n                             P.O. BOX 61\n                             I - 10099 San Mauro Torinese\n                             ITALY\n\nUpDaTeS:\n\nV 1.0 - First public release\nV 1.1 - Never released. Betatested On THE HOUSE\nV 1.2 - Corrected some nasty bugs. Text string is now 72 chrs instead of\n        the old 78 size. If you typed a full line message the border\n        output screwed up. ANSI gfx added. If no msg was found a blank\n        line was displayed. Now it notices that no msg has been left\n        asking to insert a txt using the ''R'' key. \n        Zoom directory cleaning. If any file is found in BBS:ZOOM/\n        path it will be deleted. This is an useful option xpecially if\n        you installed some doors that use the zoom dir as a storing place.\n        My users love to dl''d the whole dir crunched or from a specified\n        date and the resulting file is recorded in ZOOM dir, and I have\n        to delete by hand all the old junk files. Now life is easier!\n\nFINAL WORDS:\n-----------\nIf you love amiexp. utilities like us, and want to have them as betatester\ncall THE HOUSE and you''ll be given the lastest updates not spreaded yet!\nWe''re improving the best LHA/LZH adder checker, the great CHECK''N''ADD\ncurrent version is 2.0. If you wanna try the 2.1 as betatester call us.!\nAlways looking for cool people for coding ideas swapping. If ya need an uti.\nfor your personal use we''ll be glad to develope it, nowadays everything has \nbeen made for amiexp. so...subjects are lacking, anyway would be cool coding \na door for getting some money without working!..Any suggestion?!??  8-}\n---------------------------------------------------------------------------- \n  WE''RE LOOKING FOR MORE ACTIVE MEMBERS MEANLY CODERS, TRAINERMAKERS,\n  EURO SYSOPS RUNNING NO JUST OPENED BBS!  NO MUSICIANS PLEASE !\n  IF INTERESTED CONTACT US LEAVING MAIL TO E$G* ON OUR BOARDS WORLDWIDE!\n----------------------------------------------------------------------------\n\nSpecial greetings flies to:\n\nWintermute, Hydro, Freejack & Malachai, Eniac, Acid, Nitro,\nLoneWolf, Skol/ATX, PMF , CEEJAY, Fornax (Where the hell are you ?)\n, Metalfloscer ooopsssss METALBASHER & BLUELIGHT ! Sigma Seven/Abandon!\nHolgi/Heresy, SECO & NIKO, XAD/NIGHTFALL, The Ripper, Insector-X, \nAxe/Submission, Ken Ryu & Chun li, RED ALERT, HEAT & MEAN/2000 AD\nJoker and last but not least GIAPDJ OF TCB (STill waitin'' for yar uties!)\nand KOOL FALCO, VOYAGER & SNOWQUEEN, MICRO, SKYLARK, IOROS, QUASAR.\nSpecial greetings to TRADE/SCX and NECRONOM/SCX (it''s the first time\ni call an EURO bbs so many times ehhe.. was nice to meet you!)\nSorry if I forgot someone but i''m in a hurry!\n\n                                           DR. G of ITALIAN BAD BOYS !\n      \n                    ITALIAN BAD BOYS EUROPEAN HQ!                        \n                  ____________   _________________/\                     \nSYSOP: DR. G/IBB  \  ______   \ /   /   |\  ____    \    P R I V A T E   \n                   \/     /   //   /|   | \/___/    /                    \n   CO: ALX STY/IBB       /   //   /_|   | /   |____/        SYSTEM!      \n     : SECO & NICO/MNS  /   //    __    |/   __//   \                    \n     : TRADE/SCOOPEX   /   / \   \  |   |\   \_/     \                   \n     : IOROS           \  /   \___\ |__ | \__________/                   \n                        \/             \|                                \n            /\  OVER 210 MEGZ ON LINE        19.2 USRobotics HST            \n           /  \___     ______     ____ ___    ________ _________/\       \n          /   /   |   /      |   /   /|   |  /        \\  ____    \      \n         /   /|   |  /   /|  |  /   / |   |  \        / \/___/    /      \n        /   /_|   | /   / |  | /   /  |   |  _\   \ _/  /   |____/       \n       /    __    |/   /  |  |/   /   |   | /  \   \   /   __//   \      \n       \   \  |   |\   \__|  |\   \___|   |/    \   \  \   \_/     \     \n [Raffa]\___\ |__ | \________| \__________|\________/   \__________/     \n                 \|                                                      \n                         .-------------------------.                      \n  AMIGA 0 day ONLY !  => |+3 9 - 4 0 - 3 9 5 2 8 6 | <=  AMIGA 0 day ONLY !\n                         `-------------------------''                      \n\n                SOON RUNNING ON 2 NODES!! (AT LEAST I HOPE SO)\n                  ANYWAY WITHIN JUNE RUNNING ON A 16.8 DUAL\n\n[EOF]\n','\n',char(10)),NULL,'auto-added',12423,6,0,NULL,NULL,'1i_log12','scan',1780048351);
INSERT INTO door_catalog VALUES('1oo_wall','1OO-WALL.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/1OO-WALL.LHA',NULL,'XIM','1oo wall',NULL,NULL,'1OO',NULL,NULL,NULL,NULL,NULL,NULL,8530,0,0,NULL,NULL,NULL,'scan',1780048351);
INSERT INTO door_catalog VALUES('23_ffc09','23-FFC09.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/23-FFC09.LHA','DMS','XIM','DMS',NULL,'Thoth','23','XIM door written in SAS/C 6.55 by Thoth',replace('SigmaExpress & AmiExpress >FILECHECK< \nXIM door written in SAS/C 6.55 by Thoth\n','\n',char(10)),'fcheck.doc',replace('\n-----------------------------------------------------------------------------\n\n                          Documentation file for:\n                          -----------------------\n\n        _____         _   _____ _ _       ____ _               _\n       |  ___|_ _ ___| |_|  ___(_) | ___ / ___| |__   ___  ___| | __\n       | |_ / _` / __| __| |_  | | |/ _ \ |   | ''_ \ / _ \/ __| |/ /\n       |  _| (_| \__ \ |_|  _| | | |  __/ |___| | | |  __/ (__|   <\n       |_|  \__,_|___/\__|_|   |_|_|\___|\____|_| |_|\___|\___|_|\_\\n\n                         - current revision: 0.9 -\n\n-----------------------------------------------------------------------------\n\n\n                SigmaExpress & AmiExpress >FILECHECK< Door\n\n              a XIM door written in SAS/C 6.55 by Thoth/SNAFU\n\n\n-----------------------------------------------------------------------------\n\n\nIntroduction: [or: what is this for ?]\n-------------\n\nfastfilecheck is to be started as FILECHECK door via syscmd.\nfastfilecheck is going to identify the filetype of the\n              file in order to activate the correct checkroutine.\nfastfilecheck is going to check the file and sends the result straight\n              away to Express.\n\n\nInstallation: [or: am i dumb or what ?]\n-------------\n\njust add the following line to your bbs:commands/sys.cmd file [s!x]\nor generate an icon in bbs:commands/syscmd for FILECHECK [ICON_/X]\n\n----[file: bbs:commands/bbs.cmd]----[start]----\nFILECHECK XM001doors:fcheck.x\n----[file: bbs:commands/bbs.cmd]----[>end<]----\n\ncopy bbs/doors/fcheck.x to your doors: directory.\n\ncopy all the included extractors [inside bbs/c/] to your c: directory.\n(you may also use your own versions).\n\nin this archive included are:\n-----------------------------\n\n> LZX 1.00 EC (Evaluation) 68000/68010 Version    [for LZX support]\n> LhA Registered V1.62                            [for LHA support]\n> ExeChecker v1.1 by RiCK/CRaZe 1994              [for EXE support]\n> DMS Command Line Version 2.04r                  [for DMS support]\n\ninstallation completed (easy, eh?)...\n\nerm, for all of you reading your documentation it`s useless for me to\nsay that if Express detects a syscmd door called FILECHECK the bbs:fcheck\ndir becomes redundant. again ? okay! if you use my door, you can delete\nall the files inside BBS:FCHECK/.\n\n\nlast words: [or: are we finished already ???]\n-----------\n\ni`m really happy that i found the exechecker by RiCK/CRaZe, for this\nguy was really codin` dos_based, which means he sends different\ninvisible return codes back to dos after testing whereby the\nfastfilecheck is able to recieve these normed invisible dos_return\nvalues, and is therefor able to understand whether the test\nwas successful or not.\n\nso if you replace the exechecker with one of your own private stench\nbe sure [via testing an upload with one or two crippled -use your\ncygnused for that- files to your system] this new checker is\nalso sending these returm codes (for i tried SEVERAL lzx/lha/dms/exe\ncheckers for dos and/or express... and NONE (!) of them sends these\ncodes, so here we are using the original extractors to be sure\nthe system is used in the best possible manner.\n\nplease note that none of the traditional express checkers (mapus/...)\nuses these codes and the filechecker tool would be spending more time\nin analysing streamfiles (to find out the test result) than in testing\nthe file.\n\nbe realistic - check fast!\n\n\ncontacts: [or: if you want to get in touch with me and my charme]\n---------\n\ncontact me on the snafu whq:\n\n          cosmic trigger (2* analog, 2* isdn)\n\n          07042 950 9000 (ringdown all nodes + sysop voice!)\n\n\nmessage: (no bottle)\n--------\n\nwe really want to get in touch with any open minded and thoughtful\nspirit who reads these words! and for the fuck, i mean what i say!\n\nthoth/snafu (a schizophrenic mind)\n','\n',char(10)),NULL,'auto-added',150338,6,0,NULL,NULL,'slk_v1_0','scan',1780048351);
