INSERT INTO door_catalog VALUES('4am_font','4AM-FONT.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/4AM-FONT.LHA','8','XIM','8',NULL,NULL,'4AM','Cool!!! All Sysops Install It as EXpress font, and spread this to all users... All Asciis will look improved...',replace('Font for AmiXpress\nCool!!! All Sysops Install It as EXpress\nfont, and spread this to all users... All\nAsciis will look improved...\nGeneric 8 pt,\nSupports RIP, IBM & ISO\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 18:59:59  ON NODE: 1\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',4515,4,0,NULL,NULL,'4am_font','scan',1780048351);
INSERT INTO door_catalog VALUES('5150_b10','5150-B10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5150-B10.LHA','Bull','XIM','Bull',NULL,'nIKE/cRAZE^5150','5150','/ ///  ____   _¬\_/  _________ ¬\_ s%/\__ ¬\___/   /\__ ¬\_/  ¬/   / /  ¬/   /g/   /  ¬/   /   /   /',replace(' _ _ __ _/\________   _/\__________\n   / ///  ____   _¬\_/  _________ ¬\_\n    s%/\__ ¬\___/   /\__ ¬\_/  ¬/   /\n     /  ¬/   /g/   /  ¬/   /   /   /\n__ _/  _/   /N/  _/   /   /  _/   /__\n.\\\_______/l/___________/_______///.\n¢---- -  -    pRESENTS:    -  - ----''\n¡^bULLvIEW^ v1.0a bY nIKE/cRAZE^5150\n!tHE bEST bULLETIN vIEWER dONE nOW!!\n`------------ -  -     -\n','\n',char(10)),'Bull.Doc',replace('               _________________________·:·__________·::E^d\n               \___ \________/\_____   ¬\_/________/ \·::::\n               ·\/   _/______\ \__/    _/\    _______/\·:::\n               /¯   /__     ¬\\/__      \ \  /__     ¯¬\·::\n               \______/       \_/        \/____/-CRAZE- \·:\n               .\  \__________/\\________/\ \___________/\·\n               :.\__\         \ \\       \ \_\          \ \\n               ::HrP.\_________\/.\_______\/..\__________\/\n\n                      P·R·O·U·D·L·Y·? P·R·E·S·E·N·T·S\n\n                     BullView v1.0a by nIKE/cRAZE^5150\n\nDescription.\n~~~~~~~~~~~~\nBulletin Viewer. Let''s the sysop have all bulletins in one directory instead\nof the same files in XX directorys (hehe)..\nQuite fast (95% E, 5% Asm :)), Goodlooking (as me), easy to install.\nBtw, this door may not be used by RHYS/DELIRIUM. I think he should know why!\n\nInstalling this damn door:\n~~~~~~~~~~~~~~~~~~~~~~~~~~\nCopy "Bull" To any directory on your HD.\nCopy the icon (B.Info) to BBS:Commands/BBSCmd/ and edit it to set your needs.\nStack needs at least 3000 bytes, 4000 recommended\nType = XIM.\n\nMake a directory called BBS:Bulletins and copy "Bullhelp", and the other files\nincluded to it. Edit the files to set your needs (easy to understand?!)\nFilenames should be Bull<Nr>.Txt<.Gr> where <Nr> is the number of the bulletin.\n\nOn each line in Bullhelp to be the bulletin number you want.\nThat means, Line 1=Bulletin 1, line 7=bulletin 7 etc..\nLook at the Bullhelp file included for more info!\n\nTo be able to let the user update the bulletins, u''ll have to make an ordinary\ndos script that does it. Copy the file to S: and call it "Up"....BullView will\nExecute this if the user wants to update the bulletins!\n\nInfo ''bout 5150!\n~~~~~~~~~~~~~~~~\nTo join 5150, the ultimate Door group, then call one of our boards (Pet Sematary\n(WHQ) or Instant Pleasure (EHQ)!) and upload some of your doors!\nOnly the cream of the doorcreators will be accepted as members!\n\nInfo ''bout CraZe\n~~~~~~~~~~~~~~~~\nWe need more Gfxers! Coders are also welcome. More traders too!\nYou should know were to get in touch with us!\n','\n',char(10)),'{"TYPE":"XIM."}','auto-added',6602,5,0,NULL,NULL,'5150_b10','scan',1780048351);
INSERT INTO door_catalog VALUES('5d_dm002','5D!DM002.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5D!DM002.LHA','8','XIM','(3)TBS(3)',NULL,'sTc','5D','__|  |__.__.__  __ _|\______\__  _/.__.__. / __  |  |  |  \/ // _____  ___/ |  |  |  | /  \   |  |  | \ \ \_ |_ \/\__ \_ |  |  |  |',replace(replace('5TH :--:              _       _:--:__\r\n  __|  |__.__.__  __ _|\______\__  _/.__.__.\r\n / __  |  |  |  \/ // _____  ___/ |  |  |  |\r\n/  \   |  |  | \ \ \_ |_ \/\__ \_ |  |  |  |\r\n\______|___  |__\   / _/__\  ___/__  |___  |\r\n-DYNASTY-/___|---\_/__| /____\----\__|w/___|\r\n.---- -------------- -------- -- ------ ---.\r\n|::::. 5D-DoorMenu v0.02 ©1996 by sTc .::::|\r\n`- ---- --------- ---- ------- --------- --''\r\n--/\-- pASSED tHRU ENTROPY BBS --/\--\r\n    \r\n','\r',char(13)),'\n',char(10)),'5D-DoorMenu.guide',replace('@database 5D-DoorMenu Documentation\n\nCopyright ©1995 sTc\n\n@remark $VER: (January 13 1996, 20:00)\n@remark AmigaGuide database for the 5D-DoorMenu Documentation\n\n@node MAIN "5D-DoorMenu Documentation"\n       ._____.\n  __5TH|_    |    ._____. ___________ ________. _______ ___.           ._____.\n__\\   __     |____|_    |_\\   _    ___\\____   |_\\  ___/__  |___    ____|_    |\n\\     \\|    _/     /    |     /    \\     _    |\\_____   /  ___/___/     /    |\n \\     \\    \\     /_    |____/    / \\    \\    |    /   /   \\     \\     /_    |\n  \\__________\\_____     |   /____/   \\________|_______/|__________\\_____     |\n                  |_____|pHS!                                          |_____|\n\n                                                     ... No Fear of Fun!\n\n    5D-DoorMenu.Guide - Contents\n    ============================\n\n    1) @{" Introduction " Link ChildDoc1}\n    2) @{" Requirements " Link ChildDoc2}\n    3) @{" Installation " Link ChildDoc3}\n    4) @{" Tooltypes " Link ChildDoc7}\n    4) @{" History " Link ChildDoc4}\n    5) @{" Greetings " Link ChildDoc5}\n    6) @{" How to contact 5D " Link ChildDoc6}\n\n@endnode\n@node ChildDoc1 "Introduction"\n\n  5D-DoorMenu - Introduction\n  =============================\n\n  5D-DoorMenu is an enhancement for /X\n  that allows starting several doors\n  by a special menu (or maybe more than\n  one).\n\n@endnode\n@node ChildDoc2 "Requirements"\n\n  5D-DoorMenu - Requirements\n  =============================\n\n  o  an Amiga (or compatible - DRACO)\n  o  an AmiExpress-compatible BBS-program\n\n@endnode\n@node ChildDoc3 "Installation"\n\n  5D-DoorMenu - Installation (for AmiExpress)\n  ===========================================\n\n  Simply copy the directories in this archive into your bbs-\n  directory.\n\n@endnode\n@node ChildDoc4 "History"\n\n  5D-DoorMenu - History\n  ========================\n\n  v0.01 - First development version\n  v0.02 - [RELEASE I]\n\n@endnode\n@node ChildDoc5 "Greetings"\n\n  Greetings\n  =========\n\n  Airworx - Celator - Conan&Newton - Crayor\n  Deathknight - Dres! - Enzo - Gilthanas\n  Leland Gaunt - Mad Doc - Mad Force - Mad Man\n  Maverick - MouseBuster - Muad''Dib - Nero\n  Playmate - R/\\! - Radavi - Rainmain\n  Rebel MC - Rush - Snow - Soultaker - Steel\n  Thunder - Webster - Whirlwind - Whiz!\n  ___\n  \\_/ Special thanks go to R/\! & Whirlwind & Webster & Radavi!\n   o\n\n@endnode\n@node ChildDoc6 "How to contact 5D"\n\n  You can write a message to ''SvEN tHE CREAToR'' at the following boards:\n\n  o  Eak a Mouse\n  o  Electronic Confusion\n  o  Funky Trading\n  o  Needful Things\n  o  One Eight Seven\n  o  Terminal FuckUp\n  o  The Undiscovered\n  o  Violator\n  o  Warez Unlimited\n  o  World of Elite\n\n  ... and several more\n\n@endnode\n@node ChildDoc7 "Tooltypes"\n\n  5D-DoorMenu - Tooltypes\n  =======================\n\n  ''5D-DoorMenu.info'' may contain the following tooltypes:\n\n  TXT_FILE=<full path>         - Text to be shown as help screen\n                               ! Example: TXT_FILE=BBS:Screens/Node/DoorMenu.TXT\n\n  NUM_MENUS=<number of menus>  - Number of menus that you want to be showable\n                                 (if you use more that ONE menu then TXT_FILE\n                                 will be added by ''.<current menu>'' e.g.\n                                 ''...DoorsMenu.TXT.2'')\n                               ! Example: NUM_MENUS=2\n\n  DC_<cmd name>=</X-cmd name>  - Adds command <cmd name> to the available commands\n                                 and uses </X-cmd name> as normal /X-command\n                               ! Example: DC_FAKER=SHELL will start ''FAKER'' if\n                                 ''SHELL'' is entered\n                               ! Example: DC_PAGE=O will start ''O'' if ''PAGE''\n                                 is entered\n\n@endnode\n','\n',char(10)),NULL,'auto-added',91291,4,0,NULL,NULL,'5d_dm002','scan',1780048351);
