INSERT INTO door_catalog VALUES('5d_cc001','5D-CC001.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5D-CC001.LHA','5D-ComCommand_Prefs','XIM','5D-ComCommand',NULL,'sTc','5D','/___ \  \  \/     \/ ___ \    \      / \  \ / /  \_    \     /  __  / \___\_ __/\_    \ / /   / \   / /  /   /  /\__  \/  /    \   /',replace('5TH________  _____  ______________________\n/___ \  \  \/     \/ ___ \    \      / \  \\n / /  \_    \     /  __  / \___\_ __/\_    \\n/ /   / \   / /  /   /  /\__  \/  /    \   /\n\____/_____/_/__/\__/__/______/__/________/\n - --- -----[ P·R·E·S·E·N·T·S ]----[MaD]- -\n         5D-ComCommand v0.01 by sTc\n  Allows you to start all main commands of\n AmiExpress by pressing any key combination\n - --- ----- - ---- -------- ---- - ----- -\n','\n',char(10)),'5D-ComCommand.Guide',replace('@DataBase 5D-ComCommand Documentation\n@Author sTc/5D\n@Index Documentation\n\nCopyright © 1994 SvEN tHE CREAToR of 5tH DyNASTY\n\n@Remark $VER: 5D-ComCommand v0.01 by sTc/5D\n@Remark AmigaGuide DataBase\n\n@node MAIN "5D-ComCommand Documentation © 1994 SvEN tHE CREAToR of 5tH DyNASTY"\n                                                              :\n                                                       :      ¦\n                   ________________  __________________¦      |\n            _______\_______       /  \             /   |      |______\n           |  __   _/     /______/____\  _     _  /    ¦      |  __  |\n           |  \/  _\________    \_\  / \/       \/     _      |  \/  |\n           |______\        /     / \/   |       |      /      |______|\n                   \___________ /       |_______|_____/       |Rpd!\n                              \/                     /________|\n                         :           :                                     :\n            ____   :     ¦     :     ¦      · 5 · T · H ·            :     ¦\n  __________\  /___¦    _|__/\ ¦     |_______ _______________________¦     |\n  \______   \\//   |    \____ \|     |   _   \\_____      /       /  |     |\n   /     \   \/    ¦     |   \ \     |   /    \/   /_____/    _  /   ¦     |\n _/       \   \_____     |    \ \_   |   _     \_____   \_     \/_____     |\n \       _/    /   /     |     \     |   /      /   /    /     |     /     |\n  \__________ /__________|     |\ ___|__/_____ /_______ /______|___________|\n            \/           |     ¦ \/          \/       \/\n                         ¦     :     · D · Y · N · A · S · T · Y ·\n                         :\n\n                              (×· PrESENTS ·×)\n\n                ----- --- -> 5D-ComCommand v0.01 <- --- -----\n\n                  Coded by SvEN tHE CREAToR of 5th Dynasty\n\n                           @{" Normal Documentation " Link Documentation}\n@endnode\n@node Documentation "5D-ComCommand Documentation"\n              _______________________________________________\n             |                                               |\n             | //                                            |\n             | /                                             |\n             |                                               |\n             |            @{" D e S C R I P T I O N " Link Description}           |\n             |                                               |\n             |           @{" I n S T A L L A T I O N " Link Installation}          |\n             |                                               |\n             |              @{" G r E E T I N G S " Link Greetings}             |\n             |                                               |\n             |                                             / |\n             |                                            // |\n             |_______________________________________________|\n\n@endnode\n@node Description "5D-ComCommand Description"\n5D-ComCommand has been coded by SvEN tHE CREAToR/5D!\n\nIt''s a program which allows you to start an AmiExpress Command\nlike ''SysOp LogIn'' at any node. You can use as many key commands\nas you want. The prefs program is fully coded in OS/2+ Style.\nAs I know it''s the first program which allows such things.\n\n - --- ---[ 5D-ComCommand Prefs Description ]-- - -- ----- --- -\n\nKey Activators:    The list of activators which you have\n                   created.\nNew Activator:     Allows you to add a new key activator\n                   to the existing ones.\nDelete:            Deletes the currently set\n                   activator.\nCommands:          There you can specify which command of AmiEx\n                   shall be started when you press the key\n                   activator.\nNode:              The node where the command will be started.\n@endnode\n@node Installation "5D-ComCommand Installation"\n\nCopy the following things to the specified directory.\n\nContents of archive:\n===================\n\nPrefs/     5D-ComCommand_Prefs      <-= Allows you to edit the prefs\n           5D-ComCommand_Prefs.info\nBBS:Utils/ 5D-ComCommand            <-= The main program\n           5D-ComCommand.info\n\n===================\n\nInsert the following things to your S:User-StartUp:\n==================================================\n\nRun >NIL: BBS:Utils/5D-ComCommand\nAlias 5D-ComCommand BBS:Utils/5D-ComCommand\n\n==================================================\n\n@endnode\n@node Greetings "5D-ComCommand Greetings"\nGreetings go to:\n\n         . Celator ........... Thank you for helping me with /X! .\n         : ByteAndi ............ For helping me to learn coding! :\n         | Snow ...................... Sing mehr lieder, leader! |\n         `------( And all other persons I''ve forgotten!!! )------''\n\n@endnode\n','\n',char(10)),NULL,'auto-added',8710,1,0,NULL,NULL,'5d_cc001','scan',1780048351);
INSERT INTO door_catalog VALUES('5d_ck001','5D-CK001.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5D-CK001.LHA','5D-CheckAndKick','XIM','5th______  ___  __  ___   _____  _. ___  ___',NULL,'sTc/5D','5D','\__   \  \/  /_|  |/___\ / ___/_/ |_\  \/  / |  |  \_/ _/__\  |  /  |___  \_   _/\_/ _/ |  |  ||  ||  \\_| /   |     ||   |  |  |',replace('5th______  ___  __  ___   _____  _. ___  ___\n\__   \  \/  /_|  |/___\ / ___/_/ |_\  \/  /\n |  |  \_/ _/__\  |  /  |___  \_   _/\_/ _/\n |  |  ||  ||  \\_| /   |     ||   |  |  |\n |  |  ||  ||  |\_| \_  |SNOW!||   |  |  |\n |_____||__||__|__|__|__|_____||___|  |__|\n-==[ 5D ]==========================[ 5D ]==-\n      5D-CheckAndKick v0.01 by sTc/5D\n           For AmiExpress v3.xx+!\n-==[ 5D ]==========================[ 5D ]==-\n','\n',char(10)),'5D-CheckAndKick.Guide',replace('@DataBase 5D-CheckAndKickDoc\n\nCopyright (c) 1993 SvEN tHE CREAToR of 5th Dynasty\n\n@Remark $VER: 5D-CheckAndKick v0.01\n@Remark AmigaGuide database for the 5D-CheckAndKick Documentation\n\n@node MAIN "5D-CheckAndKick Documentation (c)1994 SvEN tHE CREAToR of 5th Dynasty"\n\n    _5tH_______    ____   ___  _____  _______ _________    ___\n    \______ \  \__/  / \ |   |/     \|       |      \  \__/  /\n     |     \ \_ \/ _/ \ \|   |   _   |  _____|___ ___\_ \/ _/\n     |     / ||\  /|   \ \   |  /    |      \  |   |  |\  /|\n     |    /  || \/ |   |\ \  |  \_   |\____  | |   |  | \/ |\n     |   /   ||sNoW|   | \ \ |   |   |       | |   |  |    |\n     :       ::    :   : :\  :   :   :       : :   :  :    :\n     `-------''`----`---'' `---`---`---`-------'' `---''  `----''\n\n                    >>> 5D-CheckAndKick <<<\n\n                   Code: SvEN tHE CREAToR/5D\n\n----------------------------------------------------------------------------\n\n         >>> C·O·N·T·E·N·T·S  O·F  D·O·C·U·M·E·N·T·A·T·I·O·N <<<\n\n                         @{"      Introduction      " Link Cap01}\n                         @{"      Requirements      " Link Cap02}\n                         @{"      Installation      " Link Cap03}\n                         @{"       Greetings!       " Link Cap05}\n                         @{"   How to Contact me?   " Link Cap06}\n\n         ---------------------------------------------------------\n                   Complete Docs for 5D-CheckAndKick v0.01\n         ---------------------------------------------------------\n         The Documentation has been written by SvEN tHE CREAToR/5D\n\n@endnode\n@node Cap01 "Introduction"\n  =======================================================================\n  5D-CheckAndKick is a AmiExpress v0.01 Dooooaaaar. Is there any\n  sense in it?? Oehhhm... Dunno... Ok, there is a sense... Example:\n  If a user logs into node 1 and node 0 is free he will be kicked\n  or something like... hehe... You can change that in the\n  icon of Doors:5D-CheckAndKick/5D-CheckAndKick!\n  =======================================================================\n@endnode\n@node Cap02 "Requirements"\n  =======================================================================\n  To install 5D-CheckAndKick you must have the following things:\n\n  - an  Amiga Model (500/600/1000/1200/2000/2500/3000/4000/CDTV/CD³²)\n  - the installed Version of OS\2, OS\3 or higher\n    (Soft- or Hardware Version)\n  - AmiExpress V2.xx , v3.xx or higher. And surely S-Express hehe.\n\n  =======================================================================\n@endnode\n@node Cap03 "How to install 5D-CheckAndKick:"\n  =======================================================================\n  To install 5D-CheckAndKick you must have all Requirement which were\n  mentioned below. You need the following things.\n\n  ---------------------------------------------------\n    BBS: Commands/ SYSCmd/          FrontEnd.info\n    BBS: Doors/    5D-CheckAndKick/ 5D-CheckAndKick\n                                    5D-CheckAndKick.Guide\n  ---------------------------------------------------\n\n  Decruch the 5D-CheckAndKick Archive. Go to your ''Doors:'' Directory\n  and make a directory called ''5D-CheckAndKick''. Copy ''5D-CheckAndKick''\n  into the Directory. Go to your ''BBS:Commands/SysCmd/'' Directory.\n  Copy ''FRONTEND.info'' into it.\n  =======================================================================\n@endnode\n@node Cap05 "Greetings go to the following guys:"\n  =======================================================================\n\n          Thunder .. Hau den Telekotzern auf die Backen!\n          Rainman .................... Gogo, NRW Leader!\n          Starcam .......... Sorry, we''ve some problems!\n          Mad Førce .............. Man, leg endlich auf!\n          Snow ............... Jaja, kriegst Deine 5 DM!\n          Airworx .. 20 Chicken McNuggets, 3*Senf-Sauce!\n          Prophet ...... Ich ziehe um, wohne 5 mins weg!\n          Circuit Breaker ................ Doedeldiduuu!\n          Zector ................. AmigaE, yeaaah! Hehe!\n          Muad''Dib ............... Hope to see you soon!\n          Scan .............. We dream about your scape!\n          Steel .................. Wie''s gööööht''s Gott?\n          Earthquake ...... Kriege hunger auf Erdbeeren!\n          Haystack ........... Wie geht es Deiner Backe?\n\n  =======================================================================\n@endnode\n@node Cap06 "How to contact me:"\n  =======================================================================\n  _____  ___   __________  _____________  _____________ ___ ______  _____\n /     \|   \ |  |       |/     \____.  \|     |       |   |      |/     \\n|   |   |  \ \|  |___ ___|   |   |   |   |     |___ ___|___|      |   |   |\n|   |   |   \ \   ||   | |   |   |   | __|  \   ||   | |   |  \   |   |   |\n|       |   |\ \  ||   | |       |      \|   \__||   | |   |   \__|       |\n|   |   |   | \ \ ||   | |   |   |   |   |   /  ||   | |   |   /  |   |   |\n|   |   |   | |\  ||   | |   |   |   |   |  /   ||   | |   |  /   |   |   |\n|___|   |___| | \ ||___| |___|   |___|   |      ||___| |___|      |___|   |\n    |   |     |   |          |   |   |   |______|          |______|   |   |\n    |___|     |___|          |___|   |___|                            |___|\n \n                      5TH DYNASTY GHQ                     .__________.\n S                                                        |   WITH   |\n Y          COOOOOOL THE COOOOLEST THING FOR DA SUMMER    |   CODER  |\n S                                                        |CONFERENCE|\n O      THE FIRST 5 UPLOADERS GET A DISABLE FOR ONE MONTH ·¯¯¯¯¯¯¯¯¯¯·\n P\n :              36 HOURS ONLINE PER 1 1/2 DAYS !\n S\n N          GET 5TH DYNASTY RELEASES FOR FREEDOWNLOAD\n O\n W         +49-306-XXXXXX : NUP=XXXXXXX : SYSTEMPW=XXX\n  =======================================================================\n@endnode\n','\n',char(10)),NULL,NULL,10296,2,0,NULL,NULL,'5d_ck001_5d_checkandkick','scan',1780048351);
