     \   \/    ¦     |   \ \     |   /    \/   /_____/    _  /   ¦     |\n _/       \   \_____     |    \ \_   |   _     \_____   \_     \/_____     |\n \       _/    /   /     |     \     |   /      /   /    /     |     /     |\n  \__________ /__________|     |\ ___|__/_____ /_______ /______|___________|\n            \/           |     ¦ \/          \/       \/\n                         ¦     :     · D · Y · N · A · S · T · Y ·\n                         :\n\n                              (×· PrESENTS ·×)\n\n                ----- --- -> 5D^DupeCheck v0.10 <- --- -----\n\n                  Coded by SvEN tHE CREAToR of 5th Dynasty\n\n                           @{" Normal Documentation " Link Documentation}\n@endnode\n@node Documentation "5D^DupeCheck Documentation"\n              _______________________________________________\n             |                                               |\n             | //                                            |\n             | /                                             |\n             |                                               |\n             |            @{" D e S C R I P T I O N " Link Description}           |\n             |                                               |\n             |           @{" I n S T A L L A T I O N " Link Installation}          |\n             |                                               |\n             |              @{" G r E E T I N G S " Link Greetings}             |\n             |                                               |\n             |                                             / |\n             |                                            // |\n             |_______________________________________________|\n\n@endnode\n@node Description "5D^DupeCheck Description"\n5D^DupeCheck has been coded by SvEN tHE CREAToR/5D!\n\nIt is a normal DupeCheck Door as like as the others out there\nbut it isn''t the slowest I hope... smile... It has been fully\ncoded in Assembler. So it''s your turn to decide which one you\nwanna use.\n\n\nImprovements:\n\n - It is now fully multientrant and able to be made resident\n - It has been more optimized\n - It has been fully new designed\n\n@endnode\n@node Installation "5D^DupeCheck Installation"\nCopy all files which are in the ''BBS'' directory of the archive\ninto your bbs directory.\n\nContents of archive:\n===================\n\nBBS/ Commands/ SysCmd/       FILECHECK.info\n     Doors/    5D^DupeCheck/ 5D^DupeCheck\n                             5D^DupeCheck.info\n                             5D^DupeCheck.Guide\n\n===================\n\nNote: If you''ve installed some other doors in your FileCheck and wanna\n      continue using''em then simply use 5D-MultiStart!\n      If you want to make it resident then simply type this into your\n      User-StartUp and copy the FILECHECK_RESIDENT.info to\n      BBS:Commands/SysCmd/FILECHECK.info!\n\nResident >NIL: 5D^DupeCheck Doors:5D^DupeCheck/5D^DupeCheck FORCE\n\n@endnode\n@node Greetings "5D^DupeCheck Greetings"\nGreetings go to:\n\n         . Celator ........... Thank you for helping me with /X! .\n         : ByteAndi ............ For helping me to learn coding! :\n         | Snow ...................... Sing mehr lieder, leader! |\n         `------( And all other persons I''ve forgotten!!! )------''\n\n@endnode\n','\n',char(10)),NULL,'auto-added',9416,4,0,NULL,NULL,'5d_dc010','scan',1780048365);
INSERT INTO door_catalog VALUES('5d_dg1','5D-DG1.LZH','~/Code/amiexpress_doors/Archives/AmiExpress/5D-DG1.LZH','RexxMast','XIM','RPStart',NULL,NULL,'5D','5(___  / ¬|  ___.  ____  /  ____  ____ ¬|  ) T/  /  \__   \ ¬|  \  _  \___ ¬\  ¬\ \__   \ H\___  /___  /  |__/  |__/_____/___/_____  /',replace('  ________._____________________________.__ \n5(___  / ¬|  ___.  ____  /  ____  ____ ¬|  )\nT/  /  \__   \ ¬|  \  _  \___ ¬\  ¬\ \__   \\nH\___  /___  /  |__/  |__/_____/___/_____  /\n|   ¬\/tGø¬\/___| \___|                 ¬\/|\n|                                          |\n|    SX2.x   dESIGNER gOODBYE 1.0  /X3.x   |\n|            ~~~~~~~~~~~~~~~~~~~~          |\n|create your OWN lOGOFF dOOR for your OWN  |\n|pleasure,FULL outfit creation,LOTS of lame|\n|functions...AIM DOOR TYPE ... /X / SigmaX |\n`------------------------------------------''\n======[5D]=sOME sTRANGE aDDICTION=[SSF]=====\n--=[5D]=-Can-you-handle-LAMENESS-?-=[SSF]=--\n','\n',char(10)),'5d-dzign.guide',replace('@database "=GUILD OF THIEVES= - AN ELITE DREAM COMES TRUE!"\n@Node MAIN "=GuILD oF THIEvES="\n                     /\\n                    //\\\n                   //  \\\n__________________//    \\_________________________________________________\n\ _______ ________/      \________ ______________________________________ /\n \\      \\                      //                                     //\n  \\      \\                    //      dESIGNER gOODBYE V1.000!       //\n   \\      \\      JORDAN      //                                     //\n    \\      \\       OF       //    Released on 31.07.94 , Sunday    //\n    //      //  5TH DyNASTY   \\                                     \\\n   //      //                  \\       NOW GO FOR THE DOCUMENTATION  \\\n  //      //                    \\                                     \\\n //______//_______        _______\\_____________________________________\\\n/________  _______\      /_______  _______________________________________\\n         ||       \\    //       ||\n         ||        \\  //        ||  @{" Purpose      ? " link "menu"}\n         ||_____/\  \\//  /\_____||  @{" Installation ? " link "menu2"}\n         |______/\\  \/  //\______|  @{" Requirements ? " link "menu3"}\n                  \\    //           @{" Credits      ? " link "menu4"}\n                   \\  //            @{" Support      ? " link "menu5"}\n                    \\//\n                     \/\n@endnode\n\n@node "menu" "What does it do?"\n@toc "menu"\n\n\n                           =WHAT DOES IT DO???=\n\n  This door is a COOL replacement for your ''G'' Command in AMIEXPRESS3.XX\n       any user can write REAL eall msgs preserved he has uploaded a\n   certain amount of bytes or he has a cool level (all to be configured)\n         It will cost him some bytes to place his eall messages :)\n\n           THE OUTFIT IS FULL CONFIGURABLE BY THE SYSOP HIMSELF\n           ----------------------------------------------------\n                 It is very simple but unbelievably Coo| !\n\n\n                            @{" BACK TO MAIN MENU? " link "MAIN"}\n\n@endnode\n\n@node "menu2" "Installation"\n@toc "menu"\n\n\n                            ../INSTALLATION\..\n\n          Nice Question ! Just Copy all files to your directories\n                                and go ...\n\n\n                  Put this shit in your startup sequence\n\n                               rpstart >nil:\n                              rexxmast >nil:\n\n                      *do not 4get to copy the libs*\n\n      IF YOU DONT GET THE INSTALLATION JUST *CLOSE* YOUR BBS!DUMMASS!\n\n@endnode\n\n@node "menu3" "What does it require?"\n@toc "menu"\n\n\n                     =WHAT ABOUT THE REQUIREMENTS???=\n\n                       AMIGA 5oo-4ooo (68ooo-68o4o)\n\n     AMIEXRESS V3.XX+ (C)LIGHTSPEED 94 / S-EXPRESS0.xx (C) SIGMA SEVEN\n\n                 TWO LIBRARIES (SUPPORTED IN THIS PACKAGE)\n\n                 SOME COMMANDS (SUPPORTED IN THIS PACKAGE)\n\n\n\n\n      This Program will run On *ANY* Machine!Execpt PeeCee Clowns :)\n\n\n@endnode\n\n@node "menu4" "Credits!"\n@toc "menu"\n\n                               =THE CREdZ!=\n\n                        Coding - Jordan/5D/SSF/NTR\n\n                            CygnusEd - ASDG Inc\n                          Rexx - C=Commodore Inc\n                         Amiexpress - Joseph Hodge\n                      RpStart - Dineen Edwards Group\n\n                     Greets to all IA MEMBERS ^ to...\n                 Blue/Coroplex/Rainman/Ceterus/Sigma Seven\n              HobbiT/Tokata/NicK!/AWOL/Kaoz/GEM/Slazer/Exocet\n        Scottie/Maz/Hamster/Irata and all I learned to know through\n                         all the years in scene :)\n\n\n                            @{" BACK TO MAIN MENU? " link "MAIN"}\n\n@endnode\n@node "menu5" "Support"\n@toc "menu"\n\nINSERT INTO door_catalog VALUES('5d_dsgb1','5D-DSGB1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5D-DSGB1.LHA','RexxMast','XIM','RPStart',NULL,NULL,'5D','5(___  / ¬|  ___.  ____  /  ____  ____ ¬|  ) T/  /  \__   \ ¬|  \  _  \___ ¬\  ¬\ \__   \ H\___  /___  /  |__/  |__/_____/___/_____  /',replace('  ________._____________________________.__ \n5(___  / ¬|  ___.  ____  /  ____  ____ ¬|  )\nT/  /  \__   \ ¬|  \  _  \___ ¬\  ¬\ \__   \\nH\___  /___  /  |__/  |__/_____/___/_____  /\n|   ¬\/tGø¬\/___| \___|                 ¬\/|\n|                                          |\n|    SX2.x   dESIGNER gOODBYE 1.0  /X3.x   |\n|            ~~~~~~~~~~~~~~~~~~~~          |\n|create your OWN lOGOFF dOOR for your OWN  |\n|pleasure,FULL outfit creation,LOTS of lame|\n|functions...AIM DOOR TYPE ... /X / SigmaX |\n`------------------------------------------''\n======[5D]=sOME sTRANGE aDDICTION=[SSF]=====\n--=[5D]=-Can-you-handle-LAMENESS-?-=[SSF]=--\n','\n',char(10)),'5d-dzign.guide',replace('@database "=GUILD OF THIEVES= - AN ELITE DREAM COMES TRUE!"\n@Node MAIN "=GuILD oF THIEvES="\n                     /\\n                    //\\\n         