on"\n@toc "menu"\n\n\n                            ../INSTALLATION\..\n\n          Nice Question ! Just Copy all files to your directories\n                                and go ...\n\n\n                  Put this shit in your startup sequence\n\n                               rpstart >nil:\n                              rexxmast >nil:\n\n                      *do not 4get to copy the libs*\n\n      IF YOU DONT GET THE INSTALLATION JUST *CLOSE* YOUR BBS!DUMMASS!\n\n@endnode\n\n@node "menu3" "What does it require?"\n@toc "menu"\n\n\n                     =WHAT ABOUT THE REQUIREMENTS???=\n\n                       AMIGA 5oo-4ooo (68ooo-68o4o)\n\n     AMIEXRESS V3.XX+ (C)LIGHTSPEED 94 / S-EXPRESS0.xx (C) SIGMA SEVEN\n\n                 TWO LIBRARIES (SUPPORTED IN THIS PACKAGE)\n\n                 SOME COMMANDS (SUPPORTED IN THIS PACKAGE)\n\n\n\n\n      This Program will run On *ANY* Machine!Execpt PeeCee Clowns :)\n\n\n@endnode\n\n@node "menu4" "Credits!"\n@toc "menu"\n\n                               =THE CREdZ!=\n\n                        Coding - Jordan/5D/SSF/NTR\n\n                            CygnusEd - ASDG Inc\n                          Rexx - C=Commodore Inc\n                         Amiexpress - Joseph Hodge\n                      RpStart - Dineen Edwards Group\n\n                     Greets to all IA MEMBERS ^ to...\n                 Blue/Coroplex/Rainman/Ceterus/Sigma Seven\n              HobbiT/Tokata/NicK!/AWOL/Kaoz/GEM/Slazer/Exocet\n        Scottie/Maz/Hamster/Irata and all I learned to know through\n                         all the years in scene :)\n\n\n                            @{" BACK TO MAIN MENU? " link "MAIN"}\n\n@endnode\n@node "menu5" "Support"\n@toc "menu"\n\nINSERT INTO door_catalog VALUES('5d_ed110','5D-ED110.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5D-ED110.LHA','5D-Edit','XIM','5D-Edit',NULL,'.sTc./5D!','5D','\_    \   \/   /|  |/   \ /   \__ \   \/   / |  |  \  /   /_|  |  |  | \___||  \  /   / |  |  |\/  _/  \  |  |  |     ||  |\/  _/',replace('5th_______  ____ __  ___   ___________  ____\n\_    \   \/   /|  |/   \ /   \__ \   \/   /\n |  |  \  /   /_|  |  |  | \___||  \  /   /\n |  |  |\/  _/  \  |  |  |     ||  |\/  _/\n |  |  | |  |    \_|     | __  ||  | |  |\n |  |  | |  |_sNoW |     |  /  ||  | |  |\n |  |  | |  | \    |  |  | /   ||  | |  |\n |  |  | |  |  \   |  |  |     ||  | |  |\n |_____| |__|__|\__|__|__|____/ |__| |__|\n (=  5D-EdIT V1.10 CoDED bY .sTc./5D!  =)\n (=      NoW WiTH CuSTOM LiNES!!!      =)\n','\n',char(10)),'5D-Edit.guide',replace('@database 5D-EditDoc\n@Author SvEN tHE CREAToR ·OF· 5TH DYNASTY\n@Index MAIN\n\nCopyright (c) 1993 SvEN tHE CREAToR / 5th Dynasty\n\n@Remark $VER: (December 3 1993, 22:30:00)\n@Remark AmigaGuide database for the 5D-Edit Documentation\n\n@node MAIN "5D-Edit Documentation (c)1993 SvEN tHE CREAToR of 5th Dynasty (December 3 1993, 22:30:00)"\n\n                                                              :\n                                                       :      ¦             \n                   ________________  __________________¦      |\n            _______\_______       /  \             /   |      |______\n           |  __   _/     /______/____\  _     _  /    ¦      |  __  |\n           |  \/  _\________    \_\  / \/       \/     _      |  \/  |\n           |______\        /     / \/   |       |      /      |______|\n                   \___________ /       |_______|_____/       |Rpd!\n                              \/                     /________|\n                         :           :                                     :\n            ____   :     ¦     :     ¦      · 5 · T · H ·            :     ¦\n  __________\  /___¦    _|__/\ ¦     |_______ _______________________¦     |\n  \______   \\//   |    \____ \|     |   _   \\_____      /       /  |     |\n   /     \   \/    ¦     |   \ \     |   /    \/   /_____/    _  /   ¦     |\n _/       \   \_____     |    \ \_   |   _     \_____   \_     \/_____     |\n \       _/    /   /     |     \     |   /      /   /    /     |     /     |\n  \__________ /__________|     |\ ___|__/_____ /_______ /______|___________|\n            \/           |     ¦ \/          \/       \/\n                         ¦     :     · D · Y · N · A · S · T · Y ·\n                         :\n\n                              >>> 5D-Edit <<<\n\n                         Code: SvEN tHE CREAToR/5D\n\n\n---------------------------------------------------------------------------- \n\n         >>> C·O·N·T·E·N·T·S  O·F  D·O·C·U·M·E·N·T·A·T·I·O·N <<<\n\n                   N·E·W :   BUGS FIXED AND THE USERS CAN NOW\n                             DEFINE SOME CUSTOM_LINES WITH:::\n                             CTRL-W!!! AND IT CAN BE INSERTED\n                             WITH CTRL-Y!!! 5D-r0oLZ!!!!!!!!!\n\n\n                         @{"      Introduction      " Link Cap01}\n                         @{"      Requirements      " Link Cap02}\n                         @{"      Installation      " Link Cap03}\n                         @{"       Tooltypes!       " Link Cap04}\n                         @{"       Greetings!       " Link Cap05}\n                         @{"   How to Contact me?   " Link Cap06}\n\n\n         ---------------------------------------------------------\n              Complete Docs for 5D-Edit V1.10 [-5th Dynasty-]\n         ---------------------------------------------------------\n         The Documentation has been written by SvEN tHE CREAToR/5D.\n\n@endnode\n@node Cap01 "Introduction"\n  =======================================================================\n  5D-Edit is a door which allows the users to edit the descriptions\n  of the files they uploaded or especially (Co-)SysOps can edit all\n  files! It is the first editor which fully supports the use of\n  cursors. Also you can insert group logos which you can simply add\n  ot remove!\n  =======================================================================\n@endnode\n@node Cap02 "Requirements"\n  =======================================================================\n  To install 5D-Edit you must have the following things:\n\n    Programm     Location           Description\n    ----------   --------           -----------\n    5D-Edit      Doors:5D-Edit      Main program\n\n  - an  Amiga Model (500/600/1000/1200/2000/2500/3000/4000/CDTV/CD³²)\n  - the installed Version of OS\2, OS\3 or higher\n    (Soft- or Hardware Version)\n  - the installed .INFO Files in the directories.\n  - AmiExpress v3.xx or higher.\n\n  =======================================================================\n@endnode\n@node Cap03 "How to install 5D-Edit"\n  =======================================================================\n  To install 5D-Edit you must have all Requirement which were\n  mentioned below. You need the following things.\n\n  --------------------------\n    Doors:5D-Edit (dir)\n      ^^^ 5D-Edit\n    BBS:Commands/BBSCmd (dir)\n      ^^^ ED.info\n  --------------------------\n\n  Decruch the 5D-Edit Archive. Go to your ''Doors:'' Directory\n  and make a Directory called ''5D-Edit/''. Copy ''5D-Edit''\n  into the Directory. Go to your ''BBS:Commands/BBSCmd/'' Directory.\n  Copy ''ED.info'' into it.\n  =======================================================================\n@endnode\n@node Cap04 "ToolTypes ..."\n  =======================================================================\n  Tooltypes of ''Doors:5D-Edit/5D-Edit.info'':\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n  OVERLAY_CHECK_LEVEL=<LEVEL>      - Allows you to set the level at\n                                     which 5D-Edit will not check\n                                     if the user has uploaded the\n                                     file.\n\n                                     EXAMPLE:\n                                     OVERLAY_CHECK_LEVEL=200\n  UDLOG                            - Allows you to define the use\n                                     of the ''UDLog'' instead of\n                                     the CallersLog!\n  MAX_LINES=<LINES>                - Allows you to set how many\n                                     lines can be edited.\n                                     I inserted this command\n                                     because I had to see that\n                                     /X 3.16 is able to use\n                                     13 lines instead of 12.\n                                     You can finally use 20 lines!\n\n                                     EXAMPLE:\n                                     MAX_LINES=13\n\n  =======================================================================\n@endnode\n@node Cap05 "Greetings go to..."\n  =======================================================================\n\n                        GREETS GO TO:\n\n    ByteAndi/MST ......................... For helping me!\n    Strider/PGS .................... Hope we''ll chat soon!\n    Mr.Return/AG ............................ Good friend!\n    Bytemaster ....................... For programming /X!\n    Celator/AFL ..................... For helping me more!\n\n              >>> ALL MEMBERS OF 5TH DYNASTY!!! <<<\n\n  =======================================================================\n@endnode\n@node Cap06 "How to contact me..."\n  =======================================================================\n    ___________________________   ___________   ___________________________\n   /\_______________________ _ \¡/           \¡/  _ ______________________/\\n   \/                            ·5TH DYNASTY·                            \/\n    ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\_______________/¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n    CELTIC CROSS ............... Thunder ...... +49-(0)30-******* ..... WHQ\n    DA UNKNOWN .................. Sharon ...... +31-(0)2990-36047 ..... EHQ\n    MIAMI HEAT ........ Sven The Creator ...... +49-(0)30-7424141 ..... GHQ\n    HOUSE OF BRAIN ............. Delta-X ...... +49-(0)3328472023 ..... GHQ\n    LE