INSERT INTO door_catalog VALUES('5d_lg112','5D-LG112.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5D-LG112.LHA','5D-LogOff','XIM','5D-LogOff',NULL,'sTc/5D!','5D','\_    \   \/   /|  |/   \ /   \__ \   \/   / |  |  \  /   /_|  |  |  | \___||  \  /   / |  |  |\/  _/  \  |  |  |     ||  |\/  _/',replace('5th_______  ____ __  ___   ___________  ____\n\_    \   \/   /|  |/   \ /   \__ \   \/   /\n |  |  \  /   /_|  |  |  | \___||  \  /   / \n |  |  |\/  _/  \  |  |  |     ||  |\/  _/  \n |  |  | |  |    \_|     | __  ||  | |  |   \n |  |  | |  |_sNoW |     |  /  ||  | |  |   \n |  |  | |  | \    |  |  | /   ||  | |  |   \n |  |  | |  |  \   |  |  |     ||  | |  |   \n |_____| |__|__|\__|__|__|____/ |__| |__|   \n (=  5D-LoGOFF V1.12 CoDED bY sTc/5D!  =)   \n (=        NoW WiTH LeAVE MsG!!        =)\n','\n',char(10)),'5D-LogOff.guide',replace('@database 5D-LogOffDoc\n\nCopyright (c) 1993 SvEN tHE CREAToR / 5th Dynasty\n\n@Remark $VER: (December 11 1993, 22:00:00)\n@Remark AmigaGuide database for the 5D-LogOff Documentation\n\n@node MAIN "5D-LogOff Documentation (c)1993 SvEN tHE CREAToR of 5th Dynasty (December 11 1993, 22:00:00)"\n\n                                                              :\n                                                       :      ¦             \n                   ________________  __________________¦      |\n            _______\_______       /  \             /   |      |______\n           |  __   _/     /______/____\  _     _  /    ¦      |  __  |\n           |  \/  _\________    \_\  / \/       \/     _      |  \/  |\n           |______\        /     / \/   |       |      /      |______|\n                   \___________ /       |_______|_____/       |Rpd!\n                              \/                     /________|\n                         :           :                                     :\n            ____   :     ¦     :     ¦      · 5 · T · H ·            :     ¦\n  __________\  /___¦    _|__/\ ¦     |_______ _______________________¦     |\n  \______   \\//   |    \____ \|     |   _   \\_____      /       /  |     |\n   /     \   \/    ¦     |   \ \     |   /    \/   /_____/    _  /   ¦     |\n _/       \   \_____     |    \ \_   |   _     \_____   \_     \/_____     |\n \       _/    /   /     |     \     |   /      /   /    /     |     /     |\n  \__________ /__________|     |\ ___|__/_____ /_______ /______|___________|\n            \/           |     ¦ \/          \/       \/\n                         ¦     :     · D · Y · N · A · S · T · Y ·\n                         :\n\n                             >>> 5D-LogOff <<<\n\n                Code: SvEN tHE CREAToR/5D  GFX: Cee Jay/5D\n\n---------------------------------------------------------------------------- \n\n         >>> C·O·N·T·E·N·T·S  O·F  D·O·C·U·M·E·N·T·A·T·I·O·N <<<\n\n                         @{"      Introduction      " Link Cap01}\n                         @{"      Requirements      " Link Cap02}\n                         @{"      Installation      " Link Cap03}\n                         @{"       Tooltypes!       " Link Cap04}\n                         @{"       Greetings!       " Link Cap05}\n                         @{"   How to Contact me?   " Link Cap06}\n\n         ---------------------------------------------------------\n             Complete Docs for 5D-LogOff V1.12 [-5th Dynasty-]\n         ---------------------------------------------------------\n         The Documentation has been written by SvEN tHE CREAToR/5D\n\n@endnode\n@node Cap01 "Introduction"\n  =======================================================================\n  5D-LogOff is a replacement for the normal LogOff SysOp Command\n  of AmiExpress ''G''.\n  =======================================================================\n@endnode\n@node Cap02 "Requirements"\n  =======================================================================\n  To install 5D-LogOff you must have the following things:\n\n    Programm     Location           Description\n    ----------   --------           -----------\n    5D-LogOff    Doors:5D-LogOff    Main program\n\n  - an  Amiga Model (500/600/1000/1200/2000/2500/3000/4000/CDTV/CD³²)\n  - the installed Version of OS\2, OS\3 or higher\n    (Soft- or Hardware Version)\n  - the installed .INFO Files in the directories.\n  - AmiExpress V2.xx , v3.xx or higher.\n\n  =======================================================================\n@endnode\n@node Cap03 "How to install 5D-LogOff"\n  =======================================================================\n  To install 5D-LogOff you must have all Requirement which were\n  mentioned below. You need the following things.\n\n  --------------------------\n    Doors:5D-LogOff (dir)\n      ^^^ 5D-LogOff\n    BBS:Commands/BBSCmd (dir)\n      ^^^ G.info\n  --------------------------\n\n  Decruch the 5D-LogOff Archive. Go to your ''Doors:'' Directory\n  and make a Directory called ''5D-LogOff''. Copy ''5D-LogOff''\n  into the Directory. Go to your ''BBS:Commands/BBSCmd'' Directory.\n  Copy ''G.info'' into it.\n  =======================================================================\n@endnode\n@node Cap04 "Tooltype Informations..."\n  =======================================================================\n  - All tooltypes available in ''Doors:5D-LogOff/5D-LogOff.info''\n\n  BBS=<BBS_NUMBERS>    - For specifying the number of BBS which will\n                         be written in "Doors:5D-LogOff/5D-LogOff.Adds".\n                         If this tooltype isn''t specified the option\n                         will be disabled in 5D-LogOff\n  PASSWORD=BROILER     - For specifying the password which\n                         has to be inserted for secret paging\n                         with SECRET_KEY. If no password is inserted\n                         5D-LogOff will do NOTHING AT THIS COMMAND!\n  SECRET_KEY=$         - Means the key which has to be pressed to come\n                         into Secret Page PASSWORD asking!\n  =======================================================================\n@endnode\n@node Cap05 "Greetings go to..."\n  =======================================================================\n\n             ···­­­> ALL MEMBERS OF 5TH DYNASTY <­­­···\n\n      .-----------------------------------------------------.\n      : And all cool people who I know and all who know me! :\n      `-----------------------------------------------------''\n\n  =======================================================================\n@endnode\n@node Cap06 "How to contact me..."\n  =======================================================================\n    ___________________________   ___________   ___________________________\n   /\_______________________ _ \¡/           \¡/  _ ______________________/\\n   \/                            ·5TH DYNASTY·                            \/\n    ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\_______________/¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n    CELTIC CROSS ............... Thunder ...... +49-(0)30-******* ..... WHQ\n    DA UNKNOWN .................. Sharon ...... +31-(0)2990-36047 ..... EHQ\n    MIAMI HEAT ........ Sven The Creator ...... +49-(0)30-7424141 ..... GHQ\n    HOUSE OF BRAIN ............. Delta-X ...... +49-(0)33-OFFLINE ..... GHQ\n    LEX EXPRESS NODE 0 ....... R.I.P.`93 ...... +49-(0)30-3242112 ..... GHQ\n    LEX EXPRESS NODE 1 ....... R.I.P.`93 ...... +49-(0)30-3242160 ..... GHQ\n    POWER BOX III ........ Frank Maxwell ...... +49-(0)30-4167884 ..... GHQ\n    5TH DYNASTY CLUB .............. Snow ...... +49-(0)30-******* ..... GHQ\n    DREAMSCAPE ................. Unknown ...... +31-(0)5255-23-72 ..... NHQ\n    HEAVENS GATE ................ Murdoc ...... +49-(0)30-6596730 ..... GDS\n\n                 ___ ___    ___    _______    ___ ___    ___\n                /  ¬|  ¬\  /  ¬\  /      ¬\  /  ¬|  ¬\  /  ¬\\n               /         \/     \/         \/         \/     \\n              /           \      \          \          \      \\n            _/             \_     \_  |      \_         \_     \_\n            \      \ /      /      /          / \ /      /      /\n             \      |      /      /   |      /   |      /      /\n              \_____|____ /_____ /____|____ /____|____ /_____ /\n          /\            \/     \/         \/         \/     \/\n_________/  \  /\___________> 5TH DYNASTY GHQ <____________________ ___ __ _\n             \/    ___ ___    _______    _______    _______\n                  /  ¬|  ¬\  /      ¬\  /      ¬\  /      ¬\\n                 /    |    \/         \/         \/         \\n                /           \    |     \          \          \\n              _/             \_     ___/\_  |      \_____     \_\n              \               /    /     /          / |        /\n               \      |      /          /   |      /  |       /\n                \_____|____ /_________ /____|____ /   |_____ /·cj·\n                          \/         \/         \/         \/\n \n                         SYSOP: SvEN tHE CREAToR/5D\n                         COSYS: Airworx/5D\n                                Mr.Return/AG\n \n                   -<>- CaLL: +49-(0)30-742-4141 -<>-\n\n  =======================================================================\n@endnode\n','\n',char(10)),NULL,'auto-added',33592,6,0,NULL,NULL,'5d_lg112','scan',1780048358);
INSERT INTO door_catalog VALUES('5d_lo014','5D-LO014.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5D-LO014.LHA','5D-LogOff','XIM','5D-LogOff',NULL,'sTc/5D!','5D','______\     /__|      /___________\___  /___ \_____ \  _/   /     /__\   ____/  _ /_/   / _/   /  \___  /\    /__/ \____ \_  \/___  /|',replace('      _______   _______           _______   \n______\     /__|      /___________\___  /___\n\_____ \  _/   /     /__\   ____/  _ /_/   /\n_/   /  \___  /\    /__/ \____ \_  \/___  /|\n\ 5TH    / / /\ \_ / \    / _/  /  |   / / |\n|\______/___/_|\  /___\  /_____/___|____/Rpd\n`---------------\/-----\/------------------''\n      5D-LogOff v1.14 coded by sTc/5D!\n             - PW bug fixed -\n','\n',char(10)),'5D-LogOff.Guide',replace('@DataBase 5D-LogOff Documentation\n@Author sTc/5D\n@Index Documentation\n\nCopyright © 1994 SvEN tHE CREAToR of 5tH DyNASTY\n\n@Remark $VER: 5D-LogOff v1.14 by sTc/5D\n@Remark AmigaGuide DataBase\n\n@node MAIN "5D-LogOff Documentation © 1994 SvEN tHE CREAToR of 5tH DyNASTY"\n                                                              :\n                                                       :      ¦             \n                   ________________  __________________¦      |\n            _______\_______       /  \             /   |      |______\n           |  __   _/     /______/____\  _     _  /    ¦      |  __  |\n           |  \/  _\________    \_\  / \/       \/     _      |  \/  |\n           |______\        /     / \/   |       |      /      |______|\n                   \___________ /       |_______|_____/       |Rpd!\n                              \/                     /________|\n                         :           :                                     :\n            ____   :     ¦     :     ¦      · 5 · T · H ·            :     ¦\n  __________\  /___¦    _|__/\ ¦     |_______ _______________________¦     |\n  \______   \\//   |    \____ \|     |   _   \\_____      /       /  |     |\n   /     \   \/    ¦     |   \ \     |   /    \/   /_____/    _  /   ¦     |\n _/       \   \_____     |    \ \_   |   _     \_____   \_     \/_____     |\n \       _/    /   /     |     \     |   /      /   /    /     |     /     |\n  \__________ /__________|     |\ ___|__/_____ /_______ /______|___________|\n            \/           |     ¦ \/          \/       \/\n                         ¦     :     · D · Y · N · A · S · T · Y ·\n                         :\n\n                              (×· PrESENTS ·×)\n\n                         Code: SvEN tHE CREAToR/5D\n\n                 ----- --- -> 5D-LogOff v1.14 <- --- -----\n\n                  Coded by SvEN tHE CREAToR of 5th Dynasty\n\n                           @{" Normal Documentation " Link Documentation}\n@endnode\n@node Documentation "5D-LogOff Documentation"\n              _______________________________________________\n             |                                               |\n             | //                                            |\n             | /                                             |\n             |                                               |\n             |            @{" D e S C R I P T I O N " Link Description}           |\n             |                                               |\n             |           @{" I n S T A L L A T I O N " Link Installation}          |\n             |                                               |\n             |              @{" G r E E T I N G S " Link Greetings}             |\n             |                                               |\n             |                                             / |\n             |                                            // |\n             |_______________________________________________|\n\n@endnode\n@node Description "5D-LogOff Description"\n5D-LogOff has been coded by SvEN tHE CREAToR/5D!\n\n5D-LogOff is a replacement for the normal LogOff SysOp Command\nof AmiExpress ''G''.\n@endnode\n@node Installation "5D-LogOff Installation"\nCopy all files which are in the ''BBS'' directory of the archive\ninto your bbs directory.\n\nContents of archive:\n===================\n\nBBS/ Commands/ BBSCmd/    G.info\n     Doors/    5D-LogOff/ Custom/\n                          Logos/\n                          5D-LogOff\n                          5D-LogOff.info\n                          5D-LogOff.Guide\n\n===================\n@endnode\n@node Greetings "5D-LogOff Greetings"\nGreetings go to:\n\n         . Celator ........... Thank you for helping me with /X! .\n         : ByteAndi ............ For helping me to learn coding! :\n         | Snow ...................... Sing mehr lieder, leader! |\n         `------( And all other persons I''ve forgotten!!! )------''\n\n@endnode\n','\n',char(10)),NULL,'auto-added',16011,1,0,NULL,NULL,'5d_lo014','scan',1780048358);
