INSERT INTO door_catalog VALUES('5d_mbfix','5D-MBFIX.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5D-MBFIX.LHA',NULL,'XIM','________._____________________________.__',NULL,NULL,'5D','5(___  / ¬|  ___.  ____  /  ____  ____ ¬|  ) T/  /  \__   \ ¬|  \  _  \___ ¬\  ¬\ \__   \ H\___  /___  /  |__/  |__/_____/___/_____  /',replace('  ________._____________________________.__ \n5(___  / ¬|  ___.  ____  /  ____  ____ ¬|  )\nT/  /  \__   \ ¬|  \  _  \___ ¬\  ¬\ \__   \\nH\___  /___  /  |__/  |__/_____/___/_____  /\n|   ¬\/tGø¬\/___| \___|                 ¬\/|\n|    /X3.x  mSGBASS2.O (1o1 % VERSION!)    |\n|                                          |\n|   ''E'' REPLACEMENT UPDATED AND UNFAKED    |\n|                                          |\n|    **FIXED MAINFILE** BUGS ERASED NOW    |\n|Install this one to make it work 101% !!! |\n`------------------------------------------''\n','\n',char(10)),'DESERTBANNER2.readme',replace('                   [ TH¡S F¡Le WaS LeeCHeD FRoM ]\n   ___________________________________________________________________\n    \_______  \______     /\   _____________   \_/______ \___/_  _____/\n    _/     /   \_   /    / /\_____  \_/    /    /    __/ ___/|    |\n    \    _/     / ______/\/      /   \    _____/\    \     \_|    |\n     \_______  /__________\___________)__________\____\_____/|    |\n             \/-Mo!/f^I                                      |____|\n                                    /\\n         __________________________/_ \________/\_____________\n         \   ________  ________     /_________/  \______     /\n         /\_____  \|   _/   __/ ___/  _/   __/ ___)    /    /\n        /      /   \   \    \     \_  \    \     \_  ______/\\n       /____________)   \____\_____/   \____\_____/__________\\n                   |____|         |____|\n','\n',char(10)),NULL,NULL,42558,7,0,NULL,NULL,NULL,'scan',1780048358);
INSERT INTO door_catalog VALUES('5d_mbs2','5D-MBS2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5D-MBS2.LHA','RexxMast','XIM','RPStart',NULL,NULL,'5D','5(___  / ¬|  ___.  ____  /  ____  ____ ¬|  ) T/  /  \__   \ ¬|  \  _  \___ ¬\  ¬\ \__   \ H\___  /___  /  |__/  |__/_____/___/_____  /',replace('  ________._____________________________.__ \n5(___  / ¬|  ___.  ____  /  ____  ____ ¬|  )\nT/  /  \__   \ ¬|  \  _  \___ ¬\  ¬\ \__   \\nH\___  /___  /  |__/  |__/_____/___/_____  /\n|   ¬\/tGø¬\/___| \___|                 ¬\/|\n|    /X3.x  mSGBASS2.O (100 % VERSION!)    |\n|                                          |\n|   ''E'' REPLACEMENT UPDATED AND UNFAKED    |\n|                                          |\n|Read the facts about the 1st release and  |\n|Why you REALLY should install THIS tool!  |\n`------------------------------------------''\n READ ABOUT APROLLO AND WHY HE WAS BUSTED\n','\n',char(10)),'5d-Msgbass.Guide',replace('@database "=GUILD OF THIEVES= - AN ELITE DREAM COMES TRUE!"\n@Node MAIN "=GuILD oF THIEvES="\n                     /\\n                    //\\\n                   //  \\\n__________________//    \\_________________________________________________\n\ _______ ________/      \________ ______________________________________ /\n \\      \\                      //                                     //\n  \\      \\                    //      MSGBASS 2.O EALL SENDER!       //\n   \\      \\      JORDAN      //                                     //\n    \\      \\       OF       //    Released on 07.07.94 , Friday    //\n    //      //  5TH DyNASTY   \\                                     \\\n   //      //                  \\       NOW GO FOR THE DOCUMENTATION  \\\n  //      //                    \\                                     \\\n //______//_______        _______\\_____________________________________\\\n/________  _______\      /_______  _______________________________________\\n         ||       \\    //       ||\n         ||        \\  //        ||  @{" Purpose      ? " link "menu"}\n         ||_____/\  \\//  /\_____||  @{" Installation ? " link "menu2"}\n         |______/\\  \/  //\______|  @{" Requirements ? " link "menu3"}\n                  \\    //           @{" Credits      ? " link "menu4"}\n                   \\  //            @{" Support      ? " link "menu5"}\n                    \\//\n                     \/\n@endnode\n\n@node "menu" "What does it do?"\n@toc "menu"\n\n\n                           =WHAT DOES IT DO???=\n\n   msgBASS is a COOL replacement for your ''E'' Command in AMIEXPRESS3.XX\n       any user can write REAL eall msgs preserved he has uploaded a\n   certain amount of bytes or he has a cool level (all to be configured)\n         It will cost him some bytes to place his eall messages :)\n\n     Coz as u all know -->> Advertising is EXPENSIVE << :) HAhahahaha\n\n                 It is very simple but unbelievably Coo| !\n\n\n          READ THE UPDATE.DELTAFORCE FILE FOR MORE INFORMATION!!!\n\n                            @{" BACK TO MAIN MENU? " link "MAIN"}\n\n@endnode\n\n@node "menu2" "Installation"\n@toc "menu"\n\n\n                            ../INSTALLATION\..\n\n          Nice Question ! Just Copy all files to your directories\n                                and go ...\n\n\n                  Put this shit in your startup sequence\n\n                               rpstart >nil:\n                              rexxmast >nil:\n\n                      *do not 4get to copy the libs*\n\n      IF YOU DONT GET THE INSTALLATION JUST *CLOSE* YOUR BBS!DUMMASS!\n\n@endnode\n\n@node "menu3" "What does it require?"\n@toc "menu"\n\n\n                     =WHAT ABOUT THE REQUIREMENTS???=\n\n                       AMIGA 5oo-4ooo (68ooo-68o4o)\n\n                     AMIEXRESS V3.XX+ (C)LIGHTSPEED 94\n\n                 TWO LIBRARIES (SUPPORTED IN THIS PACKAGE)\n\n                 SOME COMMANDS (SUPPORTED IN THIS PACKAGE)\n\n\n\n\n      This Program will run On *ANY* Machine!Execpt PeeCee Clowns :)\n\n\n@endnode\n\n@node "menu4" "Credits!"\n@toc "menu"\n\n                               =THE CREdZ!=\n\n                          Coding - Jordan/5d/SSF\n                         Guide - Jordan Interactive\n\n                            CygnusEd - ASDG Inc\n                          Rexx - C=Commodore Inc\n                         Amiexpress - Joseph Hodge\n                      RpStart - Dineen Edwards Group\n\n                     Greets to all IA MEMBERS ^ to...\n                 Blue/Coroplex/Rainman/Ceterus/Sigma Seven\n              HobbiT/Tokata/NicK!/AWOL/Kaoz/GEM/Slazer/Exocet\n        Scottie/Maz/Hamster/Irata and all I learned to know through\n                         all the years in scene :)\n\n\n                            @{" BACK TO MAIN MENU? " link "MAIN"}\n\n@endnode\n@node "menu5" "Support"\n@toc "menu"\n\nINSERT INTO door_catalog VALUES('5d_ms001','5D-MS001.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5D-MS001.LHA','5D-MultiStart','XIM','5D-MultiStart',NULL,'SvEN','5D','______\     /__|      /___________\___  /___ \_____ \  _/   /     /__\   ____/  _ /_/   / _/  _/  \___  /\    /__/ \____ \_  \/___  /|',replace('      _______   _______           _______   \n______\     /__|      /___________\___  /___\n\_____ \  _/   /     /__\   ____/  _ /_/   /\n_/  _/  \___  /\    /__/ \____ \_  \/___  /|\n\ 5.\    / / /\ \_ / \    / _/  /  |   / / |\n|\______/___/_|\  /___\  /_____/___|____/Rpd\n`---------------\/-----\/----·presents·----''\n            5D-MultiStart v0.01\n   Coded by SvEN tHE CREAToR/5tH DyNASTY\n Lets you start more than one door for one\n/X-Command! F.e.: 5D-AutoFree and DupeCheck\n','\n',char(10)),'5D-MultiStart.Guide',replace('@database 5D-MultiStart Documentation\n@Author SvEN tHE CREAToR Of 5tH DyNASTY\n@Index Documentation\n\nCopyright © 1994 SvEN tHE CREAToR / 5tH DyNASTY\n\n@Remark $VER: 5D-MultiStart v0.01 by sTc/5D\n@Remark AmigaGuide database\n\n@node MAIN "5D-MultiStart Documentation © 1994 SvEN tHE CREAToR Of 5tH DyNASTY"\n                                                              :\n                                                       :      ¦             \n                   ________________  __________________¦      |\n            _______\_______       /  \             /   |      |______\n           |  __   _/     /______/____\  _     _  /    ¦      |  __  |\n           |  \/  _\________    \_\  / \/       \/     _      |  \/  |\n           |______\        /     / \/   |       |      /      |______|\n                   \___________ /       |_______|_____/       |Rpd!\n                              \/                     /________|\n                         :           :                                     :\n            ____   :     ¦     :     ¦      · 5 · T · H ·            :     ¦\n  __________\  /___¦    _|__/\ ¦     |_______ _______________________¦     |\n  \______   \\//   |    \____ \|     |   _   \\_____      /       /  |     |\n   /     \   \/    ¦     |   \ \     |   /    \/   /_____/    _  /   ¦     |\n _/       \   \_____     |    \ \_   |   _     \_____   \_     \/_____     |\n \       _/    /   /     |     \     |   /      /   /    /     |     /     |\n  \__________ /__________|     |\ ___|__/_____ /_______ /______|___________|\n            \/           |     ¦ \/          \/       \/\n                         ¦     :     · D · Y · N · A · S · T · Y ·\n                         :\n\n                        ##>>> P r E S E N T S <<<##\n\n                            5D-MultiStart v0.01\n\n                 Coded by SvEN tHE CREAToR of 5th Dynasty\n\n                           @{" Normal Documentation " Link Documentation}\n@endnode\n@node Documentation "5D-MultiStart Documentation"\n              _______________________________________________\n             |                                               |\n             | //                                            |\n             | /                                             |\n             |                                               |\n             |            @{" D e S C R I P T I O N " Link Description}           |\n             |                                               |\n             |           @{" I n S T A L L A T I O N " Link Installation}          |\n             |                                               |\n             |              @{" T o O L T Y P E S " Link Tooltypes}             |\n             |                                               |\n             |              @{" G r E E T I N G S " Link Greetings}             |\n             |                                               |\n             |                                             / |\n             |                                            // |\n             |_______________________________________________|\n\n@endnode\n@node Description "5D-MultiStart Description"\n5D-MultiStart has been coded by SvEN tHE CREAToR/5D!\n\nIt allows the sysop to insert more than one XIM-Door or script for\none command. For example for the FILECHECK in BBS:Commands/SysCmd/.\nI wanted to install a Double Upload Checker and the 5D-AutoFree but it\nwasn''t possible for me. So I coded 5D-MultiStart which allows you\nto start as much doors as you want for one command. You can also use\nit to start more doors for a normal command. You can protect any of\nthese doors with a password which you can enter in the icon in\nBBS:Commands/MultiCmd/. In that directory are ALL Icons for 5D-MultiStart.\nFor the normal Command (f.e.: BBS:Commands/SysCmd/FILECHECK) you should\nuse the icon in this archive in that directory. If you want to use\n5D-MultiStart for another command simply clone that icon and make a new\nicon in BBS:Commands/MultiCmd/ with the command name. Look in the\ntooltypes area to see what you can insert in the icon.\n@endnode\n@node Installation "5D-MultiStart Installation"\nCopy all files which are in the archive bbs directory\nto your bbs directory.\n\nContents of archive:\n===================\n\nBBS/\n    Commands/\n        BBSCmd/\n            TEST.info\n        MultiCmd/\n            FILECHECK.info\n            TEST.info\n        SYSCmd/\n            FILECHECK.info\n    Doors/\n        5D-MultiStart/\n            5D-MultiStart\n            5D-MultiStart.info\n            5D-MultiStart.Guide\n\n===================\n\n@endnode\n@node Greetings "5D-MultiStart Greetings"\nGreetings go to:\n\n           Celator ........... Thank you for helping me with /X!\n           ByteAndi ............ For helping me to learn coding!\n           Prophet .................... For being a nice friend!\n           Snow ...................... Sing mehr lieder, leader!\n           Airworx ................. Continue work as Co Leader!\n           Delta-X ................. When you will merry Murdoc?\n           Strider ........ We should spread our standard again!\n\nSorry to all people I forgot but as you know my brain isn''t so well! hehe\n\n@endnode\n@node Tooltypes "5D-MultiStart Tooltypes"\nYou can insert the following tooltypes in the icons in\nBBS:Commands/MultiCmd/\n\n===========\n\nDOORS=8                            - Number of Doors\nLOCATION.3=Doors:5D-Who/5D-Who     - Location of the Door\nSTACK.3=8192                       - Stack of the Door\nPRIORITY.4=3                       - Priority of the Door\nPASSWORD.2=BREULER                 - Password for the Door\n\n===========\n@endnode\n','\n',char(10)),NULL,'auto-added',22965,8,0,NULL,NULL,'5d_ms001','scan',1780048358);
INSERT INTO door_catalog VALUES('5d_nf022','5D-NF022.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5D-NF022.LHA','5D-NewFiles','XIM','5D-NewFiles','0.22','STC/5D','5D',NULL,replace('5D-NEWFILES V0.22 CODED BY STC/5D\n','\n',char(10)),'5D-NewFiles.guide',replace('@database 5D-NewFilesDoc\n\nCopyright (c) 1993 SvEN tHE CREAToR\n\n@Remark $VER: (October 17 1993, 00:00:00)\n@Remark AmigaGuide database for the 5D-NewFiles Documentation\n\n@node MAIN "5D-NewFiles Documentation (c)1993 SvEN tHE CREAToR (October 17 1993, 00:00:00)"\n          ______    ______    ______    ______    ______    ______\n          \   ¬/    \   ¬/    \   ¬/    \   ¬/    \   ¬/    \   ¬/\n 5th ______\  /_ ____\  /______\  /______\  /______\  /______\  /_ ____\n    //     \\// |   \\\//     \\\//     \\\//     \\\//     \\\// |   \\\n   //       \/  |    \\/       \\/  |    \\/     ---\/       \\/  |    \\\n  /·         \___     ·\     |  ·\        ·\____    \\__      ·\___     ·\\n /·         | \        ·\    |   ·\ |      ·\        ·\ |      ·\        ·\\n \___________ /________ /____|___ /_|______ /________ / |______ /________ /\n            \/        \/        \/        \/        \/        \/    ·cj·\/\n\n                           >>> 5D-NewFiles <<<\n\n                  Code & Design: SvEN tHE CREAToR/5D\n\n                  __                                        __\n                  \ \                                      / /\n    >>>>>>>>>>>>>>>>>)    HAPPY BIRTHDAY AIRWORX/5D!!!    (<<<<<<<<<<<<<<<<<\n                  /_/                                      \_\\n\n                    THIS WISH YA ALL MEMBERS OF 5TH DYNASTY!\n\n\n---------------------------------------------------------------------------- \n\n          >>> C·O·N·T·E·N·T·S  O·F  D·O·C·U·M·E·N·T·A·T·I·O·N <<<\n\n\n         REMEMBER: THIS IS ONE OF THE FIRST TOOLS WHICH CHECK FOR THE\n                   NORMAL USER ACCESS. THIS MEANS THAT A USER WITH LEVEL 200\n                   CANNOT USE THE FILE LISTING IF IT IS REMOVED IN ACS.200.info!\n\n                         @{"      Introduction      " Link Cap01}\n                         @{"      Requirements      " Link Cap02}\n                         @{"      Installation      " Link Cap03}\n                         @{" ToolTypes--Information " Link Cap04}\n                         @{"       Greetings!       " Link Cap05}\n                         @{"   How to Contact me?   " Link Cap06}\n\n         ---------------------------------------------------------\n            Complete Docs for 5D-NewFiles V0.22 [-5th Dynasty-]\n         ---------------------------------------------------------\n         The Documentation has been written by SvEN tHE CREAToR/5D.\n\n@endnode\n@node Cap01 "Introduction"\n  =======================================================================\n  5D-NewFiles is a replacement for the normal file list commands\n  of AmiExpress ''F'' and ''N''. It has many improvements like ANSI\n  colored lines, inserted lines, new date, hold level, random description\n  color and many others.\n  =======================================================================\n@endnode\n@node Cap02 "Requirements"\n  =======================================================================\n  To install 5D-NewFiles you must have the following things:\n\n    Programm     Location           Description\n    ----------   --------           -----------\n    5D-NewFiles   Doors:5D-NewFiles   Main program\n\n  - an  Amiga Model (500/600/1000/1200/2000/2500/3000/4000/CD³²)\n  - the installed Version of OS\2, OS\3 or higher\n    (Soft- or Hardware Version)\n  - the installed .INFO Files in the directories.\n  - AmiExpress v2.xx, v3.xx or higher.\n\n  =======================================================================\n@endnode\n@node Cap03 "How to install 5D-NewFiles"\n  =======================================================================\n  To install AmiExpress you must have all Requirement which were\n  mentioned below. You need the following things.\n\n  --------------------------\n    Doors:5D-NewFiles (dir)\n      ^^^ 5D-NewFiles\n      ^^^ 5D-NewFiles.info\n    BBS:Commands/BBSCmd (dir)\n      ^^^ F.info\n      ^^^ N.info\n  --------------------------\n\n  Decruch the 5D-NewFiles Archive. Go to your ''Doors:'' Directory\n  and make a Directory called ''5D-NewFiles''. Copy ''5D-NewFiles''\n  and ''5D-NewFiles.info'' into the Directory. Go to your\n  ''BBS:Commands/BBSCmd'' Directory. Copy ''F.info'' and ''N.info''\n  into it.\n  =======================================================================\n@endnode\n@node Cap04 "ToolTypes in Icons to use 5D-NewFiles..."\n  =======================================================================\n     To use 5D-NewFiles you need some Icons containing in different\n     directories. This Icons contain some information to use\n     5D-NewFiles.\n\n                             @{" 5D-NewFiles.info " Link Cap0401}\n\n  =======================================================================\n@endnode\n@node Cap0401 "Doors:5D-NewFiles/5D-NewFiles.info"\n  =======================================================================\n  5D-NewFiles.info   - This Icon contains the definitions and \n  ~~~~~~~~~~~~~~~     defaults for 5D-NewFiles. @{" Colors " Link Cap040101}\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  LINE_INSERT=<MODE> - Tells 5D-NewFiles which default line will be\n                       inserted between files\n                       MODE:\n                       (1) = Normal Insert Line\n                       (2) = Empty Line\n                       (3) = File Number\n                       (4) = File Number in Normal Insert Line\n\n                       Example: LINE_INSERT=3\n\n  ANSI_COLOR=<MODE>  - Defines which Ansi mode should be used as default!\n                       MODE:\n                       (1) = Normal\n                       (2) = Random Desc Color\n                       (3) = Normal + Random Desc Color\n\n                       Example: ANSI_COLOR=2\n\n  NEW_DATE           - Tells 5D-NewFiles to show the new date as default.\n  USER_PREFS         - Tells 5D-NewFiles to let Users use their own\n                       preferences. If it is not present the users cannot\n                       use 5D-NewFiles Prefs and the defaults will be user\n                       for them.\n  INSERT_LINE=   >-------------===========-------------<\n                     - Defines the Insert Line.\n  INERT_LINE_COLOR=Blue\n                     - Defines the Insert Line''s Color. Default is Blue.\n  FILELENGTH_COLOR=Yellow\n                     - Defines the FileLength''s Color. Default is Yellow.\n  FAKE_COLOR=Red     - Defines the Fake Color. Default is Red.\n  CHECK_COLOR=Violett\n                     - Defines the Check Character Color. Default is\n                       Violett.\n  CURRENT_DATE_COLOR=Green\n                     - Defines the Current Date Color. Default is Green.\n  HOLD_LEVEL=250     - Defines the level at which a User can show the\n                       Hold directory.\n  FILE_HELP=BBS:Screens/Confs/FileHelp\n                     - Defines the custom File screen to be showed at ''F''.\n                       If you don''t want to have a File screen simply\n                       write ''FILE_HELP=-1''. If this command isn''t used\n                       5D-NewFiles will show BBS:Conf<x>/FileHelp.<Lang>.\n  NEW_HELP=BBS:Screens/Confs/NewHelp\n                     - Defines the File screen to show at ''N''.\n                       If no is inserted <Conf_Location>/FileHelp.txt will\n                       be showed\n  SHORT_FAKE_DESC    - Tells 5D-NewFiles that short Nuke Messies are used.\n\n                       Example: "ASTIDIDO.LHA P *OLD!*" instead of:\n                                "ASTIDIDO.LHA **OLD!**"\n  =======================================================================\n@endnode\n@node Cap040101 "Available Colors"\n  =======================================================================\n  None      - ESC[0m\n  Red       - ESC[31m\n  Green     - ESC[32m\n  Yellow    - ESC[33m\n  Dark      - ESC[34m\n  Violett   - ESC[35m\n  Blue      - ESC[36m\n  White     - ESC[37m\n  =======================================================================\n@endnode\n@node Cap05 "Greetings go to..."\n  =======================================================================\n\n           ···­­­> ALL MEMBERS OF 5TH DYNASTY <­­­···\n\n      +-----------------------------------------------------+\n      : And all cool people who I know and all who know me! :\n      `-----------------------------------------------------''\n\n  =======================================================================\n@endnode\n@node Cap06 "How to contact me..."\n  =======================================================================\n    ___________________________   ___________   ___________________________\n   /\_______________________ _ \¡/           \¡/  _ ______________________/\\n   \/                            ·5TH DYNASTY·                            \/\n    ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\_______________/¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n    CELTIC CROSS ............... Thunder ...... +49-OFFLINE ........... WHQ\n    REDSKINS .................. Vanguard ...... +49-OFFLINE ........... EHQ\n    POWER BOX II NODE 0 ....... Wolfgang ...... +49-(0)30-3242112 ..... GHQ\n    POWER BOX II NODE 1 ....... Wolfgang ...... +49-(0)30-3242160 ..... GHQ\n    MIAMI HEAT ........ Sven The Creator ...... +49-(0)30-7424141 ..... GHQ\n    DISASTER ZONE ........... Mr.Deicide ...... +49-(0)30-6614471 ..... DIS\n    POWER BOX III ........ Frank Maxwell ...... +49-(0)30-4167884 ..... DIS\n\n                 ___ ___    ___    _______    ___ ___    ___\n                /  ¬|  ¬\  /  ¬\  /      ¬\  /  ¬|  ¬\  /  ¬\\n               /         \/     \/         \/         \/     \\n              /           \      \          \          \      \\n            _/             \_     \_  |      \_         \_     \_\n            \      \ /      /      /          / \ /      /      /\n             \      |      /      /   |      /   |      /      /\n              \_____|____ /_____ /____|____ /____|____ /_____ /\n          /\            \/     \/         \/         \/     \/\n_________/  \  /\___________> 5TH DYNASTY GHQ <____________________ ___ __ _\n             \/    ___ ___    _______    _______    _______\n                  /  ¬|  ¬\  /      ¬\  /      ¬\  /      ¬\\n                 /    |    \/         \/         \/         \\n                /           \    |     \          \          \\n              _/             \_     ___/\_  |      \_____     \_\n              \               /    /     /          / |        /\n               \      |      /          /   |      /  |       /\n                \_____|____ /_________ /____|____ /   |_____ /·cj·\n                          \/         \/         \/         \/\n \n                        aMiGa aNd PC 0-1 dAy wArEz\n \n                         SYSOP: SvEN tHE CREAToR\n                         COSYS: Mr.Return\n                                Cee Jay\n \n                   -<>- CaLL: +49-(0)30-742-4141 -<>-\n\n  =======================================================================\n@endnode\n','\n',char(10)),NULL,'auto-added',31522,7,0,NULL,NULL,'5d_nf022','scan',1780048358);
INSERT INTO door_catalog VALUES('5d_nf033','5D-NF033.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5D-NF033.LHA','5D-NewFiles','XIM','5D-NewFiles',NULL,'sTc/5D!','5D','______\     /__|      /___________\___  /___ \_____ \  _/   /     /__\   ____/  _ /_/   / _/   /  \___  /\    /__/ \____ \_  \/___  /|',replace('      _______   _______           _______   \n______\     /__|      /___________\___  /___\n\_____ \  _/   /     /__\   ____/  _ /_/   /\n_/   /  \___  /\    /__/ \____ \_  \/___  /|\n\ 5TH    / / /\ \_ / \    / _/  /  |   / / |\n|\______/___/_|\  /___\  /_____/___|____/Rpd\n`---------------\/-----\/------------------''\n     5D-NewFiles v0.33 coded by sTc/5D!\n            - Known bugs fixed -\n          - Design changed a bit -\n','\n',char(10)),'5D-NewFiles.Guide',replace('@DataBase 5D-NewFiles Documentation\n@Author sTc/5D\n@Index Documentation\n\nCopyright © 1994 SvEN tHE CREAToR of 5tH DyNASTY\n\n@Remark $VER: 5D-NewFiles v0.33 by sTc/5D\n@Remark AmigaGuide DataBase\n\n@node MAIN "5D-NewFiles Documentation © 1994 SvEN tHE CREAToR of 5tH DyNASTY"\n                                                              :\n                                                       :      ¦             \n                   ________________  __________________¦      |\n            _______\_______       /  \             /   |      |______\n           |  __   _/     /______/____\  _     _  /    ¦      |  __  |\n           |  \/  _\________    \_\  / \/       \/     _      |  \/  |\n           |______\        /     / \/   |       |      /      |______|\n                   \___________ /       |_______|_____/       |Rpd!\n                              \/                     /________|\n                         :           :                                     :\n            ____   :     ¦     :     ¦      · 5 · T · H ·            :     ¦\n  __________\  /___¦    _|__/\ ¦     |_______ _______________________¦     |\n  \______   \\//   |    \____ \|     |   _   \\_____      /       /  |     |\n   /     \   \/    ¦     |   \ \     |   /    \/   /_____/    _  /   ¦     |\n _/       \   \_____     |    \ \_   |   _     \_____   \_     \/_____     |\n \       _/    /   /     |     \     |   /      /   /    /     |     /     |\n  \__________ /__________|     |\ ___|__/_____ /_______ /______|___________|\n            \/           |     ¦ \/          \/       \/\n                         ¦     :     · D · Y · N · A · S · T · Y ·\n                         :\n\n                              (×· PrESENTS ·×)\n\n                         Code: SvEN tHE CREAToR/5D\n\n                  ----- --- -> 5D-NewFiles v0.33 <- --- -----\n\n                  Coded by SvEN tHE CREAToR of 5th Dynasty\n\n                           @{" Normal Documentation " Link Documentation}\n@endnode\n@node Documentation "5D-NewFiles Documentation"\n              _______________________________________________\n             |                                               |\n             | //                                            |\n             | /                                             |\n             |                                               |\n             |            @{" D e S C R I P T I O N " Link Description}           |\n             |                                               |\n             |           @{" I n S T A L L A T I O N " Link Installation}          |\n             |                                               |\n             |              @{" T o O L T Y P E S " Link Tooltypes}             |\n             |                                               |\n             |              @{" G r E E T I N G S " Link Greetings}             |\n             |                                               |\n             |                                             / |\n             |                                            // |\n             |_______________________________________________|\n\n@endnode\n@node Description "5D-NewFiles Description"\n5D-NewFiles has been coded by SvEN tHE CREAToR/5D!\n\n5D-NewFiles is a replacement for the normal file list commands\nof AmiExpress ''F'' and ''N''. It has many improvements like ANSI\ncolored lines, inserted lines, new date, hold level, random description\ncolor and many others.\n@endnode\n@node Installation "5D-NewFiles Installation"\nCopy all files which are in the ''BBS'' directory of the archive\ninto your bbs directory.\n\nContents of archive:\n===================\n\nBBS/ Commands/ BBSCmd/      F.info\n                            N.info\n     Doors/    5D-NewFiles/ 5D-NewFiles\n                            5D-NewFiles.info\n                            5D-NewFiles.Guide\n\n===================\n@endnode\n@node Greetings "5D-NewFiles Greetings"\nGreetings go to:\n\n         . Celator ........... Thank you for helping me with /X! .\n         : ByteAndi ............ For helping me to learn coding! :\n         | Snow ...................... Sing mehr lieder, leader! |\n         `------( And all other persons I''ve forgotten!!! )------''\n\n@endnode\n@node Tooltypes "Tooltypes of 5D-NewFiles.info"\n  5D-NewFiles.info   - This Icon contains the definitions and \n  ~~~~~~~~~~~~~~~~     defaults for 5D-NewFiles. @{" Colors " Link Colors}\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  LINE_INSERT=<MODE> - Tells 5D-NewFiles which default line will be\n                       inserted between files\n                       MODE:\n                       (1) = Normal Insert Line\n                       (2) = Empty Line\n                       (3) = File Number\n                       (4) = File Number in Normal Insert Line\n\n                       Example: LINE_INSERT=3\n\n  ANSI_COLOR=<MODE>  - Defines which Ansi mode should be used as default!\n                       MODE:\n                       (1) = Normal\n                       (2) = Random Desc Color\n                       (3) = Normal + Random Desc Color\n\n                       Example: ANSI_COLOR=2\n\n  NEW_DATE           - Tells 5D-NewFiles to show the new date as default.\n  USER_PREFS         - Tells 5D-NewFiles to let Users use their own\n                       preferences. If it is not present the users cannot\n                       use 5D-NewFiles Prefs and the defaults will be user\n                       for them.\n  INSERT_LINE=   >-------------===========-------------<\n                     - Defines the Insert Line.\n  INERT_LINE_COLOR=Blue\n                     - Defines the Insert Line''s Color. Default is Blue.\n  FILELENGTH_COLOR=Yellow\n                     - Defines the FileLength''s Color. Default is Yellow.\n  FAKE_COLOR=Red     - Defines the Fake Color. Default is Red.\n  CHECK_COLOR=Violett\n                     - Defines the Check Character Color. Default is\n                       Violett.\n  CURRENT_DATE_COLOR=Green\n                     - Defines the Current Date Color. Default is Green.\n  HOLD_LEVEL=250     - Defines the level at which a User can show the\n                       Hold directory.\n  FILE_HELP=BBS:Screens/Confs/FileHelp\n                     - Defines the custom File screen to be showed at ''F''.\n                       If you don''t want to have a File screen simply\n                       write ''FILE_HELP=-1''. If this command isn''t used\n                       5D-NewFiles will show BBS:Conf<x>/FileHelp.<Lang>.\n  NEW_HELP=BBS:Screens/Confs/NewHelp\n                     - Defines the File screen to show at ''N''.\n                       If no is inserted <Conf_Location>/FileHelp.txt will\n                       be showed\n  SHORT_FAKE_DESC    - Tells 5D-NewFiles that short Nuke Messies are used.\n\n                       Example: "ASTIDIDO.LHA P *OLD!*" instead of:\n                                "ASTIDIDO.LHA **OLD!**"\n@endnode\n@node Colors "Available Colors"\n  None      - ESC[0m\n  Red       - ESC[31m\n  Green     - ESC[32m\n  Yellow    - ESC[33m\n  Dark      - ESC[34m\n  Violett   - ESC[35m\n  Blue      - ESC[36m\n  White     - ESC[37m\n@endnode\n','\n',char(10)),NULL,'auto-added',23074,1,0,NULL,NULL,'5d_nf033','scan',1780048358);
INSERT INTO door_catalog VALUES('5d_ol001','5D-OL001.LZH','~/Code/amiexpress_doors/Archives/AmiExpress/5D-OL001.LZH','5D-Olm','XIM','5D-Olm',NULL,'sTc/5D','5D','\__   \  \/  /_|  |/___\ / ___/_/ |_\  \/  / |  |  \_/ _/__\  |  /  |___  \_   _/\_/ _/ |  |  ||  ||  \\_| /   |     ||   |  |  |',replace('5th______  ___  __  ___   _____  _. ___  ___\n\__   \  \/  /_|  |/___\ / ___/_/ |_\  \/  /\n |  |  \_/ _/__\  |  /  |___  \_   _/\_/ _/\n |  |  ||  ||  \\_| /   |     ||   |  |  |\n |  |  ||  ||  |\_| \_  |SNOW!||   |  |  |\n |_____||__||__|__|__|__|_____||___|  |__|\n-==[ 5D ]==========================[ 5D ]==-\n           5D-Olm v0.01 by sTc/5D\n           For AmiExpress v3.xx+!\n-==[ 5D ]==========================[ 5D ]==-\n','\n',char(10)),'5D-Olm.Guide',replace('@DataBase 5D-OlmDoc\n\nCopyright (c) 1993 SvEN tHE CREAToR of 5th Dynasty\n\n@Remark $VER: 5D-Olm v0.01\n@Remark AmigaGuide database for the 5D-Olm Documentation\n\n@node MAIN "5D-Olm Documentation (c)1994 SvEN tHE CREAToR of 5th Dynasty"\n\n    _5tH_______    ____   ___  _____  _______ _________    ___\n    \______ \  \__/  / \ |   |/     \|       |      \  \__/  /\n     |     \ \_ \/ _/ \ \|   |   _   |  _____|___ ___\_ \/ _/\n     |     / ||\  /|   \ \   |  /    |      \  |   |  |\  /|\n     |    /  || \/ |   |\ \  |  \_   |\____  | |   |  | \/ |\n     |   /   ||sNoW|   | \ \ |   |   |       | |   |  |    |\n     :       ::    :   : :\  :   :   :       : :   :  :    :\n     `-------''`----`---'' `---`---`---`-------'' `---''  `----''\n\n                        >>> 5D-Olm <<<\n\n                   Code: SvEN tHE CREAToR/5D\n\n----------------------------------------------------------------------------\n\n         >>> C·O·N·T·E·N·T·S  O·F  D·O·C·U·M·E·N·T·A·T·I·O·N <<<\n\n                         @{"      Introduction      " Link Cap01}\n                         @{"      Requirements      " Link Cap02}\n                         @{"      Installation      " Link Cap03}\n                         @{"       Greetings!       " Link Cap05}\n                         @{"   How to Contact me?   " Link Cap06}\n\n         ---------------------------------------------------------\n                   Complete Docs for 5D-Olm v0.01\n         ---------------------------------------------------------\n         The Documentation has been written by SvEN tHE CREAToR/5D\n\n@endnode\n@node Cap01 "Introduction"\n  =======================================================================\n  5D-Olm is a replacement for da normal ''OLM''-Command of AX.\n  It works like the one of AX, but AX doesn''t check if there\n  is any user in the node you write the message to. 5D-Olm does!\n  The user can only write two lines, but why not? If he wants to write\n  thousands of lines then he should write a message!\n  =======================================================================\n@endnode\n@node Cap02 "Requirements"\n  =======================================================================\n  To install 5D-Olm you must have the following things:\n\n  - an  Amiga Model (500/600/1000/1200/2000/2500/3000/4000/CDTV/CD³²)\n  - the installed Version of OS\2, OS\3 or higher\n    (Soft- or Hardware Version)\n  - AmiExpress V2.xx , v3.xx or higher. And surely S-Express hehe.\n\n  =======================================================================\n@endnode\n@node Cap03 "How to install 5D-Olm:"\n  =======================================================================\n  To install 5D-Olm you must have all Requirement which were\n  mentioned below. You need the following things.\n\n  ---------------------------------------------------\n    BBS: Commands/ BBSCmd/          OLM.info\n    BBS: Doors/    5D-Olm/          5D-Olm\n                                    5D-Olm.Guide\n  ---------------------------------------------------\n\n  Decruch the 5D-Olm Archive. Go to your ''Doors:'' Directory\n  and make a directory called ''5D-Olm''. Copy ''5D-Olm''\n  into the Directory. Go to your ''BBS:Commands/BBSCmd/'' Directory.\n  Copy ''OLM.info'' into it.\n  =======================================================================\n@endnode\n@node Cap05 "Greetings go to the following guys:"\n  =======================================================================\n\n          Thunder .. Hau den Telekotzern auf die Backen!\n          Rainman .................... Gogo, NRW Leader!\n          Starcam .......... Sorry, we''ve some problems!\n          Mad Førce .............. Man, leg endlich auf!\n          Snow ............... Jaja, kriegst Deine 5 DM!\n          Airworx .. 20 Chicken McNuggets, 3*Senf-Sauce!\n          Prophet ...... Ich ziehe um, wohne 5 mins weg!\n          Circuit Breaker ................ Doedeldiduuu!\n          Zector ................. AmigaE, yeaaah! Hehe!\n          Muad''Dib ............... Hope to see you soon!\n          Scan .............. We dream about your scape!\n          Steel .................. Wie''s gööööht''s Gott?\n          Earthquake ...... Kriege hunger auf Erdbeeren!\n          Haystack ........... Wie geht es Deiner Backe?\n\n  =======================================================================\n@endnode\n@node Cap06 "How to contact me:"\n  =======================================================================\n  _____  ___   __________  _____________  _____________ ___ ______  _____\n /     \|   \ |  |       |/     \____.  \|     |       |   |      |/     \\n|   |   |  \ \|  |___ ___|   |   |   |   |     |___ ___|___|      |   |   |\n|   |   |   \ \   ||   | |   |   |   | __|  \   ||   | |   |  \   |   |   |\n|       |   |\ \  ||   | |       |      \|   \__||   | |   |   \__|       |\n|   |   |   | \ \ ||   | |   |   |   |   |   /  ||   | |   |   /  |   |   |\n|   |   |   | |\  ||   | |   |   |   |   |  /   ||   | |   |  /   |   |   |\n|___|   |___| | \ ||___| |___|   |___|   |      ||___| |___|      |___|   |\n    |   |     |   |          |   |   |   |______|          |______|   |   |\n    |___|     |___|          |___|   |___|                            |___|\n \n                      5TH DYNASTY GHQ                     .__________.\n S                                                        |   WITH   |\n Y          COOOOOOL THE COOOOLEST THING FOR DA SUMMER    |   CODER  |\n S                                                        |CONFERENCE|\n O      THE FIRST 5 UPLOADERS GET A DISABLE FOR ONE MONTH ·¯¯¯¯¯¯¯¯¯¯·\n P\n :              36 HOURS ONLINE PER 1 1/2 DAYS !\n S\n N          GET 5TH DYNASTY RELEASES FOR FREEDOWNLOAD\n O\n W         +49-306-XXXXXX : NUP=XXXXXXX : SYSTEMPW=XXX\n  =======================================================================\n@endnode\n','\n',char(10)),NULL,'auto-added',23164,10,0,NULL,NULL,'5d_ol001','scan',1780048358);
INSERT INTO door_catalog VALUES('5d_pag28','5D-PAG28.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5D-PAG28.LHA','5D-Page','XIM','5D-Page',NULL,NULL,'5D',':5th\ ¬/:_\ ¬/__\ ¬/__\ ¬/__\ ¬/__\ ¬/:_::: :\  \\//| \\//  \\//  \\//· \\//  \\//| \:: :/·  \/ | ·\/   ·\/ | ·\// --\/   ·\/ | ·\:',replace('::::____::____::____::____::____::____:::::\n:5th\ ¬/:_\ ¬/__\ ¬/__\ ¬/__\ ¬/__\ ¬/:_:::\n:\  \\//| \\//  \\//  \\//· \\//  \\//| \::\n:/·  \/ | ·\/   ·\/ | ·\// --\/   ·\/ | ·\:\n//   |\__  \\ |  \\    \\___  \_   \\__  \\\n\_____/_____/_|___/_|___/_____/ |___/___cj/\n:::::::::::::::P:R:E:S:E:N:T:S:::::::::::::\n      5D - Page V2.81 f0r dA gReAT /X      \n','\n',char(10)),'5D-Page.guide',replace('@database 5D-PageDoc\n\nCopyright (c) 1993 SvEN tHE CREAToR / 5th Dynasty\n\n@Remark $VER: (August 18 1993, 20:29:14)\n@Remark AmigaGuide database for the 5D-Page Documentation\n\n@node MAIN "5D-Page Documentation (c)1993 SvEN tHE CREAToR of 5th Dynasty (August 18 1993, 20:29:14)"\n          ______    ______    ______    ______    ______    ______\n          \   ¬/    \   ¬/    \   ¬/    \   ¬/    \   ¬/    \   ¬/\n 5th ______\  /_ ____\  /______\  /______\  /______\  /______\  /_ ____\n    //     \\// |   \\\//     \\\//     \\\//     \\\//     \\\// |   \\\n   //       \/  |    \\/       \\/  |    \\/     ---\/       \\/  |    \\\n  /·         \___     ·\     |  ·\        ·\____    \\__      ·\___     ·\\n /·         | \        ·\    |   ·\ |      ·\        ·\ |      ·\        ·\\n \___________ /________ /____|___ /_|______ /________ / |______ /________ /\n            \/        \/        \/        \/        \/        \/    ·cj·\/\n\n                              >>> 5D-Page <<<\n\n                Code: SvEN tHE CREAToR/5D  GFX: Cee Jay/5D\n\n---------------------------------------------------------------------------- \n\n         >>> C·O·N·T·E·N·T·S  O·F  D·O·C·U·M·E·N·T·A·T·I·O·N <<<\n\n                         @{"      Introduction      " Link Cap01}\n                         @{"      Requirements      " Link Cap02}\n                         @{"      Installation      " Link Cap03}\n                         @{"       Greetings!       " Link Cap05}\n                         @{"   How to Contact me?   " Link Cap06}\n\n         ---------------------------------------------------------\n              Complete Docs for 5D-Page V2.81 [-5th Dynasty-]\n         ---------------------------------------------------------\n         The Documentation has been written by SvEN tHE CREAToR/5D.\n\n@endnode\n@node Cap01 "Introduction"\n  =======================================================================\n  5D-Page is a replacement for the normal Page SysOp Command\n  of AmiExpress ''O''.\n  =======================================================================\n@endnode\n@node Cap02 "Requirements"\n  =======================================================================\n  To install 5D-Page you must have the following things:\n\n    Programm     Location           Description\n    ----------   --------           -----------\n    5D-Page      Doors:5D-Page      Main program\n\n  - an  Amiga Model (500/600/1000/1200/2000/2500/3000/4000/CDTV/CD³²)\n  - the installed Version of OS\2, OS\3 or higher\n    (Soft- or Hardware Version)\n  - the installed .INFO Files in the directories.\n  - AmiExpress V2.xx , v3.xx or higher.\n\n  =======================================================================\n@endnode\n@node Cap03 "How to install 5D-Page"\n  =======================================================================\n  To install 5D-Page you must have all Requirement which were\n  mentioned below. You need the following things.\n\n  --------------------------\n    Doors:5D-Page (dir)\n      ^^^ 5D-Page\n    BBS:Commands/BBSCmd (dir)\n      ^^^ O.info\n  --------------------------\n\n  Decruch the 5D-Page Archive. Go to your ''Doors:'' Directory\n  and make a Directory called ''5D-Page''. Copy ''5D-Page''\n  into the Directory. Go to your ''BBS:Commands/BBSCmd'' Directory.\n  Copy ''O.info'' into it.\n  =======================================================================\n@endnode\n@node Cap05 "Greetings go to..."\n  =======================================================================\n\n           ···­­­> ALL MEMBERS OF 5TH DYNASTY <­­­···\n\n                           ByteAndi/Mst\n                            Celator/TT\n                           Executor/DCS\n                              FuZzY\n                           Mr.Return/AG\n\n      +-----------------------------------------------------+\n      : And all cool people who I know and all who know me! :\n      `-----------------------------------------------------''\n\n  =======================================================================\n@endnode\n@node Cap06 "How to contact me..."\n  =======================================================================\n\n    .     /\_________  ______/\  /\______    /\_________  ______/\   .\n    .    _\______   .\ \______/ _\____   \  _\______   .\ \______/   .\n    :   /   _/ _/    \\/     .\/   __|   .\/   _/ _/    \\/     .\   :\n    |  /    \  \      \\      \\   \__    \\   \  \      \\      \\  |\n    +--\_____\__\       \____ //_____|     \\___\__\       \____ //--+\n    :            \  ____/    \/      |______/       \  ____/    \/   :\n    .             \/                                 \/              .\n               ___.\n              /  .|___    _______/\    /\______    ___________/\\n             /   ||   \  _\_  ____/_  _\____   \  _\_  __      /\n            /         .\/      /   .\/   __|   .\/     \______/\n           /      _    \\    _/     \\   \__    \\         .\\n           \______|     \\_________  /_____|     \\_______ //\n                  |______/         \/      |______/       \/\n\n               ···­­­>   \%\ 5TH DYNASTY GHQ \%\   <­­­···\n\n                        SYSOP: SvEN tHE CREAToR\n                        COSYS: Mr.Return\n                               Cee Jay\n\n                    -<>- CaLL: +49-(0)30-742-4141 -<>-\n\n  =======================================================================\n@endnode\n','\n',char(10)),NULL,'auto-added',11306,1,0,NULL,NULL,'5d_pag28','scan',1780048358);
