INSERT INTO door_catalog VALUES('5d_qa001','5D_QA001.LZH','~/Code/amiexpress_doors/Archives/AmiExpress/5D_QA001.LZH','5D^QuickAnsi','XIM','LE-window6.12',NULL,'sTc/5D','5D','/_____ _ /  / /___ _ /\  _/_\  ___\  \  \ /  / //__   /  / //o \___  \\ \  \___ \\ /  / ./  /  /  /  //   \  \  \  \  \  \ .\',replace(' /\_______/\___/\____\/____ __________/\    \n/_____ _ /  / /___ _ /\  _/_\  ___\  \  \   \n  /  / //__   /  / //o \___  \\ \  \___ \\  \n /  / ./  /  /  /  //   \  \  \  \  \  \ .\ \n/____ /_____/__/__/ 5tH. \_____\__\  \_____\\nSk¡n\/   _ __ _ _/________\_ _ __ _         \n                / PrESENTS \\n >×·    5D^QuickAnsi v0.01 by sTc/5D    ·×<\n >×·  To be used instead of the normal  ·×<\n >×· Ansi questionary to make it faster ·×<\n >×·          and nicer looking         ·×<\n','\n',char(10)),'5D^QuickAnsi.Guide',replace('@DataBase 5D^QuickAnsi Documentation\n@Author sTc/5D\n@Index Documentation\n\nCopyright © 1994 SvEN tHE CREAToR of 5tH DyNASTY\n\n@Remark $VER: 5D^QuickAnsi v0.01 by sTc/5D\n@Remark AmigaGuide DataBase\n\n@node MAIN "5D^QuickAnsi Documentation © 1994 SvEN tHE CREAToR of 5tH DyNASTY"\n                                                              :\n                                                       :      ¦             \n                   ________________  __________________¦      |\n            _______\_______       /  \             /   |      |______\n           |  __   _/     /______/____\  _     _  /    ¦      |  __  |\n           |  \/  _\________    \_\  / \/       \/     _      |  \/  |\n           |______\        /     / \/   |       |      /      |______|\n                   \___________ /       |_______|_____/       |Rpd!\n                              \/                     /________|\n                         :           :                                     :\n            ____   :     ¦     :     ¦      · 5 · T · H ·            :     ¦\n  __________\  /___¦    _|__/\ ¦     |_______ _______________________¦     |\n  \______   \\//   |    \____ \|     |   _   \\_____      /       /  |     |\n   /     \   \/    ¦     |   \ \     |   /    \/   /_____/    _  /   ¦     |\n _/       \   \_____     |    \ \_   |   _     \_____   \_     \/_____     |\n \       _/    /   /     |     \     |   /      /   /    /     |     /     |\n  \__________ /__________|     |\ ___|__/_____ /_______ /______|___________|\n            \/           |     ¦ \/          \/       \/\n                         ¦     :     · D · Y · N · A · S · T · Y ·\n                         :\n\n                              (×· PrESENTS ·×)\n\n                ----- --- -> 5D^QuickAnsi v0.01 <- --- -----\n\n                  Coded by SvEN tHE CREAToR of 5th Dynasty\n\n                           @{" Normal Documentation " Link Documentation}\n@endnode\n@node Documentation "5D^QuickAnsi Documentation"\n              _______________________________________________\n             |                                               |\n             | //                                            |\n             | /                                             |\n             |                                               |\n             |            @{" D e S C R I P T I O N " Link Description}           |\n             |                                               |\n             |           @{" I n S T A L L A T I O N " Link Installation}          |\n             |                                               |\n             |              @{" G r E E T I N G S " Link Greetings}             |\n             |                                               |\n             |                                             / |\n             |                                            // |\n             |_______________________________________________|\n\n@endnode\n@node Description "5D^QuickAnsi Description"\n5D^QuickAnsi has been coded by SvEN tHE CREAToR/5D!\n\nIt is programmed to be used instead of the normal ansi\nquastionary to make it more funny & faster cauz you only\nneed to press ONE digit to get in instead of f.e. ''N Q<CR>''.\nAlso I inserted the feature of using cursor keys to choose\none of the four possibilities.\n\nSpecial feature:\n\n - It is fully multientrant and able to be made resident\n\n@endnode\n@node Installation "5D^QuickAnsi Installation"\nCopy all files which are in the ''BBS'' directory of the archive\ninto your bbs directory.\n\nContents of archive:\n===================\n\nBBS/ Commands/ SysCmd/       ANSI.info\n     Doors/    5D^QuickAnsi/ 5D^QuickAnsi\n                             5D^QuickAnsi.info\n                             5D^QuickAnsi.Guide\n\n===================\n\n      If you want to make it resident then simply type the\n      following into your User-StartUp and copy the\n      ANSI_RESIDENT.info to BBS:Commands/SysCmd/ANSI.info!\n\nResident >NIL: 5D^QuickAnsi Doors:5D^QuickAnsi/5D^QuickAnsi FORCE\n\n@endnode\n@node Greetings "5D^QuickAnsi Greetings"\nGreetings go to:\n\n         . Celator ........... Thank you for helping me with /X! .\n         : ByteAndi ............ For helping me to learn coding! :\n         | Prophet .................... For being a nice friend! |\n         | Snow ...................... Sing mehr lieder, leader! |\n         | Airworx ................. Continue work as Co Leader! |\n         | Mad Doc ................. Can you catch sNoW again??? |\n         `------( And all other persons I''ve forgotten!!! )------''\n\n@endnode\n','\n',char(10)),NULL,'auto-added',10826,4,0,NULL,NULL,'5d_qa001','scan',1780048365);
INSERT INTO door_catalog VALUES('5d_qa005','5D^QA005.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5D^QA005.LHA','5D^QuickAnsi','XIM','5D^QuickAnsi',NULL,'sTc/5D!',NULL,'______\     /__|      /___________\___  /___ \_____ \  _/   /     /__\   ____/  _ /_/   / _/   /  \___  /\    /__/ \____ \_  \/___  /|',replace('      _______   _______           _______   \n______\     /__|      /___________\___  /___\n\_____ \  _/   /     /__\   ____/  _ /_/   /\n_/   /  \___  /\    /__/ \____ \_  \/___  /|\n\ 5TH    / / /\ \_ / \    / _/  /  |   / / |\n|\______/___/_|\  /___\  /_____/___|____/Rpd\n`---------------\/-----\/------------------''\n     5D^QuickAnsi v0.05 coded by sTc/5D!\n        - Memory allocate bug fixed -\n','\n',char(10)),'5D^QuickAnsi.Guide',replace('@DataBase 5D^QuickAnsi Documentation\n@Author sTc/5D\n@Index Documentation\n\nCopyright © 1994 SvEN tHE CREAToR of 5tH DyNASTY\n\n@Remark $VER: 5D^QuickAnsi v0.05 by sTc/5D\n@Remark AmigaGuide DataBase\n\n@node MAIN "5D^QuickAnsi Documentation © 1994 SvEN tHE CREAToR of 5tH DyNASTY"\n                                                              :\n                                                       :      ¦             \n                   ________________  __________________¦      |\n            _______\_______       /  \             /   |      |______\n           |  __   _/     /______/____\  _     _  /    ¦      |  __  |\n           |  \/  _\________    \_\  / \/       \/     _      |  \/  |\n           |______\        /     / \/   |       |      /      |______|\n                   \___________ /       |_______|_____/       |Rpd!\n                              \/                     /________|\n                         :           :                                     :\n            ____   :     ¦     :     ¦      · 5 · T · H ·            :     ¦\n  __________\  /___¦    _|__/\ ¦     |_______ _______________________¦     |\n  \______   \\//   |    \____ \|     |   _   \\_____      /       /  |     |\n   /     \   \/    ¦     |   \ \     |   /    \/   /_____/    _  /   ¦     |\n _/       \   \_____     |    \ \_   |   _     \_____   \_     \/_____     |\n \       _/    /   /     |     \     |   /      /   /    /     |     /     |\n  \__________ /__________|     |\ ___|__/_____ /_______ /______|___________|\n            \/           |     ¦ \/          \/       \/\n                         ¦     :     · D · Y · N · A · S · T · Y ·\n                         :\n\n                              (×· PrESENTS ·×)\n\n                ----- --- -> 5D^QuickAnsi v0.05 <- --- -----\n\n                  Coded by SvEN tHE CREAToR of 5th Dynasty\n\n                           @{" Normal Documentation " Link Documentation}\n@endnode\n@node Documentation "5D^QuickAnsi Documentation"\n              _______________________________________________\n             |                                               |\n             | //                                            |\n             | /                                             |\n             |                                               |\n             |            @{" D e S C R I P T I O N " Link Description}           |\n             |                                               |\n             |           @{" I n S T A L L A T I O N " Link Installation}          |\n             |                                               |\n             |              @{" G r E E T I N G S " Link Greetings}             |\n             |                                               |\n             |                                             / |\n             |                                            // |\n             |_______________________________________________|\n\n@endnode\n@node Description "5D^QuickAnsi Description"\n5D^QuickAnsi has been coded by SvEN tHE CREAToR/5D!\n\nIt is programmed to be used instead of the normal ansi\nquastionary to make it more funny & faster cauz you only\nneed to press ONE digit to get in instead of f.e. ''N Q<CR>''.\nAlso I inserted the feature of using cursor keys to choose\none of the four possibilities.\n\nSpecial feature:\n\n - It is fully multientrant and able to be made resident\n\nFixed:\n\n - Now the sysop can logon with automatically passing the\n   Ansi questionary\n\n - If there was a hangup at the choose question the door has hang up\n\n@endnode\n@node Installation "5D^QuickAnsi Installation"\nCopy all files which are in the ''BBS'' directory of the archive\ninto your bbs directory.\n\nContents of archive:\n===================\n\nBBS/ Commands/ SysCmd/       ANSI.info\n     Doors/    5D^QuickAnsi/ 5D^QuickAnsi\n                             5D^QuickAnsi.info\n                             5D^QuickAnsi.Guide\n\n===================\n\n      If you want to make it resident then simply type the\n      following into your User-StartUp and copy the\n      ANSI_RESIDENT.info to BBS:Commands/SysCmd/ANSI.info!\n\nResident >NIL: 5D^QuickAnsi Doors:5D^QuickAnsi/5D^QuickAnsi FORCE\n\n@endnode\n@node Greetings "5D^QuickAnsi Greetings"\nGreetings go to:\n\n         . Celator ........... Thank you for helping me with /X! .\n         : ByteAndi ............ For helping me to learn coding! :\n         | Snow ...................... Sing mehr lieder, leader! |\n         `------( And all other persons I''ve forgotten!!! )------''\n\n@endnode\n','\n',char(10)),NULL,'auto-added',6961,1,0,NULL,NULL,'5d_qa005','scan',1780048365);
INSERT INTO door_catalog VALUES('5d_rsrv1','5D-RSRV1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5D-RSRV1.LHA','5D-Reserve','XIM','5D-Reserve',NULL,'SvEN','5D','5 \____\   / \     \____\   __/     /  /   \ T/   / \__   \  T  \  / \___ \   \/___    / H/   /   \     \ |   \    \ /  \   \      /',replace('  ____________________/\___________________\n5 \____\   / \     \____\   __/     /  /   \\n T/   / \__   \  T  \  / \___ \   \/___    /\nH/   /   \     \ |   \    \ /  \   \      /\n/________/     /_|    \/   \____\___\    /\n[===/_________/==|____/_____\RpD!/______/==]\n5D-Reserve V1.00 Written by SvEN tHE CREAToR\nAllows the Sysop to reserve his bbs for a\nspecific user.\n','\n',char(10)),'5D-Reserve.guide',replace('@database 5D-ReserveDoc\n@Author SvEN tHE CREAToR ·OF· 5TH DYNASTY\n@Index MAIN\n\nCopyright (c) 1993 SvEN tHE CREAToR / 5th Dynasty\n\n@Remark $VER: (November 6 1993, 18:00:00)\n@Remark AmigaGuide database for the 5D-Reserve Documentation\n\n@node MAIN "5D-Reserve Documentation (c)1993 SvEN tHE CREAToR of 5th Dynasty (November 6 1993, 18:00:00)"\n          ______    ______    ______    ______    ______    ______\n          \   ¬/    \   ¬/    \   ¬/    \   ¬/    \   ¬/    \   ¬/\n 5th ______\  /_ ____\  /______\  /______\  /______\  /______\  /_ ____\n    //     \\// |   \\\//     \\\//     \\\//     \\\//     \\\// |   \\\n   //       \/  |    \\/       \\/  |    \\/     ---\/       \\/  |    \\\n  /·         \___     ·\     |  ·\        ·\____    \\__      ·\___     ·\\n /·         | \        ·\    |   ·\ |      ·\        ·\ |      ·\        ·\\n \___________ /________ /____|___ /_|______ /________ / |______ /________ /\n            \/        \/        \/        \/        \/        \/    ·cj·\/\n\n                           >>> 5D-Reserve <<<\n\n                   Code & Design: SvEN tHE CREAToR/5D\n\n---------------------------------------------------------------------------- \n\n         >>> C·O·N·T·E·N·T·S  O·F  D·O·C·U·M·E·N·T·A·T·I·O·N <<<\n\n                  IT HAS BEEN OPTIMIZED AND THE WRONG ACCESS\n                  CHECK ROUTINE HAS BEEN CORRECTED!\n\n                         @{"      Introduction      " Link Cap01}\n                         @{"      Requirements      " Link Cap02}\n                         @{"      Installation      " Link Cap03}\n                         @{"     Configuration!     " Link Cap04}\n                         @{"       Greetings!       " Link Cap05}\n                         @{"   How to Contact me?   " Link Cap06}\n\n         ---------------------------------------------------------\n              Complete Docs for 5D-Reserve V1.00 [-5th Dynasty-]\n         ---------------------------------------------------------\n         The Documentation has been written by SvEN tHE CREAToR/5D.\n\n@endnode\n@node Cap01 "Introduction"\n  =======================================================================\n  5D-Reserve is a tool which allows the sysop to reserve his bbs for\n  some special guys. You need it for example if you want to release\n  some tools of a group and only the traders shall come in. So you\n  can insert there name in ''Doors:5D-Reserve/5D-Reserve.cfg'' if you\n  want to reserve all nodes. If ya only want One node or more reserved\n  you only need to write it in ''5D-Reserve.cfg_1'' for node 1 for example.\n  There are two example cfgs in this archive! You need to start this door\n  by MCI Command. I installed it at the LogOn-Command. An example .txt\n  is in this archive! You can simply write your own BBS Logo into it but\n  don''t forget to have the ''~|'' at the beginning for showing /X that\n  it is an MCI Message. Ok! Enough now! Simply install it and ENJOY IT!\n  =======================================================================\n@endnode\n@node Cap02 "Requirements"\n  =======================================================================\n  To install 5D-Reserve you must have the following things:\n\n    Programm     Location           Description\n    ----------   --------           -----------\n    5D-Reserve   Doors:5D-Reserve   Main program\n\n  - an  Amiga Model (500/600/1000/1200/2000/2500/3000/4000/CDTV/CD³²)\n  - the installed Version of OS\2, OS\3 or higher\n    (Soft- or Hardware Version)\n  - the installed .INFO Files in the directories.\n  - AmiExpress v3.xx or higher.\n\n  =======================================================================\n@endnode\n@node Cap03 "How to install 5D-Reserve"\n  =======================================================================\n  To install 5D-Reserve you must have all Requirement which were\n  mentioned below. You need the following things.\n\n  --------------------------\n    Doors:5D-Reserve (dir)\n      ^^^ 5D-Reserve\n      ^^^ 5D-Reserve.cfg   (If ya want to reserve the BBS generally)\n      ^^^ 5D-Reserve.cfg_0 (If ya want to reserve node 0)\n    BBS:Commands/SysCmd (dir)\n      ^^^ 5D-Reserve.info\n  --------------------------\n\n  Decruch the 5D-Reserve Archive. Go to your ''Doors:'' Directory\n  and make a Directory called ''5D-Reserve''. Copy ''5D-Reserve''\n  into the Directory. Go to your ''BBS:Commands/SysCmd'' Directory.\n  Copy ''Reserve.info'' into it.\n  =======================================================================\n@endnode\n@node Cap04 "5D-Reserve.cfg ..."\n  =======================================================================\n  You only need to write the user names of the ones you want to be able\n  to login in ''Doors:5D-Reserve/5D-Reserve.cfg'' or if ya want to reserve\n  one special node: ''Doors:5D-Reserve/5D-Reserve.cfg_<NODE>''. EXAMPLE:\n\n  ~~~~~~~~~~~CUT HERE~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n  SnOw\n  Sven the Creator\n  Delta-X\n  Wolfgang\n  Thunder\n  Airworx\n  Prophet\n  Beagle\n  Frank Maxwell\n  ~~~~~~~~~~~CUT HERE~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n  =======================================================================\n@endnode\n@node Cap05 "Greetings go to..."\n  =======================================================================\n\n                        GREETS GO TO:\n\n    ByteAndi/MST ......................... For helping me!\n    Strider/PGS .................... Hope we''ll chat soon!\n    Mr.Return/AG ............................ Good friend!\n    Crayor/SCX ................. I willmake the multichat!\n\n              >>> ALL MEMBERS OF 5TH DYNASTY!!! <<<\n\n  =======================================================================\n@endnode\n@node Cap06 "How to contact me..."\n  =======================================================================\n    ___________________________   ___________   ___________________________\n   /\_______________________ _ \¡/           \¡/  _ ______________________/\\n   \/                            ·5TH DYNASTY·                            \/\n    ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\_______________/¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n    CELTIC CROSS ............... Thunder ...... +49-(0)30-******* ..... WHQ\n    MIAMI HEAT ........ Sven The Creator ...... +49-(0)30-7424141 ..... GHQ\n    HOUSE OF BRAIN ............. Delta-X ...... +49-(0)3328472023 ..... GHQ\n    POWER BOX II NODE 0 ....... Wolfgang ...... +49-(0)30-******* ..... GHQ\n    POWER BOX II NODE 1 ....... Wolfgang ...... +49-(0)30-******* ..... GHQ\n    POWER BOX III ........ Frank Maxwell ...... +49-(0)30-4167884 ..... GHQ\n    5TH DYNASTY CLUB .............. Snow ...... +49-(0)30-******* ..... GHQ\n\n                 ___ ___    ___    _______    ___ ___    ___\n                /  ¬|  ¬\  /  ¬\  /      ¬\  /  ¬|  ¬\  /  ¬\\n               /         \/     \/         \/         \/     \\n              /           \      \          \          \      \\n            _/             \_     \_  |      \_         \_     \_\n            \      \ /      /      /          / \ /      /      /\n             \      |      /      /   |      /   |      /      /\n              \_____|____ /_____ /____|____ /____|____ /_____ /\n          /\            \/     \/         \/         \/     \/\n_________/  \  /\___________> 5TH DYNASTY GHQ <____________________ ___ __ _\n             \/    ___ ___    _______    _______    _______\n                  /  ¬|  ¬\  /      ¬\  /      ¬\  /      ¬\\n                 /    |    \/         \/         \/         \\n                /           \    |     \          \          \\n              _/             \_     ___/\_  |      \_____     \_\n              \               /    /     /          / |        /\n               \      |      /          /   |      /  |       /\n                \_____|____ /_________ /____|____ /   |_____ /·cj·\n                          \/         \/         \/         \/\n \n                         SYSOP: SvEN tHE CREAToR/5D\n                         COSYS: Airworx/5D\n                                Mr.Return/AG\n \n                   -<>- CaLL: +49-(0)30-742-4141 -<>-\n\n  =======================================================================\n@endnode\n','\n',char(10)),NULL,'auto-added',17916,3,0,NULL,NULL,'5d_rsrv1','scan',1780048358);
INSERT INTO door_catalog VALUES('5d_se001','5D-SE001.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5D-SE001.LHA','IfNotLeftMouseThen','XIM','5D-Selector',NULL,'sTc','5D','\__   \  \/  /_|  |/___\ / ___/_/ |_\  \/  / |  |  \_/ _/__\  |  /  |___  \_   _/\_/ _/ |  |  ||  ||  \\_| /   |     ||   |  |  |',replace('5th______  ___  __  ___   _____  _. ___  ___\n\__   \  \/  /_|  |/___\ / ___/_/ |_\  \/  /\n |  |  \_/ _/__\  |  /  |___  \_   _/\_/ _/\n |  |  ||  ||  \\_| /   |     ||   |  |  |\n |  |  ||  ||  |\_| \_  |SNOW!||   |  |  |\n |_____||__||__|__|__|__|_____||___|  |__|\n.---------------- Presents ----------------.\n| 5D-Selector v0.01 by sTc - No /X-Tool :) |\n|  Lets you start tools by simply pressing |\n|     - on some nice colored buttons!      |\n`----------- 5th Dynasty r0oLZ! -----------''\n','\n',char(10)),'5D-Selector.Guide',replace('@DataBase 5D-Selector_Doc\n\nCopyright (c) 1994 SvEN tHE CREAToR of 5th Dynasty\n\n@Remark $VER: 5D-Selector v0.01\n@Remark AmigaGuide database for the 5D-Selector Documentation\n\n@node MAIN "5D-Selector Documentation (c)1994 SvEN tHE CREAToR of 5th Dynasty"\n\n    _5tH_______    ____   ___  _____  _______ _________    ___\n    \______ \  \__/  / \ |   |/     \|       |      \  \__/  /\n     |     \ \_ \/ _/ \ \|   |   _   |  _____|___ ___\_ \/ _/\n     |     / ||\  /|   \ \   |  /    |      \  |   |  |\  /|\n     |    /  || \/ |   |\ \  |  \_   |\____  | |   |  | \/ |\n     |   /   ||sNoW|   | \ \ |   |   |       | |   |  |    |\n     :       ::    :   : :\  :   :   :       : :   :  :    :\n     `-------''`----`---'' `---`---`---`-------'' `---''  `----''\n\n                            >>> 5D-Selector <<<\n\n                         Code: SvEN tHE CREAToR/5D\n\n---------------------------------------------------------------------------- \n\n         >>> C·O·N·T·E·N·T·S  O·F  D·O·C·U·M·E·N·T·A·T·I·O·N <<<\n\n                         @{"      Introduction      " Link Cap01}\n                         @{"      Requirements      " Link Cap02}\n                         @{"       Greetings!       " Link Cap05}\n                         @{"   How to Contact me?   " Link Cap06}\n\n         ---------------------------------------------------------\n                   Complete Docs for 5D-Selector v0.01\n         ---------------------------------------------------------\n         The Documentation has been written by SvEN tHE CREAToR/5D\n\n@endnode\n@node Cap01 "Introduction"\n  =======================================================================\n  Oehm............................ YO! 5D-Selector is NO AX-Tools (Yes,\n  right! NO AX-TOOL 8^-) It is a tool which opens a Screen (boahhhhhh)\n  and then shows you some buttons which you can click on until you get\n  an or(ups). You can specify for any button which program/script/suelz\n  should be started if you click on this nice button. To start 5D-Selector\n  you have to add one argument, example: 5D-Selector 5D-Selector.Script1\n  Try that! The script file looks like this:\n\n############ CUT ############\nButton Name\nProgram\nButton Name\nProgram\nButton Name\nProgram\n...\n...\n############ CUT ############\n\n                         .--------------.\n                         | Bonus Part I |\n                         `--------------''\n\n  I programmed some other tools especially for you. If you wanna get\n  started 5D-Selector while you reboot your machine and simply press\n  the left mouse button while the hd lights are blinking you only have\n  to insert this to your User-StartUp:\n\n  IfLeftMouseThen Work:Tools/5D-Selector Work:Tools/5D-Selector.Script1\n\n  Sure, you''ve to put the IfXXXXXMouseThen(s) into the C: directory\n  or anywhere else.\n\n                         .---------------.\n                         | Bonus Part II |\n                         `---------------''\n\n  I decided to spread my sources with this archive, so you can see that\n  I''ve no backdoors in my tools... smile\n\n  IfLeftMouseThen.e\n  IfRightMouseThen.e\n  IfNotLeftMouseThen.e\n\n  =======================================================================\n@endnode\n@node Cap02 "Requirements"\n  =======================================================================\n  To install 5D-Selector you must have the following things:\n\n  - an A5200\n  - the installed Version of OS\4 or higher\n    (Soft-, Middle- or Hardware Version)\n  - a hard disk with atleast 2,4GB of free space\n  - a 34" Monitor\n  - a Picasso 48 Bit Graphic Card\n\n  =======================================================================\n@endnode\n@node Cap05 "Greetings go to the following guys:"\n  =======================================================================\n\n          Thunder ............. Hmmmmmmmmmmmmmmmmmmmmmm!\n          Rainman ................. Und da isser wieder!\n          Starcam ...................... Doedel di duuu!\n          Mad Førce ......................... Summ summ!\n          Snow .................... Bloek, meckerfritze!\n          Airworx .... Und sie callen und callen und...!\n          Prophet .. Ich möchte mein C-Buch zurueck 8^-)\n          Zector .............................. Byr-573!\n          Maverick ........ The tool is nearly finished!\n          Earthquake .................. Na, du Erdbeere!\n\n  =======================================================================\n@endnode\n@node Cap06 "How to contact me:"\n  =======================================================================\n  _____  ___   __________  _____________  _____________ ___ ______  _____\n /     \|   \ |  |       |/     \____.  \|     |       |   |      |/     \\n|   |   |  \ \|  |___ ___|   |   |   |   |     |___ ___|___|      |   |   |\n|   |   |   \ \   ||   | |   |   |   | __|  \   ||   | |   |  \   |   |   |\n|       |   |\ \  ||   | |       |      \|   \__||   | |   |   \__|       |\n|   |   |   | \ \ ||   | |   |   |   |   |   /  ||   | |   |   /  |   |   |\n|   |   |   | |\  ||   | |   |   |   |   |  /   ||   | |   |  /   |   |   |\n|___|   |___| | \ ||___| |___|   |___|   |      ||___| |___|      |___|   |\n    |   |     |   |          |   |   |   |______|          |______|   |   |\n    |___|     |___|          |___|   |___|                            |___|\n \n                      5TH DYNASTY GHQ                     .__________.\n S                                                        |   WITH   |\n Y          COOOOOOL THE COOOOLEST THING FOR DA SUMMER    |   CODER  |\n S                                                        |CONFERENCE|\n O      THE FIRST 5 UPLOADERS GET A DISABLE FOR ONE MONTH ·¯¯¯¯¯¯¯¯¯¯·\n P\n :              36 HOURS ONLINE PER 1 1/2 DAYS !\n S\n N          GET 5TH DYNASTY RELEASES FOR FREEDOWNLOAD\n O\n W         +49-306-XXXXXX : NUP=XXXXXXX : SYSTEMPW=XXX\n  =======================================================================\n@endnode\n','\n',char(10)),NULL,'auto-added',8085,1,0,NULL,NULL,'5d_se001','scan',1780048358);
INSERT INTO door_catalog VALUES('5d_se010','5D^SE010.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5D^SE010.LHA','5D-Security','XIM','5D-Security',NULL,NULL,NULL,'______  __  / ____  \___  \  _____  ___  / \/  /  /  /  /  /  /  ¬  /\_  \ /  //  /  / /  /  /\__  /  /  /  /  /  /  //  /_\__  /',replace('5tH_/\____/\_ __/\__ _/\__ _/\_____/\__/\_ _\n______  __  / ____  \___  \  _____  ___  /\n \/  /  /  /  /  /  /  ¬  /\_  \ /  //  /  /\n /  /  /\__  /  /  /  /  /  /  //  /_\__  /\n/___  /___  /__/  /__/  /___  //  //___  /__\n____ /_ __ /____ /____ / ___ /__ /_ ___ //\nbIS\/    \/    \/    \/    \/  \/     \/\nSecurity Ckecker\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 18:52:26  ON NODE: 1\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',88274,7,0,NULL,NULL,'5d_se010','scan',1780048365);
INSERT INTO door_catalog VALUES('5d_sm001','5D-SM001.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5D-SM001.LHA','5D-SendMessage','XIM','5D-SendMessage',NULL,NULL,'5D','______\     /__|      /___________\___  /___ \_____ \  _/   /     /__\   ____/  _ /_/   / _/   /  \___  /\    /__/ \____ \_  \/___  /|',replace('      _______   _______           _______   \n______\     /__|      /___________\___  /___\n\_____ \  _/   /     /__\   ____/  _ /_/   /\n_/   /  \___  /\    /__/ \____ \_  \/___  /|\n\ 5th    / / /\ \_ / \    / _/  /  |   / / |\n|\______/___/_|\  /___\  /_____/___|____/rpd\n`---------------\/-----\/------------------''\n5D-SendMessage V0.01 [-5th Dynasty-]\nAllows the users to send messages to nodes\n','\n',char(10)),'5D-SendMessage.guide',replace('@database 5D-SendMessageDoc\n@Author SvEN tHE CREAToR ·OF· 5TH DYNASTY\n@Index MAIN\n\nCopyright (c) 1993 SvEN tHE CREAToR / 5th Dynasty\n\n@Remark $VER: (November 6 1993, 18:00:00)\n@Remark AmigaGuide database for the 5D-SendMessage Documentation\n\n@node MAIN "5D-SendMessage Documentation (c)1993 SvEN tHE CREAToR of 5th Dynasty (November 6 1993, 18:00:00)"\n          ______    ______    ______    ______    ______    ______\n          \   ¬/    \   ¬/    \   ¬/    \   ¬/    \   ¬/    \   ¬/\n 5th ______\  /_ ____\  /______\  /______\  /______\  /______\  /_ ____\n    //     \\// |   \\\//     \\\//     \\\//     \\\//     \\\// |   \\\n   //       \/  |    \\/       \\/  |    \\/     ---\/       \\/  |    \\\n  /·         \___     ·\     |  ·\        ·\____    \\__      ·\___     ·\\n /·         | \        ·\    |   ·\ |      ·\        ·\ |      ·\        ·\\n \___________ /________ /____|___ /_|______ /________ / |______ /________ /\n            \/        \/        \/        \/        \/        \/    ·cj·\/\n\n                           >>> 5D-SendMessage <<<\n\n                   Code & Design: SvEN tHE CREAToR/5D\n\n---------------------------------------------------------------------------- \n\n         >>> C·O·N·T·E·N·T·S  O·F  D·O·C·U·M·E·N·T·A·T·I·O·N <<<\n\n                         @{"      Introduction      " Link Cap01}\n                         @{"      Requirements      " Link Cap02}\n                         @{"      Installation      " Link Cap03}\n                         @{"       Greetings!       " Link Cap05}\n                         @{"   How to Contact me?   " Link Cap06}\n\n         ---------------------------------------------------------\n              Complete Docs for 5D-SendMessage V0.01 [-5th Dynasty-]\n         ---------------------------------------------------------\n         The Documentation has been written by SvEN tHE CREAToR/5D.\n\n@endnode\n@node Cap01 "Introduction"\n  =======================================================================\n  5D-SendMessage is a tool which allows the users to write messages\n  to other nodes.\n  =======================================================================\n@endnode\n@node Cap02 "Requirements"\n  =======================================================================\n  To install 5D-SendMessage you must have the following things:\n\n    Programm     Location           Description\n    ----------   --------           -----------\n    5D-SendMessage   Doors:5D-SendMessage   Main program\n\n  - an  Amiga Model (500/600/1000/1200/2000/2500/3000/4000/CDTV/CD³²)\n  - the installed Version of OS\2, OS\3 or higher\n    (Soft- or Hardware Version)\n  - the installed .INFO Files in the directories.\n  - AmiExpress v3.xx or higher.\n\n  =======================================================================\n@endnode\n@node Cap03 "How to install 5D-SendMessage"\n  =======================================================================\n  To install 5D-SendMessage you must have all Requirement which were\n  mentioned below. You need the following things.\n\n  --------------------------\n    Doors:5D-SendMessage (dir)\n      ^^^ 5D-SendMessage\n    BBS:Commands/BBSCmd (dir)\n      ^^^ Send.info\n  --------------------------\n\n  Decruch the 5D-SendMessage Archive. Go to your ''Doors:'' Directory\n  and make a Directory called ''5D-SendMessage''. Copy ''5D-SendMessage''\n  into the Directory. Go to your ''BBS:Commands/BBSCmd'' Directory.\n  Copy ''Send.info'' into it.\n  =======================================================================\n@endnode\n@node Cap05 "Greetings go to..."\n  =======================================================================\n\n                        GREETS GO TO:\n\n    ByteAndi/MST ......................... For helping me!\n    Strider/PGS .................... Hope we''ll chat soon!\n    Mr.Return/AG ............................ Good friend!\n    Crayor/SCX ................. I willmake the multichat!\n\n              >>> ALL MEMBERS OF 5TH DYNASTY!!! <<<\n\n  =======================================================================\n@endnode\n@node Cap06 "How to contact me..."\n  =======================================================================\n    ___________________________   ___________   ___________________________\n   /\_______________________ _ \¡/           \¡/  _ ______________________/\\n   \/                            ·5TH DYNASTY·                            \/\n    ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\_______________/¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n    CELTIC CROSS ............... Thunder ...... +49-(0)30-******* ..... WHQ\n    MIAMI HEAT ........ Sven The Creator ...... +49-(0)30-7424141 ..... GHQ\n    HOUSE OF BRAIN ............. Delta-X ...... +49-(0)3328472023 ..... GHQ\n    POWER BOX II NODE 0 ....... Wolfgang ...... +49-(0)30-******* ..... GHQ\n    POWER BOX II NODE 1 ....... Wolfgang ...... +49-(0)30-******* ..... GHQ\n    POWER BOX III ........ Frank Maxwell ...... +49-(0)30-4167884 ..... GHQ\n    5TH DYNASTY CLUB .............. Snow ...... +49-(0)30-******* ..... GHQ\n\n                 ___ ___    ___    _______    ___ ___    ___\n                /  ¬|  ¬\  /  ¬\  /      ¬\  /  ¬|  ¬\  /  ¬\\n               /         \/     \/         \/         \/     \\n              /           \      \          \          \      \\n            _/             \_     \_  |      \_         \_     \_\n            \      \ /      /      /          / \ /      /      /\n             \      |      /      /   |      /   |      /      /\n              \_____|____ /_____ /____|____ /____|____ /_____ /\n          /\            \/     \/         \/         \/     \/\n_________/  \  /\___________> 5TH DYNASTY GHQ <____________________ ___ __ _\n             \/    ___ ___    _______    _______    _______\n                  /  ¬|  ¬\  /      ¬\  /      ¬\  /      ¬\\n                 /    |    \/         \/         \/         \\n                /           \    |     \          \          \\n              _/             \_     ___/\_  |      \_____     \_\n              \               /    /     /          / |        /\n               \      |      /          /   |      /  |       /\n                \_____|____ /_________ /____|____ /   |_____ /·cj·\n                          \/         \/         \/         \/\n \n                         SYSOP: SvEN tHE CREAToR/5D\n                         COSYS: Airworx/5D\n                                Mr.Return/AG\n \n                   -<>- CaLL: +49-(0)30-742-4141 -<>-\n\n  =======================================================================\n@endnode\n','\n',char(10)),NULL,'auto-added',14281,3,0,NULL,NULL,'5d_sm001','scan',1780048358);
INSERT INTO door_catalog VALUES('5d_sm050','5D-SM050.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5D-SM050.LHA','5D-SendMessage','XIM','5D-SendMessage',NULL,'SvEN','5D','______\     /__|      /___________\___  /___ \_____ \  _/   /     /__\   ____/  _ /_/   / _/  _/  \___  /\    /__/ \____ \_  \/___  /|',replace('      _______   _______           _______   \n______\     /__|      /___________\___  /___\n\_____ \  _/   /     /__\   ____/  _ /_/   /\n_/  _/  \___  /\    /__/ \____ \_  \/___  /|\n\ 5.\    / / /\ \_ / \    / _/  /  |   / / |\n|\______/___/_|\  /___\  /_____/___|____/Rpd\n`---------------\/-----\/----·presents·----''\n            5D-SendMessage v0.50\n   Coded by SvEN tHE CREAToR/5tH DyNASTY\n           Should work 100% now!!\n','\n',char(10)),'5D-SendMessage.Guide',replace('@database 5D-SendMessage Documentation\n@Author SvEN tHE CREAToR Of 5tH DyNASTY\n@Index Documentation\n\nCopyright © 1994 SvEN tHE CREAToR / 5tH DyNASTY\n\n@Remark $VER: 5D-SendMessagee v0.50 by sTc/5D\n@Remark AmigaGuide database\n\n@node MAIN "5D-SendMessage Documentation © 1994 SvEN tHE CREAToR Of 5tH DyNASTY"\n                                                              :\n                                                       :      ¦             \n                   ________________  __________________¦      |\n            _______\_______       /  \             /   |      |______\n           |  __   _/     /______/____\  _     _  /    ¦      |  __  |\n           |  \/  _\________    \_\  / \/       \/     _      |  \/  |\n           |______\        /     / \/   |       |      /      |______|\n                   \___________ /       |_______|_____/       |Rpd!\n                              \/                     /________|\n                         :           :                                     :\n            ____   :     ¦     :     ¦      · 5 · T · H ·            :     ¦\n  __________\  /___¦    _|__/\ ¦     |_______ _______________________¦     |\n  \______   \\//   |    \____ \|     |   _   \\_____      /       /  |     |\n   /     \   \/    ¦     |   \ \     |   /    \/   /_____/    _  /   ¦     |\n _/       \   \_____     |    \ \_   |   _     \_____   \_     \/_____     |\n \       _/    /   /     |     \     |   /      /   /    /     |     /     |\n  \__________ /__________|     |\ ___|__/_____ /_______ /______|___________|\n            \/           |     ¦ \/          \/       \/\n                         ¦     :     · D · Y · N · A · S · T · Y ·\n                         :\n\n                        ##>>> P r E S E N T S <<<##\n\n                           5D-SendMessage  v0.50\n\n                 Coded by SvEN tHE CREAToR of 5th Dynasty\n\n                           @{" Normal Documentation " Link Documentation}\n@endnode\n@node Documentation "5D-SendMessage Documentation"\n              _______________________________________________\n             |                                               |\n             | //                                            |\n             | /                                             |\n             |                                               |\n             |            @{" D e S C R I P T I O N " Link Description}           |\n             |                                               |\n             |           @{" I n S T A L L A T I O N " Link Installation}          |\n             |                                               |\n             |              @{" G r E E T I N G S " Link Greetings}             |\n             |                                               |\n             |                                             / |\n             |                                            // |\n             |_______________________________________________|\n\n@endnode\n@node Description "5D-SendMessage Description"\n5D-SendMessage has been coded by SvEN tHE CREAToR/5D!\n\nIt is a door which makes it possible for a user to write some chars\nto another node. For example to say that he wants to chat with him\nor something like.\n@endnode\n@node Installation "5D-SendMessage Installation"\nCopy all files which are in the archive bbs directory\nto your bbs directory.\n\nContents of archive:\n===================\n\nBBS/\n    Commands/\n        BBSCmd/\n            SEND.info\n    Doors/\n        5D-SendMessage/\n            5D-SendMessage\n            5D-SendMessage.info\n            5D-SendMessage.Guide\n\n===================\n\n@endnode\n@node Greetings "5D-SendMessage Greetings"\nGreetings go to:\n\n           Celator ........... Thank you for helping me with /X!\n           ByteAndi ............ For helping me to learn coding!\n           Prophet .................... For being a nice friend!\n           Snow ...................... Sing mehr lieder, leader!\n           Airworx ................. Continue work as Co Leader!\n           Delta-X ................. When you will merry Murdoc?\n           Strider ........ We should spread our standard again!\n\nSorry to all people I forgot but as you know my brain isn''t so well! hehe\n\n@endnode\n','\n',char(10)),NULL,'auto-added',14076,1,0,NULL,NULL,'5d_sm001','scan',1780048358);
INSERT INTO door_catalog VALUES('5d_srt02','5D-SRT02.LZH','~/Code/amiexpress_doors/Archives/AmiExpress/5D-SRT02.LZH',NULL,'XIM','LE-window6.12',NULL,NULL,'5D','\____\  \/  / \ |  |/   \|    |     \  \/  / |   \\_  _/ \ \|  |  _  |  __|__  __\_  _/ |   / |\/||  \ \  | /   |   \  |  |  |\/|s',replace('_5TH____  ____   __  ___  ____ ________  ___\n\____\  \/  / \ |  |/   \|    |     \  \/  /\n |   \\_  _/ \ \|  |  _  |  __|__  __\_  _/ \n |   / |\/||  \ \  | /   |   \  |  |  |\/|s \n |  /  |  ||  |\ \ | \_   \__ | |  |  |  |N \n | /   |  ||  | \ \|  |  |    | |  |  |  |o \n :     :  ::  : :\ :  :  :    : :  :  :  :W \n `-----`--''`--'' `--`--`--`----'' `--''  `--''\n    5D-SORT v0.2\n','\n',char(10)),'5D-SORT02.DOC',replace('\n                  5D-SORT v0.2 full documentation\n                 ---------------------------------\n\n                           Contents :\n              .------------------------------------.\n              | Chapter #1 What is sort v0.2 ?     |\n              | Chapter #2 How to use it !         |\n              | Chapter #3 Credits                 |\n              | Chapter #4 Greetings               |\n              | Chapter #5 What`s new ?            |\n              ·------------------------------------·\n\n@chapter1[what is sort v0.2 ?]\n\n    Sort v0.1 was written especially for Airworx of 5th dynasty\n    but i diceided to release it.\n    Sort v0.1 can sort any list of data (boardlists etc.) in alphabetical\n    order.I think,that is useful,if not tell me....(don`t do it!).\n\n@chapter2[how to use it !]\n\n   Sort v0.2 is easy to handle,you`ve just to type in the filename (with\n   complete path) and the file will be sorted.After sorting the original\n   file will be overwritten by the sorted one.You can abort the sort\n   function by pressing the right mousebutton (but only if you type in\n   the filename!).\n   To quit the program just press return if you where aked for the\n   filename.\n\n@chapter3[credits]\n\n             Credits are :\n\n         fULL cODING ................ pROPHET/5D\n         iDEA ....................... aIRWORX/5D\n\n  For any bugreports contact me in some different boards (in Berlin!)\n\n            pOWERBOX III <*> hOUSE OF bRAIN <*> mIAMI hEAT\n            dIABOLO <*> gANGSTARS dISTRICT <*> lEX eXPRESS \n                           hEAVENS gATE \n  \n@chapter4[greetings]\n\n          Greets fly`s out to :\n\n                          <*> mURDOC/AFL <*>\n                            <*> sNOW <*>\n                             <*> sTC <*>\n                           <*> gOONIE <*>\n                          <*> dOC tRACE <*>\n                           <*> aIRWORX <*>\n                          <*> wOLFGANG <*>\n                        <*> fRANK mAXWELL <*> \n                           <*> x-WING <*>\n                            <*> oSSI <*>\n                        <*> bYTEANDI/mST <*>\n                           <*> tOM/KC <*>\n                        <*> bRAWLER/bD <*> \n                        <*> wILDsTYLE <*>\n                         <*> sABINE/AFL <*>\n\n@chapter5[what`s new ?]\n\n          I`ve installed a quit routine ! Just press return\n          if you where asked for the filename to quit the program.\n','\n',char(10)),NULL,'auto-added',52204,6,0,NULL,NULL,'5d_srt02','scan',1780048358);
INSERT INTO door_catalog VALUES('5d_sts15','5D-STS15.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5D-STS15.LHA','5D-Status','XIM','5D-Status',NULL,'.sTc./5D!','5D','\_    \   \/   /|  |/   \ /   \__ \   \/ |  |  \  /   /_|  |  |  | \___||  \  /   / |  |  |\/  _/  \  |  |  |     ||  |\/  _/',replace(' 5th_______  ____ __  ___   ___________  ___\n \_    \   \/   /|  |/   \ /   \__ \   \/\n  |  |  \  /   /_|  |  |  | \___||  \  /   /\n  |  |  |\/  _/  \  |  |  |     ||  |\/  _/\n  |  |  | |  |    \_|     | __  ||  | |  |\n  |  |  | |  |_sNoW |     |  /  ||  | |  |\n  |  |  | |  | \    |  |  | /   ||  | |  |\n  |  |  | |  |  \   |  |  |     ||  | |  |\n  |_____| |__|__|\__|__|__|____/ |__| |__|\n  (= 5D-StATUS V1.50 CoDED bY .sTc./5D! =)\n  (=   FiRST StATUS DoOR WiTH ToP PoS!  =)\n','\n',char(10)),'5D-Status.guide',replace('@database 5D-StatusDoc\n@Author SvEN tHE CREAToR/5D\n\nCopyright (c) 1993 SvEN tHE CREAToR / 5th Dynasty\n\n@Remark $VER: (November 6 1993, 18:00:00)\n@Remark AmigaGuide database for the 5D-Status Documentation\n\n@node MAIN "5D-Status Documentation (c)1993 SvEN tHE CREAToR of 5th Dynasty (November 6 1993, 18:00:00)"\n          ______    ______    ______    ______    ______    ______\n          \   ¬/    \   ¬/    \   ¬/    \   ¬/    \   ¬/    \   ¬/\n 5th ______\  /_ ____\  /______\  /______\  /______\  /______\  /_ ____\n    //     \\// |   \\\//     \\\//     \\\//     \\\//     \\\// |   \\\n   //       \/  |    \\/       \\/  |    \\/     ---\/       \\/  |    \\\n  /·         \___     ·\     |  ·\        ·\____    \\__      ·\___     ·\\n /·         | \        ·\    |   ·\ |      ·\        ·\ |      ·\        ·\\n \___________ /________ /____|___ /_|______ /________ / |______ /________ /\n            \/        \/        \/        \/        \/        \/    ·cj·\/\n\n                              >>> 5D-Status <<<\n\n                Code: SvEN tHE CREAToR/5D  GFX: $NØW/5D\n\n---------------------------------------------------------------------------- \n\n         >>> C·O·N·T·E·N·T·S  O·F  D·O·C·U·M·E·N·T·A·T·I·O·N <<<\n\n                         @{"      Introduction      " Link Cap01}\n                         @{"      Requirements      " Link Cap02}\n                         @{"      Installation      " Link Cap03}\n                         @{"       Greetings!       " Link Cap05}\n                         @{"   How to Contact me?   " Link Cap06}\n\n         ---------------------------------------------------------\n             Complete Docs for 5D-Status V1.50 [-5th Dynasty-]\n         ---------------------------------------------------------\n         The Documentation has been written by SvEN tHE CREAToR/5D.\n\n@endnode\n@node Cap01 "Introduction"\n  =======================================================================\n  5D-Status is a replacement for the normal Status Command\n  of AmiExpress ''S''.\n  =======================================================================\n@endnode\n@node Cap02 "Requirements"\n  =======================================================================\n  To install 5D-Status you must have the following things:\n\n    Programm     Location           Description\n    ----------   --------           -----------\n    5D-Status    Doors:5D-Status    Main program\n\n  - an  Amiga Model (500/600/1000/1200/2000/2500/3000/4000/CDTV/CD³²)\n  - the installed Version of OS\2, OS\3 or higher\n    (Soft- or Hardware Version)\n  - the installed .INFO Files in the directories.\n  - AmiExpress V2.xx , v3.xx or higher.\n\n  =======================================================================\n@endnode\n@node Cap03 "How to install 5D-Status"\n  =======================================================================\n  To install 5D-Status you must have all Requirement which were\n  mentioned below. You need the following things.\n\n  --------------------------\n    Doors:5D-Status (dir)\n      ^^^ 5D-Status\n    BBS:Commands/BBSCmd (dir)\n      ^^^ S.info\n  --------------------------\n\n  Decruch the 5D-Status Archive. Go to your ''Doors:'' Directory\n  and make a Directory called ''5D-Status''. Copy ''5D-Status''\n  into the Directory. Go to your ''BBS:Commands/BBSCmd'' Directory.\n  Copy ''S.info'' into it.\n  =======================================================================\n@endnode\n@node Cap05 "Greetings go to..."\n  =======================================================================\n\n           ···­­­> ALL MEMBERS OF 5TH DYNASTY <­­­···\n\n     .--------------------------------------------------------.\n     : And all cool people who I know and all Status know me! :\n     `--------------------------------------------------------''\n\n  =======================================================================\n@endnode\n@node Cap06 "How to contact me..."\n  =======================================================================\n\n    .     /\_________  ______/\  /\______    /\_________  ______/\   .\n    .    _\______   .\ \______/ _\____   \  _\______   .\ \______/   .\n    :   /   _/ _/    \\/     .\/   __|   .\/   _/ _/    \\/     .\   :\n    |  /    \  \      \\      \\   \__    \\   \  \      \\      \\  |\n    +--\_____\__\       \____ //_____|     \\___\__\       \____ //--+\n    :            \  ____/    \/      |______/       \  ____/    \/   :\n    .             \/                                 \/              .\n               ___.\n              /  .|___    _______/\    /\______    ___________/\\n             /   ||   \  _\_  ____/_  _\____   \  _\_  __      /\n            /         .\/      /   .\/   __|   .\/     \______/\n           /      _    \\    _/     \\   \__    \\         .\\n           \______|     \\_________  /_____|     \\_______ //\n                  |______/         \/      |______/       \/\n\n               ···­­­>   \%\ 5TH DYNASTY GHQ \%\   <­­­···\n\n                        SYSOP: SvEN tHE CREAToR\n                        COSYS: Airworx/5D\n                               Mr.Return\n\n                      -<>- CaLL: +49-30-7424141 -<>-\n\n                  >>> AND ALL OTHER 5TH DYNASTY HQs! <<<\n\n              POWER BOX III ............ +49-(0)30-4167884\n              HOUSE OF BRAIN ........... +49-(0)3328472023\n              \n  =======================================================================\n@endnode\n','\n',char(10)),NULL,'auto-added',13167,2,0,NULL,NULL,'5d_sts15','scan',1780048358);
INSERT INTO door_catalog VALUES('5d_sysop','5D-SYSOP.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5D-SYSOP.LHA','5D-SysOp','XIM','_5TH____  ____   __  ___  ____ ________  ___',NULL,'sTc','5D','\____\  \/  / \ |  |/   \|    |     \  \/  / |   \\_  _/ \ \|  |  _  |  __|__  __\_  _/ |   / |\/||  \ \  | /   |   \  |  |  |\/|s',replace('_5TH____  ____   __  ___  ____ ________  ___\n\____\  \/  / \ |  |/   \|    |     \  \/  /\n |   \\_  _/ \ \|  |  _  |  __|__  __\_  _/\n |   / |\/||  \ \  | /   |   \  |  |  |\/|s\n |  /  |  ||  |\ \ | \_   \__ | |  |  |  |N\n | /   |  ||  | \ \|  |  |    | |  |  |  |o\n :     :  ::  : :\ :  :  :    : :  :  :  :W\n ~-----~--''~--'' ~--~--~--~----'' ~--''  ~--''\nyOU tHINK wE aRE lAME , wE kICK yA aSS wITH:\n 5D-sYSOP v1.00 cODED bY sTc oF 5tH dYNASTY\n','\n',char(10)),'5D-SysOp.guide',replace('@database 5D-SysOpDoc\n@Author SvEN tHE CREAToR ·OF· 5TH DYNASTY\n@Index MAIN\n\nCopyright (c) 1993 SvEN tHE CREAToR / 5th Dynasty\n\n@Remark $VER: (November 20 1993, 20:00:00)\n@Remark AmigaGuide database for the 5D-SysOp Documentation\n\n@node MAIN "5D-SysOp Documentation (c)1993 SvEN tHE CREAToR of 5th Dynasty (November 20 1993, 18:00:00)"\n\n                                                              :\n                                                       :      ¦             \n                   ________________  __________________¦      |\n            _______\_______       /  \             /   |      |______\n           |  __   _/     /______/____\  _     _  /    ¦      |  __  |\n           |  \/  _\________    \_\  / \/       \/     _      |  \/  |\n           |______\        /     / \/   |       |      /      |______|\n                   \___________ /       |_______|_____/       |Rpd!\n                              \/                     /________|\n                         :           :                                     :\n            ____   :     ¦     :     ¦      · 5 · T · H ·            :     ¦\n  __________\  /___¦    _|__/\ ¦     |_______ _______________________¦     |\n  \______   \\//   |    \____ \|     |   _   \\_____      /       /  |     |\n   /     \   \/    ¦     |   \ \     |   /    \/   /_____/    _  /   ¦     |\n _/       \   \_____     |    \ \_   |   _     \_____   \_     \/_____     |\n \       _/    /   /     |     \     |   /      /   /    /     |     /     |\n  \__________ /__________|     |\ ___|__/_____ /_______ /______|___________|\n            \/           |     ¦ \/          \/       \/\n                         ¦     :     · D · Y · N · A · S · T · Y ·\n                         :\n\n                            >H< >A< >P< >P< >Y<\n\n                      >B< >I< >R< >T< >H< >D< >A< >Y<\n\n                           _____         _____  __  __\n                          /      /|   / /    / / /// /\n                         /____  / |  / /    / /     /\n                             / /  | / /    / / _// /\n                       _____/ /   |/ /____/ /_/ /_/\n\n\n\n                              >>> 5D-SysOp <<<\n\n                         Code: SvEN tHE CREAToR/5D\n\n\n---------------------------------------------------------------------------- \n\n         >>> C·O·N·T·E·N·T·S  O·F  D·O·C·U·M·E·N·T·A·T·I·O·N <<<\n\n\n                         @{"      Introduction      " Link Cap01}\n                         @{"      Requirements      " Link Cap02}\n                         @{"      Installation      " Link Cap03}\n                         @{"       Greetings!       " Link Cap05}\n                         @{"   How to Contact me?   " Link Cap06}\n\n\n         ---------------------------------------------------------\n              Complete Docs for 5D-SysOp V1.00 [-5th Dynasty-]\n         ---------------------------------------------------------\n         The Documentation has been written by SvEN tHE CREAToR/5D.\n\n@endnode\n@node Cap01 "Introduction"\n  =======================================================================\n  5D-SysOp is a door which allows you to REALLY delete ALL INACTIVE\n  USERS and to show all users who didn''t call for a specifyable\n  time. It allows you to REALLY delete ONE account and to rename\n  ALL INACTIVE USERS to ''DeLeTe''.\n\n  And what I think of being usefull is:\n\n  All files of 5D-Page, 5D-NewFiles, NewFiles (Mst) are changed\n  automatically so that they can be used continuesly.\n  Please tell me, if ya need other files to be converted!\n\n  =======================================================================\n@endnode\n@node Cap02 "Requirements"\n  =======================================================================\n  To install 5D-SysOp you must have the following things:\n\n    Programm     Location           Description\n    ----------   --------           -----------\n    5D-SysOp      Doors:5D-SysOp      Main program\n\n  - an  Amiga Model (500/600/1000/1200/2000/2500/3000/4000/CDTV/CD³²)\n  - the installed Version of OS\2, OS\3 or higher\n    (Soft- or Hardware Version)\n  - the installed .INFO Files in the directories.\n  - AmiExpress v3.xx or higher.\n\n  =======================================================================\n@endnode\n@node Cap03 "How to install 5D-SysOp"\n  =======================================================================\n  To install 5D-SysOp you must have all Requirement which were\n  mentioned below. You need the following things.\n\n  --------------------------\n    Doors:5D-SysOp (dir)\n      ^^^ 5D-SysOp\n    BBS:Commands/BBSCmd (dir)\n      ^^^ SP.info\n  --------------------------\n\n  Decruch the 5D-SysOp Archive. Go to your ''Doors:'' Directory\n  and make a Directory called ''5D-SysOp/''. Copy ''5D-SysOp''\n  into the Directory. Go to your ''BBS:Commands/BBSCmd/'' Directory.\n  Copy ''SP.info'' into it.\n  =======================================================================\n@endnode\n@node Cap05 "Greetings go to..."\n  =======================================================================\n\n                        GREETS GO TO:\n\n    ByteAndi/MST ......................... For helping me!\n    Strider/PGS .................... Hope we''ll chat soon!\n    Mr.Return/AG ............................ Good friend!\n    Bytemaster ....................... For programming /X!\n\n              >>> ALL MEMBERS OF 5TH DYNASTY!!! <<<\n\n  =======================================================================\n@endnode\n@node Cap06 "How to contact me..."\n  =======================================================================\n    ___________________________   ___________   ___________________________\n   /\_______________________ _ \¡/           \¡/  _ ______________________/\\n   \/                            ·5TH DYNASTY·                            \/\n    ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\_______________/¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n    CELTIC CROSS ............... Thunder ...... +49-(0)30-******* ..... WHQ\n    MIAMI HEAT ........ Sven The Creator ...... +49-(0)30-7424141 ..... GHQ\n    HOUSE OF BRAIN ............. Delta-X ...... +49-(0)3328472023 ..... GHQ\n    POWER BOX II NODE 0 ....... Wolfgang ...... +49-(0)30-******* ..... GHQ\n    POWER BOX II NODE 1 ....... Wolfgang ...... +49-(0)30-******* ..... GHQ\n    POWER BOX III ........ Frank Maxwell ...... +49-(0)30-4167884 ..... GHQ\n    5TH DYNASTY CLUB .............. Snow ...... +49-(0)30-******* ..... GHQ\n    HEAVENS GATE ................ Murdoc ...... +49-(0)30-6596730 ..... GDS\n\n                 ___ ___    ___    _______    ___ ___    ___\n                /  ¬|  ¬\  /  ¬\  /      ¬\  /  ¬|  ¬\  /  ¬\\n               /         \/     \/         \/         \/     \\n              /           \      \          \          \      \\n            _/             \_     \_  |      \_         \_     \_\n            \      \ /      /      /          / \ /      /      /\n             \      |      /      /   |      /   |      /      /\n              \_____|____ /_____ /____|____ /____|____ /_____ /\n          /\            \/     \/         \/         \/     \/\n_________/  \  /\___________> 5TH DYNASTY GHQ <____________________ ___ __ _\n             \/    ___ ___    _______    _______    _______\n                  /  ¬|  ¬\  /      ¬\  /      ¬\  /      ¬\\n                 /    |    \/         \/         \/         \\n                /           \    |     \          \          \\n              _/             \_     ___/\_  |      \_____     \_\n              \               /    /     /          / |        /\n               \      |      /          /   |      /  |       /\n                \_____|____ /_________ /____|____ /   |_____ /·cj·\n                          \/         \/         \/         \/\n \n                         SYSOP: SvEN tHE CREAToR/5D\n                         COSYS: Airworx/5D\n                                Mr.Return/AG\n \n                   -<>- CaLL: +49-(0)30-742-4141 -<>-\n\n  =======================================================================\n@endnode\n','\n',char(10)),NULL,NULL,15873,1,0,NULL,NULL,'5d_sysop','scan',1780048358);
INSERT INTO door_catalog VALUES('5d_tc002','5D-TC002.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5D-TC002.LHA','5D-TodayCallers','XIM','5D-TodayCallers',NULL,'sTc/5D!','5D','______\     /__|      /___________\___  /___ \_____ \  _/   /     /__\   ____/  _ /_/   / _/   /  \___  /\    /__/ \____ \_  \/___  /|',replace('      _______   _______           _______   \n______\     /__|      /___________\___  /___\n\_____ \  _/   /     /__\   ____/  _ /_/   /\n_/   /  \___  /\    /__/ \____ \_  \/___  /|\n\ 5TH    / / /\ \_ / \    / _/  /  |   / / |\n|\______/___/_|\  /___\  /_____/___|____/Rpd\n`---------------\/-----\/------------------''\n   5D-TodayCallers v0.02 coded by sTc/5D!\n       - Shows ALL users which have -\n         - called at the one day, -\n         - Fully coded in AmigaE! -\n','\n',char(10)),'5D-TodayCallers.Guide',replace('@DataBase 5D-TodayCallers Documentation\n@Author sTc/5D\n@Index Documentation\n\nCopyright © 1994 SvEN tHE CREAToR of 5tH DyNASTY\n\n@Remark $VER: 5D-TodayCallers v0.02 by sTc/5D\n@Remark AmigaGuide DataBase\n\n@node MAIN "5D-TodayCallers Documentation © 1994 SvEN tHE CREAToR of 5tH DyNASTY"\n                                                              :\n                                                       :      ¦             \n                   ________________  __________________¦      |\n            _______\_______       /  \             /   |      |______\n           |  __   _/     /______/____\  _     _  /    ¦      |  __  |\n           |  \/  _\________    \_\  / \/       \/     _      |  \/  |\n           |______\        /     / \/   |       |      /      |______|\n                   \___________ /       |_______|_____/       |Rpd!\n                              \/                     /________|\n                         :           :                                     :\n            ____   :     ¦     :     ¦      · 5 · T · H ·            :     ¦\n  __________\  /___¦    _|__/\ ¦     |_______ _______________________¦     |\n  \______   \\//   |    \____ \|     |   _   \\_____      /       /  |     |\n   /     \   \/    ¦     |   \ \     |   /    \/   /_____/    _  /   ¦     |\n _/       \   \_____     |    \ \_   |   _     \_____   \_     \/_____     |\n \       _/    /   /     |     \     |   /      /   /    /     |     /     |\n  \__________ /__________|     |\ ___|__/_____ /_______ /______|___________|\n            \/           |     ¦ \/          \/       \/\n                         ¦     :     · D · Y · N · A · S · T · Y ·\n                         :\n\n                              (×· PrESENTS ·×)\n\n                         Code: SvEN tHE CREAToR/5D\n\n               ----- --- -> 5D-TodayCallers v0.02 <- --- -----\n\n                  Coded by SvEN tHE CREAToR of 5th Dynasty\n\n                           @{" Normal Documentation " Link Documentation}\n@endnode\n@node Documentation "5D-TodayCallers Documentation"\n              _______________________________________________\n             |                                               |\n             | //                                            |\n             | /                                             |\n             |                                               |\n             |            @{" D e S C R I P T I O N " Link Description}           |\n             |                                               |\n             |           @{" I n S T A L L A T I O N " Link Installation}          |\n             |                                               |\n             |              @{" G r E E T I N G S " Link Greetings}             |\n             |                                               |\n             |                                             / |\n             |                                            // |\n             |_______________________________________________|\n\n@endnode\n@node Description "5D-TodayCallers Description"\n5D-TodayCallers has been coded by SvEN tHE CREAToR/5D!\n\n5D-TodayCallers is at most as like as a LastCallers utility.\nThe only difference is that it shows ALL callers of the day.\nI think that it is fast enough for you. It takes less than a\nhalf second to check the callerslog and make the output.\n@endnode\n@node Installation "5D-TodayCallers Installation"\nCopy all files which are in the ''BBS'' directory of the archive\ninto your bbs directory.\n\nContents of archive:\n===================\n\nBBS/ Doors/ 5D-TodayCallers/ 5D-TodayCallers\n                             5D-TodayCallers.info\n                             5D-TodayCallers.Guide\n\n===================\n\nTo install it you need to add a line to your logoff batch. 5D-TodayCallers\nhas the following usage:\n\n5D-TodayCallers LOGFILE <CLOG> NODE <#> CFGFILE <CFG> OUTPUT <OP> (QUIET)\n\nSo an example add could look like this:\n\nDoors:5D-TodayCallers/5D-TodayCallers LOGFILE BBS:Node0/CallersLog\n`-> NODE 0 CFGFILE Doors:5D-TodayCallers/5D-TodayCallers.cfg\n`-> OUTPUT Bulletins:Bull1.TXT QUIET\n\nThe "`->" means that it needs to be added to the first line. The example above will\ncheck out the CallersLog of Node 0, write the config into\n''Doors:5D-TodayCallers/5D-TodayCallers.cfg'' and make the output into\n''Bulletins:Bull1.TXT'', also it will show NO datas (has only sense if you run it from\nthe shell)!\n@endnode\n@node Greetings "5D-TodayCallers Greetings"\nGreetings go to:\n\n         . Celator ........... Thank you for helping me with /X! .\n         : ByteAndi ............ For helping me to learn coding! :\n         | Snow ...................... Sing mehr lieder, leader! |\n         `------( And all other persons I''ve forgotten!!! )------''\n\n@endnode\n','\n',char(10)),NULL,'auto-added',6765,1,0,NULL,NULL,'5d_tc002','scan',1780048358);
INSERT INTO door_catalog VALUES('5d_to001','5D-TO001.LZH','~/Code/amiexpress_doors/Archives/AmiExpress/5D-TO001.LZH','5D-ThrowOut','XIM','5D-ThrowOut',NULL,'sTc','5D','/___ \  \  \/     \/ ___ \    \      / \  \ / /  \_    \     /  __  / \___\_ __/\_    \ / /   / \   / /  /   /  /\__  \/  /    \   /',replace('5TH________  _____  ______________________\n/___ \  \  \/     \/ ___ \    \      / \  \\n / /  \_    \     /  __  / \___\_ __/\_    \\n/ /   / \   / /  /   /  /\__  \/  /    \   /\n\____/_____/_/__/\__/__/______/__/________/\n - --- -----[ P·R·E·S·E·N·T·S ]----[MaD]- -\n          5D-ThrowOut v0.01 by sTc\n    Allows the SysOp to throw a user of\n another node out of the bbs!  For /X 3.38+\n - --- ----- - ---- -------- ---- - ----- -\n','\n',char(10)),'5D-ThrowOut.Guide',replace('@DataBase 5D-ThrowOut Documentation\n@Author sTc/5D\n@Index Documentation\n\nCopyright © 1994 SvEN tHE CREAToR of 5tH DyNASTY\n\n@Remark $VER: 5D-ThrowOut v0.01 by sTc/5D\n@Remark AmigaGuide DataBase\n\n@node MAIN "5D-ThrowOut Documentation © 1994 SvEN tHE CREAToR of 5tH DyNASTY"\n                                                              :\n                                                       :      ¦\n                   ________________  __________________¦      |\n            _______\_______       /  \             /   |      |______\n           |  __   _/     /______/____\  _     _  /    ¦      |  __  |\n           |  \/  _\________    \_\  / \/       \/     _      |  \/  |\n           |______\        /     / \/   |       |      /      |______|\n                   \___________ /       |_______|_____/       |Rpd!\n                              \/                     /________|\n                         :           :                                     :\n            ____   :     ¦     :     ¦      · 5 · T · H ·            :     ¦\n  __________\  /___¦    _|__/\ ¦     |_______ _______________________¦     |\n  \______   \\//   |    \____ \|     |   _   \\_____      /       /  |     |\n   /     \   \/    ¦     |   \ \     |   /    \/   /_____/    _  /   ¦     |\n _/       \   \_____     |    \ \_   |   _     \_____   \_     \/_____     |\n \       _/    /   /     |     \     |   /      /   /    /     |     /     |\n  \__________ /__________|     |\ ___|__/_____ /_______ /______|___________|\n            \/           |     ¦ \/          \/       \/\n                         ¦     :     · D · Y · N · A · S · T · Y ·\n                         :\n\n                              (×· PrESENTS ·×)\n\n                ----- --- -> 5D-ThrowOut v0.01 <- --- -----\n\n                  Coded by SvEN tHE CREAToR of 5th Dynasty\n\n                           @{" Normal Documentation " Link Documentation}\n@endnode\n@node Documentation "5D-ThrowOut Documentation"\n              _______________________________________________\n             |                                               |\n             | //                                            |\n             | /                                             |\n             |                                               |\n             |            @{" D e S C R I P T I O N " Link Description}           |\n             |                                               |\n             |           @{" I n S T A L L A T I O N " Link Installation}          |\n             |                                               |\n             |              @{" G r E E T I N G S " Link Greetings}             |\n             |                                               |\n             |                                             / |\n             |                                            // |\n             |_______________________________________________|\n\n@endnode\n@node Description "5D-ThrowOut Description"\n5D-ThrowOut has been coded by SvEN tHE CREAToR/5D!\n\nIt''s a AmiEx door which allows you to throw a user out! So, if you are\na SysOp and login from someone else you can simply start 5D-ThrowOut,\nenter the node number and then he will be kicked out of that node.\n@endnode\n@node Installation "5D-ThrowOut Installation"\n\nCopy the following things to the specified directory.\n\nContents of archive:\n===================\n\nBBS/   Commands/    BBSCmd/      Throw.info\n       Doors/       5D-ThrowOut/ 5D-ThrowOut\n                                 5D-ThrowOut.Guide\n\n===================\n\n@endnode\n@node Greetings "5D-ThrowOut Greetings"\nGreetings go to:\n\n         . Celator ........... Thank you for helping me with /X! .\n         : ByteAndi ............ For helping me to learn coding! :\n         | Snow ...................... Sing mehr lieder, leader! |\n         `------( And all other persons I''ve forgotten!!! )------''\n\n@endnode\n','\n',char(10)),NULL,'auto-added',10554,4,0,NULL,NULL,'5d_to001','scan',1780048358);
INSERT INTO door_catalog VALUES('5d_topfa','5D-TOPFA.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5D-TOPFA.LHA','5D-TopFaker','XIM','5D-TopFaker',NULL,NULL,'5D',NULL,replace('5D-TOP FAKER\n','\n',char(10)),'5D-TopFaker.guide',replace('@database 5D-TopFakerDoc\n\nCopyright (c) 1993 SvEN tHE CREAToR / 5th Dynasty\n\n@Remark $VER: (September 18 1993, 22:30:00)\n@Remark AmigaGuide database for the 5D-TopFaker Documentation\n\n@node MAIN "5D-TopFaker Documentation (c)1993 SvEN tHE CREAToR of 5th Dynasty (September 18 1993, 22:30:00)"\n          ______    ______    ______    ______    ______    ______\n          \   ¬/    \   ¬/    \   ¬/    \   ¬/    \   ¬/    \   ¬/\n 5th ______\  /_ ____\  /______\  /______\  /______\  /______\  /_ ____\n    //     \\// |   \\\//     \\\//     \\\//     \\\//     \\\// |   \\\n   //       \/  |    \\/       \\/  |    \\/     ---\/       \\/  |    \\\n  /·         \___     ·\     |  ·\        ·\____    \\__      ·\___     ·\\n /·         | \        ·\    |   ·\ |      ·\        ·\ |      ·\        ·\\n \___________ /________ /____|___ /_|______ /________ / |______ /________ /\n            \/        \/        \/        \/        \/        \/    ·cj·\/\n\n                             >>> 5D-TopFaker <<<\n\n                Code: SvEN tHE CREAToR/5D  GFX: Cee Jay/5D\n\n---------------------------------------------------------------------------- \n\n         >>> C·O·N·T·E·N·T·S  O·F  D·O·C·U·M·E·N·T·A·T·I·O·N <<<\n\n                         @{"      Introduction      " Link Cap01}\n                         @{"      Requirements      " Link Cap02}\n                         @{"      Installation      " Link Cap03}\n                         @{"       Greetings!       " Link Cap05}\n                         @{"   How to Contact me?   " Link Cap06}\n\n         ---------------------------------------------------------\n            Complete Docs for 5D-TopFaker V0.12a [-5th Dynasty-]\n         ---------------------------------------------------------\n         The Documentation has been written by SvEN tHE CREAToR/5D.\n\n@endnode\n@node Cap02 "Requirements"\n  =======================================================================\n  To install 5D-TopFaker you must have the following things:\n\n    Programm     Location         Description\n    ----------   --------         -----------\n    5D-TopFaker  BBS:Utils/       Main program\n\n  - an  Amiga Model (500/600/1000/1200/2000/2500/3000/4000/CDTV/CD³²)\n  - the installed Version of OS\2, OS\3 or higher\n    (Soft- or Hardware Version)\n  - the installed .INFO Files in the directories.\n  - AmiExpress V2.xx , v3.xx or higher.\n\n  =======================================================================\n@endnode\n@node Cap03 "How to install 5D-TopFaker"\n  =======================================================================\n  To install 5D-TopFaker you must have all Requirement which were\n  mentioned below. You need the following things.\n\n  --------------------------\n    BBS:Utils/ (dir)\n      ^^^ 5D-TopFaker\n  --------------------------\n\n  Decruch the 5D-TopFaker Archive. Go to your ''BBS:Utils/'' Directory.\n  Copy ''5D-TopFaker'' into the Directory. Go to your LogOff-Batch(s) and\n  insert the following:\n\n  Usage  : 5D-TopFaker <FULL USER-DATA LOCATION> <OUTPUT FILE> <USERS TO SHOW> <MODE>\n\n  ###CUT###\n  BBS:Utils/5D-TopFaker Doors:ByteKiller/ByteKiller2.data Bulletins:Bull1.TXT 10 1\n  BBS:Utils/5D-TopFaker Doors:ByteKiller/ByteKiller3.data Bulletins:Bull2.TXT 10 2\n  ###CUT###\n\n  The first line tells 5D-TopFaker to make the output to\n  ''Bulletins:Bull1.TXT'' for conference 2.\n  The second line tells 5D-TopFaker to make the output to\n  ''Bulletins:Bull2.TXT'' for conference 3.\n  =======================================================================\n@endnode\n@node Cap05 "Greetings go to..."\n  =======================================================================\n\n           ···­­­> ALL MEMBERS OF 5TH DYNASTY <­­­···\n\n      .-----------------------------------------------------.\n      : And all cool people who I know and all who know me! :\n      `-----------------------------------------------------''\n\n  =======================================================================\n@endnode\n@node Cap06 "How to contact me..."\n  =======================================================================\n\n                   >>> CALL ALL 5TH DYNASTY HQS! <<<\n\n    .     /\_________  ______/\  /\______    /\_________  ______/\   .\n    .    _\______   .\ \______/ _\____   \  _\______   .\ \______/   .\n    :   /   _/ _/    \\/     .\/   __|   .\/   _/ _/    \\/     .\   :\n    |  /    \  \      \\      \\   \__    \\   \  \      \\      \\  |\n    +--\_____\__\       \____ //_____|     \\___\__\       \____ //--+\n    :            \  ____/    \/      |______/       \  ____/    \/   :\n    .             \/                                 \/              .\n               ___.\n              /  .|___    _______/\    /\______    ___________/\\n             /   ||   \  _\_  ____/_  _\____   \  _\_  __      /\n            /         .\/      /   .\/   __|   .\/     \______/\n           /      _    \\    _/     \\   \__    \\         .\\n           \______|     \\_________  /_____|     \\_______ //\n                  |______/         \/      |______/       \/\n\n               ···­­­>   \%\ 5TH DYNASTY GHQ \%\   <­­­···\n\n                        SYSOP: SvEN tHE CREAToR\n                        COSYS: Mr.Return\n                               Cee Jay\n\n                    -<>- CaLL: +49-(0)30-742-4141 -<>-\n\n  =======================================================================\n@endnode\n','\n',char(10)),NULL,'auto-added',9893,3,0,NULL,NULL,'5d_topfa','scan',1780048358);
INSERT INTO door_catalog VALUES('5d_ue001','5D-UE001.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5D-UE001.LHA','5D-USERED','XIM','5D-USERED',NULL,'sTc','5D','5 \____\   / \     \____\   __/     /  /   \ T/   / \__   \  T  \  / \___ \   \/___    / H/   /   \     \ |   \    \ /  \   \      /',replace('  ____________________/\___________________\n5 \____\   / \     \____\   __/     /  /   \\n T/   / \__   \  T  \  / \___ \   \/___    /\nH/   /   \     \ |   \    \ /  \   \      /\n/________/     /_|    \/   \____\___\    /\n[===/_________/==|____/_____\RpD!/______/==]\n|       5D-UserEd v0.01 © 1994 by sTc      |\n`------------------------------------------''\n    ==vv== FUCK THESE BBS ADDIES ==vv==\n','\n',char(10)),'5D-USER.GUIDE',replace('@DataBase 5D-UserEd Documentation\n@Author [tHE aDDiCT/5D!]\n@Index Documentation\n\nCopyright © 1994 5tH DyNASTY\n\n@Remark $VER: 5D-UserEd v0.01 18.6.1994\n@Remark AmigaGuide DataBase\n\n@node MAIN "5D-UserEd v0.01 Docu Main Page"\n                                                              :\n                                                       :      ¦\n                   ________________  __________________¦      |\n            _______\_______       /  \             /   |      |______\n           |  __   _/     /______/____\  _     _  /    ¦      |  __  |\n           |  \/  _\________    \_\  / \/       \/     _      |  \/  |\n           |______\        /     / \/   |       |      /      |______|\n                   \___________ /       |_______|_____/       |Rpd!\n                              \/                     /________|\n                         :           :                                     :\n            ____   :     ¦     :     ¦      · 5 · T · H ·            :     ¦\n  __________\  /___¦    _|__/\ ¦     |_______ _______________________¦     |\n  \______   \\//   |    \____ \|     |   _   \\_____      /       /  |     |\n   /     \   \/    ¦     |   \ \     |   /    \/   /_____/    _  /   ¦     |\n _/       \   \_____     |    \ \_   |   _     \_____   \_     \/_____     |\n \       _/    /   /     |     \     |   /      /   /    /     |     /     |\n  \__________ /__________|     |\ ___|__/_____ /_______ /______|___________|\n            \/           |     ¦ \/          \/       \/\n                         ¦     :     · D · Y · N · A · S · T · Y ·\n                         :\n             ____             (×· PrESENTS ·×)\n            \\  /\n             \\/----- --- -> 5D-UserEd v0.01 by sTc <- --- -----\n              \/\n                  Coded by SvEN tHE CREAToR of 5th Dynasty\n                         Docu  by [tHE aDDiCT/5D!]\n                           ^                ^\n                           | @{"    Purpose   " Link Purpose} |\n                           | @{" Requirements " Link Requirements} |\n                           | @{" Installation " Link Installation} |\n                           | @{"   Important  " Link Important} |\n                           | @{"   Greetings  " Link Greetings} |\n                           `----------------''                     ____\n                                                               \\  /\n                ----- --- -> 5D-UserEd v0.01 by sTc <- --- -----\\/\n                                                                 \/\n@endnode\n\n@node "Purpose" "Purpose of 5D-UserEd v0.01 © 1994 by sTc"\n@toc "Purpose"\n\n     5D-UserEd is a Workbench or CLI User Editor for AmiExpress 3.xx\n     should work fine on AmiExpress 2.xx or S!Express, but we hadn`t\n     got a chance to test it.\n     Just try it out!\n\n                            @{" Requirements " link "Requirements"}\n                            @{"  -> Main <-  " link "MAIN"}\n\n@endnode\n\n@node "Requirements" "Requirements for 5D-UserEd v0.01 © 1994 by sTc"\n@toc "Requirements"\n\n     You need an Amiga model 500/600/1000/1000 ..... (blabla)\n    \n     Installed Amiexpress software \n         (well, User.data & User.keys should be enough)\n\n     Some Users to edit! \n\n                            @{" Installation" link "Installation"}\n                            @{"  -> Main <- " link "MAIN"}\n\n@endnode\n@node "Installation" "Installation of 5D-UserEd v0.01 © 1994 by sTc"\n@toc "Installation"\n\n     There are three ways of @{"Usage" link "Usage"} of 5D-UserEd.\n     We highly suggest You, to put 5D-UserEd into\n\n     BBS:UTILS/\n\n     Then consult to Chapter Usage for Your favorite way of using it.\n\n                            @{"  Important  " link "Important"}\n                            @{"  -> Main <- " link "MAIN"}\n\n@endnode\n\n@node "Usage" "Usage of 5D-UserEd v0.01 © 1994 by sTc"\n@toc "Usage"\n\n     Just three ways to use this one:\n\n       1. from CLI: Simply type "BBS:UTILS/5D-UserEd\n\n       2. from WB:  Double Click on the Icon (Ouuh hard!)\n\n       3. from ACP: \n\n          /X 3.xx: Add two tooltypes to Your ACP.INFO:\n\n                   BUTTON_NAME.1=5D-USERED\n                   BUTTON_COMMAND.1=BBS:UTILS/5D-USERED\n\n          /X 2.xx: Add this line to Your ACP.STARTUP and reboot:\n\n                   BUTTON01: 5D-USERED    |BBS:UTILS/5D-USERED\n\n       4. that`s all!\n          \n\n                            @{" Installation " link "Installation"}\n                            @{"  -> Main <-  " link "MAIN"}\n\n@endnode\n\n@node "Important" "The 5th Dynasty Boards!"\n@toc "Important"\n\n                              ______ ______ __  __\n                             /  ___//_  __// /_/ /\n                          ___\__ \  /  /  /  _  /\n                         /_______/ /__/  /__//_/\n               ___ __  ___ _  __ _____ _____ ______ __   __\n              /   \\ \/  // \/ // _  // ___//_  __// /  / /\n             / /-  \\   //    // _  //__  / /  /  / /__/ /\n            /______//__//_/\_//_//_//____/ /__/  /____  /\n         ____________________________________________/ /\n        /_____________________________________________/MaD\n\n                 ----- --- --> The Boards! <-- --- -----\n\n                  ANTARCTICA       +49-30-XXXXXX  WHq\n  \n               Faceless World   +49-30-XXXXXX  SounderHQ\n  \n                 lASERdANCE       +49-21xx-XXXXX 2Ndz\n  \n            sCUMWHERE        +49-711-XXXX   3Ndz (2 iSDN RD)\n\n                  Funky Trading    +39-xxxx-XXXXX 2Ndz\n\n               Desert Strike +49-xxxx-XXXXXX 2Ndz (soon iSDN)\n\n\n                 ----- --- --> The Boards! <-- --- -----\n\n                            @{"  Greetings  " link "Greetings"}\n                            @{"  -> Main <- " link "MAIN"}\n\n@endnode\n@node "Greetings" "The Greetings of StC!"\n@toc "Greetings"\n\n\n          Thunder .. Hau den Telekotzern auf die Backen!\n          Rainman .................... Gogo, NRW Leader!\n          Starcam .......... Sorry, we''ve some problems!\n          Mad Førce .............. Man, leg endlich auf!\n          Snow ............... Jaja, kriegst Deine 5 DM!\n          Airworx .. 20 Chicken McNuggets, 3*Senf-Sauce!\n          Prophet ...... Ich ziehe um, wohne 5 mins weg!\n          Circuit Breaker ................ Doedeldiduuu!\n          Zector ................. AmigaE, yeaaah! Hehe!\n          Muad''Dib ............... Hope to see you soon!\n          Scan .............. We dream about your scape!\n\n\n                            @{"  That`s all " link "All"}\n                            @{"  -> Main <- " link "MAIN"}\n\n@endnode\n@node "All" "Hidden Node!"\n@toc "All"\n\n                           WUPPPS! \n\n                            @{"  -> Main <- " link "MAIN"}\n\n@endnode\n','\n',char(10)),NULL,'auto-added',11504,1,0,NULL,NULL,'5d_ue001','scan',1780048358);
INSERT INTO door_catalog VALUES('5d_ul001','5D-UL001.LZH','~/Code/amiexpress_doors/Archives/AmiExpress/5D-UL001.LZH','5D-UserList','XIM','5D-UserList',NULL,'sTc/5D','5D','\__   \  \/  /_|  |/___\ / ___/_/ |_\  \/  / |  |  \_/ _/__\  |  /  |___  \_   _/\_/ _/ |  |  ||  ||  \\_| /   |     ||   |  |  |',replace('5th______  ___  __  ___   _____  _. ___  ___\n\__   \  \/  /_|  |/___\ / ___/_/ |_\  \/  /\n |  |  \_/ _/__\  |  /  |___  \_   _/\_/ _/\n |  |  ||  ||  \\_| /   |     ||   |  |  |\n |  |  ||  ||  |\_| \_  |SNOW!||   |  |  |\n |_____||__||__|__|__|__|_____||___|  |__|\n-==[ 5D ]==========================[ 5D ]==-\n        5D-UserList v0.01 by sTc/5D\n    You can specify the max & min level\n           For AmiExpress v3.xx+!\n-==[ 5D ]==========================[ 5D ]==-\n','\n',char(10)),'5D-UserList.Guide',replace('@DataBase 5D-UserListDoc\n\nCopyright (c) 1993 SvEN tHE CREAToR of 5th Dynasty\n\n@Remark $VER: 5D-UserList v0.01\n@Remark AmigaGuide database for the 5D-UserList Documentation\n\n@node MAIN "5D-UserList Documentation (c)1994 SvEN tHE CREAToR of 5th Dynasty"\n\n    _5tH_______    ____   ___  _____  _______ _________    ___\n    \______ \  \__/  / \ |   |/     \|       |      \  \__/  /\n     |     \ \_ \/ _/ \ \|   |   _   |  _____|___ ___\_ \/ _/\n     |     / ||\  /|   \ \   |  /    |      \  |   |  |\  /|\n     |    /  || \/ |   |\ \  |  \_   |\____  | |   |  | \/ |\n     |   /   ||sNoW|   | \ \ |   |   |       | |   |  |    |\n     :       ::    :   : :\  :   :   :       : :   :  :    :\n     `-------''`----`---'' `---`---`---`-------'' `---''  `----''\n\n                      >>> 5D-UserList <<<\n\n                   Code: SvEN tHE CREAToR/5D\n\n----------------------------------------------------------------------------\n\n         >>> C·O·N·T·E·N·T·S  O·F  D·O·C·U·M·E·N·T·A·T·I·O·N <<<\n\n                         @{"      Introduction      " Link Cap01}\n                         @{"      Requirements      " Link Cap02}\n                         @{"      Installation      " Link Cap03}\n                         @{"       Greetings!       " Link Cap05}\n                         @{"   How to Contact me?   " Link Cap06}\n\n         ---------------------------------------------------------\n                   Complete Docs for 5D-UserList v0.01\n         ---------------------------------------------------------\n         The Documentation has been written by SvEN tHE CREAToR/5D\n\n@endnode\n@node Cap01 "Introduction"\n  =======================================================================\n  5D-UserList is an AX-Util! Yehuuuu... Why should you use this one???\n  Hmm.. Don''t ask me!! hehe... You can specify the Minimum and Maximum\n  Level of the listed users.\n\n  Usage:\n  ¯¯¯¯¯\n  5D-UserList <OUTFILE> MINLEVEL <MINLEVEL> MAXLEVEL <MAXLEVEL> (QUIET)\n\n  Example:\n  ¯¯¯¯¯¯¯\n  5D-UserList Bulletins:Bull1.TXT MINLEVEL 50 MAXLEVEL 200 QUIET\n\n  =======================================================================\n@endnode\n@node Cap02 "Requirements"\n  =======================================================================\n  To install 5D-UserList you must have the following things:\n\n  - an  Amiga Model (500/600/1000/1200/2000/2500/3000/4000/CDTV/CD³²)\n  - the installed Version of OS\2, OS\3 or higher\n    (Soft- or Hardware Version)\n  - AmiExpress V2.xx , v3.xx or higher. And surely S-Express hehe.\n\n  =======================================================================\n@endnode\n@node Cap03 "How to install 5D-UserList:"\n  =======================================================================\n  To install 5D-UserList you must have all Requirement which were\n  mentioned below. You need the following things.\n\n  ---------------------------------------------------\n    BBS:   Utils/    5D-UserList/   5D-UserList\n                                    5D-UserList.Guide\n  ---------------------------------------------------\n\n  Decruch the 5D-UserList Archive. Go to your ''BBS:Utils/'' Directory\n  and make a directory called ''5D-UserList''. Copy ''5D-UserList''\n  into the Directory. Go to your LogOff-Batch and add your individual\n  5D-UserList line.\n  =======================================================================\n@endnode\n@node Cap05 "Greetings go to the following guys:"\n  =======================================================================\n\n          Thunder .. Hau den Telekotzern auf die Backen!\n          Rainman .................... Gogo, NRW Leader!\n          Starcam .......... Sorry, we''ve some problems!\n          Mad Førce .............. Man, leg endlich auf!\n          Snow ............... Jaja, kriegst Deine 5 DM!\n          Airworx .. 20 Chicken McNuggets, 3*Senf-Sauce!\n          Prophet ...... Ich ziehe um, wohne 5 mins weg!\n          Circuit Breaker ................ Doedeldiduuu!\n          Zector ................. AmigaE, yeaaah! Hehe!\n          Muad''Dib ............... Hope to see you soon!\n          Scan .............. We dream about your scape!\n          Steel .................. Wie''s gööööht''s Gott?\n          Earthquake ...... Kriege hunger auf Erdbeeren!\n          Haystack ........... Wie geht es Deiner Backe?\n\n  =======================================================================\n@endnode\n@node Cap06 "How to contact me:"\n  =======================================================================\n  _____  ___   __________  _____________  _____________ ___ ______  _____\n /     \|   \ |  |       |/     \____.  \|     |       |   |      |/     \\n|   |   |  \ \|  |___ ___|   |   |   |   |     |___ ___|___|      |   |   |\n|   |   |   \ \   ||   | |   |   |   | __|  \   ||   | |   |  \   |   |   |\n|       |   |\ \  ||   | |       |      \|   \__||   | |   |   \__|       |\n|   |   |   | \ \ ||   | |   |   |   |   |   /  ||   | |   |   /  |   |   |\n|   |   |   | |\  ||   | |   |   |   |   |  /   ||   | |   |  /   |   |   |\n|___|   |___| | \ ||___| |___|   |___|   |      ||___| |___|      |___|   |\n    |   |     |   |          |   |   |   |______|          |______|   |   |\n    |___|     |___|          |___|   |___|                            |___|\n \n                      5TH DYNASTY GHQ                     .__________.\n S                                                        |   WITH   |\n Y          COOOOOOL THE COOOOLEST THING FOR DA SUMMER    |   CODER  |\n S                                                        |CONFERENCE|\n O      THE FIRST 5 UPLOADERS GET A DISABLE FOR ONE MONTH ·¯¯¯¯¯¯¯¯¯¯·\n P\n :              36 HOURS ONLINE PER 1 1/2 DAYS !\n S\n N          GET 5TH DYNASTY RELEASES FOR FREEDOWNLOAD\n O\n W         +49-306-XXXXXX : NUP=XXXXXXX : SYSTEMPW=XXX\n  =======================================================================\n@endnode\n','\n',char(10)),NULL,'auto-added',12742,6,0,NULL,NULL,'5d_ul001','scan',1780048358);
INSERT INTO door_catalog VALUES('5d_user1','5D-USER1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5D-USER1.LHA','5D-User','XIM','5D-User',NULL,NULL,'5D','- sOMEWHERE iN tHIS gALAXY iS tHE sYSTEM ! -',replace('The Best Account Editor For AmiExpress 3.xx \n- sOMEWHERE iN tHIS gALAXY iS tHE sYSTEM ! -\n','\n',char(10)),'5D-User.guide',replace('@database 5D-UserDoc\n\nCopyright (c) 1993 SvEN tHE CREAToR / 5th Dynasty\n\n@Remark $VER: (October 24 1993, 18:30:00)\n@Remark AmigaGuide database for the 5D-User Documentation\n\n@node MAIN "5D-User Documentation (c)1993 SvEN tHE CREAToR of 5th Dynasty (October 24 1993, 18:30:00)"\n          ______    ______    ______    ______    ______    ______\n          \   ¬/    \   ¬/    \   ¬/    \   ¬/    \   ¬/    \   ¬/\n 5th ______\  /_ ____\  /______\  /______\  /______\  /______\  /_ ____\n    //     \\// |   \\\//     \\\//     \\\//     \\\//     \\\// |   \\\n   //       \/  |    \\/       \\/  |    \\/     ---\/       \\/  |    \\\n  /·         \___     ·\     |  ·\        ·\____    \\__      ·\___     ·\\n /·         | \        ·\    |   ·\ |      ·\        ·\ |      ·\        ·\\n \___________ /________ /____|___ /_|______ /________ / |______ /________ /\n            \/        \/        \/        \/        \/        \/    ·cj·\/\n\n                              >>> 5D-User <<<\n\n          Code: SvEN tHE CREAToR/5D  Design: sNoW/5D\n\n---------------------------------------------------------------------------- \n\n         >>> C·O·N·T·E·N·T·S  O·F  D·O·C·U·M·E·N·T·A·T·I·O·N <<<\n\n\n                         @{"      Introduction      " Link Cap01}\n                         @{"      Requirements      " Link Cap02}\n                         @{"      Installation      " Link Cap03}\n                         @{"       Greetings!       " Link Cap05}\n                         @{"   How to Contact me?   " Link Cap06}\n\n         ---------------------------------------------------------\n              Complete Docs for 5D-User V1.00 [-5th Dynasty-]\n         ---------------------------------------------------------\n         The Documentation has been written by SvEN tHE CREAToR/5D.\n\n@endnode\n@node Cap01 "Introduction"\n  =======================================================================\n  5D-User is a command which allows the users to see the stats of all\n  people online at the bbs!\n  =======================================================================\n@endnode\n@node Cap02 "Requirements"\n  =======================================================================\n  To install 5D-User you must have the following things:\n\n    Programm     Location           Description\n    ----------   --------           -----------\n    5D-User Doors:5D-User Main program\n\n  - an  Amiga Model (500/600/1000/1200/2000/2500/3000/4000/CDTV/CD³²)\n  - the installed Version of OS\2, OS\3 or higher\n    (Soft- or Hardware Version)\n  - the installed .INFO Files in the directories.\n  - AmiExpress V2.xx , v3.xx or higher.\n\n  =======================================================================\n@endnode\n@node Cap03 "How to install 5D-User"\n  =======================================================================\n  To install 5D-User you must have all Requirement which were\n  mentioned below. You need the following things.\n\n  --------------------------\n    Doors:5D-User (dir)\n      ^^^ 5D-User\n    BBS:Commands/BBSCmd (dir)\n      ^^^ US.info\n  --------------------------\n\n  Decruch the 5D-User Archive. Go to your ''Doors:'' Directory\n  and make a Directory called ''5D-User''. Copy ''5D-User''\n  into the Directory. Go to your ''BBS:Commands/BBSCmd/'' Directory.\n  Copy ''US.info'' into it.\n  =======================================================================\n@endnode\n@node Cap05 "Greetings go to..."\n  =======================================================================\n\n           ···­­­> ALL MEMBERS OF 5TH DYNASTY <­­­···\n\n      +-----------------------------------------------------+\n      : And all cool people who I know and all who know me! :\n      `-----------------------------------------------------''\n\n  =======================================================================\n@endnode\n@node Cap06 "How to contact me..."\n  =======================================================================\n    ___________________________   ___________   ___________________________\n   /\_______________________ _ \¡/           \¡/  _ ______________________/\\n   \/                            ·5TH DYNASTY·                            \/\n    ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\_______________/¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n    CELTIC CROSS ............... Thunder ...... +49-Online Soon ....... WHQ\n    POWER BOX II NODE 0 ....... Wolfgang ...... +49-(0)30-3242112 ..... GHQ\n    POWER BOX II NODE 1 ....... Wolfgang ...... +49-(0)30-3242160 ..... GHQ\n    MIAMI HEAT ........ Sven The Creator ...... +49-(0)30-7424141 ..... GHQ\n    POWER BOX III ........ Frank Maxwell ...... +49-(0)30-4167884 ..... GHQ\n    5tH dYNASTY cLUB .............. sNoW ...... +49-(0)30-eLITE oNLY .. GHQ\n \n                 ___ ___    ___    _______    ___ ___    ___\n                /  ¬|  ¬\  /  ¬\  /      ¬\  /  ¬|  ¬\  /  ¬\\n               /         \/     \/         \/         \/     \\n              /           \      \          \          \      \\n            _/             \_     \_  |      \_         \_     \_\n            \      \ /      /      /          / \ /      /      /\n             \      |      /      /   |      /   |      /      /\n              \_____|____ /_____ /____|____ /____|____ /_____ /\n          /\            \/     \/         \/         \/     \/\n_________/  \  /\___________> 5TH DYNASTY GHQ <____________________ ___ __ _\n             \/    ___ ___    _______    _______    _______\n                  /  ¬|  ¬\  /      ¬\  /      ¬\  /      ¬\\n                 /    |    \/         \/         \/         \\n                /           \