INSERT INTO door_catalog VALUES('5d5esa10','5D5ESA10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5D5ESA10.LHA','5D^SYSAVAIL','XIM','5D^SYSAVAIL',NULL,'[tHE',NULL,'5 \____\   / \     \____\   __/     /  /   \ T/   / \__   \  T  \  / \___ \   \/___    / H/   /   \     \ |   \    \ /  \   \      /',replace('  ____________________/\___________________\n5 \____\   / \     \____\   __/     /  /   \\n T/   / \__   \  T  \  / \___ \   \/___    /\nH/   /   \     \ |   \    \ /  \   \      /\n/________/     /_|    \/   \____\___\    /\n[===/_________/==|____/_____\RpD!/______/==]\n|   5D-SysAvail V1.00 by [tHE aDDiCT/5D!]  |\n`------------------------------------------''\n','\n',char(10)),'5D^SYSAVAIL.GUIDE',replace('@DataBase 5D-SysAvail Documentation\n@Author [tHE aDDiCT/5D!]\n@Index Documentation\n\nCopyright © 1994 5tH DyNASTY\n\n@Remark $VER: 5D-SysAvail v1.00 18.6.1994\n@Remark AmigaGuide DataBase\n\n@node MAIN "5D-SysAvail v1.00 Docu Main Page"\n                                                              :\n                                                       :      ¦\n                   ________________  __________________¦      |\n            _______\_______       /  \             /   |      |______\n           |  __   _/     /______/____\  _     _  /    ¦      |  __  |\n           |  \/  _\________    \_\  / \/       \/     _      |  \/  |\n           |______\        /     / \/   |       |      /      |______|\n                   \___________ /       |_______|_____/       |Rpd!\n                              \/                     /________|\n                         :           :                                     :\n            ____   :     ¦     :     ¦      · 5 · T · H ·            :     ¦\n  __________\  /___¦    _|__/\ ¦     |_______ _______________________¦     |\n  \______   \\//   |    \____ \|     |   _   \\_____      /       /  |     |\n   /     \   \/    ¦     |   \ \     |   /    \/   /_____/    _  /   ¦     |\n _/       \   \_____     |    \ \_   |   _     \_____   \_     \/_____     |\n \       _/    /   /     |     \     |   /      /   /    /     |     /     |\n  \__________ /__________|     |\ ___|__/_____ /_______ /______|___________|\n            \/           |     ¦ \/          \/       \/\n                         ¦     :     · D · Y · N · A · S · T · Y ·\n                         :\n             ____             (×· PrESENTS ·×)\n            \\  /\n             \\/-----> 5D-SysAvail v1.00 by [tHE aDDiCT/5D!] <----\n              \/\n                         Coded by [tHE aDDiCT/5D!]\n                         Docu  by [tHE aDDiCT/5D!]\n                           ^                ^\n                           | @{"    Purpose   " Link Purpose} |\n                           | @{" Requirements " Link Requirements} |\n                           | @{" Installation " Link Installation} |\n                           | @{"   Important  " Link Important} |\n                           | @{"   Greetings  " Link Greetings} |\n                           `----------------'' \n\n@endnode\n\n@node "Purpose" "Purpose of 5D-SysAvail v1.00 by [tHE aDDiCT/5D!]"\n@toc "Purpose"\n\n              5D-SysAvail is a door that shows the User on the logon\n              sequence if the sysop is available for chat or not.\n\n              I didn`t include a "The-Sysop-is-not-available-but-\n              You-have-override-axs-WOW-super-duper-Option, b`cause\n              i think people with override Axs do know that they have\n              it!\n\n\n                            @{" Requirements " link "Requirements"}\n                            @{"  -> Main <-  " link "MAIN"}\n\n@endnode\n\n@node "Requirements" "Requirements for 5D-SysAvail v1.00 by [tHE aDDiCT/5D!]"\n@toc "Requirements"\n\n     You need an Amiga model 500/600/1000/1000 ..... (blabla)\n    \n     Installed Amiexpress software \n\n                            @{" Installation" link "Installation"}\n                            @{"  -> Main <- " link "MAIN"}\n\n@endnode\n@node "Installation" "Installation of "\n@toc "Installation"\n\n        5D-Sysavail is a Systemcommand door. It`s quite easy to install:\n   \n        @{"   /X 3.xx   " link "3er"}\n        @{"/X 2.xx & S!X" link "2er"}\n\n                            @{"  Important  " link "Important"}\n                            @{"  -> Main <- " link "MAIN"}\n\n@endnode\n\n@node "3er" "5D-SysAvail v1.00 by [tHE aDDiCT/5D!]"\n@toc "3er"\n\n        1. Just copy all the supplied .info files into the directories.\n\n        2. Place this line into Your logon.txt or bull<xx>.txt:\n\n           ~CC_SYSAVAIL\n\n           That`s all, Enjoy!       \n   \n\n                            @{" Installation " link "Installation"}\n                            @{"  -> Main <-  " link "MAIN"}\n\n@endnode\n\n@node "2er" "5D-SysAvail v1.00 by [tHE aDDiCT/5D!]"\n@toc "2er"\n\n\n        1. Add this line to Your Sys.Cmd :\n\n           SYSAVAIL  XM001DOORS:5D^SysAvail/5D^SysAvail\n\n        2. Copy the 5D^SysAvail - Drawer to Your Doors:\n\n        3. Place this line into Your logon.txt or bull<xx>.txt:\n\n           ~CC_SYSAVAIL\n\n           That`s all, Enjoy!\n\n\n                            @{" Installation " link "Installation"}\n                            @{"  -> Main <-  " link "MAIN"}\n\n@endnode\n\n@node "Important" "The 5th Dynasty Boards!"\n@toc "Important"\n\n                              ______ ______ __  __\n                             /  ___//_  __// /_/ /\n                          ___\__ \  /  /  /  _  /\n                         /_______/ /__/  /__//_/\n               ___ __  ___ _  __ _____ _____ ______ __   __\n              /   \\ \/  // \/ // _  // ___//_  __// /  / /\n             / /-  \\   //    // _  //__  / /  /  / /__/ /\n            /______//__//_/\_//_//_//____/ /__/  /____  /\n         ____________________________________________/ /\n        /_____________________________________________/MaD\n\n                 ----- --- --> The Boards! <-- --- -----\n\n                  ANTARCTICA       +49-30-XXXXXX  WHq\n  \n               Faceless World   +49-30-XXXXXX  SounderHQ\n  \n                 lASERdANCE       +49-21xx-XXXXX 2Ndz\n  \n            sCUMWHERE        +49-711-XXXX   3Ndz (2 iSDN RD)\n\n                  Funky Trading    +39-xxxx-XXXXX 2Ndz\n\n               Desert Strike +49-xxxx-XXXXXX 2Ndz (soon iSDN)\n\n\n                 ----- --- --> The Boards! <-- --- -----\n\n                            @{"  Greetings  " link "Greetings"}\n                            @{"  -> Main <- " link "MAIN"}\n\n@endnode\n@node "Greetings" "The Greetings of StC!"\n@toc "Greetings"\n\n\n          Rainman          - WANN iSDN ????\n          Snow             - Wie geht`s deiner 2. Dynastie ? \n          Airworx          - hehe\n    \n          [-sUPERGROBi!]   - Du liest dass ja sowieso nicht!\n          [-Joe Cool!]/M!  - Jaja.. der support\n          Gonzalez/M!      - Rexx rulz\n          Bilbo Baggins/M! - Cursor ist immer noch weg (nerv)\n          zAX/TTT          - YO!\n          CF/TTT           - Laaaaaangsam!\n          [tHE GiANTS/TyT] - Wir werden sie besiegen, die Icons\n          INCUBUS/TRSI     - paaaaaady\n\n              and all i`ve forgotten (sorry, but no time)\n\n                            @{"  That`s all " link "All"}\n                            @{"  -> Main <- " link "MAIN"}\n\n@endnode\n@node "All" "Hidden Node!"\n@toc "All"\n\nWoooooowwwww hidden Node!!! so call\n\n=====.====\================================)\==.========.======\=======.==\n    /|____)\.      .        .  /     .____/  \/|       /|       \     /|\n   /.      /|  \  /|       /|\/(_____|      // | \    / |_______)\   / |\n  //     //.|__)\/.|__    /.| \      |     //  |_)\  /. |______  \\ /. |\n /  _____/  ____/ :|  \  // |: \\   :|    // __|   \//__l  /  |___///__l\n \___  \//  \/  \  :   \//     .\\  |:    /  \___   \ ___)//  _ .\/  ___)\n / \/  \\\      /  |   /    Y   \\  . .  /\    |    /    \_  .|  \\\    \_\n//______/\  ___/\  ___/ ____|_____\__|  /  \  _|___/______/  :|___ \___  /\n\(========\(=====\(===\(=============| /====\(==========/ ____|===)/===)/=\n \         `      `    \             |/      \          \(        /    /\n                                       `                   `\n\n\n                            @{"  -> Main <- " link "MAIN"}\n\n@endnode\n','\n',char(10)),NULL,'auto-added',17248,2,0,NULL,NULL,'5d_sya10','scan',1780048358);
INSERT INTO door_catalog VALUES('5dpage28','5DPAGE28.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5DPAGE28.LHA','5D-Page','XIM','5D-Page',NULL,'5D......',NULL,NULL,replace('AmiExpress SysOp-page door.. By 5D......\n','\n',char(10)),'5D-Page.guide',replace('@database 5D-PageDoc\n\nCopyright (c) 1993 SvEN tHE CREAToR / 5th Dynasty\n\n@Remark $VER: (August 18 1993, 20:29:14)\n@Remark AmigaGuide database for the 5D-Page Documentation\n\n@node MAIN "5D-Page Documentation (c)1993 SvEN tHE CREAToR of 5th Dynasty (August 18 1993, 20:29:14)"\n          ______    ______    ______    ______    ______    ______\n          \   ¬/    \   ¬/    \   ¬/    \   ¬/    \   ¬/    \   ¬/\n 5th ______\  /_ ____\  /______\  /______\  /______\  /______\  /_ ____\n    //     \\// |   \\\//     \\\//     \\\//     \\\//     \\\// |   \\\n   //       \/  |    \\/       \\/  |    \\/     ---\/       \\/  |    \\\n  /·         \___     ·\     |  ·\        ·\____    \\__      ·\___     ·\\n /·         | \        ·\    |   ·\ |      ·\        ·\ |      ·\        ·\\n \___________ /________ /____|___ /_|______ /________ / |______ /________ /\n            \/        \/        \/        \/        \/        \/    ·cj·\/\n\n                              >>> 5D-Page <<<\n\n                Code: SvEN tHE CREAToR/5D  GFX: Cee Jay/5D\n\n---------------------------------------------------------------------------- \n\n         >>> C·O·N·T·E·N·T·S  O·F  D·O·C·U·M·E·N·T·A·T·I·O·N <<<\n\n                         @{"      Introduction      " Link Cap01}\n                         @{"      Requirements      " Link Cap02}\n                         @{"      Installation      " Link Cap03}\n                         @{"       Greetings!       " Link Cap05}\n                         @{"   How to Contact me?   " Link Cap06}\n\n         ---------------------------------------------------------\n              Complete Docs for 5D-Page V2.81 [-5th Dynasty-]\n         ---------------------------------------------------------\n         The Documentation has been written by SvEN tHE CREAToR/5D.\n\n@endnode\n@node Cap01 "Introduction"\n  =======================================================================\n  5D-Page is a replacement for the normal Page SysOp Command\n  of AmiExpress ''O''.\n  =======================================================================\n@endnode\n@node Cap02 "Requirements"\n  =======================================================================\n  To install 5D-Page you must have the following things:\n\n    Programm     Location           Description\n    ----------   --------           -----------\n    5D-Page      Doors:5D-Page      Main program\n\n  - an  Amiga Model (500/600/1000/1200/2000/2500/3000/4000/CDTV/CD³²)\n  - the installed Version of OS\2, OS\3 or higher\n    (Soft- or Hardware Version)\n  - the installed .INFO Files in the directories.\n  - AmiExpress V2.xx , v3.xx or higher.\n\n  =======================================================================\n@endnode\n@node Cap03 "How to install 5D-Page"\n  =======================================================================\n  To install 5D-Page you must have all Requirement which were\n  mentioned below. You need the following things.\n\n  --------------------------\n    Doors:5D-Page (dir)\n      ^^^ 5D-Page\n    BBS:Commands/BBSCmd (dir)\n      ^^^ O.info\n  --------------------------\n\n  Decruch the 5D-Page Archive. Go to your ''Doors:'' Directory\n  and make a Directory called ''5D-Page''. Copy ''5D-Page''\n  into the Directory. Go to your ''BBS:Commands/BBSCmd'' Directory.\n  Copy ''O.info'' into it.\n  =======================================================================\n@endnode\n@node Cap05 "Greetings go to..."\n  =======================================================================\n\n           ···­­­> ALL MEMBERS OF 5TH DYNASTY <­­­···\n\n                           ByteAndi/Mst\n                            Celator/TT\n                           Executor/DCS\n                              FuZzY\n                           Mr.Return/AG\n\n      +-----------------------------------------------------+\n      : And all cool people who I know and all who know me! :\n      `-----------------------------------------------------''\n\n  =======================================================================\n@endnode\n@node Cap06 "How to contact me..."\n  =======================================================================\n\n    .     /\_________  ______/\  /\______    /\_________  ______/\   .\n    .    _\______   .\ \______/ _\____   \  _\______   .\ \______/   .\n    :   /   _/ _/    \\/     .\/   __|   .\/   _/ _/    \\/     .\   :\n    |  /    \  \      \\      \\   \__    \\   \  \      \\      \\  |\n    +--\_____\__\       \____ //_____|     \\___\__\       \____ //--+\n    :            \  ____/    \/      |______/       \  ____/    \/   :\n    .             \/                                 \/              .\n               ___.\n              /  .|___    _______/\    /\______    ___________/\\n             /   ||   \  _\_  ____/_  _\____   \  _\_  __      /\n            /         .\/      /   .\/   __|   .\/     \______/\n           /      _    \\    _/     \\   \__    \\         .\\n           \______|     \\_________  /_____|     \\_______ //\n                  |______/         \/      |______/       \/\n\n               ···­­­>   \%\ 5TH DYNASTY GHQ \%\   <­­­···\n\n                        SYSOP: SvEN tHE CREAToR\n                        COSYS: Mr.Return\n                               Cee Jay\n\n                    -<>- CaLL: +49-(0)30-742-4141 -<>-\n\n  =======================================================================\n@endnode\n','\n',char(10)),NULL,'auto-added',10981,2,0,NULL,NULL,'5d_pag29','scan',1780048358);
INSERT INTO door_catalog VALUES('5d_amn10','5D_AMN10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5D_AMN10.LHA','5D-AdiMenu','XIM','5D-AdiMenu',NULL,'[tHE','5D','5(___  / ¬|  ___.  ____  /  ____  ____ ¬|  ) T/  /  \__   \ ¬|  \  _  \___ ¬\  ¬\ \__   \ H\___  /___  /  |__/  |__/_____/___/_____  /',replace('  ________._____________________________.__\n5(___  / ¬|  ___.  ____  /  ____  ____ ¬|  )\nT/  /  \__   \ ¬|  \  _  \___ ¬\  ¬\ \__   \\nH\___  /___  /  |__/  |__/_____/___/_____  /\n.   ¬\/tGø¬\/___| \___|                 ¬\/.\n|    5D-AdiMenu V1.0 by [tHE aDDiCT/5D!]   |\n| Handles Textfiles like Commands, so use  |\n:  it as Doormenu, Filemenu or whatever!   |\n|  fully coded in C,  fully configurable!  |\n`------------------------------------------''\n','\n',char(10)),'5D-AdiMUI.Guide',replace('@database "5th Dynasty - 5D-AdiMenu V1.0"\n@AUTHOR "[tHE aDDiCT/5D!]"\n@(C) "[tHE aDDiCT/5D!]"\n@Ver$ "5th Dynasty - 5D-AdiMenu V1.0 (10-07-94)   \n@HEIGHT 30\n@Node MAIN "5D-AdiMenu V1.0"\n\n.............................................................................\n                                             ..............@{" "link "HIDE"}.................\n                      _/\________________________/\_.........................\n                      \__   ________  ____   I   __/      ...................\n  [tHE aDDiCT/5D!]     _\____    \/    \/         \            ..............\n                      /     !     \     \    T     \               ..........\n  > 5D-/X-dESiGN <   /      ______/_____/____j      \                 .......\n                     \______j                l______/                    ....\n_/\_______ __________ __________ __________ ___________________________/\_ ..\n\______   \\__   I   \\__       \\__   _   \\__   ________  ____   I   __/  .\n /    |    \/\____    \/    T    \/   _j    \_\____    \/    \/\____    \\n/     !     \    !     \    |     \   l_     \    !     \     \    !     \\n\______      \_________/____l_____/____l_____/__________/_____/_____      \\n      l______/                                                     l______/\n                    5D-AdiMenu V1.0 by [tHE aDDiCT/5D!]\n             _ __ ___ ________________________________ __ _ _\n                     Y    .--------------------.\n                     :    |   @{"  Disclaimer  " link "Disc"}   |\n.                    .    :   @{" Requirements " link "Req"}   : \n..                   .        @{" Installation " link "Inst"}    \n....                      .   @{" How it works " link "What"}\n.......                   |   @{"   CallNow    " link "CallNow"}   |\n.........                 |   @{"  Greetings   " link "Greet"}   |\n.............             `--------------------''\n..................\n..........................\n.............................................................................\n\n\n@endnode\n\n@node "Disc"\n@toc "Disc"\n\n              5D-AdiMenu was first designed as a Doormenu....\n\n        But it works in a quite strange way, which lets 5D-AdiMenu\n             act like some kind of ~SS_ - replacement... hehe\n\n    Well You can define Textfiles like Commands now, and in this case,\n  You can give them Access-levels and Multi- or Single-command options, \n                           like in normal doors!\n\n\n                             @{" HALLELUJA! " link "MAIN"}\n\n@endnode\n\n@node "Req" "Requirements"\n@toc "Req"\n\n       Any Amiga (500,600,1000,1200,2000,3000,4000,4000T,5000(?)....\nit should also run on a Sinclair ZX81, but i hadn`t got the  chance to test!\n                   Installed S-Express, /X 2.xx or 3.xx\n                           Some bottles of Bluna\n                       A dead cat (black preferred)\n                        Some chilpi-wongo-wacklers\n                   Some nights playing Gravity Force II\n\n                            @{" BACK TO MAIN MENU? " link "MAIN"}\n\n@endnode\n@node "Inst" "Installing 5D-AdiMenu V1.0"\n@toc "Inst"\n\nJust copy the files\n\n                   5D-AdiMenu\n                   5D-AdiMUI.Guide\n\n          and the drawer\n\n                   @{"TEXT" link "TEXT"}\n\n                   to DOORS:5D-AdiMenu/\n\n-------------------------------------------------------\n/X 2.xx or S-Express:\n\nCopy the drawer 5D-AdiMenu to DOORS:\n\nEdit Your BBS.CMD and snap in the following:\n\n*Nameofdoor      XM001DOORS:5D-AdiMenu/5D-AdiMenu\n-------------------------------------------------------\n/X 3.xx:\n\nCopy the drawer 5D-AdiMenu to DOORS:\n\nJust create an icon and copy it to Your SYSCMD-Directory\n(see the examples inside the archive!!!!)\n\n                            @{" BACK TO MAIN MENU? " link "MAIN"}\n@endnode\n@node "What" "---> What it does: <---"\n@toc "What"\n\n        5D-AdiMenu reads the Commandline, which means it looks for\n       the command it was launched with... Well it`s simple, I just\n     can`t explain how it works, but it`s quite simple.... so... try \n             it out.. sorry.... a well.. let`s have a drink...\n\n                            @{" YES !" link "MAIN"}\n@endnode\n@node "TEXT" "drawer TEXT"\n@toc "TEXT"\n\n    In the drawer DOORS:5D-ADIMENU/TEXT, there are all those Textfiles,\n                     You assigned the commands to....\n \n    E.G. if You have a command called "DOORS", the textfile You want to\n               display must be DOORS:5D-ADIMENU/TEXT/DOORS .\n   This Textfile can contain ANSI-Codes, MCI-messages, Screenclearers or\n                  whatever You want (even Ketchup!).... \n\n                          @{" Hummhumm " link "Inst"}\n@endnode\n@node "Greet" "---> Greetings <---"\n@toc "Greet"\n\ngreetings fly to:\n\n      tHE lIVING dEAD/tHE gIANTS/mUSHROOM/jAKE&eLWOOD <- Caesium `94!\n          Sven the Creator/5D <- You should join my coding conf.!\n                        Joe Cool/M! <- FORMAT BBS:\n                     INNUENDO <- Ja! Maekel mich voll!\n                 [-Treach!] <- Wehting for se next colli!\n           Airworx/5D & SNOW/5D <- Muss doch ma nach beeerlin...\n               Murphy & Intercode/BB <- Yo, test the west !\n                  Bilbo Baggins/M! <- Aehm.. im Urlaub ?\n                      Gonzalez/M! <- Muffig Inc. 94 ?\n                         E.F.A./PARAFiX <- Gruen!\nJordan/5D <- Bitte blaeh die Archive net so auf, sonst sag ich ORS zu dir!\n                      Spider/ORS <- A propos ORS, hi!\n                         Supergrobi <- Elitelizer\n                    Pater Pink/ARS <- Keep Arise alive!\n        MaD FøRcE/5D <- Weiter so! Mach mir auch mal nen Ansi,thX!\n                            Steel/5D <- Jupsa!\n\n                    to my girl (there can only be one!)\n\n                      and to all the Users of my BBS!\n\n                                 @{" RiGHT ! " link "MAIN"}\n@endnode\n\n@node "CallNow" "CallNow....."\n@toc "CallNow"\n\n¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%\n%               __________/\  ____  /\________________/\                     ¾\n¾              5\_____\  /  \/ _  \/  \   ____/    / /  \                    %\n%              tH/   / \__   \_/   \   \____ \_  \/__    \_                  ¾\n¾              _/   /   \     /     \_  \_ /  /   \_      /                  %\n%              \________/____/_______/___/___/_____/_____/ bOARDS            ¾\n¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%\n%                                                                            ¾\n¾ -=>  cELTIC cROSS ..........[    tHUNDER   ].. +49-333-aSK-4-iT  < WHQ>    %\n% -=>  aNTaRCTICA ............[      sNOW    ].. +49-306-aSK-4-iT  < GHQ>    ¾\n¾ -=>  fACElESS wORLD ........[    aIRwORX   ].. +49-304-aSK-4-iT  < GHQ>    %\n¾ -=>  sCUMwHERE #0 ..........[  tHE aDDICT  ].. +49-711-aSK-4-iT  < GHQ>    %\n%      sCUMwHERE #IsdN .......[  tHE aDDICT  ].. +49-711-aSK-4-iT  < GHQ>    ¾\n¾ -=>  lASERdANCE #0 .........[    jORDAN    ].. +49-210-aSK-4-iT  < GHQ>    %\n%      lASERdANCE #1 .........[    jORDAN    ].. +49-210-aSK-4-iT  < GHQ>    ¾\n¾ -=>  fUNKY tRADING #0 ......[   mAVERICK   ].. +39-828-aSK-4-iT  < IHQ>    %\n%      fUNKY tRADING #1 ......[   mAVERICK   ].. +39-828-aSK-4-iT  < IHQ>    ¾\n¾ -=>  dISoRDER ..............[    mARWIN    ].. +46-456-aSK-4-iT  < SHQ>    %\n% -=>  dREAMsCAPE ............[     sCAN     ].. +31-525-aSK-4-iT  <NLHQ>    ¾\n¾ -=>  wORLD oF wONDER #0 ....[    sTARcAM   ].. + 1-410-aSK-4-iT  <USHQ>    %\n%      wORLD oF wONDER #1 ....[    sTARcAM   ].. + 1-410-aSK-4-iT  <USHQ>    ¾\n¾ -=>  nEEDfUL tHINGS ........[ lELAND gAUNT ].. + 1-508-aSK-4-iT  <USHQ>    %\n%                                                                            ¾\n¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%\n\n                                 @{" ATDT ! " link "MAIN"}\n\n@endnode\n\n@node "HIDE" "hidden Note....."\n@toc "Call"\n\n                       >iSDN cAllERS vERY wElCOME! <\n                       ..............................\n\n\n                                           \\n=====.====\================================)\==.========.======\=======.==\n    /|____)\.      .        .  /     .____/  \/|       /|       \     /|\n   /.      /|  \  /|       /|\/(_____|      // | \    / |_______)\   / |\n  //     //.|__)\/.|__    /.| \      |     //  |_)\  /. |______  \\ /. |\n /  _____/  ____/ :|  \  // |: \\   :|    // __|   \//__l  /  |___///__l\n \___  \//  \/  \  :   \//     .\\  |:    /  \___   \ ___)//  _ .\/  ___)\n / \/  \\\      /  |   /    Y   \\  . .  /\    |    /    \_  .|  \\\    \_\n//______/\  ___/\  ___/ ____|_____\__|  /  \  _|___/______/  :|___ \___  /\n\(========\(=====\(===\(=============| /====\(==========/ ____|===)/aDi)/=\n \         `      `    \             |/      \          \(        /    /\n                    5th      dYNASTY `  hEADQUAtER!      \\n\n\n     rUNNiNG oN aN A4ooo/o3o/6mb/55ohD   aMi-EXPRESS nEWEST! vERiON!  \n\n     sYSOP: mACHINE  cO`s: [tHE aDDiCT/5D!]   nODE0:   +49-711-lOCAl!\n                           [-sUPERGROBI!]     nODE1:   +49-711-zYXEL 19,2\n                           [-jOE cOOL-]/M!    nODE2+3: +49-711-iSDN 64kB RD\n                 \n    aMiGA oNLY - sPECiAL sEX & /X tOOLS cONF - dEMO & aGA cONFERENCE! \n\n             ==>>   sPECiAl /X-tOOlS cODiNG cONfERENCE!   <==\n\n     ]=[ iNVITED uSERS oNLY! ]=[ pRiVATE sYSTtEM = nUP rEQUiRED! ]=[ \n==========================================================================\n\n                             @{" HALLELUJA! " link "MAIN"}\n@endnode\n','\n',char(10)),NULL,'auto-added',37742,11,1,'games','Doors/5D-AdiMenu','5d_amn10','scan',1780048365);
INSERT INTO door_catalog VALUES('5d_amu20','5D^AMU20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5D^AMU20.LHA','5d-adimui','XIM','5d-adimui',NULL,'[tHE',NULL,'5(___  / ¬|  ___.  ____  /  ____  ____ ¬|  ) T/  /  \__   \ ¬|  \  _  \___ ¬\  ¬\ \__   \ H\___  /___  /  |__/  |__/_____/___/_____  /',replace('  ________._____________________________.__\n5(___  / ¬|  ___.  ____  /  ____  ____ ¬|  )\nT/  /  \__   \ ¬|  \  _  \___ ¬\  ¬\ \__   \\nH\___  /___  /  |__/  |__/_____/___/_____  /\n.   ¬\/tGø¬\/___| \___|                 ¬\/.\n|    5D-AdiMui V2.0 by [tHE aDDiCT/5D!]    |\n| Allows You to have more than one Sysop!  |\n| fully coded in C,  highly configurable!  |\n`------------------------------------------''\n','\n',char(10)),'5D-AdiMUI.Guide',replace('@database "5th Dynasty - 5D-AdiMui V2.0"\n@AUTHOR "[tHE aDDiCT/5D!]"\n@(C) "[tHE aDDiCT/5D!]"\n@Ver$ "5th Dynasty - 5D-AdiMui V2.0 (10-07-94)   \n@HEIGHT 30\n@Node MAIN "5D-AdiMui V2.0"\n\n.............................................................................\n                                             ................................\n                      _/\________________________/\_.........................\n                      \__   ________  ____   I   __/      ...................\n  [tHE aDDiCT/5D!]     _\____    \/    \/         \            ..............\n                      /     !     \     \    T     \               ..........\n  > 5D-/X-dESiGN <   /      ______/_____/____j      \                 .......\n                     \______j                l______/                    ....\n_/\_______ __________ __________ __________ ___________________________/\_ ..\n\______   \\__   I   \\__       \\__   _   \\__   ________  ____   I   __/  .\n /    |    \/\____    \/    T    \/   _j    \_\____    \/    \/\____    \\n/     !     \    !     \    |     \   l_     \    !     \     \    !     \\n\______      \_________/____l_____/____l_____/__________/_____/_____      \\n      l______/                                                     l______/\n                    5D-AdiMui V2.0 by [tHE aDDiCT/5D!]\n             _ __ ___ ________________________________ __ _ _\n                     Y    .--------------------.\n                     :    |   @{"  Disclaimer  " link "Disc"}   |\n.                    .    :   @{" Requirements " link "Req"}   : \n..                   .        @{" Installation " link "Inst"}    \n....                      .   @{" How it works " link "What"}   .\n......                    :   @{" Future Plans " link "Plans"}   :\n.........                 |   @{"  Greetings   " link "Greet"}   |\n.............             `--------------------''\n..................\n..........................\n.............................................................................\n\n\n                                                                      @{" "link "HIDE"}\n@endnode\n\n@node "Disc"\n@toc "Disc"\n\n                              What is it ???\n        5D-AdiMui is a tool which lets You have more than one local\n  Sysop available for chatting..... I wrote this tool for my girlfriend,\n     who likes to chat sometimes if someone`s on my BBS she knows....\n\n Meanwhile 5D-AdiMui has advanced to a very helpful tool, cause everytime\n my drunken Cosysops are sitting in front of my computer they always want\nto chat, and they also wanted their own "Hello hier is Plumpaquatsch"-Ansi!\n\n Because my Arexx-door (see TT_MUC10.LHA, my one and only /X tool for TT)\nwas too slow, and crashed sometimes (/X REXXPort suxx), i decided to re-code\n                it in C ... and... well... here it is.....\n\n                             @{" HALLELUJA! " link "MAIN"}\n\n@endnode\n\n@node "Req" "Requirements"\n@toc "Req"\n\n       Any Amiga (500,600,1000,1200,2000,3000,4000,4000T,5000(?)....\nit should also run on a Sinclair ZX81, but i hadn`t got the  chance to test!\n                   Installed S-Express, /X 2.xx or 3.xx\n                     Some bottles of Wine/Beer/Whiskey\n                       A dead cat (black preferred)\n                        Some chilpi-wongo-wacklers\n\n                            @{" BACK TO MAIN MENU? " link "MAIN"}\n\n@endnode\n@node "Inst" "Installation - PeiTSch dEN SueSs-Op V0.8743874"\n@toc "Inst"\n\nJust copy the files\n                     @{"STARTCHAT1.txt" link "Chat1"}  \n                     @{"STARTCHAT2.txt" link "Chat2"}   \n                     @{"STARTCHAT3.txt" link "Chat3"}\n                     ......\n\n\n                   to DOORS:5D-AdiMui/\n\nand edit them to Your Needs!\n\nThen edit 5D-AdiMui.CFG:\n   \n             1.line: DO NOT REMOVE (identifier)\n             2.line: Name of Sysop belonging to Startchat1.txt\n             3.line: Name of Sysop belonging to Startchat2.txt\n             4.line: Name of Sysop belonging to Startchat3.txt\n             .......\n\n-------------------------------------------------------\n/X 2.xx or S-Express:\n\nCopy the drawer 5D-AdiMui to DOORS:\n\nEdit Your SYS.CMD and snap in the following:\n\n*CST      XM001DOORS:5D-AdiMui/5D-AdiMui\n-------------------------------------------------------\n/X 3.xx:\n\nCopy the drawer 5D-AdiMui to DOORS:\n\nJust copy the CST icon to Your SYSCMD-Directory and \n-------------------------------------------------------\nthen edit your BBS:NODEx/STARTCHAT.TXT\n       or your BBS:BBSTEXTS/STARTCHAT.TXT\n\ninsert the following line at the start of this text:\n\n~CC_CST\n\n                            @{" BACK TO MAIN MENU? " link "MAIN"}\n@endnode\n@node "What" "---> What it does: <---"\n@toc "What"\n\n If somebody tries to page you, you`ll be able to answer his chat-request\n               by simply pressing F1 .... (like ever before)\n then, the BBS will display the BBS:NODEx/STARTCHAT.TXT (also nothing new)\n\n          The User will be prompted that the sysop is coming....\nIn this moment, it will start the 5D-AdiMui door via MCI-command (the ~CC_)!\n       Then the sysop on the console sees a menu where he can choose\n  which startchat<x>.txt (in DOORS:5D-AdiMui/) he wants to be displayed!\n\n\n                            @{" Wow !" link "MAIN"}\n@endnode\n@node "Chat1" "STARTCHAT1.txt"\n@toc "Chat1"\n\n              This Text will be displayed if You do press "1"\n                   This should be the default-sysop-text\n\n              A line will be added to the Callerslog, saying:\n             5D-AdiMUI! Chat answerd to <USER> by <SYSOP(1)> \n\n                          @{" Hummhumm " link "Inst"}\n@endnode\n@node "Chat2" "STARTCHAT2.txt"\n@toc "Chat2"\n\n               This text will be displayed if Your press "2"\n         good for girlfriends, or Your Cosysop sitting beside You!\n\n              A line will be added to the Callerslog, saying:\n             5D-AdiMUI! Chat answerd to <USER> by <SYSOP(2)> \n\n                           @{" Yarp ! " link "Inst"}\n@endnode\n@node "Chat3" "STARTCHAT3.txt"                     \n@toc "Chat3"                                             \n\n               This text will be displayed if Your press "3"\n          cause i don`t know, how much girlfriends you have =8-)\n      I use this option for my chat-maniac-cosysops (maybe someday to\n                  combine it with a multichat-option)...\n\n              A line will be added to the Callerslog, saying:\n             5D-AdiMUI! Chat answerd to <USER> by <SYSOP(3)> \n\n                                            \n                          @{" Hehehe ! " link "Inst"}\n@endnode\n@node "Plans" "Future plans"                             \n@toc "Plans"                                               \n                \n - I want to integrate the reqtools some day, cause of those OPWIN users!\n\n                        @{" Woobeegreat! " link "MAIN"}\n@endnode\n@node "Greet" "---> Greetings <---"\n@toc "Greet"\n\ngreetings fly to:\n\ntHE lIVING dEAD/tHE gIANTS/mUSHROOM/jAKE & eLWOOD <- This is the Tool for YOU!\n          Sven the Creator/5D <- You should join my coding conf.!\n                     Joe Cool/M! <- C - Coding rulez!\n    Airworx/5D & SNOW/5D <- Mist Ihr habt ja nur jeweils ein Handle ;)\n               Murphy & Intercode/BB <- Yo, test the west !\n               Treach! <- Wann kommt die nexte Azkii-colli ?\nBilbo Baggins/M! <- Deine Routinen sin alle gut, aber ich bin zu dumm dafuer.\n                  Gonzalez/M! <- Wann kommt Realog in C ?\n                         E.F.A./PARAFiX <- Frull ?\nJordan/5D <- Bitte blaeh die Archive net so auf, sonst sag ich ORS zu dir!\n                      Spider/ORS <- A propos ORS, hi!\n                         Supergrobi <- Kicher `94\n                    Pater Pink/ARS <- Keep Arise alive!\n              MaD FøRcE/5D <- Mach mir auch mal nen Ansi,thX!\n           Innuendo <- Du bist der Stinkhund unter den Pedanten!\n\n                    to my girl (there can only be one!)\n\n                      and to all the Users of my BBS!\n\n\n        Habichnochjemandvergessentutmirleidlasstsmichhaltwissen....\n\n                                 @{" So sei es! " link "MAIN"}\n@endnode\n\n@node "CallNow" "CallNow....."\n@toc "CallNow"\n\n¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%\n%               __________/\  ____  /\________________/\                     ¾\n¾              5\_____\  /  \/ _  \/  \   ____/    / /  \                    %\n%              tH/   / \__   \_/   \   \____ \_  \/__    \_                  ¾\n¾              _/   /   \     /     \_  \_ /  /   \_      /                  %\n%              \________/____/_______/___/___/_____/_____/ bOARDS            ¾\n¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%\n%                                                                            ¾\n¾ -=>  cELTIC cROSS ..........[    tHUNDER   ].. +49-333-aSK-4-iT  < WHQ>    %\n% -=>  aNTaRCTICA ............[      sNOW    ].. +49-306-aSK-4-iT  < GHQ>    ¾\n¾ -=>  fACElESS wORLD ........[    aIRwORX   ].. +49-304-aSK-4-iT  < GHQ>    %\n¾ -=>  sCUMwHERE #0 ..........[  tHE aDDICT  ].. +49-711-aSK-4-iT  < GHQ>    %\n%      sCUMwHERE #IsdN .......[  tHE aDDICT  ].. +49-711-aSK-4-iT  < GHQ>    ¾\n¾ -=>  lASERdANCE #0 .........[    jORDAN    ].. +49-210-aSK-4-iT  < GHQ>    %\n%      lASERdANCE #1 .........[    jORDAN    ].. +49-210-aSK-4-iT  < GHQ>    ¾\n¾ -=>  fUNKY tRADING #0 ......[   mAVERICK   ].. +39-828-aSK-4-iT  < IHQ>    %\n%      fUNKY tRADING #1 ......[   mAVERICK   ].. +39-828-aSK-4-iT  < IHQ>    ¾\n¾ -=>  dISoRDER ..............[    mARWIN    ].. +46-456-aSK-4-iT  < SHQ>    %\n% -=>  dREAMsCAPE ............[     sCAN     ].. +31-525-aSK-4-iT  <NLHQ>    ¾\n¾ -=>  wORLD oF wONDER #0 ....[    sTARcAM   ].. + 1-410-aSK-4-iT  <USHQ>    %\n%      wORLD oF wONDER #1 ....[    sTARcAM   ].. + 1-410-aSK-4-iT  <USHQ>    ¾\n¾ -=>  nEEDfUL tHINGS ........[ lELAND gAUNT ].. + 1-508-aSK-4-iT  <USHQ>    %\n%                                                                            ¾\n¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%\n\n                                 @{" ATDT ! " link "MAIN"}\n\n@endnode\n\n@node "HIDE" "hidden Note....."\n@toc "Call"\n\n                       >iSDN cAllERS vERY wElCOME! <\n                       ..............................\n\n\n                                           \\n=====.====\================================)\==.========.======\=======.==\n    /|____)\.      .        .  /     .____/  \/|       /|       \     /|\n   /.      /|  \  /|       /|\/(_____|      // | \    / |_______)\   / |\n  //     //.|__)\/.|__    /.| \      |     //  |_)\  /. |______  \\ /. |\n /  _____/  ____/ :|  \  // |: \\   :|    // __|   \//__l  /  |___///__l\n \___  \//  \/  \  :   \//     .\\  |:    /  \___   \ ___)//  _ .\/  ___)\n / \/  \\\      /  |   /    Y   \\  . .  /\    |    /    \_  .|  \\\    \_\n//______/\  ___/\  ___/ ____|_____\__|  /  \  _|___/______/  :|___ \___  /\n\(========\(=====\(===\(=============| /====\(==========/ ____|===)/aDi)/=\n \         `      `    \             |/      \          \(        /    /\n                    5th      dYNASTY `  hEADQUAtER!      \\n\n\n     rUNNiNG oN aN A4ooo/o3o/6mb/55ohD   aMi-EXPRESS nEWEST! vERiON!  \n\n     sYSOP: mACHINE  cO`s: [tHE aDDiCT/5D!]   nODE0:   +49-711-lOCAl!\n                           [-sUPERGROBI!]     nODE1:   +49-711-zYXEL 19,2\n                           [-jOE cOOL-]/M!    nODE2+3: +49-711-iSDN 64kB RD\n                 \n    aMiGA oNLY - sPECiAL sEX & /X tOOLS cONF - dEMO & aGA cONFERENCE! \n\n             ==>>   sPECiAl /X-tOOlS cODiNG cONfERENCE!   <==\n\n     ]=[ iNVITED uSERS oNLY! ]=[ pRiVATE sYSTtEM = nUP rEQUiRED! ]=[ \n==========================================================================\n\n                             @{" HALLELUJA! " link "MAIN"}\n@endnode\n','\n',char(10)),NULL,'auto-added',20410,1,0,NULL,NULL,'5d_amu20','scan',1780048358);
INSERT INTO door_catalog VALUES('5d_amu21','5D_AMU21.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5D_AMU21.LHA','5d-adimui','XIM','5d-adimui',NULL,'[tHE','5D','5(___  / ¬|  ___.  ____  /  ____  ____ ¬|  ) T/  /  \__   \ ¬|  \  _  \___ ¬\  ¬\ \__   \ H\___  /___  /  |__/  |__/_____/___/_____  /',replace('  ________._____________________________.__\n5(___  / ¬|  ___.  ____  /  ____  ____ ¬|  )\nT/  /  \__   \ ¬|  \  _  \___ ¬\  ¬\ \__   \\nH\___  /___  /  |__/  |__/_____/___/_____  /\n.   ¬\/tGø¬\/___| \___|                 ¬\/.\n|    5D-AdiMui V2.1 by [tHE aDDiCT/5D!]    |\n|  Allows You to have more than one Sysop! |\n|  fully coded in C,  fullly configurable! |\n|     Added a Sysop`s Coming-feature!      |\n`------------------------------------------''\n','\n',char(10)),'5D-AdiMUI.Guide',replace('@database "5th Dynasty - 5D-AdiMui V2.1"\n@AUTHOR "[tHE aDDiCT/5D!]"\n@(C) "[tHE aDDiCT/5D!]"\n@Ver$ "5th Dynasty - 5D-AdiMui V2.1 (15-07-94)   \n@HEIGHT 30\n@Node MAIN "5D-AdiMui V2.1"\n\n.............................................................................\n                                             ................................\n                      _/\________________________/\_.........................\n                      \__   ________  ____   I   __/      ...................\n  [tHE aDDiCT/5D!]     _\____    \/    \/         \            ..............\n                      /     !     \     \    T     \               ..........\n  > 5D-/X-dESiGN <   /      ______/_____/____j      \                 .......\n                     \______j                l______/                    ....\n_/\_______ __________ __________ __________ ___________________________/\_ ..\n\______   \\__   I   \\__       \\__   _   \\__   ________  ____   I   __/  .\n /    |    \/\____    \/    T    \/   _j    \_\____    \/    \/\____    \\n/     !     \    !     \    |     \   l_     \    !     \     \    !     \\n\______      \_________/____l_____/____l_____/__________/_____/_____      \\n      l______/                                                     l______/\n                    5D-AdiMui V2.1 by [tHE aDDiCT/5D!]\n             _ __ ___ ________________________________ __ _ _\n                     Y    .--------------------.\n                     :    |   @{"  Disclaimer  " link "Disc"}   |\n.                    .    :   @{" Requirements " link "Req"}   : \n..                   .        @{" Installation " link "Inst"}    \n....                      .   @{" How it works " link "What"}   .\n......                    :   @{"   History    " link "History"}   :\n.........                 |   @{"  Greetings   " link "Greet"}   |\n...........               |   @{"  Call Now!   " link "CallNow"}   |\n.............             `--------------------''\n..................\n..........................\n.............................................................................\n\n\n                                                                      @{" "link "HIDE"}\n@endnode\n\n@node "Disc"\n@toc "Disc"\n\n                              What is it ???\n        5D-AdiMui is a tool which lets You have more than one local\n  Sysop available for chatting..... I wrote this tool for my girlfriend,\n     who likes to chat sometimes if someone`s on my BBS she knows....\n\n Meanwhile 5D-AdiMui has advanced to a very helpful tool, cause everytime\n my drunken Cosysops are sitting in front of my computer they always want\nto chat, and they also wanted their own "Hello hier is Plumpaquatsch"-Ansi!\n\n Because my Arexx-door (see TT_MUC10.LHA, my one and only /X tool for TT)\nwas too slow, and crashed sometimes (/X REXXPort suxx), i decided to re-code\n                it in C ... and... well... here it is.....\n\n                             @{" HALLELUJA! " link "MAIN"}\n\n@endnode\n\n@node "Req" "Requirements"\n@toc "Req"\n\n       Any Amiga (500,600,1000,1200,2000,3000,4000,4000T,5000(?)....\nit should also run on a Sinclair ZX81, but i hadn`t got the  chance to test!\n                   Installed S-Express, /X 2.xx or 3.xx\n                     Some bottles of Wine/Beer/Whiskey\n                       A dead cat (black preferred)\n                        Some chilpi-wongo-wacklers\n\n                            @{" BACK TO MAIN MENU? " link "MAIN"}\n\n@endnode\n@node "Inst" "Installation - PeiTSch dEN SueSs-Op V0.8743874"\n@toc "Inst"\n\nJust copy the files\n                     @{"STARTCHAT1.txt" link "Chat1"}  \n                     @{"STARTCHAT2.txt" link "Chat2"}   \n                     @{"STARTCHAT3.txt" link "Chat3"}\n                     ......\n\n                     and @{"COMING.TXT" link "COME"}\n\n\n                   to DOORS:5D-AdiMui/\n\nand edit them to Your Needs!\n\nThen edit 5D-AdiMui.CFG:\n   \n             1.line: DO NOT REMOVE (identifier)\n             2.line: Name of Sysop belonging to Startchat1.txt\n             3.line: Name of Sysop belonging to Startchat2.txt\n             4.line: Name of Sysop belonging to Startchat3.txt\n             .......\n\n-------------------------------------------------------\n/X 2.xx or S-Express:\n\nCopy the drawer 5D-AdiMui to DOORS:\n\nEdit Your SYS.CMD and snap in the following:\n\n*CST      XM001DOORS:5D-AdiMui/5D-AdiMui\n-------------------------------------------------------\n/X 3.xx:\n\nCopy the drawer 5D-AdiMui to DOORS:\n\nJust copy the CST icon to Your SYSCMD-Directory and \n-------------------------------------------------------\nthen edit your BBS:NODEx/STARTCHAT.TXT\n       or your BBS:BBSTEXTS/STARTCHAT.TXT\n\ninsert the following line at the start of this text:\n\n~CC_CST\n\n                            @{" BACK TO MAIN MENU? " link "MAIN"}\n@endnode\n@node "What" "---> What it does: <---"\n@toc "What"\n\n If somebody tries to page you, you`ll be able to answer his chat-request\n               by simply pressing F1 .... (like ever before)\n then, the BBS will display the BBS:NODEx/STARTCHAT.TXT (also nothing new)\n\nIn this moment, it will start the 5D-AdiMui door via MCI-command (the ~CC_)!\n\n          The User will be prompted that the sysop is coming \n (if it exists, he`ll be shown "COMING.TXT", else by a default message...\n\n       Then the sysop on the console sees a menu where he can choose\n  which startchat<x>.txt (in DOORS:5D-AdiMui/) he wants to be displayed!\n\n\n                            @{" Wow !" link "MAIN"}\n@endnode\n@node "Chat1" "STARTCHAT1.txt"\n@toc "Chat1"\n\n              This Text will be displayed if You do press "1"\n                   This should be the default-sysop-text\n\n              A line will be added to the Callerslog, saying:\n             5D-AdiMUI! Chat answerd to <USER> by <SYSOP(1)> \n\n                          @{" Hummhumm " link "Inst"}\n@endnode\n@node "Chat2" "STARTCHAT2.txt"\n@toc "Chat2"\n\n               This text will be displayed if Your press "2"\n         good for girlfriends, or Your Cosysop sitting beside You!\n\n              A line will be added to the Callerslog, saying:\n             5D-AdiMUI! Chat answerd to <USER> by <SYSOP(2)> \n\n                           @{" Yarp ! " link "Inst"}\n@endnode\n@node "Chat3" "STARTCHAT3.txt"                     \n@toc "Chat3"                                             \n\n               This text will be displayed if Your press "3"\n          cause i don`t know, how much girlfriends you have =8-)\n      I use this option for my chat-maniac-cosysops (maybe someday to\n                  combine it with a multichat-option)...\n\n              A line will be added to the Callerslog, saying:\n             5D-AdiMUI! Chat answerd to <USER> by <SYSOP(3)> \n\n                                            \n                          @{" Hehehe ! " link "Inst"}\n@endnode\n@node "COME" "COMING.txt"\n@toc "COME"\n\n                                COMING.TXT\n                                ----------\n\n   This Text will be displayed to the User, when 5D-adimui was started.\n       You can use ANSI-codes aswell as MCI-Messages (~..) in it...\n\n             Have a look at the example inside the archive....\n\n     If this file doesn`t exist, the door will show a default message.\n\n\n                            @{" I`ll have a look! " link "Inst"}\n\n@endnode\n@node "History" "History"                             \n@toc "History" \n\nV1.0 - ugly Rexxdoor crashing all the times, with restriction\n       to 3 sysops at all.\n       Released for TT under the Name TT_MUC10.LHA ...\n\nV2.0 - coded in C, added CFG-file to have as much sysops as you\n       want, incredible speed increase, nice ansis, but a little\n       bit too much ego-tripping (sorry, Innuendo..)\n\nV2.1 - Added the feature to have an own "Coming.txt" to be displayed\n       if the sysop`s coming (into the chat! ;) )...\n       Also deleted some ego-tripping out of the default-message.\n\nV2.x - gimme some suggestions!\n\n\n                        @{" Ohmagod! " link "MAIN"}\n@endnode\n@node "Greet" "---> Greetings <---"\n@toc "Greet"\n\ngreetings fly to:\n\ntHE lIVING dEAD/tHE gIANTS/mUSHROOM/jAKE&eLWOOD <- This is the Tool for YOU!\n          Sven the Creator/5D <- You should join my coding conf.!\n                     Joe Cool/M! <- C - Coding rulez!\n           INNUENDO <- Simmer jetzt zufrieden ?? alter Pedanto!\n            [-Treach!] <- Merci beaucoup fuer le schoene Ansi!\n    Airworx/5D & SNOW/5D <- Mist Ihr habt ja nur jeweils ein Handle ;)\n               Murphy & Intercode/BB <- Yo, test the west !\n               Treach! <- Wann kommt die nexte Azkii-colli ?\nBilbo Baggins/M! <- Deine Routinen sin alle gut, aber ich bin zu dumm dafuer.\n                  Gonzalez/M! <- Wann kommt Realog in C ?\n                         E.F.A./PARAFiX <- Frull ?\nJordan/5D <- Bitte blaeh die Archive net so auf, sonst sag ich ORS zu dir!\n                      Spider/ORS <- A propos ORS, hi!\n                         Supergrobi <- Kicher `94\n                    Pater Pink/ARS <- Keep Arise alive!\n        MaD FøRcE/5D <- Weiter so! Mach mir auch mal nen Ansi,thX!\n\n\n                    to my girl (there can only be one!)\n\n                      and to all the Users of my BBS!\n\n                                 @{" RiGHT ! " link "MAIN"}\n@endnode\n\n@node "CallNow" "CallNow....."\n@toc "CallNow"\n\n¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%\n%               __________/\  ____  /\________________/\                     ¾\n¾              5\_____\  /  \/ _  \/  \   ____/    / /  \                    %\n%              tH/   / \__   \_/   \   \____ \_  \/__    \_                  ¾\n¾              _/   /   \     /     \_  \_ /  /   \_      /                  %\n%              \________/____/_______/___/___/_____/_____/ bOARDS            ¾\n¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%\n%                                                                            ¾\n¾ -=>  cELTIC cROSS ..........[    tHUNDER   ].. +49-333-aSK-4-iT  < WHQ>    %\n% -=>  aNTaRCTICA ............[      sNOW    ].. +49-306-aSK-4-iT  < GHQ>    ¾\n¾ -=>  fACElESS wORLD ........[    aIRwORX   ].. +49-304-aSK-4-iT  < GHQ>    %\n¾ -=>  sCUMwHERE #0 ..........[  tHE aDDICT  ].. +49-711-aSK-4-iT  < GHQ>    %\n%      sCUMwHERE #IsdN .......[  tHE aDDICT  ].. +49-711-aSK-4-iT  < GHQ>    ¾\n¾ -=>  lASERdANCE #0 .........[    jORDAN    ].. +49-210-aSK-4-iT  < GHQ>    %\n%      lASERdANCE #1 .........[    jORDAN    ].. +49-210-aSK-4-iT  < GHQ>    ¾\n¾ -=>  fUNKY tRADING #0 ......[   mAVERICK   ].. +39-828-aSK-4-iT  < IHQ>    %\n%      fUNKY tRADING #1 ......[   mAVERICK   ].. +39-828-aSK-4-iT  < IHQ>    ¾\n¾ -=>  dISoRDER ..............[    mARWIN    ].. +46-456-aSK-4-iT  < SHQ>    %\n% -=>  dREAMsCAPE ............[     sCAN     ].. +31-525-aSK-4-iT  <NLHQ>    ¾\n¾ -=>  wORLD oF wONDER #0 ....[    sTARcAM   ].. + 1-410-aSK-4-iT  <USHQ>    %\n%      wORLD oF wONDER #1 ....[    sTARcAM   ].. + 1-410-aSK-4-iT  <USHQ>    ¾\n¾ -=>  nEEDfUL tHINGS ........[ lELAND gAUNT ].. + 1-508-aSK-4-iT  <USHQ>    %\n%                                                                            ¾\n¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%¼%\n\n                                 @{" ATDT ! " link "MAIN"}\n\n@endnode\n\n@node "HIDE" "hidden Note....."\n@toc "Call"\n\n                       >iSDN cAllERS vERY wElCOME! <\n                       ..............................\n\n\n                                           \\n=====.====\================================)\==.========.======\=======.==\n    /|____)\.      .        .  /     .____/  \/|       /|       \     /|\n   /.      /|  \  /|       /|\/(_____|      // | \    / |_______)\   / |\n  //     //.|__)\/.|__    /.| \      |     //  |_)\  /. |______  \\ /. |\n /  _____/  ____/ :|  \  // |: \\   :|    // __|   \//__l  /  |___///__l\n \___  \//  \/  \  :   \//     .\\  |:    /  \___   \ ___)//  _ .\/  ___)\n / \/  \\\      /  |   /    Y   \\  . .  /\    |    /    \_  .|  \\\    \_\n//______/\  ___/\  ___/ ____|_____\__|  /  \  _|___/______/  :|___ \___  /\n\(========\(=====\(===\(=============| /====\(==========/ ____|===)/aDi)/=\n \         `      `    \             |/      \          \(        /    /\n                    5th      dYNASTY `  hEADQUAtER!      \\n\n\n     rUNNiNG oN aN A4ooo/o3o/6mb/55ohD   aMi-EXPRESS nEWEST! vERiON!  \n\n     sYSOP: mACHINE  cO`s: [tHE aDDiCT/5D!]   nODE0:   +49-711-lOCAl!\n                           [-sUPERGROBI!]     nODE1:   +49-711-zYXEL 19,2\n                           [-jOE cOOL-]/M!    nODE2+3: +49-711-iSDN 64kB RD\n                 \n    aMiGA oNLY - sPECiAL sEX & /X tOOLS cONF - dEMO & aGA cONFERENCE! \n\n             ==>>   sPECiAl /X-tOOlS cODiNG cONfERENCE!   <==\n\n     ]=[ iNVITED uSERS oNLY! ]=[ pRiVATE sYSTtEM = nUP rEQUiRED! ]=[ \n==========================================================================\n\n                             @{" HALLELUJA! " link "MAIN"}\n@endnode\n','\n',char(1