INSERT INTO door_catalog VALUES('5d_dc008','5D^DC008.LZH','~/Code/amiexpress_doors/Archives/AmiExpress/5D^DC008.LZH','5D^DupeCheck','XIM','5D^DupeCheck',NULL,'sTc/5D',NULL,'/_____ _ /  / /___ _ /\  _/_\  ___\  \  \ /  / //__   /  / //o \___  \\ \  \___ \\ /  / ./  /  /  /  //   \  \  \  \  \  \ .\',replace(' /\_______/\___/\____\/____ __________/\    \n/_____ _ /  / /___ _ /\  _/_\  ___\  \  \   \n  /  / //__   /  / //o \___  \\ \  \___ \\  \n /  / ./  /  /  /  //   \  \  \  \  \  \ .\ \n/____ /_____/__/__/ 5tH. \_____\__\  \_____\\nSk¡n\/   _ __ _ _/________\_ _ __ _         \n                / PrESENTS \\n >×·    5D^DupeCheck v0.08 by sTc/5D    ·×<\n >×·   Much better design & optimized   ·×<\n >×· Now fully able to be made resident ·×<\n','\n',char(10)),'5D^DupeCheck.Guide',replace('@DataBase 5D^DupeCheck Documentation\n@Author sTc/5D\n@Index Documentation\n\nCopyright © 1994 SvEN tHE CREAToR of 5tH DyNASTY\n\n@Remark $VER: 5D^DupeCheck v0.08 by sTc/5D\n@Remark AmigaGuide DataBase\n\n@node MAIN "5D^DupeCheck Documentation © 1994 SvEN tHE CREAToR of 5tH DyNASTY"\n                                                              :\n                                                       :      ¦             \n                   ________________  __________________¦      |\n            _______\_______       /  \             /   |      |______\n           |  __   _/     /______/____\  _     _  /    ¦      |  __  |\n           |  \/  _\________    \_\  / \/       \/     _      |  \/  |\n           |______\        /     / \/   |       |      /      |______|\n                   \___________ /       |_______|_____/       |Rpd!\n                              \/                     /________|\n                         :           :                                     :\n            ____   :     ¦     :     ¦      · 5 · T · H ·            :     ¦\n  __________\  /___¦    _|__/\ ¦     |_______ _______________________¦     |\n  \______   \\//   |    \____ \|     |   _   \\_____      /       /  |     |\n   /     \   \/    ¦     |   \ \     |   /    \/   /_____/    _  /   ¦     |\n _/       \   \_____     |    \ \_   |   _     \_____   \_     \/_____     |\n \       _/    /   /     |     \     |   /      /   /    /     |     /     |\n  \__________ /__________|     |\ ___|__/_____ /_______ /______|___________|\n            \/           |     ¦ \/          \/       \/\n                         ¦     :     · D · Y · N · A · S · T · Y ·\n                         :\n\n                              (×· PrESENTS ·×)\n\n                ----- --- -> 5D^DupeCheck v0.08 <- --- -----\n\n                  Coded by SvEN tHE CREAToR of 5th Dynasty\n\n                           @{" Normal Documentation " Link Documentation}\n@endnode\n@node Documentation "5D^DupeCheck Documentation"\n              _______________________________________________\n             |                                               |\n             | //                                            |\n             | /                                             |\n             |                                               |\n             |            @{" D e S C R I P T I O N " Link Description}           |\n             |                                               |\n             |           @{" I n S T A L L A T I O N " Link Installation}          |\n             |                                               |\n             |              @{" G r E E T I N G S " Link Greetings}             |\n             |                                               |\n             |                                             / |\n             |                                            // |\n             |_______________________________________________|\n\n@endnode\n@node Description "5D^DupeCheck Description"\n5D^DupeCheck has been coded by SvEN tHE CREAToR/5D!\n\nIt is a normal DupeCheck Door as like as the others out there\nbut it isn''t the slowest I hope... smile... It has been fully\ncoded in Assembler. So it''s your turn to decide which one you\nwanna use.\n\n\nImprovements:\n\n - It is now fully multientrant and able to be made resident\n - It has been more optimized\n - It has been fully new designed\n\n@endnode\n@node Installation "5D^DupeCheck Installation"\nCopy all files which are in the ''BBS'' directory of the archive\ninto your bbs directory.\n\nContents of archive:\n===================\n\nBBS/ Commands/ SysCmd/       FILECHECK.info\n     Doors/    5D^DupeCheck/ 5D^DupeCheck\n                             5D^DupeCheck.info\n                             5D^DupeCheck.Guide\n\n===================\n\nNote: If you''ve installed some other doors in your FileCheck and wanna\n      continue using''em then simply use 5D-MultiStart!\n      If you want to make it resident then simply type this into your\n      User-StartUp and copy the FILECHECK_RESIDENT.info to\n      BBS:Commands/SysCmd/FILECHECK.info!\n\nResident >NIL: 5D^DupeCheck Doors:5D^DupeCheck/5D^DupeCheck FORCE\n\n@endnode\n@node Greetings "5D^DupeCheck Greetings"\nGreetings go to:\n\n         . Celator ........... Thank you for helping me with /X! .\n         : ByteAndi ............ For helping me to learn coding! :\n         | Prophet .................... For being a nice friend! |\n         | Snow ...................... Sing mehr lieder, leader! |\n         | Airworx ................. Continue work as Co Leader! |\n         | Mad Doc ................. Can you catch sNoW again??? |\n         `------( And all other persons I''ve forgotten!!! )------''\n\n@endnode\n','\n',char(10)),NULL,'auto-added',9440,4,0,NULL,NULL,'5d_dc008','scan',1780048365);
