INSERT INTO door_catalog VALUES('5d_qa003','5D^QA003.LZH','~/Code/amiexpress_doors/Archives/AmiExpress/5D^QA003.LZH','5D^QuickAnsi','XIM','5D^QuickAnsi',NULL,'sTc/5D',NULL,'/_____ _ /  / /___ _ /\  _/_\  ___\  \  \ /  / //__   /  / //o \___  \\ \  \___ \\ /  / ./  /  /  /  //   \  \  \  \  \  \ .\',replace(' /\_______/\___/\____\/____ __________/\    \n/_____ _ /  / /___ _ /\  _/_\  ___\  \  \   \n  /  / //__   /  / //o \___  \\ \  \___ \\  \n /  / ./  /  /  /  //   \  \  \  \  \  \ .\ \n/____ /_____/__/__/ 5tH. \_____\__\  \_____\\nSk¡n\/   _ __ _ _/________\_ _ __ _         \n                / PrESENTS \\n    >×· 5D^QuickAnsi v0.03 by sTc/5D ·×<\n    >×·  Now with quick sysop login  ·×<\n    >×·  Fixed loss carrier hang up  ·×<\n','\n',char(10)),'5D^QuickAnsi.Guide',replace('@DataBase 5D^QuickAnsi Documentation\n@Author sTc/5D\n@Index Documentation\n\nCopyright © 1994 SvEN tHE CREAToR of 5tH DyNASTY\n\n@Remark $VER: 5D^QuickAnsi v0.03 by sTc/5D\n@Remark AmigaGuide DataBase\n\n@node MAIN "5D^QuickAnsi Documentation © 1994 SvEN tHE CREAToR of 5tH DyNASTY"\n                                                              :\n                                                       :      ¦             \n                   ________________  __________________¦      |\n            _______\_______       /  \             /   |      |______\n           |  __   _/     /______/____\  _     _  /    ¦      |  __  |\n           |  \/  _\________    \_\  / \/       \/     _      |  \/  |\n           |______\        /     / \/   |       |      /      |______|\n                   \___________ /       |_______|_____/       |Rpd!\n                              \/                     /________|\n                         :           :                                     :\n            ____   :     ¦     :     ¦      · 5 · T · H ·            :     ¦\n  __________\  /___¦    _|__/\ ¦     |_______ _______________________¦     |\n  \______   \\//   |    \____ \|     |   _   \\_____      /       /  |     |\n   /     \   \/    ¦     |   \ \     |   /    \/   /_____/    _  /   ¦     |\n _/       \   \_____     |    \ \_   |   _     \_____   \_     \/_____     |\n \       _/    /   /     |     \     |   /      /   /    /     |     /     |\n  \__________ /__________|     |\ ___|__/_____ /_______ /______|___________|\n            \/           |     ¦ \/          \/       \/\n                         ¦     :     · D · Y · N · A · S · T · Y ·\n                         :\n\n                              (×· PrESENTS ·×)\n\n                ----- --- -> 5D^QuickAnsi v0.03 <- --- -----\n\n                  Coded by SvEN tHE CREAToR of 5th Dynasty\n\n                           @{" Normal Documentation " Link Documentation}\n@endnode\n@node Documentation "5D^QuickAnsi Documentation"\n              _______________________________________________\n             |                                               |\n             | //                                            |\n             | /                                             |\n             |                                               |\n             |            @{" D e S C R I P T I O N " Link Description}           |\n             |                                               |\n             |           @{" I n S T A L L A T I O N " Link Installation}          |\n             |                                               |\n             |              @{" G r E E T I N G S " Link Greetings}             |\n             |                                               |\n             |                                             / |\n             |                                            // |\n             |_______________________________________________|\n\n@endnode\n@node Description "5D^QuickAnsi Description"\n5D^QuickAnsi has been coded by SvEN tHE CREAToR/5D!\n\nIt is programmed to be used instead of the normal ansi\nquastionary to make it more funny & faster cauz you only\nneed to press ONE digit to get in instead of f.e. ''N Q<CR>''.\nAlso I inserted the feature of using cursor keys to choose\none of the four possibilities.\n\nSpecial feature:\n\n - It is fully multientrant and able to be made resident\n\nFixed:\n\n - Now the sysop can logon with automatically passing the\n   Ansi questionary\n\n - If there was a hangup at the choose question the door has hang up\n\n@endnode\n@node Installation "5D^QuickAnsi Installation"\nCopy all files which are in the ''BBS'' directory of the archive\ninto your bbs directory.\n\nContents of archive:\n===================\n\nBBS/ Commands/ SysCmd/       ANSI.info\n     Doors/    5D^QuickAnsi/ 5D^QuickAnsi\n                             5D^QuickAnsi.info\n                             5D^QuickAnsi.Guide\n\n===================\n\n      If you want to make it resident then simply type the\n      following into your User-StartUp and copy the\n      ANSI_RESIDENT.info to BBS:Commands/SysCmd/ANSI.info!\n\nResident >NIL: 5D^QuickAnsi Doors:5D^QuickAnsi/5D^QuickAnsi FORCE\n\n@endnode\n@node Greetings "5D^QuickAnsi Greetings"\nGreetings go to:\n\n         . Celator ........... Thank you for helping me with /X! .\n         : ByteAndi ............ For helping me to learn coding! :\n         | Prophet .................... For being a nice friend! |\n         | Snow ...................... Sing mehr lieder, leader! |\n         | Airworx ................. Continue work as Co Leader! |\n         | Mad Doc ................. Can you catch sNoW again??? |\n         `------( And all other persons I''ve forgotten!!! )------''\n\n@endnode\n','\n',char(10)),NULL,'auto-added',15448,7,0,NULL,NULL,'5d_qa003','scan',1780048365);
INSERT INTO door_catalog VALUES('5d_sa001','5D^SA001.LZH','~/Code/amiexpress_doors/Archives/AmiExpress/5D^SA001.LZH','5D^SysOpAvail','XIM','5D^SysOpAvail',NULL,'sTc/5D',NULL,'/_____ _ /  / /___ _ /\  _/_\  ___\  \  \ /  / //__   /  / //o \___  \\ \  \___ \\ /  / ./  /  /  /  //   \  \  \  \  \  \ .\',replace(' /\_______/\___/\____\/____ __________/\    \n/_____ _ /  / /___ _ /\  _/_\  ___\  \  \   \n  /  / //__   /  / //o \___  \\ \  \___ \\  \n /  / ./  /  /  /  //   \  \  \  \  \  \ .\ \n/____ /_____/__/__/ 5tH. \_____\__\  \_____\\nSk¡n\/   _ __ _ _/________\_ _ __ _         \n                / PrESENTS \\n  >×·  5D^SysOpAvail v0.01 by sTc/5D   ·×<\n  >×·  Fully able to be made resident  ·×<\n','\n',char(10)),'5D^SysOpAvail.Guide',replace('@DataBase 5D^SysOpAvail Documentation\n@Author sTc/5D\n@Index Documentation\n\nCopyright © 1994 SvEN tHE CREAToR of 5tH DyNASTY\n\n@Remark $VER: 5D^SysOpAvail v0.01 by sTc/5D\n@Remark AmigaGuide DataBase\n\n@node MAIN "5D^SysOpAvail Documentation © 1994 SvEN tHE CREAToR of 5tH DyNASTY"\n                                                              :\n                                                       :      ¦             \n                   ________________  __________________¦      |\n            _______\_______       /  \             /   |      |______\n           |  __   _/     /______/____\  _     _  /    ¦      |  __  |\n           |  \/  _\________    \_\  / \/       \/     _      |  \/  |\n           |______\        /     / \/   |       |      /      |______|\n                   \___________ /       |_______|_____/       |Rpd!\n                              \/                     /________|\n                         :           :                                     :\n            ____   :     ¦     :     ¦      · 5 · T · H ·            :     ¦\n  __________\  /___¦    _|__/\ ¦     |_______ _______________________¦     |\n  \______   \\//   |    \____ \|     |   _   \\_____      /       /  |     |\n   /     \   \/    ¦     |   \ \     |   /    \/   /_____/    _  /   ¦     |\n _/       \   \_____     |    \ \_   |   _     \_____   \_     \/_____     |\n \       _/    /   /     |     \     |   /      /   /    /     |     /     |\n  \__________ /__________|     |\ ___|__/_____ /_______ /______|___________|\n            \/           |     ¦ \/          \/       \/\n                         ¦     :     · D · Y · N · A · S · T · Y ·\n                         :\n\n                              (×· PrESENTS ·×)\n\n                ----- --- -> 5D^SysOpAvail v0.01 <- --- -----\n\n                  Coded by SvEN tHE CREAToR of 5th Dynasty\n\n                           @{" Normal Documentation " Link Documentation}\n@endnode\n@node Documentation "5D^SysOpAvail Documentation"\n              _______________________________________________\n             |                                               |\n             | //                                            |\n             | /                                             |\n             |                                               |\n             |            @{" D e S C R I P T I O N " Link Description}           |\n             |                                               |\n             |           @{" I n S T A L L A T I O N " Link Installation}          |\n             |                                               |\n             |              @{" G r E E T I N G S " Link Greetings}             |\n             |                                               |\n             |                                             / |\n             |                                            // |\n             |_______________________________________________|\n\n@endnode\n@node Description "5D^SysOpAvail Description"\n5D^SysOpAvail has been coded by SvEN tHE CREAToR/5D!\n\nYou know it... smile\n\nFeatures:\n\n - It is fully able to be made resident\n\n@endnode\n@node Installation "5D^SysOpAvail Installation"\nCopy all files which are in the ''BBS'' directory of the archive\ninto your bbs directory.\n\nContents of archive:\n===================\n\nBBS/ Commands/ SysCmd/        AVAIL.info\n     Doors/    5D^SysOpAvail/ 5D^SysOpAvail\n                              5D^SysOpAvail.info\n                              5D^SysOpAvail.Guide\n\n===================\n\nTo use it at the logon you can simply start 5D^SysOpAvail from the\n"Bull.TXT", so simple write "~|" at the beginning of it and\n"~CC_AVAIL|" where you want it to be started.\n\nNote: If you want to make it resident then simply type this into your\n      User-StartUp and copy the AVAIL_RESIDENT.info to\n      BBS:Commands/SysCmd/AVAIL.info!\n\nResident >NIL: 5D^SysOpAvail Doors:5D^SysOpAvail/5D^SysOpAvail FORCE\n\n@endnode\n@node Greetings "5D^SysOpAvail Greetings"\nGreetings go to:\n\n         . Celator ........... Thank you for helping me with /X! .\n         : ByteAndi ............ For helping me to learn coding! :\n         | Prophet .................... For being a nice friend! |\n         | Snow ...................... Sing mehr lieder, leader! |\n         | Airworx ................. Continue work as Co Leader! |\n         | Mad Doc ................. Can you catch sNoW again??? |\n         `------( And all other persons I''ve forgotten!!! )------''\n\n@endnode\n','\n',char(10)),NULL,'auto-added',12807,5,0,NULL,NULL,'5d_sa001','scan',1780048365);
INSERT INTO door_catalog VALUES('5d_sya10','5D^SYA10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/5D^SYA10.LHA','5D^SYSAVAIL','XIM','5D^SYSAVAIL',NULL,'[tHE',NULL,'5 \____\   / \     \____\   __/     /  /   \ T/   / \__   \  T  \  / \___ \   \/___    / H/   /   \     \ |   \    \ /  \   \      /',replace('  ____________________/\___________________\n5 \____\   / \     \____\   __/     /  /   \\n T/   / \__   \  T  \  / \___ \   \/___    /\nH/   /   \     \ |   \    \ /  \   \      /\n/________/     /_|    \/   \____\___\    /\n[===/_________/==|____/_____\RpD!/______/==]\n|   5D-SysAvail V1.00 by [tHE aDDiCT/5D!]  |\n`------------------------------------------''\n','\n',char(10)),'5D^SYSAVAIL.GUIDE',replace('@DataBase 5D-SysAvail Documentation\n@Author [tHE aDDiCT/5D!]\n@Index Documentation\n\nCopyright © 1994 5tH DyNASTY\n\n@Remark $VER: 5D-SysAvail v1.00 18.6.1994\n@Remark AmigaGuide DataBase\n\n@node MAIN "5D-SysAvail v1.00 Docu Main Page"\n                                                              :\n                                                       :      ¦\n                   ________________  __________________¦      |\n            _______\_______       /  \             /   |      |______\n           |  __   _/     /______/____\  _     _  /    ¦      |  __  |\n           |  \/  _\________    \_\  / \/       \/     _      |  \/  |\n           |______\        /     / \/   |       |      /      |______|\n                   \___________ /       |_______|_____/       |Rpd!\n                              \/                     /________|\n                         :           :                                     :\n            ____   :     ¦     :     ¦      · 5 · T · H ·            :     ¦\n  __________\  /___¦    _|__/\ ¦     |_______ _______________________¦     |\n  \______   \\//   |    \____ \|     |   _   \\_____      /       /  |     |\n   /     \   \/    ¦     |   \ \     |   /    \/   /_____/    _  /   ¦     |\n _/       \   \_____     |    \ \_   |   _     \_____   \_     \/_____     |\n \       _/    /   /     |     \     |   /      /   /    /     |     /     |\n  \__________ /__________|     |\ ___|__/_____ /_______ /______|___________|\n            \/           |     ¦ \/          \/       \/\n                         ¦     :     · D · Y · N · A · S · T · Y ·\n                         :\n             ____             (×· PrESENTS ·×)\n            \\  /\n             \\/-----> 5D-SysAvail v1.00 by [tHE aDDiCT/5D!] <----\n              \/\n                         Coded by [tHE aDDiCT/5D!]\n                         Docu  by [tHE aDDiCT/5D!]\n                           ^                ^\n                           | @{"    Purpose   " Link Purpose} |\n                           | @{" Requirements " Link Requirements} |\n                           | @{" Installation " Link Installation} |\n                           | @{"   Important  " Link Important} |\n                           | @{"   Greetings  " Link Greetings} |\n                           `----------------'' \n\n@endnode\n\n@node "Purpose" "Purpose of 5D-SysAvail v1.00 by [tHE aDDiCT/5D!]"\n@toc "Purpose"\n\n              5D-SysAvail is a door that shows the User on the logon\n              sequence if the sysop is available for chat or not.\n\n              I didn`t include a "The-Sysop-is-not-available-but-\n              You-have-override-axs-WOW-super-duper-Option, b`cause\n              i think people with override Axs do know that they have\n              it!\n\n\n                            @{" Requirements " link "Requirements"}\n                            @{"  -> Main <-  " link "MAIN"}\n\n@endnode\n\n@node "Requirements" "Requirements for 5D-SysAvail v1.00 by [tHE aDDiCT/5D!]"\n@toc "Requirements"\n\n     You need an Amiga model 500/600/1000/1000 ..... (blabla)\n    \n     Installed Amiexpress software \n\n                            @{" Installation" link "Installation"}\n                            @{"  -> Main <- " link "MAIN"}\n\n@endnode\n@node "Installation" "Installation of "\n@toc "Installation"\n\n        5D-Sysavail is a Systemcommand door. It`s quite easy to install:\n   \n        @{"   /X 3.xx   " link "3er"}\n        @{"/X 2.xx & S!X" link "2er"}\n\n                            @{"  Important  " link "Important"}\n                            @{"  -> Main <- " link "MAIN"}\n\n@endnode\n\n@node "3er" "5D-SysAvail v1.00 by [tHE aDDiCT/5D!]"\n@toc "3er"\n\n        1. Just copy all the supplied .info files into the directories.\n\n        2. Place this line into Your logon.txt or bull<xx>.txt:\n\n           ~CC_SYSAVAIL\n\n           That`s all, Enjoy!       \n   \n\n                            @{" Installation " link "Installation"}\n                            @{"  -> Main <-  " link "MAIN"}\n\n@endnode\n\n@node "2er" "5D-SysAvail v1.00 by [tHE aDDiCT/5D!]"\n@toc "2er"\n\n\n        1. Add this line to Your Sys.Cmd :\n\n           SYSAVAIL  XM001DOORS:5D^SysAvail/5D^SysAvail\n\n        2. Copy the 5D^SysAvail - Drawer to Your Doors:\n\n        3. Place this line into Your logon.txt or bull<xx>.txt:\n\n           ~CC_SYSAVAIL\n\n           That`s all, Enjoy!\n\n\n                            @{" Installation " link "Installation"}\n                            @{"  -> Main <-  " link "MAIN"}\n\n@endnode\n\n@node "Important" "The 5th Dynasty Boards!"\n@toc "Important"\n\n                              ______ ______ __  __\n                             /  ___//_  __// /_/ /\n                          ___\__ \  /  /  /  _  /\n                         /_______/ /__/  /__//_/\n               ___ __  ___ _  __ _____ _____ ______ __   __\n              /   \\ \/  // \/ // _  // ___//_  __// /  / /\n             / /-  \\   //    // _  //__  / /  /  / /__/ /\n            /______//__//_/\_//_//_//____/ /__/  /____  /\n         ____________________________________________/ /\n        /_____________________________________________/MaD\n\n                 ----- --- --> The Boards! <-- --- -----\n\n                  ANTARCTICA       +49-30-XXXXXX  WHq\n  \n               Faceless World   +49-30-XXXXXX  SounderHQ\n  \n                 lASERdANCE       +49-21xx-XXXXX 2Ndz\n  \n            sCUMWHERE        +49-711-XXXX   3Ndz (2 iSDN RD)\n\n                  Funky Trading    +39-xxxx-XXXXX 2Ndz\n\n               Desert Strike +49-xxxx-XXXXXX 2Ndz (soon iSDN)\n\n\n                 ----- --- --> The Boards! <-- --- -----\n\n                            @{"  Greetings  " link "Greetings"}\n                            @{"  -> Main <- " link "MAIN"}\n\n@endnode\n@node "Greetings" "The Greetings of StC!"\n@toc "Greetings"\n\n\n          Rainman          - WANN iSDN ????\n          Snow             - Wie geht`s deiner 2. Dynastie ? \n          Airworx          - hehe\n    \n          [-sUPERGROBi!]   - Du liest dass ja sowieso nicht!\n          [-Joe Cool!]/M!  - Jaja.. der support\n          Gonzalez/M!      - Rexx rulz\n          Bilbo Baggins/M! - Cursor ist immer noch weg (nerv)\n          zAX/TTT          - YO!\n          CF/TTT           - Laaaaaangsam!\n          [tHE GiANTS/TyT] - Wir werden sie besiegen, die Icons\n          INCUBUS/TRSI     - paaaaaady\n\n              and all i`ve forgotten (sorry, but no time)\n\n                            @{"  That`s all " link "All"}\n                            @{"  -> Main <- " link "MAIN"}\n\n@endnode\n@node "All" "Hidden Node!"\n@toc "All"\n\nWoooooowwwww hidden Node!!! so call\n\n=====.====\================================)\==.========.======\=======.==\n    /|____)\.      .        .  /     .____/  \/|       /|       \     /|\n   /.      /|  \  /|       /|\/(_____|      // | \    / |_______)\   / |\n  //     //.|__)\/.|__    /.| \      |     //  |_)\  /. |______  \\ /. |\n /  _____/  ____/ :|  \  // |: \\   :|    // __|   \//__l  /  |___///__l\n \___  \//  \/  \  :   \//     .\\  |:    /  \___   \ ___)//  _ .\/  ___)\n / \/  \\\      /  |   /    Y   \\  . .  /\    |    /    \_  .|  \\\    \_\n//______/\  ___/\  ___/ ____|_____\__|  /  \  _|___/______/  :|___ \___  /\n\(========\(=====\(===\(=============| /====\(==========/ ____|===)/===)/=\n \         `      `    \             |/      \          \(        /    /\n                                       `                   `\n\n\n                            @{"  -> Main <- " link "MAIN"}\n\n@endnode\n','\n',char(10)),NULL,'auto-added',16796,1,0,NULL,NULL,'5d_sya10','scan',1780048365);
INSERT INTO door_catalog VALUES('5d_vb001','5D^VB001.LZH','~/Code/amiexpress_doors/Archives/AmiExpress/5D^VB001.LZH','5D^ViewBulls','XIM','5th______  ___  __  ___   _____  _. ___  ___',NULL,'sTc/5D',NULL,'\__   \  \/  /_|  |/___\ / ___/_/ |_\  \/  / |  |  \_/ _/__\  |  /  |___  \_   _/\_/ _/ |  |  ||  ||  \\_| /   |     ||   |  |  |',replace('5th______  ___  __  ___   _____  _. ___  ___\n\__   \  \/  /_|  |/___\ / ___/_/ |_\  \/  /\n |  |  \_/ _/__\  |  /  |___  \_   _/\_/ _/\n |  |  ||  ||  \\_| /   |     ||   |  |  |\n |  |  ||  ||  |\_| \_  |SNOW!||   |  |  |\n |_____||__||__|__|__|__|_____||___|  |__|\n«««««««««««««« P R E S E N T : »»»»»»»»»»»»»\n     5D^vIEWbULLS v0.01 cODE bY sTc/5D\n         fULLY cODED iN aSSEMBLER!\n           fULL oNLINE uPDATING!\n«««««««««««« 5tH dYNASTY rOOLZ! »»»»»»»»»»»»\n','\n',char(10)),'5D^ViewBulls.Guide',replace('@database 5D^ViewBullsDoc\n\nCopyright (c) 1993 SvEN tHE CREAToR of 5th Dynasty\n\n@Remark $VER: (March 19 1994, 18:30:00)\n@Remark AmigaGuide database for the 5D^ViewBulls Documentation\n\n@node MAIN "5D^ViewBulls Documentation (c)1994 SvEN tHE CREAToR of 5th Dynasty (March 19 1994, 18:30:00)"\n\n    _5tH_______    ____   ___  _____  _______ _________    ___\n    \______ \  \__/  / \ |   |/     \|       |      \  \__/  /\n     |     \ \_ \/ _/ \ \|   |   _   |  _____|___ ___\_ \/ _/\n     |     / ||\  /|   \ \   |  /    |      \  |   |  |\  /|\n     |    /  || \/ |   |\ \  |  \_   |\____  | |   |  | \/ |\n     |   /   ||sNoW|   | \ \ |   |   |       | |   |  |    |\n     :       ::    :   : :\  :   :   :       : :   :  :    :\n     `-------''`----`---'' `---`---`---`-------'' `---''  `----''\n\n                            >>> 5D^ViewBulls <<<\n\n                         Code: SvEN tHE CREAToR/5D\n\n---------------------------------------------------------------------------- \n\n         >>> C·O·N·T·E·N·T·S  O·F  D·O·C·U·M·E·N·T·A·T·I·O·N <<<\n\n                         @{"      Introduction      " Link Cap01}\n                         @{"      Requirements      " Link Cap02}\n                         @{"      Installation      " Link Cap03}\n                         @{"       Greetings!       " Link Cap05}\n                         @{"   How to Contact me?   " Link Cap06}\n\n         ---------------------------------------------------------\n              Complete Docs for 5D^ViewBulls V0.01 [-5th Dynasty-]\n         ---------------------------------------------------------\n         The Documentation has been written by SvEN tHE CREAToR/5D.\n\n@endnode\n@node Cap01 "Introduction"\n  =======================================================================\n  5D^ViewBulls is a replacement for the original ViewBulls Command\n  of AmiExpress ''B'' but it supports ONLINE UPDATING! It tries to show\n  the Bulls out of ("Bulletins:") which ya need to assign to a general\n  Bulletin area! For online updating you simply need to write your\n  things normally listed in the logoff-batch in a File called:\n  "Bulletins:Bull<NUMBER>.Script"!\n  For example there can stand:\n  "5D-Top BLUBBEL BLA BLIBBER Bulletins:Bull2.TXT" in "Bulleting:Bull2.Script"\n  The other possibility is to create a file called "Bulletins:UpdateBulls.Bat"\n  and to write in ALL Bulls. Then 5D^ViewBulls will start it at the\n  beginning and you don''t need to create a script file for each conference.\n \n            DON''T FORGET TO SET THE ''S''-BIT AT THE SCRIPTS!!!!\n\n  =======================================================================\n@endnode\n@node Cap02 "Requirements"\n  =======================================================================\n  To install 5D^ViewBulls you must have the following things:\n\n    Programm     Location           Description\n    ----------   --------           -----------\n    5D^ViewBulls Doors:5D^ViewBulls Main program\n\n  - an  Amiga Model (500/600/1000/1200/2000/2500/3000/4000/CDTV/CD³²)\n  - the installed Version of OS\2, OS\3 or higher\n    (Soft- or Hardware Version)\n  - the installed .INFO Files in the directories.\n  - AmiExpress V2.xx , v3.xx or higher. And surely S-Express hehe.\n\n  =======================================================================\n@endnode\n@node Cap03 "How to install 5D^ViewBulls:"\n  =======================================================================\n  To install 5D^ViewBulls you must have all Requirement which were\n  mentioned below. You need the following things.\n\n  --------------------------\n    Doors:5D^ViewBulls (dir)\n      ^^^ 5D^ViewBulls\n    BBS:Commands/BBSCmd (dir)\n      ^^^ B.info\n  --------------------------\n\n  Decruch the 5D^ViewBulls Archive. Go to your ''Doors:'' Directory\n  and make a directory called ''5D^ViewBulls''. Copy ''5D^ViewBulls''\n  into the Directory. Go to your ''BBS:Commands/BBSCmd/'' Directory.\n  Copy ''B.info'' into it.\n  =======================================================================\n@endnode\n@node Cap05 "Greetings go to the following guys:"\n  =======================================================================\n\n          Thunder ............. We need to cross celtic!\n          Rainman .............. Cool to have you in 5D!\n          Starcam ............ We''ll support ya as hell!\n          Mad Førce .................. Cool techno song!\n          Snow ................... Ich will mehr lieder!\n          Airworx .................... McDonald''s r0oLZ!\n          Prophet ............... Nice to have you back!\n          Stoker .................. Apple rooooooooo0LZ!\n          Circuit Breaker ..................... Cu soon!\n          Zector ...................... Assembler rules!\n          Bladerunner ... Really cool to have you in 5D!\n          Muad''Dib ................. We''ll discover you!\n          Scan ................. We dream on your scape!\n          Feivel ......... You''ve been a good ''Hamster''!\n\n  =======================================================================\n@endnode\n@node Cap06 "How to contact me:"\n  =======================================================================\n                 ___ ___    ___    _______    ___ ___    ___\n                /  ¬|  ¬\  /  ¬\  /      ¬\  /  ¬|  ¬\  /  ¬\\n               /         \/     \/         \/         \/     \\n              /           \      \          \          \      \\n            _/             \_     \_  |      \_         \_     \_\n            \      \ /      /      /          / \ /      /      /\n             \      |      /      /   |      /   |      /      /\n              \_____|____ /_____ /____|____ /____|____ /_____ /\n          /\            \/     \/         \/         \/     \/\n_________/  \  /\___________> 5TH DYNASTY GHQ <____________________ ___ __ _\n             \/    ___ ___    _______    _______    _______\n                  /  ¬|  ¬\  /      ¬\  /      ¬\  /      ¬\\n                 /    |    \/         \/         \/         \\n                /           \    |     \          \          \\n              _/             \_     ___/\_  |      \_____     \_\n              \               /    /     /          / |        /\n               \      |      /          /   |      /  |       /\n                \_____|____ /_________ /____|____ /   |_____ /·cj·\n                          \/         \/         \/         \/\n \n                       aMiGa aNd PC ZeR0 dAy wArEz\n \n                         SYSOP: SvEN tHE CREAToR\n                         COSYS: Airworx\n                                Mr.Return\n \n                   -<>- CaLL: +49-(0)30-742-4141 -<>-\n\n  =======================================================================\n@endnode\n','\n',char(10)),NULL,NULL,12119,5,0,NULL,NULL,'5d_vb001_5d_viewbulls','scan',1780048365);
INSERT INTO door_catalog VALUES('5d_vl012','5D_VL012.LZH','~/Code/amiexpress_doors/Archives/AmiExpress/5D_VL012.LZH','AVAIL','XIM','AVAIL',NULL,'PROPHET/5D','5D','5 \____\   / \     \____\   __/     /  /   \ T/   / \__   \  T  \  / \___ \   \/___    / H/   /   \     \ |   \    \ /  \   \      /',replace('  ____________________/\___________________\n5 \____\   / \     \____\   __/     /  /   \\n T/   / \__   \  T  \  / \___ \   \/___    /\nH/   /   \     \ |   \    \ /  \   \      /\n/________/     /_|    \/   \____\___\    /\n[===/_________/==|____/_____\RpD!/______/==]\n> 5D AVAIL v0.12 bUGFIXED ! bY PROPHET/5D <\n','\n',char(10)),'5D-AVAIL012.DOC',replace('                    .------------------------------.\n                    | 5D AVAIL v0.12 documentation |\n                    ·------------------------------·\n\n   5D-Avail is a simple(?) AVAIL replacement for the OS2.x+ AVAIL\n   of the workbench.\n   You have the following options which can be used:\n\n   - chip     (to get only the free chip mem)\n   - fast     (to get only the free fast mem)\n   - total    (to get the total memory (not only the largest total))\n   - base     (to get the adresses of some bases[dos,exec ...])\n   - shell    (to get a program intern shell)\n   - log      (to log the free mem [chip and fast and total] to a\n               userdefined logfile. Remember,you can`t add the free\n               mem to an already defined /present file.)\n   - use      (to get the used memory)\n   - boards   (to get the numbers of our boards!)\n\n   History:\n   --------\n\n   v0.1  (5.2.1994)  - a really shitty try to code avail(the original looked\n                       better!).Full of bugs.\n   v0.11 (9.2.1994)  - looked better,but was full of bugs !\n   v0.12 (16.2.1994) - now completly bugfixed and some new routines added!\n\n       Greetings :\n       -----------\n\n  Snow .....................to be a cool leader!\n  StC ......................for helping me with my problems(coding r00lz!)\n  Airworx ..................for being a METAL-FREAK and a cool friend!\n  Oskar ....................for being just a dog\n  Satan ....................what the hell ? (hey...it`s a cat!)\n  Goonie ...................suck my dig (ya know why ?!?!?!)\n  Stoker ...................Hey Skidmarks is kewl!\n  Thunder ..................let the lightnings strike again!\n  Maverick .................Sorry for the problems with the releases !\n  Shanon ...................Stone is keeping on rolling !\n  Delta-x ..................Don`t take care of kimble ...hehehehe\n    And to the rest of 5tH dYNASTY.......let us bring 5D on TOP!\n\n','\n',char(10)),NULL,'auto-added',8701,6,1,'AVAIL','Doors/AVAIL','5d_vl012','scan',1780048365);
INSERT INTO door_catalog VALUES('7m_bdes','7M-BDES.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/7M-BDES.LHA',NULL,'XIM','/\_____/\_____/\___/\_______/\/\  /\',NULL,NULL,'7M','/  \   / _____/  / / ________  \ \/  \ __\__ \_(  __)_/  / (  __)_/ /   //  \  \ \  (/) \ \    /\ (  /\    / /   / \ //  \\',replace('   /\_____/\_____/\___/\_______/\/\  /\    \n  /  \   / _____/  / / ________  \ \/  \   \n__\__ \_(  __)_/  / (  __)_/ /   //  \  \  \n\  (/) \ \    /\ (  /\    / /   / \ //  \\ \n|\___  /  \  /  \  /  \  /\ \  /  /\/\  __)\n`----\/----\/----\/----\/--\/\/-\/----\/--''\n   -*-  FULL ANIM BOARD DESIGN V7.M  -*-\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 18:52:20  ON NODE: 1\n','\r',char(13)),'\n',char(10)),NULL,NULL,17969,2,0,NULL,NULL,NULL,'scan',1780048365);
INSERT INTO door_catalog VALUES('976_rs13','976-RS13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/976-RS13.LHA',NULL,'XIM','RubberStamp.XiM',NULL,NULL,'976','//\\/    / __                /    /  /   /\ ////\\   / /     ____________/    /________/ //DoorZ/      _/  / \      /    /  /   / _',replace('  /\ //    ____________________//////______\n //\\/    / __                /    /  /   /\\n////\\   / /     ____________/    /________/\n //DoorZ/      _/  / \      /    /  /   / _\n  __   /          /   \+||+/    /  /   /-\ \\n-/ /- /       ___/\    \  /    /  /   / -/_/\n-\_\-/      _/  /  \    \/    /  /   /    DA\n    /          /____\        /  /   /____/\_\n   / /         ~~    \      /  /    ~~     /\n  (___________________\    /__/___________/\n                       \\//  New Timestamp\n-=[ RUbbErStamp V1.3 ]=-\/  Door for /X !!!\n','\n',char(10)),'RubberStamp.doc',replace('\n                             Gentlemen, Privy Tis A \n\n         - -+----------------------------------------------------+- -\n            |                                                    |\n            |/\____/\_____/\____            /\______/\__    ____/\__\n            / /\___\/\____\/\___\  ____    / /\_____\/\_\__/\___\/\_\\n           / //__  /___  ./  ___/ /\___\  / //  ____/.  /__\/___/.  /_\n          /\/___  / / / //    ./  \/___/ / /.  ____//  /   /.  //  /__\\n         / /.  / / / / ./  / //         / /   /   //  /   //  //  /   /\n         \/____ /  \/_ /____ /          \/______ /______ /__ /______ /\n            |  Y      Y     Y                   Y       Y   Y    |  Y\n            |  .      .     .                   .       .   .    |  .\n            |  o      o     o     976-Ev!L      o       o   o    |  o\n         - -+----------------------------------------[ Pa\X/s ]--+- -\n            .                                        [  &DÆ   ]\n                                Release In 1995!\n\n-------------------------------------------------------------------------------\n\n\n                             RubberStamp V1.3\n                             ~~~~~~~~~~~~~~~~\n\n            Docs By Dark Angel (but blame Strobe for the code)\n\n\n                         I N T R O D U C T I O N \n\nOi  you!   yeah you...  you know that bloody timestamp door that bombs your\nbbs when it runs?  Well this ain''t it...  this WORKS :)))) B O N U S !\n\nErm...   i''m supposed to be serious now..  but instead i''ll tell you it''s a\nreally  funky  timestamp  replacement door for ALL machines, written in C++\n(fast) and completely system legal (for a change).\n\nYou can define how it looks, take it to parties, show it to your girlfriend\n(not included in this archive folks) and generally make your users think of\nyou as a demi god :*)\n\nInstall it... then tell me it''s shite alright ?\n\n-------------------------------------------------------------------------------\n\nIt''s another eXCiTIng door from Strobe and Dark Angel of 976 Ev!L in Sunny\n                                 ENGLAND!\n\n-------------------------------------------------------------------------------\n\n                         R E Q U I R E M E N T S \n\n\nAn  Amiga,  a  hardisk,  /X, sadistic tendancies, your Grandma''s teeth and a\nlittle  time  to  spare (about 30 seconds average).  Sysops of Phantasm may\nrequire a little more time, say a day or two ;*)\n\n\n                         I N S T A L L A T I O N \n\n                                 LOAD OPUS\n            Copy the files to the relevant dirs on your bbs... \n                                 FUCK OFF\n\n\n                        C O N F I G U R A T I O N \n\nTooltypes:\n-=-=-=-=-\n\nSTAMP\n\nThis tooltype defines the groovy look of the timestamp entry on the\nfilelisting for all remote callers to the bbs..  Dead simple and quite\nhonestly I don''t see any point in telling you about it :) So I''m lazy...\nshoot me!\n\nExample tooltype configuration:\n\nSTAMP=-+=[ @HOU:@MIN:@SEC ]--[ Node @NOD ]--[ @CPS CPS ]=+-\n\nBecomes:\n\n--[23:32]--[On Node #0]--[CPS: 4536]--\n\n\n                               -------------\nSTAMP.LOCAL\n\nThis very exciting and interesting tooltype defines the look of the local\nuploads to the bbs (e.g.  local node sysop).  Basically used when the CPS\nrate is Zero, nil, nothing, nada...  or less than 1 :)\n\nExample tooltype configuration:\n\nSTAMP.LOCAL=-+=[ @HOU:@MIN:@SEC ]--[ Node @NOD ]--[ SYSOP UL ]=+-\n\nBecomes:\n\n--[23:32]--[On Node #0]--[ SYSOP UL ]--\n\nTOOLTYPE NOTE:\n\nFor BOTH of these tooltypes the following applies:\n\n@HOU is the hour of the upload\n@MIN is the minute of the upload\n@SEC is the second (fucking hell this is smart) of the upload\n@NOD is the node the file was upped on\n@CPS is the cps rate reported by /X :*) [very acurate m8]\n\nANSI colour codes supported in the tooltypes so USE ''EM!\n\n-------------------------------------------------------------------------------\n\n                          R E G I S T R A T I O M\n\nIt''s a good idea. It''s free. Just do it.\n\nSpecial registration competition!!!\n\nIf you can find out HOW to register this program then a registered copy\nwill be yours!!!\n\n-------------------------------------------------------------------------------\n\n                            G R E E T I N G S \n\nHello to everyone on planet Earth from me, Dark Angel and Strobe (who''s\nwatching me type which is a real putoff y''know...  God I hate some\npeople...  btw I''m totally sane contrary to popular opinion on the\nscene)...\n\nHello to everyone not on planet Earth...  especially the guys from uranus -\ncos let''s face it you''ve got to have a sense of humour to come from a\nplanet named after your arse :)\n\n[Fuck me why did I ask this nutter to do the docs ;) - Strobe]\n','\n',char(10)),NULL,'auto-added',9388,2,0,NULL,NULL,'976_rs13','scan',1780048365);
