INSERT INTO door_catalog VALUES('acp300','ACP300.LZH','~/Code/amiexpress_doors/Archives/AmiExpress/ACP300.LZH',NULL,'XIM','acp208.ctrl','3.0',NULL,NULL,NULL,replace('source of acp v3.0\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 18:52:13  ON NODE: 1\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',63885,3,0,NULL,NULL,'acp300','scan',1780048365);
INSERT INTO door_catalog VALUES('acpage20','ACPAGE20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ACPAGE20.LHA',NULL,'XIM','gtlayout.library',NULL,'ACP-Developement',NULL,'|  |   | \      / ________ \   | \/  ___ _/ |  |  \   \| \_/  _|_/  |/ /  \   \ (_ | | |  |__:\__/|__|\____ \__|\ \__:\__/ (__: |',replace('_|__ ___:\______________________:\  ________\n |  |   | \      / ________ \   | \/  ___ _/\n |  |  \   \| \_/  _|_/  |/ /  \   \ (_ | |\n |  |__:\__/|__|\____ \__|\ \__:\__/ (__: |\n |__|================\/====\/=WiZZy\______:\n      __\n     ///\n_   ///  ACP-Page2.0 - Sysop-Pager Door\n\\\///  (C)opyright by ACP-Developement 1995\n \XX/\n','\n',char(10)),'ACP-Page2.0.guide',replace('@database 075d7770-1\n@master bbs:ACP-Page2.0.doc\n@$VER: 1.0\n@remark Created with Heddley v1.1 (c) Edd Dumbill 1994\n\n@node "Main" "ACP-Page2.0 - Main"\n      __\n     ///\n__  ///  ACP-Page2.0 - Sysop-Pager Door\n\\\///   (C)opyright by ACP-Developement 1994-95\n \XX/\n\n\n       @{"Disclaimer" link "Document_0" 0}\n       @{"Introduction" link "Document_1" 0}\n       @{"General Installation" link "Document_2" 0}\n       @{"E! Installation" link "Document_3" 0}\n       @{"Check it out" link "Document_4" 0}\n       @{"ANSI-Animation" link "Document_5" 0}\n       @{"Contacts" link "Document_6" 0}\n\n@endnode\n\n@node "Document_0" "Disclaimer"\n\nDisclaimer\n~~~~~~~~~~\n\nACP-Page is as long freely Distributable as long as the Archive Contents stay\nintact! At least these files should be in the Archive:\n\ndoors/ACP-Page2.0 ......... Main Program ...................... 11080 Bytes\ndoors/ACP-Page2.0.c ....... Source Code ........................ 8973 Bytes\ndoors/ACP-Page.ansianim ... The Animation Sequence ............  7861 Bytes\nACP-Page2.0.doc ........... This File .......................... 4604 Bytes\nACP-Page2.0.guide ......... The .guide Version ................. 5431 Bytes\nlibs/gtlayout.library ..... Olsen''s layout library ............ 83416 Bytes\n\nFull Archive Size: 62547 Bytes\n\n@endnode\n\n@node "Document_1" "Introduction"\n\nIntroduction\n~~~~~~~~~~~~\n\nACP-Page2.0 is no longer limited to the Excelsior! BBS Package, because in\nthis Version it is a simple AmigaOS program without using any E! Commands. Due\nthe reason that I don''t know how to install DOS-Doors in other BBS Packages\nlike DLG, CNet, ... please have a look at your manual. If your BBS Software\ndon''t support DOS-Doors ACP-Page2.0 is unuseable for you. Sorry...\n\n@endnode\n\n@node "Document_2" "General Installation"\n\nGeneral Installation\n~~~~~~~~~~~~~~~~~~~~\n\nFirst Copy ACP-Page2.0 into your DOORS:, if you haven''t assigned it, you\nshould know yourself where to find it. Copy the files in the libs/#? and\ndoors/#? directory of the ACP-Page2.0 archive to the matching dirs on your\nHarddisk.  For further Installation have a look at your Manual. E! Sysop\ncontinue reading at E! Installation.\n\n@endnode\n\n@node "Document_3" "E! Installation"\n\nE! Installation\n~~~~~~~~~~~~~~~\n\nFirst Copy ACP-Page2.0 and ACP-Page.ansianim into your DOORS:, if you haven''t\nassigned it, you should know yourself where to find it. Further copy\nlibs/gtlayout.library to libs, check out if you have a newer version of the\nlibrary installed before!\n\nThen edit the EX.BBSMenus File. Primary you have to find the following line:\n\n610,  C,  0,  "1-32", ""\n\nNow insert the following text between the two ''"''s:\n\n\#4Doors:ACP-Page2.0 %1\n\nSave the File, and select the Master Window''s Pull-Down-Menu\nExtras/Re-Load/Menus. Thats all for the Installation..\n\n@endnode\n\n@node "Document_4" "Check it out"\n\n\nCheck it out\n~~~~~~~~~~~~\n\nNow make a Sysop-Login to your BBS, and type C (or the command you chose to\nlaunch the Door) at the main Menu. If everything is installed correctly you\nshould see something like that:\n\n                              .-----------------.\n                              |   ACP-Page2.0   |\n                     .-----------------------------------.\n                     |  >>> ENTER a REASON for CHAT <<<  |\n.----------------------------------------------------------------------------.\n|                                                                            |\n`----------------------------------------------------------------------------''\n                     |        by  ACP-Development        |\n                     `-----------------------------------''\n                              |  (C) 1994/95    |\n                              `-----------------''\n\nEnter a chat-reason and... a window pops up at the Workbench Screen! If you\nfeel to chat to the paging User click the ''OK Let''s chat'' gadget in the Window\nand the user will be informed that you will enter chat-mode soon, otherwise\ndont touch it or press ''Deny Chat'' - it closes itself after a few seconds. The\nuser won''t notice that you are at home.\n\n@endnode\n\n@node "Document_5" "ANSI-Animation"\n\nANSI-Animation\n~~~~~~~~~~~~~~\n\n\nThe displayed animation can be replaced by any selfmade one. We used DIed to\ngenerate a nice one. If you make your own, feel free to send it us, we will\nconsider to release it with the next update of ACP-Page.\n\n@endnode\n\n@node "Document_6" "Contacts"\n\nContacts\n~~~~~~~~\n\nHave fun with ACP-Page! If you find some bugs or have ideas how to enhance\nACP-Page in the future, simply send a NetMail or Crashmail to\n\nPeter Augustin\n2:310/72.88@fidonet\n39:23/5@AmigaNet\n314:300/1@ENet\n\nor to\n\nMichael Gredenberg\n2:310/108@fidonet\n\nor an EMail to\n\[email removed]\n\nor call \n\n+43 2252 46519   Amiga Crackpoint USR V.34+ 33600bps\n+43 2252 82615   Amiga Crackpoint ISDN 64k  64000bps\n+43 222 8761678  FaaastLane       USR V.34+ 33600bps\n\n\nFor snail-Mail write to\n\nACP-Development\nP.O.Box 98 1097\nVienna\nAustria/Europe\n\n@endnode\n\n@node "Document_6" "History"\n\nHistory\n~~~~~~~\n\n1.0 - 14.08.94\n      Initial Release\n\n1.1 - Internal Revision\n\n1.2 - 06.02.95\n      When the ChatReason was > 70 chars, E!-Page hung. Fixed.\n\n2.0 - 06.07.95\n      Completly rewritten to C\n      ACP-Page is no longer limited to E! BBS\n      Due to this reason it got renamed from E!-Page to ACP-Page.\n      Now supports gtlayout.library\n      Exchangeable ANSI-Animation.\n      Added a .guide Version\n@endnode\n\n','\n',char(10)),NULL,'auto-added',69791,7,0,NULL,NULL,'acpage20','scan',1780048365);
