INSERT INTO door_catalog VALUES('adtf','ADTF.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ADTF.LHA',NULL,'XIM','.------------------------------------------.',NULL,NULL,NULL,'|    fRONT eND fOR aMINET dIRECTORY tOOL   | | :                                      : | `-:---------                    ---------:-''',replace('.------------------------------------------.\n|    fRONT eND fOR aMINET dIRECTORY tOOL   |\n| :                                      : |\n`-:---------                    ---------:-''\n  :                                      :\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 19:09:07  ON NODE: 1\n','\r',char(13)),'\n',char(10)),NULL,NULL,27090,2,0,NULL,NULL,NULL,'scan',1780048372);
INSERT INTO door_catalog VALUES('ae_ed101','AE-ED101.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AE-ED101.LHA','UserEditor68000','XIM','UserEditor68000',NULL,NULL,'AE',NULL,replace('UserEditor Version 1.01\n','\n',char(10)),'UserEditor.doc',replace('		    ___       ___  ___\n		   / _ \____ (_) \/  / ___________________\n		  / // /    \__\    / / _ / _ / __/ __) __)\n		 / _  / _ _ / //    \/ __/  _/ _/_\_ \\_ \\n		/_//_/_/////_//__/\_/_//_/\_)________/___/\n		  The AmiExpress UserEditor Version 1.01\n		  ======================================\n\n			       Published by:\n	                 ______  ______    __            \n		        /      \/      \  /  \      \n		        \____  /\\  ___/ //   \     \n		            / /  \\ \_  // /\  \   \n		           /  \  /  _/ //  \ \  \        \n		           \__/<>\_/ <>\___/  \_/<>     \n				\n   --  -  --+- -- - -+*>> ArTiSt''S WiTh An AtTiTuDe <<*+- - -- -+-- -\n\nAmi-Express UserEditor Information file.\n\nName         : /X User-Editor.\nCoder        : Schwarzenegger/R.A.F./T.F.A.\nRelease Date : 03-01-93\nReleased at  : ToTaL CoNfUsIoN / T.F.A. WhQ\nVersion      : 1.01\nRelease      : 2\nProcessor    : 68000 + 68020+\nTyped by     : Telekinetic/T.F.A.\n\nThis documentation applies to _both_ the 68000 as well as the 68020\nversion. The previously released version only contained an 68020+ version.\n\nINTRODUCTION\n------------\n\n  AmiExpress is simply the most powerful BBS software package available today.\nBut since it lack some proper maintenance utilities, and offers a poor\nimplementation of some other program options, we decided to write our own\nUserEditor. It is an UserEditor for offline users.\n  Original idea by: Telekinetic/TFA (Total Confusion BBS).\n\nDISCLAIMER\n----------\n\n  I am never resposible for any damage caused directly or indirectly by this\nprogram to hardware or software. Allways make a backup of your data before\nyou install the program. Crucial files to copy are: user.data and user.keys.\nYou might also want to copy the acp.startup and the bbs:computerlist files.\n  If you might find any bugs, non-working features or undocumented features,\nplease feel free to contact me at:\n\n   ToTaL CoNfUsIoN BBS - +31-(0)35-855918 (ASM-One Support BBS)\n   (leave mail to me, SCHWARZENEGGER/R.A.F.)\n\nThis program is distributed as public domain. Commercial developers who wish\nto include this program in their software package, should first contact me.\n\nTECHNICAL INFORMATION\n---------------------\n\n  This program was created on an Amiga 4000. SAS/C version 6.2 was\nused to compile. This UserEditor requires Release 2.0 of the Amiga OS\nor higher.\n\nFIRST USAGE\n-----------\n\n  The AmiExpress UserEditor will automatically load some files into memory.\nThese are:\n\n  Location :		  FileName:		Comment:\n------------------------------------------------------------------------------\n  BBS:			- user.data             Normal!\n  BBS:			- user.keys 		Normal!\n  BBS:			- acp.startup		Make a copy in your bbs: !!!\n  BBS:			- node0/computerlist 	New version will get prefs!!\n------------------------------------------------------------------------------\n\n  Allways make a backup of these files before you start using a new\nprogram!\n\nFEATURES\n--------\n\nThe UserEditor is capable of doing the following:\n\n1. Cleaning up the user.data and user.keys file. AmiExpress always leaves\n   a LOT of garbage in these files (e.g., inactive users and such). The\n   UserEditor will make an attempt to either restore these users or\n   delete them permanently. It will always ask you for the final\n   decision.\n2. Adding new users\n3. Deleting users\n4. Changing the user''s data\n5. Setting presets (1..6) as stored in you acp.startup file.\n6. While loading the user.data file, the UserEditor will be checking\n   if there might be any new users. If so, the will be specified to the\n   user. You have to choices: leave them, or disable the new user\n   flag. If you choose for the last option, you will still need to\n   give him the proper access.\n\n  The UserEditor offers you a complete graphical user interface.\n\nBoth the computertypes and userslist will be available in a listview.\nJust selected a user in the listview to change its data.\nThe selected user''s name is put in the string gadget just below\nthe userlist listview.\n\nFUTURE PLANNINGS :\n------------------\n\n * Will get an user-defined preference file.\n \n * Filter for turning options on/off for selected users.\n \n * Future compatability with FREE-LEECH/T.R.S.I.\n\n * Sorting users in list view + accountnumber\n\n * Bugs get removed (Which bugs !!! gimme some !!!)\n\n * Localization (English, Dutch, German, French, and maybe Turkish or\n   Greek ?) (needs Release 2.1 or higher!)\n\n * Support of OS 3.0 specific functions (like Colorwheel)\n\n * Door for remote user editing\n\n * Editing user in the AmiExpress screen (Real Time)\n\n  Well, if you might have any ideas that could make this program more\npowerful, please feel free to contact us. Just leave mail at \n ToTaL CoNfUsIoN BBS (+31-(0)35-855918).\n\nHave fun,\n\nTELEKINETIC/T.F.A.\nSCHWARZENEGGER, The Royal Amiga Force Labs.\n \n\n -  -+-  --+  --+*>>> NoW RuNnInG On 16.8 DuAl PøWeR <<<*+--  +--  -+-  -\n \nøøøøøøøøøøøøøøøøøøøøøøøø Da|l + 31-(ø)35-855918 øøøøøøøøøøøøøøøøøøøøøøøøøø\n \n ______/\________/\_________                    ][ ThE FlÅmE ArrøWs WHQ ][\n \--  / \\    - / \\  -- - /\                   ][ $y$øp i$ TeLeK|NeT|C ][\n  \__/   \\____/   \\_____/ \\                  ][  Cø-DuDe$ ArE Pr|cE  ][\n     \   // /\\\   // /\\\   /                  ][   SaL-øNe/T.R.S.|.   ][\n      \  / \\/  \  / \\/  \ \\__                ][    ReMiX / CrY$TaL   ][\n       \/\______/\/\__/\__/\___/     /\  __                     /\  __\n                             _______/  \/  \______  __  ___  __/ \\/  \ TL\n][ 24 HøuR$ øNl|nE ][       / -  --//   \  \\  __/\/  \/   \/ /    \  \\ K\n][   CøøL U$eR$    ][      /   ___/  /\\ \  /\  / \\ ///___/\/  /\\ \  /\\n][ 96øø - 16K8 D$T ][      \\  - \\ \\/  /// \\ \  \\/__  / \\ \\/  /// \\\n][ 17ø MB''$ ønL|nE ][       \____/ \____/\/\__/\/\__/\___/  //\____/\/\__/\n                                                         \__/\n                   ][ D|$$aBlEd rAT|ø''$ Før Føre|gNeR$ ][\n                  ][ CøøL AnD GøøD ruNn|nG reQuE$T AreA ][\n                       ][ aM|Ga AnD CøN$øLe$ øNlY ][\n                 ][ Alsø 2 T|mE$ a DaY FrEE-DøWnLoAd HøuR ][\n            ][ VøTeD As øNe øF The 10 BeSt BøaRdS iN HølLaNd ][\n \nøøøøøøøøøøøøøøøøøøøøøøøø Da|l + 31-(ø)35-855918 øøøøøøøøøøøøøøøøøøøøøøøøøø\n  \n              AnD ReMeMbEr : FrIeNdSh|P RuLeZ ThEm AlL !!!\n \n -  -+-  --+  --+*>>> NoW RuNnInG On 16.8 DuAl PøWeR <<<*+--  +--  -+-  -\n \n','\n',char(10)),NULL,'auto-added',36873,4,0,NULL,NULL,'ae_ed101','scan',1780048372);
INSERT INTO door_catalog VALUES('ae_key','AE-KEY.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AE-KEY.LHA','aereg106','XIM','aereg106',NULL,NULL,'AE','| _____                _____ | | \\\\\\___   /\   ___////// | |  \______ )_/AE\_( ______/  |',replace('.--÷)> cHAMBER oF pAIN  <(÷--.\n| _____                _____ |\n| \\\\\\___   /\   ___////// |\n|  \______ )_/AE\_( ______/  |\n|        (__/rEGI\__)        |\n|           \STER/           |\n| AmiExpress \  / KeyMaker   |\n|             \/             |\n`- -÷)> 046-0223-17204 <(÷- -''\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 19:09:05  ON NODE: 1\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',7134,2,0,NULL,NULL,'ae_key','scan',1780048372);
INSERT INTO door_catalog VALUES('ae_trade','AE-TRADE.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AE-TRADE.LHA','hydracom','XIM','hydracom',NULL,NULL,'AE','who do some tradeing them selfs... For use with Jrcomm and/or Hydracom Bi-modem tranfer ----------''      `--RULEZ!',replace('Sample scripts for Ami-Express Sysops\nwho do some tradeing them selfs...\nFor use with Jrcomm and/or Hydracom\nBi-modem tranfer ----------''      `--RULEZ!\n \nSuspends node you want to call with, starts\nup jrcomm/hydracom for that node and when\nyou''re ready it resumes the node for /X...\n \nYo don''t need a brain to install this, but\nit could be of use (if ya got one)\n','\n',char(10)),'hydracom.doc',replace('\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                         HydraCom Version 1.00\n\n                    A sample implementation of the\n              HYDRA Bi-Directional File Transfer Protocol\n\n                        HydraCom was written by\n              Arjen G. Lentz, LENTZ SOFTWARE-DEVELOPMENT\n             COPYRIGHT (C) 1991-1993; ALL RIGHTS RESERVED\n\n                  The HYDRA protocol was designed by\n            Arjen G. Lentz, LENTZ SOFTWARE-DEVELOPMENT and\n                       Joaquim H. Homrighausen\n             COPYRIGHT (C) 1991-1993; ALL RIGHTS RESERVEDINSERT INTO door_catalog VALUES('ae_ue102','AE-UE102.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AE-UE102.LHA',NULL,'XIM','UserEditor.68000',NULL,NULL,'AE','/      \/      \  /  \ \____  /\\  ___/ //   \ / /  \\ \_  // /\  \',replace('       ______  ______    __            \n      /      \/      \  /  \      \n      \____  /\\  ___/ //   \     \n          / /  \\ \_  // /\  \   \n         /  \  /  _/ //  \ \  \        \n         \__/<>\_/ <>\___/  \_/<>     \n AmiExpress /X 3.x UserEditor Version 1.02\n      Schwarzenegger/R.A.F./T.F.A.\n','\n',char(10)),'UserEditor.doc',replace('		    ___       ___  ___\n		   / _ \____ (_) \/  / ___________________\n		  / // /    \__\    / / _ / _ / __/ __) __)\n		 / _  / _ _ / //    \/ __/  _/ _/_\_ \\_ \\n		/_//_/_/////_//__/\_/_//_/\_)________/___/\n		  The AmiExpress UserEditor Version 1.02\n		  ======================================\n\n			       Published by:\n	                 ______  ______    __            \n		        /      \/      \  /  \      \n		        \____  /\\  ___/ //   \     \n		            / /  \\ \_  // /\  \   \n		           /  \  /  _/ //  \ \  \        \n		           \__/<>\_/ <>\___/  \_/<>     \n				\n   --  -  --+- -- - -+*>> ArTiSt''S WiTh An AtTiTuDe <<*+- - -- -+-- -\n\nAmi-Express UserEditor Information file.\n\nName         : /X User-Editor.\nCoder        : Schwarzenegger/R.A.F./T.F.A.\nRelease Date : 03-19-93\nReleased at  : ToTaL CoNfUsIoN / T.F.A. WhQ\nVersion      : 1.02\nRelease      : 3\nProcessor    : 68000 + 68020+\nTyped by     : Telekinetic/T.F.A.\n\nThis documentation applies to _both_ the 68000 as well as the 68020\nversion. The previously released version only contained an 68020+ version.\n\nINTRODUCTION\n------------\n\n  AmiExpress is simply the most powerful BBS software package available today.\nBut since it lack some proper maintenance utilities, and offers a poor\nimplementation of some other program options, we decided to write our own\nUserEditor. It is an UserEditor for offline users.\n  Original idea by: Telekinetic/TFA (Total Confusion BBS).\n\nDISCLAIMER\n----------\n\n  I am never resposible for any damage caused directly or indirectly by this\nprogram to hardware or software. Allways make a backup of your data before\nyou install the program. Crucial files to copy are: user.data and user.keys.\nYou might also want to copy the acp.startup and the bbs:computerlist files.\n  If you might find any bugs, non-working features or undocumented features,\nplease feel free to contact me at:\n\n   ToTaL CoNfUsIoN BBS - +31-(0)35-855918 (ASM-One Support BBS)\n   (leave mail to me, SCHWARZENEGGER/R.A.F.)\n\nThis program is distributed as public domain. Commercial developers who wish\nto include this program in their software package, should first contact me.\n\nTECHNICAL INFORMATION\n---------------------\n\n  This program was created on an Amiga 4000. SAS/C version 6.2 was\nused to compile. This UserEditor requires Release 2.0 of the Amiga OS\nor higher.\n\nFIRST USAGE\n-----------\n\n  The AmiExpress UserEditor will automatically load some files into memory.\nThese are:\n\n  Location :		  FileName:		Comment:\n------------------------------------------------------------------------------\n  BBS:			- user.data             Normal!\n  BBS:			- user.keys 		Normal!\n  S:			- acp.startup		Orginal Acp.Startup Path\n  BBS:			- node0/computerlist 	New version will get prefs!!\n------------------------------------------------------------------------------\n\n  Allways make a backup of these files before you start using a new\nprogram!\n\nFEATURES\n--------\n\nThe UserEditor is capable of doing the following:\n\n1. Cleaning up the user.data and user.keys file. AmiExpress always leaves\n   a LOT of garbage in these files (e.g., inactive users and such). The\n   UserEditor will make an attempt to either restore these users or\n   delete them permanently. It will always ask you for the final\n   decision.\n2. Adding new users\n3. Deleting users\n4. Changing the user''s data\n5. Setting presets (1..6) as stored in you acp.startup file.\n6. While loading the user.data file, the UserEditor will be checking\n   if there might be any new users. If so, the will be specified to the\n   user. You have to choices: leave them, or disable the new user\n   flag. If you choose for the last option, you will still need to\n   give him the proper access.\n\n  The UserEditor offers you a complete graphical user interface.\n\nBoth the computertypes and userslist will be available in a listview.\nJust selected a user in the listview to change its data.\nThe selected user''s name is put in the string gadget just below\nthe userlist listview.\n\nCHANGES:\n--------\n\n * Small bug in save routine is now fixed.\n   Thanx to TELEKINETIC for letting me know!\n\n * Changed acp.startup path from BBS: to S:. This is the original\n   AmiExpress path.\n\nFUTURE PLANNINGS :\n------------------\n\n * Will get an user-defined preference file.\n \n * Filter for turning options on/off for selected users.\n \n * Future compatability with FREE-LEECH/T.R.S.I.\n\n * Sorting users in list view + accountnumber\n\n * Bugs get removed (Which bugs !!! gimme some !!!)\n   If you might find some, please let me know as soon as possible!\n   Call Total Confusion for it!\n\n * Localization (English, Dutch, German, French, and maybe Turkish or\n   Greek ?) (needs Release 2.1 or higher!)\n\n * Support of OS 3.0 specific functions (like Colorwheel)\n\n * Door for remote user editing\n\n * Editing user in the AmiExpress screen (Real Time)\n\n  Well, if you might have any ideas that could make this program more\npowerful, please feel free to contact us. Just leave mail at \n ToTaL CoNfUsIoN BBS (+31-(0)35-855918).\n\nHave fun,\n\nTELEKINETIC/T.F.A.\nSCHWARZENEGGER, The Royal Amiga Force Labs.\n \n\n -  -+-  --+  --+*>>> NoW RuNnInG On 16.8 DuAl PøWeR <<<*+--  +--  -+-  -\n \nøøøøøøøøøøøøøøøøøøøøøøøø Da|l + 31-(ø)35-855918 øøøøøøøøøøøøøøøøøøøøøøøøøø\n \n ______/\________/\_________                    ][ ThE FlÅmE ArrøWs WHQ ][\n \--  / \\    - / \\  -- - /\                   ][ $y$øp i$ TeLeK|NeT|C ][\n  \__/   \\____/   \\_____/ \\                  ][  Cø-DuDe$ ArE Pr|cE  ][\n     \   // /\\\   // /\\\   /                  ][   SaL-øNe/T.R.S.|.   ][\n      \  / \\/  \  / \\/  \ \\__                ][    ReMiX / CrY$TaL   ][\n       \/\______/\/\__/\__/\___/     /\  __                     /\  __\n                             _______/  \/  \______  __  ___  __/ \\/  \ TL\n][ 24 HøuR$ øNl|nE ][       / -  --//   \  \\  __/\/  \/   \/ /    \  \\ K\n][   CøøL U$eR$    ][      /   ___/  /\\ \  /\  / \\ ///___/\/  /\\ \  /\\n][ 96øø - 16K8 D$T ][      \\  - \\ \\/  /// \\ \  \\/__  / \\ \\/  /// \\\n][ 17ø MB''$ ønL|nE ][       \____/ \____/\/\__/\/\__/\___/  //\____/\/\__/\n                                                         \__/\n                   ][ D|$$aBlEd rAT|ø''$ Før Føre|gNeR$ ][\n                  ][ CøøL AnD GøøD ruNn|nG reQuE$T AreA ][\n                       ][ aM|Ga AnD CøN$øLe$ øNlY ][\n                 ][ Alsø 2 T|mE$ a DaY FrEE-DøWnLoAd HøuR ][\n            ][ VøTeD As øNe øF The 10 BeSt BøaRdS iN HølLaNd ][\n \nøøøøøøøøøøøøøøøøøøøøøøøø Da|l + 31-(ø)35-855918 øøøøøøøøøøøøøøøøøøøøøøøøøø\n  \n              AnD ReMeMbEr : FrIeNdSh|P RuLeZ ThEm AlL !!!\n \n -  -+-  --+  --+*>>> NoW RuNnInG On 16.8 DuAl PøWeR <<<*+--  +--  -+-  -\n \n','\n',char(10)),NULL,'auto-added',37644,5,0,NULL,NULL,'ae_ue102','scan',1780048372);
INSERT INTO door_catalog VALUES('ae','AE.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AE.LHA',NULL,'XIM','How to Code /X Doors in ASM!',NULL,NULL,NULL,NULL,replace('How to Code /X Doors in ASM!\n\n','\n',char(10)),'COOLIO.TXT',replace('INSERT INTO door_catalog VALUES('ae18_36','AE18_36.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AE18_36.LHA','AmigaGuide','XIM','AmigaGuide',NULL,NULL,'AE18','|.: Amiexpress from 3.18 Update to 3.36  :.| |.:U P D A T E  D O C U M E N T A T I O N:.| |New Custom Commands ; MCI Commands ;      |',replace('+------------------------------------------+\n|.: Amiexpress from 3.18 Update to 3.36  :.|\n|.:U P D A T E  D O C U M E N T A T I O N:.|\n|New Custom Commands ; MCI Commands ;      |\n|Account Editor ; Time Routines ;          |\n|Suggestions and Bug Reports ;             |\n|Upcoming Releases ; AmiXnet Updates       |\n|      and MUCH More In Amiga Quide Format |\n| Amiga Quide Included                     |\n+------------------------------------------+\n','\n',char(10)),'AE-Update.Guide',replace('@DATABASE AE-Update.guide\n@$VER: AE-Update.Guide v3.18-3.36 (19-Feb-94)\n\n@REM Copyright (c) 1993 LightSpeed Technologies Inc.\n@REM All Rights Reserved\n@REM Merged together by RaJ-Ban - Swedish Dist site !\n\n@node MAIN "/X Update Documentation (1993-1994)"\n               .: U P D A T E  D O C U M E N T A T I O N :.\n               --------------------------------------------\n\n             Choose the version you want to review for Updates!\n             (If this is the 1st time you read this Guide, then read\n              them all to get all changes !)\n\n                     @{" Updates in v3.18             " Link UPDATE318}\n                     @{" Updates in v3.19             " Link UPDATE319}\n                     @{" Updates in v3.31             " Link UPDATE331}\n                     @{" Updates in v3.34             " Link UPDATE334}\n                     @{" Updates in v3.35             " Link UPDATE335}\n                     @{" Updates in v3.36             " Link UPDATE336}\n\n                  ------------------------------------\n\n  Documentation written by:\n  Joseph Hodge\n  LightSpeed Technologies Developement\n\n  Updated by:\n  The Outlaw /X WHQ\n  RaJ-Ban\n  Swedish /X-Dist\n\n  Copyright (c) 1993 LightSpeed Technologies Inc.  All Rights Reserved.\n  Any copy or illegal distribution of this Documentation is prohibited.\n\n@endnode\n\n@node UPDATE318 "/X Update 3.18 (c)1993 LightSpeed Technologies Inc."\n               .: U P D A T E  D O C U M E N T A T I O N :.\n\n             The following is a list of changes to version 3.18\n             of AmiExpress. (01-Nov-93)\n\n                     @{" Custom Commands              " Link Update31801}\n                     @{" MCI Commands                 " Link Update31802}\n                     @{" Message Base                 " Link Update31803}\n                     @{" Account Editor               " Link Update31804}\n                  ------------------------------------\n\n  Copyright (c) 1993 LightSpeed Technologies Inc.  All Rights Reserved.\n  Any copy or illegal distribution of this Documentation is prohibited.\n\n@endnode\n@node Update31801 "Custom Commands (Doors)"\n  =========================================================================\n  We added a configuration option to the module icons called:\n\n  PASS_PARAMETER=4\n\n  This option will tell AmiExpress to bypass checking the BBSCMD modules.\n\n  This option was primarily introduced to allow a sysop to invoke an\n  INTERNAL command from a ConfXCMD and forcing it to bypass checking the\n  BBSCMD directory for the INTERNAL command.\n\n@endnode\n@node Update31802 "MCI Update"\n  =========================================================================\n  Modified the following commands:\n\n  ~SR  - Show Random Files\n\n  SYNTAX: ~<num>SR_<fileid>\n\n           ^    ^  ^\n           |    |  |\n           |    |  ---------- pathname without security level and file\n           |    |             extension\n           |    ------------- Command to show random file\n           ------------------ Number of Random files\n\n  IE: ~10SR_BBS:Logon\n\n  This will look for a random file between 1-10, the syntax for the file\n  to display is:\n\n  SYNTAX: PathName<seq>.FileName[security level]<extension>\n\n  IE: BBS:001.Logon200.txt\n\n\n  This would be the first of ten files to create to be displayed\n  by the random function, the ''200'' is the security level which is\n  optional.\n\n  -----------------------------------------------------------------------\n  ~SX  - Show Sequentual Files\n\n  SYNTAX: ~SX_<fileid>\n\n           ^  ^\n           |  |\n           |  ---------- pathname without security level and file\n           |             extension\n           ------------- Command to show sequentual file\n\n  IE: ~SX_BBS:Logon\n\n  1. This will look for a file called BBS:Logon which will store the last\n     sequence of the <fileid> that was displayed. If this file does not\n     exist, the ''SX'' command will create it.\n  2. Then it will construct a display file name based on the next sequence\n     number as follows:\n\n     SYNTAX: PathName<seq>.FileName\n\n  3. It will then look for the appropriate file to display. The actual\n     ASCII file should contain the following information for the filename:\n\n     SYNTAX: PathName<seq>.FileName[security level]<extension>\n\n     IE: BBS:001.Logon200.txt --v\n         BBS:001.Logon100.txt ----- notice the different security levels\n                                    keeping in mind that they are optional.\n         BBS:002.Logon200.txt\n\n@endnode\n@node Update31803 "Message Base Changes"\n  =========================================================================\n  Following is a list of changes to the MessageBase system\n\n  Due to popular demand we revamped the mailscan. Now AmiExpress will\n  scan each conference for mail that pertains to the user that is online.\n\n  While scanning, AmiExpress will store the msg numbers in memory until\n  the end of the scan, at the end of the scan AmiExpress will proceed to\n  show the user the originator of each message and then proceed to prompt\n  the user if he/she wishes to read the mail.\n\n  This method of scanning has 3 advantages:\n\n  1. The user will now know who left him/her mail prior to reading it.\n  2. The NewMail Scan pointer will not be updated until all the mail is\n     read. So if the user has 2 messages ''100'' and ''101'' and he/she\n     reads message 101 and not 100, then the next time the user logs on\n     or does a mail scan, he/she will still  be notified of message 100.\n  3. The NewMailScan will now remember the last valid message left to\n     the user when the user losses carrier or logs off.\n\n@endnode\n@node Update31804 "Account Editor Changes"\n  =========================================================================\n  Following is a list of changes to the Account Editor\n\n  A bug was introduced in version 3.17 of AmiExpress which was intended\n  to allow the sysop to globally store a preset''s ratio into all\n  conferences for a given user.\n\n  This change caused an error condition in that once the last conference\n  was filled with a ratio, AmiExpress retained the last conference''s\n  attributes instead of the current conference. So this could have\n  resulted in message base corruption in the last conference, especially\n  if the current conference and last conference where not of the same\n  message base type. This bug would only occur while validating users\n  that are online or when validating a user from the message base.\n\n  We have removed this bug and now everything should be fine.\n\n@endnode\n\n@node UPDATE319 "/X Update 3.19 (c)1993 LightSpeed Technologies Inc."\n               .: U P D A T E  D O C U M E N T A T I O N :.\n\n             The following is a list of changes to version 3.19\n             of AmiExpress. (12-Nov-93)\n\n                     @{" Message Base                 " Link Update31901}\n                     @{" Account Editor               " Link Update31902}\n                     @{" Time Routines                " Link Update31903}\n                     @{" Suggestions and Bug Reports  " Link Update31904}\n                     @{" Upcoming Releases            " Link Update31905}\n                     @{" Developement Issues          " Link Update31906}\n                     @{" Beta Testers                 " Link Update31907}\n                  ------------------------------------\n\n  Copyright (c) 1993 LightSpeed Technologies Inc.  All Rights Reserved.\n  Any copy or illegal distribution of this Documentation is prohibited.\n\n@endnode\n@node Update31901 "Message Base Changes"\n  =========================================================================\n  Following is a list of changes to the MessageBase system\n\n  We removed the ''...'' which was being displayed during each conference new\n  mail scan.\n\n  Fixed a problem with deleting accounts from the message base.\n  The previous version would not properly restore the current conference\n  location after reseting the user''s conference stats in each conference.\n  This could have resulted in possible msgbase corruption.\n\n  *REMARKS*\n\n  A couple of releases ago we introduced a bug in AmiExpress which caused\n  user''s accounts to improperly reflect the number of messages the user\n  has posted. Since the incorrect figures overwrote the user''s original\n  message posted stats, we had no way of correcting the damage that was\n  already done, but in version 3.18 we introduced a conference maintenance\n  function ''F5'' which contains a new command option ''6'' which allows a\n  sysop to reset the message posted field of the conf.db for each account\n  for a given conference. So those who have experienced this problem,\n  please proceed to CONFERENCE MAINTENANCE to reset the message posted\n  field.\n\n@endnode\n@node Update31902 "Account Editor Changes"\n  =========================================================================\n  Following is a list of changes to the Account Editor\n\n  Fixed the account editor so if user updates his own Time_Used\n  using the ''1'' menu prompt command, the change will effect the daily\n  time used and not only the session time used.\n@endnode\n@node Update31903 "Time Routines"\n  =========================================================================\n  Following is a list of changes to the Time Routines\n\n  Fixed the F2 and F3 online menu commands so that the user''s time\n  change will effect the daily time limits as well as the session time.\n@endnode\n@node Update31904 "Suggestions and BugReports"\n  =========================================================================\n  Following is a list of Suggestions and BugReports we would like to\n  address.\n\n  BUGREPORT:\n  -------------------------------------------------------------------------\n  [11-12-93] CHB of Blizzard\n\n  Hi,\n  there is a nasty bug also in the /X 3.18 release!\n  XPR uploads and downloads are not counted, so anyone who uses XPR\n  protocolls can suck without end!\n  Please remaove that bug quick!\n\n  CHB of Blizzard\n\n  COMMENTS FROM AUTHOR:\n\n     We have researched this problem on more than one occassion and from\n     our research have concluded that this problem is isolated to 1\n     zmodem xpr library which we feel is an error in the xpr library\n     itself. If you experience this problem from more than 1 library\n     please let us know the library names so that we may properly research\n     the problem.\n\n  -------------------------------------------------------------------------\n  [11-10-93] THE CHAMP\n\n  /X 3.18 - MessageBase-Counters still destroyed...\n            MCI-Command xxSR_" isn''t working... only when entering\n            values higher than 9... so that we use two numbers...\n            the sec. level after the FileName isn''t work, too\n\n\n  COMMENTS FROM AUTHOR:\n\n     Please read the *REMARKS* in the messagebase updates section of\n     this guide to resolve the problem with your message posted values.\n     If the problem still persists after that please inform us immediately.\n\n     Please refer to the changes text in version 3.18 for the new file\n     naming conventions for the SR and SX command. We will research this\n     problem on our end as well.\n\n  -------------------------------------------------------------------------\n  [11-08-93] Rad!\n\n  Message base problems :\n\n  The messages are again becoming blank on my bbs using 3.18 for the first\n  conference and the first conference only??? Dunno what is causing this\n  problem but no messages are able to be read, and I don''t want to loose my\n  message base... snief.. hehe\n\n  - Rad!\n\n  COMMENTS FROM AUTHOR:\n\n     This problem is probably the direct result of deleting an account\n     from the message base. This should be fixed in this release.\n\n\n@endnode\n@node Update31905 "Upcoming Releases"\n  =========================================================================\n  Following is a list of changes and additions to upcoming releases of\n  AmiExpress. These changes may or may not come to pass but we would like\n  to keep you informed.\n\n  We are currently Testing a 32 node capable version of AmiExpress. This\n  version is being developed along side the 9 node version ''3.19''. The\n  most important difference besides the 32 node capability is the fact\n  that the 32 node version is ''pure'' so that only one copy needs to be\n  in memory at a time. During the process of making the 32 node version\n  ''pure'' we had to temoporarily disable the XPR interface capability which\n  is what we are working on right now. The Assembly code for the XPR\n  interface was not coded in a way that permits us to make it ''pure'' so\n  we are recoding it right now. We bring this information to you mainly\n  because we want some feedback. If we release the 32 node version to the\n  public there will more than likely be a revision fee.\n\n  Those that maybe interested in testing the 32 node version should\n  consult The primary support board for details on obtaining a copy.\n  This will most likely me signing some agreements forms to include\n  a non-disclosure form and an upgrade fee.\n\n  Concerning all versions of AmiExpress:\n\n  1. We intend on providing more internal functions to the program, to\n     include a built in last callers routine which will be configurable\n     from MCI commands.\n  2. We plan on modifying the msgbase routines so that you can read a\n     message and suppress the READ MESSAGE flag. This will be useful\n     in instances where you read some mail and do not wish the orginator\n     to know that you have read it yet. This is an important option to\n     most sysops.\n@endnode\n@node Update31906 "Developement Issues"\n  =========================================================================\n\n  Those of you wishing to write modules or utilities for AmiExpress to\n  obtain a profit, please consult the primary support board for information\n  on obtaining licensing agreements and any associated fees.\n\n  We will also be opening the 3 developer support Bulletin Boards in a\n  couple of weeks. These boards will be devoted to providing the developer\n  with any technical information at our disposal for assistance in\n  developing and maintaining utilities and modules for AmiExpress.\n\n  We will be charging an annual development fee to compensate for the\n  time required to provide the information and assitance you may need.\n\n  Those interested in becoming registered developers please consult\n  the primary support board for further details.\n\n@endnode\n@node Update31907 "Beta Testing"\n  =========================================================================\n\n  The developement of any large scale program undoubtably requires the\n  assistance of BetaTesters. AmiExpress is no exception (we all know that).\n\n  Those interested in beta testing AmiExpress please consult the primary\n  support board to obtain a non-disclosure form.\n\n@endnode\n\n@node UPDATE331 "/X Update 3.31 (c)1992-1994 LightSpeed Technologies Inc."\n               .: U P D A T E  D O C U M E N T A T I O N :.\n\n             The following is a list of changes to version 3.31\n             of AmiExpress. (02-Jan-94)\n\n                     @{" MultiComm Port               " Link Update33101}\n                     @{" Program Execution            " Link Update33102}\n                     @{" MCI Commands                 " Link Update33103}\n                     @{" Internal Zmodem Protocol     " Link Update33104}\n                     @{" XPR Protocols                " Link Update33105}\n                     @{" Custom Commands              " Link Update33106}\n                     @{" Message Base                 " Link Update33107}\n                     @{" AmiXnet Updates              " Link Update33108}\n                  ------------------------------------\n\n  Copyright (c) 1994 LightSpeed Technologies Inc.  All Rights Reserved.\n  Any copy or illegal distribution of this Documentation is prohibited.\n\n@endnode\n@node Update33101 "MultiComm Port"\n  =========================================================================\n  Following is a list of changes to the MultiComm Port\n\n  Since version 3.30 of AmiExpress we have increased the Maximum Number\n  of Nodes that ACP can handle. ACP can now handle a maximum of 32 Nodes.\n\n  This change involved changing the internal MultiComm structure to handle\n  32 nodes vs 9 nodes. This change means that the old NewChat and some of\n  the older Online Message Send Modules may not work any longer. We have\n  released an update to the NewChat door so that it will handle the 32\n  node configuration.\n\n@endnode\n@node Update33102 "Program Execution"\n  =========================================================================\n\n  Since version 3.30 of AmiExpress you now have the ability to make\n  AmiExpress resident. Doing this should speed up program execution\n  and also conserve memory.\n\n  Making AmiExpress resident:\n\n  1. change all nodestart tooltypes in the NODE icons to reflect the\n     following:\n\n     NODESTART=express\n\n  2. Update your s:user-startup script by adding the following after\n     your BBS Assignment:\n\n     RESIDENT EXPRESS BBS:EXPRESS\n\n\n@endnode\n@node Update33103 "MCI Commands"\n  =========================================================================\n  Following is a list of changes to the MCI Commands\n\n  I have modified the ~CC command to allow the execution of MENU PROMPT\n  commands. This will allow you to run the internal WHO command from any\n  MCI text. Simply add this MCI command to your MCI Text File:\n\n  ~CC_WHO\n\n  NOTE: It is important to realise that most MENU COMMANDS should only\n        be run from the MENU PROMPT. For Instance , forcing the READING\n        of mail at the FRONTEND of express would not be wise because the\n        BBS does not know who is logging onto the system. So use your\n        own judgement on these matters.\n\n@endnode\n@node Update33104 "Internal Zmodem Protocol"\n  =========================================================================\n  Following is a list of changes to the Internal Zmodem Protocol\n\n  I added the tooltype HDTRANSBUFFER, this tooltype is for the node icons.\n\n  HDTRANSBUFFER allows you to change the buffer size from serial to\n  harddisk. This option is a better alternative than using a RAMPEN because\n  it works on a file by file basis, whereas the RAMPEN method has to wait\n  until all uploads are complete.\n\n  HDTRANSBUFFER has the following syntax:\n\n  HDTRANSBUFFER=<buffers>\n\n      You may specifiy as many buffers as you like. The number of buffers\n      default to 8 if this tooltype is not used. Here is a formula for\n      determining how much memory will be allocated for transfers when the\n      node is started:\n\n      ((buffers+2)*1024)*2\n                         ^--- This is required due to the double buffering.\n\n      ie:\n\n      HDTRANSBUFFER=20 would require 45,056 bytes of memory\n\n      1. ((20+2)*1024)*2\n      2. (22*1024)*2\n      3. (22528)*2\n      4. 45056\n\n    Version 3.30 a bug was introduced with this HDTRANSBUFFER addition.\n  AmiExpress was not freeing the memory it allocated for the buffers. This\n  is the primary reason for releasing this version.\n\n@endnode\n@node Update33105 "XPR Protocols"\n  =========================================================================\n  Following is a list of changes to the XPR Protocols Interface:\n\n  We have temporarily removed the XPR interface and placed it in a SYSCMD.\n  We will most likely put this back into AmiExpress in a month or so.\n\n  One of the important changes to AmiExpress besides this is now all batch\n  Protocol Icons must contain the tooltype AE_BATCH instead of BATCH.\n\n@endnode\n@node Update33106 "Custom Commands"\n  =========================================================================\n\n  I added the tooltype ''QUICKMODE'' for the module icons. This tooltype\n  simply tells AmiExpress not to run the Module in question if the user\n  has logged onto the sysop using the QUICK logon option.\n\n@endnode\n@node Update33107 "Message Base"\n  =========================================================================\n\n  Since Version 3.30 the message base has been modified to re-display\n  the original message if a reply to a message was aborted.\n\n@endnode\n@node Update33108 "AmiXnet Updates"\n  =========================================================================\n\n  Due to the expansion of the Net, including more sales and increased\n  volume of mail, we realized the need for a more optimized method of\n  packing netmail. AmiXnet currently recalculates the MailRoute for\n  every net mail conference when it is packing mail and unpacking mail.\n  This in itself is not efficient. Therefore I modified all of the NETMAIL\n  utilities to recognize pre computed mailroutes, this greatly speeds up\n  the mail packing process for those with only one Node Id.\n\n  In order to invoke the optimized method of packing mail you will need to\n  do the following:\n\n  1. Modify the scripts that run MRUPDATE with an additional commandline\n     option ''AUTOUPDATE''. AUTOUPDATE should be the last commandline option\n     to MRUPDATE. This will force MRUPDATE to create pre-calculated\n     mailroutes when new maps come down the net.\n\n  2. Create a directory in BBS:AmiXnet named your node id. For instance I\n     have a directory called:\n\n     BBS:AmiXnet/703001 because 703001 is my nodeid.\n\n  Once you have done the above, the next time mail is packed the netutils\n  will create pre-computed route files and place them into the newly\n  created directory.\n\n  NOTE: ONLY DO THIS IF YOU HAVE ONLY 1 NODE ID. THERE IS A COUPLE OF\n        BBSs WITH MULTIPLE NODE IDS, THIS OPTION WILL NOT WORK FOR THEM\n        AT THE MOMENT. I HOPE IN THE NEAR FUTURE I WILL HAVE THIS SOLVED.\n\n\n\n@endnode\n@node UPDATE334 "/X Update 3.34 (c)1992-1994 LightSpeed Technologies Inc."\n               .: U P D A T E  D O C U M E N T A T I O N :.\n\n             The following is a list of changes to version 3.34\n             of AmiExpress. (13-Feb-94)\n\n                     @{" Foreword                     " Link Update33401}\n                     @{" Internal Commands            " Link Update33402}\n                     @{" Multinode Chat               " Link Update33403}\n                     @{" Conference tooltypes         " Link Update33404}\n                     @{" Custom Commands              " Link Update33405}\n                     @{" Doors                        " Link Update33406}\n                     @{" Final words                  " Link Update33407}\n                  ------------------------------------\n\n  Copyright (c) 1994 LightSpeed Technologies Inc.  All Rights Reserved.\n  Any copy or illegal distribution of this Documentation is prohibited.\n\n@endnode\n@NODE update33401 "Forewords about the v3.34"\n  =========================================================================\n\n  First of all I think all of you guys, should tip your hat off to\n  Joe this month for all the extra work he has done for this release.\n  he has been putting in all his days and nights over the last few\n  weekends to make all these changes. THANKS JOE.\n\n  Personally I am very excited about the changes that are being incorp-\n  orated into express and a lot more coming.\n\n@endnode\n@NODE update33402 "Internal Commands"\n  =========================================================================\n\n  1. There is a new command called ''CF''. This command will allow your users\n     to set the way express handles conferences. From here they can set the\n     ''NEW FILE SCAN'', ''NEW MESSAGE SCAN'', and turn ''OFF'' and ''ON'' what\n     conferences they want to ZOOM mail from.\n\n     In the Conference Maintainance option in the Account editor you can\n     also Globaly set these options (F5).\n\n  2. In the ''W'' option for users, is now the ability for the user to pick\n     what kind of Zoom they want. They can pick QWK, or the old ascii\n     zoom option.\n     NOTE: You must first install some new Icons in the ZOOM dir, otherwise\n           it wont work. Samples are included in the ''UPDATE.LHA'' archive.\n           Edit them to fit your needs !\n\n@endnode\n@NODE update33403 "Multinode Chat update"\n  =========================================================================\n\n  The second biggest feature is that /X now has ''MESSAGE QUE'' capabilty for\n  multinode chat. Remember when you would chat someone on another node, and\n  they were busy doing something, and they would never get the message,\n  well now when the user is done, they will receive the mesaage you sent\n  them. There is a new ''NEWCHAT'' door online to grab, that uses this new\n  capability. (also included in the UPDATE.LHA package)\n\n@endnode\n@NODE update33404 "New TOOLTYPES to the conf icons"\n  =========================================================================\n\n  New options in the conf icons for you sysops:\n\n  FORCE_NEWSCAN\n  -------------\n  This will force your users to have a New Mail scan whether they\n  have selected it or not.\n\n  NO_NEWSCAN\n  ----------\n  This will Force No New Mail scan whether a uers has turned it off or\n  not.\n\n  SHOW_NEW_FILES\n  --------------\n  This is not a new command, but if used in the conf icon, will act\n  like the above force command for messages\n  IE: Force your users to get a new file scan whether they have chosen\n      it or not.\n\n@endnode\n@NODE update33405 "Custom Commands"\n  =========================================================================\n\n  Another new option is for your commands Dir. You can now make an icon\n  called ''NODE#CMD'' This is used like your CONF#CMD Option. Now your node\n  can use it as well.\n\n@endnode\n@NODE update33406 "BugFix for Door icon Tooltype"\n  =========================================================================\n\n  In this version there was also a BUG FID in the doors icons.\n  PRIORITY=<xx> has now been fixed. If you use PRIORITY=SAME,\n  it will use the same Priority that express uses.\n\n@endnode\n@NODE update33407 "Final Words"\n  =========================================================================\n\n  Well I think that is all. If I have forgotten to tell you everything I\n  will leave a message. Wow what a month. Ok enjoy the new express.\n  Included in archieve, is also the icons needed to put in your zoom dir.\n  For those of you useing utilities that delete everything in your Zoom\n  directory, I advise you to stop useing them. It will delete these icons\n  needed.\n  Ok that''s it for now.\n\n  /LIGHTSPEED TECHNOLOGIES INC.\n\n@endnode\n@node UPDATE335 "/X Update 3.35 (c)1992-1994 LightSpeed Technologies Inc."\n               .: U P D A T E  D O C U M E N T A T I O N :.\n\n             The following is a list of changes to version 3.35\n             of AmiExpress. (14-Feb-94)\n\n                     @{" User access                  " Link Update33501}\n                  ------------------------------------\n\n  Copyright (c) 1994 LightSpeed Technologies Inc.  All Rights Reserved.\n  Any copy or illegal distribution of this Documentation is prohibited.\n\n@endnode\n@NODE update33501 "Access tooltype"\n  =========================================================================\n\n  Added a new tooltype For Access.info or /access/ACS.xxx.info !\n\n  ACS.CONFFLAGS\n  -------------\n  This tooltype sets at what access a user can use the CF command.\n\n@endnode\n@node UPDATE336 "/X Update 3.36 (c)1992-1994 LightSpeed Technologies Inc."\n               .: U P D A T E  D O C U M E N T A T I O N :.\n\n             The following is a list of changes to version 3.36\n             of AmiExpress. (14-Feb-94)\n\n                     @{" Bug Fixes                    " Link Update33502}\n                  ------------------------------------\n\n  Copyright (c) 1994 LightSpeed Technologies Inc.  All Rights Reserved.\n  Any copy or illegal distribution of this Documentation is prohibited.\n\n@endnode\n@NODE update33502 "Bug Fixes"\n  =========================================================================\n\n  Found a bug in the way /X handled the PRIORITY=X In the doors icons.\n  This has been fixed.\n\n  Modified the ''CF'' Command to display double lines if a user has access\n  to more than 10 Conferences.\n\n@endnode\n','\n',char(10)),'{"PRIORITY":"<xx>"}','auto-added',20343,5,0,NULL,NULL,'ae18_36','scan',1780048372);
INSERT INTO door_catalog VALUES('ae21doc','AE21DOC.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AE21DOC.LHA',NULL,'XIM','Complete run-thru Doc',NULL,NULL,NULL,NULL,replace('Complete run-thru Doc\n','\n',char(10)),'BBSINFO.TXT',replace('                            BBSInfo Conference:\n			   ~~~~~~~~~~~~~~~~~~~~~\n\n                   [1] Top Uploaders   [2] Top Downloads\n\n             [3] Top Files Uploader   [4] Top Files Downloader\n\n                            [5] Ratios of Users\n\n                       [6] UserLevels (High to low)\n\n               [7] Cps Rates Download  [8] Cps Rates Upload\n\n','\n',char(10)),NULL,NULL,34323,4,0,NULL,NULL,NULL,'scan',1780048372);
