INSERT INTO door_catalog VALUES('aeadder','AEADDER.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AEADDER.LHA','arc','XIM','ARC',NULL,NULL,NULL,NULL,replace('Multi Text Adder v 1.0\n','\n',char(10)),'aeadder.doc',replace('\n        ___       _______\n       // \\      ||-----|\n      //   \\     ||___ \n     //¯¯¯¯¯\\    ||--- \n    //       \\mi ||-----|xpress Multi Text Adder v 1.0 by Pzycho/Tremors\n                  ¯¯¯¯¯¯¯\n   ########################################################################\n\n   Hi Guys...\n\n   here comez my second Amiex Tool.\n   This Tool will adding the following Files:\n   .dms .lha .lzh .run .sfx .doc .dox .txt .arc .zoo, .zip ans .zom .wrp \n   coming soon also... wait for the Update !!!\n\n   INSTALLATION :\n\n   First copy all ASCII File who stands in bbs/fcheck to your bbs/fcheck\n   Directory. then copy all who stand in the C: Directory ( pzy_*, zoo,lha,\n   arc ) to your c: Directory.\n   At the last take your Editor and edit the arcer.prefs and adder.prefs\n   for your Text ADD Files in the S: Directory.\n   The Tex.txt ist your addfile for .txt .dox and .dox, and the rest you\n   give the full path in the adder and arcer.prefs.\n   ( the TEX.TXT must be in the s: Directory !!! )\n   See my Example Prefs and addfiles...\n   Yeah thats all, it`s really simple, or don`t ???\n\n   THX, to VINCE for using your HSCHK... may be you can build a strip\n   option to your dms adder...\n\n   If you have any problems with the adders, call my Board and leave a\n   Msg. to me...\n   DIAL OUTZONE BBS ++49 (0) 2131 277208 Sysop : PzYcHo/TrEmOrS\n   \n\n   Greetings goes to NICK/TREMORS -*- CYBER/TOXIC-TRACK -*- BLUE/TREMORS\n   MICROPICTURE/HEAVENS DOOR BBS -*- KRYPTON/VENTURE -*- CARNIVORE/BEERMACHT\n   AND ALL I FORGOT ...\n\n   MUCH FUN WITH MY REAL BEST ADDERS. HEHE...\n   -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n      THIS FILE PASSED TROUGH THE...\n         |          \|/\n      ___|______   --o--       __              ______          _________\n         /  /|  |   /|\       |  |            /  /|  |        |        /\n        // / |  | __   _______|  |_______    // / |  |__   ___||  ____/\n       // /  | |||  |  \  \___  || __   /   // /  | ||  | /   |! |_\n      // /   | :|| ||BBS\ \\  | !|/ // /   // /   | !|  |//  ||:  _>\n     // /____| .|| :|____\ \\ | :| // /   // /    | .|       !|. |___\n    /__/        || .     \___\|  |// /__//__/_____|  |   /|  .|      \\n     \__________||__________/ |__|_______|\__________|__| |___|_______\__\n                         SysOp`s : pzycho/tremors                [pzy]|\n                                  and                                 |\n      UL DATE: 15-Apr-92         cyber/toxic track    UL TIME: 11:01:11\n                                and\n                               nick/tremors\n                   give me a call : ++49 (0) 213 1277 208\n   -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n','\n',char(10)),NULL,'auto-added',97778,10,0,NULL,NULL,'aeadder','scan',1780048372);
INSERT INTO door_catalog VALUES('aecl0t0','AECL0T0.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AECL0T0.LHA',NULL,'XIM','.------------[ CALL 13th HOUR ]------------.',NULL,'Download/Leech',NULL,'|                                          | | CALLERS LOTTERY v1.o (c) cYBER/iNDY 1995 | |                                          |',replace('.------------[ CALL 13th HOUR ]------------.\n|                                          |\n| CALLERS LOTTERY v1.o (c) cYBER/iNDY 1995 |\n|                                          |\n| /X 3.x+ Give your users a Byte Bonus and |\n| File bonus when they call your cool BBS! |\n|   Totally configurable to your needs!    |\n|        Download/Leech/Suck NOW!          |\n`--------------------------------------[c]-''\n','\n',char(10)),'Lottery.doc',replace('\n             ))) CALLERS LOTTERY v1.o © cYBER 1995 (((\n\nRequirements:\n------------\n\nAny Miggy, /X v3.x+\n\n\nIntroduction:\n------------\n\nThis idea is based upon a door coded in ''93 by Goofy/Anathema.\nI decided to do this door ''cause, basically, I was bored shitless! =;)\n\n\nInstallation:\n------------\n\nPretty simple really, erm.. Copy all the dirs to your doors: dir, aswell\nas the Lottery.info icon to your SYSCMD dir.\n\nEdit your logon.txt so that it reads as follows...\n  \n------------- CUT/SNAP WHAT THE FUCK EVER ------------\n\n~CC_Lottery|\n\n------------- CUT/SNAP WHAT THE FUCK EVER ------------\n\nThe door will create a CoNFiG file that you can edit to your hearts content!\nYou can find it in your S: dir named as ''Lottery.cfg''\n\nIt''s as simple as that dude.\n\nThis door also creates a Bulletin, called ''CallWinners'', just in case for\nsome reason you wanna show ya users who''s won over the days...\n\nMost intelligent SysOps will know how to call up the Bull?? Wibble...\n\nSorry about the short dox but MOST SysOps will understand how to use this\n/X door.. but then again doh...\n\n\nQuick Personal Greets:\n---------------------\n\nAce...........: ta for letting me be a pissed up /X co-sys\nTango.........: Fuck a Fresher? naw... I''ll be irritating you soon\nRage..........: Stop nicking /X from D.Candy before I do m8 ;)\nPhaid.........: Where are you m8, I lost ya voice no: :(\nDan...........: COME BACK SOON - WE ALL MiSS YOU\nHomer.........: Where you at?\nNes...........: What you up to m8?\nData-Stream...: I know 12000 bps suxx, about time I upgraded hehehe!\nsTAB..........: I miss ENTiTY m8, bring it back... NOW!\nHotwire.......: Outta the scene for a while aye? Hmmmm... N0t\nHybrib........: ta for the dissy m8 (Hopefully see ya at the Digital Party)\nSaSha.........: YOU REALLY GOING TO PLYMOUTH? hehehe See you there m8ty\n\nEND...\n\nIf anyone wants me for whatever reason you can reach me at most happening\nboards...\n\nMainly 13th Hour BBS at the mo, ''cause I like the MAD sysops hehehe!\n\nAnY ComplAints... then fuck off, I''ve heard it already and besides, I''m\n                  usually too pissed up to notice or care! ;*)\n \n[eof]\n \n','\n',char(10)),NULL,NULL,8627,6,0,NULL,NULL,NULL,'scan',1780048372);
INSERT INTO door_catalog VALUES('aeclea11','AECLEA11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AECLEA11.LHA','AEClean','XIM','AEClean','1.1',NULL,NULL,NULL,replace('AEClean v1.1  WB2.0 ONLY!\n','\n',char(10)),'AEClean.doc',replace('        ____    __  _____  __  ____   _  _    __   __ ____\n        )(\ \  _)(_ )__ / _)(_ )(\ \ _)\/(_  _)(_  \/ )__(_\n        )(_)/  )/\(  _)/  )/\( )(_)/ )/\/\(  )/\(  /\ \) \(\n        )( )\ /(\/)\ )/__ \\// )( )\ )\  /( /(\/)\ )( /)_//\n        \/ \/ \/  \//___(  \/  \/ \/ \/  \/ \/  \/ \/ )__/\n\n                - -- ---=*)> PRESENTS: <(*=--- -- -\n \n                 *** AEClean v1.1  WB2.0 ONLY! ***\n\n     AmiExpress Utility to help U ''cleanup'' inactive accounts\n\n\nThis little utility will allow you to list all your inactive accounts\nquickly.  If you also select the WARNing and MESSage switches it''ll create\na neatly formatted stdio output which you can redirect to a file and then\npost on your board to alert the ones who are calling that their friends\nmay be loosing their accounts. You can even add it to your logoff script\nto constantly alert users (when they logon that people are about to loose\ntheir accounts because of inactivity).\n\nI originally wrote this program with lots of features to even tell you\nwhat users weren''t uploading... but to do that I also had to read in\nthe BBS:Nodex/Callerslog file and I DIDN''T want to keep a long one of\nthose on my board (well maybe 1 months worth)! so I made this version\nto strictly READ (No writing involved!) your BBS:User.Data file and\nfigure out all the information...\n\nI should mention, this program does NOT delete those accounts, it only\nTELLS YOU that certain users havn''t called in X nr of days. YOU have to\ndelete them when you feel that they'' probably wont ever call back or\nwhatever...\n\nAdditonal feature of v1.1 and up.  If you have an ''AEClean.exclude'' text\nfile with user names of those you wish exclude them from the list, it\nwill, else it wont exclude anyone! Note: this file should be located in\nyour current dir, OR your BBS: directory OR your S: directory. It will\nsearch for the file in that order. Lastly, this new feature renders this\nutility FOR USE WITH WB2.0 ONLY (don''t even try it under 1.3 hehe).\n\n\n*** SYNTAX ***\n\n\nSyntax is as follows:\n\n   AEClean <days> [WARN] [MESS] [NOANSI] [NONRS] [NODAYS]\n\nWhere:\n\n<days> is a MANDATORY number which represents the number of days back in\n       time to find out who hasn''t called. Without the nr you just get help.\n\n            -< OPTIONAL SWITCHES ON/OFF >-\n\n[WARN]   turns ON the warning borders\n[NONRS]  turns OFF the numbers before the users names\n[NOANSI] turns OFF ANSI colors for warning & message\n[NODAYS] turns OFF the printing of UserX ''hasnt called in X days'' text\n[MESS]   turns ON a text message for easy AE message creation\n\nNote: The MESSage switch will print a message which will warn the users\n      that you''ll delete them after 1/2 the value of days passes. I did\n      this cause I wanted it that way for my board! I issue a 60 day\n      warning and then delete them after 90 days!\n\nTo redirect output to file use ''>''. Ie.. AEClean >ram:test 30 WARN MESS\n\n\n*** SAMPLE USE ***\n\n\nAt any Shell/Cli type:  AEClean 60 WARN MESS\n\nWill probably give you an output that looks something like this...\n\n +--------------------------------------------------------------------+ \n       WARNING     WARNING     WARNING     WARNING     WARNING \n +--------------------------------------------------------------------+ \n   The following users have failed to call the BBS in over 60\n   days and will be deleted from the board after another 30 days\n   of inactivity. Please mention it to them if you know them.\n\n       (1) Blue hasn''t called in 79 days\n       (2) John hasn''t called in 71 days\n       (3) Snake hasn''t called in 62 days\n       (4) Phantom hasn''t called in 70 days\n +--------------------------------------------------------------------+ \n       WARNING     WARNING     WARNING     WARNING     WARNING \n +--------------------------------------------------------------------+ \n\nTo get the names without anything else, you can enter the following:\n\n  AEClean 60 NONRS NODAYS\n\nand your output for the above data should look something like this:\n\n       Blue\n       John\n       Snake\n       Phantom\n\nOf course, you can always type: ''AEClean'' by itself for help with syntax.\n\n\n*** REVISION HISTORY ***\n\n\nv1.0 - 5/ 6/92 - Initial release... no known bugs...\nv1.1 - 5/23/92 - Previous version DID NOT check to see if the account was\n                 inactive - therefore it would always list old accounts\n                 active or not (at least until it was overwritten by a\n                 new user). Ooops. This bug was fixed!\n               - If a user called and did not completely log on, the\n                 user.data file will store all his info but will not\n                 update the LAST CALLED date, therefore these users would\n                 have showed up as ''... hasn''t called in 8000+ days'' (since\n                 the date variable is 0 it counts all the days since \n                 01-01-70 and echos this number). NOW these users will show\n                 up as "... has an incomplete account" (unless the NODAYS\n                 option is used).\n               - Added an option to exclude certain users via. a\n                 ''AEClean.exclude'' file. Type only 1 name per line, Currently\n                 AEClean will look in your current dir, then your BBS: dir\n                 then your S: directory for this file - if it doesn''t find\n                 it it will continue on (thinking you dont want to exclude\n                 anyone).\n               - Added a ''NONE - All users in good standing!'' output for\n                 cases where ALL users had called within the nr of days.\n               - Reduced size of code by 10%, An initial ''RaZorMaid'' release.\n\n\n*** RELEASE INFO ***\n\n\nLastly, I am running this under workbench v2.04. AND I KNOW IT WON''T WORK\nunder WB1.3. (like my MoveFiles v0.3 and SumCalls v1.1 THOSE utils are \nalso WB2.x ONLY!!! I might have forgot to mention that earlier - hehe). In\nfact, if you even try it under wb1.3 it WILL guru (I didn''t bother to check\nto see which OS you''re using!) For more info, requests, the latest warez,\netc... call my board - Snarfs Pub (407) 267-8155.......\n\nNameless\n','\n',char(10)),NULL,'auto-added',10251,5,0,NULL,NULL,'aeclea11','scan',1780048372);
INSERT INTO door_catalog VALUES('aeclea14','AECLEA14.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AECLEA14.LHA','AEClean','XIM','AEClean','1.4',NULL,NULL,NULL,replace('AEClean v1.4  WB2.0 ONLY!\n','\n',char(10)),'AEClean.doc',replace('                    _____ ______________________________\n                    \\   \\\_____//\__/\\_\\ __ //\____/\n---------/\---------// /\ // /_/ \\ \  // // __// /_/---------/\-------------\n---------\/--------// /_/// /_____\\ \// //  \// /___---------\/-------------\n                   \\/___\\____//___\//_//_/\_\\____/                Nameless\n\n \n                  - -- ---=*)> PRESENTS: <(*=--- -- -\n \n                   *** AEClean v1.4  WB2.0 ONLY! ***\n\n       AmiExpress Utility to help U ''cleanup'' inactive accounts\n\n\nThis little utility will allow you to list all your inactive accounts\nquickly.  If you also select the WARNing and MESSage switches it''ll create\na neatly formatted stdio output which you can redirect to a file and then\npost on your board to alert the ones who are calling that their friends\nmay be loosing their accounts. You can even add it to your logoff script\nto constantly alert users (when they logon that people are about to loose\ntheir accounts because of inactivity).\n\nI originally wrote this program with lots of features to even tell you\nwhat users weren''t uploading... but to do that I also had to read in\nthe BBS:Nodex/Callerslog file and I DIDN''T want to keep a long one of\nthose on my board (well maybe 1 months worth)! so I made this version\nto strictly READ (No writing involved!) your BBS:User.Data file and\nfigure out all the information...\n\nI should mention, this program does NOT delete those accounts, it only\nTELLS YOU that certain users havn''t called in X nr of days. YOU have to\ndelete them when you feel that they'' probably wont ever call back or\nwhatever...\n\nAdditonal feature of v1.1 and up.  If you have an ''AEClean.exclude'' text\nfile with user names of those you wish exclude them from the list, it\nwill, else it wont exclude anyone! Note: this file should be located in\nyour current dir, OR your BBS: directory OR your S: directory. It will\nsearch for the file in that order. Lastly, this new feature renders this\nutility FOR USE WITH WB2.0 ONLY (don''t even try it under 1.3 hehe).\n\n\n                           /========\\n                           ) SYNTAX (\n                           \========/\n\n\nSyntax is as follows:\n\n   AEClean <days> [WARN] [MESS] [NOANSI] [NONRS] [NODAYS] [CLS] [DEL=x]\n\nWhere:\n\n<days> is a MANDATORY number which represents the number of days back in\n       time to find out who hasn''t called. Without the nr you just get help.\n\n            -< OPTIONAL SWITCHES ON/OFF >-\n\n[CLS]    turns ON the issuing of a screen clear at start of output\n[WARN]   turns ON the warning borders\n[NONRS]  turns OFF the numbers before the users names\n[NOANSI] turns OFF ANSI colors for warning & message\n[NODAYS] turns OFF the printing of UserX ''hasnt called in X days'' text\n[MESS]   turns ON a text message for easy AE message creation\n\n[DEL=x]  Changes default message to indicate you''ll delete user after x days\n         instead of the <days>/2 normally printed (only when MESS swich is on)\n\nNote: The MESSage switch will print a message which will warn the users\n      that you''ll delete them after 1/2 the value of days passes. I did\n      this cause I wanted it that way for my board! I issue a 60 day\n      warning and then delete them after 90 days!\n\nTo redirect output to file use ''>''. Ie.. AEClean >ram:test 30 WARN MESS\n\n\n                         /============\\n                         ) SAMPLE USE (\n                         \============/\n\n\nAt any Shell/Cli type:  AEClean 60 WARN MESS\n\nWill probably give you an output that looks something like this...\n\n +--------------------------------------------------------------------+ \n       WARNING     WARNING     WARNING     WARNING     WARNING \n +--------------------------------------------------------------------+ \n   The following users have failed to call the BBS in over 60\n   days and will be deleted from the board after another 30 days\n   of inactivity. Please mention it to them if you know them.\n\n       (1) Blue hasn''t called in 79 days\n       (2) John hasn''t called in 73 days\n       (3) Snake hasn''t called in 72 days\n       (4) Phantom hasn''t called in 60 days\n +--------------------------------------------------------------------+ \n       WARNING     WARNING     WARNING     WARNING     WARNING \n +--------------------------------------------------------------------+ \n\nNOTICE!!! Version 1.4 and up now sorts output by showing WORST CALLERS\nFIRST... thanx to the guy who suggested this, I forgot you''re handle\nit''s been so long since ya called my board ... hehehe....\n\nTo get the names without anything else, you can enter the following:\n\n  AEClean 60 NONRS NODAYS\n\nand your output for the above data should look something like this:\n\n       Blue\n       John\n       Snake\n       Phantom\n\nOf course, you can always type: ''AEClean'' by itself for help with syntax.\n\n\n                /==================================\\n                ) SAMPLE USE (AS A LOGON BULLETIN) (\n                \==================================/\n\nInsert this line in your logoff script...\n\n  AEClean >BBS:Bull.txt 60 WARN MESS CLS\n\n\n\n                        /==================\\n                        ) REVISION HISTORY (\n                        \==================/\n\n    v1.0 => 06-May-92 - INITIAL RELEASE\n\n    v1.1 => 23-May-92\n          - Previous version DID NOT check to see if the account was inactive,\n            therefore it would always list old accounts active or not (at\n            least until it was overwritten by a new user). Ooops. Bug fixed!\n          - If a user called and did not completely log on, the user.data file\n            will store all his info but will not update the LAST CALLED date,\n            therefore these users would have showed up as ''... hasn''t called\n            in 8000+ days'' (since the date variable is 0 it counts all the days\n            since 01-01-70 and echos this number). NOW these users will show\n            up as "... has an incomplete account" (unless the NODAYS option is\n            used).\n          - Added an option to exclude certain users via. a ''AEClean.exclude''\n            file. Type only 1 name per line, Currently AEClean will look in\n            your current dir, then your BBS: dir then your S: directory for\n            this file - if it doesn''t find it it will continue on (thinking\n            you dont want to exclude anyone).\n          - Added a ''NONE - All users in good standing!'' output for cases\n            where ALL users had called within the nr of days. \n          - Reduced size of code by 10%.\n\n    v1.2 => 04-Jul-92\n          - Added the CLS option to allow faster operation when used as a\n            bulletin [cause it clears screen first and doesn''t have to resort\n            to scrolling the display...]\n\n    v1.3 => 02-Aug-92\n          - Had some illegal memory accesses'' DAMN - thanx to the enforcer,\n            I managed to eliminate ''em all...\n          - Minor touchups: added version string, changed group name (again),\n            disabled ctrl-c handling, reformated source code...\n\n    v1.4 => 10-Nov-92\n          - Recompiled with SAS-C v6.0\n          - Now sorts the output by the WORST to BEST callers (ie.. The guy\n            who hasn''t called in 100 days would be shown first, 99 next etc..\n          - Added DEL=x (note: no spaces) to override default message and\n            indicate you''ll delete user after x number of days instead...\n          - Fixed date algorithm to prevent huge numbers if you got a user who\n            might be calling from far into the future (hehe) Thanx ''Saxon of\n            Shining 8'' for pointing that out to me... The problem was I was\n            using the user with the most recent date in the user.data file\n            as todays date instead of calculating it from the system date...\n\n               \n                        /==============\\n                        ) RELEASE INFO (\n                        \==============/\n\nLastly, I am running this under workbench v2.1  AND I KNOW IT WON''T WORK\nunder WB1.3. For more info, requests, the latest warez, etc... call my\nboard - Snarfs Pub (407) 267-8155.......\n\nLater, Nameless\n\nGreetz to my new DeSiRe friends!!: SEE NAMELESS.GREETZ FILE for members list\n','\n',char(10)),NULL,'auto-added',11058,4,0,NULL,NULL,'aeclea14','scan',1780048372);
INSERT INTO door_catalog VALUES('aeclean1','AECLEAN1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AECLEAN1.LHA','AEClean','XIM','AEClean',NULL,NULL,NULL,NULL,replace('AEClean *** AmiExpress Utility\n','\n',char(10)),'AEClean.doc',replace('*** AEClean *** AmiExpress Utility to help U ''cleanup'' inactive accounts\n\nThis little utility will allow you to list all your inactive accounts\nquickly.  If you also select the WARNing and MESSage switches it''ll create\na neatly formatted stdio output which you can redirect to a file and then\npost on your board to alert the ones who are calling that their friends\nmay be loosing their accounts.\n\nI originally wrote this program with lots of features to even tell you\nwhat users weren''t uploading... but to do that I also had to read in\nthe BBS:Nodex/Callerslog file and I DIDN''T want to keep a long one of\nthose on my board (well maybe 1 months worth)! so I made this version\nto strictly READ (No writing involved!) your BBS:User.Data file and\nfigure out all the information...\n\n\n*** SYNTAX ***\n\n\nSyntax is as follows:\n\n   AEClean <days> [WARN] [MESS] [NOANSI] [NONRS] [NODAYS]\n\nWhere:\n\n<days> is a MANDATORY number which represents the number of days back in\n       time to find out who hasn''t called. Without the nr you just get help.\n\n            -< OPTIONAL SWITCHES ON/OFF >-\n\n[WARN]   turns ON the warning borders\n[NONRS]  turns OFF the numbers before the users names\n[NOANSI] turns OFF ANSI colors for warning & message\n[NODAYS] turns OFF the printing of UserX ''hasnt called in X days'' text\n[MESS]   turns ON a text message for easy AE message creation\n\nNote: The MESSage switch will print a message which will warn the users\n      that you''ll delete them after 1/2 the value of days passes. I did\n      this cause I wanted it that way for my board! I issue a 60 day\n      warning and then delete them after 90 days!\n\nTo redirect output to file use ''>''. Ie.. AEClean >ram:test 30 WARN MESS\n\n\n*** SAMPLE USE ***\n\n\nAt any Shell/Cli type:  AEClean 60 WARN MESS\n\nWill probably give you an output that looks something like this...\n\n +--------------------------------------------------------------------+ \n       WARNING     WARNING     WARNING     WARNING     WARNING \n +--------------------------------------------------------------------+ \n   The following users have failed to call the BBS in over 60\n   days and will be deleted from the board after another 30 days\n   of inactivity. Please mention it to them if you know them.\n\n       (1) Blue hasn''t called in 79 days\n       (2) John hasn''t called in 71 days\n       (3) Snake hasn''t called in 62 days\n       (4) Phantom hasn''t called in 70 days\n +--------------------------------------------------------------------+ \n       WARNING     WARNING     WARNING     WARNING     WARNING \n +--------------------------------------------------------------------+ \n\nTo get the names without anything else, you can enter the following:\n\n  AEClean 60 NONRS NODAYS\n\nand your output for the above data should look something like this:\n\n       Blue\n       John\n       Snake\n       Phantom\n\nOf course, you can always type: ''AEClean'' by itself for help with syntax.\n\n\n*** REVISION HISTORY ***\n\n\nv1.0 - 5/ 6/92 - Initial release... no known bugs...\n\n\n\n*** UPCOMMING IDEAS FOR IMPROVEMENT ***\n\n\no  I might select to read a file of names which will be ''EXCLUDED''\n   In case there are some known users who are on vacation, top ul, close\n   friends, sick... and could''t call. Wouldn''t want them to loose their\n   upload credits.\no  I''d like to modify it to automagically run every X nr of days, post\n   the message then after X/2 more days clean ''em up if they''re still\n   ''noshows''. but, I dont know..\n\n\n*** RELEASE INFO ***\n\n\nLastly, I am running this under workbench v2.04 (I''ve tested it pretty \nthoroughly with AmiExpress 1.1w), And I am releasing this program to the\nworld as FREEWARE - thats right, if you like it spread it around (Of\ncourse if you want to encourage me you''re more than welcome to send me\na few bucks). Oh yea, also ...\n\nplease call my board - Snarfs Pub (407) 267-8155.......\n','\n',char(10)),NULL,'auto-added',10687,6,0,NULL,NULL,'aeclean1','scan',1780048372);
INSERT INTO door_catalog VALUES('aeclean3','AECLEAN3.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AECLEAN3.LHA','AEClean','XIM','AEClean',NULL,NULL,NULL,'\\   \\\_____//\__/\\_\\ __ //\____/ // /\ // /_/ \\ \  // // __// /_/ // /_/// /_____\\ \// //  \// /___',replace(' _____ ______________________________\n \\   \\\_____//\__/\\_\\ __ //\____/\n // /\ // /_/ \\ \  // // __// /_/\n// /_/// /_____\\ \// //  \// /___\n\\/___\\____//___\//_//_/\_\\____/\n- -- ---=*)> PRESENTS: <(*=--- -- -\n *** AEClean v1.3  WB2.0 ONLY! ***\n','\n',char(10)),'AEClean.doc',replace('                    _____ ______________________________\n                    \\   \\\_____//\__/\\_\\ __ //\____/\n---------/\---------// /\ // /_/ \\ \  // // __// /_/---------/\-------------\n---------\/--------// /_/// /_____\\ \// //  \// /___---------\/-------------\n                   \\/___\\____//___\//_//_/\_\\____/                Nameless\n\n \n                  - -- ---=*)> PRESENTS: <(*=--- -- -\n \n                   *** AEClean v1.3  WB2.0 ONLY! ***\n\n       AmiExpress Utility to help U ''cleanup'' inactive accounts\n\n\nThis little utility will allow you to list all your inactive accounts\nquickly.  If you also select the WARNing and MESSage switches it''ll create\na neatly formatted stdio output which you can redirect to a file and then\npost on your board to alert the ones who are calling that their friends\nmay be loosing their accounts. You can even add it to your logoff script\nto constantly alert users (when they logon that people are about to loose\ntheir accounts because of inactivity).\n\nI originally wrote this program with lots of features to even tell you\nwhat users weren''t uploading... but to do that I also had to read in\nthe BBS:Nodex/Callerslog file and I DIDN''T want to keep a long one of\nthose on my board (well maybe 1 months worth)! so I made this version\nto strictly READ (No writing involved!) your BBS:User.Data file and\nfigure out all the information...\n\nI should mention, this program does NOT delete those accounts, it only\nTELLS YOU that certain users havn''t called in X nr of days. YOU have to\ndelete them when you feel that they'' probably wont ever call back or\nwhatever...\n\nAdditonal feature of v1.1 and up.  If you have an ''AEClean.exclude'' text\nfile with user names of those you wish exclude them from the list, it\nwill, else it wont exclude anyone! Note: this file should be located in\nyour current dir, OR your BBS: directory OR your S: directory. It will\nsearch for the file in that order. Lastly, this new feature renders this\nutility FOR USE WITH WB2.0 ONLY (don''t even try it under 1.3 hehe).\n\n\n                           /========\\n                           ) SYNTAX (\n                           \========/\n\n\nSyntax is as follows:\n\n   AEClean <days> [WARN] [MESS] [NOANSI] [NONRS] [NODAYS]\n\nWhere:\n\n<days> is a MANDATORY number which represents the number of days back in\n       time to find out who hasn''t called. Without the nr you just get help.\n\n            -< OPTIONAL SWITCHES ON/OFF >-\n\n[WARN]   turns ON the warning borders\n[NONRS]  turns OFF the numbers before the users names\n[NOANSI] turns OFF ANSI colors for warning & message\n[NODAYS] turns OFF the printing of UserX ''hasnt called in X days'' text\n[MESS]   turns ON a text message for easy AE message creation\n\nNote: The MESSage switch will print a message which will warn the users\n      that you''ll delete them after 1/2 the value of days passes. I did\n      this cause I wanted it that way for my board! I issue a 60 day\n      warning and then delete them after 90 days!\n\nTo redirect output to file use ''>''. Ie.. AEClean >ram:test 30 WARN MESS\n\n\n                         /============\\n                         ) SAMPLE USE (\n                         \============/\n\n\nAt any Shell/Cli type:  AEClean 60 WARN MESS\n\nWill probably give you an output that looks something like this...\n\n +--------------------------------------------------------------------+ \n       WARNING     WARNING     WARNING     WARNING     WARNING \n +--------------------------------------------------------------------+ \n   The following users have failed to call the BBS in over 60\n   days and will be deleted from the board after another 30 days\n   of inactivity. Please mention it to them if you know them.\n\n       (1) Blue hasn''t called in 79 days\n       (2) John hasn''t called in 71 days\n       (3) Snake hasn''t called in 62 days\n       (4) Phantom hasn''t called in 70 days\n +--------------------------------------------------------------------+ \n       WARNING     WARNING     WARNING     WARNING     WARNING \n +--------------------------------------------------------------------+ \n\nTo get the names without anything else, you can enter the following:\n\n  AEClean 60 NONRS NODAYS\n\nand your output for the above data should look something like this:\n\n       Blue\n       John\n       Snake\n       Phantom\n\nOf course, you can always type: ''AEClean'' by itself for help with syntax.\n\n\n                /==================================\\n                ) SAMPLE USE (AS A LOGON BULLETIN) (\n                \==================================/\n\nInsert this line in your logoff script...\n\n  AEClean >BBS:Bull.txt 60 WARN MESS CLS\n\n\n\n                        /==================\\n                        ) REVISION HISTORY (\n                        \==================/\n\n    v1.0 => 06-May-92 - INITIAL RELEASE\n\n    v1.1 => 23-May-92\n          - Previous version DID NOT check to see if the account was inactive,\n            therefore it would always list old accounts active or not (at\n            least until it was overwritten by a new user). Ooops. Bug fixed!\n          - If a user called and did not completely log on, the user.data file\n            will store all his info but will not update the LAST CALLED date,\n            therefore these users would have showed up as ''... hasn''t called\n            in 8000+ days'' (since the date variable is 0 it counts all the days\n            since 01-01-70 and echos this number). NOW these users will show\n            up as "... has an incomplete account" (unless the NODAYS option is\n            used).\n          - Added an option to exclude certain users via. a ''AEClean.exclude''\n            file. Type only 1 name per line, Currently AEClean will look in\n            your current dir, then your BBS: dir then your S: directory for\n            this file - if it doesn''t find it it will continue on (thinking\n            you dont want to exclude anyone).\n          - Added a ''NONE - All users in good standing!'' output for cases\n            where ALL users had called within the nr of days. \n          - Reduced size of code by 10%.\n\n    v1.2 => 04-Jul-92\n          - Added the CLS option to allow faster operation when used as a\n            bulletin [cause it clears screen first and doesn''t have to resort\n            to scrolling the display...]\n\n    v1.3 => 02-Aug-92\n          - Had some illegal memory accesses'' DAMN - thanx to the enforcer,\n            I managed to eliminate ''em all...\n          - Minor touchups: added version string, changed group name (again),\n            disabled ctrl-c handling, reformated source code...\n\n               \n                        /==============\\n                        ) RELEASE INFO (\n                        \==============/\n\nLastly, I am running this under workbench v2.04. AND I KNOW IT WON''T WORK\nunder WB1.3. (like my MoveFiles v0.3 and SumCalls v1.1 THOSE utils are \nalso WB2.x ONLY!!! I might have forgot to mention that earlier - hehe). In\nfact, if you even try it under wb1.3 it WILL guru (I didn''t bother to check\nto see which OS you''re using!) For more info, requests, the latest warez,\netc... call my board - Snarfs Pub (407) 267-8155.......\n\nLater, Nameless\n\nGreetz to my new DeSiRe friends!!: SEE NAMELESS.GREETZ FILE for members list\n','\n',char(10)),NULL,'auto-added',64356,20,0,NULL,NULL,'aeclean3','scan',1780048372);
INSERT INTO door_catalog VALUES('aecon2','AECON2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AECON2.LHA',NULL,'XIM','AmiExpress user.data / Tempest Accounts.data',NULL,NULL,NULL,'Converter (#2) - Bug Fix, first release did not create accounts.inx and accounts.csum files.',replace('AmiExpress user.data / Tempest Accounts.data\nConverter (#2)\n- Bug Fix, first release did not create\n  accounts.inx and accounts.csum files.\n','\n',char(10)),'V.TXT',replace('INSERT INTO door_catalog VALUES('aecrypt','AECRYPT.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AECRYPT.LHA','AECrypt','XIM','AECrypt',NULL,NULL,NULL,NULL,replace('AECrypt version 1.1\n','\n',char(10)),'CHANGES.TXT',replace('         ******* WARNING *******\n\n         BE SURE TO BACKUP YOUR CURRENT VERSION OF EXPRESS AND YOUR USER.DATA\n         AND USER.KEYS PRIOR TO IMPLEMENTING VERSION 3.7 OF AMIEXPRESS. THESE\n         VERSIONS ARE NOT BACKWARDS COMPATIBLE.\n\n         ***********************\n\nVersion 3.7 consists of the following changes:\n\n   1. Passwords are removed from the User.Data.\n\n      a. Be sure to process the ''AECrypt'' utility prior to\n         installing the new 3.7 AmiExpress. ie:\n\n         AECrypt BBS:User.Data\n\n         This will create a backup of the User.Data prior to\n         changing any data into a file called:\n\n         BBS:User.Data.old (varies depending on the filename specified in)\n                           (AECrypt parameters                           )\n\n         Once the conversion is complete, any utilities or doors that\n         modify or change the user.data may be obsolete, especially\n         any OLD msgbase utilities that where in existance prior to\n         v3.0 which updated the user''s msgbase pointers.\n\n         Also any external account editors may become obsolete. The new\n         AmiExpress does not allow the sysop to see the user''s password.\n         Therefore any account editors that allow you to change a user''s\n         password or allows the creation of an account will more than\n         likely be obsolete.\n\n   2. No longer will mistyped passwords be recorded in the Callerslogs.\n\n   3. We have reformated the way bytes and file numbers are displayed in\n      the download and upload routines by including comma formatting.\n      So far everything appears to be ok with this cosmetic change. If\n      this method of displaying numbers is accepted then we will more than\n      likely apply it to the rest of the program.\n\n   4. We are behind on the release of the Conference Accounting account\n      editor due to some 3rd party developement coordination problems.\n      Please look forward to the official Conference accounting account\n      editor on 1 Sep 93.\n\n   5. Considerations:\n\n        After long talks with ''The OutLaw'', Paul Day, and ''Planet Master''\n      we maybe implementing an external method of recording user''s passwords\n      in which the sysop would utilitize as a reference file only. We will\n      wait on some feedback from the Sysops on this before any further\n      changes are implemented.\n\n------Upcoming*\n   6. Special emphasis this month will be on the credit and time accounting\n      systems within AmiExpress. I am hearing a lot of news concerning\n      problems in this area. Anyone wishing to go into detail concerning\n      this subject please document your situation and upload it to the\n      support BBS.\n\n============================================================================\nFOR THE RECORD:\n\n    Some were a little disquieted about versions of 3.7 being released\nprematurely. I would like to announce that this should not be a concern\nto anyone when faced with the facts. I have had 3 sysops directly involved\nwith a beta version of AmiExpress since the 3.6 release.\n\n  1. > Planet Master     v3.7\n  2. > Freddy Krueger    v3.6+\n  3. > DangerMouse       v3.6+\n\n    If anyone other than these 3 were running versions higher than 3.6 please\nconsider them fakes. Also if any of the above listed where running higher\nversions than indicated here, then they were running fakes. We had a limited\nnumber of testers involved with the 3.6+ - 3.7 primarily because of the\nSecurity changes involved and also because of the backward incompatibility.\n\n    Also, all matters regarding AmiExpress should be directed towards the\nOutLaw in lue of myself unless it is a direct developement issue. I am\nstrictly a developer of AmiExpress.\n\n----------------------------------------------------------------------------\n','\n',char(10)),NULL,'auto-added',10265,5,0,NULL,NULL,'aecrypt','scan',1780048372);
INSERT INTO door_catalog VALUES('aed138','AED138.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AED138.LHA','AEd','XIM','AEd',NULL,NULL,NULL,NULL,replace('.......AmiX Editor...... ..  ...   ....  ...\n','\n',char(10)),'Registration.txt',replace('\n\n                       HOW TO REGISTER YOUR COPY OF AED\n                       --------------------------------\n\n1.  Choose a Support Center nearest you from the "SupportCenters.txt" file\n    included in the archive.\n\n2.  Print out or copy the "Registration.form" file included in the archive.\n\n3.  Please fill out the ENTIRE form and mail it, along with the registration\n    fee to the Support Center that you choose.\n\n4.  Note that each Support Center may require a different fee and/or\n    currency for the registration.  Please consult the "SupportCenters.txt"\n    file for more exact pricing information.\n\n','\n',char(10)),NULL,'auto-added',51039,4,0,NULL,NULL,'aed138','scan',1780048372);
INSERT INTO door_catalog VALUES('aedd101','AEDD101.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AEDD101.LHA','xim','XIM','xim',NULL,NULL,NULL,'- AX2DD to convert /X userbase for d² - AXList2DDList to convert /X flist for d² - DD2AX to convert d² userbase for /X (so',replace('Utils that make DayDream BBS kinda /X comp. \n- AX2DD to convert /X userbase for d²       \n- AXList2DDList to convert /X flist for d²  \n- DD2AX to convert d² userbase for /X (so   \n  you can use top utils etc.)               \n- DDList2AXList to convert d² filelist for  \n  /X                                        \n- XIM-Emulator. Makes possible to run /X    \n  doors on d².                              \n','\n',char(10)),'AEKit.doc',replace('\n  This archive contains four files mainly used for DayDream BBS.\n  They were not included with DayDream BBS, because it is illegal\n  to distribute these with it. The reason is that AmiExpress is registered\n  trademark and using structures without paying Hodge some money\n  would be illegal.\n\n  AX2DD\n  ~~~~~\n	With this you can convert your old Amix user.data for DayDream\n	BBS. Passwords won''t be converted, because of a genious password\n	crypting routine. \n\n  AXList2DDList\n  ~~~~~~~~~~~~~\n	Use this to convert your filelists for DayDream BBS.\n\n  DD2AX\n  ~~~~~\n	Converts userbase of DayDream BBS to Amix''s user.data format.\n	/X can''t use this, but top utilities can. So now you can use\n	all those cool /X-top utilities etc with DayDream BBS.\n\n  DDList2AXList\n  ~~~~~~~~~~~~~\n	Lousy filelist converter. Converts filelist of DayDream to \n	Amix-format. If file has delete-flag, it will be twitted,\n	because of handicapped format of /X-filelists.\n\n  All of these utilities have one stupid enforcer hit fixed. They were\n  nothing fatal, but some morons think that byte read from address 0\n  can crash the whole machine so i fixed them...\n\n------------------------------------------------------------------------\n\n  Xim V1.01 - Xim emulation for DayDream BBS\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n  \n  Whats this?\n  ~~~~~~~~~~~\n	Simple XIM (amieXpress Interface Module, i guess) emulation for\n	DayDream BBS. Should be faster than /X itself :) Most of the commands\n	are supported, but not tested, so i included the sourcecode among\n	this, so you can correct if there are bugs :)\n\n	If you know how /X tells door cursorkeys please tell it to the\n	author of DayDream BBS.\n\n  Usage:\n  ~~~~~~\n	xim [node] [door to run], eg:\n\n	c:run doors:xim %N doors:sysdl/sysdl\n\n  Advanced usage:\n  ~~~~~~~~~~~~~~~\n	Sometimes installing /X door for DayDream BBS can be a bit\n        complicated. I have managed to install at least following doors:\n\n	- FastWall by Nike.\n	- Chat-o-meter by Killraven/Mystic.\n	- KillerBaud by Killraven/Mystic.\n\n	Installing Chat-o-meter will surely cause problems for regular\n	SysOp, so here''s instructions how to install it to DayDream usage.\n\n	1) Makedir BBS:Commands/SysCmd and place those chat_start/end.infos\n	   there. Configure ''em too..\n\n	2a) If you have 50000 bytes or more stack, put to your \n	    linechaton.gfx/txt following line:\n\n            ÿDRun <>NIL: doors:xim %N doors:chat-o-meter|chat_start|\n                                               ^------name of the icon\n						      in Syscmd-directory.\n\n	    LinechatOff.GFX/TXT:\n\n	    ÿDRun <>NIL: doors:xim %N doors:chat-o-meter|chat_end|\n\n	    And you''re ready to go...\n\n        2b) If you don''t have 50000 bytes of stack (I have only 15000)\n	    then you need to do little hacking...\n\n	    LineChatOn.TXT/GFX:\n	    ÿDRun <>NIL: doors:kickchatometer %N|chat_start|\n\n	    LineChatOff.TXT/GFX:\n	    ÿDRun <>NIL: doors:kickchatometer %N|chat_end|\n\n	    doors:kickchatometer looks like this:\n\n----------------------------------------------------\n.key NODE\n.bra {\n.ket }\n\nstack 50000\ndoors:xim {NODE} doors:chat-o-meter\n-----------------------------------------------------\n\n	    Be sure it has kickchatometer has s-flag turned on..\n	    To turn it on, just "type protect doors:kickchatometer +s".\n\n	    And you''re ready to go...\n\n\n\n  Commands that are not support:\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n  Command          | Why\n  -----------------+----------------------------------------------------\n  JH_EF            | Not implemented in DD''s doorport \n  JH_CO            | Not implemented in DD''s doorport \n  DT_RATIOTYPE     | DD has different storage method for these\n  DT_COMPTYPE      | DD has different storage method for these\n  DT_TIMEUSED      | Not implemented in DD\n  DT_DAILYBYTELIMIT| Not implemented in DD\n  DT_DAILYBYTEDLD  | Not implemented in DD\n  DT_EXPERT        | My lazyness, useless command :)\n  ACTIVE_NODES     | Too hodgey format and DD hasn''t 9 node limit :)\n  DT_DUMP          | /X has different format in userbase\n  DT_TIMEOUT       | Not implemented in DD\n  BB_LOCAL         | Not implemented in DD\n  BB_STATUS        | Useless\n  SCREEN_ADDRESS   | Useless\n  BB_TASKPRI       | Useless for Doors.\n  RAWSCREEN_ADDRESS| Useless\n  BB_CHATFLAG      | Not implemented in DD\n  DT_STAMP_LASTON  | Lazyness\n  DT_CONFACCESS    | DD has different storage method for these\n  BB_CALLERSLOG    | Not implemented in DD''s doorport\n  BB_UDLOG         | Not implemented in DD''s doorport\n  BB_CHATSET       | Not implemented in DD''s doorport\n  ENVSTAT          | ENV: suxx, ARexx WHO-doors suck!\n  JH_MCI           | DD has faster method than MCI :)\n  BB_GETTASK       | Bullshit\n  BB_LOGONTYPE     | So you run doors in waiting for call-state?-)\n  BB_SCRLEFT       | Crap\n  BB_SCRTOP        | Crap\n  BB_SCRWIDTH      | Crap\n  BB_SCRHEIGHT     | Crap\n  BB_PURGELIN      | Crap\n  BB_PURGELINESTART| Crap\n  BB_PURGELINEEND  | Crap\n  BB_NONSTOPTEXT   | Crap\n  BB_LINECOUNT     | Crap\n  DT_LANGUAGE      | DD has different storage method for these\n  DT_QUICKFLAG     | What the hell is this crap?\n  DT_GOODFILE      | Crap\n\n  History\n  ~~~~~~~\n   V1.0  - Initial release\n   V1.01 - Added some commands.\n	 - Added logfile called DayDream:Logfiles/XimErrors[node].log.\n	   This contains debugging information if door sent a command\n           which wasn''t recognized. If possible, sent it to the author\n	   of DayDream BBS if there are doors that use those unknown\n	   commands.\n\n','\n',char(10)),NULL,'auto-added',10790,1,0,NULL,NULL,'dd_xim','scan',1780048372);
INSERT INTO door_catalog VALUES('aedoc4g','AEDOC4G.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AEDOC4G.LHA',NULL,'XIM','exe.-l0S-eND0S-bBS-.exe',NULL,NULL,NULL,'/\/    /  \      /    /. \   ___.  /|  | /   ___/    \/ |_/  __/_|  \ /_____/ :  | /   __/_  :   \ |       /    \   |\____  |',replace('       _____/\__________   /____________|  |\n    /\/    /  \      /    /. \   ___.  /|  |\n   /   ___/    \/ |_/  __/_|  \ /_____/ :  |\n  /   __/_  :   \ |       /    \   |\____  |\n /       /  |____\|  \   /      \  | /     |\n/_______/___|/____|___\_/________\_|/  ____|\n ::                                      ::\n :: AmiExpress V4.0 komplete german docs ::\n ::                                      ::\n  ::::::::::::::::::::::::::::::::::::::::\n','\n',char(10)),'Aedoc4.guide',replace('\n                     -------------------------------\n                     ->>>>>>>> Irie-FM BBS <<<<<<<<-\n                     -------------------------------\n                     -------------------------------\n                     -       SYSOP : Black         -\n                     -     CO-SYSOP: SABA          -\n                     -------------------------------\n                     -------------------------------\n                     - 3.5 Giga-Byte  ONLINE-STUFF -\n                     ->>>      AMIGA - PC      <<< -\n                     -------------------------------\n              ---------------------------------------------\n              - NODE 1 : 0049-0###-######   28800 V34 USR -\n              - NODE 2 : 0049-0###-######   19200 V-TERBO -\n              - NODE 4 : 0049-0###-#######  ISDN/BLASTER  -\n              - NODE 5 : 0049-0###-#######  ISDN/BLASTER  -\n              ---------------------------------------------\n              -           RUN UNDER PCBOARD 15.21         -\n              ---------------------------------------------\n\n\n\nHabt Ihr Euch auch schon über Dokumentationen einiger Programme geärgert,die in\nbestem Englisch verfasst waren? Deshalb hier die komplette Umsetzung der Anleitung\nzu dem derzeit bestem Mailboxprogrammes AmiExpress 4.0 für den Amiga.\nAlso dann viel Spass damit !!!\n\n\n                                 SABA\n\n\n\n\nSPECIAL GREATS TO :\n\n\nJUDAS - 1000 dank,dass Du Dir soviel Mühe gemacht hast das Teufelswerk\n        zu Übersetzen.\n\nMike /X Distributor\n\nSpeedlock TRSI\n\n\n\n\n\n\n\n\n@database AmiexDoc\n\nCopyright (c) 1993-94  LightSpeed Technologies Inc.\nAll Rights Reserved\n\n@Remark $VER: (August 02 1994, 01:06:01)\n@Remark AmigaGuide database for the /X Documentation\n\n@node MAIN "/X Documentation (c)1993-94 L.Speed Technologies Inc.(August 02 1994, 01:06:01)"\n           .: C O N T E N T S  O F  D O C U M E N T A T I O N :.\n\n    @{" Einleitung                   " Link Cap01}    @{" Copyright  Information       " Link Cap02}\n    @{" Anforderungen                " Link Cap03}    @{" Installation von AmiExpress  " Link Cap04}\n    @{" Wie installiert man configs  " Link Cap05}    @{" Startup configurieren        " Link Cap06}\n    @{" Tooltypes Information        " Link Cap07}    @{" Die Standard Dokumentation   " Link Cap08}\n    @{" Programlogik von AmiExpress  " Link Cap09}    @{" MainMenu Kommandos von \X    " Link Cap10}\n    @{" AmiExpress HOST Addresses    " Link Cap11}    @{" MCI imbedded ControlSequence " Link Cap12}\n    @{" besondere Eigenschaften      " Link Cap13}    @{" außerdem wichtig......       " Link Cap14}\n    @{" QWK Mail Unterstützung       " Link Cap15}    @{" Icon-Script-Sprachee         " Link Cap16}\n    @{" Probleme beheben             " Link Cap17}    @{" geplante Erweiterungen       " Link Cap18}\n\n          --------------------------------------------------------\n          Komplette Docs am Stück für AmiExpress Professional v4.0\n          --------------------------------------------------------\n  Original 3.36 Documentation written by Jens Langner (/X DocWriter).\n  Original 4.0  Documentation written by The Outlaw (Andy)\n     translated Documentation written by JUDAS (the JUDAS)\n  Copyright (c) 1993-94 LightSpeed Technologies Inc.  All Rights Reserved.\n   Any copy or illegal distribution of this Documentation is not allowed.\n\n@endnode\n@node Cap01 "Einleitung & Erklärung zu \X "\n  =======================================================================\n  Ami-Express ist ein BBS-program, das die Übertragung von Daten\n  zwischen Box und fernen Terminals ueber eine Telefonverbindung\n  ermöglicht. (Aha !!! =) Diese Daten koennen als files up/downgeloaded\n  werden.Die meisten BBS haben auch Message-Sektionen worin mails\n  geschrieben und gelesen werden koennen. Bei einigen BBS koennen auch\n  onlinespiele gespielt werden. Diese sind meist einfacher Art, koennen\n  dennoch recht amuesant sein. Wenn sie bereits User oder Betreiber von\n  \X waren, werden sie die groessten Veraenderungen von \X schnell\n  bemerken. Mit den voraussichtlich verfuegbaren Umsetzungen wird\n  \X bald ein aehnliches BBS werden, wie man es bereits auf PC und AMiga\n  finden kann.\n  =======================================================================\n\n@endnode\n@node Cap02 "Copyright information"\n  =======================================================================\n  If you own a an Illegal (Cracked copy) and you use it, then\n  consider buying the original. This will not only provide you with\n  support etc, but will encourage the further development of\n  Ami-Express.\n\n                    ------------------------------------\n                      AmiExpress, AmiX-Net, Utilities,\n                      docs, and its source code are\n            (c) Copyright 1993-94 by LightSpeed Technologies Inc.\n\n       --------------------------------------------------------------\n\n\n        AmigaGuide, AmigaGuide.info, amigaguide.library, WDisplay,\n        WDisplay.info,\n        (c) Copyright 1992 Commodore-Amiga, Inc. All Rights Reserved.\n        Reproduced and distributed under license from Commodore.\n\n       --------------------------------------------------------------\n\n\n                           HydraCom was written by\n                 Arjen G. Lentz, LENTZ SOFTWARE-DEVELOPMENT\n                COPYRIGHT (C) 1991-1993; ALL RIGHTS RESERVED\n\n                     The HYDRA protocol was designed by\n               Arjen G. Lentz, LENTZ SOFTWARE-DEVELOPMENT and\n                           Joaquim H. Homrighausen\n                COPYRIGHT (C) 1991-1993; ALL RIGHTS RESERVED\n\n\n  HYDRA PROTOCOL LICENSE\n\n  You are granted a license to implement the HYDRA file transfer\n  protocol, HYDRA hereafter, in your own programs and/or use the sample\n  source code and adapt these to your particular situation and needs;\n  subject to the following conditions:\n\n   -  You must refer to it as the HYDRA file transfer protocol, and you\n      must give credit to the authors of HYDRA in any information\n      screens or literature pertaining to your programs that contains\n      other such information (credits, your own copyrights, etc.).\n\n   -  HYDRA will always remain backwards compatible with previous\n      revisions. HYDRA allows for expansion of its features without\n      interfering with previous revisions. It is, however, important\n      that different people do not expand the protocol in different\n      directions. We therefore ask you to contact us if you have any\n      needs/ideas regarding HYDRA, so development can be synchronized\n      and beneficial to all.\n\n   -  If your implementation cannot converse with past or future\n      revisions as supplied by us, then you must refer to it as "HYDRA\n      derived", or as "a variation of HYDRA", or words to that effect.\n\n\n\n       --------------------------------------------------------------\n\n\n             AmiExpress is a commercial product, NOT shareware\n                      If you used it, please buy it!\n\n                    ------------------------------------\n\n  =======================================================================\n@endnode\n@node Cap03 "Anforderungen"\n  =======================================================================\n  Um \X zu installieren benoetigt man folgendes:\n\n    Program     Directory    Beschreibung\n    ---------   --------     -----------\n    Express     BBS/Utils    BBS-system\n    ACP         WBSTARTUP    BBS-controller\n    InitMisc    S:           generiert User.Misc\n\n  - Die Workbench sollte installiert sein fuer ACP\n  - Der Stack sollte 50000 betragen\n  - ein Amiga (500/600/1000/1200/2000/2500/3000/4000)\n  - Kickstart V2.0\n  - 2 MB freier Speicher fuer uploads\n  - Die installierten .INFO files in den directories\n\n  Aus Geschwindigkeitsgruenden sollte \X auf eine Harddisk installiert\n  werden.Es sollte ausreichend freies RAM fuer uploads verfuegbar sein.\n  Fuer Tests kann auch eine Disketteninstallation dienen\n  =======================================================================\n@endnode\n@node Cap04 "So installiert man \X auf die Harddisk"\n  =======================================================================\n  Um \X zu installieren braucht man die oben erwaehnten Voraussetzungen.\n  Hier also die Installation von \X.\n\n  Nehme eine Disk und installiere darauf das \X mit dem packer LZH,\n  sofern das \X nicht schon auf einer Disk geliefert wurde.\n  nun sollte man sich ueberlegen, wo man \X auf der Harddisk haben moechte.\n  Es wird empfolen \X komplet in ein BBS: directory zu installieren.\n  Sollte dieses nicht bereits existieren, sollte es angelegt werden.\n  Auf der \X Disk befinden sich folgende Dinge:\n\n  -------------------------\n       S (dir)\n       libs (dir)\n       Trashcan (dir)\n       BBS (dir)\n     Trashcan.info\n  -------------------------\n\n  Jetzt sollte man wissen, wieviele Conferences man im BBS haben moechte.\n  Hier die Installanweisung fuer das neue \X V4.0:\n\n  - AmiExpress kann nur gestarted werden wenn die Workbench laeuft und\n    ACP von Workbench gestarted wurde.\n  - Die installationsanweisung hat sich geaendert von V2.30 bis zu\n    V4.0. Es gibt kein ACP.STARTUP file um das BBS zu konfigurieren.\n  - Jetzt muss man die .INFO files fuer die configs anpacken.Wie das geht\n    beschreibt der naechste Abschnitt.\n  =======================================================================\n@endnode\n@node Cap05 "So installiert man die Configuration Files"\n  =======================================================================\n  Die .INFO Files kontrollieren das \X system. Das ACP.STARTUP wurde\n  abgewandelt in einzelne .INFO files in die man die configuration setzt.\n  Zunaechst muss der Workbench da sein, sonst kann \X nicht installiert\n  werden.\n\n  Weitere informationen findet sich in der section, die die einzlenen .INFO\n  files fuer \X beschreibt. Jetzt sollte man wissen, wieviele nodes man haben\n  moechte. Seit version 3.60 kann man bis zu 32 lines betreiben.\n\n  Wir schlagen vor, sie speichern \X und dessen files ins einem BBS:\n  directory.Dies macht es einfacher Probleme , die auftreten, zu beheben.\n  \X zu installieren ist ziemlich kompliziert, es sollten auch diese leute\n  aufpassen, die bereits mit frueheren versionen von \X vertraut sind.\n  Da es viele Anderungen gab, wird es keine Anleitung fuer eine schnelle\n  Installation geben.\n  =======================================================================\n@endnode\n@node Cap06 "Express im Startup installieren"\n  =======================================================================\n  Um \X perfekt zum laufen zu bringen, fuegen sie folgendes in ihre\n  user-startup oder startup-sequence im S:\n  directory:\n\n   -----cut here-----------\n\n   ASSIGN BBS: SYS:BBS\n   PATH BBS:UTILS ADD\n\n   -----cut here-----------\n\n  NOTE*\n\n  Seit version 3.38 v. AmiExpress kann man dieses resident machen.\n  Dieses beschleunigt die program-ausfuehrung und spart RAM:.\n\n  So macht man \X resident:\n\n  1. aendere alle NODESTART tooltypes in den NODE icons auf das folgende\n\n     NODESTART=express\n\n  2. Aendere die s:User-StartUp um folgenden Einschub nach den BBS-assigns\n     :\n\n     ---------cut here-----------\n\n     RESIDENT EXPRESS BBS:EXPRESS\n\n     ---------cut here-----------\n\n  Jetzt starte den ACP.SERVER. Man sollte ACP.CTRL & INFO FILE\n  in das WBSTARTUP directory auf der Harddisk kopieren.\n\n  Man kann ACP auch aus der shell starten, wenn der .INFO file im gleichen\n  directory liegt,ansonsten kann ACP die settings nicht lesen.\n\n  Der obige ASSIGN-Ausdruck besagt, dass das BBS in einem sys:bbs\n  directory auf der systemfestplate liegt.\n\n  Wenn all das erledigt ist, sollte man einen Reset ausfuehren.\n\n   ***NOTE***\n\n  Wenn man von version 3.38 updated, benoetigt man InitMisc um folgendes\n  vom CLI auszufuehren.\n\n       Initmisc BBS: BBS:user.data BBS:user.misc\n\n  Dieses generiert einen realnamen-file, der zu dem user.data file passt.\n  Dieser file ist notwendig, wenn man in conferences den realnamen haben moechte\n  oder auch in zukuenftigen Interneterweiterungen.\n\n  NOTE: Man sollte ein BBS:UTILS directory haben.Dort sollten alle von\n  ~~~~  \X benoetigten Utilities untergebracht werden.\n  =======================================================================\n@endnode\n@node Cap07 "ToolTypes in ICONS fuer AmiExpress..."\n  =======================================================================\n     Um \X zu betreiben braucht man eine Menge Icons in verschiedenen\n     directories. Diese ICONS beinhalten Informationen um \X zu betreiben.\n     Diese Informationen nennt man TOOLTYPES. Hier also eine Liste aller\n     noetigen Icons und den TOOLTYPES dafuer. Um die Config des BBS zu aendern\n     sollte man das Icon anklicken und mit dem rechten mousebutton auf\n     Icon-information gehen.Dann sieht man die TOOLTYPES um das \X persoenlich\n     zu gestalten. Fuer weitere Information sehe man nach den Beispielicons\n     auf Diskette.\n\n    @{" ACP.INFO ICON                " Link Cap0701}    @{" NODE(x).INFO ICON            " Link Cap0702}\n    @{" <CONF>.INFO ICON             " Link Cap0703}    @{" CONFCONFIG.INFO ICON         " Link Cap0704}\n    @{" DRIVES.INFO ICON             " Link Cap0705}    @{" SCREENTYPES.INFO ICON        " Link Cap0706}\n    @{" COMPUTERLIST.INFO ICON       " Link Cap0707}    @{" NAMESNOTALLOWED.INFO ICON    " Link Cap0708}\n    @{" PROTOCOLS <Directory>        " Link Cap0709}    @{" ACCESS.INFO ICON             " Link Cap0710}\n    @{" FCHECK    <Directory>        " Link Cap0711}    @{" NODE(x)   <Directory>        " Link Cap0712}\n    @{" COMMANDS  <Directory>        " Link Cap0713}    @{" STORAGE   <Directory>        " Link Cap0714}\n\n  =======================================================================\n@endnode\n@node Cap0701 "DH0:WBSTARTUP/ACP.INFO ICON ToolTypes information"\n  =======================================================================\n  ACP.INFO           - Dieses Icon hat Parameter für ACP und andere noetige\n  ~~~~~~~~             BBS daten.Es gitb auch an, wo sich weitere Parameter\n                       files befinden.\n  ACPFONT=           - Sagt ACP, welchen font man wuenscht.\n                       IE: ACPFONT=cleanibm.font\n  BACKUP.<numb>=     - sagt ACP ein backup backup eines speziellen files zu machen\n                       Die letzen 5 backups werden gemerkt.<numb> ist die Zahl\n                       wie oft dieser Tooltype auftritt.\n  BBS_NAME= <name>   - Gibt den namen deines BBS an.\n  BBS_STACK= <stack> - Gibt den Stack des systems an.\n  BBS_LOCATION= <dir>- Beschreibt die Pfade der Haupt-BBS-files.\n                       Dieses directory ist das DIR, wo sich die\n                       Node(x) directories befinden sollten, zusammen mit\n                       den .DEF files.\n                       Wenn der pfad ein directory ist, muss der pfadname\n                       mit einem ''/'' enden, wenn man den pfad im tooltype\n                       einstellen will.\n  BUTTON_NAME.<numb>=- definiert dden namen eines speziellen buttons.\n                       <numb> kann von 1-15 gehen.\n  BUTTON_COMMAND.<numb>\n                     - definiert das commando, das ausgefuehrt wird, wenn\n                       dieser Knopf gewaehlt wird. <numb> zwischen 1-15.\n  BBS_GEOGRAPHIC=<geo> Gibt die geografische Lage des BBS am.Dieses wird\n                       in der Logon-sequence erwaehnt.\n  CREDIT_BY_KBYTES   - Ermoeglich dem sysop die credits (files)in kBytes zu sehen,\n                       anstelle von Bytes.\n  ICONFIED           - ACP started ICONFIED oder nicht.\n  ICONIFY.LEFTEDGE=  - Anzahl der Pixel fuer die linke ecke des iconified Icons\n                       auf dem screen.\n  ICONIFY.TOPEDGE=   - wie oben, nur diesmal die Pixel der oberen Kante des\n                       iconified Icons.\n  LONG_WHO           - Dieser tooltype macht einen Absatz zwischen den einzelnen\n                       nodes, wenn das WHO kommando verwendet wird.\n  MULTICOM_PORT      - Wenn dieser Tooltype im MULTICOM PORT von \X\n                       plaziert wird, ist \X bereit fuer multinode-systeme.\n  NEW_ACCOUNTS=APPEND- ACP addiert nun neue User am Ende des Datenfiles\n                       hinzu.\n  NODE<x>_LOCATION=  - Gibt den Pfad einer bestimmten node an.\n  NODEx_NAME=<string>- der name einer node kann hier angegeben werden.\n                       Standart ist ist der gleiche name wie BBS_NAME\n  NODEx_SYSOP=<string> Ermoeglicht verschiedene SYSOPS pro node. Dies hat Einfluss\n                       auf "comment an Sysop" und "sysop rufen"..\n                       Standart ist BBS_SYSOP.\n  NODES=1            - sagt ACP wie viele nodes man betreibt\n  NUTTON_NAME.<numb>=- gibt den namen eines speziellen nuttons an.\n                       (anm: nutton=node button) <numb> von 1-15.\n  NUTTON_COMMAND.<numb>\n                     - definiert das command, das bei diesem nutton\n                       ausgefuehrt wird. <numb> von 1-15.\n                       Alle NUTTONS bekommen die NODEnummer als\n                       kommandozeilenargument geliefert..\n  PRIORITY= <numb>   - gibt die taskpriority für ACP an.\n  RESTRICT.<numb>=   - ACP soll eine filenote an den angegebenen file haengen.\n                       Dieses verwehrt es usern diesen file zu sehen oder\n                       downzuloaden.\n  SHORT_DONOTMOVE    - Mit diesem tooltype aktiv, bewegt sich das ACP window\n                       nicht, wenn das "\X" gadget aktiviert wird.\n  SYSOP_NAME= <name> - gibt deinen namen an.\n\n  =======================================================================\n@endnode\n@node Cap0702 "BBS:Node(x).INFO ICONS ToolTypes information"\n  =======================================================================\n  NODE(x).INFO       - Dieses icon enthaelt infos ueber die installation\n  ~~~~~~~~~~~~         einer node in \X. (x) = Nodenumber\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  CALLERS_LOG        - sagt /X alle Ereignisse in einen CallersLog-file\n                       im node directory zu schreiben.\n  CAPITOL_FILES      - sagt /X die namen upgeloadeter files in UPPER_CASE\n                       zu schreiben.(Grossbuchstaben)\n  CHAT_ON            - sagt /X dass das CHAT FLAG dieser node auf ON steht,\n                       wenn sie gestarted wird.\n  COPYBUFFER= <numb> - Gibt den maximalen Speicher an, den \X verwenden darf,\n                       wenn von einer partition in eine andere files kopiert\n                       werden.\n                       Wenn man nichts angibt, versucht \X so viel Speicher\n                       anzufordern, um den file in einem Zug zu kopiern.\n                       Wenn nicht genug Speicher da ist, geht \X in 8Kblock-Schritten\n                       herunter, bis es moeglich ist, zu kopieren, unabhaengig\n                       vom angegebenen COPYBUFFER.\n\n                       ie: COPYBUFFER=100000\n\n                                        ^---------100K copy buffer\n  CONF_DB=<string>   - gibt den filenamen (nicht pfad) an, der verwendet wird,\n                       wenn msgbase pointers (Zeiger) einer bestimmten node\n                       geladen werden. Standart ist CONF.DB\n  DEBUG_LOG          - Schalted das DEBUGGING Log für \X ein.\n  DEF_SCREENS        - DEF_SCREENS sagt AmiExpress nicht SicherheitsScreens\n                       zu verwenden, bevor es nach sicheren sucht. ie:\n\n\n                               BULL30.TXT\n                               BULL.TXT\n\n                       Im obigen Fall started \X die Suche nach screens mit BULL.TXT.\n                       Dies kann eine betraechtliche Zeitersparnis sein, wenn die\n                       Mehrzahl deiner Screens nicht gesichert sind.\n                       Nach diesem Schema waere BULL0.TXT eine gueltige\n                       SciherheitsZuweisung. \X sucht nach gesicherten texten in\n                       5-er Schritten, ausgehen vom Passwort der Users.Wenn ein\n                       User einen Level von 255hat und es nur einen BULL30.TXT\n                       gibt, muss \X auf die Existenz von 88screens testen,\n                       bevor es bei BULL30.TXT landet.Standartmaessig tut \X\n                       dieses.Ich will nur sagen, dass wenn man keinen sicherheits-\n                       relevanten Text hat, oder nur wenige davon, so empfehle\n                       Ich DEF_SCREENS zu benuetzen.\n\n\n\n                       NOTE: Wenn man DEF_SCREENS benuetzt, aber man hat\n                       sicherheits menues zum anzeigen,macht man anstelle von\n                       :\n\n                               BULL30.TXT\n                               BULL.TXT\n\n                               besser:\n\n                               BULL30.TXT\n                               BULL0.TXT\n\n                       oder verwende einfach keinen BULL.TXT fuer dieses Brett.\n  DISABLE_QUICK_LOGONS\n                     - Verbietet  einem User das ueberspringen der\n                       logon/off texte im BBS.\n  DOOR_LOG           - sagt /X die Anfangs und Endzeit der benuetzung\n                       eines Modules.\n  EXPFONT=           - sagt Express welchen font man will..\n                       IE: EXPFONT=cleanibm.font\n  FILESNOTALLOWED=<pathname>\n                     - <pathname> ist voller pfad und filenamen eines ASCII\n                       files, der filenamen enthaelt,von files die man nicht\n                       upgeloadet bekommen moechte.\n  FREE_RESUMING      - \X erlaubt FREE RESUMING (weiter uploaden)\n                       upgeloadeter files fuer alle User des BBS\n  HDTRANSBUFFER= <buffers>\n                     - HDTRANSBUFFER aendert die BUffergroesse von serial\n                       zu Harddisk. Diese Option ist eine bessere Alternative\n                       als RAMPEN, das es an einem file auf filebasis arbeited,\n                       RAMPEN warted hingegegen, bis der alle uploads beeendet sind.\n\n                       Man kann beliebig viele buffer angeben. Der Standartwert ist\n                       8, wenn der tooltype nicht angegeben ist.Hier noch eine Formel\n                       wieviel Speicher verwendet wird,wenn uebertragung mit\n                       dieser node betrieben wird.\n\n\n                          ((buffers+2)*1024)*2\n                                             ^--- Wird 2* benoetigt, wegen\n                                                   double buffering.\n                       ie:\n\n                       HDTRANSBUFFER=20 wuerde 45,056 bytes erfordern.\n\n                       1. ((20+2)*1024)*2\n                       2. (22*1024)*2\n                       3. (22528)*2\n                       4. 45056\n  IDLENODE           - sagt ACP diese node nicht zu starten, auf click warten\n  KEEP_UPLOAD_CREDIT= <numb>\n                     - gibt an, ob ein uploadender User gleichgestellt einem\n                       der downloaded ist.\n                       darf entweder ''0'' oder ''1'' sein.\n                       das heisst:\n\n                       ''0'' = Man zieht einem uploader keine Zeit des uploads ab.\n\n                       ''1'' = Man zeiht Ihm nichts ab und gibt Ihm zusaetzlich\n                             weitere 50% Zeit zur online-Zeit hinzu.\n\n  MAX_MSG_QUE        - gibt die maximale Anzahl von messages (olm/chat) an,\n                       die an dieser node gebuffert werden.\n                       Alles was nach dem Maximum geschickt wird, wird ignoriert.\n                       Der Standartwert bei fehlen des tooltypes ist 5.\n                       .\n  NAME_PROMPT=       - Gibt den promt fuer die logon-sequence vor.\n\n  NEWUSER_PASSWORD=  - sagt ACP dass ein neuer user dieses passwort eingeben muss,\n                       bevor er als neuer user dabei sein kann.\n  NODESTART=         - sagt ACP wo Express liegt, um diese node zu starten.\n\n  NO_TIMEOUT         - sagt /X die keyboard TIMEOUT option abzuschalten.\n  NO_MCI_MSG         - sagt /X die Faehigkeit,MCI commands in der message base\n                       zu verwenden abzuschalten.\n  NO_WILDCARD_EXPANSION\n                     - Damit erlaubt \X nicht mehr die verwendung von *\n                       als WILDCARD in der speziellen node.\n  PRIORITY= <numb>   - sagt ACP die priority dieser node im Vergleich zum\n                       system.\n  PHONECHECK         - Mit diesem tooltype aktiv fragt \X bei jedem logon\n                       nach den letzen 4 Ziffern der telefonnummer des users.\n\n  PLAYPEN= <dir>     - sagt ACP dass diese node ein sysop-directory fuer\n                       uploads besitzt.\n                       !! Keinesfalls RAM: dafuer verwenden .. !!\n                       Man muss dieses directory anlegen, wenn man`s verwendet.\n  QUIETNODE          - sagt ACP diese node Schweigen zu lassen, gegenueber\n                       dem WHO command und einigen anderen modulen.\n  RAMWORK            - sagt, die node soll nicht auf FREE SPACE testen\n                       wenn z.B man RAM: verwendet fuer Playpen.\n  RINGCOUNT=<rings>  - Dieser tooltype sagt der node, nahc wievielen RINGS\n                       sie das modem beantworten soll.\n\n\n  RIPSCRIPT=<numb>   - sagt der node die RIP Faehigkeit einzuschalten.\n                       Das ist eine neue terminalsprache.\n                       Die nummer sind 10-tel sekunden. Standart ist 10.\n                       Dieses verzeogert die login-sequence, so dass \X\n                       feststellen kann, ob ein RIP-term anruft.\n\n  REMOTE_PASSWORD=   - sagt ACP dass ein user dieses passwort angeben muss\n                       um Zugriff zur shell zu bekommen.\n\n  SCREENS=<location> - Sagt, dass \X ein Gebiet fuer die .TXT files verwenden\n                       soll.Wenn man diese option fuer conferences verwendet,\n                       muss man auch ein directory fuer die bulletins haben.\n\n\n  SCREENPENS         - dieser tooltype dient zum Test fuer die Farben des\n                       uploda-filerequesters und der gesammten Erhscheinung des\n                       screens.Es ist schwer zu erklaeren, wie das funktioniert,\n                       aber es gibt 12 editierbare pens, die das Aussehen des\n                       screens bestimmen.Der sysop kann bestimmen, wie diese\n                       12 farben aussehen, hier also ein Beispiel:\n                       so here is an example:\n\n                       SCREENPENS=101010110110\n\n                             0 = BLACK\n                             1 = WHITE\n                             2 = GREEN\n                             3 = YELLOW\n                             4 = BLUE\n                             5 = MAGENTA\n                             6 = CYAN\n                             7 = RED\n\n                       Fuer einen 2-farbigen screen sieht man nur 1 und 0,\n                       also probiere es aus und sehe wie es laeuft.\n\n  SENTBY_FILES       - sagt /X dass du den namen eines users am ende eines von\n                       ihm upgeloadeten files haben moechtest.\n  STEALTH_MODE       - hier fraegt \X nach einem systempasswort, bevor BBSname\n                       und connect-message erscheinen.\n  START_LOG          - sagt /X die start und endzeiten dieser node aufzuzeichnen.\n\n  SYSTEM_PASSWORD=   - sagt ACP dass diese node vom user ein passwort verlangt\n                       bevor Zugriff zum system gegeben wird.\n\n  SYS_PWRD_PROMPT=   - Dieser toolstype gibt den prompt fuer das systempasswort an.\n                       standart ist  >:\n  SYSOP_CHAT_COLOR=  - sagt /X welche ANSI Farbe es verwenden soll, fuer\n                       SYSOPS Chat. (Wertebereich: 31-37)\n  TRAPDOOR           - sagt ACP dass diese node Express indirekt, ueber ein\n                       anderes Program starten wird.Bei dieser Option ist\n                       das extern zu startende Program im NODESTART= tooltype\n                       anzugeben.\n  TRAP_SERIAL        - dieses faengt die Fehlermeldungen der A2232 auf.\n  UD_LOG             - sagt /X alle uploads & downloads aufzuzeichnen\n                       im file UDLOG im node directory.\n  USER_CHAT_COLOR=   - sagt /X welche ANSI farbe fuer den Userchat verwendet wird.\n                       (Wertebereich: 31-37)\n  USERDATA_NAME=<path>-Hier kann ein alternetiver Pfad angegeben werden fuer\n                       USERDATA.\n  USERKEYS_NAME=<path>-Hier kann ein alternetiver Pfad angegeben werden fuer\n                       die USERKEYS.\n  USERMISC_NAME=<path>-Hier kann ein alternetiver Pfad angegeben werden fuer\n                       das USER.MISC file.\n  USERNUMBER_LOGIN   - sagt acp, dass user sich mit ihrer account nummer einloggen\n                       koennen,anstelle Ihres namens/handle.\n  VIEW_PASSWORD      - Dieser tooltype erlaubt es dir zu sehen, was die user\n                       als ihre passwords und neue user passwords eingeben.\n\n  =======================================================================\n@endnode\n@node Cap0703 "BBS:<CONF>.INFO ICON ToolTypes information"\n  =======================================================================\n  <CONF>.INFO        - Dieses icon beinhaltet informationen ueber\n  ~~~~~~~~~~~          Conferences. <CONF> = ConfName\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  CONFDB_SHARED=<confnum>\n                     - Dieser tooltype ermoeglicht es, einer conference zu sagen,dass\n                       sie den CONF.DB file einer anderen confernce verwenden soll.\n                       (Für die file credits und ratios der user)..\n                       NOTE: ACS.CONFERENCE_ACCOUNTING ist noetig, damit obiges\n                       in Kraft tritt.\n  CUSTOM             - Sagt express, dass DIESE conference AmiX-Net Mail verwendet.\n\n  DLPATH.<numb>=<str>- Noetig fuer alle conferences, die downloads und fileanzeigen\n                       erlauben.Gibt das directory der files an, die downgeloaded werden\n                       koennen. <numb> ist die nummer, wie of dieser DLPATH tooltype\n                       auftritt.\n                       Wenn der download pfad ein directory ist, muss\n                       der pfadname auf / enden.\n\n  FREEDOWNLOADS      - sagt /X dass die diese conference free downloads erlaubt.\n\n  FORWARDMAIL= <str> - Leitet Comments fuer den Sysop zu einem anderen User um.\n  FORCE_NEWSCAN      - Das zwingt die user zu einem New Mail scan, egal ob sie\n                       das angewaehlt haben oder nicht.\n  INTERNETNAME       - Sagt \X, welchen INTERNETNAME es verwenden soll, fuer mails\n                       aus dieser conference.Wenn dieser tooltype nicht gesetzt ist,\n                       greift express auf den login namen zurueck.\n\n  MENU_PROMPT=       - Dieser tooltype stellt den MenuPrompt in dieser\n                       conference ein.\n  NDIRS= <numb>      - noetig fuer alle conferences, die file-transfers erlauben.\n                       <numb> gibt die nummer des file-catalogs dieser conference\n                       an.\n  NO_NEWSCAN         - schalted den New Mail scan ab, egal, ob derr user ein oder\n                       ausgeschalted hat.\n  REALNAME           - Schalted die realname option in dieser conference ein.\n\n  SHOW_NEW_FILES     - Wenn es im CONF icon steht, ist es wie das obige zwingende\n                       Kommando fuer messages.\n                       IE: Zwinge deine User zu einem new file scan, egal ob sie\n                           das gewaehlt haben , oder nicht.\n  ULPATH.<numb>=<str>- Gibt ein Ueberlauf directory fuer uploads an.Dies ist\n                       nuetzich fuer Faelle, wenn das Standart upload directory\n                       keinen Platz fuer weitere files hat.\n                       <numb> gibt an, wie oft ULPATH tooltypes auftreten.\n                       Wenn der uploadpfad ein Dir ist, endung auf /.\n\n\n  =======================================================================\n@endnode\n@node Cap0704 "BBS:CONFCONFIG.INFO ICON ToolTypes information"\n  =======================================================================\n  CONFCONFIG.INFO    - Dieses Icon muss im BBS directory liegen. Es definiert\n  ~~~~~~~~~~~~~~~      die conferences.\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  NCONFS= <numb>     - sagt /X die anzahlt der conferenes deines BBS.\n  NAME.<numb>=<name> - sagt/X die namen der conferences des BBS.\n  LOCATION.<numb>=   - sagt /X die pfade deiner conferences.\n  RELATIVE_CONFERENCES\n                     - /X zeigt nur conferences, die von usern benuetzt werden\n                       im vergleich zu allen verfuegbaren conferences.\n  =======================================================================\n@endnode\n@node Cap0705 "BBS:DRIVES.INFO ICON ToolTypes information"\n  =======================================================================\n  DRIVES.INFO        - dieses Icon soll ins BBS: directory.Hier gibt man die\n  ~~~~~~~~~~~          upload directories an.\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  DRIVE.<numb>=<name>- sagt /X welche laufwerke verwendet werden, wenn der freie\n                       Speicher fuer uploads berechnet wird.\n                       IE: DRIVE.1=DH0:\n                           DRIVE.2=DH1:\n  =======================================================================\n@endnode\n@node Cap0706 "BBS:SCREENTYPES.INFO ICON ToolTypes information"\n  =======================================================================\n  SCREENTYPES.INFO   - Dieses icon sollte ins BBS: Directory\n  ~~~~~~~~~~~~~~~~     hier schreibt man informationen fuer verschiedene\n                       ScreenTypes, wie z.B verschiedene Sprachen hinein.\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  TYPE.<numb>=<EXT>  - das gibt die Endung der ScreenTypes an.\n                       z.B. "TXT","GER" & "ENG". waehle was du willst..\n  TITLE.<numb>=<name>- Gibt den namen des screentypes an, den du willst.\n                       z.b. "AMIGA ANSI","GERMAN" & "ENGLISH".\n\n  =======================================================================\n@endnode\n@node Cap0707 "BBS:COMPUTERLIST.INFO ICON ToolTypes information"\n  =======================================================================\n  COMPUTERLIST.INFO    - Dieses icon gibt die ComputerTypen an, die der User\n  ~~~~~~~~~~~~~~~~~      waehlen kann.\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  COMPUTER.NUM=<numb>  - Gibt die Gesammtzahl der ComputerTypen an, die`s im\n                         BBS gibt.\n  COMPUTER.<numb>=     - Gibt die computer Beschreibung wieder, die die User\n                         waehlen koennen fuer ihre USERDATA.\n  =======================================================================\n@endnode\n@node Cap0708 "BBS:NAMESNOTALLOWED.INFO ICON ToolTypes information"\n  =======================================================================\n  NAMESNOTALLOWED.INFO - Dieser tooltype gibt Usernamen an, die man nicht verwendet\n  ~~~~~~~~~~~~~~~~~~~~   sehen will,im BBS.z.B: ALL,EALL,SYSOP sollten hier stehen,\n                         um user davonabzuhalten mit diesen namen ins BBS einzuloggen.\n                         Dieses Icon bitte ins BBS: directory.\n\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  NAME.<numb>=         - Gibt den namen an, der nicht verwendet werden soll\n                         im BBS..\n  =======================================================================\n@endnode\n@node Cap0709 "BBS:PROTOCOLS Directory information"\n  =======================================================================\n  Protocols.INFO       - Dieses Icon steht nur fuer ein directory, ein\n  ~~~~~~~~~~~~~~         Directory das im BBS: directory liegen sollte.\n\n\n  ABOUT: Dieses direcotry enthaelt XPR definintionen fuer \X.\n\n       WICHTIG ! - Man muss ein door namens XPR haben, das in BBS:COMMANDS/SYSCMD\n                   liegen sollte, damit die XPR`s funktionieren.\n\n\n  Folgendes ist eine liste von Icons, die in dieses directory gehoeren :\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n    @{" XPRTypes.INFO ICON           " Link Cap070901}    @{" <XFERlib>.INFO ICON          " Link Cap070902}\n\n                     @{" Hydra.INFO ICON           " Link Cap070903}\n\n  =======================================================================\n@endnode\n@node Cap070901 "BBS:PROTOCOLS/XPRTypes.INFO ICON ToolTypes Info"\n  =======================================================================\n  XPRTypes.INFO        - gibt die XFER protokolle an, die im BBS zur verfuegung\n  ~~~~~~~~~~~~~          stehen.Das Icon sollte ins BBS:protocols/\n\n\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  TITLE.<numb>=<title> - Gibt den Titel fuer die XFER Lib an, der im BBS\n                         erscheint.\n  LIBRARY.<numb>=<library | INTERNAL>\n\n                       - Gibt die libraray an, die fuer <numb> Title\n                         im BBS verwendet wird.INTERNAL verwendet die \\n                         eigenen Protokolle.\n  =======================================================================\n@endnode\n@node Cap070902 "BBS:PROTOCOLS/<XFERLib>.INFO ICON ToolTypes Info"\n  =======================================================================\n  <XFERLib>.INFO       - Gibt die optionen fuer jede XFERlibrary im BBS an.\n\n                         e.g.: XPRZmodem.INFO = xprzmodem.library\n                               XPRYmodem.INFO = xprymodem.library\n                         Das icon sollte ins BBS:protocols/\n\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  OPTIONS=<opt>        - ermoeglicht es options fuer die XFERLibraries anzugeben.\n\n                         e.g.: OPTIONS=TN,AY,OR,KY,SN,RN,DN,F0,B32\n  AE_BATCH             - ALLe batch protokol-icons muessen den tooltype\n                         AE_BATCH anstelle von Batch enthalten.\n  =======================================================================\n@endnode\n@node Cap070903 "BBS:PROTOCOLS/<Hydra>.INFO ICON ToolTypes Info"\n  =======================================================================\n  <Hydra>.INFO         - Gibt die optionen fuer das neue Hydra protokol an.\n  ~~~~~~~~~~~~           Damit es mit \X laeuft muss man:\n\n                            1st: aehydra file im Doors: muss da sein.\n                                 Die aehydra.library ist in diesem file, also\n                                 wird kein file im libs: benoetigt.\n\n                            2nd: Man braucht die richtigen settings im\n                                 Hydra.Info icon.\n\n                         e.g.  OPTIONS=AEHYDRA\n                               TXWINDOW=0\n                               RXWINDOW=0\n                               STACK=4096\n\n                         Man braucht nicht AE_Batch in diesem icon. Auch diese\n                         OPTION verwendet das NODE/PLAYPEN DIR fuer uploads.\n                         Man darf keinen anderen pfad wie RAMPEN angeben !\n\n\n      NOTE: INFORMATION fuer deine User.\n      ~~~~\n            Hydra laeuft ausschliesslich mit V32.Also sollten die User einen\n            V32 connect anstreben.Beim USR beispielsweise mit &N8.\n\n\n                         Dieses Icon sollte im BBS:Protocols/ sein.\n\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  AE_BATCH             - Alle batch protocol icons muessen den tooltype\n                         AE_BATCH anstelle von batch enthaten.\n  OPTIONS=<opt>        - Erlaubt, die optionen fuer die XFERlibs anzugeben.\n\n                         e.g.: OPTIONS=TN,AY,OR,KY,SN,RN,DN,F0,B32\n  =======================================================================\n@endnode\n@node Cap0710 "BBS:ACCESS.INFO ICON ToolTypes Information"\n  =======================================================================\n  ACCESS.INFO          - Gibt den standart Zugriff wieder, der einem Useraccount\n  ~~~~~~~~~~~            zugeordnet ist, wenn er/sie sich einlogt.\n                         %References: ACS.DEF.INFO ICON\n                         Diese standartwerte koennen verwendet werden, mit der\n                         ACS.OVERRIDE_DEFAULTS Option.\n\n  Folgend eine liste von icons, die in diesem directory platz finden sollte,\n  um ACCESS Levels,AREA Names & PRESETS fuer die User Accounts zu haben.\n\n    @{" ACS.<level>.INFO ICONS       " Link Cap071001}    @{" AREA.<AXSName>.INFO ICONS    " Link Cap071002}\n    @{" PRESET.<x>.INFO ICONS        " Link Cap071003}\n\n  =======================================================================\n@endnode\n@node Cap071001 "BBS:ACCESS/ACS.<level>.INFO ICON ToolTypes Info"\n  =======================================================================\n  ACS.<level>.INFO     - Das ICON muss im ACCESS directory sein.\n  <username>.INFO        Es kann der USERNAME oder das Accesslevel sein..\n  ~~~~~~~~~~~~~~~~       i.e.: ACS.010, ACS.200, ACS.255, BYTEMASTER, USER\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  ACS.ACCOUNT_EDITING  - Gibt Zugriff, um Accounts zu editieren.\n  ACS.ATTACH_FILE      - Erlaubt dem user einen file an messages zu haengen.\n  ACS.BREAK_CHAT       - Erlaubt dem user den sysopchat mit CTRL-C zu unterbrechen.\n  ACS.CONFFLAGS        - Erlaubt dem User das CF command zu verwenden.\n  ACS.CONFERENCE_ACCOUNTING\n                       - das schalted den Conference Account fuer einen user\n                         an.Man kann also ein Ratio fuer jede conference und dort\n                         fuer jeden user einstellen.\n  ACS.CREDIT_ACCESS    - Erlaubt einem user (co-sysop/sysop) den CREDIT ACCOUNT\n                         zu sehen, wenn sie ACCOUNT EDITING zugriff haben.\n  ACS.COMMENT_TO_SYSOP - Erlaubt es dem user einen commetn an sysop zu hinterlassen.\n  ACS.DUPE_FILECHECK   - Schalted DUPE FILECHECKING nach dem upload, fuer angegebene\n                         user an.\n  ACS.DOWNLOAD         - Erlaubt den usern download..\n  ACS.DISPLAY_USER_STATS\n                       - Erlaubt usern ihren systemsatus zu sehen.\n  ACS.DELETE_MESSAGE   - user darf messages leoschen.\n  ACS.EDIT_DIRS        - user darf catalogs von files ediieren.\n  ACS.EDIT_FILES       - user darf files im bbs editieren.\n  ACS.EDIT_USER_INFO   - user darf seinen account editieren\n  ACS.EDIT_USER_NAME   - der user darf sein handle aendern..\n  ACS.EDIT_USER_LOCATION\n                       - user darf seinen wohnort aendern.\n  ACS.EDIT_PHONE_NUMBER- "                telefonnummer.\n  ACS.EDIT_PASSWORD    -                  passwort\n  ACS.ENTER_MESSAGE    - user darf messages eingeben.\n  ACS.EALL_MESSAGES    - user darf EMAIL an AllE user schreiben, so dass diese\n                         gezwungen sind, diese zu lesen.\n  ACS.FULL_EDIT        - user darf den FULL-SCREEN-EDITOR verwenden, wenn es einen\n                         im SYSCMD <dir> gibt.\n  ACS.FILE_LISTINGS    - erlaubt,catalogs verfuegbarer files zu sehen..\n  ACS.FILE_EXPANSION   - erlaubt files mit wildcard anzugeben.\n  ACS.FREE_RESUMING    - erlaubt weitermachen, bei teilweisen uploads..\n  ACS.HIDE_FILES       - hindert den user beim WHO command zu sehen, welche files\n                         transfereiert werden. (ebenso im NEWCHAT-command)\n\n  ACS.JOIN_CONFERENCE  - user darf eine conference joinen.\n  ACS.LIST_NODES       - erlaubt dem user die nodes zu sehen, die online sind.\n  ACS.MAX_PAGES=<numb> - Setzt die Maximale Anzahl von (sysop)Rufen pro session.\n                         Ruft ein user ueber dem maximum, geht der Ruf als Comment\n                         zum sysop.\n\n  ACS.MCI_MESSAGE      - user darf MCI Messages im BBS schreiben.\n  ACS.MODIFY_VOTE      - erlaubt es dem sysop-zugriff,informationen in der\n                         Wahlkabine aendern.\n  ACS.NEW_FILES_SINCE  - user darf juengste catalog-eintraege listen.\n  ACS.OVERRIDE_DEFAULTS- OverRide access, wie es im ACCESS Icon tooltype bereits\n                         erklaert wurde.\n  ACS.OLM              - user darf OLM senden.(Internal ONLINE Message\n                         sender), messages an ALLE Nodes.\n  ACS.OVERRIDE_CHAT    - user darf das \X chat flag uebergehen und den\n                         Sysop rufen.\n  ACS.OVERRIDE_TIMES   - user darf die Zeitlimits umgehen, die an einer node\n                         gelten.\n  ACS.PAGE_SYSOP       - user darf sysop rufen..\n                         wenn das sysop page(= ruf) flag abgeschalted ist, wird der user\n                         verstaendigt, dass du nicht verfuegbar bist.\n\n  ACS.PUB_MSGFILES     - user darf einen file uploaden in die MSGBASE\n                         und kann diesen automatisch anhaengen an (ALLE)\n                         Users mitder "X"Option.\n  ACS.PRI_MSGFILES     - user darf file in die MSGBASE uploaden und kann\n                         ihn automatisch anhaengen an eine message an EINEN user.\n                         mit der "X" Option\n  ACS.QUIET_NODE       - user kann sich fuer andere nodes unsichtbar machen,\n                         mit dem "Q" commando im Hauptmenu.\n  ACS.READ_BULLETINS   - user darf die normalen Bulletins lesen.\n  ACS.READ_MESSAGE     - user darf messages lesen.\n  ACS.RELOGON          - user darf einen RELOGON machen, mit "RL"\n                         im Hauptmenu.\n  ACS.REMOTE_SHELL     - user bekommt zugriff auf die Remote(=ferngesteuerte) shell.\n  ACS.SYSOP_READ       - user darf mail lesen, egal fuer wen diese mail ist.\n\n  ACS.SHOW_PAYMENTS    - user kann sehen, wann sein credit account ausgeht,\n                         mittels des ''S'' commands.\n  ACS.SYSOP_VIEW       - user kann files sehen, wie der sysop.\n  ACS.SYSOP_DOWNLOAD   - user darf einen SYSOPDOWNLOAD auf jeden pfad durchfuehren.\n  ACS.SYSOP_COMMANDS   - user darf normale sysop commands ausfuehren.\n  ACS.ULSTATS          - user kann die zahl der uploads seit dem letzen sysop\n                         logon sehen.\n  ACS.UPLOAD           - user darf files uploaden.\n  ACS.VOTE             - user darf mitwaehlen, in der wahlkabine\n  ACS.WHO_IS_ONLINE    - user kann nodes sehen, mittels "WHO" command.\n  ACS.VIEW_A_FILE      - user kann downloadbare text files sehen.\n  ACS.XPR_RECEIVE      - user kann file empfangen mittels XPR Libraries.\n  ACS.XPR_SEND         -  "             senden          ".\n  ACS.ZIPPY_TEXT_SEARCH- user kann den catalog nach schluesselwoertern durchsuche\n                         mit den ONLINE-such features von /X.\n  ACS.ZOOM_MAIL        - user kann Zoom Mailing fuer messages verwenden\n  =======================================================================\n@endnode\n@node Cap071002 "BBS:ACCESS/AREA.<AXSName>.INFO ToolTypes Info"\n  =======================================================================\n  AREA.<AXSName>.INFO  - Dieses Icon sollte ins ACCESS dir.\n  ~~~~~~~~~~~~~~~~~~~    Es definiert den zugriff, den ein user in conferences hat.\n                         Der gleiche name sollte im ACCOUNT EDITING stehen,\n                         unter "AREA NAME".\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  CONF.<x>             - ein user mit diesem AREA NAME darf die conference\n                         joinen, die unter <x> angegeben ist.\n  =======================================================================\n@endnode\n@node Cap071003 "BBS:ACCESS/PRESET.<x>.INFO ToolTypes Info"\n  =======================================================================\n  PRESET.<x>.INFO      - man kann hier PRESETS fuer das Accounts editieren ueber\n  ~~~~~~~~~~~~~~~        tooltypes angeben.Das Icon bitte ins ACCESS directory.\n   <x> = 1 - 8\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  PRESET.AREA=<name>   - Gibt den AREANAME für den UserAccess an, zu dem\n                         der user zugang hat.\n  PRESET.ACCESS=<numb> - gibt den zugang fuer die Preset an, die man setzen\n                         moechte.\n  PRESET.CONFRJOIN=    - gibt die conference an, wenn ein user mit diesem\n                         PRESET gewaehlt wird. er wird automatisch diese confernce\n                         joinen, bei seinem naechsten logon\n  PRESET.DAILY_BYTE_LIMIT=\n                       - Gibt das taeglich Byte Limit für die Voreinstellung\n                         an, die man setzen moechte.\n  PRESET.RATIO_TYPE=   - Gibt den RatioType an, der als Voreinstellung dienen soll.\n\n  PRESET.RATIO=<numb>  - Gibt das Ratio, dass man als Voreinstellung wuescht.\n\n  PRESET.TIME_LIMIT=   - Gibt das Zeitlimit an, das man als Voreinstellung wuescht.\n\n  =======================================================================\n@endnode\n@node Cap0711 "BBS:FCHECK Directory Information"\n  =======================================================================\n  FCHECK.INFO          - Dieses icon steht fuer ein Directory., das sich\n  ~~~~~~~~~~~            im BBS: directory befinden muss.\n\n\n  ABOUT: Dieses Dir enthaelt infos fuer die Checker von \X.\n\n  Folgende Icons sollten in diesem dir sein.:\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                     @{" <EXTENSION>.INFO ICONS       " Link Cap071101}\n\n  =======================================================================\n@endnode\n@node Cap071101 "BBS:FCHECK/<EXT>.INFO ICON ToolTypes Info"\n  =======================================================================\n  <EXT>.INFO           - Diese ICONS werden fuer FCHECK im Express verwendet\n  ~~~~~~~~~~             und sollten sich im BBS:FCHECK befinden.\n                         <EXT> = file-endung, wie z.B: "DMS", "WRP"\n                                 & "LHA"\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  CHECKER=<comp.Path>  - gibt den vollen pfad zum FileChecker an, den man\n                         fuer diese file-endung verwenden will.\n  ERROR.<numb>=<name>  - gibt die Fehlermeldung an, wenn ein file corrupt ist\n                         und er in das Hold (=Halten) Directory gebracht wird.\n                         Man kann unbegrenzt viele Fehlermeldungen angeben, durch\n                         aendern von <numb>.\n  OPTIONS=<options>    - Gibt die option an, mit der der Filechecker gestarted\n                         gestarted wird. Sie wird nach das commando des filecheckers\n                         gesetzt.\n  PRIORITY=<numb>      - gibt die Taskprioritaet fuer den Filechecker an.\n\n  SCRIPT=<script path> - express fuehrt diese script nach dem filechecker\n                         aus. Wenn das erledigt ist, verschiebt \X den file\n                         wo immer er auch hingehoert.\n\n                         NOTE: express uebergibt den filenamen als erstes\n                         ~~~~ command line argument an die SCRIPT.\n  STACK=<numb>         - gibt den stack fuer den filechecker an.\n\n  =======================================================================\n@endnode\n@node Cap0712 "BBS:NODE(x) Directory Information"\n  =======================================================================\n  NODE<x>.INFO         - Dieses Ich steht fuer ein directory, das\n  ~~~~~~~~~~~~           sich im BBS: befinden sollte.\n\n\n  The following list are ICONS which should be placed in this directory:\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n    @{" CONNECT.DEF.INFO ICON        " Link Cap071201}    @{" WINDOW.DEF.INFO ICON         " Link Cap071202}\n    @{" TIMES.DEF.INFO ICON          " Link Cap071203}    @{" NRAMS     <Directory>        " Link Cap071204}\n    @{" SERIAL    <Directory>        " Link Cap071205}    @{" MODEM     <Directory>        " Link Cap071206}\n\n  =======================================================================\n@endnode\n@node Cap071201 "BBS:NODE<x>/CONNECT.DEF.INFO ICON Info"\n  =======================================================================\n  CONNECT.DEF.INFO     - Dieses Icon sollte im NODE<x> directory sein.\n  ~~~~~~~~~~~~~~~~       Es enthaelt connect messages um die baudrate anzupassen.\n\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  <connectmsg>=<baud>  - wenn die connectmessage uebereinstimmt, wird die\n                         baudrate auf die angegebene rate gesetzt.\n  example:\n  CONNECT 2400/ARQ/MNP/MNP5=9600\n                       - Wenn die connect message die obige ist, wird die baudrate\n                         auf 9600 Baud geaendert.\n               NOTE:     Dieser tooltype ist nicht zwingend,er erlaubt nur\n                         aelteren modems korrekt gehandhabt zu werden.\n\n                         i.e.:\n                             alte HST modems zeigten connect 9600 an,obwohl\n                             der connect bei 14400 lag.\n\n  =======================================================================\n@endnode\n@node Cap071202 "BBS:NODE<x>/WINDOW.DEF.INFO ICON Info"\n  =======================================================================\n  WINDOW.DEF.INFO      - Dieses Icon gehoert in das NODE<x> dir, es gibt\n  ~~~~~~~~~~~~~~~        window-einstellungen dieser node wieder.\n\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  WINDOW.NUM_COLORS=   - Gibt die Anzahl der Farben wieder, die man fuer dieses\n                         node window wuenscht.\n  WINDOW.INTERLACE=    - Gibt an, dass dieses window in hires-interlace\n                         sein sollte.\n  WINDOW.LEFTEDGE=     - ist der Begin der linken oberen ecke des windows.\n\n  WINDOW.TOPEDGE=      - ist der Begin des windows an dessen oberer Kante.\n\n  WINDOW.WIDTH=<numb>  - Gibt die breite des windows an..\n  WINDOW.HEIGHT=<numb> -   "      hoehe          "\n  WINDOW.STATBAR       - schalted die STATBAR im Node Window ein.\n  WINDOW.ICONIFIED     - gibt an, ob man das window ICONIFIED haben moechte,wenn\n                         man ACP.CTRL started..\n  WINDOW.TO_FRONT      - gibt an, ob das Node Window automatisch nach\n                         vorne kommt, wenn man ACP started.\n  =======================================================================\n@endnode\n@node Cap071203 "BBS:NODE<x>/TIMES.DEF.INFO ICON Info"\n  =======================================================================\n  TIMES.DEF.INFO       - Das Icon sollte im NODE<x> directory liegen, es gibt\n  ~~~~~~~~~~~~~~         Zeiten an, zu denen die baudrate nicht sein darf oder\n                         doch erlaubt ist.\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  START.<baud>=<time>  - Anfangszeit dieser BaudRate\n  END.<baud>=<time>    - Endzeit dieser  BaudRate\n                       - fuer maximale Anruf-zeit schreibe man:\n                         START.<baud>=0000\n                         END.<baud>=2359\n                         oder waehle  OVERRIDE_TIMES\n  =======================================================================\n@endnode\n@node Cap071204 "BBS:NODE<x>/NRAMS Directory Info"\n  =======================================================================\n  NRAMS.INFO           - Dieses icon ist ein directoryy, das sich im\n  ~~~~~~~~~~             BBS:NODE<x>/ directory befinden sollte.\n\n\n  ABOUT: Das dir enthaelt NRAMS definitionen fuer das modem.\n\n  Folgende files sollten in diesem dir sein:\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                     @{" <name>.DEF.INFO ICON         " Link Cap07120401}\n\n  =======================================================================\n@endnode\n@node Cap07120401 "BBS:NODE<x>/NRAMS/<name>.DEF.INFO ICON Info"\n  =======================================================================\n  <name>.DEF.INFO      - Das icon sollte im NODE<x>/NRAMS directory sein.\n  ~~~~~~~~~~~~~~~        Es gibt die NRAM Prefs wieder, die man will, wenn man\n                         den ACP.CTRL button "Set NRAMS" drueckt.\n                       - Man <name> waehlen wie man will.\n                         ACP sucht nach dem  #?.DEF.INFO file im\n                         NRAMS dir. Kein spezieller name ist notwendig.\n                       - NRAMS wird aktiviert, wenn man den\n                         "Set NRAMS" button im ACP SERVER betaetigt.\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  NRAM.<numb>=<sets>   - Gibt die NRAM Settings deines Modems an.\n                         Man kann beliebig viele NRAM settings haben, wenn\n                         man <numb> anpasst.\n  =======================================================================\n@endnode\n@node Cap071205 "BBS:NODE<x>/SERIAL Directory Info"\n  =======================================================================\n  SERIAL.INFO          - Das icon steht fuer ein Directory, das im\n  ~~~~~~~~~~~            BBS:NODE<x>/ directory sein sollte.\n\n\n  ABOUT: Das directory enthaelt SERIAL Defintionen für AmiExpress.\n\n  Folgende Icons braucht man in diesem directory:\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                     @{" <name>.DEF.INFO ICON         " Link Cap07120501}\n\n  =======================================================================\n@endnode\n@node Cap07120501 "BBS:NODE<x>/SERIAL/<name>.DEF.INFO ICON Info"\n  =======================================================================\n  <name>.DEF.INFO      - Das ICON sollte im NODE<x>/SERIAL dir sein.\n  ~~~~~~~~~~~~~~~        Es enthaelt die SERIAL Prefs deines Computers.\n\n                       - Man kann <name> frei waehlen, da ACP nach\n                         #?.DEF.INFO files im SERIAL directory sucht.\n                         Kein spezieller name ist noetig.\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  SERIAL.UNIT=<unit>   - die UNIT deiner MULTISERIALCARD.\n  SERIAL.BAUD=<baud>   - die INITT BaudRate für EXPRESS.\n  SERIAL.DRIVER=<name> - der SERIALDRIVER für EXPRESS\n                         i.e.: SERIAL.DEVICE.\n  SERIAL.A2232_PATCH   - Schalted den A2232 Multi user serial card Patch ein..\n  SERIAL.NO_PURGELINE  - express clearedt nicht den serial port, nachdem es dem\n                         modem das reset-command geschickt hat.Ich glaube nicht,\n                         dass jemand das verwenden wird.\n  SERIAL.REPURGE       - das commando verarbeited alle daten, die vom\n                         serial port nach einem modem reset kommen.normalerweise\n                         wird er port nur ge-cleared, aber bei A2232 cards, scheint\n                         ein CLEAR port nicht verstandne zu werdne, folglich ist\n                         SERIAL.REPURGE noetig, um die verbleibenden daten zu\n                         verarbeiten.\n  SERIAL.LOGOFF_RESET  - Das modem wird vor und nach jedem call reset-ed.\n                         Diese Methode war standart in der 1.x serie von \X.\n                         Wenn`s Probleme mit logoff gibt, kann man diesesversuchen.\n\n                         .\n  SERIAL.TRUE_RESET    - express reset-ed das modem mit den folgenden\n                         strings:\n                         MODEM.RESET\n                         ATZ\n                         MODEM.INIT\n                         MODEM.RESET\n  =======================================================================\n@endnode\n@node Cap071206 "BBS:NODE<x>/MODEM Directory Info"\n  =======================================================================\n  MODEM.INFO           - Dieses icon steht fuer ein dir, das sich im\n  ~~~~~~~~~~\n                         BBS:NODE<x>/ directory befinden sollte.\n\n  ABOUT: Es befinden sich darin Modem definitionen fuer express.\n\n  Folgende files bracuh man in diesem directory:\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                     @{" <name>.DEF.INFO ICON         " Link Cap07120601}\n\n  =======================================================================\n@endnode\n@node Cap07120601 "BBS:NODE<x>/MODEM/<name>.DEF.INFO ICON Info"\n  =======================================================================\n  <name>.DEF.INFO      - Dieses Icon sollte im NODE<x>/MODEM dir sein.\n  ~~~~~~~~~~~~~~~        Es enthaelt modem prefs fuer \X.\n\n                       - Man kann <name> frei waehlen, da ACP nur nach\n                         #?.DEF.INFO files im MODEM directory sucht.\n                         Kein spezieller name ist noetig.\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  MODEM.INIT=          - initialize string fuer das modem.\n  MODEM.RESET=         - reset string , um einen weiteren Anruf empfangen zu koennen\n\n  MODEM.RING=          - string, woran \X einen ankommenden Anruf erkennen\n                         kann.\n  MODEM.ANSWER=        - string, mit dem \X einen ankommenden Aruf beantorted\n\n  MODEM.OFFHOOK=       - string, mit dem das modem off hook. geht.\n  =======================================================================\n@endnode\n@node Cap0713 "BBS:COMMANDS Directory Information"\n  =======================================================================\n  COMMANDS.INFO        - Dieses Icon ist ein directory, es sollte im\n  ~~~~~~~~~~~~~          BBS: directory liegen.\n\n\n  ABOUT: Das directory enthaelt MODULE defintionen fuer modules, die in verschiedenen\n         dir liegen und unten aufgelisted sind.\n\n    @{" BBSCmd    <Directory>        " Link Cap071301}    @{" SYSCmd    <Directory>        " Link Cap071302}\n    @{" CONF(x)   <Directory>        " Link Cap071303}    @{" NODE(x)   <Directory>        " Link Cap071304}\n\n  =======================================================================\n@endnode\n@node Cap071301 "BBS:COMMANDS/BBSCmd Directory Information"\n  =======================================================================\n  BBSCmd.INFO          - Das ICON ist ein Directory, das sich im\n  ~~~~~~~~~~~            COMMANDS directory befinden sollte.\n\n\n  ABOUT: Das directory enthaelt module-defintionen fuer module, die von\n         jeder Stelle im BBS ausgefuehrt werden koennen.\n\n    Folgende icons koennen in dieses director gesetzt werden:\n    ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                     @{" <module>.INFO ICONS          " Link Cap0713011}\n\n  =======================================================================\n@endnode\n@node Cap071302 "BBS:COMMANDS/SYSCmd Directory Information"\n  =======================================================================\n  SYSCmd.INFO          - Das Icon ist ein directory, das sich im COMMANDS\n  ~~~~~~~~~~~            Directory befinden muss.\n\n\n  ABOUT: Das directory enthaelt module definitionen fuer Modules die\n         nur von MCI Message/Textures oder interenen Modulestarten ausgefuert\n         werden koennen, jedoch nicht vom Main Menu aus.\n\n    Folgende icons koennen in dieses director gesetzt werden:\n    ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                     @{" <module>.INFO ICONS          " Link Cap0713011}\n\n  =======================================================================\n@endnode\n@node Cap071303 "BBS:COMMANDS/CONF<x> Directory Information"\n  =======================================================================\n  CONF<x>.INFO         - Das Icon steht fuer ein Directory, das sich im\n  ~~~~~~~~~~~~           COMMANDS directory befinden sollte.\n\n\n  ABOUT: Das directory enthaelt module-definitionen fuer module, die nur\n         in conferences ausgefuehrt werden koennen, die man mit <x> angewaehlt\n         hat.\n\n    Folgende icons koennen in dieses director gesetzt werden:\n    ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                     @{" <module>.INFO ICONS          " Link Cap0713011}\n\n  =======================================================================\n@endnode\n@node Cap071304 "BBS:COMMANDS/NODE<x> Directory Information"\n  =======================================================================\n  NODE<x>.INFO         - Das icon ist ein dir, das sich im COMMANDS dir\n  ~~~~~~~~~~~~           befinden muss.\n\n\n  ABOUT: Das directory enthaelt modul-definitionen fuer module, die nur\n         in dieser node ausgefuehrt werden koennen, die man mit <x>\n         gewaehlt hat.\n\n    Folgende icons koennen in dieses director gesetzt werden:\n    ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                     @{" <module>.INFO ICONS          " Link Cap0713011}\n\n  =======================================================================\n@endnode\n@node Cap0713011 "<Module>.INFO ICONS ToolTypes Information"\n  =======================================================================\n  <module>.INFO        - Das ICON ist ein MODULE für /X. Der Name des\n                         <module> sollte der gleiche sein, wie im Mainmenu.\n                         Es sollte sich im Suchpfad befinden.\n\n\n     a> BBSCmd     - Module dieses dirs koennen von jedem menuprompt\n                     oder jedem MCI text file bedient werden..\n\n     b> SYSCmd     - Module dieses dirs sind nur per MCI text file und\n                     durch interne BBS operationen zu bedienen.\n\n     c> CONF(x)    - Module dieses dirs koennen vom conference(x) menu prompt\n                     oder von jedem MCI text file in dieser conference bedient.\n                     werden.\n     d> Node(x)    - Module dieses dirs koennen vom node(x) menu prompt oder\n                     per MCI text file in dieser node(x) bedient werden.\n\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  ACCESS= <numb>       - sagt /X das access level,das noetig ist, dieses\n                         module zu bedienen..Diese option wird ignoriert, wenn es sich\n                         um interen mudule-options handelt.\n  INTERNAL= <command>  - Gibt an, ob man dieses Module wie ein internes \X command\n                         haben moechte. Waehlt man dieses an, braucht man die\n                         folgenden tooltypes nicht.\n\n  LOCATION= <string>   - gibt den pfad eines modules an.\n  MULTINODE= <YES|NO>  - sagt /X,ob das module gleichzeitig von anderen\n                         nodes genutzt werden kann.\n  PASSWORD= <string>   - der user muss ein passwort eingeben, bevor er das module\n                         verwenden darf.\n  PASS_PARAMETERS=<res>- dieser tooltype ist nur noetig, wenn man auch den iNTERNAL\n                         tooltype verwendet.\n                         verfuegbare optionen sind dann:\n\n                         PASS_PARAMETERS=1 - sagt \X,es soll nicht das internal\n                                             command ausfuehren.\n                         PASS_PARAMETERS=2 - sagt \x, es soll das custom-command\n                                             mit dem internal-command austauschen,\n                                             aber die commandline-parameter\n                                             beibehalten.\n                         PASS_PARAMETERS=3 - Das gleiche wie der vorhergehende eintrag,\n                                             nur dass \X das menu command\n                                             von anfang an nochmals ausfuehrt,dh:\n                                             \X ueberprueft nochmals die customcommands\n                                             um zu sehen, dass es alle Kritrien\n                                             erfuellt.\n\n\n                         PASS_PARAMETERS=4 - sagt \X, es soll den check der BBSCmd\n                                             module uebergehen.\n                                             diese option diente urspruenglich\n                                             dazu, einem sysop die Ausfuehrung\n                                             Interner commands von einem ConfXCMD\n                                             zu ermoeglichen und dabei die Ueberpruefung\n                                             des BBSCmd dirs fuer das interne commando\n                                             zu umgehen.\n\n  PRIORITY= <numb>     -priority des doors.Wenn man\n                         PRIORITY=SAME, waehlt, bekommt es die gleiche priority,\n                         die auch express verwendet.\n  QUICKMODE            - sagt \X das module nicht zu starten, wenn der user\n                         mit QUICK LOGOn eingelogt hat.\n\n  STACK= <numb>        - sagt /X die stacksize fuer dieses module\n                         module. Sandart ist 4096.\n  TYPE= <XIM | AIM | TIM | IIM | SIM | MCI >\n                       - sagt /X welcher typ module vorliegt:\n                         XIM = /X Standard Module\n                         AIM = Arexx Module (braucht REXXDOOR in\n                               BBS:Utils directory)\n                         TIM = Traditional BBS Module (braucht PARADOOR\n                               im  BBS:Utils directory)\n                         IIM = NO INTERFACE - Dieser typ Module wird das\n                               module starten und nicht warten, bsi es fertig\n                               ist.\n                         SIM = Script BBS Module - dieser typ wird ausgefuert\n                               als normale BatchScript.\n                         MCI = MCI Commanding.\n  TRAPON               - Generiert LOGON Output in ein Log für Fehlerkontrolle\n\n  =======================================================================\n@endnode\n@node Cap0714 "BBS:STORAGE Directory Information"\n  =======================================================================\n  STORAGE.INFO         - Diesesicon ist ein dir, es sollte im BBS: dir\n  ~~~~~~~~~~~~           sein.\n\n\n    Folgende icons koennen in dieses director gesetzt werden:\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                     @{" ICONS     <Directory>        " Link Cap071401}\n\n  =======================================================================\n@endnode\n@node Cap071401 "BBS:STORAGE/ICONS Directory Information"\n  =======================================================================\n  ICONS.INFO           - Das icon ist ein dir, das sich im BBS:STORAGE\n  ~~~~~~~~~~             befinden sollte.\n\n\n    Folgende icons muessen in dieses director gesetzt werden:\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                     @{" ICONIFIED.INFO ICON          " Link Cap07140101}\n\n  =======================================================================\n@endnode\n@node Cap07140101 "BBS:STORAGE/ICONS/ICONIFIED.INFO ICON Info"\n  =======================================================================\n  ICONIFIED.INFO       - Das icons sollte im BBS:STORAGE/ICONS\n  ~~~~~~~~~~~~~~         sein, es ist das ICONIFIED ICON fuer den ACP server,\n                         wenn man sein window schliesst.\n\n  =======================================================================\n@endnode\n@node Cap08 "Normal Documentation of AmiExpress"\n  =======================================================================\n  Die folgende Anleitung wurde entworfen, um dem Sysop klarzumachen,was genau\n  vor sich geht,in jeder Phase einer BBS-operation..\n  Ausser der Beschreibung allein, dient es dazu, dem Sysop zu helfen, sein\n  system zu optimieren, fuer maximale effizienz.\n\n\n  Nun,das wesentliche update der V3.36 DOCS war eine lange Zeit ueberfaellig\n  Hier sind sie also, die V4.0.Erstellt von mir,Andy (The Outlaw). (&<<Judas>>)\n  Die groesste Schwierigkeit in jeder commerziellen softwareveroeffentlichung\n  ist die Dokumentation.Nachdem Ich Jens Langer''s docs der version 3.60\n  gesehen haben, die etwas abwichen von einer normalen documatation, beshloss Ich\n  die dox im Amigaguide format zu schreiben, wie es sie auch in jeder zukuenftigen\n  release geben wird.Wenn du diese Art der dox magst, oder es Probleme gibt,\n  kannst du die Lightspeed\n  Technologies BBS anrufen,und Ich helfe dir mit \X so gut Ich kann.\n  Es ist sehr schwer, docs zu schreiben, un dIch hoffe, dumagst diesen\n  neuen Stil der dox.\n  Aber jetzt fahren wir fort mit der Dokumentation der \X dox. (na endlich ...)\n\n  Gehe mit dem mouse cursor auf das ACP.CTRL ICON und klick es 2* an.\n  Es sollte ein ICONIFIED window auf dem workbench auftauchen.\n\n  Wenn ACP.CTRL nicht kommt auf dem Workbench Screen,sollte ACP.CTRL\n  eine Fehlermeldung gegeben haben.Wenn es einen Fehler gab, schreibe ihn auf\n  und wenn`s keine Fehlermeldung gab, konaktiere das naechste \X support BBS.\n\n  Klicke auf das ICONIFIED window von ACP.CTRL, es soltle ein window mit einer\n  Menge Buttons auftauchen.\n  Links im window sollte man einen node(x) button sehen, fuer jede node, die\n  man wuenscht.Im oberen Teil des windows gibt`s 4 categorien.\n\n\n  ''User'', ''Location'', ''Action'' & ''Baud''. Unter ''Action'' sollte man eine\n  message fuer jede node sehen, die sagt ''Awaiting Connect''.\n  Sieht man kein ''Awaiting Connect'', dann oeffne eine shell und type\n  Express x (wobei x nodenummer ist), es sollte eine fehlermeldung kommen.\n  Haufiges Problem ist, dass man die configurations ICONS nicth richtig\n  gesetzt hat,dh: verschrieben beim device-treiber fuer den serialport\n  oder es fehlen einfach ein paar files.Was immer es ist, \X sollte es dir\n  sagen... Siehe auch andere sectionen fuer korrigierende Massnahmen.\n\n\n  Unter dem node buttons gibt`s eine serie von 18 buttons. Es sind\n  15 button in 3 spaltenam linken rand des windows. Diese buttons kontrolieren\n  \X.Man benutzt eine dieser buttons, indem man 1 der 15 buttons waehlt, dann\n  einen node-button betaetigt.\n\n  Wenn alle nodes melden : ''Awaiting Connect'',mache folgendes\n\n  1> druecke den new account button\n  2> druecke node 0 button\n\n  Man kommt in den Acount editor, man sieht folgendes:\n  -------------------------------------\n  S>earch by name  N>ew account editing C>redit Accounts\n  Edit Which Account?\n  -------------------------------------\n\n  1> Type 1 dann <RETURN>\n\n  Man kommt in den acount nummer 1, das ist der deine.\n  Man sieht darin folgendes:\n\n--------------------------------------------------------------------------------\n  ACTIVE [1]   BAUD: 14400\nA> Name: User Name-------------------30  B> Real Name: Joseph Hodge\nC> Loc.: location                  D> Pass ..........: ENCRYPTED\nE> Phone Number ..: 800-555-1212   G> Area Name......: Standard\nF> Ratio .........: 0              I> Sec_Level .....: 255\nH> Ratio Type ....: 0     <-Byte)  K> AutoReJoin ....: 1\nJ> Uploads .......: 0              M> Messages_Posted: 0\nL> Downloads .....: 0              O> New_User ......: No  #Calls: 0\nN> Bytes Uled ....: 1                 Last Called ...: Tue May 26 22:00:17 1994\nP> Bytes Dled ....: 0                 Computer Type .: Amiga 1000\nQ> Byte Limit ....: 0                 Screen Type ...: Amiga Ansi\nR> Time_Total: [0       ] mins     Y> Cps Up: 0         Z> Cps DN: 0\nS> Time_Limit: [0       ] mins     T> Time_Used: [0       ] mins  W> UUCP: 0\nU> Chat_Limit: [0       ] mins     V> Chat_Used: [0       ] mins\n\nX=EXIT-NOSAVE ~=SAVE  1-8=Presets  9=RE-ACTIVATE  DEL=DELETE\nTAB=CONT @=CONFERENCE ACCOUNTING !=CREDIT ACCOUNT MAINTENANCE\n--------------------------------------------------------------------------------\n\n  2> Druecke A, dann kannst du deinen usernamen eingeben.\n\n\n  3> Druecke B, dann kannst du den realnamen eingeben.,\n     falls du am internet haengst,etc....\n\n  4> druecke C, dann kannst du eine addresse ,gruppenname oder sonst etwas\n     eingeben.\n\n  5  Druecke D, dann kannst du dir ein passwort zuordnen.\n\n  6> Druecke E, dann kannst du die teleonnummer eingeben.\n\n  7> Druecke nun einen zahl von 1 bis 8 fuer die account standartwerte.\n\n  8> Pass auf, dass dein Time_Limit nicht auf 0 steht !\n\n  9> Druecke das ''~'' um den acount zu speichern.\n\n  hier das beispiel eines sysop accounts::\n\n--------------------------------------------------------------------------------\n  ACTIVE [1]   BAUD: 14400\nA> Name: User Name-------------------30  B> Real Name: Joseph Hodge\nC> Loc.: location                  D> Pass ..........: ENCRYPTED\nE> Phone Number ..: 800-555-1212   G> Area Name......: Standard\nF> Ratio .........: 0              I> Sec_Level .....: 255\nH> Ratio Type ....: 0     <-Byte)  K> AutoReJoin ....: 1\nJ> Uploads .......: 0              M> Messages_Posted: 0\nL> Downloads .....: 0              O> New_User ......: No  #Calls: 0\nN> Bytes Uled ....: 1                 Last Called ...: Tue May 26 22:00:17 1994\nP> Bytes Dled ....: 0                 Computer Type .: Amiga 1000\nQ> Byte Limit ....: 0                 Screen Type ...: Amiga Ansi\nR> Time_Total: [0       ] mins     Y> Cps Up: 0         Z> Cps DN: 0\nS> Time_Limit: [0       ] mins     T> Time_Used: [0       ] mins  W> UUCP: 0\nU> Chat_Limit: [0       ] mins     V> Chat_Used: [0       ] mins\n\nX=EXIT-NOSAVE ~=SAVE  1-8=Presets  9=RE-ACTIVATE  DEL=DELETE\nTAB=CONT @=CONFERENCE ACCOUNTING !=CREDIT ACCOUNT MAINTENANCE\n\n--------------------------------------------------------------------------------\n\n  9> Druecke TAB um das editieren abzuschliesen.\n\n         Man sieht folgendes:\n         -------------------------------------\n           S>earch by name  N>ew account editing C>redit Accounts\n           Edit Which Account?\n         -------------------------------------\n\n  10> Druecke return um account edition zu verlassen.\n\n  11> Waehle das schliesgadged um wieder zum workbench zu kommen. Das schliesst\n      auch das BBS window..\n  =======================================================================\n@endnode\n@node Cap09 "The Programlogic of AmiExpress"\n  =======================================================================\n  Hier eine Beschreibung der Programlogik von \X, so dass man lernen kann\n  wie \X auf das maximale potential gebracht werden kann.\n\n  Das ACP window hat 15 haupt buttons am unteren Rand des windows.\n  hier eine liste deren namen und funktionen:\n\n   [ Sysop LOGON ].....logt dich in die node als sysop..\n   [ Local LOGON ].....started die log-sequence ganz von anfang an.\n                       Man muss den namen und das passwort angeben.\n\n   [ Instant LOGON ]...Gibt dem modem ein carrier detect command.Das ist\n                       gut fuer die Wiederherstellung einer verbindung mit\n                       einem User, nachdem man mit ihm auf dieser line telefoniert\n                       hat.\n   [ Reserve Node ]....reserviert die node fuer einen bestimmten user.\n                       Nachdem der user angerufen hat, ist die reservierung\n                       beendet.\n   [ AEShell ].........oeffnet einen shell auf dem node screen.\n   [ Accounts ]........geht zum account editing einer node.\n   [ Toggle Chat ].....aendert das chat request flag einer node.\n                       Wenn das flag off ist,kann nur ein user mit hohem level\n                       einen chat requesten.\n\n   [ INIT Modem ]......initialisiert das modem einer node.\n   [ Exit Node  ]......faehrt die node herunter.\n   [ Node(offhook) ]...faehrt die node herunter un schalted die line BUSY\n\n   [ Node Config ].....holt das config program fuer eine spezielle node\n\n   [ Node Chat ].......oeffnet einen chat zwischen dir und der entsprechenden\n                       node.\n   [ Save Win ]........Dieser button braucht kein NODE(x) argument.\n                       Speichert die windowkoordinaten von ACP in den file\n                       S:ACP.Config\n   [ Set NRAMS ].......Der button setzt die NRAMS deines Modems und\n                       speichert diese in das Eprom.\n\n   NOTE: Alle obigen buttons brauchen,normalerweise einen klick auf den\n   ~~~~  gewuenschten nodebutton um in kraft zu treten..\n\n\n  Wenn alle nodes gestarted sind, finden die folgenden Actions bei jeder\n  node statt:\n\n  An diesem Punkt laed das BBS die computertypen von dem Icon\n  namens:\n\n  BBS:COMPUTERLIST.INFO\n\n  Ami-Express ueberprueft, ob die node bereits laeuft, als task.Wenn das zutrifft,\n  stoppt das program und es erscheint ein error-requester.\n\n  Nun versucht \X die LIBS:REXXSYSLIB.LIBRARY fuer Arexx zu oeffnen.Geht das nicht,\n  ist Arexx abgeschalted und der user wird dahingehend informiert.\n\n\n  Ami-Express durchlaueft einen initialization Process, wobei das modem\n  off-hook (BUSY) geschalted wird, bevor es fuer`s BBS nitialisiert wird.\n  (Damit ein eingehender Anruft nicht den prozess stoert.)ocess.\n\n  Wenn jemand ONLINE ist, stehen folgende function keys zur Verfuegung.\n\n\n  F1  - Chat in/out\n  F2  - Erhoehe On-line time limit +10 mins\n  F3  - Erniedrige On-line time limit -10 mins\n  F4  - Fragt nach einem filenamen fuer einen Capturefile (nur auf des SYSOPS\n        seite), wenn schon einer geoeffnet ist, schliesst er diesen und\n        informiert dich darueber.Nochmaliges F4 stoppt den capture file\n        wieder.\nS+F4  - Ein Requester kommt zu Auswahl eines ASCII files, der dem\n        User geschickt werden soll.\n  F5  - Locale Shell\n  F6  - Account Editing\nS+F6  - Laesst dich den account eines Users nur fuer diesen Anruf, solange er online\n        ist, editieren.Wenn err auflegt,setzt das BBS seinen Acount zurueck, auf den\n        alten Wert.Druecke Shift+F6 ein 2-tes mal und die settings werden durch\n        die alten ersetzt..\n  F7  - Chat Flag aendern(ob man dich rufen kann, oder nicht)\n  F8  - Serial in on/off (User kann nicht schreiben, bist du wieder F8 drueckst)\n  F9  - Serial out on/off (User kann nicht sehen, was du tippst)\n  F10 - Keyboard out on/off (Schmeisst den online-User hinaus)\n\n  Jetzt folgen normale reaktionen von \X wenn etwas passiert, wenn das BBS im\n  standby mode ist und die nodes auf\n  "Awaiting Connect" stehen.\n\n  (1). Das BBS checkt auf F-tasten eingabe vom keyboard..\n\n  (2). Oder daten , die vom serialport kommen.\n\n  (3). Oder daten vom interenen AmiExpress_Node(x) msgport, also\n       commands wie suspend, resume, oder shutdown.\n\n  (4). oder daten kommend vom AmiExpress window selbst (Gadgets etc..)\n\n  (5). oder daten kommend von AmiExpress Control.(ACP)\n\n       Wenn das modem ein RING DETECT leifert, sendet das BBS einen Antwortstring\n       , wie er in der config steht zum modem und warted auf eine Antwort des\n       modems-Wenn das ergebnis ein gueltiger connect-string ist,geht das BBS\n       weiter, andernfalls reset-ed es das modem und ACP meldet wieder\n       "Awaiting Connect".\n\n       Wenn der connectstring gueltig ist, prueft \X einige Dinge bevor es\n       mit dem logon losgeht.:\n\n  (1). Es sucht nach einem file namens:\n       BBS:NODE{x}/NOCALLERSAT{BAUD} wobei x die node nummer ist\n       BAUD,die baudrate, die nicht akzeptiert wird.Wenn dieser file\n       existiert,und die baudrate mit der des files ubereinstimmt, wird\n       der file ausgegeben und aufgelegt..\n\n  (2). Der connect string des modems wird angezeigt.\n\n  (3). Das BBS zeigt eine standart begruessungsmitteilung.\n       und started mit der logon-prozedur..\n\n  (4). Es schaut nach ob es ein module names FRONTEND gibt, das dann\n       ausgefuehrt wird.(door-section fuer mehr infos).\n       Explanation:\n       Um das FRONTEND module zu instalieren, muss es ein ICON in\n       BBS:COMMANDS/SYSCMD geben,namens "FRONTEND"\n\n  (5). BBS prueft,ob es ein module "ANSI" im SYSCMD dir gibt, das dann\n       gestarted wird, wobei die Abfrage nach ANSI/ASCII uebersprungen wird.\n       Siehe nach punkt (4) fuer mehr infos, wie man diese doors instaliert.\n\n       Wenn das BBS kein door finden kann, fragt es den user, ob er ANSI will,\n       oder nicht. Wenn ein ''Q'' am ende der Zeile steht, wie\n       "YES Q" or "Y Q" etc., dann schau das BBS ob die option\n       DISABLE_QUICK_LOGONS an ist.Falls an, wird dem User der Logon.txt gezeigt\n       weil es die user sehen muessen.Wenn die option aus ist und der user\n       antworted mit "Y Q" oder "YES Q" ,zeigt das BBS nicht die\n       LOGON oder logoff screens.\n\n  (6). Wenn der sysop ein SYSTEM PASSWORD eingestellt hat,wird der file\n       BBS:NODE<x>/PRIVATE.TXT gezeigt, dann wird nach dem passwort gefragt.\n       Der user hat 3 versuche, dannach haengt das auf und zeigt im\n       CallersLog, dass jemand versucht hat, das password zu bekommen.\n\n\n\n  (7). Das BBS zeigt den file: BBS:NODE{x}/BBSTITLE.TXT\n\n  (8). Der user soll nun seinen FULL NAME eingeben. WILDCARDS sind moeglich,\n       sie werden erweitert und der user kann bestaetigen.Der user bekommt\n       5 versuche seinen usernamen einzugeben, dann wird aufgehaengt.\n\n  (9). Wenn das BBS seinen namen nicht findet,fragt es den user ,ob es\n       ''C''ontinue (weiterverfahren) to join oder\n       ''R''etry , er kann seinen namen nochmals eingeben.\n\n   [C]ontinue hat ein neuer user angewaehlt..:\n   ----------------------------------\n\n      (1). Wenn das BBS reserviert wurde, wird der user verstaendigt\n           , dann wird aufgehaengt.\n\n\n      (2). Wenn das BBS nicht reserviert ist, prueft es, ob die Baudrate des users\n           erlaubt zu dieser Zeit erlaubt ist. Wenn das passt, darf der user weiter-\n           machen, andernfalls bekommt er den file\n           BBS:NODE{x}/NOTTIME{BAUD}.TXT gezeigt.\n                 {x} = Node number, {BAUD} = Current Baud rate.\n\n      (3). Wenn der sysop ein new user passwort im configfile angegeben hat,\n           zeigt das BBS den file:\n           BBS:NODE{x}/NEWUSERPW.TXT\n           Dann fragt s nach dem new user password.Wenn es der user nicht weiss,\n           geht es zurueck und fraegt wieder nach dem FULL NAME, nach 5retries\n           legt es dann auf.\n\n      (4). Wenn der sysop keine weiteren neuen user haben will,such das BBS den\n           file BBS:NODE{x}/NONEWUSERS und zeigt ihn, bevor es auflegt.\n           Wenn du keine weiteren neuen user mit einer bestimmten\n           BAUD RATES, willst, such das BBS den file\n           BBS:NODE{x}/NONEWAT{BAUD}, zeigt ihn,und legt auf.\n\n                  {x} = Node number, {BAUD} = Current Baud rate.\n\n      (5). Jetzt kommt die New Account routine.\n\n            1. Es sucht nach  BBS:NODE{x}/JOIN.TXT\n\n            2. Es fragt nach dem FULL NAME.Keine Wildcards sind hier erlaubt.\n               Der user hat 5 versuche ihn einzugeben, schlaegt das fehlt,\n               heisst es "Too Many Errors, Good-bye!"\n\n            3. Das BBS sucht, ob dieser name schon existiert.,falls ja\n               fragt es nochmal.\n\n            4. Das BBS sucht, ob der name nicht in der liste verbotener\n               namen steht, die im icon BBS:NAMESNOTALLOWED steht.\n               Dort sind namen aufgefuehrt, die der sysop nicht verwendet haben\n               will.Existier der file nicht, kann kein neuer user addiert werden,\n               bis der file wieder vorhanden ist.\n               Das verhindert, dass einer sich ALL,EALL,etc. nennt.\n               Ein Hinweis wird in den\n               BBS:NODE{x}/CALLERSLOG file gesetzt.\n\n    WARNING: Man sollte in dieser Liste Sysop,All,EALL eingeben.L\n\n            5. BBS fraegt nun nach Stadt und Strasse\n\n            6. "                   der Telefonnummer\n\n            7. "                   dem userpasswort\n\n            8. Anzahl der zeilen auf dem screen (1-255)\n\n            9. Ob der Screen geloscht wird, zwischen messages.\n\n           10. Welchen screentype der user wuescht.\n\n           11. Zeigt alle einstellungen und fragt nach bestaetigung.\n               Wenn der user etwas aendern will, mus er "no sagen.\n               und der prozess geht von vorne los....\n\n           12. Jetzt sucht das BBS, ob ein scriptmodule vorhanden ist,\n               im SYSCMD Directory.Falls vorhanden started es dieses anstelle\n               der normalen frage-script. Wenn es keinen file gibt, started\n               die normale frage-script, die der user ausfuellen muss.\n               Es such in diesem Fall nach:\n               BBS:NODE{x}/SCRIPT{BAUD}\n                  {x} = Node number, {BAUD} = Current Baud rate.\n\n            NOTE: Das {BAUD} sollte 1200,2400,4800,\n                  9600, 12000, 14400 and 16800 enthalten um keine Probleme\n                  mit HST modems zu bekommen. (Anm.: 28800 nicht vergessen !)\n\n               Wenn es diese script gibt, muss sie der user jetz ausfuellen\n               hier eine beispiel-script:\n\n                    -------------Cut Here--------------------\n\n                    What is your Real Name: ~\n                    What is your Real #   : ~\n                    What is your Sex,Age  : ~\n\n                    -------------Cut here--------------------\n\n               Das  ~ Zeichen bedeuted, dass eine Eingabe vom user\n               kommen soll.Die Antworten werden gespeichert in\n               BBS:NODE{x}/TEMPANS bevor es vom sysop ueberprueft werden kann.\n               Wenn der sysop den user geprueft hat, werden die antworten nach\n               BBS:NODE{x}/Answers kopiert.\n\n         13. Das BBS zeigt jetzt den Text BBS:NODE{x}/JOINED.TXT\n\n     (10). Wenn das system einen user account geladen hat, prueft es, ob das\n           system reserviert wurde.Falls es so ist und der user mit dem reservierten\n           luser nicht uebereinstimmt, meldet das BBS dies un haengt auf.\n\n\n     (11). Das BBS zeigt jetzt den BBS:NODE{x}/LOGON.TXT, wobei\n           x fuer die node steht..\n\n     (12). Wenn das BBS nicht reserviert ist, prueft es die baudrate des users\n           ,ob sie erlaubt ist-zu dieser zeit..\n           Wenn das passt, geht es weiter, andernfalls sieht der user noch\n           BBS:NODE{x}/NOTTIME{BAUD}.TXT und es wird aufgehaengt.\n\n     (13). Wenn der Security level des users 0 ist, zeigt das BBS\n           BBS:NODE{x}/LOCKOUT-0.TXT und legt auf.\n\n     (14). Wenn der Security level 1 ist, zeigt das BBS den file\n           BBS:NODE{x}/LOCKOUT-1.TXT und legt auf.\n\n     NOTE: Diese beiden files erlauben es dem sysop einen user hoeflich\n           darauf hinzuweisen.Oder eben mehr mit deutlichen worten, wenn\n           der user seinen ausschluss durch missbrauch verursacht hat.0 und 1\n           je nach user.\n\n     (15). Das system notiert, dass ein user gekommen ist in\n           BBS:NODE{x}/CALLERSLOG .\n\n     (16). Jetzt fragt das BBS den user nach dem passwort.Wenn er etwas falsches tippt\n           so schreibt das bbs den fehlversuch nach\n           BBS:NODE{x}/CALLERSLOG. Nach 3 versuchen wird aufgelegt und dies\n           notiert im CALLERSLOG.\n\n     (17). Dann findet die stadart LOGON sequence statt und gibt dem user den\n           main command prompt.\n\n  LOGON SEQUENCE FÜR EINEN BESTEHENDEN USER:\n  -----------------------------------\n\n   Wenn ein user mit bestehenden account einlogt, ist die LOGON\n  procedure viel einfacher.Hier eine Liste:\n\n\n   (1). Das BBS prueft, ob der user fuer diesen Tag noch Zeit besitzt,falls nicht\n        zeigt es BBS:NODE{x}/LOGON24HRS.txt und legt auf.\n\n\n   (2). Wenn keine BULLBATCH files angegeben sind, sucht das BBS nach\n        Bulletin files in BBS:NODE{x}/BULL{SEC}.TXT , wobei\n        {x} = NODE NUMBER and {SEC} = USERS CURRENT SECURITY LEVEL.\n        Ist ein passender file gefunden, der zum level des users passt,\n        wird er angezeigt.z.B Das "last callers bulletin für einen standart user\n        mit level 20 wuerde nach BBS:NODE{x} geschrieben werden und sieht wie\n        BBS:NODE{x}/BULL20.TXT aus.\n        BBS:NODE{x}/BULL20.TXT. Diese funktion wurde vereinfacht von seiten des sysops\n        , so dass in Frage kommende bulletins in gekuerzter Weise durchsucht werden.\n\n     ie: Wenn ein user mit level 20 eingelogt ist und das BBS keinen eintrag\n         fuer\nBBS:NODE{x}/BULL20.TXT findet, aber es findet einen file namens\n         BBS:NODE{x}/BULL15.TXT, so wird dieser file gezeigt.\n         Gibt es einen file namens\n         BBS:NODE{x}/BULL30.TXT, so wird er usern mit level 30 und hoeher\n         gezeigt.Wenn das BBS den naheliegensten file gefunden hat, zeigt es\n         nur diesen.\n\n      NOTE: Neue funktionen in AmiExpress machen dem sysop den setup einfacher\n            und weniger nervig fuer die user.Das BBS sucht nach einem bestimmten\n            file in diesem schema.:\n\n      Ein user mit level 30 loged ein,mit ANSI Farben.Das BBS sucht nach einem\n      BULL30.TXT ,gibt es den nicht, sucht es in den bulls unter 30 weiter.\n\n\n     Look here:\n\n      BBS:NODE{x}/BULL30.TXT\n      BBS:NODE{x}/BULL25.TXT\n      BBS:NODE{x}/BULL20.TXT\n      BBS:NODE{x}/BULL15.TXT\n      BBS:NODE{x}/BULL10.TXT\n      BBS:NODE{x}/BULL5.TXT\n      BBS:NODE{x}/BULL.TXT\n\n   NOTE: wegen dieser Methode muessen alle files auf 0 oder 5\n         enden.Der userlevel wird immer auf das naechste vielfache\n         von 5 abgerundet.\n\n       Hier eine suche nach einem file, der gezeigt werden soll.Wenn er\n       gefunden ist, wird nur dieser FILE gezeigt..\n     Die Methode wird im folgenden verwendet.\n\n       BBS:NODE{x}/BULL\n       BBS:NODE{x}/JOINCONF\n       BBS:CONF/MENU\n       BBS:CONF/BULL\n\n       In manchen faellen laeuft es etwas anders, hier wird das\n       userlevel nicht verwendet:\n\n       BBS:CONF/Bulletins/BULLHELP.TXT\n       BBS:CONF/Bulletins/BULLHELP.TXT\n\n       So geht das einen und so ist dieses::\n\n       BBS:NODE{x}/JOINED\n       BBS:NODE{x}/LOGON24HRS\n       BBS:NODE{x}/GUESTLOGON\n       BBS:NODE{x}/LOGON\n       BBS:NODE{x}/LOGOFF\n       BBS:NODE{x}/JOIN\n       BBS:NODE{x}/NOTTIMEBAUD\n       BBS:NODE{x}/PRIVATE\n       BBS:CONF/FILEHELP\n\n    NOTE: Fuer mehrere bulletins beim LOGON, wird eine BULLBATCH script benutzt\n          um die noetigen bulletins in correkter Reihenfolge zu zeigen.\n          Mehr infos dazu in der section BULLBATCH implementierung.\n\n\n\n   (3). Erste User spezifische checks werden gemacht.\n\n     a> Das BBS scant alle conferences zu denen der user zugang hat und es sucht\n        nach wartender mail.Waehrend dem suchen speichert \X die MSG nummern im\n        speicher, bis zum ende des scans.Es zeigt dann dem user den absender jeder\n        message und fraegt ihn , ob er die mail lesen moechte.\n\n\n        Diese suchmethode hat 3 vorteile::\n\n  1. Der user weiss vorher, wer geshcrieben ha, bevor er es lesen muss.\n  2. Der NewMail Scan pointer wird nicht updated bis alle mail gelsen ist.\n     Wenn der user 2 messages ''100'' und ''101'' hat, und er liesst\n     101 aber nicht 100, dann wird beim naechsten LOGON oder beim mailscan\n     darauf hingewiesen, dass es noch nummer 100 gibt..\n  3. Der NewMailScan erinnert sich an die letzte gueltige message an den\n     user, wenn der carrier verloren geht oder er auslogt.\n\n        Wenn mail gefunden ist, wird der user informiert\n        und gefragt, ob es sie sehen will.\n\n\n     b> Das BBS sucht nach unvollstaendigen uploads. Wenn jemand den\n        carrier verliert waehrend dem upload und nochmals anruft, darf er\n        den upload vervollstaendigen.\n\n   (4). Das BBS geht in die conference, in der der user zuletzt war.\n\n\n   (5). Es prueft das ICON BBS:CONF um zu sehen, ob und wieviele\n        directories von files diese conference hat.\n        Es sucht, wenn im ICON das NDIRS groesser  0 ist.\n\n        for example:\n        ~~~~~~~~~~~  NDIRS=2\n\n        Das gibt an, dass es 2 filedirectories gibt und wo die files sind.\n        Ein carriage return ist noetig nach der zahl.\n\n        Wenn es diesen file nicht gibt,hat die conference keine files verfuegbar.\n        Also keine uploads & downlods sind moeglich.\n\n\n   (6). Wenn die Anzahl der directoreis groesser 0 ist, prueft das BBS, ob im\n        CONF ICON der Tooltype "FREEDOWNLOADS" gesetzt ist.\n        Falls so, sind alle files dieser conference fuer free download verfuegbar.\n\n\n   (7). Nun sucht das BBS nach BBS:CONF/BULL{SEC}.TXT files in der gleichen\n        Methode , wie sie shcon erwaehnt wurde..\n\n      NOTE: Das laeuft genauso wie bei BBS:NODE{x}/BULL files.\n\n   (8). Nach dem Zeigen der verfuegbaren bulletins, und der user nicht im expertmode\n        ist, zeigt das BBS die verfuegbaren\n        BBS:CONF/MENU{SEC}.TXT und zeigt den  MAIN MENU PROMPT.\n\n      a> Jedes command im MAIN MENU PROMPT wird im\n         BBS:Commands/BBSCmd directory gesucht. Wenn es gefunden wird, als\n         ein module in diesem dierectory, so wird es ausgefuehrt.\n         Wenn das command nicht gefunden wird,wird es verglichen mit\n         BBS:Commands/NODE{x}CMD directory und auf gleiche Art ausgefuehrt,wenn\n         vorhanden Wenn es nicht gefunden wird, wird es mit\n         BBS:Commands/CONF{x}CMD directory verglichen und beim auffinden ausgefuert.\n         .\n         Sonst wird angenommen, dass es ein internes command ist\n         und vielleicht eines  der jetzt aufgefuehren commands.\n  =======================================================================\n@endnode\n@node Cap10 "The MainMenu Commands of AmiExpress"\n  =======================================================================\n     hier ein liste verfuegbarer befehle im main menu prompt:\n     ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n  AmiExpress hat viele funktionen, die teil des programmcodes sind. Sie helfen\n  user, bei dem was sie vom system wollen. Diese commands sind haeufig einzelne\n  buchstaben, die der user mit return abschliesst.\n  AmiExpress laeuft nicht mit einem HOT-KEY tippen des users.\n  Das heisst, dass der user nicht lauter dinge ansehen muss, die er nicht wollte,\n  nur weil er die falsche taste getippt hat..\n  Ein Return zeigt an, dass die ausfuehrung gewollt ist.\n\n  Diese section ist unterteilt in 2 teile,die SYSOP ONLY COMMANDS, und die\n  Standard User Commands.\n\n    @{" SYSOP Only Main Commands     " Link Cap1001}    @{" STANDARD USER Main Commands  " Link Cap1002}\n\n  =======================================================================\n@endnode\n@node Cap1001 "SYSOP Only Commands....."\n  =======================================================================\n                           SYSOP ONLY COMMANDS:\n                           ~~~~~~~~~~~~~~~~~~~\n  Diese commands werden mit einziffrigen nummerncodes aktiviert.Sie sind nur\n  dem sysop zugaenglich, mit sysop level, wie es im\n  Config file bei AmiConfig under ACCOUNT EDITING steht.\n\n    @{" Command: ''1'' <AccountEditing>" Link Cap100101}    @{" Command: ''2'' <CallerslogView>" Link Cap100102}\n    @{" Command: ''3'' <Edit File Dirs>" Link Cap100103}    @{" Command: ''4'' <Edit Text File>" Link Cap100104}\n    @{" Command: ''5'' <View Directory>" Link Cap100105}    @{" Command: ''0'' < Remote Shell >" Link Cap100106}\n    @{" Command: ''DS''<Sysop Download>" Link Cap100107}    @{" Command: ''VS''<  Sysop View  >" Link Cap100108}\n\n  =======================================================================\n@endnode\n@node Cap100101 "[ 1 ] - Account Editing...."\n  =======================================================================\n  [ 1 ] - Account Editing:\n          ~~~~~~~~~~~~~~~\n    Dies wird verwendet um existiernde account zu sehenund zu aendern, oder\n    umnach neuen user LOGONS zu suchen, die geprueft werden wollen.Das account\n    editing module ist sehr einfach zu bedienen, das es komplett menugesteuert ist.\n    Man kann auch in den file BBSInfo CONF. file gehen.\n    Bevor Express das normale Account Editing started, versucht es\n    ein module namens "ACCOUNTS" im SYSCMS dir zu oeffnen.Dies ist fuer\n    noch kommende Account editoren.\n\n\n    Das AccountEditing sieht so aus:\n\n--------------------------------------------------------------------------------\n  ACTIVE [1]   BAUD: 14400\nA> Name: ByteMaster                      B> Location ......: Location\nC> Pass ..........: ENCRYPTED\nD> Phone Number ..: 318-793-4101   F> Area Name......: Standard\nE> Ratio .........: 0              H> Sec_Level .....: 255\nG> Ratio Type ....: 0     <-Byte)  J> AutoReJoin ....: 1\nI> Uploads .......: 0              L> Messages_Posted: 0\nK> Downloads .....: 0              N> New_User ......: No  #Calls: 1\nM> Bytes Uled ....: 1                 Last Called ...: Tue May 26 22:00:17 1994\nO> Bytes Dled ....: 0                 Computer Type .: Amiga 1000\nQ> Byte Limit ....: 0                 Screen Type ...: Amiga Ansi\nP> Time_Total: [0       ] mins     Y> Cps Up: 0         Z> Cps DN: 0\nR> Time_Limit: [0       ] mins     S> Time_Used: [0       ] mins  T> UUCP: 0\nU> Chat_Limit: [0       ] mins     V> Chat_Used: [0       ] mins\n\nX=EXIT-NOSAVE ~=SAVE  1-8=Presets  9=RE-ACTIVATE  DEL=DELETE\nTAB=CONT @=CONFERENCE ACCOUNTING !=CREDIT ACCOUNT MAINTENANCE\n--------------------------------------------------------------------------------\n\n  Druecke folgende tasten um die userdata zu aendern\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n  A> aendert den namen dieses users.\n  B> aendert seinen wohnort\n  C> aendert sein passwort\n  D> aendert seine telefonnummer\n  E> aendert sein ratio\n  F> hier kann man den Conf.Access des users aendern\n  G> aendert den ratiotype dieses users, es gibt hier 3 typen davon:\n\n                            - Ratio Type 0 = Bytes only\n                            - Ratio Type 1 = Bytes & Files\n                            - Ratio Type 2 = Files only\n\n     Diese ratiotypen bestimmen, wie das ratio berechnet wird.\n\n  H> aendert das Security Level dieses users.\n  I> aendert die anzahl der uploads, die dieser user gemacht hat.\n  J> aendert die conference, in der der user zuletzt war.\n\n  K> aendert die anzahl der downloads dieses users.\n  L> aendert die anzhal der Messages die der user im BBS geschrieben hat.\n  M> aendert die anzahl der byte, die dieser user upgeloaded hat.\n  N> laesst veraendern, ob der user NEW USER ist oder nicht.Wenn diese Flag-\n     function auf "YES" steht, wird die userdata nicht gefunden wenn man nach\n     neuen usern sucht.Wenn man die USERDATA mit gegebenen flag editiert,wird\n     es automatisch zu  "NO".\n  O> aendert die anzahl der Bytes die der user downgeloaded hat.\n  P> aendert die gesammte zeit fuer pro tag..\n  Q> aendert die anzhal byte, die downgeloaded werden kann pro tag.\n  R> aendert das Zeitlimit pro tag..\n  S> aendert die heute bereits verbauchte zeit..\n  T> aendert ob der user UUCP verwendet oder nicht..\n  U> aendert das chat-limit des users..\n  V> aendert das chat-limit, das heute verbraucht wurde.\n  Y> aendert die Top Upload CPS des users.\n  Z> aendert die Top Download CPS\n  #> aendert die anzahl der anrufe des users an dieses system.\n\n  nun folgende commands fuer`s Account Editing:\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n  [ X ]   - Exit das Account editing ohne abzuspeichern\n  [ TAB ] - geht zum naechten user, der nach dem USERNAME der jetzigen\n            Users kommt.\n  [ ~ ]   - speichert die changes der USERDATA.\n  [ 1-8 ] - setzt USERDATA auf eine Voreinstellung aus ACP.STARTUP\n  [ 9 ]   - re-aktiviert geloeschte user\n  [ DEL ] - loescht diesen user.\n            man kann ihn mit "9" wiederbeleben.\n  [ + ]   - geht zum naechten user in USERDATA.\n  [ - ]   - geht zum vorherigen user in USERDATA.\n  [ ! ]   - Aktiviert ACCOUNT CREDIT MAINTENANCE.  Diese Sache erlaubt es\n            zahlende user zu ueberwachen. Die Annahme ist, dass ein user der zahlt\n            ein disabled ratio hat. CREDIT MAINTENANCE laesst die Anzahl von Tagen\n            festsetzen, die das gilt. Waehrend dieser Zeit bekommt der User kein\n            eigentliches  DISABLED ratio.Seine  ratio aendert sich nicht, aber\n            express handhabt seinen account, als ob er disabled waere.\n            Waehrend der Zahlungsperiode zeigt ''FS'' oder "S" ein DISABLED\n            ratio.Wenn die Zahlungsperiode auslaeuft, tritt das alte Ratio in\n            Kraft.\n\n  [ @ ]   - Bringt dich zum  Conference Accounting. Man MUSS ! conference\n            accounting haben, damit es funktioniert.Hier sieht man dann\n            jede conference ,screen by screen, dort kann dann die\n            user''s STATS für jede conference editieren.Man kann von\n            conference to conference gehen, mit den +/- keys. Folge den screens\n            fuer save und exit.\n  =======================================================================\n@endnode\n@node Cap100102 "[ 2 ] - View CallersLog...."\n  =======================================================================\n  [ 2 ] - View CallersLog:\n          ~~~~~~~~~~~~~~~\n    Das laesst den sysop den file BBS:NODE{x}/CALLERSLOG rueckwaerts sehen.\n    Die letzte Zeile im CALLERSLOG wird zuerst angezeigt, die erste Zeile\n    zuletzt.Auf systemen mit mehreren nodes wird gefragt, fuer welche node\n    das CALLERSLOG gezeigt werden soll.\n  =======================================================================\n@endnode\n@node Cap100103 "[ 3 ] - Edit File Directories (EDITOR/EMACS)...."\n  =======================================================================\n  [ 3 ] - Edit File Directories (EDITOR/EMACS):\n          ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n    Beim starten dieses Commands ob die startende person remote oder local\n    ist.Ist er lokal, wird nach einem door "EDITOR" im SYSCMD gesucht, der,wenn\n    vorhanden ausgefuert und das ueblich starten des EMACS entfaellt.\n\n    Wenn die person im REMOTE_LOGON ist, wird das command so ausgefuehrt:\n\n    Das command benuetzt die CLI version von MicroEmacs fuer on-line\n    directory editing.  Wie man EMACS bedient, steht in der section\n    COMMON EMACS COMMANDS.\n    Dieses command welches dir er editieren will, bevor er den entsprecheden\n    AUX: or CNN: kanal oeffbet und  EMACS started.\n    NOTE: AUX{x}: wird nur im remote Fall verwendet.Dann ist ein watchdog\n    ~~~~  aktiv, der Carrierverlusst ueberprueft..\n          Geht der carrier waehrend dem editieren verloren, wird der computer\n          inerhalb von 2 sec reset-ed..\n          Anmerkung zu MULTI NODE systems: Der watchdog reset-ed den computer\n          bei carrierverlusst, unabhaengig , was die anderen nodes machen.\n          Wenn user in anderen nodes sind, werden sie rausgeschmissen,wenn\n          der computer reset-ed.In zukuenftigen versionen von \X wird eine\n          Benachrichtigung den anderen nodes zugeschickt und ein\n          time-out requestor informiert den sysop und die user, dass \X\n          reset-en will und jeder zum Ende kommen sollte.\n\n\n    Ein Exit aus EMACS mit  CTRL-X CTRL-C key combination bringt den user\n    zurueck zum MAIN MENU PROMPT.  Wenn ein user in EMACS ist, sagt das \X\n    dem sysop mit einer zeile, wie:\n    User in EMACS........\n\n    WARNING! Benutzer der A2232 koennten probleme beim editor\n             bekommen.Wir arbeiten an einem Fullscreen-editor\n             als ersatz.\n\n  =======================================================================\n@endnode\n@node Cap100104 "[ 4 ] - Edit eines Text File im System (EDITOR/EMACS)...."\n  =======================================================================\n  [ 4 ] - Edit any Text File on System (EDITOR/EMACS):\n          ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n    Dieses command ist das selbe wie vorher, mit der option einen vollen\n    pfad und filenamen zum editieren einzugeben.Das command fraegt nach den\n    noetigen informationen.\n  =======================================================================\n@endnode\n@node Cap100105 "[ 5 ] - List System Directories...."\n  =======================================================================\n  [ 5 ] - List System Directories:\n          ~~~~~~~~~~~~~~~~~~~~~~~\n    Das command ist wie das Amigados List command und zeigt die im gegebenen\n    pfad befindlichen sub-directories und dirs.Es kann ausserdem\n    FILENOTES, die an den file haengen anzeigen..\n    Wenn man es aufruft, fraegt \X nach dem vollen pfad und ob comments\n    gewuenshct sind, oder nicht..\n  =======================================================================\n@endnode\n@node Cap100106 "[ 0 ] - Remote Shell...."\n  =======================================================================\n  [ 0 ] - Remote Shell:\n          ~~~~~~~~~~~~\n    Dieses command fehlt in dieser version von \X.Es gibt gute doors die\n    es ersetzen koennen.Ich persoenlich empfehle das\n    MALTESE FALCON .Wer es benutzt sollte wissen, dass das spy (spion)\n    command nicht laeuft auf dieser version von \x, es konnte nur 9 nodes\n    verkraften...Express kann bsi zu 32 nodes, also disable dieses command\n    in der config, sonst installiere als alsnormales door ins BBSCMD dir\n    und waehle den 0 button dafuer an.\n\n  =======================================================================\n@endnode\n@node Cap100107 "[ DS ] - Sysop Download...."\n  =======================================================================\n  [ DS ] - Sysop Download:\n           ~~~~~~~~~~~~~~\n    Es ist das gleiche command wie der user download, aber es erlaubt\n    files aus jedem pfad downzuloaden. Die Suchfunktion mit\n    WILDCARD wurde entfernt um fehler zu vermeiden.\n\n    Alle files koennen so downgeloaded werden, es sei dennn, sie sind\n    RESTRICTED (gesperrt)zum downloading , was mit einem filecomment von\n    "RESTRICTED" geschieht.Damit schuetzt man files, die auch der Cosysop\n    nicht downloaden koennen soll..\n  =======================================================================\n@endnode\n@node Cap100108 "[ VS ] - Sysop Text View...."\n  =======================================================================\n  [ VS ] - Sysop Text View:\n           ~~~~~~~~~~~~~~~\n    Commando wie das normale User Text View command, mit der faehigkeit\n    dass der sysop files aus jedem pfad der harddisk nehmen kann.Alle files\n    koennen gelesen werden, bis auf die files mit "RESTRICTED" comment.\n    Das verhinter, dass user deine privaten sachen lesen.\n\n  =======================================================================\n@endnode\n@node Cap1002 "REGULAR USER Commands...."\n  =======================================================================\n                          REGULAR USER COMMANDS:\n                          ~~~~~~~~~~~~~~~~~~~~~\n  Alle commands werden noch genau erklaert. Alle commands koennen in den\n  ACCESS ICONS von EXPRESS gewaehlt werden.\n\n    @{" [<][>].....Fast Conf.joining " Link Cap100201}    @{" [ A ].......Alter File Flags " Link Cap100202}\n    @{" [ B ]......Bulletins reading " Link Cap100203}    @{" [ C ].......Comment to Sysop " Link Cap100204}\n    @{" [ D ].......Download File(s) " Link Cap100205}    @{" [ E ]..........Enter Message " Link Cap100206}\n    @{" [ F ]..........File Listings " Link Cap100207}    @{" [ FS ]......Full Status View " Link Cap100208}\n    @{" [ G ]........GoodBye(LOGOFF) " Link Cap100209}    @{" [ H ]..............Help Page " Link Cap100210}\n    @{" [ J ]........Join Conference " Link Cap100211}    @{" [ M ]......(COLOR/MONO) Mode " Link Cap100212}\n    @{" [ RZ].....Zmodem Upload      " Link Cap100213}    @{" [ ^ ]..Extended Help Command " Link Cap100214}\n    @{" [ N ]...New Files Since Date " Link Cap100215}    @{" [ O ]..........Operator Page " Link Cap100216}\n    @{" [ Q ].............Quiet Node " Link Cap100217}    @{" [ R ]..............Read Mail " Link Cap100218}\n    @{" [ RL ]...............ReLogon " Link Cap100219}    @{" [ S ].Status of On-Line User " Link Cap100220}\n    @{" [ T ]...................Time " Link Cap100221}    @{" [ U ].........Upload File(s) " Link Cap100222}\n    @{" [ V ].......View a Text File " Link Cap100223}    @{" [ W ]..Write User Parameters " Link Cap100224}\n    @{" [ WHO ].....Node Information " Link Cap100225}    @{" [ X ].....Expert Mode Toggle " Link Cap100226}\n    @{" [ Z ]......Zippy Text Search " Link Cap100227}    @{" [ ZOOM ].........Zoo Mailing " Link Cap100228}\n    @{" [ CF ].Set Conference Config " Link Cap100229}    @{" [ VO ]..........Voting Booth " Link Cap100230}\n\n  =======================================================================\n@endnode\n@node Cap100201 "[<][>] Fast Conference Joining Command"\n  =======================================================================\n  [ < ] - Joining Conference Up&Down:\n  [ > ]   ~~~~~~~~~~~~~~~~~~~~~~~~~~\n    Diese 2 commands erlauben es dem user conferences allein durch\n    die ''<'' ''>'' keys zu joinen..Es laesst den user eine conference hoch und runter\n    gehen.z.B:User ist in conf 3 und nimmt ''>'' key.\n    also kommt er eine conference hoeher, zu der er zugriff hat, und mit\n    ''<'' key kommt er zurueck nach conf 3..\n  =======================================================================\n@endnode\n@node Cap100202 "[ A ] - Alter File Flagging...."\n  =======================================================================\n  [ A ] - Alter File Flags:\n          ~~~~~~~~~~~~~~~~\n    Das command erlaubt es dem user die flagged (markierte) file list zu aendern\n    ,ohne ein filelisting und ohne an den PAUSE...MORE zu leiden.\n\n    Verknuefungen der daten sind zugelassen, ode das BBS fragt den user\n    nach fehlender information.\n\n    Zuerst sieht man die momentane liste der flags.\n\n    Kein file flag\n    Filename(s) to flag: (C)lear, (Enter)=none?\n\n    Hier kann man anwaehlen::\n     1. Neuen file auf die markierungliste setzen\n     2. Enter ''C'' um zum flag loeschen zu gehen.\n\n    Filename(s) to Clear: (*)All, (Enter)=none?\n\n    Hier kann man::\n     1. Filenamen eingeben, der von der flag liste soll\n        WILDCARDS sind gueltig, dennoch entfernen sie nur den\n        ersten eintrag.\n     2. ''*'' um alle eintraeg eder liste zu entfernen.\n     3. Return fuer exit.\n\n    Wenn ein user den Clear prompt verlaesst, sieht er noch mal\n    die liste der markeirten files und geht dann zum\n    MAIN MENU PROMPT.\n  =======================================================================\n@endnode\n@node Cap100203 "[ B ] - Bulletins reading...."\n  =======================================================================\n  [ B ] - Bulletins:\n          ~~~~~~~~~\n    Dieses command leasst den user bulletins sehen, die der sysop verfuegbar\n    gemacht hat..\n    - Zuerst sucht das BBS nach dem file\n      BBS:<CONF>/BULLETINS/BULLHELP.TXT .Gibt es ihn nicht, sagt es dem user,\n      dass keine bulletins verfuegbar sind in dieser conference.\n    - Wenn BBS:<CONF>/BULLETINS/BULLHELP.TXT gefunden wird, wird es angezeigt\n      und der user kann im bulletin # zum lesen oder  ''?'' fuer den\n      BULLHELP.TXT (das bulletin menu) anwaehlen.\n    - Wenn ein user ein gueltiges bulletin # waehlt, wird es angezeigt und das\n      BBS geht zurueck zum bulletin prompt.\n    - Waehlt ein user ein ungueltiges bulletin #,informiert das BBS den user\n      dass ein kein bulletin #{x} gibt, wobei {x} = nummer des bulletins\n  =======================================================================\n@endnode\n@node Cap100204 "[ C ] - Comment to Sysop...."\n  =======================================================================\n  [ C ] - Comment to Sysop:\n          ~~~~~~~~~~~~~~~~\n    Das command ist das gleiche wie das ENTER MESSAGE command, nur dass die\n    message privat zum sysop geht. Im TO: Feld steht automatisch der username\n    von SLOT 1 , das ist der sysop.\n.\n    Entdeckt das BBS den tooltype "FORWARDMAIL= <str>" der im Conference\n    ICON auf "on" steht, wird die mail weitergeleited an einen user, der in\n    <str> steht. Das ist nuetzlich, wenn man in urlaub faehrt und man moechte, dass\n    der cosysop die mails an dich lesen kann, ohne immer"R" zum lesen\n    der messages tippen zu muessen.\n  =======================================================================\n@endnode\n@node Cap100205 "[ D ] - Download File(s)...."\n  =======================================================================\n  [ D ] - Download File(s):\n          ~~~~~~~~~~~~~~~~\n    Das command bedient den transfer um files vom system zum user zu schicken.\n    Der Ablauf dieses commands ist recht komplex und steht unten:\n\n\n    1. Wenn der tooltype NDIRS null ist, informiert das BBS den user, dass\n       es keine files zum download in dieser conference gibt.\n\n    2. Das BBS zeigt den  File BBS:CONF/DOWNLOADMSG.TXT\n\n    3. Das BBS zeigt die user Download/Upload STATS.\n\n    4. Das BBS rechnet mit dem ratio die limits aus, bevor der user den\n       upload beginnt..\n\n    5. Es zeigt das transfer protokol, das der user als standart hat..\n       Der user kann dieses aendern mittels  "W" command.\n\n    6. Wenn der user "DS" anstelle von S" waehlt, handelt es sich um einen\n       sysopdownload und wenn der user erlaubt ist, einen\n       SYSOPDOWNLOAD zu taetigen, dann kann von jedem gueltigen\n       AmigaDos path im system downgeloaded werden.Wenn das so ist, fragt das bbs\n       nach dem vollen pfad und namen. KEINE WILDCARDS sind erlaubt, beim\n       Sysop Download.\n\n    7. Das BBS fragt vom user den filename(s).\n\n    8. Es prueft auf spezielle Zeichen im filenamen, wie ":/" etc.\n       Wenn gefunden, sagt es dem user, dass diese zeichen nicht gueltig sind.\n\n\n    9. Volle WILDCARDS sind erlaubt im regulaeren download, nur der\n       * WILDCARD alleine ist verboten..\n\n   10. Jetzt durchsucht das BBS die gegebenen pfade vom CONF ICON und\n       wenn es den file findet, den der user will, zeigt es die filelaenge\n       in Kbytes, die erwartete downloadzeit bei dieser baudrate und prueft,\n       ob der user genug credits hat um den file downzuloaden.\n       Stimmt das, prueft \X ob der file bereits in der downloadliste ist,\n       wenn nicht, addiert es den file.Wenn die download-sequence abgebrochen\n       wird, kann man mit "D" die markierten files wieder downloaden.Um von\n       der flagliste zu entfernen, verwendet der user das "A" command.\n\n\n   11. Jetzt preuft das BBS, ob ein Comment wie\n       "RESTRICTED" oder "FREE DOWNLOAD" ...existiert.Falls ja zeigt das BBS\n       bei "RESTRICTED" einen Hinweis , dass der file geschuetzt ist und\n       schreibt einen comment ins BBS:NODE{x}/CALLERSLOG , dass ein user\n       diesen file downen wollte.... mit diesem comment kann man den file auch\n       nicht mit level 255 und als sysop downen..der file ist also 100% sicher\n       Wenn der comment FREE DOWNLOAD heisst, kosted das downen den user keine\n       credits...\n\n   12. Drueckt man nur return im file-promt, ueberprueft das BBS nochmal, ob\n       der batch in den limits des users liegt..\n\n   13. wenn dem so ost, fraegt \X ob start, abort, oder automatically\n       logoff am ende des transfers. Das ''G''oodbye after transfer\n       gibt dem user 10 seconds seine meinung zu aendern bevor es einen\n       automatischen logoff gibt..\n\n   14. An diesem punkt beginnt die downloadsequence, also  wird die noetige\n       information ins BBS:NODE{x}/UDLOG geschrieben, wenn es eingeschalted ist.\n\n\n   15. Am Ende des downloads, wenn des users level unter dem gewaehlten in\n       dem tooltype KEEP_UPLOAD_CREDIT=<numb>, ist, bekommt der user\n       die anzahl der downloads und die byteanzahl an seine STATS angerechnet.\n\n   16. Jetzt ist die downloadsequence fertig und das BBS zeigt dem user seine\n       STATS bevor es zum MAIN MENU PROMPT geht.\n\n\n  =======================================================================\n@endnode\n@node Cap100206 "[ E ] - Enter a Message...."\n  =======================================================================\n  [ E ] - Enter a Message:\n          ~~~~~~~~~~~~~~~\n    Das command erlaubt es dem user eine private oder oeffentlich message an\n    andere user zu schreiben. Es gibt viele options dieses commands, die jetzt\n    aufgefuehrt sind..\n\n    1. Fragt, an wen man schickt. Bei WILDCARDs findet die Suche den ersten\n       User, der passt, zeigt diesen und fraeg, ob es korrekt ist.Im Falle\n       von NEIN, geht die suche weiter.Bei erfolgloser suche geht`s zum\n       MainMenu prompt.\n\n    2. Wenn der user return tippt , wenn  TO: erscheint, danngeht die message\n       an ALL.\n\n    3. Ein feature ist, dass man auch EALL schreiben kann, womit\n       alle Leute eine EMAIL bekommen,benutzbar nur fuer leute mit\n       zugriff um EALL Messages zu schreiben.Das steht im tooltype\n       im ACCESS ICON für die User. Es generiert dann eine message fuer\n       alle user.Wenn ein user kommt und nach mail sucht, sieht er diese\n       mail, die der andere user an EALL geschrieben hat.Die\n       TO: zeigt den user, der die mail empfaengt, die message an\n       ALL setzt seinen namen ein.Die message kann nur vom sender und vom\n       sysop geloescht werden.\n\n    4. Ein gueltiges argument in TO: ist SYSOP, dieses wird ersetzt mit\n       dem namen des sysops in user slot 1.\n\n    5. Naechste ingabe ist das subject der message.Bei keinem subject\n       verlaesst \X das message menu.\n\n    6. Das BBS fragt, ob dei mesage nur lesbar fuer den empfaenger\n       ist, oder oeffentlich.\n\n    7. Wenn man den optinonalen Full-Screen editor installiert hat, fragt das\n       BBS, ob man diesen verwenden will.Der user kann den editor mit dem\n       "W" command waehlen, wenn der sysop das gestatted hat.\n\n\n    8. Jetzt ist der user im message editor, Foglende commands gehen davon aus,\n       das der interne Zeileneditor verwendet wird..\n\n    9. Tabs funktionieren im editor, sie werden als  ''|'' im header\n       gezeigt.\n\n   10. CTRL-X im message editor loescht die aktuelle zeile....\n\n   11. Return in einer Leerzeile fuerht vom editmodus zum commandmodus.\n\n   12. Commands sind.:\n\n        1. <A>bort   - Abbruch der message.\n\n        2. <C>ont    - Weitermachen mit der message.Diese option gibt die\n                       letze Zeile aus und setzt den cursor ans ende der zeile.\n\n\n        3. <D>elete  - User darf bestimmte Zeile loeschen..\n\n        4. <E>dit    - User darf eine Zeile editieren..\n\n        5. <F>ile    - User mit tooltype SYSOP_DOWNLOAD koennen einen file an\n                       die message anhaengen. Diese option fragt nahc dem filename\n                       und ob der file mit der message mitgeloescht werden soll.\n\n\n        6. <M>ci List- Wenn man einen MCI HEADER in der Message hat, kann man\n                       diese funktion verwenden.Sie zeigt den ganzen text mit allen\n                       MCI comments darin.\n\n\n        7. <L>ist    - List die message auf dem screen.\n\n        8. <S>ave    - Saved die message.\n\n        9. <X>fer    - Erlaubt usern eine file in die MSGBASE zu uppen und\n                       haengt diesen file automatisch an eine message.\n                       Damit der user das darf, muss der\n                       tooltype "ACS.PRI_MSGFILES" in seinem\n                       ACCESS ICON gesetzt sein.. Wenn diese Message an ALL oder EALL\n                       geht, muss ausserdem noch\n                       "ACS.PUB_MSGFILES" eingeschalted sein.\n  =======================================================================\n@endnode\n@node Cap100207 "[ F ] - File Listings...."\n  =======================================================================\n  [ F ] - File Listings:\n          ~~~~~~~~~~~~~\n    Dieses command ermoeglicht es dem user volle dir-listings der im BBS\n    befindlichen catalogs zu machen.Wie bereits gesagt, steht das im\n    Tooltype NDIRS=<numb> im CONF ICON.\n\n    1. Wenn die Anzahl der dirs einer conference 0 ist oder\n       NDIRS ist 0, dann zeigt das BBS\n       "No files available in this conference." und setzt den user zurueck\n       zum main prompt.\n\n    2. Zeigt den file BBS:CONF/FILEHELP.TXT nur, wenn\n       alle options nicht bereits in der command line stehen..\n\n    3. Es fragt nach dem directory, das gezeigt werden soll, einschliesslich\n       ''H''old directory. Das hold directory kann nur von usern mit\n       level ueber 200 verwendet werden..\n\n    4. Das angegebene dir wird angezeigt und es wird pausiert,\n       am ende der zeilen des users, oder gar nicht, wenn NS\n       gewaehlt ist. (NS nonstop)\n\n    5. On the pause prompt, you can select ''F'' for flagging files.\n  =======================================================================\n@endnode\n@node Cap100208 "[ FS ] - Full Status View...."\n  =======================================================================\n  [ FS ] - Full Status View:\n           ~~~~~~~~~~~~~~~~\n    Diese option gibt dem user vollen ueberblick ueber seinen\n    access status in jeder conference. Es zeigt Bytes Down/Uploaded\n    in jeder conference, wo der user zugriff hat, und zeigt auch sein ratio\n\n  =======================================================================\n@endnode\n@node Cap100209 "[ G ] - GoodBye (LOGOFF)...."\n  =======================================================================\n  [ G ] - Goodbye (LOGOFF):\n          ~~~~~~~~~~~~~~~~\n    Dies beendet die momentane sesion mit dem system .Wenn der user\n    "G" waehlt, beginnt das system mit diversen aufraeumfunktionen.\n\n\n    1. Es prueft, ob es eine ZoomMail gibt, die noch nicht dowgeloaded wurde.\n       Wenn es eine gibt, fragt es den user ob er dennoch verlassen moechte.\n\n    2. Das system sucht nun nach unvollstaendigen uploads, die der user\n       noch offen hat.Falls ja, wird der user verstandigt und gefragt,\n       ob er doch verlassen will.Will er nicht mehr verlassen, kann er diese\n       files listen lassen und den upload vervollstaendigen.Er kann\n       auch den file loeschen.Will der user all das nicht, geht das BBS\n       weiter zum naechsten unvollstaendigen file.\n\n    3. Hat der user nicht ''Q'' im ANSI color prompt eingegeben,\n       oder SUPPRESS_QLOGON ist eingestellt,\n       sieht er den file BBS:NODE{x}/LOGOFF.TXT.\n\n    4. Das BBS versucht ein module "LOGOFF" oder\n       "LOGOFF<node>"zu finden und auszufuehren.\n\n  =======================================================================\n@endnode\n@node Cap100210 "[ H ] - Help Page...."\n  =======================================================================\n  [ H ] - Help:\n          ~~~~\n    Dieses zeigt die online-hilfstexte, auf die der user zurueckgreifen\n    kann.\n    Bei diesem command such das BBS nach dem file:\n    BBS:BBSHELP.TXT .Gibt es diesen nicht, ist keine hilfe verfuegbar.\n\n  =======================================================================\n@endnode\n@node Cap100211 "[ J ] - Join Conference...."\n  =======================================================================\n  [ J ] - Join Conference:\n          ~~~~~~~~~~~~~~~\n    Das dient dazu, um von dieser conference in eine andere zu wechseln,\n    in der man auch zugriff hat.Das BBS sucht nach.\n    BBS:NODE{x}/JOINCONF{SEC}.TXT und zeigt es an.\n    Gibt`s den file nicht, informiert es den user, dass der file fehlt.\n\n    Dann will es die nummer der conference, die man joinen will.Hat der\n    user keinen zugang zur gewuenschten conference, sagt ihm das das BBS.\n\n    Wenn der user zugang zu der conference hat, schalted \X zu dieser\n    conference und sucht nach mail fuer den user und zeigt dann die in frage\n    kommenden files, falls welche vorhanden sind..\n    Ist die option "RELATIVE_CONFERENCES" an, im CONF.DEF Icon, dann\n    zeit das BBS nur die conferences, zu denen der user zugriff hat.s\n\n  =======================================================================\n@endnode\n@node Cap100212 "[ M ] - Mode Select...."\n  =======================================================================\n  [ M ] - Mode Select:\n          ~~~~~~~~~~~\n    Dieses command schalted zwischen ANSI und Monochrome output um.\n    Bei ANSI versucht das BBS files mit entsprechender Endung zu verwenden.\n    Gibt es diese nicht, werden die .TXT files verwendet und konvertiert.\n\n  =======================================================================\n@endnode\n@node Cap100213 "[ RZ ] - Zmodem Upload Command...."\n  =======================================================================\n  [ RZ ] - Zmodem Upload Command:\n           ~~~~~~~~~~~~~~~~~~~~~\n    Fuehrt sofortigen zmodem upload aus..\n  =======================================================================\n@endnode\n@node Cap100214 "[ ^ ] - Extended Help Command...."\n  =======================================================================\n  [ ^ ] - Extended Help Command:\n          ~~~~~~~~~~~~~~~~~~~~~\n    Erlaubt dem user help-files zu lesen, die sich im\n    BBS:help directory.befinden Die help commands koennen MCI commands enthalten\n    wie Usernamen zeigen, um die hilfe persoenlicher wirken zu lassen.\n\n  =======================================================================\n@endnode\n@node Cap100215 "[ N ] - New Files Since Date...."\n  =======================================================================\n  [ N ] - New Files Since Date:\n          ~~~~~~~~~~~~~~~~~~~~\n    Erlaubt dem user files seit einem bestimmten datum zu listen, oder seit\n    dem letzen logon im system.Mit andern worten sieht der user, was sich an\n    files seit seinem letzten logon geaendert hat.\n\n\n    1. Wenn die anzahl der dirs der conference 0 ist, sagt das\n       BBS "No files available in this\n       conference." Das user kommt zurueck ins main menu..\n\n    2. Es fragt nach dem datum , ab dem gelisted wird..\n       Datum des letzen logons ist standart und kann einfach mit return\n       bestaetigt werden.Das datumformat hat die form:\n       MM-DD-YY.\n\n    3. Jetzt fragt das BBS das zu druchsuchende dir. Ein  ''A''\n       listed alle directories,  ''U'' zeigt das\n       upload directory.  Ein H für das hold directory.\n       Hold directory kann nur mit level ueber 200 verwendet werden.\n\n    4. Der pauseprompt ist der gleiche wie in der listing-section.\n\n  =======================================================================\n@endnode\n@node Cap100216 "[ O ] - Operator Page...."\n  =======================================================================\n  [ O ] - Operator Page:\n          ~~~~~~~~~~~~~\n    Mit diesem command ruft der remote user den sysop zum chat.\n\n    1. Zuerst checkt \x, zu wie often male der sysop gerufen wird.Hat der user\n       die maximalen versuche ausgeschoeft,darf er einen comment schreiben,\n       anstelle des chat-rufs.\n\n\n    2. Ruft der user den sysop das erste mal in dieser session, wird sein\n       username rot (bei 3 bitplanes) oder er hat einen * am Anfang des namens.\n       cWenn das ICONIFIES window da ist, erscheint sein name in anderer\n       farbe dargestellt.So kann der sysop sehen,ob ein user chatten wollte.\n\n\n    3. Wenn das F7 Chat toggle flag nichtgesetzt ist um sysop rufen zu erlauben,\n       heisst es:\n\n          "Sorry, The SYSOP, is not around right now\n           You can use ''C'' to leave a comment."\n\n    4. Wenn das toggle flag den ruf erlaubt, notiert das BBS im\n       BBS:NODE{x}/CALLERSLOG dass der user grufen hat.\n       Es zeigt dann "Paging SYSOP (CTRL-C to Abort). ." gefolgt von einer Glocke\n       un einigen punkten.\n\n    5. Wenn du als sysop chatten willst, druecke F1 fuer den chat.\n       \X sucht dann im file BBS:NODE{x}/STARTCHAT.TXT nach displays\n       fuer den user.Dies koennte ein einfacher gruss sein.Gibt`s den file\n       nicht, kommt die standart sysop chat aktive message auf dem screen.\n       Mit F1 verlaesst manden chat, wenn er beendet ist und das BBS zeigt\n       BBS:NODE{x}/ENDCHAT.TXT an.Im ANSI modus haben user und sysop\n       verschiedene farben.\n  =======================================================================\n@endnode\n@node Cap100217 "[ Q ] - Quiet Node...."\n  =======================================================================\n  [ Q ] - Quiet Node:\n          ~~~~~~~~~~\n    Dieses commands aendert die Quiet Node option, die man fuer eine node gewaehlt hat.\n    Damit kann sich ein user fuer andere user unsichtbar machen.\n\n  =======================================================================\n@endnode\n@node Cap100218 "[ R ] - Read Mail...."\n  =======================================================================\n  [ R ] - Read Mail:\n          ~~~~~~~~~\n    Es ermoeglich das on-line mailing system zum lesen von mails zu verwenden.\n    Es wird auch verwendet, wen man auf eine bestimmte message antworted.\n\n    1. Zuerst zeigt das system den prompt\n\n    MSG. Options: A,D,F,R,Q,?,<CR> ( QUIT )>:\n\n     (1). <A>gain, zeigt diese message noch einmal.\n                   (specified by the ''a'' in the above line)\n\n     (2). <D>elete, der user kann eine message leosche, wenn sie von ihm\n                    oder an ihn.User ab level 210 koennen alle mails loeschen\n\n\n     (3). <F>ile, tested, ob es einen angehaengten file zum downen\n                  gibt.\n\n     (4). <R>eply, der user kann auf diese message antworten.Das subject\n                   enthaelt das alte subject, der cursor steht dahinter.\n                   Wenn der user das subject aendern will kann er das, return\n                   nimmt das alte subject.Dann fragt das bbs, ob seine reply\n                   private ist.Standart ist NEIN.\n\n                   Dann wird gefragt, ob die alte msg gequoted werden soll,\n                   standart ist NEIN.Waehlt er ja, wird die message nochmals\n                   angezeigt und der user kann waehlen:\n\n                   Enter Startline,Endline or (*=ALL, A=Abort):\n\n                   Wobei ein "*" die ganze message quoted, ansonsten sollten\n                   start und endzeile durch komma getrennt eingegeben werden.\n\n                   Dann kommt der user zum online message editor um seine\n                   msg zu schreiben.Commands des editors funktionieren wie\n                   die ENTER MESSAGE commands.\n\n    (5). <?>, das zeigt die volle beschreibung der gepackten\n              Mail lesezeile  und dient zur hilfe.\n\n    (6). <CR=Next>, faehrt fort mit der suche nach neuen messages.\n\n    (7). "EH" - damit kann der syspü einen message header editieren\n                Er kann die TO:, subject: und das private/public aendern.\n\n    (8). "U"  - bringt den sysop zum account editing fuer diesen user, der\n                diese message geschrieben hat.So kann man einen neuen user\n                schnell ueberpruefen und sofort seinen account einrichten.\n\n  =======================================================================\n@endnode\n@node Cap100219 "[ RL ] - RELOGON...."\n  =======================================================================\n  [ RL ] - RELOGON:\n           ~~~~~~~\n    Macht einen RELOGON an dieser node. Das bringt den user zur\n    Normal LOGON sequence und started ein Module namens\n    "RELOGON" oder "RELOGON<node>" im SYSCMD Directory. Wenn das Module\n    verfuegbar ist, wird`s gestarted und nach beendigung ist der user am\n    LogonString.\n  =======================================================================\n@endnode\n@node Cap100220 "[ S ] - Status of On-Line User...."\n  =======================================================================\n  [ S ] - Status of On-Line User:\n          ~~~~~~~~~~~~~~~~~~~~~~\n    Zeigt aktuelle infos ueber den user und seinen account.\n    in der form::\n\n       Caller Num.: 2049\n       Lst Date On: 05-14-93\n       Security Lv: 30\n       # Times On : 579\n       Ratio DL/UL: Disabled\n       Online Baud: 16800\n       Rate CPS UP: 0\n       Rate CPS DN: 0\n       Screen  Clr: NO\n       Protocol   : /X Zmodem\n       Sysop Pages Remaining: 3\n\n\n                     Uploads            Downloads\n            Conf  Files    Bytes     Files    Bytes     Bytes Avail  Ratio\n            ----  -------  --------- -------  --------- -----------  -----\n               2>       0          0       0          0           0  DSBLD\n  =======================================================================\n@endnode\n@node Cap100221 "[ T ] - Time, at the system site...."\n  =======================================================================\n  [ T ] - Time, at the system site:\n          ~~~~~~~~~~~~~~~~~~~~~~~~\n    Sagt dem user, welche zeit die BBS hat.\n    Locale time/date stamp function.\n  =======================================================================\n@endnode\n@node Cap100222 "[ U ] - Upload File(s)...."\n  =======================================================================\n  [ U ] - Upload File(s):\n          ~~~~~~~~~~~~~~\n    Setzt das BBS in den empfangsmode, damit der remote user files senden kann.\n\n    1. Das BBS prueft, ob es ein directory fuer uploads gibt,es sucht im\n       NDIRS=<numb> tooltype. Gibt`s den nicht oder er ist 0, kommt der user zum\n       MAIN MENU PROMPT mit der message "no files available in this\n       conference."\n\n    2. Gibt`s einen BBS:CONF/UPLOADMSG.TXT , zeigt das BBS dem user diesen.\n\n    3. Das BBS berechnet den freien diskplatz, die erste angezeigte zahl\n       ist der freie platz auf allen drives, die in\n       DRIVES.DEF.INFO im BBS: directory stehen.\n\n       nur  drives die download files für das BBS\n       enthalten, solten angegeben werden, damit der user richtig\n       informiert wird.\n\n       Die zweie zahl ist der freie platz im\n       BBS:CONF/UPLOAD directory. Das dient dazu, dass das BBS weis, wieviel\n       platz frei ist um uploads zu bekommen, bis der sysop wiederkommt.\n\n       Das BBS erlaubt uploads, bis es weniger als 2MB freier platz im\n       BBS:CONF/UPLOAD werden.\n\n    4. Das BBS ruft die resume routine um zu testen, ob es files gibt, die\n       unvollstaendig sind.Es verfaehrt, wie unter "G"oodbye beschrieben.\n\n    5. Das BBS fragt nach den filenamen, die der user uppen moechte,\n       er kann return druecken, dann leifert zmodem den filenamen.\n       Gibt man "A" an, bricht der Vorggn ab und man landet im main\n       prompt.\n\n    6. Wenn der user filenamen eingibt, prueft das BBs, ob sie nicht schon gibt.\n       Wenn nicht, darf er einen filebeschreibung eingeben.\n       Eine leerzeile beendet die beschreibung..\n\n    7. Jetzt zeigt das BBS an:\n       (Enter) to Start, (G)oodbye after transfer, (A)bort?\n       das sind die gleichenoptions wie beim download beschrieben.\n\n       An diesem punkt kann der sysop "L" fuer die locale upload routine\n       druecken, die ein filerequester fuer direkt zu importierende\n       files bringt., ohne dass die files serial transportiert werden muessten.\n\n    8. Wenn der user noch nicht im\n       BBS:NODE{x}/UDLOG stand, tut er es jetzt.\n\n    9. Wenn der upload jetzt started, prueft das BBS auf files in der\n       FILESNOTALLOWED=<pathname> option im NODE icon.\n       Sollte der file dort aufgefuehrt sien, wird er uebergangen.\n\n\n   10. Das BBS zeigt STATS des transfers aller files.\n\n\n   11. Die suertime wird gutgeschrieben fuer diesen upload.\n\n   12. Jetzt preuft das BBS, ob die filenamen laenger sind als 12\n       Buchstaben, falls ja muss der user die files umbenennen.\n\n   13. Das BBS prueft, ob der user shcon eine filebeschreibung eingegeben hat,\n       wenn ja, gibt es diese nun aus.\n\n   14. Wenn es keine beschreibung gibt, fragt es den user dannach.8 Zeilen stehen\n       zur verfuegung.\n\n\n   15. Wenn der user rausfliegt, waehrend der beschreibungseingaben\n       setzt das BBS "LOSS CARRIER" in die beschreibung.\n       und setzt das file ins BBS:CONF/LCFILES directory,\n       zusammen mit einem Comment im <usernumber>.lc ,wo alle files stehen\n       die der user noch kommentieren muss.Es wird dann in der phase der\n       unvollstaendigen uploads im logon dannach gefragt.\n\n   16. Wenn die beschreibung eingegeben wurde prueft das BBS, ob ein door namens\n       "FILECHECK" im SYSCMD directory existiert und wird ausgefuert.\n       Es wird der interne "FCHECK" vrewendet.Hier kann man verschiedene\n       checker fuer alle formate verwenden.Wenn das door nicht existiert,\n       wird auf eine fileendung geprueft.\n        (IE:.DMS,.LHA.)).\n\n          Express vergleicht nun die endung mit den icons der\n          gleichen endung im BBS:FCHECK directory.\n\n          ICONS im CHECK directory sagen, dass man exteren filechecker\n          verwendet.Das format der icons wurde bereits erwaehnt.\n\n\n          Wenn es keine externen checker gibt, erhaelt das\n          file den comment "N" fuer nicht geprueft..\n\n   17. Wenn das Archiv geprueft ist, setzt das BBS ein "P"\n       (=passed) zwischen filenamen und filesize im listing.\n\n   18. Wenn das archiv geprueft ist und es schlecht ist, setzt das\n       BBS ein''F'' zwischen filename und filesize im listing.\n\n   19. If the file is not one of the above checkable file types\n       then the BBS puts a ''N'' between the filename and the\n       filesize in the listing.\n\n   20. Jetzt setzt das BBS den file in die listing area.  Wenn der user ein\n        ''/'' am anfang der beschreibung hat, oder der file den check nicht geschafft\n       hat, oder der user rausgeflogen ist, geht der file ins\n       BBS:CONF/HOLD/HELD Trift all das nicht zu, schreibt das BBS\n       den file ans ende von\n       BBS:CONF/DIR{U} wobei U das upload directory (oder\n       das hoehste verfuegbare dir ) ist.\n\n   21. Wenn das BBS den file nun moven will, z.B ins hold-directory und es\n       befindet sich bereits ein file dieses namans dort, wird zum namen ein\n       ''_'' angehaengt, bist der name passt.\n\n   22. Sind alle files erledigt, prueft das BBS, um sicher zu gehen, dass es keine\n       herumliegenden files im BBS:NODEx/PLAYPEN gibt.\n       Sollte es solche files finden, setzt es diese nach\n       BBS:CONF/PARTUPLOAD als unvollstaendige files, des momentanen\n       online users.\n  =======================================================================\n@endnode\n@node Cap100223 "[ V ] - View a Text File...."\n  =======================================================================\n  [ V ] - View a Text File:\n          ~~~~~~~~~~~~~~~~\n    Erlaubt dem user den inhalt eines Textfiles im\n    BBS:CONFNAME/UPLOAD directory zu lesen. Für Co-Sysop''s mit Zugriff\n    auf SYSOP_VIEW in Access ICONS, koennen files aus jedem gueltigen\n    systempfad gelesen werden.h.\n\n    1. Das BBS prueft,ob es file-dirs in dieser conf gibt, indem es den tooltype\n       NDIRS=<numb> liesst.Gibt`s den nicht oder er ist 0, kommt der user zum\n       MAIN MENU PROMPT mit der message\n       "No files available in this conference."\n\n    2. Das BBS fragt nach dem zu lesenden filenamen.\n\n    3. Wenn der user ACCESS auf die SYSOP_VIEW Option hat und er schreibt\n       ''VS'' anstatt nur ''V'' dann kann er einen pfad eingeben.\n       Der sysop wird verstaendig durch einen eintrag in\n       BBS:NODE{x}/CALLERSLOG , welcher file gelesen wurde.\n\n    4. Das BBS zeigt den file , wenn die Zeichenwerte kleiner 128 sind.\n       Ist ein Zeichen groesser als 127, meldet das BBS\n       "This file is not a text file." und geht zum main prompt.\n\n         NOTE: Files mit RESTRICTED comment kann der user nicht zeigen\n         ~~~~  Wenn er den Versuch unternimmt, wird das im\n               BBS:NODE{x}/CallersLog notiert.\n  =======================================================================\n@endnode\n@node Cap100224 "[ W ] - Write User Parameters...."\n  =======================================================================\n  [ W ] - Write User Parameters:\n          ~~~~~~~~~~~~~~~~~~~~~\n    Erlaubt dem user persoenlich dinge bezogen auf seinen account zu aendern.\n\n    Das command zeigt das folgende::\n\n            1. LOGIN NAME..............ByteMaster\n            2. REAL NAME...............Joseph Hodge\n            3. INTERNET NAME...........jhodge\n            4. LOCATION................Radford, Va.\n            5. PHONE NUMBER............603-555-1212\n            6. PASSWORD................ENCRYPTED\n            7. LINES PER SCREEN........23\n            8. COMPUTER................Amiga 2000/GVP030\n            9. SCREEN TYPE.............Amiga Ansi\n           10. SCREEN CLEAR............Yes\n           11. TRANSFER PROTOCOL......./X Zmodem\n           12. EDITOR TYPE.............Prompt\n           13. ZOOM TYPE...............QWK\n           14. AVAILABLE FOR CHAT/OLM..Yes\n\n\n           Which to change <CR>= QUIT ?\n\n     Jetzt kann der user waehlen, was er aendern moechte oder return um\n     diese funktion zu verlassen..\n     Die ersten 4 items kann der user eventuel nicht aendern, wegen seinem\n     zu niedrigem level.Fuer infos siehe dox des AmiCONFIG programs.\n\n  =======================================================================\n@endnode\n@node Cap100225 "[ WHO ] - Node Information...."\n  =======================================================================\n  [ WHO ] - Node Information:\n            ~~~~~~~~~~~~~~~~\n    Dieses command welche user online sind und was sie gerade tun.Waehlt man\n    QUIETNODE fuer eine node, wird diese node beim listen uebergangen.\n\n  =======================================================================\n@endnode\n@node Cap100226 "[ X ] - Expert Mode Toggle...."\n  =======================================================================\n  [ X ] - Expert Mode Toggle:\n          ~~~~~~~~~~~~~~~~~~\n    Der user kann hier zwischen eXpert und Neuling umschalten.Experten\n    sehen das menu nur nach einem "?", der neuling sieht es nach jedem\n    command.\n  =======================================================================\n@endnode\n@node Cap100227 "[ Z ] - Zippy Text Search...."\n  =======================================================================\n  [ Z ] - Zippy Text Search:\n          ~~~~~~~~~~~~~~~~~\n    Erlaubt dem user alle BBS:CONFNAME/DIR{x}\n    files auf einen bestimmten string durchsuchen zu lassen.\n    Wenn etwas gefunden wird, wird die ganze fileinfo angezeigt,einschliesslich\n    beschreibung.\n    Wenn NDIRS=<numb> tooltype auf 0 steht oder er nicht existert, funktioniert\n    zippy search nicht..\n  =======================================================================\n@endnode\n@node Cap100228 "[ ZOOM ] - Zoo Mail...."\n  =======================================================================\n  [ ZOOM ] - Zoo Mail:\n             ~~~~~~~~\n       Zoo mail wurde wieder eingebaut ins \X und basiert nun auf aktuellen\n       compressionsverfahren der modemhersteller, anstelle von ZOO, da\n       Zoo die tendenz hatte den Amiga zu crashen,manchmal.ZOOM verarbeitet\n       alle ungelesene mail des users (als lha, wenn gewuenscht) aus allen\n       zugriffberechtigten conferences in einen frei downloadbaren file\n       der automatisch auf die liste der markierten files fuer download\n       gesetzt wird..\n  =======================================================================\n@endnode\n@node Cap100229 "[ CF ] - Set Conference Configuration...."\n  =======================================================================\n  [ CF ] - Set Conference Configuration:\n           ~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n       Die user koennen hier einstellen, wie \X conferences handhabt.\n       Sie koennen ''NEW FILE SCAN'', ''NEW MESSAGE SCAN'', und die conferencen,\n       von denen sie zoom mails wollten an und abschalten.\n\n       Bei der conference kontrolle im Account editor kann man diese optionen\n       global setzen, mit (F5).\n  =======================================================================\n@endnode\n@node Cap100230 "[ VO ] - Voting Booth...."\n  =======================================================================\n  [ VO ] - Voting Booth:\n           ~~~~~~~~~~~~\n       Hierzu braucht man ACS.MODIFY_VOTE für SYSOPS und ACS.VOTE\n       für die user im access icon.\n\n       NOTE: Bei der Wahlkabine wird automatisch ein dir namens VOTE angelegt,\n       dieses im conference directory , in dem man eine Wahlkabine installiert.\n\n\n       Die wahlkabine kann bis 25 themen pro conference haben, jedes thema\n       bieted bis zu 99 multiple choice Fragen dazu..\n\n       Es gibt auch einen neue option im Conference Maintenance screen namens\n       RESET VOTING BOOTH.Sie streicht alle themen, ueber die der user schon\n       im file CONF.DB abgestimmt hat.\n       Man sollte das in jeder conference tun, in der man eine Wahlkabine betreibt.\n\n       Die Wahlkabine basiert auf conferences, also keine conference kann eine\n       Kabine mit einer anderen teilen..\n\n       Um eine Wahlkabine zu installieren, setze einfach die voted flags\n       CONF.DB mit conference maintenance zurueck, dann:\n\n        1. type ''VO'' im menu prompt.\n        2. Waehle  ''CREATE VOTE TOPIC'' im menu..\n           (Wichtig! man braucht ACS.MODIFY_VOTE access damit das funktioniert)\n        3. Es wird nach einer TOPIC NUMBER gefragt, dei zwischen 1-25 sein darf,\n           am besten faengt man mit 1 an ...''.\n        4. Nun sollte einen einzeilige beschreibung des Themas folgen.\n           Dann kann man : save, edit, abort, list, delete etc.\n        5. Jetzt wird man nach Fragen zum thema gefragt. Man kann bist 99\n           Fragen zum thema eingeben.\n        6. Wenn man eine frage eingegeben hat, drueckt man ''S'' zum saven\n           und man wird bezueglich multiple choice option gefragt.\n           man kann bis zu 25 multiple choice option pro frage haben.\n        7. Hat man eine option eingegeben, druecke return, speichere es und\n           gehe zur naechsten Moeglichkeit..\n        8. Wenn man alle eingegeben hat und wieder nach einer Moeglichkeit gefragt wird,\n           drueckt man einfach save, dann kommt man zu naechsten frage.e\n\n        9. Wenn man keine weitere Frage mehr hat, drueckt man abort.\n\n       10. jetzt sollte man landen im VOTE MAINTENANCE MENU.\n       11. Auch hier kann man eine Wahl,themen,etc. editieren, falls man einen\n           Fehler gemacht hat.\n\n        NOTE:\n\n        Ist ein Thema einmal generiert ist, kann man keine weiteren fragen hinzufuegen\n        , da ein user alle fragen beantworted haben muss, damit man die wahl als\n        gueltig betrachten kann.Das wird so erreicht, indem der user solange in der\n        Wahlkabine bleibt, bis er alle fragen beantworted hat.\n        Sollte der carrier verloren gehen, ist die Wahl nichtig und es muss komplett\n        neu gewaehlt werden, beim naechten logon.\n\n  =======================================================================\n@endnode\n@node Cap11 "AREXX Interface MODULES (AIM)...."\n  =======================================================================\n                         AmiExpress HOST Addresses\n                         ~~~~~~~~~~~~~~~~~~~~~~~~~\n  \X erlaubt die verwendung externer HOST Addressen um module zu starten,\n  welche vom user mittels eines speziellen keys gestarted werden koennen. Die HOST\n  addressen koennen von programmieren in modulen fuer \X verwendet werden.\n  Die Addressen koennen von vielen Programmiersprachne aus bedient werden,\n  (AREXX,C,ASSEMBLER Aso.),um dem programmierer mehr moeglichkeiten zu bieten.\n  \X bieted viele commands fuer HOST Addressen um Informationen zu den nodes zu\n  transferieren.Die Commands dazu werden in verschiedene Gruppen unterteilt.\n\n\n    @{" Standard HOST Commands       " Link Cap1101}    @{" Special Arexx HOST Cmds (AIM)" Link Cap1102}\n    @{" Traditional HOST Cmds   (TIM)" Link Cap1103}    @{" AmiExpress Interface    (XIM)" Link Cap1104}\n    @{" AmiExpress Script HOST  (SIM)" Link Cap1105}    @{" AmiExpress CLI Interface(XIM)" Link Cap1106}\n\n  =======================================================================\n@endnode\n@node Cap1102 "Special Arexx HOST Cmds (AIM)...."\n  =======================================================================\n  Das Arexxinterface benoetigt den file REXXDOOR,des sich im UTILS: pfad befinden\n  sollte.Ausserdem wird ein icon fuer das door im\n  BBSCmd oder CONF{x} benoetigt und der file sollte im BBS:Commands sein.\n  REXXDOOR wird immer gestarted, wenn ein Arexx door gefordert ist.\n  Arexx muss auf dem Amiga korrek installiert sien, damit es mit \X laeuft.\n  Dazu gehoeren unter anderem die files im dh0:Rexxc dir.In der startup-sequence\n  darf folgendes nicht fehlen:\n\n                    Assign >NIL: REXX: SYS:REXXC\n\n  Und, (steht bei mir im user-startup) dazu diese zeilen:\n\n                    Rpstart >Nil:\n\n  Jetzt ist der AMiga bereit..\n\n  NOTE: Wenn CARRIER LOSS oder ein keyboard TIMEOUT festgestellt wird, wird fehlercode\n  ~~~~  10 der Arexx script uebergeben und REXXDOOR schliesst die ports des BBS und\n        der Arexxsript.\n\n\n  So, jetzt reden wir ueber Arexx commands, die Informationen ans BBS und die\n  User lesen und schreiben koennen.Sie sind nuetzlich, wenn man einige Tools\n  fuer \X programmieren will, aber es ist recht schwierig fuer jemand, der bisher kein\n  Arexx verwendet hat.\n\n  NOTE: Diese commands sind interne und stammen nicht aus speziellen Entwicklungs\n  ~~~~  doors.\n\n  Um ein Arexx module korrekt anzubinden, schreibt man folgende erste Zeilen:\n\n  ------ cut here ------\n  /* Arexx Module TEST */\n\n  parse arg NODE\n  options results\n  address value "AERexxControl"NODE\n  ------ cut here ------\n\n  Ohne diese Zeilen arbeited das modul nicht mit \X zusammen, also pass auf,\n  dass sich diese Zeilen am anfang jedes\n  AIM Modules befinden.\n\n  Folgendes sind AmiExpress Arexx HOST Commands, die die moeglichkeit bieten\n  module selbst zu entwerfen.Eine initialisierung eines solchen modules\n  sieht wie folgt aus:\n\n\nCOMMAND NAME   FUNCTION\n=========================================================================\nGETUSER <x>    Liesst daten der funktion <x> des dezimal gegebenen host commands.\n               Die Daten werden der normalen result funktion vonArexx uebergeben.\n               Man kann damit den BBSnamen oder andere Dinge erhalten.\n               Fuer infos zu den Funktionennummern,siehe\n               ''Standard HOST Commands''.\n\n=========================================================================\nPUTUSER <x>    Das command ist das gleiche wie das GETUSER command, mit dem Unterschied,\n               dass es daten speichert und nicht  von funktion <x> liesst.\n               Um daten fuer eine funktion<x> zu speichern braucht man\n               PUTUSTR zusammen mit PUTUSER, da PUTUSER wissen muss, was es fuer\n               FUNCTION <x> speichern soll.\n\n=========================================================================\nPUTUSTR <x>    Das Arexx command definiert die PUTUSER command abhaengigen DATEN\n               fuer die HOST commands fuer \X.Benuetze diese 2 Arexx commands\n               um zu \X gehoerende Commands auszufuehren.\n\n\n               PUTUSTR "g" <- die variable, die man der\n               PUTUSER 136 <- FUNCTION 136 geben will.\n\n               Diese beiden commands fuehren das interen Goodbye menu aus\n               und sie verlassen das BBS..\n               Die ''136'' haengt von den anderen HOST COMMANDS ab, die man eingegeben\n               hat,dezimal..\n=========================================================================\nTRANSMIT ""    Das wichtigste host command bei Arexx von \X.Es schickt text\n               serial hinaus, der im "" steht, immer in das node window,\n               vondem aus es gestarted wurde.\n\n               example:\n               TRANSMIT "HELLO"\n\n               Jetzt sollte HELLO im node window autauchen, von dem aus es\n               gestarted wurde.\n=========================================================================\nSENDMESSAGE    Das gleiche command wie transmit, nur schickt es keinen\n               carrige return.Man kann also dahinter noch weiterschreiben.\n\n=========================================================================\nGETCHAR        Das command warted auf eingabe vo user und uebergibt diesen\n               dem RESULT command des normalen Arexx.Mit dem command kann\n               man dem user fragen stellen und die antwort in verschiedene\n               variablen setzen.\n=========================================================================\nPROMPT ""      Das ist eine Mischung aus TRANSMIT & GETCHAR,Nachdem es den\n               Text im "" angezeigt hat,fragt es den user nach einer eingabe,\n               die bis zum return dauert.Die Daten befinden sich dann im RESULT\n               command ov AREXX.\n=========================================================================\n@endnode\n@node Cap1101 "Standard AmiExpress HOST Commands...."\n=========================================================================\n                    Standard AmiExpress HOST Commands\n                    ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n  Das folgende ist eine liste der \X HOST commands, die in jedem program\n  verwendet werden koennen.Mit diesen commands bekommt man den BBSNAME,USERNAME\n  ,,etc.\n\n    @{" JH_LI            <Func: 000> " Link Cap1101000}    @{" JH_REGISTER      <Func: 001> " Link Cap1101001}\n    @{" JH_SHUTDOWN      <Func: 002> " Link Cap1101002}    @{" JH_WRITE         <Func: 003> " Link Cap1101003}\n    @{" JH_SM            <Func: 004> " Link Cap1101004}    @{" JH_PM            <Func: 005> " Link Cap1101005}\n    @{" JH_HK            <Func: 006> " Link Cap1101006}    @{" JH_SG            <Func: 007> " Link Cap1101007}\n    @{" JH_SF            <Func: 008> " Link Cap1101008}    @{" JH_EF            <Func: 009> " Link Cap1101009}\n    @{" JH_CO            <Func: 010> " Link Cap1101010}    @{" JH_BBSNAME       <Func: 011> " Link Cap1101011}\n    @{" JH_SYSOP         <Func: 012> " Link Cap1101012}    @{" JH_FLAGFILE      <Func: 013> " Link Cap1101013}\n    @{" DT_NAME          <Func: 100> " Link Cap1101100}    @{" DT_PASSWORD      <Func: 101> " Link Cap1101101}\n    @{" DT_LOCATION      <Func: 102> " Link Cap1101102}    @{" DT_PHONENUMBER   <Func: 103> " Link Cap1101103}\n    @{" DT_SLOTNUMBER    <Func: 104> " Link Cap1101104}    @{" DT_ACCESSLEVEL   <Func: 105> " Link Cap1101105}\n    @{" DT_RATIOTYPE     <Func: 106> " Link Cap1101106}    @{" DT_RATIO         <Func: 107> " Link Cap1101107}\n    @{" DT_COMPTYPE      <Func: 108> " Link Cap1101108}    @{" DT_MESSAGESPOSTED<Func: 109> " Link Cap1101109}\n    @{" DT_UPLOADS       <Func: 110> " Link Cap1101110}    @{" DT_DOWNLOADS     <Func: 111> " Link Cap1101111}\n    @{" DT_TIMESCALLED   <Func: 112> " Link Cap1101112}    @{" DT_TIMELASTON    <Func: 113> " Link Cap1101109}\n    @{" DT_TIMEUSED      <Func: 114> " Link Cap1101114}    @{" DT_TIMELIMIT     <Func: 115> " Link Cap1101115}\n    @{" DT_TIMETOTAL     <Func: 116> " Link Cap1101116}    @{" DT_BYTESUPLOAD   <Func: 117> " Link Cap1101117}\n    @{" DT_BYTEDOWNLOAD  <Func: 118> " Link Cap1101118}    @{" DT_DAILYBYTELIMIT<Func: 119> " Link Cap1101119}\n    @{" DT_DAILYBYTEDLD  <Func: 120> " Link Cap1101120}    @{" DT_EXPERT        <Func: 121> " Link Cap1101121}\n    @{" DT_LINELENGTH    <Func: 122> " Link Cap1101122}    @{" ACTIVE_NODES     <Func: 123> " Link Cap1101123}\n    @{" DT_DUMP          <Func: 124> " Link Cap1101124}    @{" DT_TIMEOUT       <Func: 125> " Link Cap1101125}\n    @{" BB_CONFNAME      <Func: 126> " Link Cap1101126}    @{" BB_CONFLOCAL     <Func: 127> " Link Cap1101127}\n    @{" BB_LOCAL         <Func: 128> " Link Cap1101128}    @{" BB_STATUS        <Func: 129> " Link Cap1101129}\n    @{" BB_MAINLINE      <Func: 131> " Link Cap1101131}    @{" RETURNCOMMAND    <Func: 136> " Link Cap1101136}\n    @{" ZMODEMSEND       <Func: 137> " Link Cap1101137}    @{" ZMODEMRECEIVE    <Func: 138> " Link Cap1101138}\n    @{" SCREEN_ADDRESS   <Func: 139> " Link Cap1101139}    @{" BB_TASKPRI       <Func: 140> " Link Cap1101140}\n    @{" RAWSCREEN_ADDRESS<Func: 141> " Link Cap1101141}    @{" BB_CHATFLAG      <Func: 142> " Link Cap1101142}\n    @{" DT_STAMP_LASTON  <Func: 143> " Link Cap1101143}    @{" DT_STAMP_CTIME   <Func: 144> " Link Cap1101144}\n    @{" DT_CURR_TIME     <Func: 145> " Link Cap1101145}    @{" DT_CONFACCESS    <Func: 146> " Link Cap1101146}\n    @{" BB_NODEID        <Func: 149> " Link Cap1101149}    @{" BB_CALLERSLOG    <Func: 150> " Link Cap1101150}\n    @{" BB_UDLOG         <Func: 151> " Link Cap1101151}    @{" EXPRESS_VERSION  <Func: 152> " Link Cap1101152}\n    @{" BB_CHATSET       <Func: 162> " Link Cap1101162}    @{" ENVSTAT          <Func: 163> " Link Cap1101163}\n    @{" NODE_DEVICE      <Func: 503> " Link Cap1101503}    @{" NODE_UNIT        <Func: 504> " Link Cap1101504}\n    @{" NODE_BAUD        <Func: 505> " Link Cap1101505}    @{" JH_MCI           <Func: 507> " Link Cap1101507}\n    @{" PRV_COMMAND      <Func: 508> " Link Cap1101508}    @{" BB_CONFNUM       <Func: 510> " Link Cap1101510}\n    @{" BB_DROPDTR       <Func: 511> " Link Cap1101511}    @{" BB_GETTASK       <Func: 512> " Link Cap1101512}\n    @{" NODE_BAUDRATE    <Func: 516> " Link Cap1101516}    @{" BB_LOGONTYPE     <Func: 517> " Link Cap1101517}\n    @{" BB_SCRLEFT       <Func: 518> " Link Cap1101518}    @{" BB_SCRTOP        <Func: 519> " Link Cap1101519}\n    @{" BB_SCRWIDTH      <Func: 520> " Link Cap1101520}    @{" BB_SCRHEIGHT     <Func: 521> " Link Cap1101521}\n    @{" BB_PURGELIN      <Func: 522> " Link Cap1101522}    @{" BB_PURGELINESTART<Func: 523> " Link Cap1101523}\n    @{" BB_PURGELINEEND  <Func: 524> " Link Cap1101524}    @{" BB_NONSTOPTEXT   <Func: 525> " Link Cap1101525}\n    @{" BB_LINECOUNT     <Func: 526> " Link Cap1101526}    @{" DT_LANGUAGE      <Func: 527> " Link Cap1101527}\n    @{" DT_QUICKFLAG     <Func: 528> " Link Cap1101528}    @{" DT_GOODFILE      <Func: 529> " Link Cap1101529}\n\n=========================================================================\n@endnode\n@node Cap1101000 "JH_LI             <Func: 000>"\n=========================================================================\nJH_LI          Fordert einen string vom user mit einer standart Antwort.\n\n               msg->Command = 0\n               msg->String  = standart antwort\n               msg->Data    = Maximale laenge der Antwort\n\n               msg->Data steht auf -1 wenn carrier verloren ging, oder console\n               TIMEOUT auftritt, sonst steht es auf 1.\n\n               msg->String ist der Antwortstring vom user..\n(FUNCTION #: 0 )\n=========================================================================\n@endnode\n@node Cap1101001 "JH_REGISTER       <Func: 001>"\n=========================================================================\nJH_REGISTER    REgistered ein door oder XIM dieser node..\n\n               msg->Command = 1\n\n               Das muss dasd erste command sein, das die \X node bekommt.\n               Es erhoeht die Anzhal der aktiven doors an dieser node.\n\n(FUNCTION #: 1 )\n=========================================================================\n@endnode\n@node Cap1101002 "JH_SHUTDOWN       <Func: 002>"\n=========================================================================\nJH_SHUTDOWN   Sagt der node, dass das door herunterfaehrt,das verringert die anzahl\n              der aktiven doors.Wird diese Zahl 0, schliesst  der\n              AEDoorPort.\n\n              msg->Command = 2\n              msg->Data    = N/A\n(FUNCTION #: 2 )\n=========================================================================\n@endnode\n@node Cap1101003 "JH_WRITE          <Func: 003>"\n=========================================================================\nJH_WRITE        Man kann hier einen string an den user schicken.\n\n                msg->Command = 3\n                msg->String  = text\n                msg->Data    = N/A\n(FUNCTION #: 3 )\n=========================================================================\n@endnode\n@node Cap1101004 "JH_SM             <Func: 004>"\n=========================================================================\nJH_SM           Man kann hier wieder einen string an den user schicken.\n\n                msg->Command = 4\n                msg->String  = text\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then a CR/LF combination will be sent.\n(FUNCTION #: 4 )\n=========================================================================\n@endnode\n@node Cap1101005 "JH_PM             <Func: 005>"\n=========================================================================\nJH_PM           Fraegt den user nach einer festen anzahl von buchstaben.\n\n\n                msg->Command = 5\n                msg->String  = prompt string\n                msg->Data    = maximale laenge der antwort\n\n                if msg->Data = -1, bei Carrierverlusst oder TIMEOUT, sonst\n                msg->Data = 1.\n\n                msg->String enthaelt die userantwort.\n(FUNCTION #: 5 )\n=========================================================================\n@endnode\n@node Cap1101006 "JH_HK              <Func: 006>"\n=========================================================================\nJH_HK           Erlaubt einen ein-buchstaben antwort des users..\n\n                msg->Command = 6\n                msg->String  = text\n                msg->Data    = N/A\n\n                if msg->Data = -1, bei carierverlusst oder TIMEOUT,sonst\n                msg->Data = 1.\n\n                msg->String ergebnisstring.\n(FUNCTION #: 6 )\n=========================================================================\n@endnode\n@node Cap1101007 "JH_SG             <Func: 007>"\n=========================================================================\nJH_SG           Zeigt dem user einen textfile.\n\n                msg->Command = 7\n                msg->String  = part file name.\n                msg->Data    = N/A\n\n                ie:\n\n                msg->String = "BBS:Node1/Bull\n\n                Das versucht BBS:Node1/BULL.TXT zu zeigen,es\n                zieht auch sprachabhaengigkeit in betracht..\n\n                Ausserdem sucht es nach levelabhaengigem:\n\n                Bull10.TXT, Bull100.TXT\n(FUNCTION #: 7 )\n=========================================================================\n@endnode\n@node Cap1101008 "JH_SF             <Func: 008>"\n=========================================================================\nJH_SF           Zeigt dem user einen file..\n\n                msg->Command = 8\n                msg->String  = Complete pathname\n                msg->Data    = N/A\n\n                ie:\n\n                msg->String  = "BBS:Node1/BULL.TXT"\n\n                Zeigt den filename, sofern es ihn gibt.\n(FUNCTION #: 8 )\n=========================================================================\n@endnode\n@node Cap1101009 "JH_EF             <Func: 009>"\n=========================================================================\nJH_EF          Damit kann der interne msgbase editor zum editieren der eigenen\n               files verwendet werden.\n\n               msg->Command = 9\n               msg->String  = Complete pathname\n               msg->Data    = 0\n\n               if msg->Data = -1, bei carierverlusst oder TIMEOUT,sonst\n               msg->Data will be 1.\n(FUNCTION #: 9 )\n=========================================================================\n@endnode\n@node Cap1101010 "JH_CO             <Func: 010>"\n=========================================================================\nJH_CO          Schickt einen Textstring nur an  die console.\n\n               msg->Command = 10\n               msg->String  = text\n               msg->Data    = 1 or 0\n\n               if msg->Data = 1, dann wird CR/LF am ende des texts geschickt.\n\n(FUNCTION #: 10 )\n=========================================================================\n@endnode\n@node Cap1101011 "JH_BBSNAME        <Func: 011>"\n=========================================================================\nJH_BBSNAME      Damit erhaelt man den BBSnamen..\n\n                msg->Command = 11\n                msg->Data    = N/A\n\n                msg->String enthaelt den BBSNAME\n(FUNCTION #: 11 )\n=========================================================================\n@endnode\n@node Cap1101012 "JH_SYSOP          <Func: 012>"\n=========================================================================\nJH_SYSOP        Liefert den Namen des sysops.\n\n                msg->Command = 12\n                msg->Data    = N/A\n\n                msg->String =Sysop name.\n(FUNCTION #: 12 )\n=========================================================================\n@endnode\n@node Cap1101013 "JH_FLAGFILE       <Func: 013>"\n=========================================================================\nJH_FLAGFILE     Addiert files zur liste der markierten files.\n\n                msg->Command = 13\n                msg->String  = FileName\n                msg->Data    = N/A\n\n                Addiert msg->String zur markierten fileliste,fuer`s\n                downloaden.\n\n                NOTE: Die files muessen im downloadpfad sein, damit es funktioniert.\n\n(FUNCTION #: 13 )\n=========================================================================\n@endnode\n@node Cap1101100 "DT_NAME           <Func: 100>"\n=========================================================================\nDT_NAME         Erlaubt, den usernamen /Handle zu aendern.\n\n                msg->Command = 100\n                msg->Data    = 1 or 0\n\n                wenn msg->Data = 1, dann ist msg->String der name\n                wenn msg->Data = 0, dann ist  der name  msg->String\n(FUNCTION #: 100 )\n=========================================================================\n@endnode\n@node Cap1101101 "DT_PASSWORD       <Func: 101>"\n=========================================================================\nDT_PASSWORD     Damit erhaelt man das passwort der users.\n\n                msg->Command = 101\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String ist das password.\n                if msg->Data = 0, then password ist msg->String.\n(FUNCTION #: 101 )\n=========================================================================\n@endnode\n@node Cap1101102 "DT_LOCATION      <Func: 102>"\n=========================================================================\nDT_LOCATION     Aendert den Wohnort des users.\n\n                msg->Command = 102\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String ist der wohnort.\n                if msg->Data = 0, then Wohnort ist  msg->String\n(FUNCTION #: 102 )\n=========================================================================\n@endnode\n@node Cap1101103 "DT_PHONENUMBER    <Func: 103>"\n=========================================================================\nDT_PHONENUMBER  Aendert die Telefnummer des users..\n\n               msg->Command = 103\n               msg->Data    = 1 or 0\n\n               if msg->Data = 1, then msg->String ist die phonenumber\n               if msg->Data = 0, ten phonenumber ist  msg->String\n(FUNCTION #: 103 )\n=========================================================================\n@endnode\n@node Cap1101104 "DT_SLOTNUMBER     <Func: 104>"\n=========================================================================\nDT_SLOTNUMBER  Liefert die slot nummer des users.\n\n               msg->Command = 104\n               msg->Data    = 1\n\n               if msg->Data = 1, then msg->String ist die SLOTNUMBER.\n(FUNCTION #: 104 )\n=========================================================================\n@endnode\n@node Cap1101105 "DT_ACCESSLEVEL    <Func: 105>"\n=========================================================================\nDT_ACCESSLEVEL  Aendert den access level des users..\n\n                msg->Command = 105\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String ist der ACCESSLEVEL.\n                if msg->Data = 0, then ACCESSLEVEL ist msg->String.\n(FUNCTION #: 105 )\n=========================================================================\n@endnode\n@node Cap1101106 "DT_RATIOTYPE      <Func: 106>"\n=========================================================================\nDT_RATIOTYPE    Aendert oder liefert das ratiotype des users.\n\n                msg->Command = 106\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String ist der RatioType.\n                if msg->Data = 0, then RatioType ist msg->String.\n(FUNCTION #: 106 )\n=========================================================================\n@endnode\n@node Cap1101107 "DT_RATIO          <Func: 107>"\n=========================================================================\nDT_RATIO        Liefert oder aendert das ratio des users.\n\n                msg->Command = 107\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String ist das ratio.\n                if msg->Data = 0, then ratio ist  msg->String.\n(FUNCTION #: 107 )\n=========================================================================\n@endnode\n@node Cap1101108 "DT_COMPTYPE       <Func: 108>"\n=========================================================================\nDT_COMPTYPE     Liefert oder aendert den computertyp des users.\n\n                msg->Command = 108\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String ist der ComputerTypes.\n                if msg->Data = 0, then ComputerTypes ist  msg->String.\n(FUNCTION #: 108 )\n=========================================================================\n@endnode\n@node Cap1101109 "DT_MESSAGESPOSTED <Func: 109>"\n=========================================================================\nDT_MESSAGESPOSTED Liefert oder aendert den Userwert MESSAGESPOSTED\n\n               msg->Command = 109\n               msg->Data    = 1 or 0\n\n               if msg->Data = 1, then msg->String ist das MESSAGESPOSTED.\n               if msg->Data = 0, then MESSAGESPOSTED ist msg->String.\n(FUNCTION #: 109 )\n=========================================================================\n@endnode\n@node Cap1101110 "DT_UPLOADS        <Func: 110>"\n=========================================================================\nDT_UPLOADS     Liefert oder aendert die UserUploads.\n\n                msg->Command = 110\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String sind die uploads.\n                if msg->Data = 0, then uploads ist  msg->String.\n(FUNCTION #: 110 )\n=========================================================================\n@endnode\n@node Cap1101111 "DT_DOWNLOADS      <Func: 111>"\n=========================================================================\nDT_DOWNLOADS   Liefert oder aendert die userdownloads.\n\n                msg->Command = 111\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String sind die downloads.\n                if msg->Data = 0, then downloads ist msg->String.\n(FUNCTION #: 111 )\n=========================================================================\n@endnode\n@node Cap1101112 "DT_TIMESCALLED    <Func: 112>"\n=========================================================================\nDT_TIMESCALLED  Liefert oder aendert die Anzahl der UserCalls.\n\n                msg->Command = 112\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String ist in TIMESCALLED.\n                if msg->Data = 0, then TIMESCALLED ist msg->String.\n(FUNCTION #: 112 )\n=========================================================================\n@endnode\n@node Cap1101113 "DT_TIMELASTON     <Func: 113>"\n=========================================================================\nDT_TIMELASTON   Liefert oder aendert die letze Anrufzeit des users..\n\n                msg->Command = 113\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String ist das TIMESCALLED.\n                if msg->Data = 0, then TIMESCALLED ist msg->String.\n\n                NOTE: Das ist kein Datum,sondern die Zahl der sekunden seit\n                      Januar 19-irgendwas..\n(FUNCTION #: 113 )\n=========================================================================\n@endnode\n@node Cap1101114 "DT_TIMEUSED       <Func: 114>"\n=========================================================================\nDT_TIMEUSED     Liefert oder aendert TIMEUSED today.\n\n                msg->Command = 114\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String ist  TIMEUSED.\n                if msg->Data = 0, then TIMEUSED ist msg->String.\n\n                NOTE: Angabe in sekunden.\n(FUNCTION #: 114 )\n=========================================================================\n@endnode\n@node Cap1101115 "DT_TIMELIMIT      <Func: 115>"\n=========================================================================\nDT_TIMELIMIT    Liefert oder aendert die TimeAllowed (erlaubte Zeit.)\n\n                msg->Command = 115\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String ist das TIMELIMIT.\n                if msg->Data = 0, then TIMELIMIT ist msg->String.\n\n                NOTE: Angabe in sekunden.\n(FUNCTION #: 115 )\n=========================================================================\n@endnode\n@node Cap1101116 "DT_TIMETOTAL      <Func: 116>"\n=========================================================================\nDT_TIMETOTAL   Liefert oder aendert die verbleibende Zeit eines users heute.\n\n\n               msg->Command = 116\n               msg->Data    = 1 or 0\n\n               if msg->Data = 1, then msg->String ist die time remaining.\n               if msg->Data = 0, then time remaining ist  msg->String.\n\n               NOTE: Time in seconds.\n(FUNCTION #: 116 )\n=========================================================================\n@endnode\n@node Cap1101117 "DT_BYTESUPLOAD    <Func: 117>"\n=========================================================================\nDT_BYTESUPLOAD  Liefert oder aendert die uploaded-byes fuer den user..\n\n                msg->Command = 117\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String ist BYTESUPLOADED.\n                if msg->Data = 0, then BYTESUPLOADED ist msg->String.\n(FUNCTION #: 117 )\n=========================================================================\n@endnode\n@node Cap1101118 "DT_BYTEDOWNLOAD   <Func: 118>"\n=========================================================================\nDT_BYTEDOWNLOAD Liefert oder aendert die vom user gedown-ten bytes.\n\n\n               msg->Command = 118\n               msg->Data    = 1 or 0\n\n               if msg->Data = 1, then msg->String ist  BYTESDOWNLOADED.\n               if msg->Data = 0, then BYTESDOWNLOADED ist msg->String.\n(FUNCTION #: 118 )\n=========================================================================\n@endnode\n@node Cap1101119 "DT_DAILYBYTELIMIT <Func: 119>"\n=========================================================================\nDT_DAILYBYTELIMIT Liefert das taegliche byte downloadlimit des users.\n\n\n                  msg->Command = 119\n                  msg->Data    = 1 or 0\n\n                  if msg->Data = 1, then msg->String ist bytelimit.\n                  if msg->Data = 0, then bytelimit ist msg->String.\n(FUNCTION #: 119 )\n=========================================================================\n@endnode\n@node Cap1101120 "DT_DAILYBYTEDLD   <Func: 120>"\n=========================================================================\nDT_DAILYBYTEDLD Liefert oder aendert die taeglich gedown-ten bytes..\n\n                msg->Command = 120\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String ist dailybytes.\n                if msg->Data = 0, then dailybytes ist msg->String.\n(FUNCTION #: 120 )\n=========================================================================\n@endnode\n@node Cap1101121 "DT_EXPERT         <Func: 121>"\n=========================================================================\nDT_EXPERT         Liefert und aendert den expert mode.\n\n                  msg->Command = 121\n                  msg->Data    = 1 or 0\n(FUNCTION #: 121 )\n=========================================================================\n@endnode\n@node Cap1101122 "DT_LINELENGTH     <Func: 122>"\n=========================================================================\nDT_LINELENGTH     Liefert und aendert die Zeilenlaenge (LINELENGTH).\n\n                  msg->Command = 122\n                  msg->Data    = 1 or 0\n\n                  if msg->Data = 1, then msg->String ist LINELENGTH.\n                  if msg->Data = 0, then LINELENGTH ist msg->String.\n(FUNCTION #: 122 )\n=========================================================================\n@endnode\n@node Cap1101123 "ACTIVE_NODES      <Func: 123>"\n=========================================================================\nACTIVE_NODES    Liefert einen string ueber active&inactive nodes.\n\n                msg->Command = 123\n                msg->Data    = N/A\n\n                msg->String ist 10 bytes lang, wobei "X" die aktiven nodes\n                     anzeigt.\n\n                NOTE: Das command wird noch geaendert,da das limit noch bei 9\n                      nodes liegt.\n(FUNCTION #: 123 )\n=========================================================================\n@endnode\n@node Cap1101124 "DT_DUMP           <Func: 124>"\n=========================================================================\nDT_DUMP           Schreibt die user datenstruktur in einen bestimmten file.\n\n\n                  msg->Command = 124\n                  msg->String  = FileName\n(FUNCTION #: 124 )\n=========================================================================\n@endnode\n@node Cap1101125 "DT_TIMEOUT        <Func: 125>"\n=========================================================================\nDT_TIMEOUT       Liefert oder aendert das TIMEOUT limit fuer doors.\n\n                 msg->Command = 125\n                 msg->Data    = 1 or 0\n\n                 if msg->Data = 1, then msg->String wird zu TIMEOUT.\n                 if msg->Data = 0, then TIMEOUT wird zu  msg->String.\n\n                 NOTE: Angabe in sekunden.\n(FUNCTION #: 125 )\n=========================================================================\n@endnode\n@node Cap1101126 "BB_CONFNAME       <Func: 126>"\n=========================================================================\nBB_CONFNAME       Liefert oder aendert den conference namen..\n\n                  msg->Command = 126\n                  msg->Data    = 1 or 0\n\n                  if msg->Data = 1, then msg->String ist der name.\n                  if msg->Data = 0, then name ist msg->String.\n(FUNCTION #: 126 )\n=========================================================================\n@endnode\n@node Cap1101127 "BB_CONFLOCAL      <Func: 127>"\n=========================================================================\nBB_CONFLOCAL    Liefert oder aendert den Ort der conference..\n\n                msg->Command = 127\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String wird die location.\n                if msg->Data = 0, then location ist  msg->String.\n(FUNCTION #: 127 )\n=========================================================================\n@endnode\n@node Cap1101128 "BB_LOCAL          <Func: 128>"\n=========================================================================\nBB_LOCAL          Liefert die momentane BBS location.(Standort)\n\n                  msg->Command = 128\n                  msg->Data    = N/A\n(FUNCTION #: 128 )\n=========================================================================\n@endnode\n@node Cap1101129 "BB_STATUS         <Func: 129>"\n=========================================================================\nBB_STATUS         Liefert den Status der node.\n\n                  msg->Command = 129\n                  msg->Data    = N/A\n\n                  msg->String ist  ''OFFLINE'' oder ''ONLINE'' abhaengig, ob ein\n                  user in der node ist.\n(FUNCTION #: 129 )\n=========================================================================\n@endnode\n@node Cap1101131 "BB_MAINLINE       <Func: 131>"\n=========================================================================\nBB_MAINLINE     Liefert die Eingabe im menuprompt, bet arguments bevor es in\n                das door geht..\n\n                msg->Command = 131\n                msg->Data    = N/A\n\n                msg->String ist die menu prompt eingabe.\n(FUNCTION #: 131 )\n=========================================================================\n@endnode\n@node Cap1101136 "RETURNCOMMAND     <Func: 136>"\n=========================================================================\nRETURNCOMMAND    Man kann hier ein internes command angeben, das ausgefuehrt wird,\n                 wenn das door beendet ist.\n\n                 msg->Command = 136\n                 msg->Data    = N/A\n\n                 command zum ausfuehren ist in msg->String.\n(FUNCTION #: 136 )\n=========================================================================\n@endnode\n@node Cap1101137 "ZMODEMSEND        <Func: 137>"\n=========================================================================\nZMODEMSEND      Schickt files mit dem Zmodem protocol.\n\n                msg->Command = 137\n                msg->String  = filename (complete pathname)\n                msg->Data    = N/A\n\n                Ergebnis des transfers in msg->Data, wobei\n\n                if msg->Data = 1 , then transfer erfolgreich\n                if msg->Data = -2, then carrierverlusst.\n                if msg->Data = 0 , then transfer fehlgeschlagen.\n(FUNCTION #: 137 )\n=========================================================================\n@endnode\n@node Cap1101138 "ZMODEMRECEIVE     <Func: 138>"\n=========================================================================\nZMODEMRECEIVE    Man empfaengt einen batch uploads via Zmodem protocol.\n\n                 msg->Command = 138\n                 msg->String  = receive directory path\n                 msg->Data    = N/A\n\n                 Ergebnis steht in msg->Data, wobei\n\n                 if msg->Data = 1 , then transfer erfolgreich\n                 if msg->Data = -2, then carrierverlusst\n                 if msg->Data = 0,  then transfer fehlgeschlagen.\n(FUNCTION #: 138 )\n=========================================================================\n@endnode\n@node Cap1101139 "SCREEN_ADDRESS    <Func: 139>"\n=========================================================================\nSCREEN_ADDRESS    Liefert die addresse des screens.\n\n                  msg->Command = 139\n                  msg->Data    = N/A\n\n                  msg->String ist ein string mit der hexadecimal addresse\n                  des node screens.\n(FUNCTION #: 139 )\n=========================================================================\n@endnode\n@node Cap1101140 "BB_TASKPRI        <Func: 140>"\n=========================================================================\nBB_TASKPRI    Liefert die prioritaet, mit der die node laeuft.\n\n              msg->Command = 140\n              msg->Data    = N/A\n\n              msg->String liefert die prioritaet..\n(FUNCTION #: 140 )\n=========================================================================\n@endnode\n@node Cap1101141 "RAWSCREEN_ADDRESS <Func: 141>"\n=========================================================================\nRAWSCREEN_ADDRESS Liefert die addresse des screens der node..\n\n              msg->Command = 141\n              msg->Data    = N/A\n\n              msg->String liefert die decimal address\n                   der express node.\n(FUNCTION #: 141 )\n=========================================================================\n@endnode\n@node Cap1101142 "BB_CHATFLAG       <Func: 142>"\n=========================================================================\nBB_CHATFLAG       Liefert die momentanen chat settings..\n\n                  msg->Command = 142\n                  msg->Data    = N/A\n\n                  msg->String will be "ON" or "OFF".\n(FUNCTION #: 142 )\n=========================================================================\n@endnode\n@node Cap1101143 "DT_STAMP_LASTON   <Func: 143>"\n=========================================================================\nDT_STAMP_LASTON Liefert einen Datumsstring, der das datum ist, wann der user\n                zuletzt eingeloggt war.\n\n                msg->Command = 143\n                msg->Data    = N/A\n\n                msg->String ist der datumstring\n(FUNCTION #: 143 )\n=========================================================================\n@endnode\n@node Cap1101144 "DT_STAMP_CTIME    <Func: 144>"\n=========================================================================\nDT_STAMP_CTIME    Liefert die aktuelle Zeiteinstellung.\n\n                  msg->Command = 144\n                  msg->Data    = N/A\n\n                  msg->String ist ein aktueller Zeit string.\n(FUNCTION #: 144 )\n=========================================================================\n@endnode\n@node Cap1101145 "DT_CURR_TIME      <Func: 145>"\n=========================================================================\nDT_CURR_TIME     Liefert die aktuelle Zeit in sekunden seit Januar 19-irgendwas.\n\n\n                 msg->Command = 145\n                 msg->Data    = N/A\n\n                 msg->String ist die sekundenzeit.\n(FUNCTION #: 145 )\n=========================================================================\n@endnode\n@node Cap1101146 "DT_CONFACCESS     <Func: 146>"\n=========================================================================\nDT_CONFACCESS     Liefert den Access des users fuer conferences.\n\n                  msg->Command = 146\n                  msg->Data    = 1 or 0\n\n                  if msg->Data = 1, then msg->String ist der AREANAME.\n                  if msg->Data = 0, then AREANAME ist msg->String.\n\n(FUNCTION #: 146 )\n=========================================================================\n@endnode\n@node Cap1101149 "BB_NODEID         <Func: 149>"\n=========================================================================\nBB_NODEID         Liefert die  Node nummer dieser node.\n\n\n                  msg->Command = 149\n                  msg->Data    = N/A\n\n                  msg->String ist die nodenummer\n(FUNCTION #: 149 )\n=========================================================================\n@endnode\n@node Cap1101150 "BB_CALLERSLOG     <Func: 150>"\n=========================================================================\nBB_CALLERSLOG     Macht einen Eintrag ins CALLERSLOG.\n\n                  msg->Command = 150\n                  msg->String  = text\n                  msg->Data    = N/A\n(FUNCTION #: 150 )\n=========================================================================\n@endnode\n@node Cap1101151 "BB_UDLOG          <Func: 151>"\n=========================================================================\nBB_UDLOG          Macht eien Eintrag ins UDLOG.\n\n                  msg->Command = 151\n                  msg->String  = text\n                  msg->Data    = N/A\n(FUNCTION #: 151 )\n=========================================================================\n@endnode\n@node Cap1101152 "EXPRESS_VERSION   <Func: 152>"\n=========================================================================\nEXPRESS_VERSION   Liefert den versionsstring von \X.\n\n\n                  msg->Command = 152\n                  msg->Data    = N/A\n(FUNCTION #: 152 )\n=========================================================================\n@endnode\n@node Cap1101162 "BB_CHATSET        <Func: 162>"\n=========================================================================\nBB_CHATSET     Liefert oder aendert den chatstatus..\n\n               msg->Command = 162\n               msg->Data    = 1 or 0\n\n               if msg->Data = 1, then msg->String ist der status.\n               if msg->Data = 0, then status ist msg->String.\n(FUNCTION #: 162 )\n=========================================================================\n@endnode\n@node Cap1101163 "ENVSTAT           <Func: 163>"\n=========================================================================\nENVSTAT          Liefert oder aendert den momentanen Wert einer ENV STAT\n                 variablen.\n\n                 msg->Command = 163\n                 msg->Data    = 1 or 0\n\n                 if msg->Data = 1, then msg->String ist der status.\n                 if msg->Data = 0, then status ist msg->String.\n(FUNCTION #: 163 )\n=========================================================================\n@endnode\n@node Cap1101503 "NODE_DEVICE       <Func: 503>"\n=========================================================================\nNODE_DEVICE       Liefert den devicenamen der node..\n\n                  msg->Command = 503\n                  msg->Data    = N/A\n\n                  msg->String ist der device string.\n(FUNCTION #: 503 )\n=========================================================================\n@endnode\n@node Cap1101504 "NODE_UNIT         <Func: 504>"\n=========================================================================\nNODE_UNIT         Liefet die unitnummer der node..\n\n                  msg->Command = 504\n                  msg->Data    = N/A\n\n                  msg->String ist die nummer\n(FUNCTION #: 504 )\n=========================================================================\n@endnode\n@node Cap1101505 "NODE_BAUD         <Func: 505>"\n=========================================================================\nNODE_BAUD    Liefert die eingestellte Baudrate der node..\n\n             msg->Command = 505\n             msg->Data    = N/A\n\n             msg->String ist die INIT baud rate.\n(FUNCTION #: 505 )\n=========================================================================\n@endnode\n@node Cap1101507 "JH_MCI            <Func: 507>"\n=========================================================================\nJH_MCI            Schickt einen MCI text an express.\n\n                  msg->Command = 507\n                  msg->String  = text\n                  msg->Data    = N/A\n(FUNCTION #: 507 )\n=========================================================================\n@endnode\n@node Cap1101508 "PRV_COMMAND       <Func: 508>"\n=========================================================================\nPRV_COMMAND       Fuehrt sofort ein internes menu command von \X aus.\n\n\n                  msg->Command = 508\n                  msg->String  = commandstring\n                  msg->Data    = N/A\n(FUNCTION #: 508 )\n=========================================================================\n@endnode\n@node Cap1101510 "BB_CONFNUM        <Func: 510>"\n=========================================================================\nBB_CONFNUM     Liefert die momentan conference nummer..\n\n               msg->Command = 510\n               msg->Data    = N/A\n\n               msg->String ist conference nummer zwischen 0 u. 8.\n(FUNCTION #: 510 )\n=========================================================================\n@endnode\n@node Cap1101511 "BB_DROPDTR        <Func: 511>"\n=========================================================================\nBB_DROPDTR        Schalted dem carrier fuer einen user ab.\n\n                  msg->Command = 511\n                  msg->Data    = N/A\n(FUNCTION #: 511 )\n=========================================================================\n@endnode\n@node Cap1101512 "BB_GETTASK        <Func: 512>"\n=========================================================================\nBB_GETTASK        Gibt die taskaddresse der node an..\n\n                  msg->Command = 512\n                  msg->Data    = N/A\n\n                  msg->task ist die addresse des tasks.\n(FUNCTION #: 512 )\n=========================================================================\n@endnode\n@node Cap1101516 "NODE_BAUDRATE     <Func: 516>"\n=========================================================================\nNODE_BAUDRATE     Liefert die connect-rate der users.\n\n                  msg->Command = 516\n                  msg->Data    = N/A\n\n                  msg->String ist die connect rate\n(FUNCTION #: 516 )\n=========================================================================\n@endnode\n@node Cap1101517 "BB_LOGONTYPE      <Func: 517>"\n=========================================================================\nBB_LOGONTYPE      Liefert den LOGONTYPE.\n\n                  msg->Command = 517\n                  msg->Data    = N/A\n\n                  msg->Data kann sein:\n\n                  0 = AWAIT_LOGON\n                  1 = SYSOP_LOGON\n                  2 = LOCAL_LOGON\n                  3 = REMOTE_LOGON\n(FUNCTION #: 517 )\n=========================================================================\n@endnode\n@node Cap1101518 "BB_SCRLEFT        <Func: 518>"\n=========================================================================\nBB_SCRLEFT      Liefert die screen coordinaten.\n\n                msg->Command = 518\n                msg->Data    = N/A\n\n                msg->Data ist die obere linke ecke der node..\n(FUNCTION #: 518 )\n=========================================================================\n@endnode\n@node Cap1101519 "BB_SCRTOP         <Func: 519>"\n=========================================================================\nBB_SCRTOP        Liefert die screen coordinaten..\n\n                 msg->Command = 519\n                 msg->Data    = N/A\n\n                 msg->Data ist die oberste Zeile der node.\n(FUNCTION #: 519 )\n=========================================================================\n@endnode\n@node Cap1101520 "BB_SCRWIDTH       <Func: 520>"\n=========================================================================\nBB_SCRWIDTH       Leifert die screencoordinaten..\n\n                  msg->Command = 520\n                  msg->Data    = N/A\n\n                  msg->Data ist die hoehe des node screens.\n(FUNCTION #: 520 )\n=========================================================================\n@endnode\n@node Cap1101521 "BB_SCRHEIGHT      <Func: 521>"\n=========================================================================\nBB_SCRHEIGHT      Liefert screen coordinaten.\n\n                  msg->Command = 521\n                  msg->Data    = N/A\n\n                  msg->Data ist die breite des nodescreens..\n(FUNCTION #: 521 )\n=========================================================================\n@endnode\n@node Cap1101522 "BB_PURGELIN       <Func: 522>"\n=========================================================================\nBB_PURGELIN   Bricht die serielle Eingabe ab.\n\n               msg->Command = 522\n               msg->Data    = N/A\n\n              Bricht serrial input ab und flushed den serial buffer und meldet\n              bereit fuer weitere eingabe.\n(FUNCTION #: 522 )\n=========================================================================\n@endnode\n@node Cap1101523 "BB_PURGELINESTART <Func: 523>"\n=========================================================================\nBB_PURGELINESTART Loescht den serial buffer und meldet bereit fuer weiteren\n                  serial input.\n\n                  msg->Command = 523\n                  msg->Data    = N/A\n(FUNCTION #: 523 )\n=========================================================================\n@endnode\n@node Cap1101524 "BB_PURGELINEEND   <Func: 524>"\n=========================================================================\nBB_PURGELINEEND   Loescht den serial buffer..\n\n                  msg->Command = 524\n                  msg->Data    = N/A\n(FUNCTION #: 524 )\n=========================================================================\n@endnode\n@node Cap1101525 "BB_NONSTOPTEXT    <Func: 525>"\n=========================================================================\nBB_NONSTOPTEXT    Aendert das NONSTOP text scrolling flag.\n\n                  msg->Command = 525\n                  msg->Data    = 1 or 0\n\n                  if msg->Data = 1, then display text macht keine pause.\n                  if msg->Data = 0, then display text macht pause.\n(FUNCTION #: 525 )\n=========================================================================\n@endnode\n@node Cap1101526 "BB_LINECOUNT      <Func: 526>"\n=========================================================================\nBB_LINECOUNT   Liefert oder aendert die anzahl der vom user sichtbaren zeilen.\n\n\n               msg->Command = 526\n               msg->Data    = 1 or 0\n\n               if msg->Data = 1, then msg->String ist die momentane Zeile.\n               if msg->Data = 0, then momentane Zeile ist  msg->String.\n(FUNCTION #: 526 )\n=========================================================================\n@endnode\n@node Cap1101527 "DT_LANGUAGE       <Func: 527>"\n=========================================================================\nDT_LANGUAGE      Liefert oder aendert die momentane Spracheinstellung.\n\n\n                 msg->Command = 527\n                 msg->Data    = 1 or 0\n\n                 if msg->Data = 1, then msg->String ist die Sprache.\n                 if msg->Data = 0, then die Sprache ist msg->String.\n\n                NOTE: Sprachen muessen standartisiert sein, nach diversen\n                      Richtlinien.\n\n                ie:  Default language .TXT\n                     English          .ENG\n                     German           .GER\n\n                     Das hat nur einfluss in  menus, bulletins &\n                     anderen screen text files.\n(FUNCTION #: 527 )\n=========================================================================\n@endnode\n@node Cap1101528 "DT_QUICKFLAG      <Func: 528>"\n=========================================================================\nDT_QUICKFLAG      Aendert das QUICKTEXT flag.\n\n                  msg->Command = 528\n                  msg->Data    = 1 or 0\n\n                  if msg->Data = 1, then the QuickFlag ist gesetzt.\n                  if msg->Data = 0, then the QuickFlag ist nicht gesetzt\n(FUNCTION #: 528 )\n=========================================================================\n@endnode\n@node Cap1101529 "DT_GOODFILE       <Func: 529>"\n=========================================================================\nDT_GOODFILE       Setzt dasErgenis eines geprueften files nach dem upload.\n\n\n                  msg->Command = 529\n                  msg->Data    = 1,0 or -1\n\n                  if msg->Data is 1, then the file nicht geprueft.\n                  if msg->Data is 0, then the file file war ok..\n                  if msg->Data is -1, then the file ist fehlerhaft.\n\n                  NOTE: Das command macht nur sinn mit dem SYSCmd door\n                  namens FILECHECK.\n(FUNCTION #: 529 )\n=========================================================================\n@endnode\n@node Cap1103 "Traditional Interface Module (TIM)\n=========================================================================\n\n  Das traditonelle interface bieted die moeglichkeit,DOORS zu starten, die\n  fuer andere BBS entworfen wurden.Das heisst nicht, das alle door funktionieren,\n  aber einige tun das.Das traditioinelle interface heisst PARADOOR.Es wird mit\n  \X mitgeliefert und muss sich im pfad befinden, damit es \X findet.Wenn\n  ein carrierverlust oder ein keyboard TIMEOUT auftritt, verstaendigt das BBS\n  das modul, das dann selbst stoppen sollte.Die meisten Programmierer haben das\n  gu geregelt.PARADOOR wird von \X gestarted und bitte nicht vom dir !\n\n=========================================================================\n@endnode\n@node Cap1104 "AmiExpress Interface Module System (XIM)...."\n=========================================================================\n\n  Mein interface ist das allerbeste, weil alles obige darinsteckt.\n  Das gute ist, dass man kein eigenes Programm bracuht, um es zu verwenden.\n  Es wird sicher eine Menge guter Module geben, in Zukunft, es wurden aber\n  auch schon viele gemacht.\n\n\n        ___________ message structure fuer die  XIMs\n       |            NOTE: RexxDoors werden auf diese struktur uebersetzt\n       v            ~~~~  mittels REXXDOOR utility\nstruct JHMessage\n{\n  struct Message Msg;   <----- msg structure\n  char String[200];     <----- info buffer\n  int Data;             <----- Read/Write & result indicator\n  int Command;          <----- Command sent from door.\n  int NODEID;           <----- reserved\n  int LineNum;          <----- reserved\n  unsigned long signal; <----- reserved\n  struct Process *task; <----- see BB_GETTASK below\n\n} ;\n\nPORTNAME: The portname fuer XIMs is ''AEDoorPors(n)'' ie: AEDoorPort1\n=========================================================================\n@endnode\n@node Cap1105 "AmiExpress CLI Interface (XIM)...."\n=========================================================================\n\n  Dieses neue interface kann verwendet werden fuer cli doors.Nicht alle laufen\n  ordentlich, man muss ausprobieren..\n\n  Setup procedure:\n\n        1st: Man braucht den fifo-handler im L: directory, ausserdem die\n             Fifo.Library im Libs: directory. Man braucht davon\n             version 0.4 der Fifo.Library.\n\n        2nd: Diese Zeilen bitte in die user-startup,\n\n             -------> assign AXCLI: DOORS:CliConFigs\n             -------> run >NIL: <NIL: L:Fifo-Handler\n\n        3rd: Man macht ein dir in doors: namens cliconfigs.\n             Das dir enthaelt dann configfiles fuer jedes door, das laufen soll.\n             Diese muessen den doornamen haben und auf .cfg enden, sie kontrollieren\n             den pfad zu den doors und enthalten erlaubte und verbotene tastatur\n             eingaben.\n\n    THIS IS AN EXAMPLE CFG FILE:\n\n            doors:contris/contris! ~N\n            BREAK_C\n\n        Die erste zeile ist die startzeile.Die filgende ist die filter option:\n\n            BREAK_C -----> Allows Ctrl C\n            BREAK_D -----> Allows Ctrl D\n            BREAK_E -----> Allows Ctrl E\n            BREAK_F -----> Allows Ctrl F\n            RAWMODE -----> Allows Unfiltered IO\n\n                  ~~~~~~~~~~~~ WARNING ~~~~~~~~~~~~~~\n\n        Wie man sieht sind cli doors recht gefaehrlich.Hat man die falsche\n        option im cfg file, oeffnet sich dem user das ganze bbs.\n        Es kann das cli stoppen und dann im system umherwandert...\n\n\n        Sie sollten versuchen hier mit dem multi-user filesystem fuer sicherheit\n        zu sorgen. Ich bin nicht verantwortlich, wenn einer in ihr system\n        einbricht..Sie sind gewarnt...\n\n=========================================================================\n@endnode\n@node Cap12 "The MCI imbedded ControlSequence...."\n=========================================================================\n\n  Jeder TExt kann eingebundene control sequences enthalten, die variablen\n  einsetzen koennen, oder bestimmte dinge verursachen koennen.\n\n  MCI - Introducer:\n  ~~~~~~~~~~~~~~~~\n  ~ Das ist die MCI Kennung, sie muss am beginn jedes textfiles stehen,\n    damit \X in den MCI interpreter geht, wenn es den text anzeigt.\n\n\n  MCI - User Specification:\n  ~~~~~~~~~~~~~~~~~~~~~~~~\n\n  ~N       User Name\n  ~IN      User Internet Name\n  ~RN      User Realname\n  ~UL      User Location\n  ~P       User Password\n  ~#       User Phone\n  ~TC      Total User Calls\n  ~LC      User Last Call to the system\n  ~M       User Message Posted\n  ~A       User Access Level\n  ~S       User Slot Number\n  ~CA      User Conf. Access    **** NOTE CHANGED FROM X ****\n  ~BR      User BaudRate\n  ~HW      User Computer Equipment\n  ~TL      User Initial Time Limit at logon in Minutes\n  ~TR      User Number of Mins Remaining today\n  ~UB      User Bytes Uploaded\n  ~DB      User Bytes Downloaded\n  ~FU      User Files Uploaded\n  ~FD      User Files Downloaded\n  ~BD      User Byte Download Limit\n  ~LG      User Logged On-Node\n  ~DX      Change the MCI command terminator.\n           i.e.: ~D.| will change the ''|'' to ''.''\n\n\n  ~OD      Online Since Date\n  ~OT      Online Since Time\n  ~CX      aendert vordergrund ansi color auf werte von 0-f.\n  ~BX      aendert hintergrund color auf werte von 0-f.\n  ~H       Back Space\n  ~Q       Change to default ANSI mode.\n  ~F       Clear Screen.\n  ~Nx      Neue Zeilen, wo x deren Anzahl ist.\n  ~~       Sagt, dass man das  ~ Zeichen darsellen will.Man kann beliebig viele\n           darstellen, nach dem ersten ~.\n           (NOTE: kein '','' bei diesem command)\n  ~xN      Goto X position on screen. ie: ~x10\n  ~yN      Goto Y position on screen. ie: ~y10\n\n  NOTE: Obige commands erlauben die Breitenangabe vor dem command.\n  ~~~~\n        ~10N wuerde nur die ersten 10 buchtaben des usernamens zeigen.\n\n  MCI - System Specification:\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n  ~SC     System Total calls\n  ~CT     Show current Time\n  ~DT     Show current Date\n\n  MCI - Extra Specification:\n  ~~~~~~~~~~~~~~~~~~~~~~~~~\n\n  ~CR         warten auf return\n  ~CR_Prompt  warted auf den druck irgendeiner taste\n              ie: ~CR_PressAnyKey\n  ~SP         eine standard pause, nuetzlich um es zwischen\n              ~SS commands zu setzen.\n\n  ~<xx>SR_<screens>\n              Hiermit kann man zufaellige TExtfiles anzeigen.\n              <xx> ist die maximale Zahl der zufallsfiles, die gewechselt\n              werden koennen, <screens> ist der volle pfad zu den textfiles\n              , die man zufaellig anzeigen will.\n              (ohne das.TXT)\n\n  ~SS_Name    Show <name> file. Diese file kann auch ein MCI file sein.\n\n            WARNING: Das command koennte ein Schleifenproblem bringen, wenn man\n            ~~~~~~~  im file wieder den gleichen file anzeigt..\n            WARNING: Man muss den STACK eroehen, wenn man viele files so\n            ~~~~~~~  anzeigt.\n\n            NOTE: Wird das command ueber die message base oder mit\n            ~~~~  View oder ViewSysop commands verwand, sollte der file einen\n                  commentar wie ''Allowed'' or ''{xxx}Allowed'' haben.\n\n                 {xxx} gibt das level oder hoeher an e:\n\n                 {050}Allowed, sagt, dass nur die ueber oder gleich dieses\n                               access levels diesen file sehen koennen.\n\n\n  ~SR  - Show Random Files\n\n  SYNTAX: ~<numb>SR_<fileid>\n\n           ^    ^  ^\n           |    |  |\n           |    |  ---------- pathname ohne security level und file\n           |    |             endung\n           |    ------------- Command zum zeigen der zufallsfiles\n           ------------------ Anzahl der zufallsfiles\n\n  IE: ~10SR_BBS:Logon\n\n  Das sucht einen Zufallsfile zwischen 1-10,die syntax fuer den file ist:\n\n\n  SYNTAX: PathName<seq>.FileName[security level]<extension>\n\n  IE: BBS:001.Logon200.TXT\n\n\n  Das waere der erste von 10 files, die angelgt werden, um mit der Zufallsfunktion\n  angezeigt zu werden.Das ''200'' ist der sicherheitslevel, der nicht gegeben werden\n  muss.\n\n\n  ~SX  - Show Sequentual Files\n\n  SYNTAX: ~SX_<fileid>\n\n           ^  ^\n           |  |\n           |  ---------- pathname ohne sicherheitslevel und fileendung\n           |\n           ------------- Command zum zeigen sequentieller files\n\n  IE: ~SX_BBS:Logon\n\n  1. Es such einen file namens BBS:Logon , der die letze sequence von\n     <fileid>`s einthaelt, die gezeigt wurden.Gibt`s den nicht, wird das\n     ''SX'' command ihn generieren.\n  2. Es macht dann einen display_file_name basierend auf der naechsten sequence\n     nummer folgendermassen:\n\n     SYNTAX: PathName<seq>.FileName\n\n  3. Es sucht dann den entprechenden file zum anzeigen.Der eigentliche\n     ASCII file sollte folgende informationen des files enthalten:\n\n     SYNTAX: PathName<seq>.FileName[security level]<extension>\n\n     IE: BBS:001.Logon200.TXT --v\n         BBS:001.Logon100.TXT ----- man kann versciedene security level anhaengen,\n                                    man muss aber nicht.\n         BBS:002.Logon200.TXT\n\n\n  ~CC_Name    Started ein door namens ''Name''..\n              ie: ~CC_WHO sucht in SYSCMD, BBSCmd und CONF<x>CMD\n                  directory, die im\n                  BBS:Commands directory sein muessen.\n\n  ~CC_WHO\n\n  NOTE: Es ist wichtig, dass die meisten MENU COMMANDS nur vom MENU PROMPT\n        gestarted werden sollten.PT. unklug waere das lesen von mail\n        Also bilde dir ein eigenes Urteil ueber deise Dinge.\n\n  ~CL         Zeigt eine liste der conferences, wird normalerweise im\n              JoinConf.TXT file verwendet.\n\n      *******************************************************************\n      NOTE: Alle MCI Commands muessen auf SPACE oder ein ''|'' SYMBOL\n                     enden.Gross und Kleinshreibung wird unterschieden !\n      *******************************************************************\n\n      Wir haben folgende Textzeile:\n      ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n      ~N , I hope everything is going well in ~L .\n\n      Koente zeigen:\n      ~~~~~~~~~~\n      Joseph Hodge, I hope everything is going well in Virginia.\n\n=========================================================================\n@endnode\n@node Cap13 "Notable Features of AmiExpress..."\n=========================================================================\n\n 1. Eine command-history erinnert sich an die letzten 20 commands.Nach dem\n    limit von 20 beginnt der Zyklus wieder von vorne.CTRL-B loescht die\n    history.\n\n\n 2. Die HELP taste enthaelt ein screen_nach_hinten command.\n\n 3. Das BBS prueft, ob AUXx: oder CNN: geoeffnet werden koennen\n    und meldet Probleme.\n\n 4. Baud Calling Zeiten wurden eingebaut, werden warscheinlich nochmal geaendert.\n    Man gibt die baudrate und zeit an, zu der man damit anrufen kann.\n    Sind alle Zeiten alle baudraten erlaubt, gibt man 0 fuer den begin und\n    2359 füer`s ende an.Anfangszeiten muessen kleiner als Endzeiten sein.\n    Das ganze wird sich n Zukunft noch aendern und wird leichter einzustellen\n    sein.\n\n 5. AREXX port ''AmiExpress_Node.x'', unterstuetzt folgende features:\n\n     suspend - BBS schliesst serialport,iconifiziert sich und warted auf\n               weitere commands.Wenn einer online ist, warted das BBS mit diesem\n               command bis er offline ist.Damit kann man batchfiles schreiben, die\n               das BBS stoppen, um dann ein terminalprogramm zu laden und\n               dannach wieder das BBS zu starten.\n\n               Ein Programm in Arexx saehe so aus:\n\n\n            ------------- cut here ------------------\n               /* The Suspend Command for AmiExpress V4.0 */\n               address ''AmiExpress_Node.1''\n               ''suspend''\n            ------------ cut here -------------------\n\n\n     resume  - Das commando geh nur, wenn`s BBS suspended ist.\n\n     shutdown - commando verringert die onlinezeit des users auf 2 min.\n                und sagt dem user, dass er herunterfahren muss.Wenn der user\n                aus dem bbs ist, verlaesst das BBS den speicher.\n\n\n     NOTE: Keine dieser funktionen laeuft ohne Arexx.\n\n    Es wird in Zukunft viele Arexx commands geben,inklusive eines\n    node to node chats..\n\n 6. Automatic Zmodem upload, wenn ein user den Zmodem upload im\n    main prompt das BBS started, stellt das BBS das fest und beginnt mit\n    den Zmodem-routinen.\n\n 7. SYSOP kann nun eine node im Hintergrund laufen lassen, fuer localen Gebrauch.\n    Dafuer muss man den devicenamen aus dem confignamen nehmen, damit das\n    BBS nicht an den serial port will.\n\n=========================================================================\n@endnode\n@node Cap14 "Note worthy of Mention...."\n=========================================================================\n\nIch danke .... Mai,Papi,Oma, Opa ,,,\n---\n  I would personally like to thank Joseph Hodge, who has painstakingly,\n  and endlessly programmed, and put up with us. It is not easy to try and\n  make a program do what everyone wants. I still do not know to this day\n  why he choose to carry on with AmiExpress but I sure am appreciative,\n  It has been a wonderful learning experience in both the programming world\n  and friendships. We have become like brothers, and like brothers will be\n  together through the good times and bad times.\n\n  I would also personally like to thank all of the wonderful people listed\n  on the ACP credits menu. They are great people, and have a lot of patience\n  and enthusiasm in making express the best BBS program around.\n\n  I would also like to thank all the distributors and users who have helped\n  the development of express. It is heart warming to see the devotion that\n  comes from the registered users, more devotion then we ever expected.\n\n  Enjoy the BBS, once setup will assuredly become second nature to run.\n  It is a fantastic program, and we all have Joseph Hodge to thank for\n  it''s developement.\n---\n        Hier die addresse fuer bugreports und andere Dinge::\n\n               -------------------------------------------\n               LightSpeed Technologies Inc. (305) 964-4263\n               -------------------------------------------\n\n                          Or Mail to:\n\n                          LightSpeed Technologies Inc.\n                          P.O. Box 4435\n                          Hollywood, Fl. 33083-4435\n\n=========================================================================\n@endnode\n@node Cap15 "QWK Mail Support...."\n=========================================================================\n\n  In der ''W'' option für users gibt es nun fuer den user die Moeglichkeit zu sagen,\n  welche Art von ZOOM er will.Er kann QWK oder das alte ascii waehlen.\n\n\n     NOTE: Man muss zuerst einige neue Icons im ZOOM dir installieren, sonst\n           geht`s nicht. 3 Icons sind noetig::\n\n           QWKCFG  --> mit folgenden tooltypes:\n\n                       BBS.NUMBER=<YOUR PHONE NUMBER> IE: 1-305-964-4263\n\n                       BBS.ADDRESS=<ONE LINE ADDRESS> IE: FLORIDA\n\n           QWPACK  --> mit den tooltypes:\n\n                       LHA=c:LHA a\n                       ZIP=c:ZIP -0\n\n           ASCPACK --> mit den tooltypes:\n\n                       LHA=c:LHA a\n                       ZIP=c:ZIP -0\n\n           Stelle das fuer deine Beduerfnisse ein...\n\n\n  Jetzt kann man die Antwormessage uebr das QWK interface senden.\n         Man braucht dazu:\n\n         To install:\n\n\n   First: Mach ein Icon SQWK und setze das nach bbs:cmds . Es ist ein\n          XIM door.\n\n  Second: Setze den sqwk file ins doors: dir.\n\n   Third: setze den sqwkmerge file ins BBS:utils dir. Installation fertig.\n\n\n\n         Nun muss man als user nur SQWK im MENUPROMPT druecken.\n         Das BBS erwarted dann deine QWK mail.\n         Schicke nur dein reply packet ins upload.\n         Es sollte die endung .REP haben.Der user kann weitermachen,\n         waehrend QWK die mail entpackt.\n\n\n\n=========================================================================\n@endnode\n@node Cap16 "Icon Script Language Support...."\n=========================================================================\n\n       In der version 4.0 kann acp all die icons grob anlegen. Auch leute,\n       die nicht wissen, wie man ein bbs betreibt koennen das schaffen, mit\n       dem script file, der sich im s:dir der main support disk befindet.\n       Einfach den setup-button von acp betaetigen.\n       Toll ist, dass Door-programmierer scriptfiles liefern koennen, die\n       automatisch die directories,icon,,anlegen. Setze dazu einfach deine\n       commands ins Icon, mit dem acp-installerm so wie du meinst,ohne dich\n       darum kuemmern zu muessen, wie man das programm insalliert:::\n\n       Der mitgelieferte script file provided generiert ein standart \X.Mann kann dann\n       loeschen/hinzufuegen, wie man will.Es wird ein bbs im RAM: generiert, also\n       pass auf, denn wenn man die script auf BBS: aendert, uebershreibt es\n       eventuel vorhandene files.......\n\n       Wenn acp kein configuriertes BBS findet, kommt ein requester, der nach\n       dem scriptfile fragt.Wenn man aeicon.config im dh0:s dir hat,konfiguriert\n       es automatisch ein neues BBS.Du musst dan nur die icons einstellen, die sich\n       im storage dir befinden.\n       Die setup procedure verwendet diese icons fuer`s drueberkopieren und\n       verwendet auch den script file dazu.Jetzt kann man die Icons aender,\n       wie man will, ebenso die options in den icons.\n       Im script file (aeicon.config) sieht man eine erklaerung der options\n       Ich sage dazu nichts mehr, da es sich selbst erklaert.\n\n=========================================================================\n@endnode\n@node Cap17 "Trouble Shooting...."\n=========================================================================\n\n  Problem                            Solution\n  --------------------------------   -----------------------------------\n  ACP started nicht.                1. ACP muss von startup-sequence oder\n                                        WB gestarted werden.\n                                     2. Mache eine shell auf und starte ACP von dort.\n                                        Man sollte eine Fehlermeldung sehen.\n\n                                     3. Ist das Icon im gleichen dir, wie das\n                                        Program\n  Express started nicht, aber\n  ACP tut`s.                         1. Wenn man einen batchfile zum start von \X\n                                        nimtm muss das S bit gesetzt sein.\n\n                                        PROTECT S:BBS.Startup +s\n                                                ^\n                                                |\n                                                batch filename\n                                      2. Gehe in der shell in`s \X dir und\n                                         gib ein:\n\n\n                                          Express 0\n                                                  ^\n                                                  |___ (node number)\n\n                                         eine fehlermeldung sollte kommen\n\n\n  ACP und EXPRESS starten, aber       1. Der stack von \X stimmt stimmt nicht.\n  beim msgbase scan macht express         Der stack muss 50000 sein.\n  einen guru\n\n  ACP kommt ohne die                  1. ueberpruefe::\n  NODE buttons.                           NUMBER_OF_NODES x existiert, wobei\n                                          <x> die nummer der nodes ist .\n\n\n  Mein modem initialisiert nicht ..   1. Ist die Unit korrekt eingestellt.\n\n\n                                       2. Stimmt der DEVICE_NAME\n\n\n                                       3. Hast du einen\n                                          MODEM_INIT string im MODEMICON.\n\n\n  Im  CALLERSLOG:                   1. Wurde das e\n    Error Reading MsgBase Pointer         CONFDB Utility richtig gestarted ?\n  ..steht drin                        1> CONFDB BBS:CONF/ <max.Usernumber>\n\n                                       2. gibt`s CONF.DB in jeder conference\n                                          die man hat\n\n                                       3. ist vielleicht die Usernumber\n                                          beim anlegen von\n                                          CONF.DB kleier gewesen, als die aktuelle\n                                          Anzahl.\n\n=========================================================================\n@endnode\n@node Cap18 "Future planned Enhancements.."\n=========================================================================\n\nWir erweitern staendig das \X.Einige Erweiterung werrden als updates\nnoch kommen:\n\n\n    Volle Internet unterstuetzung upload/download ins internet.\n    lesen/schreiben in einer conference ins internet.\n\n\n    Also Leutz, open Ya eYeZ, eine Menge toller Dinge kommt auf euch zu ...\n\n\n\n=========================================================================\n@endnode\n','\n',char(10)),'{"STACK":"<stack>","LOCATION":"<dir>-","PRIORITY":"<numb>","ACCESS":"<numb>","TYPE":"-"}','auto-added',70312,5,0,NULL,NULL,'aedoc4g','scan',1780048372);
INSERT INTO door_catalog VALUES('aedoor','AEDOOR.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AEDOOR.LHA','MultiDoorShutdown','XIM','aedoor',NULL,NULL,NULL,'| ---------------------------------------- | |       HOW TO CODE AMIEXPRESSDOORS        | | ---------------------------------------- |',replace('.------------------------------------------.\n| ---------------------------------------- |\n|       HOW TO CODE AMIEXPRESSDOORS        |\n| ---------------------------------------- |\n| Examples in: Hspascal, Assembler, Sac C, |\n|              and Amiga E                 |\n| Full documentations and includefiles     |\n| ---------------------------------------- |\n`------------------------------------------''\n','\n',char(10)),'AEDoor.doc',replace('TABLE OF CONTENTS\n\nAEDoor.library/CreateComm\nAEDoor.library/DeleteComm\nAEDoor.library/SendCmd\nAEDoor.library/SendStrCmd\nAEDoor.library/SendDataCmd\nAEDoor.library/SendStrDataCmd\nAEDoor.library/GetData\nAEDoor.library/GetString\nAEDoor.library/Prompt\nAEDoor.library/WriteStr\nAEDoor.library/ShowGFile\nAEDoor.library/ShowFile\nAEDoor.library/SetDT\nAEDoor.library/GetDT\nAEDoor.library/GetStr\nAEDoor.library/CopyStr\nAEDoor.library/HotKey\nAEDoor.library/PreCreateComm\nAEDoor.library/PostDeleteComm\nINSERT INTO door_catalog VALUES('aedoor28','AEDOOR28.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AEDOOR28.LHA','MultiDoorShutdown','XIM','AEDoor.library',NULL,NULL,NULL,'/\_________\_      |_____  ________/\ \_______   \/      |     \|     _    \ |     /    \      _      \         _//\',replace('           ________.\n/\_________\_      |_____  ________/\\n\_______   \/      |     \|     _    \\n |     /    \      _      \         _//\\n |    /      \     |       \    |    \\/\n |         R! \____l________)   l     \\n l_____________)==========l____________)\n  -*-  dA hOlY bRoThErHoOd pRESENTS -*-\n        AEDoor.library V2.8 UPDATED!\n ·A·T· *21/05/96*  ·L·A·N· 21:54 ·T·|·C· \n','\n',char(10)),'AEDoor.doc',replace('TABLE OF CONTENTS\n\nAEDoor.library/CreateComm\nAEDoor.library/DeleteComm\nAEDoor.library/SendCmd\nAEDoor.library/SendStrCmd\nAEDoor.library/SendDataCmd\nAEDoor.library/SendStrDataCmd\nAEDoor.library/GetData\nAEDoor.library/GetString\nAEDoor.library/Prompt\nAEDoor.library/WriteStr\nAEDoor.library/ShowGFile\nAEDoor.library/ShowFile\nAEDoor.library/SetDT\nAEDoor.library/GetDT\nAEDoor.library/GetStr\nAEDoor.library/CopyStr\nAEDoor.library/HotKey\nAEDoor.library/PreCreateComm\nAEDoor.library/PostDeleteComm\nINSERT INTO door_catalog VALUES('aedoors','AEDOORS.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AEDOORS.LHA',NULL,'XIM','E source code for /X doors',NULL,NULL,NULL,NULL,replace('E source code for /X doors\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 19:08:55  ON NODE: 1\n','\r',char(13)),'\n',char(10)),NULL,NULL,12690,4,0,NULL,NULL,NULL,'scan',1780048372);
INSERT INTO door_catalog VALUES('aeed101','AEED101.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AEED101.LHA',NULL,'XIM','AmiEditor101.exe',NULL,NULL,NULL,NULL,replace('NEW ACCOUNT-EDiTiNG DOOR FOR /X\n                                            \n','\n',char(10)),'history.txt',replace('This Txt file contains the history of Amiexpress Editor....\n\n\nAmiexpress Editor V1.00 released on 260693\n\nFunctions:\n\n(+) = Search Forward\n(-) = Search BackWords\n(*) = Enter User Number\n(S) = Search A User\n(Q) = Quit The program\n\n----------------------------------------------------------------------------\nAmiexpress Editor V1.01 released on 260693\n\nFunctions:\n\n(+) = Search Forward\n(-) = Search BackWords\n(*) = Enter User Number\n(S) = Search A User\n(Q) = Quit The program\n\nNOTE: I HAD ADD 2 NEW LINES CALLED EXPERT MODE AND PHONE NR.\n      AND USED A BETTER SEARCH COMMAND...\n\n----------------------------------------------------------------------------\n','\n',char(10)),NULL,'auto-added',54469,4,0,NULL,NULL,'aeed101','scan',1780048372);
INSERT INTO door_catalog VALUES('aeed300','AEED300.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AEED300.LHA',NULL,'XIM','AEED300.EXE',NULL,NULL,NULL,'|   ___             ___     ___  ___  ___  | |  /__/ /  / /\/\  /__/    /__/ /__/ /__   | | /    /__/ /   / /  /    /__/ /__/ ___/   |',replace('O------------------------------------------O\n|   ___             ___     ___  ___  ___  |\n|  /__/ /  / /\/\  /__/    /__/ /__/ /__   |\n| /    /__/ /   / /  /    /__/ /__/ ___/   |\n|                                          |\n|             P R E S E N T S :            |\n|             ~~~~~~~~~~~~~~~              |\n|  Amiexpress Editor Version 3.00 (AEED)   |\n|  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-   |\n|  Use This Utils instead of /X own "build |\n|  in" accounting... 41 Different Commands |\nO------------------------------------------O\n','\n',char(10)),'Amiexpress_Editor.DOC',replace('Hello guyes!!!						DATE: 21-04-1994\n\n\nNow I have Upgrade my program to work with /X v3.XX+\n\nREAD THIS FILE NOW!!!!!\n-----------------------\n\nI have decided to make an Editor, because i think many SYSop''s do really\nneed sucht a tool..\n \nOK, lets skip all the talking, and get serious...\n \nOK!?!?!?!?!?!?!\n\nTo start the program, you must copy the S directory to your own S directory\n(Stop.CFG and user.data-editor.cfg)\n\nAfter That, You have to edit the user.data-editor.cfg file, And ajust it to\nyour ASSIGNED bbs dir. (see Fig. 1) \n\n\nFIG. 1  (User.data-editor.cfg)\n------------------------------\n\nLINE 1 IS A PATCH TO AMIEXPRESS EDITOR, SO IT CAN FIND THE USER.DATA AND \nUSER.KEYS files.\n\nIF YOU HAVEN''T ASSIGNED YOUR BBS DIRECTORY, YOU MUST SET A "/" AT THE END.\n \nAn Exampel:\n-----------\n\ndh0:bbs/\nor\ndf1:ami/secret/\n\nIF YOU HAVE ASSIGNED IT, THEN WRITE:\n\nBBS:\n\n\nLine 2 and ->   (max. 50 Computer Types),\n\nare text as will be displayed in the program...to get those settings right,\nYou have To look in your COMPUTERLIST.INFO, and write it to the \nUser.data-editor.cfg file.\n\n>>END OF FIG. 1<<\n\n\nIf you find some bugs in this program or you just can''t make it work, THEN \ncall My BBS: (Look at the bottum of this txt file.) And i will offz. help you.\n\n   \nI''ll hope you find this program usefull!!!\n\nSign. Frank H. Jørgensen....   Alias Tuff Brain\n\n\n\nP.S. You can also multitask with this program, just press LEFT AMIGA + A\n\nP.P.S. >>> THIS PROGRAM WILL NOT FUCK UP YOUR USER.DATA OR USER.KEYS!!!!! <<<\n           BUT IF YOU DON''T BELIVE IN MY WORDS, THEN MAKE A COPY OF YOUR \n           USER.DATA AND USER.KEYS AND SEE FOR YOUR SELF.\n\n\nO----------------------------------------------------------------------------O\n|                   ___             ___     ___  ___  ___                    |\n|                  /__/ /  / /\/\  /__/    /__/ /__/ /__                     | \n|                 /    /__/ /   / /  /    /__/ /__/ ___/                     |\n|                                                                            |\n|		           PHONE +45 43 54 06 64                             |\n|                                                                            |\n| RUNNING /X 3.36, Terbo 21K6 Dual Standard, 410 MB Quantum HD, open 24 hrs. |\nO----------------------------------------------------------------------------O\n\n\nGREETINGS: To all members of FRAC7ION, and all the Users on PUMA BBS...\n----------\n\n','\n',char(10)),NULL,'auto-added',69529,4,0,NULL,NULL,'aeed300','scan',1780048372);
INSERT INTO door_catalog VALUES('aeed400','AEED400.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AEED400.LHA',NULL,'XIM','AEED.EXE',NULL,NULL,NULL,'/   __/      //     /     /__  \/ __  \ /  __ \   /\_//  /\_/ ____/  \__/   \__/ /  __\_ \_/ _ /  / _/ __/___    \__    \_',replace('     ______.______ ______._________  _____\n    /   __/      //     /     /__  \/ __  \\n   /  __ \   /\_//  /\_/ ____/  \__/   \__/\n  /  __\_ \_/ _ /  / _/ __/___    \__    \_\n /   \     /\/ \_  \/ \_   /  \_   / \_   /\n/___/ \__ /____ /_____ /__/______ /_____ / \n  p   r \/ e  \/  s  \/  e   n  \/ t  s\/Kk\n=--=--=--=--=--=--=--=--=--=--=--=--=--=--=\n\n   AmiExpress EDitor Version 4.00 (AEED)    \n   -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-    \n Update Of The Famous AmiExpress EDitor     \n NOW In WB2.xx and 3.xx Look,Bugs Corrected \n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                                                .------''\n             `------------------------------------------------''\n','\n',char(10)),NULL,'auto-added',95387,10,0,NULL,NULL,'aeed400','scan',1780048372);
INSERT INTO door_catalog VALUES('aeedprob','AEEDPROB.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AEEDPROB.LHA',NULL,'XIM','card_scan.exe',NULL,'Tuff',NULL,'|   ___             ___     ___  ___  ___  | |  /__/ /  / /\/\  /__/    /__/ /__/ /__   | | /    /__/ /   / /  /    /__/ /__/ ___/   |',replace('O------------------------------------------O\n|   ___             ___     ___  ___  ___  |\n|  /__/ /  / /\/\  /__/    /__/ /__/ /__   |\n| /    /__/ /   / /  /    /__/ /__/ ___/   |\n|                                          |\n|             P R E S E N T S :            |\n|             ~~~~~~~~~~~~~~~              |\n|  AmiExpress EDitor Version 4.00 (AEED)   |\n|  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-   |\n|Printer Problems In The AmiExpress EDitor |\n|READ HOW TO SOLVE THE PROBLEM NOOOOW!!!!!!|\nO-------------------->Coded By Tuff Brain<-O\n','\n',char(10)),'AEED-Problems.TXT',replace('Hi again,						Denmark, 16-May-94\n\n\nIf You have problems with The AmiExpress EDitor (AEED), and you are sure that\nall your patch and locations are right, Then Keep READING!!!!! \n\n-----------------------------------------------------------------------------\n\nI have been told that there is a problem with AmiExpress EDitor (AEED). The\nproblem appears if you don''t have any Printer Driver Located in your \nPREFS/PRINTER on your WB. To remove this error (if you got it), you have\nto ReInstall those programs/icons Into dh0:prefs/\n\n\nPrinter.info   \nPrinter        \n\nAnd you must have the PRINTER.DEVICE and PARALLEL.DEVICE located in your\ndevs: directory.\n\n\nRember to Install all the printer drivers in the patch DEVS:PRINTERS, and put \nthis in your user-startup: ASSIGN PRINTERS: DEVS:PRINTERS\n\nAfter Install the Printer program, and the Printer Drivers, you have to start\nthe program (by clicking the Printer Icon) and select a Printer driver, and do\nREMBER to Save your selected Printer Driver.\n\nReboot your computer, and if your have done it right AEED should work, \notherwise you have to use the real WB disks and Reinstall it from them. \n\n\nNOTE: This problem only appears if the program (AEED) says something link this\n\n"SORRY THIS DOES NOT COMPUTE!!!!" when your are starting it.\n\n\n\n\nSign.    Frank H. Jørgensen\n\n\n\nO----------------------------------------------------------------------------O\n|                   ___             ___     ___  ___  ___                    |\n|                  /__/ /  / /\/\  /__/    /__/ /__/ /__                     | \n|                 /    /__/ /   / /  /    /__/ /__/ ___/                     |\n|                                                                            |\n|		           PHONE +45 43 54 06 64                             |\n|                                                                            |\n| RUNNING /X 3.38, Terbo 21K6 Dual Standard, 410 MB Quantum HD, open 24 hrs. |\nO----------------------------------------------------------------------------O\n\n','\n',char(10)),NULL,'auto-added',11797,12,0,NULL,NULL,'aeedprob','scan',1780048385);
