INSERT INTO door_catalog VALUES('aeicon17','AEICON17.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AEICON17.LHA','FastView','XIM','FastView',NULL,'KiNg',NULL,'|   ___  ___  ___  ___  _ _  ___     ___   | |__| -_|| - || -_|| - || \ || _ | _ | - |__| ¡::|_) ¯|_(_||_)\ |_(_||_\_||___||_||_(_|::¡',replace(' __________________________________________\n|   ___  ___  ___  ___  _ _  ___     ___   |\n|__| -_|| - || -_|| - || \ || _ | _ | - |__|\n¡::|_) ¯|_(_||_)\ |_(_||_\_||___||_||_(_|::¡\n::::::::::::::::::::::::::::::::::::::::::::\n::::::... D° Y°U FeeL ScæreD YeT ? ...::::::\n::::...                              ...::::\n::...  /X Magic Workbench Icons V1.7   ...::\n¡         Made by KiNg of PARANOiA         ¡\n!         This is *REAL* UPDATE!!!         !\n`SdR! +--------------------+ +381 11 472424''\n','\n',char(10)),'aeicons.guide',replace('@DATABASE "amiicons.guide"\n@AUTHOR "Uros Nedeljkovic (KiNg)"\n\n@NODE "MAIN" "AmiExpress MagicWB Icons"\n@NEXT "MAIN"\n             ___________  ____________  _____  ______________   \n             7__  __ __ \ 7__ __  __ (  7__ / _7__    __ __ (   \n              /  ____/¬_ \ /¬  ¬_//¬_ \  /¬/ /  /  7  /¬ /¬_ \  \n            _/  /  _/ __ _/    `_/ __  _/  \/ _/  -''_/ _/ __  \_\n            7__/   7__/¬\7__/l__7__/¬\_7__/\__7_____7__7__/¬\__7\n\n                                  PRESENtS\n\n                  AmiExpress Magic Workbench 8 Color Icons\n                  ========================================\n                          V1.7    16. - May - 1995.\n                  ========================================\n\n                         by Uros Nedeljkovic (KiNg)\n\n        @{BG fill}@{"  " LINK "whatis"}@{BG Background} About AmiExpress Magic WB Icons\n        @{BG fill}@{"  " LINK "instal"}@{BG Background} Installation\n        @{BG fill}@{"  " LINK "change"}@{BG Background} Changes\n        @{BG fill}@{"  " LINK "author"}@{BG Background} Author\n        @{BG fill}@{"  " LINK "histor"}@{BG Background} History\n        @{BG fill}@{"  " LINK "yugbbs"}@{BG Background} Yu bOARDS\n        @{BG fill}@{"  " LINK "greeti"}@{BG Background} Greetings & Fucks\n\n@ENDNODE\n@NODE "whatis" "What is AmiExpress MWB icons?"\n\nThis  are  High-Quality  8  color  MWB  icons,  for @{"AmiExpress BBS Systems"  LINK  "aesys"}.\nUse  this  icons,  coz they are @{"FUCKWARE" LINK "FW"}.\n\n      - AEMWB Icons is very easy to @{"install" LINK "instal"}\n      - Standard size\n      - Standard palette (MAGIC WORKBENCH (included KiNg''s version))\n\n        @{" Click " LINK "pics"} to see my /X Dir, @{"with FastView" LINK "FV"}\n\n        @{"Contact me" LINK "author"}, for comments and other...\n\n@ENDNODE\n@NODE "instal" "How to Install?"\n\n                                Installation\n\n        AEMWB Icons is very easy to install, just use tool like "iconupdate",\nand replace the image but tooltype stays.\n\n        In this version "iconupdate" is included, thanks to @{"author" LINK "iconup"}\n\n        Easy, isn''t it?\n\n@ENDNODE\n@NODE "author" "Author of /X MWB icons..."\n\n                          How to contact the Author\n\nAuthor of this COOOOOOOOOL icon package is Uros Nedeljkovic (Username KiNg).\n\nContact ADRESS & FAN (BUG) CLUB :-) :\n\n                              Uros Nedeljkovic\n\n                             Brace Jerkovic 145\n                               11040 Belgrade\n                                   Serbia\n                               Yugoslavia (?)\n\n...or:\n\n                     @{BG fill}@{"Sex, Drugs & Rock''n''Roll (SdR) BBS" LINK "sdr"}@{BG Background}\n                            Phone: +381 (o)11 472424\n                        Work Time: 22-06 Every Night\n                          SysOp''s: KiNg & Ogisha\n\n                              Located in Serbia\n\n\n@ENDNODE\n@NODE "aesys" "AmiExpress"\n                              Ami Express (/X)\n\n           © 1992-1994 AmiExpress by LightSpeed Technologies Inc.\n                        Programming by:  Joseph Hodge\n@ENDNODE\n@NODE "FW" "Fuck Ware"\n\nFuck Ware means :\n\n        If you use this icons, you should let me fuck your sister...\n\n\nMy @{"ADDRESS" LINK "author"} :-)\n@ENDNODE\n@NODE "FV" "Fast View"\n                                  Fast View\n\nAuthor of this COOOOOOL viewer:\n\n                FastView 1.30 (23.1.95) - Programmed by John Hendrikx\n\n@ENDNODE\n@NODE "iconup" "Iconupdate"\n\n                                 Iconupdate\n\nAuthor of this GREAT util:\n\n              IconUpdate v2.01 written 1.3.1994 by Gerri Körner\n@ENDNODE\n@NODE "change" "Changes"\n\nChanges since version 1.6:\n\nAdd 9 new icons, bbs:node1/serial/internal_unit.def\n                 bbs:zoom/ascpack\n                          qwkpack\n                          qwkcfg\n                 bbs:access/def_area\n                            def_preset\n                            def_acs\n                 bbs:doors/def_door(1 & 2)\n\n                             NeW GUIdE ICoN ;))\n@ENDNODE\n@NODE "histor" "History"\n                                   History\n\n- 14. April 1995.\n\n        First public version...\n\n- 19. April 1995.\n\n        Second public version, fixed bugs in SIZE, added more icons & palette\npref.\n\n- 12. May 1995.\n\n        Add 2 new icons (ModemType & def. command)\n\n- 16. May 1995.\n\n        Add 9 new icons (see @{"changes" LINK "change"})\n@ENDNODE\n@NODE "sdr" "Cooooooooooooool!!!"\n\n                              @{"»» cLICK mE! ««" SYSTEM "fastview sdr.iff"}\n\n                           ______________ ________ \n                   --»»    \__  _  ___  ¬\\__  __¬\   ««--\n                   --»»    __\  \\/ /¬ /\ \/¬  ¬__/   ««--\n                   --»»   / ¬\\  \_/  /_/_/  /  \¬    ««--\n                   --»»   \______/\______\__//__/     ««--\n\n                               ³4ø MB øn-£¡ne\n\n                              øn£y Am¡gå Bøå®d\n\n                                  Çå££ Nøw!\n\n                       Eve®y N¡ght S¡nçe ². Må®çh ''95!\n\n                         Phøne: +38¹ (ø)¹¹ 472-424!\n\n                              Wørk T¡me: 22-ø6\n\n                              »» PARANOiA HQ ««\n\n                         @{BG fill}@{"Am¡ Mag D¡st®¡bµt¡øn Çente®" LINK "amag"}@{BG Background}\n@ENDNODE\n@NODE "amag" "AmiMag"\n\n   Read! Read! Read! Read! Read! Read! Read! Read! Read! Read! Read! Read!\n\n                ______ ___  ________   ___  _________________\n                7__  / 7__\/ ____  /   7__\/ ____  ____ ____7\n           :---- / _ \  /    \ /  / --- /    \ / _ \ / /___  --:\n           |:: _/ __  _/     _/  / :: _/     _/ __ _/ /_/ / .::|\n           |::.\  /.\_7__/\/\7__/.:::.\  /\/\7__/.\7_____/.::::|\n           |:::.\/.:::::::::::::::::::.\/.:::::::::::::::::::::|\n           :---------------------------------------------------:\n\n                      Yu magazine for Amiga computers.\n\n@ENDNODE\n@NODE "greeti" "Greetings"\nMORAL SUPPORT:\n                          @{"OFFSPRING" LINK "spring"} and @{"CRANBERRIES" LINK "cranber"}\n\n\nGREETINGS:\n                              --{ Cool Guys }--\n\n  Snake & Delboy, iNfusioN, Le Piaf, Kangarøø, Mødem Bøy, Koma, Nik, Miki$,\n                      Kruger, Carlos, Colaborator, Dex\n\n                              --{ Cool Guys }--\n\nFUCKS:\n\n         Slobodan Miloshevic, Microsoft, Mira Markovic, IBM, Pyroman\n\nINSPIRATION:\n\n            Radio Golf, ESCOM, Workbench, Imagine and Nike Pippen\n\n@ENDNODE\n@NODE "yugbbs" "YU Amiga Boards"\n\n        Try this Cøø£ Bøards:\n\n         Bøard                              Phone        : Wørk T¡me\n        ---------------- --  -----------        -------- : ---  - - -\n        Sex, Drµgs & Røck''n''Røll        +381 11 472424   : 22-o6\n        Black Høle                      +381 11 862743   : Nøn-Støp\n        The Clinic                      +381 11 1761345  : 22-o8\n        United                          +381 11 1777636  : 21-o6\n        4PM                             +381 11 668552   : 22-o6\n        Kruger''s Wife                   +381 24 35266    : 22-o6\n        Labyrinth                       +381 21 369861   : 18-24\n@ENDNODE\n@NODE "spring" "OFFSPRING"\n\n      2 best songs ever, COME OUT AND PLAY (i can''t find the words) and\n                                 SELF ESTEEM\n\n \n                                 Self Esteem\n                                 (OFFSPRING)\n \nLa la, la la la, la la, la la la \n\nI wrote her off for the 10th time today\nI practiced hard all the things I would say\nWhen she came over, I lost my nerve\nI took her back and made her desssert\n \nI know I''m being used\nBut that''s okay because I like the abuse...\nI know she''s playing with me\nBut that''s okay ''cause I got no self-esteem...........\n \nOhyeah........Yeah.........Oh........Yeah.......etc.\n \nWe make plans go out at night\nWait till 2 then I Turn out the light \nThis rejection''s got me so low....\nShe keeps it up I just might tell here so...\n \nOh...yeah....oh....yeah....yeah...\n \nWhen she''s saying.......ah that she wants only me. \n \nWell I wonder why she sleeps with my friends\nWhen she''s saying..ah... that I''m like a diease\nwell I wonder how much more I can stand\nWell I guess I should stand up for myself\nBut I really think it''s better this way\n \nThe more you suffer...the more it shows you really care...\n \nRight?.....Yeah,yeah...\n \nI''ll relate this little bit\nIt happens more than I''d like to admit\nLatye at night, she knocks on my door\nShe''s drunk again and lookin'' to score\nI know I should say no..\nBut''s it''s kinda hard when she''s ready to go\nI may be dumb, but I''m not a dweeb\nI''m just a sucker with no self-esteem\n \nyeah...oh,......yeah....oh...yeahyeah\n \nWhen she''s saying\nthat she wants only me\nWell I wonder why she sleeps with my firends\nWhen she''s saying\nAh, that I''m like a diesase\nWell I wonder how much more I can stand\nWell I guess I should stick up for myself\nBut I really think It''s better this way\nthe more you suffer, the more you really care...\n \nRight? Yeah, yeah\n \nOFFSPRING:\nRon Welty: Drums\nDexter Holland (love that hair and voice!): Vocals, guitar\nGreg K: Bass\nNoodles: Guitar\n \nWritten by OFFSPRING, 1994 epitaph records, the coolest damn label in the\nU.S.\n@ENDNODE\n@NODE "cranber" "Cranberries"\n\nand this two best song ever ;)\n\n                   »» Zobmie «« and »» Ode to my family ««\n\n                                  ZOMBIE\n                                (From MTV)\nAnother head\nHangs lowly\nTime is slowly tickin''\nAnd the violence causes silence\nWho are we mistaken\n \nBut you see it''s not me\nIt''s not my family\nIn your head\nIn your head they are fighting\nWith their tanks\nAnd their bombs\nAnd their guns\nIn your head\nIn your head they are cryin''\n \nIn your head (2X)\nZombie\nWhat''s in your head\nIn your head\nZombie\n \nAnother mother''s breakin'' heart\nIs taking over\nAnd the violence causes silence\nWe must be mistaken\nIt''s the same old theme\nSince 1916\nIn your head, in your head\nThey''re still fightin''\nWith their tanks... etc (look foward)\nIn your head they are dyin''\n \nIn your head, in your head\nZombie\nWhat''s in your head\nIn your head\nZombie\n \nMusic and text:O'' Riordan\n1994 Island Record Inc., Island Music LTD. (I think...)\n\n                                    ----\n\n"ODE TO MY FAMILY"\nby the Cranberries\n\n\nUnderstand the things I say\nDon''t turn away from me\n''Cause I''ve spent half my life out there\nYou wouldn''t disagree\n\nDo you see me?  Do you see?\nDo you like me?  Do you like me standing there?\nDo you notice?  Do you know?\nDo you see me?  Do you see me?\nDoes anyone care?\n\nUnhappiness was when I was young\nWe didn''t give a damn\n''Cause we were raised\nTo see life as fine\nTake it if we can \n\nMy mother, my ma\nShe hold me, she hold me\nWhen I was out there\nMy father, my father\nHe liked me, oh he liked me,\nDoes anyone care? \n\nUnderstand what I''ve become\nIt wasn''t my design\nAnd people everywhere\nThey sob, think better than I am\n\nBut I miss you, I miss --\n''Cause I liked it,\n''Cause I liked it when I was out there\nDo you notice?  Do you know you did bad by me,\nYou did bad by --\nDoes anyone care?\n\n\nUnhappiness was when I was young,\nWe didn''t give a damn\n''Cause we were raised \nTo see life as fine,\nTake it if we can\n\nMy mother, my ma \nShe hold me, she hold me\nWhen I was out there \nMy father, my father\nHe liked me, well he liked me,\nDoes anyone care?  Does anyone care?\nDoes anyone care?  Does anyone care?\nDoes anyone care?  Does anyone care?\nDoes anyone care?  Does anyone care?\n\n                                  WOOW! ;)\n@ENDNODE\n@NODE "pics" "DEMO PICS"\n\n        @{BG fill}@{"  " SYSTEM "fastview root.iff"}@{BG background} mY aMIeXPRESS rOOT dIR\n        @{BG fill}@{"  " SYSTEM "fastview other.iff"}@{BG background} oTHER aMIeXPRESS dIR''s\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',143368,2,0,NULL,NULL,'aeicon17','scan',1780048385);
