INSERT INTO door_catalog VALUES('ae_msc12','AE_MSC12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AE_MSC12.LHA',NULL,'XIM','date.library',NULL,NULL,'AE',NULL,replace('Multi Sysop comment Door\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 19:08:40  ON NODE: 1\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',8613,1,0,NULL,NULL,'ae_msc12','scan',1780048385);
INSERT INTO door_catalog VALUES('ae_slot','AE_SLOT.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AE_SLOT.LHA','move','XIM','move',NULL,NULL,'AE',NULL,replace('SLOT MACHINE\n','\n',char(10)),'2Nodez.TXT',replace('\n           -( [ DiGiT/\L X ] [ oNE oF tHE fASTEST iN eUROPE ] )-\n\n            PaRaDiSe wORLD iNNOVATION wORLD dISTRIBUTION sITE!\n\n              ________  ____________________  __   _/\  ___\n              \____   \/  / ___/  /_  _/    \/ /   \  \/ \/\n               \   \   \ / /__^  / / //  ^  /  \___ \    / \n               /_______//\___/__/ /_/ \_/\_/\_____/ /    \_\n               DREAM MACHINE WorLD DHQ CenTer ©    /__/\___\n\n\n  Node [1] +31-570-637050  Node [2] +31-570-636468  Node [3] +31-570-677702\n\n  Amiexpress V4.20 Registered On An Amiga 2000 GVP-Tekmagic 68060 32MB KS3.1\n    Pioneer Changer DRM-604X + Toshiba Cd-Rom 4 HD''s 7110MB Space Total...         \n\n   2 * cREDITZ fOR mAJORS! 3 * cREDITZ fOR mAJORS fROM yOUR oWN gROUP!\n    pROVIDING yOU: Amiga ECS/AGA, PC, AmiExpress, Sex Pic, Sex Stories\n\n          ---»> nO nEW uSER pASSWORD aND/oR sYSTEM pASSWORD! <«---    \n                                                                      \n       -( [ DiGiT/\L X ] [ oNE oF tHE BesT FroM The EaSt SidE ] )-\n\n','\n',char(10)),NULL,'auto-added',11576,4,0,NULL,NULL,'ae_slot','scan',1780048385);
INSERT INTO door_catalog VALUES('afaker20','AFAKER20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AFAKER20.LHA','amifaker','XIM','amifaker','2.0',NULL,NULL,NULL,replace('AmiFaker v2.0\n','\n',char(10)),'amifaker.doc',replace('\n\n\n\n                           AmiFaker v2.0 quickdox\n\n\n\n\n                             Installing AmiFaker\n\n1. Copy after modifying amifaker.cnf to s:\n2. If BBS:fakerlog exists, rename it as BBS:amifaker.data\n3. Copy the DOS version (amifaker) to Your c: (usage: amifaker [Conf.Number]\n   File(s))\n4. Install the door version (amifaker.x) like any other standard AmiExpress\n   Door.\n\nNOTE: AmiFaker requires about 10kb stack!\n\nNOTE: AmiFaker doesn''t lock files correctly under 1.2/1.3!\n\n\n                             Editing Preferences\n\n"BBS:CONFIG1"           /* Config file (DOS version needs this)         */\n"10"                    /* Size of top fakeloaders list                 */\n"3"                     /* Free Lines for comments                      */\n"NO"                    /* Modify ud/callerslog?? (YES/NO)              */ 1.\n"YES"                   /* Leave notes to users? (YES/NO)               */ 2.\n"YES"                   /* Leave notes to Sysop? (YES/NO)               */ 3.\n"YES"                   /* Record Sysop activities? (YES/NO)            */ 4.\n"YES"                   /* Prompt automatically commented files         */\n"-X--------"            /* Node filter                                  */ 5.\n"^^                                        ^^"  /* User comment mask    */\n"#########>>>                    <<<#########"  /* Credits taken mask   */\n"#########>>>                    <<<#########"  /* Credits given mask   */\n"Sysop,,BASICS,DELETE_FILES,MAKE_FREE_DOWNLOAD,USER_EDITOR,FILE_OPTIONS"   6.\n"END"\n\n1. Turn this one on if you''re running f.ex weektop which uses logfiles.\n2. Send private message to user who have lost or gained bytes.\n3. Send private  message to Sysop about commented files. \n4. Sysop activities will be recorded into callerslog.\n5. Mark Your active modem nodes with ''X''s, leave local node out.\n6. All users with special rights should be listed here before "END" line.\n   You may add password between the ",,"''s after user name. BASICS stands\n   for right to take credits and return credits to downloaders.\n   \nfor example:\n"ZEN,my_password,BASICS"\n"SPOCK,,MAKE_FREE_DOWNLOAD,USER_EDITOR,FILE_OPTIONS,BASICS"\n\n* Use ''$'' to enter the user editor when AmiFaker prompts for files.\n* Use ''$'' to enter the file options menu when AmiFaker prompts for comments.\n* Use ''?'' for small information screen when AmiFaker prompts for files.\n\n\n                          "Give How Many X-Bytes?"\n\nNegative and positive values accepted i.e.  try ''2'' to give double credits or\n''-1'' to take credits away.  Answering ''1'' is ignored becouse user has already\ngot 1*credits when he uploaded the file.\n\n\n                              Contacting Author\n\n                            Zenlandia BBS / SPOCK\n                         Usenet: [email removed]\n','\n',char(10)),NULL,'auto-added',41159,4,0,NULL,NULL,'afaker20','scan',1780048385);
INSERT INTO door_catalog VALUES('afkr202','AFKR202.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AFKR202.LHA','AmiFaker','XIM','AmiFaker','2.02',NULL,NULL,NULL,replace('AmiFaker v2.02\n','\n',char(10)),'AmiFaker.doc',replace('\n\n                AmiFaker v2.0 Documentation (rel. 17-Jan-93)\n                ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n                            Reason for Releasing\n                            ~~~~~~~~~~~~~~~~~~~~\nNext  Version  of  AmiFaker Will Be 2.0 Only So Here''s the Last Version That\n                             Everybody Can Use.\n\n\n                                  Contents\n                                  ~~~~~~~~\n                  AmiFaker .................. Dos Version\n                  AmiFaker.x ............ AmiExpress Door\n                  AmiFaker.Cnf .............. Config File\n\nNOTE: If BBS:FakerLog Exists Rename it as BBS:AmiFaker.data\nNOTE: AmiFaker Requires About 10kb Stack!\nNOTE: AmiFaker Doesn''t Lock Files Correctly (It''s Impossible!) Under 1.2/1.3!\n\n\n                                    Keys\n                                    ~~~~\n* Use ''$'' to Enter the User Editor When AmiFaker Prompts for Files.\n* Use ''$'' to Enter the File Options Menu When AmiFaker Prompts for Comments.\n* Use ''?'' for Small Information Screen When AmiFaker Prompts for Files.\n\n\n                          "Give How Many X-Bytes?"\n                          ~~~~~~~~~~~~~~~~~~~~~~~~\nNegative  and  Positive Values Accepted i.e.  Try ''2'' to Give Double Credits\nor  ''-1''  to  Take  Credits Away.  Answering ''1'' is Ignored Becouse User Has\nAlready Got 1 * Credits When He Uploaded the File.\n\n\n               Improments/Changes from AmiFaker V2.0 -> v2.01\n               ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n* Fixed a Bug That Caused Sometimes a Guru When Using Command ''?''\n* You Can Reward Users That Have Discovered a Fake.\n* Macrokeys Are Now Fully Configured Into Preferences File.\n* Private and Anonymous Comments.\n* Delete Users Fake Status.\n* Full Line Comments\n\n                             Contacting Author\n                             ~~~~~~~~~~~~~~~~~\n                           SPOCK / Zenlandia BBS\n                        Usenet: [email removed]\n','\n',char(10)),NULL,'auto-added',48727,8,0,NULL,NULL,'afkr202','scan',1780048385);
