INSERT INTO door_catalog VALUES('afl_cw13','AFL-CW13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AFL-CW13.LHA',NULL,'XIM','cOLORWALL.000','1.3','sHADOW','AFL','nEW fUTURES aDD`ED !! xIM dOOR bY sHADOW mAN oF aFL fOR /X2.xX/3.xX aND sIGMA-eXPRESS !',replace(' cOLORWALL v1.3! sUM fUCKING bUGS fIXED aND \nnEW fUTURES aDD`ED !! xIM dOOR bY sHADOW mAN\n oF aFL fOR /X2.xX/3.xX aND sIGMA-eXPRESS !\n','\n',char(10)),'cOLORWALL.gUIDE',replace('@database cOLORWALl.gUIDe\n\nCopyright (c) 1994 by SHaDoW MaN/aFL\n\n@Remark $VER: (May 26 1994, 23:05:00)\n@Remark AmigaGuide DataBase "SHaDoW MaN" DoCuMeNTaTioN\n\n@node MAIN "cOLORwALL V1.3 gUIDE (c) 1994 BY SHaDoW MaN/aFL (C.i.S / aFL GHQ)"\n                   /\             /\             /\\n                  /  \_____      /  \________   /  \____\n=================/         \====/            \=/        \=================\n                /       .   \  /             //         /\n               _\       |    \_\      ______/_\        /\n              / \\            \\\     ____/ / \\      /______\n             /   \\     .      \\\     |   /   \\    /       \\n            /     \)    |       \\)    |  /     \)            \\n           /            |       /      | /                    /\n===========\____________|____  /_______|=\_________________  /======[S M]=\n                           \  /                          \  /\n                            \/                            \/\n      aLPHA fLIGHT pRESENTS a pOWERFULL xIM dOOR (w) bY sHADOW mAN/aFL\n\n    @{"-=====================[ cOLOR wALL v1.3 !!! ]=====================-" LINK ColorWall}\n\n       tHAT`Z tHE fIRST wALL wITH rEAL tIME cOLOR & sTYLE cHANGING!\n                 iT`S sIMPLY tHE bEST wALL eVER sEEN !!!\n                  tHIS dOOR iS fULLY wRITTEN iN `C` !!!\n\n    @{"-======================= i = N = D = E = X =======================-" LINK Index}\n\n@endnode\n\n@node ColorWall "hEY iNSTALL iT..."\n\n         /\    /\          /\    __        /\    /\\n========/  \==/  \/\======/  \==/  \=======\ \==/  \/\====/\=============\n       /   /\/    \ \  /\/    \/ / /_    /\/\ \/    \ \  /\ \  /\\n      /  \/  \ \   \ \/  \ \   \     \  /  \ \ \ /   \ \/  \ \/  \\n      \   \  /  \  /     /  \  /  \  /  \   \  /  \  /     /     /\n      \\    /\    /\    /\    /\   \//  \\    /\   \/\    /\    //\n       \\  //\\  //\\  //\\  //\\  //    \\  //\\  //\\  //\\  //S\n        \\//  \\//  \\//  \\//  \\//      \\//  \\//  \\//  \\// \n=========\/====\/====\/====\/====\/=[v1.3]=\/====\/====\/====\/==M=======\n\n                        iS fULLY wRITTEN iN `C` !!!\n  tHE cODER gIVE`S yOU oNLY tHE gUARANTY oF a 100% bACKDOOR fREE dOOR,\n  iF yOU hAVE dOWNLOADED tHE fULL pACKAGE fROM a aFL mEMBERSHIP bOARD,\n                oR fROM tHE hOME oF tHIZ gREAT pRODUCT !\n\n     sO dON`T mISS tO cALL tHE hOME aND cALL tHE @{"cARRIER iN sPACE!"LINK jOIN!!!}\n\n                         fILESIZES aND fILEHUNKS :\n\n         fILENAME:          sIZE:        hUNK_cODE:\n\n         ColorWall.000      33036        (1001/$03E9) 31880 bYTES\n         ColorWall.030      32852        (1001/$03E9) 31696 bYTES\n         ColorWall.guide    14571        -\n\n@endnode\n\n@node Index "iT`S tHE iNDEX..."\n\n         /\    /\          /\    __        /\    /\\n========/  \==/  \/\======/  \==/  \=======\ \==/  \/\====/\=============\n       /   /\/    \ \  /\/    \/ / /_    /\/\ \/    \ \  /\ \  /\\n      /  \/  \ \   \ \/  \ \   \     \  /  \ \ \ /   \ \/  \ \/  \\n      \   \  /  \  /     /  \  /  \  /  \   \  /  \  /     /     /\n      \\    /\    /\    /\    /\   \//  \\    /\   \/\    /\    //\n       \\  //\\  //\\  //\\  //\\  //    \\  //\\  //\\  //\\  //S\n        \\//  \\//  \\//  \\//  \\//      \\//  \\//  \\//  \\// \n=========\/====\/====\/====\/====\/=[v1.3]=\/====\/====\/====\/==M=======\n\n               =============================================\n               ============= i = N = D = E = X =============\n               =============================================\n               ===                                       ===\n               ===     @{"          fEATURES!          " LINK Feature}     ===\n               ===     @("     iNFO aBOUT cW 1.4 !     " LINK Info!!!}     ===\n               ===     @{" tHE fUCKING bUGS oF cW 1.2! " LINK Bugs!!!}     ===\n               ===     @{"        iNSTALLATION!        " LINK Install}     ===\n               ===     @{"        rEQUIREMENTS!        " LINK Require}     ===\n               ===     @{"          gREETINGS          " LINK Greets!}     ===\n               ===     @{" wANT yOU bE a bETA tESTER?? " LINK bETA!!!}     ===\n               ===     @{"    jOIN tHE sPACE pOWER!    " LINK jOIN!!!}     ===\n               ===                                       ===\n               =============================================\n               =============================================\n               =============================================\n\n@endnode\n@node Feature "tHE fEATURES oF tHIS dOOR !"\n\n         /\    /\          /\    __        /\    /\\n========/  \==/  \/\======/  \==/  \=======\ \==/  \/\====/\=============\n       /   /\/    \ \  /\/    \/ / /_    /\/\ \/    \ \  /\ \  /\\n      /  \/  \ \   \ \/  \ \   \     \  /  \ \ \ /   \ \/  \ \/  \\n      \   \  /  \  /     /  \  /  \  /  \   \  /  \  /     /     /\n      \\    /\    /\    /\    /\   \//  \\    /\   \/\    /\    //\n       \\  //\\  //\\  //\\  //\\  //    \\  //\\  //\\  //\\  //S\n        \\//  \\//  \\//  \\//  \\//      \\//  \\//  \\//  \\// \n=========\/====\/====\/====\/====\/=[v1.3]=\/====\/====\/====\/==M=======\n\n                  hERE aRE tHE fEATURES oF tHIS kEWL dOOR:\n\n - rEALTIME cOLOR & sTYLE hANDLING!\n - cENTER lINE oPTION !\n - aDD uSER nAME !\n - cTRL-X cLEARS tHE lINE !\n - bACKGROUND cOLOR cHANGING                              (  nOW  nEW!  )\n - sTYLE aND bACKGROUND cOLOR cHANGING aT tHE sAME tIME ! (nEXT vERSION!)\n - hELP pAGE fOR tHE uSERS !                              (nEXT vERSION!)\n - fOR mORE kEWL iDEAS ... cALL mY bOARD !\n\n@endnode\n@node Info!!! "sUM iNFOS aBOUT cOLORWALL v1.4 !"\n\n         /\    /\          /\    __        /\    /\\n========/  \==/  \/\======/  \==/  \=======\ \==/  \/\====/\=============\n       /   /\/    \ \  /\/    \/ / /_    /\/\ \/    \ \  /\ \  /\\n      /  \/  \ \   \ \/  \ \   \     \  /  \ \ \ /   \ \/  \ \/  \\n      \   \  /  \  /     /  \  /  \  /  \   \  /  \  /     /     /\n      \\    /\    /\    /\    /\   \//  \\    /\   \/\    /\    //\n       \\  //\\  //\\  //\\  //\\  //    \\  //\\  //\\  //\\  //S\n        \\//  \\//  \\//  \\//  \\//      \\//  \\//  \\//  \\// \n=========\/====\/====\/====\/====\/=[v1.3]=\/====\/====\/====\/==M=======\n\n sORRY dUDES bUT tHE nEXT vERSION oF cOLORWALL (v1.4) wILL nOT lONGER a\n pUBLIC rELEASE ... bUT yOU cAN gET iT bY a fAST cALL aT tHE cARRIER iN\n sPACE .. bECAUSE tHIS dOOR wAS a lOT oF wORK aND i lIKE iT tO kNOW hOW\n   mANY sYSOPS aRE uSING mY dOOR(S) !! sO cALL mY bOARD aND yOU gET a\n   rEGISTRATION... aND yOU cAN dOWNLOAD aLL dOORS/uTILS dIRECTLY fROM\n                   tHE cODER ! bE cOOL aND cALL !\n\n    nOTE: mY rEGISTRATIONS nEVER cOSTS aNY mONEY ... oNLY a cALL !!!\n  cOLORWALL v1.4 wILL bE rELEASED  fOR aLL rEGISTRED uSERS aT 07-XX-94\n                  (i wILL iNFORM yOU bY a tEXT fILE !)\n\n@endnode\n@node Bugs!!! "sUM fUCKING bUGS wAS fIXED..."\n\n         /\    /\          /\    __        /\    /\\n========/  \==/  \/\======/  \==/  \=======\ \==/  \/\====/\=============\n       /   /\/    \ \  /\/    \/ / /_    /\/\ \/    \ \  /\ \  /\\n      /  \/  \ \   \ \/  \ \   \     \  /  \ \ \ /   \ \/  \ \/  \\n      \   \  /  \  /     /  \  /  \  /  \   \  /  \  /     /     /\n      \\    /\    /\    /\    /\   \//  \\    /\   \/\    /\    //\n       \\  //\\  //\\  //\\  //\\  //    \\  //\\  //\\  //\\  //S\n        \\//  \\//  \\//  \\//  \\//      \\//  \\//  \\//  \\// \n=========\/====\/=