INSERT INTO door_catalog VALUES('afl_cw14','AFL-CW14.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AFL-CW14.LHA',NULL,'XIM','cOLORWALL tHE nEW vERSION oF tHE','1.4...','sHADOW','AFL','gREATEsT wALL aROUND! iF yOU wANT tO sEE a nEW fEATURE (nEVER sEEN iN aNY wALLS aROUND) tHEN iNSTALL tHIS wALL! (w) bY sHADOW mAN`94',replace('  cOLORWALL v1.4... tHE nEW vERSION oF tHE\n gREATEsT wALL aROUND! iF yOU wANT tO sEE a\nnEW fEATURE (nEVER sEEN iN aNY wALLS aROUND)\ntHEN iNSTALL tHIS wALL! (w) bY sHADOW mAN`94\n','\n',char(10)),'cOLORWALL.gUIDE',replace('@database cOLORWALL\n\nCopyright (c) 1994 by sHADOW mAN/aFL\n\n@Remark $VER: (August 26 1994, 21:59:00)\n@Remark AmigaGuide DataBase "sHADOW mAN" DoCuMeNTaTioN\n\n@node MAIN "cOLORWALL v1.4 gUIDE (c) 1994 BY sHADOW mAN/aFL (C.i.S / aFL GHQ)"\n  _____ __    _____ __ __ _____       _____ __    __ _____ __ __ ________\n :     :  :  :     :  :  :     :     :     :  :  :  :     :  :  :        :\n ¦  .  ¦  ¦  ¦  .  ¦  ¦  ¦  .  ¦     ¦     ¦  ¦  ¦  ¦     ¦  ¦  ¦        ¦\n |  |  |  |  |  |  |  :  |  |  |     |  ___|  |  :__:  ___|  :  |__:  :__:\n |     |  |  |     |     |     |     |  _| |  |  :  : _|__|     |  ¦  ¦\n |  .  |  |__|  ___|  .  |  .  |     |  |  |  |__¦  ¦ \_  |  .  |  |  |\n |  |  |  |  |  |  |  |  |  |  |     |  |  |  |  |  |  |  |  |  |  |  |\n |  |  |  |  |  |  |  |  |  |  |     |  |  |  |  |  |  ¦  |  |  |  |  |\n ¦  ¦  ¦  ¦  ¦  |  ¦  ¦  ¦  ¦  |     ¦  ¦  ¦  ¦  ¦  ¦     ¦  ¦  ¦  ¦  ¦\n :__:__:_____:__|  :__:__:__:__:     :__:  :_____:__:_____:__:__:  :__:S M\n\n     aLPHA fLIGHT pRESENTS a pOWERFULL xIM dOOR (w) bY sHADOW mAN/aFL\n\n    iT`S tHE gREATEST wALL eVER, wITH fEATURES nEVER sEEN iN aNY oTHER\n                               wALLS aROUND!\n\n                       iT`S tHE @{" cOLORWALL v1.4 " LINK Wall} !!!\n\n                               @{" fEATURES ?! " LINK Features}\n                             @{" iNSTALLATION ?! " LINK Install}\n                             @{" rEQUIREMENTS !? " LINK Requ}\n                               @{" gREETINGS ! " LINK Greets}\n                        @{" wANNA bE a bETA-tESTER ?!? " LINK Beta}\n                               @{" tAKE oF...! " LINK jOIN!!!}\n\n@endnode\n@node Wall "tHE hISTORY oF cOLORWALL..."\n\n         /\    /\          /\    __        /\    /\\n========/  \==/  \/\======/  \==/  \=======\ \==/  \/\====/\==============\n       /   /\/    \ \  /\/    \/ / /_    /\/\ \/    \ \  /\ \  /\\n      /  \/  \ \   \ \/  \ \   \     \  /  \ \ \ /   \ \/  \ \/  \\n      \   \  /  \  /     /  \  /  \  /  \   \  /  \  /     /     /\n      \\    /\    /\    /\    /\   \//  \\    /\   \/\    /\    //\n       \\  //\\  //\\  //\\  //\\  //    \\  //\\  //\\  //\\  //S\n        \\//  \\//  \\//  \\//  \\//      \\//  \\//  \\//  \\// \n=========\/====\/====\/====\/====\/=[v1.4]=\/====\/====\/====\/==M========\n\n               cOLORWALL v1.4 iS fULLY wRITTEN iN `c` !!!\n     aT fIRST mUST i sAID tHAT mY eNGLISH iS nOT tHE bEST bUT i hOPE,\n                        tHAT yOU uNDERSTAND mE !\n          tHE iDEA tO mAKE tHIS dOOR iS oLDER tHAN 1 yEAR, bUT\n       tHIS tIME i dOESN`T kNOW hOW tO cODE iN `c` ! aND iN aREXX\n          wAS iT tO sLOW, bUT sINCE lAST yEAR (sEPTEMBER `93),\n     a cOOL dUDE cALLED sPIDER (oSIRIS) aTTEMPTS tO tEACH mE iN `c`!\n             aND nOW, iT`S dONE a gREAT wALL wITH rEALTIME\n           fOREGROUND-, bACKGROUND-cOLOR aND sTYLE cHANGING!\n                      tHAT`S cOOL... oR nOT ?!\n    oK tHE fIRST vERSIONS oF cOLORWALL wAS a bIT hEAVY tO uSE, bECAUSE\n     aS mANY cTRL-kEYS aS aVAIBLE wAS uSED fOR tHE dOOR... bUT nOW...\n  hEHE ... i hAVE tOTALLY rEWRITTEN tHIS dOOR (hOPEFULLY fASTER!) iNTO a\n           bETTER `C` aND iNTO a hOPEFULLY eASY tO uSE dOOR !\n    nOW yOU dOESN`T nEED aS mANY cONTROL kEYS... nOW, tHERE`RE oNLY 5\n             cTRL-kEYS! wHAT ?! aND wHERE aRE tHE cOLORS ?\n                hEHE oK lET`S lOOK aT tHIS sCREENSHOT`S\n\n                        @{" cOLORWALL v1.0 - v1.3 "LINK V1.3}\n                        @{" cOLORWALL vERSION 1.4 "LINK V1.4}\n\n   nOW, yOU sEE tHERE`RE oNLY 4 cTRL-kEYS (4 ? nOT 5 ?)! yES 5,bUT yOU\n dOESN`T sEE tHE bACKDOOR (JOKE!) ... nO, iT`S tHE [cTRL-C] kEY tO aBORT\n                               wRITING!\n\n         tHIS kEYS cAN yOU nOW uSE tO wRITE yOUR cOOL wALL lINES:\n\n              pRESS [cTRL-F] aND cHOOSE a fOREGROUND cOLOR !\n              pRESS [cTRL-B] aND cHOOSE a bACKGROUND cOLOR !\n              pRESS [cTRL-S] aND cHOOSE a sTYLE !\n\n nOTE: tHE sTYLE`S aRE bUTTONS (!) (oNE tIME cTRL-S aND B tURNS tHE bOLD\n       mODE oN... aGAIN cTRL-S aND B tURNS tHE bOLD mODE oFF !)\n       oK, nOW yOU cAN cHANGE tO aLL sTYLES aVAILABLE bY sWITCHING oN/oFF!\n\n       i.E.: [cTRL-S] - [B] -> bOLD iS tURNED oN!\n             [cTRL-S] - [I] -> bOLD aND iTALIC iS tURNED oN!\n             [cTRL-S] - [U] -> bOLD,iTALIC aND uNDERLINE iS tURNED oN!\n             [cTRL-S] - [N] -> nORMAL! aLL sTYLES wILL bE tURNED oFF!\n\n            oK, i tHINK tHAT`S aLL lET`S gO aND @{" iNSTALL "LINK Install} iT...\n\n            oH hERE aRE tHE sIZES oF tHE fILES:\n\n              nAME                     sIZE!\n             --------------------------------\n              cOLORWALL.000            37812\n              cOLORWALL.030            36812\n              cOLORWALL.gUIDE          23616\n              cOLORWALL.hELP            5224\n\n==========================================================================\n@endnode\n@node V1.3 "sCREENSHOT oF vERSION 1.3"\n\n         /\    /\          /\    __        /\    /\\n========/  \==/  \/\======/  \==/  \=======\ \==/  \/\====/\==============\n       /   /\/    \ \  /\/    \/ / /_    /\/\ \/    \ \  /\ \  /\\n      /  \/  \ \   \ \/  \ \   \     \  /  \ \ \ /   \ \/  \ \/  \\n      \   \  /  \  /     /  \  /  \  /  \   \  /  \  /     /     /\n      \\    /\    /\    /\    /\   \//  \\    /\   \/\    /\    //\n       \\  //\\  //\\  //\\  //\\  //    \\  //\\  //\\  //\\  //S\n        \\//  \\//  \\//  \\//  \\//      \\//  \\//  \\//  \\// \n=========\/====\/====\/====\/====\/=[v1.4]=\/====\/====\/====\/==M========\n\n.--------------------[ USE THE CTRL-KEY AND ONE OF THIS : ]--------------------.\n| COLORS: [ ]>[Q] - RED           [ ]>[W] - GREEN      [ ]>[E] - YELLOW        |\n|         [ ]>[R] - DARK BLUE     [ ]>[T] - VIOLET     [ ]>[Z] - CYAN          |\n|         [*]>[U] - WHITE         [*]>[S] - BACKGROUND                         |\n)------------------------------------------------------------------------------(\n| STYLES: [ ]>[A] - NORMAL        [ ]>[B] - BOLD       [ ]>[V] - ???????       |\n|         [ ]>[G] - BOLD/ITALIC   [ ]>[F] - INVERSE    [*]>[C] - BREAK !       |\n`------------------------------------------------------------------------------''\n\nwANT yOU sIGN yOUR tEXT ?! [Y/n] > yOHO...\n\n|------------------[ ENTER YOUR TEXT (MAX. 1 LINE/69 CHARS) ]------------------|\n...BREAK                                                             -sHADOW mAN\n|------------------------------------------------------------------------------|\n\n                ^^^ sCREENSHOT cOLORWALL V1.0 - V1.3 ^^^\n\n                            @{" bACK !!! "LINK Wall}\n\n==========================================================================\n@endnode\n@node V1.4 "sCREENSHOT F vERSION 1.4"\n\n         /\    /\          /\    __        /\    /\\n========/  \==/  \/\======/  \==/  \=======\ \==/  \/\====/\==============\n       /   /\/    \ \  /\/    \/ / /_    /\/\ \/    \ \  /\ \  /\\n      /  \/  \ \   \ \/  \ \   \     \  /  \ \ \ /   \ \/  \ \/  \\n      \   \  /  \  /     /  \  /  \  /  \   \  /  \  /     /     /\n      \\    /\    /\    /\    /\   \//  \\    /\   \/\    /\    //\n       \\  //\\  //\\  //\\  //\\  //    \\  //\\  //\\  //\\  //S\n        \\//  \\//  \\//  \\//  \\//      \\//  \\//  \\//  \\// \n=========\/====\/====\/====\/====\/=[v1.4]=\/====\/====\/====\/==M========\n\n*=fOREgROUND cOLORS:=========================