INSERT INTO door_catalog VALUES('afl_dc01','AFL-DC01.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AFL-DC01.LHA','AFL-DupeCheck','XIM','AFL-DupeCheck',NULL,'sTc/AFL','AFL','+----\________   \__   ______/  /----------+ |Alpha /     /    /   _____/   /_____Flight| +-----/    _     /      \/    /     /------+',replace('     ____________________________\n+----\________   \__   ______/  /----------+\n|Alpha /     /    /   _____/   /_____Flight|\n+-----/    _     /      \/    /     /------+\n|     \____/__  /\____  /\_______  /   #1  |\n+-------------\/------\/     RMc!\/--------+\n|           AFL-DupeCheck v0.01!           |\n+-----------( Coded by sTc/AFL )-----------+\n','\n',char(10)),'AFL-DupeCheck.Guide',replace('@DATABASE AFL-DupeCheck Documentation\012@AUTHOR SvEN tHE CREAToR/AFL\012@INDEX Documentation\012\012Copyright © 1994 SvEN tHE CREAToR/AFL\012\012@REMARK $VER: AFL-DupeCheck by sTc/AFL\012@REMARK AmigaGuide database\012\012@NODE Main "AFL-DupeCheck - Main"\012\012             (#) AFL-DupeCheck © 1994 by sTc/AFL (#)\012\012                       @{"  Prg Description  " Link PrgDesc}\012                       @{"   Installation    " Link Installation}\012                       @{"     Tooltypes     " Link Tooltypes}\012                       @{"   String files    " Link Stringfiles}\012                       @{"   Programlogic    " Link Programlogic}\012                       @{"     Greetings     " Link Greetings}\012\012@ENDNODE\012\012@NODE PrgDesc "AFL-DupeCheck - Prg Description"\012\012  Program Description:\012  ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\012  AFL-DupeCheck is a double upload checker. That means\012  that it checks if the file which has been uploaded\012  does already exist or not.\012\012@ENDNODE\012\012@NODE Programlogic\012\012  Programlogic:\012  ¯¯¯¯¯¯¯¯¯¯¯¯\012\012  1) Load ''Doors:AFL-DupeCheck/AFL-DupeCheck_Strings{.<LANGUAGE>}''\012     if it exists. Else the default strings of AFL-DupeCheck will\012     be used!\012  2) Load icon datas (''Doors:AFL-DupeCheck/AFL-DupeCheck.info'')\012  3) Check for file in every conf\012\012     3.1) Check for file in upload paths\012     3.2) Check for file in dir files\012\012  => If file exists then make file private and quit\012\012  4) Check if file name matchs the free download patterns.\012     If yes, then make it free download.\012  5) Start the other doors\012\012@ENDNODE\012\012@NODE Installation "AFL-DupeCheck - Installation"\012\012  Simply copy all these files to your BBS:\012  ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\012  Commands/SysCmd/     FILECHECK.info\012  Doors/AFL-DupeCheck/ AFL-DupeCheck\012                       AFL-DupeCheck.Guide\012\012@ENDNODE\012\012@NODE Tooltypes "AFL-DupeCheck - Tooltypes"\012\012  Tooltypes (''Doors:AFL-DupeCheck/AFL-DupeCheck.info''):\012  ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\012\012  PRG.1=Doors:ConfTop/ConfTop020.x    - Programs which will\012  PRG.2=Doors:Streußelkuchen.exe        be started when the\012  PRG.n=...                             file isn''t a double\012                                        upload\012  FREEDL.1=AFL-                       - Begin patterns which\012  FREEDL.2=5D-                          have to match the file\012  FREEDL.n=...                          name for making it\012                                        a free download\012  CHECK_CONFS.2=2 3                   - If you want to check\012  CHECK_CONFS.4=2 3 4                   more than one conf you\012  CHECK_CONFS.n=...                     have to specify the\012                                        confs which should be\012                                        checked instead of\012                                        conf <n>\012  NOUPPERCASE                         - You can use this option\012                                        if all file names in\012                                        your dir files are upper\012                                        case; this should be a\012                                        bit faster\012  DONOTCHECKULDIRS                    - If you don''t want to\012                                        check the upload paths\012  DONOTCHECKLASTDIR                   - If you don''t want to\012                                        check last dir file\012\012@ENDNODE\012\012@NODE Stringfiles "AFL-DupeCheck - String files"\012\012  String files:\012  ¯¯¯¯¯¯¯¯¯¯¯¯\012  You have the possibility to specify EVERY output\012  text of AFL-DupeCheck. The file you have to edit\012  is ''Doors:AFL-DupeCheck/AFL-DupeCheck_Strings{.<LANGUAGE>}''.\012  You can change all text but there must be ''AFL-DupeCheck''\012  and ''sTc'' anywhere in the first line!\012\012  The line format is the following:\012\012   1) Title text\012   2) Wrong arguments text\012   3) Front text - shown before normal check\012   4) Check file text - shown every time a new dir is checked\012   5) File exists text - shown if file already exists\012   6) File is ok - shown if file doesn''t exist\012   7) No files avail - shown if no files are available\012   8) Check file >LASTDIR< text - shown when the last dir of a conf\012      should be checked but DONOTCHECKLASTDIR is toggled on\012   9) File exists in ul dir text - shown when the file exists in\012      one of the upload dirs\012  10) File is ok >FREE DL< - shown in the way like 6 when the file\012      is a free download\012\012  You can use the following special chars:\012  ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\012  \b                                  - Go to begin of the line\012  \n                                  - Go to next line\012  \\                                  - "\"\012  \e                                  - <ESC>\012  ~S                                  - Check file name\012  ~D                                  - Current dir number\012  ~C                                  - Current conf number\012  ~N                                  - Current conf name\012\012  An example string file is included:\012  ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\012  Doors:AFL-DupeCheck/Examples/AFL-DupeCheck_Strings\012\012@ENDNODE\012\012@NODE Greetings "AFL-DupeCheck - Greetings"\012\012  Greetings:\012  ¯¯¯¯¯¯¯¯¯\012  Celator .... E is the best programming language!\012  Prophet ................ Where are you? Call me!\012  Airworx & Snow ..... There will come a NEW time!\012  Death Angel ...................... Yohooooooooo!\012  Patrick ...................... Dabbeldidubbedii!\012  Stingray .................... Schnabeldidubeldi!\012\012   (#^#) And all other people who I forgot! (#^#)\012\012  Short greetings:\012  ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\012  Lector, Dado, Patrick, Airworx, Circuit Breaker,\012  Mad Doc, cDm, Aladdin,  Dragonhunt, Black Demon,\012  Flite,  Exterminator,  Alf,  Hitman,  Mr.Return,\012  Diogenes, Earthquake, Ice, Frank, Rainer, Fuzzy,\012  Frank Maxwell, Fuzzy Navel, Goonie, Stoker, Eis,\012  Mad Force,  Magic Max, ProMax,  Rapit, Rebel MC,\012  Toolittle, Thunder\012\012@ENDNODE\012\012','\012',char(10)),NULL,'auto-added',14420,3,0,NULL,NULL,'afl_dc01','scan',1780048391);
INSERT INTO door_catalog VALUES('afl_dc02','AFL-DC02.LZX','~/Code/amiexpress_doors/Archives/AmiExpress/AFL-DC02.LZX',NULL,'XIM','AFL-DupeCheck',NULL,NULL,'AFL',NULL,NULL,NULL,NULL,NULL,'auto-added',14067,0,0,NULL,NULL,'afl_dc02','scan',1780048391);
INSERT INTO door_catalog VALUES('afl_dc05','AFL-DC05.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AFL-DC05.LHA','AFL-DupeCheck','XIM','AFL-DupeCheck',NULL,'sTc/AFL','AFL','+----\________   \__   ______/  /----------+ |Alpha /     /    /   _____/   /_____Flight| +-----/    _     /      \/    /     /------+',replace('     ____________________________\n+----\________   \__   ______/  /----------+\n|Alpha /     /    /   _____/   /_____Flight|\n+-----/    _     /      \/    /     /------+\n|     \____/__  /\____  /\_______  /   #1  |\n+-------------\/------\/     RMc!\/--------+\n|    AFL-DupeCheck v0.05 - Full working    |\n+-----------( Coded by sTc/AFL )-----------+\n','\n',char(10)),'AFL-DupeCheck.Guide',replace('@DATABASE AFL-DupeCheck Documentation\012@AUTHOR SvEN tHE CREAToR/AFL\012@INDEX Documentation\012\012Copyright © 1994 SvEN tHE CREAToR/AFL\012\012@REMARK $VER: AFL-DupeCheck v0.05 by sTc/AFL\012@REMARK AmigaGuide database\012\012@NODE Main "AFL-DupeCheck - Main"\012\012          (#) AFL-DupeCheck v0.05 © 1994 by sTc/AFL (#)\012\012                       @{"  Prg Description  " Link PrgDesc}\012                       @{"   Installation    " Link Installation}\012                       @{"     Tooltypes     " Link Tooltypes}\012                       @{"   String files    " Link Stringfiles}\012                       @{"   Programlogic    " Link Programlogic}\012                       @{"      History      " Link History}\012                       @{"     Greetings     " Link Greetings}\012\012@ENDNODE\012\012@NODE PrgDesc "AFL-DupeCheck - Prg Description"\012\012  Program Description:\012  ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\012  AFL-DupeCheck is a double upload checker. That means\012  that it checks if the file which has been uploaded\012  does already exist or not and will move the file to\012  the hold if it does already exist.\012\012@ENDNODE\012\012@NODE Programlogic\012\012  Programlogic:\012  ¯¯¯¯¯¯¯¯¯¯¯¯\012\012  1) Load ''Doors:AFL-DupeCheck/AFL-DupeCheck_Strings{.<LANGUAGE>}''\012     if it exists. Else the default strings of AFL-DupeCheck will\012     be used!\012  2) Load icon datas (''Doors:AFL-DupeCheck/AFL-DupeCheck.info'')\012  3) Check for file in every conf\012\012     3.1) Check for file in upload paths\012     3.2) Check for file in dir files\012\012  => If file exists then make file private and quit\012\012  4) Check if file name matchs the free download patterns.\012     If yes, then make it free download.\012  5) Start the other doors\012\012@ENDNODE\012\012@NODE Installation "AFL-DupeCheck - Installation"\012\012  Simply copy all these files to your BBS:\012  ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\012  Commands/SysCmd/     FILECHECK.info\012  Doors/AFL-DupeCheck/ AFL-DupeCheck\012                       AFL-DupeCheck.Guide\012 (Doors/AFL-DupeCheck/ AFL-DupeCheck_Strings [Examples/])\012\012@ENDNODE\012\012@NODE Tooltypes "AFL-DupeCheck - Tooltypes"\012\012  Tooltypes (''Doors:AFL-DupeCheck/AFL-DupeCheck.info''):\012  ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\012\012  PRG.1=Doors:ConfTop/ConfTop020.x    - Programs which will\012  PRG.2=Doors:Streußelkuchen.exe        be started when the\012  PRG.n=...                             file isn''t a double\012                                        upload\012  FREEDL.1=AFL-                       - Begin patterns which\012  FREEDL.2=5D-                          have to match the file\012  FREEDL.n=...                          name for making it\012                                        a free download\012  CHECK_CONFS.2=2 3                   - If you want to check\012  CHECK_CONFS.4=2 3 4                   more than one conf you\012  CHECK_CONFS.n=...                     have to specify the\012                                        confs which should be\012                                        checked instead of\012                                        conf <n>\012  NOUPPERCASE                         - You must use this option\012                                        if NOT all file names in\012                                        your dir files are upper\012                                        case\012  DONOTCHECKULDIRS                    - If you don''t want to\012                                        check the upload paths\012  DONOTCHECKLASTDIR                   - If you don''t want to\012                                        check last dir file\012  PRGISCOMMAND                        - If you wanna start the\012                                        extra programs (PRG...)\012                                        as AmiEx commands instead\012                                        of real disk programs\012                                        (eg. PRG.1=WHO)\012\012@ENDNODE\012\012@NODE Stringfiles "AFL-DupeCheck - String files"\012\012  String files:\012  ¯¯¯¯¯¯¯¯¯¯¯¯\012  You have the possibility to specify EVERY output\012  text of AFL-DupeCheck. The file you have to edit\012  is ''Doors:AFL-DupeCheck/AFL-DupeCheck_Strings{.<LANGUAGE>}''.\012  You can change all text but there must be ''AFL-DupeCheck''\012  and ''sTc'' anywhere in the first line!\012\012  The line format is the following:\012\012   1) Title text\012   2) Wrong arguments text\012   3) Front text - shown before normal check\012   4) Check file text - shown every time a new dir is checked\012   5) File exists text - shown if file already exists\012   6) File is ok - shown if file doesn''t exist\012   7) No files avail - shown if no files are available\012   8) Check file >LASTDIR< text - shown when the last dir of a conf\012      should be checked but DONOTCHECKLASTDIR is toggled on\012   9) File exists in ul dir text - shown when the file exists in\012      one of the upload dirs\012  10) File is ok >FREE DL< - shown in the way like 6 when the file\012      is a free download\012\012  You can use the following special chars:\012  ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\012  \b                                  - Go to begin of the line\012  \n                                  - Go to next line\012  \\                                  - "\"\012  \e                                  - <ESC>\012  ~S                                  - Check file name\012  ~D                                  - Current dir number\012  ~C                                  - Current conf number\012  ~N                                  - Current conf name\012\012           <=> One example string file is included! <=>\012\012@ENDNODE\012\012@NODE Greetings "AFL-DupeCheck - Greetings"\012\012  Greetings:\012  ¯¯¯¯¯¯¯¯¯\012  Aladdin .............. Much thanks for THE Ansi!\012  Celator ....................... Jehuuu,... Warp!\012  Stoeberhai .................. Thx für PGS!!!!!!!\012  Airworx & Snow ............ Paddy, Foxi: Yamyam!\012  Sabine & Ultra ................ Jodeldideidudaa!\012  Rebel MC ....................... Snief.. Callen!\012  Prophet ..... Blind, latschst einfach vorbei! :)\012  Death Angel ........................ Paddy, too!\012  Patrick ........................ No Pizza bidde!\012  Stingray ....... Der mit der Kleinanzeige tanzt!\012\012   (#^#) And all other people who I forgot! (#^#)\012\012  Short greetings:\012  ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\012  Lector, Dado, Patrick, Airworx, Circuit Breaker,\012  Mad Doc, cDm, Aladdin,  Dragonhunt, Black Demon,\012  Flite,  Exterminator,  Alf,  Hitman,  Mr.Return,\012  Diogenes, Earthquake, Ice, Frank, Rainer, Fuzzy,\012  Frank Maxwell, Fuzzy Navel, Goonie, Stoker, Eis,\012  Mad Force,  Magic Max, ProMax,  Rapid, Rebel MC,\012  Toolittle, Thunder\012\012@ENDNODE\012\012@NODE History "AFL-DupeCheck - History"\012\012  History:\012  ¯¯¯¯¯¯¯\012  v0.01   - First release\012  v0.02   - Added the icon option "PRGISCOMMAND" to start\012            the prg names as AmiEx commands instead of\012            starting''em for real\012          - Fixed the PRG.2+ bug: before that it was only\012            possible to start PRG.1\012          - Fixed the start arguments for the PRG.1+\012  v0.03   - Fully new program structure\012  v0.04   - Fixed the moving to hold\012          - Aladdin/AFL created a nice AFL-DupeCheck_Strings\012            (Much thanks!)\012          - Fixed the PRG.2+ one more time, does really work now\012  v0.05   - Added check-skip if the uploaded file is private\012\012@ENDNODE\012','\012',char(10)),NULL,'auto-added',17732,2,0,NULL,NULL,'afl_dc02','scan',1780048391);
INSERT INTO door_catalog VALUES('afl_del','AFL-DEL.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AFL-DEL.LHA','AFL-DEL','XIM','AFL-DEL',NULL,'SPY/AFL','AFL',NULL,replace('AFL-DEL: PROGRAMMED BY SPY/AFL\n','\n',char(10)),'AFL-DEL.DOC',replace('                             _______  _______  __\n                            /       \/    ___\/  \\n                           /   /   //   /_  ~/   /_\n                          /       //   __/  /   /_ \\n                          \__/   / \__/     \___~  /\n                             ~\_/ALPHAFLIGHT=''93\_/\n                                ===PRESENTS:===\n\n                        AFL-DEL: PROGRAMMED BY SPY/AFL\n                           DOCS: TRANSLATED BY CINDARELLA/AFL\n\n\nAFL-DEL IS A TOOL WHICH DELETES FILES AUTOMATICALLY THROUGH SEVERAL CRITERIA.\n\n1. IF THE DISCSPACE IS SHORTER THAN THE SPECIFIED SIZE\n2. IF THE FILES ARE OLDER THAN X DAYS\n3. IF THE DISCSPACE IS SHORTER THAN THE SPECIFIED SIZE AND THE FILES ARE\n   OLDER THAN X DAYS\n4. IF THE DISCSPACE IS SHORTER THAN THE SPECIFIED SIZE OR  THE FILES ARE\n   OLDER THAN X DAYS\n\nTHE BEST WHAT YOU CAN DO IS STARTING AFL-DEL OUT OF THE TPTCRON TOOL.\nAFL-DEL INFORMS A SPECIFIED USER THAT CERTAIN FILES WERE DELETED OR COPIED\nTO ANOTHER DIR. AFL-DEL CHANGES THE UPLOAD DIR FILE AND DELETES THE\nDESCRIPTIONS OF THE DELETED FILES.\n\n\n- IF WANTED, AFL-DEL ADDS THE DESCRIPTIONS FROM THE DELETED FILES TO AN OLD\n  DIRFILE AND CHANGES THE FILE SIZE TO "DELETED".\n- IF WANTED, AFL-DEL COPIES THE FILES IN ANOTHER DIRECTORY BEFORE IT`S\n  DELETING THEM.\n- IF WANTED, AFL-DEL CREATES NIL FILES IN ANOTHER DIRECTORY WHICH HAVE THE\n  NAMES OF THE DELTED FILES.\n\n\nOK NOW THE STRUCTURE OF THE CONFIG FILE NAMED S:AFL-DEL.CFG :\n\nLINE 1  : THE USERNAME OF THE USER WHICH IS GETTING THE "DELETED" MESSAGE\nLINE 2  : PATH TO THE CONFERENCE, WHERE AFL-DEL SHOULD SEND THE MAIL\nLINE 3  : THE CRITERION TO DELETE THE FILES (1 TO 4) :\n          1 = ONLY DISCSPACE       (FILL OUT LINE 1+2+3+4+5+7+8+9+10+11\n                                   WITHOUT LINE 6)\n          2 = ONLY DAYS            (FILL OUT LINE 1+2+3+6+7+8+9+10+11\n                                   WITHOUT LINE 4+5)\n          3 = DISKSPACE AND DAYS   (FILL OUT ALL LINES)\n          4 = DISKSPACE OR DAYS    (FILL OUT ALL LINES)\nLINE 4  : MINIMUM DISCSPACE (THE SPACE WHERE AFL-DEL STARTS TO DELETE)\nLINE 5  : HIGHEST DISKSPACE (THE SPACE WHERE AFL-DEL ENDS TO DELETE)\nLINE 6  : A NUMBER WHICH SPECIFIES THE DAYS WHERE AFL-DEL STARTS TO DELETE\n          THE FILES\nLINE 7  : UPLOAD DIR (WHERE AFL-DEL DELETES THE FILES)\nLINE 8  : UPLOAD FILELISTING (THE FILEDESCRIPTIONS)\nLINE 9  : OLD FILELISTING (OPTIONAL ! AFL-DEL ADDS THE DESCRIPTIONS FROM\n          THE FILES IN THIS LISTING. IF THE LINE IS EMPTY AFL-DEL DOESN`T\n          DO IT)\nLINE 10 : COPY PATH (OPTIONAL ! AFL-DEL COPIES THE FILES IN THIS DIR. IF\n          THE LINE IS EMPTY AFL-DEL DOESN`T DO IT)\nLINE 11 : NIL FILE PATH (OPTIONAL ! IN THIS DIR AFL-DEL MAKES NIL FILES WITH\n          THE NAME OF THE DELETED FILES. IF THE LINE IS EMPTY AFL-DEL\n          DOESN`T DO IT)\nIF THERE IS ANOTHER UPLOAD DIR AND YOU WANT THE SAME CRITERIA, THEN START\nAGAIN AT LINE 7 TO 11.\nIF THERE IS ANOTHER UPLOAD DIR AND YOU WANT NEW CRITERIA THEN START AT LINE 3\nTO 11.\nYOU SEE, YOU CAN HANDLE THE UPLOAD PATHES AS DIFFERENT AS YOU WANT !\n\nEVERY LINE WHICH IS OPTIONAL AND NOT WANTED, MUST BE INSERTED AS A BLANK LINE.\nTHE LINES 4,5,6 ARE DEPENDING FROM LINE 3. IF LINE 3 IS 1 THEN INSERT ONLY\nLINE 4+5. IF LINE 3 IS 2 THEN INSERT ONLY LINE 6. IF LINE 3 IS 3 OR 4 THEN\nINSERT LINE 4+5+6.\n\n------------------------------------------------------------------\n|                                                                |\n| NOTE : LINES 4+5+6 ARE NOT OPTIONAL. IF THEY ARE NOT NEEDED,   |\n|        KEEP THEM OUT OF THE CONFIG FILE !!!!!!                 |\n|                                                                |\n------------------------------------------------------------------\n\nOK HERE ARE TWO EXAMPLES FOR CONFIG FILES :\n\n\n-------------------------------- CUT HERE ---------------------------------\nSPY/AFL\nBBS:CONF-1/\n1\n20000000\n50000000\nBBS:CONF-1/UPLOAD/\nBBS:CONF-1/DIR2\nBBS:CONF-1/DIR1\nDH1:COPY/\nBBS:CONF-1/OLDFILES/\n-------------------------------- CUT HERE ---------------------------------\nTHESE CONFIG FILE DELETES FILES IN DIR BBS:CONF-1/UPLOAD/\nTHE DESCRIPTIONS FOR THIS DIR IS IN BBS:CONF-1/DIR2 . THE DESCRIPTION OF\nTHE DELETED FILES WERE ADDED TO BBS:CONF-1/DIR1 AND DELETED IN\nBBS:CONF-1/DIR2 . THE FILES FROM BBS:CONF-1/UPLOAD/ ARE COPIED TO DIR\nDH1:COPY/ BEFORE THEY WERE DELETED. NIL FILES WITH THE NAMES OF THE DELETED\nFILES WERE DONE IN DIR BBS:CONF-1/OLDFILES/\n\n\nOK NOW THE SECOND CFG FILE\n\n-------------------------------- CUT HERE ---------------------------------\nSPY/AFL\nBBS:CONF-1/\n1\n30000000\n40000000\nBBS:CONF-1/UPLOAD/\nBBS:CONF-1/DIR4\nBBS:CONF-1/DIR3\nDH1:COPY/\nBBS:CONF-1/OLDFILES/\n2\n31\nBBS:CONF-2/UPLOAD/\nBBS:CONF-1/DIR3\n\n\nBBS:CONF-2/OLDFILES/\n3\n50000000\n60000000\n31\nBBS:CONF-3/UPLOAD/\nBBS:CONF-3/DIR2\nBBS:CONF-3/DIR1\nDH1:COPY/\n\n4\n50000000\n60000000\n31\nBBS:CONF-4/UPLOAD/\nBBS:CONF-4/DIR3\nBBS:CONF-4/DIR2\nDH1:COPY/\nBBS:CONF-4/OLDFILES/\nBBS:CONF-5/UPLOAD/\nBBS:CONF-5/DIR4\nBBS:CONF-5/DIR3\nDH1:COPY/\nBBS:CONF-5/OLDFILES/\n----------------------------- CUT HERE -------------------------------------\nIN THIS CONFIG FILE ARE ALL POSSIBILITIES OF DELETION FROM AFL-DEL.\nFOR BBS:CONF-1/UPLOAD/ IS CRITERIA 1. FOR BBS:CONF-2/UPLOAD/ IS CRITERIA 2.\nFOR BBS:CONF-3/UPLOAD/ IS CRITERIA 3. FOR BBS:CONF-4/UPLOAD/ IS CRITERIA 4.\n','\n',char(10)),NULL,'auto-added',19916,9,0,NULL,NULL,'afl_del','scan',1780048391);
INSERT INTO door_catalog VALUES('afl_gdb','AFL-GDB.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AFL-GDB.LHA','GoodBye','XIM','EXE-ME!.CC','2.',NULL,'AFL',NULL,replace('LogoFF Door For /X V2.xx\n','\n',char(10)),'GOODBYE.txt',replace('~3SR_DOORS:SCREENS/LOGOFF|\n','\n',char(10)),NULL,'auto-added',26827,6,0,NULL,NULL,'afl_gdb','scan',1780048391);
