INSERT INTO door_catalog VALUES('afl_p21','AFL-P21.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AFL-P21.LHA','Pager21','XIM','___________________    ___________________',NULL,'fanta,','AFL','\____   \_ ____/  /___ \_    \_  / //___  \ /      ./  __/// /   /&/  /__/    ·/  _  _/ /___/  //___/ /______/ /__/  // /__/___/  /',replace(' ___________________    ___________________\n \____   \_ ____/  /___ \_    \_  / //___  \\n /      ./  __/// /   /&/  /__/    ·/  _  _/\n/___/  //___/ /______/ /__/  // /__/___/  /\n===/___/=·[Presents]·=Dt/aFL/__/==''94=/__/==\n     Pager21 By fanta, SoNy & Zorlaç\n','\n',char(10)),'Pager21.doc',replace('\n                             OperatorPager v2.1\n                              by fanta,SøNÝ & Zorlac\n\n               » Another aLPHAa fLIGHt & The®¡øN Production «\n\n\n                                    Why?\n\nSandman wanted an pager who used the built in function and you could\nconfigurate with some text. He wanted that the user should leave a comment\nif he was not home. This version has a question included if the sysop isn''t\nat home as requested by Cybertron. Of course we made it in C to accomplish\nsome speed.\n\n\n                                 Disclaimer\n\nWe don''t take any responsibility for any damage this door make on your\ncomputer hardware or software. It has been fully tested so it shouldn''t\ngive ya any problems.\n\n\n                                Installation\n\n-Copy the file BBS/Doors/pager21/pager21 to Doors:pager21/ (or wherever\n you keep  your doors) if you have a 030 ør 040 use 030/040 and just\n rename it to pager21 and copy.\n\n\n                                  /X 2.xx\n\n-Modify your custom-commands and add the following line:\n\n*o        XM010Doors:pager21/pager21\n\n^         ^    ^\n|         |    |_ Or wherever you put the pager21.\n|         |\n|         |___ Notice the "X" pager21 is an XIM door!\n|\n|______ The name to run.\n\n                                  /X 3.xx\n\n-Copy the icon BBS/Commands/BBsCmd/o.info to BBS/Commands/BBsCmd/\n\n\n\n                                   Notice\n\n\nYou can configurate this door in the info:\n\nFRONTTEXT=<textfile>    <--- text that are shown before the actuall paging\nNOTHOMETEXT=<textfile>  <--- text shown if sysop chatflagg is off\n\n\n                            Main Files included\n\n               Filename                             Org. Size\n\n\n       BBS/Doors/pager21/pager21                       12384\n\n       BBS/Doors/pager21/pager21.030                   12384\n\n       BBS/Doors/pager21/pager21.040                   12384\n\n       BBS/Doors/pager21/pager21.Doc                    3349\n\n\n\n                                 Since 1.0\n\nWe have completly rewritten the code so you don''t are dependent of\nAEDoor.library. Now you can configure this door in the icon. A question\nis now included if the sysop isn''t home.\n\n\n\n\n\n\n To provent any backdoors d¡al...    ..to get the orginal & latest version.\n\n\n\n  __________  ___________ ____________\n  \_____  _/  \__  _  __/ \__  |    _/\n   ___|    \  /    |    \  /   ¦     \  +¢6(°)³²²/¹9°97\n  /   |     \/     |     \/    :      \_________________ _ _  _    _\n /    ¦      \     ¦      \_______     \\n/     :       \    :       \/           \     Sysop¹:fanta\n\             /            /            /\n \___________/____________/    ________/      Sysop²:S0Ny\n        |                 \_____|\n        |        14400         _________  _______ _________ _____________\n        |     DualStandard     \___   _ \ \___   |\______  \\_____  ____/\n        ¦    DualSysopPower      /    |  \/      |  /  |    \  /    ___|\n        :  Kicking with /X 2.3  /     ___/__     | /   |     \/     |\n        ·                      /            \_   |/    ¦      \     l____\n        .    ·¹·Dayz warez    /     \        /   |     :       \         |\n              Therion WHQ     \      \      /    |     ·       /         |\n        . Online Door Ordering \______\    /_____|____________/__________|\n                                       \__/j\n\n\n\n\n\n[EOF]','\n',char(10)),NULL,NULL,26855,2,0,NULL,NULL,'afl_p21_pager21','scan',1780048391);
