INSERT INTO door_catalog VALUES('afl_skip','AFL-SKIP.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AFL-SKIP.LHA','OnlineSkip','XIM','____________________________',NULL,'ZERØ/AFL','AFL','+----\________   \__   ______/  /----------+ |ALPHA /     /    /   _____/   /_____FLIGHT| +-----/    _     /      \/    /     /------+',replace('     ____________________________           \n+----\________   \__   ______/  /----------+\n|ALPHA /     /    /   _____/   /_____FLIGHT|\n+-----/    _     /      \/    /     /------+\n|     \____/__  /\____  /\_______  /   #1  |\n+-------------\/------\/REBEL MC!\/--------+\n|         PRESENTS A NEW /X-TOOL           |\n+-   ONLINE SKIP v0.1 - (W) BY ZERØ/AFL   -+\n','\n',char(10)),'OnlineSkip.DOC',replace('\nThis tool was written especially for lazy sysops (and also lazy uploaders).\nLet''s  say you (as (co-)sysop) have seen that a special file has been faked\non  some  boards.  The  next  thing  you''ll  (probably)  do  is to write an\nEALL-mail  saying  not  to  upload  that faked file or your credits will be\ngone.\nThen  you''ll  create a fake-file to prevent those lazy uploaders that don''t\nread all EALLs to upload the faked file you saw somewhere else.\nSome hours later ;-) you have finished all that shit.\n\nThis door makes it all easier.\nJust\n1. call this door\n2. enter the filename of the faked file\nand everything else will be done automatically.\nThe  result  is  an  EALL-mail  saying  that you lose your credits when you\nupload  the  fake  and  a  fake-file in the respective upload dir making it\nimpossible to upload the faked file if someone tries it nevertheless.\n\n                                                                   ZER0/AFL\n\nThis door runs fine with /X V3.x\nDon''t forget to set your ULPATH in your conference-icons.\n','\n',char(10)),NULL,NULL,16975,4,0,NULL,NULL,'afl_skip_onlineskip','scan',1780048391);
INSERT INTO door_catalog VALUES('afl_sq11','AFL-SQ11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AFL-SQ11.LHA',NULL,'XIM','!!! SHaDoW-QueST !!!','1.1',NULL,'AFL',NULL,replace('!!! SHaDoW-QueST V1.1 !!!\n','\n',char(10)),'SHADOW-QUEST.DOC',replace('INSERT INTO door_catalog VALUES('afl_stat','AFL-STAT.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AFL-STAT.LHA','WaRNiNG','XIM','U-Stat.exe',NULL,NULL,'AFL','|ALPHA /     /    /   _____/   /_____FLIGHT| +-----/    _     /      \/    /     /------+ |     \____/__  /\____  /\_______  /   #1  |',replace('+----\________   \__   ______/  /----------+\n|ALPHA /     /    /   _____/   /_____FLIGHT|\n+-----/    _     /      \/    /     /------+\n|     \____/__  /\____  /\_______  /   #1  |\n+-------------\/------\/REBEL MC!\/--------+\n+-    S¡eGeL/aFL & aRGøN/aFL PReSeNTS:    -+\n+-  U-STAT V1.0 replaces Built-In "S" CMD -+\n','\n',char(10)),'U-Stat.doc',replace('            ___       ___ ______________________/\  ____/\__  /\_____\n           |   |     / __\\__  __/  _____/  ____  \|  _/ __ \/  ____/\n           |   |__: / _|  \ |  |/ \/_)__/ \/_)_|      |  (/  \__   \ \n           |   /  \/  \_   \|  |\   \  |\   \  |      |      /  |  /.\n           |______ \___| __/| _|:\_____|:\_____| /\___|\____/___  /::\n           =======\/===|/===|/=================|/===============\/\n                     B       -         B         -          S\n\no*¤°¬¯¬°¤*o,¸_¸,o*¤°¬°¤*o,¸_¸,o*¤°¬¯¬°¤*o,¸_¸,o*¤°¬°¤*o,¸_¸,o*¤°¬¯¬°¤*oo*¤°¬¯¬\n\n                        S¡eGeL/aFL & aRGøN/aFL PReSeNTS:\n\n \n                                 U-STAT V1.0\n	                         ~~~~~~~~~~~\n\n\no*¤°¬¯¬°¤*o,¸_¸,o*¤°¬°¤*o,¸_¸,o*¤°¬¯¬°¤*o,¸_¸,o*¤°¬°¤*o,¸_¸,o*¤°¬¯¬°¤*oo*¤°¬¯¬\n\nHi Folks!!!!\n \nWell, I''m (SieGeL) very proud to present U my first /X-Tool called U-STAT !!!!\nThiz Tool replaces the Built-In Command "S" with an very cewl User-Information\nScreen, on which U can see more than enough I think so...:)\n\nIf u want to use this little Tool, than get a TextEditor and change Ur BBS.CMD\nFile for the following:\n\n--- Cut here ---\n*S         XM050DOORS:U-STAT/U-STAT.EXE\n--- Cut here ---\n\nWell thats all ... very easy eh ??? Hope ya like this neaty Tool....:)\n \nGreetings:\n~~~~~~~~~~\nSaBiNe/aFL     - THX for joining your Group....:)\n\naRGoN/aFL      - For helping with the Graphics Dezign and givin'' me the idea !\n\nByteAndi/MST   - Well...U are a very cewl Programmer...hope to see ya in the\n                 next few weeks !!!!\n\nStrider/Shades - Yar BBS-Tools are very nice....keep on programming !!!\n\nSTB/2000 A.D.  - Ur BBS is cewl...if I get a faster Modem, I will call U !!!\n\nWolle/Indy     - Thx that U don''t kicked me out of Ur BBS...sometimes I will\n                 have more than 230 CPS !!!! :)\n\nCaN,GeNSCHMaN,\naNNY,Stein     - Thx for ur moral Support...FRIENDSHIP RULEZ !!!!\n\no*¤°¬¯¬°¤*o,¸_¸,o*¤°¬°¤*o,¸_¸,o*¤°¬¯¬°¤*o,¸_¸,o*¤°¬°¤*o,¸_¸,o*¤°¬¯¬°¤*oo*¤°¬¯¬\n\n- EOF -\n','\n',char(10)),NULL,'auto-added',11904,3,0,NULL,NULL,'afl_stat','scan',1780048391);
