INSERT INTO door_catalog VALUES('aflcom1','AFLCOM1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AFLCOM1.LHA','comment1','XIM','comment1',NULL,NULL,NULL,'.--/ _ \\_______/  |__ \/--ALPHA FLIGHT-\/-. | /  _  \/  __/|   |  \        ·-·         | |//  |___\___| |_______\    PRESENTS!      |',replace('    ___ ___________.                        \n.--/ _ \\_______/  |__ \/--ALPHA FLIGHT-\/-.\n| /  _  \/  __/|   |  \        ·-·         |\n|//  |___\___| |_______\    PRESENTS!      |\n/____|Stz-------------------------------/\-+\nPresents: Comment to Sysop''s V1.1           \n','\n',char(10)),'comment.doc',replace('\n                   ALPHA FLIGHT PRESENTS\n\n                  Comment To Sysop`sV 1.1\n                  ~~~~~~~~~~~~~~~~~~~~~~~\nThis tool iss an /X Door, please insert in you`re bbs.cmd:\n\n*C        XM010DOORS:comment\n\nand put in you`re s: dir a File names: comment.cfg.\nWe have sent You an Example how to use this File.\nThe first Line must have the Full Path to the User.data.\nThe next Line must have The right Sysop or Cosysop Name (max 24).\nthan you must insert the Commentfor the Sysop or Cosysop (max 34).\nand now you can do it for 9 (Co)SySoP`s.\n\nWe hope you like our Tool and send us any messi if the tool have \nany Probs.\nIn our tools are no Backdoor`s !!!!\nWe hate Backdoors !\n\nThis tool where written in :\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n________________________________________________________________________\n/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\\n""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""\n         ___         >> HeadQuarter of AFL <<       ________\n        /   \                                      /        \\n  //// /     \    ___  ______  ______  ______  _   \    \    \ \\\\\n //// /    \  \  /   \/      \/      \/      \/ \   \    \    \ \\\\\n /// /      \  \/    /   /   /\  \___/\   \   \  \  /\    \    \ \\\\n // /       /  /    /       / /  /   \ \   \   \  \/  \         \ \\\n/ /          /    /   /   / /  /     \ \       \      \         \ \\n  \_________/\___/\__/___/  \________/  \______/\_____/\________/\n\n                    >> CALL +49 03 621 23 12 <<  SySoP`s ArE\n                    >>  OR  +49 03 621 87 87 <<      Byteandi &\n                    >>  OR  +49 03 622 19 94 <<          FuZzY\n                      \n >> RUNNING ON AMIGA 3000 25Mhz, 220MB AMIGA AND PC STUFF ONLINE <<\n ________________________________________________________________________\n/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\\n""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""\n','\n',char(10)),NULL,'auto-added',13132,2,0,NULL,NULL,'aflcom1','scan',1780048391);
INSERT INTO door_catalog VALUES('aflcom2','AFLCOM2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AFLCOM2.LHA','comment','XIM','Comment',NULL,NULL,NULL,'Comment To Sysop`sV 2.0 33.6 DigITal-X Prd/NirVana Dist Site! 33.6',replace('  ALPHA FLIGHT PRESENTS\nComment To Sysop`sV 2.0\n33.6 DigITal-X Prd/NirVana Dist Site! 33.6\n','\n',char(10)),'comment.doc',replace('\n                           ALPHA FLIGHT PRESENTS\n\n                         Comment To Sysop`sV 2.0\n                         ~~~~~~~~~~~~~~~~~~~~~~~\n\nThis tool is an /X Door, please insert in your bbs.cmd:\n\n*C        XM010DOORS:comment\n\nand put in your s: dir the file named comment.cfg\nWe have sent you an example on how to use this file.\nThe first line must have the exact Sysop or Cosysop Name (max 24 chars).\nThe next line must have the comment for the Sysop or Cosysop (max 34 chars).\nThis is possible for 9 (Co)SySoP`s.\nWith that tool the User can send you a message per Upload or Editor !\n\nWe hope you like our Tool and send us any messi if you have any probs with\nthe tool.\n\n\n\n\n\nwhat have we done ?\n~~~~~~~~~~~~~~~~~~~\n\nI have found an error in the tool which messes up the message base if some\nusers write mail on two nodes at the same time. Now I have made the code \nfaster and I think the problem is solved too.\n\nNow the door doesn`t need the path for the user.data so you can use it \nin the /X 3.1 and /X 2.39.\n\nI have installed hotkeys for the questions, because I think it looks better.\n\n\n\n\nthanks and greetings to:\n~~~~~~~~~~~~~~~~~~~~~~~~\n\n Re/Y\o/AFL for help to install the /X 3.1 and other\n FuZzY/AFL  for help in the BBS\n Sabine/AFL for support\n all AFL member............\n\n\nThis tool is written for :\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n                           ·           .     ·     .\n                        ·  :                 .     :     :\n                 _______:__:_____:_____:_____:___ _|_____|__\n-============-   \____ ¬V ¬V___ ¬V___ ¬V___ ¬V ¬|  |___ ¬|   MANAGEMENT\n ALPHA FLiGHT     | ¬|  |  | ¬|  | ¬|  | ¬|  |  |  | ¬|  |   -========-\n      HQ          |  |  |  |  |  |  |  |  |  |  |  |  |  |   ANDi/AFL\n-============-    |  |  |  |     |    _|  |  |  |__|  |  |   FuZzY/AFL\n                  |  |  |  |  |  |  | ¬|  |  |  | ¬|  |  |   Re/Y\o\n-ELiTE oNLY-      |  |  |  |  |  |  |  |  |  |  |  |  |  |\n                  |  |  |  |  |  |  |  |  |  |  |  |  |  |   SYSTEM\nCALL US NoW FoR   |  |  |  |  |  |  |  |  |  |  |  |  |  |   -====-\nTHE NEWEST AMiGA/ |  |  |  |  |  |  |  |  |  |  |  |  |  |   RUNS oN A3000\nPC-stuff& /X tools|  |  |  |  |  |  |  |  |  |  |  |  |  |   WiTH 25MHZ AND\nAND ALL AFL-      |  |  |  |  |  |  |  |  |  |  |  |  |  |   AMiEX (REG.)\nRELEASES.         |  |  |  |  |  |  |  |  |  |  |  |  |  |\n                __|_____A__A__A__A_____A_____A_____A_____|D! SUPPoRTET BY\nWE oNLY ACCEPT    |     :  :     :     :     :     :     |   -==========-\n9600 - 16.800     :     ·  .     .           .     ·     :   ALPHA FLiGHT\nBAUD CoNNECTS.    .        .                                      &&\n                   NoDe 1 +49 30 621 2312 - Zyxel 16.800      þþþRANXþþþ\nASK oNE SYSoP FoR  NoDe 2 +49 30 621 8787 - DUAL  14.400\nTHE NEW USER PWD!  NoDe 0 +49 30 622 1994 - HST   14.400\n\n','\n',char(10)),NULL,'auto-added',16802,12,0,NULL,NULL,'trsi_c13_2','scan',1780048391);
INSERT INTO door_catalog VALUES('aflfro11','AFLFRO11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AFLFRO11.LHA','AFL_Front11','XIM','AFLFRO11.LHA AFL_Front11',NULL,NULL,NULL,NULL,replace('Frontstatus Version 1.1 -Major Bugs Removed!\n','\n',char(10)),'AFL_Front11.doc',replace('\n                ____________.  ________________ ___    _______\n               /°  __ ¬\°  ¬| _\_________  ¬\ø Y° ¬\  /°  __ ¬\\n              /ø  _|/   \   |/ ¬\| ø  _|/   /!_|    \/ø  _|/   \\n             / !  \_     \  /    \ !  \____/ :\_     \!  \_     \\n             \ :   |     /       / :   | \     |     /:   |     /\n              \____|   ø/__    ø/|   ø_|  \____|   ø/\____|   ø/\n               ====|___/===\___/=|___/=========|___/======|___/\n      _________________.     _____   _______     ___ ___________________\n      \_______    °/  °| __ (_____) /ø     ¬\   /ø  Y° ¬\°        `93 °/\n        |ø   ¬\___/ø   |/ ¬\|ø   ¬|/ !  \___/  / ! _|    \   .ø   .   /\n        |!    __/| !   /    \!    |  :  /   ¬\/  : \_     \_/|!   |\_/\n        |:    |  | :        /:    |    /      \     |     /  |:   |\n        |   ø_|  |____    ø/|   ø_|\______   ø/\____|   ø/   |_  ø|\n        |___/=========\___/=|___/=[-sLa-]=\__/======|___/======\__|\n\n                    ^ø^   tHiS fLiGhT WiLL nEvEr sTøP  ^ø^\n                          ¯¬°¤ø¤°¬¯¯¬°¤ø¤°¬¯¯¬°¤ø¤°¬¯\n\n          PRESENTS TODAY ANOTHER AFL RELEASE: FRoNT-STATUS V1.1\n                        © 1993 by FuZzY/AFL\n\n\n\nWHAT DOES IT DO ?\n~~~~~~~~~~~~~~~~~\nFrontstatus will tell all Users in the Login the activity on the other\nNodes. Also it will show you the Action of the other and general Infos\nabout all other active Nodes.\n\nINSTALL THIS TOOL\n~~~~~~~~~~~~~~~~~\nIn the pack following Files must be included:\n\n       AFL_FRONT11       -    THE TOOL\n       FRONTEND.INFO     -    THE COMMAND.INFO FILE FOR /X\n       AFL_FRONT11.DOC   -    THIS DOC FILE\n\nFirst you must copy the File Frontend.info in the dir:\n  BBS:COMMANDS/SYSCMD/\n\nThen copy the File AFL_FRONT11 in your doors: dir.\nThats all....have fun with this Tool and like it or not. :)\n\nFuZzY oF ALPHA FLiGHT`93\n\n\nHISTORY\n~~~~~~~\nV1.0  Released: 06-20-93\n      First Version of this Utility. Some Bugs included. :)\n\nV1.1  Released: 07-02-93\n      Same Features like V1.0 but many Bugs removed.\n\n\nGREETINGS FLYING TO:\n~~~~~~~~~~~~~~~~~~~~\nWHiTE ANGEL   : I love you ! :)\nSpy/AFL       : Cool programming and thanx for help.\nAndi/AFL      : Yo man ! Weiter so...:) And thanx for your help.\nVAN DAMME/LSD : Very good Tools. But why you don`t programm in C ??\nSABINE/AFL    : Thanx for your loyality. I`ll do my best. :)\n\nALL OTHER AFL MEMBERS and ALL I`VE FORGOTTEN HERE.\n\n\nTO CONTACT ME CALL NOW:\n\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                    -ALPHA FLiGHT GERMAN HEADUATER-\n_____________   _____   ____________________  ____________.    _______\n\_________  ¬\ (_____) /°  __ ¬\_________  ¬\/°   _ ¬\ø  °| __/°   _ ¬\\n   |ø ° | \   \|ø   ¬|/ø  _|/   \|ø  °_|/   /ø  _/ \  \   |/ ¬\ø _/ \  \\n   |!   | / °  \!    | !  \_     \!   \__  °\!  \  /  °\  /°   \ \  /  °\\n   |:   |/     /:    | :   |     /:    |/    \   \/    /       /  \/    /\n   |_____    ø/|   ø_|\____|   ø/|______    ø/___    ø/__    ø/___    ø/\n   ======\___/=|___/== ====|___/=[-sLa-]\___/====\___/===\___/====\___/\n                                                            BBs BERLiN\n\n      SYSoPS: ANDi/AFL & FuZzY/AFL      CoSYSoPS: FELDMAN\n\n   NoDE0 +49 30 6221994    NoDE1 +49 30 6212312    NoDE2 +49 30 6218787\n\n                  -THE HoME oF THE CooL AFL-/X-TooLS-\n\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~','\n',char(10)),NULL,'XIM-BBSCmd',12090,3,0,NULL,NULL,'aflfro11_afl_front11','scan',1780048391);
INSERT INTO door_catalog VALUES('aflfront','AFLFRONT.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AFLFRONT.LHA','AFL_FRONT10','XIM','AFL_FRONT10','1.0','FuZzY/AFL',NULL,NULL,replace('FRoNT-STATUS V1.0 By FuZzY/AFL\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 19:29:03  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',8155,1,0,NULL,NULL,'aflfront','scan',1780048391);
INSERT INTO door_catalog VALUES('aflnew4','AFLNEW4.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AFLNEW4.LHA',NULL,'XIM','newfiles.000',NULL,NULL,NULL,'|ALPHA /     /    /   _____/   /_____FLIGHT| +-----/    _     /      \/    /     /------+ |     \____/__  /\____  /\_______  /   #1  |',replace('+----\________   \__   ______/  /----------+\n|ALPHA /     /    /   _____/   /_____FLIGHT|\n+-----/    _     /      \/    /     /------+\n|     \____/__  /\____  /\_______  /   #1  |\n+-------------\/------\/REBEL MC!\/--------+\n+- NewFile v1.4 - Display the filelisting -+\n+- in a better way.                       -+\n','\n',char(10)),'NewFiles.doc',replace('****************************************************************************\n*                                                                          *\n*                         Yet another AFL release:                         *\n*                               NewFile v1.4                               *\n*                    (/X filelisting enhancement tool)                     *\n*                          © 1993 by ByteAndi/AFL                          *\n*                                                                          *\n****************************************************************************\n\nWhat does it do ?\n~~~~~~~~~~~~~~~~~\nNewFile will display the filelisting in some nicer way then the ordinary\nfilelisting you are used to ... It also has some more features then you\nhave with the original f-, n- and n s u commands ...\n\nWhat is New ?\n~~~~~~~~~~~~~\n\nI have change many Routine`s and have killed the "f" Fake !\n\nNow the Door will search for the Filelist on you`re HD \nif the Rest of you`re Fast-ram is to small !\n( I think it Works Finely, because my Ram: is to big to test it enough)\n\nNow you can Insert CRTL-C and the Door will stop ! \nThe Droped Carier is Working better as before\n\nThe Help`s are now Free to Configure, because my English is so Lame \nand Style it however you want\n\nthe "ns" Option in the Mainline is changed:		NS --> Nonstop\n												N  --> Quit\n												Q  --> Quit\n\nI have Installed ToolTypes To Configure what ever you want :\n\nThe Door is Compatibler to /X because I have installed the "n mm dd yy" Option,\nbevore that you must insert "n mm-dd-yy". I think it is not a Great Change, \nbut many Trader Like it.\n\nYou can change the Newdate-Line and install in all Confs \nan other Newdate_Line !\n\nAll Colors from the Filelist how ever you want !\n\nYou can Insert, witch Level can scanned you`re Hold Directory\n\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nNewFiles.Info TOOLTYPES :\n~~~~~~~~~~~~~~~~~~~~~~~~~\nnewfiles/NewFiles.Info should contain the following lines _ON is enabled and\n_OFF is disabled ofcoz\n\nANSI=ON        ------------> gives Ansi in the filelisting\nNS=ON          ------------> means you can use NS after each command line\nDATE=ON        ------------> puts dateheader when date changes \nLINES=ON       ------------> displays bars between different uploads\nRETURN=ON      ------------> puts returns between different uploads\nSENTBY=ON      ------------> puts the "sent by: Username" in Ansi Color\nSELF_EDIT=ON   ------------> the User can configure the Filelist styling himself\nHOLD_LEVEL=245 ------------> will give The User with Level 245 Access to scan the Hold\n^^^^^^^ ------> IMPORTANT--IMPORTANT--IMPORTANT--IMPORTANT--IMPORTANT--IMPORTANT--\n\nNew Options:\n~~~~~~~~~~~~\n\nDATE_LINE_COLOR=GREEN \n\nmakes The NewDateLine GREEN,\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nNEW_DATE_COLOR=RED\n\nmakes the NewDate in the NewDateLine RED\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nTEST_COLOR=VIOLETT\n\nmakes the "P","N","F" in the Filelist Violett\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nBYTE_COLOR=YELLOW\n\nmakes the Bytes in Yellow\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nDATE_COLOR=BLUE\n\nmakes the Date in Blue\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nSENTBY_COLOR=BLUE\n\nmake the Send by (if exist) in Blue\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nDATE_LINE.x=Diabolo BBS  Date: $SHOW_THE_NEW_DATE Conference:Amiga-Warez \n\nx -----------------------> ConferenceNumber\n$SHOW_THE_NEW_DATE ------> insert that and you see the Date on this Place\n\nExample:\n~~~~~~~~\n                Diabolo BBS  Date: 07-25-93 Conference:Amiga-Warez\n\nstand then in you`re Filelist in the NewDateLine.\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nDATE_LINE=Diabolo BBS  Date: $SHOW_THE_NEW_DATE Conference:All\n\nif you have the "DATE_LINE.x=" not installed or one of you`re Confs have no \n"DATE_LINE.x=" then The Door will search for "DATE_LINE=".\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nyou can Use this Colors:\n~~~~~~~~~~~~~~~~~~~~~~~~\nRED,\nGREEN,\nVIOLETT,\nYELLOW,\nDARK,\nBLUE,\n\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nThis util also works when you have DirStyle build in ...\n\nHow to use it\n~~~~~~~~~~~~~\nHere are the commands you can use:\n\nn w           The User can make a config for his Account\n^^^------> IMPORTANT--IMPORTANT--IMPORTANT--IMPORTANT--IMPORTANT--IMPORTANT--   \n\nn             first you will be prompted for the date and than the listing ...\n\nn ?           will show the help ...\n\nn w           Let you change the style from the Filelist\n\nn t           displays all new files from today in the upload dir\nn t u         displays all new files from today in the upload dir\nn t a         displays all new files from today in all dirs\nn t h         displays all new files from today in the hold dir\n\nn s a         displays all new files since last on in all dirs\nn s u         displays all new files since last on in upload dir\nn s h         displays all new files since last on in hold dir\n\nn -x          displays all files from x days before last on in upload dir\nn -x u        displays all files from x days before last on in upload dir\nn -x a        displays all files from x days before last on in all dirs\nn -x h        displays all files from x days before last on in hold dir\n\nn mm dd yy    displays new files from mm-dd-yy, prompts for listing\nn mm dd yy u  displays new files from mm-dd-yy in the upload dir\nn mm dd yy a  displays new files from mm-dd-yy in all dirs\nn mm dd yy h  displays new files from mm-dd-yy in hold dir\nn mm dd yy x  displays new files from mm-dd-yy in dir number x\n\nf             displays filehelp.txt and asks for the dir number\nf x           displays dir listing x\nf a           displays all dir listings\nf u           displays the upload listing\nf ?           will show the help\n\nAll commands can be followed with "ns" which will display the listing \nnon-stop ...\n\nHow to install ?\n~~~~~~~~~~~~~~~~\nCreate a dir NewFiles in Doors:\nCopy the files NewFiles and NewFiles.Info in that directory ...\n\nFor /X 2.x users put this in your bbs.commands\n\n-->--------CUT HERE---------------\n*f           !!!!!!!!!!!!!!!!!!\n*n           !!!!!!!!!!!!!!!!!!\n-->--------CUT HERE---------------\n\nFor /X 3.x users the specific Icons will be included and should go in the\nBBS.CMD dir ...\n\nGreetings:\n~~~~~~~~~~\nGreetings go to\n\nGenghis Khan/AFL for testing ... Give his Board a call ...\n\nThanx to all other AFL members for being such a nice group ...\n\nThanx to all Friends from the NewFiles for her Tips and Bugreports\n\nSpecial greetings to Van Damme... don`t delete me in you`re BBS,\nI have some Problemes to Call Canada this moment...,Please Write\nme any Boards where you calling...so I can Contacted you again...\n\nTHX to Spy/AFL witch have Try To install the CRTL-C Option many Hours !\nI hope next Time, Bytemaster`s Cooperation is better\nand he give us more Informations About his Kewl Amiexpress\n\nTHX to Celator/AFL witch have tell me more about the Internal Funktion`s\nfrom /X\n\n           //\nThanx to \X/ Amiga For Being The Best Computer Ever ...\n\nNext works:\n~~~~~~~~~~~\nNewfilesV1.5  ----> I will make it so fast as I can\n                    I will install a new Option to search Newfiles\n                    in All Confs\n                    Try to Write Better Dox !\n\nNuker        -----> New Nuker for /X 3.++ with All what you want, \n                    please write me you`re Ideas about this Tool\n\nEnglish      -----> I will learn it\n\n************************************************************************************\n           IF YOU FOUND ANY BUG`S, PLEASE CONTACT ME SO FAST AS YOU CAN\n************************************************************************************\n                           .     .    .   .  .     .\n                        ·  :                 .     :     :\n-============-   \____ ¬V ¬V___ ¬V___ ¬V___ ¬V ¬|  |___ ¬|   MANAGEMENT\n ALPHA FLiGHT     | ¬|  |  | ¬|  | ¬|  | ¬|  |  |  | ¬|  |   -========-\n      HQ          |  |  |  |  |  |  |  |  |  |  |  |  |  |   ANDi/AFL\n-============-    |  |  |  |     |    _|  |  |  |__|  |  |   SPY/AFL\n                  |  |  |  |  |  |  | ¬|  |  |  | ¬|  |  |   FELDMAN\n-ELiTE oNLY-      |  |  |  |  |  |  |  |  |  |  |  |  |  |\n                  |  |  |  |  |  |  |  |  |  |  |  |  |  |   SYSTEM\nCALL US NoW FoR   |  |  |  |  |  |  |  |  |  |  |  |  |  |   -====-\nTHE NEWEST AMiGA/ |  |  |  |  |  |  |  |  |  |  |  |  |  |   RUNS oN A3000\nPCSTUFF           |  |  |  |  |  |  |  |  |  |  |  |  |  |   WiTH 25MHZ AND\nAND ALL AFL-      |  |  |  |  |  |  |  |  |  |  |  |  |  |   AMiEX (REG.)\nRELEASES.         |  |  |  |  |  |  |  |  |  |  |  |  |  |\n                __|_____A__A__A__A_____A_____A_____A_____|D! SUPPoRTET BY\nWE oNLY ACCEPT    |     :  :     :     :     :     :     |   -==========-\n9600 - 16.800     :     ·  .     .           .     ·     :   ALPHA FLiGHT\nBAUD CoNNECTS.    .        .                                      &&\n                   NoDe 1 +49 30 621 2312 - Zyxel 16.800      \n                   NoDe 2 +49 30 621 8787 - DUAL  14.400\n                   NoDe 0 +49 30 622 1994 - HST   14.400\n','\n',char(10)),NULL,'auto-added',37752,2,0,NULL,NULL,'aflnew4','scan',1780048391);
