INSERT INTO door_catalog VALUES('aflwho10','AFLWHO10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AFLWHO10.LHA','AFL_Who10','XIM','AFLWHO10 AFL_Who10',NULL,'FuZzY/AFL',NULL,'WHo_ELSE V1.0 © 1993 by FuZzY/AFL 33.6 DigITal-X Prd/NirVana Dist Site! 33.6',replace('PRESENTS TODAY ANOTHER AFL RELEASE:\n WHo_ELSE V1.0 © 1993 by FuZzY/AFL\n33.6 DigITal-X Prd/NirVana Dist Site! 33.6\n','\n',char(10)),'AFL_Who10.doc',replace('\n                ____________.  ________________ ___    _______\n               /°  __ ¬\°  ¬| _\_________  ¬\ø Y° ¬\  /°  __ ¬\\n              /ø  _|/   \   |/ ¬\| ø  _|/   /!_|    \/ø  _|/   \\n             / !  \_     \  /    \ !  \____/ :\_     \!  \_     \\n             \ :   |     /       / :   | \     |     /:   |     /\n              \____|   ø/__    ø/|   ø_|  \____|   ø/\____|   ø/\n               ====|___/===\___/=|___/=========|___/======|___/\n      _________________.     _____   _______     ___ ___________________\n      \_______    °/  °| __ (_____) /ø     ¬\   /ø  Y° ¬\°        `93 °/\n        |ø   ¬\___/ø   |/ ¬\|ø   ¬|/ !  \___/  / ! _|    \   .ø   .   /\n        |!    __/| !   /    \!    |  :  /   ¬\/  : \_     \_/|!   |\_/\n        |:    |  | :        /:    |    /      \     |     /  |:   |\n        |   ø_|  |____    ø/|   ø_|\______   ø/\____|   ø/   |_  ø|\n        |___/=========\___/=|___/=[-sLa-]=\__/======|___/======\__|\n\n                    ^ø^   tHiS fLiGhT WiLL nEvEr sTøP  ^ø^\n                          ¯¬°¤ø¤°¬¯¯¬°¤ø¤°¬¯¯¬°¤ø¤°¬¯\n\n               PRESENTS TODAY ANOTHER AFL RELEASE: WHo_ELSE V1.0\n                            © 1993 by FuZzY/AFL\n\n\n\nWHAT DOES IT DO ?\n~~~~~~~~~~~~~~~~~\nWho_Else will tell all Users the activity on the other Nodes. Also\nit will show you the Action of the other and general Infos about\nall other active Nodes.\n\nINSTALL THIS TOOL\n~~~~~~~~~~~~~~~~~\nIn the pack following Files must be included:\n\n       AFL_WHO10         -    THE TOOL\n       WHO.INFO          -    THE COMMAND.INFO FILE FOR /X\n       AFL_WHO10.DOC     -    THIS DOC FILE\n\nFirst you must copy the File Frontend.info in the dir:\n  BBS:COMMANDS/BBSCMD/\n\nThen copy the File AFL_WHO10 in your doors: dir.\nThats all....have fun with this Tool and like it or not. :)\n\nFuZzY oF ALPHA FLiGHT`93\n\n\nHISTORY\n~~~~~~~\nV1.0  Released: 07-02-93\n      First Version of this Utility.\n\n\n\nGREETINGS FLYING TO:\n~~~~~~~~~~~~~~~~~~~~\nWHiTE ANGEL   : I love you ! :)\nSpy/AFL       : Cool programming and thanx for help.\nAndi/AFL      : Yo man ! Weiter so...:) And thanx for your help.\nVAN DAMME/LSD : Very good Tools. But why you don`t programm in C ??\nSABINE/AFL    : Thanx for your loyality. I`ll do my best. :)\n\nALL OTHER AFL MEMBERS and ALL I`VE FORGOTTEN HERE.\n\n\nTO CONTACT ME CALL NOW:\n\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                    -ALPHA FLiGHT GERMAN HEADUATER-\n_____________   _____   ____________________  ____________.    _______\n\_________  ¬\ (_____) /°  __ ¬\_________  ¬\/°   _ ¬\ø  °| __/°   _ ¬\\n   |ø ° | \   \|ø   ¬|/ø  _|/   \|ø  °_|/   /ø  _/ \  \   |/ ¬\ø _/ \  \\n   |!   | / °  \!    | !  \_     \!   \__  °\!  \  /  °\  /°   \ \  /  °\\n   |:   |/     /:    | :   |     /:    |/    \   \/    /       /  \/    /\n   |_____    ø/|   ø_|\____|   ø/|______    ø/___    ø/__    ø/___    ø/\n   ======\___/=|___/== ====|___/=[-sLa-]\___/====\___/===\___/====\___/\n                                                            BBs BERLiN\n\n      SYSoPS: ANDi/AFL & FuZzY/AFL      CoSYSoPS: FELDMAN\n\n   NoDE0 +49 30 6221994    NoDE1 +49 30 6212312    NoDE2 +49 30 6218787\n\n                  -THE HoME oF THE CooL AFL-/X-TooLS-\n\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~','\n',char(10)),NULL,'XIM-BBSCmd',14458,9,0,NULL,NULL,'aflwho10_afl_who10','scan',1780048391);
INSERT INTO door_catalog VALUES('afl_bull','AFL_BULL.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AFL_BULL.LHA','AFL_BULL','XIM','AFL_BULL',NULL,'FuZzY/AFL','AFL','Bulletin''s © 1993 by FuZzY/AFL 33.6 DigITal-X Prd/NirVana Dist Site! 33.6',replace('PRESENTS TODAY ANOTHER AFL RELEASE:\n  Bulletin''s © 1993 by FuZzY/AFL\n33.6 DigITal-X Prd/NirVana Dist Site! 33.6\n','\n',char(10)),'bulletin.doc',replace('\n\n         This Utils come`s from the Diabolo and Fate Gate BBS\n         ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^\n\nHow to start AFL_BULL:\n======================\n\nStart The AFL_BULL Util in your logoff-script and it will make \na Bulls for You`re BBS.\n\nEXAMPLE:\n\n			bbs:utils/AFL_BULL bbs: bbs:conf-1/Bulletins/\n\n						^       ^               ^\n					  The Tool  |				|\n                                |				|\n                       Path to the User.data    |\n                                                |\n                                      Path for the 6 Bulls\n\n***********************************************************************\n\nHow to start Bullview:\n======================\n\nBullview is an X-door.First you must make an Assign to the \nBulletins Area.\n\nThan insert in you`re bbs.cmd the Command :\n\n             *B        XM050DOORS:bullview\n\n***********************************************************************\n\nthis Bulls are our first Tools.\nIn any Time we will bring you many more Bulls as One TOOL.\n\n     If you have Probs with our Tool connected us in any boards.\n     ***********************************************************\n\n\n\n________________________________________________________________________\n/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\\n""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""\n        ___         >> HeadQuarter of AFL <<       ________\n       /   \                                      /        \\n //// /     \    ___  ______  ______  ______  _   \    \    \ \\\\\n//// /    \  \  /   \/      \/      \/      \/ \   \    \    \ \\\\\n/// /      \  \/    /   /   /\  \___/\   \   \  \  /\    \    \ \\\\n// /       /  /    /       / /  /   \ \   \   \  \/  \         \ \\\n/ /          /    /   /   / /  /     \ \       \      \         \ \\n  \_________/\___/\__/___/  \________/  \______/\_____/\________/\n\n                       >> CALL +49 03 621 23 12 <<\n                       >>  OR  +49 03 621 87 87 <<\n                       >>  OR  +49 03 622 19 94 <<\n\n >> RUNNING ON AMIGA 3000 25Mhz, 220MB AMIGA AND PC STUFF ONLINE <<\n________________________________________________________________________\n/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\\n""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""\n','\n',char(10)),NULL,'auto-added',20861,9,0,NULL,NULL,'afl_bull','scan',1780048391);
INSERT INTO door_catalog VALUES('afl_buzz','AFL_BUZZ.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AFL_BUZZ.LHA','buzz','XIM','____________________________',NULL,'Celator/AFL','AFL','+----\________   \__   ______/  /----------+ |Alpha /     /    /   _____/   /_____Flight| +-----/    _     /      \/    /     /------+',replace('     ____________________________           \n+----\________   \__   ______/  /----------+\n|Alpha /     /    /   _____/   /_____Flight|\n+-----/    _     /      \/    /     /------+\n|     \____/__  /\____  /\_______  /       |\n+-------------\/------\/         \/--------+\n+-  tIMe bUZz v0.1 - (w) by Celator/AFL   -+\n','\n',char(10)),'TIMEBUZZ.GUIDE',replace('@database TIMEBUZZ\n\nCopyright (c) 1995 by STEEL/AFL\n\n@Remark $VER: (Februar 05 1995)\n@Remark AmigaGuide DataBase "StEeL/aFl" DoCuMeNTaTioN\n\n@node MAIN "TIMEBUZZ (c) 1995 BY cEL`95"\n\n               _______   ___        ________   ___  ___   _______\n              /       \ /   \      /        \ /   \/   \ /       \\n             /    /   //    /     /    /·   //    /    //    /   /\n            /        //    /____ /    _____//         //        /\n           /    /   //    /~   //    /     /    /    //    /   /\n           \___/   //_________//____/®StEeL\___/\___/ \___/   /\n              /   /                                      /   /\n              \__/                                       \__/\n                             @{" TIMEBUZZ GERMAN! " LINK BUZZG}\n\n                             @{" TIMEBUZZ ENGLISH " LINK BUZZE}\n\n                           @{" iNSTALLATION GERMAN! " LINK InstG}\n                           @{" iNSTALLATION ENGLISH " LINK InstE}\n\n                                  @{" CREDITZ " LINK CREDITZ}\n\n                                 @{" gREETINGS " LINK Greets}\n         __________ ___        ______ ______    ___  ___   __________\n        /         //   \      /___  //      \  /   \/   \ /         /\n       /__     __//    /     ____ \//  \____/ /    /    //__     __/\n         /    _/ /    /____ /    \ /   /   \ /         /   /    /\n        /    /  /    /~   //     //   /    //    /    /   /    /\n        \___/   \________/ \____/ \_______/ \___/\___/    \___/\n\n      aLPHA fLIGHT pRESENTS a pOWERFULL xIM dOOR (w) bY cELATOR /\FL\n\n@endnode\n\n@node BUZZG "TIMEBUZZ GERMAN..."\n\n\n\n\n\n\n\n         DIESES TOOL IST FÜR ALLE SYSOP`S, DIE PROBLEME MIT IHRER\n                         ONLINE-TIME-BASE HABEN !\n       Z.B., WENN EIN USER 30 MINUTEN ONLINE ZEIT HAT, 15 MINUTEN IM\n                                 BOARD BLEIBT,\n    MÜSSTE ER EIGENTLICH FÜR DEN REST DES TAGES 15 MINUTEN ALS RESTZEIT\n                                  HABEN !\n          DURCH EINEN INTERNEN BUG IST DAS ABER NICHT DER FALL !\n         HIER HILFT NUN SCHNELL UND UNKOMPLIZIERT TIMEBUZZ V0.1 !\n\n\n\n@ENDNODE\n\n@NODE INSTG "INSTALLATION GERMAN..."\n\n\n\n\n\n\n                       AUCH DER EINBAU IST SEHR LEICHT:\n            EINFACH ALLE VORHANDENEN FILES UND DIR`S IN DIE BEREITS\n                   VORGEGEBENDEN DRAWERS KOPIEREN,  FERTIG !\n           JETZT NOCH DEN MCI-STRING (~CC_BUZZ) IN EINEN BESTEHENDEN\n             BBS-TEXT ( Z.B. BULL.TXT ) EINFÜGEN, DER VON "JEDEM"\n                          USER GESEHEN WERDEN MUSS !\n\n\n\n\n\n\n@ENDNODE\n\n@NODE BUZZE "TIMEBUZZ ENGLISH..."\n\n\n\n\n\n\n       THIS TOOL IS FOR ALL SYSOP`S THERE HAVE PROBLEM`S WITH THERE\n                            ONLINE-TIME-BASE !\n   Z.B.,WHEN A USER HAS 30 MINUTES ONLINE TIME, AND WORK`S 15 MINUTES IN\n           YOUR SYSTEM, MUST HE NORMALIE 15 MINUTES REST TIME IN\n                               YOUR SYSTEM !\n  PEAR AN INTERN-BUCK IN THE /X-SYSTEM SELF, IS THAT`S NOTHING THE ART !\n               HERE HELP`S FAST AND BEST OF THE TIMEBUZZ !!!\n\n\n@endnode\n\n@NODE INSTE "INSTALLATION ENGLISH..."\n\n\n\n\n\n               THE WORK, TO START THIS TOOL IS VERY SIMPLY !\n  ALL FILES FROM THIS DIR, COPY TO THE PATHES ON YOUR HARD-DISK (BBS-DIR)\n                NOW, A "MCI-STRING" IN A BULLTEXT, THAT ALL\n                           USER`S "MUST" SEE !?!\n\n\n\n\n\n\n\n@ENDNODE\n\n@NODE CREDITZ "ABOUT THE FLEXIBLE BRAINSTORM TEAM ..."\n\n\n\n        IDEA & LOGICAL ACCESS               LECTOR/BROADWAY BBS\n\n\n        ANSI LAYOUT, GUIDE AND DOCS         STEEL/AFL\n\n\n        WRITTEN FOR /X 4.xx                 CELATOR/AFL\n\n\n\n@ENDNODE\n\n@NODE GREETS "FLYING HANDSHAKES FLY`S TO..."\n\n\n\n        PERSONAL GREETINGS JUMP TO\n\n\n    SABINE & KEVIN                  ECHT SUESSES MINI-CHAOS\n\n    SVEN THE CREATOR                COOL ''E''-SESSIONS & PROJECTS\n\n    SIGMA 7                         LET START S!X TO NEW DIMENSIONS\n\n    ULTRA & CHANEL                  HARDEST SHOOT''EM''UP FIGHTS\n\n    PATRICK                         BETA-TESTING IS SOMETIMES A HARD JOB\n \n    PARCEVAL                        WORK AGAINST GRAVENREUTH (IN FUTURE)\n\n    BITA                            NICE NIGHTS....\n\n    \n\n         AND TO ALL MEMBERS OF ALPHA FLIGHT AND FRIENDSHIP GROUPS ...\n\n@ENDNODE\n','\n',char(10)),NULL,NULL,5738,1,0,NULL,NULL,'afl_buzz','scan',1780048391);
INSERT INTO door_catalog VALUES('afl_com1','AFL_COM1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AFL_COM1.LHA','comment1','XIM','comment1',NULL,NULL,'AFL','33.6 DigITal-X Prd/NirVana Dist Site! 33.6',replace('ALPHA FLIGHT PRESENTS Comment To Sysop`sV 1.1\n33.6 DigITal-X Prd/NirVana Dist Site! 33.6\n','\n',char(10)),'comment.doc',replace('\n                   ALPHA FLIGHT PRESENTS\n\n                  Comment To Sysop`sV 1.1\n                  ~~~~~~~~~~~~~~~~~~~~~~~\nThis tool iss an /X Door, please insert in you`re bbs.cmd:\n\n*C        XM010DOORS:comment\n\nand put in you`re s: dir a File names: comment.cfg.\nWe have sent You an Example how to use this File.\nThe first Line must have the Full Path to the User.data.\nThe next Line must have The right Sysop or Cosysop Name (max 24).\nthan you must insert the Commentfor the Sysop or Cosysop (max 34).\nand now you can do it for 9 (Co)SySoP`s.\n\nWe hope you like our Tool and send us any messi if the tool have \nany Probs.\nIn our tools are no Backdoor`s !!!!\nWe hate Backdoors !\n\nThis tool where written in :\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n________________________________________________________________________\n/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\\n""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""\n         ___         >> HeadQuarter of AFL <<       ________\n        /   \                                      /        \\n  //// /     \    ___  ______  ______  ______  _   \    \    \ \\\\\n //// /    \  \  /   \/      \/      \/      \/ \   \    \    \ \\\\\n /// /      \  \/    /   /   /\  \___/\   \   \  \  /\    \    \ \\\\n // /       /  /    /       / /  /   \ \   \   \  \/  \         \ \\\n/ /          /    /   /   / /  /     \ \       \      \         \ \\n  \_________/\___/\__/___/  \________/  \______/\_____/\________/\n\n                    >> CALL +49 03 621 23 12 <<  SySoP`s ArE\n                    >>  OR  +49 03 621 87 87 <<      Byteandi &\n                    >>  OR  +49 03 622 19 94 <<          FuZzY\n                      \n >> RUNNING ON AMIGA 3000 25Mhz, 220MB AMIGA AND PC STUFF ONLINE <<\n ________________________________________________________________________\n/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\\n""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""\n','\n',char(10)),NULL,'auto-added',17395,10,0,NULL,NULL,'afl_com1','scan',1780048391);
INSERT INTO door_catalog VALUES('afl_file','AFL_FILE.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AFL_FILE.LHA','filepacker','XIM','ALPHA FLIGHT PRESENTS : FileListDl','1.0',NULL,'AFL','33.6 DigITal-X Prd/NirVana Dist Site! 33.6',replace('ALPHA FLIGHT PRESENTS : FileListDl V1.0\n33.6 DigITal-X Prd/NirVana Dist Site! 33.6\n','\n',char(10)),'FileListDL.doc',replace('                          FileListDl V1.0\n\nThis Tool was written C, it help the User to Download all\nFilestings from the Conferences where he have ACCESS.\n\nPlease creat a File names Filepacker.cfg in your s directory and \ninsert you`re ConfNumbers what you want to have.\n \nEXAMLPE: from S:filepacker.cfg\n~~~~~~~~\n2               <-------- ConfNumber\nBBS:Conf-2/dir2 <-------- The Path for the FileList (max 49 chars)\nNEW AMIGA WAREZ <-------- The name what ever you want (max 29 chars)\n2\nBBS:Conf-2/dir1\nDeLeTeD FiLeS\n3\nBBS:Conf-3/dir2\nAMIEX FiLeS\n\nYou can creat 9 Pathes and Names.\n\n*********************************************************************\nThe Tool will Look if The User have Access for the Conf`s and when \nhe have something, than he can Download it as TXT-File or LHA-File.\nThe User can Download All in that List or from Date what ever he want.\n\nPlease insert in zhe BBS.cmd :\n\n*FL       XS050Doors:afl_lister/FileListDL\n\n*********************************************************************\n\nIf you Like our AFL Tools Call our Boards for more.\n	\n____________________________________________________________________\n/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\\n""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""\n        ___         >> HeadQuarter of AFL <<       ________\n       /   \                                      /        \\n //// /     \    ___  ______  ______  ______  _   \    \    \ \\\\\n//// /    \  \  /   \/      \/      \/      \/ \   \    \    \ \\\\\n/// /      \  \/    /   /   /\  \___/\   \   \  \  /\    \    \ \\\\n// /       /  /    /       / /  /   \ \   \   \  \/  \         \ \\\n/ /          /    /   /   / /  /     \ \       \      \         \ \\n  \_________/\___/\__/___/  \________/  \______/\_____/\________/\n\n                  >> CALL +49 03 621 23 12 <<  Zyxel\n                  >>  OR  +49 03 621 87 87 <<  DuAl\n                  >>  OR  +49 03 622 19 94 <<  DuAl\n\n >> RUNNING ON AMIGA 3000 25Mhz, 220MB AMIGA AND PC STUFF ONLINE <<\n____________________________________________________________________\n/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\/\\n""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""""\n','\n',char(10)),NULL,NULL,16851,8,0,NULL,NULL,'afl_file_filepacker','scan',1780048391);
INSERT INTO door_catalog VALUES('afl_new','AFL_NEW.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AFL_NEW.LHA','NewFiles','XIM','NewFiles',NULL,'ByteAndi/AFL','AFL','NewFile v1.0 (/X filelisting enhancement tool) © 1993 by ByteAndi/AFL',replace('     Yet another AFL release:\n           NewFile v1.0\n(/X filelisting enhancement tool)\n      © 1993 by ByteAndi/AFL\n33.6 DigITal-X Prd/NirVana Dist Site! 33.6\n','\n',char(10)),'NewFiles.doc',replace('****************************************************************************\n*                                                                          *\n*                         Yet another AFL release:                         *\n*                               NewFile v1.0                               *\n*                    (/X filelisting enhancement tool)                     *\n*                          © 1993 by ByteAndi/AFL                          *\n*                                                                          *\n****************************************************************************\n\nWhat does it do ?\n~~~~~~~~~~~~~~~~~\nNewFile will display the filelisting in some nicer way then the ordinary\nfilelisting you are used to ... It also has some more features then you\nhave with the original f-, n- and n s u commands ...\n\nHow to install ?\n~~~~~~~~~~~~~~~~\nCreate a dir NewFiles in Doors:\nCopy the files NewFiles and NewFiles.CFG in that directory ...\n\nFor /X 2.x users put this in your bbs.commands\n\n-->--------CUT HERE---------------\n*f        XM010DOORS:newfiles/newfiles\n*n        XM010DOORS:newfiles/newfiles\n-->--------CUT HERE---------------\n\nFor /X 3.x users the specific Icons will be included and should go in the\nBBS.CMD dir ...\n\nnewfiles/newfiles.cfg should contain the following lines _ON is enabled and\n_OFF is disabled ofcoz\n\nANSI_ON     ------------> gives Ansi in the filelisting\nNS_ON       ------------> means you can use NS after each command line\nDATE_ON     ------------> puts dateheader when date changes \nLINES_ON    ------------> displays bars between different uploads\nRETURN_ON   ------------> puts returns between different uploads\nSENTBY_ON   ------------> puts the "sent by: Username" in Ansi Color\n\nWatching the hold dir is only possible for users with an accesslevel higher\nthen 245 ...\n\nThis util also works when you have DirStyle build in ...\n\nHow to use it\n~~~~~~~~~~~~~\nHere are the commands you can use:\n\nn             first you will be prompted for the date and than the listing ...\n\nn ?           will show the help ...\n\nn t           displays all new files from today in the upload dir\nn t u         displays all new files from today in the upload dir\nn t a         displays all new files from today in all dirs\nn t h         displays all new files from today in the hold dir\n\nn s a         displays all new files since last on in all dirs\nn s u         displays all new files since last on in upload dir\nn s h         displays all new files since last on in hold dir\n\nn -x          displays all files from x days before last on in upload dir\nn -x u        displays all files from x days before last on in upload dir\nn -x a        displays all files from x days before last on in all dirs\nn -x h        displays all files from x days before last on in hold dir\n\nn mm-dd-yy    displays new files from mm-dd-yy, prompts for listing\nn mm-dd-yy u  displays new files from mm-dd-yy in the upload dir\nn mm-dd-yy a  displays new files from mm-dd-yy in all dirs\nn mm-dd-yy h  displays new files from mm-dd-yy in hold dir\nn mm-dd-yy x  displays new files from mm-dd-yy in dir number x\n\nf             displays filehelp.txt and asks for the dir number\nf x           displays dir listing x\nf a           displays all dir listings\nf u           displays the upload listing\nf ?           will show the help\n\nAll commands can be followed with "ns" which will display the listing \nnon-stop ...\n\nGreetings:\n~~~~~~~~~~\nGreetings go to\nRe/Y\o/AFL for helping out with some problems ...\nGenghis Khan/AFL for testing ... Give his Board a call ...\nJeannie/AFL for diners inbetween programming this tool ...\nSabine/AFL for putting up with all those AFL members ...\nSpy/AFL for some interesting hints and tips ...\nThanx to all other AFL members for being such a nice group ...\nSpecial greetings to Van Damme... Don''t forget to call\nyour brothers in Belgium and in Berlin ... :^)\n\n           //\nThanx to \X/ Amiga For Being The Best Computer Ever ...\n\n                           ·           .     ·     .\n                        ·  :                 .     :     :\n                 _______:__:_____:_____:_____:___ _|_____|__\n-============-   \____ ¬V ¬V___ ¬V___ ¬V___ ¬V ¬|  |___ ¬|   MANAGEMENT\n ALPHA FLiGHT     | ¬|  |  | ¬|  | ¬|  | ¬|  |  |  | ¬|  |   -========-\n      HQ          |  |  |  |  |  |  |  |  |  |  |  |  |  |   ANDi/AFL\n-============-    |  |  |  |     |    _|  |  |  |__|  |  |   FuZzY/AFL\n                  |  |  |  |  |  |  | ¬|  |  |  | ¬|  |  |   BRAiN\n-ELiTE oNLY-      |  |  |  |  |  |  |  |  |  |  |  |  |  |\n                  |  |  |  |  |  |  |  |  |  |  |  |  |  |   SYSTEM\nCALL US NoW FoR   |  |  |  |  |  |  |  |  |  |  |  |  |  |   -====-\nTHE NEWEST AMiGA/ |  |  |  |  |  |  |  |  |  |  |  |  |  |   RUNS oN A3000\nPC/CoNSoLE STUFF  |  |  |  |  |  |  |  |  |  |  |  |  |  |   WiTH 25MHZ AND\nAND ALL AFL-      |  |  |  |  |  |  |  |  |  |  |  |  |  |   AMiEX (REG.)\nRELEASES.         |  |  |  |  |  |  |  |  |  |  |  |  |  |\n                __|_____A__A__A__A_____A_____A_____A_____|D! SUPPoRTET BY\nWE oNLY ACCEPT    |     :  :     :     :     :     :     |   -==========-\n9600 - 16.800     :     ·  .     .           .     ·     :   ALPHA FLiGHT\nBAUD CoNNECTS.    .        .                                      &&\n                   NoDe 1 +49 30 621 2312 - Zyxel 16.800      þþþRANXþþþ\n                   NoDe 2 +49 30 621 8787 - DUAL  14.400\n                   NoDe 0 +49 30 622 1994 - HST   14.400\n\n','\n',char(10)),NULL,'auto-added',18491,6,0,NULL,NULL,'afl_new','scan',1780048391);
INSERT INTO door_catalog VALUES('afl_new1','AFL_NEW1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AFL_NEW1.LHA',NULL,'XIM','newfiles.000',NULL,'ByteAndi/AFL','AFL','NewFile v1.1 (/X filelisting enhancement tool) © 1993 by ByteAndi/AFL',replace('     Yet another AFL release:\n           NewFile v1.1\n(/X filelisting enhancement tool)\n      © 1993 by ByteAndi/AFL\n33.6 DigITal-X Prd/NirVana Dist Site! 33.6\n','\n',char(10)),'NewFiles.doc',replace('****************************************************************************\n*                                                                          *\n*                         Yet another AFL release:                         *\n*                               NewFile v1.1                               *\n*                    (/X filelisting enhancement tool)                     *\n*                          © 1993 by ByteAndi/AFL                          *\n*                                                                          *\n****************************************************************************\n\nWhat does it do ?\n~~~~~~~~~~~~~~~~~\nNewFile will display the filelisting in some nicer way then the ordinary\nfilelisting you are used to ... It also has some more features then you\nhave with the original f-, n- and n s u commands ...\n\nWhat is New ?\n~~~~~~~~~~~~~\n\nnewfiles.cfg :\n\nSELF_ON \n\nput it in the newfiles.cfg and the User can make the styling from the List \nhow ever he Want.\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\noptions :\n\nn w\n\nif SELF_ON, then the User can insert that and can make a new config \nfor her Account\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nif the User shows the filelist:\n\nif NS_ON, the User can insert every Time "N" to see the Filelisting NONSTOP\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nI have turn off the Cursor if the User search for the Filelist, to have a better\noutfit. If The Newfiles want any Inputs, the Cursor is always ON.\n\nNow the Filelist works better with other tools witch change the outfit from the \nfilelist. (Dirstyler and other).\n\n```````````````````````````````````````````````````````````````````````````````\nTHANX TO ANDY/MTN FROM THE BBS ~~ FASTWAY ~~ FOR HIS FASTES INFORM ABOUT \nTHE PROBLEM WITH DIRSTYLER AND HIS IDEAS ABOUT THIS TOOL\n''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''''\n\nI think it is now Faster as the old Newfiles.\n\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nHow to install ?\n~~~~~~~~~~~~~~~~\nCreate a dir NewFiles in Doors:\nCopy the files NewFiles and NewFiles.CFG in that directory ...\n\nFor /X 2.x users put this in your bbs.commands\n\n-->--------CUT HERE---------------\n*f           !!!!!!!!!!!!!!!!!!\n*n           !!!!!!!!!!!!!!!!!!\n-->--------CUT HERE---------------\n\nFor /X 3.x users the specific Icons will be included and should go in the\nBBS.CMD dir ...\n\nnewfiles/newfiles.cfg should contain the following lines _ON is enabled and\n_OFF is disabled ofcoz\n\nANSI_ON     ------------> gives Ansi in the filelisting\nNS_ON       ------------> means you can use NS after each command line\nDATE_ON     ------------> puts dateheader when date changes \nLINES_ON    ------------> displays bars between different uploads\nRETURN_ON   ------------> puts returns between different uploads\nSENTBY_ON   ------------> puts the "sent by: Username" in Ansi Color\nSELF_ON     ------------> the User can configure the Filelist styling himself\n^^^^^^^ ------> IMPORTANT--IMPORTANT--IMPORTANT--IMPORTANT--IMPORTANT--IMPORTANT--\n\n\nWatching the hold dir is only possible for users with an accesslevel higher\nthen 245 ...\n\nThis util also works when you have DirStyle build in ...\n\nHow to use it\n~~~~~~~~~~~~~\nHere are the commands you can use:\n\nn w           The User can make a config for his Account\n^^^------> IMPORTANT--IMPORTANT--IMPORTANT--IMPORTANT--IMPORTANT--IMPORTANT--   \n\nn             first you will be prompted for the date and than the listing ...\n\nn ?           will show the help ...\n\nn t           displays all new files from today in the upload dir\nn t u         displays all new files from today in the upload dir\nn t a         displays all new files from today in all dirs\nn t h         displays all new files from today in the hold dir\n\nn s a         displays all new files since last on in all dirs\nn s u         displays all new files since last on in upload dir\nn s h         displays all new files since last on in hold dir\n\nn -x          displays all files from x days before last on in upload dir\nn -x u        displays all files from x days before last on in upload dir\nn -x a        displays all files from x days before last on in all dirs\nn -x h        displays all files from x days before last on in hold dir\n\nn mm-dd-yy    displays new files from mm-dd-yy, prompts for listing\nn mm-dd-yy u  displays new files from mm-dd-yy in the upload dir\nn mm-dd-yy a  displays new files from mm-dd-yy in all dirs\nn mm-dd-yy h  displays new files from mm-dd-yy in hold dir\nn mm-dd-yy x  displays new files from mm-dd-yy in dir number x\n\nf             displays filehelp.txt and asks for the dir number\nf x           displays dir listing x\nf a           displays all dir listings\nf u           displays the upload listing\nf ?           will show the help\n\nAll commands can be followed with "ns" which will display the listing \nnon-stop ...\n\nGreetings:\n~~~~~~~~~~\nGreetings go to\nRe/Y\o/AFL for helping out with some problems ...\nGenghis Khan/AFL for testing ... Give his Board a call ...\nJeannie/AFL for diners inbetween programming this tool ...\nSabine/AFL for putting up with all those AFL members ...\nSpy/AFL for some interesting hints and tips ...\nThanx to all other AFL members for being such a nice group ...\nSpecial greetings to Van Damme... Don''t forget to call\nyour brothers in Belgium and in Berlin ... :^)\n\n           //\nThanx to \X/ Amiga For Being The Best Computer Ever ...\n\n','\n',char(10)),NULL,'auto-added',31502,5,0,NULL,NULL,'afl_new1','scan',1780048391);
INSERT INTO door_catalog VALUES('afl_pack','AFL_PACK.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AFL_PACK.LHA','Comment2','XIM','Comment2',NULL,'SøNÝ/AFL^THR','AFL','\____   \_ ____/  /___ \_    \_  / //___  \ /      ./  __/// /   /&/  /__/    ·/  _  _/ /___/  //___/ /______/ /__/  // /__/___/  /',replace(' ___________________    ___________________\n \____   \_ ____/  /___ \_    \_  / //___  \\n /      ./  __/// /   /&/  /__/    ·/  _  _/\n/___/  //___/ /______/ /__/  // /__/___/  /\n===/___/=·[Presents]·=Dt/aFL/__/==''94=/__/==\n/X Døø® Pack By SøNÝ/AFL^THR & FANTA/AFL^THR\n          17 XiM-doors in 1 pack\n','\n',char(10)),'Comment2.doc',replace('\n                                Comment v1.0\n                              by SøNÝ & fanta\n\n                » Another aLPHa fLIGHt/The®¡øN Production «\n\n\n                                    Why?\n\nAn usual commentdoor with configuration in the info.\nOf course we made it in C to accomplish some speed.\n\n\n                                 Disclaimer\n\nWe don''t take any responsibility for any damage this door make on your\ncomputer hardware or software. It has been fully tested so it shouldn''t\ngive ya any problems.\n\n\n                                Installation\n\n-Copy the file BBS/Doors/comment2/comment2 to Doors:comment2/ (or wherever\n you keep your doors) if you have a 030 ør 040 use 030/040 and just\n rename it to comment and copy.\n\n                                  /X 2.xx\n\n-Modify your custom-commands and add the following line:\n\n*c        XM010Doors:comment2/comment2\n\n^         ^    ^\n|         |    |_ Or wherever you put the comment2 door.\n|         |\n|         |___ Notice the "X" comment2 is an XIM door!\n|\n|______ The name to run.\n\n                                  /X 3.xx\n\n-Copy the icon BBS/Commands/BBsCmd/c.info to BBS/Commands/BBsCmd/\n and put the new path in the info.\n\n\n                                 Configuration\n\nThe following things can you configure in the comment2.info.\n\nUSER1=<sysopname>\nCOMMENT1=<string>\nUSER1SAYS=<string>\n\nUSERn=<name>\nCOMMENTn=<string>\nUSERnSAYS=<string>\n\n(n=number between 2 and 10)\n\nYou must name the command c because you can use this door like this:\n\nJoyRide [2:(-`*''-) Elite (-`*''-)] Menu (16486 mins. left): c 2\n\nCømment 1.0\n\n\nSoNy Says: W0w again a letter 4 me\n\n                       (------------------------------)\n     To: (Enter)=''ALL''? SoNy\nSubject: (Blank)=abort? ?\n\n\nand so on....\n\n\n\n\n\n                            Main Files included\n\n               Filename                             Org. Size\n\n       BBS/Doors/Comment2/Comment2                   13620\n\n       BBS/Doors/Comment2/Comment2.030               13620\n\n       BBS/Doors/Comment2/Comment2.040               13620\n\n\n\n\n\n\n\n\n\n To provent any backdoors d¡al...    ..to get the orginal & latest version.\n\n\n\n  __________  ___________ ____________\n  \_____  _/  \__  _  __/ \__  |    _/\n   ___|    \  /    |    \  /   ¦     \  +¢6(°)³²²/¹9°97\n  /   |     \/     |     \/    :      \_________________ _ _  _    _\n /    ¦      \     ¦      \_______     \\n/     :       \    :       \/           \     Sysop¹:fanta\n\             /            /            /\n \___________/____________/    ________/      Sysop²:S0Ny\n        |                 \_____|\n        |        14400         _________  _______ _________ _____________\n        |     DualStandard     \___   _ \ \___   |\______  \\_____  ____/\n        ¦    DualSysopPower      /    |  \/      |  /  |    \  /    ___|\n        :  Kicking with /X 2.3  /     ___/__     | /   |     \/     |\n        ·                      /            \_   |/    ¦      \     l____\n        .    ·¹·Dayz warez    /     \        /   |     :       \         |\n              Therion WHQ     \      \      /    |     ·       /         |\n        . Online Door Ordering \______\    /_____|____________/__________|\n                                       \__/j\n\n\n\n\n\n[EOF]','\n',char(10)),NULL,'auto-added',482528,5,0,NULL,NULL,'comment2','scan',1780048391);
INSERT INTO door_catalog VALUES('afs','AFS.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AFS.LHA','afs','XIM','AutoFreeSpace Version 1.0',NULL,NULL,NULL,'33.6 DigITal-X Prd/NirVana Dist Site! 33.6',replace('AutoFreeSpace Version 1.0\n33.6 DigITal-X Prd/NirVana Dist Site! 33.6\n','\n',char(10)),'afs.readme',replace('ØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØ\nØØØØØØØØØØØØØØØØØØØØØØØØ AutoFreeSpace Version 1.0 ØØØØØØØØØØØØØØØØØØØØØØØØØØ\nØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØØ\n\nAutoFreespace is a Tool made for all user of the AmiExpress-Mailbox-System.\n\nWell, I think every Sysop has got the same Problem: what will happen, if my\nBBS-Device is full and I am not at my terminal!! Horror!! No more Uploads\nuntil I will clean it up....\n\nThis problem means nearly the same, as being OFFLINE!!\n\nSo you got the basic idea of my little AFS-Tool. It was especially made to\nsave you from situations like that!! So your BBS will practically organize\nitself!! If you will call AFS after every LOGOFF (Batch-file), you can be\nsure, that there will be always enough space for the next callers UPLOAD!!!\n\nhere''s how to call it:\n----------------------\n\n AFS MINIMUM_Megabyte DESTINATION_path ACTUAL_DirNr DELETE_DirNr UPLOAD_path\n\nthe meaning of life..aehh...the parameter:\n------------------------------------------\n\nMINIMUM_Megabytes:  Here you tell AFS how much MB you want as minimum\n                    freespace on your BBS-Device (only 1-9 MB, to avoid\n                    possible damage!)!! Of course AFS will check the device\n                    where you store your uploads!\n\nDESTINATION_path:   This is the path, where your AMIEX keeps the\n                    ''DIR''-Files.\n\nACTUAL_DirNr:       The Actual_dirnr is the number of the number of the\n                    ''DIR''-File, where your AMIEX organizes the actual,\n                    existing uploads.\n\nDELETE_DirNr:       The Delete_dirnr is, you may guess, the number of the\n                    ''DIR''-File, where AMIEX remembers the deleted uploads.\n\nUPLOAD_path:        And finally, here''s where AFS will find the uploads your\n                    BBS organizes in the ''Upload-Dir-File''. Can be a\n                    different Device, than the DESTINATION_path.\n\n You got it??? Not yet??? Ok here''s an.....\nEXAMPLE:\n--------\n\n afs 5 BBS:conf-1 2 1 BBS:conf-1/upload\n\nThis is for the following situation: You want your BBS-System, which runs on\nthe device ''BBS:'' (of course you can also write ''DH0:'', etc.), to have\nalways more than 5 Megabyte of free HD-space (value: 0-9). You keep your\nDIR-Files in the directory ''BBS:conf-1'', and you organize you actual, still\nexisting uploads in the file: ''DIR2'', and the old, deleted uploads in the\nfile: ''DIR1''. The uploads will be found at: ''BBS:Conf-1/upload''.\nIf there is more than 5 MB space on your device, afs will do nothin. If\nthere is less than 5 MB it will delete all uploads from the oldest day.\nThen AFS is checking the kapacity again and will re-do it or quit, if there\nis more than 5 MB. You see, there is no possibility, that you keep the\nsecond Disk of a game and delete the first disk, because of Drive-Space.\nThe deleted Uploads will be automatically deleted from the DIR2 file and\nwill be added at the DIR1 file. (AFS will write ''DELETED'' instead of the\nfile-length in the delete-Dir-File).\n\nwell...everything seems to be clear now with that example.\n\nfamous last words:\n------------------\n- both files (deleted and actual) have to exist. At least they can be 0\n  Bytes of length (you can generate it with ''ED''), but they have to exist!\n\n- Of cource you can keep your uploads in a different Device, and afs will\n  check the right kapacity-limit.\n  (eg: ''afs 5 dh0:conf-1 2 1 dh1:uploads'' will check dh1:-kapacity!)\n\n- If AFS cannot delete any file, found in the ACTUAL_DIR-file it will\n  write "deleted", instead of "DELETED" in the DELETE_DIR-file, so you\n  can see, if there is, for any reason, any ghost-upload in your upload-\n  dir!!\n\n- I tried to catch all possible errors with the parameter, but I guess\n  there are still some errors possible. So don''t wonder if it gurus.\n  Just check the parameter. Always put one ''space'' between two parameter\n  and don''t leave one of them.\n\n- If AFS won''t work, it might be possible, that it recognises any errors\n  and wants to report. At our TITANICS-BBS we have no Cli-Window, so\n  AFS cannot report (will cause an error!). If so, then remove it from\n  the LOG-OFF-Batch-File, call it from CLI, get the ERROR-Msg, remove\n  the error and reinstall it in the Batch-file.\n\n- !!!! warning !!!! AFS will access YOUR BBS-Device. So handle with care\n  to avoid damage. (for that reason lock it away from little children!)\n\n- the author does not take any responsibility for anything tragical that\n  might happen! (death of relatives, or loss of money!!)\n\n\n\n By the way!!! I made this Tools for you. You won''t have to pay for it.\n Thats ok! But, you could do me a big favour. I am fanatically searching\n for the EDITOR FOR THE ROLAND D110 (final version). If you could send it\n to our BBS, that would be a very gentle job !!!!!\n\nAFS 1.0 was written in february ''92 by STARBUG/TITANICS (thats me, folks!)\n\nplease give our BBS a call:\n\nTITANICS WHQ: +49 (0)40 7249583\n\n','\n',char(10)),NULL,NULL,16696,6,0,NULL,NULL,NULL,'scan',1780048391);
