INSERT INTO door_catalog VALUES('aka_tsen','AKA_TSEN.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AKA_TSEN.LHA','rexxdoor','XIM','Rename',NULL,NULL,'AKA','_____  __  /\_/ \___ \____ \_ /  /  / _  _/  / _  _/  /  / ---------- /     /  /  /  /  /  /     /  /X sECTION',replace('_ ____________   ______ _ ___    \n  _____  __  /\_/ \___ \____ \_ \n   /  /  / _  _/  / _  _/  /  / ----------\n  /     /  /  /  /  /  /     /  /X sECTION\n /__/  /__/  /__/__/  /__/  /   ----------\n.==/__/==/__/=====/__/==/__/=[dL!]=========.\n      --\-- tERROR sTYLER rEL[1] --/--\n\n(/X4.X) sMALL & lAME oNLINE dIRsTYLER (S!X!)\n`-========================================-''\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 19:58:35  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',26153,1,0,NULL,NULL,'aka_tsen','scan',1780048403);
INSERT INTO door_catalog VALUES('alarm','ALARM.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ALARM.LHA','AmigaGuide','XIM','AmigaGuide','1.0',NULL,NULL,NULL,replace('   SYSOP-ALARMiNATOR V1.0 FOR ALL /X VERS\n','\n',char(10)),'ALARM10.GUiDE',replace('@DATABASE "ALARM10.ENGLiSH.GUiDE"\n@REMARK .------------------------------------------------------------------.\n@REMARK | This document is written in AmigaGUiDE format, so please read it |\n@REMARK | with AmigaGUiDE or your favourite guide reader.... ciao now...   |\n@REMARK `------------------------------------------------------------------''\n@REMARK $VER: ALARM V1.0\n@WiDTH 80\n@NODE MAiN "Guide to iCH SYSOP-ALARMiNATOR V1.0 WRiTTEN BY MuMu OF OSiRiS"\n                                   /\            /\            \n               ___________________/  \__________/  \__________\n               \_  _   _    _    /  __   _     /  __    _    /\n               /   |   \    |___/\__/\  _|   _/\__/\    |___/_\n              /    |    \____     \   \  \      /   \____     \\n              \    |    /   /     /   /  |\    /    /   /     /\n               \_______/_________/___/___| \  /____/_________/\n                                            \/         ©JoKER\n                            ¿S pROUD tø pRESENT:\n\n                 >»»»»> SYSOP-ALARMiNATOR VERSiON 1.00 <««««<\n\n                          @{"-*-   iNTRODUCTiON   -*-" LiNK iNTRODUCTiON}\n                          @{"-*-     FEATURES     -*-" LiNK FEATURES}\n                          @{"-*-   iNSTALLATiON   -*-" LiNK iNSTALLATiON}\n                          @{"-*-  EDiT TOOLTYPES  -*-" LiNK TOOLTYPES}\n                          @{"-*-  PRiVATE SCREEN  -*-" LiNK SCREENS}\n                          @{"-*- TROUBLE-SHOOTiNG -*-" LiNK PROBS}\n                          @{"-*-    WHO DiD iT    -*-" LiNK CREDiTS}\n                          @{"-*-     HiSTORY!     -*-" LiNK HiSTORY}\n                          @{"-*-    GREETiNGS!    -*-" LiNK GREETiNGS}\n                          @{"-*-    OUR SLOGAN    -*-" LiNK SLOGAN}\n@ENDNODE\n\n@NODE iNTRODUCTiON "iNTRODUCTiON OF SYSA VERSiON 1.0"\n\nSYSOP-ALARMiNATOR VERSiON 1.0 iS A TOOL WHO iNFORMS THE SYSOP ABOUT\nCERTAiN USERS WHEN THEY ARE LOGGiNG iNTO THE BBS.\niT HAS @{"FEATURES" LiNK FEATURES} THAT OTHER TOOLS DOESN''T HAVE.\n\n@ENDNODE\n\n@NODE FEATURES "FEATURES OF SYSA VERSiON 1.0"\n\ni DECiDED TO CODE THiS TOOL BECAUSE i LiKED THE USER-ALARMiNATOR V1.0\nRELEASED BY ABSTURZ-DESiGN LONG TiME AGO. THE USER-ALARMiNATOR V1.0\nFROM ABSTURZ-DESiGN iS VERY NiCE, BUT iT HAS SOME FEATURES MiSSiNG.\niT ONLY LOOKS iNTO A CONFiG-FiLE FOR THE USER-NAMES AND THEN WHEN iT\nFiNDS THE USER WHiCH iS LOGGiNG iNTO YOUR BBS SiMPLY PLAYS A SAMPLE\nTO iNFORM THE SYSOP.\n\niT HAS NO CONFiG-FiLES AND WORKS FULLY WiTH TOOL-TYPES iN THE iCON.\n\nMY VERSiON HAS LOTSA MORE OPTiONS. iT LOOKS FOR THE FOLLOWiNG THiNGS:\n\n 1. USER-NAME\n 2. ACCESS-AREA\n 3. ACCESS-LEVEL\n\n    OR ANY COMBiNATiON OF THOSE...\n\n\niF YOU WANT TO SEND A PERSONAL MESSAGE ALSO TO THE USER EVEN WHEN YOU\nDON''T WANT TO ALERTED WHEN HE iS LOGGiNG ON... NO PROBLEM!\n\nSYSOP-ALARMiNATOR V1.0 LOOKS WHENEVER THE TOOL iS STARTED FOR A SPECiAL\nTEXTFiLE WHiCH iS ONLY FOR THE USER WHO iS LOGGiNG ON.\n\nLOOK iNTO @{"PRiVATE SCREEN" LiNK SCREENS} FOR MORE iNFORMATiON.\n\nAND NOW i THiNK i GAVE YOU ENOUGH REASONS TO iNSTALL SYSA V1.0 :)\n\n@ENDNODE\n\n@NODE iNSTALLATiON "iNSTALLATiON OF SYSA VERSiON 1.0"\n\niNSTALLATiON TO @{"AMi EXPRESS V2.xx" LiNK AMiEXPRESSV2.xx}.\n\niNSTALLATiON TO @{"AMi EXPRESS V3.xx" LiNK AMiEXPRESSV3.xx}.\n\n@ENDNODE\n\n@NODE AMiEXPRESSV2.xx "iNSTALLATiON TO AMi EXPRESS V2.xx"\n\nTO iNSTALL THE DOOR LOAD UP THE CUSTOMCOMMANDS (/X V2.2x OR BELOW) OR\nSYS.CMD (/X V2.3x) AND ADD THE FOLLOWiNG LiNE TO THE LiST.\n\n\n          11 SPACES iN         \n          |\n-------------------------------------------          \n*ALARM    RM010MODULES:MM_TOOLS/ALARM/ALARM\n-------------------------------------------\n||        |||  |           \n||        |||  ` ''MODULES:MM_TOOLS/ALARM/ALARM'' iS THE LOCATiON OF\n||        |||     THE FiLE.\n||        |||\n||        ||` 001 THE MiNiMUM ACCESS TO USE THiS DOOR. CHANGE iT TO WHAT\n||        ||      YOU LiKE.\n||        ||\n||        |` ''M'' FOR A MULTiNODE BBS (''S'' FOR A SiNGLE NODE BBS).\n||        |\n||        ` ''R'' FOR A REXX DOOR WHiCH WiLL USE THE ''REXXDOOR''-UTiL.\n||\n|`COMMAND TO START THE DOOR.\n|\n`-RETARD OPTiON. TO MAKE SURE THEY ONLY USE ''ALARM'' & ONLY  ''ALARM''\n  TO GET THE DOOR TO COME UP. iF NOT USED, THiNGS SUCH AS ''ALARMO''\n  AND ''ALARMATRON'' WOULD STiLL BRiNG UP THE DOOR.\n\n\n  USE THE LiNE BETWEEN THE LiNES ONLY. THE OTHER PARTS ARE JUST AN\n  EXPLANATiON TO MAKE SURE YOU KNOW WHAT EACH PART iS DOiNG (SiNCE\n  NOONE WOULD TELL ME BACK iN THE DAYS WHERE i DiDN''T KNOW WHAT WAS\n  GOiNG ON!)  \n\n  NOW COPY THE ''OBJTEXT''-COMMAND FROM THE UTiLS-DiRECTORY OF THE\n  LHA-ARCHiEVE iNTO BBS:UTiLS/.\n\n  NOW COPY THE DiRECTORY ''MODULES'' FROM THE LHA-ARCHiEV TO YOUR BBS.\n\n  AT LAST EDiT THE @{"TOOLTYPES" LiNK TOOLTYPES} OF ''ALARM.iNFO''. YOU\n  WiLL FiND iT iN ''BBS:MODULES/MM_TOOLS/ALARM/''.\n\n  THE VERY LAST THiNG TO DO iS TO CHECK iF YOU HAVE THE FOLLOWiNG\n  COMMANDS iN YOUR C-DiRECTORY (COZ SYSA V1.0 WiLL NEED SOME OF THEM).\n\n  C:DELETE\n  C:COPY\n\n  NOW ADD THE FOLLOWiNG TO YOUR LOGON.TXT AND LOGON.TXT.GR\n\n  --------------CUT HERE----------------\n  ~CC_ALARM\n  --------------CUT HERE----------------\n\n \n  THAT''S ALL...\n\n@ENDNODE\n\n@NODE AMiEXPRESSV3.xx "iNSTALLATiON TO AMi EXPRESS V3.xx"\n\n  COPY ALL THE FiLES FROM THE LHA-ARCHiEV TO YOUR BBS AND\n\n  ADD THE FOLLOWiNG TO YOUR LOGON.TXT AND LOGON.TXT.GR\n\n\n  --------------CUT HERE----------------\n  ~CC_ALARM\n  --------------CUT HERE----------------\n\n\n  NOW COPY THE ''OBJTEXT''-COMMAND FROM THE UTiLS-DiRECTORY OF THE\n  LHA-ARCHiEVE iNTO BBS:UTiLS/.\n\n  AT LAST EDiT THE @{"TOOLTYPES" LiNK TOOLTYPES} OF ''ALARM.iNFO''. YOU\n  WiLL FiND iT iN ''BBS:MODULES/MM_TOOLS/ALARM/''.\n\n  THE VERY LAST THiNG TO DO iS TO CHECK iF YOU HAVE THE FOLLOWiNG\n  COMMANDS iN YOUR C-DiRECTORY (COZ SYSA V1.0 WiLL NEED SOME OF THEM).\n\n  C:DELETE\n  C:COPY\n\n@ENDNODE\n\n@NODE TOOLTYPES "HOW TO EDiT THE TOOLTYPES?"\n\n  ACSTYPE=<number>                       THE <number> DEFiNES FOR WHAT THE\n                                         SYSOP WANTS TO BE ALERTED.\n                                         1 = NAMES ONLY\n                                         2 = ACCESS-AREA ONLY\n                                         3 = ACCESS-LEVEL ONLY\n                                         4 = NAMES & ACCESS-AREA\n                                         5 = NAMES & ACCESS-LEVEL\n                                         6 = ACCESS-AREA & ACCESS-LEVEL\n                                         7 = NAMES & ACCESS-AREA &\n                                             ACCESS-LEVEL\n\n                                         E.G.: ACSTYPE=1 <- iS LOOKiNG\n                                                            FOR USER-NAME\n                                                            ONLY !!!\n\n\n  ACSLEVEL=<number>                      THE <number> DEFiNES THE \n                                         ACCESS-LEVEL OF THE USER BY WHiCH\n                                         THE SYSOP WANTS TO BE ALERTED WHEN\n                                         THiS OPTiON iS CHOSEN.\n\n                                         E.G.: ACSLEVEL=200\n\n\n  ACSAREA=<area>                         THE <area> DEFiNES THE ACCESS-AREA\n                                         OF THE USER BY WHiCH THE SYSOP\n                                         WANTS TO BE ALERTED WHEN THiS\n                                         OPTiON iS CHOSEN.\n\n                                         E.G.: ACSAREA=OSIRIS\n\n\n  USER.1=<user>                          THE <user> DEFiNES THE USER-NAME BY\n                                         WHiCH THE SYSOP WANTS TO BE ALERTED\n                                         WHEN THiS OPTiON iS CHOSEN.\n\n                                         E.G.: USER.1=MUMU\n                                               USER.2=SPIDER\n                                               USER.3=HELION\n\n                                         !!! YOU CAN ADD AS MANY USERS AS\n                                             YOU WANT !!!\n\n\n  SAMPLECONFIG=<path&options>            THE <path&options> DEFiNES THE PATH\n                                         OF THE SAMPLE-PLAYER AND THE SAMPLE\n                                         WiTH iTS OPTiONS WHiCH WiLL BE\n                                         PLAYED WHEN THE SYSOP iS ALERTED.\n\n  E.G.:\n\n  SAMPLECONFIG=SYS:C/RAWPLAY 430 63 BBS:MODULES/MM_TOOLS/ALARM/ALARM.SAMPLE\n\n  THAT SHOULD BE ALL FOR NOW...\n\n\n@ENDNODE       \n\n@NODE SCREENS "HOW TO BUiLT iN THE PRiVATE SCREENS?"\n\niF YOU WANT TO SEND A PERSONAL MESSAGE TO A USER EVEN WHEN YOU\nDON''T WANT TO ALERTED WHEN HE iS LOGGiNG ON... NO PROBLEM!\n\nSYSOP-ALARMiNATOR V1.0 LOOKS WHENEVER THE TOOL iS STARTED FOR A SPECiAL\nTEXTFiLE WHiCH iS ONLY FOR THE USER WHO iS LOGGiNG ON.\n\nMAKE A TEXTFiLE THAT SHOULD BE SHOWN TO THE SPECiAL USER AND NAME HiM\n''ALARM.USER.<number>''. THE <number> iS THE SLOTNUMBER OF THE USER WHO\nSHOULD GET THE TEXTFiLE.\n\nEXAMPLE: ''ALARM.USER.3''    <--- NOW THE USER WiTH THE SLOTNUMBER 3\n                                WiLL GET THE TEXTFiLE.\n\n !!! ATTENTiON !!!\n\nMAYBE YOU JUST WANT TO ANNOY A USER WiTH A PERSONAL TEXTFiLE BEFORE\nDELETiNG HiM. AFTER YOU DELETED THE USER iT MAY BE HAPPEN THAT ANOTHER\nUSER HAS NOW THE SAME SLOTNUMBER WHiCH THE DELETED USER HAD. NOW THE NEW\nUSER WiLL GET THE PRiVATE TEXTFiLE. TAKE CARE OF THE PRiVATE TEXTFiLES\nSO NOBODY WiLL GET A TEXTFiLE WHO SHOULD NEVER GET ONE.\n\nNOW COPY THE ''ALARM.USER.<number>'' iNTO ''BBS:MODULES/MM_TOOLS/ALARM/''.\n\nTHAT SHOULD BE ALL...\n\n@ENDNODE\n\n@NODE CREDiTS "CREDiTS FOR SYSA V1.0"\n\n   iDEA          : MuMu øf OSiRiS\n   \n   AREXX-CODiNG  : MuMu øf OSiRiS\n   \n   DOCUMENTATiON : MuMu øf OSiRiS\n\n   ANSi-ARTiST   : JOKER øf TAURUS\n\n   BETA TESTiNG  : MuMu   - KEY WEST - OSiRiS EHQ - SCANDAL DiST SiTE\n                   \n\n@ENDNODE\n\n@NODE GREETiNGS "FRiENDSHiP RULEZ"\n\n               GREETiNGS FROM MuMu TO THE FOLLOWiNG PEOPLE:\n              ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nCREEPY/TFP          - HOW iS iT GOiN''?\nGANDALF/SCL         - ARE YOU DEAD?\n                      i''VE HEARD YOU HAVE A GiRL-FRiEND NOW\nJOKER/TAU           - THANX FOR THE ALARM-ANSi!\nRAF/TFP             - STiLL UPSET, DUDE?\nMURDOC/NEON         - i WiSH YA FUN WiTH YOUR GROUP.\n \n\n                  AND A BiG HELLO TO ALL OSiRiS MEMBERS !\n\n@ENDNODE\n\n@NODE PROBS "DO YOU HAVE ANY PROBLEMS?"\n\n               FOR TROUBLE-SHOOTiNG OR LATEST UPDATES CALL:\n              ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n                 sYSOP: MuMu    «·»    1 nODE - 16.8k DHST       \n      - -- --- --------------------------------------------- --- -- -\n               ___                 \          /                      \n        ______/  /___  __  __    ___\        /____  _______________  \n        \_   /  /__  \/  \/  \   \   \      /___  \/  ____/\__    /  \n         | _/ _/ _/  /   /   /    \  /\    /  _/  /\____ \_   \__/   \n         | \  \  \__/\__    /  ·   \   \  /   \__/|    /  /     \    \n         |__\  \___________/        \/\  /________|______/|      \   \n             \__\                      \/              EaZ|_______\  \n                  OSiRiS EHQ & SCANDAL DiSTRiBUTiON SiTE             \n      - -- --- --------------------------------------------- --- -- -\n\n                    » aMiGA · /X · cONSOLE · mODULES «               \n\n               aMiXPRESS v3.XX   ø   nUP & sYSTEM pW nEEDED          \n\n                    -:) cALL nOW fOR a goOD rATiO (:-                \n\n@ENDNODE\n\n@NODE SLOGAN "OUR SLOGAN..."\n\n                                   /\            /\            \n               ___________________/  \__________/  \__________ \n               \_  _   _    _    /  __   _     /  __    _    / \n               /   |   \    |___/\__/\  _|   _/\__/\    |___/_ \n              /    |    \____     \   \  \      /   \____     \\n              \    |    /   /     /   /  |\    /    /   /     /\n               \_______/_________/___/___| \  /____/_________/ \n                                            \/         ©JoKER\n\n                        - WE DON''T WANNA BE THE BEST -\n \n                       - WE JUST WANNA HAVE MORE FUN! -\n\n@ENDNODE\n\n@NODE HiSTORY "THE HiSTORY OF ''SYSOP-ALARMiNATOR''"\n\n                   THE HiSTORY OF ''SYSOP-ALARMiNATOR V1.0\n                  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nVERSiON 0.1 - 0.9 : iNTERNAL BETA-RELEASES\n\nVERSiON 1.0       : FiRST PUBLiC RELEASE\n                    - NO BUGS KNOWN -\n\n\n                     !!! FUTURE VERSiONS WiLL FOLLOW !!!\n\n@ENDNODE\n','\n',char(10)),'{"TYPE":"<number>"}','auto-added',151915,6,0,NULL,NULL,'alarm','scan',1780048403);
INSERT INTO door_catalog VALUES('alc_ac10','ALC-AC10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ALC-AC10.LHA',NULL,'XIM','_____ __.   _____ _____ _____',NULL,NULL,'ALC','.\__ /.\ |__.\__ /.\___/.\__ /_:----------: |  __ |  |\ |  |__|     |  ___/| Alcatraz | |  \'' |  |  |  |  |     |  \'' ||   1997   |',replace(' _____ __.   _____ _____ _____\n.\__ /.\ |__.\__ /.\___/.\__ /_:----------:\n|  __ |  |\ |  |__|     |  ___/| Alcatraz |\n|  \'' |  |  |  |  |     |  \'' ||   1997   |\n`--,__l--,__l--,__l--,__l--,__l:----------:\n-------------------------------------------\n Access v1.o - Nice way of kicking a user!\n-------------------------------------------\nWill display a reson why the user is kicked\n     Nice design, fast, very useful!\n-------------------------------------------\n`-------å nei........WINTERLaND?-----------''\n','\n',char(10)),'Access.doc',replace('\n                                aCCESS v1.o\n                                -----------\n\n   (the day after i relesed EazyValidation, i realse this door.. ooooh,\n    somebody STOP me! BTW EazyVal, is the biggest door i ever made..\n    390+ lines of arexx code.. :/ Fuck arexx.. it''s slow, but sooo easy!)\n\n                                   wHAT?\n                                   -----\n  Ever seen Access Checker from MST? Very good ide, but i did''nt like the\n  design.... :/ Here is another door, that works in the same way, but in\n  my oppinion, a nicer design.. The doors checks in a cfgfile if the user\n   is listed there, and if he is, then the door will display a reson why\n               the user is unwanted, then the door hangsup!\n\n                               iNSTALLATiON\n                               ------------\n\n Hum..not much to say! Just copy the Access.dd to doors:rexxdir/ and then \n add this line at the top of Welcome.gfx/txt\n\n-\nÿDdoors:rexx %N doors:rexxdir/access.dd||\n-\n\n  Then start ced and create a file i daydream:configs/ called Access.cfg,\n     in this file u put the users + reson that is unwanted, like this:\n\n HANDLE 1       ;line 1\n RESON 1        ;line 2\n HANDLE 2       ;line 3\n RESON 2        ;line 4\n\n      then just login and (hopefully) the door will let you pass.. ;)\n\n                                oTHER dOORS\n                                -----------\n\n nAME             lATEST vERSION       tYPE\n ------------------------------------------------------------------------------ \n EazyValidation       v1.2             Newuserquestionnare\n Kickem               v2.o (unrelesed) Check baudrate, kicks slowbauders\n Lava                 v1.2             Leech Account Manager (Util, not door!)\n Leechecker           v1.1             Keep the leecher''s where the belong!\n Major Fuckup         v1.o             Passwordfailure door\n RealChecker          v1.o (Fixed ver) Checks/Add/Strips all kinds of files\n Alciztatus           v1.1             Nice status door\n StoryTeller          v1.o             Write a nice story, 1 line/user!\n Transfer             v1.o             Nice before/after transfer door\n -----------------------------------------------------------------------------\n\n                       You can leech these doors at\n \n              .--------------------------------------------------.\n        ______| ______       _______  ______       ____        __|________\n   _____\    (__\_____)_____/    __/__\_____)______\_ (__    _/   ___    /_____\n   \     \_______________________\_____________________.-''-- \_____\____/     /\n    \_____\                          _                 l______ _       /_____/\n       ______ ________ ___ __    ____\/________    __ ___ ________\n     __\___ (_\_______\\__\\_)  _)   \/       (_  (_//__//_______/_________\n   _/   __/   \                 \___/_         /                 _)   __   \_\n   \     \____ \____      __ __   _/          /  __ __    ______/  ___/-----''\n    \_____\_/   ___/___  (_/ \ )  \     _\___/  ( / \_)  _)    ____/\n           \__.__\____ \______\_   \      \_    _/_____ / ____.--''-- -\n           ult|    _/   __   (_     \      /     _)    /   \_ l______ _\n              |    \_____\____ \____ \    _ ____/ __________/ry! .\n      .-------+-- -        _/    __/___  _______   \_        - --+-------.\n      |       `------------\_____\_____\/___________/------------''       |\n      |                                                                  |\n      |     Dreamin'' along with daydream v.latest for maximum speed!     |\n      |                                                                  |\n      |      Always having a compo, +70% to topuploader each week!!      |\n      |                                                                  |\n      |  o-3 dayz amiga warez · 150MB+ oldies · large dD support conf!   |\n      |                                                                  |\n      |      +   4   6   -   0   4   1   4   -   6   0   1   1   7   +   |\n      `------------------------------------------------------------------''\n\n                           sEEKING fOR a gROUP!\n                           --------------------\n  I''m seeking for a group to join! Any-1 interested? Just invite me in! \n\n             ÷X÷ wOLFMAN ÷X÷ mOSQUiTO ÷X÷ oRiGO ÷X÷ bOOTH ÷X÷ \n               ÷X÷ dEMiGOD ÷X÷ rAY-mAN ÷X÷ jAM ÷X÷ sTORM ÷X÷\n\n Major sorry to dEMiGOD, for spellig your handle wrong in the EazyVal.doc!\n                -------\n\nLast Second Notes: DONT write me messages via e-mail, i lost all codes to\n                   Hotmail, so i can read them! Stay tuned for a new e-mail!\n\n','\n',char(10)),NULL,NULL,19441,5,0,NULL,NULL,NULL,'scan',1780048403);
INSERT INTO door_catalog VALUES('alc_la12','ALC-LA12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ALC-LA12.LHA','Lava','XIM','Lava',NULL,NULL,'ALC','.\__ /.\ |__.\__ /.\___/.\__ /_:----------: |  __ |  |\ |  |__|     |  ___/| Alcatraz | |  \'' |  |  |  |  |     |  \'' ||   1997   |',replace(' _____ __.   _____ _____ _____\n.\__ /.\ |__.\__ /.\___/.\__ /_:----------:\n|  __ |  |\ |  |__|     |  ___/| Alcatraz |\n|  \'' |  |  |  |  |     |  \'' ||   1997   |\n`--,__l--,__l--,__l--,__l--,__l:----------:\n-------------------------------------------\n   Lava v1.2 - Manager for Leech Acounts\n-------------------------------------------\n New design, works on any screen, faster,\n    nicer, better, in one word: Great!\n--------------------------------------------\n`----W I N T E R L a N D [31 Jan 1997]-----''\n[ISDN] DigiTal-X   CBD*WT*EXL* 6Ndz [ISDN]\n','\n',char(10)),'Lava.Doc',replace('\n                                 Lava v1.2\n                                 ---------\n\n                                 Update...\n                                 ---------\n\n* Replace the Lava and Lava_Check files\n* Delete Daydream:Configs/Lava.cfg\n* Run Lava & reconfigurate it...\n\n                                Install...\n                                ----------\n\n* Copy the Lava & Lava_Check to Daydream:Utils/\n* Copy the Lava#?.Msg files to Daydream:dispay/iso\n* Copy this doc file to Daydream:docs/\n* Add the line Lava_Check to Daydream:Batch/LogoffX.Bat\n* Run Lava & Config it, shold''nt be so hard.. :)\n\n                                 Usage...\n                                 --------\n\nAbout\n-----       \nShow some info, press the About button again to return\n\nAdd User\n-------\nAdds a new user, the user handle MUST be the same as in daydream.\nThe date MUST be typed in like this DD/MM/YYYY, i.e 26/01/1997\nYou have to edit the userdata in daydream to (turn free leech on..)\n\nDelete User\n-----------\nDeletes a user. NOTE: The user still got free leech in daydream, you\nmust edit the userdata to! (Mabey in another version...)\n\nWrite Msg.\n----------\nWrites a message to the user with robowriter. Write 1 = Lava1.Msg a.s.o\n\nOther Page\n----------\nFor registerd users only! Show the other page with users.\nTo get registerd, keep on reading\n\nConfig\n------\nStarts the config program, lets you reconfigurate Lava\n\nQuit\n----\nExits..\n\n                             Get registerd...\n                             ----------------\nThe registation is free, all you have to do is call +46 -414- 60117 and ask\nfor a Lava Account, or write a e-mail to [email removed].\nInclude your name/handel and some other interseting stuff, like yout bbs name\nand number. In the registred version you can have 1-46 payusers (more in\na later version...)\n\n                           Thanks & Greets to...\n                           ---------------------\n     Wolfman, Mosquito, TBB, Jam, Adde, ./\TL/\., Johnne, pET, ProXyon\n   Origo, Soxius, Fairydust, GameBoy, BigBang, Gosweede, Dwarf, RaY-mAN\n\n\n                   HTTP:   WWW.Angelfire.Com/Al/Hangover\n                    E-Mail: [email removed]\n\n','\n',char(10)),NULL,'auto-added',45710,6,0,NULL,NULL,'alc_la12','scan',1780048403);
INSERT INTO door_catalog VALUES('alcmail1','ALCMAIL1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ALCMAIL1.LHA','CyberCron','XIM','CyberCron',NULL,NULL,NULL,'~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~ A Simple Shell and CronTab Based Utility to Mail FidoNet,AmyNet..etc.. at once.',replace(' A GREAT TOOL TO USE TRAPDOOR AND /X IN ONE \n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nA Simple Shell and CronTab Based Utility to\n   Mail FidoNet,AmyNet..etc.. at once.\n--------------------------------------------\n33.6 DigITal-X Prd/NirVana Dist Site! 33.6\n','\n',char(10)),'ALCMAIL.doc',replace(' \n                          ____________________  _                    |\n   .oOo.oOo.oOo.oOo.     / __/_  _/_/__// / / \//  .oOo.oOo.oOo.oOo. |\n    _________________   /\  / / // //  /  _/\  /   __________________|\n   |                /   \  / / // //__/ / /_/ /    \                 |\n   |.oO ReAlItY Oo./     \/  \/ \/\__/\/\/ \_/      \ By:            |\n   |.oO DeSIgNs Oo.\    _______    ______________   /      AlCoHoLiC |\n   |________________\  /____/_/\/\/___/__/__/ __/  /_________________|\n   |                  /___// /   / \_/__/ //\  / \n   |.oOo.oOo.oOo.oOo /  / / /   /\  /  / / \  /    .oOo.oOo.oOo.oOo.\n   |                 \_/  \/\/\/\__/\_/\/   \/©  \n\n    ®¯®¯®¯®¯®¯®¯®¯®¯®¯®¯®¯®¯®¯®¯®¯®¯®¯®¯®¯®¯®¯®¯®¯®¯®¯®¯®¯®¯®¯®¯®¯®¯®¯\n\n\n\nPURPOSE:\n~~~~~~~~\n	I got sick and tired of trapdoor in front of my /X\n	long time ago..\n	now to convince some people that /X and trapdoor\n	suxx (in my oppinion)\n	i wrote this small tool..\n	\n	MAIN PURPOSE:\n\n	it tosses your mail in all areas\n	(as stated in your traptoss.cfg)\n	then kills your serial attached node [1 only]\n	(b''coz i only have 1 node) :(\n	and will call out the host [Boss]\n	(as stated in the trapdoor.cfg)\n	meanwhile the transfers will take place\n	and your packed mail will be send and remote\n	mail recieved..\n	after that trapdoor will close,\n	and the tool will unpack all your mail into\n	the area''s\n	(as stated in your traptoss.cfg)\n	after that it will update pointers etc..\n	close, and finally put your /X node back online\n	HOW SIMPLE..\n\n\nREQUIREMENTS:\n~~~~~~~~~~~~~\n-	atleast an amiga !\n	are they still available ??? :)\n-	a shell or crontab/cybercron(included)\n	mailing can be done by hand or remote {script}\n	i used crontab at 3 o clock at night so i don''t\n	have to get up at that time :)\n-	a complete installed fidonet..\n	preferable is ofcoz /X-fido by tycoon/mystic !!\n	(Hi Piet !)\n-	a set of configs to go allong with it\n	(otherwise the whole programm fuxx up)\n	A running amiexpress {reg ofcoz} :)\n	and a tool to handle AIM doors...\n\nHOW 2 INSTALL:\n~~~~~~~~~~~~~\n	simply copy or add the crontab example to you own\n	copy the alcmail.exe to the dir stated in s:crontab\n	and thats all...\n\n\nUSAGE:\n~~~~~~\n	let crontab take care of it\n	or if you are impatient,\n	use a shell or cli and type ''ALCMAIL.EXE''\n	\n\n\nBUG REPORT & SUGGESTIONS:                      \n~~~~~~~~~~~~~~~~~~~~~~~~~\n\n	All Utils Are Tested On A C=A1200/020/82/50mhz\n	It''s Possible That It Might Not Run On Your System\n	if So Feel Free To Contact Me....\n	ALCOHOLIC/REALITY EHQ AT STICKY-FINGERS +31-713-208-78\n	or at\n	THE SOUTHERN TRIBE REALITY WHQ +31-4160-30-252\n\n\n\nHISTORY:\n~~~~~~~~\n	none made it in a flush\n	so lets hear the bugs !\n\n\n\nTHANX MUST GO TO:\n~~~~~~~~~~~~~~~~~\n\n	myselfe for staying up late AGAIN..\n	and ofcozz wizz/reality who gave me the id\n	without even knowing it ! :)\n','\n',char(10)),NULL,'auto-added',98041,16,0,NULL,NULL,'alcmail1','scan',1780048403);
INSERT INTO door_catalog VALUES('alster','ALSTER.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ALSTER.LHA','Children','XIM','Children',NULL,'/*/sNT\eVOLUTION',NULL,'/ __ \__ \ ______\ ____ _ \__ \ ______ \_  > / / / / / / _/ / _/ _/_/ / / / / _/ / / // / \/\/\/\__/\___/\/ \___/\/\/\__/\___/\/\/ \/',replace('  __________________________________________\n / __ \__ \ ______\ ____ _ \__ \ ______ \_  >\n/ / / / / / _/ / _/ _/_/ / / / / _/ / / // /\n\/\/\/\__/\___/\/ \___/\/\/\__/\___/\/\/ \/\n  -*- iNDEPENDENT cONNECTION pRESENTS -*-\n                #18.12.1995# \n    This tool starts only for NEWUSERS /X\n            bY /*/sNT\eVOLUTION\n','\n',char(10)),'New.Doc',replace('_ __ ________________________________________________________________ __ _\n                                                      ___\n    .,,,,     .---._ Oo  .::::. .::::. :::   :::    __\__\\n    ( oo)__   (¯oo) /..\ ::  :: ::  :: :::   :::    \ / Oo\o  (\(\\n   /\_  \__) /\_  \/\_,/ ::  .. ::..:: ::''   ::''    _\\`--_/ o/oO \\n   \__)_/   _\__)_/_/    :::::: :::::: ::....::.... \_ \  \  \.--''/\n   /_/_/    \ /_/_//     `::::'' ::  :: `:::::`:::::: /_/__/   /¯\ \___\n _(__)_)_,   (__)_/  .::::.                      ;::  |_|_    \_/_/\_/\\n  o    o      (__)) ,:'' `::::::::::::::::::::::::::'' (__)_)___(_(_)  ¯¯\n              ________  ____________________  __   _/\  ___ \n              \____   \/  / ___/  /_  _/    \/ /   \  \/ \/\n               \   \   \ / /__^  / / //  ^  /  \___ \    /     ___    __o \n               /_______//\___/__/ /_/ \_/\_/\_____/ /    \_   ___   _-\<,_ \n               DREAM MACHINE WorLD DHQ CenTer ©    /__/\___''97 ___ (_)/ (_)\n\n            NirVaNa  : wORLD iNNOVATION wORLD dISTRIBUTION sITE!\n       Dream Machine : wORLD iNNOVATION wORLD dISTRIBUTION sITE! \n        Cyber Dreams : wORLD iNNOVATION wORLD dISTRIBUTION sITE!\n               Exlex : wORLD iNNOVATION wORLD dISTRIBUTION sITE!\n         Wanted Team : wORLD iNNOVATION wORLD dISTRIBUTION sITE!\n\n  Node [1] +31-570-637050  Node [2] +31-570-636468  Node [3] +31-570-677702\n\n  Amiexpress V4.20 Registered On An Amiga 2000 GVP-Tekmagic 68060 32MB KS3.1\n    Pioneer Changer DRM-604X + Toshiba Cd-Rom 4 HD''s 7110MB Space Total...\n\n   2 * cREDITZ fOR mAJORS! 3 * cREDITZ fOR mAJORS fROM yOUR oWN gROUP!\n    pROVIDING yOU: Amiga ECS/AGA, PC, AmiExpress, Sex Pic, Sex Stories\n\n\n- -- ---------------------------------------------------------------- -- -\n\n','\n',char(10)),NULL,'auto-added',96583,6,0,NULL,NULL,'alster','scan',1780048403);
INSERT INTO door_catalog VALUES('alynx131','ALYNX131.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ALYNX131.LHA','ALynx','XIM','ALynx',NULL,'Ami/Tcp',NULL,'.-----------------------. | Straight from da NET  | )--------------------- -(',replace('\n.-----------------------.\n| Straight from da NET  |\n)--------------------- -(\n|  Alynx version 1.31   |\n|     a VERY FAST!      |\n|     WWW Browser       |\n|     For Ami/Tcp       |\n|      and Mlink        |\n`-----------------------''\nbY tHE tERRoRisTS!!!!!!!','\n',char(10)),'ALynx.guide',replace('@database ALynx.guide\012@$VER ALynx.guide 0.11 (3.10.95)\012\012@node MAIN "ALynx Documentation - Contents"\012\012                   ALynx_2.4-FM AmigaPort 1.31 (10/15/95)\012\012                 ASCII-Web-Browser for Amiga/AmiTCP/MLink\012\012                  ported to Amiga in 1995 by P.Marquardt\012\012            @{" What is it ? " link DESCRIPTION}    @{"    Usage     " link USAGE}	@{"  Betatester  " link BETATESTER}\012            @{"    Author    " link AUTHOR}    @{"   Problems   " link PROBLEMS}	@{"    People    " link HELPERS}\012            @{"    Notes     " link NOTES}    @{"   Commands   " link COMMANDS}	@{"   Goodies    " link GOODIES}\012            @{"   History    " link HISTORY}    @{"   lynx.cfg   " link LYNXCFG}	@{"    Files     " link FILES}\012\012\012      ALynx Homepage: http://www.fhi-berlin.mpg.de/amiga/alynx.html\012      ALynx IRC-bot : "/msg CamAI send alynx"\012\012@endnode\012\012@index INDEX\012\012@node GOODIES "other files in distribution"\012 *************************************************************************\012 *                                Goodies                                *\012 *************************************************************************\012\012    Some goodies are distributed within the ALynx archive:\012\012	@{"ReSize.lha" link RESIZE}		handle LINES/COLS\012\012	Mosaic_Shunt.rexx	modified version from \012				Peter Hanrahan <[email removed]>\012\012	Nudel_MALS.lha		Other shunt-proggie from \012				Leo Davidson <[email removed]>\012\012	copystripper.rexx	kludge to handle DOWNLOADER: option\012\012	mail.rexx		simple mailclient which requires AmiTCPs\012					TCP:-device\012				Josef <[email removed]>\012\012    Feel free to send other tools/features for use with ALynx.\012\012    Send to     [email removed]\012         or     [email removed]\012\012@endnode\012\012@node DESCRIPTION "original description of lynx"\012 *************************************************************************\012 *                              DESCRIPTION                              *\012 *                 (from the original-distribution-docs)                 *\012 *************************************************************************\012\012 Lynx is a general-purpose distributed information browser and is part\012 of the World Wide Web project.  Lynx was designed to support a  Campus\012 Wide  Information  System  (CWIS),  but  can  be  used  for many other\012 applications.\012\012 When  it  is  started,  Lynx  is  given a local path specifying a file\012 containing text to be displayed, or a Uniform Resource  Locator  (URL)\012 that  specifies a resource to be displayed (usually the name of a file\012 containing text information), the type of  server  that  will  provide\012 the  resource,  and  the  Internet  address of the system on which the\012 specified  server  is  running.   If  the  URL  or  path  specifies  a\012 hypertext  file, that file will be a standard ASCII text file in which\012 hypertext links are embedded.  The simplest hypertext link is  just  a\012 URL  designating  another  resource which itself may contain both text\012 and links.\012\012 When  a  hypertext document is being displayed, links appear different\012 from standard  text,  and  users  press  the  up-  or  down-arrows  to\012 "select"  a  particular  link.   Selected links show up as highlighted\012 text,  and  users  press  Return  or  right  arrow  when  a  link   is\012 highlighted  to "follow" the selected link.  When the link is followed\012 Lynx finds the associated file and displays it on the screen in  place\012 of the first file.\012\012 Lynx data files can reside on any accessable local file system. (i.e.\012 NFS, AFS, etc.), or on remote  servers.   Currently  supported  remote\012 servers  are  HTTP,  Gopher,  FTP, NNTP, and WAIS.  A single hypertext\012 file may include links pointing to multiple remote  servers,  so  that\012 Lynx provides a truly distributed hypertext system.\012\012 Lynx is available for most flavors of Unix and VMS\012\012 This  Un*x version of Lynx should work on any system with a reasonable\012 Curses implementation\012\012@endnode\012\012@node NOTES "some notes about ALynx"\012 *************************************************************************\012 *                                 Notes                                 *\012 *************************************************************************\012\012  o This is a port. Don''t expect everthing to work!\012\012  o AmiTCP-Version (ALynx) works fine with AmiTCP and MLink\012  \012  o AS225-Version (Alynx_AS225) works fine with AS225r2 or I-Net 225 but\012    doesn''t work with MLink.\012    Reported by Osma Ahvenlampi <[email removed]>\012\012  o @{"files" link FILES} needed:\012\012    AMITCP:db/Lynx.cfg or INET:db/Lynx.cfg or PROGDIR:Lynx.cfg\012    ENV:Mosaic/mailcap    (configurable via @{"Lynx.cfg" link LYNXCFG})\012    ENV:Mosaic/mime.types (configurable via @{"Lynx.cfg" link LYNXCFG})\012\012  o To use a simple curses-screen type\012\012	@{b}1> ; call alynx on own screen (WB clone)@{ub}\012	@{b}1> alynx -term screen http://taa.dah.com@{ub}\012\012    or set the environmentvar CURSESTYPE to @{"SCREEN" link SCREENSETTINGS}\012\012	@{b}1> ; use own screen@{ub}\012	@{b}1> setenv CURSESTYPE screen@{ub}\012\012    ALynx runs in a CLI-Shell-Window (amigados/bbs) by default.\012\012    To force it to ANSI-mode:\012\012	@{b}1> alynx -term ansi http://taa.dah.com@{ub}\012\012    or\012	@{b}1> ; run in this shellwindow@{ub}\012	@{b}1> setenv CURSESTYPE ANSI@{ub}\012\012  o If your shell doesn''t set the environment-variables LINES & COLS\012    use @{"ReSize" link RESIZE} which is included in the ALynx archive.\012\012  o until now no DIRED-support\012\012  o BBS-Sysops:\012    Be careful by installing ALynx on a non-MuFS-BBS-System!!!\012    There is no fileprotection in ALynx. I don''t take any responsibility\012    if someone trashes your local filesystem. Lynx is designed to work\012    in a protected Unix/VMS-filesystem. I''ll try to fix this, but this\012    is really hard work. If you find any holes, TELL ME!\012\012  o There is, and there will never be direct inline-gfx/mouse-support\012\012  What works: (reported by several people)\012\012  o AUTH\012  o Proxy\012  o almost everything\012  o e-mail\012  o ftp, gopher\012\012  Todo:\012\012  o DIRED\012  o more colors (this IS heavy stuff)\012\012@endnode\012\012@node USAGE "how to start ALynx"\012 *************************************************************************\012 *                                 Usage                                 *\012 *************************************************************************\012\012	Just start ALynx with a valid URL.\012\012	@{b}1> alynx Your://favourite/URL/to/look/at@{ub}\012\012	To see the commandlineoptions try @{b}-help@{ub}\012\012	Take a look at @{" ENV:-Vars " link ENVVARS}!\012\012	Also don''t forget to take a look at @{"lynx.cfg" link LYNXCFG}!\012\012@endnode\012\012@node RESIZE "setting window bounds"\012 *************************************************************************\012 *                                ReSize                                 *\012 *************************************************************************\012\012  To use ReSize, just unpack ReSize.lha, read ReSize.readme and copy it\012  to any directory in your path.\012\012  ReSize is a small tool to calculate the number of rows/columns of the\012  current active cli-window and set environment-vars accordingly.\012  It was written due to the lack of such vars in some shells.\012\012  ReSize sets $LINES $COLS $COLUMNS $SCREENMODE vars as calculated.\012\012  Options of ReSize:\012\012  ReSize SET     ; sets local vars $LINES $COLS like "set LINES 24"\012  ReSize SETENV  ; sets same vars like "setenv LINES 24"\012  ReSize SAVE    ; same as SETENV, but also saves in ENVARC:\012  ReSize VERBOSE ; shows, what vars would be set\012\012  VERBOSE or V could be added to set and show the vars.\012\012@endnode\012\012@node ENVVARS "some vars to control ALynx"\012 *************************************************************************\012 *                         Environment variables                         *\012 *************************************************************************\012\012    ALynx understands the following environment-Variables (local/global):\012\012	COLS n\012	columns n		number of columns in shellwindow. (max. 160)\012	LINES n			number of lines in shellwindow\012				see also @{"ReSize" link RESIZE}\012\012	CURSESTYPE ANSI		run ALynx in shellwindow\012\012	@{"CURSESTYPE SCREEN" link SCREENSETTINGS}	run ALynx on own screen/pubscreen/screenmode\012\012	HOME			your valid home-directory\012\012	@{"CURSESANSICOLORS" link COLORSETTINGS}	ANSI-colormapping\012\012	@{"LYNX_CFG" link LYNXCFG}		location of @{"Lynx.cfg" link LYNXCFG}\012\012\012@endnode\012\012@node SCREENSETTINGS "how to fiddle with screens"\012 *************************************************************************\012 *                            Screensettings                             *\012 *************************************************************************\012\012	ALynx 1.12 finally introduces screenmodehandling, publicscreens\012	and cloned workbenchscreens.\012\012	This all is done by invoking ALynx with the -term=screen switch\012	or by setting the good old CURSESTYPE to "SCREEN".\012\012	The new options for this env-variable work the following way:\012\012 SET CURSESTYPE	SCREEN		<- this creates a copy of your wb-screensize\012	"	SCREEN Mosaic	<- pop up on this (existing) publicscreen\012	"	SCREEN 0x99004	<- open customscreen with this modeID\012\012	ALynx will not open on publicscreens which have hexadecimal names 8)\012\012	The same syntax as above regards to the -term switch. remember to\012	use quotes when using public screen names or screenmodes:\012\012	@{b}1> ALynx -term "screen 0x89024" ftp://kermit.the.frog@{ub}\012\012@endnode\012\012@node COLORSETTINGS ""how to fiddle with colors"\012 *************************************************************************\012 *                             Colorsettings                             *\012 *************************************************************************\012\012    To map certain ANSI-colors to other colors set the CURSESANSICOLORS\012	environmentvariable. This isn''t as complicated as it sounds.\012	The default for CURSESANSICOLORS is:\012\012	@{b}1> setenv CURSESANSICOLORS 01234567@{ub}\012\012	To swap color 7 with color 1 just type\012\012	@{b}1> setenv CURSESANSICOLORS 07234561@{ub}\012\012    Got it ? Nope ? O.k. Internals. Curses uses escapesequences like\012    "<ESC>[33m" to set the colors in ANSI-mode. So, when u decide\012    to swap color #2 with color #5, just set CURSESANSICOLORS to 01534267.\012    Now every escapesequence which should be "<ESC>[32m" will result in\012    "<ESC>[35m".\012\012    My standard curses-screen:      Workbench uses:\012\012        BLACK     0                 GREY       0\012        RED       1                 BLACK      1\012        GREEN     2                 WHITE      2\012        YELLOW    3                 GREY-BLUE  3\012        BLUE      4                 BLUE       4\012        CYAN      5                 CYAN       5\012        MAGENTA   6                 MAGENTA    6\012        WHITE     7                 ORANGE     7\012\012	@{b}1> ; use BLUE as highlight-color@{ub}\012	@{b}1> setenv CURSESANSICOLORS 01734564@{ub}\012\012	No palette-requester yet. This IS a CLI-based programm.\012\012          color item  ANSI-mode               Screen-mode\012	  ------------------------------------------------\012	  0/1   text: <ESC>[0m    (WB-black)      white\012	  2     bold: <ESC>[32m   (WB-greyblue)   yellow\012	  3     link: <ESC>[33m   (WB-white)      green\012\012@endnode\012\012@node COMMANDS "the keyboard"\012 *************************************************************************\012 *                          keystroke commands                           *\012 *************************************************************************\012\012         (from lynx_help/keystroke_commands/keystroke_help.html)\012\012          Btw, the following text wasn''t snapped, but @{b}lynxed@{ub}:\012\012   alynx -dump -nolist lynx_help/keystroke_commands/keystroke_help.html\012\012\012 MOVEMENT:  Down arrow    - Highlight next topic\012            Up arrow      - Highlight previous topic\012            Right arrow,  - Jump to highlighted topic\012            Return, Enter\012            Left arrow    - Return to previous topic\012\012 SCROLLING: + (or space)  - Scroll down to next page\012            - (or b)      - Scroll up to previous page\012\012 DIRED: (*) c             - Create a new file\012        (*) d             - Download selected file\012        (*) e             - Edit selected file\012        (*) f             - Show a full menu of options for current file\012        (*) m             - Modify the name or location of selected file\012        (*) r             - Remove selected file\012        (*) t             - Tag highlighted file\012        (*) u             - Upload a file into the current directory\012       \012 OTHER:     ? (or h)      - Help (this screen)\012            a             - Add the current link to your bookmark file\012            c             - Send a comment to the document owner\012            d             - Download the current link\012            e             - Edit the current file\012            g             - Goto a user specified URL or file\012            i             - Show an index of documents\012            j             - Execute a jump operation\012            k             - Show a list of key mappings\012            l             - List references (links) in current document\012            m             - Return to main screen\012            o             - Set your options\012            p             - Print to a file, mail, printers, or other\012            q             - Quit (Capital ''Q'' for quick quit)\012            /             - Search for a string within the current document\012            s             - Enter a search string for an external search\012            n             - Go to the next search string\012            v             - View your bookmark file\012            z             - Cancel transfer in progress\012            [backspace]   - Go to the history page\012            =             - Show file and link info\012            \\             - Toggle document source/rendered view\012        (*) !             - Spawn your default shell\012            *             - Toggle image_links mode on and off\012            [             - Toggle pseudo_inlines mode on and off\012            ]             - Send a HEAD request for the current doc or link\012            CTRL-R        - Reload current file and refresh the screen\012            CTRL-W        - Refresh the screen\012            CTRL-U        - Erase input line\012            CTRL-G        - Cancel input or transfer\012            CTRL-T        - Toggle trace mode on and off\012\012 Use  the  cursor control keys to move around in Lynx.  The up and down\012 arrows move you from one selected link  to  another.   Use  the  right\012 arrow  (or  Return) to follow a link, and use the left arrow to return\012 from a link.  The numeric keypad, or the numbers mapped to the  keypad\012 keys, can also be used (i.e., 6-right 8-up 9-pgup 3-pgdn)\012\012 (*) not implemented in Amiga-Port ALynx.\012\012@endnode\012\012@node AUTHOR "who wrote this program"\012 *************************************************************************\012 *                                Authors                                *\012 *************************************************************************\012\012          Michael Grobe, Charles Rezac, Lou Montulli\012          Academic Computing Services\012          University of Kansas\012          Lawrence, Kansas 66047\012\012\012 Thanks to Earl Fogel, Computing Services, University of Saskatchewan,\012 [email removed], who wrote the original hytelnet code, and Foteos\012 Macrides <[email removed]> who worked on many parts of the VMS\012 code.  Thanks to Jerome LAURET <[email removed]> for converting\012 the lynx man page to VMS help format.\012\012   Amiga-Port:\012\012          Peter Marquardt, Berlin, Germany\012          [email removed]\012          [email removed]\012\012   @{b}Please DO NOT bother Lou about ALynx. Send bugs/questions/improvements\012   only to [email removed] \012        or [email removed] ! Thanks.@{ub}\012\012\012   If you like me drinking lotsa coffee (which holds me awake, while porting)\012   u may donate several tons of money to:\012\012          bank     / Bank        : Postbank KOELN (Germany)\012          bank#    / Bankleitzahl: 370 100 50\012          account# / Kontonummer : 267-12-504\012          name     / Name        : P.Marquardt\012\012@endnode\012\012@node BETATESTER "how to supply bugreports"\012 *************************************************************************\012 *                          Note to Betatesters                          *\012 *************************************************************************\012\012Send bugreports to [email removed]\012                   [email removed]\012\012Enforcerhit-reports welcome!\012\012Best reports are generated by starting Enforcer like this:\012\012    @{b}run segtracker@{ub}\012    @{b}run mungwall PRESIZE 16 POSTSIZE 16 NAMETAG SHOWFAIL SHOWHUNK@{ub}\012    @{b}run enforcer SHOWPC STACKCHECK AREGCHECK DREGCHECK STDIO@{ub}\012\012Sorry, but I''m not able to find a LONG-READ on 0xDEADBEEF, so I just\012need _some_ more info 8)\012\012Tell me, what works.\012\012Well, u may also tell me, what doesn''t 8)))\012\012Thanks go to @{"these people" link HELPERS}\012\012@endnode\012\012@node HELPERS "who helped a lot"\012 *************************************************************************\012 *                                People                                 *\012 *************************************************************************\012\012    all these people on IRC reported bugs/features/suggestions\012    concerning the ALynx-port:\012\012    XS ([email removed]): Andreas Otte\012\012    N`Kognito ([email removed]): Heikki Kantola, genius\012\012    TheRaven ([email removed]): Bob Lindabury\012\012    Mick ([email removed]): Michael-W. Hohmann\012\012    babbage ([email removed])\012\012    JamesBart ([email removed])\012\012    Charger ([email removed]): Jaska Jokunen\012\012    coto ([email removed]): Thomas Runge\012\012    Camelot ([email removed]): Sami Itkonen\012\012    Tau ([email removed]): Osma Ahvenlampi\012\012    vito ([email removed]): Holger Behrens\012\012    [email removed]: Peter Hanrahan\012\012    _3V_ ([email removed]): Viljo "3V" Viitanen\012\012    cosinus ([email removed]): Christian Stelter\012\012    Billing ([email removed]): http://www.bastad.se/~billing\012\012    Saiful ([email removed]): Terje Bergström\012\012    [email removed]: Mike Meyer\012\012    [email removed]: Donald J. Maddox\012\012    [email removed]: Steinar Birkelund\012\012    Blue Thunder ([email removed]): Dave Anderson\012\012    [email removed]: Richard N. Hurt\012\012    [email removed]: Lauri Aalto\012\012    [email removed]: Dan Linder\012\012    [email removed]: Greg Baltzell\012\012    [email removed]: HammerD\012\012    [email removed]:  Andrew Nicholson\012\012    [email removed]: ScottE (a BIG help on AS225-version!!)\012\012    [email removed]: David Salbego\012\012    [email removed]: Matthias Barnutz\012\012    Josef ([email removed]): Josef Faulkner\012\012    [email removed]: Rene Beekman\012\012    [email removed]: Frank Copeland\012\012    troels.stud.cs.uit.no: Troels Walsted Hansen \012\012    ---> add your name to the list: REPORT BUGS! <---\012\012@endnode\012\012@node PROBLEMS "nah, no problems..."\012 *************************************************************************\012 *                               Problems                                *\012 *************************************************************************\012\012  - Problems with @{"ENV:Mosaic/mailcap" link PROBENVMAILCAP}\012\012  - Problems with my @{"english" link ENGLISH}\012\012----------------------------------------------------------------------------\012  Q: The URL http://foo.bar.com/blah.html doesn''t display some items correct.\012     I checked them with NetScape(tm) and other browsers so the error might\012     be in ALynx.\012\012  A: Before blaming ALynx/Lynx please run the page through something like\012     htmlchek (http://uts.cc.utexas.edu/~churchh/htmlchek.html). Also it\012     might help to run ALynx in screenmode and toggle tracemode (^T) before\012     receiving the page. NetScape(tm) is very tolerant concerning bad HTML,\012     so lots of pages out there _seem_ to be good HTML but actually are NOT.\012     Iw I wuolt wrid dis gihde laik dis, yu m8 anderstand me, but thiz\012     dohs nod mean dis iz korrect englishish. Got me ? 8)\012----------------------------------------------------------------------------\012  Q: Control-W doesn''t refresh the screen, what''s up ?\012\012  A: FComp on any other keyboard-patcher might swallow it. This might\012     occur for other keys, too. Check your systemconfiguration.\012----------------------------------------------------------------------------\012  Q: How can i disable the "Save anywhere on disk" item in the downloadmenu ?\012\012  A: Comment out "DOWNLOADER:Save anywhere on disk :..." entry in lynx.cfg\012----------------------------------------------------------------------------\012  Q: How can i set up different downloaddirs for different users on my\012     BBS setup ?\012\012  A: Edit Lynx.cfg and set DOWNLOADDIR: to any local Env-variable you like.\012     (ex.: "DOWNLOADDIR:$USERDOWNDIR" ). Then edit the startup-script for\012     ALynx on your BBS to set this new variable to the desired location.\012     (in this case for example: "set USERDOWNDIR $HOME/downloads/"). The\012     DOWNLOADDIR-option accepts directories OR vars (starting with ''$''),\012     if it doesn''t exist it uses $HOME.\012----------------------------------------------------------------------------\012  Q: How can i set up different downloaddirs in the download-menu ?\012\012  A: Take a look at "goodies/copystripper.rexx". It fixes a common \012     problem with the ALynx supplied quoted destination-filename.\012----------------------------------------------------------------------------\012  Q: Does ALynx support the new AMosaic1.4 hotlist format ?\012\012  A: No. At least not the nonstandard \@GROUP/\@ENDGROUP-tags. Sorry, I tried\012     implementing this, but when i created a hotlist with AMosaic1.4ß it\012     went to guruland. I''ll wait ''til it''s more stable.\012----------------------------------------------------------------------------\012  Q: "when it asks what name to save it under, you can add a path there ??\012      ... is there a way to make it perminantly save to a particular dir ?"\012\012  A: Well, Since 1.25 ALynx saves in $HOME by default. To specify another\012     default destination either modify DOWNLOADDIR: add new entries for \012     DOWNLOADER: in "lynx.cfg".\012----------------------------------------------------------------------------\012  Q: "it seems to work pretty fine here with Excelsior! BBS...odd thing is\012      that it popped my display into interlaced mode."\012\012  A:  You forgot to "setenv CURSESTYPE ANSI". (sorry, wasn''t mentioned here)\012      (now is default since port-release 1.2)\012----------------------------------------------------------------------------\012  Q: "I don''t have a HOME environment variable !"\012\012  A:  This variable will be created by default on local login via AmiTCP.\012      On MLink you have to set this one to any location where your "home"-\012      directory is. This location is for ALynx to search/save several files.\012      ALynx depends on existance so "set" oder "setenv" HOME.\012----------------------------------------------------------------------------\012  Q: "how can i get the cursor back to the current link ?"\012\012  A:  start ALynx with the "-show_cursor" option.\012----------------------------------------------------------------------------\012  Q: "how can i handle bigger/smaller windowsizes ?"\012\012  A:  There are 2 @{"ENV-vars" link ENVVARS}, controlling the size of the current shellwindow.\012      "COLS" & "columns" to set the number of columns.\012      "LINES"            to set the number of desired lines.\012\012      The small distributed tool @{"ReSize" link RESIZE} set these automagically.\012----------------------------------------------------------------------------\012  Q: "By the way. What''s the command to clear the history buffer ?"\012\012  A: There is no such command. This is Lynx-stuff. Maybe i''ll implement this\012     in later versions.\012----------------------------------------------------------------------------\012  Q: "How can I pass it a users email address?"\012\012  A: Options-Menu. [O] [P]\012----------------------------------------------------------------------------\012  Q: "I always get <Volume RAM: is full>-requesters after a while."\012\012  A: Your T:-assignemt probably points to RAM:T/ . This is the place\012     where ALynx puts it''s history-pages, so it might fill up fast.\012     Since version 1.18 u can tell ALynx, where to put it''s tempfiles.\012     Just take a look at @{"lynx.cfg" link LYNXCFG} and search for TEMPDIR:\012----------------------------------------------------------------------------\012\012@endnode\012\012\012@node PROBENVMAILCAP "mailcap & mime.types ?"\012 *************************************************************************\012 *                         mailcap & mime.types                          *\012 *************************************************************************\012\012   The searchorder for global mailcap-files could configured on several\012   ways. Edit "Lynx.cfg":\012   \012     1. Specify files\012        @{b}GLOBAL_MAILCAP:<path/file,,,>@{ub}\012        \012        Example:\012\012        @{i}GLOBAL_MAILCAP:ENV:Mosaic/mailcap@{ui}\012                            or\012        @{i}GLOBAL_MAILCAP:AmiTCP:db/mailcap ENV:Mosaic/mailcap@{ui}\012\012     2. Specify and Environment-variable which holds the files\012        @{b}GLOBAL_MAILCAP:$<env-var>@{ub}\012\012        Example:\012\012        In AmigaDOS:  @{i}set MAILCAPS AmiTCP:db/mailcap ENV:Mosaic/mailcap\012        In Lynx.cfg:  @{i}GLOBAL_MAILCAP:$MAILCAPS@{ui}\012\012   ENV:Mosaic/mailcap may have problems with SYS:Utilities/MultiView\012   in form of interpreting the PUBSCREEN=BlaScreen-Option.\012\012   I usually use mailcap-entries like\012\012      @{i}text/x-aguide; sys:Utilities/MultiView %s PUBSCREEN=Mosaic@{ui}\012\012   but this fails with ALynx when there is no pubscreen called "Mosaic".\012   In this case, Multiview fails with returncode 8009. [not my fault 8(]\012\012\012   A fast solution for this problem would be removing all PUBSCREEN=\012   entries from mailcap.\012\012   Solution from [email removed] (Peter Hanrahan): (thanx''a''lot)\012\012   > Also, I have a fix for the PUBSCREEN problem.  I have found on my\012   > systemn that I get a lot of problems when MUI makes or kills a\012   > public screen, frequently locking the system up.  I get around\012   > this by using ScreenWizard (on Aminet).  With this I can define a\012   > public screen, and when a program looks for it, it is created.\012   > This way MUI doesn''t get to make the screen, and so I don''t have\012   > these problems.  The other advantage is that when Alynx runs\012   > multiview, Screenwizard will create the MOSAIC pubscreen for it,\012   > a better solution than removing the pubscreen call.\012\012\012@endnode\012\012@node ENGLISH "gnafoo rabbeet kneek fata soo"\012 *************************************************************************\012 *                                English                                *\012 *************************************************************************\012\012   English isn''t my native language but I''m willing to learn it 8)\012\012   Please correct me if I''m wrong or use some offending words.\012   [I once called a Screen-Tool "stool" ... 8) ]\012\012@endnode\012\012@node FILES "ls -R, list all, dir all"\012 *************************************************************************\012 *                      ALynx - distribution-files                       *\012 *************************************************************************\012\012    ReadMe.Amiga		should get you right here \012\012    ALynx			executable\012    ALynx_AS225			AS225-executable (C= TCP/IP or I-Net 225 )\012    ALynx.guide			I don''t remember\012\012    @{"Lynx.cfg" link LYNXCFG}			check this one for configuration\012\012    jumps.html			jumps-example\012\012    CHANGES			original Unix/VMS Lynx history\012\012    ENV/Mosaic/mailcap		mailcap example    (copy to ENVARC:)\012    ENV/Mosaic/mime.types	mime.types example (copy to ENVARC:)\012\012    about_lynx/about_lynx.html	original\012    about_lynx/readme.html	original\012\012    goodies/ReSize.lha		handle COLS/LINES environment vars\012    goodies/ReSize.readme\012    goodies/Mosaic_Shunt.rexx	modified shunt (Rexx)\012    goodies/Nudel_MALS.LHA	other shunt (AmigaDOS)\012    goodies/Nudel_MALS.readme\012\012    orig/#?			some files which come with Unix/VMS Lynx\012\012    lynx_help/lynx_help_main.html	help main menu\012    lynx_help/Lynx_users_guide.html	lynx usersguide\012\012    lynx_help/keystroke_commands/#?	single helpfiles\012\012@endnode\012\012@node LYNXCFG "configure ? why ?"\012 *************************************************************************\012 *                               lynx.cfg                                *\012 *************************************************************************\012\012\012	The configurationfile "lynx.cfg" must be present in\012	one of the following locations:\012\012	1. filename specified by "-cfg" commandline option\012\012	2. filename specified by env-variable "LYNX_CFG"\012\012	3. "AmiTCP:db/lynx.cfg"\012\012	4. "INET:db/lynx.cfg"\012\012	5. "PROGDIR:lynx.cfg"\012\012 *************************************************************************\012 *                    Amiga entries in lynx.cfg                          *\012 *************************************************************************\012\012@{b}TEMPDIR@{ub}:<directory>\012\012	TEMPDIR is the default directory for ALynx to store temporary files.\012	Usually this is T:, but it could be set to some other space.\012	BEWARE! If you set TEMPDIR to some directory on harddisk, this\012	may corrupt your hard drive in case of a machinecrash.\012	The directory MUST end with a colon ":" or slash "/" \012	and it MUST exist.\012\012@{b}MAILCOMMAND@{ub}:<command to execute>\012\012	MAILCOMMAND is the default command for ALynx to mail a textfile\012	to the net. The file to be sent will be put behind this entry.\012	ALynx itself inserts the "From:" and "To:"-headerstuff.\012	You may add commandline options as needed.\012\012	ADMail-example:\012	(aminet:comm/mail by Simon Brown<[email removed]>)\012	@{i}MAILCOMMAND:ADMail@{ui}\012\012	SMTPpost-example:\012	(aminet:comm/net/INetUtils-1.4-AmiTCP)\012	the line below will expand to \012	"MAILCOMMAND:SMTPpost -f yourusername < T:L1297418400.html"\012	@{i}MAILCOMMAND:SMTPpost -f $USER <@{ui}\012\012	PutMail-example:\012	(aminet:comm/net/PutMail*.lha)\012	@{i}MAILCOMMAND:AmiTCP:bin/PutMail@{ui}\012\012@{b}DOWNLOADDIR@{ub}:<directory>\012\012	DOWNLOADDIR is the default directory for ALynx to store downloaded files.\012	On default this is $HOME, but it could be set to some other space.\012	The directory MUST end with a colon ":" or slash "/"\012	and it MUST exist.\012	ex.:DOWNLOADDIR:DH1:files/freshdata\012\012	You may also specify an environmentvariable like $DOWNDIR which\012	holds the path.. It has to be set up externally. ENV-vars are marked with\012	a leading ''$''. You cannot use mixed vars/pathes.\012	ex.: set USERDOWNDIR $HOME/downloads/\012	DOWNLOADDIR:$USERDOWNDIR\012\012@{i}for other keywords read file @{b}lynx.cfg@{ub}@{ui}\012\012@endnode\012\012@node FUN\012\012ALynx  is  an  WWW  oriented  system to view and obtain textual HTML pages.\012From  a websurfers point of view, using ALynx saves a lot of time and makes\012life  much  easier.   Thinking  about complicated terms like "delayed image\012loading" or "Guru alerts" is simply not neccesary.\012\012On the other hand, users of ALynx based WWW-connections have the ability to\012customize  nearly every option of the programs interface according to their\012personal taste.\012\012This  distribution  is  interesting  for  both, websurfers and surfwebbers.\012Please have a look at the supplied lynx.cfg and at the documentation to see\012what ALynx has to offer.\012\012@endnode\012\012@node INDEX "The Index"\012@{"AmiTCP.................." link NOTES} ALynx runs on AmiTCP\012@{"AS225..................." link NOTES} ALynx runs on AS225\012@{"Author.................." link AUTHOR} Who wrote this\012@{"Betatester.............." link BETATESTER} How to supply bugreports\012@{"Bugreports.............." link BETATESTER} gimme gimme gimme\012@{"Colors.................." link COLORSETTINGS} In ANSI-Windows\012@{"Commands................" link COMMANDS} Some keyboard definitions\012@{"DOWNLOADDIR:............" link LYNXCFG} Lynx.cfg\012@{"Downloaddirs............" link PROBLEMS} FAQ\012@{"e-mail configuring......" link FAQ} Options-Menu\012@{"e-mail of author........" link AUTHOR} My e-mail adresses\012@{"ENV: variables.........." link ENVVARS} Some special ENV: variables\012@{"ENV:COLS setting........" link RESIZE} Number of columns to display in shellwindow\012@{"ENV:CURSESANSICOLORS...." link COLORSETTINGS} How to change colors on ANSI\012@{"ENV:CURSESTYPE ANSI....." link ENVVARS} Run ALynx in current Shellwindow\012@{"ENV:CURSESTYPE SCREEN..." link ENVVARS} Run ALynx on its own screen\012@{"ENV:HOME................" link PROBLEMS} FAQ\012@{"ENV:LINES setting......." link RESIZE} Number of lines to display in shellwindow\012@{"FAQs...................." link PROBLEMS} Frequently Asked Questions\012@{"Files..................." link FILES} List of distributed files\012@{"Goodies................." link GOODIES} List of other supplied programs/utilities\012@{"History-Buffer.........." link PROBLEMS} FAQ \012@{"History................." link HISTORY} The growing of ALynx\012@{"Hotlists of AMosaic....." link PROBLEMS} FAQ\012@{"I-Net 225..............." link NOTES} ALynx runs on I-Net 225\012@{"IRC-Bot for ALynx......." link MAIN} Where to get ALynx on IRC\012@{"Keyboard................" link COMMANDS} Some keyboard definitions\012@{"Low on memory..........." link PROBLEMS} FAQ\012@{"Lynx.cfg location......." link ENVVARS} Setting via ENV:-var\012@{"Lynx.cfg................" link LYNXCFG} The configuration file, Amiga specials\012@{"mailcap................." link PROBENVMAILCAP} mailcap files: problems & where to search\012@{"MAILCOMMAND:............" link LYNXCFG} Lynx.cfg\012@{"MLink..................." link NOTES} ALynx runs on MLink\012@{"Money..................." link AUTHOR} Where to deposit your money\012@{"Mosaic_Shunt.rexx......." link GOODIES} Goodie\012@{"Notes..................." link NOTES} Some notes about ALynx\012@{"Nudel_MALS.lha.........." link GOODIES} Goodie\012@{"People.................." link HELPERS} People who helped with bugreports\012@{"Problems................" link PROBLEMS} Problems which may occur, Q&A section\012@{"Public screens.........." link SCREENSETTINGS} Run ALynx on its own screen\012@{"ReSize.................." link RESIZE} Utility to set LINES & COLS automagically\012@{"Saving files where ?...." link PROBLEMS} FAQ\012@{"Screenmodes............." link SCREENSETTINGS} Setting the desired screenmode\012@{"Screens................." link SCREENSETTINGS} Run ALynx on its own screen\012@{"Shuntprograms..........." link GOODIES} Inside archive\012@{"Starting ALynx.........." link USAGE} "Unknown command alynx"\012@{"TEMPDIR:................" link LYNXCFG} Lynx.cfg\012@{"Temporary files........." link LYNXCFG} Where to store them\012@{"Usage..................." link USAGE} How to start ALynx\012@{"What is it ?............" link DESCRIPTION} Small description of ALynx\012@{"WWW Homepage of ALynx..." link MAIN} Where to get ALynx on WWW\012@endnode\012\012@node HISTORY "...on the 7th day he ported ALynx"\012 *************************************************************************\012 *                                History                                *\012 *************************************************************************\012\012  Sun Oct 15 12:25:33 1995: @{b}ALynx_2.4-FM AmigaPort 1.31 (10/15/95)@{ub}\012\012	- fixed enforcerhit on ftp abort.\012	  (reported by Troels Walsted Hansen <troels.stud.cs.uit.no>)\012	- modified -term switch work like setenv CURSESTYPE.\012	  ex.: 1> alynx -term ansi www.foo.bar\012	  or : 1> alynx -term "screen 0x89024" ftp://localhost/stuff\012\012  Wed Oct 11 22:04:19 1995\012\012	- fixed CLI argument/[G]oto URLs to handle local filepaths with\012	  assigns again.\012	  (reported by Heikki Kantola <[email removed]>)\012\012  Tue Oct  3 21:26:22 1995: @{b}ALynx_2.4-FM AmigaPort 1.30 (10/03/95)@{ub}\012\012	- refixed mail handling\012	- btw. my e-mail has changed! Do NOT use [email removed]\012	  anymore. It''s now "[email removed]".\012	  "[email removed]" is still valid, too!\012	- fixed reference to usergroup.library for MLink''ers. No Requester\012	  should pop up anymore. MLink''ers still need usergroup.library.\012	  (reported by Wouwe van AP <[email removed]>)\012	- short feature-list: prompted string editing, editing of titles\012	  when adding bookmarks, more documentation and help updates,\012	  -validate switch for anonymous users, -historical switch for \012	  comment handling, -nolist switch, better recovering from bad \012 	  HTML, TEXTAREA handling like Netscape, STARTFILE/HOMEPAGE and\012	  ''g''oto URLs get converted "www.foo.com" -> "http://www.foo.com",\012	  ALT="" IMG tags handling, -link/traversal/crawl switch for\012	  automagically walk down all links on a page, send HEAD request\012	  key '']'', -post_data, -get_data, -auth=ID:PASSWD, -mime_header,\012	  -noredir, nntp URL handling (readonly), etc etc etc. RTFM\012\012	- no time for extensive testing, so lets bump revision, put \012	  this on the web and rely on these beta-test guys.\012	  Let''s coredump my alynx pine-folder 8)\012\012  Thu Aug 31 09:28:56 1995:\012\012	- first compiled version\012	- changed getstring behaviour to old ALynx style\012	  ([Del] deletes current char, [Backspace] moves left and erases)\012\012  Wed Aug 30 19:38:56 1995:\012  Tue Aug 29 20:13:51 1995:\012  Mon Aug 28 20:16:01 1995:\012  Sun Aug 27 13:38:56 1995:\012\012	- applied Lynx 2.4-FM (08-24-95) patches\012	  o 38 patchfiles for the ALynx-executable-sources\012	    resulting in 538 patches: 44 deletions, 173 appends, 321 changes\012	  o 30 patchfiles for the www-library-sources\012	    resulting in 248 patches: 10 deletions, 78 appends, 160 changes\012	- please read the file CHANGES for the new 2.4-FM (08-24-95)-features\012\012  Sun Jul 23 14:59:57 1995: @{b}ALynx_2.4-FM AmigaPort 1.29 (07/23/95)@{ub}\012\012	- added Josef Faulkners rexx-mail client for AmiTCP\012	- no more bugreports since 1.28 which require Amigaport fixes\012	  (other HTML-depended bugs must be fixed by Unix/VMS-Lynx)\012	- release this one on Aminet (comm/net)\012\012  Thu Jul 20 17:38:39 1995:\012\012	- added goodies/copystripper.rexx for saving files to different\012	  destination directories on some BBS setups\012	- another enforcerhit removed on ftp-abort (i begin to hate unix 8)\012\012  Mon Jul 17 18:53:37 1995: @{b}ALynx_2.4-FM AmigaPort 1.28 (07/18/95)@{ub}\012\012	- initialise DOWNLOADDIR to $HOME if not properly set up in lynx.cfg\012	- DOWNLOADDIR: in lynx.cfg now also accepts ENV-vars\012	- someone in news dared to compare ALynx'' filesize with AMosaic 8)\012	- added ENV-var support for mailcap files.\012	- added Index to ALynx.guide\012\012  Fri Jul 14 21:08:30 1995: @{b}ALynx_2.4-FM AmigaPort 1.27 (07/14/95)@{ub}\012\012	- fixed address error on 68000 Amigas\012	  (thanks go to Leo Davidson <[email removed]>\012	  && Matthias Barnutz <[email removed]> for mailing\012	  snapshot files)\012	- fixed enforcerhits on ftp-abort [someone should port enforcer\012	  to Unix & VMS 8-) ]\012	- added some spaces to "print to mail" header\012	- updated the guide\012\012  Fri Jul  7 13:54:31 1995: @{b}ALynx_2.4-FM AmigaPort 1.26 (07/07/95)@{ub}\012\012	- applied Lynx 2.4-FM (07-05-95) patches\012	  o 25 patchfiles for the ALynx-executable-sources\012	    resulting in 220 patches: 22 deletions, 97 appends, 101 changes\012	  o  7 patchfiles for the www-library-sources\012	    resulting in  50 patches:  0 deletions, 13 appends,  37 changes\012	- please read the file CHANGES for the new 2.4-FM (07-05-95)-features\012	- short: Netscape extensions (CENTER, BLINK, LEFT, RIGHT, ALIGN),\012	  treat ''>'' as both a close-double-quote and close-tag, [L]ists\012	  indicate the anchor NAME/ID if present, enable creation of links \012	  for all images (MAKE_LINKS_FOR_ALL_IMAGES in lynx.cfg, -image_links),\012	  LYK_IMAGE_TOGGLE-Key [*], downloadsstuff, <P>-stuff, bad HTML-stuff,\012	  TABLE form processing, Don''t show "[INLINE]" (Key-[, lynx.cfg:\012	  MAKE_PSEUDO_ALTS_FOR_INLINES, CLI: -pseudo_inlines), <HR WIDTH="50%">,\012	  connect() and select() bumped to 30,000 tries, etc. etc. etc.\012	- "Save to disk" now displays configured path or $HOME\012\012  Wed Jul  5 14:58:12 1995: @{b}ALynx_2.4-FM AmigaPort 1.25 (07/02/95)@{ub}\012\012	- discovered some weird bugs in curses.lib\012	- fixed curses.lib not to scroll consolewindow if a character is placed\012	  to position (COLS,LINES) (rightmost, lowest line). This might cause\012	  trouble with BBS-Installations. Please report, if weird or no scrolling\012	  occurs.\012	- removed all XWINDOWS-dependecies. If someone needs them, i''ll\012	  reimplement them. Just mail me 8)\012	- fixed colour-trouble on getstring()\012	- fixed options menu. input couldn''t be deleted\012\012  Mon Jul  3 03:56:17 1995: \012\012	- "save to disk" (D-Key) now saves to $HOME only, to allow other save-\012	  methods, use DOWNLOADER: option in "lynx.cfg" ! (enabled by default)\012\012  Sun Jul  2 16:20:46 1995:\012\012	- applied Lynx 2.4-FM (06-25-95) patches\012	  o 20 patchfiles for the ALynx-executable-sources\012	    resulting in 92 patches\012	  o  1 patchfile  for the www-library-sources\012	    resulting in 59 patches\012	- please read the file CHANGES for the new 2.4-FM (06-08-95)-features\012	- short:  new [L]ist command for creating an ACTIVATEable list\012	  of references (links) in the current document, DTD structures,\012	  forms DISABLED attribute, INPUT type "scribble", all ISO8859-1\012	  entities, FIG handling, onlinehelp HTML fixed, BQ, CAPTION,\012	  CREDIT, FIG, NOTE and OVERLAY structures, (HTML 3.0-stuff), etc etc.\012	- shortened some sleep()-calls from 2 to 1 seconds\012	- added check on existance of $HOME variable\012\012  Sun Jun 25 12:59:07 1995: @{b}ALynx_2.4 AmigaPort 1.24 (06/10/95) AS225@{ub}\012\012	- finished AS225 version\012	- added more types to ENV/Mosaic/mime.types\012\012  Sat Jun 24 20:27:03 1995\012\012	- working on AS225 version\012\012  Tue Jun 13 12:18:50 1995\012\012	- turned off requesters on local file access\012\012  Sat Jun 10 16:22:12 1995: @{b}ALynx_2.4 AmigaPort 1.24 (06/10/95)@{ub}\012\012	- applied Lynx 2.4 (06-08-95) patches (see CHANGES in dir "orig/")\012	- lynx.cfg-path configurable by env-variable\012	- cleaned up ALynx.guide\012	- resorted history\012	- created new ALynx/ distribution archive\012	- caution! files in "help_files" don''t exist anymore!\012	  path has changed to "lynx_help". please delete old path.\012	- fixed double headers in mail\012\012  Fri Jun  9 12:43:08 1995:\012\012	- applied Lynx 2.3-FM (05-29-95) patches\012\012  Wed Jun  7 22:42:19 1995: @{b}ALynx_2.3-FM AmigaPort 1.23 (06/07/95)@{ub}\012\012	- fixed reintroduced "optionsave-disabled"-bug\012\012  Mon Jun  5 19:56:21 1995: @{b}ALynx_2.3-FM AmigaPort 1.22 (06/05/95)@{ub}\012\012	- fixed filename-quoting\012\012  Mon Jun  5 14:14:12 1995: @{b}ALynx_2.3-FM AmigaPort 1.21 (06/05/95)@{ub}\012\012	- emergency-fix copy-command in download-menu\012	\012  Sun Jun  4 12:07:54 1995: @{b}ALynx_2.3-FM AmigaPort 1.20 (06/04/95)@{ub}\012\012	- fixed transfer abort (Z-key), shouldn''t lock up anymore\012	- fixed mail\012	- fixed document-refresh (^R-key)\012\012  Sat Jun  3 12:10:25 1995\012\012	- fixed temporary filenames created by mail\012\012  Fri Jun  2 15:43:37 1995: @{b}ALynx_2.3-FM AmigaPort 1.19 (06/02/95)@{ub}\012\012	- refixed commandline-supplied URLs for local files\012	- fixed -homepage=<localfile> option\012	- yup, release it now.\012\012  Thu Jun  1 13:20:49 1995\012\012	- fixed mail/mail-comments\012	- added MAILCOMMAND: in lynx.cfg to configure executable for mails\012	- lynx.cfg has new entries (BOLD_HEADERS,*_proxy,NO_DOT_FILES,\012	  GLOBAL_EXTENSION_MAP,PERSONAL_EXTENSION_MAP,MAILCOMMAND)\012	- ReSize 1.2 put in distribution \012	- refixed socket-connect\012\012  Wed May 31 18:03:07 1995: @{b}ALynx_2.3-FM AmigaPort 1.18 (05/31/95)@{ub}\012\012	  o 61 patchfiles for the ALynx-executable-sources\012	    resulting in 797 patches: 43 deletions, 259 appends, 496 changes\012\012  Sun May 21 12:40:36 1995\012\012	- upgrade to Lynx 2.3-FM\012	  please read the file CHANGES for the new 2.3-FM-features\012	   short: ftp, search within document, -show_cursor, LYK_REMOVE,\012	   memory leak fixes, -cfg switch, href parsing, -selective,\012	   -nobrowse, -localhost, Accept-Language headers, proxy via\012	   lynx.cfg, etc etc etc.\012\012	  o 24 patchfiles for the www-library-sources\012	    resulting in 311 patches: 15 deletions, 114 appends, 182 changes\012\012  Mon May 15 13:15:34 1995: \012\012	- cleaner statusline with weird https \012	  (found them on Spumonis webpages 8)\012\012  Sat May 13 15:32:25 1995\012\012	- added TEMPDIR: in Lynx.cfg for low-mem-users\012\012  Thu May 11 18:16:19 1995: @{b}ALynx_2.3.7 AmigaPort 1.17 (05/11/95)@{ub}\012\012	- emergency-fix on forms-input\012\012  Wed May 10 11:56:50 1995: @{b}ALynx_2.3.7 AmigaPort 1.16 (05/10/95)@{ub}\012\012	- fixed Jump-feature (jumpfile wasn''t closed, etc)\012	- I nearly got braindead on sc.lib:stat(). better use usr.lib:stat()\012	- i found several problems with incorrect html-files. Don''t know\012	  how to fix them.\012	- several people reported bugs like "**** HTAccess: Internal software\012	  error.". This might got fixed with 2.3.7. Please check.\012	- added PRINTER:-entry in lynx.cfg\012	- small errorchecks in ReadCfg()\012\012  Tue May  9 18:53:22 1995: @{b}ALynx_2.3.7 AmigaPort 1.15 (05/09/95)@{ub}\012\012	- fixed ANSI-Mode-"run <NIL: >NIL: ALynx"-bug (reported by N''Kognito)\012	  (yup, this isn''t very usual, but it crashed 8)\012	- refixed options-screen\012	- reapplied some patches, which got lost on my saturday patch-session\012	- fixed NULL-pointer strcmp()-bug for homepage (M-key)\012	  (Hey! SAS/cpr/Enforcer/findhit should be ported to VMS/Unix 8)\012	- fixed typo in "help_files/keystroke_commands/keystroke_help.html"\012	  (this should bump the versionnumber to ALynx''95 ;-) )\012	- made new "show-keymap" (K-key) work\012	- "remove from bookmark" now works again\012	- refixed options-popup-form (my box() is nicer 8-)\012	- lynx.cfg wasn''t closed after reading.\012\012  Sun May  7 20:26:15 1995: @{b}ALynx_2.3.7 AmigaPort 1.14 (05/07/95)@{ub}\012\012	- yup, released it now.\012\012  Sat May  6 14:03:01 1995: @{b}ALynx_2.3.7 upgrade@{ub}\012\012	- I just discovered that I ported Lynx 2.3.0 . Ok, this IS hard work.\012	- created/modified\012	  o 80 patchfiles for the www-library\012	    resulting in 448 patches: 37 deletions, 210 appends, 201 changes\012	    105 sourcefiles with approx. 980 kb\012	  o 48 patchfiles for the ALynx-executable\012	    resulting in 890 patches: 54 deletions, 267 appends, 569 changes\012	    81 sourcefiles with approx. 600 kb\012	  o including curses.lib (85 files/180kb) the overall needed sources\012	    add to ~270 sourcefiles with 1.7 MB 8))\012	- this heavy patching might introduce new AND old bugs but there\012	  are lotsa bugs fixed (concerning the HTML-stuff)\012	- cleaned up BOOL vs BOOLEAN\012	- refixed "looping-bug" (Unix-Lynx still has this one 8) )\012	- fixed Version-strings (User-Agent: field) (Thanks Mike Meyer)\012	- updated the distribution-archive\012	- the ALynx-Homepage has been fixed to support lha-files. (Thnx Vito)\012\012  Fri Apr 28 20:04:06 1995: @{b}ALynx_2.3 AmigaPort 1.13 (04/29/95)@{ub}\012\012	- fixed scrolling-bug in ansi-mode in options-statusline\012	- small layout-fixes\012	- NEW getstringfunction. now allows cursorediting.\012\012  Wed Apr 26 15:38:30 1995: @{b}ALynx_2.3 AmigaPort 1.12 (04/26/95)@{ub}\012\012	- curses.lib now supports MAXLINES ($LINES) upto 250.\012	- added support of public-screens and screenmodes (see ENV:CURSESTYPE)\012	- no "Please insert Volume INET:..." anymore. (Thnx ZZA) \012\012  Fri Apr 21 20:02:01 1995: @{b}ALynx_2.3 AmigaPort 1.11 (04/21/95)@{ub}\012\012	- ARGH! found a bug concernig COLS > 80 && CURSESTYPE = SCREEN\012	- fixed domain-problem (fixed it the hard way 8)\012	- hopefully fixed the "optionsave-disabled"-bug 8)\012	  (and other related stuff)\012\012  Fri Apr 21 15:52:18 1995: @{b}ALynx_2.3 AmigaPort 1.10 (04/21/95)@{ub}\012	( my birthday-release 8)) )\012\012	- created "ReSize"-tool to set local/global env-vars for COLS & LINES\012	  (can be found in ReSize.lha in this distribution)\012	- curses.lib now supports MAXCOLUMNS ($COLS) upto 160\012	- finally found this annoying "looping"-bug. Don''t close(0)!\012	  [same procedure as every bug, james: "not my fault 8)"]\012	- fixed badly set ''\\n'' on alerts\012\012  Wed Apr 19 21:08:09 1995:\012\012	- fixed loading/saving of "ncsa-xmosaic-hotlist-format-1"-bookmarks\012	  now it is possible to use AMosaic''s bookmark/hotlist-files: \012	  just insert "bookmark_file=envarc:mosaic/.mosaic-hotlist-default"\012	  in ".lynxrc" or "lynx.cfg". Thanks XS.\012\012  Tue Apr 18 15:54:59 1995: @{b}ALynx_2.3 AmigaPort 1.9 (04/18/95)@{ub}\012\012	- argparsing for local files fixed. "ALynx SYS:foo/bar.html" now\012	  works fine. There still will be problems on filenames like\012	  "FILE://blah/blush.html". (Assignment "file:" + 2 dirs up +\012	  down 1 dir "bla" + file "blush.html")... who cares 8)\012	- fixed HD-crash of my 120 MB source-partition. phew!\012	- fixed several stringoverflows on strncpy()\012	- hopefully fixed the "looping"-bug\012\012  Mon Apr 17 14:35:23 1995: @{b}ALynx_2.3 AmigaPort 1.8 (04/17/95)@{ub}\012\012	- fixed bad scrolling on multi-popupoptions\012	- tolower(URL) in HTParse wasn''t such a good idea\012	- print to file now works\012	- print to screen now works\012	- fixed bad SAS/C getenv()-behaviour (thnx Tau)\012\012  Sun Apr 16 15:23:38 1995: @{b}ALynx_2.3 AmigaPort 1.7 (04/16/95)@{ub}\012\012	- finally found colorbug in curseslib. fixed it.\012	- fixed another ''\\n''-related bug in curseslib.\012	  (hmmm, does anyone know, how to display the backslash\012	   in an amigaguide-document ?????)\012	- cleaned up colors \012                 ANSI-mode               Screen-mode\012	  ------------------------------------------------\012	  text: <ESC>[0m    (WB-black)      white\012	  bold: <ESC>[32m   (WB-greyblue)   yellow\012	  link: <ESC>[33m   (WB-white)      green\012\012	  since now, it is only possible to change ansicolors for\012	  bold/links. (ENV:CURSESANSICOLORS). this will be done\012	  in future by .lynxrc! More colors/attributes to come!\012\012  Sat Apr 15 16:44:27 1995:\012\012	- (internal) added some prototypes\012	- added colorsupport and revealed nasty curses-colorbug\012\012  Sat Apr 15 01:00:23 1995:\012\012	- added new SAS 6.55-ENV:TZ-code\012\012  Fri Apr 14 14:51:13 1995: @{b}ALynx_2.3 AmigaPort 1.6 (04/14/95)@{ub}\012\012	- lynx.cfg searchorder: "AMITCP:db/" -> "INET:db/" -> "PROGDIR:"\012	- hopefully fixed wgetch()-looping-problem\012	- fixed pathname on download (D-key)\012	- argh. New HTParse.c (thanks Michael) cleaned the URL to lowercase\012	  the hostname. This also converted "LYNXDOWNLOAD://Method=-1" to\012	  "LYNXDOWNLOAD://method=-1". Well... strstr(line,"Method=") didn''t\012	  like that 8)\012	- added filename-checks on user-defined local-filenames\012	- download (D-key) seems to work now\012	- fixed typo on -restrictions= helplist. must be "option_save"\012	  (still can''t find the "options-save disabled"-bug)\012	- abort transfer now works (Z or ^G)\012	- oops. there is no "/bin/rm" is it ? 8))\012\012  Wed Apr 12 21:08:15 1995: @{b}ALynx_2.3 AmigaPort 1.5 (04/12/95)@{ub}\012\012	- fixed pathname for strcat($HOME,".lynxrc")\012	- fixed same problem at several other places. Replaced them with\012	  dos.library\\AddPart()\012	- emergency-fix on "block cut''n''copy"-typo\012\012  Wed Apr 12 19:09:51 1995: @{b}ALynx_2.3 AmigaPort 1.4 (04/12/95)@{ub}\012\012	- fixed some versionstrings\012	- stacksize automagically bumped to 10000 bytes\012	- cleaned some code\012\012  Tue Apr 11 04:01:06 1995:\012\012	- fixed control-R-refresh\012	- fixed History-Page-URL (backspace-key)\012	- fixed Information-Page-URL (=-key)\012	- fixed Printing-Options-Page-URL (P-key)\012\012  Tue Apr 11 01:50:41 1995: @{b}ALynx_2.3 AmigaPort 1.3 (04/10/95)@{ub}\012\012	- finally found the external bug. curses.lib didn''t support\012	  endwin/initscr-sequences.\012\012  Mon Apr 10 14:17:59 1995: @{b}ALynx_2.3 AmigaPort 1.2 (04/10/95)@{ub}\012\012	- fixed cursor-hiding in lower right corner (N`Kognito@#amiga.IRC)\012	- changed the default-curses-startup to ANSI.\012	- added ENV:CURSESANSICOLORS to map certain colors in the shellwindow\012	- lynx.cfg first searched in "AMITCP:db/" on failure in "PROGDIR:"\012	- ReadMe.Amiga moved to ALynx.guide\012	- Kludge in libwww to work with local files. Has ANYBODY a ported\012	  libwww by hand, which handles URLs like\012	  "file://localhost/S:startup-sequence" ? Any hints welcome.\012	- added AmigaDos-$VER-string\012\012  Sun Apr  9 16:48:48 1995: @{b}ALynx_2.3 AmigaPort 1.1 (04/09/95)@{ub}\012\012	First Beta-beta-beta-test-Release on IRC\012\012	**************************************************************\012	The first to report where @{"this" link FUN} is from gets mentioned here 8)\012	**************************************************************\012\012@endnode\012','\012',char(10)),'{"TYPE":"SCREEN"}','auto-added',315835,8,0,NULL,NULL,'alynx131','scan',1780048403);
