INSERT INTO door_catalog VALUES('amb_v099','AMB-V099.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AMB-V099.LHA','vote','XIM','vote',NULL,NULL,'AMB','\___  /  \/     _/_|__|______ \  |  |_ /  /  \ \  / |  \  \  | __|| \ \ | __/_ \_____/__\/  |_____/  |__  \  \  |_____\',replace('_______/\  _______ .__._______._____.\n\___  /  \/     _/_|__|______ \  |  |_\n/  /  \ \  / |  \  \  | __|| \ \ | __/_\n\_____/__\/  |_____/  |__  \  \  |_____\\n--++------|__|-----|__|--\__\_|\ |---++--\n  || ________p_r_e_s_e_n_t_s____\|__ ||\n  .||                               ||!\n   !| TRANCE!VOTE V0.99     [XIM]   |:.\n    |CODE: COSMIC /o\ DEZIGN: RAMIS!|\n-cT!|_______________________________|`96-\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 19:58:28  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',8208,4,0,NULL,NULL,'amb_v099','scan',1780048403);
INSERT INTO door_catalog VALUES('amb_v100','AMB-V100.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AMB-V100.LHA','vote','XIM','Relyscully.exe',NULL,NULL,'AMB','\___  /  \/     _/_|__|______ \  |  |_ /  /  \ \  / |  \  \  | __|| \ \ | __/_ \_____/__\/  |_____/  |__  \  \  |_____\',replace('_______/\  _______ .__._______._____.\n\___  /  \/     _/_|__|______ \  |  |_\n/  /  \ \  / |  \  \  | __|| \ \ | __/_\n\_____/__\/  |_____/  |__  \  \  |_____\\n--++------|__|-----|__|--\__\_|\ |---++--\n  ||16/02/97_p_r_e_s_e_n_t_s____\|__ ||\n  .||                               ||!\n   !|   TRANCE!VOTE V1.00   [XIM]   |:.\n    |CODE: COSMIC /o\ DEZIGN: RAMIS!|\n-cT!|_______________________________|`96-\n','\n',char(10)),'vote.doc',replace('\n\n              .---------------------------------------------.\n              |                                             |\n              |      TRANCE!VOTE 1.oo BY COSMiC^AMB^RYL     |\n              |                                             |\n              `---------------------------------------------''\n\n\n                                 HISTORY:\n                            ==================\n\n\nSECOND BETA (24/12/96):\n\nFixed a bug at BOARDS prompt, a user must specify entries\nwith at least 5 characters or the door quits itself :)\nthe next version should kick the lamer :)\n\nLAST BETA   (14/01/97):\n\nfucking fast''n''cool dezign from ramis added and some output speed-ups done\n\nVERY LAST BETA (15/01/97):\n\nnasty bugs :) fixed da dezign bugs and added a Delay(120) at the end\nof the door...personalized version has this delay removed and has some\nother features...\n\nFIRST RELEASE VERSION 0.99 (15/01/97):\n\nremoved this lame vote.dat instead we use a single file for each user coz\nit is better to handle if some guys vote three or four times :)\noutput was increased about 100% ! have phun and use this not the old version\n\nFINAL RELEASE VERSION 1.00 (16/01/97):\n\nadded some checks for datafiles, dirs, allready-voters and\nshort-blinking version info !\nremoved user-fake procedure, so if a user don''t wanna fill out all\nfields, he just presses return !\nspeed: 220% of the first version ! only 7kb !\nmade the first coding on ACADEMY CHARTS (webpage with results made by fLi7e)\n\n\n\n                             HOW TO INSTALL !\n                         ========================\n\n       Edit your SYS.CMD, SYSCMD/VOTE or FAME:SETTINGS/DOORS/blabla\n                    (if you are sysop u SHOULd know it)\n   and install this door as XIM, MULTINODE and your usual access level!\n             Then open a shell and type "MAKEDIR BBS:ACADEMY"\n                     (where the datafiles are kept)...\n      start this door and test it, this version should be bugfree :)\n           I think, this door is useful only for ACADEMY CHARTS,\n  if u need a configurable voter, contact me and i''ll try to code it :-)\n\n\n\n        THIS DOOR WAS DEZIGNED FOR ACADEMY AWARD, A NEW CHART MAG !\n\n                   But not the uploadbytes will count !\n          all users can vote for their favorites so no faking ;)\n\n THIS IS ONLY A BETA ! WE HAVE GOT THE FOLLOWING BOARDS FOR THIS PROJECT:\n\n                               CENTRAL PARK\n                                 CRAP TOWN\n                                DEATHFIELD\n                                 DATASTORM\n                                TRASH CITY\n                                MOST WANTED\n                                ANTARCTICA\n                               DOOR TO HELL\n\n       if you wanna join as sysop/editor/anything-else then contact\n                us on irc : #amielite  -  #ambient  -  #sts\n                         or on one of these boards...\n\n\n                             EDITORS (so far):\n\n                       CYBER - ZEUS - COSMIC - fLi7e\n\n academy will be released as plaintext, exefile, amigaguide and webpage !\n get it ! some cool tunes from nop and a special about da turkish scene !\n\n\n                bye mates and keep da amiga scene alive 8-)\n\n\n','\n',char(10)),NULL,'auto-added',12260,3,0,NULL,NULL,'amb_v100','scan',1780048403);
