___/ ¦__ \___ \\r\n /   /  \ \__  \___  \  |   |   \  _/  __/ /    /\__  \  |¦   | /  \_|  \\r\n/  \/    \_ \   \ !   \_|   !    \_\    \_     /   \   \ ||   |·    /|   \_\r\n\___|     ___\  /__    /l________ /_\    /__  /_____\  / |¦   |    /_|    /\r\n    l____/-A×E\/  \___/_!       \/   \  /   \/       \/__|:   ¦__ /  l___/\r\n       ______            _____        \/      :    ____   ·   : \/\r\n    ___)     \___________)    \__________:___ ¦____)   \__________\r\n    \    _______     _______    \___    ____/ |\_____   \______   \\r\n   /\___   \/        |    _)    \/       ¦    |/    |    \    |    \\r\n _/    !    \        |    \      \_      |    |     !     \   |     \\r\n \______     \___    |_____\      /___   |    ¦            \  |      \_\r\n       \______/ \____!      \    /   \___|    :________     \_|       /\r\n                             \  /        ¦    ·       \______/|      /\r\n   YOUVE HEARD ABOUT IT!      \/         :    ·               l_____/\r\n       \r\n         MASTURBATiON STATiON AMIGA/PC/CONSOLE/ASCII-ANSI/C64        \r\n               Telnet: bbs.masturbationstationbbs.com\r\n\r\n           UPLOAD DATE: 08-23-15  TIME: 21:47:29  ON NODE: 1\r\n\r\n  UPLOADER: Black Beard            LOCATION: mASTURBATIONSTATIONBBS.COM\r\n\r\n','\r',char(13)),'\n',char(10)),NULL,NULL,3601,1,0,NULL,NULL,NULL,'scan',1780048403);
INSERT INTO door_catalog VALUES('ami_dead','AMI-DEAD.LZH','~/Code/amiexpress_doors/Archives/AmiExpress/AMI-DEAD.LZH',NULL,'XIM','-=****************************************=-',NULL,NULL,'AMI','COMMODORE IS DEAD! This is a text file explaining the recent financial collapse of',replace(replace('-=****************************************=-\r\n              COMMODORE IS DEAD!\r\n\r\n       This is a text file explaining\r\n       the recent financial collapse of\r\n    Commodore, the company that makes the\r\n          Amiga and C64 computers.\r\n\r\n               written by: MAT\r\n-=****************************************=-\r\n-=[COURIED BY]=ð=[SID JUSTICE HYBRID/SWE]=-\r\n','\r',char(13)),'\n',char(10)),'AMI-DEAD.TXT',replace(replace('A little note to all Commodore (Amiga/c64) users. \r\n\r\nThe Commodore Amiga is now officially dead in Australia and the European\r\nand American divisions of COMMODORE are expected to declare bancrupsy at\r\nany time now - if they have not done so already.\r\n\r\nBelow is the exact quote taken from the Melbourne AGE newspaper dated\r\n15th feb 1994 reporting of the financial collapse of the Amiga and CBM\r\n\r\n------------------------------------------------------------------------\r\n\r\nARTICLE TITLE :  Commodore sell-off is a sad footnote\r\n\r\nAUTHOR        :  GARETH POWELL \r\n\r\nSUBJECT       :  The demise of one of the innovators of\r\n                 the personal computer industry.)\r\n\r\n\r\nTHE LATEST chapter in the Commodore saga comes as no great surprise. Last\r\nweek, the company Ferrier Hodgson was appointed administrator of Commodore\r\nAustralia after Commodore directors considered their position and the \r\ncompany''s financial problems.\r\n\r\nAccording to Max Donnellt of Ferrier Hodgson, Commodore was unable to service\r\na bank bill due to roll over at the end of this week. The company is to be\r\nsold.\r\n\r\nCommodore, founded by Mr Jack Trameil in the ''50s, was initally invovled\r\nwith typewriters. Operations were financed largely from Canada, mainbly by the chairman\r\nC. Morgan Powell.\r\n\r\nIn 1965, three years after the group''s public listing, Mr Powell was\r\ncriticised by a Canadian royal commission for acts of "rapacious and\r\nunprincipled management". He died before the commission finished it''s report.\r\n\r\nWhile Commodore got a clean bill of health from the commission, Mr Trameil\r\nsubsequently found it difficult to get finance. To the rescue came Canadian\r\nfinancier Irving Gould, who bought in heavily.\r\n\r\nIn the early days, the calculator boom supported Commodore, but in the\r\ndownturn of 1975 the company suffered a loss of $US55 million on sales\r\nof $US50 million. It switched to computers and profits soared.\r\n\r\nIn 1985, Mr Trameil left Commodore amid much bitterness and recrimination.\r\nSince then, the company''s fortunes have been, to say the least, erratic,\r\nalthough in the Amiga it had a personal computer that was several years ahead\r\nof it''s time.\r\n\r\nAmiga was not originally designed  by Commodore. It came froma California\r\ncompany of longhairs who wanted to make the ultimate computer.\r\nAnd that was what they did.\r\n\r\nWhen it was launched, the Amiga had graphics superior to any other\r\ncomputer on the market, a super-fast Motorolla 68000 and wondrous sound.\r\nIt was also the first true multi-tasking personal computer. It is a great\r\nsadness that it has all come to this.   Commodore USA and Commodore European\r\ndivisions are expected to be making an announcement shortly as both are\r\nentering into Chapter 11 protection from creditors.  Irving Gould was quoted\r\nas ''wishing to end this sad chapter as soon as possible'' so that he might get\r\non with other investments that have not cost him so dearly in time and money.\r\n\r\n*****************************************************************************\r\n\r\n','\r',char(13)),'\n',char(10)),NULL,NULL,5468,5,0,NULL,NULL,NULL,'scan',1780048403);
INSERT INTO door_catalog VALUES('ami_fido','AMI-FIDO.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AMI-FIDO.LHA','cf','XIM','16',NULL,NULL,'AMI','+                                          + +         Amiexpress FIDO-MAILER           + +                                          +',replace('+==========================================+\n+                                          +\n+         Amiexpress FIDO-MAILER           +\n+                                          +\n+ 100% version, configured and working     +\n+ with all addictional programs like:      +\n+ TrapDoor, TrapToss, TrapList...etc.      +\n+ Included sample configs and documentation+\n+ Just copy this to your HD and check paths+\n+ 100% Backdoors free ! Working on all type+\n+ of Amiga.                                +\n+ ONE & ONLY FidoNet mailer for /X v.3.+   +\n+==========================================+\n','\n',char(10)),'AX-Fido.GUIDE',replace('@Database "Ami-X_Fido.guide"\012@Master "Ami-X_Fido"\012@Remark $VER: /XF-Guide 1.0\012@AUTHOR "Tycoon & Killraven"\012@(C) Copyright 1993 by Tycoon, all rights reserved.\012@Width 80\012@Index Index\012\012@Node Main "Guide To Ami-X FIDO -  © 1993 by TyCooN"\012                        __  __        ____ __ __   ____\012                       /  \/ / ____  / __// //  \ /   /\012                      / />  < /___/ / __// // / // / /\012                     /_//_/\_\     /_/  /_//___//___/\012 \012                  WELCOME TO AMI-X FIDO - MADE BY TYCOON\012\012                         @{" Introduction           " link Introduction}\012                         @{" What is FIDO?          " link WhatIsFido}\012                         @{" Registration!          " link Registration}\012\012                         @{" Requirements           " link Requirements}\012                         @{" Installation           " link InstallProc}\012                         @{" Directory Structure    " link DirStructure}\012                         @{" Program use in /X      " link ProgramUse}\012\012                         @{" Support BBSs           " link SupportBBS}\012                         @{" If you need help       " link IfYouNeedHelp}\012                         @{" Ami-X Fido NetWork     " link AXF}\012\012                         @{" Acknowledgements       " link Acknowledgements}\012@EndNode\012\012@Node Introduction "Introduction - © 1993 by Tycoon"\012\012                                 WELCOME!\012                                 --------\012\012   Welcome to Ami-X Fido, programmed by Tycoon of the @{"Channel-X BBS" link Channel-X}. This\012   great door enables you, the sysop and user, to read/write all kinds of\012   mail spread through fido-compatible networks and UUCP.\012\012   With AXF users can write mail to friends on other systems without even\012   being a member of that system. The only requirement is that both BBSs\012   are a member of the same network. And if the network is big enough, you\012   can even write/read messages from the other side of the world!\012\012   You may have thought that it wasn''t possible with @{"Ami-X" link Ami-X}, but now the\012   impossible has become possible! No more empty conferences, no longer\012   you will have a 1001 different conferences on your hd! And this all\012   because of AXF!\012\012                              WHY AMI-X FIDO?\012                              ---------------\012\012   Since /X 3.0 there is a possibility to exchange mail between different\012   bulletin board systems. This was done via conferences without file \012   bases. I did not like this kind of system, I wanted a fido compatible\012   system so I could exchange mail with existing systems who don''t run on\012   a /X system and that way connect to existing mail systems such as the\012   fido network and some local networks like NLA, AMY and BosNet.\012\012   I hope you will find great use in this program and enjoy the world of\012   international mail the same way I do! Have fun!\012\012                                                   -Tycoon/Channel-X\012\012                             @{" Back to Main Menu " link Main}\012\012@EndNode\012\012\012@Node DirStructure "Directory Structure of AXF - © 1993 by Tycoon"\012\012   MAIL: -+--@{" BIN " link BIN}-+--@{" Trapdoor " link TrapDoor}      BBS: -+--@{" Commands " link bbs.cmd}-+--@{" BBS.CMD   " link BBS.CMD}\012          |        +--@{" Traptoss " link TrapToss}            |             `--@{" SYSOP.CMD " link bbs.CMD}\012          |        +--@{" Trappoll " link TrapPoll}            |\012          |        +--@{" Trapscan " link TrapScan}            +--@{" Fidonet " link FidoNet}--+--@{" User " link User}\012          |        +--@{" Traptell " link TrapTell}            |             |\012          |        +--@{" Trapcall " link TrapCall}            |             +--@{" Fido-con.exe   " link Fido-Con.EXE}\012          |        +--@{" Skytick  "  link SkyTick}            |             +--@{" Fido-del.exe   " link Fido-Del.EXE}\012          |        `--@{" Skyfreq  "  link SkyFreq}            |             +--@{" Fido-del.rexx  " link Fido-Del.exe}\012          +--@{" Inbound      " link Inbound}                 |             +--@{" Fido-hgh.exe   " link Fido-con.EXE}\012          +--@{" Nodelist     " link NodeList}                 |             +--@{" Fido-mail.rexx " link Fido-Mail.REXX}\012          +--@{" Outbound     " link OutBound}                 |             +--@{" Fido-main.rexx " link Fido-Main.REXX}\012          +--@{" Scripts      " link Mailer}-+--@{" Mailer " link Mailer}     |             +--@{" Fido-ran.exe   " link User}\012          +--@{" Ticks        " link Nodelist} `--@{" Poll   " link Mailer}     |             +--@{" Fido-scan.rexx " link Fido-Mail.REXX}\012          +--@{" Fido.CFG     " link Fido.CFG}                 |             +--@{" Fido.history   " link Fido.History}\012          +--@{" Tick.CFG     " link Tick.CFG}                 |             +--@{" Fidonet.cfg    " link FidoNet.CFG}\012          +--@{" TrapDoor.x   " link TrapDoor.x} (MultiNode)     |             `--@{" UUCP-con.exe   " link UUCP-CON.EXE}\012          +--@{" TrapDoor.CFG " link TrapDoor.CFG}                 |\012          +--@{" TrapList.CFG " link TrapList.CFG}                 `--@{" Bullxx.txt " link Bullxx.TXT}\012          +--@{" TrapDoor.Key " link TrapDoor.Key}                \012          `--@{" TrapToss.Key " link TrapToss.Key}                 @{" Back To Main " link Main}\012@endnode\012\012@Node Channel-X "The Channel-X BBS Ad - © 1993 Tycoon"\012\012                        .-------------------------.\012                        |   C H A N N E L  -  X   |\012                        `-------------------------''\012 \012                  ø¤°~¬¯ AMI-X FIDO SUPPORT CENTRE ¯¬~°¤ø\012 \012                               SysOp: TyCooN\012                           Co: Killraven/DeSiRe\012 \012                        We Are Open 24 Hours A Day!\012                  2 Nodes With USR Modems (16k8/14k4 DS)\012 \012                  ø¤°~¬¯ TO ORDER: +31-2290-62244! ¯¬~°¤ø\012 \012                         REGISTRATION COSTS US$10!\012\012\012                             @{" Back to Main Menu " link Main}\012\012@EndNode\012\012@Node Ami-X "Ami-eXpress Support BBS'' - © 1993 Tycoon"\012\012                 ø¤°~¬¯  AMI-X WHQ SALES & Support  ¯¬~°¤ø\012\012              LightSpeed Technology- USA ----- 1-305-964-4263\012\012\012                 ø¤°~¬¯  Ami-eXpress Support BBSen  ¯¬~°¤ø\012\012              The Last! Amiga BBS -- USA ----- 1-305-456-0126\012              The Northern Palace -- DENMARK --  +45-31744704\012              Global Chaos BBS ----- GERMANY --  +49-82311068\012              Heart of Nowhere ----- ITALY --- +39-2-97291781\012              The To\X/er ---------- UK -------- +0253-857553\012              ThunderStruck -------- SF ------ +358-71-345294\012\012\012\012                             @{" Back to Main Menu " link Main}\012@EndNode\012\012@Node SupportBBS "The Support BBSs Around The Globe - © 1993 Tycoon"\012\012              ø¤°~¬¯ THE SUPPORT BBSs AROUND THE GLOBE ¯¬~°¤ø\012\012\012             CHANNEL X (SALE-BBS)... HOL ..... +31-229-062-244\012             Last! Amiga BBS........ USA .....  +1-305-456-0126\012             Nubis.................. GER ..... +49-617-294-0072\012             Beyond Infinity #1..... CAN .....  +1-416-461-6702\012             Beyond Infinity #2..... CAN .....  +1-416-461-9101\012             Mamba BBS.............. POL ..... +48-223-674-43\012\012\012             ø¤°~¬¯ THE BETA-TEST BBSs AROUND THE GLOBE ¯¬~°¤ø\012\012             Last Outpost........... HOL ..... +31-721-576-82\012             Last! Amiga BBS........ USA .....  +1-305-456-0126\012             Nubis.................. GER ..... +49-617-294-0072\012             Beyond Infinity #1..... CAN .....  +1-416-461-6702\012             Beyond Infinity #2..... CAN .....  +1-416-461-9101\012             Mamba BBS.............. POL ..... +48-223-674-43\012\012                 All boards support US Robotics HST mode.\012\012\012                             @{" Back to Main Menu " link Main}\012@EndNode\012\012@Node Requirements "Requirements for Ami-X Fido - © 1993 Tycoon"\012\012                               REQUIREMENTS\012                               ------------\012\012      · Registered Version Of Ami-Express 2.x or 3.x ¹\012      · Registered Version Of Ami-X Fido ²\012      · Registered TrapDoor & TrapToss ³\012      · An Amiga with at least an 68020 processor and HD\012\012      ¹ Support will ONLY be given to people who have a REGISTERED version\012        of Ami-X 2.x or 3.x. I am very strict in this, Joseph Hodge has\012        put a lot of work in Ami-Express so register yourself! You can\012        register yourself at @{"LightSpeed Technologies" link LightSpeed}.\012\012      ² Obviously, support will ONLY be given to REGISTERED users of AXF.\012        I do not ask much money for it, all I ask of you is to register\012        yourself. For registration, call @{"Channel-X" link Channel-X}.\012\012      ³ Although there is a shareware version of TrapDoor, if you use it\012        often, please register! TrapToss is not available in ShareWare\012        version so you''ll have to register for that one too!\012        Register at @{"The Austrian Amiga Developers Association" link TrapDoorReg}.\012\012\012\012                             @{" Back to Main Menu " link Main}\012@EndNode\012\012@Node IfYouNeedHelp "If You Need Help - © 1993 Tycoon"\012\012                        What To do If You Need Help\012                        ---------------------------\012\012      You can get all the help you need at a @{"/XF Support BBS" link SupportBBS} and if\012      they can''t help you you must contact @{"Channel X" link Channel-X}, the WHQ and SALE\012      BBS of /X-FIDO.\012\012      Some rules before calling for help:\012      · Read the doc, this really helps! This door is very complex so this\012        time you really need to read the doc! No easy to install door, sorry.\012      · You must be a registered Sysop, otherwise NO support.\012      · Write down your troubles so we can help you easy and quick.\012\012\012                             @{" Back to Main Menu " link Main}\012@EndNode\012\012@Node AXF "/X-Fido Network - © 1993 Tycoon"\012\012                            Ami - Fido - Network\012                            --------------------\012\012      There is a Network between all the ami-express bbs'' that uses the\012      fidodoor. This is for bugreports, new features.  At this moment\012      the following areas are included:\012\012       - /XF Sale         (For sale/Wanted)         (for the users)\012       - /XF General      (General discussions)     (for the users)\012       - /XF Cosysops     (CoSysOp Area)            (for (co)sysop)\012       - /XF Sysops       (For sysops only, swap\012                           info about users, files,\012                           fakes, partys and more!) (for sysops)\012       - /XF Beta         (Bug-Reports              (for beta-testers)\012\012\012                             @{" Back to Main Menu " link Main}\012@EndNode\012\012@Node TrapDoorReg "Registration Information about TrapDoor & TrapToss - © 1993 Tycoon"\012\012                Registration Info about TrapDoor & TrapToss\012                -------------------------------------------\012\012      TrapDoor is a copyrighted product that has been made available\012      to you under the concept of "Shareware". It has never been, nor\012      will it ever be in the "Public Domain". You are granted a\012      limited license in order to evaluate these programs. If, after a\012      3 or 4 week period of evaluation, you find that TrapDoor suits\012      your telecommunication needs, please register. By cooperating\012      with this concept you help to ensure continued development of\012      this product.\012      \012      Registered users will be shipped a disk with the latest\012      release version of TrapDoor together with a keyfile. This\012      keyfile, once copied to your system, will disable the ShareWare\012      reminders that always open when you start or quit TrapDoor.\012      \012      Site license information for commercial and government use as\012      well as source code licenses can be obtained directly from the\012      authors.\012      \012      No person(s) or businesses other than the authors are\012      authorized to accept any registration or distribution fees in\012      any form whatsoever, except the official registration and\012      support centers as specified by the authors. The only people who\012      will be acknowledged as registered users are those who have sent\012      ATS 350,- (plus another ATS 150,- if you send foreign cheques or\012      money orders) to:\012\012                           TrapDoor Development\012                            Maximilian Hantsch\012                      Matzleinsdorfer Platz 3-4/3/10\012                                A-1050 Wien\012                             Austria / Europe\012\012      As one of the safest and possibly easiest ways to send in your\012      registration fee from other countries, we would suggest an\012      international postal money order -- your local post office will\012      happily provide you with more information about this. It also\012      has the advantage that the exchange of currencies is handled\012      automatically and the surcharge is negligible.\012      \012      Alternatively, you can either send us a Eurocheque payable to\012      Maximilian Hantsch in Austrian Schillings or have your bank\012      transfer the registration fee to the "Österreichische\012      Postsparkasse (PSK)" (BLZ 60000), account 6.777.234, "Maximilian\012      Hantsch". Beware: international transfers via banks are rather\012      expensive.\012\012\012                             @{" Back to Main Menu " link Main}\012@EndNode\012\012@Node WhatIsFido "Information about Fidonet - © 1993 Tycoon"\012\012                            Information about Fidonet\012\012\012                       @{" 1. FidoNet                        " link fido1}\012                       @{"    1.1. The Structure of FidoNet  " link fido2}\012\012                       @{" 2. Becoming a Point               " link fido3}\012                       @{"    2.1. Finding The Tools         " link fido3}\012                       @{"    2.2. Deeper Understanding      " link fido4}\012                       @{"    2.3. A Little Diagram          " link fido5}\012                       @{"    2.4. Installing The Mess       " link fido6}\012@ENDNODE\012\012@Node fido1 "Information about Fidonet - © 1993 Tycoon"\012\012                    GENERAL INFORMATION ABOUT FIDO-NET\012                    ----------------------------------\012\012  1. FidoNet\012\012     Back in 1984, the sysop of a private bulletin board system in\012     the United States of America, Tom Jennings, had an idea:  He \012     felt it would be nice if users of his system could send messages\012     not only to each other, but also to users of a friend''s bbs.\012     With this in mind, he sat down and started programming... After\012     a short while, the first FidoNet mailer and bbs, "Fido", was\012     born. At night, "Fido" would pack all the messages destined for\012     other systems, call them and deliver the mail. There, another\012     "Fido" would happily accept the mail packets, unpack them and\012     pass the messages on to the individual users of that system.  \012\012     The idea received massive feedback, and more and more sysops\012     wanted to take part in the big mail exchange. In just three\012     months about 50 other systems joined in, and in the beginning of\012     1985 there already were 150 "FidoNet nodes". FidoNet was born.  \012\012     The initial software was not comfortable enough for a number\012     of programmers, and so countless utilities and tools arose, to\012     make mail transfer more efficient and thus, cheaper. Nowadays,\012     we find lots of different FidoNet programs for various computers\012     and operating systems, with sonorous names like BinkleyTerm,\012     FrontDoor, D''Bridge, Dutchie, TrapDoor, Opus, Confmail, QMail,\012     TosScan, Chameleon, GoldED, to mention a few.  \012\012     In the beginning, it was easy to know who operated what\012     system, and what telephone number to call to reach a particular\012     node. As the number of systems in FidoNet grew, it was becoming\012     harder and harder to stay up-to-date. The routing of messages\012     was getting more complicated as well. A new numbering scheme was\012     developed, and therefore today''s FidoNet addresses consist of\012     four parts: Zone, Net, Node and (optionally) Point.  \012\012     The data for all FidoNet systems is kept in a single database,\012     the "nodelist". It lists all the details of every node, such as\012     the bbs name, the sysop''s name, the telephone number, modem\012     flags, and more. And it lists the FidoNet address (the\012     node-number) for each node. Every week, the nodelist is updated;\012     closed systems are removed, new participants added, telephone\012     numbers get updated. All this is done with more tools and\012     utilities.  \012\012     Today, FidoNet consists of almost 10000 nodes with an\012     uncountable number of users. There is private mail between users\012     (Netmail), and there are public conferences (Echomail areas),\012     some of which are distributed over the globe. There are\012     conferences about cooking, about politics, sports, and much\012     more. And about computers, of course, and programming and\012     telecommunications. There are local conferences in the language\012     of that particular region, and there are international areas\012     (mostly in English).  \012\012     Programs and other files are also distributed via FidoNet,\012     especially if they are Public Domain, Freeware or Shareware.\012     There are excellent distribution systems, where a programmer of\012     a utility just has to pack it into a compressed archive\012     (together with the documentation), send it to the next\012     coordinator, and the file will be moved around the world within\012     a few days. And what''s more, the software that allows you to run\012     a FidoNet node is distributed via exactly this method -- it is\012     usually available for free.  \012\012     There is another nice point about FidoNet, which allows normal\012     bbs users to save telephone charges: when reading or writing\012     messages, you usually have to stay online (connected to the\012     other modem) all the time, and during all this time, your\012     telephone company is happily cashing away... Because of that,\012     FidoNet offers the option of "Points". With a point system, you\012     can pick up all waiting mail in compressed form when calling\012     your "boss system". After that, you can read and write messages\012     offline, without your money ticking away. The ones you write are\012     later packed and sent to your "boss" at the next call. From\012     there, the mail travels out into the rest of FidoNet. As a\012     bonus, you will obtain your own FidoNet-address, which is the\012     node number of your boss, plus a dot (".") and your point-number\012     appended, i.e., Point 24 of node 2:310/3 becomes 2:310/3.24.\012     That''s also the reason for the name "point" - because of the\012     separating dot.  \012\012     An additional feature available to point systems (compared to\012     normal bbs users) is "file requests". With file requests, new\012     programs and files that are available at the boss system can be\012     "requested" and will be sent automatically during the next\012     call.  \012\012     A last word on the organization of FidoNet: The sysops of\012     FidoNet nodes are usually individuals, who run their node just\012     for fun. It is their hobby, and they pay for their usually high\012     telephone bills out of their own pocket and partially from\012     donations from users and points. None of the FidoNet\012     coordinators receives a reward/payment for his work or his\012     expenses.  \012\012     Still, FidoNet works, and it works well. Sure, once in a\012     while, the other node will quit working, just because a sysop\012     went for a holiday and his machine decided to crash as soon as\012     he closed the door, but overall, the network runs fine.  \012\012              @{"      FIDO MENU      " link WhatIsFido}@{"      MAIN MENU      " link Main}\012\012@ENDNODE\012\012@Node Fido2 "Information about Fidonet - © 1993 Tycoon"\012\012                         THE STRUCTURE OF FIDONET\012                         ------------------------\012\012  1.1. The Structure of FidoNet\012\012                 Zone 1       Zone 2     Zone 3      Zone 4,5,6,...\012             North America    Europe    Australia\012                 1:1/0        2:2/0      3:3/0\012                                |\012                               / \\012                              /   \\012                             /\    \\012                            /  \    \\012                        Region 29  Region 25\012                        Region 30  Region 26\012                        ...        Region 27\012                                   Region 28\012                        Region 31\012                         Austria\012                         2:31/0\012                         /    \____________\012                        /      \           \\012                  Net 313       Net 310     Net 316,...\012               Lower Austria    Vienna\012                                2:310/0\012                                   |\012                                __/ \__\012                               /       \\012                              /         \\012                           __/           \________________\012                          /  \            \               \\012                         /    \            \               \\012                     Node 1  Node 2       Node 3          Node 6\012                                      Cuckoo''s Nest   The Mad House\012                                         2:310/3\012                                          / | \\012                                      lots of Points\012                                                \\012                                            Point 14\012                                 The Infinite Improbability Zone\012                                           2:310/3.14\012\012              @{"      FIDO MENU      " link WhatIsFido}@{"      MAIN MENU      " link Main}\012@ENDNODE\012\012@Node Fido3 "Information about Fidonet - © 1993 Tycoon"\012\012                           HOW TO BECOME A POINT\012                           ---------------------\012\012  2. Becoming a Point\012\012  2.1. Finding The Tools   \012\012     So you want to set up a point on your Amiga? \012\012     First, you should look for a FidoNet node willing to accept\012     you as a point, your "boss". Once this problem is solved, you\012     will need some of the following tools to setup your system.  \012\012     The names at the end of each item in this list indicate\012     typical representatives of the respective category -- the first\012     is the one tested and recommended by us, the others [in\012     brackets] are possible alternatives (alphabetically sorted) that\012     we haven''t really tested extensively, but just know that they\012     exist.  \012\012     For more details about how a point system is supposed to work,\012     see further below. For the more esoteric expressions, please\012     refer to the glossary.  \012\012          * A mailer. The mailer is needed to transfer mail bundles\012            and/or normal files to and from your boss. It will use\012            your modem to call that system, and then use distinctive\012            protocols and guidelines to securely transmit the data.  \012            TrapDoor [AmyBink, WelMat].  \012\012          * An import/export tool, also called mail\012            scanner/tosser/packer. This program will bundle the mail\012            originating at your place, destined for your boss.\012            Likewise, it will stuff incoming messages into the proper\012            locations in your message base, ready to be read using a\012            message editor.  \012            TrapToss [ConfMail, FastPoint, GCC, Juliet] \012\012          * A message editor, to comfortably read and write mail. It\012            allows to browse through the different message areas, and\012            easily reply to whatever topic or message interests you.  \012            Chameleon [GCC, Juliet, RMB] \012\012     These programs can be found on many FidoNet bulletin boards.\012     Just use your terminal software to download them. Also, you will\012     probably need various compression/decompression utilities, such\012     as Arc, LHArc, or Zoo.  \012\012     When you have downloaded the programs, decompress the archives\012     (see the documentation for Arc, LHArc and Zoo on how to do that)\012     and READ THE DOCUMENTATION that comes with each program.\012     Software authors often spend a lot of time struggling to explain\012     all the features, usage and installation of their programs in a\012     detailed manual. It is a wasted effort if you do not read it.  \012\012              @{"      FIDO MENU      " link WhatIsFido}@{"      MAIN MENU      " link Main}\012@ENDNODE\012\012@Node Fido4 "Information about Fidonet - © 1993 Tycoon"\012\012                       IF YOU WANT TO KNOW IT ALL...\012                       -----------------------------\012\012  2.2. Deeper Understanding\012\012     This is how the mail you read and write is processed -- don''t\012     be afraid of obscure terms, you will most certainly understand\012     them once you are through...  \012\012          + Your boss system bundles the mail for you. These bundles\012            are compressed (usually using ARC, a widely spread\012            archiving tool, available for many platforms -- unless\012            you arrange for something different, like LHArc or Zoo).  \012\012          + Similarly, your exporting tool - the mail packer - will\012            pack any mail not yet sent, and prepare it for transfer\012            to your boss'' system. This will result in files in your\012            outbound directory being created.  \012\012          + Your front end mailer calls your boss system,\012            identifiying itself. It will then send any files destined\012            for your boss (for example the mail bundles prepared\012            above), and receive any files the remote system wants to\012            send you (including your mail).  \012\012          + Once the mailer has completed the call, you should find a\012            lot of strange looking files in your inbound directory.\012            You will want to run the importing tool (the mail tosser)\012            to unpack the archives, and to place the incoming\012            messages in the correct areas in your message base.  \012\012          + With the editor, you now can read those freshly arrived\012            messages. You can reply to them, or you can compose new\012            ones, and these will all be sent to your boss at the next\012            call (don''t forget to call the exporting tool first!).  \012\012              @{"      FIDO MENU      " link WhatIsFido}@{"      MAIN MENU      " link Main}\012@ENDNODE\012@Node Fido5 "Information about Fidonet - © 1993 Tycoon"\012\012                              MAIL FLOW INFO\012                              --------------\012\012  2.3. A Little Diagram\012\012     Here is an outline of the mail flow between the various\012     programs. At the very bottom, you sit in front of your message\012     editor and read and write messages. On the left side, messages\012     are created, entered in your message base, exported to the\012     outbound directory, and sent to your boss. On the right side,\012     mail from your boss is received into the inbound directory, then\012     imported by the mail tosser, and finally read by you.  \012\012\012\012\012                                 FidoNet      \012                                    |         \012                            +----------------+\012                            |   Your boss    |\012                            +----------------+\012                               |          |   \012                             (file transfer)  \012                               |          |   \012                            +----------------+\012                            |     Mailer     |\012                            +----------------+\012                               |          |   \012                            (outbound)(inbound)\012                               |          |   \012                            +----------------+\012                            | Scanner/Tosser |\012                            +----------------+\012                               |          |   \012                            (export)  (import)\012                               |          |   \012                              (message base)  \012                               |          |   \012                            +----------------+\012                            | Message Editor |\012                            +----------------+\012                               |          |   \012                             (type)    (read) \012                               |          |   \012                            +----------------+\012                            |      You       |\012                            +----------------+\012\012              @{"      FIDO MENU      " link WhatIsFido}@{"      MAIN MENU      " link Main}\012@ENDNODE\012@Node Fido6 "Information about Fidonet - © 1993 Tycoon"\012\012                           INSTALLING IT CORRECT\012                           ---------------------\012\012  2.4. Installing The Mess\012\012     If you are not sincerely confused by now, you are cheating!\012     The complexity of a FidoNet point has bewildered every single\012     newcomer to FidoNet so far! (So either you''re cheating and have\012     already heard about FidoNet before, or this manual is really\012     good at explaining things.) \012\012     You have obtained all the programs needed, unpacked them, and\012     read all the documentation and manuals. Although you were\012     already tempted to give up by uncomprehensible terms like\012     "Netmail", "Mail directory" and "moderated Echomail areas", you\012     were clever enough to check the Glossary in this manual for an\012     explanation. Great.  \012\012     We cannot (and don''t really want to) take the "here''s your\012     setup" approach -- you will still have to read and understand\012     the documentation of the different tools necessary. This is of\012     great help if you run into any problems -- you will know what\012     the software does and how it does it, so you can try to find the\012     source of the error yourself. Often only a single line of text\012     in a configuration file is wrong, and can foul up the complete\012     point system.  \012\012     As for TrapDoor, there''s not really much you need. First of\012     all, you should configure TrapDoor to reflect your proper node\012     name and address.  This is described (including an example\012     setup) in TrapDoor''s Fabulous Manual (TrapDoor.Man).  \012\012     Then, you will need to create two directories -- one for\012     incoming files that remote systems send you (called the inbound\012     directory), and one for outgoing files (called the outbound\012     directory).  \012\012     Should you feel the need of using a nodelist, we believe you\012     should add another directory, to hold the nodelist and the index\012     files necessary.  \012\012     We''d suggest the following directory tree.  \012\012\012\012        +--------------------------------------------------------+\012        |                       MAIL:                            |\012        +--------------------------------------------------------+\012             |            |              |         |  |  |  |  |  \012        +---------+  +----------+  +----------+  +---------------+\012        | Inbound |  | Outbound |  | Nodelist |  | message areas |\012        +---------+  +----------+  +----------+  +---------------+\012\012              @{"      FIDO MENU      " link WhatIsFido}@{"      MAIN MENU      " link Main}\012@ENDNODE\012\012@Node Registration "Registration - © 1993 Tycoon"\012\012                              HOW TO REGISTER\012                              ---------------\012\012     1.  Print the "/X-FIDO Registration Form" of which a copy can be\012         found in the archive and on the next page.\012\012     2.  Please print or write CLEARLY!\012         2.a. Fill in your Personal Stuff and BBS stuff.\012         2.b. Your FidoNet address (not required, if present you will be\012              automatically notified when your copy is shipping.)\012         2.c. Your private voice telephone number (not compulsory).\012              If possible, use the template "+31-(229)-062244", where 31\012              is the country code and 229 is the area code.\012\012     3.  Send the registration form to /X-Fido Development.  \012\012                            /X-Fido - Development\012                               Zuiderdracht 22\012                            1696 AL Oosterblokker\012                           The Netherlands / Europe\012\012                      Fido: 44:100/0 14:100/102 99:999/4 \012                             BBS: +31-229-062-244 \012\012         If you want to donate more money for the program, you can send\012         money to the above address (this will speed up your reg.\012         version and it will be greatly appreciated, also your tips\012         complaints and a like will be taken more seriously).\012\012                @{" REGISTRATION FORM " link Registration1}      @{"      MAIN MENU     " link Main}\012\012@ENDNODE\012@Node Registration1 "Registration - © 1993 Tycoon"\012\012                      /X-FIDO  SOFTWARE REGISTRATION FORM\012                      -----------------------------------\012\012         Yes, please, I want to use FIDO with Ami-Express. I have a \012         registered version of Ami-Express.  The author of /X-FIDO has\012         the rights to decline the order at any time without further\012         notification.  I really want to use FidoNet with /X and I can''t\012         wait for my registered version to arrive!\012\012         I have enclosed US$10 in the envelope.\012\012           My name is:              _________________________________\012\012           My address:              _________________________________\012\012                 City:              _________________________________\012\012             ZIP code:              _____________\012\012              Country:              _________________________________\012\012           My Sysopname is:         _________________________________\012\012           BBS Location is:         _________________________________\012\012           Active years   :         _________________________________\012\012\012           My private telephone:    +___-(____)-__________\012\012           My BBS number (1):       +___-(____)-__________\012\012           My BBS number (2):       +___-(____)-__________\012\012           /X registration nr:      _________________________________\012\012           My fidonet address is:   ____:____/____.____\012\012         The reason I want to use FIDO is...\012\012         ____________________________________________________________\012\012         ____________________________________________________________\012\012         ____________________________________________________________\012\012         ____________________________________________________________\012\012\012                                                Yours truly,\012\012\012\012                                             __________________\012                                             (please sign here)\012\012\012                             @{" Back to Main Menu " link Main}\012@EndNode\012\012@Node Trapdoor "TrapDoor Info - © 1993 Tycoon"\012\012                              TRAPDOOR\012                              --------\012\012      Ami-X cannot handle FidoNet calls at this time, so another program\012      has to do this for you. This will be done with TrapDoor. TrapDoor\012      is a mail system that can handle (read: recognize) the following\012      incoming calls: - FidoMail call\012                      - Fax call\012                      - Data call\012\012      So whenever a call is made to your system, TrapDoor will pick up\012      the line and listens what kind of call it is (fido/fax/bbs). If\012      it''s a Fido call, it will check who the caller is, check if there\012      is mail and send it if there is, it also receives files from the\012      caller if the callers has some for you.\012\012      If the call is a data call (read: bbs call), TrapDoor will launch\012      Ami-X and the user can enter the BBS.\012\012      TrapDoor is also able to recognize FAX calls, but I don''t have a\012      fax-modem (yet!) so I haven''t figured that out yet. But don''t\012      worry, I''ll have my 16k8/fax real soon, so I''ll let ya know. That\012      way you can receive fido/fax/bbs calls on the same line! Is that\012      cool or what?!\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012\012@EndNode\012\012@Node Traptoss "TrapToss Information - © 1993 Tycoon"\012\012                              TRAPTOSS \012                              --------\012\012      TrapToss is the import/export module that is able to pack and\012      unpack Fido packets. It will unpack the messages and write them\012      to the harddrive so /XF can read the messages and display them\012      to users. \012\012      TrapToss also makes all the packets for any points you have on\012      your system and nodes that are connected to your system. That''s\012      why the config file is very difficult to config [that''s why I\012      did all the hard work for you ;-)].\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012\012@Node Skytick "SkyTick Information - © 1993 Tycoon"\012\012                              SKYTICK\012                              -------\012\012      With fido it is also possable to mail files to other bbs''en.\012      But therefore you have to need an utility that can get the files\012      out of the outbound dir and put thm at the right place.  Skytick\012      is the program that search in the outbound dir for *.Tic files\012      and if there are some it will look into the skytick.cfg and then\012      it will be placed in the dir that is given in the config.  \012      \012      When for example a new nodelist is send to your system skytick\012      will send them to the nodes on your bbs that are listed in the\012      config.  This can be done with al kinds of files, new utils\012      textfiles, updates of programms.. A lot of thinks.. But you have\012      to know the File-tag-names else skytick will give the error :\012      "Device is full" or something in that order..\012\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012\012@Node SkyFreq "SkyFreq Information - © 1993 Tycoon"\012\012                              SKYFREQ\012                              -------\012\012      What is Freqqing?  Well, with Fido you can send a frequest (file-\012      request) to another BBS without logging in under your name, etc.\012      When freqqing trapdoor will start skyfreq and then SkyFreq will\012      look for the file and than send it to you.  But most TrapDoor BBS''\012      will not have activated freqqing.  Because no download credits will\012      be registered.  So somebody can freq all your files without any\012      uploading.  That is why I do not tell anymore about freqqing because\012      it has no sence (My idea.  If you disagree, read the SkyFreq manual).\012\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012\012@Node Traptell "TrapTell Information - © 1993 Tycoon"\012\012                              TRAPTELL\012                              --------\012\012      TrapTell is a tiny program that can order TrapDoor to call another\012      system to pick up mail. This is done via TrapDoor''s ARexx-port.\012\012      It can also tell TrapDoor things like: No More Fido Callers, No\012      More Data Callers or No More FAX Callers.\012\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012\012@Node Trappoll "Trappoll Information - © 1993 Tycoon"\012\012                                  TRAPPOLL\012                                  --------\012\012      TrapPoll is a tiny program that can order TrapDoor to call another\012      system to pick up mail. This is done via TrapDoor''s ARexx-port.\012\012      It looks into the outbound dir and than decide or any bbs must\012      be called to send mail to it. More info in the TrapPoll documents.\012\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012\012@Node Traplist "TrapList Information - © 1993 Tycoon"\012\012                                  TRAPLIST\012                                  --------\012\012      Traplist is the program that converts the nodelists into some\012      readable data for TrapDoor.  So TrapDoor knows the telephone and\012      nodenubers and passwords from all nodes listed in the nodelists.\012\012      It must be run from CLI and then makes some data files. It gets\012      its data out the Traplist.cfg and all files in the nodelist-dir.\012      You have to run this program before you start using TrapDoor. \012      You only have to do this one time, not everytime you want to use\012      TrapDoor. If the NodeList changes, however, you will have to run\012      it again.                   \012\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012\012@Node TrapCall "TrapCall Information - © 1993 Tycoon"\012\012                                  TRAPCALL\012                                  --------\012\012      TrapCall is a tiny util to call other bbs''s for swapping mail.\012      It is used in the CLI and a little requester will be shown where\012      you can type the nodenumber you wanna call and then it calls it.      \012\012      \012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012\012@Node Trapscan "TrapScan Information - © 1993 Tycoon"\012\012                                  TRAPSCAN\012                                  --------\012\012      TrapScan is a replacer for ''list'' (c:list) Look docs for more info\012      because I don''t use it. Don''t know or you use it so if you have to\012      look into the TrapScan docs.\012\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012\012@Node Fido-Con.EXE "Fido-Con.EXE - © 1993 Tycoon"\012\012                            FIDO-CON.EXE\012                            ------------\012\012      Place: BBS:fidonet/\012\012      Utility for @{"Fido-Main.Rexx" link Fido-Main.REXX}.  This one converts a fido-message\012      into a readable file so the users can read them in Net.  It is written\012      fully in Assembly and can convert 60KB per sec. So a user never has to\012      wait long...\012\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012\012@Node Fido-Hgh.EXE "Fido-Hgh-.EXE - © 1993 by Tycoon"\012\012                            FIDO-HGH.EXE\012                            ------------\012\012      Place: BBS:fidonet/\012\012      Utility for @{"Fido-Main.Rexx" link Fido-Main.REXX}. This utility scanns very fast for\012      the Highest and Lowest message in an area.   NET needs to know\012      what the lowest & highest message in an area is,  because else\012      it will get into a guru. And I hate guru''s... ;-)\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012\012@Node Fido-Del.EXE "Fido-DEL.EXE - © 1993 Tycoon"\012\012                            FIDO-DEL.EXE\012                            ------------\012\012      Place: BBS:fidonet/\012\012      Utility in assembly for @{"Fido-Main.Rexx" link Fido-Main.REXX}.  The function of this\012      program is to delete message''s on the hd.   It will be called\012      in @{"Fido-Del.Rexx" link Fido-del.rexx}.\012\012@EndNode\012\012@Node Fido-Del.REXX "Fido-DEL.REXX - © 1993 by Tycoon"\012\012                               FIDO-DEL.REXX\012                               -------------\012\012      Place: BBS:fidonet/\012\012      This script reads the @{"Fidonet.Cfg" link Fidonet.cfg} for the value of @{"Maxmsg" link MAXMSG} and\012      it checks how many messages there are one the hd. If there are\012      more messages then the value of @{"Maxmsg" link MAXMSG} then all lower messages\012      will be deleted until there are Maxmsg''s left on the hd.  Then\012      it will check the next area until all areas are done.\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012\012@Node Fido-Mail.rexx "Fido-Mail.REXX - © 1993 Tycoon"\012\012                            FIDO-MAIL.REXX\012                            --------------\012\012      Place: BBS:fidonet/\012\012      This is the script to start NET. In your @{"BBS.CMD" link bbs.cmd} must be a line\012      with NET in it.  It will start  @{"Fido-Main.Rexx" link fido-main.rexx}  with a variable\012      to go to the mail routine. You can''t run Fido-Main.Rexx without\012      this script, because Fido-Main.rexx needs a variable to start.\012\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012\012@Node Fido-SCAN.REXX "Fido-SCAN.REXX - © 1993 by Tycoon"\012\012                            FIDO-SCAN.REXX\012                            --------------\012\012      Place: BBS:fidonet/\012\012      Via this script SCAN can be started.  In your @{"BBS.CMD" link bbs.cmd} must be a\012      line with SCAN in it.  It will start @{"Fido-Main.Rexx" link fido-main.rexx} with a va-\012      riable to go to the scan routine.  You can''t run Fido-Main.rexx\012      without this script, because it needs a variable to start.\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012\012@Node USER "User-Directory - © 1993 Tycoon"\012\012                            USER-DIRECTORY\012                            --------------\012\012      Place: BBS:fidonet/\012\012      This directory will hold all the data from the users. For every\012      network there will be created a <Username>.X  The meaning of the\012      x is:                                                     \012                      <Username>.0 = File with real name from user\012                      <Username>.1 = All low & high pointers from all\012                                     the areas in network 1\012                      <Username>.2 = All low & high pointers from all\012                                     the areas in network 2\012\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012@Node Fido-Ran.REXX "Fido-Ran.REXX - © 1993 by Tycoon"\012\012                            FIDO-RAN.REXX\012                            -------------\012\012      Place: BBS:fidonet/\012\012      This Utility creates a random number from 8 numbers.  This will\012      be used in @{"Fido-Main.rexx" link fido-main.rexx} for the message-ID-number.  Every msg\012      must have a number to indicate by reply''s and linking from mes-\012      sages.\012\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012\012@Node Fido-Main.Rexx "Fido-Main.REXX - © 1993 Tycoon"\012\012                            FIDO-MAIN.REXX\012                            --------------\012\012      Place: BBS:fidonet/\012\012      This is the main file of the whole Fido-mailer.  This door will\012      connect Ami-Express with Fido [the missing link :-)].  In this\012      door a user can:\012        - read   fido-mail\012        - write  fido-mail\012        - scan   fido-mail (for new mail)\012        - search fido-mail (Subject, from and to)\012        - download mail (with Z-Modem)\012\012      This door can be started by @{"Fido-scan.rexx" link fido-mail.rexx}  or  @{"Fido-mail.rexx" link fido-mail.rexx}\012      and will not run without one of them.  It has got a security-check\012      so you have to register to be able to run it. This file can call the next\012      utils and config-files:\012        - bbs:fidonet/@{"user" link user}/<Username>.X\012        - bbs:fidonet/@{"fido-con.exe" link fido-con.exe}\012        - bbs:fidonet/@{"fido-hgh.exe" link fido-con.exe}\012        - bbs:fidonet/@{"uucp-con.exe" link Uucp-con.exe}\012        - bbs:fidonet/@{"FidoNet.CFG" link fidonet.cfg}\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012@Node Bullxx.TXT "Bullxx.TXT - © 1993 Tycoon"\012\012                                 BULLXX.TXT\012                                 ----------\012\012      Place: BBS:\012\012      This file is for starting the scanner.  When an user will login,\012      Ami-Express will look for a file called BBS:bullxx.txt where xx\012      is the minimum accesslevel to read it.  So if normal users have\012      access 20 then the file must called Bull20.TXT.  Then when a user\012      logged into the bbs the file will be executed.  In the textfile\012      are some MCI commands. So a door can be ran.\012\012      In the file will be something like:\012\012      ~ \012      ~CC_SCAN\012\012      Thats all.. the first line will tell AmiExpress that it is a MCI\012      text. Behind the lines must be one SPACE !!!!\012\012      When you have already a textfile called BBS:Bullxx.txt then you\012      can use:\012\012      ~ \012      ~SS_BBS:OLDBULL.TXT \012      ~SP\012      ~CC_SCAN \012\012      This will display the file BBS:oldbull.txt what can be your old\012      bullxx.file and than ask for a Pause, press space to continue\012      and than it will start the scanner-door.\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@Endnode\012@Node BBS.CMD "Commands - © 1993 Tycoon"\012\012                            COMMANDS\012                            --------\012\012      Place: BBS:Commands/\012\012      Here are some files named BBS.CMD and SYSOP.CMD.  The sysop.cmd\012      will not be editted.. But in the bbs.cmd you must add:\012\012      *NET      RS020bbs:fidonet/FIDO-mail.rexx\012      *SCAN     RS020bbs:fidonet/FIDO-scan.rexx\012                  ^^^\012                  `-- or whatever access code you want to give it.\012\012      The first line is for the mailer and the other line can be used\012      to start the scanner to start scanning for new mail in all fido areas.\012      \012      @{"    MENU    " link DirStructure} @{" DirStructure " link DirStructure} @{"   Installation   " link InstallProc} @{"  MainMenu  " link Main}\012@EndNode\012\012@Node UUCP-con.exe "UUCP-Con.EXE - © 1993 Tycoon"\012\012                            UUCP-CON.EXE\012                            ------------\012\012      Place: BBS:Commands/\012\012      This little utility converts ''UUCP-mail'' to readable data that can\012      be used in the reader.  UUCP will not included in this version\012      but in one of the next verion.\012\012      If you want to UUCP then you have also to install the UUCP-Mail-\012      package and thats about 1.6MB. If it is supported 100% then all\012      configs will be given to all sysops who have installed /X-Fido.\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012\012@Node Fido.History "Fido.History - © 1993 Tycoon"\012\012                            FIDO.HISTORY\012                            ------------\012\012      Place: BBS:Fidonet/\012\012      This is an overview of al the changes per version of /X-Fido..\012      So you can see what we improved in the versions and what bugs\012      are fixed... Read this to see what is the latest release version!\012\012      So everybody can see how /X-Fido has become what it is now... ;-)\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012\012@Node Fidonet.cfg "FidoNet.CFG - © 1993 Tycoon"\012\012                              FIDONET.CFG\012                              -----------\012\012                  @{" 1. What is it                         " link fidonet1.cfg}\012\012                  @{" 2. The keywords                       " link fidonet.cfg}\012                  @{"    2.1.  Node     " link Node} @{"    2.9.  Area     " link area}\012                  @{"    2.2.  Delete   " link Delete} @{"    2.10. Dir      " link Dir}\012                  @{"    2.3.  All      " link All} @{"    2.11. Access   " link access}\012                  @{"    2.4.  Eall     " link Eall} @{"    2.12. Alias    " link Alias}\012                  @{"    2.5.  Local    " link local} @{"    2.13. Write    " link write}\012                  @{"    2.6.  Length   " link Length} @{"    2.14. Nodenr   " link Nodenr}\012                  @{"    2.7.  F-Origin " link F-origin} @{"    2.15. Maxmsg   " link maxmsg}\012                  @{"    2.8.  Tempdir  " link Tempdir} @{"    2.16. Origin   " link Origin}\012\012                  @{" 3. Sample config-file                 " link fidonet3.cfg}\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012\012@Node Fidonet1.cfg "Fidonet.cfg - © 1993 Tycoon"\012\012     1. What is it\012     \012        Every program has got its own Config-File. This is the config-\012        file for Fido-Main.REXX. It contains a lot of keywords that can\012        be used. If something is incorrect than the program will report\012        this. The program will not run with a corrupt configuration file.\012\012     \012             @{" Back to FidoNet.CFG " link Fidonet.cfg}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012@Node Node "2. The Keywords - © 1993 Tycoon"\012\012                                   NODE\012                                   ----\012\012      This is your Main Node Number. This is the number you will be\012      known as in the fido world. It is something like: 44:100/100.0\012\012      The address must be in 4D, that means that it has to be in this\012      format: xx:xx/xxx.x (where x is a number).\012\012      Like:\012\012      NODE     44:100/100.0\012      NODE     2:289/456.0\012      NODE     99:999/4.0\012\012\012             @{" Back to FidoNet.CFG " link Fidonet.cfg}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012\012@Node Delete "2. The Keywords - © 1993 Tycoon"\012\012                                  DELETE\012                                  ------\012\012     This is the delete access.  Be sure to set this high enough,\012     otherwise too many people can kill the mail.  Everybody with the\012     same or higher access can delete @{"ALL" link All} messages in a fido-area!!!!\012\012\012     Like:\012\012     DELETE   200     (Now access 200 or higher can delete ALL messages)\012     DELETE   0       (Now Everybody can delete messages)\012\012\012\012             @{" Back to FidoNet.CFG " link Fidonet.cfg}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012@Node all "2. The Keywords - © 1993 Tycoon"\012\012                                    ALL\012                                    ---\012\012     Can be ON or Off....  If ON, then messages to ''ALL'' will be shown\012     like ALL messages in Ami-X\012\012\012     Like:\012\012     ALL      ON    (Messages to ''ALL'' will be displayed by a scan)\012     ALL      OFF   (NO Messages to ''ALL'' will be displayed by a scan)\012\012\012\012             @{" Back to FidoNet.CFG " link Fidonet.cfg}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012@Node eall "2. The Keywords - © 1993 Tycoon"\012\012                                   EALL\012                                   ----\012\012     Can be On or Off.... IF ON, then messages to ''EALL'' will be shown\012     like EALL messages in Ami-X (format : <Username> (ALL)).\012\012\012     Like:\012\012     EALL     ON    (Messages to ''EALL'' will be displayed by a scan)     \012     EALL     OFF   (NO Messages to ''EALL'' will be displayed by a scan)\012\012\012\012             @{" Back to FidoNet.CFG " link Fidonet.cfg}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012@Node local "2. The Keywords - © 1993 Tycoon"\012\012                                   LOCAL\012                                   -----\012\012     With this option  you can swap the colours RED and WHITE in local\012     mode. If you don''t want this to happen, just enter a non-existent\012     node number (e.g. 1000).\012\012\012     Like:\012\012     LOCAL    2       (red and white for node 2 will exchanged)\012     LOCAL    1000    (node 1000 will never exists so no exchange)\012\012\012\012             @{" Back to FidoNet.CFG " link Fidonet.cfg}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012@Node length "2. The Keywords - © 1993 Tycoon"\012\012                                  LENGTH\012                                  ------\012\012     With LENGTH you can specify the width characters /X-FIDO uses to\012     word wrap in messages.\012\012\012     Like:\012\012     LENGTH   77   (all lines will be wordwrapped at 77 characters)\012     LENGTH   40   (all lines will be wordwrapped at 40 characters)\012     LENGTH   80   (all lines will be wordwrapped at 80 characters,\012                    but some terminalprogs have a right border so 80\012                    characters will not fit!)\012\012\012             @{" Back to FidoNet.CFG " link Fidonet.cfg}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012@Node F-origin "2. The Keywords - © 1993 Tycoon"\012\012                                 F-ORIGIN\012                                 --------\012\012     If you don''t specify an @{"origin" link origin} with a mail area (later on in the\012     config) /X-FIDO will take this origin.\012\012\012     Like:\012\012     F-ORIGIN CHANNEL X Home of /X-FIDO\012     F-ORIGIN CALL NOW CHANNEL X -> +31-229-062-244\012     F-ORIGIN >> I HATE MS-DOS <<\012\012\012             @{" Back to FidoNet.CFG " link Fidonet.cfg}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012@Node Tempdir "2. The Keywords - © 1993 Tycoon"\012\012                                  TEMPDIR\012                                  -------\012\012     If you have not that much ram, you can give a tempdir and then all\012     big actions will be done in the dir you give.. \012     \012     IT MUST END ON '':'' OR ''/'' !!\012\012     Like:\012\012     TEMPDIR  dh1:temp/\012     TEMPDIR  ram:\012     TEMPDIR  dh12:\012\012\012             @{" Back to FidoNet.CFG " link Fidonet.cfg}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012@Node Net "2. The Keywords - © 1993 Tycoon"\012\012                                    NET\012                                    ---\012\012     Here you have to specify the name of the net work.\012\012\012     Like:\012\012     NET      Ami-Expres-Fido-Net\012     NET      AMIGA-NETWORK\012     NET      LOCAL_USA_MAIL\012\012\012\012             @{" Back to FidoNet.CFG " link Fidonet.cfg}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012@Node level "2. The Keywords - © 1993 Tycoon"\012\012                                   LEVEL\012                                   -----\012\012     The level that is needed to have access to that specific net work.\012\012     Like:\012\012     LEVEL    255   (Only the sysop can enter this net)\012     LEVEL    200   (Only access 200 or higher can enter this net)\012     LEVEL    0     (Everybody can enter this net)\012\012\012\012             @{" Back to FidoNet.CFG " link Fidonet.cfg}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012@Node area "2. The Keywords - © 1993 Tycoon"\012\012                                   AREA\012                                   ----\012\012     Tag-Name for FIDO (be specific, this is very crucial).\012\012\012     Like:\012\012     AREA     /XF_SALE           \012     AREA     AMY_GENERAL  \012     AREA     USA_CHATTING  \012\012\012\012             @{" Back to FidoNet.CFG " link Fidonet.cfg}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012@Node dir "2. The Keywords - © 1993 Tycoon"\012     \012                                    DIR\012                                    ---\012\012      The directory where you want all your messages stored. This should\012      be the same directory TRAPTOSS uses!\012\012      Like:\012\012      DIR      BBS:FIDONET/AXF/SALE\012      DIR      BBS:FIDONET/AXF/SYSOP\012             \012\012\012             @{" Back to FidoNet.CFG " link Fidonet.cfg}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012@Node access "2. The Keywords - © 1993 Tycoon"\012\012                                  ACCESS\012                                  ------\012\012      This is the minimum access level needed for the user to have\012      access to this area.\012\012      Like:\012 \012      ACCESS   30          \012      ACCESS   200\012\012\012             @{" Back to FidoNet.CFG " link Fidonet.cfg}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012@Node alias "2. The Keywords - © 1993 Tycoon"\012\012                                   ALIAS\012                                   -----\012\012      On/Off   On = Real name & Off = Boardname (login name!)\012\012      Like:\012\012      ALIAS    ON            \012      ALIAS    OFF\012\012\012             @{" Back to FidoNet.CFG " link Fidonet.cfg}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012@Node write "2. The Keywords - © 1993 Tycoon"\012\012                                   WRITE\012                                   -----\012\012      On/Off   On = Read/Write Area & Off = Read Only Area\012\012      Like:\012\012      WRITE    ON\012      WRITE    OFF\012\012\012             @{" Back to FidoNet.CFG " link Fidonet.cfg}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012@Node Nodenr "2. The Keywords - © 1993 Tycoon"\012\012                                  NODENR\012                                  ------\012\012      This is YOUR node number in this area, for multiplex networks.\012 \012      Like:\012 \012      NODENR   99:999/4\012      NODENR   44:100/0      \012\012\012             @{" Back to FidoNet.CFG " link Fidonet.cfg}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012@Node maxmsg "2. The Keywords - © 1993 Tycoon"\012\012                                  MAXMSG\012                                  ------\012\012      The maximum number of messages in this area. If there are more\012      the first one will be deleted.\012\012      Like:\012\012      MAXMSG   100           \012      MAXMSG   5000\012\012\012\012             @{" Back to FidoNet.CFG " link Fidonet.cfg}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012@Node origin "2. The Keywords - © 1993 Tycoon"\012\012                                  ORIGIN\012                                  ------\012\012      The default origin for this area. You don''t have to specify this.\012\012      Make sure to leave one line empty when  specifying the next area!\012      You don''t have to enter NET and LEVEL again if the area is of the\012      same net work. Just read the example in chapter 3 and you''ll see.\012\012      An origin used to be used for identifying a system. But nowadays\012      it soulely is used for fun. You can put your BBS ad''s or some funny\012      one-liners in it. Try to be original! Remember, an origin can be\012      only one sentence of about 60 characters!\012\012      Like:\012\012      ORIGIN   Pity the poor egg: it only gets laid once\012      ORIGIN   We''ll get along fine as soon as you realize I''m God.\012      ORIGIN   Boo! Did I scare ya?\012\012\012             @{" Back to FidoNet.CFG " link Fidonet.cfg}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012@Node Fidonet3.cfg "Fidonet.cfg - © 1993 Tycoon"\012\012     3. Sample config-file\012     \012     Below you will find an example of a sample config-file.\012     ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\012\012; This is the CONFIG-FILE of /X-FIDO - © 1993 TYC00N (CHANNEL-X)\012;\012; This is the place where you can config /X-FIDO. Be careful to fill\012; everything in correctly otherwise the program will not work 100%.\012; Errors can cause big problems, the next versions will have a checker\012; for the config-file, but until then -=> WATCH IT! \012;\012; If something goes wrong or you can''t get it to work, just call Channel-X\012; at +31-2290-62244 (16k8 DS/24 Hrs).\012;\012; IMPORTANT\012; ~~~~~~~~~\012; EVERY OPTION MUST BE SPECIFIED AT POSITION 10!! THAT IS, AFTER THE\012; THE KEYWORD! JUST FOLLOW THE GIVEN EXAMPLES AND ALL SHOULD WORK WELL!\012\012; This is YOUR Main node number.\012\012@{"NODE     " link node}14:100/102.0\012\012; This is the delete access. Be sure to set this high enough, otherwise\012; too many people can kill the mail.\012\012@{"DELETE   " link delete}255\012\012; ALL  (on/off)   If you turn this ON, messages to ''ALL'' will be shown like\012                  EALL messages in Ami-X.\012; EALL (on/off)   If you turn this ON, messages to ''EALL'' will be shown the\012                  usual way.\012\012@{"ALL      " link all}OFF\012@{"EALL     " link all}ON\012\012; With this option you can swap the colours RED and WHITE in local mode.\012; If you don''t want this, just enter a non-existent node number (e.g. 1000).\012\012@{"LOCAL    " link local}2\012\012; With LENGTH you can specify the width characters /X-FIDO uses to word\012; wrap in messages.\012\012@{"LENGTH   " link length}77\012\012; If you don''t specifiy an origin with a mail area (later on in the config)\012; /X-FIDO will take this origin.\012\012@{"F-ORIGIN " link F-origin}Channel X -> Home of /X-FIDO Mailer !!!\012\012; -------------------------------------------------------------------------\012;  NOW FOLLOWS AN EXAMPLE OF A NET WORK MAIL SYSTEM (THE BOS-NET NET WORK)\012; --------------------------------------------------------------------------\012;\012; Config Set Up\012; ~~~~~~~~~~~~~\012; NET     Here you have to specify the name of the net work.\012; LEVEL   The level that is needed to have access to that specific net work.\012; AREA    Tag-Name for FIDO (be specific, this is very crucial)\012; DIR     The directory where you want all your messages stored. This should\012;         be the same directory TRAPTOSS uses!\012; ACCESS  This is the minimum access level needed for the user to have\012;         access to this area.\012; ALIAS   On/Off   On = Real name & Off = Boardname (loginname!)\012; WRITE   On/Off   On = Read/Write Area & Off = Read Only Area\012; NODENR  This is YOUR node number in this area, for multiplex networks.\012; MAXMSG  The maximum number of messages in this area. If there are more the\012;         first one will be deleted.\012; ORIGIN  The default origin for this area. You don''t have to specify this.\012;\012; Make sure to leave one line empty when specifying the next area! You\012; don''t have to enter NET and LEVEL again if the area is of the same\012; net work. Just read the following example and you''ll see.\012\012; ---------------\012; BOS-NET (DUTCH)\012; ---------------\012\012@{"NET      " link net}BOS\012@{"LEVEL    " link level}20\012\012@{"AREA     " link area}BOS_COMPUTERS\012@{"DIR      " link dir}dh1:bos/bos1\012@{"ACCESS   " link access}20\012@{"ALIAS    " link alias}OFF\012@{"WRITE    " link write}ON\012@{"NODENR   " link nodenr}99:999/4.0\012@{"MAXMSG   " link maxmsg}100\012@{"ORIGIN   " link origin}Channel X -> Home of /X-FIDO Mailer !!!\012\012@{"AREA     " link area}BOS_GEZWAM\012@{"DIR      " link dir}dh1:bos/bos2\012@{"ACCESS   " link access}20\012@{"ALIAS    " link alias}OFF\012@{"WRITE    " link write}ON\012@{"NODENR   " link nodenr}99:999/4.0\012@{"MAXMSG   " link maxmsg}100\012@{"ORIGIN   " link origin}Channel X -> Home of /X-FIDO Mailer !!!\012\012@{"AREA     " link area}BOS_IRRITATIE\012@{"DIR      " link dir}dh1:bos/bos3\012@{"ACCESS   " link access}20\012@{"ALIAS    " link alias}OFF\012@{"WRITE    " link write}ON\012@{"NODENR   " link nodenr}99:999/4.0\012@{"MAXMSG   " link maxmsg}100\012@{"ORIGIN   " link origin}Channel X -> Home of /X-FIDO Mailer !!!\012\012@{"AREA     " link area}BOS_MUZIEK\012@{"DIR      " link dir}dh1:bos/bos4\012@{"ACCESS   " link access}20\012@{"ALIAS    " link alias}OFF\012@{"WRITE    " link write}ON\012@{"NODENR   " link nodenr}99:999/4.0\012@{"MAXMSG   " link maxmsg}100\012@{"ORIGIN   " link origin}Channel X -> Home of /X-FIDO Mailer !!!\012\012; --------------------\012; AMI-EXPRESS-FIDO-NET\012; --------------------\012\012@{"NET      " link net}/X-FIDO-NET\012@{"LEVEL    " link level}200\012\012@{"AREA     " link area}AXF_GEN\012@{"DIR      " link dir}dh1:axf/A-gen\012@{"ACCESS   " link access}200\012@{"ALIAS    " link alias}OFF\012@{"WRITE    " link write}ON\012@{"NODENR   " link nodenr}44:100/0.0\012@{"MAXMSG   " link maxmsg}100\012@{"ORIGIN   " link origin}Channel X -> /XF-SUPPORT-WHQ!!!\012\012@{"AREA     " link area}AXF_SALE\012@{"DIR      " link dir}dh1:axf/A-sal\012@{"ACCESS   " link access}200\012@{"ALIAS    " link alias}OFF\012@{"WRITE    " link write}OFF\012@{"NODENR   " link nodenr}44:100/0.0\012@{"MAXMSG   " link maxmsg}100\012@{"ORIGIN   " link origin}Channel X -> /XF-SUPPORT-WHQ!!!\012\012@{"AREA     " link area}AXF_COSYSOP\012@{"DIR      " link dir}dh1:axf/A-cos\012@{"ACCESS   " link access}200\012@{"ALIAS    " link alias}OFF\012@{"WRITE    " link write}ON\012@{"NODENR   " link nodenr}44:100/0.0\012@{"MAXMSG   " link maxmsg}100\012@{"ORIGIN   " link origin}Channel X -> /XF-SUPPORT-WHQ!!!\012\012@{"AREA     " link area}AXF_SYSOP\012@{"DIR      " link dir}dh1:axf/A-sys\012@{"ACCESS   " link access}255\012@{"ALIAS    " link alias}OFF\012@{"WRITE    " link write}ON\012@{"NODENR   " link nodenr}44:100/0.0\012@{"MAXMSG   " link maxmsg}100\012@{"ORIGIN   " link origin}Channel X -> /XF-SUPPORT-WHQ!!!\012\012@{"AREA     " link area}AXF_BETATEST\012@{"DIR      " link dir}dh1:axf/A-bet\012@{"ACCESS   " link access}200\012@{"ALIAS    " link alias}OFF\012@{"WRITE    " link write}ON\012@{"NODENR   " link nodenr}44:100/0.0\012@{"MAXMSG   " link maxmsg}100\012@{"ORIGIN   " link origin}Channel X -> /XF-SUPPORT-WHQ!!!\012\012; End of the configFile\012\012      ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\012\012      That''s all of the configuration file.....  You can find the keywords\012      in chapter 2.\012\012             @{" Back to FidoNet.CFG " link Fidonet.cfg}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012\012@Node Traplist.cfg "Traplist.cfg - © 1993 Tycoon"\012\012                               TRAPLIST.CFG\012                               ------------\012\012      Below you will find a little traplist.cfg.    This one should be\012      working because I use it.  First some explaining about the words\012      in the config-file.\012      \012      NodelistPath = This is the path to the directory where your\012                     nodelists will be stored. Trapdoor must have some\012                     nodelists because in the nodelist are the node-\012                     numbers of the other bbs'' in the net and also the\012                     telephone numbers!\012                     \012      BufferSize   = How big the buffer for File i/o work (64K)\012\012      NodeList     = The name of the nodelist.. A name like Bosnet.011\012                     will be Bosnet because traplist will be automatic\012                     including the .011.  This is for auto-updating \012                     from nodelist via DIFFs. (More about this in the\012                     traplist docs. You have to specified this for all\012                     your nets...)\012\012      DelOldLists  = Turn the auto-updating routine on.. If there will\012                     be a new nodelist then traplist will update it.\012\012      DelOldDiffs  = This will delete the old nodelist if there is a\012                     new one..\012\012      Report       = The filename a report will written to when trap-\012                     list is runned.\012\012      Password     = The password for the node.  Here must be the\012                     passwords you use with a connection with an other\012                     fido-bbs.  You must have his nodenumber with the\012                     password and the other must have your number with\012                     the same password.\012                     \012                     like  PASSWORD  "SECRET" 44:100/199.0\012                     \012                     This will send the password SECRET if there is a\012                     connection between your bbs and node 44:100/199.0\012                     If the password is different from the other, the\012                     connection will be disconnected.\012\012      DAIL        =  You can replace dial strings in a number. Mostly\012                     the telephonenumbers in the nodelist are listed\012                     as : 31-2290-62244.  But if you live in holland\012                     then you must dial 02290-62244 so if you say:\012                     DAIL  "31-" "0"  then the "31-" will be replaced\012                     by "0" and the number 02290-62244 will be used.\012                     \012                     So can also local numbers can replaced.. If an-\012                     other bbs polls and his number is 02290-62535\012                     then he can use: DAIL  "31-2290-" ""\012                     SO the replacer will replace 31-2290 with nothing\012                     and the number will be 62244.\012                     \012                     SO also for outside your country you can put the\012                     right number before it.. A lot of countrys need\012                     "00" before the number.... that can be done with\012                     DAIL "" "00" so a number like 31-2290-622444 will\012                     be 0031-2290-62244.\012\012      COST         = Here you can set costs for a call. You can specify\012                     costs and then if the costs are to high trapdoor\012                     will not call... I have turned it off.\012\012\012      ; **********************************************\012      ; ***   Sample TrapList configuration file   ***\012      ; **********************************************\012\012      NodeListPath "Mail:Nodelist" ; my nodelist directory\012\012      BufferSize 65536             ; use 64k buffer for file i/o\012\012      NodeList "Bosnet"            ; Bosnet \012      Nodelist "AXF-net"           ; Ami-express net\012      Nodelist "nl-amiga"          ; NLA nodelist net\012\012      DelOldLists      ; delete the old nodelists when diff''ed\012      DelOldDiffs      ; delete the old nodediffs when processed\012\012      Report t:TL.report    ; put reports into this file\012\012      ; Passwords.\012      ; note that you can specify several nodenumbers that\012      ; all use the same password. this is for AKA addresses.\012\012      Password What      99:999/1.0 99:999/101.0\012      Password Shall     99:999/402.0\012      Password They      99:999/403.0\012      Password Be        99:999/4.1 14:100/102.1\012\012      ; phone number translations.\012\012      Dial "31-"   "0"\012      Dial "31-2290-" ""    ; local calls\012      Dial "-"     "-"      ; leave "-Unpublished-" as is\012      Dial ""      "00"     ; add "00" to other entries\012\012      ; cost tables (in Hoorn)\012      Cost 67    "31-2290-"    ; local calls in Hoorn\012      Cost 400   "31-"         ; somewhere in the Netherlands\012      Cost -1    "-"           ; forbid calls to -Unpublished-\012      Cost 2800  ""            ; Rest of the World                        \012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012\012@Node fido.cfg "Fido.CFG - © 1993 Tycoon"\012\012                                 FIDO.CFG\012                                 --------\012\012      In the fido.cfg stands al the information how to pack mail, what\012      a node gets at mail and where traptoss must place al the mail at\012      the harddisk.   Read first the meaning of the keywords below be-\012      fore do something.  If you wanna more explanation then you must\012      read the Traptoss manual.  This is just some general information\012      to get it online.\012      \012                                   NODE\012                                   ----\012      This keyword must not be omitted. It specifies the (main)\012      Address of your system. Put your 4-dimensional FidoNet Address\012      here. For compatibility you may omit the Zone entry, however you\012      should specify ''ZONE'' then.  \012\012                   Example:  NODE 2:310/6.4\012\012      Points, who use a ''fake'' PointNet have to specify their\012      correct 4-dimensional Address here. The Fake Address has to be\012      specified using the ''FAKE'' keyword.  \012\012\012                                    AKA\012                                    ---\012      Allows the you to add a list of fidonet addresses for your\012      system (aliases).  TrapToss will then recognize any Message\012      addressed to one of those addresses as addressed to you, which\012      may be important for Netmail. \012      \012                   Example:  AKA 2:3160/4 2:3160/4.1 39:2/3\012\012       Defaults to no AKAs.  \012\012\012                                 POINTNET\012                                 --------\012       For Nodes only. Sets the fake pointnet for your system. All\012       Addresses of template <pointnet>/<x> in Seen-By lines will be\012       treated like <mynet>/<mynode>.<x>. Additionally, packets from\012       PointNet nodes will be interpreted as being from the correct\012       4D-Address, so that security will work.  \012\012                   Example: POINTNET 3160\012\012       You need only use this keyword if some of your points are\012       running older EchoMail software that uses fake pointnet\012       addressing.  \012\012\012                                  DOMAIN\012                                  ------\012       Tells TrapToss the domain your system is in. Currently this is\012       only used for MSGID lines created by the Tosser. The syntax of\012       this command is: \012\012          DOMAIN <name>\012\012       Default is DOMAIN "Fidonet".  \012\012\012                                  ORIGIN\012                                  ------\012       Local Messages that do not contain an Origin line will be\012       provided one by the Tosser. Use this keyword to specify your\012       own particular Origin line (without the Node number which will\012       be added by TrapToss).  \012\012                   Syntax: ORIGIN origline\012\012       <origline> is a string used by the tosser for your origin\012       line.  \012\012\012                                  INBOUND\012                                  -------\012       Sets the Inbound directory path.  \012\012                   Syntax: INBOUND <path>\012\012       Default is ''INBOUND MAIL:Inbound''.  \012\012\012                               OUTBOUND     \012                                 --------\012       Like ''INBOUND'', but defines the Outbound directory path.  \012\012                   Syntax: OUTBOUND <path> \012\012       Default is ''OUTBOUND Mail:Outbound'' \012\012\012                                 TIMEZONE\012                                 --------\012       Use this to tell TrapToss what timezone you are in. TrapToss\012       will put this information in "Via" lines when it passes NetMail\012       to other systems.  \012\012                   Example: TIMEZONE "CET"\012\012       The default is no timezone at all, meaning local time...  \012\012\012                              (NO)UNATTENDED\012                              --------------\012       Switches on the ''unattended'' mode for TrapToss. This is\012       especially useful if your system works without supervision: No\012       Requesters, like "please insert disk" will appear, and smaller\012       errors will be ignored by the Tosser. Thus you do not have to\012       sit by while importing and/or exporting.  \012\012       Defaults to NOUNATTENDED.  \012\012\012                                SCREENMODE\012                                ----------\012       As you may have noticed TrapToss supports Screens. Currently\012       this is far from perfect and we have not yet decided on whether\012       we will make this a little more smart in the future or not.\012       Anyway here is the Syntax: \012\012                   SCREENMODE <mode>\012\012       where <mode> is one of ''CUSTOM'' (simply open a custom screen),\012       ''WORKBENCH'' (open windows on the default public screen),\012       ''ACTIVE'' (currently active screen), ''TRAPTOSS'' (open a shared\012       TrapToss screen, for instance causes TrapToss to open on an\012       already-opened TrapDoor screen) and ''NONE'' (no screen at all).  \012\012       The default mode is SCREENMODE TRAPTOSS, but this will most\012       probably change...  \012\012\012                                 LOGLEVEL\012                                 --------\012       Select the amount of logging from 0 to 9. 9 is most logging.  \012\012       If you select LOGLEVEL 0, no logfile will be created (and no\012       logwindow will be opened, even if you had enabled it).  \012\012                   Example: LOGLEVEL 3\012\012       Defaults to, hmmm, let me have a look, 2 (but this definitely\012       is subject to change according to enhancement requests).  \012\012\012                                  LOGFILE\012                                  -------\012       Select the name of the Logfile.  \012\012                   Example: LOGFILE Mail:TT.Log\012\012       Defaults to ''Mail:TrapToss.Log'' \012\012\012                              (NO)FILEATTACH\012                              --------------\012       This switch enables the file attach mode for TrapToss. If a\012       NetMail Message has its FileAttach bit set, TrapToss will attach\012       the specified file to the Message. The message will be treated\012       according to the settings of the Crash and Hold bits, if neither\012       is set, Direct is assumed (thus TrapToss will create .DUT files\012       for FileAttach Messages).  \012\012       Currently TrapToss tries to locate the file as given in the\012       subject.  The file name will then be copied to a ".DLO" file\012       (".CLO" or ".HLO" if the Crash or Hold bit of the Message is\012       set). If the file cannot be found, TrapToss will attempt to\012       locate the file in the Inbound directory (to allow the routing\012       of file attaches) and - if found there - copy the file name\012       prefixed by the Inbound directory name to the ".DLO" file.  \012\012       Otherwise (if TrapToss could not locate the file) the subject\012       will be copied to the ".DLO" file as-is, to enable locating the\012       file at mailer run-time (TrapDoor, for instance, will attempt to\012       locate the file in the outbound directory if no path is given).  \012\012       Please note: routing file attaches is far from perfect, right\012       now, we may give this topic additional thoughts in future\012       releases. Currently there is no way to allow local file attaches\012       and disallow file attach routing at the same time; Node systems\012       should set FILEATTACH only for scanning (and NOFILEATTACH for\012       tossing) to prevent TrapToss from routing file attaches.  \012\012       Default setting is NOFILEATTACH.  \012\012\012                               (NO)FORCE4DMO\012                               -------------\012       Causes TrapToss to use 4-dimensional .MOx files for ARCMail\012       bundles. This will override ''OLDSTYLEMO'' (see there).  \012\012       The default setting is NOFORCE4DMO, which - if ''OLDSTYLEMO'' is\012       not set - causes TrapToss to work in "compatibility mode", i.e.\012       bundles addressed to the same Zone which are not addressed to a\012       Point Address other than 0 will have "old style" 2-dimensional\012       filenames (like ''1234abcd.TU1''). All other files will be "new\012       style", e.g. ''2.310.6.4.WE7''.  \012\012       Default is NOFORCE4DMO.  \012\012\012                                 (NO)OUT4D\012                                 ---------\012       Tells TrapToss to create 4-dimensional (new style) .OUT\012       files.  Use this option if you are using a modern Mailer which\012       recognizes these new style files.  \012\012       Default is OUT4D.  \012\012\012                                  (NO)RTD\012                                  -------\012       Adds a little bit of security to Seen-By checking: also the\012       Nodes in the Path line of each Message is checked on\012       exporting/scanning/tossing; exporting is suppressed for Nodes\012       found in the Path line.  \012\012       Default setting is NORTD.  \012\012\012                               (NO)LINKMSGS\012                               ------------\012       On importing this tells TrapToss to link Messages with the\012       same subject (Reply-Linking, Threading).  \012\012       Default is NOLINKMSGS.  \012\012\012                               (NO)DUPCHECK\012                               ------------\012       Switches on the Duplicate Message checking of TrapToss. Causes\012       TrapToss to save all MSGID''s (or CRC''s if none) of incoming\012       Messages to a dup-database (two files called Duplicate.Index and\012       Duplicate.MsgId in your MAIL: directory) and to check for\012       duplicates. Currently all duplicate Messages will be moved to\012       the ''BAD'' Area. Some more options to this will probably be\012       added.  \012\012       Defaults to NODUPCHECK.  \012\012\012                                (NO)MATRIX\012                                ----------\012       In export/scan mode this causes TrapToss to export Matrix-Mail\012       (NetMail) as well as EchoMail. If you are using another NetMail\012       exporter (oMMM, for instance) you should set NOMATRIX.  \012\012       Defaults to MATRIX.  \012\012\012                                (NO)ROUTING\012                                -----------\012       Switches on (off) the routing mode of the Tosser.  \012\012       Default is ROUTING, if export/scan/toss mode is set, otherwise\012       NOROUTING.  \012\012\012                               (NO)CRASHMAIL\012                               -------------\012       Use this keyword to tell TrapToss to allow Crashmail Messages\012       in transit, i.e. incoming Messages with the Crash bit set will\012       be routed as Crashmail. This is useful to allow ''emergency\012       Messages'' to be passed on.  \012\012       Default is NOCRASHMAIL.  \012\012\012                                  CHANGE\012                                  ------\012       Change the flavour of exported Messages.  \012\012                   Syntax is: CHANGE from to nodes\012\012       where ''from'' and ''to'' are one of NORMAL, DIRECT, HOLD and\012       CRASH and ''nodes'' is a list of Fido-Nodes (Wildcards allowed).  \012\012\012                                  PACKER\012                                  ------\012       Tells TrapToss which packer to use for which Node.  \012\012                   Example: PACKER "LHArc a" 310/* 313/*\012                            PACKER "Zoo a" *\012\012       Defines ''LHArc'' as Packer for all Nodes in Nets 310 and 313\012       (of current zone) and ''ZOO'' as Packer for all other nodes.  \012\012       If a node cannot be found in the list of PACKER statements,\012       the command "Arc A" will be used to compress the mail bundle.  \012\012\012                                 UNPACKER\012                                 --------\012       Selects special unpackers for special Nodes. Takes an Unpacker\012       command (a CLI command) and a (wildcarded) list of Nodes to use\012       the unpacker for.  \012\012                   Example: UNPACKER "LHArc x" 310/6 310/11\012                            UNPACKER "Zoo x" 310/*\012\012       If no specific unpacker has been specified for a node,\012       TrapToss will look inside the mail bundle to find out what\012       compression program had been used to create the file. TrapToss\012       knows about Arc, Zoo and LhArc bundles, and will use \012\012                            "Arc x"   for ARCMail\012                            "LhArc x" for LHArcMail\012                            "Zoo x"   for ZOOMail\012\012       In case you prefer your own super-duper versatile\012       de-compressor command for all Bundles (e.g. "RX XArc X") you\012       may as well say \012\012                            UNPACKER "RX XArc x" *\012\012\012                                STRIPNODES\012                                ----------\012       This is the same as ''STRIP'', but has global scoping, i.e. all\012       Nodes specified there will be removed from Seen-By lines of\012       Messages of all Areas.  \012\012       If you are running a node system with points, you will\012       probably want to strip all occurrences of your points from the\012       Seen-By lines (don''t forget to add yourself again!), \012\012                   like in: STRIPNODES 2:310/6.* 2:3160/*\012                            ADDNODES 2:310/6\012\012\012                                 ADDNODES\012                                 --------\012       This keyword takes a list of nodes to be added to Seen-By\012       lines of all exported Messages. In principle this does the same\012       as ''ADD'' (see above), but unlike ''ADD'' this is a global keyword,\012       i.e.  does the adding for all Areas.  \012\012                   Example: ADDNODES 310/6 310/3\012\012       will add ''310/6'' and ''310/3'' to the Seen-By lines of all\012       exported Messages.  \012\012\012                                  NETMAIL\012                                  -------\012       Similar to ''AREA'' this defines the NetMail directory, but\012       unlike ''AREA'' this keyword may only occur once.  \012\012                   Syntax: NETMAIL MAILDIR Mail:Matrix\012\012       For compatibility the name of the Area should be set to\012       ''MAILDIR''.  \012\012\012                                   AREA\012                                   ----\012       Define an EchoMail Area. AREA statements list the Area Tag,\012       under which an EchoMail conference is known throughout the\012       network, plus the directory in which you intend to store\012       Messages from that Area, plus a list of nodes that receive this\012       Area from you (or from which you receive the Area).  \012\012                   Syntax: AREA tag directory {nodes} \012\012       In order to receive Messages in that Area yourself, you have\012       to list your own nodenumber as the first node in that Area. If\012       you do not list yourself among the participants of that echo,\012       the Area will be pass-through, i.e.  Messages in that Area will\012       never be stored on your system, but immediately moved to the\012       outgoing packets in your outbound directory, "on-the-fly".  \012 \012             Example: AREA TRAPDOOR Mail:TrapDoor.Area   310/6 310/6.4\012\012       Adds Area ''TRAPDOOR'' in Directory ''Mail:TrapDoor.Area'' for\012       myself (2:310/6.0) and 2:310/6.4 \012\012       Also, the AREA statement limits the scope of local keywords\012       such as ADD, STRIP, GATE and ALLOW.  \012\012\012                                   ALLOW\012                                   -----\012       Normally, TrapToss will refuse to accept EchoMail from a node\012       that is not listed in your AREA statement for that Area.\012       Instead, it will move the Messages to the BAD Message directory.\012       Sometimes, however, it is desirable to receive Messages in an\012       Area without having the node listed in the export list. An\012       example might be a read-only Area. You can allow certain nodes\012       to send you EchoMail in that Area, using the ALLOW statement.\012       ALLOW is a local keyword, and may only be used after an AREA\012       line, just like the ADD or STRIP commands. ALLOW accepts\012       wildcards.  \012\012                   example: AREA TEST MAIL:Test.area 310/6 310/3 310/42\012                            ALLOW 310/99 3160/*\012\012\012; **********************************************\012; ***   Sample Fido.cfg configuration file   ***\012; **********************************************\012\012Node      14:100/102.0\012AKA       44:100/0.0 99:999/4.0 10:150/100.0 99:999/401.0\012Pointnet  1000\012\012Domain	"fidonet"\012Origin	"Channel X -- Home of /X-FIDO MAILER"\012\012NodeListPath "Mail:NodeList"     ; where to look for nodelist files\012Inbound	    "Mail:Inbound"      ; where incomming mail goes to\012Outbound	    "Mail:Outbound"     ; where outcomming mail goes to\012\012TimeZone	"CET"\012\012[TrapToss]\012\012Unattended\012\012screenmode "NONE"\012LogLevel 4\012LogFile xlog:TrapToss.Log\012\012ScreenMode workbench\012\012FileAttach\012\012;Force4DMO\012;Out4D\012\012RTD\012\012LinkMsgs\012DupCheck\012\012Matrix\012NoRouting\012NOCRASHMAIL\012\012\012change crash hold 99:999/* 99:999/*\012change direct hold 99:999/* 99:999/*\012change normal hold 99:999/* 99:999/*\012\012change crash hold 14:100/* 14:100/*\012change direct hold 14:100/* 14:100/*\012change normal hold 14:100/* 14:100/*\012\012change crash hold 44:100/* 44:100/*\012change direct hold 44:100/* 44:100/*\012change normal hold 44:100/* 44:100/*\012\012change crash hold 2:285/* 2:285/*\012change direct hold 2:285/* 2:285/*\012change normal hold 2:285/* 2:285/*\012\012change crash hold * *\012change direct hold * *\012change normal hold * *\012\012Packer "lz -x0 -f -u -m -P-1 a" *\012UnPacker "rx XArc x" *\012\012StripNodes 14:100/102.* 99:999/4.* 44:100/0.* 44:100/100.*\012AddNodes 14:100/102.0 99:999/4.0 10:150/100.0\012\012; OK. Here are my areas. Each area may have its own local\012; STRIP and ADD commands\012\012;key areaname           directory          nodes who get it\012;¯¯¯ ¯¯¯¯¯¯¯¯           ¯¯¯¯¯¯¯¯¯          ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\012Netmail Netmail 	post:NET	   14:100/102 14:100/102.1\012allow *:*/*\012\012Area BAD                post:BAD           100/102\012\012Area AXF_SALE           post:axf/A-sal     100/102 44:100/100.1\012allow 44:*/*\012\012Area AXF_General        post:axf/A-gen     100/102 44:100/100.1 44:200/100\012allow 44:*/*\012\012Area AXF_COSYSOPS       post:axf/A-cos     100/102 44:100/100.1 44:200/100\012allow 44:*/*\012\012Area AXF_SYSOPS         post:axf/A-sys     100/102 44:100/100.1 44:200/100\012allow 44:*/*\012\012Area AXF_BETATEST       post:axf/A-bet     100/102 44:100/100.1 44:200/100\012allow 44:*/*\012\012Area BOS_COMPUTERS      post:bos/bos1      100/102 99:999/1 99:999/4.1\012allow 99:*/*\012\012Area BOS_GEZWAM         post:bos/bos2      100/102 99:999/1 99:999/4.1\012allow 99:*/*\012\012Area BOS_IRRITATIE      post:bos/bos3      100/102 99:999/1 99:999/4.1\012allow 99:*/*\012\012Area BOS_MUZIEK         post:bos/bos4      100/102 99:999/1 99:999/4.1\012allow 99:*/*\012\012Area BOS_NATUUR         post:bos/bos5      100/102 99:999/1 99:999/4.1\012allow 99:*/*\012\012Area BOS_OORLOG         post:bos/bos6      100/102 99:999/1 99:999/4.1\012allow 99:*/*\012;\012; end of fido.cfg\012\012      ----------------------------------------------------------------\012\012      So.. that is an example for fido.cfg. Again a little explanation\012      about some things.\012\012      Area BOS_OORLOG    post:bos/bos6    100/102 99:999/1 99:999/4.1\012      allow 99:*/*\012\012      This means:\012\012      · The TAGarea is BOS_OORLOG\012      · The messages will be stored in post:bos/bos6\012      · The first nodenumber is YOUR nodenumber\012      · Next are the nodes who get that area\012        (Now node 99:999/1 and Point 99:999/4.1 will get the mail)\012\012      ALLOW 99:*/* means that only nodenumbers beginning with 99: can\012      write in this area. For example, if a bbs with nodenumber \012      2:100/100.0 and brings some mail for area BOS_OORLOG it will be\012      stored in BAD because the nodenumber begins with 2: and that is\012      not allowed!\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012\012@Node trapdoor.key "TrapDoor.KEY - © 1993 Tycoon"\012\012                            TRAPDOOR.KEY\012                            ------------\012\012      Place: MAIL:\012\012      This is the registration Key to run trapdoor, without it trap-\012      door will not work 100%.  You have to registere trapdoor for\012      the keyfile! \012      Register at @{"The Austrian Amiga Developers Association" link TrapDoorReg}.\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012\012@Node TrapToss.Key\012\012                               TRAPTOSS.KEY\012                               ------------\012\012      Place: MAIL:\012\012      This is the registration Key to run TrapToss, without it Trap-\012      Toss will not work 100%.  You have to registere traptoss for\012      the keyfile!\012      Register at @{"The Austrian Amiga Developers Association" link TrapDoorReg}.\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012\012@Node NodeList "NodeList - © 1993 Tycoon"\012\012                                 NODELIST\012                                 --------\012\012      Place: MAIL:NodeList/\012\012      This is the directory where the nodelists of the networks your\012      connected with are.  The /XF-net will be on the /X-Fido disk. This\012      is a nodelist and for all the other nets you need one.  When you\012      have no Nodelist and you want to call a system trapdoor can''t\012      find the telephonenumber because in the nodelists are all the\012      nodenumbers, locations, sysopnames, telnumbers and a lot more.\012\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012@Node Ticks "Ticks - © 1993 by Tycoon"\012\012                                   TICKS\012                                   -----\012\012      Place: MAIL:Ticks/\012\012      This is the directory where all the files moved to that were sent\012      together with the mail. Then SkyTick will send these files along\012      to all the other bbs'' that are in the SkyTick config-file.\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012@Node Inbound "Inbound - © 1993 Tycoon"\012\012                                  INBOUND\012                                  -------\012\012      Place: MAIL:Inbound/\012\012      This is the directory where all the incoming mailpackets will be\012      stored.  Also files that are send with mail will go to this dir\012      and can be moved to the right directory with skytick.\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012@Node OutBound "OutBound Directory - © 1993 Tycoon"\012\012                                 OUTBOUND\012                                 --------\012\012      Place: MAIL:Outbound/\012\012      This is the directory where al the outgoing mailpackets will be\012      stored.  When a bbs called and gets his mail then it will be given\012      and after that it will be deleted.\012\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012\012@Node Mailer "Summery - © 1993 Tycoon"\012\012                                  SCRIPTS\012                                  -------\012\012      All scripts can stored in MAIL:Scripts/ Some scripts are the\012      Poll and the Mailer.\012\012                                   POLL\012                                   ----\012\012      Place: MAIL:Scripts/\012\012      This script will be used to call your MAIN supplier from fidomail.\012      You can clone them to poll.HOl to call me, Poll.USA to poll with a\012      bbs in the states or something like Poll.1 and poll.2.\012\012      Below the contents of the script:\012\012      traptell -PTrapdoor0 "call 44:100/0"\012      \012      What does it mean.   Traptell is a little program that can give\012      orders to trapdoor.  The -P<arexxport> is needed when you have\012      more then 1 node running with trapdoor.  But it is the safest\012      way to include it.  It is the same as in the trapdoor.cfg.  Then\012      the option  that must be executed by trapdoor. Now node 44:100/0\012      will be called. (that is my bbs!)\012      \012\012                                  MAILER\012                                  ------\012\012      Place: MAIL:Scripts/\012\012      This script will be executed when there is an incoming or outgoing\012      fidocall.  It will sort and scan all new mail and import/export\012      it to the other bbs''s.\012      \012      Below the contents of the script:\012\012           Copy Mail:Inbound/#? Mail:Bak Clone\012           cd mail:\012           path mail:bin\012           run >nil: trapdoor config "mail:trapdoor.0"\012           TrapToss Import\012           TrapToss export\012           rx bbs:fidonet/fido-del.rexx\012           run skytick tick\012           endcli\012\012      Some explaning:\012           1st line : This will copy all the new files to a backup dir.\012                      If something goes wrong with importing, the files\012                      will not be lost.\012           2nd line : Change directory to mail:\012           3rd line : Path the dir mail:bin where a lot of programs are\012           4th line : Start trapdoor again. Here must be exactly the\012                      same as in your trapdoor.cfg by BBSCOMMAND!\012           5th line : Run traptoss to import new mail\012           6th line : Run traptoss to export mail for other nodes.\012           7th line : Run fido-del.rexx for cutting messages to MAXMSG\012                      and put a *.NFO with every new *.MSG\012           8th line : Run skytick (Only for filesupport) \012                      Remove in the beginning!\012           9th line : End the job.\012\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012\012@Node tick.cfg "SkyTick.cfg - © 1993 Tycoon"\012\012                                 TICK.CFG\012                                 --------\012\012      Skytick is an utility to send files to other nodes, so you can\012      send ami-express utilities with the mail, or new updates can be\012      transported that way.  Also new nodelists will be transported\012      this way and if the files are in the inbound directory a util\012      must move them... that is the job of skytick.. below a tick.cfg\012      that must be in mail:\012\012;                 <*> SkyTick v3.10 sample configuration file <*>\012;\012; You MUST edit this file in order to supply your needs before using it \012; with SkyTick\012\012; Your address (Points not supported)\012HERE 14:100/102\012\012; A list of your AKAs (memory only limited)\012\012AKA 99:999/4\012AKA 99:999/401\012AKA 44:100/0\012\012; Where to search for inbound *.TIC\012IN xin:\012\012; Your outbound directory\012OUT xout:\012\012: Where to keep the *.TIC and files\012HOLD dh3:ticks/\012\012; Where to move deleted files (requires DLG Pro)\012;DELPATH dh3:bad/\012\012; Turn off the Replace feature (SkyTick won''t delete old files)\012; Default is ENABLED\012REPLACE\012\012; Where put bad files / TICs\012BAD mail:bad/\012\012; This file stores all CRCs and filenames processed in order to stop file dupes\012; if you want to turn off dupes checking comment out the following line.\012DUP xlog:SkyTick.DUP\012\012; This file stores informations about every file SkyTick has processed.\012; It''s used by MakeStat to generate statistic about the files you have\012; moved (files/week, files/day, etc etc).\012; If you don''t need this feature, just comment out the following line.\012STAT xlog:SkyTick.Stat\012\012; This is the pathname of a SkyFreq 3.00-style Index file generated by MakeIndex,\012; SkyTick uses this file to check if a file already exists in the file areas,\012; before uploading it.\012; If you don''t want this feature, just comment out the following line.\012; INDEX DLGConfig:Misc/SkyFreq.Data\012\012; Turns on the automatic CRC checking.\012;CHECK_CRC	\012\012; Comment out the following line if you want SkyTick to operate in a GENERIC\012; fashion, i.e. running it without DLG Pro.\012GENERIC\012\012; Pathname to the log file\012LOGFILE xlog:Tick.LOG\012\012; This is for message announcements...\012; LIST <match> <filename> <string>\012;\012; Tokens available for <string>:\012; \n   - Put a line feed (C style)\012; %n   - Put filename\012; %l   - Put file lenght\012; %d   - Put file description\012; %o   - Put file origin\012; %a   - Put AreaTag\012; %t   - Put file date\012; %c   - Put file CRC\012\012LIST * xlog:TICKFILES.TXT ------------------------------------------------------------------------------\n\n Nome file   : %n\n Lunghezza   : %l\n Descrizione : %d\n Ricevuto da : %o - %t\n\n\012\012; The Passwords\012PASSWORD 14:100/0      What\012PASSWORD 2:285/312     Are\012PASSWORD 2:280/452     They?\012\012; This is area SKYCOMMS and all files will be uploaded to DLG file area 5, if\012; you run SkyTick in a GENERIC fashion, you should place the path (instead of \012; the area number) where SkyTick should place the files.\012; FILEECHO SKYCOMMS  #5\012; or in a GENERIC fashion :\012\012FILEECHO XENOL  dh4:xenolinkfiles/\012\012; Set Amiga style echo (no checking of illegal characters in filenames)\012TYPE AMIGA\012\012; Set FREE flag for this files\012FREE\012\012; Disable Dupe checking for this area\012;NODUPE\012\012; Don''t copy the file in the hold dir, but make TrapDoor to take it from\012; the DLG file area\012; NOHOLD\012\012; Put the files in hold for this node (only for this area!!), accept files \012  and send both files and tics.\012\012TO 99:999/5 	&%*H\012TO 99:999/403   &%*H\012TO 99:999/413   &%*H\012\012;\012; Whith TO you can specified what nodes also gets the files that were\012; with the mail.\012;\012\012FILEECHO XENOG  dh4:xenolinkfiles/\012TYPE AMIGA\012FREE\012TO 99:999/5 	&%*H\012TO 99:999/403   &%*H\012TO 99:999/413   &%*H\012\012FILEECHO NLA_NLST   Nodelist:\012TYPE AMIGA\012FREE\012TO 14:100/102.1 	&%*H\012TO 14:100/102.2         &%*H\012TO 14:100/102.3         &%*H\012TO 14:100/102.4         &%*H\012\012FILEECHO NLA_NDFF   Nodelist:\012TYPE AMIGA\012FREE\012TO 14:100/102.1 	&%*H\012TO 14:100/102.2         &%*H\012TO 14:100/102.3         &%*H\012TO 14:100/102.4         &%*H\012\012; Valid flavours are :\012;\012; * -> Enable receiving \012; & -> Enable sending files\012; % -> Enable sending tics\012; C -> Crash mode\012; H -> Hold mode\012; D -> Direct mode\012; N -> Normal mode\012;\012;\012; Default is *%&H\012; Execute "c:rx rexx:myscript %a %n "%d" %c" each time a file is \012; received/hatched in this area. Available tokens are :\012; %a  - Areatag\012; %n  - Filename\012; %t  - Time & date the file was received\012; %l  - File lenght\012; %c  - File CRC\012; %d  - File Description\012; %z  - File Origin (zone)\012; %f  - File Origin (net)\012; %q  - File Origin (node)\012; %p  - File Origin (point)\012;\012; END OF tick.cfg\012\012      This was the config file... For more info, you have to look into\012      the official skytick package. \012\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012\012@Node trapdoor.x "Trapdoor.x - © 1993 Tycoon"\012\012                                TRAPDOOR.X\012                                ----------\012\012      If you want set up a multiplex nodesystem with more lines with\012      @{"TrapDoor" link TrapDoor} you have to make a @{"Trapdoor.cfg" link TrapDoor.CFG} file for every line.\012      The best way to make it, is to have a trapdoor.cfg with in it:\012      \012      ; This is just 1 line to have a trapdoor.cfg\012\012      That was all in trapdoor.cfg.  Now you can use the trapdoor.cfg\012      what is in this doc and set it on the hd as trapdoor.0 if you have\012      one line, and also as TrapDoor.1 if you have 2 lines.\012 \012      You have to begin with 0. So if that was your local node, than you\012      have to change that one for another.\012\012      For example I have a MultiFace 2 multi-serial card. The serial\012      units on it are 0 and 1.  To start Express you need to give some\012      options. The options are : Express <node> <linespeed>.\012      You can give for node the serial-unit number and for linespeed\012      you can use the connect from TrapDoor itselfs. so it will be:\012      Express %u %B\012      \012      Also every trapdoor must have his own Rexxname and logfilename.\012      Below a example for setting up 2 lines with the MF2 card:\012\012      Use the trapdoor.cfg what was on the /XF disk and copy it as\012      trapdoor.0 and trapdoor.1 in mail:\012      Then change in trapdoor.0:\012\012                   BBSCOMMAND "bbs:utils/Express %u %B"\012                   LOGFILE "xlog:Node-0.Log"\012                   REXXNAME "Trapdoor0"\012                   SERIALNAME "duart.device"\012                   SERIALUNIT 0\012                   SERIALFLAGS 0\012\012      Then change in trapdoor.1:\012\012                   BBSCOMMAND "bbs:utils/Express %u %B"\012                   LOGFILE "xlog:Node-1.Log"\012                   REXXNAME "Trapdoor1"\012                   SERIALNAME "duart.device"\012                   SERIALUNIT 1\012                   SERIALFLAGS 0\012\012      Now you have 2 lines with trapdoor.\012\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012\012@Node trapdoor.cfg "Trapdoor.cfg - © 1993 Tycoon"\012\012                               TRAPDOOR.CFG\012                               ------------\012\012; **********************************************************************\012; **                                                                  **\012; **               TrapDoor 1.83 Example Configuration File           **\012; **                                                                  **\012; **********************************************************************\012FORBIDFREQ\012\012NOALLOWREFUSING\012DIRECTZAP\012ZEDZIP\012WAZOO\012DIETIFNA\012ZEDZAP\012\012PICKUP ALL\012NOBEEPDISPLAY\012EMSI\012\012TASKPRI 0\012;NOFASTEMSI\012\012Aftersession "run newcli con:0/100/640/200/MAILING  mail:scripts/mailer"\012\012NODE 44:100/0.0\012\012AKA "10:100/150.0 99:999/401.0 99:999/4.0 14:100/102.0"\012\012NAME "/XF-SUPPORT-WHQ => CHANNEL X"\012\012SYSOP "Piet van Stralen"\012\012PASSWORD "SHIT"\012\012BAUD 38400\012LOCK\012\012MINBAUD 2400\012\012BOSS 44:100/0.0\012\012OUTBOUND "mail:outbound"\012\012INBOUND "mail:inbound"\012\012NODELIST "nodelist:"\012\012NOMAXBAUD\012\012RINGS 1\012\012BANNER "CHANNEL X  -- RUNNING Ami-eXpress"\012\012DROPBBSSECS 15\012\012BBSCOMMAND "bbs:utils/Express 1 %B"\012;BBSINOUT ""\012BBSMODE SPAWN\012\012LOGFILE "xlog:trapdoor.Log"\012\012LOGLEVEL 0:2		; debugger\012LOGLEVEL 1:2		; link\012LOGLEVEL 2:2		; transfer\012LOGLEVEL 3:2		; system\012LOGLEVEL 4:2		; modem\012LOGLEVEL 5:2		; session\012LOGLEVEL 6:7		; security\012LOGLEVEL 7:2		; outside\012LOGLEVEL 8:7		; information\012LOGLEVEL 9:2		; scheduler\012\012SLOWMODEM 10\012\012MODEMINIT "~~ATZ|~~~~"\012MODEMHANGUP "||^|"\012MODEMDIALPRE "~~ATDP,"\012MODEMDIALPOST "|"\012MODEMANSWER "~~ATA|"\012\012SNIFFARQ\012ARQSTRING "ARQ" \012\012SERIALNAME "serial.device"\012SERIALUNIT 0\012SERIALFLAGS 0\012\012SHARED\012\012DSR\012\0127WIRE\012\012ADJUST -11\012\012FREQUEST ""\012\012REXXNAME "Trapdoor"\012\012LOGWINDOW 0/123/722/40\012STATWINDOW 0/163/722/40\012\012SCREENMODE PUBLIC\012PUBSCREENNAME "bbs"\012\012NOBACKGROUND\012AUTOOVERSCAN\012\012COLORS 2560/4095/10/160\012\012RETRIES 0\012REDIALDELAY 3\012\012ANSWER\012\012; END OF CONFIG FILE\012\012\012                                 (NO)7WIRE\012                                 ---------\012\012      Enable/disable 7-wire cabling. This will instruct the serial\012      device to use (or not to use) the CTS and RTS signals. If you\012      are using high speed modems with data compression, such as a US\012      Robotics Courier HST, you must use 7WIRE handshake and you must\012      set your modem to "hardware handshake" mode, otherwise various\012      difficulties will arise.  \012\012                   Examples: 7Wire \012                             No7Wire \012\012                               ADJUST FACTOR\012                               -------------\012\012      NOTE: the following explaination is only valid for AmigaOS up\012      to 1.3. The serial device has been dramatically improved in\012      AmigaOS 2.04. If you have AmigaOS 2.04 or higher, set ADJUST to\012      zero or leave it out completely.  \012\012      Unfortunately, the Amiga serial.device software has a small\012      problem with baudrates: not only will it calculate the value to\012      stuff into the baudrate register of the serial hardware\012      incorrectly and therefore use baudrates that are a bit offset\012      from the correct value, but also this behaviour is different on\012      NTSC and PAL machines, which makes it even worse.  \012\012      Some modems will work fine with such slightly wrong baudrates,\012      others will not tolerate this and give a lot of transmission\012      errors. By the way, this - it seems - is the main reason why\012      programs such as BinkleyTerm Amiga fail to work with high-speed\012      modems.  \012\012      TrapDoor offers you a cure for such problems: ADJUST allows\012      you to specify how much TrapDoor will vary any given baudrate\012      before it passes it on to the serial.device. This value should\012      be given in thousands (1/1000).  An example: at the default\012      value of -11, a baudrate of 2400 will be adjusted to 2400-1.1% =\012      2400-26.4 = 2373.6 baud. This value will be rounded to an\012      integer and passed to the serial.device, which will then\012      miscalculate the values for the hardware registers and set the\012      hardware to almost exactly 2400 baud.  \012\012      Normally, you should leave this parameter at the default\012      value. If you have a HST or similar buffering modem, you can try\012      to set it to zero.  If you happen to live in the US (or any\012      other country using 60 Hz video systems), you will probably have\012      to set it to zero, or maybe even something else. Experiment! \012 \012                   Example: Adjust -11 \012\012                        AFTERSESSION COMMAND-STRING\012                        ---------------------------\012\012      As soon as TrapDoor finishes a FidoNet session with another\012      mailer, and hangs up the modem, it will call the command you\012      specify here. There may be embedded %-commands, which will be\012      substituted by the parameters of the session that just ended; a\012      list of them can be found in the chapter "Embedded\012      Percent-Commands". To turn off the AFTERSESSION command, use\012      AFTERSESSION "" or omit the statement completely.  \012\012          Examples: AfterSession "run Execute Script:CheckInbound" \012                    AfterSession "" \012\012                                AKA AKALIST\012                                -----------\012\012      During the EMSI handshake, not only your main address, but\012      also a list of other "also-known-as" addresses will be sent to\012      the other system. Using the AKA keyword, you can specify all\012      your AKA addresses. <akalist> should be a single string, listing\012      all your other addresses.  \012\012      There is a limit of 20 AKAs for your system.  \012\012                   Example: Aka "2:3160/0 2:31/0 27:47/11" \012\012                             (NO)ALLOWREFUSING\012                             -----------------\012\012      Enables (disables) AllowRefusing mode. Default is ALLOWREFUSING.  \012\012      When AllowRefusing is enabled, TrapDoor respects the other\012      end''s wishes in the EMSI handshake. When the other end states it\012      does not want to receive any compressed mail, for example,\012      TrapDoor won''t send it. With NoAllowRefusing, TrapDoor will\012      always send what has to be sent.  \012\012      Examples: AllowRefusing \012                NoAllowRefusing \012\012                                  ANSWER\012                                  ------\012\012      Forces TrapDoor to operate in "answer mode". TD will then wait\012      for a call, answer the phone and try to start a session with the\012      remote system.  While in answer mode, TrapDoor will accept\012      commands via its ARexx interface.  \012\012\012                             ARQSTRING STRING\012                             ----------------\012\012      Tells TrapDoor what string the modem returns when it connects\012      to another modem under an error-control protocol. HST modems,\012      for example, return the string "ARQ" as in "CONNECT\012      9600/ARQ/HST/HST".  \012\012      You must setup the correct ARQSTRING for your modem when you\012      use FLOATLOCK and/or SNIFFARQ.  \012\012      Example: ArqString "ARQ" \012\012                             (NO)AUTOOVERSCAN\012                             ----------------\012\012      When using the SCREENMODE CUSTOM, SCREENMODE TRAPDOOR or\012      SCREENMODE PUBLIC option, switching this on forces TrapDoor to\012      open its screen not to the standard NTSC or PAL size, but to the\012      maximum size of the Workbench screen. If you use a program like\012      "MoreRows" to expand your Workbench screen (under Kickstart\012      1.2/1.3) or use extended Overscan settings under AmigaOS 2.04\012      (or higher), and you would like TrapDoor to use the same\012      expanded screen size, use this parameter.  \012\012      Examples: AutoOverScan \012                NoAutoOverScan \012\012                              (NO)BACKGROUND\012                              --------------\012\012      When BACKGROUND is turned on, TrapDoor will open its screen\012      behind all other screens. Also, when the log and status window\012      are opened, they will not be activated, so your currently\012      activated window will stay activated.  \012\012\012                             BANNER BANNERLINE\012                             -----------------\012\012      This line will be sent to the other side when TrapDoor answers\012      a call.  This typically identifies your system, says "hi", or\012      tells human callers to hang up.  \012\012      Instead of a single line, TrapDoor can also send a text file.\012      In that case, use "<filename" as your BANNER (where filename\012      should indicate your banner file). Note that your banner file\012      should not be too long. A few lines will suffice. TrapDoor will\012      automatically convert LFs to CRLFs when sending the file.  \012\012      Examples: Banner "TrapDoor Development, online 00:00-06:00" \012                Banner "<mail:banner.txt" \012\012                               BAUD BAUDRATE\012                               -------------\012\012      This is the baudrate to initially talk to the modem -- after\012      power-on or a reset. This speed may change during a session,\012      when you did not lock the baud rate (see LOCK) and a different\012      speed is reported by the modem.  \012\012      Example: Baud 2400 \012\012                         BBSCOMMAND COMMAND-STRING\012                         -------------------------\012\012      This is used to set the command line that TrapDoor will\012      execute to start a BBS. There may be embedded %-commands, these\012      are described in the chapter "Embedded Percent-Commands".  \012\012      When a human caller presses ESC, the %-commands will be\012      replaced with the corresponding value and then the resulting\012      string will be executed.  \012\012      BBSCOMMAND will only be used if the BBSMODE is set to SPAWN or\012      EXIT.  \012\012      Examples: BBSCommand "express %u %B" \012                BBSCommand "express 1 %B"\012\012                              BBSINOUT DEVICE\012                              ---------------\012\012      This can be used to set stdin and stdout for the BBSCOMMAND to\012      something else than those of the initial CLI from which TrapDoor\012      was started. Just set it to any valid AmigaDOS device, like AUX: \012\012      To switch off this feature, use BBSINOUT "".  \012\012      Example: BBSInOut AUX: \012\012                               BBSMODE MODE\012                               ------------\012\012      There are four modes available for connecting a BBS to TrapDoor:\012\012          NONE ... There is no BBS, TrapDoor will display\012                   "Mail only system -- please hang up" to\012                   human callers.\012\012          SPAWN .. TrapDoor will use the BBSCOMMAND setting\012                   to start the BBS when a human caller\012                   enters an ESC character. When the command\012                   returns, TrapDoor will reinitialize the\012                   modem and continue to wait for a call.\012\012          EXIT ... TrapDoor will start the BBSCOMMAND just\012                   as with SPAWN, but as soon as the command\012                   returns, TrapDoor will exit.\012\012          ZMH .... There is a BBS, but at the moment, human\012                   access to the BBS is closed due to\012                   "Zone Mail Hour". TrapDoor will display\012                   "Mail only period -- please call later"\012                   to human callers.\012\012      Examples: BBSMode Spawn \012                BBSMode None \012                BBSMode ZMH \012\012\012                              (NO)BEEPDISPLAY\012                              ---------------\012\012      When BEEPDISPLAY is enabled (the default), TrapDoor will flash\012      the screen when the modem sends a CONNECT message. You can\012      disable this with NOBEEPDISPLAY.  \012\012      Example: NoBeepDisplay \012\012\012                         BOSS ZONE:NET/NODE.POINT\012                         ------------------------\012\012      Specifies the FidoNet address of your boss, as in "2:310/3".\012      Please be careful as not to leave out the zone and point\012      information when your boss node is capable of four dimensional\012      addressing.  \012\012      Note: the setting of BOSS also specifies what mail will be\012      sent to the other system when you call out using a telephone\012      number. So, if you are calling 2:310/3 with "TrapDoor call\012      0043-1-454330" to request a file, you have to set BOSS to\012      2:310/3 for that call, too.  \012\012      Just to be on the safe side: if you are running a node, set\012      this to your own address.  \012\012      Example: Boss 2:310/6 \012\012                       COLORS  PALETTE-SPECIFICATION\012                       COLOURS PALETTE-SPECIFICATION\012                       -----------------------------\012\012      When you use SCREENMODE CUSTOM, SCREENMODE TRAPDOOR or\012      SCREENMODE PUBLIC (see SCREENMODE), you can change the colors\012      with this option. The palette specifier looks rather like a\012      window specification, starting with color 0 (the background\012      color) and continuing to color 3. The value for each color is\012      given in decimal, using the formula \012\012          color = red * 256 + green * 16 + blue \012\012      where red, green and blue specify the intensity of each color (0\012      is none, 15 is highest intensity). As an alternative, each value\012      can also be given in hexadecimal notation, if prepended with a\012      dollar sign ("$").  \012 \012      If you don''t specify the colors yourself, TrapDoor will use\012      the most stunning internal defaults.  \012\012      Examples: Colours 2730/0/2560/10 \012                Colors $aaa/$000/$a00/$00a \012\012                               (NO)DIETIFNA\012                               ------------\012\012      Enable (disable) DietIfna mode. Choose this, when you only\012      transfer small files or when the line quality is rather poor\012      since it might then be faster than ZModem.  \012\012      Examples: NoDietIfna \012                DietIfna \012\012                               (NO)DIRECTZAP\012                               -------------\012\012      Enable (disable) DirectZap mode. DirectZap is a slight variant\012      of the ZedZap transfer protocol, which is a slight variant of\012      Zmodem -- on large files, this is the fastest protocol TrapDoor\012      has to offer. Like ZedZap, DirectZap will automatically switch\012      block sizes depending on modem speed and quality of the line. It\012      will also resume an interrupted transfer if possible.  \012\012      DirectZap only works in EMSI mode and only if the other side\012      also supports it. Also, DirectZap only works on 8-bit\012      transparent lines. You should disable it (use NODIRECTZAP) if\012      you are working over a non-transparent line like a\012      packet-switching network, for example.  \012\012      Examples: NoDirectZap \012                DirectZap \012\012\012                            DROPBBSSECS SECONDS\012                            -------------------\012\012      When TrapDoor cannot detect a Fidonet handshake after\012      DROPBBSSECS seconds, it will assume the caller is a human and\012      pass the call to the BBS just as if the human had pressed Escape\012      twice. You may not set DROPBBSSECS to anything lower than 10\012      seconds. It defaults to 20 seconds.  \012\012      Example: DropBBSSecs 45 \012\012                                  (NO)DSR\012                                  -------\012\012      After TrapDoor opens the serial.device, it will wait a short\012      while (depending on SLOWMODEM) and then sample the DSR line.\012      This line should be activated when a valid data set (i.e. a\012      functioning modem) is connected to the serial line. If TrapDoor\012      doesn''t find DSR activated, it will report "! modem not ready"\012      and abort.  \012\012      There are a few modems that cannot properly handle DSR. For\012      these modems, use the NODSR setting. Note that when using NODSR,\012      TrapDoor can''t tell whether the modem is powered-on, on-line and\012      ready.  \012\012      Also note that if you have not connected DSR to the modem (if\012      you have a wrong/bad cable), RTS/CTS handshake might not work\012      correctly. This is due to the way the Amiga serial.device\012      handles things.  \012\012      Examples: NoDsr \012                Dsr \012\012                                 (NO)EMSI\012                                 --------\012\012      Turns the EMSI handshake on or off.  \012\012      Note that the EMSI protocol is rather new. Although EMSI is\012      designed to be backwards compatible to older mailers, some fail\012      when presented an EMSI handshake packet. If you experience any\012      session handshake failures with other mailers, try again with\012      EMSI disabled (use the NOEMSI switch).  \012\012      If you regularly call a node that cannot handle EMSI, you can\012      set up a custom configuration string for that node. See the\012      chapter "Custom Configuration Entries".  \012\012      Examples: NoEmsi \012                Emsi \012\012                               (NO)FASTEMSI\012                               ------------\012\012      Per default, FASTEMSI is enabled and this is what TrapDoor has\012      been doing all the time since it could do EMSI: immediately\012      after the connect, it will try to detect whether the other\012      system can do EMSI, and if the other end indicates this, it will\012      immediately start the handshake.  \012\012      This "fast" variant of EMSI can however, under very rare\012      circumstances, give problems. One of the things that might lead\012      to problems are asterisks ''*'' in banner texts. If you call a\012      system and repeatedly experience EMSI handshake failures, try\012      turning off "fast" emsi with the NOFASTEMSI switch.  \012\012      When fast EMSI is turned off, EMSI handshakes will be a little\012      bit slower (about 1-2 secs).  \012\012      Examples: FastEmsi \012                NoFastEmsi \012\012                       FKEY FUNCTION-KEY-ASSIGNMENT\012                       ----------------------------\012\012      Assign a configuration command string to a function key. The\012      keyword must be followed by a single string, starting with the\012      number of the function key (F1=1, F2=2,...; Shift-F1=11,\012      Shift-F2=12,...), followed by a colon (":"), followed by the\012      assignment.  \012\012      If you wish to include spaces in the assignment, the argument\012      must be enclosed in double-quotes; to include quotes within the\012      quoted string, use the backslash ("\") as an escape character.  \012\012      Examples: FKey "1:Emsi" \012                FKey "11:NoEmsi" \012                FKey "5:Call Boss" \012                FKey "6:Run CE" \012                FKey "7:Run \"Execute Scripts:Import\"" \012                FKey "8:Run \"TrapPoll +r\"" \012\012                               (NO)FORBID...\012                               -------------\012\012      Select what type of mail/files you do _not_ want to be sent.\012      In an EMSI handshake, TrapDoor will ask the remote system to not\012      send these files (the other end may override this with the\012      NOALLOWREFUSING switch): \012\012        - FORBIDXMAIL   Compressed mail and file attaches \012        - FORBIDFREQ    File requests \012        - FORBIDALL     All of the above \012\012      Examples: ForbidXMail \012                NoForbidFreq \012\012                          FREQUEST COMMAND-STRING\012                          -----------------------\012\012      Sets the command to be executed as a file-request server on\012      received file requests from remote systems. There may be\012      embedded %-commands, these are described in the chapter\012      "Embedded Percent-Commands".  \012\012      The called command should then read the remote''s request from\012      the %i file, perform any action that it wants to do, and write a\012      list of files that it wishes to send to the other side\012      (including directory path) to the %o file.  \012\012      To turn off the file-request capability, use FREQUEST "".  \012\012      Please note that the answering of file-requests is disabled in\012      unregistered versions of TrapDoor. The external file-request\012      server will not be called.  \012\012      Examples: FRequest "rx frequest %i,%o,%l" \012                FRequest "" \012\012\012                      INBOUND INBOUND-MAIL-DIRECTORY\012                      ------------------------------\012\012      This should point to the directory where incoming files will\012      be put.  Usually "Mail:Inbound". Make sure that the TrapDoor\012      inbound directory is the same as the one for your mail tosser,\012      or your attempts to import mail will fail miserably.\012      Additionally, TrapDoor uses this directory for temporary files\012      during receiving and for files that store information about\012      aborted/interrupted file transfers, so that receiving these\012      files can be resumed in the next ZedZap session. For more\012      information, see chapter "Inbound Directory".  \012 \012      Examples: Inbound "Mail:Inbound" \012\012                                 (NO)LOCK\012                                 --------\012\012      Lock (do not lock) the baudrate. If the baudrate is locked,\012      and TrapDoor receives a "CONNECT XXXX" message from the modem,\012      TrapDoor will not adjust the baud rate to XXXX, but continue to\012      operate at the rate specified with the BAUD keyword. Use this\012      for buffered modems that convert the baud rates internally (for\012      example, HST). Be sure to also configure the modem for a locked\012      baudrate in that case (i.e. on HSTs, use &B1).  \012\012      Examples: NoLock \012                Lock \012\012                             LOGFILE FILENAME\012                             ----------------\012\012      Sets the name of the logfile.  \012\012      Example: Logfile "Mail:TrapDoor.Log" \012\012                           LOGLEVEL GROUP:LEVEL\012                           --------------------\012\012      Sets the amount of logging information to be put into the\012      logfile.  There are ten logging groups, each of which deals with\012      a different part of messages (such as modem, outbound, session\012      protection, file transfers, general messages, external messages\012      etc.). Each group maintains its own loglevel, which ranges from\012      0 to 7. A list of all log messages together with their groups\012      and levels can be found in the file "LogMsgs.doc".  \012\012        The groups: \012\012          0  Debugger    ?  debugging messages, internal errors \012          1  Link        -  line is too bad, baudrate too low \012          2  Transfer    |  receiving xyz.txt, cps rates \012          3  System      !  deleting file xyz.txt, user break, out of\012                            mem \012          4  Modem       ~  NO CARRIER, BUSY, RING, VOICE \012          5  Session     =  Begin of session, picking up mail, session\012                            aborted, giving mail to, session connect\012                            time, cost \012          6  Security    *  bad password, unlisted system, node is\012                            undialable \012          7  Outside     x  spawning dialer, executing aftersession,\012                            spawning bbs \012          8  Information :  sysop, name, aka, place, flags, using,\012                            trxid \012          9  Scheduler   +  waiting for call, incoming call detected,\012                            calling node \012\012        The levels: \012\012          0  Silent         minimum logging \012          1  Terse          terse logging \012          2  Discreet       normal logging \012          3  Verbose        detailed logging \012          4  Talkative      extensive logging \012          5  Excessive      very much logging \012          6  Annoying       even more logging \012          7  Monologue      maximum logging \012\012      Two (Discreet) seems to be a rather nice logging level and is\012      the default for all groups. You might want to turn on more\012      detailed logging in the Security and Information groups.  \012\012      Examples: Loglevel 5:3 \012                Loglevel 4:4 \012\012                      LOGWINDOW WINDOW-SPECIFICATION\012                      ------------------------------\012\012      Use this keyword to change the position and size of the log\012      window that TrapDoor opens. The window specification looks\012      rather similar to a normal AmigaDOS CON:, RAW: or NEWCON:\012      specification, but omit the device name and the window name. The\012      correct format is: LeftEdge/TopEdge/Width/Height i.e. something\012      like 0/20/640/150 \012\012      Example: LogWindow 0/20/640/150 \012\012                                (NO)MAXBAUD\012                                -----------\012\012      If turned on, the MINBAUD parameter will automatically be set\012      to the baudrate of the called system (found in the nodelist) or\012      the own baudrate (set with BAUD) on outgoing calls, whichever is\012      lower.  \012\012      What is this good for? Let us assume you have a 2400 baud\012      modem, and you wish to call a node that is also capable of 2400\012      baud. His nodelist entry also says he can do 2400 baud. Now, if\012      you call him, sometimes, when line noise appears just when the\012      modems negotiate the connect speed, this may cause a connection\012      only at 1200 baud, or even worse, at 300 baud. If you have\012      MAXBAUD enable, TrapDoor will immediately hang up in such a\012      case.  \012\012      On the other hand, if you are using an HST modem, and you are\012      calling a system with a Trailblazer PEP modem, you might have\012      problems when you use MAXBAUD: if the nodelist entry for the PEP\012      modem specifies 9600 baud, TrapDoor will hang up if the connect\012      speed is lower than 9600 baud. But: HST modems and PEP modems\012      use a different high speed protocol and can only talk at 2400\012      baud to each other. So, TrapDoor will hang up every time you\012      call such a system.  \012\012      You have to decide whether the usage of MAXBAUD is appropriate\012      for you or not. You can also set up custom configuration entries\012      to select specific MINBAUD values for selected nodes. See the\012      chapter "Custom Configuration Entries" for more details.  \012\012      Note: setconfig <node> NOMAXBAUD won''t work. See the chapter\012      "Bugs? Poof! They''re all features!".  \012\012      Examples: NoMaxBaud \012                MaxBaud \012\012                             MINBAUD BAUDRATE\012                             ----------------\012\012      Minimal baudrate to establish a connection. Connections at\012      baud rates below this limit will not be allowed, no matter if\012      incoming or outgoing.  TrapDoor will hang up immediately if the\012      baud rate is lower than the value specified.  \012\012      Example: MinBaud 1200 \012\012\012                      MODEMANSWER MODEM-ANSWER-STRING\012                      -------------------------------\012\012      Modem answer string like "AT~A|". For special characters like\012      "~", "^" and "|" that are allowed in the string, see chapter\012      "Modem Commands". The total length of the string may not exceed\012      100 characters.  \012\012      This string is sent to the modem whenever TrapDoor detects a\012      "RING" and wants to answer the phone.  \012\012      Example: ModemAnswer "ATA|" \012\012\012                    MODEMDIALPRE MODEM-PRE-DIAL-STRING\012                    ----------------------------------\012\012      Modem dial string such as "AT~DP" or "AT~DT". For special\012      characters like "~", "^" or "|" that are allowed in the string,\012      see chapter "Modem Commands".  The total length of the string is\012      limited to 100 characters.  \012\012      This string is sent to the modem whenever TrapDoor wants to\012      dial a number. After sending this string, TrapDoor will send the\012      telephone number to dial, followed by the MODEMDIALPOST string.  \012\012      Example: ModemDialPre "ATDP" \012\012                   MODEMDIALPOST MODEM-POST-DIAL-STRING\012                   ------------------------------------\012\012      Modem dial string such as "|". For special characters like\012      "~", "^" and "|" that are allowed in the string, see chapter\012      "Modem Commands".  The total length of the string is limited to\012      20 characters.  \012\012      This string is sent to the modem after the telephone number,\012      when TrapDoor wants to dial a number. Also see the description\012      of MODEMDIALPRE.  \012\012      Example: ModemDialPost "|" \012\012\012                      MODEMHANGUP MODEM-HANGUP-STRING\012                      -------------------------------\012\012      This string will be sent to the modem whenever TrapDoor wants\012      to hang up the line. There are many methods to accomplish this,\012      including the strange "~~~+++~~~ATH|" method. We do not\012      recommend this. If you have configured your modem according to\012      the descriptions in the chapter "The Modem", it should hang up\012      as soon as DTR is lowered. So, the recommended hangup string is\012      "|^|".  \012\012      For special characters like "~", "^" and "|" that are allowed\012      in the string, see chapter "Modem Commands". The total length of\012      the string is limited to 40 characters.  \012\012      Example: ModemHangup "|^|" \012\012                        MODEMINIT MODEM-INIT-STRING\012                        ---------------------------\012\012      This string will be sent to the modem during the\012      initialization phase of TrapDoor. Things like "AT~S7=20|" can be\012      done here. For special characters like "~", "^" and "|" that are\012      allowed in the string, see chapter "Modem Commands". The total\012      length of the string is limited to 160 characters.  \012\012      TrapDoor will also check if it gets any response from the\012      modem after sending this init string. The modem should at least\012      send something like "OK". In fact, any carriage-return\012      terminated string from the modem will suffice.  \012\012      If TrapDoor is unable to detect a response from the modem, it\012      will report "Initializing modem failed" and exit.  \012\012      Example: ModemInit "ATZ|" \012\012                             NAME BOARD''S NAME\012                             -----------------\012\012      Name of this system -- to be sent to the other system during\012      the beginning of a mail session. The length of the string is\012      limited to 60 characters.  \012\012      Example: Name "The Mad House -- TrapDoor Development" \012\012                         NODE ZONE:NET/NODE.POINT\012                         ------------------------\012\012      Sets your own FidoNet address.  \012\012      Just set this to your own address.  \012\012      Examples: Node 2:310/3.14 \012                Node 2:310/6 \012\012\012                        NODELIST NODELIST-DIRECTORY\012                        ---------------------------\012\012      Set this to the directory where you keep your nodelist files.\012      TrapDoor understands only nodelist files generated by its own\012      nodelist processor, TrapList.  TrapDoor now uses the\012      "traplist.library", which should be in your LIBS: directory, to\012      access the nodelist.  \012\012      To disable the nodelist support in TrapDoor, use NODELIST "".  \012\012      Examples: Nodelist "Mail:Nodelist" \012                Nodelist "" \012\012                     OUTBOUND OUTBOUND-MAIL-DIRECTORY\012                     --------------------------------\012\012      This should point to the directory where outgoing files are\012      kept. It should contain all the necessary #?.REQ, #?.FLO, #?.HLO\012      and #?.CLO files and the associated mail bundles. TrapDoor will\012      automatically maintain and delete these files as they get sent\012      out. Usually set to "Mail:Outbound".  For more information, see\012      chapter "Outbound directory".  \012\012      Example: OutBound "Mail:Outbound" \012\012                             PASSWORD PASSWORD\012                             -----------------\012\012      Specifies the password to be used for mail sessions.  \012      On an outgoing call, if your password does not match the\012      password that the other system has set up for you, you will be\012      disconnected at the session handshake.  \012\012      On incoming calls, if the password of the remote system does\012      not match the password you specified here, this will be detected\012      during the session handshake, recorded in the log file and the\012      caller/callee will politely be shown the way out (i.e.\012      disconnected).  \012\012      If Nodelist support has been enabled by setting the NODELIST\012      parameter, passwords will be fetched from there, unless the\012      other system is not found in the nodelist.  \012\012      Example: Password "secret" \012\012                                PICKUP WHAT\012                                -----------\012\012      Select what mail and files to pickup (receive) from the remote\012      system. These "Pickup Preferences" will only work if an EMSI\012      handshake was used at the beginning of the session. There are\012      three possible pickup values: \012\012        - ALL     Pick up mail and files for all of my addresses\012                  (primary address + AKAs) \012        - PRIMARY Pick up mail and files for the primary address only \012        - NONE    Do not pick up mail or files at all \012\012      Examples: Pickup Primary \012                Pickup All \012                Pickup None \012\012                            PUBSCREENNAME NAME\012                            ------------------\012\012      If you use SCREENMODE PUBLIC, this keyword allows you to\012      specify the name of the public screen that TrapDoor should use.\012      If a public screen with this name already exists, TrapDoor will\012      open its windows there. If it does not exist, TrapDoor will open\012      one.  \012\012      Expert Notice: when TrapDoor opens the public screen, it will\012      AllocVec() a buffer for the screen title. If any other program\012      than TrapDoor closes the public screen, a few bytes of memory\012      will be lost. If you are confused now and don''t quite understand\012      what I mean, just ignore it. :-) \012\012        PUBSCREENNAME defaults to "TrapDoor".  \012\012      Example: PubScreenName "Hugo" \012\012\012                            REDIALDELAY SECONDS\012                            -------------------\012\012      This specifies the amount of time TrapDoor spends idling\012      between calls to a system. Note that TrapDoor will not accept\012      incoming calls while in "redial" state, so this option is only\012      suited for points and will only work if you start TrapDoor with\012      "TrapDoor Call ..." (i.e. you do not start it in answer mode).  \012\012      Example: RedialDelay 120 \012\012                               RETRIES COUNT\012                               -------------\012\012      When calling a system, this instructs TrapDoor not to exit on\012      a failed call (eg. line is busy), but to try it thus often\012      again. Between the calls, TrapDoor will spend REDIALDELAY\012      seconds waiting. Note that this automatic redialing does _not_\012      apply if you place the call from within ANSWER mode. You have to\012      start TrapDoor directly with the CALL parameter.  \012\012      Example: Retries 5 \012\012\012                             REXXNAME PORTNAME\012                             -----------------\012\012      Using this configuration keyword, you can select the ARexx\012      port name (the "host address" in ARexx terminology) of TrapDoor.\012      If you run TrapDoor on multiple lines, be sure to set up a\012      different REXXNAME for every invocation. TrapDoor will not start\012      up if the port name is already in use.  \012\012      Example: RexxName "TrapDoor" \012\012                               RINGS NUMBER\012                               ------------\012\012      Number of rings to wait before answering an incoming call. To\012      turn off the answering feature, you can set this to any\012      high-enough value (RINGS 5000 will probably never answer the\012      phone).  \012\012      Example: Rings 1 \012\012                              SCREENMODE MODE\012                              ---------------\012\012      This allows you to specify the screen where TrapDoor opens its\012      windows.  There are five possible modes: \012\012         WORKBENCH -- TrapDoor will open its windows on the\012         workbench screen.  \012\012         CUSTOM -- TrapDoor will open its own screen and place the\012         windows there.  \012\012         TRAPDOOR -- Similar to CUSTOMSCREEN, TrapDoor will open its\012         windows on its own screen. However, if you have multiple\012         TrapDoors running at the same time, all invocations of\012         TrapDoor will share the same "TrapDoor" screen. The screen\012         will only close when the last copy of TrapDoor quits\012         running.  \012\012         PUBLIC -- Similar to TRAPDOOR, but will use a Kickstart\012         2.04 Public Screen instead of the proprietary and\012         undocumented method that SCREENMODE TRAPDOOR uses. Thus,\012         other programs can open their windows on the public TrapDoor\012         screen, too. Or you can also make TrapDoor open its windows\012         on a foreign public screen if you use SCREENMODE PUBLIC in\012         conjunction with PUBSCREENNAME (to define the name of the\012         public screen that TrapDoor should use).  \012\012         ACTIVE -- TrapDoor will use the screen with the currently\012         active window and open its windows there. Note that this is\012         rather dangerous as TrapDoor cannot control when the other\012         program will close the screen. If this happens, TrapDoor will\012         try to write to a screen that no longer exists and this will\012         in most cases immediately crash the machine.  \012\012         In spite of these restrictions, SCREENMODE ACTIVE looks\012         very nice in conjunction with Chameleon, a wonderful message\012         editor written by Jürgen Hermann. Try sticking the following\012         command into your ''CE.CFG'' file: \012\012                 External CustomScreen "Call Boss" \ \012                         "TrapDoor call boss screenmode active" \012\012         Now start Chameleon, pull down the "External" menu, select\012         this item and see for yourself ...  \012\012      Examples: ScreenMode Workbench \012                ScreenMode TrapDoor \012\012                         SERIALFLAGS SERIAL-FLAGS\012                         ------------------------\012\012      If you use some other device than "serial.device", you might\012      need to change this, too. Consult the documentation that came\012      with your other device or use zero as default.  \012\012      Example: SerialFlags 0 \012\012                       SERIALNAME SERIAL-DEVICE-NAME\012                       -----------------------------\012\012      If you happen to have a modem connected to some other device\012      than the standard Amiga "serial.device", you can use this\012      parameter to set up the correct device name. Usually,\012      "serial.device" will just be about perfect.  For Supra 2400zi\012      modems, use SERIALNAME "modem0.device".  \012\012      Example: SerialName "serial.device" \012\012                       SERIALUNIT SERIAL-UNIT-NUMBER\012                       -----------------------------\012\012      If your modem is connected to some other unit number than zero\012      (on the device you set with SERIALNAME), change this\012      appropriately.  \012\012      Example: SerialUnit 0 \012\012                                (NO)SHARED\012                                ----------\012\012      (Don''t) Open the serial device in shared mode. If you are\012      running TrapDoor in conjunction with a BBS program or similar,\012      you need to switch the serial device to SHARED mode, so that\012      both programs can have it open at the same time.  \012\012      Examples: NoShared \012                Shared \012\012                       SLOWMODEM MODEM-COMMAND-DELAY\012                       -----------------------------\012\012      Some modems won''t understand incoming data at full speed while\012      in command mode. Others take some time after a reset (ATZ or DTR\012      dropped) until they will react to incoming commands again. If\012      your modem doesn''t seem to understand the commands TrapDoor is\012      trying to send, feel free to change (increase) this parameter.\012      Also see chapter "The Modem" for some suggested values.  \012\012      SLOWMODEM changes a number of timings in TrapDoor, the most\012      important being: \012\012        (a) the time that TrapDoor waits between lowering and raising\012            of DTR when it tries to reset the modem or hang up, \012 \012        (b) the time that TrapDoor waits when it encounters a tilde\012            ("~") character in a modem command string (MODEMINIT,\012            MODEMDIAL, MODEMANSWER).  \012 \012      Example: SlowModem 7 \012\012                               (NO)SNIFFARQ\012                               ------------\012\012      If you have a modem that will detect MNP, LAP-M, V42 and\012      similar error-correction protocols, you can enable SNIFFARQ.\012      With SNIFFARQ, TrapDoor will minimize session-startup delays.  \012      The default is NOSNIFFARQ. You should _not_ use SNIFFARQ with\012      modems that have no error correction. You must specify the\012      correct ARQSTRING for your modem if you use SNIFFARQ.  \012\012      Examples: NoSniffArq \012                SniffArq \012\012                      STATWINDOW WINDOW-SPECIFICATION\012                      -------------------------------\012\012      Similar to LOGWINDOW, this changes the position and size of\012      the status window.  \012\012      Example: StatWindow 30/155/580/37 \012\012                            SYSOP SYSOP''S-NAME\012                            ------------------\012\012      Sysop''s name, will be sent to the other system during session\012      negotiation. The length of this string is limited to 20\012      characters in the YooHoo/WaZoo handshake and to 30 characters\012      when using EMSI.  \012\012      Example: Sysop "Maximilian Hantsch" \012\012                             TASKPRI PRIORITY\012                             ----------------\012\012      Use this to select the AmigaDOS/Exec task priority of\012      TrapDoor. Normal tasks operate at priority 0. It is often\012      advisable to set the priority of TrapDoor to 1 or 2, so that\012      mail sessions are not slowed down by other activity such as mail\012      importing/exporting.  \012\012      If the keyword is not used, TrapDoor will run at the priority\012      of the invoking process.  \012\012      Example: TaskPri 1 \012\012                                 (NO)WAZOO\012                                 ---------\012\012      Enable (disable) WaZoo mode. With WaZoo disabled, TrapDoor\012      will only attempt to connect using the FTS-0001 (Lotek) protocol\012      or EMSI handshake. No YooHoo will be done.  \012 \012      Examples: NoWaZOO \012                WaZOO \012\012                                (NO)ZEDZAP\012                                ----------\012\012      Enable (disable) ZedZap mode. ZedZap is a slight variant of\012      the ZModem transfer protocol -- on large files, this is one of\012      the fastest protocols around. ZedZap will automatically switch\012      block sizes depending on modem speed and quality of the line. It\012      will also resume an interrupted transfer if possible.  \012\012      ZedZap only works in WaZoo or EMSI mode and only if the other\012      side also supports it.  \012\012      Examples: NoZedZap \012                ZedZap \012\012                                (NO)ZEDZIP\012                                ----------\012\012      Enable (disable) ZedZip mode. ZedZip is the ZModem transfer\012      protocol -- it will not switch block sizes, but use a fixed\012      block size of 1kb. It will resume an interrupted transfer if\012      possible.  \012\012      ZedZip only works in WaZoo or EMSI mode and only if the other\012      side also supports it.  \012\012      Examples: NoZedZip \012                ZedZip \012\012\012             @{" Back to Main Menu " link Main}         @{" Back to Dir Structure " link DirStructure}\012@EndNode\012\012@NODE Acknowledgements "Acknowledgements "\012\012\012                      ø¤°~¬¯ ACKNOWLEDGEMENTS ¯¬~°¤ø\012\012\012      COMMODORE BUSINESS MACHINES         for making the Amiga\012\012      WILLIAM S. HAWES                    for making ARexx\012\012      TOM JENNINGS                        for FidoNet\012\012      MAXIMILIAN HANTSCH/MARTIN LAUBACH   for TrapDoor, TrapPoll,\012                                              and TrapList.\012\012      JOSEPH HODGE                        for Ami-Express\012\012\012                       ø¤°~¬¯ MANY THANKS TO ¯¬~°¤ø\012\012      SIMON SOFT                          Co-Writing Ami-X Fido.\012\012      EMPiRE/SUBMiSSiON                   Beta-Testing\012\012      KiLLRAVEN/DESiRE                    Beta-Testing & Docs\012\012                     ALL PEOPLE WHO SUPPORT AMI-X FIDO\012\012\012                       ø¤°~¬¯ GREETINGS GO TO ¯¬~°¤ø\012\012\012      BlackOut, Paul Dean, The OutLaw, Easy Rider, Pharaoh,\012      and all other cøøl guyz...\012\012                             @{" Back to Main Menu " link Main}\012@endnode\012@NODE InstallProc "Installation of /X-Fido -  © 1993 by TyCooN"\012\012                               INSTALLATION\012                               ------------\012\012      First of all, you will need to run the installation software\012      that is on the disk. Just double-click on the icon and you\012      will be asked some question about where to put it, etc.\012\012      After you have done that, read further. If not, install first.\012\012      When you have installed everything with the installer, you have\012      to install the following files/programs:\012\012        Files/programs in MAIL:BIN\012      \012        - clearacct             - enumnet               - enumnodes\012        - getnode               - listacct              - listconfig\012        - listpasswd            - setconfig             - setpasswd\012        - shownl                - TrapCall              - TrapDoor (*)\012        - TrapList (*)          - TrapPoll              - TrapScan\012        - TrapTell (*)          - Traptoss (*)          \012\012        (*) = These files are NEEDED!\012        \012        If you want to, you can put the documents of these programs in\012        Mail:Docs and the key-files must be stored in MAIL:.\012\012        All these files are not on the AXF-disk because of the copyright\012        that rests on these programs. Please check the @{"requirements" link Requirements} to\012        know where to get them.\012\012        Files in S:   (for express V2.3x)\012\012        ACP.STARTUP\012\012        In the file must be changed:\012\012        PUBLICSCREEN bbs  (for making an own screen where the trapdoor\012                           windows can be opened. So everything is easy\012                           to overlook.)\012\012        For single node, do this:\012\012        STARTNODE0: bbs:utils/express 0\012        STARTNODE1: run >nil: trapdoor \012        \012        The first line is the local node and the other the bbsnode.\012\012        For multiplex nodes, do this:\012       \012        STARTNODE0: run >nil: trapdoor config "mail:trapdoor.0"\012        STARTNODE1: run >nil: trapdoor config "mail:trapdoor.1"\012        STARTNODE2: bbs:utils/express 2\012        \012        The first 2 lines are the bbsnodes and the last one is the\012        localnode.\012\012        For every trapdoor node, you need to do this:\012\012        NODE<number> TRAPDOOR\012\012        Like:  (multiplex example)\012        NODE0 TRAPDOOR\012        NODE1 TRAPDOOR\012\012        If all is right, TrapDoor will now answer all the calls, not \012        Ami-X! Also, you''re users will notice a slight difference when\012        calling your system. Instead of the normal logon like:\012\012        Welcome to CHANNEL X, located in  Holland\012        Running AmiExpress v2.39 Copyright © Light Speed Technologies 1992-93.\012        Registration TT--13.0298. You are connected to Node 0 at 14400 baud\012        Connection occured at 00:42:00 06-05-93.\012\012        your users will see NOTHING for 5 seconds. This is the time that\012        TrapDoor uses to check wether it is a fido-call or a data-call.\012\012        Users are not limited to that 5 seconds-wait. They can also press\012        return and than they will see the same as after the 5 seconds:\012\012        * TrapDoor 1.83/54321 on Node 44:100/0.0\012        CHANNEL X  -- RUNNING Ami-eXpress\012\012        Please press Escape twice to enter the BBS.\012\012        Then they''ll have to press Escape twice and the BBS will be\012        launched:\012\012        Thank you. Please stand by while launching the BBS...\012        CONNECT 14400\012\012        And THEN the normal logon continues.\012\012\012        This is all there must be changed in the s:ACP.startup.\012\012        Then you have to config and optimize the config files:\012      \012        - Mail:@{"trapdoor.cfg" link trapdoor.cfg}\012        - Mail:@{"trapdoor<x>.cfg"link trapdoor.x}   (for multiplex nodes)\012        - Mail:@{"fido.cfg" link Fido.CFG}\012        - Mail:@{"traplist.cfg" link TrapList.CFG}\012        - Mail:@{"skytick.cfg" link Tick.CFG}\012        - BBS:fidonet/@{"fidonet.cfg" link FidoNet.CFG}\012\012      Read then the info about : @{"BBS.CMD" link bbs.cmd} & @{"BULLxx.TXT" link Bullxx.TXT} and than it must\012      be ready to work.  One last point :  You must run RPSTART else the \012      system will crash! If you don''t have it, it is on the disk.\012\012      It is possible that I have forgotten something to mention, if so,\012      please let me now and I will put it in the installation and/or\012      guide.\012\012      Have a lot of fun with this program & remember -> Call @{"Channel-X" link Channel-X}\012      for updates and support!\012\012                             @{" Back to Main Menu " link Main}\012@EndNode\012\012@node ProgramUse "Program Use Within Ami-X - © 1993 Tycoon"\012\012                             PROGRAM USE IN /X\012                             -----------------\012\012   Below you will find how you can operate Ami-X Fido in Ami-Express\012   itself.  It should be rather self-explainatory, but for those of you who\012   can''t figure it out completely, or you want your users to show how it\012   works, maybe you can show them this file.\012\012                          @{"  Starting Ami-X FIDO " link Starting}\012                          @{"   Configuring Areas  " link ConfiguringAreas}\012                          @{"     Reading mail     " link ReadingMail}\012                          @{"     Writing mail     " link WritingMail}\012                          @{"     Replying mail    " link ReplyingToMessages}\012                          @{"     Scanning mail    " link ScanningMail}\012                          @{"      Quick Scan      " link QuickScan}\012                          @{"  How To Get Out /XF  " link HowToGetOut}\012\012@EndNode\012\012@Node Starting "Starting Ami-X FIDO - © 1993 Tycoon"\012\012                               STARTING /XF\012                               ------------\012\012If you have installed /XF correctly, you can start /XF with ''net'' at the\012menu prompt. For example:\012\012      CHANNEL X [3:AMIGA] Menu (159975 mins. left): net\012\012Then, after a while, something like the following screen should appear:\012\012                         __ ____ ____ ______ ____ __ __\012                      /|/ // __//  _//     // _ // // /\012                     / | // _/  / / / |_/ //   // // /_\012                    /_/|//___/ /_/ /_/ |_//_/_//_//___/       (C) TyCooN\012 \012    ------------------------------- NETBASES -----------------------------\012 \012                         BOS...................... [ 1]\012 \012                         /X-FIDO-NET.............. [ 2]\012 \012                         Xenolink................. [ 3]\012 \012                         NLA...................... [ 4]\012 \012                         UUCP..................... [ 5]\012 \012    ----------------------------------------------------------------------\012    Config Your Areas...........[ C]      Download All New Messages...[ D]\012\012    CHANNEL X  Your Choice : (Q)=Back\012\012\012Your screen may differ from this, because you probably have other netbases.\012If you have a registered version, YOUR bbs-name will be in the place of\012CHANNEL X.\012\012@EndNode\012\012@Node ConfiguringAreas "Configuring Areas - © 1993 Tycoon"\012\012                             CONFIGURING AREAS\012                             -----------------\012\012After each screen is displayed, a prompt will be shown where you can type\012your choice. For configuring your areas you need to go to the main screen\012and enter C. Like:\012\012\012    CHANNEL X  Your Choice : (Q)=Back C\012\012\012After that, you will be asked which area to config:\012\012\012           What Net To Config ?  (Q)=Back 2\012\012\012Now area 2 will be configured, something like this should appear:\012\012\012                          /X-Fido Configuration Screen\012 \012    ------------------------------- areas -------------------------------\012\012    * AXF_GEN.....................[ 1]  * AXF_SYSOP...................[ 4]\012    * AXF_SALE....................[ 2]  * AXF_BETATEST................[ 5]\012    * AXF_COSYSOP.................[ 3]\012 \012    ----------------------------------------------------------------------\012    * = Activated Area       ''+'' = Activate All        ''-'' = Activate None\012\012    CHANNEL X  Activate Area xx : (Q)=Back\012\012\012An asterisk in front of an area means it is activated. If you want to\012deactivate all areas press ''-'' and if you want to activate them all,\012press ''+''. You can selectively activate/deactivate area by pressing the\012number in front of the area, so if you press 1, the following will appear:\012\012                          /X-Fido Configuration Screen\012 \012    ------------------------------- areas -------------------------------\012 \012      AXF_GEN.....................[ 1]  * AXF_SYSOP...................[ 4]\012    * AXF_SALE....................[ 2]  * AXF_BETATEST................[ 5]\012    * AXF_COSYSOP.................[ 3]\012\012    ----------------------------------------------------------------------\012    * = Activated Area       ''+'' = Activate All        ''-'' = Activate None\012\012\012And if you press 1 again, it will be activated again:\012\012\012                          /X-Fido Configuration Screen\012 \012    ------------------------------- areas -------------------------------\012 \012    * AXF_GEN.....................[ 1]  * AXF_SYSOP...................[ 4]\012    * AXF_SALE....................[ 2]  * AXF_BETATEST................[ 5]\012    * AXF_COSYSOP.................[ 3]\012\012    ----------------------------------------------------------------------\012    * = Activated Area       ''+'' = Activate All        ''-'' = Activate None\012\012CHANNEL X  Activate Area xx : (Q)=Back q\012\012\012To get out of the Config menu, just press Q and return. \012\012@EndNode\012\012@Node DownloadingMessages "Downloading Messages - © 1993 Tycoon"\012\012                           DOWNLOADING MESSAGES\012                           --------------------\012\012   Ami-X Fido offers the possibility to let your users download the new\012   mail.  A special option has been built in the main menu to take care of\012   this.  This option looks at the activated areas to pack the mail, so\012   only the areas that have been activated will be scanned for new mail.\012\012   Future version will have a seperate ''Download New Messages'' in every\012   area separate for separate downloading.\012\012   To download the new messages, press ''D'' in the main menu and something\012   like this will appear:\012\012 \012   Packing Your Mail Can Take A While, Therefor You Might Want To Deactivate\012   Some Areas In the Config Menu.  So If You Don''t Want ALL The Mail, Do It!\012 \012   Are You Sure You Want To Download The New Mail ???  (Y/n)? y\012 \012 \012   Packing Area : BOS_COMPUTERS.....................   55 Messages Packed \012   Packing Area : BOS_GEZWAM........................   15 Messages Packed \012   Packing Area : BOS_IRRITATIE.....................   47 Messages Packed \012   Packing Area : BOS_MUZIEK........................   No Messages Packed \012   Packing Area : BOS_NATUUR........................   No Messages Packed \012   Packing Area : BOS_OORLOG........................   No Messages Packed \012   Packing Area : BOS_POLITIEK......................   No Messages Packed \012   Packing Area : BOS_RODDELS.......................   64 Messages Packed \012   Packing Area : BOS_SOFTWARE......................   No Messages Packed \012   Packing Area : BOS_SPREUKEN......................   No Messages Packed \012   Packing Area : BOS_LEUGENS.......................    8 Messages Packed \012   Packing Area : AXF_GEN...........................    7 Messages Packed \012   Packing Area : AXF_SALE..........................   No Messages Packed \012   Packing Area : AXF_COSYSOP.......................   No Messages Packed \012   Packing Area : AXF_SYSOP.........................   No Messages Packed \012   Packing Area : AXF_BETATEST......................   No Messages Packed \012 \012   File Info    : fido_05-Jun.lha     38702 Bytes    (196 Messages)\012 \012   Ready To Send The Mail, Do You Want It?  (Y/n)? y\012\012   Internal Zmodem: Ready to Send\012   Control-X to Cancel\012   rz**B0\012   Internal Zmodem download successful\012 \012\012   Sofar the user will have the all the new mail in one big file.  He can''t\012   reply the mail at home, but he can read it and select them easier the\012   next time he logs in (every message will have it''s own number).\012\012   After downloading, the next question will appear:\012\012   Update High Message Pointer? (Y/n)? y\012\012   If the user doesn''t update his High Message Pointer, the next time he\012   logs in all the messages he downloaded will still be recognized as\012   ''unread''.\012\012@EndNode\012\012@Node ReadingMail "Reading Mail - © 1993 Tycoon"\012\012                               READING MAIL\012                               ------------\012\012   To read/write/scan mail, all you have to do is press the number of the\012   base you want to read messages from.  For example, you press 2 and the\012   following will be shown:\012\012                         __ ____ ____ ______ ____ __ __\012                      /|/ // __//  _//     // _ // // /\012                     / | // _/  / / / |_/ //   // // /_\012                    /_/|//___/ /_/ /_/ |_//_/_//_//___/       (C) TyCooN\012 \012    ------------------------------- areas -------------------------------\012 \012    AXF_GEN.....................[ 1]      AXF_SYSOP...................[ 4]\012    AXF_SALE....................[ 2]      AXF_BETATEST................[ 5]\012    AXF_COSYSOP.................[ 3]\012 \012 \012    ----------------------------- READ/WRITE -----------------------------\012 \012    Enter a message.............[ E]      Read Messages...............[ R]\012    Search messages.............[ S]      Downloading New Messages....[ D]\012\012    CHANNEL X  AXF_GEN [ 30+34 ] Your Choice : (Q)=Back \012    ^          ^         ^  ^   \012    |          |         |  `--- Highest message available\012    |          |         `------ Highest message read\012    |          `---------------- Area name that is active\012    `--------------------------- Name of your BBS (if registered)\012\012\012   To start reading the mail you have not read yet, just press return or R.\012   In this case, message 31 will first be shown.\012\012@EndNode\012\012@Node WritingMail "Writing Mail - © 1993 Tycoon"\012\012                               WRITING MAIL\012                               ------------\012\012   First of all, you will have to go to the area in the base you want to\012   write in.  This can be done by pressing their appropriate number.\012   Something like this will appear:\012\012                         __ ____ ____ ______ ____ __ __\012                      /|/ // __//  _//     // _ // // /\012                     / | // _/  / / / |_/ //   // // /_\012                    /_/|//___/ /_/ /_/ |_//_/_//_//___/       (C) TyCooN\012 \012    ------------------------------- areas -------------------------------\012 \012    AXF_GEN.....................[ 1]      AXF_SYSOP...................[ 4]\012    AXF_SALE....................[ 2]      AXF_BETATEST................[ 5]\012    AXF_COSYSOP.................[ 3]\012 \012 \012    ----------------------------- READ/WRITE -----------------------------\012 \012    Enter a message.............[ E]      Read Messages...............[ R]\012    Search messages.............[ S]      Downloading New Messages....[ D]\012\012    CHANNEL X  AXF_GEN [ 30+34 ] Your Choice : (Q)=Back \012    ^          ^         ^  ^   \012    |          |         |  `--- Highest message available\012    |          |         `------ Highest message read\012    |          `---------------- Area name that is active\012    `--------------------------- Name of your BBS (if registered)\012\012\012   To write mail in this area (AXF_GEN), just type ''E'' and you will be able\012   to write mail just like in /X:\012\012    CHANNEL X  AXF_GEN [ 30+34 ] Your Choice : (Q)=Back E\012\012                       (------------------------------)\012     To: (Enter)=''ALL''? \012Subject: (Blank)=abort? AXF Release\012\012   Enter your text. (Enter) alone to end. (75 chars/line, 100 lines, max)\012   (*-------*-------*-------*-------*-------*-------*-------*-------*-------*--)\012 1>   IMPORTANT!\012 2>   ~~~~~~~~~~\012 3>   Ami-X Fido will be released real soon! So watch out for it! For more \012 4>   info call Channel-X, +31-2290-62244 (14k4 DS).\012 5>  \012 6>   KiLLRaVeN/D3$!R3\012 7> \012\012A)bort, C)ont, D)el, E)dit, F)ile, L)ist, S)ave Option? s\012Saving... \012\012\012   And you will be back in the area menu. It isn''t hard to do.\012\012@EndNode\012\012@Node ScanningMail "Scanning for Mail - © 1993 Tycoon"\012\012                               SCANNING MAIL\012                               -------------\012\012   Ami-X Fido has an option to search for messages, this is done by\012   scanning the headers of the messages.  This also allows you to just see\012   the headers of the messages before actually reading them.  An example:\012\012                         __ ____ ____ ______ ____ __ __\012                      /|/ // __//  _//     // _ // // /\012                     / | // _/  / / / |_/ //   // // /_\012                    /_/|//___/ /_/ /_/ |_//_/_//_//___/       (C) TyCooN\012 \012    ------------------------------- areas -------------------------------\012 \012    AXF_GEN.....................[ 1]      AXF_SYSOP...................[ 4]\012    AXF_SALE....................[ 2]      AXF_BETATEST................[ 5]\012    AXF_COSYSOP.................[ 3]\012 \012 \012    ----------------------------- READ/WRITE -----------------------------\012 \012    Enter a message.............[ E]      Read Messages...............[ R]\012    Search messages.............[ S]      Downloading New Messages....[ D]\012\012    CHANNEL X  AXF_GEN [ 30+34 ] Your Choice : (Q)=Back S\012\012 Scan Menu\012 ~~~~~~~~~\012 Scan All Messages......[0]\012 Search To..............[1]\012 Search From............[2]\012 Search To & From.......[3]\012 Search Subject.........[4]\012 Search All Above.......[5]\012 \012 Scan method...........: 0\012 Begin at #2...........: \012 \012From:             To:               Subject:                 Date:       No:\012----------------------------------------------------------------------------\012Killraven         Lasau             Hoi!                     29 Mar 93   #2\012Lasau             Killraven         Hoi!                     30 Mar 93   #3\012TYC00N            ALL               testje                   04 Apr 93   #6\012KILLRAVEN/D3$!R3  Lasau             RE: Hoi!                 14 Apr 93   #8\012TYC00N            killraven/desire  area test                19 Apr 93   #9\012Killraven/DESIRE  All               Pfff........             01 May 93   #10\012NAAMPIE           Killraven/DESIRE  RE: Pfff........         12 May 93   #11\012KILLRAVEN/D3$!R3  TYC00N            RE: testing 1 2 3        13 May 93   #18\012TYC00N            KILLRAVEN/D3$!R3  RE: testing 1 2 3        25 May 93   #21\012TYC00N            killraven         test #124                25 May 93   #25\012EMPIRE            ALL               TESTING                  13 May 93   #26\012TYC00N            EMPIRE            RE: TESTING              26 May 93   #27\012TYC00N            KILLRAVEN/D3$!R3  RE: testing 1 2 3        26 May 93   #28\012Killraven/DESIRE  TYC00N            re: test 1 2 3           26 May 93   #29\01230                EALL              READ THIS !!!!!!!!!!!    01 Jun 93   #30\01230                TYC00N            RE: READ THIS !!!!!!!!!! 01 Jun 93   #31\01220                TYC00N            RE: READ THIS !!!!!!!!!! 01 Jun 93   #32\01230                KILLRAVEN/D3$!R3  RE: READ THIS !!!!!!!!!! 02 Jun 93   #33\01230                TOMMIE            RE: READ THIS !!!!!!!!!! 02 Jun 93   #34\012 \012\012Or:\012\012 Scan Menu\012 ~~~~~~~~~\012 Scan All Messages......[0]\012 Search To..............[1]\012 Search From............[2]\012 Search To & From.......[3]\012 Search Subject.........[4]\012 Search All Above.......[5]\012\012 Scan method...........: 2\012 Search for............: Kill\012 Begin at #2...........:\012\012From:             To:               Subject:                 Date:       No:\012----------------------------------------------------------------------------\012Killraven         Lasau             Hoi!                     29 Mar 93   #2\012KILLRAVEN/D3$!R3  Lasau             RE: Hoi!                 14 Apr 93   #8\012Killraven/DESIRE  All               Pfff........             01 May 93   #10\012KILLRAVEN/D3$!R3  TYC00N            RE: testing 1 2 3        13 May 93   #18\012Killraven/DESIRE  TYC00N            re: test 1 2 3           26 May 93   #29\012\012@EndNode\012\012@Node ReplyingToMessages "Replying to Messages - © 1993 Tycoon"\012\012                           REPLYING TO MESSAGES\012                           --------------------\012\012   Ofcourse you can reply to messages.  This is also done with the internal\012   editor of /X.  An example:\012\012\012A>gain D>elete R>eply Q>uit <CR>=Next ( 34+35 ) r\012 \012                       (------------------------------)\012     To: (Enter)=''ALL''? TYC00N\012Subject: (Blank)=abort? RE: READ THIS !!!!!!!!!!!\012 Subject Correct (Y/n)? y\012  Quote in Reply (y/N)? Y\012 \012 1> Some rulez in the /XF areas:\012 2>  \012 3> - ONLY ENGLISH\012 4>  \012 5> Thats all ....\012 6>  \012 7> Greetz,\012 8>         Tycoon/Desire\012 9>  ^^^-( TYC00N - 01 Jun 93  00:50:54 )---------------------------------\01210>  \01211> why only englisch ?? waarom leren die andere niet gewoon nederalnds\01212>  ^^^-( TOMMIE - 01 Jun 93  12:20:37 )---------------------------------\01213>  \01214> Stop talk Dutch...... This are International areas.....\01215> \01216> \01217> --- /X FIDO & UUCP MAILER V0.5e\01218>  * Origin: Channel X -> /XF-SUPPORT-WHQ!!! (44:100/0.0)\012 \012Enter Startline,Endline or (*=All, A=Abort): 11,14\012\012   Enter your text. (Enter) alone to end. (75 chars/line, 100 lines, max)\012   (*-------*-------*-------*-------*-------*-------*-------*-------*-------*--)\012 1> why only englisch ?? waarom leren die andere niet gewoon nederalnds\012 2>  ^^^-( TOMMIE - 01 Jun 93  12:20:37 )---------------------------------\012 3>  \012 4> Stop talk Dutch...... This are International areas.....\012 5>  ^^^-( TYC00N - 02 Jun 93  01:16:14 )---------------------------------\012 6>  \012 7> Eh, yeah, like, you know, much other peeple hafe 2 read it as wel.\012 8>  \012 9> Hehehehe... your English is GREAT Tycoon... Greetz pal...\01210> \012\012A)bort, C)ont, D)el, E)dit, F)ile, L)ist, S)ave Option? s\012Saving...\012\012\012   You see, it all is fairly simple and easy to use.  That is our main\012   goal.  If you have any suggestion, bug reports, complements, money, just\012   call us and we''ll work it out.  You can also write it in the AXF_BETATEST\012   area.\012\012@EndNode\012\012@Node HowToGetOut\012\012                                GET ME OUT\012                                ----------\012\012   Ami-X fido can be exited with ''Q'' via the main menu.\012\012   On exiting you will see:\012\012\012    +---------------------- /X-FIDO Mailer  V0.5e -----------------------+\012    |        Programmers:                            BetaTesters:        |\012    |                                                                    |\012    | TyCooN     ->  Arexx Coding            EMPiRE    -> Last Outpost   |\012    | Simon Soft ->  External Assembly       KiLLRaVeN -> Channel X      |\012    |                                                                    |\012    +------- Channel X --- +31-(0)2290-62244 --- Home of /X-FIDO --------+\012 \012@EndNode\012\012@Node QuickScan "Quick Scanning - © 1993 Tycoon"\012\012                                QUICK SCAN\012                                ----------\012\012   On every logon, all areas that have been activated be an user will be\012   searched for new messages.  This can also be done via the SCAN command\012   in the main menu of your BBS.  Something like this will appear:\012\012\012CHANNEL X [3:AMIGA] Menu (159974 mins. left): scan\012 \012Scanning FIDO-Conf.: BOS_COMPUTERS.....................   No New Messages \012Scanning FIDO-Conf.: BOS_GEZWAM........................   No New Messages \012Scanning FIDO-Conf.: BOS_IRRITATIE.....................   No New Messages \012Scanning FIDO-Conf.: BOS_MUZIEK........................   No New Messages \012Scanning FIDO-Conf.: BOS_NATUUR........................   No New Messages \012Scanning FIDO-Conf.: BOS_OORLOG........................   No New Messages \012Scanning FIDO-Conf.: BOS_POLITIEK......................   No New Messages \012Scanning FIDO-Conf.: BOS_RODDELS.......................   No New Messages \012Scanning FIDO-Conf.: BOS_SOFTWARE......................   No New Messages \012Scanning FIDO-Conf.: BOS_SPREUKEN......................   No New Messages \012Scanning FIDO-Conf.: BOS_LEUGENS.......................   No New Messages \012 \012Scanning FIDO-Conf.: AXF_GEN...........................    3 New Messages \012Scanning FIDO-Conf.: AXF_SALE..........................   No New Messages \012Scanning FIDO-Conf.: AXF_COSYSOP.......................   No New Messages \012Scanning FIDO-Conf.: AXF_SYSOP.........................   No New Messages \012Scanning FIDO-Conf.: AXF_BETATEST......................   No New Messages \012 \012Scanning UUCP-Conf.: Comp.dcom.modems..................    0 New Messages \012Scanning UUCP-Conf.: Comp.sys.amiga.datacomm...........   No New Messages \012\012\012   That is it.  All there is to be said about the working of /XF in /X.  If\012   you want to know more (I can''t guess what) feel free to call.\012\012@EndNode\012\012@Node Index\012\012@{"Access" link Access}\012@{"Acknowledgements" link Acknowledgements}\012@{"Alias" link Alias}\012@{"All" link All}\012@{"Ami-X" link Ami-X}\012@{"Area" link Area}\012@{"AXF" link AXF}\012@{"BBS.CMD" link BBS.CMD}\012@{"Bullxx.TXT" link Bullxx.TXT}\012@{"Channel-X" link Channel-X}\012@{"ConfiguringAreas" link ConfiguringAreas}\012@{"Delete" link Delete}\012@{"Dir" link Dir}\012@{"DirStructure" link DirStructure}\012@{"DownloadingMessages" link DownloadingMessages}\012@{"Eall" link Eall}\012@{"F-origin" link F-origin}\012@{"Fido-Con.EXE" link Fido-Con.EXE}\012@{"Fido-Del.EXE" link Fido-Del.EXE}\012@{"Fido-Del.REXX" link Fido-Del.REXX}\012@{"Fido-Hgh.EXE" link Fido-Hgh.EXE}\012@{"Fido-Mail.rexx" link Fido-Mail.rexx}\012@{"Fido-Main.Rexx" link Fido-Main.Rexx}\012@{"Fido-Ran.REXX" link Fido-Ran.REXX}\012@{"Fido-SCAN.REXX" link Fido-SCAN.REXX}\012@{"Fido.cfg" link Fido.cfg}\012@{"Fido.History" link Fido.History}\012@{"Fido1" link Fido1}\012@{"Fido2" link Fido2}\012@{"Fido3" link Fido3}\012@{"Fido4" link Fido4}\012@{"Fido5" link Fido5}\012@{"Fido6" link Fido6}\012@{"Fidonet.cfg" link Fidonet.cfg}\012@{"Fidonet1.cfg" link Fidonet1.cfg}\012@{"Fidonet3.cfg" link Fidonet3.cfg}\012@{"HowToGetOut" link HowToGetOut}\012@{"IfYouNeedHelp" link IfYouNeedHelp}\012@{"Inbound" link Inbound}\012@{"InstallProc" link InstallProc}\012@{"Introduction" link Introduction}\012@{"Length" link Length}\012@{"Level" link Level}\012@{"Local" link Local}\012@{"Mailer" link Mailer}\012@{"Main" link Main}\012@{"Maxmsg" link Maxmsg}\012@{"Net" link Net}\012@{"Node" link Node}\012@{"NodeList" link NodeList}\012@{"Nodenr" link Nodenr}\012@{"Origin" link Origin}\012@{"OutBound" link OutBound}\012@{"ProgramUse" link ProgramUse}\012@{"QuickScan" link QuickScan}\012@{"ReadingMail" link ReadingMail}\012@{"Registration" link Registration}\012@{"Registration1" link Registration1}\012@{"ReplyingToMessages" link ReplyingToMessages}\012@{"Requirements" link Requirements}\012@{"ScanningMail" link ScanningMail}\012@{"SkyFreq" link SkyFreq}\012@{"Skytick" link Skytick}\012@{"Starting" link Starting}\012@{"SupportBBS" link SupportBBS}\012@{"Tempdir" link Tempdir}\012@{"Tick.cfg" link Tick.cfg}\012@{"Ticks" link Ticks}\012@{"TrapCall" link TrapCall}\012@{"Trapdoor" link Trapdoor}\012@{"Trapdoor.cfg" link Trapdoor.cfg}\012@{"Trapdoor.key" link Trapdoor.key}\012@{"Trapdoor.x" link Trapdoor.x}\012@{"TrapDoorReg" link TrapDoorReg}\012@{"Traplist" link Traplist}\012@{"Traplist.cfg" link Traplist.cfg}\012@{"Trappoll" link Trappoll}\012@{"Trapscan" link Trapscan}\012@{"Traptell" link Traptell}\012@{"Traptoss" link Traptoss}\012@{"TrapToss.Key" link TrapToss.Key}\012@{"User" link User}\012@{"UUCP-con.exe" link UUCP-con.exe}\012@{"WhatIsFido" link WhatIsFido}\012@{"Write" link Write}\012@{"WritingMail" link WritingMail}\012@EndNode\012','\012',char(10)),NULL,'auto-added',1198750,26,0,NULL,NULL,'ami_fido','scan',1780048403);
