INSERT INTO door_catalog VALUES('amihack','AMIHACK.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AMIHACK.LHA','1','XIM','1',NULL,'Dux',NULL,'Coded By Dux of Sonic in 1992 33.6 DigITal-X Prd/NirVana Dist Site! 33.6',replace('   Anti-Baudkillers Util\nCoded By Dux of Sonic in 1992\n33.6 DigITal-X Prd/NirVana Dist Site! 33.6\n','\n',char(10)),'1.doc',replace('\n                             Anti-Baudkillers Util\n                           -------------------------\n\n                         Coded By Dux of Sonic in 1992\n\n\nThis Door Does NOTHING! But It Disables The Account-Edit Command ''1'' On\nAmiExpress.\n\nYou Install It As A Normal AmiExpress Door With Axs-Level 0 Or 1 And Then\nIt''s Impossible To Do Any Account-Editing From Remote. You Can Also Install\nIt So It Disables RemoteShell EtcEtc.\n\nThat''s All There''s To It...\n\n\nA Few Personal Hellos To:\n\nAlzheimer - Thanks For Sending Those Cool Utils And Doors.\n\nRamirez - To Bad You Board Was Hacked. If You''d Had This Little One At That\n          Time You Probably Could Have Avoided It :)\n\nCirculator - To Bad You Board Was Hacked. If You''d Had This Little One At That\n            Time You Probably Could Have Avoided It :)\n\nStonehead - Not Much To Say. Just Keep On Running AmiExpress.\n','\n',char(10)),NULL,'auto-added',10573,5,0,NULL,NULL,'amihack','scan',1780048403);
