INSERT INTO door_catalog VALUES('amiopen','AMIOPEN.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AMIOPEN.LHA','AmiOpen','XIM','############################################',NULL,'Faktor/Independent',NULL,'##  AmiOpen - An Available Doors Viewer   ## ## -------------------------------------- ## ##   For AmiExpress or compatibilties     ##',replace('############################################\n##  AmiOpen - An Available Doors Viewer   ##\n## -------------------------------------- ##\n##   For AmiExpress or compatibilties     ##\n##                                        ##\n##  Copyright (c) by Faktor/Independent   ##\n############################################\n','\n',char(10)),'AmiOpen.guide',replace('            _____     _________                _____    ____\n            \  _/_____\_____  /____   ____    / ___/    \   \\n            _\______  Y _l/  /___  \./ __/__ / __/___ ___\___\\n            \     |   | \___/  l/   |  |    Y  |     Y  ____/ \.\n             \    ''   ¦   |    /    ¦  `    ¦  `     ¦   l/    ¦\n              \______.^---^---/____.^._____.^.______.^.________|\n                 T                               .·        T\n                 |                              .·         |\n                 ¦..:·:::...                  .::          ¦...::\n               .:··      ··::.      .        .::...::::::::······\n             .:··           ·::   .·   ...:::::···         |\n            .:·             :::  .·    :··  ::·            |     .\n           .:·              ::  ::         :::             |   .::.\n          .:·             .:: .::     ..  .::              |  .::::.\n         .:·             .::· ::      ::: :::              | .::::::.\n        :::             .:·  ::·       :: ·:::             ¦::::::::·\n       .::            .:··  ::·        ::. ::::.         ..:::::··\n       :::.         .::·   .::.       .::: ·:::::..  ...:::::··\n       ::::.    ..:::··    ::::.    .:::::  ·:::::::::::::··\n        ::::::::::··       ·::