INSERT INTO door_catalog VALUES('amip10','AMIP10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AMIP10.LHA','AMIPAT10','XIM','AMIPAT10',NULL,NULL,NULL,'|    AMIPATCH V1.0     | -=#@@@@@@@@@@@@@@@@@@@@@@#=- 33.6 DigITal-X Prd/NirVana Dist Site! 33.6',replace('-=#@@@@@@@@@@@@@@@@@@@@@@#=-\n  |    AMIPATCH V1.0     |  \n-=#@@@@@@@@@@@@@@@@@@@@@@#=-\n33.6 DigITal-X Prd/NirVana Dist Site! 33.6\n','\n',char(10)),'Manuska.DOc',replace('			   *****					\n			************					\n		-=#@@@@@@@@@@@@@@@@@@@@@@#=-				\n		  |    AMIPATCH V1.0     |				\n		-=#@@@@@@@@@@@@@@@@@@@@@@#=-				\n			***********					\n			   *****   					\n									\n	 AmiPatch V1.0 - Nopeuttaa  AmiExpessiä joissain tapauksissa	\n	jopa 35%:lla, jopa 2400bps:lläkin. Se toimii, usko tai älä.	\n	Mutta en tietenkään ymmärrettävistä syistä kerro miten tämä	\n	ohjelma toimii.:)						\n									\n			***********					\n									\n		Tämä ohjelma on FREEWAREA ja kopioi ihan rauhassa	\n	vaan jos haluat...:)						\n	Tätä ohjelmaa saa levittää kaikkii purkkeihin kunhan vain	\n	antaa paketin olla rauhassa eli:				\n		 Anna paketin AMIP10.LHA sisältää:			\n									\n		AMIPAT10    - AmiPatch V1.0				\n		Manuska.Doc - Tämä teksti				\n			***********					\n									\n		Lähetä potsia ja palautetta:				\n									\n			 Tapio Nurmela					\n			 Aittatie 14c 					\n			 13200 Hämeenlinna				\n									\n		 Tosin voit myös lähettää rahaa jos			\n		sielu vain sietää, eli jos lähetät, niin		\n		lähetä noin.20 Mk.					\n									\n			KIITOOS.					\n									\n','\n',char(10)),NULL,'auto-added',8838,5,0,NULL,NULL,'amip10','scan',1780048403);
INSERT INTO door_catalog VALUES('amipass1','AMIPASS1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AMIPASS1.LHA','AmiPass','XIM','AmiPass','1.10',NULL,NULL,'33.6 DigITal-X Prd/NirVana Dist Site! 33.6',replace('AmiPass v1.10  ©1992 CyberX softworx.\n33.6 DigITal-X Prd/NirVana Dist Site! 33.6\n','\n',char(10)),'AmiPass.doc',replace('    AmiPass v1.10  ©1992 CyberX softworx.\n    Shareware - $10\n\n\n    Introduction:\n    -------------\n    AmiPass is a Multi-User password security system that will\n    keep un-wanted people out of your system and also keep\n    track of who is on and when.\n\n    New features of v1.10 include-\n      Optional display of an IFF picture\n      Optional locking of sensitive files (names, passwords)\n      Put the window anywhere on the screen\n      Doesn''t display users password in ''report''\n      Pass gadget was made so password isn''t visible\n      Alerts user if last person on failed to gain access\n      install - makes installation easier\n\n    Installation:\n    -------------\n    To install most of it just execute the script called ''install''.  It\n    should work if your environment is fairly normal.  It doesn''t make\n    any references to a particular drive so it should work with both\n    floppy and hard drive users.\n\n    After you execute install you should edit your startup-sequence.\n    A sample startup-sequence is included so you get the idea.\n    The only big deal is that you place it before any utilites that may\n    defeat the security scheme (popcli, etc.).\n    Now you have to edit the ''names'' and ''passwords'' files with a text\n    editor.  A new file, ''options'', should also be edited. Four parameters\n    can be changed -\n      X position  - X position of window on screen\n      Y position  - Y position of window on screen\n      Display mode- if 1 (default), tries to load IFF picture called\n       ''picture'', otherwise it just puts the window on the WB screen.\n      Lock files  - if 0 (default), will put an exclusive lock on ''names'' and \n       ''passwords'' and leaves them like that so they can''t be looked at.\n\n    You can also change the picture to anyone you want as long as it''s\n    IFF.  HAM works but I had trouble clicking in the gadgets.\n\n    Operation:\n    ----------\n    AmiPass opens a window on the Workbench or on your picture.\n    Two text are in the window.   Enter your name and password in the\n    gadgets.  In the password gadget, you must click close to the front\n    of the box.  I made it this way so the password can''t be seen.\n    (If someone knows of a more elegant way to do this please let me know.)\n    Click on the close gadget and the startup-sequence\n    will resume (if entered correctly).  The REPORT file is opened\n    and the time and user are appended to the file.  If the user\n    before you failed to get in, AmiPass will display a message alerting\n    you to the condition.\n\n\n    Comments:\n    ---------\n    I know of no bugs in AmiPass (except the HAM thing).\n    If you find some or have comments/suggestions please write to me at\n\n        CyberX softworx\n        Forest Park Estates\n        Clancy, MT  59634\n\n    AmiPass can also be used for programs by using a script\n    via iconx.\n\n    AmiPass requires the iff.library v18.5 by Christian Weber to load the IFF\n    picture. It is included in the archive and should be placed in your LIBS:.\n    The reason I didn''t put it in the install is if a new version comes out\n    and you have it, you wouldn''t want an old one copied over it!\n\n    Copyright:\n    ----------\n    AmiPass is SHAREWARE.  The fee is $10.00.  Please send it to\n    the address above and your name and address (for contact\n    of new releases.)  Your payment is greatly appreciated and\n    needed for continued development of AmiPass.\n\n    AmiPass is copyright of CyberX softworx  1992\n    This software is provided AS IS.  No warranties or guarantees\n    are expressed or implied.  CyberX softworx or Ken Gilmer\n    cannot be held responsible for ANY problems arising from the use\n    of this software; use at your own risk, but if you have problems\n    let me know and I''ll see what I can do.\n\n    iff.library is public domain and freely distributable.\n\nThanX, Ken ;)\n                                      C             B\n                                     C             B\n         PPPPP                      C             B\n       PP  P  PP                   C             B\n      P    P    P              X  C  Y       Y  B  EEE  RRRRR\n     P     P     P              X  C  Y     Y  B B       R\n     P    P P    P               X  C  Y   Y  B   B  EE   R\n      P  P   P  P                 X  C  Y Y  B     B       R\n       PP     PP                   X  C  Y  BBBBBBBBB  EEE  R\n         PPPPP                      X   Y\n                                     X Y\n   The USSR IS DEAD!                  Y\n                                     Y X\n                                        X\n                                         X\n','\n',char(10)),NULL,'auto-added',46727,9,0,NULL,NULL,'amipass1','scan',1780048403);
INSERT INTO door_catalog VALUES('amipeek','AMIPEEK.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AMIPEEK.LHA','AmiPeek','XIM','AmiPeek',NULL,NULL,NULL,'LAST10 CALLERS UTIL FOR AMIEXPRESS',replace('AMIPEEK VER 0.4\n \nLAST10 CALLERS UTIL FOR AMIEXPRESS','\n',char(10)),'AmiPeek.doc',replace('\n\n\n                          +------------------+\n                          | AmiPeek  ver 0.4 |\n                          +------------------+\n\n\n\n              Last10 Callers Utility for AmiExpress BBS''s\n \n               Copyright by: Tibor G. Balogh (10-MAR-94)\n\n                        [email removed]\n\n       Released in the Public Domain under the Shareware concept\n\n\n\n\nWhat it is:\n-----------\n   AmiPeek is a utility that displays the last ten users that were on the BBS\njust prior to the current user logging on.  \n\n\n\nHow do I set it up:\n-------------------\n   You put this line in the logoff script;\n\n   ;------------------cut----------------------------------\n   stack 32000   ;a large stack is important at this time\n   amipeek >bbs:node(x)/LogOn.TXT bbs:node(x)/CallersLog\n   stack 8192    ;then we want to set stack back to normal\n   ;------------------cut----------------------------------\n\n\n\nWhat will my output look like:\n------------------------------\n\n [34m+-------------------------------------------------------------------------+\n [34m| [44;33m Ami[37mPeek [0m [32m(Demo V0.4)    [36mLast 10 Callers Utility          [34m([33mc[34m) [32m10-MAR-94 [34m|\n [34m|----------------+----------------+-------+----------+------+------+------|\n [34m|[33m  USERS/NAMES   [34m|[33m LOCATIONS/FROM [34m|[33m SPEED [34m|[33m   DATE   [34m|[33mLOG_ON[34m|[33mLOGOFF[34m|[33mTOTAL [34m|\n [34m|----------------+----------------+-------+----------+------+------+------|\n [34m|[0m Wil H.         [34m|[0m Chico, CA      [34m|[0m  2400 [34m|[0m 03-12-94 [34m|[0m 0155 [34m|[0m 0256 [34m|[0m 0061 [34m|[0m\n [34m|[0m LELAND         [34m|[0m Chico, Ca      [34m|[0m 14400 [34m|[0m 03-11-94 [34m|[0m 2328 [34m|[0m 2330 [34m|[0m 0002 [34m|[0m\n [34m|[0m LELAND         [34m|[0m Chico, Ca      [34m|[0m 14400 [34m|[0m 03-11-94 [34m|[0m 2327 [34m|[0m 2328 [34m|[0m 0001 [34m|[0m\n [34m|[0m LELAND         [34m|[0m Chico, Ca      [34m|[0m 14400 [34m|[0m 03-11-94 [34m|[0m 2321 [34m|[0m 2322 [34m|[0m 0001 [34m|[0m\n [34m|[0m STARMAN        [34m|[0m Chico, Ca      [34m|[0m 14400 [34m|[0m 03-11-94 [34m|[0m 2248 [34m|[0m 2252 [34m|[0m 0004 [34m|[0m\n [34m|[0m STARMAN        [34m|[0m Chico, Ca      [34m|[0m 14400 [34m|[0m 03-11-94 [34m|[0m 2245 [34m|[0m 2246 [34m|[0m 0001 [34m|[0m\n [34m|[0m LELAND         [34m|[0m Chico, Ca      [34m|[0m 14400 [34m|[0m 03-11-94 [34m|[0m 2236 [34m|[0m 2243 [34m|[0m 0007 [34m|[0m\n [34m|[0m STARMAN        [34m|[0m Chico, Ca      [34m|[0m 14400 [34m|[0m 03-11-94 [34m|[0m 2226 [34m|[0m 2229 [34m|[0m 0003 [34m|[0m\n [34m|[0m STARMAN        [34m|[0m Chico, Ca      [34m|[0m 14400 [34m|[0m 03-11-94 [34m|[0m 2224 [34m|[0m 2224 [34m|[0m 0000 [34m|[0m\n [34m|[0m LELAND         [34m|[0m Chico, Ca      [34m|[0m 14400 [34m|[0m 03-11-94 [34m|[0m 2222 [34m|[0m 2223 [34m|[0m 0001 [34m|[0m\n [34m+-------------------------------------------------------------------------+\n [34m|  [32mProgram design and coding by tibor of Virtual Palace BBS 916-343-7420  [34m|\n [34m+-------------------------------------------------------------------------+[0m\n\n\n\nWhat do I need to know about ShareWare:\n---------------------------------------\n   If you use this program on a regular basis then please send a minimum of \n$4.00 (or more) to me the author of the code.  You will be entitled to receive\nfuture upgrades of this program as they become available.  Please not that\nthis program will be modified many times thus the improvements in future\nreleases of this program will be worth the MINIMUM cost to you.  So where do I\nsend my $4.00 (or more)??  Send check, moeny order, or CASH ... to:\n\n   Tibor G. Balogh\n   P. O. Box 5518\n   Chico, CA 95927\n\n\n\nIs there a disclaimer that I need to know about:\n------------------------------------------------\n   Yes, run this program at your own risk.  I have tested the program with my\nAMIGA 3000 and it runs fine, but that may not be the case for you on your \nsystem.  Please note that the author does not asume any responsibility for \ndamage caused by the use or misuse of this program, use it at your own risk.\n\n\n\nHow do I receive future upgrades:\n---------------------------------\n   If you want to receive future upgrades then send the shareware fee and \nlogon to Virtual Palace BBS at 916-343-7420 to receive future upgrades to\nthe software.\n\n\n\nBug reports:\n------------\n   Please send all suggestions and bug reports to [email removed] if\nyou have an internet account or to the address above or call the BBS which\nhas the phone number above as well.\n\n\n\nOther limitations:\n------------------\n   You may use this porgram for evaluation only, continnued use requeres \nregistration.  You may not dissasemble, modify, hack, change anything in the\nexecutable file.  You may not edit out any information in the executable file.\nYou may crunch it with PowerPacker or Imploder software.\n\n\n','\n',char(10)),NULL,'auto-added',81068,4,0,NULL,NULL,'amipeek','scan',1780048403);
