INSERT INTO door_catalog VALUES('annou_11','ANNOU!11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ANNOU!11.LHA','MuchMore','XIM','MuchMore','1.1','SoulCatcher/AFL','ANNOU','Informs the Sysop of someone logging on by using the SPEAK: device.',replace('ANNOUNCE! v1.1 by SoulCatcher/AFL\nInforms the Sysop of someone logging on\nby using the SPEAK: device.\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 19:57:08  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',13530,1,0,NULL,NULL,'annou_11','scan',1780048410);
INSERT INTO door_catalog VALUES('ansi10','ANSI10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ANSI10.LHA','Ansi','XIM','Ansi',NULL,NULL,NULL,'| /__ \/ |/ | /__ \_/__ \_/__ \/__ \ | __|/  |__\ |  |/  |__\  |  \  |__\ |__\|__ /_//____  \_|  |___ __\_ |   \ |/_____ \_\_\',replace('AnImAl/\_--/|-/|--/\_---/\_---/\_--/\_--x\n   | /__ \/ |/ | /__ \_/__ \_/__ \/__ \ |\n __|/  |__\ |  |/  |__\  |  \  |__\ |__\|__\n/_//____  \_|  |___ __\_ |   \ |/_____ \_\_\\n\_\\   |   /|  |  /|   / |   / |\    |  //_/\n---x\_____/_|____/____/__|__/__| \_____/x---\n     Ansi Selector v1.0 for AmiExpress\n33.6 DigITal-X Prd/NirVana Dist Site! 33.6\n','\n',char(10)),'Ansi.doc',replace('-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n                              Ansi Selector v1.0\n\n                               Code By Dux/TsL\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n\nThis may LOOK like an ansi SKIPPER, but with the little feature that allows\nyou to force the users to use either ansi OR ascii.\n\nIt should be installed like any other XIM door in the SYS.cmd as *ANSI.\nIf you don''t want the users to turn ansi on/off after they''ve logged on, you\nshould also disable the ''M'' function!\n\nThe Ansi Selector needs a small configfile, with a ''Y'' or a ''N'' for ansi y/n.\n\n\nThat''s all there''s to this one.\n\nHellos as usual to:\n\nAll TSL members - Alzheimer - Frostie - Ramirez - Scratch - Matriz - Ice Q -\nZany - Stonehead - Lector - Shock - Yobbo - Heat\n','\n',char(10)),NULL,'auto-added',13720,9,0,NULL,NULL,'ansi10','scan',1780048410);
INSERT INTO door_catalog VALUES('ansides','ANSIDES.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ANSIDES.LHA','AnSi-DeSiGnEr','XIM','AnSi-DeSiGnEr',NULL,'MDB',NULL,'/  / \  \  \  ___  \ \  ___ \ /  /\_/\  \ /\/| /  / /\/ /  / \  \   /  //   |/  / /  |/   \ Productions',replace('   _____/\   ______/\  _____/\ \n  /  / \  \  \  ___  \ \  ___ \\n /  /\_/\  \ /\/| /  / /\/ /  /\n \  \   /  //   |/  / /  |/   \ Productions\n  \__\ /__/ \______/  \__|____/\n| ANSI-DESIGNER 2.1 by MDB ProDuCtIoNs     |\n| Make your own ANSI logos                 |\n`------------------------------------------''\n','\n',char(10)),'AnSi-DeSiGnEr.GuIdE',replace('@DATABASE "ANSI DeSiGnEr 2.1.guide"\n@NODE MAIN "ANSI DeSiGnEr 2.1"\n                             ANSI DeSiGnEr 2.1\n                             © MDB PrOdUcTiOnS\n\n   @{" Copyright " LINK MDB-00}\n   @{" Screen    " LINK MDB-01}\n   @{" Library   " LINK MDB-97}\n   @{" Example   " LINK MDB-98}\n   @{" Contact   " LINK MDB-99}\n\n@ENDNODE\n\n@NODE MDB-00 "Copyright"\n\n(C) Copyright 1993-94 MDB Productions.  All Rights Reserved\n\n@ENDNODE\n\n@NODE MDB-01 "Screen"\n\nThe user screen is devided into three parts.\n\n   @{" Part 1 " LINK MDB-02} is the text input area.\n\n   @{" Part 2 " LINK MDB-03} is the library area.\n\n   @{" Part 3 " LINK MDB-04} is the action area.\n\n\n@ENDNODE\n\n@NODE MDB-02 "Part 1"\n\nPart 1, the text input area, is the place where you can type three lines\nof ten characters which whill be transformed to ANSI later on. Also a \ndestination file must be specified. This can be done by using the file\nrequester.\n\n@ENDNODE\n\n@NODE MDB-03 "Part 2"\n\nThis part gives you information about the active library. Its name, version\nand the characters available are displayed.\n\nThere is also a possibility to use another ANSI font, by activating an\nexternal library. First type in its name or use the file requester. Then\nload the external library. When the library is correct, the new library\ninformation will be shown.\n\nSee also: @{" Library   " LINK MDB-98}\n\n@ENDNODE\n\n@NODE MDB-04 "Part 3"\n\nYes, here the action starts.\n\n   o @{" START "} transforms the ASCII lines to ANSI and writes the file.\n\n   o @{" ABOUT "} just a little note.\n\n   o @{" SHOW  "} show the ANSI result.\n\n\nLast and least the status messages will be printed here.\n\n@ENDNODE\n\n@NODE MDB-97 "Library"\n\nNot implemented yet.\n\n@ENDNODE\n\n@NODE MDB-98 "Example"\n\n                 _______/\______   /| _____/\  __/\ \n                 \       /\  \  \ | | \  ___/  \  / \n                  \_/\  /  \  \  \| |  \/ \    /\// \n                  / _/ /   /  /\    | __\  \  /  /  \n                  \// /   /__/  \   //__   / /  /   \n                   /_/           \_/    \_/  \_/    \n \n ______/\  _____/\ _____/\  __/\  _____/\ ______   /| _____/\ _____/\ \n \  ___  \ \  ___/ \  ___/  \  /  \  ___/ \  \  \ | | \  ___/ \  ___ \\n /\/| /  / /\/|__\  \/ \    /\//  /\/|  __ \  \  \| | /\/|__\ /\/   _/\n/   |/  / /   |___ __\  \  /  /  /   |_| / /  /\    |/   |___/  |\  \ \n\___   /  \___   //__   / /  /   \___   / /__/  \   /\___   /\__|/\  \\n    \_/       \_/    \_/  \_/        \_/         \_/     \_/       \_/\n\n                        ______/\      _____/\ \n                        \  __ _/      \  ___/  \n                         \// /        /\/ | \  \n                          / /_/\     / /__|  \\n                         /__   /  __ \____   / \n                            \_/  /_/      \_/  \n@ENDNODE\n\n@NODE MDB-99 "Contact"\n\nYes, contact me:\n   MDB Productions\n   PWA-park 93\n   3905 CC  Veenendaal\n   The Netherlands\n   08385 - 29239\n\nIt is also possible to make special external libraries for you. Just send\nme a plain ASCII file with all the ANSI chars. I will convert it for you\nfor free.\n\n@ENDNODE\n\n','\n',char(10)),NULL,'auto-added',11028,1,0,NULL,NULL,'ansides','scan',1780048410);
INSERT INTO door_catalog VALUES('antihack','ANTIHACK.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ANTIHACK.LHA',NULL,'XIM','Anti Hacker Util by |<rypton / \/enture',NULL,'|<rypton',NULL,'33.6 DigITal-X Prd/NirVana Dist Site! 33.6',replace('Anti Hacker Util by |<rypton / \/enture\n33.6 DigITal-X Prd/NirVana Dist Site! 33.6\n','\n',char(10)),'Hackershell.doc',replace('                /\nti |-|acker \|til by |<rypton / \/enture\012\012I just decided to do a small anti Hacker Util in Arexx...\012Include it in Your Customcommands as :\012*tX       RM005Doors:Hacker.rexx\012in the 1.1X version and you''ll get informed about tries to hack !\012It will write you this message in the Callerslog of the node the\012User logged on: USERTRIEDTOHACKYOURBBS!!\012\012Please change thsi line to your own BBS\012address command "echo >>Stuff:Bull255.txt " || name || " tried to hack the BBS !!"\012                        ^^^^^^^^^^^^^^^^^\012Bulletin in a conference that tells you that User XXX tried to hack the bbs!\012\012Greeting to CHRIS/DECADE, CARNIVORE, ALFRED, FDT, TCM, RCF, DEVIL, FRED/VF,\012            WHITEHEAT, M C |-|AMSTER, FLYNN, GUYBRUSH TREEPWOOD, KNS, GARFIELD\012            and all others I forgot !\012','\012',char(10)),NULL,NULL,7887,5,0,NULL,NULL,NULL,'scan',1780048410);
