INSERT INTO door_catalog VALUES('ax5ed5es','AX5ED5ES.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AX5ED5ES.LHA',NULL,'XIM','aPpLeSS.exe',NULL,NULL,NULL,'|\/|//\\||)) || /|| ||   //__//\\||\\//_ ||||\\//||\\ ||//|| ||   \\//\\//||//¯// ¯  ¯ ¯¯ ¯¯ \\|// ¯¯¯¯¯¯¯  ¯¯  ¯¯ ¯¯¯¯¯¯ Inc.',replace('_  _ __ ___ ____ __ __    ___ __ ___  ___\n|\/|//\\||)) || /|| ||   //__//\\||\\//_\n||||\\//||\\ ||//|| ||   \\//\\//||//¯//\n¯  ¯ ¯¯ ¯¯ \\|// ¯¯¯¯¯¯¯  ¯¯  ¯¯ ¯¯¯¯¯¯ Inc.\n   » BrInGs \ / Ya Today : «\n============================================\n » Best /X-Modem settings « \n--------------------------------------------\n only SUPRA, TKR, USR, ZYX Modeme \n      more in SOON \n--------------------------------------------\nRelease 2 / Version 1.9    -> Fåker-Tools\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-24-18  TIME: 13:58:46  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',23904,4,0,NULL,NULL,'ax5ed5es','scan',1780048418);
INSERT INTO door_catalog VALUES('axdate45','AXDATE45.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AXDATE45.LHA','AxeDATE4-000','XIM','AxeDATE4-000',NULL,NULL,NULL,NULL,replace('Axdate door for /X\n','\n',char(10)),'AxeDATE.Guide',replace('@database "amigaguide.guide"\n\n@Node Main "amigaguide.adoc"\n                    ____    ___  ________    _  _________ _ \n                    \__.\  /__ \/  __/__ \  / \/ ___  __ _\n                     / | \/ \__/  / / \__/ /    /  | |\n                    /  |  \____\ _/ \____\/     \  | |\n                  ++\  ___/++/  /+++++++++\_/\  /++| |++\n                     \/      \_/              \/   : .\n                    $p®eaÐ the Wø®Ð - $p®ead the Wa®ez\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n                 _       ___ ________ __  __  __  _____ _\n              ___\\   /\ \''//-_/\_  //. \/  \| /_ \_ \ //___\n              \.  \\ /  \/.\\__\ /_/ \__/\__/|__//___///  ./\n               \\  \\~~~~~~~~~~~~~~~~~~~~~~~~~+Ð¡B$+~//  //\n                \ / \\      .:P R E S E N T S:.     // \ / \n                 Y   \)     ^^^^^^^^^^^^^^^^^^^    (/   Y\n                 !                                      !\n                           @{"AxeDATE V4.5 - UPDATE" Link "AxeDATE"}\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n\n                Every Hour Of Every Day I`m Learning More.\n              The More I Learn The Less I Know About Before.\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n\n                                  @{"Quick Dox" Link "QuickDox"}\n                               @{"Icon Tooltypes" Link "TOOLTYPES"}\n                              @{"Call These Boards" Link "CALL"}\n                              @{"Acknowledgements!" Link "Acknowledgements"}\n@EndNode\n\n@Node "QuickDox" "Quick Dox To AxeDATE4.5"\n\nQuick Dox:\n\n            @{"AxeDATE V4.5" Link "AxeDATE"}\n            Is a Utility Written For @{"Ami Express" Link "Ami Express"} V2.xx or above.\n            It will Append A Date Line To Selected Filelistings.\n            \nRequireMents:\n\n            Any Amiga Model With Kickstart V2.04 Or Above.\n            Approx. 50k Of Free Available Memory.\n\nHow To Install:\n\n            Simply Drag The Version For Your Machine(ie 000,030,040),\n            into your @{"SYS:WBStartup/" Link "WBSTARTUP"} drawer. Then click on the icon\n            and go to the Information menu, to set up the util`s\n            @{"ToolTypes" Link "TOOLTYPES"} for your preferences.\n\n\n@{"MainMenu" Link "Main"}\n@EndNode\n\n@Node "TOOLTYPES" "ToolTypes"\n             @{"NCONFS" Link "NCONFS"}\n                   \n             @{"CONF.x" Link "CONF.X"}\n                   \n          @{"ICONIFIED" Link "ICONIFIED"}\n   @{"ICONIFY.LEFTEDGE" Link "ICONIFIED1"}\n    @{"ICONIFY.TOPEDGE" Link "ICONIFIED2"}\n                  \n           @{"BBS_NAME" Link "BBS_NAME"}\n                   \n         @{"BBS_COLOUR" Link "BBS_COLOUR"}\n        @{"DATE_COLOUR" Link "DATE_COLOUR"}\n         @{"AXE_COLOUR" Link "AXE_COLOUR"}\n        @{"LINE_COLOUR" Link "LINE_COLOUR"}\n\n@{"MainMenu" Link "Main"}\n@EndNode\n\n@Node "WBSTARTUP" "The SYS:WBStartup/ Drawer"\n\nAnything In This Drawer Will Automaticly Be Executed When The\nLoadWB Command Is Issued. So If AxeDATE Is In Here, Then It WIll\nAutoLoad Along With Workbench And @{"Ami Express" Link "Ami Express"}\n\n@EndNode\n\n\n@Node "Ami Express" "Ami Express ©1993 Light Speed Technologies"\n  \n                   AMI-EXPRESS HOST BULLETIN BOARD SOFTWARE\n                   ----------------------------------------\n\n       Ami-Express is a host Bulletin Board software program, allowing\n       the transfer of data, between host and remote terminals via a\n       telephone link. This data can be files uploaded or downloaded\n       from remote (user end) from the BBS databases. Most Bulletin\n       boards also contain message bases where you can read and leave\n       electronic mail to other users. It is possible via some BBS`s\n       to play online games, although these are of a simple nature,\n       they can still be quite entertaining. For those of you that\n       have been a user, either host or remote, for some time, will have\n       noticed the major changes that Ami-Express has undergone. With the\n       future proposed implementations Ami-Express will soon become\n       comparable to other Major BBS programs found on Amiga and PC\n       computers.\n\n       If you own a an Illegal (Cracked copy) and you use it, then\n       consider buying the original. This will not only provide you with\n       support etc, but will encourage the further development of \n       Ami-Express.\n\n@{"MainMenu" Link "Main"}\n\n@EndNode\n\n@Node "AxeDATE" "AxeDATE4.5 ©1993 AxeTOOLS/Defekt"\n\n                               AxeDATE V4.5\n\n                             Written By AxeMAN\n                         Logo Drawn By Grasshopper\n\nFULL HISTORY!!!!!\n-----------------\n\nV1.00       First Ever Version!, Ran In Logoff Script and added a date line\n            Like this\n\n===================> 23-03-91 <===============================[AxeDATE]====\n\nV1.1        Fixed cos it only ran on about 40% of machines , now 99.9%\n            Compatible.\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\nV2.00ß      Updated to Kickstart2 ONLY. Changed Date Line To Look Like This\n\n===============> Tuesday 23 MAR 91 <======================[AxeDATE]====\n\nV2.1        Released On Das Boards(FIRST Release Of AxeDATE)\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\nSuspended Work To Work On Other Stuff\nAnd Lost Source To V1 and V2 In a freak\nCoffee Spillage.\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\nV3.0        ReThunk My Ideas, Decided A Resident Program Would Be Better\n            Designed a Nice Window Based Version, And a Beautiful Config\n            Editor. Added the ability To Use A BBSName. Date Line : \n\n============> Tuesday 23 MAR 91 <=[ The Jamaica Inn ]============[AxeDATE]==\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\nV4.0        After Getting /X v3.xx Allowing Unlimited Conferences Had\n            To ReDesign AxeDATE to Take Account Of it.\n            So Out Went The Config Editor. And In Came The ICON\n            ToolTypes. Added Unlimited Conferences.\n            \nV4.5        Added The Ability To Set The Background line`s Colour eg\n\n============> Tuesday 23 MAR 91 <=[ The Jamaica Inn ]============[AxeDATE]==\n^^^^^^^^^^^^^                   ^^^                 ^^^^^^^^^^^^^^       ^^^\n\n  All Of The Marked Bit May Be Set To a Colour.\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n                                The Future?\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n\nI Will Add an Option That Makes AxeDATE Remove The Last Date Line If\nNo Uploads Have Been Put In The Conference Eg.\n\n============> Tuesday 23 MAR 91 <=[ The Jamaica Inn ]============[AxeDATE]==\n\n\n==========> Wednesday 24 MAR 91 <=[ The Jamaica Inn ]============[AxeDATE]==\n\nBut With The New Option The Tuesday Line Would Be Replaced By the New Date.\nThis Stops Cluttering.\n\nI Will Also Add True AppIconifying And Not Just Shrinking The Window Into a \n1x1 Pixel Window(What a cheat i am..But Hey Joe Hodge Gets Away With It..).\n\nI May Also Alter The Window. To Put The Date/Time In The Window And Maybe\nA Status report Of The Last Days Update.\n\nMaybe a Requester Canceler/Reset On Crash Built In?.\n\nAny Other Ideas???????? Mail Me On a @{"Defekt BBS" Link "CALL"}.\n\n@{"MainMenu" Link "Main"}\n@EndNode\n\n@Node "NCONFS" "AxeDATE4.5 ©1993 AxeTOOLS/Defekt"\n\n                      NCONFS\n                              This Specifies The Number Of Conferences\n                              You Have set Up For /X.\n                              eg.   NCONFS=2\n\n@EndNode\n\n@Node "CONF.X" "AxeDATE4.5 ©1993 AxeTOOLS/Defekt"\n\n                      CONF.x  \n                              This Is The Path To The Dir Listing.\n                              eg. CONF.1=BBS:Conf1/Dir1\n                                  CONF.2=BBS:Conf2/Dir2\n@EndNode\n\n@Node "ICONIFIED" "AxeDATE4.5 ©1993 AxeTOOLS/Defekt"\n\n                   ICONIFIED  This Will Make AxeDATE Iconify Upon Running\n@EndNode\n\n@Node "ICONIFIED1" "AxeDATE4.5 ©1993 AxeTOOLS/Defekt"\n            ICONIFY.LEFTEDGE  The Y Co-Ordinate To Iconify To(Optional)\n@EndNode\n\n@Node "ICONIFIED2" "AxeDATE4.5 ©1993 AxeTOOLS/Defekt"\n             ICONIFY.TOPEDGE  The X Co-Ordinate To Iconify To(Optional)\n@EndNode\n\n@Node "BBS_NAME" "AxeDATE4.5 ©1993 AxeTOOLS/Defekt"\n\n                    BBS_NAME\n                              This Specifies The BBS Name.  \n                              If Not Present AxeDATE Will Default To\n                              `Your Fave BBS`\n                              eg  BBS_NAME=@{"The Jamaica Inn" Link "The Jamaica Inn"}\n\n@EndNode\n\n@Node "BBS_COLOUR" "AxeDATE4.5 ©1993 AxeTOOLS/Defekt"\n                  BBS_COLOUR  The Colour To Print The BBS Name In.\n\nSee Also : @{"Colours" Link "COLOURS"}\n@EndNode\n\n@Node "DATE_COLOUR" "AxeDATE4.5 ©1993 AxeTOOLS/Defekt"\n                 DATE_COLOUR  The Colour To Print The Date In.\n\nSee Also : @{"Colours" Link "COLOURS"}\n@EndNode\n\n@Node "AXE_COLOUR" "AxeDATE4.5 ©1993 AxeTOOLS/Defekt"\n                  AXE_COLOUR  The Colour To Print The AxeDATE Logo In.\n\nSee Also : @{"Colours" Link "COLOURS"}\n@EndNode\n\n@Node "LINE_COLOUR" "AxeDATE4.5 ©1993 AxeTOOLS/Defekt"\n                 LINE_COLOUR  The Colour To Print The Line In.\n                 \nSee Also : @{"Colours" Link "COLOURS"}\n@EndNode\n\n@Node "COLOURS" "AxeDATE4.5 ©1993 AxeTOOLS/Defekt"\n\nPossible Colours\n                     BLACK\n                     WHITE\n                     GREEN\n                     YELLOW\n                     BLUE\n                     MAGENTA\n                     CYAN\n                     RED\n                     \n@{"MainMenu" Link "Main"}\n\n@EndNode\n\n@Node "CALL" "AxeDATE4.5 ©1993 AxeTOOLS/Defekt"\n\nCall These Defekt Boards:\n\n                           @{"The JAMA¡CA ¡NN" Link "The Jamaica Inn"}\n                         @{"Nø®tHE®N  ×-Pø$µ®E" Link "Northern Xposure"}\n                               @{"ENT¡T¥" Link "Entity"}\n\n@{"MainMenu" Link "Main"}\n@EndNode\n\n@Node "The Jamaica Inn" "AxeDATE4.5 ©1993 AxeTOOLS/Defekt"\n\n\n    SYSOPS : Cø$Mø & Ð¡B$\n    NUMBER : +44 - 91 - 370 - 2781\n\n  HARDWARE : Amiga A3000/25Mhz - 6Megs 32Bit Ram - 136Megs Online\n             Courier 14400 HST Modem.\n\n@{"MainMenu" Link "Main"}\n@EndNode\n\n@Node "Northern Xposure" "AxeDATE4.5 ©1993 AxeTOOLS/Defekt"\n\n    SYSOPS : A/\/F\n    NUMBER : +44 - 642 - 788 - 778\n\n  HARDWARE : Amiga A1200/14Mhz - 2Megs 32Bit Ram - 120Megs Online\n             Courier 14400 Dual Standard Modem.\n\n@EndNode\n\n@Node "Entity" "AxeDATE4.5 ©1993 AxeTOOLS/Defekt"\n\n    SYSOPS : $T/\B\n    NUMBER : +44 - 81 - 292 - 1550\n\n  HARDWARE : Amiga A2000 - 6Megs 32Bit Ram - 120Megs Online\n             Courier 16800 Dual Modem.\n\n@EndNode\n\n@Node "Acknowledgements" "AxeDATE4.5 ©1993 AxeTOOLS/Defekt"\n\n        Amiga Is A Registered ® Trademark Of Commodore Business Machines.\n        \n        Ami Express Is ©1993 Light Speed Technologies.\n\n        HST Is © USRobitcs.\n\n        AxeDATE 4.5 Was Written In C Using SAS/C 6.2.\n        \n        \n        Any Simmilarity Between This Program And Any Other Is\n        Purely Coincidental.\n\n\n        Any Simmilarity Between D-Man And A Human Being Is\n        Also Purely Coincidental.\n\n@EndNode\n','\n',char(10)),NULL,'auto-added',29171,2,0,NULL,NULL,'axdate45','scan',1780048423);
INSERT INTO door_catalog VALUES('axechalk','AXECHALK.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AXECHALK.LHA','Chalky','XIM','Chalky',NULL,NULL,NULL,NULL,replace('Chalky Chicken Speaks!!\n','\n',char(10)),'The_PIT.TXT',replace('\n   D     _________ __  ___  _____     ________)\ ________  \n   O    |         |  ||   |/     |   |       \  |        | Sysops:\n   W    | __o  ___|  ||  o|o  __ |   |o  |    \o|__o  ___|      /\kiR/\\n   N     Y ||  | |   ||  ||| |_ \|   ||  |    /|| ||  |          KIDLAT!\n   L       ||  | |   __  |||  _|     |:   ___/ || ||  |\n   O       |:  | |   ||  :|: |__/|   |.  |  |  :| |:  |   AmiExpress 3.1\n   A       |.  | |_  ||_ .|.     |   |_  |  |  :| |. /  16.8 DUAL STANDARDS\n   D       | __|   \ |  \ |\____ |     \ |  |_ .| | /     1.5 GIGS ONLINE\n   E        Y       Y    Y      Y [ABN] Y     \ |  Y       4  N O D E S !\n   D        :       |    .      |       :      Y   |     A3000T 040/25mgz\n            .  A PRIVATE Bulletin Board System .   : \n   FROM....                                                  !! LATEST\n               A M I G A  *  P C  *  C O N S O L E S        WAREZ ONLY !!\n         \n TARKUS TEAM WHQ <> RAZOR 1911 CHQ <> ROMKiDS WHQ <> WORLDWIDE TRADERS INC WHQ\n\n      Co-Sysops:  BLUE BIRD/SBS <> RAZOR BLADE/RZR <> DCSL/TARKUS TEAM\n __                __                __                __                __\n \/ (718) 397-5413 \/ (718) 397-5532 \/ (718) 397-5520 \/ (718) 397-5442 \/\n\n              UploAd TiMe: -=> Mon 02-Aug-1993 08:02:27 <=-\n','\n',char(10)),NULL,'auto-added',15343,10,0,NULL,NULL,'axechalk','scan',1780048423);
INSERT INTO door_catalog VALUES('axedate3','AXEDATE3.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AXEDATE3.LHA','AxeDate3-000','XIM','AxeDate3-000',NULL,NULL,NULL,'o/  .\   \./ __/      .\___ __.\  __/   _./ / __  \   /  __X__/ \__/\/ /\/ / /  \__ \/B \ \   /   \     //   \    /   /     /   /u.',replace('  _________________________________________\no/  .\   \./ __/      .\___ __.\  __/   _./\n/ __  \   /  __X__/ \__/\/ /\/ / /  \__ \/B\n\ \   /   \     //   \    /   /     /   /u.\no\/\_/_\___\___/o\___/\__/\__/\____/\__/B.o\n+-=-T-H-E-=-T-0-0-L-$-=-F-A-(-T-0-R-Y-!-=-+\n:     AxeDATE V3.4 - For Ami Express      :\n+-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-+\n','\n',char(10)),'AxeDATEDox.TXT',replace('\n                                AxeDATE V3\n                              -  - ---- -  -\n\nWhat is it????\n---- -- ------\n\nAxeDATE is a util for /X BBS Sysops. At midnight EVERY night it will \nAdd a date seperator to the filelists you select, in the form:\n\n===============> Saturday 10 APR 1993 <==[ The Jamaica Inn ]========[AxeDATE]=\n                 ^ date string      ^      ^ BBS name    ^\n\nIt is totally configurable, allowing you to set the colour of the date,\nthe BBS name, the AxeDATE logo, And The BBS Name (of course!).\n\n\nGreat Now How Do I Install it??????\n----- --- --- -- - ------- --------\n\n       To install AxeDATEV3 simply follow these rather simple docs.\n             -- - --------------------------------------- - --\n\n1>  Copy both AxeDATE3 and AxeDATEConfig to the C: directory.\n\n2>  Edit the file S:User-Startup and add the line\n\n    AxeDATE3\n\n    or if you want the window opened in iconified mode simply put\n\n    AxeDATE3 Iconified \n    or\n    AxeDATE3 I\n              [They both do the same job]\n\n3>  Once that is done run the AxeDateConfig Util, its is a full\n    GUI util, and is self explanitory.\n\n4>  Save your config, by using the pull down menu.\n\n5>  Quit AxeDateConfig. And Reboot your amiga, then axedate will\n    load and run.\n\n\nCredits and stuff\n------- --- -----\n\nAll code and User Interface was designed by Axey!\nThe AxeDATE Logo was drawn by Grasshopper(Thanks Man!).\nThe Original Idea Was by some obscure person called Jetman.\n\n\nThats rather natty...How do i get more?\n----- ------ ----------- -- - --- -----\n\nFor Updates and other utils that make the rest hang their heads in shame\ncall the following boards. And leave mail to /\xe-/X\an.\n\n              The Jamaica Inn - AxeTOOLS WHQ - +44-91-3702781\n\n                          QED -              - +44-91-3720620\n                          \nOther Utils Released:-\n\n        AxePAGE V1.4 - /X X page door\n     AxeUserValidate - /X User Questionaire\n          ChalkySays - /X Fortune Cookie(with GFX by Executioner)\n             AxeEDIT - Replacement door for EMACS for use with /X\n             AxeHELP - /X Door / Help with /X Commands\n           DMSDeluxe - DMS Tester Written By Captain Dread\n\nAxeTOOLS In Development\n\nAxeCOMM - Comms Package with XPR/XEM and even XPK support\n        - XPK files as they are downloaded!..of if you are using\n        - AxeCOMM on both ends, XPK while upload!\n        - beats Xcomm/Ncomm/Term into the floor!\n\nBBPro   - /X Beater, FULL bbs, with everything /X hasn''t got!\n        - FULL Xpr Support, INFINITE nodes/Conferences\n        - All Controlled from one main program...no external\n        - programs needed.\n\nDMS D2  - DMS Deluxe V2, Replacement for DMS Windows version\n        - includes:\n        -           Kickstart 2 userinterface\n        -           about 2times faster than DMS 1.3\n        -           and XPK support for compressing disks\n        -           Using XPK!\n','\n',char(10)),NULL,'auto-added',34314,5,0,NULL,NULL,'axedate3','scan',1780048423);
INSERT INTO door_catalog VALUES('axedate4','AXEDATE4.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AXEDATE4.LHA','AxeDATE4','XIM','AxeDATE4',NULL,NULL,NULL,'« A X E - T O O L S » ******************************************** « A x e D A T E - V 4 »',replace('********************************************\n           « A X E - T O O L S »\n********************************************\n          « A x e D A T E - V 4 »\n********************************************\n','\n',char(10)),'2Nodez.TXT',replace('\n           -( [ DiGiT/\L X ] [ oNE oF tHE fASTEST iN eUROPE ] )-\n\n            PaRaDiSe wORLD iNNOVATION wORLD dISTRIBUTION sITE!\n\n              ________  ____________________  __   _/\  ___\n              \____   \/  / ___/  /_  _/    \/ /   \  \/ \/\n               \   \   \ / /__^  / / //  ^  /  \___ \    / \n               /_______//\___/__/ /_/ \_/\_/\_____/ /    \_\n               DREAM MACHINE WorLD DHQ CenTer ©    /__/\___\n\n\n  Node [1] +31-570-637050  Node [2] +31-570-636468  Node [3] +31-570-677702\n\n  Amiexpress V4.20 Registered On An Amiga 2000 GVP-Tekmagic 68060 32MB KS3.1\n    Pioneer Changer DRM-604X + Toshiba Cd-Rom 4 HD''s 7110MB Space Total...         \n\n   2 * cREDITZ fOR mAJORS! 3 * cREDITZ fOR mAJORS fROM yOUR oWN gROUP!\n    pROVIDING yOU: Amiga ECS/AGA, PC, AmiExpress, Sex Pic, Sex Stories\n\n          ---»> nO nEW uSER pASSWORD aND/oR sYSTEM pASSWORD! <«---    \n                                                                      \n       -( [ DiGiT/\L X ] [ oNE oF tHE BesT FroM The EaSt SidE ] )-\n\n','\n',char(10)),NULL,'auto-added',30547,7,0,NULL,NULL,'axedate4','scan',1780048423);
INSERT INTO door_catalog VALUES('axeolist','AXEOLIST.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AXEOLIST.LHA','AxeLIST','XIM','AxeLIST','1.00',NULL,NULL,NULL,replace('AxeLIST - ONLINE - V1.00ß\n','\n',char(10)),'AxeLIST.Doc',replace('                         AxeLIST - ONLINE - V1.00ß\n                         ------- - ------ - ------\n\n                   Someone asked for it. So here it is!\n\n  Once upon a time there was a utility called:-\n  \n  AxeLIST\n  \n  It was a simple utility, which listed all the users who called a BBS\n  that ran AmiExpress BBS S/w.\n  \n   --------------------------------------------------------------------\n\n                               This is now,\n                            and that was then.\n\n   --------------------------------------------------------------------\n\n  Although this utility served its purpose well, it had to ran\n  at each logoff. Ho-Hum. So someone shouted at me. They said,\n  \n             `Hey, Axey, Why not make it into an online door!''\n \n  Our Survey said\n\n                                 `Urr-Urr''\n                                 \n  But me being me, i did it anyway.\n  \n  \n   --------------------------------------------------------------------\n                   I Dont know how many stars there are,\n                        up in the clear night sky,\n                     I only know what i need to know,\n                        Dont ask me questions why.\n   --------------------------------------------------------------------\n\n               --=={ This door is a /X 3.xx ONLY door! }==--\n\n  To install simply make a directory in your DOORS: directory called\n  ''AxeLIST''. and copy the files into it.\n  \n  Copy the AxeLIST.Info file into the BBS:Commands/BBSCmd/ directory.\n  \n  And AxeLIST - Online is installed.\n  \n  For More AxeTOOLS Call:\n  \n             The Jamaica Inn - }{-Press UKHq - +44-91-3702781\n\n','\n',char(10)),NULL,'auto-added',19502,10,0,NULL,NULL,'axeolist','scan',1780048423);
