INSERT INTO door_catalog VALUES('axo_sw10','AXO_SW10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/AXO_SW10.LHA','Switch','XIM','LE-win5-96.exe',NULL,'Json','AXO','/X-/   / / / __/_ _/ \/\   \ _ \ _ \   \S / / / / / __/   /   ¯¯\ \ \  ¯\ \ \__¯\d /___/___/___/_/_/_______\___\_\_\___\___\N',replace('    _________________  ________________\n/X-/   / / / __/_ _/ \/\   \ _ \ _ \   \S \n  / / / / / __/   /   ¯¯\ \ \  ¯\ \ \__¯\d\n /___/___/___/_/_/_______\___\_\_\___\___\N\n \___\___\___\_\_\_ _____/___/_/_/___/___/\n<«»=%=%P·R·O·U·D·L·Y  P·R·E·S·E·N·T·S%=%=«»>\n+------------------------------------------+\n|   Switch v1.o for /X 3.x by Json / AXO   |\n|  this tool moves the user.data''s to the  |\n|  conf.db. This allows CONF_ACCOUNTING!   |\n`------------------------------------------''\n','\n',char(10)),'Switch.doc',replace('\n\n\n\n\n /X-              ___\n   _____________ / _/______ ______  _____   ______________  ________ _______\n  _\____   \   //  \      /\\    ¬\ \   /\ _\____   \    ¬\ \____  ~\\   __/\\n \\    /  /// //  /// /__/ /// / _/\/  /__\\    /  /// / _/\/   /   /_\\ \ \ \\n  //  /  //  //  //  ____\//  /_ ~//  /  ~\//  /  //  /_ ~//   /   /  ¬   \\\ \\n /_______\_______\________~\__//__\_______/_______\___//__\_______/jT_____/\ \/\n \  _____ \  ____ \  ______ \ \\   \  ___ \  _____ \  \\   \ ____ \  ____ \ \\n  \ \____\ \ \___\ \ \_____\ \ \\ \ \ \__\ \ \____\ \\ \\ \ \\___\ \ \___\ \ \\n   \________\_______\_________\_\\___\______\________\__\\___\______\_______\/\n\n\n                        Switch v 1.o by Json / /X-OVeRLORDS\n\n This tool is a tool I''ve been looking for since /X-Developers invented Conference\nAccounting! but it did not seem like anybody would make one, so I sat down one\nday and coded a test version to use on my own board. When I found out how easy\nit really was I made a public version and this is it!\n\n This tool was tested on my own board and on Sky Tower ( Hi! to my m8 Enzo! ),\nand it seems to work 100%, but to make sure nothing goes wrong please make a\nback up of the following: user.data - user.keys - all conf.db''s...\nas I don''t guarentee anything!\n\n How to configure it to your needs!\n\n with the Switch file is a icon, following tooltypes are awailable:\n\n                   CONF.<x>=<y|TRANSFER>\n\nEXAMPLE\n-------\n\n Your board has a AMIGA ELITE Conference (Conf 2), a PC Conference (Conf 3),\nand a /X Conference (Conf 4), now you want to make sure nobody leeches from\nyour /X Conf. therefore you want a ratio of 1:1 in that conf. In the Amiga Conf.\nyou want to have a ratio of 1:3 and the same in the PC conf. Then you drop these\nlines in the Switch.info:\n\n                CONF.2=3\n                CONF.3=3\n                CONF.4=1\n\nthat means that all other confs will have disable! and all users will have\ncleared accounts! BUT with the TRANSFER argument you can move all\nupload/download/bytes up/bytes down/messages send to one conference! let''s\nsay you want to move the stuff to your AMIGA ELITE:\n\n                CONF.2=TRANSFER\n                CONF.3=3\n                CONF.4=1\n\nThis will move all credits to Conf. 2 including the ratio from the user.data!\nIf you''ve got more than one major conf. like a AMIGA ELITE and a PC ELITE this\nwill mean that you have to do some manual work! this tool can only move the\ncredits to one conf! but I''m planing to release a door that will allow the users\nto move their up/down bytes/files to what ever conf. they want! this should\nsolve the problem!\n\n\nINSTALL\n-------\n\n  well.... just drop the Switch in bbs:utils/ and make sure the Switch.info\nis the same place!! and when you''ve backed up your data, you drop this line\nin a CLI:   "bbs:utils/Switch"  that should do it!\n\nany problems/bugs contact me at:        STaTiC CHaoS       +45-86439514\n\nor throw a message to me on:            SKy ToWeR          +45-75141744\n                                        MeTaL CoNNeXTioN   +45-74435949\n\n\nGreets to:\n----------\n\n all my friends in KiNGDoM and /X-OVeRLORDS, my old friends in CReeD\n Slammer/(damn) Rednex, Pain&Pleasure (loot on!)\n\n a big tnx to Enzo for testing my BETA version..\n\nHello to:\n---------\n\n Mystic /X Design.....   keep up the work lads... looking forward to chatting\n with you guys some day!!\n\n sTc / 5D....   neat doors...\n\n\nThe motto of /X-OVeRLORDS ( AXO )\n---------------------------------\n\nrelease doors/tools that are needed (not crappy shit!), make them FAST, and make\nthem better!!\n\n\n\nThat''s it, and that''s that!!\n\n\n\noh.. btw: you wanna call these boards!!\n\n        ___   __  _/\_  ___/\___  ___/\___  ___/\___  ___/\___  ___  ___\n       /   | /  \|    |/   \    \/        \|        \/        \/   \/   \\n      /    |/    \    |     \    \         \         \         \         \\n     /           /    |           \   |_____\   |     \   |     \         \\n     \           \    |           /   |_    /   |     /   |     /         /\n      \    |\    /    |    \     /         /         /         /  \  /   /\n     TF\___| \__/|_  _|\___ \___/\___  ___/|___  ___/\___  ___/\___\/___/\n                   \/      \/   WORLD\/WIDE!   \/        \/\n    .______________________________________________________________________.\n    |                                                                      |\n    |                            dA bOARdS:                                |\n    |                                                                      |\n    | STaTUs:   NoDEz:  NaMe:             SysOp:          dA nUMBa:        |\n    | -------   ------  ----------------  --------------  ---------------- |\n    | WoRLd hQ    4R    thE hOlE          OldMAN          +1  419 899 2745 |\n    | ScAn  hQ    2R    SkY tOWER         ENZo            +45 751 417 44   |\n    | dK    hQ    2     StATiC cHAoS      Json            +45 864 395 14   |\n    | dK    hQ    3R    MeTaL cONNEXTiON  WoZZy&ViOLAToR  +45 744 359 49   |\n    | Nz    hQ    1     CRyStAl CaVeRNs   RAiDEN          +64 962 410 84   |\n    |                                                                      |\n    |                         mORE tO cOMe....                             |\n    |        /\        /\                       /\             _           |\n     \  /\  /  \  _ /\/  \   /\  /\/\    _/\ /\/  \  /\      _/ \ /\  /\   |\n      \/  \/    \/ Y      \ /  \/    \  /   Y      \/  \/\  /    Y  \/  Y\ |\n                           Y          \/                  \/              \|\n','\n',char(10)),NULL,'auto-added',5519,1,0,NULL,NULL,'axo_sw10','scan',1780048423);
