INSERT INTO door_catalog VALUES('bbbulls2','BBBULLS2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BBBULLS2.LHA','BBbULLS','XIM','BBbULLS',NULL,NULL,NULL,'|  |AD |  |ROTHERS ______  |  |___|  |____   ______ \_\_\_\ |  / _ |  / _  | /_/_/_/',replace('              __     __ \n             |  |AD |  |ROTHERS\n     ______  |  |___|  |____   ______\n     \_\_\_\ |  / _ |  / _  | /_/_/_/\n     /_/_/_/ |   / ||   / | | \_\_\_\\n   stneserp  l______l_______|  presents\n-------------------------------------------\n  BBbULLS To.2 FoR /T\EMPEST   (12-25-94)\n-------------------------------------------\n    FEATURES: o cursor-key handling\n              o one or two rows\n              o a lot more...\n-------------------------------------------\n','\n',char(10)),'BBbULLS.gUiDe',replace('@database "BBbULLS To.2 bY MuRpHy oF ??? BaD bRoThErS ¿¿¿"\n@AUTHOR "MuRpHy"\n@(C) "MuRpHy oF BB/UNL"\n@Ver$ "- BBbULLS To.2 - 12-25-94 -"\n@HEIGHT 30\n@Node MAIN "ThE MaIn MeNu"\n===============================================================================\n.--.    ____   ____    .--.    ____    ___________________ _________  _________\n|  |   |    \ |    \   |  |   | __ \  /    \__   ___| |   |    \ __ \/        /\n|  |___|  |_ \| |\  \  |  |___|   \ \/  /\  \ |  | |  ¯¯  |  __/   \ \ ______/\n|  / _ | ___\ \   \  \ |  / _ |  __\ \ /  \  \|  | | ___  |  __) ___\ \____  \\n|   / ||  |   /   /  / |   / ||  |   \ \__/  /|  | |  |   |    \  |   \      /\nl______l__|__/l_____/  l______l__|____\_____/ l__| l__l___|____/__|____\____/\n\n===============================================================================\n\n   @{"*>     fEaTuReS     <*" link "Menu1"}   -> BBbULLS To.2 <-   @{"*>     GrEeTiNgS    <*" link "Menu6"}\n   @{"*>  hOw tO iNsTaLL  <*" link "Menu2"}                        @{"*>     CaLL noW!    <*" link "Menu7"}\n   @{"*>  cOnFiGuRaTiOnS  <*" link "Menu3"}           bY\n   @{"*>   fUtURe pLaNS   <*" link "Menu4"}                        @{"*>  oThEr BB Tools  <*" link "Menu8"}\n   @{"*>      hIsTOrY     <*" link "Menu5"} MuRpHy oF bAD bROTHERS\n\n===============================================================================\n\n\n@endnode\n\n@Node Menu1 "fEaTuReS"\n\n     This is a replacement for the Tempest Bulletins Menu....\n\n     - fully coded in `C`\n     - it`s fast\n     - adds header (Amiga or IBM)\n     - Amiga and IBM ansis available\n     - one or two rows of bulletins\n     - cursor-key handling\n  \n     @{"BaCk To ThE mAiN mEnU" link "MAIN"}    @{"hOw to iNsTaLL" link "Menu2"}\n@endnode\n\n@Node Menu2 "hOw tO iNsTaLL"\n\n    put this line into your *.opt file...\n\n    ---------------------->> Cut Here <<--------------------------\n    [*,*,*,*,*] = B   |T-DOOR|DOORS:BBbULLS/BBbULLS\n    ---------------------->> Cut Here <<--------------------------\n\n\n    now you only have to configurate it...\n\n \n     @{"BaCk To ThE mAiN mEnU" link "MAIN"}    @{"cOnFiGuRaTiOnS" link "Menu3"}\n@endnode\n\n@Node Menu3 "cOnFiGuRaTiOnS"\n\nTHIS SHOULD ALL BE LOCATED IN `DOORS:BBbULLS/''\n\nEdit the Headers:\n-----------------\nThe headers should be named `HEADER.AMI'' and `HEADER.IBM''... these\nheaders are shown in front of the bulletins menu...\n\n\nEdit the BBbULLS.cFG file:\n--------------------------\nHere is an example how it should looks like:\n\n---------------------->> Cut Here <<--------------------------\nTWO_LINES=YES                                      ; Two Rows [YES/NO]\nBULL.01=RECORD STATUS\nBULL.02=LAST 10 CALLERS\nBULL.03=TOP 15 ULLERS&LECHZERS\nBULL.04=TOP 15 CALLERS\nBULL.05=TOP 15 MAILERS\nBULL.06=WEEK TOP LECHZERS\nBULL.07=WEEK TOP ULLERS\nBULL.08=USERLIST\nBULL.09=10 DAYS REPORT\nBULL.10=30 DAYS REPORT\nBULL.11=NEW USERS\nBULL.11=SYSTEM USAGE\n---------------------->> Cut Here <<--------------------------\n\n1.Line to choose one or two rows\n2 to end the bulletins...\n\nFinished now....\n\n			It`s easy, isn`t it ?\n\n     @{"BaCk To ThE mAiN mEnU" link "MAIN"}    @{"fUtURe pLaNS" link "Menu4"}\n@endnode\n\n@Node Menu4 "fUtURe pLaNS"\n\n   Future plans are:\n\n   - bulletins only shown in special conferences\n   - bulletins only shown with an access defined\n   - design your own bulletins\n   - online bulletins\n\n   - and many many more... maybe you have an idea ?\n\n\n     @{"BaCk To ThE mAiN mEnU" link "MAIN"}    @{"hIsTOry" link "Menu5"}\n@endnode\n\n\n@Node Menu5 "hIsTOrY"\n\n   History:\n   --------\n\n   To.1o:  - First version (not released)\n             Features: One or two rows, IBM and AMIGA design, Header possible\n\n   To.2o:  - Cursor-Key Handling added\n\n\n     @{"BaCk To ThE mAiN mEnU" link "MAIN"}    @{"GrEEtInGS" link "Menu6"}\n@endnode\n\n\n@Node Menu6 "GrEEtInGS"\n\n\n                            GREETINGS GOES TO:\n\n     Intercode, Br/\indead, Technoking!, [tHE aDDiCt!], [-jOE cOOL!],\n         Sisko, Satan^God, Czar^Zeus, Whiz, Airworx, Hexer, MuMu,\n             Spider, -sLiME!, Evil Uncle, E-Motion, Hijack, CF\n\n\n        to all other SysOps and Group Leaders I forgot to remember\n\n                  And to all Users of the Homebase BBS...\n\n\n     @{"BaCk To ThE mAiN mEnU" link "MAIN"}    @{"CaLL ThEsE bOaRdS" link "Menu7"}\n@endnode\n\n\n@Node Menu7 "CaLL ThEsE bOaRdS"\n===========================================================================\n    .        .        .        .      .        .       .    .    .      .\n .     .        .   .    .        .      .        .       .  .      .     .\n    .        .       /\_______ .  /\______/\_____      .         .      .\n___ __ __.__ _ __.__/       .¬\ _/  ___  ¬\     ¬\_.___ __ _._ _ __.__ __ _\n                   /_______ __/\/°_  _   ./____   \\n                   \__/° \__  \//  \/    /°  /\\ . \ -MaD-\n____ __ __ _ __ _ _ _//  /   . \   /   .//  /¯¯¯  ./\_ __ __ _ _ _ _ __ ___\n__ __ __ _ _ _ __ __/___/______/__/____/ __/______/ /_ ___ _ _ __ _ ____ __\n .      .        .  \___\______\__\____\/\_\______\/ .     .         .    .\n    .        .        .        .      . \/    .  ____  .          .     .\n. /\_______/\_____  .  /\______/\______________./  ¬/\_____/\___.  /\___  .\n_/       .¬\_____¬\_ _/  \    ¬\   /  \  .¬/  //  ./    .¬/____¬\_/   .¬\__\n/_______ __/\/°___ /\/°  /__  ./__/°  /___/  //   /°\____/ /°___ /\  \___\\n\__/° \__  \// \  :\//  /\ /  /\_//  /\_/°  _¯  .// ___>__// \  :\¯\_  \__\\n _//  /   . \  /\  .\  /¯¯¯ ./ //   / ///  //   /  /    ./   /\  .\°.\  \__\n_/___/______/_/ /___/_/_____/ //.  / // __//___/\  _____/___/ /___/ ____/\_\n.\___\______\_\/\___\_\_____\//   / /¯\/\_\\___\/\/\____\___\/\___\/\___\/.\n    .        .        .      /___/ /  .\/      .  \/   .         . \/-MaD-\n .     .        .        .   \___\/      .        .       .         .     .\n    .        .        .        .      .        .       .         .      .\n===========================================================================\n\n               CaLL tHeZe coOl ??? BaD bRoThErS ¿¿¿ BoaRDs\n\n\n_______________          _____      _____   _________       ___________________\n\.            /________ |.   /_____:o    | /.        \/|___/_       \         /\n \___   _____/|.   /   \||  /|.    |:    |//   ______/·|.   / ______ \    ___/\n   /.   /_/·  ||  /     \:  \||    |·    |/   /   \ \/ ||  /_______ \/+    /\n  //  ____/   ||  \   \  \   \:   ¯¯¯    |   /    / /  ||  \ /·\  /  \  __/__\n //   / //    |+   \   \      \  \___/   |   \___/ /   |·   \/  \/   /      /\n/·   /  \\         /    \     /    |:    |        /         /       /      /\n\___/    \________/_____|\___/:    |_____|_______/\________/_______/______/\n                             l_____|·MBB·\n\n\n              NoDE 1+2: ASK FOR IT [19K2 ZyXel aND 28K8 Usr]\n\n                      NoDe 3+4: ASK FOR IT [64K ISDN]\n\n                    SysOp: InTeRcOdE and some CoSysOps\n\n                  ?BB¿ [w·H·Q] ^ UNL [e·H·Q] ^ MGE dIST.\n\n\n       _____ \n _____:     |_____     /\    /\    _______/\_____ _______________________/\\n|.    |.    |    .\   /· \  // \  /.       /__   \\       / _____