INSERT INTO door_catalog VALUES('bbl_lt02','BBL-LT02.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BBL-LT02.LHA',NULL,'XIM','_°______/\_ ______/\______/\_  °',NULL,NULL,'BBL','\______ ¬\\______ ¬\____  ¬\  · bOMbELL · /::  |/  //::  |/  /  \   ·/_a pRODiGiOUS / ·sPN|/   ·\   |/   ·\/  ·/ ·\_· sYSOP ·',replace('_°______/\_ ______/\______/\_  °\n  \______ ¬\\______ ¬\____  ¬\  · bOMbELL ·\n  /::  |/  //::  |/  /  \   ·/_a pRODiGiOUS\n / ·sPN|/   ·\   |/   ·\/  ·/ ·\_· sYSOP ·\n \_____    · /___    · /__     ·/  · oF ·°\n°_ ___ \____/ __¬\____/ ¬\____/·nO nAME bBS\n              .::pROUDl¥ pRESENTS::.\n[lOTTO v0.2FULL , dOOR fOR /X & lOGIC BBS!!]\n[ iT aLLOWS tO wIN tIME n'' cREDz iN BBS!!  ]\n[4 NEWST UPDATES CALL nOnAME BBS 4872153971]\n.::::[oH no! lEECHED fROM nOnAME bbS! ]::::.\n·::::::[nOnAME wHQ ] [ +48-72-153971 ]::::::·\n','\n',char(10)),'LOTTO.guide',replace('@DATABASE LOTTO.guide\n@WIDTH 80\n@REMARK  .-------------------------------------------------------.\n@REMARK  | This document should be read with AmigaGuide (OS 2.x) |\n@REMARK  | or MultiView (OS 3.x) or any other guide reader. Tnx. |\n@REMARK  `-------------------------------------------------------''\n@REMARK  $VER: LOTTO 0.1 BETA\n@NODE MAIN " BOMBELL lOTTO ver 0.1 fOR LOGIC BBS "\n\n                          WELCOME tO gUIDE fOR lOTTO\n\n          wHICH iS A DOOR FOR LOGIC BBS vER 1.013+ bY PARCON SOFTWARE\n\n                          pROGRAM vERSiON : 0.1\n\n                           © 1995 by @{"Bombell" link Contact}\n\n                    @{" INTRODUCTiON " link introduction} wHAt THE fUCk iS thiZ ?\n                    @{" REQUIREMENTS " link reqs        } wHAT iT rEQUIRES ?\n                    @{" INSTALLATION " link install     } hOW tO iNSTALL ...\n                    @{" CONFIGURATiON" link conf        } hOW tO cONfIgUrATE ?\n                    @{" CONTACT      " link contact     } hOW tO cONTACT wITH bOMBELL...\n                    @{" HISTORY      " link history     } hISTORY oF LOTTO\n                    @{" GREETZ       " link greetz      } sOME gREETZ...\n                    @{" PICCO INFO   " link pikko       } nFO aBOUT piCCO!\n\n@ENDNODE\n\n@AUTHOR "sPOONMAn/[·|''·¡·[·[·Ø·]\n@(C) "Copyright 1995 sPOONMAN/piCC0"\n@$VER: LOTTO.guide 0.1(23.06.95)\n\n@NODE introduction " wHAT iZ lOTTO ? - © bOMBELL "\n\n                yO! iT''s sPooNMAN/|''·¡·[·[·Ø· oN lINE nOW !\n\n     sO I wRiTE sOME iNFo ABOUT nEW rELEASE ... a mOTHER fUCKED gOOD\n    dOOR 4 lOGiC bbS!... (cool! a new door 4 logic...) sO it''ll be a...\n\n                              LOTTO vER 0.1\n\n  wITh dIZ dOOR iT''ll bE AVAiLBLE tO wIN oR lOSE sOME tIME^cREDZ iN yOUR\n                                lOCAL bbZ !\n\n  HEHE cooll... jUST wHAT yA HAVE to dO it''z oNLY to cHoiCE beEtWEEn\n  pLAYinG bY tiME oR dL liMIT... tHEn yA hAVE to tYPE soME 6 numbas\n  n'' we Start lOSTSin'' hehe... iF yA hIT 6 nUMBAS YA hAVE *DSBLD*\n  rATiO!... fOR 2 hITED NUMBAS YA wiN 5 minuTEZ  oF tIME (or 10 kb oF\n  dL liMiT ) fOr 3... etc..  fOR 1 GAME YA hAVE tO HAVE oN yoUR ACCoUNT\n  5 miNUTEZ oF tIME oR 10kb oF dL liMit ... YA cAN ALSO cHAnge tHE STAKE\n  fOR bIGGER..hehe (iN thiZ VER oNLY ZYZ cAN mAKE thIZ thing...)\n  After loSiNG yA geT tHE rESUlts.. hehe cool... sO iNSTaLL iT *NOW!*\n\n  Eh.. IF YA wANNA to See tHIZ thINGy iN acTioN bUT yA doN''t hAVE lOGiC bBS!\n  jUZt cAll me ... n''   uSE ''lOTTO'' cOMMAND..\n\n\n                                                @{"·sPOONMAN/piCCo·" link SPN}\n\n@ENDNODE\n\n@NODE reqs " wHAT iT rEQUIRES ? - © bOMBELL "\n\n\n                                 wHAT iT rEQUiRES ?\n\n                           hEh... oNLY 2 thiNGiES...\n\n               - aMIGA 1000/500/500+/600/1200/2000/3000/4000 ...\n                 wiTH OS 2.x + ...\n                 thiZ dOOR wIll nOT rUN oN pEEzEE cLOWNS hehe...\n\n               - fULLY iNSTALLED lOGiC bBS ... iT''s bETTeR tHAn /X..\n                 (iF YA waNNa to sEE iT cALl +48-71-576946... )\n\n\n\n                                                @{"·sPOONMAN/piCCo·" link SPN}\n\n@ENDNODE\n\n@NODE install " hOW tO iNSTALL... - © bOMBELL "\n\n\n                                hOW tO iNSTALL ?\n\n       sIMpLY ... bY cOPyIn'' "COMMANDS" n'' "DOORS" diRECTORYs tO vOLUME\n       cALLED ... "BBS" sIMPLY eHH ?\n\n\n                                                @{"·sPOONMAN/piCCo·" link SPN}\n\n@ENDNODE\n\n@NODE conf " hOW tO cONfIgUrATE ? - © bOMBELL "\n\n                               hOW tO cONFigURATE ?\n\n    1)iF yA wANNA tO chANGE cONF sIMPLY eDIT bBS:dOORS/BOMBELL_AREXX/LOTTO_ENG\n      DANE/LOTTO.CFG...\n\n      iN 1TH lINE yA cAN cHANGE pASSWORD tO sTAKE-ED (thIZ iZ 1th line)\n      oTHER liNEs yA cAN chANGE wITH loTTO sTAKE-eD...\n      iN tHIZ lINES aRE pLACED iNFo aBOUT sTAKES...\n\n    2)IF yA wANNA tO chANGE ACCES tO thIZ dOOR sIMPLY eDiT bBS:commands/\n      bbscmd/lotto...\n\n-----------------------------------------CUT HIER--------------------------\nNAME		BomBeLL LOTTO v0.1 ENGLISH VERSiON ; NAME oF dOOR...\nACCESSLEVEL	100                ; ACCES tO uZE tHiZ ...\nLOCATION	DOORS:bombell_arexx/LOTTO_ENG/LOTTO_ENG.rexx ; pLiZ dOn''t cHange iT!\nMULTINODE	YES                ; mULTiNODE ? yep..\nTYPE		AIM                ; dOn''T cHANGE ...\nPRIORITY	0                  ; yOUR cHOiCE\nSTACK		4096               ; sTACk ... lEAV iT ...\nHELP            wITH thiZ dOOR yA cAN wIN oR lOSE sOME cREDZ iN bbS! ; hELP..\n-----------------------------------------CUT HIER--------------------------\n\n    n'' thAt''z All.. iF yA doN''t kNOW sUMTiN'' cAAL me... sPOONMAN.. tHE\n    doC wRiTER..\n\n                                                @{"·sPOONMAN/piCCo·" link SPN}\n\n@ENDNODE\n\n@NODE contact " hOW tO cONTACT wITH bOMBELL... - © bOMBELL "\n\n                          hOW tO cONTACT wITH bOMBEL ?\n\n               juZT cALL rUSSiA bbS +48-71-576946 n'' write to bOmbell\n\n  fUCK aMiGA gUiDE           OR cALL bOmBELL''s bBS ...\n        |\n        |       |\n        |           _ __._________   _______                         !\n        `--->   |       |:.      ¬\_/      ¬\_--- +48-72-153971 -----+\n      __  ______|.......|¾  __  ø  /:. __  ø /.......................:\n               ¬:::    _|   ¬|     \_  ¬|    \_                    :::\n        yOU aRE :::    \_    !      /   l     /  fUCKING aN A12oo  ::|\n         cALl   :::     l____j     /_________/ 6 mEG rAM/1.3 GB hD ::|\n       ! tHiS ! :::      ~~~~l_ _ j~~~~~~~~~~     lOGiC bBB v1.13  :::\n                :::                                                ::|\n                :::                       FidoNet [ 2:481/16.7 ]   ::|\n      ._________:::______   ___________   _____                    ::|\n      |:       ¬\:/     ¬\_/          ¬\_/    ¬\_                  ::|\n      |¾. __   ø /:. _  ø /:. __  _   ø /:. ____/ ¾ oBSESSION hQ ¾ ::|\n     _|   ¬|     \_  |    \_  ¬|  |     \_  |___\_.................::|__\n     \_    !      /        /   |  |      /  ¬    /                  ¬|\n      l____j     /___j    /____j__|     /_______/¸                   |\n       ~~~~l_ _ j~~~~l_ _/~~~~~~~~l_ _ j~~~~~~~~ ¾ sYsOp: BomBeLL^oBS\n                                                                     |\n                                ¾ cOSYSOP: ZiuTeK^nATIVe & mAYBe yOU ¾\n\n\n                                                @{"·sPOONMAN/piCCo·" link SPN}\n\n@ENDNODE\n\n@NODE history " hISTORY oF LOTTO - © bOMBELL "\n\n                 tHERE IS nOT hISTORY noW.. iT''s 1TH vERSioN ...\n\n                         tHERE wILL BE oNLY fUTURE...\n\n                                                @{"·sPOONMAN/piCCo·" link SPN}\n\n@ENDNODE\n\n@NODE greetz " sOME gREETZ... - © bOMBELL "\n\n              gREEETZ fROM sPONMAN^bOMBELL tO fOLLOWin'' pERSOnS...\n\n                @{"·sPOONMAN/piCCo·" link SPN} - for wRITin'' thIZ gUIDE !\n                ZiUTEK/nATiVE - fOR cOOL wAREZ..\n                TyGRYSEK/$KULL$ - fiDo sUXX! hehe\n                sEBAX(zJEBAX)/oBSESSiON - uSR kEWL!\n                tOYO / ? - iN whicH gROUP aRE yA ?\n                pitER / rOYAL - fREE cALls rUlZ!\n                fENiX / ?     - nEMEziS ok !\n                mErCurY / oBS - mUZAk cool!\n                wilD tHiNG / yODEL^LGC dEV - yOUR dOORs aRE cOOL!\n                mARwIK / eQUInOX - wHAT aBOUT my CC hehe ?\n                slIME / BP - hOMELEZZ coOL...\n                wHiRLwiNd / mYTH - nUP doOR iZ cOOL...\n                mAVERiCK / piCC0 - ehehe....\n\n                n'' oTHERS...\n\n\n@ENDNODE\n\n@NODE spn " heh info about me.. the guide writer... "\n\n  e... nOW cOMMERciAL ! ... cALL rUSSiA BBS +48-71-576946...\n\n\n  fUCK aMiGA gUiDE fOR tHIZ liNES...\n  ________________________________________________________________________\n (___________________________________________\     ·/_____________________)\n  | ______________________________   _______|\\   ·//_______              |\n  | |::     ¬\__::  |    _/::    ¬\_/::    ¬\_\\ ·//\____ _¬\_            |\n  ! |·         |::  |    |:·  T    |:·  T    | \\//:|:: ___   |  cALL iT  |\n  : |     :    |·   ! ___|___ |____|___ |____|  \/ ·|·  | !   ||          |\n  · |  ___!__  |    : \__   |   \__   |     \  _ ___|__ !_:___|___*NOW!*  |\n    |  \_______|    ·    \  !     ·\  !      \ ___ ___/ ·_·_____///       |\n    |     |    \_________/\__:_   ·/\__:_    /      |   .|°   ||¯¯    :   :\n  ° |sPN! |____/`-------''    |____/    |____/`------''----|    |:      °   !\n    |_____| ... :.  ... +48..·     ...   .  __/\__  :    `----''° ..oR dIE!·\n                :            :     _________\ oO /______________________\n   [nODE1 +48-71-PRIV8  (ZYZONLY)](_________/_\/_\______________________)\n   [nODE2 +48-71*576946*(USR28k8)]|           \/                        |\n   [nODE3 +48-71-57SOON (USR28k8)]!aLL 540mB oF hD sPACE aRE w8''n 4 yA  !\n  ··· · ··     ···           :    : ..uPLOAD tO tHiS niCE BBS rUNNIn'' On:\n  : oFFiCAL wHQ·oF piCC0 ... .    ·a1200/030/6mB rAM ... wITH hELP  oF  ·\n    dAYLy fRESH·wAREZ...& mO