INSERT INTO door_catalog VALUES('bbla0404','BBLA0404.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BBLA0404.LHA','BB-Lastcaller','XIM','BB-Lastcaller',NULL,NULL,NULL,'\_     \  /    \  _   |   :/     \_    \ _|  \_/ \/   7  \/|   |   |   7   \  |  \__ |   |   \   j   \|   |   :   j   /  |   \',replace('_/\____    ___________.   ² ______/\___\n\_     \  /    \  _   |   :/     \_    \\n_|  \_/ \/   7  \/|   |   |   7   \  |  \__\n |   |   \   j   \|   |   :   j   /  |   \\n |   |    \______/l___l___j\_____/l__|    \\n_l___jdn  /_____ /T\iNNOVATIONS _____l____/\n     l___/ -> BB-Lastcaller v0.5 beta <-\n Lastcaller door for Tempest. \nCode:BiLBo BaGGins/M!^RNX    Design:Various\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 19:41:20  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',38811,1,0,NULL,NULL,'bbla0404','scan',1780048423);
INSERT INTO door_catalog VALUES('bblogoff','BBLOGOFF.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BBLOGOFF.LHA',NULL,'XIM',')->======================================<-(',NULL,'BOBO!.<-(',NULL,')->..:.::.B O B O  P R E S E N T S.::.:..<-( )->..:.::..H I S  U L T I M A T E..::.:..<-( )->..:A M I E X P R E S  U T I L I T Y:..<-(',replace(')->======================================<-(\n)->..:.::.B O B O  P R E S E N T S.::.:..<-(\n)->..:.::..H I S  U L T I M A T E..::.:..<-(\n)->..:A M I E X P R E S  U T I L I T Y:..<-(\n)->.ADDBBSTOLOGOFF V1.1 - CODED BY BOBO!.<-(\n)->======================================<-(\n','\n',char(10)),'addbbstologoff.doc',replace('\n                 Add Board to Logoff v1.1 (First Release)\n                 ------------Date: 14-Mar-1993-----------\n\n                         Copyright © 1993 - Bobo!\n                           East BBS +46-8-940614\n\n                    Doc typed at 27-Jan-1993 by RaJ-Ban\n                       Traders Nation +46-176-55202\n\n                         What is AddBBStologoff ?\n                         <======================>\n This is a Door which allows Users (Sysops) to add their own BBS to one\n of the Logoff-screens. How many times haven''t you got the Question about\n putting other boards to the Logoff-screen ? And they will keep asking\n over and over again until you finally put it there. Too lazy or to Busy\n to do that ? Well here''s the solution. No need to bother sysops, Users\n can handle all that by themselves (if the got the right access.).\n As Sysop you are able to enter how many boards you want in the logoff\n and you can also include a Header file to be displayed. It also allowes\n some sysop editing.\n\n\n                              Disclaimer\n                              <========>\n This Door is programmed in Arexx (at the moment!) and should not cause any\n problems. But as always theres no guarantee that it wont cause any damage.\n Anyway I, Bobo, take no responsibilities for what this door may cause to\n your Harddisc or Software. But I (and some other BBS''s) have been running\n this Door for about 4 weeks and NO Problem has accured. Bugreports and\n other suggestions are wanted, please look at the end of this document !\n This Door is CALLWARE. If you find it Useful and keep using it, call my\n BBS (perhaps to check for updates ?).\n\n\n\n                            What, Where and Why\n                            <=================>\n This package should incloude the following:\n\n File with Full Path                       Size   Description\n -----------------------------------------------------------------------\n East.Displayme                             1363  BBS-Ad.\n Doors:Arexx/Addbbs/Addbbstologoff.Doc     11044  You are looking on it.\n Doors:Arexx/Addbbs/Addbbstologoff.Update   2059  Whats new in v1.1?\n Doors:Arexx/Addbbs/Addbbstologoff.Rexx    23837  The Main Program.\n S:Addbbstologoff.Header                     705  Example Header included.\n S:Addbbstologoff.Help                      1260  Text for Online-Help.\n -----------------------------------------------------------------------\n If the filesize doesn''t match, Call my BBS for a new copy. Someone may\n have altered the code, and that could mean a backdoor.\n\n\n\n                           Installation The Door\n                           <===================>\n As a registered AmiExpress you know how to install a arexx type door in\n your system. If not, check the AE doc and try to understand the rest.\n First of all, make a dir in your DOORS:Arexx/ called ADDBBS or whatever\n you like. Copy the main program (and the doc) into that directory. Copy\n the Header and Help file to your S: dir. Now edit your BBS.cmd or the\n CustomCommands for older versions, located in your BBS:Command/ dir\n You should add something like this to your BBS.cmd file...\n\n -Cut Here-----------------------------------------------\n *ADDBBS   RS020Doors:Arexx/Addbbs/Addbbstologoff.rexx\n -Cut Here--|--------------------------------------------\n\n Addbbstologoff.Header\n ---------------------\n Now make a file called Addbbstologoff.Header or what ever you want it\n to be named (you can change it in the config). And in there you can have\n a logo for your board etc etc. Normally goes to the S: dir. (Look at\n the included one)\n\n Addbbstologoff.Config\n ---------------------\n To make the configfile, run your local node and run the door. Go into\n (S)ysopcommands and in there (M)ake/edit configfile. Here you can make/\n edit your config for your choices. :\n\n 1. Maxboards in logoffscreen........(10)\n 2. Seclevel to addboard.............(20)\n 3. Seclevel to access sysopcommands.(255)\n 4. Write log to callerslog..........(YES)\n 5. Headerfile.......................(S:Addbbstologoff.Header)\n 6. Helpfile.........................(S:Addbbstologoff.Help)\n 7. Outputfile.......................(BBS:Node1/Logoff.Txt)\n S. Save, quit and use this config...(Save)\n Q. Quit and use old config..........(Nosave)\n X. Quit and use this config.........(Nosave)\n\n ''Maxboards'' is the maximum numbers of boards to have on the logoffscreen.\n For example, you have it on 10, it will never be more than 10 boards in\n your logoff. Because when someone adds the 11th board, board number 1\n will be removed and the new board at the bottom etc (Going in a loop)\n\n ''Addboard'' is the lowest security level you''ll need to Add a board to the\n logoff (You maybe don''t want some lamers to add boards by them selves).\n\n ''SysopCommands'' is the lowest seclevel you''ll need to access the sysop\n (cosysop) menu. There you''ll have these options....\n [D]elete logoffscreen: Delete the logoff screen and reset all boards.\n [M]ake/Edit config   : Edit the S:Addbbstologoff.Config\n [E]dit Board         : Edit one of the boards that are added to the\n                        logoff screen.\n [R]emove Board       : Remove boards from logoffscreen.\n\n ''Log'' is if the door should write to callerslog when a user is using\n the door (You can for example see who have added wich board and so on).\n\n ''Headerfile'' is the file, with full path, you want to put over the boards.\n Example, you maybe want a logo for your bbs/group name or something\n like that to be showed at the same screen (look at the included one).\n\n ''Helpfile'' is the file, with full path, that will be displayed when a\n user presses the ''H'' key inside the door. (PLEASE don''t change the helptext)\n\n ''Outputfile'' is the output file of the Door (with full path). The outputfile\n can be BBS:Screens/Logoff.txt or the BBS:NodeX/Logoff.txt file etc etc.\n If you are using Random-logoffs, just give the outputfile a correct nr.\n\n\n\n                       Want to Change the Maxboards?\n                       <===========================>\n If you after a while would like to change the maxboards in the output,\n you''d have to (At the moment) reset the present .data file. The whole\n Procedure is easiest done by entering the SysopCommands inside the Door.\n Otherwise you''d have to manually delete the S:Addbbstologoff.data and then\n edit the S:addbbstologoff.config.\n\n\n\n                              Output Example\n                              <============>\n\n           [=> T H A N K   Y O U   F O R   C A L L I N G <=]\n             .       .       .          .        .       .       .\n          __/|___ __/|___.__/|_________/|_    __/|___ __/|___ __/|__\/_\n          \  _   \\  _   |\  _   \      _/    \  _   \\  _   \\  _   \\n   _ __ __/  |___//  |___|/  |___/\__/ _|__ __/__/   // _/   //  |___/\n  \\\\_\\_   __|_/   ___/|\___   \  / \\\\_\\____   </  \   < \___   \\n        /    |   \   |   |/   \   \/    |   /    \   \   \   \/   \   \\n        \  ______/___| __|______  /____ |   \______  /_____  /______  /\n  =======\/==========|/=========\/=====\|==========\/======\/===cgr=\/===\n\n    Y O U   C A N   A L S O   T R Y   T H E S E   C O O L   B O A R D S\n\nAddbbstologoff v1.1 - Coded in 1992/93 by BOBO! - Board: East BBS +46-8-940614!\n\nLast user added: Raj-Ban                        Last updated: 02-26-93 20:25:19\n.--+------------------+-----------------+-------------------------------------.\n|Nd| Boardname        | Phone           | Comment                             |\n+--+------------------+-----------------+-------------------------------------+\n|01| Dyers Eve        | +46-8-7618456   | F A i R L i G H T  P C  H Q ! !     |\n|01| Crazy World      | +46-8-6054434   | SYSOP CYBER & SLASH! NEWEST AM/PC!  |\n|01| The Outer Planes | +1-602-345-7672 | =CyNiX= WHQ! Newest SNES/ST stuff!  |\n|01| Risky Business   | +44-513-530299  | ELiTENDO WHQ! Newest SNES/ST Stuff! |\n|02| Garden of Eden   | +46-8-7042766   | FAiC EHQ - 2 Nodes 16.8k "Elite"    |\n|01| Illusion BBS     | +46-18-260565   | FAiC WHQ - HST 14.4k                |\n|01| Biomechaic Drms  | +46-8-317506    | CONSOLES ONLY! 250MB SNES/MD...     |\n|01| THE SLA/Y\ /Y\ER | +46(0)8-6230196 | ViRTUAL HQ 16&8 DS 68030 40Mhz /X   |\n|01| The Untouchable  | +46 8 774 78 83 | T.U.N.C WHQ . THE LATEST PC STUFF   |\n|01| Traders Nation   | +46-176-55202   | NEWEST AMIGA/PC WARES! SYSO RAJ-BAN |\n`--+------------------+-----------------+-------------------------------------''\n\n This is an example output from my board. As you see, we have a header\n above, and a maximum of 10 boards. (And ofcaurse, the ansi version looks\n much better)\n\n                           Other utils/doors in work\n                           <=======================>\n Multisysoppage......:With this utility, users are able to choice wich\n                      sysop they want to page (if you are more than one\n                      sysop on the system.)\n Remoteshell.........:The old cool remoteshell that was removed from\n                      Amie 2.0+ is now back. The same old remoteshell\n                      where you can do whatever you like. (Format hehe)\n Ultimate Usermessage:The most powerful usermessage utility ever done\n                      for amie. With alot of commands and options.\n Node Information....:A new nodeinformation door, that shows alot of\n                      informations about the users on the other nodes.\n Last Files..........:The best utility to show the last files in the\n                      area.\n Lha Checker.........:The best LHA checker utility. With this you can\n                      choice betwin check, add and remove adds.\n\n                        Don''t touch my arexx script\n                        <=========================>\n Don''t change anything in the source, becouse i have spent quite lot of\n time to make this program for you. And it doesn''t seam fair that you\n change something then write that it''s you who made the program. So,\n please call my board, and i''ll make the improvments you want!\n\n Programming and Idea by:  Bobo/East BBS\n Some Doc improvements by: RaJ-Ban/Traders Nation\n\n If you have any trouble when installing or running this door, you may \n either call my board, or some of my beta testers bbs for help. Those are\n the boards that are beta testing this utility.. :\n\n Amiexpress 1.1x with 68000 (1 Node) - East BBS (Mr.T) +46-8-940614\n Amiexpress 2.xx with 680xx (1 Node) - Traders Nation (Raj-Ban) +46-176-55202\n Amiexpress 2.xx with 68030 (1 Node) - Crazy World (Slash) +46-8-6054434\n Amiexpress 2.xx with 680xx (1 Node) - Dope House (Richi) +46-8-6031041\n\n I''m looking for more BETA testing boards!... :\n\n Amiexpress 2.xx with 68000 (Multinode)\n Amiexpress 2.xx with 68030 (Multinode)\n Amiexpress 3.xx with 680xx (1 Node or more)\n\n Call my board, or leave me a message somewhere if you''re intrested.\n\n ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                            That''s all folks...\n\n                  Call my board: +46-8-940614 (East BBS)\n\n                     For more cool doors and updates.\n\n ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n','\n',char(10)),NULL,NULL,13708,1,0,NULL,NULL,NULL,'scan',1780048423);
INSERT INTO door_catalog VALUES('bbnusa1','BBNUSA1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BBNUSA1.LHA','BBnUSA','XIM','BBnUSA',NULL,NULL,NULL,'|  |AD |  |ROTHERS ______  |  |___|  |____   ______ \_\_\_\ |  / _ |  / _  | /_/_/_/',replace('              __     __ \n             |  |AD |  |ROTHERS\n     ______  |  |___|  |____   ______\n     \_\_\_\ |  / _ |  / _  | /_/_/_/\n     /_/_/_/ |   / ||   / | | \_\_\_\\n   stneserp  l______l_______|  presents\n-------------------------------------------\n  BBnUSA To.1o FoR /T\EMPEST   (12-25-94)\n-------------------------------------------\n  FEATURS: o writing EALL message\n           o many more...\n-------------------------------------------\n','\n',char(10)),'BBnUSA.guide',replace('@database "BBnUSA To.1 bY MuRpHy oF ??? BaD bRoThErS ¿¿¿"\n@AUTHOR "MuRpHy"\n@(C) "MuRpHy oF BB/UNL"\n@Ver$ "- BBnUSA To.1 - 12-25-94 -"\n@HEIGHT 30\n@Node MAIN "ThE MaIn MeNu"\n===============================================================================\n.--.    ____   ____    .--.    ____    ___________________ _________  _________\n|  |   |    \ |    \   |  |   | __ \  /    \__   ___| |   |    \ __ \/        /\n|  |___|  |_ \| |\  \  |  |___|   \ \/  /\  \ |  | |  ¯¯  |  __/   \ \ ______/\n|  / _ | ___\ \   \  \ |  / _ |  __\ \ /  \  \|  | | ___  |  __) ___\ \____  \\n|   / ||  |   /   /  / |   / ||  |   \ \__/  /|  | |  |   |    \  |   \      /\nl______l__|__/l_____/  l______l__|____\_____/ l__| l__l___|____/__|____\____/\n\n===============================================================================\n\n   @{"*>     fEaTuReS     <*" link "Menu1"}   -> BBnUSA To.1o <-   @{"*>     GrEeTiNgS    <*" link "Menu6"}\n   @{"*>  hOw tO iNsTaLL  <*" link "Menu2"}                        @{"*>     CaLL noW!    <*" link "Menu7"}\n   @{"*>  cOnFiGuRaTiOnS  <*" link "Menu3"}           bY\n   @{"*>   fUtURe pLaNS   <*" link "Menu4"}                        @{"*>  oThEr BB Tools  <*" link "Menu8"}\n   @{"*>      hIsTOrY     <*" link "Menu5"} MuRpHy oF bAD bROTHERS\n\n===============================================================================\n\n\n@endnode\n\n@Node Menu1 "fEaTuReS"\n\n     This is a replacement for the Tempest Bulletins Menu....\n\n     - fully coded in `C`\n     - writing a message to EALL (conf eligible\n     - asks every time the answers are deleted: \n           if somebody has not answered all the questions, just delete\n           his answers and he has to do it again... \n     - empty lines are not accepted\n     - ansi bar background\n\n     @{"BaCk To ThE mAiN mEnU" link "MAIN"}    @{"hOw to iNsTaLL" link "Menu2"}\n@endnode\n\n@Node Menu2 "hOw tO iNsTaLL"\n\n    Add this line into your Text-WelcomeXX.xxx text...\n\n\n    ---------------------->> Cut Here <<--------------------------\n    ~TD(DOORS:BBnUSA/BBnUSA)\n    ---------------------->> Cut Here <<--------------------------\n\n\n    now you only have to configurate it...\n\n \n     @{"BaCk To ThE mAiN mEnU" link "MAIN"}    @{"cOnFiGuRaTiOnS" link "Menu3"}\n@endnode\n\n@Node Menu3 "cOnFiGuRaTiOnS"\n\nTHIS SHOULD ALL BE LOCATED IN `DOORS:BBnUSA/''\n\n\nEdit the BBnUSA.cFG file:\n--------------------------\nHere is an example how it should looks like:\n\n---------------------->> Cut Here <<--------------------------\n1\nY\n---------------------->> Cut Here <<--------------------------\n\n1.Line:  The Conf for the messages\n2.Line:  Ansi Bar Background Yes/No\n\n\n\n\nEdit the BBnUSA.quests file:\n----------------------------\nHere is an example how it should looks like:\n\n---------------------->> Cut Here <<--------------------------\n1[36m---[34m=============[33m( [0mWoher hast Du diese Nummer ? [33m)[34m======================[36m---[0m\n1[36m---[34m=============[33m( [0mWie lange hast Du einen Compi ? [33m)[34m===================[36m---[0m\n1[36m---[34m=============[33m( [0mHast Du eine Mailbox ? [33m)[34m============================[36m---[0m\n3[36m---[34m=============[33m( [0mWelche 3 Personnen kennen Dich ? [33m)[34m==================[36m---[0m\n3[36m---[34m=============[33m( [0mWelche 3 Mailboxen callste noch ? [33m)[34m=================[36m---[0m\n1[36m---[34m=============[33m( [0mBist Du in einer Gruppe <Welche> ? [33m)[34m================[36m---[0m\n1[36m---[34m=============[33m( [0mWas ist Dein Job ? [33m)[34m================================[36m---[0m\n1[36m---[34m=============[33m( [0mWuerdest Du fuer Free Download zahlen ? [33m)[34m===========[36m---[0m\n2[36m---[34m=============[33m( [0mSollte der SysOp noch was wissen ? [33m)[34m================[36m---[0m\n---------------------->> Cut Here <<--------------------------\n\n ^- the question\n\n^- number of answers you want for this question\n\n\n\n\nFinished now....\n\n			It`s easy, isn`t it ?\n\n     @{"BaCk To ThE mAiN mEnU" link "MAIN"}    @{"fUtURe pLaNS" link "Menu4"}\n@endnode\n\n@Node Menu4 "fUtURe pLaNS"\n\n   Future plans are:\n\n   - writing a message to the sysop with the answers\n   - questions in several languages\n\n   - and many many more... maybe you have an idea ?\n\n\n     @{"BaCk To ThE mAiN mEnU" link "MAIN"}    @{"hIsTOry" link "Menu5"}\n@endnode\n\n\n@Node Menu5 "hIsTOrY"\n\n   History:\n   --------\n\n   To.1o:  - First version\n             Features: o writing EALL message (conf eligible)\n                       o asks every time the answers are deleted\n                       o writing answerfile like Tempest\n                       o empty lines are not accepted\n                       o ansi bar background\n\n     @{"BaCk To ThE mAiN mEnU" link "MAIN"}    @{"GrEEtInGS" link "Menu6"}\n@endnode\n\n\n@Node Menu6 "GrEEtInGS"\n\n\n                            GREETINGS GOES TO:\n\n     Intercode, Br/\indead, Technoking!, [tHE aDDiCt!/], [-jOE cOOL!],\n         Sisko, Satan^God, Czar^Zeus, Whiz, Airworx, Hexer, MuMu,\n             Spider, -sLiME!, Evil Uncle, E-Motion, Hijack, CF\n\n\n        to all other SysOps and Group Leaders I forgot to remember\n\n                  And to all Users of the Homebase BBS...\n\n\n     @{"BaCk To ThE mAiN mEnU" link "MAIN"}    @{"CaLL ThEsE bOaRdS" link "Menu7"}\n@endnode\n\n\n@Node Menu7 "CaLL ThEsE bOaRdS"\n===========================================================================\n    .        .        .        .      .        .       .    .    .      .\n .     .        .   .    .        .      .        .       .  .      .     .\n    .        .       /\_______ .  /\______/\_____      .         .      .\n___ __ __.__ _ __.__/       .¬\ _/  ___  ¬\     ¬\_.___ __ _._ _ __.__ __ _\n                   /_______ __/\/°_  _   ./____   \\n                   \__/° \__  \//  \/    /°  /\\ . \ -MaD-\n____ __ __ _ __ _ _ _//  /   . \   /   .//  /¯¯¯  ./\_ __ __ _ _ _ _ __ ___\n__ __ __ _ _ _ __ __/___/______/__/____/ __/______/ /_ ___ _ _ __ _ ____ __\n .      .        .  \___\______\__\____\/\_\______\/ .     .         .    .\n    .        .        .        .      . \/    .  ____  .          .     .\n. /\_______/\_____  .  /\______/\______________./  ¬/\_____/\___.  /\___  .\n_/       .¬\_____¬\_ _/  \    ¬\   /  \  .¬/  //  ./    .¬/____¬\_/   .¬\__\n/_______ __/\/°___ /\/°  /__  ./__/°  /___/  //   /°\____/ /°___ /\  \___\\n\__/° \__  \// \  :\//  /\ /  /\_//  /\_/°  _¯  .// ___>__// \  :\¯\_  \__\\n _//  /   . \  /\  .\  /¯¯¯ ./ //   / ///  //   /  /    ./   /\  .\°.\  \__\n_/___/______/_/ /___/_/_____/ //.  / // __//___/\  _____/___/ /___/ ____/\_\n.\___\______\_\/\___\_\_____\//   / /¯\/\_\\___\/\/\____\___\/\___\/\___\/.\n    .        .        .      /___/ /  .\/      .  \/   .         . \/-MaD-\n .     .        .        .   \___\/      .        .       .         .     .\n    .        .        .        .      .        .       .         .      .\n===========================================================================\n\n               CaLL tHeZe coOl ??? BaD bRoThErS ¿¿¿ BoaRDs\n\n\n_______________          _____      _____   _________       _____________