INSERT INTO door_catalog VALUES('bbqn0405','BBQN0405.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BBQN0405.LHA','BB-Quicknew','XIM','BB-Quicknew',NULL,NULL,NULL,'\_     \  /    \  _   |   :/     \_    \ _|  \_/ \/   7  \/|   |   |   7   \  |  \__ |   |   \   j   \|   |   :   j   /  |   \',replace('_/\____    ___________.   ² ______/\___\n\_     \  /    \  _   |   :/     \_    \\n_|  \_/ \/   7  \/|   |   |   7   \  |  \__\n |   |   \   j   \|   |   :   j   /  |   \\n |   |    \______/l___l___j\_____/l__|    \\n_l___jdn  /_____ /T\iNNOVATIONS _____l____/\n     l___/ -> BB-Quicknew v0.9 beta <-\n  Shows today uploaded files of a conf\n  in a Bulletin.\nCode:BiLBo BaGGins/M!^RNX    Design:Various\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 19:41:14  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',16337,1,0,NULL,NULL,'bbqn0405','scan',1780048423);
INSERT INTO door_catalog VALUES('bbs_view','BBS-VIEW.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BBS-VIEW.LHA','BBS-VIEW','XIM','BBS-VIEW',NULL,'SieGeL/tRSi','BBS','\    ____    )  /___/\_| & rED sECTOR ¡NC | .-\___\ | \___\__   /   |  /X ¡NNOVATION   | `---|___|___|______/____|---[ [RESENTS ]---''',replace(' _____________ ___Mo! __.<---[ tRISTAR ]---.\n \    ____    )  /___/\_| & rED sECTOR ¡NC |\n.-\___\ | \___\__   /   |  /X ¡NNOVATION   |\n`---|___|___|______/____|---[ [RESENTS ]---''\n.------------------------------------------.\n|       BBS-vIEW V1.13 bY SieGeL/tRSi      |\n`------------------------------------------''\n    cLI-tOOL tO vIEW aNSI/ASCII-pICTURES\n dISPLAYS tHE pICTURES BBS-aLIKE, 1oo% ASM\n--------------------------------------------\n','\n',char(10)),'BBS-View.doc',replace('  _______________________________________________                  _______\n |  ___________      _______. ___________ _______|_      _________|_    _/\n |  \    _____/_____(_______:/   __     /___  ____/_____/_   __    /___ |\n | _/\_______     /         :   _______/   /  \__        /  ______/   / |\n | \ _ __________/__________:_____________/_____/  Mo!  /____________/  |\n |  \\ /                                       /_______/          l_____|\n |   \/  SIEGEL/tRSi (/X-iNNOVATiON) PRESENTS    |\n |      -------------------------------------    |\n |                                               |\n |                 BBS-View V1.13                |\n |                                               |\n |       fASTER tHAN lIGHT aNSI/aSCII vIEWER     |\n |                                               |\n | \                                             |\n | \\                                            |\n `-----------------------------------------------''\n\nIntroduction\n~~~~~~~~~~~~\nA long time ago (about 3 years) i''ve coded an ANSI-Viewer for CLI-Usage in\n100% ASM-Code...I use this tool since the first time, but it had some dis-\nadvantages i don''t like very much...so I decided to fix all these nasty bugs\nto re-release it, but this time bugfixed...:)\n\nWhat it is\n~~~~~~~~~~\nA simple, but very fast animation viewer for ANSI''S & ASCII''S. It displays\nall textfiles on an own screen (naturally it''s 640x256 PAL Screen, but you\ncould promote it to your needs!) with an ANSI-Colortable, meaning you see\nall pictures like an user in your BBS could saw them!\n\nWhat it needs\n~~~~~~~~~~~~~\nKickstart V37 or better (Kick 1.3 suxx!)\nasl.library V36 or better (for the FileRequester)\nSome Files to view...:)\n\nHow it works\n~~~~~~~~~~~~\nSimple...start it direct from CLI, and BBS-View pops up a Filerequester and\nasks you for a filename...select NOPE!/ABORT to cancel operation, or double-\nclick on a filename to view it.\n\nOf course you could give a filename to view it immediatly, for more infos\nenter ''BBS-VIEW ?'' in CLI-Prompt.\n\nAfter displaying the Textfile, BBS-View waits for a left-Mouseclick to exit.\n\nIf you view animations and don''t want to see the whole anim, simply press\nthe Closegadget to abort displaying.\n\nGreetings\n~~~~~~~~~\nByteAndi/tRSi      - Thx for driving me so often !\nbYSIS/iNDY         - cODING rOOLEZ, nICE wORK !\naRGON/pDY          - for support, testing etc..\nStrider/SDC        - I love FAME, it''s the best ! :)\n\n......And all the rest I''ve forgot to list here....FUEHLT EUCH GEGRUESST! :)\n------------------------------------------------------------------------[EOF]-\n\nIf you want to contact me or any other member of (tRSi/X-iNNOVATiON) for\nBug-Reports, Suggestions, gettin'' registered User or any other reason feel\nfree to call these boards:\n\n        _____ __ __ _____ __ _____.--.__ ________ ___________ __\n __ _ _/  ._ \_ |  \_    \__)     \_ | _/        \_ ___/     \_ l_  _\n   \ \\_  |/  / |  _/ |  _/\_  l___/ | \_  |  |  _/ _/\_  |  _/ _/_ /_\n       |   __/  |  |  |  |  l__   |     |  |  |  |  |  |  |  |  |  |  ||\n       |  |  |  |  |  |  |  |  |  |  |  |  |  |  |  l  |  |  |  l  |  |:\n       l__|  l_____l__|  l__l__   l__|  l__|__|  l__   l__|  l__   |  ||\n          ÷2F÷        `--''     `--''  `--''     `--''  `--''  `--''  `--''\n\n    (tRSi/X-iNNOVATiON) WHQ & bETA sITE · aRT-cORE! gHQ · eTHIC dIST sITE\n\n                              __ _____ _____\n     A4ooo/o4o aT 4oMHZ      (__)     \_    |\n                             | \_  |  _/ l__|          sYSTEM-cHIEFS:\n     14mB rAM/66o mB HD      |  |  |  |  |__\n                             |  |  |  |  l  |  _  SieGeL/tRSi & aRGON/dTL\n      USR v.fAST 28.8k       l__l__|  l__   | (_)\n                                   `--''  `--''\n\n          ! sUPPORTING pD and sHAREWARE oNLY oN aMIGA aND IBM-PC !\n\n                        cALL +49(0)30 694 84 70\n                             +49(0)30 --sOON!--\n...or try here :\n\n     _______  ______ ______  ______  __      __  __ ________ _____ ________\n     \.  _ ~\|     ~|\.   ~\|     ~||.~|    |  || ~|\.     ~\\   ~\\.     ~\\n     |\\ ___/|  __ .||\\ __/|  __ .||| |    |  || .| \\ ____/|\  _/ \\ ____/\n     | \/\   |  __ |||.\/  ||  __ |||| |___ |_    || _\/_ .\ |.\/|  _\/_ .\\n     ||   \  |  || :||| |  ||  || :||: \  .\/ \__ ||/      \\||  | /      \\\n     |:___/  |__||_:||:_|__||__||__||:__\ //\_____:|\_______/|:__| \_______/\n      .            .  .              .   \/       .           .     -FuZzY-\n                                     .            .\n                   .  .                                       .\n     .-->  tRSi/X-iNNOVATiON GHQ --- Syndicate WHQ --- ULa Dist. Side  <---.\n     ·-> AMIEXPRESS V4.8/AMIGA 3000/630 MB HD/630 MB CD-ROM/24 H ONLINE  <-·\n     |                                                                     |\n     |                U.S.Robotics DUAL STANDARD V.34 Rulez                |\n     |                                                                     |\n     |      Sysop    : Spy/tRSi                                            |\n     |      Cosysops : Arthur Dent, PHANTOM, CINDARELLA/SR&ILa,            |\n     |                 Byteandi/tRSi, JTC, CAT, big-rat                    |\n     |      Nosysop  : Ljopo/ILa                                           |\n     |                                                                     |\n     |      PORT             NUMBER   MODEM   SPEED      NODETYPE          |\n     ·---+-------------------------------------------------------------+---·\n       D | NODE 1: +49(0)30 721 6071 USR V.34 28800 RINGDOWN NODE 1-3! | C\n       I | NODE 2: +49(0)30 721 6072 USR V.34 28800 DIRECT LINE ACCESS | A\n       A | NODE 3: +49(0)30 721 6073 USR V.34 28800 DIRECT LINE ACCESS | L\n       L | NODE 4: +49(0)30 722 6065 USR V.34 28800 DIRECT LINE ACCESS | L\n         | NODE 5: +49(0)30 721 9940 USR V.34 28800 DIRECT LINE ACCESS |\n     ·---+-------------------------------------------------------------+---·\n     |                                                                     |\n     |        G . I . V . E       I . T       A       R . I . N . G        |\n     |                                                                     |\n     ·--> SUPPORTING !PD-SOFTWARE ONLY! FOR: AMIGA, ATARI, IBM-PC & MAC <--·\n','\n',char(10)),NULL,'auto-added',5773,2,0,NULL,NULL,'bbs_view','scan',1780048423);
INSERT INTO door_catalog VALUES('bbsad','BBSAD.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BBSAD.LHA',NULL,'XIM','bbsADD.AiM',NULL,NULL,NULL,'nasty BBS ADS in your mail. Lets em all put them in one place so anyone can view them A realy great Door....',replace('A Door For /X save users putting all those \nnasty BBS ADS in your mail. Lets em all put \nthem in one place so anyone can view them\nA realy great Door....\n','\n',char(10)),'BBSAdd.Guide',replace('@database BBS Advertiser 1.1 Final\n\nCopyright (C) 1993 by [-Dr.Dre!/tRSi], Germany\nAll Rights Reserved\n\n@Remark $VER: Version v1.1 (Monday 17-Jan-94 13:32:57)\nRemark AmigaGuide DataBase for BBS Advertiser 1.1final by [-Dr.Dre!/tRSi]\n\n@node MAIN "BBS Advertiser 1.1 (Monday 17-Jan-94 13:32:57) AmigaGuide Document for /X"\n             ____                        ___                     :\n           ._\  /________________________\_/ ____________________¦_ _\n           |  \/   __ _ _               _\_ /_      _/           |\n           |    _ _\         T.R.S.I      // \_    / \_ _     \\ |\n           | ____________________________//____________________\ |\n       ____| \        ___________      /_____        /______  /  |____\n      /\___\  \      /    .|   _/    _/\    /_______/       \/|  /___/\\n      \/___/   \  __/     ¦|   \      \_\_____     \_        ¦|  \___\/\n           |    \/ /      :|    \      /     /      /        :|  |\n           | \    /________|  _  \    /____________/|_________| _|\n           | \\         _ _  \_   \  /_ \\  _ __ _          _ _/ |\n           | \\\           \_/     \/ \_//       /__ _         \ |\n        _ _|________________\__________/ \__________________ /\ _|H2o!\n           ¦                           /\                   /__\\n     is proud to present: BBS Advertiser 1.1 (Monday 17-Jan-94 13:32:57)\n\n                         @{"     Introduction      " Link no1}\n                         @{"     Requirements      " Link no2}\n                         @{"     Installation      " Link no3}\n                         @{"      Menu Help!       " Link no4}\n                         @{"       Creditz!        " Link no5}\n                         @{"      Greetings!       " Link no6}\n                         @{"     tRSI Boards!      " Link no7}\n@endnode\n@node no1 " Introduction"\n\nThis Tool is usefull for all Sysop who hate all the fukkin BBSAdds in the\nMessagebase...\nBBS Advertise 1.1 allows a User to Add his BBS Add into the Door, and he\nneed to do this only one Time...\nEvery User can jump into the door and pick out the BBSAdd he want see...\nIf he like it or he need it then he can d/l it or he can d/l all Adds at\none Time....\n\nhave phun with the door...\n                       [-Dr.Dre!/tRSi]\n\n@endnode\n@node no2 " Requirements"\n\nYou need an Amiga 500/1000/2000/3000 (The Sysops with an A4ooo or A12oo \nshould call my BBS to receive an uncompiled Version)\nKickstart 2.0 or higher\nAmi Express 2.xx - 3.xx (Registered)\nAn running RPStart\nrexxplsextnd.library\nRexxplslib.library\nrexxsyslib.library\nrexxsupport.library\nin your Libs: but they are included\n\nThats all...\n\n@endnode\n@node no3 " Installation"\n\nFirst copy all Libs: (If you dont have them allready) into your libs: Dir\nCopy the Badd.info to your BBS:Commands/bbscmd/\nand make shure you run rpstart in your Startup-Sequence.\nThen create a Directory called BBSADD in your Doors...\nThere you copy all Files and Dirs from the Archive Directory \nBBS/Doors/BBSAdd/\n\nThere must be in all this Files and Dirs...\n\nadds       (dir)\nTemp       (Dir)\nadd.init   (ascii file)\nBBSAdd.AiM (The Door self)\nBBSAdd.Cfg (The Config File)\n\nAfter this jump into the BBSAdd.Cfg File and change the Levels for your BBS.\n------------------cut here------------------\n50\n100\n253\n------------------cut here------------------\nLine.1=from this Level on a User can view the Adds\nLine.2=from this Level on a User can Add an own Add to the Door\nLine.3=from this Level on a User can remove Adds from the Door\n\nThis is all what you have to do...\n\n@endnode\n@Node no4 " Menu Help"\n\n             ._______________________________________________.\n             |                                               |\n             |        1) .......View BBS Advert......        |\n             |        2) ...Download BBS Advert......        |\n          --+O---     3) ......Enter BBS Advert......     --+O---\n             |        4) .....Remove BBS Advert......        |\n             |        5) ..........Show Creditz......        |\n             |        Q) ...............Exiting......        |\n             !_______________________________________________!\n                                  __ :\n                                 /\_\: \n                                 \/_/:\n                                     ·\n\n                  This is the Main menu from the Door...\n\n1. View BBS Adverts\n2. Download Advert (or let the Door pack all Adds to one Lha File)\n3. Enter BBS Advert, here the User will be asked, if he want enter the\n   Advert in the MsgBase Editor or he want U/L The Advert, work from the\n   Local Node too...\n4. Here it is possible for Users with an specified Access level (CfgFile)\n   to remove ADverts from the Door...\n5. View Door Creditz and some Greetings...\nQ. Exit the Door\n@endnode\n@Node no5 " The Creditz!"\n\n              Copyright (C) 1994 by [-Dr.Dre!/tRSi], Germany\n                            All Rights Reserved\n\n             The AmigaGuide DataBase written by [-Dr.Dre!/tRSi]\n\n    For more good Doors call my BBS under 49 (0) 2131 275756 & 275634\n               · [ · MARLEYS COFFEE SHOP - tRSi GHQ · ] ·\n\n      Thanx to Skin! for using some of your great Style in my Doors!\n\n@endnode\n@Node no6 " Greetings"\n\n                   The Greets are going to this Dudes...\n\n ByteAndi/X-Design, Spy/X-Design, Remo/X-Design, X-Treme/TRSI, Saito/TRSI\n    Gandalf/Faith, Silver/Faith, McLoud/TRSI, Irata/TRSI, Triton/Fth\n Skylark/LSD, Nick, Metoner/TRSI, J.Walker/TRSI, Crazy/TRSI, Valshare/TRSI\n    Vicous/LSD, Richi/Flt, Steve/D&R, Amicom, -rS!, Empire/Mst, Mr.VAiN\n            APOLLO, BJoerN/Pdy, Jive/TRSi, Scope/Trsi, SkiN!\n          and simply all tRSi Member an other Doodes I forgot...\n\n@endnode\n@Node no7 " tRSi Boards Worldwide"\n\n                 To Contact me Call any of this Boards...\n           -==================================================-\n\n   Cauldron.......................German  hq............++49 Pure Elite\n   Marleys Coffee Shop............German  hq............++49 Pure Elite\n   Boondocks......................Europe  hq............+31-548-040-653\n   Final Impact...................Swedish hq............++46-54-113-486\n   Flying Spirits.................Swiss   hq............+41-217-282-524\n   Savage Amusement...............Austia  hq............+43-767-227-743\n   Zenlandia......................Finnish hq............+358-088-82-144\n\n\n           -==================================================-\n@endnode\n','\n',char(10)),NULL,'auto-added',31203,1,0,NULL,NULL,'bbsad','scan',1780048423);
INSERT INTO door_catalog VALUES('bbsg125','BBSG125.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BBSG125.LHA','BBSGuard','XIM','BBSGuard',NULL,NULL,NULL,NULL,replace('BBSGUARD 1.25 -> ANTI-LOCKUP UTIL\n','\n',char(10)),'BBSGuardv1.25.readme',replace('This program is NOT public domain. This program is copyright.\nYou may distribute the program freely so long as there is no\ncharges for the program. Anything above the cost of the media\nwhich it is copied onto or the normal user fee of a bulletin\nboard system is not allowed. This documentation must accompany\nthe executable program. No commercial use of this program is\nallowed without prior written agreement from the author (me).\n\n                                           May 1992 © Darrell Grainger\n\n                                   BBSGuard\n                                   --------\n\nA friend needed a program what would monitor the carrier detect line. If\nthere was a carrier detect this program would then monitor the line and\ntime how long the carrier was detected for. By default the program would\nreboot the computer after 11600 seconds (3 hours).\n\n The following options are available:\n\n         -a       Make the window active when run.\n         -b##     Delay between checking for new ring count. Default 10.\n         -c##     Number of seconds to abort reboot. default = 30 seconds.\n         -d##     Delay before program activates.\n         -g       Enable Guru Meditation trapping.\n         -n       No requesters. Cancels all requesters.\n         -p##     Delay between the ring pulse. Default is 75.\n                  This stands for 75/50 or 1.5 seconds.\n         -r##     Number of unanswered rings before resetting computer.\n                  Default = 5 rings.\n         -s##     Set the number of seconds of carrier detect before\n                  resetting the computer. Default = 11600 seconds.\n         -t##     Delay in seconds between checks for carrier detect.\n                  Default = 10 seconds.\n         -x##     X position of the window. Default = 0.\n         -y##     Y position of the window. Default = 0.\n\n Note: the RI line of the serial port is connected to the SEL line\n of the parallel port. Selecting and deselecting the printer will seem like\n the phone is ringing to this program.\n\n Note: to conserve CPU time this program goes to sleep for 10 seconds\n between checks. So for 10 seconds it will seem as if the program has\n locked up. Always wait 10 seconds for something to happen.\n\n                                            1992 © Darrell Grainger\n\nI have done a lot of testing with the various options and here is what I\nfound:\n \n         -b       There is ATLEAST 8 seconds between callers. This is a\n                  restriction of Bell''s phone system. Some phone exchanges\n                  take as long as 9 seconds. To be safe I set the default\n                  to 10 seconds. This should work fine.\n\n         -d       Some BBS programs take a while before they can answer the\n                  phone. Run BBSGuard with no -d option. Time how long\n                  between when BBSGuard appears and the modem initializes.\n                  Whatever the seconds this take is what the -d option\n                  should be set to.\n\n         -p       I have found that some exchanges ring slightly longer or\n                  slightly shorter. This messes me up just a little. If\n                  you can, run BBSGuard and have someone call you. BBSGuard\n                  will display when it thinks the phone is ringing. If\n                  BBSGuard misses some of the rings then set -p to\n                  something lower then 75.\n\n         -r       Most BBS programs answer on the first or second ring.\n                  Most terminal programs, when autodialing, will only let\n                  the phone ring 6 or 7 times before hanging up and trying\n                  a new number. The default of 5 seemed sensible to me BUT\n                  be warned that sometime the BBS will not immediately\n                  answer the phone after a user has logged off. One BBS\n                  was famous for taking as long as 7 rings before answering\n                  if it was busy processing EchoMail.\n                  If you are using an Amiga 1000, it has no RI line so you\n                  should set this to -r0. If you want to add RI to your\n                  Amiga 1000 please contact me and I will send you tested\n                  instructions on how to add RI just like a 500/2000/3000.\n\n         -s       This value MUST be in seconds. Sorry but I was lazy.\n                  The default of 11600 is 3 hours. If you have anyone with\n                  access longer then 3 hours you must change this. If\n                  everyone''s access is less then you can lower the default.\n                  Remember that this must be set for the user with the \n                  highest access time plus a few seconds to be safe.\n\n         -t       Rather then having the program CONSTANTLY checking the\n                  Carrier Detect line you can make my program go to sleep.\n                  I found that 10 seconds was long enough that it does not\n                  slow the CPU down or affect the BBS but you can make it\n                  long if you want. NOTE: if you change this it affects the\n                  time you have to wait if you try and quit the program.\n\n The rest of the commands are user definable and should need no further\n explanations.\n\n version 1.25 improvements\n -------------------------\n - If a system Requester occurs the system will sometimes not reboot on the\n   failure to answer (ring detect). The -n option will disable all of the\n   requesters so even the System Requester will CANCEL (this causes a Guru\n   Meditation so the -g option is recommended with this).\n\n version 1.24 improvements\n -------------------------\n - added routines to disable Guru Meditations. If a Guru Meditation occurs\n   and the -g option was enabled, the system will automatically reboot\n   rather then sit at the flashing red Guru Meditation.\n\n version 1.23 improvements\n -------------------------\n - added a self reboot feature. The program will no longer generates\n   a requester that causes "Reboot1.1" to reboot the computer. This\n   makes BBSGuard standalone.\n\n - added the -C option so you can have an abort before the thing\n   reboots. When the program is about to reboot the title to the window\n   will change to the "Double click here to abort". -C will determine\n   how long you have to abort the reboot. Default is 30 seconds.\n   During the abort/reboot period all screens will flash until you abort\n   or the computer reboots. Pressing the left mouse button from ANYWHERE\n   will abort the reboot. During ring detect the abort simply sets the\n   ring count back to zero. During the carrier detect the abort resets the\n   counter of carrier detect seconds back to -S## seconds left.\n\n version 1.22 improvements\n -------------------------\n - made the check for time between rings programmable. If the delay\n   between rings is too long we should assume this is a new caller and\n   reset the count of how many rings. Default = 10 seconds. If the time\n   from start of last ring to start of next ring is greater then 10\n   seconds the ring count will reset. This is the -B option.\n\n version 1.21 improvements\n -------------------------\n - found there was a timing problem during the ring detect on some phone\n   lines so I made the delay time between ring checks programmable.\n   This is option P. Default = 75 (75/50 = 1.5 seconds). This default is\n   new and should work on all phone lines. Some phone lines will allow\n   you to increase the delay. Try setting the delay to 100, run the\n   program, make the phone ring and see if it misses any of the rings.\n - While I was at it I made the delay between checking for carrier\n   programmable as well. The bigger this number the less slow down for\n   the user online BUT the long the delay should you wish to quit the\n   program.\n\n version 1.2 improvements\n ------------------------\n - added a delay option so they program can be made to wait for the BBS\n   to power up and initialize.\n - added the -r0 option so the program can disable ring detect. No use\n   in wasting CPU time checking for a ring that will not be there.\n - reset the ring counter if there is a 10 second pause between rings.\n   I found that the phone rings every 7 to 8 seconds so if there is a\n   ten second pause it must be a new caller. This means that ONE caller\n   must let the phone ring -R times (default = 5). Don''t set that too\n   high or this option is pointless.\n\n version 1.1 improvements\n ------------------------\n - optimized code to waste less time when checking for a ring. Program\n   now goes to sleep for 2 seconds every loop of the ring detect routine.\n   A ringing phone lasts for just over 2 seconds. If the delay is longer\n   then 2 seconds there is a good chance the program will miss some rings.\n   With a 2 second delay I have only noted it missing the first ring and\n   then only when the first ring is a partial ring (less then 2 seconds).\n\n version 1.01 improvements\n -------------------------\n - added a check for the phone ringing and the BBS not answering. If the\n   phone rings unanswered for too long then obviously the BBS has crashed.\n\n\nCurrent I can be reached at:\n\[email removed]     OR\n\ntelepro![email removed]     OR\n\nChaotic Knights BBS (416) 272-1860 - messages to SYSOP are directed to\nmyself and the actual Sysop.\n\nOR\n\nDarrell A. Grainger\n48 Wheeler Ave.\nToronto, ON\nM4L 3V2  Canada\n\n\nIf you have any suggestions or find any bugs please drop me a line. I''m\nalso interested in finding out where this program makes it to, so send\nme a postcard or something if you could.\n\n Future plans\n ------------\n - support for the Commodore A2232 card (have to get programming info\n   on the card).\n','\n',char(10)),NULL,'auto-added',19360,3,0,NULL,NULL,'bbsg125','scan',1780048423);
INSERT INTO door_catalog VALUES('bbsg203','BBSG203.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BBSG203.LHA','BBSGuard','XIM','BBSGuard','2.03.',NULL,NULL,'written for any sysop. Eliminates requester s, resets machine if software failure occoured, bypassing the GURU/Software failur',replace('BBSGUARD v2.03. One of the best utils\nwritten for any sysop. Eliminates requester\ns, resets machine if software failure\noccoured, bypassing the GURU/Software failur\nscreen. Ring counter, carrier detect, force\nhardrive to valiadate....!!\nA MUST HAVE!!','\n',char(10)),'BBSGuard.doc',replace('This program is NOT public domain. This program is copyright.\nYou may distribute the program freely so long as there is no\ncharges for the program. Anything above the cost of the media\nwhich it is copied onto or the normal user fee of a bulletin\nboard system is not allowed. This documentation must accompany\nthe executable program. No commercial use of this program is\nallowed without prior written agreement from the author (me).\n(You can supply it with your BBS software. Just don''t use it\nas a selling point and make sure this file is included with\nthe program.)\n                                     October 1992 © Darrell Grainger\n\n\nBBSGuard v2.03 © Oct 1992 - Darrell Grainger\n-------------------------------------------\n\nThis program was originally written in SAS/C but as a way of learning\n68000 assembler, I have re-written the program in assembler.\n\nUsage: BBSGuard [-b##][-c##][-d##][-g][-l][-n][-r##][-s##][-t##][-v]\n\nNote: -  don''t put a space between the option and any numbers.\n         for example: ''-b10'' is correct. ''-b 10'' is wrong.\n      -  make sure there is a space between the options. for\n         example: ''BBSGuard -b10-l'' is wrong. ''BBSGuard -b10 -l''\n         is correct.\n\nDefault: BBSGuard -b10 -c30 -d0 -r5 -s10800 -t10\n\n--------------------------------------------------------------------\n\nIf you like and use this program and would like to receive future\nupdates, please send a donation to:\n\n                  D.A.Grainger\n                  48 Wheeler Ave.\n                  Toronto, ON\n                  M4L 3V2\n                  Canada\n\nA donation of $5 cheque or money order would be appropriate.\n\nSuggestions for the program can also be sent to the same address or\nlog onto Chaotic Knights BBS at (416) 272-1860.\n\n--------------------------------------------------------------------\n\nOption   What it does\n------   ------------\n\n-b       When the phone rings I keep a count of the number of rings.\n         If I just kept track of the rings it would add up the rings\n         of the first caller, and the second, and third, etc. until\n         the count reached the maximum and rebooted the computer. So\n         I had to have some way of knowing when the first caller\n         stopped then I could reset the ring count. The time between\n         rings when someone is calling is usually five seconds. This\n         may vary from area to area. If the time is greater than five\n         seconds, we know that the first person quit ringing\n         (hopefully because the BBS answered the phone). If the time\n         is greater than ten seconds then we can be positive that the\n         caller has stopped ringing the phone. The default for -b is\n         ten. If you find the time between when a ring stops and the\n         next one starts, in your area, is greater then ten (or close\n         to it) then you might want to increase the -b option.\n         Default: -b10\n\n-c       When the phone rings too many times or a carrier is present\n         too long then I assume the BBS has crashed and attempt to\n         reboot the computer. Before I actually reboot I will flash\n         all screens on and off. The -c option indicates how long,\n         in seconds, that I will flash the screen before rebooting.\n         Default: -c30\n\n-d       You may want to run BBSGuard right away (if you are using\n         the -v, -g and -n options you might want to run BBSGuard at\n         the start of your s:Startup-Sequence). If the BBS takes a\n         while to get ready and answer the phone you DON''T want\n         BBSGuard monitoring the phone for unanswered rings. This\n         option will delay BBSGuard, in seconds, from checking the\n         ringing or carrier. Default: -d0\n         \n-g       If an Guru Meditation occurs the computer usually sits at\n         the flashing Alert message. Using the -g option will stop\n         the Alert from coming up. Instead the computer will go to\n         the warning stage. This is when the screen flashes. At this\n         time, you have -c seconds to abort the reboot. If you press\n         the left mouse button the system will suspend the task. If\n         you do nothing the computer will reboot. Note: I disable\n         all Alerts so any program that uses Alert instead of\n         Requesters will cause the system to reboot. Alerts are only\n         supposed to be used if the system is really messed up or\n         low on memory. Programmers that use Alerts as Requesters\n         are lazy.\n\n-l       Since you don''t see BBSGuard after it is written you might\n         want to know when the phone is ringing (and that BBSGuard\n         is counting it). The -l option will cause BBSGuard to flash\n         the LED as the phone rings.\n\n-n       If a requester comes up the system might sit at a stand\n         still. If you want to automatically CANCEL all requesters\n         then set the -n option. If a System Requester comes up this\n         will choose CANCEL and it will try to go for the Guru\n         Meditation so the -g option is recommended when you use the\n         -n option.\n\n-r       The option which sets the number of rings that will reboot\n         the computer. There is a warning of -c seconds before the\n         reboot. A setting of -r0 will disable check for ringing.\n         Default: -r5\n\n-s       The option which sets the number of seconds of carrier\n         detect. If the carrier lasts WAY too long then it could be\n         possible that the modem crashed or that someone got stuck\n         in a ''door'' of the BBS. Remember to set this higher then\n         the maximum user time. If your CoSysop has unlimited time\n         then you might want to disable this with a setting of -s0.\n         Default: -s10800 (3 hours)\n\n-t       This sets the time a requesters will remain up before the\n         -n option automatically cancels the requester. This gives\n         you a chance to choose something other then cancel in case\n         you are there and don''t want it to cancel.\n\n-v       If this option is set then BBSGuard will check all mounted\n         volumes. If any are validating then BBSGuard will pause\n         until the volume has finished validating. If you want to\n         abort this part then hold the left mouse button down.\n\nNotes: - You can quit BBSGuard by running it a second time. The\n         screen will flash once when BBSGuard quits. Be sure the\n         screen flashes. If the phone is ringing BBSGuard might\n         not quit just keep trying.\n         \n       - If the maximum carrier detect time or the maximum number of\n         rings is reached BBSGuard will go into the warning phase.\n         If -c is set to zero then the computer will reboot\n         immediately otherwise all screens will flash as the timer\n         counts down.\n         \n       - the A1000 does not have the RI pin connected. On the A1000\n         this status bit is for the printer SELect only. On the A500\n         A2000/A3000 the status bit is used by printer SELect and\n         modem Ring Indicator. Adding the circuitry to connect the\n         serial port RI pin to the CIA so we can read RI status is\n         fairly simply. Write me if you want the instructions to\n         make your A1000 work like the A2000 serial port.\n         \n       - the RI line of the serial port is connected to the SEL line\n         of the parallel port. Selecting and deselecting the printer\n         will seem like the phone is ringing to this program.\n\n       - If you are using ParNet then the handshaking of ParNet uses\n         the SEL line. This means that BBSGuard will see a change in\n         the RI line and think the phone is ringing. As it checks to\n         see if the phone is actually ringing it will eatup CPU time\n         and slow everything down. For this reason, if you are using\n         ParNet and BBSGuard you should use the -r0 option and not\n         bother checking for ringing.\n\n---------------------------------------------------------------------\nHISTORY\n\nA friend needed a program what would monitor the carrier detect\nline. If there was a carrier detect this program would then monitor\nthe line and time how long the carrier was detected for. By default\nthe program would reboot the computer after 11600 seconds (3 hours).\n\n version 2.03 improvements\n -------------------------\n - fixed a bug with AmigaDOS 1.3 and the -n option.\n \n version 2.02 improvements\n -------------------------\n - The -t option was added so you have a chance to choose something\n   other than CANCEL when a requester comes up.\n\n version 2.01 improvements\n -------------------------\n - The -n option now works with AmigaDOS 2.0. I was originally\n   programming in AmigaDOS 1.3 and failed to implement 2.0 cancel\n   requesters.\n \n - There is no longer a window that opens on the Workbench. To see\n   if the phone is ringing I have added the -l option.\n \n - I use the Wait() functions and an interrupt handler to make the\n   program go to sleep until something happens, i.e. ring, carrier\n   detect, guru, etc.\n\n - The -v option is new to version 2.01.\n \n - The program opens no window. Takes less memory and can be quit\n   from remote.\n \n - No need for -a, -p, or -t options. No long have a window to\n   activate (-a). Have improved the timing routines is no longer\n   need -p. Have learned how to make the program go into ''Waiting''\n   so delays between carrier checks are not necessary.\n\n version 1.25 improvements\n -------------------------\n - If a system Requester occurs the system will sometimes not reboot\n   on the failure to answer (ring detect). The -n option will\n   disable all of the requesters so even the System Requester will\n   CANCEL (this causes a Guru Meditation so the -g option is\n   recommended with this).\n\n version 1.24 improvements\n -------------------------\n - added routines to disable Guru Meditations. If a Guru Meditation\n   occurs and the -g option was enabled, the system will\n   automatically reboot rather then sit at the flashing red Guru\n   Meditation.\n\n version 1.23 improvements\n -------------------------\n - added a self reboot feature. The program will no longer generates\n   a requester that causes "Reboot1.1" to reboot the computer. This\n   makes BBSGuard standalone.\n\n - added the -C option so you can have an abort before the thing\n   reboots. When the program is about to reboot the title to the\n   window will change to the "Double click here to abort". -C will\n   determine how long you have to abort the reboot. Default is 30\n   seconds. During the abort/reboot period all screens will flash\n   until you abort or the computer reboots. Pressing the left mouse\n   button from ANYWHERE will abort the reboot. During ring detect\n   the abort simply sets the ring count back to zero. During the\n   carrier detect the abort resets the counter of carrier detect\n   seconds back to -S## seconds left.\n\n version 1.22 improvements\n -------------------------\n - made the check for time between rings programmable. If the delay\n   between rings is too long we should assume this is a new caller\n   and reset the count of how many rings. Default = 10 seconds. If\n   the time from start of last ring to start of next ring is greater\n   then 10 seconds the ring count will reset. This is the -B option.\n\n version 1.21 improvements\n -------------------------\n - found there was a timing problem during the ring detect on some\n   phone lines so I made the delay time between ring checks\n   programmable. This is option P. Default = 75 (75/50 = 1.5\n   seconds). This default is new and should work on all phone lines.\n   Some phone lines will allow you to increase the delay. Try setting\n   the delay to 100, run the program, make the phone ring and see if\n   it misses any of the rings.\n - While I was at it I made the delay between checking for carrier\n   programmable as well. The bigger this number the less slow down\n   for the user online BUT the long the delay should you wish to\n   quit the program.\n\n version 1.2 improvements\n ------------------------\n - added a delay option so they program can be made to wait for the\n   BBS to power up and initialize.\n - added the -r0 option so the program can disable ring detect. No\n   use in wasting CPU time checking for a ring that will not be\n   there.\n - reset the ring counter if there is a 10 second pause between\n   rings. I found that the phone rings every 7 to 8 seconds so if\n   there is a ten second pause it must be a new caller. This means\n   that ONE caller must let the phone ring -R times (default = 5).\n   Don''t set that too high or this option is pointless.\n\n version 1.1 improvements\n ------------------------\n - optimized code to waste less time when checking for a ring.\n   Program now goes to sleep for 2 seconds every loop of the ring\n   detect routine. A ringing phone lasts for just over 2 seconds. If\n   the delay is longer then 2 seconds there is a good chance the\n   program will miss some rings. With a 2 second delay I have only\n   noted it missing the first ring and then only when the first ring\n   is a partial ring (less then 2 seconds).\n\n version 1.01 improvements\n -------------------------\n - added a check for the phone ringing and the BBS not answering. If\n   the phone rings unanswered for too long then obviously the BBS\n   has crashed.\n','\n',char(10)),NULL,'auto-added',11803,2,0,NULL,NULL,'bbsg203','scan',1780048423);
INSERT INTO door_catalog VALUES('bbsguard','BBSGUARD.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BBSGUARD.LHA','findtask','XIM','findtask','2.0.','many.',NULL,'ultimate watchdog.  If the phone rings more than 5 times, the system will automatically be reset.  ALL requestors that pop up, are',replace('BBSGuard v2.0.  BBS software defender! The\nultimate watchdog.  If the phone rings more\nthan 5 times, the system will automatically\nbe reset.  ALL requestors that pop up, are\nautomatically cancelled, the flashing red\nGURU or software failure screen is by-passed\n... AND MORE!   A MUST!  Requested by many.\n','\n',char(10)),'BBSGuard.doc',replace('This program is NOT public domain. This program is copyright.\nYou may distribute the program freely so long as there is no\ncharges for the program. Anything above the cost of the media\nwhich it is copied onto or the normal user fee of a bulletin\nboard system is not allowed. This documentation must accompany\nthe executable program. No commercial use of this program is\nallowed without prior written agreement from the author (me).\n(You can supply it with your BBS software. Just don''t use it\nas a selling point and make sure this file is included with\nthe program.)\n                                      October 1992 © Darrell Grainger\n\n\nBBSGuard v2.01 © Oct 1992 - Darrell Grainger\n-------------------------------------------\n\nThis program was originally written in SAS/C but as a way of learning 68000\nassembler, I have re-written the program in assembler.\n\nUsage: BBSGuard [-b##][-c##][-d##][-g][-l][-n][-r##][-s##][-v]\n\nNote: don''t put a space between the option and any numbers.\n      for example: ''-b10'' is correct. ''-b 10'' is wrong.\n\nOption   What it does\n------   ------------\n\n-b       When the phone rings I keep a count of the number of rings. If I\n         just kept track of the rings it would add up the rings of the first\n         caller, and the second, and third, etc. until the count reached the\n         maximum and rebooted the computer. So I had to have some way of\n         knowing when the first caller stopped then I could reset the ring\n         count. The time between rings when someone is calling is usually\n         five seconds. This may vary from area to area. If the time is\n         greater than five seconds, we know that the first person quit\n         ringing (hopefully because the BBS answered the phone). If the\n         time is greater than ten seconds then we can be positive that the\n         caller has stopped ringing the phone. The default for -b is ten.\n         If you find the time between when a ring stops and the next one\n         starts, in your area, is greater then ten (or close to it) then\n         you might want to increase the -b option. Default: -b10\n\n-c       When the phone rings too many times or a carrier is present too\n         long then I assume the BBS has crashed and attempt to reboot the\n         computer. Before I actually reboot I will flash all screens on and\n         off. The -c option indicates how long, in seconds, that I will\n         flash the screen before rebooting. Default: -c30\n\n-d       You may want to run BBSGuard right away (if you are using the -v,\n         -g and -n options you might want to run BBSGuard at the start of\n         your s:Startup-Sequence). If the BBS takes a while to get ready\n         and answer the phone you DON''T want BBSGuard monitoring the phone\n         for unanswered rings. This option will delay BBSGuard, in seconds,\n         from checking the ringing or carrier. Default: -d0\n         \n-g       If an Guru Meditation occurs the computer usually sits at the \n         flashing Alert message. Using the -g option will stop the Alert\n         from coming up. Instead the computer will go to the warning stage.\n         This is when the screen flashes. At this time, you have -c seconds\n         to abort the reboot. If you press the left mouse button the system\n         will suspend the task. If you do nothing the computer will reboot.\n         Note: I disable all Alerts so any program that uses Alert instead\n         of Requesters will cause the system to reboot. Alerts are only\n         supposed to be used if the system is really messed up or low on\n         message. Programmers that use Alerts as Requesters are lazy.\n\n-l       Since you don''t see BBSGuard after it is written you might want to\n         know when the phone is ringing (and that BBSGuard is counting it).\n         The -l option will cause BBSGuard to flash the LED as the phone\n         rings.\n\n-n       If a requester comes up the system might sit at a stand still. If\n         you want to automatically CANCEL all requesters then set the -n\n         option. If a System Requester comes up this will choose CANCEL and\n         it will try to go for the Guru Meditation so the -g option is\n         recommended when you use the -n option.\n\n-r       The option which sets the number of rings that will reboot the\n         computer. There is a warning of -c seconds before the reboot.\n         A setting of -r0 will disable check for ringing. Default: -r5\n\n-s       The option which sets the number of seconds of carrier detect. If\n         the carrier lasts WAY too long then it could be possible that the\n         modem crashed or that someone got stuck in a ''door'' of the BBS.\n         Remember to set this higher then the maximum user time. If your\n         CoSysop has unlimited time then you might want to disable this\n         with a setting of -s0. Default: -s10800 (3 hours)\n\n-v       If this option is set then BBSGuard will check all mounted\n         volumes. If any are validating then BBSGuard will pause until\n         the volume has finished validating. If you want to abort this\n         part then hold the left mouse button down.\n\nNotes: - You can quit BBSGuard by running it a second time. The screen\n         will flash once when BBSGuard quits. Be sure the screen flashes.\n         If the phone is ringing BBSGuard might not quit just keep trying.\n         \n       - If the maximum carrier detect time or the maximum number of rings\n         is reached BBSGuard will go into the warning phase. If -c is set\n         to zero then the computer will reboot immediately otherwise alls\n         screens will flash as the timer counts down.\n         \n       - the A1000 does not have the RI pin connected. On the A1000 this\n         status bit is for the printer SELect only. On the A500/A2000/A3000\n         the status bit is used by printer SELect and modem Ring Indicator.\n         Adding the circuitry to connect the serial port RI pin to the CIA\n         so we can read RI status is fairly simply. Write me if you want\n         the instructions to make your A1000 work like the A2000 serial port.\n         \n       - the RI line of the serial port is connected to the SEL line of the\n         parallel port. Selecting and deselecting the printer will seem like\n         the phone is ringing to this program.\n\nImprovements since v1.26\n------------------------\n\nThe -n option now works with AmigaDOS 2.0. I was originally programming in\nAmigaDOS 1.3 and failed to implement 2.0 cancel requesters.\n\nThere is no longer a window that opens on the Workbench. To see if the phone\nis ringing I have added the -l option.\n\nI use the Wait() functions and an interrupt handler to make the program go\nto sleep until something happens, i.e. ring, carrier detect, guru, etc.\n\nThe -v option is new to version 2.0.\n\nThe program opens no window. Takes less memory and can be quit from remote.\nDLG sysops should like this.\n\nNo need for -a, -p, or -t options. No long have a window to activate (-a).\nHave improved the timing routines is no longer need -p. Have learned how\nto make the program go into ''Waiting'' so delays between carrier checks are\nnot necessary.\n\n-----------------------------------------------------------------------------\n\nIf you like and use this program and would like to receive future updates,\nplease send a donation to:\n\nD.A.Grainger\n48 Wheeler Ave.\nToronto, ON\nM4L 3V2\nCanada\n\nAny sort of donation in any currency would be appreciated as I''m trying to\nwork my way through university. ;)\n\nSuggestions for the program can also be sent to the same address.\n\n----------------------------------------------------------------------------\nHISTORY\n\nA friend needed a program what would monitor the carrier detect line. If\nthere was a carrier detect this program would then monitor the line and\ntime how long the carrier was detected for. By default the program would\nreboot the computer after 11600 seconds (3 hours).\n\n version 1.25 improvements\n -------------------------\n - If a system Requester occurs the system will sometimes not reboot on the\n   failure to answer (ring detect). The -n option will disable all of the\n   requesters so even the System Requester will CANCEL (this causes a Guru\n   Meditation so the -g option is recommended with this).\n\n version 1.24 improvements\n -------------------------\n - added routines to disable Guru Meditations. If a Guru Meditation occurs\n   and the -g option was enabled, the system will automatically reboot\n   rather then sit at the flashing red Guru Meditation.\n\n version 1.23 improvements\n -------------------------\n - added a self reboot feature. The program will no longer generates\n   a requester that causes "Reboot1.1" to reboot the computer. This\n   makes BBSGuard standalone.\n\n - added the -C option so you can have an abort before the thing\n   reboots. When the program is about to reboot the title to the window\n   will change to the "Double click here to abort". -C will determine\n   how long you have to abort the reboot. Default is 30 seconds.\n   During the abort/reboot period all screens will flash until you abort\n   or the computer reboots. Pressing the left mouse button from ANYWHERE\n   will abort the reboot. During ring detect the abort simply sets the\n   ring count back to zero. During the carrier detect the abort resets the\n   counter of carrier detect seconds back to -S## seconds left.\n\n version 1.22 improvements\n -------------------------\n - made the check for time between rings programmable. If the delay\n   between rings is too long we should assume this is a new caller and\n   reset the count of how many rings. Default = 10 seconds. If the time\n   from start of last ring to start of next ring is greater then 10\n   seconds the ring count will reset. This is the -B option.\n\n version 1.21 improvements\n -------------------------\n - found there was a timing problem during the ring detect on some phone\n   lines so I made the delay time between ring checks programmable.\n   This is option P. Default = 75 (75/50 = 1.5 seconds). This default is\n   new and should work on all phone lines. Some phone lines will allow\n   you to increase the delay. Try setting the delay to 100, run the\n   program, make the phone ring and see if it misses any of the rings.\n - While I was at it I made the delay between checking for carrier\n   programmable as well. The bigger this number the less slow down for\n   the user online BUT the long the delay should you wish to quit the\n   program.\n\n version 1.2 improvements\n ------------------------\n - added a delay option so they program can be made to wait for the BBS\n   to power up and initialize.\n - added the -r0 option so the program can disable ring detect. No use\n   in wasting CPU time checking for a ring that will not be there.\n - reset the ring counter if there is a 10 second pause between rings.\n   I found that the phone rings every 7 to 8 seconds so if there is a\n   ten second pause it must be a new caller. This means that ONE caller\n   must let the phone ring -R times (default = 5). Don''t set that too\n   high or this option is pointless.\n\n version 1.1 improvements\n ------------------------\n - optimized code to waste less time when checking for a ring. Program\n   now goes to sleep for 2 seconds every loop of the ring detect routine.\n   A ringing phone lasts for just over 2 seconds. If the delay is longer\n   then 2 seconds there is a good chance the program will miss some rings.\n   With a 2 second delay I have only noted it missing the first ring and\n   then only when the first ring is a partial ring (less then 2 seconds).\n\n version 1.01 improvements\n -------------------------\n - added a check for the phone ringing and the BBS not answering. If the\n   phone rings unanswered for too long then obviously the BBS has crashed.\n\n Future plans\n ------------\n - support for the Commodore A2232 and ASDG multi-serial cards.\n','\n',char(10)),NULL,'auto-added',6225,1,0,NULL,NULL,'bbsguard','scan',1780048423);
INSERT INTO door_catalog VALUES('bbsscan','BBSSCAN.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BBSSCAN.LHA','DELETE','XIM','DELETE',NULL,NULL,NULL,'=====\_____  ¬\/~   ¬\_/~    \_/~ ___/====== !:::::7~  /  _/   !   7   l___7  ___)::::::! !:::::!   \  ¬\_  .   !   7  ¬7     ¬7:::::!',replace('     _________  _____   _____   ______\n=====\_____  ¬\/~   ¬\_/~    \_/~ ___/======\n!:::::7~  /  _/   !   7   l___7  ___)::::::!\n!:::::!   \  ¬\_  .   !   7  ¬7     ¬7:::::!\n!:::::l___j\___/__¡___j_______j______j:::::!\n!:::::::::::::pReSenTs:::ToDay:::::::::::::!\n============================================\nBBSscan /X door 1.1r automatic BBS-add door!\n[THE]=--=] cS!-^-sAD-^-hJB-^-KLF! [=--=[PUB]\n','\n',char(10)),'BBSscan.doc',replace('BBSscan V1.1r (1:st release version) by Zwinx/Rage.\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nThis is a very easy-to-use-&-install /X door complete package, made in ARexx.\n\nWhy?\n~~~~\nI made this little door because I was tired of all guys who wanted to have\na eall message for their board. Now they can do this automatic, and I (or\nanyone else with access>=200) can just validate their adds and they will\nbecome public!\n\nHow does it work?\n~~~~~~~~~~~~~~~~~\nThis door uses a "conference simulation", wich means that you don''t have to\nset up a special boardadd conference or anything like that. The door has\nactually NOTHING to do with a normal conference, it just looks that way.\n\nInstallation.\n~~~~~~~~~~~~~\nThis door is made for /X3.x+ only. Just cd to DOORS: and extract the archive.\nIt should contain the following files:\n- - -\nBBSscan (dir)\n     MailStats (dir)\n     Msgbase (dir)                                \n          Headerfile\n     PlayPen (dir)                                \n     Msghold (dir)                                \n          Holderfile\n     BBSadd.rexx\n     BBSscan.rexx   \n     BBSvalidate.rexx\n     BBSScan.doc\nCommands (dir)\n     BBScmd (dir)\n          BA.info\n          BR.info\n          BV.info\nC (dir)\n     LS\n     DELETE\n- - -\nJust copy all the files to where they belong. NOTE! If you already have the\nfiles in C installed in your C: directory, don''t overwrite them! It might be\nan older version!\nNow edit your Logon.txt or bbs.txt or any other .txt file that is showed\nduring logon. It can look something like this:\n--------vv--cut--vv--------\n~\n                                                     _\n                                                    æØ\n      Æ#  _æææmw             _µÑp                  JØ´   aµµ_          _\n      Ø# ,ØP"¯"#b           ,Ø@´ __µµµµææÑr     ___Ø#ææ  Ø#°##_   _   7Ø\n     _Ø# ¶P    ¬ØL         ,ØF   Ø#°°"""¯¯_ ___ ¶@¶Ø°"¯ JØÞ dØ´  JØ#  ÆØ\n   µÆØØ#  _____ ØL  __µ_   ØP   JØL___   JØÑØ@##_ Ø#    JØMØ#´   ÆØ#  Ø#\n ,Æ#" Ø1,ØÑ@¶¶#WØ  æØ@^## Æ#    ÆØÑ@M¶   ÆØØ" `0# ØF    Ø#¶Ø¸   ,ØMØ  ØF\n ØF   ØFÆØ    ¬Ø# ÆØ"  IØ ØF    ØE______ Ø@"   Ø#JØÞ açJØÞ ¶#_  Æ# ØL Ø®ææÑÑ\nÍØ   JØ 0#_   JØÞ ØF   Ø#JØ    `@ÑÑÑ@¶¶"JØÞ    ØF¬#bµØFÆ#   ¶# æØØMØ# ¬""¯\n¬#æµµÆ#  ¶#w__ÆØ  ¶#waÆØÞ`#mw___µ,      ÆØ    JØ   °¶°        Æ#   JØÞ\n  "°°"    ¬°¶¶¶"   ¬¶¶Ø@   "@ÑÑ@°       ¶''     ¯                    ¯\n               __    Æ#\n               ¶Ø_µæØ#\n                °¶P"        - calling Elvis.\n\n       Node0: +46-31-7759390 16k8DS   Node1: +46-31-7759391 28k8VFast\n\n~CC_BR\n--------^^--cut--^^--------\n...and the new adds will be scanned for during logon.\n\nUsage from /X main prompt.\n~~~~~~~~~~~~~~~~~~~~~~~~~~\nBA      Upload a add (max 50 lines).\nBR {x}  Read boardadds, starting from message {x}. Default is {last scanned}.\nBV      Access 200+ only. Validate uploaded boardadds and post or terminate\n        them.\n\nVersions\n~~~~~~~~\nV1.0ß   [not released] This version made for my ß-testers only (thnx to\n        DEXter/AFL and Guardian).\nV1.1r   [released 941104] Final version, BV command added.\n\n/Zwinx @ dagcentral 9o21o -rage whq- +46-31-775-9390 +46-31-775-9391\n','\n',char(10)),NULL,'auto-added',26241,