INSERT INTO door_catalog VALUES('bfl_qnew','BFL-QNEW.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BFL-QNEW.LHA',NULL,'XIM','._____',NULL,'bAFFLE!','BFL','_________|____(_______/\_________________ .\_____   /_____    __   ._____/ _____   / _/___/.    l    /    l_    |   _/___/.',replace('          ._____\n _________|____(_______/\_________________\n.\_____   /_____    __   ._____/ _____   /\n    _/___/.    l    /    l_    |   _/___/.\nl_________|________/l__________|_________|\n=-=-=-=-=-=-=-=-=-=--=-=-=-=-=-=-=-=-=-=-=\n        qUICKNEW^sORTER bY bAFFLE!\nSort the output of QuickNew by Calypso/GOD\nto give it a MUCH better and improved dzg!\n÷( ''nOTHA gREAT wARE fROM bUMBLE bEE lAND )÷','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 19:40:39  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,NULL,1016,1,0,NULL,NULL,NULL,'scan',1780048428);
INSERT INTO door_catalog VALUES('bg09e1','BG09E1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BG09E1.LHA','bg','XIM','bg','0.9',NULL,NULL,'Online hack''n''slash',replace('Battle Grounds v0.9e1                       \nOnline hack''n''slash                         \n','\n',char(10)),'BGDoc.guide',replace('@database "BGDoc.guide"\n@Node Main "The Battle Grounds | Table of Contents"\n                        The Battle Grounds\n                        Version 0.9e1 ßeta\n\n          Copyright © 1992-1994, by Symbolic Source Group\n                       All rights reserved.\n\n        @{" Copyright and Disclaimer Notice " Link EG-COPYRIGHT}\n        @{" Registration Policies           " Link EG-REGISTER}\n        @{" Distribution Policies           " Link EG-DISTRIBUTION}\n        @{" Game Synopsis                   " Link EG-SYNOPSIS}\n        @{" Required Hardware               " Link EG-HARDWARE}\n        @{" Installation Information        " Link EG-SETUP}\n        @{" The Future                      " Link EG-PLANNED}\n        @{" Registered Features             " Link EG-REGFEATURES}\n        @{" Credits                         " Link EG-CREDITS}\n        @{" Authors                         " Link EG-AUTHORS}\n@ENDNODE\n\n@NODE EG-COPYRIGHT "Copyright and Disclaimer Notice"\n\n    This program and all the accompanying files are copyright ©1992-1994 by\nSymbolic Source Group.  All rights are reserved by the same.  This program\nmay not be altered or copied in any way, shape, or form, and may not be\nreproduced, or reverse-engineered.\n\n\n    Symbolic Source Group provides no warranty, either implied or otherwise\nas to the suitability of this product. In addition, Symbolic Source Group\ncannot be held liable under any circumstances for any damages that might\nresult from the use or misuse of this software.  Symbolic Source Group will\nonly gaurantee one thing, and that is, that this game will take up hard drive\nspace, and has been proven to run on our Amiga computer.  Your usage of this\nprogram means your acceptance of this statement.\n\n@ENDNODE\n\n@NODE EG-REGISTER "Registration Policies"\n\nThe registration system works as follows:\n\n    The initial registration is $15 (U.S. Dollars) for the current version.\nEach version after that is only $10 (U.S. Dollars).  All revisions (Major and\nMinor), and patches are free.\n\nHere are a few examples:\n\n    If you are currently using version .9a2 and it is your first\nregistration, then you would send $15.  The corresponding key file will work\nwith all previous versions up to 1.0a.  So, you could use .9a2, .9b, etc...\nIf you were using 1.0 and you registered it (sent the $15), then your key\nfile will work with every revision up to (but not including) version 2.0...\n\nYou may register a number of different ways:\n\n    1)  Print out the file Registration.txt.  Then send it with a check or\n        Money Order (the check must be drawn on a U.S. bank) for either $15\n        (you have never registered this software before), or $10 (you have\n        registered before, and just need an updated key file) to the address\n        listed in @{"Authors" Link EG-AUTHORS}.\n    2)  If you are not able to print out the file (or you don''t want to),\n        then you can call the support board (also listed in @{"Authors" Link EG-AUTHORS})\n        and leave a message to BG-Authors.  Simply leave the answers to\n        Registration.txt in the message.  Then send the check/MO to the above\n        address.  As soon as the check is received you will receive access to\n        the registered areas.\n\nWhat registered users get:\n\n    1)  A number of enhancements to the game listed in @{"Registered Features" Link EG-REGFEATURES}\n\n    2)  An account on the support board (Safe House BBS) with access to the\n        Battle Grounds ''registered'' areas.  You will be able to download the\n        newest versions of utilities and enhancements.  You will also receive\n        information on upcoming enhancements, releases, and new software from\n        Symbolic Source Group.\n\n    3)  Peace of Mind.  (hey, I know registering software can seem like a\n        hassle, but doesn''t knowing that you are running a registered copy\n        give you ''peace of mind''?)\n\nWho should register?\n\n    1) Those who contiue to use this software in conjunction with their\ninformation system (BBS/OIS/Network), and want the addition of other\nfeatures, as well as control over the game''s timing functions.\n\n    2) Those who run a private system (public-restricted use BBS), charge an\naccess fee, or run their board for profit MUST register this software.\n\n\n    I hope this explains the registration process to everyone.  If there are\nany questions, comments or even suggestions, then please contact me.\n\n@ENDNODE\n\n@NODE EG-DISTRIBUTION "Distribution Policies"\n\n    This software is being released under the Shareware concept.  Symbolic\nSource Group still retains the copyright to the software and all included\ndocumentation files.\n\n    This file may be distibuted by anyone as long as the following criteria\n    are met:\n\n    1)  The archive maintains its original contents.  You may convert the\n        archive to another format, provided that all the original files are\n        included in un-altered form.\n\n    2)  None of the files have been altered.  This includes the documentation\n        files!\n\n    3)  No charge is assessed for this software, except a reasonable copy fee\n        (reasonable fee is defined as the cost of copying, and possibly\n        mailing).  Shareware distribution networks, such as SkyNet, Amiga\n        Distribution Network, or FredFish are allowable types of\n        distribution.\n\n@ENDNODE\n\n@NODE EG-SYNOPSIS "Synopsis"\n\n    This game is called Battle Grounds.  It is an online game designed to be\nset up and run on a bulletin board system (although I suppose you COULD play\nit without a bbs).  When playing the game, online callers are given the\nopportunity to create a character to represent them inside the arena.\nPlayers roll their characters and the game keeps track of such statistics\nabout the game as strength and intelligence.  Once the player has equipped\nhis role playing character with the proper equipment, he/she then proceeds to\nenter the Grounds and battle monsters (and even other characters).  The game\nkeeps track of wins and losses, and can compute a ranking list according to\nthe complete list of players and their current levels.\n\n    This game was originally intented to be a character builder for another\nonline game to be released at a later date. However, this game is completely\nplayable by itself (and we will strive to continue to MAKE it playable by\nitself), we must admit we have a higher purpose for it.  What we are driving\nat is that at this point in time, there is no ultimate goal to speak of,\nother than staying alive!  This should be a feat in and of itself!\n\nFor more information about other projects we are working on see @{"The Future" Link EG-FUTURE}\n\n@ENDNODE\n\n@NODE EG-HARDWARE "Required Hardware and Software"\n\n\n    Hardware:\n            Amiga computer, with approx. 100K free memory\n            Hard drive (sorry, we don''t do dual floppies)\n            Appropriate modems and serial ports\n\n    Software:\n            Any bbs software that will run CLIable (DOS) programs\n            through some type of RAW compatible window/port.\n            DLG, Falcon, C-Net, and Excelsior will run this.\n\n@ENDNODE\n\n\n@NODE EG-SETUP "Installation Information"\n\nStep 1 : Start the install process by determining a directory where you wish\n         to keep the docmentation files (for the game), the players.data file\n         (which contains the data for player vs. player combat), and the\n         Users/ directory.\n\nStep 2 : Unarchive the program to this directory.\n\nStep 3 : Create another directory called ''Users'' in this directory.\n\nStep 4 : Edit the BattleG.config file and change the first line to the full\n         path of the directory you originally created (the directory that\n         holds the player.data file, and ''Users'' directory)\n\n         **NOTE**      The full path must end with either a '':'' or ''/''!\n\nStep 5 : Move (copy) the BattleG.config file to your S: directory (If you\n         have S: assigned to more than on directory, then you can copy it to\n         which ever of the S: assigned directories you wish, as long as it\n         can be accessed like so:  "S:BattleG.config").\n\nStep 6 : Setup the door in your BBS program.\n\n    You must make sure it runs the program through a RAW cli, or you will get\nsome erroneous results.  Also make sure that the BBS will abort the game by\nsending a Control-C, as that will tell the game to exit.  I would suggest\nlogging on and playing the game a few times first.  That way if the set-up is\nwrong or anything else shows up, you can fix it before your users run into\nit, too.\n\nThe command line to call the game correctly is:\n\n    bg FIRSTNAME LASTNAME   or    bg FULLNAME\n\n    Don''t worry if your software doesn''t provide this feature!  If bg\ndetects nothing on the command line, it will ask the full name each time.\n\n    The following are the setup instructions for those BBS sytems which The\nBattle Grounds has been tested on:\n\n    @{" Excelsior! " Link EG-EXCEL}\n    @{" Falcon     " Link EG-FALCON}\n    @{" C-Net      " Link EG-CNET}\n\nThere are a number of other BBS programs (like DLG) which will run this\nsoftware as well.  You will have to consult the documentation for those\nprograms to determine the proper setup.\n\n@ENDNODE\n\n@NODE EG-PLANNED "The Future"\n\nWhat is planned for The Battle Grounds?\n---------------------------------------\n\n    Firstly, the following updates will depend on the reply, so please\nlook through here and see if there is anything else that you would like\nto see for this.  Let me know your ideas, comments and suggestions.\n\n    Direct future:\n\n    ²   More monsters (multiple attacks, better handling).  This is THE\n        biggest suggestion, and to those who wonder why I haven''t added\n        more yet, I WILL!(*)\n\n    ²   Magic!  This will start with a few limited spells, and will later\n        be changed to a complete spell system...\n\n    ²   More equipment (weapons and armor).  This will soon be handled\n        differently, including the carrying of multiple weapons, and the\n        ability to select a different one before battle begins...\n\n    ²   Complete classes (Spell-casters, Clerics, Rogues, Hunters, etc...).\n\n    ²   Different utility programs to enhance game play.  External monster/\n        armor/spell editors.  Monster editor being first.  These will be\n        added for registered owners...\n\n\n    Future:\n\n    ²   Campaigns and complete adventures (compatible with your Battle\n        Grounds characters).\n\n    ²   REALTIME interaction and player against player multi-node!\n\n\nWhat else is coming from Symbolic Source Group?\n-----------------------------------------------\n\n        o An online campaign that uses Battle Ground characters.\n        o Other online games.  Hopefully GUI based...\n\n@ENDNODE\n\n@NODE EG-REGFEATURES "Registered Features"\n\n    Registered Features List\n    Updated 2-22-94 for version .9e\n\n    ²   Access to Battle Grounds time keeping functions.  Configurability\n        includes:\n            Time allowed per session.\n            Sessions allowed per "day".\n            Time to reset session counter.\n\n    ²   The character editor.  This will allow you to edit any character on\n        your system.  It is a CLI-able program, so it can be set up as a door\n        to allow Co-Sysop access.\n\n    ²   Top ten generation lists.  This program can be run at anytime (as an\n        event, or part of a textfile), and will generate lists based on\n        information passed at the command line.  Current list types include:\n        Top Ten:\n            Players by Level\n            Players by Experience\n            Heavy Hitters (highest point total in one hit)\n            Quick Kills (lowest rounds)\n\n    As new things are created for registered owners, I will give notification\nto each of the new feature.  You will then be able to F''Request it, download\nit, or have it sent to you.\n\n@ENDNODE\n\n@NODE EG-CREDITS "Credits"\n\n    I want to thank Jon Jackinchuk (the sysop of Hangar 18 Lansing) for\n    allowing me to use his board as a beta-test site for this game.\n    Until now, he has been the only real beta site for The Battle Grounds...\n    Thanks must also be given to Randy Darden for his suggestions and\n    support, and Jim Williams (of FireLine BBS) for the use of his board\n    in the early developing stages of this game.\n\n    Designed and Programmed by:         Josh Martin\n    Technical support, documentation,\n    and programming help from:          Mark Martin\n\n    Alpha-Test site:                    Safe House BBS\n                        Excelsior! BBS      (Sysop: Mark Martin)\n                                            1-(517)484-0431\n    Beta-Test sites:    Falcon CBCS     Hangar 18 (Sysop: Jon Jackinchuk)\n                                            1-(517)393-8749\n    Copyright 1992-1994 by:             Symbolic Source Group\n                                        (Mark and Josh Martin)\n\n    Thanks also, to the many people who have given hints, suggestions and\nconstructive criticisms.  I hope that everyone will enjoy playing this game,\nand I look forward to making more online entertainment software.\n\n\n@ENDNODE\n\n@NODE EG-AUTHORS "Authors"\n\n    I hope that everyone that plays this game enjoys it, and that those who\ndon''t, will let me know the ups and downs of this game.  For questions,\ncomments, registration information or to register, or any other question, I\ncan be reached by mail at:\n\n            Symbolic Source Group\n            ATTN: BattleG Authors\n            P.O. Box 11\n            Okemos, Michigan (MI)\n                            48805\n\n    I can also be reached on The Safe House BBS.  This board is the\ndistribution site for The Battle Grounds and is a site for all software\nproduced by Symbolic Source Group.  The latest release version is always\navailable for download, and the latest beta version is available for play.\n\n    Also, the release version of The Battle Grounds can be File requested\nfrom this site, or you can annonymous ftp it from there as well.\n\nHere are the addresses and phone number:\n\n    Safe House BBS (located in Lansing MI)\n        Phone #     1-517-484-0431\n        FIDONET     1:159/370\n        Internet    SafeHouse.sojourn.com\n                    199.177.127.70 (IP address)\n\n    You can e-mail me via the Internet at "[email removed]".  I\nwill reply as soon as I can (I check about twice a day).  Please be aware\nthat you can telnet to safehouse.sojourn.com and download the registered\nsoftware (if you are a registered owner), or annonymous ftp the latest\nrelease.\n\n@ENDNODE\n\n@NODE EG-EXCEL "Excelsior BBS Setup"\nCreated on 2-21-94 by Josh Martin\n\nThe following is the setup for Excelsior! BBS version 1.18\n(although for version 1.18, this applies to all version down to .996)\n\n    1.  Once you have the files in their respective directories.  Simply\n        ''A''dd an item to your doors area. (you can put it inside directories\n        if you wish)\n\n    2.  When asked for the directory, enter the directory containing the\n        executable ''bg'' (or use the default directory, if that''s where you\n        put it)\n\n    3.  Enter the pattern as ''bg'' and after selecting the executable, enter\n        the short description for the game, and the Access Group.\n\n    4.  Set the door type to ''DOS'', the DOS args to ''%2'', and the IPL variable\n        to ''0''.\n\n    5.  Set the other items to you liking, howver, set ''Only one user at a\n        time?'' to ''Yes''.\n\n    6.  Then ''E''dit this item and change the RAW Mode to ''Yes''.  You may\n        change any of the other flags to your liking.\n\n\n@ENDNODE\n\n@NODE EG-FALCON "Falcon BBS Setup"\nCreated on 2-21-92 by Josh Martin\n\nThe following is the menus.bbs file setup for Falcon CBCS on our system:\n\n    DISGRACE   B  RAW C "path.to.bg/bg «FULLNAME»"\n    1 ^       2^  3^ 4^         5^\n\n    1.  DISGRACE is the access level of this command.  Set this to what ever\n        access level you wish.\n\n    2.  B is the command key.  Again you can set this to what ever key you\n        wish to use to activate this door.\n\n    3.  RAW. The game must be run as a RAW not a CLI, or the game will not\n        run properly.\n\n    4.  C is the only flag you really need to use (for Control-C).  The game\n        will attemp to save the character then quit after receiving a\n        control-c from Falcon.\n\n    5.  "path.to.bg/bg «FULLNAME» is the command line.  ''path.to.bg/'' is the\n        full directory path where you put bg.  Use «FULLNAME» to pass the\n        user''s full name to bg.\n\n@ENDNODE\n\n@NODE EG-CNET "C-Net Setup"\n\nThe following is the setup for C-Net:\n\n    Add the game to the menu, being sure to indicate to CNet that "BG" (the\nactual name of the game) is a DOS program.  If one wishes to pass the handle\nof the player to the game, use the CNet DOS argument "%1".  Or, to pass the\nusers real name, use the argument "%3".  This would be done when CNet asks\nfor additional DOS arguments as you''re configuring the game (do NOT include\nthe quotes!).\n\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',49223,2,0,NULL,NULL,'bg09e1','scan',1780048428);
INSERT INTO door_catalog VALUES('biorhthm','BIORHTHM.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BIORHTHM.LHA','Biorhythms','XIM','Biorhythms',NULL,NULL,NULL,'|    nICE wB bIORHYTHM cALCULATOR, v3.0    | | :                                      : | `-:---------                    ---------:-''',replace('.------------------------------------------.\n|    nICE wB bIORHYTHM cALCULATOR, v3.0    |\n| :                                      : |\n`-:---------                    ---------:-''\n  :                                      :\n','\n',char(10)),'Biorhythms.Readme',replace('Short:    Nice WB biorhythm calculator, V3.0\nAuthor:   [email removed] (Richard Smedley)\nUploader: [email removed] (Richard Smedley)\nType:     util/misc\n\nA fully-resizable biorhythm calculator for Workbench, with a nice intuition\nfront-end. Freeware!\n\nRequires Kickstart 2.0 or better.\n\n','\n',char(10)),NULL,'auto-added',31118,2,0,NULL,NULL,'biorhthm','scan',1780048428);
INSERT INTO door_catalog VALUES('bisdn190','BISDN190.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BISDN190.LHA',NULL,'XIM','bscisdn.device',NULL,NULL,NULL,'new LOGFILE entries [20:35:12]-[ cOOl cORONa BBS ]-[24 Jan 1995]',replace('V 2.190 of BSCISDN.DEVICE\nnew LOGFILE entries\n[20:35:12]-[ cOOl cORONa BBS ]-[24 Jan 1995]\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 19:40:33  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',23647,1,0,NULL,NULL,'bisdn190','scan',1780048428);
INSERT INTO door_catalog VALUES('bitime10','BITIME10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BITIME10.LHA',NULL,'XIM','>>> _BiRDTiMES_ <<<','1.00','ThE',NULL,'A nice AIM for /X 2.20+ Written by ThE BiRD .------------------------------------------. |       ANOTHER FINE PRODUCT OF THE        |',replace('          >>> _BiRDTiMES_ V1.00 <<<\nA nice AIM for /X 2.20+ Written by ThE BiRD\n.------------------------------------------.\n|       ANOTHER FINE PRODUCT OF THE        |\n|          /X DEVELOPEMENT TEAM            |\n`------------------------------------------''\n','\n',char(10)),'BiRDTiMES.DOC',replace('******************************************************************************\n** 09-19-92      	 _BiRDTiMES_ VerSiON 1.0			    **\n**			          						    **\n**     		   --> Coded by The Bird of X-TRADE <--			    **\n******************************************************************************\n                        --> FULL DOCUMENTATION <--\n\nThis little door is for sysops who have user that are not uploading and\nallways comes into the bbs for looking for new Warez and then logs off.\nSo i decided to write this littl door. With this door you can prevent sume\nuser for logging into your bbs at a special time. so lets say you have a User\n"X" and you don`t want him to call at 18:00:00 - 20:00:00. So you can use\nmy door to prevent him to do this.\n\nWhat you need for this Door is the following:\n\n      - SHOULD BE IN DIRECTORY DOORS:BIRDTIMES or it doesn`t work\n      - SHOULD BE INSTALLED IN THE CUSTOMCOMMANDS OR SYS.CMD\n      - THERE SHOULD BE A CONFIG FILE - LOOK AT THE EXAMPLE\n      - THERE SHOULD BE A DIRECTORY "USER" in THE BIRDTIMES DIR !!\n \nSo all ya have to do is the following:\n\n- copy the whole birdtimes directory to yar DOORS: directory\n- go to CustomCommands or SYS.CMD (for AEV2.30+) file and install iT:\n  \n---- cut here ----\nBIRDTIMES RM001DOORS:BIRDTIMES/BIRDTIMES.REXX\n---- cut here ----\n\n- now install the door into a BULLxx.TXT file in the "NODEx" Directory\n  with the MCI commandos:\n\n---- cut here ----\n~CC_BIRDTIMES|\n~SP|\n---- cut here ----\n\n- The Door have to be started before any other texts or doors, or the\n  user can`t login again at the day he called wrong.\n\n- Install the config File (DOORS:BIRDTIMES/BIRDTIMES.CFG)\n\n---- cut here ----\nLamerNr1    <----- ThE UserName of the Guy You Don`t want at a special time\n00:00:00    <----- 1.Begin Time where the above user can call\n16:00:00    <----- 1.End Last Time a User can call without loosing time\n17:00:00    <----- 2.Begin Time where the above user can call again (OPTIONAL)\n24:00:00    <----- 2.End Last Time a User can call without loosing time (OPT)\nLamerNr2    <----- The Username of the 2.Guy you don`t want at a special time\n00:00:00    <----- 1.Begin Time where the above user can call\n01:00:00    <----- 1.End Last Time a User can call without loosing time\n---- cut here ----\n\nTHiS Should be all for now... I Hate writing Docs except the AMIEX DOC ;-)\nSo see ya in an other fine production from me.. and will be great to report\nme all the bugs in here... see ya at my bbs:\n \n==========================[+49-711-777-5990]===============================\n              _|____  ______________._________/\    ___\n               |    \/    |o   _    |        /  \  |   |\n  EqUiPmEnT:   |o         ||  |_\___|o  |   //   \ |:  |       EmPeRaToRs:\n  ~~~~~~~~~~   ||  \  /   |:   _|___||  |__//     \|_  |._/\   ~~~~~~~~~~~\n 21øMb OnBoard |:  |\/|   |.  |_/   ||  | /.  /\    /  ||   \   ThE BiRD\n  384øø/Os2.0  |.  |  |___|___|_____|___|/   ___\  /   |____/     AnDY!\n AMiX 2.3ø Reg |___|          |          \  /    \/|___|         J.J.F.!\n            _______  _________._________. \/\ ._______  _________.\n           |       \|    _    |o   _    | /  \|       \|    _    |\n===========|o  |\_  \_  |_\___||  | \___|//   \o  |\_  \_  |_\___|=========\n CaLL NoW! ||  | /   /   _|___||  |  ___//     \__| /   /   _|____ ------>>\n===========|:  |/   /:  |_/   |:  |_/  /.  /\    /|/   /:  |_/   |=========\n           |___/___/|.  |_____|_______/   ___\  /_/___/|.  |_____|\n                    | __|             \  /    \/       | __|     [eNf]     \n                    |/                 \/              |/     \n  ø-2 DayZ WaREZ !  |  ...where the warez come from... |  ø-2 Dayz WaREZ !\n\n==========================[+49-711-777-5990]===============================\n','\n',char(10)),NULL,NULL,7369,2,0,NULL,NULL,NULL,'scan',1780048428);
