INSERT INTO door_catalog VALUES('bk_prolm','BK-PROLM.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BK-PROLM.LHA',NULL,'XIM','_|__  ___  __|_ |__/_ ___ ____ __ __ ___  2F',NULL,NULL,'BK','l___)(___|(___/ |   /(___||   ''| | /(___| -. .------------------------------------------'' |              P r e s e n t s',replace('_|__  ___  __|_ |__/_ ___ ____ __ __ ___  2F\nl___)(___|(___/ |   /(___||   ''| | /(___| -.\n.------------------------------------------''\n|              P r e s e n t s\n`------------------------------------------.\n             ProOLM v1.1 for /X            |  \n                                           |\n Great OLM utility which will send message |\n right away instead of waiting forever for |\n     users to return to command prompt     |\n- - --- -----------------------------------''\n','\n',char(10)),'ARC-WHQ.TXT',replace('                                           ______\n        - -- - ----------- \---------| ___|__    |---_-____________ __ _\n zERO dAY cONSOLE & aMIGA   \\       ||      |   |  _ _________    \gem/aL\n  bAD kARMA wORLD hEADQUARTERS\      /\      |          |   (_/    /\n .  aRCADIA wORLD hEADQUARTERS \\             |   |      |    /    / \n_|__ _________________________ _\____/\______|   |______|________/_\n |                               \        |_ __ _|- yOUR gODS:  \n       aCCESS bY rEFERAL oR nUP oNLY!     |      .      Eric The RED/ARC^BK\n   _________  _ _____ __________ _________|    __|___    Night Assassin/SNK\n   \   ____/_/_      \ _ ____   \     _____|  /    _/___     Son Doobie/WTC\n   /     /     | |    \   |_/   /-.    __/__  \____     \         Zigor/ARC\n  /     |      | _)    \  \   _/  |  _/     |    |/     /      Rain Man/SNK\n  \____________|_|      \__\______|_________|__________/  \n   _   _  __ ___ |_______\ _ _____________________ _ ___ _ ________ _ _|_\n                                                                       |\n                       nODE 1: USR 33.6k v.eVERYTHING\n             