INSERT INTO door_catalog VALUES('bk_sizec','BK-SIZEC.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BK-SIZEC.LHA',NULL,'XIM','pizza_taxi.exe',NULL,NULL,'BK','l___)(___|(___/ |   /(___||   ''| | /(___| -. .------------------------------------------'' |              P r e s e n t s',replace('_|__  ___  __|_ |__/_ ___ ____ __ __ ___  2F\nl___)(___|(___/ |   /(___||   ''| | /(___| -.\n.------------------------------------------''\n|              P r e s e n t s\n`------------------------------------------.\n            SizeCheck v1.1 for /X          |  \n                                           |\n  Door to allow sysop/users to check how   |\n      much is online in conferences.       |\n   Divided into dirs/total, bytes/files    |\n- - --- -----------------------------------''\n','\n',char(10)),'Ringelblume4.txt',replace('                 \n                                  ·     ·\n                               _ __\   /__ _\n                            _ _)\\  \ /  //(_ _\n                           -\   __\° X °/__   /-\n                    _ __ ___ ___)  \/_\/  (___ ___ __ _\n                   -\\\_\\__\\__  _ /¦\ _  __//__//_///-\n             ·         _.      \__)_¯_¯_(__/      ._         ·\n           _/          \|_       | | | | |       _|/          \_\n         __\ ___ _/\____\/__ __ _| | | | |_ __ __\/____/\_ ___ /__\n       _/   \  (_)  \   \/  /_/\\| |_|_| |//\_\  \/   /  (_)  /   \_\n       |                    \_\/ | | | | | \/_/                    |\n      _|                      __ | | | | | __                   _ _|_\n      \|_ _                   \/_| | | | |_\/                      |/\n       |                     · _)  ¯_¯_¯  (_ ·                     |\n       |  ·H2o!·              \\___ \ / ___//                      |\n       ¯\_______________________ _)  Y  (_ _______________________/¯\n                                 \___ ___/\n                                    (_)\n ','\n',char(10)),NULL,'auto-added',16788,4,0,NULL,NULL,'bk_sizec',