INSERT INTO door_catalog VALUES('bk_up112','BK-UP112.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BK-UP112.LHA',NULL,'XIM','sonnencreme.exe',NULL,NULL,'BK','// __\__ \__\  |/   /                     | _/   _/ _/    /  _/.  B A D   K A R M A  | \____)   \_.__\____|       //            |',replace('  /   ____   ___  ____   _ ________________.\n // __\__ \__\  |/   /                     |\n  _/   _/ _/    /  _/.  B A D   K A R M A  |\n  \____)   \_.__\____|       //            |\n- ----\______|---------------/--------sTZ!-''\n.------------------------------------------.\n|   UltraPage V 1.12 & QuickAvail V 1.01   |\n| A Great Sysop Pager & Frontend Door For  |\n| S!X & /X.  Now Also Allows You To Edit A |\n| Line Why You (The Sysop) Are Gone.       |\n`-------------------------------23/Sep/96--''\n','\n',char(10)),'Schnabeltasse.doc',replace('\n\n\n               /                                           \\n              ·/(_____ sPEEEEEEEED aND fRIENDS ONlY! _____)\·\n             /                                               \\n                          fILE pASSED tHE L.E.BBS             \n             \   _____                               _____   /\n              ·\(      sPEEEEEEEED aND fRIENDS ONlY!      )/·\n               \                                           /\n    \n\n','\n',char(10)),NULL,'auto-added',75905,5,0,NULL,NULL,'bk_up112','scan',1780048428);
INSERT INTO door_catalog VALUES('bk_z095','BK-Z095.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BK-Z095.LHA',NULL,'XIM','sonnencreme.exe',NULL,NULL,'BK','// __\__ \__\  |/   /                     | _/   _/ _/    /  _/.  B A D   K A R M A  | \____)   \_.__\____|       //            |',replace('  /   ____   ___  ____   _ ________________.\n // __\__ \__\  |/   /                     |\n  _/   _/ _/    /  _/.  B A D   K A R M A  |\n  \____)   \_.__\____|       //            |\n- ----\______|---------------/--------sTZ!-''\n.------------------------------------------.\n| ZipShell V 0.95  -  A door that allows   |\n| your BBS-users to access your ZipDrive   |\n| Works on  /X & S!X                       |\n`---------------------Jan 06,''97 - nr 101--''\n','\n',char(10)),'Schnabeltasse.doc',replace('\n\n\n               /                                           \\n              ·/(_____ sPEEEEEEEED aND fRIENDS ONlY! _____)\·\n             /                                               \\n                          fILE pASSED tHE L.E.BBS             \n             \   _____                               _____   /\n              ·\(      sPEEEEEEEED aND fRIENDS ONlY!      )/·\n               \                                           /\n    \n\n','\n',char(10)),NULL,'auto-added',78823,4,0,NULL,NULL,'bk_z095','scan',1780048428);
INSERT INTO door_catalog VALUES('blc_l111','BLC-L111.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BLC-L111.LHA',NULL,'XIM','LhaStorm1.11',NULL,'Lha/Lzh','BLC','|     _|_________ _______      ____________. |      __       /_\     /   ___\    __     | |       /      /       /____\        /_____|',replace('.______.\n|     _|_________ _______      ____________.\n|      __       /_\     /   ___\    __     |\n|       /      /       /____\        /_____|\n|      /      /       /      \      /      |\n|____________/________________\_________pHS!\n -------------- [ bALANCE ] ---------------\n       - Presents - LhaStorm v1.11! -\n    The ultimate Lha/Lzh stripper/adder!\n  No more hand editing of those striplists!\n      * New great improvements done! *','\n',char(10)),'LhaStorm.doc',replace('\n                                LhaStorm 1.11\n\n                                Documentation\n                     (does it really need one? heh ...)\n\n                       Copyright © 1995- Jani Oinonen \n\n                          Released 7 October 1995\n\n\n                                   Preface\n                                   ~~~~~~~\n\nIf  you find this program worth using, then why don''t you write me some\nlines, and tell me what you think about it. It could be bug reports,\nimprovement ideas and so on. If you do so, I will personally send you the\nlatest update the day after release! The address can be found below.\n\nLhaStorm must be distributed in this archive in unmodified form. Nothing\nmay be added, or removed  from it. I take no responsibility for any\ndamage LhaStorm may cause. Use it at your own risk. Contact me at:\n\n Jani Oinonen ( Excel/Balance )\n Kungsg. 9L\n S-553 31 Jønkøping\n Sweden\n\n +46-(0)36-711462\n\n Global Effect: +46-500-485978 (Balance SHQ)\n Outpost: +46-36-141536,145544,148001\n\nYou can also write me for high quality demo and Body tape swapping.\n\n\n                               Introduction\n                               ~~~~~~~~~~~~\n\nAs I''m a modem user I can''t avoid seeing all those bbs adverts in every\ndownloaded archive ... I have downloaded 4kb intros  and found that the\narchives was over 80kb! 80-4= 76kb of bbs adverts. I think it''s sick!\nThere''s some certain bbs''s that add between 5-10 adverts and many of them\nIFF adverts and executables. So I thought that why don''t I do my part and\nmake my own stripper/adder. All my old strippers were pretty bad. If you\nwanted to update the striplist you had to do it by hand. And who does\nthat? Especially when the bbs''s use strange chars and spaces. So, I\nimplented a pretty work and time saving function called ''learn''. More\ninfo later on. LhaStorm can be used with Daydream and AmiExpress and all\nother bbs programs and others like Opus and so on. This program handles\nalso multiple args so that you can supply it with many archive names, not\nonly one, as with many others.\n\n\n                               Installation\n                               ~~~~~~~~~~~~\nSimply copy the striplist.txt and addlist.txt to S: and LhaStorm to\nC: or wherever you want it. Done! You should also have Reqtools.library\nin LIBS: ... \n\n                                  Usage\n                                  ~~~~~\nThe usage is very simple. The arguments are:\n\n NOADD   - Tells LhaStorm not to add any bbs adverts from addlist.txt.\n           Default is false.\n NOSTRIP - Tells LhaStorm not to strip files in archive from striplist.txt.\n           Default is false.\n LEARN   - This opens a filerequester where you can chose which files to\n           learn. More info comming ... Default is false.\n\nStarting LhaStorm from Shell\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n Here are some examples:\n\n1> LhaStorm NOADD file.lha file2.lha ...\n\n This only strips the .lha files from adverts.\n\n1> LhaStorm NOSTRIP file.lha file2.lha ...\n\n This only adds your adverts.\n\n1> LhaStorm NOADD NOSTRIP file.lha file2.lha ...\n\n Hmm ... Really necesary ... hehe ...\n\n1> LhaStorm LEARN\n\n This opens a filerequster. Before you start LhaStorm in LEARN mode, then\n do this. First unpack all your latest archives into one directory, lets\n say RAM:bbsadverts/ or whatever. Then you delete all files except the bbs\n adverts. Now you should have one directory, RAM:bbsadverts/ with all bbs\n adverts you wish you to learn LhaStorm. Then you\n start LhaStorm in learn mode. A filerequster should pop up. Choose all\n adverts and then press OK. Now you have learned LhaStorm all the new nasty\n adverts! Simple and easy! No more hand editing! Well, that was all!\n\nUsing LhaStorm in Dopus\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n - First choose "configuration" in the menu.\n - Press "buttons".\n - Choose a suitable button where to place LhaStorm.\n - Press the "New Entry" button.\n - Write C:LhaStorm {F} (or wherever you have placed it!)\n - Press on the "Command" so many times until AmigaDos appears.\n - These flags should be chosen: Do All Files, Output Window.\n - Fill in the name for the button and desired colors.\n - Thats it! Once you have installed it, it''s great! Ehrm ...\n\nSmall notes!\n¯¯¯¯¯¯¯¯¯¯¯¯\n * The size for striplist.txt is unfortunately hardcoded to 30kb. But I\n guess that will be no problems, but I''ll change that in the future! \n\n * There are some certain characters LHA can''t handle in a addlist or\n striplist. So if you ever get a ''Lha failed return code 20'' or something\n similiar, and you know that it worked some minutes before, then go\n through your striplist for the new adds and remove them and try again.\n\n * If you only want to select a couple of files instead of pressing the ''all''\n button then hold down shift while selecting the files.\n\n * Some bbs''s uses filenames with spaces. And that means that the filename\n has to start and end with ". My previous versions did not do this, but that\n is fixed now!\n\n                          TODO IN FUTURE VERSIONS\n                          ~~~~~~~~~~~~~~~~~~~~~~~\n\n - Support for ZIP, ARJ and LZX.\n - Security routine to prevent fake updates.\n - Any ideas?  See ''Preface'' for my address.\n\n\n\n                              Program History\n                              ~~~~~~~~~~~~~~~\nRelease 1.11\n¯¯¯¯¯¯¯¯¯¯¯¯\n - Now it inserts "" before and after the filename if it contains white\n   spaces! \n - Fixed several embarassing bugs. No more details! hehe ... Now it SHOULD\n   work fine ...\n - Included error report routines, so you will from now on know what\n   really happened ...\n - At the moment I don''t know of any bugs.\n\nRelease 1.10\n¯¯¯¯¯¯¯¯¯¯¯¯\n - First public release.\n - Optimized program.\n - Fixed a few small bugs.\n\nRelease 1.00ß\n¯¯¯¯¯¯¯¯¯¯¯¯\n - Added LEARN function.\n - Added also NOSTRIP and NOADD options.\n - A $VER string also included. The toughest part ... heh ...\n\n\n      Music support (I wouldn''t have done it without them! hehe ...)\n      ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                            Frontline Assembly\n                                  Haujobb\n                               Dance or die\n                               Leatherstrip\n                                   T.H.D\n                                   Will\n                                  AndOne\n                               Cat Rapes Dog\n                            Xmarks the pedwalk\n                                 Delerium\n                               Vomito Negro\n\n                     And all other great Body groups!\n\n                              Some greetings \n                              ~~~~~~~~~~~~~~\n                           Citron. - (Electron)\n                        Gods - (Zombie,Ghandy,PGL)\n                           Rebels - (Slime,Grey)\n                  TRSI - (Mr.King,QBA,BaldHorse,Overdose)\n                            Desire - (Jackpot)\n                           Parasite - (Steffen)\n                          Avantgarde - (TheCrow)\n                           Accession - (Zuffel)\n                   RamJam - (Payday, Klorathy, Atheist)\n                          Stellar - (Dalmak, Mac)\n                            Meetro - (UltraSur)\n                             Blaze - (Slayer)\n                           Beetless - (Skiathos)\n                            Fanatic - (Maniac)\n                           Impact DK - (Adonis) \n                            Chrome - (Hacksaw)\n                   Illusion - (Substance, Wayne, Pinkie)\n                             Mirage - (Sascha)\n                            Hellfire - (Dragon)\n                            Fear - (The Trader)\n                             Scope - (Kurczak)\n                            Amnesty - (Kipers)\n                           Cadaver - (Covenant)\n                            Crap! - (Le Chien)\n                           Disorder - (Hostile)\n                             Omega - (Norsman)\n                         DreamDealers - (Napoleon)\n                           Mystic - (Mike, Mars)\n                           Necropolis - (Barman)\n                              TPD - (Python)\n                            Mobile - (Paperboy)\n                            Suspiria - (Madsen)\n                          Abyss - (Toxic, Sting)\n                           Sardonyx - (Hostile)\n                        Mad Elks - (Action, Adonis)\n                      Razor1911 - (Deelite, Diesel8)\n                            Exxon - (St.Eagle)\n                            Magic - (Spectral)\n                             Subject - (Adder)\n                             Passion - (Xman)\n                              Spoon - (Duffy)\n                            Moment22 - (Zero!)\n                        Insane - (Coolorado, Phase)\n                            Lagoon - (Colonel)\n                             Giants - (Wizard)\n                            Saints - (Phuture)\n                        Shrimps Design - (Culture)\n                               Act - (Sunny)\n                         Scoopex - (Darren, Newt)\n                            Essence - (Dodger)\n                          Banal Projects - (Suhu)\n                           Ozone Free - (Pinkie)\n    Freezers - (Lenin, Immortal, Sputnik, Sky, Freeman and all others!)\n                             Finesse - (Deone)\n                              Vacuum - (Dave)\n                            Slurry - (Intense)\n                              ???? - (Mystra)\n                               ???? - (Wea)\n                              ???? - (Snuffy)\n                            ???? - (Scoundrel)\n                              ???? - (Vacum)\n                            ???? - (Leviticus)\n                            ???? - (Ironnuke!)\n                               ???? - (Dash)\n\n                          All members of Balance:\n\n     Wolfman, Subject, RWO, Scope, Unique, Connor, Motion, Split, Kata\n       Atheist, Confidence, Xerxes, Vicious, Pantera, Grid, Deelite\n                        Nutcase, Coma and Bigmama!\n\n                            I love you all! ;)\n\n','\n',char(10)),NULL,'auto-added',9708,2,0,NULL,NULL,'blc_l111','scan',1780048428);
INSERT INTO door_catalog VALUES('blc_ls11','BLC-LS11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BLC-LS11.LHA',NULL,'XIM','LhaStorm',NULL,'Lha/Lzh','BLC','|     _|_________ _______      ____________. |      __       /_\     /   ___\    __     | |       /      /       /____\        /_____|',replace('.______.\n|     _|_________ _______      ____________.\n|      __       /_\     /   ___\    __     |\n|       /      /       /____\        /_____|\n|      /      /       /      \      /      |\n|____________/________________\_________pHS!\n -------------- [ bALANCE ] ---------------\n        - Presents - LhaStorm v1.1! -\n    The ultimate Lha/Lzh stripper/adder!\n  No more hand editing of those striplists!\n          LhaStorm does it for you!','\n',char(10)),'LhaStorm.doc',replace('\n                               LhaStorm 1.1\n\n                               Documentation\n\n                      Copyright © 1995- Jani Oinonen \n\n                        Released 11 September 1995\n\n\n                                 Preface\n                                 ~~~~~~~\n\nIf  you find this program worth using, then why don''t you write me some\nlines, and tell me what you think about it. It could be bug reports,\nimprovement ideas and so on. If you do so, I will personally send you the\nlatest update the day after release! The address can be found below.\n\nLhaStorm must be distributed in this archive in unmodified form. Nothing\nmay be added, or removed  from it. I take no responsibility for any\ndamage LhaStorm may cause. Use it at your own risk. Contact me at:\n\n Jani Oinonen ( Excel/Balance )\n Kungsg. 9L\n S-553 31 Jønkøping\n Sweden\n\n +46-(0)36-711462\n\nYou can also write me for high quality demo swapping.\n\n\n\n                               Introduction\n                               ~~~~~~~~~~~~\n\nAs I''m a modem user I can''t avoid seeing all those bbs adverts in every\ndownloaded archive ... I some weeks ago downloaded a 4kb intro from Impact\n( Hi! ) and found that the archive was over 80kb! 80-4= 76kb of bbs adverts.\nI think it''s sick! There''s some certain bbs''s that add between 5-10 adverts\nand many of them IFF adverts and executables. So I thought that why don''t\nI do my part and make my own stripper/adder. All my old strippers were\npretty bad. If you wanted to update the striplist you had to do it by hand.\nAnd who does that? Especially when the bbs''s use strange chars and spaces.\nSo, I implented a pretty work and time saving function called ''learn''. More\ninfo later on. LhaStorm can be used with Daydream and AmiExpress and all\nother bbs programs and others like Opus and so on. This program has also a\nfunction that you can supply it with many archive names, not only one as\nwith many others.\n\n\n                               Installation\n                               ~~~~~~~~~~~~\nSimply copy the striplist.txt and addlist.txt to S: and LhaStorm to\nC: or wherever you want it. Done! You should also have Reqtools.library\nin LIBS: ...\n\n\n                                  Usage\n                                  ~~~~~\nThe usage is very simple. The arguments are:\n\n NOADD   - Tells LhaStorm not to add any bbs adverts from addlist.txt.\n NOSTRIP - Tells LhaStorm not to strip files in archive from striplist.txt.\n LEARN   - This opens a filerequester where you can chose which files to\n           learn. More info comming ...\n\nStarting LhaStorm from Shell\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n Here are some examples:\n\n1> LhaStorm NOADD file.lha file2.lha ...\n\n This only strips file.lha from adverts.\n\n1> LhaStorm NOSTRIP file.lha file2.lha ...\n\n This only adds your adverts.\n\n1> LhaStorm NOADD NOSTRIP file.lha file2.lha ...\n\n Hmm ... This doesn''t do so much! ;)\n\n1> LhaStorm LEARN\n\n This opens a filerequster. Before you start LhaStorm in LEARN mode, then\n do this. First unpack all your latest archives into one directory, lets\n say RAM:bbsadverts/. Then you delete all files except the bbs adverts.\n Now you should have one directory, RAM:bbsadverts/  with all bbs adverts\n you wish you to learn LhaStorm. Then you make sure that your current dir\n is RAM:bbsadverts/ simply by writing RAM:bbsadverts in DOS. Then you\n start LhaStorm in learn mode. A filerequster should pop up and you should\n be able to see all your bbs adverts. Press the ALL button and then OK. Now\n you have learned LhaStorm all the new nasty adverts! Simple and easy! No\n more hand editing! Well, that was all!\n\n Note: If you only want to select a few files of them, then you can hold\n down SHIFT during selection.\n\n\nUsing LhaStorm in Dopus\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n - First choose "configuration" in the menu.\n - Press "buttons".\n - Choose a suitable button where to place LhaStorm.\n - Press the "New Entry" button.\n - Write C:LhaStorm {F} (or wherever you have placed it!)\n - Press on the "Command" so many times until AmigaDos appears.\n - These flags should be chosen: Do All Files, Output Window.\n - Fill in the name for the button and desired colors.\n - Thats it! Once you have installed it, it''s great! Ehrm ...\n\nA small note!\n¯¯¯¯¯¯¯¯¯¯¯¯¯\n The size for striplist.txt is unfortunately hardcoded to 30kb. But I guess\n that will be no problems, but I''ll change that in the future! \n\n\n                          TODO IN FUTURE VERSIONS\n                          ~~~~~~~~~~~~~~~~~~~~~~~\n\n - A config file maybe.\n - Support for ZIP, ARJ and LZX.\n - Security routine to prevent fake updates.\n - If no files were given then pop up a filerequester.\n - Any ideas?  See ''Preface'' for my address.\n\n\n\n                              Program History\n                              ~~~~~~~~~~~~~~~\n\nRelease 1.10\n¯¯¯¯¯¯¯¯¯¯¯¯\n - First public release.\n   Optimized program.\n   Fixed a few small bugs.\n\nRelease 1.00ß\n¯¯¯¯¯¯¯¯¯¯¯¯\n - Added LEARN function.\n   Added also NOSTRIP and NOADD options.\n   A $VER string also included.\n\n\n                              Some greetings \n                              ~~~~~~~~~~~~~~\n                           Citron. - (Electron)\n                        Gods - (Zombie,Ghandy,PGL)\n                           Rebels - (Slime,Grey)\n                  TRSI - (Mr.King,QBA,BaldHorse,Overdose)\n                            Desire - (Jackpot)\n                           Parasite - (Steffen)\n                          Avantgarde - (TheCrow)\n                           Accession - (Zuffel)\n                   RamJam - (Payday, Klorathy, Atheist)\n                          Stellar - (Dalmak, Mac)\n                            Meetro - (UltraSur)\n                             Blaze - (Slayer)\n                           Beetless - (Skiathos)\n                            Fanatic - (Maniac)\n                           Impact DK - (Adonis) \n                            Chrome - (Hacksaw)\n                   Illusion - (Substance, Wayne, Pinkie)\n                             Mirage - (Sascha)\n                            Hellfire - (Dragon)\n                            Fear - (The Trader)\n                             Scope - (Kurczak)\n                            Amnesty - (Kipers)\n                           Cadaver - (Covenant)\n                            Crap! - (Le Chien)\n                           Disorder - (Hostile)\n                             Omega - (Norsman)\n                         DreamDealers - (Napoleon)\n                           Mystic - (Mike, Mars)\n                           Necropolis - (Barman)\n                              TPD - (Python)\n                            Mobile - (Paperboy)\n                            Suspiria - (Madsen)\n                          Abyss - (Toxic, Sting)\n                           Sardonyx - (Hostile)\n                        Mad Elks - (Action, Adonis)\n                      Razor1911 - (Deelite, Diesel8)\n                            Exxon - (St.Eagle)\n                            Magic - (Spectral)\n                             Subject - (Adder)\n                             Passion - (Xman)\n                              Spoon - (Duffy)\n                            Moment22 - (Zero!)\n                        Insane - (Coolorado, Phase)\n                            Lagoon - (Colonel)\n                             Giants - (Wizard)\n                            Saints - (Phuture)\n                        Shrimps Design - (Culture)\n                               Act - (Sunny)\n                         Scoopex - (Darren, Newt)\n                            Essence - (Dodger)\n                          Banal Projects - (Suhu)\n                           Ozone Free - (Pinkie)\n                         Obsession - (Hyper Hype)\n    Freezers - (Lenin, Immortal, Sputnik, Sky, Freeman and all others!)\n                             Finesse - (Deone)\n                              Vacuum - (Dave)\n                            Intense - (Intense)\n                              ???? - (Mystra)\n                               ???? - (Wea)\n                              ???? - (Snuffy)\n                            ???? - (Scoundrel)\n                              ???? - (Vacum)\n                            ???? - (Leviticus)\n                            ???? - (Ironnuke!)\n                               ???? - (Dash)\n\n                          All members of Balance:\n\n     Wolfman, Subject, RWO, Scope, Unique, Connor, Motion, Split, Kata\n       Atheist, Confidence, Xerxes, Vicious, Pantera, Grid, Deelite\n                    Nutcase, Roland, Coma and Bigmama!\n\n                            I love you all! ;)\n\n','\n',char(10)),NULL,'auto-added',8136,3,0,NULL,NULL,'blc_ls11','scan',1780048428);
INSERT INTO door_catalog VALUES('bldtxt20','BLDTXT20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BLDTXT20.LHA','bLDtXT','XIM','bLDtXT','2.0',NULL,NULL,NULL,replace('BLOOD_TXT V2.0 (F·D·H VERSION)\n','\n',char(10)),'bLDtXT.dOC',replace('\n                   __ __   ___   _____ ___   ___   ___\n                  /  V  \_/ . \_/  __// . \_/ | \_/ _ \\n        _________/  _ _  \ _|  \___  \  |  \  |  \  __/\_________\n       __________   \ /   _\_   _ V   _ :   _ :   _ V   __________\n                \____V    /_:___/ ·___/___ \/__   /_·   //\\n               =911=.:___/==.\\___//.===.\\//\\__/\\___//.=\n\n                    · BLOOD_TXT V2.0 (F·D·H VERSION) ·\n\nWell,  nothing special to say about this tool, it''s just a simple txt adder\nfor use with AmiExpress.\nPlace the text to add (named BLD.TXT" in your ''S:'' directory!\nUploading  time/date  can be inserted with %t(ime), %d(ate) in the add-file\n(called BLD.TXT I guess).\n\n              For Bugreports or whatever you can reach my at:\n\n                   BLOODY DECISION 49-2324-54552 (DHST)\n                                   49-2324-22698 (HST)\n\n','\n',char(10)),NULL,'auto-added',2949,1,0,NULL,NULL,'bldtxt20','scan',1780048428);
INSERT INTO door_catalog VALUES('blh_myst','BLH-MYST.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BLH-MYST.LHA',NULL,'XIM','__________   __  ___.   __   ____.',NULL,'MARKY/BACKLASH','BLH','\      _  \_ \/ /   |   \/  /    |__  [MY] \//___|   /   //   |___   // ___|  \ _// \__   /\__//  __/   \_//  \____  \',replace('__________   __  ___.   __   ____.       \n\      _  \_ \/ /   |   \/  /    |__  [MY]\n \//___|   /   //   |___   // ___|  \    \n_// \__   /\__//  __/   \_//  \____  \ \n\_ _________/\___________\_______|    \_\n<=Y====[ BACKLASH PRESENTS ]=/________ /===>\n  !                                   Y\n  : MY-STATUS! V2.0 by MARKY/BACKLASH :\n  .              /X D-SIGN            .\n  `-----------------------------------''\n','\n',char(10)),'MY-STATUS.doc',replace('                        .                                    \n__________________      : _ ____. /\    ___.  ______   ____________. \n\      _  \_   .  \/\___|__     |/  \  /   | /   .  \_/   _    /   |__\n \//___|   / __|_ \\   ___/_____/    \//   |_____|_ \\_____\  /\___|  \\n_// \__   /\_\____ \\  \      \_    \//  __/   \____ \\   | \/  /\___  \\n\___________/__|    \\_________/     \__________\|    \\_____  /___|    \_\n    [MY]      |_______/        \______\         |_______/    \/  |_______/\n                                                                   \n             /X-D-SIGN presents MY STATUS V2.0 By MARKY/BLH\n\n                          Copyright ©1995 Marky\n\n                            Registered Version\n                         Please don`t modify the\n                         File in any way without\n                                Permission.\n\n\n\n\nArchive (BLH-STMY.LHA) contents\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nMY-STATUS.rexx           4912 bytes     The all-processors version.\nMY-STATUS.doc            8716 bytes     This document file!\n\n\n\n\nDescription\n~~~~~~~~~~~\nMY STATUS is an /X door, which gives you some information about the User.\nI made it in 20 mins of hard work, after my HD crashed and I lost my\nfavorite one. I decided to create one by myself...well thats it ...\n\n\n\nFeatures\n~~~~~~~~\n- clear overview ... :)\n\n- Great outlook ...  :)\n\n- pure arexx code ... :)\n\n\n\n\nRequirements\n~~~~~~~~~~~~\nWorks on all Amigas and /X-Clones.\n\n\n\n\nInstallation\n~~~~~~~~~~~~\nJust copy the MY-STATUS dir to your doors: and edit your bbs:commands like\nthat:\n\n--------------------------------------------\n*S        XM020Doors:MY-STATUS/MY-STATUS.rexx\n*ST       XM020Doors:MY-STATUS/MY-STATUS.rexx\n--------------------------------------------\n               ^^^^^^^^^^^^^^^^^^^^^- Path and Filename of this door.\n            ^^^\n ^^^^       Access needed to use this door.\n The command that will invoke WhoHuu.\n\n\n\n\nContact me!\n~~~~~~~~~~~\nIf you wanna report any bugs or just wanna get sum updates just lemme know\n                    and leave mail wherever you noticed me...\n\n\n\n\n\nDisclaimer\n~~~~~~~~~~\nI take no responsibility of any causes or demage made to your system\n                         by using MY Status ! \n\n\n\n\n\nHistory\n~~~~~~~\n1.0  First working version !\n\n1.1  Little Bugfix !\n\n2.0  First public release. Totally new look. More Stats.\n\n\n\nThats it, thank you for using diz one, Marky/Blh !\n\n------------------------------------------------------( end )------------\n','\n',char(10)),NULL,NULL,6043,1,0,NULL,NULL,NULL,'scan',1780048428);
INSERT INTO door_catalog VALUES('blitzx','BLITZX.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BLITZX.LHA','Bulletins','XIM','.------------------------------------------.',NULL,'Genius/flood',NULL,'| Sources for making /X XIM doors in blitz | |------------------------------------------| | To /X door with full sources, and also,  |',replace('.------------------------------------------.\n| Sources for making /X XIM doors in blitz |\n|------------------------------------------|\n| To /X door with full sources, and also,  |\n| A ''clean'' door, you can build on you own |\n`------------------------------------------''\n :          Coded by Genius/flood         :\n `----------------------------------------''\n','\n',char(10)),'Bulletins.doc',replace('\n     _\n   ._)\  _______________________________.\n   |   \/                               |\n   |  .....................             |       f · L · O · o · D\n   |  :          ________ :             |\n   |  :  _______/  _____/_:___________  |          /X division    _____\n  _|__:_/   ___/__ \_        \_  __   \_|____________     ________\_   \\n_/           ____/____________/  \          /   __   \___/   ______/    \\n\_____________/           : \______________/    \       \________________\\n      :                   :..  .........|.\________________/(rLf)/-T   ...\n      :             .....   :  :        |:.    .....                ...:.:\n      :       ......:   :...:..:        | :     :  :...........     :\n    ..:.......:.............:           | :.....:           :.:.....:...\n....:         :                         |____:_______________________:__ _\n:.:           .                          ....:                       :....\n:                                        :.........presents..........::\n:\n:      F L O O D  B U L L E T I N S    v1.0 by Genius/fLD        ©mP!1996\n:          \n:.................................................................. . .\n                                                                           \n\n\n\n                           .:General information:.                         \n\n                         (___                   ___)\n                            /___________________\\n\n\n   Well, let me start by saying that I''m NOT in the mood for at super-doc\n               right now, so it''s gonna be a quickie! sorrie!\n\n\n    It''s a bulletin viewer ... "Well..." you say... "Whats new?!" .. well\n     let me explain.. At my board i use a LOT of bulletins, not just the\n    usual top-this-and-that, but lots of information, cd-lists ect. ect.\n  and my old bulletin just could not handle more.. so, i wante a bullviewer\n  that could have SUB MENUS, understand me right... I wanted a way so when\n   a pressed a speciel item in the bulletins, i got a completely new list\n  of bulletins to select from.. well, i made this fine little door in less\n   than two hours including testing ect. And i am pretty sure it''s bugfree\n   and working perfectly!, take a look at the included screenshots before\n            you install it, so you''ll know what the hell it is..\n\n     Warning... this door, requires a little more work than most others,\n     It took me about 15 minutes to set the door up, to work with all my\n                 bulletins.. but when it''s up... it''s great!\n\n\n\n                                .:Features:.                               \n\n                         (___                   ___)\n                            /___________________\\n\n\n                               "SUB" bulletins\n\n                 Cursor control + manual entering of numbers\n\n                              Changeble design\n\n                                 XIM = speed\n\n                      Cool looking, and smooth designed\n\n                  Full bulletin online-updating supported!\n\n      Bulletins does not have to be Bull4.txt ect. can also be anything\n                 else, even texts not in the bulletins: dir!\n\n                   Easy setup - good overview afterwards!\n\n\n            It''s a Flood production - do we have to say anymore??\n\n\n\n                              .:Installation:.                             \n\n                         (___                   ___)\n                            /___________________\\n\n\n  This is what i meant when i said i was not in the mood for super-docs...\n    You figure out yourself how it works.. it pretty simple, just look at\n                         the included cfg files... \n\n              (remember to use TAB when editing the cfg files!)\n\n\n\n\n\n                            .:Features to come:.                           \n\n                         (___                   ___)\n                            /___________________\\n\n\n                 Your ideas... I''m open for any suggestions!\n\n\n\n\n\n\n                                               ·\n                          .---------------------\-.\n                          |·                     \|\n                          :                       \ \n                          |                       |\\n                          :      .:gREETS:.       :~\n                         _|        ______         |\n                         \:                       :\n                          \                       |\n                          :\                     ,:\n                          `/----------------------''\n                          ·                        \n\n             CoOL /X cOdERS:.          mENACE · Chrome · Jawlog\n\n             CoOL sYSdEViLS:.          Hellride · Cybersoul \n                                       Chevy · 2PAC · Seahawk  ect.\n\n         sPECiAL tHANX 2 aLL tHE pEOPLE, wHO wAS bETATESTERS 4 mE!!!\n\n             CoOL aLLRoUND gURU''s:.    mELOMANiAC · sUNDOWN\n\n\n\n\n                      sPECiAL yOHO 2 aLL fLOoD mEMBERS\n                      ________________________________\n\n\n\n\n\n                              - gENiUS / fLOOD\n\n\n\n\n\n                           .: How to contact me :.\n\n                         (___                   ___)\n                            /___________________\\n\n\n                                                                           \n                                 .-----------.                             \n                 .--^------------|\  _____  /|-----^^--------.             \n                 | tWiLiGHT dkhq | \ \ ! / / : pLAZTiQUE whq |             \n                 |______________ |  \ \_/ /  : ______________|             \n                 |\_____       ·)| `_\___/_'' |(·      ______/|             \n                 | ¯\         // | (_\`-''/_) : \\         /¯ |             \n                 |   \____   ((__|  ¯¯| .¯¯  |__))  _____/   |             \n                 |·   ¯\___    --|  . : :    |--   ____/¯    |             \n                 |:.    ¯\_      `(_  `^'' __)''      _/¯      |_            \n                 |:::.    \____   /|      ¯:\    ___/        |/            \n                 |:::::.   ¯¯\_  _)|__·_.__|(_   _/¯         /             \n                 |:::::::.    `--'' || : | || `---''     ·©mP!·|             \n                 :­­­­­­­­­­­­­­­­­``-''-''-''''­­­­­­­­­­­­­­­­­:             \n                 |._________________________________________.|             \n                 ||__ _____|  |  .  |  ____  _  )  ______|  ||             \n                 ||  \  |  \  |  |  |  --''|  _  |  |  |  \  ||             \n                 |`-----''-----''--`--''-----''--\__|-----''-----''|             \n                 |   |¯¯|_____________  _________________|¯¯||             \n                _| __|_ |  ____  .  | \/  _____ |  _  )  |  ||             \n                \|| __/ |  --''|  |  |   / |  _/ |  _  |    -:|             \n                 \`-----''-----''--`--''-\/--''-----''--\__|--^--''|             \n                 |·.---------------------------------------. :             \n                 `-| nO nUP - 7RADERS cALL +45-3990-2992 ! |-''             \n                   `---------------------------------------''               \n\n               Well, this is the quickest way.. call my board!\n\n       If you don''t want to do THAT.. well, you can mail me at one of\n                               there adresses:\n\n\n                        Email......... not availble!\n\n                        Fidonet....... 2:236/112.5\n\n                        Amiganet...... 39:141/145.5\n\n                        HOAnet........ 10:1/26.5\n\n                        Scenenet...... 245:3/0.5\n\n\n               Or leave a messy at one of FLOODs danish sites!\n\n\n','\n',char(10)),NULL,NULL,42044,1,0,NULL,NULL,NULL,'scan',1780048428);
INSERT INTO door_catalog VALUES('bondosv9','BONDOSV9.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BONDOSV9.LHA','DOS','XIM','DOS',NULL,NULL,NULL,'V (_) /| \|: :|  \ \ Ya Face !_ V /.| \\| ||/\/. \ With... (_)!/ || //| ||\ ||__  BONEHEADs''...',replace('_) _   /\ .   ./\|\ Hammers\nV (_) /| \|: :|  \ \ Ya Face\n!_ V /.| \\| ||/\/. \ With...\n(_)!/ || //| ||\ ||__  BONEHEADs''...\n:V / _|| \\| || \||~~ DOS ShELL v1.9k\n.!/ __ | // × |\ \: /   w/TOOL-ED\n / / | | /| ~ |/ / /  (ICON Editor)\n~~~  ~\|/ .\_/.\/|/ Brand new UPdated\n       :Døk      :  version w/improved\ninterface. The Kleanest Shell around!!','\n',char(10)),'BoneSHELL.Guide',replace('@database ABUSE BONEHEADSHELL\n@Author BµSH DøKTøR\n@Index Documentation\n\nCopyright © 1994 BONEHeAD / ABUSE\n\n@Remark $VER: BONEHEADSHELL v 1.9k by Bonehead / /.BUSE\n@Remark AmigaGuide database\n\n@node MAIN "BONEHEADSHELL Documentation © 1994 Bonehead//.BUSE"\n           .\n          /|.           /\\n         / ||\  . .    /./    PRESENTS!  :\n        /  || \/| |\  / |\\n       / : ||  \| | \/ /| \      BONEHeAD''s DOS SHELL w/ TOOL-ED!\n      / /| ||:\ \ | / / |  \\n     / / | || / / | \ \ | \ \             Version 1.9 K\n    / /  | || \ \ | |\ \| |\_\\n   / /___| ||:/ / | | \ | |_.           Coded by BONEHeAD\n  /  ____  ||  /| | | / | __|\n /    / |  || / ~~~ |/ /| | __         For /X 3.xx and UP!\n/____/  |  ||/:\___// / | |/ /\n:       |  |: . Døk/ /  | / /       DOX typed by the BµSH DøKTøR\n        :\ |       \/   |  /\n          \|            | /\n           :            |/ @{" Normal Documentation " Link Documentation}\n                        :\n@endnode\n@node Documentation "BONEHEAD SHELL Documentation"\n           .\n          /|.           /\\n         / ||\  . .    /./      @{" D e s c r i p t i o n " Link Description}\n        /  || \/| |\  / |\\n       / : ||  \| | \/ /| \     @{" I n s t a l l a t i o n " Link Installation}\n      / /| ||:\ \ | / / |  \\n     / / | || / / | \ \ | \ \   @{" T o o l t y p e s " Link Tooltypes} \n    / /  | || \ \ | |\ \| |\_\\n   / /___| ||:/ / | | \ | |_.   @{" G r e e t i n g s " Link Greetings}\n  /  ____  ||  /| | | / | __|\n /    / |  || / ~~~ |/ /| | __  @{" C o n t a c t s " Link Contacts}\n/____/  |  ||/:\___// / | |/ /\n:       |  |: . Døk/ /  | / /\n        :\ |       \/   |  /\n          \|            | /\n           :            |/\n                        :\n@endnode\n@node Description "BONEHEAD SHELL Description"\nBONEHEAD SHELL has been coded by BONEHEAD / /.BUSE!\n\n    Description - Are you sick of these bullshit Shell utilities\n                  for REMOTE sysop work on /X ? Want to edit a ICON?\n                  Paranoid & afraid of getting your''re bbs hacked?\n\n        Enter...  BONEHEAD SHELL.  Quick, easy, PW protected,\n                  Edit ICONS, more...\n\n This basically sets the SHELL up so only Sysops / Co-Sysops can access\nthe remote shell of the BBS. You can also, remotely edit bbs ICONS. Kool!\n\n How Does it Work ?\n \n Easy= JUST LIKE YOUR OLD SHELL ...It does Everything Possible.\n       The only diffrence is when you UPLOAD / DOWNLOAD you Must\n       type the Complete PATH and Filename.\n  \n        Example Upload = Upload BBS:commands/bbscmd/( The file/s you send\n                                                      will be placed in\n                                                      the BBSCMD dir. )\n\n        Example Download = Download BBS:DOORS/YAMAMA.TXT\n                                                (This will Download\n                                                  YAMAMA.txt)\n  \n  \n                 [ Simple Egh - Well Thats The IDEA ]\n\nTo EDIT a ICON remotely, just type  TOOL-ED {path for Icon} {no .info needed}\n\n        Example = TOOL-ED DH0:BBS/access/ACS.255.info\n\n   There are no Fuckin Backdoors and NO ONE but Levels 255 can access!\n PLUS! No one can format your hard drive... the command is coded out. It''s\n also password protected, (of course).\n -------------------------------------------------------------------------\n\n\n\nContents of archive:\n===================\n\n\n            BONESHELL.Guide\n            BONESHELL.Guide.info\n            DOS\n            DOS.info\n            DOS.HLP\n\n\n===================\n\n      @{" Main Menu " Link Documentation}\n\n@endnode\n@node Installation "BONEHEAD SHELL Installation"\n\n     INSTALLATION =\n\n  Copy these into place...\n\n DOS.info to...\n\n  BBS/Commands/\n        BBSCmd/\n            DOS.info\n\n And the rest to...(you should make a DIR in DOORS called SHELL)\n\n      Doors/\n          SHELL/\n              DOS\n              DOS.HLP\n              BONESHELL.Guide\n              BONESHELL.GUIDE.info\n\n    Edit the DOS.info icon and put in your password... \n    Then just go over to the main prompt and type  '' DOS ''\n    Here are the commands...\n\n        EXIT = TO EXIT THE DOS SHELL.\n        UP   = TO  UPLOAD A FILE TO THE SYSTEM (INCLUDE PATH)\n        DOWN = TO DOWNLOAD A FILE FROM THE SYSTEM (INCLUDE PATH/FILE_NAME)\n        TOOL-ED = CHANGE / ADD TOOL TYPES ON SYSTEM ICONS \n        <dos commands> most all CLI command \n        HELP = GETS YOU THE COMMANDS\n \n    This new version works best with the ibm font.\n\n    You are now in a Honest to good TRUE 100% Working Shell ..\n  With no fuckin This and Thats .......\n\n    Thanks to Bonehead we can have easier things to use like this .\n\n\n      @{" Main Menu " Link Documentation}\n\n@endnode\n@node Tooltypes "BONEHEAD SHELL Tooltypes"\nYou can insert the following tooltypes in the icons in\nBBS:Commands/BBSCmd/DOS\n\n===========\n\nLOCATION=Doors:SHELL/DOS           - Location of the Door\nSTACK=10000                        - Stack of the Door\nPRIORITY=2                         - Priority of the Door\nPASSWORD=22254                     - Password for the Door\nMULTINODE=YES\nACCESS=255\nTYPE=XIM\n\n===========\n\n      @{" Main Menu " Link Documentation}\n\n@endnode\n@node Greetings "BONEHEAD SHELL Greetings"\n\n   GREETs GoINg OuT To All oUR ElIte HoMMies In The Scene !\n\n       CARDINAL ..     SHaDOWREAPER      Frantic- Abuse leader in jail now!\n\n       ACOMA           Del & KickFace    Pack Rat / Devil''s Den\n\n       ENERGY          KrOnIOn           BµSH DøKTøR\n\n       /\/orske        Gazzer            White Knight\n\n       The Legend / R/\D/\R ( We miss ya Rich )\n\n          And all The Rest of You Modem Whore''s !\n           -----------------------------------\n\n             DOX typed up by the BµSH DøKTøR\n\n\n      From Bonehead\n  \n    Hope ya like this new version. It runs quicker with some\n  improvements on the interface.  \n\n      @{" Main Menu " Link Documentation}\n\n@endnode\n@node Contacts "BONEHEAD SHELL Contacts"\nBONEHEAD SHELL has been coded by BONEHEAD / /.BUSE!\n      /\   ____  __          .\n     /  \  \  / / //\  /\   /^\   Call NOW!\n    / /\ \ / / / //  \/  \ /   \\n   / /  \// /_/ // /\ \/\ \  /\_\ Sysop: /\/\IX/\/\ASTER\n  / /    / __  // /__\ \ \ \/___\n / /    / / / // ______ \ \ \__ \     .   If ya don''t know the number, ASK!\n/ /    / / / // /  \ \/ / / /  \ \   /|.           /\\n\ \   / / / // /    \/ / / /.  / /  / ||\  . .    /./\n \ \ / /__\/ \ \    / /\/ / |\/ /  /  || \/| |\  / |\\n  \ \\// /    \/    \/\  /  |  /  / : ||  \| | \/ /| \\n   \ \/ /              \/Døk| /  / /| ||:\ \ | / / |  \\n    \  /    ______ ____     |/  / / | || / / | \ \ | \ \\n     \/     \  __ \\  _\    :  / /  | || \ \ | |\ \| |\_\\n             \ \ \ \\ \_      / /___| ||:/ / | | \ | |_.\n              \ \ \ \\  \    /  ____  ||  /| | | / | __|\n               \ \/  \\ \   /    / |  || / ~~~ |/ /| | __\n                \____/ \/  /____/  |  ||/:\___// / | |/ /\n                           :       |  |: .    / /  | / /\n                                   :\ |       \/   |  /\n                                     \|            | /\n                                      :            |/\n          @{" Main Menu " Link Documentation}      :\n\n@endnode\n','\n',char(10)),'{"LOCATION":"Doors:SHELL/DOS","STACK":"10000","PRIORITY":"2","ACCESS":"255","TYPE":"XIM"}','auto-added',21570,4,0,NULL,NULL,'bondosv9','scan',1780048428);
INSERT INTO door_catalog VALUES('boss','BOSS.LZX','~/Code/amiexpress_doors/Archives/AmiExpress/BOSS.LZX',NULL,'XIM','boss',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,70436,0,0,NULL,NULL,NULL,'scan',1780048428);
INSERT INTO door_catalog VALUES('bossnuke','BOSSNUKE.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BOSSNUKE.LHA','BossNuke','XIM','BossNuke','1.00','Big-Boss.',NULL,NULL,replace('Boss-Nuke V1.00 by Big-Boss.\n','\n',char(10)),'bossnuke.doc',replace('\n                              Boss-Nuke Docs \n                         BoSS-NuKE v1.0 written by\n                                 Big Boss\n                                 \nWelcome to ''BossNuke'' - the world''s fastest nuker!  \n\nFeatures:\n -Full CONFERENCE ACCOUNTING support for /X 3.x users!\n -Finds uploaders in less than 2 seconds!\n -Stackable command line options!\n -Up to 20 filenames at once!\n -''Speed'' award and destroy modes for FAST hassle free operation!\n -Create files to prevent them being uploaded!\n -Configuration file to allow configurable set-up!\n -Can be set up to RESTRICT files rather than DELETE them in config file.\n -Password file can be set up for better security.\n -Online detailed docs to help those ''slow-to-learn'' cosysops ;-)\n -Built for Speeeeed!\n -Now Sigma Seven!''s Dupe File Checker code installed in the Ulog.x section!\n \n\nInstallation:\n \nInstalling this is somewhat simple.  Just copy the files to the paths suggested\nand all should go well.  \nThe archive contains the following files:\n  BossNuke.x              \n  BossNuke.prefs\n  BossNuke.pw\n  Ulog.x      <----- /X 2.34 or higher /X needed to run this file.\n  BossNuke.doc\nCopy BossNuke.x to doors:nuke/ (or path to where you want nuker to go).\nCopy BossNuke.prefs to s:\nIF you want to have users enter a password BEFORE entering nuke door, copy\n  BossNuke.pw to s: - otherwise copy to doors:nuke/ for storage for future.\nCopy Ulog.x to doors:nuke/\nCopy BossNuke.doc to where ever you want!\n\nMake sure that you have the UDLOG options turned on in your AmiExpress \n  configuration.  Without this it will not find downloaders.  May not find\n  uploaders either depending on if you have ulog.x installed or not!\n\nFor AmiExpress 3.x:   2 icons are included in the archive.  One is nuke.info\n  and the other is FILECHECK.info.  Edit the nuke.info and set the correct\n  path to the BossNuke file.  Then copy this to ''doors:commands/bbscmd/''\n \n  The other icon is called FILECHECK.info.  This icon must be not be\n  renamed!  Move this to the ''bbs:commands/syscmd/'' directory.  Edit the \n  path to make sure it is to where you copied the ulog.x file to.\n\nFor AmiExpress 2.x:  Edit the bbs:commands/bbs.cmd file and add to it:\n*nuke        XS200doors:nuke/BossNuke.x\nNext Edit bbs:commands/sys.cmd file and add to it:\nFILECHECK    XM001doors:nuke/ulog.x\n(name of the sys.cmd entry MUST be ''FILECHECK'' or it will not be run at the\n correct time!)\n\nMake sure you have the file ''paths'' in each conference on your bbs that\n  contains the full download paths with no spaces after them a carriage\n  return after the last entry (standard set up of the paths file).\n\nNow it is time to edit the BossNuke.prefs file in the s: directory.\n  Included with the archive is a ''default'' example of a prefs file.  Let''s look\n  at this file:\n  \nConference_Accounting=N\nFile_Restriction=N\nSize=>LAME< \nSize=>DUPE< \nSize=>FAKE< \nSize=RENAMED\nSize= >OLD< \nSize=CORRUPT\nSize=OFFLINE\nSize=FOREIGN\nSize=>INTRO<\nSize=>MUSIC<\nComment=2x Credits Given!\nComment=3x Credits Given!\nComment=User Deleted!\nComment=Credits Taken!\nComment=Comment5\nComment=Comment6\nComment=Comment7\nComment=Comment8\nComment=Comment9\nComment=Comment10\n\nThese must be in this same order. \nLine 1: Conference_Accounting=N   \n	Conference_Accounting=Y\n 	-Y turns on the conference accounting options.. to be used only with\n         amiexpress 3.0 or higher when the conference_accounting is turned\n    	 on inside the access icons.\n    	 \nLine 2: File_Restriction=N\n	File_Restriction=Y\n	-This turns on or off the File Deletion or File Restriction routine.\n	 If ''Y'' is selected, then BossNuke will RESTRICT the nuked files from   	\n	 being downloaded, but will not delete them when the delete file\n	 option is selected in the nuke door.  If ''N'' is selected, then the\n	 file will be deleted and replaced with a 40 byte file saying \n	 ''Nuked by BossNuke'' or something like that..\n	 \nLine 3: Size=>LAME< \n	This is the 7 character or less byte size comments to be used.\nLine 4-12 are same as line 3 and must be included!\nLine 13: First of 10 File Descriptions to be entered under the nuked files.\n         Only 54 Characters will be included.\nLines 14-22 are rest of required file descriptions.\nLine 23: DupeCheck=Y\n	 DupeCheck=N\n         This turns on or off Sigma Seven!''s Dupefilechecker that checks for\n         duplicate files in the upload directory after each upload.  If a \n         duplicate file is found then the upload is moved to the hold.\n         \nOnce all this is done, the Installation is complete.  \n\nNote:  The Ulog.x file is optional but HIGHLY recommended!\n       This marks an upload each time it''s sent up.  It will create a \n       series of files with the format of ''ulog.[node#]'' in each conference.\n       These files will NEVER exceed 3200 bytes each.  They will make the \n       search for the uploaders become almost INSTANTANEOUS.  Without these,\n       ''BossNuke'' must search the UDLOGS which is not as fast.  However, even\n       using the UDLOG to search the uploader, it still is rather quick.\n       There will be one file per node per conference created.\n       \n       I have added Sigma Seven!''s Duplicate Filechecker routines to this\n       aswell!  You can turn it on or off in the BossNuke.prefs file as\n       shown above.  This will scan the file uploaded against all your dirx\n       files and if there exists a duplicate, then the upload is moved to \n       the sysop''s hold.  A great routine now that Bytemaster is not planning\n       to include this option in /X.  \n\n       \nPassWord File:\n If you want a password to be required to enter the door you must copy the\n file ''bossnuke.pw'' to the s: directory.  The format of this file is like so:\n Line1: Number of entries (users that will have passwords).\n Line2: First entry  format: NAME,PASSWORD\n If you have the file BOSSNUKE.PW in s: then no one not listed in this file\n can enter BOSSNUKE.  So, if you do NOT want to enter pw''s to use the door,\n do NOT put this file in the s: directory!  You can use the example file\n included in this archive to understand the exact format of this file.\n\n\n\n\nOperation:\n\nBossNuke has a thorough built in help screen.  Just type ''nuke -h'' and you\n  will see the online docs.  They are pretty thorough but we shall explain\n  some of the features here aswell.\n\nEasiest way to use this is to type ''nuke'' and to follow the instructions on\n  the screen.  It will allow you to enter up to 20 files at one time.\n \nStackable Commands:\n  You can enter the filename(s) on the amiexpress command line aswell like:\n  ''Nuke Filename''  or ''nuke filename1 filename2 filename3''\n  Doing this will bypass the prompt to enter files inside the door and \n  immediately being the nuking process.\n\nCreating Files to prevent fakes uploaded:\n  Enter ''-c'' as your first filename.  ''nuke -c'' or type nuke, and when asked\n  for the first filename enter ''-c''.  Then it will ask you the filenames to\n  create.  These files will be skipped when attempted to be uploaded.\n  \nSpeed Destroy Mode:\n  Speed Mode is a great feature.  It allows you to nuke a series of files \n  all automatically without any further interaction with the nuker.\n  Type ''nuke filename1 filename2 filename3 [times credits to take]'' example:\n  ''nuke dw-ship1.zip dw-ship2.zip 2'' \n  The above example will take 2x credits.  \n  Speed mode will do the following:\n  -Nuke files and delete them.\n  -Search uploader.\n  -Take credits stated on command line and save the user''s account.\n  -Send Msg to user.\n  -Update File directory with BYTE comment #1.\n  -Go to next file.\n  Speed mode will NOT return credits to dlers or use an extended description.\n  \nSpeed Award Mode:\n  This is identical to Speed Destroy Mode except it is award the uploader for\n  an excellent upload rather than nuke credits.  Speed Award Mode will do the \n  same as destroy mode except it will not delete the file and it will not \n  update the file directory.  Award mode is entered by specifying a negative\n  number for the [times credits].  Example:\n  ''nuke filename1 filename2 -2'' gives 2x additional credits to the user that\n  uploaded the file.\n  \n  Both speed modes can nuke up to 10 files in less than 1 minute including \n  all msg''s sent and all directories updated etc..  really handy if you are\n  in a hurry.\n  \nThe rest of this should be pretty much self evident.  If you have any questions\nI can be reached on the AmiExpress support bbs or Mirage if you can manage an\naccount there.  Remember to type ''nuke -h'' for online help.  Good luck and\nsuggestions are welcome to improve this utility!\n\nBig Boss\n\nPS:  Look to version 2.0 to be released soon with many more features\n     and ease options!\n\n***  -A very special THANX to Kidlat & /\kir/\ for their help and feedback!\n       Your input was invaluable!!!!\n     -Thanx also to RAZOR BLADE for the name ''BossNuke'' ;-)\n     -Thanks to Sigma Seven! for his awesome Duplicate File Checker!\n\n\n\n','\n',char(10)),NULL,'auto-added',33658,2,1,'nuke','Doors/Bossnuke','bossnuke_2','scan',1780048428);
INSERT INTO door_catalog VALUES('bosstop','BOSSTOP.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BOSSTOP.LHA','bosstop','XIM','bosstop',NULL,NULL,NULL,'___________ __________|   |_______ |   | \_ ___    / ____ \    |   |\____  \_   |___ |  _/  _/.    /  \____  _|   _    |   |',replace('                      .___.        .___.\n___________ __________|   |_______ |   |\n\_ ___    / ____ \    |   |\____  \_   |___\n |  _/  _/.    /  \____  _|   _    |   |\n |__\     |_______/   /  \_________|__ `\n ----\____|------/________\[pRESENTS!]\____\n \n \n BossTop V1.0 Weekly\n','\n',char(10)),'Spacid.doc','FORM',NULL,'auto-added',30615,5,0,NULL,NULL,'bosstop','scan',1780048428);
INSERT INTO door_catalog VALUES('bp__pag9','BP!-PAG9.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BP!-PAG9.LHA',NULL,'XIM','_____                     __,',NULL,NULL,'BP!','|____   ___) ____||____ ___    (____  ___ l____)||   \(____||   /(___)(_______)(__/_ _____          /              __,',replace('       _____                     __,       \n |____   ___) ____||____ ___    (____  ___ \n l____)||   \(____||   /(___)(_______)(__/_\n       _____          /              __,   \n   ____  ___) ___ ____ ___  __, |___(____  \n  |____)|   \(___)   /(__/_(____l________)\n«-|-------------- (_/ -----------------Mo!-»\n    [bIRDHOUSE^pROJECTS!][rELEASED^2dAY]\n             * OPERATOR PAGER *\nFEATURES: ABLE TO BUILD IN SELF-MADE ANSIS!!\n«-------------------------[CHECKITOUT!]----»\n','\n',char(10)),'BP!-Pager.Guide',replace('@DATABASE\n@Remark $VER: VERSION 0.9 [BETA-RELEASE] (FEB 16 1995 13:35:56)\n@Remark AmigaGuide DataBase for bP-pAGER v0.9ß\n\n@Node MAIN "bP-pAGER v0.9ß - [BETA-RELEASE] for AMiEXPRESS 3.37 - 4.xx"\n\n                   |__ . __  __||__  __      __  __          \n                 .-|__)|l  ''(__||  )(__)l__|`--.l_/_--------.\n                 |                           ¯¯             |\n                 |  __  __  __ . __  __ |_   __             |\n                 `-|__)l  ''(__)|l_/_(__,l__,`--.-------÷2F÷-''\n                   |        .__|             ¯¯\n\n              «««  pETE! oF bIRDHOUSE pROJECTS! /X cREATIONS  »»»\n \n                           pRESENTS: bP-pAGER v0.9ß\n\n                     @{"             Introduction!            " LINK Introduction}\n                     @{"             Installation!            " LINK Installation}\n                     @{"                Credits!              " LINK Credits}\n                     @{"               Greetings!             " LINK Greetings}\n@ENDNODE\n@NODE Introduction "BP-PAGER Introduction"\n\n                              ABOUT BP-PAGER\n                            ------------------\n\nBP-PAGER v0.9ß is a small Pager, which had the functions i was interested in.\nBP-PAGER is a  AiM Module for AmiEXPRESS written in AReXX.\n\nMany Times i would like to have a pager in which you can edit your\nCHAT TEXT for yourself.\n\nFeatures: You can edit your own CHAT - TEXT\n          In the Config - File you can see all the Chat-Reasons\n\nAll what you need is any Model of the great AMIGA, OS2.x or higher.\nRegistered (or not) Version of AmiExpress 3.37 - 4.xx.\nAssigned Doors:\nThats all... have Fun with this little Door.\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Installation "BP-PAGER Installation"\n\nCopy the complete BP-PAGER Directory to your Doors.\n\nThen Copy the O.Info to your BBS:COMMANDS/BBSCMD/ .\nNow you only have to edit DOORS:BP-pager/pager.txt for your own \nChat-Text Style!.\n\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Credits "Credits"\n\n                                 CREDITS\n                               ----------- \n\n   BP-PAGER v0.9ß was written by pETE!/bIRDHOUSE pROJECTS /X-cREATIONS\n\n   The AmigaGuide was written by pETE!/bIRDHOUSE pROJECTS /X-cREATIONS\n\nMUSICAL SUPPORT: dOG eAT dOG [·] rÖDELHEIM hARTREIM pROJEKT [·]  gREEN dAY \n                  pENNYWISE  [·]        bAD rELIGION        [·] bEASTI bOYS\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Greetings "GREETINGS"\n\n                               SOME GREETINGS\n                          -----------------------\n                           TO THE FOLLOWING GUYS\n\n   [·] pRIMUS!/bP/hBY [·] pANACEA/bP [·] -sLIME!/bP/mTH [·] rAZFAZ/bP [·]\n    [·] lUZIFER/bP/hBY [·] rOADRUNNER [·] lORD vIGO/bP [·] aLPHA oNE/bP [·]\n      [·] hUNKPAPA/bP/fTC [·] tAZ dEVIL [·] rASTA [·] mONTY/bP/iLS [·]\n                [·] mOGUE!/pIMOK/aRT-cORE [·] sAK/bP/fTC [·] \n\n                   aND tO aLL oTHER bIRDHOUSE pROJECTS mEMBERS\n                   aND tO aLL tHE oRGANISED cRIME pROJECT´lers\n                         ... and to all i forgot ...\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n','\n',char(10)),NULL,NULL,6508,1,0,NULL,NULL,NULL,'scan',1780048428);
INSERT INTO door_catalog VALUES('br_ib20','BR&IB20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BR&IB20.LHA',NULL,'XIM','BugReporter&IdeaBank 2.0, ARexx Tool for',NULL,NULL,NULL,'_______  ______  _  ___  _______________ /___  __\/ ___/ \/ \/ _ \/ ___/ _/___  __\ \/\/ /\_/ __//     / ___/ __/\_ \\/ / /\_/\',replace('BugReporter&IdeaBank 2.0, ARexx Tool for    \n _______  ______  _  ___  _______________   \n/___  __\/ ___/ \/ \/ _ \/ ___/ _/___  __\  \n\/\/ /\_/ __//     / ___/ __/\_ \\/ / /\_/\ \n \/_/ //___//_/\/\/_/\_/___/\___/\\/_/ /\\/ \n  \_\/ \___\\_\_\_\_\/ \___\/\__\/ \_\/BBS  \nWith Upload-,Download-Function, MSG-Editor, \nOnline-Help, Multinode and Logfile, Stats,  \nlanguage detect and selfinstalling all files\n- Binary uploadcheck                        \n- Extra SysopStats Tool                     \nIncludes German and English Doc.            \n','\n',char(10)),'CN-BugReporter.doc',replace('\n                      _____\n                     /      __  _ _   __  __    __  _  __  ____\n                     \     /  _/  \  /   /     /   /  /   / __\n                   ___\   /        \    / __  /   /      / __\n                  /      /  \      /   /     /   /  \   /\n______________________________________________________________________________\n\n     BugReporter, © 1994 by Casa Nova, Sysop of Skyline BBS Berlin.\n     Written for /T\empest BBS v3.15 or higher Versions. Started: 02-12-94\n______________________________________________________________________________\n\n; $VER: BugReporter Doc 1.9 (12.09.94) © by Casa Nova, Sysop of Skyline BBS Berlin\n; Skyline BBS Berlin is a registered Tempest BBS Suite.\n\nThis archive includes:\n----------------------\n\n  CN-BugReport.rexx                  (the ARexx Tool)\n  CN-BugReport.rx                    (Optimized for faster execution)\n  CN-BugReporterStats.rexx           (the ARexx Stats Tool)\n  CN-BugReporterStats.rx             (Optimized for faster execution)\n  CN-BugReporter.doc                 (this document)\n  CN-BugReporter.dok                 (the german document)\n  TEXT/Deutsch/Menu-BugReporterIdeas (the Menu for the Ideen-Bank)\n  TEXT/Deutsch/Menu-BugReporterBugs  (the Menu for the Bug-Reporter)\n  TEXT/Deutsch/Help-BugReporter      (the Help Textfile for both)\n\n\nWhat is does:\n-------------\n\nThe BugReporter was written for all *registered* Tempest BBS Sysops.\n\nThe  BugReporter/IdeaBank  allows  you  to sample, read, download or upload\nIdeas or Bugs for future /T\empest Versions.\n\nWhen  uploading  an  Idea  than be sure you upload ONE (Text-)File for EACH\nIdea.   It  does  handle  batch-uploads correct.  Each uploaded (Text-)File\nwill be one Entry in the Idea-List.\n\nWhen reading the IdeaBank the last entry is displayed at first.\n\nIf  started  first  time  and  a  Bug  or  Idea  is  entered,  it creates a\nsubdirectory  in  your  DOORS:  directory called:  "BugReporter".  You will\nfound all needed files in here.\n\nExample-Screen:\n---------------\n\n Skyline BBS  BugReporter 1.9                  Designed by Casa Nova [09-12-94]\n_______________________________________________________________________________\n\n SYSOP ACCESS!: Casa Nova\n\n                              Idea-Bank Menu\n\n  [E]nter Idea                           [C]hange to Bug-Reporter\n  [R]ead Idea-Bank                       [H]elp with Idea-Bank\n  [D]ownload the complete Idea-Bank      [S]tats\n  [U]pload Idea (single/batch)           [Q]uit\n\nIdeaBank Menu [E/R/D/U/H/C/S/Q]:\n\n\nHow to Install:\n---------------\n\n(For installing an Update, just replace the old with the new Tool.)\n\n1. Since version 1.8 there are some needed Text-Files if the used language is\n   not the default "English". In this archive there are some examples for the\n   german (Deutsch) language. Copy them to your BBS:TEXT/"LANGUAGE"/. \n   Textfiles for other Languages you have to create yourself.\n\n                  "Menu-BugReporterIdeas" (The Menu for the Idea-Bank)\n                  "Menu-BugReporterBugs"  (The Menu for the BugReporter)\n                  "Help-BugReporter"      (The Help-File for both)\n\n   Thoose german examples are for the directory ''BBS:TEXT/Deutsch/''. \n\n\n2. Insert to your your Doors.opt the following line:\n\n             [*,*,*,*,*] = BR |REXX|TempRexx:CN-BugReport.rx\n\n3. Start this Tool from your Tempest-Node. Now it creates the needed Files and\n   the directory: "BugReporter" in the defined path for "Doors:".\n\n\nThats it.\n\n\nFeatures:\n---------\n\n- Autodetect your BBS-Name (shown on screen).\n- Versionsstring included ("c:version").\n- Logbook\n- Hotkeys\n- Upload & Download of Bugs/Ideas\n- Online-Help\n- MultiNode\n- Language autodetect\n- Internal & External Stats\n- Selfinstalling for the needed Files and dir.\n\nFuture:\n-------\n\n- Checking uploaded Files (when binary code is incl. no adding to the List)\n\n\nHistory:\n--------\n\nV1.0 / 02-17-94 - Started for internal use.\n\nV1.1 / 02-23-94 - Found a little bug with the Username when shown on screen.\n\nV1.2 / 02-26-94 - No blank line at the 1. position when displaying the Bugs\n                  or Ideas on screen. Editor now handles 99 lines (before 50)\n                  Better displaying/handle when reading Bugs/Ideas. (removed\n                  More/Pause prompts)\n                  When editing BUGs/Ideas on more than 1 node at the same time,\n                  it was confuseing before and the Messages crashed.\n                  Fixed: Now it detects the Node-Number.\n                  Changed the displaying: Now the last Entry will displayed at\n                  first. Versionsstring included ("c:version"). Found that\n                  when german language was used, the "J" was not handled\n                  correct. Included "Upload" for Bug(s) or Idea(s) (single or\n                  batch) The [H]elp-File is now included (german and english).\n                  Creating BugReporter.log when started first and writes all\n                  Upload/Edit activities to this logfile:\n\n                  Example:\n                  ------------------------------------------------------------\n                   Date         Time    Node Name        Action Type\n\n                  [02-26-94] [12:40:14] [1] Casa Nova - Upload #1: Bugs\n                  [02-26-94] [12:43:14] [5] Casa Nova - Entered: Ideas\n                  ------------------------------------------------------------\n\nV1.3 / 03-02-94 - Removed a little bug when started first and creating the\n                  directory "BugReporter" in the DOORS: assignment. Speed it up\n                  when batch-upload is used. Added the # of UL to the Logbook &\n                  Msg-Header. First release for public use.\n\nV1.4 / 03-11-94 - The Location in the message header was limited to 13 chars,\n                  now done to 30 chars.Found a bug when a Sysops changed an old\n                  version to a newer version and a User tries to UL or enter a\n                  message. If one file in the BugReporter directory was missed\n                  the tool exited with an error. Fixed: It checks now each file\n                  separate and creates them - if missed - separatly.\n\nV1.5 / 04-16-94 - Included a requested More (Y/ns/n)?: prompt for some Sysops.\n                  So you can stop reading entries of the whole list.\n                  (Thanks to Skeleton and Night Stalker for the idea)\n\n                  Included the NON-STOP reading with ScreenClear after each\n                  Entry.\n                  Also a [Q]uit at the same "More (Y/ns/n)?:"-prompt; but it''s\n                  not displayed. It quits the BugReporter and goes back to the\n                  Doors.\n                  Changed the Exit&About String.\n\nV1.6 / 05-17-94 - Bug removed when displaying/reading: Sometimes it goes into a\n                  Loop that never ended. (Thanks to Skeleton for finding it)\n\nV1.7 / 05-29-94 - Converted all variables to the new Tempest 3.15. \n                  Use this version only with the new version 3.15 or higher!\n                  Remaining Time at the Prompt is disabled in this version.\n\n                  NOTE, the Name of the Tool has changed:\n\n                  OLD:  PN-BugReport.rexx\n                  NEW:  CN-BugReport.rexx\n\nV1.8 / 08-25-94 - Fixed the upload command (i forgot to change variable from\n                  the upload/DONE/ Area to the new PATH 17).\n                  (Thanks to Skeleton for finding it)\n                  Added Language detect (english [default] or german).\n\n                  Autodetect Tempest Version included. Now it breaks if you \n                  try to run this Tool below 3.15. Changed Exit&About String.\n\n                  Now the BugReporter has a new feature: It displays a Stats-\n                  "Window" in the front when it is loaded. The Reason is why I\n                  saw some people running this each time when they call to see\n                  whats new on the Bugs and Ideas.\n                  So the BugReporter displays before the first prompt the Stats\n                  and asks after this to continue.\n                   ___________________________________________________ \n                  |                                                   |\n                  |  ReporterStats    TODAY  TOTAL  LAST BY USER      |\n                  |                                                   |\n                  |  Used...........:    4     73   Casa Nova         |\n                  |  Ideas stored...:    0     21   Amtrac            |\n                  |  Bugs stored....:    2     49   Roi Danton        |\n                  |___________________________________________________|\n\n                  Would you like to...[B]ug-Reporter...[I]dea-Bank or [Q]uit ?:\n\n                  To get the stats the BugReporter is searching at the very\n                  first start of this version your ''BugReporter.log'' and \n                  creates the Stats (BugReporter.data).\n\n                  Note: Some UserNames with a space within are not correct\n                        displayed. It will be correct after the next entry.\n\n                  Language detect included (default is english, included!) and\n                  any others you can add to your BBS:TEXT/"LANGUAGE"/ \n                  directory. Just create them. Included a some new Textfiles: \n                  (german)\n\n                  "Menu-BugReporterIdeas" (The Menu for the Idea-Bank)\n                  "Menu-BugReporterBugs"  (The Menu for the Bug-Reporter)\n                  "Help-BugReporter"      (The Help Text for both)\n\n                  they are all located in the ''BBS:TEXT/Deutsch/'' directory. \n\n                  You will find the german textfiles in this archive. Just \n                  create yours for your language and put them into your \n                  LANGUAGE directory.\n\n                  The [S]tats is not longer for Sysops only, it is included to\n                  the Menus and displays at normal Users the ReporterStats and\n                  for the MainSysop the BugReporter.log file.\n\n                  Added displaying the ReporterStats when leaving the tool.\n\nV1.9 / 09-12-94 - Found little Bug when writing the stats back, the last Used\n                  Username wasn''t write to the stats. Now ist does correcty.\n                  Sometimes the Usernames was written in UPPER CASE letters. \n                  Now Fixed.\n\n                  Optimized the Code and made it faster.\n\n                  If someone tries to install the last version at the first \n                  time the BugReporter failed. Now fixed.\n                  (Thanks to Skeleton and Roi Danton for the info)\n\nV2.0 / 10-12-94 - Added a new Stats-Tool for Sysops. It''s an extra ARexx-Tool\n                  (BugReporterStats.rexx) that displays the Stats from the \n                  BugReporter. \n\n                  When running it checks if there are any new ''Bugs'' or ''Ideas''\n                  entered or uploaded. If found some it displays the Stats:\n                   ___________________________________________________ \n                  |                                                   |\n                  |  ReporterStats    TODAY  TOTAL  LAST BY USER      |\n                  |                                                   |\n                  |  Used...........:    4     73   Casa Nova         |\n                  |  Ideas stored...:    0     21   Amtrac            |\n                  |  Bugs stored....:    2     49   Roi Danton        |\n                  |___________________________________________________|\n\n                  If no changes were made since the last run of this Tool,\n                  it skips displaying the Stats and displays only one line:\n\n                  [ ReporterStats: ] No changes in the BugReporter\n\n                  Thats it. Easy and usefull for (Main-)Sysops. So the Sysop\n                  no longer has to run the BugReporter every time he logs on\n                  to see if there are any changes in the BugReporter.\n\n                  Install the ReporterStats:\n                  --------------------------\n\n                  The best way is to insert the following line to the \n                  "Text-Welcome255(.ansi)" or any other Text-File that is\n                  used when you (MainSysop) log into your BBS:\n\n                  ~REXX(TempRexx:CN-BugReporterStats.rx) ~r\n\n                  Note: Please use the same Version-Number (2.0) of\n                        BugReporter and ReporterStats.\n!!!!                 \n\nIf  someone could translate this Document or all the other Menus/Text-Files\nto other languages, I will add them to the next update.  Thanks!\n\n(You can reach me at Skyline BBS or Dawn of Eternity)\n\n!!!!\n\n\n\nNote:\n-----\n\nThis  tool  was  written  for  all Sysops useing *REGISTERED* /T\empest BBS\nSoftware!   So  the source is very easy to read and (i hope) to understand.\nBut you can be sure there is no Backdoor included.\n\nPlease: Don''t change anything!\n\n\nGreetings to:\n-------------\n\n        Tim Hatzenbeler.......for the work on this great BBS,\n        Rick Rumer............for his help and support,\n        PAnDIT................for his C and Arexx Tools,\n        Stoeberhai............his Ideas and Bugreports,\n        Amtrac................for his help and ideas,\n        Cocky.................for testing all my Tools,\n        Roi Danton............for his perfect eyes and looking for bugs,\n        Michael Bockert.......for the fast Support and including all the\n                              Ideas from the Skyline BBS Users&Sysops.\n\n        Thanks!\n\n\n\n\n ........c.a.s.a...n.o.v.a........   12-Sep-94\n\n\n','\n',char(10)),NULL,NULL,34102,1,0,NULL,NULL,NULL,'scan',1780048428);
INSERT INTO door_catalog VALUES('bread13','BREAD13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BREAD13.LHA','BullRead','XIM','BullRead',NULL,NULL,NULL,'PrEsEnTs BuLlReAd VeRsIoN 1.3 BuLlEtInS DoOr 4 /X 3.x',replace('      ExOdOuS/><PrEsS                       \n          PrEsEnTs                          \n    BuLlReAd VeRsIoN 1.3                    \n  BuLlEtInS DoOr 4 /X 3.x                   \n','\n',char(10)),'BullRead.Guide',replace('@database BullRead.guide\n@$VER: BullRead.guide v1.3 (7-May-94)\n\n@node MAIN "BullRead Contents"\n                     @{b}@{u}Documents for BullRead v1.3@{ub}@{uu}\n\n               BullRead was written by Exodous/><Press\n                        Released on 07-May-94\n\n                    1)  @{" What is BullRead ? " link WHAT_IS_BULLREAD}\n                    2)  @{" Preferences        " link BULLREAD_PREFS}\n                    3)  @{" Error Messages     " link ERRORS}\n                    4)  @{" Installation       " link INSTALLATION}\n                    5)  @{" Distribution       " link DISTRIBUTION}\n                    6)  @{" Greetings          " link GREETINGS}\n                    7)  @{" Contacting me      " link CONTACTING_ME}\n                    8)  @{" Call These BBS''s   " link BBS_ADS}\n                    9)  @{" History            " link HISTORY}\n\n               BullRead was written in 100% assembler.\n@endnode\n\n@node WHAT_IS_BULLREAD "What is BullRead"\n                      @{u}What is BullRead ?@{uu}\n\nBullRead is a Bulletins door for Ami-Express version 3.x, it has the\nfollowing features :\n\n   @{b}o@{ub}  From 1 to 99 Bulletins.\n   @{b}o@{ub}  Multi-Node support.\n   @{b}o@{ub}  View bulletins while on-line.\n   @{b}o@{ub}  Download bulletins (as free downloads) for viewing\n       while the user is off-line.\n       (With the option of packing them before they are downloaded)\n   @{b}o@{ub}  Search bulletins for a particular piece of text.\n      @{b}(The search is 2-3 times faster than the Zippy text search!)@{ub}\n\nBullRead was originally written for @{"Q.E.D" link BBS_ADS}, and was written in 680x0\nassembler using Devpac 3 from HiSoft.\n\nBullRead requires kickstart 2 or better to be installed.\n\n@{b}Important : Read Me@{ub}\n\nTo ensure that BullRead hasn''t been altered, for example by someone\nputting ''back doors'' into it, it uses various different methods of\nchecking it''s self to see if it is valid, so if you notice any ''strange''\nbehaviour or BullRead try to send me a copy so that I can verify that it\nhasn''t been ''hacked''.\n\n@endnode\n\n@node BULLREAD_PREFS "BullRead''s Preferences"\n                    @{u}BullRead''s Preferences options@{uu}\n\n@{u}General information@{uu}\n\n  @{b}o@{ub}  BullRead''s preferences file is a text file, and can be edited using\n      any text editor (ED for example)\n  @{b}o@{ub}  All comments in the source file start with a #.\n  @{b}o@{ub}  Tokens start at the beginning of the line, and end at the ''='', e.g\n\n@{i}token=@{ui}<value>\n\n@{u}Tokens and descriptions@{uu}\n\n @{b}NAME@{ub}\n                Name of the destination file to create for downloading\n                 the bulletins - @{b}Excluding path@{ub}.\n                 (An extension is automatically added to this when the\n                  bulletin is packed.)\n\n @{b}NODENUM@{ub}       (YES or NO)\n                Whether you want to have BullRead add the node number\n                 to the filename in @{i}NAME@{ui}.\n                It is recommended that this option is YES.\n\n @{b}NUMBULLS@{ub}\n                The number of bulletins you are going to have.\n\n @{b}STARTZERO@{ub}     (YES or NO)\n                Whether you want the bulletins to start from 0, or\n                 from 1... YES indicates that bulletins should start\n                 from zero.\n\n @{b}BULL_TITLE.<x>@{ub}\n                The title for bulletin <x> that is displayed when the\n                 list of bulletins is displayed.\n\n @{b}BULL_FILE.<x>@{ub}\n                The file to display or add to the archive when bulletin\n                 <x> is read / downloaded.\n\n @{b}BULL_EXEC.<x>@{ub}  @{i}Optional@{ui}\n                The AmigaDOS command to execute before the file is\n                 viewed or downloaded.\n                If the last two characters on the line are ''$N'' then\n                 the node will be passed as an argument so that other\n                 doors can be run from within BullRead.\n                @{b}Also See@{ub} : ''Example.Script''\n\n @{b}NUMPACKERS@{ub}\n                The number of packers that you have configured.\n\n @{b}PACKER_TITLE.<n>@{ub}\n                The title for packer <x> when the list of packers is\n                 displayed.\n\n @{b}PACKER_EXEC.<x>@{ub}\n                AmigaDOS file to execute to pack the data.\n                If a $D is encountered in the string then the\n                 destination filename will be substituted. (eg archive)\n                If a $S is encountered in the string then the source\n                 filename will be substituted. (eg file to add to the\n                 archive)\n\n @{b}PACKER_EXT.<x>@{ub}\n                Extension to append to the file in @{b}NAME@{ub} when\n                 the file is packed.\n\n@{u}Example.Script@{uu}\n\nI have supplied an example AmigaDOS script so that when you want run\n more than one door before a bulletin is displayed/downloaded/searched\n it is possible. The file is also displayed below.\n\n@{b}NOTE@{ub} : The supplied script will @{u}NOT@{uu} work, and can only be used as an\n        example.\n\n@{b}--- Example.Script ---@{ub}\n.key NODE\n.bra {\n.ket }\n\n; Example AmigaDOS script so that BullRead can execute more than one\n; door to produce a bulletin.\n\n; The .key, .bra and .ket lines MUST not be changed.\n\n; Call our command(s).\n; (Put all commands/doors to be executed here).\n\n; AmigaDOS command.\nDelete T:TopLeechers.txt\nDelete T:TopUploaders.txt\nDelete T:UP_DOWN.txt\n\n; Doors must have {NODE} at the end of the line.\n\nDOORS:TopLeechers {NODE}\nDOORS:TopUploader {NODE}\n\nJoin T:TopLeechers.txt T:TopUploaders.txt to T:UP_DOWN.txt\n@{b}--- END of Example.Script ---@{ub}\n\n\n@endnode\n\n@node ERRORS "BullRead''s Error Messages"\n\n@{u}Error@{uu}       Error with reading the preferences file for BullRead.\n            Please inform <SYSOP>\n\n@{u}Description@{uu} Make sure that @{b}BullRead.prefs@{ub} is in one of the\n            directories specified in @{"Installation" link INSTALLATION}\n\n\n@{u}Error@{uu}       Error in the preferences file for BullRead.\n            Please inform <SYSOP>\n\n@{u}Description@{uu} There is an error in the preferences file, and BullRead\n            cannot find all of the information it needs, check that the\n            @{"preferences" link BULLREAD_PREFS} file is complete and that any tokens aren''t\n            missing.\n\n@{u}Error@{uu}       Error reading the bulletin file.\n            Please inform <SYSOP>\n\n@{u}Description@{uu} BullRead was unable to read a bulletin file from disk.\n            Ensure that the filename in the @{"preferences" link BULLREAD_PREFS} is correct,\n            if it is then there wasn''t enough memory for BullRead to be\n            able to load the bulletin into.\n\n@{u}Error@{uu}       Sorry, there was an error packing the data, download aborted.\n\n@{u}Description@{uu} There was an error whilst packing the data and the packer\n             aborted with an error message. See the packers instructions\n             for program specific error messages.\n\n@endnode\n\n@node INSTALLATION "How to install BullRead"\n                      @{u}Installation instructions@{uu}\n\nInstallation is relatively easy....\n\nCopy @{b}B.info@{bb} to @{b}BBS:Commands/BBSCmd/@{ub}\nCopy @{b}BullRead@{ub} to @{b}DOORS:@{ub}\nCopy @{b}BullRead.Prefs@{ub} and @{b}BullRead_Title.txt@{ub} to any of the following :\n\n                @{b}BBS:Doors/@{ub}\n                @{b}DOORS:@{ub}\n                @{b}DOORS:BullRead/@{ub}\n\nEdit @{b}BullRead.Prefs@{ub} to relate to your bulletins.\n  See @{" Preferences " link BULLREAD_PREFS}\n\nBullRead can now be used from Ami-Express.\n@endnode\n\n@node DISTRIBUTION "Distribution restrictions"\n                       @{u}Distribution of BullRead@{uu}\n\nBullRead is (c)1994 Exodous/><Press and may be distributed in any way\n as long as the following conditions are met :\n\n  @{b}o@{ub}  All of the files are included, unchanged.\n  @{b}o@{ub}  No money changes hands (ie @{b}NO@{ub} PD library distribution)\n\n@endnode\n\n@node GREETINGS "Greetings"\n\nGreetings to the following people :\n\n @{b}Oll¿e@{ub} - You best get that stuff done for me soon.\n @{b}GrassHopper@{ub} - Hope you like this new version, I''ve fixed all\n                of the bugs you''ve found :-)\n @{b}M¿sta Are@{ub} - Looks like I got my doors working before you did!\n @{b}Mike@{ub} - Are you still alive? if so I''d like to hear from you.\n\nAll members of @{b}><Press@{ub}\n\n Hope you all like this, and thanks for lettin me join.\n\n@endnode\n\n@node CONTACTING_ME "How to contact me"\n                          @{u}How to contact me@{uu}\n\nI can be contacted via E-Mail in the following ways :\n\n @{"Q.E.D" link BBS_ADS}    : Exodous\n The Tower : Exodous\n\nUntil the middle of June I can also be contacted via E-Mail at the\n following host :\n\n Internet : [email removed]\n\n@endnode\n\n@node BBS_ADS "Call these ><Press BBS''s"\n                   @{uu}Call these kewl @{b}><Press@{ub} BBS''s@{uu}\n\n@{b}Q.E.D@{ub} (WHQ)         : +44 (0)91-372-1911 (2 Nodes) - @{b}GRASSHOPPER@{ub}.\n\n@{b}SLEEZY BBS@{ub} (UKHQ)   : +44 (0)422-367-163 (1 Node)  - @{b}BONEIDLE@{ub}.\n\n@{b}MEDUSA DOMAIN@{ub} (CHQ) : +1 905-574-7791    (6 Nodes) - @{b}MEDUSA@{ub}.\n\n@{b}BIO HAZARD@{ub} (CHQ)    : +1 905-841-0965    (3 Nodes) - @{b}KAPT. KAOS@{ub}.\n\n@{b}THE LAB@{ub} (CHQ)       : +1 514-745-7420    (3 Nodes) - @{b}P.R SINISTER@{ub}.\n\n@{b}WAREZ DEPOT@{ub} (USHQ)  : +1 305-819-9925    (3 Nodes) - @{b}AMIGAMAN@{ub}.\n\n@endnode\n\n@node HISTORY "The history of BullRead"\n                     @{u}History of BullRead@{uu}\n\n| Ver   | Date          | Comment\n+-------+---------------+--------------------------------------------\n| 1.0   | 25-Apr-94     | First version.\n+-------+---------------+--------------------------------------------\n| 1.1   | 30-Apr-94     | Small bug fixed... now takes arguments from\n|       |               | the /X menu.. eg b 15 - read bulletin 15.\n+-------+---------------+--------------------------------------------\n| 1.1a  | 30-Apr-94     | Now searches for the prefs file in :\n|       |               |       BBS:Doors/\n|       |               |       DOORS:\n|       |               |       DOORS:BullRead/\n+-------+---------------+--------------------------------------------\n| 1.2   | 05-May-94     | Tidied code up.. ACP window now reports\n|       |               | ''Reading Bulletin''\n+-------+---------------+--------------------------------------------\n| 1.3   | 07-May-94     | Fixed a bug caused by having 19, 29, 39 ..\n|       |               | bulletins.\n|       |               | First ''Public'' version released by @{b}><Press@{ub}.\n+-------+---------------+--------------------------------------------\n@endnode\n\nThis is version 1.2 of BullRead (see below for history), the\nfollowing files must are present in this archive :\n\n        BullRead           - The Door.\n        BullRead.Prefs     - The preferences file\n        BullRead_Title.txt - The bulletins title text.\n        README             - This file.\n\n                          What is BullRead ?\n                          ~~~~~~~~~~~~~~~~~~\nBullRead is a bulletins door that lets users read, download and search\nbulletins.\n\n                         Configuring BullRead\n                         ~~~~~~~~~~~~~~~~~~~~\nTo configure BullRead load ''BullRead.Prefs'' into a text editor and\nedit the options .... the prefs file is commented to make it easier\nto change.\n\nConfiguration note : If you want to fun more than 1 executable\n		     program from a script then modify the AmigaDOS\n		     ''Example.Script'' script file, and make sure that\n		     you do a ''Protect <script> srwed'' so that\n		     BullRead can execute it.\n\n                             Installation\n                             ~~~~~~~~~~~~\nTo install BullRead simply put all of the files in any of the\nfollowing directories :\n\n	BBS:Doors/\n	DOORS:\n	DOORS:BullRead/\n\n*********************************************************************\nNote : the Title screen and the Preferences file MUST be in the same\n	directory, otherwise a title won''t be displayed.\n*********************************************************************\n\nthen set up an icon for it (XIM) - usually as a replacement for\n''B'' - and use it.\n\n                             Information\n                             ~~~~~~~~~~~\nThe search operation in BR is between 2 and 3 times as fast as /X''s\nbuilt in zippy text searcher!!\n\n\nWritten by ExOdOuS/TlS\n\nBullRead v1.2 (05-May-94)\n\n                               History\n\n| Ver	| Date		| Comment\n+-------+---------------+--------------------------------------------\n| 1.0	| 25-Apr-94	| First version.\n+-------+---------------+--------------------------------------------\n| 1.1	| 30-Apr-94	| Small bug fixed... now takes arguments from\n|	|		| the /X menu.. eg b 15 - read bulletin 15.\n+-------+---------------+--------------------------------------------\n| 1.1a	| 30-Apr-94	| Now searches for the prefs file in :\n|	|		|	BBS:Doors/\n|	|		|	DOORS:\n|	|		|	DOORS:BullRead/\n+-------+---------------+--------------------------------------------\n| 1.2	| 05-May-94	| Tidied code up.. ACP window now reports\n|	|		| ''Reading Bulletin''\n+-------+---------------+--------------------------------------------\n','\n',char(10)),NULL,'auto-added',18694,5,0,NULL,NULL,'bullread','scan',1780048428);
INSERT INTO door_catalog VALUES('brg_mse','BRG_MSE.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BRG_MSE.LHA','MSE','XIM','AddInvite',NULL,NULL,'BRG','| T H E   B O R G   B B S   P R E S E N T S| | -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-| | A M I - E X P R E S S - G A M E D O O R  |',replace('.------------------------------------------.\n| T H E   B O R G   B B S   P R E S E N T S|\n| -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-|\n| A M I - E X P R E S S - G A M E D O O R  |\n|                                          |\n| M A S T E R   S P A C E   E M P I R E    |\n|                                          |\n`------------------------------------------''\n','\n',char(10)),'mse.doc',replace('\n                         ----------------------\n                                  MSE\n                         (Masters Space Empire)\n                              Version 2.35\n                         ----------------------\n                          Player Documentation\n                         ----------------------\n\n\n                              Introduction\n                              ------------\n\nThis version of Space Empire was adapted from Ken Smith''s version, which was \nin turn rewritten from John Radoff''s.\n\nSpace Empire in basic is a game where you battle against other players\nfor control of the galaxy. MSE has gone even further, and the game is\nnow more a matter of not how well you fare in battle, but how good you\nare at swindling other players. You can bribe, spy, cheat and do some\nreally despicable things to your enemy, while your pampering your\nfriends, and sucking resources from your alliance.\n\nSeizing control of the galaxy is simple compared to what you have to do\nto stay alive ! If you don''t look after your people, then they will turn\non you and cost you precious time and money. You will have to plot and\nplan very carefully if you want any chance of winning, or getting out\nalive.....\n\n\n                               Read Me !\n                               ---------\n\nAs MSE is now fully working for similtaneous game play, you may have to\nwait in some circumstances for access to message files, or when the game\nis attempting to reset. Please have patiance while this is ocurring.\n\nThere is a new feature to version 2.2. When you are asked to give an\noptional amount, you can also enter ''Xn'' for multiples of the default\namount, where ''n'' is the multipier. ie: ''X2'' will give 2 times the default\namount.\n\n\n                           Starting the game\n                           -----------------\n\nWhen you first play, you will be asked to enter the name you wish to\nuse. For their you are given some planets, money, food and then your on\nyour own. Each player is allowed 5 turns per day, and each turn is\ncomprised six stages.\n\nNew players are protected from being attacked for their first 21 turns.\nUse them wisely.  If you attack someone (or even ATTEMPT to attack someone), \nthen your protection will be cancelled.  Also, attempting an infiltration \nspy mission will cancel your protection. \n\nWhen you first login to MSE, you will be given an update of all the\nevents that have occured in your absence. If any player has sent you a\nmessage, you will receive them and be given the option to reply to the\nmessage. If the message you receive is a reply to a previous message,\nyou will be able to view the original.\n\nSome messages will be sent to you in an encrypted form, if the sender\nhas made previous arrangments with you, you should know the code to\ndecrypt the message, or you will have to pay the computer to decrypt it\nfor you.\n\nIf you have tapped any messages from other players, you will receive\nthem here too, but you cannot view previous message, reply to the tapped\ncomunications or pay for auto-decryption.\n\n\n                          Running Your Empire\n                          -------------------\n      \n                            1.  Ruling Round\n                            2.  Buying Round\n                            3.  Covert Round\n                            4.  Battle Round\n                            5.  Disaster/Bonus Round\n                            6.  Alliance Round\n\n\n                              Ruling Round\n                              ------------\n\n       The Ruling Round is where you get a report of the current status of \nyour empire, and decide how to budget your credits. You must pay for the \nupkeep of your planets, feed your people, and pay for your army and/or spies.\n          \n       Food stores will only hold 100,000 kilotons, so don''t rely on them \ntoo much. Buying and selling prices will change with supply/demand. So\nit is possible to make money by buying and selling food. It is advisable\nto grow as food as you can, by feeding your people more they will become\nloyal servants, starving them can lead to a revolt. Remember that the\nfood stores are for all the players, so by buying out all the food from\nthe stores and taking an opponants food planets you may starve your\nenemies people and lead them into a revolt.\n\n       There are two forms of income for your empire:  Ore mining and tax\nmoney.  Ore money is derived from the number of ore mining planets you have.\nTax money is based on the number of people in your empire.\n        \n\n                              Buying Round\n                              ------------\n\n       After allocating your funds, you will be able to buy things with the \nmoney you have left over.  You will be presented with a list of things you \ncan buy, ranging from army soldiers to spies to planets.  You may also visit \nthe bank at this prompt.\n\n       The bank is designed to help you budget your money which can be very \nimportant at the later stages of the game.  Also, another person spying on \nyou cannot see the money that is in your bank but they can see the money \nin your normal credit balance. Bank accounts earn 5% interest per day. \n\n       You can also take out a loan, the amount that you can take out depends \non how many generic planets you own. Loans have a interest rate of 20%, and \nyou must pay at least 20% of your load back each turn. Your loan payments \nwill be automatically taken out of your bank account or credits, or if you \ndon''t have enough, you will start to lose planets! If you default on loans \nyou will get a bad credit rating, and consequently, your interest rates will \nincrease.\n\n       It''s a nasty trap to fall into !\n\n       To improve your credit rating, pay back twice the minimum repayment.\nNote that you can only have one loan out at a time, and that refinancing\nis not available. If you cannot make payments, and your planets do not\ncover the loan, all but a few of your planets will be repossed and you\nwill never get another loan.\n\n       A note on governing planets:  You MUST have one governing planet for \nevery 25 other planets.  Governing planets do nothing more than sap your funds, \nbut they are required to keep law and order in your empire.  If you do not \nhave enough, then things will get out of hand quickly.\n\n       These are the differant available planets and their uses :\n\n       Food planets      - Grow food for your people.\n       Ore planets       - Generate more income for you.\n       Defence planets   - Manufacture military equipment.\n       Governing planets - Keep law and order in the galaxy.\n\n       You can do Special Missions from this menu, and you will be\nreturned here when you have finished any mission. Available also from this\nmenu is the armoury. From here you may improve to armour of your soldiers,\nfighters and cruisers, and improve the weapons and speed of your fighters.\n\nThe price will increase depending on how many you already own, as all your\nold equiptment will need to be updated. The base prices of soldiers, and\narms will also increase.\n\n\n                            Special Missions\n                            ----------------\n\nCheck for taps:\n\n       If your communications get tapped, all the messages that you send \nor receive will also be sent to the player that tapped you. For a price, \nyou can check to see if your communications have been tapped. If they are,\nyou will have to kill all your agents to find the traitor and remove the tap.\n\nSend courier:\n\n       You may also send a courier with a private message who can also give \ngifts of credits to the recipient. This can be useful for bribes or \nnegotiations.\n\nEncrytped messages:\n\n       Encryted messages may be sent from here to other players, you will \nbe asked for an encrytion code between 1 and 25. If the receiving player \ndoesn''t know the code they will have to pay to have it unscrambled. But \nany spies that are tapping your messages will also get the encryted message, \nbut they do not have the option of paying to have it decrypted, but they\ndo get one chance to guess the code.\n          \nKill agents:\n\n       If your agents get bribed, you may find them disappearing with your \ncourier messages or giving you false information. The only way to solve \nthis is to kill all your agents. This is one of the few options in the \ngame which comes free of charge. This will also remove any taps that\nmight be on your messages.\n \nTrain military:\n\n       Your military can also be trained further from here, to give you \nthat edge in battle, but once they start training, they cannot fight \nagain until the next round.\n          \nTransporters:\n\n       You may send your cargo ships out from here to other players, your \ntransporters can hold 100,000 kilotons each and you may send food,soldiers,\nfighters,cruisers or carriers in the ships.\n\nDissension:\n       \n       You can try to create properganda on your enemies planets and\nmake the people rebel against your leader.\n\nDemoralize troops:\n\n       This will demorilize your enemies troops to make it easier to\ndefeat them in battle.\n\n\n                          Covert/Battle Round\n                          -------------------\n\n       If you have any spies, then you will be asked if you want to conduct \nany covert missions against other players.  You can use this to find out \ninformation about other players.  But be warned that the consequences of a \nfailed mission are severe.  Note that spying on another person will void \nyour protection. The computer will notify you of this.\n\n       After spying, you will be asked if you want to do battle. Since the \nbest way to get points is to take planets from other players, you will \nprobably be doing this a lot. Choose the player you want to attack and the\namount of troops you want to send over and the battle is on!  Note that \nif you attempt to attack someone your protection will be nullified. There \nis always an element of chance in battle, so you always have a chance of\nwinning (or losing).\n\n       Note that if the defender is part of an alliance, then troops from\nthat alliance will rush to his aid.  If the defender is a member of YOUR \nalliance you will expelled from your alliance.\n\n       If you are the leader then your victim will be expelled rather than\nyourself.  The game will notify you when you attack someone in your own \nalliance.\n\n       If you emerge the victor in battle, then you will receive 10% of \nyour enemy''s planets (rounded up).  You can choose the type of planets, \nbut you can only choose among what the defender has (i.e.. if he has no \ndefense planets, then you can''t get any).  If you take ALL of your enemy''s\nplanets, then you wipe that player from the game (which does wonders for \nyour army''s morale).\n          \n     \n                          Disaster/Bonus Round\n                          --------------------\n\n       Disasters/Bonuses are calculated using an algorithm dependent on the \nplayers score. Low scores will "usually" receive bonuses and high scores \nwill "generally" have disasters. Some of these can do nothing, or affect \nanything from harmony to destroying planets, others are merely humorous.\n\n       Any revolutions or strife on you planets will be shown here as\nwell.\n\n\n                             Alliance Round\n                             --------------\n\n       Alliances are a VERY important part of the game.  A player does not\nhave a very good chance of surviving in the game if they are independent or \nif they are in a weak alliance.  This much the same way as a real war \nsituation.  You must choose your alliance carefully because of this.  \nIf you are simply going to join an alliance read all the alliance \ndescriptions carefully.\n\n       The alliance round is where you form, join, list, or otherwise \nmanipulate alliances.  New players will have the options to join an alliance,\nstart a new alliance, list existing alliances, and quit alliance mode.\n\n       If you decide to join an alliance it will prompt you for an alliance\nnumber or will list all the alliances for you.  The game will show you some \nstatistics on each alliance and show a description of the alliance written \nby the leader.  Just follow the prompts.\n\n       All alliances are given a rating, this is based on the alliances\nperformance in battle against other alliances, and on the strength of\nit''s recources compared to others. The rating is also affected by how it\nmembers perform in battle, so if you start to lose too many battles you\nmay find yourself kicked out of the alliance. The rating affects none of\nthe battles, only your descision to join. The rating is only affected by\nthe actions it and it''s members take, so even if you get the crap beaten\nout of you it will not reduce your rating, but when the alliance or it''s\nmembers initiate battle, the results will affect the rating. Ratings\nthough are always affected on the teams comparison to other teams\nresources.\n\n       If you decide to start an alliance, you will be prompted for a name, \nthen you will become the leader of that alliance.  You must also decide how \nmany of each kind of force to charge your members to remain in your alliance.  \nRemember, you''re a member so you also have to pay the fees.  Leaders get to \ndo a few things that no one else can do:  Break up (dissolve) an alliance and \nkick someone out of your alliance (Expel).  You may also change your alliances \nfees at any time.  You will be the only one in your alliance that is notified\nwhen your alliance is attacked and when a player defaults on their payments.\n\n       A newly formed alliance receives 21 turns of protection much the same \nway as a player does.  Attacking another alliance or spying on another \nalliance will void your protection. When you type in your description, you will \nbe given the option of sending it as an advertisement to all the other players.\n\n       The alliance maintains an army, to which individual members contribute \nsome of their forces.  This alliance army is used to protect each of the \nmembers from attack.  If the alliance is disbanded, each member should get the \ntroops it contributed back. Having a larger army will help improve the\nteam rating.\n\n       Each day you must make payments to your alliance in the form of forces.\nThe amount of the payment is determined by your leader.  If you do not have \nenough forces to pay your fees on a certain day the game will record this in \nyour record and when you try to join another team the leader of that team will \nsee how many you times you balked on your previous team.  You can make up for \na missed payment by donating forces to your alliance (review defense forces \non the alliance menu).  If you donate enough forces to make up for a full\npayment then one balk will be deducted from your record.  The game will accept \na negative amount of balks so you may donate ahead of time in case you think \nyou may default in the future.\n\n       Alliance leaders get a larger message menu. They may send encryted \nmessages to their team members, messages to other alliances and their members, \nmessages to other Alliance leaders or messages to team members.\n\n\n       After leaving the alliance menu, you will be shown the current\nrank of all the players, and if you have any turns remaining you can\ncontinue. If you choose to exit the game you will be able to leave\nprivate messages to any or all of the players.\n\n\n                            Winning The Game\n                            ----------------\n          \n       To win MSE, you must accumulated 100,000 points.  This is done mostly by\nsquashing other players (okay, so its not a friendly game...).  When a person \nreaches 100,000 points or more, he becomes the "Space Lord" (a holdover from \nJon Radoff''s Space Empire).  If he stays there for 14 days, he wins the game \nand it starts over.  If more than one player has over 100,000 points, then \nthe person with the most points is the Space Lord.  To prevent a player in a \nlarge alliance from winning without even participating in a single battle \nhimself you cannot be a space lord if you are a member of a team.\n\n       Note that there can be only ONE winner.  That generally means you have \nto stab somebody in the back if you''re part of an alliance and you want to win.  \nThis becomes more significant towards the end of the game.  Since most players \nwill not be on their own a few teams will emerge as the strong ones.  You will \neventually have to attack someone in your own team.\n\n                          Miscellaneous Stuff\n                          -------------------  \n\n       There are more features within the game which have not been\ndocumented, some will be entirly random, and others will only be\navailable after a set logic. \n\n       The winner of each game will have their name recored in a data\nfile for their entry into the MSE Super Challange to be held later in\nthe year. Any bugs, questions or suggestions can be sent to me on The\nNut Factory BBS.\n\n\n                             Hints and Tips\n                             --------------\n\nWhen you first start, you are given 21 turns of protection, this is your\nchance to get ahead. These tips can help you get the edge on everyone\nelse..\n\n1. You will get the most money from ore planets, but as you buy more,\nthe price will increase. Try buying only in large lots so you will have\nmore money.\n\n2. Keep your cash in the bank, the other players won''t know how much you\nhave and you will earn interest on it.\n\n3. If you take out a loan, spend it all on ore planets, you will make\nenough profit each turn to pay back much more than required to the bank.\n\n4. Don''t waste any money on defence or military until your protection is\njust about to run out, you can buy more planets with the money you save.\n\n5. Give your people more supplies than they need, and they will produce\nmore and be happier.\n\n6. Watch the news to see who''s fighting who, and who is joining which\nalliance. People might still be friends and team up against you even if\nthey are in differant alliances.\n\n\nWhen your protection runs out..\n\n1. Spy on every one''s military at every chance to gauge how fast they\nare growing and if they are a threat.\n\n2. Put your army into training whenever you won''t be using them, it will\nhelp you next time you want to fight.\n\n3. DONT piss people off too much if you aren''t very strong, you might\nfind yourself wiped out.\n\n4. Invest in lots of defence stations on your last turn, anything can\nhappen in a day.\n\n\nAnd most important of all..\n\nIf you can handle it, start an Alliance, and make it a good one, by\nbecmomeing the leader of the most powerful alliance, you are well on\nyour way to winning. The leader of an Alliance can direct its forces\nagainst other alliances, so you can deplete an alliances forces just\nbefore you attack a member of it yourself.\n\nDon''t stay by yourself at the early parts of the game, you need\nprotection, and there is safety in numbers, so start an alliance or join\none fast (if they will have you).\n\nTo make your alliance strong:\n\n\n1. Send messages to members of other alliance members offering them\nbetter protection to join you.\n\n2. Send bribes and gifts to stronger players to get them into your\nalliance.\n\n','\n',char(10)),NULL,'auto-added',235313,4,0,NULL,NULL,'brg_mse','scan',1780048428);
