INSERT INTO door_catalog VALUES('brs_mv02','BRS-MV02.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BRS-MV02.LHA',NULL,'XIM','movey.exe',NULL,NULL,'BRS',':.... /\________/\________/\_______/\ .... : |...  \_______     _____.   \   .___/  ... | :..    |.  _|/____/.   //   _____  .\   .. :',replace('.-->  b  R  A  i  N  R  A  P  E  R  S  <---.\n:.... /\________/\________/\_______/\ .... :\n|...  \_______     _____.   \   .___/  ... |\n:..    |.  _|/____/.   //   _____  .\   .. :\n|..    ||  \__    \|   \\   \_mLt   \\  .. |\n:...   ;____|/____/____|\____/_______/ ... :\n`--- -- ----[ pRESENTS yA tOdAY ]--- -- ---''\n  >>>>>>>>>     m0vEy v0.002f     <<<<<<<<\nMove siply filezz from a dir 2 anotha using\n/X-like file listings or simple ascii lists.\n  4 Nasty Bugs Fixed - Version 100% clean\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 19:48:08  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',22226,3,0,NULL,NULL,'brs_mv02','scan',178004843