INSERT INTO door_catalog VALUES('brs_pi10','BRS-PI10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BRS-PI10.LHA','PINFO','XIM','PINFO',NULL,NULL,'BRS','..  ___\_____     \__   _   \\_  ___/_ ...... ... \       /  __/ /  __/  _// \___   \ ..... .-\    _/    \ /   \     \_         \-.',replace('       _____________________ ________\n..  ___\_____     \__   _   \\_  ___/_ ......\n... \       /  __/ /  __/  _// \___   \ .....\n   .-\    _/    \ /   \     \_         \-.\n/\/|:/__________// ____\_____/_________/:|\/\\n\/\|0x:::::::::::\/::::::::::::::::::::::|/\/\n   `-------------------------------------''\n.:: bRAiNrAPeRS aRE pR0Ud 2 pRESEnT t0DAy ::.\n>> >        pOiNTiNFobOARD v1.0ß        <  <<\nTool 4 FIDO systems: creates an info bull for\n            whole system points.\n','\n',char(10)),'PIB10.DOC',replace('\n\n                    ______  ________.___    /\    /\\n                   / _   /\/  ___/  |  //  //\\  / /\n                  /     / /\_  \\_\   /---///\\\/ /---------+\n                 /__/__/ /  /  // / : \  ///  \\ /ARexx  ***|\n                 \__\__\_\____// /  |__\//^^^^/ $X-Group  **|\n                 |       \____/ \\__| _ //   / /\/X Doors  *|\n                 +----+\              ///   /_/  \\\Presents|\n                        +-AiM-arEXX-dOORS-dEVELOPERS--------+\n\n                                       &\n\n                 .-->  b  R  A  i  N  R  A  P  E  R  S  <---.\n                 :.... /\________/\________/\_______/\ .... :\n                 |...  \_______     _____.   \   .___/  ... |\n                 :..    |.  _|/____/.   //   _____  .\   .. :\n                 |..    ||  \__    \|   \\   \_mLt   \\  .. |\n                 :...   ;____|/____/____|\____/_______/ ... :\n                 `--- -- ---------------------------- -- ---''\n\n                                 :: pRESENT ::\n\n           - -- -*------------------------------------------*- -- -\n                           pOiNt iNFo bOARD v1.0Beta\n           - -- -*------------------------------------------*- -- -\n\n                      == Freely Destributable Version ==\n\n### Description:\n\nThis  tool  allows you to create an output bull that contains interesting infos\nabout the fido packets holding in mail:outbound/ for each point/node.\n\nSo  if  you  have  an Amiga fido-mail system you can create a list that you can\nshow to normal users.  Your point that calls with terminal can so view how much\npkts he has to download in the next poll.\n\n\n### Using it:\n\nSynopsis: PINFO <CFGFILE/A>, <OUTPUTBULL/A>\n\nWhere: CFGFILE    is a valid PINFOBOARD cfg path+file (see chapter "CFG")\n       OUTPUTBULL is a path+file for the output\n\n\n### CFG:\n\nHere an example:\n\n------------------------------------X8---  Cut ------------------------\n65:1700/1\n0xYRh\n1\n\nbLACk KniGHT\n9\n\niRON mAN\n10\nD\nChASSiS\n11\n\nZaGOR\n12\n\nDr Faustus\n13\nD\niNVERNoMuTo\n14\n\nmAD mAX\n15\nD\ncOLA\n16\nD\nMoNNA LiSA\n17\n\nNuKe\n18\n\nFStar\n21\n\nKiller Loop\n69\nD\n------------------------------------X8---  Cut ------------------------\n\n1st line: 3dimensional NODE Address (e.g.: "2:335/333" etc etc)\n\nOther lines will follow a matrix:\n\n1st Matrix line : Point Name\n2nd Matrix line : Point Number\n3rd Matrix line : Point Status (D=Down; Blank line=Active)\n\n\n### Output:\n\n                   [1mPOINT InfoBOARD on node 65:1700/1[0m                    \n\n PNT  NAME                      STATUS     MAIL HOLDING        FILE HOLDING\n[1m ---  ------------------------  ------  ------------------  ------------------[0m\n  1   0xYRh                     Active    1  :   4.08 Kb      0  :   0.00 Kb\n  9   bLACk KniGHT              Active    1  :   4.20 Kb      0  :   0.00 Kb\n 10   iRON mAN                   Down     0  :   0.00 Kb      0  :   0.00 Kb\n 11   ChASSiS                   Active    32 :  84.27 Kb      0  :   0.00 Kb\n 12   ZaGOR                     Active    1  :   0.87 Kb      0  :   0.00 Kb\n 13   Dr Faustus                 Down     0  :   0.00 Kb      0  :   0.00 Kb\n 14   iNVERNoMuTo               Active    2  : 102.53 Kb      0  :   0.00 Kb\n 15   mAD mAX                    Down     0  :   0.00 Kb      0  :   0.00 Kb\n 16   cOLA                       Down     0  :   0.00 Kb      0  :   0.00 Kb\n 17   MoNNA LiSA                Active    23 : 129.26 Kb      0  :   0.00 Kb\n 18   NuKe                      Active    1  :   2.98 Kb      0  :   0.00 Kb\n 21   FStar                     Active    1  :   4.09 Kb      0  :   0.00 Kb\n 69   Killer Loop                Down     0  :   0.00 Kb      0  :   0.00 Kb\n[1m ---  ------------------------  ------  ------------------  ------------------[0m\n\n                            Total Points number : 13                            \n\nSelf-explainatory!\n\n\n\n                              >>> GReeTinGS!! <<<\n\nSpecial thanx 2:\n\nMonna Lisa  -- BBSS_PT.DIZ idea sourcerer :>\n\nHorobi      -- tHANx! 4 TCP!\nMind Melter -- Try to call me, sometime!\nIron Man    -- 10x 10x 9x!\nPal-A       -- dA kewlest PCist (ah?!)\nVenus       -- dA XXX (censored)\nChassis     -- Sleep, sleep chassis! (da presciuttone!)\nInvernoMuto -- Neuromancer rulezzzz! Yo bro!\nDigital Guru - Really master? yEP!\nDr. G       -- Call me, sometime!\nAlx Sty     -- Yo! Thanx 4 ur helps\nPapaj       -- aNotHa great Master!\nKiller Loop -- ciauzz, lamer! (i`m jokin`! [or not?])\nStun        -- Greaaat modzz! & greaat pizzetto\nStoney      -- KOooooOOOOOol! ehi!, kill everybody!!!\nLry         -- dArK Ranger RuLeZzz?!\nSpiderMan   -- One time i`ll call u (uhmmm!)\nAlex        -- I`ve heard u only one time\nZagor       -- Top Manolo 95!\nMr Yo       -- Yo, Yo! (tom, tom!)\nRobin Hood  -- tEMpeST konverted!\nMaverick & UMM Dance ur Ass!\nDr. Faustus -- Hallo...\n\nSo, i`ve forgot anybody?\nAh! yep ... Parsekko, Metal, fRa and otha MI stuFF!\n\n*******************************************\nAND A SPECIAL HALLO 2 ALL CYBERBROTHARZZ!!!\n*******************************************\n\nCiauzzzzzzzzzzzzzzzzZzzzzz!\n\n###SEE YA! -------------------------------------------------------------------\n\n                           ______                              ______\n              ____________/     / ________  ________________  /     /\n           ___\_____     /     / _\_____  \ \     _     /   |/     /\n           \       /  __/     /_/_    _/   \/     /____/   _/   __/\n            \    _/    \    _/    \   \     \   _/    /    \     \_\n            /__________/__________/____\     \_______/______\_____/\n                                        \_____\\n               StAff:         o - -- ---  ____  --- -- - o\n               ~~~~~~        ____________/   /________/\\n             0xYrh/V0/BRs ___\_____     /   //         / Music WoRLd\n              Venu$/V0    \       /  __/   / \_    ___/  HeaRtQuaKe!\n             Chassis/CHA   \    _/    \   /   /   /      ~~~~~~~~~~~\n                           /__________/ _/   /___/0x\n                                      \/\n A2ooo `030`882 * o$3.1 * ZyX 16800 6.13 * /X 4.4 * > V0 / Sx / SVR / BRs WHQ <\n\n  Music Modules/Seven Valley Records Support/Dj News Support/Dj Music Support\n                 Cloud City Support/AreXX Support/AmiX Support\n     V0/CHA Music Modules Writers HQ -- ASX/X /X AIM Doors Development HQ\n                               bRaiN rApERs WHQ\n                             Ami & PC Public Domain\n\n                      N+U+M+B+E+R : +39 / 75 / 584 82 46\n\n\n0xYRH/V0/SX/BRs/BBBBS\n\n                This program has been released on 13/April/1995\n','\n',char(10)),NULL,'auto-added',22042,4,0,NULL,NULL,'brs_pi10','scan',1780048435);
INSERT INTO door_catalog VALUES('bryce','BRYCE.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/BRYCE.LHA',NULL,'XIM','Collection Of Bryce Utils',NULL,NULL,NULL,NULL,replace('Collection Of Bryce Utils\n','\n',char(10)),'CONTAINS.TXT',replace('\n                        Bryce''s AmiExpress Utility Pack\n\n                                   Contains:\n\nDlog V1.8     -  Top Downloaders Util\nUlog V1.8     -  Top Uploaders Util\nNoansi        -  Ansi Stripper Util\nMsgTop        -  Top Message Writers Util\nMsgRescue     -  Message Base Rescuer for Crashed Message Bases\nCycle-Texts   -  Logon & Logoff Text Cycler\nLogbook V1.7  -  Last Callers Util\nStiplog V1.1b -  Callerslog Stripper\n\nAll Utils are complete with docs!\nFor further updates to Bryce''s Utils then call: DownTown ++31 5750-29313\n\n-BamBam\n\n','\n',char(10)),NULL,NULL,76015,2,0,NULL,NULL,NULL,'scan',1780048435);
