INSERT INTO door_catalog VALUES('cds_cs10','CDS-CS10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CDS-CS10.LHA',NULL,'XIM','_______________________________________',NULL,NULL,'CDS','\_     ____________.   \_    _________/ /X! |     |     \_    |     \_______    \_ |     l      /    l_     /           /',replace(' _______________________________________\n \_     ____________.   \_    _________/ /X!\n  |     |     \_    |     \_______    \_\n  |     l      /    l_     /           /\n  l______     /______     /______     /\n ·------\____/------\____/------\____/sCf!\n  pROUDLy .. pRESENTs ...27/02/95:\n   CoolStats v1.0 - Status Door for /X!\n ·-------------------------------------·\n','\n',char(10)),'CoolStats.Doc',replace('                  _______________________________________\n                  \_     ____________.   \_    _________/\n                   |     |     \_    |     \_______    \_\n                   |     l      /    l_     /           /\n                   l______     /______     /______     /\n                  ·------\____/------\____/------\____/sCf!\n                     pROUDLy .. pRESENTs ... 27/02/95:\n\n                             - CoolStats v1.0 -\n                               © iCE/CDS 1995\n\nWHAT IS THIS?\n-------------\nWell, what''s this!? Nothing special, just another status door for /X.\nThere are dozens of status doors, but they all didn''t show what I wanted\nto know. So I `coded'' my own in Arexx. Nothing special. \nSum of the credits for the design must go out to Muad''dib `de kleine\nvervelende dwerg'' / DLT. I used his LHA/LZX checker design for ideas. \n\n\nREQUIREMENTS:\n-------------\nProperly running Arexx. Rexxdoor in BBS:Utils/ and an assigned DOORS:\ndrawer. \nTested on a 2500/030 - 5 mb Ram - /X 4.8, but there should be no problems\nwith other configurations.\n\n\nINSTALLATION:\n-------------\n/X 3.xx+\n\nCopy All the files from the archive to the right drawers. Finished!\n\n/X 2.xx & S!X\n\nDunno, but it won''t cause any problems if you install it as a normal AIM\ndoor, I suppose.\n\n\nCONTACT ME!\n-----------\nAnd that was all! Hope you can use this little door!\nContacting me: \nCall the ¡NTERSpHERE at +31-2290-35368W414, and page me! The number\nprobably will be changed in april/may so look around for the new one, then!\nOr leave me mail at any major Dutch board.\n\n\nBBS PLUG:\n---------\n\n\n        ________________.___________________________________      ·\n        \_________\_     \   \____    ____   ____\_    ___  \_    :\n        .|          \_    \    \_       \_    __\____    _   /__  ¦\n        :|           /          /        /    \     /    \     /  ¦\n        ¦l______   ·/____\    ·/_____  ·/______   ·/_____/    /::.¦\n        `------\___/------\___/-----\__/------\___/------\___/----''\n_______________________________.________________________________________\n\_    ______\_          \_     |    \_     _____\_          \_     _____\_\n |           |     l___  |     _     |     ______|     l_____|     ______|\n l______     |     ______|     |     |     l     |     |     |     l     |\n l___________l_____|     l_____|_____l___________l_____|!sCf!l___________|\n       Roøl¡Ng aT 14k4 (yEah RiTe) - +31-2290-35368-W414 - CDS WHQ \n    ÆM¡GÆ-/X-TøøLS-©øN5øLeS-mØd5-ReQµe5Ts-¡N5åNe s¥sOp-Nø FuCK¡N'' Pc''S!\n     \n                     Ya CaLLeD... And GoT nO CoNNecT!\n                  A. Add sum secs to yar dialer timeout!\n     B. You accidently got a dude on the phone, and hung op.. (DON''T!)\n                            C. You''re støøpiD!\n\n\n\nFUTURE:\n-------\nMore facts to display, o.a. Cps''s. A user definable header/tailer. \nContact me for more!\n\n\nGREETINGS!\n----------\n\nGreetings and thanx to the following dudes:\n(in no special order at all!)\n\n     Muad''Dib/DLT (o-kee!), WishBringer/DLT, LightNing/DLT, Exotic/DLT\n    Track/¿, Veteran/CCN, Sir IQ, (Good luck with MB dudes!), Pyxis/CCN\n  Funz/CCN, mAC/CCN, Midnight Caller/CCN, Eurobyte/CCN, Motive Power/MST\nKillRaven/MST, The Brain/LPS, Delite/LPS^BTW^CRY, Pinokio/BTW, ScarFace/Edge,\n Hawk,Radavi&MSW/EFFECT, D-Lorean/Myth (whahahha!), THC/Myth, PLL/Myth, Koud?\nCrew One/Myth (nuke this and @#*%), NightCrawler/Indy, aXeBlade/AC!/JeTsEt,\n   The Desert Dancer (het font is lelijk!), Tom, Zack/STD, MEGA^FORTRESS\nWhirlWind & Apollo/Dutch Dreams, The Edge, Stephen King, Neoplasia, Iris DK, \n Defiance Sweden, Sper/Spirit, all CDS members, the former Estate Staff &\n     his slaves and all dudes in Houten 1995 (including Courbois)... \n                             .\n                  .     .  ..:.   .·...·\n                          . .. _____:o:· ·\n--   ---  ______. ----.·____·o/    /+wB! --->> ------>>---------____ --\n    - -- / __   \\    .:\_  \/ _  /.:·___________ ___________  /    \\n     ¯¯ /   /\   \ __·:·:/     \_/\·:·\_  ______/ \_  ______/  \    /.\n-  -- -/   / /   /// \.:/.        \\·:·/  ___/__  _/  ___/__    \__//\n ___ _/   / /   / \\_/·//   /\     ''\_/_  L\    \\    L\    \     _\n______\   \/   /______/    /__\________/_________\\__________\\\-(_)))- -\n_____\\\______//_____\\___///_______ _______________ ________ ____ __\n\n                                   >:-)\n\n','\n',char(10)),NULL,NULL,4979,3,0,NULL,NULL,NULL,'scan',1780048442);
INSERT INTO door_catalog VALUES('cds_cs14','CDS-CS14.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CDS-CS14.LHA',NULL,'XIM','_______________________________________',NULL,NULL,'CDS','\_     ____________.   \_    _________/ |     |     \_    |     \_______    \_ |     l      /    l_     /           /',replace('  _______________________________________\n  \_     ____________.   \_    _________/\n   |     |     \_    |     \_______    \_\n   |     l      /    l_     /           /\n   l______     /______     /______     /\n  ·------\____/------\____/------\____/sCf!\n   pROUDLy .. pRESENTs ... 27/02/95:\n   CoolStats v1.4 for /X! - MAJOR BUGFIX\n  ·-------------------------------------·\n','\n',char(10)),'CoolStats.Doc',replace('                  _______________________________________\n                  \_     ____________.   \_    _________/\n                   |     |     \_    |     \_______    \_\n                   |     l      /    l_     /           /\n                   l______     /______     /______     /\n                  ·------\____/------\____/------\____/sCf!\n                     pROUDLy .. pRESENTs ... 27/02/95:\n\n                             - CoolStats v1.4 -\n                               © iCE/CDS 1995\n\nWHAT IS THIS?\n-------------\nWell, what''s this!? Nothing special, just another status door for /X.\nThere are dozens of status doors, but they all didn''t show what I wanted\nto know. So I `coded'' my own in Arexx. Nothing special. \nSum of the credits for the design must go out to Muad''dib `de kleine\nvervelende dwerg'' / DLT. I used his LHA/LZX checker design for ideas. \n\n\nNOTES ON v1.4\n-------------\nYou release a door. You sit back and relax. Then you try the door again\nwith sum changed stats and you see that the door fucks up totally. So you\nrelease another version, 1 hour after the first. Ain''t life great!?\nThanx to Midnight Caller/Cocaine/Scepcis for helping me testing!\n\n\nREQUIREMENTS:\n-------------\nProperly running Arexx. Rexxdoor in BBS:Utils/ and an assigned DOORS:\ndrawer. \nTested on a 2500/030 - 5 mb Ram - /X 4.8, but there should be no problems\nwith other configurations.\n\n\nINSTALLATION:\n-------------\n/X 3.xx+\n\nCopy All the files from the archive to the right drawers. Finished!\n\n/X 2.xx & S!X\n\nDunno, but it won''t cause any problems if you install it as a normal AIM\ndoor, I suppose.\n\n\nCONTACT ME!\n-----------\nAnd that was all! Hope you can use this little door!\nContacting me: \nCall the ¡NTERSpHERE at +31-2290-35368W414, and page me! The number\nprobably will be changed in april/may so look around for the new one, then!\nOr leave me mail at any major Dutch board.\n\nBUGS!?\n------\nThe door will fuck up if you''ve a enourmes amount of bytes left.\nCan''t fix this. :(\n\n\nBBS PLUG:\n---------\n\n\n        ________________.___________________________________      ·\n        \_________\_     \   \____    ____   ____\_    ___  \_    :\n        .|          \_    \    \_       \_    __\____    _   /__  ¦\n        :|           /          /        /    \     /    \     /  ¦\n        ¦l______   ·/____\    ·/_____  ·/______   ·/_____/    /::.¦\n        `------\___/------\___/-----\__/------\___/------\___/----''\n_______________________________.________________________________________\n\_    ______\_          \_     |    \_     _____\_          \_     _____\_\n |           |     l___  |     _     |     ______|     l_____|     ______|\n l______     |     ______|     |     |     l     |     |     |     l     |\n l___________l_____|     l_____|_____l___________l_____|!sCf!l___________|\n       Roøl¡Ng aT 14k4 (yEah RiTe) - +31-2290-35368-W414 - CDS WHQ \n    ÆM¡GÆ-/X-TøøLS-©øN5øLeS-mØd5-ReQµe5Ts-¡N5åNe s¥sOp-Nø FuCK¡N'' Pc''S!\n     \n                     Ya CaLLeD... And GoT nO CoNNecT!\n                  A. Add sum secs to yar dialer timeout!\n     B. You accidently got a dude on the phone, and hung op.. (DON''T!)\n                            C. You''re støøpiD!\n\nHISTORY:\n\nv 1.0 - Nutting new. First Release\nv 1.1-1.3 - Lotsa bugs fixed. Not released. \n\n\nFUTURE:\n-------\nMore facts to display, o.a. Cps''s. A user definable header/tailer. \nContact me for more!\n\n\nGREETINGS!\n----------\n\nGreetings and thanx to the following dudes:\n(in no special order at all!)\n\n     Muad''Dib/DLT (o-kee!), WishBringer/DLT, LightNing/DLT, Exotic/DLT\n    Track/¿, Veteran/CCN, Sir IQ, (Good luck with MB dudes!), Pyxis/CCN\n  Funz/CCN, mAC/CCN, Midnight Caller/CCN, Eurobyte/CCN, Motive Power/MST\nKillRaven/MST, The Brain/LPS, Delite/LPS^BTW^CRY, Pinokio/BTW, ScarFace/Edge,\n Hawk,Radavi&MSW/EFFECT, D-Lorean/Myth (whahahha!), THC/Myth, PLL/Myth, Koud?\nCrew One/Myth (nuke this and @#*%), NightCrawler/Indy, aXeBlade/AC!/JeTsEt,\n   The Desert Dancer (het font is lelijk!), Tom, Zack/STD, MEGA^FORTRESS\nWhirlWind & Apollo/Dutch Dreams, The Edge, Stephen King, Neoplasia, Iris DK, \n Defiance Sweden, Sper/Spirit, all CDS members, the former Estate Staff &\n     his slaves and all dudes in Houten 1995 (including Courbois)... \n                             .\n                  .     .  ..:.   .·...·\n                          . .. _____:o:· ·\n--   ---  ______. ----.·____·o/    /+wB! --->> ------>>---------____ --\n    - -- / __   \\    .:\_  \/ _  /.:·___________ ___________  /    \\n     ¯¯ /   /\   \ __·:·:/     \_/\·:·\_  ______/ \_  ______/  \    /.\n-  -- -/   / /   /// \.:/.        \\·:·/  ___/__  _/  ___/__    \__//\n ___ _/   / /   / \\_/·//   /\     ''\_/_  L\    \\    L\    \     _\n______\   \/   /______/    /__\________/_________\\__________\\\-(_)))- -\n_____\\\______//_____\\___///_______ _______________ ________ ____ __\n\n                                   >:-)\n\n','\n',char(10)),NULL,NULL,5248,3,0,NULL,NULL,NULL,'scan',1780048442);
