INSERT INTO door_catalog VALUES('cdser103','CDSER103.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CDSER103.LHA','CD-SERVER','XIM','CD-SERVER',NULL,'SieGeL',NULL,'\    ____    )  /___/\_| & rED sECTOR ¡NC | .-\___\ | \___\__   /   |  /X-¡NNOVATION   | `---|___|___|______/____|---[ PRESENTS ]---''',replace(' _____________ ___Mo! __.<---[ tRISTAR ]---.\n \    ____    )  /___/\_| & rED sECTOR ¡NC |\n.-\___\ | \___\__   /   |  /X-¡NNOVATION   |\n`---|___|___|______/____|---[ PRESENTS ]---''\n    CD-Server V1.03p by SieGeL & ByteAndi\n.------------------------------------------.\n| FIRST PUBLIC UPDATE,ALL KNOWN BUGS FIXED |\n| NOW WITH MULTIDEVICE- AND ASSIGN-SUPPORT |\n| BETTER FAME-SUPPORT, LONG PATHES WORKING |\n`------------------------------------------''\n A TOOL FROM THE "REAL" (tRSi/X-iNNOVATiON)\n','\n',char(10)),'CD-sERVER_DEUTSCH.guide',replace('@database CD-sERVER V1.03 - Deutsches DataBase\n@author "SieGeL/tRSi"\n@(c) "Copyright © 1995 (tRSi/X-iNNOVATiON)"\n@$VER: CD-SERVER.guide 1.03 (17.08.95)\n\n@index Main\n\n@node Main "CD-Server - BBS Tool geschrieben von SieGeL & ByteAndi (tRSi/X-iNNOVATiON)"\n@{b}                                                                     ______\n .-----------[ TRSI (/X·INNOVATION) ]------------.       _  ________/     /\n | _________________________________       ______`-------\\//  __    \\    /---.\n | \\       _____________     /     /______(______)  _     /    \\     \\  /    |\n |  \\______\\    |    __/   _/\\______       /     | (/)   /     /\\     \\/ Mo! |\n | \\     |      |    \\      \\       |     /      |  ¯   /     / /\\     \\_    |\n | \\\\    l______|_____\\      \\___________/_______|    _/     /_/  \\_____/    |\n `---------------------\\______/-----------------------\\_____/-\\_____/--------''@{ub}\n\n                           iS pROUD tO pRESENT:\n\n@{APEN 2}             CD-Server V1.03 public written by SieGeL & ByteAndi@{APEN 1}\n                                                                          \n                      @{" COPYRIGHT! " LINK COPYRIGHT}     @{"VERTREIBUNG!" LINK DISTRIBUTION}\n                      @{" EINFÜHRUNG " LINK EINFÜHRUNG}     @{"INSTALLATION" LINK INSTALLATION}\n                      @{" BEDIENUNG! " LINK HOW2USE}     @{" -CREDITZ!- " LINK GREETINGS}\n\n Der erste "@{b}ECHTE@{ub}" Server für jedes Amiga-DOS kompatible device,z.B. CD-Rom !\n@endnode\n\n@NODE COPYRIGHT "Copyright-Information für dieses Programm"\n\n     @{u}Copyright@{uu}\n\n   Dieses Programm ist ''FreeWare''.\n\n Es darf frei kopiert und für nicht kommerzielle Zwecke vertrieben werden,\n solange sicher gestellt ist, das kein file (ausser natürlich BBS-Addys)\n zu diesem Archiv dazugepackt oder aus diesem Archiv entnommen wird, und \n das für diese Veröffentlichung nicht mehr Geld, als für die Erstattung des\n Datenträgers/Kopierkosten, notwendig ist, verlangt wird.\n\n Das volle Copyright auf den Programmcode liegt bei dem Author (also meine\n Wenigkeit!) selbst, und ohne meine schriftliche Genehmigung ist es nicht \n erlaubt, dieses Programm kommerziell zu vertreiben.\n\n Diese Version von CD-Server ist die EINZIGSTE, die unter dem Prinzip der\n ''FreeWare'' vertrieben wird, alle anderen Updates (Fehlerbereinigungen etc.)\n sind dann nur noch für registrierte User verfügbar. Wenn Sie registrierter\n User bei mir werden möchten, dann haben Sie eine Registrierungs-Gebühr in\n Höhe von 30.- DM ($20) zu bezahlen.\n\n Diese Registrierungsgebühr ist natürlich nur einmalig zu entrichten, nach\n der Bezahlung erhalten Sie vollen Zugriff auf mein Register-Door und können\n dann frei über ALLE meine Tools verfügen.\n\n Alles weitere können Sie dann mit mir in meiner @{"BBS" LINK ADDY1} besprechen. Einfach\n mal durchcallen und ''SieGeL/tRSi'' eine Mail hinterlassen, ich kläre dann\n alles weitere.\n\n            @{"LISTE ALLER BISHER VON MIR VERFASSTEN PROGRAMME" LINK PRGLIST}\n@endnode\n\n@NODE DISTRIBUTION "Vertreibung von CD-Server"\n\n     @{u}Verbreitung/Vertreibung@{uu}\n\n  Hiermit genehmige ich die Veröffentlichung von diesem Archiv, solange wie\n  nicht mehr Geld, als für die Erstattung der Kopier-kosten etc. notwendig\n  sind, verlangt wird, und solange dieses Archiv nur in seinem Original-\n  zustand vertrieben wird. \n\n  Das Copyright liegt bei dem Author (also mir !) selbst, und ohne meine \n  schriftliche Genehmigung darf dieses Programm nicht kommerziell vertrieben \n  werden.\n@ENDNODE\n\n@node EINFÜHRUNG "Einleitung, oder warum dieses Programm entstanden ist."\n\n@{u}Einleitung@{uu}\n\nVor ein paar Monaten hatten wir die erste Version von dem CD-Server ver-\nöffentlicht, und es hat den Anschein das dieses Tool für Sysops mit CD-Roms\nein nützliches Tool geworden ist...aber wie wir ja alle wissen, ist niemand\nvollkommen, und auch wir haben einige Fehler in der ersten Version gemacht.\n\nNachdem wir die gröbsten Bugs aus der V1.00 entfernt hatten, haben wir uns\ndarauf geeinigt, entgegen der Beschreibung der V1.00 nun doch noch ein\nPublic Update zu releasen, da die V1.00 doch arg heftige Bugs hatte...\n\nNatürlich wurden auch wieder ein paar neue Dinge eingebaut, nun ist es z.B.\nmöglich, Devices & Assigns (!!!) zu verwalten. Um dieses feature zu ver-\nwenden, müssen Sie einfach ein Assign erzeugen, welches auf dem Directory\nzeigt, das Sie auch den Usern zur Verfügung stellen möchten. Dieses Assign\nwird dann im Icon von CD-Server vermerkt, und schon können die User auch\ndieses Assign "besuchen" ...\n\n@{u}Merkmale von CD-Server@{uu}\n\n - Ermöglicht Downloaden/Anzeigen von TXT-files @{b}DIREKT@{ub} von CD-Rom, ohne\n   lästige Kopierei!\n\n - @{b}Komplette C-Shell Bedienung@{ub}, z.B. @{b}TAB@{ub}-Taste für @{b}Pfadnamen-Erweiterung@{ub},\n   das ''@{b}!@{ub}'' Zeichen als Abkürzung von Befehlen im @{b}20-Zeilen Buffer@{ub}, voll-\n   ständige @{b}CRSR-Key@{ub} Simulierung (Hoch/runter für Buffer,links/rechts um\n   in der Zeile hin und her zu laufen) usw...\n\n - Unterstützt auch @{b}UNIX@{ub}-Kommandos, wie z.B. ''@{b}..@{ub}'' für Parent-Dir etc.\n\n - Eingebaute Unterstützung für GUIDE-Dateien, um diese als ANSI-Files\n   umzuwandeln und anzuzeigen\n\n - Benutzt BBS-interne Download- und FlagFile Routinen ohne das man @{b}ALLE@{ub}\n   Pfade in das Icon eintragen muss, daher auch flexibel im CD-Wechsel!\n\n - @{b}Amiex V3.++@{ub} und @{"FAME" LINK FAME} (Final Amiga Mailbox Engine) kompatibel\n\n - Braucht bis auf das Guide2DocProf @{b}KEINE@{ub} weiteren Befehle aus dem C: dir.\n\n - Sau-schnelle Directory-Scan routine mit der selben Ausgabe wie der all-\n   seits bekannte und beliebte Directory Opus :)) \n\n (V1.03)\n\n - Assign-Unterstützung funktioniert 100%-ig.\n\n - Die @{"Registrierte Version" LINK REGVERSION} hat noch mehr Funktionen.... \n\n@{u}Was man alles für den CD-Server braucht@{uu}\n\nBevor Sie dieses Programm installieren, müssen ein paar Bedingungen erfüllt\nsein...zum ersten , haben Sie ein Device (CD0: als Beispiel) oder ein\nDirectory, welches Sie KOMPLETT als Datenträger der BBS zur Verfügung \nstellen können ? \n\nDann ist in der Testphase aufgefallen, das bei Benutzung eines PCMCIA-\nControllers in Verbindung mit einem Mitsumi FX-400 CD-Rom ein Fehler auf-\ngetreten ist beim Anzeigen von Text-files. Dieser Fehler liegt nicht an\nunserer Dummheit (!!!), sondern einzig und allein daran, das dieses \npcmcia.device (oder wie auch immer) den FileInfoBlock von ADOS nicht richtig\nunterstützt, und von daher es zu merkwürdigen Fehlern kommt. Sollte dieses\nbei Ihnen der Fall sein, dann wenden Sie sich bitte an den Author dieses\nDevices, und bitten ihn um ein Update. Soweit es ging werden solche Fehler\ntransparent von CD-Server behandelt, Sie bekommen davon eigentlich nix mit.\n\nDann zu guter letzt iss natürlich klaro, das dieses Tool min. Kickstart V37\noder höher benötigt, aber wer hat schon noch 1.3 ;), und als BBS sollte\nmindestens eine Amiex V3.++ oder höher installiert sein, oder halt die @{"FAME" LINK FAME},\nwobei hier die Version noch nicht wichtig ist..:)\n\n                @{"ZUR INSTALLATION GEHTS HIER LANG :)" LINK INSTALLATION"}\n@endnode\n\n@node INSTALLATION "Wie man CD-Server auf Ihr System installiert."\n@NEXT HOW2USE\n\n@{u}Allgemeine Installation@{uu}\n\nAm besten installieren Sie CD-Server mit Hilfe des beigelegtem Installer-\nSkripts, möchten Sie "per Hand" installieren, sind diese Schritte zu \nbefolgen:\n\n1.Kopieren Sie das Directory ''CD/'' zu Ihrem Doors: Verzeichnis, oder wo immer\n  Sie Ihre BBS-Tools auch aufbewahren.\n\n2.Kopieren Sie das File CD-SERVER.HLP'' nach Ihr S: Directory, dieses File\n  ist die Online-Hilfe von CD-Server.\n\n3.Kopieren Sie das File ''GUIDE2DOCPROF'' nach Ihr C: Directory, dieses File\n  wird zum Umwandeln der AmigaGuides zu ANSI-Files benötigt.\n\n4.Editieren Sie die Tooltypes im Icon ''CD-Server.info'', es werden folgende\n  Tooltypes unterstützt:\n\n  PACKDIR=RAM:      -> Hier können Sie optional ein Directory angeben, \n                       welches dann als temporäres Dir gilt, hierher werden\n                       die umgewandelten Guides geschrieben. Wenn dieses \n                       Tooltype nicht gesetzt ist, wird standardmässig das\n                       T: Directory genommen.\n                           \n  MAX_DEVICES=<NUM> -> Hier legen Sie die maximale Anzahl der zu unter-\n                       stützenden Geräte fest. Fehlt dieses Tooltype, dann\n                       wird von CD-Server automatisch die Anzahl der Geräte\n                       auf 1 gesetzt und als Standard-Gerät wird dann das\n                       Gerät ''CD0:'' genommen.\n\n  DEVICE.<x>=<DEV>  -> Definiert Gerät Nummer <x> als <DEV>, z.B.:\n\n                                 DEVICE.1=CD0:\n                                 DEVICE.2=TREK:\n \n                       Wenn CD-Server nichtmal das ToolType DEVICE.1 findet,\n                       wird als Vorgabe-Gerät ''CD0:'' und als MAX_DEVICES\n                       eins verwendet.\n\n  NAME.<x>=<STRING> -> Hier können Sie für das jeweilige Gerät eine Kurz-\n                       beschreibung angeben, die dann in der Geräteauswahl\n                       angezeigt wird. Wird dieses Tooltype ausgelassen,\n                       zeigt CD-Server als Beschreibung ''N/A!'' an. Die\n                       maximale Länge der Beschreibung darf 60 Zeichen nicht\n                       überschreiten, längere Beschreibungen werden gecuttet.\n                       Beispiele:\n\n                                  NAME.1=AMINET 5 CD\n                                  NAME.2=All about StarTrek: Samples, Pics\n                    \n5.Zu guterletzt müssen Sie CD-Server noch in Ihr BBS-System einbinden. Bitte\n  wählen Sie das System, das bei Ihnen installiert ist : @{"AMIEX" LINK AMIEX_INSTALL} oder @{"FAME" LINK FAME_INSTALL} .\n\n6.Nach einem Reset sollte jetzt CD-Server einsatzbereit sein...\n@endnode\n\n@node AMIEX_INSTALL "CD-Server auf ein Amiex-System installieren."\n@PREV INSTALLATION\n@NEXT INSTALLATION\n\n@{u}Installation für Amiex-Betreiber:@{uu}\n\n1.Erzeugen Sie ein ASSIGN namens ''SERVER:''. Dieses Assign sollte am besten \n  nach T: assigned werden, da T: normalerweise nach RAM:T/ zeigt, und von \n  daher am schnellsten ist. Und keine Panik, ich kopiere keine Files nach \n  ''SERVER:'', CD-Server braucht dieses Assign nur, um mit der AMIEX zu \n  kommunizieren :) \n  Am besten Sie schreiben folgende Zeile in Ihre ''user-startup'' :\n\n                       ASSIGN >NIL: SERVER: T: DEFER\n\n  Wenn Sie CD-Server mit dem Installer installieren, dann wird diese Zeile\n  automatisch in Ihre user-startup eingefügt.\n\n2. Kopieren Sie das Icon ''CD.INFO'' in das Directory ''BBS:COMMANDS/BBSCMD'',\n   und ändern Sie gegebenenfalls den Pfad im Icon zu CD-Server.\n\n3. Editieren Sie alle Conference-Icons, in denen CD-Server laufen soll,\n   und tragen Sie in diese bitte ein neues DLPATH-ToolType ein:\n\n                        DLPATH.(x)=SERVER:\n\n   wobei (x) fuer die nächsthöhere Nummer der DLPATHES im jeweiligen \n   Conference-Icon steht. Angenommen, Sie haben die folgenden Tooltypes in\n   Ihrem AMIGA.INFO Conference-Icon:\n\n                         DLPATH.1=BBS:AMIGA/UPLOAD/\n                         DLPATH.2=DH2:AMIGA/UPLOAD/\n\n   dann tragen Sie für den CD-Server ein :\n\n                         DLPATH.3=SERVER:\n\n   Sie müssen dieses Tooltype in JEDEM Conference-Icon eingeben, in denen auch\n   CD-Server korrekt funktionieren soll...\n\n3. Starten Sie nun Amiex neu, da der Server alle Icons im Speicher behält,\n   und von daher auch nicht auf die Änderungen reagieren kann (Bitte ändern,\n   ByteMaster, das iss ja nu wirklich das letzte...:( ).\n\nDas ist alles für die Installation auf Amiex.\n@endnode\n\n@node FAME_INSTALL "CD-Server auf ein FAME-System installieren."\n@PREV INSTALLATION\n@NEXT INSTALLATION\n\n@{u}Installation für FAME-Betreiber:@{uu}\n\n1. Starten Sie den SystemEditor, gehen Sie in das Menü ''DOORS'', und lesen Sie\n   das File ''CD'' ein, welches diesem Archiv beigefügt ist.\n\n2. Editieren Sie den Pfad zu CD-Server, Accesslevel etc. nach Ihren eigenen\n   Wünschen und speichern Sie es im Directory ''FAME:SETTINGS/DOORS/BBSCMD/''.\n  (Bitte daran denken, das dieses Door als XIM angelegt wird, nicht als FIM!)\n\nDas iss alles für die @{"FAME" LINK FAME}-Installation. Unter @{"FAME" LINK FAME} wird das Assign nicht\nmehr länger benötigt !\n\nNun können Sie bereits den CD-Server antesten...\n@endnode\n\n@node HOW2USE "Übersicht aller Kommandos von CD-Server"\n\n@{u}Kommando-Übersicht@{uu}\n\n  @{b}DOS-KOMMANDOS@{ub}            @{b}AMIEX-KOMMANDOS@{ub}        @{b}ANDERE KOMMANDOS@{ub}\n\n   @{"    CD    " LINK CD}               @{"  FLAG/A/F " LINK FLAG}            @{"   CLEAR   " LINK CLEAR}\n   @{"   .. /   " LINK PARENT}               @{"   DOWN/D  " LINK DOWN}            @{"   VER/$   " LINK VER}\n   @{"   INFO   " LINK INFO}               @{"   VIEW/D  " LINK VIEW}            @{"  HELP/#/? " LINK HELP}\n   @{" LIST/DIR " LINK DIR}               @{"   QUIT/G  " LINK QUIT}            @{"   INDEX   " LINK INDEX}\n   @{"   TYPE   " LINK VIEW}               @{"  ZIPPY/Z  " LINK ZIPPY}            @{"  CHANGE   " LINK CHANGE}\n   @{"  ENDCLI  " LINK QUIT}\n\n@{u}Allgemeine Bedienung@{uu}\n\n @{" ZEILEN-EDITOR " LINK LINE-EDITOR}           @{" DOWNLOADEN " LINK DOWNLOADING}            @{" MARKIEREN " LINK MARK&FLAG}\n@endnode\n\n@node CD "DOS-KOMMANDO : CD - ÄNDERE DIRECTORY"\n\n@{u}CD - Ändere Directory@{uu}\n\nMit diesem Kommando können Sie das aktuelle Directory wechseln, z.B. wenn Sie\nsich im Directory ''CD0:AMINET/'' befinden und Sie möchten in das Directory\n''CD0:AMINET/BIZ/'', dann geben Sie einfach ''CD BIZ/ ein'', und CD-Server \nwechselt zu diesem Directory.\n\nAlle Directories, zu denen Sie wechseln möchten, beziehen sich immer auf das\naktuelle Directory, und sollte CD-Server einmal nicht das Directory wechseln,\ndann ist entweder der Pfadname ein File oder es existiert gar nicht (vom\naktuellen Directory aus gesehen!).\n\nNatürlich müssen Sie nicht jedesmal das CD - Kommando eingeben, einfach nur \ndie Angabe des Pfadnamens reicht ebenfalls aus, um das Dir zu wechseln.\n\n@{u}ACHTUNG:@{uu} Aus Sicherheitsgründen wurde die '':'' Taste deaktiviert, sollte ein\n         User diese Taste drücken, dann wechselt CD-Server automatisch zu dem\n         angegebenen Device (im CD-Server.info).\n\nGucken Sie in das Kapitel @{"LINE-EDITOR" LINK LINE-EDITOR} für weitere Infos über gesperrte\nKommandos/Tasten.\n@endnode\n\n@node PARENT "DOS-KOMMANDO : .. / - GEHE ZUR NÄCHSTHÖHEREN VERZEICHNIS-EBENE"\n\n@{u} .. / - Wechsle zur nächsthöheren Verzeichnisebene@{uu}\n\nMit diesen Kommandos können Sie vom aktuellen Directory aus eine Verzeichnis-\nebene höher gehen. Dies können Sie solange machen, bis Sie zum Hauptver-\nzeichnis des Gerätes/Assigns kommen (z.B. CD0:).\n\nWeitere Informationen über das Wechseln von Dirs können Sie im Kapitel @{"CD" LINK CD}\nlesen.\n@endnode\n\n@node INFO "DOS-KOMMANDO : INFO - GIBT INFO ÜBER VERWENDETES DEVICE AUS."\n\n@{u}INFO - Zeigt Device-Spezifische Informationen an@{uu}\n\nDieses Kommando zeigt die Informationen des Devices an, welches vom CD-Server\nverwendet wird. Beispielsweise sieht die Ausgabe bei mir so aus :\n\nDevice used..: CD0: (AMINET5)                                        \nUnit Number..: 0                                                     \nDisc Status..: Write protected                                       \nR/W Errors...: 0                                                     \nFile-System..: DOS0 (OFS)                                            \n# of Blocks..: 326334                                                \nBytes/Block..: 2048                                                  \nBytes used...: 637 MB                                                \n\nFür weitere Informationen über Devices sehen Sie bitte in Ihrem DOS-Manual\nnach.\n@endnode\n\n@node DIR "DOS-KOMMANDO : DIR - ZEIGT DIRECTORY-INHALT AN."\n\n@{u}LIST / DIR - Zeigt den Inhalt eines Directories an@{uu}\n\nDieses Kommando zeigt Ihnen den Inhalt eines beliebigen Directories an. Geben\nSie keinen Pfadnamen an, dann wird das aktuelle Directory angezeigt. Die \nAusgabe erfolgt genauso wie bei dem bekannten Directory Opus, erst werden\n(natürlich alphabetisch sortiert :) die Dirs angezeigt, danach dann die \nFiles.\n@endnode\n\n@node VIEW "DOS-KOMMANDO : VIEW/V/TYPE - ZEIGT TXT- & GUIDEFILES AN"\n\n@{u}VIEW/V/TYPE - Zeigt TXT- & Amiga-Guide Files an@{uu}\n\nMit diesem Kommando können Sie sich ein beliebiges TXT-File auf dem ver-\nwendeten Datenträger ansehen. Sollte es sich bei dem von Ihnen ausgesuchten\nFile um eine Amiga-Guide Database handeln, und Sie haben das Tool \nGUIDE2DOCPROF von FOX/RMD/ALIENGROUP in das C:-Directory kopiert, dann werden\ndiese Databases umconvertiert und anschliessend als ANSI-File angezeigt.\n\nBenutzer meines mEGA-vIEW''s sollten mit der Bedienung keinerlei Probleme \nhaben, da dies die selbe Routine iss...:)\n\n@{u}ACHTUNG:@{uu} Bitte gucken Sie sich mit diesem Kommando nur TXT- & GUIDE-Files an,\n         bei Binär-Dateien kann es zu merkwürdigen Effekten auf dem Screen\n         kommen! \n@endnode\n\n@node QUIT "DOS-KOMMANDO : ENDCLI/QUIT/Q/G - CD-SERVER BEENDEN."\n\n@{u}ENDCLI/QUIT/Q/G - CD-SERVER BEENDEN@{uu}\n\nMit diesem Kommando beenden Sie CD-Server, die geflaggten Files bleiben jedoch\nerhalten!\n@endnode\n\n@node FLAG "BBS-KOMMANDO : FLAG - MARKIERE FILES FÜR DEN DOWNLOAD."\n\n@{u}FLAG/F/A - Markiere Files zum Downloaden@{uu}\n\nDieses Kommando ist exakt das selbe wie das Flag-Kommando der Amiex (@{"FAME" LINK FAME}\nhat hier mehr zu bieten!) und es unterstützt natürlich auch Multi-Args,z.B.\n\n                       A TEST.LHA TH.LHA LABER.LHA\n\nund die Files ''TEST.LHA'', ''TH.LHA'' & ''LABER.LHA'' werden der Flag-Liste hinzu-\ngefügt (Pfad ist das aktuelle Directory!).\n\nAls spezielle Erweiterung habe ich diesem Flag-Kommando eine Doppelfunktion\nzugewiesen:\n\n                               A C *\n\nDieses Kommando löscht 1. die bbs-interne Flagliste und 2. löscht auch ALLE\nPfade, die sich CD-Server zu diesem Zeitpunkt gemerkt hat. Dieses wird aber\nnur bei der AMIEX gemacht, da die @{"FAME" LINK FAME} dieses Vorgehen nicht benötigt.\nDesweiteren ändert CD-Server das aktuelle Directory zu dem Start-Dir \naus Sicherheitsgründen. \nDies is sozusagen eine Art von ''Warmstart'' des CD-Servers :)))\n\nUnd als zusätzlicher Bonus ist es jetzt auch möglich, beim Flaggen einen \nPfadnamen mit anzugeben, um Files aus anderen Directories zu leechen, z.B. \n\n                  A README AMINET/BIZ/DBASE/DEMO.LHA\n\nDieser Aufruf macht folgendes, 1. wird das File README aus dem aktuellen\nDirectory in die Flagliste aufgenommen, dann wird beim zweiten File der\nPfad vom Filenamen getrennt, der Pfad CD-Server bekannt gemacht (und damit\nauch der AMIEX :), und nur noch der Filename der BBS übergeben. Bei der @{"FAME" LINK FAME}\nwird dieses Vorgehen nicht mehr benötigt, da man dort auch direkt Pfade an-\ngeben kann, daher ist auch das ASSIGN nicht mehr nötig.\nDiese Argumenten-Abfrage funktioniert auch beim Downloaden.\n\n@{u}AMIEX-SYSOPS:@{uu}\n\nNach soviel Vorzügen muß es natürlich auch einen Nachteil geben...und das\nsind die Wildcards ! Sollte in einem Pfadnamen ein ''@{b}*@{ub}'' vorkommen, dann wird\ndie BBS dieses File nicht finden (außer natürlich in den Pfaden auf HD!)..\num dieses Problem zu umgehen, sollten bei Abkürzungen immer die @{"TAB-Taste" LINK LINE-EDITOR}\nverwendet werden, da diese Funktion ja automatisch die Pfadnamen erweitert!\n\n@{u}ACHTUNG:@{uu} Sollte es während dem Transfer zu einem Lost Carrier kommen, und die\n         BBS ist in der Lage, sich die geflaggten Files zu merken, dann müssen\n         Sie unabhängig davon noch einmal in die ganzen Directories gehen, wo\n         Sie sich die Files geflaggt haben, und jeweils einmal ''A'' + Enter\n         eingeben, damit CD-Server die Pfadnamen wieder erkennt.\n\nSollte es trotzdem immer noch Probleme beim Finden der Files finden, dann\nlassen Sie sich @{"registrieren" LINK REGVERSION} und ich gebe Ihnen eine Lösung für dieses\nProblem, auch wenn es nich gerade die eleganteste Art ist...\n\n@{u}FAME-SYSOPS:@{uu}\n\nVergessen Sie alle oben genannten Einschränkungen, nach Absprache mit dem\nAuthor der @{"FAME" LINK FAME} ist es nun möglich, Wildcards zu verwenden, die Geräte zu\nwechseln ohne das die Flaglisten verloren gehen, und sogar das Rausfliegen\nund merken der ''LostCarrierFiles'' läuft perfekt !\n\nFür weitere Infos schauen Sie bitte in das Kapitel @{"MARKIEREN VON FILES" LINK MARK&FLAG} nach.\n@endnode\n\n@node DOWN "AMIEX-KOMMANDO : DOWN/D - DOWNLOADED ALLE GEFLAGGTEN FILES."\n\n@{u}DOWN/D - Downloaden aller geflaggten Files@{uu}\n\nNachdem Sie alle gewünschten Files @{"markiert" LINK FLAG} haben, können Sie mit Hilfe\ndieses Kommandos die Liste der Files downloaden. Da zum Downloaden die \ninternen Funktionen der jeweiligen BBS genommen werden, kann es passieren, \ndaß die BBS plötzlich abbricht und sagt das Sie Ihr Daily Limit überzogen\nhaben! Also achten Sie bitte darauf, das Sie auch wirklich die Anzahl der\nFiles, die Sie geflaggt haben, downloaden können.\n\nWie im Kapitel @{"MARIEREN VON FILES" LINK FLAG} bereits erwähnt wurde, können nach dem\n''D'' - Kommando auch Files (evtl. mit Pfadnamen relativ zum aktuellen Verz.)\nmit angeben werden.\n\nWenn Sie das Download-Kommando eingegeben haben, werden Sie von der BBS\nnoch nach weiteren Filenamen gefragt. Hier können Sie natürlich auch noch\nfiles aus dem Directory, aus dem Sie auch das ''D'' Kommando gestartet haben,\nflaggen, sowie auch Files die in den Normalen Download-Pfaden gefunden werden\nkönnen.\n\nHier dürfen Sie aber keine Pfade mehr mit angeben, da sonst die BBS das\nFlaggen abbricht mit der Meldung:\n\n            YOU DON''T HAVE TO INCLUDE ANY SPECIAL SYMBOLS !\n@endnode\n\n@node ZIPPY "AMIEX-KOMMANDO : ZIPPY SUCHE DATEIEN AUF GERÄTEN ODER IN TEXTEN"\n\n@{u}ZIPPY/Z - Sucht Dateien auf Geräten oder in Textdateien@{uu} (nur reg.Version!)\n\nDieses Kommando erlaubt es Ihnen, nach Dateien auf Geräten,bzw. Directories\nzu suchen oder eine bestimmte Zeichenkette innerhalb einer Textdatei zu\nsuchen. Wenn das Gerätesuchen verwendet wird, kann es je nach verwendetem\nDatenträger zu einigen Minuten Suchzeit kommen, es sollte also besser nach\nMöglichkeit vorher z.B. in einer INDEX Datei nach dem gesuchten Filenamen\ngesucht werden, da diese Methode weitaus schneller und vor allem Geräte-\nschonender ist..:)\n\nBei Verwendung des Textsuchens werden Sie zuerst nach dem zu durchsuchendem\nTextfile gefragt, Sie können hier natürlich auch einen relativen Pfad zum\naktuellen Directory angeben. Existiert dieses File, werden Sie anschliessend\nnach der Suchzeichenkette gefragt. Bitte hier KEINE Patterns verwenden!\nWird diese Zeichenkette gefunden, so springt die Suchfunktion an die Stelle\nim Text und stellt die Zeile, in der die Zeichenkette gefunden wurde, auf\ndem Bildschirm dar. Dabei wird die gesuchte Zeichenkette in Grün hervor-\ngehoben.\n\nWie oben schon erwähnt sollte auf jeden Fall die Textsuche dem Geräte-\nsuchen vorgezogen werden. Sollten Sie jedoch das Gerätesuchen wirklich\neinmal brauchen, dann werden Sie zuerst nach dem zu suchenden Dateinamen\ngefragt. Danach können Sie noch angeben, ob CD-Server rekursiv in allen\nUnter-Directories suchen soll oder die Suche auf das aktuelle Directory\nbeschränken soll. Wird der Dateiname gefunden, werden Sie gefragt, ob Sie\ngleich in das gefundene Directory wechseln wollen oder ob der gefundene\nEintrag nur angezeigt werden soll.\n\n       @{APEN 2}DIESES KOMMANDO IST NUR IN DER REGISTRIERTEN VERSION EINGEBAUT !@{APEN 1}\n@endnode\n\n@node CLEAR "KOMMANDO : CLEAR/CLS - LÖSCHT DEN BILDSCHIRM"\n\n@{u} CLEAR / CLS - Löscht den Bildschirm@{uu}\n\nDieses Kommando löscht den Inhalt des Bildschirmes und setzt den Cursor an\ndie linke obere Ecke. Mehr muß man dazu glaub ich nich schreiben :)\n@endnode\n\n@node VER "KOMMANDO : VER - ZEIGT VERSIONSNUMMER VON CD-SERVER AN"\n\n@{u}VER / $ - Zeigt Version-Informationen an@{uu}\n\nWenn Sie dieses Kommando eingeben, erscheint eine Ausgabe der aktuellen\nVersionsnummer vom CD-Server, sowie das Datum der Compilierung.\n\nNatürlich kann man die Versionsnummer des Programms auch mit dem CLI-\nKommando ''VERSION'' erfragen, für weitere Informationen gucken Sie bitte\nin Ihr Amiga-Dos Manual.\n@endnode\n\n@node HELP "KOMMANDO : HELP/?/# - ZEIGT ONLINE-HILFE AN"\n\n@{u}HELP/?/# - Zeigt die Online-Hilfe an@{uu}\n\nWenn Sie mal gerade nicht wissen, wie ein Kommando heißt, bzw. es aufgerufen\nwird, dann geben Sie eine dieser Zeichenfolgen ein, und CD-Server zeigt das\nHelpfile (S:CD-SERVER.HLP) an.\n\nDa die Geschmäcker der Menschen unterschiedlich sind (Gott sei Dank! :), habe\nich das Helpfile auch extern gehalten, so kann sich das jeder Sysop selbst\nzurecht zimmern...\n@endnode\n\n@node INDEX "KOMMANDO : INDEX - SUCHT NACH INDEX-FILE UND ZEIGT ES AN"\n\n@{u}INDEX - Sucht nach dem Index-File und zeigt es ggf. an@{uu}\n\nDa ich mein CD-Rom eigentlich nur für AMINET-CD''s benutze, habe ich fest-\ngestellt, daß bei diesen Aminet-CD''s immer ein INDEX - File in jedem Dir\nzu finden ist, welches eine kurze Übersicht über das aktuelle Directory\nenthält. Wenn nun jemand etwas bestimmtes sucht, isses wohl leichter, dieses\nFile erstmal zu durchsuchen, als sich alle .readme Dateien anzuschauen. Und\ndafür is halt das Index-Kommando da, wenn sich kein Index in einem Directory\nbefindet, erhält man die Meldung : ''NOTHING TO VIEW !'' .\n\nAber wie gesagt, dieses Kommando ist halt hauptsächlich nur für die AMINET-\nCD''s gedacht, die ich persönlich für das beste an PD überhaupt halte !\n@endnode\n\n@node CHANGE "KOMMANDO : CHANGE - AKTUELLES GERÄT/DIRECTORY ÄNDERN !"\n\n@{u}CHANGE - Ändert aktuelles Gerät/Directory@{uu} (V1.03)\n\nMit diesem Kommando können Sie das aktuelle Gerät, bzw. Directory wechseln.\nBei Verwendung der Amiex werden aus Sicherheitsgründen alle gemerkten Pfade\ngelöscht, wenn Sie also noch geflaggte Files haben, sollten Sie diese vorher\ndownloaden, bevor Sie das CHANGE Kommando benutzen!\n\nBei Verwendung der @{"FAME" LINK FAME} fällt dieses Problem nicht auf, dort bleiben alle\nFlags erhalten, Sie können also ohne Probleme auf ein neues Gerät wechseln,\ndort ein paar Dateien flaggen und dann alle auf einmal downloaden.\n@endnode\n\n@node LINE-EDITOR "WIE MAN EFFIZIENT MIT DEM ZEILEN-EDITOR ARBEITET"\n\n@{u}Benutzung des Zeilen-Editors von CD-Server@{uu}\n\nUm den Usern ein Maximum an Komfort zur Verfügung zu stellen, hat Byte-\nAndi und meine Wenigkeit eine Menge Arbeit in die Entwicklung einer Zeilen-\nEingaberoutine gesteckt. Das Ziel war es, so weit wie möglich (und notwendig)\ndie C-Shell Eingabemöglichkeiten zu simulieren, und dieses ist auch zu 98%\ngelungen möchte ich sagen :) ... hier nun eine Liste aller Kommandos :\n\n1) TAB-Taste. Diese Taste ermöglicht die automatische Filenamen-Erweiterung.\n   Nur das Drücken der Taste veranlasst CD-Server, das aktuelle Dir zu\n   scannen und das erste gefundene File anzuzeigen. Sie können z.B. auch\n   ''AMI'' eingeben und dann TAB drücken, sodaß CD-Server evtl. die folgenden\n   Filenamen findet : AMINET/, AMINET.Z, AMINET usw. Desweiteren ist es auch\n   möglich, ganze Pfade abzukürzen, wie z.B. : \n\n   Sie geben CD */*/*/* ein und drücken dann TAB, dann könnte evtl. folgende\n   Ausgabe erscheinen : AMINET/BIZ/DBASE/DEMO.LHA.\n\n   Dieses funktioniert überall auf dem Prompt, und wir dachten uns das das\n   wohl der beste Ersatz für die ''WildCards'' ist...:)\n\n2) Vollständige Zeilen-Editierung, d.h. das Sie überall innerhalb einer\n   Zeile sich mit den CRSR-links/rechts Tasten bewegen können, Zeichen ein-\n   fügen/löschen können, mit CTRL-X die komplette aktuelle Zeile löschen etc.\n   Aber bitte daran denken, daß dieses @{b}NUR@{ub} :) eine Zeilen-Routine ist, mehr \n   als 80 Zeichen abzüglich des angezeigten Pfadnamens sind derzeit nicht \n   gestattet!\n\n3) History-Buffer mit Abkürzungs-Möglichkeiten. Jede eingegebene Zeile wird\n   in einem internen Buffer gespeichert, dieser Buffer ist im Moment auf 20\n   Zeilen begrenzt, registrierte User können dann natürlich diesen ggf. auf\n   höhere Werte setzen...Wenn Sie die CRSR-Hoch/runter Tasten benutzen, dann\n   wird immer die zuletzt/zuerst eingegebene Zeile dargestellt. Dieser Buffer\n   ist auch die Basis für eine weitere nette Funktion : Das Abkürzen von\n   bereits eingegebenen Befehls-Zeilen! Stellen Sie sich vor Sie arbeiten \n   schon eine Weile mit dem CD-Server, und haben ständig das DIR Kommando\n   eingeben, und das wird nu mittlerweile lästig...dann können Sie auch z.B.\n   !di eingeben (!d geht auch!) und dann würde die Eingaberoutine nach einer\n   dementsprechenden Zeichenkette im Buffer suchen (z.B. DIR) und diese dann\n   ausführen...\n\n4) Abkürzungen der Standard-Befehle. Fast alle Befehle lassen sich durch eine\n   Taste abkürzen, z.B. das Kommando HELP -> H !\n\n5) Gesperrte Taste '':''. Diese Taste musste aus Sicherheitsgründen gesperrt\n   werden. Drücken dieser Taste befördert den User direkt in das Start-Dir,\n   das im Icon angegeben wurde...\n\n@{u}NEW IN V1.03@{uu}\n\n6) Pfadnamen im Prompt werden nun abgeschnitten, wenn sie länger als 30\n   Zeichen sind. In diesem Fall werden nur noch die letzten 27 Zeichen\n   des Pfadnamens angezeigt, am Anfang des Pfadnamens werden dann drei\n   Punkte (...) eingefügt, um anzuzeigen das der Pfadname momentan nicht\n   komplett dargestellt werden kann. Dieses Verfahren erlaubt Ihnen IMMER\n   eine Eingabe von min. 46 Zeichen, unabhängig davon, wie lang der Pfad-\n   name auch ist.\n@endnode\n\n@node DOWNLOADING "TIPS & TRICKS FÜR DIE DOWNLOADING-GESCHICHTE"\n\n@{u}Download@{uu}\n\nWie sich wohl jeder vorstellen kann, iss es nicht einfach, in die Amiex \nWÄHREND diese läuft neue Devices (und damit auch Pfade) einzutragen und \ndiese der Amiex bekannt zu geben. Daher musste ich ein wenig tricksen :),\num das doch klar zumachen. So kann es z.B. bei Multinode-Systemen passieren,\ndas bei gleichzeitiger Benutzung des CD-Servers von mehreren Usern plötzlich\nFiles mehrere Male gefunden werden, dieses ist jedoch normal und ist einer \nder netten Nebeneffekte des Programms..:)\n\nEin anderer wichtiger Punkt ist die Tatsache, das es @{b}UNMÖGLICH@{ub} ist, mehrere\nFiles @{b}GLEICHEN@{ub} Namens auf einmal zu leechen. Das ist damit begründet, daß\nAmiex solange nach einem file sucht bis es dieses gefunden hat. Danach wird\nnach dem nächsten File gesucht, und hat dieses den gleichen Namen wie das\nFile davor, dann wird dieses geskippt.\n\nSollten Sie doch einmal zwei Files gleichen Namens leechen wollen, dann ver-\nfahren Sie bitte wie folgt:\n\nAngenommen, sie wollen das File INDEX aus Directory CD0:AMINET/ und \nDirectory CD0:AMINET/BIZ/ leechen. Dann gehen Sie zuerst in das Dir \nCD0:AMINET/, leechen das File INDEX. Dann geben Sie ''A C *'' ein, um die \ninterne Pfadliste von CD-Server zu löschen, und wechseln dann in das Dir\nCD0:AMINET/BIZ/ und leechen sich von dort das zweite INDEX-File. Sorry für\ndiese Aktion, aber ich denke mal das der gesamte Komfort von CD-Server diese\nkleinen Restriktionen aufheben sollte oder ? :)))\n\nAls kleiner Bonus sei auch nochmal auf eine Sache hingewiesen, die sonst ja\neigentlich nicht möglich ist, und zwar kann man folgendes eingeben:\n\n              d aminet/biz/dbase/data1.lha readme aminet/index\n\nund CD-Server übergibt der BBS dann nur noch die Filenamen DATA1.LHA, README\nund INDEX, merkt sich jedoch auch gleichzeitig die anderen Pfade und übergibt\ndiese mit beim suchen. Diese Funktion ist identisch mit der @{"Mark Funktion" LINK FLAG}.\n\n@{u}ANMERKUNG FÜR FAME-SYSOPS:@{uu}\n\nWas soll ich sagen, @{"FAME" LINK FAME} ist nun in der Lage, dem CD-Server die volle\nKontrolle über die File-Flags zu geben, ohne dieses Assihn benutzen zu\nmüssen. Von daher haben Sie unter @{"FAME" LINK FAME} mit keinerlei Einschränkungen zu\nleben, alles läuft so wie es auch in der BBS geht.\n\nWechseln Sie auf das bessere System...es gibt keine Alternativen mehr !\n@endnode\n\n@node MARK&FLAG "TIPS & TRICKS FÜR DAS FLAGGEN DER FILES"\n\n@{u}Markieren/Flaggen von Files@{uu}\n\n@{u}ANMERKUNGEN FÜR AMIEX-SYSOPS:@{uu}\n\nWie bereits erwähnt, ist die Unterstützung der Wildcards nicht möglich. \nSollte dieser doch angegeben werden, so wird die /X die files nicht finden,\n@{b}ALSO BITTE NICHT BENUTZEN@{ub}, stattdessen nehmen Sie halt die TAB-Taste für die\nPfadnamen-Erweiterung. Dieses Problem ist bisher für Amiex nicht lösbar,da \nder Server der Amiex die Conference-Icons nur einmal beim Start ins Memory \nliest, und dann alle Daten aus dem Speicher holt. Daher reagiert auch Amiex \nnicht auf neu dazugefügte ToolTypes (wie wäre es mit einem Kommando, das \ndie Amiex zwingt, das jeweilige Conference-Icon neu einzulesen, \nByteMaster ???) !!!\n\nAmiex hat noch einen anderen Nachteil beim Markieren von Files, und zwar ist\ndie Liste der geflaggten Files auf 2048 Bytes (oder mehr) inkl. der Spaces\nbegrenzt! Sollte also Amiex beim Flaggen abbrechen, dann ist meistens der \nString dafür voll, und Sie sollten erstmal ein paar Files leechen,bzw. einige\nFiles aus der Liste löschen. Wenn Sie das @{"FAME" LINK FAME}-System fahren, dann wird\ndieses Problem nicht auftreten, da @{"FAME" LINK FAME} ECHTE DYNAMISCHE LISTEN verwendet,\nund von daher nur von Ihrer Hardware begrenzt ist, nicht vom Willen des\nProgrammierers!\n\nWie bereits im Kapitel @{"DOWNLOAD" LINK DOWNLOADING} erwähnt, können Sie auch beim Flaggen von\nFiles einen Pfad mit angeben:\n\n                    A aminet/biz/patch/suxx.lha\n\nund CD-Server flaggt nur noch den Filenamen ''suxx.lha'', behält jedoch den\nPfad im Speicher und übergibt diesen dann auch beim Downloaden der BBS.\n\n@{u}ANMERKUNG FÜR FAME-SYSOPS:@{uu}\n\nKeine Einschränkungen nötig, mit @{"FAME" LINK FAME} läuft ALLES, nur das Sie halt auch\nkomplette Pfadnamen beim Flaggen angeben können..:=)\n@endnode\n\n@node GREETINGS "DIE ALLSEITS BELIEBTEN GRÜßE :)"\n\n@{u}SieGeL & ByteAndi grüßen:@{uu}\n\nSpy/trSi        - For helping us with the Argument-Parsing & the Dirscanning\nDr.Dre!/tRSi    - Berlin roolez!!!!!!!! :()\nsTRIDER/sDC     - For his very cewl @{"FAME" LINK FAME}-System :)) DER SAFT IST MIT DIR!\nARGON           - BW Suxx...\ndEATH aNGEL/sDC - For testing it finally on @{"FAME" LINK FAME} and for being a cewl beta :)\nBloodRock/SDC   - Da ASM-Posse strikes back..:) \nfUTZi/tRSi      - Welcome to our Club :)\n\n ...uND nATÜRLICH aLLE bETATESTER & rEGISTRIERTE uSER fÜR iHRE uNTERSTÜTZUNG,\n\n  aRTCORE! fÜR iHREN mEGA-gEILEN rEQUEST-sERVICE uND aLLE aNDEREN dIE wIR\n\n        hIER vERGESSEN hABEN zU eRWÄHNEN...fÜHLT eUCH gEGRÜSST ! :)\n\n------------------------------------------------------------------------------\n\n                           @{u}Technical Info@{uu}\n\nMain Code & Idea  : SieGeL/tRSi\nAdditional Coding : ByteAndi/tRSi (EDIT-Routine) & Spy/tRSi (Dir-Scanroutine)\nGFX painted by    : (-rAPID-) fROM dA fAMOUS aRTCORE pOSSE !\n\nCD-Server wurde auf zwei A4000/040 entwickelt und erfolgreich auf folgenden\nSystemen getestet : \n\n A5oo  5MB  68ooo           OS 2.o  Amiex 4.9        - SieGeL\nA12oo  6MB  68o2o+68881 Co. OS 3.o  Amiex 4.7        - ARGON\nA12oo 10MB  68o3o+68882 Co. OS 3.o  Amiex 4.7        - BYSIS\nA2ooo 14MB  68o3o+68882 Co. OS 2.o  @{"FAME" LINK FAME}-System      - dEATH aNGEL\nA3ooo 10MB  68o3o+68882 Co. OS 2.o  Amiex 4.6        - Spy\nA4ooo 14MB  68o3o+68882 Co. OS 3.o  @{"FAME" LINK FAME}-System      - sTRIDER\nA4ooo  6MB  68o4o+68o4o Co. OS 3.o  Amiex 4.9        - ByteAndi\nA4ooo 14MB  68o4o+68o4o Co. OS 3.1  @{"FAME" LINK FAME} & Amiex 4.9 - SieGeL\n\n            @{"(tRSi/X-iNNOVATiON) - wO sINDSE dENN ?" LINK ADDY1}\n@endnode\n\n@NODE PRGLIST "LISTE ALLER MEINER PROGRAMME BIS HEUTE !"\n\n@{u}Programm-Liste@{uu}\n\nUm Ihnen einen Überblick zu geben, was Sie als registrierter User bei mir\nbekommen, hier eine Liste aller meiner bisher geschriebenen Programme :\n\n@{b}Zur Zeit für registrierte User verfügbare Prg.:@{ub}\n\nCD-Server V1.03r    - CD-Server für @{"FAME" LINK FAME}/AMIEX\nwORLD-cLOCK V1.18   - Weltzeit-Door für @{"FAME" LINK FAME}/AMIEX\nmEGA-vIEW V2.1      - Bester TXT-Viewer für @{"FAME" LINK FAME}/AMIEX\nlASTCALLERS V0.04   - Lastcaller-Util für @{"FAME" LINK FAME}, faster than SAMILOG!\nsOFT-dEL V1.01      - Schneller Online-Softdel. für @{"FAME" LINK FAME} & AMIEX\nU-sTAT V1.31        - User-Statistik Door, frei konfigurierbar (@{"FAME" LINK FAME} & /X)\nASKII-REQUEST V1.00 - aSKII-Requester Door (AMIEX/@{"FAME" LINK FAME})\npAGE-mASTER v0.73   - Pager-Door für @{"FAME" LINK FAME} mit Highscore-Liste und PW-Option.\nUser-Editor V0.02   - Externer User-Editor für @{"FAME" LINK FAME}, benutzt MUI V2.2++\nmULTI-tOP v0.01     - Multi-BulletinTool für @{"FAME" LINK FAME}, erzeugt 8 Bulletins\nNewFlag v0.01       - Flaggt automatisch alle files der letzten Tage\n\n@{b}Noch in Arbeit,bzw. muß überarbeitet werden:@{ub}\n\noRDER V.02          - VerkaufsTool, um z.B. Hardware über BBS zu verkaufen\nBBS-VIEW V1.13      - CLI-Util zum Anzeigen von ANSI-Pics, 100% ASM!\nU-Convert V0.2      - Util zum Konvert. von /X user.data -> @{"FAME" LINK FAME} user.data\nBullcreator V1.0    - Highscore-Util für ByteKiller V1.0, wird noch geupdated\npAGE-mASTER II      - Amiex Version des pAGE-mASTERS von @{"FAME" LINK FAME}\n\nIch denke mal, 30,- DM (bzw.$20) ist ja wohl nicht zuviel für diese Programme,\noder etwa doch ? Und natürlich werde ich, soweit es machbar ist, auch alle \nWünsche oder Neuheiten in diese Programme einsetzen...um mit uns in Kontakt\nzu treten, bitte mal in Kapitel @{"CONTACTS" LINK ADDY1} nachsehen.\n\n@{u}ANMERKUNG:@{uu}\n\nIch schreibe nebenbei gerade an einer MUI-Version meines mEGA-vIEWS, dieser\nist ein Kommodity, lokalisiert, hat ein AppWindow, arbeitet auf jeden Public\nSchirm usw. Ich brauche für dieses Programm noch BETA-Tester, und es wird\nauch als FreeWare veröffentlicht. Wenn Sie dieses Tool testen möchten, dann\nmelden Sie sich bitte in meiner BBS und dann werden wir das klären...\n\n@endnode\n\n@node FAME "WAS ZUM TEUFEL IS EIGENTLICH FAME ????"\n\n''Was ist FAME ?'' , werden Sie fragen...FAME ist ein neues BBS-System,welches\nvon Strider (Syndicate) geschrieben wird, und zu 90% kompatibel zu Standard-\nAmiexdoors ist. Natürlich hat es auch einen komplett eigenen Msg-Port mit\nweit über 1000 (!!) Kommandos. Desweiteren ist dieses System komplett von\nder verwendeten Hardware abhängig, was bedeutet, um so mehr RAM, umso mehr\nkann man auch durchdrehen...:)\n\nDie Konfiguration der BBS erfolgt über ein sehr komfortablen SystemEditor,\nwelcher VOLLSTÄNDIG OHNE ICONS die BBS konfiguriert und dabei komplett mit\nder Maus zu bedienen ist. Die Kontrolle der BBS läuft über einen ebenfalls\nkomplett mit der Maus bedienbaren Server (Commodity!).\n\nDadurch das die BBS noch in der Entwicklungs-Phase steckt, ist sie derzeit\nauch noch nicht erhältlich, aber wenn Sie weitere Informationen über dieses\nSystem haben wollen, dann melden Sie sich bei uns und wir geben Ihnen dann\nalle Informationen die Sie brauchen.\n@endnode\n\n@node ADDY1 "(tRSi/X-iNNOVATiON) WHQ & Beta Site"\n\nUm mit uns in Kontakt zu treten, schreiben Sie mir entweder über E-Mail:\n\n                     [email removed]\n\noder versuchen Sie unsere Boards anzurufen:\n\n   _____________  __________               /\\\n  |     __     /__\\__      /___________   /  \\             _____\n  |   ________/    /      /_\\____      \\_//   \\___________|_____|_______\n  |     |  \\      /      /      /      _//     \\    ______________      \\_\n  l_____|   \\___________/______/       \\_______/\\______   \\_    l/       /\n                              \\________/      /____________/____/       /\n                                       _________________       \\_______/\n     ______ /\\____ ____________ _______\\______   ______/\n    /      /_      \\    __    /_\\_____      \\_    |\n  _/      \\/______/   _______/\\      /       /    |    · PUN¡sHMeNT ¡NC. ·\n  \\________\\    _/_____________\\____/  Mo!  /_____|\n                /                  \\_______/\n                                           /\\  ______________  ___________\n     1oo% LeGaL sTUFF oN aM¡Ga^PC         /  \\_\\_______      \\_\\    _____/___\n                                         //   \\       /       /     /       /\n     RUNN¡NG oN a4ooo/4o · V.FasT      _//     \\_____/       /_____________/\n                                       \\________/   \\_______/\n\n TR¡sTaR & ReD seCToR ¡NC. (/X·¡NNoVaT¡oN) WHQ, aRTcORE! GHQ & eTH¡C D¡sT s¡Te\n\n   [> +49-(o)-3o-694-84-7o <]  sYsoP: s¡eGeL/TRs¡  [> +49-(o)-3o-694-85-7o! <]\n\n                     @{"> pARALYSIS BBS - dISTRIBUTION sITE <" LINK ADDY2}\n@endnode\n\n@node ADDY2 "(tRSi/X-iNNOVATiON) bETA & dIST SITE"\n       ____                                                                  \n    ___\\  /______________________________________________________________    \n   /   \\\\//                                                              \\   \n  /     \\/ -[ THe BeST eQUiPPeD PuBLIC DoMAIN BoaRD IN BeRLIN ]-          \\  \n /   -[ WiTH 4 GReaT U.S.ROBOTICS V.FAST CLASS MoDeMS WiTH FLaSH-RoMS ]-   \\ \n/                                                                           \\\n\\                        -- -[ SYNDIC/\\TE WHQ ]- --                         /\n \\   _____  _____    _____   _____  __      ___ __  _____   ___ _____      / \n  \\ /  _  \\/  _  \\  /  _  \\ /  _  \\/  |___ /   |  \\/   __)_/ __|   __)_   /  \n   /   |   \\  _   \\/   |  //   _   \\  |   \\\\_____  \\___    \\¯  |___    \\ /   \n  /   _____/  |    \\_ __   \\_  |    \\ |    \\   |    \\|      \\  | |      \\    \n  \\____| \\____|    /___|    /__|    /___   / _______/___    /__|____    /    \n      \\       l___/    l___/   l___/  \\___/___/  [ViC!]\\___/       \\___/     \n       \\                                                             /       \n        \\SYSTeM CHieFS: SPY/TRSi,ARTHuR DeNT,PHaNToM,Cat,JTC,big-rat/        \n         \\                                                         /         \n          \\   1: +49(0) 30 721 6071 USR DuAL STaNDaRD V.34 33.6   /          \n           \\  2: +49(0) 30 721 6072 USR DuAL STaNDaRD V.34 33.6  /           \n            \\ 3: +49(0) 30 721 6073 USR DuAL STaNDaRD V.34 33.6 /            \n             \\4: +49(0) 30 722 6065 USR DuAL STaNDaRD V.34 33.6/             \n              \\                                   /\\          /              \n               \\_________________________________//\\\\________/               \n                                                 /__\\\n\n                        SUPPORTS ONLY PD-/SHAREWARE !\n@endnode\n\n@node REGVERSION "ERWEITERTE REGISTRIERTE VERSION DES CD-SERVERS"\n\n@{u}Zusätze der Registrierten Version des CD-Servers@{uu}\n\nWenn Sie den vollen Support für den CD-Server genießen wollen, dann haben\nSie die Registrierungsgebühr zu bezahlen. Als registrierter User können\nSie mit den folgenden Erweiterungen rechnen:\n\n- Suchfunktionen aktiviert\n- Level-abhängige Geräte/Directories, für Co-Sysops zum C: dir z.B.\n- Interne Pack-Funktionen mit Sysop-einstellbaren Bytebegrenzungen\n- User-konfigurierbarer Dir-Style und andere Optionen (wie Packer etc.)\n\nund natürlich alle Wünsche (soweit realisierbar) für CD-Server oder die\nanderen Programme die @{"HIER" LINK PRGLIST} aufgeführt sind. Es liegt also an Ihnen, die\nWeiterentwicklung der Software zu sichern...\n@endnode\n','\n',char(10)),NULL,'auto-added',71042,7,0,NULL,NULL,'cdser103','scan',1780048442);
INSERT INTO door_catalog VALUES('cdserv','CDSERV.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CDSERV.LHA','CD-SERVER','XIM','CD-SERVER',NULL,'SieGeL',NULL,'\    ____    )  /___/\_| & rED sECTOR ¡NC | .-\___\ | \___\__   /   |  /X-¡NNOVATION   | `---|___|___|______/____|---[ PRESENTS ]---''',replace(' _____________ ___Mo! __.<---[ tRISTAR ]---.\n \    ____    )  /___/\_| & rED sECTOR ¡NC |\n.-\___\ | \___\__   /   |  /X-¡NNOVATION   |\n`---|___|___|______/____|---[ PRESENTS ]---''\n    CD-Server V1.03p by SieGeL & ByteAndi\n.------------------------------------------.\n| FIRST PUBLIC UPDATE,ALL KNOWN BUGS FIXED |\n| NOW WITH MULTIDEVICE- AND ASSIGN-SUPPORT |\n| BETTER FAME-SUPPORT, LONG PATHES WORKING |\n`------------------------------------------''\n A TOOL FROM THE "REAL" (tRSi/X-iNNOVATiON)\n','\n',char(10)),'CD-sERVER_DEUTSCH.guide',replace('@database CD-sERVER V1.03 - Deutsches DataBase\n@author "SieGeL/tRSi"\n@(c) "Copyright © 1995 (tRSi/X-iNNOVATiON)"\n@$VER: CD-SERVER.guide 1.03 (17.08.95)\n\n@index Main\n\n@node Main "CD-Server - BBS Tool geschrieben von SieGeL & ByteAndi (tRSi/X-iNNOVATiON)"\n@{b}                                                                     ______\n .-----------[ TRSI (/X·INNOVATION) ]------------.       _  ________/     /\n | _________________________________       ______`-------\\//  __    \\    /---.\n | \\       _____________     /     /______(______)  _     /    \\     \\  /    |\n |  \\______\\    |    __/   _/\\______       /     | (/)   /     /\\     \\/ Mo! |\n | \\     |      |    \\      \\       |     /      |  ¯   /     / /\\     \\_    |\n | \\\\    l______|_____\\      \\___________/_______|    _/     /_/  \\_____/    |\n `---------------------\\______/-----------------------\\_____/-\\_____/--------''@{ub}\n\n                           iS pROUD tO pRESENT:\n\n@{APEN 2}             CD-Server V1.03 public written by SieGeL & ByteAndi@{APEN 1}\n                                                                          \n                      @{" COPYRIGHT! " LINK COPYRIGHT}     @{"VERTREIBUNG!" LINK DISTRIBUTION}\n                      @{" EINFÜHRUNG " LINK EINFÜHRUNG}     @{"INSTALLATION" LINK INSTALLATION}\n                      @{" BEDIENUNG! " LINK HOW2USE}     @{" -CREDITZ!- " LINK GREETINGS}\n\n Der erste "@{b}ECHTE@{ub}" Server für jedes Amiga-DOS kompatible device,z.B. CD-Rom !\n@endnode\n\n@NODE COPYRIGHT "Copyright-Information für dieses Programm"\n\n     @{u}Copyright@{uu}\n\n   Dieses Programm ist ''FreeWare''.\n\n Es darf frei kopiert und für nicht kommerzielle Zwecke vertrieben werden,\n solange sicher gestellt ist, das kein file (ausser natürlich BBS-Addys)\n zu diesem Archiv dazugepackt oder aus diesem Archiv entnommen wird, und \n das für diese Veröffentlichung nicht mehr Geld, als für die Erstattung des\n Datenträgers/Kopierkosten, notwendig ist, verlangt wird.\n\n Das volle Copyright auf den Programmcode liegt bei dem Author (also meine\n Wenigkeit!) selbst, und ohne meine schriftliche Genehmigung ist es nicht \n erlaubt, dieses Programm kommerziell zu vertreiben.\n\n Diese Version von CD-Server ist die EINZIGSTE, die unter dem Prinzip der\n ''FreeWare'' vertrieben wird, alle anderen Updates (Fehlerbereinigungen etc.)\n sind dann nur noch für registrierte User verfügbar. Wenn Sie registrierter\n User bei mir werden möchten, dann haben Sie eine Registrierungs-Gebühr in\n Höhe von 30.- DM ($20) zu bezahlen.\n\n Diese Registrierungsgebühr ist natürlich nur einmalig zu entrichten, nach\n der Bezahlung erhalten Sie vollen Zugriff auf mein Register-Door und können\n dann frei über ALLE meine Tools verfügen.\n\n Alles weitere können Sie dann mit mir in meiner @{"BBS" LINK ADDY1} besprechen. Einfach\n mal durchcallen und ''SieGeL/tRSi'' eine Mail hinterlassen, ich kläre dann\n alles weitere.\n\n            @{"LISTE ALLER BISHER VON MIR VERFASSTEN PROGRAMME" LINK PRGLIST}\n@endnode\n\n@NODE DISTRIBUTION "Vertreibung von CD-Server"\n\n     @{u}Verbreitung/Vertreibung@{uu}\n\n  Hiermit genehmige ich die Veröffentlichung von diesem Archiv, solange wie\n  nicht mehr Geld, als für die Erstattung der Kopier-kosten etc. notwendig\n  sind, verlangt wird, und solange dieses Archiv nur in seinem Original-\n  zustand vertrieben wird. \n\n  Das Copyright liegt bei dem Author (also mir !) selbst, und ohne meine \n  schriftliche Genehmigung darf dieses Programm nicht kommerziell vertrieben \n  werden.\n@ENDNODE\n\n@node EINFÜHRUNG "Einleitung, oder warum dieses Programm entstanden ist."\n\n@{u}Einleitung@{uu}\n\nVor ein paar Monaten hatten wir die erste Version von dem CD-Server ver-\nöffentlicht, und es hat den Anschein das dieses Tool für Sysops mit CD-Roms\nein nützliches Tool geworden ist...aber wie wir ja alle wissen, ist niemand\nvollkommen, und auch wir haben einige Fehler in der ersten Version gemacht.\n\nNachdem wir die gröbsten Bugs aus der V1.00 entfernt hatten, haben wir uns\ndarauf geeinigt, entgegen der Beschreibung der V1.00 nun doch noch ein\nPublic Update zu releasen, da die V1.00 doch arg heftige Bugs hatte...\n\nNatürlich wurden auch wieder ein paar neue Dinge eingebaut, nun ist es z.B.\nmöglich, Devices & Assigns (!!!) zu verwalten. Um dieses feature zu ver-\nwenden, müssen Sie einfach ein Assign erzeugen, welches auf dem Directory\nzeigt, das Sie auch den Usern zur Verfügung stellen möchten. Dieses Assign\nwird dann im Icon von CD-Server vermerkt, und schon können die User auch\ndieses Assign "besuchen" ...\n\n@{u}Merkmale von CD-Server@{uu}\n\n - Ermöglicht Downloaden/Anzeigen von TXT-files @{b}DIREKT@{ub} von CD-Rom, ohne\n   lästige Kopierei!\n\n - @{b}Komplette C-Shell Bedienung@{ub}, z.B. @{b}TAB@{ub}-Taste für @{b}Pfadnamen-Erweiterung@{ub},\n   das ''@{b}!@{ub}'' Zeichen als Abkürzung von Befehlen im @{b}20-Zeilen Buffer@{ub}, voll-\n   ständige @{b}CRSR-Key@{ub} Simulierung (Hoch/runter für Buffer,links/rechts um\n   in der Zeile hin und her zu laufen) usw...\n\n - Unterstützt auch @{b}UNIX@{ub}-Kommandos, wie z.B. ''@{b}..@{ub}'' für Parent-Dir etc.\n\n - Eingebaute Unterstützung für GUIDE-Dateien, um diese als ANSI-Files\n   umzuwandeln und anzuzeigen\n\n - Benutzt BBS-interne Download- und FlagFile Routinen ohne das man @{b}ALLE@{ub}\n   Pfade in das Icon eintragen muss, daher auch flexibel im CD-Wechsel!\n\n - @{b}Amiex V3.++@{ub} und @{"FAME" LINK FAME} (Final Amiga Mailbox Engine) kompatibel\n\n - Braucht bis auf das Guide2DocProf @{b}KEINE@{ub} weiteren Befehle aus dem C: dir.\n\n - Sau-schnelle Directory-Scan routine mit der selben Ausgabe wie der all-\n   seits bekannte und beliebte Directory Opus :)) \n\n (V1.03)\n\n - Assign-Unterstützung funktioniert 100%-ig.\n\n - Die @{"Registrierte Version" LINK REGVERSION} hat noch mehr Funktionen.... \n\n@{u}Was man alles für den CD-Server braucht@{uu}\n\nBevor Sie dieses Programm installieren, müssen ein paar Bedingungen erfüllt\nsein...zum ersten , haben Sie ein Device (CD0: als Beispiel) oder ein\nDirectory, welches Sie KOMPLETT als Datenträger der BBS zur Verfügung \nstellen können ? \n\nDann ist in der Testphase aufgefallen, das bei Benutzung eines PCMCIA-\nControllers in Verbindung mit einem Mitsumi FX-400 CD-Rom ein Fehler auf-\ngetreten ist beim Anzeigen von Text-files. Dieser Fehler liegt nicht an\nunserer Dummheit (!!!), sondern einzig und allein daran, das dieses \npcmcia.device (oder wie auch immer) den FileInfoBlock von ADOS nicht richtig\nunterstützt, und von daher es zu merkwürdigen Fehlern kommt. Sollte dieses\nbei Ihnen der Fall sein, dann wenden Sie sich bitte an den Author dieses\nDevices, und bitten ihn um ein Update. Soweit es ging werden solche Fehler\ntransparent von CD-Server behandelt, Sie bekommen davon eigentlich nix mit.\n\nDann zu guter letzt iss natürlich klaro, das dieses Tool min. Kickstart V37\noder höher benötigt, aber wer hat schon noch 1.3 ;), und als BBS sollte\nmindestens eine Amiex V3.++ oder höher installiert sein, oder halt die @{"FAME" LINK FAME},\nwobei hier die Version noch nicht wichtig ist..:)\n\n                @{"ZUR INSTALLATION GEHTS HIER LANG :)" LINK INSTALLATION"}\n@endnode\n\n@node INSTALLATION "Wie man CD-Server auf Ihr System installiert."\n@NEXT HOW2USE\n\n@{u}Allgemeine Installation@{uu}\n\nAm besten installieren Sie CD-Server mit Hilfe des beigelegtem Installer-\nSkripts, möchten Sie "per Hand" installieren, sind diese Schritte zu \nbefolgen:\n\n1.Kopieren Sie das Directory ''CD/'' zu Ihrem Doors: Verzeichnis, oder wo immer\n  Sie Ihre BBS-Tools auch aufbewahren.\n\n2.Kopieren Sie das File CD-SERVER.HLP'' nach Ihr S: Directory, dieses File\n  ist die Online-Hilfe von CD-Server.\n\n3.Kopieren Sie das File ''GUIDE2DOCPROF'' nach Ihr C: Directory, dieses File\n  wird zum Umwandeln der AmigaGuides zu ANSI-Files benötigt.\n\n4.Editieren Sie die Tooltypes im Icon ''CD-Server.info'', es werden folgende\n  Tooltypes unterstützt:\n\n  PACKDIR=RAM:      -> Hier können Sie optional ein Directory angeben, \n                       welches dann als temporäres Dir gilt, hierher werden\n                       die umgewandelten Guides geschrieben. Wenn dieses \n                       Tooltype nicht gesetzt ist, wird standardmässig das\n                       T: Directory genommen.\n                           \n  MAX_DEVICES=<NUM> -> Hier legen Sie die maximale Anzahl der zu unter-\n                       stützenden Geräte fest. Fehlt dieses Tooltype, dann\n                       wird von CD-Server automatisch die Anzahl der Geräte\n                       auf 1 gesetzt und als Standard-Gerät wird dann das\n                       Gerät ''CD0:'' genommen.\n\n  DEVICE.<x>=<DEV>  -> Definiert Gerät Nummer <x> als <DEV>, z.B.:\n\n                                 DEVICE.1=CD0:\n                                 DEVICE.2=TREK:\n \n                       Wenn CD-Server nichtmal das ToolType DEVICE.1 findet,\n                       wird als Vorgabe-Gerät ''CD0:'' und als MAX_DEVICES\n                       eins verwendet.\n\n  NAME.<x>=<STRING> -> Hier können Sie für das jeweilige Gerät eine Kurz-\n                       beschreibung angeben, die dann in der Geräteauswahl\n                       angezeigt wird. Wird dieses Tooltype ausgelassen,\n                       zeigt CD-Server als Beschreibung ''N/A!'' an. Die\n                       maximale Länge der Beschreibung darf 60 Zeichen nicht\n                       überschreiten, längere Beschreibungen werden gecuttet.\n                       Beispiele:\n\n                                  NAME.1=AMINET 5 CD\n                                  NAME.2=All about StarTrek: Samples, Pics\n                    \n5.Zu guterletzt müssen Sie CD-Server noch in Ihr BBS-System einbinden. Bitte\n  wählen Sie das System, das bei Ihnen installiert ist : @{"AMIEX" LINK AMIEX_INSTALL} oder @{"FAME" LINK FAME_INSTALL} .\n\n6.Nach einem Reset sollte jetzt CD-Server einsatzbereit sein...\n@endnode\n\n@node AMIEX_INSTALL "CD-Server auf ein Amiex-System installieren."\n@PREV INSTALLATION\n@NEXT INSTALLATION\n\n@{u}Installation für Amiex-Betreiber:@{uu}\n\n1.Erzeugen Sie ein ASSIGN namens ''SERVER:''. Dieses Assign sollte am besten \n  nach T: assigned werden, da T: normalerweise nach RAM:T/ zeigt, und von \n  daher am schnellsten ist. Und keine Panik, ich kopiere keine Files nach \n  ''SERVER:'', CD-Server braucht dieses Assign nur, um mit der AMIEX zu \n  kommunizieren :) \n  Am besten Sie schreiben folgende Zeile in Ihre ''user-startup'' :\n\n                       ASSIGN >NIL: SERVER: T: DEFER\n\n  Wenn Sie CD-Server mit dem Installer installieren, dann wird diese Zeile\n  automatisch in Ihre user-startup eingefügt.\n\n2. Kopieren Sie das Icon ''CD.INFO'' in das Directory ''BBS:COMMANDS/BBSCMD'',\n   und ändern Sie gegebenenfalls den Pfad im Icon zu CD-Server.\n\n3. Editieren Sie alle Conference-Icons, in denen CD-Server laufen soll,\n   und tragen Sie in diese bitte ein neues DLPATH-ToolType ein:\n\n                        DLPATH.(x)=SERVER:\n\n   wobei (x) fuer die nächsthöhere Nummer der DLPATHES im jeweiligen \n   Conference-Icon steht. Angenommen, Sie haben die folgenden Tooltypes in\n   Ihrem AMIGA.INFO Conference-Icon:\n\n                         DLPATH.1=BBS:AMIGA/UPLOAD/\n                         DLPATH.2=DH2:AMIGA/UPLOAD/\n\n   dann tragen Sie für den CD-Server ein :\n\n                         DLPATH.3=SERVER:\n\n   Sie müssen dieses Tooltype in JEDEM Conference-Icon eingeben, in denen auch\n   CD-Server korrekt funktionieren soll...\n\n3. Starten Sie nun Amiex neu, da der Server alle Icons im Speicher behält,\n   und von daher auch nicht auf die Änderungen reagieren kann (Bitte ändern,\n   ByteMaster, das iss ja nu wirklich das letzte...:( ).\n\nDas ist alles für die Installation auf Amiex.\n@endnode\n\n@node FAME_INSTALL "CD-Server auf ein FAME-System installieren."\n@PREV INSTALLATION\n@NEXT INSTALLATION\n\n@{u}Installation für FAME-Betreiber:@{uu}\n\n1. Starten Sie den SystemEditor, gehen Sie in das Menü ''DOORS'', und lesen Sie\n   das File ''CD'' ein, welches diesem Archiv beigefügt ist.\n\n2. Editieren Sie den Pfad zu CD-Server, Accesslevel etc. nach Ihren eigenen\n   Wünschen und speichern Sie es im Directory ''FAME:SETTINGS/DOORS/BBSCMD/''.\n  (Bitte daran denken, das dieses Door als XIM angelegt wird, nicht als FIM!)\n\nDas iss alles für die @{"FAME" LINK FAME}-Installation. Unter @{"FAME" LINK FAME} wird das Assign nicht\nmehr länger benötigt !\n\nNun können Sie bereits den CD-Server antesten...\n@endnode\n\n@node HOW2USE "Übersicht aller Kommandos von CD-Server"\n\n@{u}Kommando-Übersicht@{uu}\n\n  @{b}DOS-KOMMANDOS@{ub}            @{b}AMIEX-KOMMANDOS@{ub}        @{b}ANDERE KOMMANDOS@{ub}\n\n   @{"    CD    " LINK CD}               @{"  FLAG/A/F " LINK FLAG}            @{"   CLEAR   " LINK CLEAR}\n   @{"   .. /   " LINK PARENT}               @{"   DOWN/D  " LINK DOWN}            @{"   VER/$   " LINK VER}\n   @{"   INFO   " LINK INFO}               @{"   VIEW/D  " LINK VIEW}            @{"  HELP/#/? " LINK HELP}\n   @{" LIST/DIR " LINK DIR}               @{"   QUIT/G  " LINK QUIT}            @{"   INDEX   " LINK INDEX}\n   @{"   TYPE   " LINK VIEW}               @{"  ZIPPY/Z  " LINK ZIPPY}            @{"  CHANGE   " LINK CHANGE}\n   @{"  ENDCLI  " LINK QUIT}\n\n@{u}Allgemeine Bedienung@{uu}\n\n @{" ZEILEN-EDITOR " LINK LINE-EDITOR}           @{" DOWNLOADEN " LINK DOWNLOADING}            @{" MARKIEREN " LINK MARK&FLAG}\n@endnode\n\n@node CD "DOS-KOMMANDO : CD - ÄNDERE DIRECTORY"\n\n@{u}CD - Ändere Directory@{uu}\n\nMit diesem Kommando können Sie das aktuelle Directory wechseln, z.B. wenn Sie\nsich im Directory ''CD0:AMINET/'' befinden und Sie möchten in das Directory\n''CD0:AMINET/BIZ/'', dann geben Sie einfach ''CD BIZ/ ein'', und CD-Server \nwechselt zu diesem Directory.\n\nAlle Directories, zu denen Sie wechseln möchten, beziehen sich immer auf das\naktuelle Directory, und sollte CD-Server einmal nicht das Directory wechseln,\ndann ist entweder der Pfadname ein File oder es existiert gar nicht (vom\naktuellen Directory aus gesehen!).\n\nNatürlich müssen Sie nicht jedesmal das CD - Kommando eingeben, einfach nur \ndie Angabe des Pfadnamens reicht ebenfalls aus, um das Dir zu wechseln.\n\n@{u}ACHTUNG:@{uu} Aus Sicherheitsgründen wurde die '':'' Taste deaktiviert, sollte ein\n         User diese Taste drücken, dann wechselt CD-Server automatisch zu dem\n         angegebenen Device (im CD-Server.info).\n\nGucken Sie in das Kapitel @{"LINE-EDITOR" LINK LINE-EDITOR} für weitere Infos über gesperrte\nKommandos/Tasten.\n@endnode\n\n@node PARENT "DOS-KOMMANDO : .. / - GEHE ZUR NÄCHSTHÖHEREN VERZEICHNIS-EBENE"\n\n@{u} .. / - Wechsle zur nächsthöheren Verzeichnisebene@{uu}\n\nMit diesen Kommandos können Sie vom aktuellen Directory aus eine Verzeichnis-\nebene höher gehen. Dies können Sie solange machen, bis Sie zum Hauptver-\nzeichnis des Gerätes/Assigns kommen (z.B. CD0:).\n\nWeitere Informationen über das Wechseln von Dirs können Sie im Kapitel @{"CD" LINK CD}\nlesen.\n@endnode\n\n@node INFO "DOS-KOMMANDO : INFO - GIBT INFO ÜBER VERWENDETES DEVICE AUS."\n\n@{u}INFO - Zeigt Device-Spezifische Informationen an@{uu}\n\nDieses Kommando zeigt die Informationen des Devices an, welches vom CD-Server\nverwendet wird. Beispielsweise sieht die Ausgabe bei mir so aus :\n\nDevice used..: CD0: (AMINET5)                                        \nUnit Number..: 0                                                     \nDisc Status..: Write protected                                       \nR/W Errors...: 0                                                     \nFile-System..: DOS0 (OFS)                                            \n# of Blocks..: 326334                                                \nBytes/Block..: 2048                                                  \nBytes used...: 637 MB                                                \n\nFür weitere Informationen über Devices sehen Sie bitte in Ihrem DOS-Manual\nnach.\n@endnode\n\n@node DIR "DOS-KOMMANDO : DIR - ZEIGT DIRECTORY-INHALT AN."\n\n@{u}LIST / DIR - Zeigt den Inhalt eines Directories an@{uu}\n\nDieses Kommando zeigt Ihnen den Inhalt eines beliebigen Directories an. Geben\nSie keinen Pfadnamen an, dann wird das aktuelle Directory angezeigt. Die \nAusgabe erfolgt genauso wie bei dem bekannten Directory Opus, erst werden\n(natürlich alphabetisch sortiert :) die Dirs angezeigt, danach dann die \nFiles.\n@endnode\n\n@node VIEW "DOS-KOMMANDO : VIEW/V/TYPE - ZEIGT TXT- & GUIDEFILES AN"\n\n@{u}VIEW/V/TYPE - Zeigt TXT- & Amiga-Guide Files an@{uu}\n\nMit diesem Kommando können Sie sich ein beliebiges TXT-File auf dem ver-\nwendeten Datenträger ansehen. Sollte es sich bei dem von Ihnen ausgesuchten\nFile um eine Amiga-Guide Database handeln, und Sie haben das Tool \nGUIDE2DOCPROF von FOX/RMD/ALIENGROUP in das C:-Directory kopiert, dann werden\ndiese Databases umconvertiert und anschliessend als ANSI-File angezeigt.\n\nBenutzer meines mEGA-vIEW''s sollten mit der Bedienung keinerlei Probleme \nhaben, da dies die selbe Routine iss...:)\n\n@{u}ACHTUNG:@{uu} Bitte gucken Sie sich mit diesem Kommando nur TXT- & GUIDE-Files an,\n         bei Binär-Dateien kann es zu merkwürdigen Effekten auf dem Screen\n         kommen! \n@endnode\n\n@node QUIT "DOS-KOMMANDO : ENDCLI/QUIT/Q/G - CD-SERVER BEENDEN."\n\n@{u}ENDCLI/QUIT/Q/G - CD-SERVER BEENDEN@{uu}\n\nMit diesem Kommando beenden Sie CD-Server, die geflaggten Files bleiben jedoch\nerhalten!\n@endnode\n\n@node FLAG "BBS-KOMMANDO : FLAG - MARKIERE FILES FÜR DEN DOWNLOAD."\n\n@{u}FLAG/F/A - Markiere Files zum Downloaden@{uu}\n\nDieses Kommando ist exakt das selbe wie das Flag-Kommando der Amiex (@{"FAME" LINK FAME}\nhat hier mehr zu bieten!) und es unterstützt natürlich auch Multi-Args,z.B.\n\n                       A TEST.LHA TH.LHA LABER.LHA\n\nund die Files ''TEST.LHA'', ''TH.LHA'' & ''LABER.LHA'' werden der Flag-Liste hinzu-\ngefügt (Pfad ist das aktuelle Directory!).\n\nAls spezielle Erweiterung habe ich diesem Flag-Kommando eine Doppelfunktion\nzugewiesen:\n\n                               A C *\n\nDieses Kommando löscht 1. die bbs-interne Flagliste und 2. löscht auch ALLE\nPfade, die sich CD-Server zu diesem Zeitpunkt gemerkt hat. Dieses wird aber\nnur bei der AMIEX gemacht, da die @{"FAME" LINK FAME} dieses Vorgehen nicht benötigt.\nDesweiteren ändert CD-Server das aktuelle Directory zu dem Start-Dir \naus Sicherheitsgründen. \nDies is sozusagen eine Art von ''Warmstart'' des CD-Servers :)))\n\nUnd als zusätzlicher Bonus ist es jetzt auch möglich, beim Flaggen einen \nPfadnamen mit anzugeben, um Files aus anderen Directories zu leechen, z.B. \n\n                  A README AMINET/BIZ/DBASE/DEMO.LHA\n\nDieser Aufruf macht folgendes, 1. wird das File README aus dem aktuellen\nDirectory in die Flagliste aufgenommen, dann wird beim zweiten File der\nPfad vom Filenamen getrennt, der Pfad CD-Server bekannt gemacht (und damit\nauch der AMIEX :), und nur noch der Filename der BBS übergeben. Bei der @{"FAME" LINK FAME}\nwird dieses Vorgehen nicht mehr benötigt, da man dort auch direkt Pfade an-\ngeben kann, daher ist auch das ASSIGN nicht mehr nötig.\nDiese Argumenten-Abfrage funktioniert auch beim Downloaden.\n\n@{u}AMIEX-SYSOPS:@{uu}\n\nNach soviel Vorzügen muß es natürlich auch einen Nachteil geben...und das\nsind die Wildcards ! Sollte in einem Pfadnamen ein ''@{b}*@{ub}'' vorkommen, dann wird\ndie BBS dieses File nicht finden (außer natürlich in den Pfaden auf HD!)..\num dieses Problem zu umgehen, sollten bei Abkürzungen immer die @{"TAB-Taste" LINK LINE-EDITOR}\nverwendet werden, da diese Funktion ja automatisch die Pfadnamen erweitert!\n\n@{u}ACHTUNG:@{uu} Sollte es während dem Transfer zu einem Lost Carrier kommen, und die\n         BBS ist in der Lage, sich die geflaggten Files zu merken, dann müssen\n         Sie unabhängig davon noch einmal in die ganzen Directories gehen, wo\n         Sie sich die Files geflaggt haben, und jeweils einmal ''A'' + Enter\n         eingeben, damit CD-Server die Pfadnamen wieder erkennt.\n\nSollte es trotzdem immer noch Probleme beim Finden der Files finden, dann\nlassen Sie sich @{"registrieren" LINK REGVERSION} und ich gebe Ihnen eine Lösung für dieses\nProblem, auch wenn es nich gerade die eleganteste Art ist...\n\n@{u}FAME-SYSOPS:@{uu}\n\nVergessen Sie alle oben genannten Einschränkungen, nach Absprache mit dem\nAuthor der @{"FAME" LINK FAME} ist es nun möglich, Wildcards zu verwenden, die Geräte zu\nwechseln ohne das die Flaglisten verloren gehen, und sogar das Rausfliegen\nund merken der ''LostCarrierFiles'' läuft perfekt !\n\nFür weitere Infos schauen Sie bitte in das Kapitel @{"MARKIEREN VON FILES" LINK MARK&FLAG} nach.\n@endnode\n\n@node DOWN "AMIEX-KOMMANDO : DOWN/D - DOWNLOADED ALLE GEFLAGGTEN FILES."\n\n@{u}DOWN/D - Downloaden aller geflaggten Files@{uu}\n\nNachdem Sie alle gewünschten Files @{"markiert" LINK FLAG} haben, können Sie mit Hilfe\ndieses Kommandos die Liste der Files downloaden. Da zum Downloaden die \ninternen Funktionen der jeweiligen BBS genommen werden, kann es passieren, \ndaß die BBS plötzlich abbricht und sagt das Sie Ihr Daily Limit überzogen\nhaben! Also achten Sie bitte darauf, das Sie auch wirklich die Anzahl der\nFiles, die Sie geflaggt haben, downloaden können.\n\nWie im Kapitel @{"MARIEREN VON FILES" LINK FLAG} bereits erwähnt wurde, können nach dem\n''D'' - Kommando auch Files (evtl. mit Pfadnamen relativ zum aktuellen Verz.)\nmit angeben werden.\n\nWenn Sie das Download-Kommando eingegeben haben, werden Sie von der BBS\nnoch nach weiteren Filenamen gefragt. Hier können Sie natürlich auch noch\nfiles aus dem Directory, aus dem Sie auch das ''D'' Kommando gestartet haben,\nflaggen, sowie auch Files die in den Normalen Download-Pfaden gefunden werden\nkönnen.\n\nHier dürfen Sie aber keine Pfade mehr mit angeben, da sonst die BBS das\nFlaggen abbricht mit der Meldung:\n\n            YOU DON''T HAVE TO INCLUDE ANY SPECIAL SYMBOLS !\n@endnode\n\n@node ZIPPY "AMIEX-KOMMANDO : ZIPPY SUCHE DATEIEN AUF GERÄTEN ODER IN TEXTEN"\n\n@{u}ZIPPY/Z - Sucht Dateien auf Geräten oder in Textdateien@{uu} (nur reg.Version!)\n\nDieses Kommando erlaubt es Ihnen, nach Dateien auf Geräten,bzw. Directories\nzu suchen oder eine bestimmte Zeichenkette innerhalb einer Textdatei zu\nsuchen. Wenn das Gerätesuchen verwendet wird, kann es je nach verwendetem\nDatenträger zu einigen Minuten Suchzeit kommen, es sollte also besser nach\nMöglichkeit vorher z.B. in einer INDEX Datei nach dem gesuchten Filenamen\ngesucht werden, da diese Methode weitaus schneller und vor allem Geräte-\nschonender ist..:)\n\nBei Verwendung des Textsuchens werden Sie zuerst nach dem zu durchsuchendem\nTextfile gefragt, Sie können hier natürlich auch einen relativen Pfad zum\naktuellen Directory angeben. Existiert dieses File, werden Sie anschliessend\nnach der Suchzeichenkette gefragt. Bitte hier KEINE Patterns verwenden!\nWird diese Zeichenkette gefunden, so springt die Suchfunktion an die Stelle\nim Text und stellt die Zeile, in der die Zeichenkette gefunden wurde, auf\ndem Bildschirm dar. Dabei wird die gesuchte Zeichenkette in Grün hervor-\ngehoben.\n\nWie oben schon erwähnt sollte auf jeden Fall die Textsuche dem Geräte-\nsuchen vorgezogen werden. Sollten Sie jedoch das Gerätesuchen wirklich\neinmal brauchen, dann werden Sie zuerst nach dem zu suchenden Dateinamen\ngefragt. Danach können Sie noch angeben, ob CD-Server rekursiv in allen\nUnter-Directories suchen soll oder die Suche auf das aktuelle Directory\nbeschränken soll. Wird der Dateiname gefunden, werden Sie gefragt, ob Sie\ngleich in das gefundene Directory wechseln wollen oder ob der gefundene\nEintrag nur angezeigt werden soll.\n\n       @{APEN 2}DIESES KOMMANDO IST NUR IN DER REGISTRIERTEN VERSION EINGEBAUT !@{APEN 1}\n@endnode\n\n@node CLEAR "KOMMANDO : CLEAR/CLS - LÖSCHT DEN BILDSCHIRM"\n\n@{u} CLEAR / CLS - Löscht den Bildschirm@{uu}\n\nDieses Kommando löscht den Inhalt des Bildschirmes und setzt den Cursor an\ndie linke obere Ecke. Mehr muß man dazu glaub ich nich schreiben :)\n@endnode\n\n@node VER "KOMMANDO : VER - ZEIGT VERSIONSNUMMER VON CD-SERVER AN"\n\n@{u}VER / $ - Zeigt Version-Informationen an@{uu}\n\nWenn Sie dieses Kommando eingeben, erscheint eine Ausgabe der aktuellen\nVersionsnummer vom CD-Server, sowie das Datum der Compilierung.\n\nNatürlich kann man die Versionsnummer des Programms auch mit dem CLI-\nKommando ''VERSION'' erfragen, für weitere Informationen gucken Sie bitte\nin Ihr Amiga-Dos Manual.\n@endnode\n\n@node HELP "KOMMANDO : HELP/?/# - ZEIGT ONLINE-HILFE AN"\n\n@{u}HELP/?/# - Zeigt die Online-Hilfe an@{uu}\n\nWenn Sie mal gerade nicht wissen, wie ein Kommando heißt, bzw. es aufgerufen\nwird, dann geben Sie eine dieser Zeichenfolgen ein, und CD-Server zeigt das\nHelpfile (S:CD-SERVER.HLP) an.\n\nDa die Geschmäcker der Menschen unterschiedlich sind (Gott sei Dank! :), habe\nich das Helpfile auch extern gehalten, so kann sich das jeder Sysop selbst\nzurecht zimmern...\n@endnode\n\n@node INDEX "KOMMANDO : INDEX - SUCHT NACH INDEX-FILE UND ZEIGT ES AN"\n\n@{u}INDEX - Sucht nach dem Index-File und zeigt es ggf. an@{uu}\n\nDa ich mein CD-Rom eigentlich nur für AMINET-CD''s benutze, habe ich fest-\ngestellt, daß bei diesen Aminet-CD''s immer ein INDEX - File in jedem Dir\nzu finden ist, welches eine kurze Übersicht über das aktuelle Directory\nenthält. Wenn nun jemand etwas bestimmtes sucht, isses wohl leichter, dieses\nFile erstmal zu durchsuchen, als sich alle .readme Dateien anzuschauen. Und\ndafür is halt das Index-Kommando da, wenn sich kein Index in einem Directory\nbefindet, erhält man die Meldung : ''NOTHING TO VIEW !'' .\n\nAber wie gesagt, dieses Kommando ist halt hauptsächlich nur für die AMINET-\nCD''s gedacht, die ich persönlich für das beste an PD überhaupt halte !\n@endnode\n\n@node CHANGE "KOMMANDO : CHANGE - AKTUELLES GERÄT/DIRECTORY ÄNDERN !"\n\n@{u}CHANGE - Ändert aktuelles Gerät/Directory@{uu} (V1.03)\n\nMit diesem Kommando können Sie das aktuelle Gerät, bzw. Directory wechseln.\nBei Verwendung der Amiex werden aus Sicherheitsgründen alle gemerkten Pfade\ngelöscht, wenn Sie also noch geflaggte Files haben, sollten Sie diese vorher\ndownloaden, bevor Sie das CHANGE Kommando benutzen!\n\nBei Verwendung der @{"FAME" LINK FAME} fällt dieses Problem nicht auf, dort bleiben alle\nFlags erhalten, Sie können also ohne Probleme auf ein neues Gerät wechseln,\ndort ein paar Dateien flaggen und dann alle auf einmal downloaden.\n@endnode\n\n@node LINE-EDITOR "WIE MAN EFFIZIENT MIT DEM ZEILEN-EDITOR ARBEITET"\n\n@{u}Benutzung des Zeilen-Editors von CD-Server@{uu}\n\nUm den Usern ein Maximum an Komfort zur Verfügung zu stellen, hat Byte-\nAndi und meine Wenigkeit eine Menge Arbeit in die Entwicklung einer Zeilen-\nEingaberoutine gesteckt. Das Ziel war es, so weit wie möglich (und notwendig)\ndie C-Shell Eingabemöglichkeiten zu simulieren, und dieses ist auch zu 98%\ngelungen möchte ich sagen :) ... hier nun eine Liste aller Kommandos :\n\n1) TAB-Taste. Diese Taste ermöglicht die automatische Filenamen-Erweiterung.\n   Nur das Drücken der Taste veranlasst CD-Server, das aktuelle Dir zu\n   scannen und das erste gefundene File anzuzeigen. Sie können z.B. auch\n   ''AMI'' eingeben und dann TAB drücken, sodaß CD-Server evtl. die folgenden\n   Filenamen findet : AMINET/, AMINET.Z, AMINET usw. Desweiteren ist es auch\n   möglich, ganze Pfade abzukürzen, wie z.B. : \n\n   Sie geben CD */*/*/* ein und drücken dann TAB, dann könnte evtl. folgende\n   Ausgabe erscheinen : AMINET/BIZ/DBASE/DEMO.LHA.\n\n   Dieses funktioniert überall auf dem Prompt, und wir dachten uns das das\n   wohl der beste Ersatz für die ''WildCards'' ist...:)\n\n2) Vollständige Zeilen-Editierung, d.h. das Sie überall innerhalb einer\n   Zeile sich mit den CRSR-links/rechts Tasten bewegen können, Zeichen ein-\n   fügen/löschen können, mit CTRL-X die komplette aktuelle Zeile löschen etc.\n   Aber bitte daran denken, daß dieses @{b}NUR@{ub} :) eine Zeilen-Routine ist, mehr \n   als 80 Zeichen abzüglich des angezeigten Pfadnamens sind derzeit nicht \n   gestattet!\n\n3) History-Buffer mit Abkürzungs-Möglichkeiten. Jede eingegebene Zeile wird\n   in einem internen Buffer gespeichert, dieser Buffer ist im Moment auf 20\n   Zeilen begrenzt, registrierte User können dann natürlich diesen ggf. auf\n   höhere Werte setzen...Wenn Sie die CRSR-Hoch/runter Tasten benutzen, dann\n   wird immer die zuletzt/zuerst eingegebene Zeile dargestellt. Dieser Buffer\n   ist auch die Basis für eine weitere nette Funktion : Das Abkürzen von\n   bereits eingegebenen Befehls-Zeilen! Stellen Sie sich vor Sie arbeiten \n   schon eine Weile mit dem CD-Server, und haben ständig das DIR Kommando\n   eingeben, und das wird nu mittlerweile lästig...dann können Sie auch z.B.\n   !di eingeben (!d geht auch!) und dann würde die Eingaberoutine nach einer\n   dementsprechenden Zeichenkette im Buffer suchen (z.B. DIR) und diese dann\n   ausführen...\n\n4) Abkürzungen der Standard-Befehle. Fast alle Befehle lassen sich durch eine\n   Taste abkürzen, z.B. das Kommando HELP -> H !\n\n5) Gesperrte Taste '':''. Diese Taste musste aus Sicherheitsgründen gesperrt\n   werden. Drücken dieser Taste befördert den User direkt in das Start-Dir,\n   das im Icon angegeben wurde...\n\n@{u}NEW IN V1.03@{uu}\n\n6) Pfadnamen im Prompt werden nun abgeschnitten, wenn sie länger als 30\n   Zeichen sind. In diesem Fall werden nur noch die letzten 27 Zeichen\n   des Pfadnamens angezeigt, am Anfang des Pfadnamens werden dann drei\n   Punkte (...) eingefügt, um anzuzeigen das der Pfadname momentan nicht\n   komplett dargestellt werden kann. Dieses Verfahren erlaubt Ihnen IMMER\n   eine Eingabe von min. 46 Zeichen, unabhängig davon, wie lang der Pfad-\n   name auch ist.\n@endnode\n\n@node DOWNLOADING "TIPS & TRICKS FÜR DIE DOWNLOADING-GESCHICHTE"\n\n@{u}Download@{uu}\n\nWie sich wohl jeder vorstellen kann, iss es nicht einfach, in die Amiex \nWÄHREND diese läuft neue Devices (und damit auch Pfade) einzutragen und \ndiese der Amiex bekannt zu geben. Daher musste ich ein wenig tricksen :),\num das doch klar zumachen. So kann es z.B. bei Multinode-Systemen passieren,\ndas bei gleichzeitiger Benutzung des CD-Servers von mehreren Usern plötzlich\nFiles mehrere Male gefunden werden, dieses ist jedoch normal und ist einer \nder netten Nebeneffekte des Programms..:)\n\nEin anderer wichtiger Punkt ist die Tatsache, das es @{b}UNMÖGLICH@{ub} ist, mehrere\nFiles @{b}GLEICHEN@{ub} Namens auf einmal zu leechen. Das ist damit begründet, daß\nAmiex solange nach einem file sucht bis es dieses gefunden hat. Danach wird\nnach dem nächsten File gesucht, und hat dieses den gleichen Namen wie das\nFile davor, dann wird dieses geskippt.\n\nSollten Sie doch einmal zwei Files gleichen Namens leechen wollen, dann ver-\nfahren Sie bitte wie folgt:\n\nAngenommen, sie wollen das File INDEX aus Directory CD0:AMINET/ und \nDirectory CD0:AMINET/BIZ/ leechen. Dann gehen Sie zuerst in das Dir \nCD0:AMINET/, leechen das File INDEX. Dann geben Sie ''A C *'' ein, um die \ninterne Pfadliste von CD-Server zu löschen, und wechseln dann in das Dir\nCD0:AMINET/BIZ/ und leechen sich von dort das zweite INDEX-File. Sorry für\ndiese Aktion, aber ich denke mal das der gesamte Komfort von CD-Server diese\nkleinen Restriktionen aufheben sollte oder ? :)))\n\nAls kleiner Bonus sei auch nochmal auf eine Sache hingewiesen, die sonst ja\neigentlich nicht möglich ist, und zwar kann man folgendes eingeben:\n\n              d aminet/biz/dbase/data1.lha readme aminet/index\n\nund CD-Server übergibt der BBS dann nur noch die Filenamen DATA1.LHA, README\nund INDEX, merkt sich jedoch auch gleichzeitig die anderen Pfade und übergibt\ndiese mit beim suchen. Diese Funktion ist identisch mit der @{"Mark Funktion" LINK FLAG}.\n\n@{u}ANMERKUNG FÜR FAME-SYSOPS:@{uu}\n\nWas soll ich sagen, @{"FAME" LINK FAME} ist nun in der Lage, dem CD-Server die volle\nKontrolle über die File-Flags zu geben, ohne dieses Assihn benutzen zu\nmüssen. Von daher haben Sie unter @{"FAME" LINK FAME} mit keinerlei Einschränkungen zu\nleben, alles läuft so wie es auch in der BBS geht.\n\nWechseln Sie auf das bessere System...es gibt keine Alternativen mehr !\n@endnode\n\n@node MARK&FLAG "TIPS & TRICKS FÜR DAS FLAGGEN DER FILES"\n\n@{u}Markieren/Flaggen von Files@{uu}\n\n@{u}ANMERKUNGEN FÜR AMIEX-SYSOPS:@{uu}\n\nWie bereits erwähnt, ist die Unterstützung der Wildcards nicht möglich. \nSollte dieser doch angegeben werden, so wird die /X die files nicht finden,\n@{b}ALSO BITTE NICHT BENUTZEN@{ub}, stattdessen nehmen Sie halt die TAB-Taste für die\nPfadnamen-Erweiterung. Dieses Problem ist bisher für Amiex nicht lösbar,da \nder Server der Amiex die Conference-Icons nur einmal beim Start ins Memory \nliest, und dann alle Daten aus dem Speicher holt. Daher reagiert auch Amiex \nnicht auf neu dazugefügte ToolTypes (wie wäre es mit einem Kommando, das \ndie Amiex zwingt, das jeweilige Conference-Icon neu einzulesen, \nByteMaster ???) !!!\n\nAmiex hat noch einen anderen Nachteil beim Markieren von Files, und zwar ist\ndie Liste der geflaggten Files auf 2048 Bytes (oder mehr) inkl. der Spaces\nbegrenzt! Sollte also Amiex beim Flaggen abbrechen, dann ist meistens der \nString dafür voll, und Sie sollten erstmal ein paar Files leechen,bzw. einige\nFiles aus der Liste löschen. Wenn Sie das @{"FAME" LINK FAME}-System fahren, dann wird\ndieses Problem nicht auftreten, da @{"FAME" LINK FAME} ECHTE DYNAMISCHE LISTEN verwendet,\nund von daher nur von Ihrer Hardware begrenzt ist, nicht vom Willen des\nProgrammierers!\n\nWie bereits im Kapitel @{"DOWNLOAD" LINK DOWNLOADING} erwähnt, können Sie auch beim Flaggen von\nFiles einen Pfad mit angeben:\n\n                    A aminet/biz/patch/suxx.lha\n\nund CD-Server flaggt nur noch den Filenamen ''suxx.lha'', behält jedoch den\nPfad im Speicher und übergibt diesen dann auch beim Downloaden der BBS.\n\n@{u}ANMERKUNG FÜR FAME-SYSOPS:@{uu}\n\nKeine Einschränkungen nötig, mit @{"FAME" LINK FAME} läuft ALLES, nur das Sie halt auch\nkomplette Pfadnamen beim Flaggen angeben können..:=)\n@endnode\n\n@node GREETINGS "DIE ALLSEITS BELIEBTEN GRÜßE :)"\n\n@{u}SieGeL & ByteAndi grüßen:@{uu}\n\nSpy/trSi        - For helping us with the Argument-Parsing & the Dirscanning\nDr.Dre!/tRSi    - Berlin roolez!!!!!!!! :()\nsTRIDER/sDC     - For his very cewl @{"FAME" LINK FAME}-System :)) DER SAFT IST MIT DIR!\nARGON           - BW Suxx...\ndEATH aNGEL/sDC - For testing it finally on @{"FAME" LINK FAME} and for being a cewl beta :)\nBloodRock/SDC   - Da ASM-Posse strikes back..:) \nfUTZi/tRSi      - Welcome to our Club :)\n\n ...uND nATÜRLICH aLLE bETATESTER & rEGISTRIERTE uSER fÜR iHRE uNTERSTÜTZUNG,\n\n  aRTCORE! fÜR iHREN mEGA-gEILEN rEQUEST-sERVICE uND aLLE aNDEREN dIE wIR\n\n        hIER vERGESSEN hABEN zU eRWÄHNEN...fÜHLT eUCH gEGRÜSST ! :)\n\n------------------------------------------------------------------------------\n\n                           @{u}Technical Info@{uu}\n\nMain Code & Idea  : SieGeL/tRSi\nAdditional Coding : ByteAndi/tRSi (EDIT-Routine) & Spy/tRSi (Dir-Scanroutine)\nGFX painted by    : (-rAPID-) fROM dA fAMOUS aRTCORE pOSSE !\n\nCD-Server wurde auf zwei A4000/040 entwickelt und erfolgreich auf folgenden\nSystemen getestet : \n\n A5oo  5MB  68ooo           OS 2.o  Amiex 4.9        - SieGeL\nA12oo  6MB  68o2o+68881 Co. OS 3.o  Amiex 4.7        - ARGON\nA12oo 10MB  68o3o+68882 Co. OS 3.o  Amiex 4.7        - BYSIS\nA2ooo 14MB  68o3o+68882 Co. OS 2.o  @{"FAME" LINK FAME}-System      - dEATH aNGEL\nA3ooo 10MB  68o3o+68882 Co. OS 2.o  Amiex 4.6        - Spy\nA4ooo 14MB  68o3o+68882 Co. OS 3.o  @{"FAME" LINK FAME}-System      - sTRIDER\nA4ooo  6MB  68o4o+68o4o Co. OS 3.o  Amiex 4.9        - ByteAndi\nA4ooo 14MB  68o4o+68o4o Co. OS 3.1  @{"FAME" LINK FAME} & Amiex 4.9 - SieGeL\n\n            @{"(tRSi/X-iNNOVATiON) - wO sINDSE dENN ?" LINK ADDY1}\n@endnode\n\n@NODE PRGLIST "LISTE ALLER MEINER PROGRAMME BIS HEUTE !"\n\n@{u}Programm-Liste@{uu}\n\nUm Ihnen einen Überblick zu geben, was Sie als registrierter User bei mir\nbekommen, hier eine Liste aller meiner bisher geschriebenen Programme :\n\n@{b}Zur Zeit für registrierte User verfügbare Prg.:@{ub}\n\nCD-Server V1.03r    - CD-Server für @{"FAME" LINK FAME}/AMIEX\nwORLD-cLOCK V1.18   - Weltzeit-Door für @{"FAME" LINK FAME}/AMIEX\nmEGA-vIEW V2.1      - Bester TXT-Viewer für @{"FAME" LINK FAME}/AMIEX\nlASTCALLERS V0.04   - Lastcaller-Util für @{"FAME" LINK FAME}, faster than SAMILOG!\nsOFT-dEL V1.01      - Schneller Online-Softdel. für @{"FAME" LINK FAME} & AMIEX\nU-sTAT V1.31        - User-Statistik Door, frei konfigurierbar (@{"FAME" LINK FAME} & /X)\nASKII-REQUEST V1.00 - aSKII-Requester Door (AMIEX/@{"FAME" LINK FAME})\npAGE-mASTER v0.73   - Pager-Door für @{"FAME" LINK FAME} mit Highscore-Liste und PW-Option.\nUser-Editor V0.02   - Externer User-Editor für @{"FAME" LINK FAME}, benutzt MUI V2.2++\nmULTI-tOP v0.01     - Multi-BulletinTool für @{"FAME" LINK FAME}, erzeugt 8 Bulletins\nNewFlag v0.01       - Flaggt automatisch alle files der letzten Tage\n\n@{b}Noch in Arbeit,bzw. muß überarbeitet werden:@{ub}\n\noRDER V.02          - VerkaufsTool, um z.B. Hardware über BBS zu verkaufen\nBBS-VIEW V1.13      - CLI-Util zum Anzeigen von ANSI-Pics, 100% ASM!\nU-Convert V0.2      - Util zum Konvert. von /X user.data -> @{"FAME" LINK FAME} user.data\nBullcreator V1.0    - Highscore-Util für ByteKiller V1.0, wird noch geupdated\npAGE-mASTER II      - Amiex Version des pAGE-mASTERS von @{"FAME" LINK FAME}\n\nIch denke mal, 30,- DM (bzw.$20) ist ja wohl nicht zuviel für diese Programme,\noder etwa doch ? Und natürlich werde ich, soweit es machbar ist, auch alle \nWünsche oder Neuheiten in diese Programme einsetzen...um mit uns in Kontakt\nzu treten, bitte mal in Kapitel @{"CONTACTS" LINK ADDY1} nachsehen.\n\n@{u}ANMERKUNG:@{uu}\n\nIch schreibe nebenbei gerade an einer MUI-Version meines mEGA-vIEWS, dieser\nist ein Kommodity, lokalisiert, hat ein AppWindow, arbeitet auf jeden Public\nSchirm usw. Ich brauche für dieses Programm noch BETA-Tester, und es wird\nauch als FreeWare veröffentlicht. Wenn Sie dieses Tool testen möchten, dann\nmelden Sie sich bitte in meiner BBS und dann werden wir das klären...\n\n@endnode\n\n@node FAME "WAS ZUM TEUFEL IS EIGENTLICH FAME ????"\n\n''Was ist FAME ?'' , werden Sie fragen...FAME ist ein neues BBS-System,welches\nvon Strider (Syndicate) geschrieben wird, und zu 90% kompatibel zu Standard-\nAmiexdoors ist. Natürlich hat es auch einen komplett eigenen Msg-Port mit\nweit über 1000 (!!) Kommandos. Desweiteren ist dieses System komplett von\nder verwendeten Hardware abhängig, was bedeutet, um so mehr RAM, umso mehr\nkann man auch durchdrehen...:)\n\nDie Konfiguration der BBS erfolgt über ein sehr komfortablen SystemEditor,\nwelcher VOLLSTÄNDIG OHNE ICONS die BBS konfiguriert und dabei komplett mit\nder Maus zu bedienen ist. Die Kontrolle der BBS läuft über einen ebenfalls\nkomplett mit der Maus bedienbaren Server (Commodity!).\n\nDadurch das die BBS noch in der Entwicklungs-Phase steckt, ist sie derzeit\nauch noch nicht erhältlich, aber wenn Sie weitere Informationen über dieses\nSystem haben wollen, dann melden Sie sich bei uns und wir geben Ihnen dann\nalle Informationen die Sie brauchen.\n@endnode\n\n@node ADDY1 "(tRSi/X-iNNOVATiON) WHQ & Beta Site"\n\nUm mit uns in Kontakt zu treten, schreiben Sie mir entweder über E-Mail:\n\n                     [email removed]\n\noder versuchen Sie unsere Boards anzurufen:\n\n   _____________  __________               /\\\n  |     __     /__\\__      /___________   /  \\             _____\n  |   ________/    /      /_\\____      \\_//   \\___________|_____|_______\n  |     |  \\      /      /      /      _//     \\    ______________      \\_\n  l_____|   \\___________/______/       \\_______/\\______   \\_    l/       /\n                              \\________/      /____________/____/       /\n                                       _________________       \\_______/\n     ______ /\\____ ____________ _______\\______   ______/\n    /      /_      \\    __    /_\\_____      \\_    |\n  _/      \\/______/   _______/\\      /       /    |    · PUN¡sHMeNT ¡NC. ·\n  \\________\\    _/_____________\\____/  Mo!  /_____|\n                /                  \\_______/\n                                           /\\  ______________  ___________\n     1oo% LeGaL sTUFF oN aM¡Ga^PC         /  \\_\\_______      \\_\\    _____/___\n                                         //   \\       /       /     /       /\n     RUNN¡NG oN a4ooo/4o · V.FasT      _//     \\_____/       /_____________/\n                                       \\________/   \\_______/\n\n TR¡sTaR & ReD seCToR ¡NC. (/X·¡NNoVaT¡oN) WHQ, aRTcORE! GHQ & eTH¡C D¡sT s¡Te\n\n   [> +49-(o)-3o-694-84-7o <]  sYsoP: s¡eGeL/TRs¡  [> +49-(o)-3o-694-85-7o! <]\n\n                     @{"> pARALYSIS BBS - dISTRIBUTION sITE <" LINK ADDY2}\n@endnode\n\n@node ADDY2 "(tRSi/X-iNNOVATiON) bETA & dIST SITE"\n       ____                                                                  \n    ___\\  /______________________________________________________________    \n   /   \\\\//                                                              \\   \n  /     \\/ -[ THe BeST eQUiPPeD PuBLIC DoMAIN BoaRD IN BeRLIN ]-          \\  \n /   -[ WiTH 4 GReaT U.S.ROBOTICS V.FAST CLASS MoDeMS WiTH FLaSH-RoMS ]-   \\ \n/                                                                           \\\n\\                        -- -[ SYNDIC/\\TE WHQ ]- --                         /\n \\   _____  _____    _____   _____  __      ___ __  _____   ___ _____      / \n  \\ /  _  \\/  _  \\  /  _  \\ /  _  \\/  |___ /   |  \\/   __)_/ __|   __)_   /  \n   /   |   \\  _   \\/   |  //   _   \\  |   \\\\_____  \\___    \\¯  |___    \\ /   \n  /   _____/  |    \\_ __   \\_  |    \\ |    \\   |    \\|      \\  | |      \\    \n  \\____| \\____|    /___|    /__|    /___   / _______/___    /__|____    /    \n      \\       l___/    l___/   l___/  \\___/___/  [ViC!]\\___/       \\___/     \n       \\                                                             /       \n        \\SYSTeM CHieFS: SPY/TRSi,ARTHuR DeNT,PHaNToM,Cat,JTC,big-rat/        \n         \\                                                         /         \n          \\   1: +49(0) 30 721 6071 USR DuAL STaNDaRD V.34 33.6   /          \n           \\  2: +49(0) 30 721 6072 USR DuAL STaNDaRD V.34 33.6  /           \n            \\ 3: +49(0) 30 721 6073 USR DuAL STaNDaRD V.34 33.6 /            \n             \\4: +49(0) 30 722 6065 USR DuAL STaNDaRD V.34 33.6/             \n              \\                                   /\\          /              \n               \\_________________________________//\\\\________/               \n                                                 /__\\\n\n                        SUPPORTS ONLY PD-/SHAREWARE !\n@endnode\n\n@node REGVERSION "ERWEITERTE REGISTRIERTE VERSION DES CD-SERVERS"\n\n@{u}Zusätze der Registrierten Version des CD-Servers@{uu}\n\nWenn Sie den vollen Support für den CD-Server genießen wollen, dann haben\nSie die Registrierungsgebühr zu bezahlen. Als registrierter User können\nSie mit den folgenden Erweiterungen rechnen:\n\n- Suchfunktionen aktiviert\n- Level-abhängige Geräte/Directories, für Co-Sysops zum C: dir z.B.\n- Interne Pack-Funktionen mit Sysop-einstellbaren Bytebegrenzungen\n- User-konfigurierbarer Dir-Style und andere Optionen (wie Packer etc.)\n\nund natürlich alle Wünsche (soweit realisierbar) für CD-Server oder die\nanderen Programme die @{"HIER" LINK PRGLIST} aufgeführt sind. Es liegt also an Ihnen, die\nWeiterentwicklung der Software zu sichern...\n@endnode\n','\n',char(10)),NULL,'auto-added',70393,7,0,NULL,NULL,'trsicd13','scan',1780048442);
INSERT INTO door_catalog VALUES('cdserver','CDSERVER.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CDSERVER.LHA','CD-SERVER','XIM','CD-SERVER',NULL,'SieGeL',NULL,'\    ____    )  /___/\_| & rED sECTOR ¡NC | .-\___\ | \___\__   /   |  /X ¡NNOVATION   | `---|___|___|______/____|---[ [RESENTS ]---''',replace(' _____________ ___Mo! __.<---[ tRISTAR ]---.\n \    ____    )  /___/\_| & rED sECTOR ¡NC |\n.-\___\ | \___\__   /   |  /X ¡NNOVATION   |\n`---|___|___|______/____|---[ [RESENTS ]---''\n    CD-Server V1.00p by SieGeL & ByteAndi\n--------------------------------------------\n1ST "REAL" SERVER WITH FULL C-SHELL COMFORT,\nDL DIRECT FROM CD-ROM, PATHNAME-COMPLETITION\nFAST DIRSCAN-ROUTINES,AMIEX & FAME COMPAT.,\n   1oo% SAFETY AND INSTALLER SUPPORTED !\n--------------------------------------------\nA NEW tOOL fROM tHE REAL (tRSi/X-iNNOVATiON)\n','\n',char(10)),'CD-sERVER_DEUTSCH.guide',replace('@database CD-sERVER V1.0 - Deutsches DataBase\n@author "SieGeL/tRSi"\n@(c) "Copyright © 1995 (tRSi/X-iNNOVATiON)"\n@$VER: CD-SERVER.guide V1.01 (05-26-95)\n\n@index Main\n\n@node Main "CD-Server - BBS Tool geschrieben von SieGeL & ByteAndi (tRSi/X-iNNOVATiON)"\n@{b}                                                                     ______\n .-----------[ TRSI (/X·INNOVATION) ]------------.       _  ________/     /\n | _________________________________       ______`-------\\//  __    \\    /---.\n | \\       _____________     /     /______(______)  _     /    \\     \\  /    |\n |  \\______\\    |    __/   _/\\______       /     | (/)   /     /\\     \\/ Mo! |\n | \\     |      |    \\      \\       |     /      |  ¯   /     / /\\     \\_    |\n | \\\\    l______|_____\\      \\___________/_______|    _/     /_/  \\_____/    |\n `---------------------\\______/-----------------------\\_____/-\\_____/--------''@{ub}\n\n                           iS pROUD tO pRESENT:\n\n@{APEN 2}             CD-Server V1.00 public written by SieGeL & ByteAndi@{APEN 1}\n                                                                          \n                      @{" COPYRIGHT! " LINK COPYRIGHT}     @{"VERTREIBUNG!" LINK DISTRIBUTION}\n                      @{" EINFÜHRUNG " LINK EINFÜHRUNG}     @{"INSTALLATION" LINK INSTALLATION}\n                      @{" BEDIENUNG! " LINK HOW2USE}     @{" -CREDITZ!- " LINK GREETINGS}\n\n Der erste "@{b}ECHTE@{ub}" Server für jedes Amiga-DOS kompatible device,z.B. CD-Rom !\n@endnode\n\n@NODE COPYRIGHT "Copyright-Information für dieses Programm"\n\n     @{u}Copyright@{uu}\n\n   Dieses Programm ist ''FreeWare''.\n\n Es darf frei kopiert und für nicht kommerzielle Zwecke vertrieben werden,\n solange sicher gestellt ist, das kein file (ausser natuerlich BBS-Addys)\n zu diesem Archiv dazugepackt oder aus diesem Archiv entnommen wird, und \n das für diese Veröffentlichung nicht mehr Geld, als für die Erstattung des\n Datenträgers/Kopierkosten, notwendig ist, verlangt wird.\n\n Das volle Copyright auf den Programmcode liegt bei dem Author (also meine\n Wenigkeit!) selbst, und ohne meine schriftliche Genehmigung ist es nicht \n erlaubt, dieses Programm kommerziell zu vertreiben.\n\n Diese Version von CD-Server ist die EINZIGSTE, die unter dem Prinzip der\n ''FreeWare'' vertrieben wird, alle anderen Updates (Fehlerbereinigungen etc.)\n sind dann nur noch für registrierte User verfügbar. Wenn Sie registrierter\n User bei mir werden möchten, dann haben Sie eine Registrierungs-Gebühr in\n Höhe von 30.- DM ($20) zu bezahlen.\n\n Diese Registrierungsgebühr ist natürlich nur einmalig zu entrichten, nach\n der Bezahlung erhalten Sie vollen Zugriff auf mein Register-Door und können\n dann frei über ALLE meine Tools verfügen.\n\n Alles weitere können Sie dann mit mir in meiner @{"BBS" LINK ADDY1} besprechen. Einfach\n mal durchcallen und ''SieGeL/tRSi'' eine Mail hinterlassen, ich kläre dann\n alles weitere.\n\n            @{"LISTE ALLER BISHER VON MIR VERFASSTEN PROGRAMME" LINK PRGLIST}\n@endnode\n\n@NODE DISTRIBUTION "Vertreibung von CD-Server"\n\n     @{u}Verbreitung/Vertreibung@{uu}\n\n  Hiermit genehmige ich die Veröffentlichung von diesem Archiv, solange wie\n  nicht mehr Geld, als für die Erstattung der Kopier-kosten etc. notwendig\n  sind, verlangt wird, und solange dieses Archiv nur in seinem Original-\n  zustand vertrieben wird. \n\n  Das Copyright liegt bei dem Author (also mir !) selbst, und ohne meine \n  schriftliche Genehmigung darf dieses Programm nicht kommerziell vertrieben \n  werden.\n@ENDNODE\n\n@node EINFÜHRUNG "Einleitung, oder warum dieses Programm entstanden ist."\n\n@{uu}Einleitung@{uu}\n\nNachdem ich mein Quadraspeed CD-Rom gekauft hatte, wollte ich dieses Laufwerk\nauch meiner BBS zukommen lassen (ich fahre momentan noch Amiex), musste \njedoch feststellen, das das gar nicht so ohne weiteres moeglich ist, ein CD-\nRom in Amiex einzubinden, da man dann ja erstmal die DLPATHES alle setzen muß,\ndann müsste man sich auch noch ein Filelisting erstellen...nene, war mir echt\nzuviel des guten...\n\nAlso hab ich erstmal nach nem Tool gesucht, was die Arbeit mit dem CD-Rom und\nder guten (?!) Amiex möglich macht...und siehe da, ich hab sogar eins ge-\nfunden, und zwar CD/FTP-Server (oder so ähnlich :) von Sigma Seven...das war\ngenau das was ich wollte...wenn da nich ein Haken gewesen wäre...dieses Door\nhat die Angewohnheit, jedes File erstmal auf HD zu kopieren, und danach dem\nUser zu geben..und mit jedem mal kopieren wird die Platte fragmentierter...\nDa ich sowas nicht mag, hab ich mir gedacht, das es auch noch einen anderen\nWeg geben müßte, ein CD-Rom in Amiex einzubinden...nunja, daraus iss halt \ndieses Programm entstanden.\n\n@{u}Merkmale von CD-Server@{uu}\n\n - Ermöglicht Downloaden/Anzeigen von TXT-files @{b}DIREKT@{ub} von CD-Rom, ohne\n   lästige Kopierei!\n\n - @{b}Komplette C-Shell Bedienung@{ub}, z.B. @{b}TAB@{ub}-Taste für @{b}Pfadnamen-Erweiterung@{ub},\n   das ''@{b}!@{ub}'' Zeichen als Abkürzung von Befehlen im @{b}20-Zeilen Buffer@{ub}, voll-\n   ständige @{b}CRSR-Key@{ub} Simulierung (Hoch/runter für Buffer,links/rechts um\n   in der Zeile hin und her zu laufen) usw...\n\n - Unterstützt auch @{b}UNIX@{ub}-Kommandos, wie z.B. ''@{b}..@{ub}'' für Parent-Dir etc.\n\n - Eingebaute Unterstützung für GUIDE-Dateien, um diese als ANSI-Files\n   umzuwandeln und anzuzeigen\n\n - Benutzt BBS-interne Download- und FlagFile Routinen ohne das man @{b}ALLE@{ub}\n   Pfade in das Icon eintragen muss, daher auch flexibel im CD-Wechsel!\n\n - @{b}Amiex V3.++@{ub} und FAME (Final Amiga Mailbox Engine) kompatibel\n\n - Braucht bis auf das Guide2DocProf @{b}KEINE@{ub} weiteren Befehle aus dem C: dir.\n\n - Sau-schnelle Directory-Scan routine mit der selben Ausgabe wie der all-\n   seits bekannte und beliebte Directory Opus :)) \n\n   etc...\n\n@{u}Was man alles für den CD-Server braucht@{uu}\n\nBevor Sie dieses Programm installieren, müssen ein paar Bedingungen erfüllt\nsein...zum ersten , haben Sie ein Device (CD0: als Beispiel), welches Sie \nKOMPLETT als Datenträger der BBS zur Verfügung stellen können ? \n\n@{APEN 2}BITTE DARAN DENKEN, ASSIGNS SIND ZU UNSICHER, DA DER USER EVTL. IN DAS ROOT-\nDIR DES ASSIGNS KOMMEN KÖNNTE, ALSO BITTE IMMER NUR DH0:, CD0:, DF0: :) USW.@{APEN 1}\n\nDann ist in der Testphase aufgefallen, das bei Benutzung eines PCMCIA-\nControllers in Verbindung mit einem Mitsumi FX-400 CD-Rom ein Fehler auf-\ngetreten ist beim Anzeigen von Text-files. Dieser Fehler liegt nicht an\nunserer Dummheit (!!!), sondern einzig und allein daran, das dieses \npcmcia.device (oder wie auch immer) den FileInfoBlock von ADOS nicht richtig\nunterstützt, und von daher es zu merkwürdigen Fehlern kommt. Sollte dieses\nbei Ihnen der Fall sein, dann wenden Sie sich bitte an den Author dieses\nDevices, und bitten ihn um ein Update. Soweit es ging werden solche Fehler\ntransparent von CD-Server behandelt, Sie bekommen davon eigentlich nix mit.\n\nDann zu guter letzt iss natürlich klaro, das dieses Tool min. Kickstart V37\noder höher benötigt, aber wer hat schon noch 1.3 ;), und als BBS sollte\nmindestens eine Amiex V3.++ oder höher installiert sein, oder halt die FAME,\nwobei hier die Version noch nicht wichtig ist..:)\n\n                @{"ZUR INSTALLATION GEHTS HIER LANG :)" LINK INSTALLATION"}\n@endnode\n\n@node INSTALLATION "Wie man CD-Server auf Ihr System installiert."\n@NEXT HOW2USE\n\n@{u}Allgemeine Installation@{uu}\n\n1.Kopieren Sie das Directory ''CD/'' zu Ihrem Doors: Verzeichnis, oder wo immer\n  Sie Ihre BBS-Tools auch aufbewahren.\n\n2.Kopieren Sie das File CD-SERVER.HLP'' nach Ihr S: Directory, dieses File\n  ist die Online-Hilfe von CD-Server.\n\n3.Kopieren Sie das File ''GUIDE2DOCPROF'' nach Ihr C: Directory, dieses File\n  wird zum Umwandeln der AmigaGuides zu ANSI-Files benötigt.\n\n4.Editieren Sie die Tooltypes im Icon ''CD-Server.info'', im Moment existieren\n  zwei Tooltypes:\n\n    DEVICE=CD0:   -> Hier müssen Sie das Device angeben, mit dem CD-Server\n                     arbeiten soll, z.B. DH0:, CD0:, DF0: :), RAD: etc.\n\n@{u}ACHTUNG:@{uu} GEBEN SIE HIER AUF KEINEN FALL EIN ASSIGN, SONDERN IMMER NUR EIN\n         DEVICE NAMEN EIN !! ALLES ANDERE IST DEFINITIV ZU UNSICHER !\n\n    PACKDIR=RAM:  -> Hier können Sie optional ein Directory angeben, welches\n                     dann als temporäres Dir gilt, hierher werden die umge-\n                     wandelten Guides geschrieben. Wenn dieses Tooltype nicht\n                     gesetzt ist, wird standardmässig T: genommen.\n\n5.Als nächstes müssen Sie ein ASSIGN namens ''SERVER:'' erzeugen. \n  Dieses Assign sollte am besten nach T: assigned werden, da T: normalerweise\n  nach RAM:T/ zeigt, und von daher am schnellsten ist. Und keine Panik, ich\n  kopiere keine Files nach ''SERVER:'', CD-Server braucht dieses Assign nur,\n  um mit der BBS zu kommunizieren :) \n  Am besten Sie schreiben folgende Zeile in Ihre ''user-startup'' :\n\n                       ASSIGN >NIL: SERVER: T: DEFER\n\n6.Zu guterletzt müssen Sie CD-Server noch in Ihr BBS-System einbinden. Bitte\n  wählen Sie das System, das bei Ihnen installiert ist : @{"AMIEX" LINK AMIEX_INSTALL} oder @{"FAME" LINK FAME_INSTALL} .\n\n7.Nach einem Reset sollte jetzt CD-Server einsatzbereit sein...\n@endnode\n\n@node AMIEX_INSTALL "CD-Server auf ein Amiex-System installieren."\n@PREV INSTALLATION\n@NEXT INSTALLATION\n\n@{u}Installation für Amiex-Betreiber:@{uu}\n\n1. Kopieren Sie das Icon ''CD.INFO'' in das Directory ''BBS:COMMANDS/BBSCMD'',\n   und ändern Sie gegebenenfalls den Pfad im Icon zu CD-Server.\n\n2. Editieren Sie alle Conference-Icons, in denen CD-Server laufen soll,\n   und tragen Sie in diese bitte ein neues DLPATH-ToolType ein:\n\n                        DLPATH.(x)=SERVER:\n\n   wobei (x) fuer die nächsthöhere Nummer der DLPATHES im jeweiligen \n   Conference-Icon steht. Angenommen, Sie haben die folgenden Tooltypes in\n   Ihrem AMIGA.INFO Conference-Icon:\n\n                         DLPATH.1=BBS:AMIGA/UPLOAD/\n                         DLPATH.2=DH2:AMIGA/UPLOAD/\n\n   dann tragen Sie für den CD-Server ein :\n\n                         DLPATH.3=SERVER:\n\n   Sie müssen dieses Tooltype in JEDEM Conference-Icon eingeben, in denen auch\n   CD-Server korrekt funktionieren soll...\n\n3. Starten Sie nun Amiex neu, da der Server alle Icons im Speicher behält,\n   und von daher auch nicht auf die Änderungen reagieren kann (Bitte ändern,\n   ByteMaster, das iss ja nu wirklich das letzte...:( ).\n\nDas ist alles für die Installation auf Amiex.\n@endnode\n\n@node FAME_INSTALL "CD-Server auf ein FAME-System installieren."\n@PREV INSTALLATION\n@NEXT INSTALLATION\n\n@{u}Installation für FAME-Betreiber:@{uu}\n\n1. Starten Sie den SystemEditor, gehen Sie in das Menü ''DOORS'', und lesen Sie\n   das File ''CD'' ein, welches diesem Archiv beigefügt ist.\n\n2. Editieren Sie den Pfad zu CD-Server, Accesslevel etc. nach Ihren eigenen\n   Wünschen und speichern Sie es im Directory ''FAME:SETTINGS/DOORS/BBSCMD/''.\n  (Bitte daran denken, das dieses Door als XIM angelegt wird, nicht als FIM!)\n\n3. Nun müssen Sie noch das Assign ''SERVER:'' in den Erweiterten Suchpfaden der\n   jeweiligen Conferencen dazuschreiben. Normalerweise heisst dieses TXT-File\n   AdvDlPathes.txt, es kann jedoch je nach Ihrer Konfiguration auch anders \n   heissen. Dieses File laden Sie bitte mit einem TXT-Editor (ASCII) Ihrer \n   Wahl ein und fügen die folgende Zeile dazu:\n\n   SERVER:\n\n   Dann speichern Sie dieses File wieder ab, und das wars auch schon..:)\n\nNun können Sie bereits den CD-Server antesten...\n@endnode\n\n@node HOW2USE "Übersicht aller Kommandos von CD-Server"\n\n@{u}Kommando-Übersicht@{uu}\n\n  @{b}DOS-KOMMANDOS@{ub}            @{b}AMIEX-KOMMANDOS@{ub}        @{b}ANDERE KOMMANDOS@{ub}\n\n   @{"    CD    " LINK CD}               @{"  FLAG/A/F " LINK FLAG}            @{"   CLEAR   " LINK CLEAR}\n   @{"   .. /   " LINK PARENT}               @{"   DOWN/D  " LINK DOWN}            @{"   VER/$   " LINK VER}\n   @{"   INFO   " LINK INFO}               @{"   VIEW/D  " LINK VIEW}            @{"  HELP/#/? " LINK HELP}\n   @{" LIST/DIR " LINK DIR}               @{"   QUIT/G  " LINK QUIT}            @{"   INDEX   " LINK INDEX}\n   @{"   TYPE   " LINK VIEW}        \n   @{"  ENDCLI  " LINK QUIT}\n\n@{u}Allgemeine Bedienung@{uu}\n\n @{" ZEILEN-EDITOR " LINK LINE-EDITOR}           @{" DOWNLOADEN " LINK DOWNLOADING}            @{" MARKIEREN " LINK MARK&FLAG}\n@endnode\n\n@node CD "DOS-KOMMANDO : CD - ÄNDERE DIRECTORY"\n\n@{u}CD - Ändere Directory@{uu}\n\nMit diesem Kommando können Sie das aktuelle Directory wechseln, z.B. wenn Sie\nsich im Directory ''CD0:AMINET/'' befinden und Sie möchten in das Directory\n''CD0:AMINET/BIZ/'', dann geben Sie einfach ''CD BIZ/ ein'', und CD-Server \nwechselt zu diesem Directory.\n\nAlle Directories, zu denen Sie wechseln möchten, beziehen sich immer auf das\naktuelle Directory, und sollte CD-Server einmal nicht das Directory wechseln,\ndann ist entweder der Pfadname ein File oder es existiert gar nicht (vom\naktuellen Directory aus gesehen!).\n\nNatürlich müssen Sie nicht jedesmal das CD - Kommando eingeben, einfach nur \ndie Angabe des Pfadnamens reicht ebenfalls aus, um das Dir zu wechseln.\n\n@{u}ACHTUNG:@{uu} Aus Sicherheitsgründen wurde die '':'' Taste deaktiviert, sollte ein\n         User diese Taste drücken, dann wechselt CD-Server automatisch zu dem\n         angegebenen Device (im CD-Server.info).\n\nGucken Sie in das Kapitel @{"LINE-EDITOR" LINK LINE-EDITOR} für weitere Infos über gesperrte\nKommandos/Tasten.\n@endnode\n\n@node PARENT "DOS-KOMMANDO : .. / - GEHE ZUR NÄCHSTHÖHEREN VERZEICHNIS-EBENE"\n\n@{u} .. / - Wechsle zur nächsthöheren Verzeichnisebene@{uu}\n\nMit diesem Kommando können Sie vom aktuellen Directory aus eine Verzeichnis-\nebene höher gehen. Dies können Sie solange machen, bis Sie zum Hauptver-\nzeichnis kommen (z.B. CD0:).\n\nWeitere Informationen über das Wechseln von Dirs können Sie im Kapitel @{"CD" LINK CD}\nlesen.\n@endnode\n\n@node INFO "DOS-KOMMANDO : INFO - GIBT INFO ÜBER VERWENDETES DEVICE AUS."\n\n@{u}INFO - Zeigt Device-Spezifische Informationen an@{uu}\n\nDieses Kommando zeigt die Informationen des Devices an, welches vom CD-Server\nverwendet wird. Beispielsweise sieht die Ausgabe bei mir so aus :\n\nDevice used..: CD0: (AMINET5)                                        \nUnit Number..: 0                                                     \nDisc Status..: Write protected                                       \nR/W Errors...: 0                                                     \nFile-System..: DOS0 (OFS)                                            \n# of Blocks..: 326334                                                \nBytes/Block..: 2048                                                  \nBytes used...: 637 MB                                                \n\nFür weitere Informationen über Devices sehen Sie bitte in Ihrem DOS-Manual\nnach.\n@endnode\n\n@node DIR "DOS-KOMMANDO : DIR - ZEIGT DIRECTORY-INHALT AN."\n\n@{u}LIST / DIR - Zeigt den Inhalt eines Directories an@{uu}\n\nDieses Kommando zeigt Ihnen den Inhalt eines beliebigen Directories an. Geben\nSie keinen Pfadnamen an, dann wird das aktuelle Directory angezeigt. Die \nAusgabe erfolgt genauso wie bei dem bekannten Directory Opus, erst werden\n(natürlich alphabetisch sortiert :) die Dirs angezeigt, danach dann die \nFiles.\n@endnode\n\n@node VIEW "DOS-KOMMANDO : VIEW/V/TYPE - ZEIGT TXT- & GUIDEFILES AN"\n\n@{u}VIEW/V/TYPE - Zeigt TXT- & Amiga-Guide Files an@{uu}\n\nMit diesem Kommando können Sie sich ein beliebiges TXT-File auf dem ver-\nwendeten Datenträger ansehen. Sollte es sich bei dem von Ihnen ausgesuchten\nFile um eine Amiga-Guide Database handeln, und Sie haben das Tool \nGUIDE2DOCPROF von FOX/RMD/ALIENGROUP in das C:-Directory kopiert, dann werden\ndiese Databases umconvertiert und anschliessend als ANSI-File angezeigt.\n\nBenutzer meines mEGA-vIEW''s sollten mit der Bedienung keinerlei Probleme \nhaben, da dies die selbe Routine iss...:)\n\n@{u}ACHTUNG:@{uu} Bitte gucken Sie sich mit diesem Kommando nur TXT- & GUIDE-Files an,\n         bei Binär-Dateien kann es zu merkwürdigen Effekten auf dem Screen\n         kommen! \n@endnode\n\n@node QUIT "DOS-KOMMANDO : ENDCLI/QUIT/Q/G - CD-SERVER BEENDEN."\n\n@{u}ENDCLI/QUIT/Q/G - CD-SERVER BEENDEN@{uu}\n\nMit diesem Kommando beenden Sie CD-Server, die geflaggten Files bleiben jedoch\nerhalten!\n@endnode\n\n@node FLAG "BBS-KOMMANDO : FLAG - MARKIERE FILES FÜR DEN DOWNLOAD."\n\n@{u}FLAG/F/A - Markiere Files zum Downloaden@{uu}\n\nDieses Kommando ist exakt das selbe wie das Flag-Kommando der Amiex (FAME\nhat hier mehr zu bieten!) und es unterstützt natürlich auch Multi-Args,z.B.\n\n                       A TEST.LHA TH.LHA LABER.LHA\n\nund die Files ''TEST.LHA'', ''TH.LHA'' & ''LABER.LHA'' werden der Flag-Liste hinzu-\ngefügt (Pfad ist das aktuelle Directory!).\n\nAls spezielle Erweiterung habe ich diesem Flag-Kommando eine Doppelfunktion\nzugewiesen:\n\n                               A C *\n\nDieses Kommando löscht 1. die bbs-interne Flagliste und 2. löscht auch ALLE\nPfade, die sich CD-Server zu diesem Zeitpunkt gemerkt hat. Desweiteren ändert\nCD-Server das aktuelle Directory zu dem Start-Dir aus Sicherheitsgründen. \nDies is sozusagen eine Art von ''Warmstart'' des CD-Servers :)))\n\nUnd als zusätzlicher Bonus ist es jetzt auch möglich, beim Flaggen einen \nPfadnamen mit anzugeben, um Files aus anderen Directories zu leechen, z.B. \n\n                  A README AMINET/BIZ/DBASE/DEMO.LHA\n\nDieser Aufruf macht folgendes, 1. wird das File README aus dem aktuellen\nDirectory in die Flagliste aufgenommen, dann wird beim zweiten File der\nPfad vom Filenamen getrennt, der Pfad CD-Server bekannt gemacht (und damit\nauch der BBS :), und nur noch der Filename der BBS übergeben. Diese Argu-\nmenten-Abfrage funktioniert auch beim Downloaden.\n\nNach zuviel Vorzügen muß es natürlich auch einen Nachteil geben...und das\nsind die Wildcards ! Sollte in einem Pfadnamen ein ''@{b}*@{ub}'' vorkommen, dann wird\ndie BBS dieses File nicht finden (außer natürlich in den Pfaden auf HD!)..\num dieses Problem zu umgehen, sollten bei Abkürzungen immer die @{"TAB-Taste" LINK LINE-EDITOR}\nverwendet werden, da diese Funktion ja automatisch die Pfadnamen erweitert!\n\nACHTUNG: Sollte es während dem Transfer zu einem Lost Carrier kommen, und die\n         BBS ist in der Lage, sich die geflaggten Files zu merken, dann müssen\n         Sie unabhängig davon noch einmal in die ganzen Directories gehen, wo\n         Sie sich die Files geflaggt haben, und jeweils einmal ''A'' + Enter\n         eingeben, damit CD-Server die Pfadnamen wieder erkennt.\n\nFür weitere Infos schauen Sie bitte in das Kapitel @{"MARKIEREN VON FILES" LINK MARK&FLAG} nach.\n@endnode\n\n@node DOWN "AMIEX-KOMMANDO : DOWN/D - DOWNLOADED ALLE GEFLAGGTEN FILES."\n\n@{u}DOWN/D - Downloaden aller geflaggten Files@{uu}\n\nNachdem Sie alle gewünschten Files @{"markiert" LINK FLAG} haben, können Sie mit Hilfe\ndieses Kommandos die Liste der Files downloaden. Da zum Downloaden die \ninternen Funktionen der jeweiligen BBS genommen werden, kann es passieren, \ndaß die BBS plötzlich abbricht und sagt das Sie Ihr Daily Limit überzogen\nhaben! Also achten Sie bitte darauf, das Sie auch wirklich die Anzahl der\nFiles, die Sie geflaggt haben, downloaden können.\n\nWie im Kapitel @{"MARIEREN VON FILES" LINK FLAG} bereits erwähnt wurde, können nach dem\n''D'' - Kommando auch Files (evtl. mit Pfadnamen relativ zum aktuellen Verz.)\nmit angeben werden.\n\nWenn Sie das Download-Kommando eingegeben haben, werden Sie von der BBS\nnoch nach weiteren Filenamen gefragt. Hier können Sie natürlich auch noch\nfiles aus dem Directory, aus dem Sie auch das ''D'' Kommando gestartet haben,\nflaggen, sowie auch Files die in den Normalen Download-Pfaden gefunden werden\nkönnen.\n\nHier dürfen Sie aber keine Pfade mehr mit angeben, da sonst die BBS das\nFlaggen abbricht mit der Meldung:\n\n            YOU DON''T HAVE TO INCLUDE ANY SPECIAL SYMBOLS !\n@endnode\n\n@node CLEAR "KOMMANDO : CLEAR/CLS - LÖSCHT DEN BILDSCHIRM"\n\n@{u} CLEAR / CLS - Löscht den Bildschirm@{uu}\n\nDieses Kommando löscht den Inhalt des Bildschirmes und setzt den Cursor an\ndie linke obere Ecke. Mehr muß man dazu glaub ich nich schreiben :)\n@endnode\n\n@node VER "KOMMANDO : VER - ZEIGT VERSIONSNUMMER VON CD-SERVER AN"\n\n@{u}VER / $ - Zeigt Version-Informationen an@{uu}\n\nWenn Sie dieses Kommando eingeben, erscheint eine Ausgabe der aktuellen\nVersionsnummer vom CD-Server, sowie das Datum der Compilierung.\n\nNatürlich kann man die Versionsnummer des Programms auch mit dem CLI-\nKommando ''VERSION'' erfragen, für weitere Informationen gucken Sie bitte\nin Ihr Amiga-Dos Manual.\n@endnode\n\n@node HELP "KOMMANDO : HELP/?/# - ZEIGT ONLINE-HILFE AN"\n\n@{u}HELP/?/# - Zeigt die Online-Hilfe an@{uu}\n\nWenn Sie mal gerade nicht wissen, wie ein Kommando heißt, bzw. es aufgerufen\nwird, dann geben Sie eine dieser Zeichenfolgen ein, und CD-Server zeigt das\nHelpfile (S:CD-SERVER.HLP) an.\n\nDa die Geschmäcker der Menschen unterschiedlich sind (Gott sei Dank! :), habe\nich das Helpfile auch extern gehalten, so kann sich das jeder Sysop selbst\nzurecht zimmern...\n@endnode\n\n@node INDEX "KOMMANDO : INDEX - SUCHT NACH INDEX-FILE UND ZEIGT ES AN"\n\n@{u}INDEX - Sucht nach dem Index-File und zeigt es ggf. an@{uu}\n\nDa ich mein CD-Rom eigentlich nur für AMINET-CD''s benutze, habe ich fest-\ngestellt, daß bei diesen Aminet-CD''s immer ein INDEX - File in jedem Dir\nzu finden ist, welches eine kurze Übersicht über das aktuelle Directory\nenthält. Wenn nun jemand etwas bestimmtes sucht, isses wohl leichter, dieses\nFile erstmal zu durchsuchen, als sich alle .readme Dateien anzuschauen. Und\ndafür is halt das Index-Kommando da, wenn sich kein Index in einem Directory\nbefindet, erhält man die Meldung : ''NOTHING TO VIEW !'' .\n\nAber wie gesagt, dieses Kommando ist halt hauptsächlich nur für die AMINET-\nCD''s gedacht, die ich persönlich für das beste an PD überhaupt halte !\n@endnode\n\n@node LINE-EDITOR "WIE MAN EFFIZIENT MIT DEM ZEILEN-EDITOR ARBEITET"\n\n@{u}Benutzung des Zeilen-Editors von CD-Server@{uu}\n\nUm den Usern ein Maximum an Komfort zur Verfügung zu stellen, hat Byte-\nAndi und meine Wenigkeit eine Menge Arbeit in die Entwicklung einer Zeilen-\nEingaberoutine gesteckt. Das Ziel war es, so weit wie möglich (und notwendig)\ndie C-Shell Eingabemöglichkeiten zu simulieren, und dieses ist auch zu 98%\ngelungen möchte ich sagen :) ... hier nun eine Liste aller Kommandos :\n\n1) TAB-Taste. Diese Taste ermöglicht die automatische Filenamen-Erweiterung.\n   Nur das Drücken der Taste veranlasst CD-Server, das aktuelle Dir zu\n   scannen und das erste gefundene File anzuzeigen. Sie können z.B. auch\n   ''AMI'' eingeben und dann TAB drücken, sodaß CD-Server evtl. die folgenden\n   Filenamen findet : AMINET/, AMINET.Z, AMINET usw. Desweiteren ist es auch\n   möglich, ganze Pfade abzukürzen, wie z.B. : \n\n   Sie geben CD */*/*/* ein und drücken dann TAB, dann könnte evtl. folgende\n   Ausgabe erscheinen : AMINET/BIZ/DBASE/DEMO.LHA.\n\n   Dieses funktioniert überall auf dem Prompt, und wir dachten uns das das\n   wohl der beste Ersatz für die ''WildCards'' ist...:)\n\n2) Vollständige Zeilen-Editierung, d.h. das Sie überall innerhalb einer\n   Zeile sich mit den CRSR-links/rechts Tasten bewegen können, Zeichen ein-\n   fügen/löschen können, mit CTRL-X die komplette aktuelle Zeile löschen etc.\n   Aber bitte daran denken, daß dieses @{b}NUR@{ub} :) eine Zeilen-Routine ist, mehr \n   als 80 Zeichen sind derzeit nicht gestattet!\n\n3) History-Buffer mit Abkürzungs-Möglichkeiten. Jede eingegebene Zeile wird\n   in einem internen Buffer gespeichert, dieser Buffer ist im Moment auf 20\n   Zeilen begrenzt, registrierte User können dann natürlich diesen ggf. auf\n   höhere Werte setzen...Wenn Sie die CRSR-Hoch/runter Tasten benutzen, dann\n   wird immer die zuletzt/zuerst eingegebene Zeile dargestellt. Dieser Buffer\n   ist auch die Basis für eine weitere nette Funktion : Das Abkürzen von\n   bereits eingegebenen Befehls-Zeilen! Stellen Sie sich vor Sie arbeiten \n   schon eine Weile mit dem CD-Server, und haben ständig das DIR Kommando\n   eingeben, und das wird nu mittlerweile lästig...dann können Sie auch z.B.\n   !di eingeben (!d geht auch!) und dann würde die Eingaberoutine nach einer\n   dementsprechenden Zeichenkette im Buffer suchen (z.B. DIR) und diese dann\n   ausführen...\n\n4) Abkürzungen der Standard-Befehle. Fast alle Befehle lassen sich durch eine\n   Taste abkürzen, z.B. das Kommando HELP -> H !\n\n5) Gesperrte Taste '':''. Diese Taste musste aus Sicherheitsgründen gesperrt\n   werden. Drücken dieser Taste befördert den User direkt in das Start-Dir,\n   das im Icon angegeben wurde...\n@endnode\n\n@node DOWNLOADING "TIPS & TRICKS FÜR DIE DOWNLOADING-GESCHICHTE"\n\n@{u}Download@{uu}\n\nWie sich wohl jeder vorstellen kann, iss es nicht einfach, in die Amiex \nWÄHREND diese läuft neue Devices (und damit auch Pfade) einzutragen und \ndiese der Amiex bekannt zu geben. Daher musste ich ein wenig tricksen :),\num das doch klar zumachen. So kann es z.B. bei Multinode-Systemen passieren,\ndas bei gleichzeitiger Benutzung des CD-Servers von mehreren Usern plötzlich\nFiles mehrere Male gefunden werden, dieses ist jedoch normal und ist einer \nder netten Nebeneffekte des Programms..:)\n\nEin anderer wichtiger Punkt ist die Tatsache, das es @{b}UNMÖGLICH@{ub} ist, mehrere\nFiles @{b}GLEICHEN@{ub} Namens auf einmal zu leechen. Das ist damit begründet, daß\nAmiex solange nach einem file sucht bis es dieses gefunden hat. Danach wird\nnach dem nächsten File gesucht, und hat dieses den gleichen Namen wie das\nFile davor, dann wird dieses geskippt.\n\nSollten Sie doch einmal zwei Files gleichen Namens leechen wollen, dann ver-\nfahren Sie bitte wie folgt:\n\nAngenommen, sie wollen das File INDEX aus Directory CD0:AMINET/ und \nDirectory CD0:AMINET/BIZ/ leechen. Dann gehen Sie zuerst in das Dir \nCD0:AMINET/, leechen das File INDEX. Dann geben Sie ''A C *'' ein, um die \ninterne Pfadliste von CD-Server zu löschen, und wechseln dann in das Dir\nCD0:AMINET/BIZ/ und leechen sich von dort das zweite INDEX-File. Sorry für\ndiese Aktion, aber ich denke mal das der gesamte Komfort von CD-Server diese\nkleinen Restriktionen aufheben sollte oder ? :)))\n\nAls kleiner Bonus sei auch nochmal auf eine Sache hingewiesen, die sonst ja\neigentlich nicht möglich ist, und zwar kann man folgendes eingeben:\n\n              d aminet/biz/dbase/data1.lha readme aminet/index\n\nund CD-Server übergibt der BBS dann nur noch die Filenamen DATA1.LHA, README\nund INDEX, merkt sich jedoch auch gleichzeitig die anderen Pfade und übergibt\ndiese mit beim suchen. Diese Funktion ist identisch mit der @{"Mark Funktion" LINK FLAG}.\n@endnode\n\n@node MARK&FLAG "TIPS & TRICKS FÜR DAS FLAGGEN DER FILES"\n\n@{u}Markieren/Flaggen von Files@{uu}\n\nWie bereits erwähnt, ist die Unterstützung der Wildcards nicht möglich. \nSollte dieser doch angegeben werden, so wird die BBS die files nicht finden,\n@{b}ALSO BITTE NICHT BENUTZEN@{ub}, stattdessen nehmen Sie halt die TAB-Taste für die\nPfadnamen-Erweiterung. Dieses Problem ist bisher für Amiex nicht lösbar (das\nFAME-System hat mittlerweile ein paar spezielle Commands für sowas, und von \ndaher is dieses Problem in einem nächsten Update bereinigt!), da der Server\nder Amiex die Conference-Icons nur einmal beim Start ins Memory liest, und\ndann alle Daten aus dem Speicher holt. Daher reagiert auch Amiex nicht auf\nneu dazugefügte ToolTypes (wie wäre es mit einem Kommando, das die Amiex\nzwingt, das jeweilige Conference-Icon neu einzulesen, ByteMaster ???) !!!\n\nAmiex hat noch einen anderen Nachteil beim Markieren von Files, und zwar ist\ndie Liste der geflaggten Files auf 2048 Bytes (oder mehr) inkl. der Spaces\nbegrenzt! Sollte also Amiex beim Flaggen abbrechen, dann ist meistens der \nString dafür voll, und Sie sollten erstmal ein paar Files leechen,bzw. einige\nFiles aus der Liste löschen. Wenn Sie das FAME-System fahren, dann wird\ndieses Problem nicht auftreten, da FAME ECHTE DYNAMISCHE LISTEN verwendet,\nund von daher nur von Ihrer Hardware begrenzt ist, nicht vom Willen des\nProgrammierers!\n\nWie bereits im Kapitel @{"DOWNLOAD" LINK DOWNLOADING} erwähnt, können Sie auch beim Flaggen von\nFiles einen Pfad mit angeben:\n\n                    A aminet/biz/patch/suxx.lha\n\nund CD-Server flaggt nur noch den Filenamen ''suxx.lha'', behält jedoch den\nPfad im Speicher und übergibt diesen dann auch beim Downloaden der BBS.\n@endnode\n\n@node GREETINGS "DIE ALLSEITS BELIEBTEN GRÜßE :)"\n\n@{u}SieGeL & ByteAndi grüßen:@{uu}\n\nSpy/trSi        - Für die Argument-Parsing & Dirscan-Routinen :)\nsTRIDER/sDC     - Für das echt GEILE @{"FAME" LINK FAME}-System :)) DER SAFT IST MIT DIR!\nARGON/dTL       - Scheisse mit dem PCMCIA-Rom, koof nen neues FileSystem Alda!\ndEATH aNGEL/sDC - Fürs Testen auf @{"FAME" LINK FAME} und überhaupt :)\nBloodRock/SDC   - Da ASM-Posse strikes back..:) \nfUTZi/tRSi      - Willkommen im Club oldae :)\n\n ...uND nATÜRLICH aLLE bETATESTER & rEGISTRIERTE uSER fÜR iHRE uNTERSTÜTZUNG,\n\n  aRTCORE! fÜR iHREN mEGA-gEILEN rEQUEST-sERVICE uND aLLE aNDEREN dIE wIR\n\n        hIER vERGESSEN hABEN zU eRWÄHNEN...fÜHLT eUCH gEGRÜSST ! :)\n\n------------------------------------------------------------------------------\n\n                           @{u}Technical Info@{uu}\n\nMain Code & Idea  : SieGeL/tRSi\nAdditional Coding : ByteAndi/tRSi (EDIT-Routine) & Spy/tRSi (Dir-Scanroutine)\nGFX painted by    : (-rAPID-) fROM dA fAMOUS aRTCORE pOSSE !\n\nCD-Server wurde auf zwei A4000/040 entwickelt und erfolgreich auf folgenden\nSystemen getestet : \n\n A5oo  5MB  68ooo           OS 2.o  Amiex 4.9        - SieGeL\nA12oo  6MB  68o2o+68881 Co. OS 3.o  Amiex 4.7        - ARGON\nA12oo 10MB  68o3o+68882 Co. OS 3.o  Amiex 4.7        - BYSIS\nA2ooo 14MB  68o3o+68882 Co. OS 2.o  @{"FAME" LINK FAME}-System      - dEATH aNGEL\nA3ooo 10MB  68o3o+68882 Co. OS 2.o  Amiex 4.6        - Spy\nA4ooo 14MB  68o3o+68882 Co. OS 3.o  @{"FAME" LINK FAME}-System      - sTRIDER\nA4ooo  6MB  68o4o+68o4o Co. OS 3.o  Amiex 4.9        - ByteAndi\nA4ooo 14MB  68o4o+68o4o Co. OS 3.1  @{"FAME" LINK FAME} & Amiex 4.9 - SieGeL\n\n            @{"(tRSi/X-iNNOVATiON) - wO sINDSE dENN ?" LINK ADDY1}\n@endnode\n\n@NODE PRGLIST "LISTE ALLER MEINER PROGRAMME BIS HEUTE !"\n\n@{u}Programm-Liste@{uu}\n\nUm Ihnen einen Überblick zu geben, was Sie als registrierter User bei mir\nbekommen, hier eine Liste aller meiner bisher geschriebenen Programme :\n\n@{b}Zur Zeit für registrierte User verfügbare Prg.:@{ub}\n\nCD-Server V1.00     - CD-Server für @{"FAME" LINK FAME}/AMIEX\nwORLD-cLOCK V1.18   - Weltzeit-Door für @{"FAME" LINK FAME}/AMIEX\nmEGA-vIEW V2.07     - Bester TXT-Viewer für @{"FAME" LINK FAME}/AMIEX\nlASTCALLERS V0.04   - Lastcaller-Util für @{"FAME" LINK FAME}, faster than SAMILOG!\nsOFT-dEL V1.01      - Schneller Online-Softdel. für @{"FAME" LINK FAME} & AMIEX\nU-sTAT V1.31        - User-Statistik Door, frei konfigurierbar (@{"FAME" LINK FAME} & /X)\nASKII-REQUEST V0.02 - aSKII-Requester Door (nur AMIEX!)\n\n@{b}Noch in Arbeit,bzw. muß überarbeitet werden:@{ub}\n\nO-Page V1.1         - Operator Page mit integrierter Highscore\nIssue-Writer V0.4   - Door um Meinungen zu schreiben, etc. (nur /X!)\noRDER V.02          - Door for Ordering sites, i.e. sell hardware via BBS..\nBBS-VIEW V1.1       - CLI-Util zum Anzeigen von ANSI-Pics, 100% ASM!\nU-Convert V0.2      - Util zum Konvert. von /X user.data -> @{"FAME" LINK FAME} user.data\nBullcreator V1.0    - Highscore-Util für ByteKiller V1.0, wird noch geupdated\n\nIch denke mal, 30,- DM (bzw.$20) ist ja wohl nicht zuviel für diese Programme,\noder etwa doch ? Und natürlich werde ich, soweit es machbar ist, auch alle \nWünsche oder Neuheiten in diese Programme einsetzen...um mit uns in Kontakt\nzu treten, bitte mal in Kapitel @{"CONTACTS" LINK ADDY1} nachsehen.\n@endnode\n\n@node FAME "WAS ZUM TEUFEL IS EIGENTLICH FAME ????"\n\n''Was ist FAME ?'' , werden Sie fragen...FAME ist ein neues BBS-System,welches\nvon Strider (Syndicate) geschrieben wird, und zu 90% kompatibel zu Standard-\nAmiexdoors ist. Natürlich hat es auch einen komplett eigenen Msg-Port mit\nweit über 1000 (!!) Kommandos. Desweiteren ist dieses System komplett von\nder verwendeten Hardware abhängig, was bedeutet, um so mehr RAM, umso mehr\nkann man auch durchdrehen...:)\n\nDie Konfiguration der BBS erfolgt über ein sehr komfortablen SystemEditor,\nwelcher VOLLSTÄNDIG OHNE ICONS die BBS konfiguriert und dabei komplett mit\nder Maus zu bedienen ist. Die Kontrolle der BBS läuft über einen ebenfalls\nkomplett mit der Maus bedienbaren Server (Commodity!).\n\nDadurch das die BBS noch in der Entwicklungs-Phase steckt, ist sie derzeit\nauch noch nicht erhältlich, aber wenn Sie weitere Informationen über dieses\nSystem haben wollen, dann melden Sie sich bei uns und wir geben Ihnen dann\nalle Informationen die Sie brauchen.\n@endnode\n\n@node ADDY1 "(tRSi/X-iNNOVATiON) WHQ & Beta Site"\n\n@{APEN 2}                           hOW tO cONTACT uS : @{aPEN 1}\n\n   _____________  __________               /\\\n  |     __     /__\\__      /___________   /  \\             _____\n  |   ________/    /      /_\\____      \\_//   \\___________|_____|_______\n  |     |  \\      /      /      /      _//     \\    ______________      \\_\n  l_____|   \\___________/______/       \\_______/\\______   \\_    l/       /\n                              \\________/      /____________/____/       /\n                                       _________________       \\_______/\n     ______ /\\____ ____________ _______\\______   ______/\n    /      /_      \\    __    /_\\_____      \\_    |\n  _/      \\/______/   _______/\\      /       /    |    · PUN¡sHMeNT ¡NC. ·\n  \\________\\    _/_____________\\____/  Mo!  /_____|\n                /                  \\_______/\n                                           /\\  ______________  ___________\n     1oo% LeGaL sTUFF oN aM¡Ga^PC         /  \\_\\_______      \\_\\    _____/___\n                                         //   \\       /       /     /       /\n     RUNN¡NG oN a4ooo/4o · V.FasT      _//     \\_____/       /_____________/\n                                       \\________/   \\_______/\n\n TR¡sTaR & ReD seCToR ¡NC. (/X·¡NNoVaT¡oN) WHQ, aRTcORE! GHQ & eTH¡C D¡sT s¡Te\n\n   [> +49-(o)-3o-694-84-7o <]  sYsoP: s¡eGeL/TRs¡  [> +49-(o)-3o-694-sOON! <]\n\n                     @{"> pARALYSIS BBS - dISTRIBUTION sITE <" LINK ADDY2}\n@endnode\n\n@node ADDY2 "(tRSi/X-iNNOVATiON) bETA & dIST SITE"\n       ____                                                                  \n    ___\\  /______________________________________________________________    \n   /   \\\\//                                                              \\   \n  /     \\/ -[ THe BeST eQUiPPeD PuBLIC DoMAIN BoaRD IN BeRLIN ]-          \\  \n /   -[ WiTH 4 GReaT U.S.ROBOTICS V.FAST CLASS MoDeMS WiTH FLaSH-RoMS ]-   \\ \n/                                                                           \\\n\\                        -- -[ SYNDIC/\\TE WHQ ]- --                         /\n \\   _____  _____    _____   _____  __      ___ __  _____   ___ _____      / \n  \\ /  _  \\/  _  \\  /  _  \\ /  _  \\/  |___ /   |  \\/   __)_/ __|   __)_   /  \n   /   |   \\  _   \\/   |  //   _   \\  |   \\\\_____  \\___    \\¯  |___    \\ /   \n  /   _____/  |    \\_ __   \\_  |    \\ |    \\   |    \\|      \\  | |      \\    \n  \\____| \\____|    /___|    /__|    /___   / _______/___    /__|____    /    \n      \\       l___/    l___/   l___/  \\___/___/  [ViC!]\\___/       \\___/     \n       \\                                                             /       \n        \\SYSTeM CHieFS: SPY/TRSi,ARTHuR DeNT,PHaNToM,Cat,JTC,big-rat/        \n         \\                                                         /         \n          \\   1: +49(0) 30 721 6071 USR DuAL STaNDaRD V.34 28.8   /          \n           \\  2: +49(0) 30 721 6072 USR DuAL STaNDaRD V.34 28.8  /           \n            \\ 3: +49(0) 30 721 6073 USR DuAL STaNDaRD V.34 28.8 /            \n             \\4: +49(0) 30 722 6065 USR DuAL STaNDaRD V.34 28.8/             \n              \\                                   /\\          /              \n               \\_________________________________//\\\\________/               \n                                                 /__\\\n\n                        SUPPORTS ONLY PD-/SHAREWARE !\n@endnode\n','\n',char(10)),NULL,'auto-added',58824,10,0,NULL,NULL,'cdserver','scan',1780048442);
INSERT INTO door_catalog VALUES('cdshel','CDSHEL.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CDSHEL.LHA','cdshell','XIM','cdshell',NULL,'SiGMA',NULL,'| CDShell/FTP-Emulator Version 1.0 (XIM!)  | l__________________________________________| |                                          |',replace('.------------------------------------------.\n| CDShell/FTP-Emulator Version 1.0 (XIM!)  |\nl__________________________________________|\n|                                          |\n| New CD-ROM Server for all Versions of /X |\n| S!X, Custom BBS, Swift Professional etc. |\n|     Easy to use and easy to install.     |\n|     All "Work" Done by SiGMA SEVEN!      |\n`-[XIM Door]----[ 01-10-95 ]----[S!X & /X]-''\n','\n',char(10)),'cdshell.doc',replace('.----------------------------------------------------------------------------.\n| CD-Shell/FTP Emulator for CD-ROMs, a XIM Door by SiGMA SEVEN!  Version 1.0 |\n`----------------------------------------------------------------------------''\n\nWell the Reason why i made/programmed/created This XIM Door was that i couldnt\nfind any single CD-ROM Door for "my" BBS Program S-Express (Commercial Break)\nThere was one (Yes just one..) Door that i found which did offer CD-ROM Usage\non any Express System (even tho it claimed Just for /X 3.x & 4.x), Somhow\ni wasnt too satisfied with how it operates, sure a Nice Menu and GUI etc but\nwell, i prefer a different Way, and a easier Installation too.\nSo here it is, a FTP/NcFTP (comes off the Internet :) Like CD-ROM Server/Shell\nEasy to use for the User and easy to install for the Sysops.\nI`m providing the Source Code of it in this Archive (I know that this might\ncause some "wave" of Variants coming up out of nowhere but hell... who cares)\nso everyone can see how lame i`m coding, still it works pretty good.\n(All Done just with basic C knowledge... nothing big, and nothing to be proud\nof)\n\n\nAnyways, here`s what you`ll need...\n\nRequirements:\n=============\nAn Amiga (any Type)\nS!Xpress / Custom BBS or any other /X Clones aswell as /X itself.\nEnough RAM\nEnough Harddisk Space for the Temporary Directory\na CD-ROM, or anything else where you`d like to use this Program for.\nLHA - the LhArc Program (c) by Stefan Boberg - accessable in a AmigaDOS\n      Path (such as C: )\n\n------------------------------------------------------------------------------\n\nLets go on with the ''HOW DO I INSTALL THIS?'' Question:\n\nIts easy..\nmake/create a new Directory in the same Directory where you store your\nDoor/Modules in.\nAfter this put all of the Files that are in the Directory called CDSHELL\ninto the newly created one.\n(e.g.: COPY RAM:CdShell/#? DOORS:cdserver/ )\nTheres no need to keep the same Directory Name i gave it. It`s "Smart" Enough\nto find the Configuration File. Also gives you the possibility to have multiple\nCdShell`s running, just incase you have a Millions of CD-ROMs or want a \nSyQuest Unit to be used like that..)\n\nNext Step would be to take an Editor and Edit the Config File called\nCDSHELL.CFG. I put a sample one into the Distribution Archive.\nThe Sample One looks like this:\n\nCD0:\ndh2:tmp/\n1\n\nNow what does this want to tell us?\n\nFirst Line : Path to your CD-ROM , in my Case just CD0:\nSecond Line: Path to your TEMPORARY Directory (which you will make later on)\nThird Line : Default Automatic Directory Showing. (0= AutoDir ON, 1= AutoDir OFF)\n\nThats all, maybe more soon.\n\nNow to this Second Line Temporary Directory.\nYou will have to MAKE this Directory, the Door is copying the Files the User\nwould like to get into this Directory. Since CD-ROMs are still rather slow this\nis "the Perfect Solution" (maybe not really BUT it works).\nMake sure you have enough Room on the Harddisk where you put this Directory on\nsince i`m NOT doing any  FreeSpace Checking (Lame, but i`m a lazy bastard)\n\n(EG: MAKEDIR DH2:TMP)\n\nNext Step: Add the Pathname of this Directory to the Conferences Path Names.\n\n(This is like the easiest way of handling the Downloading and Crediting the \n Users Download Bytes, unless you`d want to give your Guys FreeBees...)\n\nOn S!X, Custom BBS and /X upto Version 2.39 its the File called\n<YourConferencePath>/PATHS\n\nOn /X 3.x and higher it should be in the Conference Directory ICON`s ToolTypes\nlike "DLPATH.999=dh2:tmp/" (w/out the Quotes o`course)\n\n\nThats it about Installing this Door. (Should work :) )\n\n------------------------------------------------------------------------------\nNext Part "WHAT ARE THE COMMANDS IN THE SHELL?"\n\nHere`s a small List on the Shell Commands:\n\nDos Operations:\n~~~~~~~~~~~~~~~\nTYPE  		DIR   		LIST  	\nCD    		AUTODIR\n       \nFile specific Operations:\n~~~~~~~~~~~~~~~~~~~~~~~~~\nGET <filename>\nMGET <file1> <file2> <file3...> (etc.)\n\nLHA V <filename> \nLHA L <filename> \nLHA P <archive> <file_in_Archive>\n                 \nMisc. Operations:\n~~~~~~~~~~~~~~~~~\nVERSION          QUIT             ?\n\nSmall Descriptions:\n\nTYPE :\n======\nJust like the DOS Type Command. Be careful and dont TYPE a Binary File.\n\nDIR  :\n======\nJust like the DOS Dir Command.\n\nLIST :\n======\nJust like the DOS List Command.\n\nCD   :\n======\nJust like the DOS Dir Command.\n(PC Users can even use their CD .. or CD.. :) )\n\nAUTODIR :\n=========\nThis Feature can be turned on or off by just entering AUTODIR.\nIf AutoDir is turned ON it`ll show the Directory right after the User has\ndone a CD into it. (Play around with it and you`ll know what i mean)\n\nGET / MGET:\n===========\nGET a File. Will copy a File to the Temporary Directory and start the Download\n(MGET is basically the same, just that it works with more than one File)\nThe ASTERIKS Wildcard can be used to GET/MGET Files. \nJust like: GET *.dms or MGET filea.lha fileb.lha cd*.lzh\n\nLHA V <filename>:\n=================\nGuess! - Will LIST a LHA/LZH Type File\n(LHA is required to be in C: or any other Path-Assigned Directory)\n\nLHA L <filename>:\n=================\nSame as the one above, just in short Format.\n(LHA is required to be in C: or any other Path-Assigned Directory)\n\nLHA P <FileName> <Text_In_LzhArchive>:\n======================================\nWill print out a File out of a LHA/LZH Archive\neg: LHA P FILE1.LHA File.ReadMe\n(Will print out the File.Readme out of the FILE1.LHA)\n\nVERSION :\n=========\nWill just pop up the Version Information of CDShell\n\nQUIT :\n======\nIf you dont know what this means: SELL YOUR COMPUTER!\n\nand Finally\n\n? :\n===\nDisplays a small Help Text for the User. \n\n\n------------------------------------------------------------------------------\nThats about it... if you have any Problems using this small Program \nor got an Idea on how to improve this small Door Feel free to give my BBS\na Ring (Commercial Break Number 2) :\n\nO ________ _________ _________  __________________  ________ _________   O\n|/   ____/_    \    /_____   _\/   ___________    \/   ____/_    \   _\  |\n/\_____    \_____    \    \   \\     _\__\    \   _>   \__   \_____   \\ |\n\ \    \    \    \    \    \   \\    \    \         \    \    \    \   \\|\n|\ \_________\_________\____\   \\_________\____\    \_________\_________\\n| \/_________/_________/____/\____\________/____/\____\________/_________/\nO---------------------------\/____/-------------\/____/------------[aBn]-O\n|                                                                        |\n|  2 Modem Ports - 14.400 V32/V32bis/V42/V42bis & 16.800 V42/V32/V32bis  |\n|  2 ISDN  Ports - 64.000 -IM WAITING AND WAITING-                       |\n|                                                                        |\nO---[ Node1: +49-5731-40074 ]----------------[ Node2: +49-5731-40076 ]---O\n\n','\n',char(10)),NULL,'auto-added',77161,3,0,NULL,NULL,'cdshl12','scan',1780048442);
