INSERT INTO door_catalog VALUES('charts10','CHARTS10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CHARTS10.LHA',NULL,'XIM','SAMICHARTS','1.00','THE',NULL,'BY THE BOSS/LITTLE BUG 1992',replace('SAMICHARTS V1.00\nBY THE BOSS/LITTLE BUG 1992\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 19:07:33  ON NODE: 1\n','\r',char(13)),'\n',char(10)),NULL,NULL,7020,1,0,NULL,NULL,NULL,'scan',1780048442);
INSERT INTO door_catalog VALUES('chat34','CHAT34.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CHAT34.LHA',NULL,'XIM','chat3.4',NULL,NULL,NULL,'TeaM VeRsIoN 3.4',replace('MuLtI NoDe ChAt DoOr bYe /X DeVeLoPmEnT\nTeaM VeRsIoN 3.4\n','\n',char(10)),'RELEASE_NEWS.txt',replace('INSERT INTO door_catalog VALUES('chatm20','CHATM20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CHATM20.LHA','Chat-O-Meter','XIM','Chat-O-Meter',NULL,NULL,NULL,'.-\_  \/  _/   __/______\/___/-------------. | /   \/   \______  \_  \/  \_   mYSTIC!   | :/     \____/   _____/___    / /X dIVISION .',replace('  __/\  __________ _ ___  /\__              \n.-\_  \/  _/   __/______\/___/-------------.\n| /   \/   \______  \_  \/  \_   mYSTIC!   |\n:/     \____/   _____/___    / /X dIVISION .\n/_______\-\_____/--sTZ--l___/--------------:\n| KiLLraVeN/MYSTiC BRiNGS: CHAT-O-METER v2 |\n| *CREATES BULLETiN ABOUT YOUR CHAT-TiMES* :\n: o Cool Layout (StZ!) o Sysop Chat Top 10 |\n| o Hide chat & more   o User Statistics   :\n: o Conversion util to upgrade from v1.x!  |\n`------------------------------------------''\n','\n',char(10)),'Chat-O-Meter.Guide',replace('@DATABASE "Chat-O-Meter.GUiDE"\n@REMARK  .-------------------------------------------------------.\n@REMARK  | This document should be read with AmigaGuide (OS 2.x) |\n@REMARK  | or MultiView (OS 3.x) or any other guide reader. Tnx. |\n@REMARK  `-------------------------------------------------------''\n@REMARK  $VER: Chat-O-Meter 2.0.9\n@WIDTH 80\n@NODE MAIN "KiLLER Comment - MYSTiC 1994 - © 1994 KiLLraVeN/MYSTiC"\n                            Guide to Chat-O-Meter\n                 for Ami-Express 3.38+ Bulletin Board Systems\n\n                            Program version: 2.0.9\n               Compilation Date/Time: Sun Dec 25 14:00:09 1994\n\n                        © 1994/1995 by @{"KiLLraVeN/MYSTiC" link Contact}\n\n                   ... another fine MYSTiC /X production ...\n\n                       @{"       UPDATE iNFORMATiON!       " link WhatsNew}\n\n      @{" Welcome Sysop! " link WhatIs}    What is Chat-O-Meter?\n      @{" Features       " link Features}    What can it do?\n      @{" Installation   " link Install}    How to install Chat-O-Meter\n      @{" Conversion     " link Conversion}    How to convert your old 1.x bulletin to 2.x\n      @{" Example 1      " link BullExample}    Example output the bulletin of Chat-O-Meter\n      @{" Example 2      " link ExitChatExample}    Example output when you exit a chat\n      @{" History        " link History}    History of Chat-O-Meter\n      @{" Greetings      " link Greetings}    Greetings, messages and contact info\n@ENDNODE\n\n@NODE WhatIs "What is Chat-O-Meter - © KiLLraVeN/MYSTiC"\n                          - -----------------------.\n                         |  What Is Chat-O-Meter?  |\n                         `----------------------- -\n\n   Chat-O-Meter  is  a  small tool that keeps track of all your chats, in\n   particulair  the  length  of  all  your  chats  with users.  With this\n   information it is able to create a nice looking @{"bulletin" link BullExample} that displays\n   a Top Ten of all times.\n\n   Besides  that,  it  also saves the times of the chats per user. At the\n   end  of  every  chat,  the  user  gets  to  see  his  or  her personal\n   information such as the overall score and total number of chats he/she\n   was engaged in.\n\n   This  only  takes up a small amount of time and hardly any disk space.\n   The  creation of the bulletin only takes up about 1 sec (on a standard\n   machine,  it''s  even  quicker  on 020+ systems) and the file size of a\n   file that holds 400 users is about 3.5Kb.\n\n   Chat-O-Meter  also  is giftware, do with it what you want, but you may\n   not  sell  it.  Distribution on AmiNet is allowed, but distribution on\n   PD  series  is  forbidden  (I  don''t  like  people  making money of my\n   products).\n\n   Anyway,  this  version has been totally rewritten from scratch and now\n   has a cool logo made by Stezothetic, so enjoy it!\n\n                                                        @{"-KiLLraVeN/MYSTiC" link Contact}\n@ENDNODE\n\n@NODE WhatsNew "What''s New in version 2.0 - © KiLLraVeN/MYSTiC"\n                           - --------------------.\n                          |  New in version 2.0  |\n                          `-------------------- -\n\n   The  previous  version ( 1.2 ) was released over one year ago (October\n   1993)  and  to tell you the truth, the coding was lousy and it was not\n   that  sysop  friendly.   But  do  not  despair,  this version has been\n   totally rewritten (from scratch!) and is much smarter and has got some\n   nice new options.  Better forget all about the previous version :-)\n\n   It  has  to  be  said  that I would have never created this version if\n   Quartz  hadn''t  asked  for  it  AND if Stezothetic hadn''t made such an\n   awesome logo.  It seems people use my tools after all :-)\n\n   First  of  all,  the best improvement is that it is now able to detect\n   wether you started or ended a chat.  So if you were a previous user of\n   Chat-O-Meter,  the  times  of  deleting  the  old data file before you\n   started another chat are over :) Lost carriers are no problem anymore.\n\n   Another  *BIG* improvement is the @{"new layout" link BullExample}, done by Stezo (Stz).  It\n   now  has  got a really great logo and nice colours.  You''ll love it, I\n   do!  Many thanks to Stezothetic for creating the logo!\n\n   What  also  new is, is the fact that a record is kept of all chats per\n   user.   One  file is kept that contains all information about ALL your\n   chats ever (since you started to use CoM ofcoz) per user.  I will also\n   create  a  door/tool that creates a nice bulletin out of that one.  If\n   you  think  this  is  nonsense, you are able to turn it off so no data\n   file will be created.\n\n   The  previous  version also did not set the ENV:  variable of AMi-X to\n   the right value, so users that performed a ''who'' saw that the user you\n   were  chatting  with was ''using a door''.  This has been fixed.  But if\n   you  liked  that ''feature'' of Chat-O-Meter, it is still able to hide a\n   chat. Privacy above all (nope, there is no PGP function :) ).\n\n   That''s it.  I hope you''ll like it, it''s one of those nice little doors\n   that  makes  just  the  difference  between your board and your follow\n   sysops'' boards.\n@ENDNODE\n\n@NODE Features "Features of Chat-O-Meter - © KiLLraVeN/MYSTiC"\n                      - ------------------------------.\n                     |  Features of Chat-O-Meter 2.0  |\n                     `------------------------------ -\n\n   ­ Creates a bulletin wherever you want (configurable)\n\n   ­ Very nice/cool layout thanks to Stezothetic (Stz)\n\n   ­ Ability to hide a chat from other users\n\n   ­ Fast creation of data files and bulletin\n   \n   ­ Small data files (308 bytes and 2 bytes/user)\n   \n   ­ Keeps track of sysop chats, but also user chats. That is,\n     a record is kept per user with his/her personal total chat\n     time and total number of chats.\n     \n   ­ At the end of a chat, a small bulletin is shown stating the\n     latest statistics. See @{"example" link ExitChatExample}.\n     This is configurable (Quiet mode is available).\n     \n   ­ Configurable ''Show Bulletin [ Y/n ]'' when user has entered\n     the Chat-O-Meter Top Ten.\n     \n   ­ Configurable stripping of plural words ( 1 mIN instead of 1 mINS)\n\n   ­ Easy to use\n@ENDNODE\n\n@NODE ExitChatExample "Exit Chat Example - © KiLLraVeN/MYSTiC"\n\n   Every time you exit a chat, you will get to see this small bulletin.\n\n :                                                                         :\n-O-------------------------------------------------------------------------O-\n :  /X MYSTiC       Chat-O-Meter v2.0  by  KiLLraVeN/MYSTiC     /X MYSTiC  :\n ¡                                                                         .\n :  tHIS cHAT:  0:00:11 -O- oVERALL tIME: 0002:07:44 -O- cHAT #: 187       ¡\n .         yOUR oVERALL sCORE: 0000:12:46 -O- yOUR cHAT #: 132             :\n .                                                                         |\n :   sORRY dUDE, nO Chat-O-Meter tOP tIME tODAY, tRY aGAIN sOON, oKAY?!    :\n-O-------------------------------------------------------------------------O-\n :                                                                         :\n\n   However,   when   you   specify   that   you  don''t  want  a  userfile\n   (NO_USERFILE), you will get this as output:\n\n :                                                                         :\n-O-------------------------------------------------------------------------O-\n :  /X MYSTiC       Chat-O-Meter v2.0  by  KiLLraVeN/MYSTiC     /X MYSTiC  :\n ¡                                                                         .\n :  tHIS cHAT:  0:00:02 -O- oVERALL tIME: 0002:07:49 -O- cHAT #: 190       ¡\n .                                                                         |\n :   sORRY dUDE, nO Chat-O-Meter tOP tIME tODAY, tRY aGAIN sOON, oKAY?!    :\n-O-------------------------------------------------------------------------O-\n :                                                                         :\n\n@ENDNODE\n\n@NODE Install "Installation of Chat-O-Meter - © KiLLraVeN/MYSTiC"\n                      - -----------------------------.\n                     |  How to install Chat-O-Meter  |\n                     `----------------------------- -\n\n   First  of  all, you can put the executable (Chat-O-Meter) anywhere you\n   like.   The  data  files  will  be  created in that same directory.  I\n   suggest  you  put it in DOORS:Chat-O-Meter/ but hey, it''s up to you (I\n   just  hate  it  when people hard code a path in their program, haven''t\n   they heard of the PROGDIR:  assign?).\n\n   Secondly,  Chat-O-Meter  needs  to be started with an MCI command from\n   the  STARTCHAT.TXT  and  ENDCHAT.TXT  files  that can be found in your\n   BBS:NODEx/   directory.    Two   icons   have   been  supplied  called\n   `Chat_Start.info''  and  `Chat_End.info''.   I recommend you put them in\n   your  BBS:Commands/SYSCmd/  directory,  as  is  standard with commands\n   started with an MCI command.\n\n   For  those sysops who don''t know how to implement Chat-O-Meter in your\n   STARTCHAT.TXT  and  ENDCHAT.TXT,  make  sure the text files contain at\n   least the following lines:\n\n                 STARTCHAT.TXT           ENDCHAT.TXT\n                 -------------           -----------\n                 ~                       ~\n                 ~CC_CHAT_START          ~CC_CHAT_END\n\n   It  doesn''t  matter wether you''ve got a logo in those files.  Just put\n   the text in there somewhere.\n\n   Once you have copied the icons to your BBS:Commands/SYSCmd/ directory,\n   check out the following tooltypes:\n\n   Chat_Start.info\n   ---------------\n   STACK=50000          ; Keep it this high, everything is done on stack\n   There are no more tooltypes for this icon.\n   \n   Chat_End.info\n   -------------\n   CHAT_END             : This  is how Chat-O-Meter recognizes the end of\n                          a chat. Make sure it is in this icon!\n\n   BULLETIN=            : This  is where you can specify how the bulletin\n                          should be called and where it should be created\n                          (i.e. BULLETIN=BBS:Bulletins/Chat-O-Meter.TXT)\n\n   DONT_ASK             : Normally,  whenever  a user gets in the Top Ten\n                          of Chat-O-Meter,  he/she  will  be asked wether\n                          the  Chat-O-Meter  bulletin  should be shown to\n                          them. However, if you specify this tooltype, no\n                          questions  will  be  asked  and nothing will be\n                          shown.\n\n   DONT_TRUNC           : By  default  all plural ''s''-es will be removed.\n                          So  for  example:  1 hOURS  becomes 1 hOUR  and\n                          1 sECS  becomes  1 sEC.  However,  if you think\n                          that  ruins  the  bulletin (cosmetically),  you\n                          can  override  it  by specifying this tooltype.\n                          All plural ''s''-es will be left alone.\n\n   QUIET                : Whenever  a chat is ended,  a small bulletin is\n                          shown  with  the  latest  statistics about that\n                          chat.  However,  if  you do not want this to be\n                          shown,  specify this tooltype and the user will\n                          even know you are using Chat-O-Meter.  No,  not\n                          even a copyright message ;-)\n\n   NO_USERFILE          : This  version  of  Chat-O-Meter  creates a file\n                          that  contains  all  chat information about the\n                          users,   one  by  one.  So  Chat-O-Meter  knows\n                          from  every  user,  how long he/she has chatted\n                          and  how many times you have chatted with them.\n                          It  doesn''t  take  up  much space,  with around\n                          400  users  you will get a file of about 3.5KB.\n                          If  you  feel  this  is  useless or you have no\n                          need  for  this,  insert this tooltype and that\n                          file   will  not  be  created  plus  the  small\n                          bulletin at the end of a chat will be smaller.\n\n   That are all tooltypes for this moment.  When you are done setting the\n   tooltypes  you  are ready with the installation of Chat-O-Meter.  Have\n   fun and chat your head off!  :-)\n@ENDNODE\n\n@NODE BullExample "Bulletin Example Output - Design by Stezothetic!"\n\n   ASCII  never looks good in AmigaGuide or MultiView, but you''ll get the\n   idea anyway I hope.\n   \n   If  you  might wonder why there are multiple entries for one user, the\n   Chat-O-Meter  Top  Ten  is  sorted  by  the length of the chat, and it\n   doesn''t matter wether a user is present several times in it.\n   \n   This  is  not because I am to lazy to built in that check, but suppose\n   you have a chat of 5 hours with somebody.  The next time you chat with\n   him,  you  have a chat of 7 hours.  Does this mean I should just erase\n   that  5  hour  chat and mention the 7 hour chat?  I think not, that is\n   not  fair.   A  5  hour chat is just as cool as a 7 hour chat and they\n   both deserve to be mentioned.\n\n .                          _  __           /        __  _      ·          .\n-O-_____   ___.___  ___________ //\___   / ·   ______\  .        \ _      -O-\n :/  __/__/   |  ¬\/   _ ¬\____\/____/  · /   /  __ ¬\ -:---------\/-----. :\n_/   |   ¬\_  _    \_  _   \_  \/  ¬\_ / / /_/   \/   \_| >cHAT·O·mETER< | :\n\_____     /__|     /__|    /___     //_/ / \_____     /`----------------'' H\n-:---l____/---l____/---l___//\-l____/-\_\/-------l____/------ ---  --   -  ¡_\n H                       __/  \  ___  ___________  /\_________    _______  \/\n | .------------------.  \_    \/  ¬\/  __ ¬\____\/____/  __ ¬\___\____ ¬\_H\n ¡ :   ·/X mYSTIC!·   :  /     \/    \_ \____/__ \/  ¬\_  \____/__   \/  _/:\n :_`---------------- - _/       \_____/___     /__     /____     /___/    \_\n \/ -  -- --- ---------\_________/--Stz--\____/--l____/----\____/----\_____/-\n :                                                                         |\n !   o1. Muad''Dib             01 hOUR , 20 mINS aND 51 sECS  (22-dEC-94)   :\n |   o2. Muad''Dib             00 hOURS, 25 mINS aND 15 sECS  (22-dEC-94)   :\n O   o3. TyCooN/MYSTiC        00 hOURS, 03 mINS aND 04 sECS  (24-dEC-94)   ¡\n |   o4. TyCooN/MYSTiC        00 hOURS, 01 mIN  aND 51 sECS  (22-dEC-94)   O\n H   o5. KiLLRaVeN/MYSTIC     00 hOURS, 01 mIN  aND 22 sECS  (21-dEC-94)   |\n :   o6. TyCooN/MYSTiC        00 hOURS, 00 mINS aND 59 sECS  (24-dEC-94)   H\n H   o7. TyCooN/MYSTiC        00 hOURS, 00 mINS aND 51 sECS  (22-dEC-94)   :\n ¡   o8. KiLLRaVeN/MYSTIC     00 hOURS, 00 mINS aND 34 sECS  (21-dEC-94)   ·\n_:   o9. KiLLRaVeN/MYSTIC     00 hOURS, 00 mINS aND 32 sECS  (21-dEC-94)   :_\n\:   1o. KiLLRaVeN/MYSTIC     00 hOURS, 00 mINS aND 29 sECS  (22-dEC-94)   :/\n \                                                                         /\n :\        tOTAL # oF cHATS: 190         tOTAL cHAT tIME:    2:07:49      /:\n-O-\---------------------------------------------------------------------/-O-\n :  ·                                                                   ·  :\n\n           (Ghee, I chat a lot with myself don''t you think? :-) )\n\n      The design was done totally by Stezothetic, many thanks for that!\n@ENDNODE\n\n@NODE History "History of Chat-O-Meter - Amazing... :)"\n                  - -------------------------------------.\n                 |  History: Something that once was...  |\n                 `------------------------------------- -\n\n   22-Jan-95   1.0.1    Fixed CoM-Convert; it now reads the name of the\n                        user from the correct place.\n\n   04-Jan-95   1.0.0    Completed CoM-Convert and restyled it.\n\n   03-Jan-95   1.0.0    Created CoM-Convert.\n\n   25-Dec-94   2.0.9    Chat-O-Meter can also run in silent mode now.\n                        New tooltype: QUIET\n\n   25-Dec-94   2.0.8    Merry X-Mas :) Made some internal changes, removed\n                        the stack-check (smaller executable).\n\n   24-Dec-94   2.0.7    Found the bug that caused the strange resets.\n                        I adjusted the wrong variable... sigh... it\n                        should be fixed now.\n\n   24-Dec-94   2.0.6    Allocated memory for some structures by myself\n                        instead of allocating them on the stack. Hope\n                        to have fixed the strange guru''s.\n\n   24-Dec-94   2.0.5ß   Special version for Muad''Dib with DEBUG info.\n\n   24-Dec-94   2.0.5    Tried to fix a bug that caused strange resets on\n                        Muad''Dibs machine (040) and weird crashes on my\n                        own system (total freeze and I had to turn my\n                        computer off for at least one minute!).\n\n   24-Dec-94   2.0.4    Fixed a bug that caused the bulletin only the be\n                        updated in the event of a new entry in the Top\n                        Ten. The Total Chat Time was never updated.\n                        *Reported by Quartz*\n\n   23-Dec-94   2.0.3    Built in the User file, now a record is kept of\n                        every user. A new bulletin perhaps.\n                        New tooltype: NO_USERFILE\n                        \n                        Altered the output after the chat again, now also\n                        contains info about the user him/herself.\n\n   22-Dec-94   2.0.2    Altered the output a bit and made some minor\n                        internal changes that caused a smaller executable.\n\n   21-Dec-94   2.0.1    Altered the output after a chat.\n\n   21-Dec-94   2.0.0    Totally rewrote it from scratch:\n                        - END_CHAT tooltype fixes the problem with lost\n                          carriers and then starting a chat again causing\n                          the start of the chat being the end of a chat.\n                          (Never mind if you don''t get it, it''s fixed!)\n                        *Requested by Quartz*\n\n                        New layout from Stezothetic implemented.\n                        *Thanks to Stezothetic*\n\n   26-Oct-93   1.2      Output file is now sysop-configurable. Now you can\n                        have it saved anywhere you like!\n                        Released: 30-Oct-93\n\n   23-Oct-93   1.1      Implemented safety-procedure so when user drops\n                        carrier in chat the Chat-O-Top doesn''t get mixed up.\n                        Released at: 27-Oct-93\n\n   17-Oct-93   1.0      First release to friends.\n@ENDNODE\n\n@NODE Greetings "Greetings and thanks - © 1994/1995 KiLLraVeN/MYSTiC"\n                            - --------------------.\n                           |  Greetings & Thanks  |\n                           `-------------------- -\n\n   A *BIG* THANKS TO STEZOTHETIC (Stz) FOR CREATING THE DESiGN, THANKS MATE!\n\n   Also thanks to Quartz for stimulating me to create this version.\n\n                                      :\n                                     -O-\n                                      :\n\n   Muad''Dib       -  Finally 3 nodes kicking on 28k8!\n   \n   Quartz         -  Logos make me program :)\n   \n   Stezothetic    -  You''re in the army... nooohow...\n   \n   I-GO           -  Johnnies and Anitas zuigen!\n   \n   Wishbringer    -  Faces... (no, not faeces ;-) )\n   \n   Motive Power   -  War is a fucking tough game!\n   \n   bObO           -  We need to talk ( :) )\n   \n   Zed            -  I hope you like this tool mate.\n   \n   Undertaker     -  Your modules kick ass, nobody can beat you!\n   \n   Arcade         -  Some times are rough, some are tough...\n   \n   MYSTiC Members -  Love you all :-)\n   \n                       ... and everybody I forgot ...\n@ENDNODE\n\n@NODE Contact "How to get in touch with me - © KiLLraVeN/MYSTiC"\n                             - ------------------.\n                            |  Contacting me...  |\n                            `------------------ - \n\n       For FAST response (preferred) please contact me on Internet:\n\n                               [email removed]\n\n                    ( [email removed] -- backup )\n\n                       - - -- --- ------- --- -- - -\n\n                 I can be reached on the following boards:\n\n                       - - -- --- ------- --- -- - -\n\n                The Undiscovered       +31-2294-1442 (USR 28k8)\n                                       +31-2294-4442 (USR 28k8)\n                                       +31-2294-tRY! (USR 28k8)\n\n                Last Outpost           +31-72-201182 (USR 28k8)\n                                       +31-72-157682 (USR 28k8)\n\n         I know, you have to call The Netherlands for it, but it''s\n            the only boards I call on a frequent basis, sorry.\n\n                       - - -- --- ------- --- -- - -\n\n        You can also find me on IRC once in a while on the channels\n                   #amigascne, #amiga, #rave and #megawatt\n@ENDNODE\n\n@NODE Conversion "How to convert your old bulletin - © 1995 KiLLraVeN/MYSTiC"\n                           - ---------------------.\n                          |  Bulletin Conversion  |\n                          `--------------------- -\n\n   For  sysops  that  used  Chat-O-Meter  1.x, there is a special program\n   called  "CoM-Convert"  that allows you to convert your old bulletin to\n   the  new  data  file  that  Chat-O-Meter  2.0  uses.  If you are not a\n   previous user of Chat-O-Meter, you can skip this part.\n\n   To  convert  it,  simply  start  the  program  "CoM-Convert"  from the\n   directory  where  you  have Chat-O-Meter 2.0 installed.  The data file\n   will be created in the directory where you started "CoM-Convert".\n\n   Once  you  have  started the program, a file requester will pop up and\n   you  must select the old bulletin.  Press `OK'' and you will get to see\n   the names (plus additional info) from that bulletin.\n\n   After that, the program will exit (`Ready.'') and you can find the data\n   file  called  `Chat-O-Meter.Data''  in that same directory.  Move it if\n   you  have  to.  The new bulletin will not be created yet!  To do this,\n   you  have  to  start Chat-O-Meter 2.0 from /X (start and end a chat is\n   sufficient).\n\n   That''s it, easy a as a fiddle.\n\n   NOTE : To use this tool, you must have req-tools installed.\n\n   NOTE¹: There  is *NO* check whether the file you feed to "CoM-Convert"\n          really  is an old bulletin from 1.x.  You can even cheat if you\n          want to ;-)\n\n   NOTE²: To  all beta-testers, this conversion util takes in account any\n          old  `Chat-O-Meter.Data'' file.  That is, it doesn''t recalculate\n          a new Top-Ten (it simply converts the old one), but it does ADD\n          the  old  `Total Chat Time''  to the new time and that also goes\n          for the total number of chats.\n@ENDNODE\n','\n',char(10)),'{"STACK":"50000"}','auto-added',48296,6,0,NULL,NULL,'chatm20','scan',1780048442);
INSERT INTO door_catalog VALUES('chatme20','CHATME20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CHATME20.LHA','Chat-O-Meter','XIM','Chat-O-Meter',NULL,NULL,NULL,'.-\_  \/  _/   __/______\/___/-------------. | /   \/   \______  \_  \/  \_   mYSTIC!   | :/     \____/   _____/___    / /X dIVISION .',replace('  __/\  __________ _ ___  /\__              \n.-\_  \/  _/   __/______\/___/-------------.\n| /   \/   \______  \_  \/  \_   mYSTIC!   |\n:/     \____/   _____/___    / /X dIVISION .\n/_______\-\_____/--sTZ--l___/--------------:\n| KiLLraVeN/MYSTiC BRiNGS: CHAT-O-METER v2 |\n| *CREATES BULLETiN ABOUT YOUR CHAT-TiMES* :\n: o Cool Layout (StZ!) o Sysop Chat Top 10 |\n| o Hide chat & more   o User Statistics   :\n: o Conversion util to upgrade from v1.x!  |\n`------------------------------------------''\n','\n',char(10)),'Chat-O-Meter.Guide',replace('@DATABASE "Chat-O-Meter.GUiDE"\n@REMARK  .-------------------------------------------------------.\n@REMARK  | This document should be read with AmigaGuide (OS 2.x) |\n@REMARK  | or MultiView (OS 3.x) or any other guide reader. Tnx. |\n@REMARK  `-------------------------------------------------------''\n@REMARK  $VER: Chat-O-Meter 2.0.9\n@WIDTH 80\n@NODE MAIN "KiLLER Comment - MYSTiC 1994 - © 1994 KiLLraVeN/MYSTiC"\n                            Guide to Chat-O-Meter\n                 for Ami-Express 3.38+ Bulletin Board Systems\n\n                            Program version: 2.0.9\n               Compilation Date/Time: Sun Dec 25 14:00:09 1994\n\n                        © 1994/1995 by @{"KiLLraVeN/MYSTiC" link Contact}\n\n                   ... another fine MYSTiC /X production ...\n\n                       @{"       UPDATE iNFORMATiON!       " link WhatsNew}\n\n      @{" Welcome Sysop! " link WhatIs}    What is Chat-O-Meter?\n      @{" Features       " link Features}    What can it do?\n      @{" Installation   " link Install}    How to install Chat-O-Meter\n      @{" Conversion     " link Conversion}    How to convert your old 1.x bulletin to 2.x\n      @{" Example 1      " link BullExample}    Example output the bulletin of Chat-O-Meter\n      @{" Example 2      " link ExitChatExample}    Example output when you exit a chat\n      @{" History        " link History}    History of Chat-O-Meter\n      @{" Greetings      " link Greetings}    Greetings, messages and contact info\n@ENDNODE\n\n@NODE WhatIs "What is Chat-O-Meter - © KiLLraVeN/MYSTiC"\n                          - -----------------------.\n                         |  What Is Chat-O-Meter?  |\n                         `----------------------- -\n\n   Chat-O-Meter  is  a  small tool that keeps track of all your chats, in\n   particulair  the  length  of  all  your  chats  with users.  With this\n   information it is able to create a nice looking @{"bulletin" link BullExample} that displays\n   a Top Ten of all times.\n\n   Besides  that,  it  also saves the times of the chats per user. At the\n   end  of  every  chat,  the  user  gets  to  see  his  or  her personal\n   information such as the overall score and total number of chats he/she\n   was engaged in.\n\n   This  only  takes up a small amount of time and hardly any disk space.\n   The  creation of the bulletin only takes up about 1 sec (on a standard\n   machine,  it''s  even  quicker  on 020+ systems) and the file size of a\n   file that holds 400 users is about 3.5Kb.\n\n   Chat-O-Meter  also  is giftware, do with it what you want, but you may\n   not  sell  it.  Distribution on AmiNet is allowed, but distribution on\n   PD  series  is  forbidden  (I  don''t  like  people  making money of my\n   products).\n\n   Anyway,  this  version has been totally rewritten from scratch and now\n   has a cool logo made by Stezothetic, so enjoy it!\n\n                                                        @{"-KiLLraVeN/MYSTiC" link Contact}\n@ENDNODE\n\n@NODE WhatsNew "What''s New in version 2.0 - © KiLLraVeN/MYSTiC"\n                           - --------------------.\n                          |  New in version 2.0  |\n                          `-------------------- -\n\n   The  previous  version ( 1.2 ) was released over one year ago (October\n   1993)  and  to tell you the truth, the coding was lousy and it was not\n   that  sysop  friendly.   But  do  not  despair,  this version has been\n   totally rewritten (from scratch!) and is much smarter and has got some\n   nice new options.  Better forget all about the previous version :-)\n\n   It  has  to  be  said  that I would have never created this version if\n   Quartz  hadn''t  asked  for  it  AND if Stezothetic hadn''t made such an\n   awesome logo.  It seems people use my tools after all :-)\n\n   First  of  all,  the best improvement is that it is now able to detect\n   wether you started or ended a chat.  So if you were a previous user of\n   Chat-O-Meter,  the  times  of  deleting  the  old data file before you\n   started another chat are over :) Lost carriers are no problem anymore.\n\n   Another  *BIG* improvement is the @{"new layout" link BullExample}, done by Stezo (Stz).  It\n   now  has  got a really great logo and nice colours.  You''ll love it, I\n   do!  Many thanks to Stezothetic for creating the logo!\n\n   What  also  new is, is the fact that a record is kept of all chats per\n   user.   One  file is kept that contains all information about ALL your\n   chats ever (since you started to use CoM ofcoz) per user.  I will also\n   create  a  door/tool that creates a nice bulletin out of that one.  If\n   you  think  this  is  nonsense, you are able to turn it off so no data\n   file will be created.\n\n   The  previous  version also did not set the ENV:  variable of AMi-X to\n   the right value, so users that performed a ''who'' saw that the user you\n   were  chatting  with was ''using a door''.  This has been fixed.  But if\n   you  liked  that ''feature'' of Chat-O-Meter, it is still able to hide a\n   chat. Privacy above all (nope, there is no PGP function :) ).\n\n   That''s it.  I hope you''ll like it, it''s one of those nice little doors\n   that  makes  just  the  difference  between your board and your follow\n   sysops'' boards.\n@ENDNODE\n\n@NODE Features "Features of Chat-O-Meter - © KiLLraVeN/MYSTiC"\n                      - ------------------------------.\n                     |  Features of Chat-O-Meter 2.0  |\n                     `------------------------------ -\n\n   ­ Creates a bulletin wherever you want (configurable)\n\n   ­ Very nice/cool layout thanks to Stezothetic (Stz)\n\n   ­ Ability to hide a chat from other users\n\n   ­ Fast creation of data files and bulletin\n   \n   ­ Small data files (308 bytes and 2 bytes/user)\n   \n   ­ Keeps track of sysop chats, but also user chats. That is,\n     a record is kept per user with his/her personal total chat\n     time and total number of chats.\n     \n   ­ At the end of a chat, a small bulletin is shown stating the\n     latest statistics. See @{"example" link ExitChatExample}.\n     This is configurable (Quiet mode is available).\n     \n   ­ Configurable ''Show Bulletin [ Y/n ]'' when user has entered\n     the Chat-O-Meter Top Ten.\n     \n   ­ Configurable stripping of plural words ( 1 mIN instead of 1 mINS)\n\n   ­ Easy to use\n@ENDNODE\n\n@NODE ExitChatExample "Exit Chat Example - © KiLLraVeN/MYSTiC"\n\n   Every time you exit a chat, you will get to see this small bulletin.\n\n :                                                                         :\n-O-------------------------------------------------------------------------O-\n :  /X MYSTiC       Chat-O-Meter v2.0  by  KiLLraVeN/MYSTiC     /X MYSTiC  :\n ¡                                                                         .\n :  tHIS cHAT:  0:00:11 -O- oVERALL tIME: 0002:07:44 -O- cHAT #: 187       ¡\n .         yOUR oVERALL sCORE: 0000:12:46 -O- yOUR cHAT #: 132             :\n .                                                                         |\n :   sORRY dUDE, nO Chat-O-Meter tOP tIME tODAY, tRY aGAIN sOON, oKAY?!    :\n-O-------------------------------------------------------------------------O-\n :                                                                         :\n\n   However,   when   you   specify   that   you  don''t  want  a  userfile\n   (NO_USERFILE), you will get this as output:\n\n :                                                                         :\n-O-------------------------------------------------------------------------O-\n :  /X MYSTiC       Chat-O-Meter v2.0  by  KiLLraVeN/MYSTiC     /X MYSTiC  :\n ¡                                                                         .\n :  tHIS cHAT:  0:00:02 -O- oVERALL tIME: 0002:07:49 -O- cHAT #: 190       ¡\n .                                                                         |\n :   sORRY dUDE, nO Chat-O-Meter tOP tIME tODAY, tRY aGAIN sOON, oKAY?!    :\n-O-------------------------------------------------------------------------O-\n :                                                                         :\n\n@ENDNODE\n\n@NODE Install "Installation of Chat-O-Meter - © KiLLraVeN/MYSTiC"\n                      - -----------------------------.\n                     |  How to install Chat-O-Meter  |\n                     `----------------------------- -\n\n   First  of  all, you can put the executable (Chat-O-Meter) anywhere you\n   like.   The  data  files  will  be  created in that same directory.  I\n   suggest  you  put it in DOORS:Chat-O-Meter/ but hey, it''s up to you (I\n   just  hate  it  when people hard code a path in their program, haven''t\n   they heard of the PROGDIR:  assign?).\n\n   Secondly,  Chat-O-Meter  needs  to be started with an MCI command from\n   the  STARTCHAT.TXT  and  ENDCHAT.TXT  files  that can be found in your\n   BBS:NODEx/   directory.    Two   icons   have   been  supplied  called\n   `Chat_Start.info''  and  `Chat_End.info''.   I recommend you put them in\n   your  BBS:Commands/SYSCmd/  directory,  as  is  standard with commands\n   started with an MCI command.\n\n   For  those sysops who don''t know how to implement Chat-O-Meter in your\n   STARTCHAT.TXT  and  ENDCHAT.TXT,  make  sure the text files contain at\n   least the following lines:\n\n                 STARTCHAT.TXT           ENDCHAT.TXT\n                 -------------           -----------\n                 ~                       ~\n                 ~CC_CHAT_START          ~CC_CHAT_END\n\n   It  doesn''t  matter wether you''ve got a logo in those files.  Just put\n   the text in there somewhere.\n\n   Once you have copied the icons to your BBS:Commands/SYSCmd/ directory,\n   check out the following tooltypes:\n\n   Chat_Start.info\n   ---------------\n   STACK=50000          ; Keep it this high, everything is done on stack\n   There are no more tooltypes for this icon.\n   \n   Chat_End.info\n   -------------\n   CHAT_END             : This  is how Chat-O-Meter recognizes the end of\n                          a chat. Make sure it is in this icon!\n\n   BULLETIN=            : This  is where you can specify how the bulletin\n                          should be called and where it should be created\n                          (i.e. BULLETIN=BBS:Bulletins/Chat-O-Meter.TXT)\n\n   DONT_ASK             : Normally,  whenever  a user gets in the Top Ten\n                          of Chat-O-Meter,  he/she  will  be asked wether\n                          the  Chat-O-Meter  bulletin  should be shown to\n                          them. However, if you specify this tooltype, no\n                          questions  will  be  asked  and nothing will be\n                          shown.\n\n   DONT_TRUNC           : By  default  all plural ''s''-es will be removed.\n                          So  for  example:  1 hOURS  becomes 1 hOUR  and\n                          1 sECS  becomes  1 sEC.  However,  if you think\n                          that  ruins  the  bulletin (cosmetically),  you\n                          can  override  it  by specifying this tooltype.\n                          All plural ''s''-es will be left alone.\n\n   QUIET                : Whenever  a chat is ended,  a small bulletin is\n                          shown  with  the  latest  statistics about that\n                          chat.  However,  if  you do not want this to be\n                          shown,  specify this tooltype and the user will\n                          even know you are using Chat-O-Meter.  No,  not\n                          even a copyright message ;-)\n\n   NO_USERFILE          : This  version  of  Chat-O-Meter  creates a file\n                          that  contains  all  chat information about the\n                          users,   one  by  one.  So  Chat-O-Meter  knows\n                          from  every  user,  how long he/she has chatted\n                          and  how many times you have chatted with them.\n                          It  doesn''t  take  up  much space,  with around\n                          400  users  you will get a file of about 3.5KB.\n                          If  you  feel  this  is  useless or you have no\n                          need  for  this,  insert this tooltype and that\n                          file   will  not  be  created  plus  the  small\n                          bulletin at the end of a chat will be smaller.\n\n   That are all tooltypes for this moment.  When you are done setting the\n   tooltypes  you  are ready with the installation of Chat-O-Meter.  Have\n   fun and chat your head off!  :-)\n@ENDNODE\n\n@NODE BullExample "Bulletin Example Output - Design by Stezothetic!"\n\n   ASCII  never looks good in AmigaGuide or MultiView, but you''ll get the\n   idea anyway I hope.\n   \n   If  you  might wonder why there are multiple entries for one user, the\n   Chat-O-Meter  Top  Ten  is  sorted  by  the length of the chat, and it\n   doesn''t matter wether a user is present several times in it.\n   \n   This  is  not because I am to lazy to built in that check, but suppose\n   you have a chat of 5 hours with somebody.  The next time you chat with\n   him,  you  have a chat of 7 hours.  Does this mean I should just erase\n   that  5  hour  chat and mention the 7 hour chat?  I think not, that is\n   not  fair.   A  5  hour chat is just as cool as a 7 hour chat and they\n   both deserve to be mentioned.\n\n .                          _  __           /        __  _      ·          .\n-O-_____   ___.___  ___________ //\___   / ·   ______\  .        \ _      -O-\n :/  __/__/   |  ¬\/   _ ¬\____\/____/  · /   /  __ ¬\ -:---------\/-----. :\n_/   |   ¬\_  _    \_  _   \_  \/  ¬\_ / / /_/   \/   \_| >cHAT·O·mETER< | :\n\_____     /__|     /__|    /___     //_/ / \_____     /`----------------'' H\n-:---l____/---l____/---l___//\-l____/-\_\/-------l____/------ ---  --   -  ¡_\n H                       __/  \  ___  ___________  /\_________    _______  \/\n | .------------------.  \_    \/  ¬\/  __ ¬\____\/____/  __ ¬\___\____ ¬\_H\n ¡ :   ·/X mYSTIC!·   :  /     \/    \_ \____/__ \/  ¬\_  \____/__   \/  _/:\n :_`---------------- - _/       \_____/___     /__     /____     /___/    \_\n \/ -  -- --- ---------\_________/--Stz--\____/--l____/----\____/----\_____/-\n :                                                                         |\n !   o1. Muad''Dib             01 hOUR , 20 mINS aND 51 sECS  (22-dEC-94)   :\n |   o2. Muad''Dib             00 hOURS, 25 mINS aND 15 sECS  (22-dEC-94)   :\n O   o3. TyCooN/MYSTiC        00 hOURS, 03 mINS aND 04 sECS  (24-dEC-94)   ¡\n |   o4. TyCooN/MYSTiC        00 hOURS, 01 mIN  aND 51 sECS  (22-dEC-94)   O\n H   o5. KiLLRaVeN/MYSTIC     00 hOURS, 01 mIN  aND 22 sECS  (21-dEC-94)   |\n :   o6. TyCooN/MYSTiC        00 hOURS, 00 mINS aND 59 sECS  (24-dEC-94)   H\n H   o7. TyCooN/MYSTiC        00 hOURS, 00 mINS aND 51 sECS  (22-dEC-94)   :\n ¡   o8. KiLLRaVeN/MYSTIC     00 hOURS, 00 mINS aND 34 sECS  (21-dEC-94)   ·\n_:   o9. KiLLRaVeN/MYSTIC     00 hOURS, 00 mINS aND 32 sECS  (21-dEC-94)   :_\n\:   1o. KiLLRaVeN/MYSTIC     00 hOURS, 00 mINS aND 29 sECS  (22-dEC-94)   :/\n \                                                                         /\n :\        tOTAL # oF cHATS: 190         tOTAL cHAT tIME:    2:07:49      /:\n-O-\---------------------------------------------------------------------/-O-\n :  ·                                                                   ·  :\n\n           (Ghee, I chat a lot with myself don''t you think? :-) )\n\n      The design was done totally by Stezothetic, many thanks for that!\n@ENDNODE\n\n@NODE History "History of Chat-O-Meter - Amazing... :)"\n                  - -------------------------------------.\n                 |  History: Something that once was...  |\n                 `------------------------------------- -\n\n   22-Jan-95   1.0.1    Fixed CoM-Convert; it now reads the name of the\n                        user from the correct place.\n\n   04-Jan-95   1.0.0    Completed CoM-Convert and restyled it.\n\n   03-Jan-95   1.0.0    Created CoM-Convert.\n\n   25-Dec-94   2.0.9    Chat-O-Meter can also run in silent mode now.\n                        New tooltype: QUIET\n\n   25-Dec-94   2.0.8    Merry X-Mas :) Made some internal changes, removed\n                        the stack-check (smaller executable).\n\n   24-Dec-94   2.0.7    Found the bug that caused the strange resets.\n                        I adjusted the wrong variable... sigh... it\n                        should be fixed now.\n\n   24-Dec-94   2.0.6    Allocated memory for some structures by myself\n                        instead of allocating them on the stack. Hope\n                        to have fixed the strange guru''s.\n\n   24-Dec-94   2.0.5ß   Special version for Muad''Dib with DEBUG info.\n\n   24-Dec-94   2.0.5    Tried to fix a bug that caused strange resets on\n                        Muad''Dibs machine (040) and weird crashes on my\n                        own system (total freeze and I had to turn my\n                        computer off for at least one minute!).\n\n   24-Dec-94   2.0.4    Fixed a bug that caused the bulletin only the be\n                        updated in the event of a new entry in the Top\n                        Ten. The Total Chat Time was never updated.\n                        *Reported by Quartz*\n\n   23-Dec-94   2.0.3    Built in the User file, now a record is kept of\n                        every user. A new bulletin perhaps.\n                        New tooltype: NO_USERFILE\n                        \n                        Altered the output after the chat again, now also\n                        contains info about the user him/herself.\n\n   22-Dec-94   2.0.2    Altered the output a bit and made some minor\n                        internal changes that caused a smaller executable.\n\n   21-Dec-94   2.0.1    Altered the output after a chat.\n\n   21-Dec-94   2.0.0    Totally rewrote it from scratch:\n                        - END_CHAT tooltype fixes the problem with lost\n                          carriers and then starting a chat again causing\n                          the start of the chat being the end of a chat.\n                          (Never mind if you don''t get it, it''s fixed!)\n                        *Requested by Quartz*\n\n                        New layout from Stezothetic implemented.\n                        *Thanks to Stezothetic*\n\n   26-Oct-93   1.2      Output file is now sysop-configurable. Now you can\n                        have it saved anywhere you like!\n                        Released: 30-Oct-93\n\n   23-Oct-93   1.1      Implemented safety-procedure so when user drops\n                        carrier in chat the Chat-O-Top doesn''t get mixed up.\n                        Released at: 27-Oct-93\n\n   17-Oct-93   1.0      First release to friends.\n@ENDNODE\n\n@NODE Greetings "Greetings and thanks - © 1994/1995 KiLLraVeN/MYSTiC"\n                            - --------------------.\n                           |  Greetings & Thanks  |\n                           `-------------------- -\n\n   A *BIG* THANKS TO STEZOTHETIC (Stz) FOR CREATING THE DESiGN, THANKS MATE!\n\n   Also thanks to Quartz for stimulating me to create this version.\n\n                                      :\n                                     -O-\n                                      :\n\n   Muad''Dib       -  Finally 3 nodes kicking on 28k8!\n   \n   Quartz         -  Logos make me program :)\n   \n   Stezothetic    -  You''re in the army... nooohow...\n   \n   I-GO           -  Johnnies and Anitas zuigen!\n   \n   Wishbringer    -  Faces... (no, not faeces ;-) )\n   \n   Motive Power   -  War is a fucking tough game!\n   \n   bObO           -  We need to talk ( :) )\n   \n   Zed            -  I hope you like this tool mate.\n   \n   Undertaker     -  Your modules kick ass, nobody can beat you!\n   \n   Arcade         -  Some times are rough, some are tough...\n   \n   MYSTiC Members -  Love you all :-)\n   \n                       ... and everybody I forgot ...\n@ENDNODE\n\n@NODE Contact "How to get in touch with me - © KiLLraVeN/MYSTiC"\n                             - ------------------.\n                            |  Contacting me...  |\n                            `------------------ - \n\n       For FAST response (preferred) please contact me on Internet:\n\n                               [email removed]\n\n                    ( [email removed] -- backup )\n\n                       - - -- --- ------- --- -- - -\n\n                 I can be reached on the following boards:\n\n                       - - -- --- ------- --- -- - -\n\n                The Undiscovered       +31-2294-1442 (USR 28k8)\n                                       +31-2294-4442 (USR 28k8)\n                                       +31-2294-tRY! (USR 28k8)\n\n                Last Outpost           +31-72-201182 (USR 28k8)\n                                       +31-72-157682 (USR 28k8)\n\n         I know, you have to call The Netherlands for it, but it''s\n            the only boards I call on a frequent basis, sorry.\n\n                       - - -- --- ------- --- -- - -\n\n        You can also find me on IRC once in a while on the channels\n                   #amigascne, #amiga, #rave and #megawatt\n@ENDNODE\n\n@NODE Conversion "How to convert your old bulletin - © 1995 KiLLraVeN/MYSTiC"\n                           - ---------------------.\n                          |  Bulletin Conversion  |\n                          `--------------------- -\n\n   For  sysops  that  used  Chat-O-Meter  1.x, there is a special program\n   called  "CoM-Convert"  that allows you to convert your old bulletin to\n   the  new  data  file  that  Chat-O-Meter  2.0  uses.  If you are not a\n   previous user of Chat-O-Meter, you can skip this part.\n\n   To  convert  it,  simply  start  the  program  "CoM-Convert"  from the\n   directory  where  you  have Chat-O-Meter 2.0 installed.  The data file\n   will be created in the directory where you started "CoM-Convert".\n\n   Once  you  have  started the program, a file requester will pop up and\n   you  must select the old bulletin.  Press `OK'' and you will get to see\n   the names (plus additional info) from that bulletin.\n\n   After that, the program will exit (`Ready.'') and you can find the data\n   file  called  `Chat-O-Meter.Data''  in that same directory.  Move it if\n   you  have  to.  The new bulletin will not be created yet!  To do this,\n   you  have  to  start Chat-O-Meter 2.0 from /X (start and end a chat is\n   sufficient).\n\n   That''s it, easy a as a fiddle.\n\n   NOTE : To use this tool, you must have req-tools installed.\n\n   NOTE¹: There  is *NO* check whether the file you feed to "CoM-Convert"\n          really  is an old bulletin from 1.x.  You can even cheat if you\n          want to ;-)\n\n   NOTE²: To  all beta-testers, this conversion util takes in account any\n          old  `Chat-O-Meter.Data'' file.  That is, it doesn''t recalculate\n          a new Top-Ten (it simply converts the old one), but it does ADD\n          the  old  `Total Chat Time''  to the new time and that also goes\n          for the total number of chats.\n@ENDNODE\n','\n',char(10)),'{"STACK":"50000"}','auto-added',42545,2,0,NULL,NULL,'chatme20','scan',1780048442);
INSERT INTO door_catalog VALUES('chatmtr2','CHATMTR2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CHATMTR2.LHA','Chat-O-Meter','XIM','Chat-O-Meter',NULL,NULL,NULL,'.-\_  \/  _/   __/______\/___/-------------. | /   \/   \______  \_  \/  \_   mYSTIC!   | :/     \____/   _____/___    / /X dIVISION .',replace('  __/\  __________ _ ___  /\__              \n.-\_  \/  _/   __/______\/___/-------------.\n| /   \/   \______  \_  \/  \_   mYSTIC!   |\n:/     \____/   _____/___    / /X dIVISION .\n/_______\-\_____/--sTZ--l___/--------------:\n| KiLLraVeN/MYSTiC BRiNGS: CHAT-O-METER v2 |\n| *CREATES BULLETiN ABOUT YOUR CHAT-TiMES* :\n: o Cool Layout (StZ!) o Sysop Chat Top 10 |\n| o Hide chat & more   o User Statistics   :\n: o Conversion util to upgrade from v1.x!  |\n`------------------------------------------''\n','\n',char(10)),'Chat-O-Meter.Guide',replace('@DATABASE "Chat-O-Meter.GUiDE"\n@REMARK  .-------------------------------------------------------.\n@REMARK  | This document should be read with AmigaGuide (OS 2.x) |\n@REMARK  | or MultiView (OS 3.x) or any other guide reader. Tnx. |\n@REMARK  `-------------------------------------------------------''\n@REMARK  $VER: Chat-O-Meter 2.0.9\n@WIDTH 80\n@NODE MAIN "KiLLER Comment - MYSTiC 1994 - © 1994 KiLLraVeN/MYSTiC"\n                            Guide to Chat-O-Meter\n                 for Ami-Express 3.38+ Bulletin Board Systems\n\n                            Program version: 2.0.9\n               Compilation Date/Time: Sun Dec 25 14:00:09 1994\n\n                        © 1994/1995 by @{"KiLLraVeN/MYSTiC" link Contact}\n\n                   ... another fine MYSTiC /X production ...\n\n                       @{"       UPDATE iNFORMATiON!       " link WhatsNew}\n\n      @{" Welcome Sysop! " link WhatIs}    What is Chat-O-Meter?\n      @{" Features       " link Features}    What can it do?\n      @{" Installation   " link Install}    How to install Chat-O-Meter\n      @{" Conversion     " link Conversion}    How to convert your old 1.x bulletin to 2.x\n      @{" Example 1      " link BullExample}    Example output the bulletin of Chat-O-Meter\n      @{" Example 2      " link ExitChatExample}    Example output when you exit a chat\n      @{" History        " link History}    History of Chat-O-Meter\n      @{" Greetings      " link Greetings}    Greetings, messages and contact info\n@ENDNODE\n\n@NODE WhatIs "What is Chat-O-Meter - © KiLLraVeN/MYSTiC"\n                          - -----------------------.\n                         |  What Is Chat-O-Meter?  |\n                         `----------------------- -\n\n   Chat-O-Meter  is  a  small tool that keeps track of all your chats, in\n   particulair  the  length  of  all  your  chats  with users.  With this\n   information it is able to create a nice looking @{"bulletin" link BullExample} that displays\n   a Top Ten of all times.\n\n   Besides  that,  it  also saves the times of the chats per user. At the\n   end  of  every  chat,  the  user  gets  to  see  his  or  her personal\n   information such as the overall score and total number of chats he/she\n   was engaged in.\n\n   This  only  takes up a small amount of time and hardly any disk space.\n   The  creation of the bulletin only takes up about 1 sec (on a standard\n   machine,  it''s  even  quicker  on 020+ systems) and the file size of a\n   file that holds 400 users is about 3.5Kb.\n\n   Chat-O-Meter  also  is giftware, do with it what you want, but you may\n   not  sell  it.  Distribution on AmiNet is allowed, but distribution on\n   PD  series  is  forbidden  (I  don''t  like  people  making money of my\n   products).\n\n   Anyway,  this  version has been totally rewritten from scratch and now\n   has a cool logo made by Stezothetic, so enjoy it!\n\n                                                        @{"-KiLLraVeN/MYSTiC" link Contact}\n@ENDNODE\n\n@NODE WhatsNew "What''s New in version 2.0 - © KiLLraVeN/MYSTiC"\n                           - --------------------.\n                          |  New in version 2.0  |\n                          `-------------------- -\n\n   The  previous  version ( 1.2 ) was released over one year ago (October\n   1993)  and  to tell you the truth, the coding was lousy and it was not\n   that  sysop  friendly.   But  do  not  despair,  this version has been\n   totally rewritten (from scratch!) and is much smarter and has got some\n   nice new options.  Better forget all about the previous version :-)\n\n   It  has  to  be  said  that I would have never created this version if\n   Quartz  hadn''t  asked  for  it  AND if Stezothetic hadn''t made such an\n   awesome logo.  It seems people use my tools after all :-)\n\n   First  of  all,  the best improvement is that it is now able to detect\n   wether you started or ended a chat.  So if you were a previous user of\n   Chat-O-Meter,  the  times  of  deleting  the  old data file before you\n   started another chat are over :) Lost carriers are no problem anymore.\n\n   Another  *BIG* improvement is the @{"new layout" link BullExample}, done by Stezo (Stz).  It\n   now  has  got a really great logo and nice colours.  You''ll love it, I\n   do!  Many thanks to Stezothetic for creating the logo!\n\n   What  also  new is, is the fact that a record is kept of all chats per\n   user.   One  file is kept that contains all information about ALL your\n   chats ever (since you started to use CoM ofcoz) per user.  I will also\n   create  a  door/tool that creates a nice bulletin out of that one.  If\n   you  think  this  is  nonsense, you are able to turn it off so no data\n   file will be created.\n\n   The  previous  version also did not set the ENV:  variable of AMi-X to\n   the right value, so users that performed a ''who'' saw that the user you\n   were  chatting  with was ''using a door''.  This has been fixed.  But if\n   you  liked  that ''feature'' of Chat-O-Meter, it is still able to hide a\n   chat. Privacy above all (nope, there is no PGP function :) ).\n\n   That''s it.  I hope you''ll like it, it''s one of those nice little doors\n   that  makes  just  the  difference  between your board and your follow\n   sysops'' boards.\n@ENDNODE\n\n@NODE Features "Features of Chat-O-Meter - © KiLLraVeN/MYSTiC"\n                      - ------------------------------.\n                     |  Features of Chat-O-Meter 2.0  |\n                     `------------------------------ -\n\n   ­ Creates a bulletin wherever you want (configurable)\n\n   ­ Very nice/cool layout thanks to Stezothetic (Stz)\n\n   ­ Ability to hide a chat from other users\n\n   ­ Fast creation of data files and bulletin\n   \n   ­ Small data files (308 bytes and 2 bytes/user)\n   \n   ­ Keeps track of sysop chats, but also user chats. That is,\n     a record is kept per user with his/her personal total chat\n     time and total number of chats.\n     \n   ­ At the end of a chat, a small bulletin is shown stating the\n     latest statistics. See @{"example" link ExitChatExample}.\n     This is configurable (Quiet mode is available).\n     \n   ­ Configurable ''Show Bulletin [ Y/n ]'' when user has entered\n     the Chat-O-Meter Top Ten.\n     \n   ­ Configurable stripping of plural words ( 1 mIN instead of 1 mINS)\n\n   ­ Easy to use\n@ENDNODE\n\n@NODE ExitChatExample "Exit Chat Example - © KiLLraVeN/MYSTiC"\n\n   Every time you exit a chat, you will get to see this small bulletin.\n\n :                                                                         :\n-O-------------------------------------------------------------------------O-\n :  /X MYSTiC       Chat-O-Meter v2.0  by  KiLLraVeN/MYSTiC     /X MYSTiC  :\n ¡                                                                         .\n :  tHIS cHAT:  0:00:11 -O- oVERALL tIME: 0002:07:44 -O- cHAT #: 187       ¡\n .         yOUR oVERALL sCORE: 0000:12:46 -O- yOUR cHAT #: 132             :\n .                                                                         |\n :   sORRY dUDE, nO Chat-O-Meter tOP tIME tODAY, tRY aGAIN sOON, oKAY?!    :\n-O-------------------------------------------------------------------------O-\n :                                                                         :\n\n   However,   when   you   specify   that   you  don''t  want  a  userfile\n   (NO_USERFILE), you will get this as output:\n\n :                                                                         :\n-O-------------------------------------------------------------------------O-\n :  /X MYSTiC       Chat-O-Meter v2.0  by  KiLLraVeN/MYSTiC     /X MYSTiC  :\n ¡                                                                         .\n :  tHIS cHAT:  0:00:02 -O- oVERALL tIME: 0002:07:49 -O- cHAT #: 190       ¡\n .                                                                         |\n :   sORRY dUDE, nO Chat-O-Meter tOP tIME tODAY, tRY aGAIN sOON, oKAY?!    :\n-O-------------------------------------------------------------------------O-\n :                                                                         :\n\n@ENDNODE\n\n@NODE Install "Installation of Chat-O-Meter - © KiLLraVeN/MYSTiC"\n                      - -----------------------------.\n                     |  How to install Chat-O-Meter  |\n                     `----------------------------- -\n\n   First  of  all, you can put the executable (Chat-O-Meter) anywhere you\n   like.   The  data  files  will  be  created in that same directory.  I\n   suggest  you  put it in DOORS:Chat-O-Meter/ but hey, it''s up to you (I\n   just  hate  it  when people hard code a path in their program, haven''t\n   they heard of the PROGDIR:  assign?).\n\n   Secondly,  Chat-O-Meter  needs  to be started with an MCI command from\n   the  STARTCHAT.TXT  and  ENDCHAT.TXT  files  that can be found in your\n   BBS:NODEx/   directory.    Two   icons   have   been  supplied  called\n   `Chat_Start.info''  and  `Chat_End.info''.   I recommend you put them in\n   your  BBS:Commands/SYSCmd/  directory,  as  is  standard with commands\n   started with an MCI command.\n\n   For  those sysops who don''t know how to implement Chat-O-Meter in your\n   STARTCHAT.TXT  and  ENDCHAT.TXT,  make  sure the text files contain at\n   least the following lines:\n\n                 STARTCHAT.TXT           ENDCHAT.TXT\n                 -------------           -----------\n                 ~                       ~\n                 ~CC_CHAT_START          ~CC_CHAT_END\n\n   It  doesn''t  matter wether you''ve got a logo in those files.  Just put\n   the text in there somewhere.\n\n   Once you have copied the icons to your BBS:Commands/SYSCmd/ directory,\n   check out the following tooltypes:\n\n   Chat_Start.info\n   ---------------\n   STACK=50000          ; Keep it this high, everything is done on stack\n   There are no more tooltypes for this icon.\n   \n   Chat_End.info\n   -------------\n   CHAT_END             : This  is how Chat-O-Meter recognizes the end of\n                          a chat. Make sure it is in this icon!\n\n   BULLETIN=            : This  is where you can specify how the bulletin\n                          should be called and where it should be created\n                          (i.e. BULLETIN=BBS:Bulletins/Chat-O-Meter.TXT)\n\n   DONT_ASK             : Normally,  whenever  a user gets in the Top Ten\n                          of Chat-O-Meter,  he/she  will  be asked wether\n                          the  Chat-O-Meter  bulletin  should be shown to\n                          them. However, if you specify this tooltype, no\n                          questions  will  be  asked  and nothing will be\n                          shown.\n\n   DONT_TRUNC           : By  default  all plural ''s''-es will be removed.\n                          So  for  example:  1 hOURS  becomes 1 hOUR  and\n                          1 sECS  becomes  1 sEC.  However,  if you think\n                          that  ruins  the  bulletin (cosmetically),  you\n                          can  override  it  by specifying this tooltype.\n                          All plural ''s''-es will be left alone.\n\n   QUIET                : Whenever  a chat is ended,  a small bulletin is\n                          shown  with  the  latest  statistics about that\n                          chat.  However,  if  you do not want this to be\n                          shown,  specify this tooltype and the user will\n                          even know you are using Chat-O-Meter.  No,  not\n                          even a copyright message ;-)\n\n   NO_USERFILE          : This  version  of  Chat-O-Meter  creates a file\n                          that  contains  all  chat information about the\n                          users,   one  by  one.  So  Chat-O-Meter  knows\n                          from  every  user,  how long he/she has chatted\n                          and  how many times you have chatted with them.\n                          It  doesn''t  take  up  much space,  with around\n                          400  users  you will get a file of about 3.5KB.\n                          If  you  feel  this  is  useless or you have no\n                          need  for  this,  insert this tooltype and that\n                          file   will  not  be  created  plus  the  small\n                          bulletin at the end of a chat will be smaller.\n\n   That are all tooltypes for this moment.  When you are done setting the\n   tooltypes  you  are ready with the installation of Chat-O-Meter.  Have\n   fun and chat your head off!  :-)\n@ENDNODE\n\n@NODE BullExample "Bulletin Example Output - Design by Stezothetic!"\n\n   ASCII  never looks good in AmigaGuide or MultiView, but you''ll get the\n   idea anyway I hope.\n   \n   If  you  might wonder why there are multiple entries for one user, the\n   Chat-O-Meter  Top  Ten  is  sorted  by  the length of the chat, and it\n   doesn''t matter wether a user is present several times in it.\n   \n   This  is  not because I am to lazy to built in that check, but suppose\n   you have a chat of 5 hours with somebody.  The next time you chat with\n   him,  you  have a chat of 7 hours.  Does this mean I should just erase\n   that  5  hour  chat and mention the 7 hour chat?  I think not, that is\n   not  fair.   A  5  hour chat is just as cool as a 7 hour chat and they\n   both deserve to be mentioned.\n\n .                          _  __           /        __  _      ·          .\n-O-_____   ___.___  ___________ //\___   / ·   ______\  .        \ _      -O-\n :/  __/__/   |  ¬\/   _ ¬\____\/____/  · /   /  __ ¬\ -:---------\/-----. :\n_/   |   ¬\_  _    \_  _   \_  \/  ¬\_ / / /_/   \/   \_| >cHAT·O·mETER< | :\n\_____     /__|     /__|    /___     //_/ / \_____     /`----------------'' H\n-:---l____/---l____/---l___//\-l____/-\_\/-------l____/------ ---  --   -  ¡_\n H                       __/  \  ___  ___________  /\_________    _______  \/\n | .------------------.  \_    \/  ¬\/  __ ¬\____\/____/  __ ¬\___\____ ¬\_H\n ¡ :   ·/X mYSTIC!·   :  /     \/    \_ \____/__ \/  ¬\_  \____/__   \/  _/:\n :_`---------------- - _/       \_____/___     /__     /____     /___/    \_\n \/ -  -- --- ---------\_________/--Stz--\____/--l____/----\____/----\_____/-\n :                                                                         |\n !   o1. Muad''Dib             01 hOUR , 20 mINS aND 51 sECS  (22-dEC-94)   :\n |   o2. Muad''Dib             00 hOURS, 25 mINS aND 15 sECS  (22-dEC-94)   :\n O   o3. TyCooN/MYSTiC        00 hOURS, 03 mINS aND 04 sECS  (24-dEC-94)   ¡\n |   o4. TyCooN/MYSTiC        00 hOURS, 01 mIN  aND 51 sECS  (22-dEC-94)   O\n H   o5. KiLLRaVeN/MYSTIC     00 hOURS, 01 mIN  aND 22 sECS  (21-dEC-94)   |\n :   o6. TyCooN/MYSTiC        00 hOURS, 00 mINS aND 59 sECS  (24-dEC-94)   H\n H   o7. TyCooN/MYSTiC        00 hOURS, 00 mINS aND 51 sECS  (22-dEC-94)   :\n ¡   o8. KiLLRaVeN/MYSTIC     00 hOURS, 00 mINS aND 34 sECS  (21-dEC-94)   ·\n_:   o9. KiLLRaVeN/MYSTIC     00 hOURS, 00 mINS aND 32 sECS  (21-dEC-94)   :_\n\:   1o. KiLLRaVeN/MYSTIC     00 hOURS, 00 mINS aND 29 sECS  (22-dEC-94)   :/\n \                                                                         /\n :\        tOTAL # oF cHATS: 190         tOTAL cHAT tIME:    2:07:49      /:\n-O-\---------------------------------------------------------------------/-O-\n :  ·                                                                   ·  :\n\n           (Ghee, I chat a lot with myself don''t you think? :-) )\n\n      The design was done totally by Stezothetic, many thanks for that!\n@ENDNODE\n\n@NODE History "History of Chat-O-Meter - Amazing... :)"\n                  - -------------------------------------.\n                 |  History: Something that once was...  |\n                 `------------------------------------- -\n\n   22-Jan-95   1.0.1    Fixed CoM-Convert; it now reads the name of the\n                        user from the correct place.\n\n   04-Jan-95   1.0.0    Completed CoM-Convert and restyled it.\n\n   03-Jan-95   1.0.0    Created CoM-Convert.\n\n   25-Dec-94   2.0.9    Chat-O-Meter can also run in silent mode now.\n                        New tooltype: QUIET\n\n   25-Dec-94   2.0.8    Merry X-Mas :) Made some internal changes, removed\n                        the stack-check (smaller executable).\n\n   24-Dec-94   2.0.7    Found the bug that caused the strange resets.\n                        I adjusted the wrong variable... sigh... it\n                        should be fixed now.\n\n   24-Dec-94   2.0.6    Allocated memory for some structures by myself\n                        instead of allocating them on the stack. Hope\n                        to have fixed the strange guru''s.\n\n   24-Dec-94   2.0.5ß   Special version for Muad''Dib with DEBUG info.\n\n   24-Dec-94   2.0.5    Tried to fix a bug that caused strange resets on\n                        Muad''Dibs machine (040) and weird crashes on my\n                        own system (total freeze and I had to turn my\n                        computer off for at least one minute!).\n\n   24-Dec-94   2.0.4    Fixed a bug that caused the bulletin only the be\n                        updated in the event of a new entry in the Top\n                        Ten. The Total Chat Time was never updated.\n                        *Reported by Quartz*\n\n   23-Dec-94   2.0.3    Built in the User file, now a record is kept of\n                        every user. A new bulletin perhaps.\n                        New tooltype: NO_USERFILE\n                        \n                        Altered the output after the chat again, now also\n                        contains info about the user him/herself.\n\n   22-Dec-94   2.0.2    Altered the output a bit and made some minor\n                        internal changes that caused a smaller executable.\n\n   21-Dec-94   2.0.1    Altered the output after a chat.\n\n   21-Dec-94   2.0.0    Totally rewrote it from scratch:\n                        - END_CHAT tooltype fixes the problem with lost\n                          carriers and then starting a chat again causing\n                          the start of the chat being the end of a chat.\n                          (Never mind if you don''t get it, it''s fixed!)\n                        *Requested by Quartz*\n\n                        New layout from Stezothetic implemented.\n                        *Thanks to Stezothetic*\n\n   26-Oct-93   1.2      Output file is now sysop-configurable. Now you can\n                        have it saved anywhere you like!\n                        Released: 30-Oct-93\n\n   23-Oct-93   1.1      Implemented safety-procedure so when user drops\n                        carrier in chat the Chat-O-Top doesn''t get mixed up.\n                        Released at: 27-Oct-93\n\n   17-Oct-93   1.0      First release to friends.\n@ENDNODE\n\n@NODE Greetings "Greetings and thanks - © 1994/1995 KiLLraVeN/MYSTiC"\n                            - --------------------.\n                           |  Greetings & Thanks  |\n                           `-------------------- -\n\n   A *BIG* THANKS TO STEZOTHETIC (Stz) FOR CREATING THE DESiGN, THANKS MATE!\n\n   Also thanks to Quartz for stimulating me to create this version.\n\n                                      :\n                                     -O-\n                                      :\n\n   Muad''Dib       -  Finally 3 nodes kicking on 28k8!\n   \n   Quartz         -  Logos make me program :)\n   \n   Stezothetic    -  You''re in the army... nooohow...\n   \n   I-GO           -  Johnnies and Anitas zuigen!\n   \n   Wishbringer    -  Faces... (no, not faeces ;-) )\n   \n   Motive Power   -  War is a fucking tough game!\n   \n   bObO           -  We need to talk ( :) )\n   \n   Zed            -  I hope you like this tool mate.\n   \n   Undertaker     -  Your modules kick ass, nobody can beat you!\n   \n   Arcade         -  Some times are rough, some are tough...\n   \n   MYSTiC Members -  Love you all :-)\n   \n                       ... and everybody I forgot ...\n@ENDNODE\n\n@NODE Contact "How to get in touch with me - © KiLLraVeN/MYSTiC"\n                             - ------------------.\n                            |  Contacting me...  |\n                            `------------------ - \n\n       For FAST response (preferred) please contact me on Internet:\n\n                               [email removed]\n\n                    ( [email removed] -- backup )\n\n                       - - -- --- ------- --- -- - -\n\n                 I can be reached on the following boards:\n\n                       - - -- --- ------- --- -- - -\n\n                The Undiscovered       +31-2294-1442 (USR 28k8)\n                                       +31-2294-4442 (USR 28k8)\n                                       +31-2294-tRY! (USR 28k8)\n\n                Last Outpost           +31-72-201182 (USR 28k8)\n                                       +31-72-157682 (USR 28k8)\n\n         I know, you have to call The Netherlands for it, but it''s\n            the only boards I call on a frequent basis, sorry.\n\n                       - - -- --- ------- --- -- - -\n\n        You can also find me on IRC once in a while on the channels\n                   #amigascne, #amiga, #rave and #megawatt\n@ENDNODE\n\n@NODE Conversion "How to convert your old bulletin - © 1995 KiLLraVeN/MYSTiC"\n                           - ---------------------.\n                          |  Bulletin Conversion  |\n                          `--------------------- -\n\n   For  sysops  that  used  Chat-O-Meter  1.x, there is a special program\n   called  "CoM-Convert"  that allows you to convert your old bulletin to\n   the  new  data  file  that  Chat-O-Meter  2.0  uses.  If you are not a\n   previous user of Chat-O-Meter, you can skip this part.\n\n   To  convert  it,  simply  start  the  program  "CoM-Convert"  from the\n   directory  where  you  have Chat-O-Meter 2.0 installed.  The data file\n   will be created in the directory where you started "CoM-Convert".\n\n   Once  you  have  started the program, a file requester will pop up and\n   you  must select the old bulletin.  Press `OK'' and you will get to see\n   the names (plus additional info) from that bulletin.\n\n   After that, the program will exit (`Ready.'') and you can find the data\n   file  called  `Chat-O-Meter.Data''  in that same directory.  Move it if\n   you  have  to.  The new bulletin will not be created yet!  To do this,\n   you  have  to  start Chat-O-Meter 2.0 from /X (start and end a chat is\n   sufficient).\n\n   That''s it, easy a as a fiddle.\n\n   NOTE : To use this tool, you must have req-tools installed.\n\n   NOTE¹: There  is *NO* check whether the file you feed to "CoM-Convert"\n          really  is an old bulletin from 1.x.  You can even cheat if you\n          want to ;-)\n\n   NOTE²: To  all beta-testers, this conversion util takes in account any\n          old  `Chat-O-Meter.Data'' file.  That is, it doesn''t recalculate\n          a new Top-Ten (it simply converts the old one), but it does ADD\n          the  old  `Total Chat Time''  to the new time and that also goes\n          for the total number of chats.\n@ENDNODE\n','\n',char(10)),'{"STACK":"50000"}','auto-added',42486,2,0,NULL,NULL,'chatmtr2','scan',1780048442);
INSERT INTO door_catalog VALUES('chatsrc','CHATSRC.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CHATSRC.LHA','Chat-O-Meter','XIM','Chat-O-Meter',NULL,'KLR',NULL,'[ISDN]-÷ LEECHED FROM ZONE-ONE-BBS ÷-[ISDN]',replace('SRCChat-O-Meter Exec &amp; Source by KLR\n[ISDN]-÷ LEECHED FROM ZONE-ONE-BBS ÷-[ISDN] \n','\n',char(10)),'Chat-O-Meter.GUIDE',replace('@DATABASE "Chat-O-Meter.GUiDE"\n@REMARK  .-------------------------------------------------------.\n@REMARK  | This document should be read with AmigaGuide (OS 2.x) |\n@REMARK  | or MultiView (OS 3.x) or any other guide reader. Tnx. |\n@REMARK  `-------------------------------------------------------''\n@REMARK  $VER: Chat-O-Meter 2.2.3\n@WIDTH 80\n@NODE MAIN "Chat-O-Meter - MYSTiC ''94/''95 - © ''94/''95 KiLLraVeN/MYSTiC"\n                            Guide to Chat-O-Meter\n                 for Ami-Express 3.38+ Bulletin Board Systems\n\n                            Program version: 2.2.3\n               Compilation Date/Time: Mon Jun 26 21:50:06 1995\n\n                        © 1994/1995 by @{"KiLLraVeN/MYSTiC" link Contact}\n\n                   ... another fine MYSTiC /X production ...\n\n                       @{"       UPDATE iNFORMATiON        " link WhatsNew}\n\n      @{" Welcome Sysop! " link WhatIs}    What is Chat-O-Meter?\n      @{" Features       " link Features}    What can it do?\n      @{" Installation   " link Install}    How to install Chat-O-Meter\n      @{" Conversion     " link Conversion}    How to convert your old 1.x bulletin to 2.x\n\n      @{" Example 1      " link BullExample}    Example output the bulletin of Chat-O-Meter\n      @{" Example 2      " link ExitChatExample}    Example output when you exit a chat\n\n      @{" History        " link History}    History of Chat-O-Meter\n      @{" Greetings      " link Greetings}    Greetings, messages and contact info\n      @{" Troubles?      " link Troubles}    Trouble-shooting\n@ENDNODE\n\n@NODE WhatIs "What is Chat-O-Meter - © KiLLraVeN/MYSTiC"\n                          - -----------------------.\n                         |  What Is Chat-O-Meter?  |\n                         `----------------------- -\n\n   It  started out as a tool to keep track of the time you spent chatting\n   with  your users and to be able to make a nice looking @{"bulletin" link BullExample} out of\n   that  information.   But  things  have  changed, not only does it keep\n   track  of  the  time  the sysop spends chatting, it also registers the\n   time every user ever spent chatting with you, the sysop, in a separate\n   data  file.   So  for every user there is information available on how\n   long  s/he  chatted with you and how many times s/he chatted with you.\n\n   Needless to say that it''s also possible to create a full ANSI bulletin\n   based upon the users'' data file.\n\n   At  the  end  of  every  chat  you  will  get  to see a banner holding\n   information  about  your  latest  chat  and  accumulative  info  about\n   previous  chats.   At  your  request,  it  can  also  show  the users''\n   accumulated information.\n\n   Together  with  Chat-O-Top  you  are  able  to  create a wide range of\n   bulletins  from  the  data  gathered while you chat.  Examples of such\n   bulletins are:\n\n   · Top 10 of the longest chats ever.\n   · Top xx of the users that have chatted the longest/sportest with you.\n   · Top xx of the users that have chatted the most/least with you.\n\n   How  will  this  affect  your  chats  you say?  Well, I think you will\n   hardly  notice  a difference since the creation and/or updating of the\n   data  files  is  done  in  a  most  efficient way with as less fuzz as\n   possible.   Creation  of  the  Top Ten Longest Chats only takes upto 1\n   second.\n\n                                ** NOTICE **\n\n   Chat-O-Meter  is  giftware,  this means that you can use it as much as\n   you  like,  where  you like, dressed as you like and how you like, but\n   YOU MAY NOT SELL IT IN ANY WAY!  Permission is granted for distribtion\n   on AmiNet.\n\n                                ** NOTICE **\n\n                                   Enjoy!\n\n                                                        @{"-KiLLraVeN/MYSTiC" link Contact}\n@ENDNODE\n\n@NODE WhatsNew "What''s New - © KiLLraVeN/MYSTiC"\n                           - --------------------.\n                          |  New in version 2.2  |\n                          `-------------------- -\n\n   Again,  I  have  optimized the executable and I am sure it can be even\n   more optimized, maybe in the future (and without startup-code).\n\n   I  also rewrote the routine that would keep track of your daily chats,\n   as a result it is much faster and more reliable.  Please note that the\n   first  time  you  use  this  version  and  a  new bulletin needs to be\n   generated  by  Chat-O-Meter (because of a new record) there might be a\n   record of 0 seconds and 0 chats.  This will only last for a day.\n\n   The  total  time  that  you''ve  used  chatting with your users used to\n   displayed  in  hours,  minutes and seconds (such as:  2254:33:15), but\n   because  it  lacked clearity on the long run, I''ve altered it a bit so\n   it is now displayed in days, hours and minutes (i.e. 93d 11h 23m).\n\n   And  also  new  in  the  version  is the arrival of Chat-O-Top, a neat\n   little  thingy  that  is  able  to  create  several  very  interesting\n   bulletins, among others:\n\n   * Bulletin of total chatting times with the users\n   * Bulletin of the number of chats with the users\n   * Bulletin of the average time per chat with the users\n\n   These  bulletins  can be sorted either from high to low or vice versa.\n   It  is able to handle custom designs and has some other handy options.\n\n   Please check out the guide to Chat-O-Top for more information.\n\n                           - --------------------.\n                          |  New in version 2.1  |\n                          `-------------------- -\n\n   Added  a  routine  to  keep  track of your daily chats.  At the end of\n   every day (that is, when you start to chat for the first time on a new\n   day)  it  will  calculate  your  total chatting time and if it''s a new\n   record it will be added at the bottom of the Chat-O-Meter bulletin.\n   See supplied @{ "example." link BullExample }\n\n   Also,  at the end of every chat, you will get to see the current score\n   of today''s chatting time.\n   See supplied @{ "example." link ExitChatExample }\n\n   And due to some optimising the executable has become smaller.\n\n                           - --------------------.\n                          |  New in version 2.0  |\n                          `-------------------- -\n\n   The  previous  version ( 1.2 ) was released over one year ago (October\n   1993)  and  to tell you the truth, the coding was lousy and it was not\n   that  sysop  friendly.   But  do  not  despair,  this version has been\n   totally rewritten (from scratch!) and is much smarter and has got some\n   nice new options.  Better forget all about the previous version (1.2).\n\n   It  has  to  be  said  that I would have never created this version if\n   Quartz  hadn''t  asked  for  it  AND if Stezothetic hadn''t made such an\n   awesome logo.  It seems people use my tools after all :-)\n\n   First  of  all,  the best improvement is that it is now able to detect\n   wether you started or ended a chat.  So if you were a previous user of\n   Chat-O-Meter,  the  times  of  deleting  the  old data file before you\n   started another chat are over :) Lost carriers are no problem anymore.\n\n   Another  *BIG* improvement is the @{"new layout" link BullExample}, done by Stezo (Stz).  It\n   now  has  got a really great logo and nice colours.  You''ll love it, I\n   do!  Many thanks to Stezothetic for creating the logo!\n\n   But  that''s not all, another exciting new feature is the creation of a\n   data  file  that  contains  data about chats and times from every user\n   individually  (but  stored  in one single file).  I will also create a\n   door/tool  that creates a nice bulletin out of that one.  If you think\n   this  is nonsense, you are able to turn it off so no data file will be\n   created.\n\n   The  previous  version also did not set the ENV:  variable of AMi-X to\n   the right value, so users that performed a ''who'' saw that the user you\n   were  chatting  with was ''using a door''.  This has been fixed.  But if\n   you  liked  that ''feature'' of Chat-O-Meter, it is still able to hide a\n   chat. Privacy above all (nope, there is no PGP function :) ).\n\n   That''s it.  I hope you''ll like it, it''s one of those nice little doors\n   that  makes  just  the  difference  between your board and your follow\n   sysops'' boards.\n@ENDNODE\n\n@NODE Features "Features of Chat-O-Meter - © KiLLraVeN/MYSTiC"\n                      - ------------------------------.\n                     |  Features of Chat-O-Meter 2.0  |\n                     `------------------------------ -\n\n   · Super  Location(tm),  place  the  executable wherever you want (ENV:\n     will do just fine ;) ).\n\n   · Incredible  Creation(tm),  the  Chat-O-Meter bulletin can be created\n     anywhere  you  like it, there is no discrimination of directories at\n     all!  A first in Ami-X land!  :)\n\n   · Ultra  Cool  Layout(tm), thanks to the Great Stezothetic a fantastic\n     layout accompanies this package.\n\n   · Top Security(tm), prevent users from detecting you are chatting with\n     someone (optionable, but comes free with the package as a bonus).\n\n   · Speed  Creation(tm), you have never seen such fast creation/updating\n     of the data files and the bulletin.\n\n   · Space  Saver(tm),  miniscule  files to store the data.  Now you have\n     more room for your public domain software :)\n   \n   · Big  Brother(tm), not only YOUR chats are recorded, a record is kept\n     per  user  for  ultimate  security and reference.  Now you can proof\n     with  whom  you  have  chatted.   A  wide  variety of reports can be\n     generated about this subject (Chat-O-Top).\n\n   · Banner  Baffler(tm), comes in the famous Ultra Cool Layout(tm) style\n     and  tells  you  all  about  your  latest  chats  together  with the\n     accumulated info from the user you''ve chatted with (so you can check\n     if  you''ve  chatted too much with him/here this month, remember your\n     quota!  :) ).\n     \n   · Artificial  Intelligence,  Chat-O-Meter is able to detect wether you\n     want  to  have  yourself asked the question "Show Bulletin [Y/n]" or\n     not when a user hits the Top Ten.\n\n   · Spelling Checker, optionable removal of plural ''s''s (no, this is not\n     a typo) from words like "mINS", "hOURS" and "sECS".\n\n   · Once installed, you will never have to do any maintenance!\n@ENDNODE\n\n@NODE ExitChatExample "Exit Chat Example - © KiLLraVeN/MYSTiC"\n\n   Every time you exit a chat, you will get to see this small bulletin.\n\n                                 FULL SIZE\n :                                                                         :\n-O-------------------------------------------------------------------------O-\n :  /X MYSTiC       Chat-O-Meter v2.2  by  KiLLraVeN/MYSTiC     /X MYSTiC  :\n ¡                                                                         .\n :  tIME: 00:02:24 ^ cHAT #: 12404 ^ tODAY: 00:02:26 ^ oVERALL: 1199:04:34 ¡\n .            pRIVATE sCORE: 0000:07:42 ^ pRIVATE chAT #: 22               :\n .                                                                         |\n :   sORRY dUDE, nO Chat-O-Meter tOP tIME tODAY, tRY aGAIN sOON, oKAY?!    :\n-O-------------------------------------------------------------------------O-\n :                                                                         :\n\n                                 NO_USERFILE\n\n :                                                                         :\n-O-------------------------------------------------------------------------O-\n :  /X MYSTiC       Chat-O-Meter v2.2  by  KiLLraVeN/MYSTiC     /X MYSTiC  :\n ¡                                                                         .\n :  tIME: 00:02:24 ^ cHAT #: 12404 ^ tODAY: 00:02:26 ^ oVERALL: 1199:04:34 ¡\n .                                                                         |\n :   sORRY dUDE, nO Chat-O-Meter tOP tIME tODAY, tRY aGAIN sOON, oKAY?!    :\n-O-------------------------------------------------------------------------O-\n :                                                                         :\n\n                                NO_DAY_RECORD\n\n :                                                                         :\n-O-------------------------------------------------------------------------O-\n :  /X MYSTiC       Chat-O-Meter v2.2  by  KiLLraVeN/MYSTiC     /X MYSTiC  :\n ¡                                                                         .\n :    tHIS cHAT:  0:00:51 ^ oVERALL tIME: 1199:04:35 ^ cHAT #: 12406       ¡\n .            pRIVATE sCORE: 0000:07:42 ^ pRIVATE chAT #: 22               :\n .                                                                         |\n :   sORRY dUDE, nO Chat-O-Meter tOP tIME tODAY, tRY aGAIN sOON, oKAY?!    :\n-O-------------------------------------------------------------------------O-\n :                                                                         :\n\n                         NO_USERFILE & NO_DAY_RECORD\n\n :                                                                         :\n-O-------------------------------------------------------------------------O-\n :  /X MYSTiC       Chat-O-Meter v2.2  by  KiLLraVeN/MYSTiC     /X MYSTiC  :\n ¡                                                                         .\n :    tHIS cHAT:  0:00:51 ^ oVERALL tIME: 1199:04:35 ^ cHAT #: 12406       ¡\n .                                                                         |\n :   sORRY dUDE, nO Chat-O-Meter tOP tIME tODAY, tRY aGAIN sOON, oKAY?!    :\n-O-------------------------------------------------------------------------O-\n :                                                                         :\n\n                                   QUIET\n\n                                    :-)\n@ENDNODE\n\n@NODE Install "Installation of Chat-O-Meter - © KiLLraVeN/MYSTiC"\n                      - -----------------------------.\n                     |  How to install Chat-O-Meter  |\n                     `----------------------------- -\n\n   For the illiterate sysops among us:  smack the executable anywhere you\n   like  but  it''s  better you put it in DOORS:Chat-O-Meter/ because then\n   you  will not have to mess with those nasty icons!  Drag those vicious\n   icons  to  your  SYSCmd  directory  as  quick as you can.  After that,\n   modify  your  STARTCHAT.TXT  and  ENDCHAT.TXT  so  that  CHAT_START is\n   started  when you start a chat and END_CHAT is started when your END a\n   chat.  Now, that wasn''t too hard was it?  :-)\n\n   And now, for those of you who like to read huge guides, here comes the\n   verbose version of the above alinea.\n\n   Step 1 - Place  the  executable any place on this earth.  The supplied\n            icons  have  been setup to find it in DOORS:Chat-O-Meter, but\n            if  you  don''t  mind editing the icons, place it anywhere you\n            like.   Please  be  aware of the fact that the Chat-O-Meter''s\n            data  files  will  be created in the same directory you place\n            it.\n\n            Note  to  other  programmers:  Haven''t you guys ever heard of\n            the  PROGDIR:   assign?   Come  on, hard coded paths in doors\n            suck big time, it lacks knowledge of the system.\n\n   Step 2 - Copy   the   two   supplied   icons,   "Chat_Start.info"  and\n            "Chat_End.info" to your SYSCmd directory.\n\n   Step 3 - For  Chat-O-Meter  to do its job, you will have to alter your\n            STARTCHAT.TXT  and  ENDCHAT.TXT  file(s).  These files can be\n            found  in  your  BBS:NODEx/  directory(-ies), as you probably\n            know (well, did ya?).\n            \n            Make  sure  you  call the "Chat_Start" command when you start\n            chatting and call the "End_Chat" command when exiting a chat.\n            You  can do this with MCI commands.  Consult your Ami-Express\n            manual on how to do this (nah nah :) ).\n\n   Step 4 - We''re  done  with  the  steps. For ultimate performance, make\n            sure  to  check  out  the tooltypes described below, they can\n            really make your day.\n            \n   Step 5 - Oops, sorry.\n\n   Chat_Start.info\n   ---------------\n   STACK=10000          ; Should be enough.\n\n   There  are  no more tooltypes for this icon.  Sorry, I promise to work\n   on it :)\n   \n   Chat_End.info\n   -------------\n   CHAT_END             : This  is how Chat-O-Meter recognizes the end of\n                          a chat. Make sure it is in the icon.\n\n   BULLETIN=            : Use  this  tooltype  to set the name (including\n                          path)  of  the  bulletin that Chat-O-Meter will\n                          create.\n                          (i.e. BULLETIN=BBS:Bulletins/Chat-O-Meter.TXT)\n\n   DONT_ASK             : By  default, whenever a user enters the Top Ten\n                          of  longest  chats  s/he  will be asked if s/he\n                          wants  to see the updated Top Ten.  If you have\n                          something  against  that, you can override this\n                          question  with  this  tooltype,  it will NOT be\n                          shown.\n\n   DONT_TRUNC           : By  default  all plural ''s''-es will be removed.\n                          So  for  example:  1 hOURS  becomes 1 hOUR  and\n                          1 sECS  becomes  1 sEC.  However,  if you think\n                          that  ruins  the  bulletin (cosmetically),  you\n                          can  override  it  by specifying this tooltype.\n\n   QUIET                : If you are one of those quiet types, and do NOT\n                          wish  to see that ugly banner after every chat,\n                          quickly  use this tooltype to make sure it will\n                          never happen (god forbid!) :-).\n\n   NO_USERFILE          : As from version 2.0.3 a file is created holding\n                          all  information  about your users'' chats.  But\n                          if  you  think  that  the  8 bytes per user are\n                          taking  up  way  to much of your precious drive\n                          space,  you  can stop the creation of this file\n                          with  this  tooltype. \n\n   NO_DAY_RECORD        : And  if  it  isn''t enough already, Chat-O-Meter\n                          creates  another  file  of  20 bytes (ack) that\n                          holds info about the time you''ve spent chatting\n                          today  with  users  and  it  also harbours your\n                          tODAY  rECORD.   Again,  for  you poor guys out\n                          there  with  too  little  drive  space, you can\n                          prevent the creation of this file by using this\n                          tooltype.  Goodluck!  :)\n\n   That are all tooltypes for this moment.  When you are done setting the\n   tooltypes  you  are ready with the installation of Chat-O-Meter.  Have\n   fun and chat your head off!  :-)\n@ENDNODE\n\n@NODE BullExample "Bulletin Example Output - Design by Stezothetic!"\n\n   If  your  viewer  is  just as lousy as mine (AmigaGuide) then you will\n   agree  with  me  that the bulletin looks just plain ugly!  But believe\n   me, in Ami-Express or a good viewer/editor it looks way better.\n\n   And  yes,  it  is  possible for one user to be in the Top Ten multiple\n   times.   Why?   Well obviously I don''t check for it :) But why don''t I\n   check  for  it?   Easy,  how would you feel when you''ve just chatted 4\n   hours  with  the  sysop and it''s not put in the Top Ten because you''ve\n   chatted for 5 hours a previous time?  Not happy, let me tell you that.\n\n   What?  You would like to decide that for me?  Oh.  Well, tell it to me\n   in  my  face  and  maybe, just maybe I will fix it.  Pfwah, I''m amazed\n   that  you are even reading this, 99% of sysops don''t read guides, lazy\n   bastards.\n\n .                          _  __           /        __  _      ·          .\n-O-_____   ___.___  ___________ //\___   / ·   ______\  .        \ _      -O-\n :/  __/__/   |  ¬\/   _ ¬\____\/____/  · /   /  __ ¬\ -:---------\/-----. :\n_/   |   ¬\_  _    \_  _   \_  \/  ¬\_ / / /_/   \/   \_| >cHAT·O·mETER< | :\n\_____     /__|     /__|    /___     //_/ / \_____     /`----------------'' ¦\n-:---l____/---l____/---l___//\-l____/-\_\/-------l____/------ ---  --   -  ¡_\n ¦                       __/  \  ___  ___________  /\_________    _______  \/\n | .------------------.  \_    \/  ¬\/  __ ¬\____\/____/  __ ¬\___\____ ¬\_¦\n ¡ :   ·/X mYSTIC!·   :  /     \/    \_ \____/__ \/  ¬\_  \____/__   \/  _/:\n :_`---------------- - _/       \_____/___     /__     /____     /___/    \_\n \/ -  -- --- ---------\_________/--Stz--\____/--l____/----\____/----\_____/-\n :                                                                         |\n !   o1. Veteran              03 hOURS, 42 mINS aND 42 sECS  (06-jAN-95)   :\n |   o2. Veteran              03 hOURS, 28 mINS aND 53 sECS  (29-dEC-93)   :\n O   o3. skate BOB            03 hOURS, 08 mINS aND 03 sECS  (25-sEP-94)   ¡\n |   o4. Monte Q              03 hOURS, 07 mINS aND 03 sECS  (11-dEC-93)   O\n ¦   o5. SKATE BOB            03 hOURS, 03 mINS aND 40 sECS  (22-dEC-93)   |\n :   o6. KiLLraVeN/MYSTiC     02 hOURS, 52 mINS aND 01 sEC   (28-aPR-94)   ¦\n ¦   o7. skate BOB            02 hOURS, 50 mINS aND 55 sECS  (22-oCT-94)   :\n ¡   o8. Sir IQ               02 hOURS, 48 mINS aND 52 sECS  (28-oCT-93)   ·\n_:   o9. bULLOCK/jETSET       01 hOUR , 08 mINS aND 15 sECS  (05-jUN-95)   :_\n\:   1o. [MEGA^FORTRESS]      01 hOUR , 08 mINS aND 09 sECS  (20-jUN-95)   :/\n \                                                                         /\n :\        tOTAL # oF cHATS: 22866       tOTAL cHAT tIME: 2190:19:18      /:\n-O-\---------------------------------------------------------------------/-O-\n :  ·          dAY rECORD: 04:15:10 oN 23-jUN-95 ( 44 cHATS)            ·  :\n@ENDNODE\n\n@NODE History "History of Chat-O-Meter - Amazing... :)"\n                    - ---------------------------------.\n                   |  History: Something irreversible  |\n                   `-------------------------------- -\n\n                        Chat-O-Meter Ami-Express Door\n                             (more history below)\n\n   26-Jun-95   2.2.3    Chat-O-Meter  can  now also be used in the year\n                        2000 and up, inserted a simple check.\n\n   26-Jun-95   2.2.2    The  total  chatting  time  is now displayed in\n                        units of days, hours and minutes to enhance the\n                        clearity  of  the  time  spent chatting (entire\n                        days are wasted chatting :) ).\n\n                        Combined  some fprintf()''s so the executable is\n                        a few bytes smaller.\n\n   24-Jun-95   2.2.1    Finally  found  that  damn  bug  in  the  today\n                        routine.   How  the hell was I supposed to know\n                        that  time()  works from 1970 and not from 1978\n                        as  demanded  by Date2Amiga()?  Sigh.  But it''s\n                        fixed now, no more passing days at 18:00 hours.\n\n   22-Jun-95   2.2.0    Rewrote the ''today'' routine and replaced some\n                        of the fopen()-fread()-fwrite()''s with AmigaDOS\n                        function calls (Open, Read, Write) for speed.\n\n                        Rewrote  some  parts of the guide, my English\n                        has improved and I think it should show :)\n                        (Hi Radavi, better this way?)\n\n   07-Feb-95   2.1.1    Fixed the ''today''-routine. It could totally ruin\n                        your Chat-O-Meter.Data if things went wrong. The\n                        day-record is now stored in the .today file and\n                        no longer in the Chat-O-Meter.Data file (as it\n                        did in version 2.1.0).\n\n   06-Feb-95   2.1.0    Chat-O-Meter also keeps track of the total chat\n                        time per day. This can be turned off with:\n                        New tooltype: NO_DAY_RECORD\n\n                        Optimized /X link code. Smaller executable.\n\n   25-Dec-94   2.0.9    Chat-O-Meter can also run in silent mode now.\n                        New tooltype: QUIET\n\n   25-Dec-94   2.0.8    Merry X-Mas :) Made some internal changes, removed\n                        the stack-check (smaller executable).\n\n   24-Dec-94   2.0.7    Found the bug that caused the strange resets.\n                        I adjusted the wrong variable... sigh... it\n                        should be fixed now.\n\n   24-Dec-94   2.0.6    Allocated memory for some structures by myself\n                        instead of allocating them on the stack. Hope\n                        to have fixed the strange guru''s.\n\n   24-Dec-94   2.0.5ß   Special version for Muad''Dib with DEBUG info.\n\n   24-Dec-94   2.0.5    Tried to fix a bug that caused strange resets on\n                        Muad''Dibs machine (040) and weird crashes on my\n                        own system (total freeze and I had to turn my\n                        computer off for at least one minute!).\n\n   24-Dec-94   2.0.4    Fixed a bug that caused the bulletin only the be\n                        updated in the event of a new entry in the Top\n                        Ten. The Total Chat Time was never updated.\n                        *Reported by Quartz*\n\n   23-Dec-94   2.0.3    Built in the User file, now a record is kept of\n                        every user. A new bulletin perhaps.\n                        New tooltype: NO_USERFILE\n                        \n                        Altered the output after the chat again, now also\n                        contains info about the user him/herself.\n\n   22-Dec-94   2.0.2    Altered the output a bit and made some minor\n                        internal changes that caused a smaller executable.\n\n   21-Dec-94   2.0.1    Altered the output after a chat.\n\n   21-Dec-94   2.0.0    Totally rewrote it from scratch:\n                        - END_CHAT tooltype fixes the problem with lost\n                          carriers and then starting a chat again causing\n                          the start of the chat being the end of a chat.\n                          (Never mind if you don''t get it, it''s fixed!)\n                        *Requested by Quartz*\n\n                        New layout from Stezothetic implemented.\n                        *Thanks to Stezothetic*\n\n   26-Oct-93   1.2      Output file is now sysop-configurable. Now you can\n                        have it saved anywhere you like!\n                        Released: 30-Oct-93\n\n   23-Oct-93   1.1      Implemented safety-procedure so when user drops\n                        carrier in chat the Chat-O-Top doesn''t get mixed up.\n                        Released at: 27-Oct-93\n\n   17-Oct-93   1.0      First release to friends.\n\n                          Chat-O-Meter Convert Util\n\n   22-Jan-95   1.0.1    Fixed CoM-Convert; it now reads the name of the\n                        user from the correct place.\n\n   04-Jan-95   1.0.0    Completed CoM-Convert and restyled it.\n\n   03-Jan-95   1.0.0    Created CoM-Convert.\n@ENDNODE\n\n@NODE Greetings "Greetings and thanks - © 1994/1995 KiLLraVeN/MYSTiC"\n                            - --------------------.\n                           |  Greetings & Thanks  |\n                           `-------------------- -\n\n   A *BIG* THANKS TO STEZOTHETIC (Stz) FOR CREATING THE DESiGN, THANKS MATE!\n\n                                      :\n                                     -O-\n                                      :\n\n   Muad''Dib       -  Gheez,  using  custom  code to use linked lists is a\n                     bit unneccessary, but it sure shows that your skills\n                     are  improving.   Before  you know it you can finish\n                     KiLLER all by yourself :)\n\n   Wishbringer    -  Congratulations with passing your examinations.  Now\n                     it''s  time  for  the  REAL work at school or are you\n                     going  to  do  labour,  maybe working as a gardener?\n                     :-)\n   \n   Motive Power   -  Lost  your data line?  Last your data line?  How can\n                     you  be  a  good MYSTiC board then?  Naughty boy for\n                     not  telling me, I had to find out via xxxxx, afraid\n                     I  would kick you?  Well, you are right (not)!  It''s\n                     the  friendship that counts (together with megabytes\n                     :) ).\n   \n   I-GO           -  He  man,  let''s  puke  all  over this place!  Puking\n                     rules!   Let''s  inhale the odor and maybe we can get\n                     high  on  that,  woooow, sounds like the trip of our\n                     life times (and the last...  barf!).\n         \n   Exotic         -  My dear, dear friend. How is life treating you?\n   \n   Zed            -  Let  me  get this straight, you''ve made X-Caller for\n                     both XLK and AMi-X?  Why?\n   \n   Nocturn        -  Earth  calling  Nocturn,  Earth calling Nocturn.  If\n                     you  are  reading  this,  please  contact me.  Since\n                     you''ve  moved,  you seemed to have vanished from the\n                     Earth (did the gays get you in Philly?  :) ).\n                     \n   Empire         -  Why  work  for  the  money?   We  work for pleasure,\n                     pleasure  is  what  we  want out of life, so we work\n                     with  pleasure  (not).   Here''s  a  piece of advice:\n                     work to live, don''t live to work.\n   \n   bObO/MST       -  Ofcourse  you  send me 1000+ messages, they all just\n                     happened  to  be  re-routed to NIL:  ?  Oh well, I''m\n                     just  happy  your e-mail address works again.  Where\n                     the hell is File-ID 2.0 with colour support? :)\n   \n   Stezothetic    -  You''re  in the army now, wo oh oh, he''s in the army,\n                     nohow...  snief!\n   \n   UFOk           -  You  are the fastest trader I''ve ever seen!  And you\n                     don''t  trade  little  as well, almost 1 gigabyte per\n                     month.  Wouzers...  you rule for sure!\n\n   Radavi         -  You  don''t  give up easily, do you now?  You have to\n                     find EVERY tiny error I''ve made in my guide(s).  But\n                     now  I  am  convinced  that this file is free of any\n                     mistakes,  I''ve even corrected some that you did not\n                     find  (moeha!).   But  it''s all for the best, even a\n                     perfectionist  like  myself can make mistakes (did I\n                     tell you about my finest quality?  Modesty :) ).\n\n   QuartZ         -  You  thought  I  had  forgotten all about you didn''t\n                     you?   You  are thinking "why am I mentioned last in\n                     the  list?"  Getting paranoid?  No friends?  :) Nah,\n                     just teasing you my friend.\n   \n                      and to all my friends on Internet!\n@ENDNODE\n\n@NODE Contact "How to get in touch with me - © KiLLraVeN/MYSTiC"\n                             - ------------------.\n                            |  Contacting me...  |\n                            `------------------ - \n\n       For FAST response (preferred) please contact me on Internet:\n\n                               [email removed]\n\n                       - - -- --- ------- --- -- - -\n\n                 I can be reached on the following boards:\n\n                       - - -- --- ------- --- -- - -\n\n                The Undiscovered       +31-2294-1442 (USR 33k6)\n                                       +31-2294-4442 (USR 33k6)\n                                       +31-2294-tRY! (USR 33k6)\n\n                Last Outpost           +31-72-201182 (USR 33k6)\n                                       +31-72-157682 (USR 33k6)\n\n         I know, you have to call The Netherlands for it, but it''s\n            the only boards I call on a frequent basis, sorry.\n\n                       - - -- --- ------- --- -- - -\n\n        You can also find me on IRC once in a while on the channels\n                   #amigascne, #amiga, #rave and #megawatt\n@ENDNODE\n\n@NODE Conversion "How to convert your old bulletin - © 1995 KiLLraVeN/MYSTiC"\n                           - ---------------------.\n                          |  Bulletin Conversion  |\n                          `--------------------- -\n\n   For  sysops  that  used  Chat-O-Meter  1.x, there is a special program\n   called  "CoM-Convert"  that allows you to convert your old bulletin to\n   the  new  data  file  that  Chat-O-Meter  2.0  uses.  If you are not a\n   previous user of Chat-O-Meter, you can skip this part.\n\n   To  convert  it,  simply  start  the  program  "CoM-Convert"  from the\n   directory  where  you  have Chat-O-Meter 2.0 installed.  The data file\n   will be created in the directory where you started "CoM-Convert".\n\n   Once  you  have  started the program, a file requester will pop up and\n   you  must select the old bulletin.  Press `OK'' and you will get to see\n   the names (plus additional info) from that bulletin.\n\n   After that, the program will exit (`Ready.'') and you can find the data\n   file  called  `Chat-O-Meter.Data''  in that same directory.  Move it if\n   you  have  to.  The new bulletin will not be created yet!  To do this,\n   you  have  to  start Chat-O-Meter 2.0 from /X (start and end a chat is\n   sufficient).\n\n   That''s it, easy a as a fiddle.\n\n   NOTE : To use this tool, you must have req-tools installed.\n\n   NOTE¹: There  is *NO* check whether the file you feed to "CoM-Convert"\n          really  is an old bulletin from 1.x.  You can even cheat if you\n          want to ;-)\n\n   NOTE²: To  all beta-testers, this conversion util takes in account any\n          old  `Chat-O-Meter.Data'' file.  That is, it doesn''t recalculate\n          a new Top-Ten (it simply converts the old one), but it does ADD\n          the  old  `Total Chat Time''  to the new time and that also goes\n          for the total number of chats.\n@ENDNODE\n\n@NODE Troubles "Troubles with Chat-O-Meter? - © 1995 by KiLLraVeN/MYSTiC"\n                            - ------------------.\n                           |  Trouble-Shooting  |\n                           `------------------ -\n\n   Q: Chat-O-Meter does not generate the bulletin, nor does it show\n      it on screen. What should I do?\n\n   A: Remove the "CHAT_END" tooltype from your CHAT_END icon.\n\n                               - -- ---- -- -\n\n   Q: Chat-O-Meter says it has got a daily record of 0 seconds? How\n      is that possible?\n\n   A: This can only happen the first day when a new record from a user\n      has been set, but there has not been a daily record yet. This\n      will be fixed by tomorrow, be patient :)\n\n                               - -- ---- -- -\n\n   Q: Why doesn''t Chat-O-Top show the total number of chats?\n   \n   A: Because there was no room, but if you contact me I might\n      consider doing a new version.\n@ENDNODE\n','\n',char(10)),'{"STACK":"10000"}','auto-added',117323,5,0,NULL,NULL,'mst_cm20','scan',1780048442);
INSERT INTO door_catalog VALUES('chcker12','CHCKER12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CHCKER12.LHA',NULL,'XIM','File Checking SCRIPT for ALL BBS''s.',NULL,NULL,NULL,'[ cOOl cORONa BBS ]-[20:35:52]-[24 Jan 1995]',replace('File Checking SCRIPT for ALL BBS''s.\n[ cOOl cORONa BBS ]-[20:35:52]-[24 Jan 1995]\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 19:07:29  ON NODE: 1\n','\r',char(13)),'\n',char(10)),NULL,NULL,15402,1,0,NULL,NULL,NULL,'scan',1780048442);
INSERT INTO door_catalog VALUES('check','CHECK.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CHECK.LHA','LZX','REXX','____________________________________________',NULL,NULL,NULL,'\      _______  \   _______)---------------. :\__/  \|  __/  /___   \|  \ SieGeL/tRSi oF: ¦  /    \  \    \   \   \   \ /X-iNNOVATiON¦',replace('____________________________________________\n\      _______  \   _______)---------------.\n:\__/  \|  __/  /___   \|  \ SieGeL/tRSi oF:\n¦  /    \  \    \   \   \   \ /X-iNNOVATiON¦\n| /______\__\____\______/____\  PRESENTS   |\n)--mRV-------------------------------------(\n|mULTI-cHECK V1.2 - ADDER/sTRIPPER/cHECKER!|\n|                                          |\n|  sUPPORTS LZX, LHA & ZIP, aUTODETECT oF  |\n|  BBS-sYSTEM uSED (FAME aND /X) aND mANY  |\n|      oTHER fEATURES - cHECK iT oUT !     |\n`------------------------------------------''\n[ISDN]-÷ LEECHED FROM ZONE-ONE-BBS ÷-[ISDN] \n','\n',char(10)),'mULTI-cHECK.guide',replace('@database mULTI-cHECK\n@master EWORK:mULTI-cHECK/mULTI-cHECK_eng.guide\n@$VER: mULTI-cHECK.guide 1.0 (02-03-96)\n@author "SieGeL/tRSi"\n@(c) "Copyright © 1996 (tRSi/X-iNNOVATiON)"\n@wordwrap\n@index HeddleyAutoIndex\n@remark Created with Heddley v1.1 (c) Edd Dumbill 1994\n@remark Heddley Bugs Fixed with FixHeddley 1.2 (c) 1995 by David Zvekic\n\n@node "Main" "mULTI-cHECK - Archive-Checker for FAME & Amiex Systems"\n\n    @{b}:::.@{ub}       ________  _________ ____\n    @{b}::::@{ub}      |  -___ /_(____-----(____)\n    @{b}`::: ...@{ub}  `---'' `---^---------^----^\n     @{b}:::::::''@{ub}                \n    @{b}.::::''      ..@{ub}       .@{fg fill}ami express@{fg text}.       .@{b}presents in 1996@{ub}.\n   @{b}::::::.     `:::::...@{ub}                \n    @{b}`'' :::        ```:::::..@{ub}  .@{fg fill}fame@{fg text}.          .@{b}mULTI-cHECK  v1.2@{ub}.\n       @{b}`:::            ``::::@{ub}\n        @{b}`:::          ..::::''@{ub}    .@{fg fill}tempest@{fg text}.     .@{b}for /X & FAME BBS@{ub}.\n         @{b}`:::.    ..:::::''''@{ub} __ _ _ _ _ ___ _ _ ___ ___  _ ___ _ _\n          @{b}`:::::::::::''''@{ub}   (__) ` | ` | - | / | - (_ _)(_) - | ` |\n            @{b}``::::''''@{ub}       ^--^-''-^-''-^---^---^-''-''`-'' ^-^---^-''-''\n\n                          wRITTEN bY SieGeL/tRSi\n\n                         @{"COPYRIGHT & DISTRIBUTION" link "COPYRIGHT" 0}\n                         @{"INTRODUCTION & FEATURES " link "INTRODUCTION" 0}\n                         @{"INSTALLATION TO YOUR BBS" link "INSTALLATION" 0}\n                         @{"  USAGE AND PARAMETERS  " link "USAGE" 0} \n                         @{"  CREDITS & GREETINGS!  " link "CREDITZ" 0} \n\n         aNOTHER pRODUCT oF tHE "REAL" (tRSi/X-iNNOVATiON) tEAM !\n@endnode\n\n@node "COPYRIGHT" "Copyright Informations for mULTI-cHECK"\n@{b}DISTRIBUTION:@{ub}\n\n Following notice applies to product called "mULTI-cHECK" and everything \n in its original distribution archive.\n\n * Program is published by SieGeL/tRSi under concept of @{"RegisterWare" link "REGISTER" 0}.\n   No warranties are given. I take no responsibility of any possible\n   harm this product could do to your amiga system (not that it would but..).\n\n * You may NOT sell this product without permission from me.\n\n * Program must not be altered in any way.\n\n * Package must always be kept intact when spreading.\n\n * It is OK to include this on CD-ROM & disk collections and distribute\n   it through aminet and other such ftp''s and file nets.\n\n Above mentioned rules apply to mULTI-cHECK and other texts/libraries\n within the original package versions 1.2 and newer unless otherwise stated.\n@endnode\n\n@node "INTRODUCTION" "Some informations about mULTI-cHECK"\n          @{b}INTRODUCTION TO mULTI-cHECK OR WHY ANOTHER FILECHECKER ?@{ub}\n\n Well, the most important thing why I wrote this Tool is the fact that\n currently no other filechecker supports the @{"FAME-System" link "FAME" 0} (which I''m running!)\n and therefor the adding of uploader etc. was not possible...so I decided to\n write my own one, but not only for @{fg fill}LZX@{fg text} (which was the first archiver I''ve\n supported)...I don''t like many thousands of checkertools and therefor this\n mULTI-cHECKER is able to @{fg shine}check/add/strip@{fg text} from @{fg shine}LZX@{fg text}, @{fg shine}LHA@{fg text} and @{fg shine}ZIP@{fg text} archives...\n\n @{u}Other nice functions are:@{uu}\n\n - Supports @{b}LZX@{ub}, @{b}LHA@{ub} & @{b}ZIP@{ub} Archives for @{b}testing/adding/stripping@{ub}...\n\n - Full @{b}argument-driven@{ub}, no external configfile needed!\n\n - Supports @{b}FAME@{ub} & @{b}Amiex@{ub} systems (but not needed to let it work)\n\n - Is able to add @{b}Uploadername@{ub}, -@{b}location@{ub}, @{b}node@{ub}, @{b}date@{ub} & @{b}time@{ub} of upload to\n   the advert being added....\n\n - Supports @{b}stripping via external Textfile@{ub}\n\n - Very small and fast...:)\n\n If you now interested in this checker, simply take a look to the chapter\n @{"Installation" link "INSTALLATION" 0} for further informations...\n@endnode\n\n@node "INSTALLATION" "Installation to your BBS-System of mULTI-cHECK"\n                       @{b}INSTALLATION OF mULTI-cHECK@{ub}\n\n Best way to copy all neccessary files is to use the Installerscript supplied\n with the release archive...if you want to copy it by hand, follow these few\n steps:\n\n @{b}1.@{ub} Copy @{fg shine}mULTI-cHECK@{fg text} to your @{fg fill}c:@{fg text} directory or to any other directory of your\n    choice.\n\n @{b}2.@{ub} Copy the @{fg shine}documentation@{fg text} to your docs-directory or any other directory...\n\n @{b}3.@{ub} Copy the supplied sample files @{"ADVERT.TXT" link "SAMPLE_ADVERT" 0} and @{"STRIPFILE.TXT" link "SAMPLE_STRIPFILE" 0} to a\n    directory of your choice.\n\n Now you have to edit the files @{b}ADVERT.TXT@{ub} and @{b}STRIPFILE.TXT@{ub} to your needs.\n ADVERT.TXT could have some special symbols which are described @{"HERE" link "SAMPLE_ADVERT" 0}. The\n STRIPFILE.TXT should contain all filenames (!), you wish to kill from the\n archive. Please note that it''s on you to write only legal characters into\n this file, as mULTI-cHECK performs @{b}*NO*@{ub} checkings on these names !!! So\n make sure that you don''t use wildcards or other critical filenames inside\n this @{"stripfile" link "SAMPLE_STRIPFILE" 0}, otherwise it could happen that you gain only empty archives\n or other strange things...you''ve been warned!\n\n At least, you have to built in the checker to your BBS-System.\n\n\n                   @{b}--------- BBS-INSTALLATION ---------@{ub}\n\n\n@{u}AMIEX-SYSOPS:@{uu}\n\n Create three icons inside your BBS:FCHECK/ directory called\n\n                            @{fg shine}LZX.INFO@{fg text}\n                            @{fg shine}LHA.INFO@{fg text}\n                            @{fg shine}ZIP.INFO@{fg text}\n\n and edit the Tooltypes like shown below:\n\n  CHECKER = C:mULTI-cHECK\n  OPTIONS = @{"(CLICK HERE FOR OPTIONS)" link "USAGE" 0}\n    STACK = SAME\n PRIORITY = 1\n  ERROR.1 = Archive Corrupt!\n\n Repeat this steps for all three icons (or only the archive-types you want\n to use mULTI-cHECK for)...the Options are described in the @{"Parameters" link "USAGE" 0}-\n chapter, see there for further informations !\n\n Now you are ready with the installation.\n\n\n@{u}FAME-SYSOPS@{uu}:\n\n Start the System-Editor and go to FileCheckers. Now edit the @{b}LHA@{ub} & @{b}ZIP@{ub}\n configurations like shown below:\n\n  CHECKER PATH = C:mULTI-cHECK\n    STACK SIZE = 4096\n      PRIORITY = 1\n       OPTIONS = @{"(CLICK HERE FOR OPTIONS)" link "USAGE" 0}\n       ERROR 1 = Archive Corrupt!\n\n For @{b}LZX@{ub}, you have the create a new configuration with the @{fg shine}NEW@{fg text} button, enter\n LZX as extension, fill in the fields and save this configuration.\n\n Of course you have to switch the checker(s) @{b}ON@{ub} to let it work :)\n\n That''s all for installing it to @{"FAME" link "FAME" 0}, now you are ready to use it. See\n Chapter @{"Parameters" link "USAGE" 0} for further informations about the Options used by\n mULTI-cHECK.\n@endnode\n\n@node "USAGE" "How to use it and list of Parameters"\n                   @{b}LIST OF PARAMETERS USED BY mULTI-cHECK:@{ub}\n\n As mULTI-cHECK is fully commandline-driven, various parameters exists to\n control mULTI-cHECK. The command-template for mULTI-cHECK is:\n\n      @{fg shine}ADVERT/K,BBS-PATH/K,STRIPFILE/K,PACKER/K/A,TYPE/K/A,FILENAME/A@{fg text}\n\n Click @{"HERE" link "USAGE_EXAMPLES" 0} for some examples how to start mULTI-cHECK.\n\n @{u}Explanation of Parameters:@{uu}\n\n mULTI-cHECK uses standard OS 2.0++ Parms and their keywords, so please take\n a look to your AmigaDOS-Manual for further informations about the templates\n of programs etc.\n\n    @{fg shine}@{bg shadow}ADVERT/K@{fg text}@{bg back}  -  Specify here the Filename to the advert which should be\n                 added to the archive...click @{"HERE" link "SAMPLE_ADVERT" 0} for additional infos\n                 about the format of adverts used by mULTI-cHECK.\n\n                 @{b}@{fg fill}I.E.:@{ub}@{fg text} @{fg fill}ADVERT=S:MYADVERT.TXT@{fg text}\n\n                 will add @{fg fill}S:MYADVERT.TXT@{fg text} after parsing it for any special\n                 commands to the archive given as FileName.\n\n                 This Parameter is optional!\n\n  @{fg shine}@{bg shadow}BBS-PATH/K@{fg text}@{bg back}  -  If you are using mULTI-cHECK with a BBS, enter here the\n                 main path to your BBS System, i.e. @{fg fill}BBS-PATH=BBS:@{fg text} or use\n                 @{fg fill}BBS-PATH=FAME:@{fg text} . Please notice that mULTI-cHECK is able to\n                 detect itself which System you are running...if you don''t\n                 specify this Option, but using the Uploader-Name etc.\n                 features inside an advert, mULTI-cHECK will write\n                 @{b}"-+- The SysOp -+- "@{ub} and @{b}"- Local Upload -"@{ub} for the name &\n                 location fields, otherwise all needed informations where\n                 extracted from the online''s user.datas and written to your\n                 advert.\n\n                 This Parameter is optional!\n\n @{fg shine}@{bg shadow}STRIPFILE/K@{fg text}@{bg back}  -  Here you have to enter the path to a ascii-file containing\n                 all filenames you want to strip off the archive, i.e. you\n                 have a file in @{fg fill}S:@{fg text} called @{fg fill}strips@{fg text} containing:\n\n                                @{i}display.me@{ui}\n                                @{i}fuck_it.txt@{ui}\n                                @{i}werbung.txt@{ui}\n\n                 then you enter @{fg fill}STRIPFILE=S:STRIPS@{fg text} and all filenames listed\n                 inside this file where deleted from the archive. Look to\n                 the Chapter @{"Example-Stripfile" link "SAMPLE_STRIPFILE" 0} for further informations.\n\n                 @{u}NOTE:@{uu} If you are stripping from a @{fg shine}@{bg fill}ZIP-Archive@{fg text}@{bg back}, please don''t\n                       wonder about errormessages comming from ZIP, these\n                       errors are normal, as ZIP prints out all filenames,\n                       which couldn''t be found inside the archive to delete\n                       them...dunno know why this behavour exists, I can''t\n                       suppress this warnings and therefor you have to live\n                       with this :(\n\n                 This Parameter is optional!\n\n  @{fg shine}@{bg shadow}PACKER/K/A@{fg text}@{bg back}  -  Here you must enter the path to the checker you want to use.\n                 I''ve tested it with @{b}LHA V1.50@{ub}, @{b}LZX V1.20@{ub} and @{b}Zip V2.0.1@{ub} but\n                 as I only uses standard commands and therefor there should\n                 be no problems when using different versions. To specify\n                 the packer for @{fg fill}LZX@{fg text}, you could write for example:\n\n                                     @{fg fill}PACKER=C:LZX@{fg text}\n\n                 This Parameter is absolutly needed, without it mULTI-cHECK\n                 won''t work!\n\n    @{fg shine}@{bg shadow}TYPE/K/A@{fg text}@{bg back}   - Enter here the type of packer which is used...currently\n                 there exists 3 types:\n\n                                   @{fg shine}LHA LZX ZIP@{fg text}\n\n                 If you want to use @{fg fill}LHA@{fg text}, simply enter @{fg fill}TYPE=LHA@{fg text} and\n                 mULTI-cHECK uses now the @{fg fill}LHA@{fg text} routines for stripping/testing\n                 and adding...\n\n                 This Parameter is absolutly needed, without it mULTI-cHECK\n                 won''t work!\n\n  @{fg shine}@{bg shadow}FILENAME/A@{fg text}@{bg back}   - Here you specify the archive to test/add/strip. If you use\n                 mULTI-cHECK as Filechecker for your BBS, this Parameter will\n                 be filled out from the BBS, and therefor no Keyword is\n                 required to specify it (see @{"examples" link "USAGE_EXAMPLES" 0} below).\n\n                 This Parameter is absolutly needed, without it mULTI-cHECK\n                 won''t work!\n\n                @{"Click here for some examples of mULTI-cHECK" link "USAGE_EXAMPLES" 0}\n@endnode\n\n@node "USAGE_EXAMPLES" "Some examples how to use mULTI-cHECK."\n                  @{b}SOME EXAMPLES HOW TO USE mULTI-cHECK:@{ub}\n\n All examples listed here assuming that you have an advertfile called ADVERT\n found in S: and a stripfile called STRIP found in S:, too.\n\n\n@{b}1)@{ub} @{u}Simplest usage:@{uu}\n\n  mULTI-cHECK PACKER=C:LHA TYPE=LHA RAM:MYARCHIVE.LHA\n\n Will only check archive @{fg fill}RAM:MYARCHIVE.LHA@{fg text} in @{fg fill}LHA@{fg text} mode and uses @{fg fill}C:LHA@{fg text}.\n\n\n@{b}2)@{ub} @{u}With adding of an advert:@{uu}\n\n  mULTI-cHECK ADVERT=S:ADVERT PACKER=C:LZX TYPE=LZX RAM:MYARCHIVE.LZX\n\n Will check archive @{fg fill}RAM:MYARCHIVE.LZX@{fg text} in @{fg fill}LZX@{fg text} mode using @{fg fill}C:LZX@{fg text} and after the\n testing will add the @{fg fill}S:ADVERT@{fg text} file to the archive.\n\n\n@{b}3)@{ub} @{u}Stripping from an archive:@{uu}\n\n mULTI-cHECK STRIPFILE=S:STRIP PACKER=C:ZIP TYPE=ZIP RAM:MSDOS.ZIP\n\n Will check archive @{fg fill}RAM:MSDOS.ZIP@{fg text} in @{fg fill}ZIP@{fg text} mode using @{fg fill}C:ZIP@{fg text} and after testing,\n all filenames listed in @{fg fill}S:STRIP@{fg text} will be stripped off the archive.\n\n\n@{b}4)@{ub} @{u}Now an example with testing/adding/stripping for a BBS-System:@{uu}\n\n mULTI-cHECK ADVERT=S:ADVERT STRIPFILE=S:STRIP BBS-PATH=FAME: PACKER=C:ZIP\n             TYPE=ZIP RAM:MSDOS.ZIP\n\n It''s clear that you have to enter this in only one line, but the space here\n doesn''t allow it to write this example into one line. This example will\n first test @{fg fill}RAM:MSDOS.ZIP@{fg text} in @{fg fill}ZIP@{fg text} mode using @{fg fill}c:ZIP@{fg text}, then strips off all files\n contained in @{fg fill}S:STRIP@{fg text} from the archive and finally adds the advert @{fg fill}S:ADVERT@{fg text}\n to the archive, but filling out the advert first with uploader''s name, \n location etc. extracting this informations out of the BBS-Path @{fg fill}FAME:@{fg text} .\n\n I think that should be enough examples on how to use it for your needs.\n\n For an overview about the @{"StripFile" link "SAMPLE_STRIPFILE" 0} or the @{"Advert" link "SAMPLE_ADVERT" 0} format used by mULTI-cHECK\n please take a look to the according chapters.\n@endnode\n\n@node "SAMPLE_ADVERT" "An example for an Advert used by mULTI-cHECK"\n                 @{b}SPECIAL COMMANDS USED FOR THE ADVERT:@{ub}\n\n As mULTI-cHECK is able to add @{i}Uploader Name@{ui} and @{i}Location@{ui}, @{i}Node-Nr@{ui}, @{i}Date@{ui} and\n @{i}Time@{ui} of the Upload into your advert, some special commands exists to let\n mULTI-cHECK add this items. Here''s a list of a special commands, you have\n to enter them exactly the same way they are written here:\n\n@{b}1) The Uploadername:@{ub} @{fg shine}@{bg fill}-U-S-E-R-H-A-N-D-L-E-@{fg text}@{bg back}\n\n Will be replaced by the name of the Uploader. Max length is 21 chars,\n shorter names are filled with spaces, longer names are cutted. If no\n uploadername could be found, the string "@{fg fill}-+- THE SYSOP -+-@{fg text}" will be added.\n\n@{b}2) The Uploaderlocation:@{ub} @{fg shine}@{bg fill}-U-S-E-R-L-O-C-A-T-I-O-N-@{fg text}@{bg back}\n\n Will be replaced by the Location of the Uploader. Max. length is 25 chars,\n shorter names are filled with spaces, longer names are cutted. If no\n uploaderlocation could be found, the string "@{fg fill}-+- LOCAL UPLOAD -+-@{fg text}" will be\n added.\n\n@{b}3) The Nodenumber:@{ub} @{fg shine}@{bg fill}¹¹@{fg text}@{bg back}\n\n Will be replaced by the Nodenumber from where the upload was done. Max.\n length is 2 chars, the nodenumber will be right-justified written to your\n advert. If no nodenumber could be found, the string "@{fg fill}--@{fg text}" will be written\n as Nodenumber.\n\n@{b}4) Date of check:@{ub} @{fg shine}@{bg fill}@@-@@-@@@{fg text}@{bg back}\n\n Will be replaced by the date the archive was tested. The date is in the\n USA format (@{fg fill}MM-DD-YY@{fg text}) and is always been added.\n\n@{b}5) Time of check:@{ub} @{fg shine}@{bg fill}##:##:##@{fg text}@{bg back}\n\n Will be replaced by the time the archive was tested. The time is in the\n format @{fg fill}HH:MM:SS@{fg text} and is always been added.\n\n\n\n                          @{b}SAMPLE FOR AN ADVERT:@{ub}\n\n@{fg shine}--- CUT HERE ---@{fg text}\n\n        _____ __ __ _____ __ _____.--.__ ________ ___________ __\n __ _ _/  ._ \\_ |  \\_    \\__)     \\_ | _/        \\_ ___/     \\_ l_  _\n   \\ \\\\_  |/  / |  _/ |  _/\\_  l___/ | \\_  |  |  _/ _/\\_  |  _/ _/_ /_\n       |   __/  |  |  |  |  l__   |     |  |  |  |  |  |  |  |  |  |  ||\n       |  |  |  |  |  |  |  |  |  |  |  |  |  |  |  l  |  |  |  l  |  |:\n       l__|  l_____l__|  l__l__   l__|  l__|__|  l__   l__|  l__   |  ||\n          ÷2F÷        `--''     `--''  `--''     `--''  `--''  `--''  `--''\n\n           · (tRSi/X-iNNOVATiON) WHQ & bETA sITE · cONTRA! gHQ ·\n\n         · eTHIC dIST sITE · mATRIX oRDER sITE · fAME sUPPORT BBS ·\n\n                              __ _____ _____\n     A4ooo/o4o aT 4oMHZ      (__)     \\_    |\n                             | \\_  |  _/ l__|           sYSTEM-cHIEFS:\n  14mB rAM/1.6 GB HD-sPACE   |  |  |  |  |__\n                             |  |  |  |  l  |  _     SieGeL/tRSi & aRGON\n       USR v.34 28.8k        l__l__|  l__   | (_)\n                                   `--''  `--''\n\n          ! sUPPORTING pD and sHAREWARE oNLY oN aMIGA aND IBM-PC !\n\n                  cALL #0: +49(0)30 694 84 70 (v.34)\n                       #1: +49(0)30 694 85 70 (v.34)\n\n             UPLOAD DATE: @@-@@-@@  TIME: ##:##:##  ON NODE: ¹¹\n\n    UPLOADER: -U-S-E-R-H-A-N-D-L-E-  LOCATION: -U-S-E-R-L-O-C-A-T-I-O-N-\n\n@{fg shine}--- CUT HERE ---@{fg text}\n@endnode\n\n@node "SAMPLE_STRIPFILE" "An example for a Stripfile used by mULTI-cHECK"\n             @{b}EXPLANATION FOR THE STRIPFILE USED BY mULTI-cHECK:@{ub}\n\n If you want to let mULTI-cHECK automatically remove unused files from the\n archives being tested, you have to create an ASCII-file containing all file-\n names you wish to remove from the archive. mULTI-cHECK takes this file with\n the Parameter @{"STRIPFILE=<PATH_TO_FILE>" link "USAGE" 0} and removes all files from the\n archive wich matches the filenames found inside the stripfile. Please use\n this option with care, as mULTI-cHECK performs @{b}NO@{ub} checkings about the given\n filenames (i.e. Patterns, spaces between names etc.) for the use of speed.\n It''s on you to remove only @{i}LEGAL@{ui} filenames which doesn''t create problems...\n I''ll give @{b}NO@{ub} warranty about any loss data which occures while removing files\n from an archive with @{i}ILLEGAL@{ui} filenames!\n\n\n                       @{b}EXAMPLE FOR THE STRIPFILE:@{ub}\n\n This is an example how a stripfile may look like. Snap this out and save it\n under a filename of your choice. After this, enter STRIPFILE=<YOUR_NAME> as\n parameter for mULTI-cHECK, and all files where removed then.\n\n@{fg shine}--- CUT HERE ---@{fg text}\n\n display.me \n fucker.txt \n "the fastest" \n READ.ME \n "BLA BLA BLA!"\n\n@{fg shine}--- CUT HERE ---@{fg text}\n\n Don''t ask me to built in a learn function for new adverts, I won''t built-in\n such unsafe things, if you want to remove files, @{b}YOU@{ub} have to enter the\n according filenames...I don''t trust doors/checkers, which are able to \n "learn", as this produces at most cases empty archives....:|\n@endnode\n\n@node "CREDITZ" "Credits and the wellknown Greetings"\n                               @{b}THE GREETINGS:@{ub}\n\n                     @{i}SieGeL/tRSi sends his regards to:@{ui}\n\n Strider/tRSi   - Go on with FAME, you have to release it soon !\n BloodRock/tRSi - We must code together the DMS-Part for this checker ;)\n Beatnik/tRSi   - FullEd is the Power !\n Dr.Dre!/tRSi   - The tapes you''ve sended me are very nice :)\n ByteAndi/tRSi  - Don''t hear anything from you, call back mate!!!!!!!!\n Spy/tRSi       - Time to change to FAME...what do you think about it ?\n vAMPIRE/tRSi   - Hope you get everythink worked :) Waiting for the CD''s :)))\n aRGON/pDY      - Call more often, don''t here from you very much in the past\n dEATH aNGEL    - Hope your illness get''s better...best wishes!\n vENOM          - Nice to have english guys here, hope you like FAME :)\n tURBO          - The same to you, got yar in another chat :)\n sCANDIC/dCS    - FFS is the ruling name hehehe\n [oRK!]         - We talk the next days in chat, I promise!\n F. Monteilhet  - For cewl E-Mails and your nice help with translating :)\n\n\n             @{fg shine}...and of course to all my registered users and@{fg text}\n                @{fg shine}everone I''ve forgot to listen here....@{fg text}\n\n\n This is my first release in the mighty year 1996, the release year of a new\n generation of BBS-Systems:\n\n                    @{b}@{fg shine}FAME - Final Amiga MailBox Engine !@{ub}@{fg text}\n\n This checker is dedicated to this System, so go on and change/register now !\n\n   @{b}------------------------------------------------------------------------@{ub}\n\n    @{i}THE ONLY WAY TO MULTITASK ON MS-DOS IS TO RUN IBeM TWICE ON AN AMIGA !@{ui}\n@endnode\n\n@node "REGISTER" "Registration of Tools/Doors"\n@{b}REGISTER DOORS/TOOLS@{ub}\n\n All tools I''ve made in the past are released under the @{b}RegisterWare@{ub} concept.\n This means, that I release all my doors only one time as full working Public\n Versions, all updates/bugfixings are only available for registered Users.\n\n The Registration costs @{b}30.- DM@{ub} (or $20) and has to be paid only @{b}*ONE*@{ub}\n time for @{b}*ALL*@{ub} BBS-doors I have made until now. Of course all new \n doors are included in this registration fee, too.\n\n To become registered user, contact one of the following Boards and leave a\n mail to SieGeL/tRSi about Registration:\n\n @{b}pUNISHMENT iNC:@{ub} +49(0) 30 694 8470 (v.34) - fAME tEST/sUPPORT BBS!\n                 +49(0) 30 694 8570 (v.34)\n\n @{b}Paralysis:@{ub}      +49(0) 30 721 6071 (v.34)\n                 +49(0) 30 721 6072 (v.34)\n                 +49(0) 30 721 6073 (v.34)\n                 +49(0) 30 721 6065 (v.34)\n\n @{b}Spirit of Soul:@{ub} Absolute Private\n\n              @{fg shine}These Boards are supporting only 100% Public Domain.@{fg text}\n\n             You could also use @{b}E-Mail@{ub} or @{b}Compuserve@{ub} to contact me:\n\n                       E-Mail: [email removed]\n\n                   CompuServe: 101601,2654 (Sascha Pfalz)\n@endnode\n\n@node "FAME" "Informations about the FAME-System."\n\n                        @{b}Informations about FAME@{ub}\n\n FAME is at this time still under construction, but because of the fact\n that many people asked for FAME, it will be released until the end\n of february under the concept of shareware and will be available for\n everyone. At the begining not everything will be completly finished and\n because of this not everything you can already configure will work.\n The registered Versions have to work at least some days before they will\n be released for registered Users, but it''s still possible that these\n versions also make problems when using them. But as soon as you''ve\n reported those problems, they will be fixed!\n\n If some of the settings won''t work, it might be a bug but it''s also (more)\n possible that those functions are not implemented yet.\n\n Some of the internal functions are currently untested and it''s possible\n that they produce errors or problems, but please remember the complexity\n of FAME !\n\n If you have questions or problems with FAME, please turn on one of the\n FAME-Developers or ask Strider to solve your problems.\n\n\n@{b}@{u}What should FAME costs ?@{ub}@{uu}\n\n Registered Version:  110 USD / 150 DM\n Betatester Version:  145 USD / 200 DM\n\n\n@{b}@{u}What is included in the FAME-package ?@{ub}@{uu}\n\n Server, SystemEditor, MainPart, FAMEHydra.FIM, FAMEError.FIM\n\n FAME.library FAMEChat.FIM programmed by Bloodrock/tRSi\n\n FAMEFullEd.FIM, FAMEScript.FIM programmed by Beatnik/tRSi\n\n MUI UserEditor, FAMEDoorHelp.FIM, FAMEInfo programmed by SieGeL/tRSi\n\n Also some doors and tools from the FAME-Development-Team are included,\n but this doors are only unregistered Versions and have therefor some\n limitations. The registered Versions of those doors and the Informations\n how to get them are available here in the pUNISHMENT iNC. BBS.\n\n It could happen that some of the doors and tools listed here are currently\n missing because there are currently under development !\n\n\n@{b}@{u}Who creates FAME ?@{ub}@{uu}\n\n@{fg fill}Main programmer:@{fg text}\n\n - David ''Strider'' Wettig (tRSi) [email removed]\n\n@{fg fill}Additional programmer:@{fg text}\n\n - Oliver ''Bloodrock'' Lange (tRSi) [email removed]\n - Ulrich Arne ''Beatnik'' Jansen (tRSi) [email removed]\n - Sascha ''Siegel'' Pfalz (tRSi) [email removed]\n\n@{fg fill}FAME-Development-Team:@{fg text}\n\n - David ''Strider'' Wettig (tRSi) [email removed]\n - Oliver ''Bloodrock'' Lange (tRSi) [email removed]\n - Ulrich Arne ''Beatnik'' Jansen (tRSi) [email removed]\n - Sascha ''Siegel'' Pfalz (tRSi) [email removed]\n - Andreas ''ByteAndi'' Petermann (tRSi)\n - Dirk ''Spy'' Holzkampf (tRSi) [email removed]\n - Bodo ''Dr.Dre!'' Hoffmann (tRSi)\n\n\n@{b}@{u}Disclaimer:@{ub}@{uu}\n\n No warranties are given. We take no responsibility of any possible harm this\n product could do to your AMIGA system (not that it would but..).\n We give also no warranties to any dokuments or doors/tools included with\n FAME.\n You use FAME and all FAME related files at your own risk !\n\n Of course we take no responsibility when someone is using FAME for illegal\n terms.\n @{b}------------------------------------------------------------------[EOF]-----@{ub}\n@endnode\n\n@node HeddleyAutoIndex "Index"\n@remark Index auto-generated by Heddley\nIndex of database mULTI-cHECK\n\nDocuments\n\n@{"An example for a Stripfile used by mULTI-cHECK" link "SAMPLE_STRIPFILE"}\n@{"An example for an Advert used by mULTI-cHECK" link "SAMPLE_ADVERT"}\n@{"Copyright Informations for mULTI-cHECK" link "COPYRIGHT"}\n@{"Credits and the wellknown Greetings" link "CREDITZ"}\n@{"How to use it and list of Parameters" link "USAGE"}\n@{"Informations about the FAME-System." link "FAME"}\n@{"Installation to your BBS-System of mULTI-cHECK" link "INSTALLATION"}\n@{"mULTI-cHECK - Archive-Checker for FAME & Amiex Systems" link "Main"}\n@{"Registration of Tools/Doors" link "REGISTER"}\n@{"Some examples how to use mULTI-cHECK." link "USAGE_EXAMPLES"}\n@{"Some informations about mULTI-cHECK" link "INTRODUCTION"}\n\nButtons\n\n@{"  CREDITS & GREETINGS!  " link "CREDITZ" 0}\n@{"  USAGE AND PARAMETERS  " link "USAGE" 0}\n@{"(CLICK HERE FOR OPTIONS)" link "USAGE" 0}\n@{"Advert" link "SAMPLE_ADVERT" 0}\n@{"ADVERT.TXT" link "SAMPLE_ADVERT" 0}\n@{"Click here for some examples of mULTI-cHECK" link "USAGE_EXAMPLES" 0}\n@{"COPYRIGHT & DISTRIBUTION" link "COPYRIGHT" 0}\n@{"Example-Stripfile" link "SAMPLE_STRIPFILE" 0}\n@{"examples" link "USAGE_EXAMPLES" 0}\n@{"FAME" link "FAME" 0}\n@{"FAME-System" link "FAME" 0}\n@{"HERE" link "SAMPLE_ADVERT" 0}\n@{"HERE" link "USAGE_EXAMPLES" 0}\n@{"Installation" link "INSTALLATION" 0}\n@{"INSTALLATION TO YOUR BBS" link "INSTALLATION" 0}\n@{"INTRODUCTION & FEATURES " link "INTRODUCTION" 0}\n@{"Parameters" link "USAGE" 0}\n@{"RegisterWare" link "REGISTER" 0}\n@{"stripfile" link "SAMPLE_STRIPFILE" 0}\n@{"STRIPFILE.TXT" link "SAMPLE_STRIPFILE" 0}\n@{"STRIPFILE=<PATH_TO_FILE>" link "USAGE" 0}\n@endnode\n','\n',char(10)),'{"STACK":"SAME","PRIORITY":"1","TYPE":"LHA@{fg"}',NULL,101459,4,0,NULL,NULL,'check200','scan',1780048442);
INSERT INTO door_catalog VALUES('check200','CHECK200.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CHECK200.LHA','Check','REXX','o..................................o',NULL,NULL,NULL,'.     __    CHECK 2.00    _     _  . .    / /_    _ ____    __| |   | | . .   / /| |  | |____|  / /| |  / /  .',replace(replace('o..................................o\r\n.     __    CHECK 2.00    _     _  .\r\n.    / /_    _ ____    __| |   | | .\r\n.   / /| |  | |____|  / /| |  / /  .\r\n.  / / | |  | |      / / | | / /   .\r\n. / /  | |--| |----\/ /  | |/ /    .\r\n. \ \  | |--| |----/\ \  | |\ \    .\r\n.  \ \ | |  | |____  \ \ | | \ \   .\r\n.   \ \| |  | |____|  \ \| |  \ \  .\r\n.    \ \~    ~         ~~| |   | | .\r\n.     ~~  UL & DL STATUS  ~     ~  .\r\no.......For Amiexpress v3.XX.......o\r\n\r','\r',char(13)),'\n',char(10)),'prophet.doc',replace('         °         .  SpEed   .    rUleS   .    aT    .        .        °\n _ __/\______/\_____    ______/\________/\__/\ _/\____________/\__________ \n    \      ~\      ~\  /~    \      ~\     /  \_         ~  _            /\n     \__/\   \__/\   \/  /\   \__/\   \   /    /  /\__/\   /    /\  /\  /\n   _//   /   /   /  _/    /   /   /   /  _   _/   __/\..\_/    /  \   \/ °\n _///    ___/   _   \_   /   /    ___/   /   \    \   \::/    /\   \   \__\n\\\\\__  /:/ __/\    ____  _/\__  /:\   /___/:\_______ \/    /: \____  /::.\n ~~~~~~\/~~\/~~~~\  /~~~~\/~~~~~\/~~~\_/~~~~~~~~~~~~~~\  ___/~~~~~~~~\/~~~~\n  Nero/Scandal    \/    + 4 6 - I T ''S - P R I V A T E \/    Scandal SHQ!  \n   Fate!/QTX       ___/\__/\   ___/\_    _/\__   _/\_____  Daily US Imports\n     Zych/Scandal  \__   /  \_/~     \  /~   /   \      "\  2-Hours Amiga\n °     Juan/Afl     /   /    /  _/\   \/    /    _\__/\   \__ _ /X 3.32\n    .         _ ___/   _    /     /   /    /_/\ /     /   / Ask for the NUP\n        °        .\    /   /\    /   /\   /    \_   _/   /.      . °\n              ..:::\  /___/::\____  /::\______  /\  ____/:::..[rVn] .\n       .      ~~~