INSERT INTO door_catalog VALUES('checknu','CHECKNU.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CHECKNU.LHA','CheckNU','XIM','CheckNU',NULL,NULL,NULL,'EXON SCHAU MAL NACH. THANX',replace('SCHEIßE, KEINE aHNUNG\nEXON SCHAU MAL NACH. THANX\n','\n',char(10)),'CheckNU.DOC',replace('\n                  ###### ###   ## ######  ### ######  ######              \n    _______|\     ###    #### ### ###  ## ### ###  ## ###       /|________\n   |         >    ####   ######## ######  ### ######  ####     <         |\n   | |¯¯¯¯¯|/     ###    ### # ## ###     ### #####   ###       \|¯¯¯¯¯| |\n   | |            ###### ###   ## ###     ### ### ##  ######           | |\n   | |_________________________________________________________________| |\n   |                                                                     |\n   |                            CheckNU V1.0                             |\n   |                            ~~~~~~~~~~~~                             |\n   |                             TYPE:  XIM                              |\n   |                                                                     |\n   |                  ©1994 EMPiRE / MYSTiC /X-DESiGN                    |\n   |                                                                     |\n   |       LaSt OuTpOsT  +31-72-157682 & +31-72-201182  -  HOLLAND       |\n   |                                                                     |\n   |       AmixNet:  @NL0004   -   /X-Fido:  44:100/102     EMPiRE       |\n   |_____________________________________________________________________|\n\n===============================================================================\n\n PURPOSE:\n ~~~~~~~~\n  - Checks NewUser Status for Lameness:\n\n    (New) Users that have logged on a number of times and didn''t upload a\n    number of bytes and have a certain Level will be warned that their\n    account is not good enuf and that they have a number of logOn''s left\n    to Change this. After that if the User didn''t comply he is SetBack to\n    the NewUser Conference.\n\n\n===============================================================================\n\nOutput Messages:\n~~~~~~~~~~~~~~~~\n\n  MINLEVEL   15             \n  MINLOGON   10             \n  MAXLOGON   13             \n  MINBYTES   1000000        \n\n o Warning Message:\n\n ============================[   W A R N I N G   ]===========================\n                                                  \n               Your Account is BAD! You already logged on 10 Times\n\n                     Without even Uploading at least 1 Mb!\n \n                    You got 3 LogOn''s left to Change this!!\n\n                      Otherwise your Account here is GONE!!\n\n =[ 8 ]======================[   W A R N I N G   ]===========================\n\n\n\n o SetBack Message:\n\n ============================[   W A R N I N G   ]===========================\n\n \n     Your Account has been put back to a NEWUSER level coz of INACTIVITY.\n\n\n =[ 8 ]======================[   W A R N I N G   ]===========================\n\n\n\n===============================================================================\n\n REQUIREMENTS:\n ~~~~~~~~~~~~~\n  Ami Express 3.xx (there won''t be a 1.1x or 2.xx Version. So UPGRADE NOW!)\n\n\n===============================================================================\n\n INSTALLATION:\n ~~~~~~~~~~~~~\n  o Copy the EmP_Tools Directory to DOORS:\n    Edit it to your Needs. (Check the Existing CheckNU.CFG!)\n\n CheckNU.CFG LayOut:\n\n##[ start: cut here ]#########################################################\nMINLEVEL   15                   ; Levels equal/below MINLEVEL will be Checked\nMINLOGON   10                   ; Min. Nr of LogOns before Warning\nMAXLOGON   13                   ; Max. Nr of LogOns before NEWUSER SetBack\nMINBYTES   1000000              ; Min. Upload Bytes for Checking\nLOGFILE    BBS:SetBack.LOG      ; LogFile of Users who where SetBack\n##[ end: cut here ]###########################################################\n\n\n  AE 3.xx:\n  ~~~~~~~~\n  o Copy CheckNU.info BBS:Commands/SYScmd/\n\n    Or add to CheckNU.info ICON ToolType Info:\n\n      ACCESS=001\n      LOCATION=DOORS:EmP_Tools/CheckNU\n      MULTINODE=YES\n      PRIORITY=0\n      STACK=50000\n      TYPE=XIM\n\n  o This Door was designed to Start from a Bulletin this way the Door is\n    started with every User\n\n    as BBS:Bull.txt\n\n--[ start: cut here ]-------------------------\n~CC_FE_Sent\n--[ stop: cut here ]--------------------------\n\n    or with a txtfile (BBS:Bulletins/bull.txt)\n\n--[ start: cut here ]-------------------------\n~SS_BBS:Bulletins/bull.txt|~CC_FE_Sent\n--[ stop: cut here ]--------------------------\n    Example:\n\n    ~SS_BBS:Bulletins/bull.txt|~CC_CheckNU|~CC_Sent_FE|\n\n\n===============================================================================\n\n NOTE:\n ~~~~~\n\n  o When a User is SetBack the Carrier will be dropped! There is no other way\n    because /X will let the User join the conference he was last in even\n    when he hasn''t got access to it anymore!\n\n  o Users that have been SetBack to the NewUser Conference will see the\n    Message again when the LogOn but the Carrier will not be dropped!\n    So the User can explain his MisBehaviour (or NOT).\n\n  o Keep in mind that if the Name of the NewUser Conference changes then\n    Users who were setback to the Old NewUser Conference are always Kicked\n    Off after the Message.\n\n  o In the LogFile contains:\n     - Date the User was SetBack\n     - UserName\n     - ConferenceAccess before the User was SetBack\n\n  o The LogFile will be Created if it doesn''t exist!\n\n\n===============================================================================\n\n ERROR MESSAGES:\n ~~~~~~~~~~~~~~~\n\n  o ERROR:  CheckNU ONLY Works with /X 3.x!!\n  |\n  `--> Obvious\n\n  o ERROR:  DOORS:EmP_Tools/CheckNU.CFG Not Found !!!\n  |\n  `--> CheckNU.CFG can''t be found in DOORS:EmP_Tools !?\n\n  o ERROR:  BBS:ACCESS/Preset.1.info Not Found !!!\n  |\n  `--> BBS:ACCESS/Preset.1.info can''t be found\n\n  o ERROR:  BBS:Access/PRESET.1.info is NOT valid!\n  |         Can''t find IconToolType: PRESET.AREA\n  |\n  `--> Check BBS:Access/PRESET.1.info for Errors\n\n  o ERROR:  Can''t Open DoorFile\n  |\n  `--> For some reason the DoorFile can''t be Created or Written to!\n\n  o ERROR:  UnKnown Keyword: XXXXXXXX in CheckNU.CFG\n  |\n  `--> There must be 5 different lines in the INIT part (CheckNU.CFG)\n       Compare this with the original CheckNU.CFG\n       Check that the KeyWords are:\n\n         MINLEVEL\n         MINLOGON\n         MAXLOGON\n         MINBYTES\n         LOGFILE\n\n\n===============================================================================\n\n BUG REPORT & SUGGESTIONS:                                                                   \n ~~~~~~~~~~~~~~~~~~~~~~~~~\n  It''s possible that a mistake will occur.... Nobody is Perfect.\n  If you have any Suggestions or Comments Please Leave a Message on my Board:\n\n   LaSt OuTpOsT  N1: +31-72-157682  N2: +31-72-201182  -  HOLLAND\n   ~~~~~~~~~~~~  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~     ~~~~~~~\n       AmixNet:  @NL0004   -   /X-Fido:  44:100/102   EMPiRE\n       ~~~~~~~~~~~~~~~~~       ~~~~~~~~~~~~~~~~~~~~   ~~~~~~\n\n===============================================================================\n\n /X NOTE:\n ~~~~~~~~\n  This Program Has been tested on a /X 2.0 - /X 3.32 Configuration.\n\n\n===============================================================================\n\n REGISTRATION:\n ~~~~~~~~~~~~~\n  If YOU use this Program please let me know by Calling Last Outpost or\n  to send me a Message by NetMail @NL0004 - EMPiRE  Coz I want to know\n  how many Sysops are using my Tools!!!\n \n\n===============================================================================\n\n HISTORY:\n ~~~~~~~~\n  V0.1  12-10-92 - First Beta Version.\n\n  V0.2  12-22-92 - Added a LogFile with all SetBack Users.\n                 - Added some more Ansi-Color\n        01-17-94 - When CheckNU is run, it will ShowUp on the Server.\n        01-25-94 - Fixed the ''10-Node'' BUG\n\n  V1.0  01-29-94 - Release Version\n\n\n===============================================================================\n\n EMPiRE /X DOORS/UTILS COLLECTION UNTIL NOW!:\n ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n  - AboStats V0.2                        AIM Door\n  - AutoOnline V1.1                      XIM Door/Util\n  - Bulls V2.0                           XIM Door\n  - CheckNU V1.0                         XIM Door\n  - ConfAccess V1.1                      ServerUtil\n  - CopyDate V1.3                        CLI Util\n  - DlDir V2.0                           XIM Door\n  - DoorKIT 1.01                         XIM Doors/Includes\n  - DMenu V1.0                           AIM Door\n  - DutchNET V1.0  [AmiXnet]             AIM Door\n  - Front V2.0                           XIM Door\n  - JoinCnf V3.4                         XIM Door\n  - LastCalls & TopUps V1.2              LogOffUtil\n  - LastDL V0.1                          LogOffUtil\n  - LastUL V0.1                          LogOffUtil\n  - MakeFree V1.1                        AIM Door\n  - MemberList V1.0                      AIM Door\n  - MonthTopUp V2.0                      ServerUtil\n  - MultiNodeLastCaller V1.1             LogOffUtil\n  - Page V2.0                            XIM Door\n  - PMail V1.1                           AIM Door\n  - Remote Maintenance V1.3              AIM Door\n  - SceneTalk Voter V2.3                 AIM Door\n  - SceneTalk Voter V2.2 [Party]         CLI Door\n  - SecLevChk V1.0                       ServerUtil\n  - Sent FrondEnd 1.0  [Sent_FE]         XIM Door\n  - SysopCommands V1.0                   AIM Door\n  - UserData Cleaner/Repair V2.0         ServerUtil\n  - UserStats V2.0                       ServerUtil\n  - UsrCnfAx V1.1                        CLI Util\n  - View & Check Archive/Text V1.7       AIM Door\n  - WhoNode V1.3                         AIM Door\n\n===============================================================================\n\n THANX MUST GO TO ALL OFFICIAL BETA-TESTERS:\n ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n   Tycoon/Mystic             [Channel X]\n   ByteAndi/Mystic           [Diabolo]\n   JPS                       [Red October]\n   Sal-One/TRSi              [BoonDocks]\n   Sharon/Scx                [The Unknown]\n   Blue Bird/Mystic          [Tau Ceti]\n   Easy Rider/Mystic         [Mamba]\n   Mega Fortress             [MF Enterprise]\n   Beast/Partek              [Sequencial]\n   SpeedDevil/Partek         [Rising Sun]\n\n\n GREETZ/TNX GO TO:\n ~~~~~~~~~~~~~~~~~\n   ByteAndi/MST /X-DESiGN  - NewFiles is the best! And Tnx for all ya ''C''\n                             Help & Sources! You''re (almost) the Greatest!\n   Killraven/MST /X-DESiGN - For giving me sum Great Pointers/Sources on ''C''\n   CrackDown/MST /X-DESiGN - Nice Doors, Keep it up!\n   JAF/G.O.D.              - For some good REXX ideas\n   Bad Sector/Hidden       - Still Using your Sort-Routine. It''s the Fastest!\n   B.O.B./Paradox          - For (Mis)Using/Testing my tools!\n   Aragorn/Vision          - Tnx for Testing in the past\n   Camelot/Complex         - Tnx for Testing in the past\n   Telekinetic/T.F.A.      - Tnx for Testing in the past\n   Alcoholic               - Tnx for Testing in the past\n   Price/T.F.A.            - Great job on your {F}ull {S}creen {E}ditor!\n   Van Damme               - Nice Doors!!!\n   DR.G/IBB                - Hope to see Check''N Add work on a 040\n   SiGMA SEVEN             - Nice job on SiGMA-EXPRESS!\n   911/Movement            - Tnx For ya Ansi Logo''s!! You''re the Greatest!\n   Mike                    - Tnx for calling!\n   Amicom/TRSi             - Tnx for calling!\n   SkIn                    - Tnx for ya Description Logo! Looks Great!!\n   Shadow Man/S8           - Nice Doors & Tnx for ya greetz! & Calling ofcoz\n   [MAZ!^PHAZE]            - Tnx for calling!\n   Shuyuki Tanaka          - Tnx for your Messages!\n   AGONY/cOmpLeX           - Tnx for calling!\n   HUMANOiD & RU$tY/AFL    - Tnx for calling!\n   LECTOR                  - Tnx for your NetMail\n   Koo Koo Ka Choo         - Tnx for calling!\n   TaRzAN                  - Tnx for your NetMail. Yezz 040 Speed Rulez!!\n   Crayor/Scx              - Tnx for calling!\n   Foxx''n''Lynxx            - Tnx for your BugReports!!!\n   ThE BiRD                - Tnx for your NetMail on UsrCnfAx\n   Dux                     - Tnx for your NetMail\n   dR.dRE!/fAITH           - Tnx for da greetz, Nice Doors btw\n   [-RUNT&SCOTTIE-]        - Tnx for calling!\n   sPAcEcAKe/aF            - Tnx for calling!\n   Freddy Kreuger/GOD      - Tnx for your NetMail on JoinCnf 3.2\n   MF1                     - Tnx for calling!\n   AtomiX/N.A.S.A          - Hope the ''C'' archive was sume help for ya!\n   MAD HARLEQUiN [ITPH01]  - Tnx for your Nice AmiXnet Messy''s\n   Mike Hoffren  [SF0001]  - Tnx for the BugReport on JoinCnf 3.3 [100+ Cnfs]\n   Galaxy/TFA              - Nice job on da SentCleaner\n\n\n   & Ofcoz to ALL MYSTiC Members all over the Globe!\n\n\n                        ______  __________________                            \n.----------------+-----/    \ \/ / __/_  __/ / __/----------+----------------.\n|                |----/ / / /\  /\  /-/ /-/ / /----[ /X ]---|                |\n|       /\    /\ |-EmP\/ / /-/ /\  /-/ /-/ /\ \--[ DESiGN ]-|       /\    /\ |\n|      /C \  /N/ +-----\/\/--\/--\/--\/--\/--\/-------------+      /C \  /N/ |\n|     /i/\ \/G/  |                                          |     /i/\ \/G/  |\n|    /T/  \ i/   |                                          |    /T/  \ i/   |\n|   /S/   /S \   |   EMPiRE   -   BYTEANDi   -  CRACKDOWN   |   /S/   /S \   |\n|  /Y/   /E/\ \  |   TYCOON   -   KiLLRAVEN  -   SiEGEL     |  /Y/   /E/\ \  |\n| /M/   /D/  \ \ |   FUZZY    -      SPY     -  INCOGNiTO   | /M/   /D/  \ \ |\n| \/    \/    \/ |   RE/Y\o   -     BoBo     -   HARDBYTE   | \/    \/    \/ |\n|                |                                          |                |\n`----------------+----------[  MYSTiC /X DESiGN  ]----------+----------------''\n\n \n\n                       ____ _________ _________ ________ _____\n            MYSTiC    /   / \\  /    \\\  /   _\\\  /   \\\  /     MYSTiC\n                     /   /   \\/   /\ \\\/   /___\\/__   \\\/\n         CONSOLE    /   / /\  /   __   \ \____   \   /   /      AMIGA\n                   /   /_/  \/   / /   /_____/   /  /   /\n       WORLD-HQ    \________X___/ /___/\________/   \__/      EURO-HQ\n      ____ _________ ________ _________ _________ _________ ________ _____\n     /    \\\  /   / \\  /   \\\  /    \\\  /    \\\  /   _\\\  /   \\\  /\n    /   /\ \\\/   / /\\\/__   \\\/   /\ \\\/   /\ \\\/   /___\\/__   \\\/\n   /   / /  \/   / /  \   /   / /   _____\/   / /  \ \____   \   /   /\n  /   /_/   /   /_/   /  /   / /   /     /   /_/   /_____/   /  /   /\n  \________X_________/   \__/  \__/      \________/\________/   \__/\n\n\n  AMIGA - SNES - MEGADRIVE - GAMEBOY - GAMEGEAR - PC ENGINE - LYNX - C64\n\n  3.5 Gb ONLINE          SYSOP:  EMPiRE / MYSTiC           3.5 Gb ONLINE\n\n  HOLLAND:          +31-72-157682  &  +31-72-201182             :HOLLAND\n\n','\n',char(10)),'{"ACCESS":"001","LOCATION":"DOORS:EmP_Tools/CheckNU","PRIORITY":"0","STACK":"50000","TYPE":"XIM"}','auto-added',25170,5,0,NULL,NULL,'emp_cn10','scan',1780048442);
INSERT INTO door_catalog VALUES('chek20b2','CHEK20B2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CHEK20B2.LHA',NULL,'XIM','BelchCHECK ß2','0.2',NULL,NULL,'Fixed the Freedownload maker bug and also made the Dupechecker optional for every node Make sure that you reconfigure the whole',replace('BelchCHECK v0.2ß2\nFixed the Freedownload maker bug and also\nmade the Dupechecker optional for every node\nMake sure that you reconfigure the whole\ndoor or just delete the old config file...\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 19:07:27  ON NODE: 1\n','\r',char(13)),'\n',char(10)),NULL,NULL,48025,7,0,NULL,NULL,NULL,'scan',1780048442);
INSERT INTO door_catalog VALUES('chess','CHESS.LZH','~/Code/amiexpress_doors/Archives/AmiExpress/CHESS.LZH','chess','XIM','2WB4-aDDV-LCSE',NULL,NULL,NULL,NULL,replace('Chess Online Game For /X\n','\n',char(10)),'TRYTHIS.DOC',replace(replace('1-2-1990\r\nDear Friend,\n\n     My name is Dave Rhodes.  In September 1988 my car was\nreposessed and the bill collectors were hounding me like you\nwouldn''t believe.  I was laid off and my unemployment checks\nhad run out.  The only escape I had from the pressure of\nfailure was my Apple computer and my modem.  I longed to\nturn my advocation into my vocation.\n\n     This January 1989 my family and I went on a ten\nday vacation.  I am currently building a home on the\nWest Coast of Florida, with a private pool, boat slip, and a\nbeautiful view of the bay from my breakfast room table and\npatio.  I will never have to work again. Today I am rich!  I\nhave earned over $400,000.00 (Four Hundred Thousand Dollars)\nto date and will become a millionaire within 4 or 5 months.\nAnyone can do the same.  This money making program works\nperfectly every time, 100% of the time.  I have NEVER failed\nto earn $50,000.00 or more whenever I wanted. Best of all\nyou never have to leave home except to go to your mailbox or\npost office.\n\n     In October 1988, I received a letter in the mail\ntelling me how I could earn $50,000 dollars or more whenever\nI wanted.  I was naturally very skeptical and threw the\nletter on the desk next to my computer. It''s funny though,\nwhen you are desparate, backed into a corner, your mind does\ncrazy things. I spent a frustating day looking through the\nwant ads for a job with a future.  The pickings were sparse\nat best.  That night I tried to unwind by booting up my\nApple computer and calling several bulletin boards.  I read\nseveral of the message posts and than glanced at the letter\nnext to the computer.  All at once it came to me, I now had\nthe key to my dreams.\n\n      I realized that with the power of the computer I could\nexpand and enhance this money making formula into the most\nunbelievable cash flow generator that has ever been created.\nI substituted the computer bulletion boards in place of the\npost office and electronically did by computer what others\nwere doing 100% by mail.  Now only a few letters are mailed\nmanually.  Most of the hard work is speedily downloaded to\nother bulletin boards throughout the world.  If you believe\nthat someday you deserve that lucky break that you have\nwaited for all your life, simply follow the easy\ninstructions below.  Your dreams will come true.\n\n                          Sincerely yours,\n\n                          Dave Rhodes\n\n\n\n                       INSTRUCTIONS\n\nFollow these instructions EXACTLY, and in 20 to 60 days you\nwill have received well over $50,000.00 cash, all yours.\nThis program has remained successful because of the honesty\nand integrety of the participants.  Please continue its\nsuccess by carefully adhering to the instructions.\n\nWelcome to the world of Mail Order!  This little business is\na little different than most mail order houses.  Your product\nis not solid and tangible, but rather a service.  You are in\nthe business of developing Mailing lists.  Many large\ncorporations are happy to pay big bucks for quality lists.\n   (The money made from the mailing lists are secondary to the\n    income which is made from people like yourself requesting\n    that they be included in that list.)\n\n\n  1)  Immediately mail $1.00 to the first 5 names listed\n      below starting at number 1 through number 5.  Send cash only\n      please (total investment $5.00). Enclose a note with each\n      letter stating: "Please add my name to your mailing list."\n      Enclose the filled out questionare. Be sure to fill out\n      as much of the questionaire as you feel comfortable doing.\n\n         (This is a legitimate service that you\n          are requesting and you are paying $1.00\n          for this service).\n\n  2)  Remove the name that appears number 1 on the list.\n      Move the other 9 names up one position. (Number 2 will\n      become number 1 and number 3 will become number 2, etc.)\n      Place your name, address and zip code in the number 10\n      position.\n\n  3)  Post the new letter with your name in the number 10\n      position into 10 (Ten) separate bulletin boards in the\n      message base or to the file section, call the file,\n      MAKEMONY.ARC, or something similar.\n\n  4)  Within 60 days you will receive over $50,000.00 in\n      CASH.  Keep a copy of this file for yourself so that you can\n      use it again and again whenever you need money. As soon as\n      you mail out these letters you are automatically in the mail\n      order business and people are sending you $1.00 to be placed\n      on your mailing list. This list can than be rented to a list\n      broker that can be found in the Yellow Pages for additional\n      income on a regular basis.  The list will become more\n      valuable as it grows in size.  This is a service.  This is\n      perfectly legal.  If you have any doubts, refer to Title 18,\n      Sec. 1302 & 1341 of the postal lottery laws.\n\n       NOTE: Make sure you retain EVERY Name and Address sent\n             to you, either on computer or hard copy, but do not\n             discard the names and notes they send you.  This is\n             PROOF that you are truely providing a service and\n             should the IRS or some other Government Agency\n             question you, you can provide them with this proof!\n\n   Remember as each post is downloaded and the instructions\n   carefully followed, five members will be reimbursed for\n   their participation as a List Developer with one dollar\n   each.  Your name will move up the list geometrically so that\n   when your name reaches the number five position you will be\n   receiving thousands of dollars in cash.\n\n\n\n\n  1. Jason Keegan       PSC Box 475\n                        RAF Fairford\n                        Gloucestershire\n                        GL7 4DL England\n\n  2. Scott Stevens      PSC Box 946\n                        RAF Fairford\n                        Gloucestershire\n                        GL7 4DL England\n\n  3. Jeffrey Conner     PSC Box 185\n                        RAF Fairford\n                        Gloucestershire\n                        GL7 4DL England\n\n  4. Brad Funke         PSC Box 962\n                        RAF Fairford\n                        Gloucestershire\n                        GL7 4DL England  \n                        \n  5. Tim Jones          PSC Box 917\n                        RAF Fairford\n                        Gloucestershire\n                        GL7 4DL England\n\n  6. James Mahoney      2350 Tilghman Street\n                        Allentown, PA\n                        18104\n\n  7. Michelle Feaster   27 S 18th St.\n                        Allentown, PA\n                        18104\n\n  8. Juan Olmeda        PSC Box 1381\n                        RAF Fairford\n                        Gloucestershire\n                        GL7 4DL England\n\n  9. Woody Baker\n     Rt.1 Box I\n     Manor, Tx. 78653\n\n\n 10. Bob Shipman\n     Box 20, Hotz Hall\n     Fayetteville, AR  72701\n\n\n  ----------------------------------------------------------\n\nName            :______________________________\nAddress line 1  :______________________________\nAddress line 2  :______________________________\nCity         :________________\nState  :__\nZipcode         :__________\n(optional)\nSex (M/F) :_\nDate of Birth :_____________ (mm/dd/yy)\nPhone           :(___) - ___ - ____\nComputer type   :_______________________________\n  :_______________________________(things you like\nHobbies         :_______________________________ to do)\n  :_______________________________\nCatagories :_______________________________(things you\n  :_______________________________ are interested\n  :_______________________________ in receiving\n  :_______________________________ mail on)\nPets  :_______________________________ (What kind)\nOccupation :_______________________________\nType of car :_______________________________\nOwn or Rent :______________\nHouse or Apt :_____________\n# Children :_____ (if any)\nMarried (y/n) :_____\nSelf-employed   :______________________ (do you work for yourself?)\nBusiness name :______________________ (if you own your own)\nOwn a life polcy:_______________________ (own a life insurance policy)\nPurchase by mail:_________________________ (items that you have\n  :_________________________  or would purchase\n  :_________________________ )\nHousehold income range:____________________(rough figures)\n\n\n\nThe reason for requesting the above information is simple.\nMost users of mailing lists need to be able to selectivly\ntarget a particular audience.  If you are selling, say knitting\nmaterials, it would be a waste of your money to mail a catalog\nto someone who has no interest in knitting.  So, you would\nrequest that the list supplier select the names by certain\ncatagories.  The list supplier will charge you a bit more, but\nyour return for invested dollars will be much higher.\n\nEven though some of these are fairly personal in nature, they\nare all valid selection criteria for a mailing list.\n\nThe Catagories information above is very important.  You\nshould fill it out with a list of catagories of things that\nyou are interested in. The hobbies and occupation fields\nare just as important.  Perhaps you like to hunt.  If I sent\nyou an offer to join an anti-hunting group, not only would\nyou be upset, but I would have wasted my time and money.\n\nAdditional Notes:\n\n     This system works equally well if mailed out manually.\nMind you it takes more effort to hand address the envelopes\nand the cost goes up proportionately to cover the postage\nand envelopes.  You must also photo copy the instructions,\ncross out the name in  number one position, write in your\nname in the number ten slot and change the rest of the\nnumbers accordinly. (It might be neater to use white out or\npaste over the names.)  In order to achieve the same results\nyou must send out the $1.00 dollar to the first five names\nand then send out another 100 letters with copies of the\nprogram enclosed.  It has been suggested not to put a return\naddress on the outside of the envelope in order to encourage\nthe recipient to open it.  The return will approxiamate that\nthen received from the posts listed on the bulletin boards.\n\n   I see no reason why this won''t work in the United Kingdom,\nand I have a 900 quid phone bill to pay, so what the hell? Of\ncourse, the amount should be one pound, not one dollar, as \ndollars are hard to come by over here. \n\n                      Tim Jones\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',64031,6,0,NULL,NULL,'chess','scan',1780048442);
INSERT INTO door_catalog VALUES('chkpr351','CHKPR351.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CHKPR351.LHA','Checker','XIM','Checker',NULL,'Faktor/Independent',NULL,'## LhA/LZX Checker Professional Beta 3.51 ## ## -------------------------------------- ## ##       »» ßeta public release ««        ##',replace('############################################\n## LhA/LZX Checker Professional Beta 3.51 ##\n## -------------------------------------- ##\n##       »» ßeta public release ««        ##\n##                                        ##\n## - Bytes stripped with ISTRIP fixed!    ##\n## - Skipping Adding & Stripping when an  ##\n##   archive is larger than a spec size   ##\n##                                        ##\n##  Copyright (c) by Faktor/Independent   ##\n############################################\n','\n',char(10)),'Checker.guide',replace('@database "Checker.guide"\n@master "Checker.guide"\n@author Faktor/Independent\n@(c) "Copyright (c) by Faktor/Independent"\n@$VER: V3.51 (29-Mar-96)\n\n\n@node "Main" "Checker Help"\n\n\n\n        @{b}LhA/LZX Checker Professional V3.51@{ub} is an established public\n             Copyright, from 1993-1996 by Faktor/Independent.\n\n                         " A BETA PUBLIC RELEASE "\n\n\n                            @{"   Introduction    " link "Introduction" 0}\n                            @{"   Features        " link "Features" 0}\n                            @{"   Requirements    " link "Requirements" 0}\n                            @{"   Installation    " link "Installation" 0}\n                            @{"   Configuration   " link "Configuration" 0}\n                            @{"   History         " link "History" 0}\n                            @{"   Special Thanks  " link "Special Thanks" 0}\n                            @{"   Needed...       " link "Wanted" 0}\n@endnode\n\n@node "Introduction" "Checker/Introduction"\n============================================================================\n                               @{b}Introduction@{ub}\n============================================================================\n\n     Much appreciated for you who have taken the time to view this text,\n     as there are words in this text that I wish you to read.\n\n     I would  like  to  start  this  text off with a brief history of my\n     reason  producing Checker. I have come to the conclusion that I had\n     the knowledge to program a serious Lha/Lzx Checker. Since the scene\n     was lacking a quality Checker for I took the opportunity.\n\n     I have been programming Checker for the past year and will continue\n     to develop  it with as much sincere effort as always. Checker is by\n     release  the  far  most  reliable, robust  and fastest checker. The\n     combination  of safe and intelligent code with new thinking made it\n     the unbeatable solution.\n\n     The  intention  was to  provide an  replacement for all old fashion\n     checkers.  Therefore  it  is  written  especially for the Commodore\n     Amiga computer®. The primary goal is to provide the Amiga community\n     with  a  fast  and  efficient  LhA/LZX  utility   for  BBS/Shell/WB\n     usages.\n\n                                  @{" Main " link "Main" 0}\n\n@endnode\n\n@node "Features" "Checker/Features"\n============================================================================\n                                 @{b}Features@{ub}\n============================================================================\n\n	- Both LhA, LZH and LZX compatibility.\n	- File Multi/Single file selection via ASL requester.\n	- FILE_ID.DIZ adding, both an TOP and END line banner.\n	- Multi random FILE_ID.DIZ adding.\n	- FILE_ID.DIZ advert stripping.\n	- FILE_ID.DIZ viewing.\n	- Multi random filename advertising.\n	- Intelligent stripping routine.\n	- Archive listing.\n	- Selective path for LHA & LZX. Therefore possible to run RESIDENT.\n	- IStrip support.\n	- Batch file execution (script).\n	- Changeable WORK PATH.\n	- And last, the code has not been optimized in any way, just to be\n  	  sure it will benefit on ALL amigas without any compatibility\n          problems. Therefore the code is 100% PURE, and will safely run in\n          RESIDENT mode.\n\n                                  @{" Main " link "Main" 0}\n@endnode\n\n@node "Requirements" "Checker/Requirements"\n============================================================================\n                               @{b}Requirements@{ub}\n============================================================================\n\nThis version of LhA/LZX Checker requires:\n\n- Kickstart 2.04 (or above)\n- MC68000 (or better)\n- asl.library v37+\n- LhA v1.50R+\n- LZX v1.20R+\n- The T: directory assigned (preferred in Ram Disk:)\n- At least a stack of 4096.\n\n                                  @{" Main " link "Main" 0}\n@endnode\n\n@node "Installation" "Checker/Installation"\n============================================================================\n                               @{b}Installation@{ub}\n============================================================================\n\n@{b}Certain files is required for it''s execution:@{ub}\n\nConfiguration file (Checker.info) must be located in S:\n\nFor adding and stripping the files: Lha.Kill, Lha.Add, Lzx.Kill and Lzx.Add\nmust also be copied into S:\n\nFor File_id.diz stripping also copy the file FileId.strip into S:\n\nTo run Checker once, either type it''s name into a SHELL window, or\ndouble-click on it''s icon from the Workbench.\n\nGeneral aim by this utility is for BBS usages, therefore I''ve included\nthe icon settings files for AmiExpress® Bulletin Board System.\n\nSetting up Checker for other systems is easy, since it takes the filename\nas first argument.\n\n\n\n                                  @{" Main " link "Main" 0}\n@endnode\n\n@node "Configuration" "Checker/Configuration"\n============================================================================\n                            @{b}Available tooltypes@{ub}\n============================================================================\n\n       @{"   REMOVE              " Link "REMOVE"            0}              @{"   ADD                 " Link "ADD"    0}\n       @{"   CHECK               " Link "CHECK"             0}              @{"   ISTRIP              " Link "ISTRIP" 0}\n       @{"   LIST                " Link "LIST"              0}              @{"   SHOW_FILEID         " Link "SHOW_FILEID" 0}\n       @{"   WORK                " Link "WORK"              0}              @{"   FILEID_TOP          " Link "FILEID_TOP" 0}\n       @{"   FILEID_END          " Link "FILEID_END"        0}              @{"   SCRIPT              " Link "SCRIPT" 0}\n       @{"   LHA                 " Link "LHA"               0}              @{"   LZX                 " Link "LZX" 0}\n       @{"   SKIP_TEST           " Link "SKIP_TEST"         0}              @{"   SKIP_ADD            " Link "SKIP_ADD" 0}\n       @{"   SKIP_REMOVE         " Link "SKIP_REMOVE"       0}              @{"   SMART_STRIP         " Link "SMART_STRIP" 0}\n       @{"   RAND_ADDY           " Link "RAND_ADDY"         0}              @{"   BRAIN_UPDATE        " Link "BRAIN_UPDATE" 0}\n       @{"   STRIP_FILEID        " Link "STRIP_FILEID"      0}              @{"   RANDOM_ADVERT       " Link "RANDOM_ADVERT" 0}\n       @{"   RANDOM_TOP_FILEID   " Link "RANDOM_TOP_FILEID" 0}              @{"   RANDOM_END_FILEID   " Link "RANDOM_END_FILEID" 0}\n\n@endnode\n\n@node "REMOVE" "Explanation of tooltype REMOVE"\n\n\n    This ToolType is required to enable LhA|LZX to Strip files.\n\n    LhA kills files from -> S:Lha.Kill\n\n    LZX kills files from -> S:Lzx.Kill\n\n    However, LZX lacks LhA''s "-i" command, and therefore I had to fix this\n    by myself. The routine I made is a 5 minutes hack and it''s far away\n    from fast. I therefore urge you to use a small Lzx.Kill banner file.\n\n    But, if you have a fast harddrive/controller I suppose you could use\n    a somewhat large banner list, but be sure to run LZX resident or from\n    RAM: to keep the LZX execution time lower.\n\n    Lets hope Data Compression Technologies implement the -i option =)\n\n@endnode\n\n@node "ADD" "Explanation of tooltype ADD"\n\n\n    This ToolType is required to enable LhA|LZX to Add files.\n\n    \n  LhA insert files from -> S:Lha.Add and must include files with full paths\n\n  LZX insert files from -> S:Lzx.Add and must include files with full paths\n\n@endnode\n\n@node "CHECK" "Explanation of tooltype CHECK"\n\n\n    This ToolType is required to enable LhA|LZX Test files integrity.\n\n@endnode\n\n\n\n@node "ISTRIP" "Explanation of tooltype ISTRIP"\n\n\n    This ToolType is required if you''d like to use IStrip before\n    Checker attempts to access archive.\n\n    Execution is: IStrip {filename}\n\n    Make sure IStrip is in current directory, C: or resident.\n\n    You can use IStrip and Checkers own Remove function at same time.\n\n@endnode\n\n\n@node "LIST" "Explanation of tooltype LIST"\n\n    This ToolType is required to enable LhA|LZX to List all files in an\n    archive after finished. \n\n    It suppresses realtime listing by writing the listing to RAM:\n    and showed afterwards to reduce typing time.\n\n@endnode\n\n\n@node "SHOW_FILEID" "Explanation of tooltype SHOW_FILEID"\n\n    This ToolType is required to enable LhA|LZX to show the ''File_id.diz''\n    if any is available.\n\n@endnode\n\n\n@node "WORK" "Explanation of tooltype WORK"\n\nWORK={Work Path}\n\n    This ToolType is required to make LhA|LZX run properly.\n\n    The general reason by this option is to eliminate the annoying\n    system message "Volume Ram Disk is Full"\n\n    @{b}*THIS TOOLTYPE MUST BE SET*@{ub}\n    \n@endnode\n\n\n@node "FILEID_TOP" "Explanation of tooltype FILEID_TOP"\n\nFILEID_TOP={TextString}\n\n    This ToolType is required to enable LhA|LZX manipulate ''File_id.diz''.\n    The text given will be added ABOVE the real description.\n\n@endnode\n\n\n@node "FILEID_END" "Explanation of tooltype FILEID_END"\n\n\nFILEID_END={TextString}\n\n    This ToolType is required to enable LhA|LZX manipulate ''File_id.diz''.\n    The text given will be added BELOW the real description.\n\n@endnode\n\n\n@node "SCRIPT" "Explanation of tooltype SCRIPT"\n\nSCRIPT={path+filename of script}\n\n    This ToolType is required to enable LhA|LZX run a scriptfile.\n    (Textfile protected with +s).\n\n    The batchfile will be executed before Checker.\n\n@endnode\n\n\n@node "LHA" "Explanation of tooltype LHA"\n\nLHA={Path to LhA including filename}\n\n    This ToolType is required to enable Checker to know where LhA is.\n\n    To use LhA resident, just use ''LHA'' without any path.\n        \n    @{b}*THIS TOOLTYPE MUST BE SET*@{ub}\n\n@endnode\n\n\n@node "LZX" "Explanation of tooltype LZX"\n\nLZX={Path to LZX including filename}\n\n    This ToolType is required to enable Checker to know where LZX is.\n\n    To use LZX resident, just use ''LZX'' without any path.\n        \n    @{b}*THIS TOOLTYPE MUST BE SET*@{ub}\n\n@endnode\n\n\n@node "SKIP_TEST" "Explanation of tooltype SKIP_TEST"\n\nSKIP_TEST={bytes}\n\n    This ToolType is required to enable LhA|LZX skip all Testing of an\n    archive if the filesize is larger than specified bytes.\n\n@endnode\n\n@node "SKIP_ADD" "Explanation of tooltype SKIP_ADD"\n\nSKIP_ADD={bytes}\n\n    This ToolType is required to enable LhA|LZX skip *ALL* adding to an\n    archive if the filesize is larger than specified bytes.\n\n@endnode\n\n@node "SKIP_REMOVE" "Explanation of tooltype SKIP_REMOVE"\n\nSKIP_REMOVE={bytes}\n\n    This ToolType is required to enable LhA|LZX skip *ALL* stripping to an\n    archive if the filesize is larger than specified bytes.\n\n@endnode\n\n@node "SMART_STRIP" "Explanation of tooltype SMART_STRIP"\n\nSMART_STRIP\n\n    This ToolType is required to enable the "intelligent strip mode".\n    This function is not really implemented just because of the simple\n    reason: I haven''t finished it yet.\n\n    It examines all files after the file ''file_id.diz'' and search\n    for often used strings in the file.\n\n           @{b}*** This requires more time than normal stripping ***@{ub}\n\n@endnode\n\n\n@node "RAND_ADDY" "Explanation of tooltype RAND_ADDY"\n\nRAND_ADDY={path+filename}\n\n    This ToolType is required to enable the "random adding".\n\n    Specify the path+filename and the file will be copied\n    to Ram Disk: and renamed to a new filename with random picked letters.\n\n@endnode\n\n\n@node "BRAIN_UPDATE" "Explanation of tooltype BRAIN_UPDATE"\n\nBRAIN_UPDATE\n\n    Any advert after the file_id.diz which passed the normal stripping\n    process BUT found by the intelligent stripping method will be\n    inserted in the "S:Lha|Lzx.Kill" to save time when next time occurred.\n\n@endnode\n\n@node "STRIP_FILEID" "Explanation of tooltype STRIP_FILEID"\n\nSTRIP_FILEID\n\n    This will make the Checker to examine the FILE_ID.DIZ and remove\n    any BBS advert line. \n    The lines is defined in ''S:FileId.strip''.\n\n    "?" wildcard is supported.\n\n    Note: Every line in Fileid.strip will be read and Checker will put a\n          "#?" infront and behind the string. Therefore an advert like:\n         \n          --------------------cut--------------------\n          [28.8]-÷ lEEChEd fRoM lOSt cARRIEr! ÷-[28.8]\n          --------------------cut--------------------\n       \n          will be removed simply by entering "LEECHED FROM" in Fileid.strip\n\n          Of course, you can include the whole string, but Checker doesn''t\n          actually need it.\n\n@endnode\n\n@node "RANDOM_ADVERT" Explanation of tooltype RANDOM_ADVERT"\n\nRANDOM_ADVERT=Number of adverts\n\n    By using this option, Checker will insert random named adverts.\n    By setting this tooltype, you decide how many to be inserted.\n\n    @{b} This requires RAND_ADDY tooltype. @{ub}\n    \n@endnode\n\n@node "RANDOM_TOP_FILEID" "Explanation of tooltype RANDOM_TOP_FILEID"\n\nRANDOM_TOP_FILEID=Number\n\n    This option makes it possible to insert random lines into file_id.diz.\n    If you set this tooltype to 3, Checker will rand between 1-3.\n\n    You would then need:  FILEID_TOP.1=Your advert line.\n                          FILEID_TOP.2=Your advert line.\n                          FILEID_TOP.3=Your advert line.\n\n    @{b} The line will appear in top of file_id.diz @{ub}\n\n@endnode\n\n@node "RANDOM_END_FILEID" "Explanation of tooltype RANDOM_END_FILEID"\n\nRANDOM_END_FILEID=Number\n\n    This option makes it possible to insert random lines into file_id.diz.\n    If you set this tooltype to 6, Checker will rand between 1-6.\n\n    You would then need:  FILEID_TOP.1=Your advert line.\n                          FILEID_TOP.2=Your advert line.\n                          FILEID_TOP.3=Your advert line.\n                          FILEID_TOP.4=Your advert line.\n                          FILEID_TOP.5=Your advert line.\n                          FILEID_TOP.6=Your advert line.\n\n\n    @{b} The line will appear at the end of file_id.diz @{ub}\n\n@endnode\n\n\n                                  @{" Main " link "Main" 0}\n@endnode\n\n@node "History" "Checker/History"\n============================================================================\n                                  @{b}History@{ub}\n============================================================================\n\n      Due to memory loss, all history earlier than V3.20 is gone! =)\n\n\n V3.51	Changes/Additions\n	- Forgot to update the bytes stripped with ISTRIP option.\n          Thanks to [DR. G/RAM JAM]\n	- Added options for skipping Add and Stripping if the archive is\n	  larger than a specified size. Just like the Skip_Size.\n	  By this; Skip testing changed option name from Skip_Size to\n	  Skip_Test.\n	- All lines in Fileid.strip will now have an "#?" before and after.\n	  Therefore by entering "LEECHED FROM" in Fileid.strip it will remove\n          *ALL* commercials which contains *ANY* "LEECHED FROM" within.\n\n V3.50  Changes/Additions - ßETA PUBLIC RELEASE -\n	- I''m now using the same routines for LHA and LZX which shrinked\n	  the sorcecode from 46,425 -> 25,373 bytes and the executable from\n          28,867 -> 17884 bytes.\n	- Now *EACH* function call to LHA|LZX uses the work path command\n	  to save some memory.\n          Thanks to [ODEN]\n\n V3.48	Changes/Additions\n	- Added the "?" wildcard usage in FILE_ID.DIZ stripping.\n  	  Thanks to [ZANOK]\n\n V3.47	Changes/Additions\n	- Fixed a bug in LZX adding.\n	- Fixed Checker to insert random choosed Banners into file_id.diz.\n	- Fixed Checker to insert more than only one random advert.\n\n V3.46	Changes/Additions\n	- Added a FILE_ID.DIZ stripper.\n	- Removed wildcards ability, because it caused too much troubles.\n\n V3.45	Changes/Additions\n	- Brain_Update now works for LZX archives.\n	- MAJOR bug in the ASL routine. If your checker wasn''t named\n 	  ''LhaChecker'' everything crashed. Fixed!\n\n V3.44	Changes/Additions\n	- Fixed LZX to strip files via a brainfile.\n  	  Due to this Banners.Add & Banners.Kill disappeared and shall\n  	  from now on be as followed: S:Lha.add\n	                              S:Lha.kill\n        	                      S:Lzx.add\n                	              S:Lzx.kill\n\n	- For every 20th file in the Lzx.kill, LZX must be executed.\n          Only insert the most commen advertisements in this banner.\n  	  Will fix this ASAP.\n\n V3.43	Changes/Additions\n	- Corrected the byte counting routine. The checker sometimes claimed\n          to have stripped and/or added 2861345 bytes or even -96 bytes.\n	- Fixed an error in SKIP SIZE for LZX archives.\n	- Stupid mistake made when deleting adverts through Smart_strip,\n          every advert it found was deleted 10 times, meaning LhA/LZX was\n          executed 10 times as well. Fixed!\n\n V3.42	Changes/Additions\n	- Added intelligent stripping for LZX archives.\n	- Many minor annoying bugs were removed.\n	- The option "STATS" has been removed and is now always used.\n        - LZX adverts are now using S:BANNERS.ADD instead of S:LZXADDYS/\n\n V3.40	Changes/Additions\n	- Added a brief intelligent stripping routine. It is far from ready\n 	  but is able to delete some random adverts.\n	- Adverts discovered by SMART_STRIP can now be inserted in the\n          brainfiles to make the stripping faster when/if same name occur.\n\n  Due to some unknown reason I made a major version jump to v3.4\n\n V3.25	Changes/Additions\n	- Added LZX compatibility, after great demand.\n	- Skipping integrity test on files larger than a certain file size\n          is now availble. Thanks to Zanok for this idea.\n	- Added a statistic view option. When Checker is done, a little\n	  report of BYTES TESTED, BYTES STRIPPED and BYTES ADDED will be\n          shown.\n\n V3.24	Changes/Additions\n	- Instead of listing, viewing files and FILE_ID.DIZ realtime I\n          choose to make all outputs in files, therefore showed much faster.\n\n V3.23	Changes/Additions\n	- Reduced some unnecessary stack usage.\n        - Added Multi/Single file selection via ASL requester.\n\n V3.22	Changes/Additions\n	- Fixed a bug in the FILE_ID.DIZ adding.\n\n V3.21	Changes/Additions\n	- Slight design change, just to make it look more pretty.\n\n V3.20	Changes/Additions\n	- Beta release to some friends.\n\n\n                                  @{" Main " link "Main" 0}\n@endnode\n\n@node "Wanted" "Checker/Needed..."\n============================================================================\n                                 @{b}Needed...@{ub}\n============================================================================\n\n     I''m in great need of more beta testers, ideas, moral support and\n           brainfile updating and WHATEVER you may come up with!\n\n  If you''d like to get in touch with me, please dial one of these boards:\n\n                            [ Interchange     ]\n                            [ Serpent Hill    ]\n\n                  Forward your mail to "fAktOR & tRANCE"\n\n                                    or\n\n             E-Mail: [email removed]\n                           FidoNet: 2:201/328.9\n\n                                  @{" Main " link "Main" 0}\n@endnode\n\n@node "Special Thanks" "Special Thanks"\n============================================================================\n                          @{b}Special Thanks@{ub}\n============================================================================\n\nThere are some people I want to thank for their support:\n\n    * Shade/TRSI for bug reports, ideas, beta testing and more.\n\n    * Zanok/IHS for bug reports, beta testing and ideas.\n\n    * Sirius for updating the brainfile.\n\n    * Ezco/PDY for beta testing.\n\n    * Sniper/Ins for plenty of design work (mostly in other projects).\n\n                                  @{" Main " link "Main" 0}\n@endnode\n','\n',char(10)),NULL,'auto-added',59799,5,0,NULL,NULL,'chkpr351','scan',1780048442);
INSERT INTO door_catalog VALUES('chs_op13','CHS_OP13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CHS_OP13.LHA',NULL,'XIM','OPERATOR PAGE 1.3  BY MR HYDE/CHRYSEIS',NULL,'MR','CHS',NULL,replace('OPERATOR PAGE 1.3  BY MR HYDE/CHRYSEIS\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 19:07:25  ON NODE: 1\n','\r',char(13)),'\n',char(10)),NULL,NULL,2776,1,0,NULL,NULL,NULL,'scan',1780048442);
INSERT INTO door_catalog VALUES('chtmet20','CHTMET20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CHTMET20.LHA','Chat-O-Meter','XIM','Chat-O-Meter',NULL,NULL,NULL,'.-\_  \/  _/   __/______\/___/-------------. | /   \/   \______  \_  \/  \_   mYSTIC!   | :/     \____/   _____/___    / /X dIVISION .',replace('  __/\  __________ _ ___  /\__              \n.-\_  \/  _/   __/______\/___/-------------.\n| /   \/   \______  \_  \/  \_   mYSTIC!   |\n:/     \____/   _____/___    / /X dIVISION .\n/_______\-\_____/--sTZ--l___/--------------:\n| KiLLraVeN/MYSTiC BRiNGS: CHAT-O-METER v2 |\n| *CREATES BULLETiN ABOUT YOUR CHAT-TiMES* :\n: o Cool Layout (StZ!) o Sysop Chat Top 10 |\n| o Hide chat & more   o User Statistics   :\n: o Conversion util to upgrade from v1.x!  |\n`------------------------------------------''\n','\n',char(10)),'Chat-O-Meter.Guide',replace('@DATABASE "Chat-O-Meter.GUiDE"\n@REMARK  .-------------------------------------------------------.\n@REMARK  | This document should be read with AmigaGuide (OS 2.x) |\n@REMARK  | or MultiView (OS 3.x) or any other guide reader. Tnx. |\n@REMARK  `-------------------------------------------------------''\n@REMARK  $VER: Chat-O-Meter 2.0.9\n@WIDTH 80\n@NODE MAIN "KiLLER Comment - MYSTiC 1994 - © 1994 KiLLraVeN/MYSTiC"\n                            Guide to Chat-O-Meter\n                 for Ami-Express 3.38+ Bulletin Board Systems\n\n                            Program version: 2.0.9\n               Compilation Date/Time: Sun Dec 25 14:00:09 1994\n\n                        © 1994/1995 by @{"KiLLraVeN/MYSTiC" link Contact}\n\n                   ... another fine MYSTiC /X production ...\n\n                       @{"       UPDATE iNFORMATiON!       " link WhatsNew}\n\n      @{" Welcome Sysop! " link WhatIs}    What is Chat-O-Meter?\n      @{" Features       " link Features}    What can it do?\n      @{" Installation   " link Install}    How to install Chat-O-Meter\n      @{" Conversion     " link Conversion}    How to convert your old 1.x bulletin to 2.x\n      @{" Example 1      " link BullExample}    Example output the bulletin of Chat-O-Meter\n      @{" Example 2      " link ExitChatExample}    Example output when you exit a chat\n      @{" History        " link History}    History of Chat-O-Meter\n      @{" Greetings      " link Greetings}    Greetings, messages and contact info\n@ENDNODE\n\n@NODE WhatIs "What is Chat-O-Meter - © KiLLraVeN/MYSTiC"\n                          - -----------------------.\n                         |  What Is Chat-O-Meter?  |\n                         `----------------------- -\n\n   Chat-O-Meter  is  a  small tool that keeps track of all your chats, in\n   particulair  the  length  of  all  your  chats  with users.  With this\n   information it is able to create a nice looking @{"bulletin" link BullExample} that displays\n   a Top Ten of all times.\n\n   Besides  that,  it  also saves the times of the chats per user. At the\n   end  of  every  chat,  the  user  gets  to  see  his  or  her personal\n   information such as the overall score and total number of chats he/she\n   was engaged in.\n\n   This  only  takes up a small amount of time and hardly any disk space.\n   The  creation of the bulletin only takes up about 1 sec (on a standard\n   machine,  it''s  even  quicker  on 020+ systems) and the file size of a\n   file that holds 400 users is about 3.5Kb.\n\n   Chat-O-Meter  also  is giftware, do with it what you want, but you may\n   not  sell  it.  Distribution on AmiNet is allowed, but distribution on\n   PD  series  is  forbidden  (I  don''t  like  people  making money of my\n   products).\n\n   Anyway,  this  version has been totally rewritten from scratch and now\n   has a cool logo made by Stezothetic, so enjoy it!\n\n                                                        @{"-KiLLraVeN/MYSTiC" link Contact}\n@ENDNODE\n\n@NODE WhatsNew "What''s New in version 2.0 - © KiLLraVeN/MYSTiC"\n                           - --------------------.\n                          |  New in version 2.0  |\n                          `-------------------- -\n\n   The  previous  version ( 1.2 ) was released over one year ago (October\n   1993)  and  to tell you the truth, the coding was lousy and it was not\n   that  sysop  friendly.   But  do  not  despair,  this version has been\n   totally rewritten (from scratch!) and is much smarter and has got some\n   nice new options.  Better forget all about the previous version :-)\n\n   It  has  to  be  said  that I would have never created this version if\n   Quartz  hadn''t  asked  for  it  AND if Stezothetic hadn''t made such an\n   awesome logo.  It seems people use my tools after all :-)\n\n   First  of  all,  the best improvement is that it is now able to detect\n   wether you started or ended a chat.  So if you were a previous user of\n   Chat-O-Meter,  the  times  of  deleting  the  old data file before you\n   started another chat are over :) Lost carriers are no problem anymore.\n\n   Another  *BIG* improvement is the @{"new layout" link BullExample}, done by Stezo (Stz).  It\n   now  has  got a really great logo and nice colours.  You''ll love it, I\n   do!  Many thanks to Stezothetic for creating the logo!\n\n   What  also  new is, is the fact that a record is kept of all chats per\n   user.   One  file is kept that contains all information about ALL your\n   chats ever (since you started to use CoM ofcoz) per user.  I will also\n   create  a  door/tool that creates a nice bulletin out of that one.  If\n   you  think  this  is  nonsense, you are able to turn it off so no data\n   file will be created.\n\n   The  previous  version also did not set the ENV:  variable of AMi-X to\n   the right value, so users that performed a ''who'' saw that the user you\n   were  chatting  with was ''using a door''.  This has been fixed.  But if\n   you  liked  that ''feature'' of Chat-O-Meter, it is still able to hide a\n   chat. Privacy above all (nope, there is no PGP function :) ).\n\n   That''s it.  I hope you''ll like it, it''s one of those nice little doors\n   that  makes  just  the  difference  between your board and your follow\n   sysops'' boards.\n@ENDNODE\n\n@NODE Features "Features of Chat-O-Meter - © KiLLraVeN/MYSTiC"\n                      - ------------------------------.\n                     |  Features of Chat-O-Meter 2.0  |\n                     `------------------------------ -\n\n   ­ Creates a bulletin wherever you want (configurable)\n\n   ­ Very nice/cool layout thanks to Stezothetic (Stz)\n\n   ­ Ability to hide a chat from other users\n\n   ­ Fast creation of data files and bulletin\n   \n   ­ Small data files (308 bytes and 2 bytes/user)\n   \n   ­ Keeps track of sysop chats, but also user chats. That is,\n     a record is kept per user with his/her personal total chat\n     time and total number of chats.\n     \n   ­ At the end of a chat, a small bulletin is shown stating the\n     latest statistics. See @{"example" link ExitChatExample}.\n     This is configurable (Quiet mode is available).\n     \n   ­ Configurable ''Show Bulletin [ Y/n ]'' when user has entered\n     the Chat-O-Meter Top Ten.\n     \n   ­ Configurable stripping of plural words ( 1 mIN instead of 1 mINS)\n\n   ­ Easy to use\n@ENDNODE\n\n@NODE ExitChatExample "Exit Chat Example - © KiLLraVeN/MYSTiC"\n\n   Every time you exit a chat, you will get to see this small bulletin.\n\n :                                                                         :\n-O-------------------------------------------------------------------------O-\n :  /X MYSTiC       Chat-O-Meter v2.0  by  KiLLraVeN/MYSTiC     /X MYSTiC  :\n ¡                                                                         .\n :  tHIS cHAT:  0:00:11 -O- oVERALL tIME: 0002:07:44 -O- cHAT #: 187       ¡\n .         yOUR oVERALL sCORE: 0000:12:46 -O- yOUR cHAT #: 132             :\n .                                                                         |\n :   sORRY dUDE, nO Chat-O-Meter tOP tIME tODAY, tRY aGAIN sOON, oKAY?!    :\n-O-------------------------------------------------------------------------O-\n :                                                                         :\n\n   However,   when   you   specify   that   you  don''t  want  a  userfile\n   (NO_USERFILE), you will get this as output:\n\n :                                                                         :\n-O-------------------------------------------------------------------------O-\n :  /X MYSTiC       Chat-O-Meter v2.0  by  KiLLraVeN/MYSTiC     /X MYSTiC  :\n ¡                                                                         .\n :  tHIS cHAT:  0:00:02 -O- oVERALL tIME: 0002:07:49 -O- cHAT #: 190       ¡\n .                                                                         |\n :   sORRY dUDE, nO Chat-O-Meter tOP tIME tODAY, tRY aGAIN sOON, oKAY?!    :\n-O-------------------------------------------------------------------------O-\n :                                                                         :\n\n@ENDNODE\n\n@NODE Install "Installation of Chat-O-Meter - © KiLLraVeN/MYSTiC"\n                      - -----------------------------.\n                     |  How to install Chat-O-Meter  |\n                     `----------------------------- -\n\n   First  of  all, you can put the executable (Chat-O-Meter) anywhere you\n   like.   The  data  files  will  be  created in that same directory.  I\n   suggest  you  put it in DOORS:Chat-O-Meter/ but hey, it''s up to you (I\n   just  hate  it  when people hard code a path in their program, haven''t\n   they heard of the PROGDIR:  assign?).\n\n   Secondly,  Chat-O-Meter  needs  to be started with an MCI command from\n   the  STARTCHAT.TXT  and  ENDCHAT.TXT  files  that can be found in your\n   BBS:NODEx/   directory.    Two   icons   have   been  supplied  called\n   `Chat_Start.info''  and  `Chat_End.info''.   I recommend you put them in\n   your  BBS:Commands/SYSCmd/  directory,  as  is  standard with commands\n   started with an MCI command.\n\n   For  those sysops who don''t know how to implement Chat-O-Meter in your\n   STARTCHAT.TXT  and  ENDCHAT.TXT,  make  sure the text files contain at\n   least the following lines:\n\n                 STARTCHAT.TXT           ENDCHAT.TXT\n                 -------------           -----------\n                 ~                       ~\n                 ~CC_CHAT_START          ~CC_CHAT_END\n\n   It  doesn''t  matter wether you''ve got a logo in those files.  Just put\n   the text in there somewhere.\n\n   Once you have copied the icons to your BBS:Commands/SYSCmd/ directory,\n   check out the following tooltypes:\n\n   Chat_Start.info\n   ---------------\n   STACK=50000          ; Keep it this high, everything is done on stack\n   There are no more tooltypes for this icon.\n   \n   Chat_End.info\n   -------------\n   CHAT_END             : This  is how Chat-O-Meter recognizes the end of\n                          a chat. Make sure it is in this icon!\n\n   BULLETIN=            : This  is where you can specify how the bulletin\n                          should be called and where it should be created\n                          (i.e. BULLETIN=BBS:Bulletins/Chat-O-Meter.TXT)\n\n   DONT_ASK             : Normally,  whenever  a user gets in the Top Ten\n                          of Chat-O-Meter,  he/she  will  be asked wether\n                          the  Chat-O-Meter  bulletin  should be shown to\n                          them. However, if you specify this tooltype, no\n                          questions  will  be  asked  and nothing will be\n                          shown.\n\n   DONT_TRUNC           : By  default  all plural ''s''-es will be removed.\n                          So  for  example:  1 hOURS  becomes 1 hOUR  and\n                          1 sECS  becomes  1 sEC.  However,  if you think\n                          that  ruins  the  bulletin (cosmetically),  you\n                          can  override  it  by specifying this tooltype.\n                          All plural ''s''-es will be left alone.\n\n   QUIET                : Whenever  a chat is ended,  a small bulletin is\n                          shown  with  the  latest  statistics about that\n                          chat.  However,  if  you do not want this to be\n                          shown,  specify this tooltype and the user will\n                          even know you are using Chat-O-Meter.  No,  not\n                          even a copyright message ;-)\n\n   NO_USERFILE          : This  version  of  Chat-O-Meter  creates a file\n                          that  contains  all  chat information about the\n                          users,   one  by  one.  So  Chat-O-Meter  knows\n                          from  every  user,  how long he/she has chatted\n                          and  how many times you have chatted with them.\n                          It  doesn''t  take  up  much space,  with around\n                          400  users  you will get a file of about 3.5KB.\n                          If  you  feel  this  is  useless or you have no\n                          need  for  this,  insert this tooltype and that\n                          file   will  not  be  created  plus  the  small\n                          bulletin at the end of a chat will be smaller.\n\n   That are all tooltypes for this moment.  When you are done setting the\n   tooltypes  you  are ready with the installation of Chat-O-Meter.  Have\n   fun and chat your head off!  :-)\n@ENDNODE\n\n@NODE BullExample "Bulletin Example Output - Design by Stezothetic!"\n\n   ASCII  never looks good in AmigaGuide or MultiView, but you''ll get the\n   idea anyway I hope.\n   \n   If  you  might wonder why there are multiple entries for one user, the\n   Chat-O-Meter  Top  Ten  is  sorted  by  the length of the chat, and it\n   doesn''t matter wether a user is present several times in it.\n   \n   This  is  not because I am to lazy to built in that check, but suppose\n   you have a chat of 5 hours with somebody.  The next time you chat with\n   him,  you  have a chat of 7 hours.  Does this mean I should just erase\n   that  5  hour  chat and mention the 7 hour chat?  I think not, that is\n   not  fair.   A  5  hour chat is just as cool as a 7 hour chat and they\n   both deserve to be mentioned.\n\n .                          _  __           /        __  _      ·          .\n-O-_____   ___.___  ___________ //\___   / ·   ______\  .        \ _      -O-\n :/  __/__/   |  ¬\/   _ ¬\____\/____/  · /   /  __ ¬\ -:---------\/-----. :\n_/   |   ¬\_  _    \_  _   \_  \/  ¬\_ / / /_/   \/   \_| >cHAT·O·mETER< | :\n\_____     /__|     /__|    /___     //_/ / \_____     /`----------------'' H\n-:---l____/---l____/---l___//\-l____/-\_\/-------l____/------ ---  --   -  ¡_\n H                       __/  \  ___  ___________  /\_________    _______  \/\n | .------------------.  \_    \/  ¬\/  __ ¬\____\/____/  __ ¬\___\____ ¬\_H\n ¡ :   ·/X mYSTIC!·   :  /     \/    \_ \____/__ \/  ¬\_  \____/__   \/  _/:\n :_`---------------- - _/       \_____/___     /__     /____     /___/    \_\n \/ -  -- --- ---------\_________/--Stz--\____/--l____/----\____/----\_____/-\n :                                                                         |\n !   o1. Muad''Dib             01 hOUR , 20 mINS aND 51 sECS  (22-dEC-94)   :\n |   o2. Muad''Dib             00 hOURS, 25 mINS aND 15 sECS  (22-dEC-94)   :\n O   o3. TyCooN/MYSTiC        00 hOURS, 03 mINS aND 04 sECS  (24-dEC-94)   ¡\n |   o4. TyCooN/MYSTiC        00 hOURS, 01 mIN  aND 51 sECS  (22-dEC-94)   O\n H   o5. KiLLRaVeN/MYSTIC     00 hOURS, 01 mIN  aND 22 sECS  (21-dEC-94)   |\n :   o6. TyCooN/MYSTiC        00 hOURS, 00 mINS aND 59 sECS  (24-dEC-94)   H\n H   o7. TyCooN/MYSTiC        00 hOURS, 00 mINS aND 51 sECS  (22-dEC-94)   :\n ¡   o8. KiLLRaVeN/MYSTIC     00 hOURS, 00 mINS aND 34 sECS  (21-dEC-94)   ·\n_:   o9. KiLLRaVeN/MYSTIC     00 hOURS, 00 mINS aND 32 sECS  (21-dEC-94)   :_\n\:   1o. KiLLRaVeN/MYSTIC     00 hOURS, 00 mINS aND 29 sECS  (22-dEC-94)   :/\n \                                                                         /\n :\        tOTAL # oF cHATS: 190         tOTAL cHAT tIME:    2:07:49      /:\n-O-\---------------------------------------------------------------------/-O-\n :  ·                                                                   ·  :\n\n           (Ghee, I chat a lot with myself don''t you think? :-) )\n\n      The design was done totally by Stezothetic, many thanks for that!\n@ENDNODE\n\n@NODE History "History of Chat-O-Meter - Amazing... :)"\n                  - -------------------------------------.\n                 |  History: Something that once was...  |\n                 `------------------------------------- -\n\n   22-Jan-95   1.0.1    Fixed CoM-Convert; it now reads the name of the\n                        user from the correct place.\n\n   04-Jan-95   1.0.0    Completed CoM-Convert and restyled it.\n\n   03-Jan-95   1.0.0    Created CoM-Convert.\n\n   25-Dec-94   2.0.9    Chat-O-Meter can also run in silent mode now.\n                        New tooltype: QUIET\n\n   25-Dec-94   2.0.8    Merry X-Mas :) Made some internal changes, removed\n                        the stack-check (smaller executable).\n\n   24-Dec-94   2.0.7    Found the bug that caused the strange resets.\n                        I adjusted the wrong variable... sigh... it\n                        should be fixed now.\n\n   24-Dec-94   2.0.6    Allocated memory for some structures by myself\n                        instead of allocating them on the stack. Hope\n                        to have fixed the strange guru''s.\n\n   24-Dec-94   2.0.5ß   Special version for Muad''Dib with DEBUG info.\n\n   24-Dec-94   2.0.5    Tried to fix a bug that caused strange resets on\n                        Muad''Dibs machine (040) and weird crashes on my\n                        own system (total freeze and I had to turn my\n                        computer off for at least one minute!).\n\n   24-Dec-94   2.0.4    Fixed a bug that caused the bulletin only the be\n                        updated in the event of a new entry in the Top\n                        Ten. The Total Chat Time was never updated.\n                        *Reported by Quartz*\n\n   23-Dec-94   2.0.3    Built in the User file, now a record is kept of\n                        every user. A new bulletin perhaps.\n                        New tooltype: NO_USERFILE\n                        \n                        Altered the output after the chat again, now also\n                        contains info about the user him/herself.\n\n   22-Dec-94   2.0.2    Altered the output a bit and made some minor\n                        internal changes that caused a smaller executable.\n\n   21-Dec-94   2.0.1    Altered the output after a chat.\n\n   21-Dec-94   2.0.0    Totally rewrote it from scratch:\n                        - END_CHAT tooltype fixes the problem with lost\n                          carriers and then starting a chat again causing\n                          the start of the chat being the end of a chat.\n                          (Never mind if you don''t get it, it''s fixed!)\n                        *Requested by Quartz*\n\n                        New layout from Stezothetic implemented.\n                        *Thanks to Stezothetic*\n\n   26-Oct-93   1.2      Output file is now sysop-configurable. Now you can\n                        have it saved anywhere you like!\n                        Released: 30-Oct-93\n\n   23-Oct-93   1.1      Implemented safety-procedure so when user drops\n                        carrier in chat the Chat-O-Top doesn''t get mixed up.\n                        Released at: 27-Oct-93\n\n   17-Oct-93   1.0      First release to friends.\n@ENDNODE\n\n@NODE Greetings "Greetings and thanks - © 1994/1995 KiLLraVeN/MYSTiC"\n                            - --------------------.\n                           |  Greetings & Thanks  |\n                           `-------------------- -\n\n   A *BIG* THANKS TO STEZOTHETIC (Stz) FOR CREATING THE DESiGN, THANKS MATE!\n\n   Also thanks to Quartz for stimulating me to create this version.\n\n                                      :\n                                     -O-\n                                      :\n\n   Muad''Dib       -  Finally 3 nodes kicking on 28k8!\n   \n   Quartz         -  Logos make me program :)\n   \n   Stezothetic    -  You''re in the army... nooohow...\n   \n   I-GO           -  Johnnies and Anitas zuigen!\n   \n   Wishbringer    -  Faces... (no, not faeces ;-) )\n   \n   Motive Power   -  War is a fucking tough game!\n   \n   bObO           -  We need to talk ( :) )\n   \n   Zed            -  I hope you like this tool mate.\n   \n   Undertaker     -  Your modules kick ass, nobody can beat you!\n   \n   Arcade         -  Some times are rough, some are tough...\n   \n   MYSTiC Members -  Love you all :-)\n   \n                       ... and everybody I forgot ...\n@ENDNODE\n\n@NODE Contact "How to get in touch with me - © KiLLraVeN/MYSTiC"\n                             - ------------------.\n                            |  Contacting me...  |\n                            `------------------ - \n\n       For FAST response (preferred) please contact me on Internet:\n\n                               [email removed]\n\n                    ( [email removed] -- backup )\n\n                       - - -- --- ------- --- -- - -\n\n                 I can be reached on the following boards:\n\n                       - - -- --- ------- --- -- - -\n\n                The Undiscovered       +31-2294-1442 (USR 28k8)\n                                       +31-2294-4442 (USR 28k8)\n                                       +31-2294-tRY! (USR 28k8)\n\n                Last Outpost           +31-72-201182 (USR 28k8)\n                                       +31-72-157682 (USR 28k8)\n\n         I know, you have to call The Netherlands for it, but it''s\n            the only boards I call on a frequent basis, sorry.\n\n                       - - -- --- ------- --- -- - -\n\n        You can also find me on IRC once in a while on the channels\n                   #amigascne, #amiga, #rave and #megawatt\n@ENDNODE\n\n@NODE Conversion "How to convert your old bulletin - © 1995 KiLLraVeN/MYSTiC"\n                           - ---------------------.\n                          |  Bulletin Conversion  |\n                          `--------------------- -\n\n   For  sysops  that  used  Chat-O-Meter  1.x, there is a special program\n   called  "CoM-Convert"  that allows you to convert your old bulletin to\n   the  new  data  file  that  Chat-O-Meter  2.0  uses.  If you are not a\n   previous user of Chat-O-Meter, you can skip this part.\n\n   To  convert  it,  simply  start  the  program  "CoM-Convert"  from the\n   directory  where  you  have Chat-O-Meter 2.0 installed.  The data file\n   will be created in the directory where you started "CoM-Convert".\n\n   Once  you  have  started the program, a file requester will pop up and\n   you  must select the old bulletin.  Press `OK'' and you will get to see\n   the names (plus additional info) from that bulletin.\n\n   After that, the program will exit (`Ready.'') and you can find the data\n   file  called  `Chat-O-Meter.Data''  in that same directory.  Move it if\n   you  have  to.  The new bulletin will not be created yet!  To do this,\n   you  have  to  start Chat-O-Meter 2.0 from /X (start and end a chat is\n   sufficient).\n\n   That''s it, easy a as a fiddle.\n\n   NOTE : To use this tool, you must have req-tools installed.\n\n   NOTE¹: There  is *NO* check whether the file you feed to "CoM-Convert"\n          really  is an old bulletin from 1.x.  You can even cheat if you\n          want to ;-)\n\n   NOTE²: To  all beta-testers, this conversion util takes in account any\n          old  `Chat-O-Meter.Data'' file.  That is, it doesn''t recalculate\n          a new Top-Ten (it simply converts the old one), but it does ADD\n          the  old  `Total Chat Time''  to the new time and that also goes\n          for the total number of chats.\n@ENDNODE\n','\n',char(10)),'{"STACK":"50000"}','auto-added',43265,4,0,NULL,NULL,'chtmet20','scan',1780048442);
INSERT INTO door_catalog VALUES('chtmtr20','CHTMTR20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CHTMTR20.LHA','Chat-O-Meter','XIM','Chat-O-Meter',NULL,NULL,NULL,'.-\_  \/  _/   __/______\/___/-------------. | /   \/   \______  \_  \/  \_   mYSTIC!   | :/     \____/   _____/___    / /X dIVISION .',replace('  __/\  __________ _ ___  /\__              \n.-\_  \/  _/   __/______\/___/-------------.\n| /   \/   \______  \_  \/  \_   mYSTIC!   |\n:/     \____/   _____/___    / /X dIVISION .\n/_______\-\_____/--sTZ--l___/--------------:\n| KiLLraVeN/MYSTiC BRiNGS: CHAT-O-METER v2 |\n| *CREATES BULLETiN ABOUT YOUR CHAT-TiMES* :\n: o Cool Layout (StZ!) o Sysop Chat Top 10 |\n| o Hide chat & more   o User Statistics   :\n: o Conversion util to upgrade from v1.x!  |\n`------------------------------------------''\n','\n',char(10)),'Chat-O-Meter.Guide',replace('@DATABASE "Chat-O-Meter.GUiDE"\n@REMARK  .-------------------------------------------------------.\n@REMARK  | This document should be read with AmigaGuide (OS 2.x) |\n@REMARK  | or MultiView (OS 3.x) or any other guide reader. Tnx. |\n@REMARK  `-------------------------------------------------------''\n@REMARK  $VER: Chat-O-Meter 2.0.9\n@WIDTH 80\n@NODE MAIN "KiLLER Comment - MYSTiC 1994 - © 1994 KiLLraVeN/MYSTiC"\n                            Guide to Chat-O-Meter\n                 for Ami-Express 3.38+ Bulletin Board Systems\n\n                            Program version: 2.0.9\n               Compilation Date/Time: Sun Dec 25 14:00:09 1994\n\n                        © 1994/1995 by @{"KiLLraVeN/MYSTiC" link Contact}\n\n                   ... another fine MYSTiC /X production ...\n\n                       @{"       UPDATE iNFORMATiON!       " link WhatsNew}\n\n      @{" Welcome Sysop! " link WhatIs}    What is Chat-O-Meter?\n      @{" Features       " link Features}    What can it do?\n      @{" Installation   " link Install}    How to install Chat-O-Meter\n      @{" Conversion     " link Conversion}    How to convert your old 1.x bulletin to 2.x\n      @{" Example 1      " link BullExample}    Example output the bulletin of Chat-O-Meter\n      @{" Example 2      " link ExitChatExample}    Example output when you exit a chat\n      @{" History        " link History}    History of Chat-O-Meter\n      @{" Greetings      " link Greetings}    Greetings, messages and contact info\n@ENDNODE\n\n@NODE WhatIs "What is Chat-O-Meter - © KiLLraVeN/MYSTiC"\n                          - -----------------------.\n                         |  What Is Chat-O-Meter?  |\n                         `----------------------- -\n\n   Chat-O-Meter  is  a  small tool that keeps track of all your chats, in\n   particulair  the  length  of  all  your  chats  with users.  With this\n   information it is able to create a nice looking @{"bulletin" link BullExample} that displays\n   a Top Ten of all times.\n\n   Besides  that,  it  also saves the times of the chats per user. At the\n   end  of  every  chat,  the  user  gets  to  see  his  or  her personal\n   information such as the overall score and total number of chats he/she\n   was engaged in.\n\n   This  only  takes up a small amount of time and hardly any disk space.\n   The  creation of the bulletin only takes up about 1 sec (on a standard\n   machine,  it''s  even  quicker  on 020+ systems) and the file size of a\n   file that holds 400 users is about 3.5Kb.\n\n   Chat-O-Meter  also  is giftware, do with it what you want, but you may\n   not  sell  it.  Distribution on AmiNet is allowed, but distribution on\n   PD  series  is  forbidden  (I  don''t  like  people  making money of my\n   products).\n\n   Anyway,  this  version has been totally rewritten from scratch and now\n   has a cool logo made by Stezothetic, so enjoy it!\n\n                                                        @{"-KiLLraVeN/MYSTiC" link Contact}\n@ENDNODE\n\n@NODE WhatsNew "What''s New in version 2.0 - © KiLLraVeN/MYSTiC"\n                           - --------------------.\n                          |  New in version 2.0  |\n                          `-------------------- -\n\n   The  previous  version ( 1.2 ) was released over one year ago (October\n   1993)  and  to tell you the truth, the coding was lousy and it was not\n   that  sysop  friendly.   But  do  not  despair,  this version has been\n   totally rewritten (from scratch!) and is much smarter and has got some\n   nice new options.  Better forget all about the previous version :-)\n\n   It  has  to  be  said  that I would have never created this version if\n   Quartz  hadn''t  asked  for  it  AND if Stezothetic hadn''t made such an\n   awesome logo.  It seems people use my tools after all :-)\n\n   First  of  all,  the best improvement is that it is now able to detect\n   wether you started or ended a chat.  So if you were a previous user of\n   Chat-O-Meter,  the  times  of  deleting  the  old data file before you\n   started another chat are over :) Lost carriers are no problem anymore.\n\n   Another  *BIG* improvement is the @{"new layout" link BullExample}, done by Stezo (Stz).  It\n   now  has  got a really great logo and nice colours.  You''ll love it, I\n   do!  Many thanks to Stezothetic for creating the logo!\n\n   What  also  new is, is the fact that a record is kept of all chats per\n   user.   One  file is kept that contains all information about ALL your\n   chats ever (since you started to use CoM ofcoz) per user.  I will also\n   create  a  door/tool that creates a nice bulletin out of that one.  If\n   you  think  this  is  nonsense, you are able to turn it off so no data\n   file will be created.\n\n   The  previous  version also did not set the ENV:  variable of AMi-X to\n   the right value, so users that performed a ''who'' saw that the user you\n   were  chatting  with was ''using a door''.  This has been fixed.  But if\n   you  liked  that ''feature'' of Chat-O-Meter, it is still able to hide a\n   chat. Privacy above all (nope, there is no PGP function :) ).\n\n   That''s it.  I hope you''ll like it, it''s one of those nice little doors\n   that  makes  just  the  difference  between your board and your follow\n   sysops'' boards.\n@ENDNODE\n\n@NODE Features "Features of Chat-O-Meter - © KiLLraVeN/MYSTiC"\n                      - ------------------------------.\n                     |  Features of Chat-O-Meter 2.0  |\n                     `------------------------------ -\n\n   ­ Creates a bulletin wherever you want (configurable)\n\n   ­ Very nice/cool layout thanks to Stezothetic (Stz)\n\n   ­ Ability to hide a chat from other users\n\n   ­ Fast creation of data files and bulletin\n   \n   ­ Small data files (308 bytes and 2 bytes/user)\n   \n   ­ Keeps track of sysop chats, but also user chats. That is,\n     a record is kept per user with his/her personal total chat\n     time and total number of chats.\n     \n   ­ At the end of a chat, a small bulletin is shown stating the\n     latest statistics. See @{"example" link ExitChatExample}.\n     This is configurable (Quiet mode is available).\n     \n   ­ Configurable ''Show Bulletin [ Y/n ]'' when user has entered\n     the Chat-O-Meter Top Ten.\n     \n   ­ Configurable stripping of plural words ( 1 mIN instead of 1 mINS)\n\n   ­ Easy to use\n@ENDNODE\n\n@NODE ExitChatExample "Exit Chat Example - © KiLLraVeN/MYSTiC"\n\n   Every time you exit a chat, you will get to see this small bulletin.\n\n :                                                                         :\n-O-------------------------------------------------------------------------O-\n :  /X MYSTiC       Chat-O-Meter v2.0  by  KiLLraVeN/MYSTiC     /X MYSTiC  :\n ¡                                                                         .\n :  tHIS cHAT:  0:00:11 -O- oVERALL tIME: 0002:07:44 -O- cHAT #: 187       ¡\n .         yOUR oVERALL sCORE: 0000:12:46 -O- yOUR cHAT #: 132             :\n .                                                                         |\n :   sORRY dUDE, nO Chat-O-Meter tOP tIME tODAY, tRY aGAIN sOON, oKAY?!    :\n-O-------------------------------------------------------------------------O-\n :                                                                         :\n\n   However,   when   you   specify   that   you  don''t  want  a  userfile\n   (NO_USERFILE), you will get this as output:\n\n :                                                                         :\n-O-------------------------------------------------------------------------O-\n :  /X MYSTiC       Chat-O-Meter v2.0  by  KiLLraVeN/MYSTiC     /X MYSTiC  :\n ¡                                                                         .\n :  tHIS cHAT:  0:00:02 -O- oVERALL tIME: 0002:07:49 -O- cHAT #: 190       ¡\n .                                                                         |\n :   sORRY dUDE, nO Chat-O-Meter tOP tIME tODAY, tRY aGAIN sOON, oKAY?!    :\n-O-------------------------------------------------------------------------O-\n :                                                                         :\n\n@ENDNODE\n\n@NODE Install "Installation of Chat-O-Meter - © KiLLraVeN/MYSTiC"\n                      - -----------------------------.\n                     |  How to install Chat-O-Meter  |\n                     `----------------------------- -\n\n   First  of  all, you can put the executable (Chat-O-Meter) anywhere you\n   like.   The  data  files  will  be  created in that same directory.  I\n   suggest  you  put it in DOORS:Chat-O-Meter/ but hey, it''s up to you (I\n   just  hate  it  when people hard code a path in their program, haven''t\n   they heard of the PROGDIR:  assign?).\n\n   Secondly,  Chat-O-Meter  needs  to be started with an MCI command from\n   the  STARTCHAT.TXT  and  ENDCHAT.TXT  files  that can be found in your\n   BBS:NODEx/   directory.    Two   icons   have   been  supplied  called\n   `Chat_Start.info''  and  `Chat_End.info''.   I recommend you put them in\n   your  BBS:Commands/SYSCmd/  directory,  as  is  standard with commands\n   started with an MCI command.\n\n   For  those sysops who don''t know how to implement Chat-O-Meter in your\n   STARTCHAT.TXT  and  ENDCHAT.TXT,  make  sure the text files contain at\n   least the following lines:\n\n                 STARTCHAT.TXT           ENDCHAT.TXT\n                 -------------           -----------\n                 ~                       ~\n                 ~CC_CHAT_START          ~CC_CHAT_END\n\n   It  doesn''t  matter wether you''ve got a logo in those files.  Just put\n   the text in there somewhere.\n\n   Once you have copied the icons to your BBS:Commands/SYSCmd/ directory,\n   check out the following tooltypes:\n\n   Chat_Start.info\n   ---------------\n   STACK=50000          ; Keep it this high, everything is done on stack\n   There are no more tooltypes for this icon.\n   \n   Chat_End.info\n   -------------\n   CHAT_END             : This  is how Chat-O-Meter recognizes the end of\n                          a chat. Make sure it is in this icon!\n\n   BULLETIN=            : This  is where you can specify how the bulletin\n                          should be called and where it should be created\n                          (i.e. BULLETIN=BBS:Bulletins/Chat-O-Meter.TXT)\n\n   DONT_ASK             : Normally,  whenever  a user gets in the Top Ten\n                          of Chat-O-Meter,  he/she  will  be asked wether\n                          the  Chat-O-Meter  bulletin  should be shown to\n                          them. However, if you specify this tooltype, no\n                          questions  will  be  asked  and nothing will be\n                          shown.\n\n   DONT_TRUNC           : By  default  all plural ''s''-es will be removed.\n                          So  for  example:  1 hOURS  becomes 1 hOUR  and\n                          1 sECS  becomes  1 sEC.  However,  if you think\n                          that  ruins  the  bulletin (cosmetically),  you\n                          can  override  it  by specifying this tooltype.\n                          All plural ''s''-es will be left alone.\n\n   QUIET                : Whenever  a chat is ended,  a small bulletin is\n                          shown  with  the  latest  statistics about that\n                          chat.  However,  if  you do not want this to be\n                          shown,  specify this tooltype and the user will\n                          even know you are using Chat-O-Meter.  No,  not\n                          even a copyright message ;-)\n\n   NO_USERFILE          : This  version  of  Chat-O-Meter  creates a file\n                          that  contains  all  chat information about the\n                          users,   one  by  one.  So  Chat-O-Meter  knows\n                          from  every  user,  how long he/she has chatted\n                          and  how many times you have chatted with them.\n                          It  doesn''t  take  up  much space,  with around\n                          400  users  you will get a file of about 3.5KB.\n                          If  you  feel  this  is  useless or you have no\n                          need  for  this,  insert this tooltype and that\n                          file   will  not  be  created  plus  the  small\n                          bulletin at the end of a chat will be smaller.\n\n   That are all tooltypes for this moment.  When you are done setting the\n   tooltypes  you  are ready with the installation of Chat-O-Meter.  Have\n   fun and chat your head off!  :-)\n@ENDNODE\n\n@NODE BullExample "Bulletin Example Output - Design by Stezothetic!"\n\n   ASCII  never looks good in AmigaGuide or MultiView, but you''ll get the\n   idea anyway I hope.\n   \n   If  you  might wonder why there are multiple entries for one user, the\n   Chat-O-Meter  Top  Ten  is  sorted  by  the length of the chat, and it\n   doesn''t matter wether a user is present several times in it.\n   \n   This  is  not because I am to lazy to built in that check, but suppose\n   you have a chat of 5 hours with somebody.  The next time you chat with\n   him,  you  have a chat of 7 hours.  Does this mean I should just erase\n   that  5  hour  chat and mention the 7 hour chat?  I think not, that is\n   not  fair.   A  5  hour chat is just as cool as a 7 hour chat and they\n   both deserve to be mentioned.\n\n .                          _  __           /        __  _      ·          .\n-O-_____   ___.___  ___________ //\___   / ·   ______\  .        \ _      -O-\n :/  __/__/   |  ¬\/   _ ¬\____\/____/  · /   /  __ ¬\ -:---------\/-----. :\n_/   |   ¬\_  _    \_  _   \_  \/  ¬\_ / / /_/   \/   \_| >cHAT·O·mETER< | :\n\_____     /__|     /__|    /___     //_/ / \_____     /`----------------'' H\n-:---l____/---l____/---l___//\-l____/-\_\/-------l____/------ ---  --   -  ¡_\n H                       __/  \  ___  ___________  /\_________    _______  \/\n | .------------------.  \_    \/  ¬\/  __ ¬\____\/____/  __ ¬\___\____ ¬\_H\n ¡ :   ·/X mYSTIC!·   :  /     \/    \_ \____/__ \/  ¬\_  \____/__   \/  _/:\n :_`---------------- - _/       \_____/___     /__     /____     /___/    \_\n \/ -  -- --- ---------\_________/--Stz--\____/--l____/----\____/----\_____/-\n :                                                                         |\n !   o1. Muad''Dib             01 hOUR , 20 mINS aND 51 sECS  (22-dEC-94)   :\n |   o2. Muad''Dib             00 hOURS, 25 mINS aND 15 sECS  (22-dEC-94)   :\n O   o3. TyCooN/MYSTiC        00 hOURS, 03 mINS aND 04 sECS  (24-dEC-94)   ¡\n |   o4. TyCooN/MYSTiC        00 hOURS, 01 mIN  aND 51 sECS  (22-dEC-94)   O\n H   o5. KiLLRaVeN/MYSTIC     00 hOURS, 01 mIN  aND 22 sECS  (21-dEC-94)   |\n :   o6. TyCooN/MYSTiC        00 hOURS, 00 mINS aND 59 sECS  (24-dEC-94)   H\n H   o7. TyCooN/MYSTiC        00 hOURS, 00 mINS aND 51 sECS  (22-dEC-94)   :\n ¡   o8. KiLLRaVeN/MYSTIC     00 hOURS, 00 mINS aND 34 sECS  (21-dEC-94)   ·\n_:   o9. KiLLRaVeN/MYSTIC     00 hOURS, 00 mINS aND 32 sECS  (21-dEC-94)   :_\n\:   1o. KiLLRaVeN/MYSTIC     00 hOURS, 00 mINS aND 29 sECS  (22-dEC-94)   :/\n \                                                                         /\n :\        tOTAL # oF cHATS: 190         tOTAL cHAT tIME:    2:07:49      /:\n-O-\---------------------------------------------------------------------/-O-\n :  ·                                                                   ·  :\n\n           (Ghee, I chat a lot with myself don''t you think? :-) )\n\n      The design was done totally by Stezothetic, many thanks for that!\n@ENDNODE\n\n@NODE History "History of Chat-O-Meter - Amazing... :)"\n                  - -------------------------------------.\n                 |  History: Something that once was...  |\n                 `------------------------------------- -\n\n   22-Jan-95   1.0.1    Fixed CoM-Convert; it now reads the name of the\n                        user from the correct place.\n\n   04-Jan-95   1.0.0    Completed CoM-Convert and restyled it.\n\n   03-Jan-95   1.0.0    Created CoM-Convert.\n\n   25-Dec-94   2.0.9    Chat-O-Meter can also run in silent mode now.\n                        New tooltype: QUIET\n\n   25-Dec-94   2.0.8    Merry X-Mas :) Made some internal changes, removed\n                        the stack-check (smaller executable).\n\n   24-Dec-94   2.0.7    Found the bug that caused the strange resets.\n                        I adjusted the wrong variable... sigh... it\n                        should be fixed now.\n\n   24-Dec-94   2.0.6    Allocated memory for some structures by myself\n                        instead of allocating them on the stack. Hope\n                        to have fixed the strange guru''s.\n\n   24-Dec-94   2.0.5ß   Special version for Muad''Dib with DEBUG info.\n\n   24-Dec-94   2.0.5    Tried to fix a bug that caused strange resets on\n                        Muad''Dibs machine (040) and weird crashes on my\n                        own system (total freeze and I had to turn my\n                        computer off for at least one minute!).\n\n   24-Dec-94   2.0.4    Fixed a bug that caused the bulletin only the be\n                        updated in the event of a new entry in the Top\n                        Ten. The Total Chat Time was never updated.\n                        *Reported by Quartz*\n\n   23-Dec-94   2.0.3    Built in the User file, now a record is kept of\n                        every user. A new bulletin perhaps.\n                        New tooltype: NO_USERFILE\n                        \n                        Altered the output after the chat again, now also\n                        contains info about the user him/herself.\n\n   22-Dec-94   2.0.2    Altered the output a bit and made some minor\n                        internal changes that caused a smaller executable.\n\n   21-Dec-94   2.0.1    Altered the output after a chat.\n\n   21-Dec-94   2.0.0    Totally rewrote it from scratch:\n                        - END_CHAT tooltype fixes the problem with lost\n                          carriers and then starting a chat again causing\n                          the start of the chat being the end of a chat.\n                          (Never mind if you don''t get it, it''s fixed!)\n                        *Requested by Quartz*\n\n                        New layout from Stezothetic implemented.\n                        *Thanks to Stezothetic*\n\n   26-Oct-93   1.2      Output file is now sysop-configurable. Now you can\n                        have it saved anywhere you like!\n                        Released: 30-Oct-93\n\n   23-Oct-93   1.1      Implemented safety-procedure so when user drops\n                        carrier in chat the Chat-O-Top doesn''t get mixed up.\n                        Released at: 27-Oct-93\n\n   17-Oct-93   1.0      First release to friends.\n@ENDNODE\n\n@NODE Greetings "Greetings and thanks - © 1994/1995 KiLLraVeN/MYSTiC"\n                            - --------------------.\n                           |  Greetings & Thanks  |\n                           `-------------------- -\n\n   A *BIG* THANKS TO STEZOTHETIC (Stz) FOR CREATING THE DESiGN, THANKS MATE!\n\n   Also thanks to Quartz for stimulating me to create this version.\n\n                                      :\n                                     -O-\n                                      :\n\n   Muad''Dib       -  Finally 3 nodes kicking on 28k8!\n   \n   Quartz         -  Logos make me program :)\n   \n   Stezothetic    -  You''re in the army... nooohow...\n   \n   I-GO           -  Johnnies and Anitas zuigen!\n   \n   Wishbringer    -  Faces... (no, not faeces ;-) )\n   \n   Motive Power   -  War is a fucking tough game!\n   \n   bObO           -  We need to talk ( :) )\n   \n   Zed            -  I hope you like this tool mate.\n   \n   Undertaker     -  Your modules kick ass, nobody can beat you!\n   \n   Arcade         -  Some times are rough, some are tough...\n   \n   MYSTiC Members -  Love you all :-)\n   \n                       ... and everybody I forgot ...\n@ENDNODE\n\n@NODE Contact "How to get in touch with me - © KiLLraVeN/MYSTiC"\n                             - ------------------.\n                            |  Contacting me...  |\n                            `------------------ - \n\n       For FAST response (preferred) please contact me on Internet:\n\n                               [email removed]\n\n                    ( [email removed] -- backup )\n\n                       - - -- --- ------- --- -- - -\n\n                 I can be reached on the following boards:\n\n                       - - -- --- ------- --- -- - -\n\n                The Undiscovered       +31-2294-1442 (USR 28k8)\n                                       +31-2294-4442 (USR 28k8)\n                                       +31-2294-tRY! (USR 28k8)\n\n                Last Outpost           +31-72-201182 (USR 28k8)\n                                       +31-72-157682 (USR 28k8)\n\n         I know, you have to call The Netherlands for it, but it''s\n            the only boards I call on a frequent basis, sorry.\n\n                       - - -- --- ------- --- -- - -\n\n        You can also find me on IRC once in a while on the channels\n                   #amigascne, #amiga, #rave and #megawatt\n@ENDNODE\n\n@NODE Conversion "How to convert your old bulletin - © 1995 KiLLraVeN/MYSTiC"\n                           - ---------------------.\n                          |  Bulletin Conversion  |\n                          `--------------------- -\n\n   For  sysops  that  used  Chat-O-Meter  1.x, there is a special program\n   called  "CoM-Convert"  that allows you to convert your old bulletin to\n   the  new  data  file  that  Chat-O-Meter  2.0  uses.  If you are not a\n   previous user of Chat-O-Meter, you can skip this part.\n\n   To  convert  it,  simply  start  the  program  "CoM-Convert"  from the\n   directory  where  you  have Chat-O-Meter 2.0 installed.  The data file\n   will be created in the directory where you started "CoM-Convert".\n\n   Once  you  have  started the program, a file requester will pop up and\n   you  must select the old bulletin.  Press `OK'' and you will get to see\n   the names (plus additional info) from that bulletin.\n\n   After that, the program will exit (`Ready.'') and you can find the data\n   file  called  `Chat-O-Meter.Data''  in that same directory.  Move it if\n   you  have  to.  The new bulletin will not be created yet!  To do this,\n   you  have  to  start Chat-O-Meter 2.0 from /X (start and end a chat is\n   sufficient).\n\n   That''s it, easy a as a fiddle.\n\n   NOTE : To use this tool, you must have req-tools installed.\n\n   NOTE¹: There  is *NO* check whether the file you feed to "CoM-Convert"\n          really  is an old bulletin from 1.x.  You can even cheat if you\n          want to ;-)\n\n   NOTE²: To  all beta-testers, this conversion util takes in account any\n          old  `Chat-O-Meter.Data'' file.  That is, it doesn''t recalculate\n          a new Top-Ten (it simply converts the old one), but it does ADD\n          the  old  `Total Chat Time''  to the new time and that also goes\n          for the total number of chats.\n@ENDNODE\n','\n',char(10)),'{"STACK":"50000"}','auto-added',43077,2,0,NULL,NULL,'chtmtr20','scan',1780048442);
INSERT INTO door_catalog VALUES('ck_ui107','CK-UI107.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CK-UI107.LHA','UserInfo','XIM','UserInfo',NULL,NULL,'CK','/__   \ ¬\ /__ _\ ¬\ /__    ¬\ /_ _ ¬\ \_/. ____/\\/._ ___/\\/. ____/\\_/. _/\ //  /\__\/// /  ./ //____ ./\/ //  /\/',replace('   ___/\___   __/\___   __/\___   __/\_\n  /__   \ ¬\ /__ _\ ¬\ /__    ¬\ /_ _ ¬\\n  \_/. ____/\\/._ ___/\\/. ____/\\_/. _/\\n   //  /\__\/// /  ./ //____ ./\/ //  /\/\n  /___/ /   /__/___/ //______/ / /___/ /\n  \___\/    \__\___\/ \______\/NL\___\/\n CrAnK HiT iT aGAin WiTh aNotHer oF hE''S\n   /X TooLS , UserInformation V1.07\n','\n',char(10)),'UserInformationV1.7.guide',replace('@DATABASE "DoorMenu.guide"\n\n@WIDTH 80\n@NODE MAIN "cRaNk PrEsEnTs"\n\n                          User Information V1.7 \n               written by CrAnK in Thu Jan 27 00:13:01 1994\n \n            @{"    Copyright Note    " LINK COPRIGHT} -1- @{"   Urheberechte    " LINK URHEBERECHT}\n            @{"    Product Info      " LINK Produkt } -2- @{"   Produkt Info''s  " LINK PRODUKT}\n            @{"    Installation      " LINK INSTALL } -3- @{"   Installation    " LINK INSTALLATION}\n            @{"    Bug Report        " LINK BUG     } -4- @{"   FehlerReporte   " LINK FEHLER}\n            @{"                    Some Hello''s               " LINK HIHO}\n\n\n@ENDNODE\n\n@NODE COPRIGHT\n@TITLE "Copyrighted"\n\n - AmiExpress is Copyrighted(?) by LightSpeed Technologies\n\n - MultView , AmigaGuide , is Copyrighted by C=\n\n - This Tool is Callware ,who installing my Doors CAN call me\n   i''m intresting which people are installing my Tools/Doors\n   +49 5723 74340 \n\n								@{"Main Menu" LINK MAIN}\n\n@ENDNODE\n\n@NODE URHEBERECHT\n@Urheberechte\n\n - AmiExpress ist Urheberechtlich geschützt von LightSpeedTechnologies(?)\n\n - MultiView , Amiga Guide , ist Urheberechtlich geschützt von Commodore\n\n - Dieses Programm ist Callware, wer dieses Programm Installier möchte\n   sich bitte bei der CHAOS LINE melden, weil es mich intressiert\n   welche Leute meine Programme Installieren ..\n\n								@{"Main Menu" LINK MAIN}\n\n@ENDNODE\n\n@NODE PRODUkT\n@TITLE "Product Informations"\n\n  This is a AmiExpress Door for Replacement the Standardt\n  AmiExpress Status Information .\n\n								@{"Main Menu" LINK MAIN}\n@ENDNODE\n\n@NODE INSTALL\n@TITLE "User Information V1.7 - Installation"\n\n * INSTALLATION *\n\n - Copy all file to BBS:Doors/<or where you like it>\n\n\n AE 3.xx Installation\n --------------------\n\n  - Copy Open.info to BBS:Commands/BBScmd/\n\n    Or add to S.info:\n\n      ACCESS=001\n      LOCATION=DOORS:UserInformation.x\n      MULTINODE=YES\n      PRIORITY=0\n			STACK=15000\n      TYPE=XIM\n\n AE 2.xx Installation & S-Express 0.35 (Command Version)\n --------------------\n	-----CUT HERE-------\n	*S        XM010DOORS:UserInformation.x\n  --------------------\n\n\n								@{"Main Menu" LINK MAIN}\n@ENDNODE\n\n@NODE INSTALLATION\n@TITLE "User Information - Installation"\n\n * INSTALLATION *\n\n - Kopieren Sie alle Files in folgenden Pfad \n\n   "BBS:DOORS/"\n\n   AE 3.xx Installation\n   ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n - Kopieren Sie das "S.info zu "BBS:COMMANDS/BBSCMD/"\n\n   Oder fügen Sie folgende Befehle in "S.info" ein\n\n      ACCESS=001\n      LOCATION=DOORS:UserInformation.x\n      MULTINODE=YES\n      PRIORITY=0\n			STACK=15000\n      TYPE=XIM\n\n AE 2.xx Installation & S-Express 0.35 (Kommando Version)\n --------------------\n\n -----CUT HERE-------\n *S        XM010DOORS:UserInformation.x\n --------------------\n\n								@{"Main Menu" LINK MAIN}\n@ENDNODE\n\n@NODE BUG\n@TITLE "Bug Reports"\n\n BUG REPORT & SUGGESTIONS\n ------------------------\n\n   It''s possible that a mistake will occur.... nobody is perfect.\n   If you have any suggestions or comments please leave a message\n   to the programmer or Sysop on the N.A.S.A World Headquarters\n   CHAOS LINE\n  \n   For Bug Reports or Suggestion''s call our BBS\n   and Login as \n\n   NAME : GAST\n   PW   : GAST\n\n     Chaos Line  +49-5723-74340  United Germany\n     ¯¯¯¯¯¯¯¯¯¯  ¯¯¯¯¯¯¯¯¯¯¯¯¯¯  ¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n								@{"Main Menu" LINK MAIN}\n@ENDNODE\n\n@NODE FEHLER\n@TITLE "Fehler Report"\n\n Fehler Reporte & Vorschläge\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n   Es ist möglich das Fehler passieren ... niemand ist perfekt.\n   Wenn Sie vorschläge oder Fehler Reporte zu unseren Tools haben\n   dann rufen sie unser Hauptquatier an und hinterlassen Sie eine\n   Nachricht zu denn Programmierer oder zu dem Sysop\n\n   Für Fehler Reporte oder verbesserungs vorschläge Logen\n   sie sich bitte als\n\n   NAME : GAST\n   PW   : GAST\n\n   in die BBS ein\n\n   ein weiterhin haben wir immer die neusten Fred Fish Disketten\n   und AmiExpress Utilities Online (Etwas Werbung muss ja sein)\n\n\n     Chaos Line  +49-5723-74340  United Germany\n     ¯¯¯¯¯¯¯¯¯¯  ¯¯¯¯¯¯¯¯¯¯¯¯¯¯  ¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n								@{"Main Menu" LINK MAIN}\n@ENDNODE\n\n@NODE HIHO\n@TITLE "THE GREETINGS"\n\n  Greetings must go to the followings guys\n\n  Dr.Dre     - Nice chats with you\n  ByteAndi   - File ID is cool but need some modifications\n  Empire     - Thx for your help with coding C\n  Oldman     - I hope the Private Message V1.0ß is now encrypting correct\n  Highlander - nice chats,and don''t drink and Trade\n  No Limit   - thx for Support\n  Flake      - Virus Workshop Rules\n  MCC J.     - for making the paint for UI 107\n  MCloud     - you are a nice guy ,great idea''s Ghost Chat is in work\n  Yeggman    - nice trading, better times will come soon\n  Jee        - no comment\n  Doc Whoo   - i catch you soon for a mega chat\n  bAsTaRd    - keep it cool baby\n  Big Boss   - ohh no New User Stop on Mirage (snief)\n  Sigma Seven- nice Message routine in S Express,i call you in some days\n  Nero       - Nice board in Sweden\n  Aquarius   - Fast Tools...\n  Flashlight - 298 User''s Deleted oh wooow , learn C\n  Outlaw     - Thanks for the fast help\n  Diabolika  - I see you soon on the CeBit ''94\n  Stefanie   - Thank you for Moral Support..\n\n	and simply all they i have forgotten here\n\n								@{"Main Menu" LINK MAIN}\n@ENDNODE\n','\n',char(10)),'{"ACCESS":"001","LOCATION":"DOORS:UserInformation.x","PRIORITY":"0","STACK":"15000","TYPE":"XIM"}','auto-added',13625,3,0,NULL,NULL,'ck_ui107','scan',1780048442);
