INSERT INTO door_catalog VALUES('cle_ce1o','CLE-CE1O.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CLE-CE1O.LHA','CheckEx','XIM','CheckEx',NULL,'SPEEDWOLF/CYCLONE!','CLE','/·__  / \/·/__ ·/|_\___ ¬\ __\_____/ /\_/  |¬\/\_ _/ |¬\/ |¬\/ /\/ \¬| \__)___/\ \  |  \/¬ |  |  \ | ·\ \/  / | ·/   ¬\  \',replace('     _____/\  ________ ___/\___/\_______\n    /·__  / \/·/__ ·/|_\___ ¬\ __\_____/\n/\_/  |¬\/\_ _/ |¬\/ |¬\/ /\/ \¬| \__)___/\\n   \  |  \/¬ |  |  \ | ·\ \/  / | ·/   ¬\  \\n    \__ ·/\__|\__ ·/____/_/__/__|_/___ ·/sW\n       \/        \/  ...presents...   \/\n  ·» CheckEx v1.O bY SPEEDWOLF/CYCLONE! «·\n · First to check .exe «·» Well Dezigned! ·\n','\n',char(10)),'CheckEx.DoC',replace('\n                                                      · · · ·········---+\n                  /\                          /\       /\         ···::::\n        _________/__\    ____________________/  \_____/ ·\____________·::\n       /         · / \  /   /      · /|\         ¬\·      \         ·/ ·:\n   ·  / :  _____  /.:.\/   / _____  /:|·\______    \ ____  \  ______/   :\n   · /.::  |   ¬\/.::     /  |    \/·:|__/·   /\  : \   |   \  ___)__   :\n   · \ ::  | .:: \__   __/:  | .:: \ ·|  \   /  \/::.\  | :  \__   : \  :\n   :  \ :    :::·/ ¬   |\::    :::./  | :.\  \· /·:· /  | ::·  /  ·::.\\n   :·  \____  : /\   · | \____  : /     ::.\  \/    /   |.:·  /    :: / ·\n   ::.  *¤°~\  /· \____|· ~°¤*\  /\________/_______/____l____/____\  /· :\n   :::..     \/    *¤°~~       \/  ~°¤*¤°~¯ ~°¤*¤°~ ~*¤° °¤*¤°¯°¤*¤\/sW\n   +--------------···········\n                              ...presents...\n\n                «·» CheckEx v1.O bY SPEEDWOLF/CYCLONE! «·»\n\n IntroDuction\n ------------\n\n Well there are Checkers for LHa,DMs,ZIp and so on...\n But where is a Checker for Executable Files ??? Yo that''s what''s missing!\n (Note: If there was a ExeChecker before i say sorrry but this tool is \n certainly better designed!) So enjoy this piece of good(?) coding!\n\n Installation\n ------------\n \n Copy the FCheck-Infos to `BBS:Fcheck/''....\n Infos for .EXE and .DEX (usually used with Trainers etc.) are included...\n Other Infos must be created by you.....(hard fo you? NOOOTTT!!!!)\n Then at least copy the contents of the Utils drawer to `BBS:Utils''...\n\n What''s left\n -----------\n Nothing''s left! If you have done what i worte above it will work fine.\n If it don''t do its work : Sell your Amiga and buy a GameBoy!\n\n\n Contact\n -------\n\n              To Get MoRe gReaT tOOlS oR 4 CoNtaCt CaLL tHiZ!\n                         ____\n       _ __ ____________/   /______________________________ __ _\n       \\\_\\______    /   /____  _____/ __   /  _____  __ \\_\\\\n        ¯    |    / __/   /    /___   \   \__/  ___/_/  |  /    ¯\n             ¦    .   \       /   /   /    \   /    /      \\n          _ _:________/______/\______/\_____\______/    |___\sW\n             :                                    /_____¦\n                              B · B · S                :\n                  \n   (+49) 0211                                           (+49) 0211\n     4792811         CooL cReW oF fRIENDLY pEOPLE         410412\n\n                        ...wORLD hEADQUARTER oF... \n\n                  _____/\  ________ ___/\___/\_______     \n                 /·__  / \/·/__ ·/|_\___ ¬\ __\_____/     \n             /\_/  |¬\/\_ _/ |¬\/ |¬\/ /\/ \¬| \__)___/\  \n                \  |  \/¬ |  |  \ | ·\ \/  / | ·/   ¬\  \/\n                 \__ ·/\__|\__ ·/____/_/__/__|_/___ ·/sW  \n                    \/        \/                   \/     \n   \n                        bE tHERE oR bE dEAD!\n\n       wE aRe LooKing For MoRe Members! JoIn thE tW¡RL¡NG PoWeR nOW!\n\n\n =-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n\n          ...or call this dude for legal swapping,joining etc...\n\n                 <- (+49) 02102 872012 an'' ask for Kai! ->\n\n\n                              ...bYe...bYe...\n                                ...SaYz...\n \n            sW/\___  /\__ -/\__ -/\__--/\_ -/\__ -/\__- /\_ --/\____\n          ---/ .___\/ __ \/ __ \/ __ \/   \/ / /\/ __ \/  /__/  ___/\n           -_\__   / ____/ /___/ /___/  / / / / / /_/ /  /  /  __/\n          - \ _ '' /__ /--\___ /\___ /\__ /____ /\___ /\___ /  /\n           --\/¯¯¯  \/ -- - \/-- -\/   \/ - -\/- - \/ -- \/¯\/\n','\n',char(10)),NULL,'auto-added',15742,1,0,NULL,NULL,'cle_ce1o','scan',1780048442);
INSERT INTO door_catalog VALUES('cle_cl12','CLE-CL12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CLE-CL12.LHA','CompareStripList','XIM','CompareStripList',NULL,'MiLLe/cLe!','CLE','/·__  / \/·/__ ·/|_\___ ¬\ __\_____/ /\_/  |¬\/\_ _/ |¬\/ |¬\/ /\/ \¬| \__)___/\ \  |  \/¬ |  |  \ | ·\ \/  / | ·/   ¬\  \/',replace('     _____/\  ________ ___/\___/\_______\n    /·__  / \/·/__ ·/|_\___ ¬\ __\_____/\n/\_/  |¬\/\_ _/ |¬\/ |¬\/ /\/ \¬| \__)___/\\n   \  |  \/¬ |  |  \ | ·\ \/  / | ·/   ¬\  \/\n    \__ ·/\__|\__ ·/____/_/__/__|_/___ ·/sW\n       \/        \/  ...presents...   \/\n  ·» CompareStripList v1.2 bY MiLLe/cLe! «·\n     · MaKeS oNe ouT oF 2 sTRiP-LiStS ·\n     · NoW cHeCkS FoR DouBLe-eNTRieS! ·\n','\n',char(10)),'CompareStripList.guide',replace('@node MAIN "COMPARE STRIP LIST v1.2 by MILLE/CYCLONE ©1994!"\n                  _____/\  ________ ___/\___/\_______\n                 /·__  / \/·/__ ·/|_\___ ¬\ __\_____/\n   ________  /\_/  |¬\/\_ _/ |¬\/ |¬\/ /\/ \¬| \__)___/\  __________\n           \/   \  |  \/¬ |  |  \ | ·\ \/  / | ·/   ¬\  \/\n                 \__ ·/\__|\__ ·/____/_/__/__|_/___ ·/sW\n                    \/        \/  ...presents...   \/\n   _______________________________________________________________________\n  |/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::|\n  |\::/\::/\::/\::/\::/\::/\::/\::/\::/\::/\::/\::/\::/\::/\::/\::/\::/\::|\n  | \/  \/  \/  \/  \/  \/  \/  \/  \/  \/  \/  \/  \/  \/  \/  \/  \/  \/|\n  | /\  /\  /\  /\  /\  /\  /\  /\  /\  /\  /\  /\  /\  /\  /\  /\  /\  /\|\n  |/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::|\n  |\::/\::/\::/\::/\:|¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n  | \/  \/  \/  \/  \|         @{"--> Compare Strip List v1.2 <--"Link Law}\n  | /\  /\  /\  /\  /|\n  |/::\/::\/::\/::\/ |           ...bY MILLE/CYCLONE! ©''94...\n  |\::/\::/\::/\::/\ |\n  | \/  \/  \/  \/  \|                @{"   IntroDuction   "Link Intro}\n  | /\  /\  /\  /\  /|                @{"      Usage!      "Link Usage}\n  |/::\/::\/::\/::\/:|                @{" !How to Contact! "Link Contact}\n  ¦\::/\::/\::/\::/\:¦                @{" History & UpDate "Link History}\n  : \/  \/  \/  \/  \:                \n  ·                  ·               \n@endnode\n@node Law\n----[ DoWNLoAD SoRTeR - THE CREDITZ!  ]---------------------------------------\n\n CoDe (v1.O) bY ............................................... MiLLe/cLe!\n aDDiTioNaL CoDe (v1.1) bY ................................ SPEEDWOLF/cLe!\n CoDe (v1.2) bY ............................................... Mille/cLe!\n iDea & ConCepT bY ........................... MiLLe/cLe! & SPEEDWOLF/cLe!\n\n@endnode\n@node "Intro"\n----[ IntroDuction ]-------------------------------------------------------\n\n `COMPARE STRIP LIST'' is a tool to compare two Strip-Files and add the\n missing BBS-Addies to the other Strip File.\n\n E.G.: You have a StripConfig for an LHA-Checker liek LHACheck from Calypso\n and a friend of yours comes along with his own Strip-Config. Now to expand\n your own config you surely want to know if your friend''s Config concsist of\n some Addies which you don''t know. So normally you have two choices...\n \n 1) Compare the Two Files on your own (What a hell of Work :( )\n\n 2) Do nothing!\n\n or...\n Use this tool and let it be done for you.....COOL,EH??\n\n@endnode\n@node "Usage"\n----[ uSaGe! ]-------------------------------------------------------------\n\n The usage of `COMPARE STRIP LIST'' is very simple....\n\n CompareStripList <OwnList> <NewList>\n\n Ownlist is the Config-File to which should be added the missing Addies...\n\n NewList is the Config-File to which the OnwList should be compared with.\n\n@endnode\n@node "Contact"\n\n              To Get MoRe gReaT tOOlS oR 4 CoNtaCt CaLL tHiZ!\n                         ____\n       _ __ ____________/   /______________________________ __ _\n       \\\_\\______    /   /____  _____/ __   /  _____  __ \\_\\\\n        ¯    |    / __/   /    /___   \   \__/  ___/_/  |  /    ¯\n             ¦    .   \       /   /   /    \   /    /      \\n          _ _:________/______/\______/\_____\______/    |___\sW\n             :                                    /_____¦\n                              B · B · S                :\n                  \n   (+49) 0211                                           (+49) 0211\n     4792811         CooL cReW oF fRIENDLY pEOPLE         410412\n\n                     ...wORLD hEADQUARTER oF... \n\n                  _____/\  ________ ___/\___/\_______     \n                 /·__  / \/·/__ ·/|_\___ ¬\ __\_____/     \n             /\_/  |¬\/\_ _/ |¬\/ |¬\/ /\/ \¬| \__)___/\  \n                \  |  \/¬ |  |  \ | ·\ \/  / | ·/   ¬\  \/\n                 \__ ·/\__|\__ ·/____/_/__/__|_/___ ·/sW  \n                    \/        \/                   \/     \n   \n                        bE tHERE oR bE dEAD!\n\n       wE aRe LooKing For MoRe Members! JoIn thE tW¡RL¡NG PoWeR nOW!\n@endnode\n@node "History"\n----[ HiSTORY ]-------------------------------------------------------------\n\n History-Table...\n\n v1.O - Not released.\n\n v1.1 - Added a new Feature which how many new Addies have been found in\n        the NewList...\n\n v1.2 - CompareStripList now checks if there are any double entries in\n        both lists.\n\n Note:  We''ve made a Speed-Test between CompareStripList v1.2 and \n        DSXF-Joiner V3.0 from Zytech/TEX.\n\n        We''ve compared a 13K-List with a 10K-List and this was the result:\n\n        DXSF-Joiner V3.0              1:08 mins.\n        CompareStripList v1.2         0:36 mins.\n\n        Choose your favourite! [:-)\n@endnode\n','\n',char(10)),NULL,'auto-added',9917,1,0,NULL,NULL,'cle_cl12','scan',1780048442);
INSERT INTO door_catalog VALUES('cle_dizp','CLE-DIZP.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CLE-DIZP.LHA',NULL,'XIM','DIZ-Ed',NULL,'pSYCHo/cLE','CLE','/·__  / \/·/__ ·/|_\___ ¬\ __\_____/·/X· /\_/  |¬\/\_ _/ |¬\/ |¬\/ /\/ \¬| \__)___/\ \  |  \/¬ |  |  \ | ·\ \/  / | ·/   ¬\  \/',replace('     _____/\  ________ ___/\___/\_______\n    /·__  / \/·/__ ·/|_\___ ¬\ __\_____/·/X·\n/\_/  |¬\/\_ _/ |¬\/ |¬\/ /\/ \¬| \__)___/\\n   \  |  \/¬ |  |  \ | ·\ \/  / | ·/   ¬\  \/\n·/X·\__ ·/\__|\__ ·/____/_/__/__|_/___ ·/sW\n       \/        \/  ...presents...   \/\n   ·» DIZ-Ed v2.0 Patched by pSYCHo/cLE «·\n   - No longer DIZED.NFO and Text-Adding -\n','\n',char(10)),'DIZ-Ed.guide',replace('@database DIZ-Ed V2.00\n******************************************************************************\n@NODE MAIN "DIZ-Ed Version 2.00 - Complete AmigaGuide Documentation"\n\n                             @{b}DIZ-Ed Version 2.oo@{ub}\n                      (C)1994 nocTurne deSign/Origin US\n                        The Definitive File-ID Editor\n         ------------------------------------------------------------\n         @{" OverView     " LINK OVERVIEW }...................DIZ-Ed General description\n         @{" Requirements " LINK REQ      }...............Neccessary program supplements\n         @{" Examples     " LINK EXAMPLES }............Examples of program''s application\n         @{" Usage        " LINK USAGE    }...................Complete usage information\n         @{" Future Plans " LINK FUTURE   }....................Intentions for the future\n         @{" Update Queue " LINK UPDATE   }.............List of changes between versions\n         @{" Credits      " LINK CREDITS  }................Where credit is due/Greetings\n         ------------------------------------------------------------\n                 v1.0x users should read ENTIRE documentation\n\n@ENDNODE\n******************************************************************************\n@NODE OVERVIEW "DIZ-Ed General Description..."\n\n DIZ-Ed  is an editor for File_ID texts within ZIP, LHA, and DMS archives,\n executable  files,  and  text  files.    Familiarity  with the concept of\n File_ID''s  is  assumed.    If  this  sounds  alien to you, "Wiz & Liz" by\n Psygnosis may be purchased at one of many resellers around the globe, and\n would likely be a more APPROPRIATE choice of software.\n\n DIZ-Ed,  (now  abbreviated  DE),  provides  a  clean  and efficient 44x12\n character  editing  interface,  and is rich in features and options.  For\n traders,  file dizcriptions may be EXTRACTED, EDITED, and REPACKED easily\n from  all  types of files.  For coders/crackers, file descriptions may be\n CREATED  and  packed  within  a  file  for distribution with a MINIMUM of\n effort.\n\n Continue  reading  to  learn  more  of  the  power  of DE.  Those already\n aquainted with a former incarnation of the program should read ALL of the\n documentation.  Like a whole integer to the version number, MUCH has been\n added to this version.\n\n@ENDNODE\n******************************************************************************\n@NODE REQ "DIZ-Ed Requirements..."\n\n                     DIZ-Ed v2.00 requires the following:\n                     ------------------------------------\n                     @{"  ReqTools.library    " LINK REQ1 } @{"  LHA      " LINK REQ3 }\n                     @{"  DPaint.font         " LINK REQ2 } @{"  ZIP      " LINK REQ4 }\n                     @{"  WorkBench 2.0+      " LINK REQ6 } @{"  UNZIP    " LINK REQ5 }\n                     ------------------------------------\n\n@ENDNODE\n******************************************************************************\n@NODE REQ1 "DIZ-Ed Requirement - ReqTools.library"\n\n   @{b}ReqTools.library:@{ub}\n\n   This library supplies the text and file requesters used by DE.\n   The latest version is included.\n\n@ENDNODE\n******************************************************************************\n@NODE REQ2 "DIZ-Ed Requirement - DPaint.font"\n\n   @{b}DPaint.font:@{ub}\n\n   This proportional font is used for the gadget texts.  The font is\n   coded  into  the software and will automatically be installed into\n   ''FONTS:'' if not found.\n\n@ENDNODE\n******************************************************************************\n@NODE REQ3 "DIZ-Ed Requirement - LHA"\n\n   @{b}LHA:@{ub}\n\n   This is the accepted Amiga file archiver.  It is only necessary\n   if you intend to load/edit file descriptions in LHA files.\n\n@ENDNODE\n******************************************************************************\n@NODE REQ4 "DIZ-Ed Requirement - ZIP"\n\n   @{b}ZIP:@{ub}\n\n   This is the accepted IBM file archiver.  It is only needed if you\n   intend to edit the descriptions of ZIP files.\n\n@ENDNODE\n******************************************************************************\n@NODE REQ5 "DIZ-Ed Requirement - UNZIP"\n\n   @{b}UNZIP:@{ub}\n\n   This is the accepted IBM unarchiver, only necessary if you are going\n   to LOAD the descriptions of ZIP files.\n\n@ENDNODE\n******************************************************************************\n@NODE REQ6 "DIZ-Ed Requirement - WorkBench 2.0+"\n\n   @{b}WorkBench 2.O+:@{ub}\n\n   This utility has been tested on WB2.1 and WB3.1.  As it uses OS2.0+\n   specific routines, you cannot be using WB1.3-.  Those using WB1.3\n   would likely be more comfortable using Micro-EMacs.\n\n@ENDNODE\n******************************************************************************\n@NODE USAGE "DIZ-Ed General Usage..."\n\n     -----------------------------------------------------------------\n     @{" Starting Up       " LINK STARTUP  }...............Command-line arguments and such\n     @{" The Edit Window   " LINK MAINWIN  }......Main window gadget and menu descriptions\n     @{" The Prefs Window  " LINK PREFSWIN }.........Preference window gadget descriptions\n     @{" The Logos Window  " LINK LOGOWIN  }.............................Logo window usage\n     @{" Making Logo Files " LINK LOGOS    }...........Description of the logo-file format\n     -----------------------------------------------------------------\n\n@ENDNODE\n******************************************************************************\n@NODE STARTUP "DIZ-Ed - Starting Up"\n\n DE  automatically  detaches  from the CLI it was run from, freeing it for\n further  use.  However the CLI may not be closed until DE is exitted,  as\n the console will be used for lha/zip error output. DE accepts an optional \n command-line argument:  The name of the file from which it should extract \n the description at start-up. \n\n By default, the edit-window will appear on the WorkBench screen.  However\n you  may,  in  the  preferences,  choose  that it appear on the frontmost\n screen  or  on a screen of its own.  Or you may choose that it not appear\n at all upon the next start-up, in a hidden state. \n\n If  you were a user of V1.0x DE2.0 will purge your old preferences file.\n\n@ENDNODE\n******************************************************************************\n@NODE MAINWIN "DIZ-Ed Edit Window Description..."\n\n                -------------------------------------------\n                @{" Usage   " LINK MAIN1}.......Edit Window Usage/Features\n                @{" Gadgets " LINK MAIN2}..............Button Descriptions\n                @{" Menus   " LINK MAIN3}................Menu Descriptions\n                -------------------------------------------\n\n@ENDNODE\n******************************************************************************\n@NODE MAIN1 "DIZ-Ed Edit Window Usage/Features..."\n\n The fundamental editing features of DE are quite similar to those of most\n editors.    Standard  keystrokes  result  in  characters  written  to the\n display.    Cursor  keys  result  in movement of the cursor.  Cursor keys\n accompanied by the shift key move the cursor to the extreme boundaries of\n the  display.    The  cursor  may  also be positioned using the mouse, by\n clicking  on  the desired location.  The DELETE key will pull the current\n character and all those proceeding it to the left.  Shift-BackSpace pulls\n everything after the cursor to the first column.  The DEL key will delete\n the  current  character  and pull the proceeding text to the left to take\n its place.\n\n To  access  the keyboard equivalents of the buttons on the right panel of\n the  edit  window,  the CONTROL key must be held.  (eg, CONTROL-C centers\n the current line.)\n\n The  status  bar,  located  at  the  bottom  of  the  window,  will relay\n information  not worthy of a whole requester, whether it be the program''s\n current  activity  or  a  minor error.  Upon startup, the status bar will\n also  be  the  source  of  mild  amusement, as it will display a randomly\n chosen phrase.\n\n Please  read  the  remainder  of  the  guide  to  learn completely of the\n capabilities of the edit window.\n\n@ENDNODE\n*******************************************************************************\n@NODE MAIN2 "DIZ-Ed Gadget Descriptions..."\n                              -------------------\n                               @{" Clear       (X)" LINK MAINGAD1}\n                               @{" Insert Line (I)" LINK MAINGAD2}\n                               @{" Delete Line (D)" LINK MAINGAD3}\n                               @{" Center Line (C)" LINK MAINGAD4}\n                               @{" Insert      (N)" LINK MAINGAD5}\n                               @{" CursorX     n/a" LINK MAINGAD6}\n                               @{" CursorY     n/a" LINK MAINGAD7}\n                              -------------------\n@ENDNODE\n*******************************************************************************\n@NODE MAINGAD1 "DIZ-Ed Gadget Description - CLEAR"\n\n         @{b}Gadget Name: @{ub}Clear\n @{b}Keyboard Equivalent: @{ub}<CTRL>-X\n\n\n @{b}Function:@{ub}\n\n This gadget simply clears the display.  However it will not clear any\n current file affiliation; this is done with the @{" New Project " LINK MENU1} menu item.\n\n@ENDNODE\n*******************************************************************************\n@NODE MAINGAD2 "DIZ-Ed Gadget Description - INSERT LINE"\n\n         @{b}Gadget Name: @{ub}Insert Line\n @{b}Keyboard Equivalent: @{ub}<CTRL>-I\n\n\n @{b}Function:@{ub}\n\n As  might  be ascertained, this button shifts everything ON and BELOW the\n current line down one row.  Contents of the last row will be lost.\n\n@ENDNODE\n*******************************************************************************\n@NODE MAINGAD3 "DIZ-Ed Gadget Description - DELETE LINE"\n\n         @{b}Gadget Name: @{ub}Delete Line\n @{b}Keyboard Equivalent: @{ub}<CTRL>-D\n\n\n @{b}Function:@{ub}\n\n This will delete the current line, causing all text below to shift up one\n line taking its place.\n\n@ENDNODE\n*******************************************************************************\n@NODE MAINGAD4 "DIZ-Ed Gadget Description - CENTER LINE"\n\n         @{b}Gadget Name: @{ub}Center Line\n @{b}Keyboard Equivalent: @{ub}<CTRL>-C\n\n\n @{b}Function:@{ub}\n\n This will center the contents of the current line.\n\n@ENDNODE\n*******************************************************************************\n@NODE MAINGAD5 "DIZ-Ed Gadget Description - INSERT"\n\n         @{b}Gadget Name: @{ub}Insert\n @{b}Keyboard Equivalent: @{ub}<CTRL>-I\n\n\n @{b}Function:@{ub}\n\n The  state  of this checkbox gadget determines whether characters entered\n will shift forward those following the cursor.  Those characters inserted\n past the right border will be lost.\n\n@ENDNODE\n*******************************************************************************\n@NODE MAINGAD6 "DIZ-Ed Gadget Description - CURSORX"\n\n         @{b}Gadget Name: @{ub}CursorX\n @{b}Keyboard Equivalent: @{ub}n/a\n\n\n @{b}Function:@{ub}\n\n This field displays the current column number of the cursor.\n\n@ENDNODE\n*******************************************************************************\n@NODE MAINGAD7 "DIZ-Ed Gadget Description - CURSORY"\n\n         @{b}Gadget Name: @{ub}CursorY\n @{b}Keyboard Equivalent: @{ub}n/a\n\n\n @{b}Function:@{ub}\n\n This field displays the current row number of the cursor.\n\n@ENDNODE\n*******************************************************************************\n@NODE MAIN3 "DIZ-Ed Menu Items..."\n\n  @{b}Project              Text Files                   ClipBoard@{ub}\n @{" New Project        " LINK MENU1} @{" Load Text File...         " LINK MENU10} @{" Edit Buffer->ClipBoard " LINK MENU14 }\n @{" Load DIZ from...   " LINK MENU2} @{" Save Text File...         " LINK MENU11} @{" ClipBoard->Edit Buffer " LINK MENU15 }\n @{" Save DIZ           " LINK MENU3} @{" Append to Logo File...    " LINK MENU12}\n @{" Save DIZ to...     " LINK MENU4} @{" ------------------------- " LINK DIV   }\n @{" ----------------   " LINK DIV  } @{" Transmit Thru Serial Port " LINK MENU13}\n @{" Preferences...     " LINK MENU5}\n @{" Config F-Keys...   " LINK MENU6} \n @{" Save Configuration " LINK MENU7}  \n @{" ----------------   " LINK DIV  }  @{b}Logo Operations@{ub}                                     \n @{" About...           " LINK MENU8} @{" Add Logo...        " LINK MENU16} \n @{" ----------------   " LINK DIV  } @{" ------------------ " LINK DIV   }  @{b}Active Logo File @{ub}\n @{" Hide               " LINK MENU9} @{" About Logo File... " LINK MENU17} @{" < Logo File 1 > " LINK MENU19}\n @{" Quit               " LINK MENUA} @{" Reload Logos       " LINK MENU18} @{" < Logo File 2 > " LINK MENU19}\n\n@ENDNODE\n*******************************************************************************\n@NODE DIV "Thwpppt..."\n\n This is just a menu-item divider, moron.\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU1 "DIZ-Ed Menu Item - NEW PROJECT"\n\n      @{b}Menu Item Name:@{ub} New Project\n @{b}Keyboard Equivalent:@{ub} <RAMIGA>-N\n\n\n @{b}Function:@{ub}\n\n Selecting  this  menu item will clear the edit-buffer as well as any file\n affiliation.\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU2 "DIZ-Ed Menu Item - LOAD DIZ FROM..."\n\n      @{b}Menu Item Name:@{ub} Load DIZ from...\n @{b}Keyboard Equivalent:@{ub} <RAMIGA>-L\n\n\n @{b}Function:@{ub}\n\n This  menu  item  extracts  the  description from a file.  After you have\n chosen  a  filename  from the resulting file-requester, DE will determine\n the  the file''s type and scan it for a description appropriately.  If the\n filetype  cannot be determined, you will be asked if you wish the file to\n be searched as thought it were a text file.\n\n After a successful scan, the edit-buffer''s contents should match the file\n description.    If  the  description  could  not be found, you will be so\n notified in the status bar, and the screen will be cleared.\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU3 "DIZ-Ed Menu Item - SAVE DIZ"\n\n      @{b}Menu Item Name:@{ub} Save DIZ\n @{b}Keyboard Equivalent:@{ub} <RAMIGA>-S\n\n\n @{b}Function:@{ub}\n\n This will save the contents of the edit-buffer to the File_ID of the file\n whose description was last loaded, even if the file hadn''t a description.\n If  no file has been loaded, or the ''New Project'' menu had been selected,\n a  file-requester  will  prompt  you for the name of the file to save the\n description to.  Reference the edit-window''s title bar for what file this\n menu item will affect.\n\n If  a file''s type cannot be determined, you will be asked if you wish the\n description implemented as though it were a text file.\n\n The date of the file will not be changed.  \n\n **  NOTE: REPACKING A DESCRIPTION WITHIN DMS FILES MAY TAKE A WHILE  **\n **        AND REQUIRES THAT YOU HAVE ENOUGH FREE SPACE ON YOUR HARD  **\n **        DRIVE FOR A DUPE OF DMS FILE.  (for buffering purposes)    **\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU4 "DIZ-Ed Menu Item - SAVE DIZ to..."\n\n      @{b}Menu Item Name:@{ub} Save DIZ to...\n @{b}Keyboard Equivalent:@{ub} <RAMIGA>-W\n\n\n @{b}Function:@{ub}\n\n This  item  allows  you to save the current description to a file of your\n choice, by means of a file requester.  After a file has been selected, it\n will have the description injected into it by appropriate means. \n\n If  a file''s type cannot be determined, you will be asked if you wish the\n description implemented as though it were a text file.\n\n The date of the file will not be changed.  \n\n **  NOTE: REPACKING A DESCRIPTION WITHIN DMS FILES MAY TAKE A WHILE  **\n **        AND REQUIRES THAT YOU HAVE ENOUGH FREE SPACE ON YOUR HARD  **\n **        DRIVE FOR A DUPE OF DMS FILE.  (for buffering purposes)    **\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU5 "DIZ-Ed Menu Item - PREFERENCES..."\n\n      @{b}Menu Item Name:@{ub} Preferences...\n @{b}Keyboard Equivalent:@{ub} <RAMIGA>-P\n\n\n @{b}Function:@{ub}\n\n This  will call up the preferences window so that you may configure DE to\n your liking.  See the {"Preferences Window" LINK PREFSWIN} section.\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU6 "DIZ-Ed Menu Item - CONFIG F-KEYS..."\n\n      @{b}Menu Item Name:@{ub} Config F-Keys...\n @{b}Keyboard Equivalent:@{ub} <RAMIGA>-F\n\n\n @{b}Function:@{ub}\n\n (Not  yet  implemented)  This  will summon the Function Key configuration\n window, so that macros may be assigned to each of the F-Keys. \n\n@ENDNODE\n*******************************************************************************\n@NODE MENU7 "DIZ-Ed Menu Item - SAVE CONFIGURATION"\n\n      @{b}Menu Item Name:@{ub} Save Configuration\n @{b}Keyboard Equivalent:@{ub} <RAMIGA>-I\n\n\n @{b}Function:@{ub}\n\n This  will  save  all  the  current  DE  preferences  to  data   files in\n "ENV:DIZ-Ed.prefs"  and "ENVARC:DIZ-Ed.prefs".  These will will be loaded\n upon  the next execution of DE.  The following settings will be preserved\n by means of these data files:\n\n  * All Preferences settings.\n  * The currently selected logo file.\n  * The state of the ''Insert'' checkbox on the edit-window.\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU8 "DIZ-Ed Menu Item - ABOUT..."\n\n      @{b}Menu Item Name:@{ub} About...\n @{b}Keyboard Equivalent:@{ub} <RAMIGA>-A\n\n\n @{b}Function:@{ub}\n\n This  will  simply  open  a  requester   relaying   the   version number,\n compilation  date,  credits,  and abbreviated description associated with\n DE.  Registration status will also be shown. \n\n@ENDNODE\n*******************************************************************************\n@NODE MENU9 "DIZ-Ed Menu Item - HIDE"\n\n      @{b}Menu Item Name:@{ub} Hide\n @{b}Keyboard Equivalent:@{ub} <RAMIGA>-H\n\n\n @{b}Function:@{ub}\n\n As DE is now a commodity, you may choose to hide the program window if it\n is  temporarily  not needed.  This menu item will have the same effect as\n pressing  the  current hotkey, closing the window but not terminating the\n program.    To  recall the program window, you may either hit the hotkey,\n use Commodore''s Exchange program, or run the program again.\n\n@ENDNODE\n*******************************************************************************\n@NODE MENUA "DIZ-Ed Menu Item - QUIT"\n\n      @{b}Menu Item Name:@{ub} Quit\n @{b}Keyboard Equivalent:@{ub} <RAMIGA>-Q\n\n\n @{b}Function:@{ub}\n\n This item simply terminates DE.\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU10 "DIZ-Ed Menu Item - LOAD TEXT FILE..."\n\n      @{b}Menu Item Name:@{ub} Load Text File...\n @{b}Keyboard Equivalent:@{ub} n/a\n\n\n @{b}Function:@{ub}\n\n This  item  allows  text files to be loaded into the edit buffer.  If the\n file  exceeds  a  width  of 44 or a height of 12, it will be truncated as\n necessary. \n\n@ENDNODE\n*******************************************************************************\n@NODE MENU11 "DIZ-Ed Menu Item - SAVE TEXT FILE..."\n\n      @{b}Menu Item Name:@{ub} Save Text File...\n @{b}Keyboard Equivalent:@{ub} n/a\n\n\n @{b}Function:@{ub}\n\n To  save the contents of the edit-buffer to a regular ASCII file, (NOT as\n the file_id of an ascii file), use this menu item.\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU12 "DIZ-Ed Menu Item - APPEND TO LOGO FILE..."\n\n      @{b}Menu Item Name:@{ub} Append to Logo File...\n @{b}Keyboard Equivalent:@{ub} n/a\n\n\n @{b}Function:@{ub}\n\n This  will  append  the contents of the edit-buffer to a ".logos" file of\n your  choice.  If the file you select does not exist, it will be created.\n You will be requested to assign a name to the text you are appending.  If\n all  goes well a new entry will be added to the logo file.  (Note: if you\n are  adding  an  entry  to the ACTIVE logo file, you must use the ''Reload\n Logos''  menu item for DE to reload the logo file, and realize the updated\n contents.)\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU13 "DIZ-Ed Menu Item - TRANSMIT THRU SERIAL PORT"\n\n      @{b}Menu Item Name:@{ub} Transmit Thru Serial Port\n @{b}Keyboard Equivalent:@{ub} <RAMIGA>-T\n\n\n @{b}Function:@{ub}\n\n This  will  send the contents of the edit-buffer through the serial port\n (using  the  device  and  unit  defined by the "Dev|Un" preference text).\n This  may  prove  useful when you have uploaded a file to a board with no\n file_id  recognition.  In this instance you can simply "Load DIZ from..."\n the file in question, and then transmit.  If a file you have uploaded has\n no  description,  you  may find it easier to create the description in DE\n and  then  transmit  it, rather than use the crude editor most /X file_id\n packages sport.\n\n (Please  note,  your  terminal program must be using shared access to the\n serial  port  for  DE to successfully transmit.  DE will send at whatever\n baud the program has initialized at.)\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU14 "DIZ-Ed Menu Item - EDIT BUFFER->CLIPBOARD"\n\n      @{b}Menu Item Name:@{ub} Edit Buffer->ClipBoard\n @{b}Keyboard Equivalent:@{ub} <RAMIGA>-C\n\n\n @{b}Function:@{ub}\n \n This  will  copy the current description to the clipboard, (unit 0).  The\n text  may  then be pasted into other applications, (or back into DE using\n the  "ClipBoard->Edit  Buffer" item.  If you make a mistake, the two menu\n items may be used to emulate an UNDO command.)\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU15 "DIZ-Ed Menu Item - CLIPBOARD->EDIT BUFFER"\n\n      @{b}Menu Item Name:@{ub} ClipBoard->Edit Buffer\n @{b}Keyboard Equivalent:@{ub} <RAMIGA>-V\n\n\n @{b}Function:@{ub}\n \n The  contents  of  the  clipboard  (unit  0)  will  be  pasted   into the\n edit-buffer with this item.  (If the "Shift Buffer" preference setting is\n active,  the  former  contents  of  the edit-buffer will be shifted down;\n otherwise they will be eliminated.)\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU16 "DIZ-Ed Menu Item - ADD LOGO..."\n\n      @{b}Menu Item Name:@{ub} Add Logo...\n @{b}Keyboard Equivalent:@{ub} <RAMIGA>-G\n\n\n @{b}Function:@{ub}\n\n This will open the Logo window, so that you may select an ascii logo from\n the currently Active Logo File.   See the @{" Logo Window " LINK LOGOWIN} section for more\n info.\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU17 "DIZ-Ed Menu Item - ABOUT LOGO FILE..."\n\n      @{b}Menu Item Name:@{ub} About Logo File...\n @{b}Keyboard Equivalent:@{ub} n/a\n\n\n @{b}Function:@{ub}\n\n If  the  currently  Active  Logo  File  has  an About text defined by the\n creator, a requester will appear containing this text.\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU18 "DIZ-Ed Menu Item - RELOAD LOGOS"\n\n      @{b}Menu Item Name:@{ub} Reload Logos\n @{b}Keyboard Equivalent:@{ub} n/a\n\n\n @{b}Function:@{ub}\n\n This  will simply reload the current logo directory as well as the Active\n Logo File.\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU19 "DIZ-Ed Menu Item - ACTIVE LOGO FILE MENU"\n\n      @{b}Menu Item Name:@{ub} < Logo File xx >\n @{b}Keyboard Equivalent:@{ub} n/a\n\n\n @{b}Function:@{ub}\n\n The  Active  Logo  File  menu  is  a  list  of  mutually  exclusive items\n representing  logo  files present in the logos directory, (defined by the\n the "Logos" preference text).  The contents of the menu are the filenames\n minus  the  ".logos"  extension.  Checking one of these items renders its\n respective  logo  file  active;  that  is,  the  functions  in  the ''Logo\n Operations'' menu will use that particular logo file.  Dig?\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSWIN "DIZ-Ed Preference Window Gadgets"\n                 --------------------------------------------\n                     Cursor Wrap @{"  " LINK PREFSGAD1}  \n                 Start Up Hidden @{"  " LINK PREFSGAD2}    Screen @{"              " LINK PREFSGAD6 }\n                    Shift Buffer @{"  " LINK PREFSGAD3}   Hot Key @{"              " LINK PREFSGAD7 }\n                 Dither Backdrop @{"  " LINK PREFSGAD4}  BackDrop @{"              " LINK PREFSGAD8 }\n                  Real-Time Logo @{"  " LINK PREFSGAD5}  Cursor Type @{"           " LINK PREFSGAD9 }\n               \n                 Downloads Path @{"                        " LINK PREFSGAD10} @{" ? " LINK PREFSGAD11}\n                 LogoFiles Path @{"                        " LINK PREFSGAD12} @{" ? " LINK PREFSGAD11}\n               \n                   Name @{"            " LINK PREFSGAD13}    LHA @{"           " LINK PREFSGAD16} @{" ? " LINK PREFSGAD11}\n                    Tag @{"            " LINK PREFSGAD14}    ZIP @{"           " LINK PREFSGAD17} @{" ? " LINK PREFSGAD11}\n                 Dev|Un @{"            " LINK PREFSGAD15}  UNZIP @{"           " LINK PREFSGAD18} @{" ? " LINK PREFSGAD11}\n                 --------------------------------------------\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD1 "DIZ-Ed Preference Window Gadget - CURSOR WRAP"\n\n         @{b}Gadget Name:@{ub} Cursor Wrap\n @{b}Keyboard Equivalent:@{ub} W\n\n\n @{b}Function:@{ub}\n\n The state of this checkmark gadget determines whether the cursor will\n wrap around the edit-window after it has passed a boundary.\n \n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD2 "DIZ-Ed Preference Window Gadget - START UP HIDDEN"\n\n         @{b}Gadget Name:@{ub} Start up Hidden\n @{b}Keyboard Equivalent:@{ub} S\n\n\n @{b}Function:@{ub}\n\n If this option is set and the configuration is saved, the edit-window\n will start in a hidden state the next time you run DE.  \n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD3 "DIZ-Ed Preference Window Gadget - SHIFT BUFFER"\n\n         @{b}Gadget Name:@{ub} Shift Buffer\n @{b}Keyboard Equivalent:@{ub} F\n\n\n @{b}Function:@{ub}\n\n If  this option is set, pastes from the clipboard and logo additions will\n not  purge  the former contents of the edit-buffer, but rather shift them\n down.\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD4 "DIZ-Ed Preference Window Gadget - DITHER BACKDROP"\n\n         @{b}Gadget Name:@{ub} Dither Backdrop\n @{b}Keyboard Equivalent:@{ub} T\n\n\n @{b}Function:@{ub}\n\n If this is set the background color will be dithered rather than solid. \n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD5 "DIZ-Ed Preference Window Gadget - REAL-TIME LOGO"\n\n         @{b}Gadget Name:@{ub} Real-Time Logo\n @{b}Keyboard Equivalent:@{ub} O\n\n\n @{b}Function:@{ub}\n\n If this is set, a temporary buffer will be set up so that you may see the\n logo  texts when you are browsing through them.  The former contents will\n be restored if you do not choose a logo.\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD6 "DIZ-Ed Preference Window Gadget - SCREEN"\n\n         @{b}Gadget Name:@{ub} Screen\n @{b}Keyboard Equivalent:@{ub} R\n\n\n @{b}Function:@{ub}\n\n This cycle gadget has three states and determines which screen DE\n will make its residence upon.\n\n * WorkBench - DE will open on the WorkBench screen.\n\n * Custom - DE will open a 4 color public screen of its own,\n            with the name "DIZ-Ed_PubScreen".\n\n * FrontMost - DE will open on whichever screen the active window\n               is on.  Using the hot-key you can easily make DE\n               appear on your terminal program''s screen, or wherever\n               you so desire.  DE will adapt to the screen it\n               resides on.\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD7 "DIZ-Ed Preference Window Gadget - HOT KEY"\n\n         @{b}Gadget Name:@{ub} Hot Key\n @{b}Keyboard Equivalent:@{ub} H\n\n\n @{b}Function:@{ub}\n\n If  the key sequence here is pressed, DE''s visible state will be toggled.\n (For  instance, if the key-sequence is the default "LCOMMAND d", pressing\n Left-Amiga  d  will  cause  the window to disappear or reappear.) Consult\n some manual or something to learn the key names.\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD8 "DIZ-Ed Preference Window Gadget - BACKDROP"\n\n         @{b}Gadget Name:@{ub} BackDrop\n @{b}Keyboard Equivalent:@{ub} B\n\n\n @{b}Function:@{ub}\n\n This is merely an aesthetic option, which lets you define which color\n the empty parts of windows should assume.\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD9 "DIZ-Ed Preference Window Gadget - CURSOR TYPE"\n\n         @{b}Gadget Name:@{ub} Cursor Type\n @{b}Keyboard Equivalent:@{ub} Y\n\n\n @{b}Function:@{ub}\n\n Another aesthetic option, this slider will determine what type of\n complementing cursor you want.\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD10 "DIZ-Ed Preference Window Gadget - DOWNLOADS PATH"\n\n         @{b}Gadget Name:@{ub} Downloads Path\n @{b}Keyboard Equivalent:@{ub} D\n\n\n @{b}Function:@{ub}\n\n The path listed here will be used by default in the file requesters\n for loading and saving descriptions.\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD12 "DIZ-Ed Preference Window Gadget - LOGOFILES PATH"\n\n         @{b}Gadget Name:@{ub} LogoFiles Path\n @{b}Keyboard Equivalent:@{ub} P\n\n\n @{b}Function:@{ub}\n\n The path listed here is where DE will look to fetch logo files.\n \n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD13 "DIZ-Ed Preference Window Gadget - NAME"\n\n         @{b}Gadget Name:@{ub} Name\n @{b}Keyboard Equivalent:@{ub} N\n\n\n @{b}Function:@{ub}\n\n Put your name here if you want.\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD14 "DIZ-Ed Preference Window Gadget - TAG"\n\n         @{b}Gadget Name:@{ub} Tag\n @{b}Keyboard Equivalent:@{ub} G\n\n\n @{b}Function:@{ub}\n\n Your 44 character sent-by line should be pasted here.  It will be\n sent with the transmit option if it exists.\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD15 "DIZ-Ed Preference Window Gadget - DEV|UN"\n\n         @{b}Gadget Name:@{ub} Dev|Un\n @{b}Keyboard Equivalent:@{ub} V\n\n\n @{b}Function:@{ub}\n\nThis  string  contains  the  device  and  unit that will be used with the\n"Transmit Thru Serial Port" function.  The default text "serial.device|0"\nwill  use  the  serial  device  unit  0,  and should be suitable for most\napplications.  (Note the device and unit number are separated with a ''|'')\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD16 "DIZ-Ed Preference Window Gadget - LHA"\n\n         @{b}Gadget Name:@{ub} LHA\n @{b}Keyboard Equivalent:@{ub} A\n\n\n @{b}Function:@{ub}\n \n This text here should be the path and filename of your LHA executable.\n The default is "LHA".\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD17 "DIZ-Ed Preference Window Gadget - ZIP"\n\n         @{b}Gadget Name:@{ub} ZIP\n @{b}Keyboard Equivalent:@{ub} Z\n\n\n @{b}Function:@{ub}\n\n The text here should be the path and filename of your ZIP executable.\n The default is "LHA".\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD18 "DIZ-Ed Preference Window Gadget - UNZIP"\n\n         @{b}Gadget Name:@{ub} UNZIP\n @{b}Keyboard Equivalent:@{ub} I\n\n\n @{b}Function:@{ub}\n\n The text here should be the path and filename of your UNZIP executable.\n The default is "UNZIP".\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD11 "DIZ-Ed Preference Window Gadget - <File Requester Thingy>"\n\n         @{b}Gadget Name:@{ub} <File Requester Thingy> (FRT)\n @{b}Keyboard Equivalent:@{ub} 1-5\n\n\n @{b}Function:@{ub}\n\n This  button  allows  you to select the contents of its accompanying text\n gadget  with  a  file  requester.  The keyboard equivalent is the numeric\n equivalent  of  its  vertical  position.    The  "Downloads Path" FRT  is\n selected by pressing ''1'', while the "UNZIP" FRT is selected with ''5''.\n\n@ENDNODE\n******************************************************************************\n@NODE EXAMPLES "DIZ-Ed Usage Examples..."\n _________________________________________________________________________\n                                                                          \n OK,  so  you''ve  downloaded the latest World Charts, but some board put a\n advert  in  the DIZcription.  So, you select the "Load..." gadget, select\n "HLM-WCxx.dms"  from  the  file-requester, click the cursor onto the line\n with  the  advert,  and  hit  the "Delete Line" gadget, (or <CTRL>-D; all\n keyboard  equivalents  must  be accompanied by a CTRL).  Selecting "Save"\n will save the new description back to the archive.\n _________________________________________________________________________\n\n OK, so you''ve just finished fixing Blood Money for AGA.  You''ve packed it\n in DMS format, and now you load up DE and select "Tango" from the "Active\n Logo File" menu.  After hitting "Right-Amiga G", (equivalent for the "Add\n Logo"  menu  item),  a  list  of group logos from Tango will appear.  You\n press  "Right-Amiga  T" to jump to the logos beginning with ''T'', and then\n double-click  your  group''s  logo, "Throbbing Grissle".  After adding the\n traditional  "Presents"  line,  you  select  "Save  As..."  and  save the\n description to your archive.  \n _________________________________________________________________________\n \n So  you  uploaded  a  file  to a board from the Dark Ages with no FILE_ID\n support,  and  its  asking you to describe this file.  So you use "DIZ-ED\n <filename>" from the cli and then hit "Right-Amiga T" to send it thru the\n serial port.\n _________________________________________________________________________\n \n OK, so you''re a cool ASCII artist and you wanna create some Ami-X listing\n compatible  logos.   So you simply draw your logo, select "Append to Logo\n File", enter the name of the logo file to create/append the entry to, and\n then enter the name of the logo you''ve drawn.  Or you may simply save the\n picture  as  a  regular text file, (selecting "Save Text File..."), to be\n loaded later.\n  _________________________________________________________________________\n\n@ENDNODE\n****************************************************************************\n@NODE LOGOWIN "DIZ-Ed Logo Window Description..."\n\n The logos window is composed of a list of logos from the currently active\n text  file,  and the traditional "Use" and "Cancel" gadgets.  In addition\n to  manually  scrolling  throught the list with the slider, there are now\n other means of getting to the logo you want.\n\n * Up & Down Keys - One entry up or down.\n                  - When accompanied by SHIFT, page up or page down.\n                  - With CONTROL, extreme top or extreme bottom.\n\n * Right Amiga @ - Where @ is a letter from the alphabet you want\n                   to jump to.  (example: <RAMIGA>-O jumps to the\n                   to the logos beginning with O, [eg ORIGIN:])\n \n * Return and ''U'' - Uses the currently selected logo.\n\n * ESC and ''C'' - Cancels logo window\n\n If  the  preferences  setting  "Real-Time Logos" is active, as you scroll\n through  logos the edit-buffer will reflect what the selected entry looks\n like. \n\n If  you  are  running  OS3.0+  the  selected  entry  will be highlighted;\n otherwise there will be the drab 2.0 text display gadget with the current\n entry''s name.\n\n If  you  double-click,  hit  return, or "Use" a logo, the contents of the\n edit-buffer  will  be  wiped  to  make  way  for the logo.  If the "Shift\n Buffer" prefs option is on the contents will be shifted down. \n\n@ENDNODE\n******************************************************************************\n@NODE LOGOS "DIZ-Ed Logos..."\n\n A  DE  logo  file  contains  text  logos  with  special  commands that DE\n recognizes  to differentiate between the entries.  It is required to have\n the extension ".logos" in the filename for it to be recognized by DE.\n \n The  beginning of a logo entry is denoted by a @LOGO immediately followed\n by  the  name  of  the logo in quotes.  Of course, these don''t have to be\n logos;  they  could  be  pictures or commonly used texts, or whatever you\n decide when you create your own entries.\n \n At  the end of each logo entry, an @ENDLOGO command should be placed.  Of\n course,  any  comments  or  notes  may  be  placed in regions between the\n entries.\n \n About  texts may now be implemented using @ABOUT to signify the beginning\n of  the  section and @ENDABOUT at the end.  This text should typically be\n under  60 chars wide  and 10 tall.   Note the text will be AUTO CENTERED, \n so keep it left justified.  \n \n Please  reference the included logo-texts to get a better feel for making\n these files.\n \n@ENDNODE\n******************************************************************************\n@NODE FUTURE "DIZ-Ed Foresight..."\n\n Future plans for implementation:\n\n    * Faster DMS save routine\n    * F-Key macros\n    * Naked ladies\n\n@ENDNODE\n******************************************************************************\n@NODE UPDATE "DIZ-Ed Update List..."\n\n @{b}Changes from V1.01 to V2.00:@{ub}\n \n  · Changed a pixel in the icon.  :)\n \n\n @{b}Changes from V1.00 to V1.01:@{ub}\n\n  · Fixed two problems with LHA adding.  In some instances, DIZ-ED thought\n    some LHA files were TEXT FILES!  You can call me Mr. Incompetant. Many\n    thanks to Aquarius/OTL for pointing this out.\n\n    Also, if you tried loading an LHA file which had no dizcription, the\n    file would be LOCKED, and could not be written to.  Incompetance is\n    my middle name.  Thanks to Outlaw/(Uzi Suicide BBS) for pointing this\n    one out.\n\n  · Fixed the copyright year; some parts said 1993!  I''m a year behind in\n    competance TOO!\n\n  · Repaired some enforcer hits.\n\n@ENDNODE\n******************************************************************************\n@NODE CREDITS "DIZ-Ed Credits..."\n\n         This program was coded by nocTurne (deSign)/Origin US.\n                      Thanks to the following people:\n\n           Remo/MST - Executable and DMS description adding routines.\n       Aquarius/OTL - Intensive testing and suggestions.\n          Dan Silva - Dpaint font.\n          Tango/OGN - Nice logo file/OGN initiation.  Yank THIS.\n            M.BiSON - Thanks for use of your board\n         Highlander - Thx for testing, will use the ascii when I \n                      find a place for it.\n             D-Siya - Thanks for finding that text thing.\n        Blind Melon - Musical support\n\n                           -----------------\n\n                To contact me, call my new tek-support HQ:\n\n       DOMiNO EFFECT - 2 NODES @ 28.8K - A4000/040 40Mhz - 3.3 GIGZ\n              +1.503.758.0019 - New User Password: twinturbo\n\n             or my internet address: "[email removed]"\n\n     PLEASE yell to one of the above places if you encounter any bugs\n      so that I may fix them in the next release.  Enjoy... noC out!\n@ENDNODE\n******************************************************************************\n                    What the fuck are you looking at??','\n',char(10)),NULL,'auto-added',94130,4,0,NULL,NULL,'cle_dizp','scan',1780048442);
INSERT INTO door_catalog VALUES('cle_ds1o','CLE-DS1O.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CLE-DS1O.LHA',NULL,'XIM','DL-SoRTeR.eXe',NULL,'SPEEDWOLF/cLe!','CLE','/·__  / \/·/__ ·/|_\___ ¬\ __\_____/·/X· /\_/  |¬\/\_ _/ |¬\/ |¬\/ /\/ \¬| \__)___/\ \  |  \/¬ |  |  \ | ·\ \/  / | ·/   ¬\  \/',replace('     _____/\  ________ ___/\___/\_______\n    /·__  / \/·/__ ·/|_\___ ¬\ __\_____/·/X·\n/\_/  |¬\/\_ _/ |¬\/ |¬\/ /\/ \¬| \__)___/\\n   \  |  \/¬ |  |  \ | ·\ \/  / | ·/   ¬\  \/\n·/X·\__ ·/\__|\__ ·/____/_/__/__|_/___ ·/sW\n       \/        \/  ...presents...   \/\n ·» DoWnLoaD SoRTeR v1.O bY SPEEDWOLF/cLe! «·\n      /Y\ The Ultimate Trader Tool! /Y\\n','\n',char(10)),'DL-SoRTeR.GuiDe',replace('@node MAIN "DOWNLOAD SORTER v1.O by SPEEDWOLF/CYCLONE ©1994!"\n                  _____/\  ________ ___/\___/\_______\n                 /·__  / \/·/__ ·/|_\___ ¬\ __\_____/\n   ________  /\_/  |¬\/\_ _/ |¬\/ |¬\/ /\/ \¬| \__)___/\  __________\n           \/   \  |  \/¬ |  |  \ | ·\ \/  / | ·/   ¬\  \/\n                 \__ ·/\__|\__ ·/____/_/__/__|_/___ ·/sW\n                    \/        \/  ...presents...   \/\n   _______________________________________________________________________\n  |/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::|\n  |\::/\::/\::/\::/\::/\::/\::/\::/\::/\::/\::/\::/\::/\::/\::/\::/\::/\::|\n  | \/  \/  \/  \/  \/  \/  \/  \/  \/  \/  \/  \/  \/  \/  \/  \/  \/  \/|\n  | /\  /\  /\  /\  /\  /\  /\  /\  /\  /\  /\  /\  /\  /\  /\  /\  /\  /\|\n  |/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::|\n  |\::/\::/\::/\::/\:|¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n  | \/  \/  \/  \/  \|           @{"--> Download Sorter v1.O <--"Link Law}\n  | /\  /\  /\  /\  /|\n  |/::\/::\/::\/::\/ |          ...bY SPEEDWOLF/CYCLONE ©''94...\n  |\::/\::/\::/\::/\ |\n  | \/  \/  \/  \/  \|                @{"   IntroDuction   "Link Intro}\n  | /\  /\  /\  /\  /|                @{"   Installation   "Link Install}\n  |/::\/::\/::\/::\/:|                @{"  Configuration!  "Link Config}\n  ¦\::/\::/\::/\::/\:¦                @{" !How to Contact! "Link Contact}\n  : \/  \/  \/  \/  \:\n  ·                  ·\n@endnode\n@node Law\n----[ SPEEDY''S LaW - THE CREDITZ!  ]---------------------------------------\n\n CoDe bY .................................................. SPEEDWOLF/cLe!\n iDea bY .................................................. SPEEDWOLF/cLe!\n\n@endnode\n@node "Intro"\n----[ IntroDuction ]-------------------------------------------------------\n\n This tool was made for Traders like me...\n\n When you trade a lot of soft your Download Directory grow more and more \n every day. And after a time you don''t know what''s new and what''s old.\n Coz'' you never looked at the soft you leeched and only traded it but you \n want to keep it unless you know if if can be useful for you...\n\n Well this time is now over! DOWNLOAD-SORTER does the following:\n\n It checks the Date and creates a drawer named after the Date in a certain\n Dir and set an assign on this drawer called `TODAY''! Now only what you have\n to do is to set your Download Path in your Terminal to TODAY and also the\n Upload Dir.Now you see wehen you leeched a file and have a better view at\n them.\n\n@endnode\n@node "Install"\n----[ Installation ]--------------------------------------------------------\n\n It''s useful to start DOWNLOAD-SORTER in your User-Startup (or Startup-\n Sequence for OS1.3 Lamers!) so that you already have the right path when\n you boot your Amiga.\n\n The path where DOWNLOAD-SORTER should create the Dir is given in the \n Config-File located in `S:DL-Sorter.cfg''\n\n Note: Be Sure That you have started Rexxmast V1.5 and have all Rexx-Libs\n       installed.\n\n@endnode\n@node Config\n----[ Configuration ]-------------------------------------------------------\n\n Well it''s all told in INSTALLATIOn but again:\n\n Simply edit the File `S:DL-Sorter.cfg'' to your needs.\n (Enter path where the drawers should be placed!)\n \n@endnode\n@node "Contact"\n\n              To Get MoRe gReaT tOOlS oR 4 CoNtaCt CaLL tHiZ!\n                         ____\n       _ __ ____________/   /______________________________ __ _\n       \\\_\\______    /   /____  _____/ __   /  _____  __ \\_\\\\n        ¯    |    / __/   /    /___   \   \__/  ___/_/  |  /    ¯\n             ¦    .   \       /   /   /    \   /    /      \\n          _ _:________/______/\______/\_____\______/    |___\sW\n             :                                    /_____¦\n                              B · B · S                :\n                  \n   (+49) 0211                                           (+49) 0211\n     4792811         CooL cReW oF fRIENDLY pEOPLE         410412\n\n                     ...wORLD hEADQUARTER oF... \n\n                  _____/\  ________ ___/\___/\_______     \n                 /·__  / \/·/__ ·/|_\___ ¬\ __\_____/     \n             /\_/  |¬\/\_ _/ |¬\/ |¬\/ /\/ \¬| \__)___/\  \n                \  |  \/¬ |  |  \ | ·\ \/  / | ·/   ¬\  \/\n                 \__ ·/\__|\__ ·/____/_/__/__|_/___ ·/sW  \n                    \/        \/                   \/     \n   \n                        bE tHERE oR bE dEAD!\n\n       wE aRe LooKing For MoRe Members! JoIn thE tW¡RL¡NG PoWeR nOW!\n@endnode\n','\n',char(10)),NULL,'auto-added',5487,1,0,NULL,NULL,'cle_ds1o','scan',1780048442);
INSERT INTO door_catalog VALUES('cle_idf','CLE-IDF.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CLE-IDF.LHA','ZiPiD','XIM','ZiPiD',NULL,NULL,'CLE','/·__  / \/·/__ ·/|_\___ ¬\ __\_____/·/X· /\_/  |¬\/\_ _/ |¬\/ |¬\/ /\/ \¬| \__)___/\ \  |  \/¬ |  |  \ | ·\ \/  / | ·/   ¬\  \',replace('     _____/\  ________ ___/\___/\_______\n    /·__  / \/·/__ ·/|_\___ ¬\ __\_____/·/X·\n/\_/  |¬\/\_ _/ |¬\/ |¬\/ /\/ \¬| \__)___/\\n   \  |  \/¬ |  |  \ | ·\ \/  / | ·/   ¬\  \\n·/X·\__ ·/\__|\__ ·/____/_/__/__|_/___ ·/sW \n       \/        \/  ...presents...   \/\n»» FiX FoR STRIP_ID from PTL CaLLeD ZiPiD ««\n « NoW it extracts the FiLe_ID FrOm ZiPs! »\n<[·ABUSING FILEID FOR BBS ADVERTS IS COOL·]>\n','\n',char(10)),'ZiPiD.DoC',replace('                                                      · · · ·········---+\n                  /\                          /\       /\         ···::::\n        _________/__\    ____________________/  \_____/ ·\____________·::\n       /         · / \  /   /      · /|\         ¬\·      \         ·/ ·:\n   ·  / :  _____  /.:.\/   / _____  /:|·\______    \ ____  \  ______/   :\n   · /.::  |   ¬\/.::     /  |    \/·:|__/·   /\  : \   |   \  ___)__   :\n   · \ ::  | .:: \__   __/:  | .:: \ ·|  \   /  \/::.\  | :  \__   : \  :\n   :  \ :    :::·/ ¬   |\::    :::./  | :.\  \· /·:· /  | ::·  /  ·::.\\n   :·  \____  : /\   · | \____  : /     ::.\  \/    /   |.:·  /    :: / ·\n   ::.  *¤°~\  /· \____|· ~°¤*\  /\________/_______/____l____/____\  /· :\n   :::..     \/    *¤°~~       \/  ~°¤*¤°~¯ ~°¤*¤°~ ~*¤° °¤*¤°¯°¤*¤\/sW\n   +--------------···········\n                            ...FiXeD FoR Ya...\n\n        «» `STRIP_ID V1.06'' from PTL (What for does it stand ?¿) «»\n\nIntroDuction\n------------\n\nWell the story is everytime the same. The File_Id was a good invention but\nafter some time some people used it for their own profit. As we all know\nBBS-Addies in the FILE_ID.DIZ SuXX! For Luck someone coded a Stripper for \nthe Adds. the first one I saw was the ''Strip BBS Addies'' from Motion. By\nthe way : It''s pretty cool but maybe a little bit too slow coz'' of aREXX.\nMainly it''s the Problem with DMS ''n'' ZiPs. \n\nBut yesterday i saw the `STRIP_ID'' from PTL and i was very impressed. A\nfull new File_Id Tool with many new features and integrated Stripper for\nthose BBS-Addies (I think DELTAFORCE was the first who has done this\nshit!).\nAfter installing it runned very well! it was also a little bit faster than\nthe one from ByteAndi (are you still alive?) but after a time of testing\nthere was the Problem of Extrracting the ID out of ZiPs. A Look at the Dok\nand there was the Answer. I must write a Script for Zip on my own...\nBut now comes the Problem. After Extracting the FILE_ID the STRIP_ID\nsearchs for the FILE_ID in the Work-Directory of the current node.\nBut STRIp_ID said that there''s no FILE_ID though it''s in the file!\n\nThe Reason: The Tool ''UNZIP'' used to extract the FILE_ID.DIZ out of the\nZiP-File didn''t have the option to extract a single File to a certain\ndirectory. It always extracts it to the Current Dir (Usually DH0:)\nBut what do now ??? Well ther are two possibilites:\n\n        1) Install the OLD FileID and get terrored by the BBS-Addies!\n\n        or\n\n        2) Use my Tool and say bye bye to the BBS-Addies...:)\n\n\nP.S. Fo those who don''t have th STRIP_ID from PTL. Don''t worry! it''s also\nincluded in this archive!\n\n\nInstallation\n------------\n\n - Copy the Tool ''ZiPiD'' to your Utils drawer (located in BBS:Utils/)\n\n - Copy the Script to your Script-Drawer called FILEID (loc. inBBS:FILEID/)\n\nWell that''s! If you haven''t done anything wrong the STRIP_ID will now also\nextract the FILE_ID out of ZiPs.... YEEEAHH!!!\n\nContact:\n--------\n To Join or Contact Cyclone call diz...\n\n                 dA oNLY pLACE fOR fRIENDSHIP aND eLITE !\n                         ____\n       _ __ ____________/   /______________________________ __ _\n       \\\_\\______    /   /____  _____/ __   /  _____  __ \\_\\\\n        ¯    |    / __/   /    /___   \   \__/  ___/_/  |  /    ¯\n             ¦    .   \       /   /   /    \   /    /      \\n          _ _:________/______/\______/\_____\______/    |___\sW\n             :                                    /_____¦\n                              B · B · S                :\n                  \n                             0-3 Day WaReZ\n                            aMIGA aN'' PeCe\n   (+49) 0211                                           (+49) 0211\n     4792811         CooL cReW oF fRIENDLY pEOPLE         410412\n\n                     ...wORLD hEADQUARTER oF... \n\n                  _____/\  ________ ___/\___/\_______     \n                 /·__  / \/·/__ ·/|_\___ ¬\ __\_____/     \n             /\_/  |¬\/\_ _/ |¬\/ |¬\/ /\/ \¬| \__)___/\  \n                \  |  \/¬ |  |  \ | ·\ \/  / | ·/   ¬\  \/\n                 \__ ·/\__|\__ ·/____/_/__/__|_/___ ·/sW  \n                    \/        \/                   \/     \n   \n                           bE qUICK oR bE dEAD!\n\n                          ...also CALL UP FOR GREAT /X-TOOLS FROM CYCLONE\n\n  Also catch my other great tools....\n                                      sTaTs V1.0\n                                      SaFeEdiT V1.0\n                                      ZiPiD V1.0 (thiz one!)\n\n       and a lot of other things by other CLE-Members (JOIN US NOW!)\n\n A Full List with al available tools will be included in our next release!\n\nFor Legal Swapping,Contact etc. call diz (Voice!)  02102 / 872012 \n                                                       ...and ask for ''Kai''!\n\nFinal Note:\n-----------\n We are planning to release a Chipmagazine and searching for\n Addvertisements and other interersting texts or some ChipTunes....\n For tgiz call one of the Numbers above to get further Infos..........\n\n','\n',char(10)),NULL,'auto-added',139767,13,0,NULL,NULL,'cle_idf','scan',1780048442);
INSERT INTO door_catalog VALUES('cle_ls1o','CLE-LS1O.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CLE-LS1O.LHA',NULL,'XIM','_____/\  ________ ___/\___/\_______',NULL,'SPEEDWOLF/CLE','CLE','/·__  / \/·/__ ·/|_\___ ¬\ __\_____/·/X· /\_/  |¬\/\_ _/ |¬\/ |¬\/ /\/ \¬| \__)___/\ \  |  \/¬ |  |  \ | ·\ \/  / | ·/   ¬\  \/',replace('     _____/\  ________ ___/\___/\_______\n    /·__  / \/·/__ ·/|_\___ ¬\ __\_____/·/X·\n/\_/  |¬\/\_ _/ |¬\/ |¬\/ /\/ \¬| \__)___/\\n   \  |  \/¬ |  |  \ | ·\ \/  / | ·/   ¬\  \/\n·/X·\__ ·/\__|\__ ·/____/_/__/__|_/___ ·/sW\n       \/        \/  ...presents...   \/\n    > LoGSTRiPPER v1.O bY SPEEDWOLF/CLE < \n  · Cuts all the Nasty Logs automatically ·\n· For /X4.X & /X3.X and fully configurable! ·\n','\n',char(10)),'LogStrip.guide',replace('@node MAIN "LOGSTRIPPER v1.OO by SPEEDWOLF/CYCLONE ©1994!"\n\n                           tHe fLiPiNg gOdS oF \n              ___  ____.    ___    _.     ___    ___    ___\n             /  ¬\_\  ¬|__ /  ¬\_ /¬:    / .¬\  /   \  / .¬\_\n           _/  :__/ \  l //  |__//  ¦___/  :  \/___. \/_ l__/\n       __ _\   | ¬\ /\__ \   : ¬\   | ¬\   ¦   /   :  ¯/  ._)_ _ __\n       \ \\\\  l   Y   l  \  l   X  l   X  |  /\   ¦  /\  |  //// /\n        \_\\\\____/\______/\____/ \____/ \___/  \__|_/pSO___////_/\n                                                   \n                               ...pReSeNtS...\n  \n                <· LOGSTRIPPER v1.O bY SPEEDWOLF/CYCLONE''94 ·>\n  \n                             @{"   IntroDuction   "Link Intro}\n                             @{"   Installation   "Link Install}\n                             @{"  Configuration!  "Link Config}\n                             @{" !How to Contact! "Link Contact}\n                             @{" Update & History "Link History}\n                             @{" Greets & Hellos! "Link Greetinx}\n@endnode\n@node Law\n----[ LoGSTRiPPER - THE CREDITZ!  ]----------------------------------------\n\n CoDe (v1.O) bY ........................................... SPeeDWoLF/cLe!\n iDea & ConCepT bY ....................... SPeeDWoLF/cLe! & ReNDeRMaN/cLe!\n\n@endnode\n@node "Intro"\n----[ IntroDuction ]-------------------------------------------------------\n\n Well,LOGSTRIPPER was made for the more lazy sysops (don''t take it too \n serious!). LOGSTRIPPER will cut all Logs that the BBS made if they are\n longer than you want.\n So your HD-Space won''t ever be polluted with LogCrap.\n Simply install it to every `Logoff.txt'' of your BBS and LOGSTRIPPER will\n do the rest.\n\n Still written in Arexx...... :-(\n But it''s also very fast..... :-)\n\n I''m leraning a higher Language at the Moment and as long as i don''t get\n the interface and message-strucure for Doors right, my tools will be in \n Arexx.....\n Sorry for that,but i think Arexx isn''t so bad like some people think....\n It''s simple but it''s powerful....\n\n@endnode\n@node "Install"\n----[ Installation ]--------------------------------------------------------\n\n The Installation is easy as fucking your girlfriend (if you have one...)\n\n Simply Copy the Contents of this archive to same drawers as in this\n archive...\n (LOGSTRIP.info to BBS:Commands/BBSCmd...LOGSTRIP.REXX to......blabla....)\n\n All that you now have to do is to start the LOGSTRIP Command in your\n Logoff-text located in every Node-Drawer of your BBS.\n\n If you haven''t got one, GO BUY ONE! NoNoNoNo...that''s false :-)\n\n Simply make a File called LOGOFF.TXT and enter this....\n\n >----------------------<\n\n ~ \n ~CC_LOGSTRIP \n\n >----------------------<\n\n NOTE: Make Sure that after every Line is a Space...\n       (e.g. "~CC_LOGSTRIP " !)\n \n@endnode\n@node Config\n----[ Configuration ]-------------------------------------------------------\n\n Well the Configuration is as easy as...(you know!)\n\n Simply edit the Config-File as following...\n\n NewDoorSize = 50000                 ;Cutted Size of the DorLog\n NewCallerSize = 50000               ;Cutted Size of the CallersLog\n NewUDSize = 50000                   ;Cutted Size of the UDLog\n NewErrorSize = 50000                ;Cutted Size of the ErrorLog\n StripDoorBelow = 100000             ;Cut DoorLog if bigger then ''x'' Bytes\n StripCallerBelow = 100000           ;Cut CallersLog if bigger then ''x'' Bytes\n StripUDBelow = 100000               ;Cut UDLog if bigger then ''x'' Bytes\n StripErrorBelow = 100000            ;Cut ErrorLog if bigger then ''x'' Bytes\n\n In this Version LOGSTRIPPER will cut the DoorLog,Callerslog,UDLog and the\n ErrorLog. As you can see in the Config you can edit each Log seperate.\n \n Please don''t change the order of the config or write something like this:\n  \n "NewDoorSize =50000" I don''t know what happens then but it won''t work at\n  all...\n\n\n@endnode\n@node "Contact"\n\n              To Get MoRe gReaT tOOlS oR 4 CoNtaCt CaLL tHiZ!\n                         ____\n       _ __ ____________/   /______________________________ __ _\n       \\\_\\______    /   /____  _____/ __   /  _____  __ \\_\\\\n        ¯    |    / __/   /    /___   \   \__/  ___/_/  |  /    ¯\n             ¦    .   \       /   /   /    \   /    /      \\n          _ _:________/______/\______/\_____\______/    |___\sW\n             :                                    /_____¦\n                              B · B · S                :\n\n   (+49) 0211                                           (+49) 0211\n     4792811         CooL cReW oF fRIENDLY pEOPLE         410412\n\n       19.2  ÷|÷ iSDN (+49) 0211 / 4715922 ·RiNGDoWN· ÷|÷  16.8\n\n                     ...wORLD hEADQUARTER oF... \n\n                  _____/\  ________ ___/\___/\_______     \n                 /·__  / \/·/__ ·/|_\___ ¬\ __\_____/     \n             /\_/  |¬\/\_ _/ |¬\/ |¬\/ /\/ \¬| \__)___/\  \n                \  |  \/¬ |  |  \ | ·\ \/  / | ·/   ¬\  \/\n                 \__ ·/\__|\__ ·/____/_/__/__|_/___ ·/sW\n                    \/        \/                   \/     \n   \n\n         ConTaCt oNe oF oUr MeMbErS fOr JoiNiNG - sWaPPinG etC!\n         <· KERMiT · SPEEDWOLF · RENDERMAN · SPOCK · TUBORG ·>\n                   ...aND oTHErS (NoN MoDeMs·oNeS)...\n\n       wE aRe LooKing For MoRe Members! JoIn thE tW¡RL¡NG PoWeR nOW!\n\n@endnode\n@node "History"\n----[ HiSTORY & UPDATES ]---------------------------------------------------\n\n v1.O - First Public Version and First Version ever also.\n        Find No Bugs after testing it at my Beta-TestSide for a long time!\n        (THX,ReNDeRMaN!) So : Never change a working tool....\n\n UPDATES ?? Well no Future Enhancements are planned right now but if you\n know something that I can add , TELL ME!\n\n Please contact me if you''re using my tool in your BBS...\n I would like to hear from you and your opinion about it...\n Only so, good tools can be made...-> FRiENDSHiP RuLEZ aLSO :) <-\n \n@endnode\n@node "Greetinx"\n\n                          ...SoMe HeLLoS Go To...\n\n         · RENDERMAN/CLE · PSYCHO/CLE · MILLE/CLE · FRAGGLE/CLE ·\n                  · SPOCK/CLE · TUBORG/CLE · KERMIT/CLE ·\n            · CHRUSHER/S8 · DELTAFORCE/DLM (THX FOR DA HELP!) ·\n            · VALSHARE/TRSI · DR.BYTE/PGS · CUJO/PGS · ALIEX ·\n · JEFF STAINE/PGS · LAURIN/CONCEPT · MAXHEADROOM/TEX · CREATOR (BUSTED?¿) ·\n           · BREAKER(:( NEVER CHATTED AGAIN!) · ICE-T/PRODIGY ·\n     · COOLSPOT/iNDY · STARBREAKER · SPUNK/ABSOLUTE! · TWILIGHT/LEGO ·\n          · HAPE · SOLARIS/7UP · MR.NEW/S8 · BIT-BANDIT/SCEPTIC ·\n                          · CUSAK/iNDY · MoNTY ·\n\n                      ...aND tO aLL i''VE fORGOTTeN...\n\n@endnode\n','\n',char(10)),NULL,NULL,8456,4,0,NULL,NULL,NULL,'scan',1780048442);
INSERT INTO door_catalog VALUES('cle_sl1o','CLE-SL1O.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CLE-SL1O.LHA',NULL,'XIM','_____/\  ________ ___/\___/\_______',NULL,'SPEEDWOLF/CYCLONE','CLE','/·__  / \/·/__ ·/|_\___ ¬\ __\_____/·/X· /\_/  |¬\/\_ _/ |¬\/ |¬\/ /\/ \¬| \__)___/\ \  |  \/¬ |  |  \ | ·\ \/  / | ·/   ¬\  \/',replace('     _____/\  ________ ___/\___/\_______\n    /·__  / \/·/__ ·/|_\___ ¬\ __\_____/·/X·\n/\_/  |¬\/\_ _/ |¬\/ |¬\/ /\/ \¬| \__)___/\\n   \  |  \/¬ |  |  \ | ·\ \/  / | ·/   ¬\  \/\n·/X·\__ ·/\__|\__ ·/____/_/__/__|_/___ ·/sW\n       \/        \/  ...presents...   \/\n ·» SPeeDy''S LaW v1.O bY SPEEDWOLF/CYCLONE «·\n  /Y\ Let Appear texts by Chance! CooL! /Y\\n','\n',char(10)),'LaW_dT.guide',replace('@node MAIN "SPEEDY''S LaW v1.O by SPEEDWOLF/CYCLONE ©1994!"\n                  _____/\  ________ ___/\___/\_______\n                 /·__  / \/·/__ ·/|_\___ ¬\ __\_____/\n   ________  /\_/  |¬\/\_ _/ |¬\/ |¬\/ /\/ \¬| \__)___/\  __________\n           \/   \  |  \/¬ |  |  \ | ·\ \/  / | ·/   ¬\  \/\n                 \__ ·/\__|\__ ·/____/_/__/__|_/___ ·/sW\n                    \/        \/ ...präsentiert... \/\n   _______________________________________________________________________\n  |/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::|\n  |\::/\::/\::/\::/\::/\::/\::/\::/\::/\::/\::/\::/\::/\::/\::/\::/\::/\::|\n  | \/  \/  \/  \/  \/  \/  \/  \/  \/  \/  \/  \/  \/  \/  \/  \/  \/  \/|\n  | /\  /\  /\  /\  /\  /\  /\  /\  /\  /\  /\  /\  /\  /\  /\  /\  /\  /\|\n  |/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::\/::|\n  |\::/\::/\::/\::/\:|¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n  | \/  \/  \/  \/  \|             @{"--> SPEEDY''S LaW v1.O <--"Link Law}\n  | /\  /\  /\  /\  /|\n  |/::\/::\/::\/::\/ |          ...von SPEEDWOLF/CYCLONE ©''94...\n  |\::/\::/\::/\::/\ |\n  | \/  \/  \/  \/  \|                @{"    Einführung    "Link Intro}\n  | /\  /\  /\  /\  /|                @{"   Installation   "Link Install}\n  |/::\/::\/::\/::\/:|                @{"  Konfiguration!  "Link Config}\n  ¦\::/\::/\::/\::/\:¦\n  : \/  \/  \/  \/  \:\n  ·                  ·\n@endnode\n@node Law\n----[ SPEEDY''S LaW - THE CREDITZ!  ]---------------------------------------\n\n Geschrieben von .......................................... SPEEDWOLF/cLe!\n Original TeXte von ........................................ Krypton Force\n Übersetzung und Änderungen von ........................... SPEEDWOLF/cLe!\n\n@endnode\n@node "Intro"\n----[ Einführung ]---------------------------------------------------------\n\n Die Funktion dieses Programms\n Vielleicht kennst du ''Murphy''s Law'' ??? Egal,wenn nicht ist es auch nicht\n schlimm! Ich werde dir dieses Programm erklären!\n\n Nun,SPEEDY''S LAW is nichts anderes als eine Konvertierung von Murphy''s Law\n von Krypton Force neu geschrieben für /X. (M''s L war ein Tool für FastCall\n von Martin Fickner!) Da abaer FastCall lame ist doch dieses ''Tool'' dagegen\n echt gut ist hab ich es extra für /X-Freunde komplett neu geschrieben!\n\n Dennoch gibt es einige Neuerungen!\n \n        - Mehrere Sprachen in denen der Text erscheint! (Englisch oder Dt.!)\n          (macht das programm auch für nicht-deutsche Sysops interessant!)\n\n        - MultiLanguage Guide! For german and foreign Guys (English!)\n \n SPEEDY''S LAW gibt jedesmal wenn es gestartet wird einen Witz oder wie ich\n es nenne eine ''Regel!'' auf den Screen. Das programm wählt dabei zwischen\n 50 Texten, die im File ''LaW.txt'' stehen!\n Man kann jeden Text ändern bloss beachte bitte dass texte über der index-\n nummer 50 nicht akzeptiert werden!\n\n Vielleicht gibt es irgenwann nochmal ein Update wenn mir was einfällt...\n\n Wenn du irgenwelche Probleme mit dem Programm oder Ideen hast dann \n kontaktiere mich sofort durch die BUSTER BBS - CYCLONE WHQ!\n\n\n                         NoDe #1 : 0211 / 4792811\n                         Node #2 : 0211 /  410412 \n\n Schreib einfach eine nachricht an den User ''SPEEDWOLF''\n\n                      So Lange.......BLEIB DRAN''! :^)\n@endnode\n@node "Install"\n----[ Installation ]--------------------------------------------------------\n\n Kopiere den BBS-Befehl ''LaW.info'' ind das Befehls-Verzeichnis und den\n Inhalt des DOORS:LaW Verzeichnisses (in diesem Packet enthalten!) in \n dein DOOR-Verzeichnis!\n\n Jetzt kannst du zwischen drei Möglichkeiten wählen!\n\n     - Benutze SPEEDY''S LAW als Door\n                                               ...dann nist du fertig!!\n\n     - Benutze SPEEDY''S LAW im Login oder dem Logoff (sinnvoll!)\n\n                                                  ...les das folgende!!\n\n Ergänze einfach folgendes zu deinem LOGON- oder LOGOFF.TXT\n\n >--------------------------<\n       ~ \n       ~CC_LAW  (Achtung: nach ''LAW'' muß ein noch ein Leerzeichen stehen!)\n >--------------------------<\n\n ...oder kopiere die Files (auch enthalten!) in BBS:Screens/Node !!!\n \n (Vielleicht benutzt du seperate Texte für jede Node! Dann musst diesen\n  Vorgang öfters wiederholen!)\n\n Jau! Das war schon alles und nun: Hab Spass damit!\n\n@endnode\n@node Config\n----[ Configuration ]-------------------------------------------------------\n\n Durch das editieren der Datei ''DOORS:LaW/LaW.txt'' kann man die Texte ändern.\n\n Mitbei sind auch noch 2 Files namens ''LaW.dt'' und ''LaW.en'' die man\n ebenfalls als Text-datei verwenden,indem man einen der Texte auf ''LaW.txt''\n umbenennt!\n\n Wenn du aber deine eiegnen text haben willst dan mach einfach dein\n eiegenes Config-File...\n\n Einfach im TextEd folgenden text eingeben...\n\n >-------------------\n  1\n  « text 1 »\n  2\n  « text 2 »\n >-------------------\n\n                 ...und so wieter!!!\n\n@endnode\n','\n',char(10)),NULL,NULL,14859,2,0,NULL,NULL,NULL,'scan',1780048448);
INSERT INTO door_catalog VALUES('cle_uc12','CLE-UC12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CLE-UC12.LHA',NULL,'XIM','UC.LoGCreaTor',NULL,'SPEEDWOLF/cLe!','CLE','/·__  / \/·/__ ·/|_\___ ¬\ __\_____/·/X· /\_/  |¬\/\_ _/ |¬\/ |¬\/ /\/ \¬| \__)___/\ \  |  \/¬ |  |  \ | ·\ \/  / | ·/   ¬\  \/',replace('     _____/\  ________ ___/\___/\_______\n    /·__  / \/·/__ ·/|_\___ ¬\ __\_____/·/X·\n/\_/  |¬\/\_ _/ |¬\/ |¬\/ /\/ \¬| \__)___/\\n   \  |  \/¬ |  |  \ | ·\ \/  / | ·/   ¬\  \/\n·/X·\__ ·/\__|\__ ·/____/_/__/__|_/___ ·/sW\n       \/        \/  ...presents...   \/\n ·» uPLoaD cHeCKeR v1.2 bY SPEEDWOLF/cLe! «·\n    The TooL you aLL beeN waiting for !\n   NeVeR SeeN BeFoRe aND aBSOLUTELY CooL!\n','\n',char(10)),'UC.Guide',replace('@node MAIN "     uPLoaD-cHeCKeR v1.2 DoCuMeNtaTioN - ©''94 SPEEDWOLF/CYLONE!"\n@{ "tHE tWIRLING gODS oF fLIPP!" Link Contact}                           · · · ·········---+\n                  /\                          /\       /\         ···::::\n        _________/__\    ____________________/  \_____/ ·\____________·::\n       /         · / \  /   /      · /|\         ¬\·      \         ·/ ·:\n   ·  / :  _____  /.:.\/   / _____  /:|·\______    \ ____  \  ______/   :\n   · /.::  |   ¬\/.::     /  |    \/·:|__/·   /\  : \   |   \  ___)__   :\n   · \ ::  | .:: \__   __/:  | .:: \ ·|  \   /  \/::.\  | :  \__   : \  :\n   :  \ :    :::·/ ¬   |\::    :::./  | :.\  \· /·:· /  | ::·  /  ·::.\\n   :·  \____  : /\   · | \____  : /     ::.\  \/    /   |.:·  /    :: / ·\n   ::.  *¤°~\  /· \____|· ~°¤*\  /\________/_______/____l____/____\  /· :\n   :::..     \/    *¤°~~       \/  ~°¤*¤°~¯ ~°¤*¤°~ ~*¤° °¤*¤°¯°¤*¤\/sW\n   +--------------···········\n                              ...presents...\n\n      »» tHE dOCUMENTATION fOR uPLOAD cHECKER bY SPEEDWoLF/CYCLONE!««\n\n                           @{"    iNTRODUCTION    " Link Intro}\n                           @{"    iNSTALLATION    " Link Install}\n                           @{"     kNOWN bUGS     " Link Bugs}\n                           @{"   fUTURE uPDATES   " Link UpDates}\n                           @{"      hISTORY!      " Link History}\n@endnode\n@node Contact "tO cONTACT oR jOIN cYCLONE rEAD tHIZ...."\n\n\n        To Get MoRe gReaT tOOlS oR 4 CoNtaCt oR jOINING CaLL tHiZ!\n                         ____\n       _ __ ____________/   /______________________________ __ _\n       \\\_\\______    /   /____  _____/ __   /  _____  __ \\_\\\\n        ¯    |    / __/   /    /___   \   \__/  ___/_/  |  /    ¯\n             ¦    .   \       /   /   /    \   /    /      \\n          _ _:________/______/\______/\_____\______/    |___\sW\n             :                                    /_____¦\n                              B · B · S                :\n                  \n   (+49) 0211                                           (+49) 0211\n     4792811         CooL cReW oF fRIENDLY pEOPLE         410412\n\n                     ...wORLD hEADQUARTER oF... \n\n                  _____/\  ________ ___/\___/\_______     \n                 /·__  / \/·/__ ·/|_\___ ¬\ __\_____/     \n             /\_/  |¬\/\_ _/ |¬\/ |¬\/ /\/ \¬| \__)___/\  \n                \  |  \/¬ |  |  \ | ·\ \/  / | ·/   ¬\  \/\n                 \__ ·/\__|\__ ·/____/_/__/__|_/___ ·/sW  \n                    \/        \/                   \/     \n   \n                        bE tHERE oR bE dEAD!\n\n       wE aRe LooKing For MoRe Members! JoIn thE tW¡RL¡NG PoWeR nOW!\n\n@endnode\n@node Intro "wHAT iS `UPLOAD CHECKER'' ?¿?¿..."\n\n I think thiz is a tool which every Sysop should use!! If you don''t \n you are a Lamer! There''s no Excuse! It helps him to have his Users\n better under Control! In other words...\n\n `UPLOAD CHECKER'' gives you the possibilty to see the last Upload of\n every User in your System. For example if you are tired of all these\n leechers and non-pumping Guys (I know that''s it ahrd for every Sysop\n when the Uzers are only leeching and leeching...) and you wanted to\n kick some assholes you simply use thiz tool to find out which Users\n haven''t uploaded anything since two months (e.g.). No more tired\n scanning in the Callerslog to search for a User''s Last Upload! \n And if you cutted the CallersLog/UDLog recently because it was to long\n what then ?? Well,to avoid all this shit i''ve written this tool!\n\n If you decided now to use this tool or if you have any ideas to improve\n it feel free to contact! I''m everytime open for new improvements!!!\n\n Call The Buster BBS (+49) 0211 410412 and leave a Message to the Sysop\n or to me. (SPEEDWOLF)\n\n  SO WHY DON''T USE IT!? IT''S FAST - IT''S USEFUL AND ABSOLUTELY COOL!\n@endnode\n@node Install "hOW tO iNSTALL tHIS tOOL..."\n\n                             NOT WRITTEN YET!\n@endnode\n@node Bugs "wELL,sORRY bUT tHERE aRE sTILL sOME bUGS :((("\n\n Well,though this tool is cool,it has also some bugs....\n\n But there aren''t as important as you might think...\n\n - The Tool will only work if your Callerslog is never shorter than 20K.\n   (I think that''s no Problem as long as you don''t use a 2 MB HD :-) )\n\n - The Tool won''t work if a Upload is made locally!\n   (Some strange texts appaer as Last Upload! But I think this isn''t too\n    bad because it''s often the Sysop who made Uplaods locally!)\n \n Well ofcourse I will try to fix these Bugs in the next Updates but I\n think you can handle these bugs till then...\n@endnode\n@node Updates "wHaT iMPORoVEMeNTS WiLL hAVE tHE NeXt vERSiONs!"\n\n  - Option for WildCard when searching for a User! \n\n  - Fixing some Bugs (??? - if there are any left!) \n\n  - Improving the Speed though i think it''s very fast! even on an 68000er!!\n\n  - Writing the tool as a Sys-Cmd! So the Tool will directly start after\n    the File was uploaded! (after File-Id or so..) This would improve the\n    safety of the tool about 50%! (though now it''s as safety as it could be!)\n\n@endnode\n@node History "wHICH vERSIONS hAVE yOU mISSED ?¿"\n\n  v1.O - First Version but never released!\n\n  v1.1 - Not Released. Fixed some Mayor-Bugs.Sometimes it hasn''t found an\n         upload if present! -Fixed!- New Designed LayOut! -Cool!-\n        \n  v1.2 - First official Release! If a UserName contents an "/" \n         for example : "SPEEDWOLF/CLE" the tool would crash! -Fixed!-\n\n@endnode\n@node Installation "hOW tO iNSTALL & uSE tHIS cOOL tOOL!"\n\n The Installation procedure is simple...\n Copy the BBSCommand.infos for UC and UL into `BBS:Commands/BBSCMd/''\n \n Then copy the whole drawer located in DOORS called `UC'' to your local\n DOORS: Directory.\n\n','\n',char(10)),NULL,'auto-added',19558,3,0,NULL,NULL,'cle_uc12','scan',1780048448);
INSERT INTO door_catalog VALUES('cleanit3','CLEANIT3.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CLEANIT3.LHA',NULL,'XIM','CleanItUpv3.1','3.1',NULL,NULL,NULL,replace('CleanItUp v3.1\n','\n',char(10)),'CleanItUp.Doc',replace('\n                              CleanItUp v3.1\n\n                     Copyright © 1990-93 by Kool Falco\n                            All rights reserved\n\n 1. Introduction.\n    ~~~~~~~~~~~~~\n\n        Hello and welcome to another util from my collection, duno if you\nguys are going to use it or not but what the heck, the main thing is that I\nam using it and it helps me to maintain the bbs. Well let me just say its\nvery helpfull. Ok now what does it do? Well it just scans the conference\nmesage base that you specify and it searches for the files that were\nReceiver only messages and that they were readed by their receiver already.\nYeah ya might ask, and whats the hell of it, well if the mesage was readed\nby the receiver already why should I keep the messages online? I dont see\nthe point, and fuck that, message basse takes to much space on my hd anyway\nso after deleting 1/2 of my message base messages that were send to me (the\nsysop of Trash City BBS) I got over 1 meg free in that conf, not much but\nshit I have only 330 meg HD and want to keep everything on it... Oh well\nwhy I have to explain that shit to ya, if ya want use it if not then fuck\noff...\n\n 2. Setup.\n    ~~~~~~\n\n        Ya don''t need anything to set it up, what ya have to do is run the\nutil with the path name to the conference ya want to clean it up, example:\n                           CleanItUp BBS:Warez/\nWould go into BBS:Warez/MsgBase and search for all the mesages that were\nreceiver only and already received. Then it would rename the messages\nitself to let say message_number.old and if you wanted you could simply\ndelete the .old messages and will have your message base clean as hell. If\nby any chance ya want to restore everythign abck to normal, ya have to go\ninside this dir and rename all the files with .old suffix to whatever they\nwere b4, also ya will find 2 files wchich names are:\n                                HeaderFile\n                              HeaderFile.old\nJust to restore the old one replace HeaderFile with HeaderFile.old and\nbingo.\n\n 3. End Part.\n    ~~~~~~~~~\n        Well just hope ya''ll have fun with the util and find some use of\nit. And if you find it usefull please consider the donation of $1 to\ncourage me and write more of such nice utils as well continue with updating\nevery other tools I''ve already done, thanx a lot and here is my address:\n \n                                Kool Falco\n                                PO BOX 128\n                          Rockaway Park, NY 11694\n                                  U.S.A.\n\n        Any Bugs or any other strange things send to me either on this\naddress or simply call my bbs at (718) 318-8315. \n\n 4. Greetings.\n    ~~~~~~~~~~\n        Ok since this is my own util I want to send some special greets to\nmy special friends:\n\n GiapDJ of TCB   <= Thanx for beeing there for me whenever I needed ya, you\n                    are realy the best.\n Bytemaster      <= Thea same as to Giap but also please keep a good work,\n                    you are realy doing a magnificient work.\n\n DR. G           <= Thanx for the inspiration and would be nice to hear from\n                    you sometime.\n\n To all other friends <= Keep supporting my board and thanx for calling it.\n\n To all ya LAME SYSOPS who NEVER REGISTERED your /X <= Fuck you, call now\n                    and register your copy of AmiExpress today. If you use\n                    the program support the author of it.\n\nLater to all of you my friends. Ciao.\n\n\n\nUpdate NOTES:\n~~~~~~~~~~~~~\n	Hi, I just rewrote the little routine so now its much faster to\nremove all the already readed private messages, ok, so thats mainly all.\nthe thing that also changed is that you dont have the HEADERFILE.old\nanymore so if you want it just make somehting like this b4 you run this\ntool:\ncopy bbs:confpath/MsgBase/headerfile bbs:confpath/MsgBase/headerfile.old\nand this way you can prevent anything that could go wrong or somehting.\nI tested it on the april version of AE 3.0 and it works just great, fast\nand very effective but if you have earlier version of AE 3.0 then dont\nuse it. The util works with all the other versions of AE since the structure\nof the header file is exactly the same and this way it works. Ok thats\nmainly all. Oh yeah when you have all the old files then you can easly\nrestore the whole message base or just get rid of it if you wont need it\nor if you see that everything is ok. So I suggest you do those steps while\nworking with this tool:\n\ncopy bbs:confpath/MsgBase/headerfile bbs:confpath/MsgBase/headerfile.old\nCleanItUpv3.1 bbs:confpath/ [msg number to start]\nif everything will be ok then you can execute this line:\ndelete bbs:confpath/MsgBase/#?.old\nand you will get rid of all the already received private files, otherwise\njust rename all the .old files to its orginal format, and it is without\nthe .old extension and you will have your old ,essage base untouched and\nin perfect working condition.\n\nthats all for today, if you want more call my bbs, and leave me your\nsuggestions, opinions, problems and all the other things. I also have\nthis util written in C but have some little problem with it but if you\nfind out that this tool doesnt work for some reason for you just call\nme and I''ll give you the C tool and it will be everything ok. Later\n\n','\n',char(10)),NULL,'auto-added',22238,1,0,NULL,NULL,'cleanit3','scan',1780048448);
INSERT INTO door_catalog VALUES('cli_l2of','CLI-L2OF.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CLI-L2OF.LHA','CLI-LOGOFF2','XIM','+  ___________.  ____ ___.____.________    +',NULL,'DARTAGNAN/OTT/CLI/HNY','CLI','\_   ___/  |_(____)   )_|  |   _____) ---+/   /__|  |  \  /  O  /|__ \_ ____/+---> | :\_____/|______\/__   /____| /_____): |',replace('+  ___________.  ____ ___.____.________    +\n   \_   ___/  |_(____)   )_|  |   _____)\n---+/   /__|  |  \  /  O  /|__ \_ ____/+--->\n | :\_____/|______\/__   /____| /_____): |\n | `--------pReSeNtz-.\_/.---.|/.-+bC!+'' |\n\|/                  `---''   `--''       \|/\n V  ++    TRESPASS /X DOOR DEZIGN    ++  V\n\nCLI-L2OF IS A .G REPLACEMENT FOR YOUR /X BBS\n ASCII''S BY DARTAGNAN/OTT/CLI/HNY AND CODED\n BY TRESPASS/CLIQUE GET THIS IT IS THE BEST\n     LOGOFF DOOR AVAILABLE THESE DAYS.\n','\n',char(10)),'CLI-LOGOFF2.DOC',replace('\n                                    .  .. ... .. .......     .\n                     ....        :  ·              ::::: ....·\n  ·c·l·i·q·u·e·      ::::        ¦__:    -DtN      ::::: ::::._____:\n                   ___:::        (__)       ___    ::::: ::::|___  :\n                _æ^¯  Þ::        ·  ¦    _æ^¯=m*._ ::::: ::::|  |__¦\n             _æP    _/:::        ¦  |  _æP       ¬#::::: ::::|  __/.\n            æ°       :::: .......:  | æ°          w_:::: ::::|  | ¯·\n           JP        :::: :::::::|  |JP           JP:::: ::::|  |  |\n          JF         :::: :::::::|  JF            3r:::: ::::|  |  |\n          J          :::: :::::::|  J        .É   rj:::: ::::|  ¦  |\n          J#         :::: :::::::|  J#       JF  æ .:::: ::::|  :  ¦\n    ©®     JF,     _,:::: :::::::|  ¦JF,     _7F°  ::::: :::::  ·  :    ©®\n  <---->     °===*°¯ ::::.:::::::¦__:  °===*°¯¯Þ¶  `::::.::::·_____·  <---->\n    C!               `:::::::::::''  :          ´¬´  `:::::::''.     .   oTt­\n                                 :  .                        ·\n                                 .\n\n                                X Door Design\n\n                     Logoff Version 2.0 By Trespass/Clique\n                             \n                                 [10-8-1995]          \n\n\n-----------------------------------------------------------------------------\n                           --+ About This Door +--\n-----------------------------------------------------------------------------\n\nCLI-LOG2.LHA contains the files\n\n1: BBS:DOORS/CLI-LOGOFF2/CLI-LOGOFF2\n2: BBS:COMMANDS/BBSCMD/G.INFO\n3: BBS:DOORS/CLI-LOGOFF2/CLI-LOGOFF.DOC\n4: BBS:DOORS/CLI-LOGOFF2/CLI-LOGOFF.PIC\n\nEXPLANATION OF FILES.\n\n1: THE MAIN EXECUTABLE\n2: THE .INFO ICON TO ACTIVATE THE DOOR\n3: THIS DOCUMENTATION\n4: AN IFF PICTURE OF THE SCREEN DISPLAY\n\n\nCLI-LOGOFF2 WAS CODED IN DEVPAC V3 BY TRESPASS OF CLIQUE\nCLI-LOGOFF2 USES THE AEDOOR.LIBRARY V2 BY /WOT\nCLI-LOGOFF ASCIIS WERE DONE BY DARTAGNAN OF OVER THE TOP / CLIQUE AND HONEY\n\nCLI-LOGOFF OFFERS THE USER THE OPTIONS OF \n\n-( G,[CR],N,P,C,? )-\n\nEXPLANATION.\n\nG AND [CR] - GOODBYE / LOGOFF\nN          - NO GO BACK TO THE BBS\nP          - PAGE THE SYSOP\nC          - COMMENT TO THE SYSOP\n?          - DISPLAYS A HELP SCREEN AND SOME GENERAL CLIQUE INFORMATION\n\nCLI-LOGOFF2 IS DIFFERENT TO ANY OTHER LOGOFF DORR I HAVE ENCOUNTERED BY \nTHE MEANS THAT IT WILL AUTO LOGOFF THE USER AFTER ATEMPTING TO PAGE OR \nCOMMENT EITHER BEING SUCESSFUL OR UNSUCESSFUL. \n\n* I REALLY GOT ANNOYED WHEN DOING THESE THINGS ON OTHER BBS AND THEN \nBEING DUMPED BACK TO THE /X MAIN MENU.. (HOW ANNOYING)\n\n-----------------------------------------------------------------------------\n                        \n                     --+ INSTALLING CLI-LOGOFF2 +--\n\nGO TO SHELL:\n\nSHELL>  MAKEDIR DOORS:CLI-LOGOFF2\nSHELL>  COPY RAM:BBS/DOORS/CLI-LOGOFF2/#? DOORS:CLI-LOGOFF2/\nSHELL>  COPY RAM:BBS/COMMANDS/BBSCMD/G.INFO BBS:COMMANDS/BBSCMD/\n\n\nTHIS INSTALLATION PRESUMES YOU HAVE EXTRACTED THE ARCHIVE TO RAM:\n\nTHIS ABOVE INSTALATION REQUIRES YOU TO HAVE YOUR COMMANDS DIR INSTALLED \nWITHING YOUR BBS DIRECTORY. AND ALSO TO HAVE ASSIGNED DOORS: DIRECTORY.\n\nTHERE ARE SIMPLY TO MANY VARIATONS ON BBS SETUPS, SO I HAVE INCLUDED ONLY\nTHE MOST COMMON. YOU SHOULD BE ABLE TO FIGURE IT OUT.\n\nCLI-LOGOFF2 SHOULD NOW BE INSTALLED.\n\nTYPE G AT THE COMMAND LINE TO TEST IT OUT.\n\n-----------------------------------------------------------------------------\n\nGREETINGS AND HELLOS AND ALL THAT TO FOLLOW.\n\nMAGE/CLIQUE           - GOOD TO SEE COASTAL CARNAGE IS STILL PUMPING\nBODYCOUNT/CLIQUE      - THE SMASHING CONTINUES /CLIQUE\nWARCHILD/IND          - HEY CUZ :))\nGRUDGE/IND            - THANKS FOR YOUR WEIRD TEXT\nMAUD`DIB/MST          - DAMM THAT VIRUS. I BEEN GETTING SOME BAD CONNECTS\nKILLRAVEN/MST         - WELL ARE WE.. AND I THINK YOU SHOULD SAY YES!\nLORD/ABSOLUTE!        - YO MAN.. LETS SMOKE THAT VODKA\n243/RYL/N&B/CRUX/FLT  - SO THATS QUITE A FEW TITLES YOU HAVE THERE BONER :)\nBOWEN/SKIDROW/MOTION  - LETS CLEAN EM UP MATE\nPSYCHE/DEVIOUSDESIGNZ - LIKE YOUR LAST COLLECTION WITH ACID KID\nACIDKID/HONEY         - YOUR ONE FAST DUDE THESE DAYS. GLAD I COULD HELP\nSTICKYFINGAZ/CLIQUE   - YOUR A HARD MAN TO BEAT :)\nKURGAN/CLIQUE         - LOOKING FOR A GROUP HEY???\nDARTAGNAN/CLI/OTT/HNY - NICE RELEASES OF LATE KEEP IT UP IF YOU CAN\nRANCID/AFL/ABS!       - WHAT HAPPENING WITH YOUR LADY MAN.. AND CHANCES??\nCOUNTZER0/OGN/AC!/HNY - .C .C .C .C NO MATE .S .S .S .S  :)\nMUTHA/IND             - SOUND STUDIO DELUXE IS IN THE HOUSE :)\nNETRUNNER/PEARL       - I WANT MORE . GIVE ME MORE! A!\nBEAST/IKON VISUAL     - ITS THAT NUMBER AND NOW ITS A BOARD. BUT YOU #1\nWARRIOR/INSOMNIA      - I CANNOT FOR THE LIFE OF ME CONNECT TO YOUR BOARD\n\nAND ALL THE REST WHO MAY OF SLIPPED FROM MY MIND LATE THIS THURSDAY NIGHT.\n\n                                  .  .. ... .. .......     .\n                   ....        :  ­              ::::: ....­\n­c­l­i­q­u­e­      ::::        ª__:    -DtN      ::::: ::::._____:\n                 ___:::        (__)       ___    ::::: ::::|___  :\n               _µ^»  ::        ­  ª    _µ^»=m*._ ::::: ::::|  |__ª\n           _µP    _/:::        ª  |  _µP       ¼#::::: ::::|  __/.\n          µõ       :::: .......:  | µõ          w_:::: ::::|  | »­\n         JP        :::: :::::::|  |JP           JP:::: ::::|  |  |\n        JF         :::: :::::::|  JF            3r:::: ::::|  |  |\n        J          :::: :::::::|  J        .Ì   rj:::: ::::|  ª  |\n        J#         :::: :::::::|  J#       JF  µ .:::: ::::|  :  ª\n  «     JF,     _, :::: :::::::|  ªJF,     _7Fõ  ::::: :::::  ­  :    «\n<---->     õ===*õ» ::::.:::::::ª__:  õ===*õ»»¬   `::::.::::­_____­  <---->\n  C!               `:::::::::::''  :          ¨¼¨  `:::::::''.     .   oTt¡\n                                 :  .                        ­\n\n              n­e­e­d­  ­w­e­  ­s­a­y­  ­m­o­r­e­  . . . . . . .\n','\n',char(10)),NULL,NULL,13009,6,0,NULL,NULL,'cli_l2of_cli_logoff2','scan',1780048448);
INSERT INTO door_catalog VALUES('cli_logo','CLI-LOGO.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CLI-LOGO.LHA',NULL,'XIM','+  ___________.  ____ ___.____.________    +',NULL,NULL,'CLI','\_   ___/  |_(____)   )_|  |   _____) ---+/   /__|  |  \  /  O  /|__ \_ ____/+---> | :\_____/|______\/__   /____| /_____): |',replace('+  ___________.  ____ ___.____.________    +\n   \_   ___/  |_(____)   )_|  |   _____)\n---+/   /__|  |  \  /  O  /|__ \_ ____/+--->\n | :\_____/|______\/__   /____| /_____): |\n | `--------pReSeNtz-.\_/.---.|/.-+bC!+'' |\n\|/                  `---''   `--''       \|/\n V  ++    TRESPASS /X DOOR DEZIGN    ++  V\n Logoff Version 1.1 A great Logoff door for\n AmiExpress 4.xx This logoff door contains\n  Asciis from some of the greatest in Oz.!\n','\n',char(10)),'Logoff.doc',replace('\n                Yes another XIM door By trespass/Clique\n\n  This Time it is a Logoff Door ( I figure You would have guessed that )\n\n\n\n\nWhy use Cli_logoff??\n\nOk simple cli logoff offers a selection of randomlt displayed ansiis.\nthese ansii created By Dartagnan - over The Top/Clique \n                       CountZero - Art Core/Origon\n                       Trespass  - (Yes Me) Clique\n\nThis way Your users get to see pretty logoff screens that change all teh\ntime :)\n\n\nSee iff pictures inserted as Pic001\n                             Pic002\n                             Pic003\n\nOk this door is very simple so no fancy nancy docs.. Its simple.. It gives\nYour users the choice to page You (the sysop I presume) or write You a\nmessage or to abort the logoff procedure..\n\nInstall It like any other /X door \n\n-------------------------------------------------------\ncli> makedir doors:cli-logoff\ncli> copy New_bbs/doors/cli-logoff/logoff.0x0 doors:cli-logoff/logoff.0x0\ncli> copy New_bbs/commands/bbscmd/g.info bbs:commands/bbscmd/\n-------------------------------------------------------\n\nThere and it is installed. No problemo!>.\n\nnow You go to You bbs:commands/bbscmd/g.info file and decide whether you\nhave an 68000 processor or a 68020 or better.. change teh tool type\n\nLOCATION=DOORS:CLI-LOGOFF/LOGOFF.0X0 either to a .020 or .000\n\n\nTest it by typing G on Your local Node. I am sure it will work as good for\nYou as it does for me..\n\nlater!\n\n\n\nGreet flying out to these hammering peoples..\n\n   Dartagnan  - Over The Top / Clique\n   Rancid     - AlfaFlight / Absolute!\n   Kurgan     - Clique\n   BodyCount  - Clique\n   Mage       - Clique\n   Funky      - Independant\n StickyFingaz - Traders In League\n   Rasta      - Clique / UltraSonix\n   Count Zero - Origon / Art Core!B\n   Bowen      - Skid Row / Motion\n   243        - Royal / Nut And Bolt\n\n\nWell boys have fun and lets get it on!>..\n\n\n\n\n\n         Call Coastal Carnage Bbs for latest Clique productions..\n\n\n  CLiQUE World HeadQuarters PEARL OzHeadQuarters /X-Developments 28k! __/\__\n     __                                                               \ oo /\n  (==\/=====--===============-=========--=========-===============--==/_\/_\=\n                                                                        \/\n  _ -  _--  +[-- -  ---[  C O A S T A L  C A R N A G E  ]---  - --]+ --_  - _\n   __/\__\n  =\ oo /===--===============-=========--=========-===============--====/\==)\n   /_\/_\\n     \/   Closed Private System Want to Call then You will Need A Password!\n\n                               +61 75 55 274010\n','\n',char(10)),'{"LOCATION":"DOORS:CLI-LOGOFF/LOGOFF.0X0"}',NULL,16864,2,0,NULL,NULL,NULL,'scan',1780048448);
INSERT INTO door_catalog VALUES('cli_nml3','CLI-NML3.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CLI-NML3.LHA',NULL,'XIM','sfafwefDUHSKasdfF.eXE',NULL,NULL,'CLI','\_   ___/  |_(____)   )_|  |   _____) ---+/   /__|  |  \  /  O  /|__ \_ ____/+---> | :\_____/|______\/__   /____| /_____): |',replace('+  ___________.  ____ ___.____.________    +\n   \_   ___/  |_(____)   )_|  |   _____)    \n---+/   /__|  |  \  /  O  /|__ \_ ____/+--->\n | :\_____/|______\/__   /____| /_____): |  \n | `--------pReSeNtz-.\_/.---.|/.-+bC!+'' |  \n\|/                  `---''   `--''       \|/ \n V  ++    TRESPASS /X DOOR DEZIGN    ++  V  \n                                            \n NOMAiL V3.0 - BEST TOOL TO STOP YOUR USERS \n  WRiTTING MAIL iNTO NON-MAiL AREAS. SYSOP  \nDEFFINABLE CONFERANCES. COMMAND LINE SUPPORT\n','\n',char(10)),'NoMail30.doc',replace('\n                        ___                              ___\n                ________\  \                   __________\  \       \n        ________\_          \____     _________\_            \   \n       .\         \___   ____\   \____\_         \     _______\     \n        :\                  \     \     \    _   \ ______     \     \n          \____    / \----___\__         \   \\   \            \    \n        .     /   /___\_        \    \    \   \\   \            \  \n             /         _         \    \    \__      \_    _______\ \n             \________/ \_______  \    \      \ ______\    \ øne    \n             .          :       \__\___/\______\     \______\\n                       .           .                 :         \n                                                      .\n\n\n            A TOOL TO STOP USERS WRITTING MAIL IN NON-MAIL AREAS\n\n\n\n\n                       A CLIQUE PRODUCTION BY TRESPASS\n\n\n\n\n                                NOMAIL V3.0 \n\n\n\n\n\n\n\n\n              \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                            - WHAT IT IS ABOUT -\n\n\nNoMail V3.0 is a simple /X tool. That lets You define what conferances Your\nusers can write mail in. It works for ''c'' ''r'' and ''e'' commands and also\nsupports external third party sysop comment doors such as dRE!COMMENt. My\nfavorite Sysop Comment door. When users try to (c)omment the sysop (e)nter a\nmessage or (r)ead a message in a file area NoMail20 returns a ''Sorry no Mail\nin area'' and exits back to the BBS. If in a message area You defined the door\ngoes un-noticed and continues with normal Express routines/\n\n \n               Enough Shit...... Let the installation begin!\n\n                                                           /TresPass\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                           -+   INSTALATION    +-\n\n\n\n\nMake a directory in Your Doors: path named NoMail.\n---------------------------------------------------------------------\nshell> makedir doors:NoMail\n---------------------------------------------------------------------\n\nCopy the files from the archive 2_BBS:Doors/NoMail/NoMail30.rexx\n                                2_BBS:Doors/NoMail/NoMail.config\n                                2_BBS:Doors/NoMail/NoMail30.DOC\n\nto the new directory You just made\n---------------------------------------------------------------------\nshell> copy 2_BBS:Doors/NoMail/#?.#? Doors/NoMail/\n---------------------------------------------------------------------                                \n\nCopy the files from the archive 2_BBS:Commands/bbdcmd/c.info\n                                2_BBS:Commands/bbscmd/e.info\n                                2_BBS:Commands/bbscmd/r.info\n                                2_BBS:Commands/bbscmd/rs.info\n                                2_BBS:Commands/bbscmd/comment.info\n\nto Your BBS:COMMANDS/BBSCMD/ directory\n---------------------------------------------------------------------\nshell> copy 2_BBS:Commands/bbdcmd/#?.#? BBS:Commands/bbscmd/\n---------------------------------------------------------------------\n\n\n                                  (More)\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n------------------------------------------------------------------------\n *** SYSOP COMMENT *** USING A SYSOP COMMENT DOOR *** SYSOP COMMENT *** \n------------------------------------------------------------------------\n\n\nRighto Now if You use Sysop Comment door that is not the internal /X\ncommand then can still use it by Renaming your original \nbbs:commands/bbscmd/c.info to bbs:command/bbscmd/comment.info\nThis is not necessary. But if this icon is not found NoMail defaults the\n''c'' command to the internal /x comment to sysop <boreing>. The Icon for \nDre^Comment is included. Either use it. If you use dre^comment. or replace\nit with your own sysop comment door icon. Or delete it all together and use\nthe stock /x sysop comment. Easy!!!\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n------------------------------------------------------------------------\nEDITING THE CONFIG FILE      (********THIS MUST BE DONE********)\n------------------------------------------------------------------------\nYou must go into Your favorite Text editor and pull up the file\nDOORS:NoMail/NoMail30.config/\n\nIt comes default like this.\n\n-------------------------------------------------------------------------\nBBS:CONF1.PUBLICDOMAIN/\nBBS:CONF2.elite/\nBBS:CONF3.ASCII/\nBBS:CONF4.SYSOP/\nBBS:CONF5.REQUEST/\nBBS:CONF7.AMIEXPRESS/\nBBS:CONF8.DEMO/\nBBS:CONF9.CLIQUE/\nBBS:conf59.LOCAL_EMAIL/\nBBS:conf60.BUY_AND_SELL/\nBBS:conf61.AMIGA_NEWS/\n\n^^^^^^^^^^^^^^^^^^^^^^^^^make sure to have a return code after end of FULL\nPath to ALL your MAIL DIRECTORIES and the blank line above!!!!!!!\n--------------------------------------------------------------------------\n                              \nYou must edit it and insert your own Mail Conf paths in place.\n\n* These paths MUST be exactly as written in your BBS:confconfig.info\n  If you have Upper and lowercase letters in BBS:confconfig.info\n  then make 100% sure that You use the same Upper and Lower case chars\n  in this config file.\n\n* Make sure to end each of your paths with a : or /  or else the door \n  does not work.\n\n*  Also make sure that you have a return code directly after end off path.\n   No trailing spaces etc etc. Very important!!!!\n\n*  You can use as many mail conferences as you like add or take as many\n   lines as you like.\n\n*  Also be sure to leave the empty line after your final Mail Conf.\n   Without this the programme will hang.\n\n*  Only the Conferances You include in the config file will allow mail\n   to be written or read. This will not stop replying to an allready\n   written mail. SO my advice is go through and do a quick delete.\n    \n                                  (more)\n\n\n\n\n\n\n\n\n\n\n\n-------------------------------------------------------------------------\n                                 HISTORY\n-------------------------------------------------------------------------\n\n\n\n04-08-95  v1.0   Whipped up. Had to modify source to change mail confs\n\n04-09-95  v1.5   Added third party door support\n\n04-09-95  v2.0   Patched code. Make size smaller by 600bytes\n                 optimised a routine or two.\n                 Added Message scanner support\n                 Added Config file Compatability\n\n05-18-95  v3.0   Now Supports Command line arguments\n\n--------------------------------------------------------------------------\n\n                                  (more)\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n               Well thats all the dribble I can think off.\n\n                                  DIO!\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\nFavorite greets fly out to these Hammering DUDE-S/ETTs.\n\n\n\n\n\n   MaGE//BODYCøUNT//FuNKY//RANCiD//DARTaGNAN//KuRGAN//243//BAT21//PSYCHE\n  AcID kID//LøRD//PøWER//CLI//WARRIøR//CøUNTZERø//STiCKYFiNGAZ//NeTRUNNER\n              BoWeN//RaStA//SmAsH//nIke//CrEaTor//HyDro//PaCe \n                   \n                      + MORE WHO I KNOW I FORGOT!!!!\n\n                              SeCRET SQUIRREL!\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                        ___                              ___\n   <----------  ________\  \                   __________\  \ -------->      \n        ________\_          \____     _________\_            \   \n       .\         \___   ____\   \____\_         \     _______\     \n        :\                  \     \     \    _   \ ______     \     \n          \____    / \----___\__         \   \\   \            \    \n        .     /   /___\_        \    \    \   \\   \            \  \n             /         _         \    \    \__      \_    _______\ \n      <---   \________/ \_______  \    \      \ ______\    \ øne  --->  \n             .          :       \__\___/\______\     \______\\n                       .           .                 :         \n                                                      .\n','\n',char(10)),NULL,'auto-added',62802,9,0,NULL,NULL,'cli_nml3','scan',1780048448);
INSERT INTO door_catalog VALUES('cli_nul1','CLI-NUL1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CLI-NUL1.LHA',NULL,'XIM','sfafwefDUHSKasdfF.eXE',NULL,'PASS','CLI','\_   ___/  |_(____)   )_|  |   _____) ---+/   /__|  |  \  /  O  /|__ \_ ____/+---> | :\_____/|______\/__   /____| /_____): |',replace('+  ___________.  ____ ___.____.________    +\n   \_   ___/  |_(____)   )_|  |   _____)    \n---+/   /__|  |  \  /  O  /|__ \_ ____/+--->\n | :\_____/|______\/__   /____| /_____): |  \n | `--------pReSeNtz-.\_/.---.|/.-+bC!+'' |  \n\|/                  `---''   `--''       \|/ \n V  ++    TRESPASS /X DOOR DEZIGN    ++  V  \n                                            \nNOUPLOAD v1.0 - STOP USERS UPLOADING TO ANY \n CONFERANCE. SYSOP ACCESS CAN BY PASS THIS  \n','\n',char(10)),'NoUpload.doc',replace('\n                        ___                              ___\n                ________\  \                   __________\  \       \n        ________\_          \____     _________\_            \   \n       .\         \___   ____\   \____\_         \     _______\     \n        :\                  \     \     \    _   \ ______     \     \n          \____    / \----___\__         \   \\   \            \    \n        .     /   /___\_        \    \    \   \\   \            \  \n             /         _         \    \    \__      \_    _______\ \n             \________/ \_______  \    \      \ ______\    \ øne    \n             .          :       \__\___/\______\     \______\\n                       .           .                 :         \n                                                      .\n\n\n             A TOOL TO STOP USERS UPLOADING TO ANY CONFERANCE AREA\n\n\n\n\n                       A CLIQUE PRODUCTION BY TRESPASS\n\n\n\n\n                                NOUPLOAD V1.0 \n\n\n\n\n\n\n\n\n              \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                            - WHAT IT IS ABOUT -\n\n\nNoUpload V1.0 is a simple /X tool. That lets You define what conferances Your\nusers can upload to. It works for ''u'' command. NoUpload version 1 will\ncheck every time Your user hits U to upload whether He is allowed to Upload\nto this cpnferance. /X has a ''Bug'' in It I noticed where You can either\nhave files or no files in a conf. But what if You want all uploads to go\ninto one directory. You know when trying to avoid Ascii going into Amiga\nGames or similar. This is where NoUpload v1 is usefull at its best!!\n           \n               Enough Shit...... Let the installation begin!\n\n                                                                /TresPass\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                           -+   INSTALATION    +-\n\n\n\n\nMake a directory in Your Doors: path named NoUpload.\n---------------------------------------------------------------------\nshell> makedir doors:NoUpload\n---------------------------------------------------------------------\n\nCopy the files from the archive 2_BBS:Doors/NoUpload/NoUpload.rexx\n                                2_BBS:Doors/NoUpload/NoUpload.config\n                                2_BBS:Doors/NoUpload/NoUpload.DOC\n                                2_BBS:Doors/NoUpload/Sysop.config\n \nto the new directory You just made\n---------------------------------------------------------------------\nshell> copy 2_BBS:Doors/NoUpload/#?.#? Doors/Noupload/\n---------------------------------------------------------------------                                \n\nCopy the files from the archive 2_BBS:Commands/bbscmd/d.info\n\nto Your BBS:COMMANDS/BBSCMD/ directory\n---------------------------------------------------------------------\nshell> copy 2_BBS:Commands/bbscmd/#?.#? BBS:Commands/bbscmd/\n---------------------------------------------------------------------\n\n\n                                  (More)\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n------------------------------------------------------------------------\n   *** SYSOP ACCESS *** A SYSOP WANTS TO UPLOAD *** SYSOP ACCESS *** \n------------------------------------------------------------------------\n\n\nRighto Now You can define Your sysop access level where You or any other\nuser can upload to any conf. Regardless of whether the conf is defined as\nUploadable by NoUpload v1.0.\n\nFind the file in doors:NoUpload/sysop.config\n\nThere is a number edited onto the top of it. 255 usuall master sysop access\nlevel.. change this to your minimum access level that people can upload\nanywhere.. Useing 200 here would let anyone with access 200 or over to\nupload anywhere and anyone 199 or less would not be able to upload anywhere\nexcept for the defined conferances.\n\n\n\n\n\n------------------------------------------------------------------------\nEDITING THE CONFIG FILE      (********THIS MUST BE DONE********)\n------------------------------------------------------------------------\nYou must go into Your favorite Text editor and pull up the file\nDOORS:NoUpload/NoUpload.config/\n\nIt comes default like this.\n\n-------------------------------------------------------------------------\nBBS:CONF1.PUBLICDOMAIN/\nBBS:CONF2.elite/\nBBS:CONF3.ASCII/\nBBS:CONF4.SYSOP/\nBBS:CONF5.REQUEST/\nBBS:CONF7.AMIEXPRESS/\nBBS:CONF8.DEMO/\nBBS:CONF9.CLIQUE/\nBBS:conf59.LOCAL_EMAIL/\nBBS:conf60.BUY_AND_SELL/\nBBS:conf61.AMIGA_NEWS/\n\n^^^^^^^^^^^^^^^^^^^^^^^^^make sure to have a return code after end of FULL\nPath to ALL your Upload DIRECTORIES and the blank line above!!!!!!!\n--------------------------------------------------------------------------\n                              \nYou must edit it and insert your own Uploadable Conf paths in place.\n\n* These paths MUST be exactly as written in your BBS:confconfig.info\n  If you have Upper and lowercase letters in BBS:confconfig.info\n  then make 100% sure that You use the same Upper and Lower case chars\n  in this config file.\n\n* Make sure to end each of your paths with a : or /  or else the door \n  does not work.\n\n*  Also make sure that you have a return code directly after end off path.\n   No trailing spaces etc etc. Very important!!!!\n\n*  You can use as many uploadable conferences as you like add or take as many\n   lines as you like.\n\n*  Also be sure to leave the empty line after your final Upload Conf.\n   Without this the programme will hang.\n\n*  Only the Conferances You include in the config file will allow user\n   to upload. This will not stop if system asks for a user to resume an\n   older upload. SO go through and delete or move all resumable files.\n    \n                                  (more)\n\n\n\n\n\n\n\n\n\n\n\n-------------------------------------------------------------------------\n                                 HISTORY\n-------------------------------------------------------------------------\n\n04-20-95     Created Software.\n\n04-21-95     Added SySop access to upload anywhere.\n\n05-20-95     First Public Release\n--------------------------------------------------------------------------\n\n                                  (more)\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n               Well thats all the dribble I can think off.\n\n                                  DIO!\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\nFavorite greets fly out to these Hammering DUDE-S/ETTs.\n\n\n\n\n\n   MaGE//BODYCøUNT//FuNKY//RANCiD//DARTaGNAN//KuRGAN//243//BAT21//PSYCHE\n  AcID kID//LøRD//PøWER//CLI//WARRIøR//CøUNTZERø//STiCKYFiNGAZ//NeTRUNNER\n              BoWeN//RaStA//SmAsH//nIke//CrEaTor//HyDro//PaCe \n                   \n                      + MORE WHO I KNOW I FORGOT!!!!\n\n                              SeCRET SQUIRREL!\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                        ___                              ___\n   <----------  ________\  \                   __________\  \ -------->      \n        ________\_          \____     _________\_            \   \n       .\         \___   ____\   \____\_         \     _______\     \n        :\                  \     \     \    _   \ ______     \     \n          \____    / \----___\__         \   \\   \            \    \n        .     /   /___\_        \    \    \   \\   \            \  \n             /         _         \    \    \__      \_    _______\ \n      <---   \________/ \_______  \    \      \ ______\    \ øne  --->  \n             .          :       \__\___/\______\     \______\\n                       .           .                 :         \n                                                      .\n','\n',char(10)),NULL,'auto-added',61882,9,0,NULL,NULL,'cli_nul1','scan',1780048448);
INSERT INTO door_catalog VALUES('cli_page','CLI-PAGE.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CLI-PAGE.LHA',NULL,'XIM','+  ___________.  ____ ___.____.________    +',NULL,NULL,'CLI','\_   ___/  |_(____)   )_|  |   _____) ---+/   /__|  |  \  /  O  /|__ \_ ____/+---> | :\_____/|______\/__   /____| /_____): |',replace('+  ___________.  ____ ___.____.________    +\n   \_   ___/  |_(____)   )_|  |   _____)\n---+/   /__|  |  \  /  O  /|__ \_ ____/+--->\n | :\_____/|______\/__   /____| /_____): |\n | `--------pReSeNtz-.\_/.---.|/.-+bC!+'' |\n\|/                  `---''   `--''       \|/\n V  ++    TRESPASS /X DOOR DEZIGN    ++  V\nSYSOP PAGER Version 1. This is a alternate\nsysop page door for Amiexpress. (what else)\nGives the user many options on how they page\nthe sysop. Great ascii design!\n','\n',char(10)),'PAGER.doc',replace('\n                Yes another XIM door By trespass/Clique\n\n  This Time it is a Sysop Pager Door ( I figure You would have guessed that )\n\n\n\n\nWhy use Cli-Pager\n\n\n\nThis door is very simple so no fancy nancy docs.. Its simple.. It gives\nYour users the choice to page You (the sysop I presume) or write You a\nmessage once pages have run out..\n\nThe user gets one of 5 options to do... Look and see..\n(dammn I hate docs..)\n\nInstall It like any other /X door \n\n-------------------------------------------------------\ncli> makedir doors:cli-pager\ncli> copy New_bbs/doors/cli-pager/pager.0x0 doors:cli-pager/pager.0x0\ncli> copy New_bbs/commands/bbscmd/o.info bbs:commands/bbscmd/\n-------------------------------------------------------\n\nThere and it is installed. No problemo!>.\n\nnow You go to You bbs:commands/bbscmd/o.info file and decide whether you\nhave an 68000 processor or a 68020 or better.. change teh tool type\n\nLOCATION=DOORS:CLI-PAGER/PAGER.0X0 either to a .020 or .000\n\n\nTest it by typing O on Your local Node. I am sure it will work as good for\nYou as it does for me..\n\nlater!\n\n\n\nGreet flying out to these hammering peoples..\n\n   Dartagnan  - Over The Top / Clique\n   Rancid     - AlfaFlight / Absolute!\n   Kurgan     - Clique\n   BodyCount  - Clique\n   Mage       - Clique\n   Funky      - Independant\n StickyFingaz - Traders In League\n   Rasta      - Clique / UltraSonix\n   Count Zero - Origon / Art Core!B\n   Bowen      - Skid Row / Motion\n   243        - Royal / Nut And Bolt\n\n\nWell boys have fun and lets get it on!>..\n\n\n\n\n\n         Call Coastal Carnage Bbs for latest Clique productions..\n\n\n  CLiQUE World HeadQuarters PEARL OzHeadQuarters /X-Developments 28k! __/\__\n     __                                                               \ oo /\n  (==\/=====--===============-=========--=========-===============--==/_\/_\=\n                                                                        \/\n  _ -  _--  +[-- -  ---[  C O A S T A L  C A R N A G E  ]---  - --]+ --_  - _\n   __/\__\n  =\ oo /===--===============-=========--=========-===============--====/\==)\n   /_\/_\\n     \/   Closed Private System Want to Call then You will Need A Password!\n\n                               +61 75 55 274010\n','\n',char(10)),'{"LOCATION":"DOORS:CLI-PAGER/PAGER.0X0"}',NULL,5641,2,0,NULL,NULL,NULL,'scan',1780048448);
INSERT INTO door_catalog VALUES('cli_pg3r','CLI-PG3R.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CLI-PG3R.LHA','CLI-PAGER3','XIM','+  ___________.  ____ ___.____.________    +',NULL,'PHS','CLI','\_   ___/  |_(____)   )_|  |   _____) ---+/   /__|  |  \  /  O  /|__ \_ ____/+---> | :\_____/|______\/__   /____| /_____): |',replace('+  ___________.  ____ ___.____.________    +\n   \_   ___/  |_(____)   )_|  |   _____)\n---+/   /__|  |  \  /  O  /|__ \_ ____/+--->\n | :\_____/|______\/__   /____| /_____): |\n | `--------pReSeNtz-.\_/.---.|/.-+bC!+'' |\n\|/                  `---''   `--''       \|/\n V  ++    TRESPASS /X DOOR DEZIGN    ++  V\n\n CLI-PG3R IS A NEW PAGE DOOR FOR /X SYSTEMS\n  ASCII BY PHS SO ITS OUTPUT IS BRILLIANT\n  CODED BY TRESPASS/CLIQUE CHECK THIS OUT\n        REG''D VERSIONS ARE AVAILABLE\n','\n',char(10)),'CLI-PAGER3.DOC',replace('                                    .  .. ... .. .......     .\n                     ....        :  ·              ::::: ....·\n  ·c·l·i·q·u·e·      ::::        ¦__:    -DtN      ::::: ::::._____:\n                   ___:::        (__)       ___    ::::: ::::|___  :\n                _æ^¯  Þ::        ·  ¦    _æ^¯=m*._ ::::: ::::|  |__¦\n             _æP    _/:::        ¦  |  _æP       ¬#::::: ::::|  __/.\n            æ°       :::: .......:  | æ°          w_:::: ::::|  | ¯·\n           JP        :::: :::::::|  |JP           JP:::: ::::|  |  |\n          JF         :::: :::::::|  JF            3r:::: ::::|  |  |\n          J          :::: :::::::|  J        .É   rj:::: ::::|  ¦  |\n          J#         :::: :::::::|  J#       JF  æ .:::: ::::|  :  ¦\n    ©®     JF,     _,:::: :::::::|  ¦JF,     _7F°  ::::: :::::  ·  :    ©®\n  <---->     °===*°¯ ::::.:::::::¦__:  °===*°¯¯Þ¶  `::::.::::·_____·  <---->\n    C!               `:::::::::::''  :          ´¬´  `:::::::''.     .   oTt­\n                                 :  .                        ·\n                                 .\n\n                                 /X DOOR DESIGN\n\n               PRESENTS ANOTHER XIM/ASM DOOR BY TRESPASS/CLIQUE\n\n\n                          THIS TIME IT IS CLI-PAGER3\n\n\n\n\n\n\n\n\n\n\n\n-----------------------------------------------------------------------------\n\n                               WHY CLI PAGER3?\n\nSIMPLE.., I coded it and the ansii is brilliant and colours are well great.\ninstall it and see for Yourself. Deffinately amongst teh best pagers out\nthere.\n\n-----------------------------------------------------------------------------\n\n                     What is contained in this directory?\n\n1> bbs:doors/cli-pager3/cli-pager3\n2> bbs:commands/bbscmd/o.info\n3> bbs:doors/cli-pager/cli-pager3.doc\n4> bbs:doors/cli-pager3/cli-pager3.pic\n\nDeffinition of contents\n\n1> The main executable for cli-pager3\n2> The .info icon to execute the door from /x (o)pperator page\n3> This Documentation\n4> The output ansii (check it out!!)\n\n-----------------------------------------------------------------------------\n                          \n                          Installing CLI_PAGER3\ngo to shell Type\n\nshell> makedir doors:cli-pager3\nshell> copy ram:bbs/doors/cli-pager3/#? doors:cli-pager3/\nshell> copy ram:bbs/commands/bbscmd/o.info bbs:commands/bbscmd/\n\nTHIS INSTALLATION PRESUMES YOU HAVE EXTRACTED THE ARCHIVE TO RAM:\n\nTHIS ABOVE INSTALATION REQUIRES YOU TO HAVE YOUR COMMANDS DIR INSTALLED \nWITHING YOUR BBS DIRECTORY. AND ALSO TO HAVE ASSIGNED DOORS: DIRECTORY.\n\nTHERE ARE SIMPLY TO MANY VARIATONS ON BBS SETUPS, SO I HAVE INCLUDED ONLY\nTHE MOST COMMON. YOU SHOULD BE ABLE TO FIGURE IT OUT.\n\nCLI-PAGER3 should now be installed.\n\nType O at the commands line to test it out.\n\n----------------------------------------------------------------------------\nGREETINGS AND HELLOS AND ALL THAT TO FOLLOW.\n\nMAGE/CLIQUE           - GOOD TO SEE COASTAL CARNAGE IS STILL PUMPING\nBODYCOUNT/CLIQUE      - THE SMASHING CONTINUES /CLIQUE\nWARCHILD/IND          - HEY CUZ :))\nGRUDGE/IND            - THANKS FOR YOUR WEIRD TEXT\nMAUD`DIB/MST          - DAMM THAT VIRUS. I BEEN GETTING SOME BAD CONNECTS\nKILLRAVEN/MST         - WELL ARE WE.. AND I THINK YOU SHOULD SAY YES!\nLORD/ABSOLUTE!        - YO MAN.. LETS SMOKE THAT VODKA\n243/RYL/N&B/CRUX/FLT  - SO THATS QUITE A FEW TITLES YOU HAVE THERE BONER :)\nBOWEN/SKIDROW/MOTION  - LETS CLEAN EM UP MATE\nPSYCHE/DEVIOUSDESIGNZ - LIKE YOUR LAST COLLECTION WITH ACID KID\nACIDKID/HONEY         - YOUR ONE FAST DUDE THESE DAYS. GLAD I COULD HELP\nSTICKYFINGAZ/CLIQUE   - YOUR A HARD MAN TO BEAT :)\nKURGAN/CLIQUE         - LOOKING FOR A GROUP HEY???\nDARTAGNAN/CLI/OTT/HNY - NICE RELEASES OF LATE KEEP IT UP IF YOU CAN\nRANCID/AFL/ABS!       - WHAT HAPPENING WITH YOUR LADY MAN.. AND CHANCES??\nCOUNTZER0/OGN/AC!/HNY - .C .C .C .C NO MATE .S .S .S .S  :)\nMUTHA/IND             - SOUND STUDIO DELUXE IS IN THE HOUSE :)\nNETRUNNER/PEARL       - I WANT MORE . GIVE ME MORE! A!\nBEAST/IKON VISUAL     - ITS THAT NUMBER AND NOW ITS A BOARD. BUT YOU #1\nWARRIOR/INSOMNIA      - I CANNOT FOR THE LIFE OF ME CONNECT TO YOUR BOARD\nORACLE/IND            - YOUR THE GREATEST TEACHER ANYONE WANTS\n\nAND ALL THE REST WHO MAY OF SLIPPED FROM MY MIND LATE THIS THURSDAY NIGHT.\n\n                                  .  .. ... .. .......     .\n                   ....        :  ­              ::::: ....­\n­c­l­i­q­u­e­      ::::        ª__:    -DtN      ::::: ::::._____:\n                 ___:::        (__)       ___    ::::: ::::|___  :\n               _µ^»  ::        ­  ª    _µ^»=m*._ ::::: ::::|  |__ª\n           _µP    _/:::        ª  |  _µP       ¼#::::: ::::|  __/.\n          µõ       :::: .......:  | µõ          w_:::: ::::|  | »­\n         JP        :::: :::::::|  |JP           JP:::: ::::|  |  |\n        JF         :::: :::::::|  JF            3r:::: ::::|  |  |\n        J          :::: :::::::|  J        .Ì   rj:::: ::::|  ª  |\n        J#         :::: :::::::|  J#       JF  µ .:::: ::::|  :  ª\n  «     JF,     _, :::: :::::::|  ªJF,     _7Fõ  ::::: :::::  ­  :    «\n<---->     õ===*õ» ::::.:::::::ª__:  õ===*õ»»¬   `::::.::::­_____­  <---->\n  C!               `:::::::::::''  :          ¨¼¨  `:::::::''.     .   oTt¡\n                                 :  .                        ­\n\n              n­e­e­d­  ­w­e­  ­s­a­y­  ­m­o­r­e­  . . . . . . .\n','\n',char(10)),NULL,NULL,9455,6,0,NULL,NULL,'cli_pg3r_cli_pager3','scan',1780048448);
INSERT INTO door_catalog VALUES('cli_quik','CLI-QUIK.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CLI-QUIK.LHA','CLI-QUICK','XIM','+  ___________.  ____ ___.____.________    +',NULL,NULL,'CLI','\_   ___/  |_(____)   )_|  |   _____) ---+/   /__|  |  \  /  O  /|__ \_ ____/+---> | :\_____/|______\/__   /____| /_____): |',replace('+  ___________.  ____ ___.____.________    +\n   \_   ___/  |_(____)   )_|  |   _____)\n---+/   /__|  |  \  /  O  /|__ \_ ____/+--->\n | :\_____/|______\/__   /____| /_____): |\n | `--------pReSeNtz-.\_/.---.|/.-+bC!+'' |\n\|/                  `---''   `--''       \|/\n V  ++    TRESPASS /X DOOR DEZIGN    ++  V\n\n CLi-QUICK IS A QUICK LOGIN TOOL FOR /X BBS\n  SYSTEMS. NICE OUTPUTS AND COOL COLOURS!!\n','\n',char(10)),'CLI-QUICK.DOC',replace('                                    .  .. ... .. .......     .\n                     ....        :  ·              ::::: ....·\n  ·c·l·i·q·u·e·      ::::        ¦__:    -DtN      ::::: ::::._____:\n                   ___:::        (__)       ___    ::::: ::::|___  :\n                _æ^¯  Þ::        ·  ¦    _æ^¯=m*._ ::::: ::::|  |__¦\n             _æP    _/:::        ¦  |  _æP       ¬#::::: ::::|  __/.\n            æ°       :::: .......:  | æ°          w_:::: ::::|  | ¯·\n           JP        :::: :::::::|  |JP           JP:::: ::::|  |  |\n          JF         :::: :::::::|  JF            3r:::: ::::|  |  |\n          J          :::: :::::::|  J        .É   rj:::: ::::|  ¦  |\n          J#         :::: :::::::|  J#       JF  æ .:::: ::::|  :  ¦\n    ©®     JF,     _,:::: :::::::|  ¦JF,     _7F°  ::::: :::::  ·  :    ©®\n  <---->     °===*°¯ ::::.:::::::¦__:  °===*°¯¯Þ¶  `::::.::::·_____·  <---->\n    C!               `:::::::::::''  :          ´¬´  `:::::::''.     .   oTt­\n                                 :  .                        ·\n                                 .\n\n                                /X DOOR DESIGN\n\n                    ANOTHER XIM DOOR BY TRESPASS/CLIQUE\n\n                          THIS TIME IT IS CLI-QUICK\n\n\n-----------------------------------------------------------------------------\n                            \n                            WHAT IS CLI-QUICK\n\nCLI-QUICK is a quick Logon door for amiexpress bbs. It gives the user three\noptions of how to logon the bbs or the sysop 4.\n\n[1] qUICK lOGON\n[2] sHORTENED lOGON\n[3] nORMAL lOGON\nAnd [4] (which is not shown on the menu) Ultra Quick Logon (sysop Only)\n\n-----------------------------------------------------------------------------\n\n                         DEFFINITION OF CONTENTS\n\n1> BBS:DOORS/CLI-QUICK/CLI-QUICK\n2> BBS:DOORS/CLI-QUICK/CLI-QUICK.DOC\n3> BBS:DOORS/CLI-QUICK/CLI-QUICK.PIC\n4> BBS:DOORS/CLI-QUICK/MODE1.TXT\n5> BBS:DOORS/CLI-QUICK/MODE2.TXT\n6> BBS:DOORS/CLI-QUICK/MODE3.TXT\n7> BBS:DOORS/CLI-QUICK/MODE4.TXT\n8> BBS:COMMANDS/SYSCMD/CLI-QUICK.INFO\n\nExplanation of above files.\n\n1> The main executable for CLI-QUICK\n2> This documentation (WOW!)\n3> An Iff output of the display screen (check it out)\n4> Quick loggin text\n5> Shortened Loggin text\n6> Normal Loggin text\n7> Sysop Loggin text\n8> The .info icon to start CLI-QUICK\n\n-----------------------------------------------------------------------------\n\n                       INSTALLING CLI_QUICK\n\ngo to shell type\n\nshell> makedir doors:cli-quick\nshell> copy ram:bbs/doors/cli-quick/#? doors:cli-quick/\nshell> copy ram:bbs/commands/syscmd/cli-quick.info bbs:commands/syscmd/\n\nTHIS INSTALLATION PRESUMES YOU HAVE EXTRACTED THE ARCHIVE TO RAM:\n\nTHIS ABOVE INSTALATION REQUIRES YOU TO HAVE YOUR COMMANDS DIR INSTALLED \nWITHING YOUR BBS DIRECTORY. AND ALSO TO HAVE ASSIGNED DOORS: DIRECTORY.\n\nTHERE ARE SIMPLY TO MANY VARIATONS ON BBS SETUPS, SO I HAVE INCLUDED ONLY\nTHE MOST COMMON. YOU SHOULD BE ABLE TO FIGURE IT OUT.\n\n*THE MODE.TXT FILES*\n\ncut here------------------------------------------MODE1.TXT-------------\n~SS_BBS:SCREENS/NEWUSER.TXT\n~CR\n~CC_LOST\n~CC_CHART\n\ncut here------------------------------------------MODE2.TXT-------------\n~SS_bbs:screens/clique!.txt\n~CR\n~CC_WEEK\n~CR\n~SS_BBS:SCREENS/NEWUSER.TXT\n~CR\n~SS_BBS:SCREENS/NEWUSER.TXT\n~CR\n~CC_LOST\n~CC_CHART\n\ncut here------------------------------------------MODE3.TXT--------------\n~SS_bbs:screens/clique!.txt\n~CR\n~SS_BBS:SCREENS/2LAST10.TXT\n~CR\n~CC_KB-DETECT\n~CR\n~CC_WEEK\n~CR\n~SS_BBS:SCREENS/NEWUSER.TXT\n~CR\n~CC_LOST\n~CC_WALL\n~CC_CHART\n\ncut here------------------------------------------MODE4.TXT-------------\n~SS_BBS:SCREENS/NEWUSER.TXT\n~CR\n\n\n I guess You can see how these work... Useing MCI commands to call teh\ndifferent doors/text files. Install these as \n\n1> QUICK      - Maybe new users and last callers only\n2> SHORTENED  - New user ,last callers, baud and Best Ul''s\n3> NORMAL     - The usual last callers, top 10 worst 10 etc etc\n4> SYSOP      - New users only\n\nUse MCI commands and dont use the supplied ones as they are set for my bbs.\n\n\nEdit your text BBS:nodeX/bull.txt to have this and only this.\n\n~CC_CLI-QUICK\n\n(remember add any other doors you may want to execute into the MODE(x).TXT''s)\n\nThis will then exexute CLI-QUICK every time a user logs onto that nodeX.\n\nCLI-QUICK should now be installed.. Do a local login and test it out.\n\n-----------------------------------------------------------------------------\n\n\nGREETINGS AND HELLOS AND ALL THAT TO FOLLOW.\n\nMAGE/CLIQUE           - GOOD TO SEE COASTAL CARNAGE IS STILL PUMPING\nBODYCOUNT/CLIQUE      - THE SMASHING CONTINUES /CLIQUE\nWARCHILD/IND          - HEY CUZ :))\nGRUDGE/IND            - THANKS FOR YOUR WEIRD TEXT\nMAUD`DIB/MST          - DAMM THAT VIRUS. I BEEN GETTING SOME BAD CONNECTS\nKILLRAVEN/MST         - WELL ARE WE.. AND I THINK YOU SHOULD SAY YES!\nLORD/ABSOLUTE!        - YO MAN.. LETS SMOKE THAT VODKA\n243/RYL/N&B/CRUX/FLT  - SO THATS QUITE A FEW TITLES YOU HAVE THERE BONER :)\nBOWEN/SKIDROW/MOTION  - LETS CLEAN EM UP MATE\nPSYCHE/DEVIOUSDESIGNZ - LIKE YOUR LAST COLLECTION WITH ACID KID\nACIDKID/HONEY         - YOUR ONE FAST DUDE THESE DAYS. GLAD I COULD HELP\nSTICKYFINGAZ/CLIQUE   - YOUR A HARD MAN TO BEAT :)\nKURGAN/CLIQUE         - LOOKING FOR A GROUP HEY???\nDARTAGNAN/CLI/OTT/HNY - NICE RELEASES OF LATE KEEP IT UP IF YOU CAN\nRANCID/AFL/ABS!       - WHAT HAPPENING WITH YOUR LADY MAN.. AND CHANCES??\nCOUNTZER0/OGN/AC!/HNY - .C .C .C .C NO MATE .S .S .S .S  :)\nMUTHA/IND             - SOUND STUDIO DELUXE IS IN THE HOUSE :)\nNETRUNNER/PEARL       - I WANT MORE . GIVE ME MORE! A!\nBEAST/IKON VISUAL     - ITS THAT NUMBER AND NOW ITS A BOARD. BUT YOU #1\nWARRIOR/INSOMNIA      - I CANNOT FOR THE LIFE OF ME CONNECT TO YOUR BOARD\n\nAND ALL THE REST WHO MAY OF SLIPPED FROM MY MIND LATE THIS THURSDAY NIGHT.\n\n                                  .  .. ... .. .......     .\n                   ....        :  ­              ::::: ....­\n­c­l­i­q­u­e­      ::::        ª__:    -DtN      ::::: ::::._____:\n                 ___:::        (__)       ___    ::::: ::::|___  :\n               _µ^»  ::        ­  ª    _µ^»=m*._ ::::: ::::|  |__ª\n           _µP    _/:::        ª  |  _µP       ¼#::::: ::::|  __/.\n          µõ       :::: .......:  | µõ          w_:::: ::::|  | »­\n         JP        :::: :::::::|  |JP           JP:::: ::::|  |  |\n        JF         :::: :::::::|  JF            3r:::: ::::|  |  |\n        J          :::: :::::::|  J        .Ì   rj:::: ::::|  ª  |\n        J#         :::: :::::::|  J#       JF  µ .:::: ::::|  :  ª\n  «     JF,     _, :::: :::::::|  ªJF,     _7Fõ  ::::: :::::  ­  :    «\n<---->     õ===*õ» ::::.:::::::ª__:  õ===*õ»»¬   `::::.::::­_____­  <---->\n  C!               `:::::::::::''  :          ¨¼¨  `:::::::''.     .   oTt¡\n                                 :  .                        ­\n\n              n­e­e­d­  ­w­e­  ­s­a­y­  ­m­o­r­e­  . . . . . . .\n','\n',char(10)),NULL,NULL,12214,5,0,NULL,NULL,'cli_quik_cli_quick','scan',1780048448);
INSERT INTO door_catalog VALUES('clott135','CLOTT135.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CLOTT135.LHA',NULL,'XIM','Caller lottery',NULL,NULL,NULL,NULL,replace('Caller lottery\n','\n',char(10)),'Clottery.doc',replace('\n                               Callers Lottery\n                               ~~~~~~~~~~~~~~~\n                             by: Goofy/Anathema\n\n\nWhat does it do ?\n~~~~~~~~~~~~~~~~~~\n\nIt allows your users to win Download creds simply by calling....\nand hopefully you will hafve more calls/day...\n\n\nHow to Install it ?\n~~~~~~~~~~~~~~~~~~~\n\nPut the Clottery.AE file in your DOORS: dir...\n\nThen simply install the Door as a AREXX program in a textfile thats shown\nto every Users thats login on 1 time/logon using MCI....\n\nThe door will also create a Configfile that you can edit... you will find it\nin your S: dir..  A good thing to do is to change the Path to the\nCallwinners Bulletin.. Default is in RAM:....\n\n\nSorry for this QUICK doc.. but ive lost the original Doc and i dont\nhave the time to write a new one at the time...\n\n\nIf you wanna contact me or perhaps your intrested in joining Anathema\nthen make a call to one of our boards !\n\n\nLOYD BBS       +46-300-64661 [Tempest]\nMINOR MISHMASH +46-31-992525 [Amixpress]\nACES HIGH   #1 +46-410-44886\n            #2 +46-410-46577\n\n\n','\n',char(10)),NULL,NULL,3342,4,0,NULL,NULL,NULL,'scan',1780048448);
INSERT INTO door_catalog VALUES('cn_hpv1','CN-HPV1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CN-HPV1.LHA','Hackers','XIM','Hackers',NULL,NULL,'CN','___:\ ____\  | \-------------------------------. /^ _/ \   / nEW sYSTEM-pASSWORD dOOR -/X  +',replace('         .\n      ___:\\n  ____\  | \-------------------------------.\n /^ _/ \   / nEW sYSTEM-pASSWORD dOOR -/X  +\n/   \/\/ . \ gIVES oPTION tO dOWNLOAD iNFO :\n\________|  \ oN BBS tO cURRENT gUEST uSER +\n+--------|___)---» hACKER''s pARADISE ^-----''\n','\n',char(10)),'HP.Guide',replace('A cYbErDyNe/nEXUS/rEAXtIoN Production for ''98.\n\nIRC: (ca/uk/jp)us.undernet.org 6667/6668 #AMIGA\n\nMail above at: RoToGEN : (+44) 0171 FIND IT!!\n\nThis is a small door for  /X  that  kinda  replaces  the\nSYSTEM-PASSWORD  function. But not entirely, all it adds\nis  the  ability  to  download a file at logon. Plus the\nway I have presented it will scare off the  lamers  that\ninfest  our  world.  Of  course, you can change the menu\nand download message to whatever you want. Your choice.\n\nInstallation:\nThrow all the files where they should be.\nIf you can''t then you''re one of the previous people.\n\nIf you have NOT added the system-password function  then\nfollow these instructions:\n\n(1) Find the ''node(x).info'' that your users logon to.\n(2) Add the tooltype: STEALTH_MODE\n(3) Add the tooltype: SYSTEM_PASSWORD=(whateveryouwant)\n\nNormally,  ha, /X searches for the PRIVATE.TXT screen in\nBBS:SCREENS. If that isn''t the  case  with  your  system\nthen /X will tell you where to put it. Do it yourself.\n\nMessage.txt <-- What the guest user can download.\nRewrite it as you please. Keep name the same.\n\nAnd that''s about all there is to it.\nSo I can f*ck off now.\n\nGreetz oot to:\n               JUnKSHuN    <--- Bastard!\n               HeDphONeS   <--- Bigger Bastard!\n               GGT-kEEPER  <--- General f*ck-head!\n\nHey, I''m kidding here. I''d be f*cked without these guys!\n\nThere  should  really  be  more  to  this program, but I\nached over what other options should be available  to  a\nguest  loggin''  on...and  came  up with shit. So mail me\nwhen ya see  me  and  we''ll  turn  this  into  something\nbetter. Which will take a miracle or ten.\n\n\n','\n',char(10)),NULL,'auto-added',14469,1,0,NULL,NULL,'cn_hpv1','scan',1780048448);
INSERT INTO door_catalog VALUES('cnfscn26','CNFSCN26.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CNFSCN26.LHA','ConfScan','XIM','AmigaGuide',NULL,NULL,NULL,'\__ ¬\/¬\\__ ¬Y \__  __\_____¬\__ ¬\__    ¬\ /¬      \/\  l  /\   ¬\/    ¬\/¬\__/¬  \__/ /   \  /  \ \   /  \    \      \   ¬\   / ¬\',replace('_____  _ _____ ____________________________ \n\__ ¬\/¬\\__ ¬Y \__  __\_____¬\__ ¬\__    ¬\\n /¬      \/\  l  /\   ¬\/    ¬\/¬\__/¬  \__/\n/   \  /  \ \   /  \    \      \   ¬\   / ¬\\n\___/\/    \___/    \_   \_____/     \_____/\n|----(______)-(___________)-(_________)ppx-|\n| CONFERENCE SCAN v2.6 - iNTERMEDiATE REL. |\n+------------------------------------------+\n| o Ami-Express 3.38+ and 4.x Compatible!  |\n| o Remembers flagged files after log off! |\n| o Much more! Read inside!                |\n`-----------------------[KiLLraVeN/MYSTiC]-''\n','\n',char(10)),'ConfScan.Guide',replace('@DATABASE "ConfScan.GUiDE"\012@REMARK .------------------------------------------------------------------.\012@REMARK | This document is written in AmigaGUiDE format, so please read it |\012@REMARK | with AmigaGUiDE or your favourite guide reader.... ciao now...   |\012@REMARK `------------------------------------------------------------------''\012@REMARK $VER: ConfScan v2.6.06\012@WiDTH 80\012@NODE MAiN "Guide to ConfScan v2.6.06 - /X-PoWeR! - Written by KiLLrAvEn/MYSTiC"\012                               Guide to ConfScan\012                     for Ami-Express Bulletin Board Systems\012\012                          Program version: 2.6.06\012              Compilation Date/Time: Oct 7th 1994 - 23:21:06\012\012                         © 1993-94 by @{"KiLLRaVeN/MYSTiC" link Killraven}\012                          ASM Coding by ArCaDe/MYSTiC\012\012                ... another fine MYSTiC /X PoWeR! production...\012\012                 @{"      READ THiS FiRST FOR THE LATEST iNFO!     " link Important}\012\012                 @{"    Introduction    " link introduction}      @{" History of ConfScan " link History}\012                 @{"     Features!      " link     Features}      @{"    Known Bugs       " link Bugs}\012                 @{"    Requirements    " link Requirements}      @{" Possible error msgs " link Errors}\012                 @{"    Installation    " link installation}      @{" Future improvements " link Future}\012                 @{"    Configuration   " link Configuration}      @{"     Greetings       " link Greetings}\012                 @{"  Usage (by users)  " link        Usage}      @{"  Registered users!  " link Registration}\012\012                 @{"    ConfScan_DL     " link ConfScan_DL }      @{"     KiLLER iNFO     " link KiLLER}\012@EndNode\012\012@Node Introduction "Introduction to ConfScan - /X-PoWeR! - Written by KiLLrAvEn/MYSTiC"\012                     - - ­ ­ ­ [ iNTRODUCTiON ] ­ ­ ­ - -\012\012   Welcome to ConfScan!\012\012   ConfScan  was  written  during a period of 1 year and has become quite\012   a  powerful  program  with  many possibilities and great potential.  I\012   have spent a lot of time programming and testing it so I hope you will\012   like it and use it with pleasure.\012\012   A little bit of history...\012\012   At first ConfScan was merely meant as a small util that enabled sysops\012   to  easily  check  what  was uploaded in all the different conferences\012   without  having  to  join them one by one.  The very first version did\012   nothing  more  than  that.  That was version 1.0.  It was never really\012   released but to a few friends.\012\012   Nowadays ConfScan can perform a much greater task than just displaying\012   some  filenames  on  the  screen.  ConfScan can now be used to control\012   some  main  parts  of  the  bulletin  board  system Ami-Express.  With\012   ConfScan  you  can  scan for new files, view them from within ConfScan\012   and you can even Nuke files with ConfScan.  Usage of ConfScan has been\012   made as intuitive as possible and should be very easy to use.\012\012   ConfScan  is  an  intelligent program, detecting the options for every\012   user  using  ConfScan, not showing options that they don''t have access\012   for.   ConfScan  also recognizes Ami-X Net conferences that usually do\012   not have file bases, as a result these conferences without a file base\012   are not shown in the config menu (''CS W'').\012\012   ConfScan  comes  with  a  highly user friendly GUi Config program!  No\012   more  tooltypes  to fill in by the sysop!  Just start the program from\012   the CLi or Workbench and CLiCK the options you want and save''m!\012\012   ConfScan  is  made  in a way that you don''t have to repeat information\012   that  is  already known is other files or icons.  ConfScan knows where\012   to find it and will use it.  But in my opinion that is something every\012   program  should  support.   Besides that, if you have any problem with\012   ConfScan  you  can  always reach me for support, I am offering support\012   for all registered sysops of Ami-Express, FOR FREE!\012\012   But  not only for you, the sysop, ConfScan is a must.  Your users will\012   also  appreciate  it  since  ConfScan  allows users to tag their files\012   instead  of  flagging them (but they can still flag files if they want\012   to  ofcourse)  and  ConfScan  enabled  them  to  download  files  from\012   different   conferences  without  having  them  to  jump  through  the\012   conferences  by  theirselves.   in  the  near  future, it will also be\012   possible  to  download all files from all conferences in one time!  So\012   look out for the coming version!\012\012   ConfScan also offers your users a large configurability.  ConfScan has\012   a Config Menu built in so they can easily adjust their preferences.\012\012   A seperate Download door enables you to put restrictions on downloads.\012   With  the  GUi  Config  program  you can easily exclude conferences or\012   nodes from downloading.  You can put accesslevels on nodes/conferences\012   or  even  use userlists for download access on nodes/conferences.  And\012   all  this  information is again saved by the Config program, so you do\012   not have to fill in any tooltypes (GUi Config does that for you).\012\012   if  this  sounds  like  a  useful  program in your ears, check out the\012   @{"features" link features} to find out more.  Or at least start the GUi Config.\012\012                                                        @{"-KiLLrAvEn/MYSTiC" link Killraven}\012\012@EndNode\012\012@Node Requirements "What DO you need? - /X-PoWeR! - Written by KiLLrAvEn/MYSTiC"\012                   - - - ­ ­ ­ [ REQUiREMENTS ] ­ ­ ­ - - -\012\012   The  requirements can differ a lot since you can setup ConfScan anyway\012   you  like,  but  if  you  want to use ConfScan to the fullest you need\012   this:\012\012   · @{" Ami-Express BBS " link Ami-X} version 3.38+ (/X 4.x is supported)\012   \012     YOU NEED VERSiON 3.38 OR HiGHER TO RUN THiS PROGRAM, PLEASE OBTAiN\012     THE LATEST VERSiON FROM YOUR DEALER (SEE "AMi-EXPRESS BBS").\012\012   · @{" Clean dir files " link CleanDir}\012\012   For the support of [V]iewing files you need to have in your C: dir\012   · DMS\012   · LHA\012   · UNZiP\012\012   If you want to be able to nuke files with ConfScan you need to have\012\012   · @{" KiLLER " link KiLLER}\012\012   installed on your system.\012\012@EndNode\012\012@Node CleanDir "VERY iMPORTANT! READ THiS! - By KiLLraVeN/MYSTiC"\012                 - - - ­ ­ ­ [ CLEAN DiR FiLES ] ­ ­ ­ - - -\012\012   This  may sound obvious, but to get the most out of ConfScan, you need\012   to  have  clean  dir files.  So no taglines or any other alien text in\012   your dir files.\012\012   There is one exception on the other hand, there is one program you are\012   allowed to use to alter your dir file and that is DirStyle by The Bird\012   of  TRSi.   Support  for this dirstyler is built in to ConfScan.  This\012   was  done  after a request from Sal-One/TRSi.  If you have a dirstyler\012   that  you  would like to have support for, contact me and maybe we can\012   work something out.\012\012   Nukers on the other hand cause no problems.  You are free to use them,\012   even better, there is support for two nukers:  BossNuke and KiLLER.\012\012   "What  can  go  wrong  if I use a dirstyler?" you might wonder.  Well,\012   there  is  one thing that can go wrong; file-tagging.  ConfScan uses a\012   algorithm  to  recognize  filenames in the dir-file.  But if you use a\012   dirstyler  that  puts text where normally filenames are, ConfScan will\012   see that text as a filename.\012\012   If  you  still want to use that dirstyler, you can turn of the tagging\012   with the Config program (see @{"Configuration" link Configuration}).\012@EndNode\012\012@Node Installation "How to get it working - /X-PoWeR! - Written by KiLLrAvEn/MYSTiC"\012                    - - - ­ ­ ­ [ iNSTALLATiON ] ­ ­ ­ - - -\012\012   To install ConfScan, simply double-click on the install-ConfScan icon.\012\012   Installation  will  proceed  with  the  C=  installer.   Help has been\012   provided  in  the  installer  program,  so  no  need  to  repeat  that\012   information in here.\012\012   What can you do with the installer? The installer script will:\012\012   · Allow  you  to  install  the  ConfScan  main  executable  (ConfScan\012     itself).  You can choose either for the 68000 or 680x0 version.\012\012   · Allow you to install the ConfScan_DL Download door that  is  needed\012     for Ami-Express to recognize any flagged/tagged  files.   This  one\012     comes in just one flavour, 68000.\012\012   · Allow you to install the ConfScan_G door which checks if users have\012     flagged  files  still  not  downloaded  before they logoff (a small\012     patch for the original ''G'' door, nothing special).\012\012   · Allow  you to install the help files that come with ConfScan.  Such\012     files are needed to give help to users that use ConfScan.  They can\012     get  access  to  these  files  by putting a question mark after the\012     command (ie.  `N ?'').\012\012   · Allow  you to install the fully GUi Configuration program (Config).\012     This  program  will  allow  you  to  mold ConfScan to your personal\012     needs.   Here you can set all pre-defined preferences, such as ANSi\012     support,  show  new  dates  etc.   etc.  But this is also the place\012     where  you  can  set  download restrictions and exclude conferences\012     from being scanned.  And much more!\012\012   · Allow you to install this guide. You are reading it now.\012\012   · Let  you  choose  as  which  command  you  can to install ConfScan.\012     ConfScan  can  act like 3 different commands, `N'', `F'' and `CS''.  I\012     suggest  you install it as all 3 functions, but if you want you can\012     skip the `CS'' door ''cause it is built-in in `N'' also.\012\012   · Let  you  select the place where you want to install ConfScan.  The\012     default  destination  is  "DOORS:" but you are free to put it where\012     you  want  (the  destination  will  be  put  in  the  command icons\012     afterwards).   Remember,  a directory `ConfScan'' will be created in\012     that directory!\012\012   · Let  you  select  the  name  of  the  command  that the ConfScan_DL\012     download  door will be installed under.  I strongly suggest you put\012     it under the ''D'' cause otherwise users will not be able to download\012     anything ;)\012\012   · Let  you select the place where you want to install the Ami-Express\012     commands.\012     (Default: BBS:Commands/BBSCmd/).\012\012   · Let you set the minimum level required to use any of the ConfScan\012     related commands.\012     (Default: 20).\012\012   · Let  you  set the priority ConfScan will get when executed (only if\012     you  are  an  expert user).  If you are running a multinode system,\012     please  set  it  to 0, otherwise users on the other nodes will have\012     hindrance  from  it  if  you  give  it +1.  Systems with 1 node can\012     easily set it to +1 or +5 for maximum performance.\012     (Default: 0).\012\012   · Ask for the directory where you keep your ACP.info.  This is needed\012     for the Config program.\012\012   · Start the Config program for you so you can configure ConfScan.\012\012   All  commands will get a stack of 50,000 and will be set to multinode.\012   As ConfScan is written in C and ASM, it will be installed as a XiM.\012   \012   If  you want ConfScan installed under another name than `CS'', you will\012   have  to  do  it by hand.  But you can still use the installer.  After\012   installation,  simply rename the CS.info icon in your BBS:Commands/...\012   directory  to  whatever  you  want  (for example, `SCAN'').  This will,\012   however,  force  you  to rename some of the help files as well (rename\012   every file that has ".CS." in it to ".SCAN.").\012@EndNode\012\012@Node Configuration "Config - For easy configuration - KiLLraVeN/MYSTiC"\012                  - - - ­ ­ ­ [ CONFiGURATiON ] ­ ­ ­ - - -\012\012   ConfScan  comes  with an external configuration program called Config.\012   It  is  fully  GUi  so  no more stupid textfiles to create or icons to\012   fill.   Just  start  the  program  and  away  you  are.  Here are some\012   guidelines where you can find some stuff and what it all means.\012\012\012              ^-[ ACCESS LEVELS ]-^\012\012   Hold Access       ­ Every user with an access level equal to or higher\012                       than  the  value  you enter here, is able to watch\012                       the contents of the hold dirs.\012                       (Default:  250).\012\012   View Access       ­ Every  user with an access level >= than the value\012                       you  enter  here,  is  able to view files that are\012                       shown  in  the  dir  file.   You can specify which\012                       filetypes   are  supported  via  the  View  prefs.\012                       (Default:  20).\012\012   KiLL Access       ­ Every  user with an access level >= than the value\012                       you  enter  here,  is  able  to  flag/tag files as\012                       KiLLER  targets.  This is for usage with the nuker\012                       @{"''KiLLER''" link KiLLER}.\012                       (Default:  250).\012\012                ^-[ iNTRO FiLE ]-^\012\012   Intro file        ­ The  filename that you can specify here (either by\012                       entering the filename in the text box or selecting\012                       it  with ''S'') will be the name of the file that is\012                       shown at every startup of ConfScan.  At the moment\012                       you  can enter no variables (such as time/date and\012                       place).\012                       (Default:  <none>).\012\012         ^-[ DEFAULT USER PREFERENCES ]-^\012\012   These are the values that are used if an user does not have his or her\012   own private configuration for ConfScan.\012\012   ANSi Colours      ­ This  option  turns the colours on or off when the\012                       files  are  showed  in your screen.  You can setup\012                       those colours via the `Colours'' button.\012                       (Default: Off)\012\012   Show Sent-by      ­ By  default,  ConfScan  will  filter  out any file\012                       description  lines  that  start  with  ''Sent by:''.\012                       They  are  usually not interesting for users.  But\012                       with  the  latest File_iD''s and SentBy''s you don''t\012                       know what to expect anymore.\012                       (Default: Off)\012\012   Show New Dates    ­ Every time a new date is detected, a little banner\012                       will be displayed informing you of the new date.\012                       (Default: Off)\012\012   Clear Screen      ­ After  *every*  prompt, the screen will be cleared\012                       if  you  turn  this option on.  This speeds up the\012                       display  on  screen  quite  a  bit, esspecially on\012                       local nodes, try it.\012                       (Default: Off)\012\012   Lines b/files     ­ Some  users  find  it  usefull  to have a line put\012                       between all the files.  This does the trick.\012                       (Default: Off)\012\012   Pause b/confs     ­ This   will   put  a  pause  banner  between  each\012                       conference that has got new files.\012                       (Default: Off)\012\012   Return b/files    ­ Some  users  find it usefull to have an empty line\012                       between  all  the  files.  If you''ve got the time,\012                       use  it,  it  makes  it  easier  to detect all the\012                       different files.\012                       (Default: Off)\012\012   One line per file ­ If  you  turn  this on, just the first line of the\012                       file description will be shown.  Very handy if you\012                       want to tag a lot of files FAST.\012                       (Default: Off)\012\012   Always full desc. ­ This   will   prevent   file  descriptions  to  be\012                       displayed broken on your screen.  Turn this on and\012                       from  *every*  file you will always get to see the\012                       entire   file   description.   This  mode  can  be\012                       overridden with the [P] at the flag-prompt.\012                       (Default: Off)\012\012   Future expansion  ­ Guess what? Not used.\012\012               ^-[ SYSOP PREFS ]-^\012\012   This  is  where you set all the internal preferences ConfScan will use\012   while operating.  It more or less controls the engine of ConfScan.\012\012   Copy dirfiles     ­ With  multiple node systems, this is a must!  This\012                       will   first  copy  your  dirfile  to  T:   before\012                       searching   it  for  a  file  date.   This  allows\012                       multinode support.\012                       (Default: Off)\012\012   Callerslog        ­ Every  time ConfScan is started and this option is\012                       activated,  it  will  be logged in the callerslog.\012                       (Default: Off)\012\012   Use Percentage    ­ A  nice feature of ConfScan is, that it is capable\012                       of  showing  a  percentage  (%)  on  screen  while\012                       searching  the  dirfiles.  If you don''t want this,\012                       turn this option off.\012                       (Default: On)\012\012   Nuker Support     ­ ConfScan  is  also able to recognize comments made\012                       with   nukers.   Currently  supported  nukers  are\012                       BossNuke  and  KiLLER.   But any comment placed on\012                       the  spot where normally the file-size is, will be\012                       seen  as  a nuker comment.  Any nuker comment will\012                       be  display  with a dark-blue background and white\012                       characters.   If  you  don''t  want that to happen,\012                       turn this off.\012                       (Default: On)\012\012   Allow Tagging     ­ @{"Tagging" link Tagging}  is  a  thing  of the day, ConfScan had it\012                       first!   If,  for some reason, you don''t want your\012                       users to tag files, turn it off.\012\012                       Another  reason  why  you want to turn this option\012                       OFF  is  because you use a @{"dirstyler" link CleanDir} that confuses\012                       ConfScan in it''s file-recognition algorithm.\012                       (Default: On)\012\012           ^-[ iGNORED CONFERENCES ]-^\012\012   Any  conference you put in this listview will NOT be seen by ConfScan.\012   That  means  that  it will not scan the conference for new files (CS),\012   not will it be shown when the users wants to set his/her config.\012\012   You  can  add  a conference with "Add Conf", a list will appear of all\012   your conference and simply click on the one you want to add.\012\012   To remove a conference, select the one you want to remove and click on\012   "Del Conf".  Izze simple.\012\012                 ^-[ COLOURS ]-^\012\012   If  you  click  on  the [Colours] button, you will get a new window in\012   which you can enter the colours for the file listing.\012\012   The  values  you  can enter are ANSi ESC colour codes, here is a brief\012   display of all colours:\012\012             BLACK = 30 - RED    = 31 - GREEN = 32 - YELLOW = 33\012             DBLUE = 34 - PURPLE = 35 - LBLUE = 36 - WHiTE  = 0\012\012   Filename          ­ Colour of the filenames.\012                       (Default: 36)\012\012   Status            ­ Colour of the file status (P = Passed, etc.).\012                       (Default: 35)\012\012   File Size         ­ Size of the file (no, really?).\012                       (Default: 33)\012\012   File Date         ­ Date of the file (no kidding?).\012                       (Default: 31)\012\012   Description       ­ Colour that will be used for the file description.\012                       Mind  you  that  this ESC sequence will be sent at\012                       the  start  of  the  file description.  That means\012                       that  if  there is an ANSi colour code in the file\012                       description, the remainder of the file description\012                       will  be  in  THAT  colour  code  and not that you\012                       specify here.\012                       (Default: 0)\012\012                       NOTE:   Although ESC[37m is also the ANSi code for\012                       white,  Ami-Express fails to handle this correctly\012                       cause  the  local  node  will show RED (while your\012                       users  will  actually  have  white).  But by using\012                       ESC[0m you can circumvent this problem.\012\012                ^-[ ViEW PREFS ]-^\012\012   This  is  where  you  can specify which filetypes are allowed to view.\012   Currently supported filetypes are:\012\012   DMS               ­ Files  that  have  DMS  as  a file extension.  The\012                       action  that  is  performed on these files is "DMS\012                       ViEW <filename>".\012                       (Default: On)\012\012   LHA               ­ These  are  files  that  have  LHA  or  LZH  as an\012                       extension.   The action performed on such files is\012                       "LHA V <filename>".\012                       (Default: On)\012\012   Text files        ­ A whole range of extensions go for this file type:\012                       NFO,  NF0,  TXT,  DOC  and  ASC.   These files are\012                       simply  shown  to  them.   This  might  be the ONE\012                       filetype  you  want  to  turn  off  since the show\012                       routine will NOT abort display when it sees binary\012                       codes.\012                       (Default: On)\012\012   ZiP files         ­ Files with the extension ZiP will be attacked with\012                       an "ZiP -v <filename>" command and the result will\012                       be shown on screen.\012                       (Default: On)\012\012                 ^-[ SAVE iT! ]-^\012\012   To  save  all your settings, simply click on the [Save & Exit] button.\012   To quit without saving, close the window.\012\012      ^-[ WHAT ABOUT THAT OTHER BUTTON? ]-^\012\012   That  button  [ConfScan_DL]  lets  you setup some restrictions for the\012   download command.  See the @{"ConfScan_DL guide" link ConfScan_DL} for that!\012@EndNode\012\012@Node Features "Features of ConfScan - /X-PoWeR! - Written by KiLLrAvEn/MYSTiC"\012                      - - - ­ ­ ­ [ FEATURES ] ­ ­ ­ - - -\012\012 · GUi  Config  program that can be started from the CLi or Workbench for\012   easy configuration of ConfScan, a first for an /X-Tool!\012\012 · FAST searching with LOW memory consumption! Max. 60Kb per node!\012\012 · ConfScan  can  act  like `N'', `F'' and it''s own `CS''.  So you get three\012   programs for the download of one!  8-)\012\012 · ConfScan  can  show  you the full file descriptions always, so no more\012   broken file descriptions on your screen.  Fully user configurable.\012\012 · One  of the main features of ConfScan is ofcourse the fact that it can\012   scan  multiple  conferences in one time, this is unique!  No other dir\012   scanner is able to do that but ConfScan.\012\012 · Another  feature  is  the  file  @{"tagging" link Tagging}.  Although other dir scanners\012   provide  this  options  also,  ConfScan was the first to use it and it\012   kind of revolutionized the way of tagging/flagging files.\012\012 · Users  can  setup  ConfScan  to  their  own  personal  likings  via  a\012   preferences  menu they can call up with the ''W'' argument.  But this is\012   not  so special anymore.  Maybe the fact that it looks good and has no\012   overabundance  of  colours  in  it make it better than the other ones.\012   Also,  ConfScan recognizes conferences without a filebase and will not\012   even show them to users in the config menu.\012\012 · This is what the users can setup for theirselves:\012   ­ ANSi colour display\012   ­ Line between files\012   ­ Return between files\012   ­ Pause between conferences\012   ­ Show new dates\012   ­ Show sent-by (or not)\012   ­ Always show full descriptions\012   ­ Clear Screen after every prompt\012   ­ Show just the 1st line of a description\012\012 · Like I said above, ConfScan recognizes conferences without a filebase.\012   This is done to support Ami-X Net conferences (they usually don''t have\012   them). You don''t have to specify them, ConfScan is ''smart''.\012\012 · Scanning options; ConfScan has them, here you go:\012\012   ­ Scanning from a certain date\012   ­ Scanning from a number of days back\012   ­ Scanning from the day a user was last on\012   ­ Scanning from [t]oday\012   ­ Scanning in current conference or all conferences\012   ­ Scanning in upload dirs, all dirs or specified dir\012   ­ Scanning in hold dirs (special access-level required)\012   ­ Scanning in selected conferences (user configurable)\012   ­ Scanning with a byte- & filereport afterwards for users with\012     [H]old access (f.e. cosysops).\012   ­ Scanning non-stop\012\012 · Flagging  from  ALL  conferences is possible, ConfScan will keep track\012   itself  of all the files flagged and via the Download door, /X will be\012   informed about them (i.o.w.  they will be flagged).\012\012 · The  special  download  door  does  more  then just flag files for the\012   users.  It can automatically join the next conference where files were\012   flagged  by  the user.  This can be done straight away when they start\012   the download command in a conference where they have selected no files\012   or right after the downloading of files of that conference.\012\012   NOTE!       In  the near future, ConfScan will be able to send all the\012   ~~~~~       files  to  the  users  in  ONE  time.  This saves time and\012               trouble  for your users as well as for your board, it will\012               be  less  busy. \012\012 · With  @{"KiLLER" link KiLLER} installed, you can nuke files from within ConfScan.  Most\012   likely  you  will find a beta version of KiLLER inside and you will be\012   able  to  test it.  As soon as I''ve finished coding it, I will release\012   it  and  make  sure  you  can  still keep using it in cooperation with\012   ConfScan as well as a stand-alone program.\012\012   ALSO READ THE @{" HiSTORY " link History} iN THiS GUiDE FOR MORE iNFO ABOUT THESE\012   FEATURES!\012\012@EndNode\012\012@Node Usage "Usage by users (that includes you) - /X-PoWeR! - Written by KiLLrAvEn/MYSTiC"\012                       - - - ­ ­ ­ [ USAGE ] ­ ­ ­ - - -\012\012   ConfScan  is  very  easy  to  use, despite of it''s army of options ;-)\012   ConfScan comes with a set of very clear help files that your users can\012   call  in for help with ''<command> ?''.  This goes for ''N'', ''F'', ''G'' and\012   ''CS''.   Here are they in plain ASCII.  Feel free to change them if you\012   want  to.   To  get  a  full  view  of all recognized command, see the\012   @{"ALL COMMAND LIST" link SysopCommands}.\012\012   All the help is put into separate files for your convenience.  This is\012   done  to  support  multiple screentypes (so you can have separate help\012   files  for  every  screentype  (=  language)).  They are called:\012\012                      N  - Command   : ConfScan.N.Help.TXT\012                      F  - Command   : ConfScan.F.Help.TXT\012                      G  - Command   : ConfScan.G.Help.TXT\012                      CS - Command   : ConfScan.CS.Help.TXT\012\012                       In that order, their contents are:\012\012                         ^-^-^-^-[ B R E A K ]-^-^-^-^\012\012                              ConfScan User Help \012 \012  N -x     Files from x days back        Extra options:\012  N <date> Files from <date> and on      ­­­­­­­­­­­­­­\012  N S U    Files since last logon        · Add ''NS'' for non stop display\012  N T U    Files since today             · Use CTRL-C to break program\012  N S G    Files since last logon        · Enter ''N W'' for to edit your own\012           from all conf''s (Global)        personal environment settings.\012 \012                              Environment Options\012 \012  · Select global conferences            · Put lines between files on screen\012  · Usage of ANSI colours in list        · Put return between files on screen\012  · Leave out sent-by''s                  · Pause between conferences (only used\012  · Display new date banner                when you scan globally)\012  · Clear the screen after prompt        · Display only first line of descr.\012 \012  · Show Full Descriptions is an option that will make sure you will always\012    get to see the full description of a file, and never will the description\012    of a file be broken on your screen. It is not the opposite of ''one line''!\012\012                          ^-^-^-^-[ B R E A K ]-^-^-^-^\012\012                               ConfScan User Help\012 \012  F        Pop up ''f'' menu               Extra options:\012  F <#>    Files from dir <#>            ­­­­­­­­­­­­­­\012  F U      Files from upload dir         · Add ''NS'' for non stop display\012  F A      Files from all dirs           · Use CTRL-C to break program\012  F H      Files from hold dir           · Enter ''F W'' for to edit your own\012           (access required)               personal environment settings.\012 \012                              Environment Options\012 \012  · Select global conferences            · Put lines between files on screen\012  · Usage of ANSI colours in list        · Put return between files on screen\012  · Leave out sent-by''s                  · Pause between conferences (only used\012  · Display new date banner                when you scan globally)\012  · Clear the screen after prompt        · Display only first line of descr.\012 \012  · Show Full Descriptions is an option that will make sure you will always\012    get to see the full description of a file, and never will the description\012    of a file be broken on your screen. It is not the opposite of ''one line''!\012\012                          ^-^-^-^-[ B R E A K ]-^-^-^-^\012\012                               ConfScan User Help\012 \012  CS -x     Files from x days back       Extra options:\012  CS <date> Files from <date> and on     ­­­­­­­­­­­­­­\012  CS A      Files from all dirs          · Add ''NS'' for non stop display\012  CS T      Files since today            · Use CTRL-C to break program\012  CS <#>    Files from dir <#>           · Enter ''CS W'' for to edit your own\012                                           personal environment settings.\012  CS scans globally for new files in     · Add ''+'' for a byte-report\012  the upload dir since last logon          (access required)\012  unless specified different (above).\012 \012                              Environment Options\012 \012  · Select global conferences            · Put lines between files on screen\012  · Usage of ANSI colours in list        · Put return between files on screen\012  · Leave out sent-by''s                  · Pause between conferences (only used\012  · Display new date banner                when you scan globally)\012  · Clear the screen after prompt        · Display only first line of descr.\012 \012  · Show Full Descriptions is an option that will make sure you will always\012    get to see the full description of a file, and never will the description\012    of a file be broken on your screen. It is not the opposite of ''one line''!\012\012                          ^-^-^-^-[ B R E A K ]-^-^-^-^\012\012                          ConfScan Goodbye Explanation\012 \012   Theory  Your sysop has installed ConfScan for scanning the dirfiles,\012           and ConfScan stores your flagged files in a different matter\012           then Ami-Express does (because ConfScan can remember flagged\012           files from multiple conferences and /X can''t). This also asks\012           for a different ''G'' command, this is it!\012 \012           This new commands does the same as the internal one, with a\012           few differences:\012 \012           ^ Ability to start downloading from ''G''\012           ^ Ability to view your remaining flagged files\012           ^ Ability to remove your remaining flagged files\012 \012 Practice  Once notified that you have remaining files, your options are:\012 \012           [G] ^ Goodbye, let me out!             To force ConfScan_G to\012           [L] ^ List the remaining files         just log off, enter a\012           [D] ^ Download remaining files         ''!'' after the G (''G !'').\012           [R] ^ Remove them & log off\012           [Q] ^ Quit, back to /X prompt          (c) ''94 KiLLraVeN/MYSTiC\012\012                          ^-^-^-^-[ B R E A K ]-^-^-^-^\012\012   SEE ALSO: @{"More options" link More}\012\012@EndNode\012\012@Node Future "Possible Future improvements - /X-PoWeR! - KiLLrAvEn/MYSTiC"\012                - - - ­ ­ ­ [ FUTURE iMPROVEMENTS ] ­ ­ ­ - - -\012\012 · Downloading  ALL  files  from  ALL  conferences  in ONE time.  This is\012   possible now thanks to the help of Joe Hodge (thanks Joe!).  Make sure\012   you  are  a  registered  sysop,  or  else you want be able to run that\012   version of ConfScan!  It will require /X 3.38+.\012\012 · Improved  file  tagging,  it can be annoying sometimes that you cannot\012   reach a file that is still on screen.  I will have to look into that.\012\012 · ''A'' command to alter/remove flagged files (multiple conferences ofcoz).\012\012 · ''Z''  command  to  search  in  multiple  conferences  and with ConfScan\012   interface.\012\012   Anyway,  if  you  have  suggestions,  make  sure  to  drop me a line at\012   Channel-X or at one of the other MYSTiC boards (in Holland preferably,\012   that''s where  I  am most).  By the way, you don''t need to have a\012   suggestion to call  the MYSTiC boards, you''re welcome at any time, open\012   24 hours a day and at your service!\012\012   Let me know what you think and what YOU think needs improvement!\012\012                            __                       /\\012    :        _ __  __Stz___|  \________/\___________/_ \______/\ _       ·\012   _¦_______ //  \/  \_/   |  \\_  ____  \           /__/      \\\ ______:_\012    |        //       \___   ___/____ \ //__/    |__/  .|   /___/_       |\012    |     ._/    \/   \\_|    \    \|  \/\_//    ||    ||  /      \_.    |\012    |  .:::\_____||_____/|_____\__________/______||_____|__________/:::. |\012   -+--      W O R L D W I D E   B U L L E T I N   B O A R D S !       --+--\012    |                                                                    |\012    |       MASTURBATiON STATiON - 7 NODES - WHQ! - 1-305-552-1192       |\012    |           LAST OUTPOST     - 2 NODES - EHQ! -  +31-721-57682       |\012    |             THE EAST       - 3 NODES - SCHQ -   +46-8-940614       |\012    |         FORBiDDEN ENTRY    - 3 NODES - CHQ! - 1-416-281-3912       |\012    |           TRADE LiNES      - 1 NODE! - CHQ! - 1-514-966-9569       |\012    |           UZi SUiCiDE      - 3 NODES - USHQ - 1-203-437-8655       |\012    |            CHANNEL X       - 2 NODES - DHQ! - +31-2290-62244       |\012    |           OUT OF SPACE     - 1 NODE! - SHQ! -  +46-620-13141       |\012    |         FORBiDDEN PLANET   - 2 NODES - IHQ! - +353-1-820-8489      |\012    |           ROCKA ROLLA      - 2 NODES - THQ! - +90-216-363-5742     |\012    |            TAU CETi        - 1 NODE! - ESHQ -   +34-34255620       |\012   -+--------------------------------------------------------------------+--\012    :                                                                    :\012\012@EndNode\012\012@Node Bugs "Known Bugs - /X-PoWeR! - Wild Stallions Shall Rule! 8-)"\012                    - - - ­ ­ ­ [ KNOWN BUGS ] ­ ­ ­ - - -\012\012   This  is  the  part  that  all  programmers hate, admitting that their\012   program contains bugs.  I''ll ease my mind with the thought that nobody\012   is  perfect  and  that  hopefully  due to a bug, I will once day get a\012   receipt  from  the bank saying that I''ve got $10 million on my account\012   8-) Here we go...\012\012   · When  you  are  at the end of a dir file (like 95%) and you only got\012     one  file  after  pressing  return,  you 