INSERT INTO door_catalog VALUES('crd_sx','CRD!SX.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CRD!SX.LHA',NULL,'XIM','pizza_taxi.exe',NULL,'stOne/CRD''97','CRD','______ _____\_    |___ _______ ______ /  ___/__ ___  \_  |   \ ___   \  __  \_ _/   |     \_\/  _/  :    \_ |    \_\____/__',replace('               ______.\n   ______ _____\_    |___ _______ ______\n  /  ___/__ ___  \_  |   \ ___   \  __  \_\n_/   |     \_\/  _/  :    \_ |    \_\____/__\n\_____      //    \________/_      /__     /\n.----|_____/-\_____/---[yW]-|_____/--\____/.\n|:.                                     ...|\n|:::... .                     .::::::::::::|\n`----------+[  CEWL-STATIX  ]+-------------''\n\n     a cewl status door with sTYLe\n         coded by stOne/CRD''97\n','\n',char(10)),'cEWL-STATix.guide',replace('\n\n\n\n\n\n\n                        ______.      \n            ______ _____\_    |___ _______ ______    \n           /  ___/__ ___  \_  |   \ ___   \  __  \_  \n         _/   |     \_\/  _/  :    \_ |    \_\____/__\n         \_____      //    \________/_      /__     /\n        .-----|_____/-\_____/---[yW]-|_____/--\____/--. \n        |::.                                     ....:|\n        |::::... .                     .::::::::::::::|\n        `----------+[  cEWL-STATIx  ]+----------------''\n\n                  cODEd bY stOne/CRUDE''97\n\n\n\n\n\n\n\n\n                            Hi there,\n        Here comez another cewl sTONE-PRODUCt to eager you''re EgO!\n _________________________________________________________________________\n(_________________________________________________________________________)\n\n\n\n\n\n\n\n                -*-[ hISTORY & PROGRAM INFo ]-*-\n\n\n  Well a while ago, my friend yELLOW WATEr was working on a sTATUs door.\n  I just taught i maybe be a faster coder than him, so i dicide to also\n  make one for my own! :)\n  Finally I taught, "What The HACk, If He NEVER Get FiNISHEd, I Just Releasse\n  my dOOr!" :)\n\n\n\n\n\n\n              -*-[ wHAT IS DOEs & PROGRAM INFo ]-*-\n\n\n  This Cewl Program will enable the user to view his current & system status.\n  (Pretty cewl for a status dOOr doesnt it :)\n  Well the main Fun lies in the output string that looks after the CRDz and\n  notify the user by a NICE Text string, it will change after 10mb,25mb,50mb,75mb,& 100mb\n  upload crdz!.\n\n  Just look at the ScreenGrab included on this Program,.! :)\n\n\n\n\n\n\n   -*-[ iNSTALLATIOn ]-*-\n\n\n   S!X : Just copy the Doors/cRUDe/sTATUs/ and contains to\n                       dOORs:cRUDe/sTATUs/\n\n         Edit you''re Commands:BBSCMD file and add these lines:\n         *S                   RM10dOORS:cRUDe/sTATUs/sTATUs\n\n    /X : Just copy the Doors/cRUDe/sTATUs/ and contains to\n                       dOORs:cRUDe/sTATUs/\n\n         Copy the COMMANDS/BBSCMD/ to BBs:COMMANDS/BBSCMD/\n\n\n\n\n\n                   __           _  __  \n .-[ GrEeTz : _/\_/\ \__/\_____/ \/  /___\n |           (   ___) __/____  )    / _  )\n |            \__  \\ \ \ / / / /  / ___/\n `----------- - \___)\___(_____/__(____/ -[ StOnE/CrUdE 1997 ]----\n\n .-------------------------------------------------------------------.\n | If you want to SuppoRt the AmiGa_ScEnE :                          |\n | Pleasse Mail me you''re idea of any Great program that iz missing. |\n | right now !                                                       |\n |                                                                   |\n |             Mail me at : [email removed]                   -.\n |             or contact : tHE nExUs BBs +31-38-4221945              |\n `--------------------------------------------------------------------''\n\n Ofcuz, Money iz also a great gift for supporting ShArE-Ware Programmers.\n So if ya like to send some, Here''z my adress :\n                                                 T.M Tromp\n                                                 Assendorperstraat 174-3\n                                                 8012 CE Zwolle\n                                                 HOLLAND.\n\n                 ______.      \n     ______ _____\_    |___ _______ ______    \n    /  ___/__ ___  \_  |   \ ___   \  __  \_  \n  _/   |     \_\/  _/  :    \_ |    \_\____/__\n  \_____      //    \________/_      /__     /\n .-----|_____/-\_____/---[yW]-|_____/--\____/-------------------------. \n |::.                                                               .:|\n |::::... .                                .:::....................::::\n `----------+ vISIT THESE CEWl CrUdE HQ''z .---------------------------''\n .----------`-----------------------------+---------------------------.\n |: ________   __________            _________  ________    _________ |\n |:_\  ____/_ _\        /_ __________\  ___   \_\_____  \   \   __  / |\n |:|   _____ \|    __    |_\ ____  /_   \_____/|     /   \_/\___  \/\_|\n |:|   \__    /     |    ||  \__    |    __    /    /    _/    /     /|\n |:|______\  /|__________||____|    |______\  /|_______  \  ________/ |\n |:        \/                  |____|       \/ [yW]    \/ \/          |\n |:.                              :                                   :\n `---------------| LAST LEGEND      - WHQ  - ++31-70-3176466 |--------''\n                   THe nExUs        - WOHQ - ++31-38-4221945\n                   SOUTH CENTRAL    - SHQ  - ++**-PRIVATE\n                   HUSTLERS HELL    - RHQ  - ++**-PRIVATE\n                   DESTELATE WASTE  - SHQ  - ++**-PRIVATE\n                   TRADERS PARADISE - EHQ  - ++46-PRIVATE\n                   FORGOTTEN WORLDS - DHQ  - ++31-PRIVATE\n                   FLYiNG DRAGON    - GHQ  - ++49-PRIVATE\n                   CYBER DESIGN     - SCHQ - ++46-PRIVATE\n                   DREAMPHASE       - SHQ  - ++46-PRIVATE\n                   FIRE SIDE        - SHQ  - ++46-PRIVATE\n                   DISASTER AREA    - NHQ  - ++##-PRIVATE\n                   FLYiNG CiRCUS    - FHQ  - ++##-PRIVATE\n                   THE FiRM         - DiST - ++31-iNViTE!\n                   PHANTOM          - DiST - ++31-PRIVATE \n                   BANDICOOT        - MEM! - ++31-PRIVATE\n\n   -X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-\n\n\n           DA ONE AND ONLY MEMBERS OF CRUDE AT THIS MOMENT ARE:\n           ----------------------------------------------------\n \n          yELLOW wATER - LeatherFace - Apollo - JackII - ST0RM\n            Johnny Five - CYBER - PLL - Mestis - Dusty - Ten!\n                   zEUS - Tyrell - kABAL - MJK - Cloak\n                      THE MiXER - FAiRYDUST - U-man\n                         fK - Tunes - sTYLE - IF\n                         Pentangle - The Teacher\n                       la shawn - Acorn - Bubbasd\n                       Bones - Hellcat - Analyzer\n                       Stone - Kruger - dEATHroW\n                       \n   -X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-\n\n|                           GREETZ GO OUT TO: \n|                          ¬÷¬÷¬÷¬÷¬÷¬÷¬÷¬÷¬÷¬\n|                          \n|                         CRUX & BAD KARMA inc.\n|      SAINTS - LIGHTFORCE - QUASAR - REAL - DECISION - CELLBLOCK 4!\n|               JOLLY - Digital Corruption - RITE - xTREK\n|                   ABUSE - DATA DiViSiON - HELLFiRE\n:\n`---------------------------------------------------------------------------\n\n\n\n                            PERSONAL GREETZ TO:\n                           ¬÷¬÷¬÷¬÷¬÷¬÷¬÷¬÷¬÷¬÷¬\n\n             Shane - Mc - Kruger - Tyrell - Flash - Fungus - Pll - Scram\n - Crisp - Franky - Shag-Rat - Dazzler - Ecs - One - Chels - Anakin - Cloak\n            - Repe - Fain - Scram - SlapShot - Deathrow - Bubba - \n\n   -X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-x-X-\n\nSpecial Thx to : kRUGER/JFK/CRd for helping me with all the /X testings &\n                 nICE CHATting!\n                   __           _  __  \n .-[ GrEeTz : _/\_/\ \__/\_____/ \/  /___\n |           (   ___) __/____  )    / _  )\n |            \__  \\ \ \ / / / /  / ___/\n `----------- - \___)\___(_____/__(____/ -[ StOnE/CrUdE 1997 ]----\n\n','\n',char(10)),NULL,'auto-added',14930,4,0,NULL,NULL,'crd_sx','scan',1780048448);
INSERT INTO door_catalog VALUES('crd_nu12','CRD-NU12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CRD-NU12.LHA','NodeStatus','XIM','__________  ________________',NULL,NULL,'CRD','+---/ _  \  __ \/  ___/  ___/    \---------+ |--/ /___/    _/  ___/  ___/  /  /\- Json -| |-/_____/__/__/_____/_____/_____/ /--------|',replace('     __________  ________________\n+---/ _  \  __ \/  ___/  ___/    \---------+\n|--/ /___/    _/  ___/  ___/  /  /\- Json -|\n|-/_____/__/__/_____/_____/_____/ /--------|\n+-\_____\_____\_____\_____\_____\/---------+\n| PReSeNTS:       NewUser Wall v1.2 FOR /X |\n|                 NodeStatus v1.0   FOR /X |\n|  FRoNTeND DooR  SysOpAvail v1.2   FOR /X |\n+------------------------------------------+\n','\n',char(10)),'NUWall.doc',replace('\n\n\n\n                              New User Wall\n\n                                  v1.2\n\n                                 For /X\n\n\n\n Well, just some words about this /X-tool. The tool is meant to be run from\nyour LogOff Script like this:\n\n~~~~~~~~~~~~~~~~~~~~~~~\n\nbbs:utils/NUWall "BBS:conf1/BULL.TXT"\n\n\n~~~~~~~~~~~~~~~~~~~~~~~\n REMEMBER -> "  " <-\n\n This will output a file called BULL.TXT with all New User''s names.\nThese names will be found in the BBS:user.data, by checking to see if the\nNewUser (''N'' in account edit) is yes or no!! so if you inactivate a user\nremember to put NO in here or the user will be registret on the Wall.\n\n Default output file is: bbs:utils/NUWall.txt.gr\n\n A maximum of 10 New users can be on the wall at one time. That means the\n10 first new users the utility finds, are displayed. The output file is\nfor ANSI or no ANSI, it can be used for both.\n\n Planed:   include a headerfile.\n\n\nHi! must go to:\n                            ZWooLoCK, WaRNeR, D''K ??\n               Deature, Conan, Spacebrain, Paxdei, and everyone else!!\n\nThanx to Neurostorm... that chat helped a lot!!!\n\nBUGS AND #$%^@# TO:         tOON tOWN dK     +45-864185o2\n\nby the way: I''m looking for a group... anybody interested\nin me (the following describtion):   \n\n                 A4OOO/68O4O 375MB (25O for bbs), 1 node 14k4\n\n                 I code anything... /X, bbs intro, WB tools...\n\n                                                             Json / CReeD\n','\n',char(10)),NULL,NULL,13551,6,0,NULL,NULL,'crd_nu12_nodestatus','scan',1780048448);
