INSERT INTO door_catalog VALUES('crx_nta','CRX-NTA.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CRX-NTA.LHA',NULL,'XIM','______ _____ __ __ __ ___',NULL,NULL,'CRX','_)    _Y    _Y  | _Y  l _(_ \_  |_\_  l_\_  | \__    _/----------  -- -. .|  l  |  |  |  |  |  |  | sWEEt dOORS 4 U!|',replace(' ______ _____ __ __ __ ___\n_)    _Y    _Y  | _Y  l _(_\n\_  |_\_  l_\_  | \__    _/----------  -- -.\n.|  l  |  |  |  |  |  |  | sWEEt dOORS 4 U!|\n`l__   l__|2Fl_____l__|  |-----------------:\n:   `--''              `--''                 .\n. NewTelnet v1.0 *AMiEXPRESS*              .\n:                                          :\n: DOOR THAT DiSPLAYS THE iP, COOL DESiGN!! :\n:   - Copyright © NewDoors Development -   :\n`-------------[· NEWt/CRUX ·]--------------''\n','\n',char(10)),'NewTelnet.guide',replace('@database 005a9c70-0\n@node "Main" "Amiga Guidestyle document for NewTelnet"\n\n                NewTelnet AmiExpress Version Newt/Crux^Abyss              \n                                                                              \n                 Copyright © 1996-1997 NewDoors Development.                 \n\n\n            @{" Introduction    " link "Introduction" 0}    - Features & Product information\n            @{" Copyright       " link "Copyright" 0}    - Disclaimer\n   \n            @{" Installation    " link "Installation" 0}    - Installation\n\n            @{" Author          " link "Author" 0}    - How do I contact the Author\n            @{" Future          " link "Future" 0}    - Planned enhancements\n            @{" Messages        " link "messages" 0}    - Some messages...\n@endnode \n\n@node "Introduction" "Introduction"\n \n @{b}@{u}Introduction@{ub}@{uu}\n \n NewTelnet is a door which displays the IP if the board is connected\n to INTERNET. You may ONLY use AmiTcp and Miami if this door should work\n correctly, please @{"mail" link "Author" 0} me if you use some other program and wish \n to have this door fixed for it. \n\n@endnode\n\n@node "Copyright" "Copyright"\n\n @{b}COPYRIGHT@{ub}\n\n The copyright for this software is by @{"Newt" link "Author" 0}. This archive may\n only be distributed in unmodified form. In particular the deletion of\n the documentation and this copyright-note is not allowed.\n \n \n @{b}DISCLAIMER@{ub}\n \n This software is provided as-is, without warranty of any kind, either\n expressed or implied. In no event will the author be liable for direct,\n indirect, incidental or consequential damages or data loss resulting from\n the use or application of this software. The entire risk as to the results\n and performance of this software is assumed by the user.\n@endnode \n \n@node "Installation" "Installation"\n \n @{u}HOW TO INSTALL NewTelnet@{uu}\n \n Just copy all the drawers where they are in this package and if you\n want this door to be displayed every time somebody logs on then\n put this in the Screens:BULL.txt\n\n   <==== CUT HERE == CUT HERE == CUT HERE == CUT HERE == CUT HERE ====> \n\n   ~CC_TELNET\n\n   <==== CUT HERE == CUT HERE == CUT HERE == CUT HERE == CUT HERE ====> \n\n *NOTE* that it won`t be displayed if no IP address could be found!\n\n@endnode\n\n@node "Author" "Author"\n\n @{u}AUTHOR INFORMATIONS@{uu}\n\n If you have suggestions, questions, critics, bug reports etc. write to:\n\n E-Mail:@{uu}  @{b}[email removed]@{ub}\n\n or msg me on..  #amielite, #fame or #trsi-fame 24h/day.\n\n@endnode\n\n\n@node "Future" "Future"\n \n @{u}FUTURE PLANS OF NEWTELNET@{ub}@{uu}\n \n - None (suggestions?)\n\n@endnode\n\n@node "messages" "messages"\n \n                         @{u}SOME MESSAGES TO SOME FRIENDS@{ub}@{uu}\n \n                  Strider: I love FAME!!.. Wanna marry me? =)\n             Greedysnitch: Thanx for ALL the help, you rule.\n                   Dr.Dre: Bodo Hoffmann, yeah!.. i spelt it correct!\n                    Excel: PC LAMER!! =)\n                    Deamo: 80-tals pojken nummer ett!\n                   Desoto: Ascii dude No.1\n                TopFlight: Har du fått AmiTcp o funka nu?\n                  Dalamar: Byt till Fame på en gång!\n                  Sal-One: Good choice mate!\n\n@endnode\n','\n',char(10)),NULL,NULL,10073,4,0,NULL,NULL,NULL,'scan',1780048448);
INSERT INTO door_catalog VALUES('crx_nu12','CRX-NU12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CRX-NU12.LHA',NULL,'XIM','pizza_taxi.exe',NULL,NULL,'CRX','/  _____    _____   __\   / ___\     /__ __. _\  _/____\__  \__\  \  \_\   \  _/  //  | _/    \   \_  /  _/.   /   \_   _   \_     |',replace(' /    sTZ!/sE         _____    _______\n/  _____    _____   __\   / ___\     /__ __.\n  _\  _/____\__  \__\  \  \_\   \  _/  //  |\n_/    \   \_  /  _/.   /   \_   _   \_     |\n\__________/__\____|________/___/____/  .: |\n.------------------------------------------''\n| nEWT/cRUX /X-DIVISION PRESENTS:\n|\n| nEWuSER v1.2 - a fUNKY nEWuSER aNNOUNCER!!\n','\n',char(10)),'NewUser_1.2.Doc',replace('\n                                                     .\n                                                     .\n                     .---÷-----------------------÷---¦-- -\n                     |            dA rEAL!           |\n    _ ___________/_  |    __________  _______._______________.________\n    \ \_     ___/____|____\___      \_\_     |     _/\___    |    ___/\n    _/       l       \_      /      _/       |       \_      .       \_\_\n    \_________________/______\       \________________/______|________/ /\n        «---- --adk!-÷----- --\_______/---- -  - ----÷--  - --- -- -\n                     |         · p O S S E ·       .-''\n                     `--------------÷--------------''\n                                                                               \n                   ÷ iN a hIGHER sTATE oF cONSCiOUSNESS ÷                   \n \n                          PRESENTS: NewUser v1.2\n                            CODiNG: Newt\n                            DESiGN: Desoto\n                            SYSTEM: AmiExpress\n\n\n<==[ introduction ]=====================================================>\n\n This funky door is a NewUser announcer .. wich means that when a newuser\n has filled out all NewUser questions, a message will be posted to all\n users wich already have axx concerning the newusers validation.\n There are already doors like this out in the public but most of them\n doesn`t have the option to mail stuff in the conference that you like!\n Most door posts messages in Conf2 but since not everybody has their \n ELITE conf as number 2 i put in an option where you can choose\n your own conference, well... enough bullshit for this time!\n  - -- --- ---- ------------------------------------------ ---- --- -- -\n\n\n<==[ Features ]=====================================================>\n\n Conf_To_Mail:=\n\n Here you can add your conference, for example `BBS:Conf2/` or somthing\n similar. When you have entered the correct conference the validated users\n on your board will recieve a message like this:\n  __                                                                __\n =\/================================================================\/=\n\n    Hi! There is a new user here called, ZOLTRiX\n    If you know this guy, please leave some information to your sysop!\n    He would be most greatful!\n\n\n    By: Newt/Crux^Abyss......\n\n =/\================================================================/\=\n  ¯¯                                                                ¯¯\n Well... i hope ya like this door as much as .. as.....argh.. NEVER MIND!!\n\n  - -- --- ---- ------------------------------------------ ---- --- -- -\n\n<==[ Installation ]=====================================================>\n\n Just put this in BBS:Screens/Joined.txt\n\n ----------------------------\n\n ~CC_NEWUSER\n\n ----------------------------\n\n * Make a drawer called DOORS:New-Doors/NewUser/\n * Copy ALL of these files into that directory:\n\n  newuser.config              25\n  newuser.xim               5688\n\n - -- --- ---- ------------------------------------------ ---- --- -- -\n\n\n<==[ How 2 contact me ]=====================================================>\n\n               Board:  Plastic Dreams · 4ndz · +46-36-123029\n \n                    Or e-mail me:  [email removed]\n  - -- --- ---- ------------------------------------------ ---- --- -- -\n\n\n<==[ Greetings ]=====================================================>\n\n                      Hugs and mighty kisses goes to:\n                     ---------------------------------\n Ant.AntiByte.Aquarius.Atheist.Belzebub.Blade.Boheme.Boogeyman.Boone.Boot\n   Bubba.Carabat.Chewie.Citruz.CockRoach.Colorbird.Cyclone.Dalamar.Decoy\n  Deelite.DeOne.Desoto.Dexter.Dino.Electron.Excel.Exeron.Ezco.Facet.Frame\n  Freecaller.Funki.Fury.Gangsta.General Lee.Hamlet.Hemp.Hollywood.Infant\n   Interphase.Ironnuke.Jacobs.Jazz.Karpow.Keldon.Kingpin.La Shawn.Lizard\n Lizardking.Looby.Lord Kgd.Louie.Macno.MadBoy.Madsen.Magic.Maniac.Meanace\n Mestis.MOP.Mr Real.Mrk.Neptune.Nike.Noodle.Note.Offa.Orchid.Orchis.Origo\n    Orion.Orlando.Pantera.PaperBoy.Payday.Peachy.Phase.Pink.Pride.Probe\n   Prospect.Psychotron.Qen.Rahiem.Recall.Rodney.Rubberduck.Sal-One.Saxon\n   Schindler.Sealapex.Shane.Sid.Size.Slash.Slice.Slurry.Speed Freak.Spin\n  Spite.Spot.Stc!.Sticky Fingaz.SuperNao.Swoop.The Bug.Touchstone.Trivial\n Trollet.Tudor.Vlad.Webster.Whild.Whirlwind.Wraith.Xerxes.Zalo.Zanok.Zinko\n\n\n                  PLEASE REMIND ME IF I FORGOT YOU NAME!\n  - -- --- ---- ------------------------------------------ ---- --- -- -\n\n','\n',char(10)),NULL,'auto-added',11805,4,0,NULL,NULL,'crx_nu12','scan',1780048448);
