INSERT INTO door_catalog VALUES('crz_af11','CRZ-AF11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CRZ-AF11.LHA','Autofree','XIM','Autofree',NULL,'nIKE','CRZ','\___ \________/\_____   ¬\_/________/ \·:::: ·\/   _/______\ \__/    _/\    _______/\·::: /¯   /__     ¬\\/__      \ \  /__     ¯¬\·::',replace('_________________________·:·__________·::E^d\n\___ \________/\_____   ¬\_/________/ \·::::\n·\/   _/______\ \__/    _/\    _______/\·:::\n/¯   /__     ¬\\/__      \ \  /__     ¯¬\·::\n\______/       \_/        \/____/-CRAZE- \·:\n.\  \__________/\\________/\ \___________/\·\n:.\__\         \ \\       \ \_\          \ \\n::HrP.\_________\/.\_______\/..\__________\/\n[÷-------------÷) Presents (÷-------------÷]\n           AutoFree v1.1 by nIKE\n[÷-------------÷) in 1994! (÷-------------÷]\n','\n',char(10)),'Autofree.Doc',replace('    __________________ _ ________________________________._ _________\n   _)       _________/    __      _____    \_.______  _  |     _____/_\n   \  cG·dP /       |      /_____/   _/      |     ______j  _________/_\n    \ - - -/        |        |       \       |    /      ·  \         /\n     \____/_________l________l________\______!___/_______|---\_______/\n\n                     ==)> Presents 2 ya in 1994! <(==\n                       Presents another /X^S!X Door\n\n                      -^(· AutoFree v1.1 by Nike ·)^-\n\nDescription.\n============\nMakes files Free download automatically.\nByteKillHandler replacement.\n\nFeatures:\n=========\n1. It checks the file that a user uploads if it starts on the same thing\n   as in the config file.\n   In the configfile you can enter as many names and the names can be of\n   unlimited length.\n   Example:\n   -- CUT --\n   CRZ\n   5150\n   -- CUT --\n   Will make all files starting with "CRZ" or "5150" free download.\n   The names are NOT case sensitive.\n\n2. ByteKillHandler replacement.\n   If the file shouldn''t be made free download, AutoFree will comment the file\n   with the users slot number, so that ByteKiller and FastNuke (my own nuker)\n   knows who uploaded the file without checking thru the UDLog file (which\n   usually is quite BIG if you know what i mean!).\n\nInstalling this damn util:\n==========================\nCopy the dir AutoFree to Doors:\nCopy the icon to BBS:Commands/Syscmd/\nIf the file BBS:Commands/SysCmd/Filecheck1.Info exists, AutoFree\ntries to start "FILECHECK1" when it''s finished. So if you already have\na door at "FILECHECK" just rename it to FILECHECK1.\n\nHistory:\n========\nv1.0	--	First version. Not released to anyone but beta testers.\nv1.1  --  Added support for starting a door upon exiting.\n          Added ByteKillHandler replacement.\n\nGreetings\n=========\n                        -> All members of CRAZE <-\n  -> Aquarius/OutLaws - Bobo/Mystic - Xerxes/Fairlight - Demax/Delight <-\n-> Zcandaler/Duplo! - Juan/tRSi - Dr.Dre!/tRSi - Boromir/tRSi - Guardian <-\n           -> Those i''ve forgot in this short greetings list! <-\n','\n',char(10)),NULL,'auto-added',6509,2,0,NULL,NULL,'crz_af11','scan',1780048448);
INSERT INTO door_catalog VALUES('crz_bl11','CRZ-BL11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CRZ-BL11.LHA','Bull','XIM','Bull',NULL,NULL,'CRZ','\___ \________/\_____   ¬\_/________/ \·:::: ·\/   _/______\ \__/    _/\    _______/\·::: /¯   /__     ¬\\/__      \ \  /__     ¯¬\·::',replace('_________________________·:·__________·::E^d\n\___ \________/\_____   ¬\_/________/ \·::::\n·\/   _/______\ \__/    _/\    _______/\·:::\n/¯   /__     ¬\\/__      \ \  /__     ¯¬\·::\n\______/       \_/        \/____/-CRAZE- \·:\n.\  \__________/\\________/\ \___________/\·\n:.\__\         \ \\       \ \_\          \ \\n::HrP.\_________\/.\_______\/..\__________\/\n[÷-------------÷) Presents (÷-------------÷]\n               bULLvIEW v1.1!\n[÷-------------÷) in 1994! (÷-------------÷]\n','\n',char(10)),'Bull.Doc',replace('               _________________________·:·__________·::E^d\n               \___ \________/\_____   ¬\_/________/ \·::::\n               ·\/   _/______\ \__/    _/\    _______/\·:::\n               /¯   /__     ¬\\/__      \ \  /__     ¯¬\·::\n               \______/       \_/        \/____/-CRAZE- \·:\n               .\  \__________/\\________/\ \___________/\·\n               :.\__\         \ \\       \ \_\          \ \\n               ::HrP.\_________\/.\_______\/..\__________\/\n\n                      P·R·O·U·D·L·Y·? P·R·E·S·E·N·T·S\n\n                     BullView v1.1 by nIKE/cRAZE^5150\n\nDescription.\n~~~~~~~~~~~~\nBulletin Viewer. Let''s the sysop have all bulletins in one directory instead\nof the same files in XX directorys (hehe)..\nQuite fast (95% E, 5% Asm :)), Goodlooking, easy to install.\nBtw, this door may not be used by RHYS/DELIRIUM! You are a lame as-hole!\n\nInstalling this damn door:\n~~~~~~~~~~~~~~~~~~~~~~~~~~\nCopy "Bull" To any directory on your HD.\nCopy the icon (B.Info) to BBS:Commands/BBSCmd/ and edit it to set your needs.\nStack needs at least 3000 bytes, 4000 recommended\nType = XIM.\n\nMake a directory called BBS:Bulletins and copy "Bullhelp", and the other files\nincluded to it. Edit the files to set your needs (easy to understand?!)\nFilenames should be Bull<Nr>.Txt<.Gr> where <Nr> is the number of the bulletin.\n\nOn each line in Bullhelp to be the bulletin number you want.\nThat means, Line 1=Bulletin 1, line 7=bulletin 7 etc..\nLook at the Bullhelp file included for more info!\n\nTo be able to let the user update the bulletins, u''ll have to make an ordinary\ndos script that does it. Copy the file to S: and call it "Up"....BullView will\nExecute this if the user wants to update the bulletins!\n\nInfo ''bout 5150!\n~~~~~~~~~~~~~~~~\nTo join 5150, the ultimate Door group, then call one of our boards (Pet Sematary\n(WHQ) or Instant Pleasure (EHQ)!) and upload some of your doors!\nOnly the cream of the doorcreators will be accepted as members!\n\nInfo ''bout CraZe\n~~~~~~~~~~~~~~~~\nWe need more Gfxers! Coders are also welcome. More traders too!\nYou should know were to get in touch with us!\n\nHISTORY:\n~~~~~~~~~\nv1.01     - FIX: Checks for the file S:UP, before asking the user if\n                 he/she(?) wanted to update the bulletins. No use of asking\n                 when the script can''t be found!\n                 Suggested by: Marwic/cRz^eQx\n            ADD: Support for arguments!\n                 Suggested by: Marwic/cRz^eQx, MR ReaL/cRAZE, etc :)\n\n             ** VERSION NOT RELEASED TO ANYONE BUT MARWIC! **\n\nv1.1      - ADD: Better support for arguments :).\n                 Suggested by: Marwic/cRz^eQx\n            CHG: Fixed some code internally, so it should be a little bit\n                 faster, not noticable i can guess! :)\n','\n',char(10)),'{"TYPE":"XIM."}','auto-added',7337,4,0,NULL,NULL,'crz_bl11','scan',1780048448);
INSERT INTO door_catalog VALUES('crz_bt11','CRZ-BT11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CRZ-BT11.LHA','Time','XIM','Time',NULL,NULL,'CRZ','\___ \________/\_____   ¬\_/________/ \·:::: ·\/   _/______\ \__/    _/\    _______/\·::: /¯   /__     ¬\\/__      \ \  /__     ¯¬\·::',replace('_________________________·:·__________·::E^d\n\___ \________/\_____   ¬\_/________/ \·::::\n·\/   _/______\ \__/    _/\    _______/\·:::\n/¯   /__     ¬\\/__      \ \  /__     ¯¬\·::\n\______/       \_/        \/____/-CRAZE- \·:\n.\  \__________/\\________/\ \___________/\·\n:.\__\         \ \\       \ \_\          \ \\n::HrP.\_________\/.\_______\/..\__________\/\n[÷-------------÷) Presents (÷-------------÷]\n         bIG tIME v1.1 - nEW dESIGN         \n[÷-------------÷) in 1994! (÷-------------÷]\n','\n',char(10)),'Time.Doc',replace('               _________________________·:·__________·::E^d\n               \___ \________/\_____   ¬\_/________/ \·::::\n               ·\/   _/______\ \__/    _/\    _______/\·:::\n               /¯   /__     ¬\\/__      \ \  /__     ¯¬\·::\n               \______/       \_/        \/____/-CRAZE- \·:\n               .\  \__________/\\________/\ \___________/\·\n               :.\__\         \ \\       \ \_\          \ \\n               ::HrP.\_________\/.\_______\/..\__________\/\n\n                        Presents another /X^S!X Door\n\n                       -^(· bIG tIME v1.1 by Nike ·)^-\n\nDescription.\n~~~~~~~~~~~~\n Big clock, that show''s the local time with an easy-to-read-for-blind-people\nlooking "font".\nBtw, this door may not be used by RHYS/DELIRIUM! You are a lame as-hole!\n\nInstalling this damn door:\n~~~~~~~~~~~~~~~~~~~~~~~~~~\nCopy "Time" to any dir you''d like it in..\nCopy the icon and edit it (LOCATION=Doors:Time f.ex.)\nStack=4000\nType=XIM\n\nHISTORY:\n~~~~~~~~~\nv1.0      - This version.\nv1.1      - New design (By RICK/cRAZE)\n\nOFFICIAL Beta testers for nIKE/cRAZE''s doors:\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n Global Effect (xERXES/mYSTIC^oRIENT^fAIRLIGHT)\n Nuclear Waste (mARWic/cRAZE^eQUINOX^dREAM fREQUENCY^nUTS)\n 5th Dimension (jEWEL/tENSION)\n Total Eclipse (zCANDALER/dUPLO^cOMAX)\n Unicorn       (gUARDIAN)\n\nGreetings\n~~~~~~~~~\n           Greetings to the following doodes, no special order:\n\n         · PraWL/CRAZE · Mr Real/CRAZE · Rick/CRAZE · Zik/CRAZE ·\n    · Monolith/CRAZE · All the other CRAZE members · Kid Curry/Classic ·\n · PVV · Zcandaler!/DPL^CMX · Demax/Delight · Ace Caze/Obscene · Tango/DPL ·\n· Danzig · Karma · Juan/TRSI · Bobo/Mystic · Xerxes/FLT^MST · Cybertron/EQX ·\n','\n',char(10)),'{"LOCATION":"Doors:Time","STACK":"4000","TYPE":"XIM"}','auto-added',29640,3,0,NULL,NULL,'crz_bt11','scan',1780048448);
INSERT INTO door_catalog VALUES('crz_ds11','CRZ-DS11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CRZ-DS11.LHA','Ds','XIM','_________________________·:·__________·::E^d',NULL,'nIKE','CRZ','\___ \________/\_____   ¬\_/________/ \·:::: ·\/   _/______\ \__/    _/\    _______/\·::: /¯   /__     ¬\\/__      \ \  /__     ¯¬\·::',replace('_________________________·:·__________·::E^d\n\___ \________/\_____   ¬\_/________/ \·::::\n·\/   _/______\ \__/    _/\    _______/\·:::\n/¯   /__     ¬\\/__      \ \  /__     ¯¬\·::\n\______/       \_/        \/____/-CRAZE- \·:\n.\  \__________/\\________/\ \___________/\·\n:.\__\         \ \\       \ \_\          \ \\n::HrP.\_________\/.\_______\/..\__________\/\n[÷-------------÷) Presents (÷-------------÷]\n         SysopDownload v1.1 by nIKE\n[÷-------------÷) in 1994! (÷-------------÷]\n','\n',char(10)),'Ds.Doc',replace('               _________________________·:·__________·::E^d\n               \___ \________/\_____   ¬\_/________/ \·::::\n               ·\/   _/______\ \__/    _/\    _______/\·:::\n               /¯   /__     ¬\\/__      \ \  /__     ¯¬\·::\n               \______/       \_/        \/____/-CRAZE- \·:\n               .\  \__________/\\________/\ \___________/\·\n               :.\__\         \ \\       \ \_\          \ \\n               ::HrP.\_________\/.\_______\/..\__________\/\n\n                        Presents another /X^S!X Door\n\n                    -^(· SysopDownload v1.1 by Nike ·)^-\n\nContents of the file should be:\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nDoors/Craze/Ds                 3028 bytes    The Main File.\nDoors/Craze/Ds.Doc             1629 bytes    This doc file.\nBBS:Commands/BBSCmd/Ds.Info     567 bytes    The icon file.\n\nDescription.\n~~~~~~~~~~~~\nReplacement for the internal DS command.\nAllows anyone with a password to download files from your HD without having\nsysop access. Supports "RESTRICTED" Filecomments just as /X does.\n\nInstalling this damn door:\n~~~~~~~~~~~~~~~~~~~~~~~~~~\nDo the normal procedure!\n\nHistory:\n~~~~~~~~\nv1.0	--	First version. Took me about 15 minutes to make including\n            support for RESTRICTED.\n\nv1.1	--	First RELEASED version. Fixed some minor bugs.\n\nGreetings\n~~~~~~~~~\n\n           Greetings to the following doodes, no special order:\n\n         · PraWL/CRAZE · Mr Real/CRAZE · Rick/CRAZE · Zik/CRAZE ·\n    · Monolith/CRAZE · All the other CRAZE members · Kid Curry/Classic ·\n · PVV · Zcandaler!/DPL^CMX · Demax/Delight · Ace Caze/Obscene · Tango/DPL ·\n· Danzig · Karma · Juan/TRSI · Bobo/Mystic · Xerxes/FLT^MST · Cybertron/EQX ·\n','\n',char(10)),NULL,NULL,10208,2,0,NULL,NULL,'crz_ds11','scan',1780048448);
INSERT INTO door_catalog VALUES('crz_dz10','CRZ-DZ10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CRZ-DZ10.LHA','DMSDescript','XIM','DMSDescript',NULL,'Nike/CraZe','CRZ','/Y \_____Y\___  ¬Y  \_  ¬Y____/ Y \____Y\ //|   |___|   |   |   |   |  ____|  ____|\\ / |   |  ¬|  _|   |  _|   |  |  ¬|  |  ¬| \\',replace('HrP_______ _______ _______ ______ ______E^d\n /Y \_____Y\___  ¬Y  \_  ¬Y____/ Y \____Y\\n//|   |___|   |   |   |   |  ____|  ____|\\\n/ |   |  ¬|  _|   |  _|   |  |  ¬|  |  ¬| \\\n::|   |   |  \_  -[  \_   |  |   |  |   |::X\n\ |   ¦   |   |   |   |   |  ¦   |  ¦   | //\n\\|       |   |   |   |   |      |      |//\n \A_______A___|___A___|___A______A______A/\n         SpeedIz v1.0 by Nike/CraZe\n        Cool Util for all U traders!\n  .oO lEEcHeD fRoM tRaDeR''S pARaDiSe Oo.\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 19:28:19  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',76465,2,0,NULL,NULL,'crz_dz10','scan',1780048448);
INSERT INTO door_catalog VALUES('crz_ec11','CRZ-EC11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CRZ-EC11.LHA','ExeChecker','XIM','ExeChecker',NULL,'RiCK/CRZ','CRZ','/Y \_____Y\___  ¬Y  \_  ¬Y____/ Y \____Y\ //|   |___|   |   |   |   |  ____|  ____|\\ / |   |  ¬|  _|   |  _|   |  |  ¬|  |  ¬| \\',replace('HrP_______ _______ _______ ______ ______E^d\n /Y \_____Y\___  ¬Y  \_  ¬Y____/ Y \____Y\\n//|   |___|   |   |   |   |  ____|  ____|\\\n/ |   |  ¬|  _|   |  _|   |  |  ¬|  |  ¬| \\\n::|   |   |  \_  -[  \_   |  |   |  |   |::X\n\ |   ¦   |   |   |   |   |  ¦   |  ¦   | //\n\\|       |   |   |   |   |      |      |//\n \A_______A___|___A___|___A______A______A/\n------- ÷P·R·e·S·e·N·T·S÷÷T·o·D·a·Y÷ -------\nEXECHECKER V1.1 by RiCK/CRZ  1mB/2 sec! NiCE\n SiMPLy THe BeST!  eVeRY SySoP SHouLD uSE iT\n','\n',char(10)),'ExeChecker.Doc',replace('\n                     ExeChecker v1.1 by RiCK/CRaZe 1994\n                     ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nWhy shoud I use this one?\n~~~~~~~~~~~~~~~~~~~~~~~~~\n· Becoz it''s the fastest and the most detailed exe checker avaible on the\n  scene today, and it''s really simple!\n· Speed example: dopus, 273256 bytes: 0.98 sec on a 68000!\n· This code WONT crash, becoz it isn''t any bugs in it ;)\n· It''s coded by me!\n\nHow to install\n~~~~~~~~~~~~~~\nJust copy all the files in the bbs/ dir man, and it should work just fine\n(havn''t test it..)\n<does anyone read this "how to install" shit? Don''t think anyone\nwould have any problems with it..>\n\n\nSupport\n~~~~~~~\nBoard:   Cyber Force +46-510-ELITEKNOWS (NUP)\nFidoNet: 2:203/709.2 (any name..)\nCoolNet: RiCK@CF\n\n\nDo you have /X and want to join coolnet? -> Contact me!\nDo you know any good-locking girls? ------> Contact me!\n','\n',char(10)),NULL,'auto-added',6047,2,0,NULL,NULL,'crz_ec11','scan',1780048448);
INSERT INTO door_catalog VALUES('crz_fa10','CRZ-FA10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CRZ-FA10.LHA','FastAdd','XIM','FastAdd',NULL,'nIKE','CRZ','\___ \________/\_____   ¬\_/________/ \·:::: ·\/   _/______\ \__/    _/\    _______/\·::: /¯   /__     ¬\\/__      \ \  /__     ¯¬\·::',replace('_________________________·:·__________·::E^d\n\___ \________/\_____   ¬\_/________/ \·::::\n·\/   _/______\ \__/    _/\    _______/\·:::\n/¯   /__     ¬\\/__      \ \  /__     ¯¬\·::\n\______/       \_/        \/____/-CRAZE- \·:\n.\  \__________/\\________/\ \___________/\·\n:.\__\         \ \\       \ \_\          \ \\n::HrP.\_________\/.\_______\/..\__________\/\n[÷-------------÷) Presents (÷-------------÷]\n            FastAdd v1.O by nIKE\n[÷-------------÷) in 1994! (÷-------------÷]\n','\n',char(10)),'FastAdd.Doc',replace('               _________________________·:·__________·::E^d\n               \___ \________/\_____   ¬\_/________/ \·::::\n               ·\/   _/______\ \__/    _/\    _______/\·:::\n               /¯   /__     ¬\\/__      \ \  /__     ¯¬\·::\n               \______/       \_/        \/____/-CRAZE- \·:\n               .\  \__________/\\________/\ \___________/\·\n               :.\__\         \ \\       \ \_\          \ \\n               ::HrP.\_________\/.\_______\/..\__________\/\n\n                        Presents another /X^S!X Door\n\n                      -^(· FastAdd v1.O by Nike ·)^-\n\nContents of the file should be:\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nC/FastAdd                      3164 bytes    The Main File.\nS/Craze.Txt                    1218 bytes    Example file.\nFcheck/Nfo.Info                 543 bytes    Icon for .Nfo files.\nFcheck/Doc.Info                 543 bytes    Icon for .Doc files.\nFcheck/Txt.Info                 543 bytes    Icon for .Txt files.\n\nDescription.\n~~~~~~~~~~~~\nThis is another Textadder for You''re board.\nThis is not as configurable as others that adds the textfiles and strips, and\nadds some variables etc, but It''s FAST! That''s the idea of this Program!\nIf you just want the speed and not some configfiles that needs to be changed\nthen use this program.\n\nInstalling this damn util:\n~~~~~~~~~~~~~~~~~~~~~~~~~~\nCopy the Files in C/ to C:\nCopy the files in Fcheck/ to BBS:Fcheck/\nMake your own add (can be before or after the text file, and both if you want).\nConfigurate the fcheck icons so that your add will be appended.\n\nArguments:\n~~~~~~~~~~\nFastAdd <Front Add> <Tail Add> <Filename>\n\nIf you do NOT want to add a front or a Tail add, then set the argument to NONE.\n\nExamples.\n	FastAdd S:Craze.Txt NONE\n\nAdds the file S:Craze.Txt as a HEADER file in the textfile and doesn''t add\nany file as a tail file.\n\n(AmiExpress will add the filename by itself so you do not need to enter that\nin the icon).\n\nPretty easy?!\n\nHistory:\n~~~~~~~~\nv1.0	--	First version. Coded in about 5 minutes.\n\nGreetings\n~~~~~~~~~\n\n           Greetings to the following doodes, no special order:\n\n         · PraWL/CRAZE · Mr Real/CRAZE · Rick/CRAZE · Zik/CRAZE ·\n    · Monolith/CRAZE · All the other CRAZE members · Kid Curry/Classic ·\n · PVV · Zcandaler!/DPL^CMX · Demax/Delight · Ace Caze/Obscene · Tango/DPL ·\n· Danzig · Karma · Juan/TRSI · Bobo/Mystic · Xerxes/FLT^MST · Cybertron/EQX ·\n','\n',char(10)),NULL,'auto-added',5701,3,0,NULL,NULL,'crz_fa10','scan',1780048448);
INSERT INTO door_catalog VALUES('crz_fw11','CRZ-FW11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CRZ-FW11.LHA','WALL','XIM','PrIvAtE!.eXe',NULL,'nIKE/cRAZE!','CRZ','\___ \________/\_____   ¬\_/________/ \·:::: ·\/   _/______\ \__/    _/\    _______/\·::: /¯   /__     ¬\\/__      \ \  /__     ¯¬\·::',replace('_________________________·:·__________·::E^d\n\___ \________/\_____   ¬\_/________/ \·::::\n·\/   _/______\ \__/    _/\    _______/\·:::\n/¯   /__     ¬\\/__      \ \  /__     ¯¬\·::\n\______/       \_/        \/____/-CRAZE- \·:\n.\  \__________/\\________/\ \___________/\·\n:.\__\         \ \\       \ \_\          \ \\n::HrP.\_________\/.\_______\/..\__________\/\n============)> BRiNGS YoU ToDAY <(==========\nfAST wALL! v1.1 bY nIKE/cRAZE! rOOLiNG wALL!\n============================================\n','\n',char(10)),'Wall.Doc',replace('    __________________ _ ________________________________._ _________\n   _)       _________/    __      _____    \_.______  _  |     _____/_\n   \  cG·dP /       |      /_____/   _/      |     ______j  _________/_\n    \ - - -/        |        |       \       |    /      ·  \         /\n     \____/_________l________l________\______!___/_______|---\_______/\n\n                     ==)> Presents 2 ya in 1994! <(==\n\n                      fAST wALL v1.1 bY nIKE/cRAZE\n\nIntroduction:\n=============\nAnother wall! It has some kewl features I missed in SiLWALL which (In my humble\nopinion) always has been the best wall.. and of course the options i DIDN''T\nmiss...:)..here''s a list of the things in this door:\n\no It displays the lines to the user according to the users screen length.\n  Max 100 lines.\no The user can write Anonymous.\no The sysop can see who wrote something anonymous! =)..\n  (This feature ROOLES! =))\n  The users name will be displayed in *YELLOW* instead of GREEN if it is\n  anonymous so the sysop knows if it is anonymous or if the user is dumb..:)\no The sysop can write something very important and it will be displayed\n  with another colour then it normally would.\no You can kick a user from the wall, meaning that he will not be allowed to\n  watch or write to the wall.\no The wall is pretty fast.\no The wall looks pretty good (I''ve "ripped off" some design from Aquarius\n  Aquascan! Sorry doode, you''re doors look too good =))\no etc.\n\nInstallation:\n=============\nCopy the files as they are when u unpacked the archive.\nEdit the file "Doors:FastWall/FastWall.Exclude" with the users you DON''T want\nto be able to write on the wall. 1 user pr line. NOT Case sensitive.\nThe datafile will automatically be created if it does not exist.\n\nHistory:\n========\nv1.0    - No special features. Only write on the wall, and view it.\n          Not released.\nv1.1    - This version.\n\nGreetings:\n==========\n                        -> All members of CRAZE <-\n  -> Aquarius/OutLaws - Bobo/Mystic - Xerxes/Fairlight - Demax/Delight <-\n-> Zcandaler/Duplo! - Juan/tRSi - Dr.Dre!/tRSi - Boromir/tRSi - Guardian <-\n           -> those i''ve forgot in this short greetings list! <-\n','\n',char(10)),NULL,'auto-added',31620,3,0,NULL,NULL,'crz_fw11','scan',1780048448);
INSERT INTO door_catalog VALUES('crz_fw12','CRZ-FW12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CRZ-FW12.LHA',NULL,'XIM','Aedoor.Library',NULL,'nIKE/cRZ^dLT!','CRZ','.___\___     /_._\_____     /___\_____    / |      /____/  |    _|/   _/__    _______/__ |    _/        |    \        /    \        /',replace('    __________   ____________   ___________\n.___\___     /_._\_____     /___\_____    /\n|      /____/  |    _|/   _/__    _______/__\n|    _/        |    \        /    \        /\n|______________|_____\      /_____________/\n-mNt/aC!              \____/ sPURTS yA wiTH\n[ -+-----------------------------------+- ]\n[ -+-  fASTwALL 1.2 bY nIKE/cRZ^dLT!  -+- ]\n[ -+-----------------------------------+- ]\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 19:28:15  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',2093,1,0,NULL,NULL,'crz_fw12','scan',1780048448);
INSERT INTO door_catalog VALUES('crz_hp10','CRZ-HP10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CRZ-HP10.LHA','eVaCeHT','XIM','eVaCeHT',NULL,NULL,'CRZ','\___ \________/\_____   ¬\_/________/ \·:::: ·\/   _/______\ \__/    _/\    _______/\·::: /¯   /__     ¬\\/__      \ \  /__     ¯¬\·::',replace('_________________________·:·__________·::E^d\n\___ \________/\_____   ¬\_/________/ \·::::\n·\/   _/______\ \__/    _/\    _______/\·:::\n/¯   /__     ¬\\/__      \ \  /__     ¯¬\·::\n\______/       \_/        \/____/-CRAZE- \·:\n.\  \__________/\\________/\ \___________/\·\n:.\__\         \ \\       \ \_\          \ \\n::HrP.\_________\/.\_______\/..\__________\/\n[÷-------------÷) Presents (÷-------------÷]\n                aEhELP v1.o!\n[÷-------------÷) in 1994! (÷-------------÷]\n','\n',char(10)),'Help.Doc',replace('               _________________________·:·__________·::E^d\n               \___ \________/\_____   ¬\_/________/ \·::::\n               ·\/   _/______\ \__/    _/\    _______/\·:::\n               /¯   /__     ¬\\/__      \ \  /__     ¯¬\·::\n               \______/       \_/        \/____/-CRAZE- \·:\n               .\  \__________/\\________/\ \___________/\·\n               :.\__\         \ \\       \ \_\          \ \\n               ::HrP.\_________\/.\_______\/..\__________\/\n\n                      P·R·O·U·D·L·Y·? P·R·E·S·E·N·T·S\n\n                               AeHelp v1.0a\n\nDescription.\n~~~~~~~~~~~~\nOn-Line help door. Easy to install/use.\n\nInstalling this damn door:\n~~~~~~~~~~~~~~~~~~~~~~~~~~\nShould be self-explaining?!\n\nConfigurating it:\n~~~~~~~~~~~~~~~~~\nYou can edit the files how much you want (except for the main file).\nJust load ''em in to a text editor and edit them!!\nThe file "HelpMenu.Txt" (and .Gr) is the main menu.\nThe other files there called "C.Txt" etc is the help for that command..\n(C.Txt is help for "C" in /X etc).\n!!!!!!!!!!!!!!!!!!!!!!!!!!For the door coders:!!!!!!!!!!!!!!!!!!!!!!!!!!!\nIf you release a door, then put a file with your suggested command name<.Txt>\nin the archive when u release it, that contains a help file! We could make\nthat a new (and pretty ok?) standard!\n!!!!!!!!!!!!!!!!!!!!!!!!!!For the door coders:!!!!!!!!!!!!!!!!!!!!!!!!!!!\n','\n',char(10)),NULL,'auto-added',26185,7,0,NULL,NULL,'crz_hp10','scan',1780048460);
INSERT INTO door_catalog VALUES('crz_pfx1','CRZ-PFX1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CRZ-PFX1.LHA',NULL,'XIM','.----[ c R A Z e ]----.            - --.',NULL,NULL,'CRZ',': __________________  :  Fast-Express  : .___:_\___ \_____`-.___ \_:_____ | ___/  _/ _/   `- | .---'' ____/_ 13-O2-96',replace('    .----[ c R A Z e ]----.            - --.\n    : __________________  :  Fast-Express  :\n.___:_\___ \_____`-.___ \_:_____\n| ___/  _/ _/   `- | .---'' ____/_ 13-O2-96\n| \   \-\____\--\__|-----+ __/  /\n`cDr:--\                 `:-e^d/ Lidköping :\n    `-[ p r e s e n t s ]-''            - --''\n     Fast Express Preview + ScreenShots\n      + Important messages from niKE!\n','\n',char(10)),'Previews.Readme',replace('                        ·\012            __         __\__________\012         .__\//\__________\___     /_______ ____ ___________  ______.\012         |: \/     ____.  /  /   _/_ ,_  _/ _____\__ __    /// ··×X&|\012         |X.      /  __|_/__ \_____/ _/   \_\__    / _/___/       ·X|\012         |&Xx..  /   |     /___\ /   \_____/  ____/  `___\ ___  /\_:|\012          ¯¯¯¯¯\\\________/·zS!·/______\ /    `__\_____\      \//\\012                                        /_______\__             ¯¯\012                                                 \\012                                                  ·\012                              P r e s e n t s\012\012                       FastExpress (F!X) ScreenShots\012\012                       v1.0 Mon Feb 12 21:44:15 1996\012\012                     By NIKE / cRAZe&tRSi&dELIGHt&cRUx\012\012Here you go. This file has some screenshots, a feature list and some more\012things... The feature list was taken from my head at a small meeting here,\012so the list is far from complete. Expect a new update of this file very\012soon.\012\012   This file will be updated when I have updated FastExpress very much.\012\012See the end of this file for some very important news and messages. Thanks.\012\012Features:\012~~~~~~~~~\012  ( * = Feature implanted, + = In progress, - = Will be implanted soon )\012\012   * Almost All features found in AmiExpress v4.12\012\012   * Special Extended FastExpress XIM format (Doors will be able to\012                                              read SHIFTED Keys, F keys etc)\012\012   * Low memory consuming (Right now about 200kB pr node, NOT residented)\012\012   * Telnet support (of course)\012\012   * NO MORE ICONS! FastExpress has its own config format.\012\012   * Easy to use config program. Start it for the first time, and it reads\012     all the amiexpress icons. (S-Express support will soon be added)\012\012   * Uses the same user.data etc as AmiExpress\012\012   * Is 100% Compatible with AmiExpress (U can even run One node F!X & One /X)\012\012   * Updated ACP called FCP. This one reads all configs so each node doesn''t\012     have to read the config file by itself (saves memory).\012\012   * Better Nullmodem support. Just press SPACE on the remote machine to\012     logon. No more "RING\nCONNECT 359350948509438509348"\012\012   * 90% Asm Code in the release version. (The rest In AMIGA E).\012\012   * ALL XPR! support and HYDRA support of course.\012\012   * Extended MCI commands.\012\012   * Faster Door communication.\012\012   * Overall speed increase by at least 25%.\012\012   * Better prompt command (you can edit the commands you enter on the prompt)\012\012   * Very optimized serial routines.\012\012   * Never hangs (I promise)\012\012   * Uses Kick 3.0/3.1 specific routines for faster results. This means\012     UPGRADE TO KICK 3.1 NOW!\012\012   * Fast updates (Not like AmiExpress). The development is written in\012     AMIGA E which is very easy to use to update. When i have no updates\012     to do, I optimize the old routines to Asm. This means that speed will\012     improve very much all the time.\012\012   *** Internal SNES emulator (1 fps on a a500 1.2 512k mem).\012   **** Internal PLAYSTATION emulator (1 fps on a a500 1.2 512k mem).\012\012   + External design files.\012\012   + Parallel support (You can login from a remote computer using the par\012                  port (instead of nullmodem, with a normal parnet cable)\012\012   + Email support. People will be able to email to your board if you are\012     using Amitcp etc.\012\012   - Special F!X-Net will be started when at least 5 boards are running\012     FastExpress\012\012\012\012IMPORTANT INFO!!\012~~~~~~~~~~~~~~~~\012\012There are a lot of rumours about me going around.. The rumours that I will\012get 5 years of jail and shit like that are very amusing to hear....\012The facts are these..\012\012TELIA (The swedish telecom) found out that i have used a PBX and stuff like\012that.. They said that If I pay the bill they would not involve the police.\012I said "Noway i''m gonna pay for those calls, I didn''t make them" blah blah..\012Well, I have had a little fight with them.. they are refusing me to have a\012phone until I have payed and this thing gets out of the world..\012Well, they involved the police some days ago, but the police sent me a letter\012and told me that the evidence that TELIA has no good evidence and they will\012not even investigate until they give them some good proof. This means, I\012will get back my telephonelines in a couple of weeks, so please be patient!\012\012I *will* get back. I have *NOT* left the scene as some people are saying.\012             (And those who says so, slicka mein big dolmis!)\012\012Messages:\012~~~~~~~~~\012Shane          : It''s a bit hard to contact you another way, but now you\012                 know.. I''ll call you when I get back.\012                 Please say hello to all Cruxers for me!\012Agressor       : I HAVE tried to call you, No answer or noone at home.. \012                 But now you also know.. I''ll be back homie!\012Shade          : Hey mate, did you get the disks? I hope so.. Send me some\012                 disks back eh? .. I want some more trsi recordz stuff!\012U-man          : Buffel buffel.. Ringer din bräda sen..\012Mode           : Ringer dej..\012Xerxes         : Fastexpress rular mkt mer än du tror din fjärt..\012Mad Max&Juan   : Räjv on! =) (Juan, grattis!!)\012Baffle         : Sorry at jeg Ikke kom til Kindergarden, men jeg fikk ikke\012                 med meg noen små idiot svensker.. ;) (Hvem sa Marwic??)\012Marwic         : You are my first Beta tester.\012Excel          : Gha!! I need your address.. !! Now! Or Open a Postgiro!!\012\012\012\012\012\012                               I hate telia.\012                        Telia - Steals your money.\012\012\012\012\012\012\012\012\012\012\012\012\012\012\012                       Contact me at Nuclear Waste:\012\012  ___________  .____. ________________   _________  ________. ________.\012._\   _     /__|_   |_\   _     /    / __\  _____/__\____   |_\  __   | --.\012|     /    /    /   |     /____/    /__\     __/_\     _    |    \____|   |\012|____/    /    /    |    /    /    /    \    \    \    \    |     \       |\012    /____/__________|________/___________\_________\________|______\pHS!  |\012|                         _____    ________. _______   ___.     _________ |\012|  [ NUCLEAR WASTE ]    __\__  \___\____   |_\  ___/_._\  |__ __\  _____/ |\012|                      /    /   \     _    |\_____   |    __/_\     __/__ |\012|  ·aMIGA & cONSOLE·  /    /\    \    \    |    /    |    \    \    \    \\012`------------------- /_____/\_____\________|_________|__________\_________\\012\012     +46-510-27173 & +46-510-27176 & 130.242.TEL.NET & 130.242.TEL.NET\012\012\012\012\012\012\012\012\012\012Plufftelepluff..','\012',char(10)),NULL,NULL,14051,3,0,NULL,NULL,NULL,'scan',1780048460);
INSERT INTO door_catalog VALUES('crz_sm10','CRZ-SM10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CRZ-SM10.LHA','slot','XIM','slot',NULL,NULL,'CRZ','\___ \________/\_____   ¬\_/________/ \·:::: ·\/   _/______\ \__/    _/\    _______/\·::: /¯   /__     ¬\\/__      \ \  /__     ¯¬\·::',replace('_________________________·:·__________·::E^d\n\___ \________/\_____   ¬\_/________/ \·::::\n·\/   _/______\ \__/    _/\    _______/\·:::\n/¯   /__     ¬\\/__      \ \  /__     ¯¬\·::\n\______/       \_/        \/____/-CRAZE- \·:\n.\  \__________/\\________/\ \___________/\·\n:.\__\         \ \\       \ \_\          \ \\n::HrP.\_________\/.\_______\/..\__________\/\n[÷-------------÷) Presents (÷-------------÷]\n              sLOT mACHINE v1.o\n[÷-------------÷) in 1994! (÷-------------÷]\n','\n',char(10)),'slot.doc',replace('               _________________________·:·__________·::E^d\n               \___ \________/\_____   ¬\_/________/ \·::::\n               ·\/   _/______\ \__/    _/\    _______/\·:::\n               /¯   /__     ¬\\/__      \ \  /__     ¯¬\·::\n               \______/       \_/        \/____/-CRAZE- \·:\n               .\  \__________/\\________/\ \___________/\·\n               :.\__\         \ \\       \ \_\          \ \\n               ::HrP.\_________\/.\_______\/..\__________\/\n\n                      P·R·O·U·D·L·Y·? P·R·E·S·E·N·T·S\n\n                      sLOT mACHINE v1.o by cRAZE ''94\n\nDescription.\n~~~~~~~~~~~~\n Just a funny door..\nLet''s the user gamble his/her uploaded bytes, and either win or loose!\nBtw, this door may not be used by RHYS/DELIRIUM! You are a lame as-hole!!\n\nInstalling this damn door:\n~~~~~~~~~~~~~~~~~~~~~~~~~~\nCopy "Slot" to any dir you''d like it in..\nCopy the icon and edit it (LOCATION=Doors:Slot f.ex.)\nStack=4000\nType=XIM\n\nInfo ''bout CraZe!\n~~~~~~~~~~~~~~~~~\nWe need gfxers! If u''re interested, call Instant Pleasure or Dystophia.\n\nHISTORY:\n~~~~~~~~~\nv1.0      - This version.\n\nOFFICIAL Beta testers for nIKE/cRAZE''s doors:\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n Global Effect (Xerxes/Mystic^Orient)\n Nuclear Waste (mARWic/cRAZE^eQUINOX^dREAM fREQUENCY^nUTS)\n 5th Dimension (Jewel/Tension)\n','\n',char(10)),'{"LOCATION":"Doors:Slot","STACK":"4000","TYPE":"XIM"}','auto-added',5703,1,0,NULL,NULL,'crz_sm10','scan',1780048460);
INSERT INTO door_catalog VALUES('crz_ul10','CRZ-UL10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CRZ-UL10.LHA','userlist','XIM','PrIvAtE!.eXe',NULL,NULL,'CRZ','\___ \________/\_____   ¬\_/________/ \·:::: ·\/   _/______\ \__/    _/\    _______/\·::: /¯   /__     ¬\\/__      \ \  /__     ¯¬\·::',replace('_________________________·:·__________·::E^d\n\___ \________/\_____   ¬\_/________/ \·::::\n·\/   _/______\ \__/    _/\    _______/\·:::\n/¯   /__     ¬\\/__      \ \  /__     ¯¬\·::\n\______/       \_/        \/____/-CRAZE- \·:\n.\  \__________/\\________/\ \___________/\·\n:.\__\         \ \\       \ \_\          \ \\n::HrP.\_________\/.\_______\/..\__________\/\n[÷-------------÷) Presents (÷-------------÷]\n         User-List (realtime) v1.0a\n[÷-------------÷) in 1994! (÷-------------÷]\n','\n',char(10)),'Userlist.doc',replace('    __________________ _ ________________________________._ _________\n   _)       _________/    __      _____    \_.______  _  |     _____/_\n   \  cG·dP /       |      /_____/   _/      |     ______j  _________/_\n    \ - - -/        |        |       \       |    /      ·  \         /\n     \____/_________l________l________\______!___/_______|---\_______/\n\n                     ==)> Presents 2 ya in 1994! <(==\n\n                        -^(· User-List v1.0a ·)^-\n\nIntroduction:\n=============\nUserlister. Some new (?) options like Zippy search not found in other\ndoors (i think?)..\n\no Zippy Search for a user.\no "Realtime" userlisting instead of running another utility in your logoff\n  batch.\no Fast enuff\no Cool enuff (?)\no etc.\n\nInstallation:\n=============\nCopy the files as they are when u unpacked the archive.\n\nHistory:\n========\nv1.0    - This version.\n\nGreetings:\n==========\n                        -> All members of CRAZE <-\n  -> Aquarius/OutLaws - Bobo/Mystic - Xerxes/Fairlight - Demax/Delight <-\n-> Zcandaler/Duplo! - Juan/tRSi - Dr.Dre!/tRSi - Boromir/tRSi - Guardian <-\n           -> those i''ve forgot in this short greetings list! <-\n','\n',char(10)),NULL,'auto-added',42167,6,0,NULL,NULL,'crz_ul10','scan',1780048460);
INSERT INTO door_catalog VALUES('cscan26b','CSCAN26B.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CSCAN26B.LHA','ConfScan','XIM','AmigaGuide',NULL,NULL,NULL,'\__ ¬\/¬\\__ ¬Y \__  __\_____¬\__ ¬\__    ¬\ /¬      \/\  l  /\   ¬\/    ¬\/¬\__/¬  \__/ /   \  /  \ \   /  \    \      \   ¬\   / ¬\',replace('_____  _ _____ ____________________________ \n\__ ¬\/¬\\__ ¬Y \__  __\_____¬\__ ¬\__    ¬\\n /¬      \/\  l  /\   ¬\/    ¬\/¬\__/¬  \__/\n/   \  /  \ \   /  \    \      \   ¬\   / ¬\\n\___/\/    \___/    \_   \_____/     \_____/\n|----(______)-(___________)-(_________)ppx-|\n| CONFERENCE SCAN v2.6 - iNTERMEDiATE REL. |\n+------------------------------------------+\n| o Ami-Express 3.38+ and 4.x Compatible!  |\n| o Remembers flagged files after log off! |\n| o Much more! Read inside!                |\n`-----------------------[KiLLraVeN/MYSTiC]-''\n','\n',char(10)),'ConfScan.Guide',replace('@DATABASE "ConfScan.GUiDE"\012@REMARK .------------------------------------------------------------------.\012@REMARK | This document is written in AmigaGUiDE format, so please read it |\012@REMARK | with AmigaGUiDE or your favourite guide reader.... ciao now...   |\012@REMARK `------------------------------------------------------------------''\012@REMARK $VER: ConfScan v2.6.06\012@WiDTH 80\012@NODE MAiN "Guide to ConfScan v2.6.06 - /X-PoWeR! - Written by KiLLrAvEn/MYSTiC"\012                               Guide to ConfScan\012                     for Ami-Express Bulletin Board Systems\012\012                          Program version: 2.6.06\012              Compilation Date/Time: Oct 7th 1994 - 23:21:06\012\012                         © 1993-94 by @{"KiLLRaVeN/MYSTiC" link Killraven}\012                          ASM Coding by ArCaDe/MYSTiC\012\012                ... another fine MYSTiC /X PoWeR! production...\012\012                 @{"      READ THiS FiRST FOR THE LATEST iNFO!     " link Important}\012\012                 @{"    Introduction    " link introduction}      @{" History of ConfScan " link History}\012                 @{"     Features!      " link     Features}      @{"    Known Bugs       " link Bugs}\012                 @{"    Requirements    " link Requirements}      @{" Possible error msgs " link Errors}\012                 @{"    Installation    " link installation}      @{" Future improvements " link Future}\012                 @{"    Configuration   " link Configuration}      @{"     Greetings       " link Greetings}\012                 @{"  Usage (by users)  " link        Usage}      @{"  Registered users!  " link Registration}\012\012                 @{"    ConfScan_DL     " link ConfScan_DL }      @{"     KiLLER iNFO     " link KiLLER}\012@EndNode\012\012@Node Introduction "Introduction to ConfScan - /X-PoWeR! - Written by KiLLrAvEn/MYSTiC"\012                     - - ­ ­ ­ [ iNTRODUCTiON ] ­ ­ ­ - -\012\012   Welcome to ConfScan!\012\012   ConfScan  was  written  during a period of 1 year and has become quite\012   a  powerful  program  with  many possibilities and great potential.  I\012   have spent a lot of time programming and testing it so I hope you will\012   like it and use it with pleasure.\012\012   A little bit of history...\012\012   At first ConfScan was merely meant as a small util that enabled sysops\012   to  easily  check  what  was uploaded in all the different conferences\012   without  having  to  join them one by one.  The very first version did\012   nothing  more  than  that.  That was version 1.0.  It was never really\012   released but to a few friends.\012\012   Nowadays ConfScan can perform a much greater task than just displaying\012   some  filenames  on  the  screen.  ConfScan can now be used to control\012   some  main  parts  of  the  bulletin  board  system Ami-Express.  With\012   ConfScan  you  can  scan for new files, view them from within ConfScan\012   and you can even Nuke files with ConfScan.  Usage of ConfScan has been\012   made as intuitive as possible and should be very easy to use.\012\012   ConfScan  is  an  intelligent program, detecting the options for every\012   user  using  ConfScan, not showing options that they don''t have access\012   for.   ConfScan  also recognizes Ami-X Net conferences that usually do\012   not have file bases, as a result these conferences without a file base\012   are not shown in the config menu (''CS W'').\012\012   ConfScan  comes  with  a  highly user friendly GUi Config program!  No\012   more  tooltypes  to fill in by the sysop!  Just start the program from\012   the CLi or Workbench and CLiCK the options you want and save''m!\012\012   ConfScan  is  made  in a way that you don''t have to repeat information\012   that  is  already known is other files or icons.  ConfScan knows where\012   to find it and will use it.  But in my opinion that is something every\012   program  should  support.   Besides that, if you have any problem with\012   ConfScan  you  can  always reach me for support, I am offering support\012   for all registered sysops of Ami-Express, FOR FREE!\012\012   But  not only for you, the sysop, ConfScan is a must.  Your users will\012   also  appreciate  it  since  ConfScan  allows users to tag their files\012   instead  of  flagging them (but they can still flag files if they want\012   to  ofcourse)  and  ConfScan  enabled  them  to  download  files  from\012   different   conferences  without  having  them  to  jump  through  the\012   conferences  by  theirselves.   in  the  near  future, it will also be\012   possible  to  download all files from all conferences in one time!  So\012   look out for the coming version!\012\012   ConfScan also offers your users a large configurability.  ConfScan has\012   a Config Menu built in so they can easily adjust their preferences.\012\012   A seperate Download door enables you to put restrictions on downloads.\012   With  the  GUi  Config  program  you can easily exclude conferences or\012   nodes from downloading.  You can put accesslevels on nodes/conferences\012   or  even  use userlists for download access on nodes/conferences.  And\012   all  this  information is again saved by the Config program, so you do\012   not have to fill in any tooltypes (GUi Config does that for you).\012\012   if  this  sounds  like  a  useful  program in your ears, check out the\012   @{"features" link features} to find out more.  Or at least start the GUi Config.\012\012                                                        @{"-KiLLrAvEn/MYSTiC" link Killraven}\012\012@EndNode\012\012@Node Requirements "What DO you need? - /X-PoWeR! - Written by KiLLrAvEn/MYSTiC"\012                   - - - ­ ­ ­ [ REQUiREMENTS ] ­ ­ ­ - - -\012\012   The  requirements can differ a lot since you can setup ConfScan anyway\012   you  like,  but  if  you  want to use ConfScan to the fullest you need\012   this:\012\012   · @{" Ami-Express BBS " link Ami-X} version 3.38+ (/X 4.x is supported)\012   \012     YOU NEED VERSiON 3.38 OR HiGHER TO RUN THiS PROGRAM, PLEASE OBTAiN\012     THE LATEST VERSiON FROM YOUR DEALER (SEE "AMi-EXPRESS BBS").\012\012   · @{" Clean dir files " link CleanDir}\012\012   For the support of [V]iewing files you need to have in your C: dir\012   · DMS\012   · LHA\012   · UNZiP\012\012   If you want to be able to nuke files with ConfScan you need to have\012\012   · @{" KiLLER " link KiLLER}\012\012   installed on your system.\012\012@EndNode\012\012@Node CleanDir "VERY iMPORTANT! READ THiS! - By KiLLraVeN/MYSTiC"\012                 - - - ­ ­ ­ [ CLEAN DiR FiLES ] ­ ­ ­ - - -\012\012   This  may sound obvious, but to get the most out of ConfScan, you need\012   to  have  clean  dir files.  So no taglines or any other alien text in\012   your dir files.\012\012   There is one exception on the other hand, there is one program you are\012   allowed to use to alter your dir file and that is DirStyle by The Bird\012   of  TRSi.   Support  for this dirstyler is built in to ConfScan.  This\012   was  done  after a request from Sal-One/TRSi.  If you have a dirstyler\012   that  you  would like to have support for, contact me and maybe we can\012   work something out.\012\012   Nukers on the other hand cause no problems.  You are free to use them,\012   even better, there is support for two nukers:  BossNuke and KiLLER.\012\012   "What  can  go  wrong  if I use a dirstyler?" you might wonder.  Well,\012   there  is  one thing that can go wrong; file-tagging.  ConfScan uses a\012   algorithm  to  recognize  filenames in the dir-file.  But if you use a\012   dirstyler  that  puts text where normally filenames are, ConfScan will\012   see that text as a filename.\012\012   If  you  still want to use that dirstyler, you can turn of the tagging\012   with the Config program (see @{"Configuration" link Configuration}).\012@EndNode\012\012@Node Installation "How to get it working - /X-PoWeR! - Written by KiLLrAvEn/MYSTiC"\012                    - - - ­ ­ ­ [ iNSTALLATiON ] ­ ­ ­ - - -\012\012   To install ConfScan, simply double-click on the install-ConfScan icon.\012\012   Installation  will  proceed  with  the  C=  installer.   Help has been\012   provided  in  the  installer  program,  so  no  need  to  repeat  that\012   information in here.\012\012   What can you do with the installer? The installer script will:\012\012   · Allow  you  to  install  the  ConfScan  main  executable  (ConfScan\012     itself).  You can choose either for the 68000 or 680x0 version.\012\012   · Allow you to install the ConfScan_DL Download door that  is  needed\012     for Ami-Express to recognize any flagged/tagged  files.   This  one\012     comes in just one flavour, 68000.\012\012   · Allow you to install the ConfScan_G door which checks if users have\012     flagged  files  still  not  downloaded  before they logoff (a small\012     patch for the original ''G'' door, nothing special).\012\012   · Allow  you to install the help files that come with ConfScan.  Such\012     files are needed to give help to users that use ConfScan.  They can\012     get  access  to  these  files  by putting a question mark after the\012     command (ie.  `N ?'').\012\012   · Allow  you to install the fully GUi Configuration program (Config).\012     This  program  will  allow  you  to  mold ConfScan to your personal\012     needs.   Here you can set all pre-defined preferences, such as ANSi\012     support,  show  new  dates  etc.   etc.  But this is also the place\012     where  you  can  set  download restrictions and exclude conferences\012     from being scanned.  And much more!\012\012   · Allow you to install this guide. You are reading it now.\012\012   · Let  you  choose  as  which  command  you  can to install ConfScan.\012     ConfScan  can  act like 3 different commands, `N'', `F'' and `CS''.  I\012     suggest  you install it as all 3 functions, but if you want you can\012     skip the `CS'' door ''cause it is built-in in `N'' also.\012\012   · Let  you  select the place where you want to install ConfScan.  The\012     default  destination  is  "DOORS:" but you are free to put it where\012     you  want  (the  destination  will  be  put  in  the  command icons\012     afterwards).   Remember,  a directory `ConfScan'' will be created in\012     that directory!\012\012   · Let  you  select  the  name  of  the  command  that the ConfScan_DL\012     download  door will be installed under.  I strongly suggest you put\012     it under the ''D'' cause otherwise users will not be able to download\012     anything ;)\012\012   · Let  you select the place where you want to install the Ami-Express\012     commands.\012     (Default: BBS:Commands/BBSCmd/).\012\012   · Let you set the minimum level required to use any of the ConfScan\012     related commands.\012     (Default: 20).\012\012   · Let  you  set the priority ConfScan will get when executed (only if\012     you  are  an  expert user).  If you are running a multinode system,\012     please  set  it  to 0, otherwise users on the other nodes will have\012     hindrance  from  it  if  you  give  it +1.  Systems with 1 node can\012     easily set it to +1 or +5 for maximum performance.\012     (Default: 0).\012\012   · Ask for the directory where you keep your ACP.info.  This is needed\012     for the Config program.\012\012   · Start the Config program for you so you can configure ConfScan.\012\012   All  commands will get a stack of 50,000 and will be set to multinode.\012   As ConfScan is written in C and ASM, it will be installed as a XiM.\012   \012   If  you want ConfScan installed under another name than `CS'', you will\012   have  to  do  it by hand.  But you can still use the installer.  After\012   installation,  simply rename the CS.info icon in your BBS:Commands/...\012   directory  to  whatever  you  want  (for example, `SCAN'').  This will,\012   however,  force  you  to rename some of the help files as well (rename\012   every file that has ".CS." in it to ".SCAN.").\012@EndNode\012\012@Node Configuration "Config - For easy configuration - KiLLraVeN/MYSTiC"\012                  - - - ­ ­ ­ [ CONFiGURATiON ] ­ ­ ­ - - -\012\012   ConfScan  comes  with an external configuration program called Config.\012   It  is  fully  GUi  so  no more stupid textfiles to create or icons to\012   fill.   Just  start  the  program  and  away  you  are.  Here are some\012   guidelines where you can find some stuff and what it all means.\012\012\012              ^-[ ACCESS LEVELS ]-^\012\012   Hold Access       ­ Every user with an access level equal to or higher\012                       than  the  value  you enter here, is able to watch\012                       the contents of the hold dirs.\012                       (Default:  250).\012\012   View Access       ­ Every  user with an access level >= than the value\012                       you  enter  here,  is  able to view files that are\012                       shown  in  the  dir  file.   You can specify which\012                       filetypes   are  supported  via  the  View  prefs.\012                       (Default:  20).\012\012   KiLL Access       ­ Every  user with an access level >= than the value\012                       you  enter  here,  is  able  to  flag/tag files as\012                       KiLLER  targets.  This is for usage with the nuker\012                       @{"''KiLLER''" link KiLLER}.\012                       (Default:  250).\012\012                ^-[ iNTRO FiLE ]-^\012\012   Intro file        ­ The  filename that you can specify here (either by\012                       entering the filename in the text box or selecting\012                       it  with ''S'') will be the name of the file that is\012                       shown at every startup of ConfScan.  At the moment\012                       you  can enter no variables (such as time/date and\012                       place).\012                       (Default:  <none>).\012\012         ^-[ DEFAULT USER PREFERENCES ]-^\012\012   These are the values that are used if an user does not have his or her\012   own private configuration for ConfScan.\012\012   ANSi Colours      ­ This  option  turns the colours on or off when the\012                       files  are  showed  in your screen.  You can setup\012                       those colours via the `Colours'' button.\012                       (Default: Off)\012\012   Show Sent-by      ­ By  default,  ConfScan  will  filter  out any file\012                       description  lines  that  start  with  ''Sent by:''.\012                       They  are  usually not interesting for users.  But\012                       with  the  latest File_iD''s and SentBy''s you don''t\012                       know what to expect anymore.\012                       (Default: Off)\012\012   Show New Dates    ­ Every time a new date is detected, a little banner\012                       will be displayed informing you of the new date.\012                       (Default: Off)\012\012   Clear Screen      ­ After  *every*  prompt, the screen will be cleared\012                       if  you  turn  this option on.  This speeds up the\012                       display  on  screen  quite  a  bit, esspecially on\012                       local nodes, try it.\012                       (Default: Off)\012\012   Lines b/files     ­ Some  users  find  it  usefull  to have a line put\012                       between all the files.  This does the trick.\012                       (Default: Off)\012\012   Pause b/confs     ­ This   will   put  a  pause  banner  between  each\012                       conference that has got new files.\012                       (Default: Off)\012\012   Return b/files    ­ Some  users  find it usefull to have an empty line\012                       between  all  the  files.  If you''ve got the time,\012                       use  it,  it  makes  it  easier  to detect all the\012                       different files.\012                       (Default: Off)\012\012   One line per file ­ If  you  turn  this on, just the first line of the\012                       file description will be shown.  Very handy if you\012                       want to tag a lot of files FAST.\012                       (Default: Off)\012\012   Always full desc. ­ This   will   prevent   file  descriptions  to  be\012                       displayed broken on your screen.  Turn this on and\012                       from  *every*  file you will always get to see the\012                       entire   file   description.   This  mode  can  be\012                       overridden with the [P] at the flag-prompt.\012                       (Default: Off)\012\012   Future expansion  ­ Guess what? Not used.\012\012               ^-[ SYSOP PREFS ]-^\012\012   This  is  where you set all the internal preferences ConfScan will use\012   while operating.  It more or less controls the engine of ConfScan.\012\012   Copy dirfiles     ­ With  multiple node systems, this is a must!  This\012                       will   first  copy  your  dirfile  to  T:   before\012                       searching   it  for  a  file  date.   This  allows\012                       multinode support.\012                       (Default: Off)\012\012   Callerslog        ­ Every  time ConfScan is started and this option is\012                       activated,  it  will  be logged in the callerslog.\012                       (Default: Off)\012\012   Use Percentage    ­ A  nice feature of ConfScan is, that it is capable\012                       of  showing  a  percentage  (%)  on  screen  while\012                       searching  the  dirfiles.  If you don''t want this,\012                       turn this option off.\012                       (Default: On)\012\012   Nuker Support     ­ ConfScan  is  also able to recognize comments made\012                       with   nukers.   Currently  supported  nukers  are\012                       BossNuke  and  KiLLER.   But any comment placed on\012                       the  spot where normally the file-size is, will be\012                       seen  as  a nuker comment.  Any nuker comment will\012                       be  display  with a dark-blue background and white\012                       characters.   If  you  don''t  want that to happen,\012                       turn this off.\012                       (Default: On)\012\012   Allow Tagging     ­ @{"Tagging" link Tagging}  is  a  thing  of the day, ConfScan had it\012                       first!   If,  for some reason, you don''t want your\012                       users to tag files, turn it off.\012\012                       Another  reason  why  you want to turn this option\012                       OFF  is  because you use a @{"dirstyler" link CleanDir} that confuses\012                       ConfScan in it''s file-recognition algorithm.\012                       (Default: On)\012\012           ^-[ iGNORED CONFERENCES ]-^\012\012   Any  conference you put in this listview will NOT be seen by ConfScan.\012   That  means  that  it will not scan the conference for new files (CS),\012   not will it be shown when the users wants to set his/her config.\012\012   You  can  add  a conference with "Add Conf", a list will appear of all\012   your conference and simply click on the one you want to add.\012\012   To remove a conference, select the one you want to remove and click on\012   "Del Conf".  Izze simple.\012\012                 ^-[ COLOURS ]-^\012\012   If  you  click  on  the [Colours] button, you will get a new window in\012   which you can enter the colours for the file listing.\012\012   The  values  you  can enter are ANSi ESC colour codes, here is a brief\012   display of all colours:\012\012             BLACK = 30 - RED    = 31 - GREEN = 32 - YELLOW = 33\012             DBLUE = 34 - PURPLE = 35 - LBLUE = 36 - WHiTE  = 0\012\012   Filename          ­ Colour of the filenames.\012                       (Default: 36)\012\012   Status            ­ Colour of the file status (P = Passed, etc.).\012                       (Default: 35)\012\012   File Size         ­ Size of the file (no, really?).\012                       (Default: 33)\012\012   File Date         ­ Date of the file (no kidding?).\012                       (Default: 31)\012\012   Description       ­ Colour that will be used for the file description.\012                       Mind  you  that  this ESC sequence will be sent at\012                       the  start  of  the  file description.  That means\012                       that  if  there is an ANSi colour code in the file\012                       description, the remainder of the file description\012                       will  be  in  THAT  colour  code  and not that you\012                       specify here.\012                       (Default: 0)\012\012                       NOTE:   Although ESC[37m is also the ANSi code for\012                       white,  Ami-Express fails to handle this correctly\012                       cause  the  local  node  will show RED (while your\012                       users  will  actually  have  white).  But by using\012                       ESC[0m you can circumvent this problem.\012\012                ^-[ ViEW PREFS ]-^\012\012   This  is  where  you  can specify which filetypes are allowed to view.\012   Currently supported filetypes are:\012\012   DMS               ­ Files  that  have  DMS  as  a file extension.  The\012                       action  that  is  performed on these files is "DMS\012                       ViEW <filename>".\012                       (Default: On)\012\012   LHA               ­ These  are  files  that  have  LHA  or  LZH  as an\012                       extension.   The action performed on such files is\012                       "LHA V <filename>".\012                       (Default: On)\012\012   Text files        ­ A whole range of extensions go for this file type:\012                       NFO,  NF0,  TXT,  DOC  and  ASC.   These files are\012                       simply  shown  to  them.   This  might  be the ONE\012                       filetype  you  want  to  turn  off  since the show\012                       routine will NOT abort display when it sees binary\012                       codes.\012                       (Default: On)\012\012   ZiP files         ­ Files with the extension ZiP will be attacked with\012                       an "ZiP -v <filename>" command and the result will\012                       be shown on screen.\012                       (Default: On)\012\012                 ^-[ SAVE iT! ]-^\012\012   To  save  all your settings, simply click on the [Save & Exit] button.\012   To quit without saving, close the window.\012\012      ^-[ WHAT ABOUT THAT OTHER BUTTON? ]-^\012\012   That  button  [ConfScan_DL]  lets  you setup some restrictions for the\012   download command.  See the @{"ConfScan_DL guide" link ConfScan_DL} for that!\012@EndNode\012\012@Node Features "Features of ConfScan - /X-PoWeR! - Written by KiLLrAvEn/MYSTiC"\012                      - - - ­ ­ ­ [ FEATURES ] ­ ­ ­ - - -\012\012 · GUi  Config  program that can be started from the CLi or Workbench for\012   easy configuration of ConfScan, a first for an /X-Tool!\012\012 · FAST searching with LOW memory consumption! Max. 60Kb per node!\012\012 · ConfScan  can  act  like `N'', `F'' and it''s own `CS''.  So you get three\012   programs for the download of one!  8-)\012\012 · ConfScan  can  show  you the full file descriptions always, so no more\012   broken file descriptions on your screen.  Fully user configurable.\012\012 · One  of the main features of ConfScan is ofcourse the fact that it can\012   scan  multiple  conferences in one time, this is unique!  No other dir\012   scanner is able to do that but ConfScan.\012\012 · Another  feature  is  the  file  @{"tagging" link Tagging}.  Although other dir scanners\012   provide  this  options  also,  ConfScan was the first to use it and it\012   kind of revolutionized the way of tagging/flagging files.\012\012 · Users  can  setup  ConfScan  to  their  own  personal  likings  via  a\012   preferences  menu they can call up with the ''W'' argument.  But this is\012   not  so special anymore.  Maybe the fact that it looks good and has no\012   overabundance  of  colours  in  it make it better than the other ones.\012   Also,  ConfScan recognizes conferences without a filebase and will not\012   even show them to users in the config menu.\012\012 · This is what the users can setup for theirselves:\012   ­ ANSi colour display\012   ­ Line between files\012   ­ Return between files\012   ­ Pause between conferences\012   ­ Show new dates\012   ­ Show sent-by (or not)\012   ­ Always show full descriptions\012   ­ Clear Screen after every prompt\012   ­ Show just the 1st line of a description\012\012 · Like I said above, ConfScan recognizes conferences without a filebase.\012   This is done to support Ami-X Net conferences (they usually don''t have\012   them). You don''t have to specify them, ConfScan is ''smart''.\012\012 · Scanning options; ConfScan has them, here you go:\012\012   ­ Scanning from a certain date\012   ­ Scanning from a number of days back\012   ­ Scanning from the day a user was last on\012   ­ Scanning from [t]oday\012   ­ Scanning in current conference or all conferences\012   ­ Scanning in upload dirs, all dirs or specified dir\012   ­ Scanning in hold dirs (special access-level required)\012   ­ Scanning in selected conferences (user configurable)\012   ­ Scanning with a byte- & filereport afterwards for users with\012     [H]old access (f.e. cosysops).\012   ­ Scanning non-stop\012\012 · Flagging  from  ALL  conferences is possible, ConfScan will keep track\012   itself  of all the files flagged and via the Download door, /X will be\012   informed about them (i.o.w.  they will be flagged).\012\012 · The  special  download  door  does  more  then just flag files for the\012   users.  It can automatically join the next conference where files were\012   flagged  by  the user.  This can be done straight away when they start\012   the download command in a conference where they have selected no files\012   or right after the downloading of files of that conference.\012\012   NOTE!       In  the near future, ConfScan will be able to send all the\012   ~~~~~       files  to  the  users  in  ONE  time.  This saves time and\012               trouble  for your users as well as for your board, it will\012               be  less  busy. \012\012 · With  @{"KiLLER" link KiLLER} installed, you can nuke files from within ConfScan.  Most\012   likely  you  will find a beta version of KiLLER inside and you will be\012   able  to  test it.  As soon as I''ve finished coding it, I will release\012   it  and  make  sure  you  can  still keep using it in cooperation with\012   ConfScan as well as a stand-alone program.\012\012   ALSO READ THE @{" HiSTORY " link History} iN THiS GUiDE FOR MORE iNFO ABOUT THESE\012   FEATURES!\012\012@EndNode\012\012@Node Usage "Usage by users (that includes you) - /X-PoWeR! - Written by KiLLrAvEn/MYSTiC"\012                       - - - ­ ­ ­ [ USAGE ] ­ ­ ­ - - -\012\012   ConfScan  is  very  easy  to  use, despite of it''s army of options ;-)\012   ConfScan comes with a set of very clear help files that your users can\012   call  in for help with ''<command> ?''.  This goes for ''N'', ''F'', ''G'' and\012   ''CS''.   Here are they in plain ASCII.  Feel free to change them if you\012   want  to.   To  get  a  full  view  of all recognized command, see the\012   @{"ALL COMMAND LIST" link SysopCommands}.\012\012   All the help is put into separate files for your convenience.  This is\012   done  to  support  multiple screentypes (so you can have separate help\012   files  for  every  screentype  (=  language)).  They are called:\012\012                      N  - Command   : ConfScan.N.Help.TXT\012                      F  - Command   : ConfScan.F.Help.TXT\012                      G  - Command   : ConfScan.G.Help.TXT\012                      CS - Command   : ConfScan.CS.Help.TXT\012\012                       In that order, their contents are:\012\012                         ^-^-^-^-[ B R E A K ]-^-^-^-^\012\012                              ConfScan User Help \012 \012  N -x     Files from x days back        Extra options:\012  N <date> Files from <date> and on      ­­­­­­­­­­­­­­\012  N S U    Files since last logon        · Add ''NS'' for non stop display\012  N T U    Files since today             · Use CTRL-C to break program\012  N S G    Files since last logon        · Enter ''N W'' for to edit your own\012           from all conf''s (Global)        personal environment settings.\012 \012                              Environment Options\012 \012  · Select global conferences            · Put lines between files on screen\012  · Usage of ANSI colours in list        · Put return between files on screen\012  · Leave out sent-by''s                  · Pause between conferences (only used\012  · Display new date banner                when you scan globally)\012  · Clear the screen after prompt        · Display only first line of descr.\012 \012  · Show Full Descriptions is an option that will make sure you will always\012    get to see the full description of a file, and never will the description\012    of a file be broken on your screen. It is not the opposite of ''one line''!\012\012                          ^-^-^-^-[ B R E A K ]-^-^-^-^\012\012                               ConfScan User Help\012 \012  F        Pop up ''f'' menu               Extra options:\012  F <#>    Files from dir <#>            ­­­­­­­­­­­­­­\012  F U      Files from upload dir         · Add ''NS'' for non stop display\012  F A      Files from all dirs           · Use CTRL-C to break program\012  F H      Files from hold dir           · Enter ''F W'' for to edit your own\012           (access required)               personal environment settings.\012 \012                              Environment Options\012 \012  · Select global conferences            · Put lines between files on screen\012  · Usage of ANSI colours in list        · Put return between files on screen\012  · Leave out sent-by''s                  · Pause between conferences (only used\012  · Display new date banner                when you scan globally)\012  · Clear the screen after prompt        · Display only first line of descr.\012 \012  · Show Full Descriptions is an option that will make sure you will always\012    get to see the full description of a file, and never will the description\012    of a file be broken on your screen. It is not the opposite of ''one line''!\012\012                          ^-^-^-^-[ B R E A K ]-^-^-^-^\012\012                               ConfScan User Help\012 \012  CS -x     Files from x days back       Extra options:\012  CS <date> Files from <date> and on     ­­­­­­­­­­­­­­\012  CS A      Files from all dirs          · Add ''NS'' for non stop display\012  CS T      Files since today            · Use CTRL-C to break program\012  CS <#>    Files from dir <#>           · Enter ''CS W'' for to edit your own\012                                           personal environment settings.\012  CS scans globally for new files in     · Add ''+'' for a byte-report\012  the upload dir since last logon          (access required)\012  unless specified different (above).\012 \012                              Environment Options\012 \012  · Select global conferences            · Put lines between files on screen\012  · Usage of ANSI colours in list        · Put return between files on screen\012  · Leave out sent-by''s                  · Pause between conferences (only used\012  · Display new date banner                when you scan globally)\012  · Clear the screen after prompt        · Display only first line of descr.\012 \012  · Show Full Descriptions is an option that will make sure you will always\012    get to see the full description of a file, and never will the description\012    of a file be broken on your screen. It is not the opposite of ''one line''!\012\012                          ^-^-^-^-[ B R E A K ]-^-^-^-^\012\012                          ConfScan Goodbye Explanation\012 \012   Theory  Your sysop has installed ConfScan for scanning the dirfiles,\012           and ConfScan stores your flagged files in a different matter\012           then Ami-Express does (because ConfScan can remember flagged\012           files from multiple conferences and /X can''t). This also asks\012           for a different ''G'' command, this is it!\012 \012           This new commands does the same as the internal one, with a\012           few differences:\012 \012           ^ Ability to start downloading from ''G''\012           ^ Ability to view your remaining flagged files\012           ^ Ability to remove your remaining flagged files\012 \012 Practice  Once notified that you have remaining files, your options are:\012 \012           [G] ^ Goodbye, let me out!             To force ConfScan_G to\012           [L] ^ List the remaining files         just log off, enter a\012           [D] ^ Download remaining files         ''!'' after the G (''G !'').\012           [R] ^ Remove them & log off\012           [Q] ^ Quit, back to /X prompt          (c) ''94 KiLLraVeN/MYSTiC\012\012                          ^-^-^-^-[ B R E A K ]-^-^-^-^\012\012   SEE ALSO: @{"More options" link More}\012\012@EndNode\012\012@Node Future "Possible Future improvements - /X-PoWeR! - KiLLrAvEn/MYSTiC"\012                - - - ­ ­ ­ [ FUTURE iMPROVEMENTS ] ­ ­ ­ - - -\012\012 · Downloading  ALL  files  from  ALL  conferences  in ONE time.  This is\012   possible now thanks to the help of Joe Hodge (thanks Joe!).  Make sure\012   you  are  a  registered  sysop,  or  else you want be able to run that\012   version of ConfScan!  It will require /X 3.38+.\012\012 · Improved  file  tagging,  it can be annoying sometimes that you cannot\012   reach a file that is still on screen.  I will have to look into that.\012\012 · ''A'' command to alter/remove flagged files (multiple conferences ofcoz).\012\012 · ''Z''  command  to  search  in  multiple  conferences  and with ConfScan\012   interface.\012\012   Anyway,  if  you  have  suggestions,  make  sure  to  drop me a line at\012   Channel-X or at one of the other MYSTiC boards (in Holland preferably,\012   that''s where  I  am most).  By the way, you don''t need to have a\012   suggestion to call  the MYSTiC boards, you''re welcome at any time, open\012   24 hours a day and at your service!\012\012   Let me know what you think and what YOU think needs improvement!\012\012                            __                       /\\012    :        _ __  __Stz___|  \________/\___________/_ \______/\ _       ·\012   _¦_______ //  \/  \_/   |  \\_  ____  \           /__/      \\\ ______:_\012    |        //       \___ 