INSERT INTO door_catalog VALUES('ctx_ts3','CTX-TS3.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CTX-TS3.LHA','TurboScan','XIM','TurboScan',NULL,NULL,'CTX','.------ (__.(__) (  l_ (_/_ /\ ------. `-----------( brings you )-----------'' TuRbO ScAn v0.3 - ASM UTIL',replace('    ·19·   __  __   _ :_  __  .)  ·95·  \n  .------ (__.(__) (  l_ (_/_ /\ ------.\n  `-----------( brings you )-----------''\n        TuRbO ScAn v0.3 - ASM UTIL      \n    (Scan disks for empty tracks and    \n print it out. Only for df0-df4 drives! \n Usefull for all (cr) dudes in da scene)\n','\n',char(10)),'TurboScan.GUIDE',replace('@DATABASE\n@Remark $VER: vERSiON 0.3 [RELEASE 1] (Feb 05 1995 14:12:43)\n@Remark AmigaGuide DataBase for TurboScan v0.3\n\n@Node MAIN "TurboScan v0.3 - Cli util"\n\n                    ·19·   __  __   _ :_  __  .)  ·95·\n                  .------ (__.(__) (  l_ (_/_ /\ ------.\n                  `-----------( brings you )-----------''\n\n                             TurboScan  v0.3\n\n                 @{"      ·*·    iNtRoDUCtiON!   ·*·      " LINK Introduction}\n                 @{"      ·*· tROUBlE-shOOtiNGs! ·*·      " LINK Troubles}\n                 @{"      ·*·  oTER dOORs/tOOlS! ·*·      " LINK Other}\n                 @{"      ·*·     GREETiNGS!     ·*·      " LINK Greetings}\n@ENDNODE\n@NODE Introduction "iNtRoDUCtiON"\n\n                           . [ iNtRoDUCtiON: ] .\n                            - --------------- -\n\nTuboScan v0.3 is a small util to scan drives for empty sectors!!\nUsefull for all guys who wanna put there intro or trainer for games\nand dont know the free sectors on the disk!!\n\nTurboscan will print all free sectors and recognize if a disk\nhave an  R/W ERROR!!!\n\nORIGINAL LENGTH OF TURBO SCAN v0.3: 1956 bytes\n\nhave Phun!!\n\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Troubles "TROUBLE-SHOOTiNGs"\n\n                            . TROUBLE-SHOOTiNG .\n                             - -------------- -\n                                    call\n\n              28.8k!   ________    /\__ /\______/\__ _____   28.8k!\n          t            \_     ¬\  /   ¬\)      ¬\   |   ¬/\n          R   __/\__    :   :   \/  Y   \   :   /   :   /    __/\__   a\n          S   \    //   |   |    \  :    \  |  (:      (    \\    /   H\n          i   /_  _\\   |   l    /__|    /  |   \   :   \   //_  _\   q\n         INC.   \/     /:  _____/   l___/___l___/___j    \     \/     !\n                       \__/                         l____/\n          /\__ _/\__   _/\__     _      /\______/\__   _/\ _______      \n          )  ¬|\_  ¬|  \_  ¬|   /¬| |\ /   __  ¬)  ¬| /   \\_    ¬\\n          |   | |   |__ |   |__/  ( ) \___   \_/:   |/  :  \|  -+  \\n          :   | |   | ¬\|   | ¬\   |   \ ¬\    \|   |   |   \   :   \\n          |   | :   l   \   l   \  l    \  \    \   :   l    \  |    \\n          |   | l_______/_______/_______/_______/___l________/__j    /\n          l___j                  tRSi iNC. aHQ            [ctx!]l___/\n\n               (  ( ((  + 4 3 -  5 1 2  -  3 6 5 - 3 0 2  )) )  )\n\n            SysOp: CøRteX/tRSi         Co´s: DjaX, Ayatollha, D`Style\n          .----------------------------------------------------------.\n          | rUNNiNg oN a1200/33Mhz^-^720MB oNLINe StuFF^-^kEwL aNSIs |\n          |       [^Now with S!X-pReSs 0.X!^-^28.8k pOwER!!!^]       |\n          |        [^aMiGa^-^mUzAx^-^/X DooRs^-^aSm SoUrCeS^]        |\n          `----------------------------------------------------------''\n                             [·nO nUp rEqUiReD!·]\n\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Other "OTHER dOORs/TOOLS"\n\n                          . OTHER dOORs/TOOLS .\n                           - --------------- -\n\n                    XiM     Security Guide       v0.4\n                    XiM     Show Doors           v0.4\n                    XiM     ctx!CoMMeNt          v0.2\n                    XIM     Upload Detector      v0.5\n                    XIM     Front Guard          v1.0\n                    XIM     Turbo Lister         v0.1\n                    CLI     Offline Mover        v0.2\n\n\nIF YOU LIKE MY DOORS/UTILS AND WANT BE @{" REGISTERED " LINK Register} USER OF IT\nCALL MY BBS: Dark Illusion ++43-512-365-302!! no NUP! no SYSPASS!\n\nIVE SEARCHING ALSO FOR A ELITE GROUP TO JOIN. IF YA LIKE MY DOORS/UTILS CALL MY\nBBS TOO! WE CAN NEGOTIATE ABOUT TO JOIN!! :))\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Greetings "GREETINGS"\n\n                          . SOME FAST GREETINGS .\n                           - ----------------- -\n                                  · TO ·\n\n  [*] CONTROL,MARIO,UYANIK,SIEGEL,BYTEANDI,DR.DRE,SPY,KNACKOSOFT/TRSI [*]\n   [*] INSPECTOR,AYATOLLHA,ICE TEA/CLS [*] FELON/PDY [*] CALYPSO/GOD [*]\n      [*] SAL-1, SHADE, TSM, SPEEDWOLF/TRSI [*] SAUZER,PRAYER/R^D [*]\n    [*] PEEWEE [*] TEKKNO [*] D`STYLE [*] STEVE/D&R [*] METAL DEATH [*]\n       [*] PINKY FACE, PSYCHO, DREAM WARRIOR, SAITO, CAPSLOCKMAN [*]\n                      ... and all ive forgotten ...\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',5480,1,0,NULL,NULL,'ctx_ts3','scan',1780048460);
