INSERT INTO door_catalog VALUES('cy8ercv1','CY8ERCV1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CY8ERCV1.LHA','COMMENT','XIM','COMMENT',NULL,NULL,NULL,'(c)''95!   (   \  /  _ \ _|    / /X DOORS .--------- \___| _|  ___/___|_|_\.---------. |              p.r.e.s.e.n.t.s             |',replace('             __\ \  / _ ) __| _ \\n  (c)''95!   (   \  /  _ \ _|    / /X DOORS\n.--------- \___| _|  ___/___|_|_\.---------.\n|              p.r.e.s.e.n.t.s             |\n|  You with yet another pissed up attempt  |\n|   at compiling cool Ami-Express do0rs!   |\n|             cY8ER-COMMENT v1             |\n| Cool "c" replacement with lotsa features |\n| Cursor Handling - Tooltype Configurable! |\n| You can even design your own header too! |\n!                                          |\n`-------------------------------------[c]--''\n','\n',char(10)),'COMMENT.GUIDE',replace('INSERT INTO door_catalog VALUES('cy8erdwn','CY8ERDWN.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CY8ERDWN.LHA',NULL,'XIM','.------------------------------------------.',NULL,NULL,NULL,'|  DOWNLOAD INF0 v1.O (c) cYBER/iNDY 1995  | |                                          | |  Shows User Download Stats + Much more!  |',replace('.------------------------------------------.\n|  DOWNLOAD INF0 v1.O (c) cYBER/iNDY 1995  |\n|                                          |\n|  Shows User Download Stats + Much more!  |\n| Totally configurable to meet MOST needs! |\n|           /X Door for /X v2.x+           |\n!                                          !\n`---------[ LEECH/SUCK/SNAKE NOW ]---------''\n','\n',char(10)),'cY8ERDOWN.guide',replace('INSERT INTO door_catalog VALUES('cy8ereal','CY8EREAL.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CY8EREAL.LHA','o6oS_BURNING','XIM','eXeCuTeMe!',NULL,NULL,NULL,'|   .___|    Y  |  _ ___|  __   / |   _ __/ |   |   l____   |  _    |  \___/__|   _   \_ l_______l_______l_______l_________l___|____/',replace('._______.____ __._______.________ .________\n|   .___|    Y  |  _ ___|  __   / |   _ __/\n|   |   l____   |  _    |  \___/__|   _   \_\nl_______l_______l_______l_________l___|____/\n . funky little /X monster returns again! |\n :                                        |\n | Diz time he''s puked up cY8ER-EALL v1.0 |\n | A sexy "eall message" door for /Xv3.x+ |\n | Control user''s who "abuse" their "eall |\n | axis" and make the bugger''s pay for it :\n | This door''s also TopSecret compatible! .\n `-----------------------------[tGo/wL!]--''\n','\n',char(10)),'cY8ER-EALL.GUIDE',replace('[sof]\n \n                  BLOIK! HERE''S A QUICK cYBER 88S PLUG...\n                                                              \n           - --{ WHERE iNSANiTY iS CONSiDERED AN ART FORM }-- -\n                          .\n                          .                     .........    .\n    .___________  _______ :__.___.      __.___.:::  | /:::.  |__  _______\n    |  \_____  / /       \/  |   |     /  |   |:::  |/ :::|  |  \/  _ ___\n    |   \_(__  \ \_|   |_/   _   |    /   _   |:::  ·  :::|  |   \  _   /\n    |___/______/   |___| \___|   |    \___|   |:::     :::|______/__|   \_\n                      tGø/wL!`---''        `---''`::.....::''          :____/\n                          :\n                          `-----------------------------.\n              NERVE AXiS & WHALE! UKHQ - TASTE THE EXPER¦ENCE\n                                                        !\n               .----- AQUARiUS UFO DiSTRiBUTiON SiTE ---''\n               |\n POSSiBLY THE B!GGEST /X DOOR - MODULES - ASCii COLLECTiONS CONFS iN THE UK\n               :\n               `-------.\n         - --{ 2 NODE R¦NGDOWN 28.8K & 16.8K - 2 GiGS ONLiNE }-- -\n                       :\n       - --{ SEXiEST ARTWERK - COOLEST CONFS - CRAZiEST SYSOPS }-- -\n                       :\n               ÷ O · 1 · 7 · O · 4     5 · O · 5 · 8 · 4 · 5 ÷\n\n \n\n                    Righto... On with the nitty gritty...\n\n \n\n\n\n                   You''ve just stepped into cYBER''s World:\n                   it''s a social pyschotic state of bliss!\n                    You''ve been delayed in the real world \n                    how many times have you hit & missed?\n\n                .---------------------------------------------.\n                | cY8ER-EALL v1.O Copyright © cYBER/iNDY 1995 |\n                `---------------------------------------------''\n                   \n                     >>> cY8ER-EALL v1.O DoCUMENTATION <<<\n\n\n                                  COPYRIGHT\n                                  ---------\n                 Permission is granted to freely distribute  \n               this product for non-commercial purposes only,\n                  as long as all files remain unmodified.\n\n\n\n\n\n\nARCHIVE (cY8EREAL.LHA) CONTENTS:\n--------------------------------\n   Filename:           Description:                                   \n\n   xxx?Ring?me?LAME    Lame 88S adds that add tons of bytes to small files\n                       \n\n\nDOORS:cY8EREALL/\n\n   cY8ER-EALL.GUIDE    The Docs Dumbo\n   cY8ER-EALL.REXX     The Actual Arexx /X Door\n   cY8ER-EALL-VN.REXX  The same /X door, but for use in conjunction with \n                       )/ideo /\/asty''s "TopSecret" /X Mail door\n   cY8ER-EALL.CFG      The Door''s config file\n   cY8ER-EALL.HEADER   A header txt for the door\n   ARC.LHA             This /X util in archive form, just incase some twats\n                       lame stripper strips any of the txt''s for this util.\n\n\nBBS:Commands/BBSCmd/\n\n   EALL.info           Doh! obvious m8\n   VN-EALL.info        Use & rename this to ''EALL.info'' if you use Nasty''s\n                       TopSecret /X Mail Door\n   ENTER.info          Info icon, only for use with cY8ER-EALL-VN.REXX\n\n\n\n\nREQUIREMENTS:\n------------\n\nA mighty Miggy with lotsa ram and a great big juicy hardie, \nwhich is running at least a "legal version" of "/X v3.x +".\n\n\n\n\nWHAT THE SMEGGING HELL IS IT?:\n-----------------------------\n\nNowadayz...\n\nMost SysOp''s are very choosy about who has EALL access on their boards...\nWhy? because most people with such access tend to abuse it and post dozens\nof EALL msg''s (usually 88S plugs), which fill the msg base and tend to piss\nthe SysOp and the users off.\n\nThis is where cY8ER-EALL plays its part...\n\ncY8ER-EALL is an /X door which allows users (who do not have a high enough\naccess level to write an EALL Message) to buy an EALL with their credits.\n\n\n\n\nINSTALLATION:\n------------\n\n       FIRSTLY AN IMPORTANT NOTE... there are TWO versions of this door.\n\ncY8ER-EALL.REXX is the normal /X door\n\nBUT...\n\ncY8ER-EALL-VN.REXX is the same door, but for use if you SysOp''s run\n)/ideo /\/asty''s "TopSecret" /X Mail door.\n\nSysOp''s that run this door know that /\/asty''s door uses the ''e'' \ncommand, so it is necessary to use a dummy command...\n\nthis is where the ENTER.info comes in hehehe... confused? surely not doh!\n\n\n\n             OKi, FOR THOSE THAT DON''T USE /\/asty''s DOOR:\n             --------------------------------------------\n\n        Copy COMMANDS/BBScmd/EALL.info to the same Dir in your BBS\n\n        Copy the files ''cY8ER-EALL.REXX''\n                       ''cY8ER-EALL.CFG''\n                       ''cY8ER-EALL.HEADER'' to your doors dir\n\n\n\n                 FOR THOSE THAT DO USE /\/asty''s DOOR:\n                 ------------------------------------\n\n        Copy COMMANDS/BBScmd/VN-EALL.info to the same Dir in your BBS\n                        and rename it to ''eall.info\n \n        Copy COMMANDS/BBScmd/ENTER.info to the same Dir in your BBS\n\n            (The enter.info uses the /X internal ''e'' command)\n\n        Copy the files ''cY8ER-EALL-VN.REXX''\n                       ''cY8ER-EALL.CFG''\n                       ''cY8ER-EALL.HEADER'' to your doors dir\n\n                                 ----\n                     IS THAT CLEAR ENOUGH FOR YOU?\n \n\n\n\nHOW TO CONFIGURE THE ''cY8ER-EALL.CFG'' FILE:\n------------------------------------------\n\nThe config file is completely at your mercy...\nYou can be nice and only charge a few bytes for an eall msg, or you\ncan be a complete git and charge as much as you wanna...\n\n--------------------cut/snip/hack/paste/burp/---------------------\n\n1000000      <-= The amount of bytes an EALL msg Costs\n100          <-= Axis level which allows `normal'' eall msg''s \n\n--------------------cut/snip/hack/paste/burp/---------------------\n\nLine1 is how much you charge for an eall msg, in this case 1MB\nLine2 tell this door that anyone with access below this level will\n      have to pay for an eall.\n\n\n\nTHE ''cY8ER-EALL.HEADER'' FILE:\n----------------------------\n\nThis is just a text that is show as the door starts, I have included\na crap example, edit it your demented needs dude.\n\n\n\nGENERAL CRAP:\n------------\n\nIf a User with normal eall access tries to use this door, then he/she\nwill be told that they already have access and told to enter ''e eall''\nat the main menu.\n\nIf a user doesn''t have enough bytes, he/she will not be allowed to use\nthe door, and is told that he/she MUST upload something to buy an eall\n\nIf for some sad reason you don''t understand how to use this door then\nbasically\n\nWHERE O WHERE O WHERE O WHERE:\n------------------------------\n\n\n\nI CAN ALWAYS BE REACHED HERE........\n                                   ||\nOH NO... NOT AGAiN! ;)             \/     DON''T EVER GIVE ME EALL AXIS hehe!\n\n           - --{ WHERE iNSANiTY iS CONSiDERED AN ART FORM }-- -\n                          .\n                          .                     .........    .\n    .___________  _______ :__.___.      __.___.:::  | /:::.  |__  _______\n    |  \_____  / /       \/  |   |     /  |   |:::  |/ :::|  |  \/  _ ___\n    |   \_(__  \ \_|   |_/   _   |    /   _   |:::  ·  :::|  |   \  _   /\n    |___/______/   |___| \___|   |    \___|   |:::     :::|______/__|   \_\n                      tGø/wL!`---''        `---''`::.....::''          :____/\n                          :\n                          `-----------------------------.\n              NERVE AXiS & WHALE! UKHQ - TASTE THE EXPER¦ENCE\n                                                        !\n               .----- AQUARiUS UFO DiSTRiBUTiON SiTE ---''\n               |\n POSSiBLY THE B!GGEST /X DOOR - MODULES - ASCii COLLECTiONS CONFS iN THE UK\n               :\n               `-------.\n         - --{ 2 NODE R¦NGDOWN 28.8K & 16.8K - 2 GiGS ONLiNE }-- -\n                       :\n       - --{ SEXiEST ARTWERK - COOLEST CONFS - CRAZiEST SYSOPS }-- -\n                       :\n               ÷ O · 1 · 7 · O · 4     5 · O · 5 · 8 · 4 · 5 ÷\n\n\n\nAnd maybe, just maybe (if my fone bill ain''t too high) on these:\n\nDiGiTAL CANDy     +44(01)912-325-527 RINGDOWN (5 FUNKy NODES ^ MULTI-CD ROMS)\n\n                        _  _   _  _          _____      _            _       \nBeyond Reality      _  | || | | || |        |  __ \    (_)          | |      \nBurger Bar        _| |_| || |_| || |_ ______| |__) | __ ___   ____ _| |_ ___ \nCryogenics       |_   _|__   _|__   _|______|  ___/ ''__| \ \ / / _` | __/ _ \\nPhantasm           |_|    | |    | |        | |   | |  | |\ V / (_| | ||  __/\nSoap City                 |_|    |_|        |_|   |_|  |_| \_/ \__,_|\__\___|\n\n\n\n\n\nVERY WARM PiSSED GREETiNGS FLY ALL OVER:\n----------------------------------------\n\n Phaid............ GODAMNIT, I''VE LOST YOU VOICE NUMBER AGAIN T. :(\n Tango............ I''ll definately will see you at the next party Dave\n Ace & Venom...... Hope the hardie''s NOT giving you anymore trubs?\n Biggles.......... You are definately a Brownie Hound\n Rage............. /X Courier Deluxe - Love ya\n Cruise........... Bring Fantasia back Now dude\n Sasha............ Hope you survived fresher''s m8?\n Protocol......... Besides calling b.bar, what are you up to man?\n nes.............. what are you up to? where do you call now?\n sonic............ Need to talk to you, leave me mail\n Axen............. Allo m8\n Crash!........... I will fill in that NVX form one day, honest ;)\n                   But just to brown nose ya here''s a plug for NVX\n\n                   CALL THESE COOL NERVE AXiS BOARDS TODAY:\n\n                   TRiCK OR TREAT 2 WHQ  +44 (01)703-391797/495841\n                   POWERPLANT UKHQ       +44 (01)229-431590\n                   THE EDGE UKHQ         +44 (01)226-289303\n\n\n\nRESPECT GOES OUT TO THESE COOL U.K SYSOP''S \n------------------------------------------\n\n CHEM/LSD\n Rebel/QTX\n Ice-D/ATX\n Patriot/FLT\n Data-Stream/SR\n\n\n[eog]\n\nRight this is cYBER pissing off\n\n\n               .,:::::,._                       __     _\n   _          /¯__ __ ¯_ \__________  ___/¯¯¯¯¯¯¸ ¯¯¯¯T \   Alcohol Whore!\n  _\\________ \  x x  / ) \ )       ¯¯ )  _)----------''\ \       Doh!\n C-¯ _l___ __¯¯\_(.__/¯¯__/-'' \_______/  ¯ X¯¯)¬\       ¯¯\n  ¯¯¯          ¯ ¯  ¯¯¯__¯j_ /xCz     \  _/  /\  \  Lame Brain drunk again\n   Wibble Wibble!   C¯¯)____/          \    /  \__)  silly dumb-dumb cold\n                        ¯¯¯             (___/             plum insane!\n\n[eof]\n','\n',char(10)),NULL,'auto-added',43943,11,0,NULL,NULL,'cy8ereal','scan',1780048460);
