INSERT INTO door_catalog VALUES('cy8erx','CY8ERX.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CY8ERX.LHA',NULL,'XIM','.------------------------------------------.',NULL,'P0t-No0Dle',NULL,'| /X - GLOBAL DUPE DiRECTORY ''93 - Dec ''95 | | ======================================== | | This File is meant for use with the Dupe |',replace('.------------------------------------------.\n| /X - GLOBAL DUPE DiRECTORY ''93 - Dec ''95 |\n| ======================================== |\n| This File is meant for use with the Dupe |\n|  Checker Door by P0t-No0Dle of ANTHR0X!  |\n| SYSOPS! STOP DUPED/ANCiENT/VIRUS /X NOW! |\n|     *** No more wasted HD Space ***      |\n! /X     Courtesy of cYBER^LSD/NVX      /X !\n`------------------------------------------''\n     + 4 4 ( 0 ) 1 7 O 4  5 O 5 8 4 5\n','\n',char(10)),'GDD.GUiDE',replace('\n\n\n             I hate BBS adds, but this ones THE exception!\n\n\n     Yo bloody ho ... have a funky Christmas from the 13th Hour staff!\n\n                        ....     .........    .____.    .____:    .\n                     ..:::::   .:::::::::::.  |.   |__  |.  _|    |\n - --- --------- --- - :::::   :::::    ::::  |    __///| \\\_    |\n   NERVE AXiS UKHQ     :::::   ::::  :::::::  |    |____|    |    |\n - --- --------- --- - :::::            ::::  |:   |    |:   |    |\n AQUARiUS ^ TW¡STED!   :::::   ::::.   .::::  |::       |::  |    |\n  DiSTRiBUTiON SiTE ..:::::::..`:::::::::::''  |:::.     |:::.|    |\n - --- --------- --- -                     tGø`---------`----^----''-T!\n\n         + 4 · 4   (O) · 1 · 7 · O · 4       5 · O · 5 · 8 · 4 · 5\n\n.____:    ._________.____.____.__________\n|.  _|    |.        |.   |    |.  __ ___/ - --- -------------------- --- -\n| \\\_    |    |    |    |    | \\\_    |   ACE · VENOM · TANGo · BiGGLES\n|    |    |    |    |    |    |    |    |       · cYBER · CRASH ·\n|:   |    |:   |    |:   |    |:   |    | - --- -------------------- --- -\n|::  |    |::  |    |::  |    |::  |    | /X DOORS · AMiGA · MUSiC · SCi-Fi\n|:::.|    |:::.     |:::.     |:::.|    | GRAPHiCS · ASCii · /X UK REG SiTE\n`----^----`---------`---------`----''    | - --- -------------------- --- -\n\n\n[SOF]\n\n        ============== A PiSSED UP PERSONAL RELEASE ==============\n \n Righto... Happy Xmas ''95 and all that goes with it...\n \n Sorry, but I''m getting pissed off logging onto boards and having to\n sift throught /X & Miggy Dirs and deciding whether or not the l8test\n /X files are Ancient, viri or sadly... DUPED.\n \n There is NO blame on the cool traders in the U.K... Most bulk upload\n their latest warez to their beloved BBS''s and can''t check all the arcs\n that they pump... fair dues! Keep up the good work!\n\n Anyhowz, This Archive is intended to help some SysOp''s out in keeping\n DUPED/ANCIENT/VIRI infested /X warez off their systems.\n\n Quite a few BBS''s have /X dirs, but some don''t.  This Archive is really\n for these cool Boards that don''t have /X Dirs.  But if you do run an /X\n conf... hey feel free to use this... it might save you some precious HD\n space.\n\n Basically, the text file ''GLOBALDUPEDIR'' is a well shortened down list of\n virtually (feel free to add files Ace & MDR hehehic) most of the /X doors\n released from 93 to December 23rd 1995.\n\n       The ''GLOBALDUPEDIR'' contains a list of over 1000+ /X files\n\n     (This should give added protection against Dupes - I hope!?!)\n\n It should be used with Pot-Noodle of Anthrox''s DUPE CHECKER DOOR (Which I\n might add is one of the best f''ing doors ever!)\n \n Most sysops''s will know what to do with this archive, but to those that\n don''t... logon to a cool board that has an /X conf and leech potty''s door!\n and read the f''ing door dox doh!\n\n                     iF YOU''RE REALLY STUCK??? Doh!\n\n              Then you shouldn''t be running an /X BBS! hehehic\n \n                       Larterz, cYBER of |_SD/N\/X\n\n            Xmas spirits with warm pissed greetings fly all over...\n\n                     In no particular pissed up order... \n\n  Phaid, Arty, Dave wavy, Hermski, Hybrid, Nes, Chem, Axen, Fish, Crash!,\n  Protocol, Homer, Dan, Ice T, Pot-Noodle, Shaitan, Biggles, Linebacker!,\n  Cruise, Hotwire, Potsan, Daffy Duckie, Rage, Talon, Rebel, Data-Stream,\n  Venom, Sidesalad, Blind Man, Sasha, Patriot, Ben.E Wriggle and Gherkin!\n \n  Oh yup... Merry Xmas to all LSD and NXV Dudes... may ''96 bring you luck\n            and prosperity... have a good new year fellaz!\n\n[EOFCRAP heheheic]\n\n\nOops, a BBS PLug dagnamit...\n\n\n     Yo bloody ho ... have a funky Christmas from the 13th Hour staff!\n\n                        ....     .........    .____.    .____:    .\n                     ..:::::   .:::::::::::.  |.   |__  |.  _|    |\n - --- --------- --- - :::::   :::::    ::::  |    __///| \\\_    |\n   NERVE AXiS UKHQ     :::::   ::::  :::::::  |    |____|    |    |\n - --- --------- --- - :::::            ::::  |:   |    |:   |    |\n AQUARiUS ^ TW¡STED!   :::::   ::::.   .::::  |::       |::  |    |\n  DiSTRiBUTiON SiTE ..:::::::..`:::::::::::''  |:::.     |:::.|    |\n - --- --------- --- -                     tGø`---------`----^----''-T!\n\n         + 4 · 4   (O) · 1 · 7 · O · 4       5 · O · 5 · 8 · 4 · 5\n\n.____:    ._________.____.____.__________\n|.  _|    |.        |.   |    |.  __ ___/ - --- -------------------- --- -\n| \\\_    |    |    |    |    | \\\_    |   ACE · VENOM · TANGo · BiGGLES\n|    |    |    |    |    |    |    |    |       · cYBER · CRASH ·\n|:   |    |:   |    |:   |    |:   |    | - --- -------------------- --- -\n|::  |    |::  |    |::  |    |::  |    | /X DOORS · AMiGA · MUSiC · SCi-Fi\n|:::.|    |:::.     |:::.     |:::.|    | GRAPHiCS · ASCii · /X UK REG SiTE\n`----^----`---------`---------`----''    | - --- -------------------- --- -\n\n\n\n\n\n\n         FUCKING CALL THIS BBS, IT''S THE /X UK DISTRIBUTION SITE!\n\n\n\n\n','\n',char(10)),NULL,NULL,27149,1,0,NULL,NULL,NULL,'scan',1780048460);
