INSERT INTO door_catalog VALUES('cyber_rl','CYBER-RL.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/CYBER-RL.LHA',NULL,'XIM','___     |___  ___  __',NULL,NULL,'CYBER','(___(___||___)(__/_(   <-----[presents]----. .-------''----------------------------------'' |  A Simple ''RL'' Replacement Command for /X',replace(' ___     |___  ___  __\n(___(___||___)(__/_(   <-----[presents]----.\n.-------''----------------------------------''\n|  A Simple ''RL'' Replacement Command for /X\n!\n: For BBS''s that don''t want a Relogon Option\n\n. Simple,Quick,No Fuss,BD Free & a Pisstake\n`-------------------------------[tGo/WL!]-->\n','\n',char(10)),'cYBER-RL.DOC',replace('-{ SOF }-\n\n\n\n\n  ______________._______ _____._____________.___________________________\n (              |       Y     |      _ _____|      ______________ _____/\n /       )------|_______      |      _      |      __}__.       _      \_\n \____          |____         |____         |____       |_______|_______/\n     `----------''   `---------''   `---------''   `-------''tGø/wL!\n\n                           [ p R E S E N T s ]\n\n                     [ a N  i N D Y  r E L E A S e ]\n\n               [ d U E  t O  e X T R E M E  b O R D E m ]\n\n\n         -{ cYBER-RL v1.o © cYBER of nVX^uLT^tRB^lSD 04/07/96 }-\n\n\n             [ qUiCK, sLANTED, MisPelt, hACKED tOGETHER DOC ]\n\n \n          I don''t realy call this a release, just a PiSS TAKE\n\n\n                          -{ tHE iNTRODUCTiOn }-\n\n\n     This Arexx (I know, I know yuk yawn) Door is just simply an ''RL''\n     (Relogon) replacement for Boards that don''t want users to re-log\n\n     It just displays a Msg informing the users that they can''t do it\n\n     Obviously, MOST SysOp''s? will know that there''s no real point to\n     this door, as all they have to do is disable the cmd in the axis\n     configs of /X!!! But what the hell...\n\n     Oh, any1 that wants to change the msg, just deopt and edit it ;)\n\n\n\n                          -{ tHE iNSTALLATiOn }-\n\n\n                               Tis simple...\n\n                  Put the icon in BBS:COMMANDS/BBSCMD/\n             and put the door in DOORS:cYBER-DOORS/cYBER-RL/\n\n\n\n                            -{ qUiCK mESSAGEs }-\n\n\nShaitan.............I read the Dox on cY8ER-AVAiL! Hahahaha! Jup! PiSSED!\n                    Hope the logoff thingy is working now?\n                    I think I''ll try that C stuff instead m8, got time on\n                    my hands =8)\n                    Oh jup, how did the meeting go on Thurs?\n\nJEi.................Don''t fuck off to Berlin & I''ll give you £150 for the \n                    mig ;)\n                    Hope the pc is working now?\n\nData-Stream.........Allo G! Hope everything''s \n\nSnow White..........Alllooooooooooowwwwwwwwweeeee South Sheilds.\n                    (Which I might add wasn''t where I expected it ;)\n                    Still doing some trading?\n\nAce.................Allo aRty, hope 13th is as cool as ever.\n                    Saw the Fame release, nice, erm can I now have your\n                    Regg''d copy of 13th hr /X? I wanna take over & update\n                    it.\n\ntANGo...............D! Allo m8, Hope uNi went fine ''n'' funky for you?\n                    Still pestering Art aye? hehe.\n                    Erm, bloik, I need some more cYBER askii doing if\n                    you have some 3-4 secs of your time free.\n\npHAiD...............You forgot to ring me voice again\n\nhYBRiD..............What about an INtERnET conf m8?\n\nHoTWiRE.............Keep up the fu\n\ndENNiS T............I''ll ring you voice soon d!\n\n\n\n                         -{ qUiCK gREETiNx }-\n\n\n       Cruise, Ice D, Cyanide, Linebacker!, FLi7e, Crash!, Sasha,\n       Rage, MDR, Nes, Iggy, Biggles, Rebel, Hermski, Sonic/Warks\n       Red Devil, Reflex, Dreamfish, fish, Godfather, Homer, Dan,\n       Protocol, Venom, Sonny, CLoe & the sysop of cyberdreams ;)\n           \n\n                       gREETiNX tO aLL iN....\n\n           ____________________________________________________\n           \_____    \     ___________ ___     /   \     _____/\n           /.   /    /.   ___/_/.   _   \/.   /    /.   ___/_\n          //   /    //        //   /    //   /    //        /\n         /____/    /____     /____/    /\________/____     /\n             /____/    /____/    /____/              /____/\n                  ______________________________________\n                  \______   \___  / ___     \     _____/\n                  /.  __    /.   _    /.    /.____   \\n                 //   /    //   /    //    //        /\n                /____/    /____/    /_____/____     /\n                    /____/    /____/tGø/aC!   /____/\n\n\n                                +\n  _____        ____.        ______               ___  ___     ________\n._\\   /____ ._\\   |____ ._\\    /_  ._\\ ___ ._\\  \/   \ ._\\____   \-T!\n|     |    .\|      |   .\|      __/__|   \\ .\|     \/   .\|  ____/   .\\n|    /|     \\      |    \\      \    \       \\______\    \\           \\\n|____________/____________/____________\_______/ tGø/_______/____________/\n\n                                 \n                                +\n\n           ____________     __________       ________\n           \   _      |_____\___     |___   _| ____  \\n            \_/   ____|   __  /______|  /__/   \______\\n             /______/ |   ___/____/  |___ /_________|\n                   /____\______\ /__________|\n\n\n\n                                 &                         __\n /\    /\                                                 /  \\n \/   /  \_____________       ____________/\_________  /\/ /\ \__     /\\n   /\/ /\___\___     ¬|      /~  _________________  ¬\/   /  \__ \__/\\/\n   \__/ __/\__ |  o   |_____ \_______  ¬\  |~    Y    \/\/__/\__\__  /\n        \    / |     ¦|~   ¬\/~          \ |    ¦|  o  \  \    /   \/\n        /    \ |     °|      \    o       \|    °|     