INSERT INTO door_catalog VALUES('d_b_fd10','D_B_FD10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/D_B_FD10.LHA','Fastdupe','XIM','Fastdupe',NULL,NULL,NULL,'\____  \___  \ \____  \___  \/  ___/  of /  /  /  ¬ _/  /  /  /  ¬  /  ___/  tRSI /_____/__/  /o /_____/__/  /_____/& zENITh',replace('_____________  _____________  ______        \n\____  \___  \ \____  \___  \/  ___/  of    \n /  /  /  ¬ _/  /  /  /  ¬  /  ___/  tRSI   \n/_____/__/  /o /_____/__/  /_____/& zENITh  \n _____  /__/ & ________/__/_  _____________\n \   /_____.__/  /  ______  \/    \___  \__\\n / .   /  / _/ __/ ___/     /  /  /  /  /  /\n/_____/__   /__/_____/__/__/__/__/_____/__/ \n   ________/of (Mystic/X-Design) presents:\nFASTDUPE 1.o - at least the best DupeCheck!\n It Checks a 3 MB list in under 10 Seconds\n','\n',char(10)),'FastDupe.guide',replace('@database FastDupe v1.o by Byteandi ^ Dr.Dre!\n\nCopyright (C) 1994 by Byteandi ^ Dr.Dre!\nAll Rights Reserved\n\n@Remark $VER: Version v1.o (Saturday 12-Mar-94)\nRemark AmigaGuide DataBase for FastDupe v1.o\n\n@Node MAIN "FastDupe v1.o (Saturday 12-Mar-94) Dcoument for /X"\n\n                _____________  _____________  ______        \n                \____  \___  \ \____  \___  \/  ___/  of    \n                 /  /  /  ¬ _/  /  /  /  ¬  /  ___/  tRSI   \n                /_____/__/  /o /_____/__/  /_____/& zENITh  \n                 _____  /__/ & ________/__/_  _____________\n                 \   /_____.__/  /  ______  \/    \___  \__\\n                 / .   /  / _/ __/ ___/     /  /  /  /  /  /\n                /_____/__   /__/_____/__/__/__/__/_____/__/ \n                   ________/of Mystic/X-Design presents:\n\n                           are proud to present: \n                              FASTDUPE! v1.o\n                             @{" Introduction  "Link no1} \n                             @{" Requirements  "Link no2} \n                             @{" Installation  "Link no3} \n                             @{"   ToolTypes   "Link Tooltypes} \n                             @{"   Copyright   "Link no4} \n                             @{"   Greetings   "Link no5} \n\n@endnode\n@node no1 " Introduction"\n\nThis is at least the best Duplicate Checker arround at the Moment.\nWith many good and usefull @{"Features" Link feat}\n                                                     @{" Main Menu " Link main}\n@endnode\n@node no2 " Requirements"\n\nKICKSTART 2.0 or higher\nAmiExpress 2.xx - 3.xx\n\n                                                     @{" Main Menu " Link main}\n\n@endnode\n@node no3 " Installation "\n\nCopy the FastDupe & FastDupe.Info to your DOORS:\nCopy the FileCheck.Info & DUPESTART.INFO to your BBS:/COMMANDS/SYSCMD/\nAfter them open the FastDupe.Info and choose between the available\n@{"ToolTypes" Link ToolTypes}\n\n                                                     @{" Main Menu " Link main}\n@endnode\n@node feat "Notable Features"\n\nCheck 3 MB Filelist under 10 secs\nDisable specified Users by Name from the Duplicate Check.\nor disable with AccessLevel in the FASTDUPE.Info\nDisplay a TXT File after each Duplicate Check.\nExecuting up to 10 other Doors/Tools after each Upload.\nYou can make the FASTDUPE Resident for faster Access.\n\n                                                     @{" Main Menu " Link main}\n\n@endnode\n@node no4 " Copyright"\n\n   The Door was written by ByteAndi & Dr.Dre! and are coprightet to them\n\n              FastDupe has a Original Size from : 10824 Bytes\n\n                The AmigaGuide File was written by Dr.Dre!\n\n            For more usefull Doors/Tools call one of this BBS`s\n                         @{"       Diabolo       " Link Diabolo}\n                         @{" Marleys Coffee Shop " Link Coffee}\n\n                             @{" Main Menu " Link main}\n\n@endnode\n@node Tooltypes "Available ToolTypes"\n\nOVERRIDE_LEVEL=<LEVEL>\n----------------------------------------------------------------------\niE. \nOVERRIDE_LEVEL=200, this means every User with Level 200 or higher\nare disabled from the Duplicate Check Procedure.\n----------------------------------------------------------------------\n\nNAME.<#>=<String>\n----------------------------------------------------------------------\niE.\nNAME.1=ByteAndi/MST\nNAME.2=Dr.Dre!/tRSi\nNAME.3=Jeannie/SR\nThis means all Users above are disabled from the Duplicate Check\nProcedure.\n----------------------------------------------------------------------\n\nDISPLAY_TXT (Optional)\n----------------------------------------------------------------------\nIf you set this ToolType, the FastDupe will search in the actual\nConference for an TextFile called FASTDUPE.TXT(.GR) if the (.GR) not\nfound then it will display the .TXT File.\nHere you can write down what ever you want.\n----------------------------------------------------------------------\n\nDOORSTART.<#>=<STRING>\n----------------------------------------------------------------------\nAbout this ToolType it is possible to start up to 10 other Doors/Tools \nafter each DupeCheck, this is usefull if you run the ConfTop from bObO\nor the FileSystem for the BossNuke or whatever you run after each Upload.\nExplainment of the ToolType:\nDOORSTART.1=FASTDUPE1\nThis means the FASTDUPE trys to execute the FASTDUPE1.Info in \nBBS:COMMANDS/BBSCMD/ or BBS:COMMANDS/Node<X>CMD/\nBuild in this Icon what ever you want to run after the Upload.\nSee our Example Icon from the original Archive.\nI hope this will explain a bit this ToolType.\n----------------------------------------------------------------------\n\n                                                     @{" Main Menu " Link main}\n@endnode\n@node no5 " Greetings"\n\nGreetings from Byteandi..\n\n         To Dr.Dre! because nice Coding on Weekend...............\n       Special Greetings to Sigma Seven....please don`t be worry but \n       C! is Faster as E!\n                               to Empire...\n                  //\n       Thanx to \X/ Amiga For Being The Best Computer Ever made ...\n\nGreetings from Dr.Dre! to this Dudes:\n    ByteAndi/X-Design, Spy/X-Design, Remo/X-Design, X-Treme, Saito/TRSI\n      Fugitive/DLM, MetalbasheR!, McLoud/TRSI, Irata/TRSI, Triton/Pdy\n Skylark/LSD, Nick, Metoner/TRSI, J.Walker/TRSI, Crazy/TRSI, Valshare/TRSI\n     Vicous/LSD, Richi/Flt, Steve/D&R, Amicom, -rS!/TRSi, Empire/Mst, \n  BJoerN/Pdy, Scope, SkiN!,Mario/TRSI, TCM!/DLM, -runt/TRSI, Prayer/TRSI\n                         Samir/trz, Rotor/trz ...\n       and simply all tRSi & trz Member and other Doodes I forgot...\n\n\n\n\n                                                     @{" Main Menu " Link main}\n@endnode\n@node Coffee "Marleys Coffee Shop - TRZ german hQ"\n\n           * tRiStAR & RED sECtOR * zENITh * gERmAN hEADqUARtER\n                                           _______    ._____\n      _______  ____.______  ______________/   .  /____|    /_______\n      \      \/    |      \/   _  \      /   ___/_    l   /   __  /\n       \           |      \\   /  /_    /_________l____  /\__   \/\n        \    \/____l________\  \____|______|    |_______/________\\n         \____\         /______|                       _______\n                 ____          _______________________/   .  /\n                /  __l_. _____/     __/     __/   .  /   ___/_.\n               /   |   |/     \     _/\     _/   ___/_________|\n              /________|      \\____|  \____|_________|\n                       \_______/         _____    \n                      __________________/     \__________\n Dr.Dre!/tRSi        /   __  /    /    //      \    .   /\n                    /\__   \/         /\_______/    ___/\n  J.Walker/tRSi    /________\   /____/-rS!/aRt/_____|\n                          /____/\n\n                                                     @{" Main Menu " Link main}\n@endnode\n@node Diabolo "Diabolo Mystic/X-Design WHQ"\n\n                 _______·__:_____ _____ _____.__.  :_____:                     \n                 \____ ¬V ¬V___ ¬V___ ¬V___ ¬V ¬|  |___ ¬|                     \n                ) | ¬|  |  | ¬|  | ¬|  | ¬|  |  |  | ¬|  |    MANAGEMENT       \n                  |  |  |  |  |  |  |  |  |  |  |  |  |  |  -============-     \n                  |  |  |  |     |    _|  |  |  |__|  |  |   ByteAndi/MST      \n                  |  |  |  |  |  |  | ¬|  |  |  | ¬|  |  |     SPY/MST         \n                  |  |  |  |  |  |  |  |  |  |  |  |  |  |     FELDMAN         \n                  |  |  |  |  |  |  |  |  |  |  |  |  |  |    FuZzY/MsT        \n                  |  |  |  |  |  |  |  |  |  |  |  |  |  |   Wolfmann/ATX      \n                / |  |  |  |  |  |  |  |  |  |  |  |  |  |  -============-     \n                  |  |  |  |  |  |  |  |  |  |  |  |  |  |   RUNS oN A3000     \n                  |  |  |  |  |  |  |  |  |  |  |  |  |  |  WiTH 25MHZ AND     \n                  |  |  |  |  |  |  |  |  |  |  |  |  |  |   AMiEX (REG.)      \n                __|_____A__A__A__A_____A_____A_____A_____|  -============-     \n                  |     :  :     :     :     :     :     |                     \n                  :     ·  .     .           .     ·     :\n\n                                                     @{" Main Menu " Link main}\n@endnode\n','\n',char(10)),NULL,'auto-added',14695,2,0,NULL,NULL,'d_b_fd10','scan',1780048498);
INSERT INTO door_catalog VALUES('d_r_ae48','D_R_AE48.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/D_R_AE48.LHA','ACP','XIM','ACP',NULL,NULL,NULL,'_ _ __ _ __ _ _ __ _____   ____________   \ :::::::::::::::::::/   |\  \:::::/ ___/   / ::::The Legend::::/    |/   \:&:/  \__    \_',replace('__ _ __ _ __ __ __ _______________________  \n_ _ __ _ __ _ _ __ _____   ____________   \ \n:::::::::::::::::::/   |\  \:::::/ ___/   / \n::::The Legend::::/    |/   \:&:/  \__    \_\n:::::Is Back!:::::\____|____/:::\_____|____/\n.------------------------------------------.\n| Diamonds & Rust Germany Released 2Day... |\n|                                          |\n|      Ami-Express V4.8 With ACP 4.8       |\n|                                          |\n`------------------------------------------''\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 19:27:08  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',191069,2,0,NULL,NULL,'d_r_ae48','scan',1780048498);
INSERT INTO door_catalog VALUES('d_access','D-ACCESS.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/D-ACCESS.LHA',NULL,'XIM','D-Access.rexx',NULL,NULL,NULL,'i have seen todate!',replace('D-Access NewUser questions etc! best one\ni have seen todate!\n','\n',char(10)),'D-Access.TXT',replace('If you wish to become a member of the POINT BLANK BBS then you must:\n \n1) Fill in, SIGN and return 2 COPIES OF THE CALLER AGREEMENT FORM the first\n   month you apply for access ONLY!         ^^^^^^^^^^^^^^^^^^^^^\n \n2) Send the FULL AMOUNT WITH THE MOTHLY ACCESS FORM EVERY MONTH!!!\n                                 ^^^^^^^^^^^^^^^^^^\n    *********************************************************************\n    *                                                                   *\n    * ACCESS: $35/MONTH FOR 9600+ BPS LOCAL USERS ONLY.                 *\n    *         ACCESS FEE INCLUDES 45 MINUTE DAILY TIME LIMIT, UNLIMITED *\n    *         FILES TRANSFERABLE BETWEEN MIDNIGHT AND 5 AM *ONLY*!      *\n    *                                                                   *\n    *********************************************************************\n\n        RETURN THIS FORM WITH CASH, CHECK OR MONEY ORDER PAYABLE TO:\n \n                                 PHIL HORNEY\n                               P.O. BOX 58408\n                           CINCINNATI, OHIO 45258\n\n ALL ORDERS ACCOMPANIED BY PERSONAL CHECKS MUST WAIT 10 DAYS FOR PROCESSING!\n\n PLEASE FILL OUT ALL INFORMATION CORRECTLY, YOU WILL BE MAILED A COPY OF THE\n            ACCESS AGREEMENT UPON IT''S COMPLETION AND EXECUTION.\n\n                         THANK YOU FOR YOUR SUPPORT!\n\n\n-----------------------------[CUT HERE]--------------------------------------\n\n                     POINT BLANK BBS MONTHLY ACCESS FORM\n                     -----------------------------------\n\n\n               NAME_______________________________\n\n \n             HANDLE_______________________________\n\n\n            ADDRESS_______________________________\n\n\n     CITY,STATE,ZIP_______________________________\n\n\n       PHONE NUMBER_______________________________\n\n\n       MAXIMUM BAUD_______________________________ \n \n    \n    AMOUNT ENCLOSED $____________ FOR ______ MONTHS OF ACCESS.\n\n\n\n\n\n\n\n\n\n\n\n                      POINT BLANK BBS CALLER AGREEMENT\n                     <=+=+=+=+=+=+=+=++=+=+=+=+=+=+=+=>\n\nThis POINT BLANK BBS is a PRIVATE system!  Only private citizens whom are not\ninvolved with ANY country''s government or law enforcement agency or their \nactivities in any capacity are authorizied to use it.  The users are neither \nauthorized nor permitted to divilge any information gained in any way from\nthis system to any country''s government or law enforcement agencies or to\nemployees or affiliates of such governments or law enforcement agencies.\n \nNo person is to violate FCC, Copyright or other lawful regulations.\nAll data that is received is assumed to be within the the public domain.\nShould anyone advise us to the contrary we will investigate and remove\nmaterials that do not comply with these regulations and delete users who fail\nto abide by these terms and is our (sysop''s) sole extent of liability.\n\nAccess to this system by any Law Enforcement Agency (International, Federal,\nState, Local or Other), software company (including Nintendo® and Sega®),\ntelephone company, government agancy, or any one affiliated with the\naforementioned is not not allowed.  THIS IS A PRIVATE SYSTEM!  The above\nrules are in place to assure that the rights of members and sysop(s) of this\nBulletin Board System are not violated.\n \nNo person is to use any illegal means to connect with (call) or gain access to\nthis Electronic Bulletin Board System.\n\nThis is a legal and binding document.  By signing it you are agreeing to \nabide by the above rules and are granting the sysop(s) and members\npermission to use all the information contained herin and in any other part\nof the POINT BLANK BBS in whatever way necessary ONLY in the case of legal\ndispute, battle, claims, or any such legally involved action or as evidence \nagainst you (the user) should any of the aforementioned events occur.\n\n\nUSER NAME_____________________   POINT BLANK BBS OFFICER____________________\n\n\nSIGNATURE_____________________              SIGNATURE_______________________\n\n\nDATE SIGNED___________________              DATE SIGNED_____________________\n\n','\n',char(10)),NULL,'auto-added',65757,2,0,NULL,NULL,'d_access','scan',1780048460);
INSERT INTO door_catalog VALUES('d_scom10','D-SCOM10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/D-SCOM10.LHA',NULL,'XIM','Comment.exe',NULL,'-DUX-',NULL,'? ??? ??????? ?? ??? ?????? ?????? ? ??? ?????????????? ?????? ???`?? ? ???????? ???????????? ??????',replace('????????????????????????????????????????????\n    ? ??? ??????? ?? ??? ?????? ??????      \n    ? ??? ?????????????? ?????? ???`??      \n      ? ???????? ???????????? ??????        \n     ?????????????? ???????????`?????       \n--------------------------------------------\n    A NeW ReLeAsE In ThE FaMoUs SeRiEs      \n           SYSOP COMMENT V1.0               \n      A DoOr FoR /X v2.20 AnD HiGhEr        \n     CoDeD By -DUX- ThE OnE AnD OnLy!       \n--------------------------------------------\n','\n',char(10)),'Comment.doc',replace('-----------------------------------------------------------------------------\n\n                            SysOp Comment v1.0\n\n                                Coded By Dux\n\n-----------------------------------------------------------------------------\n\nABOUT\n-----\n\nThere''s A Few Other SysOp Comment Doors Out There Somewhere, But I Always\nNeeded A Little More Speed Than You Can Get From An ARexx Door And I Didn''t\nLike The 5-6 Lines Where The Coder Always Writes Something Like: Coded By\nBlabla And Thanks A Lot To My Mother Blabla And Please Call All My Friends''\nBoards Blabla etc etc.\n\nSo I Did This Little Piece. Nothing Fancy, Just Gets The Job Done In A Hurry\nAnd Only Supports Up To 99 Different People To Write To...\n\n\nINSTALL\n-------\n\nInstall It Like Any Other AmiExpress Door In Your CustomCommands:\n\n*C        XM001Doors:Comment/Comment.exe\n\nThe Executable And The Configfile MUST Be In Doors:Comment/ And The Syntax Of\nThe Configfile Is:\n\n1st Line: Name Of Reciever 1\n2nd Line: Description Of Reciever 1\n3rd Line: Name Of Reciever 2\n4th Line: Description Of Reciever 2\netc etc\n\nThe Name Of The Reciever Must Be Less Than 30 Chars (Max. Number In\nAmiExpress) And The Description Must Be Less Than 50 Chars.\n\n\nOTHER STUFF\n-----------\n\nIf You Should Have More Than 98 CoSysOps Just Call My Board And I''ll Do A\nSpecial 1000 Persons Version Just For YOU!\n\nPlease Report Any Bugs (There Shouldn''t Be Any) And/Or Ideas For Improvement.\n\nReach Me At My Board: Mainline +45-981 53062 Where You Always Can Get My\nLatest Utils And Doors.\n\n\nHELLOS\n------\n\nA Special Hello To My BetaTesters:\nCirculator, Easy Rider, Hellhound, RamRaider, Tarzan.\n\nA Normal Hello To:\nAlzheimer, Pennywise, Ramirez, Stonehead.\n\n\nEND OF FILE','\n',char(10)),NULL,'auto-added',11771,2,0,NULL,NULL,'d_scom10','scan',1780048460);
