INSERT INTO door_catalog VALUES('dcn_fid3','DCN_FID3.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DCN_FID3.LHA',NULL,'XIM','pizza_taxi.exe',NULL,'Derrow','DCN','_________________________________________  | ____ \_ ____/ _______) ________)   \___  \ | /  /  / __/_  \  \   \___  \   \_|  \ |   \|',replace('.-----------(dCN-/F·dEZiGN)----------------.\n_________________________________________  |\n____ \_ ____/ _______) ________)   \___  \ |\n/  /  / __/_  \  \   \___  \   \_|  \ |   \|\n_____/_____/______)__ /____/___ /___/_|    \\n|···················\/AdN!····\/······\____/\n|         dCN!FileID v3.o PUBLIC!          |\n|  nOW sUPPORTS fULL bACKgROUND pOSTiNG,   |\n|      wILDcRAD sTRIP aND mANY mORE!       |\n|    cODED bY Derrow (dCN-/F·dEZiGN)       |\n`--- -- - - - - - - - - - [07-06-96] -- ---''\n','\n',char(10)),'Ringelblume4.txt',replace('                 \n                                  ·     ·\n                               _ __\   /__ _\n                            _ _)\\  \ /  //(_ _\n                           -\   __\° X °/__   /-\n                    _ __ ___ ___)  \/_\/  (___ ___ __ _\n                   -\\\_\\__\\__  _ /¦\ _  __//__//_///-\n             ·         _.      \__)_¯_¯_(__/      ._         ·\n           _/          \|_       | | | | |       _|/          \_\n         __\ ___ _/\____\/__ __ _| | | | |_ __ __\/____/\_ ___ /__\n       _/   \  (_)  \   \/  /_/\\| |_|_| |//\_\  \/   /  (_)  /   \_\n       |                    \_\/ | | | | | \/_/                    |\n      _|                      __ | | | | | __                   _ _|_\n      \|_ _                   \/_| | | | |_\/                      |/\n       |                     · _)  ¯_¯_¯  (_ ·                     |\n       |  ·H2o!·              \\___ \ / ___//                      |\n       ¯\_______________________ _)  Y  (_ _______________________/¯\n                                 \___ ___/\n                                    (_)\n ','\n',char(10)),NULL,'auto-added',7242