INSERT INTO door_catalog VALUES('dcs_ax15','DCS-AX15.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DCS-AX15.LHA','lha','XIM','McFree',NULL,'cheap','DCS','__|  \________________/_ dUAL cREW /  _   _/   ___/   ___/dUAL cREW sHINING/   |   |    |  \___   \  sHINING',replace('            _|__\n           __|  \________________/_\ndUAL cREW /  _   _/   ___/   ___/dUAL cREW\n  sHINING/   |   |    |  \___   \  sHINING\n         \_______|______________/\n AX-Edit is back with a FUCKING vengeance!\n Don''t be fooled by cheap editors, get the\n      real thing. For all /X versions.\n','\n',char(10)),'Backdoor.txt',replace('              Backdoor & Trojan Disclaimer by Mack Lifeguard\n              ==============================================\n\nIf you use Ax-Edit or Turbo Zippy on your system, read on.\n\nRecently, it seems there are a group of lamers in the scene intent on\nspreading bogus text files and other insane paraphernalia regarding my\nAmiexpress doors--possibly even trojans and viruses.\n\nMainly it is the doing of an obsessed loser named James Conwell (The\nController).  Yes, The Controller helped me code Turbo Zippy, but it''s a\nloooong story full of hate and greed.  He has now turned against me and\nwill do anything in his power to ruin my reputation as a door coder.\n\nThe purpose of this text file is not to prove myself to you.  I am simply\ngoing to state the following for the record:\n\nIF YOU ARE A SYSOP AND PLAN ON INSTALLING ANY OF MY DOORS (AX-EDIT AND\nTURBO ZIPPY), BE ABSOLUTELY SURE THAT THE FILE YOU HAVE WAS UPLOADED BY A\nBONAFIED Dual Crew Shining MEMBER OR, EVEN BETTER, DOWNLOAD THE FILE FROM\nA DCS BOARD.\n\nIf this lamer decides to put out a bogus Ax-Edit or Turbo Zippy, then your\nonly protection against a trojan is to follow this advice.\n\nAlso, another important note:\n\nI ONLY CALL 4 BBSs IN THE WHOLE WORLD.  THEY ARE AS FOLLOWS:\n\n1.Hangar 18:           (713) 488-3055\n2.International Chaos: (713) 999-3640\n3.Complex Corrosion:   (612) 773-0522\n4.Danse Macabre:       (713) 324-1165\n\nThere is no exception to this fact! If someone is using my handle on your\nbbs, then it sure as hell isn''t me!\n\nSo you are warned. Don''t go blaming me or DCS if you get scr00d. Dual Crew\nShining makes quality, professional tools for your Amiexpress system, we\ncannot be held liable for the actions of a handful of lamers. Thanks for\nunderstanding.\n\n\n                       DCS /X Doors Approved Sites\n                       ---------------------------\n\nCOMPLEX CORROSION (USHQ)  +1-612-7730522   (4 NODES)   SYS: WHITE IC\nGURU''S DREAM (WHQ)        +46-8-282760     (9 NODES)   SYS: DIRTYBUSH\nULTIMATE DREAM (UKHQ)     +44-222-ELITE!   (2 NODES)   SYS: HYBRID\nSECRET WORLD (GHQ)        +49-30-8854598   (1 NODE)    SYS: EXE & PHR\nEASTERN FRONT (SFHQ)      +358-28-22915    (2 NODES)   SYS: HAKA & TRUXTON\nHANGAR 18                 +713-488-3055    (2 NODES)   SYS: Flyboy\nINTERNATIONAL CHAOS       +713-999-3640    (2 NODES)   SYS: Shatterstar\n\n','\n',char(10)),NULL,'auto-added',155806,9,0,NULL,NULL,'dcs_ax15','scan',1780048474);
INSERT INTO door_catalog VALUES('dcs_st02','DCS-ST02.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DCS-ST02.LHA',NULL,'XIM','____',NULL,'nUP!','DCS','____/_ _/_____  _______ _ _____________._ /  ____\\\\__  \/  ____////             | /   /   /   /___/\___  \      dUAL cREW  ¦',replace('        ____\n   ____/_ _/_____  _______ _ _____________._\n  /  ____\\\\__  \/  ____////             |\n /   /   /   /___/\___  \      dUAL cREW  ¦\n/  _/   /  _/   /  _/   /       sHiNiNG   :\n\______/\______/_______/dZG               ·\n-------------------------------------------\nsTATiON v0.2 -The ultimate status-door for\nall of those SysOps who don''t like status-\ndoors with 90% of it''s infos are total crap\nCoded w/ AmigaE by nUP! - Design: U-MAN/AL!\n-------------------------------------------\n','\n',char(10)),'sTATiON.dOC',replace('\n\n         _____    ____          ___\n        _\__  \__/  / \______ _/  /___\n       /   /   /   /   /_    /   /   /\n      /__ /   /_______//    /__     /\n      <--\___/-------/_________\___/------------------------------------+\n           _/  _____   ____    ____    ___/____                         |\n             _/    / _/    \__/  _/  _/  /   / \_                       |\n            /   /_/_/   /___/   _/__/   /   /   /_                      |\n           /__ /   /___/   /__ /   /______     ///_                     |\n              \___/           \___/       \____\                        |\n                    _____   ____    _   ____    _   ____    ____ _      |\n                  _/  __/__/  / \__/ \_/    \__/ \_/    \__/    \_\_    |\n                 /\__    /       /   /   /   /   /   /   /   /   / /    |\n                /__ /   /___/   /___/___/   /___/___/   /__   __/       |\n                   \___/   \____\      \____\      \____\  \___/<-2F----+\n\n\n\n\n-------------------------------[·pRESENTS·]--------------------------------\n\n\n                             ··sTATiON v0.2··\n\n\n---------------------------------------------------------------------------\n\n\n\n\n                         o1. What is sTATiON?\n\n                         o2. How to install it?\n\n                         o3. Credits\n\n                         o4. Greets\n\n                         o5. How to contact\n\n                         o6. History & the future\n\n\n\n---------------------------------------------------------------------------\n\n\n\n\n o1. What the f**k is sTATiON?\n\n\n   sTATiON is a status door for /X&S!X like 80% of the doors released.\n So, why did I make and release this? I made this for the fun of it,\n and I made it also because of the fact that most status-doors show\n alot of crap and just a few bytes of infos.. so this is how this looks:\n\n _________                                                           ________\n \     __/______________________  ____________ _____ _______________|       /\n _\___       / _       /   _    \/   _       /_____(_   _      /    \      /\n ___________/  /______/   _/     \_  /______/       /   \     /______\____/\n      uMn/_________(______\_______/______(_________/_________/aL\n--------------------------------------------------------------------------------\n nAME.....:[nUP!]                     lOCATION.....:[dUALcREW&sHINING]\n uPLOADED.:[99999 kB]                 dOWNLOADED...:[0 kB]\n rATIO....:[dISABLED]            __   rATIOtYPE....:[bYTES]\n aXXlEVEL.:[255]            _____\/_  cONFaCCESS...:[sYSOP]\n----------------------------\    /\/--------------------------------------------\n [sTATiON v0.2 bY nUP!/dCS]  \  /                 [uNREG''d tO: aRCTiC cIRCLE]\n                              \/\n\n It''s fast, it''s nice looking, and it doesn''t have too much crap in it!\n\n\n\n o2. How to install it?\n\n\n   Just copy these files from the ''DCS-ST02.LHA'' to your BBS: drawer:\n\n COMMANDS/BBSCMD/S.Info\n DOORS/DCS/sTATiON/sTATiON.XiM\n DOORS/DCS/sTATiON/sTATiON.doc\n \n\n\n o3. The credits:\n\n\n                  CODING:  nUP!/DUALCREW&SHINING\n                  DEZIGN:  U-MAN/ARCLiTE\n                  TESTING: HAKA/DUALCREW&SHINING\n                           U-MAN/ARCLITE\n\n\n\n o4. Greets to the following:\n\n\n   U-MAN/aL!........              ..yo, bro! Nice look dewd!\n\n   HAKA/DCS.........              ..I will soon visit you for sure!\n\n   TRUXTON/DCS......              ..So.. Maybe we''ll go to booze someday?\n\n   MDR/HF!..........              ..Erm.. Sorry, I have not got any means\n                                    of calling for you for free now..\n                                    I''ll soon be back, I promise!\n\n   DESOTO/M''S.......              ..Release something!\n\n   MARK RYDER/M''S...              ..Cewl to be in Mo'' Soul!\n\n   TRAITOR/OTL......              ..Ei tää sun kovoo forkkaa:)\n\n   TOXIC/OTL........              ..Finally I found your bbs'' number!\n\n   VEGAS/OTL........              ..Hopefully I''ll get Arctic Circle soon back\n                                    so that you could support it again:)\n\n   BISCROK/OTL......              ..Where are you mate?\n\n   IMMORTAL/VD/FLT..              ..Kiitos kaunis avustas E:n kanssa!\n\n   FATAL/E^D........              ..Tnx to you too for helping me out!\n\n   MR.WISHBONE/OTL..              ..I will call you soon..\n\n   PATRICIAN/OTL....              ..Öö.. Kun pääsen taas reidaan, niin suppaan\n                                    kyllä HDC:täkin!\n\n   THE REST.........              ..The rest, you are best! <- I am elite!:)\n\n\n               ··WATCH OUT FOR THE NEW SPPN COMING DCS PRODS!··\n\n\n\n o5. Where can you come and sew me for formated HDs etc..\n\n\n   Find me at:\n\n                         Eastern Front    (Finland)\n                         Zillion Hours    (Finland)\n                         Hard Disk Cafe   (Finland)\n                         Bermuda Triangle (Finland)\n                           Interchange  (Sweden)\n                           Another Step (Sweden)\n                           Final Impact (Sweden)\n                         One Eight Seven (Holland)\n                         Boondocks       (Holland)\n                         The payoff      (Holland)\n                          Cement City   (England)\n                          Digital Candy (England)\n                         Raveland        (Germany)\n                         Punishment Inc. (Germany)\n                            Sky Tower (Denmark)\n\n\n\n o6. History & The future\n\n\n  History:\n\n *private*version 0.1 -First experiment for a nice stats door\n\n *public!*version 0.2 -Design by U-MAN/ARCLITE and a few fixes\n\n\n  Future:\n\n v0.3 Configurable+upload comment+nicer outlook+possible bugfixes\n\n\n  Other projects:\n\n tRAM (The real advertisement machine)        - a textfile-adder\n cONFESSiON                 - A joinconf-door with cewl options!\n dEVELOPER                  - A door for the door developers..\n   \n\n\n\n\n\n\n\n\n\n\n\n\n\n l8er!\n\n                                                     -nUP!/dCS\n\n','\n',char(10)),NULL,NULL,6043,4,0,NULL,NULL,NULL,'scan',1780048474);
INSERT INTO door_catalog VALUES('dcsxc100','DCSXC100.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DCSXC100.LHA','5D-ZippySearch','XIM','5D-ZippySearch',NULL,NULL,NULL,'____¦____  (   _____/__  - ------------- _/     ___/ _/\_  T     ¬\_ ·  diGiTAL   · .-\     ¦/    7--7  l       / · cORRUPTiON ·',replace('        .________________\n    ____¦____  (   _____/__  - -------------\n  _/     ___/ _/\_  T     ¬\_ ·  diGiTAL   ·\n.-\     ¦/    7--7  l       / · cORRUPTiON ·\n|  \____.-----¦  ¦----.____/------- -  -   -\n|              SYSTEM-X 1.00\n|  BBS Software featuring XPR Protocols,\n|  16 color ansi, 5 door types and more.\n|             (Conference Based Version)\n`-[10/06/97]---------------------------[Zed]\n','\n',char(10)),'Dev.GUIDE',replace('@database SXDEV\012@node MAIN "Developing Doors"\012\012		  DEVELOPING DOORS AND UTILS FOR SYSTEM-X\012\012		    @{" Structures associated with SX     " Link structs}\012		    @{" How the door port works in theory " Link port}\012		    @{" List of XIM functions available   " Link funcs}\012		    @{" Communication with MCP            " Link mcp}\012\012 .-----------------------------------------------------------------------.\012 | System-X uses the XIM door port as its primary door port. This means  |\012 | it''s compatable with AmiExpress. If you are intending to write a door |\012 | especially for System-X, use the XIM port, as it gives you the most   |\012 | power.                                                                |\012 `-----------------------------------------------------------------------''\012\012 Note: if you find any developer/starter packs around for AmiExpress, they\012       will work just fine with System-X. There are examples for AmigaE\012       and heaps of ASM examples around. Developing doors for SX can also\012       be done using any of the other door types, but XIM is the best for\012       SX (has the most commands available).\012@endnode\012@node structs "Structures"\012\012The structures are all in ''C'' format, but in general:\012\012WORD, short		=	16 bit signed word\012UWORD			=	16 bit unsigned word\012int, long, LONG		=	32 bit signed word\012ULONG			=	32 bit unsigned word\012APTR			=	32 bit pointer\012\012Any fields with an asterix "*" infront of them are pointers!\012\012\012.---------------------------------------.\012| User.data or User structure in memory |\012`---------------------------------------''\012\012struct UserData {\012	char	Name[31],\012		Pass[9],\012		Location[30],\012		PhoneNumber[13];\012	USHORT	Slot_Number;\012	USHORT	Sec_Status,		/* access level */\012		Sec_Board,		/* unused	*/\012		Sec_Library,		/* unused       */\012		Sec_Bulletin,		/* unused	*/\012		Messages_Posted;\012	ULONG	NewSinceDate,\012		ConfRead1,\012		ConfRead2,\012		ConfRead3,\012		ConfRead4,\012		ConfRead5,\012		ConfRead6,\012		ConfRead7,\012		ConfRead8,\012		ConfRead9;\012	char	Conference_Access[10];\012	USHORT	Uploads,\012		Downloads,\012		ConfRJoin,\012		Times_Called;\012	long	Time_Last_On,\012		Time_Used,\012		Time_Limit,\012		Time_Left;\012	ULONG	Bytes_Download,\012		Bytes_Upload,\012		Daily_Bytes_Limit,\012		Daily_Bytes_Dld;\012	char	Expert;\012	ULONG	ConfYM1,\012		ConfYM2,\012		ConfYM3,\012		ConfYM4,\012		ConfYM5,\012		ConfYM6,\012		ConfYM7,\012		ConfYM8,\012		ConfYM9;\012	long    BeginLogCall;\012	UBYTE	Protocol,\012		UUCPA,\012		LineLength,\012		New_User;\012	};\012\012.---------------------------------------------.\012| User.Index or UserIndex structure in memory |\012`---------------------------------------------''\012\012struct UserIndexStruct\012{\012	char handle[31];\012	char realname[31];\012	UWORD misc;\012};\012\012\012.---------------------------.\012| User.SX file or in memory |\012`---------------------------''\012\012struct SXUserStruct\012{\012	UWORD byteratio;\012	UWORD fileratio;\012	ULONG flags;\012	UWORD freefiles;\012	ULONG freebytes;\012	ULONG ConfAccess[10];\012	UWORD lastfilearea;\012	char computer[24];\012	char sentbyline[46];\012	char password[16];\012	long firstcall;\012	char reserved[110];\012};\012\012\012.-----------------.\012| Prefs/Confs.DAT |\012`-----------------''\012\012struct ConfStruct\012{\012	char name[45];\012	char path[55];\012	char pass[16];\012	char filepath[52];\012	UWORD fileareas;\012	UWORD uploadarea;\012	UBYTE flf;\012	UBYTE flags;\012	char reserve[82];\012};\012\012\012.------------------.\012| Prefs/Serial.DAT |\012`------------------''\012\012struct SerialStruct\012{\012	char device[32];\012	WORD unit;\012	WORD misc;\012	long minrate;\012	long dcerate;\012	UBYTE sevenwire;\012	UBYTE shared;\012	char ring[16];\012	char connect[24];\012	char answer[16];\012	char initstr[48];\012};\012\012\012.-------------------.\012| SX:Prefs/Main.DAT |\012`-------------------''\012\012struct MainStruct\012{\012	char BBSName[64];\012	char BBSPath[64];\012	char BBSLoc[64];\012	char Sysop[64];\012	char DNPath[64];\012	char ULPath[64];\012	long nodes;\012};\012\012.---------------------------------------.\012| SX:LogFiles/Download.LOG & Upload.LOG |\012`---------------------------------------''\012\012struct XferLog\012{\012	UWORD	user_slot;\012	UBYTE	conf,\012		filearea;\012	char	filename[32];\012	long	size,\012		baud,\012		cps,\012		time;\012	UBYTE	node;\012	char	res[7];\012} Xfer;\012\012\012.-------------------------.\012| SX:LogFiles/Callers.LOG |\012`-------------------------''\012\012Note: this file has a UWORD at the top before the first structure, which\012is a pointer to the oldest entry in the log. (its a rotary log of 30)\012\012struct CallerLog\012{\012	UWORD	user_slot,\012		node;\012	long	time_login,\012		time_logout,\012		seconds_online,\012		bytes_uploaded,\012		bytes_downloaded;\012	UWORD	files_uploaded,\012		files_downloaded,\012		messages;\012	long	baud,\012		flags;\012	UBYTE	logout_mode;\012	char	res[25];\012};\012\012\012.----------------------------------------------------------------.\012| NODE STRUCTURE AS PASSED BY MCP-COMMAND-14 OR XIM-COMMAND-1505 |\012`----------------------------------------------------------------''\012\012struct node_struct\012{						/* offset DEC	*/\012	APTR next;				/*	0	*/\012	struct UserData *User;			/*	4	*/\012	struct UserIndexStruct *UserIndex;	/*	8	*/\012	struct SXUserStruct *SXUser;		/*	12	*/\012	char *action;				/*	16	*/\012	char *filename;				/*	20	*/\012	long baud;				/*	24	*/\012	long loginsecs;				/*	28	*/\012	UWORD number;				/*	32	*/\012	UBYTE actionnumber;			/*	34	*/\012	UBYTE active;				/*	35	*/\012	UBYTE useron;				/*	36	*/\012	UBYTE misc;				/*	37	*/\012};\012\012@endnode\012@node port "Door Port"\012\012There are two ways to program doors for System-X. One is to use\012AEDoor.library, which is very easy, and the other is to use exec\012messages, which gives more control. Below is explained the exec\012message style of programming doors.\012\012\012--- The message structure ---\012\012struct JHMessage\012{\012  struct Message Msg;   <----- msg structure\012  char String[200];     <----- info buffer\012  int Data;             <----- Read/Write & result indicator\012  int Command;          <----- Command sent from door.\012  int NODEID;           <----- reserved\012  int LineNum;          <----- reserved\012  unsigned long signal; <----- reserved\012  struct Process *task;\012  APTR *Semi;\012};\012\012\012The port name is AEDoorPort%d , where %d is the node number. General\012in ''C'' you''d do:\012\012--------------------------------------------------\012\012char portname[32];\012struct MsgPort *port;\012\012sprintf(portname, "AEDoorPort%d", atoi(argv[1]));\012port = FindPort(portname);\012\012--------------------------------------------------\012\012See the examples/ directory for more information.\012\012@endnode\012@node funcs "System-X XIM Functions"\012\012  The following list is a list of all System-X HOST Commands which\012  can be used in every program language to get/store information to the\012  AmiExpress Host Port. With this Command you can get Information\012  like BBSNAME, USERNAME etc. Click on the Buttons for more Information.\012\012    @{" JH_LI            <Func: 000> " Link Cap1101000}    @{" JH_REGISTER      <Func: 001> " Link Cap1101001}\012    @{" JH_SHUTDOWN      <Func: 002> " Link Cap1101002}    @{" JH_WRITE         <Func: 003> " Link Cap1101003}\012    @{" JH_SM            <Func: 004> " Link Cap1101004}    @{" JH_PM            <Func: 005> " Link Cap1101005}\012    @{" JH_HK            <Func: 006> " Link Cap1101006}    @{" JH_SG            <Func: 007> " Link Cap1101007}\012    @{" JH_SF            <Func: 008> " Link Cap1101008}    @{" JH_EF            <Func: 009> " Link Cap1101009}\012    @{" JH_CO            <Func: 010> " Link Cap1101010}    @{" JH_BBSNAME       <Func: 011> " Link Cap1101011}\012    @{" JH_SYSOP         <Func: 012> " Link Cap1101012}    @{" JH_FLAGFILE      <Func: 013> " Link Cap1101013}\012    @{" DT_NAME          <Func: 100> " Link Cap1101100}    @{" DT_PASSWORD      <Func: 101> " Link Cap1101101}\012    @{" DT_LOCATION      <Func: 102> " Link Cap1101102}    @{" DT_PHONENUMBER   <Func: 103> " Link Cap1101103}\012    @{" DT_SLOTNUMBER    <Func: 104> " Link Cap1101104}    @{" DT_ACCESSLEVEL   <Func: 105> " Link Cap1101105}\012    @{" DT_RATIOTYPE     <Func: 106> " Link Cap1101106}    @{" DT_RATIO         <Func: 107> " Link Cap1101107}\012    @{" DT_COMPTYPE      <Func: 108> " Link Cap1101108}    @{" DT_MESSAGESPOSTED<Func: 109> " Link Cap1101109}\012    @{" DT_UPLOADS       <Func: 110> " Link Cap1101110}    @{" DT_DOWNLOADS     <Func: 111> " Link Cap1101111}\012    @{" DT_TIMESCALLED   <Func: 112> " Link Cap1101112}    @{" DT_TIMELASTON    <Func: 113> " Link Cap1101109}\012    @{" DT_TIMEUSED      <Func: 114> " Link Cap1101114}    @{" DT_TIMELIMIT     <Func: 115> " Link Cap1101115}\012    @{" DT_TIMETOTAL     <Func: 116> " Link Cap1101116}    @{" DT_BYTESUPLOAD   <Func: 117> " Link Cap1101117}\012    @{" DT_BYTEDOWNLOAD  <Func: 118> " Link Cap1101118}    @{" DT_DAILYBYTELIMIT<Func: 119> " Link Cap1101119}\012    @{" DT_DAILYBYTEDLD  <Func: 120> " Link Cap1101120}    @{" DT_EXPERT        <Func: 121> " Link Cap1101121}\012    @{" DT_LINELENGTH    <Func: 122> " Link Cap1101122}    @{" ACTIVE_NODES     <Func: 123> " Link Cap1101123}\012    @{" DT_DUMP          <Func: 124> " Link Cap1101124}    @{" DT_TIMEOUT       <Func: 125> " Link Cap1101125}\012    @{" BB_CONFNAME      <Func: 126> " Link Cap1101126}    @{" BB_CONFLOCAL     <Func: 127> " Link Cap1101127}\012    @{" BB_LOCAL         <Func: 128> " Link Cap1101128}    @{" BB_STATUS        <Func: 129> " Link Cap1101129}\012    @{" BB_MAINLINE      <Func: 131> " Link Cap1101131}    @{" RETURNCOMMAND    <Func: 136> " Link Cap1101136}\012    @{" ZMODEMSEND       <Func: 137> " Link Cap1101137}    @{" ZMODEMRECEIVE    <Func: 138> " Link Cap1101138}\012    @{" SCREEN_ADDRESS   <Func: 139> " Link Cap1101139}    @{" BB_TASKPRI       <Func: 140> " Link Cap1101140}\012    @{" RAWSCREEN_ADDRESS<Func: 141> " Link Cap1101141}    @{" BB_CHATFLAG      <Func: 142> " Link Cap1101142}\012    @{" DT_STAMP_LASTON  <Func: 143> " Link Cap1101143}    @{" DT_STAMP_CTIME   <Func: 144> " Link Cap1101144}\012    @{" DT_CURR_TIME     <Func: 145> " Link Cap1101145}    @{" DT_CONFACCESS    <Func: 146> " Link Cap1101146}\012    @{" BB_NODEID        <Func: 149> " Link Cap1101149}    @{" BB_CALLERSLOG    <Func: 150> " Link Cap1101150}\012    @{" BB_UDLOG         <Func: 151> " Link Cap1101151}    @{" EXPRESS_VERSION  <Func: 152> " Link Cap1101152}\012    @{" BB_CHATSET       <Func: 162> " Link Cap1101162}    @{" ENVSTAT          <Func: 163> " Link Cap1101163}\012    @{" NODE_DEVICE      <Func: 503> " Link Cap1101503}    @{" NODE_UNIT        <Func: 504> " Link Cap1101504}\012    @{" NODE_BAUD        <Func: 505> " Link Cap1101505}    @{" JH_MCI           <Func: 507> " Link Cap1101507}\012    @{" PRV_COMMAND      <Func: 508> " Link Cap1101508}    @{" BB_CONFNUM       <Func: 510> " Link Cap1101510}\012    @{" BB_DROPDTR       <Func: 511> " Link Cap1101511}    @{" BB_GETTASK       <Func: 512> " Link Cap1101512}\012    @{" NODE_BAUDRATE    <Func: 516> " Link Cap1101516}    @{" BB_LOGONTYPE     <Func: 517> " Link Cap1101517}\012    @{" BB_SCRLEFT       <Func: 518> " Link Cap1101518}    @{" BB_SCRTOP        <Func: 519> " Link Cap1101519}\012    @{" BB_SCRWIDTH      <Func: 520> " Link Cap1101520}    @{" BB_SCRHEIGHT     <Func: 521> " Link Cap1101521}\012    @{" BB_PURGELIN      <Func: 522> " Link Cap1101522}    @{" BB_PURGELINESTART<Func: 523> " Link Cap1101523}\012    @{" BB_PURGELINEEND  <Func: 524> " Link Cap1101524}    @{" BB_NONSTOPTEXT   <Func: 525> " Link Cap1101525}\012    @{" BB_LINECOUNT     <Func: 526> " Link Cap1101526}    @{" DT_LANGUAGE      <Func: 527> " Link Cap1101527}\012    @{" DT_QUICKFLAG     <Func: 528> " Link Cap1101528}    @{" DT_GOODFILE      <Func: 529> " Link Cap1101529}\012\012    Below are functions that are System-X specific and DO NOT work under\012                     AmiExpress or any AmiExpress clones.\012\012    @{" SX_PS           <Func: 1500> " Link SX_PS}    @{" SX_USERPO       <Func: 1501> " Link SX_USERPO}\012    @{" SX_USERPO2      <Func: 1502> " Link SX_USERPO2}    @{" SX_USERPO3      <Func: 1503> " Link SX_USERPO3}\012    @{" SX_VER          <Func: 1504> " Link SX_VER}    @{" SX_NODES        <Func: 1505> " Link SX_NODES}\012    @{" SX_FUNCTION     <Func: 1506> " Link SX_FUNCTION}\012\012@endnode\012@node Cap1101000 "JH_LI             <Func: 000>"\012\012JH_LI          Requests a string of information from the user with a\012               default string.\012\012               msg->Command = 0\012               msg->String  = default result string\012               msg->Data    = Maximum length of response.\012\012               msg->Data will be set to a -1 if a loss carrier or console\012               TIMEOUT occurs, otherwise MSG->Data will be 1\012\012               msg->String will be the response string from the user.\012(FUNCTION #: 0 )\012\012@endnode\012@node Cap1101001 "JH_REGISTER       <Func: 001>"\012\012JH_REGISTER    Registers a door or XIM with the current node.\012\012               msg->Command = 1\012\012               This must be the first command issued to the express node.\012               This increments the number of doors active for the current\012               node.\012(FUNCTION #: 1 )\012\012@endnode\012@node Cap1101002 "JH_SHUTDOWN       <Func: 002>"\012\012JH_SHUTDOWN   Tells the node that a door is shutting down, this decreases\012              the number of active doors indicator , which once at 0,\012              the AEDoorPort will close.\012\012              msg->Command = 2\012              msg->Data    = N/A\012(FUNCTION #: 2 )\012\012@endnode\012@node Cap1101003 "JH_WRITE          <Func: 003>"\012\012JH_WRITE        Allows you to send a text string to the user.\012\012                msg->Command = 3\012                msg->String  = text\012                msg->Data    = N/A\012(FUNCTION #: 3 )\012\012@endnode\012@node Cap1101004 "JH_SM             <Func: 004>"\012\012JH_SM           Allows you to send a text string to the user.\012\012                msg->Command = 4\012                msg->String  = text\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then a CR/LF combination will be sent.\012(FUNCTION #: 4 )\012\012@endnode\012@node Cap1101005 "JH_PM             <Func: 005>"\012\012JH_PM           Allows you to prompt the user for a specified number of\012                characters.\012\012                msg->Command = 5\012                msg->String  = prompt string\012                msg->Data    = maximum response length.\012\012                if msg->Data = -1, then a loss carrier has occurred or a\012                TIMEOUT condition has occurred, otherwise msg->Data = 1.\012\012                msg->String will be the user response.\012(FUNCTION #: 5 )\012\012@endnode\012@node Cap1101006 "JH_HK              <Func: 006>"\012\012JH_HK           Allows you to get a 1 character response from the user.\012\012                msg->Command = 6\012                msg->String  = text\012                msg->Data    = N/A\012\012                if msg->Data = -1, then a loss carrier has occurred or a\012                TIMEOUT condition has occurred, otherwise msg->Data = 1.\012\012                msg->String will be the result string.\012(FUNCTION #: 6 )\012\012@endnode\012@node Cap1101007 "JH_SG             <Func: 007>"\012\012JH_SG           Allows you to display a text file to the user.\012\012                msg->Command = 7\012                msg->String  = part file name.\012                msg->Data    = N/A\012\012                ie:\012\012                msg->String = "BBS:Node1/Bull\012\012                This would try to display BBS:Node1/BULL.TXT\012                also takes into account language specifications.\012\012                This also searches for the access level patterns, ie:\012\012                Bull10.TXT, Bull100.TXT\012(FUNCTION #: 7 )\012\012@endnode\012@node Cap1101008 "JH_SF             <Func: 008>"\012\012JH_SF           Allows you to display a text file to the user.\012\012                msg->Command = 8\012                msg->String  = Complete pathname\012                msg->Data    = N/A\012\012                ie:\012\012                msg->String  = "BBS:Node1/BULL.TXT"\012\012                This would show the file if it exists.\012(FUNCTION #: 8 )\012\012@endnode\012@node Cap1101009 "JH_EF             <Func: 009>"\012\012JH_EF          Allows you to use the internal msgbase editor to edit your\012               own files.\012\012               msg->Command = 9\012               msg->String  = Complete pathname\012               msg->Data    = 0\012\012               if msg->Data = -1, then a loss carrier has occurred or a\012               TIMEOUT has occurred, otherwise msg->Data will be 1.\012(FUNCTION #: 9 )\012\012@endnode\012@node Cap1101010 "JH_CO             <Func: 010>"\012\012JH_CO          Allows you to send text string to the console only.\012\012               msg->Command = 10\012               msg->String  = text\012               msg->Data    = 1 or 0\012\012               if msg->Data = 1, then a CR/LF combination will be sent in\012               addition to the text.\012(FUNCTION #: 10 )\012\012@endnode\012@node Cap1101011 "JH_BBSNAME        <Func: 011>"\012\012JH_BBSNAME      Allows you to retrieve the BBS Name.\012\012                msg->Command = 11\012                msg->Data    = N/A\012\012                msg->String will be the BBS name.\012(FUNCTION #: 11 )\012\012@endnode\012@node Cap1101012 "JH_SYSOP          <Func: 012>"\012\012JH_SYSOP        Allows you to retrieve the Sysop''s Name.\012\012                msg->Command = 12\012                msg->Data    = N/A\012\012                msg->String will be the Sysop name.\012(FUNCTION #: 12 )\012\012@endnode\012@node Cap1101013 "JH_FLAGFILE       <Func: 013>"\012\012JH_FLAGFILE     Allows you to add files to the list of flagged files.\012\012                msg->Command = 13\012                msg->String  = FileName\012                msg->Data    = N/A\012\012                Adds the msg->String to the list of flagged files for\012                downloading purposes,\012\012                NOTE: The files must be in the download path for this to\012                      work.\012(FUNCTION #: 13 )\012\012@endnode\012@node Cap1101100 "DT_NAME           <Func: 100>"\012\012DT_NAME         Allows you to retrieve or change users name/handle\012\012                msg->Command = 100\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be the name.\012                if msg->Data = 0, then name will be msg->String\012(FUNCTION #: 100 )\012\012@endnode\012@node Cap1101101 "DT_PASSWORD       <Func: 101>"\012\012DT_PASSWORD     Allows you to retrieve or change users password\012\012                msg->Command = 101\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be the password.\012                if msg->Data = 0, then the password will be msg->String.\012(FUNCTION #: 101 )\012\012@endnode\012@node Cap1101102 "DT_LOCATION      <Func: 102>"\012\012DT_LOCATION     Allows you to retrieve or change users location\012\012                msg->Command = 102\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be the location\012                if msg->Data = 0, then the location will be msg->String\012(FUNCTION #: 102 )\012\012@endnode\012@node Cap1101103 "DT_PHONENUMBER    <Func: 103>"\012\012DT_PHONENUMBER  Allows you to retrieve or change users phone number.\012\012               msg->Command = 103\012               msg->Data    = 1 or 0\012\012               if msg->Data = 1, then msg->String will be the phonenumber\012               if msg->Data = 0, ten phonenumber will be msg->String\012(FUNCTION #: 103 )\012\012@endnode\012@node Cap1101104 "DT_SLOTNUMBER     <Func: 104>"\012\012DT_SLOTNUMBER  Allows you to retrieve users slot number\012\012               msg->Command = 104\012               msg->Data    = 1\012\012               if msg->Data = 1, then msg->String will be the SLOTNUMBER.\012(FUNCTION #: 104 )\012\012@endnode\012@node Cap1101105 "DT_ACCESSLEVEL    <Func: 105>"\012\012DT_ACCESSLEVEL  Allows you to retrieve or change users access level.\012\012                msg->Command = 105\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be ACCESSLEVEL.\012                if msg->Data = 0, then ACCESSLEVEL will be msg->String.\012(FUNCTION #: 105 )\012\012@endnode\012@node Cap1101106 "DT_RATIOTYPE      <Func: 106>"\012\012DT_RATIOTYPE    Allows you to retrieve or change users RatioType\012\012                msg->Command = 106\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be RatioType.\012                if msg->Data = 0, then RatioType will be msg->String.\012(FUNCTION #: 106 )\012\012@endnode\012@node Cap1101107 "DT_RATIO          <Func: 107>"\012\012DT_RATIO        Allows you to retrieve or change users ratio\012\012                msg->Command = 107\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be ratio.\012                if msg->Data = 0, then ratio will be msg->String.\012(FUNCTION #: 107 )\012\012@endnode\012@node Cap1101108 "DT_COMPTYPE       <Func: 108>"\012\012DT_COMPTYPE     Allows you to retrieve or change users ComputerTypes code\012\012                msg->Command = 108\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be ComputerTypes.\012                if msg->Data = 0, then ComputerTypes will be msg->String.\012(FUNCTION #: 108 )\012\012@endnode\012@node Cap1101109 "DT_MESSAGESPOSTED <Func: 109>"\012\012DT_MESSAGESPOSTED Allows you to retrieve or change users MESSAGESPOSTED\012\012               msg->Command = 109\012               msg->Data    = 1 or 0\012\012               if msg->Data = 1, then msg->String will be MESSAGESPOSTED.\012               if msg->Data = 0, then MESSAGESPOSTED will be msg->String.\012(FUNCTION #: 109 )\012\012@endnode\012@node Cap1101110 "DT_UPLOADS        <Func: 110>"\012\012DT_UPLOADS      Allows you to retrieve or change number of UserUploads.\012\012                msg->Command = 110\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be uploads.\012                if msg->Data = 0, then uploads will be msg->String.\012(FUNCTION #: 110 )\012\012@endnode\012@node Cap1101111 "DT_DOWNLOADS      <Func: 111>"\012\012DT_DOWNLOADS   Allows you to retrieve or change number of UserDownloads.\012\012                msg->Command = 111\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be downloads.\012                if msg->Data = 0, then downloads will be msg->String.\012(FUNCTION #: 111 )\012\012@endnode\012@node Cap1101112 "DT_TIMESCALLED    <Func: 112>"\012\012DT_TIMESCALLED  Allows you to retrieve or change number of UserCalls.\012\012                msg->Command = 112\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be TIMESCALLED.\012                if msg->Data = 0, then TIMESCALLED will be msg->String.\012(FUNCTION #: 112 )\012\012@endnode\012@node Cap1101113 "DT_TIMELASTON     <Func: 113>"\012\012DT_TIMELASTON   Allows you to retrieve or change time user last called.\012\012                msg->Command = 113\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be TIMESCALLED.\012                if msg->Data = 0, then TIMESCALLED will be msg->String.\012\012                NOTE: This is not a date stamp, this is the number of\012                      seconds since January 19something.\012(FUNCTION #: 113 )\012\012@endnode\012@node Cap1101114 "DT_TIMEUSED       <Func: 114>"\012\012DT_TIMEUSED     Allows you to retrieve or change TIMEUSED today.\012\012                msg->Command = 114\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be TIMEUSED.\012                if msg->Data = 0, then TIMEUSED will be msg->String.\012\012                NOTE: This is in seconds.\012(FUNCTION #: 114 )\012\012@endnode\012@node Cap1101115 "DT_TIMELIMIT      <Func: 115>"\012\012DT_TIMELIMIT    Allows you to retrieve or change TimeAllowed for a user.\012\012                msg->Command = 115\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be TIMELIMIT.\012                if msg->Data = 0, then TIMELIMIT will be msg->String.\012\012                NOTE: Time in seconds.\012(FUNCTION #: 115 )\012\012@endnode\012@node Cap1101116 "DT_TIMETOTAL      <Func: 116>"\012\012DT_TIMETOTAL   Allows you to retrieve or change total time remaining.\012               for a user today.\012\012               msg->Command = 116\012               msg->Data    = 1 or 0\012\012               if msg->Data = 1, then msg->String will be time remaining.\012               if msg->Data = 0, then time remaining will be msg->String.\012\012               NOTE: Time in seconds.\012(FUNCTION #: 116 )\012\012@endnode\012@node Cap1101117 "DT_BYTESUPLOAD    <Func: 117>"\012\012DT_BYTESUPLOAD  Allows you to retrieve or change bytes uploads per user.\012\012                msg->Command = 117\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be BYTESUPLOADED.\012                if msg->Data = 0, then BYTESUPLOADED will be msg->String.\012(FUNCTION #: 117 )\012\012@endnode\012@node Cap1101118 "DT_BYTEDOWNLOAD   <Func: 118>"\012\012DT_BYTEDOWNLOAD Allows you to retrieve or change bytes downloaded per\012                user.\012\012               msg->Command = 118\012               msg->Data    = 1 or 0\012\012               if msg->Data = 1, then msg->String will be BYTESDOWNLOADED.\012               if msg->Data = 0, then BYTESDOWNLOADED will be msg->String.\012(FUNCTION #: 118 )\012\012@endnode\012@node Cap1101119 "DT_DAILYBYTELIMIT <Func: 119>"\012\012DT_DAILYBYTELIMIT Allows you to retrieve or change a users daily byte\012                  download limit.\012\012                  msg->Command = 119\012                  msg->Data    = 1 or 0\012\012                  if msg->Data = 1, then msg->String will be bytelimit.\012                  if msg->Data = 0, then bytelimit will be msg->String.\012(FUNCTION #: 119 )\012\012@endnode\012@node Cap1101120 "DT_DAILYBYTEDLD   <Func: 120>"\012\012DT_DAILYBYTEDLD Allows you to retrieve or change daily bytes downloaded.\012\012                msg->Command = 120\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be dailybytes.\012                if msg->Data = 0, then dailybytes will be msg->String.\012(FUNCTION #: 120 )\012\012@endnode\012@node Cap1101121 "DT_EXPERT         <Func: 121>"\012\012DT_EXPERT         Allows you to retrieve or change expert mode.\012\012                  msg->Command = 121\012                  msg->Data    = 1 or 0\012(FUNCTION #: 121 )\012\012@endnode\012@node Cap1101122 "DT_LINELENGTH     <Func: 122>"\012\012DT_LINELENGTH     Allows you to retrieve or change user LINELENGTH specs.\012\012                  msg->Command = 122\012                  msg->Data    = 1 or 0\012\012                  if msg->Data = 1, then msg->String will be LINELENGTH.\012                  if msg->Data = 0, then LINELENGTH will be msg->String.\012(FUNCTION #: 122 )\012\012@endnode\012@node Cap1101123 "ACTIVE_NODES      <Func: 123>"\012\012ACTIVE_NODES    Allows you to retrieve a string of active&inactive nodes.\012\012                msg->Command = 123\012                msg->Data    = N/A\012\012                msg->String will be a string 10 bytes in length, with\012                     ''X''s marking the active nodes.\012\012                NOTE: This command will surely be changing, the current\012                      limit is 9 nodes.\012(FUNCTION #: 123 )\012\012@endnode\012@node Cap1101124 "DT_DUMP           <Func: 124>"\012\012DT_DUMP           Allows you to dump the user''s data structure to a\012                  specified file.\012\012                  msg->Command = 124\012                  msg->String  = FileName\012(FUNCTION #: 124 )\012\012@endnode\012@node Cap1101125 "DT_TIMEOUT        <Func: 125>"\012\012DT_TIMEOUT       Allows you to retrieve or change the door TIMEOUT limit.\012\012                 msg->Command = 125\012                 msg->Data    = 1 or 0\012\012                 if msg->Data = 1, then msg->String will equal TIMEOUT.\012                 if msg->Data = 0, then TIMEOUT will equal msg->String.\012\012                 NOTE: This time is in seconds.\012(FUNCTION #: 125 )\012\012@endnode\012@node Cap1101126 "BB_CONFNAME       <Func: 126>"\012\012BB_CONFNAME       Allows you to retrieve or change the conference name.\012\012                  msg->Command = 126\012                  msg->Data    = 1 or 0\012\012                  if msg->Data = 1, then msg->String will be name.\012                  if msg->Data = 0, then name will be msg->String.\012(FUNCTION #: 126 )\012\012@endnode\012@node Cap1101127 "BB_CONFLOCAL      <Func: 127>"\012\012BB_CONFLOCAL    Allows you to retrieve or change the conference location.\012\012                msg->Command = 127\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be location.\012                if msg->Data = 0, then location will be msg->String.\012(FUNCTION #: 127 )\012\012@endnode\012@node Cap1101128 "BB_LOCAL          <Func: 128>"\012\012BB_LOCAL          Allows you to retrieve the current BBS location.\012\012                  msg->Command = 128\012                  msg->Data    = N/A\012(FUNCTION #: 128 )\012\012@endnode\012@node Cap1101129 "BB_STATUS         <Func: 129>"\012\012BB_STATUS         Allows you to retrieve the current status of the node.\012\012                  msg->Command = 129\012                  msg->Data    = N/A\012\012                  msg->String will be ''OFFLINE'' or ''ONLINE'' depending on\012                  whether a user is logged onto the node.\012(FUNCTION #: 129 )\012\012@endnode\012@node Cap1101131 "BB_MAINLINE       <Func: 131>"\012\012BB_MAINLINE     Allows you to retrieve the menu prompt arguments prior to\012                the door being entered.\012\012                msg->Command = 131\012                msg->Data    = N/A\012\012                msg->String will be the menu prompt arguments.\012(FUNCTION #: 131 )\012\012@endnode\012@node Cap1101136 "RETURNCOMMAND     <Func: 136>"\012\012RETURNCOMMAND    Allows you to specify an internal command to be executed\012                 when the door is finished.\012\012                 msg->Command = 136\012                 msg->Data    = N/A\012\012                 command to be executed will be msg->String.\012(FUNCTION #: 136 )\012\012@endnode\012@node Cap1101137 "ZMODEMSEND        <Func: 137>"\012\012ZMODEMSEND      Allows you to send files to the user via Zmodem protocol.\012\012                msg->Command = 137\012                msg->String  = filename (complete pathname)\012                msg->Data    = N/A\012\012                result of transfer will be in msg->Data, where\012\012                if msg->Data = 1 , then transfer successful.\012                if msg->Data = -2, then user lost carrier.\012                if msg->Data = 0 , then transfer unsuccessful.\012(FUNCTION #: 137 )\012\012@endnode\012@node Cap1101138 "ZMODEMRECEIVE     <Func: 138>"\012\012ZMODEMRECEIVE    Allows you to receive batch uploads via Zmodem protocol.\012\012                 msg->Command = 138\012                 msg->String  = receive directory path\012                 msg->Data    = N/A\012\012                 result of transfer will be in msg->Data, where\012\012                 if msg->Data = 1 , then transfer successful.\012                 if msg->Data = -2, then user lost carrier.\012                 if msg->Data = 0,  then transfer unsuccessful.\012(FUNCTION #: 138 )\012\012@endnode\012@node Cap1101139 "SCREEN_ADDRESS    <Func: 139>"\012\012SCREEN_ADDRESS    Allows you to retrieve the screen address.\012\012                  msg->Command = 139\012                  msg->Data    = N/A\012\012                  msg->String will be a string containing the hexadecimal\012                  address of the Node screen.\012(FUNCTION #: 139 )\012\012@endnode\012@node Cap1101140 "BB_TASKPRI        <Func: 140>"\012\012BB_TASKPRI    Allows you to retrieve the priority the node is running at.\012\012              msg->Command = 140\012              msg->Data    = N/A\012\012              msg->String will contain the priority of the node.\012(FUNCTION #: 140 )\012\012@endnode\012@node Cap1101141 "RAWSCREEN_ADDRESS <Func: 141>"\012\012RAWSCREEN_ADDRESS Allows you to retrieve the screen address of the node.\012\012              msg->Command = 141\012              msg->Data    = N/A\012\012              msg->String will be a string containing the decimal address\012                   of the express node.\012(FUNCTION #: 141 )\012\012@endnode\012@node Cap1101142 "BB_CHATFLAG       <Func: 142>"\012\012BB_CHATFLAG       Allows you to retrieve the current chat setting.\012\012                  msg->Command = 142\012                  msg->Data    = N/A\012\012                  msg->String will be "ON" or "OFF".\012(FUNCTION #: 142 )\012\012@endnode\012@node Cap1101143 "DT_STAMP_LASTON   <Func: 143>"\012\012DT_STAMP_LASTON Allows you to retrieve a date string containing the date\012                of when the user last logged on.\012\012                msg->Command = 143\012                msg->Data    = N/A\012\012                msg->String will be the date string.\012(FUNCTION #: 143 )\012\012@endnode\012@node Cap1101144 "DT_STAMP_CTIME    <Func: 144>"\012\012DT_STAMP_CTIME    Allows you to retrieve a current time string.\012\012                  msg->Command = 144\012                  msg->Data    = N/A\012\012                  msg->String will be a current time string.\012(FUNCTION #: 144 )\012\012@endnode\012@node Cap1101145 "DT_CURR_TIME      <Func: 145>"\012\012DT_CURR_TIME     Allows you to retrieve the current time in seconds since\012                 January something.\012\012                 msg->Command = 145\012                 msg->Data    = N/A\012\012                 msg->String will be the current time.\012(FUNCTION #: 145 )\012\012@endnode\012@node Cap1101146 "DT_CONFACCESS     <Func: 146>"\012\012DT_CONFACCESS     Allows you to retrieve the users conference access.\012\012                  msg->Command = 146\012                  msg->Data    = 1 or 0\012\012                  if msg->Data = 1, then msg->String will be AREANAME.\012                  if msg->Data = 0, then AREANAME will be msg->String.\012\012(FUNCTION #: 146 )\012\012@endnode\012@node Cap1101149 "BB_NODEID         <Func: 149>"\012\012BB_NODEID         Allows you to retrieve the Node number for the current\012                  node\012\012                  msg->Command = 149\012                  msg->Data    = N/A\012\012                  msg->String will be the node number.\012(FUNCTION #: 149 )\012\012@endnode\012@node Cap1101150 "BB_CALLERSLOG     <Func: 150>"\012\012BB_CALLERSLOG     Allows you to add a line of text to the CALLERSLOG.\012\012                  msg->Command = 150\012                  msg->String  = text\012                  msg->Data    = N/A\012(FUNCTION #: 150 )\012\012@endnode\012@node Cap1101151 "BB_UDLOG          <Func: 151>"\012\012BB_UDLOG          Allows you to add a line of text to the UDLOG.\012\012                  msg->Command = 151\012                  msg->String  = text\012                  msg->Data    = N/A\012(FUNCTION #: 151 )\012\012@endnode\012@node Cap1101152 "EXPRESS_VERSION   <Func: 152>"\012\012EXPRESS_VERSION   Allows you to retrieve the current version string of\012                  express.\012\012                  msg->Command = 152\012                  msg->Data    = N/A\012(FUNCTION #: 152 )\012\012@endnode\012@node Cap1101162 "BB_CHATSET        <Func: 162>"\012\012BB_CHATSET     Allows you to retrieve or change the chat status.\012\012               msg->Command = 162\012               msg->Data    = 1 or 0\012\012               if msg->Data = 1, then msg->String will be current status.\012               if msg->Data = 0, then status will be msg->String.\012(FUNCTION #: 162 )\012\012@endnode\012@node Cap1101163 "ENVSTAT           <Func: 163>"\012\012ENVSTAT          Allows you to retrieve or change the current environment\012                 stat variable code.\012\012                 msg->Command = 163\012                 msg->Data    = 1 or 0\012\012                 if msg->Data = 1, then msg->String will be status.\012                 if msg->Data = 0, then status will be msg->String.\012(FUNCTION #: 163 )\012\012@endnode\012@node Cap1101503 "NODE_DEVICE       <Func: 503>"\012\012NODE_DEVICE       Allows you to retrieve the node device name.\012\012                  msg->Command = 503\012                  msg->Data    = N/A\012\012                  msg->String will be the device string.\012(FUNCTION #: 503 )\012\012@endnode\012@node Cap1101504 "NODE_UNIT         <Func: 504>"\012\012NODE_UNIT         Allows you to retrieve the node unit number.\012\012                  msg->Command = 504\012                  msg->Data    = N/A\012\012                  msg->String will be the current node number.\012(FUNCTION #: 504 )\012\012@endnode\012@node Cap1101505 "NODE_BAUD         <Func: 505>"\012\012NODE_BAUD    Allows you to retrieve the initialized baud rate of the node.\012\012             msg->Command = 505\012             msg->Data    = N/A\012\012             msg->String will be the INIT baud rate.\012(FUNCTION #: 505 )\012\012@endnode\012@node Cap1101507 "JH_MCI            <Func: 507>"\012\012JH_MCI            Allows you to send MCI text to express.\012\012                  msg->Command = 507\012                  msg->String  = text\012                  msg->Data    = N/A\012(FUNCTION #: 507 )\012\012@endnode\012@node Cap1101508 "PRV_COMMAND       <Func: 508>"\012\012PRV_COMMAND       Allows you to immediately execute an internal express\012                  menu command.\012\012                  msg->Command = 508\012                  msg->String  = commandstring\012                  msg->Data    = N/A\012(FUNCTION #: 508 )\012\012@endnode\012@node Cap1101510 "BB_CONFNUM        <Func: 510>"\012\012BB_CONFNUM     Allows you to retrieve the current conference number.\012\012               msg->Command = 510\012               msg->Data    = N/A\012\012               msg->String will be conference number ranging from 0 to 8.\012(FUNCTION #: 510 )\012\012@endnode\012@node Cap1101511 "BB_DROPDTR        <Func: 511>"\012\012BB_DROPDTR        Allows you to drop carrier on a user.\012\012                  msg->Command = 511\012                  msg->Data    = N/A\012(FUNCTION #: 511 )\012\012@endnode\012@node Cap1101512 "BB_GETTASK        <Func: 512>"\012\012BB_GETTASK        Finds the current nodes task address.\012\012                  msg->Command = 512\012                  msg->Data    = N/A\012\012                  msg->task will be the express task address.\012(FUNCTION #: 512 )\012\012@endnode\012@node Cap1101516 "NODE_BAUDRATE     <Func: 516>"\012\012NODE_BAUDRATE     Allows you to retrieve the current users connect rate\012\012                  msg->Command = 516\012                  msg->Data    = N/A\012\012                  msg->String will be the connect rate\012(FUNCTION #: 516 )\012\012@endnode\012@node Cap1101517 "BB_LOGONTYPE      <Func: 517>"\012\012BB_LOGONTYPE      Allows you to retrieve the LOGONTYPE.\012\012                  msg->Command = 517\012                  msg->Data    = N/A\012\012                  msg->Data will be:\012\012                  0 = AWAIT_LOGON\012                  1 = SYSOP_LOGON\012                  2 = LOCAL_LOGON\012                  3 = REMOTE_LOGON\012(FUNCTION #: 517 )\012\012@endnode\012@node Cap1101518 "BB_SCRLEFT        <Func: 518>"\012\012BB_SCRLEFT      Allows you to retrieve the screen coordinates.\012\012                msg->Command = 518\012                msg->Data    = N/A\012\012                msg->Data will be the Node''s Initial LEFTEDGE coordinate.\012(FUNCTION #: 518 )\012\012@endnode\012@node Cap1101519 "BB_SCRTOP         <Func: 519>"\012\012BB_SCRTOP        Allows you to retrieve the screen coordinates.\012\012                 msg->Command = 519\012                 msg->Data    = N/A\012\012                 msg->Data will be the Node''s Initial TOPEDGE coordinate.\012(FUNCTION #: 519 )\012\012@endnode\012@node Cap1101520 "BB_SCRWIDTH       <Func: 520>"\012\012BB_SCRWIDTH       Allows you to retrieve the screen coordinates.\012\012                  msg->Command = 520\012                  msg->Data    = N/A\012\012                  msg->Data will be the Node''s Initial screen height.\012(FUNCTION #: 520 )\012\012@endnode\012@node Cap1101521 "BB_SCRHEIGHT      <Func: 521>"\012\012BB_SCRHEIGHT      Allows you to retrieve the screen coordinates.\012\012                  msg->Command = 521\012                  msg->Data    = N/A\012\012                  msg->Data will be the Node''s Initial screen width.\012(FUNCTION #: 521 )\012\012@endnode\012@node Cap1101522 "BB_PURGELIN       <Func: 522>"\012\012BB_PURGELIN   Allows you to abort serial input.\012\012               msg->Command = 522\012               msg->Data    = N/A\012\012              aborts serial input and flushes the serial buffer and sends\012              a request for more input.\012(FUNCTION #: 522 )\012\012@endnode\012@node Cap1101523 "BB_PURGELINESTART <Func: 523>"\012\012BB_PURGELINESTART Allows you to CLEAR the serial buffer and request more\012                  serial input.\012\012                  msg->Command = 523\012                  msg->Data    = N/A\012(FUNCTION #: 523 )\012\012@endnode\012@node Cap1101524 "BB_PURGELINEEND   <Func: 524>"\012\012BB_PURGELINEEND   Allows you to CLEAR the serial buffer.\012\012                  msg->Command = 524\012                  msg->Data    = N/A\012(FUNCTION #: 524 )\012\012@endnode\012@node Cap1101525 "BB_NONSTOPTEXT    <Func: 525>"\012\012BB_NONSTOPTEXT    Allows you to change the NONSTOP text scrolling flag.\012\012                  msg->Command = 525\012                  msg->Data    = 1 or 0\012\012                  if msg->Data = 1, then display text will not pause.\012                  if msg->Data = 0, then display text will pause.\012(FUNCTION #: 525 )\012\012@endnode\012@node Cap1101526 "BB_LINECOUNT      <Func: 526>"\012\012BB_LINECOUNT   Allows you to retrieve or change the user''s current number\012               of lines viewed.\012\012               msg->Command = 526\012               msg->Data    = 1 or 0\012\012               if msg->Data = 1, then msg->String will be current line.\012               if msg->Data = 0, then current line will be msg->String.\012(FUNCTION #: 526 )\012\012@endnode\012@node Cap1101527 "DT_LANGUAGE       <Func: 527>"\012\012DT_LANGUAGE      Allows you to retrieve or change the current language\012                 specifications.\012\012                 msg->Command = 527\012                 msg->Data    = 1 or 0\012\012                 if msg->Data = 1, then msg->String will be language.\012                 if msg->Data = 0, then language will be msg->String.\012\012                NOTE: Languages need to be standardized, please what for\012                      guidelines.\012\012                ie:  Default language .TXT\012                     English          .ENG\012                     German           .GER\012\012                     note that this only effects the menus, bulletins &\012                     other screen text files.\012(FUNCTION #: 527 )\012\012@endnode\012@node Cap1101528 "DT_QUICKFLAG      <Func: 528>"\012\012DT_QUICKFLAG      Allows you to change the QUICKTEXT flag.\012\012                  msg->Command = 528\012                  msg->Data    = 1 or 0\012\012                  if msg->Data = 1, then the QuickFlag will be set.\012                  if msg->Data = 0, then the QuickFlag will not be set.\012(FUNCTION #: 528 )\012\012@endnode\012@node Cap1101529 "DT_GOODFILE       <Func: 529>"\012\012DT_GOODFILE       Allows you to set the results of a tested file after\012                  upload.\012\012                  msg->Command = 529\012                  msg->Data    = 1,0 or -1\012\012                  if msg->Data is 1, then the file was not tested.\012                  if msg->Data is 0, then the file passed the filetest.\012                  if msg->Data is -1, then the file failed the filetest.\012\012                  NOTE: This command is only useful with the SYSCmd door\012                  called FILECHECK.\012(FUNCTION #: 529 )\012\012@endnode\012@node SX_PS "System-X Only Print String"\012\012SX_PS		Prints a string to the console/serial port.\012\012		msg->Command = 1500\012		msg->Data    = pointer to a string\012\012\012		Note: no copying required and no length limit!\012\012\012(FUNCTION #: 1500 )\012@endnode\012@node SX_USERPO "Get UserStruct Pointer (UserData)"\012\012SX_USERPO	Gives you the pointer to the User structure\012\012		msg->Command = 1501\012\012\012		returns the pointer in msg->Data\012\012(FUNCTION #: 1501 )\012@endnode\012@node SX_USERPO2 "Get UserStruct Pointer (SXUser)"\012\012SX_USERPO2	Gives you the pointer to the SXUser structure\012\012		msg->Command = 1502\012\012\012		returns the pointer in msg->Data\012\012(FUNCTION #: 1502 )\012@endnode\012@node SX_USERPO3 "Get UserStruct Pointer (Index)"\012\012SX_USERPO3	Gives you the pointer to the User Index structure\012\012		msg->Command = 1503\012\012\012		returns the pointer in msg->Data\012\012(FUNCTION #: 1503 )\012@endnode\012\012@node SX_VER "Get the System-X version"\012\012SX_VER		Gives you the version of SX\012\012		msg->Command = 1504\012\012		returns it in msg->String, eg: "1.00"\012\012(FUNCTION #: 1504 )\012@endnode\012@node SX_NODES "Get a pointer to the node structures"\012\012SX_NODES	Get a pointer to the node structures\012\012		msg->Command = 1505\012\012		returns it in msg->Data\012\012		For more information, see MCP Communication/Command 14.\012\012(FUNCTION #: 1505 )\012@endnode\012@node mcp "MCP"\012\012Communication with MCP is available through standard EXEC-MESSAGES.\012\012The structure of the message is (you must allocate it)\012\012struct MCPMessage\012{\012	struct Message Msg;\012	UWORD command;\012	UWORD nodenum;\012	long data1;\012	long data2;\012	long data3;\012	long data4;\012	long data5;\012	long data6;\012};\012\012UWORD''s are 16-bit\012long''s are 32-bit\012\012\012If anything but an actual node wants to use this port, you must make\012nodenum equal 0 (zero) (that includes doors!).\012\012\012.------------------------.\012| MCP Commands Available |\012`------------------------''\012\012	Note: Commands 1 to 5 are PRIVATE!!\012\012\012	6 - MENU POINTER\012\012		Ask MCP to give you a pointer to a menu structure\012\012		themsg.command = 6\012		themsg.data1   = pointer to the menu you want\012					eg: "Main_Menu"\012\012		returns\012\012		themsg.data2   = the pointer you wanted\012		themsg.data3   = size of the struct in bytes\012\012\012\012	8 - MD5 ENCRYPTION\012\012		This will ask MCP to encrypt a string for you, using MD5.\012\012		themsg.command = 8\012		themsg.data1   = pointer to the string to encrypt\012		themsg.data2   = pointer to 16 bytes to put the result in\012\012\012	10 - QUERY SYSOP\012\012		Find out if the sysop is available\012\012		themsg.command = 10\012\012		returns\012\012		themsg.data1   = pointer to the reason for being away\012				(if NULL, the sysop is available)\012\012\012	12 - APPEND TO A FILE\012\012		themsg.command = 12\012		themsg.data1   = pointer to the filename string\012		themsg.data2   = pointer to the buffer to append\012		themsg.data3   = size of the append buffer\012\012\012	14 - GET A POINTER TO THE NODE INFORMATION CHAIN\012\012		themsg.command = 14\012\012		returns\012\012		themsg.data1   = the pointer to node 1''s structure\012				(use the NEXT field to browse through)\012\012		the struct is as follows\012\012		struct node_struct\012		{					/* offset DEC	*/\012			APTR next;			/*	0	*/\012			struct UserData *User;		/*	4	*/\012			struct UserIndexStruct *UserIndex;/*	8	*/\012			struct SXUserStruct *SXUser;	/*	12	*/\012			char *action;			/*	16	*/\012			char *filename;			/*	20	*/\012			long baud;			/*	24	*/\012			long loginsecs;			/*	28	*/\012			UWORD number;			/*	32	*/\012			UBYTE actionnumber;		/*	34	*/\012			UBYTE active;			/*	35	*/\012			UBYTE useron;			/*	36	*/\012			UBYTE misc;			/*	37	*/\012		};\012\012.--------------------------------------.\012| Example ''C'' program using MCP''s port |\012`--------------------------------------''\012\012struct MCPMessage\012{\012	struct Message Msg;\012	UWORD command;\012	UWORD nodenum;\012	long data1;\012	long data2;\012	long data3;\012	long data4;\012	long data5;\012	long data6;\012};\012struct MCPMessage themsg;\012struct MsgPort *MyPort, *MCPPort;\012\012	MCPPort = FindPort("SX-MCP");\012	if(MCPPort)\012	{\012		MyPort = CreateMsgPort();\012		if(MyPort)\012		{\012			themsg.Msg.mn_Length = sizeof(struct MCPMessage);\012			themsg.Msg.mn_ReplyPort = MyPort;\012			themsg.nodenum = 0;\012			themsg.command = 10;	/* 10 = QUERY SYSOP */\012			PutMsg(MCPPort, (struct Message *)&themsg);\012			WaitPort(MyPort);\012			DeleteMsgPort(MyPort);\012			if(themsg.data1)\012			{\012				PutStr("The Sysop is away because:\n\n");\012				PutStr((char *)themsg.data1);\012				PutStr("\n");\012			} else {\012				PutStr("The Sysop is available!\n");\012			}\012		}\012	}\012@endnode\012@node SX_FUNCTION "Execute an internal SX Function"\012\012SX_FUNCTION	Execute an internal SX Function (sxfunctions.doc)\012\012		msg->data = pointer to this structure:\012\012struct SXFuncStruct\012{\012	UWORD	id;\012	char	*string;\012	UWORD	extra;\012	UWORD	low;\012	UWORD	high;\012	char	*mainarg;\012	char	*execarg;\012} *SXFunc;\012\012		Must must allocate this structure and fill in all\012		the fields, then pass it through msg->data.\012\012(FUNCTION #: 1506 )\012@endnode\012','\012',char(10)),NULL,'auto-added',450231,8,1,'Z','Doors/5D-ZippySearch','dcsxc100','scan',1780048474);
INSERT INTO door_catalog VALUES('dcsxm100','DCSXM100.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DCSXM100.LHA','5D-ZippySearch','XIM','5D-ZippySearch',NULL,'Menu/Hotkey',NULL,'____¦____  (   _____/__  - ------------- _/     ___/ _/\_  T     ¬\_ ·  diGiTAL   · .-\     ¦/    7--7  l       / · cORRUPTiON ·',replace('        .________________\n    ____¦____  (   _____/__  - -------------\n  _/     ___/ _/\_  T     ¬\_ ·  diGiTAL   ·\n.-\     ¦/    7--7  l       / · cORRUPTiON ·\n|  \____.-----¦  ¦----.____/------- -  -   -\n|              SYSTEM-X 1.00\n|  BBS Software featuring XPR Protocols,\n|  16 color ansi, 5 door types and more.\n|            (Menu/Hotkey Based Version)\n`-[10/06/97]---------------------------[Zed]\n','\n',char(10)),'Dev.GUIDE',replace('@database SXDEV\012@node MAIN "Developing Doors"\012\012		  DEVELOPING DOORS AND UTILS FOR SYSTEM-X\012\012		    @{" Structures associated with SX     " Link structs}\012		    @{" How the door port works in theory " Link port}\012		    @{" List of XIM functions available   " Link funcs}\012		    @{" Communication with MCP            " Link mcp}\012\012 .-----------------------------------------------------------------------.\012 | System-X uses the XIM door port as its primary door port. This means  |\012 | it''s compatable with AmiExpress. If you are intending to write a door |\012 | especially for System-X, use the XIM port, as it gives you the most   |\012 | power.                                                                |\012 `-----------------------------------------------------------------------''\012\012 Note: if you find any developer/starter packs around for AmiExpress, they\012       will work just fine with System-X. There are examples for AmigaE\012       and heaps of ASM examples around. Developing doors for SX can also\012       be done using any of the other door types, but XIM is the best for\012       SX (has the most commands available).\012@endnode\012@node structs "Structures"\012\012The structures are all in ''C'' format, but in general:\012\012WORD, short		=	16 bit signed word\012UWORD			=	16 bit unsigned word\012int, long, LONG		=	32 bit signed word\012ULONG			=	32 bit unsigned word\012APTR			=	32 bit pointer\012\012Any fields with an asterix "*" infront of them are pointers!\012\012\012.---------------------------------------.\012| User.data or User structure in memory |\012`---------------------------------------''\012\012struct UserData {\012	char	Name[31],\012		Pass[9],\012		Location[30],\012		PhoneNumber[13];\012	USHORT	Slot_Number;\012	USHORT	Sec_Status,		/* access level */\012		Sec_Board,		/* unused	*/\012		Sec_Library,		/* unused       */\012		Sec_Bulletin,		/* unused	*/\012		Messages_Posted;\012	ULONG	NewSinceDate,\012		ConfRead1,\012		ConfRead2,\012		ConfRead3,\012		ConfRead4,\012		ConfRead5,\012		ConfRead6,\012		ConfRead7,\012		ConfRead8,\012		ConfRead9;\012	char	Conference_Access[10];\012	USHORT	Uploads,\012		Downloads,\012		ConfRJoin,\012		Times_Called;\012	long	Time_Last_On,\012		Time_Used,\012		Time_Limit,\012		Time_Left;\012	ULONG	Bytes_Download,\012		Bytes_Upload,\012		Daily_Bytes_Limit,\012		Daily_Bytes_Dld;\012	char	Expert;\012	ULONG	ConfYM1,\012		ConfYM2,\012		ConfYM3,\012		ConfYM4,\012		ConfYM5,\012		ConfYM6,\012		ConfYM7,\012		ConfYM8,\012		ConfYM9;\012	long    BeginLogCall;\012	UBYTE	Protocol,\012		UUCPA,\012		LineLength,\012		New_User;\012	};\012\012.---------------------------------------------.\012| User.Index or UserIndex structure in memory |\012`---------------------------------------------''\012\012struct UserIndexStruct\012{\012	char handle[31];\012	char realname[31];\012	UWORD misc;\012};\012\012\012.---------------------------.\012| User.SX file or in memory |\012`---------------------------''\012\012struct SXUserStruct\012{\012	UWORD byteratio;\012	UWORD fileratio;\012	ULONG flags;\012	UWORD freefiles;\012	ULONG freebytes;\012	ULONG ConfAccess[10];\012	UWORD lastfilearea;\012	char computer[24];\012	char sentbyline[46];\012	char password[16];\012	long firstcall;\012	char reserved[110];\012};\012\012\012.-----------------.\012| Prefs/Confs.DAT |\012`-----------------''\012\012struct ConfStruct\012{\012	char name[45];\012	char path[55];\012	char pass[16];\012	char filepath[52];\012	UWORD fileareas;\012	UWORD uploadarea;\012	UBYTE flf;\012	UBYTE flags;\012	char reserve[82];\012};\012\012\012.------------------.\012| Prefs/Serial.DAT |\012`------------------''\012\012struct SerialStruct\012{\012	char device[32];\012	WORD unit;\012	WORD misc;\012	long minrate;\012	long dcerate;\012	UBYTE sevenwire;\012	UBYTE shared;\012	char ring[16];\012	char connect[24];\012	char answer[16];\012	char initstr[48];\012};\012\012\012.-------------------.\012| SX:Prefs/Main.DAT |\012`-------------------''\012\012struct MainStruct\012{\012	char BBSName[64];\012	char BBSPath[64];\012	char BBSLoc[64];\012	char Sysop[64];\012	char DNPath[64];\012	char ULPath[64];\012	long nodes;\012};\012\012.---------------------------------------.\012| SX:LogFiles/Download.LOG & Upload.LOG |\012`---------------------------------------''\012\012struct XferLog\012{\012	UWORD	user_slot;\012	UBYTE	conf,\012		filearea;\012	char	filename[32];\012	long	size,\012		baud,\012		cps,\012		time;\012	UBYTE	node;\012	char	res[7];\012} Xfer;\012\012\012.-------------------------.\012| SX:LogFiles/Callers.LOG |\012`-------------------------''\012\012Note: this file has a UWORD at the top before the first structure, which\012is a pointer to the oldest entry in the log. (its a rotary log of 30)\012\012struct CallerLog\012{\012	UWORD	user_slot,\012		node;\012	long	time_login,\012		time_logout,\012		seconds_online,\012		bytes_uploaded,\012		bytes_downloaded;\012	UWORD	files_uploaded,\012		files_downloaded,\012		messages;\012	long	baud,\012		flags;\012	UBYTE	logout_mode;\012	char	res[25];\012};\012\012\012.----------------------------------------------------------------.\012| NODE STRUCTURE AS PASSED BY MCP-COMMAND-14 OR XIM-COMMAND-1505 |\012`----------------------------------------------------------------''\012\012struct node_struct\012{						/* offset DEC	*/\012	APTR next;				/*	0	*/\012	struct UserData *User;			/*	4	*/\012	struct UserIndexStruct *UserIndex;	/*	8	*/\012	struct SXUserStruct *SXUser;		/*	12	*/\012	char *action;				/*	16	*/\012	char *filename;				/*	20	*/\012	long baud;				/*	24	*/\012	long loginsecs;				/*	28	*/\012	UWORD number;				/*	32	*/\012	UBYTE actionnumber;			/*	34	*/\012	UBYTE active;				/*	35	*/\012	UBYTE useron;				/*	36	*/\012	UBYTE misc;				/*	37	*/\012};\012\012@endnode\012@node port "Door Port"\012\012There are two ways to program doors for System-X. One is to use\012AEDoor.library, which is very easy, and the other is to use exec\012messages, which gives more control. Below is explained the exec\012message style of programming doors.\012\012\012--- The message structure ---\012\012struct JHMessage\012{\012  struct Message Msg;   <----- msg structure\012  char String[200];     <----- info buffer\012  int Data;             <----- Read/Write & result indicator\012  int Command;          <----- Command sent from door.\012  int NODEID;           <----- reserved\012  int LineNum;          <----- reserved\012  unsigned long signal; <----- reserved\012  struct Process *task;\012  APTR *Semi;\012};\012\012\012The port name is AEDoorPort%d , where %d is the node number. General\012in ''C'' you''d do:\012\012--------------------------------------------------\012\012char portname[32];\012struct MsgPort *port;\012\012sprintf(portname, "AEDoorPort%d", atoi(argv[1]));\012port = FindPort(portname);\012\012--------------------------------------------------\012\012See the examples/ directory for more information.\012\012@endnode\012@node funcs "System-X XIM Functions"\012\012  The following list is a list of all System-X HOST Commands which\012  can be used in every program language to get/store information to the\012  AmiExpress Host Port. With this Command you can get Information\012  like BBSNAME, USERNAME etc. Click on the Buttons for more Information.\012\012    @{" JH_LI            <Func: 000> " Link Cap1101000}    @{" JH_REGISTER      <Func: 001> " Link Cap1101001}\012    @{" JH_SHUTDOWN      <Func: 002> " Link Cap1101002}    @{" JH_WRITE         <Func: 003> " Link Cap1101003}\012    @{" JH_SM            <Func: 004> " Link Cap1101004}    @{" JH_PM            <Func: 005> " Link Cap1101005}\012    @{" JH_HK            <Func: 006> " Link Cap1101006}    @{" JH_SG            <Func: 007> " Link Cap1101007}\012    @{" JH_SF            <Func: 008> " Link Cap1101008}    @{" JH_EF            <Func: 009> " Link Cap1101009}\012    @{" JH_CO            <Func: 010> " Link Cap1101010}    @{" JH_BBSNAME       <Func: 011> " Link Cap1101011}\012    @{" JH_SYSOP         <Func: 012> " Link Cap1101012}    @{" JH_FLAGFILE      <Func: 013> " Link Cap1101013}\012    @{" DT_NAME          <Func: 100> " Link Cap1101100}    @{" DT_PASSWORD      <Func: 101> " Link Cap1101101}\012    @{" DT_LOCATION      <Func: 102> " Link Cap1101102}    @{" DT_PHONENUMBER   <Func: 103> " Link Cap1101103}\012    @{" DT_SLOTNUMBER    <Func: 104> " Link Cap1101104}    @{" DT_ACCESSLEVEL   <Func: 105> " Link Cap1101105}\012    @{" DT_RATIOTYPE     <Func: 106> " Link Cap1101106}    @{" DT_RATIO         <Func: 107> " Link Cap1101107}\012    @{" DT_COMPTYPE      <Func: 108> " Link Cap1101108}    @{" DT_MESSAGESPOSTED<Func: 109> " Link Cap1101109}\012    @{" DT_UPLOADS       <Func: 110> " Link Cap1101110}    @{" DT_DOWNLOADS     <Func: 111> " Link Cap1101111}\012    @{" DT_TIMESCALLED   <Func: 112> " Link Cap1101112}    @{" DT_TIMELASTON    <Func: 113> " Link Cap1101109}\012    @{" DT_TIMEUSED      <Func: 114> " Link Cap1101114}    @{" DT_TIMELIMIT     <Func: 115> " Link Cap1101115}\012    @{" DT_TIMETOTAL     <Func: 116> " Link Cap1101116}    @{" DT_BYTESUPLOAD   <Func: 117> " Link Cap1101117}\012    @{" DT_BYTEDOWNLOAD  <Func: 118> " Link Cap1101118}    @{" DT_DAILYBYTELIMIT<Func: 119> " Link Cap1101119}\012    @{" DT_DAILYBYTEDLD  <Func: 120> " Link Cap1101120}    @{" DT_EXPERT        <Func: 121> " Link Cap1101121}\012    @{" DT_LINELENGTH    <Func: 122> " Link Cap1101122}    @{" ACTIVE_NODES     <Func: 123> " Link Cap1101123}\012    @{" DT_DUMP          <Func: 124> " Link Cap1101124}    @{" DT_TIMEOUT       <Func: 125> " Link Cap1101125}\012    @{" BB_CONFNAME      <Func: 126> " Link Cap1101126}    @{" BB_CONFLOCAL     <Func: 127> " Link Cap1101127}\012    @{" BB_LOCAL         <Func: 128> " Link Cap1101128}    @{" BB_STATUS        <Func: 129> " Link Cap1101129}\012    @{" BB_MAINLINE      <Func: 131> " Link Cap1101131}    @{" RETURNCOMMAND    <Func: 136> " Link Cap1101136}\012    @{" ZMODEMSEND       <Func: 137> " Link Cap1101137}    @{" ZMODEMRECEIVE    <Func: 138> " Link Cap1101138}\012    @{" SCREEN_ADDRESS   <Func: 139> " Link Cap1101139}    @{" BB_TASKPRI       <Func: 140> " Link Cap1101140}\012    @{" RAWSCREEN_ADDRESS<Func: 141> " Link Cap1101141}    @{" BB_CHATFLAG      <Func: 142> " Link Cap1101142}\012    @{" DT_STAMP_LASTON  <Func: 143> " Link Cap1101143}    @{" DT_STAMP_CTIME   <Func: 144> " Link Cap1101144}\012    @{" DT_CURR_TIME     <Func: 145> " Link Cap1101145}    @{" DT_CONFACCESS    <Func: 146> " Link Cap1101146}\012    @{" BB_NODEID        <Func: 149> " Link Cap1101149}    @{" BB_CALLERSLOG    <Func: 150> " Link Cap1101150}\012    @{" BB_UDLOG         <Func: 151> " Link Cap1101151}    @{" EXPRESS_VERSION  <Func: 152> " Link Cap1101152}\012    @{" BB_CHATSET       <Func: 162> " Link Cap1101162}    @{" ENVSTAT          <Func: 163> " Link Cap1101163}\012    @{" NODE_DEVICE      <Func: 503> " Link Cap1101503}    @{" NODE_UNIT        <Func: 504> " Link Cap1101504}\012    @{" NODE_BAUD        <Func: 505> " Link Cap1101505}    @{" JH_MCI           <Func: 507> " Link Cap1101507}\012    @{" PRV_COMMAND      <Func: 508> " Link Cap1101508}    @{" BB_CONFNUM       <Func: 510> " Link Cap1101510}\012    @{" BB_DROPDTR       <Func: 511> " Link Cap1101511}    @{" BB_GETTASK       <Func: 512> " Link Cap1101512}\012    @{" NODE_BAUDRATE    <Func: 516> " Link Cap1101516}    @{" BB_LOGONTYPE     <Func: 517> " Link Cap1101517}\012    @{" BB_SCRLEFT       <Func: 518> " Link Cap1101518}    @{" BB_SCRTOP        <Func: 519> " Link Cap1101519}\012    @{" BB_SCRWIDTH      <Func: 520> " Link Cap1101520}    @{" BB_SCRHEIGHT     <Func: 521> " Link Cap1101521}\012    @{" BB_PURGELIN      <Func: 522> " Link Cap1101522}    @{" BB_PURGELINESTART<Func: 523> " Link Cap1101523}\012    @{" BB_PURGELINEEND  <Func: 524> " Link Cap1101524}    @{" BB_NONSTOPTEXT   <Func: 525> " Link Cap1101525}\012    @{" BB_LINECOUNT     <Func: 526> " Link Cap1101526}    @{" DT_LANGUAGE      <Func: 527> " Link Cap1101527}\012    @{" DT_QUICKFLAG     <Func: 528> " Link Cap1101528}    @{" DT_GOODFILE      <Func: 529> " Link Cap1101529}\012\012    Below are functions that are System-X specific and DO NOT work under\012                     AmiExpress or any AmiExpress clones.\012\012    @{" SX_PS           <Func: 1500> " Link SX_PS}    @{" SX_USERPO       <Func: 1501> " Link SX_USERPO}\012    @{" SX_USERPO2      <Func: 1502> " Link SX_USERPO2}    @{" SX_USERPO3      <Func: 1503> " Link SX_USERPO3}\012    @{" SX_VER          <Func: 1504> " Link SX_VER}    @{" SX_NODES        <Func: 1505> " Link SX_NODES}\012    @{" SX_FUNCTION     <Func: 1506> " Link SX_FUNCTION}\012\012@endnode\012@node Cap1101000 "JH_LI             <Func: 000>"\012\012JH_LI          Requests a string of information from the user with a\012               default string.\012\012               msg->Command = 0\012               msg->String  = default result string\012               msg->Data    = Maximum length of response.\012\012               msg->Data will be set to a -1 if a loss carrier or console\012               TIMEOUT occurs, otherwise MSG->Data will be 1\012\012               msg->String will be the response string from the user.\012(FUNCTION #: 0 )\012\012@endnode\012@node Cap1101001 "JH_REGISTER       <Func: 001>"\012\012JH_REGISTER    Registers a door or XIM with the current node.\012\012               msg->Command = 1\012\012               This must be the first command issued to the express node.\012               This increments the number of doors active for the current\012               node.\012(FUNCTION #: 1 )\012\012@endnode\012@node Cap1101002 "JH_SHUTDOWN       <Func: 002>"\012\012JH_SHUTDOWN   Tells the node that a door is shutting down, this decreases\012              the number of active doors indicator , which once at 0,\012              the AEDoorPort will close.\012\012              msg->Command = 2\012              msg->Data    = N/A\012(FUNCTION #: 2 )\012\012@endnode\012@node Cap1101003 "JH_WRITE          <Func: 003>"\012\012JH_WRITE        Allows you to send a text string to the user.\012\012                msg->Command = 3\012                msg->String  = text\012                msg->Data    = N/A\012(FUNCTION #: 3 )\012\012@endnode\012@node Cap1101004 "JH_SM             <Func: 004>"\012\012JH_SM           Allows you to send a text string to the user.\012\012                msg->Command = 4\012                msg->String  = text\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then a CR/LF combination will be sent.\012(FUNCTION #: 4 )\012\012@endnode\012@node Cap1101005 "JH_PM             <Func: 005>"\012\012JH_PM           Allows you to prompt the user for a specified number of\012                characters.\012\012                msg->Command = 5\012                msg->String  = prompt string\012                msg->Data    = maximum response length.\012\012                if msg->Data = -1, then a loss carrier has occurred or a\012                TIMEOUT condition has occurred, otherwise msg->Data = 1.\012\012                msg->String will be the user response.\012(FUNCTION #: 5 )\012\012@endnode\012@node Cap1101006 "JH_HK              <Func: 006>"\012\012JH_HK           Allows you to get a 1 character response from the user.\012\012                msg->Command = 6\012                msg->String  = text\012                msg->Data    = N/A\012\012                if msg->Data = -1, then a loss carrier has occurred or a\012                TIMEOUT condition has occurred, otherwise msg->Data = 1.\012\012                msg->String will be the result string.\012(FUNCTION #: 6 )\012\012@endnode\012@node Cap1101007 "JH_SG             <Func: 007>"\012\012JH_SG           Allows you to display a text file to the user.\012\012                msg->Command = 7\012                msg->String  = part file name.\012                msg->Data    = N/A\012\012                ie:\012\012                msg->String = "BBS:Node1/Bull\012\012                This would try to display BBS:Node1/BULL.TXT\012                also takes into account language specifications.\012\012                This also searches for the access level patterns, ie:\012\012                Bull10.TXT, Bull100.TXT\012(FUNCTION #: 7 )\012\012@endnode\012@node Cap1101008 "JH_SF             <Func: 008>"\012\012JH_SF           Allows you to display a text file to the user.\012\012                msg->Command = 8\012                msg->String  = Complete pathname\012                msg->Data    = N/A\012\012                ie:\012\012                msg->String  = "BBS:Node1/BULL.TXT"\012\012                This would show the file if it exists.\012(FUNCTION #: 8 )\012\012@endnode\012@node Cap1101009 "JH_EF             <Func: 009>"\012\012JH_EF          Allows you to use the internal msgbase editor to edit your\012               own files.\012\012               msg->Command = 9\012               msg->String  = Complete pathname\012               msg->Data    = 0\012\012               if msg->Data = -1, then a loss carrier has occurred or a\012               TIMEOUT has occurred, otherwise msg->Data will be 1.\012(FUNCTION #: 9 )\012\012@endnode\012@node Cap1101010 "JH_CO             <Func: 010>"\012\012JH_CO          Allows you to send text string to the console only.\012\012               msg->Command = 10\012               msg->String  = text\012               msg->Data    = 1 or 0\012\012               if msg->Data = 1, then a CR/LF combination will be sent in\012               addition to the text.\012(FUNCTION #: 10 )\012\012@endnode\012@node Cap1101011 "JH_BBSNAME        <Func: 011>"\012\012JH_BBSNAME      Allows you to retrieve the BBS Name.\012\012                msg->Command = 11\012                msg->Data    = N/A\012\012                msg->String will be the BBS name.\012(FUNCTION #: 11 )\012\012@endnode\012@node Cap1101012 "JH_SYSOP          <Func: 012>"\012\012JH_SYSOP        Allows you to retrieve the Sysop''s Name.\012\012                msg->Command = 12\012                msg->Data    = N/A\012\012                msg->String will be the Sysop name.\012(FUNCTION #: 12 )\012\012@endnode\012@node Cap1101013 "JH_FLAGFILE       <Func: 013>"\012\012JH_FLAGFILE     Allows you to add files to the list of flagged files.\012\012                msg->Command = 13\012                msg->String  = FileName\012                msg->Data    = N/A\012\012                Adds the msg->String to the list of flagged files for\012                downloading purposes,\012\012                NOTE: The files must be in the download path for this to\012                      work.\012(FUNCTION #: 13 )\012\012@endnode\012@node Cap1101100 "DT_NAME           <Func: 100>"\012\012DT_NAME         Allows you to retrieve or change users name/handle\012\012                msg->Command = 100\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be the name.\012                if msg->Data = 0, then name will be msg->String\012(FUNCTION #: 100 )\012\012@endnode\012@node Cap1101101 "DT_PASSWORD       <Func: 101>"\012\012DT_PASSWORD     Allows you to retrieve or change users password\012\012                msg->Command = 101\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be the password.\012                if msg->Data = 0, then the password will be msg->String.\012(FUNCTION #: 101 )\012\012@endnode\012@node Cap1101102 "DT_LOCATION      <Func: 102>"\012\012DT_LOCATION     Allows you to retrieve or change users location\012\012                msg->Command = 102\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be the location\012                if msg->Data = 0, then the location will be msg->String\012(FUNCTION #: 102 )\012\012@endnode\012@node Cap1101103 "DT_PHONENUMBER    <Func: 103>"\012\012DT_PHONENUMBER  Allows you to retrieve or change users phone number.\012\012               msg->Command = 103\012               msg->Data    = 1 or 0\012\012               if msg->Data = 1, then msg->String will be the phonenumber\012               if msg->Data = 0, ten phonenumber will be msg->String\012(FUNCTION #: 103 )\012\012@endnode\012@node Cap1101104 "DT_SLOTNUMBER     <Func: 104>"\012\012DT_SLOTNUMBER  Allows you to retrieve users slot number\012\012               msg->Command = 104\012               msg->Data    = 1\012\012               if msg->Data = 1, then msg->String will be the SLOTNUMBER.\012(FUNCTION #: 104 )\012\012@endnode\012@node Cap1101105 "DT_ACCESSLEVEL    <Func: 105>"\012\012DT_ACCESSLEVEL  Allows you to retrieve or change users access level.\012\012                msg->Command = 105\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be ACCESSLEVEL.\012                if msg->Data = 0, then ACCESSLEVEL will be msg->String.\012(FUNCTION #: 105 )\012\012@endnode\012@node Cap1101106 "DT_RATIOTYPE      <Func: 106>"\012\012DT_RATIOTYPE    Allows you to retrieve or change users RatioType\012\012                msg->Command = 106\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be RatioType.\012                if msg->Data = 0, then RatioType will be msg->String.\012(FUNCTION #: 106 )\012\012@endnode\012@node Cap1101107 "DT_RATIO          <Func: 107>"\012\012DT_RATIO        Allows you to retrieve or change users ratio\012\012                msg->Command = 107\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be ratio.\012                if msg->Data = 0, then ratio will be msg->String.\012(FUNCTION #: 107 )\012\012@endnode\012@node Cap1101108 "DT_COMPTYPE       <Func: 108>"\012\012DT_COMPTYPE     Allows you to retrieve or change users ComputerTypes code\012\012                msg->Command = 108\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be ComputerTypes.\012                if msg->Data = 0, then ComputerTypes will be msg->String.\012(FUNCTION #: 108 )\012\012@endnode\012@node Cap1101109 "DT_MESSAGESPOSTED <Func: 109>"\012\012DT_MESSAGESPOSTED Allows you to retrieve or change users MESSAGESPOSTED\012\012               msg->Command = 109\012               msg->Data    = 1 or 0\012\012               if msg->Data = 1, then msg->String will be MESSAGESPOSTED.\012               if msg->Data = 0, then MESSAGESPOSTED will be msg->String.\012(FUNCTION #: 109 )\012\012@endnode\012@node Cap1101110 "DT_UPLOADS        <Func: 110>"\012\012DT_UPLOADS      Allows you to retrieve or change number of UserUploads.\012\012                msg->Command = 110\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be uploads.\012                if msg->Data = 0, then uploads will be msg->String.\012(FUNCTION #: 110 )\012\012@endnode\012@node Cap1101111 "DT_DOWNLOADS      <Func: 111>"\012\012DT_DOWNLOADS   Allows you to retrieve or change number of UserDownloads.\012\012                msg->Command = 111\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be downloads.\012                if msg->Data = 0, then downloads will be msg->String.\012(FUNCTION #: 111 )\012\012@endnode\012@node Cap1101112 "DT_TIMESCALLED    <Func: 112>"\012\012DT_TIMESCALLED  Allows you to retrieve or change number of UserCalls.\012\012                msg->Command = 112\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be TIMESCALLED.\012                if msg->Data = 0, then TIMESCALLED will be msg->String.\012(FUNCTION #: 112 )\012\012@endnode\012@node Cap1101113 "DT_TIMELASTON     <Func: 113>"\012\012DT_TIMELASTON   Allows you to retrieve or change time user last called.\012\012                msg->Command = 113\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be TIMESCALLED.\012                if msg->Data = 0, then TIMESCALLED will be msg->String.\012\012                NOTE: This is not a date stamp, this is the number of\012                      seconds since January 19something.\012(FUNCTION #: 113 )\012\012@endnode\012@node Cap1101114 "DT_TIMEUSED       <Func: 114>"\012\012DT_TIMEUSED     Allows you to retrieve or change TIMEUSED today.\012\012                msg->Command = 114\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be TIMEUSED.\012                if msg->Data = 0, then TIMEUSED will be msg->String.\012\012                NOTE: This is in seconds.\012(FUNCTION #: 114 )\012\012@endnode\012@node Cap1101115 "DT_TIMELIMIT      <Func: 115>"\012\012DT_TIMELIMIT    Allows you to retrieve or change TimeAllowed for a user.\012\012                msg->Command = 115\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be TIMELIMIT.\012                if msg->Data = 0, then TIMELIMIT will be msg->String.\012\012                NOTE: Time in seconds.\012(FUNCTION #: 115 )\012\012@endnode\012@node Cap1101116 "DT_TIMETOTAL      <Func: 116>"\012\012DT_TIMETOTAL   Allows you to retrieve or change total time remaining.\012               for a user today.\012\012               msg->Command = 116\012               msg->Data    = 1 or 0\012\012               if msg->Data = 1, then msg->String will be time remaining.\012               if msg->Data = 0, then time remaining will be msg->String.\012\012               NOTE: Time in seconds.\012(FUNCTION #: 116 )\012\012@endnode\012@node Cap1101117 "DT_BYTESUPLOAD    <Func: 117>"\012\012DT_BYTESUPLOAD  Allows you to retrieve or change bytes uploads per user.\012\012                msg->Command = 117\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be BYTESUPLOADED.\012                if msg->Data = 0, then BYTESUPLOADED will be msg->String.\012(FUNCTION #: 117 )\012\012@endnode\012@node Cap1101118 "DT_BYTEDOWNLOAD   <Func: 118>"\012\012DT_BYTEDOWNLOAD Allows you to retrieve or change bytes downloaded per\012                user.\012\012               msg->Command = 118\012               msg->Data    = 1 or 0\012\012               if msg->Data = 1, then msg->String will be BYTESDOWNLOADED.\012               if msg->Data = 0, then BYTESDOWNLOADED will be msg->String.\012(FUNCTION #: 118 )\012\012@endnode\012@node Cap1101119 "DT_DAILYBYTELIMIT <Func: 119>"\012\012DT_DAILYBYTELIMIT Allows you to retrieve or change a users daily byte\012                  download limit.\012\012                  msg->Command = 119\012                  msg->Data    = 1 or 0\012\012                  if msg->Data = 1, then msg->String will be bytelimit.\012                  if msg->Data = 0, then bytelimit will be msg->String.\012(FUNCTION #: 119 )\012\012@endnode\012@node Cap1101120 "DT_DAILYBYTEDLD   <Func: 120>"\012\012DT_DAILYBYTEDLD Allows you to retrieve or change daily bytes downloaded.\012\012                msg->Command = 120\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be dailybytes.\012                if msg->Data = 0, then dailybytes will be msg->String.\012(FUNCTION #: 120 )\012\012@endnode\012@node Cap1101121 "DT_EXPERT         <Func: 121>"\012\012DT_EXPERT         Allows you to retrieve or change expert mode.\012\012                  msg->Command = 121\012                  msg->Data    = 1 or 0\012(FUNCTION #: 121 )\012\012@endnode\012@node Cap1101122 "DT_LINELENGTH     <Func: 122>"\012\012DT_LINELENGTH     Allows you to retrieve or change user LINELENGTH specs.\012\012                  msg->Command = 122\012                  msg->Data    = 1 or 0\012\012                  if msg->Data = 1, then msg->String will be LINELENGTH.\012                  if msg->Data = 0, then LINELENGTH will be msg->String.\012(FUNCTION #: 122 )\012\012@endnode\012@node Cap1101123 "ACTIVE_NODES      <Func: 123>"\012\012ACTIVE_NODES    Allows you to retrieve a string of active&inactive nodes.\012\012                msg->Command = 123\012                msg->Data    = N/A\012\012                msg->String will be a string 10 bytes in length, with\012                     ''X''s marking the active nodes.\012\012                NOTE: This command will surely be changing, the current\012                      limit is 9 nodes.\012(FUNCTION #: 123 )\012\012@endnode\012@node Cap1101124 "DT_DUMP           <Func: 124>"\012\012DT_DUMP           Allows you to dump the user''s data structure to a\012                  specified file.\012\012                  msg->Command = 124\012                  msg->String  = FileName\012(FUNCTION #: 124 )\012\012@endnode\012@node Cap1101125 "DT_TIMEOUT        <Func: 125>"\012\012DT_TIMEOUT       Allows you to retrieve or change the door TIMEOUT limit.\012\012                 msg->Command = 125\012                 msg->Data    = 1 or 0\012\012                 if msg->Data = 1, then msg->String will equal TIMEOUT.\012                 if msg->Data = 0, then TIMEOUT will equal msg->String.\012\012                 NOTE: This time is in seconds.\012(FUNCTION #: 125 )\012\012@endnode\012@node Cap1101126 "BB_CONFNAME       <Func: 126>"\012\012BB_CONFNAME       Allows you to retrieve or change the conference name.\012\012                  msg->Command = 126\012                  msg->Data    = 1 or 0\012\012                  if msg->Data = 1, then msg->String will be name.\012                  if msg->Data = 0, then name will be msg->String.\012(FUNCTION #: 126 )\012\012@endnode\012@node Cap1101127 "BB_CONFLOCAL      <Func: 127>"\012\012BB_CONFLOCAL    Allows you to retrieve or change the conference location.\012\012                msg->Command = 127\012                msg->Data    = 1 or 0\012\012                if msg->Data = 1, then msg->String will be location.\012                if msg->Data = 0, then location will be msg->String.\012(FUNCTION #: 127 )\012\012@endnode\012@node Cap1101128 "BB_LOCAL          <Func: 128>"\012\012BB_LOCAL          Allows you to retrieve the current BBS location.\012\012                  msg->Command = 128\012                  msg->Data    = N/A\012(FUNCTION #: 128 )\012\012@endnode\012@node Cap1101129 "BB_STATUS         <Func: 129>"\012\012BB_STATUS         Allows you to retrieve the current status of the node.\012\012                  msg->Command = 129\012                  msg->Data    = N/A\012\012                  msg->String will be ''OFFLINE'' or ''ONLINE'' depending on\012                  whether a user is logged onto the node.\012(FUNCTION #: 129 )\012\012@endnode\012@node Cap1101131 "BB_MAINLINE       <Func: 131>"\012\012BB_MAINLINE     Allows you to retrieve the menu prompt arguments prior to\012                the door being entered.\012\012                msg->Command = 131\012                msg->Data    = N/A\012\012                msg->String will be the menu prompt arguments.\012(FUNCTION #: 131 )\012\012@endnode\012@node Cap1101136 "RETURNCOMMAND     <Func: 136>"\012\012RETURNCOMMAND    Allows you to specify an internal command to be executed\012                 when the door is finished.\012\012                 msg->Command = 136\012                 msg->Data    = N/A\012\012                 command to be executed will be msg->String.\012(FUNCTION #: 136 )\012\012@endnode\012@node Cap1101137 "ZMODEMSEND        <Func: 137>"\012\012ZMODEMSEND      Allows you to send files to the user via Zmodem protocol.\012\012                msg->Command = 137\012                msg->String  = filename (complete pathname)\012                msg->Data    = N/A\012\012                result of transfer will be in msg->Data, where\012\012                if msg->Data = 1 , then transfer successful.\012                if msg->Data = -2, then user lost carrier.\012                if msg->Data = 0 , then transfer unsuccessful.\012(FUNCTION #: 137 )\012\012@endnode\012@node Cap1101138 "ZMODEMRECEIVE     <Func: 138>"\012\012ZMODEMRECEIVE    Allows you to receive batch uploads via Zmodem protocol.\012\012                 msg->Command = 138\012                 msg->String  = receive directory path\012                 msg->Data    = N/A\012\012                 result of transfer will be in msg->Data, where\012\012                 if msg->Data = 1 , then transfer successful.\012                 if msg->Data = -2, then user lost carrier.\012                 if msg->Data = 0,  then transfer unsuccessful.\012(FUNCTION #: 138 )\012\012@endnode\012@node Cap1101139 "SCREEN_ADDRESS    <Func: 139>"\012\012SCREEN_ADDRESS    Allows you to retrieve the screen address.\012\012                  msg->Command = 139\012                  msg->Data    = N/A\012\012                  msg->String will be a string containing the hexadecimal\012                  address of the Node screen.\012(FUNCTION #: 139 )\012\012@endnode\012@node Cap1101140 "BB_TASKPRI        <Func: 140>"\012\012BB_TASKPRI    Allows you to retrieve the priority the node is running at.\012\012              msg->Command = 140\012              msg->Data    = N/A\012\012              msg->String will contain the priority of the node.\012(FUNCTION #: 140 )\012\012@endnode\012@node Cap1101141 "RAWSCREEN_ADDRESS <Func: 141>"\012\012RAWSCREEN_ADDRESS Allows you to retrieve the screen address of the node.\012\012              msg->Command = 141\012              msg->Data    = N/A\012\012              msg->String will be a string containing the decimal address\012                   of the express node.\012(FUNCTION #: 141 )\012\012@endnode\012@node Cap1101142 "BB_CHATFLAG       <Func: 142>"\012\012BB_CHATFLAG       Allows you to retrieve the current chat setting.\012\012                  msg->Command = 142\012                  msg->Data    = N/A\012\012                  msg->String will be "ON" or "OFF".\012(FUNCTION #: 142 )\012\012@endnode\012@node Cap1101143 "DT_STAMP_LASTON   <Func: 143>"\012\012DT_STAMP_LASTON Allows you to retrieve a date string containing the date\012                of when the user last logged on.\012\012                msg->Command = 143\012                msg->Data    = N/A\012\012                msg->String will be the date string.\012(FUNCTION #: 143 )\012\012@endnode\012@node Cap1101144 "DT_STAMP_CTIME    <Func: 144>"\012\012DT_STAMP_CTIME    Allows you to retrieve a current time string.\012\012                  msg->Command = 144\012                  msg->Data    = N/A\012\012                  msg->String will be a current time string.\012(FUNCTION #: 144 )\012\012@endnode\012@node Cap1101145 "DT_CURR_TIME      <Func: 145>"\012\012DT_CURR_TIME     Allows you to retrieve the current time in seconds since\012                 January something.\012\012                 msg->Command = 145\012                 msg->Data    = N/A\012\012                 msg->String will be the current time.\012(FUNCTION #: 145 )\012\012@endnode\012@node Cap1101146 "DT_CONFACCESS     <Func: 146>"\012\012DT_CONFACCESS     Allows you to retrieve the users conference access.\012\012                  msg->Command = 146\012                  msg->Data    = 1 or 0\012\012                  if msg->Data = 1, then msg->String will be AREANAME.\012                  if msg->Data = 0, then AREANAME will be msg->String.\012\012(FUNCTION #: 146 )\012\012@endnode\012@node Cap1101149 "BB_NODEID         <Func: 149>"\012\012BB_NODEID         Allows you to retrieve the Node number for the current\012                  node\012\012                  msg->Command = 149\012                  msg->Data    = N/A\012\012                  msg->String will be the node number.\012(FUNCTION #: 149 )\012\012@endnode\012@node Cap1101150 "BB_CALLERSLOG     <Func: 150>"\012\012BB_CALLERSLOG     Allows you to add a line of text to the CALLERSLOG.\012\012                  msg->Command = 150\012                  msg->String  = text\012                  msg->Data    = N/A\012(FUNCTION #: 150 )\012\012@endnode\012@node Cap1101151 "BB_UDLOG          <Func: 151>"\012\012BB_UDLOG          Allows you to add a line of text to the UDLOG.\012\012                  msg->Command = 151\012                  msg->String  = text\012                  msg->Data    = N/A\012(FUNCTION #: 151 )\012\012@endnode\012@node Cap1101152 "EXPRESS_VERSION   <Func: 152>"\012\012EXPRESS_VERSION   Allows you to retrieve the current version string of\012                  express.\012\012                  msg->Command = 152\012                  msg->Data    = N/A\012(FUNCTION #: 152 )\012\012@endnode\012@node Cap1101162 "BB_CHATSET        <Func: 162>"\012\012BB_CHATSET     Allows you to retrieve or change the chat status.\012\012               msg->Command = 162\012               msg->Data    = 1 or 0\012\012               if msg->Data = 1, then msg->String will be current status.\012               if msg->Data = 0, then status will be msg->String.\012(FUNCTION #: 162 )\012\012@endnode\012@node Cap1101163 "ENVSTAT           <Func: 163>"\012\012ENVSTAT          Allows you to retrieve or change the current environment\012                 stat variable code.\012\012                 msg->Command = 163\012                 msg->Data    = 1 or 0\012\012                 if msg->Data = 1, then msg->String will be status.\012                 if msg->Data = 0, then status will be msg->String.\012(FUNCTION #: 163 )\012\012@endnode\012@node Cap1101503 "NODE_DEVICE       <Func: 503>"\012\012NODE_DEVICE       Allows you to retrieve the node device name.\012\012                  msg->Command = 503\012                  msg->Data    = N/A\012\012                  msg->String will be the device string.\012(FUNCTION #: 503 )\012\012@endnode\012@node Cap1101504 "NODE_UNIT         <Func: 504>"\012\012NODE_UNIT         Allows you to retrieve the node unit number.\012\012                  msg->Command = 504\012                  msg->Data    = N/A\012\012                  msg->String will be the current node number.\012(FUNCTION #: 504 )\012\012@endnode\012@node Cap1101505 "NODE_BAUD         <Func: 505>"\012\012NODE_BAUD    Allows you to retrieve the initialized baud rate of the node.\012\012             msg->Command = 505\012             msg->Data    = N/A\012\012             msg->String will be the INIT baud rate.\012(FUNCTION #: 505 )\012\012@endnode\012@node Cap1101507 "JH_MCI            <Func: 507>"\012\012JH_MCI            Allows you to send MCI text to express.\012\012                  msg->Command = 507\012                  msg->String  = text\012                  msg->Data    = N/A\012(FUNCTION #: 507 )\012\012@endnode\012@node Cap1101508 "PRV_COMMAND       <Func: 508>"\012\012PRV_COMMAND       Allows you to immediately execute an internal express\012                  menu command.\012\012                  msg->Command = 508\012                  msg->String  = commandstring\012                  msg->Data    = N/A\012(FUNCTION #: 508 )\012\012@endnode\012@node Cap1101510 "BB_CONFNUM        <Func: 510>"\012\012BB_CONFNUM     Allows you to retrieve the current conference number.\012\012               msg->Command = 510\012               msg->Data    = N/A\012\012               msg->String will be conference number ranging from 0 to 8.\012(FUNCTION #: 510 )\012\012@endnode\012@node Cap1101511 "BB_DROPDTR        <Func: 511>"\012\012BB_DROPDTR        Allows you to drop carrier on a user.\012\012                  msg->Command = 511\012                  msg->Data    = N/A\012(FUNCTION #: 511 )\012\012@endnode\012@node Cap1101512 "BB_GETTASK        <Func: 512>"\012\012BB_GETTASK        Finds the current nodes task address.\012\012                  msg->Command = 512\012                  msg->Data    = N/A\012\012                  msg->task will be the express task address.\012(FUNCTION #: 512 )\012\012@endnode\012@node Cap1101516 "NODE_BAUDRATE     <Func: 516>"\012\012NODE_BAUDRATE     Allows you to retrieve the current users connect rate\012\012                  msg->Command = 516\012                  msg->Data    = N/A\012\012                  msg->String will be the connect rate\012(FUNCTION #: 516 )\012\012@endnode\012@node Cap1101517 "BB_LOGONTYPE      <Func: 517>"\012\012BB_LOGONTYPE      Allows you to retrieve the LOGONTYPE.\012\012                  msg->Command = 517\012                  msg->Data    = N/A\012\012                  msg->Data will be:\012\012                  0 = AWAIT_LOGON\012                  1 = SYSOP_LOGON\012                  2 = LOCAL_LOGON\012                  3 = REMOTE_LOGON\012(FUNCTION #: 517 )\012\012@endnode\012@node Cap1101518 "BB_SCRLEFT        <Func: 518>"\012\012BB_SCRLEFT      Allows you to retrieve the screen coordinates.\012\012                msg->Command = 518\012                msg->Data    = N/A\012\012                msg->Data will be the Node''s Initial LEFTEDGE coordinate.\012(FUNCTION #: 518 )\012\012@endnode\012@node Cap1101519 "BB_SCRTOP         <Func: 519>"\012\012BB_SCRTOP        Allows you to retrieve the screen coordinates.\012\012                 msg->Command = 519\012                 msg->Data    = N/A\012\012                 msg->Data will be the Node''s Initial TOPEDGE coordinate.\012(FUNCTION #: 519 )\012\012@endnode\012@node Cap1101520 "BB_SCRWIDTH       <Func: 520>"\012\012BB_SCRWIDTH       Allows you to retrieve the screen coordinates.\012\012                  msg->Command = 520\012                  msg->Data    = N/A\012\012                  msg->Data will be the Node''s Initial screen height.\012(FUNCTION #: 520 )\012\012@endnode\012@node Cap1101521 "BB_SCRHEIGHT      <Func: 521>"\012\012BB_SCRHEIGHT      Allows you to retrieve the screen coordinates.\012\012                  msg->Command = 521\012                  msg->Data    = N/A\012\012                  msg->Data will be the Node''s Initial screen width.\012(FUNCTION #: 521 )\012\012@endnode\012@node Cap1101522 "BB_PURGELIN       <Func: 522>"\012\012BB_PURGELIN   Allows you to abort serial input.\012\012               msg->Command = 522\012               msg->Data    = N/A\012\012              aborts serial input and flushes the serial buffer and sends\012              a request for more input.\012(FUNCTION #: 522 )\012\012@endnode\012@node Cap1101523 "BB_PURGELINESTART <Func: 523>"\012\012BB_PURGELINESTART Allows you to CLEAR the serial buffer and request more\012                  serial input.\012\012                  msg->Command = 523\012                  msg->Data    = N/A\012(FUNCTION #: 523 )\012\012@endnode\012@node Cap1101524 "BB_PURGELINEEND   <Func: 524>"\012\012BB_PURGELINEEND   Allows you to CLEAR the serial buffer.\012\012                  msg->Command = 524\012                  msg->Data    = N/A\012(FUNCTION #: 524 )\012\012@endnode\012@node Cap1101525 "BB_NONSTOPTEXT    <Func: 525>"\012\012BB_NONSTOPTEXT    Allows you to change the NONSTOP text scrolling flag.\012\012                  msg->Command = 525\012                  msg->Data    = 1 or 0\012\012                  if msg->Data = 1, then display text will not pause.\012                  if msg->Data = 0, then display text will pause.\012(FUNCTION #: 525 )\012\012@endnode\012@node Cap1101526 "BB_LINECOUNT      <Func: 526>"\012\012BB_LINECOUNT   Allows you to retrieve or change the user''s current number\012               of lines viewed.\012\012               msg->Command = 526\012               msg->Data    = 1 or 0\012\012               if msg->Data = 1, then msg->String will be current line.\012               if msg->Data = 0, then current line will be msg->String.\012(FUNCTION #: 526 )\012\012@endnode\012@node Cap1101527 "DT_LANGUAGE       <Func: 527>"\012\012DT_LANGUAGE      Allows you to retrieve or change the current language\012                 specifications.\012\012                 msg->Command = 527\012                 msg->Data    = 1 or 0\012\012                 if msg->Data = 1, then msg->String will be language.\012                 if msg->Data = 0, then language will be msg->String.\012\012                NOTE: Languages need to be standardized, please what for\012                      guidelines.\012\012                ie:  Default language .TXT\012                     English          .ENG\012                     German           .GER\012\012                     note that this only effects the menus, bulletins &\012                     other screen text files.\012(FUNCTION #: 527 )\012\012@endnode\012@node Cap1101528 "DT_QUICKFLAG      <Func: 528>"\012\012DT_QUICKFLAG      Allows you to change the QUICKTEXT flag.\012\012                  msg->Command = 528\012                  msg->Data    = 1 or 0\012\012                  if msg->Data = 1, then the QuickFlag will be set.\012                  if msg->Data = 0, then the QuickFlag will not be set.\012(FUNCTION #: 528 )\012\012@endnode\012@node Cap1101529 "DT_GOODFILE       <Func: 529>"\012\012DT_GOODFILE       Allows you to set the results of a tested file after\012                  upload.\012\012                  msg->Command = 529\012                  msg->Data    = 1,0 or -1\012\012                  if msg->Data is 1, then the file was not tested.\012                  if msg->Data is 0, then the file passed the filetest.\012                  if msg->Data is -1, then the file failed the filetest.\012\012                  NOTE: This command is only useful with the SYSCmd door\012                  called FILECHECK.\012(FUNCTION #: 529 )\012\012@endnode\012@node SX_PS "System-X Only Print String"\012\012SX_PS		Prints a string to the console/serial port.\012\012		msg->Command = 1500\012		msg->Data    = pointer to a string\012\012\012		Note: no copying required and no length limit!\012\012\012(FUNCTION #: 1500 )\012@endnode\012@node SX_USERPO "Get UserStruct Pointer (UserData)"\012\012SX_USERPO	Gives you the pointer to the User structure\012\012		msg->Command = 1501\012\012\012		returns the pointer in msg->Data\012\012(FUNCTION #: 1501 )\012@endnode\012@node SX_USERPO2 "Get UserStruct Pointer (SXUser)"\012\012SX_USERPO2	Gives you the pointer to the SXUser structure\012\012		msg->Command = 1502\012\012\012		returns the pointer in msg->Data\012\012(FUNCTION #: 1502 )\012@endnode\012@node SX_USERPO3 "Get UserStruct Pointer (Index)"\012\012SX_USERPO3	Gives you the pointer to the User Index structure\012\012		msg->Command = 1503\012\012\012		returns the pointer in msg->Data\012\012(FUNCTION #: 1503 )\012@endnode\012\012@node SX_VER "Get the System-X version"\012\012SX_VER		Gives you the version of SX\012\012		msg->Command = 1504\012\012		returns it in msg->String, eg: "1.00"\012\012(FUNCTION #: 1504 )\012@endnode\012@node SX_NODES "Get a pointer to the node structures"\012\012SX_NODES	Get a pointer to the node structures\012\012		msg->Command = 1505\012\012		returns it in msg->Data\012\012		For more information, see MCP Communication/Command 14.\012\012(FUNCTION #: 1505 )\012@endnode\012@node mcp "MCP"\012\012Communication with MCP is available through standard EXEC-MESSAGES.\012\012The structure of the message is (you must allocate it)\012\012struct MCPMessage\012{\012	struct Message Msg;\012	UWORD command;\012	UWORD nodenum;\012	long data1;\012	long data2;\012	long data3;\012	long data4;\012	long data5;\012	long data6;\012};\012\012UWORD''s are 16-bit\012long''s are 32-bit\012\012\012If anything but an actual node wants to use this port, you must make\012nodenum equal 0 (zero) (that includes doors!).\012\012\012.------------------------.\012| MCP Commands Available |\012`------------------------''\012\012	Note: Commands 1 to 5 are PRIVATE!!\012\012\012	6 - MENU POINTER\012\012		Ask MCP to give you a pointer to a menu structure\012\012		themsg.command = 6\012		themsg.data1   = pointer to the menu you want\012					eg: "Main_Menu"\012\012		returns\012\012		themsg.data2   = the pointer you wanted\012		themsg.data3   = size of the struct in bytes\012\012\012\012	8 - MD5 ENCRYPTION\012\012		This will ask MCP to encrypt a string for you, using MD5.\012\012		themsg.command = 8\012		themsg.data1   = pointer to the string to encrypt\012		themsg.data2   = pointer to 16 bytes to put the result in\012\012\012	10 - QUERY SYSOP\012\012		Find out if the sysop is available\012\012		themsg.command = 10\012\012		returns\012\012		themsg.data1   = pointer to the reason for being away\012				(if NULL, the sysop is available)\012\012\012	12 - APPEND TO A FILE\012\012		themsg.command = 12\012		themsg.data1   = pointer to the filename string\012		themsg.data2   = pointer to the buffer to append\012		themsg.data3   = size of the append buffer\012\012\012	14 - GET A POINTER TO THE NODE INFORMATION CHAIN\012\012		themsg.command = 14\012\012		returns\012\012		themsg.data1   = the pointer to node 1''s structure\012				(use the NEXT field to browse through)\012\012		the struct is as follows\012\012		struct node_struct\012		{					/* offset DEC	*/\012			APTR next;			/*	0	*/\012			struct UserData *User;		/*	4	*/\012			struct UserIndexStruct *UserIndex;/*	8	*/\012			struct SXUserStruct *SXUser;	/*	12	*/\012			char *action;			/*	16	*/\012			char *filename;			/*	20	*/\012			long baud;			/*	24	*/\012			long loginsecs;			/*	28	*/\012			UWORD number;			/*	32	*/\012			UBYTE actionnumber;		/*	34	*/\012			UBYTE active;			/*	35	*/\012			UBYTE useron;			/*	36	*/\012			UBYTE misc;			/*	37	*/\012		};\012\012.--------------------------------------.\012| Example ''C'' program using MCP''s port |\012`--------------------------------------''\012\012struct MCPMessage\012{\012	struct Message Msg;\012	UWORD command;\012	UWORD nodenum;\012	long data1;\012	long data2;\012	long data3;\012	long data4;\012	long data5;\012	long data6;\012};\012struct MCPMessage themsg;\012struct MsgPort *MyPort, *MCPPort;\012\012	MCPPort = FindPort("SX-MCP");\012	if(MCPPort)\012	{\012		MyPort = CreateMsgPort();\012		if(MyPort)\012		{\012			themsg.Msg.mn_Length = sizeof(struct MCPMessage);\012			themsg.Msg.mn_ReplyPort = MyPort;\012			themsg.nodenum = 0;\012			themsg.command = 10;	/* 10 = QUERY SYSOP */\012			PutMsg(MCPPort, (struct Message *)&themsg);\012			WaitPort(MyPort);\012			DeleteMsgPort(MyPort);\012			if(themsg.data1)\012			{\012				PutStr("The Sysop is away because:\n\n");\012				PutStr((char *)themsg.data1);\012				PutStr("\n");\012			} else {\012				PutStr("The Sysop is available!\n");\012			}\012		}\012	}\012@endnode\012@node SX_FUNCTION "Execute an internal SX Function"\012\012SX_FUNCTION	Execute an internal SX Function (sxfunctions.doc)\012\012		msg->data = pointer to this structure:\012\012struct SXFuncStruct\012{\012	UWORD	id;\012	char	*string;\012	UWORD	extra;\012	UWORD	low;\012	UWORD	high;\012	char	*mainarg;\012	char	*execarg;\012} *SXFunc;\012\012		Must must allocate this structure and fill in all\012		the fields, then pass it through msg->data.\012\012(FUNCTION #: 1506 )\012@endnode\012','\012',char(10)),NULL,'auto-added',469588,5,1,'Z','Doors/5D-ZippySearch','dcsxm100','scan',1780048474);
INSERT INTO door_catalog VALUES('dcs_ax14','DCS_AX14.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DCS_AX14.LHA','c','XIM','ax-edit.library',NULL,NULL,'DCS',NULL,replace('AXEdit Update  nice nuke&fake tool\n','\n',char(10)),'RexxEncrypt.txt',replace('                    RexxEncrypt v1.0a by Mack Lifeguard\n                    ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nWhat is RexxEncrypt?\n\nSimply put, it''s an encryption system for all ARexx scripts. The encryption\nroutines are written in C and employ "military-strength" encryption\nschemes. To crack the code you would need a Super Cray II and a lot of\npatience.\n\nHow does it work?\n\nIn an /X door environment, the very first file that is called by Amiexpress\nlaunches a custom executable file.  This file loads the encrypted rexx\nscript, decodes it, then sends it DIRECTLY into the rexx port.  It never\nsees the operating system (freely that is).  The memory is then\nde-allocated, and rexxmast executes the script just as if it had been run\nwith ''rx''. In the case of /X, the node is passed as an argument, and the\nnew, decoded script takes over the original "launchpad" one.\n\n\nBut why encryption?\n\nWell, compiled rexx worked for a while, but then accelerators and A4000s\ncame along. The compiled code would crash most non-standard systems.\n\nThus, there had to be a way to fix the situation. Releasing the original\nrexx source code was not an option due to some people waiting to tear it\napart, producing pseudo-versions of it. An author''s nightmare.\n\nThis way, the code is 100% compatible and safe.\n\n\n\nWhen will you make this encryption system public?\n\nIf there is enough demand I will write a custom encryptor system that\nanyone can use.  Whether it''s for /X doors, or anything else you can think\nof that uses ARexx, RexxEncrypt will keep it safe.\n','\n',char(10)),NULL,'auto-added',83442,7,0,NULL,NULL,'dcs_ax14','scan',1780048474);
INSERT INTO door_catalog VALUES('dcs_tn2','DCS_TN2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DCS_TN2.LHA','TNConfig','XIM','TNConfig',NULL,NULL,'DCS','*[M]ove files (several at once) to any conf. *[E]dit descriptions quick and easy. *[C]opy multiple files anywhere on ya board.',replace('  DCS spurtz ya wid: Turbo Newscan II Pro!\n*[M]ove files (several at once) to any conf.\n*[E]dit descriptions quick and easy.\n*[C]opy multiple files anywhere on ya board.\n*[N]uker searches logs at 398 kb/sec @ 7mhz!\n*[S]uperView: dumps any file to screen.\n*[G]etDIRs: download DIRs fast via ZMODEM.\n*[Z]earch links to any external Search tool.\n*[I]nfo shows uploader and date of any file.\n-Virtual Scroller System! Arrows travel DIR.\n>Don''t jerk around with cheap TN imitations<\n This tool works on S-xpress, /X 1.1x - 4.x.','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 20:23:41  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',45440,1,0,NULL,NULL,'dcs_tn2','scan',1780048474);
INSERT INTO door_catalog VALUES('dcs_tn2j','DCS_TN2J.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DCS_TN2J.LHA','TNConfig','XIM','TNConfig',NULL,NULL,'DCS','>> THE ONLY OFFICIAL PUBLIC VERSION << *Scans 2 Meg listings in 1.3 seconds @ 7Mhz! *40 times faster than other Newfile doors!',replace('DCS Proudly Regurgitates: Turbo Newscan 2.j!\n   >> THE ONLY OFFICIAL PUBLIC VERSION <<\n*Scans 2 Meg listings in 1.3 seconds @ 7Mhz!\n*40 times faster than other Newfile doors!\n*Fully configurable, more than 40 options!\n*View, Comment, & Delete files on the fly.\n*Real 100% no-bullshit cursor arrow flaggin''\n*Unique AutoScroll(tm) feature for traderz!\n*Built-in [S]ysop commands, Ax-Edit style!\n     For S-Express and /X 1.1x to 3.xx.\n         KICKIN'' YOUR ASS BYTEANDI!\n','\n',char(10)),'Registration.txt',replace('                               REGISTRATION\n\nCall International Chaos at (713) 999-3640 v32bis 9600+ only.\n\nOr reach me on the Internet:\n\[email removed]\n\nI will give more info about registration there. Before you consider\nregistering (which costs money), make sure this tool works 100% on your\nsystem. The registered version will contain many more excellent sysop\nfeatures such as: Nuker, Mover, multiple file transactions (currently, you\ncan only do one file at a time), removal of "Code Under Construction"\nbanner, plus much more.\n\n\n','\n',char(10)),NULL,'auto-added',108126,3,0,NULL,NULL,'dcs_tn2j','scan',1780048474);
INSERT INTO door_catalog VALUES('dcs_tn2z','DCS_TN2Z.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DCS_TN2Z.LHA','TNConfig','XIM','TNConfig',NULL,NULL,'DCS','*[M]ove files (several at once) to any conf. *[E]dit descriptions quick and easy. *[C]opy multiple files anywhere on ya board.',replace('  DCS spurtz ya wid: Turbo Newscan II Pro!\n*[M]ove files (several at once) to any conf.\n*[E]dit descriptions quick and easy.\n*[C]opy multiple files anywhere on ya board.\n*[N]uker searches logs at 398 kb/sec @ 7mhz!\n*[S]uperView: dumps any file to screen.\n*[G]etDIRs: download DIRs fast via ZMODEM.\n*[Z]earch links to any external Search tool.\n*[I]nfo shows uploader and date of any file.\n-Virtual Scroller System! Arrows travel DIR.\n>Don''t jerk around with cheap TN imitations<\n[THE]=--=] cS!-^-sAD-^-hJB-^-KLF! [=--=[PUB]\n','\n',char(10)),'LamerZap.Doc',replace('                     Lamer Zap v1.5 by Mack Lifeguard\n\n\nLamer Zap is a CLI-based utility that will write line noise to a specified\nserial device by using the joystick button.\n\nSimply run the program from your CLI, enter the modem unit number\n(if you have only one modem, enter 0). Then you''re all set, just hit your\njoystick button and watch the modem terminal flood with random noise!\n\nWhy did I write this tool? No idea.. I guess I was feeling evil! hahaha!\n\nEnjoy and don''t make this tool public or it will ruin all the fun. Only\ngive this to your sysop friends.\n\ncya!\n\n','\n',char(10)),NULL,'auto-added',58942,2,0,NULL,NULL,'dcs_tn2z','scan',1780048474);
INSERT INTO door_catalog VALUES('dcs_tz1p','DCS_TZ1P.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DCS_TZ1P.LHA','TurboZ','XIM','TurboZ',NULL,NULL,'DCS',NULL,replace('TURBO-ZIPPY /X-TOOL\n','\n',char(10)),'BLA1.TXT',replace('                 __________________________________________\n                |::::''       __                   ____    ø|\n                |::''        /_/\    ____________  \. /     | \n /\ \ ___  _____:''________/|\_\//\__\____      /_/\\//\____:________\n \/ //   /\   _/  _____/   |   /   __   /     /    \/    _/   _____/\n    /  _/  \_  \  __/___   |__/_   /___/    ./   __  __   \   __/________\n   /            \ /     \  l    \ /    "\  //     \  /     \  /      \  ø:\n  /_____ /\ ____/_______/_______/________\ / \_____\/______/_________/   |\n   LnG \/  \/   :     :        ____      \/    /_/\ .cOLa..:             |\n          :     |  - -o- -     \ ./            \_\/     .::|             |\n          |     |_____:_________\/____________________.::::|   oO..      |\n          |                                          ø:                  |\n  - -->   |                YOU DID JUST ENTER         |                  |\n          |                                           |                  |\n          |                 eMPIrE <> PaLACe          |           !      |\n          |                                           |                  |\n:         |                                           |      <-- -       |\n::.       |                                           |                  |\n:::: - --*-    RUNNING A2ooo / 4omHZ - 1.2GB SPACE -.3 nODES zYX -*-- -  |\n:::.      :______________________________________.::::|                  |\n::::.                              |       -                             |\n:::.         - --> YaR MasTeR iS  : Mr.SONy                              |\n:::.                               |                                     |\n:::::.             aND dA FirsT onE BehiND iS KaNE / DlT <-- -       /   |\n::::::.                            | - -->                          / /  |\n::::::::.                          |_____________________________________|\n::::::::::........    RePLaY foR da nuMbeRs AnD nEw nuPE   ....  .     ...\n:::::::::::::::::::::::::::: IsDN coMMinG SooN :::::::::::::::::::::::::::\n::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::\n','\n',char(10)),NULL,'auto-added',19981,5,0,NULL,NULL,'dcs_tz1p','scan',1780048474);
INSERT INTO door_catalog VALUES('dcs_tz1r','DCS_TZ1R.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DCS_TZ1R.LHA','TurboZ','XIM','TurboZ',NULL,NULL,'DCS',NULL,replace('Turbo ZippySearch .......... .  .   .      .\n','\n',char(10)),'Update.txt',replace('                               Turbo Zippy\n                            By Mack Lifeguard\n                    68000 Code by The Controller & NZO\n\n                                  UPDATE\n\nHere is the real 100% version of Turbo Zippy. The previous version was a\nbeta and not meant to be released.\n\nv1.r\n----\n·Fixed Purged Directory bug. Now all purged directories will be searched\n if they exist.\n·New [K]eyword command now starts searching at the very top of the file\n instead of current position.\n·The [F]lags command now holds 3 lines worth of files and not just 1 as\n before.\n·Scrolling output should be about 5% faster due to some more optimization\n on the output-engine.\n\n-END-\n\n','\n',char(10)),NULL,'auto-added',13772,3,0,NULL,NULL,'dcs_tz1r','scan',1780048474);
