INSERT INTO door_catalog VALUES('dc_v32','DC_V32.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DC_V32.LHA','DC_Collect','XIM','DreamChart . .. . .. . .. . .. . .. . .. . .',NULL,NULL,'DC',NULL,replace('DreamChart . .. . .. . .. . .. . .. . .. . .\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 19:27:10  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,NULL,9547,3,0,NULL,NULL,'dc_v32_dc_collect','scan',1780048474);
INSERT INTO door_catalog VALUES('dd_xim','DD-XIM.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DD-XIM.LHA','xim','XIM','xim',NULL,NULL,'DD','DayDream BBS. Source code included.',replace('AmiExpress (XIM) door emulation for \nDayDream BBS. Source code included.\n','\n',char(10)),'Xim.Doc',replace('\n			  Xim emulation for DayDream BBS\n			  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n  Whats this?\n  ~~~~~~~~~~~\n	Simple XIM (amieXpress Interface Module, i guess) emulation for\n	DayDream BBS. Should be faster than /X itself :) Most of the commands\n	are supported, but not tested, so i included the sourcecode among\n	this, so you can correct if there are bugs :)\n\n  Usage:\n  ~~~~~~\n	xim [node] [door to run], eg:\n\n	c:run doors:xim %N doors:sysdl/sysdl\n\n  Commands that are not support:\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n  Command          | Why\n  -----------------+----------------------------------------------------\n  JH_REGISTER      | Registers when running\n  JH_EF            | Not implemented in DD''s doorport \n  JH_CO            | Not implemented in DD''s doorport \n  DT_RATIOTYPE     | DD has different storage method for these\n  DT_COMPTYPE      | DD has different storage method for these\n  DT_TIMEUSED      | Not implemented in DD\n  DT_DAILYBYTELIMIT| Not implemented in DD\n  DT_DAILYBYTEDLD  | Not implemented in DD\n  DT_EXPERT        | My lazyness, useless command :)\n  ACTIVE_NODES     | Too hodgey format and DD hasn''t 9 node limit :)\n  DT_DUMP          | /X has different format in userbase\n  DT_TIMEOUT       | Not implemented in DD\n  BB_CONFLOCAL     | Not implemented in DD''s doorport \n  BB_LOCAL         | Not implemented in DD\n  BB_STATUS        | Useless\n  SCREEN_ADDRESS   | Useless\n  BB_TASKPRI       | Not implemented in DD, useless for Doors :)\n  RAWSCREEN_ADDRESS| Useless\n  BB_CHATFLAG      | Not implemented in DD\n  DT_STAMP_LASTON  | Lazyness\n  DT_STAMP_CTIME   | Lazyness\n  DT_CONFACCESS    | DD has different storage method for these\n  BB_CALLERSLOG    | Not implemented in DD''s doorport\n  BB_UDLOG         | Not implemented in DD''s doorport\n  BB_CHATSET       | Not implemented in DD''s doorport\n  ENVSTAT          | ENV: suxx, ARexx WHO-doors suck!\n  NODE_DEVICE      | Who needs this?\n  NODE_UNIT        | Who needs this?\n  NODE_BAUD        | Who needs this?-)\n  JH_MCI           | DD has faster method than MCI :)\n  BB_GETTASK       | Bullshit\n  BB_LOGONTYPE     | So you run doors in waiting for call-state?-)\n  BB_SCRLEFT       | Crap\n  BB_SCRTOP        | Crap\n  BB_SCRWIDTH      | Crap\n  BB_SCRHEIGHT     | Crap\n  BB_PURGELIN      | Crap\n  BB_PURGELINESTART| Crap\n  BB_PURGELINEEND  | Crap\n  BB_NONSTOPTEXT   | Crap\n  BB_LINECOUNT     | Crap\n  DT_LANGUAGE      | DD has different storage method for these\n  DT_QUICKFLAG     | What the hell is this crap?\n  DT_GOODFILE      | Crap\n\n	Over 40 commands that are not supported :) Luckily they are crap :)\n\n\n	Some doors may require those dumm infofiles, so assign BBS and\n	do them :)\n','\n',char(10)),NULL,'auto-added',20979,13,0,NULL,NULL,'dd_xim','scan',1780048474);
