INSERT INTO door_catalog VALUES('dds_gu11','DDS-GU11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DDS-GU11.LHA',NULL,'XIM','_________/\    /\_____________________',NULL,NULL,'DDS',': _______  \  / _______               \____ |     \  \  \/\   /                        : :      \____ \ __/  /X GETUPPINYALAMER 1.1 |',replace('_________/\    /\_____________________      \n: _______  \  / _______               \____ \n|     \  \  \/\   /                        :\n:      \____ \ __/  /X GETUPPINYALAMER 1.1 |\n|        \  \  \   THIS IS WORKING VERSION :\n: [DD]    \____/  V1.0 WAS SHIT! BUT STILL |\n| [STYLE]        NICE DOOR WITH BYTE STATS :\n:               JUST TRY AND SEE 4 URSELF! |\n|                                          :\n:xXx.[APL!].xXx.xXx.xXx.xXx.xXx.xXx.xXx.xXx|\n','\n',char(10)),'GETUP.doc',replace('ahum .. eh .. DOCJE!\n                                                                         \n\n         GETUPPINYALAMER V1.1 was written by Apollo of DD Style!\n                                                                         \n\nuh hehe .. 1 day after release I found out that the compiled version\nbugs like hell .. sometime it works, sometime it just crashes ! So\nregard this as V1.1 , with the (same) UNCOMPILED version.. that one\nworks perfectly ! (Also changed the Getup.info from .exe to .rexx !)\n\n\niNTRODUCTION\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nEHhe .. or .. What the fuck is this again ! Another worthless /X util !?\nWell Probably, YES! ehheeh .. but nah since ya got this far, you might try\nit ehhe .. other would be waste of yer download and we doooon''t wanna that,\nuh ? hmm .. guess ya probably wanna know, what does this thingie .. uh ..\nwell .. eh .. .uhm .. not quite sure myself .. it''s supposed to show sum up\n& download info en stuff .. kindda like a door that ya would put in yer\ndownloadmsg.txt and uploadmsg.txt .. at least I did, as far as I am\nconcerned you put it in yer menus eheh .. hmm .. whatta say .. ehhe ..\nlet''s go to another section..!!\n\niNSTALLATION\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nYeck! not even a nice neat C= installer huhu .. well handle urself .. copy\nall stuff to the correct dirs hehe .. next add to yer Downloadmsg.txt and\nUploadmsg.txt the following line:\n\n~CC_GETUP\n\nand make sure the FIRST char in thooz files also is a ~ .. then it should\nwork .. if it doesn''t .. throw it away hehe .. oh .. eheh as ya might have\nnoticed this wasn''t kindda like a project that took much of my time hehe ..\nand .. I didn''t wanna spend too much on it hehe ..so .. Top Uploader\nfunction ain''t working .. ehhehe .. no! it''s not a bug it''s a FEATURE !!\neheh .. nah if you still wanna see your topuppers name in there, write in\nthe doors:UD dir a file named ''TopUpper.txt'' and then my door will read it\n.. ehhe .. cewl, uh ? .. was pretty fuck to read the top upper from\nuser.data stuff .. so .. this worx, only you''ll have to update it once in a\nwhile hehehe .. nah .. too much for installation .. let''s jump ..\n\noTHER sTUFF aND kNOWN bUgZ!\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nHere I''m again! Yez I give to you a list of bUgZ! ehhe .. \n\n- My util can''t fix nr''s , so 257.8 MB will just bs 257 MB ! sOllY! (NOT!)\n- nEW uSERz that up 100KB and not yet down, have upped 100 times as much as\n  they downed, that will bomb them in the commentline to a VERY GOOD\n  TRADER .. ehhe .. Was too lazy to write more extensive routines !\n- hMM eheh .. wonder what will happen when up or down are 0 bytes hehe .. \n  Dividing by zero ehhe .. cOOL! Try IT hehe .. \n- And V1.0 compiled version BUGS .. So here is V1.1 ! eheh\n\nwELl the title says that I need to write more stuff in here .. huu .. nah\niF ya really like thiz util (Yeah Sum dudes DO, I already found out hehe),\nand want a sum better version etc maybe if enuff response , I will improve\nsum in thiz util ehhe .. prog my own fixing of nr''s and add topupper etc\n..eheh .. but don''t wanna have amigaguide dox ehhe .. \n\n\ncONTACT mE?\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n     sTONEHENGe - dDs eHq - hOMe oF tESTNEt mAILNEt - dEATh mUSIc hQ     \n                                                                         \n                     + 3 1 - (0) 5 4 1 3 - 5 5 0 7 3                     \n','\n',char(10)),NULL,NULL,27421,1,0,NULL,NULL,NULL,'scan',1780048474);
INSERT INTO door_catalog VALUES('dd_tr112','DD_TR112.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DD_TR112.LHA','Append','XIM','Append',NULL,'|','DD','==/      /  \   /  \       /     \   |====== \      \   \__\   \_   _/   ___/   |____ ==/  |\  \\   \_/   //   \\   \__|        \=',replace('   ___________________________________\n==/      /  \   /  \       /     \   |======\n  \      \   \__\   \_   _/   ___/   |____\n==/  |\  \\   \_/   //   \\   \__|        \=\n /        \\       //     \\     \   ___   \\n/   ______/=\_____/=\_____/=\____/   \ |WHW|\n\__/ D    R    E    A    M    S  |___/ |___|\n| TimeReq V1.12:For Those Without A Clock! |\n| TRT: added (1.1) Files added (deleted by |\n| /X LHA strip)(1.11) Language supp.(1.12) |\n+-------> Written By /\PoLLo / DD <--------+\n','\n',char(10)),'TimeReq.doc',replace('\n                               TimeReq (TR)\n                               ~~~~~~~~~~~~\n\n                           Version 1.12 (2-3-94)\n                        Made by Apollo/Dutch Dreams\n                        ~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                    Consider this still a beta version,\n                    I didn''t test it trough and trough !\n                        (Imagine what V1.0 was ....)\n\n\nPREVIOUS V1.0 USERS!\n~~~~~~~~~~~~~~~~~~~~\n(for those who don''t read docs)\n\nYou have to read the whole docs again, major changes have been made !\na BIG new feature was added, whole utility based on this now !\nIn the doc of V1.0 stood that you had to add ''Execute s:TR'' to your\nuser-startup. Delete this line, otherwise your User-Startup will be\nhalted when encountering that line !\nDo this before installing this new version !\n\n\nIntroduction\n~~~~~~~~~~~~\nOr.. What it this supposed to be ?\nWell, I am running a BBS, and the correct time in my system is very\nimportant to run this BBS, especially for the scanning for new files.\nSo.... This is a utility in DOS scripts, which tries to keep the correct\ntime in the system, when you do not have a clock (yet) in your Amiga (1200).\nThis is accomplished by creating a very small device called TRT:, and a\nspecial task will write the time to that device, where it will be read from\nevery startup.  Of course this is not 100 % accurate, the time between\nreset and restart the timewrite task isn''t active, so the time will be a\nfew seconds behind when you have restarted the system.  Also when you want\nto start from disk, like playing a game, the task isn''t active, so the time\nwill be behind lotsa minutes when you restart the system.  Therefore on\nevery startup, a small window will pop up, showing the system time, and\nasking you whether you want to change it.  A simple return will close the\nwindow immediately, to stop it annoying you.  I think this is a lot nicer\nthen a big ugly screen to set the time on every startup, also when you\ndon''t care about the time.  I wrote this to be able to set the time\nquickly, but not every time I reset my computer.  When I don''t care about\nthe time, a simple return would remove the window. Also the trt: would keep\nthe time as good as possible, so I would have to bother about setting the\nright time as less as possible.\n\nInstallation\n~~~~~~~~~~~~\nI have included a installation utility, also a script. You have to be in the\nTimeReq directory to start it. just type ''Execute TR-Install'' to start the\nscript. Do not rename this script, or move it out of its location in the\nTimeReq directory, if you do the script won''t work. \nThe script self-detaches from the CLI.\nThe script uses several commands, almost all of ''m are standard AmigaDos\ncommands, most are even resident, some should be in your C: directory. The\nfew I wasn''t sure of whether they were included with the standard\nWorkbench, I included in the archive, they will be copied to your C:\ndirectory. Once installed, you should leave the names of the scripts just\nlike they are currently named, if you change that, the whole utility won''t\nwork. A few lines will be added in front of your user-startup, to set\nthe system time from the trt: device, and to pop up the timerequester.\nThis will be done automatically by the installation util, installing by\nhand is highly unrecommended !\nAlso the installation util will check whether you have installed TimeReq\nV1.0, and delete the file coming with this. It can''t alter the user-startup\nto remove the line added by TimeReq V1.0 users, (Execute s:tr), so those\nusers will have to remove this particular line themselves, before\ninstalling TimeReq V1.1 !\n\nRequirements\n~~~~~~~~~~~~\nWell..  The TimeReq popup window uses the ''Time'' preferences utility from\nWB3.0 to set the time, so you will probably need Kick 3.0 for that, but I\nam not sure of this.  This doesn''t mean you can''t use this utility on lower\nkickstart versions, just use another (WINDOW based) utility to set the\ntime, name it ''time'' and put it in the path of your system, preferably in\nthe C:  directory. A major difference however is, that Kickstart 1.3 does\nnot use the devs:dosdrivers.  I have added in the Devs dir a replacement\ntext which should be added to the mountlist, in your Kick 1.3\nstartup-sequence you should add, by hand, ''Mount TRT:'' ..  And the\ninstallation script uses the ''S:User-Startup'', just make an empty file in\nyour s: dir, with this name, before starting the installation.  In your\nStartup-Sequence you should add ''Execute S:User-Startup'' to activate this\nscript, but after installing it is possible as well to put the contents of\nthe new User-Startup script in the Startup-Sequence.  So far for the 1.3\nusers.  I haven''t tested none of this, by the way !!  (Most of you probably\nalready have a clock in your computer anyway, so they won''t be needing\nthis) Also, on lower kickstart versions, you probably need some more\ncommands in the path of your system, but these command will probably be in\nyour path anyway, because they are very basic dos commands, usually located\nin the C:  directory.  Consider buying a clock fast (I do!), much easier\nthen using this utility ;) This utility should be compatible with Kickstart\n2.0, I guess.\n\n\nHISTORY\n~~~~~~~\n\nVersion 1.0\n~~~~~~~~~~~\nThe first step. Needed a utility like this, of course I could have set the\n''time'' utility in the startup, but then there would  always be opened a big\nwindow, whether I cared to set the correct time or not.\nThis way, a Return was enough to get rid of the nice small window.\n\nVersion 1.1\n~~~~~~~~~~~\n\n- V1.0 contained in User-Startup a line ''Execute s:TR'', delete this line !\n- V1.1 doesn''t need S:TR anymore, will be deleted by new Installation\n  script.\n- The BIG step. Added the TRT: device to store the time in, using a special\n  task, started upon every startup of your system. After a reset, TimeReq\n  will extract the time from this device, and will use this as the new system\n  time. The TimeReq popup window is just a part of the util, to set the time\n  when the time is too far behind.\n- Included Install-TR, to install automatically. Installing by hand is too\n  difficult.\n- Included Remove-TR, to remove TimeReq from the system (maybe for the little\n  bit mem that TRT: uses or whatever. After Reset, TimeReq is back in system)\n- Included Destroy-TR, to Destroy TimeReq from System. It will be deleted\n  from your system, only use when you bought yourself a clock ! ;)\n\nVersion 1.11\n~~~~~~~~~~~~\n\n- The files ''User-Startup.Add'' and ''Mountlist13.Add''\n  often were deleted by most /X LHA strippers ! Arghhh !!\n  Renamed them to ''User-Startup.addition'' and ''Mountlist13.addition''.\n  Also changed the installation script of course.\n\nVersion 1.12\n~~~~~~~~~~~~\n- Optimized code in the Install utility a bit.\n  I didn''t think of systems using another language then English,\n  so when entering the month in another language, the install utility\n  would quit. Added a check to see whether the entered date is accepted.\n  People previously using 1.11, don''t have to update, no changes made to\n  other code. I only changed the version numbers in all code.\n  Thanks to Prof B-Rom for the bug report !!\n\nWhat''s with this utility ?\n~~~~~~~~~~~~~~~~~~~~~~~~~~\nFile_Id.Diz                      487\n\n  TIMEREQ                        Dir\n     TimeReq.doc                8748\n     Destroy-tr                 2681\n     Install-tr                 5572\n     Remove-tr                  2800\n\n       DEVS                      Dir\n          Mountlist13.Addition   225\n\n            DOSDRIVERS           Dir\n               Trt               192\n\n       S                         Dir\n          TR1.bat                565\n          TR2.bat                 89\n          User-Startup.Addition  298\n\n       C                         Dir\n          Append                4588\n          Time                 13028\n          Time.info              587\n          date                  1092\n\nSpread, but keep it intact !\n\nWhat''s in store for the future?\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nHmm..  not much, I guess. Just the removal of bugs, which probably are\npresent in this util... If you find some, please contact me. Maybe,\nAmigaguide installation and Commodore installer scripts.. Dunnu, the last\none is a LOT of work for a util like this..\nIf this util needs improvement, or change or whatever, just let me know.\nAlways willing to adapt the script to ones special purposes.\n\nHow to reach me..\n~~~~~~~~~~~~~~~~~\nReach me on my BBS:         STONEHENGE\n                              DD Ehq \n                          +31-5413-55073\n\nJust leave me (Apollo) a comment or chat me..\n\nCopyright notices\n~~~~~~~~~~~~~~~~~\nNone at all. Just do me a favour and keep my name, and this document, along\nwith the utility.\n','\n',char(10)),NULL,'auto-added',27259,8,0,NULL,NULL,'dd_tr112','scan',1780048474);
INSERT INTO door_catalog VALUES('decidoor','DECIDOOR.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DECIDOOR.LHA',NULL,'XIM','____ DeCimAL - InfoX',NULL,NULL,NULL,'_  __/___/___ _______________________ ____ _ ______    \\  _______/\          //   / /    /    //\/  ___/_ /    /____//   /',replace('       ____ DeCimAL - InfoX\n _  __/___/___ _______________________ ____\n  _ ______    \\  _______/\          //   /\n    /    /    //\/  ___/_ /    /____//   /\n  _/    /    //    (o o)//    /    //   /\n +----------''+--ooO-(_)/Ooo------------+>/|\n |    DD Doors - Pager v1.1 - LogOff v2   |\n `----------------------------------------''\n','\n',char(10)),'LogOff.DOC',replace(' ------------------------------------------------------------------------\n                                 _      _\n                                /¬\    /¬\\n                                \  \  /  /\n                    .    .-«ThC»-\  \/  /-------.  ·  .\n                 .    ·  `--------\    /--------'' . .\n                    .  .  . ·     /    \      ·   .   . ·\n                 . ·.  .    .    /  /\  \     . ·   . ·\n                 .:.:.:.:.:.:.  /  /  \  \  .:.:.:.:.:.:.\n               .:::::::::::::::.\_/    \_/.:::::::::::::::.\n                         »»» +44(0)1633 274583 «««\n ------------------------------------------------------------------------\n\n   LogOff v2 - LogOff v2 - LogOff v2 - LogOff v2 - LogOff v2 - LogOff v2\n\n                       d e c i m a l   /   I n f o X\n\n\nGreets Peeps, this is my 3rd door for daydream, it is a Log off door,\nit has many options, it has a built message to next user routine,\na menu to page the sysop, Enter a comment to sysop, Quick logoff or\nlogoff with BBS Ansi/Askii adverts.\n\nTo install this door.............\n\nCopy................. \n\nlogoff.dd\n\nto \n\nDoors:Rexxdir/\n\nCopy.................\n\nLogfiles/Next\n\nto\n\nDaydream:logfiles/\n\nCopy.................\n\nConfigs/LO.cfg\n\nto\n\nDaydream:Configs/\n\nEdit your config to include this :-\n\nDOOR_COMMAND.. G\nDOOR_TYPE..... 1\nDOOR_SECURITY. 5\nDOOR_EXECUTE.. DOORS:Rexx %N doors:rexxdir/Logoff.dd\n\nARCHIVE CONTENTS\n\nDocs/LogOff.DOC\nDoors/Rexxdir/LogOff.DD\nLogfiles/Next\nConfigs/Lo.cfg\n\nUsing this door, Press the key to start the door, and the press S\nfor the Sysop menu...\n\nMenu.......................Enable/Disable Menu\nMessage 2 Next.............Enable/Disable Message to nest user\nAdverts....................Enable/Disable any adverts\nAdverts Both Sets..........Enable Elite to see both Elite & Normal adverts\nPager Type.................Default Pager type (DayDream or Pager.DD - By me)\nRandom Adverts.............Random display of adverts\nRandom Replies.............Typing random when replying to a message will leave\n									a random reply\nElite Adverts (8 Max)......How many Elite adverts you are using *\nNormal Adverts (8 Max).....How mann Normal adverts you are using **\nElite advert access........Access level or greater to Elite Adverts\nAccess level to this menu..Access Level to access sysop menu\nOops option................Menu option "Oops" Enable/Disable\nBye Bye Option.............Menu option "Bye" Bye Enable/Disable\nPage Option................Menu option "Page" Enable/Disable\nComment Option.............Menu option "Comment" Enable/Disable\nQuick Log Off Option.......Menu option "Quick LogOff" Enable/Disable\nAdvert options.............Allows you to Add/Delete/Edit Advert Paths &\n									filenames ***\n\n*\n\nIf Random adverts is off and adverts is on, then this number will be the\nadvert permanently shown to Elite users..\n\n**\n\nSame as above but for Normal Adverts/Users\n\n***\n\nChoose 1 - 16\n\n1 - 8   is the first set of 8 - Elite adverts\n9 - 16  is the second set of 8 - Normal Adverts\n\nType Path and filename of advert to show.....\n\nie.\n\nDaydream:adverts/InfoXAd.TXT\n\nor \n\n"*"\n\nTo erase current advert....\n\nCall my bbs on the number above for more FUNKY Daydream stuff......\nThanx to Antti for a really Kewl BBS program. (Sort out the bugs :))\n\nGrEeTs To.....\n\n$|<iTtLe, EaZY, Antti, OrSon, Big H!\n\nUntiLl The Next oNE . . . . .\n','\n',char(10)),NULL,NULL,7848,1,0,NULL,NULL,NULL,'scan',1780048474);
INSERT INTO door_catalog VALUES('dfbv13','DFBV13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DFBV13.LHA','append','XIM','DFBArchivers',NULL,NULL,NULL,'| ANDReW     /\__  _______/\__             : :  LePPaRDs |    \|  ____/    \   -Dynamic | |           | _ \ \  __/ | / _/   -File    :',replace('+-=-=-=-=THe FiLE SySTeM FRøM HeLL-=-=-=-=-+\n| ANDReW     /\__  _______/\__             :\n:  LePPaRDs |    \|  ____/    \   -Dynamic |\n|           | _ \ \  __/ | / _/   -File    :\n:          :|  \/ / |::::| \/  \: -Base    |\n|        :::|__  /l_j::::|___  /:::        :\n:     .::::::::\/::::::::::::\/::::::.     |\n|  CoMPLeTE New FiLE SYsTEM FoR MAX''S BBS  :\n|  ASM/C CODeD- AN ARSE-KiCKiN PACKAGE :   :\n|     EVaLUaTioN VERSioN oNLY - V1.3       |\n`------------------------------------------''2','\n',char(10)),'DFB.guide',replace('@database DFB.guide\n@master hd2:DFB/DFB.guide\n@remark Created with Heddley v1.1 (c) Edd Dumbill 1994\n@remark Heddley Bugs Fixed with FixHeddley 1.2 (c) 1995 by David Zvekic\n\n@node "main" "DFB V1.3 Documentation"\n\n             Welcome to the Dynamic File Base user''s manual\n\n Select on any topic to continue...\n\n @{i}Initial...                      Programmes...@{ui}\n \n    @{" Disclaimer               " link "disclaimer" 0}     @{" ReadDFB                  " link "ReadDFB" 0}\n    @{" Copyright                " link "copyright" 0}     @{" DFBPrefs                 " link "DFBPrefs" 0}\n    @{" Requirements             " link "requirements" 0}     @{" DFBSection               " link "DFBsection" 0}\n    @{" Introduction             " link "introduction" 0}     @{" DFBUser                  " link "DFBuser" 0}\n    @{" Installation             " link "installation" 0}     @{" DFBArchivers             " link "DFBarchivers" 0}\n    @{" How to use/Hints/HELP    " link "howtouse" 0}     @{" DFBLogin                 " link "DFBlogin" 0}    \n    @{" What''s new for V1.2/1.3  " link "whatsnew" 0}     @{" Utilities                " link "DFButes" 0}\n    \n @{i}Final...@{ui}\n    \n    @{" Feature list             " link "features" 0}     @{" Future of DFB            " link "future" 0}\n    @{" Credits & Greetings      " link "credits" 0}     @{" Developers               " link "developers" 0}\n    @{" Registration             " link "registration" 0}     @{" History                  " link "history" 0}\n@endnode\n\n@node "disclaimer" "Disclaimer"\n\n This programme and its documentation is provided ''as is'', the author\n cannot be held liable or responsible for any damage which might be caused \n directly or indirectly by the use or misuse of this programme, any damage\n caused is the sole responsibility of the user. So nyaah.  \n\n@endnode\n\n@node "DFButes" "Utilities"\n\n Files in the utilities drawer:-\n\n File            Brief Description                       Author\n ----------------------------------------------------------------------- \n DFBFlg          A file list generator for DFB.          Me\n DFBCheck        Keeps track of DFB/HD files.            Me\n DFB_UserStats   Displays users'' statistics using DFB.   Prowler/Cydonia\n DFB_TagShow     Lists tagged files and lets user        Greg Fitch\n                 delete them.\n DFB_TagKill     Kills users'' tagged file list.          Greg Fitch                  \n@endnode\n\n@node "disclaimer" "Disclaimer"\n\n This programme and its documentation is provided ''as is'', the author\n cannot be held liable or responsible for any damage which might be caused \n directly or indirectly by the use or misuse of this programme, any damage\n caused is the sole responsibility of the user. So nyaah.  \n\n@endnode\n\n\n@node "history" "History"\n Version   Date       Comment\n\nV1.0      14/02/95   Initial release.\n\nV1.0a     19/02/95   Thanks to Greg Fitch, for doing some impromptu beta-\n                     testing of DFB on a 68000, who located many bugs! \n     \n                     Bug fixes in ReadDFB now means it can also run on a 68000\n                     based machine. A problem with one of DFBUser''s requester\n                     has now been fixed. In DFB.library TimeToAscii &\n                     DateToAscii have been fixed, also an oversight in\n                     GetUser has been fixed, a routine to Add/Modify user\n                     has been enhanced.\n                     \n                     In DFBSection, clone section now works on a 68000\n                     also a small bug which could save the wrong readings of \n                     the cycle gadgets has been fixed. \n                    \n                     DFBPrefs, when creating the file base and file_id.dizs\n                     are off, no longer checks whether the files exist or\n                     not - speeding up installation time enormously.\n\nv1.0b     05/03/95   In DFBPrefs ratios 2 & 3 are now around the right way for\n                     enhanced members. DFBUser should now be more stable.\n                     Now there is only one registered file to get: DFB.library\n                     DFBArchivers now doesn''t crash if you try to restore or\n                     backup files when you haven''t set the backup file\n                     name. \n                     \n                     When checking a user''s information from ReadDFB the first\n                     conference ratio''s stats are shown as opposed to the\n                     sum of all the conference ratios (which was generally a\n                     useless result and didn''t add up anyway).\n          \n                     When changing file listing direction in ReadDFB it \n                     missed a file - this has now been fixed.\n\n                     ReadDFB now excepts the numbers 8,2,4,6 as up, down\n                     left and right for those that don''t have arrow keys.\n\nv1.0c     02/04/95   Edited requesters, now should hopefully work with ARQ.\n                     Fixed - listing files after date; also if a user is sleep\n                     disconnected after uploading files the files are now\n                     added to the file base. (only aliased sections had this\n                     problem before.). A bug with reverse listing introduced in\n                     v1.0b has been fixed. \n                     \n                     Now handles MAX''s % control codes - adding them to\n                     the file name, uploader, alias or file description will\n                     not activate the commands.\n\n                     Now displays user''s upload/download info before and\n                     after downloads and also after uploads.\n\n                     Now displays number of files listed and total files after\n                     each file listing.\n\n                     The remote file editor can now zot files and nuke \n                     uploader credits.\n\n                     Added ''save'' and ''next ->'' buttons to the user and section\n                     editors.                        \n\nv1.1      15/09/95   Re-coded the reading routines, ReadDFB is now up to 400%\n                     faster when listing files, also ReadDFB should now be as\n                     stable as a stapled down rock.\n\n                     DFB.library now has expunge code in it for tight \n                     memory users (flushlibs from debug menu on Workbench\n                     will now remove it).\n\n                     The ''i'' key in ReadDFB now displays more information\n                     including how many files listed so far and the total\n                     number of files.\n                     \n                     The local file editor can now change the file size.\n\n                     The local upload requester now remembers your last upload\n                     directory so you do not have to keep setting it every\n                     time you use it. Similarly with the position of the \n                     ''go to user'' gadget in the user editor.\n\n                     ReadDFB only asks for upload alias and displays upload\n                     information if more than 0 files were transferred on\n                     upload.\n\n                     DFB now does not crash if it loads in a tagged file\n                     list (DFBML. file) of 0 bytes.\n\n                     DFBArchivers now has a ''default'' option so DFB can \n                     process files with no extensions. (Thus viewing files\n                     online with no extension is possible.)\n\n                     Users can no longer upload to a section which is offline.\n                     Hotkeys added to GUI''s! Example: <esc> exits windows\n\n                     The displaying of uploader/alias now works _perfectly_!\n\n                     DFB now supports headers! You can now add a different\n                     text message at the start of every file list and\n                     also you can change the colours every file list.\n\n                     Hopefully the infamous ''155'' problem is now fixed and\n                     even if it hasn''t ReadDFB has some ''smart'' code to,reduce\n                     (read eliminate) the problem.\n\n                     Created the layout file: longfileid.lay which allows up\n                     to 20 line file_id.dizs.\n\n                     DFB now does not crash if it encounters file names of \n                     0 bytes (this did happen!). (This IS the reason that\n                     the release of DFB 1.1 was delayed).\n\n                     DFB now has code to detect corrupted files in the\n                     file list and cleans them up before it displays them.\n\n                     Wrote the DOS command Zot which can remove files\n                     from the file list so you can remove files without\n                     entering ReadDFB.\n\n                     Wrote DFB''s File List Generator programme - DFBFlg.\n                     (Now available in the utilities directory)\n\nv1.11     12/01/96   The BenchMaster release... :-)\n\n                     ''ReadDFB last R'' now works properly !\n                     Speeded up ''ReadDFB last'' so it gets to displaying\n                     the new files a lot quicker. No more waiting 10 \n                     seconds to be told that there are no new files!\n\n                     Fixed the standardshort.lay so there is now always\n                     a space between date and size of file.\n                     \n                     Created a new layout file:- shortnouploader.lay\n                     Modified the ''header'' code, should now work properly.\n              \n                     Downloads now do not convert the file names to lower\n                     case.                     \n\n                     You can now edit the N,L,O,D and + flags when using\n                     the ReadDFB N, ReadDFB O etc options.\n\n                     DFB can now extract file descriptions from file\n                     comments (filenotes).\n\n                     DFB''s file description editor has FINALLY been finished!\n                     For those that don''t rely heavily on file_id.dizs.\n\n                     Lots of minor fixes including the ''one weird character\n                     displayed'' bug. Also fixed the rare ''28-char bug''.\n\n                     Created a new layout file:- longdesc.lay\n\n                     Added DFBPrefs purge CLI option.\n\n                     Fixed a 1.1 AddFile()/Installation bug.\n\nv1.2      23/05/96   Changed ''marked'' to ''tagged''. Now says ''Searching...''\n\n                     DFB now handles ''missing'' libraries properly, including\n                     DFB.library and very low memory situations.\n                     \n                     Fixed a bug which caused the screen length to be set to \n                     zero.\n\n                     DFB now supports free file sections.\n                     \n                     Changed the registration file method for the second\n                     time. Registration now comes in the form of a keyfile.\n\n                     Wrote DFBMakeKeyFile so registered users can use\n                     the public release and not need to get anything from me.\n\n                     DFB is now 1 year old and still going strong \n\n                     Round 2: Andrew Leppard vs. 199 problem. Now DFB\n                     changes the pause flag not the screen length.\n\n                     New command in login will now totally remove the 199 /\n                     pause flag problem. (DFBLogin)\n\n                     If a user uploaded files without leaving file \n                     descriptions, DFB will now get them to enter the file\n                     descriptions at login. (DFBLogin)\n\n                     DFB now handles corrupt user bases a little better.\n\n                     Wrote DFBCheck to keep track of your BBS files - a\n                     CheckFiles replacement for MAX''s.\n\n                     The manual has been spell- and grammar-checked by The\n                     BenchMaster.  \n\nv1.21     04/07/96   dfb.library now uses MODE_OLDFILE instead of\n                     MODE_READWRITE. The latter doesn''t seem to work\n                     the same for AFS. DFB now works with Ami-FileSafe!                    \n\n                     Not an official release!\n\nV1.3      13/04/97   The sysop can now edit files through a remotely\n                     connected user''s account. No matter what the user''s\n                     access level. \n\n                     Improved multiline synchronization, DFB now has waits\n                     around certain commands to prevent two nodes running\n                     them at the same time.                     \n\n                     DFB now deletes file protected file_id.diz''s after it \n                     has extracted them.\n\n                     Wrote MaxsPatch to allow programmers to take over\n                     MAX''s serial device, it also fixes the pens to make MAXS\n                     use the WB2 3D window look.\n                     \n                     Totally rewrote the local file editor, now takes\n                     advantage of the ''new look'' WB 2. Moved the window''s\n                     9k of old code into the library to lower memory\n                     needed for multiline BBSes & speed up loading of ReadDFB.\n                     Another result of this rewrite is that the checkboxes\n                     *finally* look right (they used to look weird but\n                     always worked). Also the text section search now works.\n                     \n                     Added a Save button and a new Needs Description checkbox.\n  \n                     Now a copy of the preferences is kept in memory, so\n                     the preferences aren''t loaded in everytime ReadDFB\n                     is run. This speeds up loading and decreases memory\n                     size by anywhere up to 25k for a large BBS per node.\n\n                     Added click to do ''Nothing'' buttons on DFBCheck so\n                     people who click a lot won''t accidently delete files.\n                     Fixed the PurgeFileBase menu option, it never ever\n                     worked. Now added a requester to tell the user\n                     if he needs to close down any DFB programmes for the\n                     purge menu to work.\n                     Also added a ''Click to edit'' button which allows users\n                     to editfiles from DFBCheck.\n\n                     DFBFlg can now generate file lists in Amigaguide and\n                     HTML format.\n\n                     DFB now has an installer/updater script for the\n                     C= installer programme.\n\n                     DFB is two years old!\n@endnode\n\n@node "copyright" "Copyright"\n\n DFB is copyright 1994-7 by Andrew Leppard. DFB may be freely copied as \n long as the following conditions are upheld:\n  \n 1) No ''registered'' file of DFB is copied/re-sold/lent/borrowed to other(s).\n    Where ''registered'' refers to a DFB.library file which has downloading\n    enabled, or a DFB key file.\n     \n 2) No fees are charged in the copying process, non-profiting distribution\n    fees exempt.\n     \n 3) Authorization must be given for this programme to appear on cover discs,\n    magazines etc. Fred Fish and Aminet already have my permission to \n    carry this programme.\n\n 4) None of the files are to be modified or split up.\n@endnode\n\n@node "requirements" "Requirements"\n DFB requires WB2.04 or higher, it requires MAX''s BBS running with (initially)\n at least one file section. It''s recommended that MAX''s BBSs running DFB\n should have at least 1.5 megs of memory. Also at least an 8 colour Workbench\n is recommended for viewing the icons :-)\n@endnode\n\n@node "introduction" "Introduction"\n\n Liquid Softworks is proud to present V1.3 of this programme... \n\n Firstly, welcome to DFB the dynamic file base system for MAX''S. I must say\n now that if you plan to use this programme I *strongly* recommend you to\n read _ALL_ of this manual - some features are NOT obvious and may do things\n other than you originally thought they would. (Its a case of RTFM again)\n \n So what is DFB? DFB is a complete file base replacement system for MAX''S\n BBS. Many doors and utilities have come about offering enhancements for\n MAX''S namely: free file downloads, log off after transfers, byte ratios,\n file_id.diz support. DFB has all of these features and plenty more. There\n is a @{"Feature List" link "Features" 0} of DFB included in this documentation for exactly what \n DFB can do. For what DFB can''t do see the @{"Future" link "Future" 0} section.\n\n@endnode\n\n@node "installation" "Installation"\n \n Installing DFB is relatively simple to do, just follow these steps:\n (Or run the given install script!)\n\n 1) DFB must know where to find its files, so before running any DFB \n    programme you must have these directories assigned:\n    \n    (Add the assign commands to your user-startup, such as:\n    \n    assign DFBdata: dh2:maxs/doors/DFB/\n\n    which means DFB will keep its file data file in the directory\n    dh2:maxs/doors/DFB/ )    \n        \n    DFB:       This contains the programmes: @{"DFBPrefs" link "DFBPrefs" 0}, @{"DFBUser" link "DFBuser" 0}, @{"DFBSection" link "DFBSection" 0}\n                                             @{"DFBArchivers" link "DFBarchivers" 0} & @{"ReadDFB" link "ReadDFB" 0}\n \n    DFBdata:   Contains the data file DFB.data (created on installation)\n\n    DFBPrefs:  Contains the data file DFB.prefs           ''''\n    DFBusers:  Contains the data file DFB.users           ''''\n    DFBtag:    Contains the users tagged files\n\n 2) Then type from CLI:\n \n    copy DFB.library libs:\n\n    Also copy all of these files: DFBuser, DFBsection, DFBarchivers, DFBPrefs\n    & ReadDFB to the path you assigned DFB: to.\n\n 3) Reset the computer so the assign commands are run.\n\n 4) FOR CONVERTING MAX''s BBS files over to DFB:\n \n    Now run DFBPrefs and follow its instructions. DFB will tell you that\n    it is not installed then it will allow you to edit your preferences.\n    To install DFB just exit the programme and confirm that you wish to\n    install.\n\n    Warning! Before you install DFB (step 4) make sure the following are\n    set right:\n    \n    1) Ratio type: File,Byte or Credit. After installation you cannot change\n       this.\n    2) Use File_id.dizs: If you want to use them make sure this is set for\n       obvious reasons! You can change this flag after installation if\n       you wish.\n    3) Go into Archivers, if you are using file_id.dizs''s fill out the two\n       left-most columns now.\n\n 5) Now edit MAX''S BBS''s menu text so it runs ReadDFB instead of referring\n    to the old MAX''S file base. See @{"ReadDFB installation" link "ReadDFB_install" 0} for more details.\n\n 6) Install @{"DFBLogin" link "DFBlogin" 0}, to do so: copy the file DFBLogin to BBS:Doors/DFBLogin.\n    Then add to the file BBS:Doors/IntroDoor.text the line \n    \n    DFBLogin\n\n 7) You can add extra files in (i.e., not from MAX''s BBS) using standard\n    DFB upload functions. Such as: using the command ''ReadDFB up'' which \n    puts DFB into direct upload mode. You can then upload files in using \n    the asl requester.\n    \n    If you have the flag ''Use File_id.dizs'' selected (in DFBPrefs) DFB\n    will then try and use file_id.diz''s as file descriptions.\n \n    If it can''t find a file_id.diz or you do not wish to use file_id.dizs\n    DFB will then check to see if the file has a filenote (ie a ''comment''\n    displayed when you list the file from the CLI), if it does have one\n    DFB will then ask you whether you wish to use that as the file \n    description.\n    \n    (Note: DFB will only ask this question once per ''batch'' upload, ie\n    if you upload 200 files in one go, DFB will only ask you the first\n    time it encounters a file comment - it will then assume that what you \n    answered applies to the remaining 200 files.)\n@endnode\n\n@node "HowToUse" "How To Use"\n\n After installation you still have to configure MAX''S BBS to use\n the DFB files. The file @{"ReadDFB" link "ReadDFB" 0} is the MAX''S front end for DFB, this \n programme will list files, upload files, download files etc. Put this in \n the menu boxes and run it as you would run any other door programme. \n\n ALSO: it is necessary to delete line 182 from your MAX''S config files, this \n line is a ''press return to continue'' and occurs after download. If you\n do not do this DFB will send files one by one and wait for the user to\n press return after each.\n\n It is recommended for your users to have auto-download enabled so that their\n files are not transferred one by one.\n \n @{"DFBPrefs" link "DFBPrefs" 0} is a general preferences front-end. It includes buttons so you can\n immediately jump to the following four editors:\n\n @{"DFBSection" link "DFBSection" 0} is the section editor, if you need to add a section, modify \n a section or delete a section do it with this. After installation DFB\n ignores the MAX''S sections. You need at least one file section at all times!\n \n @{"DFBUser" link "DFBUser" 0} is the user editor, if you need to change a user''s file ratio,\n upload signature etc. use this. Do not edit any ''file'' information from the\n MAX''S user editor - this will not be recognized by DFB, DFB only reads this\n information at installation time.\n \n @{"DFBArchivers" link "DFBArchivers" 0} controls the archivers used with DFB. It also controls the\n following:\n \n 1) What command to execute to @{"extract file_id.dizs" link "DFBarchivers_extractor" 0}\n 2) What command to execute when someone @{"uploads a file" link "DFBarchivers_upload" 0}\n    (Example: should DFB add in a ''bbs ad''?)\n 3) What command to use to @{"view files" link "DFBarchivers_list" 0}\n    (i.e., when a user wants to view a file what should DFB do?)\n 4) Automatic @{"back-up of DFB files" link "DFBarchivers_backups" 0}\n\n Run the File Manager at least once a week - this will keep your files in\n order.  \n\n @{"DFBLogin" link "DFBlogin" 0} makes sure the user''s pause flag is on\n and also checks to see if the user uploaded any files without leaving\n a file description. If the user did it gets the file descriptions and\n updates the file base.\n \n @{b}Problems@{ub}\n \n 1) A few people have found problems with DFB not finding files (generally in\n certain sections). \n \n First of all, when DFB uploads a file it uses the file path found in the\n DFB section editor. When DFB searches for a file it uses MAX''S File paths.\n Remember to include trailing ''/''s on file paths in both programmes!\n Also if you do edit MAX''S file paths you *must* reset your computer before\n DFB notices the changes or select flushlibs from the Workbench menu\n (this requires you to bootup Workbench with the loadwb -debug option).\n \n 2) If you''re a registered user and you are wondering why some of the new\n features aren''t kicking in (Such as the ''default'' gadget in DFBarchivers) \n it may be due to the fact that you have an ''old'' DFB.library. The release \n 1.1 is considered the minimum. Doing a version command check that your \n library is at least version: 1.6. (NOTE: the version command gives a \n DIFFERENT reading than the release version, release 1.1 will give version \n 1.6 on DFB.library. Confused?)\n  \n 3) You''ve just installed V1.2 of DFB and are ready to go, you list\n files and WEIRD!!! The description has combined with the date??? What''s\n going on??? Well a minor problem in V1.1 and below was overlooked in\n the design stage - but LOOKED ok in most layouts. Basically this has\n been fixed and the layouts have been modified to look ok. This means\n you may need to use the new layouts included in this release.\n \n How to do:-\n \n Go into DFBPrefs, go to the layout box you wish to change. Change one\n letter from upper->lower case or vice versa. This tells DFBPrefs to\n ''reload'' the layout file into the preferences settings.\n \n (The upper->lower case trick ''fools'' DFB into thinking it''s a different\n layout so it goes to load the layout again.)\n   \n 4) SHOCK HORROR! Here''s the scoop shoppers, you are wondering lonely\n as a cloud, you spot one of your friendly files encumbered with\n a _wait for it_ CORRUPT file_id.diz!!! But it gets worse, DFB.. in a\n fit of RAGE exits from ReadDFB (it does this when it gets REALLY confused)\n so you figure AHA I''ll just delete this file from my DFB.data file!\n \n Then you realize, if I can''t tag the file... because it exits, how do I\n kill it?? Well new for V1.1 I have written a command called Zot.\n (It''s in your c directory in the DFB archive)\n \n You can run it like:\n \n zot <file>\n \n and then this command will hunt down the offending file and remove it\n from the file list. Simple.\n \n @{b}Housekeeping@{ub} \n\n It is important to ''purge'' the file base regularly, this tidies up\n the file base and removes any possible corruptions in it. If you find\n DFB is acting mysteriously when listing files this may be your best bet.\n \n How often?? Well this depends on your BBS. A two line high-use BBS might\n need the file base to be purged daily.\n \n Purging the file base is easy, it is done every time the ''File Manager''\n is run. You can purge the file base anytime by selecting ''purge file base''\n from the DFBPrefs programme.\n@endnode\n\n@node "whatsnew" "What''s new for V1.2/1.3"\n \n Major new features for V1.11 & V1.2\n\n * DFB can now extract file comments from files when doing a local upload\n * DFB now has ''free file sections'' so you can make a file section \n   automatically contain free downloads. \n * The DFB archive now contains a utilities drawer which contains some of\n   the latest DFB @{"utilities" link "DFButes" 0}. \n * The DFB archive now contains the developer''s kit\n * New DFB utility - @{"DFBLogin" link "DFBlogin" 0} - gets file descriptions of files which were\n   uploaded but no description was left. \n * New DFB utility - DFBCheck - which keeps track of your BBS files. It is\n   a replacement for the MAX''s CheckFiles menu option.\n\n (IF you have just upgraded I suggest you go to @{"DFBLogin" link "DFBlogin" 0} now.)\n\n New features for V1.3\n \n * ReadDFB''s local file editor has been totally rewritten. It is now\n   in the new look WB2 style. Ive added a Save button, also a Needs Desc\n   checkbox. If this is clicked the user will be asked at login to\n   enter a file description for that file. This is useful if a user has\n   left a description you do not like and you wish him to enter another.\n   The string gadget next to the section number gadget is a section jump \n   string. Enter part of your section name and it will jump to it.\n * Assorted speed increases\n * Using MaxsPatch, MAX''s screens are now public, so the command:\n   amigaguide dfb:dfb.guide PUBSCREEN MAXS.1 \n   will pop up DFB''s doucmentation on your node 1 MAXS screen :-)\n   (there are also MAXS.2, MAXS.3 etc.. for further nodes)\n * Can now edit files from the DFBCheck programme\n * File lists can now be generated in Amigaguide and HTML format\n * Installer install script for updating/installing\n\n Not everything has been updated in this release, so some programmes\n may say V1.2!\n@endnode\n\n@node "Developers" "Developers"\n\n DFB is heavily dependent on its library, DFB.library, this library contains\n dozens of functions for accessing the file base and associated features.\n \n Programming and developing for DFB using this library makes life much much\n easier. \n \n A developer''s kit is included in this release in the developers directory.\n@endnode\n\n@node "DFBPrefs" "DFBPrefs"\n\n DFBPrefs is the main front-end to DFB, from here you can edit most of \n DFB''s features, DFBPrefs also enables you to jump to either the user\n editor, section editor or archivers'' editor.\n \n @{b}Gadgets@{ub}\n   \n File List Layout, opt layout 1,2 & 3:\n \n Here you can select which layout files you want to be assigned to the\n default layout and to the optional layouts 1,2 & 3. For an explanation\n of what the file layouts are see the section on @{"installing ReadDFB" link "ReadDFB_install" 0} \n\n There are several layout files included in this release (more will come):\n \n standard.lay          - Default layout, this is customized for use with\n                         file_id.dizs.\n longfileid.lay        - Same as the default layout but allows up to 20 line\n                         file_id.dizs (new for V1.1)\n longname.lay          - This is also customized for file_id.dizs but does\n                         not display number of downloads thus allowing a \n                         longer file name.\n standardshort.lay     - This layout can be used for either file_id.dizs or\n                         not. It is the same as longname.lay but only allows\n                         two description lines (of 44 across).\n shortnouploader.lay   - Same as the above one but never displays the\n                         uploader''s name/alias thus allowing file nodes to\n                         take up only 1 line if necessary (new for V1.11)\n longdesc.lay          - Same as shortnouploader.lay but does not display\n                         date, instead it uses the room for a longer file\n                         description (new for V1.11).\n nofileid_2lines.lay   - Customized for BBS''s not using file_id.dizs this\n                         one allows 2 description lines. \n nofileid_4lines.lay   - Same as the above but with 4 description lines.\n\n  If there is a specific one you require ask and I may be able to quickly\n make it for you but more than likely an editor will become available.\n\n Description Text Editor:\n \n When using the sysop file editor from ReadDFB you can select which text\n editor you wish to use to edit the file descriptions. You can select\n any text editor (or even a word processor if you really wanted to), I\n recommend diz-ed by nocturne design, this is especially made to edit\n file descriptions and as a plus can open up on MAX''S screen. \n\n WBToFront:\n \n Unfortunately when selecting a text editor to edit the file descriptions\n you may find that the one you wish to use refuses to open up on MAX''s\n screen.\n If this happens select this flag and DFB will automatically move to\n the Workbench screen - allowing you to edit your file description - and when\n you have finished it will automatically move back to MAX''s screen.\n\n NEW for V1.3: If you are running MaxsPatch, MAX''s screens are\n public, just set the public screen argument to MAXS.X where X is\n the node number, try:\n \n amigaguide dfb:dfb.guide PUBSCREEN MAXS.1 \n\n New Files Public:\n \n Same as MAX''s option, do you want all files uploaded to be automatically\n public? Any user with their access over the ''edit file'' access level will\n automatically have their files made public. See the @{"archiver''s editor" link "DFBsection" 0}\n for more information on user access levels.\n\n Delete on Purge:\n \n When you delete a file using DFB, e.g., move the cursor over the file and\n press the ''k'' key, the file does not have to be deleted then.\n \n You may find it useful to have files deleted when you ''purge'' the file base,\n (Purging the file base is basically optimization and removing of ''old'' data)\n rather than immediately. If you select this you will find that pressing the\n ''k'' key over files you have deleted they will come back! In other words\n this flag is useful for preventing accidents. \n\n Use headers:\n \n If this is selected ReadDFB will try and load the relevant header file to\n display. (V1.1)\n \n FM Frequency:\n \n See @{"the File Manager" link "DFBsection_manage" 0}\n\n Ratio Type:\n \n This can only be changed at installation time, DFB supports three different\n types of file ratios:\n \n File:       This is the same as MAX''s file ratio, uploads and downloads are\n             counted in number of files.\n \n Byte:       Instead of keeping track of how many files have been uploaded,\n             DFB counts uploads and downloads in bytes.\n \n Credit:     Is a subset of byte ratio, users only get file ''credits'' or\n             uploads as they are called when a user downloads a file they\n             uploaded. This is useful if you find users are uploading rubbish\n             to your system.\n             \n Use File_IDs:\n \n As it says.\n\n Ratios 1&2 Linked, Ratios 2&3 Linked, Ratios 1&3 Linked: @{"See file ratios" link "DFBsection_ratio" 0} \n Enhanced->Standard: @{"See user manager" link "DFBuser_manager" 0}\n\n The remainder of the gadgets are used for the user manager but will be\n explained here.\n \n The first column is for the ''guest'' user or when ''standard membership''\n expires.\n \n The second is for ''standard user'', i.e., what happens when you press\n ''standard member'' button in the @{"user editor" link "DFBuser" 0}\n\n The last is for ''enhanced user'', similar to the above. \n\n The first three rows are for the @{"file ratios" link "DFBsection_ratio" 0}\n\n The next is for the users'' access, then time limit and finally how long\n the account lasts for. Pretty basic stuff.  \n\n @{b}Menus@{ub}\n\n Only two of them need any explanation:\n \n Purge File Base:\n \n As discussed earlier in this section, this optimizes the file base and\n does some basic housekeeping stuff. This *doesn''t* perform any file\n managing, but it is run automatically when you do file manage.\n\n The file base can be purged by using the command line option: \n\n DFBPrefs purge\n\n\n Run File Manager:\n \n This runs the File Manager, now. You should have the @{"File Manager" link "DFBsection_manage" 0} run\n automatically.\n@endnode\n\n@node "DFBSection" "DFBSection"\n\n The section editor for DFB is extremely simple to use and most if not all\n of the gadgets are self-explanatory, an overview of the most interesting\n ones is given here.\n \n @{b}Gadgets@{ub}\n \n Section name and number are the same as MAX''s. Rules are no two sections\n can have the same number and try not to use section numbers above 65,000\n since they may be reserved in future versions. \n \n Upload path is very useful. MAX''s BBS does support multiple file paths but\n DFB goes one step further, it allows each section to have its own upload\n path. This is merely the default path, when checking for the file DFB will\n check all the other paths (DFB uses the same method of paths as MAX''S does -\n but a word of warning if you change the paths DFB will not recognize the\n change until reset. This is due to its library which loads up a copy of the\n paths when it''s needed and every DFB programme uses that one copy to save\n memory.)\n \n Also when the @{"File Manager" link "DFBsection_manage" 0} moves files to another section \n it will also  physically move the file to the new directory (if needed).\n But merely  moving the files to another section by yourself using a file \n editor will not physically move the file.\n \n User Access to:\n Access:         User must have this access to list files in this section.\n Download:       As it says.\n Upload:         '''' ''''  ''''\n View Hidden:    User must have this access to view new files (non public\n                 files), to view deleted views and also to view the uploader''s\n                 real name if the section is for instance alias only.\n\n Edit File:      As it says.\n View Text:      User must have this access to view files. \n\n Use Ratio:      @{"See ratios" link "DFBsection_ratio" 0}\n \n Flags:\n\n Section Off-line:       \n                 By clicking on this check box you can take the section off-line.\n                 The files will remain the same but users cannot access them.\n                 Clicking on the check box again will put the section back \n                 on-line. This is useful if say one of your HDs is being \n                 repaired and you still want users to know your board has the\n                 files.                 \n\n Section Free:   By clicking on this check box you make all files in that\n                 file section ''free downloads''. So any user can download\n                 them without affecting his/her credit ratio. Any file\n                 uploaded to that section will then become a ''free download''.\n                 By clicking again on this check box files go back to their \n                 previous state (whether they were free or not). (V1.2)\n\n Uploader Signatures:\n                 Set if you will allow upload signatures to be used.\n                 \n Cycle gadget, Uploader:\n                 What to print when DFB prints the uploader.\n\n                 This allows you to use the same layout for different \n                 sections and yet customize it down further. MAX''S has\n                 support for several:\n                      Alias sections\n                      Sections with only the users real name\n                      Section with no name or alias.\n                 DFB allows tons of combinations. Just try them :-)\n\n                 This is not connected to upload signatures in any way so\n                 you could have both or neither of them running.\n\n Max Size/File Life/Then Move to Section:\n                 @{"See File Manager" link "DFBsection_manage" 0}\n\n @{b}Menus@{ub}\n \n Clone Section:  This is used to add sections, to add a section first go\n                 to a section with similar attributes (e.g.: access levels\n                 etc.) then select clone section from the menu - a new \n                 section with the same attributes as the section you were\n                 last on, will be created. The only differences being the\n                 section name and number.\n\n The remainder are self-explanatory.\n@endnode\n\n@node "DFBSection_manage" "DFBSection - File Manager"\n\n In MAX''s BBS, when a file is uploaded to a file section and the maximum\n number of files in that section has already been reached MAX''s will delete\n the oldest (non-locked) file.\n \n This is MAX''s File Manager. DFB goes several steps further.\n \n You cannot set the maximum number of files in a file section, I fail to\n see the point of this option. @{i}Instead@{ui} you can set the maximum\n size of the file section in megabytes. Also another difference is \n DFB does all its file managing at the end of the day - so if a user uploads\n a 2.3 meg file to a file section and that section is now over its megabyte\n limit the oldest files will not be deleted until the File Manager is run.\n \n There are 3 main gadgets which control the File Manager and how it\n operates, they are found in each file section in the section editor.\n \n The first is Max Size, this controls the size in megabytes of the file\n section in question. If Max Size is set to zero DFB considers the file\n section to be infinite in size.\n\n File Life, if you want files to remain in a certain section for a limited\n period of time set the number of days here (+1). If you set this to 0,\n the File Manager will only move/delete files if the maximum size limit\n is reached.\n \n The Move to section, if the maximum size of the file area in megabytes\n is exceeded or the life of a file is exceeded (that is if you are using\n the file life gadget) then this gadget controls where the files go to.\n If it is set to 0 the files are deleted otherwise the files are moved to\n that section.\n \n Note: You cannot move a file to section 0 with the File Manager. If this is\n a problem don''t use section 0, there are, plenty of others to choose from :-)\n \n @{b}Running the File Manager@{ub}\n\n *Before you run the File Manager make SURE every section is set up\n  correctly. The File Manager is powerful and does delete files, as you\n  can imagine misuse could have disastrous consequences*\n \n Running the File Manager is similar to the @{"user manager " link "DFBUser_manager" 0}\n  \n The File Manager has to be run to keep order and perform automatic\n housekeeping tasks. It can be run once per day or once per week depending\n on the amount of traffic your BBS has.\n \n To run it, either select the option ''Run File Manager'' from the @{"DFBPrefs" link "DFBPrefs" 0}\n menu or type from CLI:\n \n DFBPrefs filemanage\n \n Suggested ways of running it:\n \n 1) Put the above line in your startup-sequence, DFBPrefs will detect if it\n    needs to be run so frequent computer resets won''t cause it a problem.\n    \n    If you choose this there is a gadget in DFBPrefs called FM Frequency\n    which dictates how many days apart the File Manager should be run.\n    This way you can have DFBPrefs running the File Manager in your\n    startup-sequence and it can still run every x days. An FM Frequency\n    of 0 means the File Manager is run everyday. FM Freq of 1, the file\n    manager is run every other day etc.\n    \n 2) Select the menu option ''Run File Manager'' in DFBPrefs every now and\n    again :-)\n    \n 3) Use MAXsBBS AutoExecute command.\n\n@endnode\n\n@node "DFBSection_ratio" "DFBSection - File Ratios"\n\n It would be ridiculous to release a file base system with no file ratios\n because every sysop expects it, DFB goes one step further, for every\n user there isn''t just one file ratio there are three.\n\n @{b}Why three ratios?@{ub}\n \n I admit, most users will probably only require one file ratio. Having\n multiple file ratios gets a bit complicated, especially for the users.\n \n When you install you''ll see that only the first ratio box is used. Using\n more than one file ratio is optional.\n \n The reason being is that you might have files on your HD which are say\n newer than others and you find it unfair that users can say upload some\n old programmes and then go and download heaps of the newer programmes.\n \n This way you can have one ratio for all your old programmes, and if a \n user wants some newer ones he has to upload to the new section. In this\n example you could also use the File Manager to automatically move the\n files after say 30 days when the files are no longer new.  \n   \n Originally the ratios were going to be linked, so even if the user didn''t\n upload the ''new'' files he could still download them - it just meant some\n file sections required more file credits than others. This ''linking'' uses\n the three disabled check boxes in the DFBPrefs programme and will\n probably not be done. If you require this feature mail me!\n@endnode\n\n@node "ReadDFB" "ReadDFB"\n\n ReadDFB is the only programme which is run from MAX''s BBS. This programme\n can emulate the MAX''s functions: upload, download, list files, list new\n files etc. \n \n Firstly ReadDFB must be installed into MAX''S BBS, this process is not\n automatic because I thought people wouldn''t appreciate me just changing\n their whole board over to my file base without them knowing :-)\n \n Select what you wish to know about ReadDFB:\n\n @{" Installation    " link "ReadDFB_install" 0}\n @{" User functions  " link "ReadDFB_user" 0}\n @{" Sysop functions " link "ReadDFB_sysop" 0}\n @{" Customization   " link "ReadDFB_custom" 0}\n\n@endnode\n\n@node "ReadDFB_install" "ReadDFB - How to install"\n\n @{b}How to install@{ub}\n \n Enter MAX''s menu editor and change each line which accessed MAX''s file\n base to equal:\n \n Key:  Function:   Extra:    Lo acc:     Hi acc:    Filename/Name/Dest/Path:\n \n  ?       34         0          ?           ?       DFB:ReadDFB <options> \n\n Where the question marks remain what they were originally.\n \n Now there are several options which ReadDFB can use, the options are\n split down into several groups which have to be in this order:\n\n (If no options are given ReadDFB will list every single file using default\n  options)\n  \n *All the important options are marked with a star.*\n \n ReadDFB [<layout>] [<type>] [<command>] [R] [<section lists>] \n         [<(upload section)>][<"headername">]\n \n <layout>:  DFB can display the files in a variety of ways. e.g.: Should\n            DFB display how many times a file has been downloaded? How\n            many lines should be given for the description? You can specify\n            which layout you want to use, either 1,2 or 3. This number\n            matches the layout selected in DFBPrefs.\n            \n            e.g.:\n            \n            ReadDFB L1 \n            \n            Will select the first optional layout.\n                       \n   <type>:  You can list files using certain criteria such as list new files,\n            list off-line files, list new files etc.:\n          \n            D    List deleted files\n            L    List locked files\n            N    List new files\n            O    List off-line files\n            +    List free downloads\n          \n            Put a ''|'' in-between them, e.g.:\n          \n            ReadDFB D|L|+\n          \n            will list files which have either been deleted, locked or are\n            free downloads.\n           *<command>: THE most important option, this selects what you want\nReadDFB\n            to do. If you do not select a command ReadDFB just lists the\n            files.\n            \n            The commands are:\n            \n            down       (Just download files, don''t list them)\n            up         (Just upload files,    ''''    ''''  '''')\n            last       (List new files since last on (like MAX''S))\n            tag        (Only list tagged files)\n            find       (Find a file by text search of both name & description)\n            qfind      (Find a file by text search of just the name)\n            date       (List files after a date (or before if you have\n                        selected to list files in reverse order, see later))\n\n \n       [R]: Direction, if you put in an ''R'' DFB will list the files from \n            newest->oldest.   \n\n*<section lists>:\n            When you are listing files it''s essential to choose which \n            sections you want listed at a time.\n            \n            Best way to explain is to give some examples:\n            \n            ReadDFB                   List all files\n            ReadDFB 1                 List only the files in section 1\n            ReadDFB 1-100             List only the  files in sections 1 to 100\n                                      (inclusive)\n            ReadDFB 1,3               List files in section 1 and files in\n                                      section 3\n                                      \n            ReadDFB 1,1-20,1000-1012  Guess :-)\n\n            Note: Don''t get too carried away...\n\n            \n            Some points: The sections need not exist, e.g. telling ReadDFB\n            to list all files in sections 1 to 100 and not having any\n            sections between 20 and 30 will not cause a problem.\n\n            The user will only see the files in the sections he has \n            access to. So feel safe to group sysop files with ordinary files,\n            only the right guys will see them or be able to access them :-) \n            \n <upload section>:\n            If only one file section is given DFB will naturally assume\n            that uploads go there but it can get a bit confusing if you\n            have a general file list.\n            \n            So if you are listing files from multiple sections and you\n            want the user to be able to upload just put the section you\n            want the uploads to go to in brackets.\n            \n            e.g.:\n            \n            ReadDFB 1-1000 (20)\n            \n            List files in first thousand sections, uploads go to section 20.\n\n            Or, if you have only listed one section but you want the users''\n            uploads to say go to a different section (perhaps a new files\n            section) then:\n            \n            ReadDFB 3 (4)\n            \n            Will list files in section 3 but all files uploaded will go to\n            section 4.\n\n "<headername>":\n            One of version 1.1''s new features. Header files. \n            See @{"Headers" link "headers" 0} for more information.               \n\n            Forces ReadDFB to load a specific header file.\n\n            e.g.:  ReadDFB 3 (12) "DFB:headers/privateheader"\n            \n            (You must include the quote marks).\n            \n Feel free to combine all of the above but don''t get too carried away.\n \n Here is a couple of examples:\n \n ReadDFB Last 1-100 (20)       List new files since I was last on in first\n                               one hundred sections. Uploads go to 20.\n\n ReadDFB N R                   Sysop one, list non-public files (e.g.: new\n                               uploads) starting from the latest one.\n\n\n One more thing, DFB has on-line help by pressing the ''H'' key. ReadDFB then\n displays the text file: DFB:DFBhelp.txt which can easily be edited.\n@endnode\n\n@node "ReadDFB_user" "ReadDFB - User functions"\n\n DFB is simplicity itself to use so I''ll only briefly cover the options:\n\n The bottom line gives most of the user commands:\n \n -> Arrows to select, U)p D)own R)everse H)elp S)top <RETURN> -->\n ^\n |- Direction of file list, towards the right is from oldest files to newest.\n   \n Up and down arrows to select files, <RETURN> from the bottom line will\n continue the file list.\n\n U) Upload files\n D) Download tagged files and/or other files which user can enter in.\n R) Reverse the direction of file listing starting from files which aren''t\n    visible.\n H) Help, views text file DFB:DFBhelp.txt\n    (Thanks go to Bonza for writing the included one)\n\n S) Stop listing\n \n Not shown:\n \n E) Edit upload signature, if upload signatures are used the user can\n    edit his/hers. The user has a choice of auto-centreing it to make life\n    easier.\n\n I) Gives the user information on how many files uploaded/downloaded, how\n    many to go and ratio. (For byte or credit shows the number of bytes)\n\n If the user moves the cursor up:\n \n <RETURN> to tag/untag,  D)own V)iew R)everse S)top\n\n <RETURN> tags/untags files 8-)\n \n D,R and S work as above.   \n \n V) View files, see @{"Customization" link "ReadDFB_custom" 0}\n\n Ctrl-L will redraw the file list. \n \n At the end of every file list the user will see:\n \n Files listed/total: [xxxx/yyyy]\n\n I think this is self-explanatory. \n\n@endnode\n\n@node "ReadDFB_sysop" "ReadDFB - Sysop functions"\n\n The access needed for a user to have sysop functions is given in the\n section editor. Each section can have a different level for sysop functions,\n so a user might be sysop for one file section but not another.\n\n These sysop functions can still be performed on an account which only\n has standard user level ONLY if the key press came locally. I.e\n if you are sitting down at your computer and you notice that\n a file listing looks weird when one of your users lists it, you can edit \n the file using that person''s ReadDFB, even if that user doesn''t have high \n enough access.\n \n ReadDFB will note that the key press came locally and will let you\n edit the file.\n\n @{b}Editing files@{ub} \n\n Move the cursor over the file as though you were about to tag it.\n The following keys will toggle the files attributes:\n \n K      Delete file, if there is a ''D'' against the file it has been deleted,\n        The ''K'' key will delete a file and can bring the file back _only_\n        if you have selected ''Delete on Purge'' check in @{"DFBPrefs" link "DFBPrefs" 0}\n  \n N      New file, if there is an ''N'' against the file it is not a public file.\n        The N key toggles this. Only sysops can see files which are not\n        public (unlike MAX''S).\n\n L      Locked file, the same as MAX''S BBS. The L key toggles this.\n\n O      Off-line file, in DFB you can include files which are not on your\n        HD. With off-line files users can see which files you have but not\n        be able to view/download them. Also if you are temporarily unsure \n        about a files contents you can put it off-line, users can still see \n        you have it while only sysops can view/download it.\n        \n +      Free downloads, if a file is tagged with this symbol users can\n        download it even if they have a lousy file ratio. They will not be\n        charged :)\n\n E      If this letter appears next to the file name it means the file\n        is waiting for the uploader to type/retype in a file description.\n        To toggle this flag, press ''e'' to enter the file editor and then\n        toggle the ''NeedsDesc'' flag.\n                         \n If you want to edit something else, say the name or description of a file\n press ''e'' over the file.\n \n A window will come up with all the file''s attributes. Most of the\n gadgets are self-explanatory so I''ll only describe the interesting ones.\n\n The string gadget next to the section number contains the name of\n the section the file is in. If you want to move the file to a certain\n section, type in the section name or a part of the section name and\n the window will jump to the correct section.\n \n For example, if you want to move to a section named ''Comm & Terminal Progs'',\n you could enter in the section text gadget ''term'' and it would\n move the file to the right section. \n\n There is an additional checkbox available in the local file editor window,\n it is labelled NeedsDesc. If this checkbox is checked the user who\n uploaded the file, will be asked when they log in to leave a file\n description. Or DFB will search for the file''s file_id.diz if enabled\n upon user login.\n\n There are four buttons down at the buttom of the window:\n \n Description       -  DFB will load your own custom text editor to edit the\n                      file''s description. You can choose your text editor\n                      with DFBPrefs. I *totally* recommend Nocturne\n                      Designs''s diz-ed. This is absolutely brilliant and\n                      it can open up on MAX''s window. BTW just so DFB can\n                      use the above editor you may see:\n                      @BEGIN_FILE_ID.DIZ & @END_FILE_ID.DIZ, make sure the\n                      description is in-between these.\n                      \n Nuke Credits       - Don''t like the file that you''re editing? This button\n                      removes the uploader credits he would have gained from\n                      this file. Multiple clicks will severely annoy the\n                      uploader :-) If the screen flashes it is either due\n                      to: 1) Can''t find uploader\n                      or  2) User has no more credits left.\n                      \n Zot File           - If you really want this file gone, Zot it! This will\n                      immediately delete the file and will remove all \n                      mention of the file in any ReadDFB list.\n\n Save               - This will save any changes you have made to the file. \n\n A remote sysop can also edit files, the procedure is the same. Move the\n cursor over the filename and press ''e''. A new screen will come up with\n all the options. Currently file descriptions cannot be edited from remote.\n\n@endnode\n\n@node "ReadDFB_custom" "ReadDFB - Customization"\n\n Most of ReadDFB''s customization is covered in the @{"Installation" link "ReadDFB_install" 0} bit\n of this document although a major part is what happens when a user tries\n to view a file.\n \n This is fully configurable by you, @{"DFBArchivers" link "DFBArchivers" 0} contains the relevant \n information on how to set it up. See @{"DFBArchivers - viewing files" link "DFBArchivers_list" 0}\n  \n Another customization feature which is new for version 1.1 is @{"Headers" link "headers" 0},\n this is fully explained in its own section.\n\n@endnode\n\n@node "Headers" "ReadDFB - Headers"\n\n @{b}What are headers?@{ub}\n\n Headers are small text files which tell ReadDFB how to display its\n information. Currently when listing files you can change the colours\n of: filename, date, times uploaded, description, uploader, alias, size\n and filename when highlighted. You can also make ReadDFB display ansi\n texts at the start of file lists.\n \n @{b}How do I use them?@{ub}\n \n First of all you must enable them, go to@{"DFBPrefs" link "DFBPrefs" 0} and make sure that\n the headers check box is selected. \n \n Now ReadDFB is ready to use headers! First of all ReadDFB has its own\n system for working out which header to use. Each ReadDFB command can\n load a different header so every section may have a different header and\n combined file sections.\n \n ReadDFB will now choose a default header to load. It''s a pretty simple\n system, if you are listing only the files in section 1 it will\n load the header file: DFB:headers/header.1 If you are listing files only\n in section 3 it will load the header file: DFB:headers/header.3\n \n If you are listing combined sections it will default to the file:\n "DFB:headers/header." (with the period mark)\n \n Now this is a bit limiting, since you may wish to put your header files\n in RAM: to speed things up or you may wish to have several different\n headers for all your combined file lists.\n \n You can force ReadDFB to load a specific header file by placing the\n header file name in quote marks as the last command line argument,\n e.g.:\n \n ReadDFB 100 (12) "ram:myheader"\n \n @{b}How do I modify them?@{ub}  \n\n This is the tricky part, DFB''s philosophy has been to keep it simple,\n easy to use and as powerful as this will allow. Unfortunately I couldn''t\n think of an easy way to use the power of headers and have a nice GUI\n for editing them. (It would be too large!). There is a demo header file\n included in this archive (DFB:headers/header) and by following that\n it''s very simple to edit to the configuration you want.\n \n I will go over the rules briefly here but don''t worry! There is no\n reason why you can''t just modify the included one.  \n\n Here''s the rules in case you need them:\n\n 1) If you want a comment in the header file put a ''#'' as the first \n    character.\n 2) If you wish to use one of the commands (they are used to change \n    colours, put a ''$'' in front of it)\n 3) Don''t use blank lines except in the text bit to display\n 4) If you want to use the ''$'' or ''#'' symbol as the first character in\n    your ansi text to display write two of them in the text file. ReadDFB\n    will know what to do.\n 5) All commands should be in lower case.\n \n OK now feel free to forget them! Just go and edit the included one!\n All you need to know is comments and commands go at the top, the ansi\n text to display goes down the bottom and doesn''t have blank lines in-between\n comments and commands.\n \n One more thing, you can only choose the colours: white, yellow, green,\n red, cyan, purple and blue. Notice no black!\n  \n Have fun! \n\n@endnode\n\n@node "DFBArchivers" "DFBArchivers"\n\n The programme DFBArchivers controls several settings of DFB. \n \n Archivers, there are 4 columns in the archivers'' editor, the first is the\n extension. This covers the extensions which files can have, e.g.:\n .txt, .lha, .g etc.\n\n You can have up to 11 characters in here, so if the same commands should\n be executed for say .lzh files and .lha files you can put multiple\n extensions in separated by a comma:\n \n lha,lzh\n\n The other three columns control what happens when DFB encounters these\n files at certain points:\n \n @{"Extractor for file_id     " link "DFBArchivers_extractor" 0}        - What command DFB runs to extract the\n                                      file_id.diz (to the current directory)\n @{"Command On Upload         " link "DFBArchivers_upload" 0}        - What command DFB runs when a file\n                                      is uploaded. \n @{"File List                 " link "DFBArchivers_list" 0}        - What command DFB uses to make some\n                                      text to put on screen when a user tries\n\n                                      to view a file on-line via ReadDFB \n\n The archivers'' dir gadget is where DFB will look for your archiving \n programmes.\n \n You may think this is fine for programmes which end in extensions, but some\n files (mainly text ones) have no extension or what if DFB encounters a\n file with an unusual extension? (such as .bmap)\n \n For this I have added the ''default gadget'', you may notice that along side\n each row in DFBarchivers is a number. By placing this number in the default\n gadget it tells DFB which row to use if it encounters a file with either\n no extension or an unrecognized one.\n \n The default number is 0 - which means don''t do anything.\n \n Also DFBArchivers controls @{"File backups" link "DFBArchivers_backups" 0}\n@endnode\n\n@node "DFBArchivers_backups" "DFBArchivers - File backups"\n\n When the File Manager is run, DFBArchivers, as a safety precaution backs\n up the following files: DFB.prefs, DFB.users & DFB.data.\n\n You can backup/restore those files any time by using the menu options in\n DFBArchivers.\n \n The file to which these are backed up is given in the gadget in DFBArchivers,\n if this string gadget is empty DFB will not back up the files.\n \n The following command is always used to back up files:\n \n lha >NIL: u DFBdata:DFB.data DFBPrefs:DFB.prefs DFBusers:DFB.users\n \n to restore them:\n \n lha >NIL: e DFBdata:DFB.data DFBPrefs:DFB.prefs DFBusers:DFB.users\n\n Also make sure you have specified the directory your archivers are in!\n \n Note: DFB handles file paths like MAX''S BBS, for simplicity, so\n \n hd0:a/     is acceptable whilst:\n hd0:a      is not.\n@endnode\n\n@node "DFBLogin" "DFBLogin"\n\n @{b}Installation@{ub}\n \n To install DFBLogin is easy, just copy the file DFBLogin to:\n BBS:Doors/DFBLogin\n Then add the line:\n \n DFBLogin\n \n to the file BBS:Doors/IntroDoor.text\n\n @{b}What it does@{ub} \n\n DFBLogin checks the user''s status to see whether the user uploaded\n file(s) without leaving file descriptions. If the user did it will\n then ask the user to enter the file descriptions. It will then\n update the files in the file base.  \n\n It also turns the user''s pause flag on. This is necessary since due\n to a MAX''s problem, if a user loses carrier in DFB their pause flag\n will be turned off.\n\n @{b}What if I want DFBLogin to run AFTER mail?@{ub} \n\n If for some reason you would prefer DFBLogin to be run AFTER mail then\n put the line:\n \n DFBLogin\n \n in the file BBS:doors/MainDoor.text\n AND move both DFBLogin and pauseflagon to BBS:Doors/\n\n and put the line\n \n setpauseflagon\n \n in the file BBS:doors/LoginDoor.text\n\n This is necessary so that the user''s pause flag is on BEFORE mail is run.\n@endnode\n\n@node "DFBArchivers_extractor" "DFBArchivers - File_Id extractors"\n\n If you have the File_id.diz flag off in DFBPrefs this column will be\n ignored.\n\n DFB contains no code of its own to extract file_id.diz''s, instead it\n relies on external files. \n\n The format is relatively simple, just write in the command that you\n would use to extract the file_id.diz. Where the file name would normally\n be kept replace it with a ''<>'' which DFB replaces with the file name later.\n \n e.g.:\n \n lha >NIL: x <> file_id.diz  \n unzip >NIL: -e -o <> file_id.diz           \n\n Will extract file_id.diz''s from the files with the extensions which would\n be specified in the extension box.\n@endnode\n\n@node "DFBArchivers_list" "DFBArchivers - Viewing files"\n\n Viewing text files is handled slightly different from the \n @{"file_id.diz extractors" link "DFBArchivers_extractor" 0} & @{"command on uploads" link "DFBArchivers_upload" 0}\n \n @{b}How it works@{ub}\n  \n When a user selects ''view file'' DFB will immediately check the file''s\n extension. (e.g. .txt etc.). If one is not found DFB will say it can''t view\n the file, if it does find an extension it will go to the appropriate\n ''File List'' box.\n \n It will then replace the ''<>'' in the command with the full path and name\n of the file DFB wants to view. It will then execute what is in the box.\n \n After that DFB will check the current directory for a file called ListX,\n if this file is found DFB will print it out on MAX''S BBS''s screen.\n \n @{b}Example@{ub}\n \n Say when a user tries to view an ''lha'' file, I wanted DFB to print out the\n files in the archive, this is the command I would enter into the box:\n\n lha >ListX l <>\n \n Now, the first > symbol will redirect lha''s output to the file ListX in the\n current directory which DFB will then read.\n \n What if it was a plain .txt file?\n \n Well there are two ways of doing it, a:\n \n copy <> ListX\n \n Would copy the file to ListX and DFB would then read it but since text\n files are so common I included the operative: ! which is used to display\n a text file, so the above command can be written:\n \n !\n \n The ! operative is handled internally and is better than the copy command\n because it tells DFB just to read the file straight from disk.\n@endnode\n\n@node "DFBArchivers_upload" "DFBArchivers - What to do when a file is uploaded"\n\n If you want DFB to say add in a BBS ad or to remove someone else''s <grin>\n this is where you put the command, e.g.: if you wanted to put a file\n called ''mybbs'' which is kept in ram: to every .lha file uploaded you''d\n put in the ''Command on upload'' box the following command:\n  \n lha >NIL: a <> ram:mybbs\n \n Like the @{"file_id.diz box" link "DFBArchivers_extractor" 0} the <> sign indicates where DFB should put in the\n file name.\n\n Note: If you want more than one command to be executed you must create a\n dos script file. Remember that any command put in the box will be prefixed\n with the archiver''s directory. \n \n Hint: When using dos scripts try this: Put the dos script into your\n archivers directory then type from CLI:\n \n protect dosscript +s\n \n Then all you have to put in the ''command on upload'' box is:\n \n dosscript <>\n \n The ''<>'' sign passes on the file name being processed to the dos script,\n you must do this, see any dos manual for how to pass variables to a script.\n@endnode\n\n@node "DFBUser" "DFBUser"\n\n Due to some new features of DFB the standard MAX''s user.data file had to\n be expanded, all the new information just wouldn''t fit into it, and even\n if it did, MAX''S does not have the features to edit it anyway so it was\n necessary to build another user editor. \n \n So at the moment you have two different user editors! The MAX''s one and\n DFB''s. At the moment DFB''s user editor only contains relevant information\n which DFB needs (hopefully in a future release it will be a full editor).\n\n Here are the relevant sub-topics:\n\n @{"When to use DFB''s editor, when to use MAX''s" link "DFBUser_when" 0}     *important*\n @{"What everything does                       " link "DFBUser_what" 0} \n @{"The User Manager                           " link "DFBUser_manager" 0}\n@endnode\n\n@node "DFBUser_when" "DFBUser - When to user DFB''s editor, when to user MAX''s"\n\n If you are editing a user''s access or his time limit then either editor will\n do. If you use MAX''s the change may not be immediately visible in the\n DFB user editor, however the next time the user logs on DFB will act on the\n new access level (or time limit).\n \n If you are editing the user''s ratio, number of files (or bytes) uploaded \n (or downloaded) then you must use DFB''s user editor. After installation\n DFB ignores the MAX''s values for various reasons.\n \n If you are changing a user''s name for some reason change it using the\n MAX''S''s user editor then go to DFB''s editor and change the name there too.\n\n If your user.data file changes for some reason, e.g. a new user logs in\n or you delete a user or whatever DFB will gradually change its user file\n when it needs to, if however you want to view the changes immediately \n select the ''Update Users'' from the menu.\n@endnode\n\n@node "DFBUser_what" "DFBUser - What everything does"\n\n @{b}Gadgets@{ub}\n\n Most of the gadgets, if not all, in the user editor are pretty easy to\n guess. Here is just a brief mention of some of them:\n \n    User Name: If you have to edit the name make sure you edit it in both\n               MAX''S''s and DFB''s user editors to prevent confusion.\n             \n Upload Signature:\n               New feature for DFB. An alternative system for uploader''s\n               tagging their uploads. At install time each section has\n               upload signatures disabled. \n     Days Left:\n               New for MAX''s - DFB has an built-in membership door and this\n               is the main part of it. Each user can have an account with a\n               set number of days before it expires. The number of days can\n               be set with the standard/enhanced membership buttons.\n                 \n Standard Member/Enhanced Member:\n               Similar to MAX''S membership buttons. The options for what\n               happens when you select these buttons are given in \n               DFBPrefs.\n\n          Save: \n               Saves changes to user.\n          Next:\n               Go to next user.\n\n As you may note there are three boxes for uploads, downloads and ratios.\n There is an explanation for this in the section on @{"file ratios" link "DFBSection_ratio" 0}\n\n @{b}Menu Items@{ub}\n \n Update Users: This performs some basic housekeeping functions, this is\n               automatically run when you use the user manager. \n               \n Run User Manager:\n               This runs the @{"user manager" link "DFBUser_manager" 0}\n@endnode\n\n@node "DFBUser_manager" "DFBUser - User Manager"\n\n Firstly...\n\n DFB has a built in membership door, at the moment it is very simple and\n only supports the following:\n \n Quick update buttons for 2 different access levels (Standard & Enhanced)\n Which updates:\n  * Time limit\n  * Days of account\n  * Ratios\n     \n These are set in the DFBPrefs programme.\n\n @{b}The User Manager@{ub}\n \n The User Manager is used so DFB can keep track of how many days are\n remaining in everybody''s account - if you do not have any accounts which\n expire or change after a certain amount of days you do not need to run\n this!\n \n The User Manager should be run once and only once per day, every time it\n is run it first checks whether the users need updating, then it subtracts\n x number of days from everybody''s account (accounts with 0 days left are\n considered to be everlasting) if an account reaches 0 it is then reduced.\n \n A standard membership account will expire to a guest account (i.e., the\n first column in the DFBPrefs account gadgets)\n \n An enhanced membership account will either expire to a standard one or a\n guest account depending on whether the tick is set in DFBPrefs.\n (The Enhanced->Standard check box)\n \n When I say x number of days this means if the user manager detects it hasn''t\n been run in say 3 days it will subtract 3 days from everybody''s accounts. \n \n Recommended ways of running the user manager:\n \n 1) Put the following line in your startup-sequence:\n    \n    DFB:DFBuser usermanage\n    \n    DFBUser detects if it has already been run on any given day so if you\n    reset your machine several times it will not keep on subtracting 1 from\n    the days left in everybody''s accounts :)\n\n 2) Use MAX''S BBS''s AutoExecute command.\n    \n Running the menu option is not recommended since it _always_ subtracts\n at least one from the number of days in everybody''s account. So use it \n wisely.\n@endnode\n\n@node "features" "Feature List"\n\n These features are optional so if you don''t want them don''t worry!\n\n * 100% Assembly coded for minimum size, maximum speed and power!\n * Programme automagically converts from MAXS -> DFB. No messing around with\n   text files to get this programme working\n * GUI for preferences selection\n * Built in remote file editor\n * Full file_id.diz support (for anything, e.g.: .lha, .zip etc.)\n * Filenote support \n * Automatic ''file ad'' addition (execute any command on upload)\n * Can view almost any type of file on-line: (e.g. .pp, .guide are no prob)\n * Conference ratio support\n * Support for the following ratio systems: file, byte or credit.\n * Log off after downloads\n * Up to 65,000+ file sections possible leaving all 100 MAX''S sections free\n   for mail\n * Uploader signatures and uploader aliases\n * Local uploader uses an asl requester with multiple file selection\n * File & Sections can be taken off-line with a click of a button\n   (Full offline file & section support)\n * File & Sections can become free downloads with a click of a button\n * MAX''s style file tagging (even when using file_id.dizs!)\n * Make files public, lock files, make files free dls, move files off-line,\n   delete files by just moving the cursor over the name and pressing a key!\n * Each section has its own access levels for: downloading, uploading, \n   viewing, sysop functions etc.\n * Each user has his/er own tagged file list, doesn''t ''disappear'' if they\n   lose carrier (tagged file lists can be kept anywhere and sysop can \n   edit it with any text editor)\n * List *any* combination of file sections at a time: e.g. list sections 1,2,3,\n   23 and 300 to a thousand (inclusive). If a user doesn''t have access to one\n   of those sections he won''t see the files in that section.\n * List files using almost any possible criteria: By date, by name\n   by name and description, tagged files, list only off-line files, list\n   off-line files or new files etc. etc... combine this with the listing of\n   any combination of sections.. !\n * Possible to change the way DFB displays files. Don''t want it to display\n   number of downloads? No prob. Rather use only 3 description lines?\n   Just use a different layout!\n * File headers, which allow text to be displayed at the top of every\n   file list and also allows you to change the colours of the file list\n * User can change the direction of the file listing at any time\n   (THIS FEATURE IS UNIQUE TO DFB!)\n * File Manager: Automagically move/delete files after x days or move/delete\n   files if section is full\n * Automatic back-up of file base etc.\n * Each section has its own default upload directory\n * Set each section size in megabytes\n * User manager and membership door: Give users access at the touch of a\n   button, define the time limit, membership duration, ratios etc...\n@endnode\n\n@node "credits" "Credits & Greetings"\n\n               Main coding/design by:      Andrew Leppard\n               \n\n Initial idea, concept and beta testing by: Bonza\n               additional code donated by: Randy Quick\n               additional  coding help by: Michael Zucchi \n                \n Thanks go to: Randy Quick & Ari Tsironis for information concerning\n               MAX''S BBS door programming.\n               Bonza for not giving up at the sight of those _rare_ bugs :)\n               Jan van der Baard and everyone at Jaba Development for \n               GadToolsBox which was used to make all of the GUIs.\n               It''s a brilliant programme!\n\n               Micke Lehner, Shaun Payne, Randy Quick & Egress-1 for allowing\n               their boards to be used as distribution sites.\n                              \n               Thanks to my new distributors: Ray De Brabander & Paul\n               Bradley.\n               \n               Greg Fitch for alerting me promptly about bugs!\n               \n               Thanks to The BenchMaster for ideas and spell checking the \n               manual.\n                              \n               Thanks to the following people for beta testing V1.2:\n               \n               Bonza, The BenchMaster, George Kalaitzis, Tommy Samuelsson.\n                                                                            \n               Thanks to Heddley author Edd Dumbill for his excellent\n               program and to FixHeddley author David Zvekic.\n\n               All those that have stuck with MAX''S BBS this far!\n\n Greetings to: Mav (why didn''t you do the GUI for me?!@!@!), Zed and everyone\n               else at Frontier (OK, OK so I should have done some code for\n               you?), Randy Quick (when''s the 5th line coming? :), Cydonia,\n               Pearl and Digital Access, Angela Borchard, Spoonman, Bonza \n               (what do you mean uploads don''t work?), The Sorcerer, Wyrehead\n               (you could have told me about that Amiga IRC session you were \n               on!), The Haggis, Dizzy, Ari Tsironis (Pity about MAXSBBSTNG -\n               there _was_ a big market for it), a1, Azat, Cro, Prowler, Sal,\n               Jody Christine & Samantha Murphy, Benchie, Melissa Page.\n                              \n               The Jaker, Blackout, AITEC and anyone else whom I may have \n               forgotten. Big wave to Chastity from Chastity Records.\n\n Appreciation to/of:         \n               Bomb the Bass, The Prodigy, Culture Beat, Urban Cookie \n               Collective, Jolt Cola, Heaven the club, MAX''S BBS, Apotheosis \n               (for Obumbrata), JX for ''Son of a Gun'' and ''You belong to me'',\n               Amiga and all that have worked on it, Suns and the Internet,\n               -- S-Express --, Itchy & Scratchy!\n \n No-Thanks go to: \n               ACE-TV, S.A Police force (for being there), IBM (R&D exempted),\n               Microsoft (NO EXEMPTION), Reggae, Anthony Barret (for not \n               helping MAX''S BBS programmers now), Country & Western and some\n               guy called Bill and another called Drew. Stay out of the\n               park Bill.\n                                           \n And finally this programme is dedicated to Jody Murphy, because if you can''t\n dedicate a programme to someone, what can you do?\n@endnode\n\n@node "Future" "Future of DFB"\n\n Firstly, DFB is not perfect. As far as BBS file bases go, it is getting\n there though! So what do I plan to do to DFB in the future?\n \n * Utilities, doors e.g.: Top Up/Downloaders.\n   (Someone started programming this!)\n * XPR transfer protocol libraries. This way DFB will support more protocols\n   such as Super Zmodem, Bimodem etc... (already done most of the work)\n * Daily download limits\n * CDROM/DAT section support (including multiple DFB.data file support)\n * A local file editor launched from DFBPrefs with some serious searching\n   options. The DFBCheck one only works on files with problems!\n * Lots of minor enhancements \n * Can''t think of anything else. All of the features I could think of are\n   already in it!\n@endnode\n\n@node "Registration" "How to Register"\n\n @{b}Why register?@{ub}\n\n Well, quite simply, the demo (unregistered) version of DFB is next to \n useless, downloads have been disabled to encourage you to register.\n Also the saving of tagged files to disk has been disabled.\n\n @{b}How to register@{ub}\n \n First of all, fill out the @{"Registration Form" link "RegistrationForm" 0}, this contains important\n questions so come update time I know what needs to be done, because at this\n time I am not a sysop and don''t know exactly what you need!\n   \n Either...\n\n Post it to my internet account:\n\n E-mail: [email removed] \n If that one *DOESNT* work then try: [email removed]\n \n Or post it to me in a message on Fred''s BBS:\n Line 1: +618 341-5944 (2400 baud)\n Line 2: +618 341-5137 (14.4k baud)\n \n Or leave the registration form on one of DFB''s distribution sites mailed\n to the sysop. (On Fred''s BBS mail it to me)\n\n Or if all else fails, snail mail to:\n                              11 Gordon Tce, \n                              Rosslyn Pk                               \n                              5072,\n                              South Australia \n \n Finally if you _really_ need to talk to me my phone number is:\n +61(0)8 8332-0002 (Voice) but please no MAX''S problems! (Unless they are\n directly related to DFB).\n\n Once you have done this you will need to pay the small shareware fee\n of $30 Australian before you receive the registered keyfile! Suggested \n methods are a postal money order or a cheque for $30 Australian.\n\n If you live in one of the following areas you will receive your copy of\n DFB from the nearest distribution site:\n \n Europe (except UK):\n \n Ray De Brabander\n Amiga Force BBS EHQ\n +31-0-70-3604728\n Maxsnet: 86:20042/200 \n\n UK:\n \n Alex Jenkins\n The Cremlin\n +44 (0)121 321-3449\n\n USA/Canada:\n \n The BenchMaster\n The Bench//\/\\aster''s BBS\n (408) 238-5885\n San Jose, California\n\n I''m looking for an East Coast USA and a Canadian distribution site. What do \n you need? An Internet account and a MAX''S board running DFB, and must live \n in the USA or Canada (but not both :). \n\n Maybe even a South American distribution site will go down well.\n Convince me. 8-)\n\n Australasia: \n \n Andrew Leppard, USER of\n Fred''s BBS\n +61(0)8 3415944 (2400)\n +61(0)8 3415137 (14.4k)\n Maxsnet: 86:308/111\n   \n Then I will send out the latest registered version of DFB, the only \n registered file is a keyfile. All DFB programmes will recognize that \n you have registered and praise you accordingly.\n \n The method of transfer will be discussed. If you posted the registration\n form on one of the distribution sites you can get your copy off of there.\n \n Registration fees cover all updates up to (but not including) version 2,\n these updates will be available on Aminet and all the distribution sites,\n registered versions will be sent out upon request.\n@endnode\n\n@node "Hidden" "Congratulations"\n\n You have found the hidden link in this AmigaGuide document. Now find the \n hidden text messages in DFB! 8-) <you''ll need to have registered> \n@endnode\n\n@node "RegistrationForm" "Registration Form"\n\n A copy of this form is available separately...\n Just @{"Print out this form" system "type >PRT: DFB:regoform.txt "} and mail it to me.\n\n  \n REGISTRATION FORM FOR DFB (DYNAMIC FILE BASE V1.3)\n\n DFB V1.3 costs $30 Australian, this includes free updates. Upon payment\n you will receive a registered keyfile.\n\n All information in this form is confidential.\n \n         Name:\n               ~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n      Address:              \n               ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~               \n\n               ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~     \n   Home phone:\n               ~~~~~~~~~~~~~~~~~    \n   \n     BBS Name:  \n               ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n \n  BBS Line 1:                       FidoNet Address (MAX''S): \n               ~~~~~~~~~~~~~~~~~                            ~~~~~~~~~~~~~~~\n (BBS Line 2:)                      E-Mail Address:\n               ~~~~~~~~~~~~~~~~~\n (BBS Line 3:)                      \n               ~~~~~~~~~~~~~~~~~    ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n (BBS Line 4:)\n               ~~~~~~~~~~~~~~~~~\n (BBS Line 5:)\n               ~~~~~~~~~~~~~~~~~\n\n Workbench: (2.04/3.0):             CPU: 680 0     HD Space:\n                        ~~~~~               ~                ~~~~~~~~~~~\n Amiga:                          Memory:              MAX''S: V1.\n        ~~~~~~~~~~~~~~~~~~~~~            ~~~~~                  ~~\n Approx: # of users:         # of files: \n                     ~~~~~               ~~~~~\n                                           \n How did you find out about DFB?\n \n \n ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n Which features of DFB are you most interested in?\n \n \n ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n \n ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n \n ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n \n ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n \n Which features of DFB are you least interested in?\n \n \n ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n \n ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n \n ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n \n What new features do you want to see in DFB?\n \n \n ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n \n ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n \n ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n \n ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n \n Put a cross next to any of the following if you are interested in them:\n \n ( ) New message base system for MAX''S \n ( ) New menus system for MAX''S         \n ( ) Utility to allow CLI programmes to be run as MAX''S doors\n ( ) Utility to allow AREXX doors to be made for MAX''S. \n \n ( ) Other\n \n \n ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n Which distribution site do you want to pick up your copy of DFB:\n \n ( ) Europe (Amiga Force BBS EHQ/Ray De Brabander)\n ( ) U.K (The Cremlin/Alex Jenkins)\n ( ) U.S.A (The Bench//\/\\aster''s BBS/The BenchMaster)\n ( ) Australasia (Fred''s BBS/Andrew Leppard (user)) \n\n ( ) Via the internet, uuencode it to my mail account (enter above)\n ( ) Via airmail. Please add $5 for handling/mailing costs.\n@endnode\n','\n',char(10)),NULL,'auto-added',215018,8,0,NULL,NULL,'dfbv13','scan',1780048474);
INSERT INTO door_catalog VALUES('dfc_abs1','DFC-ABS1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DFC-ABS1.LHA','status','XIM','status',NULL,'cARABAT','DFC','....  :::: ::::  :::: ....  :::: ::::  :::: :::::      ::::       [dEFIANCE] ::::  :::: ::::       ::::  ....',replace(':::::::::. :::::::::. :::::::::.\n....  :::: ::::  :::: ....  ::::\n::::  :::: :::::      ::::       [dEFIANCE]\n::::  :::: ::::       ::::  ....\n::::  :::: ::::       ::::  :::: [pRESENTS]\n:::::::::. ::::       BD:::::::.\n.-----------------------------------------.\n!     a STATUS dOOR fOR /X^S!X cALLED     !\n      aNOTHER bLOODY sTATUS dOOR v1.0\n¡    cODE^dEZiGN bY cARABAT / dEFiANCE    ¡\n`-----------------------------[95-09-17]--''\n','\n',char(10)),'DOC.TXT',replace('\n             Quick docs for ''aNOTHER bLOODY sTATUS dOOR v1.0''\n\n       Code^Design by Carabat/Defiance''95      Releasedate: 95-09-17\n\n I don''t really think you''ll need a doc to make this work .. but anyway...\n\n---------------------------- DO NOT BLAME ME! ----------------------------\n\n        First of all, you may copy and use this program without any\n        fees or stuff  like that, but if  this  program  causes any\n        damage  to  your  system, I  will not  be  held responsible.\n\n----------------------------- HOW TO INSTALL -----------------------------\n\nIf you are running AMI EXPRESS do like this:\n  1. Copy Status to doors:AnoterBloody/\n  2. Copy S.info to BBS:Commands/Syscmd/ and BBS:Commands/BBScmd/\n  That''s it!\n\nIf S!X is your thing then this is the way:\n  1. Copy Status to doors:AnoterBloody/\n  2. Add the line below to your BBS:Commands/bbs.cmd\n--------------- Cut Here ---------------\n*S        XM010Doors:AnoterBloody/Status\n--------------- Cut Here ---------------\n  3. Copy Status to BBS:System/ (if you want it as ''default'')\n  Finished!\n\n--------------- THE ARCHIVE ''DFC-ABS1.LHA'' SHOULD INCLUDE: ---------------\n\n             Filename                Size       \n             ¯¯¯¯¯¯¯¯                ¯¯¯¯\n             AnotherBloody/Status    4744    (The main file)\n             AnotherBloody/S.info     556    (Icon for /X)\n             AnotherBloody/Doc.txt   1904    (This File...)\n             AnotherBloody/Pic.Iff  10220    (How it looks)\n\n------------------------------ cONTACT ME? -------------------------------\n\n                If you of any  reason would like to contact\n                me, mail me at one of the following boards:\n\n                     GLOBAL EFFECT · INSTANT PLEASURE\n                     NUCLEAR WASTE · OLYMPIA LEISURE\n                     PROPHETS HOLD · UNDER COVER\n\n--------------------------------------------------------------------[END!]\n','\n',char(10)),NULL,'auto-added',18980,5,0,NULL,NULL,'dfc_abs1','scan',1780048474);
INSERT INTO door_catalog VALUES('dfc_as11','DFC-AS11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DFC-AS11.LHA','status','XIM','status',NULL,'cARABAT','DFC','....  :::: ::::  :::: ....  :::: ::::  :::: :::::      ::::       [dEFIANCE] ::::  :::: ::::       ::::  ....',replace(':::::::::. :::::::::. :::::::::.\n....  :::: ::::  :::: ....  ::::\n::::  :::: :::::      ::::       [dEFIANCE]\n::::  :::: ::::       ::::  ....\n::::  :::: ::::       ::::  :::: [pRESENTS]\n:::::::::. ::::       BD:::::::.\n.-----------------------------------------.\n!     a STATUS dOOR fOR /X^S!X cALLED     !\n      aNOTHER bLOODY sTATUS dOOR v1.1\n¡    cODE^dEZiGN bY cARABAT / dEFiANCE    ¡\n`-----------------------------[95-09-24]--''\n','\n',char(10)),'DOC.TXT',replace('\n             Quick docs for ''aNOTHER bLOODY sTATUS dOOR v1.1''\n\n       Code^Design by Carabat/Defiance''95      Releasedate: 95-09-24\n\n I don''t really think you''ll need a doc to make this work .. but anyway...\n\n---------------------------- DO NOT BLAME ME! ----------------------------\n\n        First of all, you may copy and use this program without any\n        fees or stuff  like that, but if  this  program  causes any\n        damage  to  your  system, I  will not  be  held responsible.\n\n----------------------------- HOW TO INSTALL -----------------------------\n\nIf you are running AMI EXPRESS do like this:\n  1. Copy Status to doors:AnoterBloody/\n  2. Copy S.info to BBS:Commands/Syscmd/ and BBS:Commands/BBScmd/\n  That''s it!\n\nIf S!X is your thing then this is the way:\n  1. Copy Status to doors:AnoterBloody/\n  2. Add the line below to your BBS:Commands/bbs.cmd\n--------------- Cut Here ---------------\n*S        XM010Doors:AnoterBloody/Status\n--------------- Cut Here ---------------\n  3. Copy Status to BBS:System/ (if you want it as ''default'')\n  Finished!\n\n--------------------------------- FiXED ----------------------------------\n\nv1.0 -> v1.1 : Troubble with the ansi codes in v1.0, fixed now...\n\n------------------------------ cONTACT ME? -------------------------------\n\n                If you of any  reason would like to contact\n                me, mail me at one of the following boards:\n\n                     GLOBAL EFFECT · INSTANT PLEASURE\n                     NUCLEAR WASTE · OLYMPIA LEISURE\n                     PROPHETS HOLD · UNDER COVER\n\n--------------------------------------------------------------------[END!]\n','\n',char(10)),NULL,'auto-added',13401,13,0,NULL,NULL,'dfc_as11','scan',1780048474);
