INSERT INTO door_catalog VALUES('dive_sna','DIVE-SNA.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DIVE-SNA.LHA','sOUL-nFO','XIM','/\_____      /\______',NULL,'Mad','DIVE','/_____  \____/   /   /_______ /   /  /   /   /   /   ____/ .--+*#[(/______/   /_______/    ___/)]#*+--.',replace('         /\_____      /\______\n        /_____  \____/   /   /_______\n         /   /  /   /   /   /   ____/\n.--+*#[(/______/   /_______/    ___/)]#*+--.\n|:::::::::::::/___/:::::::/_______/dNO:::::|\n+---------------[ presents ]---------------+\n|     sOUL-nFO v1.0 by Mad Moose / Dive    |\n|                                          |\n|  So you easier view .NFO files in Zip &  |\n|    Lha archives! Also direct .NFO view   |\n`-------------------------------[96/01/23]-''\n','\n',char(10)),'sOUL-nFO.guide',replace('@Database sOUL-nFO v1.0 Documentation\n@Author Mad Moose / Dive\n@Remark $VER sOUL-nFO v1.0 by Mad Moose / Dive\n@Remark AmigaGuide database\n@node MAIN "sOUL-nFO v1.0 by Mad Moose / Dive       · Documentation ·"\n                   ______ ________,                ________ __ __\n       ____________j    /(________ ____  __________\  _ ________/_____\n       \      ______    __|__     \    \/          _/   _____________/\n        `---------------'' `--------\---------------''---------------''[mt]\n\n                                 pRESENTS\n\n                              sOUL-nFO v1.0\n \n                         Coded by Mad Moose / Dive\n\n                          @{"   Introduction   " Link int}\n                          @{"   Requierments   " Link req}\n                          @{"    How To Use    " Link use}\n                          @{"    The config    " Link cfg}\n                          @{"    Dive info     " Link dive}\n                          @{" History   Future " Link hf}\n                          @{"    So far...     " Link far}\n                          @{"    Greetings     " Link gre}\n                          @{"   Coming up...   " Link next}\n@endnode\n@node cfg "How to config sOUL-nFO v1.0"\n\n                     Just one line with the workpath.\n                          (Don''t forget / and :)\n\n              [ Configfile=Doors:Dive/sOUL-nFO/sOUL-nFO.cfg ]\n@endnode\n\n@node req "sOUL-nFO v1.0 Requierments"\n\n     sOUL-nFO v1.0 works under Ami Express v2.x - 4.x and S-Express\n         sOUL-nFO needs AEDoor.library v 1+ (supplied in archive)\n\n@endnode\n@node use "How To Use sOUL-nFO v1.0"\n\n              Just copy BBS/Commands/BBSCmd/ to BBS:Commands/BBSCmd/\n                    After that copy BBS/Doors to Doors:\n                And at last copy Libs/AEDoor.library LIBS:\n@endnode\n@node dive "Call This Fine Dive Board"\n                                   .____\n                  _____   ____    _|   /   _____\n               ._/ .  /__/__ /_._/ |  /_._/ .  /_\n               |   |    \_     |   |    \_  |    \_\n               |   |     /     |   |     /  ._____/\n               |   l_   /      |   |    /   |    /\n         ^aRYANl_______/l______|\______/l_______/\n\n\n  Dive WHQ     -» Secret Gate «-   3 nODES     +46-418-19666\n                                               +46-418-26900\n                                               +46-418-14100\n\n Are you a good or know somebody that is a good graphician, musician,\n or coder and want to join Dive, then why don''t you call\n Secret Gate and leave a message to Zync with some of your/his/her work!\n@endnode\n@node far "Doors And Utilities Released So Far By ME!"\n\n                    Releases From » Mad Moose / Dive «\n\n  Dive-FNA.LHA               11548      FuckNature v1.0          (AmiExpress)\n  Dive-JIA.LHA               14874      Jungle Info v1.0         (AmiExpress)\n  Dive-BOA.LHA               14204      BitchOrder v1.0          (AmiExpress)\n  Dive-CLS.LHA                1030      Cls v1.0                 (AmiExpress)\n  Dive-iD.LHA               218470      iD v1.0                  (CLi/SHELL)\n  SRE-MOVd.lha                5140      Mad Move v 0.01d         (AmiExpress)\n  SRE-OEDc.lha                4607      Online Edit v 0.01c      (AmiExpress)\n  SRE-DHEX.lha               14007      Decimal To Hex           (CLi/SHELL)\n  SRE-RUO.lha                 2676      Rexx UnOptimize          (CLi/SHELL)\n  SRE-MSDb.lha                5517      Mad SysDown v 0.01b      (AmiExpress)\n  SRE-oLiN.lha                2037      Online iNFO 0.01a        (AmiExpress)\n  SRE-BEb.lha                 2848      Mad Byte Earner v 0.01b  (AmiExpress)\n  SRE-oLDi.lha                2614      Online Dir v 0.01b       (AmiExpress)\n  SRE-NUPb.lha                4531      Mad NUP v 0.01b          (AmiExpress)\n  SRE-PW1d.lha                5007      Mad SysPW v 0.01d        (AmiExpress)\n  SRE-DELe.lha                4640      Mad Delete v 0.01e       (AmiExpress)\n\n  If you have any ideas to a new door then please contact me at Secret Gate\n  (@{" Dive info " Link dive}) and leave a message to me ("Mad Moose ")\n                                                                    ^\n                                                             Don''t forget!\n@endnode\n@node gre "Greetings"\n\n                               Greetings to\n\n            All members of Dive  · All of you can do better than this!\n			Aryan                · When do you get your board up!?\n@endnode\n@node next "Coming up..."\n\n           The following doors will be released by me very soon:\n\n\n         Bash Group Join ·   Most of you have seen texts like:\n                                  Call xxxxx to join us!\n                             Then you must call, get access and then\n                             ask if they want u. But with this door\n                             each sysop can define an account and when\n                             a user logs in under that account he will\n                             be asked to answer a few questions to join in!\n                             It''s hard to explain but wait and test it!\n                             Code & Design by Mad Moose\n         Mad Worm        ·   You all know the game Worm! (Masken, Nibbles!)\n                             Code & Design by Mad Moose\n         Dive Request    ·   A request door with an extra design and\n                             a nice request checker to faster check for\n                             new request to you and other\n                             + some special sysop functions\n                             Code Mad Moose, Design Aryan\n         Milkshake       ·   The first Move, Delete, Fake, Nuke, Edit door.\n                             With date mark, manual mark.\n                             Also possibility to see description at once.\n                             Built in help page. And much much more...\n                             Just wait and cry!\n                             Code Mad Moose, Design Aryan\n\n         And maybe more!? Why don''t you give me some suggestions!?\n                     Read @{" Dive info " Link dive} for more info!\n@endnode\n@node hf "History and future"\n\n                                  History\n                                  «-----»\n\n       v1.0  - This is the first and only release of sOUL-nFO so far!\n\n                                  Future\n                                  «----»\n\n                  Do you have any idea? Read @{" Dive info " Link dive}\n@endnode\n','\n',char(10)),NULL,NULL,18808,5,0,NULL,NULL,'dive_sna_soul_nfo','scan',1780048474);
INSERT INTO door_catalog VALUES('dized','DIZED.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DIZED.LHA','Diz-Ed','XIM','LE-win5-96.exe',NULL,NULL,NULL,'| STEELER presents DIZ-ED2.1 | |(c)95 ORiGiN/nocTurne deSign| `----------------------------''',replace('.----------------------------.\n| STEELER presents DIZ-ED2.1 |\n|(c)95 ORiGiN/nocTurne deSign|\n`----------------------------''\n','\n',char(10)),'DIZ-Ed.guide',replace('@database DIZ-Ed V2.1\n******************************************************************************\n@NODE MAIN "DIZ-Ed Version 2.1  - Complete AmigaGuide Documentation"\n\n                              @{b}DIZ-Ed Version 2.1 @{ub}\n                      (C)1995 nocTurne deSign/Origin US\n                             (C)1995 STEELER/PHN\n                        The Definitive File-ID Editor\n         ------------------------------------------------------------\n         @{" What`s New?  " LINK WHATSNEW }................STEELER simply updates DIZ-ED\n         @{" OverView     " LINK OVERVIEW }...................DIZ-Ed General description\n         @{" Requirements " LINK REQ      }...............Neccessary program supplements\n         @{" Examples     " LINK EXAMPLES }............Examples of program''s application\n         @{" Usage        " LINK USAGE    }...................Complete usage information\n         @{" Future Plans " LINK FUTURE   }....................Intentions for the future\n         @{" Update Queue " LINK UPDATE   }.............List of changes between versions\n         @{" Credits      " LINK CREDITS  }................Where credit is due/Greetings\n         ------------------------------------------------------------\n                 v1.0x users should read ENTIRE documentation\n\n@ENDNODE\n******************************************************************************\n@NODE WHATSNEW "STEELER simply updates DIZ-ED"\n\nYep... here we go again!\n\nThis is release 2.1 of DIZ-Ed !\n\nI just changed this nice sniffy program to handle LZX files correctly.\nThe bad thing is, dependant on patching the exe with a texteditor and not\nreal coding, that ZIP is not in here anymore... but who cares anyway???\n\nThe second thing done was the removal of this nub-suckin` .NFO file...\n--==>> I hate unnecessary stuff in my archives so it had to go!\n\nAll right... not much talking now:\n\nQuickies thrown out to  Gandalf/PHN             - yer Sysop of my beloved...\n                        Noodles                 - green shades around my eyes!\n                        SiliconSurfer/PHN       - poems for a girlfriend?\n                        McCoy/PHN               - no Bier vor vier\n                        Flake/TRSI              - hunter in the field\n                        Dr.Cool                 - workin`workin`workin`workin\n                        CCS                     - thanx for the line!\n                        Elli                    - the brown beard is lost\n\nI`m not a coder, but I do something...\n\nFriendship rules...Logout Fasicm!\n\nSorry OSR/NTD for patching... but there was no new release at all...\n\nThanks,\n	\nclick...\n\nNO CARRIER\n@ENDNODE\n******************************************************************************\n@NODE OVERVIEW "DIZ-Ed General Description..."\n\n DIZ-Ed  is an editor for File_ID texts within LZX, LHA, and DMS archives,\n executable  files,  and  text  files.    Familiarity  with the concept of\n File_ID''s  is  assumed.    If  this  sounds  alien to you, "Wiz & Liz" by\n Psygnosis may be purchased at one of many resellers around the globe, and\n would likely be a more APPROPRIATE choice of software.\n\n DIZ-Ed,  (now  abbreviated  DE),  provides  a  clean  and efficient 44x12\n character  editing  interface,  and is rich in features and options.  For\n traders,  file dizcriptions may be EXTRACTED, EDITED, and REPACKED easily\n from  all  types of files.  For coders/crackers, file descriptions may be\n CREATED  and  packed  within  a  file  for distribution with a MINIMUM of\n effort.\n\n Continue  reading  to  learn  more  of  the  power  of DE.  Those already\n aquainted with a former incarnation of the program should read ALL of the\n documentation.  Like a whole integer to the version number, MUCH has been\n added to this version.\n\n@ENDNODE\n******************************************************************************\n@NODE REQ "DIZ-Ed Requirements..."\n\n                     DIZ-Ed v2.1  requires the following:\n                     ------------------------------------\n                     @{"  ReqTools.library    " LINK REQ1 } @{"  LHA      " LINK REQ3 }\n                     @{"  DPaint.font         " LINK REQ2 } @{"  LZX      " LINK REQ4 }\n                     @{"  WorkBench 2.0+      " LINK REQ6 } @{"  UNLZX    " LINK REQ5 }\n                     ------------------------------------\n\n@ENDNODE\n******************************************************************************\n@NODE REQ1 "DIZ-Ed Requirement - ReqTools.library"\n\n   @{b}ReqTools.library:@{ub}\n\n   This library supplies the text and file requesters used by DE.\n   The latest version is included.\n\n@ENDNODE\n******************************************************************************\n@NODE REQ2 "DIZ-Ed Requirement - DPaint.font"\n\n   @{b}DPaint.font:@{ub}\n\n   This proportional font is used for the gadget texts.  The font is\n   coded  into  the software and will automatically be installed into\n   ''FONTS:'' if not found.\n\n@ENDNODE\n******************************************************************************\n@NODE REQ3 "DIZ-Ed Requirement - LHA"\n\n   @{b}LHA:@{ub}\n\n   This is the accepted Amiga file archiver.  It is only necessary\n   if you intend to load/edit file descriptions in LHA files.\n\n@ENDNODE\n******************************************************************************\n@NODE REQ4 "DIZ-Ed Requirement - LZX"\n\n   @{b}LZX:@{ub}\n\n   This is the accepted IBM&AMIGA file archiver.  It is only needed if you\n   intend to edit the descriptions of LZX files.\n\n@ENDNODE\n******************************************************************************\n@NODE REQ5 "DIZ-Ed Requirement - UNLZX"\n\n   @{b}UNLZX:@{ub}\n\n   This is the accepted IBM&AMIGA unarchiver, only necessary if you are going\n   to LOAD the descriptions of LZX files. To now LZX does not support a \n   onefiled unarchiver for the archives... but in LZX1.01 it`s said that \n   future version will have one! So use the same as in in the LZX-Requirement!\n\n@ENDNODE\n******************************************************************************\n@NODE REQ6 "DIZ-Ed Requirement - WorkBench 2.0+"\n\n   @{b}WorkBench 2.O+:@{ub}\n\n   This utility has been tested on WB2.1 and WB3.1.  As it uses OS2.0+\n   specific routines, you cannot be using WB1.3-.  Those using WB1.3\n   would likely be more comfortable using Micro-EMacs.\n\n@ENDNODE\n******************************************************************************\n@NODE USAGE "DIZ-Ed General Usage..."\n\n     -----------------------------------------------------------------\n     @{" Starting Up       " LINK STARTUP  }...............Command-line arguments and such\n     @{" The Edit Window   " LINK MAINWIN  }......Main window gadget and menu descriptions\n     @{" The Prefs Window  " LINK PREFSWIN }.........Preference window gadget descriptions\n     @{" The Logos Window  " LINK LOGOWIN  }.............................Logo window usage\n     @{" Making Logo Files " LINK LOGOS    }...........Description of the logo-file format\n     -----------------------------------------------------------------\n\n@ENDNODE\n******************************************************************************\n@NODE STARTUP "DIZ-Ed - Starting Up"\n\n DE  automatically  detaches  from the CLI it was run from, freeing it for\n further  use.  However the CLI may not be closed until DE is exitted,  as\n the console will be used for lha/LZX error output. DE accepts an optional \n command-line argument:  The name of the file from which it should extract \n the description at start-up. \n\n By default, the edit-window will appear on the WorkBench screen.  However\n you  may,  in  the  preferences,  choose  that it appear on the frontmost\n screen  or  on a screen of its own.  Or you may choose that it not appear\n at all upon the next start-up, in a hidden state. \n\n If  you were a user of V1.0x DE2.0 will purge your old preferences file.\n\n@ENDNODE\n******************************************************************************\n@NODE MAINWIN "DIZ-Ed Edit Window Description..."\n\n                -------------------------------------------\n                @{" Usage   " LINK MAIN1}.......Edit Window Usage/Features\n                @{" Gadgets " LINK MAIN2}..............Button Descriptions\n                @{" Menus   " LINK MAIN3}................Menu Descriptions\n                -------------------------------------------\n\n@ENDNODE\n******************************************************************************\n@NODE MAIN1 "DIZ-Ed Edit Window Usage/Features..."\n\n The fundamental editing features of DE are quite similar to those of most\n editors.    Standard  keystrokes  result  in  characters  written  to the\n display.    Cursor  keys  result  in movement of the cursor.  Cursor keys\n accompanied by the shift key move the cursor to the extreme boundaries of\n the  display.    The  cursor  may  also be positioned using the mouse, by\n clicking  on  the desired location.  The DELETE key will pull the current\n character and all those proceeding it to the left.  Shift-BackSpace pulls\n everything after the cursor to the first column.  The DEL key will delete\n the  current  character  and pull the proceeding text to the left to take\n its place.\n\n To  access  the keyboard equivalents of the buttons on the right panel of\n the  edit  window,  the CONTROL key must be held.  (eg, CONTROL-C centers\n the current line.)\n\n The  status  bar,  located  at  the  bottom  of  the  window,  will relay\n information  not worthy of a whole requester, whether it be the program''s\n current  activity  or  a  minor error.  Upon startup, the status bar will\n also  be  the  source  of  mild  amusement, as it will display a randomly\n chosen phrase.\n\n Please  read  the  remainder  of  the  guide  to  learn completely of the\n capabilities of the edit window.\n\n@ENDNODE\n*******************************************************************************\n@NODE MAIN2 "DIZ-Ed Gadget Descriptions..."\n                              -------------------\n                               @{" Clear       (X)" LINK MAINGAD1}\n                               @{" Insert Line (I)" LINK MAINGAD2}\n                               @{" Delete Line (D)" LINK MAINGAD3}\n                               @{" Center Line (C)" LINK MAINGAD4}\n                               @{" Insert      (N)" LINK MAINGAD5}\n                               @{" CursorX     n/a" LINK MAINGAD6}\n                               @{" CursorY     n/a" LINK MAINGAD7}\n                              -------------------\n@ENDNODE\n*******************************************************************************\n@NODE MAINGAD1 "DIZ-Ed Gadget Description - CLEAR"\n\n         @{b}Gadget Name: @{ub}Clear\n @{b}Keyboard Equivalent: @{ub}<CTRL>-X\n\n\n @{b}Function:@{ub}\n\n This gadget simply clears the display.  However it will not clear any\n current file affiliation; this is done with the @{" New Project " LINK MENU1} menu item.\n\n@ENDNODE\n*******************************************************************************\n@NODE MAINGAD2 "DIZ-Ed Gadget Description - INSERT LINE"\n\n         @{b}Gadget Name: @{ub}Insert Line\n @{b}Keyboard Equivalent: @{ub}<CTRL>-I\n\n\n @{b}Function:@{ub}\n\n As  might  be ascertained, this button shifts everything ON and BELOW the\n current line down one row.  Contents of the last row will be lost.\n\n@ENDNODE\n*******************************************************************************\n@NODE MAINGAD3 "DIZ-Ed Gadget Description - DELETE LINE"\n\n         @{b}Gadget Name: @{ub}Delete Line\n @{b}Keyboard Equivalent: @{ub}<CTRL>-D\n\n\n @{b}Function:@{ub}\n\n This will delete the current line, causing all text below to shift up one\n line taking its place.\n\n@ENDNODE\n*******************************************************************************\n@NODE MAINGAD4 "DIZ-Ed Gadget Description - CENTER LINE"\n\n         @{b}Gadget Name: @{ub}Center Line\n @{b}Keyboard Equivalent: @{ub}<CTRL>-C\n\n\n @{b}Function:@{ub}\n\n This will center the contents of the current line.\n\n@ENDNODE\n*******************************************************************************\n@NODE MAINGAD5 "DIZ-Ed Gadget Description - INSERT"\n\n         @{b}Gadget Name: @{ub}Insert\n @{b}Keyboard Equivalent: @{ub}<CTRL>-I\n\n\n @{b}Function:@{ub}\n\n The  state  of this checkbox gadget determines whether characters entered\n will shift forward those following the cursor.  Those characters inserted\n past the right border will be lost.\n\n@ENDNODE\n*******************************************************************************\n@NODE MAINGAD6 "DIZ-Ed Gadget Description - CURSORX"\n\n         @{b}Gadget Name: @{ub}CursorX\n @{b}Keyboard Equivalent: @{ub}n/a\n\n\n @{b}Function:@{ub}\n\n This field displays the current column number of the cursor.\n\n@ENDNODE\n*******************************************************************************\n@NODE MAINGAD7 "DIZ-Ed Gadget Description - CURSORY"\n\n         @{b}Gadget Name: @{ub}CursorY\n @{b}Keyboard Equivalent: @{ub}n/a\n\n\n @{b}Function:@{ub}\n\n This field displays the current row number of the cursor.\n\n@ENDNODE\n*******************************************************************************\n@NODE MAIN3 "DIZ-Ed Menu Items..."\n\n  @{b}Project              Text Files                   ClipBoard@{ub}\n @{" New Project        " LINK MENU1} @{" Load Text File...         " LINK MENU10} @{" Edit Buffer->ClipBoard " LINK MENU14 }\n @{" Load DIZ from...   " LINK MENU2} @{" Save Text File...         " LINK MENU11} @{" ClipBoard->Edit Buffer " LINK MENU15 }\n @{" Save DIZ           " LINK MENU3} @{" Append to Logo File...    " LINK MENU12}\n @{" Save DIZ to...     " LINK MENU4} @{" ------------------------- " LINK DIV   }\n @{" ----------------   " LINK DIV  } @{" Transmit Thru Serial Port " LINK MENU13}\n @{" Preferences...     " LINK MENU5}\n @{" Config F-Keys...   " LINK MENU6} \n @{" Save Configuration " LINK MENU7}  \n @{" ----------------   " LINK DIV  }  @{b}Logo Operations@{ub}                                     \n @{" About...           " LINK MENU8} @{" Add Logo...        " LINK MENU16} \n @{" ----------------   " LINK DIV  } @{" ------------------ " LINK DIV   }  @{b}Active Logo File @{ub}\n @{" Hide               " LINK MENU9} @{" About Logo File... " LINK MENU17} @{" < Logo File 1 > " LINK MENU19}\n @{" Quit               " LINK MENUA} @{" Reload Logos       " LINK MENU18} @{" < Logo File 2 > " LINK MENU19}\n\n@ENDNODE\n*******************************************************************************\n@NODE DIV "Thwpppt..."\n\n This is just a menu-item divider, moron.\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU1 "DIZ-Ed Menu Item - NEW PROJECT"\n\n      @{b}Menu Item Name:@{ub} New Project\n @{b}Keyboard Equivalent:@{ub} <RAMIGA>-N\n\n\n @{b}Function:@{ub}\n\n Selecting  this  menu item will clear the edit-buffer as well as any file\n affiliation.\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU2 "DIZ-Ed Menu Item - LOAD DIZ FROM..."\n\n      @{b}Menu Item Name:@{ub} Load DIZ from...\n @{b}Keyboard Equivalent:@{ub} <RAMIGA>-L\n\n\n @{b}Function:@{ub}\n\n This  menu  item  extracts  the  description from a file.  After you have\n chosen  a  filename  from the resulting file-requester, DE will determine\n the  the file''s type and scan it for a description appropriately.  If the\n filetype  cannot be determined, you will be asked if you wish the file to\n be searched as thought it were a text file.\n\n After a successful scan, the edit-buffer''s contents should match the file\n description.    If  the  description  could  not be found, you will be so\n notified in the status bar, and the screen will be cleared.\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU3 "DIZ-Ed Menu Item - SAVE DIZ"\n\n      @{b}Menu Item Name:@{ub} Save DIZ\n @{b}Keyboard Equivalent:@{ub} <RAMIGA>-S\n\n\n @{b}Function:@{ub}\n\n This will save the contents of the edit-buffer to the File_ID of the file\n whose description was last loaded, even if the file hadn''t a description.\n If  no file has been loaded, or the ''New Project'' menu had been selected,\n a  file-requester  will  prompt  you for the name of the file to save the\n description to.  Reference the edit-window''s title bar for what file this\n menu item will affect.\n\n If  a file''s type cannot be determined, you will be asked if you wish the\n description implemented as though it were a text file.\n\n The date of the file will not be changed.  \n\n **  NOTE: REPACKING A DESCRIPTION WITHIN DMS FILES MAY TAKE A WHILE  **\n **        AND REQUIRES THAT YOU HAVE ENOUGH FREE SPACE ON YOUR HARD  **\n **        DRIVE FOR A DUPE OF DMS FILE.  (for buffering purposes)    **\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU4 "DIZ-Ed Menu Item - SAVE DIZ to..."\n\n      @{b}Menu Item Name:@{ub} Save DIZ to...\n @{b}Keyboard Equivalent:@{ub} <RAMIGA>-W\n\n\n @{b}Function:@{ub}\n\n This  item  allows  you to save the current description to a file of your\n choice, by means of a file requester.  After a file has been selected, it\n will have the description injected into it by appropriate means. \n\n If  a file''s type cannot be determined, you will be asked if you wish the\n description implemented as though it were a text file.\n\n The date of the file will not be changed.  \n\n **  NOTE: REPACKING A DESCRIPTION WITHIN DMS FILES MAY TAKE A WHILE  **\n **        AND REQUIRES THAT YOU HAVE ENOUGH FREE SPACE ON YOUR HARD  **\n **        DRIVE FOR A DUPE OF DMS FILE.  (for buffering purposes)    **\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU5 "DIZ-Ed Menu Item - PREFERENCES..."\n\n      @{b}Menu Item Name:@{ub} Preferences...\n @{b}Keyboard Equivalent:@{ub} <RAMIGA>-P\n\n\n @{b}Function:@{ub}\n\n This  will call up the preferences window so that you may configure DE to\n your liking.  See the {"Preferences Window" LINK PREFSWIN} section.\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU6 "DIZ-Ed Menu Item - CONFIG F-KEYS..."\n\n      @{b}Menu Item Name:@{ub} Config F-Keys...\n @{b}Keyboard Equivalent:@{ub} <RAMIGA>-F\n\n\n @{b}Function:@{ub}\n\n (Not  yet  implemented)  This  will summon the Function Key configuration\n window, so that macros may be assigned to each of the F-Keys. \n\n@ENDNODE\n*******************************************************************************\n@NODE MENU7 "DIZ-Ed Menu Item - SAVE CONFIGURATION"\n\n      @{b}Menu Item Name:@{ub} Save Configuration\n @{b}Keyboard Equivalent:@{ub} <RAMIGA>-I\n\n\n @{b}Function:@{ub}\n\n This  will  save  all  the  current  DE  preferences  to  data   files in\n "ENV:DIZ-Ed.prefs"  and "ENVARC:DIZ-Ed.prefs".  These will will be loaded\n upon  the next execution of DE.  The following settings will be preserved\n by means of these data files:\n\n  * All Preferences settings.\n  * The currently selected logo file.\n  * The state of the ''Insert'' checkbox on the edit-window.\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU8 "DIZ-Ed Menu Item - ABOUT..."\n\n      @{b}Menu Item Name:@{ub} About...\n @{b}Keyboard Equivalent:@{ub} <RAMIGA>-A\n\n\n @{b}Function:@{ub}\n\n This  will  simply  open  a  requester   relaying   the   version number,\n compilation  date,  credits,  and abbreviated description associated with\n DE.  Registration status will also be shown. \n\n@ENDNODE\n*******************************************************************************\n@NODE MENU9 "DIZ-Ed Menu Item - HIDE"\n\n      @{b}Menu Item Name:@{ub} Hide\n @{b}Keyboard Equivalent:@{ub} <RAMIGA>-H\n\n\n @{b}Function:@{ub}\n\n As DE is now a commodity, you may choose to hide the program window if it\n is  temporarily  not needed.  This menu item will have the same effect as\n pressing  the  current hotkey, closing the window but not terminating the\n program.    To  recall the program window, you may either hit the hotkey,\n use Commodore''s Exchange program, or run the program again.\n\n@ENDNODE\n*******************************************************************************\n@NODE MENUA "DIZ-Ed Menu Item - QUIT"\n\n      @{b}Menu Item Name:@{ub} Quit\n @{b}Keyboard Equivalent:@{ub} <RAMIGA>-Q\n\n\n @{b}Function:@{ub}\n\n This item simply terminates DE.\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU10 "DIZ-Ed Menu Item - LOAD TEXT FILE..."\n\n      @{b}Menu Item Name:@{ub} Load Text File...\n @{b}Keyboard Equivalent:@{ub} n/a\n\n\n @{b}Function:@{ub}\n\n This  item  allows  text files to be loaded into the edit buffer.  If the\n file  exceeds  a  width  of 44 or a height of 12, it will be truncated as\n necessary. \n\n@ENDNODE\n*******************************************************************************\n@NODE MENU11 "DIZ-Ed Menu Item - SAVE TEXT FILE..."\n\n      @{b}Menu Item Name:@{ub} Save Text File...\n @{b}Keyboard Equivalent:@{ub} n/a\n\n\n @{b}Function:@{ub}\n\n To  save the contents of the edit-buffer to a regular ASCII file, (NOT as\n the file_id of an ascii file), use this menu item.\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU12 "DIZ-Ed Menu Item - APPEND TO LOGO FILE..."\n\n      @{b}Menu Item Name:@{ub} Append to Logo File...\n @{b}Keyboard Equivalent:@{ub} n/a\n\n\n @{b}Function:@{ub}\n\n This  will  append  the contents of the edit-buffer to a ".logos" file of\n your  choice.  If the file you select does not exist, it will be created.\n You will be requested to assign a name to the text you are appending.  If\n all  goes well a new entry will be added to the logo file.  (Note: if you\n are  adding  an  entry  to the ACTIVE logo file, you must use the ''Reload\n Logos''  menu item for DE to reload the logo file, and realize the updated\n contents.)\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU13 "DIZ-Ed Menu Item - TRANSMIT THRU SERIAL PORT"\n\n      @{b}Menu Item Name:@{ub} Transmit Thru Serial Port\n @{b}Keyboard Equivalent:@{ub} <RAMIGA>-T\n\n\n @{b}Function:@{ub}\n\n This  will  send the contents of the edit-buffer through the serial port\n (using  the  device  and  unit  defined by the "Dev|Un" preference text).\n This  may  prove  useful when you have uploaded a file to a board with no\n file_id  recognition.  In this instance you can simply "Load DIZ from..."\n the file in question, and then transmit.  If a file you have uploaded has\n no  description,  you  may find it easier to create the description in DE\n and  then  transmit  it, rather than use the crude editor most /X file_id\n packages sport.\n\n (Please  note,  your  terminal program must be using shared access to the\n serial  port  for  DE to successfully transmit.  DE will send at whatever\n baud the program has initialized at.)\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU14 "DIZ-Ed Menu Item - EDIT BUFFER->CLIPBOARD"\n\n      @{b}Menu Item Name:@{ub} Edit Buffer->ClipBoard\n @{b}Keyboard Equivalent:@{ub} <RAMIGA>-C\n\n\n @{b}Function:@{ub}\n \n This  will  copy the current description to the clipboard, (unit 0).  The\n text  may  then be pasted into other applications, (or back into DE using\n the  "ClipBoard->Edit  Buffer" item.  If you make a mistake, the two menu\n items may be used to emulate an UNDO command.)\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU15 "DIZ-Ed Menu Item - CLIPBOARD->EDIT BUFFER"\n\n      @{b}Menu Item Name:@{ub} ClipBoard->Edit Buffer\n @{b}Keyboard Equivalent:@{ub} <RAMIGA>-V\n\n\n @{b}Function:@{ub}\n \n The  contents  of  the  clipboard  (unit  0)  will  be  pasted   into the\n edit-buffer with this item.  (If the "Shift Buffer" preference setting is\n active,  the  former  contents  of  the edit-buffer will be shifted down;\n otherwise they will be eliminated.)\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU16 "DIZ-Ed Menu Item - ADD LOGO..."\n\n      @{b}Menu Item Name:@{ub} Add Logo...\n @{b}Keyboard Equivalent:@{ub} <RAMIGA>-G\n\n\n @{b}Function:@{ub}\n\n This will open the Logo window, so that you may select an ascii logo from\n the currently Active Logo File.   See the @{" Logo Window " LINK LOGOWIN} section for more\n info.\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU17 "DIZ-Ed Menu Item - ABOUT LOGO FILE..."\n\n      @{b}Menu Item Name:@{ub} About Logo File...\n @{b}Keyboard Equivalent:@{ub} n/a\n\n\n @{b}Function:@{ub}\n\n If  the  currently  Active  Logo  File  has  an About text defined by the\n creator, a requester will appear containing this text.\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU18 "DIZ-Ed Menu Item - RELOAD LOGOS"\n\n      @{b}Menu Item Name:@{ub} Reload Logos\n @{b}Keyboard Equivalent:@{ub} n/a\n\n\n @{b}Function:@{ub}\n\n This  will simply reload the current logo directory as well as the Active\n Logo File.\n\n@ENDNODE\n*******************************************************************************\n@NODE MENU19 "DIZ-Ed Menu Item - ACTIVE LOGO FILE MENU"\n\n      @{b}Menu Item Name:@{ub} < Logo File xx >\n @{b}Keyboard Equivalent:@{ub} n/a\n\n\n @{b}Function:@{ub}\n\n The  Active  Logo  File  menu  is  a  list  of  mutually  exclusive items\n representing  logo  files present in the logos directory, (defined by the\n the "Logos" preference text).  The contents of the menu are the filenames\n minus  the  ".logos"  extension.  Checking one of these items renders its\n respective  logo  file  active;  that  is,  the  functions  in  the ''Logo\n Operations'' menu will use that particular logo file.  Dig?\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSWIN "DIZ-Ed Preference Window Gadgets"\n                 --------------------------------------------\n                     Cursor Wrap @{"  " LINK PREFSGAD1}  \n                 Start Up Hidden @{"  " LINK PREFSGAD2}    Screen @{"              " LINK PREFSGAD6 }\n                    Shift Buffer @{"  " LINK PREFSGAD3}   Hot Key @{"              " LINK PREFSGAD7 }\n                 Dither Backdrop @{"  " LINK PREFSGAD4}  BackDrop @{"              " LINK PREFSGAD8 }\n                  Real-Time Logo @{"  " LINK PREFSGAD5}  Cursor Type @{"           " LINK PREFSGAD9 }\n               \n                 Downloads Path @{"                        " LINK PREFSGAD10} @{" ? " LINK PREFSGAD11}\n                 LogoFiles Path @{"                        " LINK PREFSGAD12} @{" ? " LINK PREFSGAD11}\n               \n                   Name @{"            " LINK PREFSGAD13}    LHA @{"           " LINK PREFSGAD16} @{" ? " LINK PREFSGAD11}\n                    Tag @{"            " LINK PREFSGAD14}    LZX @{"           " LINK PREFSGAD17} @{" ? " LINK PREFSGAD11}\n                 Dev|Un @{"            " LINK PREFSGAD15}  UNLZX @{"           " LINK PREFSGAD18} @{" ? " LINK PREFSGAD11}\n                 --------------------------------------------\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD1 "DIZ-Ed Preference Window Gadget - CURSOR WRAP"\n\n         @{b}Gadget Name:@{ub} Cursor Wrap\n @{b}Keyboard Equivalent:@{ub} W\n\n\n @{b}Function:@{ub}\n\n The state of this checkmark gadget determines whether the cursor will\n wrap around the edit-window after it has passed a boundary.\n \n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD2 "DIZ-Ed Preference Window Gadget - START UP HIDDEN"\n\n         @{b}Gadget Name:@{ub} Start up Hidden\n @{b}Keyboard Equivalent:@{ub} S\n\n\n @{b}Function:@{ub}\n\n If this option is set and the configuration is saved, the edit-window\n will start in a hidden state the next time you run DE.  \n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD3 "DIZ-Ed Preference Window Gadget - SHIFT BUFFER"\n\n         @{b}Gadget Name:@{ub} Shift Buffer\n @{b}Keyboard Equivalent:@{ub} F\n\n\n @{b}Function:@{ub}\n\n If  this option is set, pastes from the clipboard and logo additions will\n not  purge  the former contents of the edit-buffer, but rather shift them\n down.\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD4 "DIZ-Ed Preference Window Gadget - DITHER BACKDROP"\n\n         @{b}Gadget Name:@{ub} Dither Backdrop\n @{b}Keyboard Equivalent:@{ub} T\n\n\n @{b}Function:@{ub}\n\n If this is set the background color will be dithered rather than solid. \n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD5 "DIZ-Ed Preference Window Gadget - REAL-TIME LOGO"\n\n         @{b}Gadget Name:@{ub} Real-Time Logo\n @{b}Keyboard Equivalent:@{ub} O\n\n\n @{b}Function:@{ub}\n\n If this is set, a temporary buffer will be set up so that you may see the\n logo  texts when you are browsing through them.  The former contents will\n be restored if you do not choose a logo.\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD6 "DIZ-Ed Preference Window Gadget - SCREEN"\n\n         @{b}Gadget Name:@{ub} Screen\n @{b}Keyboard Equivalent:@{ub} R\n\n\n @{b}Function:@{ub}\n\n This cycle gadget has three states and determines which screen DE\n will make its residence upon.\n\n * WorkBench - DE will open on the WorkBench screen.\n\n * Custom - DE will open a 4 color public screen of its own,\n            with the name "DIZ-Ed_PubScreen".\n\n * FrontMost - DE will open on whichever screen the active window\n               is on.  Using the hot-key you can easily make DE\n               appear on your terminal program''s screen, or wherever\n               you so desire.  DE will adapt to the screen it\n               resides on.\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD7 "DIZ-Ed Preference Window Gadget - HOT KEY"\n\n         @{b}Gadget Name:@{ub} Hot Key\n @{b}Keyboard Equivalent:@{ub} H\n\n\n @{b}Function:@{ub}\n\n If  the key sequence here is pressed, DE''s visible state will be toggled.\n (For  instance, if the key-sequence is the default "LCOMMAND d", pressing\n Left-Amiga  d  will  cause  the window to disappear or reappear.) Consult\n some manual or something to learn the key names.\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD8 "DIZ-Ed Preference Window Gadget - BACKDROP"\n\n         @{b}Gadget Name:@{ub} BackDrop\n @{b}Keyboard Equivalent:@{ub} B\n\n\n @{b}Function:@{ub}\n\n This is merely an aesthetic option, which lets you define which color\n the empty parts of windows should assume.\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD9 "DIZ-Ed Preference Window Gadget - CURSOR TYPE"\n\n         @{b}Gadget Name:@{ub} Cursor Type\n @{b}Keyboard Equivalent:@{ub} Y\n\n\n @{b}Function:@{ub}\n\n Another aesthetic option, this slider will determine what type of\n complementing cursor you want.\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD10 "DIZ-Ed Preference Window Gadget - DOWNLOADS PATH"\n\n         @{b}Gadget Name:@{ub} Downloads Path\n @{b}Keyboard Equivalent:@{ub} D\n\n\n @{b}Function:@{ub}\n\n The path listed here will be used by default in the file requesters\n for loading and saving descriptions.\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD12 "DIZ-Ed Preference Window Gadget - LOGOFILES PATH"\n\n         @{b}Gadget Name:@{ub} LogoFiles Path\n @{b}Keyboard Equivalent:@{ub} P\n\n\n @{b}Function:@{ub}\n\n The path listed here is where DE will look to fetch logo files.\n \n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD13 "DIZ-Ed Preference Window Gadget - NAME"\n\n         @{b}Gadget Name:@{ub} Name\n @{b}Keyboard Equivalent:@{ub} N\n\n\n @{b}Function:@{ub}\n\n Put your name here if you want.\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD14 "DIZ-Ed Preference Window Gadget - TAG"\n\n         @{b}Gadget Name:@{ub} Tag\n @{b}Keyboard Equivalent:@{ub} G\n\n\n @{b}Function:@{ub}\n\n Your 44 character sent-by line should be pasted here.  It will be\n sent with the transmit option if it exists.\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD15 "DIZ-Ed Preference Window Gadget - DEV|UN"\n\n         @{b}Gadget Name:@{ub} Dev|Un\n @{b}Keyboard Equivalent:@{ub} V\n\n\n @{b}Function:@{ub}\n\nThis  string  contains  the  device  and  unit that will be used with the\n"Transmit Thru Serial Port" function.  The default text "serial.device|0"\nwill  use  the  serial  device  unit  0,  and should be suitable for most\napplications.  (Note the device and unit number are separated with a ''|'')\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD16 "DIZ-Ed Preference Window Gadget - LHA"\n\n         @{b}Gadget Name:@{ub} LHA\n @{b}Keyboard Equivalent:@{ub} A\n\n\n @{b}Function:@{ub}\n \n This text here should be the path and filename of your LHA executable.\n The default is "LHA".\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD17 "DIZ-Ed Preference Window Gadget - LZX"\n\n         @{b}Gadget Name:@{ub} LZX\n @{b}Keyboard Equivalent:@{ub} Z\n\n\n @{b}Function:@{ub}\n\n The text here should be the path and filename of your LZX executable.\n The default is "LHA".\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD18 "DIZ-Ed Preference Window Gadget - UNLZX"\n\n         @{b}Gadget Name:@{ub} UNLZX\n @{b}Keyboard Equivalent:@{ub} I\n\n\n @{b}Function:@{ub}\n\n The text here should be the path and filename of your UNLZX executable.\n The default is "UNLZX".\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSGAD11 "DIZ-Ed Preference Window Gadget - <File Requester Thingy>"\n\n         @{b}Gadget Name:@{ub} <File Requester Thingy> (FRT)\n @{b}Keyboard Equivalent:@{ub} 1-5\n\n\n @{b}Function:@{ub}\n\n This  button  allows  you to select the contents of its accompanying text\n gadget  with  a  file  requester.  The keyboard equivalent is the numeric\n equivalent  of  its  vertical  position.    The  "Downloads Path" FRT  is\n selected by pressing ''1'', while the "UNLZX" FRT is selected with ''5''.\n\n@ENDNODE\n******************************************************************************\n@NODE EXAMPLES "DIZ-Ed Usage Examples..."\n _________________________________________________________________________\n                                                                          \n OK,  so  you''ve  downloaded the latest World Charts, but some board put a\n advert  in  the DIZcription.  So, you select the "Load..." gadget, select\n "HLM-WCxx.dms"  from  the  file-requester, click the cursor onto the line\n with  the  advert,  and  hit  the "Delete Line" gadget, (or <CTRL>-D; all\n keyboard  equivalents  must  be accompanied by a CTRL).  Selecting "Save"\n will save the new description back to the archive.\n _________________________________________________________________________\n\n OK, so you''ve just finished fixing Blood Money for AGA.  You''ve packed it\n in DMS format, and now you load up DE and select "Tango" from the "Active\n Logo File" menu.  After hitting "Right-Amiga G", (equivalent for the "Add\n Logo"  menu  item),  a  list  of group logos from Tango will appear.  You\n press  "Right-Amiga  T" to jump to the logos beginning with ''T'', and then\n double-click  your  group''s  logo, "Throbbing Grissle".  After adding the\n traditional  "Presents"  line,  you  select  "Save  As..."  and  save the\n description to your archive.  \n _________________________________________________________________________\n \n So  you  uploaded  a  file  to a board from the Dark Ages with no FILE_ID\n support,  and  its  asking you to describe this file.  So you use "DIZ-ED\n <filename>" from the cli and then hit "Right-Amiga T" to send it thru the\n serial port.\n _________________________________________________________________________\n \n OK, so you''re a cool ASCII artist and you wanna create some Ami-X listing\n compatible  logos.   So you simply draw your logo, select "Append to Logo\n File", enter the name of the logo file to create/append the entry to, and\n then enter the name of the logo you''ve drawn.  Or you may simply save the\n picture  as  a  regular text file, (selecting "Save Text File..."), to be\n loaded later.\n  _________________________________________________________________________\n\n@ENDNODE\n****************************************************************************\n@NODE LOGOWIN "DIZ-Ed Logo Window Description..."\n\n The logos window is composed of a list of logos from the currently active\n text  file,  and the traditional "Use" and "Cancel" gadgets.  In addition\n to  manually  scrolling  throught the list with the slider, there are now\n other means of getting to the logo you want.\n\n * Up & Down Keys - One entry up or down.\n                  - When accompanied by SHIFT, page up or page down.\n                  - With CONTROL, extreme top or extreme bottom.\n\n * Right Amiga @ - Where @ is a letter from the alphabet you want\n                   to jump to.  (example: <RAMIGA>-O jumps to the\n                   to the logos beginning with O, [eg ORIGIN:])\n \n * Return and ''U'' - Uses the currently selected logo.\n\n * ESC and ''C'' - Cancels logo window\n\n If  the  preferences  setting  "Real-Time Logos" is active, as you scroll\n through  logos the edit-buffer will reflect what the selected entry looks\n like. \n\n If  you  are  running  OS3.0+  the  selected  entry  will be highlighted;\n otherwise there will be the drab 2.0 text display gadget with the current\n entry''s name.\n\n If  you  double-click,  hit  return, or "Use" a logo, the contents of the\n edit-buffer  will  be  wiped  to  make  way  for the logo.  If the "Shift\n Buffer" prefs option is on the contents will be shifted down. \n\n@ENDNODE\n******************************************************************************\n@NODE LOGOS "DIZ-Ed Logos..."\n\n A  DE  logo  file  contains  text  logos  with  special  commands that DE\n recognizes  to differentiate between the entries.  It is required to have\n the extension ".logos" in the filename for it to be recognized by DE.\n \n The  beginning of a logo entry is denoted by a @LOGO immediately followed\n by  the  name  of  the logo in quotes.  Of course, these don''t have to be\n logos;  they  could  be  pictures or commonly used texts, or whatever you\n decide when you create your own entries.\n \n At  the end of each logo entry, an @ENDLOGO command should be placed.  Of\n course,  any  comments  or  notes  may  be  placed in regions between the\n entries.\n \n About  texts may now be implemented using @ABOUT to signify the beginning\n of  the  section and @ENDABOUT at the end.  This text should typically be\n under  60 chars wide  and 10 tall.   Note the text will be AUTO CENTERED, \n so keep it left justified.  \n \n Please  reference the included logo-texts to get a better feel for making\n these files.\n \n@ENDNODE\n******************************************************************************\n@NODE FUTURE "DIZ-Ed Foresight..."\n\n Future plans for implementation:\n\n    * Faster DMS save routine\n    * F-Key macros\n    * Naked ladies\n\n@ENDNODE\n******************************************************************************\n@NODE UPDATE "DIZ-Ed Update List history..."\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n                                H I S T O R Y :\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@{b}1.00 ???-??@{ub}     |    · First release\n                |\n@{b}1.01 ???-??@{ub}     |    · Fixed two problems with LHA adding.  In some\n                |      instances, DIZ-ED thought some LHA files were TEXT\n                |      FILES!  You can call me Mr.  Incompetant.  Many\n                |      thanks to Aquarius/OTL for pointing this out.\n                |\n                |      Also, if you tried loading an LHA file which had no\n                |      dizcription, the file would be LOCKED, and could not\n                |      be written to.  Incompetance is my middle name.\n                |      Thanks to Outlaw/(Uzi Suicide BBS) for pointing this\n                |      one out.\n                |                    \n                |    · Fixed the copyright year; some parts said 1993!\n                |      I''m a year behind in competance TOO!\n                |\n                |    · Repaired some enforcer hits.\n                |\n@{b}2.00 Jul-94@{ub}     |    · © 94 OSiRiS/nocTurne deSign\n                |      Changed a pixel in the icon.  :)\n                |\n@{b}2.1  Mar-95@{ub}     |    · My release: Not much of a poke! © 95 STEELER/PHN\n                |    · Removed the saving of the .NFO file!\n                |    · Added support for LZX-archives and removed ZIP-support!\n                       I needed the space...\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@ENDNODE\n******************************************************************************\n@NODE CREDITS "DIZ-Ed Credits..."\n\n         This program was coded by nocTurne (deSign)/Origin US.\n                      Thanks to the following people:\n\n           Remo/MST - Executable and DMS description adding routines.\n       Aquarius/OTL - Intensive testing and suggestions.\n          Dan Silva - Dpaint font.\n          Tango/OGN - Nice logo file/OGN initiation.  Yank THIS.\n            M.BiSON - Thanks for use of your board\n         Highlander - Thx for testing, will use the ascii when I \n                      find a place for it.\n             D-Siya - Thanks for finding that text thing.\n        Blind Melon - Musical support\n        STEELER/PHN - Update to 2.1 just some little adds\n                           -----------------\n\n                To contact me, call my new tek-support HQ:\n\n       DOMiNO EFFECT - 2 NODES @ 28.8K - A4000/040 40Mhz - 3.3 GIGZ\n              +1.503.758.0019 - New User Password: twinturbo\n\n             or my internet address: "[email removed]"\n\n     PLEASE yell to one of the above places if you encounter any bugs\n      so that I may fix them in the next release.  Enjoy... noC out!\n@ENDNODE\n******************************************************************************\n                    What the fuck are you looking at??','\n',char(10)),NULL,'auto-added',127371,5,0,NULL,NULL,'dized','scan',1780048474);
INSERT INTO door_catalog VALUES('dized101','DIZED101.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DIZED101.LHA',NULL,'XIM','DIZ-Ed',NULL,'nocTurne',NULL,'%%| ______  ___/  /_______/  /__/__/_____|%% %%|/      \/  /  /  _____/  ___/  /  ____/%% %%/  / /  /  /  /\____ \/  /  /  /  /   /|%%',replace('%%|             ___        ___   ___     |%%\n%%| ______  ___/  /_______/  /__/__/_____|%%\n%%|/      \/  /  /  _____/  ___/  /  ____/%%\n%%/  / /  /  /  /\____ \/  /  /  /  /   /|%%\n%/__/_/__/\__  /\______/  /  /__/\_____/ |%%\n%%|      \____/        \____/  presents  |%%\n%%l______________________________________j%%\n~~~ ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n:   DIZ-Ed Version 1.01 - BugFix Release   :\n¦        by nocTurne deSign in 1994        ¦\nl__________________________________________j\n[iFFTic · $TUFF fROM tHE $TATE$! · cOURIERs]\n','\n',char(10)),'DIZ-Ed.guide',replace('@database DIZ-Ed V1.01\n******************************************************************************\n@NODE MAIN "DIZ-Ed Version 1.01 (©1994 nocTurne deSign) - Complete Documentation"\n\n\n                   DIZ-Ed Version 1.01 - BUG-FIX Update\n                     (C)1994 nocTurne deSign/Mystic US\n\n                       The Definitive File-ID Editor\n\n                              =-=-=-=-=-=-=-=\n\n           V1.00 Users need only to read update list and credits\n\n  This version is also to announce that I AM working on a new version of\n      tool.  V1.5 will feature many nice new options so WATCH FOR IT!\n\n                           @{"      OverView       " LINK OVERVIEW }\n                           @{"    Requirements     " LINK REQ }\n                           @{"       Usage         " LINK USAGE }\n                           @{"    Future Plans     " LINK FUTURE }\n                           @{"    Update Queue     " LINK UPDATE }\n                           @{"      Credits        " LINK CREDITS }\n\n@ENDNODE\n******************************************************************************\n@NODE OVERVIEW "DIZ-Ed General Description..."\n\n DIZ-Ed is an editor for File ID''s (made popular by Mystic''s FILE_ID\n utility for AmiExpress).  It provides a clean and efficient editing\n interface, as well as many pre-made logos for your use.  For traders,\n file dizcriptions may be extracted, edited, and repacked easily \n from DMS, Executable, LHA, or text files.  For coders/crackers,\n file dizcriptions may be created and packed with in the file to be\n distributed with a minimum of effort.\n \n This program features several options and is very powerful and flexible.\n Because this is a Mystic release, it IS the new standard for file ID\n editors, so if you trash this archive, you are foolish.  Please read\n further, and learn more about this nocTurne deSign/MST release.\n\n@ENDNODE\n******************************************************************************\n@NODE REQ "DIZ-Ed Requirements..."\n\n          DIZ-Ed Version 1.01 requires the following to function:\n\n\n        · ReqTools.library - For file and text requesters.\n                       \n        · Dpaint.font - For cool looking gadgets. (If you don''t \n                        have it, the font is coded into the software\n                        and will automatically be installed into \n                        FONTS:)\n\n        · LHA - Must be accessible, either by being in C: or having\n                a path to its directory.\n\n        · WB2.0+ - This utility has been tested on WB2.1 and WB3.1.\n\n\n             Everything you need is included in this release...\n\n@ENDNODE\n******************************************************************************\n@NODE USAGE "DIZ-Ed General Usage..."\n\n Upon startup, DIZ-Ed will search for the dpaint.font (a nice proportional\n font for use with the gadgets).  If it is not found, the program will\n attempt to install the font in your "FONTS:" directory.\n \n If all goes well, you should be greeted with the editing interface. \n It is suggested you read the examples of DIZ-Ed''s usage before reading\n the itemized description of the program''s options, so that you may \n better acquaint yourself with the typical operation of the program.\n \n                          @{" Usage Examples    " LINK EXAMPLES  }\n                    \n                          @{" The Main Window   " LINK MAINWIN }\n                          @{" The Logos Window  " LINK LOGOWIN }\n                          @{" The Prefs Window  " LINK PREFSWIN }\n\n                          @{" Editing Features  " LINK EDIT\n                    \n                          @{" Making Logo Files " LINK LOGOS }\n\n\n@ENDNODE\n******************************************************************************\n@NODE MAINWIN "DIZ-Ed Main Window Description..."\n\n  Following are descriptions of each button on the main window.  Note that \n  keyboard-equivalents are accessible when the right Amiga key is held.\n    \n  ''Clear'' - This will cleanse the edit-buffer.  Double clicking will\n            clear any file affiliation with the description.\n\n  ''Insert Line'' - All lines after and including the cursor''s line will\n                  be shifted down.  (The last line will be lost.)\n\n  ''Delete Line'' - The cursor''s line will be deleted and everything\n                  below will be shifted up.\n\n  ''Insert'' - This checkbox will determine whether characters entered will\n             push forward others occupying the same line.  (Operations with\n             the backspace and DEL keys will still pull characters,\n             however.)\n\n  ''Logos...'' - See @{"The Logo Window" LINK LOGOWIN}...\n\n  ''Prefs...'' - See @{"The Prefs Window" LINK PREFSWIN}...\n\n  ''Load...'' - This will summon a file-requester thats directory defaults\n              to the one defined in preferences.  After a file is selected,\n              it will be scanned to determine its type, and if recognized\n              the description will be extracted if it exists.  Note that\n              when you "Save" the description, it will be saved to this\n              file.  Reference the window title to see what file a\n              "Save" operation will affect.\n\n  ''Save'' - This will save a description to the file shown in the main\n           window''s title bar.  If it states that no file is loaded,\n           a file-requester will appear.  (See ''Save As...'')\n\n  ''Save As...'' - A file-requester will prompt you for the file to\n                 save this decription to.  If you enter a file that\n                 does not exist, a simple text file with the logo\n                 will be created.\n\n **  NOTE: REPACKING A DESCRIPTION WITHIN DMS FILES MAY TAKE A WHILE  **\n **        AND REQUIRES THAT YOU HAVE ENOUGH FREE SPACE ON YOUR HARD  **\n **        DRIVE FOR A DUPE OF DMS FILE.  (for buffering purposes)    **\n\n  ''About...'' - Renders the program information visible.\n\n  ''Quit'' - As the window''s close box does, this frees all resources and \n           exits the program.\n\n@ENDNODE\n******************************************************************************\n@NODE EXAMPLES "DIZ-Ed Usage Examples..."\n\n OK, so you downloaded the latest SCoopeX Never Mind mag-part issue, but \n the loser who packed it put his sent-by in the DIZcription.  So, you\n select the "Load..." gadget, select "SCX-NMxx.exe" from the file-requester,\n click the cursor onto the line with the guy''s name, and hit the "Delete\n Line" gadget, (or Right-Amiga ''D''... All keyboard equivalents must\n be accompanied by a Right-Amiga).  Pressing "Save" will immediately\n save back the description to the executable.\n \n OK, so you''ve just finished fixing Shadow of the Beast 1 fixed for the\n AGA chipset.  You''ve packed it in DMS format, and now you load up\n DIZ-Ed and select "Logos...".  A list of group logos (found from\n @{"''logos.txt''" LINK LOGOS} as default) will appear, from which you double-click\n your group''s name.  After adding the traditional "Presents" tailer, you\n select "Save As..." and save the description to your archive.\n \n OK, so you''re a cool AZKII artist and you wanna create some files with\n /X compatible logos.  So you simply draw your logo, "Save As...", and\n save to a new file.  A header will be prepended to these files, so that\n DIZ-Ed will recognize them when re-loaded.  \n \n@ENDNODE\n******************************************************************************\n@NODE LOGOWIN "DIZ-Ed Logo Window Description..."\n\n The window containing the logos from the logo file, (determined in \n preferences), will be summoned when the "Logos..." gadget is pressed. \n Double-clicking or "Use"ing a logo entry will replace the edit-buffer \n with the selected text.  Cancel aborts the operation all together.\n\n@ENDNODE\n******************************************************************************\n@NODE PREFSWIN "DIZ-Ed Preferences Window Description..."\n\n ''Download Directory'' - This path will be used as a default for loading\n                        and saving file-requesters.\n\n ''Logo File'' - This file will be the source of logo texts.\n\n To access the ''get-file'' gadgets adjacent to the string gadgets, press\n the numeric equivaled of their vertical position.  (eg, to get a file\n requester for download directory, press ''1'').\n\n If you choose to "Save" these preferences, your options will be preserved\n when you next use this program.\n\n@ENDNODE\n******************************************************************************\n@NODE EDIT "The DIZ-Ed Editor features..."\n\n Shift-Cursor: Moves the cursor to the extreme boundaries.\n\n Control-C: Centers the current line.  Unlike certain other editors,\n            spaces behind and in-front of the text to be centered will\n            be neglected, resulting in a TRUE center.  \n\n Shift-BackSpace: Pulls everything after the cursor to the first column.\n\n RAmiga+Button Letter:  Accesses one of the button equivalents.\n\n\n@ENDNODE\n******************************************************************************\n@NODE LOGOS "DIZ-Ed Logos..."\n\n By default, logos come from the text file "logos.txt", which may be changed\n by the preferences option.  This file contains many logos with special\n commands that DIZ-Ed recognizes to differentiate between the entries.\n \n The beginning of a logo entry is denoted by a @LOGO immediately followed\n by the name of the logo in quotes.  Of course, these don''t have to be \n logos; they could be pictures or commonly used texts, or whatever you \n decide when you create your own entries.\n \n At the end of each logo entry, an @ENDLOGO command should be placed.  Of\n course, any comments or notes may be placed in regions between the\n entries.\n \n Use @ENDFILE to signify the end of the file.\n \n Please reference the file enclosed, "logos.txt", to get a better feel\n for making logo files.  I would like to see some DIZ-Ed collections\n in the near-future.  If you have made a cool logo file, send it to\n me and I may use it in a future release.  (See the @{"Credits" LINK CREDITS} for how\n you may contact me.)\n \n@ENDNODE\n******************************************************************************\n@NODE FUTURE "DIZ-Ed Foresight..."\n\n Future plans for implementation:\n\n    * Cut, Copy, n'' Paste - (I don''t look forward to coding this...)\n\n    * Serial Send - For those boards not having File_ID recognition\n\n    * Faster save routines\n\n    * Command Line Arguments\n\n    * Whatever sounds cool you guys suggest...\n\n@ENDNODE\n******************************************************************************\n@NODE UPDATE "DIZ-Ed Update List..."\n\n\n Changes from V1.00 to V1.01:\n\n  · Fixed two problems with LHA adding.  In some instances, DIZ-ED thought\n    some LHA files were TEXT FILES!  You can call me Mr. Incompetant. Many\n    thanks to Aquarius/OTL for pointing this out.\n\n    Also, if you tried loading an LHA file which had no dizcription, the\n    file would be LOCKED, and could not be written to.  Incompetance is\n    my middle name.  Thanks to Outlaw/(Uzi Suicide BBS) for pointing this\n    one out.\n\n  · Fixed the copyright year; some parts said 1993!  I''m a year behind in\n    competance TOO!\n\n  · Repaired some enforcer hits.\n\n  Version 1.5 is in the works...  Clipboard support, serial transmission,\n  and much more.  Until then, enjoy!\n\n  (P.S:  Haven''t ANY of you found the SECRET part yet??)\n\n@ENDNODE\n******************************************************************************\n@NODE CREDITS "DIZ-Ed Credits..."\n\n         This program was coded by nocTurne (deSign)/Mystic US.  \n                Other credits (newest entries at the top):\n\n        \n        Outlaw - For much help in tracing a bug he found.\n\n        Aquarius - For the great SUGGESTIONS and pointing out the\n                   nasty LHA bug...  (Nice /X utils!)\n\n        Mr. Vain - For the ascii collection and nice comments.\n\n        Axe/MST - For the many suggestions and bug-testing,\n                  as well as letting me in... :)\n\n        Re/Y\o/MST - For the DMS and EXE packing routines.\n\n        Revenger/2KAD - For GREAT bug-testing and assistance.\n\n        /\donis/OBS - For testing and suggestions. \n\n        Minstrel/ZNT - For testing.\n\n        Axy - For the cool Mystic startup logo.\n\n        Some DPaint lackey - For the dpaint.font. (Where the hell is\n                             the standard PROPORTIONAL amiga font, C=??)\n\n        The Guys at RefLeX - For the cool swedish swear words.\n\n                             -----------------\n\n           To contact me call Sarcophaguz BBS (+1.503.548.0532)\n      or one of the following boards (and leave mail to ''nocTurne''):\n\n       Eleventh Hour, Uzi Suicide, Trash City, Masterbation Station,\n                    or any other board you see me on...\n\n\n                 Until the next release, enjoy... noC out!\n@ENDNODE\n******************************************************************************\n                    What the fuck are you looking at??','\n',char(10)),NULL,'auto-added',61076,2,0,NULL,NULL,'dized101','scan',1780048474);
INSERT INTO door_catalog VALUES('dj_ahack','DJ_AHACK.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DJ_AHACK.LHA',NULL,'XIM','________   _____  ____________  __  __',NULL,NULL,'DJ','/_/:____:\_/:___:\/:____: _ :_:\/: \/: \ \/ /\__/ _  /_  \  /_  / // / \  /\ :/\ \ / / / / // __/  / __/ / // /__/: \ \ \ \ \',replace('  ________   _____  ____________  __  __    \n /_/:____:\_/:___:\/:____: _ :_:\/: \/: \   \n \/ /\__/ _  /_  \  /_  / // / \  /\ :/\ \  \n / / / / // __/  / __/ / // /__/: \ \ \ \ \ \n/:/\__/://:/___ /:/___/://:______\:\ \:\ \:\\n\______/ \____/ \/ \___/ \/BRUCE\__/  \/  \/\n.------------------------------------------.\n| DEFJAM PRESENTS /X\AMIEX PASSWORD HACKER |\n`------------------------------------------''\n','\n',char(10)),'DJ_AHACK.README',replace('      ________   _____  ____________  __  __    \n     /_/:____:\_/:___:\/:____: _ :_:\/: \/: \   \n     \/ /\__/ _  /_  \  /_  / // / \  /\ :/\ \  \n     / / / / // __/  / __/ / // /__/: \ \ \ \ \ \n  __/:/\__/://:/___ /:/___/://:______\:\ \:\ \:\\n  \________/ \____/ \/ \___/ \/BRUCE\__/  \/  \/\n\n       DEFJAM`S /X\AMIEXPRESS PASSWORD HACK\n       ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                  -* V1.0 DEMO *-\n\nDIES IST DIE EINGESCHRAENKTE VERSION FUER 1-4 ZEICHEN\nBREITE PASSWOERTER.AUF EINEM A3000/25 DAUERT EIN USER\nSCAN CA.11 SEC`S [RANGE: A-Z] BIS ZUM FAIL FINDET DAS\nPROGRAMM EIN PASSWORT,GEHT`S NATUELICH SCHNELLER. DIE\nVOLLVERSION SCANNT BIS ZU 8 CHAR BREITEN PASSWOERTERN\n\nAMIEX CRYPTET DIE PW`S UEBER DAS X-FLAG,DADURCH GEHEN\nBYTES VERLOREN UND LASSEN SICH NICHT ZURUECKBERECHNEN\nBLEIBT NUR DIE MOEGLICHKEIT, DAS .ABC.. HOCHZUZAEHLEN\nUND ZU VERGLEICHEN.EINE ANDERE MOEGLICHKEIT WERDE ICH\nSPAETER AUSPROBIEREN.DADURCH DASS MAN IN AMIEX BIS ZU\n132  CHARS EINGEBEN KANN,WUERDE EIN USERSCAN EIN PAAR\nHUNDERT JAHRE DAUERN.[8] CHARS SIND IM MOMENT DAS ZU-\nMUTBARE. DIE PROZESSORAUSLASTUNG LIEGT HIER BEI 100%.\nDESHALB SOLLTEN PARALLEL  KEINE ANDEREN PRG`S LAUFEN.\n\nANLEITUNG: AMI-EXPRESS USERDATEN LADEN\nGGF.RANGEBEREICH EINGEBEN.[DEFAULT:A-Z BIS AAAA-ZZZZ]\nENTWEDER - DIE USER EINZELN SELEKTEN [GADGETS: << >>]\nUND DANN AUF START GEHEN.      [START =  EINZEL-SCAN]\nODER GLEICH AUTO EINSCHALTEN.  [AUTO = KOMPLETT SCAN]\nWAEHREND DES SCANNENS IST ABBRUCH DURCH STOP MOEGLICH\nDANACH KOENNEN DIE ERGEBNISSE ABGESEICHERT WERDEN.\n\n  CONTACTS: BRUCE/DEFJAM /T\ SKYLINE BBS [ONLY-PD]\n  1. +49 [0]30 824 10 71     2.+49 [0]30 824 10 71\n\n\nANM.: BEI  7.14 MHz DAUERT EIN SCAN [A-ZZZZ] ca.90 SEKUNDEN\n      BEI 25.00 MHz DAUERT EIN SCAN [A-ZZZZ] ca.12 SEKUNDEN\n\nDA DIE PW`s IN GROSSBUCHSTABEN GEWANDELT WERDEN BRAUCHT MAN\nNICHT AUF KLEINBUCHSTABEN ZU SCANNEN!\n','\n',char(10)),NULL,NULL,3151,3,0,NULL,NULL,NULL,'scan',1780048474);
INSERT INTO door_catalog VALUES('dlcount2','DLCOUNT2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DLCOUNT2.LHA','DlCount2','XIM','DlCount2',NULL,NULL,NULL,'This will be released with BelchMANIA2 It is the more intelligent version of DlCount(1) from BelchMANIA(1)',replace('DlCount2\nThis will be released with BelchMANIA2\nIt is the more intelligent version of\nDlCount(1) from BelchMANIA(1)\n 33.6 This File Passed Thru : DIGITAL-X 33.6\n','\n',char(10)),'3Nodez...)-.TxT','',NULL,'auto-added',45066,3,0,NULL,NULL,'dlcount2','scan',1780048474);
INSERT INTO door_catalog VALUES('dldc41ae','DLDC41AE.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DLDC41AE.LHA','DLDAdd','XIM','DLDAdd',NULL,'Rasmus',NULL,'*    D R E A M L I N E   D E S I G N S    * *             P R E S E N T S             * *        DLDCheck v4.1a Evaluation        *',replace('*******************************************\n*    D R E A M L I N E   D E S I G N S    *\n*             P R E S E N T S             *\n*        DLDCheck v4.1a Evaluation        *\n*        coded by Rasmus K. Ursem         *\n*                                         *\n* This new version is a bugfixed  version *\n*  of v4.1. Registered users of v4.1 can  *\n*    get a free update. (DL and read)     *\n*                                         *\n*                       Rasmus K Ursem/DLD*\n*******************************************\n','\n',char(10)),'DLDCheck41a.guide',replace('@database "DLDCheck.guide"\n@master "DLDCheck.Guide"\n\n@Node Main "DLDCheck documentation."\n                       \n      Dreamline Designs presents DLDCheck V4.1a coded by Rasmus K. Ursem.\n                             Released 29.07.95\n\n    @{" Introduction       " Link "Intro"} What is DLDCheck?\n    @{" THE WAR.           " Link "THEWAR"} Some words about banners, stripping them ect ect.\n    @{" Disclamer          " link "Disclamer"}\n    @{" Copyrights         " link "Copyrights"}\n    @{" Quick installation " link "Quick"} Follow these steps to install DLDCheck. Hints included.\n    @{" Contact address    " link "address"} How to reach the author.\n    @{" StarGate BBS       " link "StarGate"} Dreamline Designs BBS.\n    @{" Dist Sites for DLD " link "SupportBBS"} Dist Sites for DLD prods.\n    @{" Registration       " link "Registration"} How to register.\n    @{" Why register?      " Link "WhyRegister"} What you get when you register.\n    @{" Note To Crackers.  " Link "Crackers"} A little note to crackers.\n    @{" Requirements       " link "Requirements"} Needed system requirements.\n    @{" Greetings          " Link "greetings"} Dreamline Designs greetings.\n    @{" Supporters         " Link "Supporters"} Supporters of DLDCheck.\n    @{" Active Systems     " Link "ActiveSystems"} Systems of registered users, where DLDCheck works.\n\n    Programs in the archive\n    @{" DLDCheck      " link "DLDCheck"} Bannerstripper program.\n    @{" DLDEdit       " link "DLDEdit"} Handle bannerlist program.\n    @{" DLDCheckPrefs " link "DLDCheckPrefs"} Preferences program.\n    @{" DLDAdd        " link "DLDAdd"} Update bannerlist program.\n    @{" DLDConfig     " link "DLDConfig"} Configuration program used with mode C.\n\n@EndNode\n\n@Node "Intro" "Introduction"\n\nWelcome to DLDCheck version 4.1a Evaluation.\nDLDCheck is coded by Rasmus K. Ursem in pure Assembler.\n\nThis is the evaluation version of DLDCheck 4.1a. DLDCheck 4.1a is shareware.\nSee more in the @{"registration" link "Registration"} section.\n\nDLDCheck can be used to remove (and add) BBS advertisments, socalled\nbanners, from lha-archives. DLDCheck can also remove banners from textfiles.\n\nDLDCheck is one of the most configable strippers ever made, this gives \nextremely high flexibilty and efficiency. So high efficiency that once a\nbanner is detected, it will never show up again! (If you set the prefs good.)\nDLDCheck can handle *ANY* bannertype. IFF/Gif/executeables/icons/you name it.\nAll you have to do is detect these special non-ASCII files.\nDLDCheck, especially the registered version is very efficient (98-100%) and\nanother very nice thing is the "Autodelete" in IK, when I strip banners, I''ll\nonly have to delete 1-2 banners myself for every 10 archives, the rest is\nkilled by "autodelete". Until this date (29.07.95) the registered users (10-12)\nhas removed more than 100MB''s of banners since the 01.01.95.\n\n@EndNode\n\n@Node "THEWAR" "The war between adders and strippers."\n\nThey have been there for quite some time, few like them, sysops need them.\nBBS-adds, banners, advertisments are they called, spreading almost like\nan infection, making your archives and your phonebill grow huge.\n\nOver a year ago, a friend of mine used a program called lhacheck or something\nlike that. At that time the wildcards banners was rare and stripping banners\nwas actually only calling LHA with the -i option. Well somebody found out\nthat LHA couldn''t delete files containing wildcards, very quickly the \nsocalled wildcard-banners was added in large amount. The strippers couldn''t\nremove these banners by use of LHA, so routines to seek these wildcard-banners\nwas made, a couple of months passed, and everything went berserk again.\nThe latest was to add random generated banners, so the wildcard-strippers\nwould pass these banners. Strippers now had to check each file for look-alike\nbanners, the socalled intelligent killmodes was born, making it hard for\nrandomgenerated as well as unknown banners to survive. For a moment we \nthought we was safe, but no. Now they add executeables, huge gif/iff pictures\nand icons. New routines has to be coded to remove these new banners, CRC\nchecking is a very efficient way to kill ALL banners, DLDCheck 4.1a support\nthis killmode. The war goes on...\n\nI have tried to see it from the sysops point of view. Banners is necessary\nfor a BBS to survive. The what do we do? Today allmost all archives use the\nfile_id.diz standard, could we create a standard for advertising BBS-systems?\nYes we can, but it need all sysops support. DLDCheck could create a file\ncalled "Seenby.bbs". This file contain a list of BBS the archive has passed\nthrough. Each BBS has 2 lines of text, the first line gives info about \nBBS name, Sysop name, group name, baudrate, phone number and 80 chars of\nyour additional information.\n\nTHE PROBLEM: Convincing all the sysops that we are fed up with their banners\nand make them support this standard of advertisment instead of adding \n10 banners to each archive.\n\nSome of my most crazy kills:\n\nIn an archive with the size of 54kb I removed 52kb of banners. These banners\nwas wildcard, random, executeables, and iff-pictures a total of more than\n20 banners in the archive. \n\nIn an archive with the size of 84kb I found a gif-picture with the unpacked\nsize of 109kb! + a lot of other banners.\n\nIn one archive I have deleted more than 30 banners.\n\n@EndNode\n\n@Node "Disclamer" "Disclamer"\n\nI take no responsibility for datacurruption or deletion of data caused by\nDLDCheck, anyway it''s tested many times and has shown few errors so far.\n\nNOTE: DO NOT ADD THE BANNER NAMED ''*'' THIS IS A WILDCARD AND ALL FILES IN\nARCHIVE WILL BE DELETED!!!!!\n(DLDCheck Version 2.2+ can kill wildcardbanners.)\n\n@EndNode\n\n@Node "Copyrights" "Copyrigths for DLDCheck 4.1a and all the utilities for DLDCheck 4.1a."\n\nDLDCheck is ©copyrighted 1994-95 by Rasmus K. Ursem. All rights reserved.\nPermission is hereby granted to copy DLDCheck 4.1a EVALUATION as long as\nall files stays intact and only a nominal fee (Max 5$) is charged for\ncopy and postage. Permission is also granted to put DLDCheck 4.1a EVALUATION\non PD-libraries such as Fred Fish. But NOT include in Magazine Coverdisk\nwithout my authorization.\n\nDLDCheck 4.1a and all the utilities for DLDCheck 4.1a is shareware. See more\nin the @{"registration" link "Registration"} section.\n\nThis LHA-Archive includes the following files...\n\nDLDCheck\nDLDAdd\nDLDEdit\nDLDCheckPrefs + icon\nDLDConfig + icon\nKillBanners\nKillBanners.addlist\nDLDBrainFile\nDLDCheck.guide + icon.\nFile_ID.Diz\nStoreDir/\nCRCBanners\nMyDLDCheck.Prefs\n(+A lot of trashy bbs adds!)\n\n@EndNode\n\n@Node "address" "Contact address"\n\nYou can reach me at this address\n\n    Rasmus K. Ursem / Dreamline Designs\n    Gudrunsvej 8 3. TH\n    8220 Brabrand\n    D E N M A R K\n\nCall the HOT-line for registerted users: +45 86755547 \nAfter 8/8 use this number for voice:     +45 86755309\n\nor at these NetAddresses:\n\nRasmus K. Ursem:	2:238/29.10 (FidoNet)\nRasmus K. Ursem:	10:2/9.10 (HOANet)\nRasmus K. Ursem:	39:140/109.10 (AmigaNet)		\n\n@EndNode\n\n@Node "StarGate" "StarGate BBS."\n\n                          __,smmW@@@@@@@@@@@@mms__\n                     _,mW@@@@@@@@@@********@@@@@@@@@@ms_\n                  ,m@@@@@@A*¤°~¯         .    ¯~°¤*@@@@@@Ws.\n               ,m@@@@@*¤''                 .          °*M@@@@Ws.\n             gW@@@@*''       .      . .         .        `VM@@@@m.\n           ,W@@@A~               ·                  .      `V@@@@s.\n          W@@@A''    .        .              .                 *@@@@i\n        ,W@@A~          ·           .             .     .      `V@@@s\n       ,@@@A''     .          .        .  .                  .    `@@@b\n       W@@P         .   .       Welcome to the    .  .       .    `@@@i\n      ]@@A                          ·       .                      !@@@\n      W@@'' .oOOo..oOOOOo..oOOo. .oOo.  .oOOo. .oOOo..oOOOOo..oOOOo. Y@@i\n      @@A  O.       OO . O    O O  `O  O''     O ·  O   OO   O''      !@@[\n      @@[  `OOOOo.  OO   OooooO OooO''  O   OO OooooO   OO . OOOO  .  @@[\n      @@[ .      O  OO   O    O O  `O. O ·  O O    O   OO   O       .@@[\n      M@@. `OoooO''  OO   `O  O'' O   `Oo`OooO'' `O  O''   OO   `OoooO'' d@@!\n      ]@@W         .                .                .         .   i@@@\n       M@@b            .     Dreamline Designs BBS       ·   .    ,@@@!\n       `@@@W. Free download on all DLD Productions.(32MB packed) g@@@P\n        `M@@W,       Conference with many developer-tools.     ,g@@@f\n          M@@@w.             Demo-Scene conference.          _g@@@@''\n           °M@@@w_  Call +45 86755547  Hours: 22:00-09:00  ,g@@@@f''\n             °*M@@@m,_   Sysop:   Rasmus K. Ursem/DLD   ,gW@@@@*''\n               ~*@@@@@ms_     28k8/Daydream BBS     _,mW@@@@A*''\n                  ~*@@@@@@Wms,_               __,mm@@@@@@A*''\n                      °*M@@@@@@@@@mmmmmmmmm@@@@@@@@@@*¤°~\n                          ~°¤¤***@@@@@@@@@@@***¤¤¤°~\n\nNOTE: Due to some problems with the danish telecompany we couldn''t get our\nvoice-line until the 8. of august, after this date, Stargate will be online\n24h/day.\n\n@EndNode\n\n@Node "SupportBBS" "Distributions Sites for DLDProductions."\n\nNOTE: Because of some problems with Amigaguide the ASCII-logos might look\na little strage on some systems. (Amigaguide Pre V40)\n\n    @{" Nemesis Amy BBS " Link "BBS_Nemesis"} (Central Jutland)\n    @{" Girl Nation     " Link "BBS_GirlNation"} (Sealand)\n    @{" Cyberdyne       " Link "BBS_Cyberdyne"} (North Jutland)\n\nDreamline Designs is looking for dist sites outside DK. \n(Italy will be covered in the near future.)\n\nYour BBS must at least have these configs.\n\nOpen 24H - 7days/week.\n28k8 modem.\nUSERS!\nNO illegal warez!\n\nInterested? Call me, "snail" me or "e-mail" me.\n\n@EndNode\n\n@Node "BBS_Nemesis" "Nemesis Amy BBS."\n\n                                                        /\\_\n                                                       /  \\\\\n           - -- -- --- --- ---- ------------------- - /    \\\\ - -- -- -\n              __                                      \\_____/\n              \\ \\__/\\  /\\______/\\  /\\  /\\____________/\\___________/\\\n              /  \\   \\/   ____/_ \\/ _\\/   ____/  _____/_____) _____/\n             /    \\   \\  ____/  \\  /  \\  ____/______ \\(_____)____ \\\n            /    \\     \\     \\_  \\/    \\_    \\_       \\_____)      \\_\n            \\__  /\\___________/__||_____/_____/______  /____)_____  /\n               \\/                ::                  \\/    [MORPH]\\/\n                 o FidoNet  2:238/43        o AmigaNet 39:140/116\n                 o C-Link!  912:2000/0      o FooNet   50:450/21\n                 o HoANet   10:2/5          o sUN      119:450/10\n\n                 o FILE_ID.DIZ support      o Free InterNet R/W!\n                 o Nice sysop               o Running CNet/3\n                 o 24 hours all year        o Points accepted\n\n                       DreamLine Designs Distribution Site\n                    Running on an A2000/030 and 640MB harddisk\n                         USRobotics 28800 V.34 DUAL modem\n                              Call - (+45) 7535 3726\n                      ____   _____ ____ ___  ____ _________ ___   __\n            _|_ I___j l__       // i__    _) I__    _)   // ___) [__\n             |      I ___)     //  ___) ___) ___) ___)  // (____ I__)\n                              //                       //\n           - -- -- --- --- ---- ------------------- ---- --- --- -- -- -\n@endNode\n\n@Node "BBS_GirlNation" "Girl Nation."\n\n          _______________ ___       __  ____________________________  ___\n       ../  ___/__/ __  //  /\\     /  \\/  / __  /__   __/__/     /  \\/  /\\\n     .../  /  /  /    _//  /_/_   /      / __  /\\_/  / /  /  /  /      / /\n  ...../_____/__/__/\\_\\/______/\\ /__/\\__/_/ /_/ //__/ /__/_____/__/\\__/ /\n ......\\_____\\__\\__\\_\\_\\______\\/ \\__\\/\\_\\_\\/\\_\\/ \\__\\/\\__\\_____\\__\\/\\_\\/\n                            -=- Amiga BBS -=-\n                       ___ ___ ___  ___  ____\n                ../  /   /   /   /    / /   / /  / /  /\n        +45   .../__/ __/ __/ __/  __/ / / / /__/ /__/\n                .../ /   /   /      / / / /    /    /\n               .../ /__ /__ /__ ___/ /___/    /    /\n\n    -=- SysOp:  Dennis Franck -=- SemiSysOp:  Toke Godiksen -=-\n          -=- DLGPro BB/OS, A4040, 600 MB HD online -=-\n\n@endNode\n\n@Node "BBS_Cyberdyne" "Cyberdyne."\n\n                          ___                           ___\n                _________/  /\\__  __________  ____  ___/  /\\__  ______\n               / ____/  /  /___ \\/ ____/___ \\/___ \\/  /  /___ \\/ ____/\\\n              /  /\\_/  /  /  /  /  _/\\/   __/  /  /  /  /  /  /  _/\\_\\/\n             /  /  /___  /     /  /  /     /  /  /___  /  /  /  /  /\\\n            /  /  /  /  /  /  /  /  /  /  /  /  /  /  /  /  /  /  / /\n           /  /  /  /  /  /  /  /  /  /  /  /  /  /  /  /  /  /  / /\n          /___  /_____/_____/___  /__/  /_____/_____/__/  /___  / /\n          \\_/__/\\_____\\_____\\_/__/\\_/__/\\_____\\_____\\_/__/\\_/__/ /\n            \\__\\/             \\__\\/ \\__\\/             \\__\\/ \\__\\/[n$]\n  \n  \n                                Sysop: Kim B.\n                             Phone: +45-98434851\n  \n          Hardware: 030/33Mhz, 882/50Mhz, 28k8 USR, 1.5Gb HD space\n\n@endNode\n\n@Node "Quick" "Quick install of DLDCheck 4.1a."\n\n1. Unpack this archive to a directory.\n\n2. Assign DLDChecker: to the directory.\n\n3. Make sure you have reqtools.library and FileID.library in LIBS:\n\n4. Make sure you have LHA in your path.\n\n5. Make sure you have Copy in C:\n\n6. Optional: Move DLDCheck.prefs to ENVARC: and ENV: Only if you want to use\n             my prefs.\n\n7. Run the DLDCheckPrefs program and set/change the settings according to\n   your needs.\n   NOTE: The section in DLDCheckPrefs about the gadgets functions might be\n   a good idea to read. :)\n\n8. Optional: If you are using DOpus. Setup some gadgets. Examples can be\n             found under the sections for each of the programs.\n\nSome Hints/Good ideas:\n\n-Every time you find a banner which is an icon/iff/gif/executeable or any\n other non-ascii/ansi use DLDAdd with the CRC option. This will get rid of\n them (if you use Intelligent Killmode and CRC-Checking with autodelete.)\n You can also use CRC on ASCII/Ansi, but don''t use on banners which has\n a line or two at the bottom with text in this style.\n\n This file was uploaded by: BlankMan/The Blank Crew     date: 40-40-40\n\n Because CRC checking is dependant on the CRC in the archive and this changes\n if the contents of the file change. Instead add some high-probality words\n and use IKs "Del files above" to autodelete the files.\n\n-If the main kill or Intelligent Killmode cannot delete/unpack a file it \n is probably because the filename contains some kind of illegal chars.\n I have noticed that LHA uses special non-standard wildcards for some \n internal stuff. (e.g. $$)\n\n-Special Words MUST start with a letter or a number because the ASCII-\n checker will take all other ASCII-chars as "Banner-chars".\n\n-Special words which is allmost alike is not wise. The best way of explaining\n this is with an example. The following is a list of medium-probability words.\n\n ...\n Sysop\n Sysop: TheSysop\n ...\n\n DLDCheck will only find "Sysop" and leave out the rest, simply because it\n find "Sysop" before "Sysop: TheSysop". Instead you should do like this.\n\n ...\n Sysop\n TheSysop\n ...\n\nThe ":" and the " " will be handled anyway.\n\n\n\n-Be very careful with these options/settings.\n\n   -CompareKill/Use normal compare.\n   -Intelligent/SpecialWords/Kill high, skip low.\n   -If You not use Intelligent/"Check filetype fast" DLDCheck might start\n    checking misc files. Icons have somehow a very high percentage.\n\n@EndNode\n\n@Node "Registration" "How to register DLDCheck 4.1a."\n\nYou can register DLDCheck 4.1a by sending 100dkr/20US$/10GB£ + 1disk \n1 addressed envelope to my @{"address" link "address"}.\n\nWe can also transfer DLDCheck with a modem.\n\nA third way of registering DLDCheck is call me at 86755547, I''ll then give\nyou the number to my bankaccount, you will give me your address and deposit\n100 dkr. As soon as I see the income on my bankaccount I will transfer/mail\nyou the registered version. (I don''t know if this works outside DK.)\n\nNOTE: For registered users the fee is only 50dkr/10$/5£.\n\nPlease answer these questions!\n\n1. What Amiga do you have?\n2. What OS are you using?\n3. How many MB HD do you have?\n4. Other external devices such as diskdrives, tapestreamers, cdrom ect?\n5. Are you using DLDCheck with a BBS-system as a sysop? Which?\n6. What version of LHA are you using?\n7. What version of DLDCheck was the first you used?\n8. How many days did you use the evaluation version?\n9. Have you discovered any bugs that has NOT been fixed?\n10.How many MB of banners have you removed?\n11.Why do you use DLDCheck instead of other strippers?\n12.Are you a member of a "scenegroup"? Which?\n13.Your address.\n14.What do you connect Dreamline Designs with? Have you heard of Dreamline\n   Designs before?\n\nReasons to ask the questions.\n1-4.  To see how many different configurations DLDCheck is working under.\n5.    To see how many BBS-systems DLDCheck is running under. Please write\n      if your board is working in a net or just a single machine.\n6.    To make a list of LHAs DLDCheck will work with.\n7.    To see when you first used DLDCheck, which killmodes that made you\n      choose DLDCheck.\n8.    To see how many days users use an evaluation version before they \n      register.\n9.    So I can fix them. Please write version. You can also give bugreports\n      to the utilities.\n10.   I will make a counter for ALL registerted users. Global Kill!\n11.   Write which killmodes you prefer. \n12.   To see if the "Scenedudes" use this utility.\n13.   So I can contact you.\n14.   A kind of "Market Analyze".\n\nWrite if you DON''T want to be on the @{"registerted" link "Registerted"} users list.\nWrite if you want other utilities from Dreamline Designs.\n\n@EndNode\n\n@Node "WhyRegister" "Why to register DLDCheck 4.1a"\n\nThis is what you get when you register DLDCheck.\n\n * Access to the Hot-Line. (+45 86755547)\n * Non-crippled version of DLDCheck.\n * Other free utils from Dreamline Designs if you want them.\n * Access to the User-conference on Stargate. This conf is for registered \n   users only and holds some inside info and beta-releases.\n\n DLDCheck is crippled in these options.\n\n Maintenance option:\n  When the maintenance option dosn''t find any banners, DLDCheck will skip\n  the mainkill because this is checking the archive twice and getting the\n  same result.\n  NOTE: This dosn''t work in the evaluation version.\n\n Intelligent Killmode:\n -Added/Improved: 3 Types of words. Used to determine a textfiles\n  probability of being a banner. See more information in the DLDCheckPrefs\n  @{"intelligent" link "DLDCheckPrefs_Intelligent"} section.\n  NOTE: Crippled in evaluation version.\n -Added: Fast filetype check.\n  NOTE: Not optimized in evaluation version.\n -Added: Average wordlength checking. (Banners usually have very low\n  lix-value.)\n  NOTE: Not optimized in evaluation version.\n -Added: Check in subdirs. \n  NOTE: Not available in evaluation version.\n -Added: Adding subdir-banner-names to killbanners and killbanners.addlist.\n  NOTE: Not available in evaluation version.\n -Added: CRC checking, this is a very efficient way to kill ANY add \n  including IFF/GIF/Icons/executeable/you name it.\n  The routine is based on the socalled CRC. This is a checksum LHA\n  uses to check the files. If DLDCheck finds a file which matches the\n  filesize and CRC it can be autodeleted. This is very fast.\n  NOTE: Limited in the evaluation version.\n\n Compare Killmode:\n -Added: Compare killmode can sort extensions. In DLDCheckPrefs you can set\n  extensions which this killmode will NOT delete.\n  NOTE: Limited in evaluation version to a maximum of 4.\n\n@EndNode\n\n@Node "Crackers" "A little note to crackers."\n\n Some lamebrain tried to crack DLDCheck 4.0, however he did not succeed \nbecause it can''t be done. And why? Simply because the code in the\nregistered version does NOT exist in the evaluation version. So don''t try\nto do it, it''s a waste of time. If you find a cracked version don''t bother\ndownloading it, because it''s a fake!\n\nFurthermore all registered versions of DLDCheck has x special encrypted\nserial numbers build in. So if an illegal version is circulating, I''ll \nknow who spread it!\n\n(Comparing 2 registered versions will not help you because the positions\nare different from version to version.)\n\n@EndNode\n\n@Node "ActiveSystems" "Systems where DLDCheck is working."\n\n Note: This is only registered users.\n\n -A1200 with KS3.0, 214MB HD and lha 1.5x\n -A1200 with KS3.0, 540MB HD and lha 1.50\n -A4040 with KS3.0, 120MB HD, CDRom, Syquest 270SCSI and lha 1.52\n -A3000T with KS3.1, 856MB HD, CDRom, Tapestreamer and lha 1.50\n  This machine is running BBS-system "Blizzard".\n -A4040 with KS3.1, 1500MB HD, Tapestreamer and lha 1.50.\n -Amiga3000/030 KS3.1\n -Amiga4030 KS3.1\n -A500T with KS2.1, 380MB HD and lha 1.52.\n -A2030 with KS2.1 Tapestreamer, mc68030/40mhz.\n  Nemesis Amy BBS running CNet 3.05\n -A2030 with KS2.04 G-FORCE 030/33Mhz, 882/50Mhz, GVP IO Extension.\n  Cyberdyne BBS running Cnet 3.05\n -A4040 Warp with KS 3.0, 3GB HD, 7 disk CD-Rom.\n  Digital Candy BBS.\n -A1200 with KS3.0, 1263 MB HD.\n\n@Endnode\n\n@Node "Requirements" "System requirements for DLDCheck and DLDCheck Utilities."\n\n -AmigaOS V37+ (Workbench 2.04+)\n -Reqtools.library\n -FileID.library v2.0+ \n -LHA v1.40+ (I don''t know those old versions of LHA, maybe old versions \n  will work.)\n\n@EndNode\n\n\n@NODE "Greetings" "The official greetinglist."\n\n        Dreamline Designs greets these groups''n''gurus...\n\n        TechVision\n	Spoon\n	Polka Brothers\n	The Flame Arrows\n	Static Bytes\n	Kingdom\n	Upfront\n        Ram Jam\n\n	Michael ''Fix'' Sølvstad          Dennis Franck\n	Kaare ''Swyx'' Heinsen            Toke Godiksen\n	Jan Green                       Kim Borbjerggård\n	Jens Andersen\n	Jesper Juul\n	Warner/Creed\n        Dr G/Ram Jam\n	Morten K Andersen\n        Peter Frandsen\n        Erik Børsting\n\n	And finally - Commodore USED2B Inc. and Amiga Technologies.\n	 cause ''Only Amiga Makes It Possible!''\n\n@ENDNODE\n\n@Node "Supporters" "The official supporters for DLDCheck."\n\n   The following people supports DLDCheck with new banners, new ideas and\n   bugreports.\n\n  -Jesper Rou Larsen. Thanks for the Bugreports, ideas and banners.\n\n  -Karsten Niemeier. Thanks for new ideas.\n\n  -Warner of Creed. Thanks for the bugreport and your killbanners list.\n\n  -Klaus Jensen. Thanks for new ideas to DLDCheck 3.0.\n\n  -Kim Sindalsen. Thanks for the bugreport and new ideas.\n\n  -Peter F. Frandsen Thanks for bugreports and being my link to InterNet.\n\n  -Morten K. Andersen. Thanks for the arexx scripts.\n\n  -Erik Børsting. Thanks for running support-site for DLD.\n\n  -Kim Borbjerggård. Thanks for the ideas to v5.0, bugreports to v4.1 and\n   for runnning support-site for DLD.\n\n  -Dennis Franck & Toke Godiksen. Thanks for running support-site for DLD.\n\n  -Fabio Vitale. Thanks for the long letters, the ideas and "soon-to-be"-\n   support-site in Italy.\n\n  -All the people who reported "fixed" bugs. Thanks for your support.\n\n    Wanna be on this list? Contact me with bugreports, ideas, bannerslists!\n\n@EndNode\n\n******** Nodes for DLDCheck *****\n\n@Node "DLDCheck" "DLDCheck 4.1a main menu."\n\n  DLDCheck 4.1a main menu.\n\n    @{" History          " Link "DLDCheck_History"} History for DLDCheck 4.1a.\n    @{" How to install   " Link "DLDCheck_HowToInstall"} How to install DLDCheck.\n    @{" How to Use       " Link "DLDCheck_HowToUse"} How to use DLDCheck.\n    @{" Output example   " Link "DLDCheck_Example"} Output example with explanation.\n    @{" Using with DOpus " Link "DLDCheck_UsingWithDOpus"} How to set you buttons in Opus.\n    @{" Future plans     " Link "DLDCheck_FuturePlans"} Future plans for DLDCheck.\n    @{" Datafiles        " Link "DLDCheck_DataFiles"} DLDChecks relations to the datafiles.\n\n@Endnode\n\n@Node "DLDCheck_History" "History for DLDCheck."\n\nV1.0  -First workable version, but had some minor bugs. Couldn''t load\n      files with spaces. Released at The Party III\n\nV1.01 -Bug Fix: Could load files with spaces. Also released at The Party\n       III\n\nV1.1  -DLDCheck now uses ReadArgs() from the dos.library instead of just\n      getting it from the CLI. ReadArgs() is more systemfriendly and\n      DLDCheck will therefore be forward compatible.\n      -Bug Fix: DLDCheck could misundestand a ''-'' in the filename as a\n      option. This is also removed by using ReadArgs. (Thanks goes to Zest/\n      Triangle 3532 for telling me how to use ReadArgs.)\n      -Removed the ? option and included amigaguide instructions instead.\n      -Added LHA option -Qo and -Qw. Added because some bannernames \n      includes ''-'' and other wierd characters LHA could misundestand as \n      user-selected options, unfortunately LHA has a bug so -Qw dosn''t\n      work. (Don''t add the ''*''-banner in the KillBanners list, because\n      this will delete all files in the archive!!!!)\n      -Added a utility to put a new banner in the list. I coded this \n      small utility because I didn''t wanted to load an editor every time\n      I found a new banner. (I find a lot! :-l )\n\nV1.2  -Some minor options added, but this version was never released to\n      public because I decided to add a lot new stuff and rearrange the \n      template.\n\nV2.0  -Added Todays Killsize and total killsize so you can see how many\n      bytes of banners you have removed with DLDCheck.\n      -Added PROT option to ignore Protection flag.\n      -Possibility to add a banner with DLDCheck.\n      -New structure for the template, Sorry guys...\n      This Version is not released to public.\n\nV2.1  -Added S=SAFE option. Purpose to insure survival of your precious\n      HD. The reason is yet another bug in LHA, sometimes the Amiga\n      crashed while packing data, and thereby using the HD for saving.\n      The result: A Currupted HD and hours of repairwork.\n      -Bugfix: During MODE Show, DLDCheck didn''t show anything if the\n      file T:KilledToDay was not present.\n\nV2.2  -Bugfix and repairwork on the Safemode option. DLDCheck now ask\n      "skip safemode or quit" if the archive cannot be copied to mem.\n      -Added Wildcard kill. Filenames with the following letters will be\n      deleted: * # ? ~ |. This will not happen if the archive is to big.\n      I will maybe make this with buffers later. \n      -Removed LHAs "-Qw" option because it dosn''t work anyway.\n\nV2.3  -Added CompareKillmode. This new killmode stores the archivename\n      and kills any name in archive that looks like it. Files to be\n      deleted by this option is "Filename.#?" Option added because\n      some guys have started to add banners with almost the same name\n      as the archive.\n      Note: You should only use this option with care.\n      -Bugfix and repair work on the safemode option.\n\nV2.4  -Added Intelligent killmode(IK). Since some guys get wiser and wiser\n      to avoid getting their banners killed, (Such as generating random-\n      names.) I added this routine.  \n      -In connection with the IK I added an auto DLDAdd. In other words.\n      If IK finds a banner it will automatically add the name to\n      DLDChecker:Killbanners. Why? Because IK is slow compared to deleting\n      from a filelist.\n      -Added some banners to the list from a file called "2BAD.NFO". \n      This file was somebody''s killbanners list, released to public.\n      This version of the Killbanners file is roughly sorted so you easy \n      can insert you own banners.\n      -Added a printline when using the Safe option, so you can see what\n      archive you are processing.\n      -Added some new chars to the Wildcard kill routine.\n\nV2.5  -Bugfix: Using safemode an errors occured during the use of "Copy"\n      DLDCheck would delete the archive. Thanks goes to *Warner of Creed*.\n      -Bugfix: Using safemode and the wildcard option DLDCheck would crash \n      on some large archives.\n      -Added an option in the intelligent killmode so you can remove the\n      banner from the archive without adding it to the "Killbanners".\n      -Added a lot of banners to the KillBanners list. Thanks goes to\n      Warner of Creed.\n\nV3.0  -Bugfix: IK would crash if files with filesize=0 occured.\n      -Repairwork: IKs checkroutine had some minor bugs, now fixed.\n      -Added: BrainFile. Yes, DLDCheck can learn words to check in IK.\n      The brainfile is also used in connection with the new killmode.\n      -Added: New KillMode to remove banners from textfiles.  Artificial\n      Intelligence (AI) is used to learn the ways of the user.\n      In other words DLDCheck will learn how YOU use DLDCheck, and then\n      use this.\n      -Added: DLDEdit, a small utility to delete doublelines and \n      wildcard filenames in a SORTED Killbanners file. (Sort with CygnusEd)\n      -Added: New chars to wildcardkill. Now deletes files with these chars:\n      *#?><|»«©®~^¶ª×¿   (This method is faster than LHA.)\n      -Expanded: The Show option now shows the LHA-archive killsize,\n      text killsize and the words in memory.\n      -Added: A lot of banners from different files. KillBanners is now\n      more than 25Kb.\n\nV3.1  -Bugfix: Major problems in brainfile.\n      -Bugfix: DLDCheck Could set the delete point before the file starts\n      or after End Of File. Now fixed.\n      -Bugfix: IK would crash if files with filesize=0 occured. Wasn''t\n      repaired well in 3.0.\n      -Repairwork: The checkline routine would, until now, take spaces\n      for ASCIILogochars. Spaces are now total out of the evaluation\n      process.\n      -Repairwork: When changing the front delete position You had to wait \n      for a total print of the start of the file. Now DLDCheck prints the\n      last 12 lines before and after the delete position.\n      -Expanded: Show option expanded and readout of remembered words \n      changed a little bit.\n      -Added: Using Textkillmode. The checkline routine would take a total\n      line of ---- or ==== as an ASCIILogocharline. These lines are now\n      total out of the  evaluation process. An AI sort-method will try to\n      determine these lines as underlines or just a good-for-nothing\n      partline.\n      -Added: Using Textkillmode. A line to tell you where DLDCheck will\n      delete. Reason: ANSI readout would fuck up the show mode in \n      DLDCheck 3.0.\n      -Added: DLDCheck now print the file being processed during textmode.\n      -Added: Using IKA. "Train" and "Quit" added. "Train" will train the \n      BrainFile. "Quit" will quit the IKA instead of just cancel the\n      file being processed.\n      -Added: Using IKA. After viewing a file containing colorchanges\n      DLDCheck now resets the printcolor.\n      -Added: Using IKA. Spaces, Tabs and CRs are now out of the evaluation\n      process.\n      -Info: Sourcesize 92103 bytes, 5877 lines of code.\n\nV4.0  -Added: New option called maintenance. This option is used to update\n       the killbannerslist. Each name in the list will get a number which\n       is the last time this banner was deleted from an archive. The reason\n       is the extreme large killbannerslist, this takes very long time to \n       load. You can set the amount of accesses before removal in the \n       DLDCheckPrefs program. See the @{"DLDCheckPrefs" link "DLDCheckPrefs_Maintenance"} section.\n       DLDCheck is not used to remove names from the list because this \n       takes long time. This is done by DLDEdit. See the @{"How to Use" link "DLDEdit_HowToUse"}\n       section.\n       When the maintenance option dosn''t find any banners, DLDCheck will\n       skip the mainkill because this is checking the archive twice and\n       getting the same result. NOTE: This dosn''t work in the evaluation\n       version.\n      -Added: New Mode Configure. This new mode can take a configuration\n       file generated by @{"DLDConfig" link "DLDConfig"} and use this as a template.\n       The goal is to avoid entering long templates in the shell. Instead\n       just enter the saved configfile and DLDCheck will read arguments\n       from this file.\n      -Added/Improved: The show mode is expanded with a lot of counters,\n       accesses ect ect. This is output is determined by the prefs.\n      -Changed: Keep option. You can set you own filecomment. See the\n       DLDCheckPrefs @{"Keep" link "DLDCheckPrefs_Keep"} section.\n\n      -Intelligent Killmode:\n	-Bugfix: IK mode crashed if LHA failed when extracting files from\n	 archive. No fixed.\n	-Bugfix: IK mode found wierd banners. Now fixed.\n	-Bugfix: The ASCII-Checker had minor bugs. Now fixed.\n	-Added: DLDCheck tells if anything goes wrong.\n	-Added/Improved: 3 Types of words. Used to determine a textfiles\n	 probability of being a banner. See more information in the\n	 DLDCheckPrefs @{"intelligent" link "DLDCheckPrefs_Intelligent"} section.\n	 NOTE: Crippled in evaluation version.\n	-Added: Check filetype with FileID.library.\n	-Added: Fast filetype check.\n	 NOTE: Not optimized in evaluation version.\n	-Added: Average wordlength checking. (Banners usually have very\n	 low lix-value.)\n	 NOTE: Not optimized in evaluation version.\n	-Added: Ratio checking. (Banners usually have high packing ratio.)\n	-Added: You can set a lot of limits in the prefsfile. See more\n	 information in the DLDCheckPrefs @{"intelligent" link "DLDCheckPrefs_intelligent"} section.\n	-Added: Autodelete option. DLDCheck can automatically delete files\n	 above a certain percentage.\n	-Added: Count found banners. DLDCheck can count banners so you can\n	 see how many banners IK has found/removed/killed/autodeleted.\n	-Added: Check in subdirs. \n	 NOTE: Not available in evaluation version.\n	-Added: Adding subdir-banner-names to killbanners and\n	 killbanners.addlist.\n	 NOTE: Not available in evaluation version.\n      -Compare Killmode:\n	-Improved/Changed: The whole Compare Killmode is rewritten. Now\n	 this killmode handle each file like Intelligent Killmode. Not\n	 just deleting all files called <archivename>.#?\n	-Added: Compare killmode can sort extensions. In DLDCheckPrefs you can \n	 set extensions which this killmode will NOT delete.\n	 NOTE: Limited in evaluation version to a maximum of 4.\n	-Added: Option to delete reversed archivenames.\n      -Wildcard killmode:\n	-Changed: You can set the wildcards to search for.\n      -Info: Sourcesize 125465 bytes, 8153 lines of code.\n\nV4.1  -Bugfix: DLDCheck would skip the updating of date/comment/killsizes\n       if anything went wrong, now fixed.\n      -Improved: Mode c can be enabled by leaving out the "mode" argument \n       in the commandline.\n      -Overall Changes.\n        -Added: Color output, all important results will be in white. (If you\n         want it.)\n        -Added: To all calls to LHA is now added the -m option. This will \n         prevent DLDCheck from hanging if LHA asks questions.\n\n      -Safe option.\n        -Added: AutoSkip or AutoQuit in low memory situations.\n      -Add and AddT Options.\n        -Added: Display the Killsize for this archive.\n        -Added: Save the Killsize for this archive in T: Could be used in \n         connection with BBS if the users should not get uploadcredits for\n         uploading banners. See more info in the DLDCheckPrefs section.\n      -Wilcard killmode:\n        -Improved: Now DLDCheck can use a string as wildcard. E.g. "$$"\n         Reason: LHA cannot delete files with these double wildcards.\n        -Bugfix: Wildcard would delete the file if the comment contained a\n         wildcard. Now Fixed.\n      -Compare killmode:\n        -Totally rewritten. (It had some hard bugs.)\n        -Added: You can now skip the normal compare and only kill reversed\n         archive-names. (Set this in the DLDCheckPrefs/Compare window.)\n	 NOTE: Limited in evaluation version to a maximum of 4.\n      -Intelligent killmode:\n        -Global change: 5 of the check methods can affect the final\n         percentage displayed after IK found a new banner. In V4.0 a negative\n         check would cause DLDCheck to skip the file. See more info in the \n         prefs section.\n        -Bugfix: Removed a couple of possible Division by Zeros. Ops!\n        -Added: CRC checking, this is a very efficient way to kill ANY add \n         including IFF/GIF/Icons/executeable/you name it.\n         The routine is based on the socalled CRC. This is a checksum LHA\n         uses to check the files. If DLDCheck finds a file which matches the\n         filesize and CRC it can be autodeleted. This is very fast.\n         NOTE: Limited in the evaluation version.\n        -Added: Number of lines checking. Banners usually have few linefeeds.\n        -Added: Text output. Now you can see the results of the checks.\n        -Added: Store new banners. You can set DLDCheck to store new banners.\n         Every time you select CRC-Delete, Kill or Remove DLDCheck will store\n         the banner in DLDChecker:StoreDir.\n        -Improved: Special word check. You can set DLDCheck to autodelete\n         the file if the file contains a High probablity-word and skip if\n         it contains a low probabity-word. If DLDCheck find both you can\n         set it to Proceed as nothing happed, kill the file or skip the file.\n         You can also set the maximum number of words to check for.\n        -Changed: Now you can view a file unlimited times.\n        -Bugfix: The mainchecking had some minor bugs.\n      -Info: Sourcesize 149106 bytes, 9642 lines of code.\n\nV4.1a   -Bugfix: The "Check filetype fast" couldn''t handle files lower than\n         100 bytes causing DLDCheck to skip the file.\n        -Bugfix: The use of FileID.library was broken. This caused DLDCheck to\n         "pop" a lot of wierd files.\n        -Improvement/Bugfix: If $0E appeared when viewing banners in IK-mode, the\n         printed chars would have the highbit set causing them to be unreadable.\n        -Fixed a couple of Enforcer-hits. (Try DLDCheck mode Show in your old\n         version, UPS!)\n        -Fixed a couple of minor bugs in the handling of the arguments.\n        -Fixed a bug in the IK, special words beginning with a number wasn''t \n         treated as special words.\n        -info: Sourcesize 151544 bytes, 9806 lines of code.\n\n@EndNode\n\n@Node "DLDCheck_HowToInstall" "How to install DLDCheck 4.1a"\n\nHow To install DLDCheck\n\n-Assign any directory as "DLDChecker:"\n-Copy the file called "KillBanners" to DLDChecker:\n-Copy the file called "DLDBrainFile" to DLDChecker:\n-Copy the file called "KillBanners.addlist" to DLDChecker:\n-Copy DLDCheck to any directory. (Eg C: )\n-Make sure the program "LHA" is in an AmigaDos pathed directory.\n-If you use the S=SAFE option be sure Copy is in C:\n-If you use "Store new banners" in IK this directory must exist. "DLDChecker:StoreDir"\n\n@Endnode\n\n@Node "DLDCheck_HowToUse" "How to use DLDCheck 4.1a"\n\n  How to use DLDCheck 4.1a''s modes.\n\n  @{" Delete " link "DLDCheckPrefs_HowToUse_Delete"}\n  @{" Add    " link "DLDCheckPrefs_HowToUse_Add"}\n  @{" Show   " link "DLDCheckPrefs_HowToUse_Show"}\n  @{" Text   " link "DLDCheckPrefs_HowToUse_Text"}\n  @{" Config " link "DLDCheckPrefs_HowToUse_Config"}\n\n@EndNode\n\n@Node "DLDCheckPrefs_HowToUse_Delete" "The Delete mode."\n\n Usage:\nDLDCheck M=MODE/A,D=DATE/S,K=KEEP/S,P=PROT/S,A=ADD/S,AT=ADDT/S,S=SAFE/S,\nW=WILD/S,C=COMPARE/S,MAIN=MAINTENANCE/S,IKA=IKILLASK/S,IKF=IKILLFORCE/S,\nN=NAME/K,F=ADDFILE/K,CON=CONFIGFILE/K\n\n\n MODE = D\n      D will delete banners from the list DLDChecker:Killbanners in the\n      archive specified in N=NAME/K.\n\n Available options in the Delete mode.\n\nDATE: LHA set the Archive date to your systems current date. If you use\n      the DATE-Swhich DLDCheck will NOT redate the filedate to the old\n      date.\n      Default: Redate.\n\nKEEP: Keep filecomment always. DLDCheck sets a filecomment, but ONLY if the\n      current filecomment is empty. KEEP will make sure DLDCheck NEVER\n      overwrites filecomment.\n      Default: Writes comment if and only if there is no comment.\n\nPROT: Deactivates the "ignore protection" option in LHA.\n      Default: Ignore protectionbit.\n\nADD:  Add to todays killsize. This is a small file stored in T: usually\n      in ram: this will speed up for floppyusers.\n      Default: Not adding.\n\nADDT: Add to the total killsize. This is a small file stored in\n      DLDChecker: This option is mainly for HD-users.\n      Default: Not adding.\n\nSAFE: Safe option. This option copies the archive to ram: and works\n      from there. If LHA crashes no HD need repair. At last DLDCheck\n      copies the archive back to the original place. This option is\n      just a precaution agains another LHA-Bug.\n      Default: No safe.\n\nWILD: Kill wildcard files. This option can remove files which can''t\n      be removed with LHA. This may take some time, because the archive\n      must be loaded into Memory before it can be processed.\n      There are 3 returnlines from this option.\n	-Done!       which indicates that there WAS wildcardfiles.\n	-No WildCard files in Archive!\n	-Not enough memory free!\n      Default: No Wildcard Killing.\n\nCOMPARE:\n      Will delete files in archive with names semilar to the archive-\n      name. e.g. Archive name is Test.lha. All files in Test.lha that\n      fits the following pattern (Test.#? will be deleted. You can \n      specify special extensions like .info/.dms/.s ect ect. Files \n      with these extensions will not be deleted.\n      Default: No CompareKill.\n\nIKA:  Intelligent Killmode with Ask option before deleting.\n\nIKF:  Intelligent Killmode with Force option. BE CAREFUL!\n\n      The IK works this way: With LHA DLDCheck generates a FileList of\n      the archive. From this list DLDCheck extracts all those files\n      that looks interesting. (No, I won''t tell you the Sort method!)\n      When a file is extracted it will be examined for chars used\n      often in connection with Banners, and words in connection with\n      BBS''s. If IK finds a banner it will, depending on the selected\n      mode (IKA or IKF), ask, and then delete the file from the archive.\n      Finally IK will add the bannername to DLDChecker:KillBanners.\n      (Type r to remove banner without adding the name to the list.)\n\nNAME: The name of the LHA-Archive to kill banners in.\n\n\nMany special settings can be set with @{"DLDCheckPrefs" link "DLDCheckPrefs"}.\n\n@EndNode\n\n@Node "DLDCheckPrefs_HowToUse_Add" "The Add mode."\n\n Usage:\nDLDCheck M=MODE/A,D=DATE/S,K=KEEP/S,P=PROT/S,A=ADD/S,AT=ADDT/S,S=SAFE/S,\nW=WILD/S,C=COMPARE/S,MAIN=MAINTENANCE/S,IKA=IKILLASK/S,IKF=IKILLFORCE/S,\nN=NAME/K,F=ADDFILE/K,CON=CONFIGFILE/K\n\n MODE = A\n      A will add the banner specified in F=ADDFILE/K to the archive\n      specified in N=NAME/K.\n\n Available options in the Add mode.\n\nDATE: LHA set the Archive date to your systems current date. If you use\n      the DATE-Swhich DLDCheck will NOT redate the filedate to the old\n      date.\n      Default: Redate.\n\nSAFE: Safe option. This option copies the archive to ram: and works\n      from there. If LHA crashes no HD need repair. At last DLDCheck\n      copies the archive back to the original place. This option is\n      just a precaution agains another LHA-Bug.\n      Default: No safe.\n\nNAME: The name of the LHA-Archive to kill banners in.\n\nADDFILE: The name of the banner to add.\n\n@EndNode\n\n@Node "DLDCheckPrefs_HowToUse_Show" "The show mode."\n\n Usage:\nDLDCheck M=MODE/A,D=DATE/S,K=KEEP/S,P=PROT/S,A=ADD/S,AT=ADDT/S,S=SAFE/S,\nW=WILD/S,C=COMPARE/S,MAIN=MAINTENANCE/S,IKA=IKILLASK/S,IKF=IKILLFORCE/S,\nN=NAME/K,F=ADDFILE/K,CON=CONFIGFILE/K\n\n MODE = S\n      S shows a lot of information about DLDChecks killsizes, words and\n      other settings.\n\n No options available.\n\n@EndNode\n\n@Node "DLDCheckPrefs_HowToUse_Text" "The text mode."\n\n Usage:\nDLDCheck M=MODE/A,D=DATE/S,K=KEEP/S,P=PROT/S,A=ADD/S,AT=ADDT/S,S=SAFE/S,\nW=WILD/S,C=COMPARE/S,MAIN=MAINTENANCE/S,IKA=IKILLASK/S,IKF=IKILLFORCE/S,\nN=NAME/K,F=ADDFILE/K,CON=CONFIGFILE/K\n\n MODE = T\n      T Enables the intelligent textkillmode.\n\n Available options in the text mode.\n \nADD:  Add to todays killsize. This is a small file stored in T: usually\n      in ram: this will speed up for floppyusers.\n      Default: Not adding.\n\nADDT: Add to the total killsize. This is a small file stored in\n      DLDChecker: This option is mainly for HD-users.\n      Default: Not adding.\n\nNAME: The name of the textfile.\n\n This mode is used to remove banners from textfiles. It calculates a\n beginning and end of the original textfile, these marks can be changed \n by the user. The output file is the text between these marks.\n\n@EndNode\n\n@Node "DLDCheckPrefs_HowToUse_Config" "The configuration mode."\n\n Usage:\nDLDCheck M=MODE/A,D=DATE/S,K=KEEP/S,P=PROT/S,A=ADD/S,AT=ADDT/S,S=SAFE/S,\nW=WILD/S,C=COMPARE/S,MAIN=MAINTENANCE/S,IKA=IKILLASK/S,IKF=IKILLFORCE/S,\nN=NAME/K,F=ADDFILE/K,CON=CONFIGFILE/K\n\n MODE = C\n      C Enables the configuration mode. If you don''t enter any mode Mode C\n      will be enabled.\n\n Available options in the configuration mode.\n\nNAME: The name of the file to process.\n\nADDFILE:\n      The file to add using Addmode. This argument will be ignored when\n      other modes are used.\n\nCONFIGFILE:\n      Name of the configuration file.\n\n This mode can take a configuration file generated with @{"DLDConfig" link "DLDConfig"}\n and use it as a template. This should ease the use of DLDCheck.\n\n@Endnode \n\n@Node "DLDCheck_UsingWithDOpus" "Using DLDCheck with DirectoryOpus."\n\nI use 3 buttons and they are configured as follows\n\nThe killing button.\nName:  DLDCheck\nThe entry is: AmigaDOS    DLDChecker:DLDCheck MODE D KEEP SAFE WILD MAIN ADDT ADD IKA Name {f}\nFollowing flags are used:\n	-CD source\n	-Directory Opus to front\n	-Do all files\n	-Output window\nStack Size:   4000\nPriority:     0\nClose Delay:  -1\n\nThe showing button.\nName:  DLDShow\nThe entry is: AmigaDOS    DLDChecker:DLDCheck MODE S\nFollowing flags are used:\n	-Directory Opus to front\n	-No filename quote\n	-Output window\nStack Size:   4000\nPriority:     0\nClose Delay:  -1\n\nThe Textkilling button.\nName:  DLDCheckT\nThe entry is: AmigaDOS    DLDChecker:DLDCheck MODE T ADDT ADD Name {f}\nFollowing flags are used:\n	-CD source\n	-Directory Opus to front\n	-Do all files\n	-Output window\nStack Size:   4000\nPriority:     0\nClose Delay:  -1\n\n@EndNode\n\n@Node "DLDCheck_FuturePlans" "Future plans for DLDCheck"\n\nYes you are right, DLDCheck 5.0 will be released. Hopefully before the end\nof 1995. At the moment the following features will be found in v5.0.\n\nExpected release date:  ??? (Before the end of ''95)\nCoder:                  Rasmus K. Ursem, Dreamline Designs.\n\nThis project isn''t started yet, but when it is, it will have some/all of the \nfollowing features.\n\n-LZX-support. \n-Might have a key-file, but this depends on how sneaky I can make the \n protection.\n-Training option so you can teach DLDCheck new words in the IK process.\n-Option so you can define your own Logo-characters. -/\|#@!_ etc etc \n And which characters to ignore.\n-Maybe an option so you can make DLDCheck resident.\n-Option so you can set a work-dir.\n-Option so you can test corrupted archives and skip stripping/strip anyway.\n For use with BBS-systems.\n-Improved error messages and returncodes if the stripping failed.\n Optional of course so your BBS wont crash/hang because of return messages.\n-In the prefs: Option so you can save without quit.\n\n+Some "secret" ideas I will not reveal here. :)\n\nSuggestions are very welcome!!!\n\n@EndNode\n\n@Node "DLDCheck_Example" "Output example of DLDCheck 4.1a"\n\n{Startup info begins}\nDLDCheck V4.1a copyright 1995 by Rasmus K. Ursem/Dreamline Designs.\nRelease date 29.07.95. Registered to: Rasmus K. Ursem.\n\nKilling banners. Please wait...\n{Startup info ends}\n\n{Wildcard killing begins}\nKilling WildCard Files...Done!\n                         ^^^^^\nThis indicates that DLDCheck found and deleted wildcard banners. Other messages\nis selfexplaining.\n{Wildcard killing ends}\n\n{SafeMode begins}\nSafemode activated...Now processing: hd1:saves/stuff/TestDir/CTRLDEL.LHA\n\nIf you use AutoSkip or AutoQuit (set in prefs) the according text will be \nshown when the usual question "Not enough mem. Skip/Quit (s/q)" is printed.\n{SafeMode ends}\n\n{Maintenance begins}\nMaintenance option Activated. Searching for banners...\nMaintenance found and updated: "AdUMREb_ELGNAIRt!"      ;00001819\nMaintenance option DeActivated.\n\nShould be selfexpaining.\n{Maintenance ends}\n\n{MainKill begins}\nLhA Evaluation V1.52 - Copyright (c) 1993 by Stefan Boberg. \nAll rights reserved. Not for commercial use.\n\nDeleting files in archive ''T:DLDChecktemp.lha'':\n  Deleting ''AdUMREb_ELGNAIRt!''\n1 file deleted, all files OK.\n\nPacking archive...\nOperation successful.\n{Mainkill ends}\n\n{Intelligent Killmode begins}\n\nIntelligent Killmode Activated! Searching for Banners...\nAutodeleting this file from archive: LEDLRTC\nCheck Results:   WL:+  #OL:+  CR:+  SWH:+  SWL:-  CRC:-  KillPercentage: 100%\n                 ^^(1) ^^^(2) ^^(3) ^^^(4) ^^^(5) ^^^(6)\nThese abbreviations has the following meaning.\n\n(1) WL  = Wordlength check\n(2) #OL = Number of Lines or # of lines check.\n(3) CR  = Compress Ratio Check.\n(4) SWH = Special word from High-probability group found.\n(5) SWL = Special word from Low-probability group found.\n(6) CRC = CRC Check.\n\nA + after the : means that the check was positive.\nA - after the : means that the check was negative.\n\nAutodeleting this file from archive: -dT!\nCheck Results:   WL:-  #OL:-  CR:-  SWH:-  SWL:-  CRC:+  KillPercentage: 100%\n                                                  ^^^^^\nFile was deleted because CRC was set to autodelete!\n\nIntelligent Killmode DeActivated!\n{IntelligentKill ends}\n\n{All resetting, updating Killsizes begins}\nReDating file...Done!\nResetting fileComment...Done!\nAdding to todays killsize...Done!  (Added 00008090 bytes.)\n                                   ^^^^^^^^^^^^^^^^^^^^^^^\nThis is printed because "Show Killsize for actual archive" is set.\n\nAdding to total killsize...Done!\n{All resetting, updating Killsizes ends}\n\n@EndNode\n\n\n@Node "DLDCheck_DataFiles" "Datafiles used with DLDCheck 4.1a"\n\nDatafiles used with DLDCheck.\n\nENVARC:DLDCheck.Prefs\nDLDChecker:DLDBrainFile\nDLDChecker:Killbanners\nDLDChecker:Killbanners.addlist\nDLDChecker:CRCBanners\nDLDChecker:TotalKill\n\nENVARC:DLDCheck.Prefs\n This file is the preferences file generated with DLDCheckPrefs. This file\ncontains a lot of settings used by DLDCheck and all the utilities for\nDLDCheck.\n\nDLDChecker:DLDBrainFile\n This file contains brain info for the textkillmode, but also counters\nfor intelligent killmode.\n\nDLDChecker:Killbanners\n This file is the list used by DLDCheck. It contains all the banners, and\nthe counters if the maintenance option is used.\n\nDLDChecker:Killbanners.addlist\n This file contains the wildcard files such as "*.displayme". The file\nis added to the killbannerslist when DLDEdits WILDCARD option is used.\n\nDLDChecker:CRCBanners\n This file contains the CRC-info used by Intelligent killmode. Each entry\n is 12 bytes long.\n\nDLDChecker:TotalKill\n This file contains the killsizes for DLDCheck and the internal accesses\ncounter used by the maintenance option.\n\n@EndNode\n\n******** Nodes for DLDEdit *****\n\n@Node "DLDEdit" "The DLDEdit program."\n\n    @{" History          " Link "DLDEdit_History"} History for DLDEdit.\n    @{" How to install   " Link "DLDEdit_HowToInstall"} How to install DLDEdit.\n    @{" How to Use       " Link "DLDEdit_HowToUse"} How to use DLDEdit.\n\n@Endnode\n\n@Node "DLDEdit_History" "History for DLDEdit."\n\nHistory for DLDEdit\n\nV1.0  -Delete double lines in a SORTED list. (Sort with e.g. CygnusED)\n      -Delete wildcard banners. Reason: WildCardkill is faster than LHA.\n\nV2.0  -Added: Template. Now you can enable each of the 3 options.\n       DOUBLE:      Delete double lines.\n       WILDCARD:    Delete wildcardnames.\n       MAINTENANCE: Delete "old" banners.      \n       See the @{"how to use" Link "DLDEdit_HowToUse"} section for more information.\n      -Bugfix: Wildcardkill deleted the last banner in the list.\n      -Added: Wildcardkill will remove wildcardfiles with wildcards\n       specified in DLDCheckPrefs.\n      -Added: Now you can autoadd your own wildcardfiles. This is done\n       by entering the names in the Killbanners.addlist. Reason: Somebody\n       is adding banners called "<Archivename> From ...."\n      -Added: Maintenance option. This option is used to remove "old"\n       names from the killbanners file. You don''t have to worry about\n       deleting banners from the list. The intelligent killmode will find\n       them if they reappear.\n\nV4.1  -Added: In the template you can enable CRC. This will cause DLDEdit\n       to start maintenance in the file specified in NAME.\n\nV4.1a -Bugfix: If the Killbanners.addlist wasn''t present the program would exit\n       without doing anything.\n      -Bugfix: The wildcards wasn''t loaded from the prefs-file, but some internal\n       wildcards was used.\n\n@Endnode\n\n@Node "DLDEdit_HowToInstall" "How to install DLDEdit."\n\nHow to install DLDEdit.\n\n -Just copy DLDEdit to any directory e.g. c:\n\n@EndNode\n\n@Node "DLDEdit_HowToUse" "How to use DLDEdit."\n\n DLDEdit is used to handle the killbanners list.\n\nUsage: DLDEdit D=DOUBLE/S,W=WILDCARD/S,M=MAINTENANCE/S,C=CRC/S,N=NAME/A\n\nDOUBLE: Delete double lines in a SORTED list. (Sort with e.g. CygnusED)\n\nWILDCARD: Delete wildcardnames. Wildcards to delete is specified in \n        @{"DLDCheckPrefs" Link "DLDCheckPrefs"}.\n\nMAINTENANCE: Delete "old" names. The number of accesses before a file\n        is deleted is specifiled in @{"DLDCheckPrefs" Link "DLDCheckPrefs"}.\n\nCRC: This will tell DLDEdit that we are processing a CRCbanners file.\n     The only thing DLDEdit can do with CRCBanners is maintenance.\n\nNAME:   Name of list. E.g. DLDChecker:Killbanners or DLDChecker:CRCBanners.\n\n@EndNode\n\n******** Nodes for DLDCheckPrefs *****\n\n@Node "DLDCheckPrefs" "The Preferences program."\n\n    When you start DLDCheckPrefs it opens a window on you workbench screen.\n    This window has the following buttons. \n\n    @{" General     " Link "DLDCheckPrefs_General"} Settings for overall prefs.\n    @{" Safe        " Link "DLDCheckPrefs_Safe"} Settings for the Safe option.\n    @{" Add         " Link "DLDCheckPrefs_Add"} Settings for the Add option.\n    @{" Keep        " Link "DLDCheckPrefs_Keep"} Settings for the Keep option.\n    @{" Wildcard    " Link "DLDCheckPrefs_Wildcard"} Settings for the wildcard killmode.\n    @{" Compare     " Link "DLDCheckPrefs_Compare"} Settings for the compare killmode.\n    @{" Maintenance " Link "DLDCheckPrefs_Maintenance"} Settings for the Maintenance option.\n    @{" Intelligent " Link "DLDCheckPrefs_Intelligent"} Settings for the intelligent killmode.\n\n    + the usual prefs buttons and an about button.\n\n@Endnode\n\n@Node "DLDCheckPrefs_General" "Settings for general options."\n\n"Use color output" will enable color output. All important info will be in\nwhite.\n\n@EndNode\n\n@Node "DLDCheckPrefs_Safe" "Settings for the Safe option."\n\n"Auto skip/quit". When DLDCheck ask the question "not enough mem... skip/quit?"\nyou can tell DLDCheck to AutoSkip, AutoQuit or no auto. \n\n@EndNode\n\n@Node "DLDCheckPrefs_Add" "Settings for Add option."\n\n"Show Killsize for actual archive" With this on DLDCheck will display the\nkillsize for the archive.\n\n"Export Killsize to ASCII-file" With this on DLDCheck will save the killsize\nfor the archive as ASCII in T: This could be used by sysops for subtracting\nbyte-credits from an user.\n\n"Export Killsize to integer-file" With this on DLDCheck will save the killsize\nfor the archive as raw in T: This could be used by sysops for subtracting\nbyte-credits from an user.\n\n"ASCII filename" and "Integer filename" should be obvious.\n\n@EndNode\n\n@Node "DLDCheckPrefs_Keep" "Settings for the Keep option."\n\nHere you can enter your own filecomment.\n\n@EndNode\n\n@Node "DLDCheckPrefs_Wildcard" "Settings for the Wildcard killmode."\n\nHere you can add your own wildcards. This is done by selecting the "Add"\ngadget and enter the wildcard. You can now enter a string and use this as\na wildcard. E.g. $$\n\nThe "Del" gadget remove a wildcard from the listview.\n\n@EndNode\n\n@Node "DLDCheckPrefs_Compare" "Setting for the compare killmode."\n\nThe listview box called "Do not delete files with these extensions",\nthe "Add" and "del" gadgets is used to enter extensions. All files \ncalled <archivename><extension> will NOT be deleted.\n\nExample: You have entered ".Info", ".s", ".c", ".Doc" in the prefs.\n\nDLDCheck is now processing you banner called "test.lha". This archive\ncontain the following files.\n\n Test.s\n test.info\n test.ascii\n tEsT.c\n\nThe Compare killmode will only delete "test.ascii" because you have \nmarked the others extensions out in DLDCheckPrefs.\n\nNOTE: Remember to name the extensions ".<extension>" not "<extension>"\n      Else DLDCheck will look for files called "testinfo" instead of \n      "test.info".\n\nThe checkbox called "Use normal compare." is used to enable the normal\ncomparekill. If this is unchecked only reversed archivenames will be deleted.\n(If You use this.)\n\nThe checkbox called "Delete reversed archivenames." is used to enable\nthe reversed archivename kill. \n\nExample:\n -Original archivename "test.lha" \n -Reversed archivename "ahl.tset"\n\n@EndNode\n\n@Node "DLDCheckPrefs_Maintenance" "Settings for the mainteance option."\n\nThis slidergadget is used to set the number of accesses before DLDEdit\nwill remove the bannername from the killbanners file.\n\nNOTE: DLDCheck will not remove names, but only update found banners.\n\n@EndNode\n\n@Node "DLDCheckPrefs_Intelligent" "Settings for the intelligent killmode."\n\nThis part of DLDCheckPrefs is the most complex part of DLDCheckPrefs. In the\n"Intelligent" option-Window there are 3 bevelboxes.\n\nThe "check methods" bevelbox.\n -"Check filetype fast" is used to enable DLDChecks own filetype check.\n  This filetypechecker will look at the first 100 bytes of a file. This\n  is much faster than using FileID.library.\n -"Use FileID library" is used to enable filetype checking by\n  FileID.library. Use this in connection with fast filetype check and\n  you have a very efficient filetypechecker. The advantage of enabling\n  these filetype checkers is to make sure DLDCheck don''t start looking\n  in e.g. executeables.\n -"Check wordlength" is used to enable wordlength checking. Since banners\n  usually contains of very short words this checkmethod is used to sort \n  documents with long words out.\n -"Check # of Lines" is used to enable this checkmethod. You can set how\n  many lines a banner max contains.\n -"Check compress ratio" will enable the ratio checking. Since textfiles\n  usually has high compress ratios you can use this to sort out files.\n  The advantage of this is to prevent DLDCheck to unpack files from the \n  archive to evaluate them. \n -"Check special words" is used to enable the wordchecking. In the\n  bevelbox below can you enter words for this checkmethod. The check-\n  method is used to evaluate the textfiles. See more below.\n -"Use CRC checking" is used to enable CRC-Checking. This Checkmethod is\n  the absolute fastest way to remove *ANY* banner, once DLDCheck has found\n  the banner once. It checks the CRC and file-size for the files and if\n  a known banner is found it is deleted. It is fast because NO analyse\n  routines is used in the files.\n\n -The Settings gadgets is used to specify settings for the checkmethod\n  just left of the gadgets.\n\n\nThe "Main limits" bevelbox.\n -"Minimum size" is used to set the minimum size of files to evaluate.\n -"Maximum size" is used to set the maximum size of files to evaluate.\n -"Show&Ask below" is used to set the size of files DLDCheck should \n  evaluate no matter what. The reason is that some files dosn''t contain\n  any data, but the filename is a banner. E.g. "DAIL+45XXXX0431" size 5\n  bytes.\n -"Ask files above" is used to set the limit between Banner/Not banner.\n -"Del files above" is used to set an "autoremove" limit. All files with\n  ASCIILogoCharPercentage(the displayed percentage) above this will\n  automatically be deleted. This is used to remove random-generated \n  bannernames.\n\nThe "Global Settings" Bevelbox.\n -"Text output" is used to enable text output. With this checked DLDCheck\n  will write more info about which checkmethod resulted positive.\n\nThe printed line will look like this:\n\nCheck Results:   WL:-  #OL:-  CR:+  SWH:-  SWL:-  CRC:-  KillPercentage: 84%\n\nWL  is WordLength Check.\n#OL is # of Lines.\nCR  is Compress Ratio.\nSWH is Special words high probability.\nSWL is Special words low probability.\nCRC is CRC Checking.\n\n -"Count banners" enables the count option. When this option is set\n  DLDCheck will count accesses to IK, killed banners, removed banners and\n  autoremoved banners. If this option is set DLDChecks showmode will print\n  these counts.\n -"Check in subdirs". Search for banners in subdirs. \n -"Store new banners". Store new banners in DLDChecker:NewBanners.\n\n\nIn some of the settings windows is a checkbox called "Use wordlength in \nfinal analyze" or something like that. This will make the check affect the\npercentage printed when a file is found. The amount of percent the final\nanalyze is affected can be set for each check by setting the "Influence"-\ngadget. \n\nAn example of a positive check:\n\nThe main check for chars like /\\_- gives:       63%\nThe # of Lines check is positive +5%            68%  (Influence = 5%)\nThe Compress ratio is positive +8%              76%  (Influence = 8%)\n\nNOTE: Wordlength check has special info. See below.\n\n\nWhen opening the settings for WordLength.\n -"Remember largest word". When this is set the checkmethod \n  "Check wordlength" will store the largest wordlength for future checking.\n  DLDCheck will then only pass files with average wordlength 1 greater than\n  the largest wordlength.\n  If you not set this the checkmethod will only pass files with average\n  wordlength equal or lesser than the limit set in the "Avg. wordlength"-\n  gadget.\n -"StepSize" is used to calculate the influence on the final analyze. See\n  below.\n -"Avg. Wordlength" specifies the average wordlength for this checkmethod.\n  If you are using "Use wordlength in final analyze" the final analyze will\n  be affected like this.\n\n  Percentage = Percentage + ((Avg Wordlength- Actual Avg wordlength)*Stepsize)\n\n  Example:\n\n  The Percentage is 78%, the Actual Avg wordlength is 3, the Avg. word-\n  length is set to 4 and the stepsize is 2%\n\n  After this check the percentage is \n\n  Percentage = 78 + ((4-3)*2 = 78 + 2 = 80%\n\n\n\nWhen opening the settings for # of Lines.\n -"Maximum # of Lines" will set the maximum # of Lines. If you use \n  "Use # of Lines in final analyze" and the file has less than the amount\n  specified here, the value specified in "Influence" will be added to the\n  final percentage. Else the file will be evaluated further or if the \n  # of lines exceeds this amount the file will be skipped.\n\n\n\nWhen opening the settings for ratio check.\n -"Minimum ratio" is used to set the minimum ratio for the checkmethod\n  "Check compress ratio". It works exactly the same way as # of lines.\n\n\n\nWhen opening the settings for Special words.\n  This window contains 3 listviewboxes. These are used as the other\n  listviews in e.g. wildcardkillmode. The 3 types of words is defined below.\n  NOTE: The evaluation version of DLDCheck 4.1a will handle the 3 types\n  as equals. In other words don''t enter anything in the low probability\n  list. \n\n -High probability: This type of words are ONLY found in banners.\n  The wordlength will be multiplied with 2 and added to the percentage.\n  Words in this group: boardnames, sysopnames, groupnames ect ect.\n\n -Medium probability: This type of words are most likely found in banners, \n  but could also be found in textfiles.\n  The wordlength will be added to the percentage.\n  Words in this group: Sysop, cosysop, wares, bbs, node, ect ect.\n\n -Low probability: This type of words are almost NEVER found in banners.\n  The wordlength will be multiplied with 2 and subtracted from the\n  percentage.\n  Words in this group: Assign, Printf, move.l, loadwb, path ect ect.\n\n -"Kill high, skip low." If you use this DLDCheck will kill the file if\n  it finds a word from the High-probability-group and skip it if it finds\n  a word from the low-probability-group. If Both groups is found you can \n  select the action in the cycle-gadget just right of this gadget.\n  If you use this you must be very sure you don''t have any "Maybes" in the \n  high probability-group.\n\n -"Action if high and low found." This is used to specify the action if\n  DLDCheck finds both high and low-probabilty-words. The 3 options.\n  \n  -Normal: Proceed as nothing happed and if the percentage is high enough\n           ask/autodelete.\n  -Kill:   Autodelete the file.\n  -Skip:   Skip the file.\n\n -"Check max words." This is the max number of special words you want \n  DLDCheck to Look for. Used to speed up the checking.\n\nWhen opening the settings for CRC-Checking.\n -"Action when found" specifies what you want DLDCheck to do with the file.\n   -"Autodelete" will delete the file automatically.\n   -"Affect analyze!" will affect the final analyze with the value set in\n    the "influence" gadget.\n\n@EndNode\n\n******** Nodes for DLDAdd *****\n\n@Node "DLDAdd" "The DLDAdd program."\n\n    @{" History          " Link "DLDAdd_History"} History for DLDAdd.\n    @{" How to install   " Link "DLDAdd_HowToInstall"} How to install DLDAdd.\n    @{" How to Use       " Link "DLDAdd_HowToUse"} How to use DLDAdd.\n    @{" Using with DOpus " Link "DLDAdd_UsingWithDOpus"} How to set you buttons in Opus.\n\n@Endnode\n\n@Node "DLDAdd_History" "Program History for DLDAdd."\n\nHistory for DLDAdd.\n\nV1.0  -Locates and add the selected name to list. Not released to public.\n\nV1.05 -Added: DLDAdd now checks the list for the name before adding\n      to prevent more than one entry.\n\nV1.1  -Added: Option to add to Killbanners.addlist.\n\nV4.1  -Added: CRC adding.\n\nV4.1a -Improvement/bugfix: DLDAdd couldn''t add maintenance info. Now added\n       M=MAINTENANCE/S to the template. Using the M in commandline will tell DLDAdd\n       to add the maintenance-information. If you have any lines in your present\n       Killbanners-file without the maintenance-info you can add this by hand.\n       Do as follows.\n\nAfter each line WITHOUT WILDCARDS add this:\n<TAB>;00000000\n\nThe 8 zeros can be replaced by your current access-count. (Use DLDCheck Mode S\nto find this.) But remember there must be 8 digits after the <TAB>; and\nthe <TAB> must be a <TAB> NO SPACES!\n\nExample:\n\n"MightyFine" ;00001842\n\nNOTE: You should always use "file" (Quotes), because some clever guys\n      use > at the begining of their bannernames so ReadArgs think\n      that it''s a redirection and it gets confused.\n\n2nd NOTE: LHA must be present in path.\n\n@EndNode\n\n@Node "DLDAdd_HowToInstall" "How to install DLDAdd."\n\nHow to install DLDAdd.\n\n -Just copy DLDAdd to any directory e.g. c:\n\n@EndNode\n\n@Node "DLDAdd_HowToUse" "How to use DLDAdd."\n\nDLDAdd is used to add a bannername to the KillBanners list.\n\n Usage: DLDAdd W=WILDCARD/S,C=CRC/S,NAME/A\n\nWILDCARD:\n Add the name to the killbanners.addlist as well. This will prevent\n      the file to be deleted if it consists any wildcards. You should only\n      use this option with names containing wildcards. E.G. Some adders\n      will add banners called "<ArchiveName> Passed <BoardName>".\n\nCRC: Will add CRC-Info to DLDChecker:CRCBanners.\n\nNAME: The name of the banner to add to the list.\n\n@EndNode\n\n@Node "DLDAdd_UsingWithDOpus" "How to use DLDAdd in DOpus."\n\nJust adding to the Killbanners list.\n\nThe DLDAdd button.\nName:  DLDAdd\nThe entry is: AmigaDOS    DLDChecker:DLDAdd NAME {o}\nFollowing flags are used:\n	-Do all files\n	-Run asynchronously\n\nStack Size:   4000\nPriority:     0\nClose Delay:  0\n\nAdding to both "Killbanners" and "Killbanners.addlist".\n\nThe DLDAdd W button.\nName:  DLDAdd W\nThe entry is: AmigaDOS    DLDChecker:DLDAdd W NAME {aEnter wildcard name.}\nFollowing flags are used:\n	-Run asynchronously\n\nStack Size:   4000\nPriority:     0\nClose Delay:  0\n\nAdding CRC-Info to the CRCBanners list.\n\nThe DLDAdd C button.\nName:  DLDAdd\nThe entry is: AmigaDOS    DLDChecker:DLDAdd CRC NAME {o}\nFollowing flags are used:\n	-Do all files\n	-Run asynchronously\n\nStack Size:   4000\nPriority:     0\nClose Delay:  0\n\n@EndNode\n\n****** Nodes for DLDConfig ********\n\n@Node "DLDConfig" "The DLDConfig program."\n\n Nothing is changed since last.\n\n    @{" History          " Link "DLDConfig_History"} History for DLDConfig.\n    @{" How to install   " Link "DLDConfig_HowToInstall"} How to install DLDConfig.\n    @{" How to Use       " Link "DLDConfig_HowToUse"} How to use DLDConfig.\n\n@Endnode\n\n@Node "DLDConfig_History" "Program history for DLDConfig."\n\nV1.0	-First working version.\n\n@Endnode\n\n@Node "DLDConfig_HowToInstall" "How to Install DLDConfig."\n\nHow to Install DLDConfig.\n\n -Just copy DLDConfig to any directory.\n\n@Endnode\n\n@Node "DLDConfig_HowToUse" "How to use DLDConfig."\n\nHow to use DLDConfig.\n\nThis program is used to generate a small configuration-file. This file\ncontains the same options as you can specify in the template.\nInstead of typing all the options in the template you just execute\nDLDConfig, set the options, click the "save" gadget and enter a filename.\nWhen executing DLDCheck you just enter this in the shell.\n\nDLDCheck mode c name <Archivename> Configfile <Configfilename>\n\nDLDCheck will now load the options from <Configfilename> and carry on\nwith these options.\n\n@EndNode\n','\n',char(10)),NULL,'auto-added',80979,1,0,NULL,NULL,'dldc41ae','scan',1780048474);
INSERT INTO door_catalog VALUES('dldchk4e','DLDCHK4E.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DLDCHK4E.LHA','DLDAdd','XIM','DLDAdd','4.0','Rasmus',NULL,'- DLDCheck can be used to remove (and add) BBS advertisments, socalled banners, from lha-archives.  DLDCheck can also remove',replace('DLDCheck v4.0 Evaluation by Rasmus K. Ursem\n- DLDCheck can be used to remove (and add)\nBBS advertisments, socalled banners, from\nlha-archives.  DLDCheck can also remove\nbanners from textfiles.  DLDCheck is aided\nby Artificial Intelligence.\n','\n',char(10)),'DLDCheck.guide',replace('@database "DLDCheck.guide"\n@master "DLDCheck.Guide"\n\n@Node Main "DLDCheck documentation."\n                       \n      Dreamline Designs presents DLDCheck V4.0 coded by Rasmus K. Ursem.\n                             Released 13.12.94\n\n    @{" Introduction    " Link "Intro"} What is DLDCheck?\n    @{" Disclamer       " link "Disclamer"}\n    @{" Copyrights      " link "Copyrights"}\n    @{" Contact address " link "address"} How to reach the author.\n    @{" Registration    " link "Registration"} How to register.\n    @{" Requirements    " link "Requirements"} Needed system requirements.\n    @{" Greetings       " Link "greetings"} Dreamline Designs greetings.\n    @{" Supporters      " Link "Supporters"} Supporters of DLDCheck.\n    @{" Users           " Link "Registrated"} Registrated users of DLDCheck.\n\n    Programs in the archive\n    @{" DLDCheck   " link "DLDCheck"} Bannerstripper program.\n    @{" DLDEdit    " link "DLDEdit"} Handle bannerlist program.\n    @{" DLDPrefs   " link "DLDPrefs"} Preferences program.\n    @{" DLDAdd     " link "DLDAdd"} Update bannerlist program.\n    @{" DLDConfig  " link "DLDConfig"} Configuration program used with mode C.\n\n@EndNode\n\n@Node "Intro" "Introduction"\n\nWelcome to DLDCheck version 4.0 Evaluation.\nDLDCheck is coded by Rasmus K. Ursem in pure Assembler.\n\nThis is the evaluation version of DLDCheck 4.0. DLDCheck 4.0 is now\nshareware. See more in the @{"registration" link "Registration"} section.\n\nDLDCheck can be used to remove (and add) BBS advertisments, socalled\nbanners, from lha-archives. DLDCheck can also remove banners from textfiles.\n\n@EndNode\n\n@Node "Disclamer" "Disclamer"\n\nI take no responsibility for datacurruption or lack of data caused by\nDLDCheck, anyway it''s tested many times and has shown no errors so far.\n\nNOTE: DO NOT ADD THE BANNER NAMED ''*'' THIS IS A WILDCARD AND ALL FILES IN\nARCHIVE WILL BE DELETED!!!!!\n(DLDCheck Version 2.2+ can kill wildcardbanners.)\n\n@EndNode\n\n@Node "Copyrights" "Copyrigths for DLDCheck 4.0 and all the utilities for DLDCheck 4.0."\n\nDLDCheck is ©copyrighted 1994 by Rasmus K. Ursem. All rights reserved.\nPermission is hereby granted to copy DLDCheck 4.0 EVALUATION as long as\nall files stays intact and only a nominal fee (Max 5$) is charged for\ncopy and postage. Permission is also granted to put DLDCheck 4.0 EVALUATION\non PD-libraries such as Fred Fish. But NOT include in Magazine Coverdisk\nwithout my authorization.\n\nDLDCheck 4.0 and all the utilities for DLDCheck 4.0 is shareware. See more\nin the @{"registration" link "Registration"} section.\n\nThis LHA-Archive includes the following files...\n\nDLDCheck\nDLDAdd\nDLDEdit\nDLDPrefs\nDLDSet\nKillBanners\nKillBanners.addlist\nDLDBrainFile\nDLDCheck.guide\nFile_ID.Diz\n(+A lot of trashy bbs adds!)\n\n@EndNode\n\n@Node "address" "Contact address"\n\nYou can reach me at this address\n\n    Rasmus K. Ursem / Dreamline Designs\n    Vittenvej 26\n    8382 Hinnerup\n    D E N M A R K\n    Phone: +45 86 91 00 58\n\nor at these NetAddresses:\n\nRasmus K. Ursem:	2:238/67.3 (FidoNet)\nRasmus K. Ursem:	10:2/0.3 (HOANet)\nRasmus K. Ursem:	39:140/111.3 (AmigaNet)		\nPeter F. Frandsen:      U940326@.daimi.aau.dk (InterNet)\n\n@EndNode\n\n@Node "Registration" "How to register DLDCheck 4.0."\n\nYou can register DLDCheck 4.0 by sending 50dkr/10US$/5GB£ + 1 disk + \n1 stamped and addressed envelope or 60 dkr/12US$/6GB£ + your address\nto my @{"address" link "address"}.\n\nPlease include your own killbannerlist, your system data, age, group ect.\nect. \n\nWrite if you DON''T want to be on the @{"registrated" link "Registrated"} users list.\n\n@EndNode\n\n@Node "Requirements" "System requirements for DLDCheck and DLDCheck Utilities."\n\n -AmigaOS V37+ (Workbench 2.04+)\n -Reqtools.library\n -FileID.library v2.0+ \n -LHA v1.40+ (I don''t know those old versions of LHA, maybe old versions \n  will work.)\n\n@EndNode\n\n\n@NODE "Greetings" "The official greetinglist."\n\n	DLD send hellos to the following groups''n''gurus...\n\n	Transonic\n	Parasite\n	Polka Brothers\n	Triangle 3532\n	The Flame Arrows\n	Dragnet\n	Static Bytes\n	Kingdom\n	Upfront\n	Millenium Marauders\n	SubAcid\n\n	Heinz Peter Lindner\n	Bo Nørgaard\n	Michael ''Fix'' Sølvstad\n	Kaare ''Swyx'' Heinsen\n	Jan Green\n	Jens Andersen\n	Jesper Juul\n	Warner of Noise. (Thanks for supporting DLDCheck.)\n	Morten K. Andersen.\n	Peter F. Frandsen.\n\n	And finally - Commodore Inc.\n	 cause ''Only Amiga Makes It Possible!''\n\n@ENDNODE\n\n@Node "Supporters" "The official supporters for DLDCheck."\n\n   The following people supports DLDCheck with new banners, new ideas and\n   bugreports.\n\n  -Jesper Rou Larsen. Thanks for the Bugreports, ideas and banners.\n\n  -Warner of Noise. Thanks for the bugreport and your killbanners list.\n\n  -Klaus Jensen. Thanks for new ideas to DLDCheck 3.0.\n\n  -Kim Sindalsen. Thanks for the bugreport and new ideas.\n\n  -Peter F. Frandsen Thanks for bugreports and being my link to InterNet.\n\n  -Morten K. Andersen. Thanks for being my link to FidoNet,HOANet\n   and AmigaNet.\n\n    Wanna be on this list? Contact me with bugreports, ideas, bannerslists!\n\n@EndNode\n\n@Node "Registrated" "Registrated users of DLDCheck 4.0"\n\n  Registrated users of DLDCheck 4.0\n\n  -Jesper Rou Larsen.\n\n  -Karsten T. Niemeier.\n\n@EndNode\n\n******** Nodes for DLDCheck *****\n\n@Node "DLDCheck" "DLDCheck 4.0 main menu."\n\n  DLDCheck 4.0 main menu.\n\n    @{" History          " Link "DLDCheck_History"} History for DLDCheck 4.0.\n    @{" How to install   " Link "DLDCheck_HowToInstall"} How to install DLDCheck.\n    @{" How to Use       " Link "DLDCheck_HowToUse"} How to use DLDCheck.\n    @{" Using with DOpus " Link "DLDCheck_UsingWithDOpus"} How to set you buttons in Opus.\n    @{" Future plans     " Link "DLDCheck_FuturePlans"} Future plans for DLDCheck.\n    @{" Datafiles        " Link "DLDCheck_DataFiles"} DLDChecks relations to the datafiles.\n\n@Endnode\n\n@Node "DLDCheck_History" "History for DLDCheck."\n\nV1.0  -First workable version, but had some minor bugs. Couldn''t load\n      files with spaces. Released at The Party III\n\nV1.01 -Bug Fix: Could load files with spaces. Also released at The Party\n       III\n\nV1.1  -DLDCheck now uses ReadArgs() from the dos.library instead of just\n      getting it from the CLI. ReadArgs() is more systemfriendly and\n      DLDCheck will therefore be forward compatible.\n      -Bug Fix: DLDCheck could misundestand a ''-'' in the filename as a\n      option. This is also removed by using ReadArgs. (Thanks goes to Zest/\n      Triangle 3532 for telling me how to use ReadArgs.)\n      -Removed the ? option and included amigaguide instructions instead.\n      -Added LHA option -Qo and -Qw. Added because some bannernames \n      includes ''-'' and other wierd characters LHA could misundestand as \n      user-selected options, unfortunately LHA has a bug so -Qw dosn''t\n      work. (Don''t add the ''*''-banner in the KillBanners list, because\n      this will delete all files in the archive!!!!)\n      -Added a utility to put a new banner in the list. I coded this \n      small utility because I didn''t wanted to load an editor every time\n      I found a new banner. (I find a lot! :-l )\n\nV1.2  -Some minor options added, but this version was never released to\n      public because I decided to add a lot new stuff and rearrange the \n      template.\n\nV2.0  -Added Todays Killsize and total killsize so you can see how many\n      bytes of banners you have removed with DLDCheck.\n      -Added PROT option to ignore Protection flag.\n      -Possibility to add a banner with DLDCheck.\n      -New structure for the template, Sorry guys...\n      This Version is not released to public.\n\nV2.1  -Added S=SAFE option. Purpose to insure survival of your precious\n      HD. The reason is yet another bug in LHA, sometimes the Amiga\n      crashed while packing data, and thereby using the HD for saving.\n      The result: A Currupted HD and hours of repairwork.\n      -Bugfix: During MODE Show, DLDCheck didn''t show anything if the\n      file T:KilledToDay was not present.\n\nV2.2  -Bugfix and repairwork on the Safemode option. DLDCheck now ask\n      "skip safemode or quit" if the archive cannot be copied to mem.\n      -Added Wildcard kill. Filenames with the following letters will be\n      deleted: * # ? ~ |. This will not happen if the archive is to big.\n      I will maybe make this with buffers later. \n      -Removed LHAs "-Qw" option because it dosn''t work anyway.\n\nV2.3  -Added CompareKillmode. This new killmode stores the archivename\n      and kills any name in archive that looks like it. Files to be\n      deleted by this option is "Filename.#?" Option added because\n      some guys have started to add banners with almost the same name\n      as the archive.\n      Note: You should only use this option with care.\n      -Bugfix and repair work on the safemode option.\n\nV2.4  -Added Intelligent killmode(IK). Since some guys get wiser and wiser\n      to avoid getting their banners killed, (Such as generating random-\n      names.) I added this routine.  \n      -In connection with the IK I added an auto DLDAdd. In other words.\n      If IK finds a banner it will automatically add the name to\n      DLDChecker:Killbanners. Why? Because IK is slow compared to deleting\n      from a filelist.\n      -Added some banners to the list from a file called "2BAD.NFO". \n      This file was somebody''s killbanners list, released to public.\n      This version of the Killbanners file is roughly sorted so you easy \n      can insert you own banners.\n      -Added a printline when using the Safe option, so you can see what\n      archive you are processing.\n      -Added some new chars to the Wildcard kill routine.\n\nV2.5  -Bugfix: Using safemode an errors occured during the use of "Copy"\n      DLDCheck would delete the archive. Thanks goes to *Warner of Noise*.\n      -Bugfix: Using safemode and the wildcard option DLDCheck would crash \n      on some large archives.\n      -Added an option in the intelligent killmode so you can remove the\n      banner from the archive without adding it to the "Killbanners".\n      -Added a lot of banners to the KillBanners list. Thanks goes to\n      Warner of Noise.\n\nV3.0  -Bugfix: IK would crash if files with filesize=0 occured.\n      -Repairwork: IKs checkroutine had some minor bugs, now fixed.\n      -Added: BrainFile. Yes, DLDCheck can learn words to check in IK.\n      The brainfile is also used in connection with the new killmode.\n      -Added: New KillMode to remove banners from textfiles.  Artificial\n      Intelligence (AI) is used to learn the ways of the user.\n      In other words DLDCheck will learn how YOU use DLDCheck, and then\n      use this.\n      -Added: DLDEdit, a small utility to delete doublelines and \n      wildcard filenames in a SORTED Killbanners file. (Sort with CygnusEd)\n      -Added: New chars to wildcardkill. Now deletes files with these chars:\n      *#?><|»«©®~^¶ª×¿   (This method is faster than LHA.)\n      -Expanded: The Show option now shows the LHA-archive killsize,\n      text killsize and the words in memory.\n      -Added: A lot of banners from different files. KillBanners is now\n      more than 25Kb.\n\nV3.1  -Bugfix: Major problems in brainfile.\n      -Bugfix: DLDCheck Could set the delete point before the file starts\n      or after End Of File. Now fixed.\n      -Bugfix: IK would crash if files with filesize=0 occured. Wasn''t\n      repaired well in 3.0.\n      -Repairwork: The checkline routine would, until now, take spaces\n      for ASCIILogochars. Spaces are now total out of the evaluation\n      process.\n      -Repairwork: When changing the front delete position You had to wait \n      for a total print of the start of the file. Now DLDCheck prints the\n      last 12 lines before and after the delete position.\n      -Expanded: Show option expanded and readout of remembered words \n      changed a little bit.\n      -Added: Using Textkillmode. The checkline routine would take a total\n      line of ---- or ==== as an ASCIILogocharline. These lines are now\n      total out of the  evaluation process. An AI sort-method will try to\n      determine these lines as underlines or just a good-for-nothing\n      partline.\n      -Added: Using Textkillmode. A line to tell you where DLDCheck will\n      delete. Reason: ANSI readout would fuck up the show mode in \n      DLDCheck 3.0.\n      -Added: DLDCheck now print the file being processed during textmode.\n      -Added: Using IKA. "Train" and "Quit" added. "Train" will train the \n      BrainFile. "Quit" will quit the IKA instead of just cancel the\n      file being processed.\n      -Added: Using IKA. After viewing a file containing colorchanges\n      DLDCheck now resets the printcolor.\n      -Added: Using IKA. Spaces, Tabs and CRs are now out of the evaluation\n      process.\n      -Info: Sourcesize 92103 bytes, 5877 lines of code.\n\nV4.0  -Added: New option called maintenance. This option is used to update\n       the killbannerslist. Each name in the list will get a number which\n       is the last time this banner was deleted from an archive. The reason\n       is the extreme large killbannerslist, this takes very long time to \n       load. You can set the amount of accesses before removal in the \n       DLDPrefs program. See the @{"DLDPrefs" link "DLDPrefs_Maintenance"} section.\n       DLDCheck is not used to remove names from the list because this \n       takes long time. This is done by DLDEdit. See the @{"How to Use" link "DLDEdit_HowToUse"}\n       section.\n       When the maintenance option dosn''t find any banners, DLDCheck will\n       skip the mainkill because this is checking the archive twice and\n       getting the same result. NOTE: This dosn''t work in the evaluation\n       version.\n      -Added: New Mode Configure. This new mode can take a configuration\n       file generated by @{"DLDConfig" link "DLDConfig"} and use this as a template.\n       The goal is to avoid entering long templates in the shell. Instead\n       just enter the saved configfile and DLDCheck will read arguments\n       from this file.\n      -Added/Improved: The show mode is expanded with a lot of counters,\n       accesses ect ect. This is output is determined by the prefs.\n      -Changed: Keep option. You can set you own filecomment. See the\n       DLDPrefs @{"Keep" link "DLDPrefs_Keep"} section.\n\n      -Intelligent Killmode:\n	-Bugfix: IK mode crashed if LHA failed when extracting files from\n	 archive. No fixed.\n	-Bugfix: IK mode found wierd banners. Now fixed.\n	-Bugfix: The ASCII-Checker had minor bugs. Now fixed.\n	-Added: DLDCheck tells if anything goes wrong.\n	-Added/Improved: 3 Types of words. Used to determine a textfiles\n	 probability of being a banner. See more information in the\n	 DLDPrefs @{"intelligent" link "DLDPrefs_Intelligent"} section.\n	 NOTE: Crippled in evaluation version.\n	-Added: Check filetype with FileID.library.\n	-Added: Fast filetype check.\n	 NOTE: Not optimized in evaluation version.\n	-Added: Average wordlength checking. (Banners usually have very\n	 low lix-value.)\n	 NOTE: Not optimized in evaluation version.\n	-Added: Ratio checking. (Banners usually have high packing ratio.)\n	-Added: You can set a lot of limits in the prefsfile. See more\n	 information in the DLDPrefs @{"intelligent" link "DLDPrefs_intelligent"} section.\n	-Added: Autodelete option. DLDCheck can automatically delete files\n	 above a certain percentage.\n	-Added: Count found banners. DLDCheck can count banners so you can\n	 see how many banners IK has found/removed/killed/autodeleted.\n	-Added: Check in subdirs. \n	 NOTE: Not available in evaluation version.\n	-Added: Adding subdir-banner-names to killbanners and\n	 killbanners.addlist.\n	 NOTE: Not available in evaluation version.\n      -Compare Killmode:\n	-Improved/Changed: The whole Compare Killmode is rewritten. Now\n	 this killmode handle each file like Intelligent Killmode. Not\n	 just deleting all files called <archivename>.#?\n	-Added: Compare killmode can sort extensions. In DLDPrefs you can \n	 set extensions which this killmode will NOT delete.\n	 NOTE: Limited in evaluation version to a maximum of 4.\n	-Added: Option to delete reversed archivenames.\n      -Wildcard killmode:\n	-Changed: You can set the wildcards to search for.\n      -Info: Sourcesize 125465 bytes, 8153 lines of code.\n\n@EndNode\n\n@Node "DLDCheck_HowToInstall" "How to install DLDCheck 4.0"\n\nHow To install DLDCheck\n\n-Assign any directory as "DLDChecker:"\n-Copy the file called "KillBanners" to DLDChecker:\n-Copy the file called "DLDBrainFile" to DLDChecker:\n-Copy the file called "KillBanners.addlist" to DLDChecker:\n-Copy DLDCheck to any directory. (Eg C: )\n-Make sure the program "LHA" is in an AmigaDos pathed directory.\n-If you use the S=SAFE option be sure Copy is in C:\n\n@Endnode\n\n@Node "DLDCheck_HowToUse" "How to use DLDCheck 4.0"\n\n  How to use DLDCheck 4.0s modes.\n\n  @{" Delete " link "DLDPrefs_HowToUse_Delete"}\n  @{" Add    " link "DLDPrefs_HowToUse_Add"}\n  @{" Show   " link "DLDPrefs_HowToUse_Show"}\n  @{" Text   " link "DLDPrefs_HowToUse_Text"}\n  @{" Config " link "DLDPrefs_HowToUse_Config"}\n\n@EndNode\n\n@Node "DLDPrefs_HowToUse_Delete" "The Delete mode."\n\n Usage:\nDLDCheck M=MODE/A,D=DATE/S,K=KEEP/S,P=PROT/S,A=ADD/S,AT=ADDT/S,S=SAFE/S,\nW=WILD/S,C=COMPARE/S,MAIN=MAINTENANCE/S,IKA=IKILLASK/S,IKF=IKILLFORCE/S,\nN=NAME/K,F=ADDFILE/K,CON=CONFIGFILE/K\n\n\n MODE = D\n      D will delete banners from the list DLDChecker:Killbanners in the\n      archive specified in N=NAME/K.\n\n Available options in the Delete mode.\n\nDATE: LHA set the Archive date to your systems current date. If you use\n      the DATE-Swhich DLDCheck will NOT redate the filedate to the old\n      date.\n      Default: Redate.\n\nKEEP: Keep filecomment always. DLDCheck sets a filecomment, but ONLY if the\n      current filecomment is empty. KEEP will make sure DLDCheck NEVER\n      overwrites filecomment.\n      Default: Writes comment if and only if there is no comment.\n\nPROT: Deactivates the "ignore protection" option in LHA.\n      Default: Ignore protectionbit.\n\nADD:  Add to todays killsize. This is a small file stored in T: usually\n      in ram: this will speed up for floppyusers.\n      Default: Not adding.\n\nADDT: Add to the total killsize. This is a small file stored in\n      DLDChecker: This option is mainly for HD-users.\n      Default: Not adding.\n\nSAFE: Safe option. This option copies the archive to ram: and works\n      from there. If LHA crashes no HD need repair. At last DLDCheck\n      copies the archive back to the original place. This option is\n      just a precaution agains another LHA-Bug.\n      Default: No safe.\n\nWILD: Kill wildcard files. This option can remove files which can''t\n      be removed with LHA. This may take some time, because the archive\n      must be loaded into Memory before it can be processed.\n      There are 3 returnlines from this option.\n	-Done!       which indicates that there WAS wildcardfiles.\n	-No WildCard files in Archive!\n	-Not enough memory free!\n      Default: No Wildcard Killing.\n\nCOMPARE:\n      Will delete files in archive with names semilar to the archive-\n      name. e.g. Archive name is Test.lha. All files in Test.lha that\n      fits the following pattern (Test.#? will be deleted. You can \n      specify special extensions like .info/.dms/.s ect ect. Files \n      with these extensions will not be deleted.\n      Default: No CompareKill.\n\nIKA:  Intelligent Killmode with Ask option before deleting.\n\nIKF:  Intelligent Killmode with Force option. BE CAREFUL!\n\n      The IK works this way: With LHA DLDCheck generates a FileList of\n      the archive. From this list DLDCheck extracts all those files\n      that looks interesting. (No, I won''t tell you the Sort method!)\n      When a file is extracted it will be examined for chars used\n      often in connection with Banners, and words in connection with\n      BBS''s. If IK finds a banner it will, depending on the selected\n      mode (IKA or IKF), ask, and then delete the file from the archive.\n      Finally IK will add the bannername to DLDChecker:KillBanners.\n      (Type r to remove banner without adding the name to the list.)\n\nNAME: The name of the LHA-Archive to kill banners in.\n\n\nMany special settings can be set with @{"DLDPrefs" link "DLDPrefs"}.\n\n@EndNode\n\n@Node "DLDPrefs_HowToUse_Add" "The Add mode."\n\n Usage:\nDLDCheck M=MODE/A,D=DATE/S,K=KEEP/S,P=PROT/S,A=ADD/S,AT=ADDT/S,S=SAFE/S,\nW=WILD/S,C=COMPARE/S,MAIN=MAINTENANCE/S,IKA=IKILLASK/S,IKF=IKILLFORCE/S,\nN=NAME/K,F=ADDFILE/K,CON=CONFIGFILE/K\n\n MODE = A\n      A will add the banner specified in F=ADDFILE/K to the archive\n      specified in N=NAME/K.\n\n Available options in the Add mode.\n\nDATE: LHA set the Archive date to your systems current date. If you use\n      the DATE-Swhich DLDCheck will NOT redate the filedate to the old\n      date.\n      Default: Redate.\n\nSAFE: Safe option. This option copies the archive to ram: and works\n      from there. If LHA crashes no HD need repair. At last DLDCheck\n      copies the archive back to the original place. This option is\n      just a precaution agains another LHA-Bug.\n      Default: No safe.\n\nNAME: The name of the LHA-Archive to kill banners in.\n\nADDFILE: The name of the banner to add.\n\n@EndNode\n\n@Node "DLDPrefs_HowToUse_Show" "The show mode."\n\n Usage:\nDLDCheck M=MODE/A,D=DATE/S,K=KEEP/S,P=PROT/S,A=ADD/S,AT=ADDT/S,S=SAFE/S,\nW=WILD/S,C=COMPARE/S,MAIN=MAINTENANCE/S,IKA=IKILLASK/S,IKF=IKILLFORCE/S,\nN=NAME/K,F=ADDFILE/K,CON=CONFIGFILE/K\n\n MODE = S\n      S shows a lot of information about DLDChecks killsizes, words and\n      other settings.\n\n No options available.\n\n@EndNode\n\n@Node "DLDPrefs_HowToUse_Text" "The text mode."\n\n Usage:\nDLDCheck M=MODE/A,D=DATE/S,K=KEEP/S,P=PROT/S,A=ADD/S,AT=ADDT/S,S=SAFE/S,\nW=WILD/S,C=COMPARE/S,MAIN=MAINTENANCE/S,IKA=IKILLASK/S,IKF=IKILLFORCE/S,\nN=NAME/K,F=ADDFILE/K,CON=CONFIGFILE/K\n\n MODE = T\n      T Enables the intelligent textkillmode.\n\n Available options in the text mode.\n \nADD:  Add to todays killsize. This is a small file stored in T: usually\n      in ram: this will speed up for floppyusers.\n      Default: Not adding.\n\nADDT: Add to the total killsize. This is a small file stored in\n      DLDChecker: This option is mainly for HD-users.\n      Default: Not adding.\n\nNAME: The name of the textfile.\n\n This mode is used to remove banners from textfiles. It calculates a\n beginning and end of the original textfile, these marks can be changed \n by the user. The output file is the text between these marks.\n\n@EndNode\n\n@Node "DLDPrefs_HowToUse_Config" "The configuration mode."\n\n Usage:\nDLDCheck M=MODE/A,D=DATE/S,K=KEEP/S,P=PROT/S,A=ADD/S,AT=ADDT/S,S=SAFE/S,\nW=WILD/S,C=COMPARE/S,MAIN=MAINTENANCE/S,IKA=IKILLASK/S,IKF=IKILLFORCE/S,\nN=NAME/K,F=ADDFILE/K,CON=CONFIGFILE/K\n\n MODE = C\n      C Enables the configuration mode.\n\n Available options in the configuration mode.\n\nNAME: The name of the file to process.\n\nADDFILE:\n      The file to add using Addmode. This argument will be ignored when\n      other modes are used.\n\nCONFIGFILE:\n      Name of the configuration file.\n\n This mode can take a configuration file generated with @{"DLDConfig" link "DLDConfig"}\n and use it as a template. This should ease the use of DLDCheck.\n\n@Endnode \n\n@Node "DLDCheck_UsingWithDOpus" "Using DLDCheck with DirectoryOpus."\n\nI use 3 buttons and they are configured as follows\n\nThe killing button.\nName:  DLDCheck\nThe entry is: AmigaDOS    DLDChecker:DLDCheck MODE D KEEP SAFE WILD MAIN ADDT ADD IKA Name {f}\nFollowing flags are used:\n	-CD source\n	-Directory Opus to front\n	-Do all files\n	-Output window\nStack Size:   4000\nPriority:     0\nClose Delay:  -1\n\nThe showing button.\nName:  DLDShow\nThe entry is: AmigaDOS    DLDChecker:DLDCheck MODE S\nFollowing flags are used:\n	-Directory Opus to front\n	-No filename quote\n	-Output window\nStack Size:   4000\nPriority:     0\nClose Delay:  -1\n\nThe Textkilling button.\nName:  DLDCheckT\nThe entry is: AmigaDOS    DLDChecker:DLDCheck MODE T ADDT ADD Name {f}\nFollowing flags are used:\n	-CD source\n	-Directory Opus to front\n	-Do all files\n	-Output window\nStack Size:   4000\nPriority:     0\nClose Delay:  -1\n\n@EndNode\n\n@Node "DLDCheck_FuturePlans" "Future plans for DLDCheck"\n\n-Use with ZIP archives.\n-Improvement of the intelligent killroutines. Based on my increasing \n knowledge about Artificial Intelligence.\n-A homemade killroutine so DLDCheck has no need of LHA at all.\n-More Prefs.\n-Maintenance option improved so it works with dates.\n\n@EndNode\n\n@Node "DLDCheck_DataFiles" "Datafiles used with DLDCheck 4.0"\n\nDatafiles used with DLDCheck.\n\nENVARC:DLDCheck.Prefs\nDLDChecker:DLDBrainFile\nDLDChecker:Killbanners\nDLDChecker:Killbanners.addlist\nDLDChecker:TotalKill\n\nENVARC:DLDCheck.Prefs\n This file is the preferences file generated with DLDPrefs. This file\ncontains a lot of settings used by DLDCheck and all the utilities for\nDLDCheck.\n\nDLDChecker:DLDBrainFile\n This file contains brain info for the textkillmode, but also counters\nfor intelligent killmode.\n\nDLDChecker:Killbanners\n This file is the list used by DLDCheck. It contains all the banners, and\nthe counters if the maintenance option is used.\n\nDLDChecker:Killbanners.addlist\n This file contains the wildcard files such as "*.displayme". The file\nis added to the killbannerslist when DLDEdits WILDCARD option is used.\n\nDLDChecker:TotalKill\n This file contains the killsizes for DLDCheck and the internal accesses\ncounter used by the maintenance option.\n\n@EndNode\n\n******** Nodes for DLDEdit *****\n\n@Node "DLDEdit" "The DLDEdit program."\n\n    @{" History          " Link "DLDEdit_History"} History for DLDEdit.\n    @{" How to install   " Link "DLDEdit_HowToInstall"} How to install DLDEdit.\n    @{" How to Use       " Link "DLDEdit_HowToUse"} How to use DLDEdit.\n\n@Endnode\n\n@Node "DLDEdit_History" "History for DLDEdit."\n\nHistory for DLDEdit\n\nV1.0  -Delete double lines in a SORTED list. (Sort with e.g. CygnusED)\n      -Delete wildcard banners. Reason: WildCardkill is faster than LHA.\n\nV2.0  -Added: Template. Now you can enable each of the 3 options.\n       DOUBLE:      Delete double lines.\n       WILDCARD:    Delete wildcardnames.\n       MAINTENANCE: Delete "old" banners.      \n       See the @{"how to use" Link "DLDEdit_HowToUse"} section for more information.\n      -Bugfix: Wildcardkill deleted the last banner in the list.\n      -Added: Wildcardkill will remove wildcardfiles with wildcards\n       specified in DLDPrefs.\n      -Added: Now you can autoadd your own wildcardfiles. This is done\n       by entering the names in the Killbanners.addlist. Reason: Somebody\n       is adding banners called "<Archivename> From ...."\n      -Added: Maintenance option. This option is used to remove "old"\n       names from the killbanners file. You don''t have to worry about\n       deleting banners from the list. The intelligent killmode will find\n       them if they reappear.\n\n@Endnode\n\n@Node "DLDEdit_HowToInstall" "How to install DLDEdit."\n\nHow to install DLDEdit.\n\n -Just copy DLDEdit to any directory e.g. c:\n\n@EndNode\n\n@Node "DLDEdit_HowToUse" "How to use DLDEdit."\n\n DLDEdit is used to handle the killbanners list.\n\nUsage: DLDEdit D=DOUBLE/S,W=WILDCARD/S,M=MAINTENANCE/S,N=NAME/A\n\nDOUBLE: Delete double lines in a SORTED list. (Sort with e.g. CygnusED)\n\nWILDCARD: Delete wildcardnames. Wildcards to delete is specified in \n        @{"DLDPrefs" Link "DLDPrefs"}.\n\nMAINTENANCE: Delete "old" names. The number of accesses before a file\n        is deleted is specifiled in @{"DLDPrefs" Link "DLDPrefs"}.\n\nNAME:   Name of list. E.g. DLDChecker:Killbanners.\n\n@EndNode\n\n******** Nodes for DLDPrefs *****\n\n@Node "DLDPrefs" "The Preferences program."\n\n    When you start DLDPrefs it opens a window on you workbench screen.\n    This window has the following buttons. \n    Thanks goes to Karsten T. Niemeier, Dreamline Designs for coding the\n    preferences editor in C++.\n\n    @{" Keep        " Link "DLDPrefs_Keep"} Settings for the Keep option.\n    @{" Wildcard    " Link "DLDPrefs_Wildcard"} Settings for the wildcard killmode.\n    @{" Compare     " Link "DLDPrefs_Compare"} Settings for the compare killmode.\n    @{" Maintenance " Link "DLDPrefs_Maintenance"} Settings for the Maintenance option.\n    @{" Intelligent " Link "DLDPrefs_Intelligent"} Settings for the intelligent killmode.\n\n    + the usual prefs buttons and an about button.\n\n@Endnode\n\n@Node "DLDPrefs_Keep" "Settings for the Keep option."\n\nHere you can enter your own filecomment.\n\n@EndNode\n\n@Node "DLDPrefs_Wildcard" "Settings for the Wildcard killmode."\n\nHere you can add your own wildcards. This is done by selecting the "Add"\ngadget and enter the wildcard. \n\nThe "Del" gadget remove a wildcard from the listview.\n\n@EndNode\n\n@Node "DLDPrefs_Compare" "Setting for the compare killmode."\n\nThe compare killmode is improved much in DLDCheck 4.0.\n\nThe listview box called "Do not delete files with these extensions",\nthe "Add" and "del" gadgets is used to enter extensions. All files \ncalled <archivename><extension> will NOT be deleted.\n\nExample: You have entered ".Info", ".s", ".c", ".Doc" in the prefs.\n\nDLDCheck is now processing you banner called "test.lha". This archive\ncontain the following files.\n\n Test.s\n test.info\n test.ascii\n tEsT.c\n\nThe Compare killmode will only delete "test.ascii" because you have \nmarked the others extensions out in DLDPrefs.\n\nNOTE: Remember to name the extensions ".<extension>" not "<extension>"\n      Else DLDCheck will look for files called "testinfo" instead of \n      "test.info".\n\nThe checkbox called "Delete reversed archivenames." is used to enable\nthe reversed archivename kill. \n\nExample:\n -Original archivename "test.lha" \n -Reversed archivename "ahl.tset"\n\n@EndNode\n\n@Node "DLDPrefs_Maintenance" "Settings for the mainteance option."\n\nThis slidergadget is used to set the number of accesses before DLDEdit\nwill remove the bannername from the killbanners file.\n\nNOTE: DLDCheck will not remove names, but only update found banners.\n\n@EndNode\n\n@Node "DLDPrefs_Intelligent" "Settings for the intelligent killmode."\n\nThis window contains a number of bevelboxes. \n\nThe "check methods" bevelbox.\n -"Check filetype fast" is used to enable DLDChecks own filetype check.\n  This filetypechecker will look at the first 100 bytes of a file. This\n  is much faster than using FileID.library.\n -"Use FileID library" is used to enable filetype checking by\n  FileID.library. Use this in connection with fast filetype check and\n  you have a very efficient filetypechecker. The advantage of enabling\n  these filetype checkers is to make sure DLDCheck don''t start looking\n  in e.g. executeables.\n -"Check wordlength" is used to enable wordlength checking. Since banners\n  usually contains of very short words this checkmethod is used to sort \n  documents with long words out.\n -"Check compress ratio" will enable the ratio checking. Since textfiles\n  usually has high compress ratios you can use this to sort out files.\n  The advantage of this is to prevent DLDCheck to unpack files from the \n  archive to evaluate them. \n -"Check special words" is used to enable the wordchecking. In the\n  bevelbox below can you enter words for this checkmethod. The check-\n  method is used to evaluate the textfiles. See more below.\n\nThe "Define some limits" bevelbox.\n -"Minimum size" is used to set the minimum size of files to evaluate.\n -"Maximum size" is used to set the maximum size of files to evaluate.\n -"Show&Ask below" is used to set the size of files DLDCheck should \n  evaluate no matter what. The reason is that some files dosn''t contain\n  any data, but the filename is a banner. E.g. "DAIL+45XXXX0431" size 5\n  bytes.\n -"Ask files above" is used to set the limit between Banner/Not banner.\n -"Del files above" is used to set an "autoremove" limit. All files with\n  ASCIILogoCharPercentage(the displayed percentage) above this will\n  automatically be deleted. This is used to remove random-generated \n  bannernames.\n -"Minimum ratio" is used to set the minimum ratio for the checkmethod\n  "Check compress ratio".\n -"Avg. wordlength" is used to set the maximum average wordlength for\n  the "Check wordlength" checkmethod.\n\nThe "Misc" bevelbox.\n -"Count banners" enables the count option. When this option is set\n  DLDCheck will count accesses to IK, killed banners, removed banners and\n  autoremoved banners. If this option is set DLDChecks showmode will print\n  these counts.\n -"Remember largest word". When this is set the checkmethod \n  "Check wordlength" will store the largest wordlength for future checking.\n  DLDCheck will then only pass files with average wordlength 1 greater than\n  the largest wordlength.\n  If you not set this the checkmethod will only pass files with average\n  wordlength equal or lesser than the limit set in the "Avg. wordlength"\n  slidergadget in the "Define some limits" bevelbox.\n -"Check in subdirs". Search for banners in subdirs. \n\nThe "Special words" bevelbox.\n  The bevelbox contain 3 listviewboxes. These are used as the other\n  listviews. The 3 types of words is defined below.\n  NOTE: The evaluation version of DLDCheck 4.0 will handle the 3 types\n  as equals. In other words don''t enter anything in the low probability\n  list. \n\n -High probability: This type of words are ONLY found in banners.\n  The wordlength will be multiplied with 2 and added to the percentage.\n  Words in this group: boardnames, sysopnames, groupnames ect ect.\n\n -Medium probability: This type of words are most likely found in banners, \n  but could also be found in textfiles.\n  The wordlength will be added to the percentage.\n  Words in this group: Sysop, cosysop, wares, bbs, node, ect ect.\n\n -Low probability: This type of words are almost NEVER found in banners.\n  The wordlength will be multiplied with 2 and subtracted from the\n  percentage.\n  Words in this group: Assign, Printf, move.l, loadwb, path ect ect.\n\n@EndNode\n\n******** Nodes for DLDAdd *****\n\n@Node "DLDAdd" "The DLDAdd program."\n\n    @{" History          " Link "DLDAdd_History"} History for DLDAdd.\n    @{" How to install   " Link "DLDAdd_HowToInstall"} How to install DLDAdd.\n    @{" How to Use       " Link "DLDAdd_HowToUse"} How to use DLDAdd.\n    @{" Using with DOpus " Link "DLDAdd_UsingWithDOpus"} How to set you buttons in Opus.\n\n@Endnode\n\n@Node "DLDAdd_History" "Program History for DLDAdd."\n\nHistory for DLDAdd.\n\nV1.0  -Locates and add the selected name to list. Not released to public.\n\nV1.05 -Added: DLDAdd now checks the list for the name before adding\n      to prevent more than one entry.\n\nV1.1  -Added: Option to add to Killbanners.addlist.\n\n\nNOTE: You should always use "file" (Quotes), because some clever guys\n      use > at the begining of their bannernames so ReadArgs think\n      that it''s a redirection and it gets confused.\n\n\n@EndNode\n\n@Node "DLDAdd_HowToInstall" "How to install DLDAdd."\n\nHow to install DLDAdd.\n\n -Just copy DLDAdd to any directory e.g. c:\n\n@EndNode\n\n@Node "DLDAdd_HowToUse" "How to use DLDAdd."\n\nDLDAdd is used to add a bannername to the KillBanners list.\n\n Usage: DLDAdd A=ADDLIST/S,NAME/A\n\nADDLIST: Add the name to the killbanners.addlist as well. This will prevent\n      the file to be deleted if it consists any wildcards. You should only\n      use this option with names containing wildcards. E.G. Some adders\n      will add banners called "<ArchiveName> Passed <BoardName>".\n\nNAME: The name of the banner to add to the list.\n\n@EndNode\n\n@Node "DLDAdd_UsingWithDOpus" "How to use DLDAdd in DOpus."\n\nJust adding to the Killbanners list.\n\nThe DLDAdd button.\nName:  DLDAdd\nThe entry is: AmigaDOS    DLDChecker:DLDAdd {o}\nFollowing flags are used:\n	-Do all files\n	-Run asynchronously\n\nStack Size:   4000\nPriority:     0\nClose Delay:  0\n\nAdding to both "Killbanners" and "Killbanners.addlist".\n\nThe DLDAdd button.\nName:  DLDAdd W\nThe entry is: AmigaDOS    DLDChecker:DLDAdd ADDLIST {aEnter wildcard name.}\nFollowing flags are used:\n	-Run asynchronously\n\nStack Size:   4000\nPriority:     0\nClose Delay:  0\n\n@EndNode\n\n****** Nodes for DLDConfig ********\n\n@Node "DLDConfig" "The DLDConfig program."\n\n    @{" History          " Link "DLDConfig_History"} History for DLDConfig.\n    @{" How to install   " Link "DLDConfig_HowToInstall"} How to install DLDConfig.\n    @{" How to Use       " Link "DLDConfig_HowToUse"} How to use DLDConfig.\n\n@Endnode\n\n@Node "DLDConfig_History" "Program history for DLDConfig."\n\nV1.0	-First working version.\n\n@Endnode\n\n@Node "DLDConfig_HowToInstall" "How to Install DLDConfig."\n\nHow to Install DLDConfig.\n\n -Just copy DLDConfig to any directory.\n\n@Endnode\n\n@Node "DLDConfig_HowToUse" "How to use DLDConfig."\n\nHow to use DLDConfig.\n\nThis program is used to generate a small configuration-file. This file\ncontains the same options as you can specify in the template.\nInstead of typing all the options in the template you just execute\nDLDConfig, set the options, click the "save" gadget and enter a filename.\nWhen executing DLDCheck you just enter this in the shell.\n\nDLDCheck mode c name <Archivename> Configfile <Configfilename>\n\nDLDCheck will now load the options from <Configfilename> and carry on\nwith these options.\n\n@EndNode\n','\n',char(10)),NULL,'auto-added',60855,3,0,NULL,NULL,'dldchk4e','scan',1780048474);
INSERT INTO door_catalog VALUES('dldiz16','DLDIZ16.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DLDIZ16.LHA','DLDiz','XIM','DLDiz',NULL,'Rasmus',NULL,'*    D R E A M L I N E   D E S I G N S    * *             P R E S E N T S             * *   DLDiz v1.6 coded by Rasmus K Ursem.   *',replace('*******************************************\n*    D R E A M L I N E   D E S I G N S    *\n*             P R E S E N T S             *\n*   DLDiz v1.6 coded by Rasmus K Ursem.   *\n*                                         *\n* This small program can extract and show *\n* File_ID.Diz from textfiles,DMS, LHA and *\n*    LZX archives. Now DLDiz supports     *\n*  filelist  generating for Daydream and  *\n*  AmiExpress BBS. This can be used as a  *\n* local upload tool.                      *\n*                       Rasmus K Ursem/DLD*\n*******************************************\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                                                .------''\n             `------------------------------------------------''\n','\n',char(10)),NULL,'auto-added',14512,6,0,NULL,NULL,'dldiz16','scan',1780048474);
INSERT INTO door_catalog VALUES('dldiz17','DLDIZ17.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DLDIZ17.LHA','DLDiz','XIM','DLDiz',NULL,'Rasmus',NULL,'*    D R E A M L I N E   D E S I G N S    * *             P R E S E N T S             * *   DLDiz v1.7 coded by Rasmus K Ursem.   *',replace('*******************************************\n*    D R E A M L I N E   D E S I G N S    *\n*             P R E S E N T S             *\n*   DLDiz v1.7 coded by Rasmus K Ursem.   *\n*                                         *\n*    This program can extract and show    *\n* File_ID.Diz from textfiles,DMS, LHA and *\n*  LZX archives. DLDiz supports filelist  *\n* generating for Daydream  and AmiExpress *\n* BBS. This can be used as a local upload *\n* tool. Bugfixed version.                 *\n*                       Rasmus K Ursem/DLD*\n*******************************************\n','\n',char(10)),'DLDiz.doc',replace('\nWelcome to DLDiz v1.7 ©Copyright 1995 by Rasmus K. Ursem, Dreamline Designs.\n                       Release Date: 08-Apr-95\n\nIntroduction:\n DLDiz is a small utility to extract and show "file_id.diz" from Textfiles, \nLHA and DMS-archives. It can also create filelists from the file_id.diz, this\nversion can supports 2 BBS types (Daydream and AmiExpress). Using this option\nyou have the fastest local upload tool. More about this later.\nDLDiz now supports LZX.\n\nThis is BUNGYJUMPWARE. If you like it you should go bungyjumping.\n\nDisclaimer:\nI take no responsibility for any lack of data or currupted archives. \n(or any bungycrashes...) DLDiz is checked in everyday use and has shown no\nerrors.\n\nNeeded programs:\nLHA placed in the path.\nLZX placed in the path.\n\nReason to code: I used Whadiz 1.2 from nocTurne deSign/RefLeX, but this \nutility has a major bug. It dosn''t unlock files when there isn''t any \n"file_Id.diz" file in the archive. On top of that it dosn''t unlock dirs.\nVery annoying because you cannot delete these files and dirs.\nSometimes a list of the file_id.diz''s is also very useful, so DLDiz can\nnow create such a list.\n\nUsage:\nDLDiz NAME/K/M,F=FILELIST/S,Q=QUIET/S,NH=NOHEADER/S,LT=LISTTYPE/K,LN=LISTNAME/K,\nED=EDITOR/K\n\nNAME      is the name of the archive.\nFILELIST  is used to enable the create filelist. A file called \n          "Filelist_created_by_DLDiz" is placed in ram: \nQUIET     will disable all output but errormessages from DLDiz.\nNOHEADER  will disable the header output. Only the File_ID.Diz will be \n          displayed.\nLISTTYPE  is the type of the list you want to generate.\n          Currently supported listtypes is:\n          N     This result in a standard list with no sizes, dates ect.\n          A     Generates a list for AmiExpress BBS.\n          D     Generates a list for Daydream BBS.\n          If this is not found in the commandline, DLDiz will generate a \n          standard filelist like version 1.5 Did.\nLISTNAME  An optional listname. The File_ID.DIZ from the file, will be added\n          to this list specified here. \n          If this is not found in the commandline, DLDiz will add to the\n          standard filelist in ram:\nEDITOR    Editor to use if no File_ID.Diz is found. For the moment this dosn''t\n          work in DMS-Archives because DMS can''t add a File_ID.Diz without\n          repacking the whole file. :(\n\nHistory\nV1.0	-First working version.\n\nV1.1	-Improved: DMS extraction replaced with own search routines.\n	-Added: Search in textfiles. (Or any other file where the\n	 file_id.diz is between a begin and end file_id.diz line.\n	-Added: Buffermode so you can get the file_id.diz even if you\n	 havn''t enough memory free to load the whole file.\n\nV1.2	-Bugfix: V1.1 had a minor bug. (Colorflash when no file_id.diz was\n	 found.) A friend of mine uploaded v1.1 without asking me. :-(\n\nV1.3	-Bugfix: Major fuckup in the DMS-searching.\n\nV1.4    -Added: Option to create filelist.\n        -Added: Quietmode.\n\nV1.5    -Bugfix: DLDiz didn''t delete the t:File_ID.Diz when a corrupted\n         archive was processed.\n        -Added: If a lha fails (corrupted data) DLDiz print a message on\n         the screen or in the filelist.\n\nV1.6    -Added: LZX support.\n        -Added: Special list generating for AmiExpress and Daydream BBS.\n        -Improved: DLDiz can add to a userselected list instead of\n         ram:Filelist_created_by_DLDiz.\n\nV1.7    -Bugfix: V1.6 would crash on textfiles greater than 65535 bytes.(Ups!)\n        -Bugfix: DMS search-routine couldn''t find the Diz if it was placed\n         as the last "hunk".\n        -Bugfix: The listgenerator for Daydream and AmiExpress would create\n         "funny" lists if the Diz wasn''t ending on a CR. ($0a)\n        -Added: If no file_ID.Diz is found DLDiz can open a userselected \n         editor and add the File_ID.Diz to the archive. NOTE: This dosn''t\n         work on DMS-archives because DMS cannot just add File_ID.Diz-info.\n         You have to unpack the file and repack it with the Diztext option.\n         (Crap?)\n        -Added: NoHeader option, this will prevent the usual header text from\n         being displayed. Now you can use DLDiz in connection with upload on \n         Diz-supporting BBS-systems.\n        -Added: Rexxscript for use with DOpus. Thanks goes to Morten K. \n         Andersen for being our Arexx-wizard.\n        -Changed: In the privious versions you had to type DLDiz Name <File>\n         Now added a /M so you just have to type DLDiz <file>.\n        -Improved: The listgenerating-routine now adjust the width of the \n         file_id.diz.          \n\nUsing the editor option.\n\nExample:\nDLDiz test.lha f ed="ced -keepio"\n\nThis will call DLDiz, and if test.lha dosn''t have any File_ID.Diz the editor\nspecicified in Ed= will be executed. In the above example, DLDiz will execute \nthe following command.\n\nced -keepio t:File_ID.Diz\n\nIf you use some wierd editor that must have the filename as the first argument \nyou can freely create a script to execute your editor, just remember to set the\nS (Script) bit, and keep in mind that DLDiz tries to load the File_ID.Diz from\nT:File_ID.Diz.\n\nexample of script for use with CygnusEd\n\n-------------- Cut ---------------\n\nstack  8000\nCed t:File_ID.Diz -keepio\n\n-------------- Cut ---------------\n\n\n\nUsing with DOpus.\n\n*** Normal showing ***\n\nAmigaDOS    c:DLDiz NAME {f}\n\nStack:          4000\nPriority:       0\nClose Delay:    -1\n\nFlags:\nDirectory Opus to front\nDo all files\nOutput window\n\n\n*** Generating a list in ram: ***\n\nAmigaDOS    c:DLDiz NAME {f} F Q\n\nStack:          4000\nPriority:       0\nClose Delay:    -1\n\nFlags:\nDirectory Opus to front\nDo all files\nOutput window\n\n*** Local uploading on Daydream/AmiExpress ***\n\nAmigaDOS    c:DLDiz NAME {f} F Q LN {Rf} LT D\n                                     \/     \__Specifies Listtype. \n                                      \        Here Daydream. Use A for AmiX\n                                       \\n                                        \______Tells Dopus to pop a filereq.\n                                               Here ou select the list you\n                                               want to add to.\nStack:          4000\nPriority:       0\nClose Delay:    -1\n\nFlags:\nDirectory Opus to front\nDo all files\nOutput window\n\nLocal upload on Daydream and AmiExpress.\nIf you have Dopus do as described just above, else do this:\n\nc:DLDiz NAME <filename> F Q LN <Listname> LT <Listtype: D = Daydream, A = AmiExpress>\n\n1STNOTE: The archive/file MUST have a FILE_ID.Diz, else the Discription will be\n         "File_ID.Diz NOT found!"\n2NDNOTE: You must copy the files to the path according to the selected list.\n3RDNOTE: Remember these BBS-programs MUST have the names in uppercase and \n         the filename MUST support the 8.3 (PeeCee) standard.\n\n*** Using the arrex script with DOpus ***\n\nThis script is used for local uploading/creation of filelists. Use these \nsettings:\n\nARexx       rexx:dopus/DLDListgenerator.dopus\n\nStack:          9000\nPriority:       0\nClose Delay:    0\n\nFlags:\nRun asynchronously\n\n\nHow to contact the author.\nSnail mail (@, -mail)\n\n Rasmus K. Ursem\n Vittenvej 26\n 8382 Hinnerup\n Denmark\n Phone +45 86910058\n\n FidoNet:	2:238/28.10\n AmigaNet:	39:140/109.10\n HOANet:	10:2/9.10\n\nOr Call this board:\n\nStargate, Dreamline Designs BBS Phone: +4586910058 Hours: 21:00-09:00\nSysop: Rasmus K. Ursem, Dreamline Designs.\n\nSome Notes about this BBS:\nAll releases from Dreamline Designs is online, even the winner-demo from \nthe dealer-demo-competition at TP3 (22MB). Furthermore I am trying to build a\ncollection of coding utilities and public sources such as chunkytoplanar-\nroutines and other demo-routines/utilities-sources.\n\nOther Utils coded by me:\nDLDCheck:	The *ultimate* stripper, with intelligent killmode to strip\n		randomgenerated adds, CRC-Checking(=ANY banner can be deleted).\n                latest release is V4.1.\nDLDBoot:	HD-Bootprogram to wait for old slow hds.\nDLDInfo:	Improvement to CBMs info.\nDLDModRe:	Rename (unpacked) Protracker modules to the original name.\n','\n',char(10)),NULL,'auto-added',17794,2,0,NULL,NULL,'dldiz17','scan',1780048474);
INSERT INTO door_catalog VALUES('dlg_edit','DLG-EDIT.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DLG-EDIT.LHA','DLG-Edit','XIM','DLG-Edit',NULL,NULL,'DLG','(beta version 39.121) Requires a large Workbench screen (high-res laced) to use the user editor.',replace('DLG-Edit 39.121, DLG SysOp''s GUI config editor.\n(beta version 39.121)\nRequires a large Workbench screen (high-res laced) to use the user editor.\n\n','\n',char(10)),'DLG-Edit.txt',replace('This is a beta version of DLG-Edit (rev 39.545)\n\nWhat is it? It''s a simple GUI SysOp control centre for DLG.\n\nIt is also freely distributable.\n\nWhat do you need?\n\n  * A functional DLG system\n\n  * A  large(ish)   Workbench   screen,   I''ve   designed   it   using\n    NTSC:High-res  Laced  (720x480 on my setup) and some of the editor\n    windows only just about fit onto it!\n    \n  * An iron constitution (if you insist on using save...)\n\nWhy do you need it?\n\nThe normal SysOp control for DLG is rather unfriendly, requiring the SysOp\nto  first  log  on  locally,  and then go through a series of menus before\nreaching the options that he or she wants to get at.\n\nThis would be fine if all DLG SysOps  only  ever  managed  things  from  a\nremote location, but it''s not very nice for local use, especially when the\npoor SysOp has a nice 17" monitor! Who wants to be reading  terminal  type\nand pressing keys when you could be pointing and clicking...\n\nSince this a beta version, these are beta docs (but they will  get  ''beta''\n(argh!)) and as such are pretty sparse...\n\nAnd yes, I do know about TRW, but the author doesn''t  seem  to  have  done\nmuch  on  it  recently,  and  we  needed something usable here at Nemesis''\nDungeon when the news areas were being set up.\n\n\nGetting started:\n~~~~~~~~~~~~~~~~\n\n    Edit the tooltypes of the  icon  to  suit  your  preferences.  You\n    should  also set the user levels that you use on your system. This\n    is simple enough, just set the tooltype with  a  list  of  levels,\n    i.e.\n\n    USERLEVELS=1,10,50,100\n\n    Setting the font name  to  a  non-existent  font  will  cause  the\n    program  to  bring  up  an  ASL  font  requester. Some people have\n    reported getting squiggly lines instead of a  font.  I  haven''t  a\n    clue  what they''re talking about! If this happens please detail it\n    as accurately as possible (a screen snap would be nice...)\n\n    If DLG-Edit is making windows too big or too small  for  the  font\n    you''ve  chosen,  then  you  can  override  the  font width that is\n    calculated for proportional fonts with the FONTXSIZE parameter.  7\n    seems to work best for 11pt Helvetica.\n\n    You can also specify a public screen to run the program on. This s\n    useful  if  you run a non-laced workbench, but your DLGMail screen\n    is big enough to hold the user editor window.\n\n    Double click on the icon to start, or start DLG-Edit  from  a  CLI\n    (if  you  are  running from the CLI, you must still make sure that\n    you have the tooltypes defined). You should get  a  small  control\n    panel  opening  up  on  your  Workbench  screen,  with buttons for\n    managing file areas, message areas, or users.\n\n    Once you get into these particular sections everything  should  be\n    self   explanatory,   or   suitably  explained  by  the  DLG  docs\n    themselves.\n\n\nImporting areas:\n~~~~~~~~~~~~~~~~\n\nIf you want to try importing areas, then I suppose it would help if I\ntold you the format of the source text files...\n\n    The format for file area importing is:\n\n        number\n        name\n        alternate path <optional>\n        (blank line)\n        number\n        name\n        alternate path <optional>\n        (blank line)\n        etc.\n\n    As you can see, each area definition is separated by a blank line,\n    there  should  be  no blank line at the very end (i.e., the cursor\n    shouldn''t be able to move below the last line of the file) Take  a\n    look  at  "newfileareas.import.txt" in the archive for an example.\n    You''ll notice that if you have "0" as the  area  number,  it  will\n    increment by 1 over the last imported area number.\n\n    The format for message area importing is similar:\n\n        number\n        name\n        origin/newsgroup (optional)\n        (blank line)\n        number\n        name\n        origin/newsgroup (optional)\n        (blank line)\n        etc.\n\n\nIMPORTANT:\n\n    The access levels and flags of the imported  areas  are  inherited\n    from  the  area  that  was currently highlighted when the "Import"\n    button was pressed! Make sure that if  you  are  importing  Usenet\n    news  areas and ordinary areas in the same import, that you select\n    or unselect the "USENET" flag for the appropriate areas.\n\n\n\nLimitations:\n~~~~~~~~~~~~\n\nAs you may notice, some of the buttons aren''t enabled  yet,  most  notably\nthe  global  options  for the user editor, and the user-access options for\nthe area editors.\n\nIn the user editor, you can edit the user''s name, but this will never  get\nchanged  (since  it  would  require  renaming the directory). I''m not sure\nwhether to keep this as an editable option or not, tell me  if  you  would\nlike  to  be  able  to change the user''s name and have DLG-Edit rename the\nmatching user directory in response to this.\n\nSnoopDos users among you will probably have noticed that the way  DLG-Edit\nmanipulates file and message area directories is by writing a script in T:\nthat uses DOS commands to delete, rename etc. Have no fear, this  will  be\ntidied  up  and  made  an  integral part of the program in the future, but\nuntil I write some suitable code for  providing  progress  displays,  then\nscripts files is how it''s done.\n\n\nFuture:\n~~~~~~~\n\nI hope to write editor sections for other aspects of the BBS system,  like\nthe computer types, archivers, character sets etc.\n\n\nWARNING!\n********\n\n    If you have a backup of your system, and/or are quite prepared for\n    the possibility that something silly may happen then you can press\n    any of the "SAVE" buttons, otherwise EXCERCISE CONTROL  OVER  YOUR\n    FINGERS!  I''ve  tried to eliminate possible disasters, but I''m not\n    omniscient.\n\n\n                                                    :\n                                                  .-O\n                                               .O#0#@O.\n                :8   ..                       +@= =8 -0\n                @-   oO                      0O   @:  o-\n               @=    O-                     O:   +o   O:\n              0o    .8                      =    @. :.@\n             o0     8.                          =O :o8-               8=\n            -@.    +o           -+           .= @: +0+\n            @.    :0             :          =8::8  @=\n          .@.    .@.                       O+  8:+@O\n         :@o     0:  +o                    8  :#O-o=     .+oo.   +=\n        :##O    0:  o#o                    0-+@o  0.0o  +0O##:  =0@   -oo-\n       =0#+oo .0-  -#O   +.   -0#-:+O#@    -+-@  .08o8- 0=#O#+.o0 OOO@0=+o\n      0o8-  +00  .o#=    #+ -08..oo=.        o+  =#0  0=#O.0+o8-   ::\n   :O@==O   O@-  -+8    O8@00-              .@.  o@.  -OO@@+\n   ++  @  :0:.0.   8 .+@+ :.                oo   :.\n      +O.oo.  .0:  =8O+                     @:\n     :O8O:     .0-                         +O\n    :0           -Oo+-                     #.\n    8-                                     +\n   -0\n   @-\n  8-\n +o\n                                                                                \n\n    Kevin Phair.       fidonet: 2:263/150.6\n                      Internet: [email removed]\n                                [email removed]\n\n\n    Today''s Date: 30-Jan-1995\n                                                                                \n\n','\n',char(10)),NULL,'auto-added',35756,1,0,NULL,NULL,'dlg_edit','scan',1780048474);
INSERT INTO door_catalog VALUES('dlm_hl11','DLM-HL11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DLM-HL11.LHA',NULL,'XIM','__/\____________________/\____\   /_/\',NULL,'DELTAFORCE/DLM!','DLM','/    \  ___/  /___/     /___/  /  /    \ /  /  / ___/  /\  /  \  /   /  /  /  /  /\ /____ /___ /_____\/__ /\/__ /____ /  /__!__\',replace('   __/\____________________/\____\   /_/\   \n  /    \  ___/  /___/     /___/  /  /    \  \n /  /  / ___/  /\  /  \  /   /  /  /  /  /\ \n/____ /___ /_____\/__ /\/__ /____ /  /__!__\\n- --\/ - \/ --- \/ -\/--- \/ ---\/___\ -í f!\n[-------[ DLM/X-pression presents ]--------]\n:                                          :\n.         h Y D R A L U X  1 . 1 o         :\n. n.o.w. includes powerful FREE-DL option! .\n:  defines as many diff. lines as u want!  .\n:....::: created by DELTAFORCE/DLM! :::....:\n','\n',char(10)),'hYDRALUX110.doc',replace('\n                      hYDRALUX! v1.10 - documentation\n                  -------------------------------------\n\n\n                   U P D A T E - I N F O R M A T I O N\n\n     WHAT''s NEW? hYDRALUX got a new FREE_DL-Tool included and a minor\n     bug-fix was made! In some cases the last conf of the set wasn''t \n     shown afzter selecting "divert". Now it works 100% !\n\n\n1. INTRODUCTION\n\nthank you for purchasing hYDRALUX! by DELTAFORCE/DLM/X-pression! You now\nown a powerful tool that makes the great hydra protocol more powerful than\never! Unfortunately hydra became not so popular as it should! One of the\nreasons is shurely the lack of a good terminal-program that supports hydra,\nbut another thing is that hydra does only work within ONE conference. To\nmake it short: uploading amiga-stuff while leeching amiga-stuff is shurely\n"cool" for most of the local-isdn-lamers, but it is simply LAME for REAL\ntraders! So hYDRALUX! lets u leech SNES-Stuff while uploading the newest\namiga-major, or u can upload your whole daily directory into one confe-\nrence and afterwards you can divert every file in another conference!\n\n\n2. HOW DOES THIS MASTERPIECE WORK?\n\nhYDRALUX! is called via an EXAMINEx.info-command! The user is asked if he\nwants to divert the actual file into the default-conference, or in another\nconference, or all files into the default conference or all files into\nanother conference. Now hYDRALUX! changes the UL-PATH (invisible for the\nuser of course) and copies the file(s) from the playpen into the selected\nconference. That''s it!!!\n\n\n3. SYSTEM REQUIREMENTS\n\nTo make hYDRALUX! work 100%, your system must perform some minor require-\nments:\n         - there must be the command "copy" in your c:-directory!\n         - the tooltype ULPATH.1 MUST(!) describe the real upload-directory-\n           path for the conference. So if you have defined more than one\n           ULPATH-Tooltypes, but the real path into ULPATH.1 !!! In most\n           cases there will be just one directory anyway!\n\nthat''s it! So your system does not fit this requirements you should fuck\noff!\n\n\n4. LHA-PACK CONTENTS!\n\nyour lha-pack sould contain the following contents.\n\n\n               - hYDRALUX.x\n               - EXAMINE4.info\n               - CLEAR_HL.x\n               - CLEAR_HL.info\n               - SMF.x\n               - SMF.info\n               - hYDRALUX110.doc\n\n\n5. INSTALLATION\n\ncreate a directory "DOORS:HYDRALUX!" (dont forget the "!"). Copy the files\n"HYDRALUX.x",  "CLEAR_HL.x" and "SMF.x" into this directory.\ncopy "CLEAR_HL.info" and "SMF.info" into BBS:COMMANDS/BBSCMD\nand the "EXAMINE4.info" into BBS:COMMANDS/SYSCMD.\n\nNow you have to rename the EXAMINE4.info for your BBS-Configuration. If you\nuse rOCK lOBTSER and bREAK dA lINE, these 2 tools must be called AFTER(!)\nhYDRALUX! This is very important! Otherwise rOCK lOBSTER tries to check for\ndupes in the original conference instead of the new conference where the\nfile is diverted to! And if break da line drops the carrier before the user\ncould make any selsction concerning conferences, the tool is userless!!!\n\nhere is a little example how your EXAMINE-Setup could look like:\n\n                      EXAMINE.info        FileID and DELTA-Sent\n                      EXAMINE1.info       sASSY\n                      EXAMINE2.info       hYDRALUX\n                      EXAMINE3.info       bREAK dA lINE\n                      EXAMINE4.info       rOCK lOBSTER\n\nthis should help you finding the right place for hYDRALUX!!!\nthen take the file "UPLOADMSG.TXT", which is in EVERY conference, and put\nthe following MCI-command into the text: "~CC_CLEAR_HL" !!! You must\nput it in EVERY Uploadmessage.txt, also of the newUsers and the sysop-con-\nferences, otherwise the tool won''t work correct!\nTo let the FREE_DL-Option work, you must call the SMF.x tool via EVERY(!)\n(which means E V E R Y!) download-screen ("DOWNLOADMSG.TXT" in every conf)\nSO simply put in " ~CC_SMF " and don''t forget the ~ at the top of the screen!\n\n\n6. FREE-DL CONFIGURATION\n\nIt''s really simple! Jist take your CED (or another text-edit) and open the\nfile "DOORS:hYDRALUX!/FREE_DL.CONFIG". It could look like this\n\n              ----------------- [ BEGINNING ] -------------------\n; FIRST LINE: PATTERN FOR FREE_DL FILE!\n; SECOND LINE: FREE_DL COMMENT!\nDLM-*\n!! FREE DOWNLOAD !!\nDLM_*\n!! LEECH IT NOW! !!\n               ----------------- [ E N D ] -------------------\n\nAs u see the sheme is simple: the first 2 lines are just for explanation,\nbut DON''T remove them, otherwise the tool won''t work correct! \nIt''s a two-line-principle: the first line describes the beginning of the\nfile (it''s fully wildcard-supported, u can use "*", "?" and "#"), the second\nline is the FREE-DL-MESSAGE which will be shown under the file!! \nThis list can be as long as u want, so u can create different messages for\ndifferent groups.\n\nIN SHORT: SMF.info must be called from the DOWNLOADMSG.TXT\n          CLEAR_HL.info miust be called from the UPLOADMSG.TXT\n\n\n7. ADDITIONAL NOTES\n\nhYDRALUX changes some conference-parameters! If u think something went to-\ntally wrong, just type "J [confnr]" and everything is back at default!\n\nafter every call hYDRALUX removes the file from the default upload-direc-\ntory if the file has been diverted into another conference! So there is\nALWAYS O-N-E file in the default directory remaining which has been diver-\nted last! So don''t panic, this will be removed the next time hYDRALUX is\ncalled!\n\nif you have diverted all your upload files into another conference and you\ntype "N T" or "N T U" or something similar, all diverted files will appear\nalso in the filelisting of the default conference! This is a fault of /X,\nNOT of hYDRALUX! Just join the conference again and u''ll see that the files\nwere NEVER in the default! There are only in the diverted conference!\nSo don''t mind about this little effect!\n\n\n                                          15-01-95, DELTAFORCE/DLM\n\n\ngreetings go 2 (no special order): g.e.m, new sensation, ghandy,\nmr.vain, guliver, dalai lama, zion, x-man, mario, skylark, l.a.style,\ndr.poole, yankee rose, sasha, malcom, j.walker, d-siya, arch-magi, popy\nand all i forgot!\n\nspecial greetinx go to SHADOWER!\n\nPLEASE CONTACT ME FOR S U G G E S T I O N S or "B-U-G  R-E-P-O-R-T-S" at\nMEN-TEL BBS (DLM GHQ) or MAXIMUM ROCK''n''ROLL! Also if you are interested in\nthe complete DLM/X-pression Tool-collection! \n\n','\n',char(10)),NULL,NULL,37221,6,0,NULL,NULL,NULL,'scan',1780048474);
INSERT INTO door_catalog VALUES('dlm_hlux','DLM-HLUX.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DLM-HLUX.LHA',NULL,'XIM','hYDRALUX.x',NULL,'DELTAFORCE/DLM','DLM','/    \  ___/  /___/     /___/  /  /    \ /  /  / ___/  /\  /  \  /   /  /  /  /  /\ /____ /___ /_____\/__ /\/__ /____ /  /__!__\',replace('   __/\____________________/\____\   /_/\   \n  /    \  ___/  /___/     /___/  /  /    \  \n /  /  / ___/  /\  /  \  /   /  /  /  /  /\ \n/____ /___ /_____\/__ /\/__ /____ /  /__!__\\n- --\/ - \/ --- \/ -\/--- \/ ---\/___\ -í f!\n+-------( DLM /X-pression presents )-------+\n:          h Y D R A L U X  1.00           :\n:  let''s u use the HYDRA-protocol between  :\n:  all conferences. no problem to upload   .\n:     amiga-stuff while leeching SNES!     .\n: >> coded by DELTAFORCE/DLM in pure C <<  .\n+------------------------------------------+\n','\n',char(10)),'hYDRALUX!.doc',replace('\n                       hYDRALUX! v1.00 - documentation\n           ------------------------------------------------------\n\n1. INTRODUCTION\n----------------\n\nthank you for purchasing hYDRALUX! by DELTAFORCE/DLM/X-pression! You now\nown a powerful tool that makes the great hydra protocol more powerful than\never! Unfortunately hydra became not so popular as it should! One of the\nreasons is shurely the lack of a good terminal-program that supports hydra,\nbut another thing is that hydra does only work within ONE conference. To\nmake it short: uploading amiga-stuff while leeching amiga-stuff is shurely\n"cool" for most of the local-isdn-lamers, but it is simply LAME for REAL\ntraders! So hYDRALUX! lets u leech SNES-Stuff while uploading the newest\namiga-major, or u can upload your whole daily directory into one confe-\nrence and afterwards you can divert every file in another conference!\n\n\n2. HOW DOES THIS MASTERPIECE WORK?\n-----------------------------------\n\nhYDRALUX! is called via an EXAMINEx.info-command! The user is asked if he\nwants to divert the actual file into the default-conference, or in another\nconference, or all files into the default conference or all files into\nanother conference. Now hYDRALUX! changes the UL-PATH (invisible for the\nuser of course) and copies the file(s) from the playpen into the selected\nconference. That''s it!!!\n\n\n3. SYSTEM REQUIREMENTS\n-----------------------\n\nTo make hYDRALUX! work 100%, your system must perform some minor require-\nments:\n         - there must be the command "copy" in your c:-directory!\n\n         - the tooltype ULPATH.1 MUST(!) describe the real upload-directory-\n           path for the conference. So if you have defined more than one\n           ULPATH-Tooltypes, but the real path into ULPATH.1 !!! In most\n           cases there will be just one directory anyway!\n\nthat''s it! So your system does not fit this requirements you should fuck\noff!\n\n\n4. LHA-PACK CONTENTS!\n---------------------\n\nyour lha-pack sould contain the following contents.\n\n               - hYDRALUX.x\n               - EXAMINE4.info\n               - CLEAR_HL.x\n               - CLEAR_HL.info\n               - hLYDRALUX!.DOC\n\n\n5. INSTALLATION\n---------------\n\ncreate a directory "DOORS:HYDRALUX!" (dont forget the "!"). Copy the files\n"HYDRALUX.x" and "CLEAR_HL.x" into this directory.\ncopy "CLEAR_HL.info" into BBS:COMMANDS/BBSCMD and the "EXAMINE4.info" into\nBBS:COMMANDS/SYSCMD.\n\nNow you have to rename the EXAMINE4.info for your BBS-Configuration. If you\nuse rOCK lOBTSER and bREAK dA lINE, these 2 tools must be called AFTER(!)\nhYDRALUX! This is very important! Otherwise rOCK lOBSTER tries to check for\ndupes in the original conference instead of the new conference where the\nfile is diverted to! And if break da line drops the carrier before the user\ncould make any selsction concerning conferences, the tool is userless!!!\n\nhere is a little example how your EXAMINE-Setup could look like:\n\n                      EXAMINE.info        FileID and DELTA-Sent\n                      EXAMINE1.info       sASSY\n                      EXAMINE2.info       hYDRALUX\n                      EXAMINE3.info       bREAK dA lINE\n                      EXAMINE4.info       rOCK lOBSTER\n\nthis should help you finding the right place for hYDRALUX!!!\nthen take the file "UPLOADMSG.TXT", which is in EVERY conference, and put\nthe following MCI-command into the text: "~CC_CLEAR_HL" !!! You must\nput it in EVERY Uploadmessage.txt, also of the newUsers and the sysop-con-\nferences, otherwise the tool won''t work correct!\n\nDon''t forget to position your dupe-check AFTER hYDRALUX!; the dupes should be\nchecked into the final conference and not in the default conference! \n\n\n6. ADDITIONAL NOTES\n-------------------\n\nhYDRALUX changes some conference-parameters! If u think something went to-\ntally wrong, just type "J [confnr]" and everything is back at default!\nafter every call hYDRALUX removes the file from the default upload-direc-\ntory if the file has been diverted into another conference! So there is\nALWAYS O-N-E file in the default directory remaining which has been diver-\nted last! So don''t panic, this will be removed the next time hYDRALUX is\ncalled!\n\nif you have diverted all your upload files into another conference and you\ntype "N T" or "N T U" or something similar, all diverted files will appear\nalso in the filelisting of the default conference! This is a fault of /X,\nNOT of hYDRALUX! Just join the conference again and u''ll see that the files\nwere NEVER in the default! There are only in the diverted conference!\nSo don''t mind about this little effect!\n\n\n                                   01-12-95, DELTAFORCE/DLM\n\n\nfor further informations or more tools contact me at MEN-TEL BBS.\n\n                        <<<================>>>\n\ngreetings go 2 (no special order): g.e.m, new sensation, ghandy, cheech,\nmAZ!, mr.vain, guliver, dalai lama, zion, x-man, mario, skylark, l.a.style,\ndr.poole, yankee rose, sasha, malcom, j.walker, d-siya, arch-magi,\npopy and all i forgot!\n\nspecial greetinx go to SHADOWER! i''ll call ASAP! 4 SHURE!!!\n\nto dr.dre: if you also try to recode this tool like u did with "sassy!\nand "deltasent!": fuck off or make it better than the last times!\nit''s ok to remake my tools coz'' your obviously to lame for own ideas, but\nnevertheless  please try to reach some standard!\n','\n',char(10)),NULL,'auto-added',22365,2,0,NULL,NULL,'dlm_hlux','scan',1780048474);
INSERT INTO door_catalog VALUES('dlt_af12','DLT-AF12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DLT-AF12.LHA','Autofree','XIM','Autofree',NULL,NULL,'DLT','CR/\ZE aND!       /\_\ __\ __________________  \/_/  ____________/\____ ____ _ / __  /  /_____  / ____/  /  /·  _ /',replace('                     __    ____  _     _\n  CR/\ZE aND!       /\_\ __\\n__________________  \/_/  ____________/\____\n ____ _ / __  /  /_____  / ____/  /  /·  _ /\n /  / //  ___/  /  /   \/  /  /     //   \/\n/____ /_____/_____/_____\___ /__/__/______\.\nSk¡n\/---------- PRESENTS -\/--------------+\n(« aUTO fREE v1.2 - uPDATE © nIKE/cRZ^dLT »)\n+------------------------------------------+\n','\n',char(10)),'Autofree.Doc',replace('    ___________   ____________   _________      ___________    _____________\n.___\___      /_._\_____     /___\______  \ ____\_____    /____\___        /\n|      /_____/  |    _|/   _/__      _____ \      _______/____ ___/       /_\n|    _/         |    \        /      \      \     \          / __________/  \\n|_______________|_____\      /________\      \______________/________________\\n-mNt/aC!               \____/          \______\\n\n                                     &\n                  _     _ ___       ___\n                            /_  __ /__/\ _\n _ ___________________________     \__\/    _____________¦_________/\______\n ________   _ /  ___    /o   /___________  /·  ______/   |   \ _      o _ /\n __/    /   //    _____//   /    /       \//   /    /         \/       \\/\n  /________ /________ /_________/_________\_______ /_____|_____\_________\\n  \_______\/\_______\/\_________\____ ____/______\/\_____¦_____/_________/\n           \/        \/              Y.           \/     ·            Sk¡n\n                                     :o\n                                    +.\n\n                       Presents another /X^S!X Door\n\n                      -^(· AutoFree v1.2 by Nike ·)^-\n\nDescription.\n============\nMakes files Free download automatically.\nByteKillHandler replacement.\n\nFeatures:\n=========\n1. It checks the file that a user uploads if it starts on the same thing\n   as in the config file.\n   In the configfile you can enter as many names and the names can be of\n   unlimited length.\n   Example:\n   -- CUT --\n   CRZ\n   << FUCKING FREE CRAZE DOWNLOAD! <<<\n   DLT\n   << FUCKING FREE DELIGHT DOWNLOAD! <<<\n   -- CUT --\n   Will make all files starting with "CRZ" or "DLT" free download.\n   The names are NOT case sensitive.\n\n2. ByteKillHandler replacement.\n   If the file shouldn''t be made free download, AutoFree will comment the file\n   with the users slot number, so that ByteKiller and FastNuke (my own nuker)\n   knows who uploaded the file without checking thru the UDLog file (which\n   usually is quite BIG if you know what i mean!).\n\nInstalling this damn util:\n==========================\nCopy the dir AutoFree to Doors:\nCopy the icon to BBS:Commands/Syscmd/\nIf the file BBS:Commands/SysCmd/Filecheck1.Info exists, AutoFree\ntries to start "FILECHECK1" when it''s finished. So if you already have\na door at "FILECHECK" just rename it to FILECHECK1.\n\nContact nIKE?!\n==============\nCall INSTANT PLEASURE (+46-510-27660) or leave a message to any CRAZE or DELIGHT\nmember and tell them to contact me. (My board has a NUP installed, so u should\nbetter get that first! =)).\nIf you want a door personally designed or have some ideas etc for doors, then\nu should contact me! I don''t charge anything for the doors..\nAlthough u could give me a card or support my board or something =)..\n\nHistory:\n========\nv1.0  --  First version. Not released to anyone but beta testers.\nv1.1  --  Added support for starting a door upon exiting.\n          Added ByteKillHandler replacement.\nv1.2  --  Added the ability to add a comment in the filelist.\n          It was kinda lame without it.\n\nGreetings:\n==========\n     (« aLL cRAZE ^ dELIGHT mEMBERS! · bOBO/mYSTIC · xERXES/fLT^mST »)\n    (« vEDDER/iNS · dANSKEN · aGAMEMNON/m22 · rIOTER/eQX · lOGiC/rBS »)\n  (« zCANDALER!/dPL · dR.dRE!/tRSi · aQUARIUS/oTL · sAVAGE/iNS · lOUIE/iNS »)\n (« kID cURRY/cLS · jUAN/tRSi · bOROMIR/tRSi · oRG*/x-TRADE · cYBERTRON/aFL »)\n (« eXIDOR · lUSSAR''N/rEBELS · mANTA/aC · dISC · hIJACKER/cLS · cASCADE/aFL »)\n (« uFO/oRIENT · aLL tHE oTHER fELLA''S i''VE fORGOT iN tHIS sHITTY dOC fILE! »)\n\nSince everybody else write like "musical support" and shit, i''ll write it too!\n==============================================================================\n             NiRVANA ^ GREEN DAY ^ VARiOUS MODULES ^ PEARL JAM\n==============================================================================\n','\n',char(10)),NULL,'auto-added',36772,4,0,NULL,NULL,'dlt_af12','scan',1780048474);
INSERT INTO door_catalog VALUES('dlt_af13','DLT-AF13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DLT-AF13.LHA','Autofree','XIM','Autofree',NULL,NULL,'DLT','CR/\ZE aND!       /\_\ __\ __________________  \/_/  ____________/\____ ____ _ / __  /  /_____  / ____/  /  /·  _ /',replace('                     __    ____  _     _\n  CR/\ZE aND!       /\_\ __\\n__________________  \/_/  ____________/\____\n ____ _ / __  /  /_____  / ____/  /  /·  _ /\n /  / //  ___/  /  /   \/  /  /     //   \/\n/____ /_____/_____/_____\___ /__/__/______\.\nSk¡n\/---------- PRESENTS -\/--------------+\n(« aUTO fREE v1.3 - bUGfIX © nIKE/cRZ^dLT »)\n+------------------------------------------+\n','\n',char(10)),'Autofree.Doc',replace('    ___________   ____________   _________      ___________    _____________\n.___\___      /_._\_____     /___\______  \ ____\_____    /____\___        /\n|      /_____/  |    _|/   _/__      _____ \      _______/____ ___/       /_\n|    _/         |    \        /      \      \     \          / __________/  \\n|_______________|_____\      /________\      \______________/________________\\n-mNt/aC!               \____/          \______\\n\n                                     &\n                  _     _ ___       ___\n                            /_  __ /__/\ _\n _ ___________________________     \__\/    _____________¦_________/\______\n ________   _ /  ___    /o   /___________  /·  ______/   |   \ _      o _ /\n __/    /   //    _____//   /    /       \//   /    /         \/       \\/\n  /________ /________ /_________/_________\_______ /_____|_____\_________\\n  \_______\/\_______\/\_________\____ ____/______\/\_____¦_____/_________/\n           \/        \/              Y.           \/     ·            Sk¡n\n                                     :o\n                                    +.\n\n                       Presents another /X^S!X Door\n\n                      -^(· AutoFree v1.3 by Nike ·)^-\n\nDescription.\n============\nMakes files Free download automatically.\nByteKillHandler replacement.\n\nFeatures:\n=========\n1. It checks the file that a user uploads if it starts on the same thing\n   as in the config file.\n   In the configfile you can enter as many names and the names can be of\n   unlimited length.\n   Example:\n   -- CUT --\n   CRZ\n   << FUCKING FREE CRAZE DOWNLOAD! <<<\n   DLT\n   << FUCKING FREE DELIGHT DOWNLOAD! <<<\n   -- CUT --\n   Will make all files starting with "CRZ" or "DLT" free download.\n   The names are NOT case sensitive.\n\n2. ByteKillHandler replacement.\n   If the file shouldn''t be made free download, AutoFree will comment the file\n   with the users slot number, so that ByteKiller and FastNuke (my own nuker)\n   knows who uploaded the file without checking thru the UDLog file (which\n   usually is quite BIG if you know what i mean!).\n\nInstalling this damn util:\n==========================\nCopy the dir AutoFree to Doors:\nCopy the icon to BBS:Commands/Syscmd/\nIf the file BBS:Commands/SysCmd/Filecheck1.Info exists, AutoFree\ntries to start "FILECHECK1" when it''s finished. So if you already have\na door at "FILECHECK" just rename it to FILECHECK1.\n\nContact nIKE?!\n==============\nCall INSTANT PLEASURE (+46-510-27660) or leave a message to any CRAZE or DELIGHT\nmember and tell them to contact me. (My board has a NUP installed, so u should\nbetter get that first! =)).\nIf you want a door personally designed or have some ideas etc for doors, then\nu should contact me! I don''t charge anything for the doors..\nAlthough u could give me a card or support my board or something =)..\n\nHistory:\n========\nv1.0  --  First version. Not released to anyone but beta testers.\nv1.1  --  Added support for starting a door upon exiting.\n          Added ByteKillHandler replacement.\nv1.2  --  Added the ability to add a comment in the filelist.\n          It was kinda lame without it.\nv1.3  --  Found some small bugs in the code. A file was uploaded to my board\n          and AutoFree thought my group had released it.. not to good.. found\n          out that autofree stripped the last char in the config file!\n\nGreetings:\n==========\n     (« aLL cRAZE ^ dELIGHT mEMBERS! · bOBO/mYSTIC · xERXES/fLT^mST »)\n    (« vEDDER/iNS · dANSKEN · aGAMEMNON/m22 · rIOTER/eQX · lOGiC/rBS »)\n  (« zCANDALER!/dPL · dR.dRE!/tRSi · aQUARIUS/oTL · sAVAGE/iNS · lOUIE/iNS »)\n (« kID cURRY/cLS · jUAN/tRSi · bOROMIR/tRSi · oRG*/x-TRADE · cYBERTRON/aFL »)\n (« eXIDOR · lUSSAR''N/rEBELS · mANTA/aC · dISC · hIJACKER/cLS · cASCADE/aFL »)\n (« uFO/oRIENT · aLL tHE oTHER fELLA''S i''VE fORGOT iN tHIS sHITTY dOC fILE! »)\n\nSince everybody else write like "musical support" and shit, i''ll write it too!\n==============================================================================\n             NiRVANA ^ GREEN DAY ^ VARiOUS MODULES ^ PEARL JAM\n==============================================================================\n\n       And also ! Don`t forget to give these DELIGHT boards a ring !\n\n            CHAOTIC ENTITY   *WHQ*  +1 610 489 5783  [Ringdown]\n            DOOM OF EXTASY   *EHQ*  +49 PRIVATE !!!  [Ringdown]\n	    UNDERCOVER       *SHQ*  +46 8 540 23405  [2 Nodes!]\n	    DAWN RAID        *UKHQ* +44 707 320 320  [Ringdown]\n	    THE UNDISCOVERED *DHQ*  +31 229 444 42   [2 Nodes!]\n	    EUROPES CHAOS    *DST*  +49 461 311 458  [1 Node! ]\n	    THE KREMLIN      *DST*  +7  951 255 867  [1 Node! ]\n\n==============================================================================\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n','\n',char(10)),NULL,'auto-added',7293,1,0,NULL,NULL,'dlt_af13','scan',1780048479);
INSERT INTO door_catalog VALUES('dlt_ax11','DLT-AX11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DLT-AX11.LHA','MFMAxs','XIM','MFMAxs',NULL,'MFM/dELIGHT','DLT','| ____| __ | .  ____ |__ |_              / | |(____|(_/_l_l_(___( |  )l_   presents: //.| `------------.______)----------------------''',replace('.-sdn--------------------------------------.\n| ____| __ | .  ____ |__ |_              / |\n|(____|(_/_l_l_(___( |  )l_   presents: //.|\n`------------.______)----------------------''\n  ->->  MFM-Axs v1.1 by MFM/dELIGHT  <-<-\n\n  Shows the users which have AXS to a conf\n   for /X. Faster then UsrCnfAx! Update!\n<------------------------------------------>\n','\n',char(10)),'MFMAxs.doc',replace('\n __________\n \_____  ·/\ __________________________________________________________.\n  \/  / // /                                                           |\n  /____ / /                D   E   L   ¡   G   H   T                  o|\n  \___\/ /                       · PRESENTS ·                         ¦|\n  ¦  __\/__                                                           ·|\n  | /\  ___\      MFM-Axs v1.1, the DELIGHTed coder is MFM/dELIGHT!    |\n  | \ \  _)/_  ___   ___      ______            _______                |\n  |__\ \_____\/  /__/__/\    /o____/\ _____    /·_____ _ ______________|\n      \/_____/  /  /\__\ \  // /  /\/\  \  \  // /\__ _ __         Sk¡n\n            /____ / /\  \ \/____ / /\ \     \/__/ /\n            \___\/ /  \__\/\___\/ /  \ \__\__\__\/\n                 \/             \/    \/__/__/\n\n\n What this util does:\n ~~~~~~~~~~~~~~~~~~~~\nIt creates bulletins with all users who have access to a certain conference,\nlike UsrCnfAx by EMPiRE/MYSTiC but it''s MUCH faster, looks better and it''s\nNOT compiled Arexx like UsrCnfAx (or why does UsrCnfAx require RexxMast?)\n\n Requirements:\n ~~~~~~~~~~~~~\n /X 3.x - /X 4.x\n OS 2.0+\n\n Usage:\n ~~~~~~\nCLi Usage :\n\n MFMAxs <Conference Nr> <Output File> <Optional LOGO-File>\n\nExamples : \n\n MFMAxs 5 BBS:DLT/Bull20.txt\n\n MFMAxs 5 BBS:DLT/Bull20.txt BBS:Screens/DLTLogo.txt\n\nNote that you don''t need a logo. Put this in your logoff-script or where ever\nyou want. Write a line for each conference you wish to have an access-bulletin.\nYou can also test it out in CLi or SHELL with\n\n MFMAxs <Conference Nr> * <optional logo>\nor:\n MFMAxs <Conference Nr> CONSOLE: <optional logo>\n\n Customization:\n ~~~~~~~~~~~~~~\n If you DON''T have the default names and paths for the access directory and\n the user.data then you can write a file like this:\n\n --- CUT HERE ---\n\n BBS:Access/\n BBS:User.Data \n\n --- CUT HERE ---\n\n Note! You *MUST* have the tailing slash on the ACCESS directory!\n\n And save it as MFMAxs.CFG in the SAME directory as MFMAxs (If you have standard\n setup you don''t need this)\n\n Current limitations:\n ~~~~~~~~~~~~~~~~~~~~\n\n It works only on /X 3.x and higher but i will fix that if someone requests\n it. It can only handle 99 conferences but if you have more then 99 confs\n then i''ll fix it for you :)\n\n Greetings:\n ~~~~~~~~~~\n\n Sorry no greetings this time but I don''t have the time. Look in some other\n release from me...\n','\n',char(10)),NULL,'auto-added',17849,6,0,NULL,NULL,'dlt_ax11','scan',1780048479);
INSERT INTO door_catalog VALUES('dlt_dl11','DLT-DL11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DLT-DL11.LHA','DIRLOOK_CPS','XIM','DIRLOOK_CPS',NULL,NULL,'DLT','CR/\ZE aND!       /\_\ __\ __________________  \/_/  ____________/\____ ____ _ / __  /  /_____  / ____/  /  /·  _ /',replace('                     __    ____  _     _\n  CR/\ZE aND!       /\_\ __\\n__________________  \/_/  ____________/\____\n ____ _ / __  /  /_____  / ____/  /  /·  _ /\n /  / //  ___/  /  /   \/  /  /     //   \/\n/____ /_____/_____/_____\___ /__/__/______\.\nSk¡n\/---------- PRESENTS -\/--------------+\n(« dIR lOOK v1.1,dIRsTYLER © nIKE/cRZ^dLT »)\n+------------------------------------------+\n','\n',char(10)),'DirLook.Doc',replace('    ___________   ____________   _________      ___________    _____________\n.___\___      /_._\_____     /___\______  \ ____\_____    /____\___        /\n|      /_____/  |    _|/   _/__      _____ \      _______/____ ___/       /_\n|    _/         |    \        /      \      \     \          / __________/  \\n|_______________|_____\      /________\      \______________/________________\\n-mNt/aC!               \____/          \______\\n\n                                     &\n                  _     _ ___       ___\n                            /_  __ /__/\ _\n _ ___________________________     \__\/    _____________¦_________/\______\n ________   _ /  ___    /o   /___________  /·  ______/   |   \ _      o _ /\n __/    /   //    _____//   /    /       \//   /    /         \/       \\/\n  /________ /________ /_________/_________\_______ /_____|_____\_________\\n  \_______\/\_______\/\_________\____ ____/______\/\_____¦_____/_________/\n           \/        \/              Y.           \/     ·            Sk¡n\n                                     :o\n                                    +.\n\n                       Presents another /X^S!X Door\n\n                      -^(· DirLook v1.1 by Nike ·)^-\n\nDescription.\n============\nMakes files Free download automatically.\nByteKillHandler replacement.\nDirstyler (Time, Node, CPS).\n\nNB: If you have installed AutoFree then you can skip part 1 and 2 in the next\nsection of this doc! DirLook is just a replacement of AutoFree containing a\nDirStyler!\n\nFeatures:\n=========\n1. It checks the file that a user uploads if it starts on the same thing\n   as in the config file.\n   In the configfile you can enter as many names and the names can be of\n   unlimited length.\n   Example:\n   -- CUT --\n   CRZ\n   << FUCKING FREE CRAZE DOWNLOAD! <<<\n   DLT\n   << FUCKING FREE DELIGHT DOWNLOAD! <<<\n   -- CUT --\n   Will make all files starting with "CRZ" or "DLT" free download.\n   The names are NOT case sensitive.\n\n2. ByteKillHandler replacement.\n   If the file shouldn''t be made free download, AutoFree will comment the file\n   with the users slot number, so that ByteKiller and FastNuke (my own nuker)\n   knows who uploaded the file without checking thru the UDLog file (which\n   usually is quite BIG if you know what i mean!).\n\n3. Dirstyler.\n   It will add a line in the File description containing Time, Node and CPS.\n   See the example included.\n   Since I could not decide wether to start reading lots of icons and checking\n   for S-Express config files after that little line containing the info if\n   the board has an UDLog file (needed for the CPS) I''ve come up with this:\n   If a node doesn''t have UDLog turned on, either turn it on or make a file\n   called "Local" in BBS:Node<Node>/. This was a lot better for compability.\n\nInstalling this damn util:\n==========================\nIf u want dirlook with CPS then use DIRLOOK_CPS. If not use DIRLOOK_NOCPS!\nCopy the dir AutoFree to Doors:\nCopy the icon to BBS:Commands/Syscmd/\nIf the file BBS:Commands/SysCmd/Filecheck1.Info exists, DirLook\ntries to start "FILECHECK1" when it''s finished. So if you already have\na door at "FILECHECK" just rename it to FILECHECK1.\n\nContact nIKE?!\n==============\nCall INSTANT PLEASURE (+46-510-27660) or leave a message to any CRAZE or DELIGHT\nmember and tell them to contact me. (My board has a NUP installed, so u should\nbetter get that first! =)).\nIf you want a door personally designed or have some ideas etc for doors, then\nu should contact me! I don''t charge anything for the doors..\nAlthough u could give me a card or support my board or something =)..\n\nHistory:\n========\nv1.0  --  First version. Not released to anyone but juan!\nv1.1  --  This version. Rewrote the program from scratch.\n          Added the new options in AutoFree since this is supposed to be a\n          replacement for it.\n\nGreetings:\n==========\n     (« aLL cRAZE ^ dELIGHT mEMBERS! · bOBO/mYSTIC · xERXES/fLT^mST »)\n    (« vEDDER/iNS · dANSKEN · aGAMEMNON/m22 · rIOTER/eQX · lOGiC/rBS »)\n  (« zCANDALER!/dPL · dR.dRE!/tRSi · aQUARIUS/oTL · sAVAGE/iNS · lOUIE/iNS »)\n (« kID cURRY/cLS · jUAN/tRSi · bOROMIR/tRSi · oRG*/x-TRADE · cYBERTRON/aFL »)\n (« eXIDOR · lUSSAR''N/rEBELS · mANTA/aC · dISC · hIJACKER/cLS · cASCADE/aFL »)\n (« uFO/oRIENT · aLL tHE oTHER fELLA''S i''VE fORGOT iN tHIS sHITTY dOC fILE! »)\n\nSince everybody else write like "musical support" and shit, i''ll write it too!\n==============================================================================\n             NiRVANA ^ GREEN DAY ^ VARiOUS MODULES ^ PEARL JAM\n==============================================================================\n\n       And also ! Don`t forget to give these DELIGHT boards a ring !\n\n            CHAOTIC ENTITY   *WHQ*  +1 610 489 5783  [Ringdown]\n            DOOM OF EXTASY   *EHQ*  +49 PRIVATE !!!  [Ringdown]\n	    UNDERCOVER       *SHQ*  +46 8 540 23405  [2 Nodes!]\n	    DAWN RAID        *UKHQ* +44 707 320 320  [Ringdown]\n	    THE UNDISCOVERED *DHQ*  +31 229 444 42   [2 Nodes!]\n	    EUROPES CHAOS    *DST*  +49 461 311 458  [1 Node! ]\n	    THE KREMLIN      *DST*  +7  951 255 867  [1 Node! ]\n\n==============================================================================\n','\n',char(10)),NULL,'auto-added',8366,3,0,NULL,NULL,'dlt_dl11','scan',1780048479);
INSERT INTO door_catalog VALUES('dlt_dl12','DLT-DL12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DLT-DL12.LHA',NULL,'XIM','__    ____  _',NULL,'Mystif/DLT','DLT','/\_\ __\ __________________  \/_/  ____________/\____ ____ _ / __  /  /_____  / ____/  /  /   _ /',replace('                     __    ____  _\n                    /\_\ __\\n__________________  \/_/  ____________/\____\n ____ _ / __  /  /_____  / ____/  /  /   _ /\n /  / //  ___/  /  /   \/  /  /     //   \/\n/____ /_____/_____/_____\___ /__/__/______\.\nSkin\/----------- presents \/--------------+\nThe Extravagant Door List v1.2 by Mystif/DLT','\n',char(10)),'doorlist.doc',replace('                   _     _ ___       ___\n                             /_  __ /__/\ _\n  _ ___________________________     \__\/    _____________¦_________/\______\n  ________   _ /  ___    /o   /___________  /·  ______/   |   \ _      o _ /\n  __/    /   //    _____//   /    /       \//   /    /         \/       \\/\n   /________ /________ /_________/_________\_______ /_____|_____\_________\\n   \_______\/\_______\/\_________\____ ____/______\/\_____¦_____/_________/\n            \/        \/              Y.           \/     ·            Sk¡n\n                                       :o\n                                       +.\n\n                                   presents\n\n                        The Extravagant Door List v1.21\n\n                         a XIM for /X v3.xx and above\n\n\n  No docs this time, pals... If you are not brain-damaged then you''ll have\n  no problem figuring out how to install the door. But keep in mind though,\n  that the door  searches for the modules you specify in the config file in\n  ConfXcmd, NodeXcmd and Bbscmd directories and if it cannot locate the\n  module in any of these dirs then it is excluded from the module list. Oki\n  for now. Go have fun.\n\n                         Greetings go to these people\n\n                           NightProwler New Order\n                                 Tarzan The Plastic Passion\n                                 Empire Last Outpost\n                                   Nike Instant Pleasure\n                               Muad''Dib The Undiscovered\n                                  Rebel Trancentral\n                                 Hornet Error\n\n                       and all Delight members worldwide\n','\n',char(10)),NULL,NULL,13644,3,0,NULL,NULL,NULL,'scan',1780048479);
INSERT INTO door_catalog VALUES('dlt_f101','DLT-F101.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DLT-F101.LHA','FiLECOMMENT','XIM','FiLECOMMENT',NULL,'MFM/dELIGHT','DLT','| ____| __ | .  ____ |__ |_              / | |(____|(_/_l_l_(___( |  )l_   presents: //.| `------------.______)----------------------''',replace('.-sdn--------------------------------------.\n| ____| __ | .  ____ |__ |_              / |\n|(____|(_/_l_l_(___( |  )l_   presents: //.|\n`------------.______)----------------------''\n->->  FileComment v1.01 by MFM/dELIGHT  <-<-\n\nStill the FASTEST and BEST ''fake'' door made\n  for /X. With ByteKiller Mode! Bugfixed!\n<------------------------------------------>\n','\n',char(10)),'FileComment.doc',replace('\n                                    ____\n       _______  ______________     (____) _______  ____ _____________\n       \______\ \_ _____/\   |___  /    \ \_ ___/_ \   Y  \____ ____/\n .-----/     | \/  ____)_/   |   \/      \/  |___ \/ __|_  \/     \-------.\n |    /      |  \        \   |    \       \        \(____   \      \      |\n |   /_____  |   \___     \___     \       \___     \__|     \___   \     |\n |   -----l_______\-l______\-l______\_______\-l______\-l______\-l____\ML  |\n `------------------------------------------------------------------------''\n\n                    FILECOMMENT  v1.01 - by MFM/dELIGHT\n\n                           -*- Documentation -*-\n\n                               What is this?\n                               ¯¯¯¯¯¯¯¯¯¯¯¯¯\n  FileComment is a /X and S!X door that works like the old AmiFaker''s\n  FAKE option (Comment a file if its old or a rename etc!). In this version\n  you can use it with ByteKiller2 insted of it''s own slow ByteComment.\n  It has nice ansi-colors, it''s fast and it works with unlimited conferences,\n  not like AmiFaker who can only handle 9 conferences and needs some files\n  from the old /X (Like NDIRS). Ofcourse this door works with /X 2.x and SiGMA\n  EXPRESS too. FileComment also has "QuickMacros" like the AmiFaker. Another\n  nice feature is that the commenter''s name only will be on the first line\n  of the comment which allows more text to be written on less space and you\n  will anyway see who''s written the text easily because of the ansi-colors.\n\n>>> IT CONTAINS NO *LAME* "PLEASE REGISTER" MESSAGES OR SUCH F**KING CRAP! <<<\n\n\n                              News for v1.01\n                              ¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n · = DLT-F101.LHA =\n\n · * Bug Fix *\n\n   FileComment fucked up if you had 10+ dirs, now fixed.\n   Thanks to TWiSTER/oGN^dCS for mentioning it!\n\n · * FileComment is now a ·dELIGHT· product! *\n\n                              News for v1.00\n                              ¯¯¯¯¯¯¯¯¯¯¯¯¯¯   \n · = SR-FC100.LHA =\n\n · * ByteKiller-Mode *\n\n   It''s now possible to use ByteKiller2''s internal format instead of\n   a message to sysop (You will get the option to nuke the files when\n   you start ByteKiller2). This means that you should replace ByteComment\n   with this FileComment. This door is also ·MUCH· faster then ByteComment,\n   it has quickmacros, multiple commentlines, it doesn''t mess up the whole\n   listing if you are using NightScanner, it can take the filename from the\n   commandline etc!\n \n · * Some minor fixes *\n\n                              News for v0.99\n                              ¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n · = SR-FC099.LHA =\n\n · * First public release! *\n\n\n                              In short terms:\n                              ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n                   · EASY TO USE\n                   · FASTEST\n                   · FILENAME VIA COMMANDLINE\n                   · MULTiPLE COMMENTLINES\n                   · NICE COLORS\n                   · CLEAN DESiGN\n                   · MESSAGE TO SYSOP WITH COMMENT\n                     -OR-\n                     USING BYTEFAKER-2''S INTERNAL\n                     FILES\n                   · UNLiMiTED CONFERENCES (I HOPE)\n                   · QUiCK MACROS\n                   · NO *LAME* "PLEASE REGISTER" MESSAGES!\n                     (LIKE XXXx-/X iNNOVATION... hehe...)\n                   · IT IS NOT CRIPPLED IN ANY WAY!\n                   · ETC!\n\n                         Installation for /X 3-4.x\n                         ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nCopy Libs/AEDoor.Library to LIBS: (Be sure to have V2 of this library (included))\nCopy BBSCmd/FAKE.info to BBS:Commands/BBSCmd/\nCopy Doors/FiLECOMMENT/FiLECOMMENT to Doors:FileComment/\n\n                 Installation for /X 2.x and SiGMA EXPRESS\n                 ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nCopy Libs/AEDoor.Library to LIBS: (Be sure to have V2 of this library (included))\nCopy Doors/FiLECOMMENT/FiLECOMMENT to Doors:FileComment/\nAdd the following text to the textfile BBS:Commands/BBS.CMD:\n\n-- cut here --\n*FAKE     XM020Doors:FileComment/FileComment\n-- cut here --\n\nYou can ofcourse change the name from FAKE but that is the most common\nname used for fakers like this.\n\nIf you want to use the bytekiller-mode you must have the bytekiller installed\nat Doors:ByteKiller\n\n          IMPORTANT!! How do I use FileComment with ByteKiller??\n          ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n If you have a directory called DOORS:ByteKiller it will AUTOMAGICALLY use\n the ByteKiller-Mode... WARNING! If you have an older version of ByteKiller\n I don''t know if it will corrupt the fake-log cause this door is only made\n for ByteKiller 2.0 and higher. If you have a Doors:ByteKiller directory but\n doesn''t use it then you must delete/rename the directory. I haven''t tested\n the ByteKiller-mode with more then 9 conferences so if you have problems\n then write me on internet/fidonet(not reliable)/any bbs (See Below).\n Note! ByteComment/ByteKiller only supports one commentline, so this will\n be the first FileComment-line. \n\n\n                  COMPLETE documentation for FileComment\n                  ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n Start the door by typing FAKE or FAKE <FileName to Fake>. If you only wrote\n FAKE you will now see :\n\nFileComment v1.01 by MFM/dELIGHT\n\nFile to comment : \n\n Here you just enter the filename to comment. You can also write the first\n letters in the name (DLT-CRC -> DLT-CRCK.DMS) and then the commenter will\n take the first file which the letters matches. If you press enter the program\n will abort.\n After you have given the filename you will be prompted with this :\n\nYou can enter multiple commentlines, just press [ENTER] on an empty prompt\nto finish the input. Max 29 commentlines are supported!\nQuick Macros: A>ncient B>roken C>rap F>ake M>ajor O>ld R>ename L>ame\n\nComment         :\n\n Here you just enter your comment. You don''t have to worry about writing to\n long because the door will handle it for you. Because the name is only shown\n on the first commentline, you can write more text on the other lines. You can\n also use the QuickMacros which means that if you want to comment a file with\n LAME!, you just write the single character L on the commentline. You''re seeing\n all available QuickMacros above the comment-prompt. When your comment is\n finished just press [ENTER] on an empty prompt to finish the input. You will\n now see something like this:\n\nLoading Systemfiles and Directory...Ok!\nScanning Directory...Found it!\nAdding comment...Ok!\n\n The sysop gets a private message with the comment and filename\n OR if you have the ByteKiller installed it will append an entry to\n the ByteKiller''s fake-log.\n\n Or if the file is not found in the upload-directory:\n\nLoading Systemfiles and Directory...Ok!\nScanning Directory...NOT Found!\n\nNote!\nOnly the files in the upload-directory will be scanned, but I will probably\nadd a config later so you can choose which dirs that will be scanned.\nIf you get a "W8..." instead of "Ok!" one of the systemfiles is unavailable\nright now and we will have to wait until we can use it.\n\n                                Tested On:\n                                ¯¯¯¯¯¯¯¯¯¯\n                 /X 3.38-/X 4.7, /X 2.33 and SiGMA EXPRESS v0.38\n\n               >> Why does the door LOCK UP at start???? <<\n               ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nBecause you *MUST* have version 2.0 or a newer version of the AEDoor.library,\nif you have an older version the door will lock cause there is NO way back!\nThe old AEDoor.library 1.x was in the Illusion-release of /X 4.7 so if you\nhave that version you MUST upgrade it to the version in this package.\n\n                                Last notes:\n                                ¯¯¯¯¯¯¯¯¯¯¯\n· This door is not too much tested with multinode-systems but I think that\n  it should work good. If you experience problems just write me on one of\n  the boards listed below.\n\n· This is NOT the last version, so if you have any ideas/bugreports feel\n  free to contact me!\n\n· The door searches the dirfile backwards to find the new uploads first\n\n· This door was released in a hurry (as always) but it should work! :)\n\n· Thanks to SANDMAN/FLT for good ideas and suggestions for this door,\n  it was he that came up with the idea of this door!\n\n           For bugreports, ideas and suggestions contact me at :\n\n                   InterNet : [email removed]\n\n                   FidoNet  : NetMail to MFM at 2:205/357\n\n                  uNDERCOVER     [dLT  SHQ] +46-8-PRiVATE\n                  iNFiNiTE lINK  [bTd  SHQ] +46-26-124467\n                  pLAYgROUND     [bTd USHQ] +1-IT''S-PRi-VATE\n                  tRANCELAND     [aST  WHQ] +46-26-275666\n                  sPELLBOUND     [sR   SHQ] +46-PRiVATE!!\n\n             - and some other major boards around the globe -\n\n               >>> To reach me FAST write me at INTERNET <<<\n\n\n                                 Messages:\n      <===============================================================>\n\n      FLAKE/TRSi  - Use my locale catalog, the old one was really LAME...\n\n      SANDMAN/FLT - Thanks for all the really great ansis!\n \n      DEMAX/DLT   - What about showing the dlt conf on the JoinConf.TXT ?\n\n      <===============================================================>\n\n\n                              Greetingslist: \n      <===============================================================>\n                     Sandman/FairLight\n                     Twister/oRIGIN & Dual Crew ^ Shining\n                     The Silencer/The Doodles ^ Shock\n                     PolarBeer/Betrayed\n                     Smygelfh/Betrayed\n                     Rolemaster/Phenomena^Betrayed\n                     Necromancer/Phenomena^Betrayed\n                     Juan^Harpoon/TRSi^SR\n                     Flake/TRSi\n                     Ångest/MindPop^Assault\n                     Sate/The Dead Guys\n                     D-Zire/SPB & The Doodles ^ Shock\n                     Kid Curry/Classic\n                     LongPlay/Betrayed USA\n                     Demax/Delight\n                     Agressor/Delight\n                     Talon/Delight\n                     Aquarius/Outlaws\n                     Agamemnon/M22\n                     Ozone/Classic\n                     Cobra/Over The Top\n                     Sauron/Disorder\n      <===============================================================>\n\n         Yes the nuker is probably coming some fine day in 1995...\n','\n',char(10)),NULL,'auto-added',26396,7,0,NULL,NULL,'sr_fc099','scan',1780048479);
INSERT INTO door_catalog VALUES('dlt_fa11','DLT-FA11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DLT-FA11.LHA','FastAdd','XIM','FastAdd',NULL,NULL,'DLT','CR/\ZE aND!       /\_\ __\ __________________  \/_/  ____________/\____ ____ _ / __  /  /_____  / ____/  /  /·  _ /',replace('                     __    ____  _     _\n  CR/\ZE aND!       /\_\ __\\n__________________  \/_/  ____________/\____\n ____ _ / __  /  /_____  / ____/  /  /·  _ /\n /  / //  ___/  /  /   \/  /  /     //   \/\n/____ /_____/_____/_____\___ /__/__/______\.\nSk¡n\/---------- PRESENTS -\/--------------+\n(« fAST aDD v1.1 nEW oPTs! © nIKE/cRZ^dLT »)\n+------------------------------------------+\n','\n',char(10)),'FastAdd.Doc',replace('    ___________   ____________   _________      ___________    _____________\n.___\___      /_._\_____     /___\______  \ ____\_____    /____\___        /\n|      /_____/  |    _|/   _/__      _____ \      _______/____ ___/       /_\n|    _/         |    \        /      \      \     \          / __________/  \\n|_______________|_____\      /________\      \______________/________________\\n-mNt/aC!               \____/          \______\\n\n                                     &\n                  _     _ ___       ___\n                            /_  __ /__/\ _\n _ ___________________________     \__\/    _____________¦_________/\______\n ________   _ /  ___    /o   /___________  /·  ______/   |   \ _      o _ /\n __/    /   //    _____//   /    /       \//   /    /         \/       \\/\n  /________ /________ /_________/_________\_______ /_____|_____\_________\\n  \_______\/\_______\/\_________\____ ____/______\/\_____¦_____/_________/\n           \/        \/              Y.           \/     ·            Sk¡n\n                                     :o\n                                    +.\n\n                     ==)> Presents 2 ya in 1994! <(==\n\n                      -^(· FastAdd v1.1 by Nike ·)^-\n\nIntroduction:\n=============\nThis is another Textadder for You''re board.\nThis is not as configurable as others that adds the textfiles and strips, and\nadds some variables etc, but It''s FAST! That''s the idea of this Program!\nIf you just want the speed and not some configfiles that needs to be changed\nthen use this program.\n\nInstallation:\n=============\nCopy the Files in C/ to C:\nCopy the files in Fcheck/ to BBS:Fcheck/\nMake your own add (can be before or after the text file, and both if you want).\nConfigurate the fcheck icons so that your add will be appended.\n\nArguments:\n==========\n\nFastAdd <Front Add> <Tail Add> <Filename>\n\nIf you do NOT want to add a front or a Tail add, then set the argument to NONE.\n\nExamples.\n	FastAdd S:Craze.Txt NONE\n\nAdds the file S:Craze.Txt as a HEADER file in the textfile and doesn''t add\nany file as a tail file.\n\n(AmiExpress will add the filename by itself so you do not need to enter that\nin the icon).\n\nPretty easy?!\n\nContact nIKE?!\n==============\nCall INSTANT PLEASURE (+46-510-27660) or leave a message to any CRAZE or DELIGHT\nmember and tell them to contact me. (My board has a NUP installed, so u should\nbetter get that first! =)).\nIf you want a door personally designed or have some ideas etc for doors, then\nu should contact me! I don''t charge anything for the doors..\nAlthough u could give me a card or support my board or something =)..\n\nHistory:\n========\nv1.0    - First version. Coded in about 5 minutes.\nv1.1    - Many people requested a new version coz the old one was slow\n          when it only added a text at the end. This is now fixed.\n          (The old routine wrote the WHOLE FILE again even if you only added\n           an add at the end. Now it will be appended faster).\n\nGreetings:\n==========\n     (« aLL cRAZE ^ dELIGHT mEMBERS! · bOBO/mYSTIC · xERXES/fLT^mST »)\n    (« vEDDER/iNS · dANSKEN · aGAMEMNON/m22 · rIOTER/eQX · lOGiC/rBS »)\n  (« zCANDALER!/dPL · dR.dRE!/tRSi · aQUARIUS/oTL · sAVAGE/iNS · lOUIE/iNS »)\n (« kID cURRY/cLS · jUAN/tRSi · bOROMIR/tRSi · oRG*/x-TRADE · cYBERTRON/aFL »)\n (« eXIDOR · lUSSAR''N/rEBELS · mANTA/aC · dISC · hIJACKER/cLS · cASCADE/aFL »)\n (« uFO/oRIENT · aLL tHE oTHER fELLA''S i''VE fORGOT iN tHIS sHITTY dOC fILE! »)\n\nSince everybody else write like "musical support" and shit, i''ll write it too!\n==============================================================================\n             NiRVANA ^ GREEN DAY ^ VARiOUS MODULES ^ PEARL JAM\n==============================================================================\n','\n',char(10)),NULL,'auto-added',51884,8,0,NULL,NULL,'dlt_fa11','scan',1780048479);
INSERT INTO door_catalog VALUES('dlt_fa20','DLT-FA20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DLT-FA20.LHA','FastAdd','XIM','FastAdd',NULL,NULL,'DLT','CR/\ZE aND!       /\_\ __\ __________________  \/_/  ____________/\____ ____ _ / __  /  /_____  / ____/  /  /·  _ /',replace('                     __    ____  _     _\n  CR/\ZE aND!       /\_\ __\\n__________________  \/_/  ____________/\____\n ____ _ / __  /  /_____  / ____/  /  /·  _ /\n /  / //  ___/  /  /   \/  /  /     //   \/\n/____ /_____/_____/_____\___ /__/__/______\.\nSk¡n\/---------- PRESENTS -\/--------------+\n(« fAST-aDD v2.0 - mAJOR!! © nIKE/cRZ^dLT »)\n+------------------------------------------+\n','\n',char(10)),'FastAdd.guide',replace('@DATABASE "FastAdd v2.0"\n@$VER: FastAdd v2.0\n@author "Nike/Craze^Del!ght"\n@(c) "Nike/Craze^Del!ght -95"\n@remark Made by Muad''Dib\n\n@NODE MAIN "FastAdd v2.0"\n\n                                                    _____\n    _____________________________   ______________ |     |_______________\n    \_______  \   ______/       /  (______)  ____/_|_   _| \_____  _____/\n    |      /   \_ ___)_\_   ___/___/      \_ \__     |  \_     |    |\n    |     /     / \      |  \     \        /   |     |   |     |    |\n    |__________/_________|_________\_____ /____|_____|___|_____|____|\n+-Mo!/f^I- - -- - -- - -- - -- - -- - --\/- -- - -- - - -- - -- - -- - -- -+\n\n             - --(· FastAdd v2.0 By Nike/Craze^Del!ght -95 ·)-- -\n\n                             Released on 21-01-95\n\n               - --(· FastAdd Guide By Muad''Dib/Del!ght ·)-- -\n\n\n                                 @{"What is it? " Link 0.}\n                                 @{"Installation" Link 1.}\n                                 @{"Adding info " Link 2.}\n                                 @{"Errors      " Link 3.}\n                                 @{"Contact me! " Link 5.}\n                                 @{"Greetz      " Link 4.}\n                    \n                                 @{"Easy Install" Link FI}\n\n@endnode\n\n@node "0." "FastAdd v2.0 - What is FastAdd?"\n\n@{B} @{U}What is FastAdd?@{ub}@{UU}\n\n     FastAdd is a FAST TXT adder. FastAdd can join both front as a tailing\n     ASCII or ANSI text. It can place the uploader''s data in the text file,\n     read about it in @{"options" link "2." 0}\n\n@endnode\n\n@node "1." "FastAdd v2.0 - Installation"\n\n@{B} @{U}Installation@{ub}@{UU}\n\n     To spare you some time we included the necessary directories and files.\n\n     In this archive you will find after the BBS adds these dirs:\n\n          FCheck              Copy the files to BBS:FCheck/\n          Doors/FastAdd       Copy the dir FastAdd to your Doors:\n\n     In the FCheck directory you will find the files:\n\n          txt.info\n          nfo.info\n          doc.info\n\n     In these icons you will find the line CHECKER=Doors:FastAdd/FastAdd.\n     If you changed the location you have to change it here as well.\n \n     @{B}CHECKER=Doors:FastAdd/FastAdd@{ub}\n\n     After that you will find the OPTIONS. Here you can put the path and\n     the file name of the banner(s) you want to include:\n\n     @{B}OPTIONS=Add:Header.ASCII Add:Tail.ASCII@{ub}\n\n     If you don''t want a banner to be included then use key "@{B}NONE@{ub}".\n\n     Errors that can occure aren''t advised to use in the icon, since\n     there can''t be a mistake in a text file. Though some things can\n     happen. Read the @{"Errors" link "3." 0} chapter.\n\n     In the Doors/FastAdd directory you will find:\n\n          FastAdd             The main program\n          FastAdd.guide       This file ;)\n          Header.ASCII        Example of a header file\n          Tail.ASCII          Example of a tail file\n\n     The header and tailer fail can contain some keywords which will be\n     replaced. Continue reading the @{"Uploader information" Link "2." 0}.\n@endnode\n\n@node "2." "FastAdd v2.0 - Uploader information"\n\n @{U}@{B}Uploader information@{ub}@{UU}\n\n     When you include one of these keywords (or all!) then they will be\n     replaced by the info they stand for.\n\n               ==!UPLOADER!==           The name of the uploader\n               ====!LOCATION!====       and his location.\n               ==DATE==                 Current date\n               ==TIME==                 and the time\n               @#                       Node number\n\n               @{B}@{"Example" Link "2.1." 0}@{ub}\n\n@endnode\n\n@node "2.1." "FastAdd v2.0 - Example"\n\n@{U}@{B}Example:@{ub}@{UU}\n\nYou''ve made an ASCII to include and used the keywords:\n\n_____  /\______.___  ______  _\n\____\/____/   |  ¬\/  __ ¬\_\ -  -- --- ---------------------------------.\n_/   \/  ¬\_   _    \_ \____/__     >.T.H.E. .U.N.D.I.S.C.O.V.E.R.E.D.<   ¦\n\_____     /___|     /___     /:.   >.+31.229.444.42...+31.229.414.42.<   !\n-:---l____/----l____/---\____/---- --- --- --  -     >.+31.229.4ELITE.<   :\n ¡                   ______.                         ________             |\n |   DELiGHT DHQ!    \     |___  ____ .____ _  ______\      /______       O\n O  MYSTiC BETA HQ   \\_   |  ¬\/    \|   _____\__  ¬\\____/    __/__  /\ |\n |    iNFECT EHQ     _/    ·    \_   \\   ¬\_    |    \_  ¬\______  ¬\_\//¡\n ¦                  .\___________/___|\_____/_____     /____/   ______/ · :\n :        - -- --- ------------------------------l____/--\______/------   .\n . _ ______   _____________. ___________    _______ _ _____    ________ _ :\n : //  ___/__/   __ ¬\     |/     / __ ¬\___\____ ¬\_  __ ¬\___\____  ¬\\ ¦\n ._/   |    ¬\_  \/   \_   ·     /  \____/__   \/  _/  \____/__    |    \_:\n |\_____      /________/   _____/ _ __     /___/    \____     /_____     /|\n :-----l_____/-------|_____/-sTZ!/6c-\____/----\_____/--\____/-----l____/-:\n !                                                                        !\n | [MUAD''DiB/DLT]  [WISHBRINGER/DLT]  [MOTIVE POWER/MST]  [KiLLRAVEN/MST] |\n ¦                               [JAKE/PSG]                               ¦\n : >.A.M.I.G.A.<>.C.O.N.S.O.L.E.<>.6.8.O.4.O.P.0.W.E.R.<>.U.S.R.2.8.K.8.< :\n ¦------------------------------------------------------------------------¦\n |UL BY: ==!UPLOADER!== / ====!LOCATION!==== ON: ==DATE==/==TIME== NODE @#|\n `------------------------------------------------------------------------''\n\nThe bottom line will be replaced and look like:\n \n ¦------------------------------------------------------------------------¦\n |UL BY: ÐEMAX^AGRESSøR /  DELIGHT SWEDEN!   ON: 01-21-95/21:25:13 NODE 03|\n `------------------------------------------------------------------------''\n                           - --(· FastAdd v2.0 By Nike/Craze^Del!ght -95 ·)-- -\n\n@endnode\n\n@node "3." "FastAdd v2.0 - Errors"\n\n @{B}@{U}Errors:@{UU}@{ub}\n\n The following errors can occur:\n\n     "Out of memory!"       - Reason: Out of memory.\n     "File does not exist!" - One of the file you wrote does not exist.\n                              (Will not occur with /X :) )\n     "Bad args"             - You did not supply the right arguments.\n     "No userinfo found!"   - You ran the door from CLI and there couldn''t\n                              be found any information about the user.\n\n@endnode\n\n@node "4." "Greetings list"\n\n@{B} @{U}Nike sends hello to:@{ub}@{uu}\n\n      (« aLL cRAZE ^ dELIGHT mEMBERS! · bOBO/mYSTIC · xERXES/fLT^mST »)\n     (« vEDDER/iNS · dANSKEN · aGAMEMNON/m22 · rIOTER/eQX · lOGiC/rBS »)\n (« zCANDALER!/dPL · dR.dRE!/tRSi · aQUARIUS/oTL · sAVAGE/iNS · lOUIE/iNS »)\n (« kID cURRY/cLS · jUAN/tRSi · bOROMIR/tRSi · oRG*/x-TRADE · cYBERTRON/aFL »)\n (« eXIDOR · lUSSAR''N/rEBELS · mANTA/aC · dISC · hIJACKER/cLS · cASCADE/aFL »)\n («  pROBABLY mORE pEOPLE tHAT i cAN''T rEMEMBER! cONTACT mE fOR gREETINGS!  »)\n\n           -mY dOOR cODER rESPECT gOES tO tHESE fELLOW /X cODERS!-\n           ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n         dR.dRE!/tRSi - bObO/mYSTIC - aQUARIUS/oUTLAWS - cALYPSO/gOD\n        sIGMA/pREMIERE - bYTEANDI/tRSi - mFM/dELIGHT - mYSTIF/dELIGHT\n        p0T-nOODLE/aNTHROX - tANGO/oRIGIN - nOCTURNE/oRIGIN - rICK/cRZ\n\n @{B}@{U}Muad''Dib Greetz:@{ub}@{uu}\n\n     Killraven/MST       - Hang on dude! And make it the @{U}BEST@{uu}\n     Wishbringer/DLT     - Never stop believing in your self!!!\n     Lightning           - We Are Different (WestBam) :)\n     skate BOB/MST       - So close and still far away! stay "HIGH";)\n     Motive Power/MST    - Goodluck!\n     Jake                - Always on the fastlane...\n     Maria               - Somewhere there is love... ;)\n     Exotic/DLT          - Life isn''t easy sometimes, see the bright site!\n     Talon/DLT           - Keeping it all togheter just fine... \n     ÐEMAX^AGRESSøR/DLT  - Thanks for the support and the nice chats!\n     QuartZ/MST          - Good luck with yar phonebill :)\n\n     All @{B}Delight@{ub} members!!!\n     \n     Special hello to Delite, Scan, Zack & Veteran! And all others I forgot\n     to mention in this list.\n\n@endnode\n\n@node "5." "FastAdd v2.0 - Contact me!"\n\n \n     You can contact me at any of the CRAZE or DELIGHT boards worldwide!\n     For fast replies contact me at @{B}Instant Pleasure@{ub} +46-510-27660!\n\n     You can contact me for bugreports, suggestions etc...\n\n@endnode\n\n@node "FI" "The Easy Way..."\n\n @{B}@{U}Easy Installation:@{ub}@{UU}\n\n     If you want to install this door the easy way then simply extract\n     the archive to RAM: and run the file @{B}Install_FastAdd@{ub}. This\n     will copy the door to it''s directory and if you want installs the\n     icons too.\n\n     If you extracted the files already to RAM: then press @{"THIS" SYSTEM RAM:Install_FastAdd} button to\n     install the door.\n     \n@endnode\n\n','\n',char(10)),NULL,'auto-added',18925,4,0,NULL,NULL,'dlt_fa20','scan',1780048479);
INSERT INTO door_catalog VALUES('dlt_fc10','DLT-FC10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DLT-FC10.LHA','FastComment','XIM','FastComment',NULL,NULL,'DLT','CR/\ZE aND!       /\_\ __\ __________________  \/_/  ____________/\____ ____ _ / __  /  /_____  / ____/  /  /·  _ /',replace('                     __    ____  _     _\n  CR/\ZE aND!       /\_\ __\\n__________________  \/_/  ____________/\____\n ____ _ / __  /  /_____  / ____/  /  /·  _ /\n /  / //  ___/  /  /   \/  /  /     //   \/\n/____ /_____/_____/_____\___ /__/__/______\.\nSk¡n\/---------- PRESENTS -\/--------------+\n(« fASTcOMMENT 1.0 - cOOL! © nIKE/cRZ^dLT »)\n+------------------------------------------+\n','\n',char(10)),'FastComment.Doc',replace('    ___________   ____________   _________      ___________    _____________\n.___\___      /_._\_____     /___\______  \ ____\_____    /____\___        /\n|      /_____/  |    _|/   _/__      _____ \      _______/____ ___/       /_\n|    _/         |    \        /      \      \     \          / __________/  \\n|_______________|_____\      /________\      \______________/________________\\n-mNt/aC!               \____/          \______\\n\n                                     &\n                  _     _ ___       ___\n                            /_  __ /__/\ _\n _ ___________________________     \__\/    _____________¦_________/\______\n ________   _ /  ___    /o   /___________  /·  ______/   |   \ _      o _ /\n __/    /   //    _____//   /    /       \//   /    /         \/       \\/\n  /________ /________ /_________/_________\_______ /_____|_____\_________\\n  \_______\/\_______\/\_________\____ ____/______\/\_____¦_____/_________/\n           \/        \/              Y.           \/     ·            Sk¡n\n                                     :o\n                                    +.\n\n                     Presents another /X^S!X^F!X Door\n\n                    -^(· FastComment v1.0 by Nike ·)^-\n\nDescription:\n~~~~~~~~~~~~\nComment door. Allows a user to enter a comment to one of the sysops.\n\nFeatures:\n~~~~~~~~~\n* East to use!\n* Fast installation!\n* Nice design!\n* Arrow support!\n* Upto 99 Sysops!\n* The sysops may have different names then the one displayed!\n* You CAN have a different config file for each conference!\n\nInstallation:\n~~~~~~~~~~~~~\nMake a directory in Doors: Called "FASTCOMMENT".\nCopy the main program and the sample config file there.\nEdit the config file to suit your needs. Here is the format of it:\n-- CUT --\nnIKE\nnIKE\nThe MAIN MASTER!!\n-- CUT --\nFirst row: The name that will be displayed for the user!\nSecond Rw: The actual user name for this sysop!\nThird row: The description of the sysop!\n\nIf you would like to use a different config file for a conference, Then\ncreate a configfile with the above format, called\n<Conference Location>/FastComment.Cfg and it will use that one instead.\n\nProgram History:\n~~~~~~~~~~~~~~~~\nV1.0 - First Release Ever! Coded from scratch, eventhough i''ve released\n       another Comment door. The old one was simply to bad code to continue\n       working on!\n       This version created in less then one hour in the magnificent language\n       "E". If you are not already familiar to this language, then go get u''re-\n       self a copy, it''s the best!  \n       \nContact nIKE?!\n~~~~~~~~~~~~~~\nCall INSTANT PLEASURE (+46-510-27660) or leave a message to any CRAZE or DELIGHT\nmember and tell them to contact me. (My board has a NUP installed, so u should\nbetter get that first! =)).\nIf you want a door personally designed or have some ideas etc for doors, then\nu should contact me! I don''t charge anything for the doors..\nAlthough u could give me a card or support my board or something =)..\n\nGreetings:\n~~~~~~~~~~\n     (« aLL cRAZE ^ dELIGHT mEMBERS! · bOBO/mYSTIC · xERXES/fLT^mST »)\n    (« vEDDER/iNS · dANSKEN · aGAMEMNON/m22 · rIOTER/eQX · lOGiC/rBS »)\n  (« zCANDALER!/dPL · dR.dRE!/tRSi · aQUARIUS/oTL · sAVAGE/iNS · lOUIE/iNS »)\n (« kID cURRY/cLS · jUAN/tRSi · bOROMIR/tRSi · oRG*/x-TRADE · cYBERTRON/aFL »)\n (« eXIDOR · lUSSAR''N/rEBELS · mANTA/aC · dISC · hIJACKER/cLS · cASCADE/aFL »)\n (« uFO/oRIENT · aLL tHE oTHER fELLA''S i''VE fORGOT iN tHIS sHITTY dOC fILE! »)\n\n==============================================================================\n       And also ! Don`t forget to give these DELIGHT boards a ring !\n==============================================================================\n            DOOM OF EXTASY   *EHQ*  +49 PRIVATE !!!  [Ringdown]\n            UNDERCOVER       *SHQ*  +46 8 540 23405  [2 Nodes!]\n            DAWN RAID        *UKHQ* +44 707 320 320  [Ringdown]\n            THE UNDISCOVERED *DHQ*  +31 229 444 42   [2 Nodes!]\n            THE KREMLIN      *DST*  +7  951 255 867  [1 Node! ]\n==============================================================================\n                     AND OF COURSE THESE CRAZE BOARDS\n==============================================================================\n            INSTANT PLEASURE *WHQ*  +46 TOO ELITE!!  [1 Node! ]\n            CYBER FORCE      *SHQ*  +46 510   26683  [1 Node! ]\n            ALTERED STATE    *SHQ*  +46 TOO ELITE!!  [2 Nodes!]\n            NUCLEAR WASTE    *DST*  +46 510   27173  [1 Node! ]\n==============================================================================\n','\n',char(10)),NULL,'auto-added',11141,1,0,NULL,NULL,'dlt_fc10','scan',1780048479);
INSERT INTO door_catalog VALUES('dlt_fc14','DLT-FC14.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DLT-FC14.LHA','FileCheck','XIM','FileCheck',NULL,'Muad''Dib/DELiGHT','DLT','/\_\ __\ __________________  \/_/  ____________/\___ ____ _ / __  /  /_____  / ____/  /  /   _',replace('                     __    ____  _\n                    /\_\ __\\n__________________  \/_/  ____________/\___\n ____ _ / __  /  /_____  / ____/  /  /   _ \n /  / //  ___/  /  /   \/  /  /     //   \/\n/____ /_____/_____/_____\___ /__/__/______\\nSkin\/---------------------\/--------------\n  LHA/LZX FileCheck for Ami-X. Include user\n  name and lots more!   By Muad''Dib/DELiGHT\n','\n',char(10)),'FileCheck.guide',replace('@DATABASE "LHA/LZX FileCheck v1.4"\n@$VER: FileCheck v1.4 - Guide v1.0\n@author "Muad''Dib/DELiGHT"\n@(c) "Muad''Dib/DELiGHT"\n\n@NODE MAIN "LHA/LZX FileCheck v1.4"\n                                                     _____\n     _____________________________   ______________ |     |_______________\n     \_______  \   ______/       /  (______)  ____/_|_   _| \_____  _____/\n     |      /   \_ ___)_\_   ___/___/      \_ \__     |  \_     |    |\n     |     /     / \      |  \     \        /   |     |   |     |    |\n     |__________/_________|_________\_____ /____|_____|___|_____|____|\n +-Mo!/f^I- - -- - -- - -- - -- - -- - --\/- -- - -- - - -- - -- - -- - -- -+\n\n                  )-- LHA/LZX FileChecker for AmiExpress --(\n                   )-- version 1.4 released on 18-02-95 --(\n                      )--  Made by Muad''Dib/DELiGHT --(\n\n                @{" Another Checker! " Link Intro}       @{"    Problems?!    " Link Problems}\n                @{"   Installation   " Link Install}       @{" Greets & Thanks! " Link Greets}\n                @{"      Options     " Link Options}       @{"    Contact me    " Link Contact}\n\n\n                               @{" What''s next? " Link Next}\n@endnode\n\n@node "Intro" "LHA/LZX FileCheck v1.4 - Another one!?"\n\n  @{B}@{U}Yes another filechecker for Ami-X.@{ub}@{UU}\n  \n  With the difference that this one can check LZX files as well. And this\n  one has some very nice @{"options" link "Options" 0} \n  \n  Before I released this checker I gave it to 5 other sysops and listened\n  to there requests. I put as much functions in the checker as we thought\n  would be easy.   \n  \n  The door has now come to a point it''s worth releasing. Let me know what\n  you think about this tool.\n  \n  @{"How to let me know?" link "Contact" 0}\n\n@endnode\n\n@node "Install" "LHA/LZX FileCheck v1.4 - How to install?"\n\n@{B} @{U}How to install FileCheck?@{ub}@{UU}\n\n  All files are in the directories where they should be.\n  \n  Copy the @{B}FCheck@{ub} directory to BBS:FCheck/\n  Copy the @{B}DLT_FileCheck@{ub} directory to your Doors: directory.\n\n  Edit the icons in the FCheck directory to your need. You will find the\n  keyword @{B}OPTIONS=@{ub}. Here you can put your own options. \n  For more information about the options go to @{"options" link "Options" 0}.\n\n  In the DLT_FileCheck directory you will find the following files:\n  \n     FileCheck           - The executable\n     FileCheck.guide     - This file\n     FromWho             - Example add with user''s information\n     Strip.List          - Listing with files to strip from LHA files\n     Add.List            - Listing with files to include for LHA files\n\n  If you are using the @{B}A@{ub} option you need to make the assign ADD:\n  All files in the ADD: assign will be included. Also dirs!!\n  \n  To work FileCheck need LHA and LZX in your C: directory. If you want to\n  use the IStrip function you need IStrip in C: as well.\n\n@endnode\n\n@node "Options" "LHA/LZX FileCheck v1.4 - Options"\n\n@{B} @{U}Options@{ub}@{UU}\n\n  When you start FileCheck from cli without any options you will get this\n  output:\n\n     LHA/LZX Checker for AmiExpress. v1.4\n     Usage: FileCheck <options> <file to check>\n     Options:\n      a - Add files from Doors:DLT_FileCheck/Add.List (only lha!)\n      A - Add all files from assign ADD: (directories included)\n      c - Check file - No output. (/X will not know if the file is corrupt!!)\n      C - Check file\n      s - Strip file - No output. (From file Doors:DLT_FileCheck/Strip.List)\n      S - Strip file\n      i - Enable IStrip on LHA archives - No output.\n      I - Enable IStrip on LHA archives\n      + - Show node and date/time\n      - <filesize> - If the filesize is bigger then <filesize> then skip checking.\n      $ <filename> - Make Add (include UL name and Location)\n\n  You can place every option at any place. As long as the @{B}-@{ub} and @{B}$@{ub}\n  are followed with some output. E.G.:\n\n  You want to add files from the ADD: assign, check it and see some output,\n  don''t want to strip the file, see some more info and include one special\n  add with the user''s name and location. From CLI you would type:\n  \n       FileCheck + Doors:UploadedByMe A C $ <filename> \n  \n\n@{B} @{U}All options explained:@{ub}@{UU}\n  \n  a - This option will search for the file Add.List in Doors:DLT_FileCheck\n      directory. In this list you can specify which adds you want to include.\n      This option ONLY works with LHA/LZH archives and *NOT* with LZX files.\n      This is due the lack of the -i option in LZX. Hopefully this will be\n      available in the registered version of LZX.\n  A - The same as the option above, only this option includes all files in\n      the assign ADD:. This will work for LHA/LZH/LZX files. You can even\n      put some directories in this assign and they will also be included.\n \n  c - Check the file but don''t show the output to the user. When you use this\n      /X will not know if a file is corrupt or not. So i would not suggest\n      to use this one.\n  C - Check the file and show the output to the user.\n\n  s - Strip an LHA/LZH archive. This one uses the file Strip.List in the\n      Doors:DLT_FileCheck directory. As the a option this will only work\n      with LHA/LZH archives. It shows NO output.\n  S - The same as option s only the output is shown.\n\n  i - IStrip. When you have this programm in your C: directory FileCheck\n      can execute it. IStrip is a powerfull stripper and should be available.\n  I - Now FileCheck the output of IStrip is shown to the user.\n\n  + - If you turn this on FileCheck will show the filesize, node number and\n      if you use the $ option. It''s best to see it for your self to see what\n      I mean.\n\n  - - Since LHA/LZH/LZX files are getting bigger and bigger the checking time\n      takes longer and longer. If you use the - option followed by a size in\n      bytes FileCheck will see if the file is bigger then the given size and\n      disable the stripping (LHA) and the checking of the archive. The Add\n      function will stay on if you turned it on.\n\n  $ - When you have an add where you want to include the user''s stats\n      you can put the path+filename after this. FileCheck will replace some\n      keywords with the data they represent:\n      \n           ===!UPLOADER!===        - replaced with the user''s name\n          ====!LOCATION!====       - replaced with the user''s location\n               =!DATE!=            - current date\n               =!TIME!=            - current time\n                  @#               - node number\n\n     If you use FileCheck not from /X then the $ option will be ignored.\n     An example file is included called @{"FromWho" link "FromWho" 0}.\n@endnode\n\n@node "FromWho" "FastAdd v2.0 - Options - Example"\n\n_____  /\______.___  ______  _\n\____\/____/   |  ¬\/  __ ¬\_\ -  -- --- ---------------------------------.\n_/   \/  ¬\_   _    \_ \____/__     >.T.H.E. .U.N.D.I.S.C.O.V.E.R.E.D.<   ¦\n\_____     /___|     /___     /:.   >.+31.229.444.42...+31.229.414.42.<   !\n-:---l____/----l____/---\____/---- --- --- --  -     >.+31.229.4ELITE.<   :\n ¡                   ______.                         ________             |\n |   DELiGHT DHQ!    \     |___  ____ .____ _  ______\      /______       O\n O  MYSTiC BETA HQ   \\_   |  ¬\/    \|   _____\__  ¬\\____/    __/__  /\ |\n |    iNFECT EHQ     _/    ·    \_   \\   ¬\_    |    \_  ¬\______  ¬\_\//¡\n ¦                  .\___________/___|\_____/_____     /____/   ______/ · :\n :        - -- --- ------------------------------l____/--\______/------   .\n . _ ______   _____________. ___________    _______ _ _____    ________ _ :\n : //  ___/__/   __ ¬\     |/     / __ ¬\___\____ ¬\_  __ ¬\___\____  ¬\\ ¦\n ._/   |    ¬\_  \/   \_   ·     /  \____/__   \/  _/  \____/__    |    \_:\n |\_____      /________/   _____/ _ __     /___/    \____     /_____     /|\n :-----l_____/-------|_____/-sTZ!/6c-\____/----\_____/--\____/-----l____/-:\n !                                                                        !\n |         UPLOADED BY: ===!UPLOADER!===   FROM: ====!LOCATION!====       |\n ¦                  UPLOADED ON =!DATE!= / =!TIME!= / #@#                 ¦\n ¦------------------------------------------------------------------------¦\n | [MUAD''DiB/DLT]  [WISHBRINGER/DLT]  [MOTIVE POWER/MST]  [KiLLRAVEN/MST] |\n ¦                               [JAKE/PSG]                               ¦\n : >.A.M.I.G.A.<>.C.O.N.S.O.L.E.<>.6.8.O.4.O.P.0.W.E.R.<>.U.S.R.2.8.K.8.< :\n `------------------------------------------------------------------------''\n\n@endnode\n\n@node "Problems" "LHA/LZX FileCheck v1.4 - Problems?"\n\n@{U}@{B} Problems:@{ub}@{UU}\n\nP:    There are no files included in my LZX archive!\n     \nA:    Probably you used the a option. It is not yet possible to include\n      files from a list in LZX files.\n\nP:    FileCheck tells me Strip, Check are off. But in the icon I put them\n      on!\n\nA:    If you make use of the - option and a file is bigger, then the checker\n      disables the Strip and Check routines.\n      If you use the a options with an LZX file the Option is turned of\n      automatically.\n      \nIf you have another problem please @{"contact" link "Contact" 0} me!\n\n@endnode\n\n@node "Greets" "LHA/LZX FileCheck v1.4 - Greets and Thanks"\n\n @{B}@{U}Thanks:@{UU}@{ub}\n\n     Killraven/MST       - 24 hours a day help thanks for all routines,\n                           explenations etc.\n\n     Betatesters:\n\n     Motive Power/MST ^ Jake/MiRAGE ^ Delite ^ Veteran ^ Eurobyte ^ D`Style\n\n @{B}@{U}Greets go to:@{UU}@{ub}\n\n         ^ All @{B}Delight@{ub} members!!! ^ Talon ^ Killraven ^ Wishbringer ^\n      ^ Lightning ^ Delite ^ Veteran ^ Eurobyte ^ D`Style ^ Skate BOB ^\n            ^ Quartz ^ Motive Power ^ Jake ^ all dudes in Houten ^\n                 ^--- And all others I forgot to mention ---^\n\n@endnode\n\n@node "Contact" "LHA/LZX FileCheck v1.4 - Contact me!"\n\n               If you want to contact me call The Undiscovered:\n                        +31-2294-4442/1442 28k8 USR DS\n\n                        or leave me mail on internet:\n                              [email removed]\n\n@endnode\n\n@node "Next" "LHA/LZX FileCheck v1.4 - Next!"\n\n @{B}@{U}What''s next?@{ub}@{UU}\n\n   Already there are some requests:\n   \n   random names for includes and random from a list of BBS adds.    Delite\n   Left/Right/Center justify for user name in BBS add.              D`Style\n   Good strip routine for LZX files.\n   \n   There is being worked on these. If you want something in this tool\n   yourself please @{"contact" link "Contact" 0} me.\n     \n@endnode\n\n','\n',char(10)),NULL,'auto-added',22026,3,0,NULL,NULL,'dlt_fc14','scan',1780048479);
INSERT INTO door_catalog VALUES('dlt_fx10','DLT-FX10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DLT-FX10.LHA','FastComment','XIM','FastComment',NULL,NULL,'DLT','CR/\ZE aND!       /\_\ __\ __________________  \/_/  ____________/\____ ____ _ / __  /  /_____  / ____/  /  /·  _ /',replace('                     __    ____  _     _\n  CR/\ZE aND!       /\_\ __\\n__________________  \/_/  ____________/\____\n ____ _ / __  /  /_____  / ____/  /  /·  _ /\n /  / //  ___/  /  /   \/  /  /     //   \/\n/____ /_____/_____/_____\___ /__/__/______\.\nSk¡n\/---------- PRESENTS -\/--------------+\n(« fASTcOMMENT 1.0 - fIXED © nIKE/cRZ^dLT »)\n+------------------------------------------+\n','\n',char(10)),'FastComment.Doc',replace('    ___________   ____________   _________      ___________    _____________\n.___\___      /_._\_____     /___\______  \ ____\_____    /____\___        /\n|      /_____/  |    _|/   _/__      _____ \      _______/____ ___/       /_\n|    _/         |    \        /      \      \     \          / __________/  \\n|_______________|_____\      /________\      \______________/________________\\n-mNt/aC!               \____/          \______\\n\n                                     &\n                  _     _ ___       ___\n                            /_  __ /__/\ _\n _ ___________________________     \__\/    _____________¦_________/\______\n ________   _ /  ___    /o   /___________  /·  ______/   |   \ _      o _ /\n __/    /   //    _____//   /    /       \//   /    /         \/       \\/\n  /________ /________ /_________/_________\_______ /_____|_____\_________\\n  \_______\/\_______\/\_________\____ ____/______\/\_____¦_____/_________/\n           \/        \/              Y.           \/     ·            Sk¡n\n                                     :o\n                                    +.\n\n                     Presents another /X^S!X^F!X Door\n\n                    -^(· FastComment v1.0 by Nike ·)^-\n\nDescription:\n~~~~~~~~~~~~\nComment door. Allows a user to enter a comment to one of the sysops.\n\nFeatures:\n~~~~~~~~~\n* Easy to use!\n* Fast installation!\n* Nice design!\n* Arrow support!\n* Upto 99 Sysops!\n* The sysops may have different names then the one displayed!\n* You CAN have a different config file for each conference!\n\nInstallation:\n~~~~~~~~~~~~~\nMake a directory in Doors: Called "FASTCOMMENT".\nCopy the main program and the sample config file there.\nEdit the config file to suit your needs. Here is the format of it:\n-- CUT --\nnIKE\nnIKE\nThe MAIN MASTER!!\n-- CUT --\nFirst row: The name that will be displayed for the user!\nSecond Rw: The actual user name for this sysop!\nThird row: The description of the sysop!\n\nIf you would like to use a different config file for a conference, Then\ncreate a configfile with the above format, called\n<Conference Location>/FastComment.Cfg and it will use that one instead.\n\nProgram History:\n~~~~~~~~~~~~~~~~\nV1.0 - First Release Ever! Coded from scratch, even though i''ve released\n       another Comment door. The old one was simply to bad code to continue\n       working on!\n       This version created in less then one hour in the magnificent language\n       "E". If you are not already familiar to this language, then go get u''re-\n       self a copy, it''s the best!  \n       \nContact nIKE?!\n~~~~~~~~~~~~~~\nCall INSTANT PLEASURE (+46-510-27660) or leave a message to any CRAZE or DELIGHT\nmember and tell them to contact me. (My board has a NUP installed, so u should\nbetter get that first! =)).\nIf you want a door personally designed or have some ideas etc for doors, then\nu should contact me! I don''t charge anything for the doors..\nAlthough u could give me a card or support my board or something =)..\n\nGreetings:\n~~~~~~~~~~\n     (« aLL cRAZE ^ dELIGHT mEMBERS! · bOBO/mYSTIC · xERXES/fLT^mST »)\n    (« vEDDER/iNS · dANSKEN · aGAMEMNON/m22 · rIOTER/eQX · lOGiC/rBS »)\n  (« zCANDALER!/dPL · dR.dRE!/tRSi · aQUARIUS/oTL · sAVAGE/iNS · lOUIE/iNS »)\n (« kID cURRY/cLS · jUAN/tRSi · bOROMIR/tRSi · oRG*/x-TRADE · cYBERTRON/aFL »)\n (« eXIDOR · lUSSAR''N/rEBELS · mANTA/aC · dISC · hIJACKER/cLS · cASCADE/aFL »)\n (« uFO/oRIENT · aLL tHE oTHER fELLA''S i''VE fORGOT iN tHIS sHITTY dOC fILE! »)\n\n==============================================================================\n       And also ! Don`t forget to give these DELIGHT boards a ring !\n==============================================================================\n            DOOM OF EXTASY   *EHQ*  +49 PRIVATE !!!  [Ringdown]\n            UNDERCOVER       *SHQ*  +46 8 540 23405  [2 Nodes!]\n            DAWN RAID        *UKHQ* +44 707 320 320  [Ringdown]\n            THE UNDISCOVERED *DHQ*  +31 229 444 42   [2 Nodes!]\n            THE KREMLIN      *DST*  +7  951 255 867  [1 Node! ]\n==============================================================================\n                     AND OF COURSE THESE CRAZE BOARDS\n==============================================================================\n            INSTANT PLEASURE *WHQ*  +46 TOO ELITE!!  [1 Node! ]\n            CYBER FORCE      *SHQ*  +46 510   26683  [1 Node! ]\n            ALTERED STATE    *SHQ*  +46 TOO ELITE!!  [2 Nodes!]\n            NUCLEAR WASTE    *DST*  +46 510   27173  [1 Node! ]\n==============================================================================\n','\n',char(10)),NULL,'auto-added',7251,1,0,NULL,NULL,'dlt_fx10','scan',1780048479);
