INSERT INTO door_catalog VALUES('dlt_gms','DLT-GMS.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DLT-GMS.LHA','Gms','XIM','Gms',NULL,NULL,'DLT','CR/\ZE aND!       /\_\ __\ __________________  \/_/  ____________/\____ ____ _ / __  /  /_____  / ____/  /  /·  _ /',replace('                     __    ____  _     _\n  CR/\ZE aND!       /\_\ __\\n__________________  \/_/  ____________/\____\n ____ _ / __  /  /_____  / ____/  /  /·  _ /\n /  / //  ___/  /  /   \/  /  /     //   \/\n/____ /_____/_____/_____\___ /__/__/______\.\nSk¡n\/---------- PRESENTS -\/--------------+\n(« gLOBAL mAIL sCAN dOOR - © nIKE/cRZ^dLT »)\n+------------------------------------------+\n','\n',char(10)),'Gms.Doc',replace('    ___________   ____________   _________      ___________    _____________\n.___\___      /_._\_____     /___\______  \ ____\_____    /____\___        /\n|      /_____/  |    _|/   _/__      _____ \      _______/____ ___/       /_\n|    _/         |    \        /      \      \     \          / __________/  \\n|_______________|_____\      /________\      \______________/________________\\n-mNt/aC!               \____/          \______\\n\n                                     &\n                  _     _ ___       ___\n                            /_  __ /__/\ _\n _ ___________________________     \__\/    _____________¦_________/\______\n ________   _ /  ___    /o   /___________  /·  ______/   |   \ _      o _ /\n __/    /   //    _____//   /    /       \//   /    /         \/       \\/\n  /________ /________ /_________/_________\_______ /_____|_____\_________\\n  \_______\/\_______\/\_________\____ ____/______\/\_____¦_____/_________/\n           \/        \/              Y.           \/     ·            Sk¡n\n                                     :o\n                                    +.\n\n                  -^(· pRESENTS iN tHE yEAR oF 1994! ·)^-\n\n                 -^(· gLOBAL mAIL sCAN v1.0a bY nIKE! ·)^-\n\nIntroduction:\n=============\nGlobal scanning for mail.\nIt will scan all areas for mail so u don''t have to join each conference\nsingle handed..\nNB: This door was made in about 2-3 minutes so don''t expect too much by it!\n\nInstallation:\n=============\nCopy the files as they are when u unpacked the archive.\n\nHistory:\n========\nv1.0    - This version.\n\nGreetings:\n==========\n     (« aLL cRAZE ^ dELIGHT mEMBERS! · bOBO/mYSTIC · xERXES/fLT^mST »)\n    (« vEDDER/iNS · dANSKEN · aGAMEMNON/m22 · rIOTER/eQX · lOGiC/rBS »)\n  (« zCANDALER!/dPL · dR.dRE!/tRSi · aQUARIUS/oTL · sAVAGE/iNS · lOUIE/iNS »)\n (« kID cURRY/cLS · jUAN/tRSi · bOROMIR/tRSi · oRG*/x-TRADE · cYBERTRON/aFL »)\n (« eXIDOR · lUSSAR''N/rEBELS · mANTA/aC · dISC · hIJACKER/cLS · cASCADE/aFL »)\n (« uFO/oRIENT · aLL tHE oTHER fELLA''S i''VE fORGOT iN tHIS sHITTY dOC fILE! »)\n\nSince everybody else write like "musical support" and shit, i''ll write it too!\n==============================================================================\n             NiRVANA ^ GREEN DAY ^ VARiOUS MODULES ^ PEARL JAM\n==============================================================================\n','\n',char(10)),NULL,'auto-added',22090,4,0,NULL,NULL,'dlt_gms','scan',1780048479);
INSERT INTO door_catalog VALUES('dlt_hi10','DLT-HI10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DLT-HI10.LHA',NULL,'XIM','<«»«»«»(·eVERYwARE!  ÷  tRSi^aCCESs·)«»«»«»>',NULL,'NiKE/DLT^CRZ','DLT','___                      ___ ____|__ |_______ _______. ___|_  |_.________ \   __/ |\ __  /_\   /\_|/     \ | |  _    /',replace('<«»«»«»(·eVERYwARE!  ÷  tRSi^aCCESs·)«»«»«»>\n     ___                      ___\n____|__ |_______ _______. ___|_  |_.________\n\   __/ |\ __  /_\   /\_|/     \ | |  _    /\n \  \   /  ___/ /   /__ |  /__ / _ |  /___/ \n  \____/_______/______/_|____//__| |___|-Mo!\n<---------------- -- - _:____/---|___|----->\n<-- - HANGiT v1.0 bY NiKE/DLT^CRZ ''95! - -->\n<------------------------------------------>\n','\n',char(10)),'Hangit.Doc',replace(' __________\n \_____  ·/\ __________________________________________________________.\n  \/  / // /                                                           |\n  /____ / /                D   E   L   ¡   G   H   T                  o|\n  \___\/ /                       · PRESENTS ·                         ¦|\n  ¦  __\/__                                                           ·|\n  | /\  ___\                                                           |\n  | \ \  _)/_  ___   ___      ______            _______                |\n  |__\ \_____\/  /__/__/\    /o____/\ _____    /·_____ _ ______________|\n      \/_____/  /  /\__\ \  // /  /\/\  \  \  // /\__ _ __         Sk¡n\n            /____ / /\  \ \/____ / /\ \     \/__/ /\n            \___\/ /  \__\/\___\/ /  \ \__\__\__\/\n                 \/             \/    \/__/__/\n\n\n                   [%] · HangIt v1.0 by nIKE/dLT! · [%]\n\n  Description.\n--============--\nAsks user to hangup before the FILE_ID.DIZ''s are extracted. Thought there\nare several on the market this one asks before the first is extracted.\n\n  Installation.\n--=============--\nCopy the files as they are, experienced sysops should have NO difficulties.\nNOTE! The door is ONLY tested vs FILEDESCRIPTION by Bobo. It did not work\n      with it so use the supplied modified version.\n      Other FILE_ID.DIZ Extract-doors should work, but if they do not then\n      Try this:\n      1) Load the executable file into CED or HEX or something similar.\n      2) Search for "EXAMINE" (No quotes) and replace it with "EXAMIN1"\n      3) Most doors should now work.\n\n-------------------------[ DELiGHT AMiGA BOARDS ]---------------------------\n\n    DIGITAL EXTASY   [World    HQ]   +1.201.345.7102 -  4 RINGDOWN\n    DOOM OF EXTASY   [European HQ]  +49.234.921.0347 -  3 RINGDOWN\n                                    +49.234.927.0840 -  2 ISDN RGDN\n    DAWN-RAID        [UK       HQ]  +44.170.732.0320 -  21K6\n                                    +44.170.739.2317 -  14K4\n                                    +44.170.739.2453 -  2 x 28K8\n    UNDERCOVER       [Swedish  HQ]  +46.854.023.405  -  16K8\n                                    +46.854.066.627  -  28K8\n    TOTAL RECALL     [Italian  HQ]  +39.861.414.938  -  1 NODE  \n    MENTAL HANGOVER  [ Dist Site ]  +41.817.715.253  -  1 NODE\n    CHECKPOINT       [ Dist Site ]  +47.515.931.23   -  2 RINGDOWN\n\n\n-------------------------[ CRZ/PSE! AMiGA BOARDS ]---------------------------\n\n    INSTANT PLEASURE [World    HQ]     +46.510.27660 - 2 NODES\n    EVERYWARE        [Norwegi. HQ]     +47.639.54190 - 1 NODE\n    NUCLEAR WASTE    [Swedish  HQ]     +46.510.27173 - 1 NODE\n    THE CHAMELEON    [Finnish  HQ]   +358.81.5522597 - 3 NODES\n    BATTLEFIELD      [Danish   HQ]     +45.3646.3360 - 1 NODE\n\n\n\n\nIf you need to contact me!\n\nCall any of the above boards and tell any DLT or PSE member!\n','\n',char(10)),NULL,NULL,24022,1,0,NULL,NULL,NULL,'scan',1780048479);
INSERT INTO door_catalog VALUES('dlt_lc12','DLT-LC12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DLT-LC12.LHA','LhaCheck','XIM','LhaCheck',NULL,NULL,'DLT','CR/\ZE aND!       /\_\ __\ __________________  \/_/  ____________/\____ ____ _ / __  /  /_____  / ____/  /  /·  _ /',replace('                     __    ____  _     _\n  CR/\ZE aND!       /\_\ __\\n__________________  \/_/  ____________/\____\n ____ _ / __  /  /_____  / ____/  /  /·  _ /\n /  / //  ___/  /  /   \/  /  /     //   \/\n/____ /_____/_____/_____\___ /__/__/______\.\nSk¡n\/---------- PRESENTS -\/--------------+\n(« lHAcHECK 1.2 sUPPORTING oNElINE aDDS!! »)\n+------------------------------------------+\n','\n',char(10)),'LhaCheck.Doc',replace('    ___________   ____________   _________      ___________    _____________\n.___\___      /_._\_____     /___\______  \ ____\_____    /____\___        /\n|      /_____/  |    _|/   _/__      _____ \      _______/____ ___/       /_\n|    _/         |    \        /      \      \     \          / __________/  \\n|_______________|_____\      /________\      \______________/________________\\n-mNt/aC!               \____/          \______\\n\n                                     &\n                  _     _ ___       ___\n                            /_  __ /__/\ _\n _ ___________________________     \__\/    _____________¦_________/\______\n ________   _ /  ___    /o   /___________  /·  ______/   |   \ _      o _ /\n __/    /   //    _____//   /    /       \//   /    /         \/       \\/\n  /________ /________ /_________/_________\_______ /_____|_____\_________\\n  \_______\/\_______\/\_________\____ ____/______\/\_____¦_____/_________/\n           \/        \/              Y.           \/     ·            Sk¡n\n                                     :o\n                                    +.\n\n                     Presents another /X^S!X^F!X Door\n\n                     -^(· LhaCheck v1.2 by Nike ·)^-\n\nDescription:\n~~~~~~~~~~~~\nAnother LHA Stripper, But this one is supporting the standard you can read\nabout in the acompanied file "ADDS.TXT".\n\nFeatures:\n~~~~~~~~~\n* Of course, As fast as all other Lha strippers!\n* One-Line add   * OR *  normal file adding.\n\nInstallation:\n~~~~~~~~~~~~~\n1. Copy LHACHECK to C:\n2. Copy the config files to S:\n3. Edit the file S:LHACHECK.CFG.\n   If you want to add a one-liner then do enter THIS:\n   Row 1: PASSED\n   Row 2: U''re BBS'' Phone Number (14 chars)\n   Row 3: The oneline add (42 chars)\n   If u write something else then PASSED on the first line, normal file\n   adding will be used. Enter the files to be added in the file S:LHACHECK.ADD\n   and of course a list of files that will be deleted from the archives,\n   S:LHACHECK.OMIT (The stripper will always try to DELETE files BEFORE adding,\n   so even if u use the PASSED option, it will still strip other adds!)\n\nUsage:\n~~~~~~\nCopy the icons in FCHECK to BBS:FCHECK/ and of u go!\n\nProgram History:\n~~~~~~~~~~~~~~~~\nV1.0 - First Release Ever!\nV1.1 - Didn''t show all files that we''re tested!\nV1.2 - Added "PASSED" option.\n\nContact nIKE?!\n~~~~~~~~~~~~~~\nCall INSTANT PLEASURE (+46-510-27660) or leave a message to any CRAZE or DELIGHT\nmember and tell them to contact me. (My board has a NUP installed, so u should\nbetter get that first! =)).\nIf you want a door personally designed or have some ideas etc for doors, then\nu should contact me! I don''t charge anything for the doors..\nAlthough u could give me a card or support my board or something =)..\n\nGreetings:\n~~~~~~~~~~\n     (« aLL cRAZE ^ dELIGHT mEMBERS! · bOBO/mYSTIC · xERXES/fLT^mST »)\n    (« vEDDER/iNS · dANSKEN · aGAMEMNON/m22 · rIOTER/eQX · lOGiC/rBS »)\n  (« zCANDALER!/dPL · dR.dRE!/tRSi · aQUARIUS/oTL · sAVAGE/iNS · lOUIE/iNS »)\n (« kID cURRY/cLS · jUAN/tRSi · bOROMIR/tRSi · oRG*/x-TRADE · cYBERTRON/aFL »)\n (« eXIDOR · lUSSAR''N/rEBELS · mANTA/aC · dISC · hIJACKER/cLS · cASCADE/aFL »)\n (« uFO/oRIENT · aLL tHE oTHER fELLA''S i''VE fORGOT iN tHIS sHITTY dOC fILE! »)\n\nSince everybody else write like "musical support" and shit, i''ll write it too!\n==============================================================================\n                                 MODS ETC!\n==============================================================================\n\n       And also ! Don`t forget to give these DELIGHT boards a ring !\n\n            DOOM OF EXTASY   *EHQ*  +49 PRIVATE !!!  [Ringdown]\n            UNDERCOVER       *SHQ*  +46 8 540 23405  [2 Nodes!]\n            DAWN RAID        *UKHQ* +44 707 320 320  [Ringdown]\n            THE UNDISCOVERED *DHQ*  +31 229 444 42   [2 Nodes!]\n            THE KREMLIN      *DST*  +7  951 255 867  [1 Node! ]\n\n                     AND OF COURSE THESE CRAZE BOARDS\n\n            INSTANT PLEASURE *WHQ*  +46 TOO ELITE!!  [1 Node! ]\n            CYBER FORCE      *SHQ*  +46 510   26683  [1 Node! ]\n            ALTERED STATE    *SHQ*  +46 TOO ELITE!!  [2 Nodes!]\n            NUCLEAR WASTE    *DST*  +46 510   27173  [1 Node! ]\n\n==============================================================================\n','\n',char(10)),NULL,'auto-added',11425,3,0,NULL,NULL,'dlt_lc12','scan',1780048479);
INSERT INTO door_catalog VALUES('dlt_md10','DLT-MD10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DLT-MD10.LHA','MultiDoor','XIM','MultiDoor',NULL,NULL,'DLT','CR/\ZE aND!       /\_\ __\ __________________  \/_/  ____________/\____ ____ _ / __  /  /_____  / ____/  /  /·  _ /',replace('                     __    ____  _     _\n  CR/\ZE aND!       /\_\ __\\n__________________  \/_/  ____________/\____\n ____ _ / __  /  /_____  / ____/  /  /·  _ /\n /  / //  ___/  /  /   \/  /  /     //   \/\n/____ /_____/_____/_____\___ /__/__/______\.\nSk¡n\/---------- PRESENTS -\/--------------+\n(« mULTIdOOR v1.0 - cOOOL! © nIKE/cRZ^dLT »)\n+------------------------------------------+\n','\n',char(10)),'MultiDoor.Doc',replace('    ___________   ____________   _________      ___________    _____________\n.___\___      /_._\_____     /___\______  \ ____\_____    /____\___        /\n|      /_____/  |    _|/   _/__      _____ \      _______/____ ___/       /_\n|    _/         |    \        /      \      \     \          / __________/  \\n|_______________|_____\      /________\      \______________/________________\\n-mNt/aC!               \____/          \______\\n\n                                     &\n                  _     _ ___       ___\n                            /_  __ /__/\ _\n _ ___________________________     \__\/    _____________¦_________/\______\n ________   _ /  ___    /o   /___________  /·  ______/   |   \ _      o _ /\n __/    /   //    _____//   /    /       \//   /    /         \/       \\/\n  /________ /________ /_________/_________\_______ /_____|_____\_________\\n  \_______\/\_______\/\_________\____ ____/______\/\_____¦_____/_________/\n           \/        \/              Y.           \/     ·            Sk¡n\n                                     :o\n                                    +.\n\n                       Presents another /X^S!X Door\n\n                     -^(· MultiNew v1.1 by Nike ·)^-\n                      -^(· Dox by ORGASMATRON! ·)^-\n\nDescription:\n~~~~~~~~~~~~\nKind  of  "Frontdoor" for doors.  This one let you choose your favourite\ndoor  to  use.  I.e.  You can choose which NEWFILE SCAN door you want to\nuse (TURBO_NEWSCAN, CONFERENCE_SCANNER and so on).\n\nFeatures:\n~~~~~~~~~\n* Transparent for the called doors\n* Easy to use\n* Fast and easy installation\n* No need of Thunderhoney!\n*  You  don''t  need  to  use  that  irritating  door  that the sysop has\n   installed as "default".\n\nInstallation:\n~~~~~~~~~~~~~\n\n1. Copy program files into DOORS:MULTIDOOR/ (THEY MUST BE HERE!)\n2. Edit the config file for your personal needs (more about that later)\n3. Copy the INFO into BBS:COMMANDS/BBSCMD/N.INFO,(or whatever you are going\n   to replace with this cool command) and edit the AXS level for it. \n   Preferably it should be at 20. \n4. TEST IT!\n5. You can change your selection with "<name> -CFG"\n\nThe  configfiles for the commands that you shall replace *MUST* be named\nwith this pattern "MULTI_<name>.CFG" Check the included examples for more\ninformation.\n\nUsage:\n~~~~~~\nAt  first  use the door will ask you for your door selection.  In future\nuse the door will automaticly call the door you choosed.  If you want to\nchoose another door just enter ''<name> -CFG'' to select another one.\n\nConfig:\n~~~~~~~\nIf  you  would  like  to  install this door as "N" then do it like this:\nMake a config file called DOORS:MULTIDOOR/MULTI_N.CFG with the following\nformat:\n\n----8<--------8<--------8<--------8<--------8<--------8<--------8<----\n1N\nNight-Scanner V1.0 (Good options to use!, By NOC-TURNE)\nTN\nTurbo Newscan Pro 2.z (Mack Lifeguard/DCS) *FASTEST* \nFR\nFiles Reverse V1.0 (Checks files in reverse order, by NOC-TURNE)\n2N\nNewfiles (Default at AnGEL CiTY) by Killraven/MST)\nCS\nConference Scan (checks all conferences, by Killraven/MST)\n----8<--------8<--------8<--------8<--------8<--------8<--------8<----\n\nLooks  strange?   Well,  "1N"  is the command-name for NIGHT-SCANNER and\nthis  is  were you type the names you use to call the doors (i.e.  "N").\nThe  second  row  is  the  decsription that MULTIDOOR will show when you\nselects  the doors.  This is all you have to do.  If you want to install\nanother  command  just name it like "DOORS:MULTIDOOR/MULTI_O.CFG".  Easy\nhuh?   But  don''t  forget  that  the  commands you want to use *MUST* be\ninstalled with it''s ICON in the BBSCMD directory.\n\nProgram Logic:\n~~~~~~~~~~~~~~\nIf  you  I.E.   install this door as the N command.  MultiDoor will look\nfor  the  file "Doors:MultiDoor/Multi_N.Cfg".  (Check the CONFIG part of\nthe  doc  for  more  info).   If it''s found, the door will try to locate\n"Doors:MultiDoor/Multi_N.Data".   If  that is found, the door will check\nfor  the  users config in it.  If the door finds it, it will execute the\ndoor  with  the  arguments  that  is sent to MultiDoor.  If not, it will\ndisplay  a  list of the doors he can select, and what he chooses will be\nadded  to the datafile!  After this the door will work FULLY transparent\nbeteween the command prompt and the choosed door.\n\nProgram History:\n~~~~~~~~~~~~~~~~\nv0.1 - First version.  This was called "MULTINEW" and could only be installed\n       on the N command.  The idea for this door came from Zcandaler and\n       ORGASMATRON!, and they wanted it almost at the same time..!  Cool eh?\n       Only released to beta testers and some others...\n\nv1.0 - This version.  Now showing a banner so the user understands that he can\n       at any time change door at this command with the -CFG option.  Also\n       added the gr8 feature to make it installable on all commands.  Ideas by\n       ORGASMATRON!  and myself!  =) Documenation totaly rewriten and improved\n       by ORG*\n\nContact nIKE?!\n~~~~~~~~~~~~~~\nCall INSTANT PLEASURE (+46-510-27660) or leave a message to any CRAZE or\nDELIGHT  member  and  tell  them  to  contact  me.   (My board has a NUP\ninstalled,  so u should better get that first!  =)).  If you want a door\npersonally  designed  or  have  some  ideas etc for doors, then u should\ncontact  me!   I don''t charge anything for the doors..  Although u could\ngive me a card or support my board or something =)..\n\nGreetings:\n~~~~~~~~~~\n     (« aLL cRAZE ^ dELIGHT mEMBERS! · bOBO/mYSTIC · xERXES/fLT^mST »)\n    (« vEDDER/iNS · dANSKEN · aGAMEMNON/m22 · rIOTER/eQX · lOGiC/rBS »)\n  (« zCANDALER!/dPL · dR.dRE!/tRSi · aQUARIUS/oTL · sAVAGE/iNS · lOUIE/iNS »)\n (« kID cURRY/cLS · jUAN/tRSi · bOROMIR/tRSi · oRG*/x-TRADE · cYBERTRON/aFL »)\n (« eXIDOR · lUSSAR''N/rEBELS · mANTA/aC · dISC · hIJACKER/cLS · cASCADE/aFL »)\n (« uFO/oRIENT · aLL tHE oTHER fELLA''S i''VE fORGOT iN tHIS sHITTY dOC fILE! »)\n\nSince everybody else write like "musical support" and shit, i''ll write it too!\n==============================================================================\n      NiRVANA ^ GREEN DAY ^ VARiOUS MODULES ^ PEARL JAM ^ NOT CAROLA\n==============================================================================\n       And also ! Don`t forget to give these DELIGHT boards a ring !\n==============================================================================\n            CHAOTIC ENTITY   *WHQ*  +1 610 489 5783  [Ringdown]\n            DOOM OF EXTASY   *EHQ*  +49 PRIVATE !!!  [Ringdown]\n	    TOWER OF BABYLON *GHQ*  +49 PRIVATE !!!  [Ringdown]\n            UNDERCOVER       *SHQ*  +46 8 540 23405  [2 Nodes!]\n            DAWN RAID        *UKHQ* +44 707 320 320  [Ringdown]\n            THE UNDISCOVERED *DHQ*  +31 229 444 42   [2 Nodes!]\n            EUROPES CHAOS    *DST*  +49 461 311 458  [1 Node! ]\n            THE KREMLIN      *DST*  +7  951 255 867  [1 Node! ]\n==============================================================================\n                     AND OF COURSE THESE CRAZE BOARDS\n==============================================================================\n            INSTANT PLEASURE *WHQ*  +46 TOO ELITE!!  [1 Node! ]\n            CYBER FORCE      *SHQ*  +46 510   26683  [1 Node! ]\n            ALTERED STATE    *SHQ*  +46 TOO ELITE!!  [2 Nodes!]\n            NUCLEAR WASTE    *DST*  +46 510   27173  [1 Node! ]\n==============================================================================\n   X-TRADE WHQ AnGEL CiTY +46-(0)521-13387 SYSOP:ORGASMATRON / X-TRADE!\n     USR 28k8, Amiga 3000 030 30Mhz LOTS Mb Hd space! Totaly koolness!\n==============================================================================\n','\n',char(10)),NULL,'auto-added',8798,1,0,NULL,NULL,'dlt_md10','scan',1780048479);
