INSERT INTO door_catalog VALUES('dmo_wl14','DMO-WL14.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DMO-WL14.LHA',NULL,'XIM','LE-win5-96.exe',NULL,'dEAMO^iNDEPENDENT','DMO',':-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=: :    dAiMwALl v1.4 bY dEAMO^iNDEPENDENT    : :-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=:',replace('............................................\n:-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=:\n:    dAiMwALl v1.4 bY dEAMO^iNDEPENDENT    :\n:-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=:\n:  Yet ANOTHER Wall to be released!? Yep!  :\n:    -=- But look at this FEATURES: -=-    :\n:  SysOp Options - Clear Wall - Alltime    :\n::  Tags Count - Nice Design - Regular    ::\n::.   Updates, sometimes every WEEK!     .::\n:::.            tRY iT oUT!             .:::\n:::::.     * LINE WRAPPED FIXED!      .:::::\n:::::::..............................-dEAMo:\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n     