INSERT INTO door_catalog VALUES('dmsbvc','DMSBVC.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DMSBVC.LHA','DMSChecker','XIM','DMSChecker',NULL,NULL,NULL,'bin waiting for.... DMSChecker v1.0 - checks the DMS bootblock for VIRUSES and CRC Failures....',replace('Well here it is dudes , the DMS Checker you\nbin waiting for....\nDMSChecker v1.0 - checks the DMS bootblock\nfor VIRUSES and CRC Failures....\nThe Ultimate Util. for people running a BBS.\n','\n',char(10)),'DMSChecker.doc',replace('\n                            DMSChecker 1.0\n\n\n                                coded by\n\n\n                             Martin Wulffeld\n\n\n Preface\n ~~~~~~~\n\n The files in this distribution are Copyright (C) 1994 Martin Wulffeld.\n They may be freely distributed  as long as no more than a nominal fee is\n charged to cover time and copying costs and all the files are included\n and remain unmodified.\n\n No commercial usage is permitted without written permission from\n me. Everything in this distribution must be kept together, in original\n unmodified form. \n\n If you find a bug or just want to express your joy over this most\n excellent program don''t hesitate to contact me on one of the following\n addresses:\n \n  Snail:   Martin Wulffeld\n           Fredensvej 14\n           4720 Præstø\n           Denmark\n\n  Fidonet: 2:236:12.1\n  \n  Amynet:  39:141/137.1 \n         \n\n\n Disclaimer\n ~~~~~~~~~~\n\n I, the author, can not be held responsible for ANY damage this program\n might inflict to your system. Use at your own risk.\n\n\n\n Requirements\n ~~~~~~~~~~~~\n\n DMSChecker requires at least Kickstart 2.04. It also requires the\n Bootblock.library v1 and unpack.library v39 to be present in your\n LIBS: assign. Furthermore it requires the Bootblock.brainfile to be\n present in your L: assign. Those are included in this distribution.\n \n\n\n Function\n ~~~~~~~~\n\n DMSChecker was coded for those who wish to check their DMS archives for\n bootblock vira and is therefore a perfect utility for sysop`s.\n\n It finds the vira using the Bootblock library and it takes 4 arguments.\n \n A=FILE/A     - The file to check. You can also use pattern matching on this\n                one. Eg. ''FILE #?.dms''.\n\n A=ALL/S      - Specify this if you want DMSChecker to enter sub directories.\n\n C=CRC/S      - Specify this if you the DMS archives to be checked for CRC\n                errors.\n\n E=ERRORDIR/K - A path where the archives with errors or bootblock vira will\n                be copied to.\n\n When scanning the files DMSChecker outputs the filenames and if it finds a\n virus it will (of course) inform you. But if you use DMSChecker from\n within a script matters are a bit different. If DMSChecker finds a\n virus or the CRC check failed it will return to DOS with an exit code of\n 10. If both things happen it will return 20. Here is an example script:\n \n .key filename\n .bra {\n .ket }\n \n FAILAT 11\n DMSChecker {filename} CRC E=RAM:\n IF ERROR\n    ECHO "Error 20"\n ENDIF\n IF WARN\n    ECHO "DMS archive not safe"\n ENDIF\n\n Basic enough? Please remember that it''s somewhat useless using a pattern\n within a script. Why? Well, because the script will only get the result\n of the LAST check of a file!!\n\n\n\n Credits\n ~~~~~~~\n\n Brian Overby (Skyline Amy BBS +45 46 15 51 70) for giving me the idea.\n Pearl Jam (Vitalogy is great)\n ','\n',char(10)),NULL,'auto-added',4901,2,0,NULL,NULL,'dmsbvc','scan',1780048479);
INSERT INTO door_catalog VALUES('dmschk11','DMSCHK11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DMSCHK11.LHA','DMSChecker','XIM','DMSChecker',NULL,NULL,NULL,'bootblock vira and CRC errors. Great for use with BBS or scripts! Don''t miss it! [UFOk/MsT`95 (05 Jan 1995) +31···cYcLoNe···]',replace('DMSChecker 1.1 - Checks DMS archives for\nbootblock vira and CRC errors. Great for\nuse with BBS or scripts! Don''t miss it!\n[UFOk/MsT`95 (05 Jan 1995) +31···cYcLoNe···]\n','\n',char(10)),'RNTa9ubE.Txt',replace(' \n                             H-U-M-A-N-S DKHQ\n        __/\__    _/\___ _____ ____________    ______________\n        \___  \/\/  ___//     \\_______    \  /  _________   \\n         /    /  \    \/   |  .\ |:   /   _/ /  __|__  /.    /\n         \\          ///       \\|¡   \   .\/   ¡    \//    /\\n          \°   /\   ¤/°    |    \\     \   \\        \\       \_\n           \__/  \__/\_____|      \____l\   \\__.     °\_______/\n          =================|_______/=====\____/=l______/========\n   ___.  ______  __  .___.     /\_____  _____ /\_______________________\n  /  ¦|__\__   \l :\ |:  |__  /  \__  \/  ___/  \__  ____  ___/\____   \\n /   :|  \/ \   \ ¡ \|¡  | .\ \__/ /\    /\  \__/ |.  | / __|__ |: |\  .\\n/     ¡  \\  \\  \   \   ¡  \\/ .\/. \  / :\ /  \ ||  |/  ¡   .\|¡ |/   \\\n\         \\  \\  \   \       \  \\   \/  ¡ /    \||  |        \\        \\\n \____.    °\_l\°     /_______/___/   |l____\____/l___l___.     \\________/\n =====l_____/===\    /=========\______l====================l______/[ra!st]=\n                 \__/\n                             sYSOP: GiLTHANAS\n                  A4000-040 30 mHZ sPEED + 1 gIG hD-fUN!\n              0-1 aMiGA + gAMEBOY + /X 4.x + nEWEST /X uTILS\n \n                   .--x×X×x 28800 uSR v34 dUALS x×X×x--.\n                   |     .-----------------------.     |\n                   |     | Node 1: +45-!pRIVATE! |     |\n                   |     | Node 2: +45-rING-dOWN |     |\n                   |     `-----------------------''     |\n                   `--->  pACMAG''n''hYDRA sUPPORT!  <---''\n','\n',char(10)),NULL,'auto-added',76443,6,0,NULL,NULL,'dmschk11','scan',1780048479);
INSERT INTO door_catalog VALUES('dmsspt','DMSSPT.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DMSSPT.LHA','DMSScript','XIM','DMSScript',NULL,NULL,NULL,'/~ ____// | __\___  ~__~/ //  __)_// |/ ~\  /  :| | \\     ~\\ ~   \\/   || |',replace('  _______ /|   _______/\__ \n /~ ____// | __\___  ~__~/  \n//  __)_// |/ ~\  /  :| | \n\\     ~\\ ~   \\/   || |\n \  ____/\______/\____| |\n  \/ .____/\______/\____|\n   \/ < eLteCh pReSeNt >\n       oN tHe  4/1/95\n  = AUTO SCRIPT EXECUTER =\n        = FOR DMS =\n \n','\n',char(10)),'DMSScript.Doc',replace('             _______ /|   _______/\_______________    _____ \n            /~ ____// | __\___  ~__~/  _____/~   ~\  /~ ¡ ~\.  \n           //  __)_// |/ ~\  /  :| //  __) //   .__)//  |  \\\\n           \\     ~\\ ~   \\/   || \\     ~\\   : \\\\      / \  \n            \  ____/\______/\____|  \  ____/\____ // \. |__/  /\n             \/ .____/\______/\_____|\/ .TeTSUo__\/ / \/ ____/\n              \/                      \/          \/   \/ \n\n                     The Auto Script Executer For DMS\n                     ================================\n\nInstructions\n------------\n\n\n	This program was written in less than an hour when I got fed up with\ncontinually typing the same old garbage to DMS a number of disks with similar\nnames. It is by no means a perfect solution to the problem but it does allow\nyou greater multi-tasking flexibility and more importantly to compress disks\nusing everyones favourite disk shrinker.\n	This program is especially of use to MODEM users the world over, I\nhope it releaves some of the tedium of DMSing disks.\n\n	To use this program a number of points need to be followed :\n\n1 - Before you begin you will need a text editor, anything will do ( Yes\n    even Ed ), but you should ensure that the editor has cut and paste.\n\n2 - DMS and the script file should be placed into a device other than DF0.\n\n3 - This is only really of use to Hard Disk Owners.\n\nWhere Do I place DMS, the script and DMSScript ?\n------------------------------------------------\n\n	As I stated above DMS and the script should not be placed on DF0.\nThe ideal place to put DMS and the script is in RAM because this is by far\nthe fastest device on the AMIGA, if you want DMS could be put in the C\ndirectory of your hard disk, but the script should still be placed in RAM.\n\nThe CLI Parameters\n------------------\n\n\n	USAGE :   DMSScript   DMS_Command_Name   Name_Of_Script\n\nN.B - quotes are not allowed.\n\n	The Name_Of_Script should include all relevant path information and\nextension (if any).\n\n	The DMS_Command_Name is a command that you want to pass to DMS e.g\n\nREAD   - this will compress a disk into a file name\nWRITE  - this will decompress a file name into a disk\n\n	Any legal DMS command can be placed here but it must be a single\nword.\n\n	The Script is created using the text editor we discussed earlier,\nEvery time a carriage return is reached DMS will be used. For instance if\nyour script was saved to RAM:SCRIPT and looked like this :\n\nDH0:Example_1\nDH0:Example_2\nDH0:Example_3\n\n	and you typed at the CLI :\n\nDMSScript READ RAM:SCRIPT\n\n	Then you would first be asked to remove the disk in DF0 ( if one\nis present ). Then you would be asked to insert a disk, DMSScript will tell\nyou that the ARCHIVE NAME is DH0:Example_1. Once you place the disk in the\ndrive DMS will be loaded and will crunch the disk in DF0 saving it as\nDH0:Example_1. When it has finished you will be asked to remove the disk and\ninsert the next one.\n\n	That is all there is to it, please note that you can also place a\nnumber of parameters for DMS after the file name in the script as long as\nthey are on the same line. The FROM & TO commands should not be used to try\nand change the device from DF0 as this won''t help one bit.\n\n\nCredits etc.\n------------\n\n\n	Coded by LeeCH / ELTECH.\n\n	This program is freeware but is still ©1995 ELTECH.\n\n	Hello''s go to Jester,Mic Flair,Realitor of ELTECH and to any one else\n        who knows me.','\n',char(10)),NULL,'auto-added',61411,5,0,NULL,NULL,'dmsspt','scan',1780048479);
