INSERT INTO door_catalog VALUES('dnc_flha','DNC_FLHA.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DNC_FLHA.LHA','FASTLHA','XIM','FASTLHA',NULL,NULL,'DNC','\ _____ __ __ _____ _____ ___  __ __ _____ / |Y__   Y  Y  Y     Y   _ Y   YY  Y__Y  ___Y| || |   |__   |   | |     |       |  |  |  ||',replace('____________________________________________\n\ _____ __ __ _____ _____ ___  __ __ _____ /\n|Y__   Y  Y  Y     Y   _ Y   YY  Y__Y  ___Y|\n|| |   |__   |   | |     |       |  |  |  || \n||     |     |   | |   | |   ||  |  |  `--||\n|`-----''-----^---^-^---^-^---^^--^--^-----''|\n`--------------- presents -----------------''\n<[FAST-LHA v1.11a CHECKER,STRIPPER & ADDER]>\n','\n',char(10)),'FASTLHA.DOC',replace(' \n       ______     _______     _______       ___________    ____ ____\n      /  _   \   /_  ___ \   /_      \   /\/     _ __ /   /   //__ /\\n     /__ /    \ //  /  /  \ //  /  /  \ /  \ ___    //   /   ///  /  \\n    _\___\   ///   /  /   //   /  /   //   //    ___/__ /   //   /___/_\n   /    _/ _///   /__/   //   /  / _///   ///_  _     //   //   /     /\\n  /_________//__________//___/__/___//___//__________//___//_________/  \\n  \__ _     \\__ _      \\__ _      \\_  \\__ _      \\   \\__  _    \  /\n   \_________\\__________\\__________\\___\\__________\\___\\_________\/\n\n            D y n a m i c / EhQ       +49-6101-88708 / 12565\n\n\n                 FAST - LHA V1.11 by EINSTEIN/DYNAMIC\n               ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~          \n\nIntroduktion:\n-------------\nFastLHA is one of the fastest and bettest LHA Checker,Stripper and Adder!\nRemoves ALL other BBS-ADDS! Adds as mayn files as you want.\n\nIt''s freely configurable with many options!\n\nError-Handler routines included, so it will never crash!\nFull running on all Systems A500,A600,A1200,A2000,A3000,A4000 68000-680xx!\nYou must have Kick 2.0 or highter.\n\nRunning on youre SHELL with FASTLHA PATH:LHAARCHIV.LHA\nAll people on the Amiga can use it!\n\nHow to install? Copy all Files in youre C: Directory now, copy your ADD in\nthe S Dir and chanfge it with this Options!\n\nOptions: You can include wherever you want these special symbols :\n---------\n        \n  %PROC                 ... will be replaced with the current CPU\n\n  KICKSTART             ... will be replaced with your KICKSTART Version\n\n  -=F=I=L=E==N=A=M=E=-  ... will be replaced with the LHA Filename\n\n  ########              ... will be replaced with the LHA Archiv Bytes\n\n  %MM                   ... will be replaced with the Months as (JAN,FEB..)\n\n  %TT                   ... will be replaced with the Day as (MON,TUE..)\n\n  %S                    ... will be replaced with the Local Secs. \n\n  %M                    ... will be replaced with the Local Mins. \n\n  %H                    ... will be replaced with the Local Hours. \n\n  %D                    ... will be replaced with the Numeric Days. \n\n  %O                    ... will be replaced with the Numeric Months. \n\n  %S                    ... will be replaced with the Local Sec. \n\n  %YYY                  ... will be replaced with the Numeric Years (1994). \n\nMore in the next Version! Call us for this... when you like it...\n\nFiles:\n-------\nC:FAST.STRIP      ... This files deleted out of the LHA Archives!\n\nC:FAST.ADD        s:domizil this File we add in LHA Archives\n\n \n       ______     _______     _______       ___________    ____ ____\n      /  _   \   /_  ___ \   /_      \   /\/     _ __ /   /   //__ /\\n     /__ /    \ //  /  /  \ //  /  /  \ /  \ ___    //   /   ///  /  \\n    _\___\   ///   /  /   //   /  /   //   //    ___/__ /   //   /___/_\n   /    _/ _///   /__/   //   /  / _///   ///_  _     //   //   /     /\\n  /_________//__________//___/__/___//___//__________//___//_________/  \\n  \__ _     \\__ _      \\__ _      \\_  \\__ _      \\   \\__  _    \  /\n   \_________\\__________\\__________\\___\\__________\\___\\_________\/\n\n            D y n a m i c / EhQ       +49-6101-88708 / 12565\n\n','\n',char(10)),NULL,'auto-added',26099,7,0,NULL,NULL,'dnc_flha','scan',1780048479);
INSERT INTO door_catalog VALUES('dnt_wh10','DNT-WH10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DNT-WH10.LHA',NULL,'XIM','.--------------------- -- /\____ --------.',NULL,NULL,'DNT','_¦/\__________/\__________/     /__       | ________     _______     __    ____/__     | \/     /     /     /     /     /     /     |',replace('  .--------------------- -- /\____ --------.\n _¦/\__________/\__________/     /__       |\n________     _______     __    ____/__     |\n\/     /     /     /     /     /     /     |\n/______     /_____/     /\_____     /_     |\n__._ _____ /__________ /__________ /_//    |\n  ¦-bIS! \/          \/          \/        |\n  |                                        |\n  |  [-dOMINAtION /X-] : Other Nodes v1.o  |\n  |                                        |\n  `----------------------------------------''\n','\n',char(10)),'WHO.DOC',replace('\n\n\n                           <released on 17/07/95>\n\n  -========================================================================-\n\n                   _   _______/\            _____  /\__ _    _ _ /\\n        _ _______/\\   \     /  \ :______   \____\/________    //  \ :______\n  ______   __  _/  \  __\___·    \|    _/____/_  \/ ¬\_   /____/__  \|    _/\n__\__  ¬\  \/  ¬\_  \/  ¬\__¬\_   \    ¬\_  _ ¬\______/__/  __  _/   \    ¬\_\n    |    \_______/  \/    _/__/   \\     /  _   \_ _/   ¬\_ \/  ¬\_  \\     /\n_____     /  _ _____/      \ _ ___|\    /___|    /.\______/_______/__|\    /\n----l____/---------/________\-------\  /----l___/------Stz!/6c---------\  /--\n                                     \/                                 \/\n\n       ·^»> Other Nodes v1.o [-dOMINAtION·/X-] (c) Mad Jack & Zeus <«^·\n\n  -========================================================================-\n\n\n\n\n\n\n\n\n                      [.o1.] - Introduction & Features\n                      [.o2.] - Installing Other Nodes v1.o\n                      [.o3.] - Configurations & Headers\n                      [.o4.] - Contacts etc.\n\n\n\n\n\n\n\n\n      _                         _\n  ·--\/ Introduction & Features \/-----------------------------------------·\n\n\nFeatures:\n\n- Possibility to use own header, examples provided\n- Supports upto 99 nodes display\n- Superb outlook\n\n\n\nWhy did we do this util?\n\nWe decided to work on an who-command since we didn''t seem to find a\ndecent-looking one in the scene. Many of our boards were in a need\nof an who-command for their /X''s, too. So here it finally is, couple\nof weeks it took but it''s great now when it''s ready''n''runnin! It\nis coded by -Mad Jack- and the outlook is made by me, -Zeus-.\n\n\n\n<---- This is, basically, how it looks like ---->\n\n\n .----/-------------------------------------------------------------------/--.\n |  // ·^»> Other Nodes v1.o [-dOMINAtION·/X-] (c) Mad Jack & Zeus <«^· //   |\n `--/-----------------.------------------------.---------------------.--/----''\n   00 zEUS/mSt        | --»> mYSTIC/p^A! <«--  | Looking Other Nodes | 19.2k\n <--------------------+------------------------+---------------------+------->\n   01 -               | -                      |  « Node InActive »  | 00.0k\n .----/---------------^------------------------^---------------------^----/--.\n |  // ·^»> Other Nodes v1.o [-dOMINAtION·/X-] (c) Mad Jack & Zeus <«^· //   |\n `--/-------------------------------------------------------------------/----''\n\n\nAnd, ofcourse, that is done in ANSI-colour in the real-life-action. ;)\n\n\n\n\n      _                             _\n  ·--\/ Installing Other Nodes v1.o \/-------------------------------------·\n\n\nInstalling this software has been made very easy for the sysop. Just copy\nthe files in the archive to your system and adjust the configuration\nto suit your desires. The default settings are ready to kick butt,\nso test it out first! We have provided you five example-headers you might\nwant to use. Few simple ones and few not-so-simple.\n\n\n\n      _                              _\n  ·--\/ Configuring Other Nodes v1.o \/------------------------------------·\n\n\nConfiguring the Other Nodes? It''s simple, because the config-file itself\nisn''t too big. There are two lines that are the ones that matter,\nnumber of nodes to display and the header-path. The number of nodes is\nn+1, whereas n is the number of the actual nodes, amd the 1 is the local port,\nwhich will always be displayed. If you think you don''t need header,\nuse blank line in the second line of the config.\n\n\n\n\nThis example-config would display header + 2 nodes.\n\n-----------------\n1\nDOORS:DNT-UTILS/HEADERS/WHO4.HEADER\n\n; First line - The highest node-number to display\n; Second line - Path to headerfile. Blank line not to use a header\n\n; [-dOMINAtION·/X-] : [-Other Nodes v1.o Configfile-]\n-----------------\n\n\n\n\nIf you used this, you should have "MYOWN.HEADER" in the HEADERS-dir.\nSo this displays your "MYOWN.HEADER" and then shows 3 nodes.\n\n-----------------\n2\nDOORS:DNT-UTILS/HEADERS/MYOWN.HEADER\n\n; First line - The highest node-number to display\n; Second line - Path to headerfile. Blank line not to use a header\n\n; [-dOMINAtION·/X-] : [-Other Nodes v1.o Configfile-]\n-----------------\n\n\n\n\n\nHere''s a list of the logos we have provided you:\n\n\n\n--DOORS:DNT-UTILS/HEADERS/WHO1.HEADER--\n\n<only a screenclear>\n\n\n\n--DOORS:DNT-UTILS/HEADERS/WHO2.HEADER--\n\n                    ·«{ displaying other nodes activity }»·\n\n\n\n--DOORS:DNT-UTILS/HEADERS/WHO3.HEADER--\n\n                ___ |_  |__  ___  .__   .___  ___  ___| ___  ,__\n         ---»> (___)l__,|  )(__/_,|  ''  |   )(___)(___l(__/_,___) <«---\n\n\n\n--DOORS:DNT-UTILS/HEADERS/WHO4.HEADER--\n\n    _____ _____________________________________.\n    \    \|     /  _    /  _    /  ___   /  ___|_\n    _\_   \   _/_  /  _/_  (  _/_  \____/_____   \_   Node1: +358-0-PRIVATE\n    \     \     /       /       /   /    /   /    /   Node2: +358-0-DNT-/X!\n   .\\____|\___/_______/_______/________/________//.\n\n\n\n--DOORS:DNT-UTILS/HEADERS/WHO5.HEADER--\n\n                      ·\n                    __|     _ ______________________________.\n            _ __   / ¬\   ·     _  ¬\    _  _/   __  _/   __|_   __ _\n               // /    \   \_   /    \   /  ¬\_  )____\____  ¬\_\\\n                 /    \_____/________/________/________/  `____/\n        - ------/_______\--·zS!·--------------------/_______\-------- -\n\n\n\nAnd if any of these are not what you''re looking for, make it yourself\nor order the dzain from eg. the local ascii-artist. ;)\n\n\n\n\n\n      _             _\n  ·--\/ Contact us! \/-----------------------------------------------------·\n\nBeta-sites are always welcome, around the globe. So far the only beta-\ntesters are:\n\n\n    N#   Boardname          Number             Operator\n  .----.------------------.------------------.-----------------------------.\n  | 03 | COSMO BC 5000    | +358-11-231814   | G.O.D. / Bombsquad          |\n  | 01 | CLOUDKILL        | +358-0-2792021   | Mad Jack / [-dOMINAtION-]   |\n  `----^------------------^------------------^-----------------------------''\n\n\nWe have several utils under work, eg. lastcallers, status, memory-monitor\netc.. New ideas are welcome ofcourse!\n\nTo contact us, e-mail --»> [email removed] <«-- or dial our beta-\ntesting-sites and leave message to Zeus or Mad Jack.\n\n\n\n\n\n      _            _\n  ·--\/ Known Bugs \/------------------------------------------------------·\n\n- Shows hidden nodes (will be phixed)\n- Local port is always shown (not a ''bug'' though, but in the next version\n  there is an option called ''disable zero'')\n\n\n\n<EOF>\n','\n',char(10)),NULL,NULL,56707,9,0,NULL,NULL,NULL,'scan',1780048479);
INSERT INTO door_catalog VALUES('dntsend','DNTSEND.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DNTSEND.LHA',NULL,'XIM','SWidget.x',NULL,'P0T-NOoDLE',NULL,'By P0T-NOoDLE',replace('Donation form sender door for Ami Express\nBy P0T-NOoDLE\n','\n',char(10)),'SWidget.Doc',replace('This is a VERY simple, BADLY CODED, and NOT DESIGNED door (!), knocked up\nvery quickly to do a specific job for a specific person!...\n\nI hope that some other people can also find this useful, but don''t expect\nit to be very configurable! (If you don''t like it, delete it - but maybe\nyou will like it?)\n\n\nThis program simply asks what computer they have and then sends them a text\nfile (in either IBM or Amiga format).\n\nIt''s designed to send out forms for people to setup Donation accounts, but\nI guess there could be other uses...\n\n\nXIM type door.\nNormal stack size (Hardly uses any at all).\nMultiNode compatable.\n\nCode is 100% ASM, Pure/Reentrant/Residentable, 32 Node comp. (upto 100 nodes).\n\n\n\nWhen they select 1 - Amiga, the file:\n\nBBS:Donate/Amiga/Donation.TXT\n\nis sent.\n\n\nWhen they select 2 - PC, the file:\n\nBBS:Donate/PC/Donation.TXT\n\nis sent.\n\n\nIf you don''t like the file paths, you can hex-edit the binary file and put\nyour own filepaths in the areas marked something like:\n\nAmiga-Filename starts here ->BBS:Donate/Amiga/Donation.Txt<NULL>\n<<LOTS OF NULLS>>\n<- Amiga-Filename must end here.\n\nand\n\nPC-Filename starts here ->BBS:Donate/PC/Donation.Txt<NULL>\n<<LOTS OF NULLS>>\n<- PC-Filename must end here.\n\nProvided that the new filepaths end with a NULL and do not go beyond past\nthe "must end here" message. Of course, you should use your hex-editor in\nOVERWRITE mode so that the filelength remains the same (are there any where\nyou can use insert mode anyway??).\n\n\nMessages are put in the callerslog (they also say which file was downloaded).\n','\n',char(10)),NULL,'auto-added',3645,2,0,NULL,NULL,'dntsend','scan',1780048479);
INSERT INTO door_catalog VALUES('do5_full','DO5_FULL.LZX','~/Code/amiexpress_doors/Archives/AmiExpress/DO5_FULL.LZX',NULL,'XIM','08.07.95',NULL,NULL,'DO5',NULL,NULL,NULL,NULL,NULL,'auto-added',197415,0,0,NULL,NULL,'do5_full','scan',1780048479);
INSERT INTO door_catalog VALUES('doclha4l','DOCLHA4L.LZX','~/Code/amiexpress_doors/Archives/AmiExpress/DOCLHA4L.LZX',NULL,'XIM','VZ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'auto-added',51164,0,0,NULL,NULL,'doclha4l','scan',1780048479);
INSERT INTO door_catalog VALUES('donatsnd','DONATSND.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DONATSND.LHA',NULL,'XIM','exe.-l0S-eND0S-bBS-.exe',NULL,NULL,NULL,NULL,replace('Donation Send /X Door\n','\n',char(10)),'SWidget.Doc',replace('This is a VERY simple, BADLY CODED, and NOT DESIGNED door (!), knocked up\nvery quickly to do a specific job for a specific person!...\n\nI hope that some other people can also find this useful, but don''t expect\nit to be very configurable! (If you don''t like it, delete it - but maybe\nyou will like it?)\n\n\nThis program simply asks what computer they have and then sends them a text\nfile (in either IBM or Amiga format).\n\nIt''s designed to send out forms for people to setup Donation accounts, but\nI guess there could be other uses...\n\n\nXIM type door.\nNormal stack size (Hardly uses any at all).\nMultiNode compatable.\n\nCode is 100% ASM, Pure/Reentrant/Residentable, 32 Node comp. (upto 100 nodes).\n\n\n\nWhen they select 1 - Amiga, the file:\n\nBBS:Donate/Amiga/Donation.TXT\n\nis sent.\n\n\nWhen they select 2 - PC, the file:\n\nBBS:Donate/PC/Donation.TXT\n\nis sent.\n\n\nIf you don''t like the file paths, you can hex-edit the binary file and put\nyour own filepaths in the areas marked something like:\n\nAmiga-Filename starts here ->BBS:Donate/Amiga/Donation.Txt<NULL>\n<<LOTS OF NULLS>>\n<- Amiga-Filename must end here.\n\nand\n\nPC-Filename starts here ->BBS:Donate/PC/Donation.Txt<NULL>\n<<LOTS OF NULLS>>\n<- PC-Filename must end here.\n\nProvided that the new filepaths end with a NULL and do not go beyond past\nthe "must end here" message. Of course, you should use your hex-editor in\nOVERWRITE mode so that the filelength remains the same (are there any where\nyou can use insert mode anyway??).\n\n\nMessages are put in the callerslog (they also say which file was downloaded).\n','\n',char(10)),NULL,'auto-added',9158,5,0,NULL,NULL,'donatsnd','scan',1780048479);
INSERT INTO door_catalog VALUES('dooex14','DOOEX14.LZX','~/Code/amiexpress_doors/Archives/AmiExpress/DOOEX14.LZX',NULL,'XIM','dooex14',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,8357,0,0,NULL,NULL,NULL,'scan',1780048479);
INSERT INTO door_catalog VALUES('downmani','DOWNMANI.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DOWNMANI.LHA',NULL,'XIM','Download Mania',NULL,NULL,NULL,'by Pot Noodle',replace('               Download Mania\n                     by\n                 Pot Noodle\n','\n',char(10)),'DM.Doc',replace('Download Mania door by P0T-NOoDLE - custom util for Dream Warrior!\n\nA program to restrict certain users from downloading at certain times.\n\n\nAll the usual features of Gods''Gift: Nice looking, residentable, 100% Asm.\n\nTo install, install it over the "D" command (or even better "*D")\n\n\n\nFiles used by the util:\n\nDoors:DM/DM.Cfg\n	This is the config file (see example included).\n	Line 1 MUST have a 5 digit time string which specifies the START\n		of when period 1 begins. e.g. "18:00", return.\n	Line 2 MUST have a 5 digit time string which specified the END\n		of when period 1 ends. e.g. "19:00", return.\n	Line 3 MUST have a 5 digit time string which specifies the START\n		of when period 2 begins. e.g. "18:00", return.\n	Line 4 MUST have a 5 digit time string which specified the END\n		of when period 2 ends. e.g. "20:00", return.\n	All lines after the first two are taken as names of users.\n		Before each username given you must either have "**" or "P2"\n		All users not given in the file will not be able to download\n			during Period 1.\n		All users given with "P2" before their name will not be\n			able to download during Period 2.\n		All users given with "**" before their name will be able to\n			download at any time.\n	Case doesn''t matter, but make sure all lines have a return at the end.\n\nDoors:DM/DM_Allowed.Txt\n	This text file is shown when they''re allowed to download.\n	I''m not sure if /X will mind if the file doesn''t exist, so if you\n	don''t want any message sent, just have an empty file, or put a return\n	in or something.\nDoors:DM/DM_Denied.Txt\n	This text file is shown when they''re not allowed to download.\n	Same applies to this as the file above.\n\n\n\nOther things: Features/Bugs:\n\nTwo versions are included. The "normal" one will run the internal "D" command\n	once it has finished and worked out that the user is allowed to\n	download.\n	The other "extra" version will not run anything after finishing. This\n	allows you to run other doors that previously replaced the "D" command\n	(Such as confscan''s download door) via MCI from DW_Allowed.Txt.\nThe argument string given to the door (as it replaces the D command this will\n	be a list of files to download) is added to the flagged files.\nIf it is Saturday or Sunday, everyone can download all the time.\n	(Wasn''t sure if you wanted this, it''s easy to remove if you don''t)\nIt WILL pass the filenames given to it to the internal "D" command, so users\n	can still type "D FILE1.DMS FILE2.DMS" from the commandline OK.\nMessages are written to the callerslog saying the time and whether their\n	request to download was granted or not.\nWill not work for time periods that cross midnight.\n	If you need this (which I assume you don''t!) let me know.\nIf, at the command prompt, they type "D FILE1.DMS FILE2.DMS..." etc and use\n	all 200 chars available, the last five chars of the commandline will\n	be ignored. It appears that this is NOT a bug in this program but a\n	bug in /X (I have only used v2.39 which is getting very old now!) as\n	when given the BB_MAINLINE command, /X only appears to return up to\n	195 chars!\n\n\n	That''s it! Enjoy!!\n','\n',char(10)),NULL,NULL,12959,5,0,NULL,NULL,NULL,'scan',1780048479);
INSERT INTO door_catalog VALUES('dp__tp12','DP!-TP12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DP!-TP12.LHA','pager12','XIM','_  /\________________________________/\  _',NULL,NULL,'DP!','| \/           dIGITAL pOSSE!           \/ | |  __      ________   ________        __   | |  \____   \_      \  \_____  \    ____/   |',replace(' _  /\________________________________/\  _\n| \/           dIGITAL pOSSE!           \/ |\n|  __      ________   ________        __   |\n|  \____   \_      \  \_____  \    ____/   |\n|     \___  |   |   \  |   |   \ ___/      |\n|           |   |    \ |  /____/           |\n|           |________/ |   |               |\n|27/09/96         pRESENTS_|         [AMIGA]\n`------------------------------------[MM!]-''\n tERRORpAGER vERSiON 1.20bETA  /X, S!X, FAME\n sIMpLE aND fAST pAGER            [UNREGGED]\n','\n',char(10)),'pager12.doc',replace('\n\n\n---- --------  ------------- -----------------------  ------------\n                    tERROR pAGER v1.2\n--------- ------------------ ------  -------------------- --------\n\n\n\ncODED bY cOSMiC^dP!^rNSC\n\neMAiL: [email removed]\n\n --^-- NOTE: --^--\n\nTHiZ iS CALLWARE... IF YOU WANT TO GET A REGGED VERSiON FOR YOUR BOARD,\nTHEN CALL DA dP! /X SiTE.\n\ncENTRAL pARK BBS: +49-30-62XXXXX   ask some m8es ''bout da pwds\n\n\n\nThiz is a simple O command replacement. It uses the internal O to page\nif the chatflag is on and uses a built-in emergency page if the chatflag\nis OFF.\n\nAfter paging, a user is able to write a mail to the master !\n\nPut the PAGER.CFG into DOORS:DP!/O/ and edit it ... but only the third\nline, if you edit the keysettings your system will crash or other\nthings happen so plese register at central park, it will cost u only\na phonecall not a damaged harddisk ...\n\nThis my last digital posse release so do not contact me anymore for further\ninformation on the group ...\n\n\n....cOSMiC^aMB!^rNG!^sHElTER....\n\n------------ ----------  --------------------- ------------  ----- --------\n\nHiSTORY:\n\n0.1           no soundplay...called only an external pager\n\n0.2           soundplay but no dezign ;-)\n\n0.3           dezign added (made by mERLiN!)\n\n0.4           thiz version regged to mERLiN! and another regged to RED MONKEY\n\n0.5           now u can use your favourite emergency pager and comment door\n\n1.2           the next release fixed some problems and new key/pageroutine\n\n----------  ------- ------  --------------- ---------- -----------  -------\n\nmore features coming soon...;-)\n\ncontact me at jUNCTiON, tHE pUB oR aCiD sLAM !!!\n\ngreetz to following dOOdZ:\n\n...mERLiN!......thx for dezign\n...rED mONKEY...nimm wieder tempest ;-)\n...sTE3L........arexx suxx ;^)\n...sEGoY........komm aussem knick, ferien gibt es spaeter\n...iNVaSiON.....still lazy ?\n...sERAPH.......refugee ??? running on fame ???\n...mALCoLM X....your board is still offline ?!?\n...bUtCHER......wer callt schon auf bill ;-)\n...rAMiS........was los dort draussen ;)\n...sLAPsHOT.....wait some dayz !\n...lUCAS........was is das bloss fuer ne hpa section ?!?\n...tELEKOM......all hpa boards down ? fuck you !\n\n\nNOTE TO ALL REGGED USERz: \n\nAll updates available at central park...join the conference number 15 !\n\n\nGreetz to all regged until today:\n\nmERLiN!, rED mONKEY, mAGiC mAX\n\nNext update till the end of july, I hope ;)\n\n\n\nsIGN oFF...cOSMiC^sHElTER^aMB!\n\n\naTTEnTiON: uPDAtES aND mORE dOORS fOR /X aND fAME wILL fOLLoW oN sHElTER !\n\n\n','\n',char(10)),NULL,NULL,29123,7,0,NULL,NULL,NULL,'scan',1780048479);
INSERT INTO door_catalog VALUES('dph_conq','DPH-CONQ.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DPH-CONQ.LHA',NULL,'XIM','dph-conqueror.exe',NULL,NULL,'DPH','What: Amiga 64k Party: Revision 2011',replace('Who: Depth\nWhat: Amiga 64k\nParty: Revision 2011','\n',char(10)),'readme.txt',replace(replace('Who: Depth\r\nWhat: Amiga 64k\r\nParty: Revision 2011','\r',char(13)),'\n',char(10)),NULL,'auto-added',29746,4,0,NULL,NULL,'dph_conq','scan',1780048479);
INSERT INTO door_catalog VALUES('dpl_a13','DPL-A13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DPL-A13.LHA',NULL,'XIM','Announce.x',NULL,'Tango/DPL','DPL','.\____ \   /   _____   /  /\___  \---------. |/   /  \ /   / ______/  /   \/   \        | /_______/___ /   / /   _/\________/  DUPLO |',replace(' ____/\_____/\___________________           \n.\____ \   /   _____   /  /\___  \---------.\n|/   /  \ /   / ______/  /   \/   \        |\n/_______/___ /   / /   _/\________/  DUPLO |\n|          \/__ / /_______\-Mo!            |\n¦-------------\/---------------------------''\n|             P R E S E N T S\n|       Announce v1.3, by Tango/DPL\n|   Announces logons on any nodes with a\n|  window on the frontmost screen. A must\n|             for all sysops!\n`----------------------------------------->\n','\n',char(10)),'Announce.doc',replace('\n        .\n        :    :\n        :   /|\n        |  / | t A N G o                  _______\n        ._/  |___ _ ____________ _______ |      /_____________________\n       _ _   ___/____________   \     _ \|     /___________________   \\n        :    |     \      ______ \     \ \    / \______    |      |  . \_\n        :    l      \_    \    /  \_    \ \  /       |     |      ''     /\n      _ :_______     /_____\       /____|\  /______  `     |__________ /\n        |  -mNt\____/       \ ____/       \/      `--------''         \/\n        |                    \/                                      :\n        |                       o F   D U P L o                      |\n        |                                                            |\n        `---------------------- P R E S E N t S ----------------- - -''\n\n                                 Announce v1.3\n\n                              Idea by: Abbe/Indie\n\n«-----------------------------------------------------------------------------»\n\n                                Important note!\n                               ~~~~~~~~~~~~~~~~~\nThis util is released under the concept of tradeware. If you like it and use\nit, upload some on my board. I will not take any responsability for whatever\nthis door does with your computer (It wont do anything but what it should, but\nyou never know what those lamers do!).\n\n«-----------------------------------------------------------------------------»\n\n                                   History!\n                                  ~~~~~~~~~~\nv1.0 - [INTERNAL] Announced a logon on the WB-Screen.\nv1.1 - [INTERNAL] Announces both logons and logoffs on the frontmost screen if\n       it''s a PubScreen, otherwise on WB-Screen.\nv1.2 - [INTERNAL] If more than one window is open they are moved downwards\n       instead of covering each other. Added a tooltype for setting the\n       delay-time.\nv1.3 - Fixed a small bug. The program didn''t open on the frontmost screen,\n       instead it opened on the active screen. This is now fixed! Made program\n       announce carrier losses too. Added a tooltype to select if the program\n       should flash the screen when opening the window.\n\n«-----------------------------------------------------------------------------»\n\n                                 Installation!\n                                ~~~~~~~~~~~~~~~\nWhen you''re running a BBS on an Amiga, you''re often using your computer for\nother tasks than the BBS. Now, if you''re coding on that new hot C-program and\nsomeone logs on to your board you just HAVE to see who it is! (At least I do\nso! :) This is where this tool comes in, coz now you start shuffel''in those\nscreens like hell! If you run a board with 3 nodez there are a few screens,\naren''t there! :) Well, what this door does, is that it announces a logon or\nlogoff on the frontmost screen. It places a litle window in the upper right\ncorner. The window doesn''t even get highlighted, so if you''re writing it don''t\neven have to bother you!\n\nWhen you should install this door, first of all, copy the contents of the Doors\ndrawer to your DOORS:. Then move the ANNOUNCE.info file from the\nCommands/SysCmd drawer to your Commands/SysCmd drawer. Then edit your LOGON.TXT\nand LOGOFF.TXT. You should put something like this in your textfiles!\n\n---8<---\n~\n~CC_ANNOUNCE|\n---8<---\n\nAs default, this program holds it''s window for 5 sec. If you want any other\ndelay-time, put a tooltype called DELAY=<time> in the program icon.\n\nYou can also use the tooltype DISPLAYBEEP to have the program flash the screen\nevery time it shows it''s window.\n\nFinally, put something like "Announce 1 off" in your logoff.batch. The 1 is\nofcourse the nodenumber, and the off parameter means that the prog should check\nif the user loss carrier. If he did it will put up a special window and if he\ndidn''t it will just sit quiet.\n\nNow you should be set with your new announce program!\n\n\nIMPORTANT LAST MINUTE NOTE!!!!\n\nI have noticed that some programs wich opens PublicScreens wich my program (or\nany program) then can use, don''t follow the rulez. The program that opened the\nscreen must check if the screen is empty before closing it down. Some programs\ndon''t do this check, and unfortunately /X is such a program! If an announce\nwindow is on another programs screen and you''re uncertain wether the program is\ncorrectly written, please wait until the window is gone before trying to quit\nthe original program. This is not a bug in Announce and therefor I can''t do\nanything about it. Just thought you ought to know!\n\n«-----------------------------------------------------------------------------»\n\n                 These are the ß-sites for all my doors/utils!\n                ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n       Asylum Altered State #1       Juan               ++46-317-759378\n       Asylum Altered State #2       Juan               ++46-317-759376\n       Disorder                      Marwin             ++46-456-27511\n       Imagine #1                    Rille              ++46-42-135504\n       Imagine #2                    Rille              ++46-42-135505\n       Total Inferno                 Tango              ++46-42-234164\n       Twisted Society               The Big Byte       ++46-44-106144\n\nAll my utils should be free dl, otherwise tell me and I''ll kick that ß-tester.\nIf you want to ß-test my doors/utils, contact me and we''ll work something out.\n\n«-----------------------------------------------------------------------------»\n\n                                  Greetings!\n                                 ~~~~~~~~~~~~\n   Melone, Krusty, Hoot, Marwin, Manta, The Big Byte, Norad, Venger, Zendor,\n    Mike, Luca, Abbe, Stuff, Broder, Zync, Zych, La Fayette, Axe, Nebraska,\n   Eracore, Linus, Avalon, Nero, Dixy, Crux, Nuke, Fuze, Fix, Kain, Prospex,\n    Canaima, Pripps, Hilbert, Mital, D-Zire, Jucke, Double, E-Go, Distler,\n     Sy-Klone, Fazer, Zcandaler, Beavis & Butthead, Renko, Juan, Guardian,\n   EaSy RiDeR, Wozzy, Suggs, Rille, Fonus, Nightshade, Borre, Scroud, Derek,\n                               Vega, Rix, Demax\n\nForgive me if I forgot someone. It''s not easy to remember everybody you know!\n\n[EOF]\n','\n',char(10)),NULL,'auto-added',12531,2,0,NULL,NULL,'dpl_a13','scan',1780048479);
INSERT INTO door_catalog VALUES('dpl_ac10','DPL-AC10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DPL-AC10.LHA',NULL,'XIM','AxxCheck.x',NULL,'Tango/DPL','DPL','.\____ \   /   _____   /  /\___  \---------. |/   /  \ /   / ______/  /   \/   \        | /_______/___ /   / /   _/\________/  DUPLO |',replace(' ____/\_____/\___________________           \n.\____ \   /   _____   /  /\___  \---------.\n|/   /  \ /   / ______/  /   \/   \        |\n/_______/___ /   / /   _/\________/  DUPLO |\n|          \/__ / /_______\-Mo!            |\n¦-------------\/---------------------------¦\n|            P R E S E N T S :             |\n|       AxxCheck v1.0, by Tango/DPL        |\n|  Check all users that log in with high   |\n|     axx against a texfile to prevent     |\n|              hack-atempts!               |\n`------------------------------------------''\n','\n',char(10)),'AxxCheck.doc',replace('\n        .\n        :    :\n        :   /|\n        |  / | t A N G o                  _______\n        ._/  |___ _ ____________ _______ |      /_____________________\n       _ _   ___/____________   \     _ \|     /___________________   \\n        :    |     \      ______ \     \ \    / \______    |      |  . \_\n        :    l      \_    \    /  \_    \ \  /       |     |      ''     /\n      _ :_______     /_____\       /____|\  /______  `     |__________ /\n        |  -mNt\____/       \ ____/       \/      `--------''         \/\n        |                    \/                                      :\n        |                       o F   D U P L o                      |\n        |                                                            |\n        `---------------------- P R E S E N t S ----------------- - -''\n\n                                 AxxOpen v1.0\n\n                              Idea by: Double/DPL\n\n«-----------------------------------------------------------------------------»\n\n                                Important note!\n                               ~~~~~~~~~~~~~~~~~\nThis util is released under the concept of tradeware. If you like it and use\nit, upload some on my board. I will not take any responsability for whatever\nthis door does with your computer (It wont do anything but what it should, but\nyou never know what those lamers do!).\n\n«-----------------------------------------------------------------------------»\n\n                                   History!\n                                  ~~~~~~~~~~\nv1.0 - First release. Very simple program, but yet so powerfull! I want to see\n       the hacking sucker log on with sysop-axx now!\n\n«-----------------------------------------------------------------------------»\n\n                                 Installation!\n                                ~~~~~~~~~~~~~~~\nIf you run /X 3.x, copy all files I''ve supplied and you''re almost set.\n\nIf you run /X 2.x or S-Express, insert the followin line to your\n"commands/sys.cmd" file.\n\n---( cut )---\nCHECK     XM001DOORS:AxxCheck/AxxCheck.x\n---( cut )---\n\nNow you have to start the door somehow, a good place would be in your\n"LOGON.TXT" fex. Just disable the Q-logon, otherwise it''s possible to bypass\nthe checker (Or is it. I''ve allways had it off! :)! The following line will\nstart the door, if it''s named "CHECK"!\n\n---( cut )---\n~\n~CC_CHECK|\n---( cut )---\n\nNow, you have to edit the "AxxCheck.cfg" file. The first line in the file is\nwhere you should put the axxlevel wich should be checked. Enter "200" and all\nusers with axx>=200 will be checked. Second line is the level to put users at\nif they''re not allowed sysop-axx! This new axxlevel is actually stored in the\nuser data. Then, on third line and on, enter all guys who should have sysop\naxx. As easy as that! Remeber to put "AxxCheck.x" and "AxxCheck.cfg" in the\nsame dir!\n\n«-----------------------------------------------------------------------------»\n\n                 These are the ß-sites for all my doors/utils!\n                ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n       Asylum Altered State #1       Juan               ++46-317-759378\n       Asylum Altered State #2       Juan               ++46-317-759376\n       Disorder                      Marwin             ++46-456-27511\n       Imagine                       Rille              ++46-42-135505\n       Total Inferno                 Tango              ++46-42-234164\n       Twisted Society               The Big Byte       ++46-44-106144\n\nAll my utils should be free dl, otherwise tell me and I''ll kick that ß-tester.\nIf you want to ß-test my doors/utils, contact me and we''ll work something out.\n\n«-----------------------------------------------------------------------------»\n\n                                  Greetings!\n                                 ~~~~~~~~~~~~\n    Melone - Krusty - Hoot - Marwin - Manta - The Big Byte - Norad - Venger\n    Zendor - Mike - Luca - Abbe - Stuff - Broder - Zync - Zych - La Fayette\n     Axe - Nebraska - Eracore - Linus - Avalon - Nero - Dixy - Crux - Nuke\n   Fuze - Fix - Kain - Prospex - Canaima - Pripps - Hilbert - Mital - D-Zire\n        Jucke - Double - E-Go - Distler - Sy-Klone - Fazer - Zcandaler\n   Beavis & Butthead - Renko - Juan - Guardian - EaSy RiDeR - Wozzy - Suggs\n                            Rille - Fonus - Proctor\n\nForgive me if I forgot someone. It''s not easy to remember everybody you know!\n\n[EOF]\n','\n',char(10)),NULL,'auto-added',14663,2,0,NULL,NULL,'dpl_ac10','scan',1780048479);
INSERT INTO door_catalog VALUES('dpl_ad10','DPL-AD10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DPL-AD10.LHA','AddDB','XIM','AddDB',NULL,'Tango/DPL','DPL','.\____ \   /   _____   /  /\___  \---------. |/   /  \ /   / ______/  /   \/   \        | /_______/___ /   / /   _/\________/  DUPLO |',replace(' ____/\_____/\___________________           \n.\____ \   /   _____   /  /\___  \---------.\n|/   /  \ /   / ______/  /   \/   \        |\n/_______/___ /   / /   _/\________/  DUPLO |\n|          \/__ / /_______\-Mo!            |\n¦-------------\/---------------------------¦\n|            P R E S E N T S :             |\n|         AddDb v1.0, by Tango/DPL         |\n|   Have you made your conf.db files too   |\n|  small!? This is the sollution for you!  |\n`------------------------------------------''\n','\n',char(10)),'GoodBye.doc',replace('\n        .\n        :    :\n        :   /|\n        |  / | t A N G o                  _______\n        ._/  |___ _ ____________ _______ |      /_____________________\n       _ _   ___/____________   \     _ \|     /___________________   \\n        :    |     \      ______ \     \ \    / \______    |      |  . \_\n        :    l      \_    \    /  \_    \ \  /       |     |      ''     /\n      _ :_______     /_____\       /____|\  /______  `     |__________ /\n        |  -mNt\____/       \ ____/       \/      `--------''         \/\n        |                    \/                                      :\n        |                       o F   D U P L o                      |\n        |                                                            |\n        `---------------------- P R E S E N t S ----------------- - -''\n\n                                  AddDb v1.0\n\n                                 Idea by: Me!\n\n«-----------------------------------------------------------------------------»\n\n                                Important note!\n                               ~~~~~~~~~~~~~~~~~\nThis util is released under the concept of tradeware. If you like it and use\nit, upload some on my board. I will not take any responsability for whatever\nthis door does with your computer (It wont do anything but what it should, but\nyou never know what those lamers do!).\n\n«-----------------------------------------------------------------------------»\n\n                                 What it does!\n                                ~~~~~~~~~~~~~~~\nIf you''re running /X 3.x you have to create some small files in each conf\ndirectory for the message handling to work. What happens if you make these\nfiles too small!? Well, if you use JH''s utils you have to recreate those files\nto the new size and everybody have to reread all their messages! With this util\nyou simply add some more users to the conf.db files!\n\n«-----------------------------------------------------------------------------»\n\n                            Why use this one then!\n                           ~~~~~~~~~~~~~~~~~~~~~~~~\nWell, there are no replacement, if that''s not enough, it''s 1/3 of the size of\nJH''s original util. It''s even more powerfull, as you allready know, and it''s\nabout 10 times faster. Shape up JH!\n\n«-----------------------------------------------------------------------------»\n\n                                 Installation!\n                                ~~~~~~~~~~~~~~~\nWell run it from RAM: or whatever! :) Exaple usage:\n\nAddDb BBS:Conf1 100\n  ^       ^      ^\n  |       |      `----- Number of users to add to the conf.db file.\n  |       `------------ Conference path.\n  `-------------------- Command! :)\n\nIt''s noteable that if the conf.db''s don''t exist, this program will create em.\n\n«-----------------------------------------------------------------------------»\n\n                 These are the ß-sites for all my doors/utils!\n                ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n           Disorder               Marwin             ++46-456-27511\n           Forbidden Dreams       Manta              ++46-411-12894\n           Total Inferno          Tango              ++46-42-234164\n           Twisted Society        The Big Byte       ++46-44-106144\n\nAll my utils should be free dl, otherwise tell me and I''ll kick that ß-tester.\nIf you want to ß-test my doors/utils, contact me and we''ll work something out.\n\n«-----------------------------------------------------------------------------»\n\n                                  Greetings!\n                                 ~~~~~~~~~~~~\n    Melone - Krusty - Hoot - Marwin - Manta - The Big Byte - Norad - Venger\n    Zendor - Mike - Luca - Abbe - Stuff - Broder - Zync - Zych - La Fayette\n     Axe - Nebraska - Eracore - Linus - Avalon - Nero - Dixy - Crux - Nuke\n   Fuze - Fix - Kain - Prospex - Canaima - Pripps - Hilbert - Mital - D-Zire\n                  Jucke - Double - E-Go - Distler - Sy-Klone\n\nForgive me if I forgot someone. It''s not easy to remember everybody you know!\n\n[EOF]\n','\n',char(10)),NULL,'auto-added',6504,9,0,NULL,NULL,'dpl_ad10','scan',1780048479);
INSERT INTO door_catalog VALUES('dpl_an10','DPL-AN10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DPL-AN10.LHA','MessFix','XIM','____/\_____/\___________________',NULL,NULL,'DPL','.\____ \   /   _____   /  /\___  \---------. |/   /  \ /   / ______/  /   \/   \        | /_______/___ /   / /   _/\________/  DUPLO |',replace(' ____/\_____/\___________________           \n.\____ \   /   _____   /  /\___  \---------.\n|/   /  \ /   / ______/  /   \/   \        |\n/_______/___ /   / /   _/\________/  DUPLO |\n|          \/__ / /_______\-Mo!            |\n¦-------------\/---------------------------¦\n|            P R E S E N T S :             |\n|       Anonymus v1.0 & MessFix v1.0       |\n|  The complete package to for the sysop   |\n| who wants an area with anonymus messages |\n`------------------------------------------''\n','\n',char(10)),'Anonymus.doc',replace('\n        .\n        :    :\n        :   /|\n        |  / | t A N G o                  _______\n        ._/  |___ _ ____________ _______ |      /_____________________\n       _ _   ___/____________   \     _ \|     /___________________   \\n        :    |     \      ______ \     \ \    / \______    |      |  . \_\n        :    l      \_    \    /  \_    \ \  /       |     |      ''     /\n      _ :_______     /_____\       /____|\  /______  `     |__________ /\n        |  -mNt\____/       \ ____/       \/      `--------''         \/\n        |                    \/                                      :\n        |                       o F   D U P L o                      |\n        |                                                            |\n        `---------------------- P R E S E N t S ----------------- - -''\n\n                         Anonymus v1.0 & MessFix v1.0\n\n                              Idea by: Abbe/Indie\n\n«-----------------------------------------------------------------------------»\n\n                                Important note!\n                               ~~~~~~~~~~~~~~~~~\nThis util is released under the concept of tradeware. If you like it and use\nit, upload some on my board. I will not take any responsability for whatever\nthis door does with your computer (It wont do anything but what it should, but\nyou never know what those lamers do!).\n\n«-----------------------------------------------------------------------------»\n\n                                   History!\n                                  ~~~~~~~~~~\nv1.0 - First release of this cool litle door. Let you enter messages anonymus.\n       Together with the MessFix util the replys will also get anonymus.\n\n«-----------------------------------------------------------------------------»\n\n                                 Installation!\n                                ~~~~~~~~~~~~~~~\nCopy all files to their places. Note, if you want users to be able to enter\nanonymus messages in one or some confs only you''ll have to make new directories\ncalled ConfXCmd for these areas. Look in your /X manual for details.\n\nSysops who uses S-Express or /X 2.x will have to put the following line in\ntheir BBSCmd or ConfXCmd file(s).\n\n---( cut )---\nEA        XM020DOORS:Anonymus/Anonymus.x\n---( cut )---\n\nNow check out the information in the Anonymus.x.info. The tooltypes this\nprogrames reacts on is:\n\nFROMNAME : Let you chenge the name from whom an anonymus message is written.\n           Default is Anonymus :), but it may be anything....\nSYSOP    : Here state wich access is needed for sysop use of this door. The\n           only thing the sysop can do is to write anonymus messages to any\n           persons on the board. Otherwise all anonymus messages is routed to\n           all!\n\nNow it''s all set to run, but there''s one litle problem left. If a user replies\nto an anonymus message the message will be from that user to anonymus, wich\nisn''t present at your board. Therefor I''ve made a litle tool, the MessFix util,\nwich you must run in you logoffbatch in order to have those messages fixed. The\ntool changes all messages to anonymus, or whatever you choose in the icon\nabove, to a message from anonymus to all. Strange eh!? Well, check it out.\n\nThe usage of the MessFix util is as follows:\n\nMessFix <confpath> [path to anonymus.x]\n\nThe second argument must only be entered if anonymus.x is anywhere but in the\nDOORS:Anonymus directory. If you use the default settings and just copy the\nicons you don''t need this argument. Note that the util must be run once for\nevery conf there might be anonymus messages in, in order to have it all work.\n\n«-----------------------------------------------------------------------------»\n\n                 These are the ß-sites for all my doors/utils!\n                ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n       Asylum Altered State #1       Juan               ++46-317-759378\n       Asylum Altered State #2       Juan               ++46-317-759376\n       Disorder                      Marwin             ++46-456-27511\n       Imagine                       Rille              ++46-42-135505\n       Total Inferno                 Tango              ++46-42-234164\n       Twisted Society               The Big Byte       ++46-44-106144\n\nAll my utils should be free dl, otherwise tell me and I''ll kick that ß-tester.\nIf you want to ß-test my doors/utils, contact me and we''ll work something out.\n\n«-----------------------------------------------------------------------------»\n\n                                  Greetings!\n                                 ~~~~~~~~~~~~\n    Melone - Krusty - Hoot - Marwin - Manta - The Big Byte - Norad - Venger\n    Zendor - Mike - Luca - Abbe - Stuff - Broder - Zync - Zych - La Fayette\n     Axe - Nebraska - Eracore - Linus - Avalon - Nero - Dixy - Crux - Nuke\n   Fuze - Fix - Kain - Prospex - Canaima - Pripps - Hilbert - Mital - D-Zire\n        Jucke - Double - E-Go - Distler - Sy-Klone - Fazer - Zcandaler\n   Beavis & Butthead - Renko - Juan - Guardian - EaSy RiDeR - Wozzy - Suggs\n                            Rille - Fonus - Proctor\n\nForgive me if I forgot someone. It''s not easy to remember everybody you know!\n\n[EOF]\n','\n',char(10)),NULL,NULL,18624,2,0,NULL,NULL,NULL,'scan',1780048479);
INSERT INTO door_catalog VALUES('dpl_an13','DPL-AN13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DPL-AN13.LHA',NULL,'XIM','LE-win5-96.exe',NULL,'Tango/DPL','DPL','.\____ \   /   _____   /  /\___  \---------. |/   /  \ /   / ______/  /   \/   \        | /_______/___ /   / /   _/\________/  DUPLO |',replace(' ____/\_____/\___________________           \n.\____ \   /   _____   /  /\___  \---------.\n|/   /  \ /   / ______/  /   \/   \        |\n/_______/___ /   / /   _/\________/  DUPLO |\n|          \/__ / /_______\-Mo!            |\n¦-------------\/---------------------------''\n|             P R E S E N T S\n|       Announce v1.3, by Tango/DPL\n|   Announces logons on any nodes with a\n|  window on the frontmost screen. A must\n|             for all sysops!\n`----------------------------------------->\n- -[ fLYING DRAGON ]- - -  --[ rEAL WHq ]- -\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                                                .------''\n             `------------------------------------------------''\n','\n',char(10)),NULL,'auto-added',22382,6,0,NULL,NULL,'dpl_an13','scan',1780048479);
INSERT INTO door_catalog VALUES('dpl_ao10','DPL-AO10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DPL-AO10.LHA',NULL,'XIM','ASCIIOrder.x',NULL,'Tango/DPL','DPL','.\____ \   /   _____   /  /\___  \---------. |/   /  \ /   / ______/  /   \/   \        | /_______/___ /   / /   _/\________/  DUPLO |',replace(' ____/\_____/\___________________           \n.\____ \   /   _____   /  /\___  \---------.\n|/   /  \ /   / ______/  /   \/   \        |\n/_______/___ /   / /   _/\________/  DUPLO |\n|          \/__ / /_______\-Mo!            |\n¦-------------\/---------------------------¦\n|            P R E S E N T S :             |\n| The first working ASCIIOrder door for /X |\n|      ASCIIOrder v1.0, by Tango/DPL       |\n`------------------------------------------''\n','\n',char(10)),'ASCIIOrder.doc',replace('\n        .\n        :    :\n        :   /|\n        |  / | t A N G o                  _______\n        ._/  |___ _ ____________ _______ |      /_____________________\n       _ _   ___/____________   \     _ \|     /___________________   \\n        :    |     \      ______ \     \ \    / \______    |      |  . \_\n        :    l      \_    \    /  \_    \ \  /       |     |      ''     /\n      _ :_______     /_____\       /____|\  /______  `     |__________ /\n        |  -mNt\____/       \ ____/       \/      `--------''         \/\n        |                    \/                                      :\n        |                       o F   D U P L o                      |\n        |                                                            |\n        `---------------------- P R E S E N t S ----------------- - -''\n\n                               ASCII-Order v1.0\n\n                            Idea by: Manta & Stuff\n\n«-----------------------------------------------------------------------------»\n\n                                Important note!\n                               ~~~~~~~~~~~~~~~~~\nThis util is released under the concept of tradeware. If you like it and use\nit, upload some on my board. I will not take any responsability for whatever\nthis door does with your computer (It wont do anything but what it should, but\nyou never know what those lamers do!).\n\n«-----------------------------------------------------------------------------»\n\n                                 What it does!\n                                ~~~~~~~~~~~~~~~\nThis is a quite simple ASCII-Order door. It has the ability to post messages to\npainters etc. Try it out.\n\n«-----------------------------------------------------------------------------»\n\n                            Why use this one then!\n                           ~~~~~~~~~~~~~~~~~~~~~~~~\nAs far as I know, this is the only one that actually worx. If that''s not\nenough, how about the ability to select multiple painters for a logo with one\nsingle command, or the nice litel bulletin stuffed into it!?\n\n«-----------------------------------------------------------------------------»\n\n                                 Installation!\n                                ~~~~~~~~~~~~~~~\nIf you run /X 3.x, copy all files I''ve supplied and your set.\n\nIf you run /X 2.x or S-Express, insert the followin line to your\n"commands/bbs.cmd" file.\n\n---( cut )---\nORDER     XM020DOORS:ASCIIOrder/ASCIIOrder.x\n---( cut )---\n\nThen there''s the configfile, "DOORS:ASCIIOrder/ASCIIOrder.cfg". At the top of\nit you should enter all the guys that will have sysop status, then a single ";"\non a line, and after that all painters. Simple, eh!? Well, if you don''t\nunderstand, check out the example file in this package!\n\n«-----------------------------------------------------------------------------»\n\n                 These are the ß-sites for all my doors/utils!\n                ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n           Disorder               Marwin             ++46-456-27511\n           Forbidden Dreams       Manta              ++46-411-12894\n           Total Inferno          Tango              ++46-42-234164\n           Twisted Society        The Big Byte       ++46-44-106144\n\nAll my utils should be free dl, otherwise tell me and I''ll kick that ß-tester.\nIf you want to ß-test my doors/utils, contact me and we''ll work something out.\n\n«-----------------------------------------------------------------------------»\n\n                                  Greetings!\n                                 ~~~~~~~~~~~~\n    Melone - Krusty - Hoot - Marwin - Manta - The Big Byte - Norad - Venger\n    Zendor - Mike - Luca - Abbe - Stuff - Broder - Zync - Zych - La Fayette\n     Axe - Nebraska - Eracore - Linus - Avalon - Nero - Dixy - Crux - Nuke\n   Fuze - Fix - Kain - Prospex - Canaima - Pripps - Hilbert - Mital - D-Zire\n                  Jucke - Double - E-Go - Distler - Sy-Klone\n\nForgive me if I forgot someone. It''s not easy to remember everybody you know!\n\n[EOF]\n','\n',char(10)),NULL,'auto-added',20710,4,0,NULL,NULL,'dpl_ao10','scan',1780048479);
INSERT INTO door_catalog VALUES('dpl_ao11','DPL-AO11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DPL-AO11.LHA',NULL,'XIM','ASCIIOrder.x',NULL,'Tango/DPL','DPL','.\____ \   /   _____   /  /\___  \---------. |/   /  \ /   / ______/  /   \/   \        | /_______/___ /   / /   _/\________/  DUPLO |',replace(' ____/\_____/\___________________           \n.\____ \   /   _____   /  /\___  \---------.\n|/   /  \ /   / ______/  /   \/   \        |\n/_______/___ /   / /   _/\________/  DUPLO |\n|          \/__ / /_______\-Mo!            |\n¦-------------\/---------------------------¦\n|            P R E S E N T S :             |\n| The first working ASCIIOrder door for /X |\n|      ASCIIOrder v1.1, by Tango/DPL       |\n`------------------------------------------''\n','\n',char(10)),'ASCIIOrder.doc',replace('\n        .\n        :    :\n        :   /|\n        |  / | t A N G o                  _______\n        ._/  |___ _ ____________ _______ |      /_____________________\n       _ _   ___/____________   \     _ \|     /___________________   \\n        :    |     \      ______ \     \ \    / \______    |      |  . \_\n        :    l      \_    \    /  \_    \ \  /       |     |      ''     /\n      _ :_______     /_____\       /____|\  /______  `     |__________ /\n        |  -mNt\____/       \ ____/       \/      `--------''         \/\n        |                    \/                                      :\n        |                       o F   D U P L o                      |\n        |                                                            |\n        `---------------------- P R E S E N t S ----------------- - -''\n\n                               ASCII-Order v1.1\n\n                            Idea by: Manta & Stuff\n                 v1.1 Improvements suggested by: The Big Byte\n\n«-----------------------------------------------------------------------------»\n\n                                Important note!\n                               ~~~~~~~~~~~~~~~~~\nThis util is released under the concept of tradeware. If you like it and use\nit, upload some on my board. I will not take any responsability for whatever\nthis door does with your computer (It wont do anything but what it should, but\nyou never know what those lamers do!).\n\n«-----------------------------------------------------------------------------»\n\n                                 What it does!\n                                ~~~~~~~~~~~~~~~\nThis is a quite simple ASCII-Order door. It has the ability to post messages to\npainters etc. Try it out.\n\n«-----------------------------------------------------------------------------»\n\n                            Why use this one then!\n                           ~~~~~~~~~~~~~~~~~~~~~~~~\nAs far as I know, this is the only one that actually worx. If that''s not\nenough, how about the ability to select multiple painters for a logo with one\nsingle command, or the nice litel bulletin stuffed into it!?\n\n«-----------------------------------------------------------------------------»\n\n                                   History!\n                                  ~~~~~~~~~~\nv1.0 - Initial release. Simple and working.\nv1.1 - Added the ability to controll wich conference the messages would be put\n       in, and a bulletin of your choise!\n\n«-----------------------------------------------------------------------------»\n\n                                 Installation!\n                                ~~~~~~~~~~~~~~~\nIf you run /X 3.x, copy all files I''ve supplied and your set.\n\nIf you run /X 2.x or S-Express, insert the followin line to your\n"commands/bbs.cmd" file.\n\n---( cut )---\nORDER     XM020DOORS:ASCIIOrder/ASCIIOrder.x\n---( cut )---\n\nThen there''s the configfile, "DOORS:ASCIIOrder/ASCIIOrder.cfg". At the top two\nlines of it, you should enter the path to your ascii-conf and the name of the\nbulletin the door should create. If no bulletin, enter NIL: on that line.\nExample:\n\n---( cut )---\nBBS:Conf6/\nBBS:Conf6/BULL.TXT\n---( cut )---\n\nDon''t forgett the tailing "/" on the first line.\nAfter this you may enter all guys with sysop status, one on each line, the a\nline with a single ";" and finnaly all your painters, one on each line. If you\nused v1.0 of this the only thing you have to do is to insert the ConfPath and\nBulletinName at the two first lines.\n\n«-----------------------------------------------------------------------------»\n\n                 These are the ß-sites for all my doors/utils!\n                ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n       Asylum Altered State #1       Juan               ++46-317-759378\n       Asylum Altered State #2       Juan               ++46-317-759376\n       Disorder                      Marwin             ++46-456-27511\n       Forbidden Dreams              Manta              ++46-411-12894\n       Total Inferno                 Tango              ++46-42-234164\n       Twisted Society               The Big Byte       ++46-44-106144\n\nAll my utils should be free dl, otherwise tell me and I''ll kick that ß-tester.\nIf you want to ß-test my doors/utils, contact me and we''ll work something out.\n\n«-----------------------------------------------------------------------------»\n\n                                  Greetings!\n                                 ~~~~~~~~~~~~\n    Melone - Krusty - Hoot - Marwin - Manta - The Big Byte - Norad - Venger\n    Zendor - Mike - Luca - Abbe - Stuff - Broder - Zync - Zych - La Fayette\n     Axe - Nebraska - Eracore - Linus - Avalon - Nero - Dixy - Crux - Nuke\n   Fuze - Fix - Kain - Prospex - Canaima - Pripps - Hilbert - Mital - D-Zire\n        Jucke - Double - E-Go - Distler - Sy-Klone - Fazer - Zcandaler\n                  Beavis & Butthead - Renko - Juan - Guardian\n\nForgive me if I forgot someone. It''s not easy to remember everybody you know!\n\n[EOF]\n','\n',char(10)),NULL,'auto-added',41647,14,0,NULL,NULL,'dpl_ao11','scan',1780048479);
INSERT INTO door_catalog VALUES('dpl_ao12','DPL-AO12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DPL-AO12.LHA',NULL,'XIM','____/\_____/\___________________',NULL,'Tango/DPL','DPL','.\____ \   /   _____   /  /\___  \---------. |/   /  \ /   / ______/  /   \/   \        | /_______/___ /   / /   _/\________/  DUPLO |',replace(' ____/\_____/\___________________           \n.\____ \   /   _____   /  /\___  \---------.\n|/   /  \ /   / ______/  /   \/   \        |\n/_______/___ /   / /   _/\________/  DUPLO |\n|          \/__ / /_______\-Mo!            |\n¦-------------\/---------------------------¦\n|            P R E S E N T S :             |\n| The first working ASCIIOrder door for /X |\n|      ASCIIOrder v1.2, by Tango/DPL       |\n`------------------------------------------''\n','\n',char(10)),'ASCIIOrder.doc',replace('\n        .\n        :    :\n        :   /|\n        |  / | t A N G o                  _______\n        ._/  |___ _ ____________ _______ |      /_____________________\n       _ _   ___/____________   \     _ \|     /___________________   \\n        :    |     \      ______ \     \ \    / \______    |      |  . \_\n        :    l      \_    \    /  \_    \ \  /       |     |      ''     /\n      _ :_______     /_____\       /____|\  /______  `     |__________ /\n        |  -mNt\____/       \ ____/       \/      `--------''         \/\n        |                    \/                                      :\n        |                       o F   D U P L o                      |\n        |                                                            |\n        `---------------------- P R E S E N t S ----------------- - -''\n\n                               ASCII-Order v1.2\n\n                            Idea by: Manta & Stuff\n                 v1.1 Improvements suggested by: The Big Byte\n                           v1.2 Improvements by: Me\n\n«-----------------------------------------------------------------------------»\n\n                                Important note!\n                               ~~~~~~~~~~~~~~~~~\nThis util is released under the concept of tradeware. If you like it and use\nit, upload some on my board. I will not take any responsability for whatever\nthis door does with your computer (It wont do anything but what it should, but\nyou never know what those lamers do!).\n\n«-----------------------------------------------------------------------------»\n\n                                 What it does!\n                                ~~~~~~~~~~~~~~~\nThis is a quite simple ASCII-Order door. It has the ability to post messages to\npainters etc. Try it out.\n\n«-----------------------------------------------------------------------------»\n\n                            Why use this one then!\n                           ~~~~~~~~~~~~~~~~~~~~~~~~\nAs far as I know, this is the only one that actually worx. If that''s not\nenough, how about the ability to select multiple painters for a logo with one\nsingle command, or the nice litel bulletin stuffed into it!?\n\n«-----------------------------------------------------------------------------»\n\n                                   History!\n                                  ~~~~~~~~~~\nv1.0 - Initial release. Simple and working.\nv1.1 - Added the ability to controll wich conference the messages would be put\n       in, and a bulletin of your choise!\nv1.2 - Added the ability to view a sample of the art a painter is producing.\n       Ofcourse the sysop has to put it in. Also removed the hardcoded path\n       (DOORS:ASCIIOrder/). Kind''a lame. Now you may have it anywhere as long\n       as the files is in the same dir.\n\n       Look out for v2.0 of this door. I looked at my source today and looked\n       literaly like SHIT! :) Well, I must have improved some since I made this\n       and it''s up for optimizion as soon as get the time to do it.\n\n«-----------------------------------------------------------------------------»\n\n                                 Installation!\n                                ~~~~~~~~~~~~~~~\nIf you run /X 3.x, copy all files I''ve supplied and your set.\n\nIf you run /X 2.x or S-Express, insert the followin line to your\n"commands/bbs.cmd" file.\n\n---( cut )---\nORDER     XM020DOORS:ASCIIOrder/ASCIIOrder.x\n---( cut )---\n\nThen there''s the configfile, "DOORS:ASCIIOrder/ASCIIOrder.cfg". At the top two\nlines of it, you should enter the path to your ascii-conf and the name of the\nbulletin the door should create. If no bulletin, enter NIL: on that line.\nExample:\n\n---( cut )---\nBBS:Conf6/\nBBS:Conf6/BULL.TXT\n---( cut )---\n\nDon''t forgett the tailing "/" on the first line.\nAfter this you may enter all guys with sysop status, one on each line, the a\nline with a single ";" and finnaly all your painters, one on each line. If you\nused v1.0 of this the only thing you have to do is to insert the ConfPath and\nBulletinName at the two first lines.\n\nIf you want to use the sample art stuff (If you don''t, stick to v1.1!), place\na file called <name>.txt for every painter. Ex: "Kain.txt" is an example of\nKains art.\n\n«-----------------------------------------------------------------------------»\n\n                 These are the ß-sites for all my doors/utils!\n                ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n       Asylum Altered State #1       Juan               ++46-317-759378\n       Asylum Altered State #2       Juan               ++46-317-759376\n       Disorder                      Marwin             ++46-456-27511\n       Imagine                       Rille              ++46-42-135505\n       Total Inferno                 Tango              ++46-42-234164\n       Twisted Society               The Big Byte       ++46-44-106144\n\nAll my utils should be free dl, otherwise tell me and I''ll kick that ß-tester.\nIf you want to ß-test my doors/utils, contact me and we''ll work something out.\n\n«-----------------------------------------------------------------------------»\n\n                                  Greetings!\n                                 ~~~~~~~~~~~~\n    Melone - Krusty - Hoot - Marwin - Manta - The Big Byte - Norad - Venger\n    Zendor - Mike - Luca - Abbe - Stuff - Broder - Zync - Zych - La Fayette\n     Axe - Nebraska - Eracore - Linus - Avalon - Nero - Dixy - Crux - Nuke\n   Fuze - Fix - Kain - Prospex - Canaima - Pripps - Hilbert - Mital - D-Zire\n        Jucke - Double - E-Go - Distler - Sy-Klone - Fazer - Zcandaler\n   Beavis & Butthead - Renko - Juan - Guardian - EaSy RiDeR - Wozzy - Suggs\n                            Rille - Fonus - Proctor\n\nForgive me if I forgot someone. It''s not easy to remember everybody you know!\n\n[EOF]\n','\n',char(10)),NULL,NULL,25106,3,0,NULL,NULL,NULL,'scan',1780048479);
INSERT INTO door_catalog VALUES('dpl_ax10','DPL-AX10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DPL-AX10.LHA',NULL,'XIM','____/\_____/\___________________',NULL,'Tango/DPL','DPL','.\____ \   /   _____   /  /\___  \---------. |/   /  \ /   / ______/  /   \/   \        | /_______/___ /   / /   _/\________/  DUPLO |',replace(' ____/\_____/\___________________           \n.\____ \   /   _____   /  /\___  \---------.\n|/   /  \ /   / ______/  /   \/   \        |\n/_______/___ /   / /   _/\________/  DUPLO |\n|          \/__ / /_______\-Mo!            |\n¦-------------\/---------------------------¦\n|            P R E S E N T S :             |\n|     -> AxxOpen v1.0, by Tango/DPL <-     |\n| The OPEN command we''ve all been waiting  |\n|    for! Let users have diffrent menus    |\n|      depending on their axx-level!       |\n`------------------------------------------''\n','\n',char(10)),'AxxOpen.doc',replace('\n        .\n        :    :\n        :   /|\n        |  / | t A N G o                  _______\n        ._/  |___ _ ____________ _______ |      /_____________________\n       _ _   ___/____________   \     _ \|     /___________________   \\n        :    |     \      ______ \     \ \    / \______    |      |  . \_\n        :    l      \_    \    /  \_    \ \  /       |     |      ''     /\n      _ :_______     /_____\       /____|\  /______  `     |__________ /\n        |  -mNt\____/       \ ____/       \/      `--------''         \/\n        |                    \/                                      :\n        |                       o F   D U P L o                      |\n        |                                                            |\n        `---------------------- P R E S E N t S ----------------- - -''\n\n                                 AxxOpen v1.0\n\n                              Idea by: Double/DPL\n\n«-----------------------------------------------------------------------------»\n\n                                Important note!\n                               ~~~~~~~~~~~~~~~~~\nThis util is released under the concept of tradeware. If you like it and use\nit, upload some on my board. I will not take any responsability for whatever\nthis door does with your computer (It wont do anything but what it should, but\nyou never know what those lamers do!).\n\n«-----------------------------------------------------------------------------»\n\n                                   History!\n                                  ~~~~~~~~~~\nv1.0 - First release! You''re able to have diffrent menus for diffrent\n       axx-levels. You may also have a logo at the top.\n\n«-----------------------------------------------------------------------------»\n\n                                 Installation!\n                                ~~~~~~~~~~~~~~~\nIf you run /X 3.x, copy all files I''ve supplied and your set.\n\nIf you run /X 2.x or S-Express, insert the followin line to your\n"commands/bbs.cmd" file.\n\n---( cut )---\nOPEN      XM001DOORS:AxxOpen/AxxOpen.x\n---( cut )---\n\nThe files you have to edit is "AxxOpen.logo" wich should be the top logo and\n"AxxOpen.cfg" wich is the file where you should put all your doors in. The\nformat is as follows.\n\n20:This line shows if axx>=20\n255:This line shows if axx>=255\n\nYou can put ANSI-codes into the line if you want, and you may center it etc.\nie. the line must not have a non-space right after the '':''.\n\n«-----------------------------------------------------------------------------»\n\n                 These are the ß-sites for all my doors/utils!\n                ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n       Asylum Altered State #1       Juan               ++46-317-759378\n       Asylum Altered State #2       Juan               ++46-317-759376\n       Disorder                      Marwin             ++46-456-27511\n       Imagine                       Rille              ++46-42-135505\n       Total Inferno                 Tango              ++46-42-234164\n       Twisted Society               The Big Byte       ++46-44-106144\n\nAll my utils should be free dl, otherwise tell me and I''ll kick that ß-tester.\nIf you want to ß-test my doors/utils, contact me and we''ll work something out.\n\n«-----------------------------------------------------------------------------»\n\n                                  Greetings!\n                                 ~~~~~~~~~~~~\n    Melone - Krusty - Hoot - Marwin - Manta - The Big Byte - Norad - Venger\n    Zendor - Mike - Luca - Abbe - Stuff - Broder - Zync - Zych - La Fayette\n     Axe - Nebraska - Eracore - Linus - Avalon - Nero - Dixy - Crux - Nuke\n   Fuze - Fix - Kain - Prospex - Canaima - Pripps - Hilbert - Mital - D-Zire\n        Jucke - Double - E-Go - Distler - Sy-Klone - Fazer - Zcandaler\n   Beavis & Butthead - Renko - Juan - Guardian - EaSy RiDeR - Wozzy - Suggs\n                            Rille - Fonus - Proctor\n\nForgive me if I forgot someone. It''s not easy to remember everybody you know!\n\n[EOF]\n','\n',char(10)),NULL,NULL,12508,2,0,NULL,NULL,NULL,'scan',1780048479);
INSERT INTO door_catalog VALUES('dpl_fa10','DPL_FA10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DPL_FA10.LHA',NULL,'XIM','Frontavail.x',NULL,'LINUS/DPL!|','DPL','!====\\\\____,\\//,:,\\____,\/,:===/ .,\\/=! |        / ,|\ \/  |\ \/  /  \ |  /  |\ \  | |      ./   l/ \\  l/ \\  |__/ l//,\ l/ \\ |',replace('      _ ______ __ _._ ______  _.    ___ __  \n!====\\\\____,\\//,:,\\____,\/,:===/ .,\\/=!\n|        / ,|\ \/  |\ \/  /  \ |  /  |\ \  |\n|      ./   l/ \\  l/ \\  |__/ l//,\ l/ \\ |\n|    .::\______x/_____x/_xl\______x/____x/.|\n|    ~ ~~~~~~~\/~~~~~\/~~~~~~~~~~\/~~~~\/~~|\n|/X-Design!!!=====[ PROUDLY PRESENTS ]=$t5=!\n|-=-=-=-=-=-| FrontAvail V1.0 by LINUS/DPL!|\n`-----------''------------------------------''\n','\n',char(10)),'Frontavail.DOC',replace('      _ __ ___________ ________/\ __________ ________  ___________\n          \\_______  ¬\__     /  \_______  ¬\__     /_ \__    _  ¬\_ __ _\n  .---------/     /    /     /    /    ______/     / ¬\_/     /    //-----.\n  |--------/     /    /     /    /     /----/     /    /     /    /-------|\n  |·DUPLO·/     /    /     /    /     /    /     /    /     /    /·DUPLO!·|\n  |------/_____     /_____     /\    /----/_____     /_____     /---------|\n  `----------/_____/----/_____/--\  /kRm------/_____/----/_____/----------''\n   AMIEX-DESIGN!                  \/                          AMIEX-DESIGN\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n	\n              Presents:      FrontAvail V1.0 by Linus/DPL 1994\n\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\nFIRST ONE THING: I HATE WRITING DOCS! IF YOU LIKE TO WRITE MINE CALL ME!!!\nTHIS PIECE IS TRADEWARE SO DO SUM UPLOADS ON MY BBS IF YOU USE IT!!!!!!!!!\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n\nThis door was coded by me, `cause I`ve seen another door which do the SAME\nthing as mine... BUT I added one Feature and my style is very DIFFRENT!\n\nThe second case Why i coded it, was That I (as USER) Want to see if the \nSYSOP is reachable or not! Don`t know why but i want it! :))\n\n\n\nInstallion:\n\nHMPF... The /X 3.3x Sysops should copy the FRONTEND.INFO to SYSCMD Dir.\nNow they have to put the Frontavail MAINprogram to a Directory they wish!\nEdit your FRONTEND.INFO with the Paths! AND ALLLL SHOULD WORK!\n\nUFZ... The /X2.xx Sysops have to look how they Install it ... NOT! Ok..\nPut this to YOUR SYS.CMD\n\nCutttttttt\n----------\nFrontend  XM010DOORS:FRONTAVAIL.X\n----------\nCutttttttt\n\nSo it should work! Have fun! Any Ideas to change or only by FREINDSHIP so \ncall:\n\n                ++49 6723 5622     DUPLO GHQ! Sysop: LINuS/DPL!\n\n\n\n    Greetz to: Suggs, TANGO, KAIN, Double, H00t, Raiden, Lord/sp!, Ronny, \n	   The Smurf, and so on! (all my FRIENDS and thos whose i`ve\n                              forgotten toooo!!!)\n\n                DUPLO Germany - Die laengste Praline der Welt!','\n',char(10)),NULL,'auto-added',9307,4,0,NULL,NULL,'dpl_fa10','scan',1780048488);
