INSERT INTO door_catalog VALUES('dpl_fs10','DPL-FS10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DPL-FS10.LHA',NULL,'XIM','____/\_____/\___________________',NULL,'Tango/DPL''94','DPL','.\____ \   /   _____   /  /\___  \---------. |/   /  \ /   / ______/  /   \/   \        | /_______/___ /   / /   _/\________/  DUPLO |',replace(' ____/\_____/\___________________           \n.\____ \   /   _____   /  /\___  \---------.\n|/   /  \ /   / ______/  /   \/   \        |\n/_______/___ /   / /   _/\________/  DUPLO |\n|          \/__ / /_______\-Mo!            |\n¦-------------\/---------------------------¦\n|            P R E S E N T S :             |\n|    FrontScream v1.0, by Tango/DPL''94     |\n`------------------------------------------''\n','\n',char(10)),'FrontScream.doc',replace('\n        .\n        :    :\n        :   /|\n        |  / | t A N G o                  _______\n        ._/  |___ _ ____________ _______ |      /_____________________\n       _ _   ___/____________   \     _ \|     /___________________   \\n        :    |     \      ______ \     \ \    / \______    |      |  . \_\n        :    l      \_    \    /  \_    \ \  /       |     |      ''     /\n      _ :_______     /_____\       /____|\  /______  `     |__________ /\n        |  -mNt\____/       \ ____/       \/      `--------''         \/\n        |                    \/                                      :\n        |                       o F   D U P L o                      |\n        |                                                            |\n        `---------------------- P R E S E N t S ----------------- - -''\n\n                               FrontScream v1.0\n\n                                 Idea by: Abbe\n\n«-----------------------------------------------------------------------------»\n\n                                Important note!\n                               ~~~~~~~~~~~~~~~~~\nThis util is released under the concept of tradeware. If you like it and use\nit, upload some on my board. I will not take any responsability for whatever\nthis door does with your computer (It wont do anything but what it should, but\nyou never know what those lamers do!).\n\n«-----------------------------------------------------------------------------»\n\n                                   History!\n                                  ~~~~~~~~~~\nv1.0 - A friend of mine wanted a litle replacement for the ANSI on/off question\n       at logon. I made this litle sucka for him. With this, the user may\n       scream for the sysop at the ANSI-question. Good if you forget your PW or\n       just wanna say something to the sysop!\n\n«-----------------------------------------------------------------------------»\n\n                                 Installation!\n                                ~~~~~~~~~~~~~~~\nIf you run /X 3.x, copy all files I''ve supplied and your set.\n\nIf you run /X 2.x or S-Express, insert the followin line to your\n"commands/sys.cmd" file.\n\n---( cut )---\nANSI      XM001DOORS:FrontScream/FrontScream.x\n---( cut )---\n\nIt''s as simple as that! :)\n\n«-----------------------------------------------------------------------------»\n\n                 These are the ß-sites for all my doors/utils!\n                ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n       Asylum Altered State #1       Juan               ++46-317-759378\n       Asylum Altered State #2       Juan               ++46-317-759376\n       Disorder                      Marwin             ++46-456-27511\n       Imagine                       Rille              ++46-42-135505\n       Total Inferno                 Tango              ++46-42-234164\n       Twisted Society               The Big Byte       ++46-44-106144\n\nAll my utils should be free dl, otherwise tell me and I''ll kick that ß-tester.\nIf you want to ß-test my doors/utils, contact me and we''ll work something out.\n\n«-----------------------------------------------------------------------------»\n\n                                  Greetings!\n                                 ~~~~~~~~~~~~\n    Melone - Krusty - Hoot - Marwin - Manta - The Big Byte - Norad - Venger\n    Zendor - Mike - Luca - Abbe - Stuff - Broder - Zync - Zych - La Fayette\n     Axe - Nebraska - Eracore - Linus - Avalon - Nero - Dixy - Crux - Nuke\n   Fuze - Fix - Kain - Prospex - Canaima - Pripps - Hilbert - Mital - D-Zire\n        Jucke - Double - E-Go - Distler - Sy-Klone - Fazer - Zcandaler\n   Beavis & Butthead - Renko - Juan - Guardian - EaSy RiDeR - Wozzy - Suggs\n                            Rille - Fonus - Proctor\n\nForgive me if I forgot someone. It''s not easy to remember everybody you know!\n\n[EOF]\n','\n',char(10)),NULL,NULL,5766,1,0,NULL,NULL,NULL,'scan',1780048488);
