INSERT INTO door_catalog VALUES('dtcms12','DTCMS12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DTCMS12.LHA','Say','XIM','Say',NULL,'BiTMasTeR/DTC',NULL,':  _______________               : | |  _ \_   _/ _ / DiGiTaL ChAoS : | | |_\ \| || (__  BrOuGhT YoU   |',replace('.--------------------------------.\n:  _______________               :\n| |  _ \_   _/ _ / DiGiTaL ChAoS :\n| | |_\ \| || (__  BrOuGhT YoU   |\n| |_____/|_| \___\   ToDaY:    <-''\n|\n! -< D¡G¡TaL ChAøS  /X Division >-\n:\n`------> MultiStats 1.2 \n        by BiTMasTeR/DTC\n The Best Multi Functional Tool\nTry It Out Just Have a Look at It\n     !Iff Example InSide !\n','\n',char(10)),'MultiStats.guide',replace('@DataBase DTC-MultiTool-1.2 By BitMaster of Digital Chaos - /X Division\n\n®© (c) 1994-1995 B¡TMaster øf Digital Chaos\n\n@Remark $VER: DTC-MultiTool v1.2\n\n@Node Main "DTC-MultiTool Documentation (c) 1994-1995 BiTMasTeR-DTC"\n            	                    	       .\n                  ___________________/\	______/|__________/\\n                 .\___________________ Y__  _	____	___/\n                 |	 	/  __ \	\ \//  |BM!/   /\n                 |*-D¡G¡TaL    /   \__/	/  /   |  /    \___/\\n                 |	ChaoS-*\_______/  /____|  \________ /\n                 |	 	 	 	 	   Y\n                 `-=[DTC /X-Division]=---------------------''\n                         D¡G¡TaL ChAoS Present To Ya :\n                           --[> MultiStats1.2 <]-- \n                   @{"   " Link Part1} What it is?        @{"   " Link Part2} Requirements\n                   @{"   " Link Part3} Installation       @{"   " Link Part4} Configuration\n                   @{"   " Link Part5} Greetings          @{"   " Link Part6} Contacts\n                   @{"   " Link Part7} Wanna Join ?       @{"   " Link Part8} DTC Member List\n                   @{"   " Link Part9} DTC Softographi!   @{"   " Link Part99} The Next Time\n                   \n                   @{"              C R E D I T Z               " Link Part33}\n@Endnode\n@Node Part1 "What It Is"\nHi Folks!\nMultiStats is More then an ''S'' replacement Command For Your AmiExpress\n   Multi Stats Gives Ya:\n * Global Infos of a User\n * Many Info''s of Your Board\n * Nice Awesome Design :)\n * Very Small Code\n * 255 Level Hacking Control\n * Vocal Advert When User Docks In\n * SysOp Status (Chattable or Not)\n * MANY Kinds of Applikations! (See in Installation)\n   And Finally:\n * Controls The User Aktivities\n   If The User has more DownLoads of Uploads Then Displays One RANDOM\n   Comment Line From a DataBase of Comments\n   There a 2 DataBase''s, 1 With comments for Leecher''s and an other\n   with comments for good Uppers!\n   This DataBase''s are redefinable from the sysop by adding,changing or\n   deleting comments via a simple Text Editor\n\n * 9 Greeat Reasons ,to Select The Best.!\n   Get The Best And Fuck The Rest!  Competition is None!\n@EndNode\n@Node Part2 " Requirements"\n      To install MultiStats on Your System u Must Have :\n\n    - An Amiga 500-600-1000-1200-1500-2000-2500-3000-4000-5000-CDTV-CD³²-c64(?)\n    - An Operating System 2.0 3.0 or 4.0 or higher\n    - AmiExpress 3.x or 4.x \n    - Nothing Else\n    \n\n    - Tested on :\n      A4000/040/33Mhz 16 MB RAM ecc. (DIGITAL UNDERGROUNDClick ->)@{"   " Link DU}\n\n    - Tested on : \n      A1200/030/40Mhz 7MB RAM ecc. ( POINT OF NO RETURN  Click ->)@{"   " Link Part11}\n\n    - NOT Tested On :\n      Snes - GameBoy - Lynx - and on the TypeWriters (PeeCee)\n@EndNode\n@Node Part3 "Installation"\n\n Installing it as a simple Status Command!\n 1) Copy The S.Info Icon in Your BBS:Commands/BBSCMD/ Directory\n 2) Copy All the DTC Directory in Your BBS:Doors/ Directory\n\n Installing it as a simple Status Join Conference\n 1) Copy The S.Info Icon In The BBS:Commands/SYSCMD/ Directory\n 2) Copy All The DTC Directory in Your BBS:Doors/ Directory\n\n Installing for Viewing Before a Upload or A DownLoad\n 1) Edit the UP/DownLoad Bull ..or..\n 1) Put The UPLOAD.Info and The DOWNLOAD.Info in The\n    BBS:Commands/SysCMD/ Directory.!\n 2) Copy All The DTC Directory in Your BBS:Doors/ Directory\n  \n\n Installing Where You Want (before Joining a Conference loggin In..)\n 1) Edit the Bulls... you know how..!\n 2) Copy All The DTC Dir..... in Doors:\n\n@EndNode\n@Node Part4 "Configurating "\nThe Config File''s Are 3,and are;\n\nThe 255 Level Control File That must be Called "255Users"\nAnd Must be Like This\n----------(Cut)-----------\n5                         <-Number of User''s With The 255 Level\nBitMasTeR                 <-Name Of The SysOp.......\nAnDrOiD/TLN               <-... and All The CosysOps\nICE MC - DTC              <- And The Rest of Friends With 255 Lvl\nMr. CaSe SeNsItiVE        <- THis Is Case sensitive \nSoMeBODY of SomeGroUP     <- Put in The Name How it is, with Caps On and Of\n----------(Cut)-----------   \n\nThe Leecher File And The Uploader File Are Named : Leech.File and Upper.File\nSame Discussion Above... remember to put in the FIRST line the number of SysOps\nor the Number of Comments ,in the case of the Leecher or Upper Comment File''s.\n@EndNode\n@Node Part5 " Greetings and Advs"\n GreeTing Go Out To All These :\n\n  Android/Talent............... Bcoz he is The No.1 8)\n  HantareX/DTC................. 4 The BetaTesting and All The Suggestions \n  Ice MC/DTC................... Bcoz is the Boss ;)\n  Prince Of Thieves/DTC........ w8ing u 4 a nice Voice Chat.\n  DuPrEe''s PaRaDiSe/DTC........ Very CøøL Musician!\n  Prayer/TRSI.................. How is going in AUSTRIA? \n  KRS-NiCK-LaRRy............... Bcoz they are DTC Brothers!\n  RiSC......................... The RayTracer Man\n \n                           And In Randomly Order:  \n-=*=-  SauZer/RD^BF -=*=- Eniac/Faith -=*=- Modem Boy/OTL -=*=- Virus/Arise -=*=-\n               -=*=- Shot -=*=- Gabry -=*=- Transparent & S-Pin -=*=-\n                 -=*=- RoboCop/OTL -=*=- Shadow Crime EX.CMX -=*=-\n\n                          Special Thanx Go Out To:\n           GOD.......................... 4 Saving The Amiga :) \n@endNode\n@Node Part6 "Contacts"\n-------------------------------------------------------------------\n        	      ____  ____ ____            \n		__/\_| __ )| __ ) ___| ___ __/\__\n		\    /  _ \|  _ \___ \/ __|\    /\n		/_  _\ |_) | |_) |__) \__ \/_  _\\n		  \/ |____/|____/____/|___/  \/ICE MC  \nBßbS /¥aMe             bBS NµmbErz         sysøpZ\n ------------------------------------------------------------------\n@{"PøiNt Of Nø ReTuRN" Link Part11}    +39-421-560951       HanTaREX \n\n /¥\etæL SHoppe        +1-519-255-7378      MetaL SoFtWære - Ice MC\n                       +1-519-256-0278\n\n StYgIAn AbYsS         +1-312-384-0616      \n		       +1-312-384-6250	\n@{"D¡G¡TaL UnDeRGrOunD" Link DU}  +39-Very-Søøn         BiTMasTeR\n@EndNode\n@Node Part7 "Wanna Join "\n\n                  /\             /\   ___\n                 // \           // \_|   |___   ___               __\n        _/\____  \  /  _/\_____ \  /         )_|.  |             /_/\\n        ).     \ /\/\  ).      \/\/\__   ___/  \|  !             \_\/\n        |: ___  \    \//  _____//   \|   |  _   \  | __\n _  /\__|¦ \ /   \    \   |   \      \   |  Y.   \ |/. \          /\\n  \/    |   Y    /    /   |    \     /   |__||    \ /   \__/\    /  \\n  __    |_____  /_  _/\_____   /_  _/|   |  |__  _/__  _/    \  /    \__ _\n /_/\         \/_ \/       \__/  \/   \ /      \/    \/       \/\n \_\/         /_/\             _/\_.   Y\n              \_\/    _/\____  )   ¦   :/\___  _______  _/\____\n                      ). _   \/.   !_  ). _  \/  ___  \/   _   \   /\\n    _  _ __    /\  __//  Y___//  _   \//  Y   \  \ /.  \_  Y___/__/  \  _ _\n           \  /  \/ /    |   )   Y.   \   _    \  Y/   / \_    )      \/\n            \/      \____  _/____||    \__Y     \___  /____  _/LrY    __\n                         \/      !__  _/  !__  _/   \/     \/        /_/\\n                                    \/       \/         