INSERT INTO door_catalog VALUES('dtpref20','DTPREF20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DTPREF20.LHA','DTpref','XIM','DTpref',NULL,NULL,NULL,'(__|| | |||  |l_/_|_      DTprefs V2.0 `''   l|`  `    l__,    ~~~~~~~~~~~~ - ---------------------------------------- -',replace(' __  _ _ . __  __\n(__|| | |||  |l_/_|_      DTprefs V2.0\n   `''   l|`  `    l__,    ~~~~~~~~~~~~\n- ---------------------------------------- -\n Short: Prefs-Editor for Datatypes with GUI\n   Type: util/wb   Org.Name: DTpref20.lha\n- ---------------------------------------- -\n','\n',char(10)),'DTpref.guide',replace('@database DTpref\n@$VER: DTpref.guide 2.0 (24.09.95)\n@(C) Swen K. Stullich/UFT\n@author Swen K. Stullich/UFT\n@WORDWRAP\n@index Index\n\n@node Main "DTpref 2.0"\n@prev Main\n@next Main\n\n                                  @{b}@{u}DTpref 2.0@{uu}@{ub}\n\n             @{b}DTpref@{ub} package is Copyright © 1995 @{"Swen K. Stullich/UFT" link Author}.\n                             All rights reserved.\n\n  The author''s native language is german, so please forgive bad spelling, grammar mistakes etc. Or better - correct them.\n\n  @{"Copyright notice" link Copyright}\n  @{"  Introduction  " link Introduction}\n  @{"  Requirements  " link Requirements}\n  @{"  Installation  " link Installation}\n  @{"  Configuration " link Configuration}\n  @{"     Thanks     " link Thanks}\n  @{"     History    " link History}\n  @{"      To do     " link ToDo}\n@endnode\n\n@node Copyright "DTpref Copyright"\n@prev Copyright\n\n @{b}@{u}Copyright@{uu}@{ub}\n\n  @{b}DTpref@{ub} package is Copyright © 1995 @{"Swen K. Stullich/UFT" link Author}.\n\n  @{b}DTpref@{ub} is mailware. All rigths are reserved.\n   It is allowed to put this programm\n    · into the AmiNet\n    · on the AmiNetCDs\n    · on the FredFishCDs\n    · into BBS\n   all other distribution requires written permission from me.\n\n  The @{b}DTpref@{ub} from the package works, but no guarantee is given nor implied. In no case will I be liable for any results of using @{b}DTpref@{ub}.\n\n  This documentation is based on @{i}FontDT.guide@{ui}, which is Copyright © 1995 Michael Letowski.\n\n  List of all files in the distribution:\n   @{i}\n   DTpref.readme\n   DTpref.readme.info\n   Install\n   Install.info\n   Libs.info                        \n   Libs (dir)\n     gtlayout.library                 \n   Docs.info\n   Docs (dir)\n     DTpref.guide\n     DTpref.guide.info\n   DTpref.info\n   DTpref (dir)\n     DTpref\n     DTpref.info\n@{ui}\n@endnode\n\n@node Introduction "Introduction to DTpref"\n\n @{b}@{u}Introduction@{uu}@{ub}\n\n  @{b}DTpref@{ub} is a preferences editor for @{"DataTypes" link DataTypes} with settable preferences.\n\n\n  The GUI has three signifcant areas:\n\n  @{b}Left side@{ub} is a listview-gadget, where you can select a @{"DataType" link DataTypes} for changing the preferences.\n\n  @{b}Right side@{ub} is the area to act on the datatype-preferences. All @{"DataTypes" link DataTypes} has common the @{i}IO-Gadgets@{ui} and the @{i}Information@{ui}-gadget. The other layout depends on the used @{"DataType" link DataTypes}.\n    @{i}IO-Gadgets@{ui} are:\n      @{b}Save@{ub} the preferences for this @{"DataType" link DataTypes} onto the disk.\n      @{b}Use@{ub} the preferences only. After a reset the old settings will be available and used.\n      @{b}Default@{ub} set the layout to the internal (@{"DataType" link DataTypes})settings.\n      @{b}Restore@{ub} the settings from "ENV:".\n      @{b}LSaved@{ub} loads the settings by the disk.\n    @{i}Information-gadget@{ui} gives some infos about the @{"DataType" link DataTypes} and his author.\n\n  @{b}The bottom@{ub} has the three gadgets:\n    @{i}Save@{ui} all @{"DataTypes" link DataTypes}-settings to disk, without checking, if they was changed.\n    @{i}Use@{ui} all @{"DataTypes" link DataTypes}-settings, withou checking, if they was changed.\n    @{i}Cancel@{ui} (or use the @{i}CloseWindow@{ui}) don''t save or use the new @{"DataTypes" link DataTypes}-settings.\n    These gadgets also quits the programm.\n\n\n  The menu gives you the abillity to:\n   · get information about the author and the programm: @{i}Project/Version/Copyright ...@{ui}\n   · to quit the programm @{i}Project/Quit@{ui}. This is identical to the @{i}Cancel@{ui}-button\n   · reset all @{"DataTypes" link DataTypes} to default @{i}Edit/Reset to Defaults@{ui}\n   · load the last saved settings for all @{"DataTypes" link DataTypes} @{i}Edit/Last Saved@{ui}\n   · or restore all the @{"DataTypes" link DataTypes}-settings @{i}Edit/Restore@{ui}\n@endnode\n\n@node Requirements "Requirements for DTpref"\n\n @{b}@{u}Requirements@{uu}@{ub}\n\n  @{b}DTpref@{ub} requires AmigaDOS 3.0 or higher\n  For the GUI @{b}DTpref@{ub} requires the @{i}gtlayout.library@{ui} V23+, by @{b}Olaf ''Olsen'' Barthel@{ub}.\n@endnode\n\n@node Installation "Installation of DTpref"\n\n @{b}@{u}Installation@{uu}@{ub}\n\n  Use supplied @{i}Installer @{ui}script to copy necessary files.\n@endnode\n\n@node Configuration "Configuring operation of DTpref"\n\n @{b}@{u}Configuration@{uu}@{ub}\n\n  You can configurate @{b}DTpref@{ub} with @{"ToolTypes" link ToolTypes}.\n\n@{fg highlight}DT@{fg text}\n  @{fg highlight}DT=@{fg text}@{i}DTname@{ui},@{i}Filename@{ui}\n  Where @{i}DTname@{ui} the name of the @{"DataType" link DataTypes} is, and @{i}Filename@{ui} the name of the file is, which will be used to load the @{"DataType" link DataTypes}.\n  The @{i}Filename@{ui} must be in the same directory, where @{b}DTpref@{ub} is, or the complete path must be given.\n  Before using this @{"ToolType" link ToolTypes} check out, if the @{"DataTypes" link DataTypes} supports this feature. At the moment only @{b}icon.datatype V39.4@{ub} supports this. Other @{"DataTypes" link DataTypes} may follow (like @{b}binary.datatype@{ub}).\n@endnode\n\n@node Thanks "DTpref Thanks"\n\n @{b}@{u}Thanks@{uu}@{ub}\n\n  Thanks must go to:\n\n   @{b}Olaf ''Olsen'' Barthel@{ub} for his great gui-library @{i}gtlayout.library@{ui}. Without this library this tool wouldn''t exists!!!\n\n   @{b}Stefan Ruppert@{ub} for the support of @{b}DTpref@{ub}\n\n   all the others, which send me an e-mail after releasing V1.0. Without you there wouldn''t probably no V2.0 of @{b}DTpref@{ub}\n@endnode\n\n@node History "DTpref History"\n\n @{b}@{u}History@{uu}@{ub}\n\n  Version 1.0 (22.06.95) - initial release.\n\n  Version 2.0 (27.09.95) - complete rewritten.\n\n   Improvements:\n    · GUI changed. Now you can save, load, ... the config of each datatype individually\n    · Now @{"DataTypes" link DataTypes} can use @{b}DTpref@{ub} with some new methods, so programmers of @{"DataTypes" link DataTypes} can support DTpref\n@endnode\n\n@node ToDo "To do in DTpref"\n@next ToDo\n\n @{b}@{u}To do@{uu}@{ub}\n\n  · Support more @{"DataTypes" link DataTypes}\n  · Show changes at the preferences of the @{"DataType" link DataTypes} in realtime\n  · Check if already running\n@endnode\n\n@node DataTypes "DataTypes Information"\n@prev DataTypes\n@next DataTypes\n\n @{b}@{u}DataTypes@{uu}@{ub}\n\n  @{i}DataTypes @{ui}is an AmigaDOS subsystem (introduced in AmigaDOS 3.0) for dealing with different types of files found on different machines (PC''s, Macs and Amigas). @{i}DataTypes @{ui}can be used for recognizing types of files and interpreting informations in this files. An example of the latter is @{i}MultiView@{ui}, which can show many types of data.\n\n  @{i}DataTypes @{ui}divide all files into the following main categories:\n   · @{i}syst @{ui}(System) - system files;\n   · @{i}text @{ui}(Text) - textual files;\n   · @{i}docu @{ui}(Document) - documents (spreadsheet data, text with pictures etc.);\n   · @{i}soun @{ui}(Sound) - sound samples;\n   · @{i}inst @{ui}(Instrument) - musical instruments;\n   · @{i}musi @{ui}(Music) - songs;\n   · @{i}pict @{ui}(Picture) - graphics;\n   · @{i}anim @{ui}(Animation) - animations;\n   · @{i}movi @{ui}(Movie) - animation with sound.\n   Each category is further divided into subclasses. Each subclass interprets one type of file, converting it to some universal format.\n@endnode\n\n@node ToolTypes "ToolTyes"\n@prev ToolTypes\n@next ToolTypes\n\n @{b}@{u}ToolTypes@{uu}@{ub}\n\n@endnode\n\n@node Author "About the Author"\n@prev Author\n@next Author\n\n @{b}@{u}About the Author@{uu}@{ub}\n\n  @{b}DTpref@{ub} package was written by @{b}Swen K. Stullich/UFT@{ub}\n\n  If you have something to say me (questions, remarks, suggestions, wishes, bug reports) please contact me (I like receiving mail!):\n\n  by E-Mail (preferred way):\n\n   @{b}[email removed]@{ub}\n\n  by normal mail:\n\n   @{b}Swen K. Stullich\n   Am Schölkegraben 14a\n   38826 Salzgitter\n\n   Germany@{ub}\n@endnode\n\n@node Index "DTpref Index"\n@prev Index\n@next Index\n\n  @{b}@{u}Index@{uu}@{ub}\n\n  @{"     Author     " link Author}\n  @{"  Configuration " link Configuration}\n  @{"Copyright notice" link Copyright}\n  @{"    DataTypes   " link DataTypes}\n  @{"    ToolTypes   " link ToolTypes}\n  @{"      Fonts     " link Fonts}\n  @{"     History    " link History}\n  @{"  Installation  " link Installation}\n  @{"  Introduction  " link Introduction}\n  @{"     Thanks     " link Thanks}\n  @{"  Requirements  " link Requirements}\n  @{"      To do     " link ToDo}\n@endnode\n','\n',char(10)),NULL,'auto-added',78872,0,0,NULL,NULL,'dtpref20','scan',1780048498);
INSERT INTO door_catalog VALUES('dtr_fs4','DTR-FS4.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DTR-FS4.LHA',NULL,'XIM','friendsonly.exe',NULL,'Mogue!','DTR','__(_ \\   _)_ ___(_  /____ /  |_ __ __(_  \ \  /  \  _/ /   /  . \\   /   _/ _)_\  /  /_ \ \   \____\   \___ _\   \___| _/  /__\___\',replace('   ___ ______     _____ .Mo! __.       ____\n __(_ \\   _)_ ___(_  /____ /  |_ __ __(_  \\n \  /  \  _/ /   /  . \\   /   _/ _)_\  /  /_\n  \ \   \____\   \___ _\   \___| _/  /__\___\\n  /_____/ «-(____/----(____/--\______\------.\n                                            |\n   .FAMEStyle v4.o - (c) Mogue!/Desaster.   |\n    - -------------------------------- -    |\n o Logos in ansi and ascii format for       |\n   conferences/bulletins/doors/transfer     |\n o Best FAMEStyle by Mogue! sofar & overall |\n «- ----------------------------------------''\n','\n',char(10)),'Quarkteilchen.readme',replace('\n\n\n                           !SPEEDHUNK OPTIMIZED!\n\n\n                       -> f R I E N D S   O N L Y <-\n\n                            ONE OF THE FASTEST \n\n\n                           !SPEEDHUNK OPTIMIZED!\n\n\n','\n',char(10)),NULL,'auto-added',4611,1,0,NULL,NULL,'dtr_fs4','scan',1780048498);
INSERT INTO door_catalog VALUES('dtr_t98b','DTR-T98B.LZX','~/Code/amiexpress_doors/Archives/AmiExpress/DTR-T98B.LZX',NULL,'XIM','rexxtricks.library',NULL,NULL,'DTR',NULL,NULL,NULL,NULL,NULL,'auto-added',44098,0,0,NULL,NULL,'dtr_t98b','scan',1780048498);
INSERT INTO door_catalog VALUES('dupec042','DUPEC042.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DUPEC042.LHA',NULL,'XIM','DupeCheck.x','0.42',NULL,NULL,NULL,replace('Duplicate_Check V0.42\n','\n',char(10)),'DupeCheck.doc',replace('                     -The /X Development Team in 1993-\n\n                                  present\n\n                         - Duplicate_Check V0.42 -\n\n              « XIM Sys.CMD Module for Ami-Express 2.2+/3.x »\n\nOriginal "Idea" by Nitro, Sysop of Pirate`s Haven! - Code by SiGMA SEVEN!\n\nOnce again i`m supporting you with a Tool everyone probably did Wait for.\n\nThe Purpose of this XIM Door/Module should be clear. It is checking if the\nUploaded File has already been online - Just like the Internal DupeCheck\nof AmiExpress V2.x (been removed by (to me) unknown Reasons), its just a \nbit faster (Thats what i`ve been told at least).\n\nSo you may ask yourself "How can a normal Door do this". The Answer is easy:\n\nIts done because AmiExpress Version 2.20+ got the ability to run a \nDoor/Module called ''FILECHECK'' right after a File has been uploaded and\nthe Description has been entered. I`m asking myself why no-one else did\nget that Idea, but who cares - I DID IT! :)\n\nInstallation:\n~~~~~~~~~~~~~\n\nThe Installation is as easy as it SHOULD be - no "dumb" Configuration Files\nor Configuration Programs etc. - simply put the required (and supplied!)\nIcon(3.x) or SYS.CMD Line (2.x) into the desired Directory/File.\nAfter you`ve done this you`re SET... Ready to go.\n\nVersions and ....:\n~~~~~~~~~~~~~~~~~~\nV0.0   - Nitro told me about his Problems with Duplicate Uploads.\nV0.1   - Started to do it. First Version - included in my FCHECK 0.92 (Private)\n         That Time in Arexx.\nV0.2   - A Little Arexx Speed Improvement.\nV0.25  - Stand Alone Version in Arexx.\nV0.3   - 1st Try to do it in Amiga_E -> Failed.\nV0.31  - Shell/CLI Version for Speed Testing.\nV0.32  - 2nd Try in Amiga_E -> failed (Anyone who can show me how to do DOORS\n         in AMiGA_E -> LEAVE MAIL! (urgent!))\nV0.35  - Talked to Big Boss/FLT about the Problem with AMiGA_E - and he gave\n         me the Idea to code it in "C".1st Tries with "C" (still damn Slow)\nV0.37  - A few Improvements - Designed a bit the Output.\nV0.40  - 1st Test Version given out to the Beta Testers.\nV0.41  - Nice Speed Improvement - suggested by Big Boss.\nV0.41ß - Added Some nice Output (i think) like which File he`s searching for\n         and so on.\nV0.42  - First Public Release Version. \n         -If it would be in Amiga_E it would be a Hell faster-\n\n\n\nBugs.\n~~~~~\nThe Module/Door has been tested for (just) about a Week and the Result:\n\n                         -» No REAL Bugs found. «-\n\nBUT if you discover any - Simply Leave me a Mail on the Ami-Express Support\nBBS''es (in the NET Area). You could leave it to: Sigma Seven! @ 305001\n						 Sigma Seven! @ GR0002\nIt SHOULD surely reach me. - To make sure it does - make it a Public Msg.\n\nOr simply drop me a Message on every ''EliTE'' BBS.\n\n----------------------------------------------------------------------------\nSpecial Regards MUST go to Big Boss, without whom i weren`t able to do this\nDoor, You know  its hard to code in "C" without any knowledge - THANKS!\n----------------------------------------------------------------------------\n\nIf you want, you can Vote for me for the next World Charts - (Lets see if i\ncan get any higher than before :))\n\n\nNow i would like to send out some Greetings. No Special Order - as usual.\n\nNitro, Pot-Noodle, Joseph Hodge, Hydro, /X\arvin, Thrash, Ice D, Nosferatu!,\nMetalliKat, Enforcer, Tcm & Joker, Fornax, Dave!/Abandon, RiP & Andeveron,\nIce Te/\, Winston, Cecil, Warduke, Micro, TWK, Paninaro, Slapshot, Mofo,\nKamenski, Neptun, Necronom, Drizzt, The Bird, Wintermute, SinJin, The Animal\nCypher, Reeet-Mon, Straylight and everyone else i cannot think of right now\n...You know who you are.\n\n\n              -» Some (other) Regards to my Beta Testers: «-\n\n                   -» Nitro      (Pirate`s Haven)    «-\n                   -» Black Rose (House of Pain)     «-\n                   -» Micro      (Reign in Blood)    «-\n                   -» The Legend (Road to Nowhere)   «-\n                   -» White IC   (Complex Corrosion) «-\n                   -» Fornax     (Europe`s Heart)    «-\n\nThats it for today. Make sure you do not miss my next "Production" Which\nshould be the Hacker Online Game - Converted to a XIM.\n\nOr Maybe a Nuke Door for 3.x Only (Conference_Accounting)\n\nLaters Dudes...SiGMA SEVEN! of Abandon AND Premiere.  \n\n                       -/X Development Team in 1993-\n\n','\n',char(10)),NULL,'auto-added',11626,1,0,NULL,NULL,'dupec042','scan',1780048498);
INSERT INTO door_catalog VALUES('dupec089','DUPEC089.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DUPEC089.LHA',NULL,'XIM','dupecheck.x','0.89',NULL,NULL,NULL,replace('DUPE CHECKER V0.89 FOR /X\n','\n',char(10)),'DupeCheck.doc',replace('                     -The /X Development Team in 1993-\n\n                                  present\n\n                         - Duplicate_Check V0.83 -\n\n              « XIM Sys.CMD Module for Ami-Express 2.2+/3.x »\n\n        ** Read the Docs! - Some quite Important Things changed. **\n\nOriginal "Idea" by Nitro, Sysop of Pirate`s Haven! - Code by SiGMA SEVEN!\n\nOnce again i`m supporting you with a Tool everyone probably did Wait for.\n\nThe Purpose of this XIM Door/Module should be clear. It is checking if the\nUploaded File has already been online - Just like the Internal DupeCheck\nof AmiExpress V2.x (been removed by (to me) unknown Reasons), its just a \nbit faster (Thats what i`ve been told at least). Now at "bit" MORE faster :)\n\nSo you may ask yourself "How can a normal Door do this". The Answer is easy:\n\nIts done because AmiExpress Version 2.20+ got the ability to run a \nDoor/Module called ''FILECHECK'' right after a File has been uploaded and\nthe Description has been entered. I`m asking myself why no-one else did\nget that Idea, but who cares - I DID IT! :)\n\nInstallation:\n~~~~~~~~~~~~~\n\nThe Installation is as easy as it SHOULD be - no "dumb" Configuration Files\nor Configuration Programs etc. - simply put the required (and supplied!)\nIcon(3.x) or SYS.CMD Line (2.x) into the desired Directory/File.\n\nAlso make sure you copy the (Supplied in the Archive) AEDoor.library to\nthe LIBS: Directory. - or if you already have it in there skip this Part.\nOtherwise it will not work.\n\nTo have a 2nd Filecheck Door you will have to install that one\nas a Door with the Name ''SERVER'' - Access Level can be upto 255.\nMUST be in the BBSCMD Drawer(/X3.0+) or in the BBS.CMD File (/X2.34+).\n\nTo have a Text displayed after an Upload you will have to create a File\ncalled "FILECHECK.TXT" (or with .GR) in either the BBS: or\nConference Directory. This Way you can have Different Texts shown\nfor different Conferences. (Maybe for a Top Uploader List or a "Thank You"\nAnsi/Text)\n\nAfter you`ve done this you`re SET... Ready to go.\n\nVersions and ....:\n~~~~~~~~~~~~~~~~~~\nV0.0   - Nitro told me about his Problems with Duplicate Uploads.\nV0.1   - Started to do it. First Version - included in my FCHECK 0.92 (Private)\n         That Time in Arexx.\nV0.2   - A Little Arexx Speed Improvement.\nV0.25  - Stand Alone Version in Arexx.\nV0.3   - 1st Try to do it in Amiga_E -> Failed.\nV0.31  - Shell/CLI Version for Speed Testing.\nV0.32  - 2nd Try in Amiga_E -> failed (Anyone who can show me how to do DOORS\n         in AMiGA_E -> LEAVE MAIL! (urgent!))\nV0.35  - Talked to Big Boss/FLT about the Problem with AMiGA_E - and he gave\n         me the Idea to code it in "C".1st Tries with "C" (still damn Slow)\nV0.37  - A few Improvements - Designed a bit the Output.\nV0.40  - 1st Test Version given out to the Beta Testers.\nV0.41  - Nice Speed Improvement - suggested by Big Boss.\nV0.41ß - Added Some nice Output (i think) like which File he`s searching for\n         and so on.\nV0.42  - First Public Release Version.\n         -If it would be in Amiga_E it would be a Hell faster-\n\n** Been Lazy - and waiting for the Library - Thank God Sintax Released it **\n\nV0.80  - Converted it from (kinda slow) ''C'' to (kinda fast) ''E''\n	 Included first possibility to have a Second FileCheck Door.\n	 (BossNuke''s calling ,you know.)\n	 Slight SpeedUp cause of using "E" (about 500% maybe more, maybe less)\n	 2nd Test Version given out to Beta Testers.\nV0.81  - Found a small Bug where it didnt pass the FILENAME to the 2nd\n	 FileCheck Door. - Fixed.\nV0.83  - Included possibility to have a File shown after an Upload.\n	 ("Copied" it from PC-Express :)) - Can be different for each\n	 Conference.\n	 Installed Checking for 2nd Filecheck door (otherwise it would always\n	 Display ''Unknown Command..etc'' which is a bit boring and\n	 "unprofessional")\nV0.84  - Fixed a bug with NonStop Flag - on a batch Upload it would display\n         This Pause Stuff.\nV0.85  - Fixed a Bug where it didnt search for the /X2.3x SERVER Door.\n       - Forgot to install a Check for the Door w/ /X2.x - Fixed!\nV0.86  - Some Cosmetical Changes.\nV0.87  - Wouldn`t let /X Check the File if there was no Text File to be\n         Displayed.\nV0.88  - There was something, just WHAT?.. Forgot hehe...\nV0.89  - Fixed a few stupid Bugs i did include for some Reasons.\n         aswell as some Cosmetical Changes.\n\n\nIf you discover any more - Simply Leave me a Mail on the Ami-Express Support\nBBS''es (in the NET Area).\n\n You could leave it to: Sigma Seven! @ GR0002 (my BBS)\n\nIt SHOULD surely reach me. - To make sure it does - make it a Public Msg.\n\nOr simply drop me a Message on every ''EliTE'' BBS.\n\nIf you want, you can Vote for me for the next World Charts - (Lets see if i\ncan get any higher than before :))\n\n\nNow i would like to send out some Greetings. No Special Order - as usual.\n\nNitro, Pot-Noodle, Joseph Hodge, Hydro, /X\arvin, Thrash, Ice D, Nosferatu!,\nMetalliKat, Enforcer, Tcm & Joker, Fornax, Dave!/Abandon, RiP & Andeveron,\nIce Te/\, Winston, Cecil, Warduke, Micro, TWK, Paninaro, Slapshot, Mofo,\nKamenski, Neptun, Necronom, Drizzt, The Bird, Wintermute, SinJin, The Animal\nCypher, Reeet-Mon, Straylight and everyone else i cannot think of right now\n...You know who you are.\n\nThats it for today. Make sure you do not miss my next "Production" Which\nshould be the Hacker Online Game - Converted to a XIM. (Still not done.)\n\nSeems like i`m busy with a few other Things... Just need to get into the\nright Mood to do the Stuff.\n\nLaters Dudes...SiGMA SEVEN! of Abandon AND Premiere.  \n\n                       -/X Development Team in 1993-\n','\n',char(10)),NULL,'auto-added',7687,1,0,NULL,NULL,'dupec089','scan',1780048498);
INSERT INTO door_catalog VALUES('dupe_1','DUPE_1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DUPE_1.LHA','globaldupe','XIM','globaldupe',NULL,'Splash','DUPE','_\_/    / _  __  ______ _______/__  ___    / | _ \  /     /  __/__/   /_ _   /   ___   / |__\ \/ /___/_____________/____/____//___/',replace(' ___     _______________________ _ _________\n_\_/    / _  __  ______ _______/__  ___    /\n| _ \  /     /  __/__/   /_ _   /   ___   /\n|__\ \/ /___/_____________/____/____//___/\n    \  /                   .------------.\n     \/ GlobalDupe 1.4 «-- ÷-  styLE!   ¡\n                 By Splash `------------÷\n Fast Dupechecker that will check all   |\n confs. New and gr8 dezign              |\n -[25.06.95]------ ---- ---------·st!·--''\n [World release at FlAMe StRiKe MGS! WHQ]\n','\n',char(10)),'GlobalDupe.Guide',replace('@database "GlobalDupe.Guide"\n@WIDTH 77\n@NODE Main "MAIN" "Welcome to GlobalDupe Documentation"\n\n .--------------------  ---(c)-[ mEGAStYLE! pRODUCtiON ''95\n |    ____     _______________________________  _ _____________ _\n ! ___\ _/    / _  ___  __________  _________/_ __   ____       /\n . |    _ \  /      /  ___/_____/    /__ _      /    _//_      / -----.\n ¦ |st!  \ \/ /    /    /      /       /       /     _____    /   -- -÷ -»\n | |______\  /_______________________________________//______/ -------''\n |         \/           \n |\n-÷- -» _____________ ______          _____     _ ______      _ _______ ____\n |  ___\   ________/_     /_       _/    /___         /    _ __  _________/\n |  |__________     /    __/______/     /    \ /     /_______/  ___/_______\n |  |      |       /    /        /     /      \     /       /    /        /\n |  |______________________________________    \_________________________/\n .                              _  _ _____¬_____/\n |\n |\n `--------------------------------------------------- ------------ -[   -»\n\n\n\n\n\n  \n                           GlobalDupe 1.4 (25/06-95)\n     \n                          By Splash/ElTECH & Megastyle\n                                         \n                          @{"What is GlobalDupe ?      " LINK "ABOUT"}   \n                          @{"What is new ?             " LINK "NEW"}\n                          @{"Requirements.             " LINK "REQ"}                \n                          @{"Installation.             " LINK "INSTA"}              \n                          @{"Credits                   " LINK "CREDS"}\n                          @{"Greetings.                " LINK "GREET"}                 \n                          @{"About Megastyle.          " LINK "MEGASTYLE"}\n                          @{"How to contact the Author " LINK "HOWTOCONTACT"}\n              \n@ENDNODE\n\n\n\n\n\n\n\n\n\n\n@NODE "ABOUT" "What is GlobalDupe ?"\n\nGlobalDupe is a duplicate checker that will check if the file uploaded exists\nany other places on your board allready.\n\nIf you have got a board with many confs you have probably been pissed off many \ntimes because of files beeing uploaded in different conferences. This nice \ndupechecker fixes this problem. It will check in all your conferences if a file \nexists. If it does exists the file will be deleted and the desc is moved to the \nHOLD directory and the user will not be rewarded with any bytes for his upload.\n  \n@ENDNODE\n\n@NODE "REQ" "Requirements."\n\n\nA Commodore Amiga computer (Pese suxx :-) running on kick 2.0+, /X \n(I guess any version will do...) \n\nThis door uses the AEDoor.libary, so you should have this in LIBS:\n(If you haven''t got it then call me or your local /X board to get it...) \n@ENDNODE\n\n\n@NODE "INSTA" "Installation."\n\n\n                             \nJust copy the included files to the correct dirs, that''s it.... \n\n@ENDNODE\n\n@NODE "HOWTOCONTACT" "How to contact the Author"\n\nHow to contact me:\n\n@{"Flame Strike" LINK "FLAME"} :+47 51631702\n\nOr snailmail: Splash/ElTECH & Megastyle\n              Lindeveien 69\n              N-4300 Sandnes\n              Norway\n@ENDNODE\n\n@NODE "CREDS" "Credits."\n\nCode,Idea    - Splash/ElTECH & Megastyle\nDoor Design  - Magz/Grotesticle\nGuide Design - Splash/ElTECH & Megastyle\n\n@ENDNODE\n@NODE "GREET" "Greetings."\n\n\n                                  \n\n                         Greetings to all my friends ! \n\n                      Special greetings to all /X coders \n\nAND OFCOURSE ALL MEMBERS OF :\n______ ______________ ______ ________    _________/ _|_____/\______ _ __________\n ____ V _________   // ____/_______  \  _\  ______   _  __/  \  __/_________   /\n |   \_/   |   _/  //  \__   |   _/   \/  \___   \   |___     \ \      /  _/  /\n |    |    |  ____/_     |   |   _     /    _/   /   |   \    /  \_   /  ____/_\n |____|    |_______/_________:___\    /_________/____|_______/_______/________/\n      |____|                      \  /                       \n      :    :                       \/\n\n                                   AnD\n\n             _______ /|   _______/\_______________    _____ \n            /~ ____// | __\___  ~__~/  _____/~   ~\  /~ ¡ ~\.  \n           //  __)_// |/ ~\  /  :| //  __) //   .__)//  |  \\\\n           \\     ~\\ ~   \\/   || \\     ~\\   : \\\\      / \  \n            \  ____/\______/\____|  \  ____/\____ // \. |__/  /\n             \/ .____/\______/\_____|\/ .TeTSUo__\/ / \/ ____/\n              \/                      \/          \/   \/ \n\n\n\nPersonal greetings:\n~~~~~~~~~~~~~~~~~~~\nLizard/MGS!      - We ARE growing BIG now!\nWoober/MGS!      - Hi!\nJedi/MGS!        - Get those new nodes SOON!!! :-)\nNightProwler/HLM - Nice talkin'' to yah! Hope you like this door!\nMiC flAiR/ElT    - We need more releases from ElT.....\nLithium/ElT      - Hope we get the chance to talk more..\nMagz/GrT         - Great dezign.. Nice colly... greet me in the next one!\n\nSo I 4got YOU? Oki... go ahead shoot me.... I''m guilty...\n\n@ENDNODE\n\n@NODE "FLAME" "Flame Strike"\n           .    .         .         .        .\n   _______/|___/|________/|____ ___/|_______/|\n _/        l_   |    _    l_   |    l_       l_.........................\n/¬     _____j   |    ¬     l   !     l    ____j                        :\nY         |    _|__  .     | \ : /   |  _____j_     ·fLAME^sTRIKE·     :\n|     ____j   /    l :     |  \ /    |        l                        :\n|        |  _/     | :     |   :     |        |ElTECH EHQ·Megastyle WHQ:\n|        |         | !     |   !     |        |                        :\n|       ||        || |     |   |     |       ||                        :\nl________j_________j_|     |___|     |________jHOt WAREZ·CODERS CORNER·.\n :                   l_____j   l_____j [nUMEN] CHAtABlE SYSOP·YouNameIt.\n :  cREW:                    .         .      .     .         .        .\n :Splash/ElTECH^MGS!  ______/|________/|_____/|____/|____ ___/|_______/|\n :UnmaD/eXCALIBUR   _/  _____j_        l_   _ l_    l_   |    l_       l_  \n :MiC FlAiR/ElTECH /_____     l         l   ¬  l     l   !     j    ____j\n :    [YOU?]       Y     \    |    _____j    __j_    |   :  __/   _____j_\n :                 |      \   |      |    .     |    |   .    \         l\n :BIG /X conf with |       \  |      |    :     |    |   :     |        |\n :  400++ files!   |          |      |    !     |    |   !     |        |\n :.[+47·51631702]  |         ||     ||    |     |   ||   |     |       ||\n.:::....... .... ..l__________j______j____|     |____j___|     |________j\n :                                      : l_____j /X 4.9 l_____j :\n .                                      :........................:\n .\n@ENDNODE\n\n@NODE "MEGASTYLE" "About Megastyle"\n\n                                                               @{" Go back.. " Link MAIN}\n\nMegastyle is a new AmiExpress-Support group formed by Lizard of Spaceballs in\nthe middle of may 1995.\n\nOur main goal is to support all the /X-boards out there with the best doors\naround. We try hard to make our products as system-friendly as possible and\nwith unique configuration possibilities.\n\n\nWe want to be the leading /X-development group in the future, and therefore\nneed more skilled coders and ANSI-artist to make our products even better!\n\nIf you''re interesting in teaming up, then take a look at the contact-info.\n\n\n\n   _________ \n    _______ )  ·M·e·g·a·S·t·y·l·e·  ·P·r·o·d·u·c·t·i·o·n·s·\n           )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\nEven if we are a pretty new group we have released a couple of doors allready.\n\nSplash:\nAutoreward v1.3\nGlobalDupe v1.4\nSysDL      v3.1\n\nLizard:\nBulls      v1.0\nNodeStatus v1.2\n\nAll these doors are just GREAT so check''em out! And more releases to come in near \nfuture!\n\n\n   _________ \n    _______ )  ·M·e·g·a·S·t·y·l·e·  ·B·o·a·r·d·s·\n           )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           +47-51-631702 -=- @{"FlameStrike" Link "FLAME"} ·oOo· Sysop : Splash\n           +47-51-417240 -=- @{"Noiseless  " Link "NOISELESS"} ·oOo· Sysop : Lizard (NightBBS)\n           +47-77-748689 -=- @{"Eternity   " Link "ETERNITY"} ·oOo· Sysop : Woober\n           +47-51-575227 -=- @{"Total Panic" Link "TOTALPANIC"} ·oOo· Sysop : Jedi\n\n@ENDNODE\n@NODE "NOISELESS" "Propaganda : Noiseless BBS!"\n                                                               @{" Go back.. " Link "MEGASTYLE"}\n\n                                        .\n                                           ·\n   _  _  _ _______  _____ __ _____ _____:  :   _____  _____  _____ __ _  _   _\n_   _  _ ______   ||     (__)     |   __|  |  |   __||  ___||  ____ __ _ _  _\n            |  |  ||  |  |  l  `--|  _/_|  |__|  _/_ l  ''--.l  ''--.\n            |  |  ||  |  |  |--,  |  l  |  l  |  l  ||--,  ||--,  |\n            l__|  l|_____l__l__   l__   l__   l__   |l__   ll__   l\n               `--''            `--''  `--''  `--''  `--''   `--''   `--''\n\n                           SysOp : Lizard/Spaceballs\n\n      Phone : +47-51417240, only available between : 23:00PM -> 07:00AM.\n\n@ENDNODE\n@NODE "ETERNITY" "Propaganda : Eternity BBS!"\n                                                               @{" Go back.. " Link "MEGASTYLE"}\n\n                                                               ._____.\n  _____________________________________________________________:__ ._|__\n  \__ _____/___   _   / _____/______  \_   .  _/______ /     _   / |   /\n   /  ___/   /     \_/ ___/    /  _/  _/   |    \    \/¬\     \_/    _/\n  /_________/_______\_________/___\     \__|     \_______\_____\_____|\n                               -cDr\_____\ l______\\n.                                                                       .\n+-÷aMiGA ^ aSCiI ^ mODUlES ^ hACKErS lAnD ^ /X sUPpORT ^ pUBLiC dOMAiN÷-+\n:           [f]EATURING: A1200/020 ^ oNE (n)oDE (14k4 mAXLiTE)          :\n|          [m]ANAGEMENT: [w@@ßE®^tHg^nEo^mGs^bDz]-[SiENCE^tHg]          |\n!   tECHNOLOGY [nHq] · nEO [nHq] · mEGASTYLE [hQ] · bANANa dEZIGn [hQ]  !\n+÷---------------------------------------------------------------------÷+\n:                   [n]UMBER: +47-777-48689 [23 - 07]                   :\n`÷---------------------------------------------------------------------÷''\n\n@ENDNODE\n@NODE "TOTALPANIC" "Propaganda : Total Panic BBS!"\n                                                               @{" Go back.. " Link "MEGASTYLE"}\n\n «*»  Total Panic - 28.8kb v.all - Sysop : Jedi - Number : +47-51-575227  «*»\n\n@ENDNODE\n@NODE "NEW" "What is new in this version of GlobalDupe?"\n\nNot much :-)\n\nJust improved the layout, and included a great dezign by Magz/Grotesticle\n\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',11883,4,0,NULL,NULL,'dupe_1','scan',1780048498);
INSERT INTO door_catalog VALUES('dv_phan','DV-PHAN.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DV-PHAN.LHA','PhukAnsi','XIM','PhukAnsi',NULL,'Aryan/Dive','DV','/_____  \____/   /   /_______ /   /  /   /   /   /   ____/ .--+*#[(/______/   /_______/    ___/)]#*+--.',replace('         /\_____      /\______\n        /_____  \____/   /   /_______\n         /   /  /   /   /   /   ____/\n.--+*#[(/______/   /_______/    ___/)]#*+--.\n|:::::::::::::/___/:::::::/_______/dNO:::::|\n+---------------[ presents ]---------------+\n| What     : Ami Express Door              |\n| Door Name: Phuk Ansi                     |\n| Coder    : Aryan/Dive                    |\n| Language : Amiga E                       |\n`-------------------------------[96/02/18]-''\n','\n',char(10)),'PhukAnsi.Doc',replace('\n               ========[ DIVE IS BACK WITH ANOTHER ]========\n\n                                gm.\n                              _Z` VN_\n                            gZ~ mms ~Ns\n[==========================d! ,@@@@@s ''M.==================================]\n                         _A!,d@@@@@@@@s.VN_                  __.\n                        Wf ,@@@@@@@@@@A` 4K                ,Z~~Vs\n                      _Z`,g@@@@@@@@@A!  _.''*_           ,g*f,gm_''*s.\n                    ,g*`_W@@@@@@@@@A ,_g@@s.VN_        _*`,_@@@@s.''*_\n                   ,Z~ g@@@@@@@@@@KmW@@@@@@@. VW     gZ~,m@@@@@@@@m.~Ns\n                  gA ,W@@@@@@@@@M@@@@@@@@@@@@W_ *s._*`,g@@@@@@@@@@@* _A!\n                iW~ m@@@@@@@@@@f ~M@@@@@@@@@@@@m ~*~,m@@@@@@@@@@@f`,Z~\n               gf`,m@@@@@@@@@A` ms ~@@@@@@@@@@@@Ws g@@@@@@@@@@@f`,mf\n             ,Wf g@@@@@@@@@@f _Z`VN_''*@@@@@@@@@@@@@@@@@@@@@@*f _Zf\n            mP` W@@@@@@@@@A~,mf`   ~m.''V@@@@@@@@@@@@@@@@@@f`_gZ~\n           m~ iW@@@@@@@@@f`,Z~      ''Vm.~M@@@@@@@@@@@@@@f`,m~~\n         gA`,W@@@@@@@@@@` gA           Yi ''@@@@@@@@@@@@@. *b\n        Wf ,@@@@@@@@@@P`iW~          ,mf gW@@@@@@@@@@@@@@m.''Ns\n      ,@  d@@@@@@@@@A` gf           Wf ,@@@