INSERT INTO door_catalog VALUES('dvd_o105','DVD!O105.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DVD!O105.LHA','Ordering','XIM','Ordering',NULL,NULL,'DVD','_____________|  _ /_____________ \____.\___   |  //__ ___.\  ___/ .:: |  | \\  |    ./   |  | \\  /\  ::.',replace('                 _____\n   _____________|  _ /_____________\n   \____.\___   |  //__ ___.\  ___/\n.:: |  | \\  |    ./   |  | \\  /\  ::.\n::  |_____/__|\___/ ___|_____/____\ic::\n::            .presents.             ::\n::       >> ORDERING V1.05 <<        ::\n::                                   ::\n::      Powerful Directory-tool.     ::\n::      Many options included...     ::\n::        >> WORTH A LOOK <<         ::\n`:::::::::::::::::::::::::::::::::::::''\n \n \n \n \n \n \n \n \n \n \n \n \n              _  _ __ ______________________\n   ________ _________ ________ ________    /____\n  \\__    /_\_______¬\______ ¬\_/    /    /    /     ·tRELLi·\n    /   ___/_/    /___/  \_____/    /    /    /     ·iKOjENiA·\n   /    /   /    /   /    /   /    /    /    /  \n  /____    /____/__ /____    /    /____/____/   \n ____/____/____/___ _  /____/____/    /                ·\n|   _____/    / ________       /\ ________ ________ __/__________ __\n|  /    / ___/¬\__   _ ¬\_____/  \______ ¬\______ ¬\_/   _______¬\_ |\n| /    /  \_  __/    /   /   /    /  \_____/    /   /    /   __/  //|\n|/    /    /  \/    /   /   /    /    /   /    /   /    /    /   /  |\n/____/____/   /____    /____    /____    /____/   /____/____    /   |\n|   /   /____/   /____/   /____/   /____/   /____/    /   /____/kRm |\n|___________________________________________________________________|\n\n                   DVD!O105.LHA 199178 bYTES   wAS                    \n                       d·O·W·N·L·O·A·D·E·D fROM                       \n\nDeeJayMix              -[ 4-WarD ]-              02 Oct 1995 18:29:30\n','\n',char(10)),'Ordering_English.guide',replace('@database Ordering.guide\n@remark $VER: Ordering.guide 1.05 (14.09.95)\n\n\n@node "main" "Ordering documentation"\n\n                              @{b}Ordering v. 1.05\n                             ==================@{ub}\n\n                              by Julien TORRES\n\n                                  14.09.95\n\n\n\n    @{" Important          " LINK Important}\n    @{" Introduction       " LINK Introduction}\n    @{" Installation       " LINK Installation}\n    @{" Main program       " LINK MainProgram}\n    @{" Preferences editor " LINK PreferencesEditor}\n    @{" Author''s address   " LINK Address}\n    @{" Acknowledgements   " LINK Acknowledgements}\n    @{" History            " LINK History}\n@endnode\n\n\n\n@node "Important" "Important"\n\nImportant\n=========\n\n      Ordering can be freely  distributed  as long as the  following condi-\n  tions are respected :\n\n      - all the files of this archive must be supplied\n      - none of the files may be changed in any way other than archiving or\n        crunching\n      - no more than a reasonable fee can be charged to cover copying costs\n\n      No commercial  usage  of  Ordering  is  allowed  without  my  written\n  permission. This program can be included in all public domain collections\n  and  magazines may  distribute it on  their  coverdisks.  Ordering can be\n  downloaded from BBS and FTP sites.\n\n\n  @{u}Warning :@{uu}\n\n      Ordering has been tested many times.  But there is no  warranty.  You\n  use it at your own risk. I can not be made responsible for any damages or\n  loss of data  that may  result  directly or  indirectly from  the  use of\n  Ordering.\n\n@endnode\n\n\n\n@node "Introduction" "Introduction"\n\nIntroduction\n============\n\n      Ordering is a tool designed to manage  easily disks and  files.  Most\n  important features are :\n\n      - configurable with its external @{"preferences editor" LINK PreferencesEditor}\n      - neat interface\n      - completely written in assembler\n      - fast (compare...)\n      - localized\n      - recognize lots of filetypes by using whatis.library (flexible)\n      - main program''s size below 100 Kb\n      - few memory used\n\n      Ordering needs KickStart 2.04 to  work.  It may use diskfont.library,\n  icon.library, locale.library,  amigaguide.library,  whatis.library,  req-\n  tools.library  and  powerpacker.library if  they are  present.  Both last\n  libraries are Copyright © Nico François.\n\n@endnode\n\n\n@node "Installation" "Installation"\n\nInstallation\n============\n\n      You only have to double-click the  "Install" icon in your  Workbench.\n   Then follow the instructions. If you  don''t like to  use Installer, here\n   is the installation process :\n\n      - Copy the files "Ordering" and "OrderingPrefs" (with their icons) to\n        the directory of your choice.\n      - Copy reqtools.library, powerpacker.library, whatis.library to Libs:\n        and FileTypes to S:.\n      - Ordering.guide must be copied to the HELP: assign,  else the online\n        help will not work.\n\n      If you load Ordering from WorkBench,  you may specify the preferences\n  file to use with the PREFSFILE tooltype.  This is also possible from Cli,\n  using the PREFSFILE argument.  If no file is specified, Ordering tries to\n  load "ENVARC:Ordering.prefs". The @{"preferences editor" LINK PreferencesEditor} works the same.\n\n@endnode\n\n\n\n@node "MainProgram" "Main program"\n\nMain program\n============\n\n      On the main program''s screen,  you can see two large  windows,  where\n  the directories contents is displayed.  You can choose these directories,\n  either by  typing  their paths in  the  boxes (above the windows),  or by\n  clicking  one of the  buttons  located  on the  left-upper  corner of the\n  screen.  Each button contains one path.  On the right of these buttons, a\n  slider allow to  scroll the  list.  The  contents of the  buttons  may be\n  edited with the @{"preferences editor" LINK PreferencesEditor} (@{"Paths" LINK Paths} option).\n\n      To select a  directory window,  press the left  mousebutton  when the\n  pointer is over it. The selection mode may be changed with  OrderingPrefs\n  (@{"Screen" LINK Screen} option, page 2, window selection).  The  selected  window is the\n  source directory, and the other one the destination directory.\n\n      Then you can do many  things on the  selected  files and directories.\n  That''s why there are two  banks of buttons.  The second bank can be  made\n  visible just by  clicking  the  little  vertical bar (on the right of the\n  buttons). Of course, each button may be configured (@{"Buttons" LINK Buttons} option).  It\n  is possible to associate two actions with one button, the one called with\n  the left mousebutton,  and the other with the right mousebutton. At last,\n  the buttons may be above (default) or below the directories windows  (see\n  @{"Screen" LINK Screen}).\n\n      Moreover, you have menus, configurable as well (@{"Menus" LINK Menus} option).  They\n  usually are used to place  options that do not  directly act on  files or\n  directories (for example : formatting a disk).\n\n      Finally, a status bar allow Ordering to indicates what it is doing.\n\n\n@endnode\n\n\n\n@node "PreferencesEditor" "Preferences editor"\n\nPreferences editor\n==================\n\n      With the preferences editor, you may configure :\n\n                  @{"The buttons                 " LINK Buttons}\n                  @{"The paths                   " LINK Paths}\n                  @{"The menus                   " LINK Menus}\n                  @{"The actions for each filtype" LINK FileTypes}\n                  @{"The screen''s options        " LINK Screen}\n                  @{"The general options         " LINK Options}\n\n      When your configuration is  completed, you  can save it (the filename\n  is  displayed at the  bottom of the  screen).  But you  may load  another\n  configuration file,  or come back to  the  default  configuration  ("New"\n  option).\n\n@endnode\n\n\n\n@node "Buttons" "Buttons edition"\n\nButtons edition\n===============\n\n      Both banks are set the one above the other.  By clicking  one button,\n  its configuration is displayed. Then you may edit its name, its @{"function" LINK Functions}\n  and its options, its colours.  It is also  possible to add it a  shortcut\n  key. Of course you can do that for each mousebutton.\n\n      Once come back to the two banks,  you may swap buttons, copy one upon\n  others, or clear several of them.\n\n@endnode\n\n\n@node "Paths" "Paths edition"\n\nPaths edition\n=============\n\n      If you have not yet  created a configuration file,  the @{"main program" LINK MainProgram}\n  displays the list of the present devices (DF0:, RAM:, etc.). However, you\n  may personalize this list and preset the paths that you wish (for example\n  DH0:, DH0:c, DH0:libs, etc.).  Click the "Add a path"  button.  Then type\n  the path that you  wish.  Next click the "Path" button : the entered path\n  is displayed in the "Name" box.  In fact "Path" is  the directory read by\n  the program, whereas "Name" is the text displayed in the buttons (so make\n  sure that it is not too long, else it will be truncated).\n\n      Now  create a list of paths.  You  can notice  that  paths are always\n  added at the end of the list.  You may move them with "Move up" and "Move\n  down" options.\n\n      You also certainly have  noticed the  little  "Always read directory"\n  gadget at the bottom of the  screen.  If you  activate this  option for a\n  path,  it will always be read  each time you click its button in the main\n  program.  Else it will be  searched in the buffer list and redisplayed if\n  necessary.  This is very useful for directories  of which the contents is\n  often modified by other programs, because if the directory is searched in\n  the buffer list,  the contents may not be updated.  Therefore reading the\n  directory again will update it. On the other hand it will take more time.\n  Furthermore,  the "Rereading of all paths" button  allow to  enable  this\n  option  for all the  paths,  and the  "No rereading of the paths"  button\n  allow to disable it for each path.\n\n@endnode\n\n\n@node "Menus" "Menus edition"\n\nMenus edition\n=============\n\n      By default,  there  are  two menus ("Project" and "Disk"),  each  one\n  containing four items.  Of course, it is possible to  modify them.  First\n  click the "Menus" button in the preferences editor. So you can select the\n  menu to edit with  "Previous menu"  and  "Next menu".  You may also add a\n  menu (always at the end of the  list) using the option "Add menu".  It is\n  possible to delete the current menu with "Delete menu".\n\n      When you have selected the menu, you may add some items ("Add item").\n  Another window is opened,  and the item''s name, its shortcut key, and its\n  @{"function" LINK Functions} may be chosen.  You can also edit an item,  just by clicking it\n  in the  list.  Furthermore,  it is  possible  to  swap  two  items ("Swap\n  items"),  to copy an item upon other  items ("Copy item"),  and to delete\n  several items ("Delete items").\n\n@endnode\n\n\n@node "FileTypes" "Filetypes"\n\nFiletypes\n=========\n\n      You may associate two actions with a filetype, the one for a click on\n  the left mousebutton,  and the  other one for a click on the right mouse-\n  button. Two modes are available to try to find the type :\n\n      - WhatIs mode : whatis.library  is  used  (if it is  present  in your\n        LIBS: directory). This search is done in the first place.\n\n      - Internal mode : this analysis is  directly done by  Ordering if the\n        WhatIs mode failed, or if no action has been associated to the type\n        returned by whatis.library.  Several  actions are  defined for some\n        filetypes.  It is not possible to modify them, but you may edit the\n        options of certain actions.\n\n      Click the filetype with which you want to  associate an action.  Then\n  choose the  mousebutton,  and select the  wished  action.  The  following\n  actions are available :\n\n      @{"External tool    " LINK ExternalTool}\n      @{"Show icon        " LINK ShowIcon}\n      @{"Show ILBM picture" LINK ShowPic}\n      @{"Play sound       " LINK PlaySound}\n      @{"Show font        " LINK ShowFont}\n      @{"Read             " LINK Read}\n      @{"Hexadecimal read " LINK HexRead}\n      @{"Run              " LINK Run}\n      @{"Get version      " LINK GetVersion}\n\n      You may also delete actions : click the "Delete" button,  and  select\n  the filetypes  of which you want to  delete the associated actions.  When\n  this is completed, click the "Delete" button once again.\n\n      Moreover,  it is possible to add new  filetypes (recognized in WhatIs\n  mode),  just by  editing the S:FileTypes  file with your  favourite  text\n  editor.\n\n      Whatis.library uses subtypes ("SUBTYPE") : for example, an AmigaGuide\n  document is a subtype of text. Therefore, if you associate an action with\n  the filetype "Text", the action will be applied to the  AmigaGuide  docu-\n  ments as well,  except if you associate  another action with the filetype\n  "Guide".\n\n@endnode\n\n\n@node "Screen" "Screen configuration"\n\nScreen configuration\n====================\n\n  - Page 1 :\n\n      - Display mode : allow to  change the main  program screen  depth and\n        resolution. The minimal size is 640*200. The number of colours must\n        be between 4 and 256.\n\n      - Fonts : you may use several fonts for : screen (and menus), buttons\n        (non proportional),  directories  windows (non proportional),  path\n        names, disk names, status bar,  text viewer (non proportional), and\n        requesters and windows (non proportional, 8 pixels high).\n\n      - Buttons position : buttons may be located above,  below, or between\n        directories windows.\n\n      - Edit colours... : to edit the palette.\n\n      - Use Workbench colours : to copy the Workbench colours\n\n  - Page 2 :\n\n      - Sliders : the vertical sliders may be located on the left or on the\n        right of their windows.  You can also  adjust the  vertical sliders\n        width and the horizontal sliders height.  Vertical sliders may have\n        arrows. Moreover, sliders may be rendered with the new look.\n\n      - Window selection : by default, destination window is inward. But if\n        you prefer,  source window can be inward,  or the  disk name of the\n        source may be coloured.\n\n@endnode\n\n\n@node "Options" "General options"\n\nGeneral options\n===============\n\n  - Page 1 :\n\n      - Directories reading : you have three  possibilities and two options\n        to manage buttons to read directories :\n            - Don''t use right mousebutton : menus  will be  available.  But\n              you will have use the slider to scroll the buttons list.\n            - Use right mousebutton to scroll down drives  buttons : if you\n              press the  right  mousebutton when  the  pointer is  over the\n              buttons,  the list will be scrolled down.  Of course,  slider\n              may be use as well.\n            - Use mousebuttons  to  select the  directory  window : if  you\n              press left mousebutton,  directory will be  displayed  in the\n              left window.  If you press the right  mousebutton, it will be\n              displayed in the right window.\n\n        And the two options are :\n           - Separate drives buttons : if you  click the  left  side of the\n             button, directory will be displayed in the left window. If you\n             click the right side of the  button,  it will be  displayed in\n             the right window.\n           - Always search for an empty directory window : if active,  this\n             option has  priority  over all  the other ways to  choose  the\n             window.\n\n      - General :\n           - Memory monitor : available memory is displayed in the screen''s\n             title bar.\n           - Use ExAll() : ExAll() is a  DOS  function  to  read  quickly a\n             directory.  ExAll() would be a very good function if it wasn''t\n             bugged.  Under OS 3.0, with a DC-FFS disk, the first char of a\n             comment is truncated.  I don''t know what exactly happens under\n             OS 2.x.  I think there are problems with comments as well.  If\n             this option  isn''t  active  Ordering  uses  other  functions a\n             little bit slower,  but  which works fine...  So try  with and\n             without this option. I think that with a good hard disk, there\n             are few differences.\n           - Menus available when mouse is over  the buttons : you  can use\n             menus even if the pointer is over the  buttons.  On the  other\n             hand, clicking a button with the right mousebutton will not be\n             possible.\n           - Output window : you may define the  output window  parameters.\n             Output window is used by @{"Run" LINK Run} and @{"External tool" LINK ExternalTool}.  If you want\n             the window to be  opened on Ordering''s screen,  you should add\n             the SCREEN%s  option  into  the  parameter list.  "%s" will be\n             replaced by the Ordering public screen name (that may changes,\n             see @{"About" LINK About}). Of course it is possible to use a file instead of\n             a window.\n           - Printer : you may  define  the  device  used by the @{"Print" LINK Print} and\n             @{"Print directory" LINK PrintDir}  functions.  It is  usually PRT:.  But it may\n             also be a file or a window.  In that case, the SCREEN%s option\n             works as well.\n\n\n  - Page 2 :\n\n      - Directories windows : entries are sorted alphabetically. But direc-\n        tories can be above or below files, or they can be mixed.\n\n        You also have three options :\n            - Use right mousebutton to scroll list : if active, this option\n              allow to scroll the list  without using sliders.  Press right\n              mousebutton when the  pointer is over the source window,  and\n              move the mouse up or down.\n            - Use double-click : if this option is not active,  files can''t\n              be recognized.\n            - Memorize selected entries in buffers : if you select a buffer\n              entries remains selected as they were  when the directory has\n              been memorized. Else selection will be @{"cleared" LINK Clear}.\n\n      - Windows opening : requesters and  windows may be opened either over\n        the mouse pointer,  or in the middle of the  screen.  In that case,\n        pointer may be moved.\n\n\n  - Page 3 :\n        Informations  (name, size, type...) displayed  in  the  directories\n        windows may be edited.  You can change  informations,  their order,\n        and the date format.\n\n@endnode\n\n\n@node "Functions" "Functions"\n\nFunctions\n=========\n\n\n  Directory selection :\n  @{"Parent directory          " LINK ParentDir}\n  @{"Root directory            " LINK RootDir}\n  @{"Reread directory          " LINK GetDir}\n  @{"Select buffer             " LINK SelectBuffer}\n  @{"Clear buffers             " LINK ClearBuffers}\n  @{"Tree                      " LINK Tree}\n  @{"Read directory            " LINK ReadDir}\n  @{"Disk informations         " LINK DiskInfo}\n\n  Windows :\n  @{"Swap windows              " LINK SwapWindows}\n  @{"Toggle source/destination " LINK ToggleSD}\n\n  Entries selection  :\n  @{"Select all entries        " LINK All}\n  @{"Clear selection           " LINK Clear}\n  @{"Toggle selection          " LINK Toggle}\n  @{"Select entries            " LINK Select}\n  @{"Hunt files                " LINK Hunt}\n  @{"Memorize selection        " LINK MemorizeSelection}\n  @{"Restore selection         " LINK RestoreSelection}\n\n  Transfer/Deletion :\n  @{"Copy                      " LINK Copy}\n  @{"Move                      " LINK Move}\n  @{"Clone                     " LINK Clone}\n  @{"Delete                    " LINK Delete}\n  @{"Create directory          " LINK MakeDir}\n\n  Informations :\n  @{"Rename                    " LINK Rename}\n  @{"Calculate directory size  " LINK GetSize}\n  @{"Get filetype              " LINK GetFileType}\n  @{"Set comment               " LINK SetComment}\n  @{"Set protection            " LINK SetProtection}\n  @{"Set date                  " LINK SetDate}\n  @{"Add icon                  " LINK AddIcon}\n  @{"Get version               " LINK GetVersion}\n\n  Reading/Viewing :\n  @{"Action                    " LINK Action}\n  @{"Show ILBM picture         " LINK ShowPic}\n  @{"Show icon                 " LINK ShowIcon}\n  @{"Play sound                " LINK PlaySound}\n  @{"Show font                 " LINK ShowFont}\n  @{"Read                      " LINK Read}\n  @{"Hexadecimal read          " LINK HexRead}\n  @{"Search string             " LINK Search}\n\n  Running :\n  @{"Run                       " LINK Run}\n  @{"External tool             " LINK ExternalTool}\n\n  Printing :\n  @{"Print                     " LINK Print}\n  @{"Print directory           " LINK PrintDir}\n\n  Disk operations :\n  @{"Copy a disk               " LINK DiskCopy}\n  @{"Format a device           " LINK Format}\n  @{"Relabel a volume          " LINK Relabel}\n  @{"Install a disk            " LINK Install}\n\n  General :\n  @{"About Ordering            " LINK About}\n  @{"Iconify                   " LINK Iconify}\n  @{"Reread preferences        " LINK ReadPrefs}\n  @{"Quit                      " LINK Quit}\n\n@endnode\n\n\n@node "ParentDir" "Parent directory"\nParent directory\n================\n\n@{b}FUNCTION@{ub}\n\n      Reads the parent directory, and display it.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      First the parent directory is searched  in the buffers.  If it is not\n  found,  it is directly read from the device.  If this  function is called\n  whereas the source directory is the root,  the @{"Reread directory" LINK GetDir} function\n  is called.\n\n@endnode\n\n\n@node "RootDir" "Root directory"\nRoot directory\n==============\n\n@{b}FUNCTION@{ub}\n\n      Reads the root directory.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      First the parent directory is searched  in the buffers.  If it is not\n  found,  it is directly read from the device.  If this  function is called\n  whereas the source directory is the root,  the @{"Reread directory" LINK GetDir} function\n  is called.\n\n@endnode\n\n\n@node "GetDir" "Reread directory"\nReread directory\n================\n\n@{b}FUNCTION@{ub}\n\n      Forces to read and display the source directory again.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      The current selection will be lost.\n\n@endnode\n\n\n@node "SelectBuffer" "Select buffer"\nSelect buffer\n=============\n\n@{b}FUNCTION@{ub}\n\n      A requester is opened to select a directory among the buffers.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      None.\n\n@endnode\n\n\n@node "ClearBuffers" "Clear buffers"\nClear buffers\n=============\n\n@{b}FUNCTION@{ub}\n\n      To clear several directories among the buffers.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      None.\n\n@endnode\n\n\n@node "Tree" "Tree"\nTree\n====\n\n@{b}FUNCTION@{ub}\n\n      A window is opened to display all  directories and sub-directories of\n  the current volume. Then you may select a directory.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      All the directories are stored in the buffers.  So using this options\n  sometimes needs lots of memory.\n\n@endnode\n\n\n@node "ReadDir" "Read directory"\nRead directory\n==============\n\n@{b}FUNCTION@{ub}\n\n      This  function reads  selected  directories and  stores  them in  the\n  buffers. They are not displayed in the current window.\n\n@{b}OPTIONS@{ub}\n\n      Read sub-directories :\n          Sub-directories will be read and stored as well.\n\n@{b}COMMENT@{ub}\n\n      Directories read can be displayed using the @{"Select buffer" LINK SelectBuffer} function.\n\n@endnode\n\n\n@node "DiskInfo" "Disk informations"\nDisk informations\n=================\n\n@{b}FUNCTION@{ub}\n\n      Displays informations about current device.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      None.\n\n@endnode\n\n\n@node "SwapWindows" "Swap windows"\nSwap windows\n============\n\n@{b}FUNCTION@{ub}\n\n      The left window is redisplayed in the right window, and the right one\n  is redisplayed in the left one.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      None.\n\n@endnode\n\n\n@node "ToggleSD" "Toggle source/destination"\nToggle source/destination\n=========================\n\n@{b}FUNCTION@{ub}\n\n      The source window  becomes  the destination.  The  destination window\n  becomes the source window.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      None.\n\n@endnode\n\n\n@node "All" "Select all entries"\nSelect all entries\n==================\n\n@{b}FUNCTION@{ub}\n\n      Select all files and directories of the source directory.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      None.\n\n@endnode\n\n\n@node "Clear" "Clear selection"\nClear selection\n===============\n\n@{b}FUNCTION@{ub}\n\n      Unselect all files and directories of the source directory.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      None.\n\n@endnode\n\n\n@node "Toggle" "Toggle selection"\nToggle selection\n================\n\n@{b}FUNCTION@{ub}\n\n      Selected  entries  become  unselected,  and  unselected  ones  become\n  selected.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      None.\n\n@endnode\n\n\n@node "Select" "Select entries"\nSelect entries\n==============\n\n@{b}FUNCTION@{ub}\n\n      Select entries that match with the entered pattern.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      None.\n\n@endnode\n\n\n@node "Hunt" "Hunt files"\nHunt files\n==========\n\n@{b}FUNCTION@{ub}\n\n      Search for  files  that match with the  entered  pattern.  Files  are\n  searched in the selected directories.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      None.\n\n@endnode\n\n\n@node "MemorizeSelection" "Memorize selection"\nMemorize selection\n==================\n\n@{b}FUNCTION@{ub}\n\n      Memorizes  selected  entries.  You may  restore  them  using @{"Restore" LINK RestoreSelection}\n  @{"selection" LINK RestoreSelection}.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      See @{"Restore selection" LINK RestoreSelection}.\n\n@endnode\n\n\n@node "RestoreSelection" "Restore selection"\nRestore selection\n=================\n\n@{b}FUNCTION@{ub}\n\n      Select entries memorized with Memorize selection, if they exist.  All\n  the other entries will be unselected.\n\n@{b}OPTIONS@{ub}\n\n  Toggle selection :\n      Instead of being selected, memorized entries will be unselected.  The\n  other ones will be selected.\n\n@{b}COMMENT@{ub}\n\n      Example : Imagine  you want to  unarchive  files to RAM: to  test new\n  utilities.  Therefore many files and directories appears in RAM:, and you\n  will have to delete them.  But RAM: also contents the "Clipboards", "ENV"\n  and "T" directories,  that  you must not delete.  So  before  unarchiving\n  anything,  select  these three  directories  and @{"memorize the selection" LINK  MemorizeSelection}.\n  Then unarchive and test what you want.  Next restore the selection  (with\n  the  toggle selection  option).  All  entries  are  selected  except  the\n  "Clipboards", "ENV" and "T" directories.  And you only  have to  call the\n  @{"delete" LINK Delete} function.\n\n@endnode\n\n\n@node "Copy" "Copy"\nCopy\n====\n\n@{b}FUNCTION@{ub}\n\n      All selected entries will be copied  from the source  to the destina-\n  tion directory.  Moreover the program calculates and displays the size of\n  all the copied directories (see @{"Calculate directory size" LINK GetSize}).\n\n@{b}OPTIONS@{ub}\n\n  Copy date : \n      If this option  is not active,  date of the copied files  will be the\n  current date. Else it will be the source files date.\n\n  Copy protection :\n      If this  option is active,  the  protection bits  of the copied files\n  will be identicle to the ones of the source files. Else RWED bits will be\n  active.\n\n  Copy comment :\n      If the source entry has a comment it will be copied.\n\n  Ask for name :\n      Ordering will ask you to type the name of the destination entry. This\n  option is like the "Copy as" function in some other tools.\n\n  Low memory :\n      This option allows to  reduce memory usage during the copy.  Ordering\n  will only use a 11 kB buffer. But files of more than 11 kB will be copied\n  several times, and this is much slower.\n\n  Copy icon as well :\n      If an icon is associated to a file or a directory, it will be copied,\n  even it is not selected.\n\n@{b}COMMENT@{ub}\n\n      None.\n\n@endnode\n\n\n@node "Move" "Move"\nMove\n====\n\n@{b}FUNCTION@{ub}\n\n      Selected entries are @{"copied" LINK Copy}  to the  destination directory  and then\n  are @{"deleted" LINK Delete},  except if the source device and the destination device are\n  the same. In this case, entries are directly moved.\n\n@{b}OPTIONS@{ub}\n\n  Copy date : \n      If this option  is not active,  date of the copied files  will be the\n  current date. Else it will be the source files date.\n\n  Copy protection :\n      If this  option is active,  the  protection bits  of the copied files\n  will be identicla to the ones of the source files. Else RWED bits will be\n  active.\n\n  Copy comment :\n      If the source entry has a comment it will be copied.\n\n  Ask for name :\n      Ordering will ask you to type the name of the destination entry. This\n  option is like the "Copy as" function in some other tools.\n\n  Low memory :\n      This option is only  available if source and destination  devices are\n  different.  It allows to reduce  memory usage during  the copy.  Ordering\n  will only use a 11 kB buffer. But files of more than 11 kB will be copied\n  in several times, and this is much slower.\n\n  Copy icon as well :\n      If an icon is associated to a file or a directory, it will be copied,\n  even it is not selected.\n\n@{b}COMMENT@{ub}\n\n      None.\n\n@endnode\n\n\n@node "Clone" "Clone"\nClone\n=====\n\n@{b}FUNCTION@{ub}\n\n      Duplicates selected files and directories.  Ordering asks you to type\n  the name of the duplicated entries.\n\n@{b}OPTIONS@{ub}\n\n  Copy date : \n      If this option  is not active,  date of the copied files  will be the\n  current date. Else it will be the source files date.\n\n  Copy protection :\n      If this  option is active,  the  protection bits  of the copied files\n  will be identicla to the ones of the source files. Else RWED bits will be\n  active.\n\n  Copy comment :\n      If the source entry has a comment it will be copied.\n\n  Ask for name :\n      This option doesn''t do anything with this function.\n\n  Low memory :\n      This option allows to  reduce memory usage during the copy.  Ordering\n  will only use a 11 kB buffer. But files of more than 11 kB will be copied\n  several times, and this is much slower.\n\n  Copy icon as well :\n      If an icon is associated to a file or a directory, it will be copied,\n  even it is not selected.\n\n@{b}COMMENT@{ub}\n\n      None.\n\n@endnode\n\n\n@node "Delete" "Delete"\nDelete\n======\n\n@{b}FUNCTION@{ub}\n\n      Deletes selected entries.\n\n@{b}OPTIONS@{ub}\n\n  Confirm at the beginning :\n      Ordering will ask you a confirmation,  then it will delete everything\n  selected.\n\n  Confirm for each entry :\n      Ordering will ask you a confirmation for each deletion.\n\n  Auto remove protection :\n      If a file to delete is protected from deletion (D bit set),  Ordering\n  will remove the protection, then it will delete the file.  If this option\n  is not active,  Ordering will ask you a  confirmation before deleting the\n  file.\n\n  Delete icon as well :\n      Even if not selected, the icon associated to a file to delete will be\n  deleted as well\n\n@{b}COMMENT@{ub}\n\n      None.\n\n@endnode\n\n\n@node "MakeDir" "Create directory"\nCreate directory\n================\n\n@{b}FUNCTION@{ub}\n\n      Creates a new directory. Ordering will ask you to type its name.\n\n@{b}OPTIONS@{ub}\n\n  Add icon :\n      Creates an icon associated with the directory.\n\n@{b}COMMENT@{ub}\n\n      None.\n\n@endnode\n\n\n@node "Rename" "Rename"\nRename\n======\n\n@{b}FUNCTION@{ub}\n\n      Renames selected entries.\n\n@{b}OPTIONS@{ub}\n\n  Rename icon as well :\n      If the file or  the directory to rename has an icon,  it will also be\n  renamed.\n      Example : imagine  you  want  to  rename  the file  "NoFastMem"  into\n  "NoFast"; the file "NoFastMem.info" will be renamed into "NoFast.info".\n\n  Re-examine :\n      This option has been designed only because of the peecees mediocrity.\n  It  affects  PC0: disks (CrossDOSFileSystem).  Filenames  mustn''t be more\n  than 8 characters long,  and they have to be upper case.  Moreover,  many\n  chars are forbidden. However, even if you don''t apply these rules, the OS\n  will manage the name so that it suits, and no error will be generated. So\n  if you try to rename th file "PICTURE.LBM" into "Beautiful Picture.ilbm",\n  Ordering will display "Beautiful Picture.ilbm" in the window.  But if you\n  @{"read the directory again" LINK GetDir}, the file will appear as  "BEAUTIFU.ILB".  This\n  option allows to read informations  directly from the disk,  and prevents\n  Ordering from displaying a bad filename.\n\n@{b}COMMENT@{ub}\n\n      Peecees are very bad computers.\n\n@endnode\n\n\n@node "GetSize" "Calculate directory size"\nCalculate directory size\n========================\n\n@{b}FUNCTION@{ub}\n\n      Calculates the size (in bytes) token  by all  the files  contained in\n  the selected directories.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      None.\n\n@endnode\n\n\n@node "GetFileType" "Get filetype"\nGet filetype\n============\n\n@{b}FUNCTION@{ub}\n\n       Uses WhatIs.library  to find  the type  of the  selected  files.  If\n  WhatIs.library is not available, Ordering uses its internal process. Then\n  the filetype is displayed.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      See also @{"Filetypes" LINK FileTypes}.\n\n@endnode\n\n\n@node "SetComment" "Set comment"\nSet comment\n===========\n\n@{b}FUNCTION@{ub}\n\n      Allows to set the comment of the selected entries.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      None.\n\n@endnode\n\n\n@node "SetProtection" "Set protection"\nSet protection\n==============\n\n@{b}FUNCTION@{ub}\n\n      Allows to edit the protection bits of the selected entries.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      None.\n\n@endnode\n\n\n@node "SetDate" "Set date"\nSet date\n========\n\n@{b}FUNCTION@{ub}\n\n      Allows to edit the creation date of the selected entries.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      None.\n\n@endnode\n\n\n@node "AddIcon" "Add icon"\nAdd icon\n========\n\n@{b}FUNCTION@{ub}\n\n      Add an icon to the selected entries. WhatIs.library is used to find\n  the corresponding icon. If this process fails, icon.library is used.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      None.\n\n@endnode\n\n\n@node "GetVersion" "Get version"\nGet version\n===========\n\n@{b}FUNCTION@{ub}\n\n      Try to find version of the selected files.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      Except libraries and devices,  files must have the  "$VER..." string.\n  So this function will fail with all crunched files.\n\n@endnode\n\n\n@node "Action" "Action"\nAction\n======\n\n@{b}FUNCTION@{ub}\n\n      Determines the type of each selected file and launch the associated\n  action. See @{Filetypes" LINK FileTypes}.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      None.\n\n@endnode\n\n\n@node "ShowPic" "Show ILBM picture"\nShow ILBM picture\n=================\n\n@{b}FUNCTION@{ub}\n\n      Displays an IFF-ILBM picture.  When the picture is displayed, you may\n  press space  to show or  to hide the pointer.  To come  back to  the main\n  program, press the left mousebutton.\n\n@{b}OPTIONS@{ub}\n\n  Force DBLPAL/DBLNTSC :\n      Tries to  open the  screen in  DBLPAL or  DBLNTSC.  If it fails,  the\n  screen will be opened with the resolution given in the picture.\n\n@{b}COMMENT@{ub}\n\n      This viewer is fast,  but it uses more  memory  than the other  ones,\n  because the file is entirely loaded.  I have never found pictures that do\n  not work with my viewer. But if you have such images, please send them to\n  @{"me" LINK Address} (I will send your disk back to you).  Moreover, I couldn''t test it on\n  an Amiga with a graphic card.  So it may crash with pictures of more than\n  eight bitplanes. If you have problems, please write @{"me" LINK Address}.  I would like to\n  get any documentation about these cards (software).\n\n@endnode\n\n\n@node "ShowIcon" "Show icon"\nShow icon\n=========\n\n@{b}FUNCTION@{ub}\n\n      Displays selected icons.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      None.\n\n@endnode\n\n\n@node "PlaySound" "Play sound"\nPlay sound\n==========\n\n@{b}FUNCTION@{ub}\n\n      Plays selected sounds. 8SVX format is supported.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      None.\n\n@endnode\n\n\n@node "ShowFont" "Show font"\nShow font\n=========\n\n@{b}FUNCTION@{ub}\n\n      Displays selected fonts.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      None.\n\n@endnode\n\n\n@node "Read" "Read"\nRead\n====\n\n@{b}FUNCTION@{ub}\n\n      This function allows to read the selected files (ascii).  A slider is\n  on the right of screen.  On the right lower-corner, there are two numbers\n  separated by a "/". The first one is the current line, and the second one\n  is the number of  lines of the file.  Several buttons are located on  the\n  bottom of the screen :\n\n      - Print : print the file\n\n      - Abort : quit the text viewer, and abort the current operation.  For\n  example, if you have selected several texts,  Ordering will stop  reading\n  these texts.\n\n      - Quit (shortcut key : "Q", "X" or "Esc") : quit the text viewer.\n\n      - Top (shortcut key : "T) : go to the top of the text.\n\n      - Bottom (shortcut key : "B") : go to the bottom of the text.\n\n      - Iconify (shortcut key : "I") : close the the window  and the screen\n  of the  text viewer,  and open a  little  window  on the  main  program''s\n  screen. To come back to the text viewer, press the right mousebutton when\n  this window is active.  This option is only available if the text is read\n  in background (if you double-click the file).\n\n      - Line Up (shortcut key : arrow up) : scroll  the  text up,  line  by\n  line.\n\n      - Line Down (shortcut key : arrow down) : scroll the  text down, line\n  by line.\n\n      - Goto Line (shortcut key : "G") : the program asks you  to enter the\n  number of the line where you want to go.\n\n      - Page Up (shortcut key : "U" or  Shift+arrow up) : scroll  the  text\n  up, page by page.\n\n      - Page Down (shortcut  key : "D"  or  Shift+arrow down) : scroll  the\n  text down, page by page.\n\n      - Hexa/Ascii (shortcut key : "H") : toggle hexadecimal/ascii display.\n\n      - Find... (shortcut key : "F") : search for a string.\n\n      - Previous (shortcut key : "P") : the program searches for the string\n  entered with "Find...", from the current line, and backward.\n\n      - Next (shortcut  key : "N") : the  program searches for  the  string\n  entered with "Find...", from the current line, and forward.\n\n@{b}OPTIONS@{ub}\n\n  Right mousebutton to quit :\n      You may come  back  to the main program  just by  pressing  the rigth\n  mousebutton.\n\n@{b}COMMENT@{ub}\n\n      The "Find..." option uses the Boyer-Moore algorithm.  I think a better\n  algorithm doesn''t exist.  It all  the more fast  since the string is long.\n  So please  compare it with other text viewers.  If you  find a faster one,\n  please tell @{"me" LINK Address} about it.\n\n@endnode\n\n\n@node "HexRead" "Hexadecimal read"\nHexadecimal read\n================\n\n@{b}FUNCTION@{ub}\n\n      This  function is the  same as @{"Read LINK Read},  but the  file is displayed  in\n  hexadecimal.\n\n@{b}OPTIONS@{ub}\n\n  Right mousebutton to quit :\n      You may come back  to the  main program  just by  pressing  the rigth\n  mousebutton.\n\n@{b}COMMENT@{ub}\n\n      See @{"Read" LINK Read}.\n\n@endnode\n\n\n@node "Search" "Search string"\nSearch string\n=============\n\n@{b}FUNCTION@{ub}\n\n      Ordering  asks you to  type a  string  to search for  in the selected\n  files and directories. If it is found, you may read the text and continue\n  the search.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      None.\n\n@endnode\n\n\n@node "Run" "Run"\nRun\n===\n\n@{b}FUNCTION@{ub}\n\n      Run selected files, with arguments that you may enter.\n\n@{b}OPTIONS@{ub}\n\n  Runback :\n      Executes programs in background.\n\n  Output window :\n      A window will be  opened  for each  launched  program.  Window may be\n  defined with @{"Options" LINK Options} in the preferences editor.\n\n@{b}COMMENT@{ub}\n\n      None.\n\n@endnode\n\n\n@node "ExternalTool" "External tool"\nExternal tool\n=============\n\n@{b}FUNCTION@{ub}\n\n      Allows to execute external programs with parameters.\n\n@{b}OPTIONS@{ub}\n\n  Runback :\n      Executes programs in background.\n\n  Output window :\n      A window will be  opened  for each  launched  program.  Window may be\n  defined with @{"Options" LINK Options} in the preferences editor.\n\n  Reread source directory :\n      When execution is completed,  Ordering will read the source directory\n  again.\n\n  Reread destination directory :\n      When  execution is  completed,  Ordering will  read  the  destination\n  directory again.\n\n  External tool :\n      You should enter the name and the path of the  program to run and its\n  parameters in this box. There are two little buttons on the right side of\n  the box.  If you click the first one, you may select the tool with a file\n  requester.  If you click the second one, a window will be opened.  A list\n  of little strings is displayed.  Each one starts with "%".  When the tool\n  is launched, they are replaced by what they represent.  Here are  several\n  examples :\n\n      - Imagine  you created a  button with the  "External tool"  function,\n  with "C:Dir %sd" in the box, and the "Output window" option active. "%sd"\n  means "source directory". When you press the button, "%sd" is replaced by\n  the  current  source directory.  If it is "RAM:",  Ordering  will run the\n  "C:Dir RAM:" command.\n\n      - Now let''s see  something more useful : how to list an LhA  archive.\n  You may associate  to the @{"filetype" LINK FileTypes} "LHArc" the "External tool" function,\n  with "C:LhA v "%dcf"" in the box,  and the "Output window" option active.\n  %dcf means "double-clicked file".  If you double-click the "Ordering.lha"\n  file, located in  the "DH0:Archives" directory,  Ordering will launch the\n  "C:LhA v "DH0:Archives/Ordering.lha"" command. Please note that "%dcf" is\n  in quotation marks.  This  avoids lots of  problems if the  path name has\n  spaces.\n\n      - Here is the way to extract  LhA archives : associate to the "LHArc"\n  @{"filetype" LINK FileTypes} (right mousebutton  if you already have associated an action to\n  this filetype), the "External tool" function, with "C:LhA x "%dcf" "%dd""\n  in the box,  and the  "Output window" and  "Reread destination directory"\n  options  active.  Imagine the   destination  directory is "RAM:".  If you\n  double-click  the "Ordering.lha"  file  located  in  "DH0:Archives".  The\n  "C:LhA x "DH0:Archives/Ordering.lha" "RAM:"" will be launched.  When this\n  is completed, Ordering will read the destination directory again ("RAM:")\n  in order to update it.\n\n      - And now, how to create an LhA archive.  Create a @{"button" LINK Buttons} or a @{"menu" LINK Menus}\n  item with the "External tool"  function, with  "C:LhA -r a "%fr" %ase" in\n  the box,  and the  "Output window"  options  active.  "%fr"  means  "file\n  requester" and %ase means "all selected entries".  Imagine you select the\n  "Disk.info" and  "System.info"  files in the  "DH0:" directory.  When you\n  press the created button,  a file  requester will be opened.  Select your\n  archive name. If you have selected the "RAM:Test.lha" file, Ordering will\n  launch the "C:LhA -r a "RAM:Test.lha" DH0:Disk.info DH0:System.info" com-\n  mand.\n\n@{b}COMMENT@{ub}\n\n      None.\n\n@endnode\n\n\n@node "Print" "Print"\nPrint\n=====\n\n@{b}FUNCTION@{ub}\n\n      Print selected files.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      The device used may be edited with the preferences editor (@{"Options" LINK Options}).\n\n@endnode\n\n\n@node "PrintDir" "Print directory"\nPrint directory\n===============\n\n@{b}FUNCTION@{ub}\n\n      Print the contents of the directory, as it is displayed.\n\n@{b}OPTIONS@{ub}\n\n  Print diskname :\n      If this option is active, Ordering will print the path, the diskname,\n  and the free size.\n\n@{b}COMMENT@{ub}\n\n      The device used may be edited with the preferences editor (@{"Options" LINK Options}).\n\n@endnode\n\n\n@node "DiskCopy" "Copy a disk"\nCopy a disk\n===========\n\n@{b}FUNCTION@{ub}\n\n      Copies a disk. If the "Verify" option is active, each written track\n  is read and compared with the buffer to write. It is much slower, but\n  disk will be correctly copied.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      None.\n\n@endnode\n\n\n@node "Format" "Format a device"\nFormat a device\n===============\n\n@{b}FUNCTION@{ub}\n\n      Formats disks, hard disks...\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      The  device is  formated  in  background.  You may  continue  to  use\n  Ordering,  and  you  may also  format  other devices (try to do that on a\n  peecee).\n\n@endnode\n\n\n@node "Relabel" "Relabel a volume"\nRelabel a volume\n================\n\n@{b}FUNCTION@{ub}\n\n      Allows to relabel one of the present devices.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      None.\n\n@endnode\n\n\n@node "Install" "Install a disk"\nInstall a disk\n==============\n\n@{b}FUNCTION@{ub}\n\n      Allows to install a bootblock on disks.  You may load a @{"BBM library" LINK BBMLib},\n  to install any bootblock.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      None.\n\n@endnode\n\n\n@node "About" "About Ordering"\nAbout Ordering\n==============\n\n@{b}FUNCTION@{ub}\n\n      Displays informations about  Ordering and its author (@{"me" LINK Address}).  The name\n  of the public screen is also displayed.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      This  function is not  very  useful... You  should  rather  read  the\n  @{"Important" LINK Important}, @{"Introduction" LINK Introduction} and @{"Author''s address" LINK Address} paragraphs.\n\n@endnode\n\n\n@node "Iconify" "Iconify"\nIconify\n=======\n\n@{b}FUNCTION@{ub}\n\n      Close  the  window and the  screen,  then open a little window on the\n  Workbench screen. You may quit the program by closing the window, or come\n  back to  the  usual  screen by  pressing the  right  mousebutton when the\n  window is active.\n\n@{b}OPTIONS@{ub}\n\n      None.\n\n@{b}COMMENT@{ub}\n\n      Using this  option allows to  reduce memory  usage  if you don''t need\n  Ordering immediately.\n\n@endnode\n\n\n@node "ReadPrefs" "Reread preferences"\nReread preferences\n==================\n\n@{b}FUNCTION@{ub}\n\n      Rereads the preferences file.\n\n@{b}OPTIONS@{ub}\n\n  File requester :\n      To select the preferences file to load. If this option is not activa-\n ted, Ordering tries to load the "ENVARC:Ordering.prefs" file.  Note : this\n option is available only if reqtools.library is present.\n\n@{b}COMMENT@{ub}\n\n      This option is very useful to create your own preferences.  Each time\n  you save the preferences in the @{"preferences editor" LINK PreferencesEditor}, you should call this\n  function.\n\n      Warning : everything is  reinitialized.  Buffers,  selection  will be\n  lost.\n\n@endnode\n\n\n@node "Quit" "Quit"\nQuit\n====\n\n@{b}FUNCTION@{ub}\n\n      Quits Ordering.\n\n@{b}OPTIONS@{ub}\n\n  Confirm :\n      The program asks if you really want to quit.\n\n@{b}COMMENT@{ub}\n\n      Don''t forget to  create a command  to quit in  the @{"buttons" LINK Buttons} or in the\n  @{"menus" LINK Menus}...\n\n@endnode\n\n\n\n@node "BBMLib" "BBM libraries"\nBBM libraries\n==============\n\n      A BBM library is a file  created  by  Bootblock Manager (BBM),  which\n  contains several bootblocks.  So you may install the bootblocks  that you\n  want on your disks.\n\n@endnode\n\n\n\n@node "Address" "Author''s address"\n\nAuthor''s address\n================\n\n      If you like Ordering, if you use it,  or if you have anything to tell\n  me, send me a  postcard (of course, you can send something else (money)).\n  You can reach me at this address :\n\n                           Julien TORRES\n                           2 rue Pierre Fresnay\n                           87410 Le Palais sur Vienne\n                           FRANCE      (from June to September)\n\n      or                   Julien TORRES\n                           29 chemin des Maraîchers\n                           31400 Toulouse\n                           FRANCE      (from October to May)\n\n      If you have any ideas, any suggestions,  if you find bugs,  or if you\n  have problems, please contact me (I like postcards).\n\n\n@endnode\n\n\n\n@node "Acknowledgements" "Acknowledgements"\n\nAcknowledgements\n================\n\n  I''d like to thanks the following people :\n\n      - Sylvain Rougier and Pierre Carrette for the whatis.library.\n\n      - Nico François for the reqtools.library and the powerpacker.library.\n\n      - Stefan Becker for helping me.\n\n      - Olivier Dartois for help, hints, and moral support.\n\n      - Alexandre  Granvaud for  help,  hints,  for writing a (little) part\n  of this documentation, and for the Installer script.\n\n      - Christophe Laratte for help, many hints and tips, his authorization\n  to use @{"BBM libraries" LINK BBMLib}, and for writing a part of this documentation.\n\n      - You, if you @{"write me" LINK Address}.\n\n@endnode\n\n\n\n@node "History" "History"\n\nHistory\n=======\n\n       - Version 1.01 (11.04.95) : first distributed version.\n\n       - Version 1.02 (15.06.95) : some  bugs  fixed, some  changes  in the\n  @{"preferences editor" LINK PreferencesEditor}, documentation completed.\n\n       - Version 1.03 (28.06.95) : the @{"Set date" LINK SetDate} function  has been  impro-\n  ved.  Added  "%ps" and "%sr"  for  the @{"External tool" LINK ExternalTool} function.  Fixed  a\n  little bug in the @{"preferences editor" LINK PreferencesEditor}. Text viewer improved.\n\n       - Version 1.04 (19.07.95) : fixed a  bug in  the text viewer. @{"Quit" LINK Quit},\n  @{"Reread preferences" LINK ReadPrefs} and @{"Iconify" LINK Iconify} functions have been improved.  Arguments\n  and tooltypes support.  Added the "Use Workbench colours" function in the\n  @{"preferences editor" LINK PreferencesEditor} (@{"Screen" LINK Screen}). Fixed some other little bugs. Now Ordering\n  recognizes catalogs with internal mode (see @{"Filetypes" LINK FileTypes}).\n\n       - Version 1.05 (14.09.95) : fixed a bug  in the moving  of the mouse\n  pointer when opening a window.  Better keys handling.  Fixed a bug in the\n  shortcut key editing (@{"buttons" LINK Buttons}). Screens openings improved. English docu-\n  mentation corrected. Buttons may be located between windows.  Fixed a bug\n  in the @{"Reread preferences" LINK ReadPrefs} function.\n\n@endnode\n','\n',char(10)),NULL,'auto-added',191720,4,0,NULL,NULL,'dvd_o105','scan',1780048498);
INSERT INTO door_catalog VALUES('dvn_ist','DVN-IST.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DVN-IST.LHA','Istrip','XIM','Istrip',NULL,NULL,'DVN','_______ (__¡) __!   _ /__)________  _______ ____  _\/   \/  |   //   \____.  _\/  ___ /   \  \\    \  !  ·/     \   |.  \\  !____',replace('          __!_          __\n _______ (__¡) __!   _ /__)________  _______\n ____  _\/   \/  |   //   \____.  _\/  ___\n /   \  \\    \  !  ·/     \   |.  \\  !____\n \_______/____/\____/\_____/___|!   ·\______\n [==========PRESENTS==========]!______/SgE\n   Istrip With Full Random Add Generator\n [-][-]  Installer Program Supplied  [-][-]\n','\n',char(10)),'NewStrip.doc',replace('\n\n             :\n   _  _   ___|__  | _____  ____ ____  _____ ___________ _________   _  _\n    \\_\ /  ___/  |      \/    :    \      \     ._    \_    ___/_ /_//\n        /   \|    |       \    |    /       \    l/     /   __/  /\n        \_________|_______/\_______/\_______/____/     /________/\n                                                /_____/-lPY!\n\n\nNothing new about the stripper .. Written by TAS this has got to be the all\ntime Fastest stripper around .. which is why so many other strippers \nincorperate it.\n \nSo what has changed ?\n \nWell you still get the fastest stripper running but now when when you come\nto Add your own addies they will be completly randomised each time.. This\nmaking them almost impossible to strip .. You can also have your BBS name\nincluded and still randomise it ..\n \nExample :)\n \n  When you name your ads use Cap''s for letters you want to remain the same\n \n  And use LowerCase for letter to be randomised\n \n  BBSADDIE.kgjh This will keep the BBSADDIE. and randomise the last 4 letters\n  each time..\n \n  OR      BcBsSoAeDiDrIoE\n \n  You should get the idea anyhow..\n \nAnother extra included is the FileComment .. you will see in the BATCHSCRIPT \n\nthe       "Put here comments to be displayed"\n \nJust include anything inside the " ?? " and this also will be added so if the\nfile is viewed it will display your comment ..\n \nChances are most boards will have some sort of updating file for when people\nlogoff your boards for updating the lastcallers etc .. so edit it ..\nJust add this Commands to your existing scripts\nThis Should be run evertime someone logs off!\n \n     SYS:C/RFG S:SIl1 S:Sil "Put here comments to be displayed"\n \nThis will take all your ad''s from the SIL1 Dir Rename them and Add them into\nthe SIL Dir .. ALL files included in the SIL Dir will be added .. So if you\nhave a Random 8 letter Ad There isnt much chance of it being deleted by other\nboards strippers .. This being the case theres NO need to ad more than 1 file\nwith your ad to each Archive !!\nYou could add severel but if people are going to call then it wont matter to\nthem which ad they get the numba from .. and it might show that your not too\ndesperate for users !\n \nRegards goto Pink Floyd/DVN For the randomiser and putting up with me always\ncalling him when i have a problem that needs his expertise (creep) and to \nLost Treasures,Mystical Legends and Robin Hood for there patience Beta \ntesting this util.\n\n\noK I cant write doc''s but this is a simple enough util to get running ..\n\nSaRgE DvN/HF\n\n                                                       __________   _  _\n                           ____ ____       ___________/      ___/_ /_//\n               :          /    :    \  ____     ._    \_    __/  /\n     _  _   ___|__  | ____\    |    /      \    l/     /________/\n      \\_\ /  ___/  |      \_______/        \___/     /-lPY!\n          /   \|    |       \      \________/  /_____/\n          \_________|_______/\n\n','\n',char(10)),NULL,'auto-added',14599,2,0,NULL,NULL,'dvn_ist','scan',1780048498);
INSERT INTO door_catalog VALUES('dvn_skip','DVN-SKIP.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DVN-SKIP.LHA',NULL,'XIM','__!_          __',NULL,NULL,'DVN','_______ (__¡) __!   _ /__)________  _______ ____  _\/   \/  |   //   \____.  _\/  ___ /   \  \\    \  !  ·/     \   |.  \\  !____',replace('         __!_          __\n_______ (__¡) __!   _ /__)________  _______\n____  _\/   \/  |   //   \____.  _\/  ___\n/   \  \\    \  !  ·/     \   |.  \\  !____\n\_______/____/\____/\_____/___|!   ·\______\n[==========PRESENTS==========]!______/EL?\n  Sysop Skip...stop ALL them old files!\n','\n',char(10)),'SysopSkip.doc',replace('          __!_          __\n _______ (__¡) __!   _ /__)________  _______\n ____  _\/   \/  |   //   \____.  _\/  ___\n /   \  \\    \  !  ·/     \   |.  \\  !____\n \_______/____/\____/\_____/___|!   ·\______\n [==========PRESENTS==========]!______/EL?\n   Sysop Skip...stop ALL them old files!\n\n\nDisclaimer:\n\n    The programmer/docs writer or any di\/ine member accept no responsability\nfor any damage caused in the use of his program, It has been tested on an\n A4000/030 running at 50mhz, with 6meg ram, and also on A1200 standard.\n\n\nWarning!\n\n    Once you have set this program running you can not exit from it untill it\nhas finnished. It took my a4000 aprox 30mins to create 1800 files onto the\nhard drive, so you may wish to select Ram: as the source path, which will speed\nthings up considerably, or just to see that it does work!!\n\n\nwhy?\n\n    After deleting aproximately 6 months worth of warez from the hard drive\nI had a problem, people were uploading old warez.. so i decided to use\nsuper dupe check, the trouble was that this did not stop them uploading the\nold files, it merely moved them to the hold directory, and it also slowed the\nfilechecking considerably, nothing against Super dupe check, but it does take\ntime to check through a 1.5 meg file!, and after checking each and every upoad\nyou could easily add a few minutes to your upload time..\n\n\nWhat this Util does.\n\n    this util, loads in your Files list and converts all the filenames into\nfiles, in doing this it ignores "Nuke" comments Tabs and spaces, if however\nyou have other wierd characters at the start of a line that are not file names\nit will create a file with that filename, in a future version we may find a way\naround this, but for now you will have to edit them out before using this tool.\n\n\nUsage:\n\n    Just run it!!      "SysopSkip"\n\n\ncredits:\n\n     The Welder, for sitting and coding this util while being harrassed\n     Buddy (me), for writing these small docs, and harrassing The Welder\n     Dan/Oasis, for having file lists on line to test this tool on\n\n\n          __!_          __\n _______ (__¡) __!   _ /__)________  _______\n ____  _\/   \/  |   //   \____.  _\/  ___\n /   \  \\    \  !  ·/     \   |.  \\  !____\n \_______/____/\____/\_____/___|!   ·\______\n [==========PRESENTS==========]!______/EL?\n   Sysop Skip...stop ALL them old files!\n\nNow call one of our Boards:-\n\n===========================================================================\n ___________________  _________ _________ ________   _____     ____ ____\n \__  ______\______ \_\__  ___/ \__  ___/ \______ \_/     \ !! \_  Y  _/\n  /   ___/  /   _  __//   _/___ /   _/____/  ___/  /   |   \ ! /  \_/  \\n_/     |  _/    |    \    |    \    |    \  /     /    |    \_/    |    \_\n\______|  \________________________________/     /\_________/\_____|_____/\n                                          /_____/\nrUNNING 4030 / 8mEG / 1.5 gIG oNLINE               +44 (0)1255-2206/12/08\n lARGE /X cONF 1000+   ___  ___   ________________ _____ ____ ________\npC/aMIGA/h&P/cLASSIC  /   ||   \ l_______  ____   |   _/l____!\_ ___  \\n nODE1 28.8 v.FAST   /    ||    \|    |/    \/    #    \|    |/    /   \\n nODE2 28.8 v.FAST _/     /\     \    |      \    T     \    |    /     \_\n  cOOL sYSOP tEAM  \______________________________|______________/       /\n                                                  |             /_______/\n    nO nEWUSER pASSWORD fOR lIMITED pERIOD oNLY   |\n -------------------------------------------------''\n===========================================================================\n\n     1gig+Online/6mb/68030/50mhz  /X4.6-  2 node   FUN!   NUP nEEDED\n          __         .          .                         __\n          \/     /  .!__  ______!_ _________________ _    \/\n                /   !|  \/   .  ¡\/    _______    ___ _      TRD\n  di\/ine      /     !   \   !  : \_____   \/      \      dIST sITE\n   EUHQ        \_    .___/________/    ____/\______/\n              : `----''            `----''     :        Amiga/AGA Fix/HD/?\n _____________!______________________________|  .!__________________________\n___   ______  ¡\_   _________  ./    ____/   |  |\____   \_   _____    ______\n /     \      _/   _____/   _  !\_____   \   !  !|      _/   _____\_____   \\n \_____/___|   \____    \___!   |    ____/____   |___|   \____    !    ____/\n           !____/  `----''EL?`---`----''       `---''   !____/  `----`----''\n\n           " The city begins to shake as the spiritual and the\n          supernatural struggle for supremacy and the horrifying\n          strength of the Lost Treasures are finally realised ..."\n\n                    SySøP: BuDDy/dIVINE^tRD^eNTERPRISE\n                      cOSySøPs:  GaZ P/sKID rOW\n                   Fatrat/dVN    Focus/On a Mission\n            Call now! Node 1.. 01325 369632  28.8 V34Terbo\n                      Node 2.. 01325 pRIV8  14.4\n\n-------------------------------------------------------------------------------\n   ..................        \n   ..........:::::::::                       __/\__  \n   ::::::::: ::::::::''    :::::::::::::::    \ OO / \n   ::::::::: :::::::::  ::::::::  :::::::::  /_\^_\  \n   ::::::::: :::::::::  :::::::    ::::::::    \/    [-- Di\/ine UkHq --]\n               ________ ::::::::  ::::::::: \n         