INSERT INTO door_catalog VALUES('dvn_acd','DVN_ACD.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/DVN_ACD.LHA','AccessDenied','XIM','AccessDenied',NULL,NULL,'DVN','_______ (__¡) __!   _ /__)________  _______ ____  _\/   \/  |   //   \____.  _\/  ___ /   \  \\    \  !  ·/     \   |.  \\  !____',replace('          __!_          __\n _______ (__¡) __!   _ /__)________  _______\n ____  _\/   \/  |   //   \____.  _\/  ___\n /   \  \\    \  !  ·/     \   |.  \\  !____\n \_______/____/\____/\_____/___|!   ·\______\n [==========PRESENTS==========]!______/pF\n     <><> Access Denied Encryption <><>\n         As Seen On LSD CD Vol II..\n  Last Update To This Program Not Crippled.','\n',char(10)),'AccessDenied.Guide',replace('@database "Access Denied V1.3"\n@AUTHOR "Exile - Pink Fløyd ©1995"\n@(C) "Access Denied"\n@Ver$ "Access Denied V1.3"\n@HEIGHT 30\n@Node MAIN "Access Denied"\n                                                                  \n       .:::::::. .:::::::. .:::::::. ::::::::: .:::::::. .:::::::.\n       ::::::::: ::::::::: ::::::::: ::::::::: ::::::::: :::::::::\n       :::: :::: ::::  ::: ::::  ::: ::::      ::::      ::::     \n       ::::::::: ::::      ::::      :::::::    ·:::::.   ·:::::. \n       :::: :::: ::::  ::: ::::  ::: ::::            :::       :::\n       :::: :::: ::::::::: ::::::::: ::::::::: ::::::::: :::::::::\n       :::: :::: ·:::::::· ·:::::::· ::::::::: ·:::::::· ·:::::::·\n                                                                  \n       :::::::.  ::::::::: :::  :::: ::::::::: ::::::::: :::::::. \n       ::::::::: ::::::::: :::: :::: ::::::::: ::::::::: :::::::::\n       :::: :::: ::::      :::::::::   :::::   ::::      :::: ::::\n       :::: :::: :::::::   :::::::::   :::::   :::::::   :::: ::::\n       :::: :::: ::::      :::::::::   :::::   ::::      :::: ::::\n       ::::::::: ::::::::: :::: :::: ::::::::: ::::::::: :::::::::\n       ::::::::· ::::::::: ::::  ::: ::::::::: ::::::::: ::::::::·\n             _ __ ___ ________________________________ __ _ _\n                     Y    .--------------------.\n                     :    |   @{"    About.    " link "Disc"}  |\n.                    .    :   @{" Requirements " link "Req"}  : \n..                   .    :   @{" Installation " link "Inst"}  :   \n....                      .   @{" How it works " link "What"}  .\n.............             `--------------------''\n..................\n..........................\n.............................................................................\n\n\n@endnode\n\n@node "Disc"\n@toc "Disc"\n\n\n\n                              What is it ???\n \n\n\nWell this is the second version of Access Denied which basically is a small\n Encryption Program\n\nThe First Version You Will find On LSD CD Volume II In Pack\n\n WARNING - DO NOT LOSE YA PASSWORDS AS IF YOU DECRYPT A FILE WITH THE WRONG\n           PASSWORDS THE FILE WILL THEN ENCRYPT ITSELF AGAIN WITH THE NEW\n           PASSWORDS AND THE OLD SO FILE WILL BE ENCRYPTED TWICE !!!!!!!!!\n\n\n                             @{" Main Menu " link "MAIN"}\n\n@endnode\n\n@node "Req" "Requirements"\n@toc "Req"\n\n               Any Amiga (600,1200,3000,4000,4000T,5000(?)....\n\n                            @{" BACK TO MAIN MENU? " link "MAIN"}\n\n@endnode\n@node "Inst" "Installation - "\n@toc "Inst"\n                         \n                           HAHA What Installation.\n\n                            @{" BACK TO MAIN MENU? " link "MAIN"}\n@endnode\n@node "What" "---> What it does: <---"\n@toc "What"\n\n    This File Encryption Program Has Been Tested on DMS / LHA files aswell\n    as ordinary dos files with no Crashes or corruptions to date ,\n    We take no responsibilty with Loss of data or damage caused by use\n    or misuse of this Program  YOU HAVE BEEN WARNED !!!!!\n               \n    The program should be pretty much explain it''s self, I have not written\n    much about the usage of this program because I hate typing Docs....\n\n    If you have any hassle with this program or know find any bugs you can\n    contact me on the BBS: Access Denied, or if you leave mail on 1 of the \n    following boards for PINK FLOYD he will pass the messages on:\n    \n                            Freedom Within ........ Divine\n                            Robin Hood ............ Divine\n                            Lost Treasures ........ Divine\n                            Mystical Legends ...... Divine\n                            Wild ?????????   ...... Divine\n                            Blood Runners ......... Indy\n                            Pacific Uk ............ Indy\n    \n    If leave mail you will be metioned in the next update....\n    If you manage to crack this program please leave info on how you\n    done it....\n\n** NOTE **\n----------\n        Before typing in the passwords you must select a file..\n        if you type in your passwords before you have selected a \n        file the password buffers will be cleared when you select\n        a file.. although this might not happen on you system you\n        have been warned...\n\n\n < 1 >  Select File - No Explaination Needed\n\n < 2 >  Enter Passwords - Enter Two Passwords Pressing Return On Each Line\n        N.B   Must Be 6 Characters NO MORE NO LESS\n\n < 3 >  Encrypt / Decrypt - Now you have entered your passwords click this\n        gadget to Encrypt the file , The file will be save in the same \n        place as the Selected file but the new file will have the Extension\n        .EPF this is so as not to confuse you in what files have been done.\n\n < 4 >  Follow The same Procedure to Decrypt the file but any extensions\n        like .DMS .LHA will not be returned to the file ( This May be\n        cured in the next release of this program ). \n  \nWhats New:\n\n < 1 > I have added a log file which is records all the files encrypted,\n       the files path & the passwords. The log file is stored in "S:"\n       as "AD.Log", PLEASE NOTE that each time Access Denied© in run\n       the Log file will  reset.\n\n < 2 > I replaced the EXE option for Preview Log, this enables you to view\n       the previous log.\n\n < 3 > In the status box i have replaced "Directory" for "Drive", I done\n       this because if the path was to long it would go out of the \n       window. ( I''am a lazy shit, i could not be bothered to fix it )\n   \nKnown Bugs:\n\n < 1 >  The Text Overlaps the bevelled boxes (looks fucking horrible)\n < 2 >  You have to select a file before you type in the passwords...\n        This is due to a allocation error.. I should of sorted it out\n        by now but I totally forgot about it..\n     \n        There are probaly loads of small bugs in this program that\n        I don''t know about at. But to tell you the truth I can not\n        be bothered to look for them. But if you find any I would \n        like to know about them...        \n\n\n                            @{" CLICK ME PLEASE !" link "MAIN"}\n\n@endnode\n','\n',char(10)),NULL,'auto-added',10356,1,0,NULL,NULL,'dvn_acd','scan',1780048498);
