INSERT INTO door_catalog VALUES('e__st1_o','E!-ST1.O.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/E!-ST1.O.LHA',NULL,'XIM','____                          ___',NULL,NULL,'E!','___ /_  /__   __ __   ___   __    /_ | / __\ / / __\ /  Y  \ / __\ /  \___ / |_ / /__/_ / /__/_  \_/  \ /__/_  _ \ // __|__',replace('       ____                          ___\n  ___ /_  /__   __ __   ___   __    /_ |\n / __\ / / __\ /  Y  \ / __\ /  \___ / |_\n/ /__/_ / /__/_  \_/  \ /__/_  _ \ // __|__\n\_____//\_____/___|    \____/__/   \  |   /\n.=================|_____\=====/_____\____/=.\n: PRESENTS TODAY, 29.11.96               :f:\n: New Kewl Status Door For /X ,S!X & LGC :«:\n: Now With A Kewl Backloop Effekt For    :z:\n: Printing Data On The Terminal    [1/1] . :\n`------------------------------------------''\n','\n',char(10)),'STATUS.guide',replace('@database e!-Status Documentation\n\n@remark $VER: (November 29 1996, 15:40)\n@remark AmigaGuide database for the e! Status-DoorMenu Documentation\n\n@node MAIN "e!-Status Documentation"\n                 ____         ______                             ______\n  _ ____________|    |________\__   \  __________________________)   _/_\n e!\\     _     /    |    _     /    \/   _    _     /    _    __   ___/__\n     \    /____/.    |    /____/.    \/   \    /____/.    /    /    \     \ _\n      \_____    |____|\_____    |\___/    /\_____    |___/    /____________\\\n           |____|          |____|   /____/      |____|  /____/>vnz\n                                                                         \n\n    e!-Status.Guide  -  Contents\n    ============================\n\n    1) @{" Introduction " Link ChildDoc1}\n    2) @{" Requirements " Link ChildDoc2}\n    3) @{" Installation " Link ChildDoc3}\n    4) @{" History " Link ChildDoc4}\n    5) @{" Greetings " Link ChildDoc5}\n    6) @{" How to contact e! " Link ChildDoc6}\n\n@endnode\n@node ChildDoc1 "Introduction"\n\n  e!-Status   -   Introduction\n  =============================\n\n  5D-DoorMenu is an enhancement for /X\n  that allows you to se a full user status.\n\n@endnode\n@node ChildDoc2 "Requirements"\n\n  e!-Status   -   Requirements\n  =============================\n\n  o  an Amiga (or compatible - DRACO)\n  o  an AmiExpress-compatible BBS-program\n\n@endnode\n@node ChildDoc3 "Installation"\n\n  e!-Status  -  Installation (for AmiExpress)\n  ===========================================\n\n  Simply copy the directories in this archive into your bbs-\n  directory.\n\n@endnode\n@node ChildDoc4 "History"\n\n  e!-Status   -   History\n  ========================\n  \n  v0.1 - Developer versions\n  ....\n  v0.9 - Implanted a backloop routine [07-11-96]\n  v1.0 - [RELEASE I]                  [29-11-96] \n\n@endnode\n@node ChildDoc5 "Greetings"\n\n  Greetings\n  =========\n\n      2Pac - Azlan - Bakerman - Conan&Newton - Curt Cool\n    Deckard - Deliveryman - Dizy - DMG - Dr. Zero - D-Tail \n   Flozzy - Genius - Hive Tyrant - JLK - Joshua -  LionHeart \n   m7g - Madmardigan - Matriz - Metal Man - Mortician - Nicko \n    Night Walker - Phonetic - Platoon Presence - Red Cheese \n  Schindler - Scqeech -  Sealapex - Spellbinder - STC - Sticky \n SVG - Swaxi - The Foxy One - The Dancing Duck - The Tea Drinker \n  The Tick - Triumph - Tronic - vENTURA - Wiseman - Zarch&Xman\n   \n  \n Moral Support\n =============\n\n     Coca-Cola - GOA - MANGA\n@endnode\n@node ChildDoc6 "How to contact e!"\n\n  You can write a message to ''dARKWiNG'' at the following boards:\n\n  o  pRIMAL rAGE\n\n  ... and several more\n\n@endnode\n','\n',char(10)),NULL,NULL,9279,2,0,NULL,NULL,NULL,'scan',1780048498);
