INSERT INTO door_catalog VALUES('eall201','EALL201.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/EALL201.LHA',NULL,'XIM','LE-win5-96.exe','2.00',NULL,NULL,'-------------------------------------------- this file contains all required files and docs to run EALLs for the MASSES! Use this',replace('EALLs for the MASSES v2.00ß - complete pack\n--------------------------------------------\nthis file contains all required files and \ndocs to run EALLs for the MASSES! Use this\ntogether with your private registered ver-\nsion of the tool! rename it into EALL.x !!!\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                                                .------''\n             `-------