INSERT INTO door_catalog VALUES('ep_aep','EP_AEP.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/EP_AEP.LHA',NULL,'XIM','Account Editing Password o','1.',NULL,'EP',NULL,replace('Account Editing Password v1.o\n','\n',char(10)),'AEP.doc',replace('            Account Editing Password v1.o by WHiZ/ENDLESS PiR/\CY\n                     Psycho Terminal +1-2o3-698-o583\n\nThis Package Should Contain: \n----------------------------\n\n  EPUtils/AEP.Rexx - 1587 Bytes (Main File)\n  EPUtils/AEP.doc  - 1323 Bytes (Dox for this Util)\n  BBS.CMD            - 38 Bytes (How your BBS.CMD should look like)              \n\nInstallation:\n-------------\n\n  Create a directory in DOORS: called EPUtils and copy the file\n  AEP.Rexx into this directory. Then add this line to your\n  BBS:Commands/BBS.CMD :\n\n            *1        RM255DOORS:EPUtils/AEP.Rexx\n\n  Then load your favourite Text Editor and Edit AEP.Rexx to change\n  the password. Simple, eh?\n  \nWhat this little Util does:\n---------------------------\n\n  This Util is a Password Protection against the illegal use\n  of Account Editing. If someone tries to access Account \n  Editing without knowing the Password it''ll add a line to your\n  callerslog, informing you which user and at what time this\n  ''incident'' occured.\n\nBugs:\n-----\n\n  No known Bugs.\n\nHellos to:\n----------\n\n  F/\|)E\n  MR HYDE/CHRYSEiS\n  DYoNiSoS/CHRYSEiS\n  RiOTER/EQUiNoX\n  THE SiLENCER/EQUiNoX\n  POLARiS/RaZoR 1911\n  SCHWABENPOWER/RaZoR 1911\n  SoMeOnE/RaZoR 1911\n  ANF/ACCESS \n  CYCLONE/DUAL CREW\n  \n\n        *** Call Psycho Terminal for more AmiExpress Utils! ***\n','\n',char(10)),NULL,NULL,2768,2,0,NULL,NULL,NULL,'scan',1780048504);
INSERT INTO door_catalog VALUES('ep_sdp','EP_SDP.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/EP_SDP.LHA',NULL,'XIM','SySoP DoWnLoAd PaSsWoRd o','2.',NULL,'EP',NULL,replace('SySoP DoWnLoAd PaSsWoRd v2.o \n','\n',char(10)),'SDP.Doc',replace('              SySoP DoWnLoAd PaSsWoRd v2.o by WHiZ/ENDLESS PiR/\CY\n                     Psycho Terminal +1-203-698-0583\n\nThis Package Should Contain: \n----------------------------\n\n  EPUtils/SDP/SDP.Rexx        -   3034 Bytes (Main File)\n  EPUtils/SDP/Password.CFG    -   1013 Bytes (Edit this File!) \n  EPUtils/SDP.Doc             -   2196 Bytes (Docs to this Util)\n  EPUtils/BBS.CMD             -     42 Bytes               \n\nInstallation:\n-------------\n\n  Create a directory in DOORS: called "EPUtils" and move the\n  entire Directory "SDP" into the Dir "EPUtils". The next\n  step is, to edit the File EPUtils/SDP/Password.CFG with\n  your favourite Texteditor to change the Password.\n  But Remember: Not More than 12 Chars, or it won''t work!  \n  Finally add this line to your BBS:Commands/BBS.CMD File:\n\n         *DS       RM250DOORS:EPUtils/SDP/SDP.Rexx\n\nWhat this little Util does:\n---------------------------\n\n  This Utility protects your BBS from potential Hackers. Each User who\n  wants to use the ''DS'' command has to enter a Password, which you have\n  previously defined (Password.CFG) with your favourite Texteditor.\n  If he fails to enter the Password correctly he''ll be written down in\n  the Callerslog and disconnected immediately.\n\nBugs:\n-----\n\n  No known Bugs.\n\nCompatiblity:\n-------------\n  \n  This Utility should be compatible with /X v2.2+ and /X Beta.\n\nHistory:\n--------\n\n  v1.0  12-20-93  Internal Version. Programmed after two Hack Attempts.\n  v2.0  02-12-93  Release Version. Added new Features!\n\nGreetingz go out the following guyz:\n----------------------------------------\n \n  F/\|)E (alles banane?)\n  RIOTER/EQUINOX\n  THE SiLENCER/EQUINOX (Gr8 m8, full of h8? hehe)\n  SCHWABENPOWER/RAZOR 1911\n  Polaris & Spads/RAZOR 1911 (Merci pour la bonne assistance!)\n  SoMeOnE/RAZOR 1911 (Give me a call dude, I need to talk to ya!)\n  MuMu/TRACKERS (ich sag nur MEGAARC.LHA 5.4 Megs!)\n  UNTOUCHABLES/FISC (Thanx for Everything!)\n  Mr Hyde/CHRYSEiS (Sorry about your Baord!)\n  DYONISOS/CHRYSEIS (Keep Going!)\n  RiSK/TRiBE (As promised...)\n\n  and of course to all ENDLESS PiR/\CY Members WORLDWIDE!\n  \nFeel free to contact me on Psycho Terminal for suggestions and/or bugs.\n \nClick...\n','\n',char(10)),NULL,NULL,4364,2,0,NULL,NULL,NULL,'scan',1780048504);
