INSERT INTO door_catalog VALUES('eqx_lc10','EQX-LC10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/EQX-LC10.LHA','LhACheck','XIM','LhACheck',NULL,'WHiZ/eQX^rLX!','EQX','/ /__//  //\ /  //\ /\//  _/\ /  //\\ \/ / / / / / _// // _// // //\ // //  // //\ \/ \/ ¯¯\\/\¯\/ \/\¯_/ \/ \/// / \_/¯_/ \/\/\',replace(' ®/\___ /\__   /\_    /\ /\__   /\__ /\  /\\n / /__//  //\ /  //\ /\//  _/\ /  //\\ \/ /\n/ / / / _// // _// // //\ // //  // //\ \/\n\/ ¯¯\\/\¯\/ \/\¯_/ \/ \/// / \_/¯_/ \/\/\\n ¯¯¯¯¯   \/     ¯       ¯ \/    ¯¯      \/\n                  PRESENT:\n LhACheck v1.0 (100% ASM) by WHiZ/eQX^rLX!\n Very Fast LhA Checker, Stripper and Adder\nAds and Strips as many BBS Ad''s as you want\n','\n',char(10)),'LhACheck10.doc',replace('\n          _|___________________________________ ________________|_\n           |                                   Y                |\n           |/\_____________  /\________________  _______/\______|  _ _   _\n           /  \     \      \/  \ \   \   \     \/\      \ \ \   \ _ __) (_)\n          /   /\_____\______\  /\_\___\___\_____\ \______\/\_\___\ \n  _  __ _ \  /    ___/\___   \/   /   /_  /\__   \/      /_  /  _/\n (_)  __ _ \/    ___/    /   /   /   //  /   /  ./   /  /      ./\n           |\____  /______/\/\______/_  /___/  //\_____/___/_ //|\n           |   . \/     \/__\         \/  \/___/            .\/ |\n       [---|---|            pRESENT: LhACheck v1.0          |---|---]\n          _|____________________________________________________|_Sk!n\n           |                                                    |\n\n                  Copyright © 1994 by WHiZ/eQUiNOX^rEFLEX!\n                      PSYCHO TERMiNAL +1(914)682-1975\n\n\nSome Information about this Checker:\n------------------------------------\n\n  LhACheck is written in 100% Assembler, very small (2176 bytes)\n  and is of course Megafast! You can ad and strip as many BBS Ads\n  as you want and has a beautiful output!\n  \nHow to Install this Sucker:\n---------------------------\n\n 1. Copy the File LhACheck located in the archives C: dir to your\n    C: or whatever dir.\n\n 2. Copy the LHA.info Icon located in the BBS:FCheck/ dir, copy it to\n    your BBS:FCheck/ dir change the OPTIONS= Tooltype, so that your\n    Icon looks something like that:\n\n    CHECKER=C:LhACheck\n    OPTIONS=S:YOUR_ADS S:ADS_TO_STRIP             <- Change This Line\n    STACK=10000\n    PRIORITY=1\n    ERROR.1=Archive corrupted --aborting\n    ERROR.2=Operation not entirely successful\n\n  3. The File S:YOUR_ADS or whatever you name it should contain the full\n     paths to all your BBS Ad''s. If you don''t have one yet here''s how it\n     should look like:\n\n     ---/Cut/---\n     DH0:S/MYAD\n     DH1:TEXTS/CALLME!.ADD\n     ---/Cut/---\n\n   4. The File S:ADS_TO_STRIP or whatever you name it should contain all\n      the BBS AD''s you wanna strip, e.g.:\n\n      ---/Cut/---\n      *.displayme\n      [#?]\n      Call*\n      ---/Cut/---\n\n   If you are still unsure of how this Util works just type LhaCheck in\n   CLI and you''ll see the options.\n\n   That''ll do it...\n\nBugs:\n-----\n\n  No known Bugs so far. This Checker has been tested for 1.5 weeks\n  without any problems!\n\nKnown Compatibility:\n--------------------\n\n  Should work on any Amiga Model and Processor!\n\nHistory:\n--------\n\n  v1.0  04-06-94  Release Version\n\nGreetings fly out the following guys:\n-------------------------------------\n\n  The Schämp - Gibt''s dich noch?\n  THE SiLENCER/TDS^EQX - ARexx Sux :)\n  Halfast/SCX - Gimme a call mec!\n  Mr Hyde/TRY - Where are you?\n  The Fly/TRY - Thanx for the great support and help!\n  Freddy Krueger/GOD - Thanx for Testing! Sorry about the crashes :)\n  Franky/RLX - SYS64738\n  JOKER/ZZC - Ich hab momentan leider keine PBX...Sorry!\n  Dalai Lama/GOD - Sorry about your Board m8!\n  SchwabenPower/MTN - Sieht so aus als müßten wir wieder ein paar neue\n                      messys anfangen :)\n  Red Alert - Netmail Ruhlt!\n  Rioter/EQX - Thanx for the Help!\n  BBC/MTN - Wie war der Mini-Trip?\n  2-Cool/LSD - Thanx for being so patient with me!\n  g.E.m. - Vielen Dank Alter für deine Hilfe! Friendship Rulez!\n  Sid Vicious/bF - Ich will ein paar Pörnchen!\n  [«·cCs^eQx·»]/LGC - I really love your Doors!\n  Calypso/GOD - Ich call bald mal wieder an!\n  TerrOrizeR/RLX - Thanx for the great Support!\n  Dexter/aFL - Thanx for Beta-Testing. I''ll release MoDSaM very soon!\n  Foxx''n''Lynxx/ZZC - Danke für die Routine!\n  ErNeStO/RDC - Consolen-Pumpen Rulez!\n  Snow/LGC - Call mal wieder an!\n  JIVE - Ich sach nur: bAKK aFTER bUST!\n\n  and of course to all eQUiNOX, eNDLESS pIRACY & rEFLEX members worldwide!\n\n  Feel free to contact me on pSYCHO tERMINAL for suggestions and/or bugs!\n             Or get a hold on me via AmiXnet (WHiZ@203001).\n\n\n      _______/\ __________________ /\_______/\______________ ___________/\\n     /     ___//   ____________   \\______  \________  \    |    /   ____/\n  Mb/  ___/___/   / \   \/   / \   \|    |\  \|   _|/ _/\__ | __/  __/___\n  _/   \_    /    \_/    \   \_/    \    |/   \   \__  \  /   \/   \_/   \\n  \    _/    \           /          /          \   |/   \/     \_         \\n   \___\  ___|\_________/\_________/|__________/________/_______/_________/\n        \/                                                                \n\nClick...\n','\n',char(10)),'{"STACK":"10000","PRIORITY":"1"}','auto-added',6515,1,0,NULL,NULL,'eqx_lc10','scan',1780048504);
INSERT INTO door_catalog VALUES('eqx_si23','EQX-SI23.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/EQX-SI23.LHA','SysInfo','XIM','Avail',NULL,'WHiZ/eQX^rLX!','EQX','/ /__//  //\ /  //\ /\//  _/\ /  //\\ \/ / / / / / _// // _// // //\ // //  // //\ \/ \/ ¯¯\\/\¯\/ \/\¯_/ \/ \/// / \_/¯_/ \/\/\',replace(' ®/\___ /\__   /\_    /\ /\__   /\__ /\  /\\n / /__//  //\ /  //\ /\//  _/\ /  //\\ \/ /\n/ / / / _// // _// // //\ // //  // //\ \/\n\/ ¯¯\\/\¯\/ \/\¯_/ \/ \/// / \_/¯_/ \/\/\\n ¯¯¯¯¯   \/     ¯       ¯ \/    ¯¯      \/\n                  PRESENT:\n  SysInfo v2.3 (100% ASM) by WHiZ/eQX^rLX!\n  Ami-Express & S-Express Door to display\n     important Infos about your System.\n','\n',char(10)),'SysInfo23.doc',replace('\n          _|___________________________________ ________________|_\n           |                                   Y                |\n           |/\_____________  /\________________  _______/\______|  _ _   _\n           /  \     \      \/  \ \   \   \     \/\      \ \ \   \ _ __) (_)\n          /   /\_____\______\  /\_\___\___\_____\ \______\/\_\___\ \n  _  __ _ \  /    ___/\___   \/   /   /_  /\__   \/      /_  /  _/\n (_)  __ _ \/    ___/    /   /   /   //  /   /  ./   /  /      ./\n           |\____  /______/\/\______/_  /___/  //\_____/___/_ //|\n           |   . \/     \/__\         \/  \/___/            .\/ |\n       [---|---|             pRESENT: SysInfo v2.3          |---|---]\n          _|____________________________________________________|_Sk!n\n           |                                                    |\n\n                  Copyright © 1994 by WHiZ/eQUiNOX^rEFLEX!\n                      PSYCHO TERMiNAL +1(914)682-1975\n\n\nSome Information about this Tool:\n---------------------------------\n\n  Sysinfo is written in 100% Assembler and uses the AEDoor.Library\n  by Sintax/WOT. This Utility displays all important things about\n  your System, e.g. Total Amount of Memory, System Software you are\n  running, Which Volumes are available and stuff like that.\n  It has a beautiful output which every User loves :). Well, see\n  for yourself and decide...\n  \nHow to Install this Sucker:\n---------------------------\n\n 1. Move the EPUtils Directory included in this archive into your\n    DOORS: directory.\n\n 2. Edit the Tooltypes in the Sysinfo.info Icon which is located \n    in the DOORS:EPUtils/SysInfo/ Directory. \n    \n    Following Tooltypes can be found:\n\n    ACP_LOCATION=\n    EXP_LOCATION=\n    SHOW_VOLUMES=\n\n\n    ACP_LOCATION is the full path to your ACP Server, e.g.\n                   ACP_LOCATION=DH0:WBSTARTUP/ACP\n\n    EXP_LOCATION is the full path to your Express File, e.g.\n                   EXP_LOCATION=BBS:EXPRESS\n\n    SHOW_VOLUMES is the option to display all your Volumes:\n                 Hard Drives, Floppies, Ram Disk etc.\n                 To Enable this Function enter YES after\n                 this Tooltype (SHOW_VOLUMES=YES) or\n                 SHOW_VOLUMES=NO to disable it.\n  \n  3. Copy the AEDoor.Library found in the Archive into your LIBS:\n     Directory. Or Else ...\n\n  4. Now Copy the File BBS/Commands/BBSCmd/I.info to your\n     BBS:Commands/BBSCmd/ Directory or create a new one with the\n     following Tooltypes:\n\n     ACCESS=001\n     LOCATION=DOORS:EPUtils/SysInfo/SysInfo      <- Important\n     MULTINODE=NO\n     NAME=SysInfo v2.3                           <- Optional\n     PRIORITY=0\n     STACK=4096\n     TYPE=XIM\n\n     That''ll do it...\n\nBugs:\n-----\n\n  - No known Bugs so far. Mega-Thanx to Freddy Krueger for intensive\n    Beta-Testing this Tool.\n\nKnown Compatibility:\n--------------------\n\n  This Utility has been tested on /X v3.38.\n  It should work on /X v2.xx and S-Express by Sigma Seven!\n  Try it yourself and if not, please lemme know immediately!\n\nHistory:\n--------\n\n  v1.0+             Just For Fun\n  v2.0              Didn''t do very much, like a Status Door.\n  v2.1              New OutPut and New Options. Added an Icon as\n                    a Config File. \n  v2.2              Changed OutPut and made a lot of Bug Fixes.\n  v2.3              Couple of Bugs Fixed.\n\nGreetings fly out the following guys:\n-------------------------------------\n\n  The Schämp - Gibt''s dich noch?\n  THE SiLENCER/TDS^EQX - ARexx Sux :)\n  Halfast/SCX - Gimme a call mec!\n  Mr Hyde/TRY - Where are you?\n  The Fly/TRY - Thanx for the great support and help!\n  Freddy Krueger/GOD - Thanx for Testing! Sorry about the crashes :)\n  Franky/RLX - SYS64738\n  JOKER/ZZC - Ich hab momentan leider keine PBX...Sorry!\n  Dalai Lama/GOD - Sorry about your Board m8!\n  SchwabenPower/MTN - Sieht so aus als müßten wir wieder ein paar neue\n                      messys anfangen :)\n  Red Alert - Netmail Ruhlt!\n  Rioter/EQX - Thanx for the Help!\n  BBC/MTN - Wie war der Mini-Trip?\n  2-Cool/LSD - Thanx for being so patient with me!\n  g.E.m. - Vielen Dank Alter für deine Hilfe! Friendship Rulez!\n  Sid Vicious/bF - Ich will ein paar Pörnchen!\n  [«·cCs^eQx·»] - I really love your Doors!\n  Calypso/GOD - Ich call bald mal wieder an!\n  TerrOrizeR/RLX - Thanx for the great Support!\n  Dexter/aFL - Thanx for Beta-Testing. I''ll release ModSam very soon!\n  Foxx''n''Lynxx/ZZC - Danke für die Routine!\n  ErNeStO/RDC - Consolen-Pumpen Rulez!\n  Snow/LGC - Call mal wieder an!\n  JIVE - Ich sach nur: bAKK aFTER bUST!\n\n  and of course to all eQUiNOX, eNDLESS pIRACY & rEFLEX members worldwide!\n\n  Feel free to contact me on pSYCHO tERMINAL for suggestions and/or bugs!\n             Or get a hold on me via AmiXnet (WHiZ@203001).\n\n\n      _______/\ __________________ /\_______/\______________ ___________/\\n     /     ___//   ____________   \\______  \________  \    |    /   ____/\n  Mb/  ___/___/   / \   \/   / \   \|    |\  \|   _|/ _/\__ | __/  __/___\n  _/   \_    /    \_/    \   \_/    \    |/   \   \__  \  /   \/   \_/   \\n  \    _/    \           /          /          \   |/   \/     \_         \\n   \___\  ___|\_________/\_________/|__________/________/_______/_________/\n        \/                                                                \n\nClick...\n','\n',char(10)),'{"LOCATION":"DH0:WBSTARTUP/ACP","ACCESS":"001","PRIORITY":"0","STACK":"4096","TYPE":"XIM"}','auto-added',16915,1,0,NULL,NULL,'eqx_si23','scan',1780048504);
