INSERT INTO door_catalog VALUES('f123_doc','F123_DOC.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/F123_DOC.LHA',NULL,'XIM','Relyscully.exe',NULL,NULL,'F123','\_ __ __ _ ____ \ (__\\ | )\__/, FINAL AMIGA MAILBOX ENGINE --------------------------------------------',replace('___                        12-23-96 [03/03]\n\_ __ __ _ ____\n\ (__\\ | )\__/, FINAL AMIGA MAILBOX ENGINE\n--------------------------------------------\n  VERSIONS MP:1.23 SV:1.16 SE:1.18 FC:1.14\n--------------------------------------------\n NEW UPDATE OF THE MIGHTY FAME-BBS SYSTEM !\n  MANY NEW FEATURES AND USER SUGGESTIONS\n      INTEGRATED ! MANY BUGS FIXED !\n   SEE DOCUMENTATION FOR INFOS ABOUT HOW\n    TO REGISTER YOUR COPY OF FAME NOW !','\n',char(10)),'F123_DOC.readme',replace('Short:    FAME BBS-System V1.23 Demo Version.\nUploader: [email removed] (David Wettig)\nAuthor:   [email removed] (David Wettig)\nType:     comm/bbs\n\nFAME is a brand new Multi-Node BBS-System, which is currently under\ndevelopment. It supports the following main features:\n\n - Amiga style-guide conform programming and GUI\n - Configuration via one config program, no usage of icons or scripts\n - Runs as commodity, uses Kickstart V2.0+ functions only\n - No limitations on conferences, nodes or other BBS-related things\n   (Demo-version has an userlimit of 10 users and cannot be loaded resident)\n - Supports Hydra & the XPR standard\n - Configurable background file checking and posting\n - Own DoorPort with over 380 public commands\n - Full documentation and programmer examples in ASM & C included (SAS/C &\n   StormC, AsmOne & Devpac compatible)\n - Installation via Installer script; easy and fast installation\n - Many tools and doors included (FAMEFullEd,FAMEChat,etc.)\n\nAnd many many more, see supplied documentation for a complete list of\nfeatures this BBS distinguishes.\n','\n',char(10)),NULL,'auto-added',573321,5,0,NULL,NULL,'f123_doc','scan',1780048504);
INSERT INTO door_catalog VALUES('f123_ins','F123_INS.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/F123_INS.LHA','Server','XIM','FAMEDataPatcher',NULL,NULL,'F123','\_ __ __ _ ____ --- --- ------ - ---> \ (__\\ | )\__/      FAME Preview <- 2F -- -------  --- -- ----- - ----- ->',replace(' ___\n \_ __ __ _ ____ --- --- ------ - --->\n \ (__\\ | )\__/      FAME Preview\n<- 2F -- -------  --- -- ----- - ----- ->\n\n  <-=-> fINAL aMIGA mAILBOX eNGINE <-=->\n\n A picture preview of a new Mailbox Engine\n for you and your Amiga as a new standard\n      of Mailbox programs available.\n    Take a look! You won''t regret it!\n','\n',char(10)),'F123_INS.readme',replace('Short:    FAME BBS-System V1.23 Demo Version.\nUploader: [email removed] (David Wettig)\nAuthor:   [email removed] (David Wettig)\nType:     comm/bbs\n\nFAME is a brand new Multi-Node BBS-System, which is currently under\ndevelopment. It supports the following main features:\n\n - Amiga style-guide conform programming and GUI\n - Configuration via one config program, no usage of icons or scripts\n - Runs as commodity, uses Kickstart V2.0+ functions only\n - No limitations on conferences, nodes or other BBS-related things\n   (Demo-version has an userlimit of 10 users and cannot be loaded resident)\n - Supports Hydra & the XPR standard\n - Configurable background file checking and posting\n - Own DoorPort with over 380 public commands\n - Full documentation and programmer examples in ASM & C included (SAS/C &\n   StormC, AsmOne & Devpac compatible)\n - Installation via Installer script; easy and fast installation\n - Many tools and doors included (FAMEFullEd,FAMEChat,etc.)\n\nAnd many many more, see supplied documentation for a complete list of\nfeatures this BBS distinguishes.\n','\n',char(10)),NULL,'auto-added',571115,5,0,NULL,NULL,'f123_ins','scan',1780048504);
INSERT INTO door_catalog VALUES('f123_mai','F123_MAI.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/F123_MAI.LHA',NULL,'XIM','Relyscully.exe',NULL,NULL,'F123','\_ __ __ _ ____ \ (__\\ | )\__/, FINAL AMIGA MAILBOX ENGINE --------------------------------------------',replace('___                        12-23-96 [02/03]\n\_ __ __ _ ____\n\ (__\\ | )\__/, FINAL AMIGA MAILBOX ENGINE\n--------------------------------------------\n  VERSIONS MP:1.23 SV:1.16 SE:1.18 FC:1.14\n--------------------------------------------\n NEW UPDATE OF THE MIGHTY FAME-BBS SYSTEM !\n  MANY NEW FEATURES AND USER SUGGESTIONS\n      INTEGRATED ! MANY BUGS FIXED !\n   SEE DOCUMENTATION FOR INFOS ABOUT HOW\n    TO REGISTER YOUR COPY OF FAME NOW !','\n',char(10)),'Ringelblume4.txt',replace('                 \n                                  ·     ·\n                               _ __\   /__ _\n                            _ _)\\  \ /  //(_ _\n                           -\   __\° X °/__   /-\n                    _ __ ___ ___)  \/_\/  (___ ___ __ _\n                   -\\\_\\__\\__  _ /¦\ _  __//__//_///-\n             ·         _.      \__)_¯_¯_(__/      ._         ·\n           _/          \|_       | | | | |       _|/          \_\n         __\ ___ _/\____\/__ __ _| | | | |_ __ __\/____/\_ ___ /__\n       _/   \  (_)  \   \/  /_/\\| |_|_| |//\_\  \/   /  (_)  /   \_\n       |                    \_\/ | | | | | \/_/                    |\n      _|                      __ | | | | | __                   _ _|_\n      \|_ _                   \/_| | | | |_\/                      |/\n       |                     · _)  ¯_¯_¯  (_ ·                     |\n       |  ·H2o!·              \\___ \ / ___//                      |\n       ¯\_______________________ _)  Y  (_ _______________________/¯\n                                 \___ ___/\n                                    (_)\n ','\n',char(10)),NULL,'auto-added',737267,5,0,NULL,NULL,'f123_mai','scan',1780048504);
