INSERT INTO door_catalog VALUES('fafcst20','FAFCST20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/FAFCST20.LHA','ChatStarter','XIM','FAFCST20.LHA ChatStarter',NULL,NULL,NULL,'__/                                      ¦ \     ____________/\  _______________:   | \_     |           \/           |   ¦   |',replace('   ______________________________________.  \012__/                                      ¦  \012\     ____________/\  _______________:   |  \012 \_     |           \/           |   ¦   |  \012  |   __|  + FrOnTaL aCtIvItY +  |       |  \012  |   |      ¯¯¯¯¯¯¯ ¯¯¯¯¯¯¯¯    |   |   |  \012  |   |      pRoUdLy pReSeNtS    |   |   |  \012  |   |_    aNoThEr LiGhTsPeeD   |___|   |  \012  |rS  / -------------------------- \   _|  \012  |___FrOnTaLChAt StArTeR v2.0 foR AmiX_|bY \012Usefull for BBS with 2 or more Sysops! /X\nC\012','\012',char(10)),'ChAtStArTeR.GUIDE',replace('@database 003dc258-0\012@master DOORS:Front-Act/ChAtStArTeR.GUIDE\012@$VER: 2.0\012@author "MaNiAc / FrOnTaL AcTiViTy"\012@(c) "1994"\012@index Main\012@remark Created with Heddley v1.1 (c) Edd Dumbill 1994\012\012@node "Main" "FrOnTaL ChAt StaRtEr GuIdE"\012 \012                      FrOnTaL ChAt StArTeR v2.0 ©1994\012\012                     @{b}@{fg shine}@{bg shadow}DoNe bY MaNiAC / FrOnTaL AcTiViTy@{ub}@{fg text}@{bg back}\012 @{fg shine}           .      .                                  .      .   \012        .     .         .                         .     .         . @{fg text}\012 @{fg shine}    .       .       .     .@{"  Introduction   " alink "Introduction" 0}     .       .       .     .\012          . .    .     .    @{"  Requirements   " alink "Req" 0}       . .    .     .\012  .      .     .  .       . @{"  Instalation    " alink "Install" 0}     .     .  . .\012      .     .      .   .    @{"    Credits      " alink "credz" 0}    .   .\012              .           . @{"How to Contact Us" alink "add1" 0} .\012 .      .          .          . .      .    .      .          .          .\012           .  .  .    .   .          .       .  .  .      .        .\012    .              .            .         .            .              .\012            .         .    ReLeased In 12-DeC-94  .        .     .\012 .   .    .      ..            .   .    .    .        .      ..         .\012@endnode\012\012@node "Introduction" "!> InTrOduCtIoN <!"\012@prev "Main"\012    Frontal Chat Starter is a XIM Door Done in PASCAL that allows the sysops\012to choose in a maximum of 4 sysops when a user asks for chat.\012    The Door will print a table with the sysop''s name in question,etc...\012  The Table looks Like this :\012 \012  .-----------------------------------------------------------------------.\012  |     FrOnT ChAT StaRtEr v2.0 - DoNe By MaNiAC / FrOnTaL AcTiViTy       |\012  |-----------------------------------------------------------------------|\012  | Hi Maniac. The Sysop that`s is talking with you is Martin             |\012  |-----------------------------------------------------------------------|\012  |  CuRReNt TiMe : 17h42m |  TiMe ReMaInInG :   86 MiNs |  BaUd : 21600  |\012  ·-----------------------------------------------------------------------·\012 \012    This is very usefull when the sysops of a bbs are brothers and one  of\012the them starts a chat doesn''t need to say " Hello I''m (SYSOP''S NAME)".\012    Per example if the BBS is installed in a school or in a company and\012there are many sysops who have shedules to stay in the computer. \012                 \012                                                              /X\nC\012@endnode\012\012@node "Req" "Requirements"\012@prev "Main"\012    To Use this NiCe Door you must have a v2.x to v4.x of The AmiExpress\012software And an AMIGA 500,500+,600,1200,1500,2000,3000,4000,CD32.\012    The @{"Instalation" alink "Install" 0} is VERY easy!!...\012\012                                                            /X\nC\012@endnode\012\012@node "Install" "Installation"\012@prev "Main"\012    To install this CooL door you have to :\012\012      - Create a Directory in your DOORS: called FronT-AcT\012\012          -----Cut here-------------------\012           Cd DOORS:\012           Makedir FronT-Act\012          -----Cut here-------------------\012\012      - Copy the ChaTStarter file to the directory you have created.\012\012      - Copy the CHATSTART.info to BBS:COMMANDS/BBSCMD/\012\012      - Edit the startchat.txt located in the node{x} directory.\012\012          E.g.\012\012            ~CC_CHATSTART \012\012      - Edit Names.List and write there your names.\012\012    Ok, i think that''s all. Enjoy your self.\012@endnode\012\012@node "credz" "Credits"\012@next "Main"\012@prev "Main"\012    And Finally the creditz go to :\012\012     - Martin/fA ( My brother - Fucking Good Programmer )\012\012     - Bruce Lee/fA ( Who gave me this Idea )\012\012     - The Hawk/fA ( Our best trader )\012\012     - Boomerang/fA ( Where is my BooK !!?!?! ehehehe ) \012\012     - RattleSnake/fA ( Ok! Now you have a new Modem )\012\012     - Communicator/SiGMA7 ( Hurry Up with those 3 nodes )\012\012     - Lupa, MAdDog And Thunder/fA ( When do you come to Lisbon?? )\012\012     - Dr.Kaos And Stolen Alias/fA ( Thanks for the great ascii''s! ) \012\012     - And all others Around the World that i''ve not mencioned.\012@endnode\012\012@node "add1" "How to Contact Us"\012@prev "Main"\012                                                                          .\012                                                                          :\012                                                             .            |\012          ___________  /\  . _________/\___________________  |    :       |\012          \_______   \/  \/|/   _____/  \___    ____/      \ |    |       |\012            |    |    \    |   (__ \/     ||    | /    l    \|    |_      |\012          __|    |     \_  |        \__   ||    |/           \    | \__   |\012          \_____________/__|__________/___||    |\_____|      \_______/   |\012                             |    :      |________/                       |\012                                  .                                       |\012                                                                          |\012                    __    _____             _________          _____      |\012  ___________   ___|  \  /     \  _________/        /_______  /     \     |\012  \_______   \ /   |   \/   _   \/   _____/  ______/   _    \/   _   \    |\012    |    |    /    |    \   |    \  (__ \   ____)_/    |     \   |    \   |\012  __|    |    \    l     \_ |     \      X_      ¬\_   |      \_ |     \  |\012  \___________/\__________/_|      \______/________/___________/_|      \ |\012                            |______/WhQ                     [/X\]|______/ |\012\012                                                                          |\012                                                                          |\012            · ------------------------------------------------------------+-- -\012                                                                          |\012                                                                          :\012   AmiExpress 4.7 <*> Amiga 1200 + MC68882/33MHz + 4MeGs RAM <*> 420Mb HD .\012   ~~~~~~~~~~~~~~     ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~     ~~~~~~~~\012 NODE0: (!) ELiTE ONlY (!)\012 NODE1: USRobotics COURiER HST DS TeRbO 21.6k <*> PhOnE: ++351-(0)1-9572361\012\012 - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\012\012   Other FrontaL AcTiViTy BBSes: \012\012      _         _______  _______  ________\012     ::|       ::::::::|::::::::|:::::::::|\012     ::|       ::|   ::|::|    :||  ::|  :|                        \012     ::|       ::|___::|::|_____ ''  ::|   ''\012     ::|       ::::::::|::::::::|   ::|    _  _______  _______  _______\012     ::|       ::|   ::|      ::|   ::|   ::|::::::::|::::::::|::::::::|\012     ::|_____:|::|   ::|:_____::|   ::|   ::|::|   ::|::|   ::|::|    :|\012     :::::::::|::|   ::|::::::::|   ::|___::|::|   ::|::|___::|::|_____ \012                                    ::::::::|::|   ::|::::::::|::::::::|\012      SySoP: Bruce Lee              ::|   ::|::|   ::|::|      ::|      \012                                    ::|   ::|::|___::|::|      ::|    :|\012      CoSysOps: Communicator        ::|   ::|::::::::|::|      ::::::::|\012                RattleSnake\012                                           All Fucking Day/Week\012\012          PHoNE : ++351-1-9343223 /  PHQ                 28.8k  ZOOM ENGINE    \012      \012 - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -  \012\012      AND " YOUNG GODS " PHoNE : ++351-1-4581703 PhQ    SysOp: Boomerang\012       \012                           24 hours/day aT 28.8k\012\012 - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\012@endnode\012\012','\012',char(10)),NULL,'XIM-BBSCmd',13189,4,0,NULL,NULL,'fafcst20_chatstarter','scan',1780048504);
INSERT INTO door_catalog VALUES('fame6411','FAME6411.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/FAME6411.LHA',NULL,'XIM','friendsonly.exe',NULL,NULL,NULL,'\_ __ __ _ ____ \ (__\\ | )\__/, tRSi/F-Innovation FAME Text --------------------------------------------',replace('___                                13-Jun-98\n\_ __ __ _ ____\n\ (__\\ | )\__/, tRSi/F-Innovation FAME Text\n--------------------------------------------\n         FAME64.txt v1.1 - updated\n ------------------------------------------\n  All needed informations about the 64 bit\nsupport in FAME v1.30 which will be used for\nupload and download bytes to have a maximum\n space of 18.446.744.073.709.551.615 bytes\n  (more than 18 trillion bytes) available.\nThis text is especially written for tool and\n door coders to support the 64 bit feature.\n--------------------------------------------\n','\n',char(10)),'FAME6411.readme',replace('Short:    How to support 64 bit variables in FAME.\nUploader: [email removed] (David Wettig)\nAuthor:   [email removed] (David Wettig)\nType:     comm/bbs\n\nFAME64.txt v1.1 - updated.\n\nAll needed informations about the 64 bit support in FAME v1.30 which\nwill be used for upload and download bytes to have a maximum space\nof 18.446.744.073.709.551.615 bytes (more than 18 trillion bytes)\navailable. This text is especially written for tool and door coders\nto support the 64 bit feature. There will be everything explained\nyou need to know to write your own tools supporting 64 bit variables\nby using FAME.library 6.0 functions. FAME.library 6.0 supports\neverything you need like 64 bit addition, substraction, multiply,\ndivide and comparison functions. Every function is explained inside\nthis text with additional example usage source.\n','\n',char(10)),NULL,'auto-added',12013,1,0,NULL,NULL,'fame6411','scan',1780048504);
INSERT INTO door_catalog VALUES('famebus1','FAMEBUS1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/FAMEBUS1.LHA',NULL,'XIM','friendsonly.exe',NULL,NULL,NULL,'\_ __ __ _ ____ --- --- ------ - ---> \ (__\\ | )\__/  FAMEBackUpScripts 1.0 <- 2F -- -------  --- -- ----- - ----- ->',replace(' ___\n \_ __ __ _ ____ --- --- ------ - --->\n \ (__\\ | )\__/  FAMEBackUpScripts 1.0\n<- 2F -- -------  --- -- ----- - ----- ->\n\n <-=-> fINAL aMIGA mAILBOX eNGINE <-=->\n\n  FAMEBackUpScripts for easy FAME data\n  file backup like settings and users.\n','\n',char(10)),'FAMEBackUpScripts.readme',replace('\n                             FAMEBackUpScripts 1.0\n                             ---------------------\n\nFAMEBackUpScripts are scripts which will help you to backup important\nFAME data files like settings and user datas.\n\nThis release includes the following three backup scripts:\n\nFAMEBackUpConfDatas (1.437 bytes)\nFAMEBackUpSettings  (1.588 bytes)\nFAMEBackUpUserDatas (1.845 bytes)\n\nThose three scripts above are so called slave or child/sub scripts and have\nto be called by the following master script:\n\nFAMEBackUpLauncher  (4.341 bytes)\n\nThe master script (launcher) generates in FAME:BackUp/ a new subdirectory\nwhich is named like the current date in DD-MMM-YY form and then calls\nthe child script with exactly this date as argument.\n\nFAMEBackUpLauncher itself will be called with the child script as argument.\n\nExample calls:\n\nFAMEBackUpLauncher FAMEBackUpConfDatas\nFAMEBackUpLauncher FAMEBackUpSettings\nFAMEBackUpLauncher FAMEBackUpUserDatas\n\nNote: If your extractor tool has removed the script bits you can set them by \n      typing or snaping the following lines in a shell if you are in the \n      directory where the scripts are copied to:\n\nProtect FAMEBackUpLauncher +s\nProtect FAMEBackUpConfDatas +s\nProtect FAMEBackUpSettings +s\nProtect FAMEBackUpUserDatas +s\n\nThis is not important for the subscript call, because FAMEBackUpLauncher\ndoes call it by using "Execute", but it''s more easy for you especially\nthe FAMEBackUpLauncher script should be get the script bit set.\n\nThe three example child scripts are doing the following:\n\nFAMEBackUpConfDatas - Is backing up your\n                      FAME:Settings/Access/Conferences/<whatever>.dat files.\n\n                      This script was my main reason to create the backup\n                      scripts, because i tested the new FAME SystemEditor\n                      2.0 feature of reordering and reorganisating all\n                      changes of your Conferences in their new positions\n                      where the access settings will be updated automatically\n                      too. I needed a way to backup my current BBS settings\n                      which will be changed by testing out the new functions\n                      of FAME SystemEditor 2.0 ;)\n\nFAMEBackUpSettings  - Is the more advanced backup script which is backing up\n                      all FAME settings not only the access settings like\n                      above except the user datas.\n                      In particulary it is backing up the following:\n\n                      - FAME:Settings/#? (all settings including subdirectories\n                                         and their files)\n\n                      - FAME:Modules/#?.dat (all settings with .dat extension)\n\n                      - FAME:Modules/CoProcessConfig/#? (all settings including\n                                                        subdirectories and\n                                                        their files)\n\n                      - FAME:ExternEnv/#? (all settings including\n                                          subdirectories and their files)\n\nFAMEBackUpUserDatas - Is backing up your user.data and user.keys files.\n                      It also will backup all UserCnf.data files of your\n                      Conferences if you modify this script to your needs\n                      by adding the paths of your Conferences like explained\n                      and showed in example.\n\nThat''s all.\n\nFeel free to modify these scripts to your needs. And feel free to write new\nsubscripts (childs) and release them to the public if they are not to specific\nto your BBS, but don''t bet too much on these script thing, because it will\nnot directly become invalid, but with FAME 2.0 it will exist a new and better\nalternative and then the scripts are no longer needed, but ok if you want to\nuse them also with FAME 2.0.\n\nA request to all coders:\n\nIn FAME 2.0 the new feature of time sheduled co-processes the FAMECoProcess\nfeature exists. A specially for this feature written tool will take over the\ncomplete backup thing and this after setting up once totally automatical.\n\nI have not the time to write such a backup tool yet, so i ask you if there\nis someone who is interrested in writing such a FAMECoProc featuring backup\ntool. First it can be written without the FAMECoProc feature which can be\nadded later, because it''s a simple combination of FAMECoProc.library calls.\nBut if someone wants to code this tool directly with the FAMECoProc feature\nfrom the beginning it''s also no problem, because i then will handle to the\none who will programm this tool a FAME 2.0 alpha version which completely\nworks with the FAMECoProc feature and all needed stuff like the new\nadditional libraries.\n\nFor the backup tool it would be great if it''s not simply fixed to default\nbackup action it is currently knowing off. It should have the possibility\nto externally enhance the tool via scripts.\n\nThis will be very easy. The backup tool first creates the subdirectory\nof the current date and then does it''s own build in and enabled backup\nstuff and then at the end it calls the additional scripts which can be fully\ncompatible to the three child scripts above, because the tool need to start\nfor example such a script with the date of the created directory as argument.\n\nThe subscript then can do the rest of the special and additional backup stuff.\n\nFor easy use it''s the best if the backup tool executes a special directory\nwhere all the subscripts are copied too before, by using the FAME.library\nfunction ''FAMEExecuteDir''.\n\nThe backup tool itself should internally support by default the backup stuff\nthe example subscripts above are doing except the ones of the\nFAMEBackUpConfDatas script which is too specific. And for all it should be\nallowed to be enable and disable them any time by the SysOp.\n\nSo if you are interrested in doing this tool then please contact me by writing\nan e-mail to [email removed] or better into the FAME mailing list so that\neveryone is able to see who is interested in doing this.\n\nYou then if i gave the ok will get all stuff and more informations and help\nyou will need.\n\nIf you need to know more informations or just to come in contact with us\nyou can reach the FAME Development Team at:\n\n   ______ __ __ _____ __ _____ __ __ ________ _____ _____ __\n _ )  ._ Y_ | _Y     Y__Y_   _Y  | _Y       _Y   __Y    _Y  l_\n  \_  |/  / | \_  |  |   / `-\_    \_  |  | \_  _/\_  | \_  _/_\n   |   __/  |  |  |  |  /--,  |  |  |  |  |  |  l  |  |  |  l  |\n   l__|  l_____l__|  l_/l__   l__|  l__|  |  l__   l__|  l__   |\n       2F         `--''     `--''  `--''  `--l__|  `--''  `--''  `--''\n                            _______\n                            |\  /\__, .\n\n                       A4ooo/o4o aT 4oMHZ\n                         sYSTEM-cHIEFS:\n                    14mB rAM/1.6gB HD-sPACE\n                      SieGeL/tRSi & aRGON\n· (tRSi/F/X/T-iNNOVATiON) WHQ & bETA sITE! · fAME sUPPORT BBS ·\n    ! sUPPORTING pD and sHAREWARE oNLY oN aMIGA aND IBM-PC !\n               cALL #0: +49(0)30 614 25 51 (v.34)\n\nYou can also have a look at our WWW pages:\n\n                   www.trsi.de/inno/\n                   www.trsi.de/inno/strider/index.html\n                   www.trsi.de/inno/siegel/index.html\n\nOr contact us under:\n\n             [email removed] - ICQ: 7225710 - Team AMIGA -\n              [email removed] - ICQ: 9691810 - Team AMIGA -\n\n<EOF>\n','\n',char(10)),NULL,'auto-added',10127,1,0,NULL,NULL,'famebus1','scan',1780048504);
INSERT INTO door_catalog VALUES('famedemo','FAMEDEMO.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/FAMEDEMO.LHA','Server','XIM','FAMEDataPatcher',NULL,NULL,NULL,'\_ __ __ _ ____ \ (__\\ | )\__/, FINAL AMIGA MAILBOX ENGINE --------------------------------------------',replace('___                                 03-26-96\n\_ __ __ _ ____\n\ (__\\ | )\__/, FINAL AMIGA MAILBOX ENGINE\n--------------------------------------------\n FULLY FEATURED DEMO-VERSION OF A NEW AMIGA\n BBS-SYSTEM, GADTOOLS DRIVEN, COMPLETE LIST\n     OF FEATURES CAN BE FOUND INSIDE !\n DEMO HAS NO LIMITATIONS EXCEPT AN USERLIMIT\n    OF 10 USERS. COMPLETE ASM & C SUPPORT\n    FOR DOORPROGRAMMING IS ALSO INCLUDED!\n    SEE DOCUMENTATION FOR INFOS ABOUT HOW\n     TO REGISTER YOUR COPY OF FAME NOW !','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''             