INSERT INTO door_catalog VALUES('famel400','FAMEL400.LZX','~/Code/amiexpress_doors/Archives/AmiExpress/FAMEL400.LZX',NULL,'XIM','famel400',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,19386,0,0,NULL,NULL,NULL,'scan',1780048504);
INSERT INTO door_catalog VALUES('famemm10','FAMEMM10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/FAMEMM10.LHA','FAMEMsgScanModify','XIM','FAMEMsgScanModify',NULL,NULL,NULL,'\_ __ __ _ ____ --- --- ------ - ---> \ (__\\ | )\__/ FAMEMsgScanModify v1.0 <- 2F -- -------  --- -- ----- - ----- ->',replace(' ___\n \_ __ __ _ ____ --- --- ------ - --->\n \ (__\\ | )\__/ FAMEMsgScanModify v1.0\n<- 2F -- -------  --- -- ----- - ----- ->\n\n  <-=-> fINAL aMIGA mAILBOX eNGINE <-=->\n\n FAMEMsgScanModify allows you to modify\nMessage Base scan pointers of your users.\n','\n',char(10)),'FAMEMM10.readme',replace('Short:    Modify FAME Message Base scan pointers.\nUploader: [email removed] (David Wettig)\nAuthor:   [email removed] (David Wettig)\nType:     comm/bbs\n\nFAMEMsgScanModify v1.0\n\nFAMEMsgScanModify allows you to modify the Message Base scan pointers\nof your users. You can set the scan pointers to a position of your\nchoice also to 0 to reset them completely.\n\nYou can modify them in a specific Conference or in all Conferences\nin one go. The same for your Users. You can modify a specific User\nentry or all User entries of one/all Conferences in one go.\n\n--------------------------------------------------------------------\nDavid Wettig - FAME Innovation      ______  ____ :____  ________ tGø\nTeam AMIGA - CUCUG - ICOA member    \  __/_/    \|    \/   /  _/___\nICQ...: 7225710                     |    _//     \    \/  /  _|   /\nE-Mail: [email removed] |____|________\___/  /|_______\\nURL...: http://www.trsi.de/inno/strider/index.html   /___\ Developer\n--------------------------------------------------------------------\n','\n',char(10)),NULL,'auto-added',14218,6,0,NULL,NULL,'famemm10','scan',1780048504);
INSERT INTO door_catalog VALUES('famerc11','FAMERC11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/FAMERC11.LHA','FAMERemoteControl','XIM','FAMERemoteControl',NULL,NULL,NULL,'\_ __ __ _ ____ --- --- ------ - ---> \ (__\\ | )\__/  FAMERemoteControl v1.1 <- 2F -- -------  --- -- ----- - ----- ->',replace(' ___\n \_ __ __ _ ____ --- --- ------ - --->\n \ (__\\ | )\__/  FAMERemoteControl v1.1\n<- 2F -- -------  --- -- ----- - ----- ->\n\n  <-=-> fINAL aMIGA mAILBOX eNGINE <-=->\n\n FAMERemoteControl to remote control FAME\n         Nodes from CLI (Scripts).\n','\n',char(10)),'since`92.doc',replace('                 \n                                  ·     ·\n                               _ __\   /__ _\n                            _ _)\\  \ /  //(_ _\n                           -\   __\° X °/__   /-\n                    _ __ ___ ___)  \/_\/  (___ ___ __ _\n                   -\\\_\\__\\__  _ /¦\ _  __//__//_///-\n             ·         _.      \__)_¯_¯_(__/      ._         ·\n           _/          \|_       | | | | |       _|/          \_\n         __\ ___ _/\____\/__ __ _| | | | |_ __ __\/____/\_ ___ /__\n       _/   \  (_)  \   \/  /_/\\| |_|_| |//\_\  \/   /  (_)  /   \_\n       |                    \_\/ | | | | | \/_/                    |\n      _|      ?? WHO...       __ | | | | | __    ...KNOWS ??    _ _|_\n      \|_ _                   \/_| | | | |_\/                      |/\n       |                     · _)  ¯_¯_¯  (_ ·                     |\n       |  ·H2o!·              \\___ \ / ___//                      |\n       ¯\_______________________ _)  Y  (_ _______________________/¯\n                                 \___ ___/\n                                    (_)\n ','\n',char(10)),NULL,'auto-added',11561,5,0,NULL,NULL,'famerc11','scan',1780048504);
INSERT INTO door_catalog VALUES('fatecmnt','FATECMNT.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/FATECMNT.LHA',NULL,'XIM','________    ______   ______  __',NULL,NULL,NULL,'+/_  / .  )/\/ __/ /--/ __/\ \/ /----------+ | / /    </ / __/ (__/ ___>_)  (CNEt DEZiGN| +-\/\_/\_/\/\/  \___/\_____/_/\_\----------+',replace('  ________    ______   ______  __\n+/_  / .  )/\/ __/ /--/ __/\ \/ /----------+\n| / /    </ / __/ (__/ ___>_)  (CNEt DEZiGN|\n+-\/\_/\_/\/\/  \___/\_____/_/\_\----------+\n|        FateComment v1.0(11.2.1994)       |\n|Allows the User 2 send Feedback 2 multiple|\n|  Users (CoSysops etc.)...no Features :)  |\n+-=[Fate]=---------------------=[Triflex]=-+\n','\n',char(10)),'FateComment.guide',replace('@database "FateComment AmigaGuide Documentation"\n@$VER: FateComment.guide V1.0\n@node Main "FateComment Guide - Filesize: 7130"\n\n                        From the FateTools Series:\n\n                            -=[ FateComment ]=-\n\n                        V1.0 Beta (11 Jan 94 17h00)\n              Copyright (C)1994 by Fate - All Rights reserved\n\n                  A Replacement for the Feedback Function\n                Users can send Comments to multiple Persons\n\n                       @{" 1.              Legal Things " link 1}\n                       @{" 2.                  Contents " link 2}\n                       @{" 3.              Introduction " link 3}\n                       @{" 4.                  Features " link 4}\n                       @{" 5.              Installation " link 5}\n                       @{" 6.             Configuration " link 6}\n                       @{" 7.                     Usage " link 7}\n                       @{" 8.          History & Future " link 8}\n                       @{" 9.         Contacts & Greets " link 9}\n@endnode\n@node 1 "FateComment Guide - Legal Things"\n\n                                Copyright\n                                =========\n\nThe FateComment Package is Copyright (C)1994 by Fate. All Rights reserved.\n\n                               Disclaimer\n                               ==========\n\nThe  FateComment  Package  is provided "AS IS".  Usage is at your own Risk.\nThe Author can''t be made responsible for any Damage or Loss of Data, caused\ndirectly  or  indirectly  by  the  Program.   However, the Program has been\ntested and it seems to work stable...\n\n                                 Licence\n                                 =======\n\nFateComment  is  Freeware.   You may use it as you want, also on commercial\nSystems.   Modifying and/or renaming ANY File except for the Configuration-\nfile without the written Permission of the Author is STRICTLY forbidden !!!\n\n                               Distribution\n                               ============\n\nYou  are  allowed  to distribute FateComment on COST-FREE Medias avaible to\nCNet  Sysops  ONLY.   You  are  not  allowed  to  gain  any Profit with it.\nFurthermore  you are NOT allowed to sell, lend, rent, present or distribute\nit  through  Public Domain Channels or on Disc Magazines.\n@endnode\n@node 2 "FateComment Guide - Contents"\n\nThis Archive should contain the following Files:\n\nFateComment                            FateComment.cfg\nFateComment.guide                      FateComment.pic\nFILE_ID.DIZ\n\nIf  a  File misses, kick the Uploader or get the complete Archive from\none  of  the  Boards listed in @{"Contacts & Greets" link 9}.  I haven''t found out\nyet how to send it using NetMail...\n@endnode\n@node 3 "FateComment Guide - Introduction"\n\nAnother  Day,  another  Tool...   FateComment  is  a Replacement for CNet''s\ninternal  Feedback  Function.   Its  main  Advantage  is  that you can send\nFeedback  to  multiple Persons, e.g.  CoSysops and SubOps.  Furthermore you\ndon''t  need  to  specify  a  Reason anymore, but the Message comes into the\nReceiver''s  Mailbox. And it looks nice (Have a Look at "FateComment.pic") :)\n@endnode\n@node 4 "FateComment Guide - Features"\n\n+ You can send Comment(s) to multiple Person(s) (Sysop definable)\n+ No Need to specify a Reason (we''re sooo lazy :)\n+ If you want, have a Look at "FateComment.pic" !\n+ Short, compact, optimized Code\n@endnode\n@node 5 "FateComment Guide - Installation"\n\nIf  you  don''t  have  it  yet,  create  a Directory in "PFiles:" named\n"FateTools".  Copy "FateComment" and "FateComment.cfg" into it.\n\nStart  your favourite Text Editor and load "CNet:BBSMenu".  Go to Section 2\n("Avaible  everywhere") and to Line "Feedback".  Place any Char in Front of\nthe  F,  e.g.   a "\".  So the old Feedback Function will still be avaible.\nThen go to the End of the Section and add the following Line:\n\n     Feedback |<CTRL-Q>#0PFiles:FateTools/FateComment}\n\nPlease go on to @{"Configuration" link 6} immediately !!!\n@endnode\n@node 6 "FateComment Guide - Configuration"\n\nTo  configure load "PFiles:FateTools/FateComment.cfg" into the Editor.\nHere''s the Explanation of the different Lines:\n\nLine 1 : Lines the Users have for their Comments\nLine 2 : Account Number the Sysop has. I don''t think you need to\n         change it :)\nLine 3 : Name of the Sysop it. Modify it!\nLine 4 : A Banner of max. 50 Chars which will be displayed behind\n         the Sysop''s Name. No, this is NOT the Who Banner !!!\n\nAdd  for every User who should be reachable through FateComment 3 more\nLines  with  the  same  Format as Lines 2 to 4.  You can add nearly as\nmany Users as you want.  The Number is only limited by ARexx.\n\nExample Configfile:\n[---/cut here/---/cut here/---/cut here/---/cut here/---/cut here/---]\n100\n1\nSysop\nI''m your Sysop :)\n3\nCosysop\nI''m your CoSysop :)\n[---/cut here/---/cut here/---/cut here/---/cut here/---/cut here/---]\n\nThis  Configfile  would allow your Users to leave max.  100 Lines with\nComments to either Sysop, who has Account #1 (...) and whose Banner is\n"I''m your Sysop :)" or to CoSysop, who has Account #3 and whose Banner\nis "I''m your CoSysop :)".\n\nIt shouldn''t be that difficult to understand.\n@endnode\n@node 7 "FateComment Guide - Usage"\n\nWell, Usage should be self-explainatory. However... FateComment may fail to\nsend the Comment if:\n- the Receiver''s Mailbox is closed\n- the Receiver''s Mailbox is full\n- the Receiver doesn''t exist\n- I/O Problems\n\nSorry, no detailed Report yet :(\n@endnode\n@node 8 "FateComment Guide - History & Future"\n\n                         The Program''s History...\n\nV1.0 11 February 1994    First Release.\n\n                         Planned for the Future...\n\n- Random Banners\n- Extended Diagnozing of Errors if sending the Comment fails\n\nI''ve open ears for your Suggestions and Comments !!!\n@endnode\n@node 9 "FateComment Guide - Contacts & Greets"\n\n       For Bug Report, Comments, Suggestions, Wishes, Help, Chats or\n              whatever you can contact me at these Boards...\n\n                         ««« Digital Dungeons »»»\n                      (Triflex European Headquarter)\n                           ++49-6192-910718 2400\n\n                         ««« Spiritual Reality »»»\n                      (Backlash European Headquarter)\n                           ++49-6103-55001 DUAL\n           Your Masters are Marky, Power, Sir Hawk and Akira !!!\n\n                          ««« Nuclear Fusion »»»\n                           ++49-6192-46894 DUAL\n                   Your Masters are X-Ray and Atomic !!!\n\n                            Or send NetMail...\n\n                  Inter/UseNet: [email removed]\n                             AmNet: FATE;CHAOS\n                          Z-Netz: [email removed]\n                   Fido and AmigaNet are not avaible yet\n\n              And now some personal Greets in no Order to...\n\n              Red Hawk, Shodan, X-Ray, Atomic, Marky, Power,\n                Cyclone, Joe Cool, Einstein and Dotoran !!!\n\n                         This is nearly the End...\n                       C U at my next Productions...\n                               -=[ Fate ]=-\n@endnode\n','\n',char(10)),NULL,NULL,9007,1,0,NULL,NULL,NULL,'scan',1780048504);
INSERT INTO door_catalog VALUES('fatedz11','FATEDZ11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/FATEDZ11.LHA','DMSDescript','XIM','APE',NULL,NULL,NULL,'+/_  / .  )/\/ __/ /--/ __/\ \/ /----------+ | / /    </ / __/ (__/ ___>_)  (CNEt''S N0.1| +-\/\_/\_/\/\/  \___/\_____/_/\_\----------+',replace('  ________    ______   ______  __\n+/_  / .  )/\/ __/ /--/ __/\ \/ /----------+\n| / /    </ / __/ (__/ ___>_)  (CNEt''S N0.1|\n+-\/\_/\_/\/\/  \___/\_____/_/\_\----------+\n|         FAtEDiZ V1.1 (10.04.1994)        |\n| filE_iD.DiZ pR0cESS0r f0R fAAASt b0ARdZ! |\n|   c0MplEtE aRCHiVE !!! GEt iT n0W !!!    |\n+-=[FAtE]=---------------------=[tRiflEX]=-+\n','\n',char(10)),'FateDiz.guide',replace('@database "FAtEDiZ V1.1 GUiDE"\n@node main "FAtEDiZ V1.1 AMiGAGUiDE D0CUMENtAti0N"\n                      _                                    __\n        _____________/ \__________________________ _______/  \  ____\n        \______  ___/  __   \_________________/  //  _____\   \/   /\n            /    / /  _/   _/     \/  ____ /    // ______/ \  /   /\n           /    / /   \     \      \ ____//    //         \/     /\n          /    /  \____\     \_____/  /  /   _/ \_________/  \  / \\n          \___/         \_____/  \___/   \__________/ 0Vl \__/\___/\n\n                   ...cøz bEiNG iNSANE iS N0 diSEASE...\n\n                     thE Nø.1 oN CNEt rElEASEd t0dAy:\n\n                            «« FAtEDiZ V1.1 »»\n                     C0PYRiGHt (C)1994 bY FAtE/tRiflEX\n                            RElEASED 10.04.1994\n\n                <= n0t jUSt aN0tha filE_iD.DiZ pR0cESS0R =>\n\n                @{" lEGAl tHiNX! " link 1}               @{" iNtR0dUCti0N " link 2}\n                @{" iNStAllAti0N " link 3}               @{" t00l hiSt0RY " link 4}\n                @{" CREDiZ^gREEZ " link 5}               @{" iT''S REAlitY " link 6}\n@endnode\n@node 1 "FAtEDiZ V1.1 - lEGAl tHiNX!"\n\nAll parts of the FAtEDiZ Archive are Copyright (C)1994 by FAtE/tRiflEX.\nNobody is allowed to clone, rip or modify any part of it except for the\nConfigurationfile. I repeat: nobody !!!\n\nFAtEDiZ was intended to be bug-free, nevertheless the Author is not \nresponsible for any Damage caused directly or indirectly by this Tool.\nNo warranties are given, neither expressed nor implied.\n\nThe FAtEDiZ *must* contain the following Files:\n\n FateDiz                 - The main Program\n FateDizCfg              - The Configuration Editor\n FateDizSkip             - Skips the long Description Prompt\n FateDiz.guide           - This File\n DmsDescript             - Gets the Description out of Dms Files\n ExeDescript             - Gets the Description out of Exe Files\n TxtExtract              - Gets the Description out of Txt Files\n APE                     - Amiga''s Packing Enhancement (Archiver)\n FILE_ID.DIZ             - Description of the FAtEDiZ Archive\n\nWith the further Installation and/or Usage of FAtEDiZ you agree to\nthese Rules.\n@endnode\n@node 2 "FAtEDiZ v1.1 - iNtR0dUCti0N"\n\ntRiflEX, CNet''s No.1 would like to introduce you to FAtEDiZ, *not* just\nanother FILE_ID.DIZ Processor for CNet. I started it in December last Year\nbut unfortunately I didn''t manage to release it, otherwise FAtEDiZ would\nhave been the first... well, anyway, the other FILE_ID.DIZ Processors do\ntheir Work fine and they have many Options... I don''t need! FAtEDiZ is\nintended to be run on fast Boards, it should *help* the Trader, not bore\nwith Millions of Options. So FAtEDiZ does *not* prompt anything after\nUploading. Everything is set up in the Configuration Editor before. Then\nthe Trader just uses the ''U''-Key, start Uploading and get a Drink or\nwhatever.\n\nSince a FILE_ID.DIZ should come along with every File nowaydays, FAtEDiZ\ndoesn''t have a Logo Bank. If a File doesn''t have one - fake it !!!\nOf course, Sent-by Lines are supported. To be preciously, *personal*\nSent-by Lines. To be even more preciously, Sent-by Lines may contain Chars\nthat will be replaced with the current Port Number and the current Time !!\n\nIf no FILE_ID.DIZ is found, FAtEDiZ optionally auto-aborts the Uploader''s\nDefault Editor.\n\nLast not least FAtEDiZ is the only FILE_ID.DIZ Processor that can skip the\nLong Description Prompt.\n\nYou see, FAtEDiZ has *many* Options to make Trader''s Life easy !!! So why\nshouldn''t you install it, eh? Of course, if you really need a Logobase or\n12 Lines Descriptions or the "Use only a Range of Lines"-Feature use\nanother FILE_ID.DIZ Processor like Q-FID, Q-DIZ, fiP, Dizzy or WhatsDiz!\n\n...and DON''T rip my Features !!!\n@endnode\n@node 3 "FAtEStAtS V1.1 - iNStAllAti0N"\n\nCopy "FateDiz", "FateDizCfg" and "FateDizSkip" into your PFiles: Dir and\n"APE", "DmsDescript", "ExeDescript" and "TxtExtract" into your "C:" Dir.\nYou also need "LHA", "ZOO", "ARC", "UNZIP" in your C: Directory. I decided\nnot to include these as they are really avaible everywhere and I don''t want\n150k Archives like the other FILE_ID.DIZ Tools Authors do :).\n\nStart up your favourite Text Editor and load "CNet:bbsmenu".\nGo to Section 2 (avaible everywhere) and add at the End of the Section:\n\n<TAB>FID |<CTRL-Q>#0PFiles:FateDizCfg}\n\nSave the File and load "CNet:bbstext".\n\nGo to Line 465 (CNet V2.63) which says something like "enter a long\ndescription" and insert at the *start* of the Line:\n\n<CTRL-Q>#0PFiles:FateDizSkip}\n\nGo to Line 499 which says something like "please describe %s" and insert\nat the *start* of the Line:\n\n<CTRL-Q>#0PFiles:FateDiz}\n\nSave the File and restart CNet or, if you''re one of the lucky CNet 3.xx\nUsers, reload BBSText.\n\nLast not least post a News Item informing your Users that you have FAtEDiZ\ninstalled followed by:\n\n<CTRL-Q>#0PFiles:FateDizCfg}\n\nYour Users *must* have run FateDizCfg once *before* they start Uploading!\n\nThe Configuration Editor is really easy to use, so no Explanations here...\n@endnode\n@node 4 "FAtEDiZ V1.1 - t00l hiSt0RY"\n\nV1.1  1o Apr 1994  Shit, forgot to give Credits to Re/\/\o and Spy of\n                   Mystic /X Design and to Jim Geuther. And I forgot\n                   to include DMSDescript, ExeDescript and Txtextract...\n\nV1.0  o9 Apr 1994  First Release.\n\nPlanned for the Future:\n- Nothing yet... but don''t you have some Suggestions? :)\n@endnode\n@node 5 "FAtEDiZ V1.1 - CREDiZ^gREEZ"\n\n           All Coding.......................................FAtE\n           Additional Coding Support (GU30_Longs)........D0t0RAN\n\n     DMSDescript & ExeDescript are (C) by Re/\/\o(/\/\ystic /X-DeSign)\n               TxtExtract is (C) by Spy(/\/\ystic /X-DeSign)\n          APE (Amiga''s Packing Enhancement) is (C) by Jim Geuther\n\n                       ''D liKE 2 sENd gREEtiNX 2...\n\n    dA bACklASh p0SSE (eSPECiAllY mARkY), X-rAY/iA^ACt, RED hAWk/iA^ACt\n   At0MiC/iA^ACt, Sh0dAN/iA^ACt, j0E C00l/tFl, cYCl0NE/tFl, 0VERl0RD/tFl\n           CAlYPS0/g0D^l0GiC^illUSi0N aNd RED AlERt/pH0NEdAti0N\n@endnode\n@node 6 "FAtEDiZ V1.1 - iT''S REAlitY"\n\n                              iT''S REAlitY...\n                  ______       ______                     \n                  \    /       \    /        /\          \n        /\_______  \  /_________\  /________/  \_______________  \n       /   ___  /___\/\  _____ \_\/_    _   |   \__     \    _/ \n       \___\_ \/ _   \_\/  _    /\/ \_  |__ |    \_\__   \   |  \n      _/    |____|    /  \_|   /     \_ |   |)    / _/    \  |/\__ \n      \     |   \____/   /\    \___   / |        /   \     \ /    \ \n       \________/|____  /__\    \ /:_/  |____\  /____|\    //__    \\n    ________|____|____\/____\    /_|____|_____\/_____|_\  /_________\\n    \   ______ \_    \____   \  /   _/ \    /        _  \/   |    | \n     \  /  _    /  |____| \__ \/\   | __\  /______   |___    l    | \n      \/  _|   /  __|___   _/    \  |/\__\/    \_  __|__\_____    |_\n      |   \    \___|    \   \     \ /    \      /  \               /\n      |____\    \ /______\__|\    //__    \__  /|   \   ________  /\n            \    /_|        |_\  /_________\ \/ |    \_____\    \/\n       [MY]  \  /              \/               |____|             \n              \/                                           \n     «« SPiRitUAl REAlitY -!- thE bACklASh eHq -!- thE tRiflEX wHq »»\n    «« aMiGA -!- pEEcEE -!- sNeS -!- aNsi -!- 0-dAYz -!- eLitEz øNlY »»\n        «« pASh! diSt SitE -!- bLh, tFl & pASh! rElEASES 4 frEE »»\n\n                        «« ++49-61o-355-oo1 dHSt »»\n\n                                    ---\n\n       If you want a faaast Reply, call my Board DiGitAl DUNGE0N$ at\n\n                     ++49-6192-910718 (300-2400 Baud)\n\n                                    ---\n\n                tRiflEX Productions can also be found on...\n\n.----------------------------------------------------------------------------.\n|D00M lANd             tRiflEX DHQ^Skid Row HOTC              ++31-1o27-31172|\n|NUClEAR fUSi0N        ACt0DiNE^iNtERACtiVE                   ++49-6192-ElitE|\n|HitCH                 0SiRiS GHQ                             ++49-6959-ElitE|\n`----------------------------------------------------------------------------''\n@endnode\n','\n',char(10)),NULL,'auto-added',53965,1,0,NULL,NULL,'fatedz11','scan',1780048504);
INSERT INTO door_catalog VALUES('fball20','FBALL20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/FBALL20.LHA','AcceptChal','XIM','AcceptChal',NULL,'Matt',NULL,'is a fully functional FootBall simulation that can be played over MANY Amiga BBS systems.',replace('Online Football 2.0 by Matt English - This\nis a fully functional FootBall simulation\nthat can be played over MANY Amiga BBS\nsystems.\n','\n',char(10)),'OLFB.guide',replace('@database OLFB.guide\n\n/* Turn word-wrap on */\n@wordwrap\n@node Main "Online FootBall Docs"\n Online Football copyright 1993, 94 by Matt English 12-10-94\n                        version 2.0\n\n        *** For best results, read ALL the Docs.. ***\n\n\n     @{"Legal Stuff" link LEGAL}               @{"What''s new for version 2" link WHATSNEW}\n     @{"About OLFB" link FEATURES}                @{"Registration" link REGISTER}\n     @{"Beta Testers" link BETATESTERS}              @{"Customizing OLFB" link CUSTOMIZE}\n     @{"Playing OLFB" link PLAYING}              @{"Sysops Read This" link SYSOPS}\n     @{"Setting up OLFB" link SETUP}           @{"Updating from earlier versions" link UPDATE}\n     @{"OLFB History" link HISTORY}              @{"WorkBench 1.3 users !" link WB1.3}\n\n                 @{"The OLFB SYSOP CHALLENGE" link SYSCHAL}\n                 @{"OLFBscore.rexx file" LINK SCORE}\n                 @{"Registered Users, Read This!" link REGISTERED}\n                              .\n                       *********\n                       * @{"Help!" link HELP} *\n                       *********\n\n@endnode\n\n@node SCORE "What is the OLFBscore.rexx file?"\n\n  You''ll find in this archive, the file OLFBscore.rexx.\n  This file is a working example for BBBBS sysops of how\n  to utilize Score information sent from Online FootBall.\n\n  The file, as it is, ONLY works for BBBBS sysops, but if\n  you have any Arexx knowledge, it should be quite simple\n  to edit this file so it can be used on any BBS system.\n  If you need help editing it, feel free to call me or any\n  of my Beta testers and I''m sure we can get it going.\n\n  What it does:\n\n   At the end of each OLFB game, if the file "OLFBscore.rexx"\n  exists in your REXX: dir, the game will send OLFBscore\n  information about the just finished game to be used in many\n  ways. The information is sent in this format:\n\nOLFBscore.rexx OpponentName GameResult UserName OpponentScore UserScore\n\n  OpponentName = the Name of the player played by the computer.\n  GameResult = W if Opponent won, L if Opponent Lost.\n  UserName = The name of the BBS caller involved in the game.\n  OpponentScore = Final score of the Opponent\n  UserScore = Final Score of the User\n\n  OLFBscore can be edited to do many things with this information.\n  The file provided will send email to the Opponent telling him\n  that he either won or lost at OLFB and show him the final\n  score. It will also create a file in the BBS_Text dir that\n  will display once per day to each caller showing the latest\n  results of OLFB games. A copy of this file will be created\n  in the OLFB dir and named "OLFB.sb"\n\n   ** If a file named "OLFB.sb" exists in the OLFB dir,it will\n      be displayed at the beginning of each game! **\n\n  Any of the above features can be disabled by the sysop by editing\n  the OLFBscore.rexx file as indicated inside the file.\n\n  I put comments in the file to help you understand how it works\n  and assist you if you want to adapt it for any other purpose.\n  To make it work for other systems than BBBBS, you will need to\n  edit the PATHS and make BBS specific adjustments.\n\n@endnode\n\n@node HELP "I need help!"\n\n            If ya just can''t seem to get this bugger running\n            or have questions/comments feel free to call me\n            and I''ll do all I can to help ya get going.\n\n                          Matt English\n                          The Alternative BBS\n                          (503) 761-3043\n\n@endnode\n\n@node Sysops "Sysops read this.."\n\n   TO ALL SYSOPS:\n     If you use this program, a call to my BBS would be nice!\n     (If you''ve never called.)\n     The Alternative BBS (503) 761-3043\n\n   Of course @{"registering" link REGISTER} the game would be great!\n\n  Tell me about the game!!\n\n@endnode\n\n@node BetaTesters "OLFB Beta Testers"\n\n    Thanks to all my Beta Testers! Without their help, I couldn''t have\n  gotten this game done! If ya need help, they will be glad to help you!\n                     Give ''em a call just to say hi!\n\n\n                      Online FootBall Beta Testers!\n\n   John Ruckart, Ami-Zone BBS                 Jobe Smith, Synthetic BBS\n    Evans GA. running "BBBBS"               Eliot ME. running "Excelsior!"\n         706-869-1561                                207-439-3205\n\n Kurt Christ, Mount Olympus BBS                   Trebor, AsGard BBS\n Timmins Ontario, running "DLG"              Portland OR.  running "Cnet"\n     Line # 1  705-264-6763                   Line # 1 14.4 503-777-5926\n     Line # 2  705-360-5060                   Line # 2 2400 503-777-5927\n\n                    Glenn Schworak, Glenn''s World BBS\n                      Salem OR. running "Excelsior!"\n                        Line #1  28.8 503-581-6524\n                        Line #2  14.4 503-391-9881\n                        Line #3  14.4 503-391-9871\n                        Line #4  2400 503-315-4921\n\n@endnode\n\n@node Playing "How do I play OLFB?"\n\n  Online FootBall is quite easy (and fun) to play.\n  For game instructions, look under "OPTIONS"\n  while playing the game.\n\n\n@endnode\n\n@node Whatsnew "New features in version 2.0"\n\n  New Features for Version 2.0\n\n+ The OLFB @{"Sysop Challenge" link SYSCHAL} +\n\n  Added direct support for 4D BBS\n  Added direct support for E!\n  Improved support for Multi-line BBS''s\n  Added a "CLI MODE", should now run on any AMIGA BBS\n  Added more interception plays\n  Added extended runback plays for punts and interceptions\n  Fixxed and changed many small bugs and oddities\n  Added an option to have the Plays read directly off of Hard Drive\n   rather than from RAM\n\n@endnode\n\n@node Legal "Stuff ya should know about"\n\n  ***************** OLFB Legal Stuff ********************\n\n Online FootBall is copyright 1993,94 by Matt English\n\n You are NOT allowed to make ANY changes to Online FootBall.\n This game can be freely distributed in it''s UNCHANGED original\n archive only!\n\n Online FootBall is provided without warranty of any kind.\n This game has been thoroughly tested and there should be\n no problems.\n\n The file "SOUND" was written by @{"Richard Stockton" link RLS}\n and is provided here with his permission. Thanks Richard!\n\n The following files that are included in this archive are\n Copyrighted by The Dineen Edwards group and are supplied\n here by License for use with this program. These files\n can NOT be distributed seperately!\n\n                  RPStart\n                  RPStart.info\n                  RPHi\n                  RPHi.info\n                  rexxplslib.library\n\n  ********************************************************\n\n@endnode\n\n@node RLS "Richard L Stockton"\n\n Richard Stockton is the author of BBBBS (Baud Bandit BBS)\n along with many other fine programs.\n\n He''s been alot of help with the development of this game\n and all my other Arexx projects.\n\n Give him a call at GRAMMAS BBS (206) 744-1254\n\n@endnode\n\n@node Features "OLFB Features"\n\n  *** Features ***\n\n  This is a fully functional FootBall simulation that can\n  be played over MANY Amiga BBS systems.\n\n  + This game will run on BBBBS, Cnet, Trinity, DLG, E! 4D and\n    TransAmiga systems and supports a "CLI MODE" allowing it\n    to run on almost ANY Amiga BBS system!\n\n    After setting it up, the game will determine which system\n    is running it and adjust itself accordingly! This is the\n    ONLY game (that I know of) that has this feature!\n\n  + User configurable\n    BBBBS & DLG --\n     Each user can select either ANSI or ASCII graphics in both\n     B&W or Color!\n    Cnet --\n     The users BBS settings will be utilized in the game and can\n     be edited while inside the game.\n    ALL --\n     Users can @{"Challenge the Sysop" link SYSCHAL} to play one on one, live\n     online!\n     Each user can individually turn ON/OFF game animation at any\n     time!\n     Each user can individually adjust his text display speed\n     depending on his reading speed or modem speed preferences.\n     The sysop can adjust the ODDS of a play resulting in a penalty\n     from within the versitile Sysop menu.\n     Games are automatically saved when a player quits so he can\n     play a single game over several sessions.\n  + Full featured Stats\n     The game will track and sort 9 different stat categories for\n     each player and display them on the the OLFB stat Sheet!\n  + Easy to Customize\n     The plays can be easily @{"customized" link CUSTOMIZE} or added to by the Sysop!\n\n@endnode\n\n@node Register "Registering Online FootBall"\n\n Online FootBall Register.doc v 2.0 11-10-94\n\n******\n @{"Attention Registered users!!" link REGISTERED}\n******\n\n Online FootBall is the result of many endless hours of Arexx\n programing. I have been working on this project off an on\n since 1992. All concepts & code for this program were written\n completely from scratch!\n\n I have MANY (really a whole bunch) new and exciting ideas for\n future enhancements to Online FootBall! You can register this\n game for only $5! Yes, just FIVE dollars! (Of course larger amounts\n will be accepted also! :)) Amazing isn''t it!\n I don''t know of any other BBS game that you can register for Only\n Five Dollars!!\n\n What you''ll get:\n   An Email Box and access to exclusive areas on The Alternative\n  BBS where you will be able to DownLoad ALL future versions of Online\n  FootBall.\n   You''ll be able to Download a "KeyFile" that will "Unlock" hidden\n  features in this and future versions of OLFB!\n   Your "Unlocked" versions of OLFB will have your BBS name coded into\n  the game and will display the info when played!\n   Your versions will never be crippled (future demo version may be..)\n   You will get priority for any suggestions you may have for future\n  releases!\n   You''ll get that warm feeling inside knowing you are supporting\n  a Sysop/Programmer who is trying to bring new and exciting things to\n  Amiga BBS''s!!\n\n  I have written several other BBS Games and Utilites you may have seen\n around.. ShipHunt.. Yacht_C ... BlackJack ... FileBase ... LogMover\n BBS Advertiser... Plinko & more.. (btw, all were released Free of Charge)\n\n  I have several other projects in the works right now and will be\n releasing them as I finish and test them..\n\n  Thankyou!\n  -------------------------------------------------------------------------\n            (NOTE: Print this form in it''s entirety, unmodified.)\n\n                    Online FootBall Registration Form v 2.0\n\n        Real Name: ___________________________________________________\n\n        Name you use on YOUR BBS _____________________________________\n\n        Name you will be logging onto\n        The Alternative BBS with _____________________________________\n\n        Alternate name (Use in case your first choice is already in use\n        at The Alternative BBS) ______________________________________\n\n        Address: _____________________________________\n\n                 _____________________________________\n\n        Country: ________________________\n\n        BBS NAME:______________________________\n        (As you wish it to appear in your license)\n\n        BBS SOFTWARE:__________________________  Version:___________\n\n\n        Registration Fee : $ 5.00  (if you''ll be calling for your KeyFile)\n\n                           $ 10.00 (if you want me to mail you your KeyFile)\n\n        Mark one choice:\n\n                        1. I will call for my KeyFile ________\n                        2. Please mail me my KeyFile  ________\n\n        Amount enclosed $____________\n\n\n        All registrations MUST be in one of the following forms.  All\n        checks to be made payable to Matt English.  No exceptions.\n\n        o   POSTAL money order\n        o   US bank money order\n        o   Cash in US bills\n        o   Personal check drawn from a US bank\n\n\n--------------------------------8< CUT >8-------------------------------------\n        Send to:\n\n         Matt English\n         1505 SE 174th\n         Portland Or\n         USA      97233\n\n After allowing time for me to receive your registration, call The\n Alternative BBS (503)761-3043 where I will setup a mailbox under your\n "logon name" (some people like alias''s but are not required). You will\n get more info on the latest version of OLFB and be able to DownLoad your\n REGISTERED "KeyFile"!\n\n Read This > @{"OLFB SUPPORT" link SUPPORT}\n\n ** Don''t forget to call and get your KeyFile!! **\n\nCheck & Money Order instructions:\n\nPersonal checks drawn outside the US cannot be accepted, this includes Canada.\n\nThe easiest method of payment for Canadian users is Canadian Postal\nmoney orders.\n\n@endnode\n\n@node SYSCHAL "The OLFB Sysop Challenge"\n\n * NEW * as of OLFB ver 2.0\n\n Online FootBall Now allows the caller to challenge the sysop\n one on one, head to head, live, may the best man win !\n\n How it works :\n\n  When a caller selects the option to challenge the sysop, the Sysop\n  will here a guitar sound (Assuming your sound is on). The sound\n  can be any SoungFile you like as long as you name it OLFB.sound\n  and put it in your OLFB dir.\n\n  If you want to Accept the challenge and play against the caller,\n  (and assuming you have OLFB set up correctly) type "ACCEPTCHAL"\n  in a CLI window, or have it in a menu or hotkey as you prefer.\n  If you don''t wanna play, ignore it..\n\n  Once you''ve accepted the challenge, you''ll be entered into the\n  OLFB Chat mode.. Here, you can introduce yourself, and try to\n  raz the caller if ya like.. Break outta chat by typing\n  "Q" on a new line.\n\n  From that point, everything will be quite obvious. You will\n  both enter your play selections when prompted, and neither\n  player will be able to see the others entries.\n\n  * Attention *\n\n  Two things that I became aware of while testing the Sysop Challenge.\n\n  1. A caller who wanted to cheat, could try to enter the plays\n     for the Sysop. (My brother-in-law always cheats)\n\n  2. Callers using an IBM can see the plays entered, even though\n     the AMIGA sysop can''t. (This is due to the way the IBM\n     uses ANSI)\n\n  I was able to fix these problems for BBBBS, CNET, and E! by using\n  special commands that these systems provide.\n\n  For everyone else (and the above also, if you''d rather) I''ve provided\n  an option for a "Popup" window to accept OLFB input whenever\n  it''s the sysops turn, effectively locking out the caller from\n  seeing your entry or trying to enter it himself..\n\n  To activate this Feature, create a file in your OLFB dir\n  named "OLFB.screen". (A working example for BBBBS systems is\n  provided in this archive.)\n\n  The file should have three lines in it as follows:\n\nBAUD\n100\n100\n\n  This first line is the public screen name where you want the\n  Popup window to appear. (Supposedly your BBS screen)\n\n  How do I know my public screen name? > @{"Read me" link GETSCREEN}\n\n      +&+&+&+&\n\n  For CNET Systems this line should read         CNETSCREEN\n  OLFB will decide which port is being used.\n\n      +&+&+&+&\n\n  The second line is the X factor for the top left corner of the\n  Popup window. Adjust to your preferences.\n\n  The third line is the Y factor for the top left corner of the\n  Popup window. Adjust to your preferences.\n\n  That''s it, once this file exists, this feature will be active.\n\n@endnode\n\n@node GETSCREEN "How do I know what my BBS''s public screen name is?"\n\n  The easiest way to find your public screen name is by looking\n  in the docs supplied with your BBS software.\n\n  I have supplied a small Arexx script with this archive named\n  "GetScreen.rexx". Combined with "getPubName.lha" you will\n  be able to find your BBS''s public screen name if it has one.\n\n  GetPubName.lha is FreeWare & Copyright 1992 by Michael `Mick'' Hohmann\n  It is available for DL at The Alternative BBS (503)761-8024\n  and many other Amiga BBS''s.\n\n  Once you have "getPubName.lha" follow the instructions inside\n  of "GetScreen.rexx" to find your Public Screen name.\n\n@endnode\n\n@node Setup "How to setup OLFB on your BBS"\n\n  For as little as $5 you can register this game and receive new\n  versions as soon as they become available and sleep well knowing\n  you''re supporting a dedicated Original code developer for the\n  Amiga community! See @{"Registration" link REGISTER} for more info.\n\n                @{"To setup OLFB from Scratch" link SETUPFULL}\n\n                @{"To update from an earlier version" link UPDATE}\n\n@endnode\n\n@node UPDATE "To update from an earlier version"\n\n  Use the update info that applies to your System :\n\n                     @{"BBBBS" link BBBBS.UPDATE}\n                     @{"CNET" link CNET.UPDATE}\n                     @{"DLG" link DLG.UPDATE}\n                     @{"TRINITY" link TRINITY.UPDATE}\n                     @{"TransAmiga" link TA.UPDATE}\n\n  After setting up files, READ THIS > @{"Finish setting up OLFB" link MORESETUP}\n\n@endnode\n\n@node SETUPFULL "To setup OLFB from Scratch"\n\n  Use the Setup that applies to your System :\n\n                     @{"BBBBS" link BBBBS.FULL}\n                     @{"CNET" link CNET.FULL}\n                     @{"DLG" link DLG.FULL}\n                     @{"TRINITY" link TRINITY.FULL}\n                     @{"E!" link E.FULL}\n                     @{"TransAmiga" link TA.FULL}\n                     @{"4D BBS" link 4D.full}\n                     @{"CLI MODE" link CLI.FULL}\n\n  After setting up files, READ THIS > @{"Finish setting up OLFB" link MORESETUP}\n\n@endnode\n\n@node MORESETUP "Finish setting up OLFB"\n\n  WB 1.3 users! READ THIS > @{"WB 1.3" link WB1.3}\n\n  ALL Systems :\n\n  The @{"OLFB Sysop Challenge" link SYSCHAL} mode allows callers to play head\n  head against the sysop!\n\n  @{"OLFBscore.rexx file" LINK SCORE}\n\n  The file "FB.ad" (OLFB$AD.E! for E! systems) is provided so you\n  can advertise the game (if ya like). It is an ANSI text file that\n  you can install so that it can be viewed during logon, or wherever\n  is appropriate for your system.\n\n  If the file "OLFB.announce" exists in your OLFB directory, it''s contents\n  will be displayed to each player. This is a good place to place messages\n  describing new features or challenging players to play against you in\n  The Sysop Challenge.\n\n  To Reset the game, use the reset options inside the game at the\n  @{"Sysop menu" link SYSFUNC}\n\n  After running the game once, a file will be created named "OLFB.config"\n  inside your OLFB directory. If you''d like to have the Plays read directly\n  from your Hard drive, rather than from RAM, change line 3 of this file\n  to be "0".\n\n  That''s it! If you see any bugs, let me know. (I mean it..)\n  Matt\n\n  Enjoy.\n\n@endnode\n\n@node WB1.3 "Info about WB 1.3 and OLFB"\n\n  **************\n  WB 1.3 users! : This game should work fine on your system. Two things\n  that wont be quite right, however...\n\n       1. The way the stat sheets sort..\n          The 1.3 version of the sort command is different\n          from the 2.0+ version.. Sorry.\n\n       2. You won''t be able to use the "Popup Screen" option\n          in The @{"Sysop Challenge" link SYSCHAL}.\n\n          Might be finally time to update that ROM??\n\n@endnode\n\n@node History "OLFB History\n\n OLFB - History by Matt English\n\n++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++\n\n  Any Versions not listed here, or bearing any other name other than\n  "Matt English" as author are unauthorized copies of this program\n  and should be considered as such. As a show of support for people\n  who program ORIGINAL Software for the Amiga, please run ONLY\n  AUTHORIZED versions of Online FootBall.. Thankyou\n\n  Matt English\n  The Alternative BBS\n  (503) 761-3043\n  14.4, 24 hrs.\n\n++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++\n\n version 2.0 11-10-94\n  > @{"What''s new for version 2 ?" link WHATSNEW}\n\n verions 1.65 thru 1.95\n  > Released to BETA Testers only!\n\n version 1.6 4-23-94\n  > OLFB now supports BBBBS, DLG, Cnet & Trinity BBS systems without\n    any modifications!! OLFB can also be ran on TransAmiga BBS systems\n    with the Startup file provided by Jerry Jordan. Thanks Jerry!!\n  > OLFB now reads a "Key" file if one exists, to determine if OLFB\n    has been registered or not. This is much more convenient for\n    Registered sysops. No longer need to call and Download an entire\n    "Registered" archive. Only need to call once to get the keyfile.\n  > Animation routines re-written resulting in upto a 300% increase\n    in animation speed!\n  > No more tied games. A tie at the end of the 4th Quarter will\n    go into a Sudden Death overtime period. Play continues until\n    either Team scores.\n  > Each user now has the option to turn the ball animation off or\n    on from the "Options" menu. The preference will be saved in the\n    users data file and used each time he plays. This was requested\n    by players at 2400 baud. Can really speed up a game!\n  > Each player now has the option to adjust their Text Speed for\n    OLFB. Text can be displayed VERY fast to VERY slow and every\n    speed in between. The preference will be saved in the\n    users data file and used each time he plays.\n  > Added a Sysop menu for the Sysop to customize and control\n    OLFB from inside the game.\n  > Users no longer play ONLY against the Amiga! The game will\n    choose opponents for new games from ALL the players in the\n    Stats Sheets that have played OLFB. The system will pick the\n    LEAST active player as the next opponent. This helps eliminate\n    all the ZEROS in the stats from players who never finish a\n    game. This also acts as an incentive for players to stay ACTIVE!\n    Active players will never be chosen as opponents and won''t have games\n    played for them by the computer. This feature also stops "AMIGA"\n    from dominating the Stats Sheets. Sysops can also add ficticious\n    Players or Teams from the Sysop menu to enhance game play.\n  > Forfeited games now record ALL the stats from the Forfeited game\n    rather than just the WIN/LOSS stat.\n  > If a text file with the name "OLFB.announce" exists in the OLFB\n    directory, it''ll be displayed after the intro screen. This is a\n    handy way to tell your users about new features or challange them\n    to beat you in the stats (:\n  > Added penalties. User has the option to accept or decline Penalties\n    that do NOT stop play action before the hike.\n  > The sysop can now adjust the odds for penalties from the sysop menu!\n  > Players returning to OLFB will be shown the current stats of their\n    saved game before being asked if they want to continue their saved\n    game.\n  > An animated Referee has been added!\n  > Odds for making a field goal have been adjusted.\n\n version 1.56 4-2-94\n  Released to Registered OLFB sysops only..\n\n version 1.55 3-25-94\n  OLFB now supports BBBBS, DLG & Cnet BBS systems without any\n  modifications!! No other BBS game (that I know of) does this!\n  The OLFB code has been compiled for much increased access speed!\n  This makes the OLFB filesize quite large, however the speed increase\n  is well worth the added Disk space. If you like, you can powerpack\n  the Online_FootBall file to achieve about a 60% size reduction.\n  You now can kick a field goal no matter what Down it is, providing\n  you are at the 40 yard line or closer.\n  Added HalfTime & game end stats reports.\n  Completely Re-programed the logic that the Amiga uses in picking\n  his plays. The game is more challenging.\n  I made some cosmetic changes & probably a ton of stuff I simply\n  can''t remember.\n\n  *** Due to some of the logic changes and optimization changes,\n      any data files generated from an earlier version of OLFB will\n      not be compatable with this version or Future versions. Future\n      versions will be backwardly compatable with this version.. ***\n\n version 1.4 1-16-94\n  Couple bugs fixed..\n  If a player didn''t continue a saved game, he wasn''t getting\n  credited with a loss in the Stat Sheets like he should have.\n  The sort command was getting added to the resident list\n  over and over and over.. If you want it resident, set it up\n  in your startup-sequence.\n\n version 1.3 1-10-94\n  First major release! ANSI graphics and Stats sheet completed!\n\n versions 1.0 thru 1.2 were riddled with bugs and spent\n 1992 and 1993 in my disk box driving me nuts. (never released)\n\n@endnode\n\n@node RexxPlus "RexxPlus"\n\n This game is in compiled Arexx. This results in about 2-4 times\n increased execution speed over un-compiled Arexx. It also results\n in a fairly large executable. Since this file is a TRUE executable,\n you may PowerPack it, Implode it, OR make it resident.\n The choice is yours..\n\n Setting your system up for REXXPLUS is covered in the\n @{"Setup" link SETUP} section.\n\n@endnode\n\n@node OLFB.sysop "The OLFB.sysop file"\n\n After you''ve ran the game once, edit the file "OLFB.sysop", that\n will be created in the OLFB directory. Instructions will be INSIDE\n the file.\n\n This file allows you to see the @{"Sysop Functions" link SYSFUNC} whenever\n you play the game.\n\n@endnode\n\n@node SysFUNC "OLFB Sysop Functions"\n\n After you''ve setup the @{"OLFB.sysop" link OLFB.SYSOP} file,\n you will have access to the Sysop Function menu whenever\n you play the game..\n\n From the sysop menu you can :\n\n Delete all saved games\n Reset all the Stat Sheets\n Reset the entire game\n Add ficticious players\n Change the Penalty Odds\n\n@endnode\n\n@node Registered "Hello, Registered users!"\n\n  ******\n  Attention Registered users!!\n  ******\n\n Several Sysops who have registered OLFB, have STILL not called The\n Alternative BBS to Download their "KeyFile"! You need your\n keyfile to "UnLock" this and future versions of OLFB! Don''t\n forget to call after sending in your registration! (503)761-3043\n\n Please read this! > @{"SUPPORT" link SUPPORT}\n\n@endnode\n\n@node SUPPORT "OLFB Support"\n\n I Pledge to supply support for Online FootBall as\n long as physically possible.\n\n I''ve been looking at those little RCA satelite dishes\n and my wife says I can''t have both a BBS and Satelite\n so...... In the event that The Alternative BBS EVER\n shuts down (I have no plans to do this), I will supply\n KeyFiles and support to ALL registered users through\n the mail. In the event this were to happen, it does not\n mean I''ve given up any of my rights as author of this\n game or that there would no be new versions.\n\n Not bad for $5, huh?\n\n Matt English\n\n@endnode\n\n@node Customize "Customizing OLFB"\n\n                           Customize.OLFB\n\n  Customizing the @{"OLFBscore.rexx file" LINK SCORE}\n\n  You can customize the OLFB play files to have a more local feel,\n  or change the odds to make the game easier/harder to play.\n  You''ll need to be able to use a text editor and learn the following\n  formats.. I hope I can explain them good enough..\n\n  The filename of each play file represents what kind of play\n  combination has been selected in the game that resulted in this\n  file to be called..\n  File "12" means offense picked selection 1 and defense selected 2.\n  File "34".. Offense 3, defense 4.\n  After you''ve played the game, this will make sense..\n  The text of a play should reflect the selected combinations.\n  A 3 or 4 offense play, should describe a pass play..\n\n  The first line of each play file has a number.. This number is\n  how many plays are in this file. If you ADD new plays to the file,\n  increase the number..\n\n  This is an actual play from the game:\n\n111         /* Offense 1, defense 1, play 1 of the file */\n1 8 -       /* This play will be 1 thru 8 yards.. The "-" means a loss "+" means gain.*/\nThe ball is hiked                             Play text\nThey''re going for the Quarterback sneak!          "\nThe defense reads it well,----                    "\nyard loss!!                                       "\nEND                                     /* Last line */\n\n\n  The game reads the first line of the file and sees how many plays are in the file.\n  It then picks a random play from the file.\n  The first line sets a range of yardage that this play will result in\n  and weather it''s a loss, gain, no gain (0), or Interception or Punt.\n  The 2 lines right before "END" will be joined in the program with the\n  number of yard gained/lossed spliced in between.\n\n  The easiest thing to do will probably be to look at all the different kinds of\n  plays and copy the format.. Be sure to keep a backup of the original plays.\n  If you mess up, you could get some funny results..\n\n  If you write a whole bunch of new plays, and wanna send em to me,\n  YES! Please do!\n  If ya need help, give me a call.\n\n  Matt 503-761-3043\n\n@endnode\n\n@node CLI.FULL "Installing OLFB using CLI MODE"\n\n     TO INSTALL OLFB CLI MODE:    + OLFB v 2.0 +\n\n      First Setup the files as shown > @{"File Setup" link F.SETUP}\n\n      Then call the game from your BBS as follows:\n\n  USAGE: Online_FootBall C Path Timeleft Mins/Secs Name\n\n  "C" tells OLFB that you are running in CLI mode\n\n  "Path" = The Full path of the "OLFB" directory ending in ":" or "/"\n\n  "TimeLeft" = a number that your BBS passes to OLFB telling OLFB\n               how much time this player has left for this call.\n               This MUST be "0" if your BBS doesn''''t pass timeleft.\n               You can also pass any number to limit each players time.\n                    Example 45 = 45 minutes\n\n  "MINS/SECS" = If timeleft is in minutes, pass "M". If TimeLeft is in\n                Seconds, pass S. If timeleft = 0 then pass 0\n\n  "Name" = The name of the caller passed by your BBS.\n\n  Example: Online_FootBall C BBS:Doors/ %tl M %name\n  Example: Online_FootBall C Doors: 4500 S Richard Stockton\n\n** You can always see this info by typing "Online_FootBall ?" in a CLI window **\n\n@endnode\n\n@node E.full "Setting up OLFB to run on E!"\n\n   The file setup for OLFB on Excelsior, is identical to the setup\n   used for the CLI MODE, EXCEPT for the path of the OLFB directory.\n   The OLFB directory MUST exist in your MAIN DOORS PATH.\n   Online FootBall will look for the OLFB directory in the directory\n   listed in the RESULT CODE returned from the "PATH 6" command.\n\n\n            Setup the files, then come back here.\n\n                       @{"File Setup" link F.SETUP}\n\n\n   You now add the game to your BBS menu and call the game\n   as an AREXX GAME! Calling the game as DOS Game will not\n   work properly for Multi-line systems!\n\n   You need to pass NO parameters to the game.\n\n@endnode\n\n@node 4D.full "Setting up OLFb to run on 4D BBS"\n\n   The file setup for OLFB on 4D BBS, is identical to the setup\n   used for the CLI MODE. Setup the files, then come back here.\n\n                        @{"File Setup" link F.SETUP}\n\n   Assuming your path to the OLFB directory is "BBS:Games/"\n   then call the game with the following line:\n\n   Online_FootBall 5 BBS:Games/\n\n\n@endnode\n\n@node F.setup "Setting up The OLFB files for CLI MODE"\n\n     File Setup:\n\n                            ++++++++\n\n      Decide where you are going to put your OLFB directory\n      on your system. For this example, I''ll use "BBS:Games/"\n      but you can substitute any directory you like.\n\n ++ Excelsior BBS sysops MUST put OLFB dir in your MAIN DOORS dir! ++\n\n                            ++++++++\n\n     1. Copy the file "rexxplslib.library" to your LIBS: directory\n     2. Copy the files RPStart & RPStart.info to your\n         WBStartup Drawer. (This starts up the RexxPlus\n         environment which is needed for this game. Copying\n         it to your WBStartup is REQUIRED to run this game!)\n         *** WB1.3 users can copy it to C: and run it in your\n             startup-sequence.\n     3. OPTIONAL - Copy the files RPHi & RPHi.info to your C: directory.\n                   This command will stop ALL RexxPlus AND Arexx processes\n                   currently running.\n     4. Make a directory > "BBS:Games/OLFB"\n     5. Make a directory > "BBS:Games/OLFB/Plays"\n     6. Copy the file "Online_FootBall" into the "BBS:Games/OLFB" directory.\n     7. OPTIONAL - Copy the file "OLFB.announce" to your "BBS:Games/OLFB"\n        directory.\n     8. Copy these files to "BBS:Games/OLFB/Plays" :\n         11\n         12\n         13\n         14\n         21\n         22\n         23\n         24\n         31\n         32\n         33\n         34\n         41\n         42\n         43\n         44\n         55\n         56\n         65\n         66\n         76\n         85\n         86\n      9. Copy the file "Chal.sound" to your OLFB directory.\n     10. Copy the file "C/Sound" to your C: dir. (Should already be there.)\n         (Sound was written by @{"Richard Stockton" link RLS} and is provided here\n          with his permission. Thanks Richard!)\n     11. Copy the file "C/ACCEPTCHAL" to your C: dir.\n\n    **************\n\n    Please consider @{"Registering" link REGISTER} Online FootBall!\n\n    That''s it! If you see any bugs, let me know. (I mean it..)\n    Matt (503)761-3043\n\n    Enjoy.\n\n@endnode\n\n@node 4D "Setting up OLFb for 4D BBS"\n\n@endnode\n\n@node BBBBS.update "Updating OLFB on BBBBS"\n\n     Attention !!! :\n      If you are running any versions of OLFB older than version 1.55\n      you will need to do a @{"COMPLETE Installation." link BBBBS.full}\n\n      Future versions will be backwardly compatable to version 1.55.\n\n\n     TO UPDATE FROM OLFB V 1.55 OR GREATER :\n\n     1. Copy the file "Online_FootBall" over the old one in your\n        RexxDoors/data/OLFB directory.\n     2. Copy the file "OLFB.announce" to your OLFB directory.\n     3. Copy the file "Chal.sound" to your OLFB directory.\n     4. Copy the file "C/Sound" to your C: dir. (Should already be there.)\n        (Sound was written by @{"Richard Stockton" link RLS} and is provided here\n         with his permission. Thanks Richard!)\n     5. Copy the file "C/ACCEPTCHAL" to your C: dir.\n\n@endnode\n\n@node BBBBS.full "OLFB Full setup for BBBBS"\n\n     TO INSTALL OLFB ON BBBBS:    + OLFB v 2.0 +\n\n     COMPLETE INSTALLATION :\n\n     1. Copy the file "rexxplslib.library" to your LIBS: directory\n     2. Copy the files RPStart & RPStart.info to your\n         WBStartup Drawer. (This startsup the RexxPlus\n         environment which is needed for this game. Copying\n         it to your WBStartup is REQUIRED to run this game!)\n         *** WB1.3 users can copy it to C: and run it in your\n             startup-sequence.\n     3. OPTIONAL - Copy the files RPHi & RPHi.info to your C: directory.\n                   This command will stop ALL RexxPlus AND Arexx processes\n                   currently running.\n     4. Copy the file "Online_Football.rexx" to your rexxdoors directory.\n     5. Make a directory > "rexxdoors/data/OLFB"\n     6. Make a directory > "rexxdoors/data/OLFB/Plays"\n     7. Copy the file "Online_FootBall" into the "rexxdoors/data/OLFB" directory.\n     8. OPTIONAL - Copy the file "OLFB.announce" to your "rexxdoors/data/OLFB"\n        directory.\n     9. Copy these files to "rexxdoors/data/OLFB/Plays" :\n         11\n         12\n         13\n         14\n         21\n         22\n         23\n         24\n         31\n         32\n         33\n         34\n         41\n         42\n         43\n         44\n         55\n         56\n         65\n         66\n         76\n         85\n         86\n     10. Copy the file "Chal.sound" to your OLFB directory.\n     11. Copy the file "C/Sound" to your C: dir. (Should already be there.)\n         (Sound was written by @{"Richard Stockton" link RLS} and is provided here\n          with his permission. Thanks Richard!)\n     12. Copy the file "C/ACCEPTCHAL" to your C: dir.\n\n    **************\n\n    That''s it! If you see any bugs, let me know. (I mean it..)\n    Matt (503)761-3043\n\n    Enjoy.\n\n@endnode\n\n@node CNet.Update "Updating OLFB on CNET"   + OLFB v 2.0 +\n\n++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++\n\n     Attention !!! :\n      If you are running any versions of OLFB older than version 1.55\n      you will need to delete all the files in your OLFB directory\n      and do a @{"Complete Installation" link CNET.FULL}\n\n      The files generated by this version of OLFB are NOT compatable\n      with versions older than ver 1.55!\n      Future versions will be backwardly compatable to version 1.55.\n\n     Also, if you are running un-authorized versions of OLFB claiming to\n     have been written by anyone other than Matt English, the data files\n     WILL NOT be compatable with data files used by authentic\n     releases of OLFB. You should either rename your old OLFB\n     directory or delete it''s contents to avoid conflicts.\n\n++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++\n\n     The easiest thing to do is de-compress this archive to RAM:\n     and then run the AREXX script "CNetFB.Install"\n     "CNetFB.Install" will BOTH install or upgrade OLFB v 1.55 and greater.\n     Then, Adopt Online FootBall as a SINGLE USER Pfile.\n     "CNetFB.Install" provided by Trebor of Asgard BBS! Thanks Trebor!\n\n\n     Updating Manually\n\n     1. Copy the file "Online_FootBall" over the old one in your\n        PFiles: directory.\n     2. Copy the file "OLFB.announce" to your Pfiles:OLFB directory.\n     3. Copy the file "Chal.sound" to your Pfiles:OLFB directory.\n     4. Copy the file "C/Sound" to your C: dir.\n        (Sound was written by @{"Richard Stockton" link RLS} and is provided here\n         with his permission. Thanks Richard!)\n     5. Copy the file "C/ACCEPTCHAL" to your C: dir.\n\n    Please consider @{"registering" link REGISTER} Online_FootBall.\n\n@endnode\n\n@node CNet.full "Complete Installation for CNET"\n\n     TO Install OLFB ON CNET:    + OLFB v 2.0 +\n\n++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++\n\n     Attention !!! :\n      If you are running any versions of OLFB older than version 1.55\n      you will need to delete all the files in your OLFB directory\n      before installing this version.\n\n      The files generated by this version of OLFB are NOT compatable\n      with versions older than ver 1.55!\n      Future versions will be backwardly compatable to version 1.55.\n\n     Also, if you are running un-authorized versions of OLFB claiming to\n     have been written by anyone other than Matt English, the data files\n     WILL NOT be compatable with data files used by authentic\n     releases of OLFB. You should either rename your old OLFB\n     directory or delete it''s contents to avoid conflicts.\n\n++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++\n\n     The easiest thing to do is de-compress this archive to RAM:\n     and then run the AREXX script "CNetFB.Install"\n     "CNetFB.Install" will BOTH install or upgrade OLFB v 1.55 and greater.\n     Then, Adopt Online FootBall as a SINGLE USER Pfile.\n     "CNetFB.Install" provided by Trebor of Asgard BBS! Thanks Trebor!\n\n     MANUAL INSTALLATION :\n\n     1. Copy the file "rexxplslib.library" to your LIBS: directory\n     2. Copy the files RPStart & RPStart.info to your\n         WBStartup Drawer. (This starts up the RexxPlus\n         environment which is needed for this game. Copying\n         it to you WBStartup is REQUIRED to run this game!)\n         ** WB1.3 users can copy it to C: and run it in your\n            startup-sequence.\n     3. Copy the files RPHi & RPHi.info to your C: directory.\n         This command will stop ALL RexxPlus AND Arexx processes\n         currently running.\n     4. Copy the file "Online_Football" to your PFiles: directory.\n     5. Make a directory > "Pfiles:OLFB"\n     6. Make a directory > "PFiles:OLFB/Plays"\n     7. Copy these files to "Pfiles:OLFB/Plays" :\n         11\n         12\n         13\n         14\n         21\n         22\n         23\n         24\n         31\n         32\n         33\n         34\n         41\n         42\n         43\n         44\n         55\n         56\n         65\n         66\n         76\n         85\n         86\n     8. OPTIONAL - Copy the file "OLFB.announce" to your "PFiles:OLFB"\n        directory. Any file named "OLFB.announce" will be displayed\n        each time the game is played.\n     9. Copy the file "Chal.sound" to your Pfiles:OLFB directory.\n     10. Copy the file "C/Sound" to your C: dir.\n        (Sound was written by @{"Richard Stockton" link RLS} and is provided here\n         with his permission. Thanks Richard!)\n     11. Copy the file "C/ACCEPTCHAL" to your C: dir.\n\n     12. Adopt Online FootBall as a SINGLE USER Pfile.\n\n\n    Please consider @{"Registering" link REGISTER} Online FootBall!\n\n    That''s it! If you see any bugs, let me know. (I mean it..)\n    Matt (503)761-3043\n\n    Enjoy.\n\n@endnode\n\n@node DLG.update "Updating OLFB on DLG"\n\n     TO UPDATE OLFB ON DLG:    + OLFB v 2.0 +\n\n     Attention !!! :\n      If you are running any versions of OLFB older than version 1.55\n      you will need to delete all your old OLFB files and do a\n      @{"Complete Installation" link DLG.FULL}\n\n      The files generated by this version of OLFB are NOT compatable\n      with versions older than ver 1.55!\n      Future versions will be backwardly compatable to version 1.55.\n\n\n     TO UPDATE FROM OLFB V 1.55 OR GREATER :\n\n     1. Copy the file "Online_FootBall" over the old one in your\n        Doors: directory.\n     2. Copy the file "OLFB.announce" to your Doors:OLFB directory.\n     3. Copy the file "Chal.sound" to your Doors:OLFB directory.\n     4. Copy the file "C/Sound" to your C: dir. (Should already be there.)\n        (Sound was written by @{"Richard Stockton" link RLS} and is provided here\n         with his permission. Thanks Richard!)\n     5. Copy the file "C/ACCEPTCHAL" to your C: dir.\n\n    Please consider @{"registering" link REGISTER} Online_FootBall.\n\n@endnode\n\n@node DLG.full "Complete Installation for DLG"\n\n     TO INSTALL OLFB ON DLG:    + OLFB v 2.0 +\n\n     Attention !!! :\n      If you are running any versions of OLFB older than version 1.55\n      you will need to delete all the files in your OLFB directory\n      and install as outlined below.\n\n      The files generated by this version of OLFB are NOT compatable\n      with versions older than ver 1.55!\n      Future versions will be backwardly compatable to version 1.55.\n\n\n     COMPLETE INSTALLATION :\n\n     1. Copy the file "rexxplslib.library" to your LIBS: directory\n     2. Copy the files RPStart & RPStart.info to your\n         WBStartup Drawer. (This starts up the RexxPlus\n         environment which is needed for this game. Copying\n         it to you WBStartup is REQUIRED to run this game!)\n         ** WB1.3 users can copy it to C: and run it in your\n            startup-sequence.\n     3. Copy the files RPHi & RPHi.info to your C: directory.\n         This command will stop ALL RexxPlus AND Arexx processes\n         currently running.\n     4. Copy the file "Online_Football" to your Doors: directory.\n     5. Make a directory > "Doors:OLFB"\n     6. Make a directory > "Doors:OLFB/Plays"\n     7. Copy these files to "Doors:OLFB/Plays" :\n         11\n         12\n         13\n         14\n         21\n         22\n         23\n         24\n         31\n         32\n         33\n         34\n         41\n         42\n         43\n         44\n         55\n         56\n         65\n         66\n         76\n         85\n         86\n     8. Copy the file "Chal.sound" to your Doors:OLFB directory.\n     9. Copy the file "C/Sound" to your C: dir.\n        (Sound was written by @{"Richard Stockton" link RLS} and is provided here\n         with his permission. Thanks Richard!)\n     10. OPTIONAL - Copy the file "OLFB.announce" to your "Doors:OLFB"\n         directory.\n     11. Copy the file "C/ACCEPTCHAL" to your C: dir.\n\n   See the IFF picture file "dlgfootsetup.iff" to setup the game!\n   Thanks to Kurt Christ, Mount Olympus BBS, 705-264-6763 for the\n   Great IFF pic!!\n\n\n    Please consider @{"Registering" link REGISTER} Online FootBall!\n\n    That''s it! If you see any bugs, let me know. (I mean it..)\n    Matt (503)761-3043\n\n    Enjoy.\n\n@endnode\n\n\n@node TA.update "Updating OLFB on TransAmiga"\n\n     TO UPDATE OLFB ON TransAmiga:    + OLFB v 2.0 +\n\n     Attention !!! :\n\n      There were some bugs in the TransAmiga setup docs\n      for OLFB v 1.6\n\n      Even if you managed to get it running, due to changes\n      in this version, I suggest you delete all the files\n      in your OLFB directory, and install this version from\n      Scratch!\n\n     @{"Install from Scratch" link TA.full}\n\n    Please consider @{"registering" link REGISTER} Online_FootBall.\n\n@endnode\n\n@node TA.full "Complete Installation for TransAmiga"\n\n     Attention!\n\n      There were some errors in the OLFB docs of version 1.6\n      regarding TA setup.. This has been fixed! The TA File\n      setup is the same as the CLI MODE setup.\n\n      Setup Files according to The @{"CLI MODE" link F.SETUP} and then come back\n      here.\n\n\n==========================================================================\n\n     The following section was provided by Jerry Jordan. Thanks Jerry!\n\n==========================================================================\n\n     1. Edit the file "OLFB.trans" line # 24 to reflect the path of where\n        you installed the game.\n\n     2. Copy the file "OLFB.trans" to your games directory.\n\n     3. Add the following to your Extras.Rx file in your Configs directory.\n\n         N OLFB                     5 -------- OLFB.trans\n\n         ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^\n         Change the above for your needs, but leave the spaces!\n\n     4. Play the game. :)  Hopefully I didn''t forget anything!!\n\n     I can be contacted at Hawk''s Haven BBS Tel. +354-2-54758,,,,,,,,,,,,1#1\n     (12 commas for a Fax/Voice Switch *BOY I NEED A BETTER ANSWER MACHINE*)\n     or by mail at:\n                      Jerry Jordan\n                      PSC 1013 Box 628\n                      APO AE 09725-0628\n                      USA\n\n     This address is physically in Iceland, but this is a US Air Force mailing\n     address in the USA. Matt''s address can be found in the @{"Registration.Doc" link REGISTER}\n\n==========================================================================\n\n    Please consider @{"Registering Online FootBall." link REGISTER}\n\n    That''s it! If you see any bugs, let me know. (I mean it..)\n    Matt (503)761-3043\n\n    Enjoy.\n\n@endnode\n\n@node Trinity.update "Updating OLFB on Trinity"\n\n     TO UPDATE OLFB ON Trinity:    + OLFB v 2.0 +\n\n     Attention !!! :\n      If you are running any versions of OLFB older than version 1.55\n      you will need to delete all the files in your OLFB directory\n      and do a @{"Complete Installation" link TRINITY.full}\n\n      The files generated by this version of OLFB are NOT compatable\n      with versions older than ver 1.55!\n      Future versions will be backwardly compatable to version 1.55.\n\n     TO UPDATE FROM OLFB V 1.55 OR GREATER :\n\n     1. Copy the file "Online_FootBall" over the old one in your\n        OLP: directory.\n     2. Copy the file "OLFB.announce" to your OLP:OLFB directory.\n     3. Copy the file "Chal.sound" to your OLP:OLFB directory.\n     4. Copy the file "C/Sound" to your C: dir.\n        (Sound was written by @{"Richard Stockton" link RLS} and is provided here\n         with his permission. Thanks Richard!)\n     5. Copy the file "C/ACCEPTCHAL" to your C: dir.\n\n    Please consider @{"registering" link REGISTER} Online_FootBall.\n\n@endnode\n\n@node Trinity.full "Complete Installation for Trinity"\n\n     COMPLETE INSTALLATION :     + OLFB ver 2.0 +\n\n     1. Copy the file "rexxplslib.library" to your LIBS: directory\n     2. Copy the files RPStart & RPStart.info to your\n         WBStartup Drawer. (This starts up the RexxPlus\n         environment which is needed for this game. Copying\n         it to you WBStartup is REQUIRED to run this game!)\n         *** WB1.3 users can copy it to C: and run it in your\n             startup-sequence.\n     3. OPTIONAL - Copy the files RPHi & RPHi.info to your C: directory.\n                   This command will stop ALL RexxPlus AND Arexx processes\n                   currently running.\n     4. Copy the file "Online_Football" to your OLP: directory.\n     5. Make a directory > "OLP:OLFB"\n     6. Make a directory > "OLP:OLFB/Plays"\n     7. OPTIONAL - Copy the file "OLFB.announce" to your "OLP:OLFB"\n        directory.\n     8. Copy these files to "OLP:OLFB/Plays" :\n         11\n         12\n         13\n         14\n         21\n         22\n         23\n         24\n         31\n         32\n         33\n         34\n         41\n         42\n         43\n         44\n         55\n         56\n         65\n         66\n         76\n         85\n         86\n     9. Add Online FootBall to your OLP menu..\n     10. Copy the file "Chal.sound" to your OLP:OLFB directory.\n     11. Copy the file "C/Sound" to your C: dir.\n        (Sound was written by @{"Richard Stockton" link RLS} and is provided here\n         with his permission. Thanks Richard!)\n     12. Copy the file "C/ACCEPTCHAL" to your C: dir.\n\n    Please consider @{"registering" link REGISTER} Online_FootBall.\n\n    That''s it! If you see any bugs, let me know. (I mean it..)\n    Matt (503)761-3043\n\n    Enjoy.\n\n@endnode\n','\n',char(10)),NULL,'auto-added',237868,2,0,NULL,NULL,'fball20','scan',1780048504);
