INSERT INTO door_catalog VALUES('fld_lod1','FLD-LOD1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/FLD-LOD1.LHA',NULL,'XIM','rexxtricks.library',NULL,'JaWloG','FLD','._\  ___/ |   .   _      |_\_____|_fLOOD! |   __/   |   l   |  .   _   .____/ ) -|    |____|_______|  l   |   l   |----- (',replace('     ___._\_ |_\     |______. ______.\n   ._\  ___/ |   .   _      |_\_____|_fLOOD!\n   |   __/   |   l   |  .   _   .____/\n) -|    |____|_______|  l   |   l   |----- (\n | |____| presents: |_______|_______|nCo! |\n !/.                                      |_\n //     LocalDownload V1.0 By JaWloG      |/\n /   The First LocalDl Door Ever Made !  \/\n |    Supporting Ami and Sigma Express    |\n | Features Background Unp. and much more |\n `-[21/Mar/96]-----------------------[81]-''','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 20:35:19  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',25930,2,0,NULL,NULL,'fld_lod1','scan',1780048515);
INSERT INTO door_catalog VALUES('fld_p014','FLD-P014.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/FLD-P014.LHA','PowerPager','XIM','LE-win5-96.exe',NULL,'MA!/FLD','FLD','/\____!_   | ______   ______   ___|   | :/  _____/   |/  __  \ /  __  \ /  __   | .   __/ .   |.   l   Y.   l   Y.   l   |--.',replace('        .____.FLOOD /X-S!X DIVISION .___.\n  /\____!_   | ______   ______   ___|   |\n:/  _____/   |/  __  \ /  __  \ /  __   |\n .   __/ .   |.   l   Y.   l   Y.   l   |--.\n|:.  |  |:.  |:.      |:.      |:.      |t0|\n`----''  `----^--------^--------^--------'' !|\n|     PowerPager V0.14 Coded By MA!/FLD    |\n|   Full GUI Configuration, BlackListing,  |\n|    Chatflag Override, Macros And More!   |   \n|       Fully Configurable Output!         |\n`---------------------------------------[4]''','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                                                .------''\n             `------------------------------------------------''\n','\n',char(10)),NULL,'auto-added',33263,5,0,NULL,NULL,'fld_p014','scan',1780048515);
INSERT INTO door_catalog VALUES('fld_p016','FLD-P016.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/FLD-P016.LHA','POWERPAGER','XIM','POWERPAGER',NULL,'MA!/FLD','FLD','/\____!_   | ______   ______   ___|   | :/  _____/   |/  __  \ /  __  \ /  __   | .   __/ .   |.   l   Y.   l   Y.   l   |--.',replace('        .____.FLOOD /X-S!X DIVISION .___.\n  /\____!_   | ______   ______   ___|   |\n:/  _____/   |/  __  \ /  __  \ /  __   |\n .   __/ .   |.   l   Y.   l   Y.   l   |--.\n|:.  |  |:.  |:.      |:.      |:.      |t0|\n`----''  `----^--------^--------^--------'' !|\n|    PowerPager V0.16ß Coded By MA!/FLD    |\n|   Bugfixed Version! New Options Added!   |\n|GUI Configuration, Able To Refuse Page If |\n|Sysop is In Chat! Macros, Blacklisting,   |\n| Configurable Output! Check Screenshots!  |\n`---------------------------------------[5]''\n','\n',char(10)),'PowerPagerv016.DOC',replace('@BEGIN_FILE_ID.DIZ/POwerpager doc\n@END_FILE_ID.DIZ\n*[ PowerPager Documentation ]************************************************\n\n             PowerPager v0.16 For AmiExpress and SigmaExpress\n                           Coded by MeNaCe/Flood.\n\n                    ** REMEMBER TO READ THE CHANGES **\n\n*[ Program Description ]*****************************************************\n\nPowerpager is a quite powerful pager with features FULL GUI Configuration,\nChat-Request  Window,  Macros, Accept Chat, and Quiet ( Disables the Beep''s\nwithout letting user know it.  )\n\nHave a look at the iff files, included in the archive.\n\n*[ Installation ]************************************************************\n\nInstall  this  door  as  every  other  XIM-Door.   The  door  is  tested on\nAmiExpress  and  Sigma  Express  so  there  should  be  no problem.  If you\nencounter some, please report this to me asap - so I can fix the problem.\n\n*[ To Setup PowerPager ]*****************************************************\n\n The main ideas of PowerPager was to make an easy-using pager, which\nfeatures the most handy function a sysop may want.  But as of version\nv0.12+ the door is more complex that it was intended to by when I started\nthe project. From version 0.13 all text is located in different files, which\nshould make it easier to make a custom design of the door. \n\nThe door uses the following files located in BBS:BBSTexts/PowerPager/ OR\nDOORS:FLD-Doors/PowerPager/Texts/ :\n BlackListed.txt(.gr)- is displayed when a user is Blacklisted.\n ChatRefuse.txt(.gr) - if the door is setup to REFUSE if the sysop\n                       is already in a chat this file is displayed.\n\n LeaveAComment.txt(.gr)is displayed if the door fails to get sysop.\n NoReason.txt(.gr)   - is shown if the door is setup NOT to accept\n                       empty reasons.\n Reason.txt(.gr)     - is displayed before the door awaits a reason.\n ReasonNotify.txt(.gr) is displayed if the sysop is already in a chat,\n                       and the door is set to notify the user about it.\n                       If the sysop is NOT in a chat, the Reason.txt is\n                       displayed instead.\n PagingString        - Is the char''s which is printed on the screen\n                       during the paging process. ( The Internal pager\n                       uses a ''. '' ). If the PagingString is small than\n                       67 chars, it will be repeated.\n SysopNotAvail.txt(.gr)is displayed, when the chatflag is off.\n Paging.txt(.gr)     - is shown before the paging process ( before the\n                       PagingString is displayed.\n SysopIsComming.txt(.gr)is displayed when the sysop presses Accept in\n                       the Chat-Request window.\n BeforeText.txt(.gr) - and\n AfterText.txt(.gr)  - is used if the sysop sends any text from the\n                       Chat-Request Window.\n\n Useful notes:  The max input for reason is 31 chars long.\n\n*[ Configuration ]***********************************************************\n\nTo  setup  Powerpager  start  the  door  from  the  shell,  and  a nice gui\nconfiguration  window appears.  The first 10 gadgets ( 2*5 ) is the macros.\nHere  you  can  setup your own macros.  If you prefix a macro with a ''<'' it\nshould  be  a  full  path  to  a  text  file  to  be  displayed (supporting\n<access>.txt(.gr)\n\nThe next gadget is the so-called SysopInChat Action gadget.  This tells the\ndoor  how  to  react  if a user tries to page while the sysop is in a chat.\nNOTE:  If this is set to "REFUSE TO PAGE..." and the user got "Override CF"\nstatus ( and this is enabled ) - it will bypass SysopInChat Action.\n\nThe  next  two gadget is used to specify where a possible logfile should be\nplaced.\n\nThe  following  gadget  is named "Use BlackList" which tells the door if it\nshould enable the blacklist feature.\n\nThe  same  goes  for the "Allow CF Override", this is just for the Override\nfeature.\n\n"Make LogFile" is shouldn''t be too hard to figure out.\n\n"Allow Empty Reason" - if this is enabled, and the user enters nothing as a\nchat-reason,  the  door  will  continue the paging process - if this is not\nset, and the user enters nothing, the door will exit.\n\nThe next gadget is a cycle gadget, and is used to set the method of paging:\nDisplayBeep(),  Execute  Command  or  Be  Quiet.   If  Execute  Command  is\nselected, the command should be written in the below string-gadget.\n\nNew in v0.15: If the chat-request fails, it''s possible to let PowerPager \nexecute "c" or "e Sysop". \n\n"About"  shows  some vital information, you don''t wanna miss this one.  :),\nand "Save" just saves the configuration.  To cancel the changes, just close\nthe window.\n\n*[ BlackList ]***************************************************************\n\nIf you got some users you won''t wanna chat with, just his/hers name into\nthe blacklist.  The Blacklist is a file named "PowerPager.BLU" (BLU=Black\nListed Users) - and the format is:  <name><CR> ..  No more no less.\nRemember to enable the BlackList in the configuration menu, if you need\nthis feature.\n\n*[ ChatFlag Override List ]**************************************************\n\nThe option is useful if you got any cosysop, or good friends.  The list\nshould contain the names of the persons who is allowed\n\n - to bypass the InChatAction or\n - to bypass the Chatflag.\n\nIs just as easy as with the blacklist.  The file is just named\n"PowerPager.CFO" (Chat Flag Override) and the format is the same as\ndescribed above.\n\n*[ Last words ]*************************************************************/\n\n This doc stinks! But it provides a basic understanding of the PowerPager,\n so you can change the setup to suit your needs. \n\n I want to send special greeting to Flozzy, for ideas and betatestning,\n and to Enzo for betatesting. Normal greetings to my friends in the scene.\n\n If you got any ideas/bug reports for PowerPager please don''t hesitate to\n contact me at Sky Tower, BattleField or Critical Zone. Or write me at:\n fido: 2:235/314.83 amynet: 39:141/105.83 or\n inet: [email removed]\n\n And here at last a small tip to the avanced PowerPager user from Flozzy:\n If you want an easy''n''quick way to access the configuration window\n of PowerPager; Setup the ACP to have PowerPager as a button, so whenever\n you want to change the configuration, you just press the button in ACP.\n\n If you are using Sigma Express, add the following line to S:ACP.STARTUP:\n BUTTON01: PPager Config |Run >NIL: Doors:PowerPager/PowerPager >NIL:\n\n If you are using AmiExpress, add the following tooltypes to your ACP.info\n BUTTON_NAME.1=PPager Config\n BUTTON_COMMAND.1=Doors:PowerPager/PowerPager\n\n*[ Version Changes ]*********************************************************\n\nv0.12 951231 First Public Beta Release.\nv0.13 960109 The door can now be designed much better, as the door\n             uses serval ascii files. The /X display-function (JH_SG)\n             was replaced with a internal, which is much faster.\n             All text files have been replaced, or been redefined!\nv0.14 960204 Small bug fix.. If one of the text file was missing, some\n             garbage was shown. (Reported By Doig/Squeech)\nv0.15 960210 Every page is now logged in the CALLERSLOG, so utilities/doors\n             like SAmilog will know that the sysop was paged. THIS IS ALWAYS\n             done no matter if PowerPagers own log was enabled, or not.\n             (Suggested By Acoma)\n      960211 New textfile is added: SysopIsComming.txt(.gr) which is\n             displayed when sysop presses ACCEPT in the chat request window.\n             ANSI fuckup fixed!. (Reported by Squeech)\n      960218 Added the possibility to leave a comment, if the chat-request\n             failed.\n             The door now searches the PROGDIR:Texts/ directory for the text\n             files, if they are not located in BBS:BBSTexts/PowerPager.\nv0.16 960219 + Added serval gadgets, and added a 2nd. ConfigWindow. (Macro-Setup)\n      960220 + If no config is found, a default setup is used.\n      960221 + Added PageStr-Length, Reason-Length and Delay Between Pages.\n             + New textfiles added:\n                        BeforeText.txt(.gr)\n                        AfterText.txt(.gr)\n               Which is used, if the sysop sends any text from the\n               Chat-Request window\n\n*[ The End ]*****************************************************************\n','\n',char(10)),NULL,'auto-added',39382,5,0,NULL,NULL,'fld_p016','scan',1780048524);
INSERT INTO door_catalog VALUES('fld_polm','FLD-POLM.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/FLD-POLM.LHA',NULL,'XIM','cHASING_cLOUDS!.aGa.eXe',NULL,NULL,'FLD','._)  _/__)   /  ._)  _ (_._)  _ (_._)  _ \ |    ._/   _/___|    /   |    /   |    /  \ |____| |__ \    |________|________|__      |',replace('  _____  _____    ______   ______   _____ \n._)  _/__)   /  ._)  _ (_._)  _ (_._)  _ \\n|    ._/   _/___|    /   |    /   |    /  \ \n|____| |__ \    |________|________|__      |\n /X ONLY )______|- Pro-OLM v.1.0 - +)______|\n|  OLM to people in doors, chatting etc.   |\n|  Get a reciept if people are ul/dl as    |\n|    soon as they get your waiting OLM.    |\n| Supports Annonymous OLM, and Mini-Stat.  |\n|You will never use another olm door again.|\n`[21-Aug-96]--------------------------[247]''\n','\n',char(10)),'fld-Polm.doc',replace('=[ Pro-Old Documentation (MicroDoc) ]=========================================\n\n\n\n         Pro-Olm - The Intelligent OLM door v1.00 For AmiExpress \n                           Coded by JaWloG/Flood\n                        Original Idea By JaWloG/FlD!\n\n\n\n=[ Programme Description ]====================================================\n\nThe First Olm door that will OLM people scanning Files, chatting etc.\n\nPro-Olm is a door most people would be happy to get.\n\nWith Pro-Olm you''ll never go back to the internal OLM door, or most of the\ncrap "Can''t Olm - the user isen''t idle" doors.\n\n=[ Installing Pro-Olm ]=======================================================\n\n\nInstallation of Pro-Olm is very easy, simply use the installer script\nprovided. It will ask you where to install the door, and what command\nicon should call it (Olm is default)\n\n\n=[ Pro-Olm Configuration ]====================================================\n\nPro-Olm really doesent need configuration, If you want something changed\nleave a msg. for Jawlog somewhere (Preferbly in Denmark) and I''ll take a look\nat it.\n\n\n=[ Short Description (Available by using ''OLM ?'' too) ]=======================\n\nPro-Olm By JaWloG/Flood Features some of the coolest features available from\ncool OLM doors. \n\nBut the ability to OLM users chatting and scanning files is NEW\nand time saving.\n\nIf a user is not available, e.g. Downloading - \nthe door will simply wait for him to become available and then dump the olm.\n\nAll this is very good, and the user sending the OLM may choose to get a\nreciept as soon as the user got his OLM - thus you don''t have to sit around\nin IDLE mode waiting for the other user to become idle, recieve the message\nand answer it - You''ll be notified as soon as he gets the OLM.\n\nPro OLM supports a simple command line: Olm <NODE>\n\n                                   Eg.: Olm 1\n\nMore features will be available in later releases.\n\n- For Updates - Suggestions and BugReports - \n           Call ThE TriP +45 55778835\n\n\n=[ Programme Logic ]==========================================================\n\nWhen you start Pro-Olm it will check if you gave it any arguments - if not,\nit will ask you for a node number - Then it will check if it''s a valid node\nnumber, who''s on that node, and what is he doing.\n\nThis information will be presented to you.\n\nYou will then be asked if you want to get a reciept. A reciept is a small\nmessage that will return when the person you''re sending the OLM to gets the OLM\n\n- this is most usefull if the user you are about to olm is Up/Downloading - \nthe only situations where Pro-Olm cannot send the Olm right away.\n\nWhen you have made up your mind - you may choose to be annonymous - this will\nkeep your name and nodenumber private, so the person you send the olm to cannot\nsee who send it (Unless it''s a 2 node board and youre not using quiet :))\n\nIf not he will be able to see your handle, and the nodenumber you''re on.\n\nThen you will be presented with a standart msg editor, enter the txt you wish \nto send, save the message and off it goes. (Wow not hard was it :)\n\nNote: This Doc suxx ;)\n\n\n=[ Thanks Go Out to: (In Alp. Order) ]========================================\n\nEveryone On #amielite (Well - almost :))\n\nEveryone on my board - and the people I talk to every day - it''s\n\nlike almost 5 am. so the greetings can''t hold me awake :)\n\nAlso all others members of Flood, and the members of CRD, VDK, SAD CRX and HF\n\n\n=[ Contact me at: ]===========================================================\n\n  ThE TriP:\n\n==============================================================================\n\n              - fEEL tHE rUSH - fEEL tHE pOWER - fEEL tHE nEED -\n\n                                   - fEEL - \n      [- ThE TriP -]     _________          __________________________\n                      ___\        \ _______/___    _______________   /\n    _________________/___        __Y           \   \________________/\n    \______       ______/        \___           \___________________\\n     _/               \____________|             /\n     \_________________/      dIzY!l____________/\n   \n                                  ______________________________________\n                 _________________\______________/     _______________  \_\n_________________\_________________ \____________      \_________________/\n\______       ______/      .  _______/           \______________|\n _/               \________|        \_____________/\n \_________________/       l_________/(+45 55 77 88 35)\n\n                       __    __  __  __ __  _   _  _   __\n              _|_ |_| (_  _ (_  (_   _/ _/ (_) (_) _) (_  \n               |    | __)   __) __) /  /  (_) (_) __) __) \n                                                         \n        Hosted by Jawlog - CoSysOps: Dr. Chaos - Adonis - Mr. NoBody\n         CREED DKHQ - VODKA WHQ - SCEPTIC AMIEXPRESS DIVISION DKHQ.\n              FLOOD DANISH HEADQUATER - FLOOD AMIEXPRESS WHQ\n\n==============================================================================\n\n\n=[ ThE EnD ]==================================================================\n','\n',char(10)),NULL,'auto-added',58619,7,0,NULL,NULL,'fld_polm','scan',1780048524);
INSERT INTO door_catalog VALUES('fld_sc12','FLD-SC12.LZX','~/Code/amiexpress_doors/Archives/AmiExpress/FLD-SC12.LZX',NULL,'XIM','fld sc12',NULL,NULL,'FLD',NULL,NULL,NULL,NULL,NULL,NULL,89339,0,0,NULL,NULL,NULL,'scan',1780048524);
INSERT INTO door_catalog VALUES('fld_sw10','FLD-SW10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/FLD-SW10.LHA',NULL,'XIM','Install SuperWHO',NULL,'pSYCHoTROn/fLD!','FLD','______________           ____ _____/  ____/______/___________\_  \ _/          ____/\_       \_ _____/   \',replace('             fLOoD /X-dIViSiON\n          ______________           ____\n    _____/  ____/______/___________\_  \\n  _/          ____/\_       \_ _____/   \\n  \__._________/_____________/_________._\\n.....:         p r e s e n t s         :....\n:      SuperWHO 1.0 By pSYCHoTROn/fLD!     :\n:      Frontend Door And Realtime WHO      :\n:      Not CPU eating like any other!      :\n:      Nice Design "ScreenShots Inside"    :\n:.......................................[3]:\n','\n',char(10)),'SuperWHO.DOC','',NULL,'auto-added',38962,23,0,NULL,NULL,'fld_sw10','scan',1780048524);
INSERT INTO door_catalog VALUES('fld_ud06','FLD-UD06.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/FLD-UD06.LHA','PowerUDinfo','XIM','PowerUDinfo',NULL,'MeNaCe/Flood','FLD','______________           ____ _____/  ____/______/___________\_  \ _/          ____/\_       \_ _____/   \',replace('             fLOoD /X-dIViSiON\n          ______________           ____\n    _____/  ____/______/___________\_  \\n  _/          ____/\_       \_ _____/   \\n  \__._________/_____________/_________._\\n.....:         p r e s e n t s         :...\n:     PowerUDInfo v0.60 By MeNaCe/Flood   :\n:                                         :\n: Upload/Download/Normal Status Door For  :\n:          AmiExpress, and Sigma          :\n:......................................[2]:\n','\n',char(10)),'PowerUDinfo.doc',replace(' :\n.:.... ..... ..                         ..    .\n :              _______.                                        .______.\n   · ___________\_ _  ¬| _____________   _____________   _______|     ¬|\n   :/      ________    |/      __    ¬\ /      __    ¬\ /      __      |\n   ¦.       ____/      |.       l      Y.       l      Y.       l      |\n   |:.      |  |:.     |:.             |:.             |:.          t0!|\n   `--------''  `-------^---------------^---------------^---------------''\n\n                                 presents\n\n                    PowerUDInfo v0.60 By MeNaCe/Flood!\n\n : Program Description.\n `---------------------------------------------------------------------.\n   PowerUDInfo is a small status door for Amiexpress(and Sigma)        :\n   bulletin board systems. It can be used as a replacement for the     .\n   internal ''s'' command, or as a Upload/Download File-Status door.\n   ( Look at the pictures inside the archive! )\n\n\n : Installation.\n `---------------------------------------------------------------------.\n   To install the door itself:                                         :\n   Just copy the files in the drawer ''BBS/DOORS'' into you Doors:       :\n   Assignment.\n\n   To install it as an Upload-status door:\n   Copy the file from BBS/Commands/SysCmd/Upload.info to               .\n   BBS:Commands/SysCmd, and modify/create UploadMsg.txt(.gr)\n   --- C U T ---\n   ~\n   ~CC_Upload\n   --- E N D --\n\n   To install PowerUDInfo as a Download door:\n   Copy the file BBS/Commands/SysCmd/Download.Info to BBS:Commands/SysCmd\n   and modify/create DownloadMsg.txt(.gr)\n   --- C U T ---\n   ~\n   ~CC_Download\n   --- E N D --\n\n   If you want it as a normal status door:\n   Copy BBS/Commands/BBSCmd/S.info to BBS:Commands/BBSCmd/\n .\n . Thats all\n `---------------------------------------------------------------------.\n   This is one of my oldest doors, and it shows.. It havn''t got any    : \n   fancy features like PowerPager, or PowerComment, ( well it got one: .\n   if you have ansi codes in you BBS-Name it will strip ''em, most other.\n   doors just make a heck of a mess :). But use it if you like, and if\n   you got any ideas please contact me asap.\n\n','\n',char(10)),NULL,'auto-added',37239,3,0,NULL,NULL,'fld_ud06','scan',1780048524);
INSERT INTO door_catalog VALUES('fld_ulb','FLD-ULB.LZX','~/Code/amiexpress_doors/Archives/AmiExpress/FLD-ULB.LZX',NULL,'XIM','ULbye',NULL,NULL,'FLD',NULL,NULL,NULL,NULL,NULL,'auto-added',18046,0,0,NULL,NULL,'fld_ulb','scan',1780048524);
INSERT INTO door_catalog VALUES('fld_ulb0','FLD-ULB0.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/FLD-ULB0.LHA','ULbye','XIM','ULbye',NULL,'|','FLD','._)  _/__)   /  ._)  _ (_._)  _ (_._)  _ \ |    ._/   _/___|    /   |    /   |    /  \ |____| |__ \    |________|________|__      |',replace('  _____  _____    ______   ______   _____ \n._)  _/__)   /  ._)  _ (_._)  _ (_._)  _ \\n|    ._/   _/___|    /   |    /   |    /  \ \n|____| |__ \    |________|________|__      | \n         )______|               +sD+)______|\n                                           |\n|   Logoff After Upload - Cool door by     |\n|  Genius/Flood. Supports /X and s!x       |\n|                                          |\n`[12-Aug-96]--------------------------[243]''\n','\n',char(10)),'ULbye.doc',replace('\n     _\n   ._)\  _______________________________.\n   |   \/                               |\n   |  .....................             |       f · L · O · o · D\n   |  :          ________ :             |\n   |  :  _______/  _____/_:___________  |          /X division    _____\n  _|__:_/   ___/__ \_        \_  __   \_|____________     ________\_   \\n_/           ____/____________/  \          /   __   \___/   ______/    \\n\_____________/           : \______________/    \       \________________\\n      :                   :..  .........|.\________________/(rLf)/-T   ...\n      :             .....   :  :        |:.    .....                ...:.:\n      :       ......:   :...:..:        | :     :  :...........     :\n    ..:.......:.............:           | :.....:           :.:.....:...\n....:         :                         |____:_______________________:__ _\n:.:           .                          ....:                       :....\n:                                        :.........presents..........::\n:\n:          U L b y e   v 1.0   coded by Genius / FLD    ©mP!1996\n:          \n:.................................................................. . .\n                                                                           \n\n\n\n                           .:General information:.                         \n\n                         (___                   ___)\n                            /___________________\\n\n\n  Yeah! yet another "logoff after upload" door... yes- tired of them right?\n  well... try it anyway - it works! and mabye u''ll like it better then all\n                                 the others!\n\n\n                                .:Features:.                               \n\n                         (___                   ___)\n                            /___________________\\n\n\n   FULL compatible with multinode boards, that means - if a user on node 1\n selects to logoff after uploading, it''s ofcoz wont affect a user uploading\n on node 2... "What else?" ya say, well - i''ve seen sum doors like this, who\n   just put a file in ram: called LOGOFF_YES and then just logs off after\n    it''s being executed in filecheck ect.. well, stupid - coz'' that means\n        users on node 2 ALSO goes.. even though he did''nt select it!\n\n                 Well, anyway..  try it... or... don''t... 8)\n\n\n                              .:Installation:.                             \n\n                         (___                   ___)\n                            /___________________\\n\n\n     There''s icons with the package ( in Installstuff/ ) just copy them\n          to the right dirs.. you know the drill, you are a sysop!\n\n                            It''s NOT that hard...\n\n    (Basically I just don''t type 50 miles of doc'' for a door that took me\n    10 mins. to complete AND test.. so.. yeah.. figurer it out yaself..)\n\n\n                                               ·\n                          .---------------------\-.\n                          |·                     \|\n                          :                       \ \n                          |                       |\\n                          :      .:gREETS:.       :~\n                         _|        ______         |\n                         \:                       :\n                          \                       |\n                          :\                     ,:\n                          `/----------------------''\n                          ·                        \n\n             CoOL /X cOdERS:.          mENACE · Chrome · Jawlog\n\n             CoOL sYSdEViLS:.          Hellride · Cybersoul \n                                       Chevy · 2PAC · Seahawk  ect.\n\n         sPECiAL tHANX 2 aLL tHE pEOPLE, wHO wAS bETATESTERS 4 mE!!!\n\n             CoOL aLLRoUND gURU''s:.    mELOMANiAC · sUNDOWN\n\n\n                      sPECiAL yOHO 2 aLL fLOoD mEMBERS\n                      ________________________________\n\n\n\n\n\n\n\n\n                           .: How to contact me :.\n\n                         (___                   ___)\n                            /___________________\\n\n\n                                                                           \n                                                                           \n                   .-----------.                                           \n   .--^----·-------|\  _____  /|-----^^--------.  .-----------------^--.   \n   |·              | \ \ ! / / :              ·|  |·                  ·!   \n   |______________ |  \ \_/ /  : ______________|  | hAMSTARZ   wORLDhQ |   \n   |\_____       ·)| `_\___/_'' |(·      ______/|  :                    |   \n_ _|_¯\         // | (_\`-''/_) : \\         /¯_|__| pLAZTiQUE  wORLDhQ |   \n\\\_   \____   ((__|  ¯¯| .¯¯  |__))  _____/   __/|                    |   \n ¯ |·   ¯\___   ·--| .  : :    |--·  ____/¯    |  ! tWiLiGHT      dKhQ |   \n   |:.    ¯\_      `(_  `^'' __)''      _/¯     _|_ _                    |   \n   |:::.    \____   /|   "  ¯:\    ___/        _///                    |   \n   |:::::.   ¯¯\_  _)|__·_.__|(_   _/¯         | ¯. nD1   +45-39902992 |   \n   |:::::::.    `--'' || : | || `---''     ·©mP!·|  | nD2   tELNETtRYiRC |   \n   :·················`^-^-^-^''·················:  | nD3   tELNETtRYiRC |   \n   |._________________________________________.|  | nD4   ...cOMMiNG!! :   \n   ||__ _____!  |  .  |  ____  _  )  ______!  || _|_                   |   \n   ||  \  |  \  |  |  |  --''|  _  |  |  |  \  || \_                    |   \n   |`-----^-----^--^--^-----^--\__!-----^-----''|  | sYS: gENiUS/fLD   _|__ \n   |   :¯¯|_____________  _________________:¯¯||  |                    __/ \n   |.__|_ |  ____  .  | \/  _____ |  _  )  |  ||  | 0-1 dAY wAREZ oNLY |   \n   || __/ |  --''|  |  |·  / |  _/ |  _  |    -:|  | aMY & el|7e   oNLY_|_ _\n   |`-----^-----''--^--''-\/--^-----^--\__!--^--''|  |·                   _///\n   `---·---^^--^-------------------^-----------''  `--·-------^^-^------'' ¯ \n\n               Well, this is the quickest way.. call my board!\n\n       If you don''t want to do THAT.. well, you can mail me at one of\n                               there adresses:\n\n\n                        Email......... not availble 4 u!\n\n                        Fidonet....... 2:236/112.5\n\n                        Amiganet...... 39:141/145.5\n\n                        HOAnet........ 10:1/26.5\n\n                        Scenenet...... 245:3/0.5\n\n\n               Or leave a messy at one of FLOODs danish sites!\n                       Or try finding gNS^fLD on IRC!\n\n\n\n','\n',char(10)),NULL,'auto-added',20920,1,0,NULL,NULL,'fld_ulb0','scan',1780048524);
