INSERT INTO door_catalog VALUES('fsh_ad10','FSH_AD10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/FSH_AD10.LHA',NULL,'XIM','__________',NULL,NULL,'FSH','_\____ :  /_______               :    : /___/_\__   /________       ª    ª ___/    _/ _/_\___   / ______|___ |',replace(' __________                                 \n_\____ :  /_______               :    :     \n     /___/_\__   /________       ª    ª     \n    ___/    _/ _/_\___   / ______|___ |     \n    |  :    \   \_  _/  /__\_ ______/ |____ \n____|  :     \   /  \__/__|____ \|    |__  |\n       : _ ___\ /       \     /  \_   __/  |\n       :  Fesh :_ _______\   /    /   |    |\nFRESH EPAD v1.o BBS AD D/L\______/____|____|\nAmiexpress /X 2.x and V3.x\n','\n',char(10)),'EPAD.Doc',replace('                    fRESH EPAD v1.0 - First Release\n         Copyright © 1993 by WHiZ/fRESH/eNDLESS pIRACY/tHERAPY\n                    PSYCHo TeRMiNaL +1-914-682-1975\n\nInstallation:\n-------------\n\n   1. Create a dir in Doors: Called EPUtils\n   2. Create a dir in Doors:EPUtils Called EPAd\n   3. Create a dir in Doors:EPUtils/EPAd/ Called Ads\n   4. Copy the File EPAD.Rexx to Doors:EPUtils/EPAd/\n   5. Copy your BBS Ads to Doors:EPUtils/EPAd/Ads/\n   6. Copy the AD.icon to dir BBS:Commands/BBSCMD/\n\n   NOTE: You Need To Have RPSTART Running!\n\n   THE FOLLOWING FILES >MUST< BE IN YOUR C: DIR\n\n   - Filenote (To Make All Your AD''s Free Download :) )\n   - Delete   (To Delete The TempFile in T: Dir)\n   - List     (To List The BBS Ad''s)\n\nWhat this Util does:\n--------------------\n\n   With this Tool your Users can download as many BBS Ads as you have!\n\n   When a User has downloaded an Ad the Ad Name will be written into\n   the Callerslog!\n\n   That''s it. Very easy, eh!?\n\nBugs:\n-----\n\n  - No known Bugs so far. Thanx to Link&H2o for the Mini-Beta-Test :)\n\nCompatibility:\n--------------\n\n  This Utility has been tested on /X v3.17.\n\n  Dunno if it''ll work on /X v2.x.\n  Try it yourself and if not, please lemme know!\n\nHistory:\n--------\n\n  v1.0  10-03-93  Release Version.\n\nGreetingz fly out the following guyz:\n-------------------------------------\n\n  The Champ/S8 - Der Chat-Marathon ruft!\n  Hot Kid!\n  THe SiLeNCeR/TRSI\n  MuMu/iNDY - Call Mal Wieder, is ja schließlich umsonst, oda?\n  Halfast/SCX\n  Mr Hyde/TRY\n  DNSS/TRY/F^I - Kewl AzKiis! Don''t forget my Grandma :)!\n  WaRLoRD - Fötzchenpower ''93!\n  Freddy Krueger\n  The Fly/TRY - The Drunken Fly strikes back!\n  Will Scarlett/OTL - Are you going to call me or what?\n  Franky/TRY\n  Godhead/QTX - Thanx for the cool logo!\n  Buster & Fuzz/FOFT - Germania Conf Sysop isn harter Job!\n  Link^H2o/Fresh/F^I - Coole Azkiis! HD Fuck-Up Ruhlt!\n  Joker/TSL - Ruf doch mal an!\n  Dalai Lama/GOD\n  EXoCET^ARCLiTe - Coole Logos!\n  SHADOWMAN\n  ALCAPONE\n  (-sLAZeR`) - Lang nix mehr von dir gehört!\n  Schwabenpower\n  Radar\n  Red Alert - Netmail ruhlt!\n\n  and of course to all fRESH, eNDLESS pIRACY & tHERAPY mEMBERS wORLDWIDE!\n\n  Feel free to contact me on pSYCHO tERMINAL for suggestions and/or bugs!\n             Or get a hold on me via AmiXnet (WHiZ@203001).\n\nClick...\n','\n',char(10)),NULL,NULL,24862,6,0,NULL,NULL,NULL,'scan',1780048524);
INSERT INTO door_catalog VALUES('fsh_ms10','FSH_MS10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/FSH_MS10.LHA','ChamPlay','XIM','__________',NULL,NULL,'FSH','_\____ :  /_______               :    : /___/_\__   /________       ª    ª ___/    _/ _/_\___   / ______|___ |',replace(' __________                                 \n_\____ :  /_______               :    :     \n     /___/_\__   /________       ª    ª     \n    ___/    _/ _/_\___   / ______|___ |     \n    |  :    \   \_  _/  /__\_ ______/ |____ \n____|  :     \   /  \__/__|____ \|    |__  |\n       : _ ___\ /       \     /  \_   __/  |\n       :  Fesh :_ _______\   /    /   |    |\nfRESH MoDSaM v1.o\______/____|____|\nmEGACOOL pAGER! /X 2.x and V3.x\n','\n',char(10)),'MoDSaM.Guide',replace('@database MoDSaM.Guide\n\n@Remark "$VER: MoDSaM v1.o (11.Nov.93)"\n@Remark "Document for MoDSaM v1.o"\n\n@node Main "MoDSaM v1.0 - © ''93 by WHiZ/fRESH/eNDLESS pIRACY/tHERAPY"\n \n              fRESH /X dEVISION iN ''93 pRESENTS: MoDSaM v1.o\n              ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n                       @{" ·      aBOUT MoDSaM      · " Link Intro}\n                       @{" · iNSTALLATION pROCEDURE · " Link Install}\n                       @{" ·         hISTORY        · " Link History}\n                       @{" ·        gREETINGS       · " Link Greetings}\n                       @{" ·  HOW TO GET IN TOUCH!  · " Link Touch}\n\n@endnode\n\n@node Intro "Introduction to MoDSaM"\n\n  When the Sysop is NOT available for Chatting the User has the Choice\n  to leave you a comment or Return to the Main Prompt.\n  If the User left you a Comment a line will be added to the Callerslog\n  informing the Sysop at which time the User tried to page the Sysop.\n  \n  ======================================================================  \n\n  When the Sysop is available for Chatting the User has the following\n  Choices:\n\n                        @{" ·     SAMPLE     · " Link Sample}\n                        @{" ·     MODULE     · " Link Module}\n                        @{" · INTERNAL PAGER · " Link Internal}\n                        @{" ·      TIME      · " Link Time}\n                        @{" ·      MENU      · " Link Menu}\n                        @{" ·      QUIT      · " Link Quit}\n    \n\n                        @{" ·   MAIN MENU!   · " Link Main}\n@EndNode\n\n@Node Sample\n\n  If the User wants to page the Sysop with a Sample the User can choose one\n  from upto 7 Samples (depends how many Samples the Sysop has installed),\n  go back to the Main Menu or Quit. If the User decides to page you with a\n  Sample the number of the Sample will be added to the Callerslog and the\n  User will be put back to the Main Prompt.\n\n                          @{" ·   MAIN MENU!   · " Link Main}\n\n@EndNode\n\n@Node Module\n\n  If the User wants to page the Sysop with a Module the User can choose one\n  from upto 7 Modules (depends how many Modules the Sysop has installed),\n  go back to the Main Menu or Quit. If the User decides to page you with a\n  Module the Module will be played until the User presses Return.\n  The number of the Module will be added to the Callerslog.\n\n                        @{" ·   MAIN MENU!   · " Link Main}\n\n@EndNode\n\n@Node Internal\n\n  Loads the AmiExpress Internal Pager.\n\n                        @{" ·   MAIN MENU!   · " Link Main}\n\n@Endnode\n\n@Node Time\n\n  Displays the current Time and Date.\n\n                        @{" ·   MAIN MENU!   · " Link Main}\n\n@EndNode\n\n@Node Menu\n\n  Displays the Main Menu.\n\n                        @{" ·   MAIN MENU!   · " Link Main}\n\n@EndNode\n\n@Node Quit\n\n  Quits back to BBS.\n\n                        @{" ·   MAIN MENU!   · " Link Main}\n\n@EndNode\n\n@Node History\n\n  v0.1ß 02-02-93  Test Version.\n  v1.0  02-06-93  First Official Release.\n  v1.0a 03-02-93  Changed Callerslog Entries and Cosmetics.\n                  Implemented Sample-Text-File into Source Code.\n  v1.1  03-09-93  Second Official Release - Minor Changes.\n  v1.2  05-04-93  Internal Update - Minor Changes.\n  v2.0  05-14-93  Internal Update - Added New Feature.\n  v2.1  05-26-93  Internal Update - Added New Features and improved Source\n                  Code.\n  v2.2  06-20-93  Internal Update - Modified Callerslog Entries.\n  v2.5  09-06-93  Modified Callerslog Entries, Cosmetics and improved Code.\n  v3.0  09-19-93  Improved Code and added Page Checking!\n  v3.1  09-29-93  Minor Update!\n  v3.3  10-04-93  Changed Callerslog Entries!\n                  ''Sysop Paged'' will now be displayed in Last Callers Utils.\n  v4.0  10-05-93  Added ''Pages Remaining'' (Idea by Joker) and fixed ''Quit-Bug''!\n  v4.1  10-06-93  Fixed a few Bugs and changed cosmetics.\n  v4.2  10-11-93  Fixed a Bug, improved cosmetics and added Config Creator.\n  \n  v1.0  11-06-93  Added Module Paging and is now fully configurable!\n                                        -> MoDSaM <-\n\n                        @{" ·   MAIN MENU!   · " Link Main}\n\n@EndNode\n\n@Node Greetings\n \n  The Champ//S8 - Der Chat-Marathon ruft!\n  Hot Kid!\n  THe SiLeNCeR//TRSI\n  MuMu//iNDY - Call Mal Wieder, is ja schließlich umsonst, oda?\n  Halfast//SCX\n  Mr Hyde//TRY\n  DNSS//TRY//F^I - Kewl AzKiis! Don''t forget my Grandma :)!\n  WaRLoRD - Fötzchenpower ''93!\n  Freddy Krueger\n  The Fly//TRY - The Drunken Fly strikes back!\n  Will Scarlett//OTL - Are you going to call me or what?\n  Franky//TRY\n  Godhead//QTX - Thanx for the cool logo!\n  Buster & Fuzz//FOFT - Germania Conf Sysop isn harter Job!\n  Link^H2o//Fresh//F^I - Coole Azkiis! HD Fuck-Up Ruhlt!\n  Joker//TSL - Hier haste wieder ein neues Spielzeug hehe.\n  Dalai Lama//GOD\n  EXoCET^ARCLiTe - Coole Logos!\n  SHADOWMAN\n  ALCAPONE\n  (-sLAZeR`) - Lang nix mehr von dir gehört!\n  Schwabenpower\n  Radar\n  Red Alert - Netmail ruhlt!\n\n  and of course to all fRESH, eNDLESS pIRACY & tHERAPY mEMBERS wORLDWIDE!\n\n                        @{" ·   MAIN MENU!   · " Link Main}\n\n@EndNode\n\n@Node Touch\n   \n           ·pSYCHo tERMINAl· fRESH wHQ  +1-914-682-1975\n\n               ·nEO gEO·     fRESH gHQ  +49-02-pR¡VATE\n   \n              ·pARANO¡A·     fRESH eHQ  +49-53-cALL ¡T\n\n              ·mEVS-rOOM·    fRESH tHQ +090-85-pR¡VATE\n\n \n   Feel free to contact me on pSYCHO tERMINAL for suggestions and/or bugs!\n             \n            Or get a hold on me via AmiXnet (WHiZ@203001).\n\n\n                        @{" ·   MAIN MENU!   · " Link Main}\n\n@EndNode\n\n@Node Install\n \n  MoDSaM has been tested with /X v3.x. Dunno if it''ll work on /X v2.x.\n  Try it yourself and if not, please lemme know!\n\n  1. Create a dir in Doors: Called EPUtils\n  2. Create a dir in Doors:EPUtils/ Called MoDSaM\n  3. Copy ALL Files from the archive in Dir BBS:Doors/EPUtils/MoDSaM/\n     to Doors:EPUtils/MoDSaM/\n  4. Copy upto >7< Samples to Doors:EPUtils/MoDSaM/\n     Copy upto >7< Modules to Doors:EPUtils/MoDSaM/\n     All Modules and Samples over 7 will be ignored!\n  6. Rename your Samples to Sample.1, Sample.2 etc.\n     Rename your Modules to Module.1, Module.2 etc.\n\n                 NOTE: You Need To Have RPSTART Running!\n\n  If no Config File exists MoDSaM will prompt you with a Config Creator.\n  Please enter how many times a User may page you.\n\n  Edit the Files Module.CFG & Sample.CFG! with your favourite TextEditor.\n  Enter the names of the different Modules and Samples. If you have\n  less than 7 Modules or Samples, MoDSaM will display NOT USED instead\n  of the Names.\n\n                        @{" ·   MAIN MENU!   · " Link Main}\n\n@EndNode\n','\n',char(10)),NULL,NULL,110305,6,0,NULL,NULL,NULL,'scan',1780048524);
INSERT INTO door_catalog VALUES('fth_fdd','FTH-FDD.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/FTH-FDD.LHA','rexxdoor','XIM','REXXDOOR','1.','dR.dRE!','FTH',NULL,replace('File Dir Download v1.o  Door 4 /X by dR.dRE!\n','\n',char(10)),'DirDl.Guide',replace('@database File Dir Download v1.o\n\nCopyright (C) 1993 by dR.dRE! / FAITH, Germany\nAll Rights Reserved\n\n@Remark $VER: Version v2.o (Dez 15 1993, 11:32:54)\nRemark AmigaGuide DataBase for File Dir Download v1.o by dR.dRE!\n\n@node MAIN "File Dir Download v1.o (Dez 11 1993, 11:32:54) AmigaGuide Document for /X"\n\n                   _____________/\_____________________l\__\n                   \      _______ \______)        /    l   \\n                   /     _____/ /  \     \      \/          \\n                  /         \       \     \      \     _     \\n                _/           \       \     \_     \_   l      \_\n                \_____________\__/    \_____/______/   l_______/\n              -=================/______\dRE!===/_______l=========-\n      is proud to present: File Dir Download v1.o (Dez 15 1993, 11:32:54)\n\n\n\n                         @{"     Introduction      " Link file1}\n                         @{"     Requirements      " Link file2}\n                         @{"     Installation      " Link file3}\n                         @{"     Options Help      " Link file4}\n                         @{"      The NDIRS!       " Link ndirs}\n                         @{"      Greetings!       " Link file5}\n                         @{"       Creditz!        " Link file6}\n                         @{"     FAITH BOARDS!     " Link file7}\n\n\n@endnode\n@node file1 "Introduction to Most Wanted v1.o"\n\n                         · [ · INTRODUCTION · ] ·\n\nFile Dir Download (FDD) is a really use and powerfull File Dir Downloader.\nIt contains many good Options.\nThe Door will display the Filehelp.txt(.gr) in the actual Conference, so\nthe User can see what Filedir contains which Date or Files.\nIt reads the NDIRS from the actual Conference, and knows how many Dirfiles\nare in the Conference.\nYou can D/L only one Dirfile or all, the Door packs the Files with Lha and\nmakes it Free D/L!\nThe Name from the D/L Files is in each Conference another, so it is not\npossible to D/L the same File, and the User can D/L the File Dirs at one\nin every Conference he has Access to...\n\nThis Door contains 1oo% no Backdoors in any Kind, if you dant belive this, so\ncall my BBS and get there an uncompiled Version of `FDD` !\n\nIf you have an A4ooo or A12oo and the Door doesn`t work so Call my BBS under\n49 (0) 2131 275756 or 575634 for an uncompiled and registered Version!\n\nAlso call for some good ideas for another Doors or some Special Private\nDoors for your own BBS.\n\nBut now enjoy this really fine door...\n      \n  _dR.dRE!_of_fAITH!_  \n\n@endnode\n@node file2 "Requirements"\n\n                         · [ · REQUIREMENTS · ] ·\n\nAll what you need is any Model of an AMIGA OS2.o or higher!\nAmiExpress 2.xx - 3.xx\nA running RPSTART in your Startup-Sequence\nIn your Libs: Directory these Librarys\nRexxplslib.library\nrexxplsextnd.library\nrexxsupport.library\nrexxsyslib.library\n\nThe Archive includes all Librarys thats you need.\nA Directory in your BBS: called Doors (NOTE: Doors: must be assigned)\n\nThat all...\n\n@endnode\n@node most3 "INSTALLATION"\n\n                         · [ · INSTALLATION · ] ·\n\nUnpack the Archive to your RAM Disk and copy all Files in the right Directory\non your Harddrive.\n\nIf you have running /X 3.xx you have to do nothing anymore, the Door is after\nthe copying successfull Installed.\n\nIf you have running /X 2.xx edit your BBS:COMMANDS/BBSCMD File and add this to\nthe Command File.\n+---------cUT hERE----------+\n*DIRDL    RM050DOORS:WANT.REXX\n+---------cUT hERE----------+\n\nThats all, the Door is Installed now.\n \n...have Phun!...\n\n@endnode\n@Node file4 "OPTIONS HELP"\n\n                         · [ · OPTIONS HELP · ] ·\n\nThe User has 2 Ways to Download the dirfiles.\n1. he can Specify the Dir File, like 1,2,3,4,etc!\n2. He can choose the All Options and the Door wil pack all Dirs in one\n   Archive (Lha) make it Free D/L and send it directly after packing.\n\n@endnode\n@node ndirs "The NDIRS!"\n\n                         · [ ·  THE NDIRS!  · ] ·\n\nIn each Conference is a FIle called `NDIRS` there you have to Specify the\nNumber of all DirFiles.\niE. may you have 5 DirFiles, then the NDIRS File must contain a `5` and so\non.\n\n@endnode\n@node file5 "GREETINGS"\n\n                         · [ ·  GREETINGS!  · ] ·\n\nThe Greets are going to this c00L d00DEs...\n\nByteAndi/X-Dezign, Gandalf/Faith, RiCHi/Flt, Nick, Steve/D^R, Empire/Mst\nEdo the Ancient, -rS!, \> />AMME, pBX^mCI, Triton/Faith, Skin&Amblin\nCreator, Lance, Skylark, Amicom/Pdx, Scope/Trsi, Guliver/TRSi, Flux/Fth\nAPOLLO, Chaos, KiLLrAvEN/X-Dezign, Deathbringer/Fth, Cyber Bug, J.Walker\nPunk, BJoerN/Pdy, Jive/TRSi, Foxx`n`Lynxx, Silver/Fth, AtOmIx, TroniC,\nValShare/TRSi, Mr.VAiN, Enemy/CAF, dR.dREAM/Fth, Paragon & Melvin/Fth,\nmaniac/fth, Eniac/Fth, duke & eternal/Fth, and simply all I forgot...\n\n@endnode\n@node file6 "CREDITZ"\n\n\n                          · [ ·   CREDITZ   · ] ·\n\n              Copyright (C) 1993 by dR.dRE! / FAITH, Germany\n                            All Rights Reserved\n\n             The AmigaGuide DataBase writen by dR.dRE! / FAITH\n\n    For more good Doors call my BBS under 49 (0) 2131 275756 & 275634\n               · [ · MARLEYS COFFEE SHOP - FAITH EHQ · ] ·\n\n@endnode\n@node file7 "FAITH BOARDS"\n\n                    · [ · FAITH BOARDS WORLDWIDE · ] ·\n\n                  To Contact a Call any of this Boards...\n           -==================================================-\n\n                  Horrorzone: FAITH AMIGA/CONSOLES USHQ!\n                      ++1 713-855-6370 & 7138552637\n\n                  Canadian Mist: FAITH AMIGA USHQ! 2 Nodes\n                      ++1 616-866-6964 & 6168668651\n     \n                  Los Endos : FAITH AMIGA/CONSOLES EHQ\n                          +49-202-Elite - 3 Nodes\n\n                  Radio Teheran: FAITH AMIGA GHQ [2 Nodes]\n                          +49-228-660708 & 660734\n     \n                  MARLEYS COFFEESHOP: FAITH Amiga EHQ\n                        +49-2131-Elite 2 Nodes\n\n                  IRON LAW BBS - FAITH AMIGA/CONSOLES IHQ\n                              +39-906-320-01\n\n           -==================================================-\n\n@endnode\n','\n',char(10)),NULL,'auto-added',144163,4,0,NULL,NULL,'nvx_rem5','scan',1780048524);
INSERT INTO door_catalog VALUES('fth_mw1o','FTH-MW1O.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/FTH-MW1O.LHA','message','XIM','message',NULL,'dR.dRE!·','FTH','_\___     /\__   \ _\_\__\__     /\_  |__  | /____/  _/    \_/  \    \   /     __/  | ___/     \      /    \    \_/      |    |',replace(' ________________   __   _____________.    |\n_\___     /\__   \ _\_\__\__     /\_  |__  |\n    /____/  _/    \_/  \    \   /     __/  |\n   ___/     \      /    \    \_/      |    |\n    |        \    /      \    \       |____|\n____|   _ ____\  /_ ______\____\ _ ___|-dRE:\n·::::::::::::->\/ STRIKES BACK WITH <-:::::·\n·Most Wanted v1.o Req. Door 4 /X by dR.dRE!·\n','\n',char(10)),'MOST_WANTED.GUIDE',replace('@database Most Wanted v1.o\n\nCopyright (C) 1993 by dR.dRE! / FAITH, Germany\nAll Rights Reserved\n\n@Remark $VER: Version v2.o (Dez 15 1993, 11:32:54)\nRemark AmigaGuide DataBase for Most Wanted v1.o by dR.dRE!\n\n@node MAIN "Most Wanted v1.o (Dez 15 1993, 11:32:54) AmigaGuide Document for /X"\n\n                   _____________/\_____________________l\__\n                   \      _______ \______)        /    l   \\n                   /     _____/ /  \     \      \/          \\n                  /         \       \     \      \     _     \\n                _/           \       \     \_     \_   l      \_\n                \_____________\__/    \_____/______/   l_______/\n              -=================/______\dRE!===/_______l=========-\n         is proud to present: Most Wanted v1.o (Dez 15 1993, 11:32:54)\n\n\n\n                         @{"     Introduction      " Link most1}\n                         @{"     Requirements      " Link most2}\n                         @{"     Installation      " Link most3}\n                         @{"     Options Help      " Link most4}\n                         @{"    The Config File    " Link Config}\n                         @{"      Greetings!       " Link most5}\n                         @{"       Creditz!        " Link most6}\n                         @{"     FAITH BOARDS!     " Link most7}\n\n\n@endnode\n@node most1 "Introduction to Most Wanted v1.o"\n\n                         · [ · INTRODUCTION · ] ·\n\nMost Wanted is one of the best and fastest Request Door arround.\nAll Things are free configurable, like Edit remove Eall Outputpath etc.\n1oo% No Backdoors, if you dont believe this call me and get an uncompiled\nVersion!\n\nIf you have an A4ooo or A12oo and the Door doesn`t work so Call my BBS under\n49 (0) 2131 275756 or 575634 for an uncompiled and registered Version!\n\nAlso call for some good ideas for another Doors or some Special Private\nDoors for your own BBS.\n\nBut now enjoy this really fine door...\n      \n  _dR.dRE!_of_fAITH!_  \n\n@endnode\n@node most2 "Requirements"\n\n                         · [ · REQUIREMENTS · ] ·\n\nAll what you need is any Model of an AMIGA OS2.o or higher!\nAmiExpress 2.xx - 3.xx\nA running RPSTART in your Startup-Sequence\nIn your Libs: Directory these Librarys\nRexxplslib.library\nrexxplsextnd.library\nrexxsupport.library\nrexxsyslib.library\n\nThe Archive includes all Librarys thats you need.\nA Directory in your BBS: called Doors (NOTE: Doors: must be assigned)\n\nThat all...\n@endnode\n@node most3 "INSTALLATION"\n\n                         · [ · INSTALLATION · ] ·\n\nUnpack the Archive FTH-MW1o.LHA to your RAM Disk.\nexecute the Install.script3.xx and the Script will all Install for you.\nThe ownest what you have to do, is jump into your Local Node and enjoy\nMost Wanted v1.o!\n\nIf you running /X 2.xx execute the Install.script2.xx.\n\nAfter this you have to setup your Private @{" Want.cfg " Link Config}, to conigurate\nall possible Options!\n\nThats all...\n\n@endnode\n@Node most4 "OPTIONS HELP"\n\n                         · [ · OPTIONS HELP · ] ·\n\n                         @{"       Users Menu        " Link User}\n                         @{"      Sysop`s Menu       " Link Sysop}   \n\n@endnode\n@node user "Users Menu"\n\n                         · [ ·  USERS MENU  · ] ·\n\n\n                   @{"   [1.] - Make a Valid Request       " Link 1}\n                   @{"   [2.] - View all Request`s         " Link 2}\n\n\n@endnode\n@node 1 "[1.] - Make a Valid Request"\n\n1. - Make a Valid Request\n\nHere a User can make a Valid Request.\nhe have to Enter the File or Program what he need.\nAnd Most Wanted will add this request to the Output File, after this\nthe Door write a Message to the Messagebase in the Actual Conference.\nThere are 2 Kinds of Messages are available, this you have to Setup in\nthe @{" Want.cfg " Link Config}, there you can configure the EALL Level.\nIf a User have no EALL Access in Most Wanted, the message will Posted as\na normal Public Mail, if he have the EALL Access then the Mail will Posted\nas EALL Message.\n\n@endnode\n@node 2 "[1.] - View all Request`s"\n\n1. - View all Request`s\n\nHere the Users can View all Requests, this is ingenious when you not display\nthe Outputfile as textfile in your BBS !\nElse makes this Option nothing.\n\n@endnode\n@node Sysop "Sysop`s Menu"\n\n                         · [ ·  SYSOPS MENU  · ] ·\n\n\n                   @{"   [1.] - Make a Valid Request       " Link 1}\n                   @{"   [2.] - Remove Request`s           " Link 3}\n                   @{"   [3.] - Edit Request`s             " Link 4}\n                   @{"   [4.] - View Request`s             " Link 2}\n\n@endnode\n@node 3 "[2.] - Remove Request`s"\n\nHere you can Remove any Requests form the Output File.\nEnter only the Request Number, and the Line will removed from the textfile.\n\n@endnode\n@node 4 "[3.] - Edit Request`s"\n\nHere you can Edit the Most Wanted Output File.\nUnder Supporting from the Original Message Base Editor (Also Fullscreen Ed)\nshould anybody knows how to edit the File or not ?\n\n@endnode\n@node Config "The Config File"\n\nIn the Want.cfg you can Setup the Following Options.\nLine.1=The full Path with Name from the Output File. (bbs:request/Bull50.txt)\nLine.2=The Level for making a Valid Request!\nLine.3=The EALL Level\nLine.4=The Remove Level, this allows to Remove Valid Request`s\n\n@endnode\n@node most5 "GREETINGS"\n\n                         · [ ·  GREETINGS!  · ] ·\n\nThe Greets are going to this c00L d00DEs...\n\nByteAndi/X-Dezign, Gandalf/Faith, RiCHi/Flt, Nick, Steve/D^R, Empire/Mst\nEdo the Ancient, -rS!, \> />AMME, pBX^mCI, Triton/Faith, Skin&Amblin\nCreator, Lance, Skylark, Amicom/Pdx, Scope/Trsi, Guliver/TRSi, Flux/Fth\nAPOLLO, Chaos, KiLLrAvEN/X-Dezign, Deathbringer/Fth, Cyber Bug, J.Walker\nPunk, BJoerN/Pdy, Jive/TRSi, Foxx`n`Lynxx, Silver/Fth, AtOmIx, TroniC,\nValShare/TRSi, Mr.VAiN, Enemy/CAF, dR.dREAM/Fth, Paragon & Melvin/Fth,\nmaniac/fth, Eniac/Fth, duke & eternal/Fth, and simply all I forgot...\n\n@endnode\n@node most6 "CREDITZ"\n\n\n                          · [ ·   CREDITZ   · ] ·\n\n              Copyright (C) 1993 by dR.dRE! / FAITH, Germany\n                            All Rights Reserved\n\n             The AmigaGuide DataBase writen by dR.dRE! / FAITH\n\n    For more good Doors call my BBS under 49 (0) 2131 275756 & 275634\n               · [ · MARLEYS COFFEE SHOP - FAITH EHQ · ] ·\n\n@endnode\n@node most7 "FAITH BOARDS"\n\n                    · [ · FAITH BOARDS WORLDWIDE · ] ·\n\n                  To Contact a Call any of this Boards...\n           -==================================================-\n\n                  Horrorzone: FAITH AMIGA/CONSOLES USHQ!\n                      ++1 713-855-6370 & 7138552637\n\n                  Canadian Mist: FAITH AMIGA USHQ! 2 Nodes\n                      ++1 616-866-6964 & 6168668651\n     \n                  Los Endos : FAITH AMIGA/CONSOLES EHQ\n                          +49-202-Elite - 3 Nodes\n\n                  Radio Teheran: FAITH AMIGA GHQ [2 Nodes]\n                          +49-228-660708 & 660734\n     \n                  MARLEYS COFFEESHOP: FAITH Amiga EHQ\n                        +49-2131-Elite 2 Nodes\n\n                 