INSERT INTO door_catalog VALUES('gnt_act3','GNT-ACT3.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/GNT-ACT3.LHA',NULL,'XIM','______________  _____________',NULL,NULL,'GNT','.\_  ________  \/  _         /.  /X doors | /  \_   \/ \  \  \\_/   \_/ |  zOOTiLITY _/    /    \_ \     \_     \_ `------------.',replace(' ______________  _____________\n.\_  ________  \/  _         /.  /X doors\n| /  \_   \/ \  \  \\_/   \_/ |  zOOTiLITY\n_/    /    \_ \     \_     \_ `------------.\n\___________/__\_____/______/ [gENETIC ''96!]\n|                                          |\n|        ZOOACTIVITY v3.00  31-08-96       |\n|                                          |\n|  100% assembly ! create single and all   |\n|  nodes activity bulletin! for /X & S!X.  |\n`--[screenshots inside!]------------[one]--''\n.------------------------------------------.\n| features:                                |\n|                                          |\n| + 100% assembly, small and fast          |\n|   just 6892 bytes of executable!         |\n| + no aedoor.library needed               |\n| + creates single node bulletins for      |\n|   NODE activity AND an allnodes bulletin |\n|   for BOARD activity                     |\n| + no need to keep your callerslog!       |\n| + totally configurable for every node!   |\n| + shows total calls and avarage per day  |\n| + just one of the cooles utils ever!     |\n|                                          |\n|     call zooropa now to register !       |\n|                                          |\n| visit our homepage:                      |\n|                                          |\n|     www.hio.hen/~schonewi/index.html     |\n|                                          |\n|                                          |\n`--------------------[+31-(0)53-4328902]---''\n','\n',char(10)),'mastrb8.txt',replace(replace('STILL GOING STRONG in 2014!\r\n\r\n                ___         ._            _______             ·\r\n   /\  _________)  \________| \