INSERT INTO door_catalog VALUES('god_bs15','GOD-BS15.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/GOD-BS15.LHA',NULL,'XIM','Best-Scan.XIM',NULL,'CALYPS0/G0D','GOD','\____/   ______//    /  \\______   \____/ \_/    \_   \/    /\   \|    |\   \_/ \     |    \    \/   /|   /\/   /',replace('  ______/\________ _____/\ ________________\n  \____/   ______//    /  \\______   \____/\n    \_/    \_   \/    /\   \|    |\   \_/\n      \     |    \    \/   /|   /\/   /\nEXPRESS\__  _____/\_______/ |___\  __/DESIGN\n<---------\/- ·p·R·E·S·E·N·T·S· -\/-------->\n       Best-Scan V1.5 by CALYPS0/G0D !\nThe FASTEST and BEST-LOOKING Newfiles Door !\n New Update ! Now it is FREEWARE ! Use it !\n  ASM XIM POWER ! Why use something else ?\n<------------------------------------------>\n','\n',char(10)),'Best-Scan.Doc',replace('                                    .    :\n.______ ______________.   __________|    |____ __________ _____. __________.\n|:::· ·/    _____     |__/__  _    ¬\     _  ¬\______   ¬\     |_____· ·:::|\n|:·  _/    |    ¬\_   |    ¬\_ |     \_  |     \_         \_   |    ¬\_   :| \n|·   \     |      /   |      / |      /  |  ÷e÷ /   |      /   |      /_ _·|\n|.  .\\__________/__________/________/_________/__________/__________//   .|\n|             .__                        .    ·                            |  \n|  _______ ___| ¬\ ________ _________ ___|    :_______  _________________  |\n: /  _   ¬\   |   \       ¬\_____   ¬\  _     ¦  _   ¬\/     ____       ¬\ :\n_/    |    \_ |    \_  |    \_ _/   _/   |    :   |    \____    ¬\_  |    \_\n\     |     / |     /  ______/ \    \__  |    :   |     /   |     /  ______/\n:\_________/_______/____________\     /_______¦________/_________/_______ _: \n+--------------------------------\___/-------------------------------------+\n¦                                                                          ¦\n:                                                                          :\n                                    PRESENTS\n\n                    Best-Scan V1.5 coded by CALYPSO/GOD !\n\n    PROFESSIONAL TOOLS FOR PROFESSIONAL SYSOPS - GET THE REAL QUALITY !\n\n\nWHAT''S THE USE OF THIS TOOL ?\n-----------------------------\n\n        This is the FASTEST and BEST-LOOKING newfiles door ever !!!\n\n        It can be used as N and F command !\n\n        Fully configurable !\n\n        You will LOVE it !\n\n  .-----------------------------------------------------------------------.\n  |       PLEASE READ THE REGISTER!.TXT INCLUDED IN THIS ARCHIVE !!!      |\n  `-----------------------------------------------------------------------''\n\n        I think it''s worth to register my utils... they are the BEST\n        and so thank me for my work, dudes ! (not very expensive)\n\n        If you think it''s not necessary, then you can wait long\n        for an update ! Will make updates probably for registered\n        users only !\n\n\n	Note : This door is 68020+ optimized !\n	------\n\nHOW TO INSTALL :\n----------------\n\n        S-Express and /X 2.x :\n        ----------------------\n\n        Copy these files in the archive to your directories,\n        they are :\n\n        BBS:Doors/Best-Scan/Best-Scan.Config\n        BBS:Doors/Best-Scan/Best-Scan.Doc\n        BBS:Doors/Best-Scan/Best-Scan.Help\n        BBS:Doors/Best-Scan/Best-Scan.XIM\n        LIBS:AEDoor.library (© Sintax)\n\n        Append the BBS:Commands/BBS.CMD to your BBS.CMD !\n\n        If you use a 0.38x version of S-Express then copy also\n        the ''Best-Scan.XIM'' as ''NewFiles'' to your BBS:System Dir !\n\n        \n        /X 3.x :\n        --------\n\n        Copy these files in the archive to your directories,\n        they are :\n\n        BBS:Doors/Best-Scan/Best-Scan.Config\n        BBS:Doors/Best-Scan/Best-Scan.Doc\n        BBS:Doors/Best-Scan/Best-Scan.Help\n        BBS:Doors/Best-Scan/Best-Scan.XIM\n        BBS:Commands/BBSCMD/N.Info        \n        BBS:Commands/BBSCMD/F.Info        \n\n	If you don''t have it : Create a file called ''NDirs'' in every\n	Conference with the Number of Dirs you have, e.g. :\n\n	------------(cut here)-------------\n	2\n	------------(cut here)-------------\n\n\n        No worries, the door refers to DOORS: , so you can put\n        your doors wherever you want !\n\n\n        Now take a look at the Best-Scan.Config :\n\n\n        ------------(cut here)-------------\n        255                                     ; Access Level for Hold Dir !\n        [0m                                    ; Filename Color\n        [35m                                   ; Flag Color (P/N)\n        [33m                                   ; Size Color\n        [36m                                   ; Date Color\n        [0m                                    ; Description Color\n        [35m ~\/\)=====[[32m Black Moon [35m]====(/\/~ [36m@@-@@-@@ [35m~\/\)====[ [32mBlack Moon [35m]=====(/\/~\n         [32m-+[35m( [33m@@ [35m)[32m+-[0m \n        ------------(cut here)-------------\n        \n        The next-to-last line is the line you want to show when a new day\n        begins ! It MUST include the ''@@-@@-@@'' cause this will\n        be replaced by the date !\n\n        The last line is the text shown on flag-by-number... this\n        text has to be 10 chars without the colorcodes !!!\n        ''@@'' will be replaced with the filenumber !\n\n        If you upgrade from V1.0 then be sure to change your config !\n        \n\n        Next you should make ALL (in every conference) your\n        File-Help.txt(.gr) e.g. in this way :\n\n-------------------------------(cut here)--------------------------------\n\n          Dir 1 ----> Deleted files !\n\n          Dir 2 ----> Files online !\n-------------------------------(cut here)--------------------------------\n\n        Means for every directory you have, you need a blank line and\n        then the description to the directory (2 lines for each\n        directory) !\n\n        I think you got it... if you make it in an other way it will look\n        ugly !\n        \n        So you are ready to go ! Enjoy !\n\n  .-----------------------------------------------------------------------.\n  |       PLEASE READ THE REGISTER!.TXT INCLUDED IN THIS ARCHIVE !!!      |\n  `-----------------------------------------------------------------------''\n\nDOOR FEATURES:\n--------------\n\n        I think you will see by yourself.. here some hints which\n        are not seen on the first look :\n\n        Default Dir is U, so it''s enough when you write ''N S'' or ''N -1'' !\n \n        Use option S (e.g. N S U S) to show single line mode ! This\n        will show only the first line of each description !\n\n        Use option NS (e.g. N T NS) to scroll Non-Stop !\n\n        Use option # (e.g. N S #) to use flag-by-number !\n\n        All special commands can be stacked, e.g. :\n\n                N S U NS #\n             or N T # NS\n             or whatever you like...\n\n        On wrong inputs Best-Scan shows the Help-Page !\n\n\n        At the prompt use these commands :\n \n        C - Clear Screen and continue scrolling (fucking fast) !\n        N - Stop scrolling !\n       NS - Switch to Non-Stop scrolling !\n        F - Flag Files ! Use SPACE to separate filenames/numbers !\n            (Write perhaps an EALL, some users don''t recognize this !)\n        V - View a special file ! (Done for Big Boss, hi mate !)\n\nLAST WORDS :\n------------\n        \n        Now have fun with this great tool !\n\n        For Bugs (there are none), Ideas (yeah !) or just for fun\n        call my BBS :\n\n                 bLACK m00N            G·O·D GERMAN HEADQUARTERS !        \n                ~~~~~~~~~~~~     \n               +49-7071-51144         L^O^G^I^C wORLDHEADQUARTERS !\n                                    iLLUSION/gELBSUCHT hEADQUARTERS !\n          (3x 16.8 Dual Ringdown)   bIZARRE fASCINATION hEADQUARTERS !\n\n          Current NUP : ANALYSIS\n\n        See ya soon mates...\n                                                   Calypso !\n                                                   ~~~~~~~\n\n  .-----------------------------------------------------------------------.\n  |       PLEASE READ THE REGISTER!.TXT INCLUDED IN THIS ARCHIVE !!!      |\n  `-----------------------------------------------------------------------''\n\nHISTORY :\n---------\n\n        V1.0    -       First Public Release !\n\n        V1.5    -       Some small changes, bug fixes.\n                        Fucking cool flag-by-number !\n                        \nFUTURE :\n--------\n\n	V2.0	-	User configurable !\n\n\nTHANX TO :\n----------\n\n        Special thanx go to Dalai Lama for the idea to the fastest\n        search-algorithm ever !!!\n\n\n        My beta-testers :\n        -----------------\n                Zion/Zions Hideout\n                Rotor/Gates of Asgard\n                Freddy Krueger/Boiler Room\n                BloodWolf/Mortuary\n\n        You also can reach me on these boards !\n\n\nGREETINGS:\n----------\n\n   - Runt&Scottie - Polaris - Skin - XAD - Deltaforce - Andy - Wedlock -\n     - Blackbird - Planet Master - Sid Vicious - Sigma Seven - Whiz -\n      - Linebacker - Raider - Mitch - Mr.T - Samir - Power - Sisko -\n              - Atomix - Castor - Scout - Ventor - Nocturne -\n\n                       - All GOD and LOGIC Members -\n\n··············································································\n\n          - GLOBAL OVERDOSE GERMAN HQ - LOGiC WHQ - iLLUSiON HQ -\n               _ ________           _ ______________\n         /\_______    _ /     _____   ________     /__: _____  sYSOPS:\n        /____  _ /    //_____/o  _/___  /    /____/   |/    /  """""""\n      _____:/  //     /     //   \    \/    /    //   /    /   cALYPSO/GOD\n     /     |\  /__________ /.   /_\   /________ /.    \    \   cASTOR/PDX\n __|/____________\       \/_____________\     \/______|\____\  mIKE & dAVE/CLS\n   |                                                  :        sPIKE\n                      ·b·L·A·C·K· ·m·O·O·N·       :_______|__\n         /\ __ /\             _______________     |    _ /|    cALL :\n        // \\//  \____________\________   _ /____ |    //      """" "\n       /.   \/    \________   _ /     /   //     \|   o/     +49-70-eLITE !\n      /    \  /    \      /   //\    /    /|      \  ./      """"""""""""\n     /      \/______\    /    /  \_______/ |    \    /   3 nODES rINGDOWN !\n    /_______|        \_______/             |_____\  /    " """"" """"""""\n            :                                Sk!n \/   aLL nODES 16.8 DST !\n                                                       """ """"" """" """\n     rUNNiNG (LATEST!) S-eXPRESS - sUPPORTiNG aMiGA aND cONSOLE oNLY !\n         aLL {<GOD>|<LOGiC>|<iLLUSiON>}-rELEASES fREE dOWNLOAD !!!\n          cALL nOW ! LOTSA iNTERNATiONAL cALLERS ! SiMPLY eLiTE !\n','\n',char(10)),NULL,'auto-added',13178,2,0,NULL,NULL,'god_bs15','scan',1780048524);
INSERT INTO door_catalog VALUES('god_ccom','GOD-CCOM.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/GOD-CCOM.LHA',NULL,'XIM','______/\________ _____/\ ________________',NULL,'CALYPS0/G0D','GOD','\____/   ______//    /  \\______   \____/ \_/    \_   \/    /\   \|    |\   \_/ \     |    \    \/   /|   /\/   /',replace('  ______/\________ _____/\ ________________ \n  \____/   ______//    /  \\______   \____/ \n    \_/    \_   \/    /\   \|    |\   \_/   \n      \     |    \    \/   /|   /\/   /     \nEXPRESS\__  _____/\_______/ |___\  __/DESIGN\n<---------\/- ·p·R·E·S·E·N·T·S· -\/-------->\n     ConfComment V1.0 by CALYPS0/G0D !\n  ASM XIM Door ! Best Comment-Door ever !\n<------------------------------------------>\n','\n',char(10)),'ConfComment.Doc',replace('                                    .    :\n.______ ______________.   __________|    |____ __________ _____. __________.\n|:::· ·/    _____     |__/__  _    ¬\     _  ¬\______   ¬\     |_____· ·:::|\n|:·  _/    |    ¬\_   |    ¬\_ |     \_  |     \_         \_   |    ¬\_   :| \n|·   \     |      /   |      / |      /  |  ÷e÷ /   |      /   |      /_ _·|\n|.  .\\__________/__________/________/_________/__________/__________//   .|\n|             .__                        .    ·                            |  \n|  _______ ___| ¬\ ________ _________ ___|    :_______  _________________  |\n: /  _   ¬\   |   \       ¬\_____   ¬\  _     ¦  _   ¬\/     ____       ¬\ :\n_/    |    \_ |    \_  |    \_ _/   _/   |    :   |    \____    ¬\_  |    \_\n\     |     / |     /  ______/ \    \__  |    :   |     /   |     /  ______/\n:\_________/_______/____________\     /_______¦________/_________/_______ _: \n+--------------------------------\___/-------------------------------------+\n¦                                                                          ¦\n:                                                                          :\n                                    PRESENTS\n\n                   ConfComment V1.0 coded by CALYPSO/GOD !\n\n    PROFESSIONAL TOOLS FOR PROFESSIONAL SYSOPS - GET THE REAL QUALITY !\n\n\nWHAT''S THE USE OF THIS TOOL ?\n-----------------------------\n\n        This tool shows a different SysopTeam to leave a\n        Comment to in each conference !!!\n\n        Enjoy this cool tool... of course with the fucking\n        fast ASM speed you know from me ! Just look at the\n        length of the door... 2k !\n\n        Probably the BEST, FASTEST, COOLEST, SHORTEST Comment Door ever !\n\n\n   .-----------------------------------------------------------------------.\n   |                                                                       |\n   |  REGISTRATION INFO :                                                  |\n   |  -------------------                                                  |\n   |  You can get a personalized version directly from me !                |\n   |                                                                       |\n   |  I also can do some slight changes you want (e.g. different colors) ! |\n   |                                                                       |\n   |  If you are interested to get your own version, simply call           |\n   |  my BBS or write a mail on another BBS and we talk about it !         |\n   |                                                                       |\n   |  I have also alot of other high quality utils you can request your    |\n   |  own versions (look on the list at the end of the docs) !             |\n   |                                                                       |\n   `-----------------------------------------------------------------------''\n\n\nHOW TO INSTALL :\n----------------\n\n        S-Express and /X 2.x :\n        ----------------------\n\n        Copy these files in the archive to your directories,\n        they are :\n\n        BBS:Doors/ConfComment/ConfComment.XIM\n        BBS:Doors/ConfComment/SysopList.txt\n        BBS:Doors/ConfComment/Header.txt\n\n        Append the BBS:Commands/SYS.CMD to your SYS.CMD !\n\n        \n        /X 3.x :\n        --------\n\n        Copy these files in the archive to your directories,\n        they are :\n\n        BBS:Doors/ConfComment/ConfComment.XIM\n        BBS:Doors/ConfComment/SysopList.txt\n        BBS:Doors/ConfComment/Header.txt\n\n        Copy the BBS:Commands/BBSCMD/C.Info to your\n        BBS:Commands/BBSCMD/ !\n        \n\n        No worries, the door refers to DOORS: , so you can put\n        your doors wherever you want !\n\n        At last copy Libs/AEDoor.Library (© Sintax) to your LIBS: !\n\n\n        Ok, now edit your BBS:Doors/ConfComment/SysopList.txt !\n\n        It has to look like this (example) :\n\n        ------------(cut here)-------------\n        Calypso                                 First list the default\n        Da Fucking Kewl sysop !                 sysops plus their\n        Castor                                  extra text !\n        Da Demo Master !\n        Mike & Dave                             Name max. length : 20 !\n        Da Dutch Elites !                       Textline max. length : 50 !\n        SpIkE\n        Da Console Maniac !\n        #0                                      <--- ConfNumber - 1 !!!\n        Calypso                                      ~~~~~~~~~~~~~~\n        Da Fucking Kewl sysop !                 Now add the special lists\n        Castor                                  for the conferences you\n        Da Demo Master !                        want not to use the\n        #1                                      default list !\n        Calypso\n        Da Fucking Kewl sysop !                 ConfNumbers >9 supported !\n        Castor\n        Da Demo Master !\n        Mike & Dave\n        Da Dutch Elites !\n        #2\n        Calypso\n        Da Fucking Kewl sysop !\n        Castor\n        Da Demo Master !\n        SpIkE\n        Da Console Maniac !\n        #10                                     Also Confs >10 supported !\n        Calypso\n        Da Fucking Kewl sysop !\n        #                                       <--- Mark the End with # !!!\n        ------------(cut here)-------------\n        \n\n        Ok... I think this is clear... for confs where no extra list\n        is specified the default list will be shown !\n\n\n        If you want you can change the BBS:Doors/ConfComment/Header.txt !\n\n        If you want NO Header, then clear that file (0 Bytes) !\n\n\n        So you are ready to go ! Enjoy !\n\n\n\nLAST WORDS :\n------------\n        \n        Now have fun with this great tool !\n\n        For Bugs (there are none), Ideas (yeah !) or just for fun\n        call my BBS :\n\n        bLACK m00N   +49-7054-8733   G·O·D EXPRESS DESIGN WHQ !\n        ~~~~~~~~~~                   L^O^G^I^C wORLDHEADQUARTERS !\n                                     iLLUSION/gELBSUCHT hEADQUARTERS !\n                                     bIZARRE fASCINATION hEADQUARTERS !\n\n        (2 Nodes - USR Dual 16.8 !)\n\n        See ya soon mates...\n                                                   Calypso !\n                                                   ~~~~~~~\n\n\nTHANX TO :\n----------\n\n        My beta-testers :\n        -----------------\n                Dalai Lama/Point Plank\n                Rotor/Gates of Asgard\n                Freddy Krueger/Boiler Room\n                Bloodwolf/Mortuary\n                MKO!/Eleventh Hour (Thx for the idea to this door !)\n\n        You also can contact me on these boards !\n\n\nP.S. : OTHER HIGH-QUALITY /X-TOOLS BY ME :\n------------------------------------------\n\n        Only latest versions listed here !\n\n\n        LGC-LCK2.LHA    - LHA-Check V2.0\n                          THE BEST LHA-CHECKER AVAILABLE !\n\n        LGC-ZIP.LHA     - ZIP-Check V1.0\n                          Guess what ?\n\n        LGC-QN20.LHA    - QuickNew V2.0\n                          Fucking great util !\n\n        GOD-ULDL.LHA    - BestUL V1.2 and BestDL V1.2\n                          Great Topuploaders and Topdownloaders XIMs !\n\n        GOD-WA12.LHA    - V1.2 of the fucking cool wall XIM !\n\n        GOD-FRON.LHA    - FrontEnd V1.0 ! Very cool Frontend, shows\n                          User + Action + Baud !\n                          Executes a Logon-Batch !\n\n        All LOGIC and GOD utils ever released are available and\n        FREE-DOWNLOAD on my BBS !\n\n\nSOON COMING :\n-------------\n\n        Best-Scan V1.0 - Fastest Newfiles Door ever !\n\n        QuickNew V2.1  - Some improvements to this very cool util !\n\n        TheWall V1.4   - Update to my Wall Door !\n\n        WeekTop V1.0   - Yeah ! This is a really great WeekTop Door !\n\n\nGREETINGS:\n----------\n\n      - G.E.M. - Runt&Scottie - Polaris - Skin - XAD - Deltaforce - Andy -\n      - Wedlock - Blackbird - Sisko - Planet Master - Proton - Bloodwolf -\n         - Linebacker - Cujo - Raider - Mitch - Mr.T - Samir - Power -\n\n                         - All LOGIC and GOD Members -\n\n··············································································\n\n      - G·O·D Express Design HQ - LOGIC WHQ - ILLUSION HQ - bF HQ -\n               _ ________           _ ______________\n         /\_______    _ /     _____   ________     /__: _____  sYSOPS:\n        /____  _ /    //_____/o  _/___  /    /____/   |/    /  """""""\n      _____:/  //     /     //   \    \/    /    //   /    /   cALYPSO !\n     /     |\  /__________ /.   /_\   /________ /.    \    \   cASTOR\n __|/____________\       \/_____________\     \/______|\____\  gHOSTRIDER\n   |                                                  :        (yOU ?)\n                     ! lOOKING fOR cOSYSOPs !      :_______|__\n 0.5      /\ __ /\             _______________     |    _ /|\n gIG hD! // \\//  \____________\________   _ /____ |    //   nUMBERS:\n 68o3o  /.   \/    \________   _ /     /   //     \|   o/    """"""""\n       /    \  /    \      /   //\    /    /|      \  ./  +49-7054-8733\n      /      \/______\    /    /  \_______/ |    \    /  +49-7054-eLITE!\n     /_______|        \_______/             |_____\  /\n             :                                Sk!n \/  bOTH nODES 16.8 DS!\n \n      rUNNING (LATEST!) S-eXPRESS - sUPPORTING aMIGA aND sNES oNLY !\n         aLL {<GOD>|<LOGIC>|<ILLUSION>}-Releases fREE dOWNLOAD !!!\n          cALL nOW ! Lotsa INTERNATIONAL cALLERS ! Simply eLITE !\n','\n',char(10)),NULL,NULL,20247,1,0,NULL,NULL,NULL,'scan',1780048524);
INSERT INTO door_catalog VALUES('god_da20','GOD-DA20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/GOD-DA20.LHA','Copy','XIM','D-Access.RP','2.0',NULL,'GOD','THE ULTIMATE NEW-USER PROCESSING UTILITY `---------<Ø] FOR /X V3.X & UP [Ø>---------''',replace('D-ACCESS V2.0 \nTHE ULTIMATE NEW-USER PROCESSING UTILITY\n`---------<Ø] FOR /X V3.X & UP [Ø>---------''','\n',char(10)),'D-ACCESS.Guide',replace('@dataBase D-ACCESS.guide\n\n@Width 77\n@Window Normal\n@Author The Dalai Lama\n\n@Index Contents\n\n@Remark $VER: D-ACCESS V2.0 (10-JUN-1994) By The Dalai Lama of Global Overdose\n@Remark AmigaGuide DataBase\n\n@node MAIN "D-ACCESS Documentation © 1994 by The Dalai Lama of Global Overdose."\n@next "changes"\n\n        ·-G-·-L-·-O-·-B-·-A-·-L-·-·-O-·-V-·-E-·-R-·-D-·-O-·-S-·-E-·\n\n                             ·P·R·E·S·E·N·T·S·\n\n                              @{" D-ACCESS V2.0 " LINK "info"}\n                              ~~~~~~~~~~~~~~~~\n           New User and Account Control Door for Ami-Express BBS\n           ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                         WRITTEN BY THE DALAI LAMA\n                         ~~~~~~~~~~~~~~~~~~~~~~~~~\n                             TABLE OF CONTENTS\n                             ~~~~~~~~~~~~~~~~~\n                     -=*> @{" CHANGES SINCE V1.5! " link "CHANGES"} <*=-\n\n            @{" INTRODUCTION         " link "INTRO"}   @{" OVERVIEW             " link "overview"}\n            @{" INSTALLATION         " link "installation"}   @{" CONFIGURING D-ACCESS " link "config"}\n            @{" USING AUTO-NOTIFY    " LINK "notify"}   @{" NOTES ON FUNCTIONING " LINK "notesmenu"}\n            @{" USING THE SYSOP MODE " LINK "sysopmenu"}   @{" A FINAL WORD         " LINK        "lastword"}\n@endnode\n@node "info" "QUICK INFO ON D-ACCESS V2.0"\n\n                        QUICK INFO ON D-ACCESS V2.0\n                        ~~~~~~~~~~~~~~~~~~~~~~~~~~~\n     D-ACCESS is Copyright © 1994 by the Dalai Lama of @{"Global Overdose" link "GODinfo"}\n\nD-Access is the premier Ami-Express v3.xx New User handler.\nIt is completely written in Arexx and is freely distributable as long as\nnothing in either the program or the documentation are altered.\n\n\n                             REVISION HISTORY\n                             ~~~~~~~~~~~~~~~~\n10-JUN-1994 - V2.0 - THIRD PUBLIC RELEASE - COMPLETELY OVERHAULED!\n\n16-NOV-1993 - V1.5 - SECOND PUBLIC RELEASE - NEW FEATURES - NO KNOWN BUGS\n\n07-NOV-1993 - V1.4 - FIRST PUBLIC RELEASE - NO KNOWN BUGS\n\n VERSIONS 0.2 THRU 1.2 - INTERNAL RELEASE, BETA TESTERS ONLY - NO KNOWN BUGS\n\n05-AUG-1993 - V0.1 - INTERNAL BETA RELEASE\n\n@endnode\n@node "Godinfo" "GLOBAL OVERDOSE BOARD LIST"\n\n                    * Give These G.O.D Hangouts A Call! *\n\n===========================================================================\n···········································································\n.......G.O.D.  WHQ - Zion''s hideout    - 614-876-0807  - 8 Nodes...........\n.......G.O.D. USHQ - The Boiler Room   - 716-695-0414  - 2 Nodes...........\n.......G.O.D.  EHQ - Sleep City        - +31-79-219299 - 2 Nodes...........\n.......G.O.D.  AHQ - Bandits BBS       - +61-82-344672 - 2 Nodes...........\n...........................................................................\n===========================================================================\n\n@endnode\n@node "CHANGES" "CHANGES SINCE V1.5"\n\n                            CHANGES SINCE V1.5\n                            ~~~~~~~~~~~~~~~~~~\nVery many changes have been made since the release of V1.5, it would be a\ngood idea if you would take the time to look over the list of changes so\nthat the transition going from v1.5 to v2.0 is smooth!\n\n                     @{"D-ACCESS IS NOW FOR /X V3.X+ ONLY!" link "30only"}\n                     @{"A CHANGE IN THE APPLICATION FORMAT" link "formatchange"}\n                     @{"NEW SYSOP FUNCTIONS               " link "SYSFUNCCHANGE"}\n                     @{"NEW AUTO-ACCESS-UPGRADE           " link "upgradechange"}\n                     @{"NEW TOOLTYPES                     " link "Tooltypechange"}\n                     @{"NEW BBSCMD ICON                   " link "Iconchange"}\n\n@endnode\n@node "formatchange" "A CHANGE IN THE APPLICATION FORMAT"\n\n                    A CHANGE IN THE APPLICATION FORMAT\n                    ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nA change in the application format was necessary so that the new account\npreset features could more easily be implemented.  The old applications that\nyou have are not compatible with the VALIDATE function of D-Access V2.0 so\nplease warn your cosysops not to validate any but NEW users since the\ninstallation of the new version or damage to the USER.DATA and CONF.DB files\ncould result!!!\n@endnode\n@node "SYSFUNCCHANGE" "NEW SYSOP FUNCTIONS"\n\n                            NEW SYSOP FUNCTIONS\n                            ~~~~~~~~~~~~~~~~~~~\nD-Access now has a CREATE ACCOUNTS command that lets you and your cosysops\nmake accounts for new users. This is a fantastic function for you sysops that\nrun systems that are closed to new users... what do you do when you run out\nof inactive slots? Delete some suckers? Nope, use CREATE ACCOUNTS to make\nnew, fully functioning accounts for your new users! You select the preset,\nyou tell it whether or not to set the ratio in all confs and best of all, you\nnever have to log on as a new user! The CREATE ACCOUNTS command also\nsupports INFINITE PRESETS! You can add icons in your access drawer for as\nmany numbered presets as you want! The only rule is the format, just make it\nnumbers, like PRESET.34.info... etc.. you get the picture! What is more,\nD-Access SHOWS you what groups, levels, ratios, byte limits, time limits, and\nconference rejoins are set to for all the presets! No more guessing in the \ndark about which preset is for which group, it''s all right there on the \nscreeen so you can see and decide! Since all /X passwords are encrypted there\nis a file that contains passwords and their encrypted equivalents. There are\n28 passwords to choose from for each new account you make, and later on I''ll\ntell you how to make more, there is a seperate util included to help you out!\n@endnode\n@node "upgradechange" "NEW AUTO-ACCESS-UPGRADE"\n\n                          NEW AUTO-ACCESS-UPGRADE\n                          ~~~~~~~~~~~~~~~~~~~~~~~\nNow when you validate new users with D-Access you can set their attributes\nright then and there. This feature allows you to use any of the INFINITE\nPRESETS to set the new user''s accounts into working order. You choose the\npreset access and whether or not to set the ratio in all confs for conference\naccounting fans.  No more loading of the /X account editor and trying to\nremember what user was supposed to get what access. It''s all right there in\nD-Access - This, I think, is the best new feature! Try it!!!\n@endnode\n@node "tooltypechange" "NEW TOOLTYPES"\n\n                               NEW TOOLTYPES\n                               ~~~~~~~~~~~~~\nThere are several new Tooltypes for the D-ACCESS.info icon! They Are:\n\n\nDONATE_INFOFILE=full path & filename of your own donation text file.\n\nif no DONATE_INFOFILE is specified in the icon then it will default to\nDONATE_INFOFILE=DOORS:D-ACCESS/D-ACCESS.TXT \nThis is the file included in the archive.\n\n\nUSER_DATA_PATH=the full path and filename for your user.data.\n\nThis was done to accomodate systems that do not use the name or assign BBS:.\nIf not present it defaults to BBS:USER.DATA.\n\n\nPRESET_CHAT_LIMIT=time in minutes.\n \nThis sets the time in minutes that you want preset in the account you are\nvalidating or creating for the chat time limit.\n\n\nQUESTIONS.X=Language\n\nExample: QUESTIONS.1=ENGLISH, QUESTIONS.2=GERMAN, etc.\nThis will display a menu of accessible QUESTIONAIRES named\nD-ACCESS.QUESTIONS.GERMAN etc. and allows the user to use a questionaire in\nhis or her own language. The cool thing about this is that the actual\nquestions displayed to the user can be in the language the questionaire\nis for but the output response text can be in the sysops own language, it\njust happened to work out that way. If this tooltype is not present it does\nnot show the menu but just goes into the default D-ACCESS.QUESTIONS file.\n\nHave a look at the included German application, you will understand.\n@endnode\n@node "iconchange" "NEW BBSCMD ICON"\n\n                              NEW BBSCMD ICON\n                              ~~~~~~~~~~~~~~~\nThere is a new icon that goes into the BBSCMD drawer, it is called\nINTERN1.info and is required for D-Access to run properly. It allows\nD-ACCESS to jump in and out of the internal account editor without leaving\nD-ACCESS itself.\n@endnode\n\n@node "30only" "D-ACCESS IS NOW FOR /X V3.X ONLY!!!!"\n\n                   D-ACCESS IS NOW FOR /X V3.X ONLY!!!!\n                   ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nObviously I have done a major overhaul on D-Access making it more powerful\nthan ever! New Features include a window-style scrolling application list,\nautomatic access upgrade when you use D-Access to validate the new users,\nINFINITE AVAILABLE PRESETS for Access Upgrading, multiple user select to\nperform an operation on multiple applictions, a quick jump for moving quickly\naround a large list of applications, a powerfull new CREATE ACCOUNTS command\nthat lets you make new accounts without logging on - A MUST IF YOU RUN A BBS\nTHAT IS CLOSED TO NEW USERS - and much more! Best of all it''s EASIER for you\nsysops to use!\n@endnode\n\n@node "intro" "INTRO TO D-ACCESS"\n\n                               INTRODUCTION\n                               ~~~~~~~~~~~~\nAnother util? Well yeah, so here''s D-Access, a cool arexx util that\nfills a niche in the /X package... it even works too.  So what does this\nthing do?  Well I got tired (as I am sure you all have) of looking through\nthe "Answers" file (you know, that 200-500k monster lurking in every ''NODE''\ndrawer?!?) for some user that logged in only a couple days ago that\nneeds to be validated ''cause he didn''t leave a message and neither you or your\ncosys knew he applied and well, you know what it''s like! D-access is a fully\nconfigureable access questionare with lots of features to make it simple for\ncosys to validate users, see their questionaires, check out any old\nquestionaires and a whole shitload of other things that are really quite\nuseful to help automate your BBS!\n@endnode\n@node "overview" "D-ACCESS OVERVIEW"\n\n                             D-ACCESS OVERVIEW\n                             ~~~~~~~~~~~~~~~~~\nWith D-ACCESS installed you can shitcan all those ''Script'' files, delete\nthose ''ole ''Answers'' files and let IT do all the work (well, you and the\nCosys gotta help a little..).  D-ACCESS is an Arexx door that can be ran a\ncouple of ways to get the questionaire. I''ve got mine set as an MCI command\nin the node bulletin (~CC_ACCESS), if the user doesn''t fill it out, no\naccess, simple as that. It has the option of kicking users from area codes\nthat you pre-set (I.E. Those damn local lame-ass, leechin'' mo-fo''s!) but of\ncourse you have to hope that locals at least use their right area code. You\ncan also have it send a donation info text to those that qualify as ''locals''\nif you want them to PAY for access (Like I do!) The questionaire is 100%\nconfigureable, with seperate "record" and "send" lines (more on that later),\nconfigureable multi-line responses, configureable hot-key responses, and\nconditional responses, the option of ''auto-send'' message to sysop, a logon\nutil that shows new users since you last logged on (works for cosys that\nhave access to the door too, which makes the sysop mail obsolete!), a nice\nsysop function set when run from the menu prompt by someone with access and\nwell, just about everything I could think of.\n@endnode\n@node "installation" "INSTALLING D-ACCESS"\n\n                            INSTALLING D-ACCESS\n                            ~~~~~~~~~~~~~~~~~~~\nFirst, you need to copy the D-ACCESS drawer to your DOORS: directory. It\ncontains all the files that are necessary for D-ACCESS to operate. Next\ncopy the ACCESS.INFO and INTERN1.INFO files to the BBS:COMMANDS dir, you can\nreaname ACCESS.INFO to whatever you want to suit your needs. \n\nMETHOD #2: Double-Click the INSTALL icon. 8)\n\n@{" CONFIGURING D-ACCESS " link "config"}\n@endnode\n@node "config" "CONFIGURING D-ACCESS"\n\n                           CONFIGURING D-ACCESS\n                           ~~~~~~~~~~~~~~~~~~~~\n                      @{"CONFIGURING THE ICON TOOLTYPES" LINK "CONFIG1"}\n                      @{"CONFIGURING THE TEXT FILES    " LINK "TextconFIG"}\n                      @{"CONFIGURING THE QUESTIONAIRES " LINK "qconFIG"}\n                      @{"CREATING NEW PASSWORDS        " LINK "pword"}\n\n@endnode\n@node "config1" "CONFIGURING D-ACCESS"\n\n                           CONFIGURING D-ACCESS\n                           ~~~~~~~~~~~~~~~~~~~~\nD-Access is configured by editing the tooltypes in the D-Access.INFO file\nfound in the D-Access Drawer. The tool types should look like this:\n\n*NOTE* The first tooltype MUST be SYSOP_LEVEL, this speeds up the reading\nprocess greatly when D-AccessShow is used!\n\n------------------X8  SAMPLE  8X-----------------\n@{"SYSOP_LEVEL" link "SYSOP_LEVEL"}=250\n@{"DONATE_INFO" link "DONATE_INFO"}=NO\n@{"SYSOP_MESSY" link "SYSOP_MESSY"}=NO\n@{"AUTO_GOODBY" link "AUTO_GOODBY"}=YES\n@{"ACODE_BLOCK" link "ACODE_BLOCK"}=YES\n@{"AREA_CODE.1" link "AREA_CODE.x"}=513\n@{"AREA_CODE.2" link "AREA_CODE.x"}=606\n@{"AREA_CODE.3" link "AREA_CODE.x"}=812\n@{"BLANKLINE_LOGOFF" link "BLANKLINE"}=YES                              *NEW COMMAND V1.5*\n@{"COSY_ACCOUNT_EDIT" link "COSY_ACCOUNT_EDIT"}=YES                             *NEW COMMAND V1.5*\n@{"COSY_NAME.1" link "COSY_NAME.x"}=DALAI LAMA                            *NEW COMMAND V1.5*\n@{"COSY_NAME.2" link "COSY_NAME.x"}=FREUD                                 *NEW COMMAND V1.5*\n@{"SYSOP_PASSWORD" link "SYSOP_PASSWORD"}=ENTER_ME                           *NEW COMMAND V1.5*\n@{"NEWUSER_UPLOAD" link "NEWUSER_UPLOAD"}=YES                                *NEW COMMAND V1.5*\n@{"UPLOAD_PATH" link "UPLOAD_PATH"}=BBS:AMIGA/HOLD/                       *NEW COMMAND V1.5*\n@{"DELETE_UPLOAD" link "DELETE_UPLOAD"}=YES                                 *NEW COMMAND V1.5*\n@{"DONATE_INFOFILE" link "DONATE_INFOFILE"}=DOORS:D-ACCESS/D-ACCESS.TXT       *NEW COMMAND V2.0*\n@{"USER_DATA_PATH" link "USER_DATA_PATH"}=BBS:USER.DATA                      *NEW COMMAND V2.0*\n@{"PRESET_CHAT_LIMIT " link "CHATLIM"}=30                             *NEW COMMAND V2.0*\n@{"QUESTIONS.1" link "QUESTIONS.x"}=ENGLISH                               *NEW COMMAND V2.0*\n@{"QUESTIONS.2" link "QUESTIONS.x"}=GERMAN                                *NEW COMMAND V2.0*\n------------------X8  SAMPLE  8X-----------------\n@endnode\n\n\n\n@node "SYSOP_LEVEL" "SYSOP_LEVEL"\n\nSYSOP_LEVEL  -  This the the minimum level assigned for SYSOP commands in\n                D-ACCESS. I have it at 250 so that cosys can see the apps\n                and can validate the users with the internal account editor.\n\n    *WARNING*   Users that have access equal or higher than this have direct\n                use of the account editor through D-Access, please be careful\n                when setting this!\n@endnode\n@node "DONATE_INFO" "DONATE_INFO"\n\nDONATE_INFO  -  This is a YES/NO switched option. YES means that the file\n                D-ACCESS.TXT will be sent to the user, you can change the\n                file to whatever you want, but look at the supplied file\n                for an idea.\n@endnode\n@node "SYSOP_MESSY" "SYSOP_MESSY"\n\nSYSOP_MESSY  -  YES/NO switched, if YES D-Access automatically puts the user\n                into Comment to sysop so they can leave you a nice message\n                after they have completed the application.\n\n       *NOTE*   SYSOP_MESSY and AUTO_GOODBYE cannot both be YES,\n                or it will hang up on the user before he leaves a message.\n                Use ONE ON, ONE OFF at all times.\n@endnode\n@node "AUTO_GOODBY" "AUTO_GOODBY"\n\nAUTO_GOODBY  -  This is a YES/NO switchable option, if YES is selected the\n                user leaving an application will be automatically logged\n                off as soon as the application is finished. Click. Also it\n                hangs up if the user tries to leave another application or\n                if their application is in the BAD_APPS drawer.\n@endnode\n@node "ACODE_BLOCK" "ACODE_BLOCK"\n\nACODE_BLOCK  -  YES/NO switchable lets you hang up on users from area codes\n                you want to avoid new users from (I.E. Local calls,) enter\n                up to 9 area codes after this option, if NO it ignores all\n                AREA_CODE.X lines.\n\n       *NOTE*   AreaCode Block also recognizes phone numbers that are less\n                than 9 numbers long as being local callers (i.e. 123-4567)\n                and will act accordingly.\n@endnode\n@node "AREA_CODE.x" "AREA_CODE.x"\n\nAREA_CODE.X  -  Up to 9 area codes can be blocked for new users, just list\n                the ones you want blocked, one per line.\n@endnode\n@node "BLANKLINE" "BLANKLINE_LOGOFF"\n\nBLANKLINE_LOGOFF - If set to YES this function will display the text\n                D-Access.NOANSWER and then log the user off when they hit\n                <return> on any Single Line response question without\n                leaving an answer.\n@endnode\n@node "COSY_ACCOUNT_EDIT" "COSY_ACCOUNT_EDIT"\n\nCOSY_ACCOUNT_EDIT - YES/NO switchable, this option lets you configure which\n                users have access to the account editor and forces password\n                protection for it. These options are set in COSY_NAME.X and\n                SYSOP_PASSWORD. If this option is NO then any user that has\n                access to this door can use the account editor without any\n                password protection.\n@endnode\n@node "COSY_NAME.x" "COSY_NAME.x"\n\nCOSY_NAME.X  -  Enter as many names as you want, only those listed will\n                have access to the account editor and must first pass the\n                password protection. Only works when COSY_ACCOUNT_EDIT=YES.\n@endnode\n@node "SYSOP_PASSWORD" "SYSOP_PASSWORD"\n\nSYSOP_PASSWORD  Enter the password you want to use to gain access to the\n                account editor. Only works when COSY_ACCOUNT_EDIT=YES.\n\n@endnode\n@node "NEWUSER_UPLOAD" "NEWUSER_UPLOAD"\n\nNEWUSER_UPLOAD  With this option switched ON a new user is given the text\n                D-ACCESS.ULTEXT and then is prompted to begin sending their\n                file. Upon completion of the transfer the filename is added\n                to the bottom of their app for easy viewing by the sysops.\n                This option has 2 sub-settings listed below.\n@endnode\n@node "UPLOAD_PATH" "UPLOAD_PATH"\n\nUPLOAD_PATH   - This is a full pathname that tells D-Access where to stick\n                the file if you wish to to keep all the files sent by the \n                new users for later viewing. This option only has an effect\n                if DELETE_UPLOAD=NO.\n\n@endnode\n@node "DELETE_UPLOAD" "DELETE_UPLOAD"\n\nDELETE_UPLOAD - If this option is set to YES then the file that the new user\n                uploads is automatically deleted after it''s info is recorded\n                in their application. RECOMMENDED METHOD.\n\n@endnode\n@node "DONATE_INFOFILE" "DONATE_INFOFILE"\n\nDONATE_INFOFILE This tooltype should be set to the full path and filename of\n                the file that you want sent to new users when DONATE_INFO=YES\n                The default is to use DOORS:D-ACCESS/D-ACCESS.TXT\n\n\n@endnode\n@node "USER_DATA_PATH" "USER_DATA_PATH"\n\nUSER_DATA_PATH  This tooltype should contain the full path and filename of\n                your USER.DATA file. If this tooltype is excluded from the \n                icon D-Access will default to BBS:USER.DATA.\n\n@endnode\n@node "CHATLIM" "PRESET CHAT LIMIT"\n \nPRESET_CHAT_LIMIT - This is the time in minutes that you want each user to\n                    have when you use the account presets.\n@endnode\n@node "QUESTIONS.x" "QUESTIONS.x"\n\nQUESTIONS.X   - Enter As many Questionaire names as you want, the included\n                ones Are QUESTIONS.1=ENGLISH and QUESTIONS.2=GERMAN. If this\n                tooltype is excluded D-Access will default to the regular\n                DOORS:D-ACCESS.QUESTIONS file. If it is included D-Access \n                will list the available questionaires and allow the user to\n                pick the one that he wishes. The questionaires must be \n                named according to the type, i.e D-ACCESS.QUESTIONS.GERMAN.\n@endnode\n@node "TEXTCONFIG" "CONFIGURING D-ACCESS"\n\n                              THE UPLOAD TEXT\n\nThere is a file called D-ACCESS.ULTEXT which contains text that will be\nshown immediately before the applicant is prompted to upload. You can change\nthis to whatever message you want to give the applicants before they start\nSending their newest file.\n\n\n                             THE PRESHOW TEXT\n\nThere is a file called D-ACCESS.PRESHOW which contains text that will be\nshown immediately before the application is given. You can change this to\nwhatever message you want to give the applicants before they start filling in\nthe blanks.\n\n                             THE NOANSWER TEXT\n\nThere is a file called D-ACCESS.NOANSWER which contains text shown to the\nuser if they skip a line on the application just before it hangs up on\nthem.\n\n@endnode\n@node "QCONFIG" "CONFIGURING THE QUESTIONAIRES"\n\nTHE QUESTIONS FILE   * THESE HAVE BEEN CHANGED FROM V1.4!!! *\n\nNow lets have a look at the questions file.  The supplied one looks like\nthis: @{"QUESTIONAIRE" link "QAIRE"}\n\nThe numbers in front of each line reperesent the type of question being\nasked. They must be in the FIRST COLUMN and are as follows.\n\nLeft-Alt 1 (¹)  This is a comment line. Anything on a comment line goes\n                in the saved application that you see when you read the app.\n                This means that you can write the saved questions smaller\n                than the actual question the user sees, thus saving\n                space! These have a maximum length of 35 characters.\n\nLeft-Alt 2 (²)  This is a conditional question in the format ²<RESPONSE>\n                (²Y) where it only asks the question if the response equals\n                the response to the previous HOTKEY question, for example: \n\n                DO YOU SMOKE CRACK?   ~Y/N|YEP/NOPE\n                ²YWHAT THE HELL FOR?  ~2\n\n                In this case the second question would be asked ONLY if the\n                response to the previous question was "Y" (YEP).\n\n        *NOTE*  You can now have mulit-line or hotkey questions as the\n                condition question!\n\nLeft-Alt 3 (³)  * THIS HAS BEEN CHANGED FROM V1.4!!! *\n                This option, when used on a SINGLE LINE BY ITSELF, inserts\n                a blank line in the recorded application. This helps you\n                keep the recorded apps tidy and easy to read.\n\n~ (The TILDE)   The tilde can now be placed anywhere in the apps. It\n                now initiates the response mode for each question. There are\n                3 response modes availabe.\n\n~               MODE 1 - TILDE WITH NO TRAILING CHARACTERS. This asks a\n                one-line short-answer question. The result of this mode is\n                placed in the app immediately following the text in the\n                previous ¹TEXT line.\n\n~9              MODE 2 - TILDE WITH A NUMBER FROM 1 to 99 TRAILING. This \n                option initiates a Mulit-Line response. The user has x number\n                of lines for the respons. *NOTE* The user can now hit\n                <return> on a blank line to end the response before the\n                specified number of lines is reached. You can now prompt for\n                up to a 99 line response.\n\n~Y/N|YES/NO     MODE 3 - TILDE WITH HOTKEY CHARACTERS TRAILING.\n                This option initiates a HOTKEY response. The HOTKEYS appear \n                before the vertical bar (Y/N|...) and the HOTKEY WORDS appear\n                after the vertical bar. (...|YES/NO). The hotkeys are\n                automatically displayed to the user after the question is\n                given so there is no need to include them in your\n                questionaire. When the user types a key the WORD is displayed\n                so if the user hits "Y" he would see "YES" pop up onto the\n                screen. You can make the HOTKEYS and the HOTKEY WORDS\n                whatever you you like as long as they are in the format\n                KEY1/KEY2|WORD1/WORD2. The result of this mode is\n                placed in the app immediately following the text in the\n                previous ¹TEXT line.\n                *NOTE* If return is hit then the response will be the first\n                key, in this case, "Y"\n\nPLAIN TEXT   -  You can use plain text not preceded by ¹,² or ³ anywhere\n                and it will be sent to the user, so you could have a\n                disclaimer print to the user but have it save "DISCLAIMER\n                ANSWER: YES" in the save file without all the other\n                text.\n\n\n*NOTE*\n~~~~~~\nThe questionaire parser has been completely re-written, it is now more\nefficient and much more flexible. You can now initiate any TILDE command\nanywhere in the application and it is no longer dependent on the ALT\npreceding characters (¹,²,³) which makes it easier to create a questionaire\nto suit your needs.  Have a close look at the example questionaire and you\nwill see what I mean. Also have a look at the SAMPLE_OUTPUT drawer for an\nupdated sample that matches this new questionaire format!\n\n@endnode\n@node "QAIRE" "D-ACCESS SAMPLE QUESTIONAIRE"\n\n                       HERE IS A SAMPLE QUESTIONAIRE\n                       ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n-----------------------------X8  SAMPLE  8X----------------------------------\n¹REAL NAME\nWhat IS Your Real FIRST Name?                    ~\n¹CITY,STATE & COUNTRY\nWhat CITY, STATE And COUNTRY Are You From?       ~\n¹GOT THE NUP FROM\nWho gave you My NUP?                             ~\n¹AGE\nWhat Is Your Age?                                ~\n¹SYSTEM:\nWhat Computer Do You Own?                        ~\n¹SEX\nAre You MALE or FEMALE?                          ~M/F|MALE/FEMALE\n¹BEST TIME TO CALL\nWhen Is The Best Time To Call You?               ~\n¹GROUP MEMBER\nAre You A Member Of A Group?                     ~Y/N|YES/NO\n¹MEMBER OF\n²YWhich Group Is That?                             ~\n¹BEEN A MEMBER FOR\n²YHow Long Have You Been In This Group?            ~\n³\n¹BBS''S\nList 3 Fast BBS''s You Are On                    ~3\n³\n¹WARES\nList Your 3 Newest Wares                        ~3\n³\n¹REFERENCES\nList 3 GOOD References                          ~3\n¹Agreed To Terms Of Disclamer\n\n                      THE PøINT BLåNK BBS DISCLAIMER !!!\n\n     There is NO GUARANTEE of PRIVACY within this system and all\ncommunications are subject to review and possible censorship by the System\nOperator and/or Co-System Operators.  ALL users who enter a name into this\nsystem do hereby consent to be bound by the terms contained herein and\nassume all risks of whatever nature or kind that may arise through the use\nthereof and agree to hold harmless the System Operator, for any activities\nregarding the use of this Electronic Bulletin Board System.\n     The System Operator shall NOT be responsible for the content of this\nBulletin Board System.  The views expressed within this board are those of\nthe Registered Users and NOT necessarily that of the System Operator.\n     Users of this BBS acknowledge that if they choose to use this BBS they\ndo so voluntarily and at their OWN risk!  Users may be removed from the\nsystem at ANYTIME if in the Sysop''s opinion the user hasin any way ABUSED\nthe Bulletin Board System.\n\n     This IS A PRIVATE SYSTEM!!!  Usage is strictly limited to authorized\nmembers!  Usage by a Regulatory, State, and/or Governmental agency\nfor any purpose IS STRICKLY FORBIDDEN via various legal regulations as a\nviolation of our rights of PRIVACY, FREE SPEECH, and other lawful rights\nguaranteed by The United States Constitution and other applicable laws and\nregulations.  Information, data, programming, and/or other information\ncontained within the system is strickly LIMITED for the private usage of\nOUR members.  NO other usage or dissemination is authorized by proper,\nimproper, false or illegal entry or other means of obtaining such\ninformation, data, or programming including unauthorized dissemination by\nour members.  No member is to knowingly violate FCC, Copyright, Obscenity,\nor other regulations.  We assume that ALL programming is within the\nPublic Domain and reserve the right to free usage and copies thereof for the\npurposes of testing, review, and archiving of said data or programming\nwithout shareware, fees, or other compensation to others.  If any member\nadvises us to the contrary of these regulations, we will gladly investigate\nand remove any materials not compatible with these regulations and is sole\nextent of liability herein.  The System Operator(s) (SYSOP) is NOT\nResponsible for any data contained in this system.\n³\nDo You Agree To Said Such Agreements and Terms?       ~Y/N|Yes/No\n²NWhy not?  This could affect your access a lot! ~3\n\n¹Member Of A Law Agency?\n\nAre You, or any other member of your family, a member of any agency, group,\norganization of an investigative, regulatory, or legal nature, or are you\nacting in any capacity either privately or in co-operation with any of the\nforesaid?        ~Y/N|Yes/No\n²YPlease Explain! ~2\n\n¹Agreed To Keep Material Private?\n\nDo you (New Applicant) agree to keep ALL materials/information\ntransfered/viewed from/on this Bulletin Board System (BBS) to yourself, and\nNOT disclose ANY information/programs to anyone else?       ~Y/N|Yes/No\n\n²NWhy not?  This could affect your access a lot!  ~2\n\n¹Permit Use Of This Info In Court\n\nDo you grant permission for the members to use any such information\ncontained in this questonaire, AND, with your replys to the contained\nsaid questions included in the Questionaire, ONLY in the case of a legal\ndispute, battle, claims, or any such legal involved action?        ~Y/N|Yes/No\n\n²NPlease Explain!  This could affect your access a lot! ~2\n\n-----------------------------X8  SAMPLE  8X----------------------------------\n@endnode\n@node "NOTIFY" "THE AUTO-NOTIFY FUNCTION"\n\nUSING THE AUTO-NOTIFY FUNCTION\n\nThere is an extra door included that you can put in your node bulletins\nthat will show the D-ACCESS.NEWLIST file to users whose access is the same\nor greater than the SYSOP_LEVEL in the config file. It shows all new users\nthat have not been validated yet and enables you to remove message access\nfor all new users which eliminates lots of unnecessary mail to you the\nsysop! There is a bulletin included with the necessary info in it or add\nthe following line to your NODE.X/BULL.X file and copy the DASHOW.INFO file\nto your BBSCMD drawer.\n \n------------------X8  SAMPLE  8X-----------------\n~CC_DASHOW\n------------------X8  SAMPLE  8X-----------------\n@endnode\n@node "notesmenu" "NOTES ON FUNCTIONING"\n\n                           NOTES ON FUNCTIONING\n                           ~~~~~~~~~~~~~~~~~~~~\nWhen a user activates D-ACCESS it translates the handle so that it doesn''t\ninclude any illegal file characters (like /, [, ") and opens a file in the\nNEW_APPS dir (in the D-ACCESS dir) whose name is the applicants handle. It\nis automatically stamped with the users handle, date, slot, time and Phone\nNumber and can easily be called upon from the D-ACCESS menu.\n \n               @{"USING D-ACCESS AS THE BUILT-IN SCRIPT FUNCTION   " link "BISCRIPT"}\n               @{"USING D-ACCESS AS A NODE.X/BULL10.TXT MCI COMMAND" link "bullsCRIPT"}\n               @{"THE APPLICATION DRAWERS                          " link "drawers"}\n               @{"USING INFINITE PRESETS                           " link "presets"}\n\n@endnode\n@node "biscript" "NOTES ON FUNCTIONING"\n\n              USING D-ACCESS AS THE BUILT-IN SCRIPT FUNCTION\n              ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nThere are several ways to utilize D-Access, first, it CAN be used as a\nreplacement for the internal /X SCRIPT files but several features will not\nfunction properly when used as such. /X will not save the new user''s account\nif carrier is lost during application so you *MUST* turn AUTO_GOODBY OFF, it\nwill save the D-Access application properly but will not save the user''s\naccount. You must also turn SYSOP_MESSY OFF, since the internal "C"omment\nfunction will not run from the script. Both DONATE_INFO and ACODE_BLOCK may\nstill be used with no bad side-effects.\n\n------------------X8  SAMPLE  8X-----------------\nSYSOP_LEVEL=250\nDONATE_INFO=YES\nSYSOP_MESSY=NO\nAUTO_GOODBY=NO\nACODE_BLOCK=YES\nAREA_CODE.1=513\nAREA_CODE.2=606\nAREA_CODE.3=812\n.\n.\n.\n------------------X8  SAMPLE 8X-----------------\n\n\n@endnode\n@node "bullscript" "NOTES ON FUNCTIONING"\n\n             USING D-ACCESS AS A NODE.X/BULL10.TXT MCI COMMAND\n             ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nI have found that the most effective way to install D-Access is to add it as\nan MCI command to the NEW USER conference''s BULL10.txt (~CC_ACCESS). Using \nthis method allows you to let the user log on but does not allow then to get\nto the menu unless AUTO_GOODBY is set to NO, and appears to run very similar\nto the SCRIPT menthod of installation BUT all of the features are fully\nfuncitional unlike the SCRIPT installation so I recommend this method.\n\n------------------X8  SAMPLE  8X-----------------\nSYSOP_LEVEL=250\nDONATE_INFO=YES\nSYSOP_MESSY=NO\nAUTO_GOODBY=YES\nACODE_BLOCK=YES\nAREA_CODE.1=513\nAREA_CODE.2=606\nAREA_CODE.3=812\n.\n.\n.\n------------------X8  SAMPLE  8X-----------------\n\n@endnode\n@node "DRAWERS" "APPLICATION DRAWERS"\n\n                            APPLICATION DRAWERS\n                            ~~~~~~~~~~~~~~~~~~~\nThere are 3 application storage drawers, NEW_APPS, OLD_APPS and BAD_APPS.\nIf an application is left in the new_apps drawer and AUTO-GOODBY is set to\nYES then when the user tries to log on and still hasn''t been given access\nD-Access sends a friendly message saying that the user hasn''t been validated\nyet and to try back in 24 hours and then hangs up. This keeps new users from\nwasting a lot of time at the menu prompt since they don''t get that far.\n\nOnce an application has been "validated" it is moved to the NEW_APPS drawer\nwhere it is stored unless moved to the BAD_APPS drawer or deleted.\n\nWhen you move an application into the BAD_APPS drawer it can be considered\ndead. The user will not be able to fill out another app and is given a\nmessage saying that their app has been moved to the BAD drawer and to please\nnot call again, sort of a Black Book of users you want to keep off for good.\nIf AUTO_GOODBY is set it hangs up on them each time they try and call,\nhopefully they''ll get the picture sooner or later and leave your system alone!\n@endnode\n@node "presets" "USING INFINITE PRESETS"\n\n                             INFINITE PRESETS\n                             ~~~~~~~~~~~~~~~~\nD-ACCESS now supports the preset icons in your BBS:ACCESS drawer. You can\nhave and infinite number of numbered presets in there, they should be\nnumbered like PRESET.1, PRESET.2... PRESET.99... PRESET.234, etc. and they\nwill show up on the screen when you go to validate or create accounts, you\njust select the number of the preset you want the account to have. If you run\nCONFERENCE ACCOUNTING you will want to answer YES when it asks to preset the\nratio in all accessible conferences.\n\n*NOTE* D-ACCESS WILL *NOT* set ratios in AMIXNET conferences.\n\n@endnode\n@node "sysopmenu" "USING THE SYSOP MODE"\n\n                               *SYSOP MODE*\n                               ~~~~~~~~~~~~ \nSysop mode is initiated when a user with an access level greater than or \nequal to the sysop access level set in the config file starts the door from\nthe menu prompt in the bbs. (I.E. type ACCESS at the menu prompt or replace\nas the "1" key!).\n\nI reccommend that you use D-ACCESS as a replacement for the internal /X "1"\ncommand, this allows you to let cosys look at apps and validate them, but\nwould optionally require a password to get to the real /X account editor to\nadjust other users stats. \n\n                       @{"*IMPORTANT NOTE*            " link "sysopnote"}\n                       @{"STANDARD COMMAND HELP FILE  " link "help"}\n                       @{"SYSOP HELP FILE             " link "sysophelp"}\n                       @{"EXPLANATION OF COMMAND TYPES" link "explain"}\n@endnode\n@node "sysopnote" "AN IMPORTANT NOTE"\n\n                             *IMPORTANT NOTE* \n                             ~~~~~~~~~~~~~~~~\nThe "S" command will NOT function if you enter the door through an MCI\ncommand. As it is set up, there is never any reason to go into your NEWUSER\nconference again and I suggest removing access to it from all of your\ncosysops. This should be the only conference where D-Access is set up as an\nMCI command. I also suggest putting the DASHOW MCI command into\nNODEx/bullx.txt. It only shows new users to people that have high enough\naccess to run D-Access.\n \nFrom the sysop''s point of view he has many functions at hand, like viewing\nany application, be it new, old (already validated) or bad, entering the\naccount editor, moving apps around and deleting apps. Online help is\navailable as well.  D-ACCESS automatically validates and gives\naccess to a user so whoever validates the user has be especially careful\nwith this feature.\n\n@endnode\n@node "sysophelp" "SYSOP HELP FILE"\n\n                       <D-ACCESS> V2.0 - SYSOP HELP FILE\n                       ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~          \nHere is a sample command line:\n\nCHOICE: (E,C,Q,?) :> \n\n\n E    - EDIT ACCOUNTS.  This command puts the user into the factory-installed\n        /X Account Editor.\n \n C    - CREATE.  This powerfull new feature allows you to make accounts\n        from scratch. It adds the accounts to the end of the user.data\n        file.  This is a handy feature if your system is closed to new users\n        since /X gives you no way to make an account from scratch if the\n        user does not log on.  When you use this option to make an account\n        you select the preset and whether or not to adjust the ratios in\n        all of the accessible conferences.\n \n Q    - QUIT back to the main screen.\n \n ?    - HELP. Shows this help file.\n@endnode\n@node "help" "STANDARD COMMAND HELP"\n                          <D-ACCESS> V2.0 - HELP FILE\n                          ~~~~~~~~~~~~~~~~~~~~~~~~~~~          \nHere is a sample command line:\n\nCHOICE: (@{"< & >" link ">"},@{"SPACE" link "SPACE"},@{"A" link "A"},@{"B" link "B"},@{"C" link "C"},@{"D" link "D"},@{"F" link "F"},@{"J" link "J"},@{"K" link "K"},@{"M" link "M"},@{"N" link "N"},@{"O" link "O"},@{"Q" link "Q"},@{"S" link "S"},@{"V" link "V"},@{"X" link "X"},@{"Z" link "Z"},@{"?" link "?"}) [*>\n \nThis help file is the complete list of sysop functions and their useage.\n@endnode\n@node ">" "SYSOP COMMAND HELP"\n\n> & <   (or , & . - you do not need to hold the shift key!) These keys scroll\n        the list of applications up and down, you can see that the middle one\n        on the list is enclosed in >< characters and if ansi is on it will be\n        highlighted. This is refered to as the HIGHLIGHTED command, if you it \n        <RETURN> it is the app that gets viewed.\n@endnode\n@node "SPACE" "SYSOP COMMAND HELP"\n\nSPACE - Use the spacebar to select/deselect multiple user applications for\n        performing operations on. Many functions have no effect unless\n        at least one name is selected. You can select as many apps as you\n        want.\n@endnode\n@node "A" "SYSOP COMMAND HELP"\n\n A    - ALL SELECT/DESELECT. This function selects all apps if unselected\n        and vice versa. Handy for moving all new-user apps quickly.\n@endnode\n@node "B" "SYSOP COMMAND HELP"\n\n B    - Changes apps being browsed to those in the BAD_APPS drawer.\n@endnode\n@node "C" "SYSOP COMMAND HELP"\n\n C    - COMMENT on HIGHLIGHTED app. You can attach a one-line comment to\n        any application.\n@endnode\n@node "d" "SYSOP COMMAND HELP"\n\n D    - Delete SELECTED Applications. Removes them permanently.\n@endnode\n@node "f" "SYSOP COMMAND HELP"\n\n F    - Fabricate an application. Allows you to enter an application for a\n        a user you specify while online.\n@endnode\n@node "j" "SYSOP COMMAND HELP"\n\n J    - Jump.  Allows you to jump to an application by searching for a key\n        you specify. Handy for moving around in large lists of users or\n        locating and jumping to a user without scrolling.\n@endnode\n@node "k" "SYSOP COMMAND HELP"\n\n K    - Kill. Moves SELECTED apps to the BAD_APPS drawer.\n@endnode\n@node "m" "SYSOP COMMAND HELP"\n\n M    - Message. Leave a message to HIGHLIGHTED user in the BAD_APPS area.\n        This message will be shown to it''s respective user if they try to log\n        on.\n@endnode\n@node "n" "SYSOP COMMAND HELP"\n\n N    - Changes apps being browsed to those in the NEW_APPS drawer.\n@endnode\n@node "o" "SYSOP COMMAND HELP"\n\n O    - Changes apps being browsed to those in the OLD_APPS drawer.\n@endnode\n@node "q" "SYSOP COMMAND HELP"\n\n Q    - QUIT. This command exits you from D-Access.\n@endnode\n@node "s" "SYSOP COMMAND HELP"\n\n S    - SYSOP commands.  This optionally password-protected command places\n        you in the sysop command menu. See Specific help file in that area.\n@endnode\n@node "v" "SYSOP COMMAND HELP"\n\n V    - VALIDATE. This command Validates the SELECTED users in the NEW_APPS\n        drawer. You will be prompted with each users name and which access\n        preset you wish to assign to this user. You are then asked whether\n        or not to set the ratio in all active conferences for each user.\n        *WARNING* This command REALLY VALIDATES the users and gives them\n        access - Use with caution! This command is only available to\n        Cosysops whose names appear in the D-Access.info icon!\n@endnode\n@node "x" "SYSOP COMMAND HELP"\n\n X    - XPERT mode on/off.  This command toggles the built-in menu on and\n        off.\n@endnode\n@node "z" "SYSOP COMMAND HELP"\n\n Z    - ANSI on/off toggle.\n@endnode\n@node "?" "SYSOP COMMAND HELP"\n\n ?    - HELP. Shows this help file.\n@endnode\n@node "explain" "SYSOP COMMAND HELP"\n\n                          EXPLANATION OF COMMANDS\n                          ~~~~~~~~~~~~~~~~~~~~~~~\n\nHOTKEYED COMMANDS - there are several commands that work as hotkeys, they are\nthe > & <, SPACEBAR and RETURN keys. Their functions are as follows:\n \n\n> & <   (or , & . - you do not need to hold the shift key!) These keys scroll\n        the list of applications up and down, you can see that the middle one\n        on the list is enclosed in >< characters and if ansi is on it will be\n        highlighted. This is refered to as the HIGHLIGHTED command, if you it \n        <RETURN> it is the app that gets viewed.\n \nSPACEBAR - The spacebar selects and deselects the HIGHLIGHTED app by placing\n        an asterisk (*) between the > and the username like this:\n        >*DALAI LAMA              <\n        This app would now be said to have been SELECTED. You can deselect\n        the app by pressing the spacebar again. Many commands require that\n        at least one application be selected for the operation to work.\n \nRETURN - the return key views the HIGHLIGHTED application.\n\n\nSTANDARD COMMANDS - The other keys on the list are called standard commands\nbecause they require you to hit <RETURN> after entering the command.\nDescriptions of what they do can be seen above and in the help file.\n@endnode\n@node "lastword" "A FINAL WORD"\n\nBy using this utility I have managed to cut the amount of space used for\napplication responses from:\n\n        Node1:answers = 323k\n        Node2:answers = 253k\n        Node3:answers = 202k\n        --------------------\n              TOTAL   = 778k for 112 user applications.\n\nNow I have 7 nodes and since I started running this util I have had 127 new\nusers and the answer files for all 127 new users is only 110k or about 85%\nsmaller than what you get with the internal system!  Try it!\n \n@endnode\n@node "contents" "D-ACCESS INDEX OF TOPICS"\n\n                         D-ACCESS INDEX OF TOPICS\n                         ~~~~~~~~~~~~~~~~~~~~~~~~\n\n@{" D-ACCESS V2.0 " LINK "info"}\n@{" CHANGES SINCE V1.5! " link "CHANGES"}\n@{" INTRODUCTION         " link "INTRO"}\n@{" OVERVIEW             " link "overview"}\n@{" INSTALLATION         " link "installation"}\n@{" CONFIGURING D-ACCESS " link "config"}\n@{" USING AUTO-NOTIFY    " LINK "notify"}\n@{" NOTES ON FUNCTIONING " LINK "notesmenu"}\n@{" USING THE SYSOP MODE " LINK "sysopmenu"}\n@{" A FINAL WORD         " LINK        "lastword"}\n@{"Global Overdose" link "GODinfo"}\n@{"D-ACCESS IS NOW FOR /X V3.X ONLY!!" link "30only"}\n@{"A CHANGE IN THE APPLICATION FORMAT" link "formatchange"}\n@{"NEW SYSOP FUNCTIONS               " link "SYSFUNCCHANGE"}\n@{"NEW AUTO-ACCESS-UPGRADE           " link "upgradechange"}\n@{"NEW TOOLTYPES                     " link "Tooltypechange"}\n@{"NEW BBSCMD ICON                   " link "Iconchange"}\n@{" CONFIGURING D-ACCESS " link "config"}\n@{"CONFIGURING THE ICON TOOLTYPES" LINK "CONFIG1"}\n@{"CONFIGURING THE TEXT FILES    " LINK "TextconFIG"}\n@{"CONFIGURING THE QUESTIONAIRES " LINK "qconFIG"}\n@{"CREATING NEW PASSWORDS        " LINK "pword"}\n@{"SYSOP_LEVEL" link "SYSOP_LEVEL"}\n@{"DONATE_INFO" link "DONATE_INFO"}\n@{"SYSOP_MESSY" link "SYSOP_MESSY"}\n@{"AUTO_GOODBY" link "AUTO_GOODBY"}\n@{"ACODE_BLOCK" link "ACODE_BLOCK"}\n@{"AREA_CODE.x" link "AREA_CODE.x"}\n@{"BLANKLINE_LOGOFF" link "BLANKLINE"}\n@{"COSY_ACCOUNT_EDIT" link "COSY_ACCOUNT_EDIT"}\n@{"COSY_NAME.x" link "COSY_NAME.x"}\n@{"SYSOP_PASSWORD" link "SYSOP_PASSWORD"}\n@{"NEWUSER_UPLOAD" link "NEWUSER_UPLOAD"}\n@{"UPLOAD_PATH" link "UPLOAD_PATH"}\n@{"DELETE_UPLOAD" link "DELETE_UPLOAD"}\n@{"DONATE_INFOFILE" link "DONATE_INFOFILE"}\n@{"USER_DATA_PATH" link "USER_DATA_PATH"}\n@{"QUESTIONS.x" link "QUESTIONS.x"}\n@{"QUESTIONAIRE" link "QAIRE"}\n@{"USING D-ACCESS AS THE BUILT-IN SCRIPT FUNCTION   " link "BISCRIPT"}\n@{"USING D-ACCESS AS A NODE.X/BULL10.TXT MCI COMMAND" link "bullsCRIPT"}\n@{"THE APPLICATION DRAWERS                          " link "drawers"}\n@{"USING INFINITE PRESETS                           " link "presets"}\n@{"*IMPORTANT NOTE*            " link "sysopnote"}\n@{"STANDARD COMMAND HELP FILE  " link "help"}\n@{"SYSOP HELP FILE             " link "sysophelp"}\n@{"EXPLANATION OF COMMAND TYPES" link "explain"}\n@{"< & >" link ">"}\n@{"SPACE" link "SPACE"}\n@{"A" link "A"}\n@{"B" link "B"}\n@{"C" link "C"}\n@{"D" link "D"}\n@{"F" link "F"}\n@{"J" link "J"}\n@{"K" link "K"}\n@{"M" link "M"}\n@{"N" link "N"}\n@{"O" link "O"}\n@{"Q" link "Q"}\n@{"S" link "S"}\n@{"V" link "V"}\n@{"X" link "X"}\n@{"Z" link "Z"}\n@{"?" link "?"}\n@endnode\n@node "Pword" "CREATING NEW PASSWORDS"\n\n                          CREATING NEW PASSWORDS\n                          ~~~~~~~~~~~~~~~~~~~~~~\nThere is a CLI util called GetPW in the D-ACCESS drawer. You can just type\nGETPW on a command line for the default BBS:USER.DATA file to be used, or\nspecify the full path and filename for your USER.DATA file.\n \nTo actually make new passwords and add them to the password list you should\ntake the following steps:\n \n1) Run your text editor and load the file DOORS:D-ACCESS/D-ACCESS.PWS. This\n   is the current list of Passwords and should look something like this:\n \n        LAMER 2F072675\n        SCHNITZEL 08165C6B\n        YELLO! 530A1635\n        FLEER C25DC482\n        .\n        .\n        .\n\n   The first word on the line is the actual password, the following\n   hexadecimal number is the ENCRYPTED equivalent of that password.\n\n   Now enter the passwords you want to add, one on each line, like this:\n \n        LAMER 2F072675\n        SCHNITZEL 08165C6B\n        YELLO! 530A1635\n        FLEER C25DC482\n        ZAGNUT \n        ZAPHOD \n        BLABBER\n        CHICLID\n\n   Once you have all the passwords you want to add in there go to step two.\n\n\n2) Load up the internal /X account editor and load account 1 (yours). Enter\n   one of the passwords from your new list (like ZAGNUT) into your account\n   and SAVE it!\n\n3) Go back to your CLI and run GetPW. It will come up like this:\n \n---------------------------------SAMPLE-------------------------------------\n5.DHA:bbs/utils> GetPW \n\n ENCRYPTED PASSWORD GETTER V0.1 By The Dalai Lama of Global Overdose \n\nUseage: GetPW <user.data path>\n\n              Enter full path & filename of USER.DATA file.\n              DEFAULT=BBS:USER.DATA\n\nThe Hex Value Of Encrypted Password is: FC5D6495\n\n---------------------------------SAMPLE-------------------------------------\n\nWe are after the Hex value of the encrypted password here, which is\nFC5D6495.  Enter this value after the password it is for in your list of\npasswords making sure to leave a space between the password and the\nencrypted version like this :\n\n        ZAGNUT FC5D6495\n\n4) Repeat steps 2 - 4 as necessary for the number of passwords you are\nentering.\n \n5) SAVE the new D-ACCESS.PWS file... and that''s it! Your new file should\nlook like this:\n\n        LAMER 2F072675\n        SCHNITZEL 08165C6B\n        YELLO! 530A1635\n        FLEER C25DC482\n        ZAGNUT FC5D6495\n        ZAPHOD E7B52D01\n        BLABBER 0613D6C6\n        CHICLID 742418C9\n\nThese values are accurate so you can use them to test whether or not you\nare doing it right and to see if it is correct.\n@endnode\n','\n',char(10)),NULL,'auto-added',213630,2,0,NULL,NULL,'god_da20','scan',1780048524);
INSERT INTO door_catalog VALUES('god_fron','GOD-FRON.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/GOD-FRON.LHA',NULL,'XIM','______/\________ _____/\ ________________',NULL,'Calypso/GOD','GOD','\____/   ______//    /  \\______   \____/ \_/    \_   \/    /\   \|    |\   \_/ \     |    \    \/   /|   /\/   /',replace('  ______/\________ _____/\ ________________ \n  \____/   ______//    /  \\______   \____/ \n    \_/    \_   \/    /\   \|    |\   \_/   \n      \     |    \    \/   /|   /\/   /     \nEXPRESS\__  _____/\_______/ |___\  __/DESIGN\n<---------\/- ·p·R·E·S·E·N·T·S· -\/-------->\nFrontEnd V1.0 by Calypso/GOD ! ASM XIM Door!\n Shows User + Action + Baud ! Logon-Batch !\n<------------------------------------------>\n','\n',char(10)),'FrontEnd.Doc',replace('                                    .    :\n.______ ______________.   __________|    |____ __________ _____. __________.\n|:::· ·/    _____     |__/__  _    ¬\     _  ¬\______   ¬\     |_____· ·:::|\n|:·  _/    |    ¬\_   |    ¬\_ |     \_  |     \_         \_   |    ¬\_   :| \n|·   \     |      /   |      / |      /  |  ÷e÷ /   |      /   |      /_ _·|\n|.  .\\__________/__________/________/_________/__________/__________//   .|\n|             .__                        .    ·                            |  \n|  _______ ___| ¬\ ________ _________ ___|    :_______  _________________  |\n: /  _   ¬\   |   \       ¬\_____   ¬\  _     ¦  _   ¬\/     ____       ¬\ :\n_/    |    \_ |    \_  |    \_ _/   _/   |    :   |    \____    ¬\_  |    \_\n\     |     / |     /  ______/ \    \__  |    :   |     /   |     /  ______/\n:\_________/_______/____________\     /_______¦________/_________/_______ _: \n+--------------------------------\___/-------------------------------------+\n¦                                                                          ¦\n:                                                                          :\n                                    PRESENTS\n\n                     FrontEnd V1.0 coded by CALYPSO/GOD !\n\n    PROFESSIONAL TOOLS FOR PROFESSIONAL SYSOPS - GET THE REAL QUALITY !\n\n\nWHAT''S THE USE OF THIS TOOL ?\n-----------------------------\n\n        It''s a Frontend displaying the users and actions\n        of the other Nodes + current users baudrate !\n\n        Plus the possibility to execute a Logonbatch !\n\n        Enjoy the fucking speed and look of it !\n\n        ASM rules !\n\n\nHOW TO INSTALL :\n----------------\n\n        S-Express and /X 2.x :\n        ----------------------\n\n        Copy these files in the archive to your directories,\n        they are :\n\n        BBS:Doors/FrontEnd/FrontEnd-S.XIM (!)\n        BBS:Doors/FrontEnd/FrontEnd.Doc\n\n        Append the BBS:Commands/SYS.CMD to your SYS.CMD !\n\n        \n        /X 3.x :\n        --------\n\n        BBS:Doors/FrontEnd/FrontEnd-A.XIM (!)\n        BBS:Doors/FrontEnd/FrontEnd.Doc\n\n\n        Copy the BBS:Commands/BBSCMD/FrontEnd.Info to your\n        BBS:Commands/BBSCMD/ !\n        \n\n\n        Copy Libs/AEDoor.library to your LIBS: !\n\n        Now you''re ready to go...\n\n\n\n        If you want to use a logon-batch, create a file :\n\n        BBS:Logon.Batch\n\n        The Nodenumber is passed by ! Enjoy !\n\n        Be sure it has the S Flag (protect +s) !\n\n\nLAST WORDS :\n------------\n        \n        Now have fun with this great tool !\n\n        For Bugs (there are none), Ideas (yeah !) or just for fun\n        call my BBS :\n\n        BLACK MOON   +49-7054-8733   G·O·D EXPRESS DESIGN HQ !\n                                     L^O^G^I^C wORLDHEADQUARTERS !\n                                     iLLUSION hEADQUARTERS !\n\n        (2 Nodes - USR Dual 16.8 !)\n\n        See ya soon mates...\n                                                   Calypso !\n                                                   ~~~~~~~\n\n\nTHANX TO :\n----------\n\n        My beta-testers :\n        -----------------\n                Dalai Lama/Point Plank\n                Rotor/Gates of Asgard\n                Freddy Krueger/Boiler Room\n                Bloodwolf/Mortuary\n\n\nP.S. : OTHER HIGH-QUALITY /X-TOOLS BY ME :\n------------------------------------------\n\n        Only latest versions listed here !\n\n\n        LGC-LCK2.LHA    - LHA-Check V2.0\n                          THE BEST LHA-CHECKER AVAILABLE !\n\n        LGC-ZIP.LHA     - ZIP-Check V1.0\n                          Guess what ?\n\n        LGC-QN20.LHA    - QuickNew V2.0\n                          Fucking great util !\n\n        GOD-ULDL.LHA    - BestUL V1.2 and BestDL V1.2\n                          Great Topuploaders and Topdownloaders XIMs !\n\n        GOD-WA12.LHA    - V1.2 of the fucking cool wall XIM !\n\n        All LOGIC and GOD utils ever released are available and\n        FREE-DOWNLOAD on my BBS !\n\n\nGREETINGS:\n----------\n\n      - G.E.M. - Runt&Scottie - Polaris - Skin - XAD - Deltaforce - Andy -\n      - Wedlock - Blackbird - Sisko - Planet Master - Proton - Bloodwolf -\n         - Linebacker - Cujo - Raider - Mitch - Mr.T - Samir - Power -\n\n                         - All LOGIC and GOD Members -\n\n··············································································\n\n           - G·O·D Express Design HQ - LOGIC WHQ - ILLUSION HQ -\n               _ ________           _ ______________\n         /\_______    _ /     _____   ________     /__: _____  sYSOPS:\n        /____  _ /    //_____/o  _/___  /    /____/   |/    /  """""""\n      _____:/  //     /     //   \    \/    /    //   /    /   cALYPSO !\n     /     |\  /__________ /.   /_\   /________ /.    \    \   cASTOR\n __|/____________\       \/_____________\     \/______|\____\  gHOSTRIDER\n   |                                                  :        (yOU ?)\n                     ! lOOKING fOR cOSYSOPs !      :_______|__\n 0.5      /\ __ /\             _______________     |    _ /|\n gIG hD! // \\//  \____________\________   _ /____ |    //   nUMBERS:\n 68o3o  /.   \/    \________   _ /     /   //     \|   o/    """"""""\n       /    \  /    \      /   //\    /    /|      \  ./  +49-7054-8733\n      /      \/______\    /    /  \_______/ |    \    /  +49-7054-eLITE!\n     /_______|        \_______/             |_____\  /\n             :                                Sk!n \/  bOTH nODES 16.8 DS!\n \n      rUNNING (LATEST!) S-eXPRESS - sUPPORTING aMIGA aND sNES oNLY !\n         aLL {<GOD>|<LOGIC>|<ILLUSION>}-Releases fREE dOWNLOAD !!!\n          cALL nOW ! Lotsa INTERNATIONAL cALLERS ! Simply eLITE !\n','\n',char(10)),NULL,NULL,7964,1,0,NULL,NULL,NULL,'scan',1780048524);
INSERT INTO door_catalog VALUES('god_lc21','GOD-LC21.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/GOD-LC21.LHA','LhaCheck','XIM','LhaCheck',NULL,'CALYPS0/G0D','GOD','\____/   ______//    /  \\______   \____/ \_/    \_   \/    /\   \|    |\   \_/ \     |    \    \/   /|   /\/   /',replace('  ______/\________ _____/\ ________________\n  \____/   ______//    /  \\______   \____/\n    \_/    \_   \/    /\   \|    |\   \_/\n      \     |    \    \/   /|   /\/   /\nEXPRESS\__  _____/\_______/ |___\  __/DESIGN\n<---------\/- ·p·R·E·S·E·N·T·S· -\/-------->\n       LHACheck V2.1 by CALYPS0/G0D !\n<------------------------------------------>\n     + Redesigned Output !\n     + HD-Buffer option to save RAM !\n     + All features from previous version\n       (check, add, strip, info-to-txt) !\n<------------------------------------------>\n','\n',char(10)),'LhaCheck.Doc',replace('                                    .    :\n.______ ______________.   __________|    |____ __________ _____. __________.\n|:::· ·/    _____     |__/__  _    ¬\     _  ¬\______   ¬\     |_____· ·:::|\n|:·  _/    |    ¬\_   |    ¬\_ |     \_  |     \_         \_   |    ¬\_   :| \n|·   \     |      /   |      / |      /  |  ÷e÷ /   |      /   |      /_ _·|\n|.  .\\__________/__________/________/_________/__________/__________//   .|\n|             .__                        .    ·                            |  \n|  _______ ___| ¬\ ________ _________ ___|    :_______  _________________  |\n: /  _   ¬\   |   \       ¬\_____   ¬\  _     ¦  _   ¬\/     ____       ¬\ :\n_/    |    \_ |    \_  |    \_ _/   _/   |    :   |    \____    ¬\_  |    \_\n\     |     / |     /  ______/ \    \__  |    :   |     /   |     /  ______/\n:\_________/_______/____________\     /_______¦________/_________/_______ _: \n+--------------------------------\___/-------------------------------------+\n¦                                                                          ¦\n:                                                                          :\n                                    PRESENTS\n\n                    LHACheck V2.0 coded by CALYPSO/GOD !\n\n    PROFESSIONAL TOOLS FOR PROFESSIONAL SYSOPS - GET THE REAL QUALITY !\n\n\nWHY SHOULD YOU USE THIS LHA-CHECKER IN YOUR BBS ?\n-------------------------------------------------\n\n        It''s the best and fastest LHA-Checker you''ve ever seen,\n        it''s 100% written in Assembler !\n\n        Removes ALL BBS-Ads !\n\n        Adds as many files (Ads) as you want !\n\n        You can add Time, Date, Nodenumber, Username and\n        Userlocation to your Addy !\n\n        It has an HD-Buffer Option to save RAM !\n\n        It''s freely configurable with many options !\n        \n        Error-Handling routines included, so it will never crash\n        if an error appears or you''ve configured something wrong !\n\n        I made it :) !\n\n\n  .-----------------------------------------------------------------------.\n  |       PLEASE READ THE REGISTER!.TXT INCLUDED IN THIS ARCHIVE !!!      |\n  `-----------------------------------------------------------------------''\n\n          ^^^ There is a list of all my doors/utils in here... check out !\n\n\nHOW TO INSTALL :\n----------------\n\n        Copy the whole LHACheck Directory wherever you want and\n        make an ASSIGN to it called CHECKER: !\n\n        Change your FCheck-Files LHA and LZH to this :\n\n        -----------Cut here-----------\n        CHECKER:LhaCheck\n        CHECK=ON STRIP=ON ADD=ON <Addyname>\n        WARNING: Skipping corrupt/extraneous data\n        Operation not entirely successful\n        -----------Cut here-----------\n\n        If you want you can switch some of the options :\n\n        CHECK=ON/OFF turn checking on/off (all in capitals) !\n\n        STRIP=ON/OFF turn stripping on/off !\n\n        ADD=ON/OFF turn adding on/off (includes textadding of time, date,\n                   node, username) !\n\n        <Addyname> The name of the textfile you want to add time, date,\n                   node, username (explained later) with full path !\n\n        For /X 3.x you can make icons including this, but\n        the easiest way is to copy the FCheck Dir included in the\n        archive to your FCheck Dir :) !!!\n\n        IMPORTANT:\n        ----------\n\n        Your LHA must be available through an AmigaDos-Path !!!\n        I use LHA V1.50, I don''t know if it works with older versions.\n        \n\nHOW TO STRIP AND ADD BBS-ADS :\n------------------------------\n\n        There are two Config-Files : LHACheck.Strip and LHACheck.Add !\n\n        The LHACheck.Strip includes all Filenames you want to\n        be stripped, wildcards allowed (e.g. *.displayme) !\n\n        Be careful with wildcards ! If you use them wrong it will\n        strip more files as you want !\n\n        You can strip ALL ILLEGAL FILENAMES, too !\n\n        Use [ and ] to do this... e.g. [*] strips a\n        file with the name ''*'' ... the * is not taken as a wildcard !\n\n        The LHACheck.Add includes all Filenames you want to be\n        added, just specify there your BBS-Ad(s) !\n\n        Easy, isn''t it ?\n\n\nHOW TO ADD TIME, DATE, ETC. :\n-----------------------------\n\n        Ok, now about adding of time, date, nodenumber, username and\n        userlocation to your addy :\n\n        You can include wherever(!) you want these special symbols :\n\n        XX:XX:XX            ... will be replaced with the current time !\n\n        DD-MMM-YY           ... will be replaced with the current date !\n\n        §                   (shift-3) ... will be replaced with the NodeNr. !\n\n        ==UPLOADERNAME==    ... will be replaced with the name of the\n                                uploader (longer names will be cut off) !\n\n        =L=O=C=A=T=I=O=N=!= ... will be replaced by the User-Location !\n\n\n        Be sure that you have the filename <addyname> in your LHACheck.Add :)\n\n        Take a look at the examples in the archive...\n\n        If you don''t want to use this feature, then just do not\n        include the special symbols in your addy, but you have to\n        pass a valid <addyname> to the checker, or you will get an\n        error-message !\n\n\nHD-BUFFER OPTION (READ !) :\n---------------------------\n\n        You need an assign called PLAYPEN ... you can put it\n        where you want !\n\n        SAVE MAXIMUM RAM :\n        ------------------\n\n        Put T: and PLAYPEN: on your HD !\n\n        SAVE A BIT RAM AND MORE SPEED :\n        -------------------------------\n\n        Put T: into RAM: and PLAYPEN: on your HD !\n\n        SAVE NO RAM AND GET MAXIMUM SPEED :\n        -----------------------------------\n\n        Put T: into RAM: and PLAYPEN: into RAM: !\n\n\n        I think you got it... if not, then ask me !\n\n\nLAST WORDS :\n------------\n        \n        Now have fun with this great tool !\n\n        For Bugs (there are none), Ideas (yeah !) or just for fun\n        call my BBS :\n\n        BLACK MOON   +49-Private!    GOD-German Worldheadquarters !\n\n\n        See ya soon mates...\n                                                   Calypso !\n                                                   ~~~~~~~\n\nHISTORY :\n---------\n\n        V1.0    :       First public release ! (Written in 4 hours...)\n\n        V2.0    :       Major update, added switches for checking,\n                        stripping, adding and the option to add\n                        time, date, etc. to a textfile !\n                        (Written during 3 days...)\n\n        V2.1    :       HD-Buffer option added !\n                        Illegal-strip info to docs added !\n                        Re-designed output !\n\n\nTHANKS TO MY TESTERS :\n----------------------\n\n        Zion (Zions Hideout), Dr. Chaos (Black Hole)\n        Freddy Krueger (Boiler Room)\n\n\n  .-----------------------------------------------------------------------.\n  |       PLEASE READ THE REGISTER!.TXT INCLUDED IN THIS ARCHIVE !!!      |\n  `-----------------------------------------------------------------------''\n\n          ^^^ There is a list of all my doors/utils in here... check out !\n\n··············································································\n\n                 - GLOBAL OVERDOSE GERMAN HQ - LOGiC WHQ -\n               _ ________           _ ______________\n         /\_______    _ /     _____   ________     /__: _____  sYSOPS:\n        /____  _ /    //_____/o  _/___  /    /____/   |/    /  """""""\n      _____:/  //     /     //   \    \/    /    //   /    /   cALYPSO/GOD\n     /     |\  /__________ /.   /_\   /________ /.    \    \   cASTOR/PDX\n __|/____________\       \/_____________\     \/______|\____\  mIKE & dAVE/CLS\n   |                                                  :        sPIKE\n                      ·b·L·A·C·K· ·m·O·O·N·       :_______|__\n         /\ __ /\             _______________     |    _ /|    cALL :\n        // \\//  \____________\________   _ /____ |    //      """" "\n       /.   \/    \________   _ /     /   //     \|   o/     +49-Private!\n      /    \  /    \      /   //\    /    /|      \  ./      """"""""""""\n     /      \/______\    /    /  \_______/ |    \    /   USR 28.8 DUAL !\n    /_______|        \_______/             |_____\  /    """ """" """"""\n            :                                Sk!n \/ \n\n     rUNNiNG (LATEST!) S-eXPRESS - sUPPORTiNG aMiGA aND cONSOLE oNLY !\n             aLL {<GOD>|<iLLUSiON>}-rELEASES fREE dOWNLOAD !!!\n          cALL nOW ! LOTSA iNTERNATiONAL cALLERS ! SiMPLY eLiTE !\n','\n',char(10)),NULL,'auto-added',8554,2,0,NULL,NULL,'god_lc21','scan',1780048524);
