INSERT INTO door_catalog VALUES('god_qn21','GOD-QN21.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/GOD-QN21.LHA',NULL,'XIM','QuickNew',NULL,'CALYPS0/G0D','GOD','\____/   ______//    /  \\______   \____/ \_/    \_   \/    /\   \|    |\   \_/ \     |    \    \/   /|   /\/   /',replace('  ______/\________ _____/\ ________________ \n  \____/   ______//    /  \\______   \____/ \n    \_/    \_   \/    /\   \|    |\   \_/   \n      \     |    \    \/   /|   /\/   /     \nEXPRESS\__  _____/\_______/ |___\  __/DESIGN\n<---------\/- ·p·R·E·S·E·N·T·S· -\/-------->\n       QuickNew V2.1 by CALYPS0/G0D !\nThe update to the ultimate util ! Pure ASM !\n<------------------------------------------>\n','\n',char(10)),'QuickNew.Doc',replace('                                    .    :\n.______ ______________.   __________|    |____ __________ _____. __________.\n|:::· ·/    _____     |__/__  _    ¬\     _  ¬\______   ¬\     |_____· ·:::|\n|:·  _/    |    ¬\_   |    ¬\_ |     \_  |     \_         \_   |    ¬\_   :| \n|·   \     |      /   |      / |      /  |  ÷e÷ /   |      /   |      /_ _·|\n|.  .\\__________/__________/________/_________/__________/__________//   .|\n|             .__                        .    ·                            |  \n|  _______ ___| ¬\ ________ _________ ___|    :_______  _________________  |\n: /  _   ¬\   |   \       ¬\_____   ¬\  _     ¦  _   ¬\/     ____       ¬\ :\n_/    |    \_ |    \_  |    \_ _/   _/   |    :   |    \____    ¬\_  |    \_\n\     |     / |     /  ______/ \    \__  |    :   |     /   |     /  ______/\n:\_________/_______/____________\     /_______¦________/_________/_______ _: \n+--------------------------------\___/-------------------------------------+\n¦                                                                          ¦\n:                         E·X·P·R·E·S·S · D·E·S·I·G·N                                                     :\n\n                                    PRESENTS\n\n                      QuickNew V2.1 coded by CALYPSO/GOD !\n\n    PROFESSIONAL TOOLS FOR PROFESSIONAL SYSOPS - GET THE REAL QUALITY !\n\n\nWHAT''S THE USE OF THIS TOOL ?\n-----------------------------\n\n        This tool creates a textfile which includes all filenames\n        today uploaded in every (selected) conference !\n\n        It creates a nice Ansi-Output which you can display\n        after the Logonscreen or after the Lastcallers (look for\n        examples how to do this later in this docs) !\n\n        Another possibility is to make bulls for each conference !\n\n        It''s very nice to get a quick overview of all new files.\n        Also the users can see if there are new files in a conference\n        which has not every day new files !\n\n        Gives many additional informations, like Number of Files and\n        Fakes, total Megs for today and yesterday (configurable) !\n\n        Ofcourse it''s another high-quality tool from me, 100% written\n        in Assembler for maximum speed !\n        \n        ... and it''s the fastest/best-looking one !!!\n\n  .-----------------------------------------------------------------------.\n  |       PLEASE READ THE REGISTER!.TXT INCLUDED IN THIS ARCHIVE !!!      |\n  `-----------------------------------------------------------------------''\n\nHOW TO INSTALL :\n----------------\n\n        First you have to edit your Config-File(s) !\n        (I use S:QuickNew.Config(x) !)\n\n        The first line of the Config-File includes the Prefix\n        displayed for every normal filename (normally a colour-code,\n        like [0m) !\n\n        The second line includes the Prefix displayed for every\n        deleted (nuked) file !!! So can show your nuked files\n        in RED or some other colour ! (I use [35m)\n\n        (The tool detects deleted files with the ''D'' in the Dirfile, so\n         be sure to use a Faker which supports this, e.g. Amifaker !)\n\n        The third line is the DisplayMode ! There are three available :\n\n        1 - Normal Displaymode   : All Files are shown right after\n                                   each other.\n\n        2 - Columns Displaymode  : The Files will be shown in columns\n                                   (my prefered one !)\n\n        3 - Centered Displaymode : The Lines with the Files will be\n                                   shown centered ! (also nice)\n\n\n    ->  Now you write down the text you want to display ! You can write\n    |   there what you want ! The end of your text must be marked with\n    |   a line only including a ''#'' !\n    |\n    |   After the text you give the full path + name of your upload-dirfile\n    |   of the corresponding conference !\n    |\n    ---- repeat this to show multiple Conferences !\n\n\n        Special Features :\n        ------------------\n\n        You can include special keywords in your text, these are :\n\n        @N      Number of todays files...    \n        @F      Number of todays fakes...    \n        @Y      Number of yesterdays files...\n        @Z      Number of yesterdays fakes...\n        @M.0    Todays Megs uploaded !       \n        @B.0    Yesterdays Megs uploaded !\n\n\n        Take a look at the included examples and change them to your\n        needs !\n\n\n        Here''s also an example :\n\n----------------------------(cut here)--------\n[0m\n[35m\n2\nINSERT INTO door_catalog VALUES('god_qn22','GOD-QN22.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/GOD-QN22.LHA','QuickNew','XIM','QuickNew',NULL,'CALYPS0/G0D','GOD','\____/   ______//    /  \\______   \____/ \_/    \_   \/    /\   \|    |\   \_/ \     |    \    \/   /|   /\/   /',replace('  ______/\________ _____/\ ________________ \n  \____/   ______//    /  \\______   \____/ \n    \_/    \_   \/    /\   \|    |\   \_/   \n      \     |    \    \/   /|   /\/   /     \nEXPRESS\__  _____/\_______/ |___\  __/DESIGN\n<---------\/- ·p·R·E·S·E·N·T·S· -\/-------->\n        QuickNew V2.2 by CALYPS0/G0D\n         2019 Update by REbEL/QTX !\nThe update to the ultimate util ! Pure ASM !\n<------------------------------------------>\n','\n',char(10)),'QuickNew.Doc',replace('                                    .    :\n.______ ______________.   __________|    |____ __________ _____. __________.\n|:::· ·/    _____     |__/__  _    ¬\     _  ¬\______   ¬\     |_____· ·:::|\n|:·  _/    |    ¬\_   |    ¬\_ |     \_  |     \_         \_   |    ¬\_   :| \n|·   \     |      /   |      / |      /  |  ÷e÷ /   |      /   |      /_ _·|\n|.  .\\__________/__________/________/_________/__________/__________//   .|\n|             .__                        .    ·                            |  \n|  _______ ___| ¬\ ________ _________ ___|    :_______  _________________  |\n: /  _   ¬\   |   \       ¬\_____   ¬\  _     ¦  _   ¬\/     ____       ¬\ :\n_/    |    \_ |    \_  |    \_ _/   _/   |    :   |    \____    ¬\_  |    \_\n\     |     / |     /  ______/ \    \__  |    :   |     /   |     /  ______/\n:\_________/_______/____________\     /_______¦________/_________/_______ _: \n+--------------------------------\___/-------------------------------------+\n¦                                                                          ¦\n:                         E·X·P·R·E·S·S · D·E·S·I·G·N                                                     :\n\n                                    PRESENTS\n\n                      QuickNew V2.2 coded by CALYPSO/GOD !\n                      \n                              Updated by REbEL/QTX \n\n    PROFESSIONAL TOOLS FOR PROFESSIONAL SYSOPS - GET THE REAL QUALITY !\n\n\nWHAT''S THE USE OF THIS TOOL ?\n-----------------------------\n\n        This tool creates a textfile which includes all filenames\n        today uploaded in every (selected) conference !\n\n        It creates a nice Ansi-Output which you can display\n        after the Logonscreen or after the Lastcallers (look for\n        examples how to do this later in this docs) !\n\n        Another possibility is to make bulls for each conference !\n\n        It''s very nice to get a quick overview of all new files.\n        Also the users can see if there are new files in a conference\n        which has not every day new files !\n\n        Gives many additional informations, like Number of Files and\n        Fakes, total Megs for today and yesterday (configurable) !\n\n        Ofcourse it''s another high-quality tool from me, 100% written\n        in Assembler for maximum speed !\n        \n        ... and it''s the fastest/best-looking one !!!\n\n  .-----------------------------------------------------------------------.\n  |       PLEASE READ THE REGISTER!.TXT INCLUDED IN THIS ARCHIVE !!!      |\n  `-----------------------------------------------------------------------''\n\nHOW TO INSTALL :\n----------------\n\n        First you have to edit your Config-File(s) !\n        (I use S:QuickNew.Config(x) !)\n\n        The first line of the Config-File includes the Prefix\n        displayed for every normal filename (normally a colour-code,\n        like [0m) !\n\n        The second line includes the Prefix displayed for every\n        deleted (nuked) file !!! So can show your nuked files\n        in RED or some other colour ! (I use [35m)\n\n        (The tool detects deleted files with the ''D'' in the Dirfile, so\n         be sure to use a Faker which supports this, e.g. Amifaker !)\n\n        The third line is the DisplayMode ! There are three available :\n\n        1 - Normal Displaymode   : All Files are shown right after\n                                   each other.\n\n        2 - Columns Displaymode  : The Files will be shown in columns\n                                   (my prefered one !)\n\n        3 - Centered Displaymode : The Lines with the Files will be\n                                   shown centered ! (also nice)\n\n\n    ->  Now you write down the text you want to display ! You can write\n    |   there what you want ! The end of your text must be marked with\n    |   a line only including a ''#'' !\n    |\n    |   After the text you give the full path + name of your upload-dirfile\n    |   of the corresponding conference !\n    |\n    ---- repeat this to show multiple Conferences !\n\n\n        Special Features :\n        ------------------\n\n        You can include special keywords in your text, these are :\n\n        @N      Number of todays files...    \n        @F      Number of todays fakes...    \n        @Y      Number of yesterdays files...\n        @Z      Number of yesterdays fakes...\n        @M.0    Todays Megs uploaded !       \n        @B.0    Yesterdays Megs uploaded !\n        @D      Number of days of data to process (eg instead of yesterday\n                and today it can be last 7 days and previous 7 days.\n\n        Take a look at the included examples and change them to your\n        needs !\n        Here''s also an example :\n\n----------------------------(cut here)--------\n[0m\n[35m\n2\nINSERT INTO door_catalog VALUES('god_scan','GOD-SCAN.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/GOD-SCAN.LHA',NULL,'XIM','AEDoor.library',NULL,'CALYPS0/G0D','GOD','\____/   ______//    /  \\______   \____/ \_/    \_   \/    /\   \|    |\   \_/ \     |    \    \/   /|   /\/   /',replace('  ______/\________ _____/\ ________________ \n  \____/   ______//    /  \\______   \____/ \n    \_/    \_   \/    /\   \|    |\   \_/   \n      \     |    \    \/   /|   /\/   /     \nEXPRESS\__  _____/\_______/ |___\  __/DESIGN\n<---------\/- ·p·R·E·S·E·N·T·S· -\/-------->\n       Best-Scan V1.0 by CALYPS0/G0D !\nThe FASTEST and BEST-LOOKING Newfiles Door !\n Fully configurable, new features ! GREAT !\n  ASM XIM POWER ! Why use something else ?\n<------------------------------------------>\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 20:29:48  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',3438,1,0,NULL,NULL,'god_scan','scan',1780048532);
INSERT INTO door_catalog VALUES('god_tf02','GOD-TF02.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/GOD-TF02.LHA','RPStart','XIM','RPStart','2.0',NULL,'GOD','-COCKtAILS BBS-',replace('AMIFAKERV2.0 TOP FAKER V0.2\n                             -COCKtAILS BBS-\n','\n',char(10)),'HowToUse.Doc',replace(' \n              _/\_____/\      _____   _______    /\   _/\\n             /..____/|..|    /.._..\ |_____  \  /..\  |..|\n            /  /____ |  |   /  / \  \ |..|/../ /    \ |  |\n           /../|_  _||  |  <=> > < <=>|  |\  \/  /\  \|  |\n           \  \_|..| |..|_/\\..\_/../ |..|/../../__\..\..|_/\\n            \______| |______\\_____/ |______/  //______> ____\\n                                           <../\n                                            \/\n     _____ ___    ___ _/\___________  ______    _____   _/\______ _/\____\n    /.._..\\..\  /..//..____/_____  \|____  \  /.._..\  |.. __. //..____/\n   /  / \  \\  \/  //  /__   |..|/../ |..|\..\/  / \  \ |  |__\//  /__ \n  <=> > < <=>\    //  ___/   |  /  /  |  | \  \> > < <=>|__   |/  ___/\n   \..\_/../  \../ \..\____  |..\  \  |..|_/../..\_/..//\__|..|\..\____ \n    \_____/    \/   \_____/  |__|\..\|_______/ \_____//_______| \_____/\n                                  \__\\n ---------------------------------------------------------------------------\n\n    CaLL THeSe DiViNe HaNG-ouTS iN oRDeR To GeT THe LaTeST uPCoMiNG\n \n ---------------------------------------------------------------------------\n\n            G.O.D. EHQ  - SLeeP CiTy -  +31/(0)79/219299\n\n           G.O.D. WHQ - HoRNeTS NeST -  301-229-8032 (3 NoDeZ RiNGDoWN)\n\n      G.O.D. BHQ - CaRRieR oF BeLieF -  +32/(0)50/340428!\n\n ---------------------------------------------------------------------------\n\n                -=>*<=- AMIFAKERV2.0 TOP FAKER V0.2 -=>*<=-\n\nWhat does it do:\n----------------\n\nIt will read your AMIFAKER.DATA and takes the fakers out,\nthen it will create a nice bulletin of the Top 10 Fakers\n\nHow to install:\n--------------\n\nTo use this Util you need AMIFAKER V2.0\nbecouse that create''s the AMIFAKER.DATA, without this file the Util\nwill not work...(hehehe Strange hu!!)\n\n\nPut the GODFake.cfg file in your BBS directory and edit it to your needs.\n\n\nThere are some more files in the archive like:\nRPSTART\n        put that in your C directory and add it into your Startup_sequence\n        i''m not sure if it needs it but I know that a lot off utils made\n        with arexx will.\nREXXPLSLIB.LIBRARY\n        Put this one into your Libs Directory and that is about it.\n\nI had a clear screen installed in it at first but because some sysops\nwanted to put a header infront of my Top_Faker Bulletin I decided to\nremove it...\nJust use th join command to put your header in the bulletins if you\nwish to...\n\nJoin "Header.txt to (the faker bulletin) as (your new bulletin name)\n\nThe next version will have a Header Option in it and a Total Faked Bytes\nand Faked Files uploaded routine...\n\n\nAnd now!!!! some thanx to...\n\nTR-PLE-I   - For helping me out with the sort routine.\n             and for getting me hooked on Arexx.\n\n\nGreetings to..........\n\nFREUD      - Big pal (Beer & Cola ??? )\nB.O.B.     - Run this Util and STOP! asking me if it''s ready yet\n             Here it is so ... Enjoy\nROTOX      - Will give you that call a.s.a.p.\nSTING      - Running express 2.X yet ??? (Hehehe )\n             Get a NORMAL computer and dump that Pc (Ami Rulez! )\nCHRIS      - My thoughts are with you (My A2000 ain''t )\n\nAnd ofcoz all my "Good" users which I finaly can pay back all those fake\nuploadz... (2* Credz lost ofcoz Hehehe )\n\n                            JAF/GLOBAL OVERDOSE\n','\n',char(10)),NULL,'auto-added',44048,3,0,NULL,NULL,'god_tf02','scan',1780048532);
INSERT INTO door_catalog VALUES('god_ul16','GOD-UL16.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/GOD-UL16.LHA','userlist','XIM','userlist',NULL,NULL,'GOD','! /\__________   ______ ____ _____________ ! :/  \_ _  ___/___\____ Y _ _\_________   /_: /         /   /      / :   //        / __ /.',replace('+--------+[...GLobaL OverDose...]+---------+\n! /\__________   ______ ____ _____________ !\n:/  \_ _  ___/___\____ Y _ _\_________   /_:\n/         /   /      / :   //        / __ /.\n\__________  /\____________/___________ // |\n+----------\/-----PresenTs:--------Sk!n\/--+\n/X2.+ UserList v1.6 (Requested) Update /X3.+\n','\n',char(10)),'userlist.doc',replace('           _______________    _________________________________\n   .__.    \_____     /  /    \___    \_____    \_____    \   /        .__.\n   |  |    / ___/____/   \____/   \   /  __/   _/   _/    /   \____ .__|  |__.\n   |  |  _/  \___    \    \   \    \  \  \___   \         \    \   \|___  ___|\n   |  |  \      /     \_  /    \_  /   \_   /    \_  __    \_  /    \_ |  |\n.__|  |__.\    /       / /      / /     /  /      /   /     / /      / |  |\n|___  ___| \_________ /_______ /______ /________ /___/____ /_______ /  |  |\n   |__|     +-------\/-------\/------\/--[P!]--\/--------\/------+\/   |__|\n  ___________________________________________________________________________\n  \___     \   /    \___      ___    \___   \_____     \____      ____      /\n  /   \    /   \    /   \____/  |\   /   \   \    \    /    \____/    \____/\n_/     \   \    \   \     _)/   |/  /    |\   \    \   \______   \      _)__\n\      /    \_  /    \_  /  \_  /   \    |/    \_  /    \_   /    \_   /    \_\n \    /      / /      / /    /  \    \   /      / /      /  /      /  /      /\n  \________ /_______ /_____ /____\    \_______ /_______ /________ /________ /\n   +------\/-------\/-----\/------\____\-----\/-------\/--------\/-------+\/\n\n       <-   -  -- --- + PuRgE WhAt WaS - FeAr WhAt CoMeS + --- --  -   ->\n\n\n                     NewUserList v1.6 Requested Update\n\nI know I know another Userlist Creator I just released it for the guy''s that\nasked me to update it...\nSinds the old version showed the deleted user and had a config file for the\nOutput, I thought what the heck let''s update it.\nSo here it is, have fun with it or just delete it who carez i know some of \nyou out there like it....\n\nIt''s written in Arexx but soon you will see some stuff from me in Amiga-E or\nC but for now this is the best i can do 8-)\n\nWhat does it do?\n~~~~~~~~~~~~~~~~\nGet outa here! and start playing games.\n\nWhat does it need?\n~~~~~~~~~~~~~~~~~~\nA User.data from /X and a RexxPlus setup.\n\nHow do I install it?\n~~~~~~~~~~~~~~~~~~~~\nJust type UserList and all info shows up.\n\nBug''s?\n~~~~~~\nNone at the moment.\n\nHow to contact?\n~~~~~~~~~~~~~~~\nIf anyone carez you can leave me mail on all G.O.D bbs''s\nor Mail me with /XNetmail like this JAF@NL0001\n\nAnd now some greetings to!\n~~~~~~~~~~~~~~~~~~~~~~~~~~\nFreddy Krueger ---> Hope that recieve ya 21k6 soon. (USR slow basterds)\n-TCB-!         ---> You know me just got pissed again.\nDalai Lama     ---> D-Access still the BEST.\nPurple Haze    ---> What can i say,nothing but good things.(hallogeenlampje)\nBandito        ---> How ya doing mate, tryed to call but ya bbs is to busy.\nMr.Solo        ---> The trading devil.\nMr.Frostie     ---> Keep ya hands off those beers.\nHighlander     ---> Another trading devil.\n\nJPS            ---> Best uploader I have, and continue coding lazy ass!\nByteAndi/Mst   ---> Your FileId rules.\nEmpire/Mst     ---> UDClean the best no need to say more.\nFornax         ---> Hope you like this one!\nB.o.b./CF      ---> For being a pal in hard times.\n\nand all others I seem to have forgotten...\n','\n',char(10)),NULL,'auto-added',16194,2,0,NULL,NULL,'god_ul16','scan',1780048532);
INSERT INTO door_catalog VALUES('god_vd10','GOD-VD10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/GOD-VD10.LHA',NULL,'XIM','______/\________ _____/\ ________________',NULL,NULL,'GOD','\____/   ______//    /  \\______   \____/ \_/    \_   \/    /\   \|    |\   \_/ \     |    \    \/   /|   /\/   /',replace(' ______/\________ _____/\ ________________\n \____/   ______//    /  \\______   \____/\n   \_/    \_   \/    /\   \|    |\   \_/\n     \     |    \    \/   /|   /\/   /\n      \__  _____/\_______/ |___\  __/\n<--------\/-- GL0BAL 0VERD0SE --\/--------->\n  /X2.+   V & D SeTtInGs BaSe v1.0   /X3.+\n','\n',char(10)),'setter.doc',replace('\n                 ______/\________ _____/\ ________________  \n                 \____/   ______//    /  \\______  ¬\____/  \n                   \_/    \_  ¬\/    /\   \|    |\   \_/    \n                     \     |    \    \/   /|   /\/   /      \n                      \__  _____/\_______/ |___\  __/       \n                       ·-\/--<GL0BAL 0VERÐOSE>--\/-·\n                             ·P·R·E·S·E·N·T·S·\n\n                      ViEW & DowNloaD SeTTiNgS V 1.0\n\n                                    by\n\n                        JaF/GoD and JpS/Independent\n\n            JpS says, "lt''s go ''C'' "  JaF says, "Let''s go ''E'' "\n      ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nWhat does it do?\n~~~~~~~~~~~~~~~~\nIt let''s you View and Download Modem Settings from the setting base\nbeats the hell out of snapping or capture 8)\nI just got sick and tired from users asking for modem settings and now\na days you just can''t put them all in a bulletin hehehe to many modems\n around.\nSo we made this little door and that solved our problem.\n\nHow to Install:\n~~~~~~~~~~~~~~~\nSimple just copy the Setter directory to your Doors: directory\n\nand edit your customcommands like this\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nAmiExpress 2.+\n--------------\n*SETTER    RM001DOORS:SETTER/SETTER.REXX\n\nAmiExpress 3.+\n--------------\nJust copy the Setter.info to the BBSCMD directory\nand thats about it.\n\nThe Door can handle up to 99 settings all you have to do is copy your\nsetting to the Settings directory and edit the menu.\n\nBug''s\n~~~~~\nNone known by me! but were only human so if you find any leave us some\nfeedback about it.\n\nyou can reach us by /X Netmail System leave mail to\n\nJAF@NL0001 or JPS@NL0001 or give us a call at\n\nSleepCity    +31-79-219299 or 79-521171 Sysop: Jaf\n                           or\nRed October  +31-10-4165552 3 Nodes Ringdown\n\nGreetings must go to:\n \nAll members of Global OverDose.\nand all we know they know who they are......\n','\n',char(10)),NULL,NULL,8596,1,0,NULL,NULL,NULL,'scan',1780048532);
INSERT INTO door_catalog VALUES('god_wa14','GOD-WA14.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/GOD-WA14.LHA',NULL,'XIM','______/\________ _____/\ ________________',NULL,'Calypso/GOD','GOD','\____/   ______//    /  \\______   \____/ \_/    \_   \/    /\   \|    |\   \_/ \     |    \    \/   /|   /\/   /',replace('  ______/\________ _____/\ ________________ \n  \____/   ______//    /  \\______   \____/ \n    \_/    \_   \/    /\   \|    |\   \_/   \n      \     |    \    \/   /|   /\/   /     \nEXPRESS\__  _____/\_______/ |___\  __/DESIGN\n<---------\/- ·p·R·E·S·E·N·T·S· -\/-------->\n           TheWall V1.4 - Update !\n        ASM XIM Door by Calypso/GOD !\n<------------------------------------------>\n','\n',char(10)),'TheWall.Doc',replace('                                    .    :\n.______ ______________.   __________|    |____ __________ _____. __________.\n|:::· ·/    _____     |__/__  _    ¬\     _  ¬\______   ¬\     |_____· ·:::|\n|:·  _/    |    ¬\_   |    ¬\_ |     \_  |     \_         \_   |    ¬\_   :| \n|·   \     |      /   |      / |      /  |  ÷e÷ /   |      /   |      /_ _·|\n|.  .\\__________/__________/________/_________/__________/__________//   .|\n|             .__                        .    ·                            |  \n|  _______ ___| ¬\ ________ _________ ___|    :_______  _________________  |\n: /  _   ¬\   |   \       ¬\_____   ¬\  _     ¦  _   ¬\/     ____       ¬\ :\n_/    |    \_ |    \_  |    \_ _/   _/   |    :   |    \____    ¬\_  |    \_\n\     |     / |     /  ______/ \    \__  |    :   |     /   |     /  ______/\n:\_________/_______/____________\     /_______¦________/_________/_______ _: \n+--------------------------------\___/-------------------------------------+\n¦                                                                          ¦\n:                                                                          :\n                                    PRESENTS\n\n                      TheWall V1.4 coded by CALYPSO/GOD !\n\n    PROFESSIONAL TOOLS FOR PROFESSIONAL SYSOPS - GET THE REAL QUALITY !\n\n  .-----------------------------------------------------------------------.\n  |       PLEASE READ THE REGISTER!.TXT INCLUDED IN THIS ARCHIVE !!!      |\n  `-----------------------------------------------------------------------''\n\nWHAT''S THE USE OF THIS TOOL ?\n-----------------------------\n\n        This is a nice Wall Door... ofcoz with the speed and\n        quality you expect from me, hehe... ASM rules !\n\n        Featuring:\n\n        Random color and centering of the text !\n        Auto adding of username, or anonymous line !\n        Really cool look with the background by Seven /\/\ !\n\n        Enjoy !\n\n        Read the History at the end of the this file and you\n        will know what''s new in this version !\n\n  .-----------------------------------------------------------------------.\n  |       PLEASE READ THE REGISTER!.TXT INCLUDED IN THIS ARCHIVE !!!      |\n  `-----------------------------------------------------------------------''\n\nHOW TO INSTALL :\n----------------\n\n        Copy the files in the archive to your directories,\n        they are :\n\n        BBS:Doors/TheWall/TheWall.XIM\n        BBS:Doors/TheWall/TheWall.Doc\n        BBS:Doors/TheWall/TheWall.txt\n        BBS:Doors/TheWall/TheWall.txt.gr\n        BBS:Doors/TheWall/Lines.txt\n        LIBS:AEDoor.library ( © Sintax/WOT )\n\n        Now if you use /X2.x or S-Express then append the\n        BBS:Commands/BBS.CMD to your BBS.CMD !\n\n        If you use /X3.x copy the BBS:Commands/BBSCMD/Wall.info\n        to your BBS:Commands/BBSCMD/ !\n        \n        Ok, now the door is installed and a user can call it with\n        typing WALL, but normally you want it displayed during\n        logon sequence ! Use this in a file during logon :\n\n        ~CC_WALL\n\n        This will call the door !\n\n        Now you''re ready to go...\n\nLAST WORDS :\n------------\n        \n        Now have fun with this great tool !\n\n        For Bugs (there are none), Ideas (yeah !) or just for fun\n        call my BBS :\n\n        For Bugs (there are none), Ideas (yeah !) or just for fun\n        call my BBS :\n\n                   bLACK m00N         G·O·D GERMAN HEADQUARTERS !\n                  ~~~~~~~~~~~~        L^O^G^I^C wORLDHEADQUARTERS !\nRINGDOWN 16.8 USR DST  +49-70-ELITE!  iLLUSION/gELBSUCHT hEADQUARTERS ! \n         16.8 USR DST  +49-70-ELITE!  bIZARRE fASCINATION hEADQUARTERS !\n         16.8 USR DST  +49-70-ELITE!\n\n                        ^^^ Look out for the numbers, I don''t\n                            have them at the moment !\n\n        See ya soon mates...\n                                                   Calypso !\n                                                   ~~~~~~~\n  .-----------------------------------------------------------------------.\n  |       PLEASE READ THE REGISTER!.TXT INCLUDED IN THIS ARCHIVE !!!      |\n  `-----------------------------------------------------------------------''\n\nHISTORY:\n--------\n\n        V1.0    - First Release !\n \n        V1.2    - Included an option to make an anonymous\n                  line or include the username automatically !\n\n                  Sets Linecount to zero, so now you can change\n                  the background easier !\n\n                  Now refers to DOORS:TheWall/ instead of\n                  BBS:Doors/TheWall/ !\n\n        V1.3    - Some changes to make it look same to sysop/user,\n                  not released !\n\n        V1.4    - Added different background for ansi color on/off !\n                  Is now better readable for non-ansi users !\n\n\nTHANX TO :\n----------\n\n        SEVEN /\/\ for drawing the background Ansi !\n\n        My beta-testers :\n        -----------------\n                Dalai Lama/Point Plank\n                Rotor/Gates of Asgard\n                Freddy Krueger/Boiler Room\n\n        You also can reach me on these boards !\n\nGREETINGS:\n----------\n\n      - G.E.M. - Runt&Scottie - Polaris - Skin - XAD - Deltaforce - Andy -\n      - Wedlock - Blackbird - Planet Master - Sid Vicious - Sigma Seven -\n         - Linebacker - Whiz - Raider - Mitch - Mr.T - Samir - Power -\n\n                         - All LOGIC and GOD Members -\n\n··············································································\n\n          - GLOBAL OVERDOSE GERMAN HQ - LOGIC WHQ - ILLUSION HQ -\n               _ ________           _ ______________\n         /\_______    _ /     _____   ________     /__: _____  sYSOPS:\n        /____  _ /    //_____/o  _/___  /    /____/   |/    /  """""""\n      _____:/  //     /     //   \    \/    /    //   /    /   cALYPSO\n     /     |\  /__________ /.   /_\   /________ /.    \    \   cASTOR\n __|/____________\       \/_____________\     \/______|\____\  mIKE & dAVE\n   |                                                  :        sPIKE\n                       ·b·L·A·C·K· ·m·O·O·N·       :_______|__\n 0.5      /\ __ /\             _______________     |    _ /|   cALL :\n gIG hD! // \\//  \____________\________   _ /____ |    //     """" "\n 68o3o  /.   \/    \________   _ /     /   //     \|   o/  +49-70-eLITE !\n       /    \  /    \      /   //\    /    /|      \  ./   """"""""""""\n      /      \/______\    /    /  \_______/ |    \    /  3 nODES rINGDOWN !\n     /_______|        \_______/             |_____\  /   " """"" """"""""\n             :                                Sk!n \/   aLL nODES 16.8 DST !\n                                                        """ """"" """" """\n      rUNNING (LATEST!) S-eXPRESS - sUPPORTING aMIGA aND sNES oNLY !\n         aLL {<GOD>|<LOGIC>|<ILLUSION>}-Releases fREE dOWNLOAD !!!\n          cALL nOW ! Lotsa INTERNATIONAL cALLERS ! Simply eLITE !\n','\n',char(10)),NULL,NULL,7171,1,0,NULL,NULL,NULL,'scan',1780048532);
INSERT INTO door_catalog VALUES('god_week','GOD-WEEK.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/GOD-WEEK.LHA',NULL,'XIM','______/\________ _____/\ ________________',NULL,'CALYPS0/G0D','GOD','\____/   ______//    /  \\______   \____/ \_/    \_   \/    /\   \|    |\   \_/ \     |    \    \/   /|   /\/   /',replace('  ______/\________ _____/\ ________________ \n  \____/   ______//    /  \\______   \____/ \n    \_/    \_   \/    /\   \|    |\   \_/   \n      \     |    \    \/   /|   /\/   /     \nEXPRESS\__  _____/\_______/ |___\  __/DESIGN\n<---------\/- ·p·R·E·S·E·N·T·S· -\/-------->\n        WeekTop V1.0 by CALYPS0/G0D !\n   ASM XIM Door ! Many nice features and\n  fully configurable ! Use it ! Love it !\n<------------------------------------------>\n','\n',char(10)),'Week-Top.Doc',replace('                                    .    :\n.______ ______________.   __________|    |____ __________ _____. __________.\n|:::· ·/    _____     |__/__  _    ¬\     _  ¬\______   ¬\     |_____· ·:::|\n|:·  _/    |    ¬\_   |    ¬\_ |     \_  |     \_         \_   |    ¬\_   :| \n|·   \     |      /   |      / |      /  |  ÷e÷ /   |      /   |      /_ _·|\n|.  .\\__________/__________/________/_________/__________/__________//   .|\n|             .__                        .    ·                            |  \n|  _______ ___| ¬\ ________ _________ ___|    :_______  _________________  |\n: /  _   ¬\   |   \       ¬\_____   ¬\  _     ¦  _   ¬\/     ____       ¬\ :\n_/    |    \_ |    \_  |    \_ _/   _/   |    :   |    \____    ¬\_  |    \_\n\     |     / |     /  ______/ \    \__  |    :   |     /   |     /  ______/\n:\_________/_______/____________\     /_______¦________/_________/_______ _: \n+--------------------------------\___/-------------------------------------+\n¦                                                                          ¦\n:                         E·X·P·R·E·S·S · D·E·S·I·G·N                                                     :\n\n                                    PRESENTS\n\n                      WEEK-TOP V1.0 coded by CALYPSO/GOD !\n\n    PROFESSIONAL TOOLS FOR PROFESSIONAL SYSOPS - GET THE REAL QUALITY !\n\n  .-----------------------------------------------------------------------.\n  |       PLEASE READ THE REGISTER!.TXT INCLUDED IN THIS ARCHIVE !!!      |\n  `-----------------------------------------------------------------------''\n\nWHAT''S THE USE OF THIS TOOL ?\n-----------------------------\n\n        This door displays a list of your week-top-uploaders !\n\n        At the End of the Week it sends an EALL message !\n\n        It is a XIM and NO CLI tool, this means you don''t waste\n        time in your logoff-batch for it !\n\n        It is so fucking fast that the user doesn''t see any\n        difference from a file displayed from your HD !\n        \n        Enjoy the maximum (ASM) speed and perfection...\n\n        SPECIAL FEATURE : If the user is in the charts himself he\n        will be shown in different color and boldface !\n        No other weektop can do this, cause they don''t run online,\n        hehe !\n\n\n        This is meant as a replacement for \n        Weektop by Airwolf (which still some sysops use) !\n\n        Enjoy !\n\n\n        P.S. : Sorry 68000 users, but this tool is 68020+\n               optimized... but who runs a BBS with an 68000 ?\n\n\n  .-----------------------------------------------------------------------.\n  |       PLEASE READ THE REGISTER!.TXT INCLUDED IN THIS ARCHIVE !!!      |\n  `-----------------------------------------------------------------------''\n\nFUTURE:\n-------\n\n        I will make perhaps a version supporting Conference-Accounting\n        for /X3.x users ! Depends on your reaction !\n\n\nHOW TO INSTALL :\n----------------\n\n        Copy the files in the archive to your directories,\n        they are :\n\n        BBS:Doors/Week-Top/Week-Top.Config\n        BBS:Doors/Week-Top/Week-Top.XIM\n        BBS:Doors/Week-Top/Week-Top.doc\n        BBS:Doors/Week-Top/Week-Top.Header\n        LIBS:AEDoor.library ( © Sintax/WOT )\n\n        The Week-Top.Config looks like this :\n \n        --------(cut here)--------\n        2                                  <- Displaymode !\n        Y                                  <- Y/N turns first line on/off !\n        10                                 <- Amount of Users to display !\n        BBS:User.Data                      <- The Location of your User.Data !\n        BBS:Elite/MsgBase/                 <- Position of your MsgBase\n        EALL                               <- User to sent the message to !\n        DOORS:Week-Top/Week-Top.Header     <- Headertext to be displayed !\n        --------------------------\n\n        The first line is the displaymode :\n\n        1 - Show DL Bytes in second column !\n        2 - Show UL Files and Calls in second column !\n\n        The first line (Y/N) is for a better look with the header\n        in the archive. If you use your own header or NO header,\n        then please use Y to give it a better look ! You''ll see !\n        \n\n        Now if you use /X2.x or S-Express then append the\n        BBS:Commands/BBS.CMD to your BBS.CMD !\n\n        If you use /X3.x copy the BBS:Commands/BBSCMD/Week-Top.Info\n        to your BBS:Commands/BBSCMD/ !\n        \n        Ok, now the door is installed and a user can call it with\n        typing WEEK, but normally you want it displayed during\n        logon sequence ! Use this in a file during logon :\n\n        ~CC_WEEK\n\n        This will call the door !\n\n        The advantage is that you don''t have to add another util\n        to your logoffbatch !!!\n\n        If you have a week-top tool running, then remove it\n        from your logoffbatch and replace the files where it normally\n        outputs to with the ones in the BBS:Screens dir in the archive !\n\n        Now you''re ready to enjoy !\n\n\n        Some hints for proper running :\n        -------------------------------\n\n        I suggest you start it on Monday, so you get the output\n        on the first caller the next Monday... but you can choose\n        which day you want ! To restart it delete the User.Data.TOP !\n\n\nLAST WORDS :\n------------\n        \n        Now have fun with this great tool !\n\n        For Bugs (there are none), Ideas (yeah !) or just for fun\n        call my BBS :\n\n                   bLACK m00N       G·O·D EXPRESS DESIGN WHQ !        \n                  ~~~~~~~~~~~~      L^O^G^I^C wORLDHEADQUARTERS !     \n   16.8 USR DST  +49-7054-8733      iLLUSION/gELBSUCHT hEADQUARTERS ! \n   16.8 USR DST  +49-7054-2737      bIZARRE fASCINATION hEADQUARTERS !\n\n\n        See ya soon mates...\n                                                   Calypso !\n                                                   ~~~~~~~\n  .-----------------------------------------------------------------------.\n  |       PLEASE READ THE REGISTER!.TXT INCLUDED IN THIS ARCHIVE !!!      |\n  `-----------------------------------------------------------------------''\n\nTHANX TO :\n----------\n\n        Seven /\/\ for making the ''Week-Top'' logo in this archive !\n\n        My beta-testers :\n        -----------------\n                Dalai Lama/Point Plank\n                Rotor/Gates of Asgard\n                Freddy Krueger/Boiler Room\n                MKO!/Eleventh Hour\n\n        You also can reach me on these boards !\n\n\nGREETINGS:\n----------\n\n      - G.E.M. - Runt&Scottie - Polaris - Skin - XAD - Deltaforce - Andy -\n      - Wedlock - Blackbird - Planet Master - Sid Vicious - Sigma Seven -\n         - Linebacker - Whiz - Raider - Mitch - Mr.T - Samir - Power -\n\n                         - All LOGIC and GOD Members -\n\n··············································································\n\n           - G·O·D Express Design HQ - LOGIC WHQ - ILLUSION HQ -\n               _ ________           _ ______________\n         /\_______    _ /     _____   ________     /__: _____  sYSOPS:\n        /____  _ /    //_____/o  _/___  /    /____/   |/    /  """""""\n      _____:/  //     /     //   \    \/    /    //   /    /   cALYPSO !\n     /     |\  /__________ /.   /_\   /________ /.    \    \   cASTOR\n __|/____________\       \/_____________\     \/______|\____\  mIKE & dAVE\n   |                                                  :        sPIKE\n                       ·b·L·A·C·K· ·m·O·O·N·       :_______|__\n 0.5      /\ __ /\             _______________     |    _ /|\n gIG hD! // \\//  \____________\________   _ /____ |    //   nUMBERS:\n 68o3o  /.   \/    \________   _ /     /   //     \|   o/    """"""""\n       /    \  /    \      /   //\    /    /|      \  ./  +49-7054-eLITE!\n      /      \/______\    /    /  \_______/ |    \    /  +49-7054-eLITE!\n     /_______|        \_______/             |_____\  /\n             :                                Sk!n \/  bOTH nODES 16.8 DS!\n \n      rUNNING (LATEST!) S-eXPRESS - sUPPORTING aMIGA aND sNES oNLY !\n         aLL {<GOD>|<LOGIC>|<ILLUSION>}-Releases fREE dOWNLOAD !!!\n          cALL nOW ! Lotsa INTERNATIONAL cALLERS ! Simply eLITE !\n','\n',char(10)),NULL,NULL,18484,3,0,NULL,NULL,NULL,'scan',1780048532);
