INSERT INTO door_catalog VALUES('h_v_cl20','H&V-CL20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/H&V-CL20.LHA','WarCalls','XIM','WarCalls',NULL,'WarDancer/H&V',NULL,'|   |   | V   | \|  :  /  |  : __) |  _) :   _   |._.  |\ !  |&(   |  | :\_ ! _/ |   l___!_|   : \___!  \  !  | | |   |',replace('   ___:   :_ ___ _ :  .   __:  :___ _:___.  \n  |   |   | V   | \|  :  /  |  : __) |  _)  \n  :   _   |._.  |\ !  |&(   |  | :\_ ! _/   \n  |   l___!_|   : \___!  \  !  | | |   |    \n  !   ¡   zy:   ! :       `---:'' : l___:    \n(-:   :-----------(Pr@s@nts:)-!  :------+--)\nWarCalls V2.0 for /X v3.0   By WarDancer/H&V\nUse  This   To  Find  Your   Inactive  Users\nMajor Bug  Fixed, /X And CLI  Version In One\nExecutable. Other Nice Features  Also Added.\n- sOMEWHERE iN tHIS gALAXY iS tHE sYSTEM ! -\n','\n',char(10)),'WarCalls.guide',replace('@database WarCallsDoc\n@Author Wardancer/Humane&Vanity\n@Index MAIN\n\nCopyright 1994 Wardancer/Humane&Vanity\n\n@node MAIN "WarCalls V2.0 Documentation."\n\n                   ___:   :_ ___ _ :  .   __:  :___ _:___.\n                  |   |   | V   | \|  :  /  |  : __) |  _)\n                  :   _   |._.  |\ !  |&(   |  | :\_ ! _/\n                  |   l___!_|   : \___!  \  !  | | |   |\n                  !   ¡   zy:   ! :       `---:'' : l___:\n                (-:   :-----------(Pr@s@nts:)-!  :------+--)\n                                 WarCalls V2.0\n\n                      Made by : Wardancer/Humane&Vanity\n\n                              Table of contents :\n\n                            @{"     Whats this ?     " Link 01}\n                            @{"     Installation     " Link 02}\n                            @{"        Greets        " Link 03}\n                            @{"   Bug report/ideas   " Link 04}\n                            @{"       History        " Link 05}\n\n                  ''Coz I know about the power of agression''\n@endnode\n\n@node 01 "Whats this ?"\n\n  ========================================================================\n\n  WarCalls is a program  that will allow  you to list all  users that have \n  called below a number of times you specify. Warcalls will list the users\n  handel, location, and  times  called, WarCalls  will also  offer  you to\n  redirect the output to a file.\n  Since  release 2.0, WarCalls  can also be run  from CLI. And  it is also\n  Possible to  download the T:WCLSOUT  data from ram if it has been stored\n  there.\n\n  ========================================================================\n\n@endnode\n\n@node 02 "Installation"\n\n  ========================================================================\n\n  Installing  this program is really  quite simple, the  only things you\n  have to is to make sure the following is right :\n\n  Program      Location          Description\n  -------      --------          -----------\n  WarCalls     Doors:WarCalls    The main program\n\n  Also make sure that calls.info is in the commands/bbscmd drawer.\n\n  ========================================================================\n\n@endnode\n\n@node 03 "Greets"\n\n  ========================================================================\n\n  I would like to greet the following in no order :\n\n  Kronion, Dux, The Freak, Ramirez, Omar, Striker, Playmate, Calvin,\n  Plexer, Gilthanas, Energy, Shamer, Tactica, Zany, Zeke, Spike,\n  Delirium&Kickface, Mike&Tofke, Norske, Shock, Paranoid, OB1, Curmit,\n  Tin Man, Mandrake, Mr. Orion, Mr. Beer, Marty, Nookman, Poison, Json,\n  Conan&Newton, Tarzan, Jake, HAL 9000, D-Day, Cracy Creep, Mr. Vain,\n  Overlord, Stezotehic, Tango, Json, Deature, Spacebrain, Enzo,\n  G0blin, Aquarius, Cockroach, Bugbyte, Hoffi, Triple B, Curt Cool,\n  G.O.D, Lector, Nashua, Paxdei, Tas, Caesar, Nero, Undertaker, Zinko,\n  Laxity, Devilstar, Carebear, Wolfman, Ozone&Rob\n\n      And all other Humane&Vanity members and people I forgot.\n\n  Specials go to :\n\n  Kronion .......................... For being a great leader\n  Zany ............................. For the idea for this tool\n  Dux .............................. For helping me with AmiExpress\n  Ramirez .......................... For letting me test at your board\n  Omar ............................. For all sorts of crazy conversation\n  Json ............................. Also for letting me test at your bbs\n  Aquarius ......................... For helping me with /X at TG94\n  Nero ............................. Cool board\n\n  ========================================================================\n\n@endnode\n\n@node 04 "Bug report/ideas"\n\n  ========================================================================\n\n  Send your bug reports or ideas to the following boards :\n\n  Dark Domain ............ +1  305-989-0718 (Humane&Vanity WHQ)\n  Susperia ............... +45 434-342-36   (Humane&Vanity SCHQ)\n  Somewhere Online ....... +45 597-538-01   (Humane&Vanity DKHQ)\n  Suffocation ............ +45 491-807-60   (The board where I test my doors)\n  Mainline ............... +45 981-530-62   (Also supports netmail)\n  Static Chaos ........... +45 864-395-14   (Another testsite)\n\n  Or leave me a msg at /X-Net ''Wardancer@DK0001''\n\n  ======================================================================== \n\n@endnode\n\n@node 05 "History"\n\n  ========================================================================\n\n  V2.0 - MAJOR update.\n         Can now also be run from CLI.\n         Removed unnessecary code.\n         Fixed file freeing bug.\n         Now possible to download T:WCLSOUT.\n\n  V1.1 - Made WarCalls show users location.\n         Made it possible to redirect output.\n\n  V1.0 - Not released to anybody else than Susperia and Suffocation.\n\n  ========================================================================\n\n@endnode\n','\n',char(10)),NULL,'auto-added',16719,4,0,NULL,NULL,'h_v_cl20','scan',1780048532);
INSERT INTO door_catalog VALUES('h_v_cs10','H&V-CS10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/H&V-CS10.LHA',NULL,'XIM','___:   :_ ___ _ :  .   __:  :___ _:___.',NULL,NULL,NULL,'|   |   | V   | \|  :  /  |  : __) |  _) :   _   |._.  |\ !  |&(   |  | :\_ ! _/ |   l___!_|   : \___!  \  !  | | |   |',replace('   ___:   :_ ___ _ :  .   __:  :___ _:___.\n  |   |   | V   | \|  :  /  |  : __) |  _)\n  :   _   |._.  |\ !  |&(   |  | :\_ ! _/\n  |   l___!_|   : \___!  \  !  | | |   |\n  !   ¡   zy:   ! :       `---:'' : l___:\n(-:   :-----------(Pr@s@nts:)-!  :------+--)\n   CRAZY STATS V1.0 BY: PARANOID/HMN^VTY!\n','\n',char(10)),'crazystats.doc',replace('<><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><>\n<>    C R A Z Y   S T A T S   /X   D O O R   B Y   P A R A N O I D !    <>\n<><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><>\n<><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><>\n<>     									<>\n<> 1) FUNCTiON!								<>\n<> 									<>\n<> Basically this door is a replacement door to the normal S stats door <>\n<> of Ami-X.. The reason for doing this door was because most of the S  <>\n<> doors are ugly, or dont give so much information.. This version, 1.0 <>\n<> is not perfect, the code is simple, but I did not spend so much time <>\n<> working on it.... Just install it and you''ll see what it''s like! :)  <>\n<> This is my second door.. I''ve been coding AREXX for two days now!    <>\n<> 									<>\n<> 2) NUMBER OF BACKDOORS?						<>\n<> 									<>\n<> As always there are ABSOLUTELY no lame BACKDOORS in this program.... <>\n<> you can check the AREXX code out yourself if you want! All my doors  <>\n<> are always 100% guaranteed to be backdoor-free.. I am a trader&sysop <>\n<> so I have better things to do in the scene than destroy and ''hack''   <>\n<> other guys work...							<>\n<>									<>\n<> 3) GREETiNGS!							<>\n<> 									<>\n<>   GAZZER/PRODiGY - GILTHANAS/2000AD - VENGER - CAFFEINE - JAY/AFL    <>\n<>     O.B.1./FAIRLIGHT - GREEN-BERET/AFL - KRONION/H&V - ZANY/H&V      <>\n<>      BREN/AFL - TEX/FAIRLIGHT - SPLATT/FAIRLIGHT - HOGSTER/FLT       <>\n<>         BUGBYTE/CRYSTAL - EMPIRE/MYSTIC - BYTEANDI/MYSTIC!           <>\n<>          HELLHOUND/H&V - DELIRIUM+KICKFACE/H&V - FOXX/ZZC            <>\n<>           MR.BEER/H&V - NORSKE/H&V - WARDANCER/H&V - TGM             <>\n<>            FLUX/SCANDAL - ZOLDAN/SCANDAL - MERCURY/SCL               <>\n<>            6PACK^LECTER/SABOTAGE - AND ALL THE REST!                 <>\n<>	    FRiENDSHiP + OZZY OSBOURNE + SEPULTURA RULEZ!               <>\n<>									<>\n<> 4) iNSTALLATiON:							<>\n<>									<>\n<> Like all my tools simply copy the rexx file into DOORS:PARANOID/     <>\n<> if you dont have a PARANOID dir in DOORS: then make one.. Then       <>\n<> simply copy the files into the directories shown in the archive to   <>\n<> your hard drive directories of the same name.. Bah! Simple! :)       <>\n<>                                                                      <>\n<>               CALL THESE BOARDS TO CONTACT ME!                       <>\n<>                     ** ALL H&V BOARDS! **                            <>\n<>             ANGST - 410-653-2845 NUP=NOLAMERSHERE                    <>\n<>        FORBIDDEN PLANET - +353-1-8208489 (RD) NUP=HEAVEN             <>\n<>                 WARES UNLiMiTED - +45-4494-6208                      <>\n<>                                                                      <>\n<>   C Y A   L A T E R   M A T E S !   -   P A R A N O I D / H & V      <>\n<><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><>\n<>  CALL MY BOARD - CRAZY TRAIN - FiND THE NUMBER AND NUP iF YOU CaN!   <>\n<><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><><>\n >   >  > > >> > P A R A N O I D / H U M A N E & V A N I T Y < << <  <   <\n\n         _____                                            ____\n _______|    "|________________   ______________________ |   "|_____________\n \_     |    :|"    |    "|"   \_/   "|"    _    "|"    \|   :|"    _______/\n  |     "     |.    |     |     "     |:    |     |.     "    |.    ___|__\n  |     _     |_         :|_   \_/   :|_    _    .|_   _     .|_         "|\n  |:    |______/___________/____|______/____|______/   |\______/____     :|\n  |_____|                                         |____|            |_____|\n             _____                A-N-D                        _____\n            /    /\  ___________________  ____________________/    /\\n  O-------=/    /¯¯¯¯/         /        \/____/         /    //   / /=-----O\n  !::::::://   /    //   /    //   /    /    /____//   //   /   // /:::::::!\n  ::::::::\   /   //         /    /    //   /\___//   /__     __/ /:::::::::\n  ¡::::::::\     //    /   //    /   //   // /::/   //\_/   //\_\/:::::::::¡\n  O--------=\____/____/____/    /____/____/ /--/____/ //____/ /=-----------O\n             \___\____\___/____/\____\____\/   \____\/ \____\/\n                          \____\/ thE CxxLeSt CO-OPeRaTixN SiNcE\n                                      ROcK aNd RoLL!\n\n Name                Ndz  Number               Baud   Sysop         Country\n[-------------------=---=----------------------=------=------------=---------]\n PRIORITY ONE         4   +1 90 9793 0921 WHQ   16.8D  NORSKE       U.S.A.\n DARK DOMAIN          4   +1 30 5989 0718 USHQ  16.8D  TIN MAN      U.S.A.\n SUICIDAL TENDENCY    2   +32   5042 7306 EHQ   16.8D  DEL & KICK   Belgium\n MANIAC MANSION       1   +32   3707 0753 BHQ   16.8D  CRAZY CREEP  Belgium\n SUSPERIA #1          1   +45   4343 4236 SCHQ  14.4   ZANY         Denmark\n SUSPERIA #2          1   +45   4343 4238 SCHQ  14.4D  ZANY         Denmark\n SOMEWHERE ONLINE #1  1   +45   5965 3801 DKHQ  16.8   HELLHOUND    Denmark\n SOMEWHERE ONLINE #2  1   +45   5965 4155 DKHQ  16.8D  HELLHOUND    Denmark\n THRONE CHAMBER #1    1   +358  0873 6109 FINHQ 16.8D  NECRARCH     Finland\n THRONE CHAMBER #2    1   +358  0PRI VATE FINHQ 14.4   NECRARCH     Finland\n COSMO AD 2000 #1     1   +358  1123 7203 FINHQ 21.6D  G.O.D.       Finland\n COSMO AD 2000 #2     1   +358  1123 7366 FINHQ 14.4   G.O.D.       Finland\n[-------------------=---=----------------------=------=------------=---------]\n','\n',char(10)),NULL,NULL,5138,2,0,NULL,NULL,NULL,'scan',1780048532);
INSERT INTO door_catalog VALUES('h_v_e001','H&V-E001.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/H&V-E001.LHA','ESend','XIM','ESend',NULL,'Dux/Vanity',NULL,'___/   __/___  ___/  ___/___ O\____   /    \-\____   /    \-------------O /    _/    //  /     /    //   iN 1994',replace('     ______         ______                  \n ___/   __/___  ___/  ___/___               \nO\____   /    \-\____   /    \-------------O\n  /    _/    //  /     /    //   iN 1994    \n //   __¯   //   \\   /    //               \n/°    /    °/ aND \° /    °/ HUMANE & VANITY\n\____//    / _     \___   / _ /X - Division \nO-zy/_____/-//-------\___/-//--(Pr@s@nts:)-O\n    ErrorLog v0.01 for /X by Dux/Vanity     \nThis will keep you up to date with all the  \n  errors that could occur at your board     \n','\n',char(10)),'ESend.doc',replace('.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo..oOo.oOo.\n\n                              Error Sender v0.01\n\n                                by Dux/Vanity\n\n.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo..oOo.oOo.\n\n\nIntroduction\n~~~~~~~~~~~~\nDon''t you just hate when you one day, when you''re browsing through your HD you\nfind an ErrorLog in one of your node-dirs? This small util will solve these\nproblems for you by sending you a msg whenever an error occurs on your BBS.\n\n\nUsage\n~~~~~\nThe syntax is like this:\n\nESend <NodeNr> <Conferencepath>\n\nWhere <NodeNr> should be replaced with the number of the node you want to\ncheck, and <Conferencepath> should be replaced with the full path to the\nconference where you want to receive the message. The path should be WITHOUT\nany trailing :''s or /''s!\n\nYou can run the util in your logoffscript or using a cron-program.\n\nThat''s just about it...\n\n\nHow to contact\n~~~~~~~~~~~~~~\nI can be reached at Mainline: +45-9815 3062/+45-9815 3562 or on most major\nDanish boards. Or by /Xnet on: Dux@DK0001.\n\n\nGreets\n~~~~~~\nDevilstar\nLector\nRelief\nSilver Fox\nWardancer\nRamirez\nEmpire\nTarzan\nScratch\nShark\nFrostie\n','\n',char(10)),NULL,'auto-added',15231,7,0,NULL,NULL,'h_v_e001','scan',1780048532);
INSERT INTO door_catalog VALUES('h_v_ql10','H&V-QL10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/H&V-QL10.LHA','QuickLogon','XIM','Cp_nähä_Du!!',NULL,'Dux/Humane&Vanity',NULL,'___/   __/___  ___/  ___/___ O\____   /    \-\____   /    \-------------O /    _/    //  /     /    //   iN 1994',replace('     ______         ______                  \n ___/   __/___  ___/  ___/___               \nO\____   /    \-\____   /    \-------------O\n  /    _/    //  /     /    //   iN 1994    \n //   __¯   //   \\   /    //               \n/°    /    °/ aND \° /    °/ HUMANE & VANITY\n\____//    / _     \___   / _ /X - Division \nO-zy/_____/-//-------\___/-//--(Pr@s@nts:)-O\nQuickLogon V1.0 For /X  By Dux/Humane&Vanity\n','\n',char(10)),'QuickLogon.doc',replace('ooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooo\n\n                              Quick Logon v1.00\n\n                              Code by Dux/Vanity\n\nooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooo\n\n\nIntroduction\n~~~~~~~~~~~~\nHave you ever wanted to have a couple of bulletins shown at logon but still\nwanted to keep the time it took to get on your board to a minimum? Then "Quick\nLogon" is the thing you need!\n\n\nInstallation\n~~~~~~~~~~~~\nCopy the supplied QLOGON.info to your BBS:Commands/SYSCMD/ dir.\n\nCopy the QuickLogon and QuickLogon.info to wherever you want them. Eg.\nDOORS:QuickLogon.\n\nNow you need to create you bulletins. You could call your old logon-bull for\nBBS:Screens/NoQuickLogon.txt and make a short version of it called\nBBS:Screens/QuickLogon.txt.\n\nYou can ofcourse also add accesslevel to the files. Eg. NoQuickLogon40.txt.\nMCI codes are also accepted in the bullfiles.\n\nNow you can edit your BBS:Bull.txt to something like this:\n\n--CUT--\n~\n~CC_QLOGON\n--CUT--\n\nNow you need to edit the QuickLogon.info to your own needs!\n\n\nHow to contact\n~~~~~~~~~~~~~~\nI can be reached at my own board Mainline +45-9815 3062/+45-9815 3562 or on\nmost Danish elite boards. Or by /Xnet to ''Dux@DK0001''.\n\nI would appreciate to know who''s using my doors/utils.\n\n\nGreets\n~~~~~~\nDevilstar\nLector\nTarzan\nRamirez\nWardancer\nFrostie\nScratch\nEmpire\nYobbo\n','\n',char(10)),NULL,'auto-added',45461,6,0,NULL,NULL,'h_v_ql10','scan',1780048532);
INSERT INTO door_catalog VALUES('h_v_rw04','H&V-RW04.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/H&V-RW04.LHA',NULL,'XIM','RealtimeWho.000',NULL,NULL,NULL,'|   |   | V   | \|  :  /  |  : __) |  _) :   _   |._.  |\ !  |&(   |  | :\_ ! _/ |   l___!_|   : \___!  \  !  | | |   |',replace('   ___:   :_ ___ _ :  .   __:  :___ _:___.\n  |   |   | V   | \|  :  /  |  : __) |  _)\n  :   _   |._.  |\ !  |&(   |  | :\_ ! _/\n  |   l___!_|   : \___!  \  !  | | |   |\n  !   ¡   zy:   ! :       `---:'' : l___:\n(-:   :-----------(Pr@s@nts:)-!  :------+--)\nRealtime Who v0.4 for AmiExpress v2.x & 3.x!\n','\n',char(10)),'RealtimeWho.doc',replace('\n\n                               RealtimeWho v0.4\n\n                              Code by Dux/Vanity\n\n\n                     Contact me at Mainline +45 981 53062\n                               Amixnet: @DK0001\n\n\n\nINTRODUCTION\n~~~~~~~~~~~~\n\nRealtimeWho (RW) is a who-door for AmiExpress v3.x if you haven''t already\nguessed it. The only difference between RW and an ordinary who-door, is that\nRW will keep updating until you quit it. To quit RW you just press any key.\nThis door was done as a request from Hellhound/Somewhere Online.\n\n\nINSTALLATION\n~~~~~~~~~~~~\n\nInstall it as an XIM where you like. Don''t need to be in a specific directory.\nThe only requirement is that the configfile is in the same directory. You may\nrename the programfile, as long as you remember to rename the configfile too.\n\nThe configfile is used to store the phone-numbers for the different nodes. The\nmax. size of a ph. number is 15 chars! You can write what you want, chars,\nnumbers, whatever.\n\n\nHELLOS\n~~~~~~\n\nAll the other members of Vanity - Tarzan - Frostie - Ramirez - Fun Fun -\nScratch - Lector - Yobbo - Empire - Stef - Weird Dream - Devilstar.\n\nIf I''ve forgotten any please let me know :)\n','\n',char(10)),NULL,'auto-added',40720,2,0,NULL,NULL,'h_v_rw04','scan',1780048532);
INSERT INTO door_catalog VALUES('h_v_sa10','H&V-SA10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/H&V-SA10.LHA',NULL,'XIM','___:   :_ ___ _ :  .   __:  :___ _:___.',NULL,NULL,NULL,'|   |   | V   | \|  :  /  |  : __) |  _) :   _   |._.  |\ !  |&(   |  | :\_ ! _/ |   l___!_|   : \___!  \  !  | | |   |',replace('   ___:   :_ ___ _ :  .   __:  :___ _:___.\n  |   |   | V   | \|  :  /  |  : __) |  _)\n  :   _   |._.  |\ !  |&(   |  | :\_ ! _/\n  |   l___!_|   : \___!  \  !  | | |   |\n  !   ¡   zy:   ! :       `---:'' : l___:\n(-:   :-----------(Pr@s@nts:)-!  :------+--)\n   SYSOP AVAIL V1.0 BY: PARANOID/HMN^VTY!\n','\n',char(10)),'AVAIL.DOC',replace('\n+---------------------------------------------------------------------------+\n|                  CRAZY SYSOP AVAiLABLE DOOR V1.0!                         |\n|                                BY:                                        |\n|                      PARANOID/HUMANE^VANITY!                              |\n+---------------------------------------------------------------------------+\n\n1) WHAT''S iT DO!???\n\n Well, Sysop Available Door will check for a sysops chat flag. If the chat\n flag is ON then the user will be shown a little text file, saying that\n you''re around for chatting.... If not, well obviously the door will show\n a text file saying that you''re NOT around!! heheh.. \n\n2) CREDiTS!\n\n             Arexx coding by: PARANOID/HUMANE^VANiTY!\n               Cool Ansis by: ZOLDAN/SCANDAL^ESQUiRE!\n\n3) iNSTALLATiON!\n\n Installation is so damn easy that even you PC owning sysops could do it!!\n hehe.. OKi, simply copy the Dir DOORS/PARANOID/ to your BBS:Doors dir, and\n also copy the avail.info to your BBS:Commands/bbscmd/ Dir.. Boing! Easy!!!\n\n4) SOME USELESS iNFO!\n\n Although SYSOP AVAILABLE comes complete with two text files (AVAIL.TXT and\n UNAVAIL.TXT) which can be used to tell a user if you can be reached or not,\n you can change the text files if you want, diplaying a logo of your name or\n some other stuff.. Or, if you wanna attach the SYSOP AVAILABLE DOOR to a\n bull on your board (eg.LOGON.TXT) you must of course put ~ at the beginning\n of the txt file and then ~CC_AVAIL at the bottom of the text file! If you\n want to do this then you probably do not want a BIG text file saying:\n\n           "Y O   T H E   S Y S O P   I S   A V A I L A B L E !" \n\n To be displayed EVERY time some user logs onto your board! Bcoz it would\n not look so great I think.. :) OKi, so you CAN write a little one line\n text file saying "XXXX iS AVAILABLE FOR CHAT", but you dont have to do\n this!!! Yes, simply delete or rename the two text files (AVAIL.TXT and\n UNAVAIL.TXT) and SYSOP AVAILABLE will automatically place it''s own small\n one line message for you.. Making it cool for bulletins.. \n\n This is my first door, and I hope you like it! The code is not advanced\n but it does the job as well as any other util of this kind (I''ve only\n seen ONE of these utils ever, and that didn''t work on my A1200! :( )\n I will be releasing some more /X doors in the near future, so look out\n for them! There were a lot of little bugs with this, I hope that I have\n gotten rid of most of them (thanks to Venger for the help!) but only time\n will tell!! One thing I can ABSOLUTELY GUARANTEE to you is that this\n has no backdoors! Backdoors are fucking lame, and anyway, I cannot code\n well enuff to even think of putting in any backdoors!! hehe :)\n\n That''s all.. I''ve tested this version on /X 3.35, and it works fine,and\n I''ve tested it on multinode systems.. So it should work.. It''s also A1200\n compatible!! Which is sadly not so for many of these new doors! There''s\n no excuse for not making your door compatible for the new and superior\n AGA machines! So dont be stuck in the past dudes!!!\n\n NOW.. GREETINGS TO ALL MY FRIENDS!!!\n\n GAZZER/PRODIGY  -  Hey m8! How''s the satellite!??\n GILTHANAS/2kAD  -  Hope you enjoyed your skiing trip my friend!\n CAFFEINE        -  SEGA SUCKS! ANGST RULLLEEEZ! :)\n VANGER/iNDY!    -  Thanks for your help with AREXX m8!\n O.B.1./FLT      -  Ireland''s number one trader! :)\n ZOLDAN/SCANDAL  -  You''re ascii''s & ansi''s are the coolest!\n GREEN-BERET/AFL -  Beta tester and cool dude/sysop!\n KRONION/H&V     -  Ahh.. hope you like this door pal! :)\n ZANY/HMN^VTY    -  Your board is cool m8ey!! And so is PACMAG!\n WARDANCER/H&V   -  Hey m8! I liked your logoff door!\n THE FREAK/H&V   -  Cool trading mate!! \n HELLHOUND/H&V   -  Back from Norway?!??\n DARKSIDE        -  The Amazon Sysop! :) REFUSE/RESIST!!\n REVENGER/2kAD   -  How''s ''t goin'' sport!?? :) \n TEX/FLT         -  OFFSHORE is doing well these days m8!\n SPLATT/FLT      -  Where the hell is Splatterhouse now!??!? :)\n\n QUiCK GREETS TO: 6PACK^LECTER,MERCURY,STRIKER,DELiRiUM&KiCKFACE,\n                  HOGSTER,KILLERETTE,NORSKE,CHAPLIN&STONY,TARZAN,\n                  FLUX,GIANTS,STIFF,FOXX,JAY, AND ALL i FORGOT!\n\n OKi.. thats it, gotta make it short.. sorry if I forgot ya! Also, quick\n respect to the following cool /X coders: BYTEANDI/BUGBYTE/EMPIRE/BIG-\n BOSS/JORDAN/FANTA&SONY and all the rest!\n\n >MEGAGREETS TO ALL H&V MEMBERS WORLDWiDE FOR MAKiNG THiS THE FRiENDLiEST<\n >AND COOLEST CREW AROUND!<\n\n Catch me at any of these boards!\n\n FORBIDDEN PLANET  - +353-1-8208489  [RINGDOWN!] [NUP=SABBATH]\n WARES UNLIMITED   - +45-4494-6208\n ANGST             - 410-653-2845    [NUP=NOLAMERSHERE]\n SUSPERIA          - +45-4343-4236   [RINGDOWN!]\n PRIORITY ONE      - 909-793-0921    [RINGDOWN!]\n OFFSHORE          - +44-534-856292  [NUP=TETRIS]\n SOMEWHERE ONLiNE  - +45-5965-4155 or 3801\n\n And on all the other cool boards I''m on! Thats all from me.. catch you\n dudes later.. and remember that FRIENDSHIP RULEZ US ALL!\n\n >    >  > > >> > P A R A N O I D / H U M A N E & V A N I T Y < << <  <   <\n\n         _____                                            ____\n _______|    "|________________   ______________________ |   "|_____________\n \_     |    :|"    |    "|"   \_/   "|"    _    "|"    \|   :|"    _______/\n  |     "     |.    |     |     "     |:    |     |.     "    |.    ___|__\n  |     _     |_         :|_   \_/   :|_    _    .|_   _     .|_         "|\n  |:    |______/___________/____|______/____|______/   |\______/____     :|\n  |_____|                                         |____|            |_____|\n             _____                A-N-D                        _____\n            /    /\  ___________________  ____________________/    /\\n  O-------=/    /¯¯¯¯/         /        \/____/         /    //   / /=-----O\n  !::::::://   /    //   /    //   /    /    /____//   //   /   // /:::::::!\n  ::::::::\   /   //         /    /    //   /\___//   /__     __/ /:::::::::\n  ¡::::::::\     //    /   //    /   //   // /::/   //\_/   //\_\/:::::::::¡\n  O--------=\____/____/____/    /____/____/ /--/____/ //____/ /=-----------O\n             \___\____\___/____/\____\____\/   \____\/ \____\/\n                          \____\/\n\n Name                Ndz  Number               Baud   Sysop         Country\n[-------------------=---=----------------------=------=------------=---------]\n PRIORITY ONE         4   +1 90 9793 0921 WHQ   16.8D  NORSKE       U.S.A.\n DARK DOMAIN          4   +1 30 5989 0718 USHQ  16.8D  TIN MAN      U.S.A.\n SUICIDAL TENDENCY    2   +32   5042 7306 EHQ   16.8D  DEL & KICK   Belgium\n MANIAC MANSION       1   +32   3707 0753 BHQ   16.8D  CRAZY CREEP  Belgium\n SUSPERIA #1          1   +45   4343 4236 SCHQ  14.4   ZANY         Denmark\n SUSPERIA #2          1   +45   4343 4238 SCHQ  14.4D  ZANY         Denmark\n SOMEWHERE ONLINE #1  1   +45   5965 3801 DKHQ  16.8   HELLHOUND    Denmark\n SOMEWHERE ONLINE #2  1   +45   5965 4155 DKHQ  16.8D  HELLHOUND    Denmark\n THRONE CHAMBER #1    1   +358  0873 6109 FINHQ 16.8D  NECRARCH     Finland\n THRONE CHAMBER #2    1   +358  0PRI VATE FINHQ 14.4   NECRARCH     Finland\n COSMO AD 2000 #1     1   +358  1123 7203 FINHQ 21.6D  G.O.D.       Finland\n COSMO AD 2000 #2     1   +358  1123 7366 FINHQ 14.4   G.O.D.       Finland\n[-------------------=---=----------------------=------=------------=---------]\n','\n',char(10)),NULL,NULL,6163,2,0,NULL,NULL,NULL,'scan',1780048532);
INSERT INTO door_catalog VALUES('h_v_wc11','H-V-WC11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/H-V-WC11.LHA',NULL,'XIM','WarCalls',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'auto-added',34794,0,0,NULL,NULL,'h_v_wc11','scan',1780048532);
INSERT INTO door_catalog VALUES('h_v_wcl1','H&V-WCL1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/H&V-WCL1.LHA','WarCalls','XIM','WarCalls',NULL,'WarDancer/H&V',NULL,'.--/  | \/  | \___ \/ ___/   \/  \ \   ____/ ¦ /   _  \  |  \  \  / \/  |_ \   \ \  ___/ _/    |   \_`   \_ \/   \_ _/  \_\   \_   \_',replace('    __|\  __|\_____  /\___/\_  /\/\_________\n.--/  | \/  | \___ \/ ___/   \/  \ \   ____/\n¦ /   _  \  |  \  \  / \/  |_ \   \ \  ___/\n_/    |   \_`   \_ \/   \_ _/  \_\   \_   \_\n\_____|____/_____/__\____/_|____/_\___/____/\n¦\    |    /   \/  \ \__\///____  /   \   /\n¦ \   |   /  |_ \   \ \ \/ \mrv/  \___ \ /¦\n¦  \  ·  /   _/  \_\   \_   \_/    \_ \  \_\n¦aND\___/____|____/_\___/____/______/_____/\n`--------  - -÷p÷r÷e÷s÷e÷n÷t÷s÷- -  ------''\nWarCalls V1.1 for /X V3.xx  by WarDancer/H&V','\n',char(10)),'WarCalls.guide',replace('@database WarCallsDoc\n@Author Wardancer/Humane&Vanity\n@Index MAIN\n\nCopyright 1994 Wardancer/Humane&Vanity\n\n@node MAIN "WarCalls V1.1 Documentation."\n\n                   ___:   :_ ___ _ :  .   __:  :___ _:___.\n                  |   |   | V   | \|  :  /  |  : __) |  _)\n                  :   _   |._.  |\ !  |&(   |  | :\_ ! _/\n                  |   l___!_|   : \___!  \  !  | | |   |\n                  !   ¡   zy:   ! :       `---:'' : l___:\n                (-:   :-----------(Pr@s@nts:)-!  :------+--)\n                                 WarCalls V1.1\n\n                      Made by : Wardancer/Humane&Vanity\n\n\n\n                              Table of contents :\n\n                           @{"     Whats this ?     " Link 01}\n                           @{"     Installation     " Link 02}\n                           @{"        Greets        " Link 03}\n                           @{"   Bug report/ideas   " Link 04}\n                           @{"       History        " Link 05}\n\n@endnode\n\n@node 01 "Whats this ?"\n\n  ========================================================================\n\n  WarCalls is a program  that will allow  you to list all  users that have \n  called below a number of times you specify. Warcalls will list the users\n  handel, location, and  times  called, WarCalls  will also  offer  you to\n  redirect the output to a file.\n\n  ========================================================================\n\n@endnode\n\n@node 02 "Installation"\n\n  ========================================================================\n\n  Installing  this program is really  quite simple, the  only things you\n  have to is to make sure the following is right :\n\n  Program      Location          Description\n  -------      --------          -----------\n  WarCalls     Doors:WarCalls    The main program\n\n  Also make sure that calls.info is in the commands/bbscmd drawer.\n\n  ========================================================================\n\n@endnode\n\n@node 03 "Greets"\n\n  ========================================================================\n\n  I would like to greet the following in no order :\n\n  Kronion, Dux, The Freak, Ramirez, Omar, Striker, Playmate, Calvin,\n  Plexer, Gilthanas, Energy, Shamer, Tactica, Zany, Zeke, Spike,\n  Delirium&Kickface, Mike&Tofke, Norske, Chock, Paranoid, OB1, Curmit,\n  Tin Man, Mandrake, Mr. Orion, Mr. Beer, Marty, Nookman, Poison, Json,\n  Conan&Newton, Tarzan, Jake, HAL 9000, D-Day, Cracy Creep, Mr. Vain,\n  Overlord, Stezotehic\n\n      And all other Humane&Vanity members and people I forgot.\n\n  Specials go to :\n\n  Kronion .......................... For being a great leader\n  Dux .............................. Thanks for helping me with AmiExpress\n  Ramirez .......................... For letting me test at your board\n  Omar ............................. For all sorts of crazy conversation\n\n  ========================================================================\n\n@endnode\n\n@node 04 "Bug report/ideas"\n\n  ========================================================================\n\n  Send your bug reports or ideas to the following boards :\n\n  Susperia ............... +45 434-34236 (Humane&Vanity SCHQ)\n  Somewhere Online ....... +45 597-53801 (Humane&Vanity DKHQ)\n  Suffocation ............ +45 491-80760 (The board where I test my doors)\n  Mainline ............... +45 981-53062 (Also supports netmail)\n\n  ======================================================================== \n\n@endnode\n\n@node 05 "History"\n\n  ========================================================================\n\n  V1.1 - Made WarCalls show users location.\n         Made it possible to redirect output.\n\n  V1.0 - Not released to anybody else than Susperia and Suffocation.\n\n  ========================================================================\n','\n',char(10)),NULL,'auto-added',10837,2,0,NULL,NULL,'h_v_wcl1','scan',1780048532);
INSERT INTO door_catalog VALUES('h_v_wlo2','H&V-WLO2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/H&V-WLO2.LHA','WarLogoff','XIM','WarLogoff',NULL,'Wardancer/V&H',NULL,'|   |   | V   | \|  :  /  |  : __) |  _) :   _   |._.  |\ !  |&(   |  | :\_ ! _/ |   l___!_|   : \___!  \  !  | | |   |',replace('   ___:   :_ ___ _ :  .   __:  :___ _:___.\n  |   |   | V   | \|  :  /  |  : __) |  _)\n  :   _   |._.  |\ !  |&(   |  | :\_ ! _/\n  |   l___!_|   : \___!  \  !  | | |   |\n  !   ¡   zy:   ! :       `---:'' : l___:\n(-:   :-----------(Pr@s@nts:)-!  :------+--)\nWarLogoff V1.2 for /X v3.xx by Wardancer/V&H','\n',char(10)),'WarLogoff.guide',replace('@database WarLogoffDoc\n@Author Wardancer/Vanity&Humane\n@Index MAIN\n\nCopyright 1993 Wardancer/Vanity&Humane\n\n@node MAIN "WarLogoff V1.1 Documentation."\n\n                   ___:   :_ ___ _ :  .   __:  :___ _:___.\n                  |   |   | V   | \|  :  /  |  : __) |  _)\n                  :   _   |._.  |\ !  |&(   |  | :\_ ! _/\n                  |   l___!_|   : \___!  \  !  | | |   |\n                  !   ¡   zy:   ! :       `---:'' : l___:\n                (-:   :-----------(Pr@s@nts:)-!  :------+--)\n                                WarLogoff V1.1\n\n                      Made by : Wardancer/Vanity&Humane\n\n\n\n                              Table of contents :\n\n                           @{"     Whats this ?     " Link 01}\n                           @{"     Installation     " Link 02}\n                           @{"        Greets        " Link 03}\n                           @{"   Bug report/ideas   " Link 04}\n\n@endnode\n\n@node 01 "Whats this ?"\n\n  ========================================================================\n\n  WarLogoff is  another clone of the classic  logoff banner program, where\n  users can enter some  text for other users to see  when they logoff. The\n  programs  is  really  quite  simple, altough  nice to use. The  user can\n  enter  up to 10 lines of  text, and the  program  wont allow  an user to\n  save an empty text, furthermore, the  progarm allows users with suffient\n  access to  stay  anonumous. As  of V1.2,  it is  now possibel  to forbid\n  certain users to enter  anything into the door, the names of these users\n  are stored in a seperate file.\n\n  ========================================================================\n\n@endnode\n\n@node 02 "Installation"\n\n  ========================================================================\n\n  Installing  this program is really  quite simple, the  only things you\n  have to is to make sure the following is right :\n\n  Program      Location          Description\n  -------      --------          -----------\n  WarLogoff    Doors:WarLogoff   The main program\n  Banner.txt   Doors:WarLogoff   The banner to be displayed, will\n                                 be generated when the program\n                                 is run.\n  Blacklist    Doors:WarLogoff   The file containing the names of\n                                 the users that are not allowed\n                                 to enter anything to the door\n\n  Also make sure that g.info is in the commands/bbscmd drawer.\n\n  ========================================================================\n\n@endnode\n\n@node 03 "Greets"\n\n  ========================================================================\n\n  I would like to greet the following in no order :\n\n  Kronion, Dux, The Freak, Ramirez, Omar, Striker, Playmate, Calvin,\n  Plexer, Gilthanas, Energy, Shamer, Tactica, Zany, Zeke, Spike,\n  Delirium&Kickface, Mike&Tofke, Norske, Chock, Paranoid, OB1, Curmit,\n  Tin Man, Mandrake, Mr. Orion, Mr. Beer, Marty, Nookman, Poison\n  \n\n      And all other Vanity&Humane members and people I forgot.\n\n  Specials go to :\n\n  Kronion .......................... For being a great leader\n  Dux .............................. Thanks for helping me with AmiExpress\n  Ramirez .......................... For letting me test at your board\n  Omar ............................. For all sorts of crazy conversation\n\n  ========================================================================\n\n@endnode\n\n@node 04 "Bug report/ideas"\n\n  ========================================================================\n\n  Send your bug reports or ideas to the following boards :\n\n  Susperia ............... +45 434-34236\n  Somewhere Online ....... +45 597-53801\n  Suffocation ............ +45 491-80760 (The board where I test my doors)\n  Mainline ............... +45 981-53062 (Also supports netmail)\n\n  ======================================================================== \n\n@endnode\n','\n',char(10)),NULL,'auto-added',9785,1,0,NULL,NULL,'h_v_wlo2','scan',1780048532);
INSERT INTO door_catalog VALUES('h_v_wlog','H_V_WLOG.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/H_V_WLOG.LHA','WarLogoff','XIM','WarLogoff',NULL,'WarDancer/V&H',NULL,'|   |   | V   | \|  :  /  |  : __) |  _) :   _   |._.  |\ !  |&(   |  | :\_ ! _/ |   l___!_|   : \___!  \  !  | | |   |',replace('   ___:   :_ ___ _ :  .   __:  :___ _:___.  \n  |   |   | V   | \|  :  /  |  : __) |  _)  \n  :   _   |._.  |\ !  |&(   |  | :\_ ! _/   \n  |   l___!_|   : \___!  \  !  | | |   |    \n  !   ¡   zy:   ! :       `---:'' : l___:    \n(-:   :-----------(Pr@s@nts:)-!  :------+--)\nWarLogoff V1.1 for /X V3.xx by WarDancer/V&H\n','\n',char(10)),'WarLogoff.guide',replace('@database WarLogoffDoc\n@Author Wardancer/Vanity&Humane\n@Index MAIN\n\nCopyright 1993 Wardancer/Vanity&Humane\n\n@node MAIN "WarLogoff V1.1 Documentation."\n\n                   ___:   :_ ___ _ :  .   __:  :___ _:___.\n                  |   |   | V   | \|  :  /  |  : __) |  _)\n                  :   _   |._.  |\ !  |&(   |  | :\_ ! _/\n                  |   l___!_|   : \___!  \  !  | | |   |\n                  !   ¡   zy:   ! :       `---:'' : l___:\n                (-:   :-----------(Pr@s@nts:)-!  :------+--)\n                                WarLogoff V1.1\n\n                      Made by : Wardancer/Vanity&Humane\n\n\n\n                              Table of contents :\n\n                           @{"     Whats this ?     " Link 01}\n                           @{"     Installation     " Link 02}\n                           @{"        Greets        " Link 03}\n                           @{"   Bug report/ideas   " Link 04}\n\n@endnode\n\n@node 01 "Whats this ?"\n\n  ========================================================================\n\n  WarLogoff is  another clone of the classic  logoff banner program, where\n  users can enter some  text for other users to see  when they logoff. The\n  programs  is  really  quite  simple, altough  nice to use. The  user can\n  enter  up to 10 lines of  text, and the  program  wont allow  an user to\n  save an empty text, furthermore, the  progarm allows users with suffient\n  access to stay anonymous.\n\n  Future  versions will  allow the sysop to blacklist  certain users, and\n  also the ability ti quote what other people have entered.\n\n  ========================================================================\n\n@endnode\n\n@node 02 "Installation"\n\n  ========================================================================\n\n  Installing  this program is really  quite simple, the  only things you\n  have to is to make sure the following is right :\n\n  Program      Location          Description\n  -------      --------          -----------\n  WarLogoff    Doors:WarLogoff   The main program\n  Banner.txt   Doors:WarLogoff   The banner to be displayed, will\n                                 be generated when the program\n                                 is run.\n\n  Also make sure that g.info is in the commands/bbscmd drawer.\n\n  The progarm should be able to run on any Amiga, and on /X v2.xx and 3.xx\n  I have only tested  it on /X v3.xx and is therefore  not cretain that it\n  will run on /X v2.xx\n\n  ========================================================================\n\n@endnode\n\n@node 03 "Greets"\n\n  ========================================================================\n\n  I would like to greet the following in no order :\n\n  Kronion, Dux, The Freak, Ramirez, Omar, Striker, Playmate, Calvin,\n  Plexer, Gilthanas, Energy, Shamer, Tactica, Zany, Zeke, Spike,\n  Delirium&Kickface, Mike Thompson, Norske, Chock, Paranoid, OB1\n\n      And all other Vanity&Humane members and people I forgot.\n\n  Specials go to :\n\n  Dux .............................. Thanks for helping me with AmiExpress\n  Ramirez .......................... For letting me test at your board\n  Omar ............................. For all sorts of crazy conversation\n\n  ========================================================================\n\n@endnode\n\n@node 04 "Bug report/ideas"\n\n  ========================================================================\n\n  Send your bug reports or ideas to the following boards :\n\n  Susperia ............... +45 434-34236\n  Somewhere Online ....... +45 597-53801\n  Suffocation ............ +45 491-80760 (The board where I test my doors)\n  Mainline ............... +45 981-53062 (Also supports netmail)\n\n  ======================================================================== \n\n@endnode\n','\n',char(10)),NULL,'auto-added',11221,2,0,NULL,NULL,'h_v_wlog','scan',1780048545);
INSERT INTO door_catalog VALUES('h_pnwspp','H-PNWSPP.LZX','~/Code/amiexpress_doors/Archives/AmiExpress/H-PNWSPP.LZX',NULL,'XIM','ppguide',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'auto-added',174351,0,0,NULL,NULL,'h_pnwspp','scan',1780048532);
INSERT INTO door_catalog VALUES('h26e01','H26E01.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/H26E01.LHA','ESend','XIM','ESend',NULL,'Dux/Vanity',NULL,'___/   __/___  ___/  ___/___ O\____   /    \-\____   /    \-------------O /    _/    //  /     /    //   iN 1994',replace('     ______         ______                  \n ___/   __/___  ___/  ___/___               \nO\____   /    \-\____   /    \-------------O\n  /    _/    //  /     /    //   iN 1994    \n //   __¯   //   \\   /    //               \n/°    /    °/ aND \° /    °/ HUMANE & VANITY\n\____//    / _     \___   / _ /X - Division \nO-zy/_____/-//-------\___/-//--(Pr@s@nts:)-O\n    ErrorLog v0.01 for /X by Dux/Vanity     \nThis will keep you up to date with all the  \n  errors that could occur at your board     \n','\n',char(10)),'ESend.doc',replace('.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo..oOo.oOo.\n\n                              Error Sender v0.01\n\n                                by Dux/Vanity\n\n.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo.oOo..oOo.oOo.\n\n\nIntroduction\n~~~~~~~~~~~~\nDon''t you just hate when you one day, when you''re browsing through your HD you\nfind an ErrorLog in one of your node-dirs? This small util will solve these\nproblems for you by sending you a msg whenever an error occurs on your BBS.\n\n\nUsage\n~~~~~\nThe syntax is like this:\n\nESend <NodeNr> <Conferencepath>\n\nWhere <NodeNr> should be replaced with the number of the node you want to\ncheck, and <Conferencepath> should be replaced with the full path to the\nconference where you want to receive the message. The path should be WITHOUT\nany trailing :''s or /''s!\n\nYou can run the util in your logoffscript or using a cron-program.\n\nThat''s just about it...\n\n\nHow to contact\n~~~~~~~~~~~~~~\nI can be reached at Mainline: +45-9815 3062/+45-9815 3562 or on most major\nDanish boards. Or by /Xnet on: Dux@DK0001.\n\n\nGreets\n~~~~~~\nDevilstar\nLector\nRelief\nSilver Fox\nWardancer\nRamirez\nEmpire\nTarzan\nScratch\nShark\nFrostie\n','\n',char(10)),NULL,'auto-added',11282,5,0,NULL,NULL,'h26e01','scan',1780048532);
INSERT INTO door_catalog VALUES('h26vl','H26VL.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/H26VL.LHA','QuickLogon','XIM','Cp_nähä_Du!!',NULL,'Dux/Humane&Vanity',NULL,'___/   __/___  ___/  ___/___ O\____   /    \-\____   /    \-------------O /    _/    //  /     /    //   iN 1994',replace('     ______         ______                  \n ___/   __/___  ___/  ___/___               \nO\____   /    \-\____   /    \-------------O\n  /    _/    //  /     /    //   iN 1994    \n //   __¯   //   \\   /    //               \n/°    /    °/ aND \° /    °/ HUMANE & VANITY\n\____//    / _     \___   / _ /X - Division \nO-zy/_____/-//-------\___/-//--(Pr@s@nts:)-O\nQuickLogon V1.0 For /X  By Dux/Humane&Vanity\n','\n',char(10)),'QuickLogon.doc',replace('ooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooo\n\n                              Quick Logon v1.00\n\n                              Code by Dux/Vanity\n\nooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooooo\n\n\nIntroduction\n~~~~~~~~~~~~\nHave you ever wanted to have a couple of bulletins shown at logon but still\nwanted to keep the time it took to get on your board to a minimum? Then "Quick\nLogon" is the thing you need!\n\n\nInstallation\n~~~~~~~~~~~~\nCopy the supplied QLOGON.info to your BBS:Commands/SYSCMD/ dir.\n\nCopy the QuickLogon and QuickLogon.info to wherever you want them. Eg.\nDOORS:QuickLogon.\n\nNow you need to create you bulletins. You could call your old logon-bull for\nBBS:Screens/NoQuickLogon.txt and make a short version of it called\nBBS:Screens/QuickLogon.txt.\n\nYou can ofcourse also add accesslevel to the files. Eg. NoQuickLogon40.txt.\nMCI codes are also accepted in the bullfiles.\n\nNow you can edit your BBS:Bull.txt to something like this:\n\n--CUT--\n~\n~CC_QLOGON\n--CUT--\n\nNow you need to edit the QuickLogon.info to your own needs!\n\n\nHow to contact\n~~~~~~~~~~~~~~\nI can be reached at my own board Mainline +45-9815 3062/+45-9815 3562 or on\nmost Danish elite boards. Or by /Xnet to ''Dux@DK0001''.\n\nI would appreciate to know who''s using my doors/utils.\n\n\nGreets\n~~~~~~\nDevilstar\nLector\nTarzan\nRamirez\nWardancer\nFrostie\nScratch\nEmpire\nYobbo\n','\n',char(10)),NULL,'auto-added',41974,6,0,NULL,NULL,'h26vl','scan',1780048532);
