INSERT INTO door_catalog VALUES('hbt_sb20','HBT_SB20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HBT_SB20.LHA','AmigaGuide','XIM','SmartBII.000','2.0','NiGHTSHADE!','HBT',NULL,replace('SMART BULLETiNE V2.0 BY NiGHTSHADE!\n','\n',char(10)),'SmartBII.Guide',replace('@Width 72\n@Node Main "SmartBull2.0"\n    ____________________________________\n    \    /  ¬\_____  ¬\_____  ¬\_____  ¬\::::::. ::: ::: .::::::.::::::\n    /ø  _    /ø  _    /ø  _  __/ø   /   /::: ::: ::: ::: :::    :::\n   //  /    //  /    //  /    //   /   / ::::::  `:::::: :::    :::::::\n  /___/___ /___/___ /___/___ /_______ /  ::: :::     ::: :::    :::\n        ¬\/      ¬\/      ¬\/tGø   ¬\/   ::::::'' ::::::'' :::    `::::::\n\n        BRiNGS YOU TODAY THE BEST BULLETINE PROGRAM AWAiL UP TO DATE\n\n                SMART BULLETINE V2.0 By NiGHTSHADE/HARDBYTE\n         -=========================-   -=========================-\n           @{"WHY USE SMART BULLETINE" Link "WSMART"}  «-»  @{"REQUIREMENTS TO USE It " Link "Requirements"}\n           @{"COPYRIGHT NOTICES      " Link "Copyright"}  «-»  @{"INSTALL SMARTBULL 2.0  " Link "Install"}\n           @{"MAKE A BULL SCRIPT     " Link "Script"}  «-»  @{"CONTACT US             " Link "Contact"} \n           @{"GREETiNGS              " Link "Greet"}\n         -=========================-   -=========================-\n@EndNode\n\n@Node "WSMART"\n@Toc "Main"\n\n   Why use SmartBulletine V2.0\n  =============================\n\n    * No LONG loggoff scripts that must be executed every time that a user\n      loggsoff youre board.\n    * Local & Global conferance bulletines (Invidual for every conferance)\n    * Less fragmented hard drive (For FASTER fileaccess)\n    * Nicer preformance then the standard ''B'' command\n\n                     @{"  -+*+- RETURN TO MAiN -+*+-  " Link "Main"}\n\n@EndNode\n\n@Node "Requirements"\n@Toc "Main"\n\n  Requirements to run this door\n ===============================\n\n   * Amiga OS 2.0+ (Tested up to 3.0)\n   * Any CPU in the range 68000-68040\n   * /X V2.0+\n\n                     @{"  -+*+- RETURN TO MAiN -+*+-  " Link "Main"}\n\n@EndNode\n\n@Node "Copyright"\n@Toc "Main"\n\n  Copyright notices\n ===================\n\n   * Copyright 1993-1994 by NiGHTSHADE/HARDBYTE\n   * I take no responcibility for what this door may cause, but i can\n     guarantee that it have been hard tested\n   * If you find ANY buggs then report them to me by dialing WASTELANDS\n   * If you have any god ideas of improvements then dial me to!\n   * I have coded about 3 hard hours to cover & check for ANY buggs so i\n     guess that this tool should be bugg free (MANY other groups dont\n     even check theire tools 100%)\n\n                     @{"  -+*+- RETURN TO MAiN -+*+-  " Link "Main"}\n\n@EndNode\n\n@Node "Install"\n@Toc "Main"\n\n   The installation of this door\n  ===============================\n\n    * Follow the directives in the /X manual for details\n    * If you are using /X 3.0+ then you might want to use the supplied\n      icon for faster installation\n    * Make a file named ''LOBULL'' in every conferance that should use\n      the Local bulletine feature and a file naned ''GLBULL'' in every\n      conferance that should use Global bulletines... and ofcouse\n      none in a conferance that shouldnt have any bulletines at all.\n    * A sample of a dir structure :\n    * Make a script file for every bulletine that should be\n      autoupdated (see the @{" make a script " Link "Script"} charapter)\n\n  BuLL (dir)                     <-- The global bull dir\n    Bull1.s                      <-- The script making Global bull #1\n    Bull1.TXT                    <-- Global bull #1\n    BullHelp.TxT                 <-- The global Bullmenu file\n\n  Doors (dir)\n       SmartBull (dir)           <-- Smart Bulletines Directory\n         SmartBull               <-- Smart Bulletine EXE file\n\n  Elite (dir)                    <-- Local Conferance\n       Bulletins (dir)           <-- Local Conferance Bull Directory\n         Bull1.s                 <-- The script making local bull #1\n         Bull1.TXT               <-- Local bull #1\n         BullHelp.TxT            <-- The Local Bullmenu file\n       lobull                    <-- The file saying that /X should use\n                                      local bulletines in this conferance\n\n  HardByte (dir)                 <-- Another confreance\n       glbull                    <-- The magic file that sais to\n                                     smartbulletines that it should use\n                                     the GLOBAL BULLETINES (The BuLL Dir)\n\n                     @{"  -+*+- RETURN TO MAiN -+*+-  " Link "Main"}\n\n@EndNode\n\n@Node "Script"\n@Toc "Main"\n\n  Make a AUTO-UPDATE script\n ===========================\n\n   * Enter youre favorite TXT editor\n   * Make a scriptfile named BULL{no}.s in the BULL directory that\n     makes the bulletine (same no that the scriptfile)\n\n                     @{"  -+*+- RETURN TO MAiN -+*+-  " Link "Main"}\n\n@EndNode\n\n@Node "Contact"\n@Toc "Main"\n    ____________________________________\n    \    /  ¬\_____  ¬\_____  ¬\_____  ¬\::::::. ::: ::: .::::::.::::::\n    /ø  _    /ø  _    /ø  _  __/ø   /   /::: ::: ::: ::: :::    :::\n   //  /    //  /    //  /    //   /   / ::::::  `:::::: :::    :::::::\n  /___/___ /___/___ /___/___ /_______ /  ::: :::     ::: :::    :::\n        ¬\/      ¬\/      ¬\/tGø   ¬\/   ::::::'' ::::::'' :::    `::::::\n\n                       BOARDS AWAiL FOR YOURE CARRiER!\n\n       WE NEED POWERFULL MEMBERS ALL AROUND THE GLOBE SO CALL US AND\n       YOU MiGHT QUALiFY FOR A MEMBERSHiP iN OUR GROUP !\n\n     WASTELANDS  [+46-8-623O196] - [21k6 USR TERBO] - [NiGHTSHADE/HBT]\n      THE SLAMMER [+46-8-623O196] - [21k6 USR TERBO] - [DiSTLER/HBT]\n\n                     @{"  -+*+- RETURN TO MAiN -+*+-  " Link "Main"}\n\n@EndNode\n\n@Node "Greet"\n@Toc "Main"\n    ____________________________________\n    \    /  ¬\_____  ¬\_____  ¬\_____  ¬\::::::. ::: ::: .::::::.::::::\n    /ø  _    /ø  _    /ø  _  __/ø   /   /::: ::: ::: ::: :::    :::\n   //  /    //  /    //  /    //   /   / ::::::  `:::::: :::    :::::::\n  /___/___ /___/___ /___/___ /_______ /  ::: :::     ::: :::    :::\n        ¬\/      ¬\/      ¬\/tGø   ¬\/   ::::::'' ::::::'' :::    `::::::\n\n                NiGHTSHADE GREETS THE FoLLOWiNG PEOPLES:\n\n        AGAMEMON       BLAST             BOBO              CASE\n        CAT            CATEYE            @{"CENTURION       " Link "CENTURION"}  DANSKEN\n        @{"DANZIG       " Link "DANZIG"}  DISTLER           @{"GAZ             " Link "GAZ"}  GORFY\n        HOBO           ICON              @{"LOOBY           " Link "LOOBY"}  MELETH\n        NECRONOMICON   PRINCIP           PROCTOR           RAD\n        RAJ-BAN        SHAPECHANGER      SKUTT             SNIPER\n        SHOCKER        BIG BYTE          ZANOK\n\n                     @{"  -+*+- RETURN TO MAiN -+*+-  " Link "Main"}\n\n@EndNode\n\n@Node "GAZ"\n@Toc "Main"\n    ____________________________________\n    \    /  ¬\_____  ¬\_____  ¬\_____  ¬\::::::. ::: ::: .::::::.::::::\n    /ø  _    /ø  _    /ø  _  __/ø   /   /::: ::: ::: ::: :::    :::\n   //  /    //  /    //  /    //   /   / ::::::  `:::::: :::    :::::::\n  /___/___ /___/___ /___/___ /_______ /  ::: :::     ::: :::    :::\n        ¬\/      ¬\/      ¬\/tGø   ¬\/   ::::::'' ::::::'' :::    `::::::\n\n         HELLO GOOD FRiEND - HOPE YA 3DO AND SNES IS GOiNG WARM!\n\n                    @{"  -+*+- RETURN TO GREETiNGS -+*+-  " Link "GREET"}\n\n@EndNode\n\n@Node "CENTURION"\n@Toc "Main"\n    ____________________________________\n    \    /  ¬\_____  ¬\_____  ¬\_____  ¬\::::::. ::: ::: .::::::.::::::\n    /ø  _    /ø  _    /ø  _  __/ø   /   /::: ::: ::: ::: :::    :::\n   //  /    //  /    //  /    //   /   / ::::::  `:::::: :::    :::::::\n  /___/___ /___/___ /___/___ /_______ /  ::: :::     ::: :::    :::\n        ¬\/      ¬\/      ¬\/tGø   ¬\/   ::::::'' ::::::'' :::    `::::::\n\n HELLO CENTURiON, I CAN SE THAT YOURE BOARD IS A FUCKING FAST SNES BOARD!\n\n                    @{"  -+*+- RETURN TO GREETiNGS -+*+-  " Link "GREET"}\n\n@EndNode\n\n@Node "LOOBY"\n@Toc "Main"\n    ____________________________________\n    \    /  ¬\_____  ¬\_____  ¬\_____  ¬\::::::. ::: ::: .::::::.::::::\n    /ø  _    /ø  _    /ø  _  __/ø   /   /::: ::: ::: ::: :::    :::\n   //  /    //  /    //  /    //   /   / ::::::  `:::::: :::    :::::::\n  /___/___ /___/___ /___/___ /_______ /  ::: :::     ::: :::    :::\n        ¬\/      ¬\/      ¬\/tGø   ¬\/   ::::::'' ::::::'' :::    `::::::\n\n           YO LOOBY, HOPE YOU ENJOY THE SHOW - I LOVE HARDBYTE!\n      MY NEW iNCLUDE SYSTEM IS SOON COMPLETED, GIVES APPROX 30% GAiN!\n\n                    @{"  -+*+- RETURN TO GREETiNGS -+*+-  " Link "GREET"}\n\n@EndNode\n\n@Node "DANZIG"\n@Toc "Main"\n    ____________________________________\n    \    /  ¬\_____  ¬\_____  ¬\_____  ¬\::::::. ::: ::: .::::::.::::::\n    /ø  _    /ø  _    /ø  _  __/ø   /   /::: ::: ::: ::: :::    :::\n   //  /    //  /    //  /    //   /   / ::::::  `:::::: :::    :::::::\n  /___/___ /___/___ /___/___ /_______ /  ::: :::     ::: :::    :::\n        ¬\/      ¬\/      ¬\/tGø   ¬\/   ::::::'' ::::::'' :::    `::::::\n\n YO MY FRiEND - CAN YOU MAKE SONE NiCE HARDBYTE AND WASTELANDS LOGGOS !?\n\n                    @{"  -+*+- RETURN TO GREETiNGS -+*+-  " Link "GREET"}\n\n@EndNode\n','\n',char(10)),NULL,'auto-added',55946,3,0,NULL,NULL,'hbt_sb20','scan',1780048539);
