INSERT INTO door_catalog VALUES('hbt_tw10','HBT-TW10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HBT-TW10.LHA','tOP_3o_mSG_wRITERS','XIM','tOP_3o_mSG_wRITERS',NULL,'DiSTLER','HBT','________/___/_____ ________ ________ \\__    / \______ ¬\______ ¬\______ ¬\_ --/   _    /   _    /   _ ___/    /   /-----',replace('          ____\n ________/___/_____ ________ ________\n\\__    / \______ ¬\______ ¬\______ ¬\_\n--/   _    /   _    /   _ ___/    /   /-----\n·/    /   /    /   /    /  \/    /   /·BYTE·\n/____/   /____/   /____/   /____    /-------\n   /____/   /____/   /____/kRm/____/ iN 1994\n    tOP 3o mSG wRITER''S v1.O by DiSTLER\n tHE bEST oUTPUT oF tHE 3o bEST mSG wRITERS\n  iNSTALL! aND _aBUSE_ tHIS wOUNDERFUL aND\nsTUNNING fAST /X uTIL RELEASE DATE: 03-27-94\n','\n',char(10)),'wRITER''S.GUIDE','',NULL,'auto-added',18079,4,0,NULL,NULL,'hbt_tw10','scan',1780048539);
INSERT INTO door_catalog VALUES('hcd_cs10','HCD-CS10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HCD-CS10.LHA','COMPOSTATS','XIM','COMPOSTATS',NULL,'Agamemnon!','HCD','+---/o  /   /___________  _ /--------------+ //      /. _____/   /  // Hardcore Design +-/___/___//  /___/______ /----------------+',replace(' Sk¡n________   _ ___________               \n+---/o  /   /___________  _ /--------------+\n   //      /. _____/   /  // Hardcore Design\n+-/___/___//  /___/______ /----------------+\n..:::::::/______ /::::::\/::::::::::::::::..\n By Agamemnon! \/ RELEASED TODAY!!!         \n«×» CompoStats v1.0 «×××» /X any version «×»\n','\n',char(10)),'COMPOSTATS.DOC',replace('                              CompoStats v1.0\n                              ~~~~~~~~~~~~~~~\n\nCompoStats is an online upload/download toplistmaker which scans\nthe UDLog for uploads and downloads.\nThis small utility is ment for Compos etc.\n\nJust install it as an ordinary AmiExpress door in DOORS:. \n\nThere are a few tooltypes to config too:\n\n    · FROM = mm-dd-yy, from which date the compo started.\n    · TO =   mm-dd-yy, when the compo ends.\n    · AMOUNT = how many users there will be in the list.\n    · UDLOG = complete pathname with filename of the UDLog file.\n\nThats it! \n\nPlease report to Infinite Power +46-[0]171-67461 if you find any\nbugs or for new versions.\n\n\n\n  - AGAMEMNON / HARDCORE DESIGN\n','\n',char(10)),NULL,'auto-added',24233,3,0,NULL,NULL,'hcd_cs10','scan',1780048539);
