INSERT INTO door_catalog VALUES('hcd_fp15','HCD-FP15.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HCD-FP15.LHA','FilePack15','XIM','FilePack15',NULL,NULL,'HCD',NULL,replace('XXXX....\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 20:29:05  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',9574,2,0,NULL,NULL,'hcd_fp15','scan',1780048539);
INSERT INTO door_catalog VALUES('hcd_ga10','HCD-GA10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HCD-GA10.LHA','GetAnswer','XIM','GetAnswer',NULL,'Agamemnon','HCD','.\\__   / ______ ¬\_____ ¬\_---------------| |  /  _    /   /___/   /   // ·HARDCORE·   | | /   /   /   /   /   /   /    ·DESiGN·    |',replace('  _______/\_______ _______                 :\n.\\__   / ______ ¬\_____ ¬\_---------------|\n|  /  _    /   /___/   /   // ·HARDCORE·   |\n| /   /   /   /   /   /   /    ·DESiGN·    |\n|/___/   /___    /___    /-----------------''\n:---/___/---/___/kRm/___/--= By Agamemnon =-\n          GetAnswer v1.0 - /X Door          \n Extremely useful for cosysops and sysops.  \n You can read what a user wrote in the      \n ANSWERS-file.                              \n-==========================================-\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                                                .------''\n             `------------------------------------------------''\n','\n',char(10)),NULL,'auto-added',17276,6,1,'ga','Doors/GetAnswer','hcd_ga10','scan',1780048539);
INSERT INTO door_catalog VALUES('hcd_np21','HCD_NP21.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HCD_NP21.LHA','POWERPLAYER','XIM','NEWPAGE',NULL,'Agamemnon','HCD','.\\__   / ______ ¬\_____ ¬\_---------------| |  /  _    /   /___/   /   // ·HARDCORE·   | | /   /   /   /   /   /   /    ·DESiGN·    |',replace('  _______/\_______ _______                 :\n.\\__   / ______ ¬\_____ ¬\_---------------|\n|  /  _    /   /___/   /   // ·HARDCORE·   |\n| /   /   /   /   /   /   /    ·DESiGN·    |\n|/___/   /___    /___    /-----------------''\n:---/___/---/___/kRm/___/--= By Agamemnon =-\n           NewPage v2.1 - /X Door           \n Can play modules, store chats, create      \n toplists, built-in macrokeys, read chats   \n from /X, available time-limits, w/o reason \n prompt. Simply the Best! Install NOW!!     \n-==========================================-\n','\n',char(10)),'NEWPAGE.GUIDE',replace('@database "NewPage 2.1 by Agamemnon/Hardcore Design"\n@node main "NewPage 2.1 by Agamemnon/Hardcore Design"\n                _  _ __.---------------------------.__ _  _\n                       |       NewPage v2.1        |\n                _  _ __| Agamemnon/Hardcore Design |__ _  _\n                       `---------------------------''\n\n                           @{"   What is NewPage?   " link sec-1}\n\n                           @{"   Why use NewPage?   " link sec-2}\n\n                           @{"How to install NewPage" link sec-3}\n\n                           @{"    Using NewPage     " link sec-4}\n\n                           @{"       History        " link sec-5}\n\n                           @{"Bug reports and ideas " link sec-6}\n\n                           @{"       Credits        " link sec-7}\n\n@ENDNODE\n@Node SEC-1 "What is NewPage?"                         \n                         _                       _\n                      -=[_]=- WHAT IS NEWPAGE -=[_]=-\n\nThis is a very good door made for /X use. This door allows you to save all\nthe chats in special files for each user. Instead of the ridiculous beep,\nyou can @{"configurate" link sec-3 } the chatter to play a module.\n\n@ENDNODE\n\n@Node SEC-2 "Why use NewPage?"                         \n                         _                       _\n                      -=[_]=- WHY USE NEWPAGE -=[_]=-\n\nThis chatter is good to use when you want to store the chats and don''t feel\nlike turning on a giant capturefile. With this one you will be able to get\nall the chats in small files.\n@ENDNODE\n\n@Node SEC-3 "How to install NewPage?"                         \n                     _                              _\n                  -=[_]=- HOW TO INSTALL NEWPAGE -=[_]=-\n\nTo install this door in /X follow these steps.\n\n  1. Make a dir named "DOORS:NewPage/" This dir may not be changed because\n     NewPage saves all the chats in this directory.\n\n  2. Copy NewPage to the DOORS:NewPage/ directory.\n\n  3. Make a file named "DOORS:NewPage/NewPage.CFG" There you shall\n     put a few lines looking like this.\n\n               ------------------CUT HERE------------------\n                    MODULENAME=DOORS:NewPage/mod.music\n                    PLAYMODULE=YES\n                    COMMENT=Sysop Is Busy!\n                    COMMENT=Sorry, No Time For Ya!\n                    COMMENT=I''ll get right back to you!\n                    COMMENT=Burn In Hell, Fuckhead!\n                    MACRO.S=dh5:SYSOP.txt\n                    MACRO.L=dh5:LAMER.txt\n                    MACRO.E=dh5:LEECHER.txt\n                    MACRO.K=dh5:HATA.txt\n                    SYSOP1=AGAMEMNON\n                    SYSOP2=MR.SAINT\n                    TIME=0000-2359\n                    SAVE=YES\n                    OVERRIDE=100\n                    TOPLISTLONG=BBS:ELITE/BULLETINS/BULL11.TXT\n                    TOPLISTTIMES=BBS:ELITE/BULLETINS/BULL12.TXT\n                    TOPLIST#=15\n                    MAKETOPLISTS=YES\n                    IMPORTANTLEVEL=100\n                    SCANLEVEL=254\n                    DOWNOTHERLEVEL=254\n                    BREAKLEVEL=100\n                    INTERNALPLAYER=YES\n                    ENDNODE.0=1\n                    ENDNODE.1=2\n                    CTRLZEND=NO\n                    WBNODE=2\n                    REASON=NO\n               ------------------CUT HERE------------------\n\n      Explanation of the config:\n\n      · MODULENAME    - The complete path for the module that\n                        will play during the paging.\n      · PLAYMODULE    - YES/NO, play module or not.\n                        Default: YES\n      · COMMENT       - These are the text strings that will appear\n                        in a cycle gadget, and to be used when\n                        you don''t want to chat with the user.\n                        You can have infinite number of COMMENT''s.\n      · MACRO.x       - These are in-chat macros with textfiles\n                        that will be shown when the key x is pressed.\n      · SYSOP1\n        SYSOP2        - Multisysop support, some boards have more\n                        than one sysop, often 2 , but almost NEVER\n                        3 sysop''s. These names will be shown in\n                        the Chat-files as well.\n      · TIME          - HHMM-HHMM, start and end time when sysop\n                        is available. This timelimit can be overridden.\n                        Default: 0000-2359\n      · OVERRIDE      - Accesslevel to override timelimit.\n                        Default: 0\n      · SAVE          - YES/NO, some sysops don''t even want to store\n                        the chats, so I made it configurable.\n                        Default: YES\n      · TOPLISTLONG   - Complete path for the top long chatters list.\n                        Default: T:DEFAULT1.TXT\n      · TOPLISTTIMES  - Complete path for the top chatters list.\n                        Default: T:DEFAULT2.TXT\n      · TOPLIST#      - Users in toplists.\n                        Default: 10\n      · MAKETOPLISTS  - YES/NO, make toplists after every chats.\n                        Default: YES\n      · IMPORTANTLEVEL- Accesslevel for the IMPORTANT keyword.\n                        Default: 254\n      · SCANLEVEL     - Accesslevel for the SCAN keyword.\n                        Default: 255\n      · DOWNOTHERLEVEL- Accesslevel to download another user''s chatlog.\n                        Default: 255   \n      · BREAKLEVEL    - Accesslevel to break the chat.\n                        Default: 255\n      · INTERNALPLAYER- YES/NO, use the internal moduleplayer or the\n                        external PowerPlayer.\n      · ENDNODE.n     - where n is the nodenumber, set for example\n                        ENDNODE.0=1 to end chat on node 0 with F1, and\n                        ENDNODE.1=3 to end chat on node 1 with F3.\n      · CTRLZEND      - Use CTRL-Z on all nodes to end chat, no F-keys.\n                        Use this if you have other commodities like\n                        blankers etc. using hotkeys with the F-keys. \n      · WBNODE        - Node you are running on other screen than\n                        AmiExpress. \n      · REASON        - YES/NO, prompt for a reason before paging.\n                   \n   4. Copy POWERPLAYER to your C: directory if you do not use the \n      internal player.\n\n   5. Make sure that RX is located in @{"REXXC:" link jadu } if you do not \n      use the internal player.\n\n   6. Edit your BBS:Commands/BBS.CMD or the BBS:Commands/CustomCommands and\n      place this line in it...\n\n              -------------------CUT HERE-------------------\n                   *O        XS005DOORS:newpage/newpage\n              -------------------CUT HERE-------------------\n\n      This will tell /X that if a user type "O" it will run the\n      DOORS:NewPage/NewPage file and override the /X chat command...\n\n   7. Of course it works with /X as well, just configure it as\n      usual.\n\n@ENDNODE\n\n@Node SEC-4 "Using NewPage"\n                          _                     _\n                       -=[_]=- USING NEWPAGE -=[_]=-\n\n   Usage: O [UPDATE] [SCAN] [IMPORTANT] [DOWNLOAD] [LAST]\n     \n   When the user is paging you a small window will appear on your workbench\n   showing how long before /X tells the user that you were not around. The\n   user name will also be displayed and why he wants to chat with you.\n   There is also a Cycle Gadget. Press it to skip to wanted message. Then\n   press the Stop! button to send the message. Or simply press the correct\n   Answer button to pop /X and chat. STARTCHAT2.TXT and ENDCHAT2.TXT are\n   used for the second sysop. \n\n     There are also some keyboard shortcuts;\n     Press ''1'' to answer as SYSOP 1 \n     Press ''2'' to answer as SYSOP 2 \n     Press ''s'' to Stop the paging and send the comment.\n     Press TAB to cycle the comments.\n  \n   If the sysop available flag is turned off, the textfile \n   BBS:NODEx/CHATFLAGOFF.TXT will be shown if it exists, otherwise\n   the user will be shown a small default text. \n   And if the user has paged Sysop without any answer the textfile\n   BBS:NODEx/CHATNOTAVAIL.TXT will be shown if it exists or there''s\n   a default textstring to be shown.\n   If you wish to end the chat press F1 and the\n   chat will be appended to DOORS:NEWPAGE/CHATLOG_n.TXT where n is the\n   number of the user.\n\n   O ?             : Show all keywords with simple descriptions.\n\n   O UPDATE        : Update the toplists. \n                     This can be useful for those who doesn''t use the \n                     MAKETOPLISTS=YES in the configfile.\n   \n   O SCAN          : Everyone with the correct access can view chats.\n                     You can choose this level by SCANLEVEL in the config.\n                     Enter user''s name OR number, ''coz NewPage is\n                     intelligent enough to figure it out if it is\n                     a number you''ve entered. You can write\n                     "O SCAN <USERNAME/USERNR>" too if you want. \n   \n   O IMPORTANT     : Everyone with the correct access can page sysop \n                     even if the sysop available flag is turned off.                \n                     You can choose this level by IMPORTANTLEVEL in the\n                     config.\n   \n   O DOWNLOAD user : Download the user''s chatlog-file.\n                     If you have high status enough then you can \n                     download another user''s chatlog-file. Enter\n                     his/her username OR number after the keyword\n                     DOWNLOAD. This accesslevel is chosen by DOWNOTHERLEVEL\n                     in the configfile. \n   \n   O LAST          : View the last 10 chatters.\n\n                                   * * * \n                                   \n   The Toplist-headers are found in :\n   \n           S:NEWPAGE_TOPCHATTS.TXT   - The top chatts header\n           S:NEWPAGE_TOPTIMES.TXT    - The top long chatters header \n \n                                   * * *\n                                   \n   If something should fuckup totally an errormessage will be shown,\n   based on these values:\n   \n   Error 0 : Can''t open intuition.library v36+.\n         1 : Can''t open gadtools.library (any version).\n         2 : Can''t open commodities.library (any version).\n         3 : CreateMsgPort() failed, can''t create hotkey message port.\n         4 : Can''t create host broker.\n         5 : Can''t create hotkey (eg. F-keyhandler).\n         6 : Can''t create sender.\n         7 : Can''t create translater.\n         8 : Can''t lock public workbench screen.\n         9 : GetVisualInfo() failed, needed for gadgets in chatwindow.\n         10: Can''t create gadgetlist context.\n         11: At least one gadget failed.\n         12: Can''t open NewPage window.\n         13: Can''t open streplay.library for internal player\n         \n   Please contact me (Agamemnon) as fast as possible if any\n   errors occur! \n\n\n@ENDNODE\n\n@Node SEC-5 "History"\n                             _               _\n                          -=[_]=- HISTORY -=[_]=-\n\n   Version 1.0 - Initial release\n\n   Version 1.1 - Some minor changes, COMMENT''s etc.\n\n   Version 1.2 - Not released, minor changes, MACRO''s.\n\n   Version 2.0 - * Compiled with SAS/C 6.50.\n                 * Time limits. (Thanx Zune for the idea!)\n                 * Multisysop support. (Thanx Nojje for the idea!)\n                 * Bug fix in chat, now it doesn''t chop the last\n                   character on each line.\n                 * Date/Time/Sysop in chatfiles.\n                 * Save chat option. (Thanx ??? for the idea!)\n                 * Override time limit.\n                 * RX is in REXXC: now, NOT REXX:. (TNX everybody!)\n                 * Now you press F1 to end a chat, *NOT* CTRL-Z\n                   YES!! FINALLY!!\n                 * Bug fix, now handles /X Screen popping properly.\n                 * Including 020+ version now, but I don''t\n                   think they are that much faster than the 68000 version.\n                 * Tells the chat time after the chat.\n                 * Play module option. (Thanx NIGHTSHADE!)\n                 * Some default values of the options if they are\n                   not included in the configfile, it could really \n                   fuck up things before i think.\n                 * Keyboard shortcuts.\n\n   Version 2.1 - * Fixed a bug, if you had too long comment before,\n                   the text went outside the cycle gadget.\n                   (Thanx DIOGENES!)                  \n                 * Some extra returns on a few places. (Tnx DIOGENES!)\n                 * Adds in callerslog now. (Tnx DIOGENES!)\n                 * Major bug fix, doesn''t fuck up if the nodescreen\n                   is closed when you try to answer a chat request.\n                 * Keywords: SCAN, UPDATE, IMPORTANT, DOWNLOAD. Can \n                   read chats directly from /X, can make toplists, \n                   can page sysop no matter what the available flag \n                   is set to. (Thanx MR.COKE for the IMPORTANT idea :) )\n                 * Bug fix; in v2.0 it used BBS:NODE0/START,ENDCHAT\n                   files no matter what node the user paged sysop from.\n                   (Thanx AUTO!)\n                 * Internal error handler, NewPage should not fuckup\n                   if something goes wrong.\n                 * User can break chat with CTRL-C. \n                 * Keyword: LAST, view the last ten chatters. (Tnx Termax!)\n                 * Won''t fuckup F1-handling on multinode boards.\n                 * If you are 2 sysops then the user will be shown a\n                   menu to choose which sysop to comment if the \n                   available flag is off, or if nobody answered the page.\n                 * 2 textfiles to be shown if; the available flag is \n                   turned off, and if the user paged and didn''t get any\n                   answer.\n                 * Can choose to end chat with CTRL-Z.\n                 * Can choose which F-key to end chat on which node.\n                 * Can choose accesslevel to use CTRL-C to break chat.\n                 * Can use internal moduleplayer instead of POWERPLAYER.\n                 * Bug fix, too long sysopnames would go outside the \n                   gadget borders.\n                 * Infinite sysops support for Comment-section. (Tnx Vileius!)\n\n@ENDNODE\n\n@Node SEC-6 "Bug Reports and Ideas"\n\n                      _                             _\n                   -=[_]=- BUG REPORTS AND IDEAS -=[_]=-\n\n   You can leave messages to me (AGAMEMNON) on all boards of \n   HARDCORE DESIGN, or call my board: @{"INFINITE POWER" link REKLAM! } \n   at +46-[0]171-67461. Ideas for future versions of NewPage are *VERY* \n   welcome! Or I might just forget to continue the work of making \n   NewPage the very best chat-utility available right now!\n\n@ENDNODE\n\n@Node SEC-7 "Credits!"\n                             _               _\n                          -=[_]=- CREDITS -=[_]=-\n\n   Coding.....................................Agamemnon/Hardcore Design\n   Docs.......................................Agamemnon/Hardcore Design\n   ..................................................Xenophobe/Serenity\n   Ascii Headers........................................Danzig!/G-Style\n   Betatesting.......................................Xenophobe/Serenity\n   ................................................Zune/Hardcore Design\n   ..................................................Lightspeed/Obscene \n   ....................................................Ezco/Meka Design   \n   .................................................Vileius/Independent\n   ................................................Wize/Hardcore Design\n   ................................................Metz/Hardcore Design\n\n\n                                   -0:0-\n                                     ^\n                                   `---''\n@ENDNODE\n\n@Node jadu "Previous bug!"\n\n              In version 1.x of NewPage the RX command would\n              be located in REXX:, but in THIS version it \n              must be located in REXXC: instead.\n@ENDNODE\n\n@Node REKLAM! "COMMERCIAL!"\n\n      - = == ===» ONLY ONE NODE BUT A FUCKING KICKING ONE! «=== == = -\n          __ _ ___.___ .__ ________.___ .__ ___:_____._______\n            \\\\_ |\_ \| _)\_ __\_ |\_ \| _)\_ ¦     |\_ ___/\n               /  |/   \  \/  _)/  |/   \  \/  |\_/  |/  _)__\n              /   |   \    \  |/   |   \    \  | /   |   l   \\n              \___|___|\___/__|\___|___|\___/__|/____¦_______/\n            >-----¦----------------------------------:---DzG--<\n                  :                                  .\n                     ____________ ___:.__ ______________\n                     \_ _   \ _ _)\_ ¦| _)\_ ___/\_ _   \\n                    _/__/   / |  \/  ||  \/  _)__/ _/   /\n                   \\\\____/  l   \  /\   \  l   \ \   <_ _ __\n                   /____| \_______/__/\___/______/__\____\\\\\n                        ¦\n                        :   \n    - = == ===» POWERED WITH A 40 MHZ 68030 FOR KICKING CPS''s «=== == = -\n     - = == ===» FAST VALIDATION! · /X 3.9 · 600 MEGS ONLINE «=== == = -\n      - = == ===»  16800 DUAL STANDARD LOCKED AT 57600 BPS  «=== == = -\n       - = == ===»   POWERLORDS: @{"AGAMEMNON/HCD" link sec-6 } & MR.SAINT  «=== == = -\n \n                          -*- +46-[0]171-67461 -*-\n\n@ENDNODE\n                  ','\n',char(10)),NULL,'auto-added',111227,7,0,NULL,NULL,'hcd_np21','scan',1780048539);
INSERT INTO door_catalog VALUES('hcd_pl10','HCD-PL10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HCD-PL10.LHA','PlayMover','XIM','PlayMover',NULL,'Agamemnon!','HCD','+---/o  /   /___________  _ /--------------+ //      /. _____/   /  // Hardcore Design +-/___/___//  /___/______ /----------------+',replace(' Sk¡n________   _ ___________               \n+---/o  /   /___________  _ /--------------+\n   //      /. _____/   /  // Hardcore Design\n+-/___/___//  /___/______ /----------------+\n..:::::::/______ /::::::\/::::::::::::::::..\n By Agamemnon! \/Presents                   \n«» PlayMover for /X 3.x «» Great Util !!! «»','\n',char(10)),'uzi.txt',replace('                                            .---------------------------.\n    _______.-----------------._______/|     |     4NODEZ  RiNGDOWN      |\n    \_     |     .------     |________|.....| 73 GiG OF AMiGA CoNSoLE PC|\n   .:|     |     |     ______|        |:::::|  uZiSUiCiDE.sERVEBBS.ORG  |\n  .::|     |     |     |     |        |-----+-----.      TELNET         |\n .:::|           |     |     |       :|     |     |                     |\n.::::\___________|___________|________|     `-----+---------------------''\n:::::::::::::::::|                                | 24HR 7DAY STATiC iP! \n_________________|___________/|__________________/|______________________\n\_     ______    |     _______|          |_____________      _/    _____/\n_|_____    |     |     |      |    |_____|        |   |      |     ___|_ \n|     |    |     |     |      |    |     |        |   |      |     |    |\n|     |    |     |     |     :|          |       :|   |      |     |    |\n|__________|_____|_____|______|__________|________|__________|__________|\n:::::::::::::::::|            |                                         |\n`::::::::::::::::|            |ALWAYS THE LATEST VERSION oF AMi-EXPRESS |\n `:::::::::::::::|            | TONS OF ONLiNE MESSAGES AND MULTi-CHATS |\n  `::::::::::::::`------------+  NUP IS REQUIRED SO ASK WHOEVER POSTED  |\n   `::::::::::::::::::::::::::|    THIS ADVERT FOR THE NUMBER AND NUP   |\n    `:::::::::::::::::::::::::`-----------------------------------------''\n','\n',char(10)),NULL,'auto-added',11106,4,0,NULL,NULL,'hcd_pl10','scan',1780048539);
INSERT INTO door_catalog VALUES('hcd_ua10','HCD_UA10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HCD_UA10.LHA','UserAccount','XIM','UserAccount',NULL,'Agamemnon','HCD','.\\__   / ______ ¬\_____ ¬\_---------------| |  /  _    /   /___/   /   // ·HARDCORE·   | | /   /   /   /   /   /   /    ·DESiGN·    |',replace('  _______/\_______ _______                 :\n.\\__   / ______ ¬\_____ ¬\_---------------|\n|  /  _    /   /___/   /   // ·HARDCORE·   |\n| /   /   /   /   /   /   /    ·DESiGN·    |\n|/___/   /___    /___    /-----------------''\n:---/___/---/___/kRm/___/--= By Agamemnon =-\n       UserAccount v1.0 for AmiExpress      \n A nice intuition-based program to be run   \n from the WB. Controlled by some very       \n nicelooking gadgets and menues. Can search \n on various user.data-fields in any pattern.\n-==========================================-\n','\n',char(10)),'UserAccount.DOC',replace('UserAccount v1.0\n~~~~~~~~~~~~~~~~\n\nBy AGAMEMNON / HARDCORE DESIGN\n\nRun from WB.\n\nThe main window will open where you can see all the User''s data.\nWhen you activate Search Mode in the right-button-menu the fields\nwill be cleared and you can enter a value or a string in any field\nand press ENTER, all matched users will appear in a new small window.\n','\n',char(10)),NULL,'auto-added',25796,5,0,NULL,NULL,'hcd_ua10','scan',1780048539);
INSERT INTO door_catalog VALUES('hcd_wh10','HCD_WH10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HCD_WH10.LHA','Who','XIM','Who',NULL,'Agamemnon','HCD','.\\__   / ______ ¬\_____ ¬\_---------------| |  /  _    /   /___/   /   // ·HARDCORE·   | | /   /   /   /   /   /   /    ·DESiGN·    |',replace('  _______/\_______ _______                 :\n.\\__   / ______ ¬\_____ ¬\_---------------|\n|  /  _    /   /___/   /   // ·HARDCORE·   |\n| /   /   /   /   /   /   /    ·DESiGN·    |\n|/___/   /___    /___    /-----------------''\n:---/___/---/___/kRm/___/--= By Agamemnon =-\n            Who v1.0 - /X Door              \n A Fast and simple Who-door to replace the  \n internal one coz it doesn''t work in some   \n versions of /X (at least not mine :) )     \n-==========================================-\n','\n',char(10)),'Who.DOC',replace('                                  Who v1.0\n                                  ~~~~~~~~\n\n                       By AGAMEMNON / HARDCORE DESIGN\n\nA simple XIM-door that replaces the internal /X Who. This is\nnothing fancy, just to make a Who that works. Coz in my version\nof AmiExpress (3.35) the internal Who doesn''t work!!!!? So I just\ndecided to make a fast simple one, and I release it coz maybe\nsome other sysop have the same problem.\n\n','\n',char(10)),NULL,'auto-added',15325,5,0,NULL,NULL,'hcd_wh10','scan',1780048539);
INSERT INTO door_catalog VALUES('hdrul100','HDRUL100.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HDRUL100.LHA','HydraUL','XIM','HydraUL',NULL,'C+N',NULL,'/  /  /  /  / _  \/ __ _/ __- * - - /     /_   _/  /  /     )     /·\ /__/  /\/  //_____/__/  /__/  /// \',replace('        /\______________  ______/\__\|/\n       /  /  /  /  / _  \/ __ _/ __- * - -\n      /     /_   _/  /  /     )     /·\\n     /__/  /\/  //_____/__/  /__/  /// \\n  SdN\_/__///__/ \_____\_/__/\_/__///e^d·\n(»=====\__\/\__\/========\__\/=\__\/======«)\n    The Hydra Upload Counter Door v1.00\n              by C+N / Rebels\n  The Hydra magazine are back, please use\nthis door to include your board in the chart\n    Tested with AmiExpress/Fame/LogicBBS\n(»========================================«)\n','\n',char(10)),'HydraUL.Doc',replace('\n                      /\______________  ______/\__\|/\n                     /  /  /  /  / _  \/ __ _/ __- * - -\n                    /     /_   _/  /  /     )     /·\\n                   /__/  /\/  //_____/__/  /__/  /// \\n                SdN\_/__///__/ \_____\_/__/\_/__///e^d·\n              (»=====\__\/\__\/========\__\/=\__\/======«)\n\n\n\n                     HydraUL door documentation.\n\n\n\n\nJust install this door like an examine door, if you cant do this... HAHA!!\n\nCoded in assembler, tested on LogicBBS, AmiExpress and Fame.\n\n\n\nThe config file only parses config lines of the following format.\n\nLOG.<confnr>=<computer>\n\nYou can ofcoz add as many config lines as you want; ie. Amiga,PC,PSX,N64,etc.\nHere''s an example:\n\n----CUT----\nLOG.2=Amiga\n----CUT----\n\nThe HydraMag is currently only for Amiga Scene so one config will suffice.\n\nThe config file must be located in the same directory as the door.\nLog files will also be created in the same directory as the door, this could\nbe handled in the future with another config if necessary.\nThe log files will be automatically changed each month.\n\nAt the end of each month, then please pack the file to your boardname\nplus the month+year. Heres an example:\n\nHydraLog.1997.04.Apr.Amiga\n\nwould be packed in a achive named:\n\nTradeCentral0497.lha\n\nand then mail/upload the file at Trade Central(at the main prombt, please\nuse "SP"), or email it to [email removed] ... Deadline for handing in the\nfiles are the 10th in the next month.\n\nHave fun!\n\nIf you have any problems you should contact either\n\nEmail: [email removed]           BBS: Conan&Newton on SkyTower or TradeCentral.\n\nor\n\nEmail: [email removed]      BBS: Bakerman on SkyTower or TradeCentral.\n\nYou can also visit the Hydra homepage at:\n\n		http://www.image.dk/~kasperh/hydra.html\n\nMy humblest apologies for any misspellings and the delay of this door.\n\n\n\nAve NGC.\n\n"Drugs! Drugs! Larry! I want drugs..."\n\n\n\n\n\n                    _______________________________________\n                _:__\                                     /__:_\n               __:_____  _______  _________  ________  ______:\n              .\   _   \_   _   \_    _    \_  ___   \_   _   \_\n              |    /   _(  _/   _/   _/    _(   |/    /  _/    /\n              |___/    |   \_    \_  \__   |    /    /   \____/\_\n               nCo!____|____|\____/___|____|________/________.__/\n                ¯                                            :\n                 :    [·]  t r a D e   c e N t r a L  [·]    :\n     ________  __:_____  ____¯ ____¯________ ¯_______  ______:__  _____\n    .\   _   \_    _   \_    \|    |    _   \_   _   \_    _    \_    /\n    |    /____/   _/    /     \    |    /   _(  _/   _/   _/    _(  _/___\n    |    \    \_  \____/\_   \ \   |___/    |   \_    \_  \__   |   \    \_\n    |__________/_._______/___|\____|-tL!____|____|\____/___|_.__|_________/\n                 :                                           :\n                 :           sysoP: baKerMan/dePTh           :\n                 :                                           :\n                 :                  staFF:                   :\n                 :     coNaN&neWToN/reBeLS · cheVy/duNe      :\n                 :         darKwiNg/fLD+eMT+hGE+tL!          :\n                 :                                           :\n                 :          dePTh worLd heaDquarTeRs         :\n                 :         reBELs  worLd heaDquarTeRs        :\n                 :        fNuQuE  worLd   heaDquarTeRs       :\n                 :       hydRa maG. worLd  heaDquarTeRs      :\n                 :      euRocHaRt   worLd   heaDquarTeRs     :\n                 :                                           :\n                 :        +45-32-971-19O (v34+/33k6)         :\n                 :        +45-32-971-195 (v34-/28k8)         :\n                 :        +45-32-861-19O (ISDN/64kO)         :\n                 :        +45-32-861-19O (ISDN/64kO)         :\n                 :                                           :\n                 :          amiGa 4O4O · 3.1 gB hD           :\n                 :        18 mB raM · fAME! · cD-roM         :\n                _:___                                     ___:_\n                 :  /_____________________________________\  :\n\n\n\n','\n',char(10)),NULL,'auto-added',11765,2,0,NULL,NULL,'hdrul100','scan',1780048539);
INSERT INTO door_catalog VALUES('hellpswd','HELLPSWD.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HELLPSWD.LHA',NULL,'XIM','+------------------------------------------+',NULL,'hELLRAiSER',NULL,'|SYStEM PASSWORd dOOR v1.1 fOR AMi /X 3.xx+| |                                          | |      AllOWS YOU tO USE MORE tHAN         |',replace('+------------------------------------------+\n|SYStEM PASSWORd dOOR v1.1 fOR AMi /X 3.xx+|\n|                                          |\n|      AllOWS YOU tO USE MORE tHAN         |\n|    ONE SYStEM PASSWORd fOR YOUR bBS      |\n|                                          |\n|COdEd bY hELLRAiSER  (hALLOWEEN STATE bBS)|\n|                                          |\n+------------------------------------------+\n','\n',char(10)),'title.txt',replace('ENtER hERE tHE tXt YOU WANt tO bE ShOWN bEfORE tHE SYStEM PASSWORd PROMPt\n','\n',char(10)),NULL,NULL,6440,5,0,NULL,NULL,NULL,'scan',1780048539);
INSERT INTO door_catalog VALUES('hf_adm23','HF-ADM23.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HF-ADM23.LHA',NULL,'XIM','AddressMaster',NULL,NULL,'HF',NULL,NULL,NULL,NULL,NULL,'auto-added',455831,0,0,NULL,NULL,'hf_adm23','scan',1780048539);
INSERT INTO door_catalog VALUES('hf_darc1','HF-DARC1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HF-DARC1.LHA','ArcList','XIM','ArcList',NULL,NULL,'HF','____|    (_____________ _ ___  /     / ._)   |     .     _     //(_   \/     / |     _     |     _             \     \_.',replace('         _____ Hellfire /X Division ______\n    ____|    (_____________ _ ___  /     /\n  ._)   |     .     _     //(_   \/     /\n  |     _     |     _             \     \_.\n  |     \_____.     \______.      /\______|\n+-|______\ -- |______\ --- |_____/ --[Mo!]+\n\n           dRAGON''s ArcList v1.0\n\n  An archivelist-interface for your File-\n                  manager\n','\n',char(10)),'ArcList.doc',replace('\n\n       _ ____ _ _________ _ __________ ____________ _  ________ _ ________\n       \\\_   \\\_        \\\    _     \       _  ///_/         \\\_      \_\n   ______ /    \_/      _/       _      \      \_   _//          \_/       /\n  |     //      \       \_.______|      |\______/   \_._________._/       /\n  |_____________/\________|      |______|      |______|         |________/\n\n-----------------------------------------------------------------------------\n                   dragon/incal, hellfire amiexpression\n-----------------------------------------------------------------------------\n\n                               Introduction\n                               ------------\n\n This little tool was made by me a while ago, when I was testing AmigaE.\nIt is in fact a little interface to list archives. It was getting on my\nnerves, when I was not able to list an archive with just one keypress in\nmy filemanager. This was the reason why I wrote this - maybe you have\nuse for it, too.\n\n\n                                Disclaimer\n                                ----------\n\n This program including all the other data in the original archive is just\nprovided "AS IS" without any warranty or guarantee. In consequence of this\nyou as the user have the entire risk of using. The author is not \nresponsible for any damage, loss, etc. resulting from the usage of this \nprogram.\n\n\n                          Copyright, Distribution\n                          -----------------------\n\n This program including all the other data in the original archive is \nplaced within FREEWARE. You are allowed to use it without any payments.\nAny modification, packing except archiving, resourcing is prohibited.\n Any kind of distribution is allowed, as long as the original archive\nremains unchanged and is distributed completely.\n\n\n                              Program History\n                              ---------------\n\n- v1.0 original release\n       - can handle various archive-types as:\n         lha, lzx, arc, zip, dms\n\n\n                                  Credits\n                                  -------\n\n               Coding - Dragon/Incal, Hellfire Amiexpression\n                           Dragon ASCII - Mogue\n\n\n                                   Usage\n                                   -----\n\narclist ARCHIVE/A\n\n- Given an archive in the commandline, ARCLIST opens the file, checks\n  the filetype and if a valid/supported filetype is found, it executes\n  the original archiver to list the archive.\n\n- The original archivers are:\n  - lha\n  - lzx\n  - unarj\n  - unzip\n  - dms\n\n- They should of course be either in the "C:" directory, or the directory''s\n  path should be added with "Path add <directory>"\n\n\n                                  Contact\n                                  -------\n\n        For any bug-reports and suggestions, just contact me under:\n\n                       E-Mail: [email removed]\n\n If you get no immediate response, please be patient, as I am in the army\n              right now. I will respond as soon as possible.\n\n\n                      Last Words, Greetings, Messages\n                      -------------------------------\n\n            Greetings to all my friends in Scene and Real life.\n\n   Unluckily 10.01.96 will be DEPENDENCE DAY, Dragon in the German Navy\n   Therefor we will have a big party on this Saturday in the Dragon Cave\n                            See You there Mates\n\n\n','\n',char(10)),NULL,'auto-added',62067,3,0,NULL,NULL,'hf_darc1','scan',1780048539);
INSERT INTO door_catalog VALUES('hf_dc22','HF-DC22.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HF-DC22.LHA','dGNCOMMENt','XIM','dGNCOMMENt',NULL,'dRAGON','HF',':  /   _/_________\____  ___/______|     / ¦ /  __       /     ______    \_   |   _/''95 |/____/      /________________/    |____\',replace('.   _____         ___________       ______\n:  /   _/_________\____  ___/______|     /\n¦ /  __       /     ______    \_   |   _/''95\n|/____/      /________________/    |____\\n|     \_____/                /_____|-dGN!\n|        - hEllFiRE AMiEXPRESSiON -\n|\n|    dRAGONCOMMENt 2.2 fOR /X bY dRAGON\n|\n| iNClUdES NOW StAtiStiCAl OUtPUt, bEttER\n| hANdLiNG, DiFFERENt CONfIGS fOR COnFS\n`--------------------------- ---  --  -   -\n','\n',char(10)),'comment.cfg.doc',replace(';This is just a docfile for configurating - use the real config file !\n\nNUMB=3				;the number of sysops\nSYS1="dRAGON"			;sysopnames ... same as username!\nSYS2="PERfECtiON"		\nSYS3="ShAdOWOlF"		\nSYS4="SQUIRREL"			\nSYS5="JAZY"\nSYS6="-SLIME!"\nCOM1="SiMPlY tHE bESt"		;commenttexts ...\nCOM2="tHE REAl PERFECt"\nCOM3="NObODY kNOWS"\nCOM4="BERLIN POWER"\nCOM5="JUNKIE"\nCOM6="HOMELESS GUY"\n','\n',char(10)),NULL,'auto-added',27812,12,0,NULL,NULL,'hf_sdc21','scan',1780048539);
INSERT INTO door_catalog VALUES('hf_dgncm','HF-DGNCM.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HF-DGNCM.LHA','dGNCOMMENt','XIM','dGNCOMMENt',NULL,NULL,'HF','/ I \_ ___\   /   / ___\__/____  \_ __/ /  _  / __)/  /\  /\  _//  \|  /  // __) /   ! /  ! /  / / /  \ |/    |  \  \  !  \',replace('   _ ____________________________________\n  / I \_ ___\   /   / ___\__/____  \_ __/\n /  _  / __)/  /\  /\  _//  \|  /  // __)\n/   ! /  ! /  / / /  \ |/    |  \  \  !  \\n\___! \____\____\____/ |\____|  |\__\____/\n----|     \-sHy!---|   |-----|  |PreSENtS\n   dRAGONCOMMENt fOR /X 2.x+ NICE XiMdOOR\n','\n',char(10)),'comment.cfg.doc',replace(';This is just a docfile for configurating - use the real config file !\n\nNUMB=3				;the number of sysops\nSYS1="dRAGON"			;sysopnames ... same as username!\nSYS2="PERfECtiON"		\nSYS3="ShAdOWOlF"		\nSYS4="SQUIRREL"			\nSYS5="JAZY"\nSYS6="-SLIME!"\nCOM1="SiMPlY tHE bESt"		;commenttexts ...\nCOM2="tHE REAl PERFECt"\nCOM3="NObODY kNOWS"\nCOM4="BERLIN POWER"\nCOM5="JUNKIE"\nCOM6="HOMELESS GUY"\n','\n',char(10)),NULL,'auto-added',30565,6,0,NULL,NULL,'hf_dgncm','scan',1780048539);
INSERT INTO door_catalog VALUES('hf_dpg','HF-DPG.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HF-DPG.LHA',NULL,'XIM','pager.x',NULL,'dRAGON!','HF',':  /   _/_________\____  ___/______|     / ¦ /  __       /     ______    \_   |   _/''95 |/____/      /________________/    |____\',replace('.   _____         ___________       ______\n:  /   _/_________\____  ___/______|     /\n¦ /  __       /     ______    \_   |   _/''95\n|/____/      /________________/    |____\\n|     \_____/                /_____|-dGN!\n|        - hEllFiRE AMiEXPRESSiON -\n|\n|    dRAGONPAGE v1.o fOR /X bY dRAGON!\n|\n| iNCLUdES 10 diFFERENt ANiMAtIONS -)     -\n|\n`--------------------------- ---  --  -   -\n','\n',char(10)),'pager.doc',replace('\n                                                       ___ _  _ _/\  _  _\n     _ _/\_  _______            _______________ ______|          \n                ___/____________\________    _/___    |            /\n               ___         /              ___    /    _          _/\n      /_ _  _____/        /     |___________/   /_____|           \\n                 \_______/   __________________/dGN!  |_______  _ _\\n                          hEllFiRE AMiEXPRESSiON\n                 \n                  hAX is back again with another /X door              \n\n\nProduct Info\n------------\n              \nToolname : dGNPAGER ''kOMM MAl hER GEILE SAU!''\nVersion  : v1.o\nRelease  : 1st\nCoder    : dRAGON / iNCAl POSSe ^ hEllFiRE AMiEXPRESSiON\nType     : operatorpager for /X\n\nGeneral Information\n-------------------\n\nWelcome to the 100000st /X operator-page door !\n\nThis one is not something very special, I just wanted to code a pager to\nknow how it works and just by doing this I have the pager I always wanted\nto have (look out for future enhencements).\n\nFeatures\n--------\n\n- This pager features 10 different animations building up the nice styled\n  output \n- Care about the chatflag or not\n- Use ''E SYSOP'' for comment instead of using the Sysops real username\n- Adds line to the Callerslog\n\nDisclaimer\n----------\n\nI don''t take any responsibility for this program - you use it you take the\nrisk !\n\nFuture Plans\n------------\n\n- Enable the sysop to do own designs \n- Random displayed designs\n- Output window also on the WB Screen showing the Users information\n\nHow to Install\n--------------\n* Copy the AEDoor.library to your ''libs:'' drawer\n\n* Copy the ''dgn/'' directory with all contents in your ''doors:'' directory\n\n* Copy the ''O.info'' in your ''BBS:Commands/BBScmd/'' directory.\n\nGreetings\n---------\nGreets fly out to all Incal Members and all Hellfire Members and all my\nfriends\n\nSpecial Messages to:\n\nPerfection	- Hey melde Dich doch mal wieder old friend\nSquirrel	- Ich komm'' doch noch !\n-Slime!	        - benutze MEINE doors\nXegor		- ISDN suxx !\nHunk Papa	- Ich hoffe ihr seid gut von der Radwar nach hause gekommen\nSak		- Moin!\nH2O		- Du kannst meinen Account erstmal deleten, da ich momentan null\n                  callen kann ... sorry\nLenny Dee       - Sorry fuer die wenigen calls, aber fernzone suxx ultimativ !\n                  danke auch fuer die ideen, etc.\nExhorder^Horny	- Man sieht sich und net so viel saufen old friends\nJazy            - Good Luck with ISDN ...\nMogue           - Mach mir mal''n paar asciis\n','\n',char(10)),NULL,'auto-added',38165,6,0,NULL,NULL,'hf_dpg','scan',1780048539);
INSERT INTO door_catalog VALUES('hf_fans','HF-FANS.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HF-FANS.LHA',NULL,'XIM','.   _____         ___________       ______',NULL,'dRAGON!','HF',':  /   _/_________\____  ___/______|     / ¦ /  __       /     ______    \_   |   _/''95 |/____/      /________________/    |____\',replace('.   _____         ___________       ______\n:  /   _/_________\____  ___/______|     /\n¦ /  __       /     ______    \_   |   _/''95\n|/____/      /________________/    |____\\n|     \_____/                /_____|-dGN!\n|        - hEllFiRE AMiEXPRESSiON -\n|\n|    fORCE-ANSi v1.o fOR /X bY dRAGON!\n|\n| tHE sMARtESt SOlUtiON tO ENfORCe AN ANSi-\n| ONlY bbS ...\n`--------------------------- ---  --  -   -\n','\n',char(10)),'FANSi.guide',replace('@DATABASE Force Ansi v1.o\n@$VER Force Ansi Doc v1.o (8.1.95)\n@author dRAGON!/hEllfiRE^iNCAl\n@WIDTH 80\n\n@NODE main "PerLOGICLog Documentations"\n\n                        \n                                HEllFiRE AMiEXPRESSiON\n\n       .----------------------------------------------------------------------\n       |   @{"   INtROdUCtiON   " LINK "Introduction"}     @{"    DiSClAiMER    " LINK "Disclaimer"}\n       |\n       |   @{"    hOW tO USE    " LINK "HOW TO USE"}     @{"  hOW tO iNStALL  " LINK "INSTALLATION"}\n       |\n       |   @{"     CREdiTS      " LINK "CREDITS"}     @{"     GREEtiNGS    " LINK "GREETINGS"}\n       `----------------------------------  --  -     -\n@ENDNODE\n\n@NODE "Introduction"\n\nWelcome to another HEllFiRE AMiEXPRESSiON production. Anyway this one is not\na real innovative door, but it was requested by some sysops, so that I did it.\n\nThis Release is for those sysops, who only want to have a ansi-board. This\nis definetly the smartest way to do this, as this release contains :\n\n- a "M"-replacement, enabling switching\n- a ANSI-door let''s you only choose between ANSI and ANSI QUICK\n\nHave Fun^C U on RADWAR X, dRAGON!\n\nAnyway prepare yourself for a whole bunch of HAX releases in the near future !\n\n@ENDNODE\n\n@NODE "Disclaimer"\n\nTHIS PRODUCTION IS PROVIDED "AS IS" WITHOUT ANY WARRANTY OF ANY KIND.\nTHE AUTHOR IS NOT RESPONSIBLE FOR ANY WRONG OR BAD USE OF ALL INFORMATION, \nSOFTWARE AND DATA PUBLISHED WITHIN THIS RELEASE. THE ENTIRE RISK OF USING\nANYTHING INCLUDED INHERE DESPITE THE ACCURACY AND RELIABILITY OF COMPLETING\nTHIS IS ON THE USER. SHORTLY : YOU USE IT ON YOUR OWN RISK.\nI PUT MUCH INTO THIS PROGRAM, BUT IT IS ALWAYS IMPOSSIBLE TO ENSURE A 100%\nBUG-FREE PROGRAM.\n\n@ENDNODE\n\n@NODE "HOW TO USE"\n\n\n@ENDNODE\n\n@NODE "CREDITS"\n\n                           All Coding by dRAGON!\n\n@ENDNODE \n\n@NODE "GREETINGS"\n\n                          Greetings fly out to :\n\n\nlenny dee, perfection, jazy, shadowolf, voyage, sam, jms, maxwell, siriax,\nrichard23, pyro, messiah, mogue, slime, h2o, bill^ted, deathknight, kingpin\nrave, john sinclair, trooper, jazz, touchstone, all HF and INCAL POSSe \nMembers and the rest I forgot ...\n\n\n@ENDNODE\n\n@NODE "INSTALLATION"\n\nJust create 2 icons for the ANSI and for the M door.\n\nThe ANSI icon must be in the syscmd drawer executing "ANSI.X"\n\nThe M door should be in the BBSCMD drawer executing "fansi.x"\n\n@ENDNODE\n','\n',char(10)),NULL,NULL,10838,5,0,NULL,NULL,NULL,'scan',1780048539);
INSERT INTO door_catalog VALUES('hf_faup','HF-FAUP.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HF-FAUP.LHA',NULL,'XIM','.   _____         ___________       ______',NULL,'dRAGON!','HF',':  /   _/_________\____  ___/______|     / ¦ /  __       /     ______    \_   |   _/''95 |/____/      /________________/    |____\',replace('.   _____         ___________       ______\n:  /   _/_________\____  ___/______|     /\n¦ /  __       /     ______    \_   |   _/''95\n|/____/      /________________/    |____\\n|     \_____/                /_____|-dGN!\n|        - hEllFiRE AMiEXPRESSiON -\n|\n|    fORCE-ANSi v1.¹ fOR /X bY dRAGON!\n|\n| tHE sMARtESt SOlUtiON tO ENfORCe AN ANSi-\n| ONlY bbS ...\n`--------------------------- ---  --  -   -\n','\n',char(10)),'FANSi.guide',replace('@DATABASE Force Ansi v1.¹\n@$VER Force Ansi Doc v1.¹ (8.1.95)\n@author dRAGON!/hEllfiRE^iNCAl\n@WIDTH 80\n\n@NODE main "Force Ansi Documentations"\n\n\n                    ___________________________________\n                   /   _/     /_____      /     /     /\n                  /   __     /           /_         _/\n                 /____/_____/_____/_____/_____/_____/\n  \n                hAX! - hEllFiRE AMiEXPRESSiON iS bACk WiTh\n\n                     FORCe ANSi v1.¹ bY dRAGON/hf^iCl\n\n       .----------------------------------------------------------------------\n       |   @{"   INtROdUCtiON   " LINK "Introduction"}     @{"    DiSClAiMER    " LINK "Disclaimer"}\n       |\n       |   @{"   REQUiREMENtS   " LINK "REQUIREMENTS"}     @{"  hOW tO iNStALL  " LINK "INSTALLATION"}\n       |\n       |   @{"     CREdiTS      " LINK "CREDITS"}     @{"    OThER tOOlS   " LINK "OTHER TOOLS"}\n       |\n       |   @{"     HiStORY      " LINK "HISTORY"}     @{"     GREEtiNGS    " LINK "GREETINGS"}\n       `----------------------------------  --  -     -\n@ENDNODE\n\n@NODE "Introduction"\n\nWelcome to another hAX! production, again coded by dRAGON . This one\nis just another little Update of my force-ansi release v1.o. \n\nFor those who don''t know what force-ansi is about ...\n\nUsusally you can select between Ansi-(Quick) or NoAnsi-(Quick) logging on to an\n/X board. Anyway some sysops told me, that they did not want people to log on\nwithout ansi-colors, as they are very proud about their stylish (huhu) ansi\noutput.\n\nThe Doors included in this release disable the monochrom-mode for the user.\n\n- The Ansi door let''s him/her only choose between Ansi and Ansi Quick .\n- The M door just outputs, that the bbs only supports Ansi output.\n\nHave fun - if you have any troubles/suggestions or ideas contact me on \n\n- TEMPLE OF DREAMS\n- ON THE RUN\n\ndRAGON/hAX^iCl\n\nAnyway prepare yourself for a whole bunch of HAX releases in the near future !\n\n@ENDNODE\n\n@NODE "Disclaimer"\n\nTHIS PRODUCTION IS PROVIDED "AS IS" WITHOUT ANY WARRANTY OF ANY KIND.\nTHE AUTHOR IS NOT RESPONSIBLE FOR ANY WRONG OR BAD USE OF ALL INFORMATION, \nSOFTWARE AND DATA PUBLISHED WITHIN THIS RELEASE. THE ENTIRE RISK OF USING\nANYTHING INCLUDED INHERE DESPITE THE ACCURACY AND RELIABILITY OF COMPLETING\nTHIS IS ON THE USER. SHORTLY : YOU USE IT ON YOUR OWN RISK.\nI PUT MUCH INTO THIS PROGRAM, BUT IT IS ALWAYS IMPOSSIBLE TO ENSURE A 100%\nBUG-FREE PROGRAM.\n\n@ENDNODE\n\n@NODE "Requirements"\n\nThis doors should run with any Amiga with an installed /X and a installed\nAEDoor.library. Anyway this was only tested on /X 4.8 and /X 3.9 - perhaps\nit works also on /X-clones like Sigmaexpress - tell me !\n\n\n@ENDNODE\n\n@NODE "Credits"\n\n                       ASM-afternoon code by dRAGON\n\n                       AEDoor.library by SYNtAX/WOt\n\n                              MUSiC SUPPORT:\n\n                                WUtANG ClAN\n\n                                  KRS ONE\n\n                                BOB MARLEY\n\n                              JERU THE DAMAJA\n\n                                  MC RENE\n\n                             ABSOLUTE BEGINNER\n@ENDNODE \n\n\n@NODE "Installation"\n\nJust create 2 icons for the ANSI and for the M door.\n\nThe ANSI icon must be in the syscmd drawer executing "ANSI.X"\n\nThe M door should be in the BBSCMD drawer executing "fansi.x"\n\n@ENDNODE\n\n@NODE "Other Tools"\n\n               Other Previously released tools by dRAGON are\n\n- several versions of dGNCOMMENt\n- fANSi v1.o\n- several versions of mcDiz\n- a DMS-Win Interface\n\n\n@ENDNODE\n\n@NODE "History"\n\n                           History of force-ansi\n\n- v1.o first release\n\n- v1.¹ UPDATE ! Selection does not appear when you LOGON SYSOP_LOCAL.\n\n@ENDNODE\n\n@NODE "Greetings"\n\n                          Greetings fly out to :\n\n\nlenny dee, perfection, jazy, shadowolf, voyage, sam, jms, maxwell, siriax,\nrichard23, pyro, messiah, mogue, slime, h2o, bill^ted, deathknight, kingpin\nrave, john sinclair, trooper, jazz, touchstone,exhorder, horny, hunkpapa,sak\ngonzo, maz!,siegel all HF and INCAL POSSe Members and the rest I forgot ...\n\n\n@ENDNODE\n','\n',char(10)),NULL,NULL,20885,6,0,NULL,NULL,NULL,'scan',1780048539);
