INSERT INTO door_catalog VALUES('hf_mcdb','HF-MCDB.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HF-MCDB.LHA','dGNCOMMENt','XIM','dGNCOMMENt',NULL,NULL,'HF',':  /   _/_________\____  ___/______|     / ¦ /  __       /     ______    \_   |   _/''95 |/____/      /________________/    |____\',replace('.   _____         ___________       ______\n:  /   _/_________\____  ___/______|     /\n¦ /  __       /     ______    \_   |   _/''95\n|/____/      /________________/    |____\\n|     \_____/                /_____|-dGN!\n|        - hEllFiRE AMiEXPRESSiON -\n|\n|    SUPERdRAGON-COMMENt bUG-fiXEd v2.2\n|\n| BUG iN BULL CREATION REMOVED ...\n|\n`--------------------------- ---  --  -   -\n','\n',char(10)),'comment.cfg.doc',replace(';This is just a docfile for configurating - use the real config file !\n\nNUMB=3				;the number of sysops\nSYS1="dRAGON"			;sysopnames ... same as username!\nSYS2="PERfECtiON"		\nSYS3="ShAdOWOlF"		\nSYS4="SQUIRREL"			\nSYS5="JAZY"\nSYS6="-SLIME!"\nCOM1="SiMPlY tHE bESt"		;commenttexts ...\nCOM2="tHE REAl PERFECt"\nCOM3="NObODY kNOWS"\nCOM4="BERLIN POWER"\nCOM5="JUNKIE"\nCOM6="HOMELESS GUY"\n','\n',char(10)),NULL,'auto-added',17722,10,0,NULL,NULL,'hf_mcdb','scan',1780048539);
