INSERT INTO door_catalog VALUES('hf_sd24','HF-SD24.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HF-SD24.LHA','UnZip','XIM','SnatchDIZ',NULL,NULL,'HF','|   l_\ ___/ ___\  _|__ ___(____)____  ___/ |  _  | _/  \  _|__\   \  __/   \ __/_ _/  \ l__|  l______) \   \____) __)____) _  \_____',replace(' ___  ______    ____        ____      _____\n|   l_\ ___/ ___\  _|__ ___(____)____  ___/\n|  _  | _/  \  _|__\   \  __/   \ __/_ _/  \\nl__|  l______) \   \____) __)____) _  \_____\n===l_____)==l_______)=l____l===l___l___)gEN=\n.-----------------GIVES YA----------------<-\n|                                          |\n|         ---> SnatchDIZ V2.4 <---         |\n|   BEST and QUICKEST file_id extractor!   |\n|  Now able to create /X style listfiles!  |\n| 1oo% highly optimized asm!  Code: rASCAL |\n`->----------------------------------------''\n','\n',char(10)),'SnatchDIZ.guide',replace('@database\n@node main "SnatchDIZ V2.4 docs"\n@{b}     .\n     .                        .                    ____¦\n     :_       __       __     :  __     ·  __      \___|   __        __\n.____| \__ __/  \___ _/  \__  ¦_/  \__  ¦_/  \___ _____:__/  \___ __/  \___.\n|    |    Y         Y      /  |      /  |        Y     |         Y         |\n|    |   .|_____    |   __/ __|   __/ __|     ___|    .|_____    |_____    |\n|. __|   ¦|.   |____|   ¬|_/ ¬Y   ¬|_/ ¬Y.     | |.   ¦|. __|    |.   |____|\n|: \__   :|:   _____):   |   ¦|:   |   ¦|¦  ___| |:   :|: \__  __|:   _____)\n|¦   |   ¤|¦   |   .|¦   |   ||¦   |   ||:  .|   |¦   ¤|¦   |   .|¦   |   .|\n|¤   |    |¤   |   ¦|¤       ·|¤       ·|¤  ¦|   |¤    |¤   |   :|¤   |   ¦|\n|_   |____|______   |_______  |_______  |_   |   |___  |____|_   |______   |\n  \__|    :    \____|  ·NL·\__|      \__| \__|      \__|      \__|    \____|\n     ¦    .         :         ·         .    ¦         :         :\n     ·    ¦         ·         :         :    ·         ¦         ·\n          .         ·                   ·    .                   ·@{ub}\n             - EVEN GOD CONCEDED WHEN HE KNEW WE WERE ABOUT -\n\n                            HELLFIRE PRESENTS\n\n                 @{fg highlight}SnatchDIZ V2.4 - © by rASCAL on 27.11.95@{fg text}\n\n			    @{"    Purpose     " link 1}\n			    @{"     Usage      " link 2}\n			    @{"  Requirements  " link 3}\n			    @{"   Greetings    " link 4}\n			    @{"    History     " link 5}\n\n                 @{b}kEEP tHE aMIGA aLIVE aND ... lEGALIZE iT!@{ub}\n\n@endnode\n@node 1 "What the fuck..."\n\nSnatchDIZ  is  another  FILE_ID.DIZ extractor for the Shell or for use with\nany bbs-system.  Features:\n\n - LHA-, LZX-, ZIP-, DMS-, EXE-, GIF-, TXT-support\n - /X style listfile generation\n - SnatchDIZ is smaller than 3 KB and faaaaaaaaaaaaaaaaaaaast (1oo% asm)!\n - great code: SnatchDIZ does not produce HITS like WhaDIZ, SpeeDIZ etc.\n - reentrant (can be made resident)\n - good error handling: no problems with empty files or something\n\n-=> Use SnatchDIZ instead of all the other crap floating around!\n@endnode\n@node 2 "It''s easy..."\n\nUsage: SnatchDIZ FILE/A,S=SUPPRESS/S,LF=LISTFILE/K\n==================================================\n\nexample 1:  "SnatchDIZ dh0:down/PPLAY41.LZX S" will give you\n\n--------------------------------------\nPower Player 4.1 Final Omega Version\n* Latest Update! *\n--------------------------------------\n\nThis extracts and shows the file_id.diz and suppresses the credits and the\nfiletype indicator.\n\n                            ------------------\n\nexample 2:  "SnatchDIZ dh0:down/!s-w&f.lha S LF ram:listfile" will show you\nthe  file_id.diz  and add it to the listfile ram:listfile.  If ram:listfile\ndoes not exist it will be created.\n\nThe listfile looks like this:\n\n------------------------------------------------------------------------------\n!s-w&f.lha               37137     __/\____/\____/\____:_/\___/\____/\___/\__ \n                                   \  ___\_ _____ ___/ |  /___ ___\  ____  __\ \n                                  _/\_ \ /  |_/  __)/  l_ \/  __)_/\_ \ |  |\/ \n                                  \     \   ` \  l  \      \  l  \     \|  |lr\n                                  /_____/____ /_____/__/\__/_____/_____/l__!d \n                                  ======[ sCENESt pARTY cONTRiBUTiON ]========\n                                  -                                          -\n                                  -       wATER & fIRE - first place         -\n                                  -                                          -\n                                  -     a small *40kb* intro by tHERAPY      -\n                                  ==============================[09/04/95]====\n------------------------------------------------------------------------------\n\nIf  you  want to create a listfile of an entire directory, use the AmigaDOS\nscript SPat, which is distributed with every Amiga since OS 2:\n\nSPat SnatchDIZ dh0:down/#? lf ram:listfile\n\nFor maximum speed you should make SnatchDIZ resident.\n\n                            ------------------\n\nWARNING: - SnatchDIZ is cli-only so don''t start from Workbench!\n@endnode\n@node 3 "You got this crap..."\n\nYou need:\n\n - an AMIGA w/Kick 2.04+ (as always).\n - the lha-, lzx- and UNzip-executable placed in your path.\n   A working UNzip is included in the SnatchDIZ-archive.\n\nThat''s it.\n@endnode\n@node 4 "Hallöle to..."\n\n                          all the HELLFiRE guys!\n                       SHOOT (boom biddy bye bye...)\n                                 CAFFEiNE\n                                   OMEN\n        STEELER and the rest/PHANTASM (thanks for the bug reports)\n                                Flake/TRSI\n                               MAVE/CRYSTAL\n@endnode\n@node 5 "Versions..."\n\nV0.9:	not released but seems to work properly.\n\nV1.0:	1st release, 31.3.95 (CAFFEINE)\n	- added filetype indicator and the SUPPRESS option.\n\nV2.0:	2nd release, 19.4.95 (SUPREME)\n	- added own routine for search in DMSs (MUCH FASTER than DMS VIEWDIZ)\n	- optimzed search in executables A LOT!\n\nV2.1:	(no public release)\n	- added own routine for search in GIFs (MUCH FASTER than GIFDESC)\n	- SnatchDIZ is now reentrant and can be made resident (PURE option)\n	- removed KEEPDIZ option because it was unnecessary at all\n	- now checks if dos.library is >= V36\n	- no longer crunched. V2.0 sometimes crashed on 040 systems due to\n	  the used packer (CrunchMania V1.9)\n\nV2.2:	3rd release, 19.7.95 (SHOOT) :-)\n	- fixed bug with filenames containing spaces/wildcards\n	- I was told SnatchDIZ even handles JPGs, check it out yourself\n\nV2.3:	4th release, 17.8.95\n	- added /X style listfile generation\n	- fixed small bugs concerning resident ability\n\nV2.4:	5th release, 27.11.95 (HELLFiRE!)\n	- fixed bug with file_ids longer than 44*15 chars\n	- fixed bug with small text-files that could crash the system\n	- improved and bugfixed listfile generation (illegal file_ids are\n	  now formated as good as possible)\n@endnode\n','\n',char(10)),NULL,'auto-added',56951,5,0,NULL,NULL,'hf_sd24','scan',1780048539);
INSERT INTO door_catalog VALUES('hf_sd28','HF-SD28.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HF-SD28.LHA','unrar','XIM','SnatchDIZ',NULL,NULL,'HF','|   l_\ ___/ ___\  _|__ ___(____)____  ___/ |  _  | _/  \  _|__\   \  __/   \ __/_ _/  \ l__|  l______) \   \____) __)____) _  \_____',replace(' ___  ______    ____        ____      _____\n|   l_\ ___/ ___\  _|__ ___(____)____  ___/\n|  _  | _/  \  _|__\   \  __/   \ __/_ _/  \\nl__|  l______) \   \____) __)____) _  \_____\n===l_____)==l_______)=l____l===l___l___)1997\n.-----------------GIVES YA----------------<-\n|                                          |\n|         ---> SnatchDIZ V2.8 <---         |\n|   BEST and QUICKEST file_id extractor!   |\n|                                          |\n`->---------------------------------rASCAL-''\n','\n',char(10)),'SnatchDIZ.guide',replace('@database\n@node main "SnatchDIZ V2.8 docs"\n@{b}     .\n     .                        .                    ____¦\n     :_       __       __     :  __     ·  __      \___|   __        __\n.____| \__ __/  \___ _/  \__  ¦_/  \__  ¦_/  \___ _____:__/  \___ __/  \___.\n|    |    Y         Y      /  |      /  |        Y     |         Y         |\n|    |   .|_____    |   __/ __|   __/ __|     ___|    .|_____    |_____    |\n|. __|   ¦|.   |____|   ¬|_/ ¬Y   ¬|_/ ¬Y.     | |.   ¦|. __|    |.   |____|\n|: \__   :|:   _____):   |   ¦|:   |   ¦|¦  ___| |:   :|: \__  __|:   _____)\n|¦   |   ¤|¦   |   .|¦   |   ||¦   |   ||:  .|   |¦   ¤|¦   |   .|¦   |   .|\n|¤   |    |¤   |   ¦|¤       ·|¤       ·|¤  ¦|   |¤    |¤   |   :|¤   |   ¦|\n|_   |____|______   |_______  |_______  |_   |   |___  |____|_   |______   |\n  \__|    :    \____|  ·NL·\__|      \__| \__|      \__|      \__|    \____|\n     ¦    .         :         ·         .    ¦         :         :\n     ·    ¦         ·         :         :    ·         ¦         ·\n          .         ·                   ·    .                   ·@{ub}\n             - EVEN GOD CONCEDED WHEN HE KNEW WE WERE ABOUT -\n\n                            HELLFIRE PRESENTS\n\n                 @{fg highlight}SnatchDIZ V2.8 - © by rASCAL on 22.06.97@{fg text}\n\n			    @{"    Purpose     " link 1}\n			    @{"     Usage      " link 2}\n			    @{"  Requirements  " link 3}\n			    @{"   Greetings    " link 4}\n			    @{"    History     " link 5}\n			    @{"    Pick it     " link 6}\n\n                 @{b}kEEP tHE aMIGA aLIVE aND ... lEGALIZE iT!@{ub}\n\n@endnode\n@node 1 "What the fuck..."\n\nSnatchDIZ  is  another  FILE_ID.DIZ extractor for the Shell or for use with\nany bbs-system.  Features:\n\n - LHA-, LZX-, ZIP-, RAR-, XPK-, DMS-, EXE-, GIF-, TXT-support\n - /X style listfile generation\n - file_id.diz -> filecomment conversion\n - SnatchDIZ is very small and faaaaaaaaaaaaaaaaaaaast (1oo% assembly)!\n - great code: SnatchDIZ does not produce HITS like WhaDIZ, SpeeDIZ etc.\n - reentrant (can be made resident)\n - good error handling: no problems with empty files or something\n\n-=> Use SnatchDIZ instead of all the other crap floating around!\n@endnode\n@node 2 "It''s easy..."\n\nUsage: SnatchDIZ FILE/A,S=SUPPRESS/S,LF=LISTFILE/K,D2C=DIZ2COMMENT/S\n====================================================================\n\n@{b}example 1:@{ub}  "SnatchDIZ dh0:down/PPLAY41.LZX S" will give you\n\n--------------------------------------\nPower Player 4.1 Final Omega Version\n* Latest Update! *\n--------------------------------------\n\nThis extracts and shows the file_id.diz and suppresses the credits and the\nfiletype indicator.\n\n\n@{b}example 2:@{ub}  "SnatchDIZ dh0:down/!s-w&f.lha S LF ram:listfile" will show you\nthe  file_id.diz  and add it to the listfile ram:listfile.  If ram:listfile\ndoes not exist it will be created.\n\nThe listfile looks like this:\n\n------------------------------------------------------------------------------\n!s-w&f.lha               37137     __/\____/\____/\____:_/\___/\____/\___/\__ \n                                   \  ___\_ _____ ___/ |  /___ ___\  ____  __\ \n                                  _/\_ \ /  |_/  __)/  l_ \/  __)_/\_ \ |  |\/ \n                                  \     \   ` \  l  \      \  l  \     \|  |lr\n                                  /_____/____ /_____/__/\__/_____/_____/l__!d \n                                  ======[ sCENESt pARTY cONTRiBUTiON ]========\n                                  -                                          -\n                                  -       wATER & fIRE - first place         -\n                                  -                                          -\n                                  -     a small *40kb* intro by tHERAPY      -\n                                  ==============================[09/04/95]====\n------------------------------------------------------------------------------\n\n\n@{b}example 3:@{ub} "SnatchDIZ dh0:down/hf-bl060.lha D2C"\n\nwill show you the file_id.diz and convert it into the filecomment.\n\n\n@{b}HINT:@{ub} SnatchDIZ does NOT directly support wildcards! However you can\n      easily use the script "SPat" which should be in your S: to do that.\n      Look into the script "GenListFile" how that works.\n\n\n@{b}WARNING: - SnatchDIZ is cli-only so don''t start from Workbench!@{ub}\n@endnode\n@node 3 "You got this crap..."\n\nYou need:\n\n - an AMIGA w/Kick 2.04+ (as always).\n - the lha-, lzx-, UNzip- and UNrar-executable placed in your path.\n   A working UNzip and UNrar is included in the SnatchDIZ-archive.\n\nThat''s it.\n@endnode\n@node 4 "Personal greets to..."\n\n                          all the HELLFiRE guys!\n                   SUPREME/SHOOT (boom biddy bye bye...)\n                                LSD GERMANY\n                                 CAFFEiNE\n                                   OMEN\n        STEELER and the rest/PHANTASM (thanks for the bug reports)\n                                Flake/TRSI\n                               MAVE/CRYSTAL\n@endnode\n@node 5 "Versions..."\n\nV0.9:	not released but seems to work properly.\n\nV1.0:	1st release, 31.3.95 (CAFFEINE)\n	- added filetype indicator and the SUPPRESS option.\n\nV2.0:	2nd release, 19.4.95 (SUPREME)\n	- added own routine for search in DMSs (MUCH FASTER than DMS VIEWDIZ)\n	- optimzed search in executables A LOT!\n\nV2.1:	(no public release)\n	- added own routine for search in GIFs (MUCH FASTER than GIFDESC)\n	- SnatchDIZ is now reentrant and can be made resident (PURE option)\n	- removed KEEPDIZ option because it was unnecessary at all\n	- now checks if dos.library is >= V36\n	- no longer crunched. V2.0 sometimes crashed on 040 systems due to\n	  the used packer (CrunchMania V1.9)\n\nV2.2:	3rd release, 19.7.95 (SHOOT) :-)\n	- fixed bug with filenames containing spaces/wildcards\n	- I was told SnatchDIZ even handles JPGs, check it out yourself\n\nV2.3:	4th release, 17.8.95\n	- added /X style listfile generation\n	- fixed small bugs concerning resident ability\n\nV2.4:	5th release, 27.11.95 (HELLFiRE)\n	- fixed bug with file_ids longer than 44*15 chars\n	- fixed bug with small text-files that could crash the system\n	- improved and bugfixed listfile generation (illegal file_ids are\n	  now formated as good as possible)\n\nV2.41:	(no public release, 22.1.96)\n	- slightly improved listfile generation once again\n	- added small dos-script for easier listfile generation\n	- optimized code a bit\n\nV2.5:	(no puplic release, 16.6.96)\n	- added RAR support\n\nV2.6:	6th release, 25.08.96\n	- added diz->filecomment conversion\n	- added return codes (why didnt i do that b4?)\n\nV2.7:	7th release, 02.09.96\n	- GenListFile dos-script now really included (forgot that in V2.6)\n	- improved diz->comment conversion: no more "xxxxxxx" etc.\n	- fixed two small bugs (once again the resident fuck)\n\nV2.8:	8th release, 22.06.97\n	- added XPK support\n	- fixed ZIP extracting (now recognizes uppercase file_ids too)\n	  (thanks to Weetabix from IRC for reporting)\n	- added hint about wildcard usage in the Usage part of this guide\n	  (there is no need for any external program)\n@endnode\n@node 6 "PICK IT..."\n\n                                  PACK IT\n                                FIRE IT UP\n                                COME ALONG\n                       AND TAKE A HIT FROM THE BONG\n                            PUT THE BLUNT DOWN\n                             JUST FOR A SECOND\n                             DONT GET ME WRONG\n                           ITS NOT A NEW METHOD\n                             INHAAAAAAAAAAALE\n                          EXHAAAAAAAAAAAAAAAAALE\n                       JUST GOT AN OUNCE IN THE MAIL\n                     I LIKE A BLUNT OR A BIG FAT CONE\n              BUT MY DOUBLE-BARREL BONG IS GETTING ME STONED\n                                IM SKILL IT\n                            THERES WATER INSIDE\n                               DONT SPILL IT\n                     IT SMELLS LIKE SHIT ON THE CARPET\n                                 STILL IT\n                  GOES DOWN SMOOTH WHEN I GET A CLEAN HIT\n                 OF THE SKUNKY, PHUNKY, SMELLY GREEN SHIT\n                               SING MY SONG\n                            PUFF ALL NIGHT LONG\n                       AS I TAKE HITS FROM THE BONG\n\n                                   Ø¹\n                                  JØ&\n                                  dØØ\n                                 mØØØþ\n                                 mØØØØ\n                                 JØØØØ\n                                 ØØØØØÞ\n         _                      JØØØØØß\n         ¬qw_                   ¢ØØØØØÑ                    _uw"\n          ¬ØØæ_                 ØØØØØØØL                 sµØØ\n            9ØØÑµ_              4ØØØØØØÞ              _ædØØ°\n             ¬0ØØØæw_           ØØØØØØØP           _wWØØØ@¬\n               "HØØØØæ_         ØØØØØØØL         _æØØØØH°\n                ¬¶ØØØØØWw_      ØØØØØØØþ      _gWØØØØØK\n                  ''NØØØØØØw_   ¬ØØØØØØØP    _wØØØØØØH`\n                   ¬¶ØØØØØØØp   dØØØØØØK   gØØØØØØØK\n                     ¬MØØØØØØWµ ¶ØØØØØØ¹ jWØØØØØØM"\n                       "NØØØØØØ&¶ØØØØØØ\æØØØØØØ@"\n                        ¬7ØØØØØØbØØØØØ\dØØØØØ@F\n                           °0ØØØØWØØØ5ØØØØØ0"\n                ¸_  wwæwwwwax_5M@MwØkØØØMÇ_µwwwwµwwµ_  ¸\n       _  wwa&ÑÑNØØØØØØØØØØØØØØþ_ ]ØØ%®$ØØØØØØØØØØØØØØØWØØ&æµw_\n     **MHØØØØØØØØØØØØØØØØØØØØØØØØØ"ØØHØØØØØØØØØØØØØØØØØØØØØØØØØHN**\n         ¬¬°7Æ@@MØØØØØØØØØØØØHØP9¯ Ø¹ ¬9ÆØMØØØØØØØØØØØØM0Ø@Y°¯`\n                  ¯¬¬¬¬""""¬"''     dF      ¯"""""""```¯\n@endnode\n','\n',char(10)),NULL,'auto-added',85770,1,0,NULL,NULL,'hf_sd28','scan',1780048539);
INSERT INTO door_catalog VALUES('hf_sdc21','HF-SDC21.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HF-SDC21.LHA','dGNCOMMENt','XIM','dGNCOMMENt',NULL,NULL,'HF','/ I \_ ___\   /   / ___\__/____  \_ __/''95 /  _  / __)/  /\  /\  _//  \|  /  // __) /   ! /  ! /  / / /  \ |/    |  \  \  !  \',replace('   _ ____________________________________\n  / I \_ ___\   /   / ___\__/____  \_ __/''95\n /  _  / __)/  /\  /\  _//  \|  /  // __)\n/   ! /  ! /  / / /  \ |/    |  \  \  !  \\n\___! \____\____\_ __/ |\____|  |\__\____/\n----|     \-sHy!---|   |-----|  |PreSENtS\n    `------''       `---''     `--''\n        SUPERDRAGONCOMMENT (/X) 2.2\n','\n',char(10)),'comment.cfg.doc',replace(';This is just a docfile for configurating - use the real config file !\n\nNUMB=3				;the number of sysops\nSYS1="dRAGON"			;sysopnames ... same as username!\nSYS2="PERfECtiON"		\nSYS3="ShAdOWOlF"		\nSYS4="SQUIRREL"			\nSYS5="JAZY"\nSYS6="-SLIME!"\nCOM1="SiMPlY tHE bESt"		;commenttexts ...\nCOM2="tHE REAl PERFECt"\nCOM3="NObODY kNOWS"\nCOM4="BERLIN POWER"\nCOM5="JUNKIE"\nCOM6="HOMELESS GUY"\n','\n',char(10)),NULL,'auto-added',17519,12,0,NULL,NULL,'hf_sdc21','scan',1780048539);
