INSERT INTO door_catalog VALUES('hf_wall','HF-WALL.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HF-WALL.LHA','firewall','XIM','firewall',NULL,'Moby','HF','/ I \_ ___\   /   / ___\__/____  \_ __/ /  _  / __)/  /\  /\  _//  \|  /  // __) /   ! /  ! /  / / /  \ |/    |  \  \  !  \',replace(replace('   _ ____________________________________\r\n  / I \_ ___\   /   / ___\__/____  \_ __/\r\n /  _  / __)/  /\  /\  _//  \|  /  // __)\r\n/   ! /  ! /  / / /  \ |/    |  \  \  !  \\r\n\___! \____\____\____/ |\____|  |\__\____/\r\n----|     \--------|   |-----|  |PreSENtS\r\nFire Wall v1.0 Absolutly the best /X wall\r\n  coded by Moby / Hellfire /X division\r\n-----------------------------------------\r\n','\r',char(13)),'\n',char(10)),'FireWall.doc',replace('                   _ ____________________________________\n                  / I \_ ___\   /   / ___\__/____  \_ __/\n                 /  _  / __)/  /\  /\  _//  \|  /  // __)\n                /   ! /  ! /  / / /  \ |/    |  \  \  !  \\n                \___! \____\____\____/ |\____|  |\__\____/\n                    |_____\        |___|     |__|\n\n                                /X Division\n\n                                 Presents\n\n                               FireWall v1.0\n\n                                    By\n\n                                  Moby/HF\n\n\n--Introduction\n\nI made this wall because no wall''s consists ANY nice design nowadays, and, we\nwanted something to release for the almost dead /X division, so.. Here it is.\nBesides, many SysOp''s use fastwall, wich can give you a nice little guru..\nThis door is 100% error free, guaranteed.\n\n--The design\n  ____________________\n./ ___\__/____  \_ __/__ __.----------------------------------._ ___ ___ ___ __\n|   _//  \|  /  // __) _|__| Fire Wall v1.0 (c) Moby/HF 1996! |_|___|___|___|__\n|   |/    |  \  \  !  \___|`----------------------------------''___|___|___|___|\n|   |\____|  |\__\____/                                                    _|__\n|___|     |__|                                                            |___|\n|___|                                                                      _|__\n__|_                                                                      |___|\n|___|                                                                      _|__\n__|_                                                                      |___|\n|___|                                                                      _|__\n__|_                                                                      |___|\n|___|                                                                      _|__\n__|_                     (With colours, ofcourse)                         |___|\n|___|                                                                      _|__\n__|_                                                                      |___|\n|___|                                                                      _|__\n__|_                                                                      |___|\n|___|                                                                      _|__\n__|_                                                                      |___|\n|___|                                                                      _|__\n__|_                                                                      |___|\n|___|                                                                      _|__\n__|_                                                                      |___|\n|_ _|_ ___ ___ ___ ___ ___ ___ ___ ___ ___ ___ ___ ___ ___ ___ ___ ___ ___ _|__\n__|___|___|___|___|___|___|___|___|___|___|___|___|___|___|___|___|___|___|___|\n\n--Features\n  · Creates a logfile\n  · Users can choose colour\n  · Error free\n  · Coded in 100% ASM\n\n--Logfile\n  Sure, it creates a logfile, b''cause the wall itself doesn''t show any names.\n  The logfile will be put in doors:firewall.log.\n\n--Installation\n  The wall doesn''t require any icons or configuration files, and if you can\n  read this, you should probably be able to install a simple XIM.\n\n\nContact me on most HF boards in europe..\n\n    Thank you for using FireWall, and have a nice day. AJ Over and out.\n\n','\n',char(10)),NULL,'auto-added',7787,1,0,NULL,NULL,'hf_wall','scan',1780048539);
