INSERT INTO door_catalog VALUES('hlm_gutr','HLM_GUTR.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HLM_GUTR.LHA',NULL,'XIM','runlevel.am',NULL,'CHRONOS/HLM--------------','HLM','___|\ ____ ____ .__/\___/|   /\_____/|____ \  |_\    \    \|__. \_  |__/  \  \_ | __/ _/  _/ \ /  \ /  \  |  /  |  \_  \ / \_/  \_',replace('    .                     :           .  ·K·\n ___|\ ____ ____ .__/\___/|   /\_____/|____\n \  |_\    \    \|__. \_  |__/  \  \_ | __/\n_/  _/ \ /  \ /  \  |  /  |  \_  \ / \_/  \_\n\___|   \___/____/____/_______/___/   |____/\n----|____/-----------------------\____|-----\n     GULP +11 TRAINER INCLUDING CRACK! \n-----------DONE BY CHRONOS/HLM--------------','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 03-03-18  TIME: 11:04:23  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',136894,3,0,NULL,NULL,'hlm_gutr','scan',1780048539);
INSERT INTO door_catalog VALUES('hm_brv05','HM-BRV05.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HM-BRV05.LHA','def-cds','XIM','def-cds',NULL,'|','HM','|   \__/\ / \\_/ ////\  ///__/|+33 84257238| |   /\_ //   \_ ////  \////   |¦:.:¦|¦:.:¦:| |  /__// \____//////\  // \/\ |            |',replace('|   _______ _   __ _     _ ___|¦:..:¦|¦:.:¦|\n|   \__/\ / \\_/ ////\  ///__/|+33 84257238|\n|   /\_ //   \_ ////  \////   |¦:.:¦|¦:.:¦:|\n|  /__// \____//////\  // \/\ |            |\n| //   \__/\__/ ¯ ¯  \/ \___/ | Bull Reset |\n| ¯_____ _ __   ___ _   _____ |version  0.5|\n|  \ __////_ \ /__/// _ \ __/ |(/X Utility)|\n|  //  /// __///  // //  \\   |            |\n| / \ ////\\ / \_/ \///¯¯¯ \  |      by    |\n| \  \¯//  \\\__/\__//     /  |    HaReNg  |\n|  ¯¯¯ ¯    ¯        ¯¯¯¯¯¯   |    MaStER  |\n|  + 3 3 - 8 4 2 5 7 2 3 8    |¦:..:¦|¦:.:¦|\n','\n',char(10)),'BullResetV05.Doc',replace('\n                       -=> Bulletin Reset V0.5 <=-\n                           -------------------\n                            by  HaReNg MaStER\n\n                       A LAME TOOL FOR LAME SYSOP!\n\n\n\nIntroduction:\n-------------\n\n	Bulletin Reset (BR) is the lamest tool ever created ! It was only \nmade for lazy sysop (ed: like me!) . As i was really fed up with reseting\nby hand my OLD BULLETTIN , CALLERSLOG , DOORSLOG etc...  I have coded BR!\n\nHow it work ?\n-------------\n\n	BR is a simple CLI command , That delete the file specified with \nFILENAME and create a new file (same name) with a new size of 0 KBytes ! \nThis is useful for all of you , who fastly want to create 0 Kbytes file.\nThis Tool is FAST (68000 asm code) and SYSTEM FRIENDLY .. It should also\nwork as a button command on DOPUS / DIRWORK .\n\nUsage:\n------\n	BR <filename with full path>\n	\nex:	BR BBS:Node1/CallersLog\n\n\nWhy Not:\n--------\n\n	for - Bug Reports\n	    - Chat\n	    - 680xx coding ...	\n	\n=-=-=-=-=-=-=-=-=-> Give our Bbs A Call [!!! only legal !!!] <-=-=-=-=-=-=-=-=-\n\n      ThE ____      __ _     _____     ____ _____       __     _    ®\n         /___/_ /\_/ /_\\  /\\ __/    /___/_\ __ \______\_\   //_____\n        / _/ // \__ //// \/ /// _ __ //   /// \/_/\ ___/ //  /// ___/\n       / /  / \_ _//////\  // \/// // \_ /// /\ \ / \__ / \_// \__ \ \n       \/   \__/ \/////  \/ \__/ ¯¯ \__/// \/  \/ \___/ \___/  /___/ \n                  _   _       __      __  __ ___ __  _   __      \n            _|_  __) __)  __ (__)(__| __)|__  _/ __)__) (__)     \n             |  ___)___)     (__)   |(__  __) / (__ __) (__)     \n                                   \n\n            - Amiga Public Domain (Demos/Tools)     Conference \n            - Amiga Ami-X                           Conference\n            - Amiga 680xx/6888x coding              Conference\n            - Music:                                Conference\n                  - Chip Tunes (c64/protracker/sidmon)\n                  - Techno/Acid/Rave/Hardcore (infos)  \n                  - Midi ZoNe (BrAnD New ZoNe) & ChIp-PrOtRaCkS\n\n               - Sysop: HaReNg-MaStEr - CoSyS: CpT , FoNzY -\n\n=-=-=-=-=-=-=-=-=-> GiveS our Bbs A CaLl [!!! only legal !!!] <-=-=-=-=-=-=-=-=\n','\n',char(10)),NULL,'auto-added',33604,5,0,NULL,NULL,'hm_brv05','scan',1780048539);
INSERT INTO door_catalog VALUES('hm_dlv10','HM-DLV10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HM-DLV10.LHA','def-cds','XIM','def-cds',NULL,'|','HM','|   \__/\ / \\_/ ////\  ///__/|  PrEsEnTs  | |   /\_ //   \_ ////  \////   |¦:.:¦|¦:.:¦:| |  /__// \____//////\  // \/\ |  DoorList  |',replace('|   _______ _   __ _     _ ___|¦:..:¦|¦:.:¦|\n|   \__/\ / \\_/ ////\  ///__/|  PrEsEnTs  |\n|   /\_ //   \_ ////  \////   |¦:.:¦|¦:.:¦:|\n|  /__// \____//////\  // \/\ |  DoorList  |\n| //   \__/\__/// ¯  \/ \___/ | Version1.0 |\n| ¯_____ _ __  ¯___ _   _____ | (/X Doors) |\n|  \ __////_ \ /__/// _ \ __/ |            |\n|  //  /// __///  // //  \\   |     by     |\n| / \ ////\\ / \_/ \///¯¯¯ \  |   HaReNg   |\n| \_/////  \\\__/\__/ \____/  |   MaStER   |\n|  + 3 3 - 8 4 2 5 7 2 3 8    |¦:..:¦|¦:.:¦|\n','\n',char(10)),'HM-DoorList.Doc',replace('\n                         -=> DoorList V1.0 <=-\n                             -------------\n                           by  HaReNg MaStER\n\n                       A LAME TOOL FOR LAME SYSOP!\n\n             [ ------------ Only Silly Walkers ------------ ]\n             [                                              ] \n             [ CaLl Da FlYiNg CiRcUs BBS at ++33 842.572.38 ]\n             [                                              ]     \n             [ ------------ Only Silly Walkers ------------ ] \n\nIntroduction:\n~~~~~~~~~~~~\n        Congratulation ! You have made the right choice by using this little\nAMI-X-DOOR . Doorlist is the ultimate door shower , the fastest and smallest \never made . It will save your precious memory from beiing filled with nasty\nbytes and your favourite AMI-X-SCREEN from beiing spoiled with bbsad !\n\nInstallation:\n~~~~~~~~~~~~\n        Archive''s content:\n        -----------------\nBBS (DIR)\n  COMMANDS (DIR)   \n    BBSCMD (DIR)\n      OPEN.INFO   \n  DOORS (DIR)    \n    DOORLIST    (DIR)       \n      HM-DOORLIST    EXE\n      HM-DOORLIST    DOC\n      HM-DOORHEAD    TXT\n      HM-DOORLIST    TXT\nLIBS (DIR)\n  AEDOOR.LIBRARY (by SYNTAX/W0T)\n           \n        To install DOORLIST unwarp the archive in ram and copy all the files\nin the right devs or path .         \n\nUsage:\n~~~~~\n        This tool is a little door for AMI-EXPRESS . To run it just type on\nthe menu prompt from /X "open" and it will display the files HM-DOORHEAD.TXT\nHM-DOORLIST.TXT .   \n        Take not that you should not raname the file HM-DOORLIST.TXT and the\nfile HM-DOORHEAD.TXT otherwise the door will be unable to load the files and\nby the way you should not change the location (path) from these files.   \n        This version is hardpath coded so that 1.3 users could use it , the\nupcoming V1.1 will supress all hardpath. \n\nError(s):\n~~~~~~~~\n1> Error: File Not Found...\n   ------------------------\n   Read carefully the above lines and it should not appen again ! \n  \n\nHistory:\n~~~~~~~\n           [V0.1-V0.9]                 Not realised!\n           [V1.0]                      First Release\n\nEnhancement:\n~~~~~~~~~~~\n           No more Hard Path\n\nAlso released:\n~~~~~~~~~~~~~\n           BulletinReset V0.5	\n           UserList V1.0\n           LogArch V1.0\n           PwFail V0.1\n\nTo be Released:\n~~~~~~~~~~~~~~\n           AmiLoG\n           UserMaintenance   \n           UserList V1.1\n           PwFail V1.0\n\nWhy Not:   FoR AnY rEaSOn CalL My BoArD ... AmiX Coders Are Welcome !\n~~~~~~~\n\n__/\____/\__ __/\__ __/\__ __/\__ __/\__ __/\__ __/\__ __/\__ __/\____/\__\n\ oO /\    / \    / \    / \    / \    / \    / \    / \    / \    /\ oO /\n/_< _\/_  _\ /_  _\ /_  _\ /_  _\ /_  _\ /_  _\ /_  _\ /_  _\ /_  _\/_ >_\\n  \/    \/     \/     \/     \/     \/     \/     \/_    \/     \/    \/\n__/\__                     HoMe Da FrOg bUdS!      /_/\             __/\__\n\    /   ____      __ _     _____     ____ _____   \_\/__     _   ® \    /\n/_  _\  /___/_ /\_/ /_\\  /\\ __/    /___/_\ __ \______\_\   //_____/_  _\\n  \/   / _/ // \__ //// \/ /// _ __ //   /// \/_/\ ___/ //  /// ___/  \/\n__/\__/ /  / \_ _//////\  // \/// // \_ /// /\ \ / \__ / \_// \__ \ __/\__\n\    /\/   \__/ \/////  \/ \__/ ¯¯ \__/// \/  \/ \___/ \___/  /___/ \    /\n/_  _\          _   _       __      __  __ ___ __  _   __           /_  _\\n  \/      _|_  __) __)  __ (__)(__| __)|__  _/ __)__) (__)            \/\n__/\__     |  ___)___)     (__)   |(__  __) / (__ __) (__) {24Hrs}  __/\__\n\    /               _                 _                    _       \    /\n/_  _\        +..+. /_/\       +.. . ./_/\       +...+ ..  /_/\     /_  _\\n  \/           +.. .\_\/         + .. \_\/         +.+.. . \_\/       \/\n__/\__                                                              __/\__\n\    /      §¥§ØP { HaReNg MaStER }   \   UsR V.Fc 28.8 KÐ§         \    /\n/_  _\      ÇØ''s  {  CpT - FonZy  }   /   0.5 GØ - 28 Mhz PØW©®     /_  _\\n  \/              {   & HaLfAsT   }   \   Åct¦Ves CØNfe®enÇes         \/\n__/\____/\__ __/\__ __/\__ __/\__ __/\__ __/\__ __/\__ __/\__ __/\____/\__\n\ Oo /\    / \    / \    / \    / \    / \    / \    / \    / \    /\ oO /\n/_< _\/_  _\ /_  _\ /_  _\ /_  _\ /_  _\ /_  _\ /_  _\ /_  _\ /_  _\/_ >_\\n  \/    \/     \/     \/     \/     \/     \/     \/     \/     \/    \/\n','\n',char(10)),NULL,'auto-added',37141,4,0,NULL,NULL,'hm_ulv10','scan',1780048539);
INSERT INTO door_catalog VALUES('hm_lav10','HM-LAV10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HM-LAV10.LHA','LhA','XIM','LhA',NULL,'|','HM','|   \__/\ / \\_/ ////\  ///__/|+33 84257238| |   /\_ //   \_ ////  \////   |¦:.:¦|¦:.:¦:| |  /__// \____//////\  // \/\ |            |',replace('|   _______ _   __ _     _ ___|¦:..:¦|¦:.:¦|\n|   \__/\ / \\_/ ////\  ///__/|+33 84257238|\n|   /\_ //   \_ ////  \////   |¦:.:¦|¦:.:¦:|\n|  /__// \____//////\  // \/\ |            |\n| //   \__/\__/ ¯ ¯  \/ \___/ |Log Archiver|\n| ¯_____ _ __   ___ _   _____ | Version1.0 |\n|  \ __////_ \ /__/// _ \ __/ |(/X Utility)|\n|  //  /// __///  // //  \\   |            |\n| / \ ////\\ / \_/ \///¯¯¯ \  |      by    |\n| \  \¯//  \\\__/\__//     /  |    HaReNg  |\n|  ¯¯¯ ¯    ¯        ¯¯¯¯¯¯   |    MaStER  |\n|  + 3 3 - 8 4 2 5 7 2 3 8    |¦:..:¦|¦:.:¦|\n','\n',char(10)),'LogArch.doc',replace('\n                       -=> Log Archiver V1.0 <=-\n                          -------------------\n                           by  HaReNg MaStER \n\n                       A LAME TOOL FOR LAME SYSOP!\n\n             [ ------------ Only Silly Walkers ------------ ] \n             [ CaLl Da FlYiNg CiRcUs BBS at ++33 842.572.38 ]     \n             [ ------------ Only Silly Walkers ------------ ] \n\nIntroduction:\n~~~~~~~~~~~~\n       You have made the right choice by choosing this tool ! It becomes\nnumber 3 in my Lame_Tool_Collection . This tool is based on my old bull-\nreset (v0.5) and the idea comes from my Co-SysOp ''CpT!'' \n       This tool allow you to reset your CALLERSLOG/UDLOG etc.. by creating\na 0-bytes file and backup your previous file in an Lha-Archive. \n\nInstallation:\n~~~~~~~~~~~~\n        Archive''s content:\n        -----------------\n        LogArch      (dir)        \n            Lha            exe\n            LogArchV1.0    exe\n\n        To install this tool copy the LOGARCH (dir) in your BBS:UTILS/ \ndirectory with all the previous file in the directory .\n        \n        Note: - lha MUST be in logarch directory !\n              - (1.3 Users) have to copy the run cmd in C: directory    \nHow it work ?\n~~~~~~~~~~~\n        This tool is a simple cli-command and can be run from your cli\nshell window or from your favourite disk-editor but it could be more \nadvisable to run it with a text-script. \n        This tool is fast (68x00 code)  , small (832 bytes) and totally\nsystem friendly.  \n   \nUsage:\n~~~~~\n        LogArchV1.0 <file with full path> [node]<xx>\n\nex1:    To Erase your callerslog from bbs:node{x}/\n\n        LogArchV1.0 bbs:node{x}/CallersLog 00\n\n        Your node{x}/callerslog file size will fall down to 0 bytes\n        and the old callerslog file will be stored in the file Node00.lha\n        located in BBS:Utils/LogArch/        \n        \n         <xx> Stand for the node number .\n          \n          00  for node00         \n          01  for node01\n          ..\n          .. \n          ..\n          xx  for nodexx   \n        \n      Note:\n      ----\n      You must include two digit after each each logfile.\n      DO NOT WRITE [ Logarchv1.0 bbs:node{x}/doorlog 0 ] !\n\n\nex2:    Text-Script\n\n~~~ Cut Here ~~~\n\nLogArchV1.0 BBS:node{x}/Callerslog xx\nLogArchV1.0 BBS:node{x}/errorlog xx\nLogArchV1.0 BBS:node{x}/doorslog xx\nLogArchV1.0 BBS:node{x}/udlog xx\nLogArchV1.0 BBS:node{x}/... xx\n\n~~~ Cut Here ~~~\n\n       Note:\n       ----\n\n       If the file Nodexx.lha already exsist , this file will be renamed as\nNodexx.lha.bak so that you can keep your old backup. \n       If the file Nodexx.lha.bak already exsist , take note that this file \nwill be deleted but according to me two {x}log filebackup is enough !!!\n\n\nError(s):\n~~~~~~~~\n1> Error: File Not Found...\n   ------------------------\n   obvious , no more comment ... \n  \n\nHistory:\n~~~~~~~\n           [V0.1-V0.9]                 Not realised!\n           [V1.0]                      Private Release\n           [V1.0] {beta}               First Release\n\nEnhancement:\n~~~~~~~~~~~\n           Config File\n\nAlso released:\n~~~~~~~~~~~~~\n\n           BulletinReset V0.5	\n           UserList V1.0\n\nTo be Released:\n~~~~~~~~~~~~~~\n\n           AmiLoG\n           UserMaintenance   \n           UserList V1.1\n\nWhy Not:\n~~~~~~~\n        For     - Bug / ideas Reports\n                - 68xxx Coding\n                - chat\n                - or any reasons ...\n\n__/\____/\__ __/\__ __/\__ __/\__ __/\__ __/\__ __/\__ __/\__ __/\____/\__\n\ oO /\    / \    / \    / \    / \    / \    / \    / \    / \    /\ oO /\n/_< _\/_  _\ /_  _\ /_  _\ /_  _\ /_  _\ /_  _\ /_  _\ /_  _\ /_  _\/_ >_\\n  \/    \/     \/     \/     \/     \/     \/     \/_    \/     \/    \/\n__/\__                     HoMe Da FrOg bUdS!      /_/\             __/\__\n\    /   ____      __ _     _____     ____ _____   \_\/__     _   ® \    /\n/_  _\  /___/_ /\_/ /_\\  /\\ __/    /___/_\ __ \______\_\   //_____/_  _\\n  \/   / _/ // \__ //// \/ /// _ __ //   /// \/_/\ ___/ //  /// ___/  \/\n__/\__/ /  / \_ _//////\  // \/// // \_ /// /\ \ / \__ / \_// \__ \ __/\__\n\    /\/   \__/ \/////  \/ \__/ ¯¯ \__/// \/  \/ \___/ \___/  /___/ \    /\n/_  _\          _   _       __      __  __ ___ __  _   __           /_  _\\n  \/      _|_  __) __)  __ (__)(__| __)|__  _/ __)__) (__)            \/\n__/\__     |  ___)___)     (__)   |(__  __) / (__ __) (__) {24Hrs}  __/\__\n\    /               _                 _                    _       \    /\n/_  _\        +..+. /_/\       +.. . ./_/\       +...+ ..  /_/\     /_  _\\n  \/           +.. .\_\/         + .. \_\/         +.+.. . \_\/       \/\n__/\__                                                              __/\__\n\    /      §¥§ØP { HaReNg MaStER }   \   UsR V.Fc 28.8 KÐ§         \    /\n/_  _\      ÇØ''s  {  CpT - FonZy  }   /   0.5 GØ - 28 Mhz PØW©®     /_  _\\n  \/              {   & HaLfAsT   }   \   Åct¦Ves CØNfe®enÇes         \/\n__/\____/\__ __/\__ __/\__ __/\__ __/\__ __/\__ __/\__ __/\__ __/\____/\__\n\ Oo /\    / \    / \    / \    / \    / \    / \    / \    / \    /\ oO /\n/_< _\/_  _\ /_  _\ /_  _\ /_  _\ /_  _\ /_  _\ /_  _\ /_  _\ /_  _\/_ >_\\n  \/    \/     \/     \/     \/     \/     \/     \/     \/     \/    \/\n','\n',char(10)),NULL,'auto-added',69781,3,0,NULL,NULL,'hm_lav10','scan',1780048545);
INSERT INTO door_catalog VALUES('hm_ulv10','HM-ULV10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HM-ULV10.LHA','def-cds','XIM','def-cds',NULL,'|','HM','|   \__/\ / \\_/ ////\  ///__/|+33 84257238| |   /\_ //   \_ ////  \////   |¦:.:¦|¦:.:¦:| |  /__// \____//////\  // \/\ |            |',replace('|   _______ _   __ _     _ ___|¦:..:¦|¦:.:¦|\n|   \__/\ / \\_/ ////\  ///__/|+33 84257238|\n|   /\_ //   \_ ////  \////   |¦:.:¦|¦:.:¦:|\n|  /__// \____//////\  // \/\ |            |\n| //   \__/\__/ ¯ ¯  \/ \___/ |  UserList  |\n| ¯_____ _ __   ___ _   _____ | Version1.0 |\n|  \ __////_ \ /__/// _ \ __/ |(/X Utility)|\n|  //  /// __///  // //  \\   |            |\n| / \ ////\\ / \_/ \///¯¯¯ \  |      by    |\n| \  \¯//  \\\__/\__//     /  |    HaReNg  |\n|  ¯¯¯ ¯    ¯        ¯¯¯¯¯¯   |    MaStER  |\n|  + 3 3 - 8 4 2 5 7 2 3 8    |¦:..:¦|¦:.:¦|\n','\n',char(10)),'UserList.doc',replace('\n                        -=> Users List V1.0 <=-\n                           -----------------\n                           by  HaReNg MaStER\n\n                       A LAME TOOL FOR LAME SYSOP!\n\n\n\nIntroduction:\n~~~~~~~~~~~~\n\n        Welcome stranger in the deep world of the non-experimented Ami-X\nUsers , welcome to a new lame tool abomination ... LAME-TOOL-COLLECTION!\n        Here comes a new User List (Phweeew another one!!!!!) , with no\nreal innovations (by now) except the speed and the size . \n\n\n        This archive contains:\n                UserListV1.0            EXE             1692\n                UserList_doc            TXT             4159\n\nHow it work ?\n~~~~~~~~~~~\n	\n       UsersList is a simple CLI command that create a Bull(x).Txt with\nsome infos about your users . \nThis Tool is FAST (68000 asm code) and SYSTEM FRIENDLY. You can run \nUserslist from cli but it could be more advisable to include it in your\nlogoff script .\n\nUsage:\n~~~~~\n        Userslist  <user.data with full path> <Bulletin with full path>\n	\nex:     Userslist BBS:user.data BBS:Bulletins/Bullx.Txt\n\n        If the file ''bullx.txt'' does not exist , userlist will create\na file with the specified filename.\n\nErrors:\n~~~~~~\n\n1> "Error While Creating Bulletin !"\n\n    Not enough free memory             --> Reboot your sys to get freemem \nor                       \n    Could Not examine User.data       \n\n2> "datas file not found !"\n\n    Error in datas filename\n\n3> "No OutPut File !"\n\n    You have missed the second arg!    --> Userlist dxx:xxxx dxx:arg\n\n4> "Not a User.Data File !"\n\n    The file You have read is not a user.data file , Retry !\n\nHistory:\n~~~~~~~\n           [V0.1-V0.8]                 Not realised!\n           [V0.9]                      First Release                       \n           [V1.0]                      Second Release\n                               added:  UserData file detection      \n                                       Source Code Optimisation\nEnhancement:\n~~~~~~~~~~~\n           Independent option (!)\n           Independent title banner\n		\n\nAlso released:\n~~~~~~~~~~~~~\n\n           BulletinReset V0.5	\n\nTo be Released:\n~~~~~~~~~~~~~~\n\n           AmiLoG\n           UserMaintenance   \n           UserList V1.1\n\nWhy Not:\n~~~~~~~\n        For     - Bug Reports\n                - 68xxx Coding\n                - chat\n                - or any reasons ...\n\n__/\____/\__ __/\__ __/\__ __/\__ __/\__ __/\__ __/\__ __/\__ __/\____/\__\n\ oO /\    / \    / \    / \    / \    / \    / \    / \    / \    /\ oO /\n/_< _\/_  _\ /_  _\ /_  _\ /_  _\ /_  _\ /_  _\ /_  _\ /_  _\ /_  _\/_ >_\\n  \/    \/     \/     \/     \/     \/     \/     \/_    \/     \/    \/\n__/\__                     HoMe Da FrOg bUdS!      /_/\             __/\__\n\    /   ____      __ _     _____     ____ _____   \_\/__     _   ® \    /\n/_  _\  /___/_ /\_/ /_\\  /\\ __/    /___/_\ __ \______\_\   //_____/_  _\\n  \/   / _/ // \__ //// \/ /// _ __ //   /// \/_/\ ___/ //  /// ___/  \/\n__/\__/ /  / \_ _//////\  // \/// // \_ /// /\ \ / \__ / \_// \__ \ __/\__\n\    /\/   \__/ \/////  \/ \__/ ¯¯ \__/// \/  \/ \___/ \___/  /___/ \    /\n/_  _\          _   _       __      __  __ ___ __  _   __           /_  _\\n  \/      _|_  __) __)  __ (__)(__| __)|__  _/ __)__) (__)            \/\n__/\__     |  ___)___)     (__)   |(__  __) / (__ __) (__) {24Hrs}  __/\__\n\    /               _                 _                    _       \    /\n/_  _\        +..+. /_/\       +.. . ./_/\       +...+ ..  /_/\     /_  _\\n  \/           +.. .\_\/         + .. \_\/         +.+.. . \_\/       \/\n__/\__                                                              __/\__\n\    /      §¥§ØP { HaReNg MaStER }   \   UsR V.Fc 28.8 KÐ§         \    /\n/_  _\      ÇØ''s  {  CpT - FonZy  }   /   0.5 GØ - 28 Mhz PØW©®     /_  _\\n  \/              {   & HaLfAsT   }   \   Åct¦Ves CØNfe®enÇes         \/\n__/\____/\__ __/\__ __/\__ __/\__ __/\__ __/\__ __/\__ __/\__ __/\____/\__\n\ Oo /\    / \    / \    / \    / \    / \    / \    / \    / \    /\ oO /\n/_< _\/_  _\ /_  _\ /_  _\ /_  _\ /_  _\ /_  _\ /_  _\ /_  _\ /_  _\/_ >_\\n  \/    \/     \/     \/     \/     \/     \/     \/     \/     \/    \/\n','\n',char(10)),NULL,'auto-added',34001,3,0,NULL,NULL,'hm_ulv10','scan',1780048545);
