            PARANOID / hUMANS ''94                             |\n+---------------------------------------------------------------------------+\n\n1) wHAT''S iT dO!???\n\n cRAZY lOGOFF v1.O iS jUST a sMALL rEPLACEMENT fOR tHE nORMAL "G" cOMMAND fOR\n lOGGING oFF yOUR bOARD. tHIS iS sMALL, iT wILL gIVE tHE uSERNAME oF tHE dUDE\n lOGGING oFF, hIS aMOUNT OF cALLS, aND tHE nODE hE''S lOGGING oFF oF. iT hAS a\n nICE aSCII lOGO, wHICH i rIPPED fROM oNE oF cOLA''S cOOL cOLLECTIONS! sORRY\n iF yOU aRE pISSED oFF wITH mE nOT aSKING yA mATE, bUT tIME wAS nOT oN mY\n sIDE wITH tHIS dOOR!!! tHE lOGOFF dOOR aLSO hAS a mENU oF thINGS tHE uSER\n cAN dO. wHICH iS sMALL aT tHE mOMENT, bUT wILL bE iMPROVED iN fUTURE vERSIONS.\n (tHIS iS tHE fIRST vERSION!) tHE mENU lET''S tHE uSER lOGOFF (oF cOZ!), sTAY,\n dOWNLOAD yOUR bBS aD, cOMMENT tO tHE sYSOP, vIEW gREETS aND aLSO a HMS bBS\n lIST! tHE cODE iS oPEN fOR aLL tO sEE aS uSUAL! bUT lAMERS, pLEASE dO nOT\n fUCK wITH iT oR cHANGE aNY oF tHE tEXTS oR eLSE! lET oTHERS lEARN fROM tHE\n cODE, wHICH iS sIMPLE, aND gOOD fOR aNYONE iNTERESTED iN lEARNING aREXX!\n\n2) CREDITS!\n\n              aREXX cODING bY : pARANOID / hUMANS\n              cOOL aSCII lOGO : cOLA / ???\n\n3) INSTALLATION!\n\n Ok... tO iNSTALL tHIS jUST cOPY tHE sTUFF tO tHE rELEVANT dIRECTORIES. (iE.\n tHE dIRECTORIES tHEY''RE iN iNSIDE tHE aRCHIVE.. sIMPLE aS hELL.. aLSO, tO\n hAVE a BBS aDVERT wHICH uSERS cAN dOWNLOAD yOU mUST hAVE yOUR bOARD aDVERT\n iN yOUR S: dIRECTORY, aND iT >>>mUST<<< bE cALLED "BOARD.AD".. tHERE sIMPLE!\n\n4) JOINING HUMANS!\n \n Want to join the coolest new crew around? Then you want to join HUMANS! We\n are a very new force on the scene, but already growing fast and strong! We\n want TRADERS/CODERS and anybody else who would like to join, who feel they\n can contribute something to the group! Join us! Traders get a special deal!\n\n          .___.\n         _|   l___._____.__._____ __.________.________._________ _\n _ ______\_  ___  |\_   |  |\_ _ Y  |\_____  |\_  ___ |\_  _____________ _\n   :     Y    Y    Y    |   Y   \ /  Y   ___  Y    Y   Y______  Y      :\n . :......_   |    ._   !   ._   Y   ._   Y   ._   |   ._   Y   .......: .\n   .     sT\__|____| \______| \__|___| \______| \__|___| \______|      .\n \n                        hUMANS - kICKIN'' iN sTYLE!\n \n =+====================================================================+= \n =+= !hUMANS! aRE cURRENTLY lOOKING fOR cOOL nEW mEMBERS! tHE nEW aND =+=\n =+= cOOL cREW oN tHE sCENE cOULD wANT yOU! wE wANT gOOD tRADERS.  wE =+=\n =+= hAVE gOOD dEALS fOR aLL oUR tRADERS!! yOU wILL sIMPLY nEED tO bE =+=\n =+= a fAST aND cOOL tRADER wHO !wILL! uPLOAD tO oUR bOARDS aROUND dA =+=\n =+= fUCKED uP wORLD! aLSO aNYONE eLSE !cOOL! iS wELCOME iN oUR cREW! =+=\n =+= wE aLSO nEED cRACKERS aND sUPPLIERS oN aMIGA aND cONSOLE! yEAAAH =+=\n =+= jUST (r)EPLY fOR fRIENDLY eLITENESS! !jOIN uS! !cALL oUR bOARDS! =+=\n =+====================================================================+=\n\n           .___.\n          _|   l___._____.__._____ __.________.________.________ _\n  _ ______\_  ___  |\_   |  |\_ _ Y  |\_____  |\_  ___ |\_  _____________ _\n    :     Y    /    Y    |   Y   \ /  Y   ___  Y    /   Y______  Y      :\n    :     !    |    !    |   !    Y   !    /   !    |   !    /   !      :\n  . :......_   |    ._   !   ._   |   ._  /    ._   |   ._  /    .......: .\n    .     sT\__|____| \______| \__|___| \______| \__|___| \______|      .\n\n       /\            /\      /\            /\      /\            /\\n      /  \/\  /\/\  /  \/\  /  \/\  /\/\  /  \/\  /  \/\  /\/\  /  \/\\n     /      \/    \/      \/      \/    \/      \/      \/    \/      \\n     \ [tHE bOARDS:]--------[tHE nUMBERS:]----[nDZ:]---[tHE sYSOPS:]  /\n     /                                                                \\n     \      FASTRAX (wHQ)       201-939-eLITE    3     vOYAGER&sNOW!  /\n     /                                                                \\n     \   pSYCHOKINESIS (uSHQ)   318-462-6706     5     rAMBO sAMBO    /\n     /                                                                \\n     \  fORBIDDEN pLANET (iHQ)  +353-1-8208489   2     gREEN bERET    /\n     /                                                                \\n     \       cOITUS (uSHQ)      904-395-6100     2     jERKY & rETI   /\n     /                                                                \\n     \      dISORDER (SHQ)     +46-456-27511     1     mARWIN         /\n     /                                                                \\n     \      oFFSHORE (UKHQ)    +44-534-856292    2     tEX!           /\n      \            /\        /\        /\/\        /\      /\  /\/\  /\n       \/\  /\/\  /  \/\  /\/  \  /\  /    \    /\/  \/\  /  \/    \/\n          \/    \/      \/      \/  \/      \/\/        \/\n','\n',char(10)),NULL,'auto-added',25047,6,0,NULL,NULL,'hms_cl10','scan',1780048545);
INSERT INTO door_catalog VALUES('hms_sa11','HMS-SA11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HMS-SA11.LHA',NULL,'XIM','.___:_._____  _______ ___ :   _____',NULL,'pARANOID','HMS','__ _|   | :    /\/ \_ __ \   \|   \  _/___ \//_|   | |   /.  / \ \_  \   \  ._\___   \ / \_   | |  /  \/   \ |   \ \   |   l/  ø/',replace('     .___:_._____  _______ ___ :   _____\n __ _|   | :    /\/ \_ __ \   \|   \  _/___\n \//_|   | |   /.  / \ \_  \   \  ._\___   \\n  / \_   | |  /  \/   \ |   \ \   |   l/  ø/\n /ø  |___|___/___|l____\|    \|\__l_______//\n/____|---( presents )---l_____\--------mAZ-»\n    sYSOP aVAIL v1.1 bY pARANOID / hUMANS\n \n','\n',char(10)),'AVAIL11.DOC',replace('                                                           ____       ._.\n   ________.________.________.________.________.________._(____)______| |\n __\_    _ |\_    _ |\_    _ |\_    _ |\_    _ |\_    _ |\_    |\_    _ | __\n.::Y     !  Y     !  Y     |  Y     !  Y     |  Y     |  Y      Y     |  Y::.\n.::|     ___|     _  |     |__|     _  |     |  |     !  |      |     !  |sT.\n¯\:|     |::|     |  |     |::|     |  |     |  |        |      |        |:/¯\n  ¯`-----''¯¯`-----^--^-----''¯¯`-----^--^-----^--^--------^------^--------''¯\n           .___.\n          _|   l___._____.__._____ __.________.________.________ _\n  _ ______\_  ___  |\_   |  |\_ _ Y  |\_____  |\_  ___ |\_  _____________ _\n    :     Y    /    Y    |   Y   \ /  Y   ___  Y    /   Y______  Y      :\n    :     !    |    !    |   !    Y   !    /   !    |   !    /   !      :\n  . :......_   |    ._   !   ._   |   ._  /    ._   |   ._  /    .......: .\n    .     sT\__|____| \______| \__|___| \______| \__|___| \______|      .\n\n               pARANOID oF tHE cOOLEST gROUP - hUMANS - rETURNS!\n\n\n+---------------------------------------------------------------------------+\n|                  CRAZY SYSOP AVAiLABLE DOOR V1.1!                         |\n|                                BY:                                        |\n|                         PARANOID / hUMANS ''94                             |\n+---------------------------------------------------------------------------+\n\n1) WHAT''S iT DO!???\n\n Well, Sysop Available Door will check for a sysops chat flag. If the chat\n flag is ON then the user will be shown a little text file, saying that\n you''re around for chatting....  If not, well obviously the door will show\n a text file saying that you''re NOT around!! heheh.. I''ve improved this\n version by adding a little pager. So that if you are available for chatting\n the user will be asked if he/she wants to page you for a chat. So ya can\n even use this for a pager if you want (Replace your "O" command). Nothing\n special in the code, just an improvement over the last version. Check out\n the code if ya want, it''s un-encrypted to prove there''s no backdoors!\n\n2) CREDiTS!\n\n             Arexx coding by: PARANOID / hUMANS\n            Cool Ansis by: ZOLDAN/SCANDAL^ESQUiRE!\n (Hey mate, haven''t chatted with ya since the big busts in Germany!)\n\n3) iNSTALLATiON!\n\n Installation is so damn easy that even you PC owning sysops could do it!!\n hehe.. OKi, simply copy the Dir DOORS/PARANOID/ to your BBS:Doors dir, and\n also copy the avail.info to your BBS:Commands/bbscmd/ Dir.. Boing! Easy!!!\n\n4) SOME USELESS iNFO!\n\n Although SYSOP AVAILABLE comes complete with two text files (AVAIL.TXT and\n UNAVAIL.TXT) which can be used to tell a user if you can be reached or not,\n you can change the text files if you want, diplaying a logo of your name or\n some other stuff.. Or, if you wanna attach the SYSOP AVAILABLE DOOR to a\n bull on your board (eg.LOGON.TXT) you must of course put ~ at the beginning\n of the txt file and then ~CC_AVAIL at the bottom of the text file! If you\n want to do this then you probably do not want a BIG text file saying:\n\n           "Y O   T H E   S Y S O P   I S   A V A I L A B L E !" \n\n To be displayed EVERY time some user logs onto your board! Bcoz it would\n not look so great I think.. :) OKi, so you CAN write a little one line\n text file saying "XXXX iS AVAILABLE FOR CHAT", but you dont have to do\n this!!! Yes, simply delete or rename the two text files (AVAIL.TXT and\n UNAVAIL.TXT) and SYSOP AVAILABLE will automatically place it''s own small\n one line message for you.. Making it cool for bulletins.. \n I''m listening to "MUSIC FOR THE JILTED GENERATION", the latest album from\n The Prodigy, and it is cool.. so buy it!\n\n5) JOINING HUMANS!\n \n Want to join the coolest new crew around? Then you want to join HUMANS! We\n are a very new force on the scene, but already growing fast and strong! We\n want TRADERS/CODERS and anybody else who would like to join, who feel they\n can contribute something to the group! Join us! Traders get a special deal!\n\n          .___.\n         _|   l___._____.__._____ __.________.________._________ _\n _ ______\_  ___  |\_   |  |\_ _ Y  |\_____  |\_  ___ |\_  _____________ _\n   :     Y    Y    Y    |   Y   \ /  Y   ___  Y    Y   Y______  Y      :\n . :......_   |    ._   !   ._   Y   ._   Y   ._   |   ._   Y   .......: .\n   .     sT\__|____| \______| \__|___| \______| \__|___| \______|      .\n \n                        hUMANS - kICKIN'' iN sTYLE!\n \n =+====================================================================+= \n =+= !hUMANS! aRE cURRENTLY lOOKING fOR cOOL nEW mEMBERS! tHE nEW aND =+=\n =+= cOOL cREW oN tHE sCENE cOULD wANT yOU! wE wANT gOOD tRADERS.  wE =+=\n =+= hAVE gOOD dEALS fOR aLL oUR tRADERS!! yOU wILL sIMPLY nEED tO bE =+=\n =+= a fAST aND cOOL tRADER wHO !wILL! uPLOAD tO oUR bOARDS aROUND dA =+=\n =+= fUCKED uP wORLD! aLSO aNYONE eLSE !cOOL! iS wELCOME iN oUR cREW! =+=\n =+= wE aLSO nEED cRACKERS aND sUPPLIERS oN aMIGA aND cONSOLE! yEAAAH =+=\n =+= jUST (r)EPLY fOR fRIENDLY eLITENESS! !jOIN uS! !cALL oUR bOARDS! =+=\n =+====================================================================+=\n\n           .___.\n          _|   l___._____.__._____ __.________.________.________ _\n  _ ______\_  ___  |\_   |  |\_ _ Y  |\_____  |\_  ___ |\_  _____________ _\n    :     Y    /    Y    |   Y   \ /  Y   ___  Y    /   Y______  Y      :\n    :     !    |    !    |   !    Y   !    /   !    |   !    /   !      :\n  . :......_   |    ._   !   ._   |   ._  /    ._   |   ._  /    .......: .\n    .     sT\__|____| \______| \__|___| \______| \__|___| \______|      .\n\n       /\            /\      /\            /\      /\            /\\n      /  \/\  /\/\  /  \/\  /  \/\  /\/\  /  \/\  /  \/\  /\/\  /  \/\\n     /      \/    \/      \/      \/    \/      \/      \/    \/      \\n     \ [tHE bOARDS:]--------[tHE nUMBERS:]----[nDZ:]---[tHE sYSOPS:]  /\n     /                                                                \\n     \      FASTRAX (wHQ)       201-939-eLITE    3     vOYAGER&sNOW!  /\n     /                                                                \\n     \   pSYCHOKINESIS (uSHQ)   318-462-6706     5     rAMBO sAMBO    /\n     /                                                                \\n     \  fORBIDDEN pLANET (iHQ)  +353-1-8208489   2     gREEN bERET    /\n     /                                                                \\n     \       cOITUS (uSHQ)      904-395-6100     2     jERKY & rETI   /\n     /                                                                \\n     \      dISORDER (SHQ)     +46-456-27511     1     mARWIN         /\n     /                                                                \\n     \      oFFSHORE (UKHQ)    +44-534-856292    2     tEX!           /\n      \            /\        /\        /\/\        /\      /\  /\/\  /\n       \/\  /\/\  /  \/\  /\/  \  /\  /    \    /\/  \/\  /  \/    \/\n          \/    \/      \/      \/  \/      \/\/        \/\n','\n',char(10)),NULL,NULL,9256,3,0,NULL,NULL,NULL,'scan',1780048545);
