INSERT INTO door_catalog VALUES('hny_lo12','HNY-LO12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HNY-LO12.LHA',NULL,'XIM','.                              ____',NULL,'KuRGaN/HNY','HNY','_____|   . ______.   ._____________/   /_ \    |   |/  _   |___|     / __  /_   /  \_ \   .   |   \   |   \    / ____/ /____   /',replace('     .                              ____\n_____|   . ______.   ._____________/   /_\n\    |   |/  _   |___|     / __  /_   /  \_\n \   .   |   \   |   \    / ____/ /____   /\n.-\__|   |_______|____\__/_______/_______/-.\n`-uMn|___|aC!------------------------------+\n[Honey /X Clever People] proudly bring you ¦\n- ---- ------- - ------------ ---------- --+\nLogoff v1.2 by KuRGaN/HNY ''n DaRtAGnAn/HNY :\n  Sexy - Action Packed - Cant be missed!   ·\n- -- --- -- ----------- ------- ----- --- -''','\n',char(10)),'Logoff.guide',replace('@DataBase Logoff Documentation\n@Author KuRGaN(aFL/aBS!/CRC)\n@Index Documentation\n\nCopyright © 1995 KuRGaN of hONEY & g-FORCE!\n\n@Remark $VER: Logoff v1.2 by KuRGaN of hONEY & g-FORCE!\n@Remark AmigaGuide DataBase\n\n@node MAIN "Logoff Documentation © 1995 KuRGaN of hONEY & g-FORCE!"\n                                       .________\n.--- __________.      __________ _____ |       /_______.   _____ -------.\n||¯  \         |_______    .    \_    \|      /    _.__|__     /___     |\n|     \        |      /    |     /     \     /    __|    /    /    \_   |\n|      \_______|     /__________/_______\___/___________/_______    / _||\n`--------uMn|_______/aC!--------------------------->   ____________/----''\n\n                            ---[ Presents ]---\n\n		    ¡  __  __ __  ___ ___\n		    l_(__)(_j(__)l-- l--   Version 1.2\n		           _¡\n\n                    Coded by KuRGaN of hONEY & g-FORCE!\n                    \n               @{"  Introduction  " Link Description}        @{"  Requirements  " Link Requirements}\n               @{"  Installation  " Link Installation}        @{"    Contact     " Link Contact}         \n               @{"  Honey BBS''s   " Link Honey-BBS}        @{"   Greetings    " Link Greetings}\n@endnode\n\n@node Description "Logoff Description"\n                        ·D·E·S·C·R·I·P·T·I·O·N·\n\n             Logoff was coded by KuRGaN of hONEY & g-FORCE!\n              All ascii''s by dARtAGnAN of hNY/wL!/gF!/oTT\n\n    This Logoff door is a replacement for the normal Goodbye Command\n          of AmiExpress ''G'' but several options. They include:\n                    \n                   ·\n                   :\n            -  - --+--  - - \n                   |\n                   |   Y - Yes, logoff (Same as <CR>) \n                   :   N - No, go back to BBS           .\n                   .   R - Relogon                      :\n                       C - Comment to sysop             |\n                       ? - Help Screen                  | \n                                                 -  - --+--  - -\n                                                        :\n                                                        .\n@endnode\n\n@node Installation "Logoff Installation"\n                       ·I·N·S·T·A·L·L·A·T·I·O·N·\n\nCopy all files which are in the ''BBS'' directory of the archive\ninto your bbs directory.\n\nContents of archive:\n[======================]\n BBS/ Commands/ BBSCmd/      G.info\n      Doors/    hONEY/       Logoff1.2\n                             Logoff.Guide\n[======================]\n\nJust copy the directory hONEY to your DOORS: directory\nand copy the G.info into your BBS:Commands/BBSCMD directory.\n\n                      Then Hit G at the Main prompt!\n\n@endnode\n\n@node Requirements "Requirements"\n                        ·R·E·Q·U·I·R·E·M·E·N·T·S·\n\n             Any Amiga using WB2.04+ and AmiExpress v3.xx+\n\n                                Easy eh!\n\n@endnode\n\n@node Contact "How to contact KuRGaN of hONEY & g-FORCE!"\n                           ·C·O·N·T·A·C·T·\n\n\n   nOTA bENE               [hONEY WHQ!]               +46-8-58166565\n   fINAL iMPACT            [hONEY SHQ!]               +46-54-159771\n   mIDNITE                 [hONEY OZHQ]               +61-7337-97161\n\n  contact me at one of the above honey boards or catch me on the net!\n\n@endnode\n\n@node Greetings "Greetings"\n                           ·G·R·E·E·T·I·N·G·S·\n\n                              (In no order)\n\n     dARtAGnAN/hny/wl!/gf!/ott, cOUNT zERo/wl!/hny/ogn/sht, qEN/hny\n   wARHAMMER/hny, DiSTLER/hny, u-MAN/hny/wl!/gf!, H20/hny/sad, S/\L-1\n   lORD/abs!, sCORPIK/abs!, 243/ryl/crx/n&b/flt, pSYCHE/dvs, fELON/dvs\n\n\n            and of coz all the hONEY and g-FORCE! members!\n\n\n if u are not there then sorry but I am too lazy to write them all down\n\n@endnode\n\n@node Honey-BBS "Honey BBS''s WorldWide!"\n      cG!_______.\n._ _____.)      |___________ ________ .______._____________ _______.______.\n|     __¦_______|_          \_    _  \|      |   _._      / \      ¦      |\n|      __________/   dLT     /    \\  \      |    ¦/_____/__ \_____|_     |\nl_______l_______|___________/_______\________|_____________//______|/_____|\n                 __..____                          ____..__\n              <÷>\_||___/     CALL OUR BOARDS:     \___||_/<÷>\n       ...                                                        ...\n       :   nota bene           [WHQ] +46-8-58166565   [warhammer]   :\n       :   the sLammer         [EHQ] +46-8-6230196      [distLer]   :\n       :   finaL impact        [SHQ] +46-54-159771        [u-man]   :\n       :   maximum anarchy     [SHQ] +46-47-622003          [ziz]   :\n       :   receiver            [SHQ] +46-21-55745    [bLack Line]   :\n       :   bumbLe bee land     [NHQ] +47-66-794789       [baffLe]   :\n       :   midnite             [OHQ] +61-7337-97161  [count-zero]   :\n       :   raveLand            [GHQ] +49-7128-3511          [h2o]   :\n       :   apocaLypse now      [GHQ] +49-9723-8402   [%styLewars]   :\n       :   shining chrome      [AHQ] +43-662-453364      [psycho]   :\n       :   the payoff          [DHQ] +31-70-3205418      [diabLo]   :\n       :..                                                        ..:\n\n\n@endnode\n\n/*\n** Yep, KuRGaN here, this tool is fucking better than the utter\n** crap you''re using right now!\n** Wanna know why? COZ IT''S A FUCKING...\n** hONEY - g-FORCE! Production\n*/\n','\n',char(10)),NULL,NULL,15874,5,0,NULL,NULL,NULL,'scan',1780048545);
INSERT INTO door_catalog VALUES('hny_pc12','HNY-PC12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HNY-PC12.LHA','Privilege-Checker','XIM','.                              ____',NULL,'Distler','HNY','_____|   . ______.   ._____________/   /_ \    |   |/  _   |___|     / __  /_   /  \_ \   .   |   \   |   \    / ____/ /____   /',replace('     .                              ____\n_____|   . ______.   ._____________/   /_\n\    |   |/  _   |___|     / __  /_   /  \_\n \   .   |   \   |   \    / ____/ /____   /\n.-\__|   |_______|____\__/_______/_______/-.\n`-uMn|___|aC!------------------------------''\n.------------------------------------------.\n|          Privilege Checker v1.2          |\n¦ Status Checker For /X 4.xx With Awesome! ¦\n| Features, Check It Out By Distler of hny |\n`------------------------------------------''\n','\n',char(10)),'Privilege-Checker.Doc',replace('\n\n      .                     [  h   o   n   e   y  ]\n      |     .     _ ___________ ._____ .___  _ _________    ......\n     _|_____|______  __   __   \|     \|   \  __  _____/    ::::::  ......\n    _\________     \_      /    \_     \    \_    ___/______`:::::..::::::\n    \       |/      /     /      /  \   \    /     |       /        ::::::\n     \______/      / ___________/____\______/\_____       /         ::::::\n   --------÷\_____/÷------------------------------÷\_____/gZ! -- -  ::::::\n                             Presents with a smile:      .   . .....:::::''\n\n            Priviliege-Checker v1.2 1994-95 (C) by DiSTLER of hONEY\n\n_____________  /\_____ ____ ___ __ _  _  _ __ ___ ____ _____/\  ______________\n\____________\//\_____ ____ ___ __ _  _  _ __ ___ ____ _____/\\/_____________/\n             \/                                               \/\n\n   Priviliege-Checker was coded by Distler/hONEY\n   For you all /X sysop''s that want''s a status viewer \n   that has something extra! For more info about it read more sum row''s below!\n\n_____________  /\_____ ____ ___ __ _  _  _ __ ___ ____ _____/\  ______________\n\____________\//\_____ ____ ___ __ _  _  _ __ ___ ____ _____/\\/_____________/\n             \/                                               \/\n\n   1 - Copyright notes\n   2 - What it does\n   3 - Installation\n   4 - History\n   5 - Future planned enhancements\n   6 - Greetings in a random order =)\n   7 - How to contact me\n\n\n     This archive SHOULD contain:\n                  ¯¯¯¯¯¯\n     Privilege-Checker                7712  DOOR    V1.2\n     Privilege-Checker.Doc            8462  DOC\n     Privilege-Checker.IFF            8770  IFF     IFF PIC OF THE DOOR\n     S.info                            807  ICON\n\n_____________  /\_____ ____ ___ __ _  _  _ __ ___ ____ _____/\  ______________\n\____________\//\_____ ____ ___ __ _  _  _ __ ___ ____ _____/\\/_____________/\n             \/                                               \/\n\n\n   1. Copyright notes\n\n   This product is copyrighted in 1994-95 by DISTLER/HONEY/\n   You may copy this utility and spread it as much as you want\n   as long no changes or any modifications has been made.\n   This utility is released under the concept dialup ware.\n   You may NOT sell this pice of work for your / anyone''s profit!\n\n_____________  /\_____ ____ ___ __ _  _  _ __ ___ ____ _____/\  ______________\n\____________\//\_____ ____ ___ __ _  _  _ __ ___ ____ _____/\\/_____________/\n             \/                                               \/\n\n   2. What it does\n\n   Well for a starter it is an ordinary status viewer called\n   Priviliege-Checker! What it does, is that it shows the\n   user that''s online what axxz and so on...\n\n   *B*U*T*  (Yeah there is always a BUT)\n  \n   this one is QUITE different from other status doors...\n   It shows the total amount of bytes & files that the user has\n   uploaded and downloaded!\n   And it even shows how many more bytes & files that the user has\n   uploaded. \n   AND some more stuff that you MUST see!.\n\n   Personally i love the door becoz it does something that other status\n   doors don''t.. so use it or loose it! \n\n_____________  /\_____ ____ ___ __ _  _  _ __ ___ ____ _____/\  ______________\n\____________\//\_____ ____ ___ __ _  _  _ __ ___ ____ _____/\\/_____________/\n             \/                                               \/\n\n   3. Installation\n\n   AmiExpress 4.xx\n   ---------------\n\n   1. - Make a directory called PRIVILIEGE-CHECKER in your DOORS:\n\n   2. - Copy the file PRIVILIEGE-CHECKER to DOORS:PRIVILIEGE-CHECKER/\n\n   3. - Copy the S.INFO icon to BBS:Commands/BBSCmd/\n        Copy the S.INFO icon to BBS:Commands/SysCmd/\n        Ex. Copy RAM:BBS/Commands/BBSCmd/S.INFO BBS:Commands/BBSCmd/\n        Ex. Copy RAM:BBS/Commands/SysCmd/S.INFO BBS:Commands/SysCmd/\n\n   4. - Well now you are all set to GO!. Unless you have made a\n        major fokkup!\n\n\n_____________  /\_____ ____ ___ __ _  _  _ __ ___ ____ _____/\  ______________\n\____________\//\_____ ____ ___ __ _  _  _ __ ___ ____ _____/\\/_____________/\n             \/                                               \/\n\n   4. History\n\n\n   Beta1  - First working version\n\n   v0.9   - Added some ANSI and remade the output style\n\n   v1.0   - Public release! The door got everything that i can come up with \n            for the moment! But perhaps i can come up with some more\n            cool stuff to add. So don''t think that you are safe YET!\n\n   v1.1   - Added total amount of bytes&files you got to leech!\n            requested by agamemnon/hcd!\n\n   v.1.2  - Made it work on /X 4.xx versions only! And also optimized the\n            size and speed of the little but cute door =)\n\n_____________  /\_____ ____ ___ __ _  _  _ __ ___ ____ _____/\  ______________\n\____________\//\_____ ____ ___ __ _  _  _ __ ___ ____ _____/\\/_____________/\n             \/                                               \/\n\n   5. Future planned enhancements\n\n   1 - There is none, at the moment!\n\n\n          Got some ideas for me to add? or maybe you found a bug?\n                  Then call the SLAmmER  +46-8-623 01 96\n\n_____________  /\_____ ____ ___ __ _  _  _ __ ___ ____ _____/\  ______________\n\____________\//\_____ ____ ___ __ _  _  _ __ ___ ____ _____/\\/_____________/\n             \/                                               \/\n\n   6. Greetings\n\n                     Greetings to some ppl in random order:\n\n           Nightshade/ins Warhammer/hny qen/hny Looby/ins Bigwig/ins\n         h2o/hny/sad Spider/no! Diz''Nee/hny fAKTOr & tRANCe Santzia/led\n          Mood/led NecroNomicoN/bf! tbM/led/bst/pa! Case/dcs Phyro/hny\n         Metal/ins Countzero/wh/hny Virus/are Morris/bf!/dpl/acd Derek\n         Drain/Leecher! Ezco/pdy Stylewars/sht/hny/pos tbb/? Westbam/?\n           Sid Vicious/bf! Dark Ranger/dls Sniper/ins Sauzer/bf!/rdn\n         Mr Nielsen/led Zen/rdz Kurgan/hny/g-f Dartaagnan/ott/hny/gf/wh\n                      Gozz/hny Dalamar/led U-man/hny/ac! \n\n       and ofcoz all the hny members and everyone that calls my board ;)\n\n                           Some helloes goes out to:\n\n  Looby/ins Nightshade/ins Agamemnon/? Bobo/mst Sven The Creator/5d Atomix/otl\n  Roy Sutton Blast/ssp Warhammer/hny Mfm/ivn/sr/ipl Nocturne/ogn Hotz Gianluca\n     Byteandi/trsi Siegel/mst Killraven/mst Fuzz/led Empire/mst Spock/trsi\n     Crew-One/mth Mack Lifeguard Calypso/god Cannibal/neon Trespass/Clique\n         Dr.Dre/trsi Uiper/lrx Picard/phn/sht Aquarius/otl Instant/Indy\n            Kerosene/bth Grand Admiral/lsd Hunk/task Psychotron/ihm\n\n\n_____________  /\_____ ____ ___ __ _  _  _ __ ___ ____ _____/\  ______________\n\____________\//\_____ ____ ___ __ _  _  _ __ ___ ____ _____/\\/_____________/\n             \/                                               \/\n\n   7. How to contact me\n\n\n            Call one of these boards and leave me / the sysop a mail\n\n        cG!_______.\n  ._ _____.)      |___________ ________ .______.____________