INSERT INTO door_catalog VALUES('hp4lv095','HP4LV095.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HP4LV095.LHA','AmigaGuide','XIM','AmigaGuide',NULL,NULL,NULL,'/  _  \_/   _/__/___/_\_   \/___/   _/__ /   /   /___    /   /   /   /   /___    / /       /   /   /   /  _   _/   /   /   /',replace('   _____   _____   ____ _____  _________   \n  /  _  \_/   _/__/___/_\_   \/___/   _/__ \n /   /   /___    /   /   /   /   /___    / \n/       /   /   /   /  _   _/   /   /   /  \n\______/_______/___/___\___\___/_______/CoZ\n<-- -  -     .p.r.e.s.e.n.t.s.     -  - -->\n.-----------------------------------------.\n|  iGDMEA VERSiON 1.0 - ACCOUNT-EDiTiNG-  |\n|    SECURiTY-DOOR FOR ALL /X VERSiONS    |\n`-----------------------------------------''\n','\n',char(10)),'iGDMEA10.GUiDE',replace('@DATABASE "iGDMEA10.ENGLiSH.GUiDE"\n@REMARK .------------------------------------------------------------------.\n@REMARK | This document is written in AmigaGUiDE format, so please read it |\n@REMARK | with AmigaGUiDE or your favourite guide reader.... ciao now...   |\n@REMARK `------------------------------------------------------------------''\n@REMARK $VER: iGDMEA V1.0\n@WiDTH 80\n@NODE MAiN "Guide to iCH GEB DiR MAL EBEN ACCESS V1.0 WRiTTEN BY MuMu OF OSiRiS"\n                                   /\            /\            \n               ___________________/  \__________/  \__________\n               \_  _   _    _    /  __   _     /  __    _    /\n               /   |   \    |___/\__/\  _|   _/\__/\    |___/_\n              /    |    \____     \   \  \      /   \____     \\n              \    |    /   /     /   /  |\    /    /   /     /\n               \_______/_________/___/___| \  /____/_________/\n                                            \/         ©JoKER\n                            ¿S pROUD tø pRESENT:\n\n               >»»»»> iCH GEB DiR MAL EBEN ACCESS V1.0 <««««<\n\n                          @{"-*-   iNTRODUCTiON   -*-" LiNK iNTRODUCTiON}\n                          @{"-*-     FEATURES     -*-" LiNK FEATURES}\n                          @{"-*-   iNSTALLATiON   -*-" LiNK iNSTALLATiON}\n                          @{"-*-   EDiT CONFiGS   -*-" LiNK CONFiGFiLES}\n                          @{"-*- TROUBLE-SHOOTiNG -*-" LiNK PROBS}\n                          @{"-*-    WHO DiD iT    -*-" LiNK CREDiTS}\n                          @{"-*-     HiSTORY!     -*-" LiNK HiSTORY}\n                          @{"-*-    GREETiNGS!    -*-" LiNK GREETiNGS}\n                          @{"-*-    OUR SLOGAN    -*-" LiNK SLOGAN}\n@ENDNODE\n\n@NODE iNTRODUCTiON "iNTRODUCTiON OF iGDMEA VERSiON 1.0"\n\niCH GEB DiR MAL EBEN ACCESS VERSiON 1.0 iS A SECURiTY DOOR FOR ACCOUNT-\nEDiTiNG. iT HAS @{"FEATURES" LiNK FEATURES} THAT MAKE YOUR SYSTEM MUCH MORE SAFE.\n\n@ENDNODE\n\n@NODE FEATURES "FEATURES OF iGDMEA VERSiON 1.0"\n\nWELL, iGDMEA WORKS KiNDA SiMPLE. EVERYBODY HAS TO ENTER A SPECiAL PASSWORD\nTO EDiT ACCOUNTS. THEN THE DOOR CHECKS iF THE USER HAS REALLY ACCESS TO\nACCOUNT EDiTiNG OR NOT. iF NOT (ONLY HE HAS THE SECURiTY LEVEL TO START\nTHE DOOR - MAYBE A HACKER) THE DOOR WiLL MAKE AN ENTRY iNTO THE CALLERSLOG\nAND WiLL ALERT THE SYSOP BY FLASHiNG THE SCREEN AND MAKE SOME BEEPS.\n\ni THiNK THAT iS MUCH SAFER iN TiMES EVERYBODY FEARS TO GET BUSTED.\n\nAND NOW i THiNK i GAVE YOU ENOUGH REASONS TO iNSTALL iGDMEA VERSiON 1.0. :)\n\n@ENDNODE\n\n@NODE iNSTALLATiON "iNSTALLATiON OF iGDMEA VERSiON 1.0"\n\niNSTALLATiON TO @{"AMi EXPRESS V2.xx" LiNK AMiEXPRESSV2.xx}.\n\niNSTALLATiON TO @{"AMi EXPRESS V3.xx" LiNK AMiEXPRESSV3.xx}.\n\n@ENDNODE\n\n@NODE AMiEXPRESSV2.xx "iNSTALLATiON TO AMi EXPRESS V2.xx"\n\nTO iNSTALL THE DOOR LOAD UP THE CUSTOMCOMMANDS (/X V2.2x OR BELOW) OR\nBBS.CMD (/X V2.3x) AND ADD THE FOLLOWiNG LiNE TO THE LiST.\n\n\n          11 SPACES iN         \n          |\n--------------------------------------------------          \n*1        RM255MODULES:MM_TOOLS/ACCESS/ACCESS.REXX\n--------------------------------------------------\n||        |||  |           \n||        |||  ` ''MODULES:MM_TOOLS/ACCESS/ACCESS.REXX'' iS THE LOCATiON OF\n||        |||     THE FiLE.\n||        |||\n||        ||` 255 THE MiNiMUM ACCESS TO USE THiS DOOR. CHANGE iT TO WHAT\n||        ||      YOU LiKE.\n||        ||\n||        |` ''M'' FOR A MULTiNODE BBS (''S'' FOR A SiNGLE NODE BBS).\n||        |\n||        ` ''R'' FOR A REXX DOOR WHiCH WiLL USE THE ''REXXDOOR''-UTiL.\n||\n|`COMMAND TO START THE DOOR.\n|\n`-RETARD OPTiON. TO MAKE SURE THEY ONLY USE ''1'' & ONLY  ''1'' TO GET THE\n  DOOR TO COME UP. iF NOT USED, THiNGS SUCH AS ''12345'' AND ''1Z'' WOULD\n  STiLL BRiNG UP THE DOOR.\n\n\n  USE THE LiNE BETWEEN THE LiNES ONLY. THE OTHER PARTS ARE JUST AN\n  EXPLANATiON TO MAKE SURE YOU KNOW WHAT EACH PART iS DOiNG (SiNCE\n  NOONE WOULD TELL ME BACK iN THE DAYS WHERE i DiDN''T KNOW WHAT WAS\n  GOiNG ON!)  \n\n  NOW COPY THE DiRECTORY ''MODULES'' FROM THE LHA-ARCHiEV TO YOUR BBS.\n\n  THEN COPY THE ''DODELAY''-COMMAND FROM THE C-DiRECTORY OF THE\n  LHA-ARCHiEVE iNTO YOUR C-DiRECTORY.\n\n\n  AT LAST EDiT THE @{"CONFiGFiLES" LiNK CONFiGFiLES}. YOU FiND WiLL THEM iN\n \n  ''BBS:MODULES/MM_TOOLS/ACCESS''.\n\n@ENDNODE\n\n@NODE AMiEXPRESSV3.xx "iNSTALLATiON TO AMi EXPRESS V3.xx"\n\nTHE ONLY THiNG TO DO iS TO COPY THE FiLES FROM THE LHA-ARCHiEVE TO YOUR BBS. THEN\nEDiT THE @{"CONFiGFiLES" LiNK CONFiGFiLES}. YOU WiLL FiND THEM iN ''BBS:MODULES/ABSTURZ/COECP''.\n\nAT LAST COPY THE ''DODELAY''-COMMAND FROM THE C-DiRECTORY OF THE\nLHA-ARCHiEVE iNTO YOUR C-DiRECTORY.\n\n@ENDNODE\n\n@NODE CONFiGFiLES "HOW TO EDiT THE CONFiGFiLES?"\n\n1. ACCESS.CFG\n \n   - THiS iS THE PASSWORD THE USERS HAVE TO TYPE iN TO EDiT ACOUNTS.\n\n   E.G.:\n\n     1st Line = PASSWORD\n\n\n2. ACCESS.NAMES\n\n     - THESE ARE THE NAMES OF THE USERS WHO HAVE ACCESS TO ACCOUNT-EDiTiNG.\n\n     E.G.:\n\n     - Line 1 = SPiDER/OSiRiS\n     - Line 2 = DOC iCE/TSB\n     - Line 3 = KOO KOO KA CHOO\n\n     - YOU CAN ADD AS MANY NAMES AS YOU MiGHT WANT.\n\n@ENDNODE       \n\n@NODE CREDiTS "CREDiTS FOR iGDMEA V1.0"\n\n   iDEA          : MuMu øf OSiRiS\n   \n   AREXX-CODiNG  : MuMu øf OSiRiS\n   \n   DOCUMENTATiON : MuMu øf OSiRiS\n\n   BETA TESTiNG  : MuMu   - KEY WEST - OSiRiS EHQ - SCANDAL DiST SiTE\n                   JOKER  - MAD HOUSE - TAURUS GHQ - PROTECH GHQ\n                   \n@ENDNODE\n\n@NODE GREETiNGS "FRiENDSHiP RULEZ"\n\n               GREETiNGS FROM MuMu TO THE FOLLOWiNG PEOPLE:\n              ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nCREEPY/TFP          - HOW iS iT GOiN''?\nGANDALF/SCL         - WHY DON''T YOU CALL ME?\nRAPiD/SCL           - THANX FOR THE ANSiS.\nRAF/TFP             - THANX FOR THE KEY WEST LOGO. iT iS PRETTY NiCE.\nDiCE/TFP            - THANX FOR THE BBS-ADVERT YOU CODED FOR ME.\nMURDOC/NEON         - YOUR AT&T''S ARE 100% NO ViRGiN CARDS. BETTER TRY\n                      TO GET A BETTER CARD-SUPPLiER.\nDEFJAM              - THANX FOR BETA-TESTiNG.\n \n\n                  AND A BiG HELLO TO ALL OSiRiS MEMBERS !\n\n@ENDNODE\n\n@NODE PROBS "DO YOU HAVE ANY PROBLEMS?"\n\n               FOR TROUBLE-SHOOTiNG OR LATEST UPDATES CALL:\n              ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n                 sYSOP: MuMu    «·»    1 nODE - 16.8k DHST       \n      - -- --- --------------------------------------------- --- -- -\n               ___                 \          /                      \n        ______/  /___  __  __    ___\        /____  _______________  \n        \_   /  /__  \/  \/  \   \   \      /___  \/  ____/\__    /  \n         | _/ _/ _/  /   /   /    \  /\    /  _/  /\____ \_   \__/   \n         | \  \  \__/\__    /  ·   \   \  /   \__/|    /  /     \    \n         |__\  \___________/        \/\  /________|______/|      \   \n             \__\                      \/              EaZ|_______\  \n                  OSiRiS EHQ & SCANDAL DiSTRiBUTiON SiTE             \n      - -- --- --------------------------------------------- --- -- -\n\n                    » aMiGA · /X · cONSOLE · mODULES «               \n\n               aMiXPRESS v3.XX   ø   nUP & sYSTEM pW nEEDED          \n\n                    -:) cALL nOW fOR a goOD rATiO (:-                \n\n@ENDNODE\n\n@NODE SLOGAN "OUR SLOGAN..."\n\n                                   /\            /\            \n               ___________________/  \__________/  \__________ \n               \_  _   _    _    /  __   _     /  __    _    / \n               /   |   \    |___/\__/\  _|   _/\__/\    |___/_ \n              /    |    \____     \   \  \      /   \____     \\n              \    |    /   /     /   /  |\    /    /   /     /\n               \_______/_________/___/___| \  /____/_________/ \n                                            \/         ©JoKER\n\n                        - WE DON''T WANNA BE THE BEST -\n \n                       - WE JUST WANNA HAVE MORE FUN! -\n\n@ENDNODE\n\n@NODE HiSTORY "THE HiSTORY OF ''iCH GEB DiR MAL EBEN ACCESS''"\n\n                 THE HiSTORY OF ''iCH GEB DiR MAL EBEN ACCESS\n                ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nVERSiON 0.1 : iNTERNAL RELEASE\n\nVERSiON 0.2 : iNTERNAL RELEASE\n\nVERSiON 0.3 : iNTERNAL RELEASE\n\nVERSiON 0.4 : iNTERNAL RELEASE\n              SOME BUGS REMOVED\n\nVERSiON 0.5 : iNTERNAL RELEASE\n\nVERSiON 0.6 : BETA RELEASE\n\nVERSiON 0.7 : SOME BUGS REMOVED\n\nVERSiON 0.8 : BETA RELEASE\n\nVERSiON 0.9 : FiNAL BETA VERSiON\n\nVERSiON 1.0 : PUBLiC VERSiON\n\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',72332,8,0,NULL,NULL,'hp4lv095','scan',1780048545);
INSERT INTO door_catalog VALUES('hpr_pd10','HPR-PD10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HPR-PD10.LHA','PrO-DmScHeCk','XIM','PrO-DmScHeCk',NULL,NULL,'HPR','\:::::::/  / \\____  \____  \:::::::::::\ \:::::/-   _//  ____/  _   /\:::::::::::\ \:::/__/  //_  /\_/_  /\  \/:::XPRESS:::\',replace('_________/\__ __________________________\n\:::::::/  / \\____  \____  \:::::::::::\\n \:::::/-   _//  ____/  _   /\:::::::::::\\n  \:::/__/  //_  /\_/_  /\  \/:::XPRESS:::\\n  /:::\_/__/ \_\/ /:\_\/ /\  \::PRESENTS::/\n /::::::\__\/:::\/GH''94\/::\__>::::::::::/\n/:::::::::::::::::::::::::::::::::::::::/\n -== PrO-DmScHeCk v1.0 - DMS checker ==-\n -==   Fastest DMS checker around    ==-\n','\n',char(10)),'PrO-DmScHeCk.Guide',replace('@database PrO-DmScHeCk.guide\n@$VER: PrO-DmScHeCk.guide v1.0 (15-Jun-94)\n\n@node MAIN "PrO-DmScHeCk Contents"\n            @{b}@{u}Documents for PrO-DmScHeCk v1.0@{ub}@{uu}\n\n             PrO-DmScHeCk was written by Exodous/TLS & XPress\n                           Released on 15-Jun-94\n\n                      1)  @{" What is PrO-DmScHeCk ? " link WHAT_IS_PDC}\n                      2)  @{" Command line options   " link PDC_OPTS}\n                      3)  @{" Installation           " link INSTALLATION}\n                      4)  @{" Distribution           " link DISTRIBUTION}\n                      5)  @{" Greetings              " link GREETINGS}\n                      6)  @{" Contacting me          " link CONTACTING_ME}\n                      7)  @{" Call These BBS''s       " link BBS_ADS}\n                      8)  @{" History                " link HISTORY}\n                      9)  @{" Other programs         " link OTHER_PROGS}\n\n                PrO-DmScHeCk was written in 100% assembler.\n@endnode\n\n@node WHAT_IS_PDC "What is PrO-DmScHeCk"\n                     @{u}What is PrO-DmScHeCk ?@{uu}\n\nPrO-DmScHeCk is a DMS file checker meant to be run from a BBS when a\nDMS file has been uploaded.\n\nIt allows other BBS adverts to be stripped from the file, and your own\nBBS adverts can be added to advertise your BBS.\n\nPrO-DmScHeCk was originally written for @{"THE TOWER" link BBS_ADS}, and was written\nin 680x0 assembler using Devpac 3 from HiSoft.\n\n@endnode\n\n@node PDC_OPTS "PrO-DmScHeCk Options"\n               @{u}PrO-DmScHeCk''s command line options@{uu}\n\nUsage : @{b}PrO-DmScHeCk@{ub} [-<options>] <filename>\n\nWhere options is one or more of :\n\n   @{b}b@{ub} - Add a tail banner (from @{b}S:PDC_Banner_Rear@{ub})\n\n   @{b}f@{ub} - Add a front banner (from @{b}S:PDC_Banner_Front@{ub})\n\n   @{b}t@{ub} - Add a track 0 banner (from @{b}S:PDC_Track_Zero@{ub}\n                             this file @{b}MUST@{ub} be 960 bytes long.)\n\n   @{b}d@{ub} - Add the current time and/or date to one/all of the\n                text to be added.\n\n      When ''##-###-###'' appears in a file the date will be added,\n       and when ''##:##'' appears the current time will be added.\n\n  @{b}R@{ub} - Remove existing front/tail banners.\n\n  @{b}T@{ub} - Remove existing track 0 banners.\n\n@endnode\n\n@node INSTALLATION "How to install PrO-DmScHeCk"\n                    @{u}Installation instructions@{uu}\n\n@{u}Installation for normal command line usage@{uu}\n\nCopy @{b}Utils/PrO-DmScHeCk@{ub} to anywhere in your path (usually C:).\n\n@{u}Installation for Ami-Express BBS usage@{uu}\n\nCopy @{b}Utils/PrO-DmScHeCk@{ub} to @{b}BBS:Utils/PrO-DmScHeCk@{ub}\nCopy @{b}FCheck/DMS.info@{ub} to @{b}BBS:FCheck/DMS.info@{ub}\nCopy @{b}S/PDC_Banner_Front@{ub} to @{b}S:PDC_Banner_Front@{ub}\nCopy @{b}S/PDC_Banner_Rear@{ub} to @{b}S:PDC_Banner_Rear@{ub}\nCopy @{b}S/PDC_Track_Zero@{ub} to @{b}S:PDC_Track_Zero@{ub}\n\nEdit the files @{b}S:PDC_Banner_Front@{ub} (any size),\n               @{b}S:PDC_Banner_Rear@{ub} (any size)\n           and @{b}S:PDC_Track_Zero@{ub} (960 bytes)\n\n to suit your own BBS.\n\nNow when a DMS file is uploaded it will be automatically checked for\nvalidity and integrity by PrO-DmScHeCk.\n@endnode\n\n@node DISTRIBUTION "Distribution restrictions"\n                  @{u}Distribution of PrO-DmScHeCk@{uu}\n\nPrO-DmScHeCk is (c)1994 Exodous/TLS & XPR and may be distributed in any\nway as long as the following conditions are met :\n\n  @{b}o@{ub}  All of the files are included, unchanged.\n  @{b}o@{ub}  No money changes hands (ie @{b}NO@{ub} PD library distribution)\n\n@endnode\n\n@node GREETINGS "Greetings"\n\nGreetings to the following people :\n\n    @{b}Oll¿e@{ub}\n    @{b}GrassHopper@{ub}\n    @{b}FireFlash@{ub}\n    @{b}M¿sta Are@{ub}\n    @{b}Mike@{ub}\n\nAll members of @{b}TLS@{ub} and @{b}XPress@{ub}.\n@endnode\n\n@node CONTACTING_ME "How to contact me"\n                          @{u}How to contact me@{uu}\n\nI can be contacted via E-Mail in the following ways :\n\n @{"Q.E.D" link BBS_ADS}     : Exodous\n @{"The Tower" link BBS_ADS} : Exodous\n\n Internet :\n\n  [email removed]      (If this address bounces then use the next one)\n  [email removed]\n@endnode\n\n@node BBS_ADS "Call these BBS''s"\n                  @{u}Call these great XPress BBS''s@{uu}\n\n@{b}Q.E.D@{ub} (WHQ)         : +44 (0)91-372-1911 (2 Nodes) - @{b}GRASSHOPPER@{ub}.\n\n@{b}SLEEZY BBS@{ub} (UKHQ)   : +44 (0)422-367-163 (1 Node)  - @{b}BONEIDLE@{ub}.\n\n@{b}MEDUSA DOMAIN@{ub} (CHQ) : +1 905-574-7791    (6 Nodes) - @{b}MEDUSA@{ub}.\n\n@{b}BIO HAZARD@{ub} (CHQ)    : +1 905-841-0965    (3 Nodes) - @{b}KAPT. KAOS@{ub}.\n\n@{b}THE LAB@{ub} (CHQ)       : +1 514-745-7420    (3 Nodes) - @{b}P.R SINISTER@{ub}.\n\n@{b}WAREZ DEPOT@{ub} (USHQ)  : +1 305-819-9925    (3 Nodes) - @{b}AMIGAMAN@{ub}.\n\n                  @{u}Call these other great BBS''s@{uu}\n\n@{b}THE TOWER@{ub} (LsD UKHQ): +44 (0)204-384-453 (2 Nodes) - @{b}FIREFLASH@{ub}.\n                      +44 (0)204-371-868\n\n@endnode\n\n@node HISTORY "The history of PrO-DmScHeCk"\n                     @{u}History of PrO-DmScHeCk@{uu}\n\n| Ver   | Date          | Comment\n+-------+---------------+--------------------------------------------\n| 1.0   | 15-Jun-94     | First version.\n+-------+---------------+--------------------------------------------\n@endnode\n\n@node OTHER_PROGS "Other programs that I have written"\n         @{u}Here is a list of other programs that I have written@{uu}\n\n@{b}BootUte@{ub}      : Degrader type utility for @{i}newer@{ui} Amiga''s....\n               Needs Kickstart 2.0+. Features easy to use gadtools\n               interface.\n\n@{b}BullRead@{ub}     : Bulletins door for /X that allows users to search\n               bulletins while they are on-line, or download the bulletins\n               for viewing whilst off-line.\n\n@{b}X-Zippy@{ub}      : Replacement zippy search door for /X that can search\n               for multiple items at a time, about 3 times faster\n               than the built in zippy!!\n\n@{b}UserCom@{ub}      : Door for /X that allows users to make comments to files\n               so that others will know if the file is old, fake etc.\n\n@{b}PrO-LhAcHeCk@{ub} : LhA file checker - for user with most BBS systems.\n               Strips most other adverts and adds own adverts that are\n               virtually unstrippable.\n\n@{b}Decrunch@{ub}     : CLI based decruncher to decrunch loads of different\n               packed files.\n\n@{b}PPPatch@{ub}      : PowerPacker Patcher... Patches the headers of PowerPacked\n               files so that they can''t be decrunched.\n\n@{u}Projects I''m working on@{uu}\n\n@{b}EBBS@{ub}         : En¿gma Bulletin Board System\n               My own host BBS, written entirely in Assembler with loads\n               of features : Kickstart 2.0+ only.\n\n@{b}xxxx-NuKe@{ub}    : Program similar to Boss-Nuke (for /X) that allows files\n               to be nuked, givent extra credits etc., will run from /X\n               as a door, or from the CLI/WB and display a user interface\n               (Kickstart 2.0+ only)\n\n@{b}GFC@{ub}          : Graphics Format Converter\n               A great graphics converter for loads of different formats...\n               (Kickstart 2.0+ only)\n\n@{b}Shell Menu@{ub}   :\n               A program similar to Tools-Daemon and the like, but to\n               add menu''s to the Shell window.\n\n@{b}E-Dos@{ub}        : Enigma-DOS\n               Replacement floppy-disk filing system with in-line\n               encryption for transferring/storing private information.\n\n\nIf you have any suggestions for features that you would like to see in\nany of the programs then e-mail me with your suggestions.\n\n@endnode\n','\n',char(10)),NULL,'auto-added',38689,2,0,NULL,NULL,'hpr_pd10','scan',1780048545);
INSERT INTO door_catalog VALUES('humuss11','HUMUSS11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HUMUSS11.LHA','RPStart','REXX','USER STATS SCAN FOR /X','1.1',NULL,NULL,NULL,replace('USER STATS SCAN V1.1 FOR /X\n','\n',char(10)),'USS.doc',replace('          _____                                            ____     \n  _______|    "|___________ ____   ____ ___________ _____ |   "|_____________\n  \      |    :|"    |    "|"   \_/   "|"    _    "|"    \|   :|"    _______/\n   |     "     |.    |     |     "     |:    |     |.     "    |.    ___|__\n   |     _     |_         :|_   \_/   :|_    _    .|_   _     .|_         "|\n   |:    |______/___________/____|______/____|______/   |\______/_____    :|\n   |_____| --------------------------------------- |____| ---------- |_____|\n \n                  PRESENTS: USER STATS SCAN v1.01      © 93 STriKeR/HuMAnE DK\n                         \n                            ***UPDATE***\n \nJust some quick dox, ya should have no probs installing this door, if ya have\nya should not be running a board.\n\n                            REQUIREMENTS\n\nAll the usual rexx librarys and of course Ami Express. I have not include the\nrexx librarys in this archive as ya should already have them also you need to\nrunning RPStart.\n\n                            WHAT IS IT??\n\nWell I guess the name speaks for itself, its a replacement for the inbuilt S \ncommand in /X, which displays more information to the user.\n\n                           HOW TO INSTALL\nCopy RPStart to your C dir\nput this line in your userstartup or startup-sequence\n\n-----------CUT HERE---------------\nRPStart\n-----------CUT HERE---------------\n\nCreate a dir USS in Doors:\nCopy the file USS.exe into that directory ...\n\nFor /X 2.x users put this in your bbs.commands\n\n-----------CUT HERE---------------\n*S        RM010DOORS:USS/USS.exe\n-----------CUT HERE---------------\n\nFor /X 3.x users the specific Icon is included and should go in the\nBBS.CMD dir ...\n\nWell I guess that all folks!! easy huh.\n\nAny bug reports to me (STriKeR) at EVIL DEAD +45-318-57016\n\nI guarantee that when this left my board there were no backdoors, but if ya \nwanna be 100% safe just gimme a call and Dowload it from here.\n\n .oO%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%Oo.\n                          SySoP: STriKeR - HuMaNe      \n \n     FaS7 WaReZ!            Co-SySoP 1: NASHUA            GrEa7 Ra7iOnS!\n \n      /X U7iLs!     Co-SySoP 2: Jack The Zipper - HuMaNe      24HrZ!  .\n                                                                    . . .\n  ------/\____--/\____--/\_--/\_--------/\____--/\____--/\____--/\___\:/---\n       /o     \/o  /  \/ / \/o  \_     /o     \/o     \/o     \/o - -=*=---\n      //  \___//  /   /\/  //   / \   //  /   //  \___//  /\  //  /  /|\\n   __//  \___//  /   //   //   /   \_//  /   //  \___//      //  /  ./: .\n __-_-__     \\     /\\   \\       /--__ \   \\      \\      \\  \   \. \n  -__-_______/\____/  \\ _/\______/-_-_______/\______/\\ /\__/\______/.\n  ---------------------\/------------------------------\/-------------[NA]-\n \n       RuNnInG /X 2.37 -=- 16k8 DUAL -=- 24 HrZ -=- 24oo OnLy InVi7eD\n \n   0-1 DaYz Eli7e WaReS -=- UsEs OfFlInE ChEcKiNg So No 7iMe Was7eD OnLiNe\n                         ___   ___    __  ___ ___ __    __\n  __-_--__-_-   _|_ |__|(__  __ __)| (__)(__   _/|  | |(__ -___--_---_---\n  -____-_--__--  |     |___)   ___)| (__)___)  / |__| |(__) _--__-___---\n  \n .oO%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%Oo.\n','\n',char(10)),NULL,NULL,33577,6,0,NULL,NULL,'humuss11','scan',1780048545);
INSERT INTO door_catalog VALUES('hwc11','HWC11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/HWC11.LHA','WarCalls','XIM','WarCalls',NULL,'WarDancer/H&V',NULL,'¦ /   _  \  |  \  \  / \/  |_ \   \ \  ___/ _/    |   \_`   \_ \/   \_ _/  \_\   \_   \_ \_____|____/_____/__\____/_|____/_\___/____/',replace('.--/  | \/  | \___ \/ ___/   \/  \ \   ____/\n¦ /   _  \  |  \  \  / \/  |_ \   \ \  ___/ \n_/    |   \_`   \_ \/   \_ _/  \_\   \_   \_\n\_____|____/_____/__\____/_|____/_\___/____/\n¦\    |    /   \/  \ \__\///____  /   \   / \n¦ \   |   /  |_ \   \ \ \/ \mrv/  \___ \ /¦ \n¦  \  ·  /   _/  \_\   \_   \_/    \_ \  \_ \n¦aND\___/____|____/_\___/____/______/_____/ \n`--------  - -÷p÷r÷e÷s÷e÷n÷t÷s÷- -  ------'' \nWarCalls V1.1 for /X V3.xx  by WarDancer/H&V\n------------------------------>[a·bAsE]<----\n','\n',char(10)),'WarCalls.guide',replace('@database WarCallsDoc\n@Author Wardancer/Humane&Vanity\n@Index MAIN\n\nCopyright 1994 Wardancer/Humane&Vanity\n\n@node MAIN "WarCalls V1.1 Documentation."\n\n                   ___:   :_ ___ _ :  .   __:  :___ _:___.\n                  |   |   | V   | \|  :  /  |  : __) |  _)\n                  :   _   |._.  |\ !  |&(   |  | :\_ ! _/\n                  |   l___!_|   : \___!  \  !  | | |   |\n                  !   ¡   zy:   ! :       `---:'' : l___:\n                (-:   :-----------(Pr@s@nts:)-!  :------+--)\n                                 WarCalls V1.1\n\n                      Made by : Wardancer/Humane&Vanity\n\n\n\n                              Table of contents :\n\n                           @{"     Whats this ?     " Link 01}\n                           @{"     Installation     " Link 02}\n                           @{"        Greets        " Link 03}\n                           @{"   Bug report/ideas   " Link 04}\n                           @{"       History        " Link 05}\n\n@endnode\n\n@node 01 "Whats this ?"\n\n  ========================================================================\n\n  WarCalls is a program  that will allow  you to list all  users that have \n  called below a number of times you specify. Warcalls will list the users\n  handel, location, and  times  called, WarCalls  will also  offer  you to\n  redirect the output to a file.\n\n  ========================================================================\n\n@endnode\n\n@node 02 "Installation"\n\n  ========================================================================\n\n  Installing  this program is really  quite simple, the  only things you\n  have to is to make sure the following is right :\n\n  Program      Location          Description\n  -------      --------          -----------\n  WarCalls     Doors:WarCalls    The main program\n\n  Also make sure that calls.info is in the commands/bbscmd drawer.\n\n  ========================================================================\n\n@endnode\n\n@node 03 "Greets"\n\n  ========================================================================\n\n  I would like to greet the following in no order :\n\n  Kronion, Dux, The Freak, Ramirez, Omar, Striker, Playmate, Calvin,\n  Plexer, Gilthanas, Energy, Shamer, Tactica, Zany, Zeke, Spike,\n  Delirium&Kickface, Mike&Tofke, Norske, Chock, Paranoid, OB1, Curmit,\n  Tin Man, Mandrake, Mr. Orion, Mr. Beer, Marty, Nookman, Poison, Json,\n  Conan&Newton, Tarzan, Jake, HAL 9000, D-Day, Cracy Creep, Mr. Vain,\n  Overlord, Stezotehic\n\n      And all other Humane&Vanity members and people I forgot.\n\n  Specials go to :\n\n  Kronion .......................... For being a great leader\n  Dux .............................. Thanks for helping me with AmiExpress\n  Ramirez .......................... For letting me test at your board\n  Omar ............................. For all sorts of crazy conversation\n\n  ========================================================================\n\n@endnode\n\n@node 04 "Bug report/ideas"\n\n  ========================================================================\n\n  Send your bug reports or ideas to the following boards :\n\n  Susperia ............... +45 434-34236 (Humane&Vanity SCHQ)\n  Somewhere Online ....... +45 597-53801 (Humane&Vanity DKHQ)\n  Suffocation ............ +45 491-80760 (The board where I test my doors)\n  Mainline ............... +45 981-53062 (Also supports netmail)\n\n  ======================================================================== \n\n@endnode\n\n@node 05 "History"\n\n  ========================================================================\n\n  V1.1 - Made WarCalls show users location.\n         Made it possible to redirect output.\n\n  V1.0 - Not released to anybody else than Susperia and Suffocation.\n\n  ========================================================================\n','\n',char(10)),NULL,'auto-added',13999,5,0,NULL,NULL,'hwc11','scan',1780048545);
