INSERT INTO door_catalog VALUES('h_v_um24','H_V_UM24.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/H_V_UM24.LHA',NULL,'XIM','UserMsg.000',NULL,NULL,NULL,'|   |   | V   | \|  :  /  |  : __) |  _) :   _   |._.  |\ !  |&(   |  | :\_ ! _/ |   l___!_|   : \___!  \  !  | | |   |',replace('   ___:   :_ ___ _ :  .   __:  :___ _:___.  \n  |   |   | V   | \|  :  /  |  : __) |  _)  \n  :   _   |._.  |\ !  |&(   |  | :\_ ! _/   \n  |   l___!_|   : \___!  \  !  | | |   |    \n  !   ¡   zy:   ! :       `---:'' : l___:    \n(-:   :-----------(Pr@s@nts:)-!  :------+--)\n   UserMsg v2.4 for AmiExpress 2.x & 3.x    \n','\n',char(10)),'UserMsg.doc',replace('\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n                                 UserMsg v2.4\n\n                              Code by Dux/Vanity\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n\n\n                             ### INTRODUCTION ###\n\nUserMsg may be the ultimate choice for leaving msgs for the other users, this\ncan be done either as a normal door or as a logoff door. And it''s no problem\nto install it as a multinode-door, just use the MCI-codes to display the\noutputfile.\n\n\n                             ### INSTALLATION ###\n\nI will be very brief on this subject of how to install the door, since you as\na registrated owner of AmiExpress will have the doc as reference.\n\nThe executable can be put anywhere you like and should be installed as a\nXIM-type door. The only important thing to remember is that YOU - the SysOp -\nshould be the first person to run the door, since all configuration is done at\nthe first run.\n\n                             ### REGISTRATION ###\n\nIf you use this doors, please either call my board, or leave me a msg\nsomewhere. The board number is +45-981 53062. Amixnet: Dux@DK0001\n\n\n                               ### HISTORY ###\n\nSee the UserMsg.History for update-info.\n','\n',char(10)),NULL,'auto-added',53130,3,0,NULL,NULL,'h_v_um24','scan',1780048545);
INSERT INTO door_catalog VALUES('i_a_y10','I!A-Y10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/I!A-Y10.LHA',NULL,'XIM','.------------------------------------------.',NULL,NULL,'I!A','|                 YELL v1.0                | |                                          | |  From I!A Prods Useless Utility Division |',replace('.------------------------------------------.\n|                 YELL v1.0                |\n|                                          |\n|  From I!A Prods Useless Utility Division |\n|       For All(?) Amiexpress versions     |\n|                                          |\n| Lets the user contact sysop with modules |\n| or samples, internal pager or write msgs |\n|                                          |\n|          Don''t expect to much 8)         |\n`------------------------------------------''\n','\n',char(10)),'yell.doc',replace('\n                                 YELL v1.0\n                         Idea and programming iT!\n\nWhat, why and when? \n----------------------------------------------------------------------------\nFirst of all, I hate to write docs. So I will not put my heart or brain\ninto this one. Like I''ve ever put my brain into anything.\n\nYell is a small program that gives the user 3 different ways to contact the\nsysop. It can play a module or sample, use the internal pager or write a\ncomment to the sysop.\n\nI can''t tell you why you should use Yell, I use it because I want the\nusers to have an oppurtunity to contact me when I''m in other parts of the\nhouse. Even a sysop needs SOME sort of food now and then.\n\nInstallation\n----------------------------------------------------------------------------\nThe installation is simple, copy the files to their respective directories.\nYou must have assigned dOORS:\n\nWhen you have copied the files, you have to configure the three config\nfiles.\n\n Logo.cfg -> The logo you want to use in Yell. I use my handle iT!\n Yell.cfg -> Full path and name on player and sample you want to use.\nUsers.cfg -> Users that are allowed to use the YELL option if it non-public.\n\nThe Yell.cfg consists of 3 lines\n\n-- Cut Here --\nWB3.0:c2/Players/PLAY16 \nbbs:x-files.wav\nYES\n-- Cut Here --\n\nLine 1 - The full path to the player you want to use\nLine 2 - The full path to the mod or sample that should be played\nLine 3 - Yell option public (YES/NO)\n\nNew User Sysop Yell\n----------------------------------------------------------------------------\nThis is a smaller version to use in the newuser conference. I start it with \nthe MCI command from BULL.TXt. The user can here YELL, Page or write a\ncomment to the sysop. This one is still in the beta stadium and will in the\nfinal release give the sysop a wide range of different ways to use this\none. I included it because I found it usefull and comments and ideas are\nvery welcome. \n\nTo start it with MCI\n\n~CC_NUYELL\n\nOr copy, rename etc the NUYELL info icon as you like.\n\nNext version\n----------------------------------------------------------------------------\n* The next version will check if the sysop is online or not. And add the OLM\n  command if he is online.\n* Make the yell option private so only a few users can use it. Also a ban\n  users file will be included.\n\nDunno.. Ideas?\n\nLast words\n----------------------------------------------------------------------------\nThis util is callware, if you use it you have to call my board. If you have\nideas or bug reports conserning this or other utils from me please contact\nme on my board.\n                        Contact Zero +47 7004-0294\n\nAnd ofcourse won''t I take any responsebility for destroyed data or anything\nelse. When I sent this util out it would only read the configf files.\nOriginal size was:  \n','\n',char(10)),NULL,NULL,11994,6,0,NULL,NULL,NULL,'scan',1780048545);
