INSERT INTO door_catalog VALUES('ia_ans10','IA-ANS10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/IA-ANS10.LHA',NULL,'XIM','Silencio of (I)nter(A)ctive presents',NULL,NULL,'IA','...oOoOoO  "..Ansi V.1.0.."  OoOoOo... should be compatible with all /X Version`s Written  in Arexx',replace('Silencio of (I)nter(A)ctive presents\n...oOoOoO  "..Ansi V.1.0.."  OoOoOo...\nshould be compatible with all /X Version`s\nWritten  in Arexx\n','\n',char(10)),'IA-Ansi.Guide',replace('@database Comment V1.0\n\nCopyright (C) 1993 by Silencio of InterActive\nBBS Lord Wilson +49(0)212-200-983 * InterActive GHQ\nAll Rights Reserved\n\n@Remark $VER: Version V1.0 (Dez 27 1993, 18:12:55)\nRemark AmigaGuide DataBase for Comment V1.0 by Silencio!\n\n@node MAIN "Comment V1.0 (Dez 27 1993, 18:12:55) AmigaGuide Document for AmiExpress ! "\n\n   ...oOoOoO  Silencio of (I)nter(A)ctive is proud to present  OoOoOo...\n\n                   ...oOoOoO  "..Ansi V.1.0.."  OoOoOo...\n\n\n\n                          @{"    Package Cotains    " Link Comm1}\n                          @{"     Install Tools     " Link Comm2}\n                          @{"     /X Compatible     " Link Comm3}\n                          @{"       Greetings       " Link Comm4}\n                          @{"        Creditz        " Link Comm5}\n                          @{"  InterActive Boards!  " Link Comm6}\n\n\n@endnode\n@node Comm1 "This Package Contain:"\n\n                       · [ ·  The Contain File  · ] ·\n\n  BBS:Doors/IA-Ansi/Ansi.Rexx          - 385 Bytes (no Backdoor)\n  BBS:IA-Comment.guide                 - 3345 Bytes (Document for this tool)\n  BBS:SYSCmd/ANSI.info                 - 550 Bytes   (Ansi-Icon)\n\n@endnode\n@node Comm2 "Ia-Ansi Installation:"\n\n                         · [ · INSTALLATION · ] ·\n\n  Create a directory in DOORS: called IA-Ansi and copy the file\n  "Ansi.Rexx" into this directory. Then copy the\n  BBS:Commands/SYSCmd/ANSI.info in your BBS:Commands/SYSCmd/ directory.\n\n@endnode\n@node Comm3 "Compatible:"\n\n                           · [ · COMPATIBLE · ] ·\n\n  This Utility should be compatible with all /X Version`s\n\n@endnode\n@node Comm4 "Many Kewl Greetz flies to:"\n\n                          · [ ·  GREETINGS!  · ] ·\n\n                         Jordan     of  InterActive\n                         Warhammer  of  InterActive\n                         Gandalf    of  Faith\n                         Dr.Dre     of  Faith\n                         Triton     of  Faith\n                         Star       of  Absolute\n                         Flite      of  Sceptic\n                         Celic      of  Sceptic\n                         Justice    of  Analog\n                         McLoud     of  Trsi\n                         Phantom    of  Phantax\n\n                   and all the others i have forgot......\n\n@endnode\n@node Comm5 "Credits:"\n\n                          · [ ·   CREDITZ   · ] ·\n\n           Copyright (C) 1993 by Silencio of InterActive, Germany\n                            All Rights Reserved\n\n              The AmigaGuide DataBase writen by Silencio / IA\n\n@endnode\n@node Comm6 "More InterActive Boards:"\n\n                       · [ · InterActive Boards · ] ·\n\n\n                      ...oooOOO  IMPORTANT  OOOooo...\n\n      We are searching for some new members for our MODEM SECTION, if\n      you are a good TRADER, CARD SUPPLIER or SYSOP and interested in\n      joining a good group than contact one of our Trader''s in one of\n              your LOCAL BBS''s or call one of these Board''s :\n\n            Lord  Wilson     BBS   IA-GHQ     +49-(0)212-ELITE!\n            BlAcK LiNe       BBS   IA-EHQ     +49-(0)211-ELITE!\n            CiViL CrImE      BBS   IA-EHQ     +49-(0)211-733-7593\n            GuIlD oF ThIeVeS BBS   IA-GHQ     +49-(0)2104-826-99\n\n                                                     [A¡RaDDer v3.0 By A¡Rcø]\n\n@endnode\n','\n',char(10)),NULL,NULL,4688,3,0,NULL,NULL,NULL,'scan',1780048545);
INSERT INTO door_catalog VALUES('ia_log1o','IA-LOG1O.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/IA-LOG1O.LHA','RexxMast','XIM','LE-win5-96.exe',NULL,NULL,'IA','N    /__\     C -+---------------------+- T   __ ___    T  | -=+ JdN-LOG-OUT +=- | E  / //  _\   I  |       VERS1.0       |',replace('  I     /\      A   PrEsEnTs Ya ThIs TiMe:\n  N    /__\     C -+---------------------+-\n  T   __ ___    T  | -=+ JdN-LOG-OUT +=- |\n  E  / //  _\   I  |       VERS1.0       |\n  R / //    \\  V  | an official /X tool |\n   /_//_______\ E -+---------------------+-\n       bEST(!) lOGOFF dOOR eVER sEEN!\n        eVEN bETTER tHAN 5d-lOGOFF\n','\n',char(10)),'Jdn-Log.Guide',replace('@database "=GUILD OF THIEVES= - AN ELITE DREAM COMES TRUE!"\n@Node MAIN "=GuILD oF THIEvES="\n                     /\\n                    //\\\n                   //  \\\n__________________//    \\_________________________________________________\n\ _______ ________/      \________ ______________________________________ /\n \\      \\                      //                                     //\n  \\      \\                    //      Jordan-Log-Out Version 1.0!    //\n   \\      \\      JORDAN      //                                     //\n    \\      \\       OF       //    Released on 02.01.94 , Sunday    //\n    //      //  INTERACTIVE   \\                                     \\\n   //      //                  \\       NOW GO FOR THE DOCUMENTATION  \\\n  //      //                    \\                                     \\\n //______//_______        _______\\_____________________________________\\\n/________  _______\      /_______  _______________________________________\\n         ||       \\    //       ||\n         ||        \\  //        ||  @{" Purpose      ? " link "menu"}\n         ||_____/\  \\//  /\_____||  @{" Installation ? " link "menu2"}\n         |______/\\  \/  //\______|  @{" Requirements ? " link "menu3"}\n                  \\    //           @{" Credits      ? " link "menu4"}\n                   \\  //            @{" Support      ? " link "menu5"}\n                    \\//\n                     \/\n@endnode\n\n@node "menu" "What does it do?"\n@toc "menu"\n\n\n                           =WHAT DOES IT DO???=\n\n     Jordan-Logout is a small and tiny ''G'' replacement for your /X BBS\n\n                           Colorful Ansi Outfit\n                          5 or 6 (hehe) Functions\n                        looks more professional :)\n\n\n                 It is very simple but unbelievably Coo| !\n\n\n                            @{" BACK TO MAIN MENU? " link "MAIN"}\n\n@endnode\n\n@node "menu2" "Installation"\n@toc "menu"\n\n\n                            ../INSTALLATION\..\n\n          Nice Question ! Just Copy all files to your directories\n                                and go ...\n\n\n                  Put this shit in your startup sequence\n\n                               rpstart >nil:\n                              rexxmast >nil:\n\n                      *do not 4get to copy the libs*\n\n      IF YOU DONT GET THE INSTALLATION JUST *CLOSE* YOUR BBS!DUMMASS!\n\n@endnode\n\n@node "menu3" "What does it require?"\n@toc "menu"\n\n\n                     =WHAT ABOUT THE REQUIREMENTS???=\n\n                       AMIGA 5oo-4ooo (68ooo-68o4o)\n\n                 AMIEXRESS V2.xX+ / V3.xX (C)LIGHTSPEED 93\n\n                 TWO LIBRARIES (SUPPORTED IN THIS PACKAGE)\n\n                 SOME COMMANDS (SUPPORTED IN THIS PACKAGE)\n\n\n\n\n      This Program will run On *ANY* Machine!Execpt PeeCee Clowns :)\n\n\n@endnode\n\n@node "menu4" "Credits!"\n@toc "menu"\n\n                               =THE CREdZ!=\n\n                        Coding - Jordan/Interactive\n                         Guide - Jordan Interactive\n                          Ansi - Jordan/Interactive\n\n                            CygnusEd - ASDG Inc\n                          Rexx - C=Commodore Inc\n                         Amiexpress - Joseph Hodge\n                      RpStart - Dineen Edwards Group\n\n                     Greets to all IA MEMBERS ^ to...\n                 Deltaforce/Blue/Coroplex/Ceterus/Sigma Seven\n          Dr.Dre/Siegel/Byteandi/Floppyhans/Kaoz/GEM/Slaze/Exocet\n        Scottie/Maz/Hamster/Irata and all I learned to know through\n                         all the years in scene :)\n\n\n                            @{" BACK TO MAIN MENU? " link "MAIN"}\n\n@endnode\n@node "menu5" "Support"\n@toc "menu"\n\nINSERT INTO door_catalog VALUES('ia_opa10','IA-OPA10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/IA-OPA10.LHA','rexxdoor','XIM','RexxMast',NULL,'Silencio/InterActive','IA','N    /__\     C -+---------------------+- T   __ ___    T  |   Operator Pager!   | E  / //  _\   I  |      DOOR V1.0      |',replace('  I     /\      A   PrEsEnTs Ya ThIs TiMe:\n  N    /__\     C -+---------------------+-\n  T   __ ___    T  |   Operator Pager!   |\n  E  / //  _\   I  |      DOOR V1.0      |\n  R / //    \\  V  |     FOR /X3.xx+     |\n   /_//_______\ E -+---------------------+-\n  [##] 1994 (C)By Silencio/InterActive [##]\n','\n',char(10)),'OPager.Guide',replace('@database Operator Pager Door V1.0.Guide\n\nCopyright (c) 1994 by Silencio of InterActive\n\n@node MAIN "OPage 1.0"\n\n ###### ##  ## ###### ##### #####  ###### ##### ###### ###### ##    ## #####\n ###### ##  ## ###### ##### #####  ###### ##### ###### ###### ##    ## #####\n   ##   ### ##   ##   ##    ##  ## ##  ## ##      ##     ##   ##    ## ##\n   ##   ######   ##   ####  ##  ## ##  ## ##      ##     ##   ##    ## ####\n   ##   ## ###   ##   ####  #####  ###### ##      ##     ##    ##  ##  ####\n   ##   ## ###   ##   ##    ####   ###### ##      ##     ##    ##  ##  ##\n ###### ##  ##   ##   ##### ##  ## ##  ## #####   ##   ######   ####   #####\n ###### ##  ##   ##   ##### ##  ## ##  ## #####   ##   ######   ####   #####\n\n\n                                 !Contents!\n\n                    @{" What is Operator Pager Door ?  " LINK suxa}\n                    @{"    Lord Wilson BBS Numba ?     " LINK suxd}\n                    @{"        Installations!          " LINK suxe}\n                    @{"   I send Kewl Greetings to: !  " LINK suxc}\n\n@endnode\n@node suxa "What is ..."\n\n\n              (**)-- What is Operator Pager Door V1.0 ? --(**)\n\n             This is a nice  DOOR, ask for the System Operator.\n      In the Rexx Source ya can type in Names ya can always ask\n                              for the Sysop!\n\n                        Warning -- Case Sensetive --\n\n               This nice tool is fine working with /X3.xx+ !\n\n@endnode\n@node suxe "Guide Documentation for the Installations..."\n\n\n              (**)-- Install Operator Pager Door V1.0 --(**)\n\nTo Install Diz Door you have to copy Files they Included Files in my Archive\n                       to ya Directory Called "BBS:"\n\n\n@endnode\n@node suxd "Lord Wilson BBS Numba..."\n\n\n                   (**)-- Call my BBS Lord Wilson --(**)\n\n\n                              FoR BuG RePoRTS\n                                SuGGeSTioNS\n                                     or\n                                NeW iDeaS...\n\n                   Lord Wilson BBS call +49(0)212-2052xx\n\n@endnode\n@node suxc "Sum Kewl Greetinx !"\n\n\n                   (**)-- Kewl Greetings flies to: --(**)\n\n\n           All InterActive Members, and to the following others:\n\nJordan/IA                          Thanx for ya help in AREXX Coding!\nDR.Dre/TRSI                        Thanx also for ya help!\nCelic/SCEPTIC                      Not enough Stuff for me .. he\nMcLoud/TRSI                        Hy.. Hau Rein Older.. Mach Weiter So\nBlue/INDEP.                        Fast - Faster - Black Line\n\n   and all the others i have not written here.. becoz i have no more time\n                  to write the Complete Greetinx-List ...\n\n@endnode\n','\n',char(10)),NULL,'auto-added',84868,2,0,NULL,NULL,'ia_opa10','scan',1780048545);
INSERT INTO door_catalog VALUES('ia_spd10','IA-SPD10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/IA-SPD10.LHA','LhA','XIM','HuntVirus',NULL,'Silencio/InterActive','IA','N    /__\     C -+---------------------+- T   __ ___    T  |   SYSTEM PASSWORD   | E  / //  _\   I  |      DOOR V1.0      |',replace('  I     /\      A   PrEsEnTs Ya ThIs TiMe:\n  N    /__\     C -+---------------------+-\n  T   __ ___    T  |   SYSTEM PASSWORD   |\n  E  / //  _\   I  |      DOOR V1.0      |\n  R / //    \\  V  |     FOR /X3.xx+     |\n   /_//_______\ E -+---------------------+-\n  [##] 1994 (C)By Silencio/InterActive [##]\n','\n',char(10)),'Syspw.Guide',replace('@database System Password Door V1.0.Guide\n\nCopyright (c) 1994 by Silencio of InterActive\n\n@node MAIN "SysPw 1.0"\n\n ###### ##  ## ###### ##### #####  ###### ##### ###### ###### ##    ## #####\n ###### ##  ## ###### ##### #####  ###### ##### ###### ###### ##    ## #####\n   ##   ### ##   ##   ##    ##  ## ##  ## ##      ##     ##   ##    ## ##\n   ##   ######   ##   ####  ##  ## ##  ## ##      ##     ##   ##    ## ####\n   ##   ## ###   ##   ####  #####  ###### ##      ##     ##    ##  ##  ####\n   ##   ## ###   ##   ##    ####   ###### ##      ##     ##    ##  ##  ##\n ###### ##  ##   ##   ##### ##  ## ##  ## #####   ##   ######   ####   #####\n ###### ##  ##   ##   ##### ##  ## ##  ## #####   ##   ######   ####   #####\n\n\n                                 !Contents!\n\n                    @{" What is System Password Door?  " LINK suxa}\n                    @{"    Lord Wilson BBS Numba ?     " LINK suxd}\n                    @{"     Install the System PW      " LINK suxb}\n                    @{"        Installations!          " LINK suxe}\n                    @{"   I send Kewl Greetings to: !  " LINK suxc}\n\n@endnode\n@node suxa "What is ..."\n\n\n              (**)-- What is System Password Door V1.0? --(**)\n\n  This is a nice System Passwort DOOR, this ask ya for a System Password.\n  Ya have three Chances to type in the right PW. Ya can change the PW when\n       ever ya want in the "DOORS:IA/SILC-SYSPW/SYSPW.SPW" cfg.file.\n\n                        Warning -- Case Sensetive --\n\n       This nice tool works only without the editing in "NodeX.info.\n                  This tool is fine working with /X3.xx+ !\n\n@endnode\n@node suxe "Guide Documentation for the Installations..."\n\n\n              (**)-- Install System Password Door V1.0 --(**)\n\nTo Install Diz Door you have to copy Files they Included in my Archive\n                       to ya Directory Called "BBS:"\n\n\n@endnode\n@node suxb "Install the System PW..."\n\n\n                 (**)-- Install the System Password --(**)\n\n\n    Open the NodeX.info on the WorkBench with RIGHT AMIGA & I and delete\n                   diz TOOLTYPE "SYSTEM_PASSWORD=??? ...\n\n     Then create a file called "BBSTITLE.TXT" and edit this lines in it:\n\n-------------------< CUT\n~\n~CC_AUPWCH-SYS\n-------------------< CUT\n\n   If ya have diz made move this file into the "NodeX" Directory or into\n            "BBS:Screens/NodeX/" .. Ok and diz do for all Nodes\n\n@endnode\n@node suxd "Lord Wilson BBS Numba..."\n\n\n                   (**)-- Call my BBS Lord Wilson --(**)\n\n\n                              FoR BuG RePoRTS\n                                SuGGeSTioNS\n                                     or\n                                NeW iDeaS...\n\n                   Lord Wilson BBS call +49(0)212-2052xx\n\n@endnode\n@node suxc "Sum Kewl Greetinx !"\n\n\n                   (**)-- Kewl Greetings flies to: --(**)\n\n\n           All InterActive Members, and to the following others:\n\nJordan/IA                          Thanx for ya help in AREXX Coding!\nDR.Dre/TRSI                        Thanx also for ya help!\nCelic/SCEPTIC                      Not enough Stuff for me .. he\nMcLoud/TRSI                        Hy.. Hau Rein Older.. Mach Weiter So\nBlue/INDEP.                        Fast - Faster - Black Line\n\n   and all