INSERT INTO door_catalog VALUES('ice_sc10','ICE_SC10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ICE_SC10.LHA',NULL,'XIM','_________________________',NULL,NULL,'ICE','/\__   _\   ______/  ____/\ \/_/\  \ \  \____/  ____/\/ \_\  \_\  \__/  /____\/',replace('  _________________________\n /\__   _\   ______/  ____/\\n \/_/\  \ \  \____/  ____/\/\n    \_\  \_\  \__/  /____\/\n    /\______\___/______/\\n    \/______/___\______\/\n     AmIx IcE-ScAn v1.0\n     by: ArChOn of I.c.E\n','\n',char(10)),'SCAN.DOC',replace('CONF SCAN v1.0\n--------------\nWhat is it?\nIt allows users to choose whether or not they want to scan for new files\nwhen joining a conference!\n\nInstallation\nJust add the sc.info into ur BBS:commands/bbscmd/ dir\nPut SCAN.rexx into doors:ice-scan/ dir\ncopy (or add onto your own)BULL10.txt into the conf directory of the confs\nthat u want this KEwl door to start :).\n\nand thats all.....\n\nPlease report bugs to Archon (Sysop of U4EA bbs +354-25-4828)\n','\n',char(10)),NULL,NULL,4162,3,0,NULL,NULL,NULL,'scan',1780048545);
INSERT INTO door_catalog VALUES('ice_want','ICE_WANT.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ICE_WANT.LHA',NULL,'XIM','_________________________',NULL,NULL,'ICE','/\__   _\   ______/  ____/\ \/_/\  \ \  \____/  ____/\/ \_\  \_\  \__/  /____\/',replace('  _________________________\n /\__   _\   ______/  ____/\\n \/_/\  \ \  \____/  ____/\/\n    \_\  \_\  \__/  /____\/\n    /\______\___/______/\\n    \/______/___\______\/\n     AmIx UsErWaNts v1.0\n     by: ArChOn of I.c.E\n','\n',char(10)),'want.doc',replace('UseRWaNts v1.0\nby: ArChoN of U4EA BBS (+354-25-4828)\n\nWhatisit?\nAn /X tool to add or view user wants...\n\nHow to install\nMake the directory ''doors:want/''  then copy want.rexx and wanted.txt in there\ncopy the want.info icon into the ''bbs:commands/bbscmd/'' directory\n\nThats it!\n\nPlease contact me on U4EA with comments!\n\nHave fun!\n','\n',char(10)),NULL,NULL,5359,4,0,NULL,NULL,NULL,'scan',1780048545);
INSERT INTO door_catalog VALUES('ice_who_','ICE_WHO_.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ICE_WHO_.LHA',NULL,'XIM','_________________________',NULL,NULL,'ICE','/\__   _\   ______/  ____/\ \/_/\  \ \  \____/  ____/\/ \_\  \_\  \__/  /____\/',replace('  _________________________\n /\__   _\   ______/  ____/\\n \/_/\  \ \  \____/  ____/\/\n    \_\  \_\  \__/  /____\/\n    /\______\___/______/\\n    \/______/___\______\/\n       AmIx WHO! v1.0\n     by: ArChOn of I.c.E\n','\n',char(10)),'WHO.doc',replace('                                      WhO! v1.0\n                               First Release by ArcHon\n                                  For the GREAT /X\n                               Call U4EA  +354-25-4828\n\nSPREAD IT!!!!\nFor some reason (if you know why tell me!!) I could not get any ''WHO'' doors to\nwork on Amix, Including the internal!!!\nSo I had to make this tool..\n\nInstallation:\nCopy the who.info into your BBS:commands/bbscmd/ dir...\nCopy WHO.rexx into doors:who/ dir\nLoad WHO.REXX into any text editor and change the TNODE to equal how many\n  nodes you have (or how many nodes you want to pretend to have :).\nthats all.....\n\nPlease if u find bugs contact me, better yet.. fix em and give me an update :)\n\nWell thats all...\nHope you like it....\n','\n',char(10)),NULL,NULL,4293,3,0,NULL,NULL,NULL,'scan',1780048545);
