INSERT INTO door_catalog VALUES('imp_wl13','IMP_WL13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/IMP_WL13.LHA',NULL,'XIM','Wall.XIM',NULL,'[____][_','IMP','[____]        /\                    [____][_ __][_] /X    / /\    BrickWall V1.3 [_][____ [____] Doors \   \   Written By     [____][_',replace('__][____][____][____][____][____][____][____\n[____]        /\                    [____][_\n__][_] /X    / /\    BrickWall V1.3 [_][____\n[____] Doors \   \   Written By     [____][_\n__][_]        \/ /   Grand Admiral  [_][____\n[____]         \/                   [____][_\n__][_] /\   /\   Lots of Features!! [_][____\n[____] \ \  \/                      [____][_\n__][_]  \ \   Nasty Wall Clone in C [_][____\n[____]__ \/___  ____  ____  ____  __[____][_\n__][____][____][____][____][____][____][____\n','\n',char(10)),'Docs.txt',replace(' ____  ____  ____  ____  ____  ____  ____  ____  ____  ____  ____  ____  _\n[____][____][____][____][____][____][____][____][____][____][____][____][_]\n[_][____][____][____][____][____][____][____][____][____][____][____][____]\n[____][____]                                                   [_][____][_]\n[_][____][_] Imperial Software''s                    An /X Door [____][____]\n[____][____]                                                   [_][____][_]\n[_][____][_]                                                   [____][____]\n[____][____]            B R I C K   W A L L V1.3               [_][____][_]\n[_][____][_]                                                   [____][____]\n[____][____]            Coding By Grand Admiral                [_][____][_]\n[_][____][_]                                                   [____][____]\n[____][____]          DeadLight BBs (01274) FiNd iT            [_][____][_]\n[_][____][_] ____  ____  ____  ____  ____  ____  ____  ____  __[____][____]\n[____][____][____][____][____][____][____][____][____][____][____][____][_]\n[_][____][____][____][____][____][____][____][____][____][____][____][____]\n\nWelcome to Brick Wall V1.3\n\nThis program is (c)1995 Imperial Software.\n\nThis program is Public Domain, in other words FREE.\n                                              ^^^^\n\nArchive Contents\n~~~~~~~~~~~~~~~~\nIn this archive there should be:-\n\n     BBS/Commands/BBSCmd/Wall.info      Command For AmiExpress\n     BBS/Doors/ImpWall/Wall.XIM         Actual Door Program\n     BBS/Doors/ImpWall/Docs.txt         This Documentation\n     file_id.diz                        The File ID For BBS''s\n\nAnything else in this archive is bollox.\n\n\nInstallation\n~~~~~~~~~~~~\nIts very easy just copy whats in the BBS directory of my archive into your\nBBS directory and the door is fully working.\nPreferences are controlled by the door, so you need to run the door from\nthe BBS and select ''P'' for prefs.\n\nExample of how to copy -\n\nCOPY RAM:BBS/#? BBS:\n\nEasy eh?\n\n\n\n\n\nOptions\n~~~~~~~\nThere are two sets of options, User Options and Sysop Options.\n\nUser Options.....\n\n  (Y)es          This allows the user to enter a message. If the user presses\n                 <ENTER> without typing anything, then it will go straight\n                 back to the options.\n                 If a message has been entered, the user is then asked what\n                 colour to put the message in.\n                 Once that is done, the user is asked if they want to be\n                 anonymous or change handle. If they press enter their own\n                 name is used.\n\n  (F)orward      Moves the wall forward through the text.\n\n  (R)everse      Moves that wall backwards through the text to see oldest\n                 messages.\n\n  (L)ast         Moves wall to the lastest messages.\n\n  (I)nfo         Information about the program.\n\n  (V)iew         Show the real names that users have changed to anonymous\n                 or changed handle.\n\n                 NOTE: This option is definable in preferences. Allows the\n                 sysop to allow the users to use it or make it SYSOP ONLY.\n\n  (S)ysop        Show sysop commands. ONLY AVAILABLE WITH SYSOP ACCESS\n\n\nSysop Options.....\n\n  (P)refs         Change Preferences. You can change a number of preferences\n                  and when you have finished changing prefs just press <ENTER>\n                  at the prompt and the prefs will automatically be saved.\n\n                  (1) Change Enter Message Title\n                  (2) Change User Failed To Enter Message\n                  (3) Change Colour Of The Bricks\n                  (4) Change Colour Of User Name\n                  (5) Change Colour Of Anonymous\n                  (6) Allow User To Use View Option (Yes / No)\n                  (7) Draw Bricks In The Wall (Yes / No)\n                  (8) Change Deleted Message Colour\n\n  (D)elete        Delete a message a user has entered.\n\n  (E)dit          Edit a message a user has entered. Allows you to change the\n                  colour of the message as well. Keeps original user''s name.\n\n  (N)ormal Mode   Return to normal options.\n\n\n\nAll files that the program ''Creates/Loads/Save'' are located in DOORS:ImpWall/\n\n\n\n\nBarring Users\n~~~~~~~~~~~~~\nThis function allows you to bar users from entering messages on the wall.\nThey can look, but can''t touch.\n\nBarring users is very simple, You will need to create a file called\nDOORS:ImpWall/Wall.Barred\n\nThis is a text file that you edit by entering the users name and entering\nthe reason why you have banned them on a line below. Eg...\n\nFred Bloggs                           <--- Users Name\nYou have a very stupid Name           <--- Reason\n\nYou are allowed an unlimited list of names.\nNOTE: Having Hundreds of names on the barred list might cause the program\nto slow down a bit.\n\n\n\nDisclaimer\n~~~~~~~~~~\nThis program is 100% backdoor free. If in doubt phone DeadLight BBS and\ndownload the original file.\n\nThe programmer cannot and will not be responsible for any kind of damage that\nmay occure to your system directly or indirectly from use of this program.\n\n\n\n\nI hope you like this little program of mine. If you have any ideas which\ncould be used in this program or any bugs that you find, contact me at\nDeadLight BBs\n\n(c)1995 Imperial Software (Communication Division)\n\n\nHistory\n~~~~~~~\nV1.0   First Release\n\nV1.1   Modified coding to cope with preferences\n\nV1.2   Modified colour selecting to cope with Remote User or Local User.\n       In Local the red and white were swapped round.\n\n       Altered options, now have a normal options and sysop options separate.\n\nV1.3   Added users barred from entering messages on the wall. Just a simple\n       text file to edit by putting users name and reason for barring them.\n\n','\n',char(10)),NULL,'auto-added',18880,1,0,NULL,NULL,'imp_wl13','scan',1780048553);
