INSERT INTO door_catalog VALUES('ins_ba12','INS-BA12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/INS-BA12.LHA','bLACK^aDDER','XIM','LE-win5-96.exe',NULL,NULL,'INS','/__\___|   _ /   ____/__  .___|   _ /Sk¡n /    \  \   //____   /  /__|   \   //_______ \____/   \ ./______ /  /\   \   \ ./  _____/',replace('  /\    :______/\______        :______       \n /__\___|   _ /   ____/__  .___|   _ /Sk¡n   \n/    \  \   //____   /  /__|   \   //_______ \n\____/   \ ./______ /  /\   \   \ ./  _____/ \n   _|___\  /      \/_________\_\  /  _____/  \n::::|::::\/:: P r e s e n t s ::\/_______/:: \n::  bLACK^aDDER v1.02 ©1995 mARX/iNSANE!  ::\n::                                        ::\n::       - 100% PURE FAST ASM CODE -      ::\n::                                        ::\n::  - kEWLEST tXTADDER oF tHE cENTURY! -  ::\n::::::::::::::::::::::::::::::::::::::::::::\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                                                .------''\n             `------------------------------------------------''\n','\n',char(10)),NULL,'auto-added',12383,5,0,NULL,NULL,'ins_ba12','scan',1780048553);
INSERT INTO door_catalog VALUES('ins_bs10','INS-BS10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/INS-BS10.LHA','Buy&Sell','XIM','kRm_____:  .______________.  :______',NULL,'Metal/Insane','INS','-_/ _/  \ _/  _______ _/  \ _/  ___/-------- \_ \_  \\\____ \_  _ \_  \\\_  _/_. iNSANE |  |  |\ |  !  |  |  |  |\ |  !  | ------',replace('kRm_____:  .______________.  :______\n-_/ _/  \ _/  _______ _/  \ _/  ___/--------\n \_ \_  \\\____ \_  _ \_  \\\_  _/_. iNSANE\n  |  |  |\ |  !  |  |  |  |\ |  !  | ------\n  ¦  l__|  l__   l__|  l__|  l__   |  1995\n--:  ·--l__|--\__|--l__|--l__|--\__|--------\n----------------[ Presents ]----------------\n        Buy&Sell V1.00 for /X V3.x+\n  Coded in 100% Assembler by: Metal/Insane\n','\n',char(10)),'BuySell.Guide',replace('@database Buy&Sell.guide\n@$VER: Buy&Sell Document (23.03.95) - Editors: Metal&Cluster\n\nThis is a document in the AmigaGuide format.  To read it, use either\nAmigaGuide, MultiView, or any other AmigaGuide compatible hypertext\nbrowser.\n\n@node Main "Contents"\n\n===============================================================================\n=                                                                             =\n=                       Buy&Sell V1.00 by: Metal/Insane                       =\n=                                                                             =\n=                    MC68000/020 Code for AmiExpress V3.x+                    =\n=                                                                             =\n===============================================================================\n\n                                @{" Introduction " link Introduction}\n                                @{" Requirements " link Requirements}\n                                @{" Installation " link Installation}\n                                @{" ToolTypes    " link ToolTypes}\n                                @{" Last Words   " link Addys}\n\n@endnode\n\n\n@node Introduction "Introduction Text"\n\n@{b}Buy&Sell@{ub} is a AmiExpress XIM Door coded in 100% Assembler.\n\nThe reason why I decided to develope  and now 5 months later  release\nthis door, is because a  sysopfriend of mine - Cluster  (The sysop of\nINSANITARY  BBS)  wanted  to  have a  Buy&Sell advertisment door. So,\nI made this door for him and now after several months of usage at his\nBoard we''ve got great response about it''s function as a vital part of\na BBS for anyone who wishes to have a Buy&Sell advertising conf., and\nso we have now decided to share this great door with you other sysops\n\nNow,I sincerely hope that you ain''t that stupid wondering in what way\nsuch a door like this one could ever make it more comfortable for the\nusers in any way, so i''ve left the ''whyuse-part'' out of this docfile.\n\nIf you got some ideas, suggestions or bugreports to make, or just for\nthe pure fun of sharing your thoughts and wonders  about life and the\nscene, don''t you hesitate to write me a message  at any of the Insane\nBoards.. Who knows, maybe you  got this  great idea of yours of yet a\ngreat Amix-Door that I might be interested in developing...\n\n@endnode\n\n\n@node Requirements "Requirements Text"\n\n@{b}Requirements.@{ub}\n\n· OS 2.0+\n· AmiExpress V3.x+\n\n@endnode\n\n\n@node Installation "Installation Help"\n\n@{b}Installation.@{ub}\n\nJust extract the Lha Package or Copy all Dirs/Files into  your  "BBS"\nDirectory, and you''ll have it perfectly installed.\n\nHere we have a list of them files who should be lying in them Directories.\n(located in BBS:)\n\nCommands/BBSCmd/BS.info      <- Info File for /X to execute when you type "BS"\nDoors/Buy&Sell/Buy&Sell      <- The Groovy DOOR.\nDoors/Buy&Sell/Buy&Sell.info <- The Info file which consists the preferences.\n\n@endnode\n\n\n@node ToolTypes "ToolTypes Info"\n\n@{b}ToolTypes.@{ub}\n\nNAME.LEN=12                  <- 12 = Max Amount of Characters that the NAMES\n                                     will consist of.\nB/S.LEN=4                    <-  4 = Max Amount of Characters that B/S will\n                                     consist of.\nARTICLE.LEN=32               <- 32 = Max Amount of Characters that the user\n                                     will have available for describing his\n                                     offers/needs.\nPRICE.LEN=8                  <-  8 = Max Amount of Characters that the user can\n                                     use for writing his suggested price in.\nAMOUNT.LEN=6                 <-  6 = Max Amount of Characters that the user can\n                                     use to advert the amount of the ware(s)\n                                     he/her wishes to buy or sell.\n\nNAME.DESC=Name/Alias         <- "Name/Alias" is the Column Description for\n                                 the name of the users.\nB/S.DESC=B/S                 <- "B/S" is the Column Description of the users\n                                 desires wether to Buy/Sell.\nARTICLE.DESC=Article/Product <- "Article/Product" is the Column Description\n                                 of the Users ware(s) description line.\nPRICE.DESC=Price             <- "Price" is the Column Description of the\n                                 suggested price(s) from the User.\nAMOUNT.DESC=Amount           <- "Amount" is the Column Description of the\n                                 amount of stuff he/she wishes to Buy/Sell.\n\nBUY.TEXT=BUY                 <- "BUY" is the Text which will be Printed in the\n                                 area/row (B/S) if the user choosed to BUY.\nSELL.TXT=SELL                <- "SELL" is the Text which will be Printed in the\n                                 area/row (B/S) if the user choosed to SELL.\n\nTOPLOGO=DOORS:Buy&Sell/BSLogo<- "DOORS:Buy&Sell/BSLogo" The TopLogo which will\n                                 be shown at the top of the "OutPut" file and\n                                 also when a User executes the Door.\nOUTPUT=BBS:BuySell/Bull30.txt <- "BBS:BuySell/Bull30.txt" is the filename of\n                                  the OutPut text.\n\n@endnode\n\n\n@node Addys "Authors Last Words..."\n\nWell, I guess there ain''t much more left to say except that I sincerely\nhope you will find this door useful and that you make the best out of it.\n\nTo reach me or any other of the Insane /X developers, you should dial our\n\n    - World HeadQuarter BBS - INSANITARY at +46-8-7595847 (Sweden) -\n\nBtw: Check out my Request door if you liked this one. It looks almost alike,\n     allthou there are different  configurations and it consequently results\n     in a more suitable look for a request-conference ...\n\n@endnode\n\n','\n',char(10)),NULL,NULL,11590,4,0,NULL,NULL,'ins_bs10_buy_sell','scan',1780048553);
INSERT INTO door_catalog VALUES('ins_cc11','INS-CC11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/INS-CC11.LHA','catcat','XIM','catcat','1.1',NULL,'INS','|    The best logoff door ever! (DD)   | __|____   ·    _______.   _ ___ .____    | \     /__ :___/ ______|____    \|  _/____|__',replace('  o-------- -- - CAtCAt V1.1 - -- -------o\n  |    The best logoff door ever! (DD)   |\n__|____   ·    _______.   _ ___ .____    |\n\     /__ :___/ ______|____    \|  _/____|__\n \___/   \|   \_____  \  _ \   \\  | ___   /\n |   |   \\   |   ____/ _/  \_ |\__| \____/_\n |___|   |\___|___/ _ __\    /_|  \____    /\n _ __ ___|               \__/ <elvis> \___/\n','\n',char(10)),'catcat.doc',replace('\n                  CatCat V1.1 by Hydra/Insane & Daft/Selleri\n                  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nWhat''s this?\n~~~~~~~~~~~~\n	This is just a G-replacement for DayDream BBS. It has cursorkey\n	support and all the features you expect from the descent logoff\n	door.\n\nInstall\n~~~~~~~\n	This is DDDP door. If you don''t know how to install them, RTFM\n	or buy /X.\n\n	Copy Display/Iso/** to DayDream:Display/Iso/.\n\nHistory\n~~~~~~~\n	V1.0 Initial release.\n\n	V1.1 Fixed some minor bugs.\n	     Deleted accidently the sourcecode, so don''t expect a new\n	      version.\n\nContact author\n~~~~~~~~~~~~~~\n	[email removed] or Humanoid Invasion, +358-81-5409139. DD WHQ.\n\nCredits\n~~~~~~~\n	Based on E-Test by daft/selleri, finished by Hydra/Insane.\n	Yes, Hydra coded DD too :)\n\n	Ansi by zeus. (Terveisiä Otsolle)\n\nRespect.\n~~~~~~~~\n','\n',char(10)),NULL,'auto-added',8680,5,0,NULL,NULL,'ins_cc11','scan',1780048553);
INSERT INTO door_catalog VALUES('ins_chat','INS-CHAT.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/INS-CHAT.LHA','EXE','XIM','EXE',NULL,'someone??!?!','INS',NULL,replace('chAT dOOr bY someone??!?!\n','\n',char(10)),'AT&T.TXT',replace(' \n      CALL TO INSANE FINNISH HEADQUARTERS CALLED\n   ________  ____________________    _________\n   \_____  \ \   _________   \   \___\    \   \____ SYSOP : SPLIT / INSANE\n    \       \ \____   \   \   \   \   \    \    __/_      CO-ESKIMOS :\n     \   \   \ \   \   \   \   \   \   \    \   \   \  MAD''VISION / INSANE\n      \   \   \ \   \   \   \   \   \   \    \   \   \ KRISTEN / AFL & DCN\n       \   \   \ \   \   \   \   \   \   \    \   \   \\n        \   \   \ \   \   \   ___/\   \   \    \   \   \\n         \___\__/  \______/\___\   \______/\___/\______/\n                   \n      ________________________________________________   LATEST WARES ON \n      \   _____   _____   _____        ____    ____   \  AMIGA & CONSOLE \n       \____   \    __/_   \   \   \   \   \   \   \   \ AMIEXPRESS 3.10\n        \   \   \   \   \   \   \   \   \   \   \   \   \USR HST DS V32BIS\n         \   \   \   \   \   \   \   \   \   \   \   \   \FOREIGN USERS!\n          \   \   \   \   \   \   \   \   \   \   \   \   \\n           \   \   \   \   \   \   \   \   \   \   \   \   \\n            \______/\______/\______/\______/\___\__/\______/VsL\n \n  [ LATEST IMPORTS ON AMIGA & CONSOLE ]  [=====> +358-42-745603 <=====]\n \n','\n',char(10)),NULL,'auto-added',26371,7,0,NULL,NULL,'ins_chat','scan',1780048553);
INSERT INTO door_catalog VALUES('ins_mc10','INS-MC10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/INS-MC10.LHA','MCOMMENT10','XIM','kRm_____:  .______________.  :______',NULL,'NIGHTSHADE','INS','-_/ _/  \ _/  _______ _/  \ _/  ___/-------- \_ \_  \\\____ \_  _ \_  \\\_  _/_. iNSANE |  |  |\ |  !  |  |  |  |\ |  !  | ------',replace('kRm_____:  .______________.  :______        \n-_/ _/  \ _/  _______ _/  \ _/  ___/--------\n \_ \_  \\\____ \_  _ \_  \\\_  _/_. iNSANE \n  |  |  |\ |  !  |  |  |  |\ |  !  | ------ \n  ¦  l__|  l__   l__|  l__|kRm_____: /X DIV \n.-:  ·--l__|--\__|--l__|--l__|--\__|-------.\n|       NS-MULTICOMMENT V1.0 [REL 2]       |\n| THIS COOL /X DOOR IS CODED BY NIGHTSHADE |\n| SIMPLY THE BEST FOKKING MC DOOR WITH ALL |\n|      YOU NEED AND NO OTHER LAME SHIT     |\n`------------------------------------------''\n','\n',char(10)),'MCOMMENT10.GUIDE',replace('@database "NSDoor"\n@Node Main "Cool"\n:::8888M::::888::::::88:::8888888::::::::Mm   ___/\  __________________ _\n:8888M::::::88:::::::8:::::888888:::M:::::M        \/-- -\n:888MM:::::::8::::::::::M::::8888::::M::::M            wASTELANDs!\n:88:M:::::::::8::::::::::M:::8888::::::M::M\n888:M:::::::::::::::::::::M:8888:::::::::M:      -[WE ARE HERE FOR YOU]-\n88::M:::::::::::::::::::::MM:88::::::::::::M\n88::M:::::::::*88*:::::::::M:88::::::::::::::M    N#1 +468-157472  33k6\n88::M::::::::88@@88::::::::M::88::::::::::::::M   N#2 +468-6124141 28k8\n88::MM:::::::88@@88::::::::M:::8::::::::::::::*8\n:8::MM::::::::*88*:::::::::M:::::::::::::::::88@@ NiGHTSHADE/INS IS BOSS\n:::::MM:::::::::::::::::::MM:::::::::::::::::88@@\n::::::MM:::::::::::::::::MM::M::::::::::::::::*8  2 GB OF WARES TO LEECH\n:::::::MMM::::::::::::::MM:::MM:::::::::::::::M     NO RATIOS -> TRUST\n::::::::MMM::::::::::MMMM:::::MM::::::::::::MM    0-1 DAYS AMIGA AND THE\nM:::::::::MMMMMMMMMMMMM::::::::MMM::::::::MMM      FAMOUS OLD GOLD CONF\nMM:::::::::::MMMMMMM:::::::::::::MMMMMMMMMM   __________________  /\____\n8MM::::::::::::::::::::::::::::::::MMMMMM                   - --\/\n\n   @{" [ READ DOCUMENTATION - READ DOCUMENTATION - READ DOCUMENTATION ] " Link "Door"}\n@EndNode\n\n@Node "Door"\n@Title "Manual By NiGHTSHADE/iNS"\n              /\       ___.                    ___.\n            _/  \____ |   |_________/\ ______ |   | _________\n            \___|    \|   \    __  /  \\_    \|   |/   _____/\n         Mb /   |     \   |\___  \/  | \|     \   /   __/ \\n           /    |   \     |   /   \  _  \   \    /    |    \\n          /     |___|\    |_______/  |___\__|\   \__________\\n     .---/______|-----\___|----/_____|--------\___|---------------.\n     |           NS-Multicomment Amiga-Guide manual (c)           |\n     |      Code By NiGHTSHADE/iNS & Raw Design by -Shade/Ins     |\n     `------------------------------------------------------------''\n\n                         @{" What is this Door     " Link "What"}\n                         @{" Door Installations    " Link "Install"}\n                         @{" Door Usages           " Link "DoorUsage"}\n                         @{" Door History          " Link "History"}\n                         @{" Door Beta Testers     " Link "Beta"}\n                         @{" Other INS Doors       " Link "Other"}\n                         @{" The Greetings         " Link "Greetings"}\n                         @{" Contact NiGHTSHADE    " Link "ContactNS"}\n                         @{" Original File_ID.Diz  " Link "File_ID"}\n\n     *------------------------------------------------------------*\n@EndNode\n\n@Node "What"\n@Title "What is NS-Multicomment"\n\nNS-Multicomment is a powerful multicomment door who is designed to\nreplace the ''C'' command, it will bring you the following :\n\n* You can use nick names in the menu and real mail names when\n  it''s time to mail. \n* Built in Configurator - No damn SLOW TEXT files or sucking icons.\n* Statistics (No. of mail received).\n* FAST\n* Nice Design\n* Cursor key handling\n* Smart field limiter so the comment field will be as long as possible.\n* The Cosysops are able to change the comment lines etc.. as many times\n  as they like.\n* Built in ''account'' editor, the sysop can edit all and\n  all other can edit their own.\n* RELIABLE (Tested from OS 2.05 to 3.1 and from 0x0 to 040)\n* No enforcerhits at all when tested!\n\nThat''s Enough - Lets install instead!\n\n@EndNode\n\n@node "Install"\n@Title "The /X ToolTypes Information"\n\n  - THIS PART IS TAKEN FROM THE Original /X AMIGA GUIDE AND ARE MODIFIED -\n  ========================================================================\n  <module>.INFO        - This ICON defines a MODULE for /X. The Name of\n                         the <module> should be the same as the executing\n                         in MainMenu prompt, and should be in one of the\n                         three Directories. This icon should be placed\n                         in the BBS:Commands/BBSCmd directory.\n\n     The following directories are placed under the <BBS Path>:Commands/\n     path.\n\n     a> BBSCmd     - Modules in this directory are allowed to be\n                     executed from any menu prompt or MCI text file.\n\n     b> SYSCmd     - Modules in this directory are only accessible by\n                     MCI text files and internal BBS operations.\n\n     c> CONF(x)    - Modules in this directory are allowed to be\n                     executed from conference (x) menu prompt or from\n                     any MCI text file in conference (x).\n     d> Node(x)    - Modules in this directory are allowed to be\n                     executed from node (x) menu prompts or from any\n                     MCI text file in Node (x).\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  The ToolTypes of the <module(s)> :\n\n  ACCESS= <numb>       - tells /X the access level required to run this\n                         module. This option is ignored for internal\n                         Module options.\n\n  INTERNAL= <command>  - Specifies if you want to have this Module the\n                         same as a internal AmiExpress command. if you\n                         choose this option you don`t need the following\n                         tool types.\n\n  LOCATION= <string>   - Specifies the location of the Module.\n\n  MULTINODE=YES        - Tells /X if the module may be simultaneously\n                         accessed from other nodes, this door is multinode\n                         compatible. Options for this tool type\n                         are <YES/NO>.\n\n  PASSWORD= <string>   - Force the user to enter password before executing\n                         this module. This option is case sensitive which\n                         means that "OK" and "OK" isn''t the same.\n\n  PRIORITY=SAME        - Let''s you set the priority of the door. If you use\n                         PRIORITY=SAME, it will use the same Priority\n                         that express uses. For best result of the door use\n                         the ''SAME'' option.\n\n  QUICKMODE            - This simply tells AmiExpress _not_ to run the Module\n                         in question if the user has logged onto the BBS\n                         using the QUICK LOGON option.\n                         If you want all the users to be able to use this\n                         door enev if quick logged on then disable this option\n                         by not using this tooltype.\n\n  STACK=4096           - tells /X the stacksize to use when launching this\n                         module. Default is 4096.\n\n  TYPE=XIM             - tells /X which type of module it is to support:\n                         XIM = /X Standard Module, this door is a XIM door.\n\n  TRAPON               - This makes LOGON Output go to a Log for Error\n                         Checking, you don''t need this option, just\n                         fragments you''re hd a lot and slows it down!\n  \n=======================================================================\n@EndNode\n\n@Node "DoorUsage"\n@Title "Door Usage"\n=============================================================================\n\n How to use the NS-Multicomment Door :\n\n  Step 1 : Install the door by copying the supplied files\n           (reefer to the main /X manual).\n  Step 2 : Enter the door and configurate it.\n  Step 3 : Ready to rock''n roll!\n\n=============================================================================\n@EndNode\n\n\n@Node "History"\n@Title "History"\n=============================================================================\nV0.1  - NightShade/iNS  7 Jun 1995 BETA\n         * Sniper/Ins came to me with ''tears'' in his eyes and\n           said to me - You have no ''C'' door installed so i\n           started to develop and code this one.\n         + Added a simple config part.\n         + Added a simple displayer.\n         + Added a statistic function.\n         + Added ''Mail'' name and ''Nick'' name.\n         + Added the statistics in the main displayer.\n         + Added the mailer.\n         + Added the Active/Inactive switch in both the CFG and the display,\n           configuration & datafile.\n\n-----------------------------------------------------------------------------\n\nV0.2  - NightShade/iNS  9 Jun 1995 BETA\n         * The former version works butt still ugly and ''slow''.\n         + Added ANSI and a new design.\n         + Fixed cool look in the configurator.\n         + Dynamic name sizing - The mail menu is sized after\n           the length of the nicknames.\n         + Added comment to the main, cfg & datafile.\n         + Optimized a bit (764 Bytes saved).\n\n-----------------------------------------------------------------------------\n\nV0.3  - NightShade/iNS 10 Jun 1995 BETA\n         * Still something missing i guess but what !?.\n         + Added a mail comment in the CFG, Mailer & Datafile.\n         + Added a file name parser - It will simply puts the data file\n           in the same place/name as the main door with the extension ''.DATA''\n           this also offers the sysop the choice to have different types of\n           commenters (install the door as many times and with as many paths\n           as you like).\n\n\n-----------------------------------------------------------------------------\n\nV0.4  - NightShade/iNS 12 Jun 1995 BETA\n         * Working hard i guess, but who cares - Ran out of coffee (ARGH!).\n         + Added so the Co.-sysop''s are able to configurate they''re accounts\n           as they want (Only their own!), Thanks to vIETCONg for the idee!\n         + Speeded the ANSI output a bit.\n         - Fixed a minor ansi bug in the Configurator.\n\n-----------------------------------------------------------------------------\n\nV0.5  - NightShade/iNS 13 Jun 1995 BETA\n         + Added ACP Info line, so you know what''s going on even if the node\n           is iconifyed.\n         + Added cursor keys in the main screen.\n         + Changed the input routine a bit, it now have semi-intelligence\n           and just updates the screen if needed.\n         * Still the EXE is quite small : 13908 Bytes.\n\n-----------------------------------------------------------------------------\n\nV0.6  - NightShade/iNS 28 Jun 1995 [REV 1] BETA\n         + Added Return as a ''Mailer'' in the main (Cursor).\n         - Fixed a minor update bug after configuration (Adding a new user).\n         + Speeded things up (Sub routine clean up).\n         * It''s TOO hot here in Sweden right now, my back is red as a tomato.\n         * Wastelands is on the raise - Speeding up, Try it and enjoy the /X\n           tool conference (700 /X Tools on-line at the moment!)\n\nV1.0  - NightShade/iNS 19 Dec 1995 [REL 2]\n         + Fixed so if you had the cursor at the last user when you entered\n           the configurator then it will reset to position 1.\n         + Changed the internal access system in the door.\n         + Time for optimization... Completed (Pewh!)\n         + Last test with enforcer.\n\n-----------------------------------------------------------------------------\n\nVx.x  - NightShade/iNS ?? ??? ???? BETA\n         + Will add a check vs. user.data for name verification.\n         + Will add multiple designs.\n         + Will add userdefinable design no.\n\n-----------------------------------------------------------------------------\n\n* Just A Comment\n+ Added Something/Recoded Something.\n- Bug Removed.\n\n\n=============================================================================\n@EndNode\n\n@Node "Beta"\n@Title "The cool Beta crew!"\n=============================================================================\n@{" TBB/NE0      SWEDEN  MY BEST BETA TESTER.        "Link "Beta-Tbb"}\n=============================================================================\n@EndNode\n\n@Node "Beta-Tbb"\n@Title "Contact Tbb                           Dial Wastelands [+46(8)157472]"\n ^o^----------------------------------------------------------------^o^\n |   _ ____.::._._  __:  _________.::._________ __                    |\n |  \\\\___¬: /¬:¬\ \_: /  _______¬: /¯_______¬\\/                    |\n |       /¯ |/  |  \/¬|/\__ ¬\  /¯ |/  _/ / ¬|\ \----- -- -  -        |\n |      /   |   ^  \\ |   ¬\ \\/   |   l/¯¬\ l/ \\              .     |\n |      \__øl______ø/_!______ø/\__øl______ø/____ø/                    |\n |        :\/     \/        \/    \/     \/    \/               :     |\n |                  __ ______ ___    ____ __:  _______.::.._ __ .     |\n |     N E O        \//  ___//  ¬\  /¯__/^\_: /¯______¬:/¬!¬\\/ ¦     |\n |                __ /\__ ¬\/  |\ \/  |   /¬|/  _/  /¯ |\__  \  |     |\n |                \//   ¬\ \\  l/ \\  l/¯¬\ |   l/¯¬\  |¬ !  \\ |     |\n |     S H Q !      \______ø/_____ø/_____ø/_!______ø/_øl_____ø/ |     |\n |                        \/     \/     \/  ·     \/  \/ $tµ\/  |     |\n |         	    - - -- --- ---------------------------------+--   |\n |                sYSOP-=> TbB/NEO      cO-=> MiNDPHASER & RULLE      |\n |                                                                    |\n |    - --=> G-FORCE 030/33 MHz <> 13MB 32-BiTS <> 1.5GB HD <=-- -    |\n |      - --=> /X 4.8 <> AMIGA/PC! <> /X UTiLS <> MODULES <=-- -      |\n |                                                                    |\n | ×X×x×X×x×X×x nODE 1 - +46 +(0)44106144 - USR 28.8 DS! ×X×x×X×x×X×x |\n ^o^-----------------------------------------------[ JUST DO iT !! ]^o^\n\n@EndNode\n\n@Node "ContactNS"\n@Title "Contact NiGHTSHADE"\n\n___/\  _______________________________________________________________ _\n  /  \/\\n /   /  \        \\\\\\\                  [×] THE PLACE THAT ROCKS [*]\n \ PARTY \       |^ ^  \\\n  ON DUDE/      _|_ ___  |          \          {+} WASTELANDS {-}\n   \/\  /      (o(.Y.)   o)         _\__\n      \/       /(__) ^  \\         (__''_)     [] STAFF ROOSTER! []\n              (______/   ))_      _|_cOl|\n              //\ `-''   //  \   _/ __)-(_)       NiGHTSHADE/iNS\n             ((  \  _  //    \ /\  |---(_)       cASE/dCS & GAZ\n             /\\  \___//      Y  \ `---(_)\n  ____ ____ /  \\   |// ___ . `   \/\n / __ |    Y    \\__// |___||     /           FAST AMIGA & CONSOLE\n/ /(__|    '' .   (__)  |   ||\___/            [FRIENDSHIP & 4 FUN]\n\_)   |______|      o  `---''|\n             |      ¦       |                 NoDe #1 +46(8)157472\n             |      °       |                 #2 - #4 _SOON AVAIL_\n             |              |\n_ _______________________________________________________________/\  ___\n                                                               - --\/\n@EndNode\n\n@Node "Greetings"\n@Title "The good things..."\n=============================================================================\n\n MY GREETINGS MUST GO TO (A-Z ORDER) :\n\n  * ANTISOCIAL                  - HOPE INSPIRATIONS ARE GAINING LEVELS!\n  * BOBO                        - RUNNING LOW ON IDEAS !?\n  * BLAST                       - KEEP CODING AND YOU WILL KILL US :))\n  * BOROMIR                     - SOON 28k8 AGAIN\n  * CENTURION/PREMIERE          - FASTEST IN EUROPE !?\n  * CASE/DCS!                   - MY KiLLING CO-RAVER!\n  * CITRUS                      - CALLS...\n  * CLUSTER/INS                 - KEEPS INSANITARY ROOLING.\n  * COOLORADO/INS               - THE TRAIN/CRACKMANIAC NO.1\n  * CYCLONE                     - KEEP LEECHING DUDE!\n  * DANSKEN/ACS                 - SKELLEFTEA''S MANIAC NO.1!\n  * DANZIG                      - YOU''RE ASCII ARE GOOD!\n  * DISTLER                     - HOPE THAT YOU WILL GET BACK IN ST!\n                                  DAMN LAME TO LOCK YOU OUT I THINK (AND\n                                  MANY ONES WITH ME - ST ON THE LOOSE!)\n  * DELIVERY MAN                - DK FREAK - NO WAY TO CALL FOR FREE MATE!?\n  * DOC.TROTHYL                 - STILL NO ACTIVITY!\n  * ELF                         - LONG TIME SINCE I HEARD SOMETHING FROM U!\n  * EVERSLICK                   - NO TRADING NO MORE !?\n  * EZCO                        - WORKING HARD I GUESS !?\n  * fAktOR & tRANCE             - STILL TRADING !?\n  * GAZ                         - GOOD CONSOLE SUPPORT M8!\n  * GOORFY                      - ANY GOOD MUSACZ LATLY !?\n  * GUDDE                       - GOOD LEECHER!\n  * HEROIN                      - HiGH VOLTAGE STAFF (CONSOLE)\n  * ICON                        - NO CONSOLE SPEED!?\n  * JADE                        - HAVE YOU DIED !?\n  * LIGHTSPEED TECH.            - GUESS ? - FOR /X OFCOUSE.\n  * LINEBACKER                  - I WILL CALL ''THE MANSION'' SOME DAY AGAIN!\n  * LION                        - SUPPLYING ME WITH OLD STUFF.\n  * LOOBY/INS                   - PROGRAMING MANIAC.\n  * LOUIE                       - THANX FOR THE LOGGO MATE!\n  * MARX/INS                    - NO DUPECHECKER YET...\n  * METAL/INS                   - CODES A LOT (NO RESULT ??)\n  * NECROPHILIAC                - CHAT YOU AS ALWAYS!\n  * NECRONOMICON                - HOPEFULLY WITH WORKING HD !\n  * NIMITZ                      - GOT THE POWERSUPPLY WORKING YET !?\n  * MR NIELSEN                  - LEECH LISTER IS COMPLETE!\n  * OPIUM                       - REMINDS ME WHEN ITS TIME TO LEAVE DC DATA\n  * QEN                         - UPLOADING SMALL FILES :)\n  * PRINCIP                     - HELP WITH MODEMS AGAIN :)\n  * RAD                         - TO BAD YOU KILLED ''MEGA LO MANIA''!\n  * SAVAGE                      - GOOD SUPPORTER!\n  * SHADE                       - THANX FOR THE DESIGN!\n  * SHAPECHANGER                - REAL GOOD ASCII...\n  * SHOCKER                     - ALWAYS MANY REQUESTS!\n  * SKUTT                       - CATCH 22 IS THE NAME!\n  * SNIPER                      - THANX FOR THE SUPPORT!?\n  * SPEED                       - UNIX MASTER!\n  * SPIDER                      - KILLS MY SPARE TIME!\n  * TBB                         - MY BEST BETA TESTER!\n  * TWINS/PHA                   - GOOD MUSIC EDITOR INDEED!\n  * VIET CONG                   - NICE TRADER!\n  * VIRUS                       - MY ITALIAN MATE!\n  * WARHAMMER                   - NO SPEED FOR ME AT YOURE BOARD!\n  * WARLOCK                     - FOR BORROWING THIS COMPUTER.\n  * WESTBAM                     - KiLLING TRADER\n  * XCLUZIWE                    - THANX FOR THE ''BETA'' LOGO!\n  * ZANOK                       - ONE DAY BACK I HOPE!\n\n I know i have forgotten a dozzen or 2 and i''m terribe sorry for that.\n=============================================================================\n@EndNode\n\n@Node "Other"\n@Title "Other tools we have made for you"\n                /\       ___.                    ___.\n              _/  \____ |   |_________/\ ______ |   | _________\n              \___|    \|   \    __  /  \\_    \|   |/   _____/\n           Mb /   |     \   |\___  \/  | \|     \   /   __/ \\n             /    |   \     |   /   \  _  \   \    /    |    \\n            /     |___|\    |_______/  |___\__|\   \__________\\n      *>---/______|-----\___|----/_____|--------\___|---------------<*\n\n           AmiExpress Pro. Doors Available To You From NiGHTSHADE\n\n«········································································»\n\n  [Smart DSF]\n\n   SmartDSF is a replacement for the ''DS'' command,\n   it gives you the following advantages :\n\n    * Requester selected files (multiple if wanted!).\n    * Uses ASL because everybody have it (and if you\n      like the REQTools.library better, my guesses are\n      that you have patched the ASL.library).\n    * If a file was unsuccessfully downloaded the door asks\n      if you want to try again, continue with the next or\n      abort the zmodem batch transfer. (According to my\n      knowledge NO ''DS'' door offers this, not even\n      Ami Express itself!).\n    * Displays all files and there sizes before sent.\n    * Estimates the transfer time in seconds.\n    * 680x0+ and a 68020+ epitomized version included.\n    * Resident versions also included for fast execute.\n    * Better performance than all to me known ''DS'' reposers.\n    * Fast & Small.\n    * Reliable.\n    * Works on ALL OS and CPU''s (If not - Contact me).\n\n«········································································»\n\n   [Smart Show]\n\n    SmartShow is a door developed to display a TXT file eg.\n    like a door list or a member list for a group.\n    it will bring the following to you''re system :\n\n     * Simple configurator (Using cursor keys).\n     * Request selector for the TXT file to show.\n     * Built in display routine - Faster than /X''s own file viewer!\n     * Fast Statistical function (Displays No. of usages).\n     * Reliable.\n     * Fast.\n     * Works on ALL OS and CPU''s (If not - Contact me).\n\n«········································································»\n\n   [Status Scan]\n\n    Status Scan is a replacement for the ''S'' command i have seen\n    to many ones who are SLOW or have bad design and decided to\n    code one my self to easy indeed but who cares !?\n     * __FAST__\n     * Nice\n     * Reliable\n     * Small.\n     * Displays needed data - NO CREEPY INFOS like what serial-device\n\n«········································································»\n\n   [File List Manager] [Still in BETA stage]\n\n    Allows you to manipulate the filelists in many ways :\n\n     * Delete files (From Multiple paths - Just one pass needed!)\n     * Compress filelists (For faster dupechecking).\n     * Kill Descriptions (Keeps sizes and dates)\n     * Change filesizes to own string (like off-line)\n     * Star (*) mark files (For off-line purposes)\n     * And more (Be4 releasing)...\n\n«········································································»\n\n   [Add''O''Mania]\n\n    Ohh no not just another LHA checker, well this one is different\n    in some cool ways :\n\n     * 12 Chars random based add.\n     * Possibility to add date to the random add.\n     * Up to 256 Adds.\n     * Nice Design.\n     * Strips.\n     * Fast.\n     * Reliable.\n     * Statistics (How many files / bytes passed the checker).\n\n«········································································»\n\n   [Trade Lister]\n\n    A simple userlister program who have some nice features:\n\n     * Displays only users with XXX bytes uploaded.\n     * Fast & Reliable.\n     * Nice Design\n\n«········································································»\n\n   [UsKe Reader]\n\n    A Simple dos tool who displays the user.data & user.keys in TXT\n    format - Especially useful when you want to merge 2 user.datas\n\n     * Create TXT file output.\n     * Fast & Reliable.\n\n«········································································»\n\n   [You''re idea !?]\n\n    Dial me and well can chat about them!\n\n«········································································»\n@EndNode\n\n@Node "File_ID"\n@Title "Orginal File_ID"\nkRm_____:  .______________.  :______        \n-_/ _/  \ _/  _______ _/  \ _/  ___/--------\n \_ \_  \\\____ \_  _ \_  \\\_  _/_. iNSANE \n  |  |  |\ |  !  |  |  |  |\ |  !  | ------ \n  ¦  l__|  l__   l__|  l__|  l__   |  1995  \n.-:  ·--l__|--\__|--l__|--l__|--\__|-------.\n|       NS-MULTICOMMENT V1.0 [REL 2]       |\n| THIS COOL /X DOOR IS CODED BY NIGHTSHADE |\n| SIMPLY THE BEST FOKKING MC DOOR WITH ALL |\n|      YOU NEED AND NO OTHER LAME SHIT     |\n`------------------------------------------''\n@EndNode\n','\n',char(10)),'{"ACCESS":"<numb>","LOCATION":"<string>","PRIORITY":"SAME","STACK":"4096","TYPE":"XIM"}',NULL,23323,2,0,NULL,NULL,'ins_mc10_mcomment10','scan',1780048553);
INSERT INTO door_catalog VALUES('ins_mt20','INS-MT20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/INS-MT20.LHA','MegaTop','XIM','MegaTop',NULL,'Tot/Weekly','INS','\_  |   \|   /  _/__  __  |   \|   / _    /c _/  :    \  /\_    /  _/  :    \  /  _)__/_ \___l__7___/  7   /___l___l__7___/______ _',replace('__ _|_ _  __ _ ___ _____ _|_ _  __ _ ______s\n\_  |   \|   /  _/__  __  |   \|   / _    /c\n_/  :    \  /\_    /  _/  :    \  /  _)__/_\n\___l__7___/  7   /___l___l__7___/______ _\no---------l______/-------------------------o\n:           MEGATOP V2.0 [REV 1]           |\n|     THE ULTIMATE /X CHART GENERATOR!     |\n|                                          |\n|   Features: Userdefinable Designfiles,   :\n|   Tot/Weekly Stats, Mailfunction, etc.   :\n|                                          :\n|         (c)1996 By LOOBY/INSANE!         |\n`------------------------------------------''\n','\n',char(10)),'MegaTop.guide',replace('@DataBase MegaTop\n@(C) 1996 Looby/Insane\n@AUTHOR Looby/Insane\n@DOCS By Marx & Looby & Cluster!\n@$VER: MegaTop.guide v2.0 (03.01.96)\n\n@Rem ==================================================================\n@Node MAIN "MegaTop v2.0 Documentation"\n\n     ______._______  _____ _ _______ __________________  _______ _________\n     \_    |_      \|      /   ____/_______.    __     \|      /   _     /\n      /    |/       \     /____.      /    |_   \/      \     /    _)___/\n   s_/    _/      \     _/     l     /     _/    \_    \    _/     |    \_s\n   c\_____\_______|\____\___________/      l______/    |\___\____________/c\n<-- -------------------------------\_______|-----------''\n\n                              [ p.r.e.s.e.n.t.s ]\n\n             @{BG fill} @{fg Shine}>>> MEGATOP v2.0 @{fg text}- THE ULTIMATE CHART GENERATOR <<<@{BG Background}\n\n                  @{"      Copyright (c) 1996 Looby/Insane!     " Link Copyright}\n \n                    @{"  Introduction  " Link Introduction}  @{"   The Designfiles   " Link MakeDesign}\n                    @{"  Installation  " Link Installation}  @{"       Credits       " Link Credits}\n                    @{"  Requirements  " Link Requirements}  @{"       History       " Link History}\n                    @{"     Usage      " Link Usage}  @{"       Support       " Link Support}     \n\n                  @{"i n s a n e  w o r l d w i d e  b o a r d s" Link Boards}\n\n      ==================================================================\n\n@EndNode\n\n@Rem ==================================================================\n@Node Copyright "MegaTop v2.0 Documentation - Copyright!"\n\n\n                               @{fg Shine}= MegaTop v2.0 =@{fg text}\n\n                Copyright © 1996 Anders "Looby/Insane" Wahlgren\n\n               Permission is hereby granted to freely distribute\n                 this product for non-commercial purposes only\n                    as long as all files remain unmodified.\n\n\n\n                        @{"[ <<<< ]" Link Main}               @{"[ >>>> ]" Link Introduction}\n\n\n      ==================================================================\n\n@EndNode\n\n@Rem ==================================================================\n@Node Introduction "MegaTop v2.0 Documentation - Introduction!"\n\n@{fg Shine}Introduction@{fg Text}\n~~~~~~~~~~~~\n  MegaTop is currently the most advanced chart-generator for AmiExpress!\n  It creates statistical charts (both total and weekly) using\n  user-definable design-files. This means for example that the sysop\n  can virtually design his own total-uploads with customized design!\n\n@{fg Shine}Features@{fg Text}\n~~~~~~~~\n  * User-definable design-files\n  * Mixing of all items in the same chart\n  * Intelligent date handler\n  * Weekly chart-mailing\n  * Presets\n  * Scripts\n  * Large item database\n  * Design output preview in Shell\n  * Various debugging modes\n  * Logfile\n\n              @{"[ <<<< ]" Link Copyright}              @{"[ Main ]" Link Main}             @{"[ >>>> ]" Link Installation}\n@EndNode\n\n@Rem ==================================================================\n@Node Installation "MegaTop v2.0 Documentation - Installation!"\n\n@{fg Shine}Installation@{fg Text}\n~~~~~~~~~~~~\n  Just use the included install-script!\n\n  If you for some reason don''t want/can''t use the install-script\n  then all you have to do is make a directory (optional, e.g. MegaTop)\n  in DOORS: and a sub-directory (optional, e.g. Design) for the\n  design-files. That''s it!\n\n\n\n              @{"[ <<<< ]" Link Introduction}              @{"[ Main ]" Link Main}             @{"[ >>>> ]" Link Requirements}\n\n\n@EndNode\n\n@Rem ==================================================================\n@Node Requirements "MegaTop v2.0 Documentation - Requirements!"\n\n@{fg Shine}Requirements@{fg Text}\n~~~~~~~~~~~~\n  * An Amiga (at least Release 2)\n  * AmiExpress (at least v3.x, not tested below!)\n\n  * The DOORS: and T: assigns MUST be present!\n\n\n\n              @{"[ <<<< ]" Link Installation}              @{"[ Main ]" Link Main}             @{"[ >>>> ]" Link Usage}\n\n\n@EndNode\n\n@Rem ==================================================================\n@Node MakeDesign "MegaTop v2.0 Documentation - Usage : Make design files"\n\n@{fg Shine}Designfile formating@{fg Text}\n~~~~~~~~~~~~~~~~~~~~\n                             @{"     Cells     " Link Cells}\n                             @{"     Mail      " Link Mail}\n                             @{"    Presets    " Link Presets}\n\n\n\n          @{"[ <<<< ]" Link Usage}              @{"[ Main ]" Link Main}             @{"[ >>>> ]" Link Credits}\n\n@EndNode\n\n@Rem ==================================================================\n@Node Usage "MegaTop v2.0 Documentation - Usage : Usage"\n\n@{fg Shine}Usage@{fg Text}\n~~~~~\n  MegaTop is to be executed when a user logoff.\n\n  The LOGOFF1.SCRIPT for node one can look like this:\n\n  -- cut --\n  DOORS:MEGATOP/MEGATOP SCRIPT=DOORS:MEGATOP/MEGATOP.SCR\n  -- cut --\n\n@{fg Shine}Arguments@{fg Text}\n~~~~~~~~~\n  DSG=<file>      - @{I}Design file@{UI}\n                    Enter full path pointing to the designfile.\n\n  DATA=<file>     - @{I}Userdata file@{UI}\n                    Enter full path pointing to the ''User.data''.\n                    Default path is ''BBS:USER.DATA''.\n\n  USERKEYS=<file> - @{I}UserKeys file@{UI}\n                    Enter full path pointing to the ''User.keys''.\n                    Default path is ''BBS:USER.KEYS''.\n\n  OUTPUT=<file>   - @{I}Output file@{UI}\n                    Enter full path pointing to the output-file.\n\n  SCRIPT=<file>   - @{I}Script file@{UI}\n                    Enter full path pointing to the @{"script-file" Link Scripts}.\n\n@{fg Shine}Options@{fg Text}\n~~~~~~~\n  SYSOP=<n>       - @{I}Sysop counting@{UI}\n                    0 = Include sysop (default).\n                    1 = Count sysop stats but hide him/her.\n                    2 = Do not include sysop.\n         \n  NOZERO          - Do not show users/fields with zero values.\n\n  DEBUG=<n>       - @{I}Debug information@{UI}\n                    Bit#\n                       0 (0)  = No debugging information (default).\n                       1 (1)  = Show settings.\n                       2 (2)  = User.data & Megatop.dat comparison\n                                Output to screen.\n                    e.g.  ''1'' and ''2'' : (1) + (2) = 3 : DEBUG=3\n\n  LOG=<n>         - @{I}Logfile@{UI} ( DOORS:MegaTop.Log )\n                    Bit#\n                       0 (0) = Off\n                       1 (1) = On\n\n  TEST            - @{I}Test mode@{UI}\n                    To test the output in the current window.\n                    Output file will also be generated.\n                    No WeekReset nor Mailing will be made.\n                    No logdata will be saved (even if you use LOG=x).\n\n\n              @{"[ <<<< ]" Link Requirements}              @{"[ Main ]" Link Main}             @{"[ >>>> ]" Link MakeDesign}\n@EndNode\n\n@Rem ==================================================================\n@Node Cells "MegaTop v2.0 Documentation - Usage : Cells!"\n\n@{fg Shine}Cells@{fg Text}\n~~~~~\n\n  @{fg Shine}NOTE!@{fg Text} The cell MUST contain at least two dots ''.'' (Used as seperators).\n        And the SysNum_Progname and SysNum_Author cells must be included,\n        or else they will appear in the bottom of the output file..\n\n      %[1.15-.ITEM.P]\n        |  |   |   |\n        |  |   |   `----- @{" Preset " Link Presets}\n        |  |   |\n        |  |   `--------- @{" Item " Link Items}\n        |  |\n        |  `------------- @{" Width " Link Width}\n        |\n        `---------------- @{" User position " Link UserPos}\n\n  Ex. %[1.10.UL_TOT_NAME]  : Valid\n      %[..SYSSUM_AUTHOR]   : Valid\n      %[.UL_TOT_NAME]      : Not Valid\n\n\n\n              @{"[ <<<< ]" Link Presets}              @{"[ Main ]" Link MakeDesign}             @{"[ >>>> ]" Link Mail}\n\n@EndNode\n\n@Rem ==================================================================\n@Node Preset "MegaTop v2.0 Documentation - Usage : Cells : Preset!"\n\n@{fg Shine}Preset@{fg Text}\n~~~~~~\n  There are two main datatypes from which MegaTop gathers data from:\n\n  * System/Week totals\n  * User totals\n\n  (See also @{" Presets " Link Presets})\n\n\n@EndNode\n\n@Rem ==================================================================\n@Node Width "MegaTop v2.0 Documentation - Usage : Cells : Width!"\n\n@{fg Shine}Width@{fg Text}\n~~~~~\n  -n    // Right justified\n  n-    // Left justified\n  -n-   // Centered\n\n  ''n'' stands for the width of the cell.\n  (If you don''t give a number the cell won''t be formated).\n\n              @{"[ <<<< ]" Link Items}              @{"[ Main ]" Link Cells}             @{"[ >>>> ]" Link Userpos}\n\n@EndNode\n\n@Rem ==================================================================\n@Node UserPos "MegaTop v2.0 Documentation - Usage : Cells : User position!"\n\n@{fg Shine}User position@{fg Text}\n~~~~~~~~~~~~~\n  Specifies the user position in list.\n  Negative numbers equal position counted from the end of list.\n\n              @{"[ <<<< ]" Link Width}              @{"[ Main ]" Link Cells}             @{"[ >>>> ]" Link Items}\n\n@EndNode\n\n@Rem ==================================================================\n@Node Items "MegaTop v2.0 Documentation - Usage : Items!"\n\n@{fg Shine}Items@{fg Text}\n~~~~~\n  Two sorts of formats exist:\n\n\n  Used for items that doesn''t have any users connected to it.\n\n  - @{" SYSTEM/WEEK TOTALS " Link ChartModes}_ITEM\n                           |\n                           +-----@{" Week items   " Link WeekItems}\n                           `-----@{" System items " Link SysItems}\n\n  Used for items that have users connected th it.\n\n  - @{" SORT-ORDER " Link SortOrder}_@{" DATA " Link Data}_@{" ITEMS " Link UserItems}\n\n              @{"[ <<<< ]" Link Userpos}              @{"[ Main ]" Link Cells}             @{"[ >>>> ]" Link Width}\n \n@EndNode\n\n@Rem ==================================================================\n@Node ChartModes "MegaTop v2.0 Documentation - Usage : Items : Chart modes!"\n\n@{fg Shine}Chart modes@{fg Text}\n~~~~~~~~~~~\n  SYSSUM                   // System summary\n                           // ie. Total upload on system or calls.\n\n  WEEKSUM                  // Week period summary\n                           // ie. Total upload this week.\n\n              @{"[ <<<< ]" Link Sysitems}              @{"[ Main ]" Link Items}             @{"[ >>>> ]" Link WeekItems}\n\n@EndNode\n\n@Rem ==================================================================\n@Node SortOrder "MegaTop v2.0 Documentation - Usage : Items : Sort order!"\n\n@{fg Shine}Sort order@{fg Text}\n~~~~~~~~~~\n  UL                       // Upload bytes\n  DL                       // Download bytes\n  ULS                      // Upload files\n  DLS                      // Download files\n  CALL                     // Calls\n  MESS                     // Messages posted\n  CPSUL                    // Sort data on Cps upload rate\n  CPSDL                    // Sort data on Cps download rate\n  SLOT                     // Sort on users slotnumber\n\n              @{"[ <<<< ]" Link UserItems}              @{"[ Main ]" Link Items}             @{"[ >>>> ]" Link Data}\n\n@EndNode\n\n@Rem ==================================================================\n@Node Data "MegaTop v2.0 Documentation - Usage : Items : Data!"\n\n@{fg Shine}Data@{fg Text}\n~~~~\n\n  What type of data to be used.\n\n  WEEK                     // Week totals\n\n  WEEKTOT                  // ie. If you want to get the total upload\n                           // from the user how is first on the weektop.\n\n  TOT                      // System totals\n\n  TOTWEEK                  // ie. If you want to see how many calls the\n                           // user who is number one on the weektop.\n\n              @{"[ <<<< ]" Link Sortorder}              @{"[ Main ]" Link Items}             @{"[ >>>> ]" Link UserItems}\n\n@EndNode\n\n@Rem ==================================================================\n@Node WeekItems "MegaTop v2.0 Documentation - Usage : Items : Week items!"\n\n@{fg Shine}Week items@{fg Text}\n~~~~~~~~~~\n  BYTESUP                  // Upload bytes\n  BYTESDOWN                // Download bytes\n  FILESUP                  // Upload files\n  FILESDOWN                // Download files\n  CALLS                    // Calls\n  MESSAGES                 // Messages posted\n  NEWUSERS                 // New users this week\n  DELUSERS                 // Deleted users this week\n  DAYSLEFT                 // Days left on week inkl. current day\n  DAYSPASSED               // Passed days on week including current day\n\n              @{"[ <<<< ]" Link Chartmodes}              @{"[ Main ]" Link Items}             @{"[ >>>> ]" Link Sysitems}\n\n@EndNode\n\n@Rem ==================================================================\n@Node SysItems "MegaTop v2.0 Documentation - Usage : Items : System items!"\n\n@{fg Shine}System items@{fg Text}\n~~~~~~~~~~~~\n  BYTESUP                  // Upload bytes\n  BYTESDOWN                // Download bytes\n  FILESUP                  // Upload files\n  FILESDOWN                // Download files\n  CALLS                    // Calls\n  MESSAGES                 // Messages posted\n  USERS                    // Total accounts\n  DATE                     // Date when top was generated, e.g. ''22-04-95''\n  TIME                     // Time when top was generated, e.g. ''18:01:49''\n  PROGNAME                 // Name of program\n  AUTHOR                   // Name of author\n\n              @{"[ <<<< ]" Link WeekItems}              @{"[ Main ]" Link Items}             @{"[ >>>> ]" Link Chartmodes}\n\n@EndNode\n\n@Rem ==================================================================\n@Node UserItems "MegaTop v2.0 Documentation - Usage : Items : User items!"\n\n@{fg Shine}User items@{fg Text}\n~~~~~~~~~~\n  SLOTNR                   // Slot number\n  NAME                     // Name\n  LOCATION                 // Location\n  BYTESUP                  // Upload bytes\n  BYTESDOWN                // Download bytes\n  FILESUP                  // Upload files\n  FILESDOWN                // Download files\n  CALLS                    // Calls\n  MESSAGES                 // Messages posted\n  LASTONDATE               // Users last logon data ex. ''14-08-94''\n  LASTONTIME               // Users last logon time ex. ''20:35:43''\n  LCFILES                  // Lost carrier files\n  BYTERATIO                // Byteratio ''BYTESUP/BYTESDOWN''\n                              ex 10000 up 20000 dl = -2\n                                 20000    10000    =  2\n                                 10000    10000    =  0\n                                 10000        0    =  10000\n                                     0    10000    = -10000\n  FILERATIO                // fileratio FILESUP/FILESDOWN\n                              Same tactics as ''BYTERATIO''\n  CPSU                     // Top CPS upload rate\n                           // (only in ''TOT'' and ''WEEKTOT'')\n  CPSD                     // Top CPS download rate\n                           // (only in ''TOT'' and ''WEEKTOT'')\n\n              @{"[ <<<< ]" Link Data}              @{"[ Main ]" Link Items}             @{"[ >>>> ]" Link Sortorder}\n\n@EndNode\n\n@Rem ==================================================================\n@Node Mail "MegaTop v2.0 Documentation - Usage : Mail!"\n\n@{fg Shine}Mail@{fg Text}\n~~~~~\n\n @{fg Shine}NOTE!@{fg Text} Mail is configured in @{"presets" Link Presets}\n\n\n  MAIL= <mode>     - Mail persion\n                     ''WEEK''  // Weekly ( mondays )\n\n  SUBJECT=<string> - The subject of the mail\n\n  TO=<string>      - Where the mail will be sent ex.\n\n  FROM=<string>    - From who the mail will be marked as.\n\n  CONFPATH=<path>  - The path to the conference where you want the\n                     mail to be posted.\n\n@{fg Shine}Example@{fg Text}\n~~~~~~~\n  -- cut --\n  BEGIN PRESET\n\n   MAIL=WEEK SUBJECT="Week result" TO="EALL" FROM="MegaTop" CONFPATH="BBS:CONF1/"\n\n   PRESET=1 B=0 V=M\n   PRESET=2 C=U\n   etc...\n  END PRESET\n   etc..\n  -- cut --\n\n              @{"[ <<<< ]" Link Cells}              @{"[ Main ]" Link MakeDesign}             @{"[ >>>> ]" Link Presets}\n\n@EndNode\n\n@Rem ==================================================================\n@Node Presets "MegaTop v2.0 Documentation - Usage : Presets!"\n\n@{fg Shine}Presets@{fg Text}\n~~~~~~~\n  @{fg Shine}NOTE!@{fg Text} You can''t mix BREAKPOINT''s and EQUAL''s.\n\n  PRESET=<presetnumber> - This is the presetnumber used in @{"cells" Link cells}.\n                          Has to be on EVERY preset row.\n\n  LEVEL=<levelnumber>   - Only used with ''B'' or ''E''.\n\n  MAIL=<period type>    - Mail period (See @{"mail" Link Mail})\n\n                          ''WEEK''  // Mail every week ( Monday )\n\n  V=<c>      - Output type\n\n               ''B'' = Bytes\n               ''K'' = Kilobytes\n               ''M'' = Megabytes\n               ''T'' = Thousand\n\n  B=<n>      - Breakpoints\n\n               Example:                                              Range\n\n               LEVEL=1 B=10 // Do that if value is 10 or less      ( x - 10 )\n               LEVEL=2 B=20 // Do that if value is 20 or less      ( 20- 11 )\n               LEVEL=3 B=30 // Do that if value is higher or equal ( 30-  x )\n\n  E=<n>      - Equal\n\n               Example:\n\n               LEVEL=1 E=10 // Do that if value is 10\n               LEVEL=2 E=20 // Do that if value is 20\n               LEVEL=3 E=!  // Otherwise do this.\n\n               If no criteria is valid an empty string will be returned.\n\n  M=<char>   - Type of seperator character, ( ONLY ONE CHAR ).\n               Works only on Numeric strings!\n\n               Example:\n\n               1.000.000 // M=.\n               1-000-000 // M=-\n\n  P=<string> - Prefix, String will be inserted added infront of item text/value\n\n  S=<string> - Suffix, String will be added last of item text/value\n\n  C=<c>      - Case mode\n\n               ''U'' = UPPER\n               ''L'' = lower\n               ''I'' = Indent\n\n@{fg Shine}Preset Example@{fg Text}\n~~~~~~~~~~~~~~\n\n  -- Cut --\n\n  BEGIN PRESET\n\n   PRESET=1 M=.\n\n   PRESET=2 V=K M='' P="Before " S=" After"\n\n   PRESET=3 LEVEL=1 V=B B=0        S=" Bytes"\n   PRESET=3 LEVEL=2 V=K B=1024     S=" Kb"\n   PRESET=3 LEVEL=3 V=M B=1024000  S=" Mb"\n\n  END PRESET\n\n  System total download : %[.-40.SYSSUM_BYTESDOWN.1]\n  System total download : %[.-40.SYSSUM_BYTESDOWN.2]\n  System total download : %[.-40.SYSSUM_BYTESDOWN.3]\n\n  -- Cut --\n\n@{fg Shine}Explanation@{fg Text}\n~~~~~~~~~~~\n\n Preset number 1 (PRESET=1) is a very simple one. It just puts\n  points (M=.) in value, ex 1.000.000.\n\n Preset number 2 (PRESET=2) Makes the valus as Kilobytes (V=K) and\n  puts the text ''Before'' in front of the value (P="Before ") and\n  the text string ''After'' (S=" After") after the value.\n\n Preset number 3 (PRESET=3) Here is a tricky one. If we want to control the\n  value we can use Breakpoints, that means if the valus is greater than a\n  number it changes. Every value lower and equal than 0 (B=0) will have\n  the suffix " Bytes" (S=" Bytes") and the value will be in bytes (B=0).\n\n\n              @{"[ <<<< ]" Link Mail}              @{"[ Main ]" Link MakeDesign}             @{"[ >>>> ]" Link Cells}\n\n@EndNode\n\n@Rem ==================================================================\n@Node Scripts "MegaTop v2.0 Documentation - Usage : Scripts!"\n\n@{fg Shine}Scripts@{fg Text}\n~~~~~~~\n\n  * Recommended strongly, for fast generation of output files.\n\n  * Comments begins with '';'' everything behind that is ignored.\n\n  * Option ''SYSOP=<n>'' in script file doesn''t work.\n    You have to specify ''SYSOP=n'' as command line argument if you\n    want sysop option.\n\n    ie. MegaTop SCRIPT=MegaTop.script SYSOP=2\n                                       ^^^^^^^\n                                         `-- This excludes sysop counting\n                                             in all outputs generated in\n                                             the script.\n\n    ie.  -- cut --\n         DSG=DOORS:MegaTop/Dsg/Weektop.dsg OUTPUT=RAM:WeekTop.txt NOZERO\n         DSG=DOORS:MegaTop/Dsg/Top10.dsg   OUTPUT=RAM:Top10.txt\n         --- cut ---\n\n              @{"[ <<<< ]" Link Usage}              @{"[ Main ]" Link Main}             @{"[ >>>> ]" Link Usage}\n\n@EndNode\n\n@Rem ==================================================================\n\n@Rem ==================================================================\n@Node Credits "MegaTop v2.0 Documentation - Credits!"\n\n                                    @{fg Shine}Credits@{fg Text}\n                                    ~~~~~~~\n  * Looby/Insane      - MegaTop executable, install-script, Documentation\n  * Marx/Insane       - Documentation\n  * Cluster/Insane    - Documentation, No.1 Beta tester, Ideas/Suggestions\n  * Nightshade/Insane - Beta Tester\n  * Shade/Insane      - Beta Tester\n  * MadMax/Insane     - Beta Tester\n\n  * Thanks to:\n\n    Bobo, BugByte, Cluster, Distler, Ezco & Sandman for the Designs ...\n\n\n\n              @{"[ <<<< ]" Link Makedesign}              @{"[ Main ]" Link Main}             @{"[ >>>> ]" Link History}\n\n@EndNode\n\n@Rem ==================================================================\n@Node History "MegaTop v2.0 Documentation - History!"\n\n@{fg Shine}History@{fg Text}\n~~~~~~~\n@{fg Shine}03-Jan-96 Rev1 v2.0@{fg Text}\n~~~~~~~~~~~~~~~~~~~\n  * First release!\n\n@{fg Shine}11-Apr-95 Rev1 v1.0@{fg Text}\n~~~~~~~~~~~~~~~~~~~\n  * MegaTop was born, as Requested by Cluster!\n\n\n\n              @{"[ <<<< ]" Link Credits}              @{"[ Main ]" Link Main}             @{"[ >>>> ]" Link Support}\n\n@EndNode\n\n@Rem ==================================================================\n@Node Support "MegaTop v2.0 Documentation - Support!"\n\n@{fg Shine}Contact Me!@{fg Text}\n~~~~~~~~~~~\n  To get in touch with me, try the following mediums:\n\n  BBS   - +46-8-7595847 [Insanitary: iNS-WHQ!]\n\n  IRC   - #amigascne, Nick LOOBY\n\n  EMAIL - [email removed]\n\n\n@{fg Shine}Support@{fg Text}\n~~~~~~~\n  To get the latest version of MegaTop or new design files use:\n\n  WWW - http://www.canit.se/~andersw/megatop.html\n\n\n\n              @{"[ <<<< ]" Link History}              @{"[ Main ]" Link Main}             @{"[ >>>> ]" Link Boards}\n\n@EndNode\n\n@Rem ==================================================================\n@Node Boards "iNSANE wORLDWiDE bOARDS!"\n  ._________________________________________________________________________.\n  |                                                                         |\n  |              · Don''t Hesitate To Call These Insane HQ''s! ·              |\n  |                                                                         |\n  |     o1. Insanitary      -  World HeadQuarter     -   +46-8-7595847!     |\n  |         Insanitary      -  World HeadQuarter     -   +Ask-4-Telnet!     |\n  |     o2. The Chameleon   -  European HeadQuarter  -   +358-815409545     |\n  |         The Chameleon   -  European HeadQuarter  -   +358-815409589     |\n  |         The Chameleon   -  European HeadQuarter  -   +358-815546450     |\n  |     o3. Death Row       -  US HeadQuarter        -   +1-801-4769068     |\n  |         Death Row       -  US HeadQuarter        -   +1-801RingDown     |\n  |         Death Row       -  US HeadQuarter        -   +Ask-4-Telnet!     |\n  |     o4. Dial Hard       -  Swizz HeadQuarter     -   +41-735-065-25     |\n  |         Dial Hard       -  Swizz HeadQuarter     -   +41-73RingDown     |\n  |     o5. Sky Tower       -  Dannish HeadQuarter   -   +45-74-833886!     |\n  |         Sky Tower       -  Dannish HeadQuarter   -   +45-74RingDown     |\n  |     o6. Asylum          -  Swedish HeadQuarter   -   +46-303-798622     |\n  |         Asylum          -  Swedish HeadQuarter   -   +46-303-798920     |\n  |     o7. EveryWare       -  Norweigan HeadQuarter -   +47-639-541-90     |\n  |     o8. Fatal Justice   -  Distant HeadQuarter   -   +45-31118-2284     |\n  |__                                                                     __|_\n  |_/________  /\_________________________________________________________\_|\n  :          \/\n              @{"[ <<<< ]" Link Support}              @{"[ Main ]" Link Main}             @{"[ >>>> ]" Link Main}\n\n@EndNode\n','\n',char(10)),NULL,'auto-added',267779,5,0,NULL,NULL,'ins_mt20','scan',1780048553);
INSERT INTO door_catalog VALUES('ins_mt5','INS-MT5.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/INS-MT5.LHA','MegaTop','XIM','MegaTop',NULL,'Tot/Weekly','INS',':          MEGATOP V2.0 [REV 5]            | |      The ultimate chart generatoR        | |                   For                    |',replace('o------------------------------------------o\n:          MEGATOP V2.0 [REV 5]            |\n|      The ultimate chart generatoR        |\n|                   For                    |\n|  AmiExpress,Daydream,Tempest,Fame,Sigma  |\n|                                          |\n|   Features: Userdefinable Designfiles,   :\n|   Tot/Weekly Stats, Mailfunction, etc.   :\n|                                          :\n|         (c)1997 By LOOBY/iNSANE!         |\n`------------------------------------------''\n','\n',char(10)),'MegaTop.guide',replace('@DataBase MegaTop\n@(C) 1996 Looby/Insane\n@AUTHOR Looby/Insane\n@DOCS By Marx & Looby & Cluster!\n@$VER: MegaTop.guide v2.0 (30.06.96)\n\n@Rem ==================================================================\n@Node MAIN "MegaTop v2.0 Documentation"\n\n     ______._______  _____ _ _______ __________________  _______ _________\n     \_    |_      \|      /   ____/_______.    __     \|      /   _     /\n      /    |/       \     /____.      /    |_   \/      \     /    _)___/\n   s_/    _/      \     _/     l     /     _/    \_    \    _/     |    \_s\n   c\_____\_______|\____\___________/      l______/    |\___\____________/c\n<-- -------------------------------\_______|-----------''\n\n                              [ p.r.e.s.e.n.t.s ]\n\n             @{BG fill} @{fg Shine}>>> MEGATOP v2.0 @{fg text}- THE ULTIMATE CHART GENERATOR <<<@{BG Background}\n\n               @{"      Copyright (c) 1996,1997 Looby/Insane!     " Link Copyright}\n \n                    @{"  Introduction  " Link Introduction}  @{"   The Designfiles   " Link MakeDesign}\n                    @{"  Installation  " Link Installation}  @{"       Credits       " Link Credits}\n                    @{"  Requirements  " Link Requirements}  @{"       History       " Link History}\n                    @{"     Usage      " Link Usage}  @{"       Support       " Link Support}     \n\n                  @{"i n s a n e  w o r l d w i d e  b o a r d s" Link Boards}\n\n      ==================================================================\n\n@EndNode\n\n@Rem ==================================================================\n@Node Copyright "MegaTop v2.0 Documentation - Copyright!"\n\n\n                               @{fg Shine}= MegaTop v2.0 =@{fg text}\n\n             Copyright © 1996,1997 Anders "Looby/Insane" Wahlgren\n\n               Permission is hereby granted to freely distribute\n                 this product for non-commercial purposes only\n                    as long as all files remain unmodified.\n\n\n\n                        @{"[ <<<< ]" Link Main}               @{"[ >>>> ]" Link Introduction}\n\n\n      ==================================================================\n\n@EndNode\n\n@Rem ==================================================================\n@Node Introduction "MegaTop v2.0 Documentation - Introduction!"\n\n@{fg Shine}Introduction@{fg Text}\n~~~~~~~~~~~~\n  MegaTop is currently the most advanced chart-generator for AmiExpress,\n  SigmaExpress, Daydream, Fame and Tempest.\n  It creates statistical charts (both total and weekly) using\n  user-definable design-files. This means for example that the sysop\n  can virtually design his own total-uploads with customized design!\n\n@{fg Shine}Features@{fg Text}\n~~~~~~~~\n  * User-definable design-files\n  * Mixing of all items in the same chart\n  * Intelligent date handler\n  * Weekly chart-mailing\n  * Presets\n  * Scripts\n  * Large item database\n  * Design output preview in Shell\n  * Various debugging modes\n  * Logfile\n\n              @{"[ <<<< ]" Link Copyright}              @{"[ Main ]" Link Main}             @{"[ >>>> ]" Link Installation}\n@EndNode\n\n@Rem ==================================================================\n@Node Installation "MegaTop v2.0 Documentation - Installation!"\n\n@{fg Shine}Installation@{fg Text}\n~~~~~~~~~~~~\n  Just use the included install-script!\n\n  If you for some reason don''t want/can''t use the install-script\n  then all you have to do is make a directory (optional, e.g. MegaTop)\n  in DOORS: and a sub-directory (optional, e.g. Design) for the\n  design-files. That''s it!\n\n\n\n              @{"[ <<<< ]" Link Introduction}              @{"[ Main ]" Link Main}             @{"[ >>>> ]" Link Requirements}\n\n\n@EndNode\n\n@Rem ==================================================================\n@Node Requirements "MegaTop v2.0 Documentation - Requirements!"\n\n@{fg Shine}Requirements@{fg Text}\n~~~~~~~~~~~~\n  * An Amiga (at least Release 2)\n  * AmiExpress (at least v3.x, not tested below!),\n    DayDream, SigmaExpress, Tempest BBS or Fame\n\n  * The DOORS: and T: assigns MUST be present!\n\n\n\n              @{"[ <<<< ]" Link Installation}              @{"[ Main ]" Link Main}             @{"[ >>>> ]" Link Usage}\n\n\n@EndNode\n\n@Rem ==================================================================\n@Node MakeDesign "MegaTop v2.0 Documentation - Usage : Make design files"\n\n@{fg Shine}Designfile formating@{fg Text}\n~~~~~~~~~~~~~~~~~~~~\n                             @{"     Cells     " Link Cells}\n                             @{"     Mail      " Link Mail} (NOT Tempest)\n                             @{"    Presets    " Link Presets}\n\n\n\n          @{"[ <<<< ]" Link Usage}              @{"[ Main ]" Link Main}             @{"[ >>>> ]" Link Credits}\n\n@EndNode\n\n@Rem ==================================================================\n@Node Usage "MegaTop v2.0 Documentation - Usage : Usage"\n\n@{fg Shine}Usage@{fg Text}\n~~~~~\n  MegaTop is to be executed when a user logoff.\n\n  The LOGOFF1.SCRIPT for node one can look like this:\n\n  -- cut --\n  DOORS:MEGATOP/MEGATOP SCRIPT=DOORS:MEGATOP/MEGATOP.SCR\n  -- cut --\n\n@{fg Shine}Arguments@{fg Text}\n~~~~~~~~~\n  DSG=<file>      - @{I}Design file@{UI}\n                    Enter full path pointing to the designfile.\n\n  DATA=<file>     - @{I}Userdata file@{UI}\n                    Enter full path pointing to the ''User.data''.\n                    Default path is ''BBS:USER.DATA''.\n\n  USERKEYS=<file> - @{I}UserKeys file@{UI} (AmiExpress)\n                    Enter full path pointing to the ''User.keys''.\n                    Default path is ''BBS:USER.KEYS''.\n\n  OUTPUT=<file>   - @{I}Output file@{UI}\n                    Enter full path pointing to the output-file.\n\n  SCRIPT=<file>   - @{I}Script file@{UI}\n                    Enter full path pointing to the @{"script-file" Link Scripts}.\n\n@{fg Shine}Options@{fg Text}\n~~~~~~~\n  SYSOP=<n>       - @{I}Sysop counting@{UI}\n                    0 = Include sysop (default).\n                    1 = Count sysop stats but hide him/her.\n                    2 = Do not include sysop.\n         \n  NOZERO          - Do not show users/fields with zero values.\n\n  FORCEMAIL       - Every mail will be mailed without checking the date.\n\n  DEBUG=<n>       - @{I}Debug information@{UI}\n                    Bit#\n                       0 (0)  = No debugging information (default).\n                       1 (1)  = Show settings.\n                       2 (2)  = User.data & Megatop.dat comparison\n                                Output to screen.\n                    e.g.  ''1'' and ''2'' : (1) + (2) = 3 : DEBUG=3\n\n  LOG=<n>         - @{I}Logfile@{UI} ( DOORS:MegaTop.Log )\n                    Bit#\n                       0 (0) = Off\n                       1 (1) = On\n\n  TEST            - @{I}Test mode@{UI}\n                    To test the output in the current window.\n                    Output file will also be generated.\n                    No WeekReset nor Mailing will be made.\n                    No logdata will be saved (even if you use LOG=x).\n\n\n              @{"[ <<<< ]" Link Requirements}              @{"[ Main ]" Link Main}             @{"[ >>>> ]" Link MakeDesign}\n@EndNode\n\n@Rem ==================================================================\n@Node Cells "MegaTop v2.0 Documentation - Usage : Cells!"\n\n@{fg Shine}Cells@{fg Text}\n~~~~~\n\n  @{fg Shine}NOTE!@{fg Text} The cell MUST contain at least two dots ''.'' (Used as seperators).\n        And the SysNum_Progname and SysNum_Author cells must be included,\n        or else they will appear in the bottom of the output file..\n\n      %[1.15-.ITEM.P]\n        |  |   |   |\n        |  |   |   `----- @{" Preset " Link Presets}\n        |  |   |\n        |  |   `--------- @{" Item " Link Items}\n        |  |\n        |  `------------- @{" Width " Link Width}\n        |\n        `---------------- @{" User position " Link UserPos}\n\n  Ex. %[1.10.UL_TOT_NAME]  : Valid\n      %[..SYSSUM_AUTHOR]   : Valid\n      %[.UL_TOT_NAME]      : Not Valid\n\n\n\n              @{"[ <<<< ]" Link Presets}              @{"[ Main ]" Link MakeDesign}             @{"[ >>>> ]" Link Mail}\n\n@EndNode\n\n@Rem ==================================================================\n@Node Preset "MegaTop v2.0 Documentation - Usage : Cells : Preset!"\n\n@{fg Shine}Preset@{fg Text}\n~~~~~~\n  There are two main datatypes from which MegaTop gathers data from:\n\n  * System/Week totals\n  * User totals\n\n  (See also @{" Presets " Link Presets})\n\n\n@EndNode\n\n@Rem ==================================================================\n@Node Width "MegaTop v2.0 Documentation - Usage : Cells : Width!"\n\n@{fg Shine}Width@{fg Text}\n~~~~~\n  -n    // Right justified\n  n-    // Left justified\n  -n-   // Centered\n\n  ''n'' stands for the width of the cell.\n  (If you don''t give a number the cell won''t be formated).\n\n              @{"[ <<<< ]" Link Items}              @{"[ Main ]" Link Cells}             @{"[ >>>> ]" Link Userpos}\n\n@EndNode\n\n@Rem ==================================================================\n@Node UserPos "MegaTop v2.0 Documentation - Usage : Cells : User position!"\n\n@{fg Shine}User position@{fg Text}\n~~~~~~~~~~~~~\n  Specifies the user position in list.\n  Negative numbers equal position counted from the end of list.\n\n              @{"[ <<<< ]" Link Width}              @{"[ Main ]" Link Cells}             @{"[ >>>> ]" Link Items}\n\n@EndNode\n\n@Rem ==================================================================\n@Node Items "MegaTop v2.0 Documentation - Usage : Items!"\n\n@{fg Shine}Items@{fg Text}\n~~~~~\n  Two sorts of formats exist:\n\n\n  Used for items that doesn''t have any users connected to it.\n\n  - @{" SYSTEM/WEEK TOTALS " Link ChartModes}_ITEM\n                           |\n                           +-----@{" Week items   " Link WeekItems}\n                           `-----@{" System items " Link SysItems}\n\n  Used for items that have users connected th it.\n\n  - @{" SORT-ORDER " Link SortOrder}_@{" DATA " Link Data}_@{" ITEMS " Link UserItems}\n\n              @{"[ <<<< ]" Link Userpos}              @{"[ Main ]" Link Cells}             @{"[ >>>> ]" Link Width}\n \n@EndNode\n\n@Rem ==================================================================\n@Node ChartModes "MegaTop v2.0 Documentation - Usage : Items : Chart modes!"\n\n@{fg Shine}Chart modes@{fg Text}\n~~~~~~~~~~~\n  SYSSUM                   // System summary\n                           // ie. Total upload on system or calls.\n\n  WEEKSUM                  // Week period summary\n                           // ie. Total upload this week.\n\n              @{"[ <<<< ]" Link Sysitems}              @{"[ Main ]" Link Items}             @{"[ >>>> ]" Link WeekItems}\n\n@EndNode\n\n@Rem ==================================================================\n@Node SortOrder "MegaTop v2.0 Documentation - Usage : Items : Sort order!"\n\n@{fg Shine}Sort order@{fg Text}\n~~~~~~~~~~\n  UL                       // Upload bytes\n  DL                       // Download bytes\n  ULS                      // Upload files\n  DLS                      // Download files\n  CALL                     // Calls\n  MESS                     // Messages posted\n  CPSUL                    // Sort data on Cps upload rate   (AmiExpress)\n  CPSDL                    // Sort data on Cps download rate (AmiExpress)\n  SLOT                     // Sort on users slotnumber\n\n              @{"[ <<<< ]" Link UserItems}              @{"[ Main ]" Link Items}             @{"[ >>>> ]" Link Data}\n\n@EndNode\n\n@Rem ==================================================================\n@Node Data "MegaTop v2.0 Documentation - Usage : Items : Data!"\n\n@{fg Shine}Data@{fg Text}\n~~~~\n\n  What type of data to be used.\n\n  WEEK                     // Week totals\n\n  WEEKTOT                  // ie. If you want to get the total upload\n                           // from the user how is first on the weektop.\n\n  TOT                      // System totals\n\n  TOTWEEK                  // ie. If you want to see how many calls the\n                           // user who is number one on the weektop.\n\n              @{"[ <<<< ]" Link Sortorder}              @{"[ Main ]" Link Items}             @{"[ >>>> ]" Link UserItems}\n\n@EndNode\n\n@Rem ==================================================================\n@Node WeekItems "MegaTop v2.0 Documentation - Usage : Items : Week items!"\n\n@{fg Shine}Week items@{fg Text}\n~~~~~~~~~~\n  BYTESUP                  // Upload bytes\n  BYTESDOWN                // Download bytes\n  FILESUP                  // Upload files\n  FILESDOWN                // Download files\n  CALLS                    // Calls\n  MESSAGES                 // Messages posted\n  NEWUSERS                 // New users this week\n  DELUSERS                 // Deleted users this week\n  DAYSLEFT                 // Days left on week inkl. current day\n  DAYSPASSED               // Passed days on week including current day\n\n              @{"[ <<<< ]" Link Chartmodes}              @{"[ Main ]" Link Items}             @{"[ >>>> ]" Link Sysitems}\n\n@EndNode\n\n@Rem ==================================================================\n@Node SysItems "MegaTop v2.0 Documentation - Usage : Items : System items!"\n\n@{fg Shine}System items@{fg Text}\n~~~~~~~~~~~~\n  BYTESUP                  // Upload bytes\n  BYTESDOWN                // Download bytes\n  FILESUP                  // Upload files\n  FILESDOWN                // Download files\n  CALLS                    // Calls\n  MESSAGES                 // Messages posted\n  USERS                    // Total accounts\n  DATE                     // Date when top was generated, e.g. ''22-04-95''\n  TIME                     // Time when top was generated, e.g. ''18:01:49''\n  PROGNAME                 // Name of program\n  AUTHOR                   // Name of author\n\n              @{"[ <<<< ]" Link WeekItems}              @{"[ Main ]" Link Items}             @{"[ >>>> ]" Link Chartmodes}\n\n@EndNode\n\n@Rem ==================================================================\n@Node UserItems "MegaTop v2.0 Documentation - Usage : Items : User items!"\n\n@{fg Shine}User items@{fg Text}\n~~~~~~~~~~\n  SLOTNR                   // Slot number\n  NAME                     // Name\n  LOCATION                 // Location\n  BYTESUP                  // Upload bytes\n  BYTESDOWN                // Download bytes\n  FILESUP                  // Upload files\n  FILESDOWN                // Download files\n  CALLS                    // Calls\n  MESSAGES                 // Messages posted\n  LASTONDATE               // Users last logon data ex. ''14-08-94''\n  LASTONTIME               // Users last logon time ex. ''20:35:43''\n  LCFILES                  // Lost carrier files (AmiExpress)\n  BYTERATIO                // Byteratio ''BYTESUP/BYTESDOWN''\n                              ex 10000 up 20000 dl = -2\n                                 20000    10000    =  2\n                                 10000    10000    =  0\n                                 10000        0    =  10000\n                                     0    10000    = -10000\n  FILERATIO                // fileratio FILESUP/FILESDOWN\n                              Same tactics as ''BYTERATIO''\n  CPSU                     // Top CPS upload rate (AmiExpress)\n                           // (only in ''TOT'' and ''WEEKTOT'')\n  CPSD                     // Top CPS download rate (AmiExpress)\n                           // (only in ''TOT'' and ''WEEKTOT'')\n\n              @{"[ <<<< ]" Link Data}              @{"[ Main ]" Link Items}             @{"[ >>>> ]" Link Sortorder}\n\n@EndNode\n\n@Rem ==================================================================\n@Node Mail "MegaTop v2.0 Documentation - Usage : Mail!"\n\n@{fg Shine}Mail@{fg Text}\n~~~~~\n\n @{fg Shine}NOTE!@{fg Text} Mail is configured in @{"presets" Link Presets}\n\n\n  MAIL= <mode>     - Mail persion\n                     ''WEEK''  // Weekly ( mondays )\n\n  SUBJECT=<string> - The subject of the mail\n\n  TO=<string>      - Where the mail will be sent ex.\n\n  FROM=<string>    - From who the mail will be marked as.\n\n  CONFPATH=<path>  - The path to the conference where you want the\n                     mail to be posted.\n\n  EXTERN=<file>    - External mailer\n\n                     For FAME users,\n                     This command line will be executed\n                                       \n                     <extern> FROM <from> TO <to> SUBJECT <subject>\n                              CONFPATH <confpath> FILENAME <megatopmsg>\n\n                     For DAYDREAM users,\n                     This command line will be executed\n\n                     <extern> FROM <from> TO <to> SUBJECT <subject>\n                              CONF <confpath> MESSAGE <megatopmsg>\n\n                     Values between <> is replaced by the values abow\n\n  BASE=<baseno>      ** DayDream version Only **\n                     Message base number\n\n\n@{fg Shine}Example@{fg Text}\n~~~~~~~\n  -- cut --\n  BEGIN PRESET\n\n   MAIL=WEEK SUBJECT="Week result" TO="EALL" FROM="MegaTop" CONFPATH="BBS:CONF1/"\n\n   PRESET=1 B=0 V=M\n   PRESET=2 C=U\n   etc...\n  END PRESET\n   etc..\n  -- cut --\n\n              @{"[ <<<< ]" Link Cells}              @{"[ Main ]" Link MakeDesign}             @{"[ >>>> ]" Link Presets}\n\n@EndNode\n\n@Rem ==================================================================\n@Node Presets "MegaTop v2.0 Documentation - Usage : Presets!"\n\n@{fg Shine}Presets@{fg Text}\n~~~~~~~\n  @{fg Shine}NOTE!@{fg Text} You can''t mix BREAKPOINT''s and EQUAL''s.\n\n  PRESET=<presetnumber> - This is the presetnumber used in @{"cells" Link cells}.\n                          Has to be on EVERY preset row.\n\n  LEVEL=<levelnumber>   - Only used with ''B'' or ''E''.\n\n  MAIL=<period type>    - Mail period (See @{"mail" Link Mail})\n\n                          ''WEEK''  // Mail every week ( Monday )\n\n  V=<c>      - Output type\n\n               ''B'' = Bytes\n               ''K'' = Kilobytes\n               ''M'' = Megabytes\n               ''T'' = Thousand\n\n  B=<n>      - Breakpoints\n\n               Example:                                              Range\n\n               LEVEL=1 B=10 // Do that if value is 10 or less      ( x - 10 )\n               LEVEL=2 B=20 // Do that if value is 20 or less      ( 20- 11 )\n               LEVEL=3 B=30 // Do that if value is higher or equal ( 30-  x )\n\n  E=<n>      - Equal\n\n               Example:\n\n               LEVEL=1 E=10 // Do that if value is 10\n               LEVEL=2 E=20 // Do that if value is 20\n               LEVEL=3 E=!  // Otherwise do this.\n\n               If no criteria is valid an empty string will be returned.\n\n  M=<char>   - Type of seperator character, ( ONLY ONE CHAR ).\n               Works only on Numeric strings!\n\n               Example:\n\n               1.000.000 // M=.\n               1-000-000 // M=-\n\n  P=<string> - Prefix, String will be inserted added infront of item text/value\n\n  S=<string> - Suffix, String will be added last of item text/value\n\n  C=<c>      - Case mode\n\n               ''U'' = UPPER\n               ''L'' = lower\n               ''I'' = Indent\n\n@{fg Shine}Preset Example@{fg Text}\n~~~~~~~~~~~~~~\n\n  -- Cut --\n\n  BEGIN PRESET\n\n   PRESET=1 M=.\n\n   PRESET=2 V=K M='' P="Before " S=" After"\n\n   PRESET=3 LEVEL=1 V=B B=0        S=" Bytes"\n   PRESET=3 LEVEL=2 V=K B=1024     S=" Kb"\n   PRESET=3 LEVEL=3 V=M B=1024000  S=" Mb"\n\n  END PRESET\n\n  System total download : %[.-40.SYSSUM_BYTESDOWN.1]\n  System total download : %[.-40.SYSSUM_BYTESDOWN.2]\n  System total download : %[.-40.SYSSUM_BYTESDOWN.3]\n\n  -- Cut --\n\n@{fg Shine}Explanation@{fg Text}\n~~~~~~~~~~~\n\n Preset number 1 (PRESET=1) is a very simple one. It just puts\n  points (M=.) in value, ex 1.000.000.\n\n Preset number 2 (PRESET=2) Makes the valus as Kilobytes (V=K) and\n  puts the text ''Before'' in front of the value (P="Before ") and\n  the text string ''After'' (S=" After") after the value.\n\n Preset number 3 (PRESET=3) Here is a tricky one. If we want to control the\n  value we can use Breakpoints, that means if the valus is greater than a\n  number it changes. Every value lower and equal than 0 (B=0) will have\n  the suffix " Bytes" (S=" Bytes") and the value will be in bytes (B=0).\n\n\n              @{"[ <<<< ]" Link Mail}              @{"[ Main ]" Link MakeDesign}             @{"[ >>>> ]" Link Cells}\n\n@EndNode\n\n@Rem ==================================================================\n@Node Scripts "MegaTop v2.0 Documentation - Usage : Scripts!"\n\n@{fg Shine}Scripts@{fg Text}\n~~~~~~~\n\n  * Recommended strongly, for fast generation of output files.\n\n  * Comments begins with '';'' everything behind that is ignored.\n\n  * Option ''SYSOP=<n>'' in script file doesn''t work.\n    You have to specify ''SYSOP=n'' as command line argument if you\n    want sysop option.\n\n    ie. MegaTop SCRIPT=MegaTop.script SYSOP=2\n                                       ^^^^^^^\n                                         `-- This excludes sysop counting\n                                             in all outputs generated in\n                                             the script.\n\n    ie.  -- cut --\n         DSG=DOORS:MegaTop/Dsg/Weektop.dsg OUTPUT=RAM:WeekTop.txt NOZERO\n         DSG=DOORS:MegaTop/Dsg/Top10.dsg   OUTPUT=RAM:Top10.txt\n         --- cut ---\n\n              @{"[ <<<< ]" Link Usage}              @{"[ Main ]" Link Main}             @{"[ >>>> ]" Link Usage}\n\n@EndNode\n\n@Rem ==================================================================\n\n@Rem ==================================================================\n@Node Credits "MegaTop v2.0 Documentation - Credits!"\n\n                                    @{fg Shine}Credits@{fg Text}\n                                    ~~~~~~~\n  * Looby/Insane      - MegaTop Programmer, install-script, Documentation\n  * Cluster/Insane    - Documentation, No.1 Beta tester, Ideas/Suggestions\n  * Marx/Insane       - Documentation\n  * Nightshade/Insane - Beta Tester\n  * Shade/Insane      - Beta Tester\n  * MadMax/Insane     - Beta Tester\n\n  * Thanks to:\n\n    Bobo, BugByte, Cluster, Distler, Ezco & Sandman\n    Newt/Crux, Skeleton, WildThing, Mathews, Baffle,\n    Jupiter8, Hydra, Allah, Mr Terry, Faktor, Cateye\n    and everybody out there using Megatop.\n\n                                          / LOOBY\n\n\n              @{"[ <<<< ]" Link Makedesign}              @{"[ Main ]" Link Main}             @{"[ >>>> ]" Link History}\n\n@EndNode\n\n@Rem ==================================================================\n@Node History "MegaTop v2.0 Documentation - History!"\n\n@{fg Shine}History@{fg Text}\n~~~~~~~\n\n@{fg Shine}17-Feb-97 Rev5 v2.0@{fg Text}\n¯"¯"¯"¯"¯"¯"¯"¯"¯"¯\n* External mail added\n\n  Preset added for mail:\n        ''EXTERNAL'' // External mailer\n\n                   For FAME users,\n                   This command line will be executed\n                                       \n                   <external> FROM <from> TO <to> SUBJECT <subject> CONFPATH <confpath> FILENAME <megatopmsg>\n\n                   For DAYDREAM users,\n                   This command line will be executed\n\n                   <external> FROM <from> TO <to> SUBJECT <subject> CONF <confpath> MESSAGE <megatopmsg>\n\n                   For TEMPEST users,\n                   This command line will be executed\n                   \n                   <external> -A<confpath> -F<from> -S<subject> -X<megatopmsg> -Y2\n                   \n                   Values between <> is replaced by the values in the \n                   DSG file header (se Mail>.\n\n* Argument added\n       ''FORCEMAIL'' // Every mail will be mailed without checking the date.\n\n@{fg Shine}30-Jun-96 Rev4 v2.0@{fg Text}\n¯"¯"¯"¯"¯"¯"¯"¯"¯"¯\n  * Bars added.\n    Preset ''BARVAL''   // Bar max value\n                      // If this isn''t specified it uses the \n                      // value from userposition 1.\n           ''BARSTR''   // Bar string, Predefined barstring\n                      //             MegaTop will calculate how\n                      //             much of the string that will\n                      //             be shown.\n                      // NOTE! Can''t be uses together with ''BARCHR''\n           ''BARCHR''   // Bar char, Barstring char\n                      // NOTE! Can''t be uses together with ''BARSTR''\n\n  * Fame version available, Mail isn''t converted yet!\n  * DayDream version available, Mail isn''t converted yet!\n\n@{fg Shine}06-Jan-96 Rev2 v2.0@{fg Text} (not released)\n¯"¯"¯"¯"¯"¯"¯"¯"¯"¯\n  * Bug fixed: DAYSPASSED was DAYSLEFT and DAYSLEFT was DAYSPASSED.\n  * New value preset added:\n\n    V=<type>   ;  Type\n               ;--------------------------\n               ;  ''NONE''     = No value\n               ;  ''BYTE''     = Bytes\n               ;  ''KBYTE''    = Kilobytes\n               ;  ''MBYTE''    = MegaBytes\n               ;  ''THOUSAND'' = Thousands\n               ;  ''DATE''     = Show as date format\n               ;  ''TIME''     = Show as time format\n               ;  ''SEC''      = The value in sec\n               ;  ''MIN''      = ---- || ---- Minutes\n               ;  ''HOUR''     = ---- || ---- Hours\n               ;  ''DAY''      = ---- || ---- Days\n               ;  ''SS''       = Seconds\n               ;  ''MM''       = Minutes\n               ;  ''HH''       = Hours\n               ;  ''YY''       = Year\n               ;  ''MO''       = Month\n               ;  ''DD''       = Day\n\n\n@{fg Shine}05-May-96 Rev3 v2.0@{fg Text}\n¯"¯"¯"¯"¯"¯"¯"¯"¯"¯\n  * Tempest version available (80%). Mail isn''t converted yet!\n\n@{fg Shine}03-Jan-96 Rev1 v2.0@{fg Text}\n~~~~~~~~~~~~~~~~~~~\n  * First release!\n\n@{fg Shine}11-Apr-95 Rev1 v1.0@{fg Text}\n~~~~~~~~~~~~~~~~~~~\n  * MegaTop was born, as Requested by Cluster!\n\n\n\n              @{"[ <<<< ]" Link Credits}              @{"[ Main ]" Link Main}             @{"[ >>>> ]" Link Support}\n\n@EndNode\n\n@Rem ==================================================================\n@Node Support "MegaTop v2.0 Documentation - Support!"\n\n@{fg Shine}Contact Me!@{fg Text}\n~~~~~~~~~~~\n  To get in touch with me, try the following mediums:\n\n  IRC   - #amielite, Nick LOOBY\n\n  EMAIL - [email removed]\n\n  BBS   - +46-8-7595847 [Insanitary: iNS-WHQ!]\n\n@{fg Shine}Support@{fg Text}\n~~~~~~~\n  To get the latest version of MegaTop or new design files use:\n\n  WWW - http://www.canit.se/~andersw/megatop.html\n\n\n\n              @{"[ <<<< ]" Link History}              @{"[ Main ]" Link Main}             @{"[ >>>> ]" Link Boards}\n\n@EndNode\n\n@Rem ==================================================================\n@Node Boards "iNSANE wORLDWiDE bOARDS!"\n  ._________________________________________________________________________.\n  |                                                                         |\n  |              · Don''t Hesitate To Call These Insane HQ''s! ·              |\n  |                                                                         |\n  |     o1. Insanitary      -  World HeadQuarter     -   +46-8-7595847!     |\n  |         Insanitary      -  World HeadQuarter     -   +Ask-4-Telnet!     |\n  |     o2. The Chameleon   -  European HeadQuarter  -   +358-815409545     |\n  |         The Chameleon   -  European HeadQuarter  -   +358-815409589     |\n  |         The Chameleon   -  European HeadQuarter  -   +358-815546450     |\n  |     o3. Death Row       -  US HeadQuarter        -   +1-801-4769068     |\n  |         Death Row       -  US HeadQuarter        -   +1-801RingDown     |\n  |         Death Row       -  US HeadQuarter        -   +Ask-4-Telnet!     |\n  |     o4. Dial Hard       -  Swizz HeadQuarter     -   +41-735-065-25     |\n  |         Dial Hard       -  Swizz HeadQuarter     -   +41-73RingDown     |\n  |     o5. Sky Tower       -  Dannish HeadQuarter   -   +45-74-833886!     |\n  |         Sky Tower       -  Dannish HeadQuarter   -   +45-74RingDown     |\n  |     o6. Asylum          -  Swedish HeadQuarter   -   +46-303-798622     |\n  |         Asylum          -  Swedish HeadQuarter   -   +46-303-798920     |\n  |     o7. EveryWare       -  Norweigan HeadQuarter -   +47-639-541-90     |\n  |     o8. Fatal Justice   -  Distant HeadQuarter   -   +45-31118-2284     |\n  |__                                                                     __|_\n  |_/________  /\_________________________________________________________\_|\n  :          \/\n              @{"[ <<<< ]" Link Support}              @{"[ Main ]" Link Main}             @{"[ >>>> ]" Link Main}\n\n@EndNode\n','\n',char(10)),NULL,'auto-added',171517,6,0,NULL,NULL,'ins_mt5','scan',1780048553);
INSERT INTO door_catalog VALUES('ins_rq10','INS-RQ10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/INS-RQ10.LHA','Request','XIM','Request',NULL,'Metal/Insane','INS','-_/ _/  \ _/  _______ _/  \ _/  ___/-------- \_ \_  \\\____ \_  _ \_  \\\_  _/_. iNSANE |  |  |\ |  !  |  |  |  |\ |  !  | ------',replace('kRm_____:  .______________.  :______\n-_/ _/  \ _/  _______ _/  \ _/  ___/--------\n \_ \_  \\\____ \_  _ \_  \\\_  _/_. iNSANE\n  |  |  |\ |  !  |  |  |  |\ |  !  | ------\n  ¦  l__|  l__   l__|  l__|  l__   |  1995\n--:  ·--l__|--\__|--l__|--l__|--\__|--------\n----------------[ Presents ]----------------\n         Request V1.00 for /X V3.x+\n  Coded in 100% Assembler by: Metal/Insane\n','\n',char(10)),'Request.Guide',replace('@database Request.guide\n@$VER: Request Document (23.03.95) - Editors: Metal&Cluster\n\nThis is a document in the AmigaGuide format.  To read it, use either\nAmigaGuide, MultiView, or any other AmigaGuide compatible hypertext\nbrowser.\n\n@node Main "Contents"\n\n===============================================================================\n=                                                                             =\n=                       Request  V1.00 by: Metal/Insane                       =\n=                                                                             =\n=                    MC68000/020 Code for AmiExpress V3.x+                    =\n=                                                                             =\n===============================================================================\n\n                                @{" Introduction " link Introduction}\n                                @{" Requirements " link Requirements}\n                                @{" Installation " link Installation}\n                                @{" ToolTypes    " link ToolTypes}\n                                @{" Last Words   " link Addys}\n\n@endnode\n\n\n@node Introduction "Introduction Text"\n\n@{b}Request@{ub} is a AmiExpress XIM Door coded in 100% Assembler.\n\nThe reason why I decided to develope  and now 5 months later  release\nthis door, is because a  sysopfriend of mine - Cluster  (The sysop of\nINSANITARY  BBS)  wanted  to  have a  Requests advertisment door. So,\nI made this door for him and now after several months of usage at his\nBoard we''ve got great response about it''s function as a vital part of\na BBS who wishes to have a Requests advertising conf., and so we have\ndecided to share this great door with you other sysops..\n\nNow,I sincerely hope that you ain''t that stupid wondering in what way\nsuch a door like this one could ever make it more comfortable for the\nusers in any way, so i''ve left the ''whyuse-part'' out of this docfile.\n\nIf you got some ideas, suggestions or bugreports to make, or just for\nthe pure fun of sharing your thoughts and wonders  about life and the\nscene, don''t you hesitate to write me a message  at any of the Insane\nBoards.. Who knows, maybe you  got this  great idea of yours of yet a\ngreat Amixdoor that I might be interested in developing...\n\n@endnode\n\n\n@node Requirements "Requirements Text"\n\n@{b}Requirements.@{ub}\n\n· OS 2.0+\n· AmiExpress V3.x+\n\n@endnode\n\n\n@node Installation "Installation Help"\n\n@{b}Installation.@{ub}\n\nJust extract the Lha Package or Copy all Dirs/Files into  your  "BBS"\nDirectory, and you''ll have it perfectly installed.\n\nHere we have a list of them files who should be lying in them Directories.\n(located in BBS:)\n\nCommands/BBSCmd/REQ.info     <- InfoFile for /X to execute when you type "REQ"\nDoors/Request/Request        <- The Groovy DOOR.\nDoors/Request/Request.info   <- The Info file which consists the preferences.\n\n@endnode\n\n\n@node ToolTypes "ToolTypes Info"\n\n@{b}ToolTypes.@{ub}\n\nNAME.LEN=13                  <- 13 = Max Amount of Characters that the NAMES\n                                     will consist of.\nDATE.LEN=9                   <-  4 = Max Amount of Characters that the DATES\n                                     will consist of.\nREQUEST.LEN=47               <- 32 = Max Amount of Characters that the user\n                                     will have available for describing his\n                                     request(s).\n\nNAME.DESC=Name/Alias         <- "Name/Alias" is the Column Description for\n                                 the name of the users.\n\nTOPLOGO=DOORS:Request/ReqLogo<- "DOORS:Request/ReqLogo" The TopLogo which will\n                                 be shown at the top of the "OutPut" file and\n                                 also when a User executes the Door.\nOUTPUT=BBS:Request/Bull30.txt <- "BBS:BuySell/Bull30.txt" is the filename of\n                                  the OutPut text.\n\n@endnode\n\n\n@node Addys "Authors Last Words..."\n\nWell, I guess there ain''t much more left to say except that I sincerely\nhope you will find this door useful and that you make the best out of it.\n\nTo reach me or any other of the Insane /X developers, you should dial our\n\n    - World HeadQuarter BBS - INSANITARY at +46-8-7595847 (Sweden) -\n\nBtw: Check out my Buy&Sell door if you liked this one. It looks almost alike,\n     allthou there are different  configurations and it  consequently results\n     in a more suitable look for a buy&sell advertising conference...\n\n@endnode\n\n','\n',char(10)),NULL,'auto-added',30333,6,1,'req','Doors/Request','ins_rq10','scan',1780048553);
INSERT INTO door_catalog VALUES('ins_s103','INS-S103.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/INS-S103.LHA','sKAN^4^sTATUs','XIM','sKAN^4^sTATUs',NULL,NULL,'INS','/__\___|   _ /   ____/__  .___|   _ /Skin /    \  \   //____   /  /__|   \   //_______ \____/   \ ./______ /  /\   \   \ ./  _____/',replace('  /\    :______/\______        :______      \n /__\___|   _ /   ____/__  .___|   _ /Skin  \n/    \  \   //____   /  /__|   \   //_______\n\____/   \ ./______ /  /\   \   \ ./  _____/\n   _|___\  /      \/_________\_\  /  _____/ \n::::|::::\/:: P r e s e n t s ::\/_______/::\n::                                        ::\n:: sKAN^4^sTATUs V1.03 - ©1995 .mX/iNSANE ::\n::                                        ::\n:: uSER sTATUS dOOR (XIM) fOR aMiX v3.X-> ::\n::                                        ::\n::::::::::::::::::::::::::::::::::::::::::::\n','\n',char(10)),'sKAN^4^sTATUs.guide',replace('@database "sKAN^4^sTATUs.guide"\n@node MAIN\n@title "sKAN^4^sTATUs · cODED bY mARX/iNSANE!"\n      .......\n      ::....:\n      .......   -  - -- --------------.                .---- -- -  -\n    __:_____:__ __ _   _________     _|_______ _ ______|__ _ _  .............\n   /  :     :  \\    _/  ______/___ /         \           \\   :      ..     :\n  /   :     :   \ ___\______       /           \           \ __:.______:     :\n /    :     :  \ \        /       / i n s a n e \         \ \  ::.   ..\.....:\n/_____::____:___\ \   _ _________/____.__________\ ____.___\ \ ·:::.....\...:\n      :::...:    \            \splat  |:.          ..::|e^d \            \\n                  \____________\    .-|----------------''     \____________\\n                                    `-''\n           p · R · O · U · D · L · Y   p · R · E · S · E · N · T · S\n\n                          -> sKAN^4^sTATUs V1.03! <-\n\n                    All coding & developing by -mARX/iNSANE!\n\n                           @{" ->  Introduction  <- " link INTRODUCTION }\n                           @{" ->  Requirements  <- " link REQUIREMENTS }\n                           @{" ->  Installation  <- " link INSTALLATION }\n                           @{" ->   The Future   <- " link THE_FUTURE }\n                           @{" ->    Epilogue    <- " link EPILOGUE }\n                           @{" ->     Credits    <- " link CREDITS }\n@endnode\n\n@node INTRODUCTION\n@title "sKAN^4^sTATUs · cODED bY mARX/iNSANE!"\n+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+\n\nIntroduction:\n~~~~~~~~~~~~~\n\nsKAN^4^sTATUs V1.03 features:\n\n** 100% M680x0 ASM-code (faaaaaaast!)\n** VERY cool dezign (Hiya cLUSTER!)\n\nsKAN^4^sTATUs V1.03 does NOT feature:\n\n** Configuration abilities upto 99% (YET!)\n\n\n\nYepp! I''m back! This time with another cool release... sKAN^4^sTATUs V1.03!\nAlthough none of my projects start without the goal in mind of making them\nNO.1 in whatever /X cathegory of tools they might belong to, this one can\nreally make you scratch your head. It is as simple as a alternative to the\n1000 status-doors already available! Now, WHAT makes this one so special?\nWell, at this stage of development, almost nothing! At least, if you ignore\nthe VERY COOL DEZIGN (which you really can''t ignore, can you? ;) The real\nadvantage of this baby, is... the forthcoming features! (Read ''THE FUTURE''!)\nI have sum great fockin'' plans for this one (as always...) and you''re gonna\nsee the kind of features that nobody ever seen in a goddam status-door!\n\nA status-door has one task, and that is to display relevant information to\nthe user. It is also very easy to code such a door. Since it''s considered\nbeing the first door one codes, many people have done their own version.\nNow, the amount of information doesn''t grow with newer versions of /X.\nSo, the only significant change from door to door is... the design!\n\n+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+\n@endnode\n\n@node REQUIREMENTS\n@title "sKAN^4^sTATUs · cODED bY mARX/iNSANE!"\n+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+\n\nRequirements:\n~~~~~~~~~~~~~\nsKAN^4^sTATUs V1.03 requires:\n\n** AmiExpress 3.xx      (Doesn''t everybody have it?)\n** Kickstart 2+         (Doesn''t everybody have it?)\n** Motorola 68020+      (Doesn''t everybody have it?)\n\n+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+\n@endnode\n\n@node INSTALLATION\n@title "sKAN^4^sTATUs · cODED bY mARX/iNSANE!"\n+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+\n\nInstallation:\n~~~~~~~~~~~~~\n\nVery easy! All you need is the executable itself. Simply modify the\nBBS:Commands/BBSCmd/S.info to point to skAN^4^sTATUs.\n\n... and you''re READY TO GO!\n\n+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+\n@endnode\n\n@node THE_FUTURE\n@title "sKAN^4^sTATUs · cODED bY mARX/iNSANE!"\n+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+\n\nThe Future:\n~~~~~~~~~~~\n\nCurrently, I''m busy surviving the military service. Although I have great\nplans for this baby, that must be taken into consideration. The goal is to\nmake it independent of the traditional hardcoded design. That means that YOU\nwill be able to create design-files for it. Only your imagination will be\nyour obstacle!\n\nNow imagine yourself that YOU can design your own status-door. Cool, huh?\nWell, that''s the point! It''s existance will eliminate every need of\nalternative status-doors!\n\nIn short, I''m gonna take this baby so far...... aaaaaaaaarrrrrrrgh!\n\n+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+\n@endnode\n\n@node EPILOGUE\n@title "sKAN^4^sTATUs · cODED bY mARX/iNSANE!"\n+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+\n\nEpilogue:\n~~~~~~~~~\n\nThis is my second /X-util that I release and I hope it won''t be the last.\nIt''s a small project and I hope you find it useful and easy to use.\nIf you for any reason feel the need of contacting me (Bugs? NAH! :)) please\ndo so! I can be reached at most groovy bulletine board systems (the majority\nof them are located in Stockholm/Sweden).\nJust write me a msg at any of these:\n\n\n\n** Insanitary [iNS WHQ]         Sysop:  cLUSTER/iNS\n** Asylum     [iNS SHQ]         Sysop:  jUAN/iNS^tRSI\n\n** Flashback                    Sysop:  tWiSTeR/oGN^dCS\n** Undercover                   Sysop:  DeMaX/dLT^rYL\n** Instant Pleasure             Sysop:  nIKE/tRSI^cRZ\n\n\n\nmARX/iNSANE signing off...\n\n+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+\n@endnode\n\n@node CREDITS\n@title "sKAN^4^sTATUs · cODED bY mARX/iNSANE!"\n+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+\n\nCredits:\n~~~~~~~~\n\nCoding & Developing.................:   mARX/iNSANE\nDesign & ßeta-testing...............:   cLUSTER/iNSANE\nSuggestions, Ideas & /X Help........:   nIKE/tRSI^cRZ\n\nßeta-testers (alpha order):\n\nFlashback               (at least for a couple of hours, huh mate? ;))\nInsanitary              (as always!)\nInstant Pleasure        (sum people like to piss others off ;))\nPalladium               (curiosity killed the shark ;))\n\nsKAN^4^sTATUs was developed on a A4000/030 with 14Mb RAM and OS3.0!\n\n+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+:+\n@endnode\n','\n',char(10)),NULL,'auto-added',7710,1,0,NULL,NULL,'ins_s103','scan',1780048553);
