------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                                                .------''\n             `------------------------------------------------''\n','\n',char(10)),NULL,'auto-added',11315,6,0,NULL,NULL,'ivn_ax12','scan',1780048560);
INSERT INTO door_catalog VALUES('ivn_n05','IVN-N05.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/IVN-N05.LHA','nups','XIM','MFM-Nuke (12/8-95) by MFM/Invasion.','0.05','MFM/Invasion.','IVN','Works with AmiExpress and Sigma Express.',replace('MFM-Nuke v0.05 (12/8-95) by MFM/Invasion.\nWorks with AmiExpress and Sigma Express.\n','\n',char(10)),'nups.readme',replace('This is just a little bonus for ya, and its the original version I wrote in\n1994 and not a byte is changed since then.\n\nThis is an old program I wrote after an idea from rAD!/LSD on MegaLoMania.\nIt''s a door to store nups (new user passwords) in a database, and I recommend\nthat you dont give all lamers access to it if you wish to use it seriously.\nIt was made in 1-2 hours writing the whole door from scratch so the design is\nnot the very best. Test it and see what you think! It uses AEDoor.library\nv2.x. Just make a standard /X icon, TYPE=XIM etc. At start it creates (if\nit doesn''t exist) a directory called ''Doors:Nups'' and there is where it\nstores its datafiles. \n\nSee ya!       MFM\n','\n',char(10)),'{"TYPE":"XIM"}',NULL,33335,7,0,NULL,NULL,NULL,'scan',1780048560);
