\n    \              uLI ·» bBS fLYING sAUCER    «·                 \\n     \               cREEPING-dEATH   «-»  cODER&tRADER            \ \n      \              bULLDOZER        «-»  cODER                    \__\n       \                   mR.b!G     «-»  tRADER                     /\n        \                  dR.bubka   «-»  tRADER                    /\n         \                 pILLE      «-»  tRADER                   /   \n          \                 eASA       «-»  tRADER                 /  \n           \                sABREWOLF  «-»  tRADER                /\n            \               sTEAM      «-»  cODER&tRADER         /     \n             \              cLAWFINGER «-»  tRADER              /\n     _____ __(  ...and best regards to our beloved enemies...   )____\n      \          <----------------------------------------->        /\n      ·     ... Thanx to cREEPING-dEATH for his really great Tool ...    ·\n        \________                                                _/___\n      (_\_   ___\_                                              (/  _/\n        \)  \   \)                       _____________________(/\n _  _ _______\__________________________/\n              \)  \n\naMD eVERYONE, wHO i hAD fORGOTTEN !\nfUCK aLL aRROGANTE tRADERS !\n\n@ENDNODE\n\n\n                                           (»·CrEEpIn-DeaTh·/·i^c!·«)\n\n\n','\n',char(10)),NULL,'auto-added',26474,5,0,NULL,NULL,'i_c','scan',1780048560);
INSERT INTO door_catalog VALUES('i_c_st','I^C.ST.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/I^C.ST.LHA','status','XIM','Intro D^R 2',NULL,'cREEPiN-DEATH',NULL,'(_____ \___ \___/__  /__/_ \___ \___/_ \___/ / \_/  / /  /_) /__/_)  /  / /  /_) /  / \_ /   /___\___/___/__l____/___\___/___/___\  /',replace(' ______ _________ _________ ________________\n(_____ \___ \___/__  /__/_ \___ \___/_ \___/\n / \_/  / /  /_) /__/_)  /  / /  /_) /  / \_\n/   /___\___/___/__l____/___\___/___/___\  /\n\__/-------------------------prO/i^C--/___/+\n|    INdePEndENt^COnnECtiON presents:      |\n| Status-Door 1.0  Coded by cREEPiN-DEATH  |\n|            qL Status-Door                |\n| wORKS oN aLL cURRETLY uSED /X vERSIONS.  |\n| Status-Door (i^C//X-Design) ©.20-06-95   |\n`------------------------------------------''\n','\n',char(10)),'status.guide',replace('@DataBase Logoff Dokumentation\n@Author cREEPIN-DEATH\n@Remark $VER:  v1.0 by cREEPIN-DEATH\n@Node MAIN "sTATUS cODING bY cREEPiN-DEATH!\n\n\n\n                           PrESENTS  \n\n                cODED 1995 bY CReEPIn-DeatH \n\n              ----- --- -> sTATUS v1.0 <- --- -----\n\n                      ->> qL /X-Tool <<-\n\n                       -@{" D e S C R I P T I O N " Link Description}          \n                       -@{" I n S T A L L A T I O N " LINK inst}          \n                       -@{" S u P P O R T " Link support}                    \n                       -@{" G r E E T Z " Link Greetings}                      \n\n                                                  (»·CrEEpIn-DeaTh·/·i^c·«)\n\n@endnode\n\n@NODE inst\njUZT cOPY tHE fILE "s.info" 2 bbs:coomands/bbscomands/\naND tHE dIRECTORY "status" tO yOUR dOORS: dir ...\n\nwELL tHATZ aLL .....\n\n\n@ENDNODE\n\n@NODE support\n___________ _ ____ ____________ _____________ _ _____ ______________________\n (_________  \_____ \_  _______  \_  ________  \______ \_  ________  \_______/\n /    \_ /    /   /  /___/_   /___/___/_   /    /    /  /___/_   / 