INSERT INTO door_catalog VALUES('jmenu','JMENU.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/JMENU.LHA','JumpMenu','XIM','JumpMenu',NULL,NULL,NULL,'LETS USERS JUMP CERTAIN MENUS -------------------------------------------- DEPENDING ON THERE ACCESS!',replace('============================================\nLETS USERS JUMP CERTAIN MENUS\n--------------------------------------------\nDEPENDING ON THERE ACCESS!\n============================================\n','\n',char(10)),'JumpMenu.doc',replace('        JumpMenu version 1.0 by Robert Masters for MAXsBBS 1.52\n\nJumpMenu is a door for automaticly putting users into differant menus\ndepending on access levels. It can be run either through a script or\nfunction 34.\n\nTo configure, run with argument -C, you can then set upto 10 levels of\ntesting. You can use as few levels as you wish, just be sure that you\nhave covered all access levels from 0 to 10000.\n\nThe low access limit of each level will be filled automaticly with the\nhigh access of the previous entry plus 1.\n\nStarting at 0, enter the access ranges and the menu to send them to,\nwhen you have finished, hit ''Q'' to quit and save the configuration.\n\n\nNotes:\n\n1.0 -  First release.\n\n\n         Thanks to Norbert Feist for Beta testing this program.\n\n         For bug-reports and updates, call The Nut Factory BBS.\n\n              V.22 V.22bis                  (02) 822-5613\n\n              V.32 V.32bis V.42 V.42bis     (02) 822-4366 \n\n              \n\n','\n',char(10)),NULL,'auto-added',27737,6,0,NULL,NULL,'jmenu','scan',1780048560);
