INSERT INTO door_catalog VALUES('joinc40','JOINC40.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/JOINC40.LHA','JoinCnf','XIM','JoinCnf',NULL,NULL,NULL,'¦_/\___/\___/\___                          ¦ |\   /\ __/_  __/ Added Features:          | |/ Y \/_.¬\/  \   o Totally NEW Lay-Out    |',replace('+[ MYSTiC /X-POWER ]-----[ JoinCnf 4.0 ]---+\n¦_/\___/\___/\___                          ¦\n|\   /\ __/_  __/ Added Features:          |\n|/ Y \/_.¬\/  \   o Totally NEW Lay-Out    |\n/  | \\¬¦ \\  \\  o Manages up to 256 Cnfs |\n\__l_//___//__//                           ¦\n|dL!\/   \/  \/    Try it and be AMAZED!!  |\n+-[ EMPiRE/MYSTiC ]----[ XIM - /X 3.38+ ]--+\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                                                .------''\n             `------------------------------------------------''\n','\n',char(10)),NULL,'auto-added',34712,7,0,NULL,NULL,'joinc40','scan',1780048560);
INSERT INTO door_catalog VALUES('joincf40','JOINCF40.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/JOINCF40.LHA','JoinCnf','XIM','JoinCnf',NULL,NULL,NULL,'¦_/\___/\___/\___                          ¦ |\   /\ __/_  __/ Added Features:          | |/ Y \/_.¬\/  \   o Totally NEW Lay-Out    |',replace('+[ MYSTiC /X-POWER ]-----[ JoinCnf 4.0 ]---+\n¦_/\___/\___/\___                          ¦\n|\   /\ __/_  __/ Added Features:          |\n|/ Y \/_.¬\/  \   o Totally NEW Lay-Out    |\n/  | \\¬¦ \\  \\  o Manages up to 256 Cnfs |\n\__l_//___//__//                           ¦\n|dL!\/   \/  \/    Try it and be AMAZED!!  |\n+-[ EMPiRE/MYSTiC ]----[ XIM - /X 3.38+ ]--+\n','\n',char(10)),'JoinCnf.DOC',replace('\n                  ###### ###   ## ######  ### ######  ######              \n    _______|\     ###    #### ### ###  ## ### ###  ## ###       /|________\n   |         >    ####   ######## ######  ### ######  ####     <         |\n   | |¯¯¯¯¯|/     ###    ### # ## ###     ### #####   ###       \|¯¯¯¯¯| |\n   | |            ###### ###   ## ###     ### ### ##  ######           | |\n   | |_________________________________________________________________| |\n   |                                                                     |\n   |                            JoinCnf V4.0                             |\n   |                            ~~~~~~~~~~~~                             |\n   |                             TYPE:  XIM                              |\n   |                                                                     |\n   |                   ©1994  EMPiRE / MYSTiC /X-PoWeR!                  |\n   |                                                                     |\n   |       LaSt OuTpOsT  +31-72-157682 & +31-72-201182  -  HOLLAND       |\n   |                                                                     |\n   |       AmixNet:  @NL0004   -   /X-Fido:  44:100/102     EMPiRE       |\n   |_____________________________________________________________________|\n \n===============================================================================\n\n PURPOSE:\n ~~~~~~~~\n  o This DOOR is a alternative to the ''j'' command in /X 4.xx\n\n  o At the moment i''m using 36 Conferences and I don''t want Users\n    to ''See'' Conferences where they don''t have Access to, like the Private\n    Conferences.\n\n  o SplitUp between the File and the NetMail Conferences (optional)\n\n  o Passwords Checking for Access to Private Conferences.\n    If a User fails to enter the right Conference Password it will be Logged\n    in DOORS:Doors.LOG and/or he/she will be Kicked-Off (optional)\n\n  o Cursor-Key control for Conference selecting.\n\n  o It''s possible to have more Conferences then there would fit on one screen.\n    Up to 256 Conferences are no possible.\n\n\n===============================================================================\n\n REQUIREMENTS:\n ~~~~~~~~~~~~~\n  Ami Express 4.xx\n  It Doesn''t work with Ami Express 1.1x or 2.xx!!\n\n\n===============================================================================\n\n INSTALLATION:\n ~~~~~~~~~~~~~\n  o Copy the EmP_Tools Directory to DOORS:\n  o Make sure ENV: exists! (standard with OS2.x+)\n  o Merge your NodeX/JoinConf.txt with my DOORS:EmP_Tools/JoinCnf.CFG and\n    Edit it to your Needs. (Check the Existing JoinCnf.CFG!)\n\n JoinCnf.CFG LayOut:\n\n##[ start: cut here ]#########################################################\nLOGFILE            Doors:Doors.LOG  ; Log File Name for Password Failures\nDUAL_LISTING       YES              ; Use 2 Listings [YES/NO]\nCURRENT_CNF        YES              ; Show Current Conferences [YES/NO]\nCNF_NAMES          NO               ; Use Names from ConfConfig.info Icon [/X 3.x]\nNRCONFLINES        11               ; Nr Lines used for Conferences\nPASSWORD_LEVEL     256              ; Password Protection Below Level\nNETMAIL_STARTCNF   24               ; First NetMail Conference Number\nDROP_DTR           3                ; Drop Carrier after 3 Password Failures\n[Init_END] ==============================.=====================================\nCNF_NAME.1 =.................... NEW USER\nCNF_NAME.2 =................. AMiGA UTiLS\nCNF_NAME.3 =............. AMiGA <OUTPOST>\nCNF_NAME.4 =.............. SNES <OUTPOST>\nCNF_NAME.5 =...... MEGADRiVE/MS <OUTPOST>\nCNF_NAME.6 =........... GAMEBOY <OUTPOST>\nCNF_NAME.7 =......... GAME GEAR <OUTPOST>\nCNF_NAME.8 =......... PC-ENGiNE <OUTPOST>\nCNF_NAME.9 =.............. LYNX <OUTPOST>\nCNF_NAME.10=........... NEO-GEO <OUTPOST>\nCNF_NAME.11=........... CONSOLE <OUTPOST>\nCNF_NAME.12=............... C64 <OUTPOST>\nCNF_NAME.13=..................... COPiERS\nCNF_NAME.14=.................... REQUESTS\nCNF_NAME.15=.................. /X SUPPORT\nCNF_NAME.16=.................... ROM BASE\nCNF_NAME.17=.............................\nCNF_NAME.18=.............................\nCNF_NAME.19=............. UniFIX BetaSITE\nCNF_NAME.20=......... /X-PoWeR! BeTa-ArEa\nCNF_NAME.21=............ MYSTiC <PRiVATE>\nCNF_PASS.21=NONOFYOURBUSINESS\nCNF_NAME.22=............ MYSTiC SCENETALK\nCNF_PASS.22=NONOFYOURBUSINESS\nCNF_NAME.23=............ MYSTiC /X-PoWeR!\nCNF_NAME.24=[AX0001]........ /X Net Admin\nCNF_NAME.25=[LS0001]....... C Programming\nCNF_NAME.26=[LS0002]..... ASM Programming\nCNF_NAME.27=[LS0003].... REXX Programming\nCNF_NAME.28=[PN0001].......... Pirate NET\nCNF_NAME.29=[HLT001]........... DuTCH NeT\nCNF_NAME.30=[ADV001]...... Adventure Help\nCNF_NAME.31=[PFT001]........ Amiga Topics\nCNF_NAME.32=[MOV001]........ Movie Topics\nCNF_NAME.33=[AA0001]......... ANSI Topics\nCNF_NAME.34=[WBS001].......... Buy & Sell\nCNF_NAME.35=[CHBX01].......... ChatterBox\nCNF_NAME.36=[CNS001]........ Console News\n[CNF_END]================================^====================================\n  [36m___/\  ___/\  ___/\  ___/\ ___/\  ___/\  ___/\  ___/\  ___/\  ___/\  ___/\\n  \[35m_ [36m. \ \_ . \ \_ . \ \  __\\  __\ \_ . \ \  __\ \_ . \ \  . \ \  __\ \  __\\n  [35m/  |__\/  |  \/  |  \/  ._l/  ._l_/  |__\/  ._l_/  |  \/  |__\/  ._l_/__.  \\n /   ¡   \  ¡   \  |   \  | /   ¡   \  .   \  ¡   \  |   \  ¡   \  ¡   \  ¡   \\n [34m\_____  /______/__¡_  /__¡ \_____  /__¡_  /____  /__¡_  /____  /____  /____  /\n-------\/------------\/-----------\/-----\/-----\/[Ð!]-\/-----\/-----\/-----\/-\n[TITLE_END]===================================================================\n[34m.--------[35m[  [36mFILE CONFERENCES  [35m][34m--------.-------[35m[  [36mNETMAIL CONFERENCES  [35m][34m------.\n|[38C|[38C|\n|[38C|[38C|\n|[38C|[38C|\n|[38C|[38C|\n|[38C|[38C|\n|[38C|[38C|\n|[38C|[38C|\n|[38C|[38C|\n|[38C|[38C|\n|[38C|[38C|\n|[38C|[38C|\n|[38C|[38C|\n|[38C|[38C|\n+--------------------------------------^--------------------------------------+\n[LINES_END]===================================================================\n[34m|[77C|\n`-----------------------------------------------------------------------------''\n[CURCNF_END]==================================================================\n##[ end: cut here ]###########################################################\n\n\n\n  - If ''CNF_NAMES'' is set to YES then the CNF_NAME.xx is taken from\n    the BBS:ConfConfig.info Icon [/X 3.x].\n    This makes the CNF_NAME.xx in JoinCnf.CFG obsolete.\n    It''s also possible to Mix this with the Names from JoinCnf.CFG, first\n    the Names from BBS:ConfConfig.info or s:Acp.Startup are read and then\n    the names from JoinCnf.CFG are written over the old ones.\n  - CNF_NAME.x can''t be longer the 80 Characters.\n  - CNF_PASS.x can''t be longer the 40 Characters.\n\n\n[Init_END] ====================================================================\nCNF_NAME.2 =........... AMiGA PUBLIC DOMAIN\nCNF_PASS.15=PASSWORD\nCNF_PASS.16=PASSWORD\nCNF_NAME.18=[AX0001]. /X Net Administration\nCNF_NAME.19=[LS0001]......... C Programming\nCNF_NAME.20=[LS0002]....... ASM Programming\nCNF_NAME.21=[LS0003]...... REXX Programming\nCNF_NAME.22=[PN0001]............ Pirate NET\nCNF_NAME.23=[HLT001]............. DuTCH NeT\nCNF_NAME.24=[PFT001].......... Amiga Topics\n[Cnf_END]=====================================================================\n\n\n  - If you don''t want to Use the ''PASSWORD_LEVEL'' Option then set is to a\n    value greater than 255, this way Everyone has to enter the Private \n    Conference Password.\n\n  - For now I expect that all Conferences above ''NETMAIL_STARTCNF'' are\n    NetMail Conferences so if this isn''t the case or you don''t want to use\n    the File/NetMail Splitup then set NETMAIL_STARTCNF to 0\n\n  - Set ''DROP_DTR'' to the number of Password-tries before the User is Kicked.\n    He/she will not be able to use JoinCnf until ENV:JC-PWFAIL.{SLotNr} has\n    been deleted (for example after a SystemReset).\n    Use ''0'' to disable this option.\n\n\n  AE 4.xx:\n  ~~~~~~~~\n  - Copy J.info,<.info & >.info to BBS:Commands/BBScmd/\n\n    Or add to J.info, <.info & >.info ICON ToolType Info:\n\n      ACCESS=001\n      LOCATION=DOORS:EmP_Tools/JoinCnf\n      MULTINODE=YES\n      PRIORITY=0\n      STACK=50000\n      TYPE=XIM\n\n  - If you want ''Relative Conferences'' then you add the following to\n    BBS:CONFCONFIG.INFO IconToolType Info: \n\n      RELATIVE_CONFERENCES\n\n\n===============================================================================\n\n USAGE:\n ~~~~~~\n  Just enter J, < or > on the MAIN screen in AmiExpress.\n\n  Selecting > x or < x  will make JoinCnf jump x Conferences Up or Down.\n\n===============================================================================\n\n ERROR MESSAGES:\n ~~~~~~~~~~~~~~~\n\n  o ERROR:  DOORS:EmP_Tools/JoinCnf.CFG Not Found !!!\n  |\n  `--> JoinCnf.CFG can''t be found in DOORS:EmP_Tools !?\n\n  o ERROR:  BBS:ConfConfig Not Found !!!\n  |\n  `--> BBS:ConfConfig can''t be found in BBS:\n\n  o ERROR:  JoinCnf 3.0 ONLY Works with /X 3.xx!!\n  |\n  `--> Obvious\n\n  o ERROR:  UnKnown Keyword: XXXXXXXX in JoinCnf.CFG\n  |\n  `--> There must be 8 different KeyWords in the INIT part (JoinCnf.CFG)\n       Compare this with the original JoinCnf.CFG\n       Check that the KeyWords are:\n\n         LOGFILE\n         DUAL_LISTINGS\n         CURRENT_CNF\n         CNF_NAMES\n         PASSWORD_LEVEL\n         NETMAIL_STARTCNF\n         DROP_DTR\n         CURSOR_KEYS\n\n  o ERROR:  CNF_NAME part of JoinCnf.CFG is NOT Valid!!\n  |\n  `--> Check that all CNF_NAME.xx are correct and that xx is a Valid Conf.\n       The Line has to start with CNF_NAME.xx=  (example: CNF_NAME.1 =)\n\n  o ERROR:  CNF_PASS part of JoinCnf.CFG is NOT Valid!!\n  |\n  `--> Check that all CNF_PASS.x are correct and that x is a Valid Conference.\n       The Line has to start with CNF_PASS.xx=  (example: CNF_PASS.1 =)\n\n  o ERROR:  BBS:Access/AREA.x Not Found!!\n  |\n  `--> An User got an ConferencesAccess (x) that doesn''t exist (anymore)!!\n\n  o ERROR:  ToolType NCONFS doesn''t Exist in BBS:ConfConfig.info!!\n  |\n  `--> Should/Will never happen... /X Wouldn''t have started!\n\n  o ERROR:  CNF_PASS.x in JoinCnf.CFG is LONGER then 40 Characters!!!\n  |\n  `--> Edit CNF_PASS.x password to a smaller one (< 40 Characters)!\n\n  o ERROR:  Only 256 Conferences are Supported for now!!!\n  |\n  `--> Contact EMPiRE and Blackmail/Bribe him in making a ''Bigger'' version.\n\n\n===============================================================================\n\n BUG REPORT & SUGGESTIONS:                                                                   \n ~~~~~~~~~~~~~~~~~~~~~~~~~\n  It''s possible that a mistake will occur.... Nobody is Perfect.\n  If you have any Suggestions or Comments Please Leave a Message on my Board:\n\n   LaSt OuTpOsT  N1: +31-72-157682  N2: +31-72-201182  -  HOLLAND\n   ~~~~~~~~~~~~  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~     ~~~~~~~\n   AmixNet:  @NL0004\n   /X-Fido:  44:100/102\n   UUCP   :  [email removed]\n\n===============================================================================\n\n NOTE:\n ~~~~~\n  o This Program Has been tested on a /X 3.x - /X 4.6TD (4.7) Configuration.\n  o If you don''t use Conference Passwords then the < and > references are\n    not necessary and can be left out if you want, because the internal\n    < and > are always a bit faster.\n  o The ScreenUpdating is not that fast but there is (for now) no faster\n    way to do this as it is done now! (or get a FASTER modem!)\n\n\n===============================================================================\n\n REGISTRATION:\n ~~~~~~~~~~~~~\n  If YOU use this Program please let me know by Calling Last Outpost or\n  to send me a Message by NetMail @NL0004 - EMPiRE  Coz I want to know\n  how many Sysops are using my Tools!!!\n \n\n===============================================================================\n\n HISTORY:\n ~~~~~~~~\n  V1.0  07-05-92 - Release Version\n\n  V1.1  07-15-92 - Improved Password Checking\n\n  V1.2  07-28-92 - The internal j(oin) command can be changed.\n                 - Relative Conferences: ConfAccess _______X_ -> j 1 !!!\n\n  V1.3  07-29-92 - Made ''Relative Conferences'' selectable. Default OFF\n                 - Improved Conference selection.\n\n  V1.4  08-03-92 - Default ''Relative Conferences'' is YES. As it''s now Default\n                   in /X 2.1 [1 Aug''92]\n                 - Moved ''Relative Conferences'' to the Config file\n                   [ JoinCnf.CFG CHANGED! ]\n                 - Bug Removed:\n                    o The Door Failed when e.g ''J 1abcd'' was entered.\n                    o Minor Bug removed in the Password Protection.\n\n  V1.5  08-23-92 - Changed the ColorLayout a bit.\n\n  V1.6  09-11-92 - Request Update for THC/DESiRE: 2 Conference Lists.\n                   [ JoinCnf.CFG CHANGED! ]\n\n  V1.7  10-21-92 - Small Improvements.\n\n  V1.8  01-23-93 - Small Improvements in the 2 Conference Lists.\n\n  V1.9  01-25-93 - Bug Report from JPS (Tnx!):\n                    o 1 Cnf List Failed, 1 Line of Code was Accidentally\n                      Killed from the Source.... \n\n  V1.10 02-22-93 - Changed Layout a bit\n\n  V2.ß  04-22-93 - /X 3.1 UPDATE!!! - It''s Still BETA coz I Just got /X 3.1\n                   2 Hours ago!\n        04-29-93 - Added < and > Support because of Password Protection\n        05-03-93 - Better Error Checking (''Fool'' Proof?!)\n        05-04-93 - Changed whole Config (JoinCnf.CFG) Layout!!\n                   [ JoinCnf.CFG CHANGED! ]\n                 - Added ''Current Confererence'' Option\n        05-06-93 - Bug Report from Aragorn/Vision (Tnx!):\n                    o Rexx claims that 2a,2b,.. exist between 1 to 20 (dec)\n\n  V2.0  05-09-93 - Release Version\n\n  V2.1  05-10-93 - Minor Update. The date in Doors.LOG file was wrong.\n        05-20-93 - Added ''Password Level'', this way the Sysop/CoSysop doesn''t\n                   need to enter a Conferences Password eachtime he Joins\n                   that Conference. (Thanx to Alcoholic for the Idea!!)\n                   [ JoinCnf.CFG CHANGED! ]\n        05-27-93 - Fixed the UpperCase Problem in JoinCnf.CFG and all used\n                   Icon Files [/X 3.x]\n\n  V2.2  06-18-93 - Updated the ''<'' & ''>'' code.\n        06-21-93 - Fixed a small Error found with the RexxDoorDebugger.\n        06-28-93 - Added the ErrorMessages in the doc.\n\n  V2.3  07-23-93 - Better Error handling\n\n  V3.ß1 08-10-93 - At last the XIM Version! Rexx is a thing of the Past!\n                 - Changed ALL References from AIM to XIM !!!\n                 - Keywords ''NRSPACES'', ''RELATIVE_CONFERENCE'', ''NCONFS'' are\n                   deleted from JoinCnf.CFG (Obsolete) because they are now\n                   ''read'' from the BBS:ConfConfig.info [/X 3.x] or\n                   s:ACP.Startup [/X 2.xx]\n                   [ JoinCnf.CFG CHANGED! ]\n\n  V3.ß2 08-13-93 - Keyword ''NRLINES'' is deleted from JoinCnf.CFG.\n                 - Keyword ''NETMAIL_STARTCNF'' added to JoinCnf.CFG\n                   If there are NetMail Conferences then the Conference\n                   showing can be split in 2 (Files & Netmail).\n                 - Renamed Keyword ''2_LISTINGS'' to ''DUAL_LISTING''\n                   [ JoinCnf.CFG CHANGED! ]\n                 - Included Optimized 030 Version!\n\n  V3.ß3 08-15-93 - Added the ''LOGFILE'' Option. Password Failures on Private\n                   Conferences will be logged in DOORS:Doors.LOG (default)\n                 - Added the ''CNF_NAMES'' Keyword (was ''CONFCONFIG_NAMES'')\n                   Now ConferenceNames from BBS:ConfConfig tooltype [/X 3.x]\n                   (or s:ACP.Startup [/X 2.xx]) and CNF_NAME.xx from\n                   JoinCnf.CFG can be Mixed in the Output.\n\n  V3.ß4 08-23-93 - Optimized the code and it''s now about 2 kb smaller\n                 - Bug Report from Beast (Tnx!):\n                    o JoinCnf failed completely when the OLD ''LOADCONFIG''\n                      option in ACP.Startup was used [/X 2.xx]\n                 - DEBUG OPTION: enter !% as Conference and you get some info\n                                 when all goes wrong.\n\n  V3.0  08-26-93 - Release Version.\n                 - All Debug routines removed.\n                 - Optimized 030 Version Included.\n\n  V3.1  09-04-93 - Bug Reports from ByteAndi/MST:\n                    o The Last conference couldn''t be joined when Not using\n                      ''RELATIVE_CONFERENCE'' (only happend in the Menu)\n        09-05-93 -  o Sometimes when only entering ''J'' a Conference would be\n                      joined. This is due to a BUG in /X... Fixed for now!\n        09-11-93 - Release Version.\n\n  V3.2  10-02-93 - /X 3.11 Update... AE Returned a different VersionNumber\n                   then in previous versions... this made JoinCnf think that\n                   it wasn''t /X 3.xx but /X 2.xx... FIXED!\n\n  V3.3ß 10-09-93 - Bug Report from ByteAndi/MST:\n                    o Conference Passwords bigger than 80 Chars would Halted\n                      the system! The maximum CNF_PASS size is now 40 Chars.\n                 - Updated some more code. Needs Lesser memory to run.\n                 - Better Error checking.\n        10-14-93 - Bug Report from Sal1/TRSI:\n                    o /X 2.xx & NOT using ''RELATIVE_CONFERENCE'' still failed.\n                      Should be fixed now!\n                 - When the KeyWord ''LOADCONFIG'' is used in the Acp.Startup\n                   [/X 2.xx] then the ''Current Conference'' Option will be\n                   Disabled! \n                 - Some more Code-Optimizing.\n\n  V3.3  12-01-93 - Release Version\n                 - Included an Optimized 020 Version for A1200/A4000 Users.\n                 - Just replace the Old JoinCnf with the New One!\n\n  V3.4ß 01-16-93 - Bug Report from Sal1/TRSI:\n                    o When Using /X 3.20+ & ''NETMAIL_STARTCNF  0'' & Not Using\n                      ''RELATIVE_CONFERENCE'' the Conferences were not shown.\n                 - Added ''DROP_DTR'' option, it Drops the Carrier of the\n                   User after he/she fails to enter the Right Password for\n                   a number of times. After this he/she won''t be able to use\n                   JoinCnf until the file ENV:JC_PWFAIL.{SlotNr} doesn''t exist\n                   anymore (for example after a systemreset). When he tries\n                   he will be Kicked-Off right away!\n        01-17-94 - Bug Report from Mike Hoffren:\n                    o Using 108 Conferences will Crash the System!\n                      In the past it was ''Only'' possible to use 100 Confs,\n                      I never thought there would be more than that!\n                      It''s been Fixed to 256 Conferences for now\n                 - When JoinCnf is run, it will ShowUp on the Server.\n        01-21-94 - Change the Command-Line a bit.\n                 - JoinCnf will now make Use of the full 80 Chars/Line, this\n                   means that LayOut of JoinCnf.CFG Changed a bit!\n                   [ JoinCnf.CFG CHANGED! ]\n        01-25-94 - Fixed the ''10-Node'' BUG. Using Node 10+ would result in\n                   JoinCnf thinking it was started from Node 1.... FIXED!\n\n  V3.4  01-29-94 - Release Version.\n\n  V3.5ß 02-01-94 - Change the ''Full Use of 80 Chars/Line'' to 79 Chars/Line\n                   because some Terminals on Amiga/PC can''t handle the 80th\n                   character on the right (extra linefeeds)!\n                   [ JoinCnf.CFG CHANGED! ]\n                 - Took out all 100+ Conferencing coz /X-Fido is on it''s way\n                   now (so no need for 100+ Conferences) and otherwise the\n                   Code becomes too big! A 100+ Version Can be REQUESTED!\n        02-06-94 - Changed the CommandLine-Input so only Numbers can be\n                   selected.\n                 - Added some BETA-Code to use the Cursor-Keys to select a\n                   Conference. The only BIG problem exists when there are too\n                   many Conferences and the Screen starts scrolling....\n        02-09-94 - Updated the Cursor-Key Code so it''s now possible to Use\n                   Cursor-Keys only if the JoinCnf output-screen fits in the\n                   Users terminalscreen (without scrolling). If it doesn''t\n                   ''fit'' then the Cursor-Keys are disabled otherwise it would\n                   mess up the screen!\n                 - Added the ''CURSOR_KEYS'' KeyWord, when it''s ''NO'' then there\n                   will never be made use of ANSI when using the Cursors.\n                   When the KeyWord is ''YES'' or is leftout then ANSI is used\n                   when the JoinCnf-Screen ''fits'' in the Users TerminalScreen.\n                   [ JoinCnf.CFG CHANGED! ]\n                 - Note: For now the Cursor-Code works only with Relative\n                         Conferences.\n        02-16-94 - Fixed a Small Bug in the Password Handling.\n        02-20-94 - Fixed the Non-Relative Conferences problems so now it will\n                   work on ANY /X 2.xx or 3.xx configuration.\n        02-21-94 - Fixed a Bug in printing the Command-Line to Screen. It\n                   failed when there where Non-Even FileConfs & NetMailConfs.\n                 - Changed the Cursor-Handling. The ''jump'' from FileConf to \n                   NetMailConf has been changed.\n        03-08-94 - Optimized the Cursor-Key Routine.\n\n  V3.5  03-13-94 - Release Version.\n\n  V3.6ß 04-11-94 - Added the ''Q'' to the CommandLine on Tycoon''s Request:\n                    o Pressing ''Q'' will now Exit JoinCnf Immediately, even\n                      when a Conference is selected.\n        04-14-94 - Killed all sscanf''s in the Source coz of Bugs in the\n                   SAS Compiler and this way JoinCnf gets 2 kb smaller!\n        04-17-94 - After a long talk with ByteMaster I managed to kill some\n                   obsolete code, this will make JoinCnf startup Faster!\n                 - Added an New CommandLine Option: \n                    ''> 4''  will Join: Current Conference + 4 (if it Exists)\n                    ''< 9''  will Join: Current Conference - 9 (if it Exists)\n                    ''< -2'' will Join: Current Conference + 2 (if it Exists)\n                 - ReCompiled with the Latest AE.Includes\n        06-28-94 - Fixed some code that can cause random guru''s (SAS C Bug!)\n                 - Removed ALL /X 2.xx support because of the new AE.Includes\n                   JoinCnf won''t work on any /X version before /X 3.38, if\n                   you still have not upgraded then this is the time to do so!\n\n  V3.6  07-01-94 - Release Version.\n\n  V4.0ß 09-20-94 - Changed the Total layout of JC\n                 - The maximum of used conferences has been changed from 100\n                   to 256 (Should be MORE than enough.. if not TELL me!)\n                   [ JoinCnf.CFG CHANGED! ]\n        10-01-94 - Removed the Hide Cursor ansi ("[0 p") coz some terminals\n                   can''t handle this and will print nice p''s thru the screen.\n                 - Added Single Conference Layout.\n        10-04-94 - Fixed a bug that not all Conferences could be selected.\n                   tried to read the PageUp/Down (without luck...)\n                 - Fixed the NonRelativeConference Bug (as usually i am slow\n                   on this... for obvious reasons). [Sal-One]\n                 - Added the ''NRCONFLINES'' KeyWord, this is the number of\n                   conferences which will be printed on the screen.\n                   (Keep in mind that you must also edit the border in\n                   JoinCnf.CFG)\n                   [ JoinCnf.CFG CHANGED! ]\n        11-27-94 - The ScreenUpdating is now faster by only rewritting 1\n                   Conference list at the time.\n                 - Removed the Beta-Code\n\n  V4.0  02-01-95 - Release Version\n\n\n===============================================================================\n\n EMPiRE /X DOORS/UTILS COLLECTION UNTIL NOW!:\n ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n  - AboStats V0.2                        AIM Door\n  - AE2PCE V1.0                          CLI Util\n  - AutoOnline V1.3                      XIM Door/Util\n  - Bulls V2.3                           XIM Door\n  - CheckDir V1.0                        CLI Util\n  - CheckNU V1.0                         XIM Door\n  - ConfAccess V1.1                      ServerUtil\n  - CopyDate V1.3                        CLI Util\n  - DlDir V2.2                           XIM Door\n  - DoorKIT 1.01                         XIM Doors/Includes\n  - DMenu V1.0                           AIM Door\n  - DutchNET V1.0  [AmiXnet]             AIM Door\n  - Front V2.0                           XIM Door\n  - JoinCnf V4.0                         XIM Door\n  - LastCalls & TopUps V1.2              LogOffUtil\n  - LastDL V0.1                          LogOffUtil\n  - LastUL V0.1                          LogOffUtil\n  - MakeFree V1.1                        AIM Door\n  - MemberList V1.0                      AIM Door\n  - MonthTopUp V2.0                      ServerUtil\n  - MultiNodeLastCaller V1.1             LogOffUtil\n  - Page V2.1                            XIM Door\n  - PMail V1.1                           AIM Door\n  - Remote Maintenance V1.4              AIM Door\n  - SceneTalk Voter V2.3                 AIM Door\n  - SceneTalk Voter V2.2 [Party]         CLI Door\n  - SecLevChk V1.0                       ServerUtil\n  - Sent FrondEnd 1.0  [Sent_FE]         XIM Door\n  - StripCR V1.0                         CLI Util\n  - SysopCommands V1.0                   AIM Door\n  - UserData Cleaner/Repair V2.0         ServerUtil\n  - UserStats V2.0                       ServerUtil\n  - UsrCnfAx V1.1                        CLI Util\n  - View & Check Archive/Text V1.7       AIM Door\n  - WhoNode V1.3                         AIM Door\n\n\n===============================================================================\n\n THANX MUST GO TO ALL OFFICIAL BETA-TESTERS:\n ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n   Sal-One/TRSi              [BoonDocks]\n   Beast/Partek              [Sequencial]\n   SpeedDevil/Partek         [Rising Sun]\n   Galaxy                    [Ulixys]\n\n\n GREETZ/TNX GO TO:\n ~~~~~~~~~~~~~~~~~\n   Killraven/MST /X-PoWeR! - For giving me sum Great Pointers/Sources on ''C''\n   Tycoon/Mystic /X-PoWeR! - another EX-/X programmer...\n   ByteAndi/TRSI           - Tnx for all ya ''C'' Help & Sources!\n   Easy Rider/Mystic       - hope ya are back soon!\n   JAF/G.O.D.              - For some good REXX ideas\n   JPS                     - I think /X is still better!\n   Bad Sector/Hidden       - Still Using your Sort-Routine. It''s the Fastest!\n   B.O.B./CyberForce       - For (Mis)Using/Testing my tools! :)\n   Aragorn/Vision          - Tnx for Testing\n   Camelot/Complex         - Tnx for Testing\n   Sharon/5D               - Tnx for Testing\n   Telekinetic/T.F.A.      - Tnx for Testing\n   Alcoholic               - Tnx for Testing\n   Price/T.F.A.            - Great job on your {F}ull {S}creen {E}ditor!\n   Van Damme               - Nice Doors!!!\n   DR.G/IBB                - Hope to see Check''N Add work on a 040\n   SiGMA SEVEN             - Nice job on SiGMA-EXPRESS! Tempted to ''Convert''\n   911/Movement            - Tnx For ya Ansi Logo''s!! You''re the Greatest!\n   Mike                    - Tnx for calling!\n   Amicom/TRSi             - Tnx for calling!\n   THC/Legend              - Tnx for Beta-Testing!\n   Mega Fortress           - Tnx for Beta-Testing!\n   SkIn                    - Tnx for ya Description Logo! Looks Great!!\n   Shadow Man/S8           - Nice Doors & Tnx for ya greetz! & Calling ofcoz\n   [MAZ!^PHAZE]            - Tnx for calling!\n   Shuyuki Tanaka          - Tnx for your Messages!\n   AGONY/cOmpLeX           - Tnx for calling!\n   HUMANOiD & jABBA /MST & SCANDAL\n                           - Tnx for calling!\n   LECTOR                  - Tnx for your NetMail\n   Koo Koo Ka Choo         - Tnx for calling!\n   TaRzAN                  - Tnx for your NetMail. Yezz 040 Speed Rulez!!\n   Crayor/Scx              - Tnx for calling!\n   Foxx''n''Lynxx            - Tnx for your BugReports!!!\n   ThE BiRD                - Tnx for your NetMail on UsrCnfAx\n   Dux                     - Tnx for your NetMail\n   dR.dRE!/fAITH           - Tnx for da greetz, Nice Doors btw\n   [-RUNT&SCOTTIE-]        - Tnx for calling!\n   sPAcEcAKe/aF            - Tnx for calling!\n   Freddy Kreuger/GOD      - Tnx for your NetMail on JoinCnf 3.2\n   MF1                     - Tnx for calling!\n   AtomiX/N.A.S.A          - Hope the ''C'' archive was sume help for ya!\n   MAD HARLEQUiN [ITPH01]  - Tnx for your Nice AmiXnet Messy''s\n   Mike Hoffren  [SF0001]  - Tnx for the BugReport on JoinCnf 3.3 [100+ Cnfs]\n   Galaxy/TFA              - Nice job on da SentCleaner\n   SvEN tHE CREAToR/5D     - ''Tnx'' for forcing me to use Cursor-Keys!\n   Diogenes/TPY/5D         - Tnx for calling and for your BugReport!\n   L.A.Style               - Tnx For Calling/Beta-Testing!\n\n   & Ofcoz to ALL MYSTiC Members all over the Globe!\n\n\n NO TNX GO TO:\n ~~~~~~~~~~~~~\n   Vampire/TRSI  for being a BIG asshole by spreading our BETA''s.. LAME...\n\n\n                        ______  __________________                            \n.----------------+-----/    \ \/ / __/_  __/ / __/----------+----------------.\n|                |----/ / / /\  /\  /-/ /-/ / /----[ /X ]---|                |\n|       /\    /\ |-EmP\/ / /-/ /\  /-/ /-/ /\ \--[ PoWeR! ]-|       /\    /\ |\n|      /C \  /!/ +-----\/\/--\/--\/--\/--\/--\/-------------+      /C \  /!/ |\n|     /i/\ \/R/  |                                          |     /i/\ \/R/  |\n|    /T/  \ E/   |   EMPiRE   -   KiLLRAVEN  -   TYCOON     |    /T/  \ E/   |\n|   /S/   /W \   |                                          |   /S/   /W \   |\n|  /Y/   /O/\ \  |   RE/Y\o   -   INCOGNiTO  -   HARDBYTE   |  /Y/   /O/\ \  |\n| /M/   /P/  \ \ |                                          | /M/   /P/  \ \ |\n| \/    \/    \/ |                   BoBo                   | \/    \/    \/ |\n|                |                                          |                |\n`----------------+----------[  MYSTiC /X PoWeR!  ]----------+----------------''\n\n\n \n\n                       ____ _________ _________ ________ _____\n            MYSTiC    /   / \\  /    \\\  /   _\\\  /   \\\  /     MYSTiC\n                     /   /   \\/   /\ \\\/   /___\\/__   \\\/\n         CONSOLE    /   / /\  /   __   \ \____   \   /   /      AMIGA\n                   /   /_/  \/   / /   /_____/   /  /   /\n       WORLD-HQ    \________X___/ /___/\________/   \__/      EURO-HQ\n      ____ _________ ________ _________ _________ _________ ________ _____\n     /    \\\  /   / \\  /   \\\  /    \\\  /    \\\  /   _\\\  /   \\\  /\n    /   /\ \\\/   / /\\\/__   \\\/   /\ \\\/   /\ \\\/   /___\\/__   \\