INSERT INTO door_catalog VALUES('jrm_stat','JRM-STAT.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/JRM-STAT.LHA',NULL,'XIM','._________________  <e>  ______  _______',NULL,'Poksahtaja','JRM','THE |   _____ \_____  \/\  /\\____ \/  ____/ |___|   |/  |  \_ _|  /  \/  \/ _|  \___  \| \   |   |   |   / \_  \_ \/   \_\_   \_|   \',replace('    ._________________  <e>  ______  _______\nTHE |   _____ \_____  \/\  /\\____ \/  ____/\n|___|   |/  |  \_ _|  /  \/  \/ _|  \___  \|\n\   |   |   |   / \_  \_ \/   \_\_   \_|   \\n|\______|\_____/___|___/_/_____/_|____/____/\n`--------------p-r-e-s-e-n-t-s-------------''\nJormaStats v0.1 for /X - Coded by Poksahtaja\nCODED WITH PURE JENKKI FOR MAXIMUM VELOCITY!\n--------------------------------------------\n','\n',char(10)),'JRm-stAT.guide',replace('@database JormaStatus\n@remark $VER: JRm-stAT.guide v0.1 (05.06.94)\n@node MAIN\n@title "JormaStatus Doku-mentti"\n \n  _¦_  ¦_ _¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦  _¦_¦_ _\n    _ _¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_ _ _¦\n ¦_¦_ _¦ ¦ ¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦ ¦_¦_¦_¦_¦_¦_¦_\n  _¦_¦/¯¯¯¬\_¦_¦_¦_¦ ¦ ¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦ ¦_¦ ¦ ¦ ¦/¯¯¬\¦_¦ZMb¦_¦ ¦_¦\n ¦_¦_\_     \¦ ¦ ¦ /¯¯¬\_¦_¦_¦_¦ ¦ ¦_¦ ¦ ¦_¦/¯¯¬\¯¯¯¯¯¯¯     \_¦_¦_¦/¯¯¬\¦\n ¦ ¦ ¦/    __/¯¯¯¯¯     \¦ ¦ ¦ /¯¯¬\/¯¯¯¬\_/     \_   |     __/ ___      \_\n_/¯¯¯¬\_   ¬\    _    ___/¯¯¯¯¯     \_   _  _  ___/   _      \____¬\______/\n\            \   |     ¬\    |    ___/   ¬\/    ¬\____/       \  ¬\     ¬\\n \___________/_____      \   _     (______/       \¦_¦\_______/_____      \\n ¦_¦_¦_¦_¦_¦_¦_¦_\_______/___/      ¬\_¦_¦\_______/¦_¦_¦_¦_¦_¦_¦_¦\_______/\n ¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_\_______/_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦\n ¦ ¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_ _¦\n  _¦_ _¦_ _ _¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_ _¦_ _¦_\n   ¦ ¦  _¦_ _¦_ _¦ ¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦ ¦_ _¦ ¦_  ¦_\n \n=¦===============[ User Stats v0.1ß © Poksahtaja / Jormas ]==============¦=\n \n                               INCREMENTS:\n                               ¯¯¯¯¯¯¯¯¯¯¯\n                           @{" [ tRACkmodUCtioN ] " link TRACKMO}\n                           @{" [  CredIToSSSSS  ] " link CREDITS}\n                           @{" [  JRm-stAT.LhA  ] " link SISUSTUS}\n                           @{" [ iKSÄMpL oUtPUt ] " link EXAMPLE}\n                           @{" [ HOW TO INSTALL ] " link INSTALL}\n                           @{" [HOW TO REACH ME?] " link CONTACT}\n                           @{" [ AlL ThE BUGS.. ] " link BUGS}\n                           @{" [ lOok 2 fUtuRE! ] " link FUTURE}\n\n@endnode\n@node TRACKMO "JormaStatus Doku-mentti - tRACkmodUCtioN"\n                                    HEI!\n                                    ¯¯¯¯\n          Should I tell ya why did I do the 38475938th status door\n                         for Ami-Express IN AREXX?!\n \n         Well.. here comes the excuse. It was a dark and stormy day\n      when I noticed that my old and cool status door had disappeared\n       from the Doors: directory. Oh.. it was horrible. I was in love\n      with that statusdoor. It was sooo beautiful with animations and\n                                everything.\n \n       What to do?.. I was in panic ofcourse and cried and shouted..\n     But then I noticed that it didn''t help a bit. Had to do something\n            aaaaaaaaannd heeeeeereeeeee iiiissssss the RESULT!!!\n \n                           JormaStatus-door v0.1!\n \n          Nothing more than an usual statusdoor made with arexx.. \n       and NOTHING LESS either.  I think it has quite a k00l design!\n@endnode\n@node CREDITS "JormaStatus Doku-mentti - the maker(s) of this door."\n \n          Changes to the original Arexx-script done by Poksahtaja.\n \n         Thanks to the maker of the original door. I''m not telling\n           ya who it is but maybe you recognize maybe you don''t.\n \n         Anyway, the d-zign is changed completely and some features\n         are changed also. The code is almost completely rewritten.\n@endnode\n@node SISUSTUS "JormaStatus Doku-mentti - contents of da paku."\n \nDH7:BBS/Node125/Elitewarez:> lha v JRm-stAT.LhA\nLhA V1.50r - Copyright (c) 1991,92 Stefan Boberg. Not for commercial use.\nRegistered to motherfuckers\n \nListing of archive ''JRm-stAT.LhA'':\nOriginal  Packed Ratio    Date     Time    Name\n-------- ------- ----- --------- --------  -------------\n     570     325 42.9% 07-Jun-94 16:17:10  BBS/Commands/BBSCmd/s.info\n    7572    1818 75.8% 07-Jun-94 16:13:54  BBS/Doors/JormaS/JRm-stAT.REXX\n    9467    3121 67.0% 07-Jun-94 16:37:52  Docs/JRm-stAT.dOC\n   10273    3479 66.1% 07-Jun-94 16:38:30  Docs/JRm-stAT.guide\n     405     209 48.3% 07-Jun-94 16:35:42  file_id.diz\n     694     241 65.2% 07-Jun-94 16:30:26  LL.DiSPLAYME\n    2574     527 79.5% 07-Jun-94 16:19:00  Output/Output.ansi\n    1680     466 72.2% 07-Jun-94 16:17:38  Output/Output.ascii\n-------- ------- ----- --------- --------\n   33459   10248 69.3% 07-Jun-94 16:39:08   8 files\n \nOperation successful.\n \nAnd here is the description!\n \n    ._________________  <e>  ______  _______\nTHE |   _____ \_____  \/\  /\\____ \/  ____/\n|___|   |/  |  \_ _|  /  \/  \/ _|  \___  \|\n\   |   |   |   / \_  \_ \/   \_\_   \_|   \\n|\______|\_____/___|___/_/_____/_|____/____/\n`--------------p-r-e-s-e-n-t-s-------------''\nJormaStats v0.1 for /X - Coded by Poksahtaja\nCODED WITH PURE JENKKI FOR MAXIMUM VELOCITY!\n--------------------------------------------\n \n@endnode\n@node INSTALL "JormaStatus Doku-mentti - installatiducktales"\n \n            No lamer can install this fine piece of arexx-code.\n@endnode\n@node EXAMPLE "JormaStatus Doku-mentti - iksämpl"\n              Here is a nice example of the output eli uloste:\n \n===========================================================================\n                      Status of Uloste from ISDN node                      \n======================================·====================================\n    User Slot Number [     1     ]    ¦    Access Level   [    255    ]    \n    Number of calls  [   1285    ]    ¦    Access Area    [   SYSoP   ]    \n    Messages posted  [    43     ]    ¦    Minutes left   [    975    ]    \n======================================¦====================================\n    Uploaded Files   [   23552   ]    ¦    Leeched files  [    324    ]    \n    Uploaded Bytes  [  98345345   ]   ¦    Leeched Bytes [  29538532   ]   \n======================================¦====================================\n    Ratio           [  DISABLED!  ]   ¦    With this ratio you can leech   \n    Ratio type      [ ONLY BYTES! ]   ¦    [  AS MUCH AS YOU WANT !!!  ]   \n======================================¦====================================\n    You are on node  [     0     ]    ¦    Speed          [   19200   ]    \n======================================¦====================================\n        Name of the conference        ¦          Name of the board         \n    [     mAJORS & pREVIEWS!      ]   ¦    [         LamERlAnd         ]   \n======================================·====================================\n                   User Stats v0.1 © Poksahtaja / Jormas                   \n===========================================================================\n \n   (Cutted version. Take a look in the OUTPUT directory in this packetti)\n \n  I''m not sure but I think that the ''With this ratio you can leech''-thing\n                  is something new in these status-doors.\n    As this is the first (ßeta-) release I can''t guarantee that it works\n                                 perfectly.\n          Fuck! It isn''t anything new at all BUT WHO REALLY CARES.\n \n@endnode\n@node CONTACT "JormaStatus Doku-mentti - how to hauhau"\n  \n=¦=======================================================================¦=\n \n         If you have any comments or suggestions, you can reach me\n       from the new Jormas Distribootion Site - S I N E S T U D I O !\n \n       .         .                  .                    .         .\n        .   ·  o    ·  .  ·  o  · .   ·  . ° o  · . o  ·  .  ·  .     .\n     ·   /\__.__/\·__/\.·_____._______________/\°·____° ·__/\o·/\__ .\n      . /^ ___\__//^   \/^    /^ ___       / /^ \|^   \· \__/./^   \  ·\n       _\__  \/^ \   __ \ ____\__  \__\ \_/  \   \  l  \./^ \/   l  \\n       \      \   \   / /  _/\      \·/  \\      /      \    \      /\n     ·  \  ___/___/  /\/\_____\_____//___/.\____/l______/____/\__  / ·\n   - ----\/--------\/--------------------------------------------\/---- -\n \n   [ +358-41-3110417 ] [A1200] [Modules/Anims/Jormas] [AmiX-Net] [+MORE!]\n \n=¦=======================================================================¦=\n \n \n \n You can also try to reach me from the Jormas WHQ but bcoz it''s so PRIVATE\n           ELITE & K00L it may be quite impossible mission 2015.\n \n_/\  ___/\ _:   ___/\ ____ ___/\ _:   ___/\ ________/\ ____\n ts\\\__  \¬l___\__  \__ ¬\\__  \¬l___\__ _\________  \__ ¬\  [ThE JORmAS]\n      /     |  ¬\/   __l_  \/     |  ¬\/  _____)__/    _l   \  [World HQ]\n    _/      |    \_  \___   \_  \___/  \_  l     ¬\_   _____/\n   /        |     ¬\   l     ¬\   l     ¬\ |       ¬\   l   ¬\\n   \        |      /   |      /   |      / |        /   |     \  /\\n    \________     /____|     /____|     /___       /____|     ///  \_______\n           \_____/     l____/     l____/  \_______/     l____/\n LAmeRlAnd!            :          :                     :     Sys: NaX!/JRM\n____________________/\  ___/\ _:   ___/\ ____ ___/\ ____ ___/\ ____\n                      \\\__  \¬l___\__  \__ ¬\\__  \___¬\\__  \___¬\\n  68XXX hARdCoREPoWER    /     |  ¬\/   __l_  \/      l  \/      l  \\n     200+bpm oNlY!     _/      |    \_  \___   \_     |   \_     |   \_\n                      /        |     ¬\   l     ¬\    |    ¬\   _l    ¬\\n MothAPhUKkeN F·A·S·T \  