INSERT INTO door_catalog VALUES('jrm_who_','JRM-WHO!.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/JRM-WHO!.LHA',NULL,'XIM','___ _____ _____ _____ _____ ______',NULL,'Poksahtaja','JRM','nAX! |  Y  _  Y  _  Y _ _ Y  _  Y  _  | .__¦  |  ¦  |  ¦  |  Y  |  ¦  |  ¦__|. .::) |  |  |  |  _ (_  |  |  _  |__   (::.',replace('      ___ _____ _____ _____ _____ ______    \n nAX! |  Y  _  Y  _  Y _ _ Y  _  Y  _  |    \n   .__¦  |  ¦  |  ¦  |  Y  |  ¦  |  ¦__|.   \n .::) |  |  |  |  _ (_  |  |  _  |__   (::. \n:::/  ¦  |  ¦  |  ¦  |  ¦  |  ¦  |  ¦   \:::\n::(______|_____|__|__|__|__|__|__|_______)::\n`--p--r--e--s--e--n--t--s---t--o--d--a--y--''\nJormaS-Who v0.1 for /X - Coded by Poksahtaja\nRule-door for 1 node BBSes! Zekitout! WORKS!\n--------------------------------------------\n','\n',char(10)),'JRm-Who!.guide',replace('@database JormaS-Who\n@remark $VER: JRm-Who!.guide v0.1 (10.06.94)\n@node MAIN\n@title "JormaS-Who"\n \n=¦=============================[ The JormaS ]============================¦=\n      _ _     _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _     _   _ \n  _¦_  ¦_ _¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦  _¦_¦_ _\n    _ _¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_ _ _¦\n ¦_¦_ _¦ ¦ ¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦ ¦_¦_¦_¦_¦_¦_¦_\n  _¦_¦/¯¯¯¬\_¦_¦_¦_¦ ¦ ¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦ ¦_¦ ¦ ¦ ¦/¯¯¬\¦_¦ZMb¦_¦ ¦_¦\n ¦_¦_\_     \¦ ¦ ¦ /¯¯¬\_¦_¦_¦_¦ ¦ ¦_¦ ¦ ¦_¦/¯¯¬\¯¯¯¯¯¯¯     \_¦_¦_¦/¯¯¬\¦\n ¦ ¦ ¦/    __/¯¯¯¯¯     \¦ ¦ ¦ /¯¯¬\/¯¯¯¬\_/     \_   |     __/ ___      \_ \n_/¯¯¯¬\_   ¬\    _    ___/¯¯¯¯¯     \_   _  _  ___/   _      \____¬\______/ \n\            \   |     ¬\    |    ___/   ¬\/    ¬\____/       \  ¬\     ¬\\n \___________/_____      \   _     (______/       \¦_¦\_______/_____      \\n ¦_¦_¦_¦_¦_¦_¦_¦_\_______/___/      ¬\_¦_¦\_______/¦_¦_¦_¦_¦_¦_¦_¦\_______/\n ¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_\_______/_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦\n ¦ ¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_ _¦\n  _¦_ _¦_ _ _¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_ _¦_ _¦_\n   ¦ ¦  _¦_ _¦_ _¦ ¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦_¦ ¦_ _¦ ¦_  ¦_\n \n=¦==================[ Jormas Who © Poksahtaja / Jormas ]=================¦=\n \n \n \n \n                               INCREMENTS:\n                               ¯¯¯¯¯¯¯¯¯¯¯\n                           @{" [  iNtRodUCtioN  ] " link TRACKMO}\n                           @{" [    CrediTSs    ] " link CREDITS}\n                           @{" [  JRm-Who!.LhA  ] " link SISUSTUS}\n                           @{" [ HOW TO INSTALL ] " link INSTALL}\n                           @{" [HOW TO REACH ME?] " link CONTACT}\n\n@endnode\n@node TRACKMO "JormaS-Who"\n \n \n \n \n \n                                    fAK!\n                                    ¯¯¯¯\n        Here we are again. This is a · RULE · door for 1 node BBSes!\n               It ''emulates'' the built in who of amiexpress,\n                  shows the user in node 1 (OR in node 0),\n              adds 3 other nodes, the users and their actions.\n \n                  You can configure the users by yourself,\n              and it''s not too hard to add more nodes either!\n                  Just examine and change the arexx-code!\n \n                         This time this even works!\n@endnode\n@node CREDITS "JormaS-Who"\n \n \n \n \n \n                                  kREditS:\n                                  ¯¯¯¯¯¯¯¯\n         If I remember correctly, this isn''t a ripped code at all.\n                       Everything made by Poksahtaja!\n@endnode\n@node SISUSTUS "JormaS-Who"\n \n \n \n \n \n                                 The packet\n                                 ¯¯¯¯¯¯¯¯¯¯ \nDH9:BBS/Node251/Elitewarez:> lha v JRm-Who!.LhA\nLhA V1.50r - Copyright (c) 1991,92 Stefan Boberg. Not for commercial use.\nRegistered to motherfuckers\n \nListing of archive ''JRm-Who!.LhA'':\n   Date     Time    Name\n--------- --------  -------------\n11-Jun-94 15:00:01  BBS/Commands/BBSCmd/Who.info\n11-Jun-94 15:00:02  BBS/Doors/JormaS/JRm-Who.REal\n11-Jun-94 15:00:03  BBS/Doors/JormaS/JRm-Who.fAkE\n11-Jun-94 15:00:04  Docs/JRm-Who!.dOC\n11-Jun-94 15:00:05  Docs/JRm-Who!.guide\n11-Jun-94 15:00:06  file_id.diz\n--------- --------\n11-Jun-94 15:00:07  6 files\n \nOperation successful.\n \nAnd here is the description!\n \n      ___ _____ _____ _____ _____ ______\n nAX! |  Y  _  Y  _  Y _ _ Y  _  Y  _  |\n   .__¦  |  ¦  |  ¦  |  Y  |  ¦  |  ¦__|.\n .::) |  |  |  |  _ (_  |  |  _  |__   (::.\n:::/  ¦  |  ¦  |  ¦  |  ¦  |  ¦  |  ¦   \:::\n::(______|_____|__|__|__|__|__|__|_______)::\n`--p--r--e--s--e--n--t--s---t--o--d--a--y--''\nJormaS-Who v0.1 for /X - Coded by Poksahtaja\nRULE-door for 1 node BBSes! Zekitout! WORKS!\n--------------------------------------------\n@endnode\n@node INSTALL "JormaS-Who"\n \n \n \n \n \n                               How to install\n                               ¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n            No lamer can install this fine piece of arexx-code.\n@endnode\n@node CONTACT "JormaS-Who"\n  \n=¦=======================================================================¦=\n \n         If you have any comments or suggestions, you can reach me\n       from the new Jormas Distribootion Site - S I N E S T U D I O !\n \n       .         .                  .                    .         .\n        .   ·  o    ·  .  ·  o  · .   ·  . ° o  · . o  ·  .  ·  .     .\n     ·   /\__.__/\·__/\.·_____._______________/\°·____° ·__/\o·/\__ .\n      . /^ ___\__//^   \/^    /^ ___       / /^ \|^   \· \__/./^   \  ·\n       _\__  \/^ \   __ \ ____\__  \__\ \_/  \   \  l  \./^ \/   l  \\n       \      \   \   / /  _/\      \·/  \\      /      \    \      /\n     ·  \  ___/___/  /\/\_____\_____//___/.\____/l______/____/\__  / ·\n   - ----\/--------\/--------------------------------------------\/---- -\n \n   [ +358-41-3110417 ] [A1200] [Modules/Anims/Jormas] [AmiX-Net] [+MORE!]\n \n=¦=======================================================================¦=\n \n \n \n You can also try to reach me from the Jormas WHQ but bcoz it''s so PRIVATE\n           ELITE & K00L it may be quite impossible mission 2015.\n \n_/\  ___/\ _:   ___/\ ____ ___/\ _:   ___/\ ________/\ ____\n ts\\\__  \¬l___\__  \__ ¬\\__  \¬l___\__ _\________  \__ ¬\  [ThE JORmAS]\n      /     |  ¬\/   __l_  \/     |  ¬\/  _____)__/    _l   \  [World HQ]\n    _/      |    \_  \___   \_  \___/  \_  l     ¬\_   _____/\n   /        |     ¬\   l     ¬\   l     ¬\ |       ¬\   l   ¬\\n   \        |      /   |      /   |      / |        /   |     \  /\\n    \________     /____|     /____|     /___       /____|     ///  \_______\n           \_____/     l____/     l____/  \_______/     l____/\n LAmeRlAnd!            :          :                     :     Sys: NaX!/JRM\n____________________/\  ___/\ _:   ___/\ ____ ___/\ ____ ___/\ ____\n                      \\\__  \¬l___\__  \__ ¬\\__  \___¬\\__  \___¬\\n  68XXX hARdCoREPoWER    /     |  ¬\/   __l_  \/      l  \/      l  \\n     200+bpm oNlY!     _/      |    \_  \___   \_     |   \_     |   \_\n                      /        |     ¬\   l     ¬\    |    ¬\   _l    ¬\\n MothAPhUKkeN F·A·S·T \        |      /   |      /    |     /    ~     / /\\nAnd UNlimiTEd EXCREMENT\________     /____|     /_____|    /______    ///  \n        sUPpoRt!              \_____/     l____/      l___/     \____/\n                                          :           :\n@endnode\n','\n',char(10)),NULL,NULL,10484,2,0,NULL,NULL,NULL,'scan',1780048560);
INSERT INTO door_catalog VALUES('jso_id10','JSO-ID10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/JSO-ID10.LHA','DMSDescript','XIM','DMSDescript','1.0',NULL,'JSO','._ ._____ ___ __   __ ______ ___ _____ ____. .__|    / ._____ )\____._____ _____ ______ | |  |   ///____  X    __.___  X     X      \|',replace('[- Json -]   [ IDClean v1.0ß ]  [ /X v3.xx ]\n._ ._____ ___ __   __ ______ ___ _____ ____.\n.__|    / ._____ )\____._____ _____ ______ |\n|  |   ///____  X    __.___  X     X      \|\n|     /  \|  |   \  |._|  |   \ |   \_     \\n|     \_  )  |    \ ||  \ |   / |   / \/   /\n|__|___/_/|__|____/_____/____X_____X__||jT/|\n`---ReleasEd:---------- ------ ----- ------''\nClean the BBS tag lines from the FILE_ID.DIZ\n-  - -- --- -------------------- --- -- -  -\n','\n',char(10)),'uzi.txt',replace('                                            .---------------------------.\n    _______.-----------------._______/|     |     4NODEZ  RiNGDOWN      |\n    \_     |     .------     |________|.....| 73 GiG OF AMiGA CoNSoLE PC|\n   .:|     |     |     ______|        |:::::|  uZiSUiCiDE.sERVEBBS.ORG  |\n  .::|     |     |     |     |        |-----+-----.      TELNET         |\n .:::|           |     |     |       :|     |     |                     |\n.::::\___________|___________|________|     `-----+---------------------''\n:::::::::::::::::|                                | 24HR 7DAY STATiC iP! \n_________________|___________/|__________________/|______________________\n\_     ______    |     _______|          |_____________      _/    _____/\n_|_____    |     |     |      |    |_____|        |   |      |     ___|_ \n|     |    |     |     |      |    |     |        |   |      |     |    |\n|     |    |     |     |     :|          |       :|   |      |     |    |\n|__________|_____|_____|______|__________|________|__________|__________|\n:::::::::::::::::|            |                                         |\n`::::::::::::::::|            |ALWAYS THE LATEST VERSION oF AMi