INSERT INTO door_catalog VALUES('l_offl','L-OFFL.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/L-OFFL.LHA','offliner','XIM','offliner',NULL,'Crew-One',NULL,'\__   /\ _______\ ___/\ \________   \____ /.  /_/_\  __/   /__\/_\  __/  /   /___ \ //  /  /   __/   /   /.   __/  /  //   /  \',replace('_______         ______  ____________        \n\__   /\ _______\ ___/\ \________   \____   \n /.  /_/_\  __/   /__\/_\  __/  /   /___ \  \n//  /  /   __/   /   /.   __/  /  //   /  \ \n\_____/     /\______//     /__/_ ./   /   /\\n \____\____/ /\_____\_____/\__\_\/_______/ /\n[Sk!n]=\___\/Presents\____\/=====\_______\/ \n»» oFFLiner V1.1 New /X UtiL by Crew-One ««\n[iSDN][-÷ lEEChEd fRoM gOd''s hArEm ÷-][16.8]\n','\n',char(10)),'offliner.doc',replace('\n                         OffLiner For /X 2.s & 3.x\n\n                          Programmed By Crew-One\n\n                       For Mystical /X Util Designs\n \n                            For [L]egend 1993\n                         \n                          Release Date: 21-12-93\n\n\nWhat is Off-liner???\n--------------------\n\nOffliner Is a Small Util For /X bbs''en Who Want To Put File''s Off-line\nIn a whole Dir And Show To The users that the file''s Are Off-line By Putting\nA Text On the Bytes Place, Like OffLinE Or DeLeTed...\n\n\nExample:\n\n   Offliner dir10 dir10.bak OfFLinE\n              /    /              \\nOrig. Filename   Backup Filename   Command Line\n\n\nAnd Thiz Is The Result..:\n   \n\n [L]egend HQ 3 OfFLinE 12-19-93  19th OF DECEMBER 1993    [L]egend HQ 3 NoDeZ\n               ^^^^^^^   ___       _    _    _\n                        /__  /  / / \  / \  /_\ \_/\n                        __/  \_/ /  / /__/ /  /  /\n \nMAGCWB12.LHA P OfFLinE 12-19-93  MagicWB V1.2p: Great looking WB !!!    CaBlE\nDT213.LHA    P OfFLinE 12-19-93  DOSTRACE 2.13\nEXE&PHR.LHA  P OfFLinE 12-19-93   _______   /\___    .   /\________._ __/|__\n                                 |  ___/ \ (___  \  /|  (__)   __  | \\  __/\n                                 |  __/|  \/ \/  / / |/\/  \  /__   \/  |_. \n                                 |  |  _   \  \  \/  /  \   \ \  \ |   \| | \n                                 |__|  | __/__/\  \_____/___/____/_:___/  | \n                                    `--|/<T>    \__/    PrEsE       `-----'' \n                                 R.R.R. Multi-Tool /X Util Update.\nYAK156SR.LHA P OfFLinE 12-19-93  Yak 1.56 Source!\n5D-SRT02.LZH P OfFLinE 12-19-93  x   ____________________/\__________________\n                                 5 \____\   / \     \____\   __/     /  /   \\n                                  T/   / \__   \  T  \  / \___ \   \/___    /\n                                 H/   /   \     \ I   \    \ /  \   \      / \n                                 /________/     /_I    \/   \____\___\    /  \n                                 [===/_________/==I____/_____\RpD!/______/==]\n                                  > 5D-SORT v0.2 uPDATE by PROPHET/5D <      \n                                 -=[PhAnT¢M/oVeRlOrds]=-----[Cool CoroNA bBS]\nABS!SH12.DMS P OfFLinE 12-19-93     ___  ___  ________  _.    __  __________ \n                                   /   \/ _ \/  __/   \/ |   /| \/    \ ___/ \n                                  /  | \\    \__  \ |  \ |__/ | \\/  \/ __)_ \n                                 /      \\|   \|   \|   \|  \    \\   \     \\n                                 \___T___/____/____/____/___/_____/___/_____/\n                                 <>cSt<>----------> presents <---------------\n                                          SlEdGe HaMMer issue 12 !           \n                                 -=[PhAnT¢M/oVeRlOrds]=-----[Cool CoroNA bBS]\nAFL-NM02.LHA P OfFLinE 12-19-93       ____________________________           \n                                 +----\________   \__   ______/  /----------+\n                                 |ALPHA /     /    /   _____/   /_____FLIGHT|\n                                 +-----/    _     /      \/    /     /------+\n                                 |     \____/__  /\____  /\_______  /   #1  |\n                                 +-------------\/------\/REBEL MC!\/--------+\n                                 |      UPDATED & NEW OPTION INCLUDED.      |\n                                 +-NODE MATCH V0.2 - CREATED BY CELATOR/AFL-+\nCF_MUSIC.LHA P OfFLinE 12-19-93  THE MUSIC FROM CANNON FODDER, SEEING AS \n                                 EVERYONE LIKES THE MUSIC SO MUCH, IT WAS\n                                 REWRITTEN, THIS IS NOT RIPPED MUSIC.    \nIDE2AMI4.LHA P OfFLinE 12-19-93  IDE-2-AMI version4 Now in amiga guide format\n                                 with even more tips and has docs on how to  \n                                 fit 2 3.5'' hard disks to an A1200!!!!!      \n\n\n\nI Think It''s Quite Easy, So Enjoy Thiz Kewl Util....\n\n\n\n        »»»»»»»»  Any Bug Reports Can Be given On ThiZ BBs: ««««««««\n\n    ___ _/\    ___/\    _____/\  ___/\   __/\   ___/\    ___/\    __/\    \n  _/   V   \__/  |  \__/  ____/_/  .  \_(____)_/  .  \__/  .  \__/   /__  \n_/    _:_    \_____   \______  \_  |    \_   \_   |___/\_ _|    \_  _/  \__\n\     \ /     /   |    /    |   /__;     /    /   |     / \__    /  |    /\n \_____V     /    ·___/     ·__/  |   __/   _/__  ·    /___|    /__ ·   / \n      .:____/\____/  \______/    .:___/ \__/    \_____/   .:___/  \____/  \n                                                                          \n·mYSTiCAl·  ___/\    __/\    ___/\    ___/\    ___/\    _____/\   [L] DhQ        \n ·pLACes· _/  .  \__/   /___/  .  \__/  .  \__/  _  \__/  ____/___  _  _ __\n_  _  ___/    |    \_  _/  \_ _|    \_  |___/\_  ____/\______  \_         \n  _  ___\     ______/  |    / \__    /  |     /  \/    /    |   /___  _   \n       \\\___  |  \___ ·   /___|    /___·    /___     /     ·__///        \n            \__:.    \____/   .:___/911\____/   \____/______/             \n                                                                          \n       · SYSOP: ThC/[L]egend/DBPP ·«»· CO''Sysop: sAl-oNe/TRSi ·  \n                                                                     \n  ·  /X2.39 REG. ·«»· GVP F*RCE 68O3O/68882 4O MhZ! ·«»· 1,2 GiG HD!  ·  \n                     .                              .         ______  \n                   __:______________________________:__      /\____/\\n       ______    -(__:______________________________:__)-   /  \   \ \\n      /\     \       :                              :      /    \___\_\\\n     / /\     \      : Node 1: +31-104-779-507 (DsT):      \    /     //\n   //_/  \_____\\    | Node 2: +31-104-774-218 (DsT)|       \  /     /\n   \\ \  /     //    : Node 3: +31-104-772-519 (HsT):        \/_____/\n     \ \/     /    __:______________________________:__                                                     \n      \/_____/    (__:______________________________:__)-  \n','\n',char(10)),NULL,'auto-added',34949,25,0,NULL,NULL,'l_offl','scan',1780048560);
INSERT INTO door_catalog VALUES('l_thcc21','L-THCC21.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/L-THCC21.LHA','thc-chatter','XIM','thc-chatter',NULL,NULL,NULL,'\   |  \  ___/\  ___/\  ___/\ __ \_____ \ /  _|__/_ _|/\/ |_  \/  _|/\/  |  \  |/  \ /        / |   \  |   \  |   \  |   \      \',replace(' ____:  ___:______:______:______:_____:__\n \   |  \  ___/\  ___/\  ___/\ __ \_____ \\n /  _|__/_ _|/\/ |_  \/  _|/\/  |  \  |/  \\n/        / |   \  |   \  |   \  |   \      \\n\____\  /_______\______\______\_|    \_____/\n      \/    /X )-sIGN rELEASED: |____/sD!\n»------------------------------------------«\ntHC-cHAT v2.1, tHE uLTIMATE mULTI cHAT DOOR\n         fOR /X 3.x vERSiONS.\n  fULL sCREEN,hIGH sCORES,lAST cHATTERS\n      jOIN cHAT, mULTI tYPE sYSTEM.\n','\n',char(10)),'thc-chatter.guide',replace('@database "tHC-cHAT 2.1 gUIDE"\n@Node MAIN tHC-cHAT 2.1 dOCS"\n                                                                          \n                         [L}EGEND /X )-sIGN rELEASED\n\n                        »»·»»» tHC-cHAT v2.1 «««·««\n         »»·»» cODED bY: cREW-oNE   iDEA & dESIGNED bY: tHC ««·««\n\n\n                           @{" »· iNTRODUCTION ·« " link "intro"}\n\n                           @{" »· iNSTALATION! ·« " link "install"}\n\n                           @{" »·  gREETINGS!! ·« " link "greetings"}\n\n                     @{" »· cONTACT uS!, bUG rEPORTS ·« " link "contact"}\n                        \n@endnode\n\n@node "intro" "iNTRODUCTION"\n\n        Thiz is the ultimate multi-chat door NOW on the /X-scene...\n                           thIZ aRE tHE oPTIONS:\n\n  - fULL sCREEN cHAT\n  - tYPE wHEN tHE oTHER iS tYPING\n  - hIGHSCORE (lONGEST cHATS)\n  - lAST cHATTERS\n  - jOIN cHAT''S\n  - fAAST aSM cODING  \n\n            nO tIME fOR lONG aND bORING dOC''S, gET tO tHE poINT.\n        inSTALL thIZ oNE oN yoUR mULTI NODE sYSTEM iT''S tHE FUTURE\n\n@endnode\n\n@node "install" "iNSTALLATION"\n\n- Directory:\n\n cOPY tHEZE fILEZ iN tHE dIRECTORY: BBS:DOORS/THC-CHAT/\n\n      > THC-CHATTER          \n      > THC-CHATTER.HIGHSCORE\n      > THC-CHATTER.LASTUSERS\n      >	THC-CHATTER.LENGHT\n      >	THC-CAHTTER.gUIDE\n\n cOPY tHIS iCON iN tHE dIRECTORY: BBS:COMMANDS/BBSCMD/\n\n      > CHAT.INFO\n\n\n tHaTS aLL.. iNSTALL iT aND uSE iT!!!!!\n\n@endnode\n\n@node "gREETINGS" "iNSTALLATION"\n\n            gREETINGS mUST GO tO THEZE REGISTRATED bETA tESTERS\n          »-----------------------------------------------------«\n                tHC/lEGEND     - mYSTICAL pLACES  [ 4 NODEZ ]   \n                eMPIRE/mYSTIC  - lAST oUTPOST     [ 2 nODEZ ]\n                oVERLORD/SR    - dOOMBASE]        [ 2 nODEZ ]\n                pHANTOM        - cOOL cORNIA      [ 2 nODEZ ]\n                tAZ dEVIL/CF   - rUINS oF wISDOM  [ 3 nODEZ ]\n                mINDEX         -                  [ 2 noDEZ ]\n          »-----------------------------------------------------«\n\n                oTHER gREETINGS gO tO: aLL lEGEND mEMBERS,             \n                     anD aLL uSERS oF mYSTICAL pLACES \n\n@toc "menu"\n@endnode\n\n@node "cONTACT" "cONTACT uS!!!!"\n                   ___\n    .  /\  /\  ____|  \_____________________  _______________ ________\n   _:_// \/  \/~  ||   \_   _______   .__/__)/~        /~    \|.    _/__:_\n    |/        \__ `'' ___/_____  \/   .||~  .|    /____/   |   \|    |___|\n   _/    \/   \\|    |_/     |  \\_  |||   ||   / ~  \    _   \\    |   \_\n   \_____||     \____|\      _____/___||____|___     \\___|     \________/\n   -|-----|______/-----\_____/----Stz!---------\_______/--|______/------|-\n    |     _________________    _____  __________________/\___________  .|\n    |     \_______  \    _/   /~    \/~         /~ ____   /~   _____/  ||\n   _|______|.  __/   \   |___/   |   \    /____/  __/_\ //______   \____|\n    :      ||  \______)  |~  \_  _   \\_ / ~  \_       \/\_    /   \\_  .\n    .      |     | |__________/  |_____/_______/__________/__________/\n -:--------|_____|--------\______|---------------------------------------:-\n ___________________________________________________________________________\n             nODE 1.......   +31-(0)10-477-9507  (dUAL 21k6)\n             nODE 2.......   +31-(0)10-477-4218  (dUAL 14k4)\n             nODE 3.......   +31-(0)10-477-2519  (dUAL 21k6)\n             nODE 4.......   +31-(0)10-477-2985  (dUAL 21k6)\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n     »» cONTACT thIZ bBS tO gET tHE lATEST vERSION oF tHE tHC-CHAT ««\n  »»  aND/oR rEPORT bUG rEPORTS oR iF yOU wANT to bE a bETA tESTER !! ««\n@toc "menu"\n@endnode\n','\n',char(10)),NULL,'auto-added',14805,1,0,NULL,NULL,'l_thcc21','scan',1780048560);
INSERT INTO door_catalog VALUES('l_thcqv1','L-THCQV1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/L-THCQV1.LHA','tHC-qUEST','XIM','____:  ___:______:______:______:_____:__',NULL,'pLL',NULL,'\   |  \  ___/\  ___/\  ___/\ __ \_____ \ /  _|__/_ _|/\/ |_  \/  _|/\/  |  \  |/  \ /        / |   \  |   \  |   \  |   \      \',replace(' ____:  ___:______:______:______:_____:__\n \   |  \  ___/\  ___/\  ___/\ __ \_____ \\n /  _|__/_ _|/\/ |_  \/  _|/\/  |  \  |/  \\n/        / |   \  |   \  |   \  |   \      \\n\____\  /_______\______\______\_|    \_____/\n      \/   /X )-sIGN rELAESED   |____/sD!\n »»· tHC-qUEST v1.0 bY pLL Developments ·««\n','\n',char(10)),'PPTPUM.guide',replace('@database PPTPUM-Documentation\n\n@master ©PPTPUM.guide\n@Remark AmigaGuide database for the ©PPTPUM Documentation\n\n@node main "©PPTPUM-DOC Contents"\n \n\n                    /X PlayPen To PartUpload Mover V1.5 Docs\n                    ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                         (C) 1994 by Metal Death/Leprosy\n\n\n	@{" Legal Stuff                         " link "Legal Stuff"}\n	@{" Brief Description                   " link "Brief Description"}\n	@{" Configuration, installation, etc... " link "Configuration, installation, etc..."}\n	@{" Limitations                         " link "Limitations"}\n	@{" Credits                             " link "Credits"}\n	@{" Support                             " link "Support"}\n	@{" Contact the Autor                   " link "Contact"}\n\n\n@endnode\n\n@node "Legal Stuff"\n\n                     /X PlayPen To PartUpload Mover V1.5 Docs\n                     ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nLegal Stuff:\n~~~~~~~~~~~~\n	This tool is (C) 1994 by @{"Metal Death/Leprosy" link "Credits"}. It may NOT be\n	distributed by some weird PD companies without the explicit\n	permission of the author. Anyway, it may be freely copied,\n	as long as no money get`s involved. The program was released\n	to the public as `MetalWare`, means, if you like and use it,\n	go ahead and send me a tape with some @{"Death/Thrash/Funk/Heavy" link "Shame"}\n	Metal on it, preferably demos of unsigned bands, or any other\n	(real!) heavy stuff !   ~~~~~~~~~~~~~~~~~~~~~~~\n	Please don`t bore me with shit like Poison, Winger and so on 8-)\n\n@endnode\n\n@node "Brief Description"\n\nBrief Description:\n~~~~~~~~~~~~~~~~~~\n	If you`re running a BBS on /X, you surely know that problem:\n	somebody pumps up tons of warez, just before he`s finished,\n	the BBS crashes and after the reboot, all those files are\n	flying around in nodeX/playpen, it`s not possible to resume them\n	or enter a description, until the sysop moves `em to the right\n	directories. This is, where ©PPTPUM comes in: it will scan all\n	your playpen dirs for files, if something is found, it will scan\n	the @{"callerslog" link "Configuration, installation, etc..."} of the correspondig node for the uploader and\n	the right conference and then move the files to the according\n	directories, ready for the user to resume.\n	Now, why use this one ? There are already tools out, that do\n	the same ? Correct, but this one is by far the best, just read\n	on, and you`ll know why !\n\n\n@endnode\n\n@node "Configuration, installation, etc..."\n\nConfiguration, installation, etc...\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n	First, you will have to do some configuration stuff. Just use\n	your favourite txt-editor ( ©Cygnus Ed, ©Edge, ©EdWard, ... )\n	and create a file like this:\n\ns:lep-np.cfg\nbbs:bbs/NewUsers/partupload/\nbbs:bbs/PublicDomain/partupload/\nbbs:bbs/Amiga/partupload/\nbbs:bbs/Sysops/partupload/\nbbs:bbs/PC/partupload/\nbbs:bbs/Requests/partupload/\nbbs:bbs/Ae-Support/partupload/\nbbs:bbs/Pics/partupload/\nbbs:bbs/Coders/partupload/\n\n	The first line has to be a path & filename of your choice, it`s\n	where ©PPTPUM will look for your node-config file, we`ll talk\n	about that later on.\n	The other lines are simply the full paths to each conference`s\n	partupload-directory. Be sure, you put them in the right order,\n	means, conference 1 first, then conference 2, ...up to conference 9.\n	Don`t forget the `/` at the end of each path !\n	Now save this file to wherever you like, this will be the main-\n	config file.\n\n	Now, you have to create another file, with information about\n	your nodes in it, this should look like that:\n\nbbs:bbs/node0/playpen/\nbbs:bbs/node0/callerslog\nbbs:bbs/node1/playpen/\nbbs:bbs/node1/callerslog\nbbs:bbs/node2/playpen/\nbbs:bbs/node2/callerslog\n\n	This would be an example for a BBS with 3 nodes.\n	Line 1 is the path of the node`s playpen dir, line 2 is the\n	path & name of the callerslog for that node, just do that for\n	all nodes you have, and you`re done. Save this, just as you wrote\n	in the first line of the main-config, e.g. in this example as\n	`s:lep-np.cfg`.\n\n	Now just put ©PPTPUM in your startup-sequence, with the path &\n	name of the main-config as an argument, e.g. PPTPUMV1.5 s:LEP-PPM.cfg\n	DO NOT put any comment in at the end of this line, the path \n	HAS to end with a RETURN, there`s no real argument-parsing !\n\n\n	That`s it for the normal stuff, ©PPTPUM will do it`s work now...\n	....BUT: have you ever seen something like that in your\n	callerslog ??\n\n**************************************************************\n02-04-94 (13:56:22) [113] MORGOTH (CONNECT 14400/ARQ/V42b) -HADES-\n	Resuming cls_ff1.dms  614878 bytes [219136]\n	Uploading ipt-cka.nfo  4934 bytes\n	Uploading ipt-cka1.dms 469983 bytes\n	Uploading ipt-cka2.dms 582783 bytes\n	Uploading ipt-cka3.dms 562510 bytes\n	Uploading ipt-cka4.dms 559318 bytes\n	Uploading sr-elan2.dms 390395 bytes\n\n\n	As you can see, there`s no information about the conference, in\n	which the upload took place in this callerslog-entry !\n	This happens, whenever a user is resuming an upload after a\n	loss carrier. Now, there would be no possibility to move the\n	files to the correct directory for any available playpen-mover !\n	But ©PPTPUM offers you another chance in such cases, it is able\n	to move files according to their extensions (.DMS, .ZIP, ...) !\n	For instance, you have an AMIGA-conf & a PC-conf: now, DMS or LHA\n	files will surely belong to the AMIGA-conf, ZIP, ARJ belongs most\n	likely to the PC-section. So you can tell ©PPTPUM, to move these\n	files to the right conferences ! To do so, you have to create\n	another file, which has to be called `Lep-PPDF.cfg` and has to\n	reside in s:\n	©PPTPUM will look for this file, if it`s found, extension-moving\n	will be on, else off. This file has to look like that:\n\n.arj5.zip5.dms2.txt6.ARJ5.ZIP5.DMS2.TXT6.lha2.LHA2\n\n	This means: ARJ and ZIP will go to conf 5, TXT will go to conf 6\n	DMS and LHA will be moved to conf 2 ! You can do this for any\n	extension & conference you like, just add it to `Lep-PPDF.cfg` !\n	Each entry must consist of the extension followed by the conference\n	to move to, e.g. `.ZOM4`, do this in lower- and uppercase !\n	Just put all these entries in ONE line, with a RETURN at the end\n	of the line. Up to 20 extensions are supported !\n	Now, ©PPTPUM will do it`s normal work, and in case, it can`t find\n	information on the correct conference, it will look for the\n	extensions and only if even this fails, the file will stay in\n	playpen !\n\n@endnode\n\n@node Limitations\n\nLimitations:\n~~~~~~~~~~~~\n	- Up to 10 nodes are supported\n	- Up to 10 conferences are supported\n	- Up to 20 extensions can be used\n\n	If there is a demand, i can extend those limitations of coz !\n\n@endnode\n\n@node Credits\n\nCredits:\n~~~~~~~~\n	Coding & docs by:		Metal Death/Leprosy\n	Guide conversion by:		Secret Agent/Leprosy\n	Beta testing & bug reporting:	Ufo\n\n\n\n	If you should encounter some bugs or have any suggestions, or\n	if you are a good trader (hehehe) give us a ring at:\n\n\n\n                                /X\eTal Church\n                                ~~~~~~~~~~~~~~\n      -------------------------------------------------------------------\n      LINE #1: +43-725-266-402   (2400-38.400 Baud - V.32bis/Zyxel 16.8!)\n      LINE #2: +43-725-280-598   (9600-38.400 Baud - V.32, USR-DUAL HST)\n      LINE #3: +43-725-268-6557  (2400-38.400 Baud - USR-HST)\n      -------------------------------------------------------------------\n\n@endnode\n\n@node Support\n _________. ._________.  __________.  _________   ____.\n|   ._.   | |.        | |          | |        .| |   .|         RUNNING ON:\n|:  |||   | ||  ______| |___    ___| |    |   :| |   ||         ~~~~~~~~~~~\n||  |||   | ||  ___|__.    |   .|    |        || |:   |____.   68030/25 MHZ\n||  | |   | |         |    |   ||    |    |   || ||        |     /X V3.32\n|___| |___| |_________|    |____|    |____|____| |_________|   1 GIGA-BYTE!!\n._________.  _________.  _________. ._________  ._________.  _________.\n|.        | |.   |    | |    |    | |.        | |         | |    |   .|\n||  ______| |:   |    | |:   |    | ||   _____| |.  ______| |    |   :|\n||  |_____. ||        | ||   |   .| ||   |      ||  |_____. |.       ||\n|         | ||   |    | |        || |    |      ||        | ||   |   ||\n|_________| |____|____| |_________| |____|      |_________| |____|____|\n          :           :             :                     :           :!RS!\n                   >>> SEARCHIN` FOR AN ELITE-GROUP <<<\n   SAINT  : UFO                                               \n   SINNERS: METAL DEATH/LEPROSY, SNOWMAN/LEPROSY\n   -------------------------------------------------------------------\n   LINE #1: +43-725-266-402   (2400-38.400 Baud - V.32bis/Zyxel 16.8!) \n   LINE #2: +43-725-280-598   (9600-38.400 Baud - V.32, USR-DUAL HST)      \n   LINE #3: +43-725-268-6557  (2400-38.400 Baud - USR-HST)             \n   -------------------------------------------------------------------\n            "/X\ETAL CHURCH - THE AUSTRIAN WAY OF FRIENDSHIP!"\n\n@endnode\n\n@node CONTACT\n\n	To contact the autor of this great tool, write to:\n\n                         -+---------------------+-\n                          | Metal Death/Leprosy |\n                          |     PO. BOX 194     |\n                          | 4400 Steyr/AUSTRIA  |\n                         -+---------------------+-\n                                    or\n\n                      call our @{" support BBS " link "support"} in Austria\n\n@endnode\n\n@node HELP\n\n	use the textbuttons to read details to the tool.\n	For information to ©Amigaguide read the manual.\n\n@endnode\n\n@node Shame\n\n\n	What?????\n\n	You don''t know Death/Thrash/Funk/Heavy Metal????!!!!....HEHEHEHE\n\n	Oh, what a shame!!!!!\n\n@endnode\n\n','\n',char(10)),NULL,NULL,22070,3,0,NULL,NULL,'l_thcqv1_thc_quest','scan',1780048567);
INSERT INTO door_catalog VALUES('lac_v120','LAC-V120.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LAC-V120.LHA',NULL,'XIM','LaCUtil.exe',NULL,'Delusion.','LAC',NULL,replace('Last callers by Delusion. Compiled Arexx    \n','\n',char(10)),'Convert111to120.doc',replace('\nTHIS PROGRAM SHOULD BE RUN BY OLD PREVIOUS USERS OF LACUTIL V1.11!\n\n/* ----------------------- Delusion & ViRtUaL ---------------------------- */\n\nCONVERT USAGE:\n\nCONVERT BULL10.txt BULL40.txt\n\n        |__\n            Use the output bulletin names thay you has specified with\n            your old LacUtil V1.11!\n\nIt converts your old bulletins to the V1.20 standard and also\nconverts the old Virtual.Data to the new BIGGER one..\n\n/* ----------------------- Delusion & ViRtUaL ---------------------------- */\n\n','\n',char(10)),NULL,'auto-added',61316,1,0,NULL,NULL,'lac_v120','scan',1780048567);
INSERT INTO door_catalog VALUES('lameqwkr','LAMEQWKR.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LAMEQWKR.LHA','QWk','XIM','Pointers',NULL,NULL,NULL,':_______\_  |__________/\_______\_  |_____ |  ___  \|  /   ________ \ ___  \|  ____  \ |  |  \  \  \____ ¬\/  |  \|  \  \  / _/   \',replace('        ______ _  _             ______ _  _ \n:_______\_  |__________/\_______\_  |_____  \n|  ___  \|  /   ________ \ ___  \|  ____  \ \n|  |  \  \  \____ ¬\/  |  \|  \  \  / _/   \\n|  |   \  · /   |   \  .   \   \  ·/  \____/\n|__:   |\___\_______/__|    \__|\__\____  ¬\\n<--|___|----[ßmR!]-----|_____/---------|___/\n·------· rELEASES fOR yAR pLEASURE: ·------·\nLAMEQWK FOR AMIEXPRESS·DA BEST QWK DOOR 4 /X\n','\n',char(10)),'QWk.DOC',replace('\n	×××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××\n\n\n		THE LAMEQWK V1.0 DOCUMENTATION BY =DEETSAY=/INSANE\n		  (Gee... It''s my first MAJOR release for /X...)\n\n\n	×××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××\n\n\n		-- HOW DOES THE QWK SYSTEM WORK:\n\n\n	Well.  The user dives into the door, which will prepare for him a\n	packed file with some messages inside.  A bit like ZOOMmail...\n	Then, offline, the user takes out his favourite QWK reader and\n	reads the mail in the packet and the reader packs his replies into\n	a .REP packet.  The user uploads the reply packet to the QWK door\n	and the QWK door adds the messages to the BBS.\n\n	So that''s what LameQWK is basically supposed to do, too.  LameQWK\n	is the QWK door.  You''ll have to find the QWK reader from somewhere\n	else.\n\n\n	×××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××\n\n\n		-- INSTALLATION:\n\n\n	Requirements:	Any Amiga\n			AmiExpress 3.x (Sorry, 2.xx''ers!)\n			AEDoor.library by Sintax/WoT, in LIBS:\n\n\n	Place the "QWK" program in its own unique directory on your hard\n	drive (make sure there''s enough space!!) and the "QWK.CONFIG" and\n	"QWKTITLE.TXT" go to the same dir. You can edit the "QWKTITLE"\n	yourself. It is shown with ''ShowGFile'' call, so it uses the\n	filename extensions you''ve defined for Express. (screentypes)\n	For example: ".TXT.GR", ".IBM" or whatever!\n\n	The contents of the "QWK.CONFIG" file are:\n\n		Line 1:	BBS-ID, max. 8 chars.\n		Line 2:	BULLETIN file.\n		Line 3:	NEWS file.\n		Line 4:	GOODBYE file.\n		Line 5:	Max. messages. It takes 3-5 minutes to add 1000 msgs\n			on my A1200. So if you put 10000 here, then the\n			user may leave your BBS offline for quite a while\n			because the program doesn''t detect a lost carrier\n			until it asks something from the user.\n		Line 6:	Name of packer #1.\n		Line 7:	Name of packer #2.\n		Line 8:	Name of packer #3.\n\n\n	Example "QWK.CONFIG":\n\n		SINESTUD\n		RAM:SIENI/SCREENS/NODE/BULL.IBM\n		RAM:SIENI/SCREENS/NODE/LOGON.TXT\n		RAM:SIENI/SCREENS/NODE/LOGOFF.IBM\n		1000\n		LhA\n		LzH\n		Zip\n\n\n	Think that was it?  Hah, you have only the worst thing to do.\n	You have to take your "CONFCONFIG.INFO" (located in your BBS\n	directory) and write a "QWKID.<conf>" identification for all your\n	conferences.  The QWKID can''t be longer than 13 chars.\n\n\n	Example "CONFCONFIG.INFO":\n\n		NAME.1=(Main) StudioLine\n		LOCATION.1=BBS:Confs/Main/\n		QWKID.1=MAIN\n		NAME.2=(Amiga) Pub Domain\n		LOCATION.2=BBS:Confs/Amiga/\n		QWKID.2=AMIGA\n		etc...\n\n\n	Don''t write ID''s for net conferences; those will be automatically\n	skipped because they have different headerfiles and it''s near\n	impossible to store any nodeid''s in the QWK file.\n\n	ANYWAY, I intend to code netconf-support in the future.\n\n\n	The next worst thing is to edit all the ".S" files in the QWK\n	directory to match the packer programs you''ve promised in\n	"QWK.CONFIG"...  YOU MUST EDIT THESE even if you don''t change\n	the packers: You must change all the "SINESTUD" strings\n	(my BBS-ID) to whatever your BBS-ID is..!..  Don''t forget it!\n\n	The "add-1.s", "add-2.s" and "add-3.s" scripts are for adding\n	all the files from "QWK_WORK.<node>/" (where <node> is the node\n	from which the door was called from) to one file called\n	"QWK_TEMP.<node>/<bbsid>.QWK" (where <bbsid> is YOUR BBS-ID, not\n	"SINESTUD", replace it!! =))  You can change the packers or their\n	parameters freely, as these are normal script files.\n\n	The "ext-1.s", "ext-2.s" and "ext-3.s" scripts are the matching\n	extract scripts.  They''re supposed to extract the file called\n	"QWK_TEMP.<node>/<bbsid>.REP" to "QWK_WORK.<node>/"...  Replace\n	my BBS-ID''s with your own again!\n\n	Set the script protect bit on all the ".s" files!\n	(try "protect #?.s +s" in the shell)\n\n\n	You''re very close to being perfectly set up =)...  Dig up your\n	"logoff batch(es)", wherever they are, or if you don''t have them,\n	then create them.  You can place the program called "Pointers"\n	anywhere, and you must run it after the user has logged off,\n	like in the logoff-batch for example.  The program takes one\n	argument and that is the node number.  So for example in the\n	"logoff-batch" of node 1 you must write:\n\n		POINTERS 1\n\n\n	Finally create an icon called "BBS:COMMANDS/BBSCMD/QWK.INFO" and\n	edit it (tooltypes) to look about like this (example):\n\n		LOCATION=DOORS:QWK/QWK\n		MULTINODE=NO\n		ACCESS=10\n		TYPE=XIM\n		STACK=50000\n\n\n	...and I guess you''re ready to go.  Have phun!\n\n\n	×××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××\n\n\n		-- KNOWN BUGS & GOOD POINTS:\n\n\n	Take a look at this list and think if you could do a better QWK\n	door... and if you can, then please do it.\n\n\n	- /X usernames can be 30 chars long, the QWK format will cut them\n	  at 25 chars.  This means that users with long names won''t get\n	  any mail right by QWK.\n\n	- Any user can send, for example, 4000 private messages to a user\n	  called ''kyhmy'', even if you don''t have a user called ''kyhmy''.\n\n	- There''s no limits for incoming messages.  If a user sends you a\n	  .REP file with 10000000000 messages then...  It may take a while,\n	  but LameQWK won''t stop adding until it''s done, or you come and\n	  reboot. =)\n\n	- LameQWK supports only up to 1024 conferences.\n\n	- LameQWK will skip AmiXnet conferences, or any other conferences\n	  that have a "MsgBase.def.info", because in practise this means\n	  that the messagebase is not normal.\n\n	- The users'' message pointers will be changed even if the download\n	  fails.  This may be annoying to the user, but who cares.\n\n	- Some more?  Tell me via AmiXnet, write to =dEEtsAY=@SF0004\n\n\n	Despite the name, LameQWK is not only made of bugs. Here''s a couple\n	of prods too:\n\n\n	+ Incoming EALL messages will be converted to normal ALLs =)...\n\n	+ LameQWK will automatically skip AmiXnet conferences.  Of course\n	  it would be better if it supported them =) but skipping them\n	  is better than causing msgbase errors, isn''t it?\n\n	  In the future, AmiXnet conferences will be supported.  I think.\n	  Some day.\n\n	+ LameQWK supports up to 1024 conferences.\n\n	+ Some more?  Tell me via AmiXnet, write to =dEEtsAY=@SF0004\n\n\n	×××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××\n\n\n		-- DISCLAIMER AND UNREGISTERING INFORMATION:\n\n\n	Who knows what kind of bugs this door will eventually be found to\n	have. You can''t hold me morally or legally or financially\n	responsible for anything that happens in your BBS during usage of\n	LameQWK.\n\n	The REGISTERED version of LameQWK v1.0 is included in this package,\n	which is completely free.\n\n	If you don''t like LameQWK, you must UNREGISTER within 30 days of\n	deleting it. Send $25, along with the following form completely\n	filled, to: s1nEsTud10, Päivämiehent. 7, 40950 Muurame, Finland.\n\n\n		<<<< LAMEQWK v1.0 UNREGISTERING INFORMATION >>>>\n\n\n	Handle........: _____________________________________________\n\n	Group.........: _____________________________________________\n\n\n	FULL REAL Name: _____________________________________________\n\n\n	Address.......: _____________________________________________\n\n	              : _____________________________________________\n\n	              : _____________________________________________\n\n	              : _____________________________________________\n\n\n	Phone number..: _____________________________________________\n\n\n	BBS name......: _____________________________________________\n\n	BBS number....: _____________________________________________\n\n\n	Amiga used....: A500 A600 A1000 A1200 A2000 A3000 A4000 OTHER\n\n\n	Other info....: _____________________________________________\n\n	              : _____________________________________________\n\n	              : _____________________________________________\n\n	              : _____________________________________________\n\n\n\n	Signature.....: _____________________________________________\n\n\n\n	×××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××\n\n\n		-- THANKS:\n\n\n	Thanks to the people in AmiXnet who helped with the system coding,\n	especially Dope. Then thanks to Generator and 2-cool for help with\n	the machine code. Also thanks to Wouter van Oortmerssen for the\n	Amiga-E and Sintax/WoT for the aedoor.library.\n\n	And thanks to Bytemaster for the AmiExpress, of course =)..\n\n\n							=dEEtsAY= /1n$AnE\n\n\n	×××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××\n\n\n			    LAMEQWK SUPPORT (NOT INSANE BOARD):\n	    -=========================================================-\n		      SINESTUDIO      || +358-41-3110417 || =dEEtsAY=\n	    -=========================================================-\n\n\n				  INSANE BOARDS:\n	    -=========================================================-\n		  INTERCHANGE, WHQ    ||  +46-86082339   ||  Princip\n		  SHADOW ZONE, SHQ    ||  +46-87651455   ||  Boozer\n		A SPLIT SECOND, SFHQ  || +358-42-745603  ||  Split\n	    -=========================================================-\n\n\n	×××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××××\n\n','\n',char(10)),'{"LOCATION":"DOORS:QWK/QWK","ACCESS":"10","TYPE":"XIM","STACK":"50000"}','auto-added',22818,14,0,NULL,NULL,'lameqwkr','scan',1780048567);
INSERT INTO door_catalog VALUES('last10','LAST10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LAST10.LHA',NULL,'XIM','LAST 10 CALLERS BY BUBBA','3.2','BUBBA',NULL,NULL,replace('LAST 10 CALLERS V3.2 BY BUBBA\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 19:32:42  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,NULL,3125,1,0,NULL,NULL,'mst_lt12_last10','scan',1780048567);
INSERT INTO door_catalog VALUES('later','LATER.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LATER.LHA',NULL,'XIM','__|___________:___:_______:___:___|___',NULL,'nocTurne',NULL,'/      |   _   |   |       |   |       \ /   l   |   \___|   |   l_  |   |   |    \ \_______|___|   |___|____/  |___|___|____/',replace('   __|___________:___:_______:___:___|___\n  /      |   _   |   |       |   |       \\n /   l   |   \___|   |   l_  |   |   |    \\n \_______|___|   |___|____/  |___|___|____/\n     `------------ -  _ _____j - ----''noC\n .------                            ------.\n :   noC-LATER V1.21 by nocTurne deSign   |\n            - --===========-- -           :\n : Graphical means for remote cosysops to\n |   kick off an online user (/X 3.38+)   :\n `------ -                 - -- ----------''\n','\n',char(10)),'LATER.doc',replace('\012          ______             .   .                            ______\012   ____  /     /_____________|   |___________________  ____  /     /_________\012  /    \/     /    \    ______    ______/    /   _   \/    \/     /         /\012 /           /      \   \    |    \    /    /    /   /           /    7____/\012/_____/\____/________\_______|_____\_______/____/\________/\____/\_________ _\012noC\012                noC-LATER v1.21 - (C)1994 nocTurne deSign/Origin\012                ------------------------------------------------\012\012                         Synopsis:\012                         ---------\012                         noC-LATER  provides a graphical means for remote\012                         sysops  to boot users off of other nodes, giving\012                         them  a  node list through which they can scroll\012                         and  select  whom they want to dispose of.  Even\012                         those  who  are  transferring files are not free\012                         from the wrath of noC-LATER.\012\012    Installation:\012    -------------\012    Install  noC-LATER  as  you  would  any other /X\012    door.   Please note that you must be using v3.38\012    or  greater.   The bbscmd icon included requires\012    users to have an access of 250 to use the door.\012\012                            Usage:\012                            ------\012                            After  the  user has typed "LATER" at the prompt\012                            and  he  has  sufficient access, a list of users\012                            online  and their actions will be displayed.  At\012                            that  point  you  may  he  the  cursor  keys  to\012                            highlight  the user he wishes to boot, or simply\012                            type  the node number.  The user may also update\012                            the list by pressing ''U''.  when the desired user\012                            is  highlighted, pressing return will bring up a\012                            verification  request.   If confirmed, noC-LATER\012                            will proceed to knock off the selected user.  It\012                            will  take a few moments for the user to be gone\012                            completely.\012\012     Credits:\012     --------\012     noC-LATER  is  a  product  of nocTurne deSign of\012     ORiGiN  US  in  1994.   Bug-Reports and comments\012     should be directed to nocTurne on DOMiNO EFFECT,\012     (ad  below),  or  one of the other many boards I\012     frequent. Or shoot some mail at my internet addy\012     "[email removed]".\012\012_______________________________________________________________________________\012 |                        |\012 |     :     :            |/\                          _______\012 | ____|     |____________/  \  ____________________  /      /________.\012 |/          |           /    \/    \        /      \/      /         |\012 /     7     |    7     /            \      /              /     7    |\012 \___________|_________/______\/______\____/______/\______/___________|\012 |                _________|_________ _                    .     .\012 | ____________  /      ___/    _____________  ____________|     |___ _\012 |/            \/     ____   ____            \/    _________      _____\012 /      7______/        |     \       7______/     \       |      \noC\012 \______________________|______\_____________\_____________|_______\\012 |                         |\012 | nODE 1: +1.503.758.0019 |    sTAFF:  M.BiSON/ACC - nOCTURNE/OGN\012 | nODE 2: +1.503.RNG.DOWN |    nOCTURNE dESIGN & ACC hEADqUARTERS\012 | nODE 3: +1.503.VRY.SOON |            aMIGA/PC/SNES/SEGA\012 | nODE 4: +1.503.VRY.SOON |  aLL sNES tITLES sINCE JAN ''92 *ONLINE*\012 |   aLL 28.8K USR dUALS   |        a4ooo''o4o/4oMhz - 3.3 gIGS\012 |                         |      dOMINO eFFECT - NUP: tWINtURBO\012 `-------------------------''\012','\012',char(10)),NULL,NULL,29206,12,0,NULL,NULL,'later','scan',1780048567);
INSERT INTO door_catalog VALUES('lc_bl100','LC-BL100.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LC-BL100.LHA','LC-BBSList','XIM','LC-BBSList',NULL,NULL,'LC','-+- ----=*=---- ----- -   -  -  -+- !                               . ! eRRoR & LC_Prg Developments   !',replace('  .                               .\n -+- ----=*=---- ----- -   -  -  -+-\n  !                               .\n  ! eRRoR & LC_Prg Developments   !\n    proudly presents :            i\n  !                               .\n  :    LC-BBSList Creator v1.00   \n  .                               !\n -+- --   -  -  ---*----  -- -   -+-\n  `                               `\n','\n',char(10)),'LC-BBSList.doc',replace('\n\n                        LC-BBSList creator v1.00\n                        ~~~~~~~~~~~~~~~~~~~~~~~~\n                        Coding : Lord Coma/eRRoR\n                        Design : T-SpOoN\n\n                        ~~~~~~~~~~~~~~~~~~~~~~~~\n\n\n 1. Introduction.\n\n    Welcome,\n\n    This is LC-BBSList creator for Amiexpress / S!Express or any\n    other clone that is capable running these doors, this door\n    is just wat is says, it creates a BBSList that ofcourse have\n    to be filled in by the user (a sysop/cosys) online.\n\n 2. NOTICE!.\n\n    I, Lord Coma of the group eRRoR do not RUN /X or other clone\n    so please dont give thought''s to items that i am forgetting\n    to mention or even to add to this archiver.\n\n    This tool will also be available on Xenolink, requires v1.90\n    or above.\n\n    Also, the credits for the ideeas and design go''s to T-SpOoN\n\n 3. Installation.\n\n    Make a directory called:      Doors:LC-Tools/\n    (remember THIS is hardcoded as default path, so just create it)\n\n    Move the file LC-BBSList to this directory ''Doors:LC-Tools/''\n\n    Move the file LC-BBSList.info to this directory ''Doors:LC-Tools/''\n\n    Move the supplied ICON file into your bbs commands directory(s)\n    or just remember to create a icon of yourself with the correct\n    path as LOCATION ''Doors:LC-Tools/'' and as door TYPE XIM module.\n\n 4. Configuration\n\n    The only configuration you have to do is edit your LC-BBSList.Info\n    that belongs in the directory Doors:LC-Tools/ with only 2 parameters\n\n    1.  PATH=<your bulletins path> \n    2.  FILE=<the bulletins filename>\n\n    Pleas ensure yourself that you ADD a slashback known as / to the end\n    of the PATH= or else the door will not work.. \n\n    Example :\n\n    PATH=BBS:Bulletins/\n    FILE=Bull200.txt\n\n 4. Final words.\n\n    Well as small as this document is i hope you will enyou this door\n    Ofcourse, this is just one of thousends of /X tools.\n\n    Also, if there are *BUGS* or *IDEEAS* then do try to reach me at\n\n    LordsCave BBS Deventer +31(0)5700-10479 running Xenolink v1.95\n\n                                  or at\n           \n    Super Dancer node #1 +31(0)5700-37050 / node #2 +31(0)5700-77702 28k8\n    running on /X with lots of goodies.. he has been offline for a while\n    due *MANY* hardware problems so DO give hime a call!.\n\n    Almost forgot,  Greetings to everyone i know.. not gonna mention \n    names this time but any eRRoR , LC''er or Impact dude.. have my\n    special greetings..  : -------- *    Groetjes    * --------\n\n\n As expected, EOF','\n',char(10)),NULL,'auto-added',20155,2,0,NULL,NULL,'lc_bl100','scan',1780048567);
INSERT INTO door_catalog VALUES('lcd','LCD.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LCD.LHA','LCD','XIM','LCD',NULL,NULL,NULL,'Mb / _   / ____/  \/  ||__|    0F /  |__/  _/\ |      ||  | /   |  |  |  \|  \/  ||  | fAiRLiGHT',replace('      ______________  __..__.\n  Mb / _   / ____/  \/  ||__|    0F\n    /  |__/  _/\ |      ||  |\n   /   |  |  |  \|  \/  ||  | fAiRLiGHT\n   \______|______\  ||__||__|\n+----------------|__|--------[pREsENtS]--+\n|  Last Callers Designer - Version 1.0   |\n|­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­­|\n| Create your OWN last caller bulletins, |\n| using the editor provided.  For /X 3.x |\n| All coded in ASSEMBLER for fast output |\n+----------------------------------------+\n','\n',char(10)),'LCD.DOC',replace('\n              -----------------------------------------------\n              Last callers designer v1.0 by Cemi of fairlight\n              -----------------------------------------------\n\n\n            You need an 68020 or better to use this program!!!\n\n\nLast callers designer allows the sysop to create his/her? own last callers\nbulletin!\n\nTWO program files are included in the archive as well as some\nexample ''Last Caller Designs'' and this documentation.\n\nYou use an special ANSI editor to create designs and set preferences, then\nyou use another program to update bulletins from the design you created.\n\nThere are some things in the editor that may seem rather obnoxious, eg.\nyou can multi-select menu items(!)  I got no more time to waste on this\nutility, I got other things to do, you''ll just have to live with it until\nI can be bothered to update it.\n\nThese docs are rather shit, I can''t be bothered with it anymore.  Like it\nor lump it.\n\nNTSC users will have their screen set to interlace mode.  I can''t be\nbothered to change my code.  Maybe later on in the year...\n\n\nI say, I am a lazy bastard.... Oh well.\n---------------------------------------------------------------------------\n\n                           LAST CALLERS DESIGNER\n                           =====================\n\n3.Boot:> LCD <filename>\n\n<filename> is optional, you must specify the full path+filename to a design\n\n\nThis is what you must run FIRST.\n\nSelect MAIN PREFS from the PROJECT menu, fill in the details for the node\nnumbers you have set-up in /X then select SAVE.  (A file called S:LCD.prefs\nwill be created which holds this data)\n\n\n* Number of callers to store *\n\nThis value will tell LCD_UPDATE how many callers to store in S:LCD.DATA\n\n\n\nPLACE FIELD - INFO FIELD menus\n==============================\n\nUse these menus to place a field.\n\neg. USERNAME/HANDLE\n\nSelect which type of field you want to place, which is one of:\n\n    TODAY, YESTERDAY, THIS WEEK, LAST WEEK, BEST DAY, BEST WEEK, TOTAL\n\n\nPlace ''x'' characters where you want the username to appear in the bulletin\nusing the current color and style.  You dont have to use ''x'' characters but\nit makes the design more readable.\n\nWhen your done press RETURN and you will be returned to normal text mode.\n\n\n\n(Imagine the screen as a grid.  Where ever you type characters, the field is\n placed)\n\nNOTE:  You cannot have a field in multi colors.\n\neg. <ESC>[44mxxx<ESC>[42mxxx<ESC>[41m...\n\n---------------------------------------------------------------------------\n                          LCD - Bulletin Creator\n                          ======================\n\nLCD_UPDATE <#> <LC_Design>\n\n\nLCD_UPDATE is the bulletin creator.  It takes the design you created and\noutputs the bulletins you specified in the PREFS screen using the node\nnumber you put in the parameters (#).\n\n\n\n---------------------------------------------------------------------------\n                                   MENUS\n                                   =====\n\nProject -\n          Clear         : Clears the current design\n          Open          : Open an existing design\n          ---------------\n          Save          : Save the current design\n          Save As...    : Save the current design to a specified filename\n          ---------------\n          Main Prefs    : Set the main preferences\n          Field Prefs   : Set the field preferences for the current design\n          Info Prefs    : Set the information prefs for the current design\n          ---------------\n          About         : Show some info\n          Quit          : Quit the editor\n\nEdit -\n          Redraw Screen : Redraw the screen\n          Toggle Insert : Toggle between Insert and overstrike mode\n          Delete Line   : Delete the line the cursor is on\n          Insert Line   : Insert a line\n          Delete To EOL : Delete all characters to the end of the line\n          ---------------\n          Filter -\n                        Reset Foreground : Resets Foreground colors\n                        Reset Background : Resets Background colors\n                        Reset Style      : Resets Style codes\n                        Reset Fields     : Resets ALL field information\n                        ----------------\n                        Reset ALL        : Resets all of the above\n\nStyle -\n          Normal           : Sets current style to Normal\n          Bold             : Sets current style to Bold\n          Italic           : Sets current style to Italic\n          Underline        : Sets current style to Underline\n\nPen Color -\n          Black            : Sets current pen color to Black\n          White            : Sets current pen color to White\n          Green            : Sets current pen color to Green\n          Yellow           : Sets current pen color to Yellow\n          Dark Blue        : Sets current pen color to Dark Blue\n          Purple           : Sets current pen color to Purple\n          Light Blue       : Sets current pen color to Light Blue\n          Red              : Sets current pen color to Red\n\nScreen Color -\n          Black            : Sets current screen color to Black\n          White            : Sets current screen color to White\n          Green            : Sets current screen color to Green\n          Yellow           : Sets current screen color to Yellow\n          Dark Blue        : Sets current screen color to Dark Blue\n          Purple           : Sets current screen color to Purple\n          Light Blue       : Sets current screen color to Light Blue\n          Red              : Sets current screen color to Red\n\nPlace Field -\n          Usernumber       : Last caller [user number]\n          Username/Handle  : Last caller [handle]\n          Location/Group   : Last caller [location]\n          Activity -    Lost Carrier      : Last caller [lost carrier ?]\n                        Uploaded          : Last caller [uploaded ?]\n                        Downloaded        : Last caller [downloaded ?]\n                        Operator Paged    : Last caller [paged sysop ?]\n                        Sysop Activity    : Last caller [sysop activity ?]\n                        Password Failed   : Last caller [password failed ?]\n                        Phone No. Failed  : Last caller [phone number failed ?]\n                        Directory Scanned : Last caller [directory scanned?]\n                        New User          : Last caller [new user ?]\n          Logon Date       : Last caller [log-on date]\n          Logon Time       : Last caller [log-on time]\n          Logoff Time      : Last caller [log-off time]\n          OnLine Time      : Last caller [time on-line]\n          Bytes Uploaded   : Last caller [bytes uploaded]\n          Bytes Downloaded : Last caller [bytes downloaded]\n          Files Uploaded   : Last caller [files uploaded]\n          Files Downloaded : Last caller [files downloaded]\n          Baud Rate        : Last caller [baud rate]\n          Node Number      : Last caller [node number]\n\nPlace Info -\n          Calls            : calls              - T/Y/TW/LW/BD/BW/T\n          Bytes Uploaded   : bytes uploaded     - T/Y/TW/LW/BD/BW/T\n          Bytes Downloaded : bytes downloaded   - T/Y/TW/LW/BD/BW/T\n          Files Uploaded   : files uploaded     - T/Y/TW/LW/BD/BW/T\n          Files Downloaded : files downloaded   - T/Y/TW/LW/BD/BW/T\n          Upload Fails     : upload fails       - T/Y/TW/LW/BD/BW/T\n          Download Fails   : download fails     - T/Y/TW/LW/BD/BW/T\n          New Users        : new users          - T/Y/TW/LW/BD/BW/T\n          Password Fails   : password fails     - T/Y/TW/LW/BD/BW/T\n          Phone Fails      : phone fails        - T/Y/TW/LW/BD/BW/T\n          Operator Pages   : operator pages     - T/Y/TW/LW/BD/BW/T\n          File Scans       : dir scans          - T/Y/TW/LW/BD/BW/T\n          Lost Carriers    : lost carriers      - T/Y/TW/LW/BD/BW/T\n          Time Used        : time used          - T/Y/TW/LW/BD/BW/T\n          Best D/L CPS     : best download cps  - T/Y/TW/LW/O\n          Best U/L CPS     : best upload cps    - T/Y/TW/LW/O\n          Worst D/L CPS    : worst download cps - T/Y/TW/LW/O\n          Worst U/L CPS    : worst upload cps   - T/Y/TW/LW/O\n          Current Date     : current date\n          Current Time     : current time\n\nKey:\n\n[T]  - Today\n[Y]  - Yesterday\n[TW] - This week\n[LW] - Last week\n[BD] - Best day\n[BW] - Best week\n[T]  - Total\n[O]  - Overall\n---------------------------------------------------------------------------\n\nHi to all these kewl doodes.\n\nSplatt, Hogster, Mok, Renegade, Reflex, Nomad, Linebacker, Metalbasher\nMoon, Shadow, JBM, Rebel, Flux, Samir, Richi, Majic Mushroom, Tea Bag,\nO.B.1., Executioner, Pot-Noodle....\n\n---------------------------------------------------------------------------\n\n  Please report all slaggings, bugs, improvements to some fairlight board\n\n---------------------------------------------------------------------------\n\n\nI am ashamed of my creation....\n\n:(\n\nIm off to hang myself...Bye\n\n','\n',char(10)),NULL,'auto-added',41494,4,0,NULL,NULL,'lcd','scan',1780048567);
INSERT INTO door_catalog VALUES('lcfile14','LCFILE14.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LCFILE14.LHA',NULL,'XIM','!!eRRoR.exe',NULL,'Big',NULL,NULL,replace('Lost Carrier File Processor by Big Boss\n','\n',char(10)),'lost.doc',replace('\n\n                             LCFILE PROCESSOR v1.4\n\nThese docs will be BRIEF as i hate writing them.  \n\nThis utility will scan the lcfiles directory of the conference that  the \nuser is AUTOREJOINING for lost carrier files.  If any are found, then it \nwill ask the user if he can name them.  If so, it will move them so that\nhe can do so.  It requires that the files be in the ''lost carrier'' state\nfor a minimum of 2 hours before letting other users name the files.   Of\ncourse, the user that named the files gets the credits for them. \n\nOk for installation - I have included my icon I use for this.  I recommend\nputting it in the syscmd drawer rather than the bbscmd drawer so that a \nuser cannot enter the door from the command line.\nCopy the file ''lost.x'' to a dir called ''doors:scan/'' and then put the icon\nin bbs:commands/syscmd/ and you should be partially setup.  Now, you must \ndo the following:\n Create a directory called ''bbs:lcfile''\n For every conference you want this door to run you must include a file named\n the conference number and it must contain a PATH to that conference.  As\n an example, if i want my amiga conference which is conference number 1 to\n be checked, you create a file called bbs:lcfile/1 and inside it is the path\n to my amiga conference which is ''bbs:amiga/'' - there should be a carriage\n return afterwards also.  I have included my conference 1 and conference 3\n files for examples.\nIf you want a message to be displayed to the user, then put a file called\n bbs:lcfile/lost.txt with the message you want to be shown.  The door will\n show this file right after the ''lost carrier v1.4'' stuff is shown.\nTo get the door to run, run it with MCI commands in one of the bull.txt''s\n in bbs: or in bbs:nodex/   The line is something like:  ~CC_LOST|\n That should run a door called ''lost''.  \n\n\nOK good luck.  That''s all the docs there are.  \n\nBIG BOSS\n','\n',char(10)),NULL,'auto-added',47318,6,0,NULL,NULL,'lcfile14','scan',1780048567);
INSERT INTO door_catalog VALUES('led_cb10','LED-CB10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LED-CB10.LHA','CrazyBull','XIM','CrazyBull',NULL,NULL,'LED','|_____.   ___________ ___|_  / LEd /X Dev. | |\_   |   \    _____//   __  \             | |/    |___/__  __|__/_   |    \fUZZ oF LEd |',replace('.-------- ------ --- -- -.____ - -- --- ---.\n|_____.   ___________ ___|_  / LEd /X Dev. |\n|\_   |   \    _____//   __  \             |\n|/    |___/__  __|__/_   |    \fUZZ oF LEd |\n/     l     /  l     /   l     \           |\n\__________/________/__________/ pRESENTs  |\n------------------------------- -  -       |\n| cRAZYbULL v1.0 bULLcREATOR fEAT.mONTHtOP |\n| uP/dOWN tOP·uSERLIStS·pERVOtOP·dIRTIEST- |\n| dUDE ONLINE·pUKE''O''METER·wANK-ALERT oN   |\n| yOUR PERVOCORNER·gOATbEARDWARNER· NOT =) |\n`------------------------------------------''\n','\n',char(10)),'CrazyBull.guide',replace('@database " · cRAZYbULL v1.o · (C) 1995 fUZZ/LiMITED eDITION · "\n@Node Main " · cRAZYbULL v1.o · (C) 1995 fUZZ/LiMITED eDITION · mAIN · "\n\n                 .____________.___________________________\n                 |    ______  |   _________   /_______   /\n                 |    ____/   |    |/   _____/_/   _____/__\n                 |     | |    |    |     |     |    |     |\n                 |_____| |_________|___________|__________|\n\n                                    Of\n\n                              lIMITED eDITION!\n\n @{"»»»»»»"  link MENU} @{"»»»»»»»»"  link MENU} @{"»[ cRAZYbULL v1.o bY fUZZ / LEd ]«"  link MENU} @{"««««««««"  link MENU} @{"««««««"  link MENU}\n\n@ENDNODE\n@Node MENU " · cRAZYbULL v1.o · (C) 1995 fUZZ/LiMITED eDITION · mENU · "\n                                         ______.\n._________.____________________._________|__   |_____.\n|    _____________   |_   __   |_______    /   |_    |\n|    |    |_  ___ ____/   _/   |/   ______/______    |\n|    |     /    |     |   |    |     |     |   |     |\n|_________/_____|     |___|____|___________|_________|\n                |    _|_____.____.____.____.   _____.\n                |    ___    |_   |    |_   |   |    |\n                |     |     |    |    |    |___|__  |______\n                |     |     |    |    |    |     |  |     |\n                |___________|_________|__________|________| vERSION 1.O\n\n                    @{"»[       lEGAL sHIT       ]«"  link DISCLAMER}\n                    @{"»[ cRAZYbULL iNTROdUCTION ]«"  link INTRODUCT}\n                    @{"»[        fEATURES        ]«"  link FEATURES}\n                    @{"»[      iNSTALLATiON      ]«"  link INSTALLATION}\n                    @{"»[          uSAGE         ]«"  link USAGE}\n                    @{"»[        gREETiNGS       ]«"  link GREETINGS}\n                    @{"»[    HOW 2 CONTACT ME!   ]«"  link HOW2CONTACTME}\n@Endnode\n@Node DISCLAMER " · cRAZYbULL v1.o · (C) 1995 fUZZ/LiMITED eDITION · dISCLAMER · "\n\n  This software is provided "as is".  No warranties are made, either\n  expressed or implied, with respect to the reliability, quality,\n  performance, or operation of this software. The use of this program is at\n  your own risk.  The author assumes no responsibility or liability for any\n  damage or losses resulting from the use of this software.\n\n@Endnode\n\n@Node INTRODUCT " · cRAZYbULL v1.o · (C) 1995 fUZZ/LiMITED eDITION · iNTROdUCTION · "\n\n Crazybull is a multibulletin util for AmiExpress Professional v3.x+\n It is written in nice clean, DOS friendly C code, so there should be\n no gurus or other bad experiences with this util.\n\n It was coded end of 94 and start of 95 and has been tested on a few\n boards since then and no troubles at all have arisen. It is a standard\n DOS util so you can run it from your logoff or just to view from the CLI\n or using any bulletin viewer for AmiExpress.\n\n@Endnode\n\n@Node FEATURES " · cRAZYbULL v1.o · (C) 1995 fUZZ/LiMITED eDITION · fEATURES · "\n\n Crazybull has a lot of different modes of outputs, 11 to be exact. These\n are as follows:\n\n Top Byte Uploaders,    Top Byte Downloaders\n Top File Uploaders,    Top File Downloaders\n Top Callers,           Top Msg Writers\n Top ULers w/month UL,  Top Month ULers w/tot UL\n Top DLers w/month DL,  Top Month DLers w/tot UL\n User List\n\n What they output should be quite obvious to see, but some explanation\n might be needed for some of the modes.\n\n Top ULers w/month UL     - Outputs a list sorted after the users total\n                            upload but also prints out the users month UL\n\n Top DLers w/month DL     - Just like the above, but with DL\n\n Top Month ULers w/tot UL - Outputs a list of this months top ULers.\n                            It also prints the users total UL\n\n Top Month DLers w/tot UL - See above but with DL\n\n Userlist                 - Not much to say here, accept that it only\n                            outputs active users (no deleted) and shows\n                            a * after the usernumber on new users.\n\n@Endnode\n\n@Node INSTALLATION " · cRAZYbULL v1.o · (C) 1995 fUZZ/LiMITED eDITION · iNSTALLATiON · "\n\n This really couldn''t be much easier, just make a directory in your doors:\n assign called ''CrazyBull'' and place CarzyBull wherever you want. The dir\n is needed for some datafiles that are needed for the month ul lists. If\n you don''t want these lists you can skip the directory and just place\n Crazybull somewhere else.\n\n If you are using a bulletin viewer that is using script files to create\n the bulletins you would write (if the door then looks for a file called\n bbs:bull/bull1.txt and you want to output mode #1, the total uploaders\n list with 30 users listed):\n\n ''doors:crazybull/crazybull 1 30 >bbs:bull/bull1.txt''\n\n This redirects the output to the file bbs:bull/bull1.txt. If you are\n running it from the CLI or at logoff you would write the same line\n or skip the >bbs:bull/bull1.txt part for screen output in the CLI.\n\n@Endnode\n\n@Node USAGE " · cRAZYbULL v1.o · (C) 1995 fUZZ/LiMITED eDITION · uSAGE · "\n\n Usage: <path>Crazybull <mode> <# users>\n\n <mode>    - Output modes 1-11\n <# users> - Number of users to output\n\n MODE 1 : Top Byte Uploaders   MODE 2 : Top Byte Downloaders\n MODE 3 : Top File Uploaders   MODE 4 : Top File Downloaders\n MODE 5 : Top Callers          MODE 6 : Top Msg Writers\n MODE 7 : Top ULers w/month    MODE 8 : Top Month ULers w/UL\n MODE 9 : Top DLers w/month    MODE 10: Top Month DLers w/UL\n MODE 11: User List\n\n ie. doors:crazybull/crazybull 3 50\n\n Would output a list of 50 users sorted after files uploaded.\n\n You can also redirect output to a file by using the > character\n\n ie. doors:crazybull/crazybull 5 50 >bbs:bull/bull5.txt\n\n If you want to save the month top results in a file you can use the\n >> characters to append to a file, using perhaps a cron to run the\n door on the last day of the month or manualy (this will be included\n in the next version of crazybull automaticly).\n\n@Endnode\n\n@Node GREETINGS " · cRAZYbULL v1.o · (C) 1995 fUZZ/LiMITED eDITION · gREETiNGS · "\n\n                            GREETINGS GOES TO\n                           ~~~~~~~~~~~~~~~~~~~\n\n         Skize/LED           - For nagging on me to release it =)\n                               and making the ascii''s!\n\n         Opium/LED           - For betatesting \n         ARAGORN/LED^3ad           - " -\n         Biztro/LED^WARGEBER       - " -\n         Dalamar/LED               - " -\n\n         All the users that have keept calling my board through periods\n         of frequent reboots =). And to all that I might have forgotten!\n\n@Endnode\n\n@Node HOW2CONTACTME " · cRAZYbULL v1.o · (C) 1995 fUZZ/LiMITED eDITION · HOW 2 CONTACT ME! · "\n\n Call me at my board INTOXICATION 2 nodes 28k8! +46-8-265322,+46-8-263536\n                                                \n You can also reach me at any Dream Chart HQ and on Serpent Hill!\n\n Contact me for bugs or ideas on new doors!\n\n@Endnode\n','\n',char(10)),NULL,'auto-added',26446,8,0,NULL,NULL,'led_cb10','scan',1780048567);
INSERT INTO door_catalog VALUES('led_dc22','LED-DC22.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LED-DC22.LHA','DC_15to22','XIM','DC_15to22',NULL,NULL,'LED','|  \/                                \/   | | NEW VERSION OF  THE DC_SPEED DOOR  THAT | | ALL  BOARDS THAT WANT TO BE PART OF THE |',replace('.--__-[ dc_Speed 2.2 - NEW VERSION ]-__---.\n|  \/                                \/   |\n| NEW VERSION OF  THE DC_SPEED DOOR  THAT |\n| ALL  BOARDS THAT WANT TO BE PART OF THE |\n| DREAMCHART  SHOULD  INSTALL!  SCRIPT TO |\n| UPDATE  OLD DATAFILES INCLUDED!  *USE!* |\n| WORRIED  ABOUT   TROJANS  AND  VIRUSES? |\n| CALL A DC HQ AND GET IT FROM US!  -FuZZ!|\n`-----------------------------------------''\n','\n',char(10)),'DC_Speed.DoC',replace('\n .--__-[ dc_Speed 2.2 - NEW VERSION ]-__---.\n |  \/                                \/   |\n | NEW VERSION OF  THE DC_SPEED DOOR  THAT |\n | ALL  BOARDS THAT WANT TO BE PART OF THE |\n | DREAMCHART  SHOULD  INSTALL!  SCRIPT TO |\n | MAKE THE INSTALLATION  EASIER INCLUDED! |\n | WORRIED  ABOUT   TROJANS  AND  VIRUSES? |\n | CALL A DC HQ AND GET IT FROM US!  -FuZZ!|\n `-----------------------------------------''\n\n\n                       DC_SPEED v2.2 by FuZZ/LED\n                      ~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nRelease info\n~~~~~~~~~~~~\nOriginal archive LED-DC22.lha\n\nFile                                 Size  Description\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nBBS/DOORS/DC/DC_Speed              12.708  Main executable, XIM door for Amix\nBBS/DOORS/DC/DC_Speed.doc          12.388  This file\nBBS/DOORS/DC/DC_Speed.info            686  Example cfg-info file\nBBS/COMMANDS/SYSCMD/EXAMINEx.info   1.049  Included Examine icon, just rename\nDC_15to22                           2.132  Converter util for old datafiles!\nInstall                             2.416  The install script, RUN!\nInstall.info                          697  Just an icon =)\nInstaller                         115.144  C=''s installer\nfile_id.diz                           396  File_id.diz for BBS''s\n\nDC_Speed v2.2 was finished on the 25-May-95 (on my birthday, hurray! =))\n\n\nWho do I blame if it destroys my HD?\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nNot me anyway! You run this door completely on your own risk!\nThis door has been tested on many boards already so there should\nbe little risk of anything going wrong! But you never know =)\n\n\nWhat is it?\n~~~~~~~~~~~\nIt is the main door for generating the stats file we need to make the\nDreamChart. This is the ALL NEW DreamChart, be ready for som treats\nin an issue soon!\nDc_Speed is an examine door for amiexpress that registers the files ULed,\nwhen they are ULed and by whom. This is done to be able to show exactly\nhow fast each board is on releases. It will apear in the Dream Chart SOON!\nIt also replaces the old DC_Init file that used to be run from your logoff.\nIt''s all in this door now. It generates all the files needed at the start\nof every month, ONCE to save speed.\n\nDC_Speed 2.2 is the new version of the DreamChart examine door. It replaces\nALL older doors like DC_Init, Dc_Collect, DC_Speed 1.5. Use the included\ninstall script orelse you''ll loose all the stats for this month sofar and\nthe datafile will for next month will be totally fucked up!\n\n\nNew featues in the DreamChart\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nThe June issue will NOT have all of the cool new charts.\nThis is simply because the necessery programing hasn''t been done yet.\n(yes, blame me =)) But some new cool charts will be included.\nThe final result will be packed with mouthwatering stuff =)\n\nSome examples:\n\n· Chart to see which board REALLY is fastest!\n· Separate speedcharts for AMIGA, PC & CONSOLE aswell!\n· Fastest trader (we''re not sure about this one, nag on us =))\n· ''Cheating'' on each board, how much extra credz is given!\n· Global charts! We''re expanding outside Sweden. This is the\n  first time the global scene has got an accurate chart!\n\n\nInstallation\n~~~~~~~~~~~\nCopy DC_Speed and DC_Speed.info to your DreamChart directory, ie Doors:DC/.\nFrom Dc_speed 2.0 and forward you can place the dreamchart in any directory\nyou want to! You *DON''T* need to put it in DOORS:DC/!\nYou can use the included installer script if you want or you can copy\nthe files manually. NOTE! This *ONLY* works if you havn''t got any old\ndatafiles you want to keep from DC_Speed 1.5!\nEdit the EXAMINEx.info and change X to the lowest number that is free\n(i.e Examine3.info). Change the tooltypes in DC_Speed.info icon.\nCheck "Tooltypes" for help.\n\nIf you were in the DreamChart before (March-95) you should remove\nthe old DC_Init from your logoff-scripts and ALL older doors!! (they don''t\ndo any harm but there''s no point running them anylonger)\n\n\nUpgrade\n~~~~~~~\nIf you''ve run an earlier version of dc_speed (v1.5) then you *HAVE* to run\nthe included installer script!! Orelse your datafile *WILL BE FUCKED UP* for\ntwo months! Sorry about this but the structure of the datafiles have been\ntotaly rewritten! Just run the included installer script and you should be\nfine. Then edit the tooltypes in the DC_Speed.info icon and change the X\nin the name of the EXAMINEx.info icon to the lowest free number.\n\n\nTooltypes\n~~~~~~~~~\nThese are the tooltypes for the DC_Speed.info icon.\nAn example icon has been included. Use it and change whatever is needed.\n\nNODES=<x>           ----> Number of NON local nodes your board has\n\nAMIGA.x=<x>         ----> Conferencenumber(s) to your AMIGA conference(s)\n                          This HAS to be the right number! We use this to\n                          check the speed on your board!\n                          x is a number from 1 to 9, if you''ve got more than\n                          one conf for AMIGA then use .1 .2 extensions etc.\n                          Check with BBS:ConfConfig.info if you aren''t sure\n                          what the correct numbers are.\n\nPC.x=<x>            ----> Same as above but for PC\n\nCONSOLE.x=<x>       ----> Same as above but for CONSOLE\n\nBOARD_OPENED=<x>    ----> The date you opened the board, in DDMMYY format\n                          i.e 26 april 93 would be 260493\n\nBOARDNAME           ----> The name you want your board to have. PLEASE\n                          don''t use ansi or non standard characters!\n                          Use the plain A-Z characters!\n\nSYSOPNAME           ----> The name of the sysop of the board. These two\n                          tooltypes can be usefull if you don''t want your\n                          proper boardname and sysopname displayed.\n                          Just write SECRET or something completely different.\n\nMINAXX              ----> OBS! OPTIONAL! Leave out if you don''t need it!\n                          Users below this tooltype will NOT be included in\n                          the dreamchart. OBS! their credz will *NOT* be\n                          counted in ANY of the charts! Usefull if you have\n                          a lot of paying users or friends calling.\n\nCOMPUTER            ----> Your computer type.\n                          ie A3000/040 18mb ram 3.4Gb HD (max 30 characters)\n\nBBSPROGRAM          ----> Your BBSProgram. ie AmiExpress Pro v4.9\n                          (max 30 characters)\n\nUSER_DATA           ----> The location of your user.data. ie BBS:User.data\n\nCheck the included icon if you still can''t figure it out or contact us\nor another sysop who has already installed the door!\n\nTo be part of the DreamChart\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nInstall the door and at the start of each month call your local (or any)\nDreamChart HQ. Current DreamChart HQ''s are Dragonlance, Intoxication,\nTotal Eclipse and Aces High in Sweden. We are setting up a few HQs in europe\naswell.\nLogin on a normal account or the special DreamChart account,\nHandle: DreamChart  PW: DreamChart. After you''ve loged on use the ''DC''\ncommand to Upload your stats file.\n\nThis file can be found in the dir that you installed Dc_Speed in and is named\nSENDME_MMYY.data. i.e the May datafile will be called SENDME_0595.data.\nFollow the onscreen help and you should be fine. If problems do accour contact\nthe sysop! Remember, we will NOT call YOU to get the datafiles!! If you''re\nnot at home then get a cosysop or someone you trust to send us the file!\nBoards that haven''t sent us the datafile before the 5th at 23:59 every month\nwill NOT be allowed to come later with them. Insted we will use an old (if\nwe''ve got one) datafile from that board.\n\nSince we''re going to measure the speed on the boards it is imperative that\nall of you have your clocks set properly. We MIGHT check this, if it isn''t\nset correctly you will be excluded from the DreamChart!! It''s allright\nif you haven''t got an internal clock and your system hangs (and the date\nis TOTALY wrong, a few years atleast). But if your clock is off by just\nan hour or a day we will view this as cheating!\nPlease make our lifes easier and try to send us the datafiles as early as\npossible, we''ve got lots of articles and so on that has to be included before\nwe release each issue!\n\n\nTroubleshooting\n~~~~~~~~~~~~~~~\nQ: The door doesn''t make the datafile at the start of each month\nA: Check that your internal clock is set properly.\n   If this doesn''t work make sure you have followed the installation\n   or upgrade information properly.\n\nQ: The door doesn''t work at all. All it does is print out a msg that\n   an error has accoured and an errorcode.\nA: Check with the errorlist in this doc and fix the problem. If you\n   can''t manage, contact a DreamChart HQ.\n   \nQ: The ''DC'' command, when I want to deliver my stats, doesn''t work.\nA: Since two different versions of dc_speed are out and our coder for\n   the collect door hasn''t had the proper time to check that it works\n   with both of them so if it doesn work, it''s probably our fault =(.\n   Attach the datafile to a msg to the sysop or make it a private UL\n   in the DreamChart conf!!\n\nIf you''ve still got you problems and the doc doesn''t help at all, feel\nfree to contact me on my board! But PLEASE read the doc first!\n\n\nERRORCODES\n~~~~~~~~~~\n100 - Unable to open icon.library version 33\n101 - Couldn''t open Amix User.data for input\n102 - Couldn''t open the PROGDIR:SENDME_MMYY.data file for output\n103 - Couldn''t open PROGDIR:DC_temp.data for output (temporary file)\n104 - Something wrong with the tooltypes or icon missing in PROGDIR:DC_SPEED.info\n105 - Couldn''t open PROGDIR:DC_Speed.data for input\n106 - Couldn''t create PROGDIR:DC_Speed.data\n107 - Couldn''t create PROGDIR:DC_Users.data\n\n\nHistory\n~~~~~~~\nversion 1.0-1.4   Beta versions only\n\nversion 1.5       First public release. Added filesize in bytes instead of Kb\n\nversion 1.6-1.9   Beta versions only\n\nversion 2.0       Fix the problems with finding the icon. Added tooltype\n                  BoardName and SysopName.\n                  You can now set the boardname and sysopname to whatever\n                  you like. Doesn''t ask amix for it anymore.\n\nversion 2.1       Extended header to include some new info and also room for\n                  more info in later releases.\n                  Added USER.data location, for boards that don''t have it in\n                  the BBS: dir, as a tooltype. Added computer as a tooltype.\n\nversion 2.2       Final (?) version of dc_Speed.\n                  Added a few more tooltypes by request and MinAxx level to\n                  be listed in the dreamchart.\n                  Completely rewritten header for the datafiles for faster\n                  processing and lower memory consumption, don''t bother, it''s\n                  only a good feature for us when we compile the chart =)\n\nWho did it?\n~~~~~~~~~~~\nFUZZ of LiMiTED EDiTION, contact me on my board.\n\nINTOXICATION #1 +46-8-265322 V.WHATEVER\n             #2 +46-8-263536 V.FC\n\n\nGreetings to..\n~~~~~~~~~~~~~~\n      Vileius - For coding all the original DreamChart doors.\n                Hope you like the way I have recoded all of them =)\n      Dalamar - The father of The DreamChart!\n                For nagging on me to complete it =)\n                And some betatesting aswell\n      Tango   - For helping me to get it going!\n                No hard feelings about the design I hope =)\n      Skize   - For the nice design (hope you all like it,\n                you know who to blame =))\n      Opium   - Betatesting\n      Ezco    - Betatesting\n      Aragorn - Betatesting\n\n\nDreamChart HQ''s\n~~~~~~~~~~~~~~~\n\nDRAGONLANCE   #1 +46-35-102075 SYSOP: DALAMAR (main DreamChart editor)\n\nINTOXICATION  #1 +46-8-265322  SYSOP: FUZZ (coder of this and other DC doors)\n              #2 +46-8-263536\n\nACES HIGH     #1 +46-410-44886 SYSOP: NORAD\n              #2 +46-410-46577\n              #3 +46-410-46358\n              #4 +46-410-45242\n              #5 +46-410-44304\n\nTOTAL ECLIPSE #1 +46-31-572545 SYSOP: ZCANDALER\n\nMore global HQs on their way. Look out for them in the next DreamChart issue!\n\nUse the special DreamChart handle for troublefree access to our boards!\n\nHandle: DreamChart  PW: DreamChart\n\nThe command to UL your stats file is ''DC'' just write it and follow the\nonscreen instructions.\n\nIf for some reason this doesn''t work, attach your stats to a mail to the\nsysop!\n\n','\n',char(10)),NULL,'auto-added',91935,3,0,NULL,NULL,'led_dc22','scan',1780048567);
INSERT INTO door_catalog VALUES('led_dcsp','LED-DCSP.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LED-DCSP.LHA','DC_Speed','XIM','DC_Speed',NULL,NULL,'LED','|   \/                                \/   | | THE NEW DREAMCHART DOOR FOR ALL /X BBS''s | | INSTALL TO BE PART OF THE DREAMCHART!!   |',replace('.---__---[ THE DREAMCHART IS BACK ]---__---.\n|   \/                                \/   |\n| THE NEW DREAMCHART DOOR FOR ALL /X BBS''s |\n| INSTALL TO BE PART OF THE DREAMCHART!!   |\n| THIS DOOR HAS TO BE INSTALLED BEFORE THE |\n| 5th AND WE HAVE TO GET YOUR DATAFILE     |\n| BEFORE 5th MAY 23:59! IF YOU ARE WORRIED |\n| ABOUT TROJANS AND VIRUSES CALL A DC HQ   |\n| AND GET IT STRAIGHT FROM US!      -FuZZ! |\n`------------------------------------------''\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                                                .------''\n             `------------------------------------------------''\n','\n',char(10)),NULL,'auto-added',20348,6,0,NULL,NULL,'led_dcsp','scan',1780048567);
INSERT INTO door_catalog VALUES('led_ul13','LED-UL13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LED-UL13.LHA',NULL,'XIM','UL-Logoff.x',NULL,NULL,'LED','__    /_____   ___________    \ /    /    /    __/__/    /    / - -- --- --. \____    /_____    /_____    /_  -liMitED! |',replace('__/\___ __ _/\________/\______\n__    /_____   ___________    \\n/    /    /    __/__/    /    / - -- --- --.\n\____    /_____    /_____    /_  -liMitED! |\n_._____ /________ /__ _____ /_/  eDitiON!- |\n ¦    \/        \/        \/               |\n |            P R E S E N T S              |\n |             UL-Logoff 1.3               |\n | A goodbye after upload door for /X 3.x+ |\n |                                  __-bIS!|\n `----------------------------------\/-----''\n','\n',char(10)),'Ul-Logoff.guide',replace('@database 00325fa0-0\n@master BBS:misc/ihs/work/Ul-Logoff.guide\n@$VER: Ul-Logoff.x 1.3 (10.12.95)\n@author "tANGO/lED^pTL"\n@(c) "1995 by tANGO/lED^pTL"\n\n@node "Main" "No title"\n\n   _/\\___ _ __/\\___/\\__________/\\___/   _/_ _ /\\________/\\______\n  __    /_____   _________   __   __    __/___   ___________    \\\n  /    /    /    /   /   /   /    /    /    /    __/__/    /    /\n  \\____    /    /___/___/   /    /\\____    /_____    /_____    /_ ____ __  __\n  _ _____ /___ /__________ /___ /________ /________ /________ /_//\n        \\/   \\/          \\/   \\/        \\/        \\/        \\/\n\n                                            /\\___\n  _ ___ _______ __/\\________/\\________/\\___/    /_ _ /\\___/\\________/\\______\n              //__   ___________    __   __    __/___   ______    ______    \\\n               \\/    __/__/    /    /    /    /    /    /    /    /    /    /\n            __ /_____    /_____    /    /\\____    /    /\\____    /____/    /_\n               _ ______ /________ /___ /________ /___ /________ /________ /_/\n                      \\/        \\/   \\/        \\/   \\/        \\/        \\/bIS\n\n                                  pRESENTS\n\n                               uL-lOGOFF v1.3\n\n                              bY tANGO/lED^pTL\n\n\n                               @{" iNTRODUCTION " link "introduction" 0}\n                               @{" rEQUIREMENTS " link "requirement" 0}\n                               @{" iNSTALLATION " link "installation" 0}\n                               @{"   hISTORY    " link "history" 0}\n                               @{"  gREETINGS   " link "greetings" 0}\n                               @{" hOW tO rEACH " link "howtoreach" 0}\n@endnode\n\n@node "introduction" "iNTRODUCTION"\n\n                                 iNTRODUCTION\n                                 ~~~~~~~~~~~~\nThis is not the first door that lets you log off after an upload... Though,\nit''s the first one that completely melts into /X. You don''t need to run it\nwith an MCI command, it replaces the U command completely... Choosing\ngoodbye after upload will really hang you up after you''ve uploaded, and\nbefore all the filechecking. If you just choose start, or use RZ you will be\nasked if you want to log off after the upload is complete. What more is\nthere to it? This is the first door I''ve seen so far that solves this\nproblem in a nice and easy way. There''s simply now reason not to run it!\n\nThis door is, like all my other doors and utils, written in C. No lame arexx\nhere... It''s fast and good looking... Simply pure quality!\n@endnode\n\n@node "requirement" "rEQUIREMENTS"\n\n                                rEQUIREMENTS\n                                ~~~~~~~~~~~~\nThis door requires you to run /X v3.x+ on an Amiga! :)\n@endnode\n\n@node "installation" "iNSTALLATION"\n\n                                iNSTALLATION\n                                ~~~~~~~~~~~~\nEverything is set up for you... Simply copy the files to the correct\ndirectories.\n\nPlease note that if you already run doors as EXAMINE, fex file_id or\ndreamchart doors, you''ll have to rename some icons. I''ve installed this door\nas EXAMINE and have moved all the other EXAMINE doors one step forward, ie\n\n   EXAMINE  -> EXAMINE1\n   EXAMINE1 -> EXAMINE2\n\nand so on... This way you will get the logoff question before any file_id''s\nare processed. It''s not needed though. You may as well run it after all the\nother EXAMINE doors. If you want to do it this way, reanme the EXAMINE icon i\nsupplied.\n\nIf you want to you can add the following to you logoff batch as well.\n\n   delete ENV:UL-Logoff.<node> QUIET\n\nIf you skip this, the door won''t ask the user if he wants to hang up or not if\nhe just called and uploaded then hanged up, called again and used RZ. If he\nused U he would get the question again. This happens because there''s no other\nway to detect if the user loged off or not.\n@endnode\n\n@node "history" "hISTORY"\n\n                                  hISTORY\n                                  ~~~~~~~\nv1.0  -  First beta version. Not realeased other than to some of my friends.\n\nv1.1  -  Added a function to check if the user had uploads to resume. If he\n         had the normal upload routine will be called. This is needed\n         because there''s no way to resume an upload if /X doesn''t do it it''s\n         way.\n         Added a function to show and check the upload space. While i was\n         beta-testing v1.0, some of my users asked if there was room on the\n         HD, so I fixed the problem.\nv1.2  -  You wasn''t able to resume an upload in the last version. This problem\n         is now fixed. The file has the same size as the old one, because it\n         was a very small lousy bug.\nv1.3  -  There was some problems when we were about to release v1.2. My HD\n         broke down, and I had supplied the wrong version to the iHS crew.\n         Therefor, that version was never released. When I finally got my\n         board back together i wanted to enhance v1.2 some before I released\n         it. Therefor this version is also featuring full length upload space,\n         like /X has. Enjoy my work!\n@endnode\n\n@node "greetings" "gREETINGS"\n\n                                 gREETINGS\n                                 ~~~~~~~~~\nI know I''m bound to forget someone if I write a long greetings list.\nTherefor I won''t do it... Feel greeted if you know me. Here are some special\nones that I want to share with you though!\n\n       Cathleen, La Fayette, Exeron & Maniac, DJ Gizmo, Christ, Abbe\n       TBB, Scroud & Melone, Rille, Rioter, Overlord, Hiway & Route66\n                              Visitor & Recall\n\nPlease forgive me if I forgot someone! :)\n@endnode\n\n@node "howtoreach" "hOW tO rEACH"\n\n                                hOW tO rEACH\n                                ~~~~~~~~~~~~\nIf you want to get in contact with me, write me a message on my board,\nInferno, on any board in the 042, 0431, 0435 or 0418 areas in sweden or on\none of the following boards,\n\n              Bitchboard, Ace of spades, Skyline, Last resort\n\nor write an e-mail to [email removed]\n@endnode\n\n','\n',char(10)),NULL,'auto-added',19257,5,0,NULL,NULL,'led_ul13','scan',1780048567);
INSERT INTO door_catalog VALUES('lep_dlc2','LEP_DLC2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LEP_DLC2.LHA',NULL,'XIM','DLCV2.0',NULL,NULL,'LEP','\_ ¬7 \____¬\____¬\____¬\____¬\_   ¬\_  | ¬7 7  |KZ7~¬7__7~¬7  7~¬7  7~¬7  7  ¡__7  !  | |  |__|  ___|  |  |    <¡  |  !___  ¡___  ¡',replace('_____ ______________________________________\n\_ ¬7 \____¬\____¬\____¬\____¬\_   ¬\_  | ¬7\n 7  |KZ7~¬7__7~¬7  7~¬7  7~¬7  7  ¡__7  !  |\n |  |__|  ___|  |  |    <¡  |  !___  ¡___  ¡\n |  ¡ ¬7  7~ ¡  ___|  ¡  7  |  ! ¬7  | ¬7  ¡\n |  !  |     |  7  !  |  |  |  !  !  |  |  !\n |_____|_____!__|  |__|__|_____!_____|_____|\n                 PRESENTS                   \n            DLC V2.0 for /X !!              \n Cool Download-Counter Tool ! Get It NOW !  \n','\n',char(10)),'DLCV2.0.DOC',replace('\n                          /X Download-Counter V2.0 Docs\n                         ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nLegal Stuff:\n~~~~~~~~~~~~\n	This tool is (C) 1994 by Metal Death/Leprosy. It may NOT be\n	distributed by some weird PD companies without the explicit\n	permission of the author. Anyway, it may be freely copied,\n	as long as no money get`s involved. The program was released\n	to the public as `MetalWare`, means, if you like and use it,\n	go ahead and send me a tape with some Death/Thrash/Funk/Heavy\n	Metal on it, preferably demos of unsigned bands, or any other\n	(real!) heavy stuff !   ~~~~~~~~~~~~~~~~~~~~~~~\n	Please don`t bore me with shit like Poison, Winger and so on 8-)\n\n	Metal Death/Leprosy\n	PO. BOX 194\n	4400 Steyr/AUSTRIA\n\nBrief Description:\n~~~~~~~~~~~~~~~~~~\n	Will count, how many times each file on your BBS got downloaded\n	and output the result to your filedir. Failed downloads will\n	be skipped automatically, thus not being counted twice.\n	Look at the example at the end of the doc !\n\nConfiguration, installation, etc...\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n	First, you will have to do some configuration stuff. Just use\n	your favourite txt-editor and create a file like this:\n\nbbs:node0/callerslog\nbbs:2/dir4\nbbs:5/dir2\n\n	Real easy, as you see...the first line tell`s DLC, where it can\n	find the callerslog for the specific node. The following lines\n	are the complete paths & names for the directories, that should\n	be processed, you can have up to 20 of these ! Just make sure, that\n	all directories, that will be processed, do have at least 2 lines\n	of file description for each file ! You can do so, by either turning\n	on SENT_BY_FILES in /X, or by using `Autosent` !\n	Now save that file anywhere under a name of your choice, e.g\n	''s:LEP-DLCN0''. Start DLC in the logoff-batch of the specific node,\n	with the config-file as argument. For this example that would be\n	''DLCV2.0 s:LEP-DLCN0''.\n	If you have more nodes, just create such config files for all other\n	nodes as well and call DLC in each logoff-batch with the corresponing\n	config file as parameter.\n	Take a look at the example-configs included !\n\nLimitations:\n~~~~~~~~~~~~\n	- Up to 20 directories are supported\n	- downloads will be counted up to 9999, that should be enough\n	  i guess 8-)\n\nCredits:\n~~~~~~~~\n	Coding & docs by:			Metal Death/Leprosy\n	Beta testing & bug reporting:	Ufo\n\n	If you should encounter some bugs or have any suggestions, or\n	if you are a good trader (hehehe) give us a ring at:\n\n                                  /X\eTal Church\n					   ~~~~~~~~~~~~~~~~\n      -------------------------------------------------------------------\n      LINE #1: +43-725-266-402   (2400-38.400 Baud - V.32bis/Zyxel 16.8!)\n      LINE #2: +43-725-280-598   (9600-38.400 Baud - V.32, USR-DUAL HST)\n      LINE #3: +43-725-268-6557  (2400-38.400 Baud - USR-HST)\n      -------------------------------------------------------------------\n\n                  _ _____ _    _ ____ ___ _ ___  _ ____    _           \n Running on:     /.\\. _//.\  /.\\__/ \_//.\\_/ /.\\_ .\  /.\          \n ~~~~~~~~~~     /  / \/ /  / /  /__     /  /   /  /_/  / /  /          \n68030/25 MHZ!  /  /    /  / /  //_/    /  /   /  //   / /  /           \n1 GIGA-BYTE!! /. /    /. / /. /__     /. /   /. / /. / /. /__          \n              \_/     \_/  \_//__\    \_/    \_/  \_/  \_//__\         \nAMI-EXPRESS _ ____  _    _    _    _    _ ____    _ ____  _    _       \n   V3.35   /.\\__/ /.\  /.\  /.\  /.\  /.\\_ .\  /.\\__/ /.\  /.\      \n          /  /    /  /_/  / /  / /  / /  /_/  / /  /    /  /_/  /      \n         /  /    /  //   / /  / /  / /  //. _/ /  /    /  //   /       \n        /. /__  /. / /. / /. /_/. / /. / \ .\ /. /__  /. / /. /        \n        \_//__\ \_/  \_/  \_//___/  \_/   \_/ \_//__\ \_/  \_/         \n                                                                       \n                   >>> SEARCHIN` FOR AN ELITE-GROUP <<<\n\n   SAINT  : UFO                                               \n   SINNERS: METAL DEATH/LEPROSY, SNOWMAN/LEPROSY\n   -------------------------------------------------------------------\n   LINE #1: +43-725-266-402   (2400-38.400 Baud - V.32bis/Zyxel 16.8!) \n   LINE #2: +43-725-280-598   (9600-38.400 Baud - V.32, USR-DUAL HST)      \n   LINE #3: +43-725-268-6557  (2400-38.400 Baud - USR-HST)             \n   -------------------------------------------------------------------\n                           [OVER 53.000 CALLS!]\n\n            "/X\ETAL CHURCH - THE AUSTRIAN WAY OF FRIENDSHIP!"\n\n\nExample:\n~~~~~~~~\n\nULIB3840.LHA P  72132  02-19-94  Unpack.library 38.40 a new WORLD RELEASE    \n      Downloads->  27            now knowing more than 130 different cruncher\n                                 s incl. DMS and Lha. Use it or you are a    \n                                 fool. Upload by Speedy, SHI!                \n                                 ----------------------------[®-ViRANiA-¯]---\n                                 Sent by: [33mVIRANIA[0m\nDMN-BAR.TXT  N  11348  02-19-94    ___________________________               \n                                 .-\_____  ¬\       ¬\______ ¬\-------------.\n                                 | /.   /   /. / /   /.  /    /             |\n                                 |//   /   // / /   //  /    / DAMIAN IN 94 |\n                                 /_______ /__/_/__ /___/___ /               |\n                                 `-----¬\/------¬\/tGø---¬\/----------------''\n                                      BARRAVENTO - THE KICKBOXER [INFO]      \n                                 Sent by: [33mVIRANIA[0m\nPDY-OSIR.DMS P 500294  02-19-94   _________________________  _______  ______ \n      Downloads->  32             \____  /___   / _  \___  \/__/  _/_/  /  / \n                                 _/  ___/ \  __/  /  /  /  /  /  /  /__   /  \n                                 \__/  \__/\  \_____/_____/__/___  /_____/RD \n                                 <----------\__/---------------/__/--------->\n                                          oSiRiS bY bOEDER sOFTWARE          \n                                 <--------------------------->>·[-m.SiNCLAiR]\n                                 Sent by: [33mVIRANIA[0m\nTRSI-ZNT.EXE N  21784  02-20-94  TRSI and Zenith present a new Crackintro    \n      Downloads->  28            [-·«-­·×­=·+*#·[ TRiNiTY ]·#*+·-·=­×·­-»·-]\n                                 Sent by: [33mTrinity[0m\nDD-COL3.TXT  N  32649  02-21-94     ___________________________________      \n      Downloads->   7             =/      /  \   /  \       /     \   |======\n                                   \  .   \   \__\   \_   _/   ___/   |____  \n                                 ==/  |\  \\   \_/   //   \\   \__|        \=\n                                  /        \\       //     \\     \   ___   \\n                                 /   ______/=\_____/=\_____/=\____/   \ |   |\n                                 \__/ D    R    E    A    M    S  |___/ |___|\n                                 +---------------------------------[WHW]----+\n                                 |               PRESENTS:                  |\n                                 |     WHIRLWIND''S 3RD ASCII COLLECTION!    |\n                                 +------------------------------------------+\n                                 ©do was here\n                                 Sent by: [33mEDO D&R*FLT[0m\nRUN68017.LZH P  30720  02-21-94  emulates an 68020 on an 68000\n      Downloads->  28            ****** SECRET AGENT <<<>>> LEPROSY ******\n                                 Sent by: [33mSECRET AGENT[0m\nAFL-A335.LHA P 167401  02-21-94             __________________________       \n      Downloads->  27                       \_________  /. ______/o  /___Sk¡n\n                                 +-----------\_/       // ___/\_//  /   /\---\n                                 Alpha Flight /___/___/___/\_\//______ / /   \n                                 -------------\___\___\___\/---\_____\/ /---+\n                                            · P r e s e n t s ·       \/     \n                                        - AMIEXPRESS V 3.35 CRACKED! -o      \n                                 ----------------------------[®-ViRANiA-¯]---\n                                 Sent by: [33mVIRANIA[0m\nCN&CD.EXE    N 182388  02-22-94     ________________________________         \n      Downloads->  39            .__\_     `\_     `\_     `\_____ `\_______.\n                                 |tGo/. /___//. _   //. /___//.  /  /MN 1994|\n                                 |  // /   /// /   /// /   ///  /  /Cyberiad|\n                                 | /_____ //__/__ //_____ //_____ /Carillion|\n                                 `------\/------\/------\/------\/----------''\n                                       THE SATURDAY NIGHT BEAVER SHOW        \n                                    >X<«»×«» [PRiZM/tRSi CANAdA] «»×«»>X<    \n                                 Sent by: [33mRevenger[0m\nCRMAN.DMS    P 154673  02-22-94  CRUNCH MANIA VER 3.9                        \n      Downloads->  36            <========================= Revenger/2KAD ==>\n                                 Sent by: [33mRevenger[0m\n','\n',char(10)),NULL,'auto-added',14476,7,0,NULL,NULL,'lep_dlc2','scan',1780048567);
INSERT INTO door_catalog VALUES('lep_pp15','LEP_PP15.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LEP_PP15.LHA',NULL,'XIM','PPTPUMV1.5',NULL,NULL,'LEP','/ \   /    \/    \/    \/    \/    \/  / \ /  /__/  /__/  /  /  /  /  /  /__/__/__/  / /  /  /  ___/  ___/  _ _/  /  /  /  /  /  /',replace('   _     ____  ____  ____  ____  ____  ____\n  / \   /    \/    \/    \/    \/    \/  / \\n /  /__/  /__/  /  /  /  /  /  /__/__/__/  /\n/  /  /  ___/  ___/  _ _/  /  /  /  /  /  /\n\__   \__   \__/  \__/  \__   \__   \__   \\n==\___/=\___/=[AC]==\___/=\___/=\___/=\___/=\n                 Presents:\n  PlayPen-to-Partupload-Mover V1.5 for /X\n   Simply the best playpenmover around !\n','\n',char(10)),'PPTPUM.guide',replace('@database PPTPUM-Documentation\n\n@master ©PPTPUM.guide\n@Remark AmigaGuide database for the ©PPTPUM Documentation\n\n@node main "©PPTPUM-DOC Contents"\n \n\n                    /X PlayPen To PartUpload Mover V1.5 Docs\n                    ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                         (C) 1994 by Metal Death/Leprosy\n\n\n	@{" Legal Stuff                         " link "Legal Stuff"}\n	@{" Brief Description                   " link "Brief Description"}\n	@{" Configuration, installation, etc... " link "Configuration, installation, etc..."}\n	@{" Limitations                         " link "Limitations"}\n	@{" Credits                             " link "Credits"}\n	@{" Support                             " link "Support"}\n	@{" Contact the Autor                   " link "Contact"}\n\n\n@endnode\n\n@node "Legal Stuff"\n\n                     /X PlayPen To PartUpload Mover V1.5 Docs\n                     ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nLegal Stuff:\n~~~~~~~~~~~~\n	This tool is (C) 1994 by @{"Metal Death/Leprosy" link "Credits"}. It may NOT be\n	distributed by some weird PD companies without the explicit\n	permission of the author. Anyway, it may be freely copied,\n	as long as no money get`s involved. The program was released\n	to the public as `MetalWare`, means, if you like and use it,\n	go ahead and send me a tape with some @{"Death/Thrash/Funk/Heavy" link "Shame"}\n	Metal on it, preferably demos of unsigned bands, or any other\n	(real!) heavy stuff !   ~~~~~~~~~~~~~~~~~~~~~~~\n	Please don`t bore me with shit like Poison, Winger and so on 8-)\n\n@endnode\n\n@node "Brief Description"\n\nBrief Description:\n~~~~~~~~~~~~~~~~~~\n	If you`re running a BBS on /X, you surely know that problem:\n	somebody pumps up tons of warez, just before he`s finished,\n	the BBS crashes and after the reboot, all those files are\n	flying around in nodeX/playpen, it`s not possible to resume them\n	or enter a description, until the sysop moves `em to the right\n	directories. This is, where ©PPTPUM comes in: it will scan all\n	your playpen dirs for files, if something is found, it will scan\n	the @{"callerslog" link "Configuration, installation, etc..."} of the correspondig node for the uploader and\n	the right conference and then move the files to the according\n	directories, ready for the user to resume.\n	Now, why use this one ? There are already tools out, that do\n	the same ? Correct, but this one is by far the best, just read\n	on, and you`ll know why !\n\n\n@endnode\n\n@node "Configuration, installation, etc..."\n\nConfiguration, installation, etc...\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n	First, you will have to do some configuration stuff. Just use\n	your favourite txt-editor ( ©Cygnus Ed, ©Edge, ©EdWard, ... )\n	and create a file like this:\n\ns:lep-np.cfg\nbbs:bbs/NewUsers/partupload/\nbbs:bbs/PublicDomain/partupload/\nbbs:bbs/Amiga/partupload/\nbbs:bbs/Sysops/partupload/\nbbs:bbs/PC/partupload/\nbbs:bbs/Requests/partupload/\nbbs:bbs/Ae-Support/partupload/\nbbs:bbs/Pics/partupload/\nbbs:bbs/Coders/partupload/\n\n	The first line has to be a path & filename of your choice, it`s\n	where ©PPTPUM will look for your node-config file, we`ll talk\n	about that later on.\n	The other lines are simply the full paths to each conference`s\n	partupload-directory. Be sure, you put them in the right order,\n	means, conference 1 first, then conference 2, ...up to conference 9.\n	Don`t forget the `/` at the end of each path !\n	Now save this file to wherever you like, this will be the main-\n	config file.\n\n	Now, you have to create another file, with information about\n	your nodes in it, this should look like that:\n\nbbs:bbs/node0/playpen/\nbbs:bbs/node0/callerslog\nbbs:bbs/node1/playpen/\nbbs:bbs/node1/callerslog\nbbs:bbs/node2/playpen/\nbbs:bbs/node2/callerslog\n\n	This would be an example for a BBS with 3 nodes.\n	Line 1 is the path of the node`s playpen dir, line 2 is the\n	path & name of the callerslog for that node, just do that for\n	all nodes you have, and you`re done. Save this, just as you wrote\n	in the first line of the main-config, e.g. in this example as\n	`s:lep-np.cfg`.\n\n	Now just put ©PPTPUM in your startup-sequence, with the path &\n	name of the main-config as an argument, e.g. PPTPUMV1.5 s:LEP-PPM.cfg\n	DO NOT put any comment in at the end of this line, the path \n	HAS to end with a RETURN, there`s no real argument-parsing !\n\n\n	That`s it for the normal stuff, ©PPTPUM will do it`s work now...\n	....BUT: have you ever seen something like that in your\n	callerslog ??\n\n**************************************************************\n02-04-94 (13:56:22) [113] MORGOTH (CONNECT 14400/ARQ/V42b) -HADES-\n	Resuming cls_ff1.dms  614878 bytes [219136]\n	Uploading ipt-cka.nfo  4934 bytes\n	Uploading ipt-cka1.dms 469983 bytes\n	Uploading ipt-cka2.dms 582783 bytes\n	Uploading ipt-cka3.dms 562510 bytes\n	Uploading ipt-cka4.dms 559318 bytes\n	Uploading sr-elan2.dms 390395 bytes\n\n\n	As you can see, there`s no information about the conference, in\n	which the upload took place in this callerslog-entry !\n	This happens, whenever a user is resuming an upload after a\n	loss carrier. Now, there would be no possibility to move the\n	files to the correct directory for any available playpen-mover !\n	But ©PPTPUM offers you another chance in such cases, it is able\n	to move files according to their extensions (.DMS, .ZIP, ...) !\n	For instance, you have an AMIGA-conf & a PC-conf: now, DMS or LHA\n	files will surely belong to the AMIGA-conf, ZIP, ARJ belongs most\n	likely to the PC-section. So you can tell ©PPTPUM, to move these\n	files to the right conferences ! To do so, you have to create\n	another file, which has to be called `Lep-PPDF.cfg` and has to\n	reside in s:\n	©PPTPUM will look for this file, if it`s found, extension-moving\n	will be on, else off. This file has to look like that:\n\n.arj5.zip5.dms2.txt6.ARJ5.ZIP5.DMS2.TXT6.lha2.LHA2\n\n	This means: ARJ and ZIP will go to conf 5, TXT will go to conf 6\n	DMS and LHA will be moved to conf 2 ! You can do this for any\n	extension & conference you like, just add it to `Lep-PPDF.cfg` !\n	Each entry must consist of the extension followed by the conference\n	to move to, e.g. `.ZOM4`, do this in lower- and uppercase !\n	Just put all these entries in ONE line, with a RETURN at the end\n	of the line. Up to 20 extensions are supported !\n	Now, ©PPTPUM will do it`s normal work, and in case, it can`t find\n	information on the correct conference, it will look for the\n	extensions and only if even this fails, the file will stay in\n	playpen !\n\n@endnode\n\n@node Limitations\n\nLimitations:\n~~~~~~~~~~~~\n	- Up to 10 nodes are supported\n	- Up to 10 conferences are supported\n	- Up to 20 extensions can be used\n\n	If there is a demand, i can extend those limitations of coz !\n\n@endnode\n\n@node Credits\n\nCredits:\n~~~~~~~~\n	Coding & docs by:		Metal Death/Leprosy\n	Guide conversion by:		Secret Agent/Leprosy\n	Beta testing & bug reporting:	Ufo\n\n\n\n	If you should encounter some bugs or have any suggestions, or\n	if you are a good trader (hehehe) give us a ring at:\n\n\n\n                                /X\eTal Church\n                                ~~~~~~~~~~~~~~\n      -------------------------------------------------------------------\n      LINE #1: +43-725-266-402   (2400-38.400 Baud - V.32bis/Zyxel 16.8!)\n      LINE #2: +43-725-280-598   (9600-38.400 Baud - V.32, USR-DUAL HST)\n      LINE #3: +43-725-268-6557  (2400-38.400 Baud - USR-HST)\n      -------------------------------------------------------------------\n\n@endnode\n\n@node Support\n _________. ._________.  __________.  _________   ____.\n|   ._.   | |.        | |          | |        .| |   .|         RUNNING ON:\n|:  |||   | ||  ______| |___    ___| |    |   :| |   ||         ~~~~~~~~~~~\n||  |||   | ||  ___|__.    |   .|    |        || |:   |____.   68030/25 MHZ\n||  | |   | |         |    |   ||    |    |   || ||        |     /X V3.32\n|___| |___| |_________|    |____|    |____|____| |_________|   1 GIGA-BYTE!!\n._________.  _________.  _________. ._________  ._________.  _________.\n|.        | |.   |    | |    |    | |.        | |         | |    |   .|\n||  ______| |:   |    | |:   |    | ||   _____| |.  ______| |    |   :|\n||  |_____. ||        | ||   |   .| ||   |      ||  |_____. |.       ||\n|         | ||   |    | |        || |    |      ||        | ||   |   ||\n|_________| |____|____| |_________| |____|      |_________| |____|____|\n          :           :             :                     :           :!RS!\n                   >>> SEARCHIN` FOR AN ELITE-GROUP <<<\n   SAINT  : UFO                                               \n   SINNERS: METAL DEATH/LEPROSY, SNOWMAN/LEPROSY\n   -------------------------------------------------------------------\n   LINE #1: +43-725-266-402   (2400-38.400 Baud - V.32bis/Zyxel 16.8!) \n   LINE #2: +43-725-280-598   (9600-38.400 Baud - V.32, USR-DUAL HST)      \n   LINE #3: +43-725-268-6557  (2400-38.400 Baud - USR-HST)             \n   -------------------------------------------------------------------\n            "/X\ETAL CHURCH - THE AUSTRIAN WAY OF FRIENDSHIP!"\n\n@endnode\n\n@node CONTACT\n\n	To contact the autor of this great tool, write to:\n\n                         -+---------------------+-\n                          | Metal Death/Leprosy |\n                          |     PO. BOX 194     |\n                          | 4400 Steyr/AUSTRIA  |\n                         -+---------------------+-\n                                    or\n\n                      call our @{" support BBS " link "support"} in Austria\n\n@endnode\n\n@node HELP\n\n	use the textbuttons to read details to the tool.\n	For information to ©Amigaguide read the manual.\n\n@endnode\n\n@node Shame\n\n\n	What?????\n\n	You don''t know Death/Thrash/Funk/Heavy Metal????!!!!....HEHEHEHE\n\n	Oh, what a shame!!!!!\n\n@endnode\n\n','\n',char(10)),NULL,'auto-added',14922,5,0,NULL,NULL,'lep_pp15','scan',1780048567);
INSERT INTO door_catalog VALUES('lfc_hp30','LFC-HP30.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LFC-HP30.LHA',NULL,'XIM','__________________/______-----------------·',NULL,NULL,'LFC','\     /___  _____/ _____/_ -·lightforce·- | /    /_  /   __/    /_   /----------------| \_______/_____|_________/  -í PRESENTS í- |',replace('__________________/______-----------------·\n\     /___  _____/ _____/_ -·lightforce·- |\n/    /_  /   __/    /_   /----------------|\n\_______/_____|_________/  -í PRESENTS í- |\n+======/=========(fts)=/==================>\n|       HellPager v3.oo for /X & DD       |\n|    Pager Door with GUI, TWIT etc etc    |\n|    (/X Version has some restrictions)   |\n|     (Read Manual! For Restrictions!)    |\n+-----------------------------------------+\n','\n',char(10)),'Help.doc',replace('                         ........ ........\n              .   .......::    ::.:     ::.....\n            ..::..::     ::    ¸¸¸ `½½,      ::\n         ¸·:::.      ½½  ::  ,½½½½½¸`½½  ½½¸ :::::     :::::::\n  ·:.      :·  ,½½½¸ ½½      ½'' ½½''  ½½, ,½½    ::::::::    ::  ::::::\n  .·::::::::  ,½½''`½½½''   ½½ ½   ¸¸  `½½,½½''  ¸   ¸  ¸      ::  ::   :\n    ·::.      ½½    `'',½'' ½½ ½¸ ½½½,  ½½½''   ½½¸ `½''`½''   ..:: .::.  :::::\n     ·::.   ,½½½½½½'' ,½'' ,½½ ½½¸`½½½ ,½½`½½½¸`½½            ::   ·::.    :\n      ·::.    `½½½   ½½ ,½½½ `½½½½½'',½½''  `½½½½''  _______ ..::... ·::··  :.\n.::::  ·::.    `½½½  ½½,½''_______       _________¡       ¡     ::  ::.::.\n   ::   ·:::::  `½½½¸ ½½''¡       ¡     !________/|       | ..  ::  .:::. ·¸\n   ::  ::··  _____________       |      ________ |       | ::..::::::·::.\n ..:: ::·   _\  _        /       |     ¡       /_!       |     ::     ·::\n.:...::·   ¡    /       /¡       |     |       __!       !____ ::  :::  ·::.\n   ·::·    |   /       /_        l_______     \___        ___/ ::  : :     ::\n    ·::.   |  /_______/  ¡       __     /        |       ¡________ : ::::: ::\n     ·::. _l____________ |       |/      ¡       |     _/       _/ :     :.·\n·::::::::.\         _ _/ |       |       |       |     \         ¡ :   .·:....\n ·::.      \             |__     |       |       |      \        |::  ::.\n  ·::.     /_          __! /_____!       |     __!       \       | ..::::.\n  ::::.      \_________\ ......!        _!_____\ |        \_     |   :::·::.\n.::··::. .....           ::  :: \_______\ ¸      /_             _!·.:: ::.:::.\n··   ·::::: ::...........::  ::.          )pL@®    \____________\       :: ·::\n   [ DATA DiViSiON ^ DECiSiON ^ FLOOD ^ MYSTiC ^ NAH-KOLOR  pOLiSh HQ! ]\n        [ AZKiNESS eASTERn eUROPe HQ! ]----[ MYSTiC PC wORLd HQ! ]\n \n     [n#1 +48 89 279966] [n#2 +48 89 359ask ] [ n#3,4 194.183.44.101 ]\n \n [BiLLY/cOR^dAT^dCN^fLD^mST] [QBA/nAH^cOR] [qLA/rYL [jACOBS/rYL] [WALEK/MST]\n                        [zIUTEK/rYL] [zIELU/mST pC]\n \n ','\n',char(10)),NULL,NULL,64538,3,0,NULL,NULL,NULL,'scan',1780048567);
INSERT INTO door_catalog VALUES('lfc_l221','LFC-L221.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LFC-L221.LHA','LZXstrip','XIM','LZXstrip',NULL,NULL,'LFC','|  | (__)\_.  /|__   _/ __/ \____  \  _/___/ | _|_|  |/ |_/ | \| |/  _/ . \ _/ _/ |  __/_ |  | \  /  | _ _  \ /   |  |  \\  \  |__ d!/',replace(' __.  __ ______.____________________________\n|  | (__)\_.  /|__   _/ __/ \____  \  _/___/\n| _|_|  |/ |_/ | \| |/  _/ . \ _/ _/ |  __/_\n|  | \  /  | _ _  \ /   |  |  \\  \  |__ d!/\n|_____\ \___ | |__/ \_  |_____/_\  \___/__/ \n-----|__|---\|_|--|_|-\_|--------\__/-------\n   LZXstrip 2.21 - aDDER/sTRIPPER/cHECKER!\n    bUG fIXED! - cHECK iT oUT - tHE bEST!\n--------------------------------------------\n','\n',char(10)),'LZXstrip.Doc',replace('\n \n \n                                  _/\_\n                                __\__/__\n                               _\      /_\n                              _\        /_\n                             _\          /_\n       ....                  \            /\n       :  :       ......         .......                   ......\n       /\ :.. . . :    :         :     :... .              :    :...\n      _/\_          _/\_.     ...: _/\_       .::::::::.    _/\_   :\n     _\__/__________\__/_______ ___\__/_______::_     ::____\__/_________\n   _|     _/    \_   ____/   _/_\___  ___/ ____:/   _/:_  \_   __/  ____/\n  _\  ... |_     /_  \__ \      \_/    \    __/:   _\ :  __/  |..\  _/ \\n__\ ..:.:.  \_    /_      \_ :   /_     \_   \_:  _\  :|   \_  :..\_    \ __\n\_\\_________/_____/_______/_|____/______/____/:  \___:|____/______/____//_/\n                                              ::......::ic!\n                                               ········\n                        ( · L I G H T F O R C E · )\n \n                 ( · F A S T E R   T H A N   L I G H T · )\n\n\n---=======================================================================---\n                         LZXstrip 2.21 (31.12.96)\n\n              cODED bY [tHE dENTIST!]/iNTRANCE''96^lIGHTfORCE\n---=======================================================================---\n\n\n  tHIS pROGRAM aND tHIS dOC iS fREELY dISTRIBUTABLE, bUT rEMAIN cOPYRIGHT\n\n                        © [tHE dENTIST!]/iNT''96^LFC\n\n---=======================================================================---\n\n\n                 __\n                .\/----------------------------------------.\n                |                                          |\n                |         -> tABLE oF cONTENTS <-          |\n                |         -----------------------          |\n                ·                                          ·\n                |     o1. iNTROdUCTION                     |\n                :     o2. hARD & sOFTwARE rEQUIREmENT      ¦\n                !     o3. iNSTALLATiON                     |\n                |     o4. uSAGE fROM sHELL                 |\n                |     o5. tHE cONFIGfILE                   |\n                |     o6. tHE bRAINfILE                    |\n                |     o7. hISTORY                          |\n                |     o8. tECHNICAL iNFOS                  |\n                |     o9. fUTURE iMPROVEmENT               |\n                |     1o. cONTACT mE                       |\n                |     11. dISCLAIMER                       |\n                |     12. cOPYrIGHT                        |\n                |     13. tHE gREETINGS                    |\n                |                                          |\n                `----------------------------------------/\''\n                                                         ¯¯\n\n                                     ......        \n                                       ··::::..    \n                                           ·::::.  \n                                            ·::::. \n                                            ::::::.\n                                           .:::::::\n                                           :::::::·\n                                          :::::::: \n                                         ::::::::  \n                                        ::::::::·  \n                            .          :::::::::   \n                            ::.      .:::::::::    \n                            ::::. ..::::::::::·    \n                            ::::::::::::::::::     \n                            :::::::::::::::::      \n                            ::::::::::::::::       \n                            :::::::::::::::        \n                            ::::::::::::::.        \n                            ::::::::::::::::.      \n                            ::::::::::::::::::.\n\n\n\n\n \n                  __ |_   __  __  __|     __ |_    __  __\n                ||  )l__,l  ''(__)(__|l__|(___l__,|(__)|  )\n             .--|--------------------------------|-----------.\n             `-----------------------------------------------''\n\n            This fine tool strips bbs advertisements (banners)\n         from lzx-archives. I think there is nothing more to say.\n\n                             The features are:\n\n      Configfile (reg. version) && 2 brainfiles (in the s directory).\n           Filename+Wildcard && CRC-32 && ZERO length stripping.\n             Testing archive and checking for advertisements.\n                   Ability to add banner(s) to archive.\n                         BBS-ANSI colors and look.\n                       I think it is also very fast.\n\n\n\n     |__  __  __  __|    __  __  __|    __  __ .--|_       __  __  __\n     |  )(__|l  ''(__|   (__||  )(__|   `--.(__)|- |__,\/\/(__|l  ''l_/_\n  .------------------------------------.__|----|------------------------.\n  |             __  __  __       __  __  ___  __  __ |_  .--------------''\n  |            l  ''l_/_(__|l__|||  ''l_/_| | )l_/_|  ||__,`--.\n  `-----------------------|----|''                   l_______|\n\n                    LZX 1.x (Evaluation or Registered)\n\n                          Kickstart 2.o or higher\n\n        (Tested on A4ooo 3oMHz and 4Mb of ram and Kickstart 39.1o6\n                              -> works fine)\n\n (Tested on A12oo Blizzard 122o/28MHz and 6Mb of ram and Kickstart 39.1o6\n                              -> works fine)\n\n\n\n                   __  __ |_   __ |  |   __ |_    __  __\n                 ||  )`--.l__,(__|l_,l_,(__|l__,|(__)|  l__\n              .-------.__|                                 |\n              `--------------------------------------------''\n\n      Copy <LZXstrip.ads> and <LZXstrip.cfg> and <LZXstrip.crc> to S:\n\n         Copy <LZXstrip> to a directory of your choice (e.g. C: )\n\n\n\n             __  __  __  __   .-- __  __  ___    __ |__  __ |  |\n        |__|`--.(__|l__|l_/_  |- l  ''(__)| | )  `--.|  |l_/_l_,l_,\n     .------.__|    .__|------|-----------------.__|----------------.\n     `--------------------------------------------------------------''\n\n  Usage: LZXstrip <archive> [BBS] [SHOW] [TEST] [CHECK] [NOCRC] [NOZERO]\n                            [ADVERT <path>] [STRIPFILE <path>]\n                                                             \n     BBS    switch: uses BBS-ANSI colors and look.\n     SHOW   switch: show checked/deleted file(s).\n     TEST   switch: test file(s) in archive.\n     CHECK  switch: show advert(s) without killing them.\n     NOCRC  switch: don''t use CRC scan mode.\n     NOZERO switch: don''t kill files with ZERO length.\n     ADVERT    key: filename/path of advert(s) to be added.\n     STRIPFILE key: path of file containing advert(s) to strip.\n                    Default: ''S:LZXstrip.ads''.\n\n\n                        Explanation of Parameters:\n                        --------------------------\n\n   BBS/S       - Uses BBS-ANSI colors and look for BBS-Usage.\n\n   SHOW/S      - Show checked and deleted files by name. If you do not\n                 use this option a message appears.\n\n                 (I.E.: Checking file(s)... 1 file(s) found\n                        Deleting file(s)... 10 file(s) deleted )\n\n   TEST/S      - Test file(s) in archive.\n\n   CHECK/S     - Show advert(s) without killing them.\n\n   NOZERO/S    - Don''t kill files with ZERO length in archive.\n\n   NOCRC/S     - You can switch of the CRC-32 scanner.\n\n   ADVERT/K    - Specify here the filename/path to the advert which should\n                 be added to the archive.\n\n                 I.E.: ADVERT=S:BBSADVERT.TXT or AD=S:BBSADVERT.TXT\n\n                       S:BBSADVERT.TXT will be added to the archive given\n                       as filename.\n\n                       ADVERT=DH2:BBS/ADVERT/\n\n                       All files in DH2:BBS/ADVERT/ will be added to the\n                       archive.\n\n                       NOTE: This option supports the ability to add empty\n                             directories.\n\n   STRIPFILE/K - Specify here the path to a ascii-file containing all\n                 filenames you want to strip off the archive. All filenames\n                 listed inside this file will be deleted from the archive.\n\n                 I.E.: #?tRS?&#?\n                       FirstOn.txt\n                       RELAESE.TXT\n\n                 If you do not specify a stripfile ...\n\n                 I.E.: STRIPFILE=S:KILLNAME or SF=S:KILLNAME\n\n                 ... the default stripfile ''S:LZXstrip.ads'' will be\n                 used automatically.\n\n\n       NOTE: If you want to use LZXstrip in DirectoryOpus just make\n                a new entry as an AmigaDOS command and type\n\n                   <c:LZXstrip {f} or c:LZXstrip {s}{o}>\n\n\n\n                |_ |__  __   __  __  __ .--  __ .-- |  __\n                l__|  )l_/_ l__,(__)|  )|- |l__||- |l_l_/_.--.\n             .--------------------------''  l___||            |\n             `-----------------------------------------------''\n\n         NOTE: It is no need of using this configfile. It is only\n                      more comfortable for bbs usage.\n\n     If you copy the configfile to S:LZXstrip.cfg all shell parameters\n         will be ignored and the parameters of the configfile will\n                                 be used.\n\n  NOTE: Only type one parameter in each line and do not exceed 7o chars.\n                 Only upper chars allowed for parameters.\n\n                       Right: ADD=BBS:adds/testadd01\n                       Wrong: ADD="BBS:adds/testadd01"\n\n\n                    ------[Start of configfile!]------\n\nLZXstrip 2.21 Configfile © 1995-1996 by [tHE dENTiST!]/iNT''96^LFC\n\n[----------------------------- 7o Chars -----------------------------]\nTEST\nNOZERO\nSHOW\nADD=BBS:adds/testadd01\nSTRIPFILE=S:TriCheck.strip\n\n                      ------[End of configfile]------\n\n\n\n                 |_ |__  __   |__  __  __   __ .-- |  __ \n                 l__|  )l_/_  |__)|  ''(__|||  )|- |l_l_/_.--.\n              .--------------------------------''            |\n              `---------------------------------------------''\n\n                          There are 2 brainfiles.\n     One for normal & wildcard stripping and one for CRC-32 stripping.\n     You can edit the brainfiles to add new banners you want to strip,\n             But put only one filename or CRC-32 in each line.\n\n                NOTE: The stripper searches CASE SENSITIVE.\n\n\n\n                 1.The CRC-32 stripfile (<LZXstrip.crc>):\n                 ----------------------------------------\n\n First of all, if you do NOT know what a CRC is then read about it in the\n    manual of LZX! This is absolutely necessary if you want to use the\n                       entire power of this option.\n      With the CRC-32 strip option you have the possibility to strip\n            bbs advertisements with random generated filenames.\n\n     To add a new CRC-32 to <LZXstrip.crc> just list the LZX-archive\n   with the option <v> instead of <l> and than add the CRC of the files\n                         you want to be stripped.\n\n   NOTE: You can only strip files that are not modified in any way, for\n     example by adding the uploader and/or time. This changes the CRC.\n\n\n         2.The normal incl. wildcard brainfile (<LZXstrip.list>):\n         --------------------------------------------------------\n\n       Examples: 1. You want to strip <YouKnow.txt> from an archive.\n                    Simply add <YouKnow.txt> to <LZXstrip.list>.\n\n                 2. You want to strip <C D S> from an archive.\n                    Right: add <"C D S"> to <LZXstrip.list>.\n                    Wrong: add  <C D S>  to <LZXstrip.list>.\n\n                 3. You want to strip all files ending with <.displayme>.\n                    Simply use wildcards and add <#?.displayme> to\n                    <LZXstrip.list>.\n\n                 4. You want to strip all files like <SoS/Q/IMT.where.FHK>.\n                    So just add <SoS/Q/#?> to <LZXstrip.list>.\n\n                 5. You want to strip <.| 5 NODES OF PURE HARDCORE |>\n                    from an archive.\n                    Right: add <.[|]5 NODES OF PURE HARDCORE [|]> or\n                               <#?5 NODES OF PURE HARDCORE#?>\n                           to  <LZXstrip.list>.\n\n                 6. You want to strip <     .nfo> from an archive.\n                    Right: add <"     .nfo"> to <LZXstrip.list>.\n                    Wrong: add  <     .nfo>  to <LZXstrip.list>.\n\n\n                      how to use wildcard characters\n                      ------------------------------\n\n   ?       matches a single character.\n   #       matches the following expression 0 or more times.\n   (ab|cd) matches any one of the items seperated by ''|''.\n   ~       negates the following expression.  it matches all strings\n           that do not match the expression (aka ~(foo) matches all\n           strings that are not exactly "foo").\n   [abc]   character class: matches any of the characters in the class.\n   [~bc]   character class: matches any of the characters not in the\n           class.\n   a-z     character range (only within character classes). \n   %       matches 0 characters always (useful in "(foo|bar|%)").\n   *       synonym for "#?", not available by default in 2.0.  available\n           as an option that can be turned on.\n\n      "expression" in the above table means either a single character\n     (ex: "#?"), or an alternation (ex: "#(ab|cd|ef)"), or a character\n                         class (ex: "#[a-za-z]").\n\n         read the amiga dos manual for more information how to use\n                          the wildcard characters\n\n\n\n                         |__   __ |_   __  __\n                         |  )|`--.l__,(__)|  ''l__|\n                      .------l___|------------.__|--.\n                      `-----------------------------''\n\n           LZXstrip 1.o && 1.o1     - Never released (only for me)\n\n           LZXstrip 1.o2 (17.o1.96) - First public release\n\n           LZXstrip 2.o  (22.o1.96) - Total rewritten code\n                                    - Speedup\n\n           LZXstrip 2.o1 (xx.yy.zz) - Never released\n\n           LZXstrip 2.o2 (o2.o2.96) - Speed improvements\n                                    - Added wildcard supporting\n\n           LZXstrip 2.o3 (o9.o3.96) - Memory bug fixed\n                                    - Now real wildcard supporting\n                                    - Optimized code\n                                    - Now only one brainfile\n\n           LZXstrip 2.1  (23.o3.96) - Optimized code\n                                    - Speed improvements\n\n           LZXstrip 2.11 (o9.o5.96) - Optimized code\n                                    - Added SHOW option\n                                    - No need for File_ID.library anymore\n\n           LZXstrip 2.2o (22.o9.96) - Added BBS option to use BBS-look\n                                    - Added TEST option for file testing\n                                    - Added CHECK option to show ads\n                                    - Added CRC-32 scanner\n                                    - Added NOZERO option to kill files\n                                      with ZERO length.\n                                    - Added ADVERT option to add banners\n                                      to archive.\n                                    - New design\n                                    - Total new code\n                                    - New documents\n\n           LZXstrip 2.21 (31.12.96) - Advert list renamed to\n                                      S:LZXstrip.ads\n                                    - Added STRIPFILE option to use your\n                                      own stripfiles\n                                    - Added configfile (reg. version)\n                                    - Fixed some bugs (Thx to Shallow)\n                                    - A little bit new designed\n\n\n\n             |_   __  __ |__  __   __  __ |      __ .--__  _____ \n             |__,l_/_(___|  )|  )|(___(__|l_,  ||  )|-(__)`--.  |\n          .-----------------------------------------''     l__|  |\n          `-----------------------------------------------------''\n               __\n              .\/------------------------------------------.\n              |                                            |\n              !                                            !\n              |      lINES iN sOURCEcODE: 354\n              ·    bYTElEN oF sOURCEcODE: 13376 bYTES      ·\n              |                                            .\n              :           tIME oF cODING: sINCE dEC''95     ¦\n              !            mUSIC sUPPORT: tECHNO & aCID &  |\n              |                           pROG. hOUSE      |\n              |                                            |\n              `------------------------------------------/\''\n                                                         ¯¯\n\n\n    .--.  |_       __  __     ___  __  __  __     __  ___  __  __ |_\n    |-|__||__,|__|l  ''l_/_  || | )|__)l  ''(__)\_/l_/_| | )l_/_|  )|__,\n .--|-----------------------|-----|-------------------------------------.\n `----------------------------------------------------------------------''\n\n                  Still working on intelligent stripping.\n\n              Do you know something? Yes? Contact the author.\n\n\n\n                   __  __  __ |_   __  __ |_     ___  __\n                  (___(__)|  )l__,(__|(___l__,  | | )(_/_\n               .-------------------------------------------.\n               `-------------------------------------------''\n\n           If you have suggestions or remarks about this program\n                      or if you find any bugs try to\n                     reach me on the following boards.\n\n                     [Blackys Kneipe] [Teutonic Place]\n                                [Fuck Shop]\n\n\n\n                     __|  __  __ |   __   ___  __  __\n                    (__||`--.(___l_,(__||| | )l_/_l  ''\n                 .-------.__|---------------------------.\n                 `--------------------------------------''\n         __\n        .\/------------------------------------------------------.\n        |                                                        !\n        !              aLL uSE iS aT yOUR oWN rISK.              ·\n        ·       nO lIABILITY oR rESPONSIBILITY iS aSSUMED.       ¦\n        |                                                        |\n        `------------------------------------------------------/\''\n                                                               ¯¯\n\n\n                      __  __  __      __   __ |__ |_\n                     (___(__)|__)l__|l  ''|(__||  )|__,--.\n                  .----------|---.__|    l___|          |\n                  `-------------------------------------''\n\n                   This program and document is freeware\n             but remain copyright by [tHE dENTIST!]/iNT''96^LFC\n\n       You are allowed to copy and spread this program and document,\n           but you are not allowed to modify it or use it in any\n        commercial production without the permission of the author.\n\n\n\n              |_  |__  __   __  __  __  __ |_    __  __  _____\n              l__,|  )(_/_ (__|l  ''(_/_(_/_l__,||  |(__|`--.  |\n           .---------------.__|                |   l___|l__|  |\n           `--------------------------------------------------''\n\n      A special thanxs to sHALLOW for bug reporting and helping me to\n                                  fix it!\n\n   .-------------------    -----------  ---    -- - +   - - -===-- -=- .\n   |                                                                   |\n   !           [lENNY dEE] ÷ [iCARUS] ÷ [lUCAS] ÷ [sHALLOW]            |\n               [lUCKY] ÷ [gREMLIN] ÷ [bLACKY] ÷ [-jOE cOOL!]           |\n   ¡         [tHALER] ÷ [nEUROdANCER] ÷ [iNTERCODE] ÷ [sUNSET]         !\n   |           [E.F.A.] ÷ [sISKO] ÷ [bBC] ÷ [bILBO bAGGINS]            :\n   |                ] jOKER [ ÷ [wENDIGO] ÷ [bRAINDEAD]\n   !                     [aLL lIGHTfORCE mEMBERS]                      .\n                                                                       ¡\n                                                                       |\n   .                      ... tO bE cONTINUED ...                      +\n   :               ... sORRY tO aLL i hAVE fORGOTTEN ...               !\n   ¡                                                                   .\n   `------------------ -- - -               - -- ----  + ------ --- ---''\n\n\n                                    __\n                                   _\/_\n                                   \/\/\n\n                       |. sIGNED [tHE dENTIST!] .|\n                     +---------------------------+- -\n                       |                           |\n         