INSERT INTO door_catalog VALUES('lfc_lsty','LFC-LSTY.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LFC-LSTY.LHA','LIQUIDSTYLER','XIM','Installer',NULL,'KLeiNDuiMPJe','LFC','|  | (__)\_.  /|__   _/ __/ \____  \  _/___/ | _|_|  |/ |_/ | \| |/  _/ . \ _/ _/ |  __/_ |  | \  /  | _ _  \ /   |  |  \\  \  |__ d!/',replace(' __.  __ ______.____________________________\n|  | (__)\_.  /|__   _/ __/ \____  \  _/___/\n| _|_|  |/ |_/ | \| |/  _/ . \ _/ _/ |  __/_\n|  | \  /  | _ _  \ /   |  |  \\  \  |__ d!/\n|_____\ \___ | |__/ \_  |_____/_\  \___/__/\n-----|__|---\|_|--|_|-\_|--------\__/-------\nLiQuiD STyLeR bY KLeiNDuiMPJe version   2.0\nThe Best /X CatStyler - /X AMIEXPRESS\n','\n',char(10)),'LiquidStyler.GUIDE',replace('@DATABASE "Default"\n@NODE "MAIN" "LiquidStyler 2.00 a REVOLUTION in Stylers"\n@NEXT "DISCLAIMER"\n@PREV "MAIN"\n@TOC "MAIN"\n             _______             _______\n      _______ )____/___________  .)     |_____ _______\n    _/      /_______\\      _   \\_|      |     \\.)     |_\n    \\      /         \\     \\     \\      _      |      _/\n     \\________________\\_____      \\     |      |______|\n                    Mo!/aL-|_______\\    |______|\n                 ___________ ____|_   __|_______ _______ ________\n                 .)      __/  _    \\. \\_       /      _//     __/___\n                 |      _/    \\     |  /      /.      \\_.    _/     |\n                 |______|___________|  \\_______|________|___________|\n                                 |      |\n                        .:( L I G H T F O R C E ):.\n\n                 .:( F A S T E R   T H A N   L I G H T ):.\n                                 |      |\n                                 |      |\n                                 |      |\n                                 |      |\n                                 |      |\n                                 |      |\n                                 |      |\n                         .:(  P R E S E N T S  ):.\n                       __________|      |__________\n                       \\                          /\n                        \\                        /\n                         \\                      /\n                          \\                    /\n                           \\                  /\n                            \\                /\n                             \\              /\n                              \\            /\n                               \\          /\n                                \\        /\n                                 \\      /\n                                  \\    /\n                                   \\  /\n                                    \\/\n   _______ ____________\n   \\_    /_\\       ___/___\n.-_/   _/   \\_  /\\_____   \\_- --- ------ -------------------------(f@nK!)-.\n| \\_____      \\/ __________/  LiQuiD STyLeR bY KLeiNDuiMPJe version  2.0  |\n`---- --\\_____/\\/------------------------ --- ----------------------------''\n\n                           .:( LiquidStyler ):.\n\n                       .:( The Best /X CatStyler ):.\n\n            .:( A DUO-Production by kLEIndUIMPJe and FUNK! ):.\n\n\n                            @{".:( Disclaimer ):." LINK "DISCLAIMER"}\n                            @{".:( Copyrights ):." LINK "COPYRIGHT"}\n                            @{".:(Introduction):." LINK "INTRO"}\n                            @{".:( What is it ):." LINK "WHATISIT"}\n                            @{".:(Installation):." LINK "INSTALLATION"}\n                            @{".:(Ansi Colours):." LINK "CSYSTEM"}\n                            @{".:(  Credits   ):." LINK "CREDITS"}\n                            @{".:(  History   ):." LINK "HISTORY"}\n                            @{".:( Contact Me ):." LINK "CONTACT"}\n                            @{".:(   Greets   ):." LINK "GREETZ"}\n\n@ENDNODE\n\n@NODE "DISCLAIMER" "Disclaimer"\n@NEXT "COPYRIGHT"\n@PREV "MAIN"\n@TOC "MAIN"\n\n                                Disclaimer\n                                ----------\nLiquidStyler is a combined tool and door package for AmiExpress.\nLiquidStyler has been fully tested by  the LS BetaTestTeam and  should not\ncause  any  harm  to   you  or   your  system ( :] )  BUT in the case that\nLiquidStyler, LSAfter or anything from the LSPackage may harm your system,\nyour family, your kids, your dog,  your dinner, your  supper, your heavily\nalcoholised terrible tasting drink, your hardfloppy, your softfloppy, your\nlightbulbs, your  television  or  ANYTHING  else  damaged,  no matter  how\nsevere or little the damage may be to whatever, kLEIndUIMPje (thats me :])\nis  NOT  responsible  and   does   not   give  any   guarantee.  Remember!\nThis   Tool/door  is  FREEWARE   and  therefore you did not pay the author\nANYTHING this frees the  author of  ANY  obligation one could put upon the\nauthor.\n\n\n@ENDNODE\n\n@NODE "COPYRIGHT" "Copyright 1996 by kLEIndUIMPJe"\n@NEXT "INTRO"\n@PREV "DISCLAIMER"\n@TOC "MAIN"\n                        Copyright 1996 by kD-cOdING\n                        ---------------------------\n\nLSAfter  and   LiquidStyler  itself    are copyright by KD-Coding,  nothing\nof the LS  Package  may     be altered  without  written  permission of the\ncopyright holder.  No fee may  be  asked for this  package  (this means the\ndocs and the programs)  without  the  written   permission of the copyright\nholder, if any fee IS asked, it may not be higher then  costprize, else  it\nshould be reported to the copyright holder. No group  other than LightForce\nis  licensed to release this package without a  written  permission of  the\ncopyright  holder,  this   permission must be hand  written and should\ncontain a written signature. The copyright holder has hereby every right to\nwithdraw  any  license  and/or  right   given  by the copyright holder. The\ncopyright holder is allowed to do whatever he wants  with his  product. The\ncopyright holder  representative of the LiquidStyler Package is known as\n                              "KLEINDUIMPJE".\n\n@ENDNODE\n\n@NODE "INTRO" "Introduction to LiquidStyler"\n@NEXT "WHATISIT"\n@PREV "COPYRIGHT"\n@TOC "MAIN"\n\n                               Introduction\n                               ------------\nLiquidStyler was  created by kLEIndUIMPJE, the idea came from FUNKI who was\nexperiencing some   real  problems  with  catstyler and  tried   some other\nstylers, they all  gave  funki problems and then he came to me, he asked me\nif I could make a new  catstyler,  so  I  started coding and after almost a\nmonth  the  first  complete   working   beta  with correct working dl-times\nextractor was finished.\n\n\n@ENDNODE\n\n@NODE "WHATISIT" "What is LiquidStyler?"\n@NEXT "INSTALLATION"\n@PREV "INTRO"\n@TOC "MAIN"\n\n                                What is it\n                                ----------\nNow, what is it and why you should you use it?\nWhat is it?\nEver wondered   how  some sysops  get  the upload info into their catalogs?\nEver wondered how some sysops get the number of times a file was downloaded\nin their catalogs? Well,   this  is done  by  a so called catalog styler. A\nvariety of stylers has been released for  /X but  most of them did not work\ncorrectly with the NUKE programs, or  just  did not add the dl-times to the\ncatalog, or sometimes they just were nasty  backdoor programs giving people\ndisabled ratios. What you have  here   is  a  100%  reliable BACKDOOR FREE!\nprogram. And believe it or not, the program can be as fast as the CatStyler\nthat was made by ByteJammer,  and don''t  mix these things, but LiquidStyler\nwas made in pure 100% E code,  CatStyler  from ByteJammer was made in ASM!.\n\n\n@ENDNODE\n\n@NODE "INSTALLATION" "Installation of LiquidStyler"\n@NEXT "CSYSTEM"\n@PREV "WHATISIT"\n@TOC "MAIN"\n\n                               Installation\n                               ------------\nFirst  of  all!  You   have  to know that with  this  program there comes a\ninstaller especially written for LS by me. It  copies  the  door and logoff\nutil, it copies the icons (config files) and it makes  the first BIN  inits\n(the first LSAFTER startup). The only thing it does NOT do is make an entry\nin the Logoff  icon/script and it uses the default config settings. If  you\nthink you want to do everything by hand, be my guest, but don''t forget  you\ncan  let this  installer  do some things  for  you   (also enable it in the\nSYSCMD/EXAMINEx.INFO).\n\nIf you don''t use the installer you have to do this first:\n\nCopy the files in the DOORS/ directory from the archive to your DOORS:\ndirectory.\n\nSince this styler consists of two separate programs you should install both\nthe programs.  The LiquidStyler   itself  is an Examine door, install it as\none, example icon is included.\nThen you should edit the LiquidStyler.info which is situated in\nDOORS:LIQUIDSTYLER/\n\nBRACKET.1=5\nBRACKET.2=5\nNODECOLOUR=7\nNAMECOLOUR=7\nTIMECOLOUR=7\nCPSCOLOUR=7\nDATECOLOUR=7\nFILECOLOUR=7\nDLSTRCOL=7\nNUMSTRCOL1=4\nNUMSTRCOL2=7\nDLTIMESLINE=2\nBACKUPDIR=DH0:T/\nULBRACKETOPEN=[\nULBRACKETCLOSE=]\nDLSTRING=D/L-TIMES\nNOANSI\nDLBRACKETOPEN=[\nDLBRACKETCLOSE=]\nULPRESET.1=1\nULPRESET.2=11\n\nBRACKET.1 is the colour number for the open bracket in the uploadinfo, \n        see below for the info on the colour system of LiquidStyler\n\nBRACKET.2 is the colour number for the close bracket of the upload info.\n\nNODECOLOUR is the colour number for node number\n\nNAMECOLOUR is the colour number for the uploader name\n\nTIMECOLOUR is the colour number for the time of uploading string\n\nCPSCOLOUR is the colour number for the cps rate string\n\nDATECOLOUR is the colour number for the date string\n\nFILECOLOUR is the colour number for the filename string\n\nDLSTRCOL is the colour number of the colour of the DLTIMESSTRING\n\nNUMSTRCOL1 is the colour number of the open bracket of the DLTIMES\n\nNUMSTRCOL2 is the colour number of the close bracket of the DLTIMES\n\nDLTIMESLINE is the line number where the DLTIMESTRING is to be placed\n\nBACKUPDIR is the directory where the BACKUP of the DIR is placed after a\n        style operation has been completed. It is ALSO the place where the\n        TEMPORARY directory is placed (which is beeing styled) so make sure\n        it has enough room.\n\nDLSTRING contains the string for the DLTIMES\n\nNOANSI is the keyword for those sysops who want no ansi codes in their\n        catalogs. Difference between this and the other tooltypes\n        is that this tooltype does not need a =blabla anything behind\n        it.\n\nULBRACKETOPEN is the OPEN bracket ({[ etc. or anything else that is put\n        in front of the NODE,USER,TIME,CPS (in other words: in front of the\n        upload info) Be sure to use just ONE char!\n\nULBRACKETCLOSE is the CLOSED bracket, sits behind the UPLOADINFO...just like\n        BRACKETOPEN , here you should also use just ONE char!\n\nDLBRACKETOPEN is the OPENED bracket for the DL-String in the catalog.\n\nDLBRACKETCLOSE is the CLOSED bracket for the DL-string\n\nULPRESET.1 is the preset for the uploader information\n        the reason for the .1 is that in future releases there will be a\n        second, third or multi line possibility in the uploader info.\n        You now can choose from one of the following presets:\n\n        (these area EXAMPLEs filled in with EXAMPLE info)\n\n    Preset  1. [Nd#.1][kLEIndUIMPJe.......][20:56:11][3000]\n\n    Preset  2. [kLEIndUIMPJe.............][20:56:39][Nd#.1]\n\n    Preset  3. [Nd#.1][kLEIndUIMPJe.................][3000]\n\n    Preset  4. [Nd#.1][08.SePTeMBeR]       [20:57:26][3000]\n\n    Preset  5. [Nd#.1][08.SePTeMBeR]LSsTYLE[20:57:49][3000]\n\n    Preset  6. [Nd#.1][20:58:19]LSsTYLE[08.SePTeMBeR][3000]\n\n    Preset  7. [kLEIndUIMPJe.......]         [08.SePTeMBeR]\n\n    Preset  8. [kLEIndUIMPJe.......]   [08.SePTeMBeR][3000]\n\n    Preset  9. [FILENAME.LHA][08.SePTeMBeR][20:57:26][3000]\n\n    Preset 10. [FILENAME.LHA][kLEIndUIMPJe..........][3000]\n\n    Preset 11. [FILENAME.LHA....]LIQUIDSTYLER[08.SePTeMBeR]\n\n    Preset 12. [FILENAME.LHA........]LIQUIDSTYLER[20:57:26]\n\nThe default (so when you don''t specify a preset also) is preset number\none. These are just examples but show how your upload info could look like.\nIn the future there may be more presets OR freely configurable but that\nis for the future.\n\nULPRESET.2 is the preset for an OPTIONAL second Uploader Info Line.\n        you may choose from the same number of presets as you can with\n        ULPRESET.1. If you put this tooltype betweebn brackets OR enter\n        a zero preset, the second line will NOT be added.\n\nIf you have done this al, then copy LSAFter anywhere you want but be sure\nto include it in your logoff script of each node.\nThe LSAfter should be installed with a NODE NUMBER behind it and HAS to be\nrun every time a user logs off because this lsafter ALSO updates the BIN\nfiles used by the examine door. LSAfter has the following syntax:\nLSAFter [NODEID] [ON/OFF]\nSo, if you put it in the logoff file of node 0 and you want the DL-TIMES to\nbe added then insert this in you logoff icon/script.:\nLSAfter 0 ON\n\nThe ON/OFF switch is for the DL-TIMES so you can switch it on or off.\n\nTIP:\nIf you DON''T want Uploadinfo but DO want dl-times, then just don''''t use the\nexamine program (so kill the EXAMINEx.INFO for example, as sysop you should\nknow what I am talking about)\nIf you DON''T want DL-TIMES added, but DO want the Uploadinfo, then DON''T\nand is say DON''T leave out the LSAfter fromt the logoff because the UploadInfo\nmight fuck up. Just put an OFF behind the lsafter. Example for node 0:\nLSAFTER 0 OFF\n\n@ENDNODE\n\n@NODE "CSYSTEM" "ColourSystem of LiquidStyler"\n@NEXT "CREDITS"\n@PREV "INSTALLATION"\n@TOC "MAIN"\n                      The LiquidStyler Colour System\n                      ------------------------------\n\nThe colour system of LS was suggested by FUNKI and Stingray in order to let\nusers of LS use it safe and without any possible bug up danger.\nThis is done by checking if the number of the colour system is valid\nand by not allowing any other codes then ansi colour codes.\nSo, in order to enable colours in your dl times string and the upload info\nstring, you ought to use one of the following numbers where a colour number\nis required:\n\nFrontGround Colours:\n\n0 - Black\n1 - Red\n2 - Green\n3 - Yellow\n4 - Blue\n5 - Purple\n6 - (equivalent to ESC[36m)\n7 - White (equivalent to ESC[0m and NOT ESC[37m)\n\nBackGround Colours:\n\n8  - Black\n9  - Red\n10 - Green\n11 - Yellow\n12 - Blue\n13 - Purple\n14 - (equivalent to ESC[46m)\n15 - White (equivalent to ESC[47m)\n\nTo be able to make a background AND a foreground different from colour, you\nmay use TWO numbers but MUST be separated with an comma.\nExample:\n15,4\nmakes a white background and a blue foreground. Do not use MORE then one comma\nthat will be ignored.\n@ENDNODE\n\n@NODE "CREDITS" "The Credits"\n@NEXT "HISTORY"\n@PREV "CSYSTEM"\n@TOC "MAIN"\n\n                                  Credits\n                                  -------\nInitial Idea\nand\nadditional\nideas       :       FUNKI\nCoding      :       kLEindUIMPje\n\nBetaTestTeam:       FUNKI           (SPACID BBS)\n                    SELECTOR        (BROTHERS BBS)\n                    kLEindUImPJE    (XFILES BBS)\n                    STINGRAY        (THE INNER CORE)\n\nFunki has been with this project from the beginning and it is to him I would\nlike to say a really big THNX! for his support and him putting up with me.\nI was sometimes a real pain in the ass when you discovered YET ANOTHER bug :)\nBut I have learned to live with bugs :) and learned to discover and fix them,\nall because of you (now, don''t blush :) ) You have done a fair piece with this\ntool, the most important piece: Create The Idea! Sometimes that is MORE important\nthan the code. You have been a big help and we will keep in touch because you will\nbe my staff member on my board :) ....\n\n@ENDNODE\n\n@NODE "HISTORY" "History of LiquidStyler"\n@NEXT "CONTACT"\n@PREV "CREDITS"\n@TOC "MAIN"\n\n                                  History\n                                  -------\n\n             LsAfter 0.00b-0.09b         (07.06.96 - 22.06.96)\n             -------------------------------------------------\n                          BetaTest Team Releases\n                             .:(NOT PUBLIC):.\n\n             LiquidStyler 0.00b-1.03b     (17.05.96 -07.06.96)\n             -------------------------------------------------\n                          BetaTest Team Releases\n                             .:(NOT PUBLIC):.\n\n             LiquidStyler 1.04b            (07.06.96-25.07.96)\n             -------------------------------------------------\n                          BetaTest Team Releases\n                             .:(NOT PUBLIC):.\n\n             LiquidStyler 2.0      LSAfter 1.0      (16.08.96)\n             -------------------------------------------------\n\n                          .:( PUBLIC RELEASE ):.\n\n\n@ENDNODE\n\n@NODE "CONTACT" "How to get in touch with us."\n@NEXT "GREETZ"\n@PREV "HISTORY"\n@TOC "MAIN"\n\n                                Contact Me\n                                ----------\nIf you want to contact me (kLEIndUIMPje) or FUNKi then you can call one of\nthe following boardz:\n\n                      AMNESIA BBS     +31\n                      XFILES BBS      +31(0)703253901\n                      BROTHERS BBS    +31\n@ENDNODE\n\n@NODE "GREETZ" "The guys that receive credit :)"\n@PREV "CONTACT"\n@TOC "MAIN"\n                              Greetings go to\n                              ---------------\n\n                                  Icarus\n                                    RKR\n                                   Lucas\n                                   Funki\n                                 Selector\n                                  Skinny\n                               Kleinduimpje\n                                   Conan\n                                  D-Sign\n                                  mERLIN!\n                                  Mogue!\n                                  FLASH!\n                                 Deskline\n                                  Voyage\n                                   Nails\n                               The Big Boss\n                                 Wildcard!\n                              The Little Boss\n                                Shai Hulud\n                                 StingRay\n                              ALL ABI MEMBERS\n\n    and alllll others I forgot...and that are plenty of people, sorry.\n@ENDNODE\n\n','\n',char(10)),NULL,'auto-added',52005,1,0,NULL,NULL,'lfc_lsty','scan',1780048567);
INSERT INTO door_catalog VALUES('lfc_sd20','LFC-SD20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LFC-SD20.LHA','SplitDir','XIM','SplitDir',NULL,'sOULtAKEr/Lfc','LFC','|  | (__)\_.  /|__   _/ __/ \____  \  _/___/ | _|_|  |/ |_/ | \| |/  _/ . \ _/ _/ |  __/_ |  | \  /  | _ _  \ /   |  |  \\  \  |__   /',replace(' __.  __ ______.____________________________\n|  | (__)\_.  /|__   _/ __/ \____  \  _/___/\n| _|_|  |/ |_/ | \| |/  _/ . \ _/ _/ |  __/_\n|  | \  /  | _ _  \ /   |  |  \\  \  |__   /\n|_____\ \___ | |__/ \_  |_____/_\  \___/__/ \n-----|__|---\|_|--|_|-\_|--------\__/-------\n|-          F/\STER TH/\N L|GHT!          -|\n| ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯ |\n|      SplitDir v2.0 By sOULtAKEr/Lfc      |\n|The ultimate /X FileDir/Cat splitting tool|\n`-----------------------[Small But Handy!]-''^# TROEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEETE #^\n','\n',char(10)),'SplitDir.guide',replace('@database SplitDir\n@$VER: SplitDir Documentation 0.1 (03-jan-97)\n@author "sOULtAKEr/Lfc/Ryl"\n@(c) "Copyright © 1997 Lightforce"\n\n@node "Main" "SplitDir V2.0 Documentation - A Lightforce Production."\n\n           ______              _______                                 \n   _______ )____/___________  .)     |_____  _______                   \n _/      /_______\\      _   \\_|      |     \\.)     |_ ·LiGhtFoRCE! ''97·\n \\      /         \\     \\     \\      _      |      _/ FAStER thAN LiGht\n  \\________________\\_____      \\     |      |______|                   \n                 Mo!/aL-|_______\\    |______|                          \n         ___________ ____|_   __|_______ _______ ________              \n         .)      __/  _    \\. \\_       /      _//     __/___           \n         |      _/    \\     |  /      /.      \\_.    _/     |          \n         |______|___________|  \\_______|________|___________|          \n                         |______|                                      \n\n                                  @{" SplitDir V2.0 " link "MainMenu" 0}\n\n                           Created by sOULtAKEr/Lfc/Ryl.\n\n@endnode\n\n@node "MainMenu" "SplitDir V2.0 Documentation - Main Menu"\n@prev "Main"\n\n           SplitDir V2.0 - A @{fg highlight}(· LiGHTFORCE ·)@{fg text} Production \n                 Developed by Soultaker/Lfc/Ryl\n\n [Topic]\n\n @{" Introduction   " link "Introduc" 0}........A little introduction.\n @{" Requirements   " link "Requirements" 0}........What will you need to use this program?\n @{" Installation   " link "Installation" 0}........How you will get this program on your system.\n @{" Usage          " link "Usage" 0}........How you will have to use this program.\n\n @{" Technical Info " link "Techinfo" 0}........For the coders/interested.\n @{" Bugs           " link "Bugs" 0}........Why don''t they create a spray for them 8).\n @{" History        " link "History" 0}........Evolution in progress\n @{" Future         " link "future?" 0}........Look into the MagicBowl of sOULtAKEr!\n @{" Contact        " link "How2contactme" 0}........Fanmail rulez!\n @{" Greetings      " link "Greetz" 0}........My friends!\n\n @{" Quit           " link "quit" 0}........Exit!\n\n@endnode\n\n@node "Introduc" "SplitDir V2.0 Documentation - Overview - A Little introduction"\n\nSysops sometimes have to cut-down the size of\ntheir FileCatalog/FileDir. Usually the reason is the lack of free mem. If a\nbig FileDir is being worked with it sometimes tends to be unhandleble by the\nsize. For example you are scanning the Filedir for a file or anything else.\nSome programs have built in systems that will load the FileDir only\npartially. Handle that part, free the mem of that part again and load the next\npart. But sometimes it takes (valuable) time to do so. Especially when it\nhappens online or through file checking.\n\nSo the sysop decides to cut down the size of the FileCatalog/Filedir,\nhe wants to use a split util but it''s very unhandy because you have to give\nthe correct line. So he loads it into a text editors, snaps one half and wants\nto place it into a new file but then discovers that the new pasted piece\nis incomplete.\n\nThats where this program comes in. It will allow the sysop to cut\nthe FileDir in 2 pieces. Divided by a date which you may choose. FileDirs\nmust be AmiExpress compatible to be able to use this program. It does it\nfast, clean and simple. It has also a special anti-reset system which will\nbackup your sourcedir FIRST before doing anything. This will guarantee that\nyou will never lose your FileDir if a crash/guru occures.\n\n                                @{" Return to MainMenu " link "Mainmenu" 0}\n\n@endnode\n\n@node "Requirements" "SplitDir V2.0 Documentation - Requirements - What will you need to use this program?"\n\nAmigaOS v2.04+ AmiExpress compatible filecatalogs/filedirs.\n\nAny Amiga.\n\nSplitDir has been tested on the following setups:\n\n                  - A1200/030-50Mhz/6Mb Ram/850Mb HD\n                  - A1200/020-14Mhz/2Mb Ram/120Mb HD\n                  - A3000/030-25Mhz/10Mb Ram/1Gig HD\n\nAnd has worked fine.\n\n                                @{" Return to MainMenu " link "Mainmenu" 0}\n@endnode\n\n@node "Installation" "SplitDir V2.0 - Installation - How you will get this program on your system."\n\nYou can copy SplitDir (and this documentation) anywhere in your\nsystem as long it can be found when you call it. Recommended C: or BBS:Utils/\nfor /X.\n\n                                @{" Return to MainMenu " link "Mainmenu" 0}\n\n@endnode\n\n@node "Usage" "SplitDir V2.0 - Usage - How you will have to use this program."\n\n@{fg highlight}[NOTE: When I say files in the FileDirs I mean the FileId.Diz,\n       Filename etc. NOT the actual file!]@{fg text}\n\n\nThe commandline arguments are SourceFileDir,DestFileDir,Date and Quiet.\n\n\nSourceFileDir - Specify here the Source FileDir. This is the FileDir\n                which will be divided.\nDestFileDir   - Specify here the Destination FileDir. This will be the\n                newly created filedir.\nDate          - Specify here the Date from which the file will be\n                divided. All files that have been uploaded earlier\n                than this date (the files above this date) will be\n                kept in the same FileDir. The other files which are\n                uploaded after this date will be placed in the new\n                in DestFileDir specified FileDir. The Date format must\n                be DD-MM-YY. (DAY-MONTH-YEAR e.g. 12-01-97)\nQuiet         - This option is a switch. It means that when you specify\n                this word in the argument line, all operations will\n                be done quietly. That means NO output will be directed\n                to the console. You may also use the >NIL: redirection\n                keyword but with this option it will be slightly\n                faster because the full progress indication system\n                will be skipped.\n\nProgress indicators are implemented in the program to allow you to\nsee what''s going on.\n\n\nA simple example:\n\n\n  9.Cyberdrive:E/Sources/System/SplitDir2.0> splitdir dir19 dir20 12-01-97\n  \n  SplitDir V2.0 By sOULtAKEr (- LiGHTFORCE DESIGN! -)\n  \n  Please wait while loading: dir19....Done..\n  Backing up dir19 to dir19.bak!\n  Searching for date: 12-01-97. Line: 12578  Found!\n  Please wait while parsing/saving to dir2. Line: 9698  Done!\n  Rewriting dir1. Line: 12578  Done!\n  Operation Successfull!\n  \n  9.Cyberdrive:E/Sources/System/SplitDir2.0> \n\n                                @{" Return to MainMenu " link "Mainmenu" 0}\n\n@endnode\n\n@node "TechInfo" "SplitDir V2.0 - Technical Info - For the coders."\n\nSplitDir has been developed with E version 3.2a. It uses asynchronous\nI/O in file loading routines for max. performance.\n\nSplitDir has been created by using E and optimizations in Assembler.\n\nThe date search routine is totally optimized for high speed. It\nonly works with /X filedirs (positions etc) and is fully hardcoded.\n\nThe following programs have been used in the process of\ndeveloping SplitDir: CygnusEditor Professional V3.5, Doscontrol V6.0,\nAmiExpress V4.8, EC V3.2a, EDBG V3.2a.\n\nDeveloped on a: A1200/030 50Mhz/6Mb Mem/850Mb Hd\n           and: A3000/030 25Mhz/10Mb Mem/1 Gig Hd (ONE EiGHT SEVEN)\n\nTested on various systems (020/030/040 etc)\n\n                                @{" Return to MainMenu " link "Mainmenu" 0}\n\n@endnode\n\n@node "Bugs" "SplitDir V2.0 Documentation - Why don''t they create a spray for them 8)."\n\nI made an earlier version but it was a big mistake. It contained a\nlot of MAJOR bugs, lousy coding and wanting a fast release. Version 2.0 is a\nlot more stable, a lot of bugs have been removed. For the people who used\nthe older version, sorry but I think this version will work better :). I\nhave removed to many bugs and haven''t written them, so I have forgot them\n(I''m writing this doc months after removing those bugs). So no bugfixlist\nthis time.\n\nAs far as I know this version is totally free of bugs but if\nyou encounter one, tell me and I''ll try to remove it as soon as possible.\n\n                                @{" Return to MainMenu " link "Mainmenu" 0}\n\n@endnode\n\n@node "history" "SplitDir V2.0 Documentation - Evolution in progress!"\n\n\n        v0.01 - Just a idea. I came on it when Whirlwind (i know him\n                very well) lost some FileDirs by cutting them with\n                a texteditor.\n        v1.0  - Worked out the idea, initial release.\n        v1.2  - Never released, some bugfixes and cosmetic changes.\n        v2.0  - Fully optimized DateSearchs routines. New size: 20% of\n                old size. 300% speed increase!\n                Removed a lot of *STUPID* bugs.\n                Enhanced Quit routine.\n                Added QUIET option in commandline args.\n                Optimized datesearch routine a litte bit more.\n                Added linebased progress indicators.\n                Added memory checking routine.\n\n                                @{" Return to MainMenu " link "Mainmenu" 0}\n\n@endnode\n\n@node "future?" "SplitDir V2.0 Documentation - Look into the MagicBowl of sOULtAKEr!"\nNot much I think, i''ve got some ideas but I don''t think they will\ntruly increase the productivity of this tool. (Like requesters etc) But if you\nhave any ideas tell me and i''ll see what I can do :).\n\n                                @{" Return to MainMenu " link "Mainmenu" 0}\n\n@endnode\n\n@node "How2contactme" "SplitDir V2.0 Documentation - Fanmail rulez!"\nTo contact me for any reason:\n\nBBS: ONE EiGHT SEVEN\n                 n1: +31-elite-know\n                 n2: +31-elite-know\n                 n3: +31-priva-te\n                 n4: TELNET\n                 n5: TELNET\n\nInternet:  Email: [email removed]\n             Irc: #amigaelite,#amigascne on FNET.\n\n                                @{" Return to MainMenu " link "Mainmenu" 0}\n\n@endnode\n\n@node "Greetz" "SplitDir V2.0 Documentation - My friends!"\nGreetings fly out to: [ALPHABETIC ORDER]\n\nApollo!,  B, Boheme, ByteJammer,  Carebear, Citruz, Clotug, Crew One,\nDazz, Dazzler, Desoto, Dunkan&Delvin, Eikeltje, Eagle, Floppy Robby,\nFlash, Funki, Hamlet, Hoppa, Hi-Tech, Hifi, Hudson Hawk, Icarus, Ice,\nIdaho, Infant, Jinx, Junk, Kleinduimpje, Kostek, Lucas, MegaFortress,\nMuad''dib,  Nails,  Newt,  Niceguy,  One,  Orlingo,  Oxidator,  Piter,\nPlastikman,  Prodigy,  Prefix,  Pyxis,  QLA,  Quazar,  Radavi,  Rick,\nRing+Ring, RKR, Scarface, Slime, Solo, Steel, Sven The Creator,  Tib,\nWild,  Wild Thing,    Whirlwind, Zinko, Ziutek,      Zoltrix.\n\n@endnode\n\n@node "quit" "SplitDir V2.0 Documentation - Exit!"\n^ There''s no way out!!\n|\n| I know what you are thinking now :). Just press that small button on\n| the top/left of this window :)\n|        `-----------------.\n`--------------------------''\n@endnode\n\n','\n',char(10)),NULL,'auto-added',17903,2,0,NULL,NULL,'lfc_sd20','scan',1780048567);
INSERT INTO door_catalog VALUES('lfc_fs20','LFC_FS20.LZX','~/Code/amiexpress_doors/Archives/AmiExpress/LFC_FS20.LZX',NULL,'XIM','STATUS',NULL,NULL,'LFC',NULL,NULL,NULL,NULL,NULL,'auto-added',6528,0,0,NULL,NULL,'lfc_fs20','scan',1780048567);
INSERT INTO door_catalog VALUES('lgb_bo16','LGB-BO16.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGB-BO16.LHA','BelchOLM','XIM','BelchOLM',NULL,'Noisy','LGB','.:________________________    /________ /     /   _    /  ______/___/        / /     /\   /   /   /   /     \  \____/',replace('                _  _ ___ ________    (-fAZ!)\n  .:________________________    /________   \n   /     /   _    /  ______/___/        /   \n  /     /\   /   /   /   /     \  \____/    \n /________\____ /________\_____/_______\    \n+- -----------\/-- ---> S!X Development <--+\n|    BelchOLM v1.6 by Noisy Belch/LOGIC    |\n| INSTANT REPLY, GLOBAL OLM, ANONYMOUS OLM |\n|   OLM node 1 2 and 4 with [OLM 4 1 2]    |\n+--> /X.info is HiSTORY <> FAME is LAME <--+\n','\n',char(10)),'BelchOLM.guide',replace('@database "BelchOLM"\n@node main "Main"\n                            __               ____\n ._________. .____________ /_/\ _____________\   \ ____________. ._________.\n |         | |             \_\/               \___\            | |         |\n |.       /\_|__    __/\________  ____________/\  /    /\______|_|_       :|\n ||    _ /  \   \___\/  \       \/\           \ \/____/  \         \ _    ||\n |:    //   /\___\   \  /\_______\ \___________\/\    \  /\_________\\    O|\n |o   . \  /.    /____\// \__   __\/   ________// \____\/. \________/ .   :|\n |.      \//    /     /.    /    ///    /     /o       //   /_____\       .|\n |        \_________ /\__________/\_________ /_______ /\_________ /        |\n |         | |     \/                      \/   __  \/         |\/        .|\n |_________| |________________________________ /\_\ ___________| |_________|\n :         : :                                 \/_/_           : :    Sk!n :\n\n                      BelchOLM v1.6 by Noisy Belch/LOGIC\n\n                                S!Express ONLY\n\n                                  @{" Features " link "features"}\n                                  @{" History  " link "history"}\n                               @{" How to Install " link "install"}\n             @{" The fastest Independent Console Only Board in Europe " link "4Ndz Console Only"}\n@endnode\n@node "Features"\n\n\n   Supports as many nodes as you want\n   OLM can be send ANONYMOUS\n   OLM all nodes at the same time\n   3 lines for your Messages\n   Supports the S!X intern OLM.message.txt routine\n   Faststart with Commandline options... Example: [OLM 1] for node 1\n   (Optional) Instant Reply (even if the sender was anonymous!!!!)\n   The Instant Reply can be generally disabled by the (lame) sysop\n\n   You will love it...\n@endnode\n\n@node "History"\n\n   0.1ß  lame\n   0.2ß  a few improvements and better design\n   0.3ß  added a scale, global and other stuff\n   0.4ß  added the Anonymous function and changed the design a bit\n   0.5ß  cosmetical changes\n   0.6ß  only a few cosmetical changes...\n   0.7ß  total re-written and optimized version\n   0.8ß  Translated from Arexx into C\n   0.9ß  WHO shows now "Using OLM" instead of "Module"\n   1.0   added hotkey at "should i.." question.. public release..\n   1.1   added a new powerful feature... INSTANT REPLY after receiving\n         an message the OLM itself will popup and you can reply automatically\n         or just press CR if you are not interested.. \n\n         EXAMPLE....\n\n         Someone poststs anonymous an OLM to you and you CAN reply.. but still\n         without knowing who he was haha...\n\n         This feature needs new commands in the bbs.cmd file...\n \n         -------------------------------- cut -----------------------------\n	 *olm      XM030doors:BelchOLM/BelchOLM\n	 *reply0   XM030doors:BelchOLM/BelchOLM\n	 *reply1   XM030doors:BelchOLM/BelchOLM\n	 *reply2   XM030doors:BelchOLM/BelchOLM\n	 *reply3   XM030doors:BelchOLM/BelchOLM\n	 *reply4   XM030doors:BelchOLM/BelchOLM\n         -------------------------------- cut -----------------------------\n\n         this is for an 5 nodes board if you have more nodes just add more\n         reply commands with the node number... reply5, reply6, reply7 ...\n   1.2   Instant Reply is now OPTIONAL... you''ll be asked.. \n   1.3   worked a bit on the Insant reply stuff again.. now the sysop can\n         disable it generally by creating or not creating a dummy file called\n\n         DOORS:BelchOLM/NOREPLY\n\n         If BelchOLM find the file the Instant reply mode is deactivated\n         Also included fina;ly somthing like word wrap...\n   1.4   A few changes in the questins and the design... also fixed the\n         shutdown bug... \n   1.5   now you can OLM node 1 2 and 4 with [OLM 4 1 2] (as example)\n         just type the nodes you want to olm in behind the command in\n         no order and it will work.. if you want to olm all nodes you\n         can still type [OLM *]\n   1.6   included optional WHO just create a dummy file called \n         DOORS:BELCHOLM/WHO and belcholm will start the who door at\n	 the beginning... that doesnt seem to work with the internal who\n	 (not my fault!!) so use belchwho for example or let it be.. eheh\n         Added AEdoor.library support.. now its SMALLER and FASTER..\n\n         This was the last update.. because im tired of releasing always\n         the same kind of doors.. and the OLM is pretty good now..\n\n         watch out for the BelchWHO final..   coming soon...\n@endnode\n@node "Install"\n\n         put the olm somewhere and add this to you bbs.cmd\n\n         -------------------------------- cut -----------------------------\n	 *olm      XM030doors:BelchOLM/BelchOLM\n	 *reply0   XM030doors:BelchOLM/BelchOLM\n	 *reply1   XM030doors:BelchOLM/BelchOLM\n	 *reply2   XM030doors:BelchOLM/BelchOLM\n	 *reply3   XM030doors:BelchOLM/BelchOLM\n	 *reply4   XM030doors:BelchOLM/BelchOLM\n         -------------------------------- cut -----------------------------\n\n         this is an example for a 5 nodes board if you have more nodes just\n         add more reply commands with the node number...\n         reply5, reply6, reply7 ...\n\n         Since version 1.3 the Sysop can disable the Instant Reply generally\n         by creating or not creating a dummy file called\n\n         DOORS:BelchOLM/NOREPLY\n\n         If BelchOLM find the file the Instant reply mode is deactivated\n@endnode\n\n@node "4Ndz Console Only"\n\n                                     ___ _ _ _ __ _ __ _____\n                                    /\__\\n                  _   _ _ __ ____ __\/__/\n                                                                 ·aBn/fAZ!·\n                                                      ______ _____\n     _________  ________  _____ _____________________/   __/_  __/_________\n    _\___    /__\___   /_/____/_\    __________     /    ___/  ______     /\n   /    /     /    /    /     /  \      \/    /    /     /     /    /    /\n  /    /     /         /     /          /    _____/_    /_    /_   _____/_\n /____/     /_________/     /__________/___________/_____/_____/_________/\n  .  /______\        /_____/                                             :\n  |                                                                      |\n  | ...the fastest four nodes Independent Console only board in Europe.. |\n  |                                                                      !\n  |+            +49-52X-aSK-4iT -> USRobotics with Ringdown              o\n :¡.            +49-X24-fAST!   -> Euro ISDN with Ringdown!              ¡\n  |                                                                      |\n  |                -*- Sysop: Noisy Belch   Nup: AsK -*-                 |\n !|_____________________________________________________________________!|.\n ::::                                                                    !\n@next "main"\n@endnode\n','\n',char(10)),NULL,'auto-added',26891,1,0,NULL,NULL,'lgb_bo16','scan',1780048567);
INSERT INTO door_catalog VALUES('lgc_bb02','LGC-BB02.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGC-BB02.LHA',NULL,'XIM','_  _ ___ ________    (-fAZ!)',NULL,'Noisy','LGC','.:________________________    /________ /     /   _    /  ______/___/        / /     /\   /   /   /   /     \  \____/',replace('                _  _ ___ ________    (-fAZ!)\n  .:________________________    /________   \n   /     /   _    /  ______/___/        /   \n  /     /\   /   /   /   /     \  \____/    \n /________\____ /________\_____/_______\    \n+- -----------\/-- ---> Forget /X.info! <--+\n|    BelchBULL v0.2 by Noisy Belch/LOGIC   |\n|            A WORLD REVOLUTION            |\n|  Create your BULLETINS with ANIMATIONS!  |\n+--> ANOTHER REASON to get S!Xpress NOW <--+\n','\n',char(10)),'uzi.txt',replace('                                            .---------------------------.\n    _______.-----------------._______/|     |     4NODEZ  RiNGDOWN      |\n    \_     |     .------     |________|.....| 73 GiG OF AMiGA CoNSoLE PC|\n   .:|     |     |     ______|        |:::::|  uZiSUiCiDE.sERVEBBS.ORG  |\n  .::|     |     |     |     |        |-----+-----.      TELNET         |\n .:::|           |     |     |       :|     |     |                     |\n.::::\___________|___________|________|     `-----+---------------------''\n:::::::::::::::::|                                | 24HR 7DAY STATiC iP! \n_________________|___________/|__________________/|______________________\n\_     ______    |     _______|          |_____________      _/    _____/\n_|_____    |     |     |      |    |_____|        |   |      |     ___|_ \n|     |    |     |     |      |    |     |        |   |      |     |    |\n|     |    |     |     |     :|          |       :|   |      |     |    |\n|__________|_____|_____|______|__________|________|__________|__________|\n:::::::::::::::::|            |                                         |\n`::::::::::::::::|            |ALWAYS THE LATEST VERSION oF AMi-EXPRESS