INSERT INTO door_catalog VALUES('lgc_bb03','LGC-BB03.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGC-BB03.LHA','ByeByeBELCH','XIM','ByeByeBELCH',NULL,'Noisy','LGC','.-» l__,|__|l__||l__'' S!X Development_\/_«-. |--------------''---------------------\/\/--| |                                          :',replace('    .    __  __ . __                  __    \n.-» l__,|__|l__||l__'' S!X Development_\/_«-.\n|--------------''---------------------\/\/--|\n|                                          :\n|   ByeByeBELCH v.3 by Noisy Belch/LOGIC   |\n|            (S!X v0.39o4+ ONLY)           |\n|                                          |\n|       KICK callers on OTHER nodes        |\n:                                          |\n`------------------------------------------''\n','\n',char(10)),'ByeByeBELCH.guide',replace('@database "ByeByeBELCH"\n@node main "Main"\n                            __               ____\n ._________. .____________ /_/\ _____________\   \ ____________. ._________.\n |         | |             \_\/               \___\            | |         |\n |.       /\_|__    __/\________  ____________/\  /    /\______|_|_       :|\n ||    _ /  \   \___\/  \       \/\           \ \/____/  \         \ _    ||\n |:    //   /\___\   \  /\_______\ \___________\/\    \  /\_________\\    O|\n |o   . \  /.    /____\// \__   __\/   ________// \____\/. \________/ .   :|\n |.      \//    /     /.    /    ///    /     /o       //   /_____\       .|\n |        \_________ /\__________/\_________ /_______ /\_________ /        |\n |         | |     \/                      \/   __  \/         |\/        .|\n |_________| |________________________________ /\_\ ___________| |_________|\n :         : :                                 \/_/_           : :    Sk!n :\n\n                     ByeByeBELCH v.3 by Noisy Belch/LOGIC\n                              (S!X v0.39o4+ ONLY)\n                                    \n                          KICK callers on OTHER nodes\n\n\n                                  @{" Features " link "features"}\n                                  @{" History  " link "history"}\n                               @{" How to Install " link "install"}\n             @{" The fastest Independent Console Only Board in Europe " link "4Ndz Console Only"}\n@endnode\n@node "Features"\n\n\n   Kick lamers and make place for Couriers\n   Soon (propably next weekend) with build-in node reserver and other crap\n   like a config file where you can put in handles of the users.. hmm\n   because it still works only with access level limitation.. sorry\n\n@endnode\n\n@node "History"\n\n   0.1ß  Requested by Dragon Avenger\n   0.2   first public release... pretty selfexplaining\n   0.3   included [BYE 1 5 3 2] option\n\n@endnode\n@node "Install"\n\n   Put it somewhere and give it the command [BYE] in the BBS.CMD\n\n   or use the example BBS.CMD file...\n\n\n@endnode\n\n@node "4Ndz Console Only"\n\n\n\n\n\n\n\n\n\n                   __ _/\/\__  __  ____/\____/\______/\____/\\n                  /  \  /    \/  \/  ___/  ___/   _   _/ ___/\n                 /      \  |  \   \___  \  _)_|   \   \  _)_\n                 \__\___/_____/___/_____/_____)___/___/_____)nb\n\n             The FASTEST Independent Console Only Board in EUROPE\n\n                        4 Nodes USRobotics and EuroISDN\n\n                             Much OLD stuff ONLINE\n\n@next "main"\n@endnode\n','\n',char(10)),NULL,'auto-added',27019,2,0,NULL,NULL,'lgc_bb03','scan',1780048567);
INSERT INTO door_catalog VALUES('lgc_bj07','LGC-BJ07.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGC-BJ07.LHA','BelchJOIN','XIM','BelchJOIN',NULL,'Noisy','LGC','.:________________________    /________ /     /   _    /  ______/___/        / /     /\   /   /   /   /     \  \____/',replace('                _  _ ___ ________    (-fAZ!)\n  .:________________________    /________   \n   /     /   _    /  ______/___/        /   \n  /     /\   /   /   /   /     \  \____/    \n /________\____ /________\_____/_______\    \n+- -----------\/-- ---> S!X Development <--+\n|    BelchJOIN v0.7 by Noisy Belch/LOGIC   |\n|       CIRCLEJOIN, JUMPJOIN and MORE      |\n+--> /X.info is HiSTORY <> FAME is LAME <--+\n','\n',char(10)),'BelchJOIN.guide',replace('@database "BelchJOIN"\n@node main "Main"\n                            __               ____\n ._________. .____________ /_/\ _____________\   \ ____________. ._________.\n |         | |             \_\/               \___\            | |         |\n |.       /\_|__    __/\________  ____________/\  /    /\______|_|_       :|\n ||    _ /  \   \___\/  \       \/\           \ \/____/  \         \ _    ||\n |:    //   /\___\   \  /\_______\ \___________\/\    \  /\_________\\    O|\n |o   . \  /.    /____\// \__   __\/   ________// \____\/. \________/ .   :|\n |.      \//    /     /.    /    ///    /     /o       //   /_____\       .|\n |        \_________ /\__________/\_________ /_______ /\_________ /        |\n |         | |     \/                      \/   __  \/         |\/        .|\n |_________| |________________________________ /\_\ ___________| |_________|\n :         : :                                 \/_/_           : :    Sk!n :\n\n                      BelchJOIN v0.7 by Noisy Belch/LOGIC\n                                         \n                                S!Express ONLY\n\n                                  @{" Features " link "features"}\n                                  @{" History  " link "history"}\n                               @{" How to Install " link "install"}\n             @{" The fastest Independent Console Only Board in Europe " link "4Ndz Console Only"}\n\n\n\n@endnode\n@node "Features"\n\n   Join with > from the last conference into the first\n   Join with < from the first conference into the last\n\n   Jump with >> from anywhere to the last conference\n   Jump with << from anywhere to the first conference\n\n   Jump with  > 2 two confs forward\n   Jump with  < 2 two confs backward\n\n   Jump with  > 3 three confs forward\n   Jump with  < 3 three confs backward\n\n   ReJoin a conference with RJ  ... hehe.. dunno.. but might be useful\n                                                               for someone\n   If you have S!X lower than v0.39p then this wont work with\n   relative confs ON\n\n@endnode\n@node "History"\n\n   0.1ß  lame\n   0.2ß  Different Bugs fixed\n   0.3ß  Translated from Arexx into C\n   0.4   Updated to 25 Conferences support\n   0.5   started to code the RELATIVE_CONFERENCES version\n   0.6   removed the lame shutdown bug\n   0.7   Added AEDoor.library support.. now its smaller and faster...\n\n         If you have S!X lower than v0.39p then belchjoin wont work with\n         relative confs ON\n@endnode\n@node "Install"..\n\n*>        XM010doors:belchjoin/belchjoin\n*<        XM010doors:belchjoin/belchjoin\n*>>       XM010doors:belchjoin/belchjoin\n*<<       XM010doors:belchjoin/belchjoin\n*rj       XM010doors:belchjoin/belchjoin\n\nthis is an example BBS.CMD\n\nJust check it out.. you will like it.. for sure..\n\n@endnode\n\n@node "4Ndz Console Only"\n\n                                     ___ _ _ _ __ _ __ _____\n                                    /\__\\n                  _   _ _ __ ____ __\/__/\n                                                                 ·aBn/fAZ!·\n                                                      ______ _____\n     _________  ________  _____ _____________________/   __/_  __/_________\n    _\___    /__\___   /_/____/_\    __________     /    ___/  ______     /\n   /    /     /    /    /     /  \      \/    /    /     /     /    /    /\n  /    /     /         /     /          /    _____/_    /_    /_   _____/_\n /____/     /_________/     /__________/___________/_____/_____/_________/\n  .  /______\        /_____/                                             :\n  |                                                                      |\n  | ...the fastest four nodes Independent Console only board in Europe.. |\n  |                                                                      !\n  |+            +49-52X-aSK-4iT -> USRobotics with Ringdown              o\n :¡.            +49-X24-fAST!   -> Euro ISDN with Ringdown!              ¡\n  |                                                                      |\n  |                -*- Sysop: Noisy Belch   Nup: AsK -*-                 |\n !|_____________________________________________________________________!|.\n ::::                                                                    !\n@next "main"\n@endnode\n','\n',char(10)),NULL,'auto-added',26998,5,0,NULL,NULL,'lgc_bj07','scan',1780048567);
INSERT INTO door_catalog VALUES('lgc_bj09','LGC-BJ09.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGC-BJ09.LHA','BelchJOIN','XIM','BelchJOIN',NULL,'Noisy','LGC','.:________________________    /________ /     /   _    /  ______/___/        / /     /\   /   /   /   /     \  \____/',replace('                _  _ ___ ________    (-fAZ!)\n  .:________________________    /________   \n   /     /   _    /  ______/___/        /   \n  /     /\   /   /   /   /     \  \____/    \n /________\____ /________\_____/_______\    \n+- -----------\/-- ---> S!X Development <--+\n|    BelchJOIN v0.9 by Noisy Belch/LOGIC   |\n|            A WORLD REVOLUTION            |\n|Create your OWN JOIN MENU with ANIMATIONS!|\n+--> /X.info is HiSTORY <> FAME is LAME <--+\n','\n',char(10)),'BelchJOIN.guide',replace('@database "BelchJOIN"\n@node main "Main"\n                            __               ____\n ._________. .____________ /_/\ _____________\   \ ____________. ._________.\n |         | |             \_\/               \___\            | |         |\n |.       /\_|__    __/\________  ____________/\  /    /\______|_|_       :|\n ||    _ /  \   \___\/  \       \/\           \ \/____/  \         \ _    ||\n |:    //   /\___\   \  /\_______\ \___________\/\    \  /\_________\\    O|\n |o   . \  /.    /____\// \__   __\/   ________// \____\/. \________/ .   :|\n |.      \//    /     /.    /    ///    /     /o       //   /_____\       .|\n |        \_________ /\__________/\_________ /_______ /\_________ /        |\n |         | |     \/                      \/   __  \/         |\/        .|\n |_________| |________________________________ /\_\ ___________| |_________|\n :         : :                                 \/_/_           : :    Sk!n :\n\n                      BelchJOIN v0.9 by Noisy Belch/LOGIC\n                                         \n                                S!Express ONLY\n\n                                  @{" Features " link "features"}\n                               @{" Too slow Menues? " link "Background"}\n                                  @{" History  " link "history"}\n                               @{" How to Install " link "install"}\n             @{" The fastest Independent Console Only Board in Europe " link "4Ndz Console Only"}\n\n\n\n@endnode\n@node "Features"\n\n   This JoinDoor works with FRAMES it can animate a menu like DPaint ... there\n   is no limitation ... you can do what you want.. every confernce has its\n   own frame.. and you can select it with the cursor keys.. and it is now\n   as fast as any other lame joindoor...\n\n   for example you can paint a little landscape with amiga and ibm logos on\n   it which scrolls left right or up and down and in that way you selevct \n   a conference... Or you can let it look like the lame menu output of other\n   well known joindoors...\n\n   every frame with the file name\n\n   BelchJOIN.frame(x) is default for all users with any coonferwnce access...\n\n   but it is also possible to name a frame\n\n   XXXX_XX__.frame(x) for users which shouldnt see the other\n   coonference names (RELATIVE_CONFERENCES)\n\n   IMPORTANT: XXXX_XX__.frame(x)\n              ^^^^^^^^^\n              TThis is the access name how he stands in the ACCESS EDITOR!!\n              If you have 26 conferences turned on *DONT* use\n              XXXXX_____XXXXX_X_X_XXXXX.frame(x) as name!!!! use\n              the AREANAME which stands in the ACCESSEDITOR\n\n   eheh ok.. when you''ve made your own menu... someone may say that it is @{" Too slow! " link "Background"}\n\n   Expect this kewl [J] command this door has much more powerful\n   options like  > 2 or > 3 or < 2 (like in /X.info) or RJ (rejoin)\n   or >> << (jump from anywhere to the last/first conf)\n\n   If you have S!X lower than v0.39p then this wont work with\n   RELATIVE_CONFERENCES ON\n\n   I KNOW THAT THIS DOOR IS VERY COMPLEX AND NOT EASY TO INSTALL ... BUT\n   TAKE A LOOK AT THE EXAMPLES AND YOU WILL LOVE IT... MAKE YOUR OWN SHIT!!\n\n\n@endnode\n@node "History"\n\n   0.1ß  lame\n   0.2ß  Different Bugs fixed\n   0.3ß  Translated from Arexx into C\n   0.4   Updated to 25 Conferences support\n   0.5   started to code the RELATIVE_CONFERENCES version\n   0.6   removed the lame shutdown bug\n   0.7   Added AEDoor.library support.. now its smaller and faster...\n\n         If you have S!X lower than v0.39p then belchjoin wont work with\n         relative confs ON\n   0.8ß  added the [j] comand\n   0.9   added the possibility to do (areaname).frame1 eeh..\n         optimized the text output ... should be faster now.. release..\n\n@endnode\n@node "Install"..\n\n*>        XM010doors:belchjoin/belchjoin\n*<        XM010doors:belchjoin/belchjoin\n*>>       XM010doors:belchjoin/belchjoin\n*<<       XM010doors:belchjoin/belchjoin\n*rj       XM010doors:belchjoin/belchjoin\n*j        XM010doors:belchjoin/belchjoin\n\nthis is an example BBS.CMD\n\nJust check it out.. you will like it.. for sure..\n\n@endnode\n@node "Background"\n\n   That is absolutely NO problem!!!!\n \n   You have the possibilitie to create a MAIN menu background called \n\n   DOORS:BelchJOIN/BelchJOIN.background\n\n   or\n\n   DOORS:BelchJOIN/(Areaname).background\n\n   which will always be displyed.. so that you have only to put the\n   CHANGES over it with the well known ESC[y;xH commands\n\n   That will speed it up for sure.. eheh...\n\n   I KNOW THAT THIS DOOR IS VERY COMPLEX AND NOT EASY TO INSTALL ... BUT\n   TAKE A LOOK AT THE EXAMPLES AND YOU WILL LOVE IT... MAKE YOUR OWN SHIT!!\n\n@endnode\n\n@node "4Ndz Console Only"\n\n         _________________________________________   _____   _________\n        _\      _\      _\__\       _\    ___\   (___\   (___\    ___/\n        \_   |  \_   |  \_   \   `--\_   _/_\_   _/_\_   _/_\_   _/__\n         |   |   |   |   |   /---,   |   l   |   l   |   l   |   l   :.\n         l___|   l_______l__/l___    l___    l___    l___    l___  ..::\n             `---''               `---''   `---''   `---''   `---''   `-2F·:\n\n           Fastest 4 Nodes Independent Console Only Board in Europe\n           USRobotics and ISDN                   Sysop: Noisy Belch\n\n@next "main"\n@endnode\n','\n',char(10)),NULL,'auto-added',23217,6,0,NULL,NULL,'lgc_bj09','scan',1780048567);
INSERT INTO door_catalog VALUES('lgc_bl05','LGC-BL05.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGC-BL05.LHA','BelchLIST','XIM','BelchLIST',NULL,'Noisy','LGC','.-» l__,|__|l__||l__'' S!X Development_\/_«-. |--------------''---------------------\/\/--| |                                          :',replace('    .    __  __ . __                  __    \n.-» l__,|__|l__||l__'' S!X Development_\/_«-.\n|--------------''---------------------\/\/--|\n|                                          :\n|    BelchLIST v.5 by Noisy Belch/LOGIC    |\n|                                          |\n|   The BEST UserLIST you have ever seen   |\n| LAMER DETECT, ZIPPY, STATS, HEADER LOGO  |\n:         and MUCH MUCH MUCH more          |\n`------------------------------------------''\n','\n',char(10)),'BelchLIST.guide',replace('@database "BelchLIST"\n@node main "Main"\n                            __               ____\n ._________. .____________ /_/\ _____________\   \ ____________. ._________.\n |         | |             \_\/               \___\            | |         |\n |.       /\_|__    __/\________  ____________/\  /    /\______|_|_       :|\n ||    _ /  \   \___\/  \       \/\           \ \/____/  \         \ _    ||\n |:    //   /\___\   \  /\_______\ \___________\/\    \  /\_________\\    O|\n |o   . \  /.    /____\// \__   __\/   ________// \____\/. \________/ .   :|\n |.      \//    /     /.    /    ///    /     /o       //   /_____\       .|\n |        \_________ /\__________/\_________ /_______ /\_________ /        |\n |         | |     \/                      \/   __  \/         |\/        .|\n |_________| |________________________________ /\_\ ___________| |_________|\n :         : :                                 \/_/_           : :    Sk!n :\n\n                      BelchLIST v.5 by Noisy Belch/LOGIC\n                                        \n                     The BEST UserLIST you have ever seen\n                    LAMER DETECT, ZIPPY, STATS, HEADER LOGO\n                            and MUCH MUCH MUCH more\n\n                                  @{" Features " link "features"}\n                                  @{" History  " link "history"}\n                               @{" How to Install " link "install"}\n             @{" The fastest Independent Console Only Board in Europe " link "4Ndz Console Only"}\n\n\n\n@endnode\n@node "Features"\n\n   If the user is a lame LEECHER his download bytes will be shown in a\n   different colour\n\n   If the user didnt call for more days than you have defined in the\n   DOORS:BelchLIST/BelchLIST.config than It will show how many DAYS ago his\n   last call was in colour\n\n   ZIPPY will search for a user...\n\n   STATISTICS ... upload download files/byte lamer, elite,normal,deleted\n                     and more shit..\n\n   The "calls" of a new user  will show "NEW" instead of "1"\n\n@endnode\n\n@node "History"\n\n   0.1ß  lame\n   0.2ß  included config file\n   0.3   Fiest Public release\n   0.4   changed the output a bit removed files and added Calls\n         also added a new line to the config file..\n         removed DELETE again.. and also reoved the shutdown bug...\n\n         DONT USE OLDER VERSIONS OF BELCHLIST\n\n   0.5   much new options added...\n         statistics\n         mails\n         zippy by location\n\n         also fixed the DONT VIEW SYSOP stuff...\n\n	 Included FAZWONGA!''s kewl header...\n\n@endnode\n@node "Install"\n\n   Make sure the DOORS:BelchLIST/BelchLIST.config looks like this..\n\n   --------------------- cut ------------------\n   Y\n   esc[1m\n   6\n   30\n   bbs:user.data\n   --------------------- cut ------------------\n\n   1st line - Show the Sysop? Y or N\n   2nd line - must be a real ESCAPE code .. look into the example config file\n              here you can change the color/style of lameness wthpout limits\n   3rd line - Ratio for the Leech (0 == If you like leechers)\n   4th line - LAST_TIME_ON limit in days\n\n              With this config file for example all users which didnt\n              call in the last 30 days..\n              BelchLIST will show the days they didnt call in colour\n\n   5th line - Location of yer user.data\n\n@endnode\n@node "4Ndz Console Only"\n\n\n\n\n\n\n\n\n\n                   __ _/\/\__  __  ____/\____/\______/\____/\\n                  /  \  /    \/  \/  ___/  ___/   _   _/ ___/\n                 /      \  |  \   \___  \  _)_|   \   \  _)_\n                 \__\___/_____/___/_____/_____)___/___/_____)nb\n\n             The FASTEST Independent Console Only Board in EUROPE\n\n                        4 Nodes USRobotics and EuroISDN\n\n                             Much OLD stuff ONLINE\n\n@next "Main"\n@endnode\n','\n',char(10)),NULL,'auto-added',31305,2,0,NULL,NULL,'lgc_bl05','scan',1780048567);
INSERT INTO door_catalog VALUES('lgc_bl06','LGC-BL06.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGC-BL06.LHA','BelchLIST','XIM','BelchLIST',NULL,'Noisy','LGC','.:________________________    /________ /     /   _    /  ______/___/        / /     /\   /   /   /   /     \  \____/',replace('                _  _ ___ ________    (-fAZ!)\n  .:________________________    /________   \n   /     /   _    /  ______/___/        /   \n  /     /\   /   /   /   /     \  \____/    \n /________\____ /________\_____/_______\    \n+- -----------\/-- ---> S!X Development <--+\n|    BelchLIST v0.6 by Noisy Belch/LOGIC   |\n|   The BEST UserLIST you have ever seen   |\n|LAMER DETECT,ZIPPY,STATS,HEADER, USER.KEYS|\n+--> /X.info is HiSTORY <> FAME is LAME <--+\n','\n',char(10)),'BelchLIST.guide',replace('@database "BelchLIST"\n@node main "Main"\n                            __               ____\n ._________. .____________ /_/\ _____________\   \ ____________. ._________.\n |         | |             \_\/               \___\            | |         |\n |.       /\_|__    __/\________  ____________/\  /    /\______|_|_       :|\n ||    _ /  \   \___\/  \       \/\           \ \/____/  \         \ _    ||\n |:    //   /\___\   \  /\_______\ \___________\/\    \  /\_________\\    O|\n |o   . \  /.    /____\// \__   __\/   ________// \____\/. \________/ .   :|\n |.      \//    /     /.    /    ///    /     /o       //   /_____\       .|\n |        \_________ /\__________/\_________ /_______ /\_________ /        |\n |         | |     \/                      \/   __  \/         |\/        .|\n |_________| |________________________________ /\_\ ___________| |_________|\n :         : :                                 \/_/_           : :    Sk!n :\n\n                      BelchLIST v0.6 by Noisy Belch/LOGIC\n\n                                S!Express ONLY\n\n                                  @{" Features " link "features"}\n                                  @{" History  " link "history"}\n                               @{" How to Install " link "install"}\n             @{" The fastest Independent Console Only Board in Europe " link "4Ndz Console Only"}\n\n\n\n@endnode\n@node "Features"\n\n   If the user is a lame LEECHER his download bytes will be shown in a\n   different colour\n\n   If the user didnt call for more days than you have defined in the\n   DOORS:BelchLIST/BelchLIST.config than It will show how many DAYS ago his\n   last call was in colour\n\n   ZIPPY will search for a user...\n\n   STATISTICS ... upload download files/byte lamer, elite,normal,deleted\n                     and more shit..\n\n   The "calls" of a new user  will show "NEW" instead of "1"\n\n   Shows BAUD up and Download CPS and is realtime...\n\n@endnode\n\n@node "History"\n\n   0.1ß  lame\n   0.2ß  included config file\n   0.3   Fiest Public release\n   0.4   changed the output a bit removed files and added Calls\n         also added a new line to the config file..\n         removed DELETE again.. and also reoved the shutdown bug...\n\n         DONT USE OLDER VERSIONS OF BELCHLIST\n\n   0.5   much new options added...\n         statistics\n         mails\n         zippy by location\n\n         also fixed the DONT VIEW SYSOP stuff...\n\n	 Included FAZWONGA!''s kewl headers...\n   0.6   Changed the design and added AEDoor.library support.. now its\n         SMALLER and FASTER...\n\n         It also shows now the UPCPS and DOWNCPS and the BAUD rate\n         of the last call.. becuse i made it so that belchlist also \n         loads the USER.KEYS ... make sure that you add their path to\n         the config file as shown in @{" How to Install " link "install"}\n\n@endnode\n@node "Install"\n\n   Make sure the DOORS:BelchLIST/BelchLIST.config looks like this..\n\n   --------------------- cut ------------------\n   Y\n   esc[1m\n   6\n   30\n   bbs:user.data\n   bbs:user.keys\n   --------------------- cut ------------------\n\n   1st line - Show the Sysop? Y or N\n   2nd line - must be a real ESCAPE code .. look into the example config file\n              here you can change the color/style of lameness wthpout limits\n   3rd line - Ratio for the Leech (0 == If you like leechers)\n   4th line - LAST_TIME_ON limit in days\n\n              With this config file for example all users which didnt\n              call in the last 30 days..\n              BelchLIST will show the days they didnt call in colour\n\n   5th line - Location of yer user.data\n   6th line - Location of yer user.keys\n\n@endnode\n@node "4Ndz Console Only"\n\n                                     ___ _ _ _ __ _ __ _____\n                                    /\__\\n                  _   _ _ __ ____ __\/__/\n                                                                 ·aBn/fAZ!·\n                                                      ______ _____\n     _________  ________  _____ _____________________/   __/_  __/_________\n    _\___    /__\___   /_/____/_\    __________     /    ___/  ______     /\n   /    /     /    /    /     /  \      \/    /    /     /     /    /    /\n  /    /     /         /     /          /    _____/_    /_    /_   _____/_\n /____/     /_________/     /__________/___________/_____/_____/_________/\n  .  /______\        /_____/                                             :\n  |                                                                      |\n  | ...the fastest four nodes Independent Console only board in Europe.. |\n  |                                                                      !\n  |+            +49-52X-aSK-4iT -> USRobotics with Ringdown              o\n :¡.            +49-X24-fAST!   -> Euro ISDN with Ringdown!              ¡\n  |                                                                      |\n  |                -*- Sysop: Noisy Belch   Nup: AsK -*-                 |\n !|_____________________________________________________________________!|.\n ::::                                                                    !\n@next "Main"\n@endnode\n','\n',char(10)),NULL,'auto-added',34089,5,0,NULL,NULL,'lgc_bl06','scan',1780048567);
INSERT INTO door_catalog VALUES('lgc_bm2','LGC-BM2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGC-BM2.LHA',NULL,'XIM','Relyscully.exe',NULL,'Noisy','LGC','.:________________________    /________ /     /   _    /  ______/___/        / /     /\   /   /   /   /     \  \____/',replace('                _  _ ___ ________    (-fAZ!)\n  .:________________________    /________\n   /     /   _    /  ______/___/        /\n  /     /\   /   /   /   /     \  \____/\n /________\____ /________\_____/_______\\n==============\/============================\n      BelchMANIA2 by Noisy Belch/LOGIC\n  *** MORE NEW_SMALL_USEFUL_NICE DOORS ***\nGet S!X or let your BOARD look like a PD BBS\n=====================[S!X and lame /X.info]=\n','\n',char(10)),'Prepdocuments.doc',replace('                 \n                                  ·     ·\n                               _ __\   /__ _\n                            _ _)\\  \ /  //(_ _\n                           -\   __\° X °/__   /-\n                    _ __ ___ ___)  \/_\/  (___ ___ __ _\n                   -\\\_\\__\\__  _ /¦\ _  __//__//_///-\n             ·         _.      \__)_¯_¯_(__/      ._         ·\n           _/          \|_       | | | | |       _|/          \_\n         __\ ___ _/\____\/__ __ _| | | | |_ __ __\/____/\_ ___ /__\n       _/   \  (_)  \   \/  /_/\\| |_|_| |//\_\  \/   /  (_)  /   \_\n       |                    \_\/ | | | | | \/_/                    |\n      _|      ?? WHO...       __ | | | | | __    ...KNOWS ??    _ _|_\n      \|_ _                   \/_| | | | |_\/                      |/\n       |                     · _)  ¯_¯_¯  (_ ·                     |\n       |  ·H2o!·              \\___ \ / ___//                      |\n       ¯\_______________________ _)  Y  (_ _______________________/¯\n                                 \___ ___/\n                                    (_)\n ','\n',char(10)),NULL,'auto-added',109664,3,0,NULL,NULL,'lgc_bm2','scan',1780048567);
INSERT INTO door_catalog VALUES('lgc_bo15','LGC-BO15.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGC-BO15.LHA','BelchOLM','XIM','BelchOLM',NULL,'Noisy','LGC','.-» l__,|__|l__||l__'' S!X Development_\/_«-. |--------------''---------------------\/\/--| |                                          :',replace('    .    __  __ . __                  __    \n.-» l__,|__|l__||l__'' S!X Development_\/_«-.\n|--------------''---------------------\/\/--|\n|                                          :\n|    BelchOLM v1.5 by Noisy Belch/LOGIC    |\n|                                          |\n| INSTANT REPLY, GLOBAL OLM, ANONYMOUS OLM |\n| Changed the DESIGN a bit and now you can |\n:   OLM node 1 2 and 4 with [OLM 4 1 2]    |\n`------------------------------------------''\n','\n',char(10)),'BelchOLM.guide',replace('@database "BelchOLM"\n@node main "Main"\n                            __               ____\n ._________. .____________ /_/\ _____________\   \ ____________. ._________.\n |         | |             \_\/               \___\            | |         |\n |.       /\_|__    __/\________  ____________/\  /    /\______|_|_       :|\n ||    _ /  \   \___\/  \       \/\           \ \/____/  \         \ _    ||\n |:    //   /\___\   \  /\_______\ \___________\/\    \  /\_________\\    O|\n |o   . \  /.    /____\// \__   __\/   ________// \____\/. \________/ .   :|\n |.      \//    /     /.    /    ///    /     /o       //   /_____\       .|\n |        \_________ /\__________/\_________ /_______ /\_________ /        |\n |         | |     \/                      \/   __  \/         |\/        .|\n |_________| |________________________________ /\_\ ___________| |_________|\n :         : :                                 \/_/_           : :    Sk!n :\n\n                      BelchOLM v1.5 by Noisy Belch/LOGIC\n\n                   INSTANT REPLY, GLOBAL OLM, ANONYMOUS OLM\n                   Changed the DESIGN a bit and now you can\n                      OLM node 1 2 and 4 with [OLM 4 1 2]\n\n                                  @{" Features " link "features"}\n                                  @{" History  " link "history"}\n                               @{" How to Install " link "install"}\n             @{" The fastest Independent Console Only Board in Europe " link "4Ndz Console Only"}\n@endnode\n@node "Features"\n\n\n   Supports as many nodes as you want\n   OLM can be send ANONYMOUS\n   OLM all nodes at the same time\n   3 lines for your Messages\n   Supports the S!X intern OLM.message.txt routine\n   Faststart with Commandline options... Example: [OLM 1] for node 1\n   (Optional) Instant Reply (even if the sender was anonymous!!!!)\n   The Instant Reply can be generally disabled by the (lame) sysop\n\n   You will love it...\n@endnode\n\n@node "History"\n\n   0.1ß  lame\n   0.2ß  a few improvements and better design\n   0.3ß  added a scale, global and other stuff\n   0.4ß  added the Anonymous function and changed the design a bit\n   0.5ß  cosmetical changes\n   0.6ß  only a few cosmetical changes...\n   0.7ß  total re-written and optimized version\n   0.8ß  Translated from Arexx into C\n   0.9ß  WHO shows now "Using OLM" instead of "Module"\n   1.0   added hotkey at "should i.." question.. public release..\n   1.1   added a new powerful feature... INSTANT REPLY after receiving\n         an message the OLM itself will popup and you can reply automatically\n         or just press CR if you are not interested.. \n\n         EXAMPLE....\n\n         Someone poststs anonymous an OLM to you and you CAN reply.. but still\n         without knowing who he was haha...\n\n         This feature needs new commands in the bbs.cmd file...\n \n         -------------------------------- cut -----------------------------\n	 *olm      XM030doors:BelchOLM/BelchOLM\n	 *reply0   XM030doors:BelchOLM/BelchOLM\n	 *reply1   XM030doors:BelchOLM/BelchOLM\n	 *reply2   XM030doors:BelchOLM/BelchOLM\n	 *reply3   XM030doors:BelchOLM/BelchOLM\n	 *reply4   XM030doors:BelchOLM/BelchOLM\n         -------------------------------- cut -----------------------------\n\n         this is for an 5 nodes board if you have more nodes just add more\n         reply commands with the node number... reply5, reply6, reply7 ...\n   1.2   Instant Reply is now OPTIONAL... you''ll be asked.. \n   1.3   worked a bit on the Insant reply stuff again.. now the sysop can\n         disable it generally by creating or not creating a dummy file called\n\n         DOORS:BelchOLM/NOREPLY\n\n         If BelchOLM find the file the Instant reply mode is deactivated\n         Also included fina;ly somthing like word wrap...\n   1.4   A few changes in the questins and the design... also fixed the\n         shutdown bug... \n   1.5   now you can OLM node 1 2 and 4 with [OLM 4 1 2] (as example)\n         just type the nodes you want to olm in behind the command in\n         no order and it will work.. if you want to olm all nodes you\n         can still type [OLM *]\n\n@endnode\n@node "Install"\n\n         put the olm somewhere and add this to you bbs.cmd\n\n         -------------------------------- cut -----------------------------\n	 *olm      XM030doors:BelchOLM/BelchOLM\n	 *reply0   XM030doors:BelchOLM/BelchOLM\n	 *reply1   XM030doors:BelchOLM/BelchOLM\n	 *reply2   XM030doors:BelchOLM/BelchOLM\n	 *reply3   XM030doors:BelchOLM/BelchOLM\n	 *reply4   XM030doors:BelchOLM/BelchOLM\n         -------------------------------- cut -----------------------------\n\n         this is an example for a 5 nodes board if you have more nodes just\n         add more reply commands with the node number...\n         reply5, reply6, reply7 ...\n\n         Since version 1.3 the Sysop can disable the Instant Reply generally\n         by creating or not creating a dummy file called\n\n         DOORS:BelchOLM/NOREPLY\n\n         If BelchOLM find the file the Instant reply mode is deactivated\n@endnode\n\n@node "4Ndz Console Only"\n\n\n\n\n\n\n\n\n\n                   __ _/\/\__  __  ____/\____/\______/\____/\\n                  /  \  /    \/  \/  ___/  ___/   _   _/ ___/\n                 /      \  |  \   \___  \  _)_|   \   \  _)_\n                 \__\___/_____/___/_____/_____)___/___/_____)nb\n\n             The FASTEST Independent Console Only Board in EUROPE\n\n                        4 Nodes USRobotics and EuroISDN\n\n                             Much OLD stuff ONLINE\n\n@next "main"\n@endnode\n','\n',char(10)),NULL,'auto-added',33969,6,0,NULL,NULL,'lgc_bo15','scan',1780048567);
INSERT INTO door_catalog VALUES('lgc_bo16','LGC-BO16.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGC-BO16.LHA','BelchOLM','XIM','BelchOLM',NULL,'Noisy','LGC','.:________________________    /________ /     /   _    /  ______/___/        / /     /\   /   /   /   /     \  \____/',replace('                _  _ ___ ________    (-fAZ!)\n  .:________________________    /________   \n   /     /   _    /  ______/___/        /   \n  /     /\   /   /   /   /     \  \____/    \n /________\____ /________\_____/_______\    \n+- -----------\/-- ---> S!X Development <--+\n|    BelchOLM v1.6 by Noisy Belch/LOGIC    |\n| INSTANT REPLY, GLOBAL OLM, ANONYMOUS OLM |\n|   OLM node 1 2 and 4 with [OLM 4 1 2]    |\n+--> /X.info is HiSTORY <> FAME is LAME <--+\n','\n',char(10)),'BelchOLM.guide',replace('@database "BelchOLM"\n@node main "Main"\n                            __               ____\n ._________. .____________ /_/\ _____________\   \ ____________. ._________.\n |         | |             \_\/               \___\            | |         |\n |.       /\_|__    __/\________  ____________/\  /    /\______|_|_       :|\n ||    _ /  \   \___\/  \       \/\           \ \/____/  \         \ _    ||\n |:    //   /\___\   \  /\_______\ \___________\/\    \  /\_________\\    O|\n |o   . \  /.    /____\// \__   __\/   ________// \____\/. \________/ .   :|\n |.      \//    /     /.    /    ///    /     /o       //   /_____\       .|\n |        \_________ /\__________/\_________ /_______ /\_________ /        |\n |         | |     \/                      \/   __  \/         |\/        .|\n |_________| |________________________________ /\_\ ___________| |_________|\n :         : :                                 \/_/_           : :    Sk!n :\n\n                      BelchOLM v1.6 by Noisy Belch/LOGIC\n\n                                S!Express ONLY\n\n                                  @{" Features " link "features"}\n                                  @{" History  " link "history"}\n                               @{" How to Install " link "install"}\n             @{" The fastest Independent Console Only Board in Europe " link "4Ndz Console Only"}\n@endnode\n@node "Features"\n\n\n   Supports as many nodes as you want\n   OLM can be send ANONYMOUS\n   OLM all nodes at the same time\n   3 lines for your Messages\n   Supports the S!X intern OLM.message.txt routine\n   Faststart with Commandline options... Example: [OLM 1] for node 1\n   (Optional) Instant Reply (even if the sender was anonymous!!!!)\n   The Instant Reply can be generally disabled by the (lame) sysop\n\n   You will love it...\n@endnode\n\n@node "History"\n\n   0.1ß  lame\n   0.2ß  a few improvements and better design\n   0.3ß  added a scale, global and other stuff\n   0.4ß  added the Anonymous function and changed the design a bit\n   0.5ß  cosmetical changes\n   0.6ß  only a few cosmetical changes...\n   0.7ß  total re-written and optimized version\n   0.8ß  Translated from Arexx into C\n   0.9ß  WHO shows now "Using OLM" instead of "Module"\n   1.0   added hotkey at "should i.." question.. public release..\n   1.1   added a new powerful feature... INSTANT REPLY after receiving\n         an message the OLM itself will popup and you can reply automatically\n         or just press CR if you are not interested.. \n\n         EXAMPLE....\n\n         Someone poststs anonymous an OLM to you and you CAN reply.. but still\n         without knowing who he was haha...\n\n         This feature needs new commands in the bbs.cmd file...\n \n         -------------------------------- cut -----------------------------\n	 *olm      XM030doors:BelchOLM/BelchOLM\n	 *reply0   XM030doors:BelchOLM/BelchOLM\n	 *reply1   XM030doors:BelchOLM/BelchOLM\n	 *reply2   XM030doors:BelchOLM/BelchOLM\n	 *reply3   XM030doors:BelchOLM/BelchOLM\n	 *reply4   XM030doors:BelchOLM/BelchOLM\n         -------------------------------- cut -----------------------------\n\n         this is for an 5 nodes board if you have more nodes just add more\n         reply commands with the node number... reply5, reply6, reply7 ...\n   1.2   Instant Reply is now OPTIONAL... you''ll be asked.. \n   1.3   worked a bit on the Insant reply stuff again.. now the sysop can\n         disable it generally by creating or not creating a dummy file called\n\n         DOORS:BelchOLM/NOREPLY\n\n         If BelchOLM find the file the Instant reply mode is deactivated\n         Also included fina;ly somthing like word wrap...\n   1.4   A few changes in the questins and the design... also fixed the\n         shutdown bug... \n   1.5   now you can OLM node 1 2 and 4 with [OLM 4 1 2] (as example)\n         just type the nodes you want to olm in behind the command in\n         no order and it will work.. if you want to olm all nodes you\n         can still type [OLM *]\n   1.6   included optional WHO just create a dummy file called \n         DOORS:BELCHOLM/WHO and belcholm will start the who door at\n	 the beginning... that doesnt seem to work with the internal who\n	 (not my fault!!) so use belchwho for example or let it be.. eheh\n         Added AEdoor.library support.. now its SMALLER and FASTER..\n\n         This was the last update.. because im tired of releasing always\n         the same kind of doors.. and the OLM is pretty good now..\n\n         watch out for the BelchWHO final..   coming soon...\n@endnode\n@node "Install"\n\n         put the olm somewhere and add this to you bbs.cmd\n\n         -------------------------------- cut -----------------------------\n	 *olm      XM030doors:BelchOLM/BelchOLM\n	 *reply0   XM030doors:BelchOLM/BelchOLM\n	 *reply1   XM030doors:BelchOLM/BelchOLM\n	 *reply2   XM030doors:BelchOLM/BelchOLM\n	 *reply3   XM030doors:BelchOLM/BelchOLM\n	 *reply4   XM030doors:BelchOLM/BelchOLM\n         -------------------------------- cut -----------------------------\n\n         this is an example for a 5 nodes board if you have more nodes just\n         add more reply commands with the node number...\n         reply5, reply6, reply7 ...\n\n         Since version 1.3 the Sysop can disable the Instant Reply generally\n         by creating or not creating a dummy file called\n\n         DOORS:BelchOLM/NOREPLY\n\n         If BelchOLM find the file the Instant reply mode is deactivated\n@endnode\n\n@node "4Ndz Console Only"\n\n                                     ___ _ _ _ __ _ __ _____\n                                    /\__\\n                  _   _ _ __ ____ __\/__/\n                                                                 ·aBn/fAZ!·\n                                                      ______ _____\n     _________  ________  _____ _____________________/   __/_  __/_________\n    _\___    /__\___   /_/____/_\    __________     /    ___/  ______     /\n   /    /     /    /    /     /  \      \/    /    /     /     /    /    /\n  /    /     /         /     /          /    _____/_    /_    /_   _____/_\n /____/     /_________/     /__________/___________/_____/_____/_________/\n  .  /______\        /_____/                                             :\n  |                                                                      |\n  | ...the fastest four nodes Independent Console only board in Europe.. |\n  |                                                                      !\n  |+            +49-52X-aSK-4iT -> USRobotics with Ringdown              o\n :¡.            +49-X24-fAST!   -> Euro ISDN with Ringdown!              ¡\n  |                                                                      |\n  |                -*- Sysop: Noisy Belch   Nup: AsK -*-                 |\n !|_____________________________________________________________________!|.\n ::::                                                                    !\n@next "main"\n@endnode\n','\n',char(10)),NULL,'auto-added',31096,5,0,NULL,NULL,'lgc_bo16','scan',1780048567);
INSERT INTO door_catalog VALUES('lgc_bt03','LGC-BT03.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGC-BT03.LHA',NULL,'XIM','LE-window5.exe',NULL,NULL,'LGC',NULL,NULL,NULL,NULL,NULL,'auto-added',18006,0,0,NULL,NULL,'lgc_bt03','scan',1780048567);
INSERT INTO door_catalog VALUES('lgc_bv12','LGC-BV12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGC-BV12.LHA','BelchVIEW','XIM','BelchVIEW',NULL,'Noisy','LGC','.-» l__,|__|l__||l__'' S!X Development_\/_«-. |--------------''---------------------\/\/--| |    BelchVIEW v1.2 by Noisy Belch/LOGIC   :',replace('    .    __  __ . __                  __    \n.-» l__,|__|l__||l__'' S!X Development_\/_«-.\n|--------------''---------------------\/\/--|\n|    BelchVIEW v1.2 by Noisy Belch/LOGIC   :\n|                                          |\n|       ARC ARJ DMS LHA LZH LZX RUN        |\n|       SFX SHR TXT WRP ZIP ZOM ZOO        |\n|                                          |\n:Supports WILDCARDS and SPACES in Filenames|\n`------------------------------------------''\n','\n',char(10)),'BelchVIEW.guide',replace('@database "BelchVIEW"\n@node main "Main"\n                            __               ____\n ._________. .____________ /_/\ _____________\   \ ____________. ._________.\n |         | |             \_\/               \___\            | |         |\n |.       /\_|__    __/\________  ____________/\  /    /\______|_|_       :|\n ||    _ /  \   \___\/  \       \/\           \ \/____/  \         \ _    ||\n |:    //   /\___\   \  /\_______\ \___________\/\    \  /\_________\\    O|\n |o   . \  /.    /____\// \__   __\/   ________// \____\/. \________/ .   :|\n |.      \//    /     /.    /    ///    /     /o       //   /_____\       .|\n |        \_________ /\__________/\_________ /_______ /\_________ /        |\n |         | |     \/                      \/   __  \/         |\/        .|\n |_________| |________________________________ /\_\ ___________| |_________|\n :         : :                                 \/_/_           : :    Sk!n :\n\n                      BelchVIEW v1.2 by Noisy Belch/LOGIC\n                                          \n                          ARC ARJ DMS LHA LZH LZX RUN\n                          SFX SHR TXT WRP ZIP ZOM ZOO\n                                          \n                  Supports WILDCARDS and SPACES in Filenames\n\n\n                                  @{" Features " link "features"}\n                                  @{" History  " link "history"}\n                               @{" How to Install " link "install"}\n             @{" The fastest Independent Console Only Board in Europe " link "4Ndz Console Only"}\n\n@endnode\n@node "Features"\n\n   Supports ARC ARJ DMS LHA LZH LZX RUN SFX SHR TXT WRP ZIP ZOM ZOO\n\n   It also views files from inside the archive with SPACES in the Filename\n   MEGA-VIEW does not...\n\n   It was tested on S!X but might also work with /X.info\n\n@endnode\n\n@node "History"\n\n   0.1ß  lame\n   0.2ß  \n   0.3ß  \n   0.4ß  \n   0.5ß  \n   0.6ß  \n   0.7ß  \n   0.8   translated from Arexx to C\n   0.9   Wildcards added\n   1.0   Some small changes\n   1.1   Canged the design a bit and removed the stupid Shutdown bug..\n         also included LZX of course... but i still preffer LHA ehee\n\n         Please add lzx=c:lzx or something to your .config file\n   1.2   small changes in the design.. some bug fixes and also\n         optimized the code a bit...\n\n\n@endnode\n@node "Install"..\n\n   Make sure all paths in the DOORS:BelchVIEW/BelchVIEW.config file are ok..\n\n   I doesnt matter in which order you enter them..\n\n   --------------------- cut ------------------\n   shr=c:shrink\n   arj=c:arj\n   dms=c:dmscli\n   zom=c:zoomchk\n   wrp=c:warpck\n   lha=lha\n   zip=c:unzip\n   zoo=c:zoo\n   arc=c:arc\n   acc=255\n   lzx=c:lzx\n   --------------------- cut ------------------\n\n   [acc=] is the account level minimum to view files which are\n          not in the upload dir\n\n   Install it like a XIM door as V and VS in your BBS.CMD\n@endnode\n\n@node "4Ndz Console Only"\n\n\n\n\n\n\n\n\n\n                   __ _/\/\__  __  ____/\____/\______/\____/\\n                  /  \  /    \/  \/  ___/  ___/   _   _/ ___/\n                 /      \  |  \   \___  \  _)_|   \   \  _)_\n                 \__\___/_____/___/_____/_____)___/___/_____)nb\n\n             The FASTEST Independent Console Only Board in EUROPE\n\n                        4 Nodes USRobotics and EuroISDN\n\n                             Much OLD stuff ONLINE\n\n@next "main"\n@endnode\n','\n',char(10)),NULL,'auto-added',229973,2,0,NULL,NULL,'lgc_bv12','scan',1780048567);
INSERT INTO door_catalog VALUES('lgc_bv13','LGC-BV13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGC-BV13.LHA','BelchVIEW','XIM','BelchVIEW',NULL,'Noisy','LGC','.:________________________    /________ /     /   _    /  ______/___/        / /     /\   /   /   /   /     \  \____/',replace('                _  _ ___ ________    (-fAZ!)\n  .:________________________    /________   \n   /     /   _    /  ______/___/        /   \n  /     /\   /   /   /   /     \  \____/    \n /________\____ /________\_____/_______\    \n+- -----------\/-- ---> S!X Development <--+\n|    BelchVIEW v1.3 by Noisy Belch/LOGIC   |\n|     Supports ALL FORMATS, WILDCARDS      |\n| SPACES in Filenames and ...FLAGGED FILES |\n+--> /X.info is HiSTORY <> FAME is LAME <--+\n','\n',char(10)),'BelchVIEW.guide',replace('@database "BelchVIEW"\n@node main "Main"\n                            __               ____\n ._________. .____________ /_/\ _____________\   \ ____________. ._________.\n |         | |             \_\/               \___\            | |         |\n |.       /\_|__    __/\________  ____________/\  /    /\______|_|_       :|\n ||    _ /  \   \___\/  \       \/\           \ \/____/  \         \ _    ||\n |:    //   /\___\   \  /\_______\ \___________\/\    \  /\_________\\    O|\n |o   . \  /.    /____\// \__   __\/   ________// \____\/. \________/ .   :|\n |.      \//    /     /.    /    ///    /     /o       //   /_____\       .|\n |        \_________ /\__________/\_________ /_______ /\_________ /        |\n |         | |     \/                      \/   __  \/         |\/        .|\n |_________| |________________________________ /\_\ ___________| |_________|\n :         : :                                 \/_/_           : :    Sk!n :\n\n                      BelchVIEW v1.3 by Noisy Belch/LOGIC\n                                          \n                                S!Express ONLY\n\n                                  @{" Features " link "features"}\n                                  @{" History  " link "history"}\n                               @{" How to Install " link "install"}\n             @{" The fastest Independent Console Only Board in Europe " link "4Ndz Console Only"}\n\n@endnode\n@node "Features"\n\n   Supports ARC ARJ DMS LHA LZH LZX RUN SFX SHR TXT WRP ZIP ZOM ZOO\n\n   It also views files from inside the archive with SPACES in the Filename\n   or files in directories MEGA-VIEW does not !!!...\n\n   If you have  S!X 0.39p+ it will also ask to view FLAGGED FILES!!\n\n@endnode\n\n@node "History"\n\n   0.1ß  lame\n   0.2ß  \n   0.3ß  \n   0.4ß  \n   0.5ß  \n   0.6ß  \n   0.7ß  \n   0.8   translated from Arexx to C\n   0.9   Wildcards added\n   1.0   Some small changes\n   1.1   Canged the design a bit and removed the stupid Shutdown bug..\n         also included LZX of course... but i still preffer LHA ehee\n\n         Please add lzx=c:lzx or something to your .config file\n   1.2   small changes in the design.. some bug fixes and also\n         optimized the code a bit...\n   1.3   Added AEdoor.library support.. now its SMALLER and FASTER...\n         belchview is new able to view your flagged files but that will\n         only work with S!X 0.39p+ ... if you have an older version of\n         S!X it will do nothing...\n\n@endnode\n@node "Install"..\n\n   Make sure all paths in the DOORS:BelchVIEW/BelchVIEW.config file are ok..\n\n   I doesnt matter in which order you enter them..\n\n   --------------------- cut ------------------\n   shr=c:shrink\n   arj=c:arj\n   dms=c:dmscli\n   zom=c:zoomchk\n   wrp=c:warpck\n   lha=lha\n   zip=c:unzip\n   zoo=c:zoo\n   arc=c:arc\n   acc=255\n   lzx=c:lzx\n   --------------------- cut ------------------\n\n   [acc=] is the account level minimum to view files which are\n          not in the upload dir\n\n   Install it like a XIM door as V and VS in your BBS.CMD or take a look at\n   the example..\n@endnode\n\n@node "4Ndz Console Only"\n\n                                     ___ _ _ _ __ _ __ _____\n                                    /\__\\n                  _   _ _ __ ____ __\/__/\n                                                                 ·aBn/fAZ!·\n                                                      ______ _____\n     _________  ________  _____ _____________________/   __/_  __/_________\n    _\___    /__\___   /_/____/_\    __________     /    ___/  ______     /\n   /    /     /    /    /     /  \      \/    /    /     /     /    /    /\n  /    /     /         /     /          /    _____/_    /_    /_   _____/_\n /____/     /_________/     /__________/___________/_____/_____/_________/\n  .  /______\        /_____/                                             :\n  |                                                                      |\n  | ...the fastest four nodes Independent Console only board in Europe.. |\n  |                                                                      !\n  |+            +49-52X-aSK-4iT -> USRobotics with Ringdown              o\n :¡.            +49-X24-fAST!   -> Euro ISDN with Ringdown!              ¡\n  |                                                                      |\n  |                -*- Sysop: Noisy Belch   Nup: AsK -*-                 |\n !|_____________________________________________________________________!|.\n ::::                                                                    !\n@next "main"\n@endnode\n','\n',char(10)),NULL,'auto-added',230324,4,0,NULL,NULL,'lgc_bv13','scan',1780048567);
