INSERT INTO door_catalog VALUES('lgc_jc11','LGC_JC11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGC_JC11.LHA',NULL,'XIM','JoyComment.xim',NULL,'AtomiX','LGC','__ /\__\  /\_____\_____\__\_____\___ _ __ / /  / / / _   /  ___/  /     / presents / /  /_/_/  /  /  /-./  /  /--/    another',replace('__ _ ___    _____________________ ____ _ __ \n __ /\__\  /\_____\_____\__\_____\___ _ __\n   / /  / / / _   /  ___/  /     / presents\n  / /  /_/_/  /  /  /-./  /  /--/    another\nNL\/______/_____/_____/__/_____/cool prod.:\n  JoyComment V1.1 by AtomiX [/X 2.x & 3.x]\n     Release Date 04.05.94\n','\n',char(10)),'JoyComment.doc',replace('____________________________________________________________________\n::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nOrginalFile . JoyComment.xim JoyComment.xim 15992 bytes\n____________________________________________________________________\n::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\nJoyComment V1.1 Mon Apr  4 09:36:06 1994\n--------------\n\nV1.0 -   First Release\nV1.1 -   Optimized and writen a new Turbo Routine for faster\n         Screen Output\n\n____________________________________________________________________\n::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\nHow to Install ?\n----------------\n\nThis is a XIM Door\n\nCopy just all to the BBS i prepared it so that is working\nAutomaticaly ;^))\n\nOk Doki and now the Introducing or so ;))\n\nConfigure the "DOORS:JOYCOMENNT/JoyComment.xim.info"\n\n------------------------------------------------------------------------\nToolTypes:\n\n          SYSOPS=              <Add the MAX Number of Sysops you want>\n         SYSOP.x=              <Here the Name of the Sys/CoSysop>\n       COMMENT.x=              <"    "   Comment of the " ">\n		MENU_LEVEL=              <"    "   Access Level which is allowed\n                                to view the Sysop Menu (Default is 20)>\n\n------------------------------------------------------------------------\n\nso that''s all i you have a Problem with my Door/s then leave me\na mail or call me.\n\n____________________________________________________________________\n::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nWhat is JoyComment ?\n--------------------\n\nJoyComment is a MultipleComment Door for Sysops and Cosysops\nbla bla . i think you all now what is Comment Door..\n____________________________________________________________________\n::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\nFuture :\n--------\n\n      NO FEAUTURE hehe\n____________________________________________________________________\n::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\niF YoU FoUnD BuGS or have Suggestion''s let me know on AmiXnet\n\n	@GR0003\n	@GR0004\n\nor on some German BBS System , Skara Brae , Blue Moon , Diabolo\netc etc..\nmy user handle is on all BBS Systems AtomiX\n\n____________________________________________________________________\n::AtomiX::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬\n\n     _____  _____  _____  _____  _____       __     ___  _____  _____\n    /\    \/\   \\/\    \/\    \/\    \     /\ \   /\  \/\    \/\    \\n.__/  \____\ \___\\ \____\ \____\ \____\   /  \_\ /  \__\ \____\ \____\\n| /   /¯   ¬\/   /¬\/ __ ¬\/ __ ¬\/    ¬\ /   / ¬\   /  ¬\/  _ ¬\/    ¬\\n|/   /o /___/o  /  /o/_/  /o  /  / _____//   /o  /  /o   /o  /  /o ----/\n|\  // /   //     //     //  /  /____  / \  //  /_\//   //  /  // ____/\n| \/___   /___/  /___/  /___   /___   /   \/___   /__  /___/  /___   /\n|    \/__/  \/__/  \/__/NL\/__/  \/__/       \/__/ \/_/   /__/  \/__/\n|                             |\n|  da cRew: AtomiX & No LiMit |    .__________________________________.\n|           Flake , KiWi      |    |                                  |\n|_____________________________|    |  NoDe0: +49-(sE)-cReT!!! <- DHST |\n·                             ·    |  NoDe1: +49-(sE)-cReT!!! <- SOON |\n                                   |  NoDe2: +49-(Pr)-iVAt!!! <-- LOC |\n                                   !__________________________________!\n                                   ·                                  ·\n                                                                      ·\n¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬\n\n','\n',char(10)),NULL,'auto-added',12908,2,0,NULL,NULL,'lgc_jc11','scan',1780048575);
INSERT INTO door_catalog VALUES('lgc_lc20','LGC-LC20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGC-LC20.LHA','LhaCheck','XIM','Execute_Me',NULL,'WHiZ/LOGiC','LGC','/ /\_\__\/ /\____\/\________\/\__\________\ / //  /___\// \_  _\/  ______/____/  ______/ \/.  /    /o   \  ///  /    /    //  /____\',replace('  /\__   __/\_____  _________/\____________\n / /\_\__\/ /\____\/\________\/\__\________\\n/ //  /___\// \_  _\/  ______/____/  ______/\n\/.  /    /o   \  ///  /    /    //  /____\\n \______ /\_______/\______ /___ /\_______ /\nSk!n:::\/::::::::Presents\/:::\/::::::::\/::\n        LhACheck v2.0 by WHiZ/LOGiC !\nThe ultimate LhA Checker coded in pure ASM !\nAdds and Strips unlimited Adverts. Displays\nnew and old filesize. Beaufiful Output !\nThis is the LhA Checker you''ve been waiting\nfor ! Install it and see for yourself !\n','\n',char(10)),'LhACheck20.doc',replace('                            __               ____\n ._________. .____________ /_/\ _____________\   \ ____________. ._________.\n |         | |             \_\/               \___\            | |         |\n |.       /\_|__    __/\________  ____________/\  /    /\______|_|_       :|\n ||    _ /  \   \___\/  \       \/\           \ \/____/  \         \ _    ||\n |:    //   /\___\   \  /\_______\ \___________\/\    \  /\_________\\    O|\n |o   . \  /.    /____\// \__   __\/   ________// \____\/. \________/ .   :|\n |.      \//    /     /.    /    ///    /     /o       //   /_____\       .|\n |        \_________ /\__________/\_________ /_______ /\_________ /        |\n |         | |     \/                      \/   __  \/         |\/        .|\n |_________| |________________________________ /\_\ ___________| |_________|\n :         : :                                 \/_/_           : :    Sk!n :\n\n                                PRESENTS\n\n                   LhACheck v2.0 coded by WHiZ/LOGiC !\n\n    PROFESSIONAL TOOLS FOR PROFESSIONAL USERS - GET THE REAL QUALITY !\n\n\nWHAT''S THE USE OF THIS TOOL ?\n-----------------------------\n\n        It''s another LhAChecker coded in pure ASM with a lot of cool\n        features. For example, you have the possibility of adding and\n        stripping unlimited adverts ! Additionally you can choose\n        having all stripped adverts displayed or not. The coolest\n        feature of this Checker probably is that the old and new\n        size of the LHA/LZH File is displayed after stripping and\n        adding all adverts.\n\nWHY SHOULD I USE IT ?\n---------------------\n\n        If you love speed and beautiful outputs this is the tool\n        you have been waiting for ! Install it, and see for yourself.\n\nHOW TO INSTALL THIS TOOL :\n--------------------------\n\n        It''s quite easy to install. If you run /X v3.x or /X v4.x all\n        you need to do is the following with your FCheck LHA/LZH icons.\n        I hope that /X v2.x or S-Express Sysops will be able to install\n        this tool on their own.\n        \n        CHECKER=C:LhACheck\n        OPTIONS=-D S:ConfigFile S:Stripadverts\n        STACK=10000\n        PRIORITY=1\n        ERROR.1=CORRUPT\n\n        Line.1: Path to this LhA Checker\n        Line.2: -D displays all stripped adverts\n                -S will surpress the display\n                \n                S:ConfigFile or whatever you name it, should be the file\n                in which all your Adverts are listed, e.g.:\n\n                DH0:MyAD.Txt\n                "DH1:Call.Displayme    "\n                "S:Give_it_a_Ring  "\n\n \n               -^- Unlimited Lines -^-\n\n\n                S:Stripadvertss or whatever you name it, is the file in\n                which all adverts you want to strip are listed, e.g.:\n\n                *.displayme\n                Great_System\n                TypeMe.TXT\n\n\n                -^- Unlimited Lines -^-\n\n                \n        Line.3: Stacksize of this tool. Play around with it, i always take\n                10000\n        Line.4: Priority of this tool. Play around with it !\n        Line.5: Very Important ! Do not change it or all corrupt archives\n                won''t be moved to your hold !\n\n       NOTE: It''s not BBS specific, meaning you can use it also with other\n             BBS Software or even in your DiskMaster, DOPus or whatever !\n\nLAST WORDS :\n------------\n\n        Have fun with this great Checker ! It has been tested for a long time\n        now without ANY problems. If you should discover bugs or have any\n        suggestions to make about this tool, feel free to leave me mail via\n        AmiXNet (WHiZ@203001) or give my board PSYCHO TERMiNAL a ring !\n\n        See ya soon mates...\n                                                                 WHiZ/LOGiC !\n                                                                 ~~~~~~~~~~~~\n\nSOON TO BE RELEASES TOOLS - ALL CODED IN ASM! :\n-----------------------------------------------\n\n       Turbo Boost v1.x - Another Text Adder/Checker/Stripper !\n       BullUp v1.1      - /X & S!X Online Bulletin Updater !\n       ModSaM vx.x      - The Ultimate Pager (Modules/Samples and more).\n                          Now coded in pure ASM !\n                          Update to the lame ARexx Release !\n       LogonInfo v2.x   - The Best Frontend you''ve ever seen!\n\nGREETINGS:\n----------\n\n	The Champ · Halfast · Mr Hyde · The Fly · Freddy Krueger · Franky\n	Joker/ZZC · Dalai Lama · SchwabenPoweR · Red Alert · Rioter · BBC\n	2-Cool · g.E.m. · Sid Vicious · Ccs & Eqx · Calypso · TerrorizeR\n	Dexter/aFL · Foxx''n''Lynxx · Ernesto · Snow · Jive · Sintax · Treach\n	The Addict · Cobra · Manta · Sce · Hot Kid · Rofoe · Don Dog\n        Cas(ch)tor · Warhawk · Dragon · Warlord · and all LOGiC Members !\n	\n\n      _______/\ __________________ /\_______/\______________ ___________/\\n     /     ___//   ____________   \\______  \________  \    |    /   ____/\n  Mb/  ___/___/   / \   \/   / \   \|    |\  \|   _|/ _/\__ | __/  __/___\n  _/   \_    /    \_/    \   \_/    \    |/   \   \__  \  /   \/   \_/   \\n  \    _/    \           /          /          \   |/   \/     \_         \\n   \___\  ___|\_________/\_________/|__________/________/_______/_________/\n        \/                                                                \n\nClick...\n\n··············································································\n                                                    ·\n     _ ______________________           ____________¦________________\n   ·    ________   /   _____/________  /· ______/   |   \______    o/  ·\n   ¦_____/   _____/_____   /\    \   \//  /____/         \    /   //___¦\n   |    /____/   /________/  \______ /_______ /_____|_____\_______/Sk¡n|\n   |                          \ _______\    \/      ¦                  |\n   |                           \/                   ·                  |\n   |                                       ___        ·                |\n   |                                      /\__\ _     ¦_____    _ _____|\n___|_________________  /\______/\ __ /\   \/__/  ____ |  _ /____ _    /|___\n\ _ o    _ /  __    /_/___  _ /  \\// o\________|    \|  //o    \/   /    /\n \//     \/  ______/    |/  //    \/   \\       /___\ \  //     /_______ /\n /________\______ /_____/   /____\  /____\_____/     \  /_________\    \/\n   |            \/      \___\     \/                  \/               |\n   |                                                                   |\n   |   eNDLESS pIRACY wORLD hEADQUARTERS - lOGiC gERMAN hEADQUARTERS   |\n   |                      rEFLEX gERMAN hEADQUARTERS                   |\n   |___________________________________________________________________|\n     \n                       +49-aSK-fOR-iT! [ dUAL 28.8 ]\n                       +49-aSK-fOR-iT! [ dUAL 21.6 ]\n          \n    > mASTER: WHiZ/LOGiC!           sLAVES: Calypso/GOD - The Fly/TRY <\n','\n',char(10)),'{"STACK":"10000","PRIORITY":"1"}','auto-added',8376,1,0,NULL,NULL,'lgc_lc20','scan',1780048567);
INSERT INTO door_catalog VALUES('lgc_lck2','LGC-LCK2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGC-LCK2.LHA','LhaCheck','XIM','LhaCheck',NULL,'CALYPSO','LGC','_ __   /______________   // \\__________ /   / \_____  \/  _/__//   \\____    / /   /   \   /   \  \    \____/   /___/_',replace(' _ _______      _ __________ /\             \n  _ __   /______________   // \\__________  \n    /   / \_____  \/  _/__//   \\____    /  \n   /   /   \   /   \  \    \____/   /___/_  \n   \________\ /    /_.     |__ _|_ /     /  \n- ------ - \______/D!`-----''- - :\______/ -»\n LHACheck V2.0 by CALYPSO ! Major Update !\n   New features ! It''s still the BEST !\n','\n',char(10)),'LhaCheck.Doc',replace('                            __               ____\n ._________. .____________ /_/\ _____________\   \ ____________. ._________.\n |         | |             \_\/               \___\            | |         |\n |.       /\_|__    __/\________  ____________/\  /    /\______|_|_       :|\n ||    _ /  \   \___\/  \       \/\           \ \/____/  \         \ _    ||\n |:    //   /\___\   \  /\_______\ \___________\/\    \  /\_________\\    O|\n |o   . \  /.    /____\// \__   __\/   ________// \____\/. \________/ .   :|\n |.      \//    /     /.    /    ///    /     /o       //   /_____\       .|\n |        \_________ /\__________/\_________ /_______ /\_________ /        |\n |         | |     \/                      \/   __  \/         |\/        .|\n |_________| |________________________________ /\_\ ___________| |_________|\n :         : :                                 \/_/_           : :    Sk!n :\n\n                                    PRESENTS\n\n                     LHACheck V2.0 coded by CALYPSO/LOGIC\n\n\nWHY SHOULD YOU USE THIS LHA-CHECKER IN YOUR BBS ?\n-------------------------------------------------\n\n        It''s the best and fastest LHA-Checker you''ve ever seen,\n        it''s 100% written in Assembler !\n\n        Removes ALL BBS-Ads !\n\n        Adds as many files (Ads) as you want !\n\n        You can add Time, Date, Nodenumber, Username and\n        Userlocation to your Addy !\n\n        It''s freely configurable with many options !\n        \n        Error-Handling routines included, so it will never crash\n        if an error appears or you''ve configured something wrong !\n\n        I made it :) !\n\n\nHOW TO INSTALL :\n----------------\n\n        Copy the whole LHACheck Directory wherever you want and\n        make an ASSIGN to it called CHECKER: !\n\n        Change your FCheck-Files LHA and LZH to this :\n\n        -----------Cut here-----------\n        CHECKER:LhaCheck\n        CHECK=ON STRIP=ON ADD=ON <Addyname>\n        WARNING: Skipping corrupt/extraneous data\n        Operation not entirely successful\n        -----------Cut here-----------\n\n        If you want you can switch some of the options :\n\n        CHECK=ON/OFF turn checking on/off (all in capitals) !\n\n        STRIP=ON/OFF turn stripping on/off !\n\n        ADD=ON/OFF turn adding on/off (includes textadding of time, date,\n                   node, username) !\n\n        <Addyname> The name of the textfile you want to add time, date,\n                   node, username (explained later) with full path !\n\n        For /X 3.x you can make icons including this, but\n        the easiest way is to copy the FCheck Dir included in the\n        archive to your FCheck Dir :) !!!\n\n        IMPORTANT:\n        ----------\n\n        Your LHA must be available through an AmigaDos-Path !!!\n        I use LHA V1.50, I don''t know if it works with older versions.\n        \n\nHOW TO STRIP AND ADD BBS-ADS :\n------------------------------\n\n        There are two Config-Files : LHACheck.Strip and LHACheck.Add !\n\n        The LHACheck.Strip includes all Filenames you want to\n        be stripped, wildcards allowed (e.g. *.displayme) !\n\n        Be careful with wildcards ! If you use them wrong it will\n        strip more files as you want !\n\n        The LHACheck.Add includes all Filenames you want to be\n        added, just specify there your BBS-Ad(s) !\n\n        Easy, isn''t it ?\n\n\nHOW TO ADD TIME, DATE, ETC. :\n-----------------------------\n\n        Ok, now about adding of time, date, nodenumber, username and\n        userlocation to your addy :\n\n        You can include wherever(!) you want these special symbols :\n\n        XX:XX:XX            ... will be replaced with the current time !\n\n        DD-MMM-YY           ... will be replaced with the current date !\n\n        §                   (shift-3) ... will be replaced with the NodeNr. !\n\n        ==UPLOADERNAME==    ... will be replaced with the name of the\n                                uploader (longer names will be cut off) !\n\n        =L=O=C=A=T=I=O=N=!= ... will be replaced by the User-Location !\n\n\n        Be sure that you have the filename <addyname> in your LHACheck.Add :)\n\n        Take a look at the examples in the archive...\n\n        If you don''t want to use this feature, then just do not\n        include the special symbols in your addy, but you have to\n        pass a valid <addyname> to the checker, or you will get an\n        error-message !\n\nLAST WORDS :\n------------\n        \n        If these Docs get lost you can save them with ''LHACheck ?'' !\n        (There''s a message concerning that if you run it from CLI !)\n\n        Now have fun with this great tool !\n\n        For Bugs (there are none), Ideas (yeah !) or just for fun\n        call my BBS :\n\n        BLACK MOON   +49-7054-8733   L^O^G^I^C Worldheadquarter !\n\n\n        See ya soon mates...\n                                                   Calypso !\n                                                   ~~~~~~~\n\nHISTORY :\n---------\n\n        V1.0    :       First public release ! (Written in 4 hours...)\n\n        V2.0    :       Major update, added switches for checking,\n                        stripping, adding and the option to add\n                        time, date, etc. to a textfile !\n                        (Written during 3 days...)\n\n\nTHANXS TO MY TESTERS :\n----------------------\n\n        Polaris and Rotor (Gates of Asgard), Giants (Creeping Death)\n        Freddy Krueger (Boiler Room), Dalai Lama (Point Blank),\n        Linebacker (The Mansion), Mercury (Doom of Extasy) !\n        \n\nP.S. : OTHER HIGH-QUALITY /X-TOOLS BY L^O^G^I^C\n-----------------------------------------------\n        \n        LGC-QN11.LHA    - QuickNew V1.1 by Calypso/LOGIC !\n                          (wait for V2.0, it''ll be great !!!)\n\n        LGC-STR.LHA     - StripAdd V1.0 (Text-Checker) by Warhawk/LOGIC\n\n        Get them... they''re worth it !\n\n··············································································\n\n              ( L·O·G·I·C  W·O·R·L·D·H·E·A·D·Q·U·A·R·T·E·R·S )\n  ____________    ______      ___________      _________    ____   ________\n  \      _    \__/     /      \_____     \  __/         \__/    | /     SP/\n   \____//     \      /_____  /     \     \/             \      |/       /\n ______ /     _/     /      \/      _\     \      |______/      /      _/\n/     //       \    /|       \      \_\     \     |      \              \\n\______________/\___/\_______/\_____________/\___________/______|\_______\\n             /\    /  \     __________  __________     _______\n            /  \  /    \____\         \/         /____/       \____\n           /    \/      \    \___      \     ___/     \     __     \\n          /      \       \     |/      /     \|       /     \|      \\n         /          /     \    /      /\      \      /       \       \\n        /______/\  /|______\_________/  \___________/\________\______/\n                 \/\n   dA pOSSE : cALYPSO/Logic - cASTOR/Logic, gHOSTRIDER/Logic, mOTIV8/sCX !\n \n  - DIAL! -   +49-7o54-8733  (U·S·R  D·U·A·L !)  +49-7o-Members!   - DIAL! -\n              ~~~~~~~~~~~~~                      ~~~~~~~~~~~~~~~\n     - aMIGA - sNES - fUN -  <-- sUPPORTING -->  - aMIGA - sNES - fUN -\n\n','\n',char(10)),NULL,'auto-added',12408,4,0,NULL,NULL,'lgc_lck2','scan',1780048567);
INSERT INTO door_catalog VALUES('lgc_nfic','LGC-NFIC.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGC-NFIC.LHA',NULL,'XIM','__.',NULL,'Small/Fast','LGC','______.  /__|__ __________.::. __________ \__   | / \___ \\__ _    /`::'' \__ _    / /    |/___.|   \/ __\__/_....  /   \__/_.',replace('           __.\n ______.  /__|__ __________.::. __________\n \__   | / \___ \\__ _    /`::'' \__ _    /\n  /    |/___.|   \/ __\__/_....  /   \__/_.\n /   __/    |!    \_\___   |:::_/    !    |\n \__________|______/_______|·::\_______dZG|\n«-------------------------- · : -----------»\n»  NFiComment v0.98 © 1994 cCs^eQx/LOGiC!  «\n«--( The Only Comment Door You''ll Need! )--»\n»  Lightbar/Conf_Relative/Small/Fast/Sexy  «\n«------------------------------------------»\n','\n',char(10)),'NFiComm.DOC',replace('\n.-- -- ---- - ------------------------------------------------[ /X Dezign ]-.\n|___ _ _________ __ ____________ __________ ______ ________ __________ _ ___|\n| _ __ _     __/_____________   \   ______/_\___ _/   ____/          _ __ _ |\n/\_\ ___ _   \        /    _/    \_ \__     \_   \     \_______    _ ___ /_/\\n\/_/__ _      \_     /            /   |      /    \     \     /      _ __\_\/\n|___ _ _____________/\___________/__________/_____|\_________/·aBn·_________|\n|                                                                           |\n`-[ Presents ]----------------------------------- ----------  - ---- ---- --''\n\n                 NFiComment v0.98 © 1994 cARCASS!^EQUiNOXE\n     ____                                                           ____\n ____\  /__________                                     ____________\  /____\n(___ \\// ________/     · What The Fuck Is This? ·      \__________ \\// ___)\n    \ \/ /                                                         \ \/ /\n     \  /                                                           \  /\n      \/   NFiComment is [surprise surprise] another Comment Door    \/\n           for /X. Before you scream ''Not another fucking useless\n           door!'', have a look at what this door offers.\n\n     ____                                                           ____\n ____\  /__________                                     ____________\  /____\n(___ \\// ________/    · Features? What Features? ·     \__________ \\// ___)\n    \ \/ /                                                         \ \/ /\n     \  /                                                           \  /\n      \/   · Written by us [ok, we''re biased]                        \/\n\n           · User Definable ANSi [incase you don''t like ours]\n\n           · Upto 50 SysOp''s/CoSysOp''s PER CONFERENCE!\n\n           · Conference Selective SysOps\n\n           · /<-CoOoOoOl LiGHTBAR technology! [chorus of ''ooooooh!'']\n\n           · Small, Fast, Powerful, Good Looking, Single.. oops..\n\n           · Keeps you company on those lonely nights..\n\n           · Without a doubt the best Comment door ever written!\n\n           · Written by us [told you we were biased..]\n\n     ____                                                           ____\n ____\  /__________                                     ____________\  /____\n(___ \\// ________/    · Help Me Install it, Daddy ·    \__________ \\// ___)\n    \ \/ /                                                         \ \/ /\n     \  /                                                           \  /\n      \/ [/X v3.x]                                                   \/\n\n           Copy these files in the archive to your directories,\n           they are as follows.\n\n           BBS:Doors/NFiComment/NFiComment.XiM\n           BBS:Doors/NFiComment/NFiComment.CFG\n\n           Copy the BBS/Commands/BBSCMD/C.Info to your\n           BBS:Commands/BBSCMD/\n\n           Libs/AEDoor.Library (© Sintax) to LIBS:\n\n\n         [/X v2.x/S-Express]\n\n           Copy these files in the archive to your directories,\n           they are,\n\n           BBS:Doors/NFiComment/NFiComment.XiM\n           BBS:Doors/NFiComment/NFiComment.CFG\n\n           Append the BBS/Commands/BBS.CMD to your BBS.CMD\n\n           Libs/AEDoor.Library (© Sintax) to LIBS:\n\n     ____                                                           ____\n ____\  /__________                                     ____________\  /____\n(___ \\// ________/     · But, Thats Not My Name! ·     \__________ \\// ___)\n    \ \/ /                                                         \ \/ /\n     \  /                                                           \  /\n      \/   So far, so good. You''re upto the config section.          \/\n\n           Best way is to look at the config and fuck round with\n           it, but some like to actually KNOW what the fuck they\n           are actually doing.\n\n           Lines beginning with ; are naturally ignored.\n\n        [Line 1]\n\n           Access level to USE the door. Anyone with access\n           LOWER than this number, will be dropped through to the\n           internal /X comment routine, thereby bypassing the\n           LiGHTBAR [Feature #5] Technology.\n\n        [Line 2]\n\n           Ansi colour #1. By changing this and lines 3 and 4, you\n           can more-or-less customize the look of NFiComment. Any\n           ANSi codes can be entered - depending on your taste, or\n           lack thereof.\n\n        [Line 3]\n\n           Ansi colour #2. As above, ''cept it pertains to a different\n           section of the ANSi.\n\n        [Line 4]\n\n           Ansi colour #3. As above, ''cept it pertains to a different\n           section of the ANSi. Play around with it, you''ll get the\n           idea..\n\n        [Line 5]\n\n           Hilight ANSi colour. What is displayed when the SysOp\n           is selected. Can be any valid ANSi codes, bold, italics,\n           underline, reverse video etc.\n\n        [Line 6]\n\n           Lowlight ANSi colour. Opposite of the above. What is\n           shown when the SysOp is NOT hilighted. Again, can be any\n           valid ANSi code, as suggested above.\n\n        [Line 7]\n\n           Default number of SysOps, ranging from 1 -> 50.\n\n        [Line 8]\n\n           From here you put your SysOp names and comments, or whatever\n           you want to be displayed, as an example,\n\n           EQUiNOXE          -           The Moose Keeper\n\n           But of course, it is up to you. You don''t have to have any\n           of the above. You can have just the SysOp name if you so\n           desire, or a comment, or their dick size or something..\n\n           There is 1 stipulation with the above. It *MUST* be 46chars\n           in length, padded with spaces if necessary.\n\n         [Line 9]\n\n           SysOp''s name as appears EXACTLY in your user.data\n\n         Repeat this for all the SysOps you wish to have.\n\n\n         [Selective Conference SysOp''s]\n\n           This is not needed, but can be used. With this, you can have\n           different SysOps in different conferences. You need not supply\n           details for every conference you have, just the ones you wish\n           to be different. Any conferences that do not have their own\n           seperate config, will use the default setup, as described\n           above.\n\n           Each conference configuration must begin with\n\n           ## BEGIN x ##\n\n           where x is the conference number - 1.\n\n           The rest is exactly like the default setup, containing the\n           number of SysOps, Definable Text, and Sysop Name.\n\n         Repeat this for any conferences you wish to contain a different\n         array of SysOps..\n\n           Finally, the last line must look like this\n\n           ## END ##\n\n           This is purely for the purpose of making the config file\n           just that little bit easier to understand.\n\n         If you still don''t get it, look at the config file and play\n         round with it.. you''ll get the hang of it.. eventually..\n\n     ____                                                           ____\n ____\  /__________                                     ____________\  /____\n(___ \\// ________/    · Can I Have MY Name On It? ·    \__________ \\// ___)\n    \ \/ /                                                         \ \/ /\n     \  /                                                           \  /\n      \/   Quite Simply, No. There is no Registered/Public version   \/\n           of this door. Should you, however, wish to get a custom\n           version, different ANSi, or you want something added to\n           it, we can be reached at the number below, or on any\n           major boards.\n\n     ____                                                           ____\n ____\  /__________                                     ____________\  /____\n(___ \\// ________/       ·  Shameless Plug Inc ·       \__________ \\// ___)\n    \ \/ /                                                         \ \/ /\n     \  /                                                           \  /\n      \/   Yeh, we had to do it.. we''re heartless bastards..         \/\n\n              Any Bugs, Suggestions, Death Threats, Money, or\n                 just for the fuck of it, give us a call..\n\n   ____             .   .    .   :                                       ·\n __\  /___ .________|___|____|_  |_______________________________________:\n \__\/\__ \|     /  ___/\__   /  /  ______  ___ \_____   /__\_____  \__  ¦\n  /   |/ \ \    /   /   |/   /   \____  \    \___/\   __/   |/  _   |/   |___.\n_/    ¦   \ \  /   /|   |   /_   ¦  _\   \_   \_/  \   \    |   /_  ¦  __/   |\n\_____:____\  /_________¦________:________/____/____\   \___¦_______:________|\n      ·     \/          :       ____   .   .         \___/  :     . ·\n _ _ ________.__________________\  / __|___|_____________ ._____\/_______\n  \\\\_____  \__ _    /__ _    /_\/|/  ___/\_____   /\__ \|     / ___   /\n      /  _   |/   \__/_/   \__/_   |   /   |/ \____/_./ \ \    /   \___/\n    _/   /_  ¦    !    \   !    \  ¦  /|   |   /_    ¦   \ \  /     \_ _ _\n dZG\________:__________\________\_:_______¦_________:____\  /_______////\n             ·                     ·       :               \/\n  · ·· LOGiC AHQ ^ OBSCENE AHQ ^ DARKPYRE D-ZiGN WHQ · · +6¹·²·545·467¹ ·· ·\n\n     ____                                                           ____\n ____\  /__________                                     ____________\  /____\n(___ \\// ________/ · Oh Gosh! I''d Just Like to Thank · \__________ \\// ___)\n    \ \/ /                                                         \ \/ /\n     \  /                                                           \  /\n      \/   [cARCASS!/LGC]·[For helping me get started in coding &]   \/\n                          [hassling me to finish this door!......]\n\n           [...SaDuS!...]·[1. Being a forgetful bastard :).......]\n                          [2. For being on the other end of the..]\n                          [phone when I was stuck with a coding..]\n                          [mess!.................................]\n\n           [...DANZiG...]·[For the way cool ANSi''s you''ve done...]\n                          [for us over the years.................]\n\n           [.SiNTAX/WøT.]·[The E Guru.. And Impending Saint :)...]\n\n           [..Sal-One!..]·[For keeping me up past my bed time :).]\n\n           [....WHiZ....]·[My GetDiskObjectNew() pal.............]\n\n           [..Calypso...]·[Obligatory Hello! :)..................]\n\n           [.Black Gunk.]·[For keeping us awake..and awake..and..]\n\n           [S''land Pizza]·[Garlic Bread? Bread? Garlic Wheel!....]\n\n    · All Obscene Members · Krion · Souri [dumb Laotion!] · wHiTe SaGe ·\n       · RasterBlaster · Collector · Dark Pearl · all LOGiC Members ·\n                · FireFlash/LSD · nocTurne · Elvin · BoWeN ·\n\n                      And Anyone Else We''ve Forgotten\n\n     ____                                                           ____\n ____\  /__________                                     ____________\  /____\n(___ \\// ________/ · The Sky is Falling! Moommmmmyy! · \__________ \\// ___)\n    \ \/ /                                                         \ \/ /\n     \  /                                                           \  /\n      \/   That''s it. The End. More Great Tools Coming Soon-ish..    \/\n\n','\n',char(10)),NULL,NULL,9890,2,0,NULL,NULL,NULL,'scan',1780048567);
INSERT INTO door_catalog VALUES('lgc_nt05','LGC-NT05.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGC-NT05.LHA','BelchNET','XIM','BelchNET',NULL,'Noisy','LGC','.:________________________    /________ /     /   _    /  ______/___/        / /     /\   /   /   /   /     \  \____/',replace('                _  _ ___ ________    (-fAZ!)\n  .:________________________    /________   \n   /     /   _    /  ______/___/        /   \n  /     /\   /   /   /   /     \  \____/    \n /________\____ /________\_____/_______\    \n+- -----------\/-- ---> S!X Development <--+\n|    BelchNET v0.5 by Noisy Belch/LOGIC    |\n|     The BEST NET you have EVER seen      |\n|      LAMER proof and with LOGFILE        |\n+--> /X.info is HiSTORY <> FAME is LAME <--+\n','\n',char(10)),'BelchNET.guide',replace('@database "BelchVIEW"\n@node main "Main"\n                            __               ____\n ._________. .____________ /_/\ _____________\   \ ____________. ._________.\n |         | |             \_\/               \___\            | |         |\n |.       /\_|__    __/\________  ____________/\  /    /\______|_|_       :|\n ||    _ /  \   \___\/  \       \/\           \ \/____/  \         \ _    ||\n |:    //   /\___\   \  /\_______\ \___________\/\    \  /\_________\\    O|\n |o   . \  /.    /____\// \__   __\/   ________// \____\/. \________/ .   :|\n |.      \//    /     /.    /    ///    /     /o       //   /_____\       .|\n |        \_________ /\__________/\_________ /_______ /\_________ /        |\n |         | |     \/                      \/   __  \/         |\/        .|\n |_________| |________________________________ /\_\ ___________| |_________|\n :         : :                                 \/_/_           : :    Sk!n :\n\n                      BelchNET v0.5 by Noisy Belch/LOGIC\n\n                                S!Express ONLY\n                                          \n                                  @{" Features " link "features"}\n                                  @{" History  " link "history"}\n                               @{" How to Install " link "install"}\n             @{" The fastest Independent Console Only Board in Europe " link "4Ndz Console Only"}\n\n@endnode\n@node "Features"\n\n   FIFO: realtime display of MsgBase up and download..\n\n   Nobody can fail to use it.. its too easy...\n\n   creates a logfile containing WHERE and WHEN the messages come from\n\n   -------------> SOON with FULLSCREEN editor... <-----------------------\n   \n@endnode\n\n@node "History"\n\n   0.1ß  saw SaLeS NET and laughed my ass off..\n   0.2ß  fixed bugs ...\n   0.3ß  fixed more bugs and changed the output\n   0.4ß  first tests...\n   0.5   first public release\n\n@endnode\n@node "Install"..\n\n   This NET is really simple to install... the only thing you habe\n   to do is to change the X in the name of CONFX.CMD into the\n   conference you want to use for BelchNET... and put it into\n   BBS:COMMANDS/ copy the belchnet to your doors\n\n   erm.. makr sure that u have LHA, COPY and DELETE in the\n   C: directory.... (or resident...(as just the name without C: ))\n\n   Here is shown how the CONFX.CMD file should look like\n\n---------------------------cut---------------------------\n*e        XM030doors:belchnet/belchnet\n*u        XM030doors:belchnet/belchnet\n*d        XM030doors:belchnet/belchnet\n---------------------------cut---------------------------\n\nthe [u] and [d] command are not really necessary.. but check out what\nbelchnet will do if you use them...\n\nAfter all that.. simply start belchnet with [e] one time and configure it\nand now have fun with that shit.. and always keep using the latest update...\n\n@endnode\n\n@node "4Ndz Console Only"\n\n                                     ___ _ _ _ __ _ __ _____\n                                    /\__\\n                  _   _ _ __ ____ __\/__/\n                                                                 ·aBn/fAZ!·\n                                                      ______ _____\n     _________  ________  _____ _____________________/   __/_  __/_________\n    _\___    /__\___   /_/____/_\    __________     /    ___/  ______     /\n   /    /     /    /    /     /  \      \/    /    /     /     /    /    /\n  /    /     /         /     /          /    _____/_    /_    /_   _____/_\n /____/     /_________/     /__________/___________/_____/_____/_________/\n  .  /______\        /_____/                                             :\n  |                                                                      |\n  | ...the fastest four nodes Independent Console only board in Europe.. |\n  |                                                                      !\n  |+            +49-52X-aSK-4iT -> USRobotics with Ringdown              o\n :¡.            +49-X24-fAST!   -> Euro ISDN with Ringdown!              ¡\n  |                                                                      |\n  |                -*- Sysop: Noisy Belch   Nup: AsK -*-                 |\n !|_____________________________________________________________________!|.\n ::::                                                                    !\n@next "main"\n@endnode\n','\n',char(10)),NULL,'auto-added',84049,6,0,NULL,NULL,'lgc_nt05','scan',1780048567);
INSERT INTO door_catalog VALUES('lgc_op41','LGC-OP41.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGC-OP41.LHA','display','XIM','display',NULL,NULL,'LGC','= |\__    ________/|\________ __/|\_____   = = |   |   \____.   |   .____/|   |    __|  = = |   |_/\ |   |   |   |   | |   |   |_/\  =',replace('============================================\n= |\__    ________/|\________ __/|\_____   =\n= |   |   \____.   |   .____/|   |    __|  =\n= |   |_/\ |   |   |   |   | |   |   |_/\  =\n= |_______\|_______|_______| |___|_______\ =\n=  --------------[PRESENTS]---------CST--->=\n= /X 2.x - /X 3.x  © OpeRaToR PaGe V4.1! © =\n============================================\n','\n',char(10)),'Operator.guide',replace('@database © Ken/LoGiC ShoToKaN PaLaCe - Operator Page V4.1\n@Author Ken / LoGiC ShoToKaN PaLaCe +32 2 270 04 07\n@Index MAIN\n\nCopyright © Ken / LoGiC ShoToKaN PaLaCe +32 2 270 04 07\n\n@Remark $VER: (January 10 1994, 21:00:00)\n@Remark AmigaGuide database for the Operator Page Documentation\n\n@node MAIN "Operator Page Documentation © Ken / LoGiC ShoToKaN PaLaCe\n\n                            __               ____\n ._________. .____________ /_/\ _____________\   \ ____________. ._________.\n |         | |             \_\/               \___\            | |         |\n |.       /\_|__    __/\________  ____________/\  /    /\______|_|_       :|\n ||    _ /  \   \___\/  \       \/\           \ \/____/  \         \ _    ||\n |:    //   /\___\   \  /\_______\ \___________\/\    \  /\_________\\    O|\n |o   . \  /.    /____\// \__   __\/   ________// \____\/. \________/ .   :|\n |.      \//    /     /.    /    ///    /     /o       //   /_____\       .|\n |        \_________ /\__________/\_________ /_______ /\_________ /        |\n |         | |     \/                      \/   __  \/         |\/        .|\n |_________| |________________________________ /\_\ ___________| |_________|\n :         : :                                 \/_/            : :    Sk!n :\n		  BeLGiAn HeAdQuArTeRs ! \n\n                                                                 ·          \n----------------------------------------------------------------------------\n\n\n                         @{"      Introduction      " Link Cap01}\n                         @{"      Requirements      " Link Cap02}\n                         @{"      Ken & Ryu Pub ;)  " rxs "address command ''display ken&ryu''"}\n                         @{"       Greetings        " Link Cap05}\n                         @{"   How to Contact me    " Link Cap06}\n\n\n         ---------------------------------------------------------\n                  Complete Docs for OpeRaTor Pager V4.1\n         ---------------------------------------------------------\n               The Documentation has been written by KeN/LoGiC\n\n@endnode\n@node Cap01 "Introduction"\n  =======================================================================\n  Operator Page I made in a couple of minutes, since non on the "market"\n  suited my needs. It is very simple to use, HAS NO BACKDOORS :), and it\n  does what it is supposed to do. It pages the sysop when he is around.\n  First i made it since i wanted to know also WHY a user would page me,\n  even if i was not around..so the pager prompts in both cases for a :\n  ''Reason to chat ?'' and then acts on the Chatflag being ON or OFF. The\n  message will always be written in the callerslog of the node and with\n  it i write if the Chatflag was ON, OFF or if the user was Blacklisted.\n  Yes, the Operator.cfg is a list of users that never get to bore the\n  sysop again. You can add as many as users in there, i''ll scan the file\n  untill the end. But don''t forget that the Handles in there must be the\n  exact same handle as the user in your user.data..so ToM is ToM and not\n  TOM or tom...sorry will fix that in some time.\n  Well have fun...\n  Suggestions and ideas are welcome on my bbs...use the SGST door to add\n  your ideas, suggestions or whatever..or doors you want to see for /X in\n  the future.\n                          ^^^^^^^^^^^^^^^^^^^^\n  	            This was arexx, now the new one :\n                    =================================\n\n  That was it for the old docs..Well the new one is quiet shorter and a\n  bit faster then its preprocessor. This one is coded in C and so ya can\n  gain speed. So no more Arexx doors...:) Well on a 030/040 there is \n  little difference in speed between a C or an Arexx Compiled Door. But\n  on a 500 the difference can be seen. Didn''t know that till now coz i\n  don''t have a 500 :)\n  Changes : New improved code, fast layout, and Operator.Cfg goes into S\n  directory (as asked by many users amonst you on my bbs.\n\n  Again some people requested that i made the opposite of the Boring ba..\n  that are int the S:Operator.cfg. So know you can put the ones that can\n  ALWAYS page you, no mather how the CHATFLAG is (ON or OFF) they will \n  override it, and well all is written in your callerslog...just check it\n  out. I forgot to mention that in the docs that there are 5 remarks in\n  you callerslog. \n \n		1. No Reason, No Chat + Message\n                2. Chatflag On        + Message\n                3. Chatflag Off       + Message\n                4. Override Chatflag  + message  >operator.pw\n                5. Boring Bas...      + Message  >operator.cfg\n\n  well that''s it for now. If any more ideas, requests, whatever..give me\n  a buzz..also if you want personalized doors for you bbs only. :)\n\n 					KeN/LoGiC\n  -EoF-\n  =======================================================================\n@endnode\n@node Cap02 "Requirements"\n  =======================================================================\n  To install Operator Pager you must have the following things:\n\n    Programm      Location           Description\n    ----------    --------           -----------\n    Operator.exe  Wherever           Main program\n    Operator.cfg  S:                 blacklist file (MUST BE IN THIS DIR!)\n    Operator.pw   S:                 Cosysops, friends, etc...\n\n  - an  Amiga Model (500/600/1000/1200/2000/2500/3000/4000/CDTV/CD³²)\n  - the installed Version of OS\2, OS\3 or higher\n    (Soft- or Hardware Version)\n  - the installed .INFO Files in the directories.\n  - AmiExpress v2.xx & v3.xx.\n\n  =======================================================================\n@endnode\n@node Cap05 "Greetings go to..."\n  =======================================================================\n\n                        Greetingz to:\n\n    \n Re/X\ö/MsT........................Am I going fast or am i going fast? :)\n ByteAndi/MsT .........File.Id Datafile, i have to change my ULChecker :(\n Axe/MsT..........What''s The difference between MsT /X DeSiGn and Mst? ;)\n Planet Master........You wanna have a module for The Edge, just ring. :)\n Bytemaster ...............WHERE DID MY MONEY GO ? NO NETMAIL NO FUN ! :(\n    \n  And everybody worldwide, who thinks he/she should be in it. Give\n  me a buzz and I''ll put you in next time. (Soon coz more modules\n  coming up very soon) If you have a module that you want for your\n  bbs, feel free to call, made within 4 dayz, free of charge !\n                                      ^\n	 	 		      | due to TO popular demand 2 dayz\n					  has become impossible! :)\n\n  Btw, are there any female sysops around who need a "leave HER a mesage"\n  version ? Just call me up and i''ll fix that. :) Don''t wanna be a sexist.\n\n\n                       GreeTings OfCoZ To :\n\n                  >>> All MeMBeRs oF LoGiC <<<\n\n    SNOW, ASCENDER, AGNUS, CALYPSO, CASTOR, COSMIC, GHOSTRIDER,\n    ROFOE, SCAMPY, TRAVELLER, TRONIX, WARHAWK, XENTEC, SNAKE/NAZGUL,\n\n      One left here, but i STILL don''t know who it was again ? :)\n\n    \n    \n  =======================================================================\n@endnode\n@node Cap06 "How to contact us..."\n  =======================================================================\n\n	Call me on ShoToKaN PaLaCe : LoGiC BhQ +32 (0) 2 270 04 07\n\n         /\___     /\______  __________/\______  /\________/\________       \n        /  \  \___/  \     \/\         \ \     \/  \       \ \       \      \n       /   /\__\  \  /\_____\ \_________\/\_____\  /\_______\/\_______\     \n      /   // \ /___\/ \\    _\/.  ______// \    _\/  \_ ____/. \_ ____/     \n._____\  /.   /    /   .\   ///   /    /.   \   //.  ____/ //  ____/_______.\n|____  \/________ /\________/________ /\________//   /_\  /    /_ Sk!n     |\n|\\//           \/                  \/        \/_____ / \/_____ /          |\n| \/     GiVe TheZe CooL LoGiC-BbS`s AlSo a RiNG!   \/        \/           |\n|                                                                          |\n|    HaPPy NaTion    +49 972-121-932   - SNOW      - NoDeS : 1  GHQ        |\n|    BlaCK MooN      +49 705-487-33    - CaLyPSo   - NoDeS : 2  WHQ   __   |\n|    SNaKe`S DeN     + 1 513-271-3213  - SNaKe     - NoDeS : 3  USHQ /\_\  |\n|    ShoToKaN PaLaCe +32 2-270-04-07   - KeN & Ryu - NoDeS : 3  BHQ  \/_/  |\n|__________________________________________________________________________|\n                                                                          \n  =======================================================================\n@endnode\n','\n',char(10)),NULL,'auto-added',59712,2,0,NULL,NULL,'lgc_op41','scan',1780048567);
INSERT INTO door_catalog VALUES('lgc_qn11','LGC-QN11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGC-QN11.LHA','QuickNew','XIM','QuickNew',NULL,'Calypso','LGC','|a  __/_________  \/  ____/_(_____)/  .__/_. |B  \      /  _/   \_ \__   \_   _/   |    | |n   \_   /         /   |    /   \    `    |',replace('.______ _ ________  _______  _____  ______\n|a  __/_________  \/  ____/_(_____)/  .__/_.\n|B  \      /  _/   \_ \__   \_   _/   |    |\n|n   \_   /         /   |    /   \    `    |\n|________/\________/________/_____\________|\n`---------------» rElEASEd «---------------''\n QuickNew V1.1 by Calypso - Great /X-Util !\n LOGIC - For the best quality you can get !\n','\n',char(10)),'QuickNew.Doc',replace('                            __               ____\n ._________. .____________ /_/\ _____________\   \ ____________. ._________.\n |         | |             \_\/               \___\            | |         |\n |.       /\_|__    __/\________  ____________/\  /    /\______|_|_       :|\n ||    _ /  \   \___\/  \       \/\           \ \/____/  \         \ _    ||\n |:    //   /\___\   \  /\_______\ \___________\/\    \  /\_________\\    O|\n |o   . \  /.    /____\// \__   __\/   ________// \____\/. \________/ .   :|\n |.      \//    /     /.    /    ///    /     /o       //   /_____\       .|\n |        \_________ /\__________/\_________ /_______ /\_________ /        |\n |         | |     \/                      \/   __  \/         |\/        .|\n |_________| |________________________________ /\_\ ___________| |_________|\n :         : :                                 \/_/_           : :    Sk!n :\n\n                                    PRESENTS\n\n                     QuickNew V1.1 coded by CALYPSO/LOGIC\n\n\nWHAT''S THE USE OF THIS TOOL ?\n-----------------------------\n\n        This tool creates a textfile which includes all filenames\n        today uploaded in every (selected) conference !\n\n        It creates a nice Ansi-Output which you can display\n        after the Logonscreen or after the Lastcallers (e.g. added\n        as tailer to SAmilog-Output) !\n\n        It''s very nice to get a quick overview of all new files.\n        Also the user can see if there are new files in a conference\n        which has not every day new files !\n\n        Ofcourse it''s another high-quality tool from me, 100% written\n        in Assembler for maximum speed !\n\n\nHOW TO INSTALL :\n----------------\n\n        First you have to edit the S:QuickNew.Config !\n\n        Put the Conference-Name in the first line and the\n        filename of the UploadDir (with full path) in the\n        second line. Third line next Conference-Name, etc.\n        You can put as many conferences as you want in the\n        Config-File !\n\n        Example :\n\n        ----------------------------(cut here)--------\n        >> Amiga Elite ! <<\n        BBS:Elite/Dir2\n        >> SNES Only ! <<\n        BBS:Consoles/Dir3\n        >> Requests (Amiga/SNES) ! <<\n        BBS:Private/Dir2\n        ----------------------------(cut here)--------\n\n        \n        You can run the tool from CLI for testing. The output\n        will be sent to your CLI-Window. Install it in your\n        Logoff-Batch using ''>'' to redirect the output to a file !\n\n        E.g. :\n\n        ----------------------------(cut here)--------\n        QuickNew >BBS:Screens/QuickNew.txt.gr\n        ----------------------------(cut here)--------\n        \n\n        An Example-Output is included in the archive !\n\n\n        If you don''t know where to place it in your BBS then\n        take a look at this :\n\n        Call it with MCI-Commands from your S:SAmilog.Tailer.txt(.gr)\n        like this :\n\n        ----------------------------(cut here)--------\n        ~SP                            \n        ~SS_BBS:Screens/QuickNew.txt.gr\n        ----------------------------(cut here)--------\n\n        ... and don''t forget that the first char in your\n        SAmilog.Header.txt(.gr) has to be a <~> !!!\n\nLAST WORDS :\n------------\n        \n        Now have fun with this great tool !\n\n        For Bugs (there are none), Ideas (yeah !) or just for fun\n        call my BBS :\n\n        BLACK MOON   +49-7054-8733   L^O^G^I^C Worldheadquarter !\n\n        If needed I can make you a special version of this tool\n        (e.g. changed output) !\n\n        See ya soon mates...\n                                                   Calypso !\n                                                   ~~~~~~~\n\nP.S. : OTHER HIGH-QUALITY /X-TOOLS BY L^O^G^I^C\n-----------------------------------------------\n\n        LGC-LHCK.LHA    - LHA-Check V1.0 by Calypso/LOGIC\n\n        LGC-STR.LHA     - StripAdd V1.0 (Text-Checker) by Warhawk/LOGIC\n\n\nGREETINGS:\n----------\n\n        - SNOW - SKIN - RAIDER - VENTOR - SAINT - POLARIS - SUBZERO -\n         - THE DUTCHMAN - WEDLOCK - CUJO - XAD - WORMEATER - G.E.M -\n           - TRINITY - EXOCET - SPLATT - DEXON - LINEBACKER -\n                    and ofcourse to all LOGIC Members !\n\n··············································································\n\n        ... ånð ðøn''t fø®get tø çå££ :\n  ____________    ______      ___________      _________    ____   ________\n  \      _    \__/     /      \_____     \  __/         \__/    | /     SP/\n   \____//     \      /_____  /     \     \/             \      |/       /\n ______ /     _/     /      \/      _\     \      |______/      /      _/\n/     //       \    /|       \      \_\     \     |      \              \\n\______________/\___/\_______/\_____________/\___________/______|\_______\\n             /\    /  \     __________  __________     _______\n            /  \  /    \____\         \/         /____/       \____\n           /    \/      \    \___      \     ___/     \     __     \\n          /      \       \     |/      /     \|       /     \|      \\n         /          /     \    /      /\      \      /       \       \\n        /______/\  /|______\_________/  \___________/\________\______/\n                 \/\n                               ThE øNe AnÐ øNlY\n  \n                  £^Ø^G^¡^Ç - W^Ø^®^£^Ð^H^E^Å^Ð^Q^U^Å^®^T^E^®\n                  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n      ¥øµ® MåsTe® ¡s ÇÅ£¥PSØ ånð h¡s Se®vånTs å®e ÇÅSTØ® ånð GHØST®¡ÐE® !\n                     ~~~~~~~                      ~~~~~~     ~~~~~~~~~~\n          Nøðe1 ±49~7o54~8733  #*+*#*+*#*+*#  Nøðe2 ±49~7o54~Øn£¡ne!\n          ~~~~~                               ~~~~~\n              ÅM¡gÅ +*#*+ SµpE® N¡nTenÐø +*#*+ X×X ånð mµçh mø®e...\n              ~~~~~       ~~~~~ ~~~~~~~~       ~~~\n','\n',char(10)),NULL,'auto-added',9246,6,0,NULL,NULL,'lgc_qn11','scan',1780048567);
INSERT INTO door_catalog VALUES('lgc_qn20','LGC_QN20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGC_QN20.LHA','QuickNew','XIM','QuickNew',NULL,'CALYPSO','LGC','_ __   /______________   // \\__________ /   / \_____  \/  _/__//   \\____    / /   /   \   /   \  \    \____/   /___/_',replace(' _ _______      _ __________ /\             \n  _ __   /______________   // \\__________  \n    /   / \_____  \/  _/__//   \\____    /  \n   /   /   \   /   \  \    \____/   /___/_  \n   \________\ /    /_.     |__ _|_ /     /  \n- ------ - \______/D!`-----''- - :\______/ -»\n QuickNew V2.0 by CALYPSO ! Major Update !\n      Grab this Masterpiece... NOW !\n','\n',char(10)),'QuickNew.Doc',replace('                            __               ____\n ._________. .____________ /_/\ _____________\   \ ____________. ._________.\n |         | |             \_\/               \___\            | |         |\n |.       /\_|__    __/\________  ____________/\  /    /\______|_|_       :|\n ||    _ /  \   \___\/  \       \/\           \ \/____/  \         \ _    ||\n |:    //   /\___\   \  /\_______\ \___________\/\    \  /\_________\\    O|\n |o   . \  /.    /____\// \__   __\/   ________// \____\/. \________/ .   :|\n |.      \//    /     /.    /    ///    /     /o       //   /_____\       .|\n |        \_________ /\__________/\_________ /_______ /\_________ /        |\n |         | |     \/                      \/   __  \/         |\/        .|\n |_________| |________________________________ /\_\ ___________| |_________|\n :         : :                                 \/_/_           : :    Sk!n :\n\n                                    PRESENTS\n\n                     QuickNew V2.0 coded by CALYPSO/LOGIC !\n\n    PROFESSIONAL TOOLS FOR PROFESSIONAL SYSOPS - GET THE REAL QUALITY !\n\n\nWHAT''S THE USE OF THIS TOOL ?\n-----------------------------\n\n        This tool creates a textfile which includes all filenames\n        today uploaded in every (selected) conference !\n\n        It creates a nice Ansi-Output which you can display\n        after the Logonscreen or after the Lastcallers (look for\n        examples how to do this later in this docs) !\n\n        Another possibilty is to make bulls for each conference !\n\n        It''s very nice to get a quick overview of all new files.\n        Also the users can see if there are new files in a conference\n        which has not every day new files !\n\n        Gives many additional informations, like Number of Files and\n        Fakes, total Megs for today and yesterday (configurable) !\n\n        Ofcourse it''s another high-quality tool from me, 100% written\n        in Assembler for maximum speed !\n        \n        ... and it''s the fastest/best-looking one !!!\n\nHOW TO INSTALL :\n----------------\n\n        First you have to edit your Config-File(s) !\n        (I use S:QuickNew.Config(x) !)\n\n        The first line of the Config-File includes the Prefix\n        displayed for every normal filename (normally a colour-code,\n        like [0m) !\n\n        The second line includes the Prefix displayed for every\n        deleted (nuked) file !!! So can show your nuked files\n        in RED or some other colour ! (I use [35m)\n\n        (The tool detects deleted files with the ''D'' in the Dirfile, so\n         be sure to use a Faker which supports this, e.g. Amifaker !)\n\n        The third line is the DisplayMode ! There are three available :\n\n        1 - Normal Displaymode   : All Files are shown right after\n                                   each other.\n\n        2 - Columns Displaymode  : The Files will be shown in columns\n                                   (my prefered one !)\n\n        3 - Centered Displaymode : The Lines with the Files will be\n                                   shown centered ! (also nice)\n\n\n    ->  Now you write down the text you want to display ! You can write\n    |   there what you want ! The end of your text must be marked with\n    |   a line only including a ''#'' !\n    |\n    |   After the text you give the full path + name of your upload-dirfile\n    |   of the corresponding conference !\n    |\n    ---- repeat this to show multiple Conferences !\n\n\n        Special Features :\n        ------------------\n\n        You can include special keywords in your text, these are :\n\n        @N      Number of todays files...    \n        @F      Number of todays fakes...    \n        @Y      Number of yesterdays files...\n        @Z      Number of yesterdays fakes...\n        @M.0    Todays Megs uploaded !       \n        @B.0    Yesterdays Megs uploaded !\n\n\n        Take a look at the included examples and change them to your\n        needs !\n\n\n        Here''s also an example :\n\n----------------------------(cut here)--------\n[0m\n[35m\n2\n[32mTodays Uploads in [33m>> Amiga Elite ! <<[34m :     [0m([35mFiles[33m: [36m@N[0m, [35mFakes[33m: [36m@F, [35mMegs[33m: [36m@M.0[0m)\n[35mYesterdays Statistics [0m: [32m@Y [36mFiles[33m, [32m@Z [36mFakes[33m, [32m@B.0 [36mMegs [33m!\n#\nBBS:Elite/Dir2\n[32mTodays Uploads in [33m>> SNES Only ! <<[34m :       [0m([35mFiles[33m: [36m@N[0m, [35mFakes[33m: [36m@F, [35mMegs[33m: [36m@M.0[0m)\n[35mYesterdays Statistics [0m: [32m@Y [36mFiles[33m, [32m@Z [36mFakes[33m, [32m@B.0 [36mMegs [33m!\n#\nBBS:Consoles/Dir2\n----------------------------(cut here)--------\n\n        \n        You can run the tool from CLI for testing. The output\n        will be sent to your CLI-Window. Install it in your\n        Logoff-Batch using ''>'' to redirect the output to a file !\n\n        E.g. :\n\n        ----------------------------(cut here)--------\n        QuickNew S:QuickNew.Config >BBS:Screens/QuickNew.txt.gr\n        ----------------------------(cut here)--------\n        \n\n        If you call it with different config-files you can make\n        different outputs, e.g. for every conference !\n\n        Example-Outputs are included in the archive !\n\n\n        Now some hints how you can display it in your BBS !\n\n        This is my Node(x)/Bull(x).txt(.gr) :\n\n        ----------------------------(cut here)--------\n        ~SS_BBS:Screens/LastCallers.txt.gr\n        ~SP                               \n        ~SS_BBS:Screens/QuickNew.txt.gr\n        ----------------------------(cut here)--------\n\n        So you can display the Lastcallers and the QuickNew right\n        after each other...        \n\n\nLAST WORDS :\n------------\n        \n        Now have fun with this great tool !\n\n        For Bugs (there are none), Ideas (yeah !) or just for fun\n        call my BBS :\n\n        BLACK MOON   +49-7054-8733   L^O^G^I^C Worldheadquarter !\n\n        (2 Nodes - USR Dual 16.8 !)\n\n        See ya soon mates...\n                                                   Calypso !\n                                                   ~~~~~~~\n\nTHANX TO :\n----------\n\n        Ron/Esquire for the Conference-Ansis !\n\n        My beta-testers :\n        -----------------\n                Dalai Lama/Point Plank\n                Rotor/Gates of Asgard\n                Freddy Krueger/Boiler Room\n\n\nHISTORY :\n---------\n\n        V1.0    Only for my BBS :) !\n\n        V1.1    First public release !\n\n        V2.0    The ultimate major update !\n                - Three different DisplayModes...\n                - Can show deleted files in another color...\n                - Shows lots of additional informations !\n                - Fully configurable (config-file, conf-text, colors, etc.) !\n\n\nP.S. : OTHER HIGH-QUALITY /X-TOOLS BY L^O^G^I^C\n-----------------------------------------------\n\n        LGC-STR.LHA     - StripAdd V1.0 (Text-Checker) by Warhawk/LOGIC\n\n        LGC-LCK2.LHA    - LHA-Check V2.0 by Calypso/LOGIC\n                          THE BEST LHA-CHECKER AVAILABLE :) !!!\n\n        LGC-ZIP.LHA     - ZIP-Check V1.0 by Calypso/LOGIC\n\n\nGREETINGS:\n----------\n\n      - G.E.M. - Runt&Scottie - Polaris - Skin - XAD - Giants - Andy -\n         - Wedlock - Subzero - Andeveron - Planet Master - Proton -\n            - Linebacker - Cujo - Raider - Mitch - Mr.T - Samir -\n\n                            - All LOGIC Members -\n\n··············································································\n\n              ( L·O·G·I·C  W·O·R·L·D·H·E·A·D·Q·U·A·R·T·E·R·S )\n  ____________    ______      ___________      _________    ____   ________\n  \      _    \__/     /      \_____     \  __/         \__/    | /     SP/\n   \____//     \      /_____  /     \     \/             \      |/       /\n ______ /     _/     /      \/      _\     \      |______/      /      _/\n/     //       \    /|       \      \_\     \     |      \              \\n\______________/\___/\_______/\_____________/\___________/______|\_______\\n             /\    /  \     __________  __________     _______\n            /  \  /    \____\         \/         /____/       \____\n           /    \/      \    \___      \     ___/     \     __     \\n          /      \       \     |/      /     \|       /     \|      \\n         /          /     \    /      /\      \      /       \       \\n        /______/\  /|______\_________/  \___________/\________\______/\n                 \/\n          dA pOSSE : cALYPSO/Logic - cASTOR/Logic, gHOSTRIDER/Logic !\n \n  - DIAL! -   +49-7o54-8733  (U·S·R  D·U·A·L !)  +49-7o-Members!   - DIAL! -\n              ~~~~~~~~~~~~~                      ~~~~~~~~~~~~~~~\n     - aMIGA - sNES - fUN -  <-- sUPPORTING -->  - aMIGA - sNES - fUN -\n','\n',char(10)),NULL,'auto-added',12787,6,0,NULL,NULL,'lgc_qn20','scan',1780048575);
INSERT INTO door_catalog VALUES('lgc_rb10','LGC-RB10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGC-RB10.LHA','RedBull','XIM','.    __  __ . __                  __',NULL,'WHiZ/LOGiC','LGC','.-» l__,|__|l__||l__'' S!X Development_\/_«-. |--------------''---------------------\/\/--| |      Red Bull V1.0 by WHiZ/LOGiC !       :',replace('    .    __  __ . __                  __\n.-» l__,|__|l__||l__'' S!X Development_\/_«-.\n|--------------''---------------------\/\/--|\n|      Red Bull V1.0 by WHiZ/LOGiC !       :\n|                                          |\n| Coded in 100% ASM ! Runs on S!X and /X ! |\n|                                          |\n|  This Door is a Global Online Bulletin   |\n:    Updater and only 1460 Bytes long !    |\n`------------------------------------------''\n','\n',char(10)),'RedBull.Doc',replace('                            __               ____\n ._________. .____________ /_/\ _____________\   \ ____________. ._________.\n |         | |             \_\/               \___\            | |         |\n |.       /\_|__    __/\________  ____________/\  /    /\______|_|_       :|\n ||    _ /  \   \___\/  \       \/\           \ \/____/  \         \ _    ||\n |:    //   /\___\   \  /\_______\ \___________\/\    \  /\_________\\    O|\n |o   . \  /.    /____\// \__   __\/   ________// \____\/. \________/ .   :|\n |.      \//    /     /.    /    ///    /     /o       //   /_____\       .|\n |        \_________ /\__________/\_________ /_______ /\_________ /        |\n |         | |     \/                      \/   __  \/         |\/        .|\n |_________| |________________________________ /\_\ ___________| |_________|\n :         : :                                 \/_/_           : :    Sk!n :\n\n                                PRESENTS\n\n                   Red Bull v1.0 coded by WHiZ/LOGiC !\n\n    PROFESSIONAL TOOLS FOR PROFESSIONAL SYSOPS - GET THE REAL QUALITY !\n\n\nWHAT''S THE USE OF THIS TOOL ?\n-----------------------------\n\n        This little Door is a replacement for the internal AmiExpress\n	or S!Express "B" command. With Red Bull you have the possibility\n 	of having your Bulletins online updated, meaning that you can\n	have a Batch executed prior displaying the Bulletin.\n	The advantage is clear: Your Logon- & Logoffbatches can be\n	much shorter. Red Bull is written in 100% Assembler and only\n	1460 bytes long!\n\nWHY SHOULD I USE IT ?\n---------------------\n\n        If you love speed and beautiful outputs this is the tool\n        you have been waiting for ! Install it, and see for yourself.\n\nHOW TO INSTALL THIS TOOL :\n--------------------------\n\n        BBS/Doors/RedBull/RedBull      --> DOORS:RedBull/RedBull\n        BBS/Doors/RedBull/RedBull.Doc  --> DOORS:RedBull/RedBull.Doc\n        Libs/AEDoor.library            --> LIBS:\n\n        Append BBS/Commands/BBS.CMD to your BBS:Commands/BBS.CMD !\n\n        1. Create a Directory called Bulletins in BBS:.\n	2. Create a Directory in BBS:Bulletins called Batch.\n	3. The Batch Directory will contain all the Bulletins you want\n	   to update, e.g. if you want to update Bulletin #2 you\n           need a Batch called BBS:Bulletins/Batch/2.\n           BBS:Bulletins/Batch/2 can look something like this:\n	   Quicknew S:QuickNew.Config >BBS:Bulletins/2\n           \n           Example: You want to Update Bulletin INFO:\n\n           a) Name of Batch: BBS:Bulletins/Batch/INFO\n           b) Content of INFO: UserList >Bulletins/INFO\n           c) Output User will see (when typing INFO): BBS:Bulletins/INFO\n\n	4. All the Bulletins which you don''t want to update need to\n           be located in your BBS:Bulletins/ Directory, e.g.:\n           BBS:Bulletins/13\n	5. Create or Edit your Bulletin Menu and copy it into the\n           BBS:Bulletins/ Directory under the name: Menu.TXT.\n        6. Copy the supplied AEDoor.library v2.x (© by Sintax/WOT) in your\n           LIBS: Directory (AEDoor.library version >=2 is required).\n\n        That''s all...\n\n\nLAST WORDS :\n------------\n\n        It has been tested for a long time from S!X developers, so you can be\n        sure this tool is 100% bug-free !\n\n        S!X running with official S!X tools NEVER crashes, like other\n        BBS software does, hehe...\n\n        See ya soon mates...\n                                                                 WHiZ/LOGiC !\n                                                                 ~~~~~~~~~~~~\n\n\nIMPORTANT :\n-----------\n\n\n        Read the included LOGIC.NFO text !\n                          ---------\n        It contains important information about S!X and LOGIC and how\n        to contact us ! Read it !\n                        ---------\n\n\nSOON TO BE RELEASED TOOLS - ALL CODED IN ASM! :\n-----------------------------------------------\n\n       Turbo Boost v2.0 - Another Text Adder/Checker/Stripper !\n       (ModSaM vx.x)    - The Ultimate Pager (Modules/Samples and more).\n                          Now coded in pure ASM !\n                          Update to the lame ARexx Release !\n       FrontInfo v1.0   - The Best Frontend you''ve ever seen!\n\nGREETINGS:\n----------\n\n	The Champ · Halfast · Mr Hyde · The Fly · Freddy Krueger · Franky\n	Joker/ZZC · Dalai Lama · SchwabenPoweR · Red Alert · Rioter · BBC\n	2-Cool · g.E.m. · Sid Vicious · Ccs & Eqx · Calypso · TerrorizeR\n	Dexter/aFL · Foxx''n''Lynxx · Ernesto · Jive · Sintax · Treach\n	The Addict · Cobra · Manta · Sce · Hot Kid · Rofoe · Don Dog\n        Cas(ch)tor · Warhawk · Dragon · Warlord · and all LOGiC Members !\n	\n\n      _______/\ __________________ /\_______/\______________ ___________/\\n     /     ___//   ____________   \\______  \________  \    |    /   ____/\n  Mb/  ___/___/   / \   \/   / \   \|    |\  \|   _|/ _/\__ | __/  __/___\n  _/   \_    /    \_/    \   \_/    \    |/   \   \__  \  /   \/   \_/   \\n  \    _/    \           /          /          \   |/   \/     \_         \\n   \___\  ___|\_________/\_________/|__________/________/_______/_________/\n        \/                                                                \n\nClick...\n\n··············································································\n                                                   ·\n    _ ______________________           ____________¦________________\n   ·   ________   /   _____/________  /· ______/   |   \______    o/  ·\n   ¦____/   _____/_____   /\    \   \//  /____/         \    /   //___¦\n   |   /____/   /________/  \______ /_______ /_____|_____\_______/Sk¡n|\n   |                         \ _______\    \/      ¦                  |\n   |                          \/                   ·                  |\n   |                                      ___        ·                |\n   |                                     /\__\ _     ¦_____    _ _____|\n___|________________  /\______/\ __ /\   \/__/  ____ |  _ /____ _    /|___\n\ _ o   _ /  __    /_/___  _ /  \\// o\________|    \|  //o    \/   /    /\n \//    \/  ______/    |/  //    \/   \\       /___\ \  //     /_______ /\n /_______\______ /_____/   /____\  /____\_____/     \  /_________\    \/\n   |           \/      \___\     \/                  \/               |\n   |__________________________________________________________________|\n     \n                       ·p·S·Y·C·H·O·  ·t·E·R·M·i·N·A·L·\n \n                        - lOGiC gERMAN hEADQUARTERS! -\n         \n       sYSOP tEAM: wHiZ/lOGiC - cALYPSO/gOD^lOGiC - [-tREACH!]/-aC !\n       \n      cLOSED pURE eLiTE sYSTEM kiCKiNG aSS wiTH uSR 28.8/v34 mODEMS !\n','\n',char(10)),NULL,NULL,16915,6,0,NULL,NULL,'lgc_rb10_redbull','scan',1780048567);
INSERT INTO door_catalog VALUES('lgc_si10','LGC-SI10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGC-SI10.LHA','S!XInfo','XIM','List',NULL,'WHiZ/LOGiC','LGC','.-» l__,|__|l__||l__'' S!X Development_\/_«-. |--------------''---------------------\/\/--| |       S!XInfo V1.0 by WHiZ/LOGiC !       :',replace('    .    __  __ . __                  __\n.-» l__,|__|l__||l__'' S!X Development_\/_«-.\n|--------------''---------------------\/\/--|\n|       S!XInfo V1.0 by WHiZ/LOGiC !       :\n|                                          |\n|     Pure ASM ! Runs with S!X and /X !    |\n|                                          |\n|      This door displays an important     |\n:  message to every user in a funny way !  |\n`------------------------------------------''\n','\n',char(10)),'S!XInfo.Doc',replace('                            __               ____\n ._________. .____________ /_/\ _____________\   \ ____________. ._________.\n |         | |             \_\/               \___\            | |         |\n |.       /\_|__    __/\________  ____________/\  /    /\______|_|_       :|\n ||    _ /  \   \___\/  \       \/\           \ \/____/  \         \ _    ||\n |:    //   /\___\   \  /\_______\ \___________\/\    \  /\_________\\    O|\n |o   . \  /.    /____\// \__   __\/   ________// \____\/. \________/ .   :|\n |.      \//    /     /.    /    ///    /     /o       //   /_____\       .|\n |        \_________ /\__________/\_________ /_______ /\_________ /        |\n |         | |     \/                      \/   __  \/         |\/        .|\n |_________| |________________________________ /\_\ ___________| |_________|\n :         : :                                 \/_/_           : :    Sk!n :\n\n                                PRESENTS\n\n                   S!XInfo v1.0 coded by WHiZ/LOGiC !\n\n    PROFESSIONAL TOOLS FOR PROFESSIONAL SYSOPS - GET THE REAL QUALITY !\n\n\nWHAT''S THE USE OF THIS TOOL ?\n-----------------------------\n\n        It displays an important message (e.g. change of SYSPW) to every\n        user during logon sequence.\n\n        The user is forced to watch it a certain time.\n\n        It looks very funny, so check it out !\n\n\nWHY SHOULD I USE IT ?\n---------------------\n\n        If you love speed and beautiful outputs this is the tool\n        you have been waiting for ! Install it, and see for yourself.\n\nHOW TO INSTALL THIS TOOL :\n--------------------------\n\n        Copy these files :\n\n        BBS/Doors/S!XInfo/S!XInfo      --> DOORS:S!XInfo/S!XInfo\n        BBS/Doors/S!XInfo/S!XInfo.Txt  --> DOORS:S!XInfo/S!XInfo.Txt\n        BBS/Doors/S!XInfo/S!XInfo.Doc  --> DOORS:S!XInfo/S!XInfo.Doc\n        Libs/AEDoor.library            --> LIBS:\n\n\n        Append BBS/Commands/BBS.CMD to your BBS:Commands/BBS.CMD !\n\n\n        The S!XInfo.Txt is the text to be displayed... change it to\n        your needs !\n\n        Call it during logon sequence from any bull using MCI-Command :\n\n        ~CC_S!XINFO\n\n\n        That''s all...\n\n\nLAST WORDS :\n------------\n\n        It has been tested for a long time from S!X developers, so you can be\n        sure this tool is 100% bug-free !\n\n        S!X running with official S!X tools NEVER crashes, like other\n        BBS software does, hehe...\n\n        See ya soon mates...\n                                                                 WHiZ/LOGiC !\n                                                                 ~~~~~~~~~~~~\n\n\nIMPORTANT :\n-----------\n\n\n        Read the included LOGIC.NFO text !\n                          ---------\n        It contains important information about S!X and LOGIC and how\n        to contact us ! Read it !\n                        ---------\n\n\nSOON TO BE RELEASED TOOLS - ALL CODED IN ASM! :\n-----------------------------------------------\n\n       Turbo Boost v2.0 - Another Text Adder/Checker/Stripper !\n       BullUp v2.0      - /X & S!X Online Bulletin Updater !\n       (ModSaM vx.x)    - The Ultimate Pager (Modules/Samples and more).\n                          Now coded in pure ASM !\n                          Update to the lame ARexx Release !\n       FrontInfo v1.0   - The Best Frontend you''ve ever seen!\n\nGREETINGS:\n----------\n\n	The Champ · Halfast · Mr Hyde · The Fly · Freddy Krueger · Franky\n	Joker/ZZC · Dalai Lama · SchwabenPoweR · Red Alert · Rioter · BBC\n	2-Cool · g.E.m. · Sid Vicious · Ccs & Eqx · Calypso · TerrorizeR\n	Dexter/aFL · Foxx''n''Lynxx · Ernesto · Jive · Sintax · Treach\n	The Addict · Cobra · Manta · Sce · Hot Kid · Rofoe · Don Dog\n        Cas(ch)tor · Warhawk · Dragon · Warlord · and all LOGiC Members !\n	\n\n      _______/\ __________________ /\_______/\______________ ___________/\\n     /     ___//   ____________   \\______  \________  \    |    /   ____/\n  Mb/  ___/___/   / \   \/   / \   \|    |\  \|   _|/ _/\__ | __/  __/___\n  _/   \_    /    \_/    \   \_/    \    |/   \   \__  \  /   \/   \_/   \\n  \    _/    \           /          /          \   |/   \/     \_         \\n   \___\  ___|\_________/\_________/|__________/________/_______/_________/\n        \/                                                                \n\nClick...\n\n··············································································\n                                                   ·\n    _ ______________________           ____________¦________________\n   ·   ________   /   _____/________  /· ______/   |   \______    o/  ·\n   ¦____/   _____/_____   /\    \   \//  /____/         \    /   //___¦\n   |   /____/   /________/  \______ /_______ /_____|_____\_______/Sk¡n|\n   |                         \ _______\    \/      ¦                  |\n   |                          \/                   ·                  |\n   |                                      ___        ·                |\n   |                                     /\__\ _     ¦_____    _ _____|\n___|________________  /\______/\ __ /\   \/__/  ____ |  _ /____ _    /|___\n\ _ o   _ /  __    /_/___  _ /  \\// o\________|    \|  //o    \/   /    /\n \//    \/  ______/    |/  //    \/   \\       /___\ \  //     /_______ /\n /_______\______ /_____/   /____\  /____\_____/     \  /_________\    \/\n   |           \/      \___\     \/                  \/               |\n   |__________________________________________________________________|\n     \n                       ·p·S·Y·C·H·O·  ·t·E·R·M·i·N·A·L·\n \n                        - lOGiC gERMAN hEADQUARTERS! -\n         \n       sYSOP tEAM: wHiZ/lOGiC - cALYPSO/gOD^lOGiC - [-tREACH!]/-aC !\n       \n      cLOSED pURE eLiTE sYSTEM kiCKiNG aSS wiTH uSR 28.8/v34 mODEMS !\n','\n',char(10)),NULL,'auto-added',15029,6,0,NULL,NULL,'lgc_si10','scan',1780048567);
INSERT INTO door_catalog VALUES('lgc_st20','LGC-ST20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGC-ST20.LHA','Status','XIM','List',NULL,'WHiZ/LOGiC','LGC','.-» l__,|__|l__||l__'' S!X Development_\/_«-. |--------------''---------------------\/\/--| |       Status V2.0 by WHiZ/LOGiC !        :',replace('    .    __  __ . __                  __\n.-» l__,|__|l__||l__'' S!X Development_\/_«-.\n|--------------''---------------------\/\/--|\n|       Status V2.0 by WHiZ/LOGiC !        :\n|                                          |\n|  Pure ASM ! Needs S!X V0.39n1+ to run !  |\n|                                          |\n|  This is a fucking great-looking Status  |\n:     Door, exclusively for S!Express !    |\n`------------------------------------------''\n','\n',char(10)),'Status.Doc',replace('                            __               ____\n ._________. .____________ /_/\ _____________\   \ ____________. ._________.\n |         | |             \_\/               \___\            | |         |\n |.       /\_|__    __/\________  ____________/\  /    /\______|_|_       :|\n ||    _ /  \   \___\/  \       \/\           \ \/____/  \         \ _    ||\n |:    //   /\___\   \  /\_______\ \___________\/\    \  /\_________\\    O|\n |o   . \  /.    /____\// \__   __\/   ________// \____\/. \________/ .   :|\n |.      \//    /     /.    /    ///    /     /o       //   /_____\       .|\n |        \_________ /\__________/\_________ /_______ /\_________ /        |\n |         | |     \/                      \/   __  \/         |\/        .|\n |_________| |________________________________ /\_\ ___________| |_________|\n :         : :                                 \/_/_           : :    Sk!n :\n\n                                PRESENTS\n\n                   Status v2.0 coded by WHiZ/LOGiC !\n\n    PROFESSIONAL TOOLS FOR PROFESSIONAL USERS - GET THE REAL QUALITY !\n\n\nWHAT''S THE USE OF THIS TOOL ?\n-----------------------------\n\n        It''s a fucking great looking Status Door for S!X V0.39n1+ only !\n\n\nWHY SHOULD I USE IT ?\n---------------------\n\n        If you love speed and beautiful outputs this is the tool\n        you have been waiting for ! Install it, and see for yourself.\n\nHOW TO INSTALL THIS TOOL :\n--------------------------\n\n        Copy these files :\n\n        System/Status              --> BBS:System\n        System/Status.Doc          --> BBS:System\n        Libs/AEDoor.library        --> LIBS:\n\n        That''s all...\n\n\nLAST WORDS :\n------------\n\n        It has been tested for a long time from S!X developers, so you can be\n        sure this tool is 100% bug-free !\n\n        S!X running with official S!X tools NEVER crashes, like other\n        BBS software does, hehe...\n\n        See ya soon mates...\n                                                                 WHiZ/LOGiC !\n                                                                 ~~~~~~~~~~~~\n\n\nIMPORTANT :\n-----------\n\n\n        Read the included LOGIC.NFO text !\n                          ---------\n        It contains important information about S!X and LOGIC and how\n        to contact us ! Read it !\n                        ---------\n\n\nSOON TO BE RELEASED TOOLS - ALL CODED IN ASM! :\n-----------------------------------------------\n\n       Turbo Boost v2.0 - Another Text Adder/Checker/Stripper !\n       BullUp v2.0      - /X & S!X Online Bulletin Updater !\n       (ModSaM vx.x)    - The Ultimate Pager (Modules/Samples and more).\n                          Now coded in pure ASM !\n                          Update to the lame ARexx Release !\n       FrontInfo v1.0   - The Best Frontend you''ve ever seen!\n\nGREETINGS:\n----------\n\n	The Champ · Halfast · Mr Hyde · The Fly · Freddy Krueger · Franky\n	Joker/ZZC · Dalai Lama · SchwabenPoweR · Red Alert · Rioter · BBC\n	2-Cool · g.E.m. · Sid Vicious · Ccs & Eqx · Calypso · TerrorizeR\n	Dexter/aFL · Foxx''n''Lynxx · Ernesto · Jive · Sintax · Treach\n	The Addict · Cobra · Manta · Sce · Hot Kid · Rofoe · Don Dog\n        Cas(ch)tor · Warhawk · Dragon · Warlord · and all LOGiC Members !\n	\n\n      _______/\ __________________ /\_______/\______________ ___________/\\n     /     ___//   ____________   \\______  \________  \    |    /   ____/\n  Mb/  ___/___/   / \   \/   / \   \|    |\  \|   _|/ _/\__ | __/  __/___\n  _/   \_    /    \_/    \   \_/    \    |/   \   \__  \  /   \/   \_/   \\n  \    _/    \           /          /          \   |/   \/     \_         \\n   \___\  ___|\_________/\_________/|__________/________/_______/_________/\n        \/                                                                \n\nClick...\n\n··············································································\n                                                   ·\n    _ ______________________           ____________¦________________\n   ·   ________   /   _____/________  /· ______/   |   \______    o/  ·\n   ¦____/   _____/_____   /\    \   \//  /____/         \    /   //___¦\n   |   /____/   /________/  \______ /_______ /_____|_____\_______/Sk¡n|\n   |                         \ _______\    \/      ¦                  |\n   |                          \/                   ·                  |\n   |                                      ___        ·                |\n   |                                     /\__\ _     ¦_____    _ _____|\n___|________________  /\______/\ __ /\   \/__/  ____ |  _ /____ _    /|___\n\ _ o   _ /  __    /_/___  _ /  \\// o\________|    \|  //o    \/   /    /\n \//    \/  ______/    |/  //    \/   \\       /___\ \  //     /_______ /\n /_______\______ /_____/   /____\  /____\_____/     \  /_________\    \/\n   |           \/      \___\     \/                  \/               |\n   |__________________________________________________________________|\n     \n                       ·p·S·Y·C·H·O·  ·t·E·R·M·i·N·A·L·\n \n                        - lOGiC gERMAN hEADQUARTERS! -\n         \n       sYSOP tEAM: wHiZ/lOGiC - cALYPSO/gOD^lOGiC - [-tREACH!]/-aC !\n       \n      cLOSED pURE eLiTE sYSTEM kiCKiNG aSS wiTH uSR 28.8/v34 mODEMS !\n','\n',char(10)),NULL,'auto-added',16228,6,0,NULL,NULL,'lgc_st20','scan',1780048567);
INSERT INTO door_catalog VALUES('lgc_st26','LGC_ST26.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGC_ST26.LHA','NONBBS-STRIPADD26','XIM','INSTALL',NULL,'\X/arhawk/LGC','LGC','| /   |___/   .   \/   __________/        /| |/    |   \   |    \   |   \     |   |___/ | /     |    \  |     \  |    \    |   |    \|',replace('+  ___.    _______  _______________________+\n| /   |___/   .   \/   __________/        /|\n|/    |   \   |    \   |   \     |   |___/ |\n/     |    \  |     \  |    \    |   |    \|\n\________  /________/_____  /____|______  /|\n+-----÷e÷\/------presents-\/------------\/-+\nStrip''N''Add V2.6 by \X/arhawk/LGC - Bugfix !\n The BEST and FASTEST textchecker for /X !\n','\n',char(10)),'STRIPADD26.DOC',replace('                           __               ____\n._________. .____________ /_/\ _____________\   \ ____________. ._________.\n|         | |             \_\/               \___\            | |         |\n|.       /\_|__    __/\________  ____________/\  /    /\______|_|_       :|\n||    _ /  \   \___\/  \       \/\           \ \/____/  \         \ _    ||\n|:    //   /\___\   \  /\_______\ \___________\/\    \  /\_________\\    O|\n|o   . \  /.    /____\// \__   __\/   ________// \____\/. \________/ .   :|\n|.      \//    /     /.    /    ///    /     /o       //   /_____\       .|\n|        \_________ /\__________/\_________ /_______ /\_________ /        |\n|         | |     \/                      \/   __  \/         |\/        .|\n|_________| |________________________________ /\_\ ___________| |_________|\n:         : :                                 \/_/_           : :    Sk!n :\n                                  PrEsEnTs:\n                                  ---------\n\n                              STRIP`N`ADD V2.6\n\n                        coded by \X/arhawk OF LOGIC\n\n                          RELEASE DATE: 27.02.1994\n\nWHAT IS THE TOOL ABOUT ?\n------------------------\n\nIt`s an /X-Utility for removing BBS-addys specified in a configuration-file\nfrom an uploaded textfile and for adding your own bbs-addy if you want. You\ncan define whether you want NO own addy added, FRONT or TAIL addy or both.\nIt`s for those people who don`t like textfiles containing 90% of bbs-addys\nand 10% of the real text.\n\n\nWHY USE MY ONE AND NOT ANOTHER STRIPPER ?\n-----------------------------------------\n\nHmm, well that can be easily seen at the speed it works with. It`s the\nfastest and bestest Stripper`n`Adder coded yet ! And you can include the\nuploader-name, the date&time, etc.\n\n\nHOW TO USE IT ?\n---------------\n\nThe usage will be displayed if you just type in the name of the prg or if\nyou make a mistake in defining the arguments. The usage is the following:\n\nSTRIPADD Config-File <FRONT Addyname1> <TAIL Addyname2> Original-File\n\nConfig-File   -> Name of the Configuration-File\nOriginal-File -> Name of the file to be stripped and to be added to\nFRONT         -> Signal that you want a addy to be added in front of the\n                 textfile\nTAIL          -> Signal that you want a addy to be added to the end of the\n                 textfile\nAddyname1/2   -> Names of your own BBS-addys\n\nNote: If you want both - a FRONT and a TAIL addy - then first type\nFRONT+name1 and then type TAIL+name2. Otherwise the prg says "BAD ARGS...".\nAnd "FRONT" & "TAIL" must be in capital letters !\n\nHere''s an example how you can build up your FCheck-File for /X :\n\n-----------Cut here-----------\nSTRIPADD\nConfig-File FRONT Addy1.txt TAIL Addy2.txt\nERROR\nNOT ENOUGH MEMORY\n-----------Cut here-----------\n\nOr simply use the FCheck/TXT or FCheck/TXT.Info included in the archive !\n\n\nHOW IS THE CONFIG-FILE BUILT UP ?\n---------------------------------\n\nThe config-file is built up by using an identification-string\n(~N_A <cr>)so that the prg knows when a new addy starts. After\nthat ID-string comes the bbs-add you want to strip out. Only put that\npart of the addy into the cfg-file that contains real text (no spaces\nor free lines at the beginning and end), because you can never know if\nthe bbs-addy always has free lines or spaces in front or after itself.\nThe spaces and free lines are removed automatically.\nDo not write the ID-String in front of the first addy !\n\nIn case you have Addies which change (e.g. with built-in uploadtime),\nyou can replace the chars which change with ''?'' (e.g. change the\nuploadtime from 10:20:05 to ??:??:??) !\nThe ''?'' is a kind of joker...\nOr if you are too lazy to type 5 "?", you can also type "?#". This feature\nlet`s the stripper ignore the rest of the line.\ne.g:\n\nblablabla ?# Uploadername: \X/arhawk   Date: 30-Oct-93\n\n          ^^ Do ya know what I mean !!!\n\nGot it ??? If not, there`s an example CFG-FILE in the archive !!!\n\nHOW TO ADD TIME, DATE, ETC. :\n-----------------------------\n\n        Ok, now about adding of time, date, nodenumber, username and\n        userlocation to your OWN addy :\n\n        You can include wherever(!) you want these special symbols :\n\n        XX:XX:XX            ... will be replaced with the current time !\n\n        DD-MMM-YY           ... will be replaced with the current date !\n\n        §                   (shift-3) ... will be replaced with the NodeNr. !\n\n        ==UPLOADERNAME==    ... will be replaced with the name of the\n                                uploader (longer names will be cut off) !\n\n        =L=O=C=A=T=I=O=N=!= ... will be replaced by the User-Location !\n\n\n        Take a look at the example in the archive...\n\n        If you don''t want to use this feature, then just do not\n        include the special symbols in your addy.\n\n        (NOTE: This is 100% compatible to Calypso''s LHACheck V2.0, so you\n         can use the same textfile to add if you want !)\n\nNOTE2: I also included a NON-BBS-Version of the Stripper which doesn`t\n       have the feature to include the U/L-name,etc., so it is not in need\n       of the NodeX.user file, so you can use it from DirOpus or SID...\n       I removed the ansies from the NON-BBS-Version, coz. that looks a bit\n       strange ! :-)\n\nHISTORY :\n---------\n\nVersion 1: First Stripper in the scene, but a little bit (too) slow...\n\nVersion 2: Much, much faster ! Added the feature to add the uploadername,\n           his location, time and date and the nodenumber, the TXT-file was\n           uploaded on.\nVersion 2.5:\n           Added the "?#" feature, so the CFG-File is compatible to the\n           CFG-File of BBC`s TexRIP, so if you want to use mine, you just\n           have to replace "#?" with "?#" and "~next addy:" with "N_A" !\n           Now the stripper displays how many addies in per cent were in\n           the stripped file.\nVersion 2.6:\n           Mini speed improvement. Following bug removed: When the U/L name\n           or the location was longer than the keyword (==UPLOADERNAME==),\n           then the whole name/location was put into the addy. Now, only the\n           length of the keyword is copied.. This led to some ugly looking\n           addies...\n           Second, when the .TXT File had the length 0 (ZERO), the stripper\n           crashed.. same with the config-file or nodex.user file.. Now\n           it works 100% !\n\nGREETZ:\n-------\n\nFirst to all LOGIC members.\n\nBBC: Mal wieda Splash oda ?\nANDY: Thanks for the idea !\nJOKER: Sorry, daß ich des PowerPack Teil net rein hab, aber denk mal: Wenn\n       jemand `nen TXT uppt, der gepackt is, isses erstens selber schuld und\n       zweitens zerstört des FILE_ID.diz des .pp File so oder so..\nSTEFF: Hee, melde Dich !\nJUSTICE: Wir haben den erste Kreuz-Kurs nu, wa !\nEAZY-E: Rave on !\nTACCY: Is E.T. on XTC ?\nSUNSET: Hehe, nice mails.\nEOL: Peitsch mich !\nGIANTS: Install it.. It doesn`t crash ya BBS !\nE.F.A.: 2400 is too less :-(\n\nWell, that`s it folks. Hope you like this tool and put it into your BBS.\nSigning off...\n\n                     \X/arhawk OF LOGIC !!!\n\nP.S. : Ofcourse it''s written 100% in Assembler for maximum speed !\n\n··············································································\n\n               _ ________           _ ______________    \n         /\_______    _ /     _____   ________     /__: _____  sYSOPS:\n        /____  _ /    //_____/o  _/___  /    /____/   |/    /  """""""\n      _____:/  //     /     //   \    \/    /    //   /    /   cALYPSO !\n     /     |\  /__________ /.   /_\   /________ /.    \    \   cASTOR\n __|/____________\       \/_____________\     \/______|\____\  gHOSTRIDER\n   |                                                  :        sOKRATES\n                        · L·O·G·I·C · W·H·Q ·      :_______|__\n          /\ __ /\             _______________     |    _ /|\n         // \\//  \____________\________   _ /____ |    //   nUMBERS:\n        /.   \/    \________   _ /     /   //     \|   o/    """"""""\n       /    \  /    \      /   //\    /    /|      \  ./  +49-7054-8733\n      /      \/______\    /    /  \_______/ |    \    /  +49-7054-eLITE!\n     /_______|        \_______/             |_____\  /\n             :                                Sk!n \/  bOTH nODES 16.8 DS!\n\n','\n',char(10)),NULL,'auto-added',16662,7,0,NULL,NULL,'lgc_st26','scan',1780048575);
INSERT INTO door_catalog VALUES('lgc_ul40','LGC-UL40.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGC-UL40.LHA','RpStart','XIM','RPSTaRT',NULL,NULL,'LGC','/ /\_\__\/ /\____\/\________\/\__\________\ / //  /___\// \_  _\/  ______/____/  ______/ \/.  /    /o   \  ///  /    /    //  /____\',replace('  /\__   __/\_____  _________/\____________ \n / /\_\__\/ /\____\/\________\/\__\________\\n/ //  /___\// \_  _\/  ______/____/  ______/\n\/.  /    /o   \  ///  /    /    //  /____\ \n \______ /\_______/\______ /___ /\_______ / \nSk!n:::\/::::::::Presents\/:::\/::::::::\/::\n  /X 2.x - /X 3.x  © AuToSenTCheCk V4.0  ©  \n','\n',char(10)),'Upload.guide',replace('@database © Ken/LoGiC ShoToKaN PaLaCe - AutoSentCheck V4.0\n@Author Ken / LoGiC ShoToKaN PaLaCe +32 2 270 04 07\n@Index MAIN\n\nCopyright © Ken / LoGiC ShoToKaN PaLaCe +32 2 270 04 07\n\n@Remark $VER: (January 6 1994, 14:00:00)\n@Remark AmigaGuide database for the AutoSentCheck Documentation\n\n@node MAIN "AutoSent Check Documentation © Ken / LoGiC ShoToKaN PaLaCe\n\n                            __               ____\n ._________. .____________ /_/\ _____________\   \ ____________. ._________.\n |         | |             \_\/               \___\            | |         |\n |.       /\_|__    __/\________  ____________/\  /    /\______|_|_       :|\n ||    _ /  \   \___\/  \       \/\           \ \/____/  \         \ _    ||\n |:    //   /\___\   \  /\_______\ \___________\/\    \  /\_________\\    O|\n |o   . \  /.    /____\// \__   __\/   ________// \____\/. \________/ .   :|\n |.      \//    /     /.    /    ///    /     /o       //   /_____\       .|\n |        \_________ /\__________/\_________ /_______ /\_________ /        |\n |         | |     \/                      \/   __  \/         |\/        .|\n |_________| |________________________________ /\_\ ___________| |_________|\n :         : :                                 \/_/            : :    Sk!n :\n		  BeLGiAn HeAdQuArTeRs ! \n\n                                                                 ·          \n----------------------------------------------------------------------------\n\n\n                         @{"      Introduction      " Link Cap01}\n                         @{"      Requirements      " Link Cap02}\n                         @{"      Ken & Ryu Pub ;)  " rxs "address command ''display ken&ryu''"}\n                         @{"       Greetings        " Link Cap05}\n                         @{"   How to Contact me    " Link Cap06}\n\n\n         ---------------------------------------------------------\n                  Complete Docs for AutoSentCheck V4.0\n         ---------------------------------------------------------\n               The Documentation has been written by KeN/LoGiC\n\n@endnode\n@node Cap01 "Introduction"\n  =======================================================================\n  The AUTOSENT by ByTeAnDI/MsT used in the FILE.ID pacakge was the first\n  major thing that struck the Amiga Scene (I mean the File.id.lha). This\n  door i made (is very small but working) for people to FORCE them to use\n  AUTOSENT and no longer put in their handles after their UPLOAD. Why did\n  I do that ? Well simply because the next generation of FIle.Id from\n  ByteAndi will automatically copy the description of the user into the\n  file if it ain''t their yet ! Cööl I should think no ? But for this we\n  must be sure that the user DOESN''T put in his handle aswell as this \n  would be then copied again in the FIle.id.diz..and so at the end we\n  would have the same Handle in the File.id.diz when uploaded anywere. So\n  My door forces the user to install their personal SENT BY line BEFORE\n  they can even upload. Notice that it needs the DOORS:FILEID/ to be pre-\n  sent otherwise my door won''t work.\n  Suggestions and ideas are welcome on my bbs...use the SGST door to add\n  your ideas, suggestions or whatever..or doors you want to see for /X in\n  the future.\n  =======================================================================\n@endnode\n@node Cap02 "Requirements"\n  =======================================================================\n  To install Operator Pager you must have the following things:\n\n    Programm      Location           Description\n    ----------    --------           -----------\n    Upload.rexx   Wherever you like  Main program\n\n  - an  Amiga Model (500/600/1000/1200/2000/2500/3000/4000/CDTV/CD³²)\n  - the installed Version of OS\2, OS\3 or higher\n    (Soft- or Hardware Version)\n  - the installed .INFO Files in the directories.\n  - AmiExpress v3.xx or higher. dunno for /X 2.xx\n\n  You must use it like this :\n  \n  Edit your CONFx/UPLOADMSG.TXT(.GR) in your Conference and add this\n\n  ~\n  ~CC_UPLOAD\n\n  So now the user get''s prompted if he didn''t already use the SENT com-\n  mand from ByTeAndi. Then i will ask him to insert his private line and\n  add this to DOORS:/FILEID/Sent_By.x where x is the users slot number.\n  =======================================================================\n@endnode\n@node Cap05 "Greetings go to..."\n  =======================================================================\n\n                        Greetingz to:\n\n    \n    ByteAndi/MST ............EVERYBODY SHOULD USE FILE_ID.DIZ FROM YOU!\n    Dalai Lama/PoinT Blank .....................Where''s The D-Bank ? :(\n    Planet Master/The Edge .............Where are those damn ansies! :)\n    Becky ...................................................Any News ?\n    Bytemaster .........For programming /X!..Btw: NeTmail Remember? :((\n    \n    And everybody worldwide, who thinks he/she should be in it. Give\n    me a buzz and I''ll put you in next time. (Soon coz more modules\n    coming up very soon) If you have a module that you want for your\n    bbs, feel free to call, made within 4 dayz, free of charge !\n                                        ^\n					| due to TO popular demand 2 dayz\n					       has become impossible! :)\n\n                       GreeTings OfCoZ To :\n\n                  >>> All MeMBeRs oF LoGiC <<<\n\n    SNOW, ASCENDER, AGNUS, CALYPSO, CASTOR, COSMIC, GHOSTRIDER,\n    ROFOE, SCAMPY, TRAVELLER, TRONIX, WARHAWK, XENTEC, SNAKE/NAZGUL,\n\n 	 One left here, but i dunno who it was again ? :)\n\n    \n  =======================================================================\n@endnode\n@node Cap06 "How to contact us..."\n  =======================================================================\n\n	Call me on ShoToKaN PaLaCe : LoGiC BhQ +32 (0) 2 270 04 07\n\n         /\___     /\______  __________/\______  /\________/\________       \n        /  \  \___/  \     \/\         \ \     \/  \       \ \       \      \n       /   /\__\  \  /\_____\ \_________\/\_____\  /\_______\/\_______\     \n      /   // \ /___\/ \\    _\/.  ______// \    _\/  \_ ____/. \_ ____/     \n._____\  /.   /    /   .\   ///   /    /.   \   //.  ____/ //  ____/_______.\n|____  \/________ /\________/________ /\________//   /_\  /    /_ Sk!n     |\n|\\//           \/                  \/        \/_____ / \/_____ /          |\n| \/     GiVe TheZe CooL LoGiC-BbS`s AlSo a RiNG!   \/        \/           |\n|                                                                          |\n|    HaPPy NaTion    +49 972-121-932   - SNOW      - NoDeS : 1  GHQ        |\n|    BlaCK MooN      +49 705-487-33    - CaLyPSo   - NoDeS : 2  WHQ   __   |\n|    SNaKe`S DeN     + 1 513-271-3213  - SNaKe     - NoDeS : 3  USHQ /\_\  |\n|    ShoToKaN PaLaCe +32 2-270-04-07   - KeN & Ryu - NoDeS : 4  EHQ  \/_/  |\n|__________________________________________________________________________|\n                                                                          \n  =======================================================================\n@endnode\n','\n',char(10)),NULL,'auto-added',80125,1,0,NULL,NULL,'woa_tc11','scan',1780048567);
INSERT INTO door_catalog VALUES('lgc_user','LGC-USER.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGC-USER.LHA',NULL,'XIM','nosefuck.exe',NULL,'Calypso/LOGiC','LGC','.-» l__,|__|l__||l__'' S!X Development_\/_«-. |--------------''---------------------\/\/--| |     UserList V1.0 by Calypso/LOGiC !     :',replace('    .    __  __ . __                  __\n.-» l__,|__|l__||l__'' S!X Development_\/_«-.\n|--------------''---------------------\/\/--|\n|     UserList V1.0 by Calypso/LOGiC !     :\n|                                          |\n|     Pure ASM ! Runs with S!X and /X !    |\n|                                          |\n|   This door displays all usernames and   |\n: shows stats about active/deleted users ! |\n`------------------------------------------''\n','\n',char(10)),'UserList.Doc',replace('                            __               ____\n ._________. .____________ /_/\ _____________\   \ ____________. ._________.\n |         | |             \_\/               \___\            | |         |\n |.       /\_|__    __/\________  ____________/\  /    /\______|_|_       :|\n ||    _ /  \   \___\/  \       \/\           \ \/____/  \         \ _    ||\n |:    //   /\___\   \  /\_______\ \___________\/\    \  /\_________\\    O|\n |o   . \  /.    /____\// \__   __\/   ________// \____\/. \________/ .   :|\n |.      \//    /     /.    /    ///    /     /o       //   /_____\       .|\n |        \_________ /\__________/\_________ /_______ /\_________ /        |\n |         | |     \/                      \/   __  \/         |\/        .|\n |_________| |________________________________ /\_\ ___________| |_________|\n :         : :                                 \/_/_           : :    Sk!n :\n\n                                 PRESENTS\n\n              -=> UserList V1.0 coded by CALYPSO/LOGIC <=-\n\n    PROFESSIONAL TOOLS FOR PROFESSIONAL SYSOPS - GET THE REAL QUALITY !\n\n\nWHAT''S THE USE OF THIS TOOL ?\n-----------------------------\n\n        This door displays a list of all users (in realtime) !\n        Delete users will be shown in red color !\n\n        If you do not use S-Express the Red/White colors may\n        be wrong, but it works on all Express Versions !\n\n        Enjoy !\n\n  .-----------------------------------------------------------------------.\n  |       PLEASE READ THE REGISTER!.TXT INCLUDED IN THIS ARCHIVE !!!      |\n  `-----------------------------------------------------------------------''\n\nWHY SHOULD I USE IT ?\n---------------------\n\n        If you love speed and beautiful outputs this is the tool\n        you have been waiting for ! Install it, and see for yourself.\n\nHOW TO INSTALL :\n----------------\n\n        Copy the files in the archive to your directories,\n        they are :\n\n        BBS:Doors/UserList/UserList.Config\n        BBS:Doors/UserList/UserList.XIM\n        BBS:Doors/UserList/UserList.Doc\n        BBS:Doors/UserList/UserList.Header\n        BBS:Doors/UserList/UserList.Tailer\n        LIBS:AEDoor.library ( © Sintax/WOT )\n\n        The UserList.Config looks like this :\n \n        --------(cut here)--------\n        BBS:User.Data                      <- The Location of your User.Data !\n        DOORS:UserList/UserList.Header     <- Headertext to be displayed !\n        DOORS:UserList/UserList.Tailer     <- Tailertext to be displayed !\n        --------------------------\n\n        The Tailer-Text can be left out.\n        \n\n        Append the BBS:Commands/BBS.CMD to your BBS.CMD !\n\n        Ok, now the door is installed and a user can call it with\n        typing USERLIST, but normally you want it as a bulletin.\n        Use this in a bulletin :\n\n        ~CC_USERLIST\n\n        This will call the door !\n\n        The advantage is that you don''t have to add another util\n        to your logoffbatch !!!\n\n\n  .-----------------------------------------------------------------------.\n  |       PLEASE READ THE REGISTER!.TXT INCLUDED IN THIS ARCHIVE !!!      |\n  `-----------------------------------------------------------------------''\n\n\nLAST WORDS :\n------------\n        \n        It has been tested for a long time from S!X developers, so you can be\n        sure this tool is 100% bug-free !\n\n        S!X running with official S!X tools NEVER crashes, like other\n        BBS software does, hehe...\n\n        Have fun with my tools...\n\n                                                        Calypso/LOGIC !\n\n#########################################################################\n\nIMPORTANT :\n-----------\n\n\n        Read the included LOGIC.NFO text !\n                          ---------\n        It contains important information about S!X and LOGIC and how\n        to contact us ! Read it !\n                        ---------\n#########################################################################\n\n\nSOON TO BE RELEASED TOOLS - ALL CODED IN ASM (AS EVER) ! :\n----------------------------------------------------------\n\n        ConfAXX V1.0   - New and great-looking tool to show who\n                         has access to the current conference !\n\n        Best-Scan V2.0 - You won''t believe it, but this is true !\n                         The update to the FASTEST newfiles-scanner !\n\n        ... gimme suggestions for more tools ...\n\n\nGREETINGS/MESSAGES:\n-------------------\n\nSigma Seven - S-Express rules !\nNoisy Belch - Good luck with coding in C ! Good designs !\nGalaxy - Resource-God :)\nNo Limit - Why don''t you switch to S-Express ?\nBBC - Keep coding !\nBilbo Baggins - Contact me (internet ?) !\nSisko - Hows ZIVI life ?\nRaider/Scout/Ventor - Still active ?\nWedlock - Call me !\nSid Vicious - Where are you ?!\nWhiz - Kick your BBS !\nCastor - Paradox suxx, hehe\nE.F.A. - Nothing to crack ?\nDoc - Keep those loooong messages !\nDalai Lama - Where are you ? Use internet !\nWormeater - Still no Playstation ? (it rules !)\nJAF - Contact me !\nMike & Dave - Where are you ?!\nSpike - Where have you been on the PARTY IV ?\nAutopsy - Hi ! New World-Charts coming ?\n-TCB!- - Just gimme a call...\nZion - If you have internet... write me !\n\nSorry if I forgot someone, hehe... that''s all folx !\n','\n',char(10)),NULL,'auto-added',17077,8,0,NULL,NULL,'lgc_user','scan',1780048567);
INSERT INTO door_catalog VALUES('lgc_usr2','LGC-USR2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGC-USR2.LHA',NULL,'XIM','_  _ ___ ________    (-fAZ!)',NULL,'Noisy','LGC','.:________________________    /________ /     /   _    /  ______/___/        / /     /\   /   /   /   /     \  \____/',replace('                _  _ ___ ________    (-fAZ!)\n  .:________________________    /________\n   /     /   _    /  ______/___/        /\n  /     /\   /   /   /   /     \  \____/\n /________\____ /________\_____/_______\\n==============\/============================\n    ChangeUSR v0.2 by Noisy Belch/LOGIC\nPatch your USRobotics Courier FlashROM files\nto the Country you need  [Including Source!]\n====================================[AMIGA]=\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 20:14:41  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,NULL,16857,4,0,NULL,NULL,NULL,'scan',1780048567);
INSERT INTO door_catalog VALUES('lgc_wh18','LGC-WH18.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGC-WH18.LHA','who','XIM','exe.-l0S-eND0S-bBS-.exe',NULL,'Noisy','LGC','.:________________________    /________ /     /   _    /  ______/___/        / /     /\   /   /   /   /     \  \____/',replace('                _  _ ___ ________    (-fAZ!)\n  .:________________________    /________   \n   /     /   _    /  ______/___/        /   \n  /     /\   /   /   /   /     \  \____/    \n /________\____ /________\_____/_______\    \n+- -----------\/-- ---> S!X Development <--+\n|    BelchWHO v1.8 by Noisy Belch/LOGIC    |\n|         S!Express v0.39p1+ ONLY          |\n|XFER BAR,MONITORING,WHAT,STATUS,...PERFECT|\n+--> /X.info is HiSTORY <> FAME is LAME <--+\n','\n',char(10)),'BelchWHO.guide',replace('@database "BelchWHO"\n@node main "Main"\n                            __               ____\n ._________. .____________ /_/\ _____________\   \ ____________. ._________.\n |         | |             \_\/               \___\            | |         |\n |.       /\_|__    __/\________  ____________/\  /    /\______|_|_       :|\n ||    _ /  \   \___\/  \       \/\           \ \/____/  \         \ _    ||\n |:    //   /\___\   \  /\_______\ \___________\/\    \  /\_________\\    O|\n |o   . \  /.    /____\// \__   __\/   ________// \____\/. \________/ .   :|\n |.      \//    /     /.    /    ///    /     /o       //   /_____\       .|\n |        \_________ /\__________/\_________ /_______ /\_________ /        |\n |         | |     \/                      \/   __  \/         |\/        .|\n |_________| |________________________________ /\_\ ___________| |_________|\n :         : :                                 \/_/_           : :    Sk!n :\n\n                      BelchWHO v1.8 by Noisy Belch/LOGIC\n\n                            S!Express v0.39p1+ ONLY\n\n                                  @{" Features " link "features"}\n                                  @{" History  " link "history"}\n                               @{" How to Install " link "install"}\n             @{" The fastest Independent Console Only Board in Europe " link "4Ndz Console Only"}\n@endnode\n@node "Features"\n\nJust put an eye on the example output files to see how powerfull this damn\nWHO door is.. reheh\n\nIf you realize that the sizes in the WHAT funktion are not correct then its\nstill a little bug in S!X which will be fixed in further versions.\n\nIf it is fixed BelchWHO will automatically recognize it .. no problem...\n@endnode\n\n@node "History"\n\n                       There were Million ßeta versions\n\n               I just write in which order I added the functions\n\n                            CPS CONF SIZE POS TODO\n                           WHAT -> (RECEIVED FILES)\n                            WHAT -> (SKIPPED FILES)\n                                 TRANSFER BAR\n                              CONFIGURATION MENU\n                                  MONITORING\n                                    TIMER\n                                   \n1.5ß  Sigma changed The Semaphores ..  now they are smaller than before\n      BelchWHO is now for v0.39o4+ only.. but will also still work with\n      lower versions... but then it will show weird stuff..\n1.6ß  optimized the whole door a bit and fixed the header for pc users\n1.7ß  optimized the whole door a bit Added WHAT -> (FLAGGED FILES)\n      added a new option if the user.data is located in BBS: the who door\n      will show some information aboutthe user.. I''ll make the path\n      configureable soon...\n      BelchWHO is now v0.39p1+ only.. no chance for lower versions... 8(\n      added colors!!! many people requested that.. but i was to busy making\n      other doors eheh... thanks again to FAZWONGA! for that kewl header...\n1.8   first public release\n\n@endnode\n@node "Install"\n\n           Put this door named as WHO into the BBS:SYSTEM directory\n\n          and create DOORS:BelchWHO/ for the CONFIG and HEADER files\n@endnode\n\n@node "4Ndz Console Only"\n\n                                     ___ _ _ _ __ _ __ _____\n                                    /\__\\n                  _   _ _ __ ____ __\/__/\n                                                                 ·aBn/fAZ!·\n                                                      ______ _____\n     _________  ________  _____ _____________________/   __/_  __/_________\n    _\___    /__\___   /_/____/_\    __________     /    ___/  ______     /\n   /    /     /    /    /     /  \      \/    /    /     /     /    /    /\n  /    /     /         /     /          /    _____/_    /_    /_   _____/_\n /____/     /_________/     /__________/___________/_____/_____/_________/\n  .  /______\        /_____/                                             :\n  |                                                                      |\n  | ...the fastest four nodes Independent Console only board in Europe.. |\n  |                                                                      !\n  |+            +49-52X-aSK-4iT -> USRobotics with Ringdown              o\n :¡.            +49-X24-fAST!   -> Euro ISDN with Ringdown!              ¡\n  |                                                                      |\n  |                -*- Sysop: Noisy Belch   Nup: AsK -*-                 |\n !|_____________________________________________________________________!|.\n ::::                                                                    !\n@next "main"\n@endnode\n','\n',char(10)),NULL,'auto-added',48284,6,0,NULL,NULL,'lgc_wh18','scan',1780048567);
INSERT INTO door_catalog VALUES('lgc_zip','LGC-ZIP.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGC-ZIP.LHA','ZIP','XIM','ZIPCheck',NULL,'Calypso/LOGIC','LGC','Mb\_    /      \/  _    /  \/   _    / .--/    /\   |   \ _|___/___/    |___/-. | /    /  \_ |   / \_   |   \    |  |  |',replace('    _____________  ________/\  _________\n  Mb\_    /      \/  _    /  \/   _    /\n .--/    /\   |   \ _|___/___/    |___/-.\n | /    /  \_ |   / \_   |   \    |  |  |\n | \________/____/___|   |____\______|  |\n `-----------Presents`---'' -------------''\n  >> ZIPCheck V1.0 << by Calypso/LOGIC !\n    Public Release Version ! Get it !\n','\n',char(10)),'ZIP.Doc',replace('NAME\n     zip, zipcloak, zipnote,  zipsplit  -  package  and  compress\n     (archive) files\n\nSYNOPSIS\n     zip [-cdDeEfFghjklLmoqrSTuvVwyz@$]  [-b path]  [-n suffixes]\n     [-t mmddyy] [ zipfile [ file1 file2 ...]] [-xi list]\n\n     zipcloak [-dhL] [-b path] zipfile\n\n     zipnote [-hwL] [-b path] zipfile\n\n     zipsplit [-hiLpst] [-n size] [-b path] zipfile\n\nDESCRIPTION\n     zip is a compression and file packaging  utility  for  Unix,\n     VMS,  MSDOS,  OS/2,  Windows NT, Minix, Atari and Macintosh.\n     It is analogous to a combination of the UNIX commands tar(1)\n     and  compress(1)  and  is compatible with PKZIP (Phil Katz''s\n     ZIP for MSDOS systems).\n\n     A companion program (unzip(1L)), unpacks zip archives.   The\n     zip  and  unzip(1L) programs can work with archives produced\n     by PKZIP, and PKZIP and PKUNZIP can work with archives  pro-\n     duced  by  zip.   zip version 2.0.1 is compatible with PKZIP\n     2.04 Note that PKUNZIP 1.10 cannot extract files produced by\n     PKZIP 2.04 or zip 2.0.1. You must use PKUNZIP 2.04g or unzip\n     5.0p1 (or later versions) to extract them.\n\n     For a brief help on zip and unzip, run each without specify-\n     ing any parameters on the command line.\n\n     The program is useful for packaging a set of files for  dis-\n     tribution; for archiving files; and for saving disk space by\n     temporarily compressing unused files or directories.\n\n     The zip program puts one or more  compressed  files  into  a\n     single  zip  archive, along with information about the files\n     (name, path, date, time of  last  modification,  protection,\n     and  check information to verify file integrity).  An entire\n     directory structure can be packed into a zip archive with  a\n     single command.  Compression ratios of 2:1 to 3:1 are common\n     for text files.  zip has one compression method  (deflation)\n     and can also store files without compression.  zip automati-\n     cally chooses the better of the two  for  each  file  to  be\n     compressed.\n\n     When given the name of an existing  zip  archive,  zip  will\n     replace  identically named entries in the zip archive or add\n     entries for new names.  For example, if foo.zip  exists  and\n     contains foo/file1 and foo/file2, and the directory foo con-\n     tains the files foo/file1 and foo/file3, then:\n\n          zip -r foo foo\n\n     will replace foo/file1  in  foo.zip  and  add  foo/file3  to\n     foo.zip.  After this, foo.zip contains foo/file1, foo/file2,\n     and foo/file3, with foo/file2 unchanged from before.\n\n     If the file list is specified as -@, zip takes the  list  of\n     input  files  from  standard input.  Under UNIX, this option\n     can be used to  powerful  effect  in  conjunction  with  the\n     find(1)  command.   For example, to archive all the C source\n     files in the current directory and its subdirectories:\n\n          find . -name "*.[ch]" -print | zip source -@\n\n     (note that the pattern must be quoted to keep the shell from\n     expanding  it).  zip will also accept a single dash ("-") as\n     the zip file name, in which case it will write the zip  file\n     to  standard  output,  allowing  the  output  to be piped to\n     another program. For example:\n\n          zip -r - . | dd of=/dev/nrst0 obs=16k\n\n     would write the zip output  directly  to  a  tape  with  the\n     specified  block  size  for  the  purpose  of backing up the\n     current directory.\n\n     zip also accepts a single dash ("-") as the name of  a  file\n     to  be  compressed, in which case it will read the file from\n     standard input, allowing zip to take input from another pro-\n     gram. For example:\n\n          tar cf - . | zip backup -\n\n     would compress the output of the tar command for the purpose\n     of backing up the current directory. This generally produces\n     better compression than the previous example  using  the  -r\n     option, because zip can take advantage of redundancy between\n     files. The backup can be restored using the command\n\n          unzip -p backup | tar xf -\n\n     When no zip file name is given and stdout is not a terminal,\n     zip acts as a filter, compressing standard input to standard\n     output.  For example,\n\n          tar cf - . | zip | dd of=/dev/nrst0 obs=16k\n\n     is equivalent to\n\n          tar cf - . | zip - - | dd of=/dev/nrst0 obs=16k\n\n     zip archives created in this manner can  be  extracted  with\n     the  program  funzip which is provided in the unzip package,\n     or by gunzip which is provided  in  the  gzip  package.  For\n     example:\n\n     dd if=/dev/nrst0  ibs=16k | funzip | tar xvf -\n\n     When changing an existing zip archive, zip will write a tem-\n     porary  file with the new contents, and only replace the old\n     one when the process of creating the new  version  has  been\n     completed without error.\n\n     If the name of the zip archive does not  contain  an  exten-\n     sion,  the extension .zip is added. If the name already con-\n     tains an extension other than .zip the existing extension is\n     kept unchanged.\n\nOPTIONS\n     -b path\n          Use the specified path for the temporary  zip  archive.\n          For example:\n\n               zip -b /tmp stuff *\n\n          will put the temporary zip  archive  in  the  directory\n          /tmp,  copying  over stuff.zip to the current directory\n          when done. This option is only useful when updating  an\n          existing  archive,  and the file system containing this\n          old archive does not have enough space to hold both old\n          and new archive at the same time.\n\n     -c   Add one-line comments for each file.   File  operations\n          (adding, updating) are done first, and the user is then\n          prompted for a one-line comment for each  file.   Enter\n          the  comment  followed by return, or just return for no\n          comment.\n\n     -d   Remove (delete) entries from a zip archive.  For  exam-\n          ple:\n\n               zip -d foo foo/tom/junk foo/harry/\* \*.o\n\n          will remove the entry foo/tom/junk, all  of  the  files\n          that  start  with foo/harry/, and all of the files that\n          end with .o (in any path).  Note  that  shell  pathname\n          expansion  has been inhibited with backslashes, so that\n          zip can see the asterisks, enabling zip to match on the\n          contents  of the zip archive instead of the contents of\n          the current directory.\n\n          Under MSDOS, -d is case sensitive when it matches names\n          in  the  zip archive.  This requires that file names be\n          entered in upper case if they were zipped by  PKZIP  on\n          an MSDOS system.\n\n     -D   Do not create entries in the  zip  archive  for  direc-\n          tories.   Directory  entries  are created by default so\n          that their attributes can be saved in the zip  archive.\n          The  environment  variable ZIPOPT can be used to change\n          the default options. For example under Unix with sh:\n\n               ZIPOPT="-D"; export ZIPOPT\n\n          (The variable ZIPOPT can be used for any option  except\n          -i  and -x and can include several options.) The option\n          -D is a shorthand for -x "*/" but the latter cannot  be\n          set as default in the ZIPOPT environment variable.\n\n     -e   Encrypt the contents of the zip archive using  a  pass-\n          word  which is entered on the terminal in response to a\n          prompt (this will not be echoed; if standard  error  is\n          not a tty, zip will exit with an error).\n\n     -ee  Encrypt contents, prompting  for  the  password  twice,\n          checking  that  the  two  entries  are identical before\n          using the password.\n\n     -f   Replace (freshen) an existing entry in the zip  archive\n          only  if  it  has  been modified more recently than the\n          version already in the zip archive; unlike  the  update\n          option  (-u)  this  will  not  add  files  that are not\n          already in the zip archive.  For example:\n\n               zip -f foo\n\n          This command should be run from the same directory from\n          which  the  original  zip  command was run, since paths\n          stored in zip archives are always relative.\n\n     -F   Fix the zip archive. This option can be  used  if  some\n          portions   of  the  archive  are  missing.  It  is  not\n          guaranteed to work, so you MUST make a  backup  of  the\n          original archive first.\n\n          When doubled as  in  -FF  the  compressed  sizes  given\n          inside  the  damaged  archive  are  not trusted and zip\n          scans for special signatures  to  identify  the  limits\n          between  the  archive  members.  The  single -F is more\n          reliable if the archive is not too  much  damaged,  for\n          example  if  it  has  only  been truncated, so try this\n          option first.\n\n          Neither option will recover  archives  that  have  been\n          incorrectly   transferred  in  ascii  mode  instead  of\n          binary. After the repair, the -t option  of  unzip  may\n          show  that some files have a bad CRC. Such files cannot\n          be recovered; you can  remove  them  from  the  archive\n          using the -d option of zip.\n\n     -g   Grow (append to) the specified zip archive, instead  of\n          creating  a  new  one.  If  this  operation  fails, zip\n          attempts to restore the archive to its original  state.\n          If the restoration fails, the archive might become cor-\n          rupted.\n\n     -h   Display the zip help information (this also appears  if\n          zip is run with no arguments).\n\n     -i files\n          Include only the specified files, as in:\n\n               zip -r foo . -i \*.c\n\n          which will include only the files that end in .c in the\n          current  directory  and  its  subdirectories. (Note for\n          PKZIP users: the equivalent command is\n\n               pkzip -r foo *.c\n\n          PKZIP does not allow  recursion  in  directories  other\n          than  the  current one.) The backslash avoids the shell\n          filename substitution, so that  the  name  matching  is\n          performed by zip at all directory levels.\n\n     -j   Store just the name of a saved file  (junk  the  path),\n          and  do not store directory names. By default, zip will\n          store the full path (relative to the current path).\n\n     -k   Attempt to convert the names and paths  to  conform  to\n          MSDOS,  store  only  the MSDOS attribute (just the user\n          write attribute from UNIX), and mark the entry as  made\n          under MSDOS (even though it was not); for compatibility\n          with PKUNZIP under MSDOS which  cannot  handle  certain\n          names such as those with two dots.\n\n     -l   Translate the Unix end-of-line character  LF  into  the\n          MSDOS  convention CR LF. This option should not be used\n          on binary files.  This option can be used  on  Unix  if\n          the  zip  file  is intended for PKUNZIP under MSDOS. If\n          the input files already contain CR LF, this option adds\n          an extra CR. This ensure that unzip -a on Unix will get\n          back an exact copy of the original file,  to  undo  the\n          effect of zip -l.\n\n     -ll  Translate the MSDOS end-of-line CR  LF  into  Unix  LF.\n          This  option  should not be used on binary files.  This\n          option can be used on MSDOS if the zip file is intended\n          for unzip under Unix.\n\n     -L   Display the zip license.\n\n     -m   Move the specified files into the  zip  archive;  actu-\n          ally,  this  deletes the target directories/files after\n          making  the  specified  zip  archive.  If  a  directory\n          becomes empty after removal of the files, the directory\n          is also removed. No deletions are done  until  zip  has\n          created  the archive without error.  This is useful for\n          conserving disk space, but is potentially dangerous  so\n          it  is  recommended to use it in combination with -T to\n          test the archive before removing all input files.\n\n     -n suffixes\n          Do not attempt to compress files named with  the  given\n          suffixes. Such files are simply stored (0% compression)\n          in the output zip file, so that zip doesn''t  waste  its\n          time   trying  to  compress  them.   The  suffixes  are\n          separated by either colons or semicolons.  For example:\n\n               zip -rn .Z:.zip:.tiff:.gif:.snd  foo foo\n\n          will copy everything from foo into  foo.zip,  but  will\n          store  any  files that end in .Z, .zip, .tiff, .gif, or\n          .snd without trying to compress them (image  and  sound\n          files  often  have  their  own  specialized compression\n          methods).  By default, zip does not compress files with\n          extensions  in  the  list  .Z:.zip:.zoo:.arc:.lzh:.arj.\n          Such files are stored directly in the  output  archive.\n          The  environment  variable ZIPOPT can be used to change\n          the default options. For example under Unix with csh:\n\n               setenv ZIPOPT "-n .gif:.zip"\n\n          To attempt compression on all files, use:\n\n               zip -n : foo\n\n          The  maximum  compression  option  -9   also   attempts\n          compression on all files regardless of extension.\n\n     -o   Set the "last modified" time of the zip archive to  the\n          latest  (oldest)  "last  modified" time found among the\n          entries in the zip archive.  This can be  used  without\n          any other operations, if desired.  For example:\n\n          zip -o foo\n\n          will change the last modified time of  foo.zip  to  the\n          latest time of the entries in foo.zip.\n\n     -q   Quiet mode; eliminate informational messages  and  com-\n          ment  prompts.   (Useful, for example, in shell scripts\n          and background tasks).\n\n     -r   Travel the directory structure recursively;  for  exam-\n          ple:\n\n               zip -r foo foo\n\n          In this case, all the files and directories in foo  are\n          saved  in  a zip archive named foo.zip, including files\n          with names starting with ".", since the recursion  does\n          not  use  the shell''s file-name substitution mechanism.\n          If you wish to include only a specific  subset  of  the\n          files  in directory foo and its subdirectories, use the\n          -i option to the specify the pattern  of  files  to  be\n          included.   You  should  not use -r with the name ".*",\n          since that matches ".." which will attempt  to  zip  up\n          the parent directory (probably not what was intended).\n\n     -S   Include system and hidden files. This option is  effec-\n          tive on some systems only; it is ignored on Unix.\n\n     -t mmddyy\n          Do not operate on files modified prior to the specified\n          date,  where  mm  is the month (0-12), dd is the day of\n          the month (1-31), and yy are the last two digits of the\n          year.  For example:\n\n               zip -rt 120791 infamy foo\n\n          will add all the files in foo  and  its  subdirectories\n          that were last modified on or after 7 December 1991, to\n          the zip archive infamy.zip.\n\n     -T   Test the integrity of the new zip file.  If  the  check\n          fails,  the  old zip file is unchanged and (with the -m\n          option) not input files are removed.\n\n     -u   Replace (update) an existing entry in the  zip  archive\n          only  if  it  has  been modified more recently than the\n          version already in the zip archive.  For example:\n\n               zip -u stuff *\n\n          will add any new files in the  current  directory,  and\n          update any files which have been modified since the zip\n          archive stuff.zip was last created/modified (note  that\n          zip will not try to pack stuff.zip into itself when you\n          do this).\n\n          Note that the -u option with no arguments acts like the\n          -f (freshen) option.\n\n     -v   Verbose  mode.  Display  a  progress  indicator  during\n          compression.\n\n     -V   Save VMS file attributes. This option is  available  on\n          VMS  only;  zip  archives created with this option will\n          generally not be usable on other systems.\n\n     -w   Append the version number of the  files  to  the  name,\n          including  multiple  versions  of  files.   (VMS  only;\n          default: use only the most recent version of  a  speci-\n          fied file).\n\n     -x files\n          Explicitly exclude the specified files, as in:\n\n               zip -r foo foo -x \*.o\n\n          which will include the contents of foo in foo.zip while\n          excluding  all the files that end in .o.  The backslash\n          avoids the shell filename  substitution,  so  that  the\n          name matching is performed by zip at all directory lev-\n          els.\n\n     -y   Store symbolic  links  as  such  in  the  zip  archive,\n          instead of compressing and storing the file referred to\n          by the link (UNIX only).\n\n     -z   Prompt for a multi-line  comment  for  the  entire  zip\n          archive.   The  comment  is  ended by a line containing\n          just a period, or an end of file condition (^D on UNIX,\n          ^Z  on  MSDOS,  OS/2, and VAX/VMS).  The comment can be\n          taken from a file:\n\n               zip -z foo < foowhat\n\n     -#   Regulate the speed of compression using  the  specified\n          digit  #,  where -0 indicates no compression (store all\n          files), -1 indicates  the  fastest  compression  method\n          (less   compression)   and  -9  indicates  the  slowest\n          compression method (optimal  compression,  ignores  the\n          suffix list). The default compression level is -6.\n\n     -@   Take the list of input files from standard input.\n\n     -$   Include the volume label for the the drive holding  the\n          first  file  to  be compressed.  If you want to include\n          only the volume label or to force a specific drive, use\n          the drive name as first file name, as in:\n\n               zip -$ foo a: c:bar\n\n          This option is effective on some  systems  only  (MSDOS\n          and OS/2); it is ignored on Unix.\n\nEXAMPLES\n     The simplest example:\n\n          zip stuff *\n\n     creates the archive stuff.zip (assuming it does  not  exist)\n     and  puts  all  the files in the current directory in it, in\n     compressed form (the .zip  suffix  is  added  automatically,\n     unless  that archive name given contains a dot already; this\n     allows the explicit specification of other suffixes).\n\n     Because of the way the  shell  does  filename  substitution,\n     files  starting  with "." are not included; to include these\n     as well:\n\n          zip stuff .* *\n\n     Even this will  not  include  any  subdirectories  from  the\n     current directory.\n\n     To zip up an entire directory, the command:\n\n          zip -r foo foo\n\n     creates the archive foo.zip, containing all  the  files  and\n     directories  in  the  directory foo that is contained within\n     the current directory.\n\n     You may want to make a zip archive that contains  the  files\n     in  foo, without recording the directory name, foo.  You can\n     use the -j option to leave off the paths, as in:\n\n          zip -j foo foo/*\n\n     If you are short on disk space, you might  not  have  enough\n     room to hold both the original directory and the correspond-\n     ing compressed zip archive.  In this case,  you  can  create\n     the  archive  in steps using the -m option.  If foo contains\n     the subdirectories tom, dick, and harry, you can:\n\n          zip -rm foo foo/tom\n          zip -rm foo foo/dick\n          zip -rm foo foo/harry\n\n     where the first command creates foo.zip, and  the  next  two\n     add  to it.  At the completion of each zip command, the last\n     created archive is deleted, making room  for  the  next  zip\n     command to function.\n\nPATTERN MATCHING\n     This section applies only to UNIX.   Watch  this  space  for\n     details on MSDOS and VMS operation.\n\n     The UNIX shells (sh(1) and csh(1)) do filename  substitution\n     on command arguments.  The special characters are:\n\n     ?    match any single character\n\n     *    match any number of characters (including none)\n\n     []   match any character in the range indicated  within  the\n          brackets (example: [a-f], [0-9]).\n\n     When these characters are encountered (without being escaped\n     with  a  backslash or quotes), the shell will look for files\n     relative to the current path that  match  the  pattern,  and\n     replace the argument with a list of the names that matched.\n\n     The zip program can do the same matching on names  that  are\n     in  the zip archive being modified or, in the case of the -x\n     (exclude) or -i (include) options, on the list of  files  to\n     be  operated  on, by using backslashes or quotes to tell the\n     shell not to do the name expansion.  In  general,  when  zip\n     encounters a name in the list of files to do, it first looks\n     for the name in the file system.  If it finds  it,  it  then\n     adds it to the list of files to do.  If it does not find it,\n     it looks for the name in the zip archive being modified  (if\n     it  exists), using the pattern matching characters described\n     above, if present.  For each match, it will add that name to\n     the  list of files to be processed, unless this name matches\n     one given with the -x option, or does  not  match  any  name\n     given with the -i option.\n\n     The pattern matching includes the path, and so patterns like\n     \*.o  match  names that end in ".o", no matter what the path\n     prefix is.  Note that the backslash must precede every  spe-\n     cial  character  (i.e. ?*[]), or the entire argument must be\n     enclosed in double quotes ("").\n\n     In general, use backslash to make zip do the pattern  match-\n     ing with the -f (freshen) and -d (delete) options, and some-\n     times after the  -x  (exclude)  option  when  used  with  an\n     appropriate operation (add, -u, -f, or -d).\n\nSEE ALSO\n     compress(1), shar(1L), tar(1), unzip(1L), gzip(1L)\n\nBUGS\n     zip 2.0.1 is not compatible with PKUNZIP 1.10. Use  zip  1.1\n     to produce zip files which can be extracted by PKUNZIP 1.10.\n\n     zip files produced by zip 2.0.1 must not be updated  by  zip\n     1.1  or  PKZIP 1.10, if they contain encrypted members or if\n     they have been produced in a pipe or on a non-seekable  dev-\n     ice.  The  old  versions  of  zip  or  PKZIP would create an\n     archive with an incorrect format.  The old versions can list\n     the  contents  of  the zip file but cannot extract it anyway\n     (because of the new compression algorithm).  If you  do  not\n     use  encryption  and use regular disk files, you do not have\n     to care about this problem.\n\n     Under VMS, not all of the odd file formats are treated prop-\n     erly.   Only stream-LF format zip files are expected to work\n     with zip.  Others can be converted using Rahul Dhesi''s  BILF\n     program.  This version of zip handles some of the conversion\n     internally.  When using Kermit to transfer  zip  files  from\n     Vax  to  MSDOS, type "set file type block" on the Vax.  When\n     transfering from MSDOS to Vax, type "set file type fixed" on\n     the  Vax.   In  both  cases,  type "set file type binary" on\n     MSDOS.\n\n     Under VMS, zip hangs for file specification that uses DECnet\n     syntax foo::*.*.\n\n     On OS/2, zip cannot match some names, such as those  includ-\n     ing  an  exclamation  mark or a hash sign.  This is a bug in\n     OS/2 itself: the 32-bit DosFindFirst/Next  don''t  find  such\n     names.   Other programs such as GNU tar are also affected by\n     this bug.\n\n     Under OS/2, the amount of External Attributes  displayed  by\n     DIR is (for compatibility) the amount returned by the 16-bit\n     version of DosQueryPathInfo(). Otherwise OS/2  1.3  and  2.0\n     would  report  different  EA sizes when DIRing a file.  How-\n     ever,  the  structure  layout   returned   by   the   32-bit\n     DosQueryPathInfo() is a bit different, it uses extra padding\n     bytes and link pointers (it''s a linked  list)  to  have  all\n     fields  on  4-byte boundaries for portability to future RISC\n     OS/2 versions. Therefore the value reported  by  zip  (which\n     uses  this  32-bit-mode  size) differs from that reported by\n     DIR.  zip stores the 32-bit format for portability, even the\n     16-bit  MS-C-compiled  version  running on OS/2 1.3, so even\n     this one shows the 32-bit-mode size.\n\nAUTHORS\n     Copyright (C) 1990-1993 Mark Adler, Richard B. Wales,  Jean-\n     loup  Gailly,  Kai  Uwe  Rommel,  Igor Mandrichenko and John\n     Bush.  Permission is granted to any individual  or  institu-\n     tion  to use, copy, or redistribute this software so long as\n     all of the original files are included, that it is not  sold\n     for profit, and that this copyright notice is retained.\n\n     LIKE ANYTHING ELSE THAT''S FREE, ZIP AND ITS ASSOCIATED UTIL-\n     ITIES  ARE  PROVIDED  AS IS AND COME WITH NO WARRANTY OF ANY\n     KIND, EITHER EXPRESSED OR IMPLIED.  IN  NO  EVENT  WILL  THE\n     COPYRIGHT  HOLDERS  BE LIABLE FOR ANY DAMAGES RESULTING FROM\n     THE USE OF THIS SOFTWARE.\n\n     Please  send  bug  reports  and  comments   by   email   to:\n     [email removed].  For bug reports, please include the\n     version of zip, the make options used  to  compile  it,  the\n     machine  and operating system in use, and as much additional\n     information as possible.\n\nACKNOWLEDGEMENTS\n     Thanks to R. P. Byrne  for  his  Shrink.Pas  program,  which\n     inspired  this  project, and from which the shrink algorithm\n     was stolen; to Phil Katz for placing in  the  public  domain\n     the  zip  file format, compression format, and .ZIP filename\n     extension, and for accepting minor changes to the file  for-\n     mat; to Steve Burg for clarifications on the deflate format;\n     to Haruhiko Okumura and Leonid Broukhis for  providing  some\n     useful  ideas for the compression algorithm; to Keith Peter-\n     sen, Rich Wales, Hunter Goatley and Mark Adler for providing\n     a  mailing  list and ftp site for the INFO-ZIP group to use;\n     and most importantly, to the INFO-ZIP group  itself  (listed\n     in  the file infozip.who) without whose tireless testing and\n     bug-fixing efforts a portable zip would not have been possi-\n     ble.   Finally  we  should  thank (blame) the first INFO-ZIP\n     moderator, David Kirschbaum, for getting us into  this  mess\n     in  the first place.  The manual page was rewritten for UNIX\n     by R. P. C. Rodgers.\n','\n',char(10)),NULL,'auto-added',74746,8,0,NULL,NULL,'lgc_zip','scan',1780048575);
INSERT INTO door_catalog VALUES('lgc_best','LGC_BEST.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGC_BEST.LHA',NULL,'XIM','_ _______      _ __________ /\',NULL,'Calypso/LOGIC','LGC','_ __   /______________   // \\__________ /   / \_____  \/  _/__//   \\____    / /   /   \   /   \  \    \____/   /___/_',replace(' _ _______      _ __________ /\             \n  _ __   /______________   // \\__________  \n    /   / \_____  \/  _/__//   \\____    /  \n   /   /   \   /   \  \    \____/   /___/_  \n   \________\ /    /_.     |__ _|_ /     /  \n- ------ - \______/D!`-----''- - :\______/ -»\n      BestUL V1.0 by Calypso/LOGIC !\n First Top-Uploaders XIM ever ! Pure ASM !\n','\n',char(10)),'BestUL.Doc',replace('                            __               ____\n ._________. .____________ /_/\ _____________\   \ ____________. ._________.\n |         | |             \_\/               \___\            | |         |\n |.       /\_|__    __/\________  ____________/\  /    /\______|_|_       :|\n ||    _ /  \   \___\/  \       \/\           \ \/____/  \         \ _    ||\n |:    //   /\___\   \  /\_______\ \___________\/\    \  /\_________\\    O|\n |o   . \  /.    /____\// \__   __\/   ________// \____\/. \________/ .   :|\n |.      \//    /     /.    /    ///    /     /o       //   /_____\       .|\n |        \_________ /\__________/\_________ /_______ /\_________ /        |\n |         | |     \/                      \/   __  \/         |\/        .|\n |_________| |________________________________ /\_\ ___________| |_________|\n :         : :                                 \/_/_           : :    Sk!n :\n\n                                    PRESENTS\n\n                     BestUL V1.0 coded by CALYPSO/LOGIC !\n\n    PROFESSIONAL TOOLS FOR PROFESSIONAL SYSOPS - GET THE REAL QUALITY !\n\n\nWHAT''S THE USE OF THIS TOOL ?\n-----------------------------\n\n        This door displays a list of your top-uploaders !\n\n        It is a XIM and NO CLI tool, this means you don''t waste\n        time in your logoff-batch for it !\n\n        It is so fucking fast that the user doesn''t see any\n        difference from a file displayed from your HD !\n        \n        Enjoy the maximum (ASM) speed and perfection...\n\n\nHOW TO INSTALL :\n----------------\n\n        Copy the files in the archive to your directories,\n        they are :\n\n        S:BestUL.Config\n        BBS:Doors/BestUL/BestUL.XIM\n        BBS:Doors/BestUL/BestUL.doc\n        BBS:Doors/BestUL/BestUL.Header\n        BBS:Doors/BestUL/BestUL.Tailer\n        LIBS:AEDoor.library ( © Sintax/WOT )\n\n        The S:BestUL.Config looks like this :\n \n        --------(cut here)--------\n        N                               <- Y/N turns first line on/off !\n        15                              <- Amount of Users to display !\n        BBS:User.Data                   <- The Location of your User.Data !\n        Ansi:BestUL.Header              <- Headertext to be displayed !\n        Ansi:BestUL.Tailer              <- Tailertext to be displayed !\n        --------------------------\n\n        The first line (Y/N) is for a better look with the header\n        in the archive. If you use your own header please use Y to\n        give it a better look. You''ll see !\n        \n\n        Now if you use /X2.x or S-Express then append the\n        BBS:Commands/BBS.CMD to your BBS.CMD !\n\n        If you use /X3.x copy the BBS:Commands/BBSCMD/BestUL.info\n        to your BBS:Commands/BBSCMD/ !\n        \n        Ok, now the door is installed and a user can call it with\n        typing BESTUL, but normally you want it displayed during\n        logon sequence ! Use this in a file during logon :\n\n        ~CC_BESTUL\n\n        This will call the door !\n\n        The advantage is that you don''t have to add another util\n        to your logoffbatch !!!\n\n        If you have a top-uploader tool running, then remove it\n        from your logoffbatch and replace the files where it normally\n        outputs to with the ones in the BBS:Screens dir in the archive !\n\n        Now you''re ready to enjoy !\n\nLAST WORDS :\n------------\n        \n        Now have fun with this great tool !\n\n        For Bugs (there are none), Ideas (yeah !) or just for fun\n        call my BBS :\n\n        BLACK MOON   +49-7054-8733   L^O^G^I^C wORLDHEADQUARTERS !\n                                     iLLUSION gERMAN hEADQUARTERS !\n\n        (2 Nodes - USR Dual 16.8 !)\n\n        See ya soon mates...\n                                                   Calypso !\n                                                   ~~~~~~~\n\nTHANX TO :\n----------\n\n        My beta-testers :\n        -----------------\n                Dalai Lama/Point Plank\n                Rotor/Gates of Asgard\n                Freddy Krueger/Boiler Room\n                Bloodwolf/Mortuary\n\n\nP.S. : OTHER HIGH-QUALITY /X-TOOLS BY L^O^G^I^C\n-----------------------------------------------\n\n        LGC-ST25.LHA    - StripAdd V2.5 (Text-Checker) by Warhawk/LOGIC\n                          THE BEST TEXT-CHECKER AVAILABLE !\n\n        LGC-LCK2.LHA    - LHA-Check V2.0 by Calypso/LOGIC\n                          THE BEST LHA-CHECKER AVAILABLE !\n\n        LGC-ZIP.LHA     - ZIP-Check V1.0 by Calypso/LOGIC\n\n        LGC-QN20.LHA    - QuickNew V2.0 by Calypso/LOGIC\n                          Fucking great util !\n\n        All LOGIC utils ever released are available and\n        FREE-DOWNLOAD on my BBS !\n\n\nGREETINGS:\n----------\n\n      - G.E.M. - Runt&Scottie - Polaris - Skin - XAD - Deltaforce - Andy -\n       - Wedlock - Blackbird - TCB - Planet Master - Proton - Bloodwolf -\n         - Linebacker - Cujo - Raider - Mitch - Mr.T - Samir - Power -\n\n                            - All LOGIC Members -\n\n··············································································\n               _ ________           _ ______________    \n         /\_______    _ /     _____   ________     /__: _____  sYSOPS:\n        /____  _ /    //_____/o  _/___  /    /____/   |/    /  """""""\n      _____:/  //     /     //   \    \/    /    //   /    /   cALYPSO !\n     /     |\  /__________ /.   /_\   /________ /.    \    \   cASTOR\n __|/____________\       \/_____________\     \/______|\____\  gHOSTRIDER\n   |                                                  :        (yOU ?)\n            - L·O·G·I·C - WHQ · I·L·L·U·S·I·O·N - GHQ -\n                                                   :_______|__\n 0.5      /\ __ /\             _______________     |    _ /|\n gIG hD! // \\//  \____________\________   _ /____ |    //   nUMBERS:\n        /.   \/    \________   _ /     /   //     \|   o/    """"""""\n       /    \  /    \      /   //\    /    /|      \  ./  +49-7054-8733\n      /      \/______\    /    /  \_______/ |    \    /  +49-7054-eLITE!\n     /_______|        \_______/             |_____\  /\n             :                                Sk!n \/  bOTH nODES 16.8 DS!\n \n      rUNNING (LATEST!) S-eXPRESS - sUPPORTING aMIGA aND sNES oNLY !\n','\n',char(10)),NULL,NULL,9624,7,0,NULL,NULL,NULL,'scan',1780048575);
INSERT INTO door_catalog VALUES('lgn_do21','LGN-DO21.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGN-DO21.LHA',NULL,'XIM','o-- ___     ________ _____--o',NULL,NULL,'LGN','|  /  /\   /  _____//  _  \ | ! /  / /  /  /_   //  //  /\| /  /_/__/  /_/  //  //  / /!',replace('o-- ___     ________ _____--o               \n|  /  /\   /  _____//  _  \ |               \n! /  / /  /  /_   //  //  /\|               \n /  /_/__/  /_/  //  //  / /!               \n/_______/_______//__//  / / :               \n\_______\_______\\__/__/ /                  \n:         PReSeNTS  \__\/   :               \n   CRaZyDoS V2.1 fixed      .               \n|  WoRKS WiTH /X2.x 3.x                     \n|  ReMoTe CLI/SHELL, CøøL   |               \no-- -- ---------------------o               \n','\n',char(10)),'CRaZy.DoC',replace(' \n                ___     _____________________________________                  \n               /  /\   /  __   /  _____/  __   /  __   /  _  \                 \n              /  / /  /  /_/  /  /_   /  /\/  /  /\/  /  //  /\                \n             /  /_/__/  __   /  /_/  /  /_/  /  /_/  /  //  / / \n            /_______/__/\/__/_______/_______/_______/__//  / / \n            \_______\__\/\__\_______\_______\_______\__/__/ /                  \n                                                       \__\/                   \n                              - PReSeNTS -                 \n\n    - 94-12-21 -              CRaZyDoS V2.1                 - 94-12-21 -\n            \n\n                            \n                           * aBouT CRaZyDoS *\n\n             CRaZyDoS Was written by CRUMP/LaGooN in Arexx -94\n             Coz i had no DoS door and i decided to make one.\n             Arexx isn''t to fast ya know, but i think it''s quite \n             good anyway, next release mabye will be made in E\n             for better speed, i don''t know.\n             (This better be short coz i hate doc files)\n\n      \n       \n                         * HoW To iNSTaLL 2.x *\n\n                Put this in your BBS:Commands/BBS.CMD file\n         \n-================================================- <-- CUT HERE                            \n*DOS      Rm255Doors:LaGooN/CRZDoS/CRaZyDoS.ReXX\n-================================================- <-- CUT HERE                            \n\n                   And copy the Dir LaGooN to Doors:\n\n\n\n\n                         * HoW To iNSTaLL 3.x *\n\n                          How easy can it be?  \n             Just copy the file Commands/BBScmd/DoS.iNFo\n                        To BBS:Commands/BBSCmd/\n                    Copy the Dir LaGooN to Doors:                 \n             Everyting is ready if the PATHS are correct\n\n\n\n                           * FiLeS iNCLuDeD *\n\n                    Doors/LaGooN/CRZDoS/CRaZyDoS.ReXX\n                    Doors/LaGooN/CRZDoS/Password.DAT\n                    Doors/LaGooN/CRZDoS/CRaZy.DOC\n                    Commands/BBScmd/DoS.iNFo\n\n                             * HoW To uSe *\n\n     Write your password in the file Doors:LaGooN/CRZDoS/Password.DAT\n     it''s CaSe Sensitive.                  \n\n     Just type DOS or what you have called the door, type the Password\n     you wrote in the password file and thats it...\n\n     Exit back to the bbs, Just press return at the CRAZYDOS prompt\n\n\n                           * HeLLo''S GoeS To *\n\n                  aLL LaGooN MeMBeRS, ZyS, DoC, XeRXeS\n                 BeNGT, KRuXMaN, MeMBRaNe, DReaM DRaiNeR\n                      eXiDoR, LuSSaR''N aND THe ReST        \n\n','\n',char(10)),NULL,NULL,3717,2,0,NULL,NULL,NULL,'scan',1780048575);
INSERT INTO door_catalog VALUES('lgn_dos','LGN-DOS.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGN-DOS.LHA',NULL,'XIM','o-- ___     ________ _____--o',NULL,NULL,'LGN','|  /  /\   /  _____//  _  \ | ! /  / /  /  /_   //  //  /\| /  /_/__/  /_/  //  //  / /!',replace('o-- ___     ________ _____--o               \n|  /  /\   /  _____//  _  \ |               \n! /  / /  /  /_   //  //  /\|               \n /  /_/__/  /_/  //  //  / /!               \n/_______/_______//__//  / / :               \n\_______\_______\\__/__/ /                  \n:         PReSeNTS  \__\/   :               \n   CRaZyDoS V2.0            .               \n|  WoRKS WiTH /X2.x 3.x                     \n|  ReMoTe CLI/SHELL, CøøL   |               \no-- -- ---------------------o               \n','\n',char(10)),'CRaZy.DoC',replace(' \n                ___     _____________________________________                  \n               /  /\   /  __   /  _____/  __   /  __   /  _  \                 \n              /  / /  /  /_/  /  /_   /  /\/  /  /\/  /  //  /\                \n             /  /_/__/  __   /  /_/  /  /_/  /  /_/  /  //  / / \n            /_______/__/\/__/_______/_______/_______/__//  / / \n            \_______\__\/\__\_______\_______\_______\__/__/ /                  \n                                                       \__\/                   \n                              - PReSeNTS -                 \n\n    - 94-03-21 -              CRaZyDoS V2.0                 - 94-03-21 -\n            \n\n                            \n                           * aBouT CRaZyDoS *\n\n             CRaZyDoS Was written by CRUMP/LaGooN in Arexx -94\n             Coz i had no DoS door and i decided to make one.\n             Arexx isn''t to fast ya know, but i think it''s quite \n             good anyway, next release mabye will be made in E\n             for better speed, i don''t know.\n             (This better be short coz i hate doc files)\n\n      \n       \n                         * HoW To iNSTaLL 2.x *\n\n                Put this in your BBS:Commands/BBS.CMD file\n         \n-================================================- <-- CUT HERE                            \n*DOS      Rm255Doors:LaGooN/CRZDoS/CRaZyDoS.ReXX\n-================================================- <-- CUT HERE                            \n\n                   And copy the Dir LaGooN to Doors:\n\n\n\n\n                         * HoW To iNSTaLL 3.x *\n\n                          How easy can it be?  \n             Just copy the file Commands/BBScmd/DoS.iNFo\n                        To BBS:Commands/BBSCmd/\n                    Copy the Dir LaGooN to Doors:                 \n             Everyting is ready if the PATHS are correct\n\n\n\n                           * FiLeS iNCLuDeD *\n\n                    Doors/LaGooN/CRZDoS/CRaZyDoS.ReXX\n                    Doors/LaGooN/CRZDoS/Password.DAT\n                    Doors/LaGooN/CRZDoS/CRaZy.DOC\n                    Commands/BBScmd/DoS.iNFo\n\n                             * HoW To uSe *\n\n     Write your password in the file Doors:LaGooN/CRZDoS/Password.DAT\n     it''s CaSe Sensitive.                  \n\n     Just type DOS or what you have called the door, type the Password\n     you wrote in the password file and thats it...\n\n     Exit back to the bbs, Just press return at the CRAZYDOS prompt\n\n\n                           * HeLLo''S GoeS To *\n\n                  aLL LaGooN MeMBeRS, ZyS, DoC, XeRXeS\n                 BeNGT, KRuXMaN, MeMBRaNe, DReaM DRaiNeR\n                      eXiDoR, LuSSaR''N aND THe ReST        \n\n^-=-^-=-^-=-^-=-^-=-^-=-^-=-^-=-^-=-^-=-^-=-^-=-^-=-^-=-^-=-^-=-^-=-^-=-^-=-^\n\n                          THiS FiLe PaSSeD TRouGH\n     _____ /\ __ __    _____ __ __ _____ /\___     __    /\___ _____ ____\n    |  _  Y  Y  Y  |  |  _  Y  Y  Y  _  Y  _  |   |  |  Y  _  Y  _  Y  _ \\n    |  |__|  |  |  |  |  |  |  |  |  |  |  |__|   |  |  |  |  |  |  |  |  Y\n    |  |__|  |  |  |__|__|  |  |  |    _|  _|_    |  |__|     |  |  |  |  |\n    |  |  |  |  |  |  |  |  |  |  |  _  |  |  |   |  |  |  |  |  |  |  |  |\n    |  |  |  |  |  |  |  |  |  |  |  |  |  |  |   |  |  |  |  |  |  |  |  |\n    |  |  |  |  |  |  |  |  |  |  |  |  |  |  |   |  |  |  |  |  |  |  |  |\n    |___  |_____|_____|  |  |_____|__|__|_____|   |_____|__|__|__|  |___  |\n        \/               |__|                                    |__|   \/\n                               SySoP - CRuMP\n                             SeRVaNT - MR ReaL\n\n                        THe NuMBeR iS +46-51o-28526\n\n^-=-^-=-^-=-^-=-^-=-^-=-^-=-^-=-^-=-^-=-^-=-^-=-^-=-^-=-^-=-^-=-^-=-^-=-^-=-^\n','\n',char(10)),NULL,NULL,8189,6,0,NULL,NULL,NULL,'scan',1780048575);
INSERT INTO door_catalog VALUES('lgn_triv','LGN-TRIV.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGN-TRIV.LHA','AmigaGuide','XIM','AmigaGuide',NULL,'NiKE','LGN','___   ___   /_____/ _   / _   /_ ___ /  /__/     / ____/  /  /  /  /  X  / ::/  /  /__/__/ /_  /____ /_____/  X  /:',replace('          _ ______      ____________        \n     ___   ___   /_____/ _   / _   /_ ___   \n    /  /__/     / ____/  /  /  /  /  X  /   \n ::/  /  /__/__/ /_  /____ /_____/  X  /:   \n :/_____/:::::/_____/::::\/:::::/__/__/::   \n«------------------------------------[rick] \n         /X Trivia v1.00 by NiKE\n     The ultimate Trivia for /X v3.x!\n   Released 23 March in the year of 1994\n«------------------------------------------\n','\n',char(10)),'Trivia.Guide',replace('@database Trivia.Guide\n\n@Node MAIN "/X Trivia Challenge v1.0 AmigaGuide Manual (c) 1994 Nike of LaGooN"\n\n	This is just another trivia door, that asks the user some questions..\n	But there are some things that makes this more cool then other...\n\n	It is quite self-explaining, so just set up the door and use the\n	on-line help if you need it.\n\n                  @{" Install           " Link Install}\n                  @{" Contact           " Link Contact}\n                  @{" The Question File " Link Questfile}\n                  @{" How To Use        " Link ToUse}\n                  @{" Future Plans      " Link Future}\n                  @{" Thanks etc..      " Link Thx}\n                  @{" History           " Link History}\n\n@Endnode\n\n@Node Contact "Contact NiKE!!!"\n\n	If you have any bug reports, sugestions or remarks about this\n	program, please contact me. This can be done the following ways:\n\n	Modem:\n		Send mail to NIKE at one of these boards:\n		Instant Pleasure  - +46-51027660\n        Pet Semetary      - +46-INVITED!\n        Or any elite bbs in sweden..\n\n@Endnode\n\n@Node Install "Installation.."\n\n\n	To install this program, copy these files to the directory\n	"Doors:LaGooN/Trivia"..\n\n	Trivia.Rexx\n	Trivia.Cfg\n	Rand\n	Questions.X (Where X is numbers from 1 and up to 9.)\n	Text/HALLofFAME\n	Text/TrivChall\n	Text/Menu\n	Text/Sysop-Menu\n	Text/Info\n	Text/Fame\n\n	You should also make a directory in this path which you call Users.\n	All files in the Text directory, should still be in a directory\n	called Text.\n\n	Then, you must edit the configfile (Trivia.cfg) properly.\n	  The first line should be the filename of the bulletin where you\n	want the highscore list to be.  If you don''t want the list as a\n	bulletin, then just enter another name.  It''s important that you\n	enter something becasue Trivia uses that file as an internal\n	highscore list too.  But there''s no catastrophy if the file is\n	deleted as long as the filename is included in the configfile.\n	Trivia uses it''s personal file as well, but that file is not very\n	nice to look at. :)\n	  The second line should be the maximum number of entries allowed\n	on the highscore list.\n	  The third line should be the number of questions each user can\n	try to answer each day.\n	  The fourth line should be the name of the Sysop on the BBS. This\n	person will not be included in the highscore list, but he''s the only\n	person who can reset the highscore list, and change number of\n	questions per day.\n	  The fifth line should be the filename of the bulletin where you\n	want the "Hall of Fame" list to be.\n	  The sixth line should be the number of points needed to get into\n	the "Hall of Fame" list.\n	  The seventh line should be the number of times Trivia should\n	try to find a new question if the question found is the same as\n	last time. If you chose a high number, Trivia may need more time,\n	and on a slow machine, this will be very anoying for the users.\n	  The eigth line should contain the number of questions available\n	for this trivia. That means the number of questions in the question-\n	files.\n	  The ninth line should contain the maximum number of questions \n	each questionfile can have. If you only want one questionfile, set\n	this number very high.\n\n	If you want to, you can edit an info file called \n	Doors:LaGooN/Trivia/Text/Startup. This file	will be displayed\n	when you start Trivia. It''s optional if you want\n	that file, and there''s no need for it to get Trivia to work.\n\n	Copy the icons in Commands/BBSCMD to yer BBSCMD directory. They should be\n	OK as they are, but you might want to change the access..\n\n	It might be smart to check if a file called "T:TriviaInUse" exists\n	and if it does delete it when you start The BBS. If you have assigned\n	T: to you harddisk, and The BBS crashes while somebody used the\n	trivia-door, it won''t be deleted and nobody can use the door.\n@Endnode\n\n@Node QuestFile "The Question File(s)"\n\n	I have not included any huge question file for an obvious reason.\n	If I did, then most of the Trivia''s on the different BBS''s would be\n	quite useless since everybody has the chance to get this program\n	and the included question file.\n\n	The question file is quite easy to edit if you want more questions.\n	This can be done this way:\n	Just enter a line with the question, and then enter a line with the\n	answer.  The total number of questions should be set in the config-\n	file.  If you have many questions, it migth be wise to divide them\n	up into several files. The questionfiles should be named\n	"Questions.X" where X is the number of the file. Up to nine files\n	are supported by this program. That should be enough. If you have\n	835 questions, you could divide it into files with a limit of 200.\n	The 200 first questions & answers should then be in the file called\n	Questions.1, the next 200 in Questions.2, the next 200 in Questions.3,\n	the next 200 in Questions.4, and the last 35 in Questions.5.\n	You should not include these two signs in the question file:  '' "\n	It won''t make things crash, but the question might look a bit silly.\n\n@Endnode\n\n@Node ToUse "How to use!"\n\n	If you wonder how to use this door, then just open the door from\n	yer BBS, and use the Info command for information about this subject.\n	One thing not mentioned there are the Sysop commands. These are the\n	commands, and what they do:\n	D - Goes through the file containing new questions from the\n	    users, and lets you install those you want.	\n	K - Deletes all users, and clears the highscore list.\n	L - Displays the question file.\n	N - Change number of questions each user has each day.\n	R - Read the file containing complaints about the questions from\n	    the users.\n	Remember that the Sysop won''t be included in the highscore list.\n\n	You can run several Trivias on the same BBS. This can be useful if\n	you want different questions. To do this, just use another path,\n	and install Trivia in this path. As an extra feature, you can now\n	edit the Startup files (described earlier in this manual) so that\n	they display what kind of questions this Trivia has.\n\n@Endnode\n\n@node Future "Future Plans!"\n	I might want to convert this to amiga E in the future, ARexx is so slow..\n	This was converted from ABBS to /X coz i changed my BBS program......\n	The original was done by Marius Willms, to contact him (Why should you? ;))\n	Call ABBS Support..\n@Endnode\n\n@Node Thx "Thanks & Greetings & Messages"\n	Thanx to Crump/LaGooN for telling me to convert it....It''s due to him\n	this program exists at all...\n	Exidor/Razor 1911            - When will you release the trackmo??!\n	Kid Curry/Classic            - Gr8 BBS!!\n	Rick/LaGooN                  - Finally a nice looking file_id.diz!!\n	Death Warrior/Wizzcat        - Don''t be so lame! Make something NEW!\n	Metal Warrior                - Get a real BBS program!\n	And hello to all friends..\n@Endnode\n\n@Node History "History!"\n\nv1.0 - First public release!\n@Endnode\n','\n',char(10)),NULL,'auto-added',64485,4,0,NULL,NULL,'lgn_triv','scan',1780048575);
INSERT INTO door_catalog VALUES('lgth_zip','LGTH_ZIP.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LGTH_ZIP.LHA','zipcheck','XIM','zipcheck',NULL,NULL,'LGTH','<<<<<<<    this is the real zip checker <<<<<<<    for your /X system ! <<<<<<<    "never released yet" but',replace('<<<<<<< 1. ZIP Checker & Adder for /X 3-4.X \n<<<<<<<    this is the real zip checker\n<<<<<<<    for your /X system !\n<<<<<<<    "never released yet" but\n<<<<<<<    very cool . checks zip files for\n<<<<<<<    crc errors and add your bbs adds\n<<<<<<<    as comment very fast in the file!\n<<<<<<<    THIS IS THE NEVER RELEASED \n<<<<<<<    ZIPCHECKER FROM janx/poison \n<<<<<<<    from 1993 it s time now for \n<<<<<<<    publishing this great one !\n<<<<<<<    have fun ! Signed a Sysop \n','\n',char(10)),'ZIPADDER.TXT',replace(' \n\n \n \n\n \n \n           here you can add your bbs advertisment ! \n\n\n             >> maximal 28 lines << it s better\n \n  \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n','\n',char(10)),NULL,'auto-added',4174,5,0,NULL,NULL,'lgth_zip','scan',1780048575);
INSERT INTO door_catalog VALUES('lhac00l','LHAC00L.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LHAC00L.LHA',NULL,'XIM','________   ___________________________',NULL,NULL,NULL,'/    ___/__|_       _     /     _  ___/____ /\____        /       \___/      /         / \____________/_________\   \______________/:',replace('  ________   ___________________________\n /    ___/__|_       _     /     _  ___/____\n/\____        /       \___/      /         /\n\____________/_________\   \______________/:\n::.:.:.:.:.:.:.:.:.:.:.:.:.:.:.:.^starfix^.:\n:             S.T.C. pRESENTS              :\n: A LHA STRIP FILE WITH OVER 4000 ADDS     :\n: A MUST HAVE FOR ANY SYSOP DUDE OR ANY    :\n: ONE ELSE WHO *HATES* LHA ADDS.           :\n: 100% VERSION STRIPS ALSO WILDCARDS       :\n`------------------------------------------''\n','\n',char(10)),'LHAStrip.Doc','',NULL,NULL,39035,7,0,NULL,NULL,NULL,'scan',1780048575);
INSERT INTO door_catalog VALUES('lhacck','LHACCK.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LHACCK.LHA','LhaCheck','XIM','Execute_Me','2.0',NULL,NULL,NULL,replace('LhaCheck v2.0\n','\n',char(10)),'LhACheck20.doc',replace('                            __               ____\n ._________. .____________ /_/\ _____________\   \ ____________. ._________.\n |         | |             \_\/               \___\            | |         |\n |.       /\_|__    __/\________  ____________/\  /    /\______|_|_       :|\n ||    _ /  \   \___\/  \       \/\           \ \/____/  \         \ _    ||\n |:    //   /\___\   \  /\_______\ \___________\/\    \  /\_________\\    O|\n |o   . \  /.    /____\// \__   __\/   ________// \____\/. \________/ .   :|\n |.      \//    /     /.    /    ///    /     /o       //   /_____\       .|\n |        \_________ /\__________/\_________ /_______ /\_________ /        |\n |         | |     \/                      \/   __  \/         |\/        .|\n |_________| |________________________________ /\_\ ___________| |_________|\n :         : :                                 \/_/_           : :    Sk!n :\n\n                                PRESENTS\n\n                   LhACheck v2.0 coded by WHiZ/LOGiC !\n\n    PROFESSIONAL TOOLS FOR PROFESSIONAL USERS - GET THE REAL QUALITY !\n\n\nWHAT''S THE USE OF THIS TOOL ?\n-----------------------------\n\n        It''s another LhAChecker coded in pure ASM with a lot of cool\n        features. For example, you have the possibility of adding and\n        stripping unlimited adverts ! Additionally you can choose\n        having all stripped adverts displayed or not. The coolest\n        feature of this Checker probably is that the old and new\n        size of the LHA/LZH File is displayed after stripping and\n        adding all adverts.\n\nWHY SHOULD I USE IT ?\n---------------------\n\n        If you love speed and beautiful outputs this is the tool\n        you have been waiting for ! Install it, and see for yourself.\n\nHOW TO INSTALL THIS TOOL :\n--------------------------\n\n        It''s quite easy to install. If you run /X v3.x or /X v4.x all\n        you need to do is the following with your FCheck LHA/LZH icons.\n        I hope that /X v2.x or S-Express Sysops will be able to install\n        this tool on their own.\n        \n        CHECKER=C:LhACheck\n        OPTIONS=-D S:ConfigFile S:Stripadverts\n        STACK=10000\n        PRIORITY=1\n        ERROR.1=CORRUPT\n\n        Line.1: Path to this LhA Checker\n        Line.2: -D displays all stripped adverts\n                -S will surpress the display\n                \n                S:ConfigFile or whatever you name it, should be the file\n                in which all your Adverts are listed, e.g.:\n\n                DH0:MyAD.Txt\n                "DH1:Call.Displayme    "\n                "S:Give_it_a_Ring  "\n\n \n               -^- Unlimited Lines -^-\n\n\n                S:Stripadvertss or whatever you name it, is the file in\n                which all adverts you want to strip are listed, e.g.:\n\n                *.displayme\n                Great_System\n                TypeMe.TXT\n\n\n                -^- Unlimited Lines -^-\n\n                \n        Line.3: Stacksize of this tool. Play around with it, i always take\n                10000\n        Line.4: Priority of this tool. Play around with it !\n        Line.5: Very Important ! Do not change it or all corrupt archives\n                won''t be moved to your hold !\n\n       NOTE: It''s not BBS specific, meaning you can use it also with other\n             BBS Software or even in your DiskMaster, DOPus or whatever !\n\nLAST WORDS :\n------------\n\n        Have fun with this great Checker ! It has been tested for a long time\n        now without ANY problems. If you should discover bugs or have any\n        suggestions to make about this tool, feel free to leave me mail via\n        AmiXNet (WHiZ@203001) or give my board PSYCHO TERMiNAL a ring !\n\n        See ya soon mates...\n                                                                 WHiZ/LOGiC !\n                                                                 ~~~~~~~~~~~~\n\nSOON TO BE RELEASES TOOLS - ALL CODED IN ASM! :\n-----------------------------------------------\n\n       Turbo Boost v1.x - Another Text Adder/Checker/Stripper !\n       BullUp v1.1      - /X & S!X Online Bulletin Updater !\n       ModSaM vx.x      - The Ultimate Pager (Modules/Samples and more).\n                          Now coded in pure ASM !\n                          Update to the lame ARexx Release !\n       LogonInfo v2.x   - The Best Frontend you''ve ever seen!\n\nGREETINGS:\n----------\n\n	The Champ · Halfast · Mr Hyde · The Fly · Freddy Krueger · Franky\n	Joker/ZZC · Dalai Lama · SchwabenPoweR · Red Alert · Rioter · BBC\n	2-Cool · g.E.m. · Sid Vicious · Ccs & Eqx · Calypso · TerrorizeR\n	Dexter/aFL · Foxx''n''Lynxx · Ernesto · Snow · Jive · Sintax · Treach\n	The Addict · Cobra · Manta · Sce · Hot Kid · Rofoe · Don Dog\n        Cas(ch)tor · Warhawk · Dragon · Warlord · and all LOGiC Members !\n	\n\n      _______/\ __________________ /\_______/\______________ ___________/\\n     /     ___//   ____________   \\______  \________  \    |    /   ____/\n  Mb/  ___/___/   / \   \/   / \   \|    |\  \|   _|/ _/\__ | __/  __/___\n  _/   \_    /    \_/    \   \_/    \    |/   \   \__  \  /   \/   \_/   \\n  \    _/    \           /          /          \   |/   \/     \_         \\n   \___\  ___|\_________/\_________/|__________/________/_______/_________/\n        \/                                                                \n\nClick...\n\n··············································································\n                                                    ·\n     _ ______________________           ____________¦________________\n   ·    ________   /   _____/________  /· ______/   |   \______    o/  ·\n   ¦_____/   _____/_____   /\    \   \//  /____/         \    /   //___¦\n   |    /____/   /________/  \______ /_______ /_____|_____\_______/Sk¡n|\n   |                          \ _______\    \/      ¦                  |\n   |                           \/                   ·                  |\n   |                                       ___        ·                |\n   |                                      /\__\ _     ¦_____    _ _____|\n___|_________________  /\______/\ __ /\   \/__/  ____ |  _ /____ _    /|___\n\ _ o    _ /  __    /_/___  _ /  \\// o\________|    \|  //o    \/   /    /\n \//     \/  ______/    |/  //    \/   \\       /___\ \  //     /_______ /\n /________\______ /_____/   /____\  /____\_____/     \  /_________\    \/\n   |            \/      \___\     \/                  \/               |\n   |                                                                   |\n   |   eNDLESS pIRACY wORLD hEADQUARTERS - lOGiC gERMAN hEADQUARTERS   |\n   |                      rEFLEX gERMAN hEADQUARTERS                   |\n   |___________________________________________________________________|\n     \n                       +49-aSK-fOR-iT! [ dUAL 28.8 ]\n                       +49-aSK-fOR-iT! [ dUAL 21.6 ]\n          \n    > mASTER: WHiZ/LOGiC!           sLAVES: Calypso/GOD - The Fly/TRY <\n','\n',char(10)),'{"STACK":"10000","PRIORITY":"1"}','auto-added',7695,1,0,NULL,NULL,'lhacck','scan',1780048575);
INSERT INTO door_catalog VALUES('lhacheck','LHACHECK.LZX','~/Code/amiexpress_doors/Archives/AmiExpress/LHACHECK.LZX',NULL,'XIM','LHACheck',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'auto-added',44264,0,0,NULL,NULL,'nc_lchk_3','scan',1780048575);
INSERT INTO door_catalog VALUES('lhas10r','LHAS10R.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LHAS10R.LHA','LHAStrip','XIM','LHAStrip','1.0',NULL,NULL,NULL,replace('LHAStrip V1.0r\n','\n',char(10)),'LHAStrip.DOC',replace('***************************************************************************\n                             LHAStrip V1.0r\n***************************************************************************\nReleased: 08/11/92\ndone by : GOOSEMAN/ANALOG\n\nArchive Contents upon release:\n\nLHAStrip	(  2432 Bytes)          : Executable\nLHAStrip.DOC                            : Documentation\nLHA                                     : Sample Checkfile (-> BBS:FCHECK)\n\nShort Description:\n\nLHAStrip automatically strips all .DISPLAYME Files out of LHA/LZH packed\narchives. It can optionally test the archives and/or add a Textfile (BBS-\nAdvertisment) to it.\n\nSyntax:\n\nLHAStrip [-t] [-a -TEXTFILE] [ARCHIVE]\n\n-t	 : If you want to test the archive choose this option\n-a       : It will add TEXTFILE to the ARCHIVE. Note the "-" in\n           Front of TEXTFILE informing LHAStrip that this is the\n           Text to be added and not the archive.\n-TEXTFILE: See above. THIS SHOULD BE LOCATED IN YOUR S: Directory\nARCHIVE	 : Name of the file to be processed.\n\nWhy is it only 2432 Bytes?\n\nI think it''s a waste of diskspace always coding special routines. We\nhave our LHA from Stefan Boberg which includes all we need for this\nprog and that''s why I use it.\n\nNOTE: LHA has to be accesible in your C: or anyother path included\n      in the PATH variable.\n\nHints:\n\n- The Sample LHA-Checker File (which goes into BBS:FCHECK/) is set up\n  for LHA V1.32. If you don''t have this Version check the errormessages!\n\n- TEXTFILE doesn''t necessarily have to be a Textfile, in fact ANY DOS-\n  File (EXEcutables, LIBrarys,...) can be included.\n\n- Testing of Archives can be VERY SLOW on 68000 machines so you may want\n  to disable testing.\n\n- If you select Archivetesting the program will output the results of your\n  LHA to Amiexpress so your BBS:FCHECK/LHA File can determine whether the\n  File is faulty or not.\n\n- As LHA is able also to process LZH Files this tool can be used on\n  LZH Packed Archives too.\n\nDisclaimer:\n\nThis program has been tested only on 68000 Machine. It SHOULD run without\ntrouble on any other processor type (20er,30er). I cannot be held responsib-\nle for any physical damage this program may do to any of your hardware.\n\nBUG-Reports / Errors / Money:\n\nSend all of the above to:\n\n                   GOOSEMAN, P.O. Box 33, CH-9204 Andwil\n\nor call my BBS:\n\n                    PROTON DREAMS at +(41) 71 850-612\n\nor for a voice chat:\n\n                      GOOSEMAN at +(41) 71 850-176\n','\n',char(10)),NULL,'auto-added',3854,1,0,NULL,NULL,'lhas10r','scan',1780048575);
INSERT INTO door_catalog VALUES('lister07','LISTER07.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LISTER07.LHA',NULL,'XIM','Lister.exe',NULL,NULL,NULL,NULL,replace('XXXX....\n','\n',char(10)),'Lister.doc',replace('                        FileLister V0.7ß Documents\n\nThis is a X Type door for the AmiExpress V2.33+ system coded by Chucky.\n\nWhat it does:\n\nIt simply takes all directorys in the current conference the user is located\nin and makes one file and let the user download this list free of any ratios!\n\n\nWhat is it good for?\n\nWell some sysops like i have some big filelists like modules, pictures or just\na BIG harddrive and often get the question from the users: Can i DL your\nfilelist so i can check them off-line??\nThis is the answer  now you dont have to use "join" in the logoff script and\nyou can be out partying when your users without problems can DL the filelist\nand be happy!\n\n\nHow do you install it?\n\nWell read the documents to your AmiExpress on how to install a X type of a door\nPlease remember that this door doesnt support more then ONE version at the\nsame time running so multinode sysops should NOT set this door as a multidoor!\n\nConfigurations:\n\nTheres a file in the S: directory called Lister.Cfg and its set up like this:\n\nram:lista.txt\n#  Filelist from GangBang at +46 (0)554-12133  16.8 KBps HST/DS   Sysop: Chucky\nN\n\nthe first row is the NAME of the file that the user will download\nthe second row is a header and can be only on ONE line right now. the \n# char in the beginning must be there and will not be shown in the list!\nthis is just for future versions where i will put a possability of having\na filename here where you can have a whole file as a header instead!\nthe last line is a simple Y or N if you have a Y the file will be deleted\nafter the user have downloaded the file!  any other chars will do so the\nfile will NOT be deleted after DL!\n\n\n---------------------------------------------------------------------------\n\nHistory:\n\n0.5ß   92-12-21:\n The first released version for betatesters\n\n0.6ß   92-12-23:\n The first released version for the public (STILL a ßeta version)\n Inserted configfile\n Inserted a function so it adds a text in the callerslog\n Put in some ANSI colors into the text shown on the screen\n\n<Happy new year folks!>\n\n0.7ß   93-01-02:\n Bugfix, when someone tried to use the list function in a conference that\n doesnt have any files the computer crashed!\n Fixed the versiontag string aswell! :)\n\n---------------------------------------------------------------------------\n\nPlease send bugreports and tips about new doors to me on:\n\nGangBang BBS: +46 (0)554-12133  24Hrs   16.8 DS\nFidonet: 2:203/602.2@John Hertell\n\n','\n',char(10)),NULL,'auto-added',9446,5,0,NULL,NULL,'lister07','scan',1780048575);
INSERT INTO door_catalog VALUES('listu12','LISTU12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LISTU12.LHA','Ulist','XIM','Ulist',NULL,'Mr.',NULL,'mi-Express User Listing Utility',replace('ListUsers+ V 1.2 Programmed by Mr. MigAn\nmi-Express User Listing Utility\n','\n',char(10)),'ListUsers.DOC',replace('                    ListUsers+ V 1.2   [22/05/94]\n      Programmed by Mr. Mig    /    ANSI Colors+Setup by Empire\n                    For use with Ami-Express BBS\n\nIntroduction\n------------\n    Here is yet another /X utility.  But look on the bright siude, it''s\nMY first /X utility release!  Don''t get me wrong, I''ve written quite a few\n/X utils, but I have never released any of them.  This is NOT the best\n/X utility I''ve written.  I have written much better ones, but since Ami-\nExpress doesn''t have any User Listing function, I have made one for myself\nand for those who wish to use it.\n\n    It''s not fast. It''s written in Arexx.  It is not efficient, but it get''s\nthe job done. Check out the included IFF file to see how the output looks.  If\nyou don''t like it, simply don''t use it.\n\nHow to Install it\n-----------------\n    I have included a little script which will install all the files into\ntheir proper directories, ASSUMING that you have all the proper assignments\n(i.e. - BBS:, BBS:Utils/, Doors:)\n    If you don''t have these assignments, the Install script will not work.\nTo run the install script, CD into the directory containing all the ListUsers\nfiles, and type ''LUInstall''.  That''s it.  Here is what it does (in case you\nwant to install it yourself)\n\n    - It copies the ''ListUsers'' directory into your Doors: assignment.\n    - It copies the ''UList'' command into your BBS:Utils/\n    - It copies the ''User.info'' command icon into your\n      ''BBS:Commands/BBSCmd/'' directory so your user can access it.\n\n    Simple enough? Good.\n\nWhat you also have to do!!\n--------------------------\n    You also have to add the following line into your Midnight Update\nScript! (You know, that script you run every midnight?)\n\nBBS:Utils/UList All A B F H L M N P Q >BBS:UserList\n\n    You need this command line executed every midnight if you want your\nuser list to ever be updated!!  Read below why you have to do this.\n\nWhat ListUsers+ does\n--------------------\n    This utility simply lists all active users showing their Slot Number,\nLocation/Group, Number of Calls, Number of Uploads/Downloads, Number of\nMegs Uploaded/Downloaded and Number of Messages Written.  Pretty\ninformative, eh? (Look at the IFF!!!)\n    One thing I should mention, since I still haven''t figured out how to\nread binary files in Arexx, I had to use another sort of means to read the\nuser data file to get all the data.  I had to use:\n\n         "UList v0.8 by Nameless/DeSiRe Sysop of Snarfs'' Pub"   (Thanks!)\n\nto read all the data, which I save into a text file and read from Arexx.\nThis is also why you must add the previously mentionned update line to your\nmidnight update script because I could not run this from within the Arexx\nprogram.  It was impossible.  Beleive me, I tried!\n    To use it, after you install the "User.info" into your\n"BBS:Commands/BBSCmd/" drawer, the user, or sysop simply has to type\n''USER'' at the BBS prompt.  If you wish to rename it to ''UL'' or something\nelse, simple rename "User.info" to "UL.info", and voila.\n    Oh, by the way, this method is used for /X v 3.xx.  I have never seen\nthe older versions, but I hope no one else is still using it.  It''s ooooold!\n\nFeatures\n--------\nNothing much, but I''ll list them anyways:\n\n    - Adjusts itself to the screen length of each different user\n      when the "Continue [Y/n]" prompt comes up.\n    - Doesn''t show the Sysop account.\n    - Doesn''t show any inactive (Deleted) users.\n    - Displays everything in a nice looking screen (I hope it''s nice!)\n    - Displays the red and white properly when a sysop (Access = 255)\n      logs on.\n\nHistory\n-------\nV 1.2 (OFFICIAL RELEASE!)\n\n- It now gives the user a "Continue [Y/n]" prompt which adjusts\n  to the user''s screen length.  Before it showed the default /X\n  Continue Prompt (Yuk!) which didn''t even work.\n\nV 1.1\n\n- Changed some colors and column sizes to make it look much nicer.\n\nV 1.0\n\n- Initial birth of ListUsers+.\n\nLast words\n----------\nWell, that''s about it.  I hope you enjoy this utility.  It''s not a piece\nof crap like most of the stuff I''ve seen for /X, but it''s not the best /X\nutility either.  I haven''t seen any User List commands for /X better than\nthis though.\n\nIf you would like to give me some comments (PLEASE! I would like hear from\nyou, no matter who or where you are), you can E-Mail me through Internet at:\n\n                        [email removed]\n\nOr contact me on almost any Amiga BBS in Montreal, Quebec, Canada.\n','\n',char(10)),'{"ACCESS":"255)"}','auto-added',16102,3,0,NULL,NULL,'listu12','scan',1780048575);
INSERT INTO door_catalog VALUES('lll_pp','LLL-PP.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LLL-PP.LHA','PowerPager','XIM','PowerPager',NULL,']****************','LLL','Liderlige Lamsebamse Lise Productions Presents PowerPager v0.12 [Public ß-Release] ****************[ FEATURES ]****************',replace('*************[ HAPPY NEW YEAR ]*************\n   Liderlige Lamsebamse Lise Productions\nPresents PowerPager v0.12 [Public ß-Release]\n****************[ FEATURES ]****************\n- Full GUI Configuration\n- Chat-Request Window\n- Chatflag Override, and BlackListing\n- Custom Execution Of A Command.\n- Macros, and more..\n****************[ CODED BY ]****************\n         MeNaCe/Searching 4 A Group\n*[ MA! ]*************************[ 311295 ]*\n','\n',char(10)),'PowerPager.DOC',replace('*[ PowerPager Documentation ]************************************************\n\n            PowerPager V0.9 [Beta] For AmiExpress/SigmaExpress\n                Updated for v0.12 [Beta] 27/12/95 [at TP5]\n Code: MeNaCe/Indenpendent ÷ Additional Ideas: Flozzy ÷ Beta: Flozzy & Enzo\n\n*[ Program Description ]*****************************************************\n\nPowerpager is a quite powerfull pager with features FULL GUI Configuration,\nChat-Request  Window,  Macros, Accept Chat, and Quiet ( Disables the Beep''s\nwithout letting user know it.  )\n\n*[ Installation ]************************************************************\n\nInstall  this  door  as  every  other  XIM-Door.   The  door  is  tested on\nAmiExpress  and  Sigma  Express  so  there  should  be  no problem.  If you\nencounter some, please report this to me asap - so I can fix the problem.\n\n*[ Program Logic ]***********************************************************\n\nIf a user wants to chat, the door will:\n\n- Check if a log is wanted.  If so, the file will be opened.\n\n- Check if intuition.library, gadtool.library, reqtools.library\n  utility.library and the memory allocation for the configuration went ok.\n  If one or more of these thing fails it will display a error, and exits.\n\n- Everything ok: If SysopIsInChat-Action is set to REFUSE and the\n  the sysop is in chat the door will display: \n  BBS:BBSTexts/PowerPager/ChatRefuse(access).txt(.gr) and exit.  If the\n  user got clearance to override the CF the door will continue without\n  showing any file.\n\n- At this point the doors checks if the user is blacklisted, if so\n  the   displays  BBS:BBSTexts/PowerPager/BlackListed(access).txt(.gr)  and\n  exits.\n\n- If the chat flag is off and the user tries to page - the file\n  BBS:BBSTexts/PowerPager/SysopNotAvail(access).txt(.gr) is displayed,\n  but the user got CF Override access - the door will continue as if\n  the chatflag was set to on.\n\n- The paging process: The file \n  BBS:BBSTexts/PowerPager/Paging(access).txt(.gr)\n  is displayed. And if the SysopIsInChat-Action is set to NOTIFY\n  an additional line is display, informing the user that sysop\n  is already in a chat with another user.\n\n- A reason is prompted. If the input is valid the door continues..\n\n- At this point PowerPager sets the env-variable (STATS@) to\n  Requesting Chat, and sets up the window with gadgets.  The window\n  is opened on the default public screen, and this screen is moved\n  to front if it isn''t the current screen.  PowerPager pages for\n  about 17 sec, and if it receives no response it''ll just exit, closing\n  the window.  At every half second a DisplayBeep is made.\n  The  process  is aborted by pressing any key.  If the sysop presses "Send\n  Text"  the  text/macro  displayed in the cyclegadget is send to the user,\n  and the door exits.  If the text startes with an ''<'' the rest should be a\n  filename.  eg:  "<BBS:Comming" cause the door to display a file named\n  BBS:Comming(access).txt(.gr).\n  To change macro/text press the cyclegadget - or use f1 through f10\n  to select text.  If the sysop presses the "Enter string.." a ReqTools\n  string request pops up ( but also freezes the paging process :( ).\n  Anything entered in this request is displayed to the user, and\n  afterwards the door exits.  The two last buttons are probaly the most\n  important of them all.  "Accept" accepts the chat-request, and goes\n  into chat after pressing this on.  "Quiet" Stops the door from using\n  DisplayBeep - and thereby stops the beep''ing.  Nice if you don''t wanna\n  talk to the user without beeing "nasty" ( Nothing happens from the user\n  point of view ).\n\n- If the chatrequest was unsuccessfull the door exits.\n\n*[ Configuration ]***********************************************************\n\nTo  setup  Powerpager  start  the  door  from  the  shell,  and  a nice gui\nconfiguration  window appears.  The first 10 gadgets ( 2*5 ) is the macros.\nHere you can setup your own macros.\n\nThe next gadget is the so-called SysopInChat Action gadget.  This tells the\ndoor  how  to  react  if a user tries to page while the sysop is in a chat.\nNOTE:  If this is set to "REFUSE TO PAGE..." and the user got "Override CF"\nstatus ( and this is enabled ) - it will bypass SysopInChat Action.\n\nThe  next  two gadget is used to specify where a possible logfile should be\nplaced.\n\nThe  following  gadget  is named "Use BlackList" which tells the door if it\nshould enable the blacklist feature.\n\nThe  same  goes  for the "Allow CF Override", this is just for the Override\nfeature.\n\n"Make LogFile" is shouldn''t be too hard to figure out.\n\n"Allow Empty Reason" - if this is enabled, and the user enters nothing as a\nchat-reason,  the  door  will  continue the paging process - if this is not\nset, and the user enters nothing, the door will exit.\n\nThe next gadget is a cycle gadget, and is used to set the method of paging:\nDisplayBeep(),  Execute  Command  or  Be  Quiet.   If  Execute  Command  is\nselected, the command should be written in the below string-gadget.\n\n"About"  shows  some vital information, you don''t wanna miss this one.  :),\nand "Save" just saves the configuration.  To cancel the changes, just close\nthe window.\n    \n\n*[ BlackList ]***************************************************************\n\nIf  you  got  some users you won''t wanna chat with, just his/hers name into\nthe  blacklist.   The Blacklist is a file named "PowerPager.BLU" (BLU=Black\nListed  Users)  -  and  the  format  is:  \n<name><CR>\n..  No more no less.  Remember to enable the BlackList in the configuration\nmenu, if you need this feature.\n\n*[ ChatFlag Override List ]**************************************************\n\nIs   just  as  easy  as  with  the  blacklist.   The  file  is  just  named\n"PowerPager.CFO"  (Chat  Flag  Override)  and  the  format  is  the same as\ndescriped above.\n\n*[ Last words ]**************************************************************\n\n I want to send special greeting to Flozzy, for ideas and betatestning,\n and to Enzo for betatesting. Normal greetings to my friends in the scene.\n\n If you got any ideas/bug reports for PowerPager please don''t hesitate to\n contact me at Sky Tower, BattleField or Warez Unlimited.\n\n And here at last a small tip to the avanced PowerPager user from Flozzy:\n If you want an easy''n''quick way to access the configuration window\n of PowerPager; Setup the aCP to have PowerPager as a button, so whenever\n you want to change the configuration, you just press the button in ACP.\n\n If you are using Sigma Express, add the following line to S:ACP.STARTUP:\n BUTTON01: PPager Config |Run >NIL: Doors:PowerPager/PowerPager >NIL:\n\n If you are using AmiExpress, add the following tooltypes to your ACP.info\n BUTTON_NAME.1=PPager Config\n BUTTON_COMMAND.1=Doors:PowerPager/PowerPager\n\n*[ Version Changes ]*********************************************************\n\nv0.12 951231 First Public Beta Release.\n\n*[ The End ]*****************************************************************\n','\n',char(10)),NULL,'auto-added',20132,2,0,NULL,NULL,'lll_pp','scan',1780048575);
