INSERT INTO door_catalog VALUES('lns_tt2a','LNS-TT2A.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LNS-TT2A.LHA','TapeWorm-FS','XIM','___/\______  _____  ___  __  __  ___  /\___',NULL,'doC','LNS','\  __  / |¬\/  __/ /  | / ¬\/ ¬\/  ¬\/ ___/ \/ ¬\/     \  _)_/   |/_ | \ | \ |  \___¬\ \__/\__|__/____/\_____/___/___/_|__/____/',replace('___/\______  _____  ___  __  __  ___  /\___\n\  __  / |¬\/  __/ /  | / ¬\/ ¬\/  ¬\/ ___/\n \/ ¬\/     \  _)_/   |/_ | \ | \ |  \___¬\\n  \__/\__|__/____/\_____/___/___/_|__/____/\n===========================================\nTAPETrans v.02a  File Transfer Utility Door\n        all versions of Ami Express\n     Transfer files directly from your\n   Tape Drive for your users to download\n **** DOCUMENTATION CORRECTION RELEASE ****\n          by doC wHoO / LoONs 1994\n===========================================\n','\n',char(10)),'uzi.txt',replace('                                            .---------------------------.\n    _______.-----------------._______/|     |     4NODEZ  RiNGDOWN      |\n    \_     |     .------     |________|.....| 73 GiG OF AMiGA CoNSoLE PC|\n   .:|     |     |     ______|        |:::::|  uZiSUiCiDE.sERVEBBS.ORG  |\n  .::|     |     |     |     |        |-----+-----.      TELNET         |\n .:::|           |     |     |       :|     |     |                     |\n.::::\___________|___________|________|     `-----+---------------------''\n:::::::::::::::::|                                | 24HR 7DAY STATiC iP! \n_________________|___________/|__________________/|______________________\n\_     ______    |     _______|          |_____________      _/    _____/\n_|_____    |     |     |      |    |_____|        |   |      |     ___|_ \n|     |    |     |     |      |    |     |        |   |      |     |    |\n|     |    |     |     |     :|          |       :|   |      |     |    |\n|__________|_____|_____|______|__________|________|__________|__________|\n:::::::::::::::::|            |                                         |\n`::::::::::::::::|            |ALWAYS THE LATEST VERSION oF AMi-EXPRESS |\n `:::::::::::::::|            | TONS OF ONLiNE MESSAGES AND MULTi-CHATS |\n  `::::::::::::::`------------+  NUP IS REQUIRED SO ASK WHOEVER POSTED  |\n   `::::::::::::::::::::::::::|    THIS ADVERT FOR THE NUMBER AND NUP   |\n    `:::::::::::::::::::::::::`-----------------------------------------''\n','\n',char(10)),NULL,NULL,109259,7,0,NULL,NULL,NULL,'scan',1780048575);
INSERT INTO door_catalog VALUES('lns_work','LNS-WORK.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LNS-WORK.LHA','Protect','XIM','D0JU6',NULL,NULL,'LNS','WORK V1.0 /X DOOR FOR ALL VERSIONS EXPRESS UNPROTECTS ALL FILES IN YOUR WORK DIR SO THAT YOUR DIZ EXTRACTOR CAN DELETE THEM.',replace('=====> LENSMEN <==========================\nWORK V1.0 /X DOOR FOR ALL VERSIONS EXPRESS \nUNPROTECTS ALL FILES IN YOUR WORK DIR SO\nTHAT YOUR DIZ EXTRACTOR CAN DELETE THEM.\nNO MORE SCREW UPS WITH PROTECTED DIZ''S!!!\n   MASTURBATiON STATiON (305)222-2251\n==========================> LENSMEN <=====\n     ','\n',char(10)),'WORK.DOC',replace('\nBlack Beard Of lENSMEN AMIGA DIVISION\nTHE MASTURBATION STATION (305)222-2251 NEW RINGDOWN LINE!\n\n\n\nWork V1.0 By Black Beard Of The Masturbation Station.\n\nThis is a very simple and easy door, but its a life safer.  Why you ask,\nWell Ill tell you lamer boy.  Well do you ever get an upload that\nhas a protected file_id.diz in it and it sits in your work directory\nbecause your file_id.diz stripper can''t delete it, because its protected.\nFor the remainder of the day all your uploads get the same file_id.diz.\nAll Because that protected diz remains in your work directory untill you \nmanully delete it.  Well not anymore this door will unproteect everything\nyour checker unpacks.  It also does it fast because theres not much to the\ncommand. \n\nIts very easy door, which my grandmother could write but unfortunately\nnobody has implemented it in there file_id.diz extractor.\n\n\nINSTALLATION\n------------\nCopy the files to their proper directory.\n\nTo Get this door to work properly make sure it runs before it does the\nfinal file test.  You should be running some type of multi door launcher\nfor your diz extractor,checker,nuker etc. So just ad this one right in.\nThis works with all version of X\ and all computers because its a small \nbatch file.\n\nEdit The Work txt file in doors:work to your bbs specifications..\n\n\nEXAMPLE FOR IDIOTS.\n\nprotect bbs:node0/work +rwd all quiet\n\n\nprotect path of your work dir +rwd all quit\n\nQuick hellos to my pals:\n\nAxe, Killraven, Gt One, & Doc Who.\n\nGreets to all Myth Members!\n\nBlack Beard, lENSMEN  ''95\n\n\n','\n',char(10)),NULL,'auto-added',9475,7,0,NULL,NULL,'lns_work','scan',1780048575);
INSERT INTO door_catalog VALUES('lobster1','LOBSTER1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LOBSTER1.LHA','AmigaGuide','XIM','AmigaGuide','1.01',NULL,NULL,'-------------------------------------------- world''s fastest checker - checks 5000Files in less than 0.2 secs!',replace('     RoCK LoBSTER v1.01ß - DUPE CHECKER\n--------------------------------------------\nworld''s fastest checker - checks 5000Files \nin less than 0.2 secs! \ncomplete documentation is now in AmigaGuide!\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                                                .------''\n             `------------------------------------------------''\n','\n',char(10)),NULL,'auto-added',49708,5,0,NULL,NULL,'lobster1','scan',1780048575);
INSERT INTO door_catalog VALUES('local141','LOCAL141.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LOCAL141.LHA',NULL,'XIM','Localv1.41','1.41',NULL,NULL,NULL,replace('Local Uploader v1.41\n','\n',char(10)),'uzi.txt',replace('                                            .---------------------------.\n    _______.-----------------._______/|     |     4NODEZ  RiNGDOWN      |\n    \_     |     .------     |________|.....| 73 GiG OF AMiGA CoNSoLE PC|\n   .:|     |     |     ______|        |:::::|  uZiSUiCiDE.sERVEBBS.ORG  |\n  .::|     |     |     |     |        |-----+-----.      TELNET         |\n .:::|           |     |     |       :|     |     |                     |\n.::::\___________|___________|________|     `-----+---------------------''\n:::::::::::::::::|                                | 24HR 7DAY STATiC iP! \n_________________|___________/|__________________/|______________________\n\_     ______    |     _______|          |_____________      _/    _____/\n_|_____    |     |     |      |    |_____|        |   |      |     ___|_ \n|     |    |     |     |      |    |     |        |   |      |     |    |\n|     |    |     |     |     :|          |       :|   |      |     |    |\n|__________|_____|_____|______|__________|________|__________|__________|\n:::::::::::::::::|            |                                         |\n`::::::::::::::::|            |ALWAYS THE LATEST VERSION oF AMi-EXPRESS |\n `:::::::::::::::|            | TONS OF ONLiNE MESSAGES AND MULTi-CHATS |\n  `::::::::::::::`------------+  NUP IS REQUIRED SO ASK WHOEVER POSTED  |\n   `::::::::::::::::::::::::::|    THIS ADVERT FOR THE NUMBER AND NUP   |\n    `:::::::::::::::::::::::::`-----------------------------------------''\n','\n',char(10)),NULL,'auto-added',65090,5,0,NULL,NULL,'local141','scan',1780048575);
INSERT INTO door_catalog VALUES('logbook7','LOGBOOK7.LZH','~/Code/amiexpress_doors/Archives/AmiExpress/LOGBOOK7.LZH','Cycle-Texts','XIM','Cycle-Texts','1.6',NULL,NULL,NULL,replace('LogBook V1.6 \n','\n',char(10)),'Cycle-Texts.doc',replace('****************************************************************************\n*                                                                          *\n*                 Cycle-Texts V1.0 By Bryce! and Ted 1991                  *\n*                                                                          *\n*                Logon & Logoff Cycler util for AmiExpress                 *\n*                                                                          *\n****************************************************************************\n\n                User''s Manual for the Cycle-Texts utility.\n\n\n1. Introduction\n\n   This is just a short document for the Cycle-Texts util, which\n   is a util for changing the logon and logoff textfile, after\n   every logoff. It''s really quite simple to use, so let''s get\n   down to business.\n\n2. Getting started\n\n   First, create a directory in your BBS: assignment called ''Screens''.\n   (And for all you sysops who have been using Luser, I am glad to \n   say that Cycle-Texts is fully compatible with Luser, what concerns\n   the Screen directory and the filenames of the textfiles with in this\n   directory.) Then copy all you logon and logoff textfiles to the \n   Screens directory, and name them; \n\n   Logon1      - First logon without Ansi.\n   Logon1.gr   - First logon with Ansi.\n   Logon2      - Second logon without Ansi.\n   Logon2.gr   - Second logon with Ansi.\n   .           - Etc...\n   .\n\n   Logoff1     - First logoff without Ansi.\n   Logoff1.gr  - First logoff with Ansi.\n   Logoff2     - Second logoff without Ansi.\n   Logoff2.gr  - Second logoff with Ansi.\n   .           - Etc...\n   .\n\n   When you''ve copied the desired number of logons and logoffs,\n   you are ready to use the program. \n\n   Let''s say you have 10 logons and 5 logoffs in the Screens\n   directory, and you would like to ramdomly choose one to\n   go to the Node0 directory, as Logon.txt and Logoff.txt.\n   The commandline would then look like this:\n\n   Cycle-Texts 10 BBS:Node0/Logon.txt 5 BBS:Node0/Logoff.txt\n\n   Pretty simple, eh? And please note that the program will\n   automaticly copy the respective Logon.txt.gr file as well,\n   so there is no need to manualy create the .gr files by \n   copying them. \n\n\n3. Credits and other Information\n\n   Programmed in Manx Aztec ''C'' for reliable and system-friendly code.\n\n   Programming:             Bryce! - Horizon\n   Additional Programming:  Ted    - Defjam\n  \n   Please look at the main LogBook Document for info on\n   memory set-up''s and kickstart versions tested with \n   these utils.\n\n                                 ...Bryce! ''91\n','\n',char(10)),NULL,'auto-added',32366,4,0,NULL,NULL,'logbook7','scan',1780048575);
INSERT INTO door_catalog VALUES('logic100','LOGIC100.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LOGIC100.LHA','LogicBBS','XIM','+------------------------------------------+',NULL,NULL,NULL,'|(PS) LogicBBS v1.0  *ParCon Software* (PS)| +-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=| | COMPLETE Bulletin System. 100% /X CLONE. |',replace('+------------------------------------------+\n|(PS) LogicBBS v1.0  *ParCon Software* (PS)|\n+-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=|\n| COMPLETE Bulletin System. 100% /X CLONE. |\n:   XIM&AIM Compatible.  100% Assembly.    :\n: LIGHTSPEED performance, you are TEMPTET, :\n:   to DAYDREAM about it.  Doc included.   :\n+-""------------------------------------""-+\n<------------------------------------------>\n','\n',char(10)),'NS.GUiDE',replace('@database noC-WHO Documentation\n******************************************************************************\n@NODE MAIN "NS Version 1.OO Complete Guide - by nocTurne deSign/Origin in ''94"\n\n\n            @{b}NiGHT-SCANNER V1.OO - /X New-Files/Files-Reverse Door@{ub}\n             (C)1994 nocTurne deSign/ORiGiN Ami-Express Division\n              -------------------------------------------------\n              @{" Overview       " LINK OVER   } General Description of Features\n              @{" Installation   " LINK INSTALL} Installing/Configuring NS\n              @{" Usage          " LINK USAGE  } Door Usage/Theory\n              @{" Changes        " LINK CHANGES} History of Implementation\n              @{" Credits/Greets " LINK CREDS  } Where to reach me/Messages\n              -------------------------------------------------\n\n@ENDNODE\n*******************************************************************************\n@NODE OVER "NiGHT-SCANNER v1.OO - Overview"\n\n NiGHT-SCANNER  is the nocTurne deSign entry into the NewFiles door market.\n It  has  been  merged  with  Files-Reverse  so that it functions as both a\n new-files directory scanner as well as a reverse scanner (showing files in\n their  reverse  chronological  order,  newest   to   oldest).    NS offers\n flexibility  for  both  the sysop and the user.  An easily editable config\n file  allows the operator to define defaults, access levels, graphics, and\n more.    A user config file allows users to customize NS to act and output\n to  their  satisfaction.  Packed with features and conveniences, NS should\n prove  to  be  file-scanning  door to contend with.  Read further for more\n details.\n\n@ENDNODE\n*******************************************************************************\n@NODE INSTALL "NiGHT-SCANNER v1.O - Installation"\n\n This program is an XIM and should be installed as such.  Knowledge of door\n installation  convention  is  assumed.   Icons have been provided for 3.xx\n owners.    Note that once installed, NS and its support files should be in\n the  drawer  "DOORS:noC-NS/"  The  text  file  "NS.CONFiG"  allows  you to\n configure the door''s various sysop options, which are detailed here:\n\n  ------------------------------------------------------------------------\n  @{" DIVIDERS    " LINK TT1 } Divider Lines?  Access Lvl for Hold Dir @{" HOLD.ACS        " LINK TT5 }\n  @{" COLORS      " LINK TT2 } Color Display?\n  @{" SHOWNEWDATE " LINK TT3 } Date Lines?       Key-Command Full Name @{" KC_NAME.[NUM]   " LINK TT6 }\n  @{" FILENUMBERS " LINK TT4 } File Numbering?            KC Door Name @{" KC_CMD.[NUM]    " LINK TT7 }\n  @{" DIVIDER.TXT " LINK TT11} Divider Graphic      KC Key Designation @{" KC_KEY.[NUM]    " LINK TT8 }\n  @{" NEWDATE.TXT " LINK TT12} Date Graphic        Access Level for KC @{" KC_ACCESS.[NUM] " LINK TT9 }\n  @{" ENDLINE.TXT " LINK TT13} Final Graphic       Accept args for KC? @{" KC_ARGS.[NUM]   " LINK TT10 }\n  ------------------------------------------------------------------------\n@ENDNODE\n******************************************************************************\n@NODE TT1 "NiGHT-SCANNER v1.O Config Parameter - DIVIDERS"\n\n @{b}Template: @{ub}DIVIDERS=[YES/NO]\n  @{b}Example: @{ub}DIVIDERS=YES\n\n If  you  want  to  enable  by default the dividing lines between each file\n description, simply set this option to YES.  The text in the "DIVIDER.TXT"\n config parameter will be utilized as the divider graphic.\n\n@ENDNODE\n******************************************************************************\n@NODE TT2 "NiGHT-SCANNER v1.O Config Parameter - COLORS"\n\n @{b}Template: @{ub}COLORS=[YES/NO]\n  @{b}Example: @{ub}COLORS=YES\n\n To  make colors in the listing default, set this parameter to YES.  Colors\n will be used in the file number, (if used), and file information.\n\n@ENDNODE\n******************************************************************************\n@NODE TT3 "NiGHT-SCANNER v1.O Config Parameter - SHOWNEWDATE"\n\n @{b}Template: @{ub}SHOWNEWDATE=[YES/NO]\n  @{b}Example: @{ub}SHOWNEWDATE=YES\n\n To  enable the date-divider graphic, ie what is shown when there is a date\n change  in  the  listing,  set this option to YES.  The text in the config\n parameter "NEWDATE.txt" will be utilized as the date-divider graphic.\n\n@ENDNODE\n******************************************************************************\n@NODE TT4 "NiGHT-SCANNER v1.O Config Parameter - FILENUMBERS"\n\n @{b}Template: @{ub}FILENUMBERS=[YES/NO]\n  @{b}Example: @{ub}FILENUMBERS=YES\n\n If  you  want,  by  default,  file-numbers  to  be  shown and want numeric\n flagging  available,  set  this  to  YES.  With this option, filenames are\n assigned 1 to 2 digit numbers, which makes for easier file flagging.\n\n@ENDNODE\n******************************************************************************\n@NODE TT5 "NiGHT-SCANNER v1.O Config Parameter - HOLD.ACS"\n\n @{b}Template: @{ub}HOLD.ACS=[NUMBER]\n  @{b}Example: @{ub}HOLD.ACS=200\n\n The  number  here will set the access level required for a user to be able\n to scan the hold directory.\n\n@ENDNODE\n******************************************************************************\n@NODE TT6 "NiGHT-SCANNER v1.O Config Parameter - KC_NAME.[NUM]"\n\n @{b}Template: @{ub}KC_NAME.[NUM]=[TEXT]\n  @{b}Example: @{ub}KC_NAME.1=BOSS-NUKE v1.5\n\n To  define  a new Key-Command you must first define a descriptive name for\n it.    If  you  plan to make a KC that calls a nuker, you should title the\n nuker  here.    All  KC_NAME texts (of KC''s available to the user) will be\n shown  when  the  user  hits  ''?''  at  the  pause  prompt.   [NUM] must be\n incremented for each KC definition you add.\n\n See @{" Key-Commands " link KC} for more info.\n\n@ENDNODE\n******************************************************************************\n@NODE TT7 "NiGHT-SCANNER v1.O Config Parameter - KC_CMD.[NUM]"\n\n @{b}Template: @{ub}KC_CMD.[NUM]=[TEXT]\n  @{b}Example: @{ub}KC_CMD.1=NUKE\n\n The  argument  specified here is the name of the DOOR that will be spawned\n with  Key-Command  number [NUM].  It will be called just as though it were\n written at the main prompt, with arguments if KC_ARGS.[NUM] is set to YES.\n \n See @{" Key-Commands " link KC} for more info.\n\n@ENDNODE\n******************************************************************************\n@NODE TT8 "NiGHT-SCANNER v1.O Config Parameter - KC_KEY.[NUM]"\n\n @{b}Template: @{ub}KC_KEY.[NUM]=[CHAR]\n  @{b}Example: @{ub}KC_KEY.1=X\n\n The  character  here  will  define  the key that, when pressed at the main\n prompt,  will  spawn  the  door  defined  in  the respective KC_CMD.[NUM].\n Please  note  this  character should not be ''Y'', ''N'', or ''F'', as those are\n reserved for other prompt functions.\n\n See @{" Key-Commands " link KC} for more info.\n \n@ENDNODE\n******************************************************************************\n@NODE TT9 "NiGHT-SCANNER v1.O Config Parameter - KC_ACCESS.[NUM]"\n\n @{b}Template: @{ub}KC_ACCESS.[NUM]=[NUMBER]\n  @{b}Example: @{ub}KC_ACCESS.1=240\n\n You  may set the access level required to see/use Key-Command number [NUM]\n with this config parameter. \n\n See @{" Key-Commands " link KC} for more info.\n \n@ENDNODE\n*****************************************************************************\n@NODE TT10 "NiGHT-SCANNER v1.O Config Parameter - KC_ARGS.[NUM]"\n\n @{b}Template: @{ub}KC_ARGS.[NUM]=[YES/NO]\n  @{b}Example: @{ub}KC_ARGS.1=YES\n\n If  the Key-Command number [NUM]''s door supports arguments and this option\n is  set,  the  user  will be given a large text field so that he may enter\n filenames/numbers  to  use  with  the  spawned  door.   If, for example, a\n Key-Command  activates  a nuke door and the KC_ARGS for that particular KC\n is  turned  on,  the  user may enter "1 2 3" and files 1, 2, and 3 will be\n affected by the spawned nuke operation.\n\n See @{" Key-Commands " link KC} for more info.\n \n@ENDNODE\n*****************************************************************************\n@NODE TT11 "NiGHT-SCANNER v1.O Config Parameter - DIVIDER.TXT"\n\n @{b}Template: @{ub}DIVIDER.TXT=[TEXT]\n  @{b}Example: @{ub}DIVIDER.TXT=*-----------------------------------------*\n\n The  one  line  text written here will divide file entries if the user has\n that  feature  turned  on.    The text should be less than around 78 chars\n wide.  Ansi codes may be used.\n\n@ENDNODE\n*****************************************************************************\n@NODE TT12 "NiGHT-SCANNER v1.O Config Parameter - NEWDATE.TXT"\n\n @{b}Template: @{ub}NEWDATE.TXT=[TEXT]\n  @{b}Example: @{ub}NEWDATE.TXT=*--------------< @THEDATE >---------------*\n  \n The one line text written here will be written when there is a date change\n between  entries in the listing (if the user has the feature active).  Use\n the  text  @THEDATE where you wish the date to appear.  The text should be\n less than around 78 chars wide.  Ansi codes may be used.\n\n@ENDNODE\n*****************************************************************************\n@NODE TT13 "NiGHT-SCANNER v1.O Config Parameter - ENDLINE.TXT"\n\n @{b}Template: @{ub}ENDLINE.TXT=[TEXT]\n  @{b}Example: @{ub}ENDLINE.TXT=*=========================================*\n  \n The one line text written here will be the last text outputted.\n\n@ENDNODE\n*****************************************************************************\n@NODE USAGE "NiGHT-SCANNER v1.O - Usage"\n\n Check  out the "NS-USER.doc" file for information on actual program usage.\n The user may download this file by typing "N Z" at the main prompt.\n\n@ENDNODE\n******************************************************************************\n@NODE KC "NiGHT-SCANNER v1.O - Key-Commands"\n\n Key-Commands  are  functions that YOU define, available to the user at the\n pause  prompt.    Up  to  8 KC''s may be defined.  You may set certain KC''s\n (such  as  one  that  calls  up  a nuker) to only be available to those of\n certain  access  levels.    You  may  set KC''s that accept arguments, (for\n example a VIEWING key command, so that if the user types "V7", file number\n 7 will be viewed.) Please consult the config file which contains 4 example\n KC entries. \n\n@ENDNODE\n******************************************************************************\n@NODE CREDS "NiGHT-SCANNER v1.O - Credits/Greetings"\n\n NiGHT-SCANNER is created by nocTurne deSign/Origin in 1994.  Any questions\n regarding  the  use  of  this program should be addressed to "nocTurne" on\n Mortuary,  Domino  Effect,  or  any other board you see me on.  Or you may\n direct mail to "[email removed]". \n\n -------------------------------------------------------------------------\n * This  utility is BACKDOOR and VIRUS FREE.  All nocTurne deSign products\n   are created with a dedication to quality and stability.\n -------------------------------------------------------------------------\n\n Thanks for the help with this release: \n\n * BLooDWoLF/MORTUARY\n * PiCARD/USS ENTERPRISE\n * RAD!/LSD\n * ARCH-MAGi/TOWER of SORCERY\n * M.BiSON/DOMiNO EFFECT\n * SASHA/DATALUS\n\n@ENDNODE\n******************************************************************************\n@NODE CHANGES "NiGHT-SCANNER v1.O - Changes/Enhancements"\n\n - uh.. I added a line of code...\n\n@ENDNODE\n','\n',char(10)),NULL,NULL,334077,15,0,NULL,NULL,NULL,'scan',1780048575);
INSERT INTO door_catalog VALUES('logoff','LOGOFF.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LOGOFF.LHA',NULL,'XIM','Logoff',NULL,'tANGO/lED^iHS^pTL',NULL,'| | \ | |  _  | |_| | |\/| |  _  | \·::::. ¦ |_|_|\__|_| |_|_____|_|  |_|_| |_|_|.._.:: : p R E S E N T S     RcL·::::· ·',replace('| |  \| | |_| | | | |  \/  |  _  |  ::.|   !\n| | \ | |  _  | |_| | |\/| |  _  | \·::::. ¦\n|_|_|\__|_| |_|_____|_|  |_|_| |_|_|.._.:: :\n             p R E S E N T S     RcL·::::· ·\n    uL-lOGOFF v1.1 bY tANGO/lED^iHS^pTL    .','\n',char(10)),'Ul-Logoff.guide',replace('@database 00325fa0-0\n@master BBS:misc/ihs/work/Ul-Logoff.guide\n@$VER: Ul-Logoff.x 1.1 (13.9.95)\n@author "tANGO/iHS^lED^pTL"\n@(c) "1995 by tANGO/iHS^lED^pTL"\n@remark Created with Heddley v1.1 (c) Edd Dumbill 1994\n\n@node "Main" "No title"\n\n\n                  _ __         ____\n   _____      ______  |__ ____|_   |___  ___  _______      ______ _____\n _:_____: ___|     /  |  \\     /   |   \\/   \\_\\____  \\____|     /  ___/___\n \\       |   \\    /   .   \\_  /    |  _  /   \\_  _/   \\_  \\    /_____    /\n  \\______|____\\__/____|    /_______|___\\/_____/__\\     /___\\__/_________/\n <--------------------|___/--------------------uMn\\___/------------------>\n\n                                  pRESENTS\n\n                               uL-lOGOFF v1.1\n\n                            bY tANGO/iHS^lED^pTL\n\n\n                               @{" iNTRODUCTION " link "introduction" 0}\n                               @{" rEQUIREMENTS " link "requirement" 0}\n                               @{" iNSTALLATION " link "installation" 0}\n                               @{"   hISTORY    " link "history" 0}\n                               @{"  gREETINGS   " link "greetings" 0}\n                               @{" hOW tO rEACH " link "howtoreach" 0}\n@endnode\n\n@node "introduction" "iNTRODUCTION"\n\n                                 iNTRODUCTION\n                                 ~~~~~~~~~~~~\nThis is not the first door that lets you log off after an upload... Though,\nit''s the first one that completely melts into /X. You don''t need to run it\nwith an MCI command, it replaces the U command completely... Choosing\ngoodbye after upload will really hang you up after you''ve uploaded, and\nbefore all the filechecking. If you just choose start, or use RZ you will be\nasked if you want to log off after the upload is complete. What more is\nthere to it? This is the first door I''ve seen so far that solves this\nproblem in a nice and easy way. There''s simply now reason not to run it!\n\nThis door is, like all my other doors and utils, written in C. No lame arexx\nhere... It''s fast and good looking... Simply pure quality!\n@endnode\n\n@node "requirement" "rEQUIREMENTS"\n\n                                rEQUIREMENTS\n                                ~~~~~~~~~~~~\nThis door requires you to run /X v3.x+ on an Amiga! :)\n@endnode\n\n@node "installation" "iNSTALLATION"\n\n                                iNSTALLATION\n                                ~~~~~~~~~~~~\nEverything is set up for you... Simply copy the files to the correct\ndirectories.\n\nPlease note that if you already run doors as EXAMINE, fex file_id or\ndreamchart doors, you''ll have to rename some icons. I''ve installed this door\nas EXAMINE and have moved all the other EXAMINE doors one step forward, ie\n\n   EXAMINE  -> EXAMINE1\n   EXAMINE1 -> EXAMINE2\n\nand so on... This way you will get the logoff question before any file_id''s\nare processed. It''s not needed though. You may as well run it after all the\nother EXAMINE doors. If you want to do it this way, reanme the EXAMINE icon i\nsupplied.\n\nIf you want to you can add the following to you logoff batch as well.\n\n   delete ENV:UL-Logoff.<node> QUIET\n\nIf you skip this, the door won''t ask the user if he wants to hang up or not if\nhe just called and uploaded then hanged up, called again and used RZ. If he\nused U he would get the question again. This happens because there''s no other\nway to detect if the user loged off or not.\n@endnode\n\n@node "history" "hISTORY"\n\n                                  hISTORY\n                                  ~~~~~~~\nv1.0  -  First beta version. Not realeased other than to some of my friends.\n\nv1.1  -  Added a function to check if the user had uploads to resume. If he\n         had the normal upload routine will be called. This is needed\n         because there''s no way to resume an upload if /X doesn''t do it it''s\n         way.\n         Added a function to show and check the upload space. While i was\n         beta-testing v1.0, some of my users asked if there was room on the\n         HD, so I fixed the problem.\n@endnode\n\n@node "greetings" "gREETINGS"\n\n                                 gREETINGS\n                                 ~~~~~~~~~\nI know I''m bound to forget someone if I write a long greetings list.\nTherefor I won''t do it... Feel greeted if you know me. Here are some special\nones that I want to share with you though!\n\n       Cathleen, La Fayette, Exeron & Maniac, DJ Gizmo, Christ, Abbe\n       TBB, Scroud & Melone, Rille, Rioter, Overlord, Hiway & Route66\n                              Visitor & Recall\n\nPlease forgive me if I forgot someone! :)\n@endnode\n\n@node "howtoreach" "hOW tO rEACH"\n\n                                hOW tO rEACH\n                                ~~~~~~~~~~~~\nIf you want to get in contact with me, write me a message on my board,\nInferno, on any board in the 042, 0431, 0435 or 0418 areas in sweden or on\none of the following boards,\n\n              Bitchboard, Ace of spades, Skyline, Last resort\n\nor write an e-mail to [email removed]\n@endnode\n\n','\n',char(10)),NULL,'auto-added',19380,5,0,NULL,NULL,'otl_lo10','scan',1780048575);
INSERT INTO door_catalog VALUES('logon','LOGON.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LOGON.LHA',NULL,'XIM','logon',NULL,'/X\ardanpet',NULL,'*How would you like to log on to your BBS  * *from the comfort of your chair            * *Nullmodem.device does this                *',replace('********************************************\n*How would you like to log on to your BBS  *\n*from the comfort of your chair            *\n*Nullmodem.device does this                *\n*configs included for /x,Term & Ncomm      *\n*it allows downloading as well as uploading*\n********************************************\n* Sorted by /X\ardanpet                    *\n********************************************\n!\n!\n!\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 12-22-17  TIME: 18:26:48  ON NODE: 1\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',12735,2,0,NULL,NULL,'tms_lo15','scan',1780048575);
INSERT INTO door_catalog VALUES('logshrin','LOGSHRIN.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LOGSHRIN.LHA','log-shrink','XIM','log-shrink',NULL,NULL,NULL,'____\        /___\   ____  /____/ ___/______ _     \l      _  \_______ ____\/       __l_________  __l__       l ___',replace('    __________   ___________     _____\n____\        /___\   ____  /____/ ___/______\n               _     \l      _  \_______\n____\/       __l_________  __l__       l ___\ng®m /________)   e^D \_____)   (_________)\n          «« m e g a s t y l e  »»\n               ...presents...\n \n              Log-Shrink v1.o!\n \nThe best way to shorten down your HUGE logs!\n','\n',char(10)),'Log-Shrink.GUIDE',replace('@database "mEGAZTYLE.guide"\n@node MAIN\n@title "                                              »«  m e g a s t y l e  »«  r u l e s  »«"\n@{b}\n                              @{u}m e g a s t y l e@{uu}\n\n                 ________   _________   _________     ______.\n           ______\      /___\  ___  /___\  ___  /_____\____ l____\n     ______\              _     l/    _    \l     _     __/     /_______\n.___(       \____\/     __l__  _______l_______  __l__   \l_____/        )___.\n|                /______)   (_____/        \____)   (____\                  |\n|                                                                           |\n| g®m      _____      ___.           .______   ___.       _________     e^D |\n|___  ____/ ___/______\  l___________|     /___\ _l_______\  ___  /____  ___|\n   (__\   \______   _    __/     _   l       _   \      _     l/      /__)\n       \__      l __l__  l     __l_______  __l_        _l_  _________/\n         (________)   (________)     \_____)  (________) (_____/ @{ub}\n\n\n\n@{fg shine}                  p r e s e n t s   a   n e w   d o o r :@{fg text}\n\n\n                @{b}    @{bg shine}@{u}  L o g - S h r i n k   1 . o  @{bg back}@{ub}@{uu}\n\n\n\n\n              @{"           d o c u m e n t a t i o n           " link index}\n\n\n\n\n@endnode\n\n@node index\n@title "                                             »» i n d e x ««"\n\n\n    @{u}                                                          @{uu}\n\n\n@{b}                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n         ____        __________          ____.   ___________   ½½½½½  ½½½½½\n________(___/________\ __     /__________\___l___\  ____   /__    `½½½½''\n                   _   l/       _      _____/  _      l/      ½½½½½½  ½½½½½½\n_____            __l___/      __l__    l     __l__  __________½½½½½½  ½½½½½½\n    (____________)    /_______)   (__________)   (_____/      ½½½½½½  ½½½½½½\n                                                              ½½½½½½  ½½½½½½\n                                                              ½½½½½½  ½½½½½½\n   @{fg shine} @{"            introduction             "  link introduction      }    @{fg text}                ½½½½½½  ½½½½½½\n@{fg shine}    @{"            installation             "  link installation      }          @{fg text}          ½½½½½½  ½½½½½½\n@{fg shine}    @{"              how 2 use              "  link how 2 use         }\n    @{"              copyright              "  link copyright         }\n    @{"          changes ÷ history          " link changes ÷ history  } @{ub} @{fg text}\n\n\n    @{u}                                                          @{uu}\n\n\n@endnode\n\n\n\n\n\n\n\n\n@node introduction\n                                                                 .\n\n                                                                 :\n                                                                 :\n             __________________.______.      ________            :\n          ._(___)_.   ___     _|      l_____\\_     /____________:_ _\n          |       |----/      \        /     \   __/\      __    :\n          l_______|   /_______/        |-----/_______\____       :\n                              l________|(rLf)            /-------:-\n                                                                 :\n                                                                 :\n                                                                 :\n                                                                 .\n\n\nEver discovered that some of the applications you''re using just seems to append\nand append and append to the log-files without erasing the old data?\n\nWell, I just noticed that my AmiExpress Callerslog was over 2MB long once, and\ndecided to make a utility that could keep the length of that particular file\ndown to a resonable level without loosing any important data.\n\nI then started to code on this little program that can be used on any log-file\nin text-format generated by any application for the Amiga. My main goal was to\nmake a fast and system-friendly door, which I could trust wouldn''t screw up my\nsystem totally.\n\n\nThis door does that, it reduce the length of any (text-)file to a desired\namount of bytes, from within the file till the end of the file.\n\nThis way you won''t lose the last entries in the file, and discard the old \nentries on the top of the file.\n\n\n\n                                 Enjoy it! :)\n\n\n\n           - - - --- ------[ lizard of megastyle! ]------ --- - -  -\n\n\n     This program should be 100% systemfriendly coded. If any error should\n    occure, then the program should managed to shutdown without causing any\n                             damage to the system.\n\n\n\n\n@endnode\n\n\n\n\n\n\n@node installation\n\n .\n                                                                              .\n :\n :                                                                            :\n : __        _____ .___.   ______ __.              _________. ____________    :\n_:(__)_______\_ _/_|_  l___\__  // _l______.  _____\__  //  l____)_  _   /____:_\n :    | __    /_  _ /   /     _ // \     /_l__\__     _ //   /    |_    / ___ :\n_:____|--/   /-/  //    |--/____/----/__/ \     /--/____/    |____|/---/\--/  :\n :      /___/ /___/_____|(rLf)          \---/__/       l_____|            /___:_\n :                                                                            :\n :                        i n s t a l l a t i o n                             :\n .                                                                            :\n                                                                              .\n\n @{fg shine}To install...@{fg text}\n\n\n\n All you have to do is to copy the main executable file in this archive to\n whatever directory you wish. I would advice SYS:C/.\n\n\n Also, if you wish to use it together with AmiExpress v3.x+, then you should\n write a command-line into your logoff-script for each node.\n\n\n That''s all... (Simple isn''t it? :)\n\n\n\n\n Functionality :\n\n\n   Log-shrink <Path+Filename> <Size>\n\n   <Path+Filename> is the source-file to be shrinked.\n   <Size> is a number in bytes to dedicate how big the logfile should be...\n\n\n\n If there is spaces in the filename, use "''s marks to indicate start and the end\n of the complete path+filename.\n\n\n\n Remember : This shrinker will cut from within the file -> end of file. \n            So... You won''t miss your last entries in the file. :)\n\n\n@endnode\n\n\n\n\n\n@node how 2 use\n@title "                                              )>» h o w  2  u s e «<("\n\n                                      ½½½½½½½½½½½½½½½½½½½½½½½.\n                                     ½½½½½½½½         ½½½½½½½½\n      ____.            _________         _______      ½½½½½½½½\n   ___\ __l____________\       /_________\     /______½½½½½½½½\n   \    \___        _             _      /\           ½½½½½½½½\n    \______/      __l__    "    __l__           ___   ½½½½½½½½\n          /_______)   (_________)   (___________) /_  ½½½½½½½½\n                                                   |  ½½½½½½½½\n                ½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½''\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½      ._____      _____    |   _|________\n                ½½½½½½½½______|    /_____/ ___/____|___\  ____  /___\n                ½½½½½½½½      |       _  \_______   _       l/     /\n                ½½½½½½½½__    l     __l__       l __l__  _________/\n                ½½½½½½½½ (__________)   (_________)|  (____/\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½  @{fg shine}   h o w       u s e  @{fg text}   |  ½½½½½½½½\n                ½½½½½½½½      @{fg shine}       2    @{fg text}         |  ½½½½½½½½\n                ½½½½½½½½                           |  ½½½½½½½½\n                ½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½\n\n\n\n   Just @{"Install" link installation} it and use it from a CLI window,\n             logoff-scripts or whatever pops up in your mind! :) \n\n\n@endnode\n\n\n\n\n\n\n@node copyright\n            .\n\n            :\n            :                                      ________ _______ _  _\n           _:__________  _________________ ________\__   _//\n            :      ___/__\__    __      /\\\ __      /___ /       .\n          _ :_ ____        /___        /     \______/   /_________:_ _\n            :     /-------/ __/-------/\______|        ___________|\n            :     _________(___)__________    ________/       /   l_\n           _:____\\_     /       |    ___/____\__   _        /     /\n            :     \   __/\_______|   /_         /---/       /      |\n         - -:-----/_______\(rLf) \----/________/   /_______/_______|\n            :\n            :                 c o p y r i g h t\n            :\n            .\n\n\n\n                                 ---[%]---\n\n                     Log-Shrink is a Megastyle! production\n\n               Code, idea & design by   Lizard of TBL MGS!\n\n\n              \n\n                         Creds for this GUIDE file\n\n               Slapped together by      Lizard\n               Asciis by                Relief   of T! MGS! 5D\n                                        Grimlock of GRT E^D MGS!\n\n                                 ---[%]---\n\n\n\n                      Megastyle! does now consist of\n \n               Leader . . . . . . . . . Lizard\n               Code . . . . . . . . . . Lizard\n                                        Magz\n                                        Instant\n                                        Splash\n               AscII. . . . . . . . . . Relief\n                                        U-MAN\n                                        Grimlock!\n                                        Magz\n               Boards . . . . . . . . . Noiseless - WHQ         LIZARD\n                                        Genetic Waste           MAGZ\n                                        Ecstatica               INSTANT\n                                        Traders Paradise        U-MAN\n\n                                 ---[%]---\n\n\n\n\n\n\n   ............\n   ::        ::\n   ::        ::\n    .        ::\n   /_____    ::          ___________                                          .\n  /_     \//\____________\      ___/_______    _________\n //      \/        _     /     /_         /____\___    //                     :\n/--------/     .---/____/   .---/________         _    //                     :\n     -T!/______\  /_       _|  .______.  \-----/_______/                      :\n                  __\   __/____|_     l_          _______.     _____________  :\n   ::        ::   \  \__    _ _        /_____ ____\     _l_____\     _     /__:_\n   ::        ::    \--(/      /            _//          \        ____/____/  /:\n   ::        ::       /____________________ /      /\-----/_____/   /_________:_\n   ::        ::                           /_______/(rLf)                      :\n   ::........::                                                               :\n                                                                              :\n                        m e g a s t y l e    ¹ 9 9 6                          :\n                                                                              .\n\n@endnode\n\n\n\n\n\n\n@node changes ÷ history\n\n\n    ___.        __      ____    ___.      _____  ½½½½½½½½½½      .____\n  ._\ _l_______(_/_____/ __/____\  l______\   /__½½½½   ½½½______|   /_.\n  |   \__   _       _  \____  _    __/  _        ½½½½½½½''        l     |\n  |____l/  _l_     _l_     l _l_   l   _l_  "  __½½½½   ½½½½½_______  _l\n g®m   /___) (_____) (_______) (_______) (_____) ½½½½   ½½½½½   \_____)\n                                                 ½½½½   ½½½½½ e^D\n\n                               ...HISTORY...\n\n\n\n29.03.96            First public release of this utility. Hope someone find it\n                    useful!! :)\n\n\n\n\n\nThanks to the following boards for helpful beta-testing of MegaStyle-products:\n«----------------------------------------------------------------------------»\n\n                             Genetic Waste (Magz)\n  Checkpoint (Kingpin)   -   Power Rage (Instant)   -   EveryWare (-Shade!)\n                           Bumble Bee Land (Baffle!)\n\n\n@endnode\n','\n',char(10)),NULL,'auto-added',17628,6,0,NULL,NULL,'logshrin','scan',1780048575);
INSERT INTO door_catalog VALUES('love_02b','LOVE-02B.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LOVE-02B.LHA',NULL,'XIM','LE-win5-96.exe',NULL,NULL,'LOVE','|\__/\__/\__/,--->ASGARD SUBDIVISON<-- 2F--. |                                          | |  UPLOAD_NOTE AN XIM DOOR FOR S!X v0.2ß!  |',replace('|_____   ____\n|\__/\__/\__/,--->ASGARD SUBDIVISON<-- 2F--.\n|                                          |\n|  UPLOAD_NOTE AN XIM DOOR FOR S!X v0.2ß!  |\n|                                          |\n+-[ aDDED : FILESIZE INFO & ACCESCONTROL ]-+\n|                                          |\n`-- - ---------------- - -------------- -- >\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                                                .------''\n             `------------------------------------------------''\n','\n',char(10)),NULL,'auto-added',18753,6,0,NULL,NULL,'love_02b','scan',1780048575);
INSERT INTO door_catalog VALUES('love_a16','LOVE-A16.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LOVE-A16.LHA',NULL,'XIM','air.xim',NULL,NULL,'LOVE','|\__/\__/\__/,--->ASGARD SUBDIVISON<-- 2F--. |                                          | |     AiRBYTES AN XIM DOOR FOR S!X V1.6    |',replace('|_____   ____\n|\__/\__/\__/,--->ASGARD SUBDIVISON<-- 2F--.\n|                                          |\n|     AiRBYTES AN XIM DOOR FOR S!X V1.6    |\n|                                          |\nO-    NEW DEZIGN AND CONFIG FILE ADDED    -O\n`-- - ---------------- - -------------- -- >\n','\n',char(10)),'air.doc',replace('** LOVE WHO AND WHAT\n \nWell first of all love is the subdevision of ASGARD an console group\nu all should know by now.. if not who carez :).. i (sharon) made doors\nfor a while and was now ready to release `m (yeah mayby someone else \nwould like to run one of my doors :) so i started love with ODIN and\nTMB (you will see doors from them in the future)\n\n** WHAT IS AIRBYTES\n\nWell in holland we have the thing  called AIRMILES u get one when ur\npumping gass or when u buy stuff at the grocery and things like that\nwith these airmiles u can make trips to forreign country`s or get\nprice reduction at amusement parks ... when this was new i tought\nhey i want this on my bbs so i started thinking how can i do it and\nfinally came up with the idea to give every caller that makes his\n10th call an extra 100K of upload bytes (its only for fun and making\n10 calls is easy :)\n\n** WHATS NEW :\n  \nWell i only changed the dezign a bit and added a config file so u can\ndecide yourself how many bytes u want to add .. if the config is not\nfound it will simply add 100K (nice eh ?)\n\n** HOW TO INSTALL\n \nThis is easy just copy the file AIR.XIM into your DOORS: dir\n(best is to make a subdir called air and place it inthere)\nand write the folowing line into your BBS.CMD\n \nAIR XM010DOORS:AIR.XIM\n \nor when u place it into a subdir called air\n \nAIR XM010DOORS:AIR/AIR.XIM\n \nFor /X users just make an ICON for it its easy =)\n\n** NEW FEATURE\n\nIf u don`t want to give 100k u can make a config file like this:\n-- cut here --\n1234567890\n-- cut here --\nto add 1234567890 instead of 100K this config must be in doors:air/\nand must be called Air.Config\n\n** KNOWN BUGS\n\nu can`t add 117 bytes.. don`t feel like fixing it since i think noone\nwants to give away 117 bytes\n\n** HISTORY\n\nv0.05ß  - first version written in arexx \nv0.1    - final version all bugs removed\nv1.0    - converted from arexx to c to improve the speed\nv1.1    - small bugs removed \nv1.5    - added config file for interphase\nv1.6    - totally changed the dezign\n          fixed a small bug that came into the door\n\n** NOTE \n \nIf u find any bugs please report `m to me by calling my bbs or leave me mail\nsomehere \n \nTHE UNKNOWN\n \n		+31-(0)2990-36047\n		+32-(0)2990-79677\n\nAlso please let me know when u are using one of my doors and if u like `m\nCoders that would like to join love can also call\n\n** OUR PRODUCTIONS \n \nAIRBYTES    - Coder SHARON\nUPLOADNOTE  - Coder SHARON\nUSERLISTER  - Coder SHARON\n\n** GREETINGS\n\nInterphase   - For testing and bug report AND! some idea`s\nSigma seven  - For helping me out a lot and doing S!X :)\nNoisy belch  - For his nice doors and kewl feedback\nPino         - Helping me out in the world of c\nOdin         - For what !?\nSno          - For his movies\nEmpire       - For his help and so on\nMumbly       - For his cool GB trainers for asgard!\nZigor        - HIYA! hope u can call again soon dude\nCoolhand     - For saying all the time i love AMIGA\nIron Monkey  - For his card from HK\n2FAST        - For his logo`z\n\n- and to all the guys i did forget!\n','\n',char(10)),NULL,'auto-added',17010,3,0,NULL,NULL,'love_a16','scan',1780048575);
INSERT INTO door_catalog VALUES('love_air','LOVE-AIR.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LOVE-AIR.LHA',NULL,'XIM','air.xim',NULL,NULL,'LOVE','|\__/\__/\__/,--->ASGARD SUBDIVISON<-- 2F--. |                                          | |   AiRBYTES AN XIM DOOR FOR S!X AND /X    |',replace('|_____   ____\n|\__/\__/\__/,--->ASGARD SUBDIVISON<-- 2F--.\n|                                          |\n|   AiRBYTES AN XIM DOOR FOR S!X AND /X    |\n|                                          |\n`-- - ---------------- - -------------- -- >\n','\n',char(10)),'air.doc',replace('** LOVE WHO AND WHAT\n \nWell first of all love is the subdevision of ASGARD an console group\nu all should know by now.. if not who carez :).. i (sharon) made doors\nfor a while and was now ready to release `m (yeah mayby someone else \nwould like to run one of my doors :) so i started love with ODIN and\nTMB (you will see doors from them in the future)\n\n** WHAT IS AIRBYTES\n\nWell in holland we have the thing  called AIRMILES u get one when ur\npumping gass or when u buy stuff at the grocery and things like that\nwith these airmiles u can make trips to forreign country`s or get\nprice reduction at amusement parks ... when this was new i tought\nhey i want this on my bbs so i started thinking how can i do it and\nfinally came up with the idea to give every caller that makes his\n10th call an extra 100K of upload bytes (its only for fun and making\n10 calls is easy :)\n\n** HOW TO INSTALL\n \nThis is easy just copy the file AIR.XIM into your DOORS: dir\n(best is to make a subdir called air and place it inthere)\nand write the folowing line into your BBS.CMD\n \nAIR XM010DOORS:AIR.XIM\n \nor when u place it into a subdir called air\n \nAIR XM010DOORS:AIR/AIR.XIM\n \nFor /X users just make an ICON for it its easy =)\n\n** HISTORY\n\nv0.05ß  - first version written in arexx \nv0.1    - final version all bugs removed\nv1.0    - converted from arexx to c to improve the speed\nv1.1    - small bugs removed \n\n** NOTE \n \nIf u find any bugs please report `m to me by calling my bbs or leave me mail\nsomehere \n \nTHE UNKNOWN\n \n		+31-(0)2990-36047\n		+32-(0)2990-79677\n\nAlso please let me know when u are using one of my doors and if u like `m\nCoders that would like to join love can also call\n\n** OUR PRODUCTIONS \n \nAIRBYTES - Coder SHARON\n\nMore will come soon hey this is our first one :) i am already bussy with \nthe next one :)\n','\n',char(10)),NULL,'auto-added',11354,2,0,NULL,NULL,'love_air','scan',1780048575);
INSERT INTO door_catalog VALUES('love_upn','LOVE-UPN.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LOVE-UPN.LHA','UploadNote','XIM','UploadNote',NULL,NULL,'LOVE','|\__/\__/\__/,--->ASGARD SUBDIVISON<-- 2F--. |                                          | |  UPLOAD_NOTE AN XIM DOOR FOR S!X v0.1ß!  |',replace('|_____   ____\n|\__/\__/\__/,--->ASGARD SUBDIVISON<-- 2F--.\n|                                          |\n|  UPLOAD_NOTE AN XIM DOOR FOR S!X v0.1ß!  |\n|                                          |\n`-- - ---------------- - -------------- -- >\n','\n',char(10)),'UploadNote.doc',replace('** SHARON/LOVE CONTACT ME!\n\nHe if u use my door please let me know by mailing me on a system\ni am on .. or call my bbs. number bellow in this txt file  \n\n** WHAT IS UPLOADNOTE\n\nWell a little door to let users on the other node(s) know there has\nbeen an upload... it tell info like who uploaded what file and in\nwhat conference. i hope u like the idea\n\n** HOW TO INSTALL\n \nJust rename the file into EXAMINE1 and place it in the BBS:SYSTEM/\ndir and thats all \n\n** HISTORY\n\nv0.1ß    - initial start of the door should be no BUGS :) i hope \n\n** NOTE \n \nIf u find any bugs please report `m to me by calling my bbs or leave me mail\nsomehere \n \nTHE UNKNOWN\n \n		+31-(0)2990-36047\n		+32-(0)2990-79677\n\nAlso please let me know when u are using one of my doors and if u like `m\nCoders that would like to join love can also call\n\n** OUR PRODUCTIONS \n \nAIRBYTES       - Coder SHARON\nUPLOADNOTE     - Coder SHARON\n','\n',char(10)),NULL,'auto-added',19220,6,0,NULL,NULL,'love_upn','scan',1780048575);
