INSERT INTO door_catalog VALUES('lrx_nn10','LRX-NN10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LRX-NN10.LHA','NudelNews','XIM','NudelNews',NULL,NULL,'LRX','\     / _/\___________.______ _/     /__\______   \   |     / \    _/    _/  _/  _/   |   _/',replace('       _______\n       \     / _/\___________.______\n     _/     /__\______   \   |     /\n     \    _/    _/  _/  _/   |   _/\n      \___\    /    \    \_  _    \\n           \  /\_____\    /__|     \\n            \/        \  /   |______\\n-- ------- ---- -- - --\/----- --- -- --- --\n U¡PER^LRX kickz ya 2day with another fine\n       /X-Production: nUDEL-nEWS v1.0\n-- -- - -- ---- --- ---- -- - -- --- ----- -\n','\n',char(10)),'NudelNews.doc',replace('                      .-----------------------------.\n                      | NudelNews v1.0 by U¡PER^LRX |\n                      `-----------------------------''\n\nArchiv contents - What you leeched :)\n~~~~~~~~~~~~~~~\nDOORS:NudelNews/NudelNews\nDOORS:NudelNews/NudelNews.doc\nBBS:NEWS\nBBS:Commands/BBSCmd/NEWS.info\nfile_id.diz\n-----------------------------\nand ofcoz an endless list of BBS-Adds ;)\n\n\nIntroduction - What is NudelNews?!\n~~~~~~~~~~~~\nNudelNews is a possibility for you to inform your userz about\nnews etc. without editing your "Bull.txt" everytime :)\n\n\nInstallation - eaaaaazy as alwayz ;)\n~~~~~~~~~~~~\nSimply copy the "NudelNews"-Directory to your DOORS: assign and the\n"NEWS.info" to your "BBS:Commands/BBSCmd"-Drawer ...\n(If you don''t want your userz to read the news manually kick it to\n SYSCmd!)\nAt least you have to add " ~CC_NEWS " to any BBSText-File you want ...\n"BBS:Screens/Bull.txt" seems to be a nice place ;)\n\n\nUsage - even more eazy! ;))\n~~~~~\nEdit the "BBS:NEWS"-File with your favorite Text-Editor (CED roOlez!)\n[ESC-Codes are allowed but try not to use Cursor-Positioning-Codez bcause \n they could cause sum'' trouble .. Try out the newsfile you found in the \n archiv!]\n\nIf you have nothin'' to tell your uzers, simply delete "BBS:News" ...\n\n\nLegal blabla\n~~~~~\nThiz door is SkyFuß-Ware, everybody may use it exept SkyFuß! :)))))\n\n\n','\n',char(10)),NULL,'auto-added',20520,7,0,NULL,NULL,'lrx_nn10','scan',1780048575);
INSERT INTO door_catalog VALUES('lsc_clen','LSC_CLEN.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LSC_CLEN.LHA','cleanx','XIM','cleanx',NULL,NULL,'LSC','|  |RS!._______________________________ |  |__ |__)     /~ ___/~  |~ /    /~__/ |  |  \)  |  __/  __)/    | /  __/  _)',replace('.__.\n|  |RS!._______________________________\n|  |__ |__)     /~ ___/~  |~ /    /~__/\n|  |  \)  |  __/  __)/    | /  __/  _)\n|      \  |__  \    ~\  |   \  \ \   ~\\n|______/__|____/\____/\_|____\____\___/\n''      Y  Y  PrEseNtS:  Y    Y    Y\n      -*-   /X Utility -*-\n\n           CleanX   v1.0\n\nThis util will clean up your User data files\n','\n',char(10)),'cleanx.doc',replace('\n                                CleanX v1.0\n\n                                    -*-\n\n                         © 1996 by Dr. Ice/lISENCE\n\n  -----------------------------------------------------------------------\n\n  COPYRIGHT\n  ~~~~~~~~~\n  CleanX is NetWare, this means that you must send me an E-MAIL and\n  say that you like/dislike CleanX! :))\n\n  What is CleanX !?...\n  ~~~~~~~~~~~~~~~~~~~~\n\n  CleanX is a utility that will remove all INACTIVE users in your\n  User.Data file, and re-create a new User.Data and User.Keys\n  in RAM:\n\n  How do I use it !?...\n  ~~~~~~~~~~~~~~~~~~~~~\n\n  Using it is very simpel, just write the BBS path where CleanX can\n  find User.Data and User.keys. Eg.. CleanX BBS:\n\n  How do I contact you !?...\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n  If you want to contact me for bug reports, then do it by one of\n  these ways:\n\n  E-MAIL: kaarej@barentsnettno\n  BBS   : Key Stroke BBS, +47-7847-1042\n\n','\n',char(10)),NULL,'auto-added',10074,4,0,NULL,NULL,'lsc_clen','scan',1780048575);
INSERT INTO door_catalog VALUES('lsc_xswp','LSC_XSWP.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LSC_XSWP.LHA','xsweep','XIM','pizza_taxi.exe',NULL,':','LSC',':     :¬ ¬:___ __ //____ __ //___      : ::    |:  l¯  \__\/__   \  \/    \    :: :::   l_____ //_________/________/   :::',replace('      .___. _ ____/\  _ ____/\\n:     :¬ ¬:___ __ //____ __ //___      :\n::    |:  l¯  \__\/__   \  \/    \    ::\n:::   l_____ //_________/________/   :::\n::::.<===== \/  pRESENTS:  =======>.::::\n:                                      :\n:              xSWEEP v1.0             :\n:       /X dIRx lOGfiLE sTRIpPEr       :\n:                                      :\n:               cODeD bY               :\n:           dR. iCE/LSC^OPS            :\n:                                      :\n`......................................''\n','\n',char(10)),'xsweep.doc',replace('Short:    /X dir Sweep cleaner\nVersion:  1.0\nAuthor:   Kåre Johansen <[email removed]>\nUploader: Kåre Johansen <[email removed]>\nType:     Comm/Amiex\n\n\n   Welcome\n   -------\n   Welcome to yet another product from me Dr. Ice/LSC^OPS.. This time\n   presenting XSweep for AmiExpress.. A new Dir Logfile stripper..\n\n   Copyright\n   ---------\n   XSweep is copyrighted by me Dr. Ice/LSC^OPS in 1997, all rights\n   reserved..\n\n   NetWare\n   -------\n   Some golden rules:\n\n   1.. XSweep is FreeWare, but, the copyright still remains as it is..\n   2.. The Author cannot be held responssible if XSweep should damage\n       your files/or your system.. Use it on your own risk..\n   3.. If you use XSweep allot, you should contact the author and telling\n       him how much you like his products! :)..\n   4.. XSweep can NOT be sold for profit of any kinds, except from\n       diskcharge and mailing expences..\n   5.. Write me an E-MAIL : [email removed]\n\n   What is XSweep?\n   ---------------\n   I have been on alot of boards, and happend to find alot of files\n   that has been faked, deleted, old and so on.. This was getting\n   on my nerves, going threw a DIRx logfile in several minutes\n   just to see files that didn''t exists at all.. So, I made this\n   smart program.. This program will REMOVE all of these labels\n   (And ofcoz, remove the file_id.diz in the DIRx logfile aswell)..\n   from your DIRx file..\n\n   What about duplicates?\n   ----------------------\n   Every sysop doesn''t want duplicate files on their board, right?..\n   So, the big feature in XSweep is that XSweep makes fake files\n   of the files it removes from the DIRx file.. So, when a user\n   uploads this file again, the file is already presented at the\n   board..\n\n   Usage\n   -----\n   XSweep is quite easy to use:\n\n   XSweep filename filedirpath\n\n   Filename    - The path+the dirlogfile name\n   FileDirpath - The path upload path to the filename\n\n   XSweep BBS:CONF1/DIR1 BBS:CONF2/UPLOAD/\n\n   How do I config XS?\n   -------------------\n   Configing should be quite easy aswell..\n\n   The config file contains 2 args, this 2 args must always be the same\n   length on every next line, eg\n\n   ARG1    ARG2\n   --------------\n   L-A-M-E option\n   RENAMED option\n\n   As you can se, the first argument have to be 7 chars (not shorter, and\n   not any longer).. The options will be explained soon! :) The ARG1 is\n   the header size of a file in a DIRx log, that has been changed in cause\n   of fake, old, deleted and so on, eg\n\n   Filename        FILESIZE = Replaced with DELETED or what ever!!\n   -------------------------------------------------------------------------\n   CHAOS.LHA    P  48988  12-17-96  Chaos - small address tool for permanent\n   CHAOS.LHA    P DELETED 12-17-96  Chaos - small address tool for permanent\n\n   The ARG2 options is as follows:\n\n   D = Delete files, delete from LOG and HD..\n   R = Remove files, Delete from LOG only\n   F = Fake   Files, make fake files to prevent files being uploaded again..\n\n   How do I contact you?\n   ---------------------\n   You can contact me in one of the following ways:\n\n   E-MAIL: [email removed]\n                                          \      /\n      BBS: Key Stroke BBS - +47-7847-1042 /NORWAY\\n\n   Or call Checkpoint WHQ for Lisence, and enter a message to:\n\n   dR. IcE lSC\n\n   History\n   -------\n   v1.0\n   - First public release version\n','\n',char(10)),NULL,'auto-added',10731,4,0,NULL,NULL,'lsc_xswp','scan',1780048575);
