INSERT INTO door_catalog VALUES('lsd_intu','LSD-INTU.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LSD-INTU.LHA','IntuiLhA','XIM','AddIcon',NULL,NULL,'LSD','!o  |   !o       vo    .\\ |||  |___|:  |____||  |  \\\\:- -:|||:  |   |___    :|:  |   .\\',replace('        __/|    ____/\__ ____/\           \n       !o  |   !o       vo    .\\         \n      |||  |___|:  |____||  |  \\\\:-     \n   -:|||:  |   |___    :|:  |   .\\       \n      ||.  |   |sc |   o|.  |    /        \n       |______ |________| ______/         \n       ~~~~~~~\|presents|/~~~~~~\n--------------------------------------------\n            IntuiLhA\n','\n',char(10)),'IntuiLhA.guide',replace('@DATABASE "IntuiLhA.guide"\n@NODE MAIN "IntuiLhA Dokumentation"\n\n\n                               IntuiLhA 1.15\n                               Dokumentation\n\n                     © 1992/1993 by Holger Fleischmann\n\n\n      @{"Unbedingt lesen!" LINK wichtig}               BEDIENUNGSANLEITUNG\n      @{"Copyright" LINK copyright}                      @{"Voraussetzungen" LINK voraussetzungen}\n      @{"Registrierung" LINK registrierung}                  @{"Installation" LINK installation}\n      @{"Updates" LINK updates}                        @{"Starten" LINK starten}  (mit Optionen & Tooltypes)\n      @{"Über Locale" LINK locale}                    @{"Hauptfenster" LINK hauptfenster}\n      @{"Über das Keyfile" LINK keyfile}               @{"Addfenster" LINK addfenster}\n                                     @{"Optionenfenster" LINK optionenfenster}\n      @{"Features" LINK features}                       @{"Einstellungsfenster" LINK einstellungsfenster}\n      @{"Kurzbeschreibung" LINK kurzbeschreibung}               @{"Toolsfenster" LINK toolsfenster}\n                                     @{"Online-Help" LINK online_help}\n      @{"Paketumfang" LINK paketumfang}\n      @{"Hinweise" LINK hinweise}\n      @{"History" LINK history} und @{"Zukunft" LINK zukunft}\n      @{"Fehler, Anregungen und Support" LINK fehler}\n\n      @{"Greetings & Schluß" LINK schluss}\n\n\n@ENDNODE\n@NODE wichtig "Unbedingt lesen!"\n\n\n\n   ACHTUNG: Ich übernehme KEINERLEI VERANTWORTUNG für eventuelle, durch\n            IntuiLhA entstehende Schäden. Jeder benutzt das Programm AUF\n            EINGENE GEFAHR !!!\n\n            Bitte beachten Sie die @{"Copyrighthinweise" LINK copyright}!\n\n@ENDNODE\n@NODE copyright "Copyrighthinweise"\n\n\n\n IntuiLhA ist @{"Shareware" LINK shareware}. Für nicht registrierte Benutzer ist IntuiLhA durch\n Nervrequester eingeschränkt. Jeder darf IntuiLhA frei kopieren und\n weitergeben, sofern er folgende Bedingungen erfüllt:\n\n o IntuiLhA muß mit @{"ALLEN SEINEN FILES" LINK paketumfang} vertrieben\n   werden.\n\n o KEINE DER DATEIEN DARF in irgend einer Weise VERÄNDERT werden.\n   Ausnahme:  Catalogs dürfen geändert oder neuerstellt werden, falls es\n              sich um ernstgemeinte Übersetzungen handelt. Die beiden\n              englischen Originale müssen trotzdem weitergegeben werden.\n              (siehe @{"Locale" LINK locale})\n\n o Es darf aus dem Vertrieb von IntuiLhA kein Profit entstehen: Der Preis\n   pro Diskette darf NICHT ÜBER DM 5,-- liegen.\n   Deshalb ist der Vertrieb für Fa. Karstadt, Fa. Stefan Ossowski, Fa. Wolf\n   ausdrücklich untersagt.\n\n o Das @{"KEYFILE" LINK keyfile} von IntuiLhA darf NICHT WEITERGEGEBEN ODER VERÄNDERT\n   werden. (siehe @{"Registrierung" LINK registrierung})\n\n o Zum Vertrieb und Copyright von LhA und ReqTools.library bitte die\n   entsprechenden .DOC-Files beachten.\n\n\n@ENDNODE\n@NODE paketumfang "Paketumfang"\n\n\n IntuiLhA darf nur zusammen mit folgenden Dateien weitergegeben werden:\n\n      IntuiLhA                      (Hauptprogramm)\n      IntuiLhA.info                 (Icon)\n      IntuiLhA.guide                (diese Dokumentation)\n      IntuiLhA.cd (+.ct)            (für Änderungen an den Catalogs)\n      IntuiLhAGad.cd  (+.ct)\n      IntuiLhA.catalog              (Catalogs für englisch)\n      IntuiLhAGad.catalog\n      IntuiLhA_dock_pic             (Brush für Toolsmanager)\n\n@ENDNODE\n@NODE shareware "Zum Begriff Shareware"\n\n\n\n  Shareware ist Software, die frei kopiert und getestet werden darf. Nach\n  einigen Wochen Benutzung gilt das Programm als Raubkopie und muß gelöscht\n  werden, außer Sie bezahlen sie Sharewaregebühr an den Autor, bei dem Sie\n  dann @{"registriert" LINK registrierung} werden.\n\n  Da die Sharewaremoral leider zu wünschen übrig läßt, habe ich IntuiLhA\n  durch Nervrequester eingeschränkt. Das soll Sie daran erinnern, meine\n  Share zu bezahlen.\n\n\n@ENDNODE\n@NODE hinweise "Hinweise"\n\n\n\n o Änderungen und Bugfixes sind aus @{"History" LINK history} ersichtlich!\n\n\n o Zur Konfigurationsdatei :\n\n     Ab V1.15 wurde das Format der Konfigurationsdatei komplett erneuert.\n     - Die Datei ist nun immer nur so lang, wie eben nötig\n     - kann von allen Versionen ab @{"1.15" LINK  history_1_15} gelesen werden\n     - bei @{"Updates" LINK updates} keine Neueinstellung mehr notwendig\n     - passenderer Name: ''IntuiLhA.config''  (früher ''IntuiLhA.prefs'')\n\n     Ich änderte diese Datei, da es nicht mehr tragbar war, IntuiLhA mit\n     jedem Update neu zu Konfigurieren. Außerdem müssen ab V1.15 auch\n     verschieden viele Daten gesichert werden (z.B. im @{"Toolsfenster" LINK toolsfenster}).\n\n     Diese Version muß also das letzte mal Konfiguriert werden.\n\n     Siehe auch:  @{"Einstellungen" LINK einstellungsfenster}\n                  @{"Optionen" LINK optionenfenster}\n                  @{"Toolsfenster" LINK toolsfenster}\n\n\n o IntuiLhA 1.10 finden Sie auch auf  TIME 147 !\n\n\n o Um den vollen Leistungsumfang von IntuiLhA nutzen zu können, lesen Sie\n   diese Dokumentation bitte durch! Hinter einigen Funktionen verbirgt sich\n   mehr als erwartet.\n\n\n@ENDNODE\n@NODE voraussetzungen "Voraussetzungen"\n\n\n\n o mindestens Kickstart 2.0 !\n\n o ReqTools.library V38+ (© Nico François)\n     Diese Funktionsbibliothek wird für vielfältige Requesterfunktionen\n     benötigt.\n\n o LhA (© Stefan Boberg)\n     Das "Herz" von IntuiLhA\n\n\n Folgende Bibliotheken sind optional, werden aber für vollen Leistungs-\n umfang benötigt:\n\n o Locale.library      (um andere @{"Sprachen" LINK locale} außer deutsch zu benutzen)\n\n o Diskfont.library    (um beliebige @{"Fonts" LINK pr_font} einstellen zu können)\n\n o AmigaGuide.library  (um @{"Online-Help" LINK online_help} nutzen zu können)\n\n o WhatIs.library V3+  (um @{"Anzeigefunktionen" LINK anzeigefkt} nutzen zu können)\n\n\n@ENDNODE\n@NODE registrierung "Registrierung"\n\n\n\n Da mir das Programmieren von IntuiLhA viel Zeit kostete, und auch noch\n viel Zeit kosten wird (@{"Updates" LINK updates}!!!), möchte ich für meine Arbeit auch ein\n kleines Honorar. Nachdem es aber nur wenige Benutzer gibt, die die\n Sharewaregebühr freiwillig bezahlen, habe ich einen hübschen, kleinen\n Nervrequester eingebaut (ist doch wirklich hübsch, oder?). Um diesen\n loszuwerden, müssen Sie sich bei mir registrieren lassen:\n\n\n Um nun registriert zu werden, senden Sie mir bitte\n\n     DM 20,--        (nur deutsche Mark!!!)\n\n\n Meine Adresse und Kontoverbindung:\n\n     Holger Fleischmann\n     Enzianstraße 72\n     W-8901 Königsbrunn         (ab 1.Juli 1993 neue Postleitzahl: 86343)\n     Tel. 08231/85595\n\n     Raiffeisenbank Königsbrunn\n     BLZ        :  720 691 29\n     Kontonummer:  73474\n\n ACHTUNG:  Ab 16.7.1993 ändert sich die Kontonummer und Bankleitzahl der\n           Raiffeisenbank. Verwenden Sie dann die von mir angegebene.\n\n\n Als Zahlungsmittel akzeptiere ich:\n\n       BARGELD\n       EUROCHEQUE\n       ÜBERWEISUNG          (nach telefonischer Absprache)\n\n Geben Sie bitte Ihre VOLLSTÄNDIGE ADRESSE LESERLICH an.\n\n Bei Überweisung setzen Sie sich bitte mit mir telefonisch in Verbindung.\n\n\n Falls Sie mir Bargeld oder Eurocheque senden, werde ich Ihre Registrierung\n sofort bearbeiten. Bei Überweisungen warte ich auf das Eintreffen des\n Geldes. Also bitte etwas Geduld.\n\n Ich werde Ihnen dann eine Diskette mit den beiden aktuellsten Versionen\n von IntuiLhA (siehe @{"History" LINK history}), Ihrem persönlichem @{"Keyfile" LINK keyfile} und den anderen\n frei vertreibbaren, notwendigen Dateien zusenden.\n\n Ich verwende Markendisketten, um Ihnen und mir Ärger mit kaputen Files zu\n ersparen.\n\n ACHTUNG: GEBEN SIE IHRE K E Y F I L E S   N I C H T   W E I T E R ! ! !\n          LEGEN SIE SICH EINE SICHERHEITSKOPIE AN!!!\n\n          MIT DER SHAREWAREGEBÜHR HABEN SIE  N U R  INTUILHA REGISTRIERT !!!\n          FÜR DIE REGISTRIERUNG VON LHA UND REQTOOLS.LIBRARY LESEN SIE\n          BITTE DIE ENTSPRECHENDEN DOCFILES.\n\n\n\n --------------------------------------------------------------------------\n\n  An jeden, der sich registrieren läßt, ein ganz herzliches Dankeschön !!!\n\n --------------------------------------------------------------------------\n\n\n\n\n@ENDNODE\n@NODE keyfile "Über das Keyfile"\n\n\n\n IntuiLhA ist durch Nervrequester eingeschränkt. Findet sich im Verzeichnis\n S: die Datei IntuiLhA.key mit korrektem Inhalt, ist IntuiLhA automatisch\n @{"registriert" LINK registrierung}. Dadurch können Sie alle weiteren Updates problemlos nutzen.\n\n ACHTUNG: Das Keyfile beinhaltet Ihre Adresse! Geben Sie es keinesfalls\n          weiter!\n\n\n@ENDNODE\n@NODE updates "Updates"\n\n\n\n Für IntuiLhA habe ich Updates geplant: Ich möchte neue Funktionen einbauen,\n alte verbessern und @{"Fehler" LINK fehler} beheben.\n\n\n Für den Vertrieb der Updates an registrierte Benutzer habe ich mir\n folgendes ausgedacht:\n\n Sie können @{"mir" LINK adresse} eine 3½" DD-Diskette mit einem an Sie ADRESSIERTEN\n UND AUSREICHEND FRANKIERTEN RÜCKUMSCHLAG (momentan DM2,--) zuschicken.\n Ich werde Ihnen dann die beiden neuesten Versionen von IntuiLhA\n schnellsmöglich zurücksenden.\n\n Natürlich können Sie IntuiLhA auch von Freunden, PD-Serien oder per DFÜ\n beziehen. Dank Ihrem @{"KeyFile" LINK keyfile} ist IntuiLhA dann sofort registriert, was\n Ihnen und mir eine Menge Arbeit spart und außerdem viele Updates\n ermöglicht.\n\n Die aktuellste Version von IntuiLhA liegt auch immer in der StarBox\n Hiltenfingen vor:  Tel. 08232/6067   (im Brett AMIGA-PROGRAMME)\n\n Die Version 1.10 finden Sie auch auf  TIME 147 .\n\n\n@ENDNODE\n@NODE fehler "Fehler, Anregungen und Support"\n\n\n\n Wenn Sie FEHLER in IntuiLhA entdecken:\n\n   Schreiben Sie mir oder Rufen Sie mich an!\n\n\n Wenn Sie ANREGUNGEN haben:\n\n   Vergewissern Sie sich, daß Ihre Idee nicht sowieso schon geplant ist,\n   dann wie oben.  (siehe @{"Zukunft" LINK zukunft})\n\n\n Wenn Sie PROBLEME haben:\n\n   Lesen Sie den entsprechenden Teil dieser Dokumentation, die @{"Hinweise" LINK hinweise},\n   und falls Ihr Problem dann immer noch nicht gelöst ist, rufen Sie mich\n   an.\n\n @{"Adresse und Telefonnummer" LINK adresse}\n\n\n@ENDNODE\n@NODE adresse "Meine Adresse"\n\n\n\n   Meine Adresse:\n\n        Holger Fleischmann\n        Enzianstr. 72\n        W-8901 Königsbrunn\n        Tel. 08231/85595\n\n        Deutschland\n\n   Bitte beachten Sie die neue Postleitzahl ab 1.7.1993: 86343\n\n@ENDNODE\n@NODE locale "Über Locale"\n\n\n\n IntuiLhA wurde von mir in deutsch programmiert. Damit es aber auch von\n Leuten benutzt werden kann, die des Deutschen nicht mächtig sind, stellte\n ich es im Februar 1993 auf Locale um.\n Dieses Feature kann erst ab WB2.1 genutzt werden, da IntuiLhA hierfür die\n Locale.library benötigt (ist nicht PD!).\n\n Ich erstelle die Catalogs für Englisch selbst, die aber wahrscheinlich\n nicht ganz fehlerfrei sind; sie dürfen also gerne korrigiert werden.\n Geben Sie die Originale aber bitte mit weiter.\n\n Wenn sie eigene, vollständige Übersetzungen in Fremdsprachen erstellen,\n dann lassen Sie mir diese mit den zugehörigen .ct-Files bitte zukommen.\n Die Catalogs werden dann dem @{"IntuiLhA-Paket" LINK paketumfang} zugefügt und somit auch für\n andere Anwender nutzbar.\n\n\n\n Zur Erstellung von Catalogs:\n\n    Dies ist in den Ausgaben 10+11''92 des AMIGA-Magazines genau\n    beschrieben. Auf den zugehörigen PD-Disketten finden Sie auch das von\n    mir verwendete ''MakeCat'', das die Catalogs generiert. Natürlich können\n    Sie auch ''CatComp'' (©Commodore) benutzen, falls Sie eingetragener\n    Entwickler sind...\n\n\n@ENDNODE\n@NODE features "Features"\n\n\n\n Wie der Name IntuiLhA vermuten läßt, hat dieses Programm irgend etwas mit\n dem Archivierer LhA zu tun. Das ''Intui'' steht für Intuition, und Intuition\n ist bekanntlich die Benutzeroberfläche des Amiga. Woraus sich ergibt:\n    IntuiLhA ist die ultimative Benutzeroberfläche für den genialen\n Archivierer LhA. Es soll ihnen die Eingabe ewig langer Befehlszeilen\n sparen. Jeder, der LhA schon des öfteren benutzt hat, weiß vermutlich, daß\n man sich da hin und wieder vertippt (außer einige Genies...).\n\n Es gibt für den Amiga zwar schon manche ähnliche Utilities, aber entweder\n haben die einen fest eingebauten, veralteten Packalgorithmus, sind\n unkonfortabel oder unterstützen LhA nur unvollständig.\n\n Hier einige Features von IntuiLhA:\n\n o IntuiLhA  generiert eine Befehlszeile, die dann ausgeführt wird. Dadurch\n   kann man eine beliebige Version von LhA benutzen und hat immer maximale\n   Geschwindigkeit.\n\n o IntuiLhA hat eine ansprechende und durchdachte Oberfläche im OS2.0-look.\n   Sie wurde so praktisch wie möglich gestaltet.\n\n o Es wurde sowohl an den Anfänger, als auch an den routinierten Profi\n   gedacht: @{"Sicherheitsabfragen" LINK pr_frage_vor} sind abschaltbar!\n\n o Alle wichtigen @{"Optionen" LINK optionenfenster} von LhA sind mit Gadgets einstellbar; das Merken\n   von ''-x''-Begriffen wird überflüssig, da man alle wichtigen Funktionen im\n   Klartext vor sich hat.\n\n o Die Eingabe von @{"Pfad- und Programmnamen" LINK einstellungsfenster}, sowie @{"Font" LINK pr_font} und @{"Screen" LINK pr_pubscreen}ein-\n   stellungen wird durch die konfortablen Requester der ReqTools.library\n   unterstützt.\n\n o Alle @{"Einstellungen" LINK einstellungsfenster} sind speicherbar\n\n o @{"Iconify-Funktion" LINK m_iconifizieren} (dient gleichzeitig als Appwindow!)\n\n o IntuiLhA verwenden entweder den voreingestellten Systemfont oder eine\n   beliebige, von Ihnen einstellbare, andere @{"Schrift" LINK pr_font} (benötigt\n   @{"Diskfont.library" LINK voraussetzungen})\n\n o IntuiLhA öffnet seine Fenster auf einem beliebigen @{"PublicScreen" LINK pr_pubscreen}, den es\n   auf Wunsch auch selbst öffnet!\n\n o @{"Localeunterstützung" LINK locale}: arbeiten in Ihrer Landessprache!\n\n o @{"KeyFile" LINK keyfile} für einfache @{"Updates" LINK updates}: Der @{"registrierte" LINK registrierung} Benutzer braucht nur die\n   neueste @{"Version" LINK history} von IntuiLhA zu kopieren, sie ist dann automatisch\n   registriert. Das spart Ihnen (und mir) eine Menge Arbeit.\n\n o AmigaGuide-Dokumentation\n\n o @{"Online-Help" LINK online_help}\n\n o @{"Anzeigefunktionen" LINK anzeigefkt} mit automatischer Dateikennung\n\n     Es gibt natürlich noch viele weitere Features, die ich hier aus\n     Faulheit nicht mehr aufführen kann...probieren Sie''s einfach aus!\n     Vielleicht sind Sie überrascht...\n\n\n@ENDNODE\n@NODE kurzbeschreibung "Kurzbeschreibung"\n\n\n\n  IntuiLhA ist eine konfortable Benutzeroberfläche für Steffan Bobergs\n  Archivierer LhA mit vielen Features: OS2.0-Oberfläche; direktes Ein-\n  stellen vieler Optionen ;  abschaltbare Sicherheitsabfragen; umfang-\n  reiche  Requesterabfragen;   Appicon-Funktion;  Localeunterstützung;\n  vielen Konfigurationsmöglichkeiten (Font,Screen...); Anzeigemöglich-\n  keiten mit automatischer Dateikennung (beliebig erweiterbar);Online-\n  Help ; und vor allem komfortable Archivierfunktionen (Patternselect,\n  Statistik, ...); und vieles mehr!\n  IntuiLhA ist Shareware: Registrierungsgebühr DM 20.--\n  © 1992/1993 Holger Fleischmann, Enzianstr.72, DW-8901 Königsbrunn\n\n\n@ENDNODE\n@NODE history "History"\n\n\n\n Hier werden die Änderungen in den Verschiedenen Versionen beschrieben.\n\n Legende:\n\n   KF  kleiner Fehler    (Schönheitsfehler, kleine Macken, ...)\n   GF  großer Fehler     (z.B. Systemabsturz, Zerstörung von Daten, ...)\n   NF  neues Feature     (neu eingeführte Funktion)\n   VB  Verbesserung einer alten Funktion\n   IÄ  Interne Änderung  (bräuchte ich eigentlich nicht aufführen)\n\n\n              @{"IntuiLhA1.00" LINK history_1_00}              @{"IntuiLhA1.01" LINK history_1_01}\n              @{"IntuiLhA1.10" LINK history_1_10}              @{"IntuiLhA1.11" LINK history_1_11}\n              @{"IntuiLhA1.12" LINK history_1_12}              @{"IntuiLhA1.13" LINK history_1_13}\n              @{"IntuiLhA1.14" LINK history_1_14}              @{"IntuiLhA1.15" LINK history_1_15}\n\n\n Zu den Versionsnummern:\n\n     Bei "normalen" @{"Updates" LINK updates} zähle ich um 1/100 hoch, bei großen und\n     aufwendigen Änderungen runde ich auf das nächste 1/10 auf, wie es\n     z.B bei der Umstellung auf @{"Locale" LINK locale} der Fall war.\n\n\n@ENDNODE\n@NODE kf "KF"\n\n\n   KF  kleiner Fehler    (Schönheitsfehler, kleine Macken, ...)\n\n@ENDNODE\n@NODE gf "GF"\n\n\n   GF  großer Fehler     (z.B. Systemabsturz, Zerstörung von Daten, ...)\n\n@ENDNODE\n@NODE nf "NF"\n\n\n   NF  neues Feature     (neu eingeführte Funktion)\n\n@ENDNODE\n@NODE vb "VB"\n\n\n   VB  Verbesserung einer alten Funktion\n\n@ENDNODE\n@NODE iae "IÄ"\n\n\n   IÄ  Interne Änderung  (bräuchte ich eigentlich nicht aufführen)\n\n@ENDNODE\n@NODE history_1_15 "IntuiLhA1.15"\n\n\n        Version 1.15 vom 2.6.1993\n\n\n @{"NF" LINK nf}  @{"Anzeigemöglichkeiten" LINK anzeigefkt} nun auch im @{"Hauptfenster" LINK hauptfenster}!\n\n @{"NF" LINK nf}  @{"Anzeigemöglichkeiten" LINK anzeigefkt} mit automatischer Dateikennung!\n\n @{"NF" LINK nf}  Für die Anzeigemöglichkeiten sind nun umfangreiche Kommandoaufrufe\n     möglich (@{"Toolsfenster" LINK toolsfenster})!\n\n @{"VB" LINK vb}  Der @{"Dateifilter" LINK pr_archivfilter} für den Archivrequester ist nun einstellbar!\n\n @{"VB" LINK vb}  Neue Konfigurationsdatei (siehe @{"Hinweise" LINK hinweise})\n\n @{"KF" LINK kf}  Beim Scrollen konnte es vorkommen, daß am rechten Rand ein Zeichen\n     nicht richtig gelöscht wurde.\n\n @{"KF" LINK kf}  Bei Angabe @{"anderer Optionen" LINK o_other_opts} wurde die erste darin eingestellte Option\n     nicht beachtet und außerdem die @{"Console" LINK p_console} falsch geöffnet.\n\n @{"VB" LINK vb}  Bei den @{"R-Gadgets" LINK pr_r} wird nun die momentan eingestellte Datei in den\n     Requester übernommen.\n\n @{"KF" LINK kf}  War kein @{"Screenname" LINK pr_pubscreen} eingestellt und @{"Öffne Screen" LINK pr_oeffne_screen} an, dann wurde der\n     Default-Publicscreen benutzt.\n\n @{"NF" LINK nf}  Ab sofort gibt''s @{"Online-Help" LINK online_help}!\n\n @{"KF" LINK kf}  Nach nochmaligem Klick auf ein Verzeichnis, aus dem man mit @{"Parent" LINK a_parent}\n     zurückgelangt ist, wurde dieses sofort geöffnet. Nun ist ein\n     Doppelklick erforderlich.\n\n @{"NF" LINK nf}  Ab sofort liegt die Dokumentation im Amigaguide®-Format vor.\n\n\n@ENDNODE\n@NODE history_1_14 "IntuiLhA1.14"\n\n\n\n        Version 1.14 vom 17.4.1993\n\n\n @{"NF" LINK nf}  Beim klicken an den linken Fensterrand wird nun @{"Parent" LINK a_parent} ausgeführt.\n\n @{"GF" LINK gf}  Im @{"Einstellungsfenster" LINK einstellungsfenster} gingen die ''R''-Gadgets nicht mehr! Leider\n     bemerkte ich den Fehler erst, nachdem die @{"Version 1.13" LINK history_1_13} bereits\n     im Umlauf war.\n\n\n@ENDNODE\n@NODE history_1_13 "IntuiLhA1.13"\n\n\n\n        Version 1.13 vom 17.4.1993\n\n\n @{"NF" LINK nf}  Im @{"Benutzergadget" LINK m_benutzer} können nun Platzhalter für Archiv, Fileliste,\n     Requester, etc. definiert werden.\n\n @{"NF" LINK nf}  @{"Iconifizieren" LINK m_iconifizieren} sofort beim Start durch Option oder Tooltype (für\n     Benutzung als AppIcon)\n\n @{"VB" LINK vb}  Bei @{"Druckerkommando" LINK pr_drucker_kommando} nun auch Escapesequenzen möglich!\n\n @{"VB" LINK vb}  @{"Weicheres Scrolling" LINK pr_scrolling} ist jetzt schneller (jetzt 2 Pixel).\n\n @{"VB" LINK vb}  Das @{"Scrolling" LINK pr_scrolling} ist jetzt flackerfrei.\n\n\n@ENDNODE\n@NODE history_1_12 "IntuiLhA1.12"\n\n\n\n        Version 1.12  vom 27.3.1993\n\n\n @{"VB" LINK vb}  Die Tabcycle-Reihenfolge der Stringgadgets im @{"Einstellungsfenster" LINK einstellungsfenster}\n     wurde geordnet.\n\n @{"NF" LINK nf}  Der von IntuiLhA benutzte @{"Font" LINK pr_font} ist nun einstellbar!\n\n @{"NF" LINK nf}  Sie können nun ein @{"Archiv öffnen" LINK m_archiv_oeffnen}, indem Sie sein Icon auf das\n     @{"iconifizierte" LINK m_iconifizieren} Fenster von IntuiLhA ziehen! (Ist nun ein AppWindow)\n\n @{"NF" LINK nf}  Das @{"iconifizierte" LINK m_iconifizieren} Fenster erscheint nun auf Wunsch auf der Workbench!\n\n @{"NF" LINK nf}  Die Größe des Consolefensters kann nun @{"per Maus eingestellt" LINK pr_r_console} werden!\n\n\n@ENDNODE\n@NODE history_1_11 "IntuiLhA1.11"\n\n\n\n        Version 1.11  vom 23.3.1993\n\n\n @{"NF" LINK nf}  Nun ist @{"einstellbar" LINK einstellungsfenster}, auf welchem @{"PublicScreen" LINK pr_pubscreen} IntuiLhA seine Fenster\n     öffnet. IntuiLhA kann den Screen auf Wunsch auch selbst öffnen!\n\n @{"KF" LINK kf}  Aus irgend einem Grund war der Pointer den ich von OpenWorkBench()\n     erhielt nicht immer richtig. Deshalb ersetzte ich die Funktion durch\n     LockPubScreen("Workbench"). Nun ist der @{"Nervrequester" LINK registrierung} immer schön in\n     der Mitte.\n\n @{"KF" LINK kf}  Im @{"Addfenster" LINK addfenster} wurde die Byteanzahl falsch gezählt: wenn im Namen eines\n     Verzeichnisses Ziffern am Anfang standen, wurden diese als Bytelänge\n     gewertet.\n\n @{"VB" LINK vb}  Beim @{"Iconifizieren" LINK m_iconifizieren} wird nun auch die FontBREITE beachtet. Außerdem wird\n     die Iconfensterleiste auf dem DefaultPublicScreen geöffnet.\n\n @{"KF" LINK kf}  Wenn man IntuiLhA vom @{"Addfenster" LINK addfenster} aus @{"iconifizierte" LINK m_iconifizieren}, wurde der @{"Stammpfad" LINK a_stammpfad}\n     im Stringgadget nicht mehr angezeigt.\n\n @{"VB" LINK vb}  @{"Scrolling" LINK pr_scrolling} im @{"Haupt-" LINK hauptfenster} und @{"Addfenster" LINK addfenster} wurde verbessert: nun werden nicht\n     mehr alle Einträge neu geschrieben, sondern die bereits verfügbaren\n     mit dem Blitter gescrollt.\n\n @{"KF" LINK kf}  Unter @{"OS1.3" LINK voraussetzungen} erscheint ein Requester, der darauf hinweist, daß @{"OS2.0" LINK voraussetzungen}\n     benötigt wird. Leider konnte man die weiße Schrift auf weißem Grund\n     nicht lesen...\n\n @{"KF" LINK kf}  Die @{"Optionen" LINK optionenfenster} für @{"eingeschränktes Extrahieren" LINK o_extract} (nach Datum, etc.) wurden\n     nicht beachtet, wenn man mit @{"vollem Pfad" LINK o_full_path} extrahierte.\n\n\n@ENDNODE\n@NODE history_1_10 "IntuiLhA1.10"\n\n\n\n        Version 1.10  vom 9.2.1993\n\n\n @{"KF" LINK kf}  Im @{"Addfenster" LINK addfenster} werden nun die selektierten Einträge eines Unterver-\n     zeichnisses richtig gezählt, auch wenn darin Dateien in weiteren\n     Verzeichnissen selektiert sind. (war eigentlich kein unbeabsichtigter\n     Fehler, sondern eher ein Schönheitsfehler)\n\n @{"VB" LINK vb}  Das frei definierbare @{"Optionenstring" LINK o_other_opts} wird nun ganz vorne im Kommando-\n     aufruf eingesetzt. Wenn also widersprüchliche Optionen auftreten, dann\n     wertet LhA die von Ihnen selbst eingegebenen.\n\n @{"NF" LINK nf}  Bei den @{"Optionen" LINK optionenfenster} kann man ab nun das @{"bedingte Extrahieren" LINK o_extract} per Gadget\n     einstellen: alle Dateien / neue Dateien / neuere D. / neue & neuere D.\n\n @{"KF" LINK kf}  Bei der Umstellung auf @{"Locale" LINK locale} fiel mir ein (ziemlich blöder) Recht-\n     schreibfehler im @{"Nervrequester" LINK registrierung} auf:  ... Vorraus ... wurde geändert in\n     ... voraus ...     (OK, ich geb''s ja zu...)\n\n @{"NF" LINK nf}  IntuiLhA unterstützt @{"Locale" LINK locale}, falls sie unter @{"WB2.1" LINK voraussetzungen} arbeiten!!!\n\n\n@ENDNODE\n@NODE history_1_01 "IntuiLhA1.01"\n\n\n\n        Version 1.01  vom 23.1.1993\n\n\n @{"KF" LINK kf}  @{"Weicheres Scrolling" LINK pr_scrolling} war bei ungeraden Fonthöhen nicht in Ordnung,\n     jetzt scrollt es genau so weit, wie es soll.\n\n @{"IÄ" LINK iae} Einige Aufräumarbeiten bei den Selektionsroutinen.\n\n @{"KF" LINK kf}  Bei @{"Archiv öffnen" LINK m_archiv_oeffnen} erscheint nur noch ein Requester, falls dieser\n     nicht ausgeschalten ist, wenn bereits eines geöffnet ist. Das alte\n     Archiv wird erst geschlossen, wenn ein neues angewählt wurde (geschah\n     früher schon nach Sicherheitsabfrage).\n\n @{"KF" LINK kf}  Im @{"Add-Fenster" LINK addfenster} wird der Waitpointer bei Filerequestern nun korrekt\n     gesetzt.\n\n @{"NF" LINK nf}  Automatische .info-Selektion (natürlich @{"ausschaltbar" LINK pr_select_info})\n\n @{"IÄ" LINK iae}  Da der Sourcecode schon über 130KByte erreicht hatte (ohne Oberfläche!),\n     verteilte ich ihn auf mehrere Dateien. Der Bearbeitungs- und Zeitaufwand\n     war einfach zu groß. Ich hoffe, daß dadurch keine Fehler entstanden.\n\n\n@ENDNODE\n@NODE history_1_00 "IntuiLhA1.00"\n\n\n        Version 1.00  vom 8.1.1993\n\n\n   Erste offizielle Version von IntuiLhA\n\n\n@ENDNODE\n@NODE zukunft "Zukunft"\n\n\n\n   Hier möchte ich einige geplante Verbesserungen und Ideen zu IntuiLhA\n   aufführen:\n\n\n\n o Unterstützung beliebiger Archivierer durch einstellbare Kommandosyntax.\n   (wie im @{"Toolsfenster" LINK toolsfenster}, nur noch besser!)\n\n o Archivierfunktionen frei definierbar (etwa wie @{"Benutzergadget" LINK pr_benutzer_kommando})\n\n o ARexxport\n\n o Tastatursteuerung\n\n o Einbau von Funktionen wie @{"Disk Info" LINK m_disk_info} oder @{"Formatieren" LINK m_formatieren}\n\n o Mehrere Archive gleichzeitig offen\n\n o Directorybuffering\n\n o Passwortoption\n\n o Archive über mehrere Disketten direkt einstellbar\n\n o Menue für beliebig viele Benutzerkommandos\n\n o Drucken abbrechbar\n\n o Haupt- und Addfenster als Appwindow\n\n o Bessere Sicherheitsabfrage beim Verlassen (geänderte Konfig)\n\n o Benutzung der ExAll()-Routine (Geschwindigkeit!)\n\n o Installscript\n\n\n@ENDNODE\n@NODE schluss "Greetings und Schluß"\n\n\n\n            An dieser Stelle  möchte ich meinem Bruder danken,\n                  der mir seinen AMIGA3000 und seine Ideen\n                        zur Verfügung gestellt hat.\n\n             ...die vielen kleinen Streits seien vergessen...\n\n         Ohne ihn wäre IntuiLhA nicht so schnell so gut geworden.\n\n\n\n          Außerdem danke ich für Programme, Kurse, Tips, u.a.:\n\n             Matthew Dillon                 Steffan Boberg\n             Nico François                  allen Amiga-Magazinen\n             einigen ACF-Mitgliedern        A.P.S.\n             Commodore                      Gerhard\n             Günther                        Kiki\n             S.R. & P.C.\n\n               ...allen registrierten IntuiLhA-Benutzern...\n\n            ...und natürlich allen, die ich vergessen habe...\n\n\n\n Probieren Sie IntuiLhA in Ruhe aus. Wenn Sie meinen, dieses Programm öfters\n     benutzen zu wollen, dann lassen Sie sich bitte bei mir registrieren.\n                       DM 20 sind nicht die Welt...\n\n\n\n                           Holger Fleischmann\n\n\n@ENDNODE\n@NODE installation "Installation"\n\n\n\n  Zum kopieren benutzen Sie entweder den CLI-Befehl COPY oder besser ein\n  Directory-Utility, wie z.B. DirOpus, DiskMate,...\n\n  Eventuell werde ich für die Zukunft ein Installscript schreiben.\n\n\n  Gehen Sie wie folgt vor:\n\n    o Kopieren Sie IntuiLhA in ein beliebiges Verzeichnis.\n\n    o In LIBS: muß ReqTools.library V38+ vorliegen.\n\n    o Kopieren Sie LhA in ein beliebiges Verzeichnis\n\n\n  Wenn Sie die @{"Fonts" LINK pr_font} beliebig einstellen möchten:\n\n    o in LIBS: muß Diskfont.library vorliegen, Version ist egal\n\n\n  Wenn Sie @{"Locale" LINK locale} benutzen wollen:\n\n    o Kopieren Sie die Catalogs der von Ihnen gewünschten Landessprachen\n      in LOCALE:\n      ACHTUNG: Es gibt zwei Catalogs pro Sprache! (IntuiLhA.catalog und\n               IntuiLhAGad.catalog)\n\n    o in LIBS: muß Locale.library vorliegen.\n\n\n  Wenn Sie Online-Help benutzen wollen:\n\n    o in LIBS: muß AmigaGuide.library vorliegen.\n\n\n  Wenn Sie @{"Anzeigefunktionen" LINK anzeigefkt} benutzen wollen:\n\n    o in LIBS: muß WhatIs.library V3+ vorliegen\n\n\n  Wenn Sie @{"registrierter" LINK registrierung} Benutzer sind:\n\n    o @{"IntuiLhA.key" LINK keyfile} muß in S: vorliegen.\n\n\n@ENDNODE\n@NODE starten "Starten"\n\n\n\n Sie können IntuiLhA von der Workbench oder vom CLI aus starten:\n\n  Workbench:  Doppelklick auf IntuiLhA-Icon, oder:\n              Wenn Sie gleich ein @{"Archiv öffnen" LINK m_archiv_oeffnen} wollen, können Sie IntuiLhA\n              anklicken, dann mit gedrückter Shift-Taste doppelt auf das\n              gewünschte Archivpicktogram klicken.\n\n              Wird der Tooltype ICONIFY angegeben (im Workbenchmenü Icon/\n              Information), dann verhält sich IntuiLhA beim Start wie nach\n              der Anwahl von @{"Iconifizieren" LINK m_iconifizieren} im @{"Hauptfenster" LINK hauptfenster}. Dies ist\n              sinnvoll, wenn Sie IntuiLhA immer auf der Workbench zur Ver-\n              fügen haben wollen (AppWindow-Funktion). Kopieren Sie das Icon\n              dazu in das Verzeichnis WBStartup und tragen den Tooltype\n              ICONIFY ein. Zukünftig wird IntuiLhA dann iconifiziert\n              gestartet.\n\n              TIP: Die können IntuiLhA auch als Default-Tool für ein Archiv-\n              icon eintragen: Wenn Sie dieses nun doppelt anklicken, wird es\n              automatisch von IntuiLhA @{"geöffnet" LINK m_archiv_oeffnen}.\n\n  CLI:        IntuiLhA [ICONIFY] [ArchivName]\n\n              Wird die Option ICONIFY angegeben, dann verhält sich IntuiLhA\n              wie nach Anwahl von @{"Iconifizieren" LINK m_iconifizieren} im @{"Hauptfenster" LINK hauptfenster}. Dies ist\n              sinnvoll, wenn Sie IntuiLhA immer auf der Workbench zur Ver-\n              fügen haben wollen (AppWindow-Funktion).\n              Das optional anzugebende Archiv wird automatisch geöffnet.\n\n\n Wenn IntuiLhA vor öffnen des @{"Hauptfensters" LINK hauptfenster} einen Fehler feststellt (z.B.\n keine Reqtools.library, oder nur @{"OS1.3" LINK voraussetzungen}), dann erscheint ein\n Informationsrequester, der die Fehlerursache angibt, und IntuiLhA bricht ab.\n\n\n Für nicht registrierte Benutzer:\n\n   Es erscheint ein Nervrequester, der Sie daran erinnern soll, sich\n   @{"registrieren" LINK registrierung} zu lassen. Sie müssen warten, bis er wieder verschwindet.\n\n\n@ENDNODE\n@NODE hauptfenster "Hauptfenster"\n\n\n\n Bei Verwendung des @{"Topaz-8-Fonts" LINK pr_font} hat das Hauptfenster eine Größe von\n 640x256 Pixeln.\n\n\n Das Hauptfenster stellt das Herz von IntuiLhA dar; von hier steuern Sie\n das Programm.\n\n Im Hauptfenster findet sich ein @{"Schließgadget" LINK m_closegad}, eine große @{"Auswahlfläche" LINK m_selektion}\n mit @{"Schiebebalken" LINK m_schiebebalken} an den Seiten, darunter eine @{"Statuszeile" LINK m_statuszeile}, und ganz unten\n ein Block mit vielen Gadgets:\n\n @{" DOS Kommando " LINK m_dos_kommando} @{"Archiv öffnen " LINK m_archiv_oeffnen} @{" Extrahieren  " LINK m_extrahieren} @{"Alles " LINK m_alles}  @{"Nichts" LINK m_nichts} @{"   Optionen   " LINK m_optionen}\n @{" Formatieren  " LINK m_formatieren} @{"  Archiv zu   " LINK m_archiv_zu} @{"   Löschen    " LINK m_loeschen} @{"  Umgekehrt   " LINK m_umgekehrt} @{"Einstellungen " LINK m_einstellungen}\n @{"Über IntuiLhA " LINK m_about} @{"Archiv testen " LINK m_archiv_testen} @{"   Erneuern   " LINK m_erneuern} @{"  Muster...   " LINK m_muster} @{"Konfig sichern" LINK m_konfig_sichern}\n @{"Iconifizieren " LINK m_iconifizieren} @{" Add-Fenster  " LINK m_addfenster} @{"Liste drucken " LINK m_liste_drucken} @{"  Schwarzes   " LINK m_schwarzes} @{" System Info  " LINK m_system_info}\n @{"   Beenden    " LINK m_beenden} @{"  Neues Dir   " LINK m_neues_dir} @{"   Benutzer   " LINK m_benutzer} @{"Alles schwarz " LINK m_alles_schwarz} @{"  Disk Info   " LINK m_disk_info}\n\n\n HINWEISE: @{"Anzeigefunktion" LINK anzeigefkt}\n\n Viele Funktionen von IntuiLhA werden hier nur allgemein erklärt, für\n nähere Beschreibungen müssen sie LhA.man lesen, was ich Ihnen sowieso\n empfehle, da sich darin viel Wissenswertes über die Funktionsvielfalt von\n LhA findet.\n\n\n@ENDNODE\n@NODE m_closegad "Schließgadget des Hauptfensters"\n\n\n\n  Schließgadget:\n\n\n Gleiche Funktion wir @{"Beenden" LINK m_beenden}: Nach einer @{"abschaltbaren" LINK pr_frage_vor} Sicherheitsabfrage\n wird IntuiLhA beendet.\n\n\n@ENDNODE\n@NODE m_schiebebalken "Schiebebalken"\n\n\n\n  Schiebebalken:\n\n\n Mit ihnen können Sie den sichtbaren Bereich der Archivliste einstellen.\n\n\n@ENDNODE\n@NODE m_statuszeile "Statuszeile"\n\n\n\n  Die Status Zeile:\n\n Sie zeigt ihnen, womit IntuiLhA gerade beschäftigt ist, welche Fehler\n auftraten und wie viele Bytes und Einträge gerade @{"selektiert" LINK m_selektion} sind.\n\n\n@ENDNODE\n@NODE m_selektion "Selektion im Hauptfenster"\n\n\n\n Im Hauptfenster können nach dem @{"Öffnen" LINK m_archiv_oeffnen} eines Archives die angezeigten\n Einträge mit der Maus oder einigen Gadgets selektiert werden. Diese\n werden dann invers (weiß auf schwarz) dargestellt.\n\n Das @{"Statusgadget" LINK m_statuszeile} hält Sie immer auf dem laufenden, wie viele Dateien\n mit welcher Bytelänge selektiert sind.\n\n Beim Doppelklick auf eine Datei wird diese - @{"falls eingestellt" LINK t_anzeige_haupt} -\n extrahiert und @{"angezeigt" LINK anzeigefkt}\n\n Bereits @{"extrahierte" LINK m_extrahieren} Einträge werden mit der Farbe blau als solche\n gekennzeichnet.\n\n\n@ENDNODE\n@NODE m_dos_kommando "DOS Kommando"\n\n\n  DOS Kommando:\n\n Damit können Sie von IntuiLhA aus ein Kommando wie im CLI ausführen.\n Die Aus- und Eingaben erfolgen auf dem einstellbaren @{"Consolefenster" LINK pr_console}.\n\n\n@ENDNODE\n@NODE m_formatieren "Formatieren"\n\n\n\n  Formatieren:\n\n\n Dieses Gadget startet das eingestellte @{"Formatierutility" LINK pr_format_util}, was oft sehr\n sinnvoll ist, wenn man auf eine Diskette entpacken will und gerade keine\n leere zu Hand hat. (Benutzen Sie den Formatbefehl in sys:System oder ein\n PD-Utility)\n\n\n@ENDNODE\n@NODE m_about "Über IntuiLhA"\n\n\n\n  Über IntuiLhA :\n\n\n Zeigt ihnen den Aboutrequester des Programms: Copyrightvermerk, @{"Version" LINK history}\n und den Namen des @{"registrierten" LINK registrierung} Benutzers.\n\n\n@ENDNODE\n@NODE m_iconifizieren "Iconifizieren"\n\n\n\n  Iconifizieren :\n\n Schließt das @{"Hauptfenster" LINK hauptfenster} und bringt eine kleine Titelleiste auf den\n Bildschirm. Wenn Sie in IntuiLhA zurückkehren wollen, klicken Sie die\n Leiste an und drücken die recht Maustaste, worauf sich IntuiLhA wieder\n wie vorher meldet.\n\n Wenn die Fensterleiste @{"auf der Workbench" LINK pr_iconify_wb} liegt, können Sie das Icon eines\n Archives darauf ziehen: Es wird automatisch @{"geöffnet" LINK m_archiv_oeffnen}!\n\n Wenn Sie das Schließgadget anklicken, wird IntuiLhA @{"beendet" LINK m_beenden}.\n\n Die Position der Iconifyleiste wird in s:IntuiLhA.prefs mit\n @{"abgespeichert" LINK m_konfig_sichern} und bei weiteren Aufrufen verwendet.\n\n\n@ENDNODE\n@NODE m_beenden "Beenden"\n\n\n\n  Beenden:\n\n\n Beendet IntuiLhA, falls Sie die @{"Sicherheitsabfrage" LINK pr_frage_vor} positiv beantworten.\n\n\n@ENDNODE\n@NODE m_archiv_oeffnen "Archiv öffnen"\n\n\n\n  Archiv öffnen :\n\n\n Bevor Sie die Archivfunktionen im @{"Hauptfenster" LINK hauptfenster} nutzen können, müssen Sie\n ein Archiv öffnen:\n\n  Es erscheint ein Filerequester, mit dem Sie ein Archiv auswählen müssen.\n\n  Falls bereits ein Archiv geöffnet ist, wird vorher gefragt, ob Sie\n  wirklich ein neues öffnen wollen (@{"abschaltbar" LINK pr_frage_vor}).\n\n  Ist das Archiv geöffnet, erscheinen die Einträge im @{"Selektionsfeld" LINK m_selektion}.\n\n Ein Archiv kann auch durch das Hineinziehen eines Icons in die @{"Iconify-" LINK m_iconifizieren}\n @{"leiste" LINK m_iconifizieren} geöffnet werden.\n\n\n Zum öffnen geht IntuiLhA folgendermaßen vor:\n\n  Es läßt von LhA eine Archivliste (Kommando v - siehe LhA.man) in eine\n  @{"Laufzeitdatei" LINK pr_temp_datei} schreiben, die dann eingelesen wird. Reicht der Speicher\n  nicht aus, wird die Archivliste nur teilweise eingelesen.\n  Danach wird die Laufzeitdatei wieder gelöscht.\n\n\n@ENDNODE\n@NODE m_archiv_zu "Archiv zu"\n\n\n\n  Archiv zu:\n\n\n Schließt das @{"offene" LINK m_archiv_oeffnen} Archiv wieder. Falls eingestellt, erfolgt eine\n @{"Sicherheitsabfrage" LINK pr_frage_vor}.\n\n\n@ENDNODE\n@NODE m_archiv_testen "Archiv testen"\n\n\n\n  Archiv testen:\n\n Die Struktur eines Archives, das sich durch einen Filerequester\n auswählen läßt, wird überprüft (Kommando t - siehe LhA.man). Die Ausgaben\n erfolgen auf die eingestellte @{"Console" LINK pr_console}.\n\n Die eingestellten @{"Optionen" LINK optionenfenster} werden im Kommandoaufruf mit angegeben.\n\n\n@ENDNODE\n@NODE m_addfenster "Add-Fenster"\n\n\n\n  Add-Fenster:\n\n Ein zweites, auf die Funktionen des Archivierens angepaßtes @{"Fenster" LINK addfenster} wird\n geöffnet. Während dieses Fenster offen ist, können im Hauptfenster keine\n Eingaben erfolgen!\n\n\n@ENDNODE\n@NODE m_neues_dir "Neues Dir"\n\n\n\n  Neues Dir :\n\n Ein neues Verzeichnis wird angelegt. Mit dem Filerequester können Sie\n seinen Pfad und Namen (der Filename) eingeben. Arbeitet wie MakeDir -\n nur konfortabler.\n\n\n\n@ENDNODE\n@NODE m_extrahieren "Extrahieren"\n\n\n\n  Extrahieren:\n\n\n Die @{"selektierten" LINK m_selektion} Einträge werden extrahiert, d.h. entpackt.\n (Kommando e - siehe LhA.man)\n\n Dabei werden die eingestellten @{"Optionen" LINK optionenfenster} beachtet. Die Ein- und Ausgaben\n erfolgen auf die eingestellte @{"Console" LINK pr_console}.\n\n Traten beim Extrahieren keine Fehler auf (LhA liefert Returncode 0), werden\n die extrahierten Einträge @{"blau" LINK m_selektion} gekennzeichnet. Dies soll Ihnen helfen, die\n Übersicht zu wahren. (Siehe auch @{"Schwarzes" LINK m_schwarzes}, @{"Alles schwarz" LINK m_alles_schwarz})\n\n\n@ENDNODE\n@NODE m_loeschen "Löschen"\n\n\n\n  Löschen:\n\n\n Die @{"selektierten" LINK m_selektion} Einträge werden nach einer @{"Sicherheitsabfrage" LINK pr_frage_vor} von LhA\n aus dem Archiv gelöscht (Kommando d - siehe LhA.man).\n\n ACHTUNG: gelöschte Dateien können nicht mehr gerettet werden!!!\n\n\n@ENDNODE\n@NODE m_erneuern "Erneuern"\n\n\n\n  Erneuern:\n\n\n Die @{"selektierten" LINK m_selektion} Einträge werden erneuert, d.h. durch Dateien neueren\n Datums ersetzt (Kommando f - siehe LhA.man).\n Dazu müssen Sie mit einem Filerequester das Verzeichnis angeben, in dem\n LhA die Dateien des Archives sucht und evtl. die @{"Sicherheitsabfrage" LINK pr_frage_vor}\n beantworten.\n\n Aus Zeitgründen wird die Archivliste NICHT neu eingelesen, die angezeigten\n Datum der erneuerten Einträge sind also nicht aktuell!\n Falls Sie darauf aber Wert legen sollten, können Sie das Archiv ja nochmals\n @{"öffnen" LINK m_archiv_oeffnen}.\n\n Diese Funktion ist sehr praktisch, wenn man Sicherheitskopien anlegt: Es\n brauchen nur die veränderten Files archiviert werden, was eine\n erhebliche Zeitersparnis bringt.\n\n\n@ENDNODE\n@NODE m_liste_drucken "Liste drucken"\n\n\n\n  Liste Drucken:\n\n\n Die Archivliste, die sich momentan im Speicher befindet, wird auf dem\n Drucker ausgegeben. Falls gewünscht, erscheint eine @{"Sicherheitsabfrage" LINK pr_frage_vor}.\n\n Haben sie als Druckerdevice "PAR:" oder "PRT:" @{"eingestellt" LINK pr_drucker}, erscheint\n sofort ein Printer-Trouble-Requester, wenn der Drucker nicht Online ist.\n Dadurch können Sie den Druckvorgang gleich abbrechen, ohne vorher eine\n halbe Minute warten zu müssen (das hätte Commodore in OS2.0 wohl ändern\n können!).\n\n\n@ENDNODE\n@NODE m_benutzer "Benutzergadget"\n\n\n\n  Benutzergadget:\n\n\n Dies ist ein frei belegbares Gadget, mit dem Sie ein DOS-Kommando\n aufrufen können. Einstellbar ist dieses @{"Kommando" LINK pr_benutzer_kommando} und der @{"Gadgettext" LINK pr_benutzer_text} im\n @{"Einstellungsfenster" LINK einstellungsfenster}.\n\n Ab IntuiLhA1.13 können Sie mit diesem Gadget viele Funktionen mit\n Requestern und allem Drum und Dran realisieren. Auch Archivfunktionen\n lassen sich nachbilden!\n\n\n@ENDNODE\n@NODE m_alles "Alles"\n\n\n\n  Alles:\n\n @{"Selektiert" LINK m_selektion} alle Einträge.\n\n\n@ENDNODE\n@NODE m_nichts "Nichts"\n\n\n\n  Nichts:\n\n Macht alle Einträge @{"unselektiert" LINK m_selektion}.\n\n\n@ENDNODE\n@NODE m_umgekehrt "Umgekehrt"\n\n\n\n  Umgekehrt:\n\n\n @{"Selektiert" LINK m_selektion} alle unselektierten Eintrage, und macht alle selektierten\n Einträge unselektiert.\n\n Damit können Sie z.B. nachprüfen, wie viel Speicher die nicht\n selektierten Einträge noch brauchen. (sinnvoll, wenn Sie die Dateien\n eines Archives auf mehrere Disketten verteilen wollen)\n\n\n@ENDNODE\n@NODE m_muster "Muster..."\n\n\n\n  Muster...:\n\n\n Es werden Einträge, die auf ein bestimmtes Muster passen, @{"selektiert" LINK m_selektion},\n bzw. unselektiert. Die Groß/Kleinschreibung wird nicht beachtet, die\n Syntax für Namensmuster ist im 2.0-Systemhandbuch Kapitel 7-22 genau\n beschrieben:\n\n\n    ?     steht für ein unbekanntes einzelnes Zeichen.\n           A?B  : "azb" "aab" "a b"\n           ???? : "aaaa" "pFDf" "2xY."\n\n    #<p>  steht für ein Zeichen oder eine Zeichenfolge, die sich beliebig\n          oft wiederholt.\n           A#BC    : "AC" "ABC" "ABBC" "ABBBBBBBBC"\n           A#?C    : "Axyz3C" "A_rezsdgC"\n           A#(er)q : "Aq" "Aerererq"\n\n    <p1>|<p2>  Es muß entweder Muster p1 oder p2 passen.\n                a|b|c      : "a" "b" "c"\n                x.(c|h|o)  : "x.c" "x.h" "x.o"\n                A(B|C)D    : "ABD" "ACD"\n\n    ~<p>  Alle Zeichenfolgen außer Muster p\n           ~#?.c : "fdhg" "erz" "e.h"    ABER NICHT "x.c" "sdg.c"\n\n    #? = *  Beliebig lange Folge unbekannter Zeichen.\n             *abc* : "xabc" "sdabc.f"\n\n\n\n@ENDNODE\n@NODE m_schwarzes "Schwarzes"\n\n\n\n  Schwarzes:\n\n\n Selektiert alle @{"schwarzen" LINK m_selektion} Einträge (die, welche noch nicht extrahiert\n wurden). Sinnvoll, wenn Sie die verbliebenen Dateien auch noch entpacken\n wollen, z.B. auf eine andere Diskette.\n\n\n@ENDNODE\n@NODE m_alles_schwarz "Alles schwarz"\n\n\n\n  Alles schwarz:\n\n\n Macht die als @{"extrahiert gekennzeichneten" LINK m_selektion} Einträge wieder schwarz.\n\n\n@ENDNODE\n@NODE m_optionen "Optionen"\n\n\n\n  Optionen:\n\n\n Öffnet das @{"Optionenfenster" LINK optionenfenster}.\n\n\n@ENDNODE\n@NODE m_einstellungen "Einstellungen"\n\n\n\n  Einstellungen:\n\n\n Öffnet das @{"Eintellungsfenster" LINK einstellungsfenster}.\n\n\n@ENDNODE\n@NODE m_konfig_sichern "Konfig sichern"\n\n\n\n  Konfig sichern:\n\n\n Speichert alle @{"Einstellungen" LINK einstellungsfenster} und @{"Optionen" LINK optionenfenster}, sowie die Position der\n Fensterleiste beim @{"Iconifizieren" LINK m_iconifizieren} von IntuiLhA in\n\n     s:IntuiLhA.prefs\n\n ab.\n\n\n@ENDNODE\n@NODE m_system_info "System Info"\n\n\n\n  System Info:\n\n\n Gibt Ihnen Informationen über den freien Speicher und den Namen des\n @{"offenen" LINK m_archiv_oeffnen} Archives.\n\n\n@ENDNODE\n@NODE m_disk_info "Disk Info"\n\n\n\n  Disk Info:\n\n\n Startet das eingestellte @{"Infoutility" LINK pr_info_util}. Es soll ihnen Informationen über den\n freien Platz auf Speichermedien geben.\n\n\n@ENDNODE\n@NODE addfenster "Addfenster"\n\n\n\n Bei Verwendung des @{"Topaz-8-Fonts" LINK pr_font} hat das Addfenster eine Größe von\n 640x256 Pixeln.\n\n Das Addfenster wurde zum möglichst komfortablen Erstellen von Archiven\n konzipiert.\n\n Das Addfenster wird von @{"Hauptfenster" LINK hauptfenster} aus aufgerufen. Es erscheint ein\n Verzeichnisrequester, in dem Sie den @{"Stammpfad" LINK a_stammpfad} festlegen sollen.\n\n Im Addfenster findet sich ein @{"Schließgadget" LINK a_closegad}, eine große @{"Auswahlfläche" LINK a_selektion}\n mit @{"Schiebebalken" LINK m_schiebebalken} an den Seiten und darunter eine @{"Statuszeile" LINK a_statuszeile}.\n Am oberen und rechten Fensterrand finden Sie eine Reihe von Gadgets:\n\n  @{"Stammpfad" LINK a_stammpfad} @{" Stringgadget " LINK a_pfad} @{"Lesen" LINK a_lesen} @{"Parent" LINK a_parent}\n\n  @{" Alles " LINK a_alles} @{"Nichts " LINK a_nichts}      @{"@     Add      " LINK a_add}      @{" DOS Kommando  " LINK m_dos_kommando}\n  @{"    Dateien    " LINK a_dateien}      @{" Neues / Hinzu " LINK a_neues_hinzu}      @{"   Optionen    " LINK m_optionen}\n  @{" Verzeichnisse " LINK a_verzeichnisse}      @{"Hinzu & öffnen " LINK a_hinzu_und_oeffnen}      @{" Einstellungen " LINK m_einstellungen}\n  @{"Nichts rekursiv" LINK a_nichts_rekursiv}      @{" Zu Geöffnetem " LINK a_zu_geoeffnetem}      @{" Iconifizieren " LINK a_iconifizieren}\n  @{"   Muster...   " LINK a_muster}                           @{"   Verlassen   " LINK a_verlassen}\n  @{"@ Zeige Liste  " LINK a_zeige_liste}                           @{"    Abbruch    " LINK a_abbruch}\n\n\n HINWEISE: @{"Option -r" LINK a_rek_suchen}, @{"linker Fensterrand" LINK a_parent}, @{"Anzeigefunktion" LINK anzeigefkt}\n\n Viele Funktionen von IntuiLhA werden hier nur allgemein erklärt, für\n nähere Beschreibungen müssen sie LhA.man lesen, was ich Ihnen sowieso\n empfehle, da sich darin viel Wissenswertes über die Funktionsvielfalt von\n LhA findet.\n\n\n\n@ENDNODE\n@NODE a_closegad "Schließgadget des Addfensters"\n\n\n  Schließgadget:\n\n\n Gleiche Funktion wir @{"Abbruch" LINK a_abbruch}:\n Das Addfenster wird verlassen.\n\n\n@ENDNODE\n@NODE a_statuszeile "Statuszeile"\n\n\n\n  Die Status Zeile:\n\n\n Sie zeigt ihnen, womit IntuiLhA gerade beschäftigt ist, welche Fehler\n auftraten und wie viele Bytes und Einträge gerade @{"selektiert" LINK a_selektion} sind.\n\n\n@ENDNODE\n@NODE a_selektion "Selektion im Addfenster"\n\n\n\n Nach Wahl des Stammpfades erscheint die Liste des Verzeichnisses:\n\n            XYZ                   (blau -» Verzeichnis)\n      628  .info                  (schwarz -» Datei )\n    12345  Beispiel\n\n Links steht bei Dateien die Länge in Bytes. Bei Verzeichnissen findet sich\n hier, falls darin Dateien oder Verzeichnisse selektiert wurden, z.B.\n folgender Ausdruck:\n\n     8/4   XYZ          -» in XYZ sind 8 Dateien und 4 Verzeichnisse\n                           selektiert\n\n Solch ein Eintrag ist gesperrt, d.h. er kann nicht unselektiert gemacht\n werden, solange darin irgendwelche Objekte selektiert sind.\n\n\n In Verzeichnisse gelangen Sie durch Doppelklick, zurück mit @{"Parent" LINK a_parent} oder\n Klick an den linken Fensterrand.\n\n\n Ein @{"Doppelklick" LINK anzeigefkt} auf eine Datei zeigt diese an, falls\n @{"eingestellt" LINK t_anzeige_add}\n\n Sie können die gewünschten Dateien und Verzeichnisse mit der Maus\n selektieren. Diese werden dann invers gekennzeichnet.\n\n\n@ENDNODE\n@NODE a_stammpfad "Stammpfad"\n\n\n\n  Stammpfad:\n\n\n Damit setzen Sie das Stammverzeichnis, von dem alle Pfadangaben für LhA\n ausgehen, z.B.:\n\n          Datei :  RAM:Dir/UnterDir/Datei\n      Stammpfad :  RAM:Dir\n Name im Archiv :  UnterDir/Datei\n\n Dieses Verzeichnis kann auch direkt in das @{"Stringgadget" LINK a_pfad} über der\n @{"Selektionsfläche" LINK a_selektion} eingegeben werden.\n\n\n@ENDNODE\n@NODE a_pfad "Stringgadget mit Pfad"\n\n\n\n Hier wird der @{"Stammpfad" LINK a_stammpfad} angezeigt und kann per Tastatur verändert werden.\n\n\n@ENDNODE\n@NODE a_lesen "Lesen"\n\n\n\n  Lesen:\n\n\n Das aktuelle Verzeichnis wird neu eingelesen. Dies ist sinnvoll, wenn sich\n inzwischen dessen Inhalt geändert hat.\n\n\n@ENDNODE\n@NODE a_parent "Parent"\n\n\n\n  Parent :\n\n\n Damit gelangen Sie vom aktuellen Verzeichnis in dessen Mutterverzeichnis.\n Dies geht natürlich nur, wenn Sie sich nicht sowieso schon im\n @{"Stammverzeichnis" LINK a_stammpfad} befinden.\n\n Genau das selbe geschieht, wenn sie an den linken Fensterrand klicken.\n\n\n@ENDNODE\n@NODE a_rek_suchen "Hinweis zur Option -r"\n\n\n\n HINWEIS: Haben Sie Dateien in Unterverzeichnissen selektiert, muß die\n          Option @{"Dateien rekursiv suchen" LINK o_search_rekurs} aktiviert sein!\n          Ansonsten wird LhA nur Dateien aus dem Stammverzeichnis\n          archivieren.\n\n\n@ENDNODE\n@NODE a_alles "Alles"\n\n\n\n  Alles:\n\n\n Selektiert alle Dateien und Verzeichnisse in aktuellen Verzeichnis.\n Gegenteil von @{"Nichts" LINK a_nichts}.\n\n\n@ENDNODE\n@NODE a_nichts "Nichts"\n\n\n\n  Nichts:\n\n\n Macht alle Einträge in aktuellen Verzeichnis unselektiert.\n Gegenteil von @{"Alles" LINK a_alles}.\n\n\n@ENDNODE\n@NODE a_dateien "Dateien"\n\n\n\n  Dateien:\n\n\n Selektiert alle Dateien im aktuellen Verzeichnis.\n Gegenteil von @{"Verzeichnisse" LINK a_verzeichnisse}.\n\n\n@ENDNODE\n@NODE a_verzeichnisse "Verzeichnisse"\n\n\n\n  Verzeichnisse:\n\n Selektiert alle Verzeichnisse im aktuellen Verzeichnis.\n Gegenteil von @{"Dateien" LINK a_dateien}.\n\n\n@ENDNODE\n@NODE a_muster "Muster..."\n\n\n\n  Muster...:\n\n\n Es werden Einträge, die auf ein bestimmtes Muster passen, @{"selektiert" LINK a_selektion},\n bzw. unselektiert. Die Groß/Kleinschreibung wird nicht beachtet; die\n Syntax für Namensmuster ist im 2.0-Systemhandbuch Kapitel 7-22 genau\n beschrieben:\n\n\n    ?     steht für ein unbekanntes einzelnes Zeichen.\n           A?B  : "azb" "aab" "a b"\n           ???? : "aaaa" "pFDf" "2xY."\n\n    #<p>  steht für ein Zeichen oder eine Zeichenfolge, die sich beliebig\n          oft wiederholt.\n           A#BC    : "AC" "ABC" "ABBC" "ABBBBBBBBC"\n           A#?C    : "Axyz3C" "A_rezsdgC"\n           A#(er)q : "Aq" "Aerererq"\n\n    <p1>|<p2>  Es muß entweder Muster p1 oder p2 passen.\n                a|b|c      : "a" "b" "c"\n                x.(c|h|o)  : "x.c" "x.h" "x.o"\n                A(B|C)D    : "ABD" "ACD"\n\n    ~<p>  Alle Zeichenfolgen außer Muster p\n           ~#?.c : "fdhg" "erz" "e.h"    ABER NICHT "x.c" "sdg.c"\n\n    #? = *  Beliebig lange Folge unbekannter Zeichen.\n             *abc* : "xabc" "sdabc.f"\n\n\n\n@ENDNODE\n@NODE a_nichts_rekursiv "Nichts rekursiv"\n\n\n\n  Nichts rekursiv:\n\n\n Macht ALLE Verzeichnisse und Dateien unselektiert, auch wenn sich diese\n nicht im aktuellen Verzeichnis befinden.\n\n\n@ENDNODE\n@NODE a_zeige_liste "Zeige Liste / Zeige Dir"\n\n\n\n  @ Zeige Liste/Zeige Dir:\n\n\n Mit diesem Cyclegadget schalten Sie zwischen einer Gesamtübersicht aller\n @{"selektierten" LINK a_selektion} Dateien (Liste) und dem aktuellen Verzeichnis (Dir) um.\n In der Liste können (momentan) keine Einträge angewählt werden.\n\n\n@ENDNODE\n@NODE a_add "Add / Replace / Update / Move"\n\n\n\n  Add/Replace/Update/Move:\n\n\n Mit diesem Cyclegadget können Sie die Art und Weise wählen, mit der LhA\n Dateien archiviert:\n\n     Add        Es werden nur Dateien archiviert, die NOCH NICHT IM ARCHIV\n                sind.\n\n     Replace    Es werden alle Dateien archiviert, evtl. bereits vorhandene\n                werden ERSETZT.\n\n     Update     Es werden alle Dateien archiviert, die NOCH NOCHT IM ARCHIV\n                sind oder ein NEUERES DATUM besitzten.\n\n     Move       Wie Add, aber die Dateien werden nach dem archivieren\n                gelöscht: sie werden ins Archiv verschoben.\n                Werden Daten so archiviert, dann ließt IntuiLhA das aktuelle\n                Verzeichnis neu ein.\n\n\n@ENDNODE\n@NODE a_neues_hinzu "Neues/Hinzu"\n\n\n\n  Neues/Hinzu:\n\n\n Über einen Filerequester können Sie ein Archiv auswählen, zu dem die\n Dateien addiert werden. Falls dieses Archiv noch nicht existiert, wird\n ein neues Archiv erzeugt.\n Die Ausgaben erfolgen auf die eingestellte @{"Console" LINK pr_console}.\n\n\n@ENDNODE\n@NODE a_hinzu_und_oeffnen "Hinzu & Öffnen"\n\n\n\n  Hinzu und Öffnen:\n\n\n Wie @{"Neues / Hinzu" LINK a_neues_hinzu}, aber nach abgeschlossenem Addvorgang wird das Archiv\n @{"geöffnet" LINK m_archiv_oeffnen}.\n\n\n@ENDNODE\n@NODE a_zu_geoeffnetem "Zu Geöffnetem"\n\n\n\n  Zu Geöffnetem:\n\n\n Die Dateien werden zum @{"offenem" LINK m_archiv_oeffnen} Archiv addiert. Die Archivliste wird nach\n erfolgtem Packvorgang neu eingelesen.\n\n\n@ENDNODE\n@NODE a_verlassen "Verlassen"\n\n\n\n  Verlassen:\n\n Sie kehren zum @{"Hauptfenster" LINK hauptfenster} zurück.\n\n Die Verzeichnisliste mit den selektierten Einträgen wird NICHT gelöscht\n und ist beim erneuten Starten des Addfensters sofort wieder verfügbar.\n\n\n@ENDNODE\n@NODE a_iconifizieren "Iconifizieren"\n\n\n\n  Iconifizieren:\n\n\n Schließt alle Fenster von IntuiLhA.\n Gleiche Wirkung wie @{"Iconifizieren" LINK m_iconifizieren} im Hauptfenster.\n\n\n@ENDNODE\n@NODE a_abbruch "Abbruch"\n\n\n\n  Abbruch:\n\n\n Sie kehren zum @{"Hauptfenster" LINK hauptfenster} zurück.\n\n Beim erneuten Starten des Addfensters verhält sich dieses wie beim\n Erststart.\n\n Das @{"Schließgadget" LINK a_closegad} hat die gleiche Wirkung.\n\n\n@ENDNODE\n@NODE einstellungsfenster "Einstellungsfenster"\n\n\n\n Bei Verwendung des @{"Topaz-8-Fonts" LINK pr_font} hat das Einstellungsfenster eine Größe\n von 640x256 Pixeln.\n\n Im Einstellungsfenster können Sie IntuiLhA konfigurieren und Ihren Wünschen\n anpassen.\n\n Neben dem @{"Schließgadget" LINK pr_closegad} finden sich folgende Gadgets:\n\n   @{"Console                        " LINK pr_console} @{"R" LINK pr_r_console}   @{" Voreinstellung " LINK pr_voreinstellung} @{"    Benutzen    " LINK pr_benutzen}\n   @{"Archivierer                    " LINK pr_archivierer} @{"R" LINK pr_r}   @{"  Zurücksetzen  " LINK pr_zuruecksetzen} @{"Sichern,Benutzen" LINK pr_sichern_benutzen}\n   @{"Temp. Datei                    " LINK pr_temp_datei} @{"R" LINK pr_r}   @{" Gespeichertes  " LINK pr_gespeichertes} @{"   Abbrechen    " LINK pr_abbrechen}\n   @{"Info Util.                     " LINK pr_info_util} @{"R" LINK pr_r}\n   @{"Format Util.                   " LINK pr_format_util} @{"R" LINK pr_r}   @{"O Automatisches Scrolling" LINK pr_auto_scroll}\n   @{"Help-Guide                     " LINK pr_help_guide} @{"R" LINK pr_r}   @{"@ Standard Scrolling" LINK pr_scrolling}\n   @{"Temp. Verz.                    " LINK pr_temp_dir} @{"R" LINK pr_r}\n   @{"Archivfilter                   " LINK pr_archivfilter}     @{"O LhA Resident" LINK pr_lha_resident}\n   @{"       Tools Einstellen        " LINK pr_tools_einstellen}     @{"O Kommentare anzeigen" LINK pr_show_comments}\n                                       @{"O Selektiere .info" LINK pr_select_info}\n                                       @{"O Iconifiziere auf Workbench" LINK pr_iconify_wb}\n\n   @{"Frage vor...  " LINK pr_frage_vor} O Erneuern           @{"Publicscreen                     " LINK pr_pubscreen}\n   O Extrahieren  O Liste drucken      @{"Öffne Screen O" LINK pr_oeffne_screen}   @{"   Screenmode   " LINK pr_screenmode}\n   O Löschen      O Beenden            @{"O Benutze Systemfont" LINK pr_ben_sysfont}\n   O Addieren     O Archiv schließen   @{"Font" LINK pr_font}    Name.font    Größe      @{"R" LINK pr_r_font}\n\n\n   @{"Gadget Text                      " LINK pr_benutzer_text}   @{"Drucker                          " LINK pr_drucker}\n   @{"Kommando                       " LINK pr_benutzer_kommando} @{"R" LINK pr_r}   @{"Kommando                         " LINK pr_drucker_kommando}\n\n\n@ENDNODE\n@NODE pr_closegad "Schließgadget"\n\n\n\n  Schließgadget:\n\n\n Verläßt das Einstellungsfenster ohne Änderungen zu übernehmen.\n Gleiche Funktion wie @{"Abbrechen" LINK pr_abbrechen}.\n\n\n@ENDNODE\n@NODE pr_voreinstellung "Voreinstellung"\n\n\n\n  Voreinstellung:\n\n\n Die Einstellungsgadgets werden auf Standardeinstellung gesetzt. Dies\n passiert auch, falls die Konfiguration nicht gespeichert vorliegt.\n\n\n@ENDNODE\n@NODE pr_zuruecksetzen "Zurücksetzen"\n\n\n\n  Zurücksetzen:\n\n\n Die Einstellungen werden so gesetzt, wie sie beim Aufruf des Fensters\n waren.\n\n\n@ENDNODE\n@NODE pr_gespeichertes "Gespeichertes"\n\n\n\n  Gespeichertes:\n\n\n Die Einstellungen werden so gesetzt, wie sie zuletzt gespeichert wurden.\n\n Falls keine Konfigurationsdatei (s:IntuiLhA.prefs) vorliegt, macht ein\n Requester Sie darauf aufmerksam.\n\n\n@ENDNODE\n@NODE pr_benutzen "Benutzen"\n\n\n\n  Benutzen:\n\n\n Die Änderungen werden übernommen und Sie kehren ins @{"Hauptfenster" LINK hauptfenster} bzw.\n @{"Addfenster" LINK addfenster} zurück.\n\n\n@ENDNODE\n@NODE pr_sichern_benutzen "Sichern,Benutzen"\n\n\n\n  Sichern,Benutzen:\n\n\n Die Änderungen werden gesichert (s:IntuiLhA.prefs) und übernommen.\n Sie kehren dann ins @{"Hauptfenster" LINK hauptfenster} bzw. @{"Addfenster" LINK addfenster} zurück.\n\n\n@ENDNODE\n@NODE pr_abbrechen "Abbrechen"\n\n\n\n  Abbruch:\n\n\n Sie kehren ins @{"Hauptfenster" LINK hauptfenster} bzw. @{"Addfenster" LINK addfenster} zurück ohne daß die Änderungen\n übernommen werden.\n\n\n@ENDNODE\n@NODE pr_console "Console"\n\n\n\n  Console:\n\n\n Voreinstellung: con:0/20/640/210/IntuiLhA-Console/AUTO/CLOSE/WAIT\n\n\n In diesem Stringgadget stellen Sie das IntuiLhA-Consolewindow ein.\n Dieses wird immer dann benutzt, wenn von IntuiLhA gestartete Programme\n Ein- oder Ausgaben verlangen.\n\n Wenn Sie das @{"R" LINK pr_r_console} rechts neben dem Stringgadget anwählen (R wie Request),\n dann öffnet sich ein Fenster mit den Dimensionen der eingestellten\n Console (falls vorhanden). Bringen Sie das Fenster nun auf gewünschte\n Größe und Position, danach schließen Sie das Fenster. Diese Dimensionen\n werden nun in den Consolestring übernommen.\n\n\n Hinweise zu Consolefenstern finden sich in Ihrem Systemhandbuch:\n\n    con:links/oben/Breite/Höhe/Titel [/Optionen]\n\n    Einige wichtige Optionen:\n\n    AUTO   Fenster erscheint erst, wenn Ein- oder Ausgaben erfolgen\n    CLOSE  Fenster hat Schließgadget\n    WAIT   Fenster wird erst beim Anklicken des Schließgadgets oder bei der\n           Eingabe von CTRL-\ geschlossen.\n    SCREENxxxx  xxxx steht für den Namen des Publicscreens, auf dem das\n           Fenster öffnen soll.\n\n\n@ENDNODE\n@NODE pr_r_console "R Console"\n\n\n\n  R Console:\n\n\n Wenn Sie das ''R'' rechts neben dem Stringgadget anwählen (R wie Request),\n dann öffnet sich ein Fenster mit den Dimensionen der eingestellten\n Console (falls vorhanden). Bringen Sie das Fenster nun auf gewünschte\n Größe und Position, danach schließen Sie das Fenster. Diese Dimensionen\n werden nun in den Consolestring übernommen.\n\n\n@ENDNODE\n@NODE pr_archivierer "Archivierer"\n\n\n\n  Archivierer:\n\n\n Voreinstellung:  c:LhA\n\n Hier stellen Sie Ihren Archivierer (LhA) ein.\n\n\n@ENDNODE\n@NODE pr_r "Das R-Gadget"\n\n\n\n Das ''R''-Gadget rechts neben dem Stringgadget ruft einen Filerequester auf,\n mit dem Sie den Programmpfad und Namen komfortabel eingeben können.\n\n\n@ENDNODE\n@NODE pr_temp_datei "Temporäre Datei"\n\n\n\n  Temporäre Datei:\n\n\n Voreinstellung:  t:IntuiLhA.runtime\n\n Hier stellen Sie die von IntuiLhA benötigte Laufzeitdatei ein.\n Da diese oft zum schreiben und lesen geöffnet und danach wieder gelöscht\n wird, sollte sie in der Ram Disk: liegen.\n\n Bei Verwendung von PIPE: kann ein Archiv zwar geöffnet werden, aber wenn\n eine Namensliste an LhA übergeben werden muß (z.B. beim @{"Extrahieren" LINK m_extrahieren} oder\n @{"Löschen" LINK m_loeschen}, erkennt LhA diese nicht an.\n\n\n@ENDNODE\n@NODE pr_info_util "Info Utility"\n\n\n\n  Info Utility:\n\n\n Voreinstellung:  c:Info\n\n Das hier eingestellte Utility wird dann aufgerufen, wenn Sie im\n @{"Hauptfenster" LINK hauptfenster} @{"Disk Info" LINK m_disk_info} anwählen. Es hat die Aufgabe Sie über den freien\n Speicherplatz auf den verfügbaren Speichermedien zu informieren.\n\n\n@ENDNODE\n@NODE pr_format_util "Format Utility"\n\n\n\n  Format Utility:\n\n\n Voreinstellung:   c:Format  (z.B. irgendein PD-Utility)\n Gute Alternative: sys:System/Format ?\n\n Dieses Utility soll es ihnen ermöglichen, Disketten zu formatieren, ohne\n IntuiLhA verlassen zu müssen. Es wird vom @{"Hauptfenster" LINK hauptfenster} aus mit dem Gadget\n @{"Formatieren" LINK m_formatieren} gestartet.\n\n\n@ENDNODE\n@NODE pr_help_guide "Help-Guide"\n\n\n\n  Help-Guide:\n\n\n Voreinstellung: IntuiLhA.guide\n\n Hier muß die IntuiLhA-Dokumentation (diese Datei) eingestellt werden.\n Diese wird für die @{"Online-Help" LINK online_help} benötigt.\n\n\n\n@ENDNODE\n@NODE pr_temp_dir "Temporäres Verzeichnis"\n\n\n\n  Temporäres Verzeichnis:\n\n\n Voreinstellung: t:\n\n In dieses Verzeichnis entpackt IntuiLhA einzellne Dateien aus Archiven\n um Sie @{"anzeigen" LINK anzeigefkt} zu können.\n Das Verzeichnis sollte in der RAM DISK: liegen.\n\n\n@ENDNODE\n@NODE pr_archivfilter "Archivfilter"\n\n\n\n  Archivfilter:\n\n\n Voreinstellung: (*.lzh|*.lha|*.run)\n\n Das hier eingestellte Namensmuster wird in allen Requestern benutzt, in\n denen ein Archiv ausgewählt werden soll.\n Das Muster muß das selbe Format haben wie bei @{"Muster..." LINK m_muster}.\n\n\n@ENDNODE\n@NODE pr_auto_scroll "Automatisches Scrolling"\n\n\n\n  Automatisches Scrolling:\n\n\n Voreinstellung: AN\n\n Wenn Sie den Mauszeiger mit gedrückter linker Maustaste aus dem\n @{"Selektionsfeld" LINK m_selektion} bewegen, dann wird die Archivliste automatisch\n weitergescrollt (bis zum "Anschlag").\n\n\n@ENDNODE\n@NODE pr_scrolling "Scrolling"\n\n\n\n  Standard Scrolling/Weicheres scrolling:\n\n\n Voreinstellung: Standard Scrolling\n\n Hier können Sie zwischen dem normalen Scrolling, bei dem die Einträge um\n die ganze @{"Fonthöhe" LINK pr_font} auf einmal bewegt werden, und einem Zwei-Pixel-\n Softscrolling wählen.\n\n\n@ENDNODE\n@NODE pr_lha_resident "LhA resident"\n\n\n\n  LhA Resident:\n\n\n Voreinstellung: AUS\n\n LhA wird resident in den Speicher geladen und muß so nicht bei jeder\n Operation neu eingelesen werden. Dies ist für Diskettenbenutzer besonders\n sinnvoll.\n\n IntuiLhA ruft intern das DOS-Kommando RESIDENT auf.\n\n\n@ENDNODE\n@NODE pr_show_comments "Kommentare anzeigen"\n\n\n\n  Kommentare anzeigen:\n\n\n Voreinstellung: AUS\n\n In einigen Archivlisten finden sich neben der Dateieinträge auch noch\n kleine Kommantare. Diese können auf Wunsch mit eingelesen werden, sind\n dann jedoch vorsichtshalber nicht @{"selektierbar" LINK m_selektion}.\n\n\n@ENDNODE\n@NODE pr_select_info "Selektiere .info"\n\n\n\n  Selektiere .info:\n\n\n Voreinstellung: AUS\n\n Falls an, werden die Icons der Dateien automatisch (un)selektiert.\n\n\n@ENDNODE\n@NODE pr_iconify_wb "Iconifiziere auf Workbench"\n\n\n\n  Iconifiziere auf Workbench:\n\n\n Voreinstellung: AUS\n\n Normalerweise erscheint die Iconifyleiste auf dem selben Publicscreen, auf\n dem IntuiLhA geöffnet wurde. Wollen Sie die Leiste auch als AppWindow\n (siehe @{"Iconifizieren" LINK m_iconifizieren} bei @{"Hauptfenster" LINK hauptfenster}) benutzen, dann muß sie immer auf\n der Workbench liegen.\n\n\n@ENDNODE\n@NODE pr_frage_vor "Frage vor..."\n\n\n\n  Frage vor...:\n\n\n Voreinstellungen:\n  @{"Extrahieren" LINK m_extrahieren}        AUS\n  @{"Löschen" LINK m_loeschen}            EIN\n  @{"Addieren" LINK addfenster}           EIN\n  @{"Erneuern" LINK m_erneuern}           AUS\n  @{"Liste drucken" LINK m_liste_drucken}      AUS\n  @{"Beenden" LINK m_beenden}            EIN\n  @{"Archiv schließen" LINK m_archiv_zu}   EIN\n\n\n Mit den Checkboxgadgets unter dieser Überschrift ist es Ihnen möglich,\n Sicherheitsabfragen abzuschalten. Dies ist vor allem für geübte Benutzer\n sinnvoll, während Anfänger kein Risoko eingehen müssen.\n\n\n@ENDNODE\n@NODE pr_pubscreen "Publicscreen"\n\n\n\n  Publicscreen:\n\n\n Voreinstellung: LEER   (Default-Publicscreen)\n\n Hier stellen Sie den Namen des Publicscreens ein, auf dem IntuiLhA seine\n Fenster öffnen soll. Findet IntuiLhA den Screen nicht vor und ist\n @{"Öffne Screen" LINK pr_oeffne_screen} ausgeschaltet, dann wird der Default-Publicscreen verwendet.\n Dies ist normalerweise die Workbench.\n\n\n HINWEIS: Momentan wird die Änderung erst beim nächsten @{"Neustart" LINK starten} von\n          IntuiLhA aktiv (Einstellungen dazu vorher @{"sichern" LINK pr_sichern_benutzen}!)\n\n\n@ENDNODE\n@NODE pr_oeffne_screen "Öffne Screen"\n\n\n\n  Öffne Screen:\n\n\n Voreinstellung: AUS\n\n Wenn Öffne Screen angeschaltet ist, dann öffnet IntuiLhA seinen\n Publicscreen selbst, sofern der Screen nicht schon offen ist. IntuiLhA\n verwendet den Namen aus @{"Publicscreen" LINK pr_pubscreen}.\n Wenn kein Name definiert ist, wird der Defaultname ''IntuiLhA'' verwendet.\n\n Wurde noch kein Screenmode gewählt, wird automatisch @{"Screenmode" LINK pr_screenmode}\n angesprungen.\n\n\n HINWEIS: Momentan wird die Änderung erst beim nächsten @{"Neustart" LINK starten} von\n          IntuiLhA aktiv (Einstellungen dazu vorher @{"sichern" LINK pr_sichern_benutzen}!)\n\n\n@ENDNODE\n@NODE pr_screenmode "Screenmode"\n\n\n\n  Screenmode:\n\n\n Voreinstellung:  nicht vorhanden\n\n Mit dieser Funktion können Sie die Auflösung, Farbtiefe und Größe des\n @{"Publicscreens" LINK pr_pubscreen} einstellen, den IntuiLhA benutzen soll.\n\n Dieser Bildschirm wird nur geöffnet, wenn @{"Öffne Screen" LINK pr_oeffne_screen} angeschalten ist!\n\n\n HINWEIS: Momentan wird die Änderung erst beim nächsten @{"Neustart" LINK starten} von\n          IntuiLhA aktiv (Einstellungen dazu vorher @{"sichern" LINK pr_sichern_benutzen}!)\n\n\n@ENDNODE\n@NODE pr_ben_sysfont "Benutze Systemfont"\n\n\n\n  Benutze Systemfont:\n\n\n Voreinstellung: AN\n\n Wenn diese Einstellung an ist, dann benutzt IntuiLhA den in den Preferences\n voreingestellten Systemfont für seine Fenster. Andernfalls wird die in\n IntuiLhA @{"definierte Schriftart" LINK pr_font} verwendet.\n\n Die Fenster werden auf die entsprechende Größe skaliert; falls sie dann zu\n groß für den @{"Screen" LINK pr_screenmode} sind, wird Topaz 8 verwendet.\n\n\n HINWEIS: Momentan wird die Änderung erst beim nächsten @{"Neustart" LINK starten} von\n          IntuiLhA aktiv (Einstellungen dazu vorher @{"sichern" LINK pr_sichern_benutzen}!)\n\n\n@ENDNODE\n@NODE pr_font "Font"\n\n\n\n  Font:\n\n\n Voreinstellung: topaz.font 8\n\n Hier wird der momentan eingestellte Font angezeigt.\n Dieser läßt sich mit dem @{"R-Gadget" LINK pr_r_font} ändern.\n\n\n HINWEIS: Momentan wird die Änderung erst beim nächsten @{"Neustart" LINK starten} von\n          IntuiLhA aktiv (Einstellungen dazu vorher @{"sichern" LINK pr_sichern_benutzen}!)\n\n\n@ENDNODE\n@NODE pr_r_font "R Font"\n\n\n  R Font:\n\n\n Mit diesem Gadget rufen Sie einen Fontrequester auf, in dem Sie die von\n IntuiLhA benutzte Schriftart festlegen können. Es sind alle Schriften mit\n max. 24 Pixeln Höhe und fester Breite zugelassen.\n\n Der Name der eingestellten Schriftart wird in @{"Font" LINK pr_font} angezeigt.\n\n Für diese Funktion wird die @{"Diskfont.library" LINK voraussetzungen} benötigt. Falls diese nicht\n geöffnet werden kann, verfährt IntuiLhA wie bei @{"Benutze Systemfont" LINK pr_ben_sysfont}.\n\n HINWEIS: Momentan wird die Änderung erst beim nächsten @{"Neustart" LINK starten} von\n          IntuiLhA aktiv (Einstellungen dazu vorher @{"sichern" LINK pr_sichern_benutzen}!)\n\n\n@ENDNODE\n@NODE pr_benutzer_text "Gadgettext für Benutzerkommando"\n\n\n\n  Gadgettext für Benutzerkommando:\n\n\n Voreinstellung:  Benutzer\n\n Der hier eingestellte Text (max. 14 Zeichen) erscheint als Gadgettext des\n Benutzergadgets, mit dem @{"Benutzerkommandos" LINK pr_benutzer_kommando} aufgerufen werden können.\n\n\n@ENDNODE\n@NODE pr_benutzer_kommando "Benutzerkommando"\n\n\n\n  Benutzerkommando:\n\n\n Voreinstellung:  LEER\n\n Hier können Sie ein Benutzerkommando definieren, das vom @{"Hauptfenster" LINK hauptfenster} aus\n mit einem @{"Gadget" LINK pr_benutzer_text} aufrufbar ist.\n\n Ab @{"IntuiLhA1.13" LINK history_1_13}  haben Sie nicht nur die Möglichkeit, Utilities aufzurufen,\n sondern auch Platzhalter für Archivnamen, Filelisten, Requester, etc. zu\n definieren. Dadurch können Sie zum Beispiel ein nicht implementiertes\n LhA-Kommando einbauen!\n\n Das Kommando beinhaltet ein einfaches DOS-Kommando, in dem bei Bedarf\n @{"Platzhalter" LINK platzhalter} definiert werden können.\n\n\n\n   Praktische Beispiele:\n\n\n    Nachbildung von @{"Extrahieren" LINK m_extrahieren}:\n\n       "{lh}"  {op}       e     "{ar}"   "@{"@" LINK klammeraffe}{fl}"      "{rd}"\n\n         |       |        |       |        |             |\n        LhA  Optionen Kommando  Archiv  Fileliste Zielverzeichnis\n\n\n    Nachbildung von @{"Archiv testen" LINK m_archiv_testen}:\n\n       "{lh}"  t     "{ra}"\n\n         |     |       |\n        LhA Kommando Archiv\n\n\n    Volle Liste des geöffneten Archives ausgeben:\n\n       "{lh}"  vv    "{ar}"\n\n         |     |       |\n        LhA Kommando Archiv\n\n\n    Rename-Funktion:\n\n       Rename "{rf}" "{rf}"\n\n         |      |      |\n       Befehl  Name   Name\n\n\n@ENDNODE\n@NODE klammeraffe "Klammeraffe{"\n\n\n\n Ich habe es nicht geschafft, mit Amigaguide® die Zeichenfolge\n   Klammeraffe - geschwungene Klammer auf\n darzustellen.\n Diese Sequenz wird von AG nämlich als Steuerkommando interpretiert.\n Als Notlösung ist der Klammeraffe nun halt umrahmt. Sorry...\n\n\n@ENDNODE\n@NODE pr_drucker "Drucker"\n\n\n\n  Drucker:\n\n\n Voreinstellung:  prt:\n\n Hier stellen Sie ein, auf welches Gerät IntuiLhA seinen Druckerausgaben\n schickt (z.B. bei @{"Liste drucken" LINK m_liste_drucken}).\n\n Ist hier prt: oder par: eingetragen, wird der Printertrouble-Requester\n von IntuiLhA abgefangen, was Ihnen bei versehentlicher Anwahl lange\n Wartezeien erspart. Ist dies nicht erwünscht (serieller Anschluß oder\n Spooler), geben Sie zusätzlich ein Lehrzeichen mit ein.\n\n\n\n@ENDNODE\n@NODE pr_drucker_kommando "Drucker Kommando"\n\n\n\n  Kommando:\n\n\n Voreinstellung: LEER\n\n Das hier eingegebene String wird von IntuiLhA bei @{"Druckerausgaben" LINK pr_drucker} zuerst\n gesendet. Es kann zum Beispiel eine Überschrift oder Steueranweisungen\n enthalten. Der Schrägstrich ''\'' ersetzt ein Escapezeichen. Ein doppelter\n Schrägstring ''\\'' erstetzt den einfachen ''\''.\n\n\n Beispiele:\n\n   \[3m          -->   ESC[3m        (schaltet Schrägschrift ein)\n   \\Hallo\\     -->   \Hallo\\n   \\\\//        -->   \\//\n   \[1m          -->   ESC[1m        (Fettdruck an)\n\n\n@ENDNODE\n@NODE pr_tools_einstellen "Tools einstellen"\n\n\n\n  Mit diesem Gadget gelangen Sie in das @{"Toolsfenster" LINK toolsfenster}.\n\n\n@ENDNODE\n@NODE optionenfenster "Optionenfenster"\n\n\n\n Bei Verwendung des @{"Topaz-8-Fonts" LINK pr_font} hat das Optionenfenster eine Größe von\n 640x256 Pixeln.\n\n Im Optionenfenster stellen Sie die Optionen von LhA ein. Diese legen das\n Arbeitsverhalten des @{"Archivierers" LINK pr_archivierer} fest.\n\n Neben dem @{"Schließgadget" LINK o_closegad} finden sich folgende Gadgets:\n\n\n  @{"Buffer                        " LINK o_buffer}     @{"Voreinstellung " LINK o_voreinstellung} @{"    Benutzen    " LINK o_benutzen}\n  @{"Priorität                     " LINK o_priority}     @{"  Zurücksetzen " LINK o_zuruecksetzen} @{"Sichern,Benutzen" LINK o_sichern_benutzen}\n  @{"Geschwindigk.                 " LINK o_speed}     @{"  Gesichertes  " LINK o_gesichertes} @{"    Abbruch     " LINK o_abbruch}\n\n    Allgemeine Optionen                Anzeigeoptionen\n  O @{"Voller Pfad                 " LINK o_full_path}     O @{"Keine Ausgaben                " LINK o_be_quiet}\n  O @{"Filenotes ignorieren        " LINK o_ignore_filenotes}     O @{"Keine Byteanzeige             " LINK o_no_byte_progress}\n  O @{"Dateiattribute sichern      " LINK o_preserve_attrs}     O @{"Keine Fortschrittsanzeige     " LINK o_no_progress}\n  O @{"Dateiname zu Kleinbuchstaben" LINK o_to_small}     O @{"Schnelle Anzeige              " LINK o_fast_display}\n  O @{"Dateiname zu Großbuchstaben " LINK o_to_capital}       Anzeige @{"@ Bytes " LINK o_display}\n  O @{"Dateien bestätigen          " LINK o_check_files}\n  O @{"Keine Fragen                " LINK o_no_queries}       Extrahieroptionen\n  O @{"LHAOPTS-Variable ignorieren " LINK o_ignore_lhaopts}       Extrahiere @{"@ alle Dateien " LINK o_extract}\n  O @{"Kein .lha/.lzh anhängen     " LINK o_no_suffix}     O @{"Arc-Bit bei Extract löschen   " LINK o_clear_arcbit}\n                                     O @{"Datum aktualisieren           " LINK o_act_date}\n    Optionen für Add                 O @{"Keine Autoshow-Dateien        " LINK o_no_autoshow}\n  O @{"Leere Dirs archivieren      " LINK o_archive_empty}\n  O @{"Dateien rekursiv suchen     " LINK o_search_rekurs}       Archiviermethode\n  O @{"Bei Effizienz<3% speichern  " LINK o_store_ratio}       Algorithmus @{"@ -lh5- " LINK o_algorithm}\n  O @{"Archive packen              " LINK o_pack_archives}\n\n  @{"Andere Optionen                                                    " LINK o_other_opts}\n\n\n@ENDNODE\n@NODE o_buffer "Buffer"\n\n\n\n  Buffer:\n\n\n Option:           -b\n Voreinstellung :  32k\n\n Diese Option setzt den Arbeitsspeicher für LhA. Je größer dieser ist,\n desto schneller kann LhA Archive bearbeiten. Der sinnvolle Bereich ist\n mit minimal 8K und maximal 128K begrenzt.\n\n\n@ENDNODE\n@NODE o_priority "Priorität"\n\n\n\n  Priorität:\n\n\n Option:          -P\n Voreinstellung : 0\n\n Diese Option setzt die Taskpriorität von LhA, also die vom System zur\n Verfügung gestellte Rechenzeit. Der Bereich kann von -15 bis +15\n eingestellt werden.\n\n ACHTUNG: Sehr hohe Priorität kann andere wichtige Systemprogramme fast zum\n          stehen bringen!\n\n\n@ENDNODE\n@NODE o_speed "Geschwindigkeit"\n\n\n\n  Geschwindigkeit:\n\n\n Option:          -v\n Voreinstellung : 5\n\n Diese Option setzt die Packgeschwindigkeit von LhA. Mit wachsender\n Geschwindigkeit werden die Dateien allerdings weniger gepackt.\n Der Bereich ist von 1 bis 9 einstellbar.\n\n\n@ENDNODE\n@NODE o_closegad "Schließgadget"\n\n\n\n  Schließgadget:\n\n\n Verläßt das Optionenfenster ohne Änderungen zu übernehmen.\n Gleiche Funktion wie @{"Abbruch" LINK o_abbruch}.\n\n\n@ENDNODE\n@NODE o_voreinstellung "Voreinstellung"\n\n\n\n  Voreinstellung:\n\n\n Die Optionengadgets werden auf Standardeinstellung gesetzt. Dies\n passiert auch, falls die Konfiguration nicht gespeichert vorliegt.\n\n\n@ENDNODE\n@NODE o_zuruecksetzen "Zurücksetzen"\n\n\n\n  Zurücksetzen:\n\n\n Die Optionen werden so gesetzt, wie sie beim Aufruf des Fensters waren.\n\n\n@ENDNODE\n@NODE o_gesichertes "Gesichertes"\n\n\n\n  Gesichertes:\n\n\n Die Optionen werden so gesetzt, wie sie zuletzt gespeichert wurden.\n\n Falls keine Konfigurationsdatei (s:IntuiLhA.prefs) vorliegt, macht ein\n Requester Sie darauf aufmerksam.\n\n\n@ENDNODE\n@NODE o_benutzen "Benutzen"\n\n\n\n  Benutzen:\n\n\n Die Änderungen werden übernommen und Sie kehren ins @{"Hauptfenster" LINK hauptfenster} bzw.\n @{"Addfenster" LINK addfenster} zurück.\n\n\n@ENDNODE\n@NODE o_sichern_benutzen "Sichern,Benutzen"\n\n\n\n  Sichern,Benutzen:\n\n\n Die Änderungen werden gesichert (s:IntuiLhA.prefs) und übernommen.\n Sie kehren dann ins @{"Hauptfenster" LINK hauptfenster} bzw. @{"Addfenster" LINK addfenster} zurück.\n\n\n@ENDNODE\n@NODE o_abbruch "Abbruch"\n\n\n\n  Abbruch:\n\n\n Sie kehren ins @{"Hauptfenster" LINK hauptfenster} bzw. @{"Addfenster" LINK addfenster} zurück ohne daß die Änderungen\n übernommen werden.\n\n\n@ENDNODE\n@NODE o_full_path "Voller Pfad"\n\n\n\n  Voller Pfad:\n\n\n Option:          -x\n Voreinstellung : EIN  (-x1)\n\n Mit dieser Option legen Sie fest, ob Dateien mit vollem Pfad oder nur nach\n Dateinamen @{"archiviert" LINK addfenster} bzw. @{"extrahiert" LINK m_extrahieren} werden.\n\n\n Falls diese Option ausgeschaltet ist, wird beim extrahieren ''-x2''\n angegeben und beim Archivieren ''-x0''.\n\n\n@ENDNODE\n@NODE o_ignore_filenotes "Filenotes ignorieren"\n\n\n\n  Filenotes ignorieren:\n\n\n Option:          -f\n Voreinstellung : AUS\n\n Mir dieser Option können Sie verhindern, daß Filenotes (der einer Datei\n zugefügte Kommentar) archiviert oder extrahiert wird.\n\n\n@ENDNODE\n@NODE o_preserve_attrs "Dateiattribute sichern"\n\n\n\n  Dateiattribute sichern:\n\n\n Option:          -a\n Voreinstellung : AUS  (-a0)\n\n Mit dieser Option können Sie LhA dazu veranlassen, daß die Dateiattribute\n (rwed Flags) mit archiviert bzw. extrahiert werden.\n\n\n@ENDNODE\n@NODE o_to_small "Dateiname zu Kleinbuchstaben"\n\n\n\n  Dateiname zu Kleinbuchstaben:\n\n\n Option:          -l\n Voreinstellung : AUS\n\n Mir dieser Option werden die Dateinamen zu Kleinbuchstaben gewandelt.\n\n\n@ENDNODE\n@NODE o_to_capital "Dateiname zu Großbuchstaben"\n\n\n\n  Dateiname zu Großbuchstaben:\n\n\n Option:          -u\n Voreinstellung : AUS\n\n Mit dieser Option werden Dateinamen zu Großbuchstaben gewandelt.\n\n\n@ENDNODE\n@NODE o_check_files "Dateien bestätigen"\n\n\n\n  Dateien bestätigen:\n\n\n Option:          -c\n Voreinstellung : AUS\n\n Mit dieser Option überprüft LhA nach dem nach dem Extrahieren, ob die Datei\n richtig angelegt wurde.\n\n\n@ENDNODE\n@NODE o_no_queries "Keine Fragen"\n\n\n\n  Keine Fragen:\n\n\n Option:          -m\n Voreinstellung : AUS\n\n Mit dieser Option verhindern Sie eventuelle Sicherheitsabfragen von LhA.\n Diese erscheinen z.B. beim überschreiben einer Datei.\n\n\n@ENDNODE\n@NODE o_ignore_lhaopts "LHAOPTS-Variable ignorieren"\n\n\n\n  LHAOPTS-Variable ignorieren:\n\n\n Option:          -I\n Voreinstellung : EIN\n\n Mit dieser Option verhindern Sie die Auswertung der Umgebungsvariable\n LHAOPTS, in der Optionen für LhA angegeben werden können.\n\n Dies ist SINNVOLL, da sich die Optionen in LHAOPTS und die von IntuiLhA\n übergebenen Optionen widersprechen könnten!\n\n\n@ENDNODE\n@NODE o_no_suffix "Kein .lha/.lzh anhängen"\n\n\n\n  Kein .lha/.lzh anhängen:\n\n\n Option:          -X\n Voreinstellung : AUS\n\n Mit dieser Option verhindern Sie, daß LhA automatisch fehlende\n Archivnamenendungen (.lha/.lzh) anhängt.\n\n\n@ENDNODE\n@NODE o_archive_empty "Leere Dirs archivieren"\n\n\n\n  Leere Dirs archivieren:\n\n\n Option:          -e\n Voreinstellung : AUS\n\n Mit dieser Option archiviert LhA auch leere Verzeichnisse.\n Wenn diese Option aktiviert wird, setzt IntuiLhA automatisch\n @{"Dateien rekursiv suchen" LINK o_search_rekurs}, da sie sonst wirkungslos wäre.\n\n\n@ENDNODE\n@NODE o_search_rekurs "Dateien rekursiv suchen"\n\n\n\n  Dateien rekursiv suchen:\n\n\n Option:          -r\n Voreinstellung : EIN\n\n Diese Option muß aktiviert sein, damit LhA auch Dateien aus\n Unterverzeichnissen archiviert.\n\n\n@ENDNODE\n@NODE o_store_ratio "Bei Effizienz<3% speichern"\n\n\n\n  Bei Effizienz<3% speichern :\n\n\n Option:          -Y\n Voreinstellung : AUS\n\n Mit dieser Option speichert LhA Dateien ungepackt ins Archiv, wenn sie\n um weniger als 3% gepackt werden konnten.\n Dies bringt beim @{"Extrahieren" LINK m_extrahieren} Geschwindigkeitsvorteile.\n\n\n@ENDNODE\n@NODE o_pack_archives "Archive packen"\n\n\n\n  Archive packen:\n\n\n Option:          -Z\n Voreinstellung : AUS\n\n Mir dieser Option packt LhA Archivdateien beim @{"Addieren" LINK addfenster} nochmals, obwohl\n diese meist nicht mehr kürzer werden.\n\n\n@ENDNODE\n@NODE o_be_quiet "Keine Ausgaben"\n\n\n\n  Keine Ausgaben:\n\n\n Option:          -q\n Voreinstellung : AUS\n\n Mit dieser Option macht LhA keine Bildschirmausgaben.\n\n\n@ENDNODE\n@NODE o_no_byte_progress "Keine Byteanzeige"\n\n\n\n  Keine Byteanzeige:\n\n\n Option:          -n\n Voreinstellung : AUS\n\n Mit dieser Option zeigt LhA nicht an, wie viel einer Datei bereits\n bearbeitet wurde.\n\n\n@ENDNODE\n@NODE o_no_progress "Keine Fortschrittsanzeige"\n\n\n\n  Keine Fortschrittsanzeige:\n\n\n Option:          -N\n Voreinstellung : AUS\n\n Mit dieser Optiom zeigt LhA nicht an, welche Datei gerade bearbeitet wird.\n\n\n@ENDNODE\n@NODE o_fast_display "Schnelle Anzeige"\n\n\n\n  Schnelle Anzeige:\n\n\n Option:          -F\n Voreinstellung : AUS\n\n Mir dieser Option springt LhA nur beim Auftreten eines Fehlers in die\n nächste Zeile.\n Dadurch entfällt normalerweise das Scrollen, wodurch man einen kleinen\n Geschwindigkeitsvorteil erhält.\n\n\n@ENDNODE\n@NODE o_display "Bytes / Rotierende Linie / In Prozent / Balken"\n\n\n\n  @Bytes/Rotierende Linie/In Prozent/Balken:\n\n\n Option:          -D\n Voreinstellung : Bytes  (-D0)\n\n Mir dieser Option kann man LhA dazu veranlassen, eine alternative Anzeige\n für das Bearbeiten von Dateien zu verwenden:\n\n\n  Bytes:\n\n    (    xx/  yyyy)  xx Bytes von yyyy gesamt\n\n\n  Rotierende Linie:\n\n    LhA gibt nacheinander die Zeichen \ | / - ... an der selben Position\n    aus, wodurch der Eindruck einer um eine Achse rotierenden Linie\n    entsteht.\n\n\n  In Prozent:\n\n    (xx%)  xx Prozent von der Gesamtlänge der Datei\n\n\n  Balken:\n\n    Wenn der Balken voll ist, wurde die Datei ganz bearbeitet.\n\n\n@ENDNODE\n@NODE o_clear_arcbit "Arc-bit bei Extrakt löschen"\n\n\n\n  Arc-bit bei Extrakt löschen:\n\n\n Option:          -C\n Voreinstellung : AUS\n\n Mit dieser Option löscht LhA bei einer extrahierten Datei das Archivbit.\n (---arwed)\n     ^\n\n\n@ENDNODE\n@NODE o_act_date "Datum aktualisieren"\n\n\n\n  Datum aktualisieren:\n\n\n Option:          -E\n Voreinstellung : AUS\n\n Mit dieser Option wird das Datum der extrahierten Dateien auf das aktuelle\n gesetzt.\n\n\n@ENDNODE\n@NODE o_no_autoshow "Keine Autoshow-Dateien"\n\n\n\n  Keine Autoshow-Dateien :\n\n\n Option:          -M\n Voreinstellung : AUS\n\n Mit dieser Option verhindern Sie, daß LhA auf ''.displayme'' endende Dateien\n anzeigt.\n\n\n@ENDNODE\n@NODE o_extract "Extrahiere  alle/neue/neuere/neue & neuere  Dateien"\n\n\n\n  Extrahiere  @alle/neue/neuere/neue & neuere  Dateien:\n\n\n Option:          keine / -t / -G / -T\n Voreinstellung   alle Dateien (keine)\n\n\n Mit dieser Option können Sie festlegen, ob LhA alle Dateien, noch nicht\n vorhandene oder aktuellere Dateien @{"extrahiert" LINK m_extrahieren}.\n\n\n@ENDNODE\n@NODE o_algorithm "Algorithmus"\n\n\n\n  Algorithmus @lh5/lh4/lh1:\n\n\n Option:          -2 / -1 / -0\n Voreinstellung : -2\n\n\n Mit dieser Option bestimmen Sie, welchen Packalgorithmus LhA beim\n @{"Archivieren" LINK addfenster} verwendet.\n\n lh5 ist momentan der neueste Algorithmus.\n\n lh5 Archive enden auf ''.lha''\n lh4 Archive enden auf ''.lzh''\n lh1 Archive enden auf ''.lzh''\n\n\n@ENDNODE\n@NODE o_other_opts "Andere Optionen"\n\n\n\n  Andere Optionen:\n\n\n Voreinstellung:  LEER\n\n In diesem Stringgadget können Sie einen Optionenstring angeben, der in\n den Aufruf von LhA mit eingebaut wird.\n Diese hier eingestellten Optionen haben den per Gadgets Eingestellten\n auf jeden Fall Vorrang.\n\n\n@ENDNODE\n@NODE online_help "Online-Help"\n\n\n\n  Wenn Sie in einem Fenster von IntuiLhA die HELP-Taste drücken, erscheint\n  der entsprechende Teil der AmigaGuide®-Dokumentation.\n\n  Dazu wird die @{"Amigaguide.library" LINK voraussetzungen} benötigt.\n  Die @{"Help-Guide" LINK pr_help_guide} muß im @{"Einstellungsfenster" LINK einstellungsfenster} definiert werden!\n\n\n@ENDNODE\n@NODE anzeigefkt "Anzeigefunktionen"\n\n\n\n  Um die Anzeigefunktionen nutzen zu können, benötigt IntuiLhA die\n  @{"WhatIs.library V3+" LINK voraussetzungen}.\n\n  Um eine Datei anzuzeigen müssen Sie mit der Maus darauf eine Doppelklick\n  ausführen. Vom @{"Hauptfenster" LINK hauptfenster} aus wird diese Datei zuerst in das\n  @{"Temporäre Verzeichnis" LINK pr_temp_dir} extrahiert.\n  Dann stellt IntuiLhA den @{"Dateityp" LINK dateitypen} fest (z.B. Text,ILBM-Bild,...), und ruft\n  die entsprechenden Kommandos auf. Diese Kommandos sind im @{"Toolsfenster" LINK toolsfenster} zu\n  definieren.\n\n  Die Doppelklickfunktion ist im Toolsfenster abschaltbar.\n\n\n@ENDNODE\n@NODE toolsfenster "Toolsfenster"\n\n\n\n  Im Toolsfenster werden Kommandoaufrufe für die @{"Anzeigefunktionen" LINK anzeigefkt}\n  definiert. Man öffnet es von @{"Einstellungsfenster" LINK einstellungsfenster} aus mit\n  @{"Tools einstellen" LINK pr_tools_einstellen}.\n\n  ACHTUNG: es wird die WhatIs.library V3+ benötigt!\n\n  RECHTS UNTEN finden sich die vom @{"Einstellungs" LINK einstellungsfenster}- und @{"Optionenfenster" LINK optionenfenster}\n  bekannten Gadgets, mit denen man die Änderungen sichern, zurücksetzen oder\n  übernehmen kann. Unterschied: es gibt keine Voreinstellungen.\n\n  LINKS OBEN findet sich die Liste der bekannten @{"Dateitypen" LINK dateitypen}.\n  RECHTS OBEN lassen sich die @{"Kommandos editieren" LINK t_edit_coms}.\n\n  Außerdem gibt es noch Einstellungsgadgets:\n\n   @{"O Anzeige im Hauptfenster" LINK t_anzeige_haupt}\n   @{"O Anzeige im Addfenster  " LINK t_anzeige_add}\n\n\n@ENDNODE\n@NODE dateitypen "Dateitypen"\n\n\n\n  Die Dateitpyen werden mit Hilfe der @{"WhatIs.library" LINK voraussetzungen} festgestellt. Diese\n  kennt schon eine ganze Reihe davon, kann aber mit Hilfe der Datei\n  s:FileTypes erweitert werden (siehe Dokumentation zu WhatIs).\n  Wenn eine Datei falsch erkannt wird, müssen Sie s:FileTypes (wie in\n  WhatIs.doc beschrieben) ändern.\n\n\n@ENDNODE\n@NODE t_anzeige_haupt "Anzeige im Hauptfenster"\n\n\n\n  Anzeige im Hauptfenster:\n\n\n Schaltet die @{"Anzeigefunktion" LINK anzeigefkt} auf Doppelklick im @{"Hauptfenster" LINK hauptfenster} ein oder aus.\n\n\n@ENDNODE\n@NODE t_anzeige_add "Anzeige im Addfenster"\n\n\n\n  Anzeige im Addfenster:\n\n\n Schaltet die @{"Anzeigefunktion" LINK anzeigefkt} auf Doppelklick im @{"Addfenster" LINK addfenster} ein oder aus.\n\n\n@ENDNODE\n@NODE t_edit_coms "Kommandos editieren"\n\n\n\n  Zuerst muß man von den @{"Dateitypen" LINK dateitypen} einen auswählen, zu dem man den\n  Kommandoaufruf definieren will. Dann stehen folgende Gadgets zur\n  Verfügung:\n\n\n     @{"Text                                            " LINK t_text}\n\n     @{"Kommandoliste                                   " LINK t_com_list}\n     @{"                                                " LINK t_com_list}\n     @{"                                                " LINK t_com_list}\n\n     @{"@   DOS    " LINK t_dos} @{"Kommandostring" LINK t_kommando}\n     @{"@ Synchron " LINK t_synch} @{"  Neues  " LINK t_neues} @{" Löschen " LINK t_loeschen} @{"  Rauf  " LINK t_rauf} @{" Runter " LINK t_runter}\n\n\n@ENDNODE\n@NODE t_text "Text"\n\n\n\n  Der hier eingestellte Text wird beim Aufruf automatisch ausgegeben.\n\n\n@ENDNODE\n@NODE t_com_list "Kommandoliste"\n\n\n\n  Dies ist die Liste von Kommandos in der Reihenfolge, wie sie später\n  aufgerufen werden.\n  Man wählt ein Kommando mit der Maus aus. Nun kann es verändert werden.\n  Die Reihenfolge wird mit @{"Rauf" LINK t_rauf} - @{"Runter" LINK t_runter} geändert.\n  Es können Kommandos @{"zugefügt" LINK t_neues}  oder @{"gelöscht" LINK t_loeschen} werden.\n\n\n  @{"Beispiele für Kommandoaufrufe" LINK beispiel_kommandos}\n\n@ENDNODE\n@NODE t_rauf "Rauf"\n\n\n\n  Rauf:\n\n\n Bewegt Kommando nach oben.\n\n\n@ENDNODE\n@NODE t_runter "Runter"\n\n\n\n  Runter:\n\n\n Bewegt Kommando nach unten.\n\n\n@ENDNODE\n@NODE t_neues "Neues"\n\n\n\n  Neues:\n\n\n Fügt neues Kommando hinzu.\n\n\n@ENDNODE\n@NODE t_loeschen "Löschen"\n\n\n\n  Löschen:\n\n\n Löscht Kommando.\n\n\n@ENDNODE\n@NODE t_dos  "@ DOS / INTERN"\n\n\n\n  @ DOS / INTERN:\n\n\n Hier stellen Sie ein, ob das Kommando ein @{"DOS-Kommando" LINK dos_kommando} oder ein\n @{"IntuiLhA-Internes" LINK interne_kommandos} Kommando ist.\n\n\n\n@ENDNODE\n@NODE t_synch "@ Synchron / Asynchron"\n\n\n\n  @ Synchron / Asynchron:\n\n\n Hier legen Sie fest, wie ein Kommando gestartet wird:\n\n Synchron:  - das nächste Kommando wird erst ausgeführt, wenn dieses\n              zurückgekehrt ist\n            - der Rückgabewert wird beachtet und die Ausführung evtl.\n              abgebrochen (siehe @{"FAILAT" LINK interne_kommandos}).\n            - es wird eine gemeinsame @{"Console" LINK pr_console} für alle Synchronen\n              Kommandos benutzt\n\n Asynchron: - das Kommando wird im Hintergrund gestartet\n            - die Ausführung weiterer Kommandos wird gleich fortgesetzt\n            - der Rückgabewert wird NICHT beachtet\n            - jedes asynchrone Kommando erhält eine eigene @{"Console" LINK pr_console}\n\n\n\n@ENDNODE\n@NODE t_kommando "Kommandostring"\n\n\n\n  In diesem Stringgadget können sie nach Anwahl eines Kommandos oder\n  des Gadgets @{"Neues" LINK t_neues} den Kommandoaufruf eingeben.\n  Dies kann entweder ein @{"DOS-Kommando" LINK dos_kommando} oder ein @{"internes Kommando" LINK interne_kommandos} sein.\n\n\n@ENDNODE\n@NODE interne_kommandos "Interne Kommandos"\n\n\n\n  IntuiLhA besitzt eine Reihe eingebauter Kommandos. Diese werden immer\n  synchron abgearbeitet!\n\n  Wenn Einstellungen geändert werden (z.B. FAILAT, REQTITLE), dann gilt\n  dies NUR für die momentane Kommandoliste!\n\n\n  Kommandos:\n ~~~~~~~~~~~~\n\n    ECHO <text> :\n\n  Gibt <text> auf Console aus.\n\n  BEISPIEL:  ECHO Hallo, ließ mich!\n\n\n    FAILAT <nummer> :\n\n  Stellt ein, ab welchem Rückgabewert von Kommandos die Ausführung\n  abgebrochen wird. Voreinstellung ist 1.\n\n  BEISPIEL:  FAILAT 21\n\n\n    REALLY <text> :\n\n  Öffnet einen Requester mit "Okay"- und "Abbruch"-Gadgets und dem\n  Text <text>. Bei "Okay" wird fortgefahren, bei "Abbruch" wird die\n  Ausführung abgebrochen.\n  Dies ist für Sicherheitsabfragen gedacht.\n\n  BEISPIEL:  REALLY Wollen Sie wirklich fortfahren?\n\n\n\n    REQTITLE <text> :\n\n  Stellt die Titel des nächsten Datei/Stringrequesters ein (nicht für\n  REALLY). REQTITLE kann mehrmals hintereinander angegeben werden.\n\n  BEISPIEL: REQTITLE Datei anwählen...\n            REQTITLE Neuer Name...\n            rename @{"{rf}" LINK platzhalter} {rf}\n\n\n    SHOW <text> :\n\n  Gibt <text> in der Statuszeile aus. Die Ausgabe wird von IntuiLhA nach\n  beendeter Ausführung nicht überschrieben.\n\n\n@ENDNODE\n@NODE dos_kommando "DOS-Kommando"\n\n\n\n  Ein DOS-Kommando wird wie im CLI ausgeführt. Es kann entweder\n  @{"synchron oder asynchron" LINK t_synch} gestartet werden.\n\n  Im Kommandoaufruf können Sie die @{"IntuiLhA-Platzhalter" LINK platzhalter} verwenden.\n  {fi} beinhaltet hier das anzuzeigende Datei.\n\n  Um Ein- und Ausgaben von der eingestellten Console umzuleiten, benutzen\n  Sie ''<EINGABE'' und ''>AUSGABE'':\n\n  Beispiel:     type <>con:0/0/640/100/IO-Console {fi}\n                xyz <>NIL: ar gu men te\n\n\n\n@ENDNODE\n@NODE platzhalter "Platzhalter in DOS-Kommandos"\n\n\n\n  In DOS-Kommandos kann man folgende Platzhalter definieren:\n\n\n     {ar} Archivname: Der Name der aktuellen Archives wird eingesetzt. Ist\n          ~~          keines @{"geöffnet" LINK m_archiv_oeffnen}, wird mit einer Fehlermeldung abge-\n                      brochen.\n\n\n     {fl} Filelist :  Der Name der @{"temporären Datei" LINK pr_temp_datei}, in der die Namen aller\n          ~   ~       @{"selektierten" LINK m_selektion} Dateien abgelegt sind, wird eingesetzt.\n                      Falls keine Einträge angewählt wurden, wird mit einer\n                      Fehlermeldung abgebrochen.\n\n\n     {nf} Number of files:  Anzahl der @{"selektierten" LINK m_selektion} Dateien als Zahl.\n          ~         ~\n\n     {op} Options :   Der von IntuiLhA generierte @{"Optionenstring" LINK optionenfenster} für LhA\n          ~~          wird eingesetzt.\n                      Er wird momentan immer für den @{"Modus EXTRACT" LINK o_full_path} erstellt.\n\n\n     {co} Console :   Das eingestellte @{"IO-Consolefenster" LINK pr_console} wird eingesetzt.\n          ~~\n\n     {pr} Printer :   Der eingestellte @{"Drucker" LINK pr_drucker} wird eingesetzt.\n          ~~\n\n     {lh} LhA :       Der eingestellte @{"Archivierer" LINK pr_archivierer} wird eingesetzt.\n          ~~          Benutzen Sie diesen Platzhalter, da LhA entweder mit\n                      oder ohne (wenn @{"LhA resident" LINK pr_lha_resident} ist) Pfadangabe\n                      gestartet werden muß.\n\n\n     {rf} Request file : Öffnet einen Filerequester und setzt die gewählte\n          ~       ~   Datei ein. Bei Anwahl von CANCEL wird mit einer\n                      Meldung abgebrochen.\n\n\n     {ra} Request archive : Öffnet einen Filerequester mit dem eingestellten\n          ~       ~   @{"Filter" LINK pr_filter}, damit nur Archive angezeigt werden.\n                      Bei Anwahl von CANCEL wird mit einer Meldung\n                      abgebrochen.\n\n\n     {rd} Request dir : Öffnet einen Verzeichnisrequester und setzt den\n          ~       ~   Pfad mit '':'' oder ''/'' endend ein. Bei Anwahl von\n                      CANCEL wird mit einer Meldung abgebrochen.\n\n\n     {rs} Request string : Öffnet einen Textrequester und setzt das\n          ~       ~   Eingegebene ein. Es MUß ein Text eingegeben werden,\n                      sonst wird abgebrochen, wie bei Anwahl von CANCEL.\n\n     {rse} Request string empty : Öffnet einen Textrequester und setzt das\n           ~       ~      ~       Eingegebene ein. Es wird auch ein Leer-\n                      string akzeptiert. Bei Anwahl von CANCEL wird mit\n                      Meldung abgebrochen.\n\n     {fi} File :      Der aktuelle Dateiname wird eingesetzt. Dieser Platz-\n          ~~          halter kann nur bei den Anzeigefunktionen benutzt\n                      werden.\n\n\n   BEACHTEN SIE BITTE:  Die eingefügten Texte werden NICHT automatisch in\n                        Anführungszeichen gesetzt! Dies könnte nämlich\n                        Probleme geben:\n\n                        @{"@" LINK klammeraffe}{fl}   ---> @"IntuiLhA.runtime"  wäre falsch\n                        "@{"@" LINK klammeraffe}{fl}" ---> "@IntuiLhA.runtime"  wird akzeptiert\n\n                        Deshalb müssen Sie ihre Anführunszeichen selbst\n                        setzen. Aber warum überhaupt? Deshalb:\n\n                        {rd}    --->  Ram Disk:    würde als ZWEI Argumente\n                                                   interpretiert.\n                        "{rd}"  --->  "Ram Disk:"  wird wie gewollt für ein\n                                                   Argument gehalten\n\n                        Setzen Sie deshalb möglichst alle Dateien und Pfade\n                        in Anführungszeichen!\n\n\n                        Falls die expandierte Kommandozeile 500 Zeichen\n                        überschreitet, wird mit einer Fehlermeldung abge-\n                        brochen.\n\n\n@ENDNODE\n@NODE beispiel_kommandos "Beispiele für Kommandoaufrufe"\n\n\n  BEISPIEL #1 für Dateityp Exe (ausführbares Programm):\n\n     @{"REQTITLE" LINK interne_kommandos} Argumente eingeben...\n     @{"{fi}" LINK platzhalter} @{"{rse}" LINK platzhalter}\n\n\n  BEISPIEL #2:   (löscht Datei)\n\n     @{"REQTITLE" LINK interne_kommandos} Datei zum LÖSCHEN auswählen...\n     delete @{"{rf}" LINK platzhalter}\n\n\n@ENDNODE\n\n','\n',char(10)),NULL,'auto-added',114070,7,0,NULL,NULL,'lsd_intu','scan',1780048582);
