INSERT INTO door_catalog VALUES('lsd_more','LSD-MORE.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LSD-MORE.LHA','AddPart','XIM','AddPart',NULL,'El','LSD','O-----/o  |---.--/   ___________    o\-----O |    //   |___|\/\___    o\/    |    \\    : :   //    |     \    |    \\    |     \\   |',replace(':      /\_        /\_______________/\      :\nO-----/o  |---.--/   ___________    o\-----O\n|    //   |___|\/\___    o\/    |    \\    :\n:   //    |     \    |    \\    |     \\   |\nO---\\____|_____/__________/__________ /---O\n|    \|  MoreCLI 1.2 by El Pedro/LSD |/    |\n:        (A selection of CLI tools)        :\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                     