INSERT INTO door_catalog VALUES('lsd_nuah','LSD-NUAH.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LSD-NUAH.LHA',NULL,'XIM','<--. ------------- ------------------------.',NULL,NULL,'LSD','_/¦  _/\___/\    PRESENTS: NuAH v1.o Beta ¦ \ |  \ __/\ .\   An /X Door which handles | / |_ /_.¬\/ | \   your New User Accounts  |',replace('<--. ------------- ------------------------.\n _/¦  _/\___/\    PRESENTS: NuAH v1.o Beta ¦\n \ |  \ __/\ .\   An /X Door which handles |\n / |_ /_.¬\/ | \   your New User Accounts  |\n/  l ¬\ ¦  \ l  \ Keep Leechers, Lamers an :\n\____ /___ /___ / Layabouts from your 88S! ¦\n<- -\/---\/- -\/[-dL!-]- --12-Feb-96-- - --''\n','\n',char(10)),'NuAH.GUiDE',replace('@DATABASE "©"\n@$VER:© v1.o\n@AUTHOR "©"\n@FONT topaz.font 8\n@WORDWRAP\n\n@NODE MAIN "  [N]ew [u]ser [A]ccount [H]andler v1.o Beta v1.o © cYBER/LSD 1996!"\n\n                ___     |___  ___  __   __ .--   |    __ __|\n               (___(___||___)(__/_(    (__)|-    |__ _) (__|_\n                -------''                   ''\n                              p R E S E N T s\n\n                 [N]ew [u]ser [A]ccount [H]andler v1.o Beta\n \n                           © cYBER/LSD 12/02/96\n\n                              @{b} GENERAL iNDEX @{ub}\n\n                             @{"  Introduction  " link iNTRO}\n                             @{"  Requirements  " link REQUiREMENTS}\n                             @{"  Arc Contents  " link CONTENTS}\n                             @{"  Installation  " link iNSTALLATiON}\n                             @{"  Config File!  " link CONFiG}\n                             @{"  Bug Reports?  " link DOH}\n                             @{"  Distribution  " link DIST}\n                             @{"  ·Disclaimer·  " link DISCLAIMER}\n                             @{"  ···Greets···  " link GREETS}\n                             @{"  ··Updates?··  " link BOLLOX}\n@ENDNODE\n\n@NODE iNTRO "iNTRODUCTiON"\n                    \n                             .--------------.\n                             | iNTRODUCTiON |\n                             `--------------''\n\n            [N]ew [u]ser [A]ccount [H]andler (NuAH for SHOrt)\n               is just what the title of the door implies!\n\n                   * * * THiS iS A BETA VERSiON! * * *\n\n                  * * * SO GiMMiE FEEDBACK Y''ALL! * * *\n\n                * * * It handles NEW USER Accounts! * * *\n\n\n     When you allow a NEW USER onto your Board, giving them normal axis\n     after their initial period in the New User AreA (where most SysOps\n     usually do a check on the new prospect in question) this door will\n     basically check that they are NOT Leechers, Lamers or Layabouts ;)\n \n     If your NEW USER doesn''t UPLOAD the requested amount of Bytes then\n     this door will (all configured by the SysOp) either warn the LAMER\n     or take action by altering the PRATT iN QUESTiON''s Account (Yeah!)\n \n     You (SysOp) can totally configure this Door to your demented needs\n\n     This Door does (or can do, depending on your mood!) the following:\n\n      * TELLS THE NEW USER TO UPLOAD A MiNiMUM AMOUNT OF BYTES\n      * GiVES THE NEW USER A CERTAiN AMOUNT OF CALLS TO COMPLY\n      * GiVES WARNiNGS TO THE NEW USER EACH TiME HE/SHE/iT CALLS\n      * GiVES THE NEW USER HiS/HERz/iTz STATS etc.\n      * LOGS THE USER OFF iF HE/SHE/iT FAiLS TO COMPLY WiTH YOUR RULES\n      * SETS THE NEW USER ACCOUNT BACK TO LAMER LEVEL\n      * SKiPS USERS THAT YOU KNOW, i.e LOCAL YOBS or ELiTES (Whatever)\n      * WRiTES & RECORDS ALL ACTiViTiES TO YOUR BBS CALLERSLOG\n      * MAKES L0VE TO YOU (Erm? Ahem) ETC ETC ETC YAWN...\n   \n\n                             @{"Config File!" link CONFiG}\n                             @{"Requirements" link REQUiREMENTS}\n\n@ENDNODE\n\n@NODE REQUiREMENTS "REQUiREMENTS"\n\n                            .--------------.\n                            | rEQUiREMENTs |\n                            `--------------''\n\n\n    * Doh! A Mighty Miggy would help!\n    * At least Workbench 2.01\n    * /X correctly installed with all necessary libs to run this door\n      (What no libs? Tough!)     \n    * A good sense of humour (if you haven''t got one then you have no\n      nOoOo place in Comms.\n    * The Numbers of ALL LSD Boards worldwide.\n    * A 88S with a funky name! Any 88S with a name related to the mob \n      is as LAME as ** ****.\n\n                  Click the Button... @{"Arc Contents" link CONTENTS}      \n@ENDNODE\n\n@NODE CONTENTS "ARCHiVE CONTENTS"\n\n                        .------------------.\n                        | ARCHiVE CONTENTS |\n                        `------------------'' \n\n  Listing of Archive ''LSD-NuAH.LHA'':\n\n  * CRAPPy BBS ADDS THAT WASTe A LOTA HD SPACE DOh! *\n\n  BBS:Commands/SYSCmd/NuAH.info\n\n\n  DOORS:LSD-TOOLz/NuAH/NuAH.GUiDE    (This Guide)\n\n                       NuAH          (Size: 18306, Optimised Rexx so you can\n                                                   check for backdoors!\n                                                   Don''t rip, I''ll find out!\n\n                       NuAH.CFG      (NuAH''s Configuration File)\n\n  I recommend that you check the NuAH file size to that of the above!\n\n  If the size doesn''t match then the NuAH Optimised Arexx file may have been\n  tampered with in some way or may been infected with a virus.\n  \n          You should avoid using this /X Door if you are uncertain!\n  \n  The original (un-hacked) Arexx Version is available from me and all LSD\n  BBS/Distribution sites... see BUG REPORTS SECTiON.\n\n                Click the Button... @{"Installation" link iNSTALLATiON}\n@ENDNODE\n\n@NODE iNSTALLATiON "iNSTALLATiON"\n\n                           .--------------.\n                           | iNSTALLATiON |\n                           `--------------'' \n\n   You MUST have these commands in your startup-sequence or user-startup\n\n   -------------8<------------------------------------------------------\n                    Assign >NiL: REXX: SYS:REXXC\n                    Rpstart >Nil:\n   -------------8<------------------------------------------------------\n\n                      Your system is now Arexx ready.\n\n    Now it''s quite simple, just copy all the files to your directories!\n\n    To actually run the door you must use /X''s MCi Commands in your logon\n    script(s).\n\n    i.e BBS:NODE/SCREENS/LOGONxxx.TXT, where xxx is the user axis level.\n\n    Edit your LOGONxxx.TXT so that somewarez it reads:\n\n  -------------8<------------------------------------------------------\n\n  ~CC_NuAH|\n\n  -------------8<------------------------------------------------------\n\n               Then all you have to do is edit the ''NuAH.Cfg'' File\n\n                     Click the Button... @{"Config File!" link CONFiG}\n\n@ENDNODE\n\n@NODE CONFiG "CONFiGURATiON"\n\n                         .--------------------------.\n                         | CONFiGURATiON FiLE Ooer! |\n                         `--------------------------'' \n\n                         Wahey.. the ''NuAH.cfg'' file!\n   \n    The Config File is TOTALLY CONFiGURABLE to your demented needs\n            (that''s why it''s called a config file hehehehic!)\n\n    It''s all pretty simple, but just for SysOp''s with low i.Q''s...\n\n    I have included an example config file, it should loOk like this...\n\n   -------------8<------------------------------------------------------\n   5\n   N\n   10\n   1000000\n   SYSOP\n   COSYSOP\n   LSD\n   NVX\n   ELiTE\n   NEWUSER\n   10\n   5\n   -------------8<------------------------------------------------------\n\n\n\n   KEY TO CONFiG:\n   =^=^=^=^=^=^=\n\n   LiNE 1... NUMBER OF CALLS BEFORE THE NEW USER RECEiVES A SERiOUSiSH?\n             WARNiNG WiTH REGARD TO hiS/HERz/iTz STATS!  i.e: USE ''5'' & \n             THE LAMER WiLL iN QUESTiON WiLL RECEiVE A PASSiVE WARNiNG!\n             (N.B: ON THE FiRST CALL, THE USER WiLL BE WELCOMED TO YOUR\n             BBS & WiLL iNFORMED OF WHAT HE/SHE/iT MUST DO TO GAiN FULL\n             AXiS TO YOUR BOARD).\n  \n   LiNE 2... DROP CARRiER ON THE USER iF THEY DOn''T TAKE YOUR WARNiNGS.\n             ''Y''=DROP CARRiER ON THEM AND SET THEM BACK TO LAMER LAND.\n             ''N''=SET THEM BACK TO LAMER LAND, BUT NO DiSCONNECT.\n\n   LiNE 3... THE MAXiMUM AMOUNT OF CALLS THE USER CAN MAKE BEFORE BEiNG\n             SENT TO LAMER LAND i.e USE ''10'' then ON CALL ''9'' THE LAMER\n             WiLL BE GiVEN A FiNAL WARNiNG!, iF iGNORED THEN ON CALL 10\n             THE TWAT WiLL BE SET BACK.\n\n   LiNE 4... THE MiNiMuM AMOUNT OF BYTES THE NEW USER HAS TO PUMP UP TO\n             THE BBS. i.e 1000000 (1mb, up2u!).\n\n   LiNE 5... ACCESS AREA TO SKiP THiS /X DOOR, i.e ELiTE, PRiVATE...\n             USERS GiVEN THiS AXiS AREA iN THEiR ACCOUNT WiLL NOT BE\n             BOTHERED BY THiS DOOR AT ALL.\n\n   LiNE 6... SAME AS LiNE 5.\n\n   LiNE 7... SAME AS LiNE 5.\n\n   LiNE 8... SAME AS LiNE 5.\n \n   LiNE 9... SAME AS LiNE 5.\n\n   (SO YOU HAVE A MAX. OF 5 AXiS AREAS THAT WiLL SKiP THiS DOOR)\n\n\n   LiNE 10.. THE NEW USER WiLL BE SET BACK TO THiS ACCESS AREA iF\n             HE/SHE/iT FAiLS 2 UPLOAD THE MiNiMUM AMOUNT OF BYTES\n             AS DEFiNED iN LiNE 4, i.e NEWUSER or LAMER\n\n   LiNE 11.. THE SECURiTY LEVEL TO WHiCH THE NEW USER WiLL BE SET\n             BACK TO, i.e 10 or 5 or whatever you decide.\n\n   LiNE 12.. THE TiME LiMiT THAT YOU WANT THE NEW DWEEb TO BE SET\n             BACK TO, i.e 10 or 5 mins etc.\n\n\n   Argh!\n\n   iN SH0RT.. just for the impatient and for peeps that can''t read\n              and because this door is so obvious...\n\n----------------------8<-----------------------------------------------------\n5          ; Number of Calls before a *WARNiNG* is sent to the New User\nN          ; Log User off if when a Set back Occuers (Y or N)\n10         ; Number of Calls before a user is Set back to New User Level\n1000000    ; Minimum Bytes the New user needs pump before full axis\nSYSOP      ; Area.1 to bypass this LSd /X dOor - eDiT tHiS\nCOSYSOP    ; Area.2 to bypass this lSd /X dOor - eDiT tHiS\nLSD        ; Area.3 to bypass this Lsd /X D00r - eDiT tHiS\nNVX        ; Area.4 to bypass this lSd /X DoOr - eDiT tHiS\nELiTE      ; Area.5 to bypass this LSd /X DoOr - eDiT tHiS\nNEWUSER    ; Axis Area to the set the user back to (Max 10 Chars)\n10         ; Lamer/New user Security Level to be set back to (Max. 10 Chars)\n5          ; Time limit (in minutes) to be set back to\n----------------------8<-----------------------------------------------------\n\n                     Click the Button... @{"BUG REPORTS" link DOH}\n\n@ENDNODE\n\n@NODE DOH "BUG REPORTS"\n\n                        .--------------------------.\n                        | BUGS? DOH! i HATE THEM :(|\n                        `--------------------------'' \n\n     Erm, if you have all of the necessary libraries & files installed\n     correctly then this door should NOT cause any problems at ALL ;)\n\n        But then again, I was wasted when I wrote the door... hic..\n\n     If there are any bugs please feel free to mail me on most cool U.K\n     boards...\n\n     You can definately reach me at:\n\n                   Soap City        +44(0!)-HUNT-ME-DOWN (2 NDZ)\n                   The Welsh Coast  +44(0!)-TRY-N-FiNDiT (2 NDZ) \n\n                   13th Hour        +44(0!)704-505-845 (2 NDZ)\n                   Digital Candy    +44(0!)912-325-527 (5 NDZ) \n\n\n      Other Boards you might just reach me at are:\n\n                   Burger Bar       +44(0!)-PRiVATE!!!\n                   Cryogenics       +44(0!)-PR!VATE!!!\n                   Phantasm         +44(0!)-PRiVATE!!!\n\n                   & Other Cool Boards too Numerous to mention! ;)\n\n                  Click the Button... @{"Warm Greets!" link GREETS}\n\n\n@ENDNODE\n\n@NODE GREETS "WARM GREETiNGS..."\n\n\n               .,:::::,._                       __     _\n   _          /¯__ __ ¯_ \______