INSERT INTO door_catalog VALUES('lsd_nup','LSD_NUP.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LSD_NUP.LHA','nup','XIM','LE-win5-96.exe',NULL,'SuBhUmAnZ/LSD','LSD','\   / /  __//     \ Present a XIM door /  /  \   \ /  /\  \  for /X V3.00+ /  /__ _\_  \  /_/  / NUP Finder V1.0',replace(' _____  _____ _____ \n \   / /  __//     \ Present a XIM door\n /  /  \   \ /  /\  \  for /X V3.00+\n/  /__ _\_  \  /_/  / NUP Finder V1.0\n\____//_____/______/ by SuBhUmAnZ/LSD\n Displays current NUP for each node.\n No more comments from users asking\n what the NUP is for the current month.\n','\n',char(10)),'nup.doc',replace('               .. _ __ ___ _____  _____ _____ ___ __ _ ... \n               ... ___ __ _\   / /  __//___  \ _ __ ___ .. \n               .. _ __ ___ /  /  \   \ /  /\  \ ___ __ _ . \n               . ___ __ _ /  /__ _\_  \  /_/  /_ __ ___ .. \n                .. _ __ ___\____//_____/______/___ __ _ ...\n                     Present a XIM door for /X V3.00+ \n                     NUP Finder V1.0 by SuBhUmAnZ/LSD\n                  Shows ya the current NUP for each node \n                             The Documention!\n-----------------------------------------------------------------------------\nI TAKE NO RESPONSIBILIY FOR BACKDOORS, OR FUCKED DATA BY THE USE OF THIS \nPROGRAM.  I DID NOT PUT ANY BACK DOORS IN THE CODE.  HOPEFULLY NO ONE \nDECIDES TO DO SO!  IF YOUR NOT SURE, GET IT FROM AN LSD BOARD!\n\n-----------------------------------------------------------------------------\n\n\nCopy NUP and NUP.Config into a doors:nup/\n\nEdit NUP.Config to suite your needs.  \n\nCopy NUP.info into your bbscmd directory.\n\n\nDescription of door:\n--------------------\nI wrote this little door because i waz tired of getting shitloads of mail \nasking what my current NUP waz.  It reads the tooltypes from your NODEx.icon\nand displays the NEWUSER_PASSWORD= Tooltype to the user.  It will display\na NUP for each node!  I did this cause it is possible for a sysop to have a\nNUP for each node.  Not sure why you would wanna do that, but the possibility\nexists.  L8r...... \n\n\nIf you have any suggestions or would really like to see something added, \ncontact me on a LSD BBS.  Some BBS''s that i hang out on are, Diabolical \nSabotage, Skull Buggery, Mass Media, Tempest Thunderstorm, and /X World HQ.   \n\nGreets to:   (In no perticular order)\nALL the LSD members, including..... \nDr Vinculum (My other partner in crime around here)\nPazza (I have to greet him he is the leader...:) )\nFish (Busy as fuck l8tly?  Where ya been?)\n2-Cool (His name sez it all!)\nMub (What are ya getting me?  :) )\nVan Damme (Sorry to see you left the scene!  Good Luck!)\nMerchant Man (The master of H/P!)\nBytemaster (The man behind the BBS) \nMaltese Falcon (Gr8 Friend & Excellent Coder! :) ) \nRacer-X (Friend from the CCI days :) )\nRoach (Long time friend and chum :) )\n.44 Magnum (Just plain k00l...)\nGambit (The best gamer around, i sed gamer not lamer :) )\nThundor (An IBM lamer that will never see this mooohahahahahha)\n\nAnd most importantly i send a big wet kiss to DoMiNo!\n\nLSD is the k00lest of the k00l thanx for all the support guys.....\n\nALL MY USERS, you also know who you are!\nand anyone else i forgot........\n\n \nL8r, \n-SuBhUmAnZ/LSD\n \n','\n',char(10)),NULL,'auto-added',14179,3,0,NULL,NULL,'lsd_nup','scan',1780048582);
