INSERT INTO door_catalog VALUES('lsd_add','LSD_ADD.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LSD_ADD.LHA','add','XIM','add',NULL,'fAITH/lSD','LSD','/  /\ /  ______ \_ /  /_//___  /  /  /\ .-----------/  /  /     /  /  / /-----------.',replace('               ___   _________               \n              /  /\ /  ______ \_             \n             /  /_//___  /  /  /\            \n.-----------/  /  /     /  /  / /-----------.\n|          /_____/_____/_____/ /            |\n`----------\_____\_____\_____\/ZMb----------''\n   pRESENTS sTAR aDDER v1.0 bY fAITH/lSD','\n',char(10)),'Star.Doc',replace('	·+--------------------COMES-DIRECTLY-FROM--------------------+.\n	.|F  /\ __  ____  __/\_____  /\_________________/\_____  /\ F|.\n	.|A // V ¬\/   ¬\/    \_  ¬\/ ___/\__  _/  _____   ¬\ ¬\/ \\A|.\n	.|I/      \\ ¦  \\  ¦ \\ ¦  \__.¬\  / ||   _)_|¬  ¦ /\_   _/I|.\n	.|T\  \ / // ¦  //  | //    ·\¬¦ \\/  ·|     ¬\| \  \_||  | T|.\n	.|H \__X ·/\____/\\ |_/ _|___/__ //\___|\___ //__|\\ /|__ | H|.\n	.|-----·\/·------·\/··\/·------·\/·--------·\/·---·\/·--·\|--|.\n	.| /|     _________                                          |.\n	.|/|| _  /  _____ ¬\    ** Amiga Ibm Hpa Sections     **     |.\n	./ ·|/¬\ \__. \/ | \\   ** Amiexpress 3.x             **     |.\n	.\  ¦  \\/ ¬¦ \\ ¦  ·\  ** 68030 + 68882 40 Mhz       **     |.\n	.|\_____/\\ ___/ ____/  ** 1 Giga + 212 Mb On-Line    **     |.\n	.|        \/   \/                                            |.\n	.|     Monastery LSD IDS ++39-41-527-4664 HST Dual 21600     |.\n	.| NUP:X-RAY  Sysop -» FAITH/LSD «- Cosysop -» THE DOCTOR «- |.\n	.|                                  Cosysop -» Lobo «-       |.\n	 +-----------------------------------------------------------+ \n \n                              Star Adder V1.0\n                              ~~~~~~~~~~~~~~~\n\nPURPOSE:\n~~~~~~~~\n\n  - This program permitts you to add hundred of texts file in your \n    LHA, LZH, LZA, Arc Archives. It is able also to add a "*" in to\n    the Archive: in this way when a user is uncompressing the "*" file\n    will be shown to him, and he will be OBLIGHED to see it. \n    The really interesting thing of the "*" file is that it won''t be\n    uncompressed to your Destination Direcotry but only redirected\n    to the Screen\n    The Start symbol is the same of SCR: Device !!!!\n\n REQUIREMENTS:\n ~~~~~~~~~~~~~\n   - AmiExpress 1.x 2.x 3.x\n\n\n INSTALLATION:\n ~~~~~~~~~~~~~\n   - Copy the ADD file contained in the Star/C directory to your C: assigned\n     Directory\n   - Copy the Star/FCheck directory to BBS:FCheck Directory\n\n   ->>>>>> Assign the TEST: directory to a Directory in your harddisk that \n           will contain the Text file you want to add to the archive, AND\n           Do NOT FORGET to rename one of this as "*"\n\n\n BUG REPORT & SUGGESTIONS:\n ~~~~~~~~~~~~~~~~~~~~~~~~~\n  It is possible that a mistake will occur .... I''m not God yet \n  PLEASE if ya have any suggestions or Comments please leave a message \n  on my Board:\n \n      **  MONASTERY     +39-(0)41-5274664  Dual Standard 21.600 - ITALY **\n  \n  Or if ya cannot call Skull Buggery, Diabolika Sabotage, Planet-X .\n  And leave a message to FAITH\n\n\n REGISTRATION:\n ~~~~~~~~~~~~~\n - Please if You use this program let me know i''d like to kow how many \n   Sysops use this tool!\n - The registration is completely free of course, You will have your name\n   in the ADD WorkScreen\n\n GREETINGS:\n ~~~~~~~~~\n  - To My GirlFriend .... She is so patient with me. Smack\n  - To Cooey  ( hi bro, hope to catch ya here in italy in July!!)\n  - To Fish   ( You are a good friend! )\n  - John Yaya (He test all my /X tools !! Poor guy! ;)  )\n  - Lobo ( YO man , you are here this time too! hahaha )\n  - Eddie The Head (You are here too!! )\n  - To The Biker ( do you always drink something for me?!!? )\n  - The Doctor ( This is the Teacher!!! )\n  - To all LSD guys.\n \n That''s all folks! See ya on the next /X Tool .\n Stay Tuned!\n\n				- Faith/LSD ''94 -\n','\n',char(10)),NULL,'auto-added',15870,2,0,NULL,NULL,'lsd_add','scan',1780048582);
INSERT INTO door_catalog VALUES('lsd_vdrq','LSD_VDRQ.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LSD_VDRQ.LHA','Copy','XIM','Copy',NULL,'VAN','LSD',NULL,replace('VD REQUESTS BY VAN DAMME VERSION 3.0\n','\n',char(10)),'VDRequest.Doc',replace('\n\n\n\n=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n                     - The Time For Difference Is Now -\n\n                       © FreakWare & LSD 1993 Present\n\n      /\  /\___/\___  ____/\__  /\ ______/\___/\_______  /\____   ___/\\n     / / /\  _ \  _ \/  ___/_ \/ // /  ___/ ___   __  /  \____ \ /  _ /\n     \ \/ /  ¬ /  ¬ /  __/  ¬ / X/ /  __/__  \/  /  \/     \__  \\  ¬ \\n      \__/\___/_/\__\___/\___X____/\___/\____/__/           \___/o\___/\n\n                        VDRequest v3.0 By Van Damme\n\n                     - The Time For Difference Is Now -\n=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n\n\n\n\n\n\n © FreakWare Is A Label That Was Created To Bring  Quality And Excellence To\n The Sysops Around The World. All Products Under This Label Have Been Tested\n And Written To Unsure You Of Some Of The Best Ami-Express Utilities Around.\n Only Quality Products Will Carry The FreakWare Stamp. So Be On  The Lookout\n For Products With  This Label And  Be Assured They Will Be  Something Worth\n Looking Into. For Info On How To  Register Your Utilities Under This Label,\n Please See The Section On Registering Located Near The End Of The Document.\n\n\n\n\n\n\n=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n\n » 1. Index «\n\n 1  . Index\n 2  .. Copyright      \n 3  ... Disclaimer\n 4  .... Introduction                  \n 5  ..... System Requirements\n 6  ...... Installation\n 7  ....... Preferences\n 8  ........ Door Features\n 9  ......... Main Menu\n 9a .......... Main Menu Option 1 - Enter A Request\n 9b ........... Main Menu Option 2 - Answer A Request\n 9c ............ Main Menu Option 3 - View The Request List\n 9d ............. Main Menu Option 4 - Remove A Request\n 9e .............. Main Menu Option 5 - Edit The Request List\n 9f ............... Main Menu Option 6 - Edit Request Stats\n 9g ................ Main Menu Option 7 - Exit Program\n 10 ................. Request Answered Approval Record Screen\n 11 .................. Request Answered Deletion Record Screen\n 12 ................... Callerslog\n 13 .................... Sysop Pointers And Advice\n 14 ..................... Future Developments\n 15 ...................... Credits\n 16 ....................... FreakWare Registration\n 17 ........................ History\n 18 ......................... Greetings And Thanks\n 19 .......................... Last Words\n\n=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n\n » 2. Copyright «\n\n Since This Program Is Licensed And Copyrighted Under © FreakWare You Are\nHeld Responsible To Fulfill Conditions 1 Through 4 When Spreading Or Using\nThe Utility. The Rest Of The Conditions Are Completly Optional.\n\n 1. The Archive Is Freely Distributable As Long As All The Original Files\n    (Including Any Docs, Program Files, Or Examples) Are Kept Within It.\n 2. Any Modified Versions Of The Program Are Not To Be Spread Or Used For \n    Anything Other Then Personal Use. Any Modifications To The Program\n    Are However Stronger Discouraged And You Should Get Ahold Of The\n    Original Coder To Have Them Made For You.\n 3. This Program Can Not Be Sold In Any Shape Or Form.\n 4. You Must Contact The Original Coder And Get His Permission Before You\n    Can Include This Program On A Utility Or Disk Pack Of Any Kind.\n\n 5. Have sex with a female blond teenager and scream your favourite cricket\n    players name twice.\n 6. Have sex with a female teenager with long dark hair and scream "Nuts" \n    backward with an extra accent on the "s".\n 7. Watch 17 shows of Ren & Stimpy (Commercials included) while standing\n    on your left foot only.\n 8. Listen to any of "Alice In Chains", "Metalica", "Soundgarden" , "Pearl\n    Jam" or "Danzig" songs backwards and write down (In black ink) any death \n    chants or references to satan you might hear.\n 9. Shave your head bald and draw a large bullseye on it and proceed to the\n    nearest pub or bar where there is a dart tournament being held.\n 10. Go down to the nearest movie theater and chant "Pee-Wee, We love you!"\n     until:\n     a) your given free movie passes\n     b) your given a free box of jube-jubes\n     c) your given a free box of kleenex\n     d) your thrown onto the street\n 11. Mix all the alcohol in your house into the largest glass you can find,\n     add a tablespoon of milk (Does a body good) and drink it straight with\n     no stops while gargaling out the last three digits of your girlfriends\n     phonenumber (If you have none, any number from the phonebook will do).\n 12. Have sex with a lifesize picture of Teresa Roncon, Natalie Merchant,\n     Cory Everson, or any other photograph (Must be lifesize!) that you\n     find attractive while eating a bar of soap.\n 13. Call up the local phone operator and tell her/him you find their feet\n     very sexy.\n 14. Drink large amounts of gasoline and tie yourself to the first person\n     you see. Then threaten to light up a smoke if they don''t lower the \n     price of car bateries.\n 15. Spraypaint your face with a lardish greenish jello color and tell\n     everyone you see that it''s very contagious.\n 16. Turn the clocks in your house 3 hours back and tell your boss you\n     thought you finally got to work earily (Replace with teacher if your\n     a student).\n 17. Attach the largest cross in your house to a necklace and walk around\n     chanting verses from your favourite bible passage.\n 18. Rent a copy of every movie you have ever hated watching and watch them\n     with a pair of binoculars.\n 19. Tie a playing card to your head, drive down to a casino (Los Vegas have\n     been know to give the best results) and tell any female dealer wearing\n     black you aren''t cheating, but simply using your rights to speak out\n     against the injustice to the enviroment.\n 20. Tape yourself having sex with a sheep (Cows are fine if you don''t have\n     any sheeps, but no horses please) with socks on and send a copy to the\n     nearest political figure. Note that the socks on the animal are optional\n     if you are right handed.\n 21. Show your teacher/boss your middle finger and explain to them you think\n     that they are number one.\n 22. Read all of Van Damme''s poetry when released in LSD''s Grapevine Issue\n     sixteen.\n 23. Put your clothing on backwards (socks excluded) and walk into every\n     wall you see. When you regain consiousness and awake in a mental ward\n     explain to them it was only a desperate cry to show the world that\n     while clothes can be worn backwards, socks simply cannot be.\n 24. Tape the forward button of your remote control button down and place\n     it in the middle of the floor. (Note - Make sure no one sees you taping\n     it.) Then run around screaming that your converter is possesed by those\n     lovable trolls. (If you don''t like those loveable trolls, then any \n     disney character such as Alladin will work fine).\n 25. Tatoo your name on your forehead so people will never again say, "Who''s\n     that guy?", Or "Who''s your friend?".\n 26. Break your arm and ask the ambulance driver if you can sit in the \n     front.\n 27. Bring a copy of bloodsport to watch in slow-motion on the security\n     cameras as you stand in line at the bank. (Warning, Although any of\n     Van Damme''s movies will also work, do not use Kickboxer as it has been\n     known to promote too much violence in nuns and bank clerks).\n 28. (Note - Before you start this one, remember you need 2 phones hooked up\n     for this one to work. Although it could be more fun with one.) Pick up\n     one of the phones and dial the other one. Then run over to the ringing\n     phone, pick it up and yell, "Get off the phone, I''m trying to make a\n     call".\n 29. By different, be original, and be proud.\n\n=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n\n » 3. Disclaimer «\n\n Van Damme Holds No Responsible As To Any Damages, Lost Girlfriends, Missing\nSocks, Busted Ribs, Swolen Glands, Thinning Hair, Impaired Hearing, Or Any\nOther Social Or Physical Damages Of Any Kind As A Result From This Program.\n \n=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n\n » 4. Introduction «\n\n\n First, before I say another word. Let me explain before you start jumping\naround at the size of the doc. Although this doc is VERY large in size, it\nin no way means you have to go through the entire thing. In the doc is\nthe COMPLETE outline of EVERY option for the new user or those that want\nto make the most out of the door. If you don''t read the doc any further\nthen the installation part, you will still be able to figure out probably\nevery option there is. This is because they are all lined out in a easy\nand simple to use method. So please don''t feel that you have to read \nthe entire thing. If you want to, great, you''ll know ALL of the wonderful\noptions you can use. If you don''t read it all, scan the parts you want\nto know more about. If you hate docs, fool around with the door and learn\nwhat each option does this way. You will probably be able to learn all you\nneed to know from doing this anyway. \n Either way, at least take the time out to scan over the doc quickly to\nsee some or all of the nice options that you can use. It took ALONG time\nto type this doc out and I hate to think that no one will use it. Take\nadvantage of this fully complete doc and learn all you can learn, be all\nyou can be! (:\n\n\n Once again, it''s Van Damme here bringing to your home computer the best\nin utilities for Ami-Express. If you know my utilites, you know they mean\ntop quality and excellence. If you haven''t used one of my utilties before,\nthen pull up and chair and make yourself comfortable. Let''s get to know\neach other better. \n Today''s utility is VDRequest v3.0. While there are currently no other\nsuch utilities as my request door (or at least none that I know of) I \nfelt that v2.3b (or anything below that) wasn''t up to my normal standards \nand that I could improve on it two-fold. And So I did, and here we are.\n This door is the perfect way to keep track of requests that go through your\nboard. The older versions allowed you to keep a list to show to the users\nof all the files that the users have requested. You also had the option\nto remove entries that were unwanted or answered. I have taken this\nconcept quite a few steps further. You will now be able to do such things\nas, have a user enter a request, have a user answer a request, and have\na user delete his request when he''s done with it. This is a simple outline\nof the logic in which the utility works. Of course, there''s alot more to\nit then just that, but we have to start somewhere.\n So if you have a request section or have users that have asked for certain\nolder files from you (which is about 99.9% of us) then get ready to install\nthe next generation of of the best request utility to be released in the\nhistory of our planet. And if I haven''t sold you yet, you have but to run\nthe utility to see what all this talk is about. \n Also, it''s all set up so that''s its easy for a new user to figure out how to\nuse, but still contains more then enough options to keep any one happy.\n\n=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n\n » 5. System Requirements «\n\n Before you all go off saying - Oh no, it''s in arexx, let me explain. I \nknow I said my new utils would be in C, but I do prefer arexx, and I saw\nthat this program needed no real boost in speed. So I left it as is in rexx.\n First off, I have done something I thought I would never do again. This\nis release my source along with the program. I have done this for the \nfollowing reasons:\n\n 1. Compiled arexx doesn''t work on all machines. I want everyone to be able\n    to have this door running on their boards. The arexx source will work\n    on any machine.\n 2. On Accelated machines there is no real great difference in speeds of the\n    compiled vs. source code of this program. \n 3. To make sure everyone sees my code has NO backdoors. My code never has\n    and never will. Some people should take example to this.\n 4. To give people that use arexx to make doors or are still learning arexx \n    a chance to view some of my useful tatics. \n 5. The compiled version is completly huge. Some people don''t want to run\n    300k doors. Most of you have nice systems with plenty of space, but\n    there''s always the few that don''t.\n\n I hope their will be no real idiots out there that will decide to do \nanother little scam like with the VDEdit source. Let''s show that we all have\nsome active braincells out there. I also don''t mind if you use parts of my\nsource for your own programs. After all, we all have to learn from somewhere.\nI just ask a few things if you do. One, to give credit where it''s due.\nAnd second, no complete copies of the source code. I don''t want a \nLAMERequest v1.7 or something like that popping up somewhere. And remember to\nleave my name on it. I DID THE WORK, NOT YOU - Remember That!!!\n Let me talk about the speed of the program for a second. If your amiga runs\non anything higher then a standard 68000, then the speed of the program will\nbe very quick. This door doesn''t need millions of calculations per second,\nor the reading of hugh callerslogs. It''s all set up to handle one thing at\na time, not taking too much on at once to slow things down. If your have\nan accelator you will find that you will be able to run the source or the\ncompiled version and both will be very quick. If you have a standard 68000\nyou are advised to use the compiled version, as you guys need all the speed\nyou can get. \n This program has been tested on Ami-Express versions 3.6, 3.3, and 2.39.\nAlso my beta testers have versions running at these and between as well. \nAll this points down to this. I can almost guarentee that the door will work \non  the version of ami-express you are currently running. So I expect to see\nthis door running on everyboard across the world. No exceptions! (:\n Finally, just in case, this utility is meant as a door for Ami-Express\nBulletin-Board systems. If you don''t have Ami-Express running on your\namiga, then you will have no need for this program.\n\n=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n\n » 6. Installation «\n\n The following is a list of all the files that should be inside of the\nVDRequest archive and what each of them is for.\n\n C/Copy                       : Needed For Door Use\n C/Delete                     : Needed For Door Use \n C/Filenote                   : Needed For Door Use\n C/MakeDir                    : Needed For Door Use \n\n ExampleOutput/Bull50.Txt     : Example Of A Request List\n ExampleOutput/Dir2           : Example Of Effects Of Filelist Options\n\n Libs/Rexxplslib.Library      : Needed For Door Use (Compiled Only)\n\n VDRequest/VDRequest          : Compiled Program File\n VDRequest/VDRequest.Rexx     : Source Program File\n VDRequest/VDRequest.Access   : File For Special Access Option\n VDRequest/VDRequest.Users    : File For Users Not Allowed Option\n VDRequest/VDRequest.Prefs    : Preference File\n\n DeATHRoW.DiSPLaYMe           : My Board Addvertisment\n VDRequest.Doc                : The VDRequest 3.0 Full Documentation\n VDRequest.Upload_Banner      : Upload Text Description\n VDUtils.Txt                  : My Entire Utility Collection Listing\n FreakWare                    : List Of All Registered FreakWare Products\n\n NOTE: If you are an experienced sysop or have installed arexx source or\n       compiled doors before, you will just have to create ''Doors:VDRequest''\n       directory and copy either the source or compiled version over. From\n       here you can install it as any other arexx door. The following\n       installation procedure is just for the beginner or inexperience.\n       Also remember to copy over the VDRequest.Prefs file to the same\n       directory as the program file. Then you can skip to the preference\n       section.\n\n Before I talk about how to install it on ami-express, make sure that\nyou have the following things in order. If you are missing any of the items,\nclear it up before attemping to run the program.\n\n 1. Make sure you have RPStart running in the background. (Compiled version\n    Only). To install this, copy the C:RPStart file from the archive to your\n    C: Directory. Now in your ''S:Startup-Sequence'' or your ''S:User-Startup''\n    just add the line ''RPStart''. This will run the program when you reboot\n    to make sure it''s always running. You can also run it from a shell or\n    cli but you will have to do it manually everytime then.\n 2. Make sure the rexxplus library included is already in your Libs: \n    directory. If not, copy it there from the archives Libs drawer.(Compiled\n    Version only)\n 3. Make sure you have the following command in your C: directory.\n\n     -Copy      (Needed to move over adjusted request lists)\n     -Delete    (Needed to remove temporary work files in ram)\n     -Makedir   (Needed to make the descriptions directory)\n     -Filenote  (Needed to make files freedownloads)\n\n    If you are missing any, copy them over from the archives C: Directory to\n    your own.\n\n 2.x Series\n ¯¯¯¯¯¯¯¯¯¯ \n Installing this door if your running a 2.x version of ami-express (That''s\nany version starting with 2.) is fairly simple. First you must make a\ndirectory inside of your ''Doors:'' called ''VDRequest''. This is similar\nto the way VDEdit works. Once you have made the directory:\n\n                            "Doors:VDRequest"\n\n ..your ready to continue. After making this drawer, you must decide whether\nyou are going to use the source or compiled version of the program. If your\nwondering what the difference is, see section 4 on system requirements. \nNow that you''ve choosen which one you are going to use:\n\n If your using the compiled version, copy the ''VDRequest'' program over to\nthis new directory. If your using the source, copy the ''VDRequest.Rexx''\nfile to this directory. Now copy the ''VDRequest.Prefs'' file over to the same\ndirectory. After this, load up your ''BBS:Commands/BBS.CMD'' file with a text\neditor and add the following line to it.\n\n Using the compiled file:\n\n          11 Spaces In\n-----------------------------------------\n*REQ      RM050DOORS:VDRequest/VDRequest\n-----------------------------------------        \n\n Using the source file:\n\n          11 Spaces In\n----------------------------------------------\n*REQ      RM050DOORS:VDRequest/VDRequest.Rexx\n----------------------------------------------\n\n NOTE: Use only the line inside the brackets. Don''t use the ''11 Space'' or ''-''\n       lines.\n\n The explaination for this command line is as follows:\n\n * : Makes sure that only the extact word ''REQ'' is used, and not ''REQUEST''\n     or ''REQUESTOR''. When you use the star, only an exact match of the\n     door name (In this case REQ) would run the door. If you don''t use the\n     star (Still start the other part 11 spaces in) then you don''t need\n     an exact match. Anything starting with the door name will run the\n     door as well. So if you don''t use the star, whenever you type\n     something starting with REQ it will bring up the door.\n REQ : This is the name of the door as it will be on your board. The users\n       will have to type this name to bring the door up. So on your board,\n       in this case the user would have to type ''REQ'' to load the door. Also\n       see above for variations on this.\n R : This means the door is an arexx type module.\n M : This means the door is able to be run from more then one node at the\n     same problem. If when two people run the door at the same type it\n     causes problems on your board, change it to ''S'' for single node use\n     only.\n 050 : This is the access level that a user will need to be able to load the\n       door up. In this case the user will need an access of 50 or higher       to run the door. Change it according to your access levels on your\n       board.\n Doors:VDRequest/VDRequest      : This is the location of where the program\n           Or                   : file is located. It is the complete path\n Doors:VDRequest/VDRequest.Rexx : to the file.\n\n Once your done adding this line to the BBS.CMD file save the changes in\nyour text editor. Now you should have 2 files, the program and the \npreference file located in the ''Doors:VDRequest'' directory, and your\nBBS.CMD file adjusted for the new door. Now log on your board, and type\nthe door name (REQ if you didn''t change it) and the door should load up.\nIf the door doesn''t load or something seems to go wrong, check the problem\nlist below for possible solutions, and then try to re-install it. If the \ndoor has come up, skip to the preference section.\n\n 3.x Series\n ¯¯¯¯¯¯¯¯¯¯\n Installing this door on a 3.x version of ami-express (That''s any version\nstarting with 3.) is abit different. This is mainly because of Mr. Hodges\nnew method of configuring the bbs program. I would prefer if he went back\nto the older system of configuration, but it''s not my choice. First you must\nmake a directory inside of your ''Doors:'' called ''VDRequest''. This is similar\nto the way VDEdit works. Once you have made the directory:\n\n                            "Doors:VDRequest"\n\n ..your ready to continue. After making this drawer, you must decide whether\nyou are going to use the source or compiled version of the program. If your\nwondering what the difference is, see section 4 on system requirements. \nNow that you''ve choosen which one you are going to use:\n\n If your using the compiled version, copy the ''VDRequest'' program over to\nthis new directory. If your using the source, copy the ''VDRequest.Rexx''\nfile to this directory. Now copy the ''VDRequest.Prefs'' file over to the same\ndirectory. Now you must make an Icon in the ''BBS:Commands/BBSCMD'' Directory\nto match the name of the door as you wish to call it up. If you want ''REQ''\nto load up the door on your board, you would an icon called ''REQ.Info''.\nIf you want the command ''VDRequest'' to load up the door, you would make an\nicon called ''VDRequest.Info'' and so on. Remember this icon is to be made in\nthe above directory , so the icons would be ''BBS:Commands/BBSCMD/REQ.Info'' \nand so on. Once this icon is made, select it on the workbench and pull down\nthe ''Icons'' menu with the right mouse and select the ''Information...'' \noption. Now select the ''New'' option on this new screen to add a tool type.\nYou can click on the different items in the tool type window to edit them,\nor use the ''Del'' option to delete them. Also remember to use the ''Save''\nfeature once your done making the changes. Now after selecting ''New'',\nadd the following items (selecting new again for each item):\n\n LOCATION=Doors:VDRequest/VDRequest\n MULTINODE=Yes\n ACCESS=50\n TYPE=AIM\n\n The explaination for these lines are follows:\n\n LOCATION is the full path to the program. Use ''Doors:VDRequest/VDRequest'' \nfor the compiled version and ''Doors:VDRequest/VDRequest.Rexx'' for the\nsource file. \n MULTINODE is whether you want to be able to access it from more then one\nnode at the same time. Set it to ''Yes'' or ''No''\n ACCESS is the access level to be able to use the door. In this case, it''s\nset at ''50''. Set it at a level where all your users can use the door.\n TYPE is just that. In this case, an arexx door so the ''AIM'' type is used.\n\n Now you should have 2 files, the program and the preference file located \nin the ''Doors:VDRequest'' directory, and your new .Info file adjusted for\nthe new door. Now log on your board, and type the door name (REQ if you\ndidn''t change it) and the door should load up. If the door doesn''t load or\nsomething seems to go wrong, check the problem list below for possible \nsolutions, and then try to re-install it. If the door has come up, skip to\nthe preference section.\n\n Problems\n ¯¯¯¯¯¯¯¯\n If the node locks up and the door doesn''t come up? It is usually either\n one of three things. You haven''t correctly installed the RPStart, your\n system can''t handle rexx compiled doors, or you are missing the rexxplus\n library (All 3 can come only from running the compiled version). Check the\n section on installing the RPStart, make sure you have copied the lib over\n to your own Lib: directory, or try running the source file.\n\n The board says it can''t find the location of the door? You have made a \n mistake in the path location of the door. Check the REQ.Info or BBS.CMD\n file to make sure the path to the file is correct - which should be\n ''Doors:VDRequest/VDRequest.Rexx'' or ''Doors:VDRequest/VDRequest''\n\n The door tells you to make sure you have it in the ''Doors:VDRequest'' \n directory? You must have the door in this location. It looks for all \n support files here. Make the directory if you haven''t already and copy\n the files to this proper directory.\n\n Your told your access isn''t high enough to run the door? You have set the\n access level too high in the REQ.Info or BBS.CMD file. Check the file out\n and make sure it''s a proper level. Usually 1 - 255 is where it will be.\n Use the value of your average user so everyone can run the door.\n\n Your told you need the preference file? Make sure you copied the \n VDRequest.Prefs file over to the directory. You must have this file in\n order for the door to run.\n\n=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n\n » 7. Preferences «\n\n Preferences are what allow you to set this door up according to the way\nyou like. There are quite a few options you can set up to make the door\nsuit your own needs. I will cover them all so you get an understanding\nof what each one does.\n\n To change the preferences to the way you like, their are now 2 ways of\ndoing it. The first way is the old fashioned way of loading the preference\nfile in a text editor and changing the lines you want and saving it. This\nwill still work for this door. However, a newer and nicer way to configure\nthe door has been added. By editing the preferences through the door, you\nwill be told what each line does and have a chance to change it, instead\nof having to flip back and forth between the doc and the preference file.\nEither way will work, use whatever way you like best.\n\n NOTE: You should always configure a program before you let you users start\n       using it. If you don''t, some items might be setup differently then\n       you would like and so could cause problems. Don''t wait for a problem\n       to appear, change the preferences before one does. Also, you can\n       use my ''VDRequest.Prefs'' file included as an example and make the\n       changes to that, or make your own file with the same name and\n       start from scratch. It''s just easier with a reference point. If you\n       decide to change the preferences through the door editor - you will\n       need the VDRequest.Prefs file I included, you cannot start from \n       scratch.\n\n Manual Editing\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n For this method, you must first load the ''VDRequest.Prefs'' file into a\ntext editor such as TXEd or CygnusEd. The preference file outline is as\nfollows. Go through the file and change the current values to those that you\nwould like. \n\n-----------------------------------------------------------------\nMake The Answer A Request Option Active [Y/N]\nMake Awarded Files Free Downloads [Y/N]\nMake The Message Options Active [Y/N]\nComment For Deleted Files In Filelists [Blank = None]\nComment For Awarded Files In Filelists [Blank = None]\nDefault Conference Name [Blank = None]\nDefault Conference Location On Harddrive [Blank = None]\nAccess Level To Use EALL In Messages\nAccess Level To Use Sysop Options\nDefault Times Credit Amount For Awards\nMaxmium Number Of Requests Per Person [Blank = Unlimited]\nMaxmium Number Of Requests Alltogether [Blank = Unlimited]\nLocation Of User.Data File\nLocation Of User.Keys File\nOutput Bulletin For Request List\nCommand Used To Run Door [Blank = No Logon Awarding]\nPath To All Award Bulletins [Seperated By A Space/Blank = None]\n-----------------------------------------------------------------\n\n The space between the lines contains the items you will need to configure.\nFor a complete explanation of what each one does, see the next section on\ndoor editing. The values that are currently in the preference file are the\nway I have them setup on my board - unless you have created your own file\nand started from scratch. \n If something has [Y/N] then the line should have only a ''Y'' or ''N'' (or ''y''\nor ''n''). If a line has a [Blank=None] then you can leave this line blank to\nturn this option off. You must leave the line blank though, you can''t simply\nskip over it. This is the same for [Blank = Unlimited]. Leaving this line\nblank will set no maxmium number, but the line must be left blank or have\nsomething in it. You can''t skip over it.\n\n Door Editing\n ¯¯¯¯¯¯¯¯¯¯¯¯\n For this method, you must first make sure you copy the VDRequest.Prefs\nfile included in the archive over to the VDRequest dir. Without this file\nyou will not be able to run the door and so won''t be able to use the\nbuilt-in preference editor. Once it''s in the drawer, log on your board\nand start the door up (Usually typing REQ if you set it up exactly as \noutlined above). Once the door is up, select the ''Edit Request Stats'' \noption. Please note that you need to have an access of 255 to use this\noption (you will be able to change this in the preferences, but for now\nit''s set at 255). This shouldn''t be a problem as if your installing this\nyou are usualy the sysop and so have sysop access on your board. If you\ndon''t for some reason, raise your access to 255 or higher so that you\nwill be able to use this option.\n Once you select this option you will be prompted for a users name that\nyou wish to edit. Your name will already be in the space. Erase this name\n(whether with Ctrl-X or backspaces) and enter the name ''Prefs''. (Note that\nwildcards are supported if you lazy. So typing ''Pr*'' or ''Pre'' would\nbring up the prompt if ''Prefs'' was the name you were looking for. More on\nwildcards later). Once you have entered ''Prefs'' and hit return you will\nenter the preference editing where you can change all the preference items.\nNow for a list of all the items in order and what each of them does.\n\n NOTE: The current setting will always appear first so you can see what\n       it''s set at now. If you need to make changes, erase what you dont\n       want and put in the new setting. Then press return. Also note the\n       program is not case sensitive. If the doc says to use ''Y'', then\n       you can use a ''Y'' or ''y''. The case doesn''t have to match.\n\n -Make The Answer A Request Option Active [Y/N]\n\nThis option will allow you to either let the users use the ''Answer A \nRequest'' option or to disable it. If you don''t want users to be allowed\nto answer requests (See Answering a request section) then put a ''N'' here.\nIf you want them to use it, put a ''Y'' here. You should let them use it\nas it greatly inhances the door.\n\n -Make Awarded Files Free Downloads [Y/N]\n\nIf the setting is set to ''Y'', then when someone answers a request the files\nthat he has uploaded will be made free downloads so that the user that\nwanted the files will lose no credits when he takes his request files. If\nthe option is set to ''N'', then the files will not be made free downloads\nand the user will need enough bytes to download the files as with normal\nfiles. It''s better to make them freedownloads, as these files aren''t new\nand so credits shouldn''t be wasted on taking them.\n\n -Make The Message Options Active [Y/N]\n\nThis setting will allow you to disable the message features of the door.\nIf the setting is set to ''N'', then no messages will be sent from the door.\nThe user won''t be allowed to accompainy his request with a message, and\nno message will be posted to the receiver of a request when the files are\nuploaded. You should leave the messages on as they help in letting people\nknow when things happen.\n\n -Comment For Deleted Files In Filelists [Blank = None]\n\nThis is the text that will appear over the filesize of a file once the\nuser has taken his requests and deletes them. If you leave this blank then\nno text will appear over the filesize once the files are deleted. You \nshould use this option with a message like ''Deleted'' or ''Offline'' so the\nusers will know the files have been deleted and so don''t try to take them.\nOr so they ask questions like, the files are in the lists but I can''t \ndownload them. Note, this is like faker utility messages that are used\nin the filelists.\n\n -Comment For Awarded Files In Filelists [Blank = None]\n\nThis is similar to the Deleted files comment, but will be used once a \nrequest has been answered. Once the request is awarded, this text will\nbe posted in the filelists on the files that were awarded. This is to let\nthe person that uploaded them see that his requests were awarded, and to\nlet everyone else know the same. This is useful for sysops, as if the files\nstill have the award comment and the user has taken the files, the sysop\ncan tell the user not to forget to delete his requests. Their are some\nspecial characters the user can use. One is a ''#'', this will be replaced\nby the amount of credit times the user recieved for the files. So if the\nsysop has awarded a user *10 credits for requested files, the # will be\nreplaced by a 10. Another character is the ''@''. This will be replaced\nby the original bytesize of the file, in case you still want to know. So\nif the size of the file is 103948 bytes, the @ will be replaced with a\n103948. Some examples of these special characters in use are.\n\n -Credit Award for these examples is 5, bytesize is 292039.\n\n You Enter    Appears As\n\n #×@         :3×292039\n #*@         :3*292039\n x# AWARD    :x3 AWARD\n @!!         :292039!!\n Award #     :Award 3\n #-AWARD-#   :3-AWARD-3\n P @         :P 292039\n # @!        :3 292039!\n # # # #     :3 3 3 3\n\n NOTE: The maximum length is 9, so anything above that will be cut to keep\n       it from running into the other parts of the file description. Also\n       mutilply special characters can be used, even the same one more then\n       once.\n\nIf a special character has been used, once you press return after entering\nwhat you want, you will be shown how it will look on the board as the \nexamples above. This is to give you an idea of how it will look like in\nthe filelists. You will be asked if it''s okay, and you can hit ''Y'' if it\nis and ''N'' to go back and change it. If you haven''t used any special \ncharacters, you won''t be shown this.\n\n -Default Conference Name [Blank = None]\n\nThis option is very useful to help keep track of things. If you wish to have\nall activies done in only one confernece (like your request conference) and\nnot have it everywhere, then this section is for you. If you want to let\nusers make and answer requests in any of your conferences, leave this\nline blank. The messages and files will appear in the current conference\nthey are in. If you do have a request section, as most of us do, then\nby using this option everything will be done in this conference. For\nthis option, enter the name that you wish to call this conference in here.\nThis doesn''t have to match a conference on your board. It''s just the name\nthat will appear while running the door as the conference they are in. You\ncould set it as ''Request'' or ''Req Files'' or anything you like. I have it\nset as ''Cell Block'', even though the confernece on my board is called\n''[*] Requests [*]''. This option doesn''t have to match up, only the\nlocation has to be exact. (See next item below). Once again, leave this\nblank to allow people to use the request door in any conference. Enter\nany name that you wish to call the conference here if you wish to restrict\nthings to only one conf. The reason for me adding this conference, is that\nif the actually conference on your board is too long, it will be cutoff.\nBut now you can shorten and use another name so it won''t get cut.\n\n -Default Conference Location On Harddrive\n\n NOTE: You won''t be shown this option unless you have entered something in \n       the above option. If the default conference name option is blank, you\n       won''t be shown this option as their is no need to set it.\n\nThis option goes along with the option above of the default conference\nname. This option however must match up with a valid path to the\nconference location (The full path, with or without the ''/'' at the end).\nWhen they run the door then and these 2 options are used, it will be like\nthey were actually in this conference and so all messages, posts, and changes\nto the filelists will appear in this section.\n\n Now to make sense of these 2 options, lets take a real life example.\n\n You have a conference on your board called ''ThE WoRLdS BeSt ReQueSt CoNf''.\nThis is the exact name as it appears on your board. This conference\nis located on your harddrive at ''BBS:Request''. Now you want all the actions\nof the request door to be done in this conference, because you don''t want\npeople posting request messages in your amiga and ibm conferences, and\nyou also don''t want them uploading requests to these areas. Since the\nactual name of the conference is quite long, you decide that you will\ncall it ''Requests''. So you enter the name ''Requests'' in the default \nconference name, and you enter the default conference location as \n''BBS:Request''. Now when the user runs the door, the conference name will\nbe listed as ''Requests'' and all activities will be done in the conference\nthat you have on your harddrive as ''BBS:Request''. Meaning if they decide\nto post a message, it will appear in the ''BBS:Request'' message base, etc.\nNo matter what conference they run the door in, the name will appear as\n''Requests'' and the ''BBS:Request'' area will be used. \n Now, if you didn''t use this option, the current conference they are in\nwill appear as the name, and the location on your harddrive matching with\nthat conf will be used. So if they ran the door from your amiga conf, the\namiga conference name will be shown, and the amiga conference location on\nyour harddrive will be used.\n\n If all this sounds confusing, go over the example a few times until you\ncan make sence. If all else fails and you want to use this option, Enter\nthe default conference name as ''Requests'' and the full path to your request\nconference (Usually something like ''BBS:Request'') as the default conference\nlocation.\n\n NOTE: If you don''t have a request conference, it would be a good idea to\n       open one up. It''s also okay if you just want to use say an amiga\n       conference for request files. It''s just easier to keep track of\n       things when they are all in one conference with this option.\n       Also, note that you can use this option to make sure all things are\n       done in any conference, not just the request one, but the request\n       one will usually work better (hence the name!). I don''t see many\n       sysops making sure all the requests are made in the amiga conference,\n       although it''s perfectly alright to do so if you wanted to.\n\n -Access Level To Use EALL In Messages\n\nThis is the access level needed by a user in order to make a request message\nat the eall level. If a user does make the message out to ''EALL'' and has\na access as high or higher then this setting, the message will be posted to\nall users and they will recieve the message when the log on the board. It\nwill be as though you had written the message to everyuser. Very usefull \nwhen you need something really badly and must let everyone know about it.\n\n -Access Level To Use Sysop Options\n\nThis is the access level a user will need in order to gain access to the\nsysop items. If a user has an access as high or higher then this setting,\nthen they will be able to use the sysop options. Be carefull as to whom\nyou let use these options. All the sysop options are as follows:\n\n You are allowed to make as many requests as you want.\n You are allowed to view any request whether private or not.\n You are allowed to remove any request.\n You are allowed to edit any request.\n You are allowed to use the ''Edit Request Stats'' option on the main menu.\n You are allowed to award or remove request answers that users put in.\n You are given the ''Reset All Stats'' option from the ''Remove A Request'' menu.\n\n -Default Times Credit Amount For Awards\n\nWhen a user answers a request, and the answer a request record screen is\nshown, you will be given the chance to award the person that uploaded the\nrequest a credit award. This default times credit award will appear on\nthe screen as the credit reward he should get. This amount times the \noriginal credit for the uploads will be the reward he will get. So say\nthe files were 100000 bytes, and this setting was at 3. Then 3 times\n100000 would mean he would get a reward of 300000 bytes (3*100000). Note\nthat you will be able to change the credit award on the screen because\ndifference cases call for different awards. This is just the default amount\nthat will appear on the screen when it first comes up. You can then use it\nor change it. More on this in the answering a request section later on.\n\n -Maxmium Number Of Requests Per Person [Blank = Unlimited]\n\nThis option will allow you to set a limit on how many requests each user\nwill be able to have at one time. If you set this option at 5, then each\nuser will be able to make 5 requests at one time. He will never be able to\nhave more then 5 requests at any one time. If he has already made 5, he will\nhave to delete some before he can add other ones. This option helps to make\nsure the users remove their old and unwanted ones before they put new ones\nup. If you don''t enforce a limit, users tend to make alot of requests and\nfill the lists up, making it harder for the ones they need to get spoted.\nIf you leave this option blank, then there will be no limit as to how many\nrequests a user can have at any one time.\n\n -Maxmium Number Of Requests Alltogether [Blank = Unlimited]\n\nThis option will allow you to set a limit on the maximum number of requests\nthere is at one time. So if you set this option at 20, then you won''t be\nable to have more the 20 requests on the list at one time. If you already\nhave 20, you will have to delete some of them to add new ones. Again, this\nhelps to make sure the requests up are valid and needed and that the list\ndoesn''t contain old and forgotten about ones. If this option is blank, then\ntheir will be no limit as to how many requests can be made at one time.\n\n -Location Of User.Data File\n\nThis is simply the full path to your ''User.Data'' file, usually something\nlike ''BBS:User.Data''. This is needed in order to scan the info for the\nmessage routines to make sure the users exist and to provide wildcards.\n\n -Location Of User.Keys File\n\nThis is the same as above, but it''s the full path to you ''User.Keys'' file,\nusually something like ''BBS:User.Keys''. It is needed for the same reason\nas the ''User.Data'' file.\n\n -Output Bulletin For Request List\n\nThis is the full path and name of the output list that the door will use\nto show the requests on. When a user makes a request, the request will be\nadded to this list. This output bulletin is the basis for the door, as all\ncurrent requests will be listed on this list. Also, any option that\nsays it will do something to the list, they are referring to this one. So\nthe ''Edit The Request List'' and all other options will affect this list.\nIf you have a request conference, it''s a good idea to make this list a\nbulletin in the list. You can also make this a bulletin for when your \nlogging onto your board. Or you can make it a list that won''t be shown to\nanyone. Some examples of possible lists are:\n\nDoors:VDRequest/VDRequest.List\nDoors:VDRequest/VDRequest.Txt\nS:RequestList\nBBS:Bull50.Txt\nBBS:Node1/Bull40.Txt\nBBS:Requests/Bull10.Txt\n\n NOTE: Only ''Bull<#>.Txt'' type output files will work as bulletins.The first\n       three examples here will not be shown to the users unless they enter\n       the door and use the view request option. The last three examples are\n       meant as bulletins that will be shown to the users when they are\n       on your board.\n\n The number after the word ''Bull'' is the access level needed for the \nbulletin to be shown to this person. So if you have ''Bull50'' then a user\nwould need an access of 50 or higher to see this bulletin. Needless to say,\nyou should make this a level that all users will be able to see.\n\n Bulletins made in the ''BBS:'' drawer will be the first ones shown when you\nlog on the board, then the ones in the ''NODE(x)'' drawer, and finally\nthe ones in the conference locations will be shown everytime a user joins\nthe conference. It''s a good idea to put the output file as a bulletin in\nyour request conference, so that it will be shown to the users everytime\nthey join the request conference.\n If you already use mutilply bulletins with the help of the MCI commands,\nthen you can also change it to show this bulletin when you want to. This\nisn''t needed and sysops that do use this feature will already know how to\nset it up.\n Also note, that if you change the location of your output bulletin while\nthere is already one in use, then the old one will be renamed to the new\none. So if you called it ''S:Request.Txt'' at first, but then decided to\nchange it to ''BBS:Bull50.Txt'', then the old one will be renamed to this new\none so the requests on the list will remain intact.\n\n -Command Used To Run Door [Blank = No Logon Awarding]\n\nThis is a nice option to make sure that when a user tries to answer a \nrequest, it will be done so as soon as possible. The reason for using this\noption is that if you do, the door will create a bulletin (or bulletins)\nwith a notice saying that there are answer records awaiting approval.\nSo for example, if there is a request answer that is awaiting approval from\na sysop, and you are one and you log on your board, this bulletin will\ncome up telling you that there are answers waiting so you can run the door\nand answer them immediatly, instead of making the users wait for awhile.\nThis is a much better way instead of running the door every once in awhile\nand checking if there''s anything waiting for you to check up on or answer.\nHowever,If you do not wish to use this option, simply leave this and the\nnext line blank. If you do wish to use this option, then in this space\nenter the name of the door as it appears on your board in here. So if you\ntype ''REQ'' to load the door on your board, then you would enter ''REQ'' in for\nthis option (Not case sensitive of course - ''Req'' or ''req'' would be fine as\nwell). This will come up in the notice so that the sysop will know what to\ntype to bring the door up. This is all that''s needed for this option, now\nyou will move on to the next one to configure it.\n\n -Path To All Award Bulletins [Seperated By A Space/Blank = None]\n\n                or\n\n -Location Of Logon Award Bulletin [ # ]\n\n NOTE: You won''t be shown this option unless you have entered something in \n       the above option. If that option is blank, you won''t be shown this\n       option as their is no need to set it. Also note, that if your\n       using the editor then you will be prompted with the line ''Location\n       Of Logon Award Bulletin [ # ], where # is the number of the location\n       that you are current entering. If your not using the built in editor,\n       then the line ''Path To All Award Bulletins [Seperated By A Space] is\n       the way to edit the line. This will become more clearer as you read\n       on.\n\n If your not going to be using this option, then this line and the one\nabove should be blank. If not, then continue on and I''ll tell ya how to set\nit up.\n\n An important thing to note here is that if your editing this option \nmanually (with a text editor) then this line will contain the location\npaths for the bulletins seperated by a space. For example:\n\nBBS: BBS:Node1 BBS:Node2\n\n This would make a bulletin in the drawers ''BBS:'',''BBS:Node1'' and ''BBS:Node2''\n\nBBS:\n\n This would make a bulletin in the drawer ''BBS'' only.\n\n However, if your using the built in preference editor in the door, it\nwill prompt you for the names on at a time. You will enter each one and \nthen press return after each. So for the top example, You would enter\n''BBS:'' for the first location and press return, then it would ask you for\nthe second one, and you would put ''BBS:Node1'' and press return, and so on.\nYou can use a ''/'' at the end of the location or not, it doesn''t matter. So\n''BBS:Node1/'' and ''BBS:Node1'' are the same.\n\n Once again, if your editing it manually then it will be one line with\nthe conference locations seperated by a space. If your editing it through\nthe door, you will enter each location in one at a time.\n\n NOTE: This is ONLY the full path to where these bulletins should be made.\n       You don''t need to put actually bulletin name with these paths, they\n       will be added by the door. So ''BBS:Node1/Bull50.Txt'' is wrong, and\n       ''BBS:Node1/'' or ''BBS:Node2'' is right. Also note these bulletins will\n       only exist when their is a request answer waiting approval. Once \n       all the answer records have been answered, these bulletins will be\n       deleted. Finally, if your not sure about the difference of where\n       bulletins are located, the see the preference section that deals with\n       the output bulletin for the request list. This will distinguish the\n       differences between where bulletins are located and the effects.\n\nThe name of the actual bulletin depends on the access level that you have the\nsysop option set for. This is because only the people with sysop access for\nthe door will be able to validate or delete request answer records. So\nif you have the sysop access option set to 255, then the bulletins made\nwill be called ''Bull255.Txt''. If you have the sysop access option set to\n200, then the bulletins or bulletin made will be called ''Bull200.Txt'' etc.\nSo if the location path was ''BBS:'', and if you had the access set for 255,\nthe bulletin made would be ''BBS:Bull255.Txt''.\n\n As for MCI commands, if you already have alot of bulletins on your board\nyet you still want to use this option, you can use these MCI commands in\norder to show these new bulletins. For this, make the bulletins as normal,\nthen use the MCI commands to show these new bulletins.\n\n Heres Another real life example for using this option. You decide to use\nthis option because you don''t have time to be checking when someone uploads\na request, you want it to notify you as soon as someone does. You \ndecide to use the built in editor to change this, as it''s easier to do. The\nname of the door as it appears on your board is ''REQ'', so for the ''Command \nUsed To Run Door'' option you enter ''REQ''. Now, you already have a last\ncallers bulletin in the ''BBS:'' directory, so you decide to make these\nbulletins appear in the ''BBS:NODE1'' and ''BBS:NODE2'' drawers. This means\nthey will appear after your last caller bull (because it''s located in BBS:)\nwhen you log onto node1 or node2. So because of these directories where\nyou want to make the bulletins, you enter ''BBS:Node1'' & then ''BBS:Node2'' in\nfor the Locations of the Logon Bulletins option. Now, awhile later.. someone\nuploads a request and fills out a answer a request record for it. Now, since \nthere is a answer record awaiting approval now,the door creates the bulletins\nin ''BBS:Node1 & BBS:Node2''. You have the sysop access set at 255, so the\nbulletin names are ''Bull255.Txt''. Later on that day, you log on your board\non node1 and are first shown the last caller bulletin as normal. Now, since\nyour access is 255, you are now shown the ''BBS:Node1/Bull255.Txt'' bull.\nThis will tell you that there are records awaiting approval, so after you\nfinish logging on your type ''REQ'' to load up the request door. Once in the\ndoor, you are brought to the screen where you can award or remove the answer\nthe user put in eariler that day. After this, you will be brought to the\nmain menu, where you select the exit option and continue on your way.\n If you wanted to use this same example but edit it manually and not\nthrough the door editor, you would change the ''Command Used To Run Door \n[Blank =  No Logon Awarding]'' line to ''REQ'' and the ''Path To All Award\nBulletins [Seperated By A Space/Blank = None]'' line to ''BBS:NODE1 BBS:NODE2''\n\n\n Please note that any changes you make in the preference section take effect\nright away while your using the built in editor. So if you have changed\nanything, the changes will be in effect as soon as you return to the main\nmenu.\n\n After your done editing the preferences, you will be returned to the main\nmenu of the door. \n\n User & Access Files\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n NOTE: You do not need the VDRequest.Users or VDRequest.Access files in\n       order for the door to work. You will only need them if you want to\n       use the following two options.\n\n Now your almost done configuring the program. You might have noticed two\nfiles included in the VDRequest archive called VDRequest.Users and \nVDRequest.Access. These files are not needed in order to run the door, but\nthey can be used for 2 specific options. The VDRequest.User file is used\nif you want to keep someone from using this door, whether out of mistrust\nor misuse. This file should contain the names of all the users (Not case\nsensitive) that you wish to keep out of the door. One name per space. So\nif you wanted to keep the users ''Elmo'' and ''Bigbird'' from using the door,\nyou would add the following lines to the VDRequest.User file:\n\n-------------\nElmo\nBigbird\n-------------\n\n When the door is run, if this file is found it will scan all the names\ninside. If a match is found with the current user he will be exited from\nthe door before he can use it.\n\n The second file, the VDRequest.Access file is used in order to give users\nsysop access to the door without actually raising their real access level\non your board. So if you have a user that looks after the requests on your\nboard, and wanted to give him full access to all the request option, you\nwould add his name to the list (Not case sensitive). So lets say you have\nthe sysop access option for the door set at 255. Now you have a user that\nyou want to be able to use all the sysop options for the request door, \nwithout giving him a 255 access on your board. Lets say this users name\nwas ''Drunk Man''. You would add his name to the VDRequest.Access file (one\nuser per line only) as:\n\n-------------\nDrunk Man\n-------------\n\n When the door is run, if this file is found it will scan all the names\ninside of it. If a match is found, like in this case drunk man, the user\nwill be given the same access for the door as the sysop option is set for.\nIn this case, you have the door''s sysop access set for 255, so while in\nthe door Drunk Man would be given a 255 access in order to use all the \noptions. \n\n NOTE: Please note that the users access on your board will NEVER change\n       with this option. If the user has an access of 50 on your board, then\n       it will stay at 50 no matter what. The access setting I am talking\n       about is inside the request door only. You don''t have to worry\n       about his real access level on your board ever changing.\n\n\n That''s it. Your now done configuring the door as you want it to run on\nyour board. You should now take a minute to run through the other options\navailable on the door so that you will know how to use them when you need\nto. Also, you should have a good working knowledge of the options on the\ndoor so you can answer any problems that the users might have about it.\n\n=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n\n » 8. Door Features «\n\n The first time you run the VDRequest program on your board, it will make\na ''Description'' directory inside of the ''Doors:VDRequest'' directory. This\nwill be used to keep track of the long descriptions for requests, as well\nas other info needed for each request made. This is in case your wondering\nwhy this directory is there if you ever look.\n Also, the first time you run the door, it will create a ''VDRequest.Store''\nfile in the same directory. This storage file is used to keep track of all\nthe statistics for the door. Do not edit this file with a text editor, as\nit''s set up specially and you will more then likely corrupt it. If you need\nto change stats at any time, the use the ''Edit Request Stats'' option from\nthe main menu. You can however remove whole lines from the storage file,\nas long as you delete the entire line you want to get rid of and don''t\nedit anything else. There shouldn''t really be a need for this anyway, but\njust in case.\n\n Before I start explaining the options for the door, I want to tell you \nabout some of the general items and nice features that are found throughout\nthe door. \n\n Wildcards\n ¯¯¯¯¯¯¯¯¯\n Whenever you are asked to input something you should note that wildcards\nwill be supported. For example, when you are trying to write a message\nto someone, wildcards will be supported. Entering ''Van'' or ''Van*'' will scan\nall the users for a match, which in my case would be ''Van Damme''. You will\nbe prompted when a match is found if it is the correct one. If it isn''t,\nit will continue searching for one. More info on wildcards can be found\nin the sections that use them.\n\n NOTE: Wildcards can be used by using a ''*'' or not. Whenever you enter\n       a name, it will start searching for a match. If an exact match is\n       found then the users name will be used right away. If no exact match\n       is found, it will start looking for names that start with the text\n       you entered. If a match is found, you will be asked if it is the \n       correct one. If you say it is, then this name will be used. If\n       you say it isn''t, it will keep searching for another match. If \n       another match is found it will ask you if it''s the correct one, and\n       so on. If no more matchs are found, you will be told the name doesn''t\n       exist and be returned to the original prompt where you are to enter\n       another name. So for example, if you enter ''Van'' or ''Van*'' (You can\n       use a ''*'' at the end or not, it doesn''t matter) it will start\n       searching for the name ''Van''. If it finds the name ''Van'' it will use\n       it. If the name ''Van'' is not found, it will start looking for names\n       starting with ''Van''. Now lets say it found a match with the name\n       ''Van Damme''. It will then ask if you if this is the right name that\n       you were looking for. If you say yes, it will use this name. If you\n       say no, it will keep looking, and so on.\n\n If you just use a ''*'' for the name and nothing else, it will allow you \nto scan all of the current names, files, etc. This is useful for viewing\nall of the current available names or files, or when you forget the name\nyou are looking for.\n\n Memory Feature\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n A nice feature on the door is that it will remember which request number\nor user that you have used last. Whenever you enter a number for any request\noption, this number will be remember. If you then select another option\nconcerning a request (like erase a request, edit a request, answer a \nrequest, etc) then this number will appear in the input box aready. You of\ncourse can delete this if you no longer want it and put another one in. If\nat any time you enter a blank line as a request number, then the number\nin memory will default to the highest current request. When you enter the\ndoor for the first time, it also defaults to the highest current request\nin memory.\n This number in memory works the same with a users name for the ''Edit\nRequest Stats'' option. Whenever you edit, view, delete, etc a request, the\nuser involved in that option will be remembered. When you select the\n''Edit Request Stats'' option then, this users name will appear in the input\nbox already. You of course can delete this if you don''t want to use this\npersons name, and enter the correct one. If at any time you enter a blank\nline in the Edit User box brought up through the ''Edit Request Stats'' \noption, then the name in memory will default to the users name running it.\nWhen you enter the door for the first time, it also defaults to the\nusers name running the program.\n\n NOTE: The ''View The Request List'' option from the main menu will always\n       start listing at 1, so simply selecting this option will not cause\n       any number or name to be put in memory. However, the Jump and View\n       sub options inside of this option will function normally with the\n       memory feature.\n\n Input Features\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n Whenever you are given the chance to input something, note that by pressing\nCtrl And ''X'' at the same time you can delete everything currently in the\ninput space. Also, the tab key will always move the cursor over 6 spaces.\nThe enter a long description option that you can use when entering a \nrequest also contains a wrap around feature, which will bring the word over\nto the next line if you run out of space. More on this in the ''Enter A \nRequest'' Section. \n When you are asked to input something, entering a blank line will always\nquit you from the option and bring you to the previous or main menu. \n\n NOTE: If you are prompted for input that requires numbers only, hitting\n       any key other then a number will do nothing save for the backspace,\n       Ctrl + X, and return.\n\n Menus\n ¯¯¯¯¯\n If you press the return key at any menu, it will always select the highest\nor farthest option to the right of the screen. For example, pressing \nreturn in the main menu will select the ''Exit'' option, and pressing return\nfrom the ''View The Request List'' option will select continue (farthest\noption to the right). Pressing return in the ''Remove A Request'' option\nwill select the ''Quit'' option (again furthest to the right), and so on.\n Pressing a key not outlined in the current menu (other then return) will\ndo nothing.\n\n Yes/No Prompts\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n When you are prompted with a ''Sure (Y/n)?'' or ''Correct (y/N)'' or anything\nwith the (Y/n) prompt, there is something useful you should note. If the\n''Y'' is a capital, then pressing any letter other then ''N'' will act as Yes.\nIf the ''N'' is a capital, the pressing any letter other then ''Y'' will act\nas no. For example, in the prompt ''(Y/n)'' if you press any letter other\nthen ''N'' it will be Yes. If you press the ''N'' key it will act as No. If the\nprompt is (y/N), then if you press any letter other then ''Y'' it will be\nNo. If you press ''Y'' it will be yes. So hitting say return on the (Y/n)\nprompt will act as Yes sense the ''Y'' is the capital one.\n This is useful for options like deleting. You will be prompted will things\nlike ''Delete (y/N)'',and you will be forced to have to press the ''Y'' key to\nuse the delete. If you miss or slip and hit another key, (any key other then\n''N'') it will not use the delete. This is to make sure you don''t delete\nanything by accident.\n\n Statistics\n ¯¯¯¯¯¯¯¯¯¯\n The request door will keep a record of a few things. It will keep track\nof how many requests have been made altogether (since you started running\nthe door) and also how many requests have been answered althogether. It will\nalso keep track of how many requests each user has made, and how many \nrequests each user has answered. These stats will be shown on the main \nmenu, or also if you are editing the persons stats. More on the statistics\nlater on.\n\n Conferences\n ¯¯¯¯¯¯¯¯¯¯¯\n If you don''t use the default conference to make sure all the actions of\nthe door are made in one conf, the door will still remember where you made\nthese actions occur in. If you then call the door from another conference,\nand it needs to get something from the conference the action was made in, it\nwill still be able to find it''s way around.For example, if you post a request\nwith a message in the amiga conference, and then run the door in the ibm\nconference and delete that request and the message along with it, it will\nstill remember that you made it in the amiga conference and delete it from\nthere, even though your currenly in the ibm conference. Or if your request\nfiles are in the snes conf, and you run the door from the amiga conf and\ndelete the files, it will still be able to find them in the snes conference.\n The default conference will work in a simliar matter, but for more on it\nplease see the preference section.\n\n=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n\n » 9. Main Menu «\n\n This is the central area of the door, from which the program is based upon.\nFrom here, you will be able to select all the different options available\nto you, although not all the options will be available to all users at\na time. From here you may also exit the door. \n Whenever you have completed or exited from an option in the request door,\nyou will always be returned to the main menu. From here you can use the\nsame option you just came from, or try something else.\n A general description of what you see on the main menu is as follows:\n\n The top line of the main menu contains the info about the program name\n(VDRequest), the program version (3.0), the program creater (Van Damme),  \nthe programs company (© FreakWare), and the user that it is currently\nserving. The name that will appear beside the ''NOW SERVING'' prompt is the\nname of the user that has run the door.\n\n To the right of the door are listed the request statistics. The ''Total\nStats'' box will contain the total amount of requests that have been made\naltogether since the door was installed, the also the total amount of\nreqeusts that have been answered. The ''Users Stats'' box will contain the\nstatistics for the user that has run the door. It will list how many \nrequests that one user has made, and also how many requests that user\nhas answered.\n\n Below the requests statistic boxes are the name of the conference that\nthe user is currently in, and the option prompt. The name that is shown\nin the ''CONF'' area is the current conference that the user has run the door\nfrom. This conference can be preset (see the section of preferences).\nThe ''OPTION'' prompt will remain blank until the user selects an option. Once\nthe user has picked an option, the name of that option (Usually in short\nform) will appear beside the ''OPTION'' prompt to remind the user of what \noption he is currently using.\n\n Finally, to the left of the statistic boxes is the main menu option list.\nThese are the options that the user can select from while on the main menu,\nlabelled 1-7. The ''Enter a request option'' has its own box to make it stand\nout from the rest, as this will be the most used option by your users.\nPressing 1-7 on this screen will select the option that matches up with the\nnumber.\n Note that on this option list, it''s possible for there to be ''[DIS]'' \nmessage beside the ''Answer A Request'' or ''Edit Request Stats'' option. This\n[DIS] means that this option is currently disabled. The ''Answer a request''\noption will have this if you have turned it off in the preference section,\nand the ''Edit Request Stats'' option will have this if you don''t have enough\naccess to use the sysop options (Edit Request Stats is a sysop option). \n If a user selects an option with [DIS] beside it, nothing will happen\nas this option has been currently disabled for him.\n\n=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n\n » 9a. Main Menu Option 1 - Enter A Request «\n\n This is the first option listed on the main menu. It will also be the most\nused option in this door. As before anything can be done, a user must\nfirst enter a request. I''ll bring you through this option step by step,\npointing out anything I think you will know.\n\n After pressing ''1'' on the main menu you will be brought into the enter a\nrequestion option. The first thing it will do is check to see what request\nnumber it is at. If the requests made is equal to the maximum number of\nrequests that the user set up in the preference file (if he did) then the\nuser will be told that he cannot make any more requests until some of the\ncurrent ones have been removed. So if the door is set up for a maximum\nof 20 requests at one time, and 20 requests have already been made, the user\nwill be told to clear some of the old ones off, and he won''t be allowed to\nmake any new ones. He will then be returned to the main menu.\n The second thing it does is check how many requests this one user has\nmade compared to the maximum amount of requests allowed by one user (as set\nin the prefs). If the user has already made his maximum amount of requests,\nhe will be told to delete some of his older ones to make room for his new\nones. He will then be returned to the main menu without being allowed to \nenter a new request.\n\n If no maximum limit is reached, the user can enter a new request. He will\nbe told what request number this will be, and he will be prompted for a \none line description of his request. Pressing enter here will abort and\nreturn him to the main menu. The input commands (as described in the door\nfeatures section) will work here as with any other input section. Tab will\nwork as 6 spaces, and Ctrl-X will delete the entire line. These 2 features\nwill also be shown to the user so he knows that they are there for the \nusing.\n\n After he has has entered the one line description and presses return, the\ndescription he entered will be kept on the screen so he can remember what\nhe has just put in. It will also be a different color (if Ansi is on). Now he\nwill be asked if he wants to enter a long description. If he hits ''N'' then\nit will continue on and the request will have no long description. If he\nsays ''Y though, he will be allowed to enter a 3 line description of what\nhis request is about. This is in case it''s a complex or important request,as\nsometimes 1 line isn''t enough to get things across. While entering the long\ndescription, pressing return on a blank line will exit it. Wrap around will\nwork here, and if you get to the end of a line and you don''t have enough \nroom to finish the word, keep typing and the word will be carried over to \nthe next line. If he has entered a long description then it will say\n[Long Description] to the right of the 1 line description to remind him that\nthis request has a long description. Likewise, if no long description was\nentered, it will say [No Long Description] in the same place. Note, if you\nsay ''Y'' to enter the long description, and then press return without\nentering any text, you will exit the long description routine and the\nrequest will have no long description. Also, if you don''t enter any valid\ncharacters (letters) for the long description (ei, you put all spaces), this\nwill make the request also have no long description.\n\n Next, you will be asked if you want to write a message for your request.\nPressing ''N'' will let you continue on without entering a message for this\nrequest. If you press ''Y'', then you will be allowed to write a message along\nwith this request. If you pressed ''Y'', then you will be asked who the \nmessage is for with the prompt ''To: (Enter)=''ALL''?''. Pressing return here  \nwill make the message addressed to all. If you enter ''Eall'' here and your\naccess is high enough, the message will be made out to ''Eall'' (see \npreference section as for what eall means). If you want to send this request\nto a particular user - one that you know has the files you wanted, then\nyou can enter his name here (Wildcards supported). If you make the request\nout to a particular user, then you will be asked if you wish to make it\nprivate or not. More on private requests later in the section. So the message\nwill now be addressed to either a specific user, ''All'', or ''Eall'', and\nif it''s to a user it will also be private or public. \n\n NOTE: You can also address the message to ''Sysop'' or ''Sysop*''. Doing so\n       will send the message to the sysop of the board (again this can be\n       private or not).\n\n If you try to write the message to yourself you will be told to make it\nout to another user only. Also, if you used a wildcard, and no match was\nfound, you will be told the user doesn''t exist and be brought back to the\nmessage prompt on who to send it to.\n\n The message that you write will appear in the conference that is listed\non the main menu prompt beside ''CONF:''. This will usually be the conference\nthe user ran the door from, unless the sysop has set the perference to use\na default conf. If the message is to a user it will be addressed to him.\nIf it was addressed to Eall or All, it will be addressed to the users of\nyour board. What will be in this message is the one line description for\nthe request. If any long description was entered, it will also appear in\nthe message. Any blank lines will not be shown in the message however.\n\n NOTE: The subject for the message will be ''REQUEST [#]'' where # is the \n       number of this request.\n\n After your done entering or not entering a message, You will note that all\nof the things you have entered so far are still on the screen. These items\nwill be the the one line description you entered, whether or not you have\na long description entered, and who the message is to. If you decided not\nto write a message, it will say the message is to ''NONE''. Now, a new item\nappears on the screen. It is the ''Requests Left'' item. This item will tell\nthe user how many requests he has left to make (This value will depend on\nhow many requests per user you set in the preferences). Note that this\nnumber will be the number of requests left before this new request is made.\nIf he decides to put this request in now, he will have one less request from\nthis item. For example, a user wants to enter his first request and you have\nthe maximum number of requests per person set to 5. He enters all the info\nfor the request, and after he''s done this, it tells him that he has 5 \nrequests left. He has 5 requests left because he has not made any requests\nbefore. If he decides to go through with the request he has just answered\n(When it asks if the request is valid) then he will have 4 requests left.\nNow when he enters another 1, it will come up as 4 requests left. \n\n NOTE: If you are a sysop or have the maximum requests per person option\n       turned off, the requests left will come up as ''DIS'' meaning disabled.\n       This means that you have no limit and can make as many as you want.\n\n At this point, you will be asked ''Is This Request Valid? (Y/n). If you \nhit ''N'' then the request will not be processed and will not go up on the\nlist. If you want the request you just entered to be processed (most cases)\nthen hit ''Y'' or any key other then ''N''. The request you just entered will\nthen be added to the list and if there is a maximum limit of requests per\nuser (and your no sysop),then 1 will be taken off from how many requests you\nhave left. So if your a normal user, and it said ''Requests Left [ 5 ]'' and\nyou processed your new request, you would now have 4 requests left.\n This part is mainly incase you made a mistake. (Although you can edit it\nafterward). But in case you made a big mistake of some sort, you can hit ''N''\nto show that it''s not valid and go back and enter it in again.\n \n If you process the request, all stats will then be updated and any \nadjustments will also be shown on the main menu.\n\n Request List\n ¯¯¯¯¯¯¯¯¯¯¯¯\n Once your request is process, it will be added to the bottem of the request\nlist. The format for the request list is as follows.\n\nNum        User                     Request Description             L M  Date \n===-===================-===========================================-=-=-======\n1   FLASH               Q-blue--Registered Version                  * * May 25\n\n Num: The number of this request.\n User: The user that has made this request.\n Request Description: The single line description of the request.\n L: A ''*'' means that this request has a Long description included with it.\n    To view this long description you will need to run the door and use\n    the ''View Long Description'' option from the ''View The Request'' option\n    on the main menu. If there is no ''*'' and it''s blank under the L, then\n    this request has no long description.\n M: A ''*'' means that this request has a message included with it. To view\n    the message you will have to read the message base. To find the \n    information about the message (The number, conf it was posted in,etc) \n    you will have to use the ''View Long Description'' as described above.\n    If there is no ''*'' and it''s blank under the M, then this request has\n    no message included with it.\n Date: The date that the request was made in the the format of ''Month/Day''\n\n Private Requests\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n The only way you can make a request private is if you add a message with\nit. When the message comes up, you must direct it to a certain user. When\nthis is done, you will be asked if you wish to make it private or not. A\nprivate request will come up on the list as ''Private Request Sent To USER'',\nwhere USER is the person you sent it to. The only people that will be able\nto view this request then is the sysops, the person it has been sent to, and\nthe person that wrote it. Also, people cannot answer a private request \nunless they are one of these 3 people. All messages for a private request\n(original + answered) will also be private so the users can''t see it. Make\na request private if you don''t want everyone to see it, like if you are\nrequesting some files from a sysop that you don''t want getting out or\nsomething along these lines. \n While in the door, if you don''t have sysop access and the request wasn''t\nsent to or by you, it will also come up as ''Private Request Sent To USER''.\nHowever, if you do have sysop access, or the private request was sent to\nyou, you will be able to view it while in the door. It will come up in\na different color as the rest of the list (if you have ansi on) and will\nalso have a ''!'' at the beginning of it (in case you don''t have the ansi\ncolor on) to make sure you know it''s private.\n\n For example, while viewing the bulletin while not in the door or viewing\nit in the door without proper access it would come up as:\n\n2   Hunter              Private Request Sent To VAN DAMME           * * May 27\n\n While viewing the request in the door with the proper access, this same\nrequest will come up as:\n\n2   Hunter             !Amos Pro New Vers And 3D Compiler           * * May 27\n\n Note that while using the ''View Long Description'' in the ''View The Request\nList'' option, if you don''t have the proper access, all the items like\nthe long description and who the message was sent to will also be concealed.\n\n Once again, the only way to view a private request is through the door.\nThe actual request list will not contain the real description.\n\n=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n\n » 9b. Main Menu Option 2 - Answer A Request «\n\n First off, if the sysop has disabled this option in the preferences, you\nwill not be able to use it. You will know if it''s disabled or not, because\nif it is, it will have a ''DIS'' beside the option on the main menu.\n\n This option is for answering requests when people put them up. Answering\na request involves two things. First you must upload the files that a user\nwants. After your done uploading the files you must run this door and\nuse this option. You will be allowed to fill the infomation about your\nuploaded files for the sysop to then review (to make sure they are okay).\nIf the files are okay, you will then be rewarded for your uploads.\n\n There are two different types of ways to answer a request. The first is\nif the request is located on the request list. This means the user has put\nthe request into the door already. This is the easiest way. The second way\nis if a user has a request but hasn''t put it into the door. This might be\nbecause he has told you in a message or on the phone that he needs a certain\nfile. Either way is really easy to use.\n\n NOTE: If you select the ''Answer A Request'' option, you have sysop access,\n       and there are currently requests waiting approval, you will be\n       brought to the ''Answering A Record Screen''. For more info on how to\n       use this screen see the matching section. \n\n Answering A Request On List\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n This type of answer will be used the most (usually). First off, you must\nknow the request number that you are going to answer. To find out what\nnumber it is, you can use the ''View The Request List'' option from the main\nmenu. If you view or jump to that request while in the list option, the\nnumber will be put in memory (see section on Memory) so when you select\nthe ''Answer A Request'' option again the number will already be entered.\n Once you select this option, you will be prompted for the request number.\nSince you should now know what request number it is on the list, enter that\nnumber now. The program will now check for a few things.\n\n -If you have have made this request you will be returned to the main menu.\n  (You can''t answer your own requests.)\n -If the request is already awaiting approval you will be returned to the\n  main menu. (This means someone has already put in a answer record to the\n  sysop for this particular request and is awaiting approval).\n -If this request is private and you don''t have sysop access or the request\n  wasn''t sent to you, you will be returned to the main menu. \n\n If none of these conditions are met, you will continue on with answering\nthe request. Now the program will bring up the request number you have\nentered (including all information about it) and ask you if your sure\nif this is the right request you wanted to answer. Hitting ''N'' will bring\nyou back to the main menu if this isn''t the right one you wanted to answer.\nIf it is the right one then hit ''Y'' or anything other then ''N'' and you will\nbe prompted for the uploaded files to answer this request with.\n \n The prompt for the files you will see is:\n\n Enter Filename [ # ] Of Uploaded Requests:[           ]\n\n NOTE: If the conference that is listed on the main menu (the one it is\n       currently using) contains no filelists, then when you try to enter\n       a filename you will be told that the current conf has no lists and\n       be returned to the main menu.\n\n Where ''#'' is the current filename you are on. It will be at ''1'' when you \nfirst get to this prompt. Now you can enter the names of the files that\nyou have uploaded for this request. Two very important things to note here\nare that it will:\n\n 1: Search for the uploaded files in the conference listed on the main\n    menu only. Whatever conference is listed here is where it will look\n    for the files (Usually the conference you are in, unless the sysop\n    has the default conference preference set).\n\n 2: Search + Use files found only in the highest file lists of that \n    conference - the upload file lists. So if a conference has 3 file\n    sections, it will always use the highest one only. The reasons for this\n    is that they are the upload lists, and since the user has uploaded\n    the request files they will be found here. And also because it''s faster\n    then looking through all the filelists for the files. \n\n Now at the prompt, you can enter the names of the files that you have\nuploaded. Wildcards are fully supported here and you can use them to help\nyou find the file names. If you try to enter the same name twice you will\nnot be allowed and told you have already used that filename. The wildcards\nalso work as the other ones, showing you the match and asking if it''s the\nright one. If you say No it will continue looking until no more matches\nare found. If you say Yes it will use that filename it has found. Also\nyou can use a ''*'' or not at the end of the filename (''LSD*'' and ''LSD'' are\nconsidered the same thing). If you enter the exact filename it will be\nused right away with no searching. Entering a ''*'' alone will allow you to\nsearch all of the valid filenames.\n\n There are some two nice options added to the wildcard section to help\nyou find what you are looking for in a hurry. These options are as follows:\n\n First off, when using the wildcards, it will not show you the filenames\nyou have already used. So say there are two request files that you have\nalready uploaded. These two request files are called ''LSD_VDCf.Lha''\nand ''LSD_VDRq.Lha''. Since both these files start with ''LSD'' you decide\nto use wildcards. At the first filename prompt, you enter ''LSD''. It then\nbrings up ''LSD_VDCf.Lha'' and asks you if it''s right. You say yes and it\nenters it as one of the filenames. Now, to find the other file you again\nenter ''LSD''. It will skip over the first file you have already entered and\nbring up the second file ''LSD_VDRq.Lha''. You again say this is a correct\nmatch and it also enters it as a filename. Now you''ve entered both the files\nyou wanted without breaking a sweat. Easy isn''t it. (:\n\n Secondly, when using the wildcards, it will not show you the filesnames\nof files that are offline. The way that it detects if a file is offline, is\nif the current filesize of the file matches the current setting you have for\ndeleted requests in the preference, then it will deem this file as offline\nand not show it to the users. If you enter the name of a file that is \noffline directly without using wildcards, you will also be told that it''s\nalready offline. If you don''t have the comment for deleted files set in\nthe preferences then this option won''t work. For example, in the preferences\nyou currently have the comment for deleted files set to ''»OFFLINE«''. Now,\nwhen it''s searching for wildcards, if any file has the filesize of\n''»OFFLINE«'' (Meaning it has been deleted by the door) then it will not\nbe displayed to the user because this file has already been deleted. \n It will always use the current value in this setting while checking.\nIf all the files in your upload directory have ''»OFFLINE«'', and then you\ndecide to change the setting to ''»DELETED«'', then the door will not consider\nthe »OFFLINE« files as being offline, because the current setting that it\nuses to check is now »DELETED«. Only files that have a filesize of »DELETED«\nwill be considered offline now, and so on.\n\n Also, if most of the files in the current upload directory are already\noffline,  using a ''*'' as a wildcard will quickly scan all the files left\nincase you have forgotten the names of the files. Or if your just lazy\nand hate typing. (:\n\n Once you have entered a correct filename whether through wildcards or\nmanually, you will be shown at the bottem of the screen the stats for\nthe file. Including the filename, date, size, and the first line of the\ndescription. It will then clear the filename prompt to allow you to enter\nanother filename and move the filename number up by 1 to let you know\nhow many files you have entered and what number your currently on.\n\n NOTE: You can enter only a maximum of 5 files per request answer. Once this\n       limit is reached you will be exited from the filename prompt and\n       continue on.\n\n Entering a blank line for a filename will exit you from the prompt.\nIf you haven''t entered any file names you will be returned to the main \nmenu. If you have entered at least 1 valid filename you will be shown\nall the filenames you have entered and then asked these files are \ncorrect. If everything looks okay then hit ''Y'' and and the answer will\nbe sent to the sysop for him to check over. If you have made a mistake\nand want to fix it or decide to not answer the request, you can hit\n''N'' and you will be brought back to the main menu.\n \n If you have decided to process this answer, and the sysop has the awarding\nlogon bulletin option turned on in the preferences, these bulls will then\nbe made at this point. This is so that as soon as a sysop logs on the\nboard, these notices will tell him that there are records waiting so he\ncan deal with them as soon as possible.\n\n NOTE: When you answer a request, nothing will take effect right away. \n       The record will be sent to the sysops so they can make sure that it\n       is valid. It''s then his choice to decide what to do with it. This\n       is to prevent people from entering fake answers just to award \n       themselves with credits.\n\n Answering A Request Not On List\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n This way of answering a request is for when the request you want to \nanswer is not found on the list. So say your talking with a friend on the\nphone, and he says he needed a Dialer program. You call the board and\nupload the program and then load up the request door and select the\n''Answer A Request Option''. Since he asked you for this program on the\nphone, this request will not be found on the list. So instead of entering\nthe any valid request number here, you would instead enter the number ''0''\nat the ''Answer What Request Number'' prompt.\n\n NOTE: When you select the ''Answer A Request'' option, it will display the\n       notice ''Use "0" If Request Is Not Listed'' to make sure the users\n       know how to answer requests not on the list.\n\n After you enter the request number as ''0'' it will say ''Answering Request\nNot Listed'' to make sure you know what you just did. Now it will prompt\nyou with the users name that the request files are for. Hitting return\nwithout entering anything will bring you back to the menu. While entering\nthe users name, wildcards are fully supported to the same extent as they\nare when addressing a request message to a user. If you enter the user\nas your own name, you will be told to make it to another user only.\n\n NOTE: You can also address the message to ''Sysop'' or ''Sysop*''. Doing so\n       will send the message to the sysop of the board (again this can be\n       private or not).\n\n Also, you can make this answer private or not. After you enter a valid \nuser name it will ask if you want to make it private. If you want to, then\nthe message sent to the user about your files (should the sysop validate\nthe record) will be private.\n\n After you have completed this user entry and whether or not it''s private,\nthe name of the person that the request files are for will remain on screen.\nYou will now be prompted for a one line description as to what this request\nis. This prompt will be the same as the one line description when you are\nusing the ''Enter A Request'' option. If you enter no description you will be \nreturned to the main menu. If you do enter the description, then it will\nremain on the screen (will change color after you hit return if you have\nansi on) and you will move on to where you can enter the filenames of the\nuploaded files.\n\n Now from this point on when you have to enter the filenames, it is the\nsame as it is listed in the ''Answering A Request On List'' section right\non top of this section. Please see this section on how to enter the \nfilenames and all the options you can use from when doing it.\n\n NOTE: When you answer a request, nothing will take effect right away. \n       The record will be sent to the sysops so they can make sure that it\n       is valid. It''s then his choice to decide what to do with it. This\n       is to prevent people from entering fake answers just to award \n       themselves with credits.\n\n\n If you have sysop access and are putting a request up for a user, the\nway to do it is to fill out the answer record normally (whether on list or\nnot) and then select the ''Answer A Request'' option again on the main menu\nafter your done entering the record. You will now be able to self validate\nthe answer right away. Users do not have this advantage as you or one of\nyour sysops have to valid the record, the users can''t do it themselves. For \nmore on validating the answer records, please see the section on it.\n\n NOTE: Please note that if you answer a request, this request will then\n       be protected from anyone deleting or editing it until the sysop\n       decides to what to do with it. If the sysop validates the answer,\n       the request will be removed from the list. If the sysop rejects the\n       answer, then the request will be open to being answered, deleted, or\n       edited once again. More on this in the answer record section.\n\n=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n\n » 9c. Main Menu Option 3 - View The Request List «\n\n First off, if this option is selected and there are currently no reqeusts\non the list, the user will be told so and brought back to the main menu.\n\n When a user selects this option and their are at least one request on it,\nit will bring up the request list starting at the first request (Number 1).\nIt will always start at request number one, no matter which number is in\nmemory. The way it lists it is as follows. First, it will bring up the\nheader to make sure you know what is what on the list. For information\nabout the format of the request list, please see the section on it in\nthe ''Enter A Request'' option section. After this header, it will start\nshowing the requests in order from lowest to highest. It will show 6 \nrequests at a time, and then bring up the paused prompt where you can\nselect an option from here. Note that if there are currently less then\n6 requests to be shown at the time, the rest of the space will be padded\nwith blank lines.\n\n The options on the paused prompt are as follows:\n\n [J]ump To A Number\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n Hitting ''J'' will select this option. This will bring up a prompt asking\nyou which request number you wish to jump to. It can be any valid number\nof a request. Entering nothing will bring you back to the paused prompt.\nEntering an invalid number will also bring you back to the paused prompt.\nHowever, if you enter a valid number, it will then begin viewing the \nrequest list starting at this number. So if you enter the number ''4'',\nit will show you the request list starting with number 4 and continuing\nfrom 4 on up. \n The Jump prompt will also tell you the current valid numbers of requests\nso you know which numbers you can jump to. Min [ # ] will be the lowest\nnumber you can jump to, and Max [ # ] will be the highest request you can\njump to.\n\n NOTE: The memory feature will not work here. You will always have to \n       enter a number in.\n\n [V]iew Long Description\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nHitting ''V'' will select this option. This will bring up a prompt asking\nyou which request number you wish to jump to. Again, you will be told the\ncurrent valid numbers of requests so you know which ones you can view.\nMin [ # ] will be the lowest number you can jump to, and Max [ # ] will be\nthe highest request you can jump to. If you don''t enter a valid number or\ndon''t enter any number, you will be returned to the paused prompt.\n\n NOTE: The memory feature will not work here. You will always have to \n       enter a number in.\n\n If you do enter a valid number, you will be shown the information about \nthe long description of that request. This includes:\n\n -The normal request line from the list\n -The information about the message for the request if one was posted in\n  the format of:\n\n  Message:[      NONE/CONFERENCE/NUMBER/STATUS       ]\n\n  If no message was posted, then the message stats will come up as above.\n  If there is a message however, NONE will be whom the message is to,\n  CONFERENCE will be the name of the conf it is posted it, NUMBER will be\n  the number of the message, and STATUS will be if it''s private or not.\n  ''R'' means receiver only (private) and ''P'' means public.\n\n  So some examples of requests with a messages are:\n\n  Message:[        VAN DAMME/CeLL BLoCK/89/R         ]\n  Message:[           ALL/CeLL BLoCK/96/P            ]\n\n  If you don''t have the proper access to view a private request, then\n  the message will come up with the user it was sent to, and the status\n  of the message. The conference and number won''t be shown, as this are\n  the only real important items (because you already know who it''s to and\n  that the status is private). For example:\n\n  Message:[      VAN DAMME/CONFERENCE/NUMBER/R       ]\n\n -The users request number that this request was. If this was the users\n  first request, the number will be 1. If it was his fourth request, the \n  number will be 4 etc.\n -The complete 3 line long description included with the request. If no\n  long description was entered with the request, the long description box\n  will contain ''No Long Description Available''. If the request is private\n  and you don''t have the proper access, the long description box will\n  contain ''Private Long Description''.\n\n Once the long description info is shown, you will be returned to the\npaused prompt where you can select another option.\n\n NOTE: If you use the Continue option after viewing a long description of a\n       request, the continue will start listing at the request above the\n       one you just view. So if your viewing the long description of request\n       number 3, and then you select continue, it will start listing the\n       requests from number 4 on up.\n\n [Q]uit\n ¯¯¯¯¯¯\n Hitting ''Q'' while at the paused prompt will exit and bring you back to\nthe main menu. It doesn''t matter if your viewing a long description or\nthe list.\n\n [C]ontinue\n ¯¯¯¯¯¯¯¯¯¯\n If you select this option, it will continue viewing the list from the\ncurrent number you are at, whether viewing the list or a long description.\nIf your viewing the request list and select continue, you will continue\nto view the list starting this time from the highest number you have \nalready seen. So if your currently looking at requests 1-6, selecting\ncontinue will bring up the next 6, in this case 7-12. If there''s not 6\nmore requests, the amount there is will be shown only then. If your\nviewing a long description and select continue, it will start showing you\nthe list starting with the one after the one you were looking at. So if\nyou were viewing the long description of request 4, selecting continue would\nstart listing the request list from number 5 on up.\n\n NOTE: Selecting continue while at the highest request number (whether you\n       were view the list or long description) will cause you to exit and\n       return to the main menu. This is because there are no more requests\n       to view.\n\n Also note if you hit a key that isn''t a valid option, it will act as the\nContinue option. So if you hit say ''M'' or return, it will act as continue.\n(For more on this, see the section on menus in the door feature section.)\n\n=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n\n » 9d. Main Menu Option 4 - Remove A Request «\n\n When you select this option, it will prompt you for the number of the\nrequest you wish to delete (as it appears on the list). Entering an invalid\nnumber or a blank line will bring you back to the main menu.\n\n Now, if your don''t have sysop access, it will check the request number that\nyou have entered to make sure you have made that request. This is to make\nsure that people can''t delete requests they didn''t make. If you have sysop\naccess however, you can delete whichever request you like. \n\n Finally, it will check to make sure the request isn''t awaiting approval.\nThis means that someone has uploaded files and used the ''Answer A Request''\noption and the sysop hasn''t gotten around to validating it yet. If the\nanswer is awaiting approval, you will not be able to delete it and will\nbe returned to the main menu. For more on this see the section on answering\na request.\n\n Now, if none of these conditions are met and it''s a valid number, the \ncurrent request you wish to delete will be brought up. This includes the\nline from the list and any long description it might have. This is so you\ncan see what request you are about to delete to make sure it''s the right\none. You will now come to the delete prompt, where you can select an option.\nThe options are as follows:\n\n NOTE: The [R]eset All Stats option only appears if you have sysop access.\n\n [D]elete Request\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n This will bring up a ''Sure [y/N]?'' prompt. This is to make sure you really\nwant to delete the request. If you hit anything other then ''N'' you will\nreturn to the delete prompt. If you hit ''Y'' however, it will proceed to\ndelete the request. When a request is deleted, the following things will\noccur.\n\n -It will be removed from the request list. (If this was the last request on\n  the list, then the list will be deleted completly.)\n -Any long description will also be deleted.\n -The other requests on the list will be shifted into place to fill the\n  empty spot. All long descriptions will also be shifted.\n -The users stats will be updated to give him another request left. So if\n  the user that made this request had 3 requests left, he will now have 4\n  left.\n -If a message was written with this request, the message will also be\n  deleted from the conference it was written in. Note that the message\n  will be checked before it''s deleted to make sure it''s the original request\n  message. (in case you have reset the message base and the original request\n  message is now a new and different one). It also checks to see if the\n  original request message has already been deleted. If so, then it will\n  do nothing.\n\n [E]rase Range\n ¯¯¯¯¯¯¯¯¯¯¯¯¯\n This option will allow you to delete more then one request at a time. When\nyou select this option, you will be brought up to another prompt where you\ncan selete the range from which you want to delete the requests. The first\nnumber of the range will always be the number of the request you selected\nto delete from the main menu. Now you can select the end number for this\nrange. You will be also be told minimum and maximum number of the range\nyou can select. This min/max range is the only valid numbers you can use.\nEntering a number outside of this range will bring you back to the\ndelete prompt. So for example, if you went to delete request 4 from the\nmain menu option, and there''s currently say 10 requests, and then you\nselected the delete range option, you would see:\n\n Erase Requests From:[  4  ] To [     ]  Min:[ 1 ] Max:[ 8 ]\n\n You can now enter any number between 1-8. If you do enter a valid number\nin this range, it will list the requests on the screen inside of this range\nso you can see what you are deleting. For example:\n\n If you wanted to delete requests 4-7 in this case you would enter the \nnumber 7. You would then be shown requests number 4-7.\n\n If you wanted to delete requests 4-1 in this case you would enter the \nnumber 1. You would then be shown reqests number 1-4.\n\n NOTE: 4-1 and 1-4, or 8-3 and 3-8 etc. mean the same thing. It''s just the\n       range included that''s important, not which one comes first.\n\n Please note that if you don''t have sysop access, you still won''t be able\nto delete requests that aren''t yours. The program will check all the \nrequests in the range to make sure you have written them. If not, you will\nbe told and returned to the delete prompt. \n\n Also, you still won''t be able to delete requests that are awaiting \napproval. The program will check all the requests in the range to make sure\nthey are not awaiting approval. If they are, you will be told and returned\nto the delete prompt.\n\n After your shown the requests in the range, you will be asked if your\nsure to delete them with the prompt ''Sure [y/N]?''. This is to make sure \nyou really want to delete these requests. If you hit anything other then\n''Y'' you will return back to the delete prompt. If you hit ''Y'' however,\nit will proceed to delete the requests in the range you have outlined.\nWhen a range of requests are deleted, the follow things will be done:\n\n -They will be removed from the request list. (If there are no requests\n  left on the list when these are removed, the list will be deleted\n  completly.)\n -Any long descriptions will also be deleted.\n -The other requests on the list will be shifted into place to fill the\n  empty spots. All long descriptions will also be shifted.\n -The users stats will be updated to give them more requests left. \n  For every request a user made in this range, that user will then have 1\n  more request left to be made. For example, the user ''Bono'' currently\n  has 3 more requests that he can make. The user ''Eddie'' currenly has 4\n  more requests he can make. If you delete a range that contains 2 requests\n  that Eddie made, and 1 request that Bono made, Eddie will now have 6 \n  requests (4+2) and Bono will now have 4 requests (3+1) left.\n -If any messages were written with the requests in the range, then all of\n  these messages will be deleted from the conference they were written in.\n  Note that the messages will be checked before they are deleted to make \n  sure that they are the original request messages (in case you have reset \n  the message base and the original request messages are now new and\n  different ones). It also checks to see if the original request messages\n  have already been deleted. If so, then it will do nothing.\n\n NOTE: You cannot delete a range of more then 5 requests at a time.\n\n [R]eset All Stats\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n This option will only be available to you if you have sysop access. If you\nhave sysop access you will be able to use this option. The option will\nbe also shown in a different color (if ansi is so) to show the importance\nof it. Once you select this option you will again be asked if your sure.\nHitting anything other then ''Y'' will bring you back to the delete prompt.\nHitting ''Y'' will proceed to reset all stats.\n\n      *    -»    *    «-    *    WARNING    *    -»    *    «-    *\n\n Please use this option with CARE. If you use it, ALL the request items\nwill be removed. These items that will be delete are:\n\n -All user statistics will be reset.\n -Any request answers awaiting approval will be deleted.\n -Any deletion records of uploaded files will be deleted.\n -The request list will be deleted.\n -All long descriptions will be deleted.\n -All messages made with requests will be deleted from the conference they\n  were written in. Note that the messages will be checked before they are\n  deleted to make sure that they are the original request messages (in case\n  you have reset the message base and the original request messages are now\n  new and different messages). It will also check if the original request\n  messages have already been deleted. If so, it will do nothing. \n\n As you can see, this will do a total wipe of every record used by the\nrequest door. Use it only if your really want to start over again.\n\n Also, the stats will also be reset on the main menu and will all be at\nzero again.\n \n [Q]uit\n ¯¯¯¯¯¯\nPressing ''Q'' or return will bring you back to the main menu and quit the\ndelete option.\n\n=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n\n »9e. Main Menu Option 5 - Edit The Request List «\n\n When you select this option, it will prompt you for the number of the\nrequest you wish to edit (as it appears on the list). Entering an invalid\nnumber or a blank line will bring you back to the main menu.\n\n Now, if your don''t have sysop access, it will check the request number that\nyou have entered to make sure you have made that request. This is to make\nsure that people can''t edit requests they didn''t make. If you have sysop\naccess however, you can edit whichever request you like. \n\n Finally, it will check to make sure the request isn''t awaiting approval.\nThis means that someone has uploaded files and used the ''Answer A Request''\noption and the sysop hasn''t gotten around to validating it yet. If the\nanswer is awaiting approval, you will not be able to edit it and will\nbe returned to the main menu. For more on this see the section on answering\na request.\n\n Now, if none of this conditions are met and it''s a valid request number,\nyou will be brougt up to the editing screen. This includes the line of\nthe description from the request list, and also the long description.\nYou will now be brought to the edit prompt where you can select an option.\nThese option are as follows:\n\n [1] Edit User\n ¯¯¯¯¯¯¯¯¯¯¯¯¯\n This will allow you to edit the user that made the request. If you make\nany changes, this new name will function as the person that wrote it in\nevery manner. It will be as if that person had wrote the request. Be \ncareful when using this option. If you change the name to someone else and\nsave it, you will no longer be able to do anything to it because it will\nnow act as if that person had wrote it originally. (Unless of course you\nhave sysop access and can edit other peoples requests.)\n\n [2] Edit Description\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n This will allow you to edit the one line description made with the \nrequest.\n\n [3] Edit Long Descript\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n This will allow you to edit the long 3 line description made with the \nrequest. Pressing return will bring you down to the next line. However,\nif you press return on a blank line and there is no more description on\nthe lines below the current one, it will exit the editing and bring you\nback to the edit prompt. Note that the ''*'' under the ''L'' for the 1 line\ndescription will also update to show if there''s a long description or not\nif you make any changes.\n\n NOTE: The wrap around feature will not work here.\n\n [S]ave\n ¯¯¯¯¯¯\n Selecting the save option will save any changes you have made to the\ncurrent request. Any changes to the user name, short or long description\nwill now be saved as what you have changed them too.\n\n Here''s a really nice option I decided to put into use. If the request you\nare editing has a message, and you make changes to the request and save\nit, the information in the message for this request will also be updated to\nmatch these new changes. So if the request you are editing has a message\nincluded with it, and you change the short description and/or the long\ndescription, the changes you made will also be made to the request message.\n Also, if you have changed the username and the request has a message,\nthe person that the message is from will also be changed to this new user.\nSo if say Booger made the original request and posted a message with it,\nthe message would be from Booger. If you edited the request and changed\nthe username to Arnold, and saved it, that same message would now be\nfrom Arnold instead of Booger. Nice eh?\n\n  Note that the message will be checked before any changes are made to\n  it to make sure that it is the original request message (in case you have\n  reset the message base and the original request message is now a new\n  and different one.)\n\n [Q]uit\n ¯¯¯¯¯¯\nPressing ''Q'' or return will select this option. It will exit you from the\nedit prompt and bring you back to the main menu. \n\n NOTE: No changes will be saved unless you select the Save option. If you\n       exit the request editing without saving the changes you have made,\n       they will be lost. Also note you can edit private requests normally\n       the same way you would edit any other request.\n\n=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n \n »9f. Main Menu Option 6 - Edit Request Stats «\n\n You will only be able to use this option if you have sysop access in the\ndoor. If you don''t, this option will be disabled from the main menu. This\nis because you don''t want normal users editing their own or other peoples\nrequest stats. From this prompt you can edit 3 different types of things:\n\n -Entering the name ''Prefs'' will allow you to edit the doors preferences\n  through the internal editor. This should be done when you first run the\n  door or when you wish to change one of the settings. For more info on\n  this, please see the section on preferences.\n -Entering the name ''Total'' will allow you to edit the Total request\n  stats.\n -Entering any valid user name will allow you to edit that users request\n  stats. \n\n Please note while entering names in the ''Edit User:'' prompt, that wildcards\nare again fully supported. See the section on wildcards on how to use them.\nAlso note that wildcards will work when entering any type of name. For\nexample, entering ''Pr*'' or ''Pr'' would bring up the wildcard prompt for\n''Prefs'', and ''T*'' or ''T'' would bring up the wildcard prompt for the ''Total''.\n\n NOTE: A user will only have a statistic file if he has run the door before.\n       Once a user runs the door for the first time, he will have one made\n       for him. If a user has never run the door before, then he will have\n       no request statistic in the door. If a user has no request statistic,\n       you won''t be able to edit it because it doesn''t exist.\n\n Editing Preferences\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n Entering the name ''Prefs'' through wildcards or normal will bring you to\nedit the doors configuration through the internal editor. This is the best\nway to edit the preferences. For more info on what each option is for, \nplease see the section on preferences. Once you are done editing the prefs,\nyou will be returned to the main menu.\n\n Editing The Total Stats\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nEntering the name ''Total'' through wildcards or normal will bring you to\nedit the total stats for requests. There will be only 2 stats to edit here,\nthe Total Requests and Total Answered. You will now be brought to the edit\nstat prompt where you can select an option.\n\n  -[1] Edit Requests\n   ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n Selecting this will allow you to edit the total requests made.\n\n  -[2] Edit Answered\n   ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n Selecting this will allow you to edit the total answered requests.\n\n  -[S]ave\n   ¯¯¯¯¯¯\n Selecting this will save all the changes you have made to the total stats.\n\n NOTE: Any changes that have been made will show on the main menu info\n       boxes when you select the save option.\n\n  -[Q]uit\n   ¯¯¯¯¯¯\n Pressing Q or return will quit the statistic editing and bring you back\nto the main menu.\n\n NOTE: No changes will be saved unless you select the Save option. If you\n       exit the stat editing without saving the changes you have made,\n       they will be lost. \n\n Editing A User Stats\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nEntering the any valid user name that has a statistic file in the door\nthrough wildcards or normal will bring you to edit the statistics for this\nparticular user. There are 3 stats to edit here, Total requests,\ntotal answered, and total left. The options you will be able to select now\nare:\n\n  -[1] Edit Requests\n   ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n Selecting this will allow you to edit the users requests made.\n\n  -[2] Edit Answered\n   ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n Selecting this will allow you to edit the users answered requests.\n\n  -[3] Edit Left\n\n Selecting this will allow you to edit the amount of requests the user\nhas left that he can make. For example, if you set the user to have 2 \nin this stat, then that user will be able to make 2 more requests before\nreaching his maximum limit. Note, you will not be able to set this number\nhigher then the maximum number of requests per person preference. If you\nenter a higher number, you will be told what the highest number you can\nenter is, and then be you will be prompted to enter a lower number. You will\nnot be able to leave enter you enter a valid number lower then the max.\nThis is because a user cannot have more requests left then set in the\nmaximum number of requests per person stat.\n\n NOTE: If you have the maximum number of requests per person disabled, you\n       will not be able to edit this stat because the users will have\n       unlimited requests left. A ''DIS'' will appear beside the ''Requests\n       Left'' prompt and you won''t be able to edit it.\n\n  -[S]ave\n   ¯¯¯¯¯¯\n Selecting this will save all the changes you have made to the users stats.\n\n NOTE: Any changes that have been made will show on the main menu info\n       boxes when you select the save option if the user running the door\n       is the one your editing, sense these are his stats shown there.\n\n  -[Q]uit\n   ¯¯¯¯¯¯\n Pressing Q or return will quit the statistic editing and bring you back\nto the main menu.\n\n NOTE: No changes will be saved unless you select the Save option. If you\n       exit the stat editing without saving the changes you have made,\n       they will be lost. \n\n=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n \n » 9g. Main Menu Option 7 - Exit Program « \n\n This option is the easiest of them all to use. In short, when you select\nthis option it will exit you from the program and bring you back to the bbs.\nPressing return from the main menu will also select this option.\n\n=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n\n » 10. Request Answered Approval Record Screen «\n\n There are two ways to get to this answering a record screen. The first is\nif you have sysop access and you run the door and there are request answers\nawaiting approval. This will bring the answer a request record screen\nup instead of the main menu. The second way is if you have sysop access\nand you select the ''Answer A Request'' option from the main menu. Instead\nof the normal option, this screen will come up instead. This means that\nif you have sysop access, you won''t be able to use the normal answer a\nrequest option until all answered approval screens are taken care of.\n\n NOTE: When running the door, the answered deletion screen will take \n       priority over this one and will always come up before it.\n\n This screen appears when someone has used the answer a request option and\nfilled out a record for approval. This record will be shown to you on this\nscreen so you can decide what to do with it. This screen was made for the\nco/sysops to decide what to do with upload request files. To either award\nthem if they are valid, or to delete them if they are fake or wrong.\n\n NOTE: This is the screen that the logon awarding bulletins are made for.\n       It''s from this screen that you can do everything to the answer \n       records. When the logon bulletins come up, this is where you want to\n       get to. For more on this see the preference section.\n\n When this screen comes up, you will be shown the following items:\n\n The first line will contain the number of the record that it is. This \nnumber of the record will match up with the number of the request that is\nanswered here. So if request number 5 is answered here, the record will\nbe number 5. If this answered request was not on the original list (They\nused ''0'' for the number in the answer a request option) then no number will\nbe listed here. It will simply be ''Request Answered Approval Record''. This\nfirst line will also contain the program name again, just to see who spent\nall his time writing the door again. (:\n\n The second line will contain the name of the user that has answered the\nrequest. This is the person that will or will not be awarded. It will\nalso contain the conference name it was answered in (where the files are\nlocated) and the date that it was answered on in the format ''Month-Day''\n\n After this second line, it will show the one line description of the\nrequest as it appeared on the request list. For the format of how this\none line description is set up, please see the section on the request list\nin the enter a request section. (Although it should be pretty obvious\nanyway what each item is for.) The long description for this request will\nalso appear if there is one. If not, a ''No Long Description'' will appear\nin the long description box. Note, that if the request here answered\ndidn''t appear on the original request list (as described just above in\nthe number of the record section), then the number in the one line\ndescription will be ''...'' to show it isn''t a real number on the list, and\nthe long description will appear as ''No Listing Available''. Private\nRequests will also appear as normal, with a ''!'' appearing before the\nshort description (and a different color in ansi).\n\n The next five lines will contain the names, descriptions, original sizes,\nand dates (the normal filelistings) for the files that are waiting to be\nawarded. If you have less then five files, the extra lines will be blank.\nThese are the files that the user has uploaded to answer the listed request.\n\n After the filelisting will contain the information needed for the reward.\nThese items include:\n\n Users Uploaded:  This is the amount of bytes that the user being awarded\n                  has uploaded so far. Please note here that this value of\n                  bytes will have the Request bytes removed from it already.\n                  So this value is how much the user has uploaded not\n                  including the bytes he has received for uploading the\n                  request files. So if the user had 289384 bytes, and then\n                  uploaded 1 file for 29384 bytes, the users uploaded\n                  value will still be 289384 because this is what he had\n                  before he sent the request files. This is set up this\n                  way so if you set the award to times 0 (x0) you will \n                  remove the original request bytes.. More on this later.\n\n Request Bytes:   This is the total bytes of all the request files that \n                  were uploaded. This value will be subtracted from the\n                  Users Uploaded stat described above.\n\n Award x#:        This is the current award that the user will receive for\n                  the upload files. The current award will be the request\n                  bytes times the current award (#). So if you have a \n                  Request Bytes of 10000 and an award of 5, you will have\n                  an award of 50000 (5*10000).\n\n NOTE: The default number that will appear as the award amount is set\n       from the preferences. The number you set in there is the one that\n       will appear here.\n\n Total:           The total stat will be the users new uploaded bytes after\n                  the new award has been added. It''s the award bytes +\n                  the original users uploaded stat.\n\n NOTE: These values will be updated on the screen everytime you change\n       the award amount. However, the only stats that will change are the\n       Total and Award values. The Users Uploaded and Request Byte stats\n       are fixated and will not change when the award is.\n            \n After being shown these stats, you will be brought to the award prompt. \nFrom here you can select an option as follows:\n\n [C]hange Award\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n This option will prompt you for a number to which it will change the award\namount. The minimum amount you will be able to change this value to is\nzero, and the maximum you will be able to set it for is 99. Giving a user\n99 times award is abit rediculous, but it''s up to you if you ever want to.\nIf you enter any valid number then the request award will be changed to\nthis value and the stats will all be changed to show this new number. You\nwill then be returned to the award prompt to select another option.\nEntering an invalid number will return you to the the award prompt without\nmaking any changes.\n\n Note, the current total for the user works as follows. It will be \nhis current uploaded byte stats without the bytes he received from\nuploading the request files, plus the current awarded bytes amount. Because\nthe bytes from the request files are removed from his original uploaded\nbyte stat, it will allow the award amount to work as follows:\n\n x0 Award: This will mean the original bytes for the request files are\n           removed. The user will receive no credits for the uploaded files.\n           It''s as though you have nuked the file with a -1 credit award\n           with a faker utility.\n\n x1 Award: This will give the user the original bytes back for uploading\n           the files. This also means that there is no award, since he''s \n           just getting back the credit for the original uploads.\n           The total bytes he will now have will be the same as when\n           he uploaded the request files.\n\n x2 Award: This will give the user the original bytes back for the uploaded\n           files times two. So if he had uploaded 100000 before the requests,\n           and then uploaded 20000 of requests,and then you gave him a times \n           2 award, his new stat would be:\n  \n In Numbers:           (120000-20000)      +       (20000*2)      = 140000\n  In Words :   (Original Bytes-File Bytes) + (File Bytes * Award) = Total\n\n This makes sure that times 2 is an actual times 2 award. Some programs\n don''t take into consideration that you have already receieved credits for\n uploading the files. This one does. If you left the original request\n bytes plus the award, it would make the total 160000, which is not a times\n 2 award.\n\n On that stat screen, the (Original Bytes-File Bytes) Will be the ''Users\n Uploaded'' stat, The (File Bytes * Award) will be the Award x(#) stat, and\n the whole equation (Original Bytes-File Bytes) + (File Bytes* Award) will\n be the ''Total'' stat.\n\n x3 Award: Same as x2 but the award stat will be 3 and not 2..etc.\n\n Now for a few real life examples to try to make some sense out of that.\n\n Example 1:\n\n You call your favourite BBS and decide to join the request conference\nto see if there''s anything you have that someone might need. You see\nupon the list a request for lemmings 2 made by some user. Since\nyou have these files, and your so nice, you decide to upload them to the\nrequest section and answer the request through the request door. Before you\nuploaded these request, you have currently uploaded ''1,500,000'' bytes to\nthis board. Since the size of these files altogether were ''800,000'', your\nuploaded byte stat is now at ''2,300,000'' (1500000+800000). Later that\nday, the sysop logs on the board and the request door comes up with\nthe answer a record approval screen with your answer record. Your\nUploaded Bytes stat will be at 1,500,000 - the original bytes before you\nuploaded the request files. The sysop decides you give you a times 2 award\n(x2), so the total amount of bytes you will be awarded with is 1,600,000\n(800000*2). This 1,600,000 bytes of award is then added to your original\nbyte size, so you now have a total uploaded bytes of 3,100,000. The way\nit gets this value is your original bytes of 1500000, plus the award of\n1600000, which is 3100000. \n\n Example 2:\n\n NOTE: This example is not meant to portray you or anyone else around the\n       boards. It''s just an explanation of what could or might happen. \n\n You have nothing better to do one day so you decide to mess around on\nsome board. You call one of the BBS''s around town and join the request\nconference. You then decide to uploaded some fake requests to try to\nget some easy credits. Your total uploaded stat on the board is currently\n100,000 before you upload the files. After uploading 500,000 of files, your\nnew stat is now 600,000 (500000+100000). You then fill out the answer\nrecord in the request door to try to get more credits through an award.\nA few minutes later the sysop runs the door and up comes your record. Your\nUploaded Byte stat comes up as 100000 since that''s what you had before \nuploading the request files. The sysop changes the award to 0 to remove\nthe files since they are obviously garbage. Because the award amount\nis zero, your total uploaded bytes stays at 100000, which is what you had\nbefore uploading the files. So you received no credits for your lame attemp\nat credits, and still have what you did before uploading the files. The\nsysop then proceeds to delete you from his board. (:\n\n\n It works this way for all the awards. If your confused by what I''ve just\nsaid somehow, load the door up, make your own answer record, and play\naround with the changing the award amount. Watch how all the stats get\nchanged around when you change the award amount. You''ll see it all makes\nsense and is really easy to figure out once you understand what''s going on.\n\n NOTE: Changing the amount to 0 will cause the request to be removed. More\n       on this in the award user section below. Anything higher then 0 \n       will be deemed a vaild request.\n\n [S]kip Record \n ¯¯¯¯¯¯¯¯¯¯¯¯¯\n Since more then one award record can exist at a time, this option can\ncome in handy. It will allow you to skip over the current record and move\nto the next one if one exists. This helps if you want to ask a user or\nfind some info about the files before you decide what to do with them.\nIf you select this option and another record does not exist, then it will\nact as the quit option below. If there is more then one record, you can\nthen use this option to scan through them all and pick which ones to award\nat that time.\n\n [A]ward <Username>\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n This option will proceed to award the current <Username> (Where username\nis the name of the user that appears in this spot) with the amount of\nbytes that is in the award stat box. His new stat will now match the\nstat in the total box. Instead of awarding, you can also remove this record \nwithout changing anything else if the files aren''t what are supposed to be.\nIf the value of bytes inside the answer box is at ''0'' it will remove\nthe record. If the value of bytes inside the answer box is higher then\n''0'', it will conside it a valid request and award it. \n\n NOTE: The easiest way to make the answer box read 0 is to change the\n       award amount to 0.\n\n When you select this option you will first be asked if your sure to award\nthis record. Hitting ''N'' will bring you back to the award prompt, hitting \n''Y'' or anything other then ''N'' will proceed to award the request.\n\n Award Bytes Above 0\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n  When you award a request and the award byte is currently at anything\nabove ''0'' it will be consider valid and will be awarded. The following\nthings will then happen.\n\n -The users uploaded stats will be updated to show this new credit award.\n -The files that the user sent will be made freedownloads if you have this\n  option turned on in the preferences.\n -The filelistings for the files will be updated to show that these files\n  have been awarded. The comment that will appear as the filesizes for these\n  files will be as you have set it in the preferences. See the preference\n  section for more on setting it. If you have this option off, then\n  the filelistings will not be changed.\n -This record will be removed from the waiting award list.\n -A deletion record will be made for the user that these files are for.\n  This is so he can remove the files when he''s done downloading them.\n  For most on these records, see the section below on Request Deletion\n  Records.\n -The user that answered the request will have his stats updated to show\n  he has answered one more request. The total awarded stats will also be\n  updated.\n -The original request will be removed as if you had used the ''Remove A\n  Request'' option and then used the ''Delete Request'' option at the\n  delete prompt. This includes the long description, the 1 line description,\n  the message, removing 1 from the users requests left stat, and everything\n  else as described for this option. For more on this, please see the\n  matching section. Note, the reason for removing the request is because\n  it is now considered answered, so no use keeping it around any longer.\n -If you have the message option on, it will proceed to send a message\n  to the user that had requested the files. This is to let him know that\n  someone has uploaded the files he wanted. The answered messages subject\n  will be ''ANSWER [#]'', where # is the current number of answered requests\n  that have been made. The message will also include the conference the\n  files are uploaded to, the filenames of the files, and it will also\n  be private or public, depending on what the original request was.\n\n NOTE: If you award a person and that user is currently online, then it will\n       tell you so and the record will be skipped. This is because you \n       can''t change a users stats while he is online. It will be the same\n       as selecting the skip option. You can then go back and award the\n       request when the user isn''t online anymore. However, if the user\n       that is receiving the award is currently running the door, it will \n       use the internal values to set his stats so it won''t be skipped.\n\n Award Bytes At 0\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n You could make the award set at 0 for several reasons. The files that\nwere uploaded may no longer be needed, they could be fake, or mabey the\nuser uploaded the wrong files by mistake. Either way, this is an easy\nway to remove the files and the record without touching anything else.\n\n  When you award a request and the award byte is currently at ''0'', it will\nthen conside the request fake and removed the record. The following things\nwill then happen:\n\n -The bytes that the user receieved for uploading the files will be \n  removed.\n -If you have the ''Comment For Delete Files'' preference set on, then the\n  filesizes for the files in the filelists will be replaced with this\n  Comment. So if you have the comment set for ''»OFFLINE«'', then all files\n  in this record will have their filesizes as ''»OFFLINE«'' in the lists.\n -It will proceed to delete the files from the current conference that\n  they are located in. Please note that it will search all of the upload\n  paths outlined in the conference/paths file (2.x) or the conference.info\n  file (3.x) for the location of the files. It will however always check\n  the conference/upload directory first. If the files aren''t found here, it \n  will then proceed to check the other upload paths listed for your version\n  of ami-express. As soon as it finds all the files, it will stop looking\n  for them.\n -It will remove this answer record from the door so it won''t come up\n  again.\n\n [Q]uit\n ¯¯¯¯¯¯\n This option will exit you from the answered approval screen and bring you\nto the main menu of the request door. Pressing ''Q'' or return will select\nthis option.\n \n=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n\n » 11. Request Answered Deletion Record Screen «\n\n There are two ways to get to this deleting a record screen. The first is\nif you have a request deletion record in the waiting (meaning you have\nrequest files still on the board still that you haven''t removed) and you\nrun the door. This will bring the delete a request record screen instead\nof the main menu. The second way is if you have a request deletion record\nwaiting and you select the ''Remove A Request'' option from the main menu.\nInstead of the normal option, this screen will come up instead. This means\nthat if you have a deletion record, you won''t be able to use this normal\nremove a request option until all of your deletion records are removed.\n\n NOTE: When running the door, this screen will take priority over the \n       answered approval record screen and will always come up before it.       \n\n This screen appears when you have request files that have been uploaded\nfor you and you haven''t delete these files yet. This screen will allow you\nto delete the files off the board when your finished downloading them\nto free up the space taken by the files and to make sure that there aren''t\nhundreds of past request files floating around the board. Once your done\nwith the files, this option will allow you to remove them from the board.\n\n When this screen comes up, you will be shown the following items:\n\n The first line will contain the number of the deletion record. This number\nmatches up with the total number of requests answered at the time this\nrecord was made. For example, if this record is from the 4th request\nanswered, this record will be number 4. If this record is from the 22nd\nrequest answered, this record will be number 22. The first line will also\ncontain the program name again - VDRequest 3.0 of course.\n The second line will contain the users name that the record belongs too.\nAfter this, the next line will have the name of the conference that these\nfiles are located in.\n The next five lines will contain the names, descriptions, original sizes,\nand date (the normal filelistings) for the files that are waiting to be\ndeleted. If you have less then five files, the extra lines will be blank.\nYou will then be brought to the deletion prompt where you can select an\noption. These options are:\n\n [D]elete Requested Files\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n Again this will be in a different color (if you have ansi on) to show the\nimportance of it. When you select this option, it will first ask if your\nsure to delete the files. Hitting ''N'' will bring you back to the deletion\nprompt. Hitting ''Y'' or anything other the ''N'' will proceed to delete the\nfiles. When the files are deleted, the following things occur:\n\n -If you have the ''Comment For Delete Files'' preference set on, then the\n  filesizes for the files in the filelists will be replaced with this\n  Comment. So if you have the comment set for ''»OFFLINE«'', then all files\n  in this record will have their filesizes as ''»OFFLINE«'' in the lists.\n -It will proceed to delete the files from the current conference that\n  they are located in. Please note that it will search all of the upload\n  paths outlined in the conference/paths file (2.x) or the conference.info\n  file (3.x) for the location of the files. It will however always check\n  the conference/upload directory first. If the files aren''t found here, it \n  will then proceed to check the other upload paths listed for your version\n  of ami-express. As soon as it finds all the files, it will stop looking\n  for them.\n -If the message options are on, it will proceed to delete the answer message\n  that was sent to this user telling him that his files had been uploaded.\n  It will delete it from the conference it was written in. Note that the \n  message will be checked before it''s deleted to make sure it''s the original\n  answer message. (in case you have reset the message base and the \n  original answer is now a new and different one). It also checks to see if\n  the original answer message has already been deleted. If so, then it will\n  do nothing.\n -It will remove this deletion record from the door so it won''t come up\n  again.\n\n NOTE: If you use this delete option and you have more deletion records, you\n       will be brought to them. If you have no more records and you delete\n       the current one, you will be brought to the main menu as if you had\n       selected the quit option.\n\n [S]kip Record\n ¯¯¯¯¯¯¯¯¯¯¯¯¯\n Since one user can have more then one deletion record at a time, this\noption can come in handy. It will skip over the current record and move\nto the next one if one exists. If another record does not exists, then\nit will act as the quit option below. If you have more then one record,\nyou can use this to scan through them all and decide which one you want\nto delete.\n\n [Q]uit\n ¯¯¯¯¯¯\n This option will exit you from the answered deletion screen and bring you\nto the main menu of the request door. Pressing ''Q'' or return will select\nthis option.\n\n=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n\n » 12. Callerslog «\n\n Whenever a major activity is done in the door, it will be recorded in\nthe callerslog for that node. This includes the entering of a request, \nthe deletion of a request, the approval of a record, etc. Minor things\nlike viewing the list will not be recorded.\n\n NOTE: For things like editing the list and stats, it will only record\n       it if you actualy save the changes.\n\n The callerslog will also record the time that the door was started and\nfinished at.\n\n=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n\n » 13. Sysop Pointers «\n\n Because I have been running and testing this door for about a month\nand a half now (the time it took to write it and these docs), I have\npicked up a few pointers that you might be able to find useful.\nPlease note that these are JUST advice on the way I think it should be\nrun. If you think differently then by all means ignore what is said.\n\n If your using Ami-Express v3.x, it''s advised that you not use the\ndifferent conference ratio enforcer which holds the credits in each\nconference seperatly. You can still use it if you want, no problems here.\nBut, if the main reason your users upload requests is to get credits,\nI don''t think many users would want to upload request for other people\njust to gain more request bytes. (If you have a request conference that is).\nThe users on my board (and I hope most) upload requests to help other people\nout. And because they are helping out, I reward them with the credits for\nthese uploads. If they want to download amiga or snes etc files with them\nthen that should be their right. I personally don''t like the ratio\nenforcer thing myself and would never run it on my board, but that''s just\nme. \n\n Make sure to move the offline filelistings every once in awhile to either\nan offline filelisting area, or just delete them all together. 5 pages\nof offline request files is a bitch to scan through. I move all the request\nfiles that are now offline to an offline file listing about once every one\nor two months. This only takes a second and helps things looking nice.\nI will be adding an option to move or delete them by itself soon, but\nfor now your stuck doing it by hand. Once again, you don''t need to by\nany means. I have sometimes left them for like 6 months at a time without\nany problems at all.\n\n Use your head when validating answers. If one user seems to be answering\ntoo many requests that are originally not on the list, make sure these\nrequests are valid ones and it''s not just him trying to get alot of credits.\n\n Try to set the award at around x2 - x4. The users uploading requests files\ngo out of their way to get and upload them, so they should be given\na proper award. I have it set for x3 which works nicely. Not too much and\nnot to small.It keeps them coming back for more and my request section stays\nactive. For a really large upload (like 5 disks at 880k) you might want\nto limit it to x2, or even x1 and let them just keep the original bytes\nfor the files. Either way, see the section on changing the award for\nthe way it works in awarding them before you decide.\n\n Put one user or a few (cosysops are good for this) users in charge of\nlooking after the requests, making sure to keep an eye on things and to see \neveryone is getting what they want. Also to make sure no one is doing\nany funny stuff. These people can also advise users that can''t seem to\nfigure out how to work a certain option. Or to let them know about some\nof the special options available to them. (Until the help options are\nset up in a future version). If you get a normal user to do this which\nis sometimes the case, set his access to sysop while in the door so that\nhe can use all the options (see the preference section on how to do this.)\n\n Posts notices that you have installed the door, and try to get your users\nactivly involved with them. The users on my board try to answer requests\njust because its alot of fun to play around with the door.\n\n If someone is messing around with the door, like entering alot of fake\nrequests or messing up the list with board adds or something, restrict\nhis access from the door and keep him from spoiling it for the other users.\n(See the preference option on how to do this).\n\n=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n\n » 14. Future Developments «\n\n Quite a few options are now in thought for future versions of the door.\nSome of the ones I have come up with already are:\n\n -A Download Protect door to keep users from downloading other peoples \n  private requests. This will also work independant of the request door.\n -Keeping more detailed statistics on each user.\n -Allowing sysop to list all current Deletion and Answer records.\n -Disabled of deletion records for boards that have alot of space online.\n -Sysop allowed to activate any delete record if user doesn''t do it.\n -Moving of deleted filelistings to an offline filelist.\n -A Complete help system while online for the user to view.\n -Messages sent to users that still haven''t deleted files after a certain\n  time.\n\n If you have ANY ideas, I''d love to hear and put them into use. Please\nfind some way to get ahold of me (usually on my board) and I will do my\nbest to add the options you want. After all the door is meant for you.\nIf you would also like to help me test my utilities, also let me know.\n \n=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n \n » 15. Credits «\n\n\n All Coding: .................. Van Damme.\n\n All Documentation: ........... Van Damme.\n\n Major Testing: ............... Van Damme.\n\n Assistance Testing: .......... Doc, White Ic, Doc Whoo, Oldman.\n\n All Ideas For VDRequest: ..... Van Damme.\n\n All Concepts For VDRequest: .. Van Damme.\n\n Opinions/Suggestions/Help: ... Marky, Doc, Mr. Bit, Illuvatar, Doc Whoo,\n                                Oldman, Echo, Zandor, Nzo, White Ic, \n                                Frantic, Proteus, Illicit Trader, Torment,\n                                Blade, Cooey.\n\n Music: ....................... Pearl Jam, U2, 10,000 Maniacs, Sound Garden,\n                                Metalica, The Doors, Nirvana, 2 Unlimited,\n                                Danzig, Gun And Roses, Alice In Chains, and\n                                Tori Amos. (All of which who''s great music\n                                kept me awake on many a night while hard at\n                                work.)\n                                \n Movies: ...................... Braindoners, Dr. Giggles, Kickboxer, \n                                Hellraiser (2 & 3), Hot Shots, Under Siege. \n\n Food: ........................ Pizza, Skittles, Pringle Chips, KFC Chicken.\n\n Drinks: ...................... Coke, Sprite, Labatts Ice Beer, Labatts \n                                Blue, Jack Daniels, Vodka.\n \n Entertainment: ............... Lemmings 2, Walker, Batman Returns (Snes).\n\n Sleep: ....................... Hardly.\n\n=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n\n » 16. FreakWare Registration «\n\n FreakWare is meant to be to Ami-Express what Unreal is to Ascii. I have\nstarted this label in attempt to make a steady source of quality and\nrealiable Ami-Express utilities. However, nothing can be done alone and\nI need other people to work with me on this one. If you have written a new\nutility or are still working on one, and you think it''s good, then drop me\na line so we can get together to talk. \n\n For all worthy utilities that are shared with me, I will be willing to:\n\n A. Help you with testing the program.\n B. Help you document the program.\n C. Give you ideas on ways to improve it.\n\n I hope this is a way to get a new generation of utilites running on our\nboards worldwide. But I do need your help. Please apply today.\n\n The only current place to register your utilites is on my board which\nis DeATHRoW. However, if things start moving which I hope they will, then\nI will be looking for other boards, users, and sysops to help in the effort\nas well.\n\n\n Please note that this is no way means that if your already with a group\nyou cannot be apart of this. FreakWare is NOT a group. It is simply a \nlabel to show that the utility has been tested and proven to be a quality\nand realibly product.\n\n            \n              Only people serious about their work need apply!\n\n             - The Time For Different Is Now © FreakWare 1993 -\n\n=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n\n » 17. History «\n\n v1.0 : -First Version. Only Options Were Enter And View A Request.\n v1.1 : -Added Deletion Of Request List.\n v2.0 : -Added Deletion Of Range Instead Of Entire List. Completly Changed\n         Door And Request List Look. Much Better Now. Many Other Improvments\n         Made.\n v2.3 : -Made Configuration Section Into A Seperate Preference File Instead\n         Of Including It In The Acutal Program.\n        -Fixed A Bug In The Reading Of The Request List.\n        -Now Cuts Request If It''s Too Long Instead Of Telling You To Make It\n         Shorter.\n v2.3a: -Removed ''See Ya Later!'' Message When The Door Exited.\n        -Compiled Size (63485)\n        -First Public Release.\n v3.0B: -2.3a Program Code Thrown Out. Program Rewritten From Scratch. \n        -Beta Version - Released Privatly For Testing Only\n v3.0 : -Many Options/Changes From Intial v3.0 Beta Release\n        -Public Release Under The © FreakWare/LSD Label\n        -Source Size (99996)\n        -Compiled Size (396728)\n\n=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n \n » 18. Greetings And Thanks «\n\n Greetings to ALL sysops that use my utilities and ALL Ami-Express coders\nthat have greeted me in their programs. Be assured I have read all of them\nand I''m doing my best to call all of your boards.\n\n Thanks to Pharoah for when along time back, he gave me the original idea\nfor making up a request door. His idea was for a program that could make a\nlist of requests to keep track of them. I have added much to this original\nidea, but he got me started on it.\n\n Thanks to Virtual of Delusion for help on the message equation that will\nnow get the date of it right. I have no way of knowing how you figured it\nout, but I used this equation just as you wrote it. \n\n And where would I be without all my friends....\n\n Skol - So ya went back to anthrox after all. (: Keep training!\n Nzo - I have just one word for you. "Intro".\n PMF - See ya when you come to visit. And Thanks for passing word to beast.\n /\KiRA - I still can''t get the LCFiles in 3.3 to work. It''s annoying me!\n mUb - Thanks for the ascii''s. Got um in use now.\n Phideaux! - Hope to hear from you again soon. Don''t stay away too long.\n Ceejay - Greets Mate. Save me a brewskie - make that whiskey, and alot.\n Zen - Always my best friend around! (: But you lost touch!\n Echo - Your are truely the best musician I know. Other then myself of coz!\n Kidlat - Got any more ideas for me. I''d love to hear them.\n Zandor - My right hand man. Thanks for everything.\n Illicit Trader - Cheers to my new console sysop.\n Gilby - You should call me more! I may have PC one day.\n AxeL - Where''d ya go. I miss our chats.\n King Conan - Thanks for the update ideas. Keep the doors coming.\n Denon - Thanks for the update ideas as well. Really Appriciated.\n Eddie The Head - Bah. Cnet.. Trader! (:\n Iceman - Too bad you shut your board down. Keep in touch.\n Alberta - Good luck with the board. I''m sure it will work out.\n Esskayare - Stop reading Nzo''s mail! hehe\n TsM - How''s the weather in germany friend.\n Shen - My last greet to you since your now gone. Oh well, it was great\n        knowing you. Live long and prosper!\n Sinatra - Long time no talk. Don''t ya hate canada phone systems.\n Kitaro - One day your lha checker will work again. \n SkyLark - You really are the Number One Skull Brother. Use your account!\n The Biker - The brotherhood rules ya all. Get my board on the logoff! (:\n Blade - Hiya lefty!\n MetalBasher! - You really are the ascii Genius! Call for the /X help.\n Pazza - I hope to see GV 16 out soon... looking forward to it.\n Boomer - Make some ascii''s for my board..pretty please!\n Easy Rider - You like U2 also so your cool! hehe\n D-Man - The most modest person in the scene today. No joke!\n Byteandi - I won''t forget my roots. I just have trouble calling out \n            overseas. Thanks for the greet, but just remember who had the\n            first (and best) weektop for different confs. (:\n Axe - I love the way you did the doc for the descriptor util. Keep being\n       original. It''s nice for a change.\n Delusion - I still need the NUP for your board.\n Prizm - Thanks for all the help lately. Don''t forget the Skinny P. tape.\n Grim Reaper - See ya at the pearl jam concert! Mabey. (:\n John Yaya - Thanks for all the 3.x help. \n Will Scarlett - Your cool so I great ya anyway.. hehe\n Beast - Glad to see you called back.\n Psiq - Thanks for the replacment copy of sensible soccer.\n Eniac - Love your DMS Check/adder. Nice work!\n\n Of course to all LSD members that call my board, and those that are going\n to call after reading this! (:\n\n Greetings To The Fellow Ami-Express Coders:\n\n Dr. G, Sigma Seven, Cool Falco, Maltese Falcon, Nosferatu, Pot-Noodle, \n Caffeine, Dux, Spock, GiapDJ, Trash, The Bird, Axeman, Shadow Man, \n Delusion, Andy, Empire, Thrash, Bobo, Byteandi, Re/Yo, Colorboy.\n\n    If I have someone managed to miss or forgot you, please let me know.\n\n=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n\n » 19. Last Words «\n\n Here I am, at the end of another VD Program. I think this is my best\neffort yet, as I just keep seem to be getting better. This program and\ndocument has taken me 1 & 1/2 months to finish. The documenation probably\ntook longer then the program did. I''m sure that this is the longest doc and\narexx utility ever written for an ami-express door. And I guess I had to\nbe the one to do it. I''m sure my next utility will be in C as well, I got\nalittle sidetracked creating this one.\n\n To get off topic for a sec, if you use 3.x, then leave the ''Ndirs'' and\n''Paths'' file in the conference. As alot of utilites still use these. Not\neveryone has time to update them for the new changes. Also, try to leave\nthe new conference access as ''XXXXX'' etc as most utilities use this format.\n\n And something I have to say to J. Hodge. You write a great program, no\nproblems there. But I would suggest you slow down on the updates and start\nreleasing newer versions with actually visable changes. Pretty soon\nyou''ll be up to 3.99, and then what - 4.0? I don''t even have the 3.3\ninstalled correctly yet. Also, it is possible to update things without\nchanging it so much that past utilites don''t work. I know this is probably\nthe least of your worries, but me and every other coder would really hate\nto have to update our utilites every time you put a new version out. I would\nmuch rather work on something new then trying to fix an old program. \n\n And finally, for those that are still wondering, I''m only 18, I live in\ncanada, and I love to have a good time. That''s it, see ya soon in another \ngreat utility on a board near you. Until then!\n\n\n                         -» INSTALL AND ENJOY «-\n\n\n                                           Signed...  Van Damme/LSD (TW,SA)\n\n','\n',char(10)),'{"LOCATION":"Doors:VDRequest/VDRequest","ACCESS":"50","TYPE":"AIM"}','auto-added',215360,1,0,NULL,NULL,'lsd_vdrq','scan',1780048582);
INSERT INTO door_catalog VALUES('lt_sb_13','LT-SB_13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LT-SB_13.LHA','AUTOconvert','XIM','AUTOSENT',NULL,NULL,'LT','.----/  \/ /-------------------------------. |   / />  < LIGHTSPEED TECHNOLOGIES BRINGS | |--/_//_/\_\--.----------------------------:',replace('      __  __\n.----/  \/ /-------------------------------.\n|   / />  < LIGHTSPEED TECHNOLOGIES BRINGS |\n|--/_//_/\_\--.----------------------------:\n| Ami-Express | LT-AutoSentBy v1.3  TyCooN |\n| Multimailer | 100% NO BACKDOORS   DL IT! |\n`-------------^----------------------------''\n','\n',char(10)),'autosent.guide',replace('@database LT-AutoSent V1.3\n\nCopyright (C) 1994 by Lightspeed Technologies, Written by Tycoon/MYSTIC\nAll Rights Reserved\n\n@Remark $VER: LT-AutoSent V1.3 (Apr 19 1994, 20:41:04)\n\n@node MAIN "LT-AutoSent V1.3 - (C) 1994 by Lightspeed Technologies"\n     ___ __ ___ ______ ___ __ ___ _________________________________ _\n    /  /<_/<__/<_____//  /<_//  /<________________________________// \\n   /  /   ___ ______ /  <__ /  <__ ______ ______ ______ ______ ___/  /\n  /  /   /  //     //     // ____//  ___//     //  ___//  ___//     /\n  \  \___\  \\  \  \\  \  \\     \\___  \\  \  \\   __>\   __>\  \  \\n   \_____>\__>\__   >\__\__>\_____>\_____>\   __>\_____>\_____>\_____>\n              ___> /                      /  /\n   (C) 1994  <____/      TECHNOLOGIES    <__/         PRESENTS\n\n\n                           LT-AUTOSENT  v1.3\n\n      =------- Makers of -------=     @{"      INTRODUCTION      " LINK WEL}\n        AmiExpress BBS SoftWare       @{"      REQUIREMENTS      " LINK REQ}\n        MultiMailer - UUCP/FIDO       @{"      INSTALLATION      " LINK INS}\n        Ami-X-Net Netmail-Stuff       @{"         GREETZ         " LINK GRZ}\n      =-------------------------=     @{"   DEVELOPMENT BOARDS   " LINK DEV}\n@endnode\n\n@node WEL "Introduction - (C) 1994 by Lightspeed Technologies"\n\n   Welcome to this util released by Lightspeed Technologies!  Because the\n   version of "Byteandi" has a little backdoor or something! We have made\n   another one WITHOUT any backdoor or possibily to ''kill'' your bbs.\n   The sent-by versions of Byteandi (below 1.4) have a BIG BACKDOOR that\n   can DELETE/FORMAT your harddisk!!\n   We won''t tell you how it is done, but be warned not to use older\n   SendBy utilities.\n\n>> It is simple a REPLACEMENT for the old autosent versions from byteandi <<\n>> You need to install  the Fileid V1.5 and autosent first before you can <<\n>> use this REPLACEMENT.                                                  <<\n\n\n                                @{" BACK " LINK MAIN}\n@endnode\n\n@node REQ "Requirements - (C) 1994 by Lightspeed Technologies"\n\n               The hardware and software you need to run:\n               ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n  - An Amiga with Kickstart 2.04++ (else /X 3.xx won''t work)\n\n  - The installed Ami-Express-Software (/X 3.20++)\n  \n  - Fileid V1.5, autosent V1.2 or higher.\n\n  - AUTOconvert to convert old sent.dat files to the new ones.\n\n\n                                @{" BACK " LINK MAIN}\n@endnode\n\n@node INS "Installation - (C) 1994 by Lightspeed Technologies"\n\n                      Install it on your harddrive\n                      ~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n  Installing it is very simple like this:\n  \n  - Use AUTOconvert to convert your old SENT.DAT to the new one.\n  \n  - copy the autosent over the old version.\n  \n  Now you are ready. Test it now and if it''s not working 100% then must\n  remove the SENT.DAT because you were not using the right one! Sorry but\n  then all your users have to insert their tagline again. (Who carez,\n  your bbs is ''save'' again!!!)\n\n\n                                @{" BACK " LINK MAIN}\n@endnode\n\n@node GRZ "GREETINGS - (C) 1994 by Lightspeed Technologies"\n\n\n                            MANY THANKS TO:\n                            ~~~~~~~~~~~~~~~\n\n      ByteMaster        - Great working with you man..\n      The Outlaw        - Let''s sell about 10,000 ami-express packages\n      GEERT-JAN         - Co-Writing Ami-MultiMailer & Server.\n      KiLLRAVEN/MYSTiC  - Beta-Testing and Supporting my BBS.\n      EMPiRE/MYSTiC     - Beta-Testing & Suggestions \n                          Wanna Buy Some cdrom players ???\n      Blackout/???      - Beta-Testing MM (MultiMailer)   \n      Easy Rider/MYSTiC - Beta-Testing MM & Call more to my board man..\n      Pharaoh/SKIDROW   - Beta-Testing MM and how''s live over there ?\n      Muad''dib          - Beta-Testing MM & Try to beat us......\n      SIMON SOFT        - Thanks for all Help with first versions and\n                          keep up the fine crack work ;-)))))\n      Chaplin & Stony   - Thanks for the 25000 resets for enforcer\n                          hits for the server!  Chat you later man.\n\n                     ALL PEOPLE WHO SUPPORT AMI-X FIDO\n\n\n                            GREETINGS GO TO\n                            ~~~~~~~~~~~~~~~\n\n      Rayon             - Yes.. Keep up the fine Pictures for channel X\n      Sal-one/TSRi      - Blablalblallalallbllbllala\n      Boozer            - What is happening to your bbs ???\n      Cable             - Let''s play Cardguppies ;-)\n      Paul Dean         - Still interested in FIDO ??\n      Kool Falco        - How''s live at the other side of the ocean?\n      Planetmaster      - Shit man... buy more nodes.. always busy\n      Wizz              - When do you install the MultiMailer???\n      ALCOHOLIC         - Your always drunk\n      Axe/MYSTiC        - How can i forgot our great leader hahhahaha\n      HardByte/MYSTiC   - How''s Coding ??\n      BYTEANDi/?????    - YoHo, stop complaining about some utils ;-)\n                          And stop make utils with backdoors or what you\n                          call it ;-(\n      RE/Y\O/MYSTiC     - Fix your great chatter soon.\n      Domino/TRSi       - Hhhha.... saw you on killraven his party tape ;-)\n      Van Damme         - Nice Doors, hope you will be back soon!!\n      Mike              - Get yourself a brand new Cosysop man !!!\n      Koo Koo Ka Choo   - Ask the Outlaw for more info about fido!\n      MAD HARLEQUiN     - Hey man... Install the multimailer and send me\n                          some nice messages ;)\n      BadBoy (stranger) - You ready SUXXXX man.... Shithole, try to get\n                          your points at school man hahahahahahahahaha!\n\n      AND all members of MYSTiC around the globe and all other cøøl guyz.\n\n\n    \n                :+:+:+: BETTER THAN PLAYBOY CHANNEL :+:+:+:\n          ____________  __________  ____  _______  _______________\n         /       /   /\/  /   __  \/    \/  /    \/  /       /   /\  K\n        /  _____/   /_/  /   /_/  /        /        /  _____/   /  \ L\n       /  /____/   __   /   __   /   /\   /   /\   /  __/__/   /___/ R\n      /       /   / /  /   / /  /   / /  /   / /  /       /       /\ !\n     /_______/___/ /__/___/ /__/___/ /__/___/ /__/_______/_______/  \\n     \       \   \ \  \   \ \  \   \ \  \   \ \  \       \       \  /\n      \_______\___\/\__\___\/\__\___\/\__\___\/\__\_______\_______\/\n       \n   - - -- --- --------------- ^ ---------- ^ ---------------- --- -- - -\n                             /:\__      __/:\\n                            /:::\ \    / /:::\\n      /X-Fido Mail WHQ      \::::\ \  / /::::/   A2000/040/882 @ 33Mhz\n                            /\::::\ \/ /::::/\\n      /X-MultiMailer EHQ   /  \::::\  /::::/  \   AmigA/SneS/PC/18PluS\n                           \   \::::\/::::/   /\n      /X-Development EHQ    \   \::::::::/   / sys: TyCooN & KiLLRaVeN\n                             \   \::::::/   /\n      MySTiC /X-PoWeR! EHQ   /   /::::::\   \  cos: EMPiRE & EasyRider\n                            /   /::::::::\   \        \n      Reg. Ami-Express     /   /::::/\::::\   \      2 Nodes with USRs\n                           \  /::::/  \::::\  /      \n      Busy Message Bases    \/::::/ /\ \::::\/  Node 1: +31-2290-62244\n                            /::::/ /  \ \::::\         \n      2 Gig & CdRom On-Line \:::/_/    \_\:::/  Node 2: +31-2290-62535\n                             \:/          \:/\n                              V            V\n\n\n                                @{" BACK " LINK MAIN}\n@endnode\n\n@node DEV "Ami-Express Development boards"\n\n                     OFFICIAL /X Development boards\n                     ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n                 Sysop : ByteMaster\n                 Board : ByteMaster''s BBS -> /X-DEV WHQ\n                 Number: +1 703-PRI-VATE\n\n                 Sysop : TyCooN\n                 Board : CHaNNeL X,  /X-Development EHQ\n                 Number: +31-2290-62244  +31-2290-62535\n\n\n                                @{" BACK " LINK MAIN}\n@endnode\n','\n',char(10)),NULL,'auto-added',18687,2,0,NULL,NULL,'lt_sb_13','scan',1780048582);
INSERT INTO door_catalog VALUES('lt_scan','LT-SCAN.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LT-SCAN.LHA',NULL,'XIM','LE-window6.12',NULL,NULL,'LT','/ | /  \/  \/   \ \_ Y  |     LooNyScaN /  |/_ o \ O \ |  \/  |  |   a lITTLE /X \____/___/___/_|__/\___  |__   dOOR tHAT',replace('  _   __  __  ___  ___ __.\n / | /  \/  \/   \ \_ Y  |     LooNyScaN\n/  |/_ o \ O \ |  \/  |  |   a lITTLE /X\n\____/___/___/_|__/\___  |__   dOOR tHAT\n\__  ___/ \/  \/   \/ |  |_/ sCANS fILES\n  |  |/  O \ o \ |  \____|  sENT tO yOUR\n  |__|\____/___/_|__/LT96  bBS fOR vIRII\n%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%\nnOW tHERE wILL bE lESS vIRUSES iN wAREZ!\n[41;33m===  [L^S^D]=[WELSH COAST][+44 FIND IT]  ===[0m\n','\n',char(10)),'CLASS.README',replace('                      ·\n     .:::::··   ·     : ·\n   .::''  _______    .:::.   _________     rIOT..: - WHQ  JORMAS..: - GHQ\n  .:''  ._\_    /__ .:   :.__\  _____/___. ABYSS.: - GHQ  NUANCE..: - EHQ\n  :·   |     _/   ::     ::  \----.     | GODS..: - GHQ  SYNDROME: - GHQ\n  :    :--.________:.   .:''_____________| mONO..: - GHQ  sUKMAS..: - GHQ\n  :                 :. .:                         ·\n  :               .  ::: .· >>LOS·ENDOS·BBS<<     :\n  :    ____________   :       _____   ________  .:::.    _________\n  :  ._\_____     /___·_____ |     |__\____   \.:    :.__\  _____/___.\n  :  |    _/_____/    |     \|     |      /   ::     ::  \----.     |\n  :  :--._____________|____\ \     |-.________/:.   .:''--.__________|\n  :                  cDr/e^d\______|            :. .:\n                                                 :::      _ _ __  _\nnODE0: +49-(0)-02103-lOCAL   -   33.6k v.34 sOON! :    __/\\__ _ __  _\nnODE1: +49-(0)-02103-52440   -   33.6k v.34 sPEED      \ Oo¯//_ _   _\nnODE2: TELNET 194.163.210.xx -   19.2k !vARIABLE!      / ø _\\__ _  __\nnODE3: TELNET 194.163.210.xx -   19.2k !vARIABLE!      ¯¯\//¯¯_    __\n                                                          ¯\n   - t H I S   i S   d A   b O A R D   f O R   t H E   d E M O S C E N E -','\n',char(10)),NULL,'auto-added',18972,7,0,NULL,NULL,'lt_scan','scan',1780048582);
INSERT INTO door_catalog VALUES('ltx_kil2','LTX_KIL2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LTX_KIL2.LHA',NULL,'XIM','LATEX PRESENTS: NUKER','2.0',NULL,'LTX',NULL,replace('LATEX PRESENTS: NUKER V2.0\n','\n',char(10)),'killer.doc',replace('\n              __________________  __\n             /\  /_\___   _/ __ \/ /\n            / /_/ _ \ / /Y/ _/ >  <\n           / __  // / \/ |\ / / /\ \\n           \/  YY \/     : Y  \/  YY\n               .         .        .:\n\n                    PRESENTS\n\n\n\nKiller V2.0 (c) 16.12.1993 by Quickfinger/LATEX\n\nWhat is it:\n\nKiller is a file-nuker for C-NET BBSs (>V2.79).\n\n\nFeatures:\n\n- nuke credits up to 999 times\n- reward credits up to 999 times\n- automail to "nuked" user\n- optional deletion of file from the hd\n- optional entry of nuker, nukecause and a message into the scanlist\n- different file and byte nuke values\n- password protected, let only your favourite users use it\n- able to use predefined macro definitions for fast usage\n\nInstallation:\n\n- copy the files KILLER and KILLER.LIST to pfiles:\n- enter the following line to your cnet-startup:\n\ncopy pfiles:killer.list ram:env\n\n- add the following line to your bbsmenu(s) under "5; Respond or Pass?"\n  in the last line (before 6;)\n\n   NUKe  |#0pfiles:killer}|\n\n(it should look like:\n\n   :\n   .\n	Z, SEArch\n	VOte\n	Yank\n	<\n   NUKE  |#0pfiles:killer}|\n\n6; News/GFiles/PFiles\n	Off\n\n- add the following line to line 424 of your bbstext(s) at the END:\n\n#0ram:env/killer.list}\n\n\n- reload bbstext/menu (CNET Pulldownmenu!)\n\n- load pfiles:killer into an editor and change the macro until it pleases you\n  (and save it, of course)\n\nFinished!\n\n\n\n\nUsing killer:\n\n\n- Read the enty you want to nuke (R <number>)\n- Enter NUKE at the prompt\n- Enter NUKE CLEAR to clear the current nuketext (">>>>> BLABLA <<<<<")\n- Enter NUKE CLALL to clear ALL nuketexts of that subboard.\n\n\nAfter that you will be queried for the password (if you are not sysop-ag).\nOtherwise you will be asked if you want to use the fast-macro.\n\nIf you use the fast macro, everything will just scroll through, you don''t\nhave to do anything (isn''t that wacky, loony and zany :).\n\nAnswer the prompt with NO and you will see the information of the\ncurrent file.\n\nThen you will be asked, if you want to delete the file (not recommended when\nrewarding credits :*)\n*WARNING* If you answer with YES, the file is gone.. gone... GONE!\n\nAfter that you will see the most important prompt Reduce/Reward Credits.\nAnswer with no and the program quits.\nAnswer with yes and you will be queried for the times you want to reduce the\ncredits (file and byte separated).\n\nThen you will get a list what happened to the user''s credits.\n\nAfter that the user will get his notification (via message). So he will\nsee who nuked his files and how many creds he''s got left.\n\nAt last you will be asked what text should appear in the scanlist...\n\nThe last prompt "Does that look ok to you" applies to the FILESCAN only!\nIf you cancel here, the credits are still gone.\n\n\nHope the program is usable and installable. If you can''t install it, simply\ndon''t use it.\n\nIf you encounter any heavy bugs or hidden features.. then give me a call:\n\n\nParanoia Complex BBS\n\n++49(0)6251-75324\n++49(0)6251-75059\n++49(0)6251-787728\n\nSysop: Quickfinger (YEAH that''s me!)\n\n\n\n\n                 .oOo.L/\TeX - International Board-List.oOo.\n\n\n    White House #1 -   Whq  - +49-030-8059056 - Sysop:      Ice, Co: Hammer\n                #2 -          +49-030-8059057 -\n    Barracuda -        Ehq  - +49-02594-80017 - Sysop:         Uncle Unkewl\n    HountedHouse -     Ghq  - +49- 09227-2542 - Sysop:  Blowfly, Co: Cedrix\n    Paranoia Complex - Ghq  - +49-06251-75324 - Sysop:          Quickfinger\n                              +49-06251-75059 \n                              +49-06251-787728 \n    Perfect Illusion - Hq   - +49- 02595-7611 - Sysop: Blastaar, Co: Cedrix\n    Scaffold -         Hq   - +49-030-4061402 - Sysop:               Beavis\n    Cleptomania -      Hq   - +49-(very soon) - Sysop:       Breaker (soon)\n    Special Forces -   UShq - +1-412-981-8337 - Sysop:          Machine Gun\n    Continuum -        UShq - +1-609-461-7062 - Sysop:                 Mr.Q\n    Damaged Justice -  UShq - +1-215-529-9621 - Sysop:                Leper\n','\n',char(10)),NULL,NULL,6320,1,0,NULL,NULL,NULL,'scan',1780048582);
INSERT INTO door_catalog VALUES('ltx_olm1','LTX_OLM1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LTX_OLM1.LHA',NULL,'REXX','_______',NULL,'ICE/LTX/PREOGRESS','LTX','_______    _________________________|      / \      |__/  ___ \     _ /__    /   |    _/| |\     |  \_ __/  \    \/ _/   /_   _    \_|',replace('                                     _______\n_______    _________________________|      /\n\      |__/  ___ \     _ /__    /   |    _/|\n|\     |  \_ __/  \    \/ _/   /_   _    \_|\n| \        / \     \_  |  \___/ /   |     /|\n|  \______/___\     /__|_______/    |____/ |\n+--------------\___/---------\______|Rpd!--+\n| presents: OnlineMessage v1.1 (/X +- 3.xx)|\n|          by ICE/LTX/PREOGRESS            |\n`------------------------------------------''\n','\n',char(10)),'olm.doc',replace('                                                   __________\n                                                   \       |\n _ ____/\  _ __ _/\__  ________/\________/\________/\__    | /\_ __ _  /\____ _\n         \_\\\_\\  _/  \ __  _/   /    _/   /    _/   /    |/  //_///_/\n              _\   |___/\\/  _    \_  _    /\    ____/_    /   _/_\n            _/     | _/  \_  _     ____\ \/  \_  /     \_         \\n            \_   _ _     _/  \ CoZ  / _/ _   _/  _     _/  _       \_\n _ ___________  /__|\__ _____|\__  /  \___\ ______\__ ____/| latex  _________ _\n              \/       \/        \/        \/        \/    |________/\n                     \n                      p   r   e   s   e   n   t   s \n\n\n\n                    O N L I N E  M E S S A G E  v1.1\n\n      (O.L.M. v1.1) © 1993 bY ICe/LATEX^PROGRESS ® bY LATEX`93(tm) \n\n\n\n                         What is Onlinemessage\n                         """""""""""""""""""""\nOnlinemessage is a additional Commands for the communication form one \nnode to the other. This tool is able to use the internal amiexpress \nwho command. \n\n\n\n                          System requirements\n                          """""""""""""""""""\nFirst U need an Amiga Model (500-4000) with the installed Kickstart V37++,\na full Version of Amiexpress V2.3x or higher to work correctly.\n\nThe archive "ltx_olm1.lha" contains the following files:\n\n             1.) olm.rexx              - The Main Program\n             2.) olm.cfg               - Configuration File\n             4.) olm.info              - Icon for /X V3.xx\n\n\n\n                     Installation of OnlineMessage\n                     """""""""""""""""""""""""""""\nFirst, youe have to create a drawer called "DOORS:olm/", copy the files\n"olm.rexx" and "olm.cfg" into this drawer.\n\nThe further Installation depends on which Amiex-Version you`r using OLM.\n\nInstall OLM to  /X V2.3+ :\nGet a Texteditor and add the following lines to yar BBS:COMMANDS/BBS.CMD\n\n-----------( cut here )-------------------\n*OLM       RM020DOORS:OLM/OLM.rexx\n-----------( cut here )-------------------\n\n\nInstall OLM to  /X V3.xx :\nCopy olm.info into your BBS:COMMANDS/BBSCMD/ Drawer.\n\n\nThen edit the olm.cfg file to set the maximum number of running nodes.\nDOORS:OLM/OLM.cfg\nWith the second option you can disable the copyright string.\n\n------( cut here )-------\n2\n^-----------------[maximum numbers of nodes]\n1                                                                  \n^------[1 = display copyright bar; 0 = don`t display copyright bar]\n------( cut here )-------\n\n\n\n\n                          What can OnlineMessage\n                          """"""""""""""""""""""\nYou can send a 2 line messages from one node to other. At the command promt\nyou can use the internel who command to display some informatons about the\nthe other nodes.\nIt does do some checking though to make sure that the node your are trying\nto send the message to is actually there and that there is someone loggedon\nthat node.\n\nIf you have any problems or find some bugs  call me at:\n                         Gotham City(49-(0)30-805-9056) and ask for help.\n\nThe only thing that I ASK for your use of this little tool is that you give\nme a call at Gotham City and tell me what ya think of it and any ideas that\nyou have for the next version.\n\n                        Commands at the MainPrompt\n                        """"""""""""""""""""""""""\n\n(?)         --->  Online Help\n\n(WHO)       --->  Call internel Who Command\n\n(®) ALT+R   --->  Call the Creditz Part\n\n\n                            G R E E T I N G S \n                            """""""""""""""""\n\n      Greetings to all Members of LATEX & Progress and the rest.. 8)\n\n\n','\n',char(10)),NULL,NULL,20371,1,0,NULL,NULL,'ltx_olm1','scan',1780048582);
INSERT INTO door_catalog VALUES('lzx_idfx','LZX_IDFX.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/LZX_IDFX.LHA','LZX','XIM','LZX',NULL,NULL,'LZX','\      ______/\      ______/\::/    \titan: :\/    \/    \:\/    \/  -   \/  _   \1995: :/      \     \/      \  |   /   |    \::::',replace('____________________________    ____\n\      ______/\      ______/\::/    \titan:\n:\/    \/    \:\/    \/  -   \/  _   \1995:\n:/      \     \/      \  |   /   |    \::::\n:\  ____/ ____/\  ____/ _|___\  _|____/::::\n+-\/----\/------\/----\/------\/----------+\nBring Ya File Id Fixed to support LZX Files\n+-----------------------------------------+\n','\n',char(10)),'SSP_LZXCheck.doc',replace('        -^-v-^- - - -- ---v-^- - -- - - --^-v-^- - -- --^-v--^-- -\n            SSP_LZXCheck v1.0  Code:Blast/Sunshine Productions\n      - -^- -- -^-v-^- -^-v-^- -  --- -- -- -v- --^-v-^-^-v-^-- -- -\n\n       Liability\n       ~~~~~~~~~\n       If your computer crashes, your car blows up, your\n       girlfriend leaves you, your cat becomes pregnant,\n       your dog begins to walk under the ceiling,or your\n       TV  begins  to  transmit ''V'' 24 hours a day, it''s\n       not  MY  fault,  and  I  take  NO  responsibility\n       whatsoever   for  the  (mis)performance  of  this\n       program...\n\n\n       General Information\n       ~~~~~~~~~~~~~~~~~~~\n     - What is this LZX anyway?\n\n     - LZX is a new compression algorithm developed by Jonathan\n       Forbes, the creator of many programs including the good\n       old LZ and XenoLink (the BBS system)...\n\n     - So ? What does that help me?\n\n     - The thing with LZX is that it''s quick, and compresses far\n       better than any other compression program including LHA and\n       Shrink.\n\n     - But is this something only for the Amiga or what?\n\n     - Nope! LZX will be coming in a PC version soon as well,\n       so it''ll be multiplatform available for the public..\n\n     - Ahuh, and what if I''ve got, say a BBS or something and\n       want to be able to use it, like check if files are ok\n       that are compressed with this LZX, what do I do?\n\n     - This is where LZXCheck comes in, you simply enter the\n       filename on the mainline and it checks the file!\n\n     - Wow! It''s just that simple.. wow..\n\n     - Yeah, and you can add files to the archive as well..\n       Adds and stuff.. But the limitation right now is\n       that LZX itself can''t add multiple files on one go,\n       that is only available when registered.. I''ll\n       be coming out with a new version as soon as I get my\n       hands on a registered LZX, so that it''ll be possible\n       to specify a file that LZX will read what files\n       to add to the archive...\n\n     - But I can still add one file, right?\n\n     - Yeah, right now you can add ONE file to the archive..\n       And in the registered LZX you''ll be able to strip\n       files from the archive as well... I''ll add that\n       feature like I said, when I get the registered\n       version...\n\n\n       Installation\n       ~~~~~~~~~~~~\n     - But how do I do for AmiExpress for example?\n\n     - You just copy the directory called SSP to your\n       DOORS: and the icon LZX.info to your BBS:FCheck/\n       and change the options to whatever suitable...\n\n     - Ok! How do I specify an add file?\n\n     - The information in the icon should look something\n       like this:\n\n                               ---- CUT ----\n       CHECKER=DOORS:SSP/SSP_LZXCheck/SSP_LZXCheck.exe\n       OPTIONS=-A DOORS:SSP/SSP_LZXCheck/AddFile\n                               ---- CUT ----\n\n       You can forget about the rest, it is set as it should,\n       don''t change it!\n\n       The CHECKER= is the path to the checker... Leave it at\n       that...\n       The OPTIONS= string is configured like this:\n\n       If there is a -A in it, then Adding is enabled, then\n       you change the S:MyAddFile to whatever you want,\n       this is the file that will be added...\n       If you DON''T want any adding, only testing, just delete\n       the OPTIONS= field or put a semicolon in front of it\n       like :\n       ;OPTIONS=-A DOORS:SSP/SSP_LZXCheck/AddFile\n\n       Nothing more, nothing less...\n\n       DON''T FORGET TO ADD THIS FILETYPE TO THE DIZ DOORS AS WELL!\n\n       For example for ByteAndi''s FileID door:\n\n       extern_LZX_ADD=c:LZX -q a %P %WFILE_ID.DIZ\n       extern_LZX_EX=c:LZX -q e %P %WFILE_ID.DIZ\n\n       Bugs\n       ~~~~\n       Bugs? Nah, ain''t none... But if you find one, just call\n       my Board and tell me about it and I''ll fix it right\n       away...\n\n       History\n       ~~~~~~~\n       V1.0 - First release... What you see is what you get!\n\n       Future\n       ~~~~~~\n       To make it work with the registered version with multifile\n       adding and stripping, I''ve got to get hold of the\n       registered version first though.. Well, any other ideas\n       are welcome! Just call Napalm at +46-8-894595 and tell me\n       about it!\n\n       Greetings goes to:\n       ~~~~~~~~~\n\n       The Eagle.: You''ll get it back soon.. I promise!\n\n       Mr.Coke...: Is your board ALWAYS busy or what?\n\n       Nightshade: Have you changed the output of that ''c'' door YET?\n','\n',char(10)),NULL,'auto-added',118437,9,0,NULL,NULL,'trsi_tl2','scan',1780048582);
