INSERT INTO door_catalog VALUES('m_bbss03','M!BBSS03.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/M!BBSS03.LHA','status','XIM','status',NULL,'BiLBo',NULL,'\_     \  /    \  _   |   :/     \_    \ _|  \_/ \/   7  \/|   |   |   7   \  |  \__ |   |   \   j   \|   |   :   j   /  |   \',replace('_/\____    ___________.   ² _______/\___\n\_     \  /    \  _   |   :/     \_    \\n_|  \_/ \/   7  \/|   |   |   7   \  |  \__\n |   |   \   j   \|   |   :   j   /  |   \\n |   |    \______/l___l___j\_____/l__|    \\n_l___jdn  /_presents another /X door_l____/\n     l___/       BB-Stats v0.3\nSystem-Status door for Sigma Express that\nshows the users status and a little who.\n XIM Module written by BiLBo BaGGIns/MoTiON\n','\n',char(10)),'status.guide',replace('@DATABASE "BB-Stats Documentation"\n@AUTHOR "BiLBo BaGGIns/Motion"\n@REMARK $VER: "BB-Stats v0.3 (09-08-94) by BiLBo BaGGIns/Motion"\n@HEIGHT 30\n@WIDTH 78\n@INDEX main\n@Node main "Guide to BB-Stats v0.3 by BiLBo BaGGIns/Motion"\n\n  .%%%................%%%....%%%..........%%/\%%.%%%......%%%....%..%....%%\n .%%.%%%%%%%%%%%%%%%%%%.%%%%%%.%%%%%%%%%%%%/  \%%%.%%%%%%%%.%%%%%%%%%%%%%%.\n %%/(_________________/(_____/(___________(____)%/(______%%|\___%.____.%%.%\n %%\                 /      ~\\             /  |//      ~\%|.   \|   ~|%%%.\n .%%\  /\           //   |:   \\  ..   .   /   |/    |    \||    \    |%%%%\n  .%%\/            //    |.    \_/||   |\_/|   |     |.    \|         |%%%.\n ..%%|.  (\   /)   \\          /%%|:   |%%|:   |\          /:   \     |%%. \n ..%%||   \\_//     \____.    /%%%|_   |%%|.___|%\__.     /|.   |\    |%%%.\n ====||    \==\\   /=====|_  /======\__|==|/========|__._/=|____|=\___|====\n %%%%|______\..\\//%%%%%%%%)/%%%%%%%%%%%%%:%%%%%%%%%%%%Y%%%%%%%%%%%:%%%%%%%\n %%%%%%%%%%\/%%%\/%%%%%%%%%°%%%%%%%%%%%%%%.%%%%%%%%%%%%:%%%%%%%%%%%.%%°Adi·\n   ·%%%%%%%%%%%%%%%°·····°%%%°··········°%%%°·········°%%°········°%°··\n        +-------------------» PRESENTS IN 1994 «-------------------+\n\n                               BB-Stats v0.3\n\n                        dONE bY BiLBo BaGGIns/MoTioN\n\n                     @{"          iNTRODUCTION          " link "Intro"}\n                     @{"          iNSTALLATION          " link "Install"}\n                     @{"          iNSTRUCTIONS          " link "Instr"}\n                     @{"          fUTURE pLANS          " link "Plans"}\n                     @{"              bUGS              " link "Bugs"}\n                     @{"             gREETS             " link "Greet"}\n                     @{"           lAST wORDS           " link "Last"}\n                     @{"            cALL nOW            " link "Call"}\n\n\n@endnode\n@Node Intro "---> Introduction <---"\n\n Sigma Express from the newer versions on started an system-door called\n status everytime a user loggs on after the mailscan. At the begining we\n started there the who door coz we had no cewl status door in C. After\n some days I was so happy with the who command, that I didn`t want to miss\n it so I decided to code a combined who and status door.\n\n Features:\n - showing the Users status and a who\n - nice designs (thx to Treach)\n - C for more speed\n - running on Sigma Express and /X 2.xx only\n - no backdoors as usually from me\n\n\n                           @{" Back to main menu " link "MAIN"}\n@endnode\n@Node Install "---> Installation <---"\n\n Extract the whole Status archive to your SYSTEMS drawer in BBS:.\n That`s all.\n\n\n                           @{" Back to main menu " link "MAIN"}\n@endnode\n@Node Instr "---> Instruction <---"\n\n The door will be started everytime a user loggs in and show his Status\n and all the other Users that are already logged in.\n\n\n                           @{" Back to main menu " link "MAIN"}\n@endnode\n\n@Node Plans "---> Future Plans <---"\n\n - no future plans at the moment\n\n\n                           @{" Back to main menu " link "MAIN"}\n@endnode\n\n@Node Bugs "---> Bugs <---"\n\n No known Bugs at the moment. This version runned on Deep Space Nine\n for 2 monthes.\n\n\n                           @{" Back to main menu " link "MAIN"}\n@endnode\n\n@node Greet "---> Greetings <---"\n\n                              Greetings go to\n          Sisko/MoTioN....................trading all night&days\n          Spider/Osiris.................thx for help in coding C\n          Giants/TYT.................thx for ya sources and help\n          tHe aDDiCt..............................keep on coding\n\n          BBC/MTN...Andy/MTN...E.F.A./PDX...Eazy-E/ORS...jMS/MTN\n          Disque Bleu/MTN....Striker/ORS....Fnord/MTN......Q/MTN\n          Calypso/GOD^LGC.....\X/arhawk/LGC....Schwabenpower/MTN\n          Treach...Sagor/HLM...Tango/ORG...Jordan...............\n\n                       all MoTioN members worldwide\n                     and all the rest I have forgotten\n\n           Thanx for the help on releasing this door must go to\n          Treach..........................................dezign\n\n                            and my testboards\n   dEEP sPACE nINE       - MoTioN GHQ (busted)        S!X - Sysop: sISKO\n\n\n                           @{" Back to main menu " link "MAIN"}\n@endnode\n\n@Node Last "---> Last Words <---"\n\n                      Other MoTioN /X tools avaible:\n\n Multi-Diz....................New DIZ system for all files.............Andy\n News In All Conferences......Showing `n s u` in all conferences.......Andy\n On-Line-Message..............Sending online message...................Andy\n OnLineBulletinsUpdater.......Updating bulls if ya wanna se it.........Andy\n PlaY-PeN-PaRt-UpLoAD-MoVeR...Moves files after a system crash.........Andy\n LHADo........................LHA-Checker/Stripper/Adder................BBC\n Textstripper.................Text-Stripper/Adder.......................BBC\n Dream Status.................Status door.....................BiLBo BaGGins\n StarTrek.....................Star Trek comment door..........BiLBo BaGGins\n Frontstatus..................Frontend door...................BiLBo BaGGins\n Userlist.....................Creates userlist bulletin.......BiLBo BaGGins\n FileIDAdd....................Add your line to FileID.........BiLBo BaGGins\n User Answer Shower...........Shows the new user answers......BiLBo BaGGins\n SendAnswer...................Sends User Answer to Sysop......BiLBo BaGGins\n BB-Stats.....................System STATUS for S!X...........BiLBo BaGGins\n\n                      MoTioN -  The Force that moves\n\n\n                           @{" Back to main menu " link "MAIN"}\n@endnode\n\n@Node Call "---> Call Now <---"\n\n                          MoTioN boards worldwide:\n\n FASTWAY             WHQ  6 Ndz RD: +49-7-BUSTED!!!! DST 21.6  Andy\n                          2 Ndz RD: +49-7-BUSTED!!!! ISDN\n DEEP SPACE NINE     WHQ        #1: +49-7-BUSTED!!!! V32.bis   Sisko\n                          2 Ndz RD: +49-7-BUSTED!!!! DST 21.6\n                          2 Ndz RD: +49-7-BUSTED!!!! ISDN\n SANITARIUM          GHQ        #1: +49-8-BUSTED!!!! DST 28.8  jMS\n                                #2: +49-8-BUSTED!!!! DST\n                                #3: +49-8-BUSTED!!!! V32.bis\n WILD MARIA          GHQ        #1: +49-7-Ask-For-IT V32.bis   Joe Cool\n                                #2: +49-7-Ask-For-IT V32.bis\n PARANOID ILLUSION  USHQ        #1:  +1-203-859-0335 DST       Buzz\n\n\n                           @{" Back to main menu " link "MAIN"}\n@endnode\n','\n',char(10)),NULL,'auto-added',13978,2,0,NULL,NULL,'m_bbss03','scan',1780048582);
