INSERT INTO door_catalog VALUES('m_comm01','M!COMM01.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/M!COMM01.LHA',NULL,'XIM','_  _    ___ ________   ___    ___',NULL,'jOE',NULL,'/ \/ \  /   \__  __\_> /   \  /   \ /  \/ \\/  | \\/ .\/ .\/  | \\/  | \\ ::/   ||  \\  |  \\  \\  \\  |  \\  |  \\::',replace('     _  _    ___ ________   ___    ___\n    / \/ \  /   \__  __\_> /   \  /   \\n   /  \/ \\/  | \\/ .\/ .\/  | \\/  | \\\n::/   ||  \\  |  \\  \\  \\  |  \\  |  \\::\n::\ __||___/______/___/___/______/__|__ /::\n===\|=========P=R=E=S=E=N=T=S======[B]|/===\n= /X2.x /X3.x cOMMENT 0.1 bY jOE cOOL/m!  =\n===========================================\n','\n',char(10)),'cOMMENT.gUIDE',replace('@database "MoTiOn - (-cOMMENT 0.1-)"\n@AUTHOR "jOE cOOl"                 \n@(C) "jOE cOOL/mOTION"                  \n@Ver$ "(-cOMMENT 0.1-) (20-06-94)"\n@HEIGHT 30\n@Node MAIN "(-Main Menu-)"\n\n _____________________________________________________________________\n MoTioN-MoTioN-MoTioN-MoTioN-MoTioN-MoTioN-MoTioN-MoTioN-MoTioN-MoTioN\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n            _    _    ____   ______ ____  ____    _____  \n           / \\__/ \\  /    \\ / _  _ \\\\  / /    \\  /  _  \\  \n          /   __  .\\/   | .\\\\// .\\\\//\\/\\/   | .\\/   |  .\\  \n         /    ||   \\\\   |  \\\\/   \\\\/   \\\\   |  \\\\   |   \\\\  \n         \\ ___||____/_______/\\____/\\____/_______/___|___ /  \n          \\| -------] the force that moves: M! [------ |/  \n  \n _____________________________________________________________________\n MoTioN-MoTioN-MoTioN-MoTioN-MoTioN-MoTioN-MoTioN-MoTioN-MoTioN-MoTioN\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n     +-------------------» PRESENTS IN 1994 «-------------------+\n\n\n                            (-cOMMENT 0.1-)\n           \n                    by  @{"(-     jOE cOOL      -)" link "coder"}\n                        @{"(-     Features      -)" link "Intro"}                \n                        @{"(-   Installation    -)" link "Install"}                \n                        @{"(-   Instructions    -)" link "Instr"}              \n                        @{"(-    Greetings      -)" link "Greet"}  \n                        @{"(-    Last Words     -)" link "Last"}              \n                        @{"(-     CaLL NoW      -)" link "Call"}  \n                        \n\n@endnode\n@Node coder "(-     jOE cOOL      -)"\n\n    Hello ! If you wanna contact me just leave a mail to Joe Cool\n    or try to talk to another Motion Member !\n\n\n                           @{" Back to main menu " link "MAIN"}\n@endnode\n@Node Intro "(-     Features      -)"\n\n    I thought that there was no well Designed Comment Door.\n    So I decided to code a cooler one. Here it is ! \n\n    If U just use the comment C then the Menu will appear but\n    if u use C 1 or C 2 or C x then the Sysop Number 1,2,x will\n    automatically get a mail.\n  \n\n                           @{" Back to main menu " link "MAIN"}\n@endnode\n@Node Install "(-   Installation    -)"\n\n \n  /X2.x: Append the following Line to your\n         BBS:Commands/BBS.CMD File:\n         ---------------------->> Cut Here <<--------------------------\n         c          RM020DOORS:cOMMENT/cOMMENT.rexx\n         ---------------------->> Cut Here <<--------------------------\n\n  /X3.x: 1) Copy C.INFO to your BBS:Syscmd-Drawer\n         2) Copy Comment-Drawer to your Doors:\n	  \n    *** Complete ***\n\n \n                           @{" Back to main menu " link "MAIN"}\n@endnode\n@Node Instr "(- Instruction -)"\n\n\n         cOMMENT.cFG:\n\n\n         ---------------------->> Cut Here <<--------------------------\n         [-jOE cOOl!]\n         I am the Hardware Sysop\n         [-gONZALEZ!]\n         I am the Software Sysop\n         ---------------------->> Cut Here <<--------------------------\n\n         First you have to insert The name of a Sysop\n         Then you have to insert the comment line. Thats all!\n\n\n\n                           @{" Back to main menu " link "MAIN"}\n@endnode\n\n@Node Plans "(- Future Plans -)"\n\n * I wanna code some more useful /X-Tools\n   but next time they will be coded in C\n\n\n                           @{" Back to main menu " link "MAIN"}\n@endnode\n@node Greet "(- Greetings -)"\n\n\n\n                              Greetings go to\n          BBC/MoTioN...............thx for your "Chaos-ASM-Kurs" \n          Andy/MoTioN...................biggest greetings to you\n          Sisko/MoTioN..............................Hello to you\n          Incubus/GOD.......................keep on trading dude\n          \\X/arhawk/Logic................Strip`n Add is the best\n          tHe aDDiCt/5D.....................say thanx to Hillary\n          Calypso/GOD...............I think we have to call more\n                     and all the rest I have forgotten\n\n\n\n                                 @{" WOW ! " link "MAIN"}\n@endnode\n\n@Node Last "(- Last Words -)"\n\n                      Other MoTioN /X tools avaible:\n\n Multi-Diz....................New DIZ system for all files.............Andy\n News In All Conferences......Showing `n s u` in all conferences.......Andy\n On-Line-Message..............Sending online message...................Andy\n OnLineBulletinsUpdater.......Updating bulls if ya wanna se it.........Andy\n PlaY-PeN-PaRt-UpLoAD-MoVeR...Moves files after a system crash.........Andy\n LHADo........................LHA-Checker/Stripper/Adder................BBC\n Textstripper.................Text-Stripper/Adder.......................BBC\n Dream Status.................Status door.............................Bilbo\n StarTrek.....................Star Trek comment door..................Bilbo\n Frontstatus..................Frontend door...........................Bilbo\n Userlist.....................Creates userlist bulletin...............Bilbo\n FileIDAdd....................Add your line to FileID.........BiLBo BaGGins\n User Answer Shower...........Shows the new user answers......BiLBo BaGGins\n SendAnswer...................Sends User Answer to Sysop......BiLBo BaGGins\n sTRIP bBS aDDIES.............Stripps ADDs in File_id.DIZ.gONZALEZ&jOE cOOL\n rEALOG.......................Callerslog Viewer....................gONZALEZ\n nEW uSERS aNSWER.............Shows New Users Answers..............jOE cOOL\n pAGER........................Sysop Pager..........................jOE cOOL\n oPEN.........................Another Open Door....................jOE cOOL                     \n cOMMENT......................Another Comment Door.................jOE cOOL\n \n                      MoTioN -  The Force that moves\n\n\n                           @{" Back to main menu " link "MAIN"}\n@endnode\n\n@Node Call "(- Call Now -)"\n\n                          MoTioN boards worldwide:\n\n DEEP SPACE NINE     WHQ        #1: +49-7-Ask-For-IT V32.bis   Sisko\n                          2 Ndz RD: +49-7-Ask-For-IT DST 21.6\n                          2 Ndz RD: +49-7-Ask-For-IT ISDN\n SANITARIUM          GHQ        #1: +49-8-Ask-For-IT DST       jMS\n                                #2: +49-8-Ask-For-IT DST\n                                #3: +49-8-Ask-For-IT V32.bis\n WILD MARIA          GHQ        #1: +49-7-Ask-For-IT V32.bis   Joe Cool\n                                #2: +49-7-Ask-For-IT V32.bis\n PARANOID ILLUSION  USHQ        #1:  +1-203-859-0335 DST       Buzz\n\n\n                                  @{" ATDT !" link "MAIN"}\n@endnode\n','\n',char(10)),NULL,NULL,4802,2,0,NULL,NULL,NULL,'scan',1780048582);
INSERT INTO door_catalog VALUES('m_ds1','M!DS1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/M!DS1.LHA','dreamstatusa','XIM','dreamstatus.exe',NULL,'Bilbo/MTN',NULL,'/        /     /  ___/___/     /     /\ // /  /  // /  // /  //  // /  // /  / / // /  /  // /  // /  //  // /  // /  / /',replace('    _____________________________________\n   /        /     /  ___/___/     /     /\\n  // /  /  // /  // /  //  // /  // /  / /\n // /  /  // /  // /  //  // /  // /  / /\n/__/__/__/_____/__/__/___/_____/__/__/ /\n\__\__\__\_____\_____\___\_____\__\__\/[B]\n+-+-+-+- pReSeNtZ aNoThEr /X ToOl -+-+-+-+\n+     Dream Status V1.4 by Bilbo/MTN     +\n+  status door for ALL Express systems   +\n+ have a look at the IFF Picture inside  +','\n',char(10)),'dreamstatus.guide',replace('@database "MoTiOn - Dream Status V1.4"\n@AUTHOR "The aDDiCt"                 \n@(C) "Bilbo/Motion"                  \n@Ver$ "Dream Status V1.3 (30-03-94)   \n@HEIGHT 30\n@Node MAIN "--> Main Menu <--"\n\n  .%%%................%%%....%%%..........%%/\%%.%%%......%%%....%..%....%%\n .%%.%%%%%%%%%%%%%%%%%%.%%%%%%.%%%%%%%%%%%%/  \%%%.%%%%%%%%.%%%%%%%%%%%%%%.\n %%/(_________________/(_____/(___________(____)%/(______%%|\___%.____.%%.%\n %%\                 /      ~\\             /  |//      ~\%|.   \|   ~|%%%.\n .%%\  /\           //   |:   \\  ..   .   /   |/    |    \||    \    |%%%%\n  .%%\/            //    |.    \_/||   |\_/|   |     |.    \|         |%%%.\n ..%%|.  (\   /)   \\          /%%|:   |%%|:   |\          /:   \     |%%. \n ..%%||   \\_//     \____.    /%%%|_   |%%|.___|%\__.     /|.   |\    |%%%.\n ====||    \==\\   /=====|_  /======\__|==|/========|__._/=|____|=\___|====\n %%%%|______\..\\//%%%%%%%%)/%%%%%%%%%%%%%:%%%%%%%%%%%%Y%%%%%%%%%%%:%%%%%%%\n %%%%%%%%%%\/%%%\/%%%%%%%%%°%%%%%%%%%%%%%%.%%%%%%%%%%%%:%%%%%%%%%%%.%%°Adi·\n   ·%%%%%%%%%%%%%%%°·····°%%%°··········°%%%°·········°%%°········°%°··\n        +-------------------» PRESENTS IN 1994 «-------------------+\n\n\n                             Dream Status V1.4\n\n                           done by  @{"Bilbo/MoTioN" link "coder"}\n\n                            guide by @{"tHe aDDiCt" link "guider"} \n\n                           +-------------------+\n                           |  @{"   Features   " link "Intro"}  |              \n                           |  @{" Installation " link "Install"}  |              \n                           |  @{" Instructions " link "Instr"}  |             \n                           |  @{"   Greetings  " link "Greet"}  |\n                           |  @{"  Last Words  " link "Last"}  |            \n                           |  @{"   CaLL NoW   " link "Call"}  |\n                           +-------------------+\n\n@endnode\n@Node coder "--> Bilbo/MoTioN <--"\n\n That`s me, the coder of that door. If you found any bugs or know any\n improvements please contact me. Also contact me if you wanna have a special\n version for your BBS.\n\n\n                           @{" Back to main menu " link "MAIN"}\n@endnode\n@Node guider "--> tHe aDDiCt <--"\n\n Yeahhh that`s me, tHe aDDiCt. The cewl dude who made this guide.\n\n\n                           @{" Back to main menu " link "MAIN"}\n@endnode\n@Node Intro "--> Features <--"\n\n * displays nearly all informations avaible for the user on one screen \n * nice ANSI output                                                   \n * running on all Express Versions (/X 2.xx-3.xx & Sigma Express)     \n * no backdoors\n * compiled AREXX\n * tested over monthes\n\n \n                           @{" Back to main menu " link "MAIN"}\n@endnode\n@Node Install "--> Installation <--"\n\n Extract the whole Dream Status archiv to you assigned doors dir.\n\n /X2.x: Append the following Line to your\n        BBS:Commands/BBS.CMD File:\n        ---------------------->> Cut Here <<--------------------------\n        *S            RM010DOORS:DreamStatus/DreamStatus.rexx\n        ---------------------->> Cut Here <<--------------------------\n\n /X3.x: For installing on that systems make your own Icon and place it\n        in your BBS:Commands/BBS.CMD drawer.\n\n Copy the rexxsupport.library to your assigned LIBS: dir.\n\n If the BBS name is not displayed correctly, insert it in the file\n DreamStatus.CFG. Do not use Escape Codes for colors, bold, underlined,..\n and not more than 24 figures!\n\n DreamStatus.CFG - The Config File:\n Edit the names and paths of the User.Keys file, Systemstats file,\n Computerlist file and if needed the BBS Name.\n Note: /X v3.xx users have to edit the included Computerlist file for\n       their own System. In the first line stands the amount of\n       Computers, after that each Computer.\n\n Be sure, that you have the following files: (otherwise the door won`t work)\n * LIBS:rexxsupport.library\n * Doors:DreamStatus/DreamStatus.cfg\n * USER.KEYS\n * SystemStats\n * Computerlist\n\n\n                           @{" Back to main menu " link "MAIN"}\n@endnode\n@Node Instr "--> Instruction <--"\n\n Just press `s` in the main prompt an the door will appear.\n\n\n                           @{" Back to main menu " link "MAIN"}\n@endnode\n\n@Node Plans "--> Future Plans <--"\n\n * no more at the moment\n\n\n                           @{" Back to main menu " link "MAIN"}\n@endnode\n@node Greet "---> Greetings <---"\n\n                              Greetings go to\n          Andy/MoTioN...........thx for the great help in coding\n          Sisko/MoTioN................greatest friend and tester\n          Spider/Osiris.........where are the Osiris releases ??\n          Incubus/GOD............................keep on trading\n          \X/arhawk/Logic................Strip`n Add is the best\n          Eazy-e/Taurus..............................let`s party\n          Schwabenpower/MoTioN............cewl long chats hehehe\n          tHe aDDiCt.....................................machine\n                     and all the rest I have forgotten\n\n           Thanx for the help on releasing this door must go to\n          Andy/MoTioN.............................help in coding\n          jMS/MoTioN........................................ANSI\n          tHe aDDiCt..................................guide file\n\n                           and to my betatester\n              Sisko/MoTioN, jMS/MoTioN, Schwabenpower/MoTioN\n\n\n                                 @{" WOW ! " link "MAIN"}\n@endnode\n\n@Node Last "---> Last Words <---"\n\n                      Other MoTioN /X tools avaible:\n\n Multi-Diz....................New DIZ system for all files.............Andy\n News In All Conferences......Showing `n s u` in all conferences.......Andy\n On-Line-Message..............Sending online message...................Andy\n OnLineBulletinsUpdater.......Updating bulls if ya wanna se it.........Andy\n PlaY-PeN-PaRt-UpLoAD-MoVeR...Moves files after a system crash.........Andy\n LHADo........................LHA-Checker/Stripper/Adder................BBC\n Textstripper.................Text-Stripper/Adder.......................BBC\n Dream Status.................Status door.............................Bilbo\n\n                      MoTioN -  The Force that moves\n\n\n                           @{" Back to main menu " link "MAIN"}\n@endnode\n\n@Node Call "---> Call Now <---"\n\n                          MoTioN boards worldwide:\n\n FASTWAY             WHQ  6 Ndz RD: +49-714-129-0036 DST 21.6  Andy\n                          2 Ndz RD: +49-714-129-3050 ISDN\n DEEP SPACE NINE     EHQ        #1: +49-715-290-2518 V32.bis   Sisko\n                          2 Ndz RD: +49-715-290-2507 DST 21.6\n                          2 Ndz RD: +49-715-293-8240 ISDN\n GATEWAY TO HELL     GHQ        #1: +49-712-147-8470 DST 16.8  Dragon\n                                #2: +49-712-144-696  DST 16.8\n                          2 Ndz RD: +49-712-194-1590 ISDN\n BLIND DATE          GHQ        #1: +49-714-151-252  HST       Psycho\n                                #2: +49-714-151-759  V32.bis\n SANITARIUM          GHQ        #1: +49-816-566-642  DST       jMS\n                                #2: +49-816-566-738  V32.bis\n SNAKE BITE          GHQ        #1: +49-713-422-682  DST       Schwabenpower\n PARANOID ILLUSION  USHQ        #1:  +1-203-859-0335 DST       Buzz\n\n\n                                  @{" ATDT !" link "MAIN"}\n@endnode\n','\n',char(10)),NULL,'auto-added',63423,6,0,NULL,NULL,'m_ds1','scan',1780048582);
