INSERT INTO door_catalog VALUES('m_s_uj','M!S-UJ.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/M!S-UJ.LHA','upjoin','XIM','_____    /\  ____________   M A G I C',NULL,'F!G','M!S','\__  \  /  \/   ________/              ''96 /  \ \/ /  \_____    \     S T Y L E _/    \  /   |   _\     \_',replace(' _____    /\  ____________   M A G I C\n \__  \  /  \/   ________/              ''96\n  /  \ \/ /  \_____    \     S T Y L E\n_/    \  /   |   _\     \_\n\______\/____|___________/   Presents\n.----------- -  ------  -  -  ---  -  - ---.\n| UpJoin by F!G Version 0.2 -------------. |\n: Upload Mover which centers the infos<--'' :\n. and have a quiet nice output...(Very 8*)\n  The M!S OutPut Style ! Coded 100% in C!  .\n: `--> UpJoin by F!G/M!S (c)1996           |\n%%%%%%%%%% RHYTHM NATION 03-02-96 %%%%%%%%%%\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :