INSERT INTO door_catalog VALUES('med_dope','MED-DOPE.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MED-DOPE.LHA',NULL,'XIM','decrunch.library',NULL,'yOgHuRt/MeD.....','MED','\ ¬\/¬\\____    /\____ ¬\ /.     \/  ¬\__/_|  ¬|  \\  MeDeLLíN ''94 //  \/   \  ___/ ¬/   :   \\ ~~~~~~~~~~~~',replace('   ___  _ _________________\n   \ ¬\/¬\\____    /\____ ¬\\n   /.     \/  ¬\__/_|  ¬|  \\  MeDeLLíN ''94\n  //  \/   \  ___/ ¬/   :   \\ ~~~~~~~~~~~~\n /____|| __/_______/|______  /\n=-----:|/---------------ErX\/---PreSenTs---=\n       ·  » ........68øXø DoPe 1.4........ «\n          » .ThE ulTiMaTe PoLi-DeCrUnChEr. «\n          » .....CoDeD bY yOgHuRt/MeD..... «\n=------------------------------------------=\n','\n',char(10)),'DoPe.Doc',replace('\n            /\_______________________                                    \n           / _________  __________  /        ___                         \n          / /         \/          \/ /\     / __\                        \n         / /_  /\__/\__  /\__/\      \/__  / /                           \n        /    \/ __/ __ \/ __/ / /\  /\/  \/ /        --=> DoPe <=--      \n       / / / / /_/ / / / /_/ / / / / / / / /     Da UlTiMaTe DeCrUnChEr  \n      / / / / __/ / / / __/ / / / / / / / /                              \n     / / / / /_/  \/ / /_/ /_/ /_/ / / / /         68ø×ø  VeRsIoN 1.4      \n    / /\/\/\  /\  __/\  /\__/\  /\/ /\  /                                \n    \/[Y]   \/  \/    \/      \/ / /  \/       ©1994 YoGhUrT oF MeDeLlIn \n ______/\__________/\___________/ /                                      \n/______________________________  /                                       \n                               \/                                        \n\n  \n  OvErViEw...\n  --------------\n \n  This Proggie is the first  of his class,it can handle fully the\n  decrunch.lib and offer requester and so on.. but it''s only the beginning.\n  the further versions will be expalined later in the doc.\n  of course the prog was in developement for zum days and it normally must\n  work on any 68000 series microprocessors (tested on 68040^68000)\n  Requesters may not perturb da source or destination like in some fucking\n  lame assemblers.\n\n\n  ReQuIrEmEnTs\n  ---------------\n\n  An amiga (noooo ?)\n  at least 512 kb fast \n  The Decrunch.library (any Version)\n  \n  and if ya want the requesters the Req.library\n  The package includes: Decrunch.lib -- req.lib -- DOPE and the docs\n\n\n  UsE\n  ------\n\n  If ya want to use da requesters just type DoPe.exe\n  if not here''s da syntax...\n\n  DoPe.exe [=SOURCE=] [=DESTINATION=] \n\n  then DoPe will fix where da source will be loaded and will load it.\n  after that,it will analyse the source and establish what was the cruncher \n  used, if it finds it, it will write what''s up and decrunch..\n\n  simple but good !\n\n  \n  FiLeS fOrMaT\n  ---------------\n\n  Well, the differents OUT-Files formats are follow:\n\n  If da Crunched file was in ''RELOC'' mode................Executable\n  If da crunched file was in ''ABSOLUTE'' mode.............Binary\n\n  Well, this version of Dope is better for the ''RELOC'' decrunchs,\n  the absolutes crunching mode are supported too but Dope is not\n  able to tell da jmp, load, decruncher adresses... \n\n  NOTE: The ''KILL SYSTEM'' decrunchers are supported fully !\n        (Bytekiller pro, Defjam packer, etc...)\n        Trying decrunching these type of decrunchers will not crash\n        da AmIgA..  No PrObLeM.. !\n\n  and here are the INcoming formats supported by this decrunch.lib\n\n        CrunchMania A               TurtleSmasher 2.00 D\n        IAM Packer 1.0 D (ICE!)     IAM Packer 1.0 D (ATM5)\n        SoundTracker Song           CrunchMania A  \n        CrunchMania D               CrunchMania D/S\n        CrunchMania D/H             CrunchMania D/H/S\n        CrunchMania R/L/[H]         CrunchMania R/N/[H]\n        CrunchMania R/S             PackIt 1.0 D\n        DragPack 2.52 D             Black&Decker 2.00\n        ByteKiller 2.0              ByteKiller 3.0\n        ByteKiller Pro 1.0          Crunch Master 1.0\n        Crunch-O-Matic 1.0 E        Crunch-O-Matic 1.0 I/M/T\n        DefJam Cruncher 3.2 - 3.5   DefJam Cruncher 3.2 Pro\n        Double Action 1.0           DragPack 2.52\n        FlashSpeed 1.0              Freeway 0.7\n        High Pressure Cruncher      HQC Cruncher 2.0\n        Imploder 1.0-3.1 P          Imploder 4.0\n        Lib Imploded                Master Cruncher 3.0 Abs\n        Master Cruncher 3.0 Reloc   MaxPacker 1.2\n        Mega Cruncher 1.0           Mega Cruncher 1.2 Abs\n        Mega Cruncher 1.2 Reloc     PackIt 1.0\n        PowerPacker 2.x             PowerPacker 3.0\n        PP 3.0 Overlayed            PP 3.0 Password\n        PowerPacker 4.0             PP 4.0 Library\n        PP 4.0 Overlayed            PP 4.0 Overlay/Lib\n        PP 4.0 Password             PP 4.0 Password/Lib\n        ReloKit 1.0                 RSI Packer 1.4\n        Spike Cruncher 1.5          StoneCracker 2.70-4.60K\n        TetraPack 1.02              TetraPack 2.1\n        TetraPack 2.1 Pro           TetraPack 2.2\n        TetraPack 2.2 Pro           TFA Cruncher 1.54\n        Time Cruncher 1.7-2.2       Titanics Cruncher 1.1-1.2\n        TNM Cruncher 1.1            TryIt 1.01\n        TurboSqueezer 8.0           TurtleSmasher 1.3\n        TurtleSmasher 2.00          Ultimate Packer 1.1b\n\n\n   Any Decrunch.library will run !!!  if ya have newest versions\n   you can use them !!!\n\n \n  FuTuRe\n  ---------\n\n  -A first version supporting only Absolutes in complement, it will\n   tell ya all, jump add, decrunch add, stack ^ so !!!\n\n  -after that including the both in a full working version of dope\n   where it will check first if it''s reloc or absolute and then using\n   the decrunch lib for reloc and a totally new and mega efficient\n   absolute decrunch routine.. wich can decrunch everything absolute\n   using the header of each files !!\n\n\n  CrEdz\n  ---------------------\n\n  CoDe............YoGhUrT - MeDeLlIn\n  Support.........CaNaBiZzz\n\n\n  \n  ThIs LiL''PrOgGiE..  CoUlD nOt Be SpReAd In Da PuBlIc DoMaIn, It''S fOr\n  Da PrOz OnLy AnD nOt FoR dA lAmEr BuYiNg ShArE..!\n\n\n  FoR BuGz RePoRt ^ AnYtHiNg ElSe, CaLl OuR bOaRdz WoRlDwIdE...\n\n              _______ _____     ________________ ___________\n            __\_____ ¥ _  ¬\____\ _____________/_\_____    ¬\__\n   _ __ ___/¯      ¯\_/      ¬\  \/¯  ________)_     ¯|       ¬\\n    _ __ __          |         \_     !        ¬\__   !         \___ __ _\n           \ ________|          /______           /____          __ _ _ _\n            \/¯     ¯¦________ /     ¯\_________ /    \________ /\n                     :      ¯\/               ¯\/             \/\n\n             CiVil War-------[2-ndz]--[-EHQ-]--+41-(0)27-227472\n             Hangar 18-------[1-ndz]--[-USA-]--++1-713-488-3055\n             BioHazard-------[nd #1]--[-CAN-]--++1-905-841-0965\n             BioHazard-------[nd #2]--[-CAN-]--++1-905-841-8170\n             Midnite---------[1-ndz]--[-AUS-]--+61---73-797-161\n             Traders Nation--[nd #1]--[-SWE-]--+46---17-655-202\n             Traders Nation--[nd #2]--[-SWE-]--+46---17-619-228\n             UnderCover------[--DIST--SITE--]--+46--854-023-405\n             DaWn Ra¡D-------[4-ndz]--[-UK!-]--+44--707-GUESS..\n             New Order-------[1-ndz]--[-RUS-]--++7-812-290-0305\n\n        -- YoU lOvE pOwEr AnD sPeEd ?? JoIn Da CaRtEl Of MedellíN --\n\n\n\n\n\n                                                     -=  YoGhUrT =-\n','\n',char(10)),NULL,'auto-added',36918,5,0,NULL,NULL,'med_dope','scan',1780048595);
INSERT INTO door_catalog VALUES('med_f111','MED-F111.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MED-F111.LHA','DMSDescript','XIM','DMSDescript','1.11',NULL,'MED','Work with :.LHA,.LZH,.RUN,.FMS,.TXT,.DOC .NFO,.EXE,.XMS,.ZIP AND MORE ..',replace('Meddelin present : File Id Extractor v1.11 !\nWork with :.LHA,.LZH,.RUN,.FMS,.TXT,.DOC\n.NFO,.EXE,.XMS,.ZIP AND MORE ..\n','\n',char(10)),'FidV1_11.Guide',replace('@Database "Fid_V1.11.guide"\n\n@Width 72\n\n@Index "index"\n@node Main "Fid V1.11 /Contenu"\n@Next "Intro"\n\n\n                        @@Wm.          ,gms    ,_mmmm@@@@@@ms  gm@@@@@@@@@@@m_      \n                       g@@@@        ,m@@@@W   M@@@@@@A******! M@@@@@@@@@@@@@@W.    \n                     g@@@@@@      ,m@@@@@@A    d@@@@f          ''Y@@@@     Y@@@@.   \n                   ,W@@@@@@@    ,m@@@@@@@@`   g@@@A`            W@@@@      @@@@W   \n                  g@@@@@@@@@   g@@@A*@@@@!  ,W@@@@`            d@@@@!     d@@@@A   \n                 g@@@A`]@@@@ ,W@@@f g@@@P  ,@@@@@@mmmmm.      g@@@@A     i@@@@A`   \n                W@@@P  ]@@@@m@@@A` i@@@A  ,@@@@@@@@@@@A!     g@@@@A     g@@@@@`    \n              ,W@@@f   ]@@@@@@@f  ,@@@@! ,@@@@@f`           g@@@@A`   ,W@@@@A`     \n             ,W@@@P    ]@@@@@A`   W@@@P  W@@@@!            d@@@@A`   g@@@@@f       \n            ,@@@@P     ]@@@@f    i@@@@` W@@@@P            W@@@@A` ,gW@@@@A`        \n           ,@@@@P      ]@@@!     @@@@[ i@@@@@     ____  ,W@@@@@Wm@@@@@@*`          \n           @@@@A       ]@@P     ]@@@@` !@@@@@@@@@@@@@A  ]@@@@@@@@@@@Af             \n           V@@A`        ''~      !@@@A   V*@@@@A***~~`    ''*~~*****~`[Y]               \n                                  ~*!                                              \n\n\n                                      PRESENT\n\n\n                              Fid V1.11 by ReddoC /Med\n\n\n                                 @{"  Introduction  " Link Intro}\n\n                                 @{"  Installation  " Link Install}\n\n                                 @{" How to use Fid " Link Use}\n\n                                 @{"     Credit     " Link Credit}\n\n                                 @{"    History     "  Link Hist}\n\n                                 @{"  Call our BBS  "  Link Call}\n\n@Endnode\n\n@node "Intro" "Fid V1.11 /Introduction"\n@Next "Install"\n@Prev "Main"\n@Toc "Main"\n\nIntroduction :\n--------------\n\nI coded this programme to extract the File_id.diz of :\n\n                            #?.LHA\n                            #?.LZH\n                            #?.RUN\n                            #?.DMS\n                            #?.FMS\n                            #?.TXT\n                            #?.DOC\n                            #?.NFO\n                         -- #?.EXE --\n                          - #?.XMS -\n\nFid can be use as well in the directory opus (see in How to use Fid)\n\n@Endnode\n\n\n\n@node "Install" "Fid V1.11 /Installation"\n@Next "Use"\n@Prev "Intro"\n@Toc "Main"\n\nInstallation :\n--------------\n\nYou must copy Fid into your c directory\nYou must have the files LHA\n                        DMSDescript\n                        EXEDescript\n                        TxtExtract\n                        XMash\n\nin your c directory.\n\n@Endnode\n\n\n@node "Use" "Fid V1.11 /How to use Fid"\n@Next "Credit"\n@Prev "Install"\n@Toc "Main"\n\nHow to use Fid :\n----------------\n\nin the Shell (or Cli) :\n\nFid <command> [<option>...] <sources>... [$<directory destinations>]\n\ncommand: X = extract file Id.\n         V = view file Id.\n         A = add file Id.\n         D = Delete file Id of archive, but only of archive .lha/lzh/run,\n                                                            .dms/fms,\n                                                            .exe\n\n\n\noptions for the command X: -r  = open a requester for each file id destination.\n                           -v  = view file id during extracting.\n                           -of = all file id are extacting in one file destination.\n                           -s  = extacting file id as '' FILE_ID.DIZ''.\n                           -na = If the File Id exists already, it will be replaced without asking.\n\n(EG: fid X -v -r Upload:file.lha Upload:file2.txt Upload:file<x>.dms $ram:)\n\n\noptions for the command V: none for the moment.\n(EG: fid V Upload:file.lha Upload:file2.txt Upload:file<x>.dms)\n\noptions for the command A: none for the moment.\n(EG: fid A Upload:File.lha FileID:File_ID.DIZ)\n\noptions for the command D: none for the moment.\n(EG: fid D Upload:file.lha Upload:file2.dms Upload:file<x>.exe)\n\nif you don''t type a directory destination a file requester will be opened by default.\nif you don''t type the option -s , the file id .diz will be extracting as <name of the file>.diz\n\n\nin Directory Opus:\n\n                    in your configuration set :\n\n                    C:Fid <command> [<options>]{F} ${d}\n\n@Endnode\n\n\n@node "Credit" "Fid V1.11 /Credit"\n@Next "Call"\n@Prev "Use"\n@Toc "Main"\n\nCredit:\n-------\n\nFid V1.11 is coded By REDDOC of Medellin in 1994\n\nGreatings are going to: Yoghurt/Med\n                        Eurex/Med   (thanx for your Ideas)\n                        Highlander/Med\n                        Hawkmoon/Med/\n                        Tas/Med\n                        Axl\n                        Yelm/Alc\n                        Eto/Alc\n                        Warlord/Alc\n                        Not/Alc\n                        Garg/Alc\n                        Fryg/Alc\n                        Joghndow\n                        DarkLord\n                        Jedi\n                        Creator\n                        and all people i forget .........\n\n\n@Endnode\n\n@node "Hist" "Fid V1.11 /History"\n@Next "Call"\n@Prev "Credit"\n@Toc "Main"\n\nHistory:\n--------\n\nFid V1.00  - fid could only extract file.\nFid V1.10a - some bugs fixed, add archive .exe and .xms, some new option as (-v,-r,etc...)\n             and the command V\nFid V1.11  - some bugs fixed, add command ''A'' and ''D''.\n\nFuture:    - add archive zip and more options..\n             and later an interface MUI will be opened with an other option.\n\n@Endnode\n\n@node "Call" "Fid V1.11 /Call our BBS"\n@Prev "Credit"\n@Toc "Main"\n\nCall our BBS:\n-------------\n\n         CiVil War.............[2.ndz]..[=EHQ=]..+41.(0)27.227472\n         Hangar 18.............[1.ndz]..[=USA=]..++1.713.488.3055\n         BioHazard.............[nd #1]..[=CAN=]..++1.905.841.0965\n         BioHazard.............[nd #2]..[=CAN=]..++1.905.841.8170\n         Dark Sun..............[2.ndz]..[=AUS=]..+61...42.683.036\n         Traders Nation........[nd #1]..[=SWE=]..+46...17.655.202\n         Traders Nation........[nd #2]..[=SWE=]..+46...17.619.228\n         DaWn Ra¡D.............[1.ndz]..[=UK!=]..+44..707.320.320\n         New Order.............[1.ndz]..[=RUS=]..++7.812.290.0305\n\n@Endnode\n\n','\n',char(10)),NULL,'auto-added',87648,1,0,NULL,NULL,'med_f111','scan',1780048595);
INSERT INTO door_catalog VALUES('med_tag','MED-TAG.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MED-TAG.LHA','MultiView','XIM','MultiView',NULL,NULL,'MED','|___ ____/\______  __/\___ ___ ___/\ __  /\ |\  Y /\_ _____  \ \_ ___//  //  (__)\ \/ / |/    \/ ___)/ \  \/ ___)/  //  //  \/  \ \',replace('.----÷THE÷^CARTEL^÷WILL÷NEVER÷DIE÷!÷---16÷03\n|___ ____/\______  __/\___ ___ ___/\ __  /\\n|\  Y /\_ _____  \ \_ ___//  //  (__)\ \/ /\n|/    \/ ___)/ \  \/ ___)/  //  //  \/  \ \\n/  \/  \ l  \  /  /  l  \  //¯\ ¯¯\  \ \   \\n\___\  /____/____/\_____/___ErX\___\_/_/\__/\n`---÷\/÷----÷Br¡NgS÷Tø÷U÷TøDaYs÷-----------.\n.------------------------------------------''\n| /X 2.xx   <÷> T.A.G. v1.2ø <÷>    /X 3.xx\n| ThE F¡rSt WaLL wIth CøløR & StYle EdItiøN\n`------------------------------- ---- --- ->\n','\n',char(10)),'change.txt',replace('\n .------------------------------------------------------------.\n |  !    _ __ __  __ __ __ ___  __________  _____________     |\n |--+-- / |  |  \|  |\/|  |\  \/ ____/  _ \/.  ___/ ____/     |\n |  |  /  | !|!  \  | ||  |/ //  _/ |. |/ /\___  \\ __/       |\n |    //  |  |: \   | .|  / /// \\/\|: \  \/   | \\ \ ¯\      |\n |    \______|__|\__|__|____/\_____/|__|\__/______/____/i!    |\n |                                                            |\n |    :++::     :+:!--»» +49-AsK-ELiTE! ««--!:+:      :+:     |\n |  ::+                                                 +:+   |\n |  +:    3 nOdEs dSt riNGdOwN ^ 2 nOdEs iSdN riNGdOwN   ::+  |\n | :+                                                    +:   |\n |  :+    stAff: PiGEON ^ iAN!/TT ^ RONIN/SCX ^ BOMBER  +:    |\n |                                                            |\n `------------------------------------------------------------''\n','\n',char(10)),NULL,'auto-added',58746,7,0,NULL,NULL,'med_tag','scan',1780048595);
INSERT INTO door_catalog VALUES('megat10e','MEGAT10E.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MEGAT10E.LHA','MegaTool','XIM','LE-win5-96.exe','1.02',NULL,NULL,NULL,replace('AMIEXPRESS MEGATOOL BETA V1.02\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                                                .------''\n             `------------------------------------------------''\n','\n',char(10)),NULL,'auto-added',47003,5,0,NULL,NULL,'megat10e','scan',1780048595);
INSERT INTO door_catalog VALUES('mental10','MENTAL10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MENTAL10.LHA',NULL,'XIM','MENTAL.EXE',NULL,'The',NULL,':             VISAGE PRESENT''s             : -------------------------------------------- :     An Amiexpress door From Mr.orion     :',replace('--------------------------------------------\n:             VISAGE PRESENT''s             :\n--------------------------------------------\n:     An Amiexpress door From Mr.orion     :\n--------------------------------------------\n:        Mental Status V1.0 (Update)       :\n--------------------------------------------\n:        Released On The 24/05/1995        :\n--------------------------------------------\n:        Ofcouz It''s A (XIM) door..        :\n--------------------------------------------\n      UploadED by The Boss him SElf...      \n06:04:52  -=-  nODE:  0  -=-  cNX: 57600 -=-\n','\n',char(10)),'Mental_V1.0.Guide',replace('@database "GlobalDupe.Guide"\n@WIDTH 77\n@NODE Main "MAIN" "Welcome to Mental-Status Documentation"\n\n  \n                           Mental Status 1.0 (24/05-95)\n     \n                              By Mr.orion / ViSaGe\n                                         \n                          @{"What is Mental Status ?   " LINK "ABOUT"}   \n                          @{"Requirements.             " LINK "REQ"}                \n                          @{"Installation.             " LINK "INSTA"}              \n                          @{"Credits                   " LINK "CREDS"}\n                          @{"Greetings.                " LINK "GREET"}                 \n                          @{"How to contact Me         " LINK "HOWTOCONTACT"}\n              \n@ENDNODE\n\n\n\n\n\n\n\n\n\n\n@NODE "ABOUT" "What is Mental Status ?"\n\n\nMental Status V1.0 is an STATUS door to Amiexpress V4.xx+\nwell.. i wanted to make an STATUS door becourze all \n( ALLmost all STATUS doors ) is not so userfriendly like\nthiz door.. i my self thing that tiz door is VERY userfri-\nendly to look at.. there for i deside to make THIZ...\n  \n\n\n\n                   Filesize :\n\n              Mental_V1.0.guide   = 3859 Kbytes\n              Mental_V1.0.exe     = 5520 Kbytes\n\n@ENDNODE\n\n@NODE "REQ" "Requirements."\n\nYou need an : commodore amiga ( A40x0 )\n              KS 2.0+\n              Amiexpress 4.xx+\n              AEdoor.library\n              \n@ENDNODE\n\n\n@NODE "INSTA" "Installation."\n\n\n                             \nCopy thiz Files over to Da dir''s :\n\nS.info               --->          bbs:commands/bbscmd/\nMental_V1.0.exe      --->          bbs:doors/mental/\nMental_V1.0.guide    --->          bbs:doors/mental/\n\nThat was all... if it Still don''t work then DON''T\nDrive a Board....\n\n\n@ENDNODE\n\n@NODE "HOWTOCONTACT" "How to contact Mr.orion"\n\nHow to contact me:\n\n@{" Mental Insanity  VSG DKHQ " LINK "MENTAL"}    :+45 65943572\n@{" Sticky Fingers  VSG WHQ   "}    :+31 71320878\n@{" Premium  VSG SHQ          "}    :+46 24387645\n@{" Bumble Bee Land  VSG NHQ  "}    :+47 22508551\n@{" Electrick Kafe  VSG HQ    "}    :+45 PRIVATE!\n\nJust Leave An Comment To Me!! (Mr.orion) \n\n@ENDNODE\n\n@NODE "CREDS" "Credits."\n\nCode,Idea    -    Mr.orion / VISAGE ''95\nDoor Design  -    Mr.orion / VISAGE ''95\nGuide Design -    Mr.orion / VISAGE ''95\n\n\n@ENDNODE\n@NODE "GREET" "Greetings."\n\n\n                                  \n\n                         Greetings to all I know!!! \n\nAll in : VISAGE, EXCALIBUR, REBELS\n\n       : YOBBO/RBS, MR.HYDE/PSG, RAMOSYS/MST, PRINCIP/KINGDOM\n         NSL/ZEKT, JOSHUA/ZEKT, RING+RING/????, WILD THING/YDL\n         D-SIYA/??, DEVILSTAR/VD-FLT, ENZO/PSG-LSD-HF, \n         \n\n@ENDNODE\n\n@NODE "MENTAL" "Mental Insanity"\n               ______              _______      ______\n               \_   /              \_    /      \_   /\n       _______./   /_______________/    /______./   /     \n       \__    /   /___   __  _   __   _____    /   /___\n        /   \/   /___/   /   /   /    /   /   /   /   /  VISAGE DKHQ\n       /    /   / \_____/   /   /    /  _    /   /   /\n      /    /   /  _/   /   /   /    /   /   /   /   /_______  ______\n      \___/___/_______/___/___/____/___/___/_______/ \_    /  \_   /\n     ________________________________________________/    /___/   /\n     \_________  _   _____   _____   __  _   ________   _____/   /\n      /      /   /   /   /___/   /   /   /   /     /    /   /   /\n     /      /   /   /___   \   _    /   /   /     /    /   /   /\n    /      /   /   /   /   /   /   /   /   /     /    /   /   /\n    \_____/___/___/_______/___/___/___/___/_____/____/____   /sCf!\n                                                        /  _/\n                                                       /____\\n   -=- /X 4.4 -=- 0.5 gIg Online -=- 0-3 Day''s Stuff-=-\n   -=- Nice Ratio -=- c00l Conf''s -=- Nice Staff''s  -=-\n   -=- Only Elite Dudez aRe Welc0me HerE!!.....AnD  -=- \n   -=- Just DiaL Da FuckiNG Numba!! +45 6594-3562   -=-\n   -=- No NupE -=- No Lamer''s -=- Only Elite m8''s.. -=-\n\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',24284,2,0,NULL,NULL,'mental10','scan',1780048595);
