INSERT INTO door_catalog VALUES('mgs__b15','MGS!-B15.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MGS!-B15.LHA','bulls','XIM','Bulls',NULL,NULL,'MGS!','____\        /___\   ____  /____/ ___/______ _     \l      _  \_______ ____\/       __l_________  __l__       l ___',replace('    __________   ___________     _____\n____\        /___\   ____  /____/ ___/______\n               _     \l      _  \_______\n____\/       __l_________  __l__       l ___\ng®m /________)   e^D \_____)   (_________)\n          «« m e g a s t y l e  »»\n               ...presents...\n \n                 Bulls v1.5\n \nNEW and IMPROVED Bulletin-viewer for /X+S!X.\n','\n',char(10)),'Bulls.GUIDE',replace('@database "mEGAZTYLE.guide"\n@node MAIN\n@title "                                              »«  m e g a s t y l e  »«  r u l e s  »«"\n@{b}\n                              @{u}m e g a s t y l e@{uu}\n\n                 ________   _________   _________     ______.\n           ______\      /___\  ___  /___\  ___  /_____\____ l____\n     ______\              _     l/    _    \l     _     __/     /_______\n.___(       \____\/     __l__  _______l_______  __l__   \l_____/        )___.\n|                /______)   (_____/        \____)   (____\                  |\n|                                                                           |\n| g®m      _____      ___.           .______   ___.       _________     e^D |\n|___  ____/ ___/______\  l___________|     /___\ _l_______\  ___  /____  ___|\n   (__\   \______   _    __/     _   l       _   \      _     l/      /__)\n       \__      l __l__  l     __l_______  __l_        _l_  _________/\n         (________)   (________)     \_____)  (________) (_____/ @{ub}\n\n\n\n@{fg shine}                  p r e s e n t s   a   n e w   d o o r :@{fg text}\n\n\n                      @{b}    @{bg shine}@{u}  B u l l s   1 . 5  @{bg back}@{ub}@{uu}\n\n\n\n\n              @{"           d o c u m e n t a t i o n           " link index}\n\n\n\n\n@endnode\n\n@node index\n@title "                                             »» i n d e x ««"\n\n\n    @{u}                                                          @{uu}\n\n\n@{b}                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n         ____        __________          ____.   ___________   ½½½½½  ½½½½½\n________(___/________\ __     /__________\___l___\  ____   /__    `½½½½''\n                   _   l/       _      _____/  _      l/      ½½½½½½  ½½½½½½\n_____            __l___/      __l__    l     __l__  __________½½½½½½  ½½½½½½\n    (____________)    /_______)   (__________)   (_____/      ½½½½½½  ½½½½½½\n                                                              ½½½½½½  ½½½½½½\n                                                              ½½½½½½  ½½½½½½\n   @{fg shine} @{"            introduction             "  link introduction      }    @{fg text}                ½½½½½½  ½½½½½½\n@{fg shine}    @{"            installation             "  link installation      }          @{fg text}          ½½½½½½  ½½½½½½\n@{fg shine}    @{"              how 2 use              "  link how 2 use         }\n    @{"              copyright              "  link copyright         }\n    @{"          changes ÷ history          " link changes ÷ history  } @{ub} @{fg text}\n\n\n    @{u}                                                          @{uu}\n\n\n@endnode\n\n\n\n\n\n\n\n\n@node introduction\n                                                                 .\n\n                                                                 :\n                                                                 :\n             __________________.______.      ________            :\n          ._(___)_.   ___     _|      l_____\\_     /____________:_ _\n          |       |----/      \        /     \   __/\      __    :\n          l_______|   /_______/        |-----/_______\____       :\n                              l________|(rLf)            /-------:-\n                                                                 :\n                                                                 :\n                                                                 :\n                                                                 .\n\n\nBulls v1.5 is a handy utility to show different bulletin-textfiles to the\nAmiExpress server. However, it does differ from other bulletin-viewers in\nseveral ways. More features included, and full support of the MCI-interface has\nbeen implanted to try to make this door the best around.\n\n\nThe main reason why I coded this door is that most of the other doors I''ve tried\nout have had a aweful design, bad cursor reading, poor display-routines and some\nvery-very (Sysop) unfriendly configuration possibilities.\n\n\nSince I didn''t like the ones I got hold of from others, I started to code\nsomething for my own sake. - And this is it! :)\n\n\nI''m currently working on Bulls v2.o which I hope will be even better than this\nversion. I coded this before I started on the Zippy-Search, so... Much can be\nimproved in future releases, and all registered users WILL notice the benefit\nof it! :)\n\n\n           - - - --- ------[ lizard of megastyle! ]------ --- - -  -\n\n@endnode\n\n\n\n\n\n\n@node installation\n\n .\n                                                                              .\n :\n :                                                                            :\n : __        _____ .___.   ______ __.              _________. ____________    :\n_:(__)_______\_ _/_|_  l___\__  // _l______.  _____\__  //  l____)_  _   /____:_\n :    | __    /_  _ /   /     _ // \     /_l__\__     _ //   /    |_    / ___ :\n_:____|--/   /-/  //    |--/____/----/__/ \     /--/____/    |____|/---/\--/  :\n :      /___/ /___/_____|(rLf)          \---/__/       l_____|            /___:_\n :                                                                            :\n :                        i n s t a l l a t i o n                             :\n .                                                                            :\n                                                                              .\n\n@{fg shine}To install...@{fg text}\n\n\n\nAll you have to do is to copy each of the files in this archive to its\nbelonging directory under "BBS:".\n\nThat''s all... (Simple isn''t it? :)\n\n\n\nConfiguration :\n---------------\n\nThere is only one way to configurate this door, and that is through the\nBulls.info icon. If you, from workbench, use information on this icon, you''ll\nsee several different Tooltype strings.\n\nFirst of all you''ll have to configurate where to locate your BullX.TXT-files.\nThis is done by changing the PATH followed with a "/" to the "BULLETINS_PATH="\ntooltype.\n\nThen you''ll have to state how many bulletin-lines to be included in the \nbulletin-list. Do not write more than the total amount of Bulletin-lines.\n\nUse the tooltype BULLETIN.x=<name> to declare the bulletin-lines, where "x"\nis the line-number and <name> is the name of the Bulletin-Door to be showned.\n\nThe tooltype CONFSHOW.x=<parameters> is used to set up in which conference the\nBulletin-Door is to be displayed in. Remember that the "x" is the line-number\nto the belonging Bulletin-Door. These parameters is set up like this:\n\n\nCONFSHOW.x=xxxxxxxxxxxxoxo....etc...etc..\n\n#confnr :  123456789012345...etc...etc..\n           000000000111111......etc...\n\nAs you can see, each "x" or "o" represent a conference-number. "x" means that\nthe Bulletin-Door will be displayed in this colume''s conference-nr. And "o" \nmeans that the Bulletin-Door will be suppressed in this conference, and will\nnot be displayed on the bulletin-list.\n\n2 simple examples to get your minds going crazy :\n\nCONFSHOW.1=xo  - Set up that Bulletin-Door #1 will be showned in Conf #1, but\n                 not in Conf #2.\n\nCONFSHOW.1=ox  - Set up that Bulletin-Door #1 will NOT be showned in Conf #1,\n                 but will be visible in Conf #2.\n\n\n\nHere is an example of how to set up this BULLS.INFO-icon :\n\n-------------------------- Cut Start Here! --------------------------\n\nBULLETINS_PATH=BBS:BULLETINS/\nANTBULLETINS=9\nBULLETIN.1=AMFETAMIN\nCONFSHOW.1=xxxxxxxxxxxxoxo\nBULLETIN.2=Quick-New\nCONFSHOW.2=oxxxxxxxxxxxoxo\n.\n.\n.\n.\n\n\n--------------------------- Cut End Here! ---------------------------\n\n\nThen you''ll have to make small bulletin-textfiles. These can include standard\nMCI-functions (~) aswell as ordinary text and ANSI-codes.\n\nEach Bulletin-file must have a filename like this "BULLx.TXT", where "x" is the\nmatching bulletin-line number. And the files must exist in the BULLETINS_PATH-\ndrawer. Otherwise none of the bulletins will be showned.\n\n\n\nHere is an example of how to set up such a "BULLx.TXT"-textfile :\n\n--------------------------------- cut start ---------------------------------\n\n~SS_BBS:Screens/Amfetamin.txt \n\n---------------------------------  cut end  ---------------------------------\n\nOr you can use : ~CC_BestUl to launch commands etc...\n\n\n\n Megastyle! is not to held responsible if this program should cause any damage\n to your computer or lead to loss of data. It is provided as is, and is being\n installed and used on your own risk. There is no installer-script provided\n together with the UNREGISTERED versions of the Megastyle! productions!\n\n\n@endnode\n\n\n\n\n\n@node how 2 use\n@title "                                              )>» h o w  2  u s e «<("\n\n                                      ½½½½½½½½½½½½½½½½½½½½½½½.\n                                     ½½½½½½½½         ½½½½½½½½\n      ____.            _________         _______      ½½½½½½½½\n   ___\ __l____________\       /_________\     /______½½½½½½½½\n   \    \___        _             _      /\           ½½½½½½½½\n    \______/      __l__    "    __l__           ___   ½½½½½½½½\n          /_______)   (_________)   (___________) /_  ½½½½½½½½\n                                                   |  ½½½½½½½½\n                ½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½''\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½      ._____      _____    |   _|________\n                ½½½½½½½½______|    /_____/ ___/____|___\  ____  /___\n                ½½½½½½½½      |       _  \_______   _       l/     /\n                ½½½½½½½½__    l     __l__       l __l__  _________/\n                ½½½½½½½½ (__________)   (_________)|  (____/\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½  @{fg shine}   h o w       u s e  @{fg text}   |  ½½½½½½½½\n                ½½½½½½½½      @{fg shine}       2    @{fg text}         |  ½½½½½½½½\n                ½½½½½½½½                           |  ½½½½½½½½\n                ½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½\n\n\n\n     Just @{"Install" link installation} it and run it from /X or S!X.\n\nUse the command "B" at the main prompt, and you may include the correct\nBulletin-number to view a Bulletin-file right away.\n\n\n\n@endnode\n\n\n\n\n\n\n@node copyright\n            .\n\n            :\n            :                                      ________ _______ _  _\n           _:__________  _________________ ________\__   _//\n            :      ___/__\__    __      /\\\ __      /___ /       .\n          _ :_ ____        /___        /     \______/   /_________:_ _\n            :     /-------/ __/-------/\______|        ___________|\n            :     _________(___)__________    ________/       /   l_\n           _:____\\_     /       |    ___/____\__   _        /     /\n            :     \   __/\_______|   /_         /---/       /      |\n         - -:-----/_______\(rLf) \----/________/   /_______/_______|\n            :\n            :                 c o p y r i g h t\n            :\n            .\n\n\n\n                                 ---[%]---\n\n                    Zippy-Search is a Megastyle! production\n\n               Code, idea & design by   Lizard of TBL MGS!\n               Error-logo by            Magz of GRT MGS!\n               Tooltype read code by    Lizard of TBL MGS!\n               Bulletin logo            Jedi (Ex. MGS!)\n\n\n              \n\n                         Creds for this GUIDE file\n\n               Slapped together by      Lizard\n               Asciis by                Relief   of T! MGS! 5D\n                                        Grimlock of GRT E^D MGS!\n\n                                 ---[%]---\n\n\n\n                      Megastyle! does now consist of\n \n               Leader . . . . . . . . . Lizard\n               Code . . . . . . . . . . Lizard\n                                        Magz\n                                        Instant\n                                        Splash\n               AscII. . . . . . . . . . Relief\n                                        U-MAN\n                                        Grimlock!\n                                        Magz\n               Boards . . . . . . . . . Noiseless - WHQ         LIZARD\n                                        Genetic Waste           MAGZ\n                                        Ecstatica               INSTANT\n                                        Traders Paradise        U-MAN\n\n                                 ---[%]---\n\n\n\n\n\n\n   ............\n   ::        ::\n   ::        ::\n    .        ::\n   /_____    ::          ___________                                          .\n  /_     \//\____________\   