INSERT INTO door_catalog VALUES('mgs__ls1','MGS!-LS1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MGS!-LS1.LHA','log-shrink','XIM','log-shrink',NULL,NULL,'MGS!','____\        /___\   ____  /____/ ___/______ _     \l      _  \_______ ____\/       __l_________  __l__       l ___',replace('    __________   ___________     _____\n____\        /___\   ____  /____/ ___/______\n               _     \l      _  \_______\n____\/       __l_________  __l__       l ___\ng®m /________)   e^D \_____)   (_________)\n          «« m e g a s t y l e  »»\n               ...presents...\n \n              Log-Shrink v1.o!\n \nThe best way to shorten down your HUGE logs!\n','\n',char(10)),'Log-Shrink.GUIDE',replace('@database "mEGAZTYLE.guide"\n@node MAIN\n@title "                                              »«  m e g a s t y l e  »«  r u l e s  »«"\n@{b}\n                              @{u}m e g a s t y l e@{uu}\n\n                 ________   _________   _________     ______.\n           ______\      /___\  ___  /___\  ___  /_____\____ l____\n     ______\              _     l/    _    \l     _     __/     /_______\n.___(       \____\/     __l__  _______l_______  __l__   \l_____/        )___.\n|                /______)   (_____/        \____)   (____\                  |\n|                                                                           |\n| g®m      _____      ___.           .______   ___.       _________     e^D |\n|___  ____/ ___/______\  l___________|     /___\ _l_______\  ___  /____  ___|\n   (__\   \______   _    __/     _   l       _   \      _     l/      /__)\n       \__      l __l__  l     __l_______  __l_        _l_  _________/\n         (________)   (________)     \_____)  (________) (_____/ @{ub}\n\n\n\n@{fg shine}                  p r e s e n t s   a   n e w   d o o r :@{fg text}\n\n\n                @{b}    @{bg shine}@{u}  L o g - S h r i n k   1 . o  @{bg back}@{ub}@{uu}\n\n\n\n\n              @{"           d o c u m e n t a t i o n           " link index}\n\n\n\n\n@endnode\n\n@node index\n@title "                                             »» i n d e x ««"\n\n\n    @{u}                                                          @{uu}\n\n\n@{b}                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n         ____        __________          ____.   ___________   ½½½½½  ½½½½½\n________(___/________\ __     /__________\___l___\  ____   /__    `½½½½''\n                   _   l/       _      _____/  _      l/      ½½½½½½  ½½½½½½\n_____            __l___/      __l__    l     __l__  __________½½½½½½  ½½½½½½\n    (____________)    /_______)   (__________)   (_____/      ½½½½½½  ½½½½½½\n                                                              ½½½½½½  ½½½½½½\n                                                              ½½½½½½  ½½½½½½\n   @{fg shine} @{"            introduction             "  link introduction      }    @{fg text}                ½½½½½½  ½½½½½½\n@{fg shine}    @{"            installation             "  link installation      }          @{fg text}          ½½½½½½  ½½½½½½\n@{fg shine}    @{"              how 2 use              "  link how 2 use         }\n    @{"              copyright              "  link copyright         }\n    @{"          changes ÷ history          " link changes ÷ history  } @{ub} @{fg text}\n\n\n    @{u}                                                          @{uu}\n\n\n@endnode\n\n\n\n\n\n\n\n\n@node introduction\n                                                                 .\n\n                                                                 :\n                                                                 :\n             __________________.______.      ________            :\n          ._(___)_.   ___     _|      l_____\\_     /____________:_ _\n          |       |----/      \        /     \   __/\      __    :\n          l_______|   /_______/        |-----/_______\____       :\n                              l________|(rLf)            /-------:-\n                                                                 :\n                                                                 :\n                                                                 :\n                                                                 .\n\n\nEver discovered that some of the applications you''re using just seems to append\nand append and append to the log-files without erasing the old data?\n\nWell, I just noticed that my AmiExpress Callerslog was over 2MB long once, and\ndecided to make a utility that could keep the length of that particular file\ndown to a resonable level without loosing any important data.\n\nI then started to code on this little program that can be used on any log-file\nin text-format generated by any application for the Amiga. My main goal was to\nmake a fast and system-friendly door, which I could trust wouldn''t screw up my\nsystem totally.\n\n\nThis door does that, it reduce the length of any (text-)file to a desired\namount of bytes, from within the file till the end of the file.\n\nThis way you won''t lose the last entries in the file, and discard the old \nentries on the top of the file.\n\n\n\n                                 Enjoy it! :)\n\n\n\n           - - - --- ------[ lizard of megastyle! ]------ --- - -  -\n\n\n     This program should be 100% systemfriendly coded. If any error should\n    occure, then the program should managed to shutdown without causing any\n                             damage to the system.\n\n\n\n\n@endnode\n\n\n\n\n\n\n@node installation\n\n .\n                                                                              .\n :\n :                                                                            :\n : __        _____ .___.   ______ __.              _________. ____________    :\n_:(__)_______\_ _/_|_  l___\__  // _l______.  _____\__  //  l____)_  _   /____:_\n :    | __    /_  _ /   /     _ // \     /_l__\__     _ //   /    |_    / ___ :\n_:____|--/   /-/  //    |--/____/----/__/ \     /--/____/    |____|/---/\--/  :\n :      /___/ /___/_____|(rLf)          \---/__/       l_____|            /___:_\n :                                                                            :\n :                        i n s t a l l a t i o n                             :\n .                                                                            :\n                                                                              .\n\n @{fg shine}To install...@{fg text}\n\n\n\n All you have to do is to copy the main executable file in this archive to\n whatever directory you wish. I would advice SYS:C/.\n\n\n Also, if you wish to use it together with AmiExpress v3.x+, then you should\n write a command-line into your logoff-script for each node.\n\n\n That''s all... (Simple isn''t it? :)\n\n\n\n\n Functionality :\n\n\n   Log-shrink <Path+Filename> <Size>\n\n   <Path+Filename> is the source-file to be shrinked.\n   <Size> is a number in bytes to dedicate how big the logfile should be...\n\n\n\n If there is spaces in the filename, use "''s marks to indicate start and the end\n of the complete path+filename.\n\n\n\n Remember : This shrinker will cut from within the file -> end of file. \n            So... You won''t miss your last entries in the file. :)\n\n\n@endnode\n\n\n\n\n\n@node how 2 use\n@title "                                              )>» h o w  2  u s e «<("\n\n                                      ½½½½½½½½½½½½½½½½½½½½½½½.\n                                     ½½½½½½½½         ½½½½½½½½\n      ____.            _________         _______      ½½½½½½½½\n   ___\ __l____________\       /_________\     /______½½½½½½½½\n   \    \___        _             _      /\           ½½½½½½½½\n    \______/      __l__    "    __l__           ___   ½½½½½½½½\n          /_______)   (_________)   (___________) /_  ½½½½½½½½\n                                                   |  ½½½½½½½½\n                ½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½''\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½      ._____      _____    |   _|________\n                ½½½½½½½½______|    /_____/ ___/____|___\  ____  /___\n                ½½½½½½½½      |       _  \_______   _       l/     /\n                ½½½½½½½½__    l     __l__       l __l__  _________/\n                ½½½½½½½½ (__________)   (_________)|  (____/\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½  @{fg shine}   h o w       u s e  @{fg text}   |  ½½½½½½½½\n                ½½½½½½½½      @{fg shine}       2    @{fg text}         |  ½½½½½½½½\n                ½½½½½½½½                           |  ½½½½½½½½\n                ½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½\n\n\n\n   Just @{"Install" link installation} it and use it from a CLI window,\n             logoff-scripts or whatever pops up in your mind! :) \n\n\n@endnode\n\n\n\n\n\n\n@node copyright\n            .\n\n            :\n            :                                      ________ _______ _  _\n           _:__________  _________________ ________\__   _//\n            :      ___/__\__    __      /\\\ __      /___ /       .\n          _ :_ ____        /___        /     \______/   /_________:_ _\n            :     /-------/ __/-------/\______|        ___________|\n            :     _________(___)__________    ________/       /   l_\n           _:____\\_     /       |    ___/____\__   _        /     /\n            :     \   __/\_______|   /_         /---/       /      |\n         - -:-----/_______\(rLf) \----/________/   /_______/_______|\n            :\n            :                 c o p y r i g h t\n            :\n            .\n\n\n\n                                 ---[%]---\n\n                     Log-Shrink is a Megastyle! production\n\n               Code, idea & design by   Lizard of TBL MGS!\n\n\n              \n\n                         Creds for this GUIDE file\n\n               Slapped together by      Lizard\n               Asciis by                Relief   of T! MGS! 5D\n                                        Grimlock of GRT E^D MGS!\n\n                                 ---[%]---\n\n\n\n                      Megastyle! does now consist of\n \n               Leader . . . . . . . . . Lizard\n               Code . . . . . . . . . . Lizard\n                                        Magz\n                                        Instant\n                                        Splash\n               AscII. . . . . . . . . . Relief\n                                        U-MAN\n                                        Grimlock!\n                                        Magz\n               Boards . . . . . . . . . Noiseless - WHQ         LIZARD\n                                        Genetic Waste           MAGZ\n                                        Ecstatica               INSTANT\n                                        Traders Paradise        U-MAN\n\n                                 ---[%]---\n\n\n\n\n\n\n   ............\n   ::        ::\n   ::        ::\n    .        ::\n   /_____    ::          ___________                                          .\n  /_     \//\____________\      ___/_______    _________\n //      \/        _     /     /_         /____\___    //                     :\n/--------/     .---/____/   .---/________         _    //                     :\n     -T!/______\  /_       _|  .______.  \-----/_______/                      :\n                  __\   __/____|_     l_          _______.     _____________  :\n   ::        ::   \  \__    _ _        /_____ ____\     _l_____\     _     /__:_\n   ::        ::    \--(/      /            _//          \        ____/____/  /:\n   ::        ::       /____________________ /      /\-----/_____/   /_________:_\n   ::        ::                           /_______/(rLf)                      :\n   ::........::                                                               :\n                                                                              :\n                        m e g a s t y l e    ¹ 9 9 6                          :\n                                                                              .\n\n@endnode\n\n\n\n\n\n\n@node changes ÷ history\n\n\n    ___.        __      ____    ___.      _____  ½½½½½½½½½½      .____\n  ._\ _l_______(_/_____/ __/____\  l______\   /__½½½½   ½½½______|   /_.\n  |   \__   _       _  \____  _    __/  _        ½½½½½½½''        l     |\n  |____l/  _l_     _l_     l _l_   l   _l_  "  __½½½½   ½½½½½_______  _l\n g®m   /___) (_____) (_______) (_______) (_____) ½½½½   ½½½½½   \_____)\n                                                 ½½½½   ½½½½½ e^D\n\n                               ...HISTORY...\n\n\n\n29.03.96            First public release of this utility. Hope someone find it\n                    useful!! :)\n\n\n\n\n\nThanks to the following boards for helpful beta-testing of MegaStyle-products:\n«----------------------------------------------------------------------------»\n\n                             Genetic Waste (Magz)\n  Checkpoint (Kingpin)   -   Power Rage (Instant)   -   EveryWare (-Shade!)\n                           Bumble Bee Land (Baffle!)\n\n\n@endnode\n','\n',char(10)),NULL,'auto-added',12537,5,0,NULL,NULL,'mgs_logs','scan',1780048595);
INSERT INTO door_catalog VALUES('mgs__mdx','MGS!-MDX.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MGS!-MDX.LHA',NULL,'XIM','__________   ___________     _____',NULL,NULL,'MGS!','____\        /___\   ____  /____/ ___/______ _     \l      _  \_______ ____\/       __l_________  __l__       l ___',replace('    __________   ___________     _____\n____\        /___\   ____  /____/ ___/______\n               _     \l      _  \_______\n____\/       __l_________  __l__       l ___\ng®m /________)   e^D \_____)   (_________)\n          «« m e g a s t y l e  »»\n \n       »» MgzDirX 1.o for /X & s!x ««\n \n This shell-util scans through your dir<x>s\nAnd removes from list all non-existing Files\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                                                .------''\n             `------------------------------------------------''\n','\n',char(10)),NULL,NULL,7136,5,0,NULL,NULL,NULL,'scan',1780048595);
INSERT INTO door_catalog VALUES('mgs__r11','MGS!-R11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MGS!-R11.LHA','autoreward','XIM','autoreward',NULL,'Splash','MGS!','_\_/    / _  __  ______ _______/__  ___    / | _ \  /     /  __/__/   /_ _   /   ___   / |__\ \/ /___/_____________/____/____//___/',replace(' ___     _______________________ _ _________\n_\_/    / _  __  ______ _______/__  ___    /\n| _ \  /     /  __/__/   /_ _   /   ___   /\n|__\ \/ /___/_____________/____/____//___/\n    \  /                   .------------.\n     \/ AutoReward 1.1 «-- ÷-  styLE!   ¡\n          By Splash        `------------÷\n EXAMINE door that will automaticly give|\n users a specified number of credz for  |\n their UL. Different credz for each conf|\n -[20.05.95]------ ---- ---------·st!·--''\n [World release at FlAMe StRiKe MGS! WHQ]\n','\n',char(10)),'autoreward.guide',replace('@database "AutoReward.Guide"\n@WIDTH 77\n@NODE Main "MAIN" "Welcome to AutoReward Documentation"\n\n .--------------------  ---(c)-[ mEGAStYLE! pRODUCtiON ''95\n |    ____     _______________________________  _ _____________ _\n ! ___\ _/    / _  ___  __________  _________/_ __   ____       /\n . |    _ \  /      /  ___/_____/    /__ _      /    _//_      / -----.\n ¦ |st!  \ \/ /    /    /      /       /       /     _____    /   -- -÷ -»\n | |______\  /_______________________________________//______/ -------''\n |         \/           \n |\n-÷- -» _____________ ______          _____     _ ______      _ _______ ____\n |  ___\   ________/_     /_       _/    /___         /    _ __  _________/\n |  |__________     /    __/______/     /    \ /     /_______/  ___/_______\n |  |      |       /    /        /     /      \     /       /    /        /\n |  |______________________________________    \_________________________/\n .                              _  _ _____¬_____/\n |\n |\n `--------------------------------------------------- ------------ -[   -»\n\n\n\n\n \n  \n                           AutoReward 1.1 (20/05-95)\n     \n                          By Splash/ElTECH & Megastyle\n                                         \n                          @{"What is AutoReward ?      " LINK "ABOUT"}   \n                          @{"Requirements.             " LINK "REQ"}                \n                          @{"Installation.             " LINK "INSTA"}              \n                          @{"Credits                   " LINK "CREDS"}\n                          @{"Greetings.                " LINK "GREET"}                 \n                          @{"About Megastyle.          " LINK "MEGASTYLE"}\n                          @{"How to contact the Author " LINK "HOWTOCONTACT"}\n\n\n              \n@ENDNODE\n\n\n\n\n\n\n\n\n\n\n@NODE "ABOUT" "What is AutoReward ?"\nAutoReward is a simple little EXAMINE door that will check which conf a file is\nuploaded to, and you can configure how many *credz an upload in this conf should \nbe rewarded with. If you for example has an /X conf (like me) and would like to \nreward all /X uploads with 2*credz, then all you have to do is install this door,\nconfigure it, and all rewarding will be automatic !\n@ENDNODE\n\n@NODE "REQ" "Requirements."\n\n\nA Commodore Amiga computer (Pese suxx :-) running on kick 2.0+, \n/X (preferably 4.x) \n \n\nThis door uses the AEDoor.libary, so you should have this in LIBS:\n(If you haven''t got it then call me or your local /X board to get it...) \n@ENDNODE\n\n\n@NODE "INSTA" "Installation."\n\n\n                             \nJust copy the included files to the correct dirs, that''s it.... \n\nIf you allready have got a file called EXAMINE1.info in syscmd/ you can rename the\none in this archive to EXAMINE2.info or whatever. \n\nThe configuring is done in the autoreward.info\nYou use the tooltype CONF.x=c where x is the conf number and c is the number of \ncredz to be given in this conf.\n\nNB ! \n\n@{b}You only have to have a tooltype for those confs where more than 1*credz should \nbe given!@{ub}\n@ENDNODE\n\n@NODE "HOWTOCONTACT" "How to contact the Author"\n\n \nHow to contact me:\n\n@{"Flame Strike" LINK "FLAME"} :+47 51631702\n\nOr snailmail: Splash/ElTECH & Megastyle\n              Lindeveien 69\n              N-4300 Sandnes\n              Norway\n@ENDNODE\n\n@NODE "CREDS" "Credits."\n\nCode,Idea    - Splash/ElTECH & Megastyle\nDoor Design  - Splash/ElTECH & Megastyle\nGuide Design - Splash/ElTECH & Megastyle\n\n(Guess I did it all by myself then :-)\n@ENDNODE\n@NODE "GREET" "Greetings."\n\n\n                                  \n\n                         Greetings to all my friends ! \n\nSpecial greetings to all /X coders \n\nAND OFCOURSE ALL MEMBERS OF :\n______ ______________ ______ ________    _________/ _|_____/\______ _ __________\n ____ V _________   // ____/_______  \  _\  ______   _  __/  \  __/_________   /\n |   \_/   |   _/  //  \__   |   _/   \/  \___   \   |___     \ \      /  _/  /\n |    |    |  ____/_     |   |   _     /    _/   /   |   \    /  \_   /  ____/_\n |____|    |_______/_________:___\    /_________/____|_______/_______/________/\n      |____|                      \  /                       \n      :    :                       \/\n\n                                   AnD\n\n             _______ /|   _______/\_______________    _____ \n            /~ ____// | __\___  ~__~/  _____/~   ~\  /~ ¡ ~\.  \n           //  __)_// |/ ~\  /  :| //  __) //   .__)//  |  \\\\n           \\     ~\\ ~   \\/   || \\     ~\\   : \\\\      / \  \n            \  ____/\______/\____|  \  ____/\____ // \. |__/  /\n             \/ .____/\______/\_____|\/ .TeTSUo__\/ / \/ ____/\n              \/                      \/          \/   \/ \n\nSpecial greetings to:\nLizard and stRAtOS! -> Let''s make Megastyle the biggest /X group EVER!\n\nSome messages:\nLizard   - I''ve still released more doors than you :-)\nstRAtOS! - You wanted more dezigning work... Oki... I''m gonna make a status door\n           so just start designing! Let''s make it THE best!\n@ENDNODE\n\n@NODE "FLAME" "Flame Strike"\n           .    .         .         .        .\n   _______/|___/|________/|____ ___/|_______/|\n _/        l_   |    _    l_   |    l_       l_.........................\n/¬     _____j   |    ¬     l   !     l    ____j                        :\nY         |    _|__  .     | \ : /   |  _____j_     ·fLAME^sTRIKE·     :\n|     ____j   /    l :     |  \ /    |        l                        :\n|        |  _/     | :     |   :     |        |ElTECH EHQ·Megastyle WHQ:\n|        |         | !     |   !     |        |                        :\n|       ||        || |     |   |     |       ||                        :\nl________j_________j_|     |___|     |________jHOt WAREZ·CODERS CORNER·.\n :                   l_____j   l_____j [nUMEN] CHAtABlE SYSOP·YouNameIt.\n :  cREW:                    .         .      .     .         .        .\n :Splash/ElTECH^MGS!  ______/|________/|_____/|____/|____ ___/|_______/|\n :UnmaD/eXCALIBUR   _/  _____j_        l_   _ l_    l_   |    l_       l_  \n :    [YOU?]       /_____     l         l   ¬  l     l   !     j    ____j\n :                 Y     \    |    _____j    __j_    |   :  __/   _____j_\n :BIG /X conf with |      \   |      |    .     |    |   .    \         l\n :almost 400 files!|       \  |      |    :     |    |   :     |        |\n :                 |          |      |    !     |    |   !     |        |\n :.[+47·51631702]  |         ||     ||    |     |   ||   |     |       ||\n.:::....... .... ..l__________j______j____|     |____j___|     |________j\n :                                      : l_____j /X 4.X l_____j :\n .                                      :........................:\n .\n@ENDNODE\n\n@NODE "MEGASTYLE" "About Megastyle"\n\nMegastyle is a new /X developer group consisting of /X coders and dezigners.\nWe need more members, so if you want to join or have got anything to \ncontribute with (Ideas, hints, dezigns, bugreports aso.) then contact me.\n\nEven if we are a pretty new group we have released a couple of doors allready.\n\nMeGaStYlE Productions:\n\nSplash:\nAutoreward v1.1\nGlobalDupe v1.2\nSysDL      v2.7\n\nLizard:\nBulls      v1.0\n\nAll these doors are just GREAT so check''em out! And more releases to come in near \nfuture!\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',9160,3,0,NULL,NULL,'mgs_awrd','scan',1780048595);
INSERT INTO door_catalog VALUES('mgs__r13','MGS!-R13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MGS!-R13.LHA','autoreward','XIM','autoreward',NULL,'Splash','MGS!','_\_/    / _  __  ______ _______/__  ___    / | _ \  /     /  __/__/   /_ _   /   ___   / |__\ \/ /___/_____________/____/____//___/',replace(' ___     _______________________ _ _________\n_\_/    / _  __  ______ _______/__  ___    /\n| _ \  /     /  __/__/   /_ _   /   ___   /\n|__\ \/ /___/_____________/____/____//___/\n    \  /                   .------------.\n     \/ AutoReward 1.3 «-- ÷-  styLE!   ¡\n                 By Splash `------------÷\n Now also possible to reward group      |\n releases. Auto crediting by filename or|\n by conf (or both!) BUGFIX from v 1.2   |\n -[06.06.95]------ ---- ---------·st!·--''\n [World release at FlAMe StRiKe MGS! WHQ]\n','\n',char(10)),'autoreward.guide',replace('@database "AutoReward.Guide"\n@WIDTH 77\n@NODE Main "MAIN" "Welcome to AutoReward Documentation"\n                                                   __.       \n______ ______________ ______ ________    _________/ _|_____/\______ _ __________\n ____ V _________   // ____/_______  \  _\  ______   _  __/  \  __/_________   /\n |   \_/   |   _/  //  \___  |   _/   \/  \___   \   |___     \ \      /  _/  /\n |    |    |  ____/_     |   |   _     /    _/   /   |   \    /  \_   /  ____/_\n |____|    |_______/_________:___\    /_________/____|_______/_______/________/\n      |____|                      \  /                       \n      :   _____                    \/\n           ____\__________\n            ____\_______  )\n                 \/     ) ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n                        ¯¯¯¯¯¯¯¯¯¯¯¯¯¯ ·g·i·v·e·s·  ·y·o·u·\n\n                                                   \n                        .-------------- -       - ---.\n                        |                          ¯7|\n                        |                            :\n                        :  AutoReward 1.3 (06/06-95) .\n                        ·\n                        ·             by\n                                                     ·\n                        ·  Splash/ElTECH & Megastyle :\n                        :·                           |\n                        |l_                          |\n                        `----- -       - ------------''\n                                         \n                         @{"What is AutoReward ?      " LINK "ABOUT"}   \n                         @{"Requirements.             " LINK "REQ"}                \n                         @{"Installation.             " LINK "INSTA"}              \n                         @{"Credits                   " LINK "CREDS"}\n                         @{"Greetings.                " LINK "GREET"}                 \n                         @{"About Megastyle.          " LINK "MEGASTYLE"}\n                         @{"How to contact the Author " LINK "HOWTOCONTACT"}\n\n\n              \n@ENDNODE\n\n\n\n\n\n\n\n\n\n\n@NODE "ABOUT" "What is AutoReward ?"\n\n\nAutoReward is a simple little EXAMINE door that will check which conf a file is\nuploaded to, and you can configure how many *credz an upload in this conf should \nbe rewarded with. If you for example has an /X conf (like me) and would like to \nreward all /X uploads with 2*credz, then all you have to do is install this door,\nconfigure it, and all rewarding will be automatic !\n\n*New in this version is the possibility to rive extra credits for special group\nreleases such as fexs files starting with MGS!-,ELT- or PGS-\n\nYou can have a different amount of credits for each group and also a different\ncomment for each group which will be displayed if a file from that group are \nuploaded. You can also use this door without giving any credist just for using \nthis commenting feature!\n@ENDNODE\n\n@NODE "REQ" "Requirements."\n\n\nA Commodore Amiga computer running on kick 2.0+, /X (preferably 4.x) \n \n\nThis door uses the AEDoor.libary, so you should have this in LIBS:\n(If you haven''t got it then call me or your local /X board to get it...) \n@ENDNODE\n\n\n@NODE "INSTA" "Installation."\n\n\n                             \nJust copy the included files to the correct dirs, that''s it.... \n\nIf you allready have got a file called EXAMINE1.info in syscmd/ you can rename the\none in this archive to EXAMINE2.info or whatever. \n\nThe configuring is no longer done in the autoreward.info, it is now done in\nautoreward.cfg in the same path as this door.\nSe the included .cfg file for more info on this subject\n\n@{b}You only need to include those confs where more than 1*credz should be given!@{ub}\n@ENDNODE\n\n@NODE "HOWTOCONTACT" "How to contact the Author"\n\n \nHow to contact me:\n\n@{"Flame Strike" LINK "FLAME"} :+47 51631702\n\nOr snailmail: Splash/ElTECH & Megastyle\n              Lindeveien 69\n              N-4300 Sandnes\n              Norway\n@ENDNODE\n\n@NODE "CREDS" "Credits."\n\nCode,Idea    - Splash (borrowed one routine from Lizard though :-)\nDoor Design  - Splash\nGuide Design - Splash/Lizard\n\n@ENDNODE\n@NODE "GREET" "Greetings."\n\n   _________ \n    _______ )  ·M·e·g·a·S·t·y·l·e·  ·s·e·n·d·s·  ·g·r·e·e·t·i·n·g·  ·t·o·\n           )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n    Spaceballs, Eltech, Andromeda, CNCD, Parallax, Complex, Virtual dreams,\nStone Arts, Rebels, TRSI, Scoopex, Avalon, Aquarious, Access, Prestige, Skid Row\n\n                   And to all the other /X-coders out there!\n\n\n________ \n ______ ) ·S·p·l·a·s·h·  ·s·e·n·d·s·  ·s·p·e·c·i·a·l·  ·g·r·e·e·t·i·n·g·  ·t·o·\n       )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n       ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n                                  \n\n                         Greetings to all my friends ! \n\nLizard      : LONG live Megastyle!\nJedi        : Welcome to Megastyle! Hope we can use a design by you soon...\nPreacher    : Håper du kan få deg tlf linje snart.\nSkinner     : How about some more activity in ElTECH ? MORE releases! :-)\nMic Flair   : Hope you like this door, let''s have another chat!\nMaze        : Like DC? New dezign+magpart comming up!\nStratos!    : 2 bad you had to leave, you''ll regret it :-)\nShade       : Hope to C your board up''n''running soon.\nScience     : Still haven''t found any bugs ? :-)\nNike        : Nice talkin'' to yah..\nWoober      : Looking forward to C more releases from you..\nTHEGODFATHER: Board up''n''running soon ?\nACID        : Hi!\n\n\n(+ the rest I 4got..)\n\nAND OFCOURSE ALL MEMBERS OF :\n______ ______________ ______ ________    _________/ _|_____/\______ _ __________\n ____ V _________   // ____/_______  \  _\  ______   _  __/  \  __/_________   /\n |   \_/   |   _/  //  \__   |   _/   \/  \___   \   |___     \ \      /  _/  /\n |    |    |  ____/_     |   |   _     /    _/   /   |   \    /  \_   /  ____/_\n |____|    |_______/_________:___\    /_________/____|_______/_______/________/\n      |____|                      \  /                       \n      :    :                       \/\n\n                                   AnD\n\n             _______ /|   _______/\_______________    _____ \n            /~ ____// | __\___  ~__~/  _____/~   ~\  /~ ¡ ~\.  \n           //  __)_// |/ ~\  /  :| //  __) //   .__)//  |  \\\\n           \\     ~\\ ~   \\/   || \\     ~\\   : \\\\      / \  \n            \  ____/\______/\____|  \  ____/\____ // \. |__/  /\n             \/ .____/\______/\_____|\/ .TeTSUo__\/ / \/ ____/\n              \/                      \/          \/   \/ \n\n\n@ENDNODE\n\n@NODE "FLAME" "Flame Strike"\n           .    .         .         .        .\n   _______/|___/|________/|____ ___/|_______/|\n _/        l_   |    _    l_   |    l_       l_.........................\n/¬     _____j   |    ¬     l   !     l    ____j                        :\nY         |    _|__  .     | \ : /   |  _____j_     ·fLAME^sTRIKE·     :\n|     ____j   /    l :     |  \ /    |        l                        :\n|        |  _/     | :     |   :     |        |ElTECH EHQ·Megastyle WHQ:\n|        |         | !     |   !     |        |                        :\n|       ||        || |     |   |     |       ||                        :\nl________j_________j_|     |___|     |________jHOt WAREZ·CODERS CORNER·.\n :                   l_____j   l_____j [nUMEN] CHAtABlE SYSOP·YouNameIt.\n :  cREW:                    .         .      .     .         .        .\n :Splash/ElTECH^MGS!  ______/|________/|_____/|____/|____ ___/|_______/|\n :UnmaD/eXCALIBUR   _/  _____j_        l_   _ l_    l_   |    l_       l_  \n :    [YOU?]       /_____     l         l   ¬  l     l   !     j    ____j\n :                 Y     \    |    _____j    __j_    |   :  __/   _____j_\n :BIG /X conf with |      \   |      |    .     |    |   .    \         l\n :almost 400 files!|       \  |      |    :     |    |   :     |        |\n :                 |          |      |    !     |    |   !     |        |\n :.[+47·51631702]  |         ||     ||    |     |   ||   |     |       ||\n.:::....... .... ..l__________j______j____|     |____j___|     |________j\n :                                      : l_____j /X 4.9 l_____j :\n .                                      :........................:\n .\n@ENDNODE\n\n@NODE "MEGASTYLE" "About Megastyle"\n\n                                                               @{" Go back.. " Link MAIN}\n\nMegastyle is a new AmiExpress-Support group formed by Lizard of Spaceballs in\nthe middle of may 1995.\n\nOur main goal is to support all the /X-boards out there with the best doors\naround. We try hard to make our products as system-friendly as possible and\nwith unique configuration possibilities.\n\n\nWe want to be the leading /X-development group in the future, and therefore\nneed more skilled coders and ANSI-artist to make our products even better!\n\nIf you''re interesting in teaming up, then take a look at the contact-info.\n\n\n\n   _________ \n    _______ )  ·M·e·g·a·S·t·y·l·e·  ·P·r·o·d·u·c·t·i·o·n·s·\n           )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\nEven if we are a pretty new group we have released a couple of doors allready.\n\nSplash:\nAutoreward v1.2\nGlobalDupe v1.3\nSysDL      v3.0\n\nLizard:\nBulls      v1.0\nNodeStatus v1.2\n\nAll these doors are just GREAT so check''em out! And more releases to come in near \nfuture!\n\n\n   _________ \n    _______ )  ·M·e·g·a·S·t·y·l·e·  ·B·o·a·r·d·s·\n           )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           +47-51-631702 -=- @{"FlameStrike" Link "FLAME"} ·oOo· Sysop : Splash\n           +47-51-417240 -=- @{"Noiseless  " Link "NOISELESS"} ·oOo· Sysop : Lizard (NightBBS)\n           +47-77-748689 -=- @{"Eternity   " Link "ETERNITY"} ·oOo· Sysop : Woober\n           +47-51-575227 -=- @{"Total Panic" Link "TOTALPANIC"} ·oOo· Sysop : Jedi\n@ENDNODE\n@NODE "NOISELESS" "Propaganda : Noiseless BBS!"\n                                                               @{" Go back.. " Link "MEGASTYLE"}\n\n                                        .\n                                           ·\n   _  _  _ _______  _____ __ _____ _____:  :   _____  _____  _____ __ _  _   _\n_   _  _ ______   ||     (__)     |   __|  |  |   __||  ___||  ____ __ _ _  _\n            |  |  ||  |  |  l  `--|  _/_|  |__|  _/_ l  ''--.l  ''--.\n            |  |  ||  |  |  |--,  |  l  |  l  |  l  ||--,  ||--,  |\n            l__|  l|_____l__l__   l__   l__   l__   |l__   ll__   l\n               `--''            `--''  `--''  `--''  `--''   `--''   `--''\n\n                           SysOp : Lizard/Spaceballs\n\n      Phone : +47-51417240, only available between : 23:00PM -> 07:00AM.\n\n@ENDNODE\n@NODE "ETERNITY" "Propaganda : Eternity BBS!"\n                                                               @{" Go back.. " Link "MEGASTYLE"}\n\n                                                               ._____.\n  _____________________________________________________________:__ ._|__\n  \__ _____/___   _   / _____/______  \_   .  _/______ /     _   / |   /\n   /  ___/   /     \_/ ___/    /  _/  _/   |    \    \/¬\     \_/    _/\n  /_________/_______\_________/___\     \__|     \_______\_____\_____|\n                               -cDr\_____\ l______\\n.                                                                       .\n+-÷aMiGA ^ aSCiI ^ mODUlES ^ hACKErS lAnD ^ /X sUPpORT ^ pUBLiC dOMAiN÷-+\n:           [f]EATURING: A1200/020 ^ oNE (n)oDE (14k4 mAXLiTE)          :\n|          [m]ANAGEMENT: [w@@ßE®^tHg^nEo^mGs^bDz]-[SiENCE^tHg]          |\n!   tECHNOLOGY [nHq] · nEO [nHq] · mEGASTYLE [hQ] · bANANa dEZIGn [hQ]  !\n+÷---------------------------------------------------------------------÷+\n:                   [n]UMBER: +47-777-48689 [23 - 07]                   :\n`÷---------------------------------------------------------------------÷''\n\n@ENDNODE\n@NODE "TOTALPANIC" "Propaganda : Total Panic BBS!"\n                                                               @{" Go back.. " Link "MEGASTYLE"}\n\n «*»  Total Panic - 28.8kb v.all - Sysop : Jedi - Number : +47-51-575227  «*»\n\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',13077,4,0,NULL,NULL,'mgs_awrd','scan',1780048595);
INSERT INTO door_catalog VALUES('mgs__rew','MGS!-REW.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MGS!-REW.LHA','autoreward','XIM','autoreward',NULL,'Splash','MGS!','_\_/    / _  __  ______ _______/__  ___    / | _ \  /     /  __/__/   /_ _   /   ___   / |__\ \/ /___/_____________/____/____//___/',replace(' ___     _______________________ _ _________\n_\_/    / _  __  ______ _______/__  ___    /\n| _ \  /     /  __/__/   /_ _   /   ___   /\n|__\ \/ /___/_____________/____/____//___/\n    \  /                   .------------.\n     \/ AutoReward 1.0 «-- ÷-  styLE!   ¡\n          By Splash        `------------÷\n EXAMINE door that will automaticly give|\n users a specified number of credz for  |\n their UL. Different credz for each conf|\n -[05.05.95]------ ---- ---------·st!·--''\n [World release at FlAMe StRiKe MGS! WHQ]\n','\n',char(10)),'autoreward.guide',replace('@database "GlobalDupe.Guide"\n@WIDTH 77\n@NODE Main "MAIN" "Welcome to GlobalDupe Documentation"\n\n .--------------------  ---(c)-[ mEGAStYLE! pRODUCtiON ''95\n |    ____     _______________________________  _ _____________ _\n ! ___\ _/    / _  ___  __________  _________/_ __   ____       /\n . |    _ \  /      /  ___/_____/    /__ _      /    _//_      / -----.\n ¦ |st!  \ \/ /    /    /      /       /       /     _____    /   -- -÷ -»\n | |______\  /_______________________________________//______/ -------''\n |         \/           \n |\n-÷- -» _____________ ______          _____     _ ______      _ _______ ____\n |  ___\   ________/_     /_       _/    /___         /    _ __  _________/\n |  |__________     /    __/______/     /    \ /     /_______/  ___/_______\n |  |      |       /    /        /     /      \     /       /    /        /\n |  |______________________________________    \_________________________/\n .                              _  _ _____¬_____/\n |\n |\n `--------------------------------------------------- ------------ -[   -»\n\n\n\n\n \n  \n                           AutoReward 1.0 (05/05-95)\n     \n                          By Splash/ElTECH & Megastyle\n                                         \n                          @{"What is AutoReward ?      " LINK "ABOUT"}   \n                          @{"Requirements.             " LINK "REQ"}                \n                          @{"Installation.             " LINK "INSTA"}              \n                          @{"Credits                   " LINK "CREDS"}\n                          @{"Greetings.                " LINK "GREET"}                 \n                          @{"About Megastyle.          " LINK "MEGASTYLE"}\n                          @{"How to contact the Author " LINK "HOWTOCONTACT"}\n\n\n              \n@ENDNODE\n\n\n\n\n\n\n\n\n\n\n@NODE "ABOUT" "What is AutoReward ?"\nAutoReward is a simple little EXAMINE door that will check which conf a file is\nuploaded to, and you can configure how many *credz an upload in this conf should \nbe rewarded with. If you for example has an /X conf (like me) and would like to \nreward all /X uploads with 2*credz, then all you have to do is install this door,\nconfigure it, and all rewarding will be automatic !\n@ENDNODE\n\n@NODE "REQ" "Requirements."\n\n\nA Commodore Amiga computer (Pese suxx :-) running on kick 2.0+, \n/X (preferably 4.x) \n \n\nThis door uses the AEDoor.libary, so you should have this in LIBS:\n(If you haven''t got it then call me or your local /X board to get it...) \n@ENDNODE\n\n\n@NODE "INSTA" "Installation."\n\n\n                             \nJust copy the included files to the correct dirs, that''s it.... \n\nIf you allready have got a file called EXAMINE1.info in syscmd/ you can rename the\none in this archive to EXAMINE2.info or whatever. \n\nThe configuring is done in the autoreward.info\nYou use the tooltype CONF.x=c where x is the conf number and c is the number of \ncredz to be given in this conf.\n\nNB ! \n\n@{b}You only have to have a tooltype for those confs where more than 1*credz should \nbe given!@{ub}\n@ENDNODE\n\n@NODE "HOWTOCONTACT" "How to contact the Author"\n\n \nHow to contact me:\n\n@{"Flame Strike" LINK "FLAME"} :+47 51631702\n\nOr snailmail: Splash/ElTECH & Megastyle\n              Lindeveien 69\n              N-4300 Sandnes\n              Norway\n@ENDNODE\n\n@NODE "CREDS" "Credits."\n\nCode,Idea    - Splash/ElTECH & Megastyle\nDoor Design  - Splash/ElTECH & Megastyle\nGuide Design - Splash/ElTECH & Megastyle\n\n(Guess I did it all by myself then :-)\n@ENDNODE\n@NODE "GREET" "Greetings."\n\n\n                                  \n\n                         Greetings to all my friends ! \n\nSpecial greetings to all /X coders \n\nAND OFCOURSE ALL MEMBERS OF :\n\n             _______ /|   _______/\_______________    _____ \n            /~ ____// | __\___  ~__~/  _____/~   ~\  /~ ¡ ~\.  \n           //  __)_// |/ ~\  /  :| //  __) //   .__)//  |  \\\\n           \\     ~\\ ~   \\/   || \\     ~\\   : \\\\      / \  \n            \  ____/\______/\____|  \  ____/\____ // \. |__/  /\n             \/ .____/\______/\_____|\/ .TeTSUo__\/ / \/ ____/\n              \/                      \/          \/   \/ \n\nSpecial greetings to:\nLizard and stRAtOS! -> Let''s make Megastyle the biggest /X group EVER!\n\nSome messages:\nLizard   - Hope you got your modules working again :-)\nstRAtOS! - Make more Megastyle ASCII''s.... I didn''t many to choose from...\n@ENDNODE\n\n@NODE "FLAME" "Flame Strike"\n           .    .         .         .        .\n   _______/|___/|________/|____ ___/|_______/|\n _/        l_   |    _    l_   |    l_       l_.........................\n/¬     _____j   |    ¬     l   !     l    ____j                        :\nY         |    _|__  .     | \ : /   |  _____j_     ·fLAME^sTRIKE·     :\n|     ____j   /    l :     |  \ /    |        l                        :\n|        |  _/     | :     |   :     |        |ElTECH EHQ·Megastyle WHQ:\n|        |         | !     |   !     |        |                        :\n|       ||        || |     |   |     |       ||                        :\nl________j_________j_|     |___|     |________jHOt WAREZ·CODERS CORNER·.\n :                   l_____j   l_____j [nUMEN] CHAtABlE SYSOP·YouNameIt.\n :  cREW:                    .         .      .     .         .        .\n :Splash/ElTECH^MGS!  ______/|________/|_____/|____/|____ ___/|_______/|\n :UnmaD/eXCALIBUR   _/  _____j_        l_   _ l_    l_   |    l_       l_  \n :    [YOU?]       /_____     l         l   ¬  l     l   !     j    ____j\n :                 Y     \    |    _____j    __j_    |   :  __/   _____j_\n :BIG /X conf with |      \   |      |    .     |    |   .    \         l\n :almost 400 files!|       \  |      |    :     |    |   :     |        |\n :                 |          |      |    !     |    |   !     |        |\n :.[+47·51631702]  |         ||     ||    |     |   ||   |     |       ||\n.:::....... .... ..l__________j______j____|     |____j___|     |________j\n :                                      : l_____j /X 4.X l_____j :\n .                                      :........................:\n .\n@ENDNODE\n\n@NODE "MEGASTYLE" "About Megastyle"\n\nMegastyle is a new /X developer group consisting of /X coders and dezigners.\nWe need more members, so if you want to join or have got anything to \ncontribute with (Ideas, hints, dezigns, bugreports aso.) then contact me.\n\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',7301,1,0,NULL,NULL,'mgs_awrd','scan',1780048595);
