           finished. YES!!!\n\n3o.o3.96                Version 1.oß is a bit modified and made version @{fg shine}1.o@{fg text} and\n                        released public.\n\n@endnode\n','\n',char(10)),NULL,NULL,36035,5,0,NULL,NULL,NULL,'scan',1780048595);
INSERT INTO door_catalog VALUES('mgs__zs1','MGS!-ZS1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MGS!-ZS1.LHA','zippy-search','XIM','zippy-search',NULL,NULL,'MGS!','____\        /___\   ____  /____/ ___/______ _     \l      _  \_______ ____\/       __l_________  __l__       l ___',replace('    __________   ___________     _____\n____\        /___\   ____  /____/ ___/______\n               _     \l      _  \_______\n____\/       __l_________  __l__       l ___\ng®m /________)   e^D \_____)   (_________)\n          «« m e g a s t y l e  »»\n               ...presents...\n \n             Zippy-Search v1.o.\n \nNEW and IMPROVED Search-Utility for /X & S!X\n','\n',char(10)),'Zippy-Search.GUIDE',replace('@database "mEGAZTYLE.guide"\n@node MAIN\n@title "                                              »«  m e g a s t y l e  »«  r u l e s  »«"\n@{b}\n                              @{u}m e g a s t y l e@{uu}\n\n                 ________   _________   _________     ______.\n           ______\      /___\  ___  /___\  ___  /_____\____ l____\n     ______\              _     l/    _    \l     _     __/     /_______\n.___(       \____\/     __l__  _______l_______  __l__   \l_____/        )___.\n|                /______)   (_____/        \____)   (____\                  |\n|                                                                           |\n| g®m      _____      ___.           .______   ___.       _________     e^D |\n|___  ____/ ___/______\  l___________|     /___\ _l_______\  ___  /____  ___|\n   (__\   \______   _    __/     _   l       _   \      _     l/      /__)\n       \__      l __l__  l     __l_______  __l_        _l_  _________/\n         (________)   (________)     \_____)  (________) (_____/ @{ub}\n\n\n\n@{fg shine}                  p r e s e n t s   a   n e w   d o o r :@{fg text}\n\n\n                   @{b}    @{bg shine}@{u}Z i p p y - S e a r c h    1 . o@{bg back}@{ub}@{uu}\n\n\n\n\n              @{"           d o c u m e n t a t i o n           " link index}\n\n\n\n\n@endnode\n\n@node index\n@title "                                             »» i n d e x ««"\n\n\n    @{u}                                                          @{uu}\n\n\n@{b}                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n         ____        __________          ____.   ___________   ½½½½½  ½½½½½\n________(___/________\ __     /__________\___l___\  ____   /__    `½½½½''\n                   _   l/       _      _____/  _      l/      ½½½½½½  ½½½½½½\n_____            __l___/      __l__    l     __l__  __________½½½½½½  ½½½½½½\n    (____________)    /_______)   (__________)   (_____/      ½½½½½½  ½½½½½½\n                                                              ½½½½½½  ½½½½½½\n                                                              ½½½½½½  ½½½½½½\n   @{fg shine} @{"            introduction             "  link introduction      }    @{fg text}                ½½½½½½  ½½½½½½\n@{fg shine}    @{"            installation             "  link installation      }          @{fg text}          ½½½½½½  ½½½½½½\n@{fg shine}    @{"              how 2 use              "  link how 2 use         }\n    @{"              copyright              "  link copyright         }\n    @{"          changes ÷ history          " link changes ÷ history  } @{ub} @{fg text}\n\n\n    @{u}                                                          @{uu}\n\n\n@endnode\n\n\n\n\n\n\n\n\n@node introduction\n                                                                 .\n\n                                                                 :\n                                                                 :\n             __________________.______.      ________            :\n          ._(___)_.   ___     _|      l_____\\_     /____________:_ _\n          |       |----/      \        /     \   __/\      __    :\n          l_______|   /_______/        |-----/_______\____       :\n                              l________|(rLf)            /-------:-\n                                                                 :\n                                                                 :\n                                                                 :\n                                                                 .\n\n\n@{fg shine} Zippy-Search @{fg text}is probably the most used searchtool for /X and S!X.\n However, most of the searchers previously released have not support for large\n dirlists, or more than 10 conference Dir(nr) files containing your File_id`s.\n\n   I think of this door as one of the FASTEST ever for the /X or S!X, and it\n    also includes many new features NEVER been used in earlier Z-versions.\n               Just check out the screenshots before installing!\n\n\n A especially thanks to Kingpin/Spaceballs for the nice Beta-testing and good\n           support + design ideas! - I hope you enjoy the result! :)\n\n\n       The things that makes this Zippy differ from other searchers are:\n    <«-------------------------------------------------------------------»>\n\n       «»          Simple and easy interface toward the user          «»\n       «»     Logical analyze of arguments provided to the door.      «»\n       «»     Highly OPTIMIZED Assembler search-routines! (FAST!)     «»\n       «»   The best Error-trap system ever made to a AmiX/S!X door   «»\n       «»   Fully compatible with older versions of Zippy-Searchers   «»\n\n\n           - - - --- ------[ lizard of megastyle! ]------ --- - -  -\n\n@endnode\n\n\n\n\n\n\n@node installation\n\n .\n                                                                              .\n :\n :                                                                            :\n : __        _____ .___.   ______ __.              _________. ____________    :\n_:(__)_______\_ _/_|_  l___\__  // _l______.  _____\__  //  l____)_  _   /____:_\n :    | __    /_  _ /   /     _ // \     /_l__\__     _ //   /    |_    / ___ :\n_:____|--/   /-/  //    |--/____/----/__/ \     /--/____/    |____|/---/\--/  :\n :      /___/ /___/_____|(rLf)          \---/__/       l_____|            /___:_\n :                                                                            :\n :                        i n s t a l l a t i o n                             :\n .                                                                            :\n                                                                              .\n\n@{fg shine}To install...@{fg text}\n\n Well, it''s very simple to install. Just copy the directory-structure as it is\n presented in its original archive into your BBS: assignment.\n\n\n Megastyle! is not to held responsible if this program should cause any damage\n to your computer or lead to loss of data. It is provided as is, and is being\n installed and used on your own risk. There is no installer-script provided\n together with the UNREGISTERED versions of the Megastyle! productions!\n\n\n@endnode\n\n\n\n\n\n@node how 2 use\n@title "                                              )>» h o w  2  u s e «<("\n\n                                      ½½½½½½½½½½½½½½½½½½½½½½½.\n                                     ½½½½½½½½         ½½½½½½½½\n      ____.            _________         _______      ½½½½½½½½\n   ___\ __l____________\       /_________\     /______½½½½½½½½\n   \    \___        _             _      /\           ½½½½½½½½\n    \______/      __l__    "    __l__           ___   ½½½½½½½½\n          /_______)   (_________)   (___________) /_  ½½½½½½½½\n                                                   |  ½½½½½½½½\n                ½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½''\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½      ._____      _____    |   _|________\n                ½½½½½½½½______|    /_____/ ___/____|___\  ____  /___\n                ½½½½½½½½      |       _  \_______   _       l/     /\n                ½½½½½½½½__    l     __l__       l __l__  _________/\n                ½½½½½½½½ (__________)   (_________)|  (____/\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½  @{fg shine}   h o w       u s e  @{fg text}   |  ½½½½½½½½\n                ½½½½½½½½      @{fg shine}       2    @{fg text}         |  ½½½½½½½½\n                ½½½½½½½½                           |  ½½½½½½½½\n                ½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½\n\n\n\n     Just @{"Install" link installation} it and run it from /X or S!X.\n\n  Then you can type "Z HELP" or "Z ?" if you should ever wonder how it works.\n\n\n\n\n                         About the Dirlist operators :\n             <«=-----------------------------------------------»>\n\n \n  You may use any of these syntax : 1,2,3-6,u,a \n\n  A = ALL directories. When encountered this letter in a dirlist, all dirs will\n      automaticly be searched through. Even if you have specified dirnr infront\n      of this argument.\n\n  U = Upload dir. Usually the last directory of your conference DirX structure.\n\n  , = Seperator. Used to choose multiple dirnr. to check through. 1,2,3,4..etc.\n\n  - = Mark dirs. Handy when you wish to search through dirs 1 => 7.. "1-7" will\n      then be the correct syntax. Can be combined with seperator. \n\n\n      For instant : Z 1,4-7,12-22 my-search-words..\n\n      (or like this: Z my-search-words.. 1,4-7,12-22 ... The same thing! :)\n\n\n\n\n\n                       About the Searchlist operators :\n             <«=----------------------------------------------»>\n\n  You may use any of these syntax : &, !, / \n\n  & = logic AND of searchwords. For instant, you wish to find a file_id which\n      contains both the word "Amiga_News" AND "#14" ... Then you can simply\n      write : Z a Amiga_news & #14   ... and you would skip all the other files\n      that doesn''t have BOTH these words in the File_id... VERY useful when\n      searching for a specified disk-nr. in a diskset for a program.\n\n  ! = logic NOT. This is used the same way as the &, but often combined with\n      the & operator. Example : Z a Amiga_news &! #14 ! Lizard\n\n  / = Is used to find a file_id with none of the above operators involved.\n      For instant : Z a lizard & instant / magz\n\n      This would lead to a search after the two words "lizard" AND "instant",\n      or a file_id with only the word "magz" in.  \n\n\n\n  REMEMBER : The search-string is NON-CASE-SENSITIVE... To easy your pain! :)\n\n\n\n  The Searchlist options will ONLY be available in the REGISTERED versions. \n    Do consider to register your door. You''ll then be able to recieve the \n                           future upgrades for FREE.\n\n\n@endnode\n\n\n\n\n\n\n@node copyright\n            .\n\n            :\n            :                                      ________ _______ _  _\n           _:__________  _________________ ________\__   _//\n            :      ___/__\__    __      /\\\ __      /___ /       .\n          _ :_ ____        /___        /     \______/   /_________:_ _\n            :     /-------/ __/-------/\______|        ___________|\n            :     _________(___)__________    ________/       /   l_\n           _:____\\_     /       |    ___/____\__   _        /     /\n            :     \   __/\_______|   /_         /---/       /      |\n         - -:-----/_______\(rLf) \----/________/   /_______/_______|\n            :\n            :                 c o p y r i g h t\n            :\n            .\n\n\n\n                                 ---[%]---\n\n                    Zippy-Search is a Megastyle! production\n\n               Code, idea & design by   Lizard of TBL MGS!\n               Error-logo by            Magz of GRT MGS!\n               Tooltype read code by    Lizard of TBL MGS!\n\n\n              \n\n                         Creds for this GUIDE file\n\n               Slapped together by      Lizard\n               Asciis by                Relief   of T! MGS! 5D\n                                        Grimlock of GRT E^D MGS!\n\n                                 ---[%]---\n\n\n\n                      Megastyle! does now consist of\n \n               Leader . . . . . . . . . Lizard\n               Code . . . . . . . . . . Lizard\n                                        Magz\n                                        Instant\n                                        Splash\n               AscII. . . . . . . . . . Relief\n                                        U-MAN\n                                        Grimlock!\n                                        Magz\n               Boards . . . . . . . . . Noiseless - WHQ         LIZARD\n                                        Genetic Waste           MAGZ\n                                        Ecstatica               INSTANT\n                                        Traders Paradise        U-MAN\n\n                                 ---[%]---\n\n\n\n\n\n\n   ............\n   ::        ::\n   ::        ::\n    .        ::\n   /_____    ::          ___________                                          .\n  /_     \//\____________\      ___/_______    _________\n //      \/        _     /     /_         /____\___    //                     :\n/--------/     .---/____/   .---/________         _    //                     :\n     -T!/______\  /_       _|  .______.  \-----/_______/                      :\n                  __\   __/____|_     l_          _______.     _____________  :\n   ::        ::   \  \__    _ _        /_____ ____\     _l_____\     _     /__:_\n   ::        ::    \--(/      /            _//          \        ____/____/  /:\n   ::        ::       /____________________ /      /\-----/_____/   /_________:_\n   ::        ::                           /_______/(rLf)                      :\n   ::........::                                                               :\n                                                                              :\n                        m e g a s t y l e    ¹ 9 9 6                          :\n                                                                              .\n\n@endnode\n\n\n\n\n\n\n@node changes ÷ history\n\n\n    ___.        __      ____    ___.      _____  ½½½½½½½½½½      .____\n  ._\ _l_______(_/_____/ __/____\  l______\   /__½½½½   ½½½______|   /_.\n  |   \__   _       _  \____  _    __/  _        ½½½½½½½''        l     |\n  |____l/  _l_     _l_     l _l_   l   _l_  "  __½½½½   ½½½½½_______  _l\n g®m   /___) (_____) (_______) (_______) (_____) ½½½½   ½½½½½   \_____)\n                                                 ½½½½   ½½½½½ e^D\n\n                               ...HISTORY...\n\n\n\n2000BC          Started on the Door, gave it to all the MGS!-members AND one\n                beta-version to Kingpin for heavy-testing. THANX MATE!\n\n29.03.96        First Public-Release v1.o of the door. Together with a bunch\n                of other doors + a intro. - I sure hope you have it ALL! :)\n\n\n\n\n\n\nThanks to the following boards for helpful beta-testing of MegaStyle-products:\n«----------------------------------------------------------------------------»\n\n                             Genetic Waste (Magz)\n  Checkpoint (Kingpin)   -   Power Rage (Instant)   -   EveryWare (-Shade!)\n\n\n\n@endnode\n','\n',char(10)),NULL,'auto-added',31693,5,0,NULL,NULL,'mgszippy','scan',1780048595);
INSERT INTO door_catalog VALUES('mgs_arew','MGS-AREW.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MGS-AREW.LHA','autoreward','XIM','autoreward',NULL,'Splash','MGS','_\_/    / _  __  ______ _______/__  ___    / | _ \  /     /  __/__/   /_ _   /   ___   / |__\ \/ /___/_____________/____/____//___/',replace(' ___     _______________________ _ _________\n_\_/    / _  __  ______ _______/__  ___    /\n| _ \  /     /  __/__/   /_ _   /   ___   /\n|__\ \/ /___/_____________/____/____//___/\n    \  /                   .------------.\n     \/ AutoReward 1.3 «-- ÷-  styLE!   ¡\n                 By Splash `------------÷\n Now also possible to reward group      |\n releases. Auto crediting by filename or|\n by conf (or both!) BUGFIX from v 1.2   |\n -[06.06.95]------ ---- ---------·st!·--''\n [World release at FlAMe StRiKe MGS! WHQ]\n','\n',char(10)),'autoreward.guide',replace('@database "AutoReward.Guide"\n@WIDTH 77\n@NODE Main "MAIN" "Welcome to AutoReward Documentation"\n                                                   __.       \n______ ______________ ______ ________    _________/ _|_____/\______ _ __________\n ____ V _________   // ____/_______  \  _\  ______   _  __/  \  __/_________   /\n |   \_/   |   _/  //  \___  |   _/   \/  \___   \   |___     \ \      /  _/  /\n |    |    |  ____/_     |   |   _     /    _/   /   |   \    /  \_   /  ____/_\n |____|    |_______/_________:___\    /_________/____|_______/_______/________/\n      |____|                      \  /                       \n      :   _____                    \/\n           ____\__________\n            ____\_______  )\n                 \/     ) ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n                        ¯¯¯¯¯¯¯¯¯¯¯¯¯¯ ·g·i·v·e·s·  ·y·o·u·\n\n                                                   \n                        .-------------- -       - ---.\n                        |                          ¯7|\n                        |                            :\n                        :  AutoReward 1.3 (06/06-95) .\n                        ·\n                        ·             by\n                                                     ·\n                        ·  Splash/ElTECH & Megastyle :\n                        :·                           |\n                        |l_                          |\n                        `----- -       - ------------''\n                                         \n                         @{"What is AutoReward ?      " LINK "ABOUT"}   \n                         @{"Requirements.             " LINK "REQ"}                \n                         @{"Installation.             " LINK "INSTA"}              \n                         @{"Credits                   " LINK "CREDS"}\n                         @{"Greetings.                " LINK "GREET"}                 \n                         @{"About Megastyle.          " LINK "MEGASTYLE"}\n                         @{"How to contact the Author " LINK "HOWTOCONTACT"}\n\n\n              \n@ENDNODE\n\n\n\n\n\n\n\n\n\n\n@NODE "ABOUT" "What is AutoReward ?"\n\n\nAutoReward is a simple little EXAMINE door that will check which conf a file is\nuploaded to, and you can configure how many *credz an upload in this conf should \nbe rewarded with. If you for example has an /X conf (like me) and would like to \nreward all /X uploads with 2*credz, then all you have to do is install this door,\nconfigure it, and all rewarding will be automatic !\n\n*New in this version is the possibility to rive extra credits for special group\nreleases such as fexs files starting with MGS!-,ELT- or PGS-\n\nYou can have a different amount of credits for each group and also a different\ncomment for each group which will be displayed if a file from that group are \nuploaded. You can also use this door without giving any credist just for using \nthis commenting feature!\n@ENDNODE\n\n@NODE "REQ" "Requirements."\n\n\nA Commodore Amiga computer running on kick 2.0+, /X (preferably 4.x) \n \n\nThis door uses the AEDoor.libary, so you should have this in LIBS:\n(If you haven''t got it then call me or your local /X board to get it...) \n@ENDNODE\n\n\n@NODE "INSTA" "Installation."\n\n\n                             \nJust copy the included files to the correct dirs, that''s it.... \n\nIf you allready have got a file called EXAMINE1.info in syscmd/ you can rename the\none in this archive to EXAMINE2.info or whatever. \n\nThe configuring is no longer done in the autoreward.info, it is now done in\nautoreward.cfg in the same path as this door.\nSe the included .cfg file for more info on this subject\n\n@{b}You only need to include those confs where more than 1*credz should be given!@{ub}\n@ENDNODE\n\n@NODE "HOWTOCONTACT" "How to contact the Author"\n\n \nHow to contact me:\n\n@{"Flame Strike" LINK "FLAME"} :+47 51631702\n\nOr snailmail: Splash/ElTECH & Megastyle\n              Lindeveien 69\n              N-4300 Sandnes\n              Norway\n@ENDNODE\n\n@NODE "CREDS" "Credits."\n\nCode,Idea    - Splash (borrowed one routine from Lizard though :-)\nDoor Design  - Splash\nGuide Design - Splash/Lizard\n\n@ENDNODE\n@NODE "GREET" "Greetings."\n\n   _________ \n    _______ )  ·M·e·g·a·S·t·y·l·e·  ·s·e·n·d·s·  ·g·r·e·e·t·i·n·g·  ·t·o·\n           )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n    Spaceballs, Eltech, Andromeda, CNCD, Parallax, Complex, Virtual dreams,\nStone Arts, Rebels, TRSI, Scoopex, Avalon, Aquarious, Access, Prestige, Skid Row\n\n                   And to all the other /X-coders out there!\n\n\n________ \n ______ ) ·S·p·l·a·s·h·  ·s·e·n·d·s·  ·s·p·e·c·i·a·l·  ·g·r·e·e·t·i·n·g·  ·t·o·\n       )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n       ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n                                  \n\n                         Greetings to all my friends ! \n\nLizard      : LONG live Megastyle!\nJedi        : Welcome to Megastyle! Hope we can use a design by you soon...\nPreacher    : Håper du kan få deg tlf linje snart.\nSkinner     : How about some more activity in ElTECH ? MORE releases! :-)\nMic Flair   : Hope you like this door, let''s have another chat!\nMaze        : Like DC? New dezign+magpart comming up!\nStratos!    : 2 bad you had to leave, you''ll regret it :-)\nShade       : Hope to C your board up''n''running soon.\nScience     : Still haven''t found any bugs ? :-)\nNike        : Nice talkin'' to yah..\nWoober      : Looking forward to C more releases from you..\nTHEGODFATHER: Board up''n''running soon ?\nACID        : Hi!\n\n\n(+ the rest I 4got..)\n\nAND OFCOURSE ALL MEMBERS OF :\n______ ______________ ______ ________    _________/ _|_____/\______ _ __________\n ____ V _________   // ____/_______  \  _\  ______   _  __/  \  __/_________   /\n |   \_/   |   _/  //  \__   |   _/   \/  \___   \   |___     \ \      /  _/  /\n |    |    |  ____/_     |   |   _     /    _/   /   |   \    /  \_   /  ____/_\n |____|    |_______/_________:___\    /_________/____|_______/_______/________/\n      |____|                      \  /                       \n      :    :                       \/\n\n                                   AnD\n\n             _______ /|   _______/\_______________    _____ \n            /~ ____// | __\___  ~__~/  _____/~   ~\  /~ ¡ ~\.  \n           //  __)_// |/ ~\  /  :| //  __) //   .__)//  |  \\\\n           \\     ~\\ ~   \\/   || \\     ~\\   : \\\\      / \  \n            \  ____/\______/\____|  \  ____/\____ // \. |__/  /\n             \/ .____/\______/\_____|\/ .TeTSUo__\/ / \/ ____/\n              \/                      \/          \/   \/ \n\n\n@ENDNODE\n\n@NODE "FLAME" "Flame Strike"\n           .    .         .         .        .\n   _______/|___/|________/|____ ___/|_______/|\n _/        l_   |    _    l_   |    l_       l_.........................\n/¬     _____j   |    ¬     l   !     l    ____j                        :\nY         |    _|__  .     | \ : /   |  _____j_     ·fLAME^sTRIKE·     :\n|     ____j   /    l :     |  \ /    |        l                        :\n|        |  _/     | :     |   :     |        |ElTECH EHQ·Megastyle WHQ:\n|        |         | !     |   !     |        |                        :\n|       ||        || |     |   |     |       ||                        :\nl________j_________j_|     |___|     |________jHOt WAREZ·CODERS CORNER·.\n :                   l_____j   l_____j [nUMEN] CHAtABlE SYSOP·YouNameIt.\n :  cREW:                    .         .      .     .         .        .\n :Splash/ElTECH^MGS!  ______/|________/|_____/|____/|____ ___/|_______/|\n :UnmaD/eXCALIBUR   _/  _____j_        l_   _ l_    l_   |    l_       l_  \n :    [YOU?]       /_____     l         l   ¬  l     l   !     j    ____j\n :                 Y     \    |    _____j    __j_    |   :  __/   _____j_\n :BIG /X conf with |      \   |      |    .     |    |   .    \         l\n :almost 400 files!|       \  |      |    :     |    |   :     |        |\n :                 |          |      |    !     |    |   !     |        |\n :.[+47·51631702]  |         ||     ||    |     |   ||   |     |       ||\n.:::....... .... ..l__________j______j____|     |____j___|     |________j\n :                                      : l_____j /X 4.9 l_____j :\n .                                      :........................:\n .\n@ENDNODE\n\n@NODE "MEGASTYLE" "About Megastyle"\n\n                                                               @{" Go back.. " Link MAIN}\n\nMegastyle is a new AmiExpress-Support group formed by Lizard of Spaceballs in\nthe middle of may 1995.\n\nOur main goal is to support all the /X-boards out there with the best doors\naround. We try hard to make our products as system-friendly as possible and\nwith unique configuration possibilities.\n\n\nWe want to be the leading /X-development group in the future, and therefore\nneed more skilled coders and ANSI-artist to make our products even better!\n\nIf you''re interesting in teaming up, then take a look at the contact-info.\n\n\n\n   _________ \n    _______ )  ·M·e·g·a·S·t·y·l·e·  ·P·r·o·d·u·c·t·i·o·n·s·\n           )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\nEven if we are a pretty new group we have released a couple of doors allready.\n\nSplash:\nAutoreward v1.2\nGlobalDupe v1.3\nSysDL      v3.0\n\nLizard:\nBulls      v1.0\nNodeStatus v1.2\n\nAll these doors are just GREAT so check''em out! And more releases to come in near \nfuture!\n\n\n   _________ \n    _______ )  ·M·e·g·a·S·t·y·l·e·  ·B·o·a·r·d·s·\n           )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           +47-51-631702 -=- @{"FlameStrike" Link "FLAME"} ·oOo· Sysop : Splash\n           +47-51-417240 -=- @{"Noiseless  " Link "NOISELESS"} ·oOo· Sysop : Lizard (NightBBS)\n           +47-77-748689 -=- @{"Eternity   " Link "ETERNITY"} ·oOo· Sysop : Woober\n           +47-51-575227 -=- @{"Total Panic" Link "TOTALPANIC"} ·oOo· Sysop : Jedi\n@ENDNODE\n@NODE "NOISELESS" "Propaganda : Noiseless BBS!"\n                                                               @{" Go back.. " Link "MEGASTYLE"}\n\n                                        .\n                                           ·\n   _  _  _ _______  _____ __ _____ _____:  :   _____  _____  _____ __ _  _   _\n_   _  _ ______   ||     (__)     |   __|  |  |   __||  ___||  ____ __ _ _  _\n            |  |  ||  |  |  l  `--|  _/_|  |__|  _/_ l  ''--.l  ''--.\n            |  |  ||  |  |  |--,  |  l  |  l  |  l  ||--,  ||--,  |\n            l__|  l|_____l__l__   l__   l__   l__   |l__   ll__   l\n               `--''            `--''  `--''  `--''  `--''   `--''   `--''\n\n                           SysOp : Lizard/Spaceballs\n\n      Phone : +47-51417240, only available between : 23:00PM -> 07:00AM.\n\n@ENDNODE\n@NODE "ETERNITY" "Propaganda : Eternity BBS!"\n                                                               @{" Go back.. " Link "MEGASTYLE"}\n\n                                                               ._____.\n  _____________________________________________________________:__ ._|__\n  \__ _____/___   _   / _____/______  \_   .  _/______ /     _   / |   /\n   /  ___/   /     \_/ ___/    /  _/  _/   |    \    \/¬\     \_/    _/\n  /_________/_______\_________/___\     \__|     \_______\_____\_____|\n                               -cDr\_____\ l______\\n.                                                                       .\n+-÷aMiGA ^ aSCiI ^ mODUlES ^ hACKErS lAnD ^ /X sUPpORT ^ pUBLiC dOMAiN÷-+\n:           [f]EATURING: A1200/020 ^ oNE (n)oDE (14k4 mAXLiTE)          :\n|          [m]ANAGEMENT: [w@@ßE®^tHg^nEo^mGs^bDz]-[SiENCE^tHg]          |\n!   tECHNOLOGY [nHq] · nEO [nHq] · mEGASTYLE [hQ] · bANANa dEZIGn [hQ]  !\n+÷---------------------------------------------------------------------÷+\n:                   [n]UMBER: +47-777-48689 [23 - 07]                   :\n`÷---------------------------------------------------------------------÷''\n\n@ENDNODE\n@NODE "TOTALPANIC" "Propaganda : Total Panic BBS!"\n                                                               @{" Go back.. " Link "MEGASTYLE"}\n\n «*»  Total Panic - 28.8kb v.all - Sysop : Jedi - Number : +47-51-575227  «*»\n\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',19649,3,0,NULL,NULL,'mgs_arew','scan',1780048595);
INSERT INTO door_catalog VALUES('mgs_atrw','MGS-ATRW.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MGS-ATRW.LHA','autoreward','XIM','autoreward',NULL,'Splash','MGS','_\_/    / _  __  ______ _______/__  ___    / | _ \  /     /  __/__/   /_ _   /   ___   / |__\ \/ /___/_____________/____/____//___/',replace(' ___     _______________________ _ _________\n_\_/    / _  __  ______ _______/__  ___    /\n| _ \  /     /  __/__/   /_ _   /   ___   /\n|__\ \/ /___/_____________/____/____//___/\n    \  /                   .------------.\n     \/ AutoReward 1.3 «-- ÷-  styLE!   ¡\n                 By Splash `------------÷\n Now also possible to reward group      |\n releases. Auto crediting by filename or|\n by conf (or both!) BUGFIX from v 1.2   |\n -[06.06.95]------ ---- ---------·st!·--''\n [World release at FlAMe StRiKe MGS! WHQ]\n','\n',char(10)),'autoreward.guide',replace('@database "AutoReward.Guide"\n@WIDTH 77\n@NODE Main "MAIN" "Welcome to AutoReward Documentation"\n                                                   __.       \n______ ______________ ______ ________    _________/ _|_____/\______ _ __________\n ____ V _________   // ____/_______  \  _\  ______   _  __/  \  __/_________   /\n |   \_/   |   _/  //  \___  |   _/   \/  \___   \   |___     \ \      /  _/  /\n |    |    |  ____/_     |   |   _     /    _/   /   |   \    /  \_   /  ____/_\n |____|    |_______/_________:___\    /_________/____|_______/_______/________/\n      |____|                      \  /                       \n      :   _____                    \/\n           ____\__________\n            ____\_______  )\n                 \/     ) ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n                        ¯¯¯¯¯¯¯¯¯¯¯¯¯¯ ·g·i·v·e·s·  ·y·o·u·\n\n                                                   \n                        .-------------- -       - ---.\n                        |                          ¯7|\n                        |                            :\n                        :  AutoReward 1.3 (06/06-95) .\n                        ·\n                        ·             by\n                                                     ·\n                        ·  Splash/ElTECH & Megastyle :\n                        :·                           |\n                        |l_                          |\n                        `----- -       - ------------''\n                                         \n                         @{"What is AutoReward ?      " LINK "ABOUT"}   \n                         @{"Requirements.             " LINK "REQ"}                \n                         @{"Installation.             " LINK "INSTA"}              \n                         @{"Credits                   " LINK "CREDS"}\n                         @{"Greetings.                " LINK "GREET"}                 \n                         @{"About Megastyle.          " LINK "MEGASTYLE"}\n                         @{"How to contact the Author " LINK "HOWTOCONTACT"}\n\n\n              \n@ENDNODE\n\n\n\n\n\n\n\n\n\n\n@NODE "ABOUT" "What is AutoReward ?"\n\n\nAutoReward is a simple little EXAMINE door that will check which conf a file is\nuploaded to, and you can configure how many *credz an upload in this conf should \nbe rewarded with. If you for example has an /X conf (like me) and would like to \nreward all /X uploads with 2*credz, then all you have to do is install this door,\nconfigure it, and all rewarding will be automatic !\n\n*New in this version is the possibility to rive extra credits for special group\nreleases such as fexs files starting with MGS!-,ELT- or PGS-\n\nYou can have a different amount of credits for each group and also a different\ncomment for each group which will be displayed if a file from that group are \nuploaded. You can also use this door without giving any credist just for using \nthis commenting feature!\n@ENDNODE\n\n@NODE "REQ" "Requirements."\n\n\nA Commodore Amiga computer running on kick 2.0+, /X (preferably 4.x) \n \n\nThis door uses the AEDoor.libary, so you should have this in LIBS:\n(If you haven''t got it then call me or your local /X board to get it...) \n@ENDNODE\n\n\n@NODE "INSTA" "Installation."\n\n\n                             \nJust copy the included files to the correct dirs, that''s it.... \n\nIf you allready have got a file called EXAMINE1.info in syscmd/ you can rename the\none in this archive to EXAMINE2.info or whatever. \n\nThe configuring is no longer done in the autoreward.info, it is now done in\nautoreward.cfg in the same path as this door.\nSe the included .cfg file for more info on this subject\n\n@{b}You only need to include those confs where more than 1*credz should be given!@{ub}\n@ENDNODE\n\n@NODE "HOWTOCONTACT" "How to contact the Author"\n\n \nHow to contact me:\n\n@{"Flame Strike" LINK "FLAME"} :+47 51631702\n\nOr snailmail: Splash/ElTECH & Megastyle\n              Lindeveien 69\n              N-4300 Sandnes\n              Norway\n@ENDNODE\n\n@NODE "CREDS" "Credits."\n\nCode,Idea    - Splash (borrowed one routine from Lizard though :-)\nDoor Design  - Splash\nGuide Design - Splash/Lizard\n\n@ENDNODE\n@NODE "GREET" "Greetings."\n\n   _________ \n    _______ )  ·M·e·g·a·S·t·y·l·e·  ·s·e·n·d·s·  ·g·r·e·e·t·i·n·g·  ·t·o·\n           )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n    Spaceballs, Eltech, Andromeda, CNCD, Parallax, Complex, Virtual dreams,\nStone Arts, Rebels, TRSI, Scoopex, Avalon, Aquarious, Access, Prestige, Skid Row\n\n                   And to all the other /X-coders out there!\n\n\n________ \n ______ ) ·S·p·l·a·s·h·  ·s·e·n·d·s·  ·s·p·e·c·i·a·l·  ·g·r·e·e·t·i·n·g·  ·t·o·\n       )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n       ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n                                  \n\n                         Greetings to all my friends ! \n\nLizard      : LONG live Megastyle!\nJedi        : Welcome to Megastyle! Hope we can use a design by you soon...\nPreacher    : Håper du kan få deg tlf linje snart.\nSkinner     : How about some more activity in ElTECH ? MORE releases! :-)\nMic Flair   : Hope you like this door, let''s have another chat!\nMaze        : Like DC? New dezign+magpart comming up!\nStratos!    : 2 bad you had to leave, you''ll regret it :-)\nShade       : Hope to C your board up''n''running soon.\nScience     : Still haven''t found any bugs ? :-)\nNike        : Nice talkin'' to yah..\nWoober      : Looking forward to C more releases from you..\nTHEGODFATHER: Board up''n''running soon ?\nACID        : Hi!\n\n\n(+ the rest I 4got..)\n\nAND OFCOURSE ALL MEMBERS OF :\n______ ______________ ______ ________    _________/ _|_____/\______ _ __________\n ____ V _________   // ____/_______  \  _\  ______   _  __/  \  __/_________   /\n |   \_/   |   _/  //  \__   |   _/   \/  \___   \   |___     \ \      /  _/  /\n |    |    |  ____/_     |   |   _     /    _/   /   |   \    /  \_   /  ____/_\n |____|    |_______/_________:___\    /_________/____|_______/_______/________/\n      |____|                      \  /                       \n      :    :                       \/\n\n                                   AnD\n\n             _______ /|   _______/\_______________    _____ \n            /~ ____// | __\___  ~__~/  _____/~   ~\  /~ ¡ ~\.  \n           //  __)_// |/ ~\  /  :| //  __) //   .__)//  |  \\\\n           \\     ~\\ ~   \\/   || \\     ~\\   : \\\\      / \  \n            \  ____/\______/\____|  \  ____/\____ // \. |__/  /\n             \/ .____/\______/\_____|\/ .TeTSUo__\/ / \/ ____/\n              \/                      \/          \/   \/ \n\n\n@ENDNODE\n\n@NODE "FLAME" "Flame Strike"\n           .    .         .         .        .\n   _______/|___/|________/|____ ___/|_______/|\n _/        l_   |    _    l_   |    l_       l_.........................\n/¬     _____j   |    ¬     l   !     l    ____j                        :\nY         |    _|__  .     | \ : /   |  _____j_     ·fLAME^sTRIKE·     :\n|     ____j   /    l :     |  \ /    |        l                        :\n|        |  _/     | :     |   :     |        |ElTECH EHQ·Megastyle WHQ:\n|        |         | !     |   !     |        |                        :\n|       ||        || |     |   |     |       ||                        :\nl________j_________j_|     |___|     |________jHOt WAREZ·CODERS CORNER·.\n :                   l_____j   l_____j [nUMEN] CHAtABlE SYSOP·YouNameIt.\n :  cREW:                    .         .      .     .         .        .\n :Splash/ElTECH^MGS!  ______/|________/|_____/|____/|____ ___/|_______/|\n :UnmaD/eXCALIBUR   _/  _____j_        l_   _ l_    l_   |    l_       l_  \n :    [YOU?]       /_____     l         l   ¬  l     l   !     j    ____j\n :                 Y     \    |    _____j    __j_    |   :  __/   _____j_\n :BIG /X conf with |      \   |      |    .     |    |   .    \         l\n :almost 400 files!|       \  |      |    :     |    |   :     |        |\n :                 |          |      |    !     |    |   !     |        |\n :.[+47·51631702]  |         ||     ||    |     |   ||   |     |       ||\n.:::....... .... ..l__________j______j____|     |____j___|     |________j\n :                                      : l_____j /X 4.9 l_____j :\n .                                      :........................:\n .\n@ENDNODE\n\n@NODE "MEGASTYLE" "About Megastyle"\n\n                                                               @{" Go back.. " Link MAIN}\n\nMegastyle is a new AmiExpress-Support group formed by Lizard of Spaceballs in\nthe middle of may 1995.\n\nOur main goal is to support all the /X-boards out there with the best doors\naround. We try hard to make our products as system-friendly as possible and\nwith unique configuration possibilities.\n\n\nWe want to be the leading /X-development group in the future, and therefore\nneed more skilled coders and ANSI-artist to make our products even better!\n\nIf you''re interesting in teaming up, then take a look at the contact-info.\n\n\n\n   _________ \n    _______ )  ·M·e·g·a·S·t·y·l·e·  ·P·r·o·d·u·c·t·i·o·n·s·\n           )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\nEven if we are a pretty new group we have released a couple of doors allready.\n\nSplash:\nAutoreward v1.2\nGlobalDupe v1.3\nSysDL      v3.0\n\nLizard:\nBulls      v1.0\nNodeStatus v1.2\n\nAll these doors are just GREAT so check''em out! And more releases to come in near \nfuture!\n\n\n   _________ \n    _______ )  ·M·e·g·a·S·t·y·l·e·  ·B·o·a·r·d·s·\n           )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           +47-51-631702 -=- @{"FlameStrike" Link "FLAME"} ·oOo· Sysop : Splash\n           +47-51-417240 -=- @{"Noiseless  " Link "NOISELESS"} ·oOo· Sysop : Lizard (NightBBS)\n           +47-77-748689 -=- @{"Eternity   " Link "ETERNITY"} ·oOo· Sysop : Woober\n           +47-51-575227 -=- @{"Total Panic" Link "TOTALPANIC"} ·oOo· Sysop : Jedi\n@ENDNODE\n@NODE "NOISELESS" "Propaganda : Noiseless BBS!"\n                                                               @{" Go back.. " Link "MEGASTYLE"}\n\n                                        .\n                                           ·\n   _  _  _ _______  _____ __ _____ _____:  :   _____  _____  _____ __ _  _   _\n_   _  _ ______   ||     (__)     |   __|  |  |   __||  ___||  ____ __ _ _  _\n            |  |  ||  |  |  l  `--|  _/_|  |__|  _/_ l  ''--.l  ''--.\n            |  |  ||  |  |  |--,  |  l  |  l  |  l  ||--,  ||--,  |\n            l__|  l|_____l__l__   l__   l__   l__   |l__   ll__   l\n               `--''            `--''  `--''  `--''  `--''   `--''   `--''\n\n                           SysOp : Lizard/Spaceballs\n\n      Phone : +47-51417240, only available between : 23:00PM -> 07:00AM.\n\n@ENDNODE\n@NODE "ETERNITY" "Propaganda : Eternity BBS!"\n                                                               @{" Go back.. " Link "MEGASTYLE"}\n\n                                                               ._____.\n  _____________________________________________________________:__ ._|__\n  \__ _____/___   _   / _____/______  \_   .  _/______ /     _   / |   /\n   /  ___/   /     \_/ ___/    /  _/  _/   |    \    \/¬\     \_/    _/\n  /_________/_______\_________/___\     \__|     \_______\_____\_____|\n                               -cDr\_____\ l______\\n.                                                                       .\n+-÷aMiGA ^ aSCiI ^ mODUlES ^ hACKErS lAnD ^ /X sUPpORT ^ pUBLiC dOMAiN÷-+\n:           [f]EATURING: A1200/020 ^ oNE (n)oDE (14k4 mAXLiTE)          :\n|          [m]ANAGEMENT: [w@@ßE®^tHg^nEo^mGs^bDz]-[SiENCE^tHg]          |\n!   tECHNOLOGY [nHq] · nEO [nHq] · mEGASTYLE [hQ] · bANANa dEZIGn [hQ]  !\n+÷---------------------------------------------------------------------÷+\n:                   [n]UMBER: +47-777-48689 [23 - 07]                   :\n`÷---------------------------------------------------------------------÷''\n\n@ENDNODE\n@NODE "TOTALPANIC" "Propaganda : Total Panic BBS!"\n                                                               @{" Go back.. " Link "MEGASTYLE"}\n\n «*»  Total Panic - 28.8kb v.all - Sysop : Jedi - Number : +47-51-575227  «*»\n\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',19058,3,0,NULL,NULL,'mgs_atrw','scan',1780048595);
INSERT INTO door_catalog VALUES('mgs_awrd','MGS-AWRD.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MGS-AWRD.LHA','autoreward','XIM','autoreward',NULL,'Splash','MGS','_\_/    / _  __  ______ _______/__  ___    / | _ \  /     /  __/__/   /_ _   /   ___   / |__\ \/ /___/_____________/____/____//___/',replace(' ___     _______________________ _ _________\n_\_/    / _  __  ______ _______/__  ___    /\n| _ \  /     /  __/__/   /_ _   /   ___   /\n|__\ \/ /___/_____________/____/____//___/\n    \  /                   .------------.\n     \/ AutoReward 1.3 «-- ÷-  styLE!   ¡\n                 By Splash `------------÷\n Now also possible to reward group      |\n releases. Auto crediting by filename or|\n by conf (or both!) BUGFIX from v 1.2   |\n -[06.06.95]------ ---- ---------·st!·--''\n [World release at FlAMe StRiKe MGS! WHQ]\n','\n',char(10)),'autoreward.guide',replace('@database "AutoReward.Guide"\n@WIDTH 77\n@NODE Main "MAIN" "Welcome to AutoReward Documentation"\n                                                   __.       \n______ ______________ ______ ________    _________/ _|_____/\______ _ __________\n ____ V _________   // ____/_______  \  _\  ______   _  __/  \  __/_________   /\n |   \_/   |   _/  //  \___  |   _/   \/  \___   \   |___     \ \      /  _/  /\n |    |    |  ____/_     |   |   _     /    _/   /   |   \    /  \_   /  ____/_\n |____|    |_______/_________:___\    /_________/____|_______/_______/________/\n      |____|                      \  /                       \n      :   _____                    \/\n           ____\__________\n            ____\_______  )\n                 \/     ) ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n                        ¯¯¯¯¯¯¯¯¯¯¯¯¯¯ ·g·i·v·e·s·  ·y·o·u·\n\n                                                   \n                        .-------------- -       - ---.\n                        |                          ¯7|\n                        |                            :\n                        :  AutoReward 1.3 (06/06-95) .\n                        ·\n                        ·             by\n                                                     ·\n                        ·  Splash/ElTECH & Megastyle :\n                        :·                           |\n                        |l_                          |\n                        `----- -       - ------------''\n                                         \n                         @{"What is AutoReward ?      " LINK "ABOUT"}   \n                         @{"Requirements.             " LINK "REQ"}                \n                         @{"Installation.             " LINK "INSTA"}              \n                         @{"Credits                   " LINK "CREDS"}\n                         @{"Greetings.                " LINK "GREET"}                 \n                         @{"About Megastyle.          " LINK "MEGASTYLE"}\n                         @{"How to contact the Author " LINK "HOWTOCONTACT"}\n\n\n              \n@ENDNODE\n\n\n\n\n\n\n\n\n\n\n@NODE "ABOUT" "What is AutoReward ?"\n\n\nAutoReward is a simple little EXAMINE door that will check which conf a file is\nuploaded to, and you can configure how many *credz an upload in this conf should \nbe rewarded with. If you for example has an /X conf (like me) and would like to \nreward all /X uploads with 2*credz, then all you have to do is install this door,\nconfigure it, and all rewarding will be automatic !\n\n*New in this version is the possibility to rive extra credits for special group\nreleases such as fexs files starting with MGS!-,ELT- or PGS-\n\nYou can have a different amount of credits for each group and also a different\ncomment for each group which will be displayed if a file from that group are \nuploaded. You can also use this door without giving any credist just for using \nthis commenting feature!\n@ENDNODE\n\n@NODE "REQ" "Requirements."\n\n\nA Commodore Amiga computer running on kick 2.0+, /X (preferably 4.x) \n \n\nThis door uses the AEDoor.libary, so you should have this in LIBS:\n(If you haven''t got it then call me or your local /X board to get it...) \n@ENDNODE\n\n\n@NODE "INSTA" "Installation."\n\n\n                             \nJust copy the included files to the correct dirs, that''s it.... \n\nIf you allready have got a file called EXAMINE1.info in syscmd/ you can rename the\none in this archive to EXAMINE2.info or whatever. \n\nThe configuring is no longer done in the autoreward.info, it is now done in\nautoreward.cfg in the same path as this door.\nSe the included .cfg file for more info on this subject\n\n@{b}You only need to include those confs where more than 1*credz should be given!@{ub}\n@ENDNODE\n\n@NODE "HOWTOCONTACT" "How to contact the Author"\n\n \nHow to contact me:\n\n@{"Flame Strike" LINK "FLAME"} :+47 51631702\n\nOr snailmail: Splash/ElTECH & Megastyle\n              Lindeveien 69\n              N-4300 Sandnes\n              Norway\n@ENDNODE\n\n@NODE "CREDS" "Credits."\n\nCode,Idea    - Splash (borrowed one routine from Lizard though :-)\nDoor Design  - Splash\nGuide Design - Splash/Lizard\n\n@ENDNODE\n@NODE "GREET" "Greetings."\n\n   _________ \n    _______ )  ·M·e·g·a·S·t·y·l·e·  ·s·e·n·d·s·  ·g·r·e·e·t·i·n·g·  ·t·o·\n           )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n    Spaceballs, Eltech, Andromeda, CNCD, Parallax, Complex, Virtual dreams,\nStone Arts, Rebels, TRSI, Scoopex, Avalon, Aquarious, Access, Prestige, Skid Row\n\n                   And to all the other /X-coders out there!\n\n\n________ \n ______ ) ·S·p·l·a·s·h·  ·s·e·n·d·s·  ·s·p·e·c·i·a·l·  ·g·r·e·e·t·i·n·g·  ·t·o·\n       )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n       ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n                                  \n\n                         Greetings to all my friends ! \n\nLizard      : LONG live Megastyle!\nJedi        : Welcome to Megastyle! Hope we can use a design by you soon...\nPreacher    : Håper du kan få deg tlf linje snart.\nSkinner     : How about some more activity in ElTECH ? MORE releases! :-)\nMic Flair   : Hope you like this door, let''s have another chat!\nMaze        : Like DC? New dezign+magpart comming up!\nStratos!    : 2 bad you had to leave, you''ll regret it :-)\nShade       : Hope to C your board up''n''running soon.\nScience     : Still haven''t found any bugs ? :-)\nNike        : Nice talkin'' to yah..\nWoober      : Looking forward to C more releases from you..\nTHEGODFATHER: Board up''n''running soon ?\nACID        : Hi!\n\n\n(+ the rest I 4got..)\n\nAND OFCOURSE ALL MEMBERS OF :\n______ ______________ ______ ________    _________/ _|_____/\______ _ __________\n ____ V _________   // ____/_______  \  _\  ______   _  __/  \  __/_________   /\n |   \_/   |   _/  //  \__   |   _/   \/  \___   \   |___     \ \      /  _/  /\n |    |    |  ____/_     |   |   _     /    _/   /   |   \    /  \_   /  ____/_\n |____|    |_______/_________:___\    /_________/____|_______/_______/________/\n      |____|                      \  /                       \n      :    :                       \/\n\n                                   AnD\n\n             _______ /|   _______/\_______________    _____ \n            /~ ____// | __\___  ~__~/  _____/~   ~\  /~ ¡ ~\.  \n           //  __)_// |/ ~\  /  :| //  __) //   .__)//  |  \\\\n           \\     ~\\ ~   \\/   || \\     ~\\   : \\\\      / \  \n            \  ____/\______/\____|  \  ____/\____ // \. |__/  /\n             \/ .____/\______/\_____|\/ .TeTSUo__\/ / \/ ____/\n              \/                      \/          \/   \/ \n\n\n@ENDNODE\n\n@NODE "FLAME" "Flame Strike"\n           .    .         .         .        .\n   _______/|___/|________/|____ ___/|_______/|\n _/        l_   |    _    l_   |    l_       l_.........................\n/¬     _____j   |    ¬     l   !     l    ____j                        :\nY         |    _|__  .     | \ : /   |  _____j_     ·fLAME^sTRIKE·     :\n|     ____j   /    l :     |  \ /    |        l                        :\n|        |  _/     | :     |   :     |        |ElTECH EHQ·Megastyle WHQ:\n|        |         | !     |   !     |        |                        :\n|       ||        || |     |   |     |       ||                        :\nl________j_________j_|     |___|     |________jHOt WAREZ·CODERS CORNER·.\n :                   l_____j   l_____j [nUMEN] CHAtABlE SYSOP·YouNameIt.\n :  cREW:                    .         .      .     .         .        .\n :Splash/ElTECH^MGS!  ______/|________/|_____/|____/|____ ___/|_______/|\n :UnmaD/eXCALIBUR   _/  _____j_        l_   _ l_    l_   |    l_       l_  \n :    [YOU?]       /_____     l         l   ¬  l     l   !     j    ____j\n :                 Y     \    |    _____j    __j_    |   :  __/   _____j_\n :BIG /X conf with |      \   |      |    .     |    |   .    \         l\n :almost 400 files!|       \  |      |    :     |    |   :     |        |\n :                 |          |      |    !     |    |   !     |        |\n :.[+47·51631702]  |         ||     ||    |     |   ||   |     |       ||\n.:::....... .... ..l__________j______j____|     |____j___|     |________j\n :                                      : l_____j /X 4.9 l_____j :\n .                                      :........................:\n .\n@ENDNODE\n\n@NODE "MEGASTYLE" "About Megastyle"\n\n                                                               @{" Go back.. " Link MAIN}\n\nMegastyle is a new AmiExpress-Support group formed by Lizard of Spaceballs in\nthe middle of may 1995.\n\nOur main goal is to support all the /X-boards out there with the best doors\naround. We try hard to make our products as system-friendly as possible and\nwith unique configuration possibilities.\n\n\nWe want to be the leading /X-development group in the future, and therefore\nneed more skilled coders and ANSI-artist to make our products even better!\n\nIf you''re interesting in teaming up, then take a look at the contact-info.\n\n\n\n   _________ \n    _______ )  ·M·e·g·a·S·t·y·l·e·  ·P·r·o·d·u·c·t·i·o·n·s·\n           )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\nEven if we are a pretty new group we have released a couple of doors allready.\n\nSplash:\nAutoreward v1.2\nGlobalDupe v1.3\nSysDL      v3.0\n\nLizard:\nBulls      v1.0\nNodeStatus v1.2\n\nAll these doors are just GREAT so check''em out! And more releases to come in near \nfuture!\n\n\n   _________ \n    _______ )  ·M·e·g·a·S·t·y·l·e·  ·B·o·a·r·d·s·\n           )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           +47-51-631702 -=- @{"FlameStrike" Link "FLAME"} ·oOo· Sysop : Splash\n           +47-51-417240 -=- @{"Noiseless  " Link "NOISELESS"} ·oOo· Sysop : Lizard (NightBBS)\n           +47-77-748689 -=- @{"Eternity   " Link "ETERNITY"} ·oOo· Sysop : Woober\n           +47-51-575227 -=- @{"Total Panic" Link "TOTALPANIC"} ·oOo· Sysop : Jedi\n@ENDNODE\n@NODE "NOISELESS" "Propaganda : Noiseless BBS!"\n                                                               @{" Go back.. " Link "MEGASTYLE"}\n\n                                        .\n                                           ·\n   _  _  _ _______  _____ __ _____ _____:  :   _____  _____  _____ __ _  _   _\n_   _  _ ______   ||     (__)     |   __|  |  |   __||  ___||  ____ __ _ _  _\n            |  |  ||  |  |  l  `--|  _/_|  |__|  _/_ l  ''--.l  ''--.\n            |  |  ||  |  |  |--,  |  l  |  l  |  l  ||--,  ||--,  |\n            l__|  l|_____l__l__   l__   l__   l__   |l__   ll__   l\n               `--''            `--''  `--''  `--''  `--''   `--''   `--''\n\n                           SysOp : Lizard/Spaceballs\n\n      Phone : +47-51417240, only available between : 23:00PM -> 07:00AM.\n\n@ENDNODE\n@NODE "ETERNITY" "Propaganda : Eternity BBS!"\n                                                               @{" Go back.. " Link "MEGASTYLE"}\n\n                                                               ._____.\n  _____________________________________________________________:__ ._|__\n  \__ _____/___   _   / _____/______  \_   .  _/______ /     _   / |   /\n   /  ___/   /     \_/ ___/    /  _/  _/   |    \    \/¬\     \_/    _/\n  /_________/_______\_________/___\     \__|     \_______\_____\_____|\n                               -cDr\_____\ l______\\n.                                                                       .\n+-÷aMiGA ^ aSCiI ^ mODUlES ^ hACKErS lAnD ^ /X sUPpORT ^ pUBLiC dOMAiN÷-+\n:           [f]EATURING: A1200/020 ^ oNE (n)oDE (14k4 mAXLiTE)          :\n|          [m]ANAGEMENT: [w@@ßE®^tHg^nEo^mGs^bDz]-[SiENCE^tHg]          |\n!   tECHNOLOGY [nHq] · nEO [nHq] · mEGASTYLE [hQ] · bANANa dEZIGn [hQ]  !\n+÷---------------------------------------------------------------------÷+\n:                   [n]UMBER: +47-777-48689 [23 - 07]                   :\n`÷---------------------------------------------------------------------÷''\n\n@ENDNODE\n@NODE "TOTALPANIC" "Propaganda : Total Panic BBS!"\n                                                               @{" Go back.. " Link "MEGASTYLE"}\n\n «*»  Total Panic - 28.8kb v.all - Sysop : Jedi - Number : +47-51-575227  «*»\n\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',19119,3,0,NULL,NULL,'mgs_awrd','scan',1780048595);
INSERT INTO door_catalog VALUES('mgs_bull','MGS-BULL.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MGS-BULL.LHA','bulls','XIM','bulls',NULL,NULL,'MGS','_\_/     / _ __ _________ _____/_____ ____ |  _ \  /    / ___/----/   /_ _   /  ______ |___\ \/ /__________________/____/____//____',replace(' ___      ______________________  _ ______ _\n_\_/     / _ __ _________ _____/_____ ____ \n|  _ \  /    / ___/----/   /_ _   /  ______\n|___\ \/ /__________________/____/____//____\n|    \  /                       .----------.\n|     \/   /X - BuLLs v1.0  «-- ÷-  styLE! |\n|                               `----------÷\n| New Bulletin shower for the AmiExpress! |\n| Nice''n''fast output, great configuration |\n| and highly optimized ASM-code!          |\n|                                  Lizard |\n`-----------------------------------·st!·-''\n','\n',char(10)),'Bulls.guide',replace('@database "GlobalDupe.Guide"\n@WIDTH 77\n@NODE Main "MAIN" "Welcome to Bulls Documentation"\n\n .--------------------  ---(c)-[ mEGAStYLE! pRODUCtiON ''95\n |    ____     _______________________________  _ _____________ _\n ! ___\ _/    / _  ___  __________  _________/_ __   ____       /\n . |    _ \  /      /  ___/_____/    /__ _      /    _//_      / -----.\n ¦ |st!  \ \/ /    /    /      /       /       /     _____    /   -- -÷ -»\n | |______\  /_______________________________________//______/ -------''\n |         \/           \n |\n-÷- -» _____________ ______          _____     _ ______      _ _______ ____\n |  ___\   ________/_     /_       _/    /___         /    _ __  _________/\n |  |__________     /    __/______/     /    \ /     /_______/  ___/_______\n |  |      |       /    /        /     /      \     /       /    /        /\n |  |______________________________________    \_________________________/\n .                              _  _ _____¬_____/\n |\n |\n `---------------------------------------------------.\n .---------------------------------------------------''\n |\n |                       Bulls v1.0 (10/05-95)\n |    \n |\n |                       A MEGASTYLE production 19(C)95.\n |                       Code by Lizard - Design by Stratos!\n |                                        \n |\n |                       @{"What is Bulls ?           " LINK "ABOUT"}   \n |                       @{"Requirements.             " LINK "REQ"}                \n |                       @{"Installation.             " LINK "INSTA"}              \n |                       @{"Credits                   " LINK "CREDS"}\n |                       @{"Greetings.                " LINK "GREET"}                 \n |                       @{"About Megastyle.          " LINK "MEGASTYLE"}\n `---------.             @{"How to contact the Author " LINK "HOWTOCONTACT"}\n   .-------''                            \n   `----------------------------------------------------------------.\n              .-----------------------------------------------------''\n@ENDNODE\n\n@NODE "ABOUT" "What is Bulls ?"\nWhen I first started to collect doors to my own /X-board, I found out that most\nof the Bulletin-viewers available were quite lousy and hard to configurate.\n\nThis gave me the idea to code my own door which in my opinion has become one of\nthe best Bulletin-showers around compared to other Bulletin-Doors.\n\nFirst of all, I''ve tried to make this door as SysOp-friendly as possible.\nHowever, my /X-interface for setting up this door has not yet been implanted,\nbut will be released in a soon coming update to this door.\n\nAlso better design and optimized code will be improved as I continue to work on\nthis AmiExpress-product.\n@ENDNODE\n\n@NODE "REQ" "Requirements."\n\n\nAny Commodore Amiga computer will do as long as it is running on kick 2.0+++.\nYou may also use any AmiExpress version... (But preferably 4.x+) \n \n\nThis door uses the AEDoor.libary, so you should have this library in LIBS:\n(If you haven''t got it then call me or your local /X board to get it...) \n@ENDNODE\n\n\n@NODE "INSTA" "Installation."\n\nJust copy the included files to the correct dirs, that''s it.... \n\nThe configuring is done in the Bulls.info icon.\n\nFirst of all you''ll have to configurate where to locate your BullX.TXT-files.\nThis is done by changing the PATH followed with a "/" to the "BULLETINS_PATH="\ntooltype.\n\nThen you''ll have to state how many bulletinlines which should be included to\nthe bulletinlist. Do not write more than the total amount of Bulletin-lines.\n\nYou use the tooltype BULLETIN.x=<name> to declare the bulletin-lines, where\nx is the line-number and <name> is the name of the Bulletin-Door to be showned.\n\n\nHere is an example of how to set up this BULLS.INFO-icon :\n\n--------------------------------- cut start ---------------------------------\n\nBULLETINS_PATH=BBS:BULLETINS/\nANTBULLETINS=9\nBULLETIN.1=AMFETAMIN\nBULLETIN.2=Quick-New\nBULLETIN.3=Best Uploaders\nBULLETIN.4=Best Downloaders\nBULLETIN.5=ChaT-o-MeteR ScoRes\nBULLETIN.6=RoO-tOp-uPLoADeRs\nBULLETIN.7=tOP CPS-rATEs\nBULLETIN.8=tOP 3o cALLER''s\nBULLETIN.9=tOP 3o mSG wRITER''S\n\n---------------------------------  cut end  ---------------------------------\n\nThen you''ll have to make small bulletin-textfiles. These can include standard\nMCI-functions (~) aswell as ordinary text and ANSI-codes.\n\nEach Bulletin-file must have a filename like this "BULLx.TXT", where x is the\nmatching bulletinline number. And the files must exist in the BULLETINS_PATH-\ndrawer. Otherwise none of the bulletins will be showned.\n\n\n\nHere is an example of how to set up such a "BULLx.TXT"-textfile :\n\n--------------------------------- cut start ---------------------------------\n\n~SS_BBS:Screens/Amfetamin.txt \n\n---------------------------------  cut end  ---------------------------------\n\nOr you can use : ~CC_BestUl to launch commands etc...\n@ENDNODE\n\n@NODE "HOWTOCONTACT" "How to contact the Author"\n\n \nHow to contact me:\n\n@{"NOISELESS" LINK "NOISELESS"} :+47-51417240 - After 23:00PM to 09:00AM\n\nOr snailmail: Lizard / Spaceballs + Megastyle\n              Boveien 81\n              N-4070 Randaberg\n              Norway\n\n              Voice between 09:00AM to 23:00PM, ask for Magnar.\n@ENDNODE\n\n@NODE "CREDS" "Credits."\n\nCode,Idea    - Lizard  oF Megastyle+Spaceballs\n\nDoor Design  - StratoS oF Megastyle\n               Lizard  oF Megastyle+Spaceballs\n\nGuide Design - Splash  oF Megastyle+Eltech\n               Lizard  oF Megastyle+Spaceballs\n\n@ENDNODE\n\n@NODE "GREET" "Greetings."\n                                  \nGreetings to all my friends ! \n\n\nSpecial greetings to all /X coders out there  -  Especially those on IRC!\n\n\nAND OFCOURSE ALL MEMBERS OF :\n\n___ ___/\_____/\_ ___/\_____/\_____/\_____/\_ ___/\___. _____. ___ ___/\\n\__Y ___ \___,  \Y    /_  ___ \  ____/_____.\Y    /_  |_\__  |_\__Y ___ \\n /___  .\/  ____/  T .\.  .\ \/  __/_/   /  /  T .\.  | .\.  | .\___  .\/\n/.   \  \\ |  /.      \\   \\/\     .\  \__ \     \\     \\     \\  \  \\\n\\ ______/_l  \\ __l___/______/______/______/__l___/______/______/______/\n \/     \/     \/     \/     \/     \/     \/     \/     \/     \/  -Wß®-\n\n\n\n\nSpecial greetings to:\nSplash and stRAtOS! -> Let''s make Megastyle the biggest /X group EVER!\n\nSome messages:\nSplash   - When will your newest version of the SysDl be finished?\nstRAtOS! - Make Asc²!!! And try to improve the design on this door aswell. :)\nWoober   - Have you managed to decode your HD now? ;)\n@ENDNODE\n\n@NODE "NOISELESS" "NOISELESS"\n                                        .\n                                           ·\n   _  _  _ _______  _____ __ _____ _____:  :   _____  _____  _____ __ _  _   _\n_   _  _ ______   ||     (__)     |   __|  |  |   __||  ___||  ____ __ _ _  _\n            |  |  ||  |  |  l  `--|  _/_|  |__|  _/_ l  ''--.l  ''--.\n            |  |  ||  |  |  |--,  |  l  |  l  |  l  ||--,  ||--,  |\n            l__|  l|_____l__l__   l__   l__   l__   |l__   ll__   l\n               `--''            `--''  `--''  `--''  `--''   `--''   `--''\n\n       USRobotic v.All - 28.8kb - Sysop : Lizard of Spaceballs+Megastyle\n\n                  Only available between 23:00PM to 09:00AM.\n\n                              +47 - 51 - 41 72 40\n@ENDNODE\n\n@NODE "MEGASTYLE" "About Megastyle"\n\nMegastyle is a new /X developer group consisting of /X coders and dezigners.\nWe need more members, so if you want to join or have got anything to \ncontribute with (Ideas, hints, dezigns, bugreports aso.) then contact me.\n\n\n\nCurrent memberstatus :\n\n.------------.------------ --- -- - -  -   -    -\n¦   HANDLE   |   FUNCTION \n+------------+-------------- --- -- - -  -   -    -\n|   LIZARD   | Organizer, Coder, Designer, Asc².\n!   SPLASH   : Coder, Designer, Asc².\n·   WOOBER   . Asc².\n:  STRATOS   : Designer, Asc².\n`------------^---------- --- -- - -  -   -    -  \n@ENDNODE\n','\n',char(10)),NULL,'auto-added',19298,6,0,NULL,NULL,'mgs_bull','scan',1780048595);
INSERT INTO door_catalog VALUES('mgs_c11','MGS-C11.LZX','~/Code/amiexpress_doors/Archives/AmiExpress/MGS-C11.LZX',NULL,'XIM','chatter',NULL,NULL,'MGS',NULL,NULL,NULL,NULL,NULL,'auto-added',11547,0,0,NULL,NULL,'mgs_c11','scan',1780048595);
INSERT INTO door_catalog VALUES('mgs_chat','MGS-CHAT.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MGS-CHAT.LHA','chatter','XIM','chatter',NULL,'Splash','MGS','_\_/    / _  __  ______ _______/__  ___    / | _ \  /     /  __/__/   /_ _   /   ___   / |__\ \/ /___/_____________/____/____//___/',replace(' ___     _______________________ _ _________\n_\_/    / _  __  ______ _______/__  ___    /\n| _ \  /     /  __/__/   /_ _   /   ___   /\n|__\ \/ /___/_____________/____/____//___/\n    \  /                   .------------.\n     \/ Mega-Chatter 1.1 «-÷-  styLE!   ¡\n                By Splash  `------------÷\n   Nice little chatter door that will   |\n display random txt files when entering |\n chat.   Can use different languages!   |\n -[05.07.95]------ ---- ---------·st!·--''\n [World release at FlAMe StRiKe MGS! WHQ]\n','\n',char(10)),'MegaChatter.Guide',replace('@database "Mega-Chatter.Guide"\n@WIDTH 77\n@NODE Main "MAIN" "Welcome to Mega-Chatter Documentation"\n\n .--------------------  ---(c)-[ mEGAStYLE! pRODUCtiON ''95\n |    ____     _______________________________  _ _____________ _\n ! ___\ _/    / _  ___  __________  _________/_ __   ____       /\n . |    _ \  /      /  ___/_____/    /__ _      /    _//_      / -----.\n ¦ |st!  \ \/ /    /    /      /       /       /     _____    /   -- -÷ -»\n | |______\  /_______________________________________//______/ -------''\n |         \/           \n |\n-÷- -» _____________ ______          _____     _ ______      _ _______ ____\n |  ___\   ________/_     /_       _/    /___         /    _ __  _________/\n |  |__________     /    __/______/     /    \ /     /_______/  ___/_______\n |  |      |       /    /        /     /      \     /       /    /        /\n |  |______________________________________    \_________________________/\n .                              _  _ _____¬_____/\n |\n |\n `--------------------------------------------------- ------------ -[   -»\n\n\n\n\n\n\n                           Mega-Chatter 1.1 (05-07-95)\n     \n                              By Splash/Megastyle\n                                         \n                          @{"What is Mega-Chatter ?    " LINK "ABOUT"}   \n                          @{"What is new since v1.0 ?  " LINK "NEW"}\n                          @{"Requirements.             " LINK "REQ"}                \n                          @{"Installation.             " LINK "INSTA"}              \n                          @{"How to operate.           " LINK "OPERATE"}\n                          @{"Credits                   " LINK "CREDS"}\n                          @{"Greetings.                " LINK "GREET"}                 \n                          @{"About Megastyle.          " LINK "MEGASTYLE"}\n                          @{"How to contact the Author " LINK "HOWTOCONTACT"}\n              \n@ENDNODE\n\n\n\n\n\n\n\n\n\n\n@NODE "ABOUT" "What is Mega-Chatter ?"\n\n                                                               @{" Go back.. " Link MAIN}\nMega-Chatter is a nice little tool I made just for fun. I wanted to have a \nbetter way to start my chats (when you are a sysop you actually do alot of \nchatting... I do anyway..)  \n\nThis door is actually a simple writer, that will write som random txt to the \nuser when entering chat. You as sysop have the opportunity to choose which \ntype of txt you want to display. You can disply txt in different languages, \nin different moods or whatever. YOU choose.. The txt will be written just as \nif YOU were the one actually writing it. You also have the ability to include\nuser''s handle in the txt... The users will be impressed with you writing \nskills! :-) \n@ENDNODE\n\n@NODE "REQ" "Requirements."\n\n                                                               @{" Go back.. " Link MAIN}\nA Commodore Amiga computer (Pese suxx :-) running on kick 2.0+, /X \n(I guess any version will do...) \n\nThis door uses the AEDoor.libary, so you should have this in LIBS:\n(If you haven''t got it then call me or your local /X board to get it...) \n@ENDNODE\n\n\n@NODE "INSTA" "Installation."\n\n                                                               @{" Go back.. " Link MAIN}\n                             \n1. Copy the included files to the correct dirs.\n\n2. Edit the nodex/startchat.txt and include:''~CC_CHATTER''\n\n3. If you want, Mega-Chatter can display a txt file before starting the writer,\n   if you want this then just call the file chat.txt and put it in ''S:''. \n\n4. This door does not use a specific pen coulour, so the pen/paper colour can be set\n   f.exs in chat.txt\n\n5. Edit and install the @{"Textfiles" LINK "TEXTFILES"}\n\n6. @{"How to operate" LINK "OPERATE"}\n\nThen start chatting!!! \n@ENDNODE\n\n@NODE "HOWTOCONTACT" "How to contact the Author"\n\n                                                               @{" Go back.. " Link MAIN}\nHow to contact me:\n\n@{"Flame Strike" LINK "FLAME"} :+47 51631702\n\nOr snailmail: Splash/ElTECH & Megastyle\n              Lindeveien 69\n              N-4300 Sandnes\n              Norway\n@ENDNODE\n\n@NODE "CREDS" "Credits."\n\n                                                               @{" Go back.. " Link MAIN}\nCode,Idea    - Splash/ElTECH & Megastyle\nDoor Design  - Splash/ElTECH & Megastyle (Is there any ?)\nGuide Design - Splash/ElTECH & Megastyle\n\n@ENDNODE\n@NODE "GREET" "Greetings."\n\n                                                               @{" Go back.. " Link MAIN}\n                                  \n\n                         Greetings to all my friends ! \n\n                      Special greetings to all /X coders \n\nAND OFCOURSE ALL MEMBERS OF :\n______ ______________ ______ ________    _________/ _|_____/\______ _ __________\n ____ V _________   // ____/_______  \  _\  ______   _  __/  \  __/_________   /\n |   \_/   |   _/  //  \__   |   _/   \/  \___   \   |___     \ \      /  _/  /\n |    |    |  ____/_     |   |   _     /    _/   /   |   \    /  \_   /  ____/_\n |____|    |_______/_________:___\    /_________/____|_______/_______/________/\n      |____|                      \  /                       \n      :    :                       \/\n\n                                   AnD\n\n             _______ /|   _______/\_______________    _____ \n            /~ ____// | __\___  ~__~/  _____/~   ~\  /~ ¡ ~\.  \n           //  __)_// |/ ~\  /  :| //  __) //   .__)//  |  \\\\n           \\     ~\\ ~   \\/   || \\     ~\\   : \\\\      / \  \n            \  ____/\______/\____|  \  ____/\____ // \. |__/  /\n             \/ .____/\______/\_____|\/ .TeTSUo__\/ / \/ ____/\n              \/                      \/          \/   \/ \n\n\n\nPersonal greetings:\n~~~~~~~~~~~~~~~~~~~\nLizard/MGS!      - We ARE growing BIG now!\nWoober/MGS!      - Hi!\nJedi/MGS!        - Get those new nodes SOON!!! :-)\nNightProwler/HLM - Nice talkin'' to yah! Hope you like this door!\nMiC flAiR/ElT    - We need more releases from ElT.....\nLithium/ElT      - Hope we get the chance to talk more..\nMagz/GrT         - Nice colly... greet me in the next one!\n\nSo I 4got YOU? Oki... go ahead shoot me.... I''m guilty...\n\n@ENDNODE\n\n@NODE "FLAME" "Flame Strike"\n                                                               @{" Go back.. " Link MAIN}\n           .    .         .         .        .\n   _______/|___/|________/|____ ___/|_______/|\n _/        l_   |    _    l_   |    l_       l_.........................\n/¬     _____j   |    ¬     l   !     l    ____j                        :\nY         |    _|__  .     | \ : /   |  _____j_     ·fLAME^sTRIKE·     :\n|     ____j   /    l :     |  \ /    |        l                        :\n|        |  _/     | :     |   :     |        |ElTECH EHQ·Megastyle WHQ:\n|        |         | !     |   !     |        |                        :\n|       ||        || |     |   |     |       ||                        :\nl________j_________j_|     |___|     |________jHOt WAREZ·CODERS CORNER·.\n :                   l_____j   l_____j [nUMEN] CHAtABlE SYSOP·YouNameIt.\n :  cREW:                    .         .      .     .         .        .\n :Splash/ElTECH^MGS!  ______/|________/|_____/|____/|____ ___/|_______/|\n :UnmaD/eXCALIBUR   _/  _____j_        l_   _ l_    l_   |    l_       l_  \n :MiC FlAiR/ElTECH /_____     l         l   ¬  l     l   !     j    ____j\n :    [YOU?]       Y     \    |    _____j    __j_    |   :  __/   _____j_\n :                 |      \   |      |    .     |    |   .    \         l\n :BIG /X conf with |       \  |      |    :     |    |   :     |        |\n :  500++ files!   |          |      |    !     |    |   !     |        |\n :.[+47·51631702]  |         ||     ||    |     |   ||   |     |       ||\n.:::....... .... ..l__________j______j____|     |____j___|     |________j\n :                                      : l_____j /X 4.9 l_____j :\n .                                      :........................:\n .\n\n@ENDNODE\n\n@NODE "MEGASTYLE" "About Megastyle"\n\n                                                               @{" Go back.. " Link MAIN}\n\nMegastyle is a new AmiExpress-Support group formed by Lizard of Spaceballs in\nthe middle of may 1995.\n\nOur main goal is to support all the /X-boards out there with the best doors\naround. We try hard to make our products as system-friendly as possible and\nwith unique configuration possibilities.\n\n\nWe want to be the leading /X-development group in the future, and therefore\nneed more skilled coders and ANSI-artist to make our products even better!\n\nIf you''re interesting in teaming up, then take a look at the contact-info.\n\n\n\n   _________ \n    _______ )  ·M·e·g·a·S·t·y·l·e·  ·P·r·o·d·u·c·t·i·o·n·s·\n           )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\nEven if we are a pretty new group we have released a couple of doors allready.\n\nSplash:\nSysDL        v3.2\nGlobalDupe   v1.4\nAutoreward   v1.3\nMega-Chatter v1.0\n\nLizard:\nBulls        v1.0\nNodeStatus   v1.2\n\nAll these doors are just GREAT so check''em out! And more releases to come in near \nfuture!\n\n\n   _________ \n    _______ )  ·M·e·g·a·S·t·y·l·e·  ·B·o·a·r·d·s·\n           )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           +47-51-631702 -=- @{"FlameStrike" Link "FLAME"} ·oOo· Sysop : Splash\n           +47-51-417240 -=- @{"Noiseless  " Link "NOISELESS"} ·oOo· Sysop : Lizard (NightBBS)\n           +47-77-748689 -=- @{"Eternity   " Link "ETERNITY"} ·oOo· Sysop : Woober\n           +47-51-575227 -=- @{"Total Panic" Link "TOTALPANIC"} ·oOo· Sysop : Jedi\n\n@ENDNODE\n@NODE "NOISELESS" "Propaganda : Noiseless BBS!"\n                                                               @{" Go back.. " Link "MEGASTYLE"}\n\n                                        .\n                                           ·\n   _  _  _ _______  _____ __ _____ _____:  :   _____  _____  _____ __ _  _   _\n_   _  _ ______   ||     (__)     |   __|  |  |   __||  ___||  ____ __ _ _  _\n            |  |  ||  |  |  l  `--|  _/_|  |__|  _/_ l  ''--.l  ''--.\n            |  |  ||  |  |  |--,  |  l  |  l  |  l  ||--,  ||--,  |\n            l__|  l|_____l__l__   l__   l__   l__   |l__   ll__   l\n               `--''            `--''  `--''  `--''  `--''   `--''   `--''\n\n                           SysOp : Lizard/Spaceballs\n\n      Phone : +47-51417240, only available between : 23:00PM -> 07:00AM.\n\n@ENDNODE\n@NODE "ETERNITY" "Propaganda : Eternity BBS!"\n                                                               @{" Go back.. " Link "MEGASTYLE"}\n\n                                                               ._____.\n  _____________________________________________________________:__ ._|__\n  \__ _____/___   _   / _____/______  \_   .  _/______ /     _   / |   /\n   /  ___/   /     \_/ ___/    /  _/  _/   |    \    \/¬\     \_/    _/\n  /_________/_______\_________/___\     \__|     \_______\_____\_____|\n                               -cDr\_____\ l______\\n.                                                                       .\n+-÷aMiGA ^ aSCiI ^ mODUlES ^ hACKErS lAnD ^ /X sUPpORT ^ pUBLiC dOMAiN÷-+\n:           [f]EATURING: A1200/020 ^ oNE (n)oDE (14k4 mAXLiTE)          :\n|          [m]ANAGEMENT: [w@@ßE®^tHg^nEo^mGs^bDz]-[SiENCE^tHg]          |\n!   tECHNOLOGY [nHq] · nEO [nHq] · mEGASTYLE [hQ] · bANANa dEZIGn [hQ]  !\n+÷---------------------------------------------------------------------÷+\n:                   [n]UMBER: +47-777-48689 [23 - 07]                   :\n`÷---------------------------------------------------------------------÷''\n\n@ENDNODE\n@NODE "TOTALPANIC" "Propaganda : Total Panic BBS!"\n                                                               @{" Go back.. " Link "MEGASTYLE"}\n\n «*»  Total Panic - 28.8kb v.all - Sysop : Jedi - Number : +47-51-575227  «*»\n\n@ENDNODE\n\n@NODE "TEXTFILES" "How to use the text files."\n\n                                                               @{" Go back.. " Link MAIN}\nOne of the great features of this dooris that you can have up to 10 different \ntextfile types. You can for example have one area in your own language, one in \nEnglish end perhaps a area containing jokes, one angry area aso.\n\nTo use this feature, first of all you must decide how many areas you want.\nThen make one dir for each area (in the same directory as the door was started \nfrom) Name these dirs with a number, from 1-x (where x is the number of areas \nyou want) Now you have to put some files in these areas. You can have as many \nfiles as you want. Also name these files with a number from 1-x.\nThere is no need to configure how many areas you have got or how many txt files \nyou hvae got in each area, my clever door does it all by it self.\n\nOnly the first line of the files will be written. When writing the files you can\nuse ''%U'' (case-sensitive) to include user''s name) Other functions might be \nincluded later, so if you have got any ideas of what I might include then tell \nme!\n\nNow it is time to use this great door, but first have a look here ->@{"OPERATION" LINK "OPERATE"} \n@ENDNODE\n\n@NODE "OPERATE" "How to operate Mega-Chatter"\n\n                                                               @{" Go back.. " Link MAIN}\nWhen started, Mega-Chatter will wait for you to press a key. You have several \noptions. Hitting SPACE will display a random file from ALL the areas you have \ngot. You can also select which area to pick the file from by hitting a numeric \nkey. If you hit f.exs. ''1'' It will pick a random file in area 1. Hitting ''0'' \nwill pick a file in area 10. If you don''t want any txt written, just press any\nother button, and it will work just like ordinary chatting....\n\n@ENDNODE\n@NODE "NEW" "What is new in this version ?"\n\n*I fixed a bug in connection with the displaying of ''chat.txt''. This file now has \nto be put in ''S:'' if you want to use this feature.\n\nNot much bug-fixing, but it was an important fix....\n\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',21686,4,0,NULL,NULL,'mgs_chat','scan',1780048595);
INSERT INTO door_catalog VALUES('mgs_clas','MGS-CLAS.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MGS-CLAS.LHA','curselast','XIM','6OC-!SGM.EXE',NULL,NULL,'MGS','____\        /___\   ____  /____/ ___/______ _     \l      _  \_______ ____\/       __l_________  __l__       l ___',replace('    __________   ___________     _____\n____\        /___\   ____  /____/ ___/______\n               _     \l      _  \_______\n____\/       __l_________  __l__       l ___\ng®m /________)   e^D \_____)   (_________)\n          «« m e g a s t y l e  »»\n              ...presents...\n \n   CURSELAST Vo.6 - 999 LASTCALLERS\n         WITH CURSORSCROLLING!\n                                    17-o7-96\n','\n',char(10)),'Megastyle.GUIDE',replace('@database "mEGAZTYLE.guide"\n@node MAIN\n@title "                                              »«  m e g a s t y l e  »«  r u l e s  »«"\n@{b}\n                              @{u}m e g a s t y l e@{uu}\n\n                 ________   _________   _________     ______.\n           ______\\      /___\\  ___  /___\\  ___  /_____\\____ l____\n     ______\\              _     l/    _    \\l     _     __/     /_______\n.___(       \\____\\/     __l__  _______l_______  __l__   \\l_____/        )___.\n|                /______)   (_____/        \\____)   (____\\                  |\n|                                                                           |\n| g®m      _____      ___.           .______   ___.       _________     e^D |\n|___  ____/ ___/______\\  l___________|     /___\\ _l_______\\  ___  /____  ___|\n   (__\\   \\______   _    __/     _   l       _   \\      _     l/      /__)\n       \\__      l __l__  l     __l_______  __l_        _l_  _________/\n         (________)   (________)     \\_____)  (________) (_____/ @{ub}\n\n\n\n@{fg shine}                  p r e s e n t s   a   n e w   d o o r :@{fg text}\n\n\n                       @{b}    @{bg shine}@{u}c u r s e l a s t   o . 6@{bg back}@{ub}@{uu}\n\n\n\n\n              @{"           d o c u m e n t a t i o n           " link index}\n\n\n\n\n@endnode\n\n@node index\n@title "                                             »» i n d e x ««"\n\n\n    @{u}                                                          @{uu}\n\n\n@{b}                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n         ____        __________          ____.   ___________   ½½½½½  ½½½½½\n________(___/________\\ __     /__________\\___l___\\  ____   /__    `½½½½''\n                   _   l/       _      _____/  _      l/      ½½½½½½  ½½½½½½\n_____            __l___/      __l__    l     __l__  __________½½½½½½  ½½½½½½\n    (____________)    /_______)   (__________)   (_____/      ½½½½½½  ½½½½½½\n                                                              ½½½½½½  ½½½½½½\n                                                              ½½½½½½  ½½½½½½\n   @{fg shine} @{"            introduction             "  link introduction      }    @{fg text}                ½½½½½½  ½½½½½½\n@{fg shine}    @{"            installation             "  link installation      }          @{fg text}          ½½½½½½  ½½½½½½\n@{fg shine}    @{"              how 2 use              "  link how 2 use         }\n    @{"              copyright              "  link copyright         }\n    @{"          changes ÷ history          " link changes ÷ history  } @{ub} @{fg text}\n\n\n    @{u}                                                          @{uu}\n\n\n@endnode\n\n\n\n\n\n\n\n\n@node introduction\n                                                                 .\n\n                                                                 :\n                                                                 :\n             __________________.______.      ________            :\n          ._(___)_.   ___     _|      l_____\\\\_     /____________:_ _\n          |       |----/      \\        /     \\   __/\\      __    :\n          l_______|   /_______/        |-----/_______\\____       :\n                              l________|(rLf)            /-------:-\n                                                                 :\n                                                                 :\n                                                                 :\n                                                                 .\n\n\n     Curselast is a door for /X and S!X that displays up to @{fg shine}999@{fg text}(!!!!)\n            You can actually scroll up/down with your cursors!!\n    @{fg shine}last callers@{fg text} with a gr8 design! Just @{"install" link installation} it and check it out!!!\n        Curselast was coded in AmigaE and is fairly fast and small.\n\n                            -magz of megastyle-\n\n@endnode\n\n\n\n\n\n\n@node installation\n\n .\n                                                                              .\n :\n :                                                                            :\n : __        _____ .___.   ______ __.              _________. ____________    :\n_:(__)_______\\_ _/_|_  l___\\__  // _l______.  _____\\__  //  l____)_  _   /____:_\n :    | __    /_  _ /   /     _ // \\     /_l__\\__     _ //   /    |_    / ___ :\n_:____|--/   /-/  //    |--/____/----/__/ \\     /--/____/    |____|/---/\\--/  :\n :      /___/ /___/_____|(rLf)          \\---/__/       l_____|            /___:_\n :                                                                            :\n :                        i n s t a l l a t i o n                             :\n .                                                                            :\n                                                                              .\n\nCopy the files in DOORS/ and COMMANDS/ to your directories named DOORS:\nand BBS:COMMANDS/ Then put in let''s say your LOGON.TXT and/or one of your\nBULL<xx>.TXT files:\n\n-----[ cut ]------\n\n~\n~CC_curselast|\n\n-----[ cut ]------\n\n\nCurselast requires to be updated in the\nlogoffbatch of your bbs. therefore add to your logoffbatch:\n\n-----[ cut ]------\n\nDOORS:-mgs!-curselast/curseupdate <node>\n\n-----[ cut ]------\n\nWhere <node> stands for the node the logoffbatch will\nbe executed by on logoff.\n\n\nEdit the icon "DOORS:-mgs!-curselast/curseupdate.info" to suit your needs:\n                  .\nSYSOP=<sysop>     | Where <sysop> can be 1 (display sysop/local logins) or 0 (ignore sysop/local logins)\nLINES=<lines>     | Where <lines> can be 16-999 which is the number of last callers you want to display\n                  | (16 = No scrolling)\n                  ''\n\nThat should be it :)\n\nFor S!X users.. just make a new line in your bbs.cmd file.. you know how ;)\n\n\n@endnode\n\n\n\n\n\n@node how 2 use\n@title "                                              )>» h o w  2  u s e «<("\n\n                                      ½½½½½½½½½½½½½½½½½½½½½½½.\n                                     ½½½½½½½½         ½½½½½½½½\n      ____.            _________         _______      ½½½½½½½½\n   ___\\ __l____________\\       /_________\\     /______½½½½½½½½\n   \\    \\___        _             _      /\\           ½½½½½½½½\n    \\______/      __l__    "    __l__           ___   ½½½½½½½½\n          /_______)   (_________)   (___________) /_  ½½½½½½½½\n                                                   |  ½½½½½½½½\n                ½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½''\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½      ._____      _____    |   _|________\n                ½½½½½½½½______|    /_____/ ___/____|___\\  ____  /___\n    