INSERT INTO door_catalog VALUES('mgs_magz','MGS-MAGZ.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MGS-MAGZ.LHA','mgzlistman','XIM','mgzlistman',NULL,NULL,'MGS','____\        /___\   ____  /____/ ___/______ _     \l      _  \_______ ____\/       __l_________  __l__       l ___',replace('    __________   ___________     _____\n____\        /___\   ____  /____/ ___/______\n               _     \l      _  \_______\n____\/       __l_________  __l__       l ___\ng®m /________)   e^D \_____)   (_________)\n \n          »» magzlistmanager 1.o ««\n \nTired of DELETING and MOVING files manually?\n Then this is the perfect /X door for you!\nNow you can do all that stuff from AQUASCAN!\n','\n',char(10)),'ListManDoc.GUIDE',replace('@database "mEGAZTYLE.guide"\n@node MAIN\n@title "                                              »«  m e g a s t y l e  »«  r u l e s  »«"\n@{b}\n                              @{u}m e g a s t y l e@{uu}\n\n                 ________   _________   _________     ______.\n           ______\      /___\  ___  /___\  ___  /_____\____ l____\n     ______\              _     l/    _    \l     _     __/     /_______\n.___(       \____\/     __l__  _______l_______  __l__   \l_____/        )___.\n|                /______)   (_____/        \____)   (____\                  |\n|                                                                           |\n| g®m      _____      ___.           .______   ___.       _________     e^D |\n|___  ____/ ___/______\  l___________|     /___\ _l_______\  ___  /____  ___|\n   (__\   \______   _    __/     _   l       _   \      _     l/      /__)\n       \__      l __l__  l     __l_______  __l_        _l_  _________/\n         (________)   (________)     \_____)  (________) (_____/ @{ub}\n\n\n\n@{fg shine}                  p r e s e n t s   a   n e w   d o o r :@{fg text}\n\n\n @{b}                     @{bg shine}@{u} m a g z l ! s t m a n   1 . o @{bg back}@{uu}@{ub}\n\n\n\n              @{"           d o c u m e n t a t i o n           " link index}\n\n\n\n\n@endnode\n\n@node index\n@title "                                             »» i n d e x ««"\n\n\n    @{u}                                                          @{uu}\n\n\n@{b}                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n         ____        __________          ____.   ___________   ½½½½½  ½½½½½\n________(___/________\ __     /__________\___l___\  ____   /__    `½½½½''\n                   _   l/       _      _____/  _      l/      ½½½½½½  ½½½½½½\n_____            __l___/      __l__    l     __l__  __________½½½½½½  ½½½½½½\n    (____________)    /_______)   (__________)   (_____/      ½½½½½½  ½½½½½½\n                                                              ½½½½½½  ½½½½½½\n                                                              ½½½½½½  ½½½½½½\n   @{fg shine} @{"            introduction             "  link introduction      }    @{fg text}                ½½½½½½  ½½½½½½\n@{fg shine}    @{"            installation             "  link installation      }          @{fg text}          ½½½½½½  ½½½½½½\n@{fg shine}    @{"              how 2 use              "  link how 2 use         }\n    @{"              copyright              "  link copyright         }\n    @{"          changes ÷ history          " link changes ÷ history  } @{ub} @{fg text}\n\n\n    @{u}                                                          @{uu}\n\n\n@endnode\n\n\n\n\n\n\n\n\n@node introduction\n                                                                 .\n\n                                                                 :\n                                                                 :\n             __________________.______.      ________            :\n          ._(___)_.   ___     _|      l_____\\_     /____________:_ _\n          |       |----/      \        /     \   __/\      __    :\n          l_______|   /_______/        |-----/_______\____       :\n                              l________|(rLf)            /-------:-\n                                                                 :\n                                                                 :\n                                                                 :\n                                                                 .\n\n\n@{fg shine}MagzListMan 1.o@{fg text} is a door for /X and compatibles. To be run from s!x,\nyou need the /X config icons like confconfig.info and <conf>.info...\nA s!x-optimized version will soon be available. \n\nWhat it does: It lets you select files from AquaScan and @{fg shine}delete@{fg text}\nthem/@{fg shine}move@{fg text} them to other confs. Very usefull to @{fg shine}remove@{fg text} old files or\n@{fg shine}move@{fg text} files to let''s say you /X tools conf. @{fg shine}MagzListMan@{fg text} will automaticly\nedit your dir<x> files and put "deleted" in them, or if you wish remove\nthe files from the dirs completely. @{"Install" link installation} it and check it out! \n\n                           UNREGISTERED VERSION!\n\n           TO RECEIVE A REGISTERED VERSION WITH YOUR BOARD NAME\n                ON, JUST D!AL @{fg shine}GENETIC WASTE@{fg text} - +47-33o45192\n                 AND UPLOAD A SMALL FILE AND ASK FOR ONE.\n\n\n                            -magz of megastyle-\n\n@endnode\n\n\n\n\n\n\n@node installation\n\n .\n                                                                              .\n :\n :                                                                            :\n : __        _____ .___.   ______ __.              _________. ____________    :\n_:(__)_______\_ _/_|_  l___\__  // _l______.  _____\__  //  l____)_  _   /____:_\n :    | __    /_  _ /   /     _ // \     /_l__\__     _ //   /    |_    / ___ :\n_:____|--/   /-/  //    |--/____/----/__/ \     /--/____/    |____|/---/\--/  :\n :      /___/ /___/_____|(rLf)          \---/__/       l_____|            /___:_\n :                                                                            :\n :                        i n s t a l l a t i o n                             :\n .                                                                            :\n                                                                              .\n\n@{fg shine}To install...@{fg text}\n\n   To install it for use from AquaScan (what it was made for), copy the\n   files in commands/ and doors/ to BBS:. Then edit your AquaScan.info \n                    file (located in DOORS:Aquascan/) \n       (or AquaScan.config if you use the text-config for AquaScan)\n\n                                LIKE THIS:\n\nwhere <num> is the number you choose for the command (can be whatever you want)\n\n\nPPC_CMD.<num>=DEL\n(DEL is the command used to execute MGZLISTMAN)\n\nPC_KEY.<num>=D\n(Where D is the hotkey in Aquascan used to execute MGZLISTMAN. \n(if you already are using D, use another key)\n\nPPC_ACS.<num>=255\n(access level to run MGZLISTMAN .. should be 255 so other people can''t\nfuck your filelists!)\n\nPPC_DSC.<num>=MagzListManager\n(The name of the command that will appear in the Aquascan Help)..\n\nPPC_CNF.<num>=YES\n(If command can be executed in CS mode in other confs. MUST be\nyes due to a bug in /X)\n\nPPC_NUM.<num>=YES\n(If you can select files for delfiles by numbers. SHOULD ABSOLUTELY\nbe YES!!!)\n\n\n\n... Well, that should be it actually :) \n\n\n\n@{"how do I use it then?!" link how 2 use}\n\n@endnode\n\n\n\n\n\n@node how 2 use\n@title "                                              )>» h o w  2  u s e «<("\n\n                                      ½½½½½½½½½½½½½½½½½½½½½½½.\n                                     ½½½½½½½½         ½½½½½½½½\n      ____.            _________         _______      ½½½½½½½½\n   ___\ __l____________\       /_________\     /______½½½½½½½½\n   \    \___        _             _      /\           ½½½½½½½½\n    \______/      __l__    "    __l__           ___   ½½½½½½½½\n          /_______)   (_________)   (___________) /_  ½½½½½½½½\n                                                   |  ½½½½½½½½\n                ½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½''\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½      ._____      _____    |   _|________\n                ½½½½½½½½______|    /_____/ ___/____|___\  ____  /___\n                ½½½½½½½½      |       _  \_______   _       l/     /\n                ½½½½½½½½__    l     __l__       l __l__  _________/\n                ½½½½½½½½ (__________)   (_________)|  (____/\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½  @{fg shine}   h o w       u s e  @{fg text}   |  ½½½½½½½½\n                ½½½½½½½½      @{fg shine}       2    @{fg text}         |  ½½½½½½½½\n                ½½½½½½½½                           |  ½½½½½½½½\n                ½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½\n\n\n\n        Select the files from @{fg shine}AquaScan@{fg text} that you want deleted/moved.\n        Then just follow the instructions that pop up. If you can''t\n                        understand, don''t use it :)\n\n                                  Woyaya!\n\n@endnode\n\n\n\n\n\n\n@node copyright\n            .\n\n            :\n            :                                      ________ _______ _  _\n           _:__________  _________________ ________\__   _//\n            :      ___/__\__    __      /\\\ __      /___ /       .\n          _ :_ ____        /___        /     \______/   /_________:_ _\n            :     /-------/ __/-------/\_