INSERT INTO door_catalog VALUES('mgs_zsea','MGS-ZSEA.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MGS-ZSEA.LHA','zippy-search','XIM','zippy-search',NULL,NULL,'MGS','____\        /___\   ____  /____/ ___/______ _     \l      _  \_______ ____\/       __l_________  __l__       l ___',replace('    __________   ___________     _____\n____\        /___\   ____  /____/ ___/______\n               _     \l      _  \_______\n____\/       __l_________  __l__       l ___\ng®m /________)   e^D \_____)   (_________)\n          «« m e g a s t y l e  »»\n               ...presents...\n \n             Zippy-Search v1.o.\n \nNEW and IMPROVED Search-Utility for /X & S!X\n','\n',char(10)),'Zippy-Search.GUIDE',replace('@database "mEGAZTYLE.guide"\n@node MAIN\n@title "                                              »«  m e g a s t y l e  »«  r u l e s  »«"\n@{b}\n                              @{u}m e g a s t y l e@{uu}\n\n                 ________   _________   _________     ______.\n           ______\      /___\  ___  /___\  ___  /_____\____ l____\n     ______\              _     l/    _    \l     _     __/     /_______\n.___(       \____\/     __l__  _______l_______  __l__   \l_____/        )___.\n|                /______)   (_____/        \____)   (____\                  |\n|                                                                           |\n| g®m      _____      ___.           .______   ___.       _________     e^D |\n|___  ____/ ___/______\  l___________|     /___\ _l_______\  ___  /____  ___|\n   (__\   \______   _    __/     _   l       _   \      _     l/      /__)\n       \__      l __l__  l     __l_______  __l_        _l_  _________/\n         (________)   (________)     \_____)  (________) (_____/ @{ub}\n\n\n\n@{fg shine}                  p r e s e n t s   a   n e w   d o o r :@{fg text}\n\n\n                   @{b}    @{bg shine}@{u}Z i p p y - S e a r c h    1 . o@{bg back}@{ub}@{uu}\n\n\n\n\n              @{"           d o c u m e n t a t i o n           " link index}\n\n\n\n\n@endnode\n\n@node index\n@title "                                             »» i n d e x ««"\n\n\n    @{u}                                                          @{uu}\n\n\n@{b}                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n         ____        __________          ____.   ___________   ½½½½½  ½½½½½\n________(___/________\ __     /__________\___l___\  ____   /__    `½½½½''\n                   _   l/       _      _____/  _      l/      ½½½½½½  ½½½½½½\n_____            __l___/      __l__    l     __l__  __________½½½½½½  ½½½½½½\n    (____________)    /_______)   (__________)   (_____/      ½½½½½½  ½½½½½½\n                                                              ½½½½½½  ½½½½½½\n                                                              ½½½½½½  ½½½½½½\n   @{fg shine} @{"            introduction             "  link introduction      }    @{fg text}                ½½½½½½  ½½½½½½\n@{fg shine}    @{"            installation             "  link installation      }          @{fg text}          ½½½½½½  ½½½½½½\n@{fg shine}    @{"              how 2 use              "  link how 2 use         }\n    @{"              copyright              "  link copyright         }\n    @{"          changes ÷ history          " link changes ÷ history  } @{ub} @{fg text}\n\n\n    @{u}                                                          @{uu}\n\n\n@endnode\n\n\n\n\n\n\n\n\n@node introduction\n                                                                 .\n\n                                                                 :\n                                                                 :\n             __________________.______.      ________            :\n          ._(___)_.   ___     _|      l_____\\_     /____________:_ _\n          |       |----/      \        /     \   __/\      __    :\n          l_______|   /_______/        |-----/_______\____       :\n                              l________|(rLf)            /-------:-\n                                                                 :\n                                                                 :\n                                                                 :\n                                                                 .\n\n\n@{fg shine} Zippy-Search @{fg text}is probably the most used searchtool for /X and S!X.\n However, most of the searchers previously released have not support for large\n dirlists, or more than 10 conference Dir(nr) files containing your File_id`s.\n\n   I think of this door as one of the FASTEST ever for the /X or S!X, and it\n    also includes many new features NEVER been used in earlier Z-versions.\n               Just check out the screenshots before installing!\n\n\n A especially thanks to Kingpin/Spaceballs for the nice Beta-testing and good\n           support + design ideas! - I hope you enjoy the result! :)\n\n\n       The things that makes this Zippy differ from other searchers are:\n    <«-------------------------------------------------------------------»>\n\n       «»          Simple and easy interface toward the user          «»\n       «»     Logical analyze of arguments provided to the door.      «»\n       «»     Highly OPTIMIZED Assembler search-routines! (FAST!)     «»\n       «»   The best Error-trap system ever made to a AmiX/S!X door   «»\n       «»   Fully compatible with older versions of Zippy-Searchers   «»\n\n\n           - - - --- ------[ lizard of megastyle! ]------ --- - -  -\n\n@endnode\n\n\n\n\n\n\n@node installation\n\n .\n                                                                              .\n :\n :                                                                            :\n : __        _____ .___.   ______ __.              _________. ____________    :\n_:(__)_______\_ _/_|_  l___\__  // _l______.  _____\__  //  l____)_  _   /____:_\n :    | __    /_  _ /   /     _ // \     /_l__\__     _ //   /    |_    / ___ :\n_:____|--/   /-/  //    |--/____/----/__/ \     /--/____/    |____|/---/\--/  :\n :      /___/ /___/_____|(rLf)          \---/__/       l_____|            /___:_\n :                                                                            :\n :                        i n s t a l l a t i o n                             :\n .                                                                            :\n                                                                              .\n\n@{fg shine}To install...@{fg text}\n\n Well, it''s very simple to install. Just copy the directory-structure as it is\n presented in its original archive into your BBS: assignment.\n\n\n Megastyle! is not to held responsible if this program should cause any damage\n to your computer or lead to loss of data. It is provided as is, and is being\n installed and used on your own risk. There is no installer-script provided\n together with the UNREGISTERED versions of the Megastyle! productions!\n\n\n@endnode\n\n\n\n\n\n@node how 2 use\n@title "                                              )>» h o w  2  u s e «<("\n\n                                      ½½½½½½½½½½½½½½½½½½½½½½½.\n                                     ½½½½½½½½         ½½½½½½½½\n      ____.            _________         _______      ½½½½½½½½\n   ___\ __l____________\       /_________\     /______½½½½½½½½\n   \    \___        _             _      /\           ½½½½½½½½\n    \______/      __l__    "    __l__           ___   ½½½½½½½½\n          /_______)   (_________)   (___________) /_  ½½½½½½½½\n                                                   |  ½½½½½½½½\n                ½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½''\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½      ._____      _____    |   _|________\n                ½½½½½½½½______|    /_____/ ___/____|___\  ____  /___\n                ½½½½½½½½      |       _  \_______   _       l/     /\n                ½½½½½½½½__    l     __l__       l __l__  _________/\n                ½½½½½½½½ (__________)   (_________)|  (____/\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½  @{fg shine}   h o w       u s e  @{fg text}   |  ½½½½½½½½\n                ½½½½½½½½      @{fg shine}       2    @{fg text}         |  ½½½½½½½½\n                ½½½½½½½½                           |  ½½½½½½½½\n                ½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½\n\n\n\n     Just @{"Install" link installation} it and run it from /X or S!X.\n\n  Then you can type "Z HELP" or "Z ?" if you should ever wonder how it works.\n\n\n\n\n                         About the Dirlist operators :\n             <«=-----------------------------------------------»>\n\n \n  You may use any of these syntax : 1,2,3-6,u,a \n\n  A = ALL directories. When encountered this letter in a dirlist, all dirs will\n      automaticly be searched through. Even if you have specified dirnr infront\n      of this argument.\n\n  U = Upload dir. Usually the last directory of your conference DirX structure.\n\n  , = Seperator. Used to choose multiple dirnr. to check through. 1,2,3,4..etc.\n\n  - = Mark dirs. Handy when you wish to search through dirs 1 => 7.. "1-7" will\n      then be the correct syntax. Can be combined with seperator. \n\n\n      For instant : Z 1,4-7,12-22 my-search-words..\n\n      (or like this: Z my-search-words.. 1,4-7,12-22 ... The same thing! :)\n\n\n\n\n\n                       About the Searchlist operators :\n             <«=----------------------------------------------»>\n\n  You may use any of these syntax : &, !, / \n\n  & = logic AND of searchwords. For instant, you wish to find a file_id which\n      contains both the word "Amiga_News" AND "#14" ... Then you can simply\n      write : Z a Amiga_news & #14   ... and you would skip all the other files\n      that doesn''t have BOTH these words in the File_id... VERY useful when\n      searching for a specified disk-nr. in a diskset for a program.\n\n  ! = logic NOT. This is used the same way as the &, but often combined with\n      the & operator. Example : Z a Amiga_news &! #14 ! Lizard\n\n  / = Is used to find a file_id with none of the above operators involved.\n      For instant : Z a lizard & instant / magz\n\n      This would lead to a search after the two words "lizard" AND "instant",\n      or a file_id with only the word "magz" in.  \n\n\n\n  REMEMBER : The search-string is NON-CASE-SENSITIVE... To easy your pain! :)\n\n\n\n  The Searchlist options will ONLY be available in the REGISTERED versions. \n    Do consider to register your door. You''ll then be able to recieve the \n                           future upgrades for FREE.\n\n\n@endnode\n\n\n\n\n\n\n@node copyright\n            .\n\n            :\n            :                                      ________ _______ _  _\n           _:__________  _________________ ________\__   _//\n            :      ___/__\__    __      /\\\ __      /___ /       .\n          _ :_ ____        /___        /     \______/   /_________:_ _\n            :     /-------/ __/-------/\______|        ___________|\n            :     _________(___)__________    ________/       /   l_\n           _:____\\_     /       |    ___/____\__   _        /     /\n            :     \   __/\_______|   /_         /---/       /      |\n         - -:-----/_______\(rLf) \----/________/   /_______/_______|\n            :\n            :                 c o p y r i g h t\n            :\n            .\n\n\n\n                                 ---[%]---\n\n                    Zippy-Search is a Megastyle! production\n\n               Code, idea & design by   Lizard of TBL MGS!\n               Error-logo by            Magz of GRT MGS!\n               Tooltype read code by    Lizard of TBL MGS!\n\n\n              \n\n                         Creds for this GUIDE file\n\n               Slapped together by      Lizard\n               Asciis by                Relief   of T! MGS! 5D\n                                        Grimlock of GRT E^D MGS!\n\n                                 ---[%]---\n\n\n\n                      Megastyle! does now consist of\n \n               Leader . . . . . . . . . Lizard\n               Code . . . . . . . . . . Lizard\n                                        Magz\n                                        Instant\n                                        Splash\n               AscII. . . . . . . . . . Relief\n                                        U-MAN\n                                        Grimlock!\n                                        Magz\n               Boards . . . . . . . . . Noiseless - WHQ         LIZARD\n                                        Genetic Waste           MAGZ\n                                        Ecstatica               INSTANT\n                                        Traders Paradise        U-MAN\n\n                                 ---[%]---\n\n\n\n\n\n\n   ............\n   ::        ::\n   ::        ::\n    .        ::\n   /_____    ::          ___________                                          .\n  /_     \//\____________\      ___/_______    _________\n //      \/        _     /     /_         /____\___    //                     :\n/--------/     .---/____/   .---/________         _    //                     :\n     -T!/______\  /_       _|  .______.  \-----/_______/                      :\n                  __\   __/____|_     l_          _______.     _____________  :\n   ::        ::   \  \__    _ _        /_____ ____\     _l_____\     _     /__:_\n   ::        ::    \--(/      /            _//          \        ____/____/  /:\n   ::        ::       /____________________ /      /\-----/_____/   /_________:_\n   ::        ::                           /_______/(rLf)                      :\n   ::........::                                                               :\n                                                                              :\n                        m e g a s t y l e    ¹ 9 9 6                          :\n                                                                              .\n\n@endnode\n\n\n\n\n\n\n@node changes ÷ history\n\n\n    ___.        __      ____    ___.      _____  ½½½½½½½½½½      .____\n  ._\ _l_______(_/_____/ __/____\  l______\   /__½½½½   ½½½______|   /_.\n  |   \__   _       _  \____  _    __/  _        ½½½½½½½''        l     |\n  |____l/  _l_     _l_     l _l_   l   _l_  "  __½½½½   ½½½½½_______  _l\n g®m   /___) (_____) (_______) (_______) (_____) ½½½½   ½½½½½   \_____)\n                                                 ½½½½   ½½½½½ e^D\n\n                               ...HISTORY...\n\n\n\n2000BC          Started on the Door, gave it to all the MGS!-members AND one\n                beta-version to Kingpin for heavy-testing. THANX MATE!\n\n29.03.96        First Public-Release v1.o of the door. Together with a bunch\n                of other doors + a intro. - I sure hope you have it ALL! :)\n\n\n\n\n\n\nThanks to the following boards for helpful beta-testing of MegaStyle-products:\n«----------------------------------------------------------------------------»\n\n                             Genetic Waste (Magz)\n  Checkpoint (Kingpin)   -   Power Rage (Instant)   -   EveryWare (-Shade!)\n\n\n\n@endnode\n','\n',char(10)),NULL,'auto-added',37433,6,0,NULL,NULL,'mgs_zsea','scan',1780048602);
INSERT INTO door_catalog VALUES('mgsmagli','MGSMAGLI.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MGSMAGLI.LHA','mgzlistman','XIM','mgzlistman',NULL,NULL,NULL,'____\        /___\   ____  /____/ ___/______ _     \l      _  \_______ ____\/       __l_________  __l__       l ___',replace('    __________   ___________     _____\n____\        /___\   ____  /____/ ___/______\n               _     \l      _  \_______\n____\/       __l_________  __l__       l ___\ng®m /________)   e^D \_____)   (_________)\n \n          »» magzlistmanager 1.o ««\n \nTired of DELETING and MOVING files manually?\n Then this is the perfect /X door for you!\nNow you can do all that stuff from AQUASCAN!\n','\n',char(10)),'ListManDoc.GUIDE',replace('@database "mEGAZTYLE.guide"\n@node MAIN\n@title "                                              »«  m e g a s t y l e  »«  r u l e s  »«"\n@{b}\n                              @{u}m e g a s t y l e@{uu}\n\n                 ________   _________   _________     ______.\n           ______\      /___\  ___  /___\  ___  /_____\____ l____\n     ______\              _     l/    _    \l     _     __/     /_______\n.___(       \____\/     __l__  _______l_______  __l__   \l_____/        )___.\n|                /______)   (_____/        \____)   (____\                  |\n|                                                                           |\n| g®m      _____      ___.           .______   ___.       _________     e^D |\n|___  ____/ ___/______\  l___________|     /___\ _l_______\  ___  /____  ___|\n   (__\   \______   _    __/     _   l       _   \      _     l/      /__)\n       \__      l __l__  l     __l_______  __l_        _l_  _________/\n         (________)   (________)     \_____)  (________) (_____/ @{ub}\n\n\n\n@{fg shine}                  p r e s e n t s   a   n e w   d o o r :@{fg text}\n\n\n @{b}                     @{bg shine}@{u} m a g z l ! s t m a n   1 . o @{bg back}@{uu}@{ub}\n\n\n\n              @{"           d o c u m e n t a t i o n           " link index}\n\n\n\n\n@endnode\n\n@node index\n@title "                                             »» i n d e x ««"\n\n\n    @{u}                                                          @{uu}\n\n\n@{b}                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n         ____        __________          ____.   ___________   ½½½½½  ½½½½½\n________(___/________\ __     /__________\___l___\  ____   /__    `½½½½''\n                   _   l/       _      _____/  _      l/      ½½½½½½  ½½½½½½\n_____            __l___/      __l__    l     __l__  __________½½½½½½  ½½½½½½\n    (____________)    /_______)   (__________)   (_____/      ½½½½½½  ½½½½½½\n                                                              ½½½½½½  ½½½½½½\n                                                              ½½½½½½  ½½½½½½\n   @{fg shine} @{"            introduction             "  link introduction      }    @{fg text}                ½½½½½½  ½½½½½½\n@{fg shine}    @{"            installation             "  link installation      }          @{fg text}          ½½½½½½  ½½½½½½\n@{fg shine}    @{"              how 2 use              "  link how 2 use         }\n    @{"              copyright              "  link copyright         }\n    @{"          changes ÷ history          " link changes ÷ history  } @{ub} @{fg text}\n\n\n    @{u}                                                          @{uu}\n\n\n@endnode\n\n\n\n\n\n\n\n\n@node introduction\n                                                                 .\n\n                                                                 :\n                                                                 :\n             __________________.______.      ________            :\n          ._(___)_.   ___     _|      l_____\\_     /____________:_ _\n          |       |----/      \        /     \   __/\      __    :\n          l_______|   /_______/        |-----/_______\____       :\n                              l________|(rLf)            /-------:-\n                                                                 :\n                                                                 :\n                                                                 :\n                                                                 .\n\n\n@{fg shine}MagzListMan 1.o@{fg text} is a door for /X and compatibles. To be run from s!x,\nyou need the /X config icons like confconfig.info and <conf>.info...\nA s!x-optimized version will soon be available. \n\nWhat it does: It lets you select files from AquaScan and @{fg shine}delete@{fg text}\nthem/@{fg shine}move@{fg text} them to other confs. Very usefull to @{fg shine}remove@{fg text} old files or\n@{fg shine}move@{fg text} files to let''s say you /X tools conf. @{fg shine}MagzListMan@{fg text} will automaticly\nedit your dir<x> files and put "deleted" in them, or if you wish remove\nthe files from the dirs completely. @{"Install" link installation} it and check it out! \n\n                           UNREGISTERED VERSION!\n\n           TO RECEIVE A REGISTERED VERSION WITH YOUR BOARD NAME\n                ON, JUST D!AL @{fg shine}GENETIC WASTE@{fg text} - +47-33o45192\n                 AND UPLOAD A SMALL FILE AND ASK FOR ONE.\n\n\n                            -magz of megastyle-\n\n@endnode\n\n\n\n\n\n\n@node installation\n\n .\n                                                                              .\n :\n :                                                                            :\n : __        _____ .___.   ______ __.              _________. ____________    :\n_:(__)_______\_ _/_|_  l___\__  // _l______.  _____\__  //  l____)_  _   /____:_\n :    | __    /_  _ /   /     _ // \     /_l__\__     _ //   /    |_    / ___ :\n_:____|--/   /-/  //    |--/____/----/__/ \     /--/____/    |____|/---/\--/  :\n :      /___/ /___/_____|(rLf)          \---/__/       l_____|            /___:_\n :                                                                            :\n :                        i n s t a l l a t i o n                             :\n .                                                                            :\n                                                                              .\n\n@{fg shine}To install...@{fg text}\n\n   To install it for use from AquaScan (what it was made for), copy the\n   files in commands/ and doors/ to BBS:. Then edit your AquaScan.info \n                    file (located in DOORS:Aquascan/) \n       (or AquaScan.config if you use the text-config for AquaScan)\n\n                                LIKE THIS:\n\nwhere <num> is the number you choose for the command (can be whatever you want)\n\n\nPPC_CMD.<num>=DEL\n(DEL is the command used to execute MGZLISTMAN)\n\nPC_KEY.<num>=D\n(Where D is the hotkey in Aquascan used to execute MGZLISTMAN. \n(if you already are using D, use another key)\n\nPPC_ACS.<num>=255\n(access level to run MGZLISTMAN .. should be 255 so other people can''t\nfuck your filelists!)\n\nPPC_DSC.<num>=MagzListManager\n(The name of the command that will appear in the Aquascan Help)..\n\nPPC_CNF.<num>=YES\n(If command can be executed in CS mode in other confs. MUST be\nyes due to a bug in /X)\n\nPPC_NUM.<num>=YES\n(If you can select files for delfiles by numbers. SHOULD ABSOLUTELY\nbe YES!!!)\n\n\n\n... Well, that should be it actually :) \n\n\n\n@{"how do I use it then?!" link how 2 use}\n\n@endnode\n\n\n\n\n\n@node how 2 use\n@title "                                              )>» h o w  2  u s e «<("\n\n                                      ½½½½½½½½½½½½½½½½½½½½½½½.\n                                     ½½½½½½½½         ½½½½½½½½\n      ____.            _________         _______      ½½½½½½½½\n   ___\ __l____________\       /_________\     /______½½½½½½½½\n   \    \___        _             _      /\           ½½½½½½½½\n    \______/      __l__    "    __l__           ___   ½½½½½½½½\n          /_______)   (_________)   (___________) /_  ½½½½½½½½\n                                                   |  ½½½½½½½½\n                ½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½''\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½      ._____      _____    |   _|________\n                ½½½½½½½½______|    /_____/ ___/____|___\  ____  /___\n                ½½½½½½½½      |       _  \_______   _       l/     /\n                ½½½½½½½½__    l     __l__       l __l__  _________/\n                ½½½½½½½½ (__________)   (_________)|  (____/\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½  @{fg shine}   h o w       u s e  @{fg text}   |  ½½½½½½½½\n                ½½½½½½½½      @{fg shine}       2    @{fg text}         |  ½½½½½½½½\n                ½½½½½½½½                           |  ½½½½½½½½\n                ½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½\n\n\n\n        Select the files from @{fg shine}AquaScan@{fg text} that you want deleted/moved.\n        Then just follow the instructions that pop up. If you can''t\n                        understand, don''t use it :)\n\n                                  Woyaya!\n\n@endnode\n\n\n\n\n\n\n@node copyright\n            .\n\n            :\n            :                                      ________ _______ _  _\n           _:__________  _________________ ________\__   _//\n            :      ___/__\__    __      /\\\ __      /___ /       .\n          _ :_ ____        /___        /     \______/   /_________:_ _\n            :     /-------/ __/-------/\______|        ___________|\n            :     _________(___)__________    ________/       /   l_\n           _:____\\_     /       |    ___/____\__   _        /     /\n            :     \   __/\_______|   /_         /---/       /      |\n         - -:-----/_______\(rLf) \----/________/   /_______/_______|\n            :\n            :                 c o p y r i g h t\n            :\n            .\n\n\n\n                                 ---[%]---\n\n                    MAGZLISTMAN is a Megastyle! production\n\n               code, idea & design by   Magz of MGS! GRT INT\n               tooltype read code by    Lizard of TBL MGS!\n\n               \n\n                         Creds for this GUIDE file\n\n               Slapped together by      Magz\n               Asciis by                Relief   of T! MGS! 5D\n                                        Grimlock of GRT E^D MGS!\n\n                                 ---[%]---\n\n\n\n                      Megastyle! does now consist of\n \n               Leader . . . . . . . . . Lizard\n               Code . . . . . . . . . . Lizard\n                                        Magz\n                                        Splash\n                                        Instant\n               AscII. . . . . . . . . . Relief\n                                        Grimlock!\n                                        Magz\n                                        U-MAN\n               Boards . . . . . . . . . Noiseless - WHQ         LIZARD\n                                        Genetic Waste           MAGZ\n                                        Ecstatica               INSTANT\n                                        Final Impact (SHQ)      U-MAN\n\n                                 ---[%]---\n\n\n\n\n\n\n   ............\n   ::        ::\n   ::        ::\n    .        ::\n   /_____    ::          ___________                                          .\n  /_     \//\____________\      ___/_______    _________\n //      \/        _     /     /_         /____\___    //                     :\n/--------/     .---/____/   .---/________         _    //                     :\n     -T!/______\  /_       _|  .______.  \-----/_______/                      :\n                  __\   __/____|_     l_          _______.     _____________  :\n   ::        ::   \  \__    _ _        /_____ ____\     _l_____\     _     /__:_\n   ::        ::    \--(/      /            _//          \        ____/____/  /:\n   ::        ::       /____________________ /      /\-----/_____/   /_________:_\n   ::        ::                           /_______/(rLf)                      :\n   ::........::                                                               :\n                                                                              :\n                        m e g a s t y l e    ¹ 9 9 6                          :\n                                                                              .\n\n@endnode\n\n\n\n\n\n\n@node changes ÷ history\n\n\n    ___.        __      ____    ___.      _____  ½½½½½½½½½½      .____\n  ._\ _l_______(_/_____/ __/____\  l______\   /__½½½½   ½½½______|   /_.\n  |   \__   _       _  \____  _    __/  _        ½½½½½½½''        l     |\n  |____l/  _l_     _l_     l _l_   l   _l_  "  __½½½½   ½½½½½_______  _l\n g®m   /___) (_____) (_______) (_______) (_____) ½½½½   ½½½½½   \_____)\n                                                 ½½½½   ½½½½½ e^D\n\n                               ...HISTORY...\n\n\n\n22.o3.96                After MANY betaversions a version @{fg shine}1.o@{fg text} is\n                        finished. Hope it''s not too buggy! :) First public version.\n\n3o.o3.96                Finally! Can''t find more bugs neither can the betatesters(?)\n                        hehe.. version @{fg shine}1.o@{fg text} finally finished. Public Version!\n\n@endnode\n','\n',char(10)),NULL,'auto-added',21285,6,0,NULL,NULL,'mgsmagli','scan',1780048602);
INSERT INTO door_catalog VALUES('mgsmchat','MGSMCHAT.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MGSMCHAT.LHA','chatter','XIM','chatter',NULL,'Splash',NULL,'_\_/    / _  __  ______ _______/__  ___    / | _ \  /     /  __/__/   /_ _   /   ___   / |__\ \/ /___/_____________/____/____//___/',replace(' ___     _______________________ _ _________\n_\_/    / _  __  ______ _______/__  ___    /\n| _ \  /     /  __/__/   /_ _   /   ___   /\n|__\ \/ /___/_____________/____/____//___/\n    \  /                   .------------.\n     \/ Mega-Chatter 1.1 «-÷-  styLE!   ¡\n                By Splash  `------------÷\n   Nice little chatter door that will   |\n display random txt files when entering |\n chat.   Can use different languages!   |\n -[05.07.95]------ ---- ---------·st!·--''\n [World release at FlAMe StRiKe MGS! WHQ]\n','\n',char(10)),'MegaChatter.Guide',replace('@database "Mega-Chatter.Guide"\n@WIDTH 77\n@NODE Main "MAIN" "Welcome to Mega-Chatter Documentation"\n\n .--------------------  ---(c)-[ mEGAStYLE! pRODUCtiON ''95\n |    ____     _______________________________  _ _____________ _\n ! ___\ _/    / _  ___  __________  _________/_ __   ____       /\n . |    _ \  /      /  ___/_____/    /__ _      /    _//_      / -----.\n ¦ |st!  \ \/ /    /    /      /       /       /     _____    /   -- -÷ -»\n | |______\  /_______________________________________//______/ -------''\n |         \/           \n |\n-÷- -» _____________ ______          _____     _ ______      _ _______ ____\n |  ___\   ________/_     /_       _/    /___         /    _ __  _________/\n |  |__________     /    __/______/     /    \ /     /_______/  ___/_______\n |  |      |       /    /        /     /      \     /       /    /        /\n |  |______________________________________    \_________________________/\n .                              _  _ _____¬_____/\n |\n |\n `--------------------------------------------------- ------------ -[   -»\n\n\n\n\n\n\n                           Mega-Chatter 1.1 (05-07-95)\n     \n                              By Splash/Megastyle\n                                         \n                          @{"What is Mega-Chatter ?    " LINK "ABOUT"}   \n                          @{"What is new since v1.0 ?  " LINK "NEW"}\n                          @{"Requirements.             " LINK "REQ"}                \n                          @{"Installation.             " LINK "INSTA"}              \n                          @{"How to operate.           " LINK "OPERATE"}\n                          @{"Credits                   " LINK "CREDS"}\n                          @{"Greetings.                " LINK "GREET"}                 \n                          @{"About Megastyle.          " LINK "MEGASTYLE"}\n                          @{"How to contact the Author " LINK "HOWTOCONTACT"}\n              \n@ENDNODE\n\n\n\n\n\n\n\n\n\n\n@NODE "ABOUT" "What is Mega-Chatter ?"\n\n                                                               @{" Go back.. " Link MAIN}\nMega-Chatter is a nice little tool I made just for fun. I wanted to have a \nbetter way to start my chats (when you are a sysop you actually do alot of \nchatting... I do anyway..)  \n\nThis door is actually a simple writer, that will write som random txt to the \nuser when entering chat. You as sysop have the opportunity to choose which \ntype of txt you want to display. You can disply txt in different languages, \nin different moods or whatever. YOU choose.. The txt will be written just as \nif YOU were the one actually writing it. You also have the ability to include\nuser''s handle in the txt... The users will be impressed with you writing \nskills! :-) \n@ENDNODE\n\n@NODE "REQ" "Requirements."\n\n                                                               @{" Go back.. " Link MAIN}\nA Commodore Amiga computer (Pese suxx :-) running on kick 2.0+, /X \n(I guess any version will do...) \n\nThis door uses the AEDoor.libary, so you should have this in LIBS:\n(If you haven''t got it then call me or your local /X board to get it...) \n@ENDNODE\n\n\n@NODE "INSTA" "Installation."\n\n                                                               @{" Go back.. " Link MAIN}\n                             \n1. Copy the included files to the correct dirs.\n\n2. Edit the nodex/startchat.txt and include:''~CC_CHATTER''\n\n3. If you want, Mega-Chatter can display a txt file before starting the writer,\n   if you want this then just call the file chat.txt and put it in ''S:''. \n\n4. This door does not use a specific pen coulour, so the pen/paper colour can be set\n   f.exs in chat.txt\n\n5. Edit and install the @{"Textfiles" LINK "TEXTFILES"}\n\n6. @{"How to operate" LINK "OPERATE"}\n\nThen start chatting!!! \n@ENDNODE\n\n@NODE "HOWTOCONTACT" "How to contact the Author"\n\n                                                               @{" Go back.. " Link MAIN}\nHow to contact me:\n\n@{"Flame Strike" LINK "FLAME"} :+47 51631702\n\nOr snailmail: Splash/ElTECH & Megastyle\n              Lindeveien 69\n              N-4300 Sandnes\n              Norway\n@ENDNODE\n\n@NODE "CREDS" "Credits."\n\n                                                               @{" Go back.. " Link MAIN}\nCode,Idea    - Splash/ElTECH & Megastyle\nDoor Design  - Splash/ElTECH & Megastyle (Is there any ?)\nGuide Design - Splash/ElTECH & Megastyle\n\n@ENDNODE\n@NODE "GREET" "Greetings."\n\n                                                               @{" Go back.. " Link MAIN}\n                                  \n\n                         Greetings to all my friends ! \n\n                      Special greetings to all /X coders \n\nAND OFCOURSE ALL MEMBERS OF :\n______ ______________ ______ ________    _________/ _|_____/\______ _ __________\n ____ V _________   // ____/_______  \  _\  ______   _  __/  \  __/_________   /\n |   \_/   |   _/  //  \__   |   _/   \/  \___   \   |___     \ \      /  _/  /\n |    |    |  ____/_     |   |   _     /    _/   /   |   \    /  \_   /  ____/_\n |____|    |_______/_________:___\    /_________/____|_______/_______/________/\n      |____|                      \  /                       \n      :    :                       \/\n\n                                   AnD\n\n             _______ /|   _______/\_______________    _____ \n            /~ ____// | __\___  ~__~/  _____/~   ~\  /~ ¡ ~\.  \n           //  __)_// |/ ~\  /  :| //  __) //   .__)//  |  \\\\n           \\     ~\\ ~   \\/   || \\     ~\\   : \\\\      / \  \n            \  ____/\______/\____|  \  ____/\____ // \. |__/  /\n             \/ .____/\______/\_____|\/ .TeTSUo__\/ / \/ ____/\n              \/                      \/          \/   \/ \n\n\n\nPersonal greetings:\n~~~~~~~~~~~~~~~~~~~\nLizard/MGS!      - We ARE growing BIG now!\nWoober/MGS!      - Hi!\nJedi/MGS!        - Get those new nodes SOON!!! :-)\nNightProwler/HLM - Nice talkin'' to yah! Hope you like this door!\nMiC flAiR/ElT    - We need more releases from ElT.....\nLithium/ElT      - Hope we get the chance to talk more..\nMagz/GrT         - Nice colly... greet me in the next one!\n\nSo I 4got YOU? Oki... go ahead shoot me.... I''m guilty...\n\n@ENDNODE\n\n@NODE "FLAME" "Flame Strike"\n                                                               @{" Go back.. " Link MAIN}\n           .    .         .         .        .\n   _______/|___/|________/|____ ___/|_______/|\n _/        l_   |    _    l_   |    l_       l_.........................\n/¬     _____j   |    ¬     l   !     l    ____j                        :\nY         |    _|__  .     | \ : /   |  _____j_     ·fLAME^sTRIKE·     :\n|     ____j   /    l :     |  \ /    |        l                        :\n|        |  _/     | :     |   :     |        |ElTECH EHQ·Megastyle WHQ:\n|        |         | !     |   !     |        |                        :\n|       ||        || |     |   |     |       ||                        :\nl________j_________j_|     |___|     |________jHOt WAREZ·CODERS CORNER·.\n :                   l_____j   l_____j [nUMEN] CHAtABlE SYSOP·YouNameIt.\n :  cREW:                    .         .      .     .         .        .\n :Splash/ElTECH^MGS!  ______/|________/|_____/|____/|____ ___/|_______/|\n :UnmaD/eXCALIBUR   _/  _____j_        l_   _ l_    l_   |    l_       l_  \n :MiC FlAiR/ElTECH /_____     l         l   ¬  l     l   !     j    ____j\n :    [YOU?]       Y     \    |    _____j    __j_    |   :  __/   _____j_\n :                 |      \   |      |    .     |    |   .    \         l\n :BIG /X conf with |       \  |      |    :     |    |   :     |        |\n :  500++ files!   |          |      |    !     |    |   !     |        |\n :.[+47·51631702]  |         ||     ||    |     |   ||   |     |       ||\n.:::....... .... ..l__________j______j____|     |____j___|     |________j\n :                                      : l_____j /X 4.9 l_____j :\n .                                      :........................:\n .\n\n@ENDNODE\n\n@NODE "MEGASTYLE" "About Megastyle"\n\n                                                               @{" Go back.. " Link MAIN}\n\nMegastyle is a new AmiExpress-Support group formed by Lizard of Spaceballs in\nthe middle of may 1995.\n\nOur main goal is to support all the /X-boards out there with the best doors\naround. We try hard to make our products as system-friendly as possible and\nwith unique configuration possibilities.\n\n\nWe want to be the leading /X-development group in the future, and therefore\nneed more skilled coders and ANSI-artist to make our products even better!\n\nIf you''re interesting in teaming up, then take a look at the contact-info.\n\n\n\n   _________ \n    _______ )  ·M·e·g·a·S·t·y·l·e·  ·P·r·o·d·u·c·t·i·o·n·s·\n           )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\nEven if we are a pretty new group we have released a couple of doors allready.\n\nSplash:\nSysDL        v3.2\nGlobalDupe   v1.4\nAutoreward   v1.3\nMega-Chatter v1.0\n\nLizard:\nBulls        v1.0\nNodeStatus   v1.2\n\nAll these doors are just GREAT so check''em out! And more releases to come in near \nfuture!\n\n\n   _________ \n    _______ )  ·M·e·g·a·S·t·y·l·e·  ·B·o·a·r·d·s·\n           )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           +47-51-631702 -=- @{"FlameStrike" Link "FLAME"} ·oOo· Sysop : Splash\n           +47-51-417240 -=- @{"Noiseless  " Link "NOISELESS"} ·oOo· Sysop : Lizard (NightBBS)\n           +47-77-748689 -=- @{"Eternity   " Link "ETERNITY"} ·oOo· Sysop : Woober\n           +47-51-575227 -=- @{"Total Panic" Link "TOTALPANIC"} ·oOo· Sysop : Jedi\n\n@ENDNODE\n@NODE "NOISELESS" "Propaganda : Noiseless BBS!"\n                                                               @{" Go back.. " Link "MEGASTYLE"}\n\n                                        .\n                                           ·\n   _  _  _ _______  _____ __ _____ _____:  :   _____  _____  _____ __ _  _   _\n_   _  _ ______   ||     (__)     |   __|  |  |   __||  ___||  ____ __ _ _  _\n            |  |  ||  |  |  l  `--|  _/_|  |__|  _/_ l  ''--.l  ''--.\n            |  |  ||  |  |  |--,  |  l  |  l  |  l  ||--,  ||--,  |\n            l__|  l|_____l__l__   l__   l__   l__   |l__   ll__   l\n               `--''            `--''  `--''  `--''  `--''   `--''   `--''\n\n                           SysOp : Lizard/Spaceballs\n\n      Phone : +47-51417240, only available between : 23:00PM -> 07:00AM.\n\n@ENDNODE\n@NODE "ETERNITY" "Propaganda : Eternity BBS!"\n                                                               @{" Go back.. " Link "MEGASTYLE"}\n\n                                                               ._____.\n  _____________________________________________________________:__ ._|__\n  \__ _____/___   _   / _____/______  \_   .  _/______ /     _   / |   /\n   /  ___/   /     \_/ ___/    /  _/  _/   |    \    \/¬\     \_/    _/\n  /_________/_______\_________/___\     \__|     \_______\_____\_____|\n                               -cDr\_____\ l______\\n.                                                                       .\n+-÷aMiGA ^ aSCiI ^ mODUlES ^ hACKErS lAnD ^ /X sUPpORT ^ pUBLiC dOMAiN÷-+\n:           [f]EATURING: A1200/020 ^ oNE (n)oDE (14k4 mAXLiTE)          :\n|          [m]ANAGEMENT: [w@@ßE®^tHg^nEo^mGs^bDz]-[SiENCE^tHg]          |\n!   tECHNOLOGY [nHq] · nEO [nHq] · mEGASTYLE [hQ] · bANANa dEZIGn [hQ]  !\n+÷---------------------------------------------------------------------÷+\n:                   [n]UMBER: +47-777-48689 [23 - 07]                   :\n`÷---------------------------------------------------------------------÷''\n\n@ENDNODE\n@NODE "TOTALPANIC" "Propaganda : Total Panic BBS!"\n                                                               @{" Go back.. " Link "MEGASTYLE"}\n\n «*»  Total Panic - 28.8kb v.all - Sysop : Jedi - Number : +47-51-575227  «*»\n\n@ENDNODE\n\n@NODE "TEXTFILES" "How to use the text files."\n\n                                                               @{" Go back.. " Link MAIN}\nOne of the great features of this dooris that you can have up to 10 different \ntextfile types. You can for example have one area in your own language, one in \nEnglish end perhaps a area containing jokes, one angry area aso.\n\nTo use this feature, first of all you must decide how many areas you want.\nThen make one dir for each area (in the same directory as the door was started \nfrom) Name these dirs with a number, from 1-x (where x is the number of areas \nyou want) Now you have to put some files in these areas. You can have as many \nfiles as you want. Also name these files with a number from 1-x.\nThere is no need to configure how many areas you have got or how many txt files \nyou hvae got in each area, my clever door does it all by it self.\n\nOnly the first line of the files will be written. When writing the files you can\nuse ''%U'' (case-sensitive) to include user''s name) Other functions might be \nincluded later, so if you have got any ideas of what I might include then tell \nme!\n\nNow it is time to use this great door, but first have a look here ->@{"OPERATION" LINK "OPERATE"} \n@ENDNODE\n\n@NODE "OPERATE" "How to operate Mega-Chatter"\n\n                                                               @{" Go back.. " Link MAIN}\nWhen started, Mega-Chatter will wait for you to press a key. You have several \noptions. Hitting SPACE will display a random file from ALL the areas you have \ngot. You can also select which area to pick the file from by hitting a numeric \nkey. If you hit f.exs. ''1'' It will pick a random file in area 1. Hitting ''0'' \nwill pick a file in area 10. If you don''t want any txt written, just press any\nother button, and it will work just like ordinary chatting....\n\n@ENDNODE\n@NODE "NEW" "What is new in this version ?"\n\n*I fixed a bug in connection with the displaying of ''chat.txt''. This file now has \nto be put in ''S:'' if you want to use this feature.\n\nNot much bug-fixing, but it was an important fix....\n\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',21037,4,0,NULL,NULL,'mgsmchat','scan',1780048602);
INSERT INTO door_catalog VALUES('mgsmgz','MGSMGZ.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MGSMGZ.LHA','mGzdIRX','XIM','mGzdIRX',NULL,NULL,NULL,'____\        /___\   ____  /____/ ___/______ _     \l      _  \_______ ____\/       __l_________  __l__       l ___',replace('    __________   ___________     _____\n____\        /___\   ____  /____/ ___/______\n               _     \l      _  \_______\n____\/       __l_________  __l__       l ___\ng®m /________)   e^D \_____)   (_________)\n          «« m e g a s t y l e  »»\n \n       »» MgzDirX 1.o for /X & s!x ««\n \n This shell-util scans through your dir<x>s\nAnd removes from list all non-existing Files\n','\n',char(10)),'MGZDIRX.GUIDE',replace('@database "mEGAZTYLE.guide"\n@node MAIN\n@title "                                              »«  m e g a s t y l e  »«  r u l e s  »«"\n@{b}\n                              @{u}m e g a s t y l e@{uu}\n\n                 ________   _________   _________     ______.\n           ______\      /___\  ___  /___\  ___  /_____\____ l____\n     ______\              _     l/    _    \l     _     __/     /_______\n.___(       \____\/     __l__  _______l_______  __l__   \l_____/        )___.\n|                /______)   (_____/        \____)   (____\                  |\n|                                                                           |\n| g®m      _____      ___.           .______   ___.       _________     e^D |\n|___  ____/ ___/______\  l___________|     /___\ _l_______\  ___  /____  ___|\n   (__\   \______   _    __/     _   l       _   \      _     l/      /__)\n       \__      l __l__  l     __l_______  __l_        _l_  _________/\n         (________)   (________)     \_____)  (________) (_____/ @{ub}\n\n\n\n@{fg shine}                  p r e s e n t s   a   n e w   d o o r :@{fg text}\n\n\n @{b}                        @{bg shine}@{u} m a g z d ! r X    1 . o @{bg back}@{uu}@{ub}\n\n\n\n              @{"           d o c u m e n t a t i o n           " link index}\n\n\n\n\n@endnode\n\n@node index\n@title "                                             »» i n d e x ««"\n\n\n    @{u}                                                          @{uu}\n\n\n@{b}                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n         ____        __________          ____.   ___________   ½½½½½  ½½½½½\n________(___/________\ __     /__________\___l___\  ____   /__    `½½½½''\n                   _   l/       _      _____/  _      l/      ½½½½½½  ½½½½½½\n_____            __l___/      __l__    l     __l__  __________½½½½½½  ½½½½½½\n    (____________)    /_______)   (__________)   (_____/      ½½½½½½  ½½½½½½\n                                                              ½½½½½½  ½½½½½½\n                                                              ½½½½½½  ½½½½½½\n   @{fg shine} @{"            introduction             "  link introduction      }    @{fg text}                ½½½½½½  ½½½½½½\n@{fg shine}    @{"            installation             "  link installation      }          @{fg text}          ½½½½½½  ½½½½½½\n@{fg shine}    @{"              how 2 use              "  link how 2 use         }\n    @{"              copyright              "  link copyright         }\n    @{"          changes ÷ history          " link changes ÷ history  } @{ub} @{fg text}\n\n\n    @{u}                                                          @{uu}\n\n\n@endnode\n\n\n\n\n\n\n\n\n@node introduction\n                                                                 .\n\n                                                                 :\n                                                                 :\n             __________________.______.      ________            :\n          ._(___)_.   ___     _|      l_____\\_     /____________:_ _\n          |       |----/      \        /     \   __/\      __    :\n          l_______|   /_______/        |-----/_______\____       :\n                              l________|(rLf)            /-------:-\n                                                                 :\n                                                                 :\n                                                                 :\n                                                                 .\n\n    Loads of sysops have problems when they delete files, and forget to\n     remove them from their dir-listings. Now, if YOU are one of them,\n                    @{fg shine}   MGZDIRX @{fg text}is the tool for YOu!\n\n  @{fg shine} MGZDIRX @{fg text}Scans through your dirs (selected in the cfgfile) and checks\n   the dlpaths on your board if the files really excists. If they don''t,\n               @{fg shine} MGZDiRX @{fg text}removes the @{fg shine}FILE_ID @{fg text}from your dirs.\n\n                            -magz of megastyle-\n\n@endnode\n\n\n\n\n\n\n@node installation\n\n .\n                                                                              .\n :\n :                                                                            :\n : __        _____ .___.   ______ __.              _________. ____________    :\n_:(__)_______\_ _/_|_  l___\__  // _l______.  _____\__  //  l____)_  _   /____:_\n :    | __    /_  _ /   /     _ // \     /_l__\__     _ //   /    |_    / ___ :\n_:____|--/   /-/  //    |--/____/----/__/ \     /--/____/    |____|/---/\--/  :\n :      /___/ /___/_____|(rLf)          \---/__/       l_____|            /___:_\n :                                                                            :\n :                        i n s t a l l a t i o n                             :\n .                                                                            :\n                                                                              .\n\n@{fg shine}To install...@{fg text}\n\nTo install just copy @{fg shine}mGzdIRX@{fg text} to whatever dir on your HD you want\n(BBS:utils??) and edit the config file in S: named @{fg shine}mGZdIRx.cFg@{fg text}\nlike this:\n\n     ----------------[ cut from Magz'' config file ]------------------\nBBS:2elite/dir1\nBBS:2elite/dir2\nBBS:2elite/dir3\nBBS:3request/dir1\nBBS:4amix/dir1\nBBS:5ascii/dir1\nbbs:6grt/dir1\nbbs:7mgs!/dir1\nBBS:9school/dir1\n@\nBBS:2elite/upload/\nBBS:2elite/older/\nBBS:2elite/old/\nBBS:3request/upload/\nBBS:4amix/upload/\nBBS:5ascii/upload/\nbbs:6grt/upload/\nbbs:7mgs!/upload/\nBBS:9school/upload/\n             ----------------[ end of cut ]------------------\n\n\n       The lines above the @{fg shine}@@{fg text} are the @{fg shine}dirs@{fg text} you want to scan through,\n        while the lines below the @{fg shine}@@{fg text} are the @{fg shine}paths@{fg text} the files in your\n                              dir<x> may be. \n\n\n                              %%% @{fg shine}WARNING@{fg text} %%%\n         Remember to write the paths RIGHT and include "@{fg shine}/@{fg text}" or "@{fg shine}:@{fg text}"\n         at the end of @{fg shine}EVERY@{fg text} path, or mGzdIRX wont find your files\n                 and remove all of them from your dir<x>!!\n                              %%% @{fg shine}WARNING@{fg text} %%%\n\n\n\n\n@{"how do I use it then?!" link how 2 use}\n\n@endnode\n\n\n\n\n\n@node how 2 use\n@title "                                              )>» h o w  2  u s e «<("\n\n                                      ½½½½½½½½½½½½½½½½½½½½½½½.\n                                     ½½½½½½½½         ½½½½½½½½\n      ____.            _________         _______      ½½½½½½½½\n   ___\ __l____________\       /_________\     /______½½½½½½½½\n   \    \___        _             _      /\           ½½½½½½½½\n    \______/      __l__    "    __l__           ___   ½½½½½½½½\n          /_______)   (_________)   (___________) /_  ½½½½½½½½\n                                                   |  ½½½½½½½½\n                ½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½''\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½      ._____      _____    |   _|________\n                ½½½½½½½½______|    /_____/ ___/____|___\  ____  /___\n                ½½½½½½½½      |       _  \_______   _       l/     /\n                ½½½½½½½½__    l     __l__       l __l__  _________/\n                ½½½½½½½½ (__________)   (_________)|  (____/\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½  @{fg shine}   h o w       u s e  @{fg text}   |  ½½½½½½½½\n                ½½½½½½½½      @{fg shine}       2    @{fg text}         |  ½½½½½½½½\n                ½½½½½½½½                           |  ½½½½½½½½\n                ½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½\n\n\n\n             Just make the CFG-file and run the mGZdIRX prog.\n                                  Woyaya!\n\n@endnode\n\n\n\n\n\n\n@node copyright\n            .\n\n            :\n            :                                      ________ _______ _  _\n           _:__________  _________________ ________\__   _//\n            :      ___/__\__    __      /\\\ __      /___ /       .\n          _ :_ ____        /___        /     \______/   /_________:_ _\n            :     /-------/ __/-------/\______|        ___________|\n            :     _________(___)__________    ________/       /   l_\n           _:____\\_     /       |    ___/____\__   _        /     /\n            :     \   __/\_______|   /_         /---/       /      |\n         - -:-----/_______\(rLf) \----/________/   /_______/_______|\n            :\n            :                 c o p y r i g h t\n            :\n            .\n\n\n\n                                 ---[%]---\n\n                    MAGZDIRX is a Megastyle! production\n\n               code, idea & design by   Magz of MGS! GRT INT\n               \n\n\n                         Creds for this GUIDE file\n\n               Slapped together by      Magz\n               Asciis by                Relief   of T! MGS! 5D\n                                        Grimlock of GRT E^D MGS!\n\n                                 ---[%]---\n\n\n\n                      Megastyle! does now consist of\n \n               Leader . . . . . . . . . Lizard\n               Code . . . . . . . . . . Lizard\n                                        Magz\n                                        Splash\n                                        Instant(?!)\n               AscII. . . . . . . . . . Relief\n                                        Grimlock!\n                                        Magz\n               Boards . . . . . . . . . Noiseless - WHQ         LIZARD\n                                        Genetic Waste           MAGZ\n                                        Ecstatica               INSTANT\n                                        Final Impact (SHQ)      U-MAN\n\n                                 ---[%]---\n\n\n\n\n\n\n   ............\n   ::        ::\n   ::        ::\n    .        ::\n   /_____    ::          ___________                                          .\n  /_     \//\____________\      ___/_______    _________\n //      \/        _     /     /_         /____\___    //                     :\n/--------/     .---/____/   .---/________         _    //                     :\n     -T!/______\  /_       _|  .______.  \-----/_______/                      :\n                  __\   __/____|_     l_          _______.     _____________  :\n   ::        ::   \  \__    _ _        /_____ ____\     _l_____\     _     /__:_\n   ::        ::    \--(/      /            _//          \        ____/____/  /:\n   ::        ::       /____________________ /      /\-----/_____/   /_________:_\n   ::        ::                           /_______/(rLf)                      :\n   ::........::                                                               :\n                                                                              :\n                        m e g a s t y l e    ¹ 9 9 6                          :\n                                                                              .\n\n@endnode\n\n\n\n\n\n\n@node changes ÷ history\n\n\n    ___.        __      ____    ___.      _____  ½½½½½½½½½½      .____\n  ._\ _l_______(_/_____/ __/____\  l______\   /__½½½½   ½½½______|   /_.\n  |   \__   _       _  \____  _    __/  _        ½½½½½½½''        l     |\n  |____l/  _l_     _l_     l _l_   l   _l_  "  __½½½½   ½½½½½_______  _l\n g®m   /___) (_____) (_______) (_______) (_____) ½½½½   ½½½½½   \_____)\n                                                 ½½½½   ½½½½½ e^D\n\n                               ...HISTORY...\n\n\n\no3.o3.96                Made this on request from Kingpin at Checkpoint.\n                        Coz his filelists were full of non-existant files! :\\n\n3o.o3.96                Added a fuction so that it shows how many files was removed.\n                        V 1.o .. first public release\n\n@endnode\n','\n',char(10)),NULL,'auto-added',17120,6,0,NULL,NULL,'mgsmgz','scan',1780048602);
INSERT INTO door_catalog VALUES('mgsnodem','MGSNODEM.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MGSNODEM.LHA','nodemsg','XIM','nodemsg',NULL,':',NULL,'.aQUa.           `¤×¼¼¼¼¼%×¤''       .-. :r· |\  /|¯¯¯7¯¯7f¯¯¯7¯¯¯7¼f¯T¯7¯7 |¯¯¯7| | |e: | \/ | ¯T| T¯7 '' | `-|¼l ` | | | ¯T¯l_j |s|',replace('                     .¼.                ·P\n.aQUa.           `¤×¼¼¼¼¼%×¤''       .-. :r·\n|\  /|¯¯¯7¯¯7f¯¯¯7¯¯¯7¼f¯T¯7¯7 |¯¯¯7| | |e:\n| \/ | ¯T| T¯7 '' | `-|¼l ` | | | ¯T¯l_j |s|\nl \/ | ¯¯7 '' | | |¯  |¼|¯¯ j ¯¯7 ¯¯7( )¯|e|\\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¼¼¼¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯|n|¯\n                 _./¯~~~¯\._            |t:\n                  ¯¯¯¯¯¯¯¯¯             :s.\n              Node-Message v1.0         .\n\n      Coded by : Lizard of Megastyle!','\n',char(10)),'_Node-Message.guide',replace('@database "Node-Message v1.0.Guide"\n@WIDTH 80\n@INDEX "MAIN"\n@NODE Main "MAIN" "Welcome to the Node-Message Documentation!"\n                                                   __.       \n______ ______________ ______ ________    _________/ _|_____/\______ _ __________\n ____ V _________   // ____/_______  \  _\  ______   _  __/  \  __/_________   /\n |   \_/   |   _/  //  \___  |   _/   \/  \___   \   |___     \ \      /  _/  /\n |    |    |  ____/_     |   |   _     /    _/   /   |   \    /  \_   /  ____/_\n |____|    |_______/_________:___\    /_________/____|_______/_______/________/\n      |____|                      \  /                       \n      :   _____                    \/\n           ____\__________\n            ____\_______  )\n                 \/     ) ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n                        ¯¯¯¯¯¯¯¯¯¯¯¯¯¯ ·g·i·v·e·s·  ·y·o·u·\n\n                                                   \n                        .-------------- -       - ---.\n                        |                          ¯7|\n                        |                            :\n                        :      Node-Message v1.0     .\n                        ·\n                        ·             by\n                                                     ·\n                        ·  Magnar Harestad (Lizard)  :\n                        :·                           |\n                        |l_                          |\n                        `----- -       - ------------''\n\n\n                       Beta-Release date : 21.12.95\n\n                       @{"What is Node-Message v1.0?       " LINK "ABOUT"}   \n                       @{"Requirements to run the program " LINK "REQUIRE"}   \n                       @{"How to install Node-Message...   " LINK "INSTALL"}   \n                       @{"Who''s done what ?               " LINK "CREDITS"}   \n                       @{"The official mGs!-Greetings!    " LINK "GREETINGS"}   \n                       @{"Info about MegaStyle!           " LINK "INFO"}   \n                       @{"How to contact MEGASTyLE!       " LINK "CONTACT"}\n@ENDNODE\n\n\n\n;-------------------------------------------------------------------------------------\n\n\n\n@NODE "ABOUT" "What is Node-Message v1.0 ?"\n                                                               @{" Go back.. " Link MAIN}\n\nI''ve long been thinking about setting up my board with a FIDO mailreader and/or\ntogether with other file/message-sharing systems, but how can this be achieved?\n\nWell, AmiExpress have some communications port ready for this purpose, but I\nthought it would be easier to make a program that you could just give some\nparameters once for all, instead of making stupid Arexx-scripts.\n\nI hope some can find this little CLI/DOS util useful, to suspend/resume and\neven shutdown nodes on your board.\n\n\n-------------------------------------------------------------------------------\n\nThis program should be 100% systemfriendly coded. If any error should\noccure, then the program should managed to shutdown without causing any\ndamage to the system.\n\nThis utility is coded in Amiga-E with inline-ASM for maximal speed-performance!\n\n@ENDNODE\n\n\n\n;-------------------------------------------------------------------------------------\n\n\n\n@NODE "REQUIRE" "Requirements to run this door."\n                                                               @{" Go back.. " Link MAIN}\n\n\nI think that this program should run on any version of WB and Amiga-Dos.\n\nIf you should miss any library, then the door would give a error-message and\nterminate the run automaticly without harming the system.\n\nThe door should be able to run with the ordinary libraries supported with the\noriginal Workbench-package from Commodore. (Any revision)\n\nAlso... Arexx-libraries... :)\n\n@ENDNODE\n\n\n\n;-------------------------------------------------------------------------------------\n\n\n\n@NODE "INSTALL" "How to do the installation..."\n                                                               @{" Go back.. " Link MAIN}\n\nAll you have to do is to copy the main executable file in this archive to\nwhatever directory you wish. I would advice SYS:C/.\n\n\nAlso, if you wish to use it together with AmiExpress v3.x+, then you should\nwrite a command-line into your logoff-script for each node.\n\n\nThat''s all... (Simple isn''t it? :)\n\n\n\n\nFunctionality :\n\n\n  Nodemsg <Node> <Message>\n\n  <Node> is which node the message should be redirected to.\n  <Message> is a string, like : Shutdown, Resume or Suspend.\n\n\n\nKeep in mind :\n\nIf no argument is supported, a usage-help will appear. And if only the node-nr.\nis being used as argument, then the node-nr. will also be the message to send!\n\n\n@ENDNODE\n\n\n\n;-------------------------------------------------------------------------------------\n\n\n\n@NODE "CREDITS" "Credits for this MEGASTYLE production:"\n                                                               @{" Go back.. " Link MAIN}\n\n\n                             The credits goes to :\n                            «=-------------------=»\n\n\n\n             Magnar Harestad, Lizard of Megastyle and Spaceballs!\n\n\n\n\n                        For doing the following things:\n                       «-------------------------------»\n\n                                    Coding\n                                   Designing\n                                Guide-Designing\n                             AsC²-art and designs\n                            Writing this guide-text\n\n\n@ENDNODE\n\n\n\n;-------------------------------------------------------------------------------------\n\n\n\n@NODE "GREETINGS" "The Official MeGaSTyLe GrEeTiNgS:"\n                                                               @{" Go back.. " Link MAIN}\n\n   _________ \n    _______ )  ·M·e·g·a·S·t·y·l·e·  ·s·e·n·d·s·  ·g·r·e·e·t·i·n·g·  ·t·o·\n           )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n Spaceballs, Eltech, Andromeda, CNCD, Parallax, Complex, Virtual dreams, Mystic\nStone Arts, Rebels, TRSI, Scoopex, Avalon, Aquarious, Access, Prestige, Skid Row\n\n                   And to all the other /X-coders out there!\n\n\n________ \n ______ ) ·L·i·z·a·r·d·  ·s·e·n·d·s·  ·s·p·e·c·i·a·l·  ·g·r·e·e·t·i·n·g·  ·t·o·\n       )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n       ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\nInstant : Welcome to MegaStyle, m8!\nMagz    : Love your Logoff-Wall! :)\nSplash  : How''s the army-life? Terrible I guess... :D \nJedi    : If you ever read this, then I hope you''re back on tha Amiga again!\nDr. Ice : Thx for all the help you have given me regarding Amiga-E.\nKingpin : Thanks for all the support you have been giving me!\nJeek E. : Love your intro, man. Flames FoRevEr!\nShorty  : G-shade and texturemapped vectors forever? :)\nMr.Z    : Where are you? Your lines are down... :''-(\nBaffle  : Great new Ansi''s on your board! COOL!\nStratos : How''s life? ... Coded anything lately?\nRainbow : Amiga-E, Amiga-E, Amiga-E! :)\nWoober  : Are you going to get a 28.8kb modem soon?\nFake    : Get a decent modem, and get that board on the air!\n\n\n                   And a nice HUGE hug to all my IRC-mates!\n\n@ENDNODE\n\n\n\n;-------------------------------------------------------------------------------------\n\n\n\n@NODE "INFO" "About MegaStyle..."\n                                                               @{" Go back.. " Link MAIN}\n\nMegastyle is a new AmiExpress-Support group formed by Lizard of Spaceballs in\nthe middle of may 1995.\n\nOur main goal is to support all the /X-boards out there with the best doors\naround. We try hard to make our products as system-friendly as possible and\nwith unique configuration possibilities.\n\n\nWe want to be the leading /X-development group in the future, and therefore\nneed more skilled coders and ANSI-artist to make our products even better!\n\n\n\nIf you''re interesting in teaming up, then take a look at the contact-info.\n\n\n\n\nThanks to the following boards for helpful beta-testing of MegaStyle-products:\n«----------------------------------------------------------------------------»\n\n                            Dr. Feelgood (Science)\n  Checkpoint (Kingpin)   -   Power-Rage (Instant)   -   Genetic Waste (Magz)\n\n@ENDNODE\n\n\n\n;-------------------------------------------------------------------------------------\n\n\n\n@NODE "CONTACT" "How to contact MegaStyle!"\n                                                               @{" Go back.. " Link MAIN}\n\n\n                              How to contact us :\n                         ·-=>=>=>=>=>=><=<=<=<=<=<=-·\n\n\n          E-Mail : [email removed]\n\n\n          BBS    : +47-51-410397 -=- @{"Noiseless    " Link "NOISELESS"} ·oOo· Sysop : Lizard\n                   +47-33-045192 -=- @{"Genetic Waste" Link "GENETICWASTE"} ·oOo· Sysop : Magz\n                   +47-66-900578 -=- @{"Power-Rage   " Link "ETERNITY"} ·oOo· Sysop : Instant\n\n\n          Snail  : Lizard/MegaStyle+Spaceballs\n                   Boveien 81\n                   4070 Randaberg\n                   Norway\n\n\n          Phone  : +47-51-417240 -=- Between 17:00PM -> 23:00PM. Ask for Magnar!\n\n\n\n\n    -     -    -   -  - - -- --- ---- ----- ----------------------------------\n\n\n      We are very interested in new ANSI-artists and skilled /X-coders. \n     If our group sounds interesting to you, then feel free to contact us!\n\n\n--------------------------- ------ ----- ---- --- -- - -  -   -    -     -\n@ENDNODE\n\n\n\n;-------------------------------------------------------------------------------------\n\n\n\n@NODE "NOISELESS" "Propaganda : Noiseless BBS!"\n                                                               @{" Go back.. " Link "CONTACT"}\n\n                                        .\n                                           ·\n   _  _  _ _______  _____ __ _____ _____:  :   _____  _____  _____ __ _  _   _\n_   _  _ ______   ||     (__)     |   __|  |  |   __||  ___||  ____ __ _ _  _\n            |  |  ||  |  |  l  `--|  _/_|  |__|  _/_ l  ''--.l  ''--.\n            |  |  ||  |  |  |--,  |  l  |  l  |  l  ||--,  ||--,  |\n            l__|  l|_____l__l__   l__   l__   l__   |l__   ll__   l\n               `--''            `--''  `--''  `--''  `--''   `--''   `--''\n\n                           SysOp : Lizard/Spaceballs\n\n        Phone : +47-51410397, 33.6kb USRobotic Courier, 24 hours a day!\n\n@ENDNODE\n\n\n\n;-------------------------------------------------------------------------------------\n\n\n\n@NODE "GENETICWASTE" "Propaganda : Genetic-Waste BBS!"\n                                                               @{" Go back.. " Link "CONTACT"}\n\n «*»  Genetic Waste - 33.6kb v.all - Sysop : Magz - Number : +47-33-045192  «*»\n \n@ENDNODE\n\n\n\n;-------------------------------------------------------------------------------------\n\n\n\n@NODE "ETERNITY" "Propaganda : Power Rage BBS!"\n                                                               @{" Go back.. " Link "CONTACT"}\n\n «*»  Power Rage - 33.6kb v.all - Sysop : Instant - Number : +47-66-900578  «*»\n\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',7017,2,0,NULL,NULL,'mgsnodem','scan',1780048602);
INSERT INTO door_catalog VALUES('mgsnodest','MGSNODEST.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MGSNODEST.LHA','node-status','XIM','node-status',NULL,NULL,NULL,'_\_/    / _  __  ______ _______/__  ___    / | _ \  /     /  __/__/   /_ _   /   ___   / |__\ \/ /___/_____________/____/____//___/',replace(' ___     _______________________ _ _________\n_\_/    / _  __  ______ _______/__  ___    /\n| _ \  /     /  __/__/   /_ _   /   ___   /\n|__\ \/ /___/_____________/____/____//___/\n    \  /                   .------------.\n     \/  Node-Status v1.2 -÷-  styLE!   ¡\n                           `------------÷\nNice /X-door to report your BBS-activity|\nat logon. Good configurations options.  |\n -[31.O5.95]------ ---- ---------·LZD·--''\n','\n',char(10)),'_Node-Status.guide',replace('@database "Node-Status.Guide"\n@WIDTH 77\n@INDEX "MAIN"\n@NODE Main "MAIN" "Welcome to the Node-Status Documentation!"\n                                                   __.       \n______ ______________ ______ ________    _________/ _|_____/\______ _ __________\n ____ V _________   // ____/_______  \  _\  ______   _  __/  \  __/_________   /\n |   \_/   |   _/  //  \___  |   _/   \/  \___   \   |___     \ \      /  _/  /\n |    |    |  ____/_     |   |   _     /    _/   /   |   \    /  \_   /  ____/_\n |____|    |_______/_________:___\    /_________/____|_______/_______/________/\n      |____|                      \  /                       \n      :   _____                    \/\n           ____\__________\n            ____\_______  )\n                 \/     ) ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n                        ¯¯¯¯¯¯¯¯¯¯¯¯¯¯ ·g·i·v·e·s·  ·y·o·u·\n\n                                                   \n                        .-------------- -       - ---.\n                        |                          ¯7|\n                        |                            :\n                        :      NODE-STATUS v1.1      .\n                        ·\n                        ·             by\n                                                     ·\n                        ·  Magnar Harestad (Lizard)  :\n                        :·                           |\n                        |l_                          |\n                        `----- -       - ------------''\n\n\n                            Release date : 31.05.95\n\n                       @{"What is Node-Status v1.0?       " LINK "ABOUT"}   \n                       @{"Requirements to run this door   " LINK "REQUIRE"}   \n                       @{"How to install Node-Status...   " LINK "INSTALL"}   \n                       @{"Who''s done what ?               " LINK "CREDITS"}   \n                       @{"The official mGs-Greetings!     " LINK "GREETINGS"}   \n                       @{"Info about MegaStyle.           " LINK "INFO"}   \n                       @{"How to contact MEGASTyLE!       " LINK "CONTACT"}\n@ENDNODE\n\n\n\n;-------------------------------------------------------------------------------------\n\n\n\n@NODE "ABOUT" "What is Node-Status ?"\n                                                               @{" Go back.. " Link MAIN}\n\nNode-status v1.0 is a small utility to show which node you''re logged onto.\nIt also report the baudrate of the connection and the current status on each\nof the other available nodes.\n\nNode-Status can also be used to display a logo-textfile (with MCI-support)\nto the users together with the node-status report.\n\n\nThe main reason why I coded this door is that most of the doors available lacks\na good design, and do not have any textfile support.\n\nI also included a Clear-Screen argument for those who wants to get rid of that\n"modem-report" message from AmiExpress at the top of the screen.\n\n\nThe door is also in my opinion more powerful than other doors available. \nFirst of all, it has a very nice tool-type support. This is very important when\nyou want a correct node baudrate directly out from each individual node-icon. \nNo incorrect-status from the /X-port is being used for this purpose. \n\n\n\nFinally,\n\n\nThis utility is coded in Amiga-E with inline-ASM for maximal speed-performance!\n@ENDNODE\n\n\n\n;-------------------------------------------------------------------------------------\n\n\n\n@NODE "REQUIRE" "Requirements to run this door."\n                                                               @{" Go back.. " Link MAIN}\n\n\nYou will need a computer with OS 2.x, or higher, and any version of AmiExpress.\nHowever, AmiExpress v4.xx++ is preferred.\n\n\nNode-Status also requires the AEDoor.Library present in LIBS:. You can find this\nlibrary in the LIBS-directory in this package.\n\nIf this library is not present for some reason in this package, then give my\nboard a call and I''ll gladly give it to you.\n\n@ENDNODE\n\n\n\n;-------------------------------------------------------------------------------------\n\n\n\n@NODE "INSTALL" "How to do the installation..."\n                                                               @{" Go back.. " Link MAIN}\n\nAll you have to do is to copy each of the files in this archive to its\nbelonging directory under "BBS:".\n\nThat''s all... (Simple isn''t it? :)\n\n\n\nConfiguration :\n---------------\n\nThere is only one way to configurate this door, and that is through the\nNode-Status.info icon. If you, from workbench, use information on this icon,\nyou''ll see two Tooltype choices in use. These are : \n\n\nCLEAR_SCREEN=YES\nSHOW_LOGO=YES\n\n\nThese choices can be toggled by writing YES or NO. (Not case-sensitive)\n\n\nThe first one will clear the screen right after the modem-handshake is over,\nand the second one will show the textfile : "Node-status.Logo".\n\n\n* The logo-textfile must be placed in the same directory as the main-program.\n\n@ENDNODE\n\n\n\n;-------------------------------------------------------------------------------------\n\n\n\n@NODE "CREDITS" "Credits for this MEGASTYLE production:"\n                                                               @{" Go back.. " Link MAIN}\n\n\n                             The credits goes to :\n                            «=-------------------=»\n\n\n\n             Magnar Harestad, Lizard of Megastyle and Spaceballs!\n\n\n\n\n                        For doing the following things:\n                       «-------------------------------»\n\n                                    Coding\n                                   Designing\n                                 ANSI-Drawning\n                                Guide-Designing\n                             AsC²-art and designs\n                            Writing this guide-text\n\n\n\n\n(Splash, it seems like you''re not the only one doing everything by yourself! :)\n\n@ENDNODE\n\n\n\n;-------------------------------------------------------------------------------------\n\n\n\n@NODE "GREETINGS" "The Official MeGaSTyLe GrEeTiNgS:"\n                                                               @{" Go back.. " Link MAIN}\n\n   _________ \n    _______ )  ·M·e·g·a·S·t·y·l·e·  ·s·e·n·d·s·  ·g·r·e·e·t·i·n·g·  ·t·o·\n           )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n    Spaceballs, Eltech, Andromeda, CNCD, Parallax, Complex, Virtual dreams,\nStone Arts, Rebels, TRSI, Scoopex, Avalon, Aquarious, Access, Prestige, Skid Row\n\n                   And to all the other /X-coders out there!\n\n\n________ \n ______ ) ·L·i·z·a·r·d·  ·s·e·n·d·s·  ·s·p·e·c·i·a·l·  ·g·r·e·e·t·i·n·g·  ·t·o·\n       )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n       ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\nSplash  : Your SysDl looks REALLY impressive! - Nice going, m8!\nDr. Ice : Thx for all the help you have given me regarding Amiga-E.\nWoober  : Keep on doing those Asc²... But think about cOLoUrS Too!\nJedi    : Welcome to MegaStyle, m8!\nShorty  : G-shade and texturemapped vectors forever? :)\nKingpin : Thanks for the bug-report on this first beta-release!\nShade   : Still afraid of busts? ;)))))))\nRaz     : Love your intro, man. Flames rulE!\nMr.Z    : Where are you? Your lines are down... :''-(\nBaffle  : Is your board up?\nStratos : to bad that you decided to leave. No hard feelings.\nFake    : Get a decent modem, and get that board on the air!\nChris   : Nice haircut! :) And what''s up in Bergen?\n\n\nAnd a nice''n''lovelY fucking to this SHI-member :\n\nKurt H. : GO''N''HANG YOURSELF!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!! (lamEr!)\n@ENDNODE\n\n\n\n;-------------------------------------------------------------------------------------\n\n\n\n@NODE "INFO" "About MegaStyle..."\n                                                               @{" Go back.. " Link MAIN}\n\nMegastyle is a new AmiExpress-Support group formed by Lizard of Spaceballs in\nthe middle of may 1995.\n\nOur main goal is to support all the /X-boards out there with the best doors\naround. We try hard to make our products as system-friendly as possible and\nwith unique configuration possibilities.\n\n\nWe want to be the leading /X-development group in the future, and therefore\nneed more skilled coders and ANSI-artist to make our products even better!\n\n\n\nIf you''re interesting in teaming up, then take a look at the contact-info.\n\n\n\n\nThanks to the following boards for helpful beta-testing of MegaStyle-products:\n«----------------------------------------------------------------------------»\n\n                            Dr. Feelgood (Science)\n   Checkpoint (Kingpin)   -   Total Panic (Jedi)   -   Flame-Strike (Splash)\n\n@ENDNODE\n\n\n\n;-------------------------------------------------------------------------------------\n\n\n\n@NODE "CONTACT" "How to contact MegaStyle!"\n                                                               @{" Go back.. " Link MAIN}\n\n\n                              How to contact us :\n                         ·-=>=>=>=>=>=><=<=<=<=<=<=-·\n\n\n          E-Mail : [email removed]\n                   [email removed]\n\n\n          BBS    : +47-51-417240 -=- @{"Noiseless  " Link "NOISELESS"} ·oOo· Sysop : Lizard (NightBBS)\n                   +47-51-631702 -=- @{"FlameStrike" Link "FLAMESTRIKE"} ·oOo· Sysop : Splash\n                   +47-77-748689 -=- @{"Eternity   " Link "ETERNITY"} ·oOo· Sysop : Woober\n                   +47-51-575227 -=- @{"Total Panic" Link "TOTALPANIC"} ·oOo· Sysop : Jedi\n\n\n          Snail  : Lizard/MegaStyle+Spaceballs\n                   Boveien 81\n                   4070 Randaberg\n                   Norway\n\n\n          Phone  : +47-51-417240 -=- Between 17:00PM -> 23:00PM. Ask for Magnar!\n\n\n\n\n    -     -    -   -  - - -- --- ---- ----- ----------------------------------\n\n\n      We are very interested in new ANSI-artists and skilled /X-coders. \n     If our group sounds interesting to you, then feel free to contact us!\n\n\n--------------------------- ------ ----- ---- --- -- - -  -   -    -     -\n@ENDNODE\n\n\n\n;-------------------------------------------------------------------------------------\n\n\n\n@NODE "NOISELESS" "Propaganda : Noiseless BBS!"\n                                                               @{" Go back.. " Link "CONTACT"}\n\n                                        .\n                                           ·\n   _  _  _ _______  _____ __ _____ _____:  :   _____  _____  _____ __ _  _   _\n_   _  _ ______   ||     (__)     |   __|  |  |   __||  ___||  ____ __ _ _  _\n            |  |  ||  |  |  l  `--|  _/_|  |__|  _/_ l  ''--.l  ''--.\n            |  |  ||  |  |  |--,  |  l  |  l  |  l  ||--,  ||--,  |\n            l__|  l|_____l__l__   l__   l__   l__   |l__   ll__   l\n               `--''            `--''  `--''  `--''  `--''   `--''   `--''\n\n                           SysOp : Lizard/Spaceballs\n\n      Phone : +47-51417240, only available between : 23:00PM -> 07:00AM.\n\n@ENDNODE\n\n\n\n;-------------------------------------------------------------------------------------\n\n\n\n@NODE "FLAMESTRIKE" "Propaganda : Flame-Strike BBS!"\n                                                               @{" Go back.. " Link "CONTACT"}\n\n\n \n \n ____/\____:_/\ ::______/\__.:____ ____.:/\_____\n \ _      ¬:.  Y.:.        ¬\:\_  Y   / :.     / SysOp:\n  \/   _____   | _________   \/  _ _  \   l___/  Splash/ElTECH\n  /    __) /   l/  \    l¬    \   Y    \  __)__\n  \    |   \   /    \   __    /   |    /  l    \ \n   \___!    \______ /\ __l___/\___l__ /_______ / CoSys:UnMad\n==================\/==\/============\/=======\/  \nElTECH    EHQ                               ·   ..\nMegastyle WHQ      __/\_____:__/\__:_/\____ :   ·:_/| /\.:/\______\n                   \       ¬:.     ¬:   _  \¦   :   |/  \:.      /\nRunning on:         \  l_______  ____ __/  /|   ¦   l  _/   l___/\nA4ooo/o3o/25Mhz   __/\__ ¬\  /   Y /  \    \|   |   _   \_  __)__\n                  \    l   \/    |/   |\    /   |   \    /  l   ¬\\nUSRobotics HST DS  \______ /\ ___l\___l \  /¦   ¦___l\  /_______ /\n                   ======\/==\/==========\/=:   :=====\/=======\/\n                                            `---''\n                         Call +47 51631702 \n \n@ENDNODE\n\n\n\n;-------------------------------------------------------------------------------------\n\n\n\n@NODE "ETERNITY" "Propaganda : Eternity BBS!"\n                                                               @{" Go back.. " Link "CONTACT"}\n\n                                                               ._____.\n  _____________________________________________________________:__ ._|__\n  \__ _____/___   _   / _____/______  \_   .  _/______ /     _   / |   /\n   /  ___/   /     \_/ ___/    /  _/  _/   |    \    \/¬\     \_/    _/\n  /_________/_______\_________/___\     \__|     \_______\_____\_____|\n                               -cDr\_____\ l______\\n.                                                                       .\n+-÷aMiGA ^ aSCiI ^ mODUlES ^ hACKErS lAnD ^ /X sUPpORT ^ pUBLiC dOMAiN÷-+\n:           [f]EATURING: A1200/020 ^ oNE (n)oDE (14k4 mAXLiTE)          :\n|          [m]ANAGEMENT: [w@@ßE®^tHg^nEo^mGs^bDz]-[SiENCE^tHg]          |\n!   tECHNOLOGY [nHq] · nEO [nHq] · mEGASTYLE [hQ] · bANANa dEZIGn [hQ]  !\n+÷---------------------------------------------------------------------÷+\n:                   [n]UMBER: +47-777-48689 [23 - 07]                   :\n`÷---------------------------------------------------------------------÷''\n\n@ENDNODE\n\n\n\n;-------------------------------------------------------------------------------------\n\n\n\n@NODE "TOTALPANIC" "Propaganda : Total Panic BBS!"\n                                                               @{" Go back.. " Link "CONTACT"}\n\n «*»  Total Panic - 28.8kb v.all - Sysop : Jedi - Number : +47-51-575227  «*»\n\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',21172,2,0,NULL,NULL,'mgsnodest','scan',1780048602);
INSERT INTO door_catalog VALUES('mgssysdl','MGSSYSDL.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MGSSYSDL.LHA','sysdl','XIM','sysdl',NULL,'Splash',NULL,'_\_/    / _  __  ______ _______/__  ___    / | _ \  /     /  __/__/   /_ _   /   ___   / |__\ \/ /___/_____________/____/____//___/',replace(' ___     _______________________ _ _________\n_\_/    / _  __  ______ _______/__  ___    /\n| _ \  /     /  __/__/   /_ _   /   ___   /\n|__\ \/ /___/_____________/____/____//___/\n    \  /                   .------------.\n     \/ SysDL 3.3      «-- ÷-  styLE!   ¡\n                 By Splash `------------÷\n Now with remote mode that works like   |\n DOPUS!! THE BEST SYSDL DOOR EVER MADE! |\n -[17.07.96]------ ---- ---------·st!·--''\n [           VIRUS REMOVED!             ]\n','\n',char(10)),'SysDL33.Guide',replace('@database "SysDL.Guide"\n@WIDTH 77\n@NODE Main "Welcome to SysopDL Documentation"\n                                                   __.       \n______ ______________ ______ ________    _________/ _|_____/\______ _ __________\n ____ V _________   // ____/_______  \  _\  ______   _  __/  \  __/_________   /\n |   \_/   |   _/  //  \___  |   _/   \/  \___   \   |___     \ \      /  _/  /\n |    |    |  ____/_     |   |   _     /    _/   /   |   \    /  \_   /  ____/_\n |____|    |_______/_________:___\    /_________/____|_______/_______/________/\n      |____|                      \  /                       \n      :   _____                    \/\n           ____\__________\n            ____\_______  )\n                 \/     ) ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n                        ¯¯¯¯¯¯¯¯¯¯¯¯¯¯ ·g·i·v·e·s·  ·y·o·u·\n\n\n          @@@@@*5W@@@WsW@@!********************!@@@@@@@WmZ**]@@@@[@@@@@@\n          5    ,@@@@@@@@@@                      @@@@@@@@@@s ]@@@@[     P   \n          9    ]@@@P  V@@@ ______,___.  ___.,__  @@@@  M@@@. ]@@@[     r \n          ''    ]@@@b   *** @@@@@@]@@@[i@@@@@W@@  @@@@  ]@@@b ]@@@[     e \n          r    ''@@@@Ws.    M@@@@*!M@@!@@@P ''M@@  @@@@  ]@@@W ]@@@[     a \n          e     ''M@@@@@Ws   M@@@b d@! @@@@s.''~~  @@@@  ]@@@@ ]@@@[     c \n          h       ''VM@@@@W  !@@@@_@A  !@@@@@W_   @@@@  ]@@@@ ]@@@[     h \n          c    ,__.  V@@@@[  M@@@@@!   ''*@@@@@W  @@@@  ]@@@D ]@@@[     e \n          a    ]@@b   @@@@[  !@@@@A   __. ~M@@@[ @@@@  d@@@! ]@@@[     r \n          e    ]@@@WmW@@@@!   M@@@!   @@W. d@@@[m@@@@mm@@@A iW@@@Wi    '' \n          r    ]@@A@@@@@@f    !@@A    @@A@@@@@A @@@@@@@@@f  ]@@@@@[    9 \n          P    2XX__XXXX______g@@L____XXL2XXXL__XXXXXXXL____2XXXXXL    5   \n          ~~~~~~~~~~~~~~~~~~~T@A~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                            ,@A`Sysop Download 3.3 (17/07-96)\n\n                         \n \n                           By Splash/ElTECH^MEGASTYLE\n              \n                          @{"What is Sysop Download ?  " LINK "ABOUT"}   \n                          @{"What is new in v3.3 ?     " LINK "NEW"}\n                          @{"Requirements.             " LINK "REQ"}                \n                          @{"Features.                 " LINK "FEATURES"}               \n                          @{"Installation.             " LINK "INSTA"}              \n                          @{"How to operate.           " LINK "USE"}              \n                          @{"Future Upgrades           " LINK "FUTURE"}\n                          @{"Credits                   " LINK "CREDS"}\n                          @{"Greetings.                " LINK "GREET"}                 \n                          @{"About Megastyle.          " LINK "MEGASTYLE"}\n                          @{"How to contact the Author " LINK "HOWTOCONTACT"}\n              \n@ENDNODE\n\n\n\n\n\n\n\n\n\n\n@NODE "ABOUT" "What is Sysop Download ?"\n                                                               \n _________ \n  _______ )·A·b·o·u·t·\n         )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n         ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\nSysop DL is a door for all sysops that have lots of users who ask to download\nspecific files... Imagine how hard it is to pack the files and then upload it to \nyour board so that the user can download it..... But now..... The hard work is \nover......  \nJust have a look at these great @{"features" LINK "FEATURES"} \n@ENDNODE\n\n@NODE "REQ" "Requirements."                                                        \n                                                               \n _________ \n  _______ )·R·e·q·u·i·r·e·m·e·n·t·s·\n         )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n         ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n\nA Commodore Amiga computer (Pese suxx :-), /X (I guess any version will do...) \n\nFor this door to work you should also have:\nreqtools.library and AEDoor.library in your LIBS:\n\nIf U want to use the lha packing feature, U must have lha in your path !\nA good place to have it is in C:\n\n\nIf you by any chance should have problems getting this door working, \nthen @{"contact me !" LINK "HOWTOCONTACT"}\n@ENDNODE\n\n@NODE "FEATURES" "Features."\n                                                               \n _________ \n  _______ )·F·e·a·t·u·r·e·s·\n         )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n         ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n                               \n\n* Fileselector for sysop to choose files from. \n\n* Online lha crunching (automatic if a directory is selected)  \n\n* Also includes a @{"remote" LINK "DOPUS"} function (With PW protection) for \ncosysops.\n\n* You can now @{"restrict" LINK "RESTRICT"} different files/dirs from being \ndownloaded, by putting\n  these entries i a file called restrict located in the same dir as this door.  \n\n* This door can now by any time (almost) be exited by pressing Ctrl+c.\n\n* 100% security!\n\n* @{"DOPUS MODE" LINK "DOPUS"} in REMOTE mode!\n@ENDNODE\n\n@NODE "INSTA" "Installation."\n                                                               \n _________ \n  _______ )·I·n·s·t·a·l·l·a·t·i·o·n·\n         )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n         ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n\n                             \nJust copy the included files to the correct dirs, that''s it.... \nThe configuration can be found in the SysDL.info. Here you can choose the temp\ndir for lha crunching (The lha file will ofcoz be deleted after the transfer)\nThe PASSWORD= tooltype contains the password to use if a user is not on the \nremote list.\n\n\nHow to give users axx to remote mode:\nUSER.X=Username (Where x is a number)\n(This is not needed for the sysop who has automaticly access to this...)\nFor example like this:\nUSER.1=Preacher\nUSER.2=UnMad\n\nThe username is ofcoz NOT CASE SENSITIVE.\n\nCouldn''t be more simple.... (I think)\n@ENDNODE\n\n@NODE "USE" "How to operate."\n                                                               \n _________ \n  _______ )·H·o·w· ·t·o· ·o·p·e·r·a·t·e·\n         )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n         ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n                              \n\nWhen you first start the door U will be asked if U want to use the @{"REMOTE" \nLINK "DOPUS"} \nfunction. This function is included for cosysops etc. ,so if you are local\n(In front of your computer :-) U should NOT use this. I''ll explain the \ndifference between the two modes:\n\n@{i}@{"REMOTE" LINK "DOPUS"}@{ui}\n------\n\n@{i}FILESELECTOR@{ui}\n------------\nIf U select Continue from the first prompt, A Nice filerequester will pop up,\nand u can select your files or dirs. But before popping up it will check if the \nnodex screen is active, to see if the sysop is around. If not the requester will \nNOT pop up.  \nWhen U are finished, just press OK!, \nand on U go! U are then asked if U would like to Pack the files. If U want that \nthen select Pack, else select Continue.... (or Quit)\n@ENDNODE\n\n@NODE "FUTURE" "Future Upgrades"\n                                                               \n _________ \n  _______ )  ·F·u·T·u·R·e· ·P·l·A·n·S· \n         )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n         ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\nI have worked VERY hard and for a long time to make this door as good as \npossible, and I have received much response from people telling me how gr8 this\ndoor is. This gives me much inspiration for further developing. Thank you all for\nthe support!\n\nThis is the first update of SysDL for over a year! I have had VERY little time \nfor coding because of my year in the army, but finally; now I''m back in bizz!\nWith a lot of inspiration a and urge to keep develop both this and other doors.\n\nI can''t see that there is much missing in this door (some minor features only)\nso if YOU miss anything please @{"contact me !" LINK "HOWTOCONTACT"}\n\n@endnode\n@node "HowToContact"\n\n \nHow to contact me:\n\nMy BBS is offline at the moment, but will be up in a couple of weeks, probably\non another number so look out for it or ask around.\n\n\nE-Mail:[email removed]\n\nWWW: http://www.netpower.no/~jthorsen/\n\nOr snailmail: Splash/Megastyle\n              Lindeveien 69\n              N-4300 Sandnes\n              Norway\n@ENDNODE\n\n@NODE "CREDS" "Credits."\n                                                               \n _________ \n  _______ )  ·C·r·E·d·I·T·s·\n         )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n         ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\nCode,Idea    - Splash/ElT^MGS\nDoor Design  - Shade (Standard dezign) and Baffle! (REMOTE dezign)\nGuide Design - Splash/ElT^MGS (Stole some from Lizard though)\nSysDL ASCII  - Logo used in this guide by Preacher/Bizarre interactive Dezigns \n\n@ENDNODE\n@NODE "GREET" "Greetings."\n                                                               \n _________ \n  _______ )  ·G·r·E·e·T·i·N·g·S·\n         )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n         ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n                                  \n\n                         Greetings to all my friends ! \n\nLizard      : Hope you get settled soon!\n\nDr.ICE      : For always being there when I need some help with my coding.\n              And for giving me Bug-Reports\n\nThunderCat  : For encouraging me and giving me Bug-Reports           \n\nSkinner     : Get yourself connected to THE NET!\n\nMic Flair   : Great talking to you on IRC, much more easy using the NET than\n              calling all the way to Norway heh ? :-) \n\nTHEGODFATHER: You spend all your time on IRC too! :-)\n\n\n+all on #amielite: Hope you like this door!\n\nAND OFCOURSE ALL MEMBERS OF :\n______ ______________ ______ ________    _________/ _|_____/\______ _ __________\n ____ V _________   // ____/_______  \  _\  ______   _  __/  \  __/_________   /\n |   \_/   |   _/  //  \__   |   _/   \/  \___   \   |___     \ \      /  _/  /\n |    |    |  ____/_     |   |   _     /    _/   /   |   \    /  \_   /  ____/_\n |____|    |_______/_________:___\    /_________/____|_______/_______/________/\n      |____|                      \  /                       \n      :    :                       \/\n\n                                   AnD\n\n             _______ /|   _______/\_______________    _____ \n            /~ ____// | __\___  ~__~/  _____/~   ~\  /~ ¡ ~\.  \n           //  __)_// |/ ~\  /  :| //  __) //   .__)//  |  \\\\n           \\     ~\\ ~   \\/   || \\     ~\\   : \\\\      / \  \n            \  ____/\______/\____|  \  ____/\____ // \. |__/  /\n             \/ .____/\______/\_____|\/ .TeTSUo__\/ / \/ ____/\n              \/                      \/          \/   \/ \n\n@ENDNODE\n@NODE "DOPUS" "How to use the REMOTE mode."\n                                                               \n _________ \n  _______ )  ·R·e·M·o·T·e ·M·o·D·e··\n         )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n         ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\nUsers not specified in the sysdl.info will need to enter a password to get axx \nto this feature (sysop&users specified in sysdl.info will automaticly get ax to \nthis ofcoz...)\n\nWhen entering this mode U can select files/dirs by using the cursor keys.\nU can select as many items as U like. Pressing any char will make the cursor \njump\nto the first entry starting with that char. (Just as in DOPUS!)\n\nWhen U are finished, just pressing return, or pressing Ctrl+G will bring up a \nrequest of what U want to do. \n\nU can select between: Pack,Continue,Quit...\n\n*Pack will let you LHA pack your files before downloading.\n*Continue will download the files without packing.\n*Quit will Quit the door (Wow !)\n\nPressing Ctrl+P from within REMOTE mode, will let you start packing your files\ndirectly.\n\nHave a look at @{"RESTRICTING FILES" LINK "RESTRICT"}\n@ENDNODE\n@NODE "NEW" "What has changes in v3.3 ?"\n   _________ \n    _______ )  ·W·h·a·t· ·I·s· ·N·e·w·?·\n           )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n* Changed the ANSI commands a bit for compablility with DayDream BBS\n\n* Added possibility to restrict files on both username and access-level\n\n* Changed some minor output bugs\n\nNot VERY much new things in this version as you can see, it is more just to tell\neverybody that this project is not dead (and neither is MGS!) and that I am back \nfrom the army and KICKING like never before!\n\n@ENDNODE\n@NODE "MEGASTYLE" "About Megastyle"\n                                                               \n   _________ \n    _______ )  ·A·b·o·u·t ·M·e·g·a·s·t·y·l·e\n           )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\nMegastyle is a AmiExpress-Support group formed by Lizard in the middle of may \n1995.\n\nOur main goal is to support all the /X-boards out there with the best doors\naround. We try hard to make our products as system-friendly as possible and\nwith unique configuration possibilities.\n\n\nWe want to be the leading /X-development group in the future, and therefore\nneed more skilled coders and ANSI-artist to make our products even better!\n\nIf you''re interested in teaming up, then take a look at the contact-info.\n\n\n\n   _________ \n    _______ )  ·M·e·g·a·S·t·y·l·e·  ·P·r·o·d·u·c·t·i·o·n·s·\n           )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n\n@{i}Splash:@{ui}\n\nAutoreward   v1.3\nGlobalDupe   v1.5\nSysDL        v3.3\nMega-Chatter v1.1\n\n\n@{i}Lizard:@{ui}\n\nBulls        v1.5\nNodeStatus   v1.2\nLog-Shrink   v1.0\nNode-Message v1.0\nUser-Status  v1.0\nZippy-Search v1.0\n\n\n@{i}Magz:@{ui}\n\nmagzlistmanager v1.0\nMgzDirX         v1.0\nWALLHALL        v1.0\nCURSELAST       v0.6\n\nAll these doors are just GREAT so check''em out! And more releases to come in \nnear \nfuture!\n\n\n   _________ \n    _______ )  ·M·e·g·a·S·t·y·l·e·  ·H·o·M·e·P·a·G·e\n           )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n            http://www.netpower.no/~jthorsen/mgs.html \n\n\nCheck it out!\nSoon you will find all MGS! doors there!\n\n@ENDNODE\n@NODE "RESTRICT" "Restricting files/dirs"\n                                                               \n   _________ \n    _______ )·R·e·s·t·r·i·c·t·i·n·g ·F·i·l·e·s·\n           )¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\nIf you like you can put a file called ''restrict'' in the same path as this door.\nIn this txt file you can enter the files/dirs you don''t want the user to have axx\nto. You only have to write a part of an entry you want to restrict.\nFor example ''Sources'' will restrict both ''main:sources'' and ''boot:store/sources''.  \n\n1.This door will first look for a file called "restrict."+username, this way you \n  can have special restrictions for EACH user if you like...\n\n2.If it can not find "restrict."+username it will look for "restrict."+axxlevel,\n  for example "restrict.50". This way you can have a restriction for all users \n  with axx level 50.\n \n3.If it can''t find neither of the above it will look for "restrict", and if this\n  is not found there will not apply any restrictions!\n\nUsing this smart system you could fexs have a file called "restrict" to restrict\nfiles from all the users, but if you want a special user to have more axx, then \njust make an empty (if you don''t want ANY restrictions on him) file called \n"restrict."+his username and he will get other restriction than the others.\nThe same goes for "restrict."+axxlevel.\n\n\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',25892,1,0,NULL,NULL,'mgssysdl','scan',1780048602);
