INSERT INTO door_catalog VALUES('mgswall','MGSWALL.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MGSWALL.LHA',NULL,'XIM','__________   ___________     _____',NULL,NULL,NULL,'____\        /___\   ____  /____/ ___/______ _     \l      _  \_______ ____\/       __l_________  __l__       l ___',replace('    __________   ___________     _____\n____\        /___\   ____  /____/ ___/______\n               _     \l      _  \_______\n____\/       __l_________  __l__       l ___\ng®m /________)   e^D \_____)   (_________)\n          «« m e g a s t y l e  »»\n              ...presents...\n \n              WALLHALL 1.o!!\n \n» THE ULTIMATE WALL AND LOGOFF DOOR FOR /X «\n','\n',char(10)),'Wallhall.GUIDE',replace('@database "mEGAZTYLE.guide"\n@node MAIN\n@title "                                              »«  m e g a s t y l e  »«  r u l e s  »«"\n@{b}\n                              @{u}m e g a s t y l e@{uu}\n\n                 ________   _________   _________     ______.\n           ______\      /___\  ___  /___\  ___  /_____\____ l____\n     ______\              _     l/    _    \l     _     __/     /_______\n.___(       \____\/     __l__  _______l_______  __l__   \l_____/        )___.\n|                /______)   (_____/        \____)   (____\                  |\n|                                                                           |\n| g®m      _____      ___.           .______   ___.       _________     e^D |\n|___  ____/ ___/______\  l___________|     /___\ _l_______\  ___  /____  ___|\n   (__\   \______   _    __/     _   l       _   \      _     l/      /__)\n       \__      l __l__  l     __l_______  __l_        _l_  _________/\n         (________)   (________)     \_____)  (________) (_____/ @{ub}\n\n\n\n@{fg shine}                  p r e s e n t s   a   n e w   d o o r :@{fg text}\n\n\n                       @{b}    @{bg shine}@{u}w a l l h a l l   1 . o@{bg back}@{ub}@{uu}\n\n\n\n\n              @{"           d o c u m e n t a t i o n           " link index}\n\n\n\n\n@endnode\n\n@node index\n@title "                                             »» i n d e x ««"\n\n\n    @{u}                                                          @{uu}\n\n\n@{b}                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n         ____        __________          ____.   ___________   ½½½½½  ½½½½½\n________(___/________\ __     /__________\___l___\  ____   /__    `½½½½''\n                   _   l/       _      _____/  _      l/      ½½½½½½  ½½½½½½\n_____            __l___/      __l__    l     __l__  __________½½½½½½  ½½½½½½\n    (____________)    /_______)   (__________)   (_____/      ½½½½½½  ½½½½½½\n                                                              ½½½½½½  ½½½½½½\n                                                              ½½½½½½  ½½½½½½\n   @{fg shine} @{"            introduction             "  link introduction      }    @{fg text}                ½½½½½½  ½½½½½½\n@{fg shine}    @{"            installation             "  link installation      }          @{fg text}          ½½½½½½  ½½½½½½\n@{fg shine}    @{"              how 2 use              "  link how 2 use         }\n    @{"              copyright              "  link copyright         }\n    @{"          changes ÷ history          " link changes ÷ history  } @{ub} @{fg text}\n\n\n    @{u}                                                          @{uu}\n\n\n@endnode\n\n\n\n\n\n\n\n\n@node introduction\n                                                                 .\n\n                                                                 :\n                                                                 :\n             __________________.______.      ________            :\n          ._(___)_.   ___     _|      l_____\\_     /____________:_ _\n          |       |----/      \        /     \   __/\      __    :\n          l_______|   /_______/        |-----/_______\____       :\n                              l________|(rLf)            /-------:-\n                                                                 :\n                                                                 :\n                                                                 :\n                                                                 .\n\n\n  @{fg shine} Wallhall @{fg text}is a excellent (hehe) wall for /X, s!x and all compatibles.\n             Check out the gr8 screenshots before installing!\n       The things that makes this wall differ from other walls are:\n\n                      » Up to @{fg shine}1ooo@{fg text} lines with tags! «\n                       » Scrollable with cursors! «\n                    » Can be used as "@{fg shine}G@{fg text}" command(!!) «\n                    » Gr8 design by Magz & Grimlock! «\n\n                           UNREGISTERED VERSION!\n\n           TO RECEIVE A REGISTERED VERSION WITH YOUR BOARD NAME\n                ON, JUST D!AL @{fg shine}GENETIC WASTE@{fg text} - +47-33o45192\n                 AND UPLOAD A SMALL FILE AND ASK FOR ONE.\n\n  \n                            -magz of megastyle-\n\n@endnode\n\n\n\n\n\n\n@node installation\n\n .\n                                                                              .\n :\n :                                                                            :\n : __        _____ .___.   ______ __.              _________. ____________    :\n_:(__)_______\_ _/_|_  l___\__  // _l______.  _____\__  //  l____)_  _   /____:_\n :    | __    /_  _ /   /     _ // \     /_l__\__     _ //   /    |_    / ___ :\n_:____|--/   /-/  //    |--/____/----/__/ \     /--/____/    |____|/---/\--/  :\n :      /___/ /___/_____|(rLf)          \---/__/       l_____|            /___:_\n :                                                                            :\n :                        i n s t a l l a t i o n                             :\n .                                                                            :\n                                                                              .\n\n@{fg shine}To install...@{fg text}\n\n\nWell, @{fg shine}Wallhall@{fg text} can be used either as a normal wall, or as a\nreplacement for the "@{fg shine}G@{fg text}" command in /X.\n\n@{u}To install it as a logoff-replacement (recomended) :) :@{uu}\n\nCopy The G.INFO file from the Commands/SYSCmd/ path to your matching\npath. Then copy all the files in Doors/ to your DOORS:.\n\nEdit the "doors:-mGs!-wALLhALL/wallhall.info" icon to suit your needs:\n\nLINES=<lines>   (Where lines can be anything below 1ooo) This tooltype\n                Decides how many tags the users will be able to scan through\n                with their cursor-keys. Around 1oo is recommended for speed.\n\nTAGS=<tags>     Is the number of tags the user should be able to enter on the\n                wall each time he/she :) logs off. \n\n\n\n\n@{u}To install it as a "normal" wall (recomended too) :) :@{uu}\n\nCopy The wall.INFO file from the Commands/BBSCmd/ path to your matching\npath. Then copy all the files in Doors/ to your DOORS:.\n\nEdit the "doors:-mGs!-wALLhALL/wallhall.info" icon to suit your needs:\n\nLINES=<lines>   (Where lines can be anything below 1ooo) This tooltype\n                Decides how many tags the users will be able to scan through\n                with their cursor-keys. Around 1oo is recommended for speed.\n\nTAGS=<tags>     Is the number of tags the user should be able to enter on the\n                wall each time he/she :) uses the wall. \n\n\n\n\n@{u}ofcoz you can install it as both :) @{uu}\n\n\n\n@endnode\n\n\n\n\n\n@node how 2 use\n@title "                                              )>» h o w  2  u s e «<("\n\n                                      ½½½½½½½½½½½½½½½½½½½½½½½.\n                                     ½½½½½½½½         ½½½½½½½½\n      ____.            _________         _______      ½½½½½½½½\n   ___\ __l____________\       /_________\     /______½½½½½½½½\n   \    \___        _             _      /\           ½½½½½½½½\n    \______/      __l__    "    __l__           ___   ½½½½½½½½\n          /_______)   (_________)   (___________) /_  ½½½½½½½½\n                                                   |  ½½½½½½½½\n                ½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½''\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½      ._____      _____    |   _|________\n                ½½½½½½½½______|    /_____/ ___/____|___\  ____  /___\n                ½½½½½½½½      |       _  \_______   _       l/     /\n                ½½½½½½½½__    l     __l__       l __l__  _________/\n                ½½½½½½½½ (__________)   (_________)|  (____/\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½  @{fg shine}   h o w       u s e  @{fg text}   |  ½½½½½½½½\n                ½½½½½½½½      @{fg shine}       2    @{fg text}         |  ½½½½½½½½\n                ½½½½½½½½                           |  ½½½½½½½½\n                ½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½\n\n\n\n     Just @{"Install" link installation} it and run it from /X or S!X.\n          Check out the help screen on the wall to get more info.\n                              Should be NP :)\n\n\n                                  Woyaya!\n\n@endnode\n\n\n\n\n\n\n@node copyright\n            .\n\n            :\n            :                                      ________ _______ _  _\n           _:__________  _________________ ________\__   _//\n            :      ___/__\__    __      /\\\ __      /___ /       .\n