      finished. YES!!!\n\n3o.o3.96                Version 1.oß is a bit modified and made version @{fg shine}1.o@{fg text} and\n                        released public.\n\n@endnode\n','\n',char(10)),NULL,NULL,41126,6,0,NULL,NULL,NULL,'scan',1780048602);
INSERT INTO door_catalog VALUES('mgszippy','MGSZIPPY.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MGSZIPPY.LHA','zippy-search','XIM','zippy-search',NULL,NULL,NULL,'____\        /___\   ____  /____/ ___/______ _     \l      _  \_______ ____\/       __l_________  __l__       l ___',replace('    __________   ___________     _____\n____\        /___\   ____  /____/ ___/______\n               _     \l      _  \_______\n____\/       __l_________  __l__       l ___\ng®m /________)   e^D \_____)   (_________)\n          «« m e g a s t y l e  »»\n               ...presents...\n \n             Zippy-Search v1.o.\n \nNEW and IMPROVED Search-Utility for /X & S!X\n','\n',char(10)),'Zippy-Search.GUIDE',replace('@database "mEGAZTYLE.guide"\n@node MAIN\n@title "                                              »«  m e g a s t y l e  »«  r u l e s  »«"\n@{b}\n                              @{u}m e g a s t y l e@{uu}\n\n                 ________   _________   _________     ______.\n           ______\      /___\  ___  /___\  ___  /_____\____ l____\n     ______\              _     l/    _    \l     _     __/     /_______\n.___(       \____\/     __l__  _______l_______  __l__   \l_____/        )___.\n|                /______)   (_____/        \____)   (____\                  |\n|                                                                           |\n| g®m      _____      ___.           .______   ___.       _________     e^D |\n|___  ____/ ___/______\  l___________|     /___\ _l_______\  ___  /____  ___|\n   (__\   \______   _    __/     _   l       _   \      _     l/      /__)\n       \__      l __l__  l     __l_______  __l_        _l_  _________/\n         (________)   (________)     \_____)  (________) (_____/ @{ub}\n\n\n\n@{fg shine}                  p r e s e n t s   a   n e w   d o o r :@{fg text}\n\n\n                   @{b}    @{bg shine}@{u}Z i p p y - S e a r c h    1 . o@{bg back}@{ub}@{uu}\n\n\n\n\n              @{"           d o c u m e n t a t i o n           " link index}\n\n\n\n\n@endnode\n\n@node index\n@title "                                             »» i n d e x ««"\n\n\n    @{u}                                                          @{uu}\n\n\n@{b}                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n                                                               ½½½½½  ½½½½½\n         ____        __________          ____.   ___________   ½½½½½  ½½½½½\n________(___/________\ __     /__________\___l___\  ____   /__    `½½½½''\n                   _   l/       _      _____/  _      l/      ½½½½½½  ½½½½½½\n_____            __l___/      __l__    l     __l__  __________½½½½½½  ½½½½½½\n    (____________)    /_______)   (__________)   (_____/      ½½½½½½  ½½½½½½\n                                                              ½½½½½½  ½½½½½½\n                                                              ½½½½½½  ½½½½½½\n   @{fg shine} @{"            introduction             "  link introduction      }    @{fg text}                ½½½½½½  ½½½½½½\n@{fg shine}    @{"            installation             "  link installation      }          @{fg text}          ½½½½½½  ½½½½½½\n@{fg shine}    @{"              how 2 use              "  link how 2 use         }\n    @{"              copyright              "  link copyright         }\n    @{"          changes ÷ history          " link changes ÷ history  } @{ub} @{fg text}\n\n\n    @{u}                                                          @{uu}\n\n\n@endnode\n\n\n\n\n\n\n\n\n@node introduction\n                                                                 .\n\n                                                                 :\n                                                                 :\n             __________________.______.      ________            :\n          ._(___)_.   ___     _|      l_____\\_     /____________:_ _\n          |       |----/      \        /     \   __/\      __    :\n          l_______|   /_______/        |-----/_______\____       :\n                              l________|(rLf)            /-------:-\n                                                                 :\n                                                                 :\n                                                                 :\n                                                                 .\n\n\n@{fg shine} Zippy-Search @{fg text}is probably the most used searchtool for /X and S!X.\n However, most of the searchers previously released have not support for large\n dirlists, or more than 10 conference Dir(nr) files containing your File_id`s.\n\n   I think of this door as one of the FASTEST ever for the /X or S!X, and it\n    also includes many new features NEVER been used in earlier Z-versions.\n               Just check out the screenshots before installing!\n\n\n A especially thanks to Kingpin/Spaceballs for the nice Beta-testing and good\n           support + design ideas! - I hope you enjoy the result! :)\n\n\n       The things that makes this Zippy differ from other searchers are:\n    <«-------------------------------------------------------------------»>\n\n       «»          Simple and easy interface toward the user          «»\n       «»     Logical analyze of arguments provided to the door.      «»\n       «»     Highly OPTIMIZED Assembler search-routines! (FAST!)     «»\n       «»   The best Error-trap system ever made to a AmiX/S!X door   «»\n       «»   Fully compatible with older versions of Zippy-Searchers   «»\n\n\n           - - - --- ------[ lizard of megastyle! ]------ --- - -  -\n\n@endnode\n\n\n\n\n\n\n@node installation\n\n .\n                                                                              .\n :\n :                                                                            :\n : __        _____ .___.   ______ __.              _________. ____________    :\n_:(__)_______\_ _/_|_  l___\__  // _l______.  _____\__  //  l____)_  _   /____:_\n :    | __    /_  _ /   /     _ // \     /_l__\__     _ //   /    |_    / ___ :\n_:____|--/   /-/  //    |--/____/----/__/ \     /--/____/    |____|/---/\--/  :\n :      /___/ /___/_____|(rLf)          \---/__/       l_____|            /___:_\n :                                                                            :\n :                        i n s t a l l a t i o n                             :\n .                                                                            :\n                                                                              .\n\n@{fg shine}To install...@{fg text}\n\n Well, it''s very simple to install. Just copy the directory-structure as it is\n presented in its original archive into your BBS: assignment.\n\n\n Megastyle! is not to held responsible if this program should cause any damage\n to your computer or lead to loss of data. It is provided as is, and is being\n installed and used on your own risk. There is no installer-script provided\n together with the UNREGISTERED versions of the Megastyle! productions!\n\n\n@endnode\n\n\n\n\n\n@node how 2 use\n@title "                                              )>» h o w  2  u s e «<("\n\n                                      ½½½½½½½½½½½½½½½½½½½½½½½.\n                                     ½½½½½½½½         ½½½½½½½½\n      ____.            _________         _______      ½½½½½½½½\n   ___\ __l____________\       /_________\     /______½½½½½½½½\n   \    \___        _             _      /\           ½½½½½½½½\n    \______/      __l__    "    __l__           ___   ½½½½½½½½\n          /_______)   (_________)   (___________) /_  ½½½½½½½½\n                                                   |  ½½½½½½½½\n                ½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½''\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½      ._____      _____    |   _|________\n                ½½½½½½½½______|    /_____/ ___/____|___\  ____  /___\n                ½½½½½½½½      |       _  \_______   _       l/     /\n                ½½½½½½½½__    l     __l__       l __l__  _________/\n                ½½½½½½½½ (__________)   (_________)|  (____/\n                ½½½½½½½½                           |    |\n                ½½½½½½½½                           |    |\n                ½½½½½½½½  @{fg shine}   h o w       u s e  @{fg text}   |  ½½½½½½½½\n                ½½½½½½½½      @{fg shine}       2    @{fg text}         |  ½½½½½½½½\n                ½½½½½½½½                           |  ½½½½½½½½\n                ½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½½\n\n\n\n     Just @{"Install" link installation} it and run it from /X or S!X.\n\n  Then you can type "Z HELP" or "Z ?" if you should ever wonder how it works.\n\n\n\n\n                         About the Dirlist operators :\n             <«=-----------------------------------------------»>\n\n \n  You may use any of these syntax : 1,2,3-6,u,a \n\n  A = ALL directories. When encountered this letter in a dirlist, all dirs will\n      automaticly be searched through. Even if you have specified dirnr infront\n      of this argument.\n\n  U = Upload dir. Usually the last directory of your conference DirX structure.\n\n  , = Seperator. Used to choose multiple dirnr. to check through. 1,2,3,4..etc.\n\n  - = Mark dirs. Handy when you wish to search through dirs 1 => 7.. "1-7" will\n      then be the correct syntax. Can be combined with seperator. \n\n\n      For instant : Z 1,4-7,12-22 my-search-words..\n\n      (or like this: Z my-search-words.. 1,4-7,12-22 ... The same thing! :)\n\n\n\n\n\n                       About the Searchlist operators :\n             <«=----------------------------------------------»>\n\n  You may use any of these syntax : &, !, / \n\n  & = logic AND of searchwords. For instant, you wish to find a file_id which\n      contains both the word "Amiga_News" AND "#14" ... Then you can simply\n      write : Z a Amiga_news & #14   ... and you would skip all the other files\n      that doesn''t have BOTH these words in the File_id... VERY useful when\n      searching for a specified disk-nr. in a diskset for a program.\n\n  ! = logic NOT. This is used the same way as the &, but often combined with\n      the & operator. Example : Z a Amiga_news &! #14 ! Lizard\n\n  / = Is used to find a file_id with none of the above operators involved.\n      For instant : Z a lizard & instant / magz\n\n      This would lead to a search after the two words "lizard" AND "instant",\n      or a file_id with only the word "magz" in.  \n\n\n\n  REMEMBER : The search-string is NON-CASE-SENSITIVE... To easy your pain! :)\n\n\n\n  The Searchlist options will ONLY be available in the REGISTERED versions. \n    Do consider to register your door. You''ll then be able to recieve the \n                           future upgrades for FREE.\n\n\n@endnode\n\n\n\n\n\n\n@node copyright\n            .\n\n            :\n            :                                      ________ _______ _  _\n           _:__________  _________________ ________\__   _//\n            :      ___/__\__    __      /\\\ __      /___ /       .\n          _ :_ ____        /___        /     \______/   /_________:_ _\n            :     /-------/ __/-------/\______|        ___________|\n            :     _________(___)__________    ________/       /   l_\n           _:____\\_     /       |    ___/____\__   _        /     /\n            :     \   __/\_______|   /_         /---/       /      |\n         - -:-----/_______\(rLf) \----/________/   /_______/_______|\n            :\n            :                 c o p y r i g h t\n            :\n            .\n\n\n\n                                 ---[%]---\n\n                    Zippy-Search is a Megastyle! production\n\n               Code, idea & design by   Lizard of TBL MGS!\n               Error-logo by            Magz of GRT MGS!\n               Tooltype read code by    Lizard of TBL MGS!\n\n\n              \n\n                         Creds for this GUIDE file\n\n               Slapped together by      Lizard\n               Asciis by                Relief   of T! MGS! 5D\n                                        Grimlock of GRT E^D MGS!\n\n                                 ---[%]---\n\n\n\n                      Megastyle! does now consist of\n \n               Leader . . . . . . . . . Lizard\n               Code . . . . . . . . . . Lizard\n                                        Magz\n                                        Instant\n                                        Splash\n               AscII. . . . . . . . . . Relief\n                                        U-MAN\n                                        Grimlock!\n                                        Magz\n               Boards . . . . . . . . . Noiseless - WHQ         LIZARD\n                                        Genetic Waste           MAGZ\n                                        Ecstatica               INSTANT\n                                        Traders Paradise        U-MAN\n\n                                 ---[%]---\n\n\n\n\n\n\n   ............\n   ::        ::\n   ::        ::\n    .        ::\n   /_____    ::          ___________                                          .\n  /_     \//\____________\      ___/_______    _________\n //      \/        _     /     /_         /____\___    //                     :\n/--------/     .---/____/   .---/________         _    //                     :\n     -T!/______\  /_       _|  .______.  \-----/_______/                      :\n                  __\   __/____|_     l_          _______.     _____________  :\n   ::        ::   \  \__    _ _        /_____ ____\     _l_____\     _     /__:_\n   ::        ::    \--(/      /            _//          \        ____/____/  /:\n   ::        ::       /____________________ /      /\-----/_____/   /_________:_\n   ::        ::                           /_______/(rLf)                      :\n   ::........::                                                               :\n                                                                              :\n                        m e g a s t y l e    ¹ 9 9 6                          :\n                                                                              .\n\n@endnode\n\n\n\n\n\n\n@node changes ÷ history\n\n\n    ___.        __      ____    ___.      _____  ½½½½½½½½½½      .____\n  ._\ _l_______(_/_____/ __/____\  l______\   /__½½½½   ½½½______|   /_.\n  |   \__   _       _  \____  _    __/  _        ½½½½½½½''        l     |\n  |____l/  _l_     _l_     l _l_   l   _l_  "  __½½½½   ½½½½½_______  _l\n g®m   /___) (_____) (_______) (_______) (_____) ½½½½   ½½½½½   \_____)\n                                                 ½½½½   ½½½½½ e^D\n\n                               ...HISTORY...\n\n\n\n2000BC          Started on the Door, gave it to all the MGS!-members AND one\n                beta-version to Kingpin for heavy-testing. THANX MATE!\n\n29.03.96        First Public-Release v1.o of the door. Together with a bunch\n                of other doors + a intro. - I sure hope you have it ALL! :)\n\n\n\n\n\n\nThanks to the following boards for helpful beta-testing of MegaStyle-products:\n«----------------------------------------------------------------------------»\n\n                             Genetic Waste (Magz)\n  Checkpoint (Kingpin)   -   Power Rage (Instant)   -   EveryWare (-Shade!)\n\n\n\n@endnode\n','\n',char(10)),NULL,'auto-added',36784,6,0,NULL,NULL,'mgszippy','scan',1780048602);
INSERT INTO door_catalog VALUES('mi__st10','MI!-ST10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MI!-ST10.LHA','sH0Ck-cHECKER','XIM','sH0Ck-cHECKER',NULL,NULL,'MI!','|        __  __           / \\      `96    | |       /  \/  \          \__/    pRESENTS | |      /       \\        / .  \            |',replace('.------------------------- /\ -------------.\n|        __  __           / \\      `96    |\n|       /  \/  \          \__/    pRESENTS |\n|      /       \\        / .  \            |\n|     /    \/   \\      /  |  \\           |\n|     \____||__  /AGiC  \____  /MAGE iNC!  |\n|------------- \/ ---------- \/ -----------|\n|    sH0CK sTATUs V1.oo [Unregistered]     |\n|------------------------------------------|\n|    a nEW dOOR fOR aMIEXXPReSS! V4.**     |\n`-------------------------------[04-06-96]-''\n','\n',char(10)),'sH0Ck-sTART.DOC',replace('                                                                  _ ________\n                                                                        __ (_.\n              · NeutroN ·                                               \/   |\n   ________                      ____________  _________ ________  ________  |\n   \_      \_ _______ _   ______|     .      |_        /         \ \_      \_\n    /       /     __///__ \     /     |      _/      _//          \_/       /\n ._/       /     _\      /     /|     |      \       \_._________._/       /\n |________/\_____________\___________________|\________|-Mo!     |________/\n.\n|  __                                                  · NeutroN ·\n|_ \/\n  )________ _\n\n                        Neutron AmiExpress presents\n\n      THE FINAL DOOR TO START REXXMASHED DOORS FROM WITHIN AMIEXPRESS\n\n                  CODED IN 1995/96 BY GRAVEDANCER/NEUTRON\n\nAbout RexxMasher\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\nRexxMasher (©1994 by ray Norish) is a compiler for arexx scripts and makes\nthem run better and faster.\n\n\nUsing\n¯¯¯¯¯\n\nTO ADD A REXXMASHED DOOR TO YOUR AMIEXPRESS ENVIRONMENT YOU HAVE SIMPLY TO\nADD AN TOOLTYPE TO DOORS:NTR-REXXSTART.INFO LIKE THE FOLLOWING:\n\nFR=DOORS:NTR-DIRINTER/NTR-DIRINTER\n\n\nSupplied Configuration\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\nThe supplied configuration includes the settings for all my doors, that\nneeded the old version of rexxstart (NTR-RMS), so far.\n\nCREDITS\n¯¯¯¯¯¯¯\n\nALL IDEA AND CODING DONE BY GRAVEDANCER/NEUTRON^SHOOT^PROTEST\nNEUTRON LOGO BY MOGUE/ARCLITE\n','\n',char(10)),NULL,'auto-added',20823,3,0,NULL,NULL,'mi_tc10','scan',1780048602);
