INSERT INTO door_catalog VALUES('mid_x45d','MID_X45D.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MID_X45D.LHA','Acp','XIM','Acp',NULL,NULL,'MID','TRION & MARK `OH! -> AMI EXPRESS V4.5D <- `/X4.5D'' AND `ACP'' INCLUDED!',replace('                                            \n             TRION & MARK `OH!              \n                                            \n          -> AMI EXPRESS V4.5D <-           \n                                            \n       `/X4.5D'' AND `ACP'' INCLUDED!         \n                                            \n[-MONKEY ISLAND-] ·:·:· [-TRION & MARK `OH-]\n-^-[ uNl ]-^-[ sAtANiC dREAMS ]-^-[ uNl ]-^-\n','\n',char(10)),'DU_SCHWEIN!.DOC',replace(' \n[1m____________________________________________________ ___________\n[22m\[1m[32m____   ___  [22m\[1m_  _______   ______  ___ __________   [22m\[31m\[1m[32m__  _____[22m/\n [31m/  /[1m[32m____[22m\[31m/   [32m/  |[31m/  [32m\[31mL    [32m/  \[31mL    [32m/ [1m[31m___[3m[22m)[23m[1m_ [22m/   /[1m[32m____[22m\[31m/[1m_____  [22m[32m\\n[3m[31m|   _   [23m[32m\[31m_   [32m/   |    /   /    /   /  [31m\    [32m\[31m_   _   [32m\[1m[31m_[22m    [1m_[22m/   [32m\\n[3m[31m\[23m[1m[32m___[3m[22m[31m7[23m[1m[32m____[22m/[1m_______[22m|[1m___[22m/[1m___[22m/[31m\[1m[32m___[22m/[1m___[22m/[1m_________[22m/[1m___[3m[22m[31m7[23m[1m[32m____[22m/[1m_________[22m/\n                                                           [33m[JZ]\n [31m+49-911-447085  +49-911-447066  +49-911-447067 [33m[[31m3NDZ R/D![33m][1m[31m____\n[22m           [1m___________________   ___________________  ____[22m/   [32mT[31m_\n [33m$Y$0P:    [31m\[1m[32m_______  _______  [22m\  [31m\[1m[32m________________  [22m\[31m/     [1m[32m____[22m/\n [31mBUG ROG3R5 /  [1m__[22m[32m![31m/   [32m\   ![31m/   [32m\ [31m/       [32m\ [31m/   [32m\[31mL   /[1m[32m______[22m\  T\n [33mNUP:      [3m[31m|[23