INSERT INTO door_catalog VALUES('milld2','MILLD2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MILLD2.LHA','Millennium-PDemo','XIM','Millennium-PDemo',NULL,NULL,NULL,'- Works on almost every single BBS Package - Has to be one of the best online games ever made!  Very addictive.',replace('Millennium Online Mega Game Demo.\n- Works on almost every single BBS Package\n- Has to be one of the best online games\n  ever made!  Very addictive.\n- Fight other users on the bbs!\n','\n',char(10)),'Millennium.Readme',replace('  .   .  __  __  __  __    __    ___  __  _  __  _  __  _  _  __  __         .\n ú .::::[  \/  ][  ][  ]  [  ]  [  _][  \[ ][  \[ ][  ][ ][ ][  \/  ]::::.\n ú::::::| \  / ||  ||  [_ |  [_ | ]_ | \   || \   ||  || [] || \  / |::::::.  ú\n   `::::[_]\/[_][__][____][____][___][_]\__][_]\__][__][____][_]\/[_]::::'' . .\n\n                      Programmed by Michael P. Bockert\n\n                           (C) Copyrighted 1994\n\n                   This Demo Release Date: April 15, 1994\n\n  ______________\n |::::::::::::::|\n |::To Install::|\n |::::::::::::::|\n `--------------''\n\n This disabled demo version is a paragon door so that many different bbs''s can\n install it and try it out. Many bbs packages have emulation for running\n paragon doors so I released the disabled demo as a paragon door. I have other\n specific versions for other bbs packages on Amiga.\n\n        VERSIONS AVAILABLE FOR THE FOLLOWING BULLETIN BOARD SOFTARE:\n\n         - AmiCon             - Excelsior             - Trans Amiga\n         - Ami Express        - Paragon/Starnet       - XenoLink\n         - C-Net              - Report\n         - DLG (Dialog)       - /T\empest             - And more...\n\n  ________________\n |::::::::::::::::|\n |::Registration::|\n |::::::::::::::::|\n `----------------''\n\n = Support for almost all bbs software on the Amiga. Ask if your bbs is\n   supported, if not then may be able to add it to the list.\n\n If you would like to register for this online game send $15. US Dollars to:\n\n Michael P. Bockert\n 3846 - 36th Street\n Des Moines, Iowa 50310\n United States\n\n After you have registered you will get a full complete registered version\n that is not disabled.\n\n\n  _________________\n |:::::::::::::::::|\n |::To contact me::|\n |:::::::::::::::::|\n `-----------------''\n\n My BBS: Dawn Of Eternity : 515-255-9066 : 9600+ Buad only\n\n Fido Address: Not Available Yet\n','\n',char(10)),NULL,'auto-added',71411,5,0,NULL,NULL,'milld2','scan',1780048602);
INSERT INTO door_catalog VALUES('mintel10','MINTEL10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MINTEL10.LHA',NULL,'XIM','sonnenbrand.exe',NULL,NULL,NULL,':    Mo-Intelligence v1.00 - sAFRA 1999    : +------------------------------------------+ : Looks like a pager door until the sysop  :',replace('.------------------------------------------.\n:    Mo-Intelligence v1.00 - sAFRA 1999    :\n+------------------------------------------+\n: Looks like a pager door until the sysop  :\n:  answers. Then things aren''t what they   :\n:  appear to be. A total funk-piss-take.   :\n+------------------------------------------+\n:         Requires AmiExpress 4.xX         :\n+------------------------------------------+\n:   100% Arexx Door - 100% Public Domain   :\n`------------------------------------------''\n','\n',char(10)),'Mo-Intel.Guide',replace('Mo-Intelligence v1.00 - sAFRA 1999.\nPublic Domain.\n\nI take no responsibility for any damage caused by this file.\nTrust man, trust.\n\nRequires:\nThe ability to run Arexx doors on /X.\nrexxtricks.library   - here\nrexxsyslib.library\nrexxsupport.library  - here\n\nWhat is it?\nCouple of years back I saw an  Artificial  Intelligence  door  on\nMAXs  -  which  I  have  copied  a  little here. Was a three hour\nprogramming stint, so nothing majorly special. Pretty funky tho;)\n\nUsing  Arexx timer functions, which I can only pray works fine on\nfaster systems than mine (020/882) it will  give  the  appearance\nthat  the  sysop  is there, typing to you. Basic pattern matching\nwill respond to the user''s input.  For  some  reason  it  doesn''t\nALWAYS work. But more times than not it seems ''alive'':)\n\nThe user is first greeted with a pager door.\nThen a random time elapses and the sysop enters.\nYou get the idea.\n\nConfiguration:\nMain  rule:  When  editing the ''#?.DAT'' or ''.cfg'' files make SURE\nthere are NO blank lines in the file when saved, else  this  will\nscrew up responses for the user.\n\nBasically, you can add your own responses to keywords.\n\nThe main file is ''words.cfg'':\n\n hello   greeting.dat\n hiya    greeting.dat\n sunny   weather.dat\n rain    weather.dat\n\nEach line of this cfg file must contain only two words.\n\n(1) Keyword          (2) File to read from (no full path names)\n\nPlay around and you''ll get the idea.\n\nA user''s input is interpreted as follows: The  script  takes  his\nsentence  and  does  a ''matchpattern'' routine for keywords in the\n''words.cfg'' file. If he/she(?) types:\n\n''Hello to you sysop''\n\nThe script will probably find  ''#?hello#?''  and  respond  with  a\nline from the ''greeting.dat'' file.\n\nAnyway, this is a simple program.\nLove it or loathe it.\n\nContact: [email removed]\n','\n',char(10)),NULL,'auto-added',17244,5,0,NULL,NULL,'mintel10','scan',1780048602);
INSERT INTO door_catalog VALUES('ml_rchat','ML!RCHAT.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ML!RCHAT.LHA','eXeCuTeMe!','XIM','eXeCuTeMe!',NULL,NULL,'ML','--========*#>·)  pRESENTS!  (·<#*========-- A New Page-Door For /X V4.x That Randomly Gives An Excuse For The Sysop NOT To Chat',replace('--========*#>·) [35mmOONLiGHTER [0m(·<#*========--\n--========*#>·) [35m pRESENTS!  [0m(·<#*========--\n\n A New Page-Door For /X V4.x That Randomly\n Gives An Excuse For The Sysop NOT To Chat\n With The Paging User. Fun, Nice Output!!!\n Install It Now And Have Fun Later!! =)\n ------------------------------------------\n wORLD rELEASE aT eAGLE eYE +46-16-519326!!\n ------------------------------------------\n','\n',char(10)),'RandomChat.Doc',replace('                 Archive Made: 1995-10-30 At 03:56\n              -=====================================-\n\n\n\n             Random Chat Door V1.2 © 1995 By Moonlighter\n             All Rights Reserved, ® 1995 By Moonlighter!\n     -=========================================================-\n\n    You May Use This Freely As Long As You *DON''T* Edit Anything\n    In The Script Or The Archive.\n                                             Signed: Moonlighter\n     -=========================================================-\n\n\n Archive Contents:\n =================\n\n 1.st_ML!Release!/bbs/commands/bbscmd/o.info\n 1.st_ML!Release!/bbs/doors/ml!doors/RandomChat.rexx\n 1.st_ML!Release!/bbs/doors/ml!doors/RandomChat.Doc\n 1.st_ML!Release!/Libs/AEDoor.library\n\n\n Installing The RandomChat Door:\n ===============================\n\n Simple! Just Copy The Files To Their Directories, And\n Off You Go To Have Lots Of Fun! =)\n\n\n What Does It Do??\n =================\n\n Well, The Whole Idea Is To Make The Page-Door A Little More\n "Fun-To-Use", B''Coz When You Page A Sysop At Some BBS, And\n The Chatfleg Is Turned Off You Get A Message Saying Something\n Like:\n\n To Bad "USERNAME", But "SYSOP" Is Not Around Right Now.\n Use ''C'' To Leave Him A Comment!\n\n And That''s A Little Boring Don''t You Think! Well I Did, So I\n Got The Idea Of Making This Little Door.\n\n What It Does Is When The Chatflag Is Turned Off, It Displays\n A Random Output With Different Reasons To Why The Sysop Is Not\n Around To Chat With The User. And The Outputs Are Quite Funny\n So In My Oppinion It Will Lighten Up The Situation A Bit =)\n\n And A Small Thing I''ve Added Since Last Version Is That When\n A User Is Paging You It Adds A Line To CallersLog That Looks\n Something Like This:\n\n ex. Operator Paged by mOONLiGHTER at (03:02:30)\n\n Quite Nice To Have If You Now Are Doing Something Else And Can''t\n See If You Are Being Paged Or Not!\n\n Nothing Fancy, But Handy...\n\n Well, Guess That''s It For This Release.\n\n You Can Always Call My BBS, Eagle Eye, At +46-16-519326 For Any\n Bugreports Or Ideas For New Ingrediants! =)\n\n\n\n\n\n                    \\ mOONLiGHTER\n\n\n\n\n\n\n\n\n\n                       GREETINGS:\n                    -==============-\n\n             Just To All My Friends And All\n             Of You Who Uses This Door!!!!!\n\n','\n',char(10)),NULL,'auto-added',54154,10,0,NULL,NULL,'ml_rchat','scan',1780048602);
INSERT INTO door_catalog VALUES('ml_cbd12','ML-CBD12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ML-CBD12.LHA','Cowbung','XIM','Cowbung',NULL,NULL,'ML','Cowabunga Deleter, the most comprehensive file maintenance system ever developed for /X. An all GUI interface makes deleting',replace('         Mack Lifeguard Coded 4 u:\n Cowabunga Deleter, the most comprehensive\n file maintenance system ever developed for\n  /X. An all GUI interface makes deleting\n      and moving massive files a snap.\nFor the ultracool S-Express and compatibles.\n','\n',char(10)),'AuthorsFinalNote.txt',replace('Sat Jan 29 14:30:27 1994\n\nIf you would like this program to work on /X 3.xx, then you will need to add\nthe /X 2.xx style NDIRS and PATHS files.\n\nI will make this program compatible with /X 3.xx at a later time.\n\n','\n',char(10)),NULL,'auto-added',134560,11,0,NULL,NULL,'ml_cbd12','scan',1780048602);
INSERT INTO door_catalog VALUES('mlotto12','MLOTTO12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MLOTTO12.LHA',NULL,'XIM','Multi Lotto','1.12',NULL,NULL,NULL,replace('Multi Lotto V1.12\n','\n',char(10)),'Mlotto.doc',replace('MLOTTO.DOC\n----------\n\n\nMULTILOTTO:\n^^^^^^^^^^^^\n\nThe user can buy Tickets for the cost of XX Upload Bytes.. if he Loose the\nUpload bytes will be stored in the Pot. If he Wins he will take the Pot !\n\n\n\nHistory:\n^^^^^^^^\nV1.00 xx/xx/93 : * First release....including a spell error !\n\nV1.01 xx/xx/93 : * Quick Fix for west bbs\n\nV1.02 xx/xx/93 : * Official Buggfixed release.\n\nV1.10 06/01/93 : * User could regain lost bytes if he dropped carrier,FIXED!\n                 * The Sysop can now Define own games\n                 * Sysop can define how many tickets a user can buy/day\n                 * if the Pot gets empty the BBS will donate XX tickets.\n                 * ML now keeps track of how much a user lost/won.\n                 * a "facelift" :-(\n\nV1.11 xx/xx/93 : * Private release to Flabbergast/ATM\n\nV1.12 09/09/93 : * Fixed Bugg: The proggy wouldnt save your stats if\n                   you stoped playing after just 1 round of loosing.\n\n\nInstallation:\n^^^^^^^^^^^^^\n\nIf you have an older version installed, Just put the *.Cfg file in S: and\nexchangde the old Mlotto.Ae file with the new...\n\nIf you never have used this door, put the Mlotto.AE in a Dir\nnamed "Doors:Blotto/" the Mlotto.cfg file in S: and install the Mlotto.Ae as\na Rexx command.\n\n\nSysop Usage:\n^^^^^^^^^^^^\nI made some quick sysop funktions... next version will include more advanced\nfunctions but i wanted to release this version a.s.a.p !\n\nA. Create/remove games.\n^^- this funktion will prompt you to enter the prices of all games\n    that you would like to have ex "20 50 70 100" NEVER write anything\n    else then numbers on this prompt, if you do be sure to correct it\n    before Playing/exiting the game cauz i have not included a error check\n    in that option.\n\nB. Lists your Config settings (edit the S:Mlotto.cfg)\n\n\n\n\nWell i''ll think thats all.... If ya wanna reach me then Please call my Board\n\nLOYD BBS +46-300-64661 [Tempest]\nor\nMINOR MISHMASH +46-31-992525 [Amixpress]\nor whay not call our new Board !?\n\nACES HIGH #1 +46-410-44886\n          #2 +46-410-46577\n\n\n                                 Goofy/Conny\n\n\nPS. Dont ya &*&%$*&*& Change Anything in these scripts without Asking ME !\n\n','\n',char(10)),NULL,NULL,10196,8,0,NULL,NULL,NULL,'scan',1780048602);
INSERT INTO door_catalog VALUES('mlt_awsc','MLT-AWSC.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MLT-AWSC.LHA',NULL,'XIM','_ __ ___   ___ __ _',NULL,NULL,'MLT','/\__  ___________  /  /__________________ \   \/     / ___/ /  /____  ____/ __/__  \ \        / __/__/ _/\   |  | / __/__ /  /',replace('            _ __ ___   ___ __ _\n/\__  ___________  /  /__________________\n\   \/     / ___/ /  /____  ____/ __/__  \\n \        / __/__/ _/\   |  | / __/__ /  /\n  \  \/  /  |   /     \_ |  |/  |   / \  \_\n   \__\__\_____/_______/ |__|\_____/__|\__/\n=====================> pRESENtS: <=========\n              Awaitscreen.txt\n   A replacement of the BORiNG screen of\n AmiExpress when it''s waiting for a call!\n','\n',char(10)),'Docs.txt',replace('-  - -- --- ------------------------------------------------------------------.\n                                                                              |\n                  .    .                                                      :\n/\___  ______/\___|   _|______                                                .\n\    \/     /  \  \   \_____  \\n \          \__/       |  _/   \                                              .\n  \   \/   /|  |       |  \    /\n Mb\   \___\|  |___\___|___\__/\n_ __\___\ __`--''___ _ _ _    _   _  _  _ _ ______    _____ _ _ _  _  _\n                          /\___  _____________  / __/_____________________\n                          \    \/      /   __/ /  \____  ____/  __/___    \\n.                          \          /  __/_ /  _/\  |  | /  __/__  /    /\n                            \   \/   /   |   /      \_|  |/   |   /  \    \_\n.                            \   \___\______/________/|  |\______/    \____/\n:            _   _  _ _ ______\___\ ______ _ _  _   _ `--''       `----''\n|\n+  - -- --- -------------------------------------------------------------------\n|                          >>> pRESENTS aNOTHER kOOL aRCHiVE!\n`------------------------------------------------------------------ --- -- -  -\n\n                               -------------\n                                CHAPTER ONE\n                             HOW TO INSTALL IT\n                           --------------------\n\nSimple: copy the file:\nbbs/localnode/awaitcreen.txt\nin your localnode (my local node is the node 0!)\n\nand the file:\nbbs/node1/awaitscreen.txt\nin your user''s node!\n\nAnd  the  boring  screen  that  appears  when  your  board is waiting for a\ncallers, will change with a more coloured and less poor screen!\n\n                               -------------\n                                CHAPTER TWO\n                           A LiTTLE SUGGESTiON!\n                           --------------------\n\n\nA suggestion:  for the user''s node, you can use the awaitscreen like a last\ncaller:   in  your  logoff.bat, add a string that make with output a screen\nwith the last 15 callers:  I use the SAMILOG and my string is this:\n\nBBS:UTILS/SAmiLog -ONTLR"bbs:node1/awaitscreen.txt"15\n\nSo,  when you''ll see the screen you''ll see the last 15 callers without make\na local logon!\n\nThis suggest has made by Dr. G !! THANKS FRIEND!\n\n                               -------------\n                               CHAPTER THREE\n                           GREETiNGS AND THANKS\n                           --------------------\n\nUnlike  the  others works (my fonts etc..), I don''t want to give the thanks\nto all-my-friends, but only to:\n\n    >Dr. G< for his precious suggest and for his simphaty! HI FRIEND!!\n                   >Papaj< for the dizzy in his board ;)\n     >Alx Sty< for the dizzy and the patience to read all my EALLS ;)\n\n But, Obviously, I give the greetings to >all my friends< around the world!\n\n                              --------------\n                               CHAPTER FOUR\n                              HOW TO HELP ME!\n                           --------------------\n\n                   To give me suggestion, call my board:\n\n                               PRiMAL ORDeR\n                              +39-45-8011137\n                           24h/24h obviously ;)\n\nOr  send  a  mail  to  the  italian boards, like The House, Digit Star, The\nGroove, Paradise Dreams, ....\n\nSee  ya l8er friends!!  Thanks for the attention ;) Stay kool and wait soon\nothers works by MiNd MeLTeR ;)\nbYZ!\n                                             «··M·e·L·T·e·R··/··b·R·S··»\n\nP.S.   SORRY FOR EVENTUALLY MISTAKES IN THIS FILE..  i''M NOT A GENIOUS WITH\nTHE ENGLISH LANGUAGE HEHE!  BYZ!\n','\n',char(10)),NULL,NULL,16475,6,0,NULL,NULL,NULL,'scan',1780048602);
INSERT INTO door_catalog VALUES('ml_cd12','ML_CD12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ML_CD12.LHA','Cowbung','XIM','Cowbung',NULL,NULL,'ML','Cowabunga Deleter, the most comprehensive file maintenance system ever developed for /X. An all GUI interface makes deleting',replace('         Mack Lifeguard Coded 4 u:\n Cowabunga Deleter, the most comprehensive\n file maintenance system ever developed for\n  /X. An all GUI interface makes deleting\n      and moving massive files a snap.\nFor the ultracool S-Express and compatibles.\n--------------------------(dREAm pHASe)----','\n',char(10)),'AuthorsFinalNote.txt',replace('Sat Jan 29 14:30:27 1994\n\nIf you would like this program to work on /X 3.xx, then you will need to add\nthe /X 2.xx style NDIRS and PATHS files.\n\nI will make this program compatible with /X 3.xx at a later time.\n\n','\n',char(10)),NULL,'auto-added',77038,5,0,NULL,NULL,'ml_cd12','scan',1780048602);
INSERT INTO door_catalog VALUES('mmail201','MMAIL201.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MMAIL201.LHA',NULL,'XIM','sonnenbrand.exe',NULL,NULL,NULL,':mO-mAIL v2.01- sAFRA 1999 - BETA TEST DOOR: +------------------------------------------+ :>>>>> Requires YAM 2.0p7 and /X 4.12 <<<<<:',replace('.------------------------------------------.\n:mO-mAIL v2.01- sAFRA 1999 - BETA TEST DOOR:\n+------------------------------------------+\n:>>>>> Requires YAM 2.0p7 and /X 4.12 <<<<<:\n:>>> AmiExpress Email Door - 100% AREXX <<<:\n+------------------------------------------+\n|  Mo-Mail is PD. Do what you wish with it |\n+------------------------------------------+\n|  THIS VERSION FOR USERS WITH A STATIC IP :\n`------------------------------------------''\n','\n',char(10)),'Mo-Email.Guide',replace('@database Mo-Email.Guide\n@$VER: Mo-E-Mail (v1.03)\n@author "Safra"\n\n@node "Main" "mO-eMAIL dOCS"\n\n              @{b}==============================================\n               mO-eMAIL - v2.0X - STATIC IP VERSION - sAFRA\n              ==============================================@{ub}\n\n              @{" Introduction                  " link "Intr"}  -  mO-eMAIL!\n              @{" System Specs                  " link "spec"}  -     nEEDS!\n              @{" Installation                  " link "inst"}  -        gO!\n              @{" Important                     " link "Impo"}  -      vERY!\n              @{" Author                        " link "auth"}  -   cONTACT!\n              @{" Files                         " link "file"}  -     cHECK!\n              @{" Known Bugs                    " link "bugs"}  -   rECHECK!\n              @{" Final                         " link "fina"}  -   tHE eND!\n\n              @{" READ ME                       " link "upda"}  -    pLEASE!\n              @{b}==============================================\n              [AREXX-DOOR-AREXX-DOOR--AREXX-DOOR-AREXX-DOOR]\n              ==============================================@{ub}\n\n\n@endnode\n\n@node "Intr" "Introduction"\nForever ago I wanted an email door for ?Express. Nothing was  out\nthere  aside  from  a custom door by RRR. This wasn''t public so I\nstarted on this little effort.\n\nThe original MoMail17.lha can go piss in a lake for all  I  care.\nI  have  now  changed a few things in it so anyone using a STATIC\nIP gains. Hopefully. The original door was  for  temp-assigned-IP\ninternet  users - using some godforsaken programming to allow the\nBBS to have ''unlimited email  addresses''.  It  could  still  work\nproperly,  but  lack  of feedback and patience forced me to ditch\nit. Too bad.\n\nAnyhows,  this  new  version  is  for people at Demon Net etc. Or\nperhaps Freeserve (which is free, shockingly):\n\n [email removed]\n [email removed]\n\nYou know the score.\n\n@endnode\n@node "spec" "Specifications"\nMo-Email is currently running on my:  A1200 (68020) (68882 fpu)\n                                      10 Meg RAM\n                                      85 Meg Drive (still)\n                                      /X version 4.12\n                                      YAM 2.00 Preview 7\n\nWhether this will work on other versions of /X, I have no idea.\nWill it work on other systems? Fame/S!x/DayDream? I don''t know.\nYou tell me.\n\n@endnode\n@node "Impo" "Important!"\n\n<--------------------------------------------------------------->\nBEGIN OLD DOCS: MAY NOW NOT APPLY TO YAM 2.00:\n\nIn  order  for  users  to  delete  their  mail,  you  MUST UNtick\n''CONFIRM BEFORE DELETION'' in your YAM prefs/config.  Also  cancel\n''GET MAIL ON STARTUP''...as I am not sure whether this interferes\nwith the program, should a  user  be  the  one  to  load  YAM.  I\nbelieve  it  causes  no  hassle  when YAM is in HIDE mode. YAM is\ntold to go HIDE its ass when Mo-Email is run.\n\nIt  would  be  wise to put YAM in WBSTARTUP, else the program has\nto be loaded when a  user  tries  to  access  Mo-Mail.  It  needs\nloading only once, but once is enough to piss off a user.\n<--------------------------------------------------------------->\n\nBEGIN NEW DOCS: How other things work:\n\nThe  tailer  that  is  added  to  an outgoing email contains your\npersonal tag: (doors:email/signature.txt). Change  this  to  suit\nyour BBS etc. The easy part:)\n\nAnyone on the BBS using split names will become hyphenated:\n\n IE: ''The Count'' becomes ''The-Count''\n\nElse they do not have a valid email address.\nThough I''m sure I''m wrong.\nSee also: KNOWN BUGS\n\nAs  you  know,  any incoming mail contains a shitload of crap and\ninformation as a header.\n\nI have added a routine that removes most of this when a  user  is\nonline reading their mail. It takes a complete  email  and  scans\nthrough  until it finds the string: "Content-Type:" ...thereafter\nshowing the rest of the file, nothing beforehand.\n\nKILL:\nI agonised over this for days. Finally came  up  with  this  lame\nidea  for  deleting  mail.  It  deletes all current mail for that\nuser. They have chances to download etc. It will ask whether  the\nuser wants to KILL the mail yet (or not). It works just fine  and\nI see no reason to update it ever.\n\nABOUT + INFORMATION:\nSimple text files to add fun and frolics.\n\nIf  the door is in use then no other node can access their email,\nhaving  to  wait until user1 is finished. Simultaneous use of YAM\nscanning etc could result in hassle. Or so I theorise.\n\nRead mail options:\n\nDownload:  Let  you  download  the  current  file.  A  counter is\ncurrently running that makes each new download:\n\n YourMail1\n YourMail2\n YourMail3  ...etc...\n\n...so files don''t overwrite each other at the user''s end.\nCan''t remember if NCOMM etc overwrite in that way.\nBut I programmed it in anyway :)\n\nREPLY:  Accesses  the  text  editor,  already supplying the email\naddress of current-read email. Simple.\n\nFILE-ATTACH is currently disabled.\n\nEXTRAZ:\n       mosearch.info  (*)\n       cumail.txt\n       nomail.txt\n       logonsearch.rexx\n       scanit.rexx\n\n(*) Info file goes in usual BBS:commands/bbscmd. The other  files\nare  left  where  they are. Two txt files can be changed to suit,\nload up into suitable ANSI/TEXT editor.\n\n(*) Add: ~CC_MOSEARCH ...to your logon script. You know how.\n    Shows whether the logged-on user has email or not.\n    Will load YAM if not already loaded. Beware!\n\nAnd that''s about it.\nAs usual, all ideas/abuse appreciated.\n@endnode\n@node "auth" "Contact"\nContact:   [email removed]\nBBS:       (UK) 01536-744-639 (After 10pm please)\n@endnode\n@node "file" "Files"\nWhen   program  runs  it  loads  (if  not  already  loaded)  YAM,\nsearching for it in the usual YAM: assign.\n@endnode\n@node "fina" "Jerry Springer''s Final Thought..."\nYAM courtesy of Marcel Beck - 1995/1999.\nSuperb program. Truly.\n\nAscII courtesy of TANGo.\n\n@endnode\n@node "inst" "Getting this fecker to work..."\nJust put all files where they should be. Phhhhhh.\nRexxMast and RPstart must be running.\nCheck AEDocs for RPstart instructions.\n\nMost important: Find ''Folder.cfg'' and load into  a  text  editor,\nchanging  the number 4 to any desired folder of YAM that you wish\nto store all BBS-Emails. 0 -  3  are  Incoming,  Outgoing,  Sent,\nArchived.  Custom folders begin at 4. Please consult YAM guide on\nhow to achieve multiple orgasms. Erm, folders.\n\nVery important: Find ''Domain.cfg'' and change it to your domain.\nIf your email address is ''[email removed]'' then your\nDomain.cfg will be ''welcome.demon.co.uk''\n\nMAKE SURE that all files go where I say they  should.  You  might\nthink  it  okay that you have ''waitforport'' etc in your SYS:REXXC\ndirectory, but Mo-Mail wants it in C: (for my personal ease),  it\nwon''t go searching for it. It doesn''t give a feck.\n\nWhere files should be:\n\n libs:rexxsyslib.library\n C:rx\n C:waitforport\n C:delete\n C:wait\n C:makedir\n C:dir\n C:list\n\nYou  as the sysop will have to send the mail. If anyone out there\nhas the luxury of 24/7 net connects then basically  someone  with\na    high    enough   level  of  axs  on  the  BBS  can  begin  a\ndirect-from-the-net mail check. Otherwise, it''s up  to  sysop  to\ngather all mail etc.\n\nA  script/program  could  be  created  that will send YAM(Miami?)\nonline once a day. This would of course have nothing to  do  with\n/X or MoMail. Totally independant. I''m not writing it.\n\nIf anyone does, then MoMail needs tweaking to show  that  YAM  is\ncurrently running a mail call.\n\nYes, I have put little thought into this. Cough.\n\n@endnode\n@node "Bugs" "Those feckin crawlies..."\n\nMOMAIL  will  do a pathetic check on any entered email address to\ncheck for validity. If it does NOT contain a ''@''  then  the  user\nwill not proceed further. NOT  implemented  is  a  check  to  see\nwhether a user has entered a duff-space name:\n\n IE: [email removed] org\n\n(Space between ''com'' and ''org'')\n\n...Or  something  similar.  If YAM is not hidden then a requester\nwill pop up to tell the  Amiga  owner  that  somebody  fucked  up\nsomewhere.  If  YAM is hidden then everything should be cool, and\nthe user simply loses out. Not sure entirely.\n\nIf YAM is not running when MOMAIL begins then it  will  load  the\nYAM as follows:\n\nrun etc: ''YAM:YAM PREFSFILE=YAM:.config MAILDIR=YAM: NOCHECK HIDE''\n\nPREFSFILE=the main config for your YAM program\nMAILDIR=the directory that holds all your incoming/etc folders.\n\nRemember: The current setup needs FOLDER 4 TO BE CALLED ''BBS''\nRemember: Folders begin at ''0''.\n\n@endnode\n\n@node "upda" "BETA"\nTHIS IS A BETA VERSION\nI TAKE NO RESPONSIBILITY FOR ANY DAMAGE CAUSED\nYOU USE AT YOUR OWN RISK\n\nAnd...etc.\n@endnode\n\n','\n',char(10)),NULL,'auto-added',16200,5,0,NULL,NULL,'mmail201','scan',1780048602);
INSERT INTO door_catalog VALUES('mmail202','MMAIL202.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MMAIL202.LHA',NULL,'XIM','sonnenbrand.exe',NULL,NULL,NULL,':mO-mAIL v2.02- sAFRA 1999 - BETA TEST DOOR: +------------------------------------------+ :>>>>> Requires YAM 2.0p7 and /X 4.12 <<<<<:',replace('.------------------------------------------.\n:mO-mAIL v2.02- sAFRA 1999 - BETA TEST DOOR:\n+------------------------------------------+\n:>>>>> Requires YAM 2.0p7 and /X 4.12 <<<<<:\n:>>> AmiExpress Email Door - 100% AREXX <<<:\n+------------------------------------------+\n|  Mo-Mail is PD. Do what you wish with it |\n+------------------------------------------+\n|  THIS VERSION FOR USERS WITH A STATIC IP :\n`------------------------------------------''\n','\n',char(10)),'CuMail.txt',replace('\n[34m- --[ [0mmESSAGE fROM mO-eMAIL[34m: [36myOU hAVE mAIL wAITING! wAHOO! [34m]------------- -- -\n','\n',char(10)),NULL,'auto-added',10507,4,0,NULL,NULL,'mmail202','scan',1780048612);
INSERT INTO door_catalog VALUES('mmail203','MMAIL203.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MMAIL203.LHA','8','XIM','10',NULL,NULL,NULL,':mO-mAIL v2.03- sAFRA 1999 - BETA TEST DOOR: +------------------------------------------+ :>>>>> Requires YAM 2.0p7 and /X 4.12 <<<<<:',replace('.------------------------------------------.\n:mO-mAIL v2.03- sAFRA 1999 - BETA TEST DOOR:\n+------------------------------------------+\n:>>>>> Requires YAM 2.0p7 and /X 4.12 <<<<<:\n:>>> AmiExpress Email Door - 100% AREXX <<<:\n+------------------------------------------+\n|  Mo-Mail is PD. Do what you wish with it |\n+------------------------------------------+\n|  THIS VERSION FOR USERS WITH A STATIC IP :\n`------------------------------------------''\n','\n',char(10)),'Mo-Email.Guide',replace('@database Mo-Email.Guide\n@$VER: Mo-E-Mail (v2.03)\n@author "Safra"\n\n@node "Main" "mO-eMAIL dOCS"\n\n              @{b}==============================================\n               mO-eMAIL - v2.03 - STATIC IP VERSION - sAFRA\n              ==============================================@{ub}\n\n              @{" Introduction                  " link "Intr"}  -  mO-eMAIL!\n              @{" Installation                  " link "inst"}  -        gO!\n              @{" What it does                  " link "impo"}  -   dETAILS!\n              @{" Contact                       " link "auth"}  -   cONTACT!\n              @{" Known Bugs                    " link "bugs"}  -   rECHECK!\n\n              @{" Updates                       " link "upda"}  -     sMILE!\n              @{" Files                         " link "file"}  -    nEEDED!\n              @{b}==============================================\n              [AREXX-DOOR-AREXX-DOOR--AREXX-DOOR-AREXX-DOOR]\n              ==============================================@{ub}\n\n                - rEMEMBER: tHIS iS a bETAtESTER vERSION -\n                       - mO-mAIL IS PUBLIC DOMAIN -\n@endnode\n\n@node "Intr" "Introduction"\nForever ago I wanted an email door for ?Express. Nothing was  out\nthere  aside  from  a custom door by RRR. This wasn''t public so I\nstarted on this little effort.\n\nOriginal MoMail used some godforsaken programming to allow a  BBS\nto  have  ''unlimited  email addresses'' using a server-assigned IP\naddress.  Those  with  static  addresses  (Demon   Net/Freeserve)\nshould  use  this  version.  In  fact,  you  should  get a static\naddress simply to use this version. MoMail17.lha has  been  found\nbuggy  and  unusable.  I  *may*  fix  this in future, but lack of\nfeedback on the project forced me to ditch it.\n\nAnywayz, let us continue with this new version...\n\n@endnode\n@node "spec" "Specifications"\nMo-Email is currently running on my:  A1200/020/882/P45\n                                      10 Meg RAM\n                                      85 Gig Drive (dream)\n                                      85 Meg Drive (reality)\n                                      /X version 4.12\n                                      YAM 2.00 Preview 7\n\nWhether this will work on other versions of /X, I have no idea.\nWill it work on other systems? Fame/S!x/DayDream? I don''t know.\nI only have the above to test it on.\n\n@endnode\n@node "Impo" "Important!"\nAnyone on the BBS using split names will become hyphenated:\n\n IE: ''The Count'' becomes ''The-Count''\n\nElse they do not have a valid email address.\n\nAs  you  know,  any incoming mail contains a shitload of crap and\ninformation as a header. Routines make sure  the  user  does  not\nhave  to read through all this rubbish. If a user has been sent a\nmessage that has an attached file then  all  encoded  information\nwill  be  cut,  else  it will scroll and scroll to infinity. This\nwill not happen if the attached file is a simple text file.\n\nKILL:\nI agonised over this for days. Finally came  up  with  this  lame\nidea  for  deleting  mail.  It  deletes all current mail for that\nuser. They have chances to download etc. It will ask whether  the\nuser wants to KILL the mail yet (or not). It works just fine  and\nI see no reason to update it ever. If a user chooses to  download\nthe  current-read  message  then  it will be named ''07743.001'' or\nwhatever name YAM has assigned to it.\n\nIf  the door is in use then no other node can access their email,\nhaving  to  wait until userX is finished. Simultaneous use of YAM\nscanning etc could result in hassle. Or so I theorise.\n\n@endnode\n@node "auth" "Contact"\nContact:   [email removed]\nBBS:       (UK) 01536-744-639 (After 10pm please)\n\nOnce again, no bitching about this program. It''s been a bitch  to\nprogram  especially  with  YAM undergoing a major change from 1.3\nto 2.0. That was a swine. Neither am  I  heads-up  on  the  Arexx\nscore. But nobody else would do it, so hey.\n\n@endnode\n@node "inst" "Getting this fucker to work..."\n(1) You must make sure that RexxMast/RPStart is running to allow\nuse of AIM(Rexx) doors in AmiExpress.\n\n(2) Copy all files from archive to where they should be.\n\n(3)  Find  ''doors:email/folder.cfg''  and  change contents to suit\nwhich folder you will be using in YAM. Remember,  custom  folders\nbegin  at  4.  0=INCOMING  3=SENT etc. This archive uses folder 4\nas default.\n\n(4) Find ''doors:email/domain.cfg'' and  change  contents  to  your\ncurrent  domain.  IE: ''funky.demon.co.uk''. Do NOT include the ''@''\nbefore your domain.\n\n(5) Make sure you have the following files in your ''C:'' dir:\n\n    C:rx\n    C:waitforport\n    C:delete\n    C:wait\n    C:makedir\n    C:dir\n    C:list\n\nThe above MUST be in C: You may  already  have  ''waitforport''  in\nREXXC but it MUST exist here also.\n\n(6) Check for these in ''LIBS:''\n\n    rexxsyslib.library\n    rexxtricks.library [©Jurgen Kohrmeyer 1994/95]\n\n(7)  You  will find some texts in the ''doors:email/'' dir that can\nbe changed to suit your board. IE: The main menu etc.\n\n(8) Add ''~CC_MOSEARCH|'' to your logon script so users  can  check\nfor awaiting mail while logging on.\n\n(9)  Change  ''doors:email/signature.txt'' to suit your board. This\nsig will be attached to all BBS outgoing mail.\n\n(10)  MOST  IMPORTANT:  Open  YAM  configuration    and    select\n''MISCELLANEOUS''  from  the  side  bar. Find ''Confirm deletion...''\nand make sure it is *NOT* ticked. If ticked, then  the  user  may\nwant  to  kill  mail  from  the BBS, which won''t happen because a\nrequester will pop up.\n\n(11)  Try and keep YAM running. If YAM is not present when a user\nwants it then the program will load it. Which may bug the fuck.\n\n(12) You as sysop will be in control of  sending/receiving  mail.\nDo  this  when  you want. Every day/every other day. Your choice.\nThere could be a program written  (independant  of  MoMail)  that\nwill send Miami/YAM online and check for mail.\n\n(13)  You  may  have  to  change the rexx scripts (email.rexx and\nlogonsearch.rexx) to suit your needs, as it currently  loads  YAM\nas follows:\n\n "run ''YAM:YAM PREFSFILE=YAM:.config MAILDIR=YAM: NOCHECK HIDE''"\n\n PREFSFILE=the main config for your YAM program\n MAILDIR=the directory that holds all your incoming/etc folders.\n\nIf you run YAM yourself (without the  need  for  the  program  to\ncall  it)  then  make  sure  you  use the same config as mine, as\nabove. YAM must be where the folders  are  and  the  config  file\nmust be called ''.config''.\n\n(14)  Make sure ''NoAttach'' exists in ''doors:email/'' if you do not\nwish to use the ''attach file to email'' option.\n@endnode\n\n@node "Upda" "Updates..."\nv2.03  -  File Attach added. This needs some serious testing.\n          I''ve not had any problems, aside from the fact that any\n          uploaded file needs to be one word. Split filename will\n          result in ''file already exists'' but the program will\n          carry on happily, not attaching anything.\n          Put a file in ''doors:email/'' called ''NoAttach'' and\n          this function will be disabled. Any file. If a user\n          uploads multiple files then only the first is used.\n\n          If no mail is there for the user then a different\n          message will be displayed.\n\n          Overall: I am very happy with this proggy, even though it\n          looks ''tacked together in a day''. Learning more and more about\n          Arexx - use of libs etc. I find that ''makedir'' ''delete'' etc are\n          all part of rexxsupport.library. The less ''outside'' files I have\n          to use, the better.\n\n          Please see also: @{" KNOWN BUGS " link BUGS }\n\nv2.02  -  MoMail  not  bothered  now  by uppercase/lowercase. The\n          email will be read by ''sAFRA'' or ''safra''...etc.\n          Used rexxtricks.library to achieve this.\n          Yes, there was probably an easier way, but.\n\n          Hyphenation of user name if a split word prog routine\n          changed. I had some nightmare check routine which has\n          been replaced by a built-in Arexx function. Likely there\n          are a million more built-in functions that could reduce\n          this whole program to ten lines long, damn it.\n\n          Aside from the check for ''@'' in any entered email address\n          also added is the check to make sure there are no spaces.\n\n          Layout changes. New main menu.\n\n          Guide re-written. All UPDATE info now within.\n\n          Filename change to MMail20x.lha\n          Old filename was 13 chars long.\n          Which is not allowed when upping to an /X board.\n          Oh man, a bug in the file name. Sickening.\n          I''m sure some god is laughing at me.\n\n          Counter on ''readmail''. ''Message 1 of 3'' etc. Cheap.\n\n          ''Format SYS:'' command implemented via ''ZZ'' command on main.\n          Then pressed by accident.\n          Re-wrote whole program from scratch.\n\nv2.01 - Another rush release. Must stop.\n\nv2.00 - Rushed release. Shouldn''t have. Idiot.\n@endnode\n@node "Bugs" "Those feckin crawlies..."\nFile  attach  is  giving problems. /X will not allow me to upload\nany file with a space name: IE: ''look.lha'' is fine but ''the text''\nrefuses to go anywhere. Working on this.\n\nHaving  learned  just  a  little  more  about Arexx I find simple\nthings: Makedir and Delete etc are avail through  rexxsupport.lib\n-  there  are  probably a whole heap of things avail. So, I''ll be\ngoing through  the  whole  program  looking  for  major  ways  to\noptimize before v2.04 is released.\n\nThere  is one major hassle with the whole program. Being an Arexx\nscript it is already  ADDRESSing  AmiExpress.  If  I  could  also\nADDRESS  YAM  directly  from  the  main  email.rexx  then I could\nbasically write the whole thing in  one  script.  It  would  mean\nless  files  to  write  to ''t:mo-mail'' - would be faster - etc. I\ndon''t know if this is currently possible, hence the  main  script\nis calling on all those external files.\n\nBasically,  the  scene  is almost dead, so finding help with this\nis next to impossible. But I''ll battle on anyways, regardless  of\nwhether my collected effort is obsolete or not:)\n@endnode\n@node "file" "Files you SHOULD have here..."\n***DOORS:EMAIL/***\n\nScanIt.Rexx\nScan.Rexx\nSignature.txt\nNoMail.txt\nEmail.Rexx\nMenu.txt\nLogonSearch.Rexx\nKill.Rexx\nCuMail.txt\nReply.Rexx\nInformation.txt\nHide.rexx\nHandler.Rexx\nFolder.cfg\nDomain.cfg\n(NoAttach)\n\n***BBSCMD***\n\nMOSEARCH.info\nEMAIL.info\n@endnode\n','\n',char(10)),NULL,'auto-added',42790,4,0,NULL,NULL,'mmail203','scan',1780048612);
INSERT INTO door_catalog VALUES('mmail204','MMAIL204.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MMAIL204.LHA','8','XIM','10',NULL,NULL,NULL,':mO-mAIL v2.04- sAFRA 1999 - BETA TEST DOOR: +------------------------------------------+ :>>>>> Requires YAM 2.0p7 and /X 4.xx <<<<<:',replace('.------------------------------------------.\n:mO-mAIL v2.04- sAFRA 1999 - BETA TEST DOOR:\n+------------------------------------------+\n:>>>>> Requires YAM 2.0p7 and /X 4.xx <<<<<:\n:>>> AmiExpress Email Door - 100% AREXX <<<:\n+------------------------------------------+\n|  Mo-Mail is PD. Do what you wish with it |\n+------------------------------------------+\n|  THIS VERSION FOR USERS WITH A STATIC IP :\n`------------------------------------------''\n','\n',char(10)),'Mo-Email.Guide',replace('@database Mo-Email.Guide\n@$VER: Mo-E-Mail (v2.04)\n@author "Safra"\n\n@node "Main" "mO-eMAIL dOCS"\n\n              @{b}==============================================\n               mO-eMAIL - v2.04 - STATIC IP VERSION - sAFRA\n              ==============================================@{ub}\n\n              @{" Introduction                  " link "Intr"}  -  mO-eMAIL!\n              @{" Installation                  " link "inst"}  -        gO!\n              @{" What it does                  " link "impo"}  -   dETAILS!\n              @{" Contact                       " link "auth"}  -   cONTACT!\n              @{" Known Bugs                    " link "bugs"}  -   rECHECK!\n\n              @{" Updates                       " link "upda"}  -     sMILE!\n              @{b}==============================================\n              [AREXX-DOOR-AREXX-DOOR--AREXX-DOOR-AREXX-DOOR]\n              ==============================================@{ub}\n\n                - rEMEMBER: tHIS iS a bETAtESTER vERSION -\n                       - mO-mAIL IS PUBLIC DOMAIN -\n@endnode\n\n@node "Intr" "Introduction"\nForever ago I wanted an email door for ?Express. Nothing was  out\nthere  aside  from  a custom door by RRR. This wasn''t public so I\nstarted on this little effort.\n\nOriginal MoMail used some godforsaken programming to allow a  BBS\nto  have  ''unlimited  email addresses'' using a server-assigned IP\naddress.  Those  with  static  addresses  (Demon   Net/Freeserve)\nshould  use  this  version.  In  fact,  you  should  get a static\naddress simply to use this version. MoMail17.lha has  been  found\nbuggy  and  unusable.  I  *may*  fix  this in future, but lack of\nfeedback on the project forced me to ditch it.\n\nAnywayz, let us continue with this new version...\n\n@endnode\n@node "spec" "Specifications"\nMo-Email is currently running on my:  A1200/020/882\n                                      10 Meg RAM\n                                      85 Meg Drive\n                                      /X version 4.#?\n                                      YAM 2.00 Preview 7\n\nWhether this will work on other versions of /X, I have no idea.\nWill it work on other systems? Fame/S!x/DayDream? I don''t know.\nI only have the above to test it on.\n\n@endnode\n@node "Impo" "Important!"\nAnyone on the BBS using split names will become hyphenated:\n\n IE: ''The Count'' becomes ''The-Count''\n\nElse they do not have a valid email address.\n\nAs  you  know,  any incoming mail contains a shitload of crap and\ninformation as a header. Routines make sure  the  user  does  not\nhave  to read through all this rubbish. If a user has been sent a\nmessage that has an attached file then  all  encoded  information\nwill  be  cut,  else  it will scroll and scroll to infinity. This\nwill not happen if the attached file is a simple text file.\n\nKILL:\nI agonised over this for days. Finally came  up  with  this  lame\nidea  for  deleting  mail.  It  deletes all current mail for that\nuser. They have chances to download etc. It will ask whether  the\nuser wants to KILL the mail yet (or not). It works just fine  and\nI see no reason to update it ever. If a user chooses to  download\nthe  current-read  message  then  it will be named ''07743.001'' or\nwhatever name YAM has assigned to it.\n\nIf  the door is in use then no other node can access their email,\nhaving  to  wait until userX is finished. Simultaneous use of YAM\nscanning etc could result in hassle. Or so I theorise.\n\n@endnode\n@node "auth" "Contact"\nContact:   [email removed]\nBBS:       (UK) 01536-744-639 (After 10pm please - offline soon)\n\nOnce again, no bitching about this program. It''s been a swine  to\nprogram  especially  with  YAM undergoing a major change from 1.x\nto 2.0. That was a swine. Neither am  I  heads-up  on  the  Arexx\nscore. But nobody else would do it, so hey.\n\n@endnode\n@node "inst" "Getting this fucker to work..."\n(1) You must make sure that RexxMast/RPStart is running to allow\nuse of AIM(Rexx) doors in AmiExpress.\n\n(2) Copy all files from archive to where they should be.\n\n(3) Find ''doors:email/email.info'' and change tooltypes to suit\n    your system:\n\n    DOMAIN=funky.demon.co.uk etc:)\n\n    FOLDER=Which folder in YAM you wish to use. If you currently\n    have only four folders then add another. YAM will call this\n    folder 4 (the first folder is 0). This is where all mail TO\n    BBS users is stored. Any mail they write goes to ''outgoing''.\n\n    SIGNATURE=Open your YAM config and go to:\n              ''signature/default signature''\n              Clicking this twice will change it to:\n              ''Alt signature #2''\n\n              Careful, as signature 0 = no signature, so\n              ''alt. signature #2'' is 4. Okay!\n\n    REGGEDTO=Your BBS name/whatever\n\n\n(4) Make sure you have the following files in your ''C:'' dir:\n\n    C:waitforport\n    C:delete\n\nThe above MUST be in C: You may  already  have  ''waitforport''  in\nREXXC but it MUST exist here also.\n\n(4) Check for these in ''LIBS:''\n\n    rexxsyslib.library\n    rexxtricks.library [©Jurgen Kohrmeyer 1994/95]\n    rexxsupport.library\n\n(5) Add ''~CC_MOSEARCH|'' to your logon script so users  can  check\nfor awaiting mail while logging on.\n\n(7)  Try and keep YAM running. If YAM is not present when a user\nwants it then the program will load it. Which may bug the fuck.\n\n(8) You as sysop will be in control of  sending/receiving  mail.\nDo  this  when  you want. Every day/every other day. Your choice.\nThere could be a program written  (independant  of  MoMail)  that\nwill send Miami/YAM online and check for mail.\n\n(9)  You  may  have  to  change the rexx scripts to suit your\n      needs, as it currently loads YAM as follows:\n\n "run ''YAM:YAM PREFSFILE=YAM:.config MAILDIR=YAM: NOCHECK HIDE''"\n\n PREFSFILE=the main config for your YAM program\n MAILDIR=the directory that holds all your incoming/etc folders.\n\nIf you run YAM yourself (without the  need  for  the  program  to\ncall  it)  then  make  sure  you  use the same config as mine, as\nabove. YAM must be where the folders  are  and  the  config  file\nmust be called ''.config''.\n@endnode\n\n@node "Upda" "Updates..."\nv2.04  -  File attach removed. Giving me too much shit and I haven''t\n          the patience to sort it right now:(\n\n          ***MAJOR OVERHAUL*** of entire program:\n\n          First thing you notice is lack of files. Well, I finally\n          found a way to address YAM as well as AEREXXCONTROL-etc\n          so everything is in one file now, excluding the logon-email\n          check rexx.\n\n          ***Basically, ditch old files and re-install***\n          ***This won''t happen again, I dearly promise***\n\n          ;)\n\n          Tooltypes added for ease. Rexxtricks and Rexxsupport library\n          have totally saved this program. Not all of the original C:\n          commands are needed now. Go through installation docs again.\n\n          Signature now uses the inbuilt YAM sig creator.\n\n          Other node using MMail/lost carrer users etc all\n          reprogrammed.\n\n          All programming texts tidied up.\n\n          Please see also: @{" KNOWN BUGS " link BUGS }\n\nv2.03  -  File Attach added. This needs some serious testing.\n          I''ve not had any problems, aside from the fact that any\n          uploaded file needs to be one word. Split filename will\n          result in ''file already exists'' but the program will\n          carry on happily, not attaching anything.\n          Put a file in ''doors:email/'' called ''NoAttach'' and\n          this function will be disabled. Any file. If a user\n          uploads multiple files then only the first is used.\n\n          If no mail is there for the user then a different\n          message will be displayed.\n\n          Overall: I am very happy with this proggy, even though it\n          looks ''tacked together in a day''. Learning more and more about\n          Arexx - use of libs etc. I find that ''makedir'' ''delete'' etc are\n          all part of rexxsupport.library. The less ''outside'' files I have\n          to use, the better.\n\n          Please see also: @{" KNOWN BUGS " link BUGS }\n\nv2.02  -  MoMail  not  bothered  now  by uppercase/lowercase. The\n          email will be read by ''sAFRA'' or ''safra''...etc.\n          Used rexxtricks.library to achieve this.\n          Yes, there was probably an easier way, but.\n\n          Hyphenation of user name if a split word prog routine\n          changed. I had some nightmare check routine which has\n          been replaced by a built-in Arexx function. Likely there\n          are a million more built-in functions that could reduce\n          this whole program to ten lines long, damn it.\n\n          Aside from the check for ''@'' in any entered email address\n          also added is the check to make sure there are no spaces.\n\n          Layout changes. New main menu.\n\n          Guide re-written. All UPDATE info now within.\n\n          Filename change to MMail20x.lha\n          Old filename was 13 chars long.\n          Which is not allowed when upping to an /X board.\n          Oh man, a bug in the file name. Sickening.\n          I''m sure some god is laughing at me.\n\n          Counter on ''readmail''. ''Message 1 of 3'' etc. Cheap.\n\n          ''Format SYS:'' command implemented via ''ZZ'' command on main.\n          Then pressed by accident.\n          Re-wrote whole program from scratch.\n\nv2.01 - Another rush release. Must stop.\n\nv2.00 - Rushed release. Shouldn''t have. Idiot.\n@endnode\n@node "Bugs" "Those feckin crawlies..."\nPossible problems with YAM aliases. All addresses can be resolved\nusing the addrresolve command. Fuck knows how.\n\nAny problems, gimme a shout.\n@endnode\n','\n',char(10)),NULL,'auto-added',29186,4,0,NULL,NULL,'mmail204','scan',1780048612);
INSERT INTO door_catalog VALUES('mmail205','MMAIL205.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MMAIL205.LHA',NULL,'XIM','sonnenbrand.exe',NULL,NULL,NULL,':  Mo-Mail v2.05 - Beta Final - Safra ''99  : +------------------------------------------+ :         : AmiExpress 4.xX                :',replace('.------------------------------------------.\n:  Mo-Mail v2.05 - Beta Final - Safra ''99  :\n+------------------------------------------+\n:         : AmiExpress 4.xX                :\n:Requires : Yam 2.00 Preview 7+            :\n:         : Static IP Internet Account     :\n+------------------------------------------+\n:   100% Arexx Door - 100% Public Domain   :\n`------------------------------------------''\n','\n',char(10)),'Mo-Email.Guide',replace('@database Mo-Email.Guide\n@$VER: Mo-E-Mail (v2.05)\n@author "Safra"\n\n@node "Main" "mO-eMAIL dOCS"\n\n              @{b}==============================================\n               mO-eMAIL - v2.05 - STATIC IP VERSION - sAFRA\n              ==============================================@{ub}\n\n              @{" Introduction                  " link "Intr"}  -  mO-eMAIL!\n              @{" Installation                  " link "inst"}  -        gO!\n              @{" What it does                  " link "impo"}  -   dETAILS!\n              @{" Contact                       " link "auth"}  -   cONTACT!\n              @{" Known Bugs                    " link "bugs"}  -   rECHECK!\n              @{" Disclaimer                    " link "disc"}  -   nOsUEmE!\n\n              @{" Updates                       " link "upda"}  -     sMILE!\n              @{" Credits                       " link "cred"}  -    tHANKS!\n              @{b}==============================================\n              [AREXX-DOOR-AREXX-DOOR--AREXX-DOOR-AREXX-DOOR]\n              ==============================================\n@endnode\n\n@node "Intr" "Introduction"\nForever ago I wanted an email door for ?Express. Nothing was  out\nthere  aside  from  a custom door by RRR. This wasn''t public so I\nstarted on this little effort.\n\nOriginal MoMail used some godforsaken programming to allow a  BBS\nto  have  ''unlimited  email addresses'' using a server-assigned IP\naddress.  Those  with  static  addresses  (Demon   Net/Freeserve)\nshould  use  this  version.  In  fact,  you  should  get a static\naddress simply to use this version. MoMail17.lha has  been  found\nbuggy and unusable. I never got around to fixing it.\n\nMo-Mail is public domain. If you decide to copy it, be my  guest.\nCopy  the  entire  code,  do  what  you  want but do NOT make any\nattempt to remove/update my version on Aminet/elsewhere. Even  if\nyou  make  a  near-direct  copy of this - make sure you give it a\nname of your own! That''s all I ask. Thank you.\n\n@endnode\n@node "spec" "Specifications"\nMo-Email is currently running on my:  A1200/020/882\n                                      10 Meg RAM\n                                      85 Meg Drive\n                                      /X version 4.#?\n                                      YAM 2.00 Preview 7\n\nWhether this will work on other versions of /X, I have no idea.\nWill it work on other systems? Fame/S!x/DayDream? I don''t know.\nGood answers.\n\n@endnode\n@node "Impo" "Important!"\nAnyone on the BBS using split names will become hyphenated:\n\n IE: ''The Count'' becomes ''The-Count''\n\nElse they do not have a valid email address.\n\nKILL:\nI agonised over this for days. Finally came  up  with  this  lame\nidea  for  deleting  mail.  It  deletes all current mail for that\nuser. They have chances to download etc. It will ask whether  the\nuser wants to KILL the mail yet (or not). It works just fine  and\nI see no reason to update it ever. If a user chooses to  download\nthe  current-read  message  then  it will be named ''07743.001'' or\nwhatever name YAM has assigned to it.\n\nIf  the door is in use then no other node can access their email,\nhaving  to  wait until userX is finished. Simultaneous use of YAM\nscanning etc could result in hassle. Or so I theorise.\n\nPlease read the updates text for more info.\n\n@endnode\n@node "auth" "Contact"\nContact:   [email removed]\nBBS:       (UK) 01536-744-639 (After 10pm please - offline soon)\n\nOnce again, no bitching about this program. It''s been a swine  to\nprogram  especially  with  YAM undergoing a major change from 1.x\nto 2.0. That was a swine. Neither am  I  heads-up  on  the  Arexx\nscore. But nobody else would do it, so hey.\n\n@endnode\n@node "inst" "Getting this sod to work..."\n(1) You must make sure that RexxMast/RPStart is running to allow\nuse of AIM(Rexx) doors in AmiExpress.\n\n(2) Copy all files from archive to where they should be.\n\n(3) Find ''doors:email/email.info'' and change tooltypes to suit\n    your system:\n\n    DOMAIN=    funky.demon.co.uk etc:)\n\n    FOLDER=    Which folder in YAM you wish to use. If you currently\n               have only four folders then add another. YAM will call this\n               folder 4 (the first folder is 0). This is where all mail TO\n               BBS users is stored. Any mail they write goes to ''outgoing''.\n\n    SIGNATURE= Open your YAM config and go to:\n               ''signature/default signature''\n               Clicking this twice will change it to:\n               ''Alt signature #2''\n\n               Careful, as signature 0 = no signature, so\n               ''alt. signature #2'' is 4. Okay!\n\n    REGGEDTO=  Your BBS name/whatever\n\n    PREFSFILE= Where your main YAM config is located.\n               Usual is - ''YAM:.config''\n\n    MAILDIR=   Where your YAM folders (incoming/outgoing/etc) are\n               located. Usual is - ''YAM:''\n\n    ATTACH=    yes or no - Disable/Enable file attach function.\n\n(4) Make sure you have the following files in your ''C:'' dir:\n\n    C:waitforport\n    C:delete\n\nThe above MUST be in C: You may  already  have  ''waitforport''  in\nREXXC but it MUST exist here also.\n\n(5) Check for these in ''LIBS:''\n\n    rexxsyslib.library\n    rexxtricks.library\n    rexxsupport.library\n\n(6) Add ''~CC_MOSEARCH|'' to your logon script so users  can  check\nfor awaiting mail while logging on.\n\n(7)  Try and keep YAM running. If YAM is not present when a user\nwants it then the program will load it. Which may bug the fuck.\n\n(8) You as sysop will be in control of  sending/receiving  mail.\nDo  this  when  you want. Every day/every other day. Your choice.\nThere could be a program written  (independant  of  MoMail)  that\nwill send Miami/YAM online and check for mail.\n\n(9) If you decide to run YAM before running this door then please\nmake sure your config file etc is the same as the door tooltypes.\n@endnode\n\n@node "Upda" "Updates..."\nv2.05  -  Another big update. This is definately the BETA FINAL.\n          It has enough functions.\n          But of course, mail me with problems/ideas.\n\n          Alias problem sorted. If...\n          ''[email removed]''\n          ...received a mail addressed to:\n          ''Safra Coerlin <[email removed]>''\n          ...then previously the ''alias (Safra Coerlin)'' would have\n          made this an unknown email. Safra would not get it.\n          Routine changed to remove this bug.\n\n          YAM ''prefsfile'' and ''maildir'' now added to tooltypes\n          in case anyone uses a strange system setup.\n\n          MOSEARCH will not load YAM now. If a user is logging on\n          in a hurry, they don''t wanna sit there and wait for your YAM\n          to load if they don''t care about email. Basically, this little\n          fix has saved your life/made you friends. Your welcome.\n\n          Abort message routine sorted.\n\n          Notice a linespace between ''Send to:'' and ''Subject'' when\n          writing mail. For some reason, when the two lines are together,\n          the letter ''m'' appears in the ''subject'' input. Two hours to\n          fucking spot this thing. Only happened with certain ''Send to:''\n          addresses. IE: ''Send to: [email removed]'' - strange.\n\n          WriteAttach exists again. Enable/Disable via tooltype.\n          Problem of filenames with spaces still exists. Routine to check\n          for spaces or ''#?.info'' files brings up a message explaining\n          to the user regarding failure.\n\n          Readmail feature now uses YAM routines. It''s a little slower\n          but YAM will split headers/attachments/plaintext - which is\n          easier for handling.\n\n          Reply feature now quotes original message.\n\n          About screen changed.\n\n          Previous update said no major changes would take place.\n          I promised aswell. What can I say?\n          ''You can say sorry, you bastard.''\n          ''Sorry.''\n          ''Man, that was insincere...''\n\n          Anyway, this version can be spread.\n          I''m gonna sit back and check this thing through again.\n          While waiting for other bug reports.\n\nv2.04  -  File attach removed. Giving me too much shit and I haven''t\n          the patience to sort it right now:(\n\n          ***MAJOR OVERHAUL*** of entire program:\n\n          First thing you notice is lack of files. Well, I finally\n          found a way to address YAM as well as AEREXXCONTROL-etc\n          so everything is in one file now, excluding the logon-email\n          check rexx.\n\n          ***Basically, ditch old files and re-install***\n          ***This won''t happen again, I dearly promise***\n\n          ;)\n\n          Tooltypes added for ease. Rexxtricks and Rexxsupport library\n          have totally saved this program. Not all of the original C:\n          commands are needed now. Go through installation docs again.\n\n          Signature now uses the inbuilt YAM sig creator.\n\n          Other node using MMail/lost carrer users etc all\n          reprogrammed.\n\n          All programming texts tidied up.\n\nv2.03  -  File Attach added. This needs some serious testing.\n          I''ve not had any problems, aside from the fact that any\n          uploaded file needs to be one word. Split filename will\n          result in ''file already exists'' but the program will\n          carry on happily, not attaching anything.\n          Put a file in ''doors:email/'' called ''NoAttach'' and\n          this function will be disabled. Any file. If a user\n          uploads multiple files then only the first is used.\n\n          If no mail is there for the user then a different\n          message will be displayed.\n\n          Overall: I am very happy with this proggy, even though it\n          looks ''tacked together in a day''. Learning more and more about\n          Arexx - use of libs etc. I find that ''makedir'' ''delete'' etc are\n          all part of rexxsupport.library. The less ''outside'' files I have\n          to use, the better.\n\nv2.02  -  MoMail  not  bothered  now  by uppercase/lowercase. The\n          email will be read by ''sAFRA'' or ''safra''...etc.\n          Used rexxtricks.library to achieve this.\n          Yes, there was probably an easier way, but.\n\n          Hyphenation of user name if a split word prog routine\n          changed. I had some nightmare check routine which has\n          been replaced by a built-in Arexx function. Likely there\n          are a million more built-in functions that could reduce\n          this whole program to ten lines long, damn it.\n\n          Aside from the check for ''@'' in any entered email address\n          also added is the check to make sure there are no spaces.\n\n          Layout changes. New main menu.\n\n          Guide re-written. All UPDATE info now within.\n\n          Filename change to MMail20x.lha\n          Old filename was 13 chars long.\n          Which is not allowed when upping to an /X board.\n          Oh man, a bug in the file name. Sickening.\n          I''m sure some god is laughing at me.\n\n          Counter on ''readmail''. ''Message 1 of 3'' etc. Cheap.\n\n          ''Format SYS:'' command implemented via ''ZZ'' command on main.\n          Then pressed by accident.\n          Re-wrote whole program from scratch.\n\nv2.01 - Another rush release. Must stop. No. Make me. Punch. Oh, okay.\n\nv2.00 - Static vers. Rushed release. Shouldn''t have. Idiot.\n\nv1.07 - Dyn-vers. ...this on BBS''s still. Yikes. Delete!\n\nv1.06 - Dyn-vers. ...and...\n\nv1.05 - Dyn-vers. See this...\n\nv1.04 - Dynamic version. Oh dear me.\n\n\n@endnode\n@node "Bugs" "Those feckin crawlies..."\nNothing to report right now.\nAny problems, gimme a shout.\n@endnode\n@node "disc" "This is entirely...not my fault."\nDISCLAIMER!\n\nWith  this  document  I  make  no  warranties  or  representations,  either\nexpressed  or  implied,  with  respect to the program described herein. The\nprogram  and  the  information presented herein is being supplied on an `as\nis''  basis  and  is  expressly subject to change without notice. The entire\nrisk  as to the use of the program and the information presented is assumed\nby the user. In no event will I be liable for direct, indirect, incidental,\nor consequential damages resulting from any claim arising out of the use of\nthe program or the information presented herein.\n@endnode\n\n@node "cred" "Ladies and Gentlemen, presenting..."\nMarcel Beck    - Author of YAM and helper via [email removed] :)\nAminet scripts - Countless. Many many excellents sources of info.\nPepsi          - Total addiction.\nSmokes         - Foreign ciggs. UK prices take the total piss.\n\n\n\n@endnode\n','\n',char(10)),NULL,'auto-added',30714,4,0,NULL,NULL,'mmail205','scan',1780048612);
