INSERT INTO door_catalog VALUES('mmh_gs13','MMH-GS13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MMH-GS13.LHA','gRAPEsTATS','XIM','LE-win5-96.exe',NULL,NULL,'MMH','|    .    l    .  l___  | ____| P¡GeøN |   | \    \  | \   _/  |   /     oF --|   |  \    ) |  \  |   .   \.-MeTAMoRPH',replace('_ _._________._______._____._____.__\n   |    .    l    .  l___  | ____| P¡GeøN\n   |   | \    \  | \   _/  |   /     oF\n --|   |  \    ) |  \  |   .   \.-MeTAMoRPH\n   |   l__/  ./  l__/  |   |    ) pRESENTS\n_ _l____/l___l____/l___pGN_l___/_ _ _\n        --^-gRAPEfRUITsTATS v1.0-^--\n a sTATUSdOOR fOR aMIeXPRESS 3.× aND aBOVE!\n   iT hAS aLL yOU eVER dREAMT oF aND mORE','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                                                .------''\n             `------------------------------------------------''\n','\n',char(10)),NULL,'auto-added',12093,5,0,NULL,NULL,'mmh_gs13','scan',1780048612);
INSERT INTO door_catalog VALUES('mnt_sd22','MNT_SD22.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MNT_SD22.LHA','SnatchDIZ','XIM','SnatchDIZ',NULL,NULL,'MNT','___ __ :__    :    ___ : : : : __  _(___)  \|\/  __|__ / __|| |_| |______ |  \/ |   | \ \  \ \/|__) / _ |  _  |     /',replace('=[ MiDNiGHT ]=:      :========: :=: :=====>\n       ___ __ :__    :    ___ : : : :\n __  _(___)  \|\/  __|__ / __|| |_| |______\n|  \/ |   | \ \  \ \/|__) / _ |  _  |     /\n|     l___|_/ /  |\__|  ||_| || | | | _._/:\nl__|l__| l___/|  |  l___l____|l_| l_|  |  :\n:=[pResENtS]==l__|bSt===============l__|==:\n| SnatchDIZ - FILE_ID.DIZ extractor with  |\n|    LHA, LZX, ZIP, DMS, EXE, GIF, TXT    |\n|     support - smaller than 3 KB and     |\n|  faaaaaaaaaaaaaaaaaaaaast (1oo% asm)!   |\n`-[aMiGA-sECTioN-miDNiGhT-wHq]------[1/1]-''','\n',char(10)),'SnatchDIZ.guide',replace('@database\n@node main "SnatchDIZ V2.2 docs"\n@{b}                    _         _         _         _         _\n              _____/ \_______/ \_______/ \_______/ \_______/ \___ __ _\n            _/  __/   \_____/   \_____/   \_____/   \_____/   \_//_///\n            \______    \   |     \   |     \   |     \   |     \\n     _ __ _/     \/     \_ .      \_ ·      \_ ·      \_ |      \_\n     \\\_\\_______       /_|       /__       /__       /_|       /\n      ------m!^DG|______/--|______/--|______/--|______/--|______/----@{ub}\n               @{fg highlight}SnatchDIZ V2.2 - © by rASCAL/SHOOT on 19.7.95@{fg text}\n\n\n			    @{"    Purpose     " link 1}\n			    @{"     Usage      " link 2}\n			    @{"  Requirements  " link 3}\n			    @{"   Greetings    " link 4}\n			    @{"    History     " link 5}\n\n                 @{b}kEEP tHE aMIGA aLIVE aND ... lEGALIZE iT!@{ub}\n\n@endnode\n@node 1 "What the fuck..."\n\nSnatchDIZ  is  another  FILE_ID.DIZ extractor for the Shell or for use with\nany bbs-system.  Features:\n\n - LHA-, LZX-, ZIP-, DMS-, EXE-, GIF-, TXT-support\n - SnatchDIZ is smaller than 3 KB and faaaaaaaaaaaaaaaaaaaast (1oo% asm)!\n - great code: SnatchDIZ does not produce HITS like WhaDIZ, SpeeDIZ etc.\n - reentrant (can be made resident)\n - good error handling: no problems with empty files or something\n\n-=> Use SnatchDIZ instead of all the other crap floating around!\n@endnode\n@node 2 "It''s easy..."\n\nUsage: SnatchDIZ FILE/A,S=SUPPRESS/S\n=====================================\n\nFor example:  "SnatchDIZ dh0:down/PPLAY41.LZX S K" will give you\n\n--------------------------------------\nPower Player 4.1 Final Omega Version\n* Latest Update! *\n--------------------------------------\n\nThis extracts and shows the file_id.diz and suppresses the credits and the\nfiletype indicator.\n\nWARNINGS: - SnatchDIZ is cli-only so don''t start from Workbench!\n@endnode\n@node 3 "You got this crap..."\n\nYou need:\n\n - an AMIGA w/Kick 2.04+ (as always).\n - the lha-, lzx- and UNzip-executable placed in your path.\n   A working UNzip is included in the SnatchDIZ-archive.\n\nThat''s it.\n@endnode\n@node 4 "Hallöle to..."\n\n                             all SHOOT members\n                                 CAFFEiNE\n                                   OMEN\n        STEELER and the rest/PHANTASM (thanks for the bug reports)\n                                Flake/TRSI\n                               MAVE/CRYSTAL\n@endnode\n@node 5 "Versions..."\n\nV0.9:	- not released but seems to work properly.\n\nV1.0:	1st release, 31.3.95 (CAFFEINE)\n	- added filetype indicator and the SUPPRESS option.\n	- 1st release (under CAFFEiNE label)!\n\nV2.0:	2nd release, 19.4.95 (SUPREME)\n	- added own routine for search in DMSs (MUCH FASTER than DMS VIEWDIZ)\n	- optimzed search in executables A LOT!\n\nV2.1:	(no public release)\n	- added own routine for search in GIFs (MUCH FASTER than GIFDESC)\n	- SnatchDIZ is now reentrant and can be made resident (PURE option)\n	- removed KEEPDIZ option because it was unnecessary at all\n	- now checks if dos.library is >= V36\n	- no longer crunched. V2.0 sometimes crashed on 040 systems due to\n	  the used packer (CrunchMania V1.9)\n\nV2.2:	3rd release, 19.7.95 (SHOOT) :-)\n	- fixed bug with filenames containing spaces/wildcards\n	- I was told SnatchDIZ even handles JPGs, check it out yourself\n@endnode\n','\n',char(10)),NULL,'auto-added',7657,5,0,NULL,NULL,'mnt_sd22','scan',1780048612);
INSERT INTO door_catalog VALUES('mo_ab10','MO-AB10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MO-AB10.LHA',NULL,'XIM','.------------------------------------------.',NULL,NULL,'MO',':       Mo-AddBBS v1.00 - Safra 1999       : +------------------------------------------+ :   100% Arexx Door - 100% Public Domain   :',replace('.------------------------------------------.\n:       Mo-AddBBS v1.00 - Safra 1999       :\n+------------------------------------------+\n:   100% Arexx Door - 100% Public Domain   :\n`------------------------------------------''\n','\n',char(10)),'MoAddBBS.doc',replace('MoAddBBS v1.00 - sAFRA 1999\n~~~~~~~~~~~~~~~~~~~~~~~~~~~\nSimple and quick door to add bbs to logoff. It  could  have  been\nmuch  more,  but the sysop can deal with the rest of the work. If\nyou need to edit it then dive into the output file  with  a  text\neditor. Not much hassle.\n\nBreak  lines  between  each  entry can be removed, go through the\nrexx script until you find the relevant comments.\n\nIf  the  headerfile  is  not  there then it won''t be added to the\noutput. Output file can be renamed  to  ''bbs:screens/logoffx.txt''\nor whatever. 100% public domain as always.\n\nReason  for this door, knowing others exist out there, is because\ncertain others have a first entry  of  the  author''s  BBS,  which\ntotally fucking sucks.\n\nNo libraries needed. Tested on /X 4.12-68020/882.\n\nDo I sound pissed off? Yeah.\n\nContact:\n~~~~~~~~\[email removed]\n\n','\n',char(10)),NULL,NULL,7574,1,0,NULL,NULL,NULL,'scan',1780048612);
INSERT INTO door_catalog VALUES('mo_ad11','MO-AD11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MO-AD11.LHA',NULL,'XIM','.------------------------------------------.',NULL,'Time/Date','MO',':  Mo-Text-Add v1.01 (BETA)  - sAFRA 1999  : +------------------------------------------+ :     > ULName/ULLoca/Time/Date/Node <     :',replace('.------------------------------------------.\n:  Mo-Text-Add v1.01 (BETA)  - sAFRA 1999  :\n+------------------------------------------+\n:     > ULName/ULLoca/Time/Date/Node <     :\n:     > ULPhoneNo/ULAccsLvl/FileName <     :\n+------------------------------------------+\n:         Requires AmiExpress 4.xX         :\n+------------------------------------------+\n:   100% Arexx Door - 100% Public Domain   :\n`------------------------------------------''\n','\n',char(10)),'Mo-AD11.readme',replace('Short    : Adder for text files (AREXX)\nAuthor   : Safra Jameson <[email removed]>\nUploader : Safra Jameson <[email removed]>\nVersion  : 1.01\nType     : comm/amiex\n\nAdds header/tailer to txt/nfo/etc.\nSpecial functions.\n','\n',char(10)),NULL,NULL,6439,2,0,NULL,NULL,NULL,'scan',1780048612);
INSERT INTO door_catalog VALUES('mo_ai11','MO-AI11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MO-AI11.LHA',NULL,'XIM','.------------------------------------------.',NULL,NULL,'MO',':    Mo-Intelligence v1.01 - sAFRA 1999    : +------------------------------------------+ : Looks like a pager door until the sysop  :',replace('.------------------------------------------.\n:    Mo-Intelligence v1.01 - sAFRA 1999    :\n+------------------------------------------+\n: Looks like a pager door until the sysop  :\n:  answers. Then things aren''t what they   :\n:  appear to be. A total funk-piss-take.   :\n+------------------------------------------+\n:         Requires AmiExpress 4.xX         :\n+------------------------------------------+\n:   100% Arexx Door - 100% Public Domain   :\n`------------------------------------------''\n','\n',char(10)),'Mo-Intel.Guide',replace('@database Mo-Intel.Guide\n@$VER: Mo-Intel (v1.01)\n@author "Safra"\n\n@node "Main" "mO-InTel dOCS"\n\n              @{b}==============================================\n                   mO-iNTELLIGENCE - v1.01 - sAFRA 1999\n              ==============================================@{ub}\n\n              @{" Introduction                                " link "Intr"}\n              @{" Installation                                " link "inst"}\n              @{" What it does                                " link "impo"}\n              @{" Contact                                     " link "auth"}\n              @{" Known Bugs                                  " link "bugs"}\n              @{" Disclaimer                                  " link "disc"}\n\n              @{" Updates                                     " link "upda"}\n              @{b}==============================================\n              [AREXX-DOOR-AREXX-DOOR--AREXX-DOOR-AREXX-DOOR]\n              ==============================================\n@endnode\n\n@node "Intr" "Introduction"\nI once saw a door on a MAXs  board  that  let  you  talk  to  the\nsysop.  Of course, it wasn''t the fecking sysop at all, and I left\ncrying. So, here is a version of  that  for  AmiExpress.  A  fake\npager  door is first activated, followed by the sysop breaking in\nfor a natter - via a fake chat.\n@endnode\n@node "spec" "Specifications"\nMo-Email is currently running on my:  A1200/020/882\n                                      10 Meg RAM\n                                      85 Meg Drive\n                                      /X version 4.#?\n@endnode\n@node "Impo" "Important!"\nBasically  it''s  as  clever as your .DAT files, some of which are\nsupplied. It will read a  user''s input  and  respond  accordingly\n(well,  in  a  simple  pattern-matching  way).  It  will give the\nappearance of the sysop typing via  the  RAND/DELAY  commands  in\nArexx.  A  different delay value between each character appearing\non screen etc. This can be adjusted.\n\nAll    entered  text  from  the  sysop/victim  is  saved  into  a\ntime-stamped text file for later public humiliation.\n\nAs usual, Mo-products are  public  domain.  I  don''t  believe  in\nshareware.  Emailware  is  cool though, as I would like to read a\nfew Mo-Intelligence saved-responses:)\n@endnode\n@node "auth" "Contact"\nContact:   [email removed]\nBBS:       (UK) 01536-744-639 (After 10pm please - offline soon)\n@endnode\n@node "inst" "Getting this sod to work..."\n(1) Copy all files to where they should  be,  renaming  the  main\ncommand  icon if necessary. Cool people will rename it to ''o'' and\nreplace their existing pager, which will be renamed to  something\nnon-lamers will know.\n\n(2)  Go  through  the ''die.rexx'' text and look for comments. This\nwill allow you to change the speed at which the sysop types,  how\nmany lines he will type before leaving etc.\n\n(3) Ermmmmm...:)\n\n\n(4) Libraries needed:\n    rexxtricks.library   - here\n    rexxsyslib.library\n    rexxsupport.library  - here\n\nMost important!\nMain  rule:  When  editing the ''#?.DAT'' or ''.cfg'' files make SURE\nthere are NO blank lines in the file when saved, else  this  will\nscrew up responses for the user.\n\nBasically, you can add your own responses to keywords.\n\nThe main file is ''words.cfg'':\n\n hello   greeting.dat\n hiya    greeting.dat\n sunny   weather.dat\n rain    weather.dat\n\nEach line of this cfg file must contain only two words.\n\n(1) Keyword          (2) File to read from (no full path names)\n\nPlay around and you''ll get the idea.\n\nA user''s input is interpreted as follows: The  script  takes  his\nsentence  and  does  a ''matchpattern'' routine for keywords in the\n''words.cfg'' file. If he/she(?) types:\n\n''Hello to you sysop''\n\nThe script will probably find  ''#?hello#?''  and  respond  with  a\nline from the ''greeting.dat'' file.\n@endnode\n@node "Upda" "Updates..."\nv1.01  - FINAL.\n         Sysop leaves when ''he'' wants.\n         Docs rewritten into guide form.\n         Few tweaks here and there.\n\nv1.00  - Written in three hours. Rush released, which is my usual\nstyle of fucking things up. Nothing mentioned in docs on  how  to\nexit the bastard chat. ''EXIT'' was the keyword. Idiot. Apologies.\n@endnode\n@node "Bugs" "Those feckin crawlies..."\nSometimes  keywords and their matching filenames fail to give the\ncorrect response. Try  changing  their  order  in  the  words.cfg\nlist.  It  may work. Not a problem. This whole door is just a bit\nof fun and not to be taken seriously. Damn it.\n\nNote: The following doesn''t always work. Might work once  in  any\n      given line of text. Unknown why.\n\nYou can give the appearance of the sysop making a typo  by  using\nAnsi  Control  Char:  *[1D  - where ''*'' is the escape code thang.\nYou know, it looks like  a  little  box.  Get  this  by  pressing\nLEFTAMIGA+ESCAPE  - which usually exits the editor program you''re\nrunning because they never gave this any thought, damn it. Hehe.\n\nSo, the following will type ''sabfra''...\n...then ''delete'' the ''b'' and turn it into ''safra'':\n\nsab*[1Dfra\n@endnode\n@node "disc" "You trashed my drive, you bastard."\nDISCLAIMER!\n\nWith  this  document  I  make  no  warranties  or  representations,  either\nexpressed  or  implied,  with  respect to the program described herein. The\nprogram  and  the  information presented herein is being supplied on an `as\nis''  basis  and  is  expressly subject to change without notice. The entire\nrisk  as to the use of the program and the information presented is assumed\nby the user. In no event will I be liable for direct, indirect, incidental,\nor consequential damages resulting from any claim arising out of the use of\nthe program or the information presented herein.\n@endnode\n','\n',char(10)),NULL,NULL,10171,3,0,NULL,NULL,NULL,'scan',1780048612);
INSERT INTO door_catalog VALUES('mo_dn10','MO-DN10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MO-DN10.LHA',NULL,'XIM','.------------------------------------------.',NULL,NULL,'MO',':      Mo-Down v1.00 (BETA)- sAFRA ''99     : +------------------------------------------+ :       Download Directory Listing(s)      :',replace('.------------------------------------------.\n:      Mo-Down v1.00 (BETA)- sAFRA ''99     :\n+------------------------------------------+\n:       Download Directory Listing(s)      :\n+------------------------------------------+\n:         Requires AmiExpress 4.xX         :\n+------------------------------------------+\n:   100% Arexx Door - 100% Public Domain   :\n`------------------------------------------''\n','\n',char(10)),'Mo-Down.Guide',replace('@database Mo-Down.Guide\n@$VER: Mo-Down (v1.00)\n@author "Safra"\n\n@node "Main" "mO-dOWN dOCS"\n\n              @{b}==============================================\n                        mO-dOWN - v1.00 - sAFRA 1999\n              ==============================================@{ub}\n\n              @{" Introduction                                " link "Intr"}\n              @{" Installation                                " link "inst"}\n              @{" What it does                                " link "impo"}\n              @{" Contact                                     " link "auth"}\n              @{" Known Bugs                                  " link "bugs"}\n              @{" Disclaimer                                  " link "disc"}\n\n              @{" Updates                                     " link "upda"}\n              @{b}==============================================\n              [AREXX-DOOR-AREXX-DOOR--AREXX-DOOR-AREXX-DOOR]\n              ==============================================\n@endnode\n\n@node "Intr" "Introduction"\nThis  will allow a user to download directory listings from their\ncurrent conference. Difference between this and  other  doors  is\nthat  it  will  send  the  user renamed files. It won''t just send\n''DIR1'' text file. It''ll be called ''XPressSupport1'' or whatever.\n@endnode\n@node "spec" "Specifications"\nMo-Email is currently running on my:  A1200/020/882\n                                      10 Meg RAM\n                                      85 Meg Drive\n                                      /X version 4.#?\n@endnode\n@node "Impo" "Important!"\nMoDown gleans all its information from your  current  BBS  icons.\nFirst  it  will check out what conference the user is in. If he''s\nin conference 2 then the script will check out the icon for  that\nparticular conference. IE: (My BBS setup...)\n\nUser in    > 2:Express Support\nReal name  > BBS:Conf2\nChecks     > BBS:Conf2.info\n\n...and finds the ''NDIRS='' tooltype. It it doesn''t exist then  the\nprogram  exits.  If  it has ''0'' the program will exit. I''ve tried\nto think up all fuckhead results from checking this tooltype  and\nbelieve everything is covered.\n\nUser  can then choose which directory listing to download. It can\nbe a single listing or all. Whatever it is it will be  copied  to\n''T:MoDown(user''s-node)/''  -  all  dir  listings  renamed  to  the\ncurrent conference  name  (stripped  of  spaces  and  other  misc\ncharacters) + original dir listing number.\n\nUser  then  chooses  download options. If he chose (ALL) then the\nprogram will fail to activate the packer option ''(4)-NONE''.  This\nonly works for a single listing download.\n\nIf  a  packer  is  chosen then the user waits until it''s done its\nthang, then ''hit a key'' to download. As  directory  listings  are\nall  copied  to  ''T:etc...''  the  system  will appear to be doing\nnothing, but it is packing.\n\n(In Built Stealth Mode Function ® sAFRA 1972)\n\nBut seriously, I have seen another door like  this  on  an  alien\nBBS  system  that  let the user see the status of the packing. As\nif the LHA etc output was piped to the AmiExpress  screen.  Well,\nI  know  little  of  this,  and PIPE, don''t know what I''m talking\nabout, so if anyone DOES...lemme know.\n\nRemember: BETA Tester!\n\n@endnode\n@node "auth" "Contact"\nContact:   [email removed]\nBBS:       (UK) 01536-744-639 (After 10pm please - offline soon)\n\n@endnode\n@node "inst" "Getting this sod to work..."\n(1) Stick all files up yer arse.\n\n(2) Make sure all of these are in C:\n\n    ZIP\n    LZX\n    LHA\n    copy\n    makedir\n    delete\n\nFew people out there still not aware that LHA and LZX are both\nnow freeware. On Aminet. Somewhere.\n\nAminet/comm/utils/gfx/mods/funktracker/scans/net/tcp/lha.zip\n\nHehehehe. Man, I''m easily amused. Bet you''re not.\n\n(3) Read other sections of this docfile.\n\n\n@endnode\n@node "Upda" "Updates..."\nv1.00  - BETA - Possible FINAL.\n\n@endnode\n@node "Bugs" "Those feckin crawlies..."\nNone spotted.\n@endnode\n@node "disc" "You trashed my drive, you bastard."\nDISCLAIMER!\n\nWith  this  document  I  make  no  warranties  or  representations,  either\nexpressed  or  implied,  with  respect to the program described herein. The\nprogram  and  the  information presented herein is being supplied on an `as\nis''  basis  and  is  expressly subject to change without notice. The entire\nrisk  as to the use of the program and the information presented is assumed\nby the user. In no event will I be liable for direct, indirect, incidental,\nor consequential damages resulting from any claim arising out of the use of\nthe program or the information presented herein.\n@endnode\n','\n',char(10)),NULL,NULL,8476,2,0,NULL,NULL,NULL,'scan',1780048612);
INSERT INTO door_catalog VALUES('mo_em26','MO-EM26.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MO-EM26.LHA',NULL,'XIM','.------------------------------------------.',NULL,NULL,'MO',':        Mo-Mail v2.06 - Safra 1999        : +------------------------------------------+ :         : AmiExpress 4.xX                :',replace('.------------------------------------------.\n:        Mo-Mail v2.06 - Safra 1999        :\n+------------------------------------------+\n:         : AmiExpress 4.xX                :\n:Requires : Yam 2.00 Preview 7+            :\n:         : Static IP Internet Account     :\n+------------------------------------------+\n:   100% Arexx Door - 100% Public Domain   :\n`------------------------------------------''\n','\n',char(10)),'Mo-Email.Guide',replace('@database Mo-Email.Guide\n@$VER: Mo-E-Mail (v2.06)\n@author "Safra"\n\n@node "Main" "mO-eMAIL dOCS"\n\n              @{b}==============================================\n               mO-eMAIL - v2.06 - STATIC IP VERSION - sAFRA\n              ==============================================@{ub}\n\n              @{" Introduction                  " link "Intr"}  -  mO-eMAIL!\n              @{" Installation                  " link "inst"}  -        gO!\n              @{" What it does                  " link "impo"}  -   dETAILS!\n              @{" Contact                       " link "auth"}  -   cONTACT!\n              @{" Known Bugs                    " link "bugs"}  -   rECHECK!\n              @{" Disclaimer                    " link "disc"}  -   nOsUEmE!\n\n              @{" Updates                       " link "upda"}  -     sMILE!\n              @{" Credits                       " link "cred"}  -    tHANKS!\n              @{b}==============================================\n              [AREXX-DOOR-AREXX-DOOR--AREXX-DOOR-AREXX-DOOR]\n              ==============================================\n@endnode\n\n@node "Intr" "Introduction"\nForever ago I wanted an email door for ?Express. Nothing was  out\nthere  aside  from  a custom door by RRR. This wasn''t public so I\nstarted on this little effort.\n\nOriginal MoMail used some godforsaken programming to allow a  BBS\nto  have  ''unlimited  email addresses'' using a server-assigned IP\naddress.  Those  with  static  addresses  (Demon   Net/Freeserve)\nshould  use  this  version.  In  fact,  you  should  get a static\naddress simply to use this version. MoMail17.lha has  been  found\nbuggy and unusable. I never got around to fixing it.\n\nMo-Mail is public domain. If you decide to copy it, be my  guest.\nCopy  the  entire  code,  do  what  you  want but do NOT make any\nattempt to remove/update my version on Aminet/elsewhere. Even  if\nyou  make  a  near-direct  copy of this - make sure you give it a\nname of your own! That''s all I ask. Thank you.\n\n@endnode\n@node "spec" "Specifications"\nMo-Email is currently running on my:  A1200/020/882\n                                      10 Meg RAM\n                                      85 Meg Drive\n                                      /X version 4.#?\n                                      YAM 2.00 Preview 7\n\nWhether this will work on other versions of /X, I have no idea.\nWill it work on other systems? Fame/S!x/DayDream? I don''t know.\nGood answers.\n\n@endnode\n@node "Impo" "Important!"\nAnyone on the BBS using split names will become hyphenated:\n\n IE: ''The Count'' becomes ''The-Count''\n\nElse they do not have a valid email address.\n\nKILL:\nI agonised over this for days. Finally came  up  with  this  lame\nidea  for  deleting  mail.  It  deletes all current mail for that\nuser. They have chances to download etc. It will ask whether  the\nuser wants to KILL the mail yet (or not). It works just fine  and\nI see no reason to update it ever. If a user chooses to  download\nthe  current-read  message  then  it will be named ''07743.001'' or\nwhatever name YAM has assigned to it.\n\nIf  the door is in use then no other node can access their email,\nhaving  to  wait until userX is finished. Simultaneous use of YAM\nscanning etc could result in hassle. Or so I theorise.\n\nPlease read the updates text for more info.\n\n@endnode\n@node "auth" "Contact"\nContact:   [email removed]\nBBS:       (UK) 01536-744-639 (After 10pm please - offline soon)\n\nOnce again, no bitching about this program. It''s been a swine  to\nprogram  especially  with  YAM undergoing a major change from 1.x\nto 2.0. That was a swine. Neither am  I  heads-up  on  the  Arexx\nscore. But nobody else would do it, so hey.\n\n@endnode\n@node "inst" "Getting this sod to work..."\n(1) You must make sure that RexxMast/RPStart is running to allow\nuse of AIM(Rexx) doors in AmiExpress.\n\n(2) Copy all files from archive to where they should be.\n\n(3) Find ''doors:email/email.info'' and change tooltypes to suit\n    your system:\n\n    DOMAIN=    funky.demon.co.uk etc:)\n\n    FOLDER=    Which folder in YAM you wish to use. If you currently\n               have only four folders then add another. YAM will call this\n               folder 4 (the first folder is 0). This is where all mail TO\n               BBS users is stored. Any mail they write goes to ''outgoing''.\n\n    SIGNATURE= Open your YAM config and go to:\n               ''signature/default signature''\n               Clicking this twice will change it to:\n               ''Alt signature #2''\n\n               Careful, as signature 0 = no signature, so\n               ''alt. signature #2'' is 4. Okay!\n\n    REGGEDTO=  Your BBS name/whatever\n\n    PREFSFILE= Where your main YAM config is located.\n               Usual is - ''YAM:.config''\n\n    MAILDIR=   Where your YAM folders (incoming/outgoing/etc) are\n               located. Usual is - ''YAM:''\n\n    ATTACH=    yes or no - Disable/Enable file attach function.\n\n    TIME=      The hour that you will do your mail run. If you set\n               it to 22 then that equals 10pm. Therefore\n               MoEmail is not avail during 22 and 23 (10pm and 11pm).\n               Set to 25 or some other non-time number if you wish\n               this function disabled.\n\n(4) Make sure you have the following files in your ''C:'' dir:\n\n    C:waitforport\n    C:delete\n\nThe above MUST be in C: You may  already  have  ''waitforport''  in\nREXXC but it MUST exist here also.\n\n(5) Check for these in ''LIBS:''\n\n    rexxsyslib.library\n    rexxtricks.library\n    rexxsupport.library\n\n(6) Add ''~CC_MOSEARCH|'' to your logon script so users  can  check\nfor awaiting mail while logging on.\n\n(7)  Try and keep YAM running. If YAM is not present when a user\nwants it then the program will load it. Which may bug the fuck.\n\n(8) You as sysop will be in control of  sending/receiving  mail.\nDo  this  when  you want. Every day/every other day. Your choice.\nThere could be a program written  (independant  of  MoMail)  that\nwill send Miami/YAM online and check for mail.\n\n(9) If you decide to run YAM before running this door then please\nmake sure your config file etc is the same as the door tooltypes.\n@endnode\n\n@node "Upda" "Updates..."\nv2.06  -  Mail run time check implemented.\n          See tooltypes configuration guide.\n          Script to send YAM on a mail will be a separate archive.\n          If I write it, that is. It should appear next to this\n          archive on Aminet.\n\nv2.05  -  Another big update. This is definately the BETA FINAL.\n          It has enough functions.\n          But of course, mail me with problems/ideas.\n\n          Alias problem sorted. If...\n          ''[email removed]''\n          ...received a mail addressed to:\n          ''Safra Coerlin <[email removed]>''\n          ...then previously the ''alias (Safra Coerlin)'' would have\n          made this an unknown email. Safra would not get it.\n          Routine changed to remove this bug.\n\n          YAM ''prefsfile'' and ''maildir'' now added to tooltypes\n          in case anyone uses a strange system setup.\n\n          MOSEARCH will not load YAM now. If a user is logging on\n          in a hurry, they don''t wanna sit there and wait for your YAM\n          to load if they don''t care about email. Basically, this little\n          fix has saved your life/made you friends. Your welcome.\n\n          Abort message routine sorted.\n\n          Notice a linespace between ''Send to:'' and ''Subject'' when\n          writing mail. For some reason, when the two lines are together,\n          the letter ''m'' appears in the ''subject'' input. Two hours to\n          fucking spot this thing. Only happened with certain ''Send to:''\n          addresses. IE: ''Send to: [email removed]'' - strange.\n\n          WriteAttach exists again. Enable/Disable via tooltype.\n          Problem of filenames with spaces still exists. Routine to check\n          for spaces or ''#?.info'' files brings up a message explaining\n          to the user regarding failure.\n\n          Readmail feature now uses YAM routines. It''s a little slower\n          but YAM will split headers/attachments/plaintext - which is\n          easier for handling.\n\n          Reply feature now quotes original message.\n\n          About screen changed.\n\n          Previous update said no major changes would take place.\n          I promised aswell. What can I say?\n          ''You can say sorry, you bastard.''\n          ''Sorry.''\n          ''Man, that was insincere...''\n\n          Anyway, this version can be spread.\n          I''m gonna sit back and check this thing through again.\n          While waiting for other bug reports.\n\nv2.04  -  File attach removed. Giving me too much shit and I haven''t\n          the patience to sort it right now:(\n\n          ***MAJOR OVERHAUL*** of entire program:\n\n          First thing you notice is lack of files. Well, I finally\n          found a way to address YAM as well as AEREXXCONTROL-etc\n          so everything is in one file now, excluding the logon-email\n          check rexx.\n\n          ***Basically, ditch old files and re-install***\n          ***This won''t happen again, I dearly promise***\n\n          ;)\n\n          Tooltypes added for ease. Rexxtricks and Rexxsupport library\n          have totally saved this program. Not all of the original C:\n          commands are needed now. Go through installation docs again.\n\n          Signature now uses the inbuilt YAM sig creator.\n\n          Other node using MMail/lost carrer users etc all\n          reprogrammed.\n\n          All programming texts tidied up.\n\nv2.03  -  File Attach added. This needs some serious testing.\n          I''ve not had any problems, aside from the fact that any\n          uploaded file needs to be one word. Split filename will\n          result in ''file already exists'' but the program will\n          carry on happily, not attaching anything.\n          Put a file in ''doors:email/'' called ''NoAttach'' and\n          this function will be disabled. Any file. If a user\n          uploads multiple files then only the first is used.\n\n          If no mail is there for the user then a different\n          message will be displayed.\n\n          Overall: I am very happy with this proggy, even though it\n          looks ''tacked together in a day''. Learning more and more about\n          Arexx - use of libs etc. I find that ''makedir'' ''delete'' etc are\n          all part of rexxsupport.library. The less ''outside'' files I have\n          to use, the better.\n\nv2.02  -  MoMail  not  bothered  now  by uppercase/lowercase. The\n          email will be read by ''sAFRA'' or ''safra''...etc.\n          Used rexxtricks.library to achieve this.\n          Yes, there was probably an easier way, but.\n\n          Hyphenation of user name if a split word prog routine\n          changed. I had some nightmare check routine which has\n          been replaced by a built-in Arexx function. Likely there\n          are a million more built-in functions that could reduce\n          this whole program to ten lines long, damn it.\n\n          Aside from the check for ''@'' in any entered email address\n          also added is the check to make sure there are no spaces.\n\n          Layout changes. New main menu.\n\n          Guide re-written. All UPDATE info now within.\n\n          Filename change to MMail20x.lha\n          Old filename was 13 chars long.\n          Which is not allowed when upping to an /X board.\n          Oh man, a bug in the file name. Sickening.\n          I''m sure some god is laughing at me.\n\n          Counter on ''readmail''. ''Message 1 of 3'' etc. Cheap.\n\n          ''Format SYS:'' command implemented via ''ZZ'' command on main.\n          Then pressed by accident.\n          Re-wrote whole program from scratch.\n\nv2.01 - Another rush release. Must stop. No. Make me. Punch. Oh, okay.\n\nv2.00 - Static vers. Rushed release. Shouldn''t have. Idiot.\n\nv1.07 - Dyn-vers. ...this on BBS''s still. Yikes. Delete!\n\nv1.06 - Dyn-vers. ...and...\n\nv1.05 - Dyn-vers. See this...\n\nv1.04 - Dynamic version. Oh dear me.\n\n\n@endnode\n@node "Bugs" "Those feckin crawlies..."\nNothing to report right now.\nAny problems, gimme a shout.\n@endnode\n@node "disc" "This is entirely...not my fault."\nDISCLAIMER!\n\nWith  this  document  I  make  no  warranties  or  representations,  either\nexpressed  or  implied,  with  respect to the program described herein. The\nprogram  and  the  information presented herein is being supplied on an `as\nis''  basis  and  is  expressly subject to change without notice. The entire\nrisk  as to the use of the program and the information presented is assumed\nby the user. In no event will I be liable for direct, indirect, incidental,\nor consequential damages resulting from any claim arising out of the use of\nthe program or the information presented herein.\n@endnode\n\n@node "cred" "Ladies and Gentlemen, presenting..."\nMarcel Beck    - Author of YAM and helper via [email removed] :)\nAminet scripts - Countless. Many many excellents sources of info.\nPepsi          - Total addiction.\nSmokes         - Foreign ciggs. UK prices take the total piss.\n\n\n\n@endnode\n','\n',char(10)),NULL,NULL,38542,2,0,NULL,NULL,NULL,'scan',1780048612);
INSERT INTO door_catalog VALUES('mo_fl10','MO-FL10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MO-FL10.LHA',NULL,'XIM','.------------------------------------------.',NULL,NULL,'MO',':       Fast Logoff v1.00 - sAFRA ''99      : +------------------------------------------+ :         Requires AmiExpress 4.xX         :',replace('.------------------------------------------.\n:       Fast Logoff v1.00 - sAFRA ''99      :\n+------------------------------------------+\n:         Requires AmiExpress 4.xX         :\n+------------------------------------------+\n:   100% Arexx Door - 100% Public Domain   :\n`------------------------------------------''\n','\n',char(10)),'MoFast.doc',replace('MoFast - sAFRA 1999.\n\nWaste of time docs:\n\n''gf'' command - instant logoff.\n\nSmall file, no libraries.\nNote: Won''t work on a local login.\n\nBut if it does, worry.\n','\n',char(10)),NULL,NULL,2391,1,0,NULL,NULL,NULL,'scan',1780048612);
INSERT INTO door_catalog VALUES('mo_ha12','MO-HA12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MO-HA12.LHA',NULL,'XIM','.------------------------------------------.',NULL,NULL,'MO',':         Mo-Hack v1.02 - sAFRA 1999       : +------------------------------------------+ :Puts security between users and 1<->5 keys:',replace('.------------------------------------------.\n:         Mo-Hack v1.02 - sAFRA 1999       :\n+------------------------------------------+\n:Puts security between users and 1<->5 keys:\n+------------------------------------------+\n:    BUGFIX - Requires AmiExpress 4.xX     :\n+------------------------------------------+\n:   100% Arexx Door - 100% Public Domain   :\n`------------------------------------------''\n','\n',char(10)),'MoHack.Guide',replace('@database Mo-Hack.Guide\n@$VER: Mo-Hack (v1.01)\n@author "Safra"\n\n@node "Main" "mO-Hack dOCS"\n\n              @{b}==============================================\n                    mOhACK - sAFRA ''99 - v1.01 BUGFIX\n              ==============================================@{ub}\n\n              @{" Introduction                                " link "Intr"}\n              @{" Installation                                " link "inst"}\n              @{" What it does                                " link "impo"}\n              @{" Contact                                     " link "auth"}\n              @{" Known Bugs                                  " link "bugs"}\n              @{" Disclaimer                                  " link "disc"}\n\n              @{" Updates                                     " link "upda"}\n              @{b}==============================================\n              [AREXX-DOOR-AREXX-DOOR--AREXX-DOOR-AREXX-DOOR]\n              ==============================================\n\n@endnode\n\n@node "Intr" "Introduction"\nYou''ve  seen  this before, gIZMO/ULTIMA and LSD have both written\ndoors that stop users from hitting the 1-5 keys etc. This  is  my\nown personal version...msgbase safe.\n\nSeveral  features  available  via  tooltypes.  Has the ability to\nsend an EALL/drop user from line/change axs level.\n\nA private message to sysop will always be sent, but the  rest can\nbe switched off.\n\nPassword at mainline (if correct) will  allow  a  user  into  the\nfamous five situation. A small menu for their delight.\n\nPlus it looks pretty funky.\n\nThis  is  really  a waste of time as in this day and age no sysop\nshould use the 1-5 keys. Use OPUS to  scan  your  callerlogs  etc\nand  if  you want to send users files then go on a local node and\nput them online in a ''requests''  conference!  They  can  download\nthem in a safer way. End of ''I''m ya mutha'' speech;)\n@endnode\n@node "spec" "Specifications"\nMo-Email is currently running on my:  A1200/020/882\n                                      10 Meg RAM\n                                      85 Meg Drive\n                                      /X version 4.#?\n@endnode\n@node "Impo" "Important!"\nNeeds: rexxtricks.library\n       rexxsupport.library\n       somehackers.library;)\n@endnode\n@node "auth" "Contact"\nContact:   [email removed]\nBBS:       (UK) 01536-744-639 (After 10pm please - offline soon)\n@endnode\n@node "inst" "Getting this sod to work..."\n(1) Copy all files to >NIL:\n\n(2) Adjust the tooltypes as below:\n\nSAFEPASS=The password select users can have to bypass everything.\n         Note: 15 chars or less!\n\nPRIVMAIL=Name of sysop for private alert message.\n\nEALLCONF=Path to conf for EALL message. Must end with ''/''\n\nPRIVCONF=Path to conf for PRIV message. Must end with ''/''\n\nDROPLINE=yes/no - Ditch user from system if he''s fucking about.\n\nLOGOTEXT=Path/filename to main screen gfx file.\n\nMAILTEXT=Path/filename for PRIV message header txt.\n\nSENDEALL=yes/no - Alert board users of hack attempts.\n\nLOWERAXS=yes/no - Lower a hacker''s access level.\n\nNUAXSLVL=The level to drop a user to if function enabled.\n\nMAILSUBJ=Subject for all messages sent.\n\nEALLTEXT=Path/filename for EALL message header txt.\n\n@endnode\n@node "Upda" "Updates..."\nv1.01 - FUCK!!! Change password function removed.\n        Buggy, so it went.\n        Steer clear of v1.00.\n        Sometimes it worked, sometimes it didn''t.\n        Bugs like that can go fuck ''emselves.\n\nv1.00  - Possible final.\n@endnode\n@node "Bugs" "Those feckin crawlies..."\nNone spotted.\n@endnode\n@node "disc" "You trashed my drive, you bastard."\nDISCLAIMER!\n\nWith  this  document  I  make  no  warranties  or  representations,  either\nexpressed  or  implied,  with  respect to the program described herein. The\nprogram  and  the  information presented herein is being supplied on an `as\nis''  basis  and  is  expressly subject to change without notice. The entire\nrisk  as to the use of the program and the information presented is assumed\nby the user. In no event will I be liable for direct, indirect, incidental,\nor consequential damages resulting from any claim arising out of the use of\nthe program or the information presented herein.\n@endnode\n','\n',char(10)),NULL,NULL,26036,2,0,NULL,NULL,NULL,'scan',1780048612);
INSERT INTO door_catalog VALUES('mo_ml10','MO-ML10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MO-ML10.LHA',NULL,'XIM','.------------------------------------------.',NULL,NULL,'MO',':     MsgBase Lister v1.00 - sAFRA 1999    : +------------------------------------------+ :  Rexx script to output all messages from :',replace('.------------------------------------------.\n:     MsgBase Lister v1.00 - sAFRA 1999    :\n+------------------------------------------+\n:  Rexx script to output all messages from :\n:chosen conference -> useless but nice file:\n+------------------------------------------+\n:         Requires AmiExpress 4.xX         :\n+------------------------------------------+\n:   100% Arexx Door - 100% Public Domain   :\n`------------------------------------------''\n','\n',char(10)),'MsgLister.doc',replace('MsgBase Lister - sAFRA 1999\n\nThis  little  waste  of  time  script  will  ask for a conference\nof your choice - then output all of the messages found within  to\na file - also your choice. Lucky you.\n\nThis  was  merely  a  programming exercise while I learn more and\nmore about /X.\n\nNeeds: rexxtricks.library © Jurgen Kohrmeyer.\n       rexxsupport.library\n\nUseage: rx MsgLister.rexx\n\nIt will read from your ''bbs:confconfig.info'' icon.\n','\n',char(10)),NULL,NULL,2825,1,0,NULL,NULL,NULL,'scan',1780048612);
INSERT INTO door_catalog VALUES('mo_ms11','MO-MS11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MO-MS11.LHA',NULL,'XIM','.------------------------------------------.',NULL,NULL,'MO',': Samilog-Mini-Callerslog-Restyler - sAFRA : +------------------------------------------+ :               Version 1.01               :',replace('.------------------------------------------.\n: Samilog-Mini-Callerslog-Restyler - sAFRA :\n+------------------------------------------+\n:               Version 1.01               :\n+------------------------------------------+\n:   100% Arexx Door - 100% Public Domain   :\n`------------------------------------------''\n','\n',char(10)),'MCS.Guide',replace('@database Mo-MCS.Guide\n@$VER: Mo-MCS (v1.01)\n@author "Safra"\n\n@node "Main" "mO-MCS dOCS"\n\n              @{b}==============================================\n              sAMILOG-mINI-cALLERSLOG-rESTYLER - v1.01 sAFRA\n              ==============================================@{ub}\n\n              @{" Introduction                                " link "Intr"}\n              @{" Installation                                " link "inst"}\n              @{" What it does                                " link "impo"}\n              @{" Contact                                     " link "auth"}\n              @{" Known Bugs                                  " link "bugs"}\n              @{" Disclaimer                                  " link "disc"}\n\n              @{" Updates                                     " link "upda"}\n              @{b}==============================================\n              [AREXX-DOOR-AREXX-DOOR--AREXX-DOOR-AREXX-DOOR]\n              ==============================================\n                          Beta - Possible Final\n\n@endnode\n\n@node "Intr" "Introduction"\nThis little rexx  script  will  take  your  MiniCallerslog  (from\nSamilog)  and  allow  you  to  output a lastcallers bulletin with\npersonalised borders and colours.\n\nYes,  Samilog does the same. Except it doesn''t let you change the\ncolours, unless you dive in with a binary editor.\n\nThis is public domain, but this time I ask  that  you  make  DAMN\nsure you  put ''P0T-NOoDLE/Samilog-v2.00/Etc'' in your personalised\nborder. I did not write this to shit on Mr Noodle.\n\nThis  was  mainly  inspired  by  Venom and his NVX-AWAIT program,\nwhich does a similar thing.\n\n@endnode\n@node "spec" "Specifications"\nMo-Email is currently running on my:  A1200/020/882\n                                      10 Meg RAM\n                                      85 Meg Drive\n                                      /X version 4.#?\n\nIt should run with S!X etc as it''s not BBS specific.\n\n@endnode\n@node "Impo" "Important!"\nWhen first run it will create a new LCallers bulletin. Make  sure\nall  files  are  where they should be, as I haven''t programmed in\nany safety checks etc. Run it from a shell as a first test.\n\n bbs:utils/MCS.rexx -c              Clears LC bulletin\n bbs:utils/MCS.rexx ?               Useless Information\n\nIf you don''t want the Sysop to appear  in  LastCallers  then  you\ndefine this via Samilog.\n\nsamilog -USC"etc"10 <--- remove the ''S''\n\nOr something like that.\n\nNeeds: rexxtricks.library\n@endnode\n@node "auth" "Contact"\nContact:   [email removed]\nBBS:       (UK) 01536-744-639 (After 10pm please - offline soon)\n@endnode\n@node "inst" "Getting this sod to work..."\n(1) Copy all files to where they should be.\n\n(2) Then delete them, cos you''re scared.\n\n(3) Reinstall and go through the rexx script with text editor.\n\n(4) Change LINE=? to suit how many lines you want.\n\n(5) Change paths to make sure they''re all okay.\n\n(6) Make sure you test this in a shell first.\n\n(7) Untested is use of weird ansi codes ^[44;32m etc.\n\n(8) Run from logoff script as ''c:rx bbs:utils/mcs.rexx''\n\nOr wherever you keep rx.\nJust play until you figure it.\n@endnode\n@node "Upda" "Updates..."\nv1.00  - Possible final.\n@endnode\n@node "Bugs" "Those feckin crawlies..."\nNone spotted.\n@endnode\n@node "disc" "You trashed my drive, you bastard."\nDISCLAIMER!\n\nWith  this  document  I  make  no  warranties  or  representations,  either\nexpressed  or  implied,  with  respect to the program described herein. The\nprogram  and  the  information presented herein is being supplied on an `as\nis''  basis  and  is  expressly subject to change without notice. The entire\nrisk  as to the use of the program and the information presented is assumed\nby the user. In no event will I be liable for direct, indirect, incidental,\nor consequential damages resulting from any claim arising out of the use of\nthe program or the information presented herein.\n@endnode\n','\n',char(10)),NULL,NULL,11379,3,0,NULL,NULL,NULL,'scan',1780048612);
INSERT INTO door_catalog VALUES('mo_nc11','MO-NC11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MO-NC11.LHA',NULL,'XIM','.------------------------------------------.',NULL,NULL,'MO',':       Mo-Next - v1.01 - sAFRA 1999       : +------------------------------------------+ :        Message to next caller job        :',replace('.------------------------------------------.\n:       Mo-Next - v1.01 - sAFRA 1999       :\n+------------------------------------------+\n:        Message to next caller job        :\n+------------------------------------------+\n:         Requires AmiExpress 4.xX         :\n+------------------------------------------+\n:   100% Arexx Door - 100% Public Domain   :\n`------------------------------------------''\n','\n',char(10)),'MoNext.guide',replace('Mo-Next docs.\nNo guide, program too simple/too short;)\n\nPut files where they should be.\n\nAdd to logon.txt:\n\n~f ~SS_doors:monext/nextcaller.txt ~SP\n\nAnd you''re all set.\n\nRexxtricks used because it takes away hassles.\n\n','\n',char(10)),NULL,NULL,5512,1,0,NULL,NULL,NULL,'scan',1780048612);
INSERT INTO door_catalog VALUES('mo_op12','MO-OP12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MO-OP12.LHA',NULL,'XIM','.------------------------------------------.',NULL,NULL,'MO',':        Mo-Open v1.02 - sAFRA 1999        : +------------------------------------------+ :  Shows other commands available at users :',replace('.------------------------------------------.\n:        Mo-Open v1.02 - sAFRA 1999        :\n+------------------------------------------+\n:  Shows other commands available at users :\n:    current access level. Nothing more.   :\n+------------------------------------------+\n:         Requires AmiExpress 4.xX         :\n+------------------------------------------+\n:   100% Arexx Door - 100% Public Domain   :\n`------------------------------------------''\n','\n',char(10)),'Mo-Open.Guide',replace('@database Mo-Open.Guide\n@$VER: Mo-Open (v1.02)\n@author "Safra"\n\n@node "Main" "mO-oPeN dOCS"\n\n              @{b}==============================================\n                        mO-oPEN - v1.02 - sAFRA 1999\n              ==============================================@{ub}\n\n              @{" Introduction                                " link "Intr"}\n              @{" Installation                                " link "inst"}\n              @{" What it does                                " link "impo"}\n              @{" Contact                                     " link "auth"}\n              @{" Known Bugs                                  " link "bugs"}\n              @{" Disclaimer                                  " link "disc"}\n\n              @{" Updates                                     " link "upda"}\n              @{b}==============================================\n              [AREXX-DOOR-AREXX-DOOR--AREXX-DOOR-AREXX-DOOR]\n              ==============================================\n@endnode\n\n@node "Intr" "Introduction"\nAllows you to display other doors available to users -  shit  you\ncouldn''t  fit  on  your main menu cos there''s a ton of ansi there\nat bursting point.\n\nAnyway,  there  is  one config file which holds all data for this\ndoor, a smart door, that shows the user other commands  avail  at\nhis access level. Nothing else.\n\nA  door  like  this  exists  out there, which I haven''t got, so I\nwrote this to compensate. Respect to  the  guy  that  wrote  that\ndoor. MoOpen born because of you.\n@endnode\n@node "spec" "Specifications"\nMo-Email is currently running on my:  A1200/020/882\n                                      10 Meg RAM\n                                      85 Meg Drive\n                                      /X version 4.#?\n@endnode\n@node "Impo" "Important!"\nRead ''commands.cfg'' with a text viewer/editor.\n@endnode\n@node "auth" "Contact"\nContact:   [email removed]\nBBS:       (UK) 01536-744-639 (After 10pm please - offline soon)\n\nVery soon indeed.\nRead errors on my WORK: partition. But I''ll battle on.\nToe stub. Ouch.\n@endnode\n@node "inst" "Getting this sod to work..."\nRead the ''commands.cfg''. It explains everything.\n@endnode\n@node "Upda" "Updates..."\nv1.02  - Possible FINAL.\n\n@endnode\n@node "Bugs" "Those feckin crawlies..."\nNone spotted.\n@endnode\n@node "disc" "You trashed my drive, you bastard."\nDISCLAIMER!\n\nWith  this  document  I  make  no  warranties  or  representations,  either\nexpressed  or  implied,  with  respect to the program described herein. The\nprogram  and  the  information presented herein is being supplied on an `as\nis''  basis  and  is  expressly subject to change without notice. The entire\nrisk  as to the use of the program and the information presented is assumed\nby the user. In no event will I be liable for direct, indirect, incidental,\nor consequential damages resulting from any claim arising out of the use of\nthe program or the information presented herein.\n@endnode\n','\n',char(10)),NULL,NULL,8137,2,0,NULL,NULL,NULL,'scan',1780048612);
INSERT INTO door_catalog VALUES('mo_over','MO-OVER.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MO-OVER.LHA',NULL,'XIM','rexxtricks.library',NULL,NULL,'MO',': [mO-sTUFF]   [GAME OVER]    [sAFRA 1999] : : -- --- -------------------------- --- -- : :  Newest versions of all my doors for /X  :',replace('.------------------------------------------.\n: [mO-sTUFF]   [GAME OVER]    [sAFRA 1999] :\n: -- --- -------------------------- --- -- :\n:  Newest versions of all my doors for /X  :\n:  - -- --- -------------------- --- -- -  :\n:  zERO iNTENTION oF fUTURE rELEASES LTD!  :\n`------------------------------------------''\n','\n',char(10)),'Mo-ZZz-Docs1.txt',replace('Mo-Doors Volume One (of one :-) - sAFRA 1999\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nWell, having been told by Aminet moderators NOT to  upload  these\nfiles  individually,  I  have  archived  the lot and sent them on\ntheir way to you.\n\nIn the event that you have a major problem with  any  doors,  let\nme  know  directly  and  I  will  fix a personal version for you.\n\nRemember,  all  MoDoors/Utilities  are  public domain. You can do\nwhatever the hell you want with them.\n\nNot  sure  whether you should upload these to a BBS, as there are\nmissing libs etc that were in  the  original  archives  -  but  I\nhave  removed  rexxtricks.library  and  rexxsupport.library  from\neach  archive  for  one  reason:  To reduce the size, making sure\nrexxtricks etc isn''t duplicated.\n\nPlease check through this archive, as most of  the  files  within\nare possibly newer versions than you have already.\n\nAs the fileid says, I will be releasing nothing more.\nIf you have a personal request, lemme know.\n\nGonna try and play around with C and ASM.\nI''ve looked at both.\nAnd they are a total bitch.\nMUCH respect to those kinds of programmers. MUCH.\n\nContact\n~~~~~~~\[email removed]\n\nAdd: If anyone has  any  information  on  /X  user.data, 4.12  or\nabove,  please  let  me  know.  Also,  I''d be grateful if someone\ncould tell me the details concerning  the  encryption  method.  I\nbelieve  it  takes  a  password  and  breaks  it  down  to  a new\nfour-part passie.  IE:  user.data=232  bytes.  Locations  101-104\ncontain the ''password''??? See ''Mo-Shell-Status''. Cheers.\n\nFiles:\n~~~~~~\n\n[01] Mo-AB10.lha             .------------------------------------------.\nFiletype: LH_CLONE           :       Mo-AddBBS v1.00 - Safra 1999       :\nSize: 6532                   +------------------------------------------+\nDate: 12-Jul-1999            :   100% Arexx Door - 100% Public Domain   :\n                             `------------------------------------------''\n\n\n[02] Mo-AD11.lha             .------------------------------------------.\nFiletype: LH_CLONE           :  Mo-Text-Add v1.01 (BETA)  - sAFRA 1999  :\nSize: 5397                   +------------------------------------------+\nDate: 12-Jul-1999            :     > ULName/ULLoca/Time/Date/Node <     :\n                             :     > ULPhoneNo/ULAccsLvl/FileName <     :\n                             +------------------------------------------+\n                             :         Requires AmiExpress 4.xX         :\n                             +------------------------------------------+\n                             :   100% Arexx Door - 100% Public Domain   :\n                             `------------------------------------------''\n\n\n[03] Mo-AI11.lha             .------------------------------------------.\nFiletype: LH_CLONE           :    Mo-Intelligence v1.01 - sAFRA 1999    :\nSize: 9130                   +------------------------------------------+\nDate: 12-Jul-1999            : Looks like a pager door until the sysop  :\n                             :  answers. Then things aren''t what they   :\n                             :  appear to be. A total funk-piss-take.   :\n                             +------------------------------------------+\n                             :         Requires AmiExpress 4.xX         :\n                             +------------------------------------------+\n                             :   100% Arexx Door - 100% Public Domain   :\n                             `------------------------------------------''\n\n\n[04] Mo-DN10.lha             .------------------------------------------.\nFiletype: LH_CLONE           :      Mo-Down v1.00 (BETA)- sAFRA ''99     :\nSize: 7435                   +------------------------------------------+\nDate: 12-Jul-1999            :       Download Directory Listing(s)      :\n                             +------------------------------------------+\n                             :         Requires AmiExpress 4.xX         :\n                             +------------------------------------------+\n                             :   100% Arexx Door - 100% Public Domain   :\n                             `------------------------------------------''\n\n\n[05] Mo-EM26.lha             .------------------------------------------.\nFiletype: LH_CLONE           :        Mo-Mail v2.06 - Safra 1999        :\nSize: 37338                  +------------------------------------------+\nDate: 12-Jul-1999            :         : AmiExpress 4.xX                :\n                             :Requires : Yam 2.00 Preview 7+            :\n                             :         : Static IP Internet Account     :\n                             +------------------------------------------+\n                             :   100% Arexx Door - 100% Public Domain   :\n                             `------------------------------------------''\n\n\n[06] Mo-EMI1.lha             Info for MoEmail.\n\n\n[07] Mo-FL10.lha             .------------------------------------------.\nFiletype: LH_CLONE           :       Fast Logoff v1.00 - sAFRA ''99      :\nSize: 1348                   +------------------------------------------+\nDate: 10-Jul-1999            :         Requires AmiExpress 4.xX         :\n                             +------------------------------------------+\n                             :   100% Arexx Door - 100% Public Domain   :\n                             `------------------------------------------''\n\n\n[08] Mo-HA12.lha             .------------------------------------------.\nFiletype: LH_CLONE           :         Mo-Hack v1.02 - sAFRA 1999       :\nSize: 24994                  +------------------------------------------+\nDate: 12-Jul-1999            :Puts security between users and 1<->5 keys:\n                             +------------------------------------------+\n                             :    BUGFIX - Requires AmiExpress 4.xX     :\n                             +------------------------------------------+\n                             :   100% Arexx Door - 100% Public Domain   :\n                             `------------------------------------------''\n\n\n[09] Mo-ML10.lha             .------------------------------------------.\nFiletype: LH_CLONE           :     MsgBase Lister v1.00 - sAFRA 1999    :\nSize: 1783                   +------------------------------------------+\nDate: 9-Jul-1999             :  Rexx script to output all messages from :\n                             :chosen conference -> useless but nice file:\n                             +------------------------------------------+\n                             :         Requires AmiExpress 4.xX         :\n                             +------------------------------------------+\n                             :   100% Arexx Door - 100% Public Domain   :\n                             `------------------------------------------''\n\n\n[10] Mo-MS11.lha             .------------------------------------------.\nFiletype: LH_CLONE           : Samilog-Mini-Callerslog-Restyler - sAFRA :\nSize: 10337                  +------------------------------------------+\nDate: 12-Jul-1999            :               Version 1.01               :\n                             +------------------------------------------+\n                             :   100% Arexx Door - 100% Public Domain   :\n                             `------------------------------------------''\n\n\n[11] Mo-NC11.lha             .------------------------------------------.\nFiletype: LH_CLONE           :       Mo-Next - v1.01 - sAFRA 1999       :\nSize: 4470                   +------------------------------------------+\nDate: 12-Jul-1999            :        Message to next caller job        :\n                             +------------------------------------------+\n                             :         Requires AmiExpress 4.xX         :\n                             +------------------------------------------+\n                             :   100% Arexx Door - 100% Public Domain   :\n                             `------------------------------------------''\n\n\n[12] Mo-OP12.lha             .------------------------------------------.\nFiletype: LH_CLONE           :        Mo-Open v1.02 - sAFRA 1999        :\nSize: 7096                   +------------------------------------------+\nDate: 10-Jul-1999            :  Shows other commands available at users :\n                             :    current access level. Nothing more.   :\n                             +------------------------------------------+\n                             :         Requires AmiExpress 4.xX         :\n                             +------------------------------------------+\n                             :   100% Arexx Door - 100% Public Domain   :\n                             `------------------------------------------''\n\n\n[13] Mo-SS10.lha             .------------------------------------------.\nFiletype: LH_CLONE           :      Shell-Status v1.00 - sAFRA 1999     :\nSize: 8637                   +------------------------------------------+\nDate: 12-Jul-1999            :    Exercise in reading user.data etc     :\n                             +------------------------------------------+\n                             :         Requires AmiExpress 4.xX         :\n                             +------------------------------------------+\n                             :   100% Arexx Door - 100% Public Domain   :\n                             `------------------------------------------''\n\n\n[14] Mo-ST13.lha             .------------------------------------------.\nFiletype: LH_CLONE           :    Mo-Statistics - v1.03 - sAFRA 1999    :\nSize: 7965                   +------------------------------------------+\nDate: 12-Jul-1999            :              Stats/Cookies               :\n                             +------------------------------------------+\n                             :         Requires AmiExpress 4.xX         :\n                             +------------------------------------------+\n                             :   100% Arexx Door - 100% Public Domain   :\n                             `------------------------------------------''\n\n\n[15] Mo-Stuff1.readme\n\n\n[16] Mo-UL10.lha             .------------------------------------------.\nFiletype: LH_CLONE           :      Mo-UserList v1.00 - sAFRA 1999      :\nSize: 1009                   +------------------------------------------+\nDate: 9-Jul-1999             :Rexx script to output all users from shell:\n                             +------------------------------------------+\n                             :         Requires AmiExpress 4.xX         :\n                             +------------------------------------------+\n                             :   100% Arexx Door - 100% Public Domain   :\n                             `------------------------------------------''\n\n\n[17] Mo-WA11.lha             .------------------------------------------.\nFiletype: LH_CLONE           :        Mo-Wall - v1.01 - sAFRA 1999      :\nSize: 14978                  +------------------------------------------+\nDate: 12-Jul-1999            :     Personal-exercise-in-Arexx-release   :\n                             +------------------------------------------+\n                             :         Requires AmiExpress 4.xX         :\n                             +------------------------------------------+\n                             :   100% Arexx Door - 100% Public Domain   :\n                             `------------------------------------------''\n\n\nAdded: Mo-SR21.lha - Newer version of the Samilog restyler.\n                     Preset output, looks and acts better than\n                     the original. Possibly buggy as fuck.\n                     But worked for me;)\n\nAny ideas for new doors appreciated.\n','\n',char(10)),NULL,'auto-added',186398,1,0,NULL,NULL,'mo_over','scan',1780048612);
INSERT INTO door_catalog VALUES('mo_sr21','MO-SR21.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MO-SR21.LHA',NULL,'XIM','.------------------------------------------.',NULL,NULL,'MO',':    Samilog Restyler v2.1 - Safra 1999    : +------------------------------------------+ :           Alternative version            :',replace('.------------------------------------------.\n:    Samilog Restyler v2.1 - Safra 1999    :\n+------------------------------------------+\n:           Alternative version            :\n+------------------------------------------+\n:   100% Arexx Door - 100% Public Domain   :\n`------------------------------------------''\n','\n',char(10)),'SAR.doc',replace('Super Amilog Restyler - Safra 1999 - BETATESTER\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nSAMILOG.STORE version 2.1\n\nDoes NOT need ''BBS:Mini_Callerslog''\n\nNOT to be confused with my previous Mini_Callerslog styler.\nThey do roughly the same thing, but this is better.\n\nUseage:\n~~~~~~~\nTEMPLATE: rx SAR.rexx <outputfile> <# of users>\nEXAMPLE : rx SAR.rexx bbs:screens/lastcallers.txt 15\n\nIf  you  currently  use  SAMILOG to output a lastcallers bulletins then you\ncan remove that part. SAMILOG still needs to update, of coz.\n\nIE: bbs:utils/samilog -U"<NODE>"\n\nThere are no seperate headers and tailers here. I might implement  them  in\nthe  future,  but  the  output  looks  fine  the way it is. And it''s not my\ndesign either. It is a near-copy of Venom''s NVX-AWAIT - which  I  chose  to\n''duplicate''  simply because it looks cool and clean. I did this without any\npermission whatsoever, but hope no-one is deeply offended. Sniff.\n\nObviously the main credit goes to P0T-NOodle for Samilog. Excellent.\n\nRemember this is a BETA version. I take zero responsibility  for  any  fuck\nups caused by this program.\n\nRequires:\n~~~~~~~~~\nRexxTricks.Library (Jurgen Kohrmeyer)\n\nContact:\n~~~~~~~~\[email removed]\n\n\n\n','\n',char(10)),NULL,NULL,5587,1,0,NULL,NULL,NULL,'scan',1780048612);
INSERT INTO door_catalog VALUES('mo_ss10','MO-SS10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MO-SS10.LHA',NULL,'XIM','.------------------------------------------.',NULL,NULL,'MO',':      Shell-Status v1.00 - sAFRA 1999     : +------------------------------------------+ :    Exercise in reading user.data etc     :',replace('.------------------------------------------.\n:      Shell-Status v1.00 - sAFRA 1999     :\n+------------------------------------------+\n:    Exercise in reading user.data etc     :\n+------------------------------------------+\n:         Requires AmiExpress 4.xX         :\n+------------------------------------------+\n:   100% Arexx Door - 100% Public Domain   :\n`------------------------------------------''\n','\n',char(10)),'ShellStatus.doc',replace('Shell Status - Safra 1999.\n\nThis was created to try and understand the user.data etc  of  AmiExpress  a\nlittle  better.  If you run Sigma Express then you could give it a try. The\nonly thing it writes to is the output file.\n\nI have a few things missing, all of which I want to track down - so I  have\na complete table of all user.data/etc locations.\n\nI  could  do with some feedback on user.misc and user.keys, if anyone knows\nthe full design of these little swines. There are also  a  lot  of  unknown\nareas in user.data.\n\nAlso, if anyone knows the password encryption routine, lemme  know.  Surely\nthere  is  a way to program it in Arexx, even though the speed will be mind\nnumbing.\n\nI  was playing around with Aqua''s Create-Account door - and that man surely\nknew his user.data etc:) So this program was born, to try  and  further  my\nknowledge a little. Well, a lot.\n\nMake sure to read through the rexx script comments. Lots.\n\n---------------------------------------------------------------------------\n\nNeeds  : rexxtricks.library (C)Jurgen Kohrmeyer\n         rexxsupport.library\n\nContact: [email removed]\n\n\n','\n',char(10)),NULL,NULL,9679,1,0,NULL,NULL,NULL,'scan',1780048612);
INSERT INTO door_catalog VALUES('mo_st10','MO-ST10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MO-ST10.LHA',NULL,'XIM','rexxtricks.library',NULL,'Stats/Cookies','MO',':    Mo-Statistics - v1.00 - sAFRA 1999    : +------------------------------------------+ :              Stats/Cookies               :',replace('.------------------------------------------.\n:    Mo-Statistics - v1.00 - sAFRA 1999    :\n+------------------------------------------+\n:              Stats/Cookies               :\n+------------------------------------------+\n:         Requires AmiExpress 4.xX         :\n+------------------------------------------+\n:   100% Arexx Door - 100% Public Domain   :\n`------------------------------------------''\n','\n',char(10)),'Mo-Stats.Guide',replace('@database Mo-Stats.Guide\n@$VER: Mo-Stats (v1.00)\n@author "Safra"\n\n@node "Main" "mO-Stats dOCS"\n\n              @{b}==============================================\n                     mO-sTATISTICS - v1.00 - sAFRA 1999\n              ==============================================@{ub}\n\n              @{" Introduction                                " link "Intr"}\n              @{" Installation                                " link "inst"}\n              @{" What it does                                " link "impo"}\n              @{" Contact                                     " link "auth"}\n              @{" Known Bugs                                  " link "bugs"}\n              @{" Disclaimer                                  " link "disc"}\n\n              @{" Updates                                     " link "upda"}\n              @{b}==============================================\n              [AREXX-DOOR-AREXX-DOOR--AREXX-DOOR-AREXX-DOOR]\n              ==============================================\n@endnode\n\n@node "Intr" "Introduction"\nSimple stats door. You know it.\n@endnode\n@node "spec" "Specifications"\nMo-Email is currently running on my:  A1200/020/882\n                                      10 Meg RAM\n                                      85 Meg Drive\n                                      /X version 4.#?\n@endnode\n@node "Impo" "Important!"\nA header file will be shown if it exists in the  doors  directory\nas  ''title.txt''.  The  cookie output exists as ''liners.cfg'' - but\nthere must be NO empty lines in the cookie file.\n\nNeeds: rexxtricks.library\n       rexxsupport.library\n@endnode\n@node "auth" "Contact"\nContact:   [email removed]\nBBS:       (UK) 01536-744-639 (After 10pm please - offline soon)\n@endnode\n@node "inst" "Getting this sod to work..."\n(1) Copy all files to where they should be.\n    Dat''s it!\n@endnode\n@node "Upda" "Updates..."\nv1.00  - FINAL.\n@endnode\n@node "Bugs" "Those feckin crawlies..."\nNone spotted.\n@endnode\n@node "disc" "You trashed my drive, you bastard."\nDISCLAIMER!\n\nWith  this  document  I  make  no  warranties  or  representations,  either\nexpressed  or  implied,  with  respect to the program described herein. The\nprogram  and  the  information presented herein is being supplied on an `as\nis''  basis  and  is  expressly subject to change without notice. The entire\nrisk  as to the use of the program and the information presented is assumed\nby the user. In no event will I be liable for direct, indirect, incidental,\nor consequential damages resulting from any claim arising out of the use of\nthe program or the information presented herein.\n@endnode\n','\n',char(10)),NULL,'auto-added',37388,2,0,NULL,NULL,'mo_st10','scan',1780048612);
INSERT INTO door_catalog VALUES('mo_st13','MO-ST13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MO-ST13.LHA',NULL,'XIM','.------------------------------------------.',NULL,'Stats/Cookies','MO',':    Mo-Statistics - v1.03 - sAFRA 1999    : +------------------------------------------+ :              Stats/Cookies               :',replace('.------------------------------------------.\n:    Mo-Statistics - v1.03 - sAFRA 1999    :\n+------------------------------------------+\n:              Stats/Cookies               :\n+------------------------------------------+\n:         Requires AmiExpress 4.xX         :\n+------------------------------------------+\n:   100% Arexx Door - 100% Public Domain   :\n`------------------------------------------''\n','\n',char(10)),'Mo-Stats.Guide',replace('@database Mo-Stats.Guide\n@$VER: Mo-Stats (v1.03)\n@author "Safra"\n\n@node "Main" "mO-Stats dOCS"\n\n              @{b}==============================================\n                     mO-sTATISTICS - v1.03 - sAFRA 1999\n              ==============================================@{ub}\n\n              @{" Introduction                                " link "Intr"}\n              @{" Installation                                " link "inst"}\n              @{" What it does                                " link "impo"}\n              @{" Contact                                     " link "auth"}\n              @{" Known Bugs                                  " link "bugs"}\n              @{" Disclaimer                                  " link "disc"}\n\n              @{" Updates                                     " link "upda"}\n              @{b}==============================================\n              [AREXX-DOOR-AREXX-DOOR--AREXX-DOOR-AREXX-DOOR]\n              ==============================================\n@endnode\n\n@node "Intr" "Introduction"\nSimple stats door. You know it.\n@endnode\n@node "spec" "Specifications"\nMo-Email is currently running on my:  A1200/020/882\n                                      10 Meg RAM\n                                      85 Meg Drive\n                                      /X version 4.#?\n@endnode\n@node "Impo" "Important!"\nA header file will be shown if it exists in the  doors  directory\nas  ''title.txt''.  The  cookie output exists as ''liners.cfg'' - but\nthere must be NO empty lines in the cookie file.\n\nNeeds: rexxtricks.library\n       rexxsupport.library\n@endnode\n@node "auth" "Contact"\nContact:   [email removed]\nBBS:       (UK) 01536-744-639 (After 10pm please - offline soon)\n@endnode\n@node "inst" "Getting this sod to work..."\n(1) Copy all files to where they should be.\n    Dat''s it!\n@endnode\n@node "Upda" "Updates..."\nv1.03  - Shit.\n         Have some scripts that have ''call addlib(''rexxsupport'',0,-30...)''\n         As opposed to (''rexxsupport.LIBRARY'',0,-30,0)\n         They keep creeping into my archives before I upload\n         Sincere apologies for this lame hassle\n\nv1.02  - Commas added to output of large numbers.\n         Can''t believe I forgot this stupid fucking shite.\n\nv1.01  - Well, not quite.\n\nv1.00  - FINAL.\n@endnode\n@node "Bugs" "Those feckin crawlies..."\nNone spotted.\n@endnode\n@node "disc" "You trashed my drive, you bastard."\nDISCLAIMER!\n\nWith  this  document  I  make  no  warranties  or  representations,  either\nexpressed  or  implied,  with  respect to the program described herein. The\nprogram  and  the  information presented herein is being supplied on an `as\nis''  basis  and  is  expressly subject to change without notice. The entire\nrisk  as to the use of the program and the information presented is assumed\nby the user. In no event will I be liable for direct, indirect, incidental,\nor consequential damages resulting from any claim arising out of the use of\nthe program or the information presented herein.\n@endnode\n','\n',char(10)),NULL,NULL,9008,2,0,NULL,NULL,NULL,'scan',1780048612);
INSERT INTO door_catalog VALUES('mo_ul10','MO-UL10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MO-UL10.LHA',NULL,'XIM','.------------------------------------------.',NULL,NULL,'MO',':      Mo-UserList v1.00 - sAFRA 1999      : +------------------------------------------+ :Rexx script to output all users from shell:',replace('.------------------------------------------.\n:      Mo-UserList v1.00 - sAFRA 1999      :\n+------------------------------------------+\n:Rexx script to output all users from shell:\n+------------------------------------------+\n:         Requires AmiExpress 4.xX         :\n+------------------------------------------+\n:   100% Arexx Door - 100% Public Domain   :\n`------------------------------------------''\n','\n',char(10)),'Mo-UL10.readme',replace('Short    : User Data Lister (AREXX)\nAuthor   : Safra Jameson <[email removed]>\nUploader : Safra Jameson <[email removed]>\nVersion  : 1.00\nType     : comm/amiex\n\nRun from shell: rx DataLister.rexx <bbs:user.data> <output>\n','\n',char(10)),NULL,NULL,2050,1,0,NULL,NULL,NULL,'scan',1780048612);
INSERT INTO door_catalog VALUES('mo_wa11','MO-WA11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MO-WA11.LHA',NULL,'XIM','.------------------------------------------.',NULL,NULL,'MO',':        Mo-Wall - v1.01 - sAFRA 1999      : +------------------------------------------+ :     Personal-exercise-in-Arexx-release   :',replace('.------------------------------------------.\n:        Mo-Wall - v1.01 - sAFRA 1999      :\n+------------------------------------------+\n:     Personal-exercise-in-Arexx-release   :\n+------------------------------------------+\n:         Requires AmiExpress 4.xX         :\n+------------------------------------------+\n:   100% Arexx Door - 100% Public Domain   :\n`------------------------------------------''\n','\n',char(10)),'Mo-Wall.Guide',replace('@database Mo-Wall.Guide\n@$VER: Mo-Wall (v1.01)\n@author "Safra"\n\n@node "Main" "mO-Wall dOCS"\n\n              @{b}==============================================\n                        mO-wALL - v1.01 - sAFRA 1999\n              ==============================================@{ub}\n              @{" Introduction                                " link "Intr"}\n              @{" Installation                                " link "inst"}\n              @{" Contact                                     " link "auth"}\n              @{" Known Bugs                                  " link "bugs"}\n              @{" Disclaimer                                  " link "disc"}\n\n              @{" Updates                                     " link "upda"}\n              @{b}==============================================\n              [AREXX-DOOR-AREXX-DOOR--AREXX-DOOR-AREXX-DOOR]\n              ==============================================\n@endnode\n\n@node "Intr" "Introduction"\nA  simple  wall door that was programmed as an exercise, but I''ll\nrelease it anyway and see what happens.\n@endnode\n@node "spec" "Specifications"\nMo-Email is currently running on my:  A1200/020/882\n                                      10 Meg RAM\n                                      85 Meg Drive\n                                      /X version 4.#?\n@endnode\n@node "auth" "Contact"\nContact:   [email removed]\nBBS:       (UK) 01536-744-639 (After 10pm please - offline soon)\n@endnode\n@node "inst" "Getting this sod to work..."\n(1) Copy all files to where they should be.\n\n(2) Check for rexxtricks.library and rexxsupport.library\n\n(3) Tooltypes:\n\n    ANONY_COL= Anonymous name colour\n    NORML_COL= Username colour\n    ANONY_CFG= ''yes'' to enable the anonymous function\n    CURSO_OFF= ''yes'' to blank cursor from screen\n    LINES_CFG= How many wall lines. Be realistic:)\n    EDITL_LVL= Level needed for built-in editor\n\n(4)  The current setup is for 15 lines on the wall. If you change\nthis then it  will  adjust  itself,  adding  or  removing  lines,\nwhich might take a while. After that, it''s speed city. Possibly.\n\n(5) Add ''doors:mowall/wall.logo'' for top logo if desired.\n\n(6)  Go  through  the  rexx  script itself, adjusting things that\nshould have been tooltypes also, but I''m fucked man, fucked.\n\n(7) Anonymous entries are saved to ''wall.stat''.\n@endnode\n@node "Upda" "Updates..."\nv1.00  - Possible Final.\n@endnode\n@node "Bugs" "Those feckin crawlies..."\nNone spotted.\n@endnode\n@node "disc" "You trashed my drive, you bastard."\nDISCLAIMER!\n\nWith  this  document  I  make  no  warranties  or  representations,  either\nexpressed  or  implied,  with  respect to the program described herein. The\nprogram  and  the  information presented herein is being supplied on an `as\nis''  basis  and  is  expressly subject to change without notice. The entire\nrisk  as to the use of the program and the information presented is assumed\nby the user. In no event will I be liable for direct, indirect, incidental,\nor consequential damages resulting from any claim arising out of the use of\nthe program or the information presented herein.\n@endnode\n','\n',char(10)),NULL,NULL,16020,2,0,NULL,NULL,NULL,'scan',1780048612);
