INSERT INTO door_catalog VALUES('moduti21','MODUTI21.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MODUTI21.LHA','ModemUtilityII','XIM','ModemUtilityII','2.1',NULL,NULL,NULL,'Log file analyzer and more. OS2.0 V2.1','ModemUtilityII.DOC',replace('\n\n			     Modem Utility II V2.1\n\n			      by Stefano Cairoli\n\n What is Modem Utility II:\n\n	It''s an handy program that let you calculate your modems expenses\n	and obtain a lot of interesting informations from your log files.\n        Modem Utility II supports logfiles from KCommodity, Trapdoor,\n        Term, JR Comm, Terminus and MagicCX.\n        (Sorry for the poor documentation, but I don''t have a lot of free \n         time during this period. If you register, I''ll surely send you a\n         better manual)\n         \n What do you need:\n\n	- Kickstart 2.0 or higher\n	- a log file to analize;)\n	- an Amiga\n\n Installation:\n\n	- simply copy the program to your hard disk;\n	- copy the prefs files to the S: directory.\n          (you can use it without these files too, but they are a good\n           example to reconfig the program to suit your needs).\n\n Usage:\n\n        CALCULATE:  analyse to log file from the ''First Date'' until the\n                    ''Last Date''.\n        OPTIMIZE:   optimize the log file erasing all the useless\n                    informations that are included into the log file.  It''s\n                    very handy to make a long file a shorter one.\n        ERASE:      erase the log file until from the beginning until the\n                    ''Last Date''.\n\n        EDIT PREFERENCES:  to enter the phone rates. To use this option, you\n                           can study and modify the included preferences file.\n        BBS NAME:   if you are interested in one particular BBS, enter here\n                    the name.\n        SHOW FULL STATISTIC:  if you select this option, you can obtain a\n                              lot of additional informations from your log\n                              file.\n\n        For the other options, I''ll make a better manual in the future: SORRY\n\nDISCLAIMER\n\n          The  informations and  the  program  are provided "as is" without\nwarranty  of  any kind, either expressed or implied.  The entire risk as to\nthe  accuracy  of  the  information  herein is assumed by you.  I don''t not\nwarrant,  guarantee,  or  make any representations regarding the use of, or\nthe  results  of  the  use  of,  the information or the program in terms of\ncorrectness, accuracy, reliability, currentness, or otherwise.\n\nSHAREWARE FEE\n\nModem  Utility  II is a Shareware program.  Permission is granted to freely\ndistribute   this  program  without  profit.   Copy  is  allowed  but  only\ncompletely and unchanged.\nIf  you  use it often, please pay us a donation of 10 US$.  In exchange you\nwill  get  an update without the troublesome requester (and a better manual\n;))\nPS: Please send cache and no check.\n\nMy address:\n\nSTEFANO CAIROLI\nVia F. Chiesa 2\n6833 VACALLO\nTI - SWITZERLAND\n\neMail: [email removed]\nFido:  2:301/231.20\n\n','\n',char(10)),NULL,'auto-added',70971,5,0,NULL,NULL,'moduti21','scan',1780048612);
INSERT INTO door_catalog VALUES('momail15','MOMAIL15.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MOMAIL15.LHA','Delete','XIM','Delete',NULL,NULL,NULL,':mO-mAIL v1.05 - wORMHOLe 1998 - BETATESTER: :>>>>> Requires YAM 1.3.4 and /X 4.12 <<<<<: :>>> AmiExpress Email Door - 100% AREXX <<<:',replace('.------------------------------------------.\n:mO-mAIL v1.05 - wORMHOLe 1998 - BETATESTER:\n:>>>>> Requires YAM 1.3.4 and /X 4.12 <<<<<:\n:>>> AmiExpress Email Door - 100% AREXX <<<:\n+------------------------------------------+\n:   All reports to [email removed]  :\n`------------------------------------------''\n','\n',char(10)),'Mo-Email.Guide',replace('@database Mo-Email.Guide\n@$VER: Mo-E-Mail (v1.03)\n@author "Wormhole"\n\n@node "Main" "mO-eMAIL dOCS"\n\n              @{b}=============================================\n               mO-eMAIL - v1.05 - wORMHOLe 1998 - mO-eMAIL\n              =============================================@{ub}\n\n              @{" Introduction                  " link "Intr"}  -  mO-eMAIL!\n              @{" System Specs                  " link "spec"}  -     nEEDS!\n              @{" Installation                  " link "inst"}  -        gO!\n              @{" Important                     " link "Impo"}  -      vERY!\n              @{" Author                        " link "auth"}  -   cONTACT!\n              @{" Files                         " link "file"}  -     cHECK!\n              @{" Known Bugs                    " link "bugs"}  -   rECHECK!\n              @{" Final                         " link "fina"}  -   tHE eND!\n\n              @{b}=============================================\n              [AREXX-DOOR-AREXX-DOOR-AREXX-DOOR-AREXX-DOOR]\n              =============================================@{ub}\n\n\n@endnode\n\n@node "Intr" "Introduction"\nEverybody wants an email door. Well, I do. I don''t  know  whether\nthere  are any out there now, but a year ago there was sod all. I\nhave been offline all this time, phone  bill  etc,  so  took  the\nspare  time  to write this program. And learn Arexx a little. Not\nin that order either. Ahem.\n\nSo,  here it is. Programmed without a modem, so the testing comes\nlast. But it relies heavily on YAM, of  course,  the  main  email\nprogram of the entire galaxy.\n\nUsers  of  your  BBS (Ami-Express) can send out an email or three\n- and receive. You do NOT need other email addresses for this  as\nthe  program  uses  a  subtle procedure to tell you which is your\nmail and which belongs to others. Explain later.\n\n@endnode\n@node "spec" "Specifications"\nMo-Email is currently running on my:  A1200 (68020) (68882 fpu)\n                                      10 Meg RAM\n                                      85 Meg Drive (to be upgraded soon:)\n                                      /X version 4.12\n                                      YAM 1.3.4\n\nYou, of course, don''t need all this memory.\nBut more always helps.\n\nAs  to  whether this will work on other versions of /X, I have no\nidea. I have never personally  seen  another  version  of  /X.  I\nfound the original programmer (Joseph Hodge) to be untraceable.\n\nAny help would be appreciated. Mail me.\n\nWill it work on other systems? Fame/S!x/DayDream? I don''t know.\nYou tell me.\n\n@endnode\n@node "Impo" "Important!"\nMost important:\n\nIn  order  for  users  to  delete  their  mail,  you  MUST UNtick\n''CONFIRM BEFORE DELETION'' in your YAM prefs/config.  Also  cancel\n''GET MAIL ON STARTUP''...as I am not sure whether this interferes\nwith the program, should a  user  be  the  one  to  load  YAM.  I\nbelieve  it  causes  no  hassle  when YAM is in HIDE mode. YAM is\ntold to go HIDE its ass when Mo-Email is run.\n\nIt  would  be  wise to put YAM in WBSTARTUP, else the program has\nto be loaded when a  user  tries  to  access  Mo-Mail.  It  needs\nloading  only once, but once is enough to piss off a user. Me, no\neffing doubt.\n\nDELETE MAIL: If you install this  door  then  remember  the  only\nmain rule:  DO  NOT DELETE OTHER PEOPLE''S MAIL FROM YAM DIRECTLY.\nIf you feel the need to delete a user''s message(s) then log  into\nthe BBS as that user and KILL mail from the Mo-Mail program.\n\nThe bug was untraceable. Possibly worked out.\nYou can still delete YOUR mail.\n\nHow other things work:\n\nWRITE MAIL: Asks for email address then calls  on  the  /X editor\nfor  the  user''s following email. The resulting file is stored in\nT: then processed to add a header and  tail.  The  header  is  to\ntell  the  addressee  NOT  to  change  the  subject header of the\nemail. The subject header carries ''(USER).PVT'' (IE: JaDe.PVT).\n\n(Send yourself an email via this program and see.)\n\nThis allows the addressee to reply  back  to  the  SYSOP''S  email\naddress,  the email sitting in the ''INCOMING'' folder of YAM. Then\nit is up to the SYSOP to move  any  mail  ending  ''.PVT''  to  the\narchive folder so /x users can read their email etc.\n\n(Note: There is a  filter  function  in  YAM  that  automatically\nmoves  new  mail to any given folder. Just set it to scan for any\nmail subject ending in ''.PVT'' - see enclosed screenshot. I  can''t\nget this fucker to work. Lemme know how you do.)\n\n(Note:  It  is HIGHLY likely that someone somewhere will reply to\na user''s mail: IE: User ''Wormhole'' sends a mail. The  subject  of\nhis  mail is then ''Wormhole.PVT''. Someone will read this mail and\nreply to Wormhole, hence it ends  up  returning  with  a  subject\nheader  of  ''Re:  Wormhole.PVT''. Mo-Mail takes this into account,\nbut ONLY this. I don''t, at this time, know if there are any  more\nprefixes  to  Subject  headers. IE: Does something else exist for\nforwarded mail? IE: ''Fo: Wormhole.PVT''.  Lemme  know,  as  it  is\neasily updated.)\n\nThe  tailer  that  is  added  to  an outgoing email contains your\npersonal tag: (doors:email/signature.txt). Change  this  to  suit\nyour BBS etc. The easy part:)\n\nMAIL READ:\nAs  you  know,  any incoming mail contains a shitload of crap and\ninformation as a header. It also contains your email  address.  I\nhave  added  a  routine  that removes most of this when a user is\nonline reading their mail. It takes a complete  email  and  scans\nthrough  until  it  finds  the  string: "X-Mailer:" ...thereafter\nshowing the rest of the file,  nothing  beforehand.  So,  if  you\nhave  users on your BBS that you don''t much care for...well, they\nwill  never  get  to see your (*) email address. Plus, the screen\ndoesn''t become cluttered up with unwanted information.\n\n(*) Remember all mails  returned  to  BBS  users  are  originally\naddressed  to  YOU.  You''ll  soon  see.  If  you scan a .PVT file\ndirectly from YAM you''ll see  all  the  information  in  the  YAM\nheader that is cut out when viewing through Ami-Express.\n\nKILL:\nI agonised over this for days. Finally came  up  with  this  lame\nidea  for  deleting  mail.  It  deletes all current mail for that\nuser. They have chances to download etc. It will ask whether  the\nuser wants to KILL the mail yet (or not). It works just fine  and\nI see no reason to update it in the future. Slouch. Beer burp.\n\nABOUT + INFORMATION:\nSimple text files to add flair. Puh. Spit.\n\n------------------------------------------\n\nIf  the door is in use then no other node can access their email,\nhaving  to  wait until user1 is finished. Simultaneous use of YAM\nscanning etc could result in World War IV.\nOr so I theorise.\n\nWhat happened to WW3?\nProbably occurred, between me writing this and you reading this.\nWe''ll see. Always be prepared.\n\nAnyway, Def-Base tells me that it is possible to  make  the  door\nmultinode  friendly,  but  I haven''t got around to that yet. He''s\nsmarter than the average bear, + I''m still trying to understand.\n\n:P\n\n------------------------------------------\n\nRead mail options:\n\nDownload:  Let  you  download  the  current  file.  A  counter is\ncurrently running that makes each new download:\n\n YourMail1\n YourMail2\n YourMail3  ...etc...\n\n...so files don''t overwrite each other at the user''s end.\nCan''t remember if NCOMM etc overwrite in that way.\nBut I programmed it in anyway :)\n\nREPLY:  Accesses  the  text  editor,  already supplying the email\naddress of current-read email. Simple.\n\nFILE  ATTACH has been re-installed, as I was bored. As to whether\nit functions correctly, I don''t know. Seems fine to me. Test.\n\nEXTRAZ:\n       mosearch.info  (*)\n       cumail.txt\n       nomail.txt\n       logonsearch.rexx\n       scanit.rexx\n\n(*) Info file goes in usual BBS:commands/bbscmd. The other  files\nare  left  where  they are. Two txt files can be changed to suit,\nload up into suitable ANSI/TEXT editor.\n\n(*) Add: ~CC_MOSEARCH ...to your logon script. You know how.\n    Shows whether the logged-on user has email or not.\n    Will load YAM if not already loaded. Beware!\n\nAnd that''s about it.\nAs usual, all ideas/abuse appreciated.\n@endnode\n@node "auth" "Contact"\nContact:   [email removed]\n\nBBS        Wormhole/JaDe: Digital Candy\n           JaDe         : 13th Hour\n           Moriarty     : Havok\n\nIRC:       Peace4U/[-JaDe-]/WoRmHoLe\n           #England            - undernet.org\n           #Am!ga              - stealth.net\n           #100%FullOnSexPics  - :)\n@endnode\n@node "file" "Files"\nWhen   program  runs  it  loads  (if  not  already  loaded)  YAM,\nsearching for it in the usual YAM: assign.\n@endnode\n@node "fina" "Jerry Springer''s Final Thought..."\nAnsi  for  MO-SEARCH created using the style of Tango. Tango, the\nman himself, recoloured a mainmenu.txt for me, but I lost  it  in\na hard drive crash.  If  I  can contact Tango then I will ask for\nanother, else I will throw something shite together myself.\n\nYAM courtesy of Marcel Beck.\n@endnode\n@node "inst" "Getting this fecker to work..."\nJust put all files where they should be. Phhhhhh.\nRexxMast and RPstart must be running.\nCheck AEDocs for RPstart instructions.\n\nMost important: Find ''Folder.cfg'' and load into  a  text  editor,\nchanging  the number 4 to any desired folder of YAM that you wish\nto store all BBS-Emails. 0 -  3  are  Incoming,  Outgoing,  Sent,\nArchived.  Custom folders begin at 4. Please consult YAM guide on\nhow to achieve multiple orgasms. Erm, folders.\n\nMAKE SURE that all files go where I say they  should.  You  might\nthink  it  okay that you have ''waitforport'' etc in your SYS:REXXC\ndirectory, but Mo-Mail wants it in C: (for my personal ease),  it\nwon''t go searching for it. It doesn''t give a feck.\n@endnode\n@node "Bugs" "Those feckin crawlies..."\nYAM  looks  for  aliases:  If  a  user  tries  to enter a non-net\naddress when writing an email it will store this as an  error  in\nYAM,  so  next  time you open the YAM icon it will show a list of\nerror messages. Just clear these and cancel  any  other  unwanted\nwindows.  If  YAM is left un(?)iconified then this will leave the\nsystem hanging when a user endters a stupid address. A  real  net\naddress is something with ''@'' in it. Etc.\n\nMo-Email,  as  said before, kicks YAM into HIDE mode, so don''t be\nfuckin'' around with it. It ain''t no toy:P\n\nAlso: You might wanna change your ''realname'' config in  YAM  main\nprogram,  as  all  emails sent out contain your address - for all\nreturned mail/replies etc. Change it  to  something  like  ''Email\nUser'', or some lame crap like that. Further explaination on this\nis beyond me right now, new headache.\n@endnode\n\n','\n',char(10)),NULL,'auto-added',33852,2,0,NULL,NULL,'momail15','scan',1780048612);
