INSERT INTO door_catalog VALUES('mst_fcop','MST-FCOP.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MST-FCOP.LHA','AmigaGuide','XIM','AmigaGuide',NULL,'Colorboy/Mystic','MST','/  v  ¼\   v ¼\   ____  _   _____/  .   / /  \ /   \__.   \___  ¼\/    |   ¼\  |__/_ /    v     \ |    \ v    \    |     \ |   ¼\',replace('   __ ___ ___ __ _____________.____________ \n  /  v  ¼\   v ¼\   ____  _   _____/  .   / \n /  \ /   \__.   \___  ¼\/    |   ¼\  |__/_ \n/    v     \ |    \ v    \    |     \ |   ¼\\n\____|___  /____  /____  / ___|___  /____  /\n½-#e#----\/-----\/-----\/\/-------\/-----\/-\nColorboy/Mystic presents ya now\n             ''FREECOP''\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `-