INSERT INTO door_catalog VALUES('mst_jc40','MST-JC40.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MST-JC40.LHA','JoinCnf','XIM','JoinCnf',NULL,NULL,'MST','¦_/\___/\___/\___                          ¦ |\   /\ __/_  __/ Added Features:          | |/ Y \/_.¬\/  \   o Totally NEW Lay-Out    |',replace('+[ MYSTiC /X-POWER ]-----[ JoinCnf 4.0 ]---+\n¦_/\___/\___/\___                          ¦\n|\   /\ __/_  __/ Added Features:          |\n|/ Y \/_.¬\/  \   o Totally NEW Lay-Out    |\n/  | \\¬¦ \\  \\  o Manages up to 256 Cnfs |\n\__l_//___//__//                           ¦\n|dL!\/   \/  \/    Try it and be AMAZED!!  |\n+-[ EMPiRE/MYSTiC ]----[ XIM - /X 3.38+ ]--+\n','\n',char(10)),'JoinCnf.DOC',replace('\n                  ###### ###   ## ######  ### ######  ######              \n    _______|\     ###    #### ### ###  ## ### ###  ## ###       /|________\n   |         >    ####   ######## ######  ### ######  ####     <         |\n   | |¯¯¯¯¯|/     ###    ### # ## ###     ### #####   ###       \|¯¯¯¯¯| |\n   | |            ###### ###   ## ###     ### ### ##  ######           | |\n   | |_________________________________________________________________| |\n   |                                                                     |\n   |                            JoinCnf V4.0                             |\n   |                            ~~~~~~~~~~~~                             |\n   |                             TYPE:  XIM                              |\n   |                                                                     |\n   |                   ©1994  EMPiRE / MYSTiC /X-PoWeR!                  |\n   |                                                                     |\n   |       LaSt OuTpOsT  +31-72-157682 & +31-72-201182  -  HOLLAND       |\n   |                                                                     |\n   |       AmixNet:  @NL0004   -   /X-Fido:  44:100/102     EMPiRE       |\n   |_____________________________________________________________________|\n \n===============================================================================\n\n PURPOSE:\n ~~~~~~~~\n  o This DOOR is a alternative to the ''j'' command in /X 4.xx\n\n  o At the moment i''m using 36 Conferences and I don''t want Users\n    to ''See'' Conferences where they don''t have Access to, like the Private\n    Conferences.\n\n  o SplitUp between the File and the NetMail Conferences (optional)\n\n  o Passwords Checking for Access to Private Conferences.\n    If a User fails to enter the right Conference Password it will be Logged\n    in DOORS:Doors.LOG and/or he/she will be Kicked-Off (optional)\n\n  o Cursor-Key control for Conference selecting.\n\n  o It''s possible to have more Conferences then there would fit on one screen.\n    Up to 256 Conferences are no possible.\n\n\n===============================================================================\n\n REQUIREMENTS:\n ~~~~~~~~~~~~~\n  Ami Express 4.xx\n  It Doesn''t work with Ami Express 1.1x or 2.xx!!\n\n\n===============================================================================\n\n INSTALLATION:\n ~~~~~~~~~~~~~\n  o Copy the EmP_Tools Directory to DOORS:\n  o Make sure ENV: exists! (standard with OS2.x+)\n  o Merge your NodeX/JoinConf.txt with my DOORS:EmP_Tools/JoinCnf.CFG and\n    Edit it to your Needs. (Check the Existing JoinCnf.CFG!)\n\n JoinCnf.CFG LayOut:\n\n##[ start: cut here ]#########################################################\nLOGFILE            Doors:Doors.LOG  ; Log File Name for Password Failures\nDUAL_LISTING       YES              ; Use 2 Listings [YES/NO]\nCURRENT_CNF        YES              ; Show Current Conferences [YES/NO]\nCNF_NAMES          NO               ; Use Names from ConfConfig.info Icon [/X 3.x]\nNRCONFLINES        11               ; Nr Lines used for Conferences\nPASSWORD_LEVEL     256              ; Password Protection Below Level\nNETMAIL_STARTCNF   24               ; First NetMail Conference Number\nDROP_DTR           3                ; Drop Carrier after 3 Password Failures\n[Init_END] ==============================.=====================================\nCNF_NAME.1 =.................... NEW USER\nCNF_NAME.2 =................. AMiGA UTiLS\nCNF_NAME.3 =............. AMiGA <OUTPOST>\nCNF_NAME.4 =.............. SNES <OUTPOST>\nCNF_NAME.5 =...... MEGADRiVE/MS <OUTPOST>\nCNF_NAME.6 =........... GAMEBOY <OUTPOST>\nCNF_NAME.7 =......... GAME GEAR <OUTPOST>\nCNF_NAME.8 =......... PC-ENGiNE <OUTPOST>\nCNF_NAME.9 =.............. LYNX <OUTPOST>\nCNF_NAME.10=........... NEO-GEO <OUTPOST>\nCNF_NAME.11=........... CONSOLE <OUTPOST>\nCNF_NAME.12=............... C64 <OUTPOST>\nCNF_NAME.13=..................... COPiERS\nCNF_NAME.14=.................... REQUESTS\nCNF_NAME.15=.................. /X SUPPORT\nCNF_NAME.16=.................... ROM BASE\nCNF_NAME.17=.............................\nCNF_NAME.18=.............................\nCNF_NAME.19=............. UniFIX BetaSITE\nCNF_NAME.20=......... /X-PoWeR! BeTa-ArEa\nCNF_NAME.21=............ MYSTiC <PRiVATE>\nCNF_PASS.21=NONOFYOURBUSINESS\nCNF_NAME.22=............ MYSTiC SCENETALK\nCNF_PASS.22=NONOFYOURBUSINESS\nCNF_NAME.23=............ MYSTiC /X-PoWeR!\nCNF_NAME.24=[AX0001]........ /X Net Admin\nCNF_NAME.25=[LS0001]....... C Programming\nCNF_NAME.26=[LS0002]..... ASM Programming\nCNF_NAME.27=[LS0003].... REXX Programming\nCNF_NAME.28=[PN0001].......... Pirate NET\nCNF_NAME.29=[HLT001]........... DuTCH NeT\nCNF_NAME.30=[ADV001]...... Adventure Help\nCNF_NAME.31=[PFT001]........ Amiga Topics\nCNF_NAME.32=[MOV001]........ Movie Topics\nCNF_NAME.33=[AA0001]......... ANSI Topics\nCNF_NAME.34=[WBS001].......... Buy & Sell\nCNF_NAME.35=[CHBX01].......... ChatterBox\nCNF_NAME.36=[CNS001]........ Console News\n[CNF_END]================================^====================================\n  [36m___/\  ___/\  ___/\  ___/\ ___/\  ___/\  ___/\  ___/\  ___/\  ___/\  ___/\\n  \[35m_ [36m. \ \_ . \ \_ . \ \  __\\  __\ \_ . \ \  __\ \_ . \ \  . \ \  __\ \  __\\n  [35m/  |__\/  |  \/  |  \/  ._l/  ._l_/  |__\/  ._l_/  |  \/  |__\/  ._l_/__.  \\n /   ¡   \  ¡   \  |   \  | /   ¡   \  .   \  ¡   \  |   \  ¡   \  ¡   \  ¡   \\n [34m\_____  /______/__¡_  /__¡ \_____  /__¡_  /____  /__¡_  /____  /____  /____  /\n-------\/------------\/-----------\/-----\/-----\/[Ð!]-\/-----\/-----\/-----\/-\n[TITLE_END]===================================================================\n[34m.--------[35m[  [36mFILE CONFERENCES  [35m][34m--------.-------[35m[  [36mNETMAIL CONFERENCES  [35m][34m------.\n|[38C|[38C|\n|[38C|[38C|\n|[38C|[38C|\n|[38C|[38C|\n|[38C|[38C|\n|[38C|[38C|\n|[38C|[38C|\n|[38C|[38C|\n|[38C|[38C|\n|[38C|[38C|\n|[38C|[38C|\n|[38C|[38C|\n|[38C|[38C|\n+--------------------------------------^--------------------------------------+\n[LINES_END]===================================================================\n[34m|[77C|\n`-----------------------------------------------------------------------------''\n[CURCNF_END]==================================================================\n##[ end: cut here ]###########################################################\n\n\n\n  - If ''CNF_NAMES'' is set to YES then the CNF_NAME.xx is taken from\n    the BBS:ConfConfig.info Icon [/X 3.x].\n    This makes the CNF_NAME.xx in JoinCnf.CFG obsolete.\n    It''s also possible to Mix this with the Names from JoinCnf.CFG, first\n    the Names from BBS:ConfConfig.info or s:Acp.Startup are read and then\n    the names from JoinCnf.CFG are written over the old ones.\n  - CNF_NAME.x can''t be longer the 80 Characters.\n  - CNF_PASS.x can''t be longer the 40 Characters.\n\n\n[Init_END] ====================================================================\nCNF_NAME.2 =........... AMiGA PUBLIC DOMAIN\nCNF_PASS.15=PASSWORD\nCNF_PASS.16=PASSWORD\nCNF_NAME.18=[AX0001]. /X Net Administration\nCNF_NAME.19=[LS0001]......... C Programming\nCNF_NAME.20=[LS0002]....... ASM Programming\nCNF_NAME.21=[LS0003]...... REXX Programming\nCNF_NAME.22=[PN0001]............ Pirate NET\nCNF_NAME.23=[HLT001]............. DuTCH NeT\nCNF_NAME.24=[PFT001].......... Amiga Topics\n[Cnf_END]=====================================================================\n\n\n  - If you don''t want to Use the ''PASSWORD_LEVEL'' Option then set is to a\n    value greater than 255, this way Everyone has to enter the Private \n    Conference Password.\n\n  - For now I expect that all Conferences above ''NETMAIL_STARTCNF'' are\n    NetMail Conferences so if this isn''t the case or you don''t want to use\n    the File/NetMail Splitup then set NETMAIL_STARTCNF to 0\n\n  - Set ''DROP_DTR'' to the number of Password-tries before the User is Kicked.\n    He/she will not be able to use JoinCnf until ENV:JC-PWFAIL.{SLotNr} has\n    been deleted (for example after a SystemReset).\n    Use ''0'' to disable this option.\n\n\n  AE 4.xx:\n  ~~~~~~~~\n  - Copy J.info,<.info & >.info to BBS:Commands/BBScmd/\n\n    Or add to J.info, <.info & >.info ICON ToolType Info:\n\n      ACCESS=001\n      LOCATION=DOORS:EmP_Tools/JoinCnf\n      MULTINODE=YES\n      PRIORITY=0\n      STACK=50000\n      TYPE=XIM\n\n  - If you want ''Relative Conferences'' then you add the following to\n    BBS:CONFCONFIG.INFO IconToolType Info: \n\n      RELATIVE_CONFERENCES\n\n\n===============================================================================\n\n USAGE:\n ~~~~~~\n  Just enter J, < or > on the MAIN screen in AmiExpress.\n\n  Selecting > x or < x  will make JoinCnf jump x Conferences Up or Down.\n\n===============================================================================\n\n ERROR MESSAGES:\n ~~~~~~~~~~~~~~~\n\n  o ERROR:  DOORS:EmP_Tools/JoinCnf.CFG Not Found !!!\n  |\n  `--> JoinCnf.CFG can''t be found in DOORS:EmP_Tools !?\n\n  o ERROR:  BBS:ConfConfig Not Found !!!\n  |\n  `--> BBS:ConfConfig can''t be found in BBS:\n\n  o ERROR:  JoinCnf 3.0 ONLY Works with /X 3.xx!!\n  |\n  `--> Obvious\n\n  o ERROR:  UnKnown Keyword: XXXXXXXX in JoinCnf.CFG\n  |\n  `--> There must be 8 different KeyWords in the INIT part (JoinCnf.CFG)\n       Compare this with the original JoinCnf.CFG\n       Check that the KeyWords are:\n\n         LOGFILE\n         DUAL_LISTINGS\n         CURRENT_CNF\n         CNF_NAMES\n         PASSWORD_LEVEL\n         NETMAIL_STARTCNF\n         DROP_DTR\n         CURSOR_KEYS\n\n  o ERROR:  CNF_NAME part of JoinCnf.CFG is NOT Valid!!\n  |\n  `--> Check that all CNF_NAME.xx are correct and that xx is a Valid Conf.\n       The Line has to start with CNF_NAME.xx=  (example: CNF_NAME.1 =)\n\n  o ERROR:  CNF_PASS part of JoinCnf.CFG is NOT Valid!!\n  |\n  `--> Check that all CNF_PASS.x are correct and that x is a Valid Conference.\n       The Line has to start with CNF_PASS.xx=  (example: CNF_PASS.1 =)\n\n  o ERROR:  BBS:Access/AREA.x Not Found!!\n  |\n  `--> An User got an ConferencesAccess (x) that doesn''t exist (anymore)!!\n\n  o ERROR:  ToolType NCONFS doesn''t Exist in BBS:ConfConfig.info!!\n  |\n  `--> Should/Will never happen... /X Wouldn''t have started!\n\n  o ERROR:  CNF_PASS.x in JoinCnf.CFG is LONGER then 40 Characters!!!\n  |\n  `--> Edit CNF_PASS.x password to a smaller one (< 40 Characters)!\n\n  o ERROR:  Only 256 Conferences are Supported for now!!!\n  |\n  `--> Contact EMPiRE and Blackmail/Bribe him in making a ''Bigger'' version.\n\n\n===============================================================================\n\n BUG REPORT & SUGGESTIONS:                                                                   \n ~~~~~~~~~~~~~~~~~~~~~~~~~\n  It''s possible that a mistake will occur.... Nobody is Perfect.\n  If you have any Suggestions or Comments Please Leave a Message on my Board:\n\n   LaSt OuTpOsT  N1: +31-72-157682  N2: +31-72-201182  -  HOLLAND\n   ~~~~~~~~~~~~  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~     ~~~~~~~\n   AmixNet:  @NL0004\n   /X-Fido:  44:100/102\n   UUCP   :  [email removed]\n\n===============================================================================\n\n NOTE:\n ~~~~~\n  o This Program Has been tested on a /X 3.x - /X 4.6TD (4.7) Configuration.\n  o If you don''t use Conference Passwords then the < and > references are\n    not necessary and can be left out if you want, because the internal\n    < and > are always a bit faster.\n  o The ScreenUpdating is not that fast but there is (for now) no faster\n    way to do this as it is done now! (or get a FASTER modem!)\n\n\n===============================================================================\n\n REGISTRATION:\n ~~~~~~~~~~~~~\n  If YOU use this Program please let me know by Calling Last Outpost or\n  to send me a Message by NetMail @NL0004 - EMPiRE  Coz I want to know\n  how many Sysops are using my Tools!!!\n \n\n===============================================================================\n\n HISTORY:\n ~~~~~~~~\n  V1.0  07-05-92 - Release Version\n\n  V1.1  07-15-92 - Improved Password Checking\n\n  V1.2  07-28-92 - The internal j(oin) command can be changed.\n                 - Relative Conferences: ConfAccess _______X_ -> j 1 !!!\n\n  V1.3  07-29-92 - Made ''Relative Conferences'' selectable. Default OFF\n                 - Improved Conference selection.\n\n  V1.4  08-03-92 - Default ''Relative Conferences'' is YES. As it''s now Default\n                   in /X 2.1 [1 Aug''92]\n                 - Moved ''Relative Conferences'' to the Config file\n                   [ JoinCnf.CFG CHANGED! ]\n                 - Bug Removed:\n                    o The Door Failed when e.g ''J 1abcd'' was entered.\n                    o Minor Bug removed in the Password Protection.\n\n  V1.5  08-23-92 - Changed the ColorLayout a bit.\n\n  V1.6  09-11-92 - Request Update for THC/DESiRE: 2 Conference Lists.\n                   [ JoinCnf.CFG CHANGED! ]\n\n  V1.7  10-21-92 - Small Improvements.\n\n  V1.8  01-23-93 - Small Improvements in the 2 Conference Lists.\n\n  V1.9  01-25-93 - Bug Report from JPS (Tnx!):\n                    o 1 Cnf List Failed, 1 Line of Code was Accidentally\n                      Killed from the Source.... \n\n  V1.10 02-22-93 - Changed Layout a bit\n\n  V2.ß  04-22-93 - /X 3.1 UPDATE!!! - It''s Still BETA coz I Just got /X 3.1\n                   2 Hours ago!\n        04-29-93 - Added < and > Support because of Password Protection\n        05-03-93 - Better Error Checking (''Fool'' Proof?!)\n        05-04-93 - Changed whole Config (JoinCnf.CFG) Layout!!\n                   [ JoinCnf.CFG CHANGED! ]\n                 - Added ''Current Confererence'' Option\n        05-06-93 - Bug Report from Aragorn/Vision (Tnx!):\n                    o Rexx claims that 2a,2b,.. exist between 1 to 20 (dec)\n\n  V2.0  05-09-93 - Release Version\n\n  V2.1  05-10-93 - Minor Update. The date in Doors.LOG file was wrong.\n        05-20-93 - Added ''Password Level'', this way the Sysop/CoSysop doesn''t\n                   need to enter a Conferences Password eachtime he Joins\n                   that Conference. (Thanx to Alcoholic for the Idea!!)\n                   [ JoinCnf.CFG CHANGED! ]\n        05-27-93 - Fixed the UpperCase Problem in JoinCnf.CFG and all used\n                   Icon Files [/X 3.x]\n\n  V2.2  06-18-93 - Updated the ''<'' & ''>'' code.\n        06-21-93 - Fixed a small Error found with the RexxDoorDebugger.\n        06-28-93 - Added the ErrorMessages in the doc.\n\n  V2.3  07-23-93 - Better Error handling\n\n  V3.ß1 08-10-93 - At last the XIM Version! Rexx is a thing of the Past!\n                 - Changed ALL References from AIM to XIM !!!\n                 - Keywords ''NRSPACES'', ''RELATIVE_CONFERENCE'', ''NCONFS'' are\n                   deleted from JoinCnf.CFG (Obsolete) because they are now\n                   ''read'' from the BBS:ConfConfig.info [/X 3.x] or\n                   s:ACP.Startup [/X 2.xx]\n                   [ JoinCnf.CFG CHANGED! ]\n\n  V3.ß2 08-13-93 - Keyword ''NRLINES'' is deleted from JoinCnf.CFG.\n                 - Keyword ''NETMAIL_STARTCNF'' added to JoinCnf.CFG\n                   If there are NetMail Conferences then the Conference\n                   showing can be split in 2 (Files & Netmail).\n                 - Renamed Keyword ''2_LISTINGS'' to ''DUAL_LISTING''\n                   [ JoinCnf.CFG CHANGED! ]\n                 - Included Optimized 030 Version!\n\n  V3.ß3 08-15-93 - Added the ''LOGFILE'' Option. Password Failures on Private\n                   Conferences will be logged in DOORS:Doors.LOG (default)\n                 - Added the ''CNF_NAMES'' Keyword (was ''CONFCONFIG_NAMES'')\n                   Now ConferenceNames from BBS:ConfConfig tooltype [/X 3.x]\n                   (or s:ACP.Startup [/X 2.xx]) and CNF_NAME.xx from\n                   JoinCnf.CFG can be Mixed in the Output.\n\n  V3.ß4 08-23-93 - Optimized the code and it''s now about 2 kb smaller\n                 - Bug Report from Beast (Tnx!):\n                    o JoinCnf failed completely when the OLD ''LOADCONFIG''\n                      option in ACP.Startup was used [/X 2.xx]\n                 - DEBUG OPTION: enter !% as Conference and you get some info\n                                 when all goes wrong.\n\n  V3.0  08-26-93 - Release Version.\n                 - All Debug routines removed.\n                 - Optimized 030 Version Included.\n\n  V3.1  09-04-93 - Bug Reports from ByteAndi/MST:\n                    o The Last conference couldn''t be joined when Not using\n                      ''RELATIVE_CONFERENCE'' (only happend in the Menu)\n        09-05-93 -  o Sometimes when only entering ''J'' a Conference would be\n                      joined. This is due to a BUG in /X... Fixed for now!\n        09-11-93 - Release Version.\n\n  V3.2  10-02-93 - /X 3.11 Update... AE Returned a different VersionNumber\n                   then in previous versions... this made JoinCnf think that\n                   it wasn''t /X 3.xx but /X 2.xx... FIXED!\n\n  V3.3ß 10-09-93 - Bug Report from ByteAndi/MST:\n                    o Conference Passwords bigger than 80 Chars would Halted\n                      the system! The maximum CNF_PASS size is now 40 Chars.\n                 - Updated some more code. Needs Lesser memory to run.\n                 - Better Error checking.\n        10-14-93 - Bug Report from Sal1/TRSI:\n                    o /X 2.xx & NOT using ''RELATIVE_CONFERENCE'' still failed.\n                      Should be fixed now!\n                 - When the KeyWord ''LOADCONFIG'' is used in the Acp.Startup\n                   [/X 2.xx] then the ''Current Conference'' Option will be\n                   Disabled! \n                 - Some more Code-Optimizing.\n\n  V3.3  12-01-93 - Release Version\n                 - Included an Optimized 020 Version for A1200/A4000 Users.\n                 - Just replace the Old JoinCnf with the New One!\n\n  V3.4ß 01-16-93 - Bug Report from Sal1/TRSI:\n                    o When Using /X 3.20+ & ''NETMAIL_STARTCNF  0'' & Not Using\n                      ''RELATIVE_CONFERENCE'' the Conferences were not shown.\n                 - Added ''DROP_DTR'' option, it Drops the Carrier of the\n                   User after he/she fails to enter the Right Password for\n                   a number of times. After this he/she won''t be able to use\n                   JoinCnf until the file ENV:JC_PWFAIL.{SlotNr} doesn''t exist\n                   anymore (for example after a systemreset). When he tries\n                   he will be Kicked-Off right away!\n        01-17-94 - Bug Report from Mike Hoffren:\n                    o Using 108 Conferences will Crash the System!\n                      In the past it was ''Only'' possible to use 100 Confs,\n                      I never thought there would be more than that!\n                      It''s been Fixed to 256 Conferences for now\n                 - When JoinCnf is run, it will ShowUp on the Server.\n        01-21-94 - Change the Command-Line a bit.\n                 - JoinCnf will now make Use of the full 80 Chars/Line, this\n                   means that LayOut of JoinCnf.CFG Changed a bit!\n                   [ JoinCnf.CFG CHANGED! ]\n        01-25-94 - Fixed the ''10-Node'' BUG. Using Node 10+ would result in\n                   JoinCnf thinking it was started from Node 1.... FIXED!\n\n  V3.4  01-29-94 - Release Version.\n\n  V3.5ß 02-01-94 - Change the ''Full Use of 80 Chars/Line'' to 79 Chars/Line\n                   because some Terminals on Amiga/PC can''t handle the 80th\n                   character on the right (extra linefeeds)!\n                   [ JoinCnf.CFG CHANGED! ]\n                 - Took out all 100+ Conferencing coz /X-Fido is on it''s way\n                   now (so no need for 100+ Conferences) and otherwise the\n                   Code becomes too big! A 100+ Version Can be REQUESTED!\n        02-06-94 - Changed the CommandLine-Input so only Numbers can be\n                   selected.\n                 - Added some BETA-Code to use the Cursor-Keys to select a\n                   Conference. The only BIG problem exists when there are too\n                   many Conferences and the Screen starts scrolling....\n        02-09-94 - Updated the Cursor-Key Code so it''s now possible to Use\n                   Cursor-Keys only if the JoinCnf output-screen fits in the\n                   Users terminalscreen (without scrolling). If it doesn''t\n                   ''fit'' then the Cursor-Keys are disabled otherwise it would\n                   mess up the screen!\n                 - Added the ''CURSOR_KEYS'' KeyWord, when it''s ''NO'' then there\n                   will never be made use of ANSI when using the Cursors.\n                   When the KeyWord is ''YES'' or is leftout then ANSI is used\n                   when the JoinCnf-Screen ''fits'' in the Users TerminalScreen.\n                   [ JoinCnf.CFG CHANGED! ]\n                 - Note: For now the Cursor-Code works only with Relative\n                         Conferences.\n        02-16-94 - Fixed a Small Bug in the Password Handling.\n        02-20-94 - Fixed the Non-Relative Conferences problems so now it will\n                   work on ANY /X 2.xx or 3.xx configuration.\n        02-21-94 - Fixed a Bug in printing the Command-Line to Screen. It\n                   failed when there where Non-Even FileConfs & NetMailConfs.\n                 - Changed the Cursor-Handling. The ''jump'' from FileConf to \n                   NetMailConf has been changed.\n        03-08-94 - Optimized the Cursor-Key Routine.\n\n  V3.5  03-13-94 - Release Version.\n\n  V3.6ß 04-11-94 - Added the ''Q'' to the CommandLine on Tycoon''s Request:\n                    o Pressing ''Q'' will now Exit JoinCnf Immediately, even\n                      when a Conference is selected.\n        04-14-94 - Killed all sscanf''s in the Source coz of Bugs in the\n                   SAS Compiler and this way JoinCnf gets 2 kb smaller!\n        04-17-94 - After a long talk with ByteMaster I managed to kill some\n                   obsolete code, this will make JoinCnf startup Faster!\n                 - Added an New CommandLine Option: \n                    ''> 4''  will Join: Current Conference + 4 (if it Exists)\n                    ''< 9''  will Join: Current Conference - 9 (if it Exists)\n                    ''< -2'' will Join: Current Conference + 2 (if it Exists)\n                 - ReCompiled with the Latest AE.Includes\n        06-28-94 - Fixed some code that can cause random guru''s (SAS C Bug!)\n                 - Removed ALL /X 2.xx support because of the new AE.Includes\n                   JoinCnf won''t work on any /X version before /X 3.38, if\n                   you still have not upgraded then this is the time to do so!\n\n  V3.6  07-01-94 - Release Version.\n\n  V4.0ß 09-20-94 - Changed the Total layout of JC\n                 - The maximum of used conferences has been changed from 100\n                   to 256 (Should be MORE than enough.. if not TELL me!)\n                   [ JoinCnf.CFG CHANGED! ]\n        10-01-94 - Removed the Hide Cursor ansi ("[0 p") coz some terminals\n                   can''t handle this and will print nice p''s thru the screen.\n                 - Added Single Conference Layout.\n        10-04-94 - Fixed a bug that not all Conferences could be selected.\n                   tried to read the PageUp/Down (without luck...)\n                 - Fixed the NonRelativeConference Bug (as usually i am slow\n                   on this... for obvious reasons). [Sal-One]\n                 - Added the ''NRCONFLINES'' KeyWord, this is the number of\n                   conferences which will be printed on the screen.\n                   (Keep in mind that you must also edit the border in\n                   JoinCnf.CFG)\n                   [ JoinCnf.CFG CHANGED! ]\n        11-27-94 - The ScreenUpdating is now faster by only rewritting 1\n                   Conference list at the time.\n                 - Removed the Beta-Code\n\n  V4.0  02-01-95 - Release Version\n\n\n===============================================================================\n\n EMPiRE /X DOORS/UTILS COLLECTION UNTIL NOW!:\n ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n  - AboStats V0.2                        AIM Door\n  - AE2PCE V1.0                          CLI Util\n  - AutoOnline V1.3                      XIM Door/Util\n  - Bulls V2.3                           XIM Door\n  - CheckDir V1.0                        CLI Util\n  - CheckNU V1.0                         XIM Door\n  - ConfAccess V1.1                      ServerUtil\n  - CopyDate V1.3                        CLI Util\n  - DlDir V2.2                           XIM Door\n  - DoorKIT 1.01                         XIM Doors/Includes\n  - DMenu V1.0                           AIM Door\n  - DutchNET V1.0  [AmiXnet]             AIM Door\n  - Front V2.0                           XIM Door\n  - JoinCnf V4.0                         XIM Door\n  - LastCalls & TopUps V1.2              LogOffUtil\n  - LastDL V0.1                          LogOffUtil\n  - LastUL V0.1                          LogOffUtil\n  - MakeFree V1.1                        AIM Door\n  - MemberList V1.0                      AIM Door\n  - MonthTopUp V2.0                      ServerUtil\n  - MultiNodeLastCaller V1.1             LogOffUtil\n  - Page V2.1                            XIM Door\n  - PMail V1.1                           AIM Door\n  - Remote Maintenance V1.4              AIM Door\n  - SceneTalk Voter V2.3                 AIM Door\n  - SceneTalk Voter V2.2 [Party]         CLI Door\n  - SecLevChk V1.0                       ServerUtil\n  - Sent FrondEnd 1.0  [Sent_FE]         XIM Door\n  - StripCR V1.0                         CLI Util\n  - SysopCommands V1.0                   AIM Door\n  - UserData Cleaner/Repair V2.0         ServerUtil\n  - UserStats V2.0                       ServerUtil\n  - UsrCnfAx V1.1                        CLI Util\n  - View & Check Archive/Text V1.7       AIM Door\n  - WhoNode V1.3                         AIM Door\n\n\n===============================================================================\n\n THANX MUST GO TO ALL OFFICIAL BETA-TESTERS:\n ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n   Sal-One/TRSi              [BoonDocks]\n   Beast/Partek              [Sequencial]\n   SpeedDevil/Partek         [Rising Sun]\n   Galaxy                    [Ulixys]\n\n\n GREETZ/TNX GO TO:\n ~~~~~~~~~~~~~~~~~\n   Killraven/MST /X-PoWeR! - For giving me sum Great Pointers/Sources on ''C''\n   Tycoon/Mystic /X-PoWeR! - another EX-/X programmer...\n   ByteAndi/TRSI           - Tnx for all ya ''C'' Help & Sources!\n   Easy Rider/Mystic       - hope ya are back soon!\n   JAF/G.O.D.              - For some good REXX ideas\n   JPS                     - I think /X is still better!\n   Bad Sector/Hidden       - Still Using your Sort-Routine. It''s the Fastest!\n   B.O.B./CyberForce       - For (Mis)Using/Testing my tools! :)\n   Aragorn/Vision          - Tnx for Testing\n   Camelot/Complex         - Tnx for Testing\n   Sharon/5D               - Tnx for Testing\n   Telekinetic/T.F.A.      - Tnx for Testing\n   Alcoholic               - Tnx for Testing\n   Price/T.F.A.            - Great job on your {F}ull {S}creen {E}ditor!\n   Van Damme               - Nice Doors!!!\n   DR.G/IBB                - Hope to see Check''N Add work on a 040\n   SiGMA SEVEN             - Nice job on SiGMA-EXPRESS! Tempted to ''Convert''\n   911/Movement            - Tnx For ya Ansi Logo''s!! You''re the Greatest!\n   Mike                    - Tnx for calling!\n   Amicom/TRSi             - Tnx for calling!\n   THC/Legend              - Tnx for Beta-Testing!\n   Mega Fortress           - Tnx for Beta-Testing!\n   SkIn                    - Tnx for ya Description Logo! Looks Great!!\n   Shadow Man/S8           - Nice Doors & Tnx for ya greetz! & Calling ofcoz\n   [MAZ!^PHAZE]            - Tnx for calling!\n   Shuyuki Tanaka          - Tnx for your Messages!\n   AGONY/cOmpLeX           - Tnx for calling!\n   HUMANOiD & jABBA /MST & SCANDAL\n                           - Tnx for calling!\n   LECTOR                  - Tnx for your NetMail\n   Koo Koo Ka Choo         - Tnx for calling!\n   TaRzAN                  - Tnx for your NetMail. Yezz 040 Speed Rulez!!\n   Crayor/Scx              - Tnx for calling!\n   Foxx''n''Lynxx            - Tnx for your BugReports!!!\n   ThE BiRD                - Tnx for your NetMail on UsrCnfAx\n   Dux                     - Tnx for your NetMail\n   dR.dRE!/fAITH           - Tnx for da greetz, Nice Doors btw\n   [-RUNT&SCOTTIE-]        - Tnx for calling!\n   sPAcEcAKe/aF            - Tnx for calling!\n   Freddy Kreuger/GOD      - Tnx for your NetMail on JoinCnf 3.2\n   MF1                     - Tnx for calling!\n   AtomiX/N.A.S.A          - Hope the ''C'' archive was sume help for ya!\n   MAD HARLEQUiN [ITPH01]  - Tnx for your Nice AmiXnet Messy''s\n   Mike Hoffren  [SF0001]  - Tnx for the BugReport on JoinCnf 3.3 [100+ Cnfs]\n   Galaxy/TFA              - Nice job on da SentCleaner\n   SvEN tHE CREAToR/5D     - ''Tnx'' for forcing me to use Cursor-Keys!\n   Diogenes/TPY/5D         - Tnx for calling and for your BugReport!\n   L.A.Style               - Tnx For Calling/Beta-Testing!\n\n   & Ofcoz to ALL MYSTiC Members all over the Globe!\n\n\n NO TNX GO TO:\n ~~~~~~~~~~~~~\n   Vampire/TRSI  for being a BIG asshole by spreading our BETA''s.. LAME...\n\n\n                        ______  __________________                            \n.----------------+-----/    \ \/ / __/_  __/ / __/----------+----------------.\n|                |----/ / / /\  /\  /-/ /-/ / /----[ /X ]---|                |\n|       /\    /\ |-EmP\/ / /-/ /\  /-/ /-/ /\ \--[ PoWeR! ]-|       /\    /\ |\n|      /C \  /!/ +-----\/\/--\/--\/--\/--\/--\/-------------+      /C \  /!/ |\n|     /i/\ \/R/  |                                          |     /i/\ \/R/  |\n|    /T/  \ E/   |   EMPiRE   -   KiLLRAVEN  -   TYCOON     |    /T/  \ E/   |\n|   /S/   /W \   |                                          |   /S/   /W \   |\n|  /Y/   /O/\ \  |   RE/Y\o   -   INCOGNiTO  -   HARDBYTE   |  /Y/   /O/\ \  |\n| /M/   /P/  \ \ |                                          | /M/   /P/  \ \ |\n| \/    \/    \/ |                   BoBo                   | \/    \/    \/ |\n|                |                                          |                |\n`----------------+----------[  MYSTiC /X PoWeR!  ]----------+----------------''\n\n\n \n\n                       ____ _________ _________ ________ _____\n            MYSTiC    /   / \\  /    \\\  /   _\\\  /   \\\  /     MYSTiC\n                     /   /   \\/   /\ \\\/   /___\\/__   \\\/\n         CONSOLE    /   / /\  /   __   \ \____   \   /   /      AMIGA\n                   /   /_/  \/   / /   /_____/   /  /   /\n       WORLD-HQ    \________X___/ /___/\________/   \__/      EURO-HQ\n      ____ _________ ________ _________ _________ _________ ________ _____\n     /    \\\  /   / \\  /   \\\  /    \\\  /    \\\  /   _\\\  /   \\\  /\n    /   /\ \\\/   / /\\\/__   \\\/   /\ \\\/   /\ \\\/   /___\\/__   \\\/\n   /   / /  \/   / /  \   /   / /   _____\/   / /  \ \____   \   /   /\n  /   /_/   /   /_/   /  /   / /   /     /   /_/   /_____/   /  /   /\n  \________X_________/   \__/  \__/      \________/\________/   \__/\n\n\nAMIGA - SNES - MEGADRIVE - GAMEBOY - GAMEGEAR - PC ENGINE - LYNX NEOGEO - C64\n\n4.5 Gb ONLINE             SYSOP:  EMPiRE / MYSTiC               4.5 Gb ONLINE\n\nHOLLAND:              +31-72-157682  &  +31-72-201182               :HOLLAND\n\n','\n',char(10)),'{"ACCESS":"001","LOCATION":"DOORS:EmP_Tools/JoinCnf","PRIORITY":"0","STACK":"50000","TYPE":"XIM"}','auto-added',32939,6,0,NULL,NULL,'mst_jc40','scan',1780048619);
INSERT INTO door_catalog VALUES('mst_kb13','MST-KB13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MST-KB13.LHA','KiLLER_Baud','XIM','KiLLER_Baud',NULL,NULL,'MST','.-\_  \/  _/   __/______\/___/-------------. | /   \/   \______  \_  \/  \_   mYSTIC!   | :/     \____/   _____/___    / /X dIVISION .',replace('  __/\  __________ _ ___  /\__              \n.-\_  \/  _/   __/______\/___/-------------.\n| /   \/   \______  \_  \/  \_   mYSTIC!   |\n:/     \____/   _____/___    / /X dIVISION .\n/_______\-\_____/--sTZ--l___/--------------:\n| KiLLraVeN/MYSTiC BRiNGS: KiLLER-BAUD 1.3 |\n| *Creates bulls about users'' baud-rates!* :\n: o Exclude baud-rates  o Nice lay-out     |\n| o Two pages of info!  o Future proof!    |\n`------------------------------------------''\n','\n',char(10)),'KiLLER_Baud.Guide',replace('@DATABASE "KiLLER-Comment.GUiDE"\n@REMARK	.-------------------------------------------------------.\n@REMARK  | This document should be read with AmigaGuide (OS 2.x) |\n@REMARK  | or MultiView (OS 3.x) or any other guide reader. Tnx. |\n@REMARK  `-------------------------------------------------------''\n@REMARK	$VER: KiLLER Baud 1.3.0\n@WIDTH 80\n@NODE MAIN "KiLLER Comment - MYSTiC 1994 - © 1994 KiLLraVeN/MYSTiC"\n                             Guide to KiLLER Baud\n                 for Ami-Express 3.38+ Bulletin Board Systems\n\n                             Program version: 1.3.0\n                Compilation Date/Time: Thu Jan  5 14:32:32 1995\n\n                         © 1994/1995 by @{"KiLLraVeN/MYSTiC" link Contact}\n\n                   ... another fine MYSTiC /X production ...\n\n      @{" First words... " link WhatIs}    What is KiLLER Baud\n      @{" Features       " link Features}    What can it do?\n      @{" Installation   " link Install}    How to install KiLLER Baud on your system\n      @{" Example 1      " link BaudUsage}    Example output of bulletin 1\n      @{" Example 2      " link LastBauds}    Example output on bulletin 2\n      @{" History        " link History}    History of KiLLER Baud\n      @{" Greetings      " link Greetings}    Big hellos and messages\n@ENDNODE\n\n@NODE Contact "How to contact KiLLraVeN/MYSTiC - © Me me me! :)"\n                            .--------------------.\n                            |  Contacting me...  |\n                            `--------------------''\n\n       For FAST response (preferred) please contact me on Internet:\n\n                               [email removed]\n\n                    ( [email removed] -- backup )\n\n                       - - -- --- ------- --- -- - -\n\n                 I can be reached on the following boards:\n\n                       - - -- --- ------- --- -- - -\n\n                The Undiscovered       +31-2294-1442 (USR 28k8)\n                                       +31-2294-4442 (USR 28k8)\n                                       +31-2294-tRY! (USR 28k8)\n\n                Last Outpost           +31-72-201182 (USR 28k8)\n                                       +31-72-157682 (USR 28k8)\n\n         I know, you have to call The Netherlands for it, but it''s\n            the only boards I call on a frequent basis, sorry.\n\n                       - - -- --- ------- --- -- - -\n\n        You can also find me on IRC once in a while on the channels\n                   #amigascne, #amiga, #rave and #megawatt\n@ENDNODE\n\n@NODE WhatIs "What is KiLLER Baud - © KiLLraVeN/MYSTiC"\n                        .------------------------.\n                        |  What is KiLLER Baud?  |\n                        `------------------------''\n\n   KiLLER  Baud is (another) statistical mumbo jumbo door.  It is able to\n   create  some  nice  statistics  about  the baud rate your users use to\n   logon your system.  It is styled in the same way as @{"KiLLER Comment" link KiLLERComment}, so\n   if  you  are familiar with that door, you will know that the output of\n   it will be fair enough :-)\n\n   I  made  this  door  as a simple diversion of some other projects I am\n   working  on.   This  door  was created in two days and I don''t feel it\n   should  be  released  to  the  public  because  it is too simple to be\n   released.   The  idea  is not my own, I saw another ''accumulative baud\n   report''  door  and  I  am  still  recovering from the output that door\n   creates.   I  don''t  know where some people get their inspiration from\n   but that output reminded me of kindergarten ;-)\n\n   And  because  of  the  nice  respons  I  got from some sysops about my\n   previous  releases,  I  thought  it  would  be  nice  to  make another\n   statistical  door,  sysops can''t get enough of BBS statistics.\n\n   Anyway,  I hope you like it and if you do, please give me a yell.\n\n                                                         @{"KiLLraVeN/MYSTiC" link Contact}\n@ENDNODE\n\n@NODE Features "Features of KiLLER Baud - © Me me me and nobody else! :)"\n                           .--------------------------.\n                           |  Features of KiLLER Baud |\n                           `--------------------------''\n\n   ­ Create two pages of statistical data in one bulletin\n     (With a ''Space to Resume'' between them ofcourse)\n\n   ­ Create two pages of statistical data divided over 2 bulletins\n     (So two separate files)\n     \n   ­ Create either one of the two possible bulletins.\n     (You can choose between @{"Baud Usage" link BaudUsage} and @{"Last Bauds" link LastBauds})\n\n   ­ Only show the output on screen, don''t create the bulletins.\n     (Two pages, not selectable).\n\n   Other program features are:\n\n   · Fast baud detecting, virtually no delay for users.\n   · Very small data file to create bulletins\n   · You can remove baud rates from the bulletin(s).\n@ENDNODE\n\n@NODE Install "How to Install KiLLER Baud - © KiLLraVeN/MYSTiC (that''s me)"\n                      .------------------------------.\n                      |  How to install KiLLER Baud  |\n                      `------------------------------''\n\n   You are free to call the programs whatever you want and you can locate\n   the  program  wherever  you want.  I hate programs that have hardcoded\n   paths in their source.\n\n   The KiLLER_Baud executable has got a double function:  update the data\n   file  and create the bulletin(s).  Depending on available tooltypes in\n   the command icon, KiLLER Baud will know what to do.\n\n   ­­ Baud Detection ­­\n\n   First  of  all,  make  sure  that  KiLLER_Baud is run at least once to\n   update the data file.  I suggest you install it as an MCI command in a\n   bulletin  that  is  shown  to  every  user  that logs in (or logs out,\n   whatever fits you best).\n\n   · Example ·\n\n   ~CC_KB-DETECT\n   \n   · End ·\n\n   To  have  KiLLER_Baud  only  update the data file, create an icon that\n   holds  the tooltype "DETECT_BAUD".  If this tooltype is present in the\n   icon with what KiLLER_Baud was started, the data file will be updated.\n   This data file will reside in the same directory as the program itself\n   and will  be called "KiLLER_Baud.Data" and is 484 bytes in size.  Note\n   that  the  bulletin(s)  will not be created!  An example icon has been\n   provided called "KB-DETECT.info".\n   \n   Important tooltypes for that command are:\n   \n   DETECT_BAUD             ­ This tooltype MUST be present if you want KB\n                             to update the data file.\n                             \n   LOCAL_NODE=<number>     ­ KiLLER_Baud  will  not add your local logins\n                             to its data file.  Normally,  the local node\n                             would be node 0, but certain boards that run\n                             /X-Fido  for example have their last node as\n                             their local node.  So with this tooltype you\n                             can specify which node is the local node.\n                             \n                             You  can  also specify a node which does not\n                             exist,  and  your local logins will be added\n                             to the data file.\n                             \n                             Default value is node 0.\n\n   ­­ Bulletin Creation ­­\n\n   Unless  you  want  to install KiLLER_Baud as a regular /X command that\n   can  be  started  from  the  main  prompt,  you  also  need to install\n   KiLLER_Baud  as  another  MCI command, but this time to have it create\n   the bulletin(s).\n\n   You  can  specify the name(s) of the bulletin(s) with tooltypes.  Here\n   are the important tooltypes for this command:\n\n   BULL=<filename>         ­ When specified, one bulletin will be created\n                             containing 2 pages of statistics,  separated\n                             by a "Space to Resume".\n\n   BULL.1=<filename>       ­ This  will  result in one bulletin that only\n                             contains the @{"Baud Usage" link BaudUsage} information.\n\n   BULL.2=<filename>       ­ This  induces KiLLER_Baud to create only the\n                             @{"Last Bauds" link LastBauds} bulletin and nothing more.\n\n   NOTE¹ : The `BULL'' tooltype overrides both BULL.1 and BULL.2 !!\n\n   NOTE² : If you ommit all of these tooltypes, KiLLER_Baud will show the\n           bulletins on screen and will not create any bulletin.\n           \n   If  you  wish,  you  can  have  certain  baud  rates  removed from the\n   bulletins.   Normally,  the  bulletin would contain baud rates ranging\n   from  SLOW  to FAST, whereas SLOW means all baud rates below 9600 baud\n   and  FAST all baudrates above the highest speed available. Please note\n   that both the SLOW and FAST baud rates will not be put in the bulletin\n   until they are actually used.\n\n   For  example,  there  is  a BBS somewhere in Finland that has no 12000\n   baud users.  As strange as it is, this was true.  But the bulletin did\n   contain  the  12000  baud  line.  It was much disliked by the sysop of\n   that  board.   It even got to a point where he get himself drunk, felt\n   bad (a la Michael Jackson) and called The Undiscovered BBS.\n\n   There  he  wrote me a message saying that he hated the 12000 baud line\n   and  that  it  should  be removed.  I made him clear that although his\n   board  did  not  have 12000 baud users, the Undiscovered has got them!\n   He felt like an ass and left crying.  I felt so bad about this, that I\n   made it possible to leave out any baudrate you like.  However, this is\n   purely  COSMETIC.  The 12000 connects are still being counted and they\n   are  also used for the total number of connects.  But it was the least\n   I could do for such a lonely guy (snif).\n\n   So  without telling you the name of the sysop (QUARTZ QUARTZ QUARTZ!),\n   this is how to disable baudrates:\n\n   NO_SLOW     - Disable  SLOW baudrate\n   NO_9600     - Disable  9600 baudrate\n   NO_12000    - Disable 12000 baudrate (see! :) )\n   NO_14400    - Disable 14400 baudrate\n   ...\n   NO_FAST     - Disable FAST baudrate\n   \n   These  tooltypes  can be put in the K-Baud tooltype and remember, they\n   are  purely  cosmetic,  if  you  disable all baudrates and look at the\n   bulletin,  there  will  be NO baudrates mentioned, but there will be a\n   total number of connects and a favourite baudrate.\n\n   ­­ Regular /X Command ­­\n\n   If  you want it to install like a regular command, install it like any\n   other  command but make sure you remove the BULL#?  tooltypes from the\n   icon or it will create bulletins instead of showing them.\n\n   ­­ Overview ­­\n\n   ONCE AGAIN (but in short):\n   \n      · K-Baud can either create bulletins or display them pronto\n      · To make it create bulletins, either put the BULL tooltype\n        or BULL.x tooltypes in the icon (NOT BOTH!).\n      · To disable baudrates use tooltype: NO_<baudrate>\n      · If  you  remove all BULL* tooltypes from the K-Baud icon,\n        K-Baud will show the results on screen right away.\n\n   ­­ Reset the counting ­­\n\n   If  you  want  to reset the counting, simply remove the data file.  It\n   will  detect itself that the file is gone and create a new one (with a\n   new starting date).\n@ENDNODE\n\n@NODE LastBauds "Example Output: Last Baud (Bull.2) - © KiLLraVeN/MYSTiC"\n.-----------------------------------------------------------------------------.\n| KiLLER BAUD v1.0  ^  <> Baud Rate Statistical View <>  ^  KiLLraVeN/MYSTiC! |\n`-----------------------------------------------------------------------------''\n.----------------.--------------------------.---------------------------------.\n| Connect String | Date/Time last Connect   | Last Connect made by            |\n:----------------:--------------------------:---------------------------------:\n|   9.600 baud   | Fri Dec 16 12:14:45 1994 | ArCaDe/MYSTiC                   |\n|  12.000 baud   | Never                    | Nobody                          |\n|  14.400 baud   | Sun Dec 18 19:35:31 1994 | Kerstman                        |\n|  16.800 baud   | Sat Dec 17 09:03:12 1994 | Sal-One                         |\n|  19.200 baud   | Sun Dec 18 15:39:33 1994 | Incognito/MST                   |\n|  21.600 baud   | Sun Dec 18 11:32:50 1994 | WiSHBRiNGER                     |\n|  24.000 baud   | Fri Dec 16 23:11:22 1994 | skate BOB                       |\n|  26.400 baud   | Sun Dec 18 19:59:58 1994 | Motive Power/MST                |\n|  28.800 baud   | Sun Dec 18 02:13:26 1994 | KiLLraVeN/MYSTiC                |\n:----------------^--------------------------^---------------------------------:\n| Total Connects :  64041 ^ Favourite speed: 21.600 baud ^ Since: 16-Dec-1994 |\n`-----------------------------------------------------------------------------''\n\n                     This is bulletin 2 (BULL.2 tooltype).\n@ENDNODE\n\n@NODE BaudUsage "Example Output: Baud Usage (Bull.1) - © KiLLraVeN/MYSTiC"\n.-----------------------------------------------------------------------------.\n| KiLLER BAUD v1.1  ^  <> Baud Rate Statistical View <>  ^  KiLLraVeN/MYSTiC! |\n`-----------------------------------------------------------------------------''\n.----------------.----------------------.-------.-------.---------------------.\n| Connect String | 0%--------------100% | Total | Perc% | Overall             |\n:----------------:----------------------:-------:-------:---------------------:\n|   9.600 baud   | ####                 |    52 |    5% | Doing fine          |\n|  12.000 baud   | ######               |    86 |    9% | Popular rate        |\n|  14.400 baud   | #########            |   120 |   13% | Steady size.        |\n|  16.800 baud   | ############         |   154 |   17% | Substantial         |\n|  19.200 baud   | #                    |    17 |    1% | Among others        |\n|  21.600 baud   | #####                |    66 |    7% | Steady basis        |\n|  24.000 baud   | ####                 |    59 |    6% | Steady basis        |\n|  26.400 baud   | #################### |   255 |   29% | THE baud rate!      |\n|  28.800 baud   | ##                   |    34 |    3% | Doing fine          |\n:----------------^----------------------^-------^-------^---------------------:\n| Total Connects :    867 ^ Favourite speed: 26.400 baud ^ Since: 16-Dec-1994 |\n`-----------------------------------------------------------------------------''\n\n   The  graphical percentages shown are a RELATIVE comparison between the\n   most used baud rates and the rest.\n\n   Both  the  `Slower''  and  `Faster'' baudrate are ONLY shown when it has\n   been actually used by someone.\n\n                   (And yes, this output is a fraud :) )\n@ENDNODE\n\n@NODE History "History of KiLLER Baud - © 1994 KiLLraVeN/MYSTiC"\n                          .--------------------------.\n                          |  History of KiLLER Baud  |\n                          `--------------------------''\n\n   \n   1.3.0    05-Jan-95   Improved    Put the code to update the data file\n                                    into the main KiLLER_Baud program to\n                                    save space. This saved about 14KB.\n\n   1.2.2    04-Jan-95   NEW         You can now have baud rates removed\n                                    from the bulletin with the tooltypes:\n                                    NO_<baudrate>.\n                                    *Cried for by Quartz/MST*\n\n   1.2.1    25-Dec-94   Improved    Added two more checks that prevent a\n                                    division by zero (guru #80000005).\n\n   1.2.0    21-Dec-94   Improved    The baud rates "Slower" and "Faster" are\n                                    now only shown when they are actually in\n                                    use. It''s a cosmetic change.\n                                    *Requested by Muad''Dib*\n\n   1.1.0    20-Dec-94   Improved    The graphical percentage bar is now made\n                                    relative to the most used baud rate for\n                                    better representation.\n\n   1.0.0    18-Dec-94   Release     Muad''Dib got the first version to test.\n\n   1.0.0    18-Dec-94   NEW         Created KiLLER Baud.\n\n                                    -*-\n\n                                    OBSOLETE! Put the code into the\n                                    main executable (saving about 14KB).\n\n   1.2.1    25-Dec-94   Improved    When the data file is first created,\n                                    all variables will be cleared now on\n                                    a more firm basis.\n\n   1.2.0    21-Dec-94   Improved    Made it work with the new structure and\n                                    revised it to 1.2.0 for compatibility\n                                    reasons.\n\n   1.0.1    18-Dec-94   Fixed       KiLLER Detect now detects the line speed\n                                    and not the speed between modem and\n                                    computer (sigh).\n                                    Reported by: Muad''Dib/DLT\n\n   1.0.0    16-Dec-94   NEW         Created KiLLER Detect.\n@ENDNODE\n\n@NODE Greetings "Aloha! - By KiLLraVeN/MYSTiC"\n                                .-------------.\n                                |  Greetings  |\n                                `-------------''\n\n   Muad''Dib/DLT/iFT     Let''s crash your machine! Moehaha! :)\n   \n   Quartz/MYSTiC        You cry baby! :)\n\n   Motive Power/MST     28k8 beats 26k4 bud... ;)\n   \n   I-GO/Perseus         To bad you weren''t at the O22VW\n   \n   Zed                  I hope to contact you soon!\n   \n   Jake/Prestige        One day I will come and leech, don''t worry :)\n   \n   Tycoon/MYSTiC        It was fun, but to all good things come an end\n\n   Shuyuki Tanaka       Try to contact me at my Internet address! Japan\n                        is very very very cool!\n\n                      ...and to all my other good friends!\n@ENDNODE\n\n@NODE KiLLERComment "KiLLER-WHAT? - © 1995 KiLLraVeN/MYSTiC"\n\n         «« THIS IS AN EXCERPT OUT OF THE GUIDE OF KILLER COMMENT ««\n\n                         .---------------------------.\n                         |  What is KiLLER Comment?  |\n                         `---------------------------''\n\n   KiLLER Comment is number 1001 in the row of a [C]omment doors.  But this\n   is not just *a* comment door, otherwise I wouldn''t have made it.  I have\n   some profound reasons.\n\n   Despite  the  fact  that  there  must be over a 1000 different [C]omment\n   doors,  there  is not one comment door that suits my needs.  I have seen\n   plenty of them but to me they all look ugly, have static interfaces, are\n   as flexible as a log of wood and generally suck :-).\n\n   With  this mind I''ve tried to make KiLLER Comment as smart and pretty as\n   I  can  and  I  feel I have succeeded.  I have never seen a comment door\n   that  works  as  simple  as  this  one  with  a fair amount of so-called\n   ''intelligence'' and comes with a nice GUI.\n\n   What  is  this  ''intelligence'' I speak about you say?  Well, all comment\n   doors  sofar  weren''t  able  to see that if I typed "c kill" I wanted to\n   comment to "KiLLraVeN/MYSTiC" nor where they able to see that if I typed\n   "c  amiga" I wanted to comment to the Amiga co-sysop.  KiLLER Comment is\n   able to detect this!\n\n   Another  thing  is  security.   Every  new  user  was  able to see which\n   cosysops  you  had,  but  by giving every cosysop a security level, they\n   will  not see their names/jobs.  And if there is only one (co)sysop they\n   are  allowed  to  see,  they  will  not  even  see it is done via KiLLER\n   Comment.\n\n   Also,  per user in the [C]omment list there is a check wether he/she has\n   got access to the conference that KiLLER [C]omment is called from, so it\n   is  impossible  to write a message to someone who doesn''t have access to\n   that conference.\n\n   What I personally also dislike are comment doors that only fill like 25%\n   of  your  screen.   Not  that  you  should put a lot of nonsense in your\n   comment  door,  no,  but  KiLLER  Comment puts an extra line between the\n   names  of  the  (co-)sysops  if  that''s possible with the user''s maximum\n   numbers  of  lines  he  can  handle  on his screen.  It''s these kinds of\n   things I miss in those 13-in-a-dozen [C]omment doors.  That''s why I made\n   KiLLER Comment.\n\n   And  oh, just like I first introduced cursor control in ConfScan, KiLLER\n   comment also uses cursor control for selecting a user you can write to.\n\n                             »» END OF EXCERPT ««\n\n   To get hold of this tool, simply @{"contact" link Contact} me.\n\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',41503,5,0,NULL,NULL,'mst_kb13','scan',1780048619);
INSERT INTO door_catalog VALUES('mst_kb14','MST-KB14.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MST-KB14.LHA','KiLLER_Baud','XIM','KiLLER_Baud',NULL,NULL,'MST','.-\_  \/  _/   __/______\/___/-------------. | /   \/   \______  \_  \/  \_   mYSTIC!   | :/     \____/   _____/___    / /X dIVISION .',replace('  __/\  __________ _ ___  /\__              \n.-\_  \/  _/   __/______\/___/-------------.\n| /   \/   \______  \_  \/  \_   mYSTIC!   |\n:/     \____/   _____/___    / /X dIVISION .\n/_______\-\_____/--sTZ--l___/--------------:\n| KiLLraVeN/MYSTiC BRiNGS: KiLLER-BAUD 1.4 |\n| *Creates bulls about users'' baud-rates!* :\n: MAJOR BUGFiX AND CORRECTED SUPPLiED iCON !\n| o Exclude baud-rates  o Nice lay-out     ¡\n: o Two pages of info!  o Future proof!    |\n`------------------------------------------''\n','\n',char(10)),'KiLLER_Baud.Guide',replace('@DATABASE "KiLLER-Comment.GUiDE"\n@REMARK	.-------------------------------------------------------.\n@REMARK  | This document should be read with AmigaGuide (OS 2.x) |\n@REMARK  | or MultiView (OS 3.x) or any other guide reader. Tnx. |\n@REMARK  `-------------------------------------------------------''\n@REMARK	$VER: KiLLER Baud 1.4.0\n@WIDTH 80\n@NODE MAIN "KiLLER Comment - MYSTiC 1994 - © 1994 KiLLraVeN/MYSTiC"\n                             Guide to KiLLER Baud\n                 for Ami-Express 3.38+ Bulletin Board Systems\n\n                             Program version: 1.4.0\n                Compilation Date/Time: Thu Feb  2 21:30:48 1995\n\n                         © 1994/1995 by @{"KiLLraVeN/MYSTiC" link Contact}\n\n                   ... another fine MYSTiC /X production ...\n\n      @{" First words... " link WhatIs}    What is KiLLER Baud\n      @{" Features       " link Features}    What can it do?\n      @{" Installation   " link Install}    How to install KiLLER Baud on your system\n      @{" Example 1      " link BaudUsage}    Example output of bulletin 1\n      @{" Example 2      " link LastBauds}    Example output on bulletin 2\n      @{" History        " link History}    History of KiLLER Baud\n      @{" Greetings      " link Greetings}    Big hellos and messages\n@ENDNODE\n\n@NODE Contact "How to contact KiLLraVeN/MYSTiC - © Me me me! :)"\n                            .--------------------.\n                            |  Contacting me...  |\n                            `--------------------''\n\n       For FAST response (preferred) please contact me on Internet:\n\n                               [email removed]\n\n                    ( [email removed] -- backup )\n\n                       - - -- --- ------- --- -- - -\n\n                 I can be reached on the following boards:\n\n                       - - -- --- ------- --- -- - -\n\n                The Undiscovered       +31-2294-1442 (USR 28k8)\n                                       +31-2294-4442 (USR 28k8)\n                                       +31-2294-tRY! (USR 28k8)\n\n                Last Outpost           +31-72-201182 (USR 28k8)\n                                       +31-72-157682 (USR 28k8)\n\n         I know, you have to call The Netherlands for it, but it''s\n            the only boards I call on a frequent basis, sorry.\n\n                       - - -- --- ------- --- -- - -\n\n        You can also find me on IRC once in a while on the channels\n                   #amigascne, #amiga, #rave and #megawatt\n@ENDNODE\n\n@NODE WhatIs "What is KiLLER Baud - © KiLLraVeN/MYSTiC"\n                        .------------------------.\n                        |  What is KiLLER Baud?  |\n                        `------------------------''\n\n   KiLLER  Baud is (another) statistical mumbo jumbo door.  It is able to\n   create  some  nice  statistics  about  the baud rate your users use to\n   logon your system.  It is styled in the same way as @{"KiLLER Comment" link KiLLERComment}, so\n   if  you  are familiar with that door, you will know that the output of\n   it will be fair enough :-)\n\n   I  made  this  door  as a simple diversion of some other projects I am\n   working  on.   This  door  was created in two days and I don''t feel it\n   should  be  released  to  the  public  because  it is too simple to be\n   released.   The  idea  is not my own, I saw another ''accumulative baud\n   report''  door  and  I  am  still  recovering from the output that door\n   creates.   I  don''t  know where some people get their inspiration from\n   but that output reminded me of kindergarten ;-)\n\n   And  because  of  the  nice  respons  I  got from some sysops about my\n   previous  releases,  I  thought  it  would  be  nice  to  make another\n   statistical  door,  sysops can''t get enough of BBS statistics.\n\n   Anyway,  I hope you like it and if you do, please give me a yell.\n\n                                                         @{"KiLLraVeN/MYSTiC" link Contact}\n@ENDNODE\n\n@NODE Features "Features of KiLLER Baud - © Me me me and nobody else! :)"\n                           .--------------------------.\n                           |  Features of KiLLER Baud |\n                           `--------------------------''\n\n   ­ Create two pages of statistical data in one bulletin\n     (With a ''Space to Resume'' between them ofcourse)\n\n   ­ Create two pages of statistical data divided over 2 bulletins\n     (So two separate files)\n     \n   ­ Create either one of the two possible bulletins.\n     (You can choose between @{"Baud Usage" link BaudUsage} and @{"Last Bauds" link LastBauds})\n\n   ­ Only show the output on screen, don''t create the bulletins.\n     (Two pages, not selectable).\n\n   Other program features are:\n\n   · Fast baud detecting, virtually no delay for users.\n   · Very small data file to create bulletins\n   · You can remove baud rates from the bulletin(s).\n@ENDNODE\n\n@NODE Install "How to Install KiLLER Baud - © KiLLraVeN/MYSTiC (that''s me)"\n                      .------------------------------.\n                      |  How to install KiLLER Baud  |\n                      `------------------------------''\n\n   You are free to call the programs whatever you want and you can locate\n   the  program  wherever  you want.  I hate programs that have hardcoded\n   paths in their source.\n\n   The KiLLER_Baud executable has got a double function:  update the data\n   file  and create the bulletin(s).  Depending on available tooltypes in\n   the command icon, KiLLER Baud will know what to do.\n\n   ­­ Baud Detection ­­\n\n   First  of  all,  make  sure  that  KiLLER_Baud is run at least once to\n   update the data file.  I suggest you install it as an MCI command in a\n   bulletin  that  is  shown  to  every  user  that logs in (or logs out,\n   whatever fits you best).\n\n   · Example ·\n\n   ~CC_KB-DETECT\n   \n   · End ·\n\n   To  have  KiLLER_Baud  only  update the data file, create an icon that\n   holds  the tooltype "DETECT_BAUD".  If this tooltype is present in the\n   icon with what KiLLER_Baud was started, the data file will be updated.\n   This data file will reside in the same directory as the program itself\n   and will  be called "KiLLER_Baud.Data" and is 484 bytes in size.  Note\n   that  the  bulletin(s)  will not be created!  An example icon has been\n   provided called "KB-DETECT.info".\n   \n   Important tooltypes for that command are:\n   \n   DETECT_BAUD             ­ This tooltype MUST be present if you want KB\n                             to update the data file.\n                             \n   LOCAL_NODE=<number>     ­ KiLLER_Baud  will  not add your local logins\n                             to its data file.  Normally,  the local node\n                             would be node 0, but certain boards that run\n                             /X-Fido  for example have their last node as\n                             their local node.  So with this tooltype you\n                             can specify which node is the local node.\n                             \n                             You  can  also specify a node which does not\n                             exist,  and  your local logins will be added\n                             to the data file.\n                             \n                             Default value is node 0.\n\n   ­­ Bulletin Creation ­­\n\n   Unless  you  want  to install KiLLER_Baud as a regular /X command that\n   can  be  started  from  the  main  prompt,  you  also  need to install\n   KiLLER_Baud  as  another  MCI command, but this time to have it create\n   the bulletin(s).\n\n   You  can  specify the name(s) of the bulletin(s) with tooltypes.  Here\n   are the important tooltypes for this command:\n\n   BULL=<filename>         ­ When specified, one bulletin will be created\n                             containing 2 pages of statistics,  separated\n                             by a "Space to Resume".\n\n   BULL.1=<filename>       ­ This  will  result in one bulletin that only\n                             contains the @{"Baud Usage" link BaudUsage} information.\n\n   BULL.2=<filename>       ­ This  induces KiLLER_Baud to create only the\n                             @{"Last Bauds" link LastBauds} bulletin and nothing more.\n\n   NOTE¹ : The `BULL'' tooltype overrides both BULL.1 and BULL.2 !!\n\n   NOTE² : If you ommit all of these tooltypes, KiLLER_Baud will show the\n           bulletins on screen and will not create any bulletin.\n           \n   If  you  wish,  you  can  have  certain  baud  rates  removed from the\n   bulletins.   Normally,  the  bulletin would contain baud rates ranging\n   from  SLOW  to FAST, whereas SLOW means all baud rates below 9600 baud\n   and  FAST all baudrates above the highest speed available. Please note\n   that both the SLOW and FAST baud rates will not be put in the bulletin\n   until they are actually used.\n\n   For  example,  there  is  a BBS somewhere in Finland that has no 12000\n   baud users.  As strange as it is, this was true.  But the bulletin did\n   contain  the  12000  baud  line.  It was much disliked by the sysop of\n   that  board.   It even got to a point where he get himself drunk, felt\n   bad (a la Michael Jackson) and called The Undiscovered BBS.\n\n   There  he  wrote me a message saying that he hated the 12000 baud line\n   and  that  it  should  be removed.  I made him clear that although his\n   board  did  not  have 12000 baud users, the Undiscovered has got them!\n   He felt like an ass and left crying.  I felt so bad about this, that I\n   made it possible to leave out any baudrate you like.  However, this is\n   purely  COSMETIC.  The 12000 connects are still being counted and they\n   are  also used for the total number of connects.  But it was the least\n   I could do for such a lonely guy (snif).\n\n   So  without telling you the name of the sysop (QUARTZ QUARTZ QUARTZ!),\n   this is how to disable baudrates:\n\n   NO_SLOW     - Disable  SLOW baudrate\n   NO_9600     - Disable  9600 baudrate\n   NO_12000    - Disable 12000 baudrate (see! :) )\n   NO_14400    - Disable 14400 baudrate\n   ...\n   NO_FAST     - Disable FAST baudrate\n   \n   These  tooltypes  can be put in the K-Baud tooltype and remember, they\n   are  purely  cosmetic,  if  you  disable all baudrates and look at the\n   bulletin,  there  will  be NO baudrates mentioned, but there will be a\n   total number of connects and a favourite baudrate.\n\n   ­­ Regular /X Command ­­\n\n   If  you want it to install like a regular command, install it like any\n   other  command but make sure you remove the BULL#?  tooltypes from the\n   icon or it will create bulletins instead of showing them.\n\n   ­­ Overview ­­\n\n   ONCE AGAIN (but in short):\n   \n      · K-Baud can either create bulletins or display them pronto\n      · To make it create bulletins, either put the BULL tooltype\n        or BULL.x tooltypes in the icon (NOT BOTH!).\n      · To disable baudrates use tooltype: NO_<baudrate>\n      · If  you  remove all BULL* tooltypes from the K-Baud icon,\n        K-Baud will show the results on screen right away.\n\n   ­­ Reset the counting ­­\n\n   If  you  want  to reset the counting, simply remove the data file.  It\n   will  detect itself that the file is gone and create a new one (with a\n   new starting date).\n@ENDNODE\n\n@NODE LastBauds "Example Output: Last Baud (Bull.2) - © KiLLraVeN/MYSTiC"\n.-----------------------------------------------------------------------------.\n| KiLLER BAUD v1.4  ^  <> Baud Rate Statistical View <>  ^  KiLLraVeN/MYSTiC! |\n`-----------------------------------------------------------------------------''\n.----------------.--------------------------.---------------------------------.\n| Connect String | Date/Time last Connect   | Last Connect made by            |\n:----------------:--------------------------:---------------------------------:\n|   9.600 baud   | Fri Dec 16 12:14:45 1994 | ArCaDe/MYSTiC                   |\n|  12.000 baud   | Never                    | Nobody                          |\n|  14.400 baud   | Sun Dec 18 19:35:31 1994 | Kerstman                        |\n|  16.800 baud   | Sat Dec 17 09:03:12 1994 | Sal-One                         |\n|  19.200 baud   | Sun Dec 18 15:39:33 1994 | Incognito/MST                   |\n|  21.600 baud   | Sun Dec 18 11:32:50 1994 | WiSHBRiNGER                     |\n|  24.000 baud   | Fri Dec 16 23:11:22 1994 | skate BOB                       |\n|  26.400 baud   | Sun Dec 18 19:59:58 1994 | Motive Power/MST                |\n|  28.800 baud   | Sun Dec 18 02:13:26 1994 | KiLLraVeN/MYSTiC                |\n:----------------^--------------------------^---------------------------------:\n| Total Connects :  64041 ^ Favourite speed: 21.600 baud ^ Since: 16-Dec-1994 |\n`-----------------------------------------------------------------------------''\n\n                     This is bulletin 2 (BULL.2 tooltype).\n@ENDNODE\n\n@NODE BaudUsage "Example Output: Baud Usage (Bull.1) - © KiLLraVeN/MYSTiC"\n.-----------------------------------------------------------------------------.\n| KiLLER BAUD v1.4  ^  <> Baud Rate Statistical View <>  ^  KiLLraVeN/MYSTiC! |\n`-----------------------------------------------------------------------------''\n.----------------.----------------------.-------.-------.---------------------.\n| Connect String | 0%--------------100% | Total | Perc% | Overall             |\n:----------------:----------------------:-------:-------:---------------------:\n|   9.600 baud   | ####                 |    52 |    5% | Doing fine          |\n|  12.000 baud   | ######               |    86 |    9% | Popular rate        |\n|  14.400 baud   | #########            |   120 |   13% | Steady size.        |\n|  16.800 baud   | ############         |   154 |   17% | Substantial         |\n|  19.200 baud   | #                    |    17 |    1% | Among others        |\n|  21.600 baud   | #####                |    66 |    7% | Steady basis        |\n|  24.000 baud   | ####                 |    59 |    6% | Steady basis        |\n|  26.400 baud   | #################### |   255 |   29% | THE baud rate!      |\n|  28.800 baud   | ##                   |    34 |    3% | Doing fine          |\n:----------------^----------------------^-------^-------^---------------------:\n| Total Connects :    867 ^ Favourite speed: 26.400 baud ^ Since: 16-Dec-1994 |\n`-----------------------------------------------------------------------------''\n\n   The  graphical percentages shown are a RELATIVE comparison between the\n   most used baud rates and the rest.\n\n   Both  the  `Slower''  and  `Faster'' baudrate are ONLY shown when it has\n   been actually used by someone.\n\n                   (And yes, this output is a fraud :) )\n@ENDNODE\n\n@NODE History "History of KiLLER Baud - © 1994 KiLLraVeN/MYSTiC"\n                          .--------------------------.\n                          |  History of KiLLER Baud  |\n                          `--------------------------''\n\n   \n   1.4.0    02-Feb-95   Fixed       After spending two hours with on the\n                                    with Muad''Dib, we finally discovered\n                                    that I forgot to put the tooltype\n                                    TYPE=XIM in the icon that I delivered\n                                    in the package. This caused quite\n                                    some problems on some boards, but not\n                                    on mine ;) But we found it, and I\n                                    fixed it so it works again.\n                                    *Reported by Muad''Dib*\n\n   1.3.1    02-Feb-95   Fixed       I misplaced the code from the KiLLER\n                                    detect program causing two errors ;(\n                                    This has been fixed, sorry dudes.\n                                    *Detected by NightShade & Motive Power*\n\n   1.3.0    05-Jan-95   Improved    Put the code to update the data file\n                                    into the main KiLLER_Baud program to\n                                    save space. This saved about 14KB.\n\n   1.2.2    04-Jan-95   NEW         You can now have baud rates removed\n                                    from the bulletin with the tooltypes:\n                                    NO_<baudrate>.\n                                    *Cried for by Quartz/MST*\n\n   1.2.1    25-Dec-94   Improved    Added two more checks that prevent a\n                                    division by zero (guru #80000005).\n\n   1.2.0    21-Dec-94   Improved    The baud rates "Slower" and "Faster" are\n                                    now only shown when they are actually in\n                                    use. It''s a cosmetic change.\n                                    *Requested by Muad''Dib*\n\n   1.1.0    20-Dec-94   Improved    The graphical percentage bar is now made\n                                    relative to the most used baud rate for\n                                    better representation.\n\n   1.0.0    18-Dec-94   Release     Muad''Dib got the first version to test.\n\n   1.0.0    18-Dec-94   NEW         Created KiLLER Baud.\n\n                                    -*-\n\n                                    OBSOLETE! Put the code into the\n                                    main executable (saving about 14KB).\n\n   1.2.1    25-Dec-94   Improved    When the data file is first created,\n                                    all variables will be cleared now on\n                                    a more firm basis.\n\n   1.2.0    21-Dec-94   Improved    Made it work with the new structure and\n                                    revised it to 1.2.0 for compatibility\n                                    reasons.\n\n   1.0.1    18-Dec-94   Fixed       KiLLER Detect now detects the line speed\n                                    and not the speed between modem and\n                                    computer (sigh).\n                                    Reported by: Muad''Dib/DLT\n\n   1.0.0    16-Dec-94   NEW         Created KiLLER Detect.\n@ENDNODE\n\n@NODE Greetings "Aloha! - By KiLLraVeN/MYSTiC"\n                                .-------------.\n                                |  Greetings  |\n                                `-------------''\n\n   Muad''Dib/DLT/iFT     Let''s crash your machine! Moehaha! :)\n   \n   Quartz/MYSTiC        You cry baby! :)\n\n   Motive Power/MST     28k8 beats 26k4 bud... ;)\n   \n   I-GO/Perseus         To bad you weren''t at the O22VW\n   \n   Zed                  I hope to contact you soon!\n   \n   Jake/Prestige        One day I will come and leech, don''t worry :)\n   \n   Tycoon/MYSTiC        It was fun, but to all good things come an end\n\n   Shuyuki Tanaka       Try to contact me at my Internet address! Japan\n                        is very very very cool!\n\n                      ...and to all my other good friends!\n@ENDNODE\n\n@NODE KiLLERComment "KiLLER-WHAT? - © 1995 KiLLraVeN/MYSTiC"\n\n         «« THIS IS AN EXCERPT OUT OF THE GUIDE OF KILLER COMMENT ««\n\n                         .---------------------------.\n                         |  What is KiLLER Comment?  |\n                         `---------------------------''\n\n   KiLLER Comment is number 1001 in the row of a [C]omment doors.  But this\n   is not just *a* comment door, otherwise I wouldn''t have made it.  I have\n   some profound reasons.\n\n   Despite  the  fact  that  there  must be over a 1000 different [C]omment\n   doors,  there  is not one comment door that suits my needs.  I have seen\n   plenty of them but to me they all look ugly, have static interfaces, are\n   as flexible as a log of wood and generally suck :-).\n\n   With  this mind I''ve tried to make KiLLER Comment as smart and pretty as\n   I  can  and  I  feel I have succeeded.  I have never seen a comment door\n   that  works  as  simple  as  this  one  with  a fair amount of so-called\n   ''intelligence'' and comes with a nice GUI.\n\n   What  is  this  ''intelligence'' I speak about you say?  Well, all comment\n   doors  sofar  weren''t  able  to see that if I typed "c kill" I wanted to\n   comment to "KiLLraVeN/MYSTiC" nor where they able to see that if I typed\n   "c  amiga" I wanted to comment to the Amiga co-sysop.  KiLLER Comment is\n   able to detect this!\n\n   Another  thing  is  security.   Every  new  user  was  able to see which\n   cosysops  you  had,  but  by giving every cosysop a security level, they\n   will  not see their names/jobs.  And if there is only one (co)sysop they\n   are  allowed  to  see,  they  will  not  even  see it is done via KiLLER\n   Comment.\n\n   Also,  per user in the [C]omment list there is a check wether he/she has\n   got access to the conference that KiLLER [C]omment is called from, so it\n   is  impossible  to write a message to someone who doesn''t have access to\n   that conference.\n\n   What I personally also dislike are comment doors that only fill like 25%\n   of  your  screen.   Not  that  you  should put a lot of nonsense in your\n   comment  door,  no,  but  KiLLER  Comment puts an extra line between the\n   names  of  the  (co-)sysops  if  that''s possible with the user''s maximum\n   numbers  of  lines  he  can  handle  on his screen.  It''s these kinds of\n   things I miss in those 13-in-a-dozen [C]omment doors.  That''s why I made\n   KiLLER Comment.\n\n   And  oh, just like I first introduced cursor control in ConfScan, KiLLER\n   comment also uses cursor control for selecting a user you can write to.\n\n                             »» END OF EXCERPT ««\n\n   To get hold of this tool, simply @{"contact" link Contact} me.\n\n@ENDNODE\n','\n',char(10)),'{"TYPE":"XIM"}','auto-added',41952,11,0,NULL,NULL,'mst_kb14','scan',1780048619);
INSERT INTO door_catalog VALUES('mst_kb15','MST-KB15.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MST-KB15.LHA','KiLLER_Baud','XIM','KiLLER_Baud',NULL,NULL,'MST','.-\_  \/  _/   __/______\/___/-------------. | /   \/   \______  \_  \/  \_   mYSTIC!   | :/     \____/   _____/___    / /X dIVISION .',replace('  __/\  __________ _ ___  /\__              \n.-\_  \/  _/   __/______\/___/-------------.\n| /   \/   \______  \_  \/  \_   mYSTIC!   |\n:/     \____/   _____/___    / /X dIVISION .\n/_______\-\_____/--sTZ--l___/--------------:\n| KiLLraVeN/MYSTiC BRiNGS: KiLLER-BAUD 1.5 |\n| *Creates bulls about users'' baud-rates!* :\n+------------------------------------------+\n|   NOW RECOGNIZES 31.200 & 33.600 BAUD!   ¡\n`------------------------------------------''\n','\n',char(10)),'KiLLER_Baud.Guide',replace('@DATABASE "KiLLER-Comment.GUiDE"\n@REMARK	.-------------------------------------------------------.\n@REMARK  | This document should be read with AmigaGuide (OS 2.x) |\n@REMARK  | or MultiView (OS 3.x) or any other guide reader. Tnx. |\n@REMARK  `-------------------------------------------------------''\n@REMARK	$VER: KiLLER Baud 1.5.0\n@WIDTH 80\n@NODE MAIN "KiLLER Comment - MYSTiC 1994 - © 1994 KiLLraVeN/MYSTiC"\n                             Guide to KiLLER Baud\n                 for Ami-Express 3.38+ Bulletin Board Systems\n\n                             Program version: 1.5.0\n                Compilation Date/Time: Thu Jun  1 15:45:51 1995\n\n                         © 1994/1995 by @{"KiLLraVeN/MYSTiC" link Contact}\n\n                   ... another fine MYSTiC /X production ...\n\n                        @{"     UPDATE INFORMATION     " link Update}\n\n      @{" First words... " link WhatIs}    What is KiLLER Baud\n      @{" Features       " link Features}    What can it do?\n      @{" Installation   " link Install}    How to install KiLLER Baud on your system\n      @{" Example 1      " link BaudUsage}    Example output of bulletin 1\n      @{" Example 2      " link LastBauds}    Example output on bulletin 2\n      @{" History        " link History}    History of KiLLER Baud\n      @{" Greetings      " link Greetings}    Big hellos and messages\n@ENDNODE\n\n@NODE Contact "How to contact KiLLraVeN/MYSTiC - © Me me me! :)"\n                            .--------------------.\n                            |  Contacting me...  |\n                            `--------------------''\n\n       For FAST response (preferred) please contact me on Internet:\n\n                               [email removed]\n\n                    ( [email removed] -- backup )\n\n                       - - -- --- ------- --- -- - -\n\n                 I can be reached on the following boards:\n\n                       - - -- --- ------- --- -- - -\n\n                The Undiscovered       +31-2294-1442 (USR 28k8)\n                                       +31-2294-4442 (USR 28k8)\n                                       +31-2294-tRY! (USR 28k8)\n\n                Last Outpost           +31-72-201182 (USR 28k8)\n                                       +31-72-157682 (USR 28k8)\n\n         I know, you have to call The Netherlands for it, but it''s\n            the only boards I call on a frequent basis, sorry.\n\n                       - - -- --- ------- --- -- - -\n\n        You can also find me on IRC once in a while on the channels\n                            #amigascne and #rave\n@ENDNODE\n\n@NODE WhatIs "What is KiLLER Baud - © KiLLraVeN/MYSTiC"\n                        .------------------------.\n                        |  What is KiLLER Baud?  |\n                        `------------------------''\n\n   KiLLER  Baud is (another) statistical mumbo jumbo door.  It is able to\n   create  some  nice  statistics  about  the baud rate your users use to\n   logon your system.  It is styled in the same way as @{"KiLLER Comment" link KiLLERComment}, so\n   if  you  are familiar with that door, you will know that the output of\n   it will be fair enough :-)\n\n   I  made  this  door  as a simple diversion of some other projects I am\n   working  on.   This  door  was created in two days and I don''t feel it\n   should  be  released  to  the  public  because  it is too simple to be\n   released.   The  idea  is not my own, I saw another ''accumulative baud\n   report''  door  and  I  am  still  recovering from the output that door\n   creates.   I  don''t  know where some people get their inspiration from\n   but that output reminded me of kindergarten ;-)\n\n   And  because  of  the  nice  respons  I  got from some sysops about my\n   previous  releases,  I  thought  it  would  be  nice  to  make another\n   statistical  door,  sysops can''t get enough of BBS statistics.\n\n   Anyway,  I hope you like it and if you do, please give me a yell.\n\n                                                         @{"KiLLraVeN/MYSTiC" link Contact}\n@ENDNODE\n\n@NODE Features "Features of KiLLER Baud - © Me me me and nobody else! :)"\n                           .--------------------------.\n                           |  Features of KiLLER Baud |\n                           `--------------------------''\n\n   ­ Create two pages of statistical data in one bulletin\n     (With a ''Space to Resume'' between them ofcourse)\n\n   ­ Create two pages of statistical data divided over 2 bulletins\n     (So two separate files)\n     \n   ­ Create either one of the two possible bulletins.\n     (You can choose between @{"Baud Usage" link BaudUsage} and @{"Last Bauds" link LastBauds})\n\n   ­ Only show the output on screen, don''t create the bulletins.\n     (Two pages, not selectable).\n\n   Other program features are:\n\n   · Fast baud detecting, virtually no delay for users.\n   · Very small data file to create bulletins\n   · You can remove baud rates from the bulletin(s).\n@ENDNODE\n\n@NODE Install "How to Install KiLLER Baud - © KiLLraVeN/MYSTiC (that''s me)"\n                      .------------------------------.\n                      |  How to install KiLLER Baud  |\n                      `------------------------------''\n\n   You are free to call the programs whatever you want and you can locate\n   the  program  wherever  you want.  I hate programs that have hardcoded\n   paths in their source.\n\n   The KiLLER_Baud executable has got a double function:  update the data\n   file  and create the bulletin(s).  Depending on available tooltypes in\n   the command icon, KiLLER Baud will know what to do.\n\n   ­­ Baud Detection ­­\n\n   First  of  all,  make  sure  that  KiLLER_Baud is run at least once to\n   update the data file.  I suggest you install it as an MCI command in a\n   bulletin  that  is  shown  to  every  user  that logs in (or logs out,\n   whatever fits you best).\n\n   · Example ·\n\n   ~CC_KB-DETECT\n   \n   · End ·\n\n   To  have  KiLLER_Baud  only  update the data file, create an icon that\n   holds  the tooltype "DETECT_BAUD".  If this tooltype is present in the\n   icon with what KiLLER_Baud was started, the data file will be updated.\n   This data file will reside in the same directory as the program itself\n   and will  be called "KiLLER_Baud.Data" and is 484 bytes in size.  Note\n   that  the  bulletin(s)  will not be created!  An example icon has been\n   provided called "KB-DETECT.info".\n   \n   Important tooltypes for that command are:\n   \n   DETECT_BAUD             ­ This tooltype MUST be present if you want KB\n                             to update the data file.\n                             \n   LOCAL_NODE=<number>     ­ KiLLER_Baud  will  not add your local logins\n                             to its data file.  Normally,  the local node\n                             would be node 0, but certain boards that run\n                             /X-Fido  for example have their last node as\n                             their local node.  So with this tooltype you\n                             can specify which node is the local node.\n                             \n                             You  can  also specify a node which does not\n                             exist,  and  your local logins will be added\n                             to the data file.\n                             \n                             Default value is node 0.\n\n   ­­ Bulletin Creation ­­\n\n   Unless  you  want  to install KiLLER_Baud as a regular /X command that\n   can  be  started  from  the  main  prompt,  you  also  need to install\n   KiLLER_Baud  as  another  MCI command, but this time to have it create\n   the bulletin(s).\n\n   You  can  specify the name(s) of the bulletin(s) with tooltypes.  Here\n   are the important tooltypes for this command:\n\n   BULL=<filename>         ­ When specified, one bulletin will be created\n                             containing 2 pages of statistics,  separated\n                             by a "Space to Resume".\n\n   BULL.1=<filename>       ­ This  will  result in one bulletin that only\n                             contains the @{"Baud Usage" link BaudUsage} information.\n\n   BULL.2=<filename>       ­ This  induces KiLLER_Baud to create only the\n                             @{"Last Bauds" link LastBauds} bulletin and nothing more.\n\n   NOTE¹ : The `BULL'' tooltype overrides both BULL.1 and BULL.2 !!\n\n   NOTE² : If you ommit all of these tooltypes, KiLLER_Baud will show the\n           bulletins on screen and will not create any bulletin.\n           \n   If  you  wish,  you  can  have  certain  baud  rates  removed from the\n   bulletins.   Normally,  the  bulletin would contain baud rates ranging\n   from  SLOW  to FAST, whereas SLOW means all baud rates below 9600 baud\n   and  FAST all baudrates above the highest speed available. Please note\n   that both the SLOW and FAST baud rates will not be put in the bulletin\n   until they are actually used.\n\n   For  example,  there  is  a BBS somewhere in Finland that has no 12000\n   baud users.  As strange as it is, this was true.  But the bulletin did\n   contain  the  12000  baud  line.  It was much disliked by the sysop of\n   that  board.   It even got to a point where he get himself drunk, felt\n   bad (a la Michael Jackson) and called The Undiscovered BBS.\n\n   There  he  wrote me a message saying that he hated the 12000 baud line\n   and  that  it  should  be removed.  I made him clear that although his\n   board  did  not  have 12000 baud users, the Undiscovered has got them!\n   He felt like an ass and left crying.  I felt so bad about this, that I\n   made it possible to leave out any baudrate you like.  However, this is\n   purely  COSMETIC.  The 12000 connects are still being counted and they\n   are  also used for the total number of connects.  But it was the least\n   I could do for such a lonely guy (snif).\n\n   So  without telling you the name of the sysop (QUARTZ QUARTZ QUARTZ!),\n   this is how to disable baudrates:\n\n   NO_SLOW     - Disable  SLOW baudrate\n   NO_9600     - Disable  9600 baudrate\n   NO_12000    - Disable 12000 baudrate (see! :) )\n   NO_14400    - Disable 14400 baudrate\n   ...\n   NO_FAST     - Disable FAST baudrate\n   \n   These  tooltypes  can be put in the K-Baud tooltype and remember, they\n   are  purely  cosmetic,  if  you  disable all baudrates and look at the\n   bulletin,  there  will  be NO baudrates mentioned, but there will be a\n   total number of connects and a favourite baudrate.\n\n   ­­ Regular /X Command ­­\n\n   If  you want it to install like a regular command, install it like any\n   other  command but make sure you remove the BULL#?  tooltypes from the\n   icon or it will create bulletins instead of showing them.\n\n   ­­ Overview ­­\n\n   ONCE AGAIN (but in short):\n   \n      · K-Baud can either create bulletins or display them pronto\n      · To make it create bulletins, either put the BULL tooltype\n        or BULL.x tooltypes in the icon (NOT BOTH!).\n      · To disable baudrates use tooltype: NO_<baudrate>\n      · If  you  remove all BULL* tooltypes from the K-Baud icon,\n        K-Baud will show the results on screen right away.\n\n   ­­ Reset the counting ­­\n\n   If  you  want  to reset the counting, simply remove the data file.  It\n   will  detect itself that the file is gone and create a new one (with a\n   new starting date).\n@ENDNODE\n\n@NODE LastBauds "Example Output: Last Baud (Bull.2) - © KiLLraVeN/MYSTiC"\n.-----------------------------------------------------------------------------.\n| KiLLER BAUD v1.5  ^  <> Baud Rate Statistical View <>  ^  KiLLraVeN/MYSTiC! |\n`-----------------------------------------------------------------------------''\n.----------------.--------------------------.---------------------------------.\n| Connect String | Date/Time last Connect   | Last Connect made by            |\n:----------------:--------------------------:---------------------------------:\n|  Slower baud   | Sat May 27 10:56:37 1995 | celtic                          |\n|   9.600 baud   | Thu Jun 01 21:49:11 1995 | Alf                             |\n|  12.000 baud   | Thu Jun 01 17:51:58 1995 | wHIRLWIND                       |\n|  14.400 baud   | Thu Jun 01 18:00:15 1995 | yhatware                        |\n|  16.800 baud   | Thu Jun 01 16:45:12 1995 | UFOk                            |\n|  19.200 baud   | Thu Jun 01 20:46:07 1995 | D`sTyLE                         |\n|  21.600 baud   | Fri Jun 02 16:02:02 1995 | KiLLraVeN/MYSTiC!               |\n|  24.000 baud   | Thu Jun 01 01:32:36 1995 | I-GO                            |\n|  26.400 baud   | Thu Jun 01 21:26:36 1995 | Arlette                         |\n|  28.800 baud   | Thu Jun 01 17:39:38 1995 | [MEGA^FORTRESS]                 |\n|  31.200 baud   | Thu Jun 01 17:56:02 1995 | KiLLraVeN/MYSTiC                |\n|  33.600 baud   | Fri Jun  2 16:03:29 1995 | KiLLraVeN/MYSTiC                |\n|  Faster baud   | Thu Jun 01 18:00:36 1995 | KiLLraVeN/MYSTiC                |\n:----------------^--------------------------^---------------------------------:\n| Total Connects :  14352 ^ Favourite speed: 14.400 baud ^ Since: 25-Dec-1994 |\n`-----------------------------------------------------------------------------''\n\n                     This is bulletin 2 (BULL.2 tooltype).\n@ENDNODE\n\n@NODE BaudUsage "Example Output: Baud Usage (Bull.1) - © KiLLraVeN/MYSTiC"\n.-----------------------------------------------------------------------------.\n| KiLLER BAUD v1.5  ^  <> Baud Rate Statistical View <>  ^  KiLLraVeN/MYSTiC! |\n`-----------------------------------------------------------------------------''\n.----------------.----------------------.-------.-------.---------------------.\n| Connect String | 0%--------------100% | Total | Perc% | Overall             |\n:----------------:----------------------:-------:-------:---------------------:\n|  Slower baud   |                      |    75 |    0% | Private             |\n|   9.600 baud   |                      |   127 |    0% | Private             |\n|  12.000 baud   |                      |    50 |    0% | Hardly used         |\n|  14.400 baud   | #################### |  5724 |   39% | The Ruler!          |\n|  16.800 baud   | ###                  |   869 |    6% | Used by few         |\n|  19.200 baud   | ##                   |   728 |    5% | Used by few         |\n|  21.600 baud   | ####                 |  1424 |    9% | Not too bad         |\n|  24.000 baud   | ##                   |   656 |    4% | Used by few         |\n|  26.400 baud   | ######               |  1975 |   13% | Popular rate        |\n|  28.800 baud   | #########            |  2704 |   18% | Much liked          |\n|  31.200 baud   |                      |     2 |    0% | Hardly used         |\n|  33.600 baud   |                      |     5 |    0% | Hardly used         |\n|  Faster baud   |                      |    13 |    0% | Hardly used         |\n:----------------^----------------------^-------^-------^---------------------:\n| Total Connects :  14352 ^ Favourite speed: 14.400 baud ^ Since: 25-Dec-1994 |\n`-----------------------------------------------------------------------------''\n\n   The  graphical percentages shown are a RELATIVE comparison between the\n   most used baud rates and the rest.\n\n   Both  the  `Slower''  and  `Faster'' baudrate are ONLY shown when it has\n   been actually used by someone.\n\n                   (And yes, this output is a fraud :) )\n@ENDNODE\n\n@NODE History "History of KiLLER Baud - © 1994 KiLLraVeN/MYSTiC"\n                      -//- History of KiLLER Baud -//-\n   \n   1.5.0    01-Jun-95   Improved    33.600 baud is recognized.\n\n            01-Jun-95   Improved    Changed the texts in KiLLER Baud.\n\n   1.4.0    02-Feb-95   Fixed       After spending two hours with on the\n                                    with Muad''Dib, we finally discovered\n                                    that I forgot to put the tooltype\n                                    TYPE=XIM in the icon that I delivered\n                                    in the package. This caused quite\n                                    some problems on some boards, but not\n                                    on mine ;) But we found it, and I\n                                    fixed it so it works again.\n                                    *Reported by Muad''Dib*\n\n   1.3.1    02-Feb-95   Fixed       I misplaced the code from the KiLLER\n                                    detect program causing two errors ;(\n                                    This has been fixed, sorry dudes.\n                                    *Detected by NightShade & Motive Power*\n\n   1.3.0    05-Jan-95   Improved    Put the code to update the data file\n                                    into the main KiLLER_Baud program to\n                                    save space. This saved about 14KB.\n\n   1.2.2    04-Jan-95   NEW         You can now have baud rates removed\n                                    from the bulletin with the tooltypes:\n                                    NO_<baudrate>.\n                                    *Cried for by Quartz/MST*\n\n   1.2.1    25-Dec-94   Improved    Added two more checks that prevent a\n                                    division by zero (guru #80000005).\n\n   1.2.0    21-Dec-94   Improved    The baud rates "Slower" and "Faster" are\n                                    now only shown when they are actually in\n                                    use. It''s a cosmetic change.\n                                    *Requested by Muad''Dib*\n\n   1.1.0    20-Dec-94   Improved    The graphical percentage bar is now made\n                                    relative to the most used baud rate for\n                                    better representation.\n\n   1.0.0    18-Dec-94   Release     Muad''Dib got the first version to test.\n\n   1.0.0    18-Dec-94   NEW         Created KiLLER Baud.\n\n                                    -*-\n\n                                    OBSOLETE! Put the code into the\n                                    main executable (saving about 14KB).\n\n   1.2.1    25-Dec-94   Improved    When the data file is first created,\n                                    all variables will be cleared now on\n                                    a more firm basis.\n\n   1.2.0    21-Dec-94   Improved    Made it work with the new structure and\n                                    revised it to 1.2.0 for compatibility\n                                    reasons.\n\n   1.0.1    18-Dec-94   Fixed       KiLLER Detect now detects the line speed\n                                    and not the speed between modem and\n                                    computer (sigh).\n                                    Reported by: Muad''Dib/DLT\n\n   1.0.0    16-Dec-94   NEW         Created KiLLER Detect.\n@ENDNODE\n\n@NODE Greetings "Aloha! - By KiLLraVeN/MYSTiC"\n                                .-------------.\n                                |  Greetings  |\n                                `-------------''\n\n   Muad''Dib/MST/DLT     USR sure as hell rulez!\n\n   UFOk/MST^LSD^PSG     Trying to break the world-record? ;)\n\n   QuartZ/MYSTiC        Let''s get it going! Intro''s!\n\n   Motive Power/MST     33k6 beats 26k4 bud... ;)\n   \n   I-GO^MDMA            0.25 is not enough for energy.\n   \n   Zed                  I hope to contact you soon!\n   \n                      ...and to all my other good friends!\n@ENDNODE\n\n@NODE KiLLERComment "KiLLER-WHAT? - © 1995 KiLLraVeN/MYSTiC"\n         «« THIS IS AN EXCERPT OUT OF THE GUIDE OF KILLER COMMENT ««\n\n                     -//- What is KiLLER Comment? -//-\n\n   KiLLER Comment is number 1001 in the row of a [C]omment doors.  But this\n   is not just *a* comment door, otherwise I wouldn''t have made it.  I have\n   some profound reasons.\n\n   Despite  the  fact  that  there  must be over a 1000 different [C]omment\n   doors,  there  is not one comment door that suits my needs.  I have seen\n   plenty of them but to me they all look ugly, have static interfaces, are\n   as flexible as a log of wood and generally suck :-).\n\n   With  this mind I''ve tried to make KiLLER Comment as smart and pretty as\n   I  can  and  I  feel I have succeeded.  I have never seen a comment door\n   that  works  as  simple  as  this  one  with  a fair amount of so-called\n   ''intelligence'' and comes with a nice GUI.\n\n   What  is  this  ''intelligence'' I speak about you say?  Well, all comment\n   doors  sofar  weren''t  able  to see that if I typed "c kill" I wanted to\n   comment to "KiLLraVeN/MYSTiC" nor where they able to see that if I typed\n   "c  amiga" I wanted to comment to the Amiga co-sysop.  KiLLER Comment is\n   able to detect this!\n\n   Another  thing  is  security.   Every  new  user  was  able to see which\n   cosysops  you  had,  but  by giving every cosysop a security level, they\n   will  not see their names/jobs.  And if there is only one (co)sysop they\n   are  allowed  to  see,  they  will  not  even  see it is done via KiLLER\n   Comment.\n\n   Also,  per user in the [C]omment list there is a check wether he/she has\n   got access to the conference that KiLLER [C]omment is called from, so it\n   is  impossible  to write a message to someone who doesn''t have access to\n   that conference.\n\n   What I personally also dislike are comment doors that only fill like 25%\n   of  your  screen.   Not  that  you  should put a lot of nonsense in your\n   comment  door,  no,  but  KiLLER  Comment puts an extra line between the\n   names  of  the  (co-)sysops  if  that''s possible with the user''s maximum\n   numbers  of  lines  he  can  handle  on his screen.  It''s these kinds of\n   things I miss in those 13-in-a-dozen [C]omment doors.  That''s why I made\n   KiLLER Comment.\n\n   And  oh, just like I first introduced cursor control in ConfScan, KiLLER\n   comment also uses cursor control for selecting a user you can write to.\n\n                             »» END OF EXCERPT ««\n\n   To get hold of this tool, simply @{"contact" link Contact} me.\n\n@ENDNODE\n\n@NODE Update "Update Information - USR Rules Again!"\n                        -//-  Update Information -//-\n\n   Today  (June  1st,  1995)  US  Robotics  surprised  the  scene with an\n   unexpected  present:   USR modems with a flash rom can update to v.34+\n   allowing  speeds  upto  33.600  baud  instead of the 28.800 baud other\n   modems have as a maximum.  Since I own one myself I love it :)\n\n   This  ofcourse  asked  for  a quick update of KiLLER Baud, because you\n   want  those 33.600 connects showing in your bulletin!  I thought I had\n   outsmarted  USR  by  already  recognizing  31.200 baud in the previous\n   version,  but  I had not expected 33k6.  But I''m not complaining here,\n   hell no, I love 4000CPS on LHA files :)\n\n   So all this update does extra is recognize 33k6 connects.\n\n   Because  of  the  new data format involved, I''ve included a very small\n   util  to update your KiLLER_Baud.Data.  All you have to do is start it\n   in  the same directory as where your data file resides.  A backup file\n   will be created by it!\n\n   AFTER  YOU  HAVE  DONE THAT, you can start using the new version.  All\n   you  have  to  do  is copy the new executable over the old version and\n   you''re done.\n\n   That''s  all about this update, if you have any suggestions, questions,\n   bug-reports, feel free to @{"contact" link Contact} me.\n\n                                                      -KiLLraVeN/MYSTiC-\n@ENDNODE\n','\n',char(10)),'{"TYPE":"XIM"}','auto-added',40907,5,0,NULL,NULL,'mst_kb15','scan',1780048619);
INSERT INTO door_catalog VALUES('mst_kc11','MST-KC11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MST-KC11.LHA','KC-Config','XIM','KC-Config',NULL,NULL,'MST','.-\_  \/  _/   __/______\/___/-------------. | /   \/   \______  \_  \/  \_   mYSTIC!   | :/     \____/   _____/___    / /X dIVISION .',replace('  __/\  __________ _ ___  /\__              \n.-\_  \/  _/   __/______\/___/-------------.\n| /   \/   \______  \_  \/  \_   mYSTIC!   |\n:/     \____/   _____/___    / /X dIVISION .\n/_______\-\_____/--sTZ--l___/--------------:\n| KiLLraVeN/MYSTiC BRiNGS: KiLLER-COMMENT! |\n| *WiTHOUT A DOUBT THE BEST COMMENT DOOR!* :\n: o GUI Config program o Top Safe Security |\n| o Nice lay-out!      o Statistical info! :\n: o Intelligent user selection (see guide) |\n`------------------------------------------''\n','\n',char(10)),'KiLLER-Comment.Guide',replace('@DATABASE "KiLLER-Comment.GUiDE"\n@REMARK	.-------------------------------------------------------.\n@REMARK  | This document should be read with AmigaGuide (OS 2.x) |\n@REMARK  | or MultiView (OS 3.x) or any other guide reader. Tnx. |\n@REMARK  `-------------------------------------------------------''\n@REMARK	$VER: KiLLER Comment 1.1.0\n@WIDTH 80\n@NODE MAIN "KiLLER Comment - MYSTiC 1994 - © 1994 KiLLraVeN/MYSTiC"\n                            Guide to KiLLER Comment\n                     for Ami-Express Bulletin Board Systems\n\n                             Program version: 1.1.0\n                Compilation Date/Time: Mon Dec 26 01:10:53 1994\n\n                           © 1994 by @{"KiLLraVeN/MYSTiC" link Contact}\n\n                   ... another fine MYSTiC /X production ...\n\n      @{" First words... " link WhatIs}    What/Why is KiLLER Comment?\n      @{" Features       " link Features}    What can it do?\n      @{" Installation   " link Install}    How to install KiLLER Comment on your BBS\n      @{" Usage /X       " link AmiUsage}    How things go with Ami-Express\n      @{" Usage Config   " link Config}    How to use the Config GUI\n      @{" History        " link History}    History of KiLLER Comment\n      @{" History Config " link HistoryGUI}    History of KiLLER Config\n      @{" Greetings      " link Greetings}    Greetings, messages and contact info\n@ENDNODE\n\n@NODE WhatIs "What/Why is KiLLER Comment? - © 1994 KiLLraVeN/MYSTiC"\n                         .---------------------------.\n                         |  What is KiLLER Comment?  |\n                         `---------------------------''\n\n   KiLLER Comment is number 1001 in the row of a [C]omment doors.  But this\n   is not just *a* comment door, otherwise I wouldn''t have made it.  I have\n   some profound reasons.\n\n   Despite  the  fact  that  there  must be over a 1000 different [C]omment\n   doors,  there  is not one comment door that suits my needs.  I have seen\n   plenty of them but to me they all look ugly, have static interfaces, are\n   as flexible as a log of wood and generally suck :-).\n\n   With  this mind I''ve tried to make KiLLER Comment as smart and pretty as\n   I  can  and  I  feel I have succeeded.  I have never seen a comment door\n   that  works  as  simple  as  this  one  with  a fair amount of so-called\n   ''intelligence'' and comes with a nice GUI.\n\n   What  is  this  ''intelligence'' I speak about you say?  Well, all comment\n   doors  sofar  weren''t  able  to see that if I typed "c kill" I wanted to\n   comment to "KiLLraVeN/MYSTiC" nor where they able to see that if I typed\n   "c  amiga" I wanted to comment to the Amiga co-sysop.  KiLLER Comment is\n   able to detect this!\n\n   Another  thing  is  security.   Every  new  user  was  able to see which\n   cosysops  you  had,  but  by giving every cosysop a security level, they\n   will  not see their names/jobs.  And if there is only one (co)sysop they\n   are  allowed  to  see,  they  will  not  even  see it is done via KiLLER\n   Comment.\n\n   Also,  per user in the [C]omment list there is a check wether he/she has\n   got access to the conference that KiLLER [C]omment is called from, so it\n   is impossible to write a person to someone in the wrong conference.\n\n   What I personally also dislike are comment doors that only fill like 25%\n   of  your  screen.   Not  that  you  should put a lot of nonsense in your\n   comment  door,  no,  but  KiLLER  Comment puts an extra line between the\n   names  of  the  (co-)sysops  if  that''s possible with the user''s maximum\n   numbers  of  lines  he  can  handle  on his screen.  It''s these kinds of\n   things I miss in those 13-in-a-dozen [C]omment doors.  That''s why I made\n   KiLLER Comment.\n\n   And  oh, just like I first introduced cursor control in ConfScan, KiLLER\n   comment also uses cursor control for selecting a user you can write to.\n\n   Anyway,  I  hope  you  will  enjoy KiLLER Comment as much as I will.  Go\n   check out the features if you want to know more.\n\n                                                          -KiLLraVeN/MYSTiC\n@ENDNODE\n\n@NODE Features "Features of KiLLER Comment - © 1994 KiLLraVeN/MYSTiC"\n                        .------------------------------.\n                        |  Features of KiLLER Comment  |\n                        `------------------------------''\n\n   Although  the  list  of  features isn''t big, it''s enough for a [C]omment\n   door.  Remember, it''s only a [C]omment door.\n\n   » GUI Config\n\n   A small program comes with it to set it up the way you want it as easy\n   as possible.  It''s just click and save, you probably won''t even need the\n   keyboard but to fill in some personal info.\n\n   » Security\n\n   Users  with  low  access will not see all cosysops in the [C]omment list\n   (esspecially useful with new users).\n\n   » Known as\n\n   Very often your cosysops will have names that contain some sort of group\n   name  in  it  (like  KiLLraVeN/MYSTiC), but it''s not always that nice or\n   handy  to  have  that group name in the comment door (be it for cosmetic\n   reasons,  be  it  for  some  other reason).  That''s why you can enter an\n   alias  for  each of your cosysops (and for yourself ofcourse) which will\n   be used to display in the comment list.\n\n   » Info\n\n   For  every (co)sysop you can enter one line of information regarding why\n   he  is in the comment list.  This can be something like "Amiga Co-Sysop"\n   or "Takes care of users / files / lamers".\n\n   » Comments\n\n   Most  comment doors offer you the possibility to display a message after\n   the  user has selected someone to write to.  This is generally something\n   like  "<name>  says:   bla bla".  With KiLLER Comment you can make lines\n   like  this:   "And  there  goes another message to <name>" or "<name> is\n   cheering of joy!".\n   \n   An example file with fortune cookies has been supplied (Comments.ASCII).\n\n   » Cursor Control / Numeric entries / Default sysop\n\n   Selecting  a  user  can  be done with the cursor keys or by entering the\n   corresponding number.  A default sysop is also available (space).\n\n   » Comment Statistics\n\n   KiLLER  Comment  keeps record of the number of messages written to every\n   user  and  also knows when every user received his last message plus the\n   user  who  wrote  it to him.  So with this information it is possible to\n   create  some  nice  looking  statistics.  These statistics can be viewed\n   within /X or with the Config program.\n@ENDNODE\n\n@NODE Install "How to install KiLLER Comment - © 1994 KiLLraVeN/MYSTiC"\n                      .----------------------------------.\n                      |  Installation of KiLLER Comment  |\n                      `----------------------------------''\n\n   KiLLER  Comment  can  be installed like any /X 3.x command, but please\n   take notice of these tooltypes:\n\n   "KC-Config.info" - The icon of the GUI config program\n   \n   · ACP_LOCATION=<path>      - Location of your ACP.info file.\n                                (eg. ACP_LOCATION=SYS:WBStartUp)\n\n   · KC_LOCATION=<path>       - Location of the /X version\n                                (eg. KC_LOCATION=DOORS:K-Comment)\n                                ** NOTE ** NOTE ** NOTE ** NOTE ** NOTE **\n                                 THIS SHOULD BE THE PATH TO THE DIRECTORY\n                                 AND SHOULD _NOT_ INCLUDE THE NAME OF THE\n                                 EXECUTABLE! DON''T FORGET THIS! (HI JAKE)\n                                ** NOTE ** NOTE ** NOTE ** NOTE ** NOTE **\n\n   · KC_VIEWER=<full name>    - External viewer for the Commentistics\n                                (eg. KC_VIEWER=C:PPMORE)\n\n   · PUB_SCREEN=<name>        - Optional(!) name of public screen that the\n                                config program will open on instead of the\n                                Workbench.\n                                (eg. PUB_SCREEN=ECS_PUB)\n\n   "C.info"          - The icon in your BBS command directory\n\n   · ACS_STATS=<level>        - The minimum level required to view the\n                                statiscal mumbo jumbo that KiLLER Comment\n                                is able to create for you (with ''C ?'').\n                                (eg. ACS_STATS=50)\n\n   · BBS_LOCATION=<path>      - This should be the path to your BBS:, or\n                                if you keep your USER.DATA located some-\n                                where else, the path to your USER.DATA.\n\n   · SEPARATOR_LINES          - An empty line is by default put  between\n                                two sysops if possible, but if you don''t\n                                like  that,  you can also have a line of\n                                ''-''s put between them.  To do so, simply\n                                this tooltype.\n\n   I  have  found  it  very  useful  to  put the Config program in my ACP\n   command list.  Maybe this can be useful for you too.\n\n@ENDNODE\n\n@NODE AmiUsage "Usage in Ami-Express - © 1994 KiLLraVeN/MYSTiC"\n                          .------------------------.\n                          |  Usage in Ami-Express  |\n                          `------------------------''\n\n                          ^-^  Selecting a user  ^-^\n\n   Once  installed, the usage of the [C]omment door is (and should be) real\n   easy.  You can simply start it with ''C'' and you will be presented with a\n   menu from which you can select a user to send some mail to.\n\n   However,  like I said in the first words, KiLLER comment is a bit smart.\n   If  you enter a parameter after the ''C'', you can skip the menu and still\n   select  the  person you want to write to.  For example, suppose you want\n   to write a message to "Muad''Dib".  We all know that this is a very lousy\n   name  to spell, so we can suffice by entering "C Muad" and Muad''Dib will\n   be selected.\n\n   However,  if  you''ve  got  another  cosysop  in  the  list that is named\n   Muad''Dab,  KiLLER  Comment  will  take  the first name that has the part\n   "muad"  in it.  This is just the way it goes, so if you want to write to\n   Muad''Dab  instead  of  Muad''Dib  you  have  to enter another string that\n   uniquely identifies Muad''Dab, for instance:  "C Dab" :)\n\n   Another  way to select a user is entering his or her appropriate number.\n   If  you  know  that Muad''Dib is number 2 in the list, you can suffice by\n   entering  "C 2".   And  if  you  know that Muad''Dab is number 5, you can\n   enter  "C 5"  to  write  to Muad''Dab.  Real easy.  If you enter a number\n   that does not exist, you will be presented with the menu again.\n\n   But  that''s not all, let''s say you got separate sysops (or cosysops) for\n   different  conferences;  Amiga,  SNES  and  PC.  And suppose you want to\n   write  to  the Amiga cosysop, you can simply enter "C Amiga" or "C Ami".\n   Make  sure  the  length  of  the  string  after  the  "C"  is at least 3\n   characters,  otherwise  it will be marked as ambigious and the menu will\n   be  prompted.   And  yes,  that means that "C PC" will NOT work (haha!).\n   But  hey,  there  are  3  other  ways of selecting that sysop.  So don''t\n   despair (or enter "C p PC" if the text is "Cosysop PC").\n\n                           ^-^  Commentistics  ^-^\n\n   The  commentistics  can be viewed by entering a question mark behind the\n   "C".  Couldn''t be more simple.  Just enter "C ?" and you will be able to\n   view  all  sorts  of  statistic mumbo jumbo on your screen.  Once you''ve\n   seen the first screen, you can go to the next screen by pressing any key\n   BUT Q, ESC can CTRL-C.  Than the screen will be cleared in a fashionable\n   style and the last page will be shown, containing the times and names of\n   users who wrote last to the users in the Comment list.\n\n                           ^-^  Syntax Summary  ^-^\n\n   For all you folks that didn''t bother to read the upper texts, here''s the\n   brief list of all commands:\n\n   C        - A menu will be shown from which you can select a user\n\n   C <text> - The  <text> will be compared to the names of the users in the\n              list  and  if  that fails, it will be compared to the info of\n              each user in the list. This comparing is case insensitive.\n\n   C <#>    - The corresponding name with the number will be selected.\n\n   C ?      - The commentistics will be shown.\n\n@ENDNODE\n\n@NODE Config "The Config Editor - © 1994 KiLLraVeN/MYSTiC"\n                             .-----------------.\n                             |  Config Editor  |\n                             `-----------------''\n\n   KiLLER  Comment  comes  with  a  full C= compliant Guided User Interface\n   (commonly  known  as  GUI).  With this Configuration Editor you are able\n   to setup KiLLER Comment the way YOU want.\n\n   When  you  start  the  Config  Editor for the first time, the sysop will\n   automatically  added as the first entry in the list of users that can be\n   commented  to.   There  should  at  least  be  ONE  entry in the list or\n   otherwise the user can''t comment to anybody :-)\n\n   Okay,  I  think it is best if I just tell you what every button does and\n   how to do things.  Here we go...\n\n   » Known As\n\n   You  can  enter an alias for every user that is in the list.  By default\n   the  alias  is  the  same  as  their real name in /X but you are free to\n   change  it.  KiLLER Comment will still know their real name, don''t worry\n   about that.  This function can be handy if you got a cosysop with a name\n   like [-Bad Boy^Lamers-R-Us^I-Suck-] but you don''t want to have that damn\n   ugly handle in your comment door.  Fill in whatever you like.\n\n   » Info\n\n   As  usual  you are able to enter one line of text that somehow describes\n   why  this  user  is put in the list of ''commenteers'' :) You can put info\n   like "Amiga Cosysop" in here or "Nuking is my nick-name!".  You are free\n   to  use  any colours in it, just enter them in the gadget like you would\n   do  in  a  text  file.   If pressing the ESC removes the cursor from the\n   gadget,  you  need to TURN OF THE TEXT-FILTER OPTION IN YOUR PREFERENCES\n   FROM YOUR AMIGA (Prefs/IControl)!!\n\n   Although  you  can only have like 34 chars on screen for info about that\n   user,  the  Config  Editor  takes 80 chars.  You are responsible for the\n   length  of  the  text.   If you put 80 chars of text in it, it will look\n   like a mess on screen in Ami-Express.\n\n   » Comments\n\n   A  comment is a line of text that is shown to the user who just selected\n   somebody.   This  can  be  a  message  like  "Muad''Dib says:  Thanks for\n   nothing!"  or  "You can hear Muad''Dib shout with joy.".  Or you can show\n   him fortune cookie (max.  1 line!).  An example file has been included.\n\n   This gadget wants a full path plus filename to a file that contains such\n   messages.   This can be a different file for every user or the same file\n   for all users.  The lines in the text file can contain anything you like\n   where you can use ''%s'' to represent the name of the choosen user.\n\n   Examples:   %s says: Thanks for your mail bud.\n               You can hear %s scream with joy.\n               %s is overwhelmed with tears by your gesture.\n               Who is General Failure and why is he reading my hard drive?\n\n   Be creative!\n\n   With  the  [S]  button  you  can select a file via a file-requester than\n   rather typing in its full name.\n\n   » Req. Acs\n\n   For  security  reasons,  you  are able to set a minimum access level for\n   every  user in the comment list.  This way you are able to have multiple\n   cosysops and not let all the users know what they all do.\n\n   Imagine  you''ve got a cosysop for the Amiga section, SNES section and PC\n   section.   You''ve  got  a lot of Amiga users, but you don''t want them to\n   know  that  you  got  a  PC  section.   If  they would use the ''C'' door,\n   normally  they  would  see  that  you  got a cosysop for the PC section.\n   "What  PC  section?"  they will think.  Or even worse, new users who use\n   the door can easily spot your conferences.  But not with KiLLER Comment,\n   just  make  sure that the Amiga users have a lower access level than the\n   PC users.\n\n   It''s  not  perfect yet, but it''s a start.  I am thinking of a better way\n   to secure this (it''s possible, I just have to work it out a bit more).\n\n   By  the  way,  cosysops  with  "C"  access  will  also NOT see the other\n   cosysop(s) (not even in the Commentistics).\n\n   » Commentistics\n\n   Not  only in Ami-Express, but also in the Config Editor, you are able to\n   look  up  the statistics that KiLLER Comment can create.  The statistics\n   are  put  into  a  file  and that file is shown to you with the external\n   viewer  you specified.  For your information, that file is always called\n   T:KC_Commentistics,  does  NOT  contain  any  ANSI  codes and is removed\n   afterwards.\n\n   » Add / Del\n\n   Adding  a  user  to  the  list is quite easy, select Add and you will be\n   presented  with  a  list  of all your users in your USER.DATA.  This may\n   take  a  while,  depending on your type (read:  speed) of computer, hard\n   drive  and number of users in your USER.DATA.  A new user will always be\n   inserted at the END of the list.\n\n   To  remove  a user from the list, make it the active user (its name will\n   be  shown  below the listview) and press Del.  Easy as peanuts.  The new\n   current user will be the last user in the list.\n\n   You can not remove all users from the list.  A protection has been built\n   in  so please try to do so :) It''s impossible to remove them all because\n   to who should the users in your system comment to?\n\n   » Up / Down\n\n   With  those  gadgets  you  are  able to determine the order in which the\n   users  will  appear a) in the list and b) on screen in Ami-Express.  The\n   most upper user will be the default sysop!\n\n   To  move  a user, make it the current one by selecting it and then press\n   either up or down (repeatively if neccessary).\n\n   » Save\n\n   Guess what?\n\n   » &\n   \n   Sorry? What did you say? :)\n\n   » Quit\n\n   You  guessed  it.   By  the  way,  there  is  NO  warning if you changed\n   something and did not save it before quitting.\n\n@ENDNODE\n\n@NODE Greetings "Greetings go to... - © KiLLraVeN/MYSTiC"\n                            .-------------------.\n                            |  Greetings to...  |\n                            `-------------------''\n\n                  ^-^   ALL MYSTiC MEMBERS WORLD-WIDE!   ^-^\n\n                            YOU ARE THE GREATEST!\n\n                  ^-^   ALL MYSTiC MEMBERS WORLD-WIDE!   ^-^\n\n\n   Muad''Dib       Happy New Year! Come to the Mazzo!\n\n   Quartz         And you made me make another update... :)\n   \n            To all my other friends I say: Happy New Year!\n\n   If you want to contact me, read @{"this!" link Contact}\n@ENDNODE\n\n@NODE Contact "How to get in touch with me - © KiLLraVeN/MYSTiC"\n                             - ------------------.\n                            |  Contacting me...  |\n                            `------------------ - \n\n                 I can be reached on the following boards:\n\n                       - - -- --- ------- --- -- - -\n\n                The Undiscovered       +31-2294-1442 (USR 28k8)\n                                       +31-2294-4442 (USR 28k8)\n                                       +31-2294-tRY! (USR 28k8)\n\n                Last Outpost           +31-72-201182 (USR 28k8)\n                                       +31-72-157682 (USR 28k8)\n\n         I know, you have to call The Netherlands for it, but it''s\n            the only boards I call on a frequent basis, sorry.\n\n                       - - -- --- ------- --- -- - -\n\n       For FAST response (preferred) please contact me on Internet:\n\n                               [email removed]\n\n                    ( [email removed] -- backup )\n\n                       - - -- --- ------- --- -- - -\n\n        You can also find me on IRC once in a while on the channels\n                     #amigascne, #amiga and #megawatt\n@ENDNODE\n\n@NODE History "History of KiLLER Comment - © 1994 KiLLraVeN/MYSTiC"\n\n   1.1.0    26-12-94    KiLLER [C]omment now checks wether the persons in\n                        the [C]omment list have access to the current conf\n                        that KC is called from. If not, that person will\n                        not be put in the list.\n                        REQUESTED BY: QuartZ\n\n   1.0.5    02-11-94    You can now have lines used as a separator on screen\n                        instead of a blank line.\n                        New tooltype: SEPARATOR_LINES\n                        REQUESTED BY: JAKE\n\n   1.0.4    20-10-94    Added an access level check. If a user does not have\n                        the minimal required access to actually see a cosysop\n                        in the Comment list, than that user will not see\n                        that cosysop. See also @{"History Gui" link HistoryGUI}.\n                        REQUESTED BY: TYCOON/MYSTIC & MUAD''DIB\n\n            20-10-94    The program now attempts to write messages with the\n                        external "E" door (if any). This makes it more\n                        flexible for sysop, allowing them to have external\n                        "E" doors installed, like the one from 5D and the\n                        external one from Tycoon/MYSTiC (/X-Fido).\n                        REQUESTED BY: TYCOON/MYSTiC\n\n   1.0.3    15-10-94    A bug in the "Commentistics" routine caused a guru\n                        when there were users with no messages. A division\n                        by zero was the result -> guru :( Fixed that.\n\n   1.0.0    14-10-94    First initial release to friends.\n\n@ENDNODE\n\n@NODE HistoryGUI "History of KiLLER Config Editor - © 1994 KiLLraVeN/MYSTiC"\n\n   1.0.2    20-10-94    Restyled the GUI bit. I removed the "Show Comments"\n                        gadget because I found it not useful. Removed the\n                        code also (ofcoz, but you never know who reads\n                        this :) ).\n\n            20-10-94    New option: [ Req. Acs ] (Required Access)\n                        You can set a minimum access level per user in the\n                        list. Users with an access level lower than that\n                        level will NOT see him in the [C]omment door.\n                        This enables you to let even new users use this\n                        door and not reveal to them that you (for instance)\n                        have an Amiga cosysop and/or SNES cosysop and/or\n                        PC cosysop.\n                        REQUESTED BY: TYCOON/MYSTIC & MUAD''DIB/DLT\n\n            20-10-94    New option: [ Clear Statistical Data ]\n                        With this option you can clear all statistical data\n                        that is kept for every user. This means that the\n                        total # of msg-s, last msg date and user will be set\n                        to 0 (or None).\n\n            20-10-94    Another restyle: [ Save ][ & ][ Quit ]\n                        Save -> Saves the (new) prefs\n                        &    -> Save and Quit\n                        Quit -> Quit the program\n\n            20-10-94    Another restyle: I changed the placed of the [ Add ]\n                        [ Del ] [ Up ] [ Down ] a bit, to make it a bit more\n                        logical.\n\n   1.0.1    14-10-94    First bug found in 3 secs by Muad''Dib :) If you\n                        selected "Commentistics" from the GUI Config and\n                        there were no messages written yet, a crash was\n                        the result (division by zero). Fixed it.\n\n   1.0.0    14-10-94    First initial release to friends.\n@ENDNODE\n','\n',char(10)),'{"LOCATION":"<path>"}','auto-added',47821,1,0,NULL,NULL,'mst_kc11','scan',1780048619);
INSERT INTO door_catalog VALUES('mst_kc12','MST-KC12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MST-KC12.LHA','KC-Config','XIM','KC-Config',NULL,NULL,'MST','|______ __  / _   ____  ___  _  __//_//    | |\/ / / /  /  /\_  \ /  //  /  /__         | ¦/ / / /\__  /  /  //  //  /  /  / ____    |',replace('.___/\____/\_ __/\_____/\__/\_/\___ __ ____.\n|______ __  / _   ____  ___  _  __//_//    |\n|\/ / / /  /  /\_  \ /  //  /  /__         |\n¦/ / / /\__  /  /  //  //  /  /  / ____    |\n/_/_/ /___  /___  //  //  /\__  /__\  /____.\n____ /____ /____ /__ /__ /____ /___\\//_   ¦\n|  \/bIS \/    \/  \/  \/    \/     \/     |\nKiLLER CoMMENT DooR fOR /X\n','\n',char(10)),'KiLLER-Comment.GUiDE',replace('@DATABASE "KiLLER-Comment.GUiDE"\n@REMARK	.-------------------------------------------------------.\n@REMARK  | This document should be read with AmigaGuide (OS 2.x) |\n@REMARK  | or MultiView (OS 3.x) or any other guide reader. Tnx. |\n@REMARK  `-------------------------------------------------------''\n@REMARK	$VER: KiLLER Comment 1.2.0\n@WIDTH 80\n@NODE MAIN "KiLLER Comment - MYSTiC 1994/1995 - © 1994/1995 KiLLraVeN/MYSTiC"\n                            Guide to KiLLER Comment\n                     for Ami-Express Bulletin Board Systems\n\n                             Program version: 1.2.0\n                Compilation Date/Time: Thu Feb  2 15:23:39 1995\n\n                         © 1994/1995 by @{"KiLLraVeN/MYSTiC" link Contact}\n\n                   ... another fine MYSTiC /X production ...\n\n      @{" First words... " link WhatIs}    What/Why is KiLLER Comment?\n      @{" Features       " link Features}    What can it do?\n      @{" Installation   " link Install}    How to install KiLLER Comment on your BBS\n      @{" Usage /X       " link AmiUsage}    How things go with Ami-Express\n      @{" Usage Config   " link Config}    How to use the Config GUI\n      @{" History        " link History}    History of KiLLER Comment\n      @{" History Config " link HistoryGUI}    History of KiLLER Config\n      @{" Greetings      " link Greetings}    Greetings, messages and contact info\n@ENDNODE\n\n@NODE WhatIs "What/Why is KiLLER Comment? - © 1994/1995 KiLLraVeN/MYSTiC"\n                         .---------------------------.\n                         |  What is KiLLER Comment?  |\n                         `---------------------------''\n\n   KiLLER Comment is number 1001 in the row of a [C]omment doors.  But this\n   is not just *a* comment door, otherwise I wouldn''t have made it.  I have\n   some profound reasons.\n\n   Despite  the  fact  that  there  must be over a 1000 different [C]omment\n   doors,  there  is not one comment door that suits my needs.  I have seen\n   plenty of them but to me they all look ugly, have static interfaces, are\n   as flexible as a log of wood and generally suck :-).\n\n   With  this mind I''ve tried to make KiLLER Comment as smart and pretty as\n   I  can  and  I  feel I have succeeded.  I have never seen a comment door\n   that  works  as  simple  as  this  one  with  a fair amount of so-called\n   ''intelligence'' and comes with a nice GUI.\n\n   What  is  this  ''intelligence'' I speak about you say?  Well, all comment\n   doors  sofar  weren''t  able  to see that if I typed "c kill" I wanted to\n   comment to "KiLLraVeN/MYSTiC" nor where they able to see that if I typed\n   "c  amiga" I wanted to comment to the Amiga co-sysop.  KiLLER Comment is\n   able to detect this!\n\n   Another  thing  is  security.   Every  new  user  was  able to see which\n   cosysops  you  had,  but  by giving every cosysop a security level, they\n   will  not see their names/jobs.  And if there is only one (co)sysop they\n   are  allowed  to  see,  they  will  not  even  see it is done via KiLLER\n   Comment.\n\n   Also,  per user in the [C]omment list there is a check wether he/she has\n   got access to the conference that KiLLER [C]omment is called from, so it\n   is impossible to write a person to someone in the wrong conference.\n\n   What I personally also dislike are comment doors that only fill like 25%\n   of  your  screen.   Not  that  you  should put a lot of nonsense in your\n   comment  door,  no,  but  KiLLER  Comment puts an extra line between the\n   names  of  the  (co-)sysops  if  that''s possible with the user''s maximum\n   numbers  of  lines  he  can  handle  on his screen.  It''s these kinds of\n   things I miss in those 13-in-a-dozen [C]omment doors.  That''s why I made\n   KiLLER Comment.\n\n   And  oh, just like I first introduced cursor control in ConfScan, KiLLER\n   comment also uses cursor control for selecting a user you can write to.\n\n   Anyway,  I  hope  you  will  enjoy KiLLER Comment as much as I will.  Go\n   check out the features if you want to know more.\n\n                                                          -KiLLraVeN/MYSTiC\n@ENDNODE\n\n@NODE Features "Features of KiLLER Comment - © 1994/1995 KiLLraVeN/MYSTiC"\n                        .------------------------------.\n                        |  Features of KiLLER Comment  |\n                        `------------------------------''\n\n   Although  the  list  of  features isn''t big, it''s enough for a [C]omment\n   door.  Remember, it''s only a [C]omment door.\n\n   » GUI Config\n\n   A small program comes with it to set it up the way you want it as easy\n   as possible.  It''s just click and save, you probably won''t even need the\n   keyboard but to fill in some personal info.\n\n   » Security\n\n   Users  with  low  access will not see all cosysops in the [C]omment list\n   (esspecially useful with new users).\n\n   » Known as\n\n   Very often your cosysops will have names that contain some sort of group\n   name  in  it  (like  KiLLraVeN/MYSTiC), but it''s not always that nice or\n   handy  to  have  that group name in the comment door (be it for cosmetic\n   reasons,  be  it  for  some  other reason).  That''s why you can enter an\n   alias  for  each of your cosysops (and for yourself ofcourse) which will\n   be used to display in the comment list.\n\n   » Info\n\n   For  every (co)sysop you can enter one line of information regarding why\n   he  is in the comment list.  This can be something like "Amiga Co-Sysop"\n   or "Takes care of users / files / lamers".\n\n   » Comments\n\n   Most  comment doors offer you the possibility to display a message after\n   the  user has selected someone to write to.  This is generally something\n   like  "<name>  says:   bla bla".  With KiLLER Comment you can make lines\n   like  this:   "And  there  goes another message to <name>" or "<name> is\n   cheering of joy!".\n   \n   An example file with fortune cookies has been supplied (Comments.ASCII).\n\n   » Cursor Control / Numeric entries / Default sysop\n\n   Selecting  a  user  can  be done with the cursor keys or by entering the\n   corresponding number.  A default sysop is also available (space).\n\n   » Comment Statistics\n\n   KiLLER  Comment  keeps record of the number of messages written to every\n   user  and  also knows when every user received his last message plus the\n   user  who  wrote  it to him.  So with this information it is possible to\n   create  some  nice  looking  statistics.  These statistics can be viewed\n   within /X or with the Config program.\n@ENDNODE\n\n@NODE Install "How to install KiLLER Comment - © 1994/1995 KiLLraVeN/MYSTiC"\n                      .----------------------------------.\n                      |  Installation of KiLLER Comment  |\n                      `----------------------------------''\n\n   KiLLER  Comment  can  be installed like any /X 3.x command, but please\n   take notice of these tooltypes:\n\n   "KC-Config.info" - The icon of the GUI config program\n   \n   · ACP_LOCATION=<path>      - Location of your ACP.info file.\n                                (eg. ACP_LOCATION=SYS:WBStartUp)\n\n   · KC_LOCATION=<path>       - Location of the /X version\n                                (eg. KC_LOCATION=DOORS:K-Comment)\n                                ** NOTE ** NOTE ** NOTE ** NOTE ** NOTE **\n                                 THIS SHOULD BE THE PATH TO THE DIRECTORY\n                                 AND SHOULD _NOT_ INCLUDE THE NAME OF THE\n                                 EXECUTABLE! DON''T FORGET THIS! (HI JAKE)\n                                ** NOTE ** NOTE ** NOTE ** NOTE ** NOTE **\n\n   · KC_VIEWER=<full name>    - External viewer for the Commentistics\n                                (eg. KC_VIEWER=C:PPMORE)\n\n   · PUB_SCREEN=<name>        - Optional(!) name of public screen that the\n                                config program will open on instead of the\n                                Workbench.\n                                (eg. PUB_SCREEN=ECS_PUB)\n\n   "C.info"          - The icon in your BBS command directory\n\n   · ACS_STATS=<level>        - The minimum level required to view the\n                                statiscal mumbo jumbo that KiLLER Comment\n                                is able to create for you (with ''C ?'').\n                                (eg. ACS_STATS=50)\n\n   · BBS_LOCATION=<path>      - This should be the path to your BBS:, or\n                                if you keep your USER.DATA located some-\n                                where else, the path to your USER.DATA.\n\n   · SEPARATOR_LINES          - An empty line is by default put  between\n                                two sysops if possible, but if you don''t\n                                like  that,  you can also have a line of\n                                ''-''s put between them.  To do so, simply\n                                this tooltype.\n\n   I  have  found  it  very  useful  to  put the Config program in my ACP\n   command list.  Maybe this can be useful for you too.\n\n@ENDNODE\n\n@NODE AmiUsage "Usage in Ami-Express - © 1994/1995 KiLLraVeN/MYSTiC"\n                          .------------------------.\n                          |  Usage in Ami-Express  |\n                          `------------------------''\n\n                          ^-^  Selecting a user  ^-^\n\n   Once  installed, the usage of the [C]omment door is (and should be) real\n   easy.  You can simply start it with ''C'' and you will be presented with a\n   menu from which you can select a user to send some mail to.\n\n   However,  like I said in the first words, KiLLER comment is a bit smart.\n   If  you enter a parameter after the ''C'', you can skip the menu and still\n   select  the  person you want to write to.  For example, suppose you want\n   to write a message to "Muad''Dib".  We all know that this is a very lousy\n   name  to spell, so we can suffice by entering "C Muad" and Muad''Dib will\n   be selected.\n\n   However,  if  you''ve  got  another  cosysop  in  the  list that is named\n   Muad''Dab,  KiLLER  Comment  will  take  the first name that has the part\n   "muad"  in it.  This is just the way it goes, so if you want to write to\n   Muad''Dab  instead  of  Muad''Dib  you  have  to enter another string that\n   uniquely identifies Muad''Dab, for instance:  "C Dab" :)\n\n   Another  way to select a user is entering his or her appropriate number.\n   If  you  know  that Muad''Dib is number 2 in the list, you can suffice by\n   entering  "C 2".   And  if  you  know that Muad''Dab is number 5, you can\n   enter  "C 5"  to  write  to Muad''Dab.  Real easy.  If you enter a number\n   that does not exist, you will be presented with the menu again.\n\n   But  that''s not all, let''s say you got separate sysops (or cosysops) for\n   different  conferences;  Amiga,  SNES  and  PC.  And suppose you want to\n   write  to  the Amiga cosysop, you can simply enter "C Amiga" or "C Ami".\n   Make  sure  the  length  of  the  string  after  the  "C"  is at least 3\n   characters,  otherwise  it will be marked as ambigious and the menu will\n   be  prompted.   And  yes,  that means that "C PC" will NOT work (haha!).\n   But  hey,  there  are  3  other  ways of selecting that sysop.  So don''t\n   despair (or enter "C p PC" if the text is "Cosysop PC").\n\n                           ^-^  Commentistics  ^-^\n\n   The  commentistics  can be viewed by entering a question mark behind the\n   "C".  Couldn''t be more simple.  Just enter "C ?" and you will be able to\n   view  all  sorts  of  statistic mumbo jumbo on your screen.  Once you''ve\n   seen the first screen, you can go to the next screen by pressing any key\n   BUT Q, ESC can CTRL-C.  Than the screen will be cleared in a fashionable\n   style and the last page will be shown, containing the times and names of\n   users who wrote last to the users in the Comment list.\n\n                           ^-^  Syntax Summary  ^-^\n\n   For all you folks that didn''t bother to read the upper texts, here''s the\n   brief list of all commands:\n\n   C        - A menu will be shown from which you can select a user\n\n   C <text> - The  <text> will be compared to the names of the users in the\n              list  and  if  that fails, it will be compared to the info of\n              each user in the list. This comparing is case insensitive.\n\n   C <#>    - The corresponding name with the number will be selected.\n\n   C ?      - The commentistics will be shown.\n\n@ENDNODE\n\n@NODE Config "The Config Editor - © 1994/1995 KiLLraVeN/MYSTiC"\n                             .-----------------.\n                             |  Config Editor  |\n                             `-----------------''\n\n   KiLLER  Comment  comes  with  a  full C= compliant Guided User Interface\n   (commonly  known  as  GUI).  With this Configuration Editor you are able\n   to setup KiLLER Comment the way YOU want.\n\n   When  you  start  the  Config  Editor for the first time, the sysop will\n   automatically  added as the first entry in the list of users that can be\n   commented  to.   There  should  at  least  be  ONE  entry in the list or\n   otherwise the user can''t comment to anybody :-)\n\n   Okay,  I  think it is best if I just tell you what every button does and\n   how to do things.  Here we go...\n\n   » Known As\n\n   You  can  enter an alias for every user that is in the list.  By default\n   the  alias  is  the  same  as  their real name in /X but you are free to\n   change  it.  KiLLER Comment will still know their real name, don''t worry\n   about that.  This function can be handy if you got a cosysop with a name\n   like [-Bad Boy^Lamers-R-Us^I-Suck-] but you don''t want to have that damn\n   ugly handle in your comment door.  Fill in whatever you like.\n\n   » Info\n\n   As  usual  you are able to enter one line of text that somehow describes\n   why  this  user  is put in the list of ''commenteers'' :) You can put info\n   like "Amiga Cosysop" in here or "Nuking is my nick-name!".  You are free\n   to  use  any colours in it, just enter them in the gadget like you would\n   do  in  a  text  file.   If pressing the ESC removes the cursor from the\n   gadget,  you  need to TURN OF THE TEXT-FILTER OPTION IN YOUR PREFERENCES\n   FROM YOUR AMIGA (Prefs/IControl)!!\n\n   Although  you  can only have like 34 chars on screen for info about that\n   user,  the  Config  Editor  takes 80 chars.  You are responsible for the\n   length  of  the  text.   If you put 80 chars of text in it, it will look\n   like a mess on screen in Ami-Express.\n\n   » Comments\n\n   A  comment is a line of text that is shown to the user who just selected\n   somebody.   This  can  be  a  message  like  "Muad''Dib says:  Thanks for\n   nothing!"  or  "You can hear Muad''Dib shout with joy.".  Or you can show\n   him fortune cookie (max.  1 line!).  An example file has been included.\n\n   This gadget wants a full path plus filename to a file that contains such\n   messages.   This can be a different file for every user or the same file\n   for all users.  The lines in the text file can contain anything you like\n   where you can use ''%s'' to represent the name of the choosen user.\n\n   Examples:   %s says: Thanks for your mail bud.\n               You can hear %s scream with joy.\n               %s is overwhelmed with tears by your gesture.\n               Who is General Failure and why is he reading my hard drive?\n\n   Be creative!\n\n   With  the  [S]  button  you  can select a file via a file-requester than\n   rather typing in its full name.\n\n   » Req. Acs\n\n   For  security  reasons,  you  are able to set a minimum access level for\n   every  user in the comment list.  This way you are able to have multiple\n   cosysops and not let all the users know what they all do.\n\n   Imagine  you''ve got a cosysop for the Amiga section, SNES section and PC\n   section.   You''ve  got  a lot of Amiga users, but you don''t want them to\n   know  that  you  got  a  PC  section.   If  they would use the ''C'' door,\n   normally  they  would  see  that  you  got a cosysop for the PC section.\n   "What  PC  section?"  they will think.  Or even worse, new users who use\n   the door can easily spot your conferences.  But not with KiLLER Comment,\n   just  make  sure that the Amiga users have a lower access level than the\n   PC users.\n\n   It''s  not  perfect yet, but it''s a start.  I am thinking of a better way\n   to secure this (it''s possible, I just have to work it out a bit more).\n\n   By  the  way,  cosysops  with  "C"  access  will  also NOT see the other\n   cosysop(s) (not even in the Commentistics).\n\n   » Commentistics\n\n   Not  only in Ami-Express, but also in the Config Editor, you are able to\n   look  up  the statistics that KiLLER Comment can create.  The statistics\n   are  put  into  a  file  and that file is shown to you with the external\n   viewer  you specified.  For your information, that file is always called\n   T:KC_Commentistics,  does  NOT  contain  any  ANSI  codes and is removed\n   afterwards.\n\n   » Add / Del\n\n   Adding  a  user  to  the  list is quite easy, select Add and you will be\n   presented  with  a  list  of all your users in your USER.DATA.  This may\n   take  a  while,  depending on your type (read:  speed) of computer, hard\n   drive  and number of users in your USER.DATA.  A new user will always be\n   inserted at the END of the list.\n\n   To  remove  a user from the list, make it the active user (its name will\n   be  shown  below the listview) and press Del.  Easy as peanuts.  The new\n   current user will be the last user in the list.\n\n   You can not remove all users from the list.  A protection has been built\n   in  so please try to do so :) It''s impossible to remove them all because\n   to who should the users in your system comment to?\n\n   » Up / Down\n\n   With  those  gadgets  you  are  able to determine the order in which the\n   users  will  appear a) in the list and b) on screen in Ami-Express.  The\n   most upper user will be the default sysop!\n\n   To  move  a user, make it the current one by selecting it and then press\n   either up or down (repeatively if neccessary).\n\n   » Save\n\n   Guess what?\n\n   » &\n   \n   Sorry? What did you say? :)\n\n   » Quit\n\n   You  guessed  it.   By  the  way,  there  is  NO  warning if you changed\n   something and did not save it before quitting.\n\n@ENDNODE\n\n@NODE Greetings "Greetings go to... - © KiLLraVeN/MYSTiC"\n                            .-------------------.\n                            |  Greetings to...  |\n                            `-------------------''\n\n                            In no specific order:\n\n            Muad''Dib/DLT ^ Motive Power/MST ^ QuartZ/MST ^ Jabbah \n\n            Exotic ^ UFOk/MST ^ Easy Rider/MST ^ I-GO/MW ^ Galaxy\n\n        bObO/MST ^ Famous''O''Hara ^ Zed ^ Green Beret/MST ^ Arcade/MST\n\n                     ... and to all my other friends ...\n\n\n   If you want to contact me, read @{"this!" link Contact}\n@ENDNODE\n\n@NODE Contact "How to get in touch with me - © KiLLraVeN/MYSTiC"\n                             - ------------------.\n                            |  Contacting me...  |\n                            `------------------ - \n\n       For FAST response (preferred) please contact me on Internet:\n\n                               [email removed]\n\n                    ( [email removed] -- backup )\n\n                       - - -- --- ------- --- -- - -\n\n                 I can be reached on the following boards:\n\n                The Undiscovered       +31-2294-1442 (USR 28k8)\n                                       +31-2294-4442 (USR 28k8)\n                                       +31-2294-tRY! (USR 28k8)\n\n                Last Outpost           +31-72-201182 (USR 28k8)\n                                       +31-72-157682 (USR 28k8)\n\n         I know, you have to call The Netherlands for it, but it''s\n            the only boards I call on a frequent basis, sorry.\n\n                       - - -- --- ------- --- -- - -\n\n        You can also find me on IRC once in a while on the channels\n                     #amigascne, #amiga and #megawatt\n@ENDNODE\n\n@NODE History "History of KiLLER Comment - © 1994/1995 KiLLraVeN/MYSTiC"\n\n   1.2.0    03-02-95    Fixed the version numbers in the executable ;)\n                        REPORTED BY: MOTiVE POWER\n                        \n                        You can now enter an asterisk behind the name of\n                        the person you want to write to (ie. C MUAD*).\n                        REQUESTED BY: MUAD''DiB\n                        \n                        Made the percentage bar in the commentistics a\n                        relative one, like in KiLLER-Baud. The user with\n                        the most messages will always have 100% and the\n                        rest will be a relative representation to that\n                        user.\n\n   1.1.0    26-12-94    KiLLER [C]omment now checks wether the persons in\n                        the [C]omment list have access to the current conf\n                        that KC is called from. If not, that person will\n                        not be put in the list.\n                        REQUESTED BY: QuartZ\n\n   1.0.5    02-11-94    You can now have lines used as a separator on screen\n                        instead of a blank line.\n                        New tooltype: SEPARATOR_LINES\n                        REQUESTED BY: JAKE\n\n   1.0.4    20-10-94    Added an access level check. If a user does not have\n                        the minimal required access to actually see a cosysop\n                        in the Comment list, than that user will not see\n                        that cosysop. See also @{"History Gui" link HistoryGUI}.\n                        REQUESTED BY: TYCOON/MYSTiC & MUAD''DiB\n\n            20-10-94    The program now attempts to write messages with the\n                        external "E" door (if any). This makes it more\n                        flexible for sysop, allowing them to have external\n                        "E" doors installed, like the one from 5D and the\n                        external one from Tycoon/MYSTiC (/X-Fido).\n                        REQUESTED BY: TYCOON/MYSTiC\n\n   1.0.3    15-10-94    A bug in the "Commentistics" routine caused a guru\n                        when there were users with no messages. A division\n                        by zero was the result -> guru :( Fixed that.\n\n   1.0.0    14-10-94    First initial release to friends.\n\n@ENDNODE\n\n@NODE HistoryGUI "History of KiLLER Config Editor - © 1994/1995 KiLLraVeN/MYSTiC"\n\n   1.0.3    14-02-95    Fixed a bug that caused all users with a name\n                        shorter than 4 characters to be left out of the\n                        user-list when you wanted to add a user.\n                        REPORTED BY: PHANTOM/OVERLORDS\n\n   1.0.2    20-10-94    Restyled the GUI bit. I removed the "Show Comments"\n                        gadget because I found it not useful. Removed the\n                        code also (ofcoz, but you never know who reads\n                        this :) ).\n\n            20-10-94    New option: [ Req. Acs ] (Required Access)\n                        You can set a minimum access level per user in the\n                        list. Users with an access level lower than that\n                        level will NOT see him in the [C]omment door.\n                        This enables you to let even new users use this\n                        door and not reveal to them that you (for instance)\n                        have an Amiga cosysop and/or SNES cosysop and/or\n                        PC cosysop.\n                        REQUESTED BY: TYCOON/MYSTIC & MUAD''DIB/DLT\n\n            20-10-94    New option: [ Clear Statistical Data ]\n                        With this option you can clear all statistical data\n                        that is kept for every user. This means that the\n                        total # of msg-s, last msg date and user will be set\n                        to 0 (or None).\n\n            20-10-94    Another restyle: [ Save ][ & ][ Quit ]\n                        Save -> Saves the (new) prefs\n                        &    -> Save and Quit\n                        Quit -> Quit the program\n\n            20-10-94    Another restyle: I changed the placed of the [ Add ]\n                        [ Del ] [ Up ] [ Down ] a bit, to make it a bit more\n                        logical.\n\n   1.0.1    14-10-94    First bug found in 3 secs by Muad''Dib :) If you\n                        selected "Commentistics" from the GUI Config and\n                        there were no messages written yet, a crash was\n                        the result (division by zero). Fixed it.\n\n   1.0.0    14-10-94    First initial release to friends.\n@ENDNODE\n','\n',char(10)),'{"LOCATION":"<path>"}','auto-added',56376,1,0,NULL,NULL,'mst_kc12','scan',1780048619);
INSERT INTO door_catalog VALUES('mst_lt10','MST-LT10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MST-LT10.LHA','Last10','XIM','8',NULL,NULL,'MST','/  v  ¼\   v ¼\   ____  _   _____/  .   / /  \ /   \__.   \___  ¼\/    |   ¼\  |__/_ /    v     \ |    \ v    \    |     \ |   ¼\',replace('   __ ___ ___ __ _____________.____________ \n  /  v  ¼\   v ¼\   ____  _   _____/  .   / \n /  \ /   \__.   \___  ¼\/    |   ¼\  |__/_ \n/    v     \ |    \ v    \    |     \ |   ¼\\n\____|___  /____  /____  / ___|___  /____  /\n½-#e#----\/-----\/-----\/\/-------\/-----\/-\n             LAST TEN CALLER`S\n','\n',char(10)),'Last10.GUIDE',replace('@DATABASE "LAST10.GUIDE"\n@WIDTH 80\n@HEIGHT 255\n\n@NODE Main "LAST 10"\n                                 \n                                MYSTIC/X-DESIGN\n                                   PRESENTS \n                                   LAST TEN\n\n                             @{"  Introduction    " link About} \n\n               @{"  Requirements    " LINK Requirements}         @{"  Installation    " LINK Installation} \n\n               @{"  Author          " LINK Author}         @{"  Bug report      " LINK bugs} \n\n               @{"  Update''s        " LINK update''s}         @{"  Greetings       " LINK GREETINGS}\n \n               @{"  Mystic/X-desig  " LINK X_DESIGN}         @{"  Mystic boards   " LINK BOARDS} \n@ENDNODE\n\n@NODE About "About LAST 10"\n\n   Last Ten is an Ami-Express tool made by HardByte/MYSTIC (/X DeSIGn).\n   \n   Last Ten enables the user to see his Last ten Uploads and Downloads\n   from within Ami-X. (still only the node they logged on!)\n   \n   The program needs no parameters.\n\n\n\n\n\n\n   ====================================================================\n   Thanx Must go to EMPiRE who Supplied me (in his eternal wishdom) the\n   Idea for this Great Door!!\n   ====================================================================\n\n@ENDNODE\n\n@NODE Requirements "Requirements"\n\nYou need: /X 3.x\n          OS 2.x+\n          Any Amiga Computer.\n          a UDlog in all the nodes.\n\n          Although the programming is in C, it can take a while, so a\n          accelerator is recommended! Also, large UDLogs can slow things\n          down.\n   \n          The following results were done on a 40 Mhz Amiga.\n\n    +-----+-------------------+--------------------+---------------------+\n    |amiga| Udlog 65820 bytes | Udlog 131640 bytes | Udlog 1316400 bytes |\n    +-----+-------------------+--------------------+---------------------+\n    |40mhz|    +- 1.5 sec     |      +- 3 sec      |     +-  10 sec      |\n    +-----+-------------------+--------------------+---------------------+\n\n@ENDNODE\n\n@NODE Installation "Installation"\n\n   Create a icon in the BBS:COMMANDS/BBSCMD named ''Last10.info''\n   An put the next lines in the icon. (Or copy the file ''Last10.info''\n   from the lha file to bbs:commands/bbscmd/   \n        \n   ACCESS=20                      ;The level the user need to run the door.\n   LOCATION=DOORS:LAST10/Last10   ;Location of this door.\n   MULTINODE=no                   ;If more the 1 node put ''yes''.\n   PRIORITY=0                     ;Priority 0 is good.\n   STACK=20000                    ;Stack Size.\n   TYPE=XIM                       ;Make sure it''s XIM.\n\n   Also copy the files in the fonts directorys to your fonts:\n   for a better display of the rasters around the text.\n\n@ENDNODE\n\n\n@NODE Author "About the Author and the program "\n\n      Author: HARDBYTE/MYSTIC\n         Age: 24\n     Country: HOLLAND\n     \n     Program: First ''C'' program I have made\n \n     For VIRUS checking:\n     the files must have the same sizes as given here!.\n\n     BBS:DOORS/LAST10/    Last10             =    18796 bytes   \n     BBS:DOORS/LAST10/    Last10.guide       =    7525  bytes\n     BBS:COMMANDS/BBSCMD/ Last10.info        =    1071  bytes\n     c/                   AmigaGuide         =    6656  bytes     \n     fonts/ibm/           8                  =    3252  bytes\n     fonts/ibm            ibm.font           =    264   bytes            \n     libs/                amigaguide.library =    24800 bytes\n          \n\n@ENDNODE\n\n@NODE Bugs "Bug report"\n\n   If you think you have found a bug, you can reach me at:\n\n+-------------------------------------------------------------------------+\n|LaST ouTposT   Nd#1 aMiGa ehq! ^ SnEs Whq ÷ /X-DeSiGn EhQ +31-72157682   |\n|LaST ouTposT   Nd#2 aMiGa ehq! ^ SnEs Whq ÷ /X-DeSiGn EhQ +31-72201182   |\n+-------------------------------------------------------------------------+\n\n   And you can leave me a message there.\n\n\n   You can also contact me for any othere reason!!. (LIKE RAYTRACING)\n@ENDNODE\n\n@NODE Update''s "Update''s "\n\n  +------------------------------------------------------------------+\n  | VERSION             DATE             BUG REPORT                  |\n  +------------------------------------------------------------------+  \n  |                                                                  |  \n  | LAST10  V0.000A     11-nov-93        No bugs! (yet!!)            |\n  |                                      Internal release            |  \n  |                                                                  |  \n  | LAST10  V0.000B     15-nov-93        First bug found             |\n  |                                      Did not exit the right way  |\n  |                                      if there was no UDlog found |  \n  |                                                                  |  \n  | LAST10  V0.000C     19-nov-93        There was no raster drawn   |  \n  |                                      around last 10 downloads    |  \n  |                                      if there was no downloading |  \n  |                                      found under the users name. |  \n  |                                                                  |\n  | LAST10  V1.0000     21-nov-93        first release               |\n  +------------------------------------------------------------------+\n@ENDNODE\n\n@NODE Greetings "Greetings "\n\nGreetings go to:\n\nAll mystic members all over the world,\nS.O.B \nAnimator \nCamelot\nRemix/Crystal (what about calling sometime)\nSphinx\nAnd all others I have forgotten! \n\n\nMany thanx to: Killraven/Mystic,\n               EMPiRE/Mystic \n               ByTeAnDi/Mystic  \n               TyCooN/Mystic\n               & Incognito/Mystic   (all mystic/X-design members also) \n               For their help with the program... :)\n\n@ENDNODE\n\n@NODE X_DESIGN "More about Mystic/X-design\n\n               Here the list of the latest Mystic/X-design releases.\n \nRelease date     Name                     Discription\n+----------+--------------+----------------------------------------------+\n| 07-18-93 | CD-STA01.LHA |  CDstatus 0.1                                | \n| 07-18-93 | EMP-UA10.LHA |  Create Bulls Conference Access.             |\n| 09-30-93 | MSTWHO.LHA   |  The ultimate who - search for quite node    |\n| 10-08-93 | SYSDLV1.LHA  |  sysopdownload bug fixedpack dirs,search for |\n|          |              |  files/pathes via tab                        | \n| 10-16-93 | MST-CS2O.LHA |  ConfScan v2.0                               |\n| 10-16-93 | MST-NS02.LHA |  NodeStat v0.2 by KiLLraVeN/MYSTiC (/X 3.x)  |\n|          |              |  Show Statistics About The UDLog By The Day  |\n| 10-17-93 | EMP-JC32.LHA |  AE DOOR: JoinCnf V3.2 /X 3.11+ Update       |\n| 10-11-93 | NFILES21.LHA |  NewFiles V2.1                               |\n+----------+--------------+----------------------------------------------+\n\n AND MANY MORE, CHECK LAST OUTPOST FOR ALL THE MYSTIC RELEASES EVER MADE!\n\n                 Soon more major Mystic/X-Design releases\n@ENDNODE\n\n@NODE BOARDS "Mystic boards (call now)\n\n\n                               MYSTIC BOARDS\n\n\n     DiGiTAL CANDY   +1-5134713366    TRADE iN CENTER   +49-708260611\n     LAST OUTPOST    +31-72-157682    NO LiMiT          +49-46-PHREAK\n     LAST OUTPOST    +31-72-201182    CRYiNG FiELDS     +49-406452525\n     BLOOD STREET    +45-751-59284    THE ADDiCTiON     +49-610231564\n     UZi SUiCiDE     +1-2034378655    EUROPE''S HEART    +49-522122536\n     DiABOLO         +49-306218787    MAMBA             +48-22-367443  \n     THE CAVERN      +44-204382612    OUT OF SPACE      +46-620-13141  \n     CHANNEL-X       +31-229062244     \n\n\n@ENDNODE\n\n','\n',char(10)),'{"ACCESS":"20","LOCATION":"DOORS:LAST10/Last10","PRIORITY":"0","STACK":"20000","TYPE":"XIM"}','auto-added',39831,6,0,NULL,NULL,'mst_lt10','scan',1780048619);
INSERT INTO door_catalog VALUES('mst_lt12','MST-LT12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MST-LT12.LHA','LAST10','XIM','_____    ___    _____________.__. ____',NULL,NULL,'MST','_/  v  \__/ ! \  /  _____.   ._(__)/  . \ \_ _:_ ______  \/\___  \ |   | |  \_  |_/\ _/  \ /  \_  v  __   v   \|   | |    _ |   \',replace('   _____    ___    _____________.__. ____   \n _/  v  \__/ ! \  /  _____.   ._(__)/  . \  \n \_ _:_ ______  \/\___  \ |   | |  \_  |_/\ \n_/  \ /  \_  v  __   v   \|   | |    _ |   \\n\    v    /  ___/\    ___/!___! !___/__-   /\n-\___:___/___/-Ã!-\___/---------------\___/-\n-\n','\n',char(10)),'Last10.guide',replace('@DATABASE "LAST10.GUIDE"\n@WIDTH 80\n@HEIGHT 255\n\n@NODE Main "LAST 10"\n                                 \n                                MYSTIC/X-DESIGN\n                                   PRESENTS \n                                   LAST TEN\n\n                             @{"  Introduction    " link About} \n\n               @{"  Requirements    " LINK Requirements}         @{"  Installation    " LINK Installation} \n\n               @{"  Author          " LINK Author}         @{"  Bug report      " LINK bugs} \n\n               @{"  Update''s        " LINK update''s}         @{"  Greetings       " LINK GREETINGS}\n \n               @{"  Mystic/X-desig  " LINK X_DESIGN}         @{"  Mystic boards   " LINK BOARDS} \n@ENDNODE\n\n@NODE About "About LAST 10"\n\n o Last Ten is an Ami-Express tool made by HardByte/MYSTIC (/X DeSIGn).\n   \n o Last Ten enables the user to see his last ten uploads and downloads\n   from within Ami-X. (still only the node they logged in!)\n o See his status.\n o See some info and abouts!  \n o The program needs no parameters.\n\n@ENDNODE\n\n@NODE Requirements "Requirements"\n\nYou need: /X 3.x\n          OS 2.x+\n          Any Amiga Computer.\n          a UDlog in all the nodes.\n\n          Although the programming is in C, it can take a while, so a          \n          accelerator is recommended! Also, large UDLogs can slow things\n          down.\n   \n          I have made this result on my amiga with 40mhz\n          +-----------+---------------+----------------+-----------------+\n          |           | Udlog 65820b  + Udlog 131640k  | Udlog 1316400k  |             |\n          +-----------+---------------+----------------+-----------------+\n          |amiga 40mhz|  +- 1.5 sec   |  +- 3 sec      | +-1  10 sec     | \n          +-----------+--------------------------------+-----------------+ \n\n@ENDNODE\n\n@NODE Installation "Installation"\n\n   Create a icon in the BBS:COMMANDS/BBSCMD named ''LAST10.info''\n   An put the next lines in the icon. (Or copy the file ''last10.info''\n   from the lha file to bbs:commands/bbscmd/   \n        \n   ACCESS=20                        ;The level the user need to run the door.\n   LOCATION=DOORS:LAST10/LAST10     ;Location of this door.\n   MULTINODE=no                     ;If more the 1 node put ''yes''.\n   PRIORITY=0                       ;Priority 0 is good.\n   STACK=20000                      ;Stack for the programm\n   TYPE=XIM                         ;Make sure it''s XIM and not AIM (Wont work.) \n\n   Also copy the files in the fonts directorys to your fonts:\n   for a better display of the rasters around the text.\n\n@ENDNODE\n\n\n@NODE Author "About the Author and the program "\n\n      Author: HARDBYTE/MYSTIC\n         Age: 24\n     Country: HOLLAND\n     \n     Program: First ''C'' program I have made\n \n     For VIRUS checking:\n     the files must have the same sizes as given here!.\n\n     bbs:doors/last10/    last10             =    34956 bytes   \n     bbs:doors/last10/    last10.guide       =    7971  bytes\n     bbs:commands/bbscmd/ last10.info        =    1071  bytes\n     c/                   AmigaGuide         =    6656  bytes     \n     fonts/ibm/           8                  =    3252  bytes\n     fonts/ibm            ibm.font           =    264   bytes            \n     libs/                amigaguide.library =    24800 bytes\n          \n\n@ENDNODE\n\n@NODE Bugs "Bug report"\n\n   If you think you have found a bug, you can reach me at:\n\n+----------------------------------------------------------------------------+\n|LaST ouTposT     Nd#1 aMiGa Dhq! ^ SnEs Whq ÷ /X-DeSiGn EhQ +31-72157682    |\n|LaST ouTposT     Nd#2 aMiGa Dhq! ^ SnEs Whq ÷ /X-DeSiGn EhQ +31-72201182    |\n+----------------------------------------------------------------------------+\n\n   And you can leave me a message there.\n\n\n   You can also contact me for any othere reason!!. (LIKE RAYTRACING)\n@ENDNODE\n\n@NODE Update''s "Update''s "\n\n  +------------------------------------------------------------------+\n  | VERSION             DATE             BUG REPORT                  +\n  +------------------------------------------------------------------+  \n  |                                                                  |  \n  | LAST10  V0.000A     11-nov-93        No bugs! (yet!!)            |\n  |                                      Internal release            |  \n  |                                                                  |  \n  | LAST10  V0.000B     15-nov-93        First bug found             |\n  |                                      did not exit the right way  |           \n  |                                      If there was no UDlog found |  \n  |                                                                  |  \n  | LAST10  V0.000C     19-nov-93        There was no raster drawn   |  \n  |                                      around last 10 dloads       |  \n  |                                      if there was no downloading |  \n  |                                      found under the users name. |  \n  |                                                                  |\n  | LAST10  V1.0000     21-nov-93        First release               |\n  |                                                                  |\n  | LAST10  V1.0002     05-dec-93        Some improvements.          |\n  |                                      A userinfo added and infos  |\n  +------------------------------------------------------------------+\n@ENDNODE\n\n@NODE Greetings "Greetings "\n\nGreetings go to:\n\nAll Mystic members all over the world,\nS.O.B \nAnimator \nCamelot\nRemix/Crystal (what about calling sometime)\nSphinx\nAnd all others I have forgotten! \n\n\nMany thanx to: Killraven/Mystic,\n               Empire/Mystic        (also for beta testing!)\n               ByTeAnDi/Mystic  \n               TyCooN/Mystic        (also for beta testing!)\n               & Incognito/Mystic   (all mystic/X-design members also) \n               For their help with the program... :)\n\n@ENDNODE\n\n@NODE X_DESIGN "More about Mystic/X-design\n\n               Here the list of the latest Mystic/X-design releases.\n \nRelease date        Name           Discription   \n+-----------+----------------+----------------------------------------------+           \n| 07-18-93  |  CD-STA01.LHA  |  CDstatus 0.1                                | \n| 07-18-93  |  EMP-UA10.LHA  |  Create Bulls Conference Access.             |\n| 09-30-93  |  MSTWHO.LHA    |  The ulimative who search for quite node     |\n| 10-08-93  |  SYSDLV1.LHA   |  sysopdownload bug fixedpack dirs,search for |\n|           |                |  files/pathes via tab                        | \n| 10-16-93  |  MST-CS2O.LHA  |  ConfScan v2.0                               |\n| 10-16-93  |  MST-NS02.LHA  |  NodeStat v0.2 by KiLLraVeN/MYSTiC (/X 3.x)  |\n|           |                |  Show Statistics About The UDLog By The Day  |\n| 10-17-93  |  EMP-JC32.LHA  |  AE DOOR: JoinCnf V3.2 /X 3.11+ Update       |\n| 10-11-93  |  NFILES21.LHA  |  NewFiles V2.1                               |\n+-----------+----------------+----------------------------------------------+  \n\n  AND MANY MORE, CHECK LOST OUTPOST FOR ALL THE MYSTIC TOOLS EVER MADE!!\n\n                 Soon more major Mystic/X-design releases\n@ENDNODE\n\n@NODE BOARDS "Mystic boards (Call now)\n\n\n                               MYSTIC BOARDS\n\n\n.-DiGiTAL CANDY---[WHQ! 4]-+1-513-ELITE!-UZi SUiCiDE--[USHQ 3]-+1-2034378655-.\n| MYSTiCAL CHAOS  [UHQ! 1] +49-TOPSECRET STATiC CHAOS [DKHQ 2] +45-864-37190 |\n| LAST OUTPOST    [EHQ! 2] +31-721-57682 DiABOLO      [GHQ! 3] +49-306218787 |\n| EUROPE''S HEART  [MHQ! 4] +49-522-ELITE THE TOWER    [UKHQ 1] +44-204382612 |\n| TOWER OF SORCERY[USHQ 3] +1-6142621230 OUT OF SPACE [SHQ! 1] +46-620-13141 |\n| BLOOD STREET    [SCHQ 2] +45-751-59284 NO LiMiT     [PHHQ 1] +49-46-PHREAK |\n| CRYiNG FiELDS   [GHQ! 2] +49-406452525 CHANNEL-X    [DIST 2] +31-229062244 |\n`----------------------------------------------------------------------------''\n                 TRADE iN CENTER [IBM EHQ 3] +49-708260611\n\n\n\n@ENDNODE\n','\n',char(10)),'{"ACCESS":"20","LOCATION":"DOORS:LAST10/LAST10","PRIORITY":"0","STACK":"20000","TYPE":"XIM"}',NULL,39265,3,0,NULL,NULL,'mst_lt12_last10','scan',1780048619);
INSERT INTO door_catalog VALUES('mst_mt11','MST_MT11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MST_MT11.LHA','*','XIM','MultiTop.000',NULL,'BOBO......|','MST','.---/    \ \/ / __/_  __/ / __/------------. |--/ / / /\  /\  /-/ /-/ / /---Bobo--------| |--\/ / /-/ /\  /-/ /-/ /\ \----Mystic-----|',replace('     ______  __________________\n.---/    \ \/ / __/_  __/ / __/------------.\n|--/ / / /\  /\  /-/ /-/ / /---Bobo--------|\n|--\/ / /-/ /\  /-/ /-/ /\ \----Mystic-----|\n|---\/\/--\/--\/--\/--\/--\/-----/X-Design-|\n|......MultiTop (Version 1.1) by BOBO......|\n|.The replacement for all your bullmakers!.|\n|..Features: 7 Different bulletins, Fast!..|\n`------------------------------------------''\n','\n',char(10)),'Multitop.Doc',replace('   ____ _________________   _______________________ _ _______________\n --\__ Y ____ __________/---\_____ ___ ______ ____// \\__ ________  /----\n    / \ / \/_____\/   \  /X  /   Y \/  _)__/_____\/   \/  l_ \/  Y  \ \n   /   Y   \    ! \    \    /    !  \      \    ! \    \      \  |   \\n --\___|_  /____  /__  /----\_____  /____  /____  /__  /____  /__|_  /---\n         \/     \/   \/           \/     \/     \/   \/     \/   ML\/\n          W·E  P·R·O·D·U·C·E  F·O·R  Y·O·U·R  C·O·M·F·O·R·T !\n\n                    PRESENTS A NEW MAJOR PRODUCT >:\n\n          MultiTop v1.1 (Util) for Amiexpress BBS (Release 1)\n          ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n          Auther: BOBO/MYSTiC   Favourite Board: The East BBS\n          Door Requirements: AmigaDOS2.0 & Amiexpress 2.(33?)\n\n                 This documentation is written by BOBO!\n\n  Program history and example outputs/scripts come in seperate files with\n                          the release archive.\n\n\n                     Notable features on Multi Top...\n                     ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n        * Amiexpress compatible with all amiexpress versions above 2.33.\n        * Special Optimized Versions for all CPU types (000/010/020/030/040)\n        * Makes 7 different bulletins.\n        * Very Fast!\n        * Lot''s of secuirty checks. Nothing can go wrong!\n\n       MultiTop have been tested on the most setups from 2.33 to 3.36.\n    If you have any problems at your board, call me or leave me a message\n\n         Suggestions, Ideas and bug reports are welcome and wanted!\n\n\n        The complete release Archive (MST-MT11.LHA) should contents\n        ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nMultitop.000            19748 bytes   All-processors version.\nMultitop.020            19744 bytes   Optimized version for 020 or better\nMultitop.Doc             8993 bytes   This document file.\nMultitop.Update          2121 bytes   Update file.\nExamples/Multitop0.txt   2091 bytes   Multitop Output Example (Mode 0).\nExamples/Multitop1.txt   2091 bytes   Multitop Output Example (Mode 1).\nExamples/Multitop2.txt   2091 bytes   Multitop Output Example (Mode 2).\nExamples/Multitop3.txt   2091 bytes   Multitop Output Example (Mode 3).\nExamples/Multitop4.txt   2091 bytes   Multitop Output Example (Mode 4).\nExamples/Multitop5.txt   2091 bytes   Multitop Output Example (Mode 5).\nExamples/Multitop6.txt   2091 bytes   Multitop Output Example (Mode 6).\nExamples/Multitop7.txt   2091 bytes   Multitop Output Example (Mode 7).\n\n\n                         BackGround & Purpose\n                         ~~~~~~~~~~~~~~~~~~~~\nI was sick and tired of having alot of different utils to do my bulletins\n(Some of them had really bad design too), so i started coding this nice and\neasy util. This tool will replace the most of your utils. It will create your:\n\nTop Uploaders (In Bytes)\nTop Uploaders (In Files)\nTop Downloaders (In Bytes)\nTop Downloaders (In Files)\nTop Message Writers\nTop Calls\nTop Upload CPS\nTop Download CPS\n\n\n                   The syntax of Multitop (How to use)\n                   ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                The SYNTAX for multitop is the following:\n\n  MULTITOP <userdata> <outputfile> <mode> <# users> [<userkeys>]\n\n     <userdata>   -  The FULL path to your USER.DATA file.\n     <outputfile> -  The FULL path to outputfile. You may enter a STAR (*)\n                     to send the output directly to screen.\n     <mode>       -  7 different modes are availible for the moment. They are:\n\n                     MODE (0) - Top Uploaders (Bytes)\n                     MODE (1) - Top Downloaders (Bytes)\n                     MODE (2) - Top Uploaders (Files)\n                     MODE (3) - Top Downloaders (Files)\n                     MODE (4) - Top Message Writers\n                     MODE (5) - Top Calls\n                     MODE (6) - Top Upload CPS\n                     MODE (7) - Top Download CPS\n\n     <# users>    -  How many users you want in the output. The output have\n                     two colums, so if you enter 30 users, it will be 15\n                     lines.\n\n     [<userkeys>] -  The FULL path to your USER.KEYS file. This is ONLY needed\n                     for MODE 6 & 7.\n\n          Example >: MULTITOP BBS:USER.DATA BBS:BULL.TXT 0 30\n                     - This would output the 30 top uploaders (bytes)\n                       to BBS:Bull.txt.\n\n                  >: MULTITOP BBS:USER.DATA * 6 30 BBS:USER.KEYS\n                     - This would output the 30 top upload CPS\n                       directly to screen.\n\n                  >: MULTITOP BBS:USER.DATA BBS:BULL.TXT 5 50\n                     - This would output the 50 top callers\n                       to BBS:Bull.txt.\n\n\n                        Use a Header/Tailer\n                        ~~~~~~~~~~~~~~~~~~~\nMultitop will always search for a headerfile/tailerfile ..\n\n· S:Multitop.Header - for add before the output, and\n· S:Multitop.Tailer - for add after the output.\n\nIf no headerfile is found, a clear-screen (CTRL-L) is added so it displays\nquicker/nicer.\n\nNOTE: When you are using a own headerfile, don''t forget the clear-screen at\n      the top!\n\n\n                            Contact me\n                            ~~~~~~~~~~\nTo contact me, or to contact Mystic/X-Design, or if you have any suggestions\nor bug reports or anything else, call my board or Mystic /X design WHQ and\nleave me a message.\n\nBoardname             Phonenumber         Cputype        Sysop         Nodes\n==============================================================================\nThe East BBS #1 (SHQ) +46-8940614         68030/50Mhz    BOBO/MYSTIC   3 Nodes\nThe East BBS #2 (SHQ) +46-8940615         68030/50Mhz    BOBO/MYSTIC   3 Nodes\nThe East BBS #3 (SHQ) +46-8940919         68030/50Mhz    BOBO/MYSTIC   3 Nodes\nDiabolo #1 (WHQ)      +49-306218787       68030/25Mhz    ANDY/MYSTIC   3 Nodes\nDiabolo #2 (WHQ)      +49-306221994       68030/25Mhz    ANDY/MYSTIC   3 Nodes\nDiabolo #3 (WHQ)      +49-306212312       68030/25Mhz    ANDY/MYSTIC   3 Nodes\n\n                             Greetings\n                             ~~~~~~~~~\nGreetings to: Looby, Nightshade, Pacific/2000 AD, Cruger/Skidrow, Dee/Delight\n              Agressor, Reactor/MST, Rhys/FLT, Screwball, Distler\n\nMany thanx to Looby, your SORT routine is the greatest!\n\nMany thanx to Byteandi/Mystic and Remo/Mystic for all help and support.\n\nAnd many many thanx to all my beta testers for bug-reports, suggestions and\nhints & tips to improve this tool.\n\n\n                    All members of (Mystic/X-Design)\n                    ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                        ______  __________________\n.----------------+-----/    \ \/ / __/_  __/ / __/----------+----------------.\n|                |----/ / / /\  /\  /-/ /-/ / /----[ /X ]---|                |\n|       /\    /\ |-EmP\/ / /-/ /\  /-/ /-/ /\ \--[ DESiGN ]-|       /\    /\ |\n|      /C \  /N/ +-----\/\/--\/--\/--\/--\/--\/-------------+      /C \  /N/ |\n|     /i/\ \/G/  |                                          |     /i/\ \/G/  |\n|    /T/  \ i/   |                                          |    /T/  \ i/   |\n|   /S/   /S \   |   EMPiRE   -   BYTEANDi   -  CRACKDOWN   |   /S/   /S \   |\n|  /Y/   /E/\ \  |   TYCOON   -   KiLLRAVEN  -   SiEGEL     |  /Y/   /E/\ \  |\n| /M/   /D/  \ \ |   FUZZY    -      SPY     -  INCOGNiTO   | /M/   /D/  \ \ |\n| \/    \/    \/ |   RE/Y\o   -     BOBO!    -   HARDBYTE   | \/    \/    \/ |\n|                |                                          |                |\n`----------------+----------[  MYSTiC /X DESiGN  ]----------+----------------''\n\n----------------------------------------------------------------------------\n\n  ____/\____/\ ______/\_____  ___/\_______/\_______/\_______/\_____\n -\____ ____  Y  ____ _____/ML\__ ___________  ____ _________ ____/------\n    /    \/___|_  \/  __)___   /  __)___/___Y_  \/______ \/    \\n   /      \\____   \  |     \ /   |     \\____   \     |  \     \ B.B.S.\n   \      /   T    /  !     / \   !     /   T    /     !  /     /\n ---\____/\___|___/\_______/   \_______/\___|___/\_______/\____/---------\n.---------v-----------------------------------------------v-------------.\n| NODE (1):+46-8-940614 - NODE (2) +46-8-940615 - NODE (3).+46-8-940919 |\n|         .                                               :             |\n|  ...:.:..:..  MyStIc: FuN & FriEnDshIp! - NoThInG ElSe! ..:..:.:...   |\n`-v-----------------------v-------------------------------------------v-''\n  :____ _________________ : _______________________ _ _______________ :\n -.\__ Y ____ __________/-.-\_____ ___ ______ ____// \\__ ________  /-.--\n  . / \ / \/_____\/   \  /X  /   Y \/  _)__/_____\/   \/  l_ \/  Y  \ .\n   /   Y   \    ! \    \    /    !  \      \    ! \    \      \  |   \\n --\___|_  /____  /__  /----\_____  /____  /____  /__  /____  /__|_  /---\n         \/     \/   \/           \/     \/     \/   \/     \/   ML\/\n          W·E  P·R·O·D·U·C·E  F·O·R  Y·O·U·R  C·O·M·F·O·R·T !\n\n','\n',char(10)),NULL,'auto-added',40731,6,0,NULL,NULL,'mst_mt11','scan',1780048628);
INSERT INTO door_catalog VALUES('mst_mt20','MST-MT20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MST-MT20.LHA','MultiTop','XIM','MultiTop',NULL,NULL,'MST','\   /\ | /\ __/\ . /\ |\ . /| bObO/mYStiC | / V \/_. \/_.¬\/_| \/ |/ |_\| ~~~~~~~~~~~ | /  |  \¬|  \¬¦  \¬|  \ |  ¦ ¬\  PRESENTS:  |',replace(' _/\___/¦___/\___/\___/¦_/\__.-------------.\n \   /\ | /\ __/\ . /\ |\ . /| bObO/mYStiC |\n / V \/_. \/_.¬\/_| \/ |/ |_\| ~~~~~~~~~~~ |\n/  |  \¬|  \¬¦  \¬|  \ |  ¦ ¬\  PRESENTS:  |\n\__¦  /__  /__  / ¦__/_¦___  /  ~~~~~~~~~  |\n.---\/---\/---\/-/X-pOwEr!-\/^-------------|\n|   MultiTop (Version 2.0)  [RELEASE 2]    |\n| The BEST Top Utility ever written for /X |\n|  Make your OWN DESIGN (16 designs incl)  |\n|        ! WORTH TAKING A LOOK AT !        |\n`------------------------------------------''\n','\n',char(10)),'MultiTop.doc',replace('\n---------------------------------------------------------------------------\n            MultiTop v2.0 [RELEASE 2] - Public Release Version!\n                     All Coding by Bobo (Mystic/X-Power)\n---------------------------------------------------------------------------\n\nHi again, and welcome to another fine product from Mystic-Amiexpress.  Here\nit is - the new update  of MultiTop.  It have been completly rewritten, and\ntoday it''s the DAMN best top utility available for amiexpress bbs.  It does\nnot only allow you to make the most of your bulletins,  but also with  your\nown created design and much much more! (Continue reading)\n\nSome notable features:\n~~~~~~~~~~~~~~~~~~~~~~\n* MultiTop have a nice built in config program where you can configure your\n  personal settings.\n* MultiTop lets you make your own design.\n* MultiTop generates your top uploaders/downloaders (bytes and files),\n  top callers and top message writers.\n* MultiTop have been tested and works 100% on multinode systems.\n* MultiTop is written entirely in C for fast code.\n* MultiTop comes in 000 & 030 code to get the maximum speed on your system.\n  (please note that the 030 version will also work on 020 (a1200))\n* MultiTop have everything builtin. No need to create cfgs and such things,\n  you control everything in the cfg program.\n* Each design file can have its own personal configuration.\n* MultiTop can generate bulletins using your conference databases.\n  (You must have Conference Accounting activated to use this.)\n* MultiTop allow wildcards at the design argument.  This means that you can\n  have randomly top bulletins.\n* MultiTop can exclude users you don''t want to have listed.\n\nMultiTop is your final replacement for all your top makers. It doesn''t only\nallow you to make your top uploaders bulletin, but also top callers and top\nmessage writers and much much more.\n\nAs you all probably know, there are perhaps fifty other top uploader  utils\navailable for amiexpress today, and all of them with different designs.  It\nis always hard to choose between them,  becouse you really don''t  know what\ndesign you want to use.  This problem is solved now,  becouse MultiTop lets\nyou make your own design!\n\nI hope that some of you design & ascii makers will create some nice designs\nfor  this util  in the future.  This way there is no need to any other  top\nutility becouse all of them really works in the same way but with different\ndesigns.  HERE YOU GOT THE CODE - MAKE THE DESIGN!\n\n\n--------------------------------------------------( Usage and Examples )---\n\nThe usage of MultiTop is very simple, and it is the only thing you have  to\n"learn", if you ofcouse don''t want to make your own designs!\n\nUsage: MULTITOP <Design> <Output> [<Userdata>] [CONFDB <confdb>] [NOANSI]\n\n<Design> : Full path to your designfile.  You may use AMIGADOS wildcards to\n           use random design files. (ie #?)\n\n<Output> : Full path to your outputfile.  You may use a star (*) for output\n           directly to screen. (ie *)\n\n[<Userdata>] : Full path to your userdata.  (BBS:User.Data is default)\n\n[CONFDB <file>] : If you have conference accounting activated,  you can use\n                  conferences database to make the bulletins. <file> is the\n                  full path to your conf.db file.\n\n[NOANSI] : Write a NO ANSI output. (Ansi is default)\n\n\nSome examples:\n~~~~~~~~~~~~~~\nMULTITOP BBS:Designs/MTopULBytes#?.dsg BBS:Bull.txt SYS:User.Data NOANSI\n--- Generate a random TOP UPLOADERS bulletin using SYS:User.data with\n    NOANSI to BBS:Bull.txt\n\nMULTITOP BBS:Designs/MTopULBytes#?.dsg BBS:Bull.txt CONFDB BBS:Conf2/Conf.db\n--- Generate a random TOP UPLOADERS bulletin from conference 2 to\n    BBS:Bull.txt\n\nMULTITOP BBS:Designs/MTopMsgs1.dsg * NOANSI\n--- Generate a TOP MESSAGES bulletin (design 1) with NOANSI to screen.\n\n\n----------------------------------------------( Design files - General )---\n\nAs you probably already figured out,  MultiTop needs a design file to work.\nA designfile is a normal textfile (ASCII)  created in a normal  text-editor\nwith some keywords in it. The designfiles can also have its personal config\nin it. (explained later)\n\nPLEASE NOTE\n\nYou don''t have to make your own design if you don''t have time or want  too.\nThere are many nice designs delivered with this archive that''s free to use,\nso if you aren''t that good at painting etc, just use them. (This means that\nyou DONT have to read the chapter about the design files)\n\n\n----------------------------------( Design files - Keywords & Examples )---\n\nLIST OF AVAILABLE KEYWORDS\n\nUSERINFO               BOARDINFO                   BOARDINFO (CONTINUATION)\n~~~~~~~~               ~~~~~~~~~                   ~~~~~~~~~\nUN=UserName            TC=Total Calls              LT=Last Updated (Time)\nLT=Location            TM=Total Msgs               LD=Last Updated (Date)\nUB=Uploaded Bytes      UB=Total Uploaded Bytes     VT=Version Text\nUK=Uploaded K          UK=Total Uploaded K\nUM=Uploaded Megs       UM=Total Uploaded Megs\nUF=Uploaded Files      UF=Total Uploaded Files\nDB=Downloaded Bytes    DB=Total Downloaded Bytes\nDK=Downloaded K        DK=Total Downloaded K\nDM=Downloaded Megs     DM=Total Downloaded Megs\nDF=Downloaded Files    DF=Total Downloaded Files\nMS=Messages            SC=System Calls\nCS=Calls               TU=Total Active Users\nST=Status              RG=Registered to\n\nNOTE: The keyword VT *MUST* be used, or no output will be written.\n      It will insert a string (MultiTop v2.0) on 14 chars.\n\n\nUSERINFO format:\n%<pos><center><length><keyword>  Example: %01-10UN\n|  |     |       |       |\n|  |     |       |       |> Userinfo Keyword\n|  |     |       |--------> Number of chars to display of keyword\n|  |     |----------------> Minus (-) for left, dot (.) for right\n|  |----------------------> User number from top\n|-------------------------> Keyword Identifer\n\nBOARDINFO format:\n%<center><length><keyword>       Example: %-10VT\n|   |       |       |\n|   |       |       |-----> Boardinfo Keyword\n|   |       |-------------> Number of chars to display of keyword\n|   |---------------------> Minus (-) for left, dot (.) for right\n|-------------------------> Keyword Identifer\n\nExamples\n~~~~~~~~\nUsername: [%01-10UN]  Location: [%01.10LT]  Bytes: [%01-10UB]\n\nThe above string would be translated to:\nUsername: [bObO/mYSTi]  Location: [    mYStiC]  Bytes: [1,123,123 ]\n\n\nTotal uploaded bytes: [%-10UB]  files: [%.00UF]\n\nThe above string would be translated to:\nTotal uploaded bytes: [1,123,123]  files: [1,123]\n\n\nI recommend you to take a look  at the included example design-files  while\nreading this chapter to get hold of how it works.  I''m really sorry for not\nwriting more information about this, but i hadn''t got enough time. MultiTop\nhave been lying here for almost 3 weeks finished and ready, but the doc was\nmissing.  This weekend i decided that it MUST be released, therefor i wrote\nthis doc in a hurry.  This means that there are probably some lame spelling\nmistakes and/or things missing in the document etc.  Once again i am sorry,\nbut i hope you are smart enough to understand the most of it.\n\n\n------------------------------------( Design files - Personal Settings )---\n\nThe design file(s) may have its own config in it. All of them are optional,\nbut if you want to make an other output then top ulbytes,  you need to  use\nthem.  Available commands/settings are:\n\nSEPARATOR=DOT    - Use DOT (.) separator\n          COMMA  - Use COMMA (,) separator\n          NONE   - Donot use any separator\n\nSORT=UPLOADEDBYTES    - Sort userlist by Uploaded Bytes (DEFAULT)\n     UPLOADEDFILES    - Sort userlist by Uploaded Bytes\n     DOWNLOADEDBYTES  - Sort userlist by Downloaded Bytes\n     DOWNLOADEDFILES  - Sort userlist by Downloaded Bytes\n     CALLS            - Sort userlist by Calls\n     MESSAGES         - Sort userlist by Messages\n\nAll lines in the designfile starting with ''@'' will *NOT* be written in  the\noutput. @ followed by an option will active it. You may also use @ when you\nwrite comments in the designfile.\n\n\nEXAMPLES\n~~~~~~~~\n@ This is a comment line\n\n@SEPARATOR=DOT                    I can write whatever i want out here!\n\n@SORT=DOWNLOADEDBYTES             I can write whatever i want out here!\n\n\nFor more help and examples, take a look at the included designfiles.\n\n\n------------------------------------------------------( Config program )---\n\nMultiTop has a built in config program where you configure MultiTop. I wont\ngo into details what every option do, becouse you''ll see and find out!\n\nTo start the config program,  write "MULTITOP CFG" at the prompt,  or start\nMultiTop from workbench.\n\n\n-------------------------------------------------------------( The End )---\n\nThis program was written and developed (c)1993-1995 Bobo/Mystic using SAS/C\n(c) SAS Institute Inc.  You are free to use this util as long as you  want,\nbut the  author is not responsible for any damages caused by this util.\n\nIf you want to contact me, feel free to call my board.\n\nThe East BBS: +46-8940614  [28.8 DS]      Logon as: GUEST\n              +46-8940615  [28.8 DS]      Password: PASSWORD\n              +46-8940919  [28.8 DS]\nLast Outpost: +31-72157682 [28.8 DS]\n              +31-72201182 [28.8 DS]\n\n\nLAST NOTE\n~~~~~~~~~\nEveryone waiting for an update of WHAT (AEHydra) and FileDescription - just\nbe patient.  The update is coming any time now.  The new WHAT will ofcourse\nsupport AEHydra and will show CPS rates etc!.  The new FILEDESCRIPTION will\nbe better then ever - Just wait and see!\n','\n',char(10)),NULL,'auto-added',73868,2,1,'MTOP','Doors/multitop','mst_mt20','scan',1780048619);
INSERT INTO door_catalog VALUES('mst_mt21','MST-MT21.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MST-MT21.LHA','MultiTop','XIM','IconEdit',NULL,NULL,'MST','\   /\ | /\ __/\ . /\ |\ . /| bObO/mYStiC | / V \/_. \/_.¬\/_| \/ |/ |_\| ~~~~~~~~~~~ | /  |  \¬|  \¬¦  \¬|  \ |  ¦ ¬\  PRESENTS:  |',replace(' _/\___/¦___/\___/\___/¦_/\__.-------------.\n \   /\ | /\ __/\ . /\ |\ . /| bObO/mYStiC |\n / V \/_. \/_.¬\/_| \/ |/ |_\| ~~~~~~~~~~~ |\n/  |  \¬|  \¬¦  \¬|  \ |  ¦ ¬\  PRESENTS:  |\n\__¦  /__  /__  / ¦__/_¦___  /  ~~~~~~~~~  |\n.---\/---\/---\/-/X-pOwEr!-\/^-------------|\n|   MultiTop (Version 2.1)  [RELEASE 3]    |\n| The BEST Top Utility ever written for /X |\n|  Make your OWN DESIGN (20 designs incl)  |\n| HERE YOU GOT THE CODE - MAKE THE DESIGN! |\n`------------------------------------------''\n','\n',char(10)),'MultiTop.guide',replace('@DATABASE "MultiTop.Guide"\n@REMARK  .-----------------------------------------------------------.\n@REMARK  | This document should be read with AmigaGuide or MultiView |\n@REMARK  `-----------------------------------------------------------''\n@REMARK  $VER: MultiTop 2.1\n@INDEX MAIN\n@WIDTH 80\n@NODE MAIN "MultiTop v2.1 [RELEASE 3] - Public Release Version!"\n                         MultiTop v2.1 [RELEASE 3]\n                          Public Release Version!\n\n                         All Coding by @{"BOBO/MYSTIC" link Contact}\n\n                           Guide by KILLRAVEN/MST\n                              Logo by BARK/MST\n\n                 ... another fine MYSTiC /X production ...\n\n                       @{" Introduction & New Features " link Introduction}\n                       @{"      Usage & Examples       " link Usage}\n\n                       @{" General Info Designer Files " link DesignGeneral }\n                       @{" Keywords for Designer Files " link DesignKeywords }\n                       @{" Configuring  Designer Files " link DesignPersonalSettings }\n\n                       @{"    How to contact me...     " link Contact}\n@ENDNODE\n\n@NODE Introduction "Introduction & New Features in v2.1 - © 1995 bObO/MST"\n\n   Hi  again, and welcome to another fine product from Mystic-Amiexpress.\n   Here  it  is  -  the  new  update  of MultiTop.  It has been completly\n   rewritten,  and  today  it''s  the  DAMN best top utility available for\n   Ami-Express.   It  does  not  only  allow you to make the most of your\n   bulletins, but also with your own created design and much much more!\n\n   New in version 2.1:\n   ~~~~~~~~~~~~~~~~~~~\n   * MultiTop can now generate top upload/download cps rates\n   * MultiTop now using a new load/sort routine =50% faster!\n   * New config program with nicer design and easier to use.\n   * Optimized the code =faster executable!\n\n   Some notable features:\n   ~~~~~~~~~~~~~~~~~~~~~~\n   * MultiTop  has  got a nice built-in config program that allows you to\n     configure your personal settings.\n   * MultiTop lets you use your own design.\n   * MultiTop generates your top uploaders/downloaders (bytes and files),\n     top callers,  top message writers and top upload/download cps rates.\n   * MultiTop has been tested on and works 100% on multinode systems.\n   * MultiTop is written entirely in C for fast code.\n   * MultiTop  comes  in  000 & 0x0 code to get the maximum speed on your\n     system.\n     Please note that the 030 version will also work on A1200s & A4000s.\n   * MultiTop has got everything built-in. No need to create cfgs and\n     such things, you control everything in the config editor.\n   * Each design file can have its own personal configuration.\n   * MultiTop can generate bulletins using your conference databases.\n     (You must have Conference Accounting activated to use this.)\n   * MultiTop  allow wildcards at the design argument.  This means that\n     you can have MultiTop pick random top bulletins.\n   * MultiTop can exclude users you don''t want to have listed.\n\n   MultiTop  is  your  final  replacement  for  all  your top makers.  It\n   doesn''t  only  allow you to make your top uploaders bulletin, but also\n   top callers and top message writers and much much more.\n\n   As  you  all probably know, there are perhaps fifty other top uploader\n   utils  available for Ami-Express today, and all of them with different\n   designs.  It is always hard to choose between them, because you really\n   don''t  know  what design you want to use.  This problem is solved now,\n   because MultiTop lets you use your own created design!\n\n   I  hope  that  some  of  you  ascii/ansi  makers will create some nice\n   designs for this util in the future.  This way there is no need to any\n   other  top utility because all of them really work in the same way but\n   with different designs.\n\n             I HAVE CREATED THE CODE, NOW YOU MAKE THE DESIGN!\n\n                                                            -bObO/mYSTiC-\n\n   ----------------------------------------------------------------------\n\n                             LEGAL MUMBO JUMBO\n\n   This  program was written and developed (c)1993-1995 Bobo/Mystic using\n   SAS/C (c) SAS Institute Inc.  You are free to use this util as long as\n   you  want, but the author is not responsible for any damages caused by\n   this util.\n\n   ----------------------------------------------------------------------\n\n@ENDNODE\n\n@NODE Usage "Usage And Examples - © 1995 by bObO/MYSTiC"\n\n   The  usage  of  MultiTop  is very simple, and it is the only thing you\n   have to "learn", if you don''t want to make your own designs!\n\n   Usage: MULTITOP <designfile> <outputfile> [<userdata>] [UKEYS <file>]\n                   [CONFDB <file>] [NOANSI]\n\n   <designfile> : Full path to your designfile. You may use AMIGADOS\n                  wildcards to use random design files. (ie #?)\n\n   <outputfile> : Full path to your outputfile. You may use an asterisk\n                  for output directly to screen. (i.e. "*")\n\n   [<userdata>] : Full path to your userdata.  (BBS:User.data is default)\n\n   [UKEYS <file>]  : The  Userkeys file  is  ONLY  used if the designfile\n                     need  cps  rates  info.  <file>  is the full path to\n                     your userkeys file. (BBS:User.keys is default).\n\n   [CONFDB <file>] : If  you  have  conference accounting activated,  you\n                     can  use  conference database to make the bulletins.\n                     <file>  is  the  full  path to your conf.db file for\n                     that conference.\n\n   [NOANSI] : Write a NO ANSI output. (Ansi is default)\n\n\n   Some examples:\n   ~~~~~~~~~~~~~~\n   MULTITOP Designs/MTopULBytes#?.dsg BBS:Bull.txt SYS:User.data NOANSI\n   --- Generate a random TOP UPLOADERS bulletin using SYS:User.data with\n       NOANSI to BBS:Bull.txt\n\n   MULTITOP Designs/MTopULBytes#?.dsg BBS:Bull.txt CONFDB BBS:Conf2/Conf.db\n   --- Generate a random TOP UPLOADERS bulletin from conference 2 to\n       BBS:Bull.txt\n\n   MULTITOP Designs/MTopDLBytes#?.dsg BBS:Bull.txt UKEYS SYS:User.keys\n   --- Generate a random TOP DOWNLOADERS bulletin using a external Userkeys\n       to BBS:Bull.txt\n\n   MULTITOP Designs/MTopMsgs1.dsg * NOANSI\n   --- Generate a TOP MESSAGES bulletin (design 1) with NOANSI directly to\n       screen.\n@ENDNODE\n\n@NODE DesignGeneral "General Info about the Design files - © 1995 bObO/MST"\n\n   As  you  probably already figured out, MultiTop needs a design file to\n   work.   A  designfile is a normal textfile (ASCII) created in a normal\n   text-editor  with  some keywords in it.  The designfiles can also have\n   its personal config in it.  (explained later)\n\n   PLEASE NOTE\n\n   You  don''t have to make your own design if you don''t have time or want\n   to.   There are many nice designs delivered with this archive that you\n   can  freely  use, so if you aren''t that good at painting etc, just use\n   them.   (This  means  that  you  DON''T have to read the part about the\n   design files)\n@ENDNODE\n\n@NODE DesignKeywords "How to create your own files - © 1995 bObO/MST"\n\n   I  recommend  you  to take a look at the included example design-files\n   while reading this chapter to understand how it works.\n\n\n   LIST OF AVAILABLE KEYWORDS\n\n   USERINFO               BOARDINFO\n   ~~~~~~~~               ~~~~~~~~~\n   UN=UserName            TC=Total Calls\n   LT=Location            TM=Total Msgs\n   UB=Uploaded Bytes      UB=Total Uploaded Bytes\n   UK=Uploaded K          UK=Total Uploaded K\n   UM=Uploaded Megs       UM=Total Uploaded Megs\n   UF=Uploaded Files      UF=Total Uploaded Files\n   DB=Downloaded Bytes    DB=Total Downloaded Bytes\n   DK=Downloaded K        DK=Total Downloaded K\n   DM=Downloaded Megs     DM=Total Downloaded Megs\n   DF=Downloaded Files    DF=Total Downloaded Files\n   UC=Upload CPS Record   SC=System Calls\n   DC=Download CPS Record TU=Total Active Users\n   MS=Messages            LT=Last Updated (Time)\n   CS=Calls               LD=Last Updated (Date)\n   ST=Status              RG=Register Information\n   ---------------------- VT=Version Text\n\n   NOTE: The keyword VT *MUST* be used, or no output will be written.\n         It will insert a string (MultiTop v2.1) of 14 chars long.\n\n\n   USERINFO format:\n   %<pos><center><length><keyword>  Example: %01-10UN\n   |  |     |       |       |\n   |  |     |       |       |> Userinfo Keyword\n   |  |     |       |--------> Number of chars to display of keyword\n   |  |     |----------------> Minus (-) for left, dot (.) for right\n   |  |----------------------> User number from top\n   |-------------------------> Keyword Identifer\n\n   BOARDINFO format:\n   %<center><length><keyword>       Example: %-10VT\n   |   |       |       |\n   |   |       |       |-----> Boardinfo Keyword\n   |   |       |-------------> Number of chars to display of keyword\n   |   |---------------------> Minus (-) for left, dot (.) for right\n   |-------------------------> Keyword Identifer\n\n   Examples\n   ~~~~~~~~\n   Username: [%01-10UN]  Location: [%01.10LT]  Bytes: [%01-10UB]\n\n   The above string would be translated to:\n   Username: [bObO/mYSTi]  Location: [    mYStiC]  Bytes: [1,123,123 ]\n\n\n   Total uploaded bytes: [%-10UB]  files: [%.00UF]\n\n   The above string would be translated to:\n   Total uploaded bytes: [1,123,123]  files: [1,123]\n\n                                PLEASE NOTE!\n\n   All  I  want from you who make the design, is NOT to remove or somehow\n   hide  the  VT-keyword.   I  KNOW there is quite an easy way to hide it\n   with esc- chars (i.e.  set the black color before the keyword) or such\n   things, but PLEASE show me some respect for my work and leave it as it\n   should be - thank you.\n\n       (THIS IS ALL I ASK FROM YOU. YOU DON''T HAVE TO INCLUDE MY NAME OR\n        OTHER THINGS, THE VT-KEYWORD IS ENOUGH)\n\n   See also: @{"Configuring Designer Files" link DesignPersonalSettings}\n\n@ENDNODE\n\n@NODE DesignPersonalSettings "Personal Settings in Designer Files - © 1995 bObO/MST"\n\n   The  design  file(s)  may  have  its  own  config  in  it.  All of the\n   following  keywords  for setting options are optional, but if you want\n   to  make  an  other  output  then  top  ulbytes, you need to use them.\n   Available commands/settings are:\n\n   SEPARATOR=DOT    - Use DOT (.) separator\n             COMMA  - Use COMMA (,) separator\n             NONE   - Donot use any separator\n\n   READUSERKEYS - Read userkeys when using this design - to be able to use\n                  cps rates information.\n\n   SORT=UPLOADEDBYTES    - Sort userlist by Uploaded Bytes (DEFAULT)\n        UPLOADEDFILES    - Sort userlist by Uploaded Files\n        DOWNLOADEDBYTES  - Sort userlist by Downloaded Bytes\n        DOWNLOADEDFILES  - Sort userlist by Downloaded Files\n        CALLS            - Sort userlist by Calls\n        MESSAGES         - Sort userlist by Messages\n        UPLOADCPS        - Sort userlist by Upload CPS\n        DOWNLOADCPS      - Sort userlist by Download CPS\n\n   All lines in the designfile starting with ''@'' will *NOT* be written in\n   the output. @ followed by an option will activate it. You may also use\n   @ to write comments in the designfile.\n\n\n   EXAMPLES\n   ~~~~~~~~\n   @ This is a comment line\n\n   @SEPARATOR=DOT                   I can write whatever i want out here!\n\n   @SORT=DOWNLOADEDBYTES            I can write whatever i want out here!\n\n\n   For more help and examples, take a look at the included designfiles.\n@ENDNODE\n\n@NODE ConfigProgram "Config Program - © 1995 bObO/MST"\n\n   MultiTop  has  a built-in config program where you configure MultiTop.\n   I  wont  go  into  details  what  every option does, because it''s very\n   intuitive to use.  Go and see.\n\n   To  start  the  config program, write "MULTITOP CFG" at the prompt, or\n   start MultiTop from workbench.\n\n   NOTE: If you don''t have your userdata located in the default path\n         (BBS:), you may enter "MULTITOP CFG <userdata>"\n\n     IE: MULTITOP CFG SYS:USER.DATA\n@ENDNODE\n\n@NODE Contact "How to reach ... "\n\n   The  easiest  way to contact me, is to write me a message on internet:\n\n                              [email removed]\n\n   You may also call any of these MYSTiC boards and leave me a messgae:\n\n   The East BBS: +46-8940614  [28.8 DS]      Logon as: GUEST\n                 +46-8940615  [28.8 DS]      Password: GUEST\n                 +46-8940919  [28.8 DS]      Mail to : bObO/mYSTiC\n   Last Outpost: +31-72157682 [28.8 DS]\n                 +31-72201182 [28.8 DS]\n   Undiscovered: +31-22941442 [28.8 DS]      Leave mail to:\n                 +31-22944442 [28.8 DS]      KiLLraVeN/MYSTiC\n\n   If  YOU  are interested to join one of the finest groups in the scene:\n   MYSTiC  -  Make  sure you call one of our headquarters in your nearest\n   country and leave the sysop a message.\n\n   ----------------------------------------------------------------------\n\n           More quality doors/tools will be available very soon!\n                Keep in touch with the best coders - MYSTiC!\n\n   ----------------------------------------------------------------------\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',58974,1,1,'MTOP','Doors/multitop','mst_mt21','scan',1780048619);
INSERT INTO door_catalog VALUES('mst_ns04','MST-NS04.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MST-NS04.LHA','NodeStat','XIM','LE-win5-96.exe',NULL,NULL,'MST',NULL,replace('-\n','\n',char(10)),'NodeStat.GUIDE',replace('@DATABASE "NodeStat.GUIDE"\n@REMARK .------------------------------------------------------------------.\n@REMARK | This document is written in AmigaGUIDE format, so please read it |\n@REMARK | with AmigaGUIDE or your favourite guide reader.... ciao now...   |\n@REMARK `------------------------------------------------------------------''\n@REMARK $VER: NodeStat v0.4\n@WIDTH 80\n@NODE MAIN "Guide to NodeStat v0.4 - By KiLLraVeN/MYSTiC"\n                           .                                          \n            _______     __/|__    _______________________.  /\______  \n           _\  .. ¬\   /   ! ¬\  _\  ________.   .___.  ¬| /   .___/  \n           \_  ||   \ /____.   \_\_____ ¬\___|   |___|   |/    |__Z___\n          /¬   ||  -\\    ¬!  -\\    ¬V -\\  | -!|axe| -!|\    !¬  -//\n          \____!!_  _/\______  _/\_____  _/\ |___|   |___| \_____  _/ \n           \___\_\_/\\/\____\_/\\/\___\_/\\/ !___!   !___!\/___/\_//  \n                  \\/        \\/       \\/                     \//   \n\n            KiLLraVeN/MYSTiC BrInGs YoU aNoThEr /X-DeSiGn PrOdUcTiOn\n\n                             -%- NodeStat v0.4 -%-\n\n                               @{"+-Introduction--+" link introduction }\n                               @{"+-Installation--+" link installation }\n                               @{"+-----Usage-----+" link usage}\n\n                               @{"+----History----+" link History }\n                               @{"+----Contact----+" link Contact }\n                               @{"+----Greetz!----+" link Greetinx }\n\n@EndNode\n\n@Node Introduction "What is NodeStat? - By KiLLraVeN/MYSTiC"\n                              -%- Introduction -%-\n\n   NodeStat is a small program that scans the CallersLog of a certain node\n   or  multiple  nodes and generates a small report of each node.  It must\n   be run from within Ami-X, not the CLI.\n\n   NodeStat tells you about the number of: Calls\n                                           Lost Carriers\n                                           Sysop Pages\n                                           System Password failures\n                                           Account edits\n                                           Downloads (also in bytes)\n                                           Uploads   (also in bytes)\n          @{"EXAMPLE OUTPUT" link example}                   Failed uploads\n                                           Failed downloads\n                                           Skipped files\n                                           Incomplete transfers\n\n   It  ain''t  much,  but it gives you (the sysop) an accurate view of what\n   happened today on the board and can be handy.  I mainly made it for own\n   usage, but if you like it, feel free to use it.\n@EndNode\n\n@Node Installation "How to install NodeStat - By KiLLraVeN/MYSTiC"\n                            -%- Installation -%-\n\n          This tool can ONLY be used with Ami-Express version 3.xx!\n\n   Create a directory in your DOORS:  by the name of NodeStat and copy the\n   main  program  in  it ("@{"NodeStat" link NodeStat}").  If you like you can copy it to any\n   place but this way you can get it up and running the swiftest way.\n\n   Then,  copy  the  icon file ("NSTAT.INFO") to your BBS:Commands/BBSCmd/\n   directory.   After that, you need to fill in how many nodes your system\n   is  and  what the local node is.  This can be done via tooltypes in the\n   icon, they are:\n\n   NODES=x                          ; The number of nodes\n   NODE.LOCAL=0                     ; The number of the local node\n   NODE.OVERRIDE=255                ; Accesslevel to be allowed to scan\n                                      the local node\n   BACKUP_MODE                      ; If turned on, a backup will first\n                                      be made of the callerslog.\n\n   I  have  turned  the  backup  mode to an option (first it was standard)\n   because  this  can  take up quite some time (not hours, but still a few\n   secs  in  the  worst  case).   If  you  turn  it off (by simply putting\n   brackets  around  the  word  "BACKUP_MODE")  the  procedure of making a\n   backup  is  skipped  and the program will start scanning the log in the\n   original file.\n   \n   This  CAN have some negative results.  If NodeStat is scanning the file\n   it  is not possible for any other tool/program to write in it.  So that\n   means  that  not  even Ami-X can write in it!  If you enable the backup\n   mode,  this problem is solved.  But if you have an one node system, you\n   can turn the backup mode off.\n\n   The  rest  of  the  tooltypes  in  the icon can be left alone, they are\n   standard. (Multinode is supported).\n@EndNode\n\n@Node Usage "How to get it working - By KiLLraVeN/MYSTiC"\n                                -%- Usage -%-\n\n   The  main idea behind this little tool was to get to know what has been\n   goin'' on the board on a certain date.  After a day I would like to know\n   how  many  uploads  I  had and how much was leeched of the board.  Then\n   came this util, written in a few hours.\n\n   Also,  it would be nice if it also could scan on another date than just\n   today.   That''s  why  it  is  possible  to select another date or enter\n   something like -5 to get the statistics from 5 days back.  And ofcourse\n   an accumulative report would be welcome also.\n\n   Well,  that  is  what can be achieved with NodeStat.  Plain and simple.\n   How?  Read on.\n\n   If  you  just enter ''NSTAT'' you will get the statistics of today of all\n   nodes (as sysop).  If you don''t want to get the statistics of the local\n   node, simply set the override access above 255.\n\n   Yesterdays  statistics can be extracted with ''NSTAT -1''.  If you want a\n   cumulative  report  of  today and yesterday, enter ''NSTAT -1 +''.  So if\n   you  want  the  statistics  of 5 days back, ''NSTAT -5'' is the solution.\n   And again, cumulative is ''NSTAT -5 +''.\n\n   Statistics  of a certain day will show up after entering ''NSTAT <date>''\n   where  <date>  ofcourse  is  a  date  like  08-18-93.   Also here it is\n   possible  to  get  a cumulative report with the ''+'', just add it to the\n   command string (''NSTAT 08-18-93 +'').\n\n   Let''s just say you have a 12 node system, and getting the statistics of\n   all  nodes  can take quite a while, esspecially when you have big logs.\n   I think the maximum number of node statistics displayed on screen is 3.\n   It  is  possible  to  get  more, but there is NO break/pause.  So it is\n   possible  to  just get 1 node in special.  Just enter ''NSTAT x'' where x\n   is  the  node  number.   For  example:   ''NSTAT  6''  will  give you the\n   statistics of node 6.\n\n   All these options can be combined like this:\n\n   NSTAT 1 -1 +          - Show results of yesterday of node 1 cumulative\n   NSTAT 5 08-10-93 +    - Show results of node 5 since Aug 10 cumulative\n   NSTAT -5 +            - Show results cumulative of the last 5 days\n   \n   I think you will have gotten the picture by now. In syntax form:\n\n   NSTAT [node#|days_back|date] [days_back|date|+] [+]\n   \n   Online  help  is  available through ''NSTAT ?''.  I hope you will find it\n   useful. If so, please drop me a line at Channel-X or Last Outpost.\n\n@EndNode\n\n@Node History "The life of NodeStat - By KiLLraVeN/MYSTiC"\n                               -%- History -%-\n\n   I am thinking of making it CLI compatible also, that means that you can\n   have  output  on  your console screen as well, but is it really useful?\n   If you think it is, you know where to reach me.\n\n\n   23-Oct-93   0.4   Switched from UDLog to Callerslog for more info\n                     about activities on the board.\n                     Will be released on 27-Oct-93.\n\n   16-Oct-93   0.3   Built in the backup mode option\n                     Only spread to friends.\n\n   16-Oct-93   0.2   First public release.\n\n   13-Oct-93   0.2   Made it multi-node compatible by copying the\n                     UDlog to T: first. It slows it down a little\n                     bit, but it is safer.\n\n   12-Oct-93   0.1   First released to some friends\n\n   Creation is the result of sheer will-power!\n\n@EndNode\n\n@Node Contact "To get in contact with me - By KiLLraVeN/MYSTiC"\n                               -%- Contact -%-\n\n                            I can be reached at:\n\n               Channel-X - Node 1 - +31-2290-62244 - 14k4DS/TD\n               Channel-X - Node 2 - +31-2290-62535 - 16k8DS/TD\n               \n                                    or at\n\n               Last Outpost - Node 1 - +31-72-157682 - 16k8DS\n               Last Outpost - Node 2 - +31-72-201182 - 16k8DS\n\n                                    or at\n\n                          INTERNET: [email removed]\n                       /X-FIDO NET: 44:100/100.1\n                           NLA NET: 14:100/102.1\n                           BOS NET: 99:999/4.1\n                           AMY NET: 39:151/201.1\n\n                               Bye for now...\n@EndNode\n\n@Node Greetinx "Greetings to people I know - By KiLLraVeN/MYSTiC"\n                              -%- Greetinx -%-\n\n   Big hello''s fly to:\n   \n   HardByte/MST   - Your A4000/040 is cooooool and f*cking f*st!\n   \n   Tycoon/MST     - I hope you can get the tosser working dude! Looks gr8!\n   \n   Muad''Dib/ATX   - Three-way phoning in the Netherlands eh?\n   \n   Dick Jansen    - You know your way around I thought...\n   \n   Yhatware       - Pizza rulez!\n\n   Coca Cola Kid  - Do you exist?\n   \n   Cable          - Coolnes knows no boundaries ;)\n\n@EndNode\n\n@Node Example "This is how it looks like - By KiLLraVeN/MYSTiC"\n\n.-----------------------------------------------------------------------------.\n| Node Status v0.4                Date: 10-16-93             KiLLraVeN/MYSTiC |\n*-----------------------------------------------------------------------------*\n|                                   Node: 1                                   |\n*-----------------------------------------------------------------------------*\n| Callers:    76 Lost Carrier:    4 SysPage:   13 SysPW:    2 AccountEd:    9 |\n*-----------------------------------------------------------------------------*\n| Uploads  :  92 Upload   bytes:    6181105 Failed uploads  :   2 Skipped:  5 |\n| Downloads:  98 Download bytes:    3465816 Failed downloads:   0 Incompl:  1 |\n`--------------------------------( /X DeSiGn )--------------------------------''\n\n@EndNode\n\n@Node NodeStat "Version of NodeStat - By KiLLraVeN/MYSTiC"\n                       -%- NodeStat the program -%-\n\n   If  you  own an accelerated Amiga (that means 68020+), you can copy the\n   020   version   of  NodeStat  ("NodeStat.020")  over  the  000  version\n   ("NodeStat").  It''s a bit faster.\n\n@EndNode\n','\n',char(10)),NULL,'auto-added',42998,8,0,NULL,NULL,'mst_ns04','scan',1780048619);
INSERT INTO door_catalog VALUES('mst_olm','MST-OLM.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MST-OLM.LHA','OLM','XIM','olm',NULL,NULL,'MST','+---/    \ \/ / __/_  __/ / __/------------+ |--/ / / /\  /\  /-/ /-/ / /----Re/Y\o/MsT-| |--\/ / /-/ /\  /-/ /-/ /\ \---------------|',replace('     __________________________             \n+---/    \ \/ / __/_  __/ / __/------------+\n|--/ / / /\  /\  /-/ /-/ / /----Re/Y\o/MsT-|\n|--\/ / /-/ /\  /-/ /-/ /\ \---------------|\n+---\/\/--\/--\/--\/--\/--\/---(/X-DeSiGN)-+\n|           PReSeNTS : OLM V0.9            |\n+------------------------------------------+\n','\n',char(10)),'Olm.guide',replace('@database OLMDoc\n\nCopyright (C) 1993 TekLords/Mystic/X-DeSign, Belgium, LI\nAll Rights Reserved\n\n@Remark $VER: Version V1.0 (Oct 28 1993, 19:01:21)\n@Remark AmigaGuide database for the OLM Documentation for /X\n\n@node MAIN "OLM AmigaGuide Document (C) 1993 TekLords/Mystic/X-DeSign (Oct 28 1993, 19:01:21)"\n\n                                :                                          \n   ________               :     ¦                    /\\                    \n   \\       \\  ____________¦    _|_ ___________ _____/_ \\_ _ __________ __ _\n    \\______ \\/ __ _ _/    |    \\\\\\\\\\_       /\\\\\\_    /__/\\\\\\\\__      //_///\n     /     \\  /     \\     |    _/   /______/     _  /   \\    _/     /      \n   _/       \\/       \\_____   _\\______    \\_      \\/     \\_  \\_____/\\_     \n   \\        ||        /   /   \\      /     /      |       /          /     \n    \\ ______||______ /_________\\_________ /_______|_____ /_________ /      \n     \\/            \\/                   \\/             \\/     Rpd!\\/ \n                              (MYSTiC/X-DeSiGN) \n\n\n              .: C O N T E N T S  O F  D O C U M E N T A T I O N :.\n              ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n                         @{"        Introduction        " Link Part01}\n                         @{"        Requirements        " Link Part02}\n                         @{" How to install the /X Door " Link Part03}\n                         @{"         Greetings          " Link Part04}\n\n                Docs done by @{" Re/Y\o/TekLords/Mystic/X-DeSign " Link Diabolo}.\n                       Install And Enjoy The Program ...\n@endnode\n@node Part01 "Introduction To OLM by Re/Y\o/TLS/MST "\n\n                              .: Introduction :.\n                              ~~~~~~~~~~~~~~~~~~\n\nWell it is very easy ... OLM will send a message of an unlimited length to any \nuser, who is online at that moment and can be reached through ©Ami-Express \nitselve ... At the same time you get the message, OLM will try to call another\nOLM on the other node you were sending the OLM to ... You can then reply to or\nQuit from the OLM ... There might be some more features in the future then\nthere are now ...\nYou are able to send OLM''s to Handles (with wildcards) or to NodeNumbers or \nofcourse to ALL Nodes ...\n\n\n@endnode\n@node Part02 "Requirements"\n\n                              .: Requirements :.\n                              ~~~~~~~~~~~~~~~~~~\n\nAll you need is an ©Amiga and ©Ami-Express version whatever ... For the rest\nyou need a little bit patience and luck ... The rest is for the @{"Installation" Link Part03}.\nIf you find any BUGS or have some SUGGESTIONS please leave me a messy ... You\nwill most certainly be able to find me at @{" Diabolo " Link Diabolo}.\n\n\n@endnode\n@node Part03 "How To Install OLM by Re/Y\o/TLS/MST"\n\n                            .:Installation Guide:.\n                            ~~~~~~~~~~~~~~~~~~~~~~\n\nThe Program runs on most versions of Ami-Express as far as I have access to all\nthose versions ...\n\n                             @{"  Ami-Express v2.x  " Link Part030}\n                             @{"  Ami-Express v3.x  " Link Part031}\n\n@endnode\n@node Part030 "Ami-Express v2.x"\n\n                            .:Ami-Express v2.x:.\n                            ~~~~~~~~~~~~~~~~~~~~\n\nIt is very easy to install this program ... It does not require special\nprograms or preferences ... I might put some language-specific functions in\nit as soon as Bytemaster will start supporting LOCALE in a way ... Could be\nnice if everybody could work in your BBS in his own language ... What did\ncommodore ever invented LOCALE for :) ?\n\nOk just put this in your bbscommands ...\n\n~~~~~~~~~~~~~ <- Cut Here :)\n~~~~~~~~~~~~~\n*OLM      XM010DOORS:olm\n~~~~~~~~~~~~~ <- Cut Here :)\n~~~~~~~~~~~~~\n\nSince Ami-Express v2.x is not used that often anymore it was not tested on\nthese older versions ... But I hope it works on the 2.x versions ... if not\nleave me mail somewhere and I will make one that does work ...\n\n@endnode\n@node Part031 "Ami-Express v3.x"\n\n                            .:Ami-Express v3.x:.\n                            ~~~~~~~~~~~~~~~~~~~~\n\nIt is very easy to install this program ... It does not require special\nprograms or preferences ... I might put some language-specific functions in\nit as soon as Bytemaster will start supporting LOCALE in a way ... Could be\nnice if everybody could work in your BBS in his own language ... What did\ncommodore ever invented LOCALE for :) ?\n\nJust copy one of the existing Icons you have in your BBSCmd directory and put\nthese tooltypes in it ...\n\n~~~~~~~~~~~~~ <- Cut Here :)\n~~~~~~~~~~~~~\nLOCATION=Doors:OLM\nMULTINODE=YES\nACCESS=10\nTYPE=XIM\nSTACK=20000\n(RESIDENT)\n~~~~~~~~~~~~~ <- Cut Here :)\n~~~~~~~~~~~~~\n\nThe OLM Door can be made resident ... To do this just put\nresident OLM Doors:OLM pure add\nin your user-startup or where you want it ... And delete the brackets around\nthe RESIDENT tooltype ...\nLOCATION=Doors:OLM should be changed into LOCATION=Olm ...\n\nThat should be all folks ...\n\n@endnode\n@node Part04 "Greetings To EveryOne"\n\n\n\n               First Of All I Want To Greet Some Betatesters ...\n\n                               @{"     Andi/MST     " Link Diabolo}\n                               @{"     Spy/MST      " Link Paralysis}\n                               @{"    SieGel/MST    " Link Diabolo}\n                               @{" Genghis Khan/TLS " Link WOK}\n                               @{"       Uli        " Link FlyingSaucer}\n                               @{"      Amiga       " Link Amiga}\n\n               Secondly All The Members Of Mystic & TekLords ...\n\n                                 @{"    Mystic    " Link Mystic}\n                                 @{"   TekLords   " Link TekLords}\n\n                            And Last But Not Least ...\n\n        All Ex- And Still-Members Of AFL That I Have Met Over The Years...\n\n\n@endnode\n@node Diabolo  "Diabolo -=- Mystic/X-DeSign WHQ -=-"\n\n\n                        ·  :                 .     :     :\n-============-   \\____ ¬V ¬V___ ¬V___ ¬V___ ¬V ¬|  |___ ¬|   MANAGEMENT\n (Mystic/X-Design)| ¬|  |  | ¬|  | ¬|  | ¬|  |  |  | ¬|  |   -========-\n      WHQ         |  |  |  |  |  |  |  |  |  |  |  |  |  |   ANDi/MST\n-============-    |  |  |  |     |    _|  |  |  |__|  |  |   SPY/MST\n                  |  |  |  |  |  |  | ¬|  |  |  | ¬|  |  |   FELDMAN\n-ELiTE oNLY-      |  |  |  |  |  |  |  |  |  |  |  |  |  |   FuZzY/MsT\n                  |  |  |  |  |  |  |  |  |  |  |  |  |  |   Wolfmann/TRSI\nCALL US NoW FoR   |  |  |  |  |  |  |  |  |  |  |  |  |  |   (-FaZ! & tERMi-)\nTHE NEWEST AMiGA/ |  |  |  |  |  |  |  |  |  |  |  |  |  |     -====-\nPCSTUFF           |  |  |  |  |  |  |  |  |  |  |  |  |  |   RUNS oN A3000\nAND ALL MST-      |  |  |  |  |  |  |  |  |  |  |  |  |  |   WITH 25MHZ AND\nRELEASES.         |  |  |  |  |  |  |  |  |  |  |  |  |  |   AMIEX (REG.)\n                __|_____A__A__A__A_____A_____A_____A_____|D! \nWE oNLY ACCEPT    |     :  :     :     :     :     :     |   SUPPoRTET BY\n9600 - 16.800     :     ·  .     .           .     ·     :   -==========-\nBAUD CoNNECTS.    .        .                                 M Y S T I C\n\n\n@endnode\n@node Paralysis  "Best PD-BBS in Berlin ... Give it a RING"\n\n\n  _______)\\  ________ _____)\\  ________ _____________)\\ ____ _______)\\\n  \\  _____ \\ \\  ____ \\\\  ___ \\ \\  ___  \\\\\\ / //\\\\  ___  / \\\\\\  ___  /\n  _\\/____/ /__\\/___/ /_\\/__/ /__\\/__/  / \\  / \\ \\/ / \\/\\/  // \\/\\/\n  \\  _____/ \\  ___  / \\  ___/ \\  ___  /  / /\\ \\_/ /  \\ \\___\\  /  \\ \\___\n /\\\\//\\\\/  / / /\\\\ \\/\\\\/  / //\\ \\//\\\\___/ /\\ \\___ \\ /\\\\/ /\\ \\___ \\\n// \\// \\  / / // \\\\ \\_// \\  / /// \\ __ // \\// \\ __/ /// \\ // \\ __/ /\n\\__/\\__/  \\/  \\__/ \\ /\\__/  \\/ \\__//__\\\\__/\\__//___/ \\__/ \\__//___/\nV\n         SYSOP : Spy/MST  !    COSYSOP : PHANTOM        SYSOP : Arthur Dent\n.\nAmIgA 3ooo / 25 MhZ / 24H 7DaYz / CoOl RaTiOs / USR DuAl RuLeZ\n\n\n NoDe 1 : 745 2093     U.S.Robotics DUAL Standard 14400 (RINGDOWN FOR NODE 1-3)\n NoDe 2 : 745 2094     U.S.Robotics DUAL Standard 16800\n NoDe 3 : 745 2095     U.S.Robotics DUAL Standard 16800\n NoDe 4 : 746 7782     U.S.Robotics COURIER HST   16800 (ZyXEL 19200 soon)\n\n\n@endnode\n@node WOK  "Wrath Of Khan -=- TekLords WHQ -=-"\n                  INVOKE IF YOU DARE THE... .|\n      __ _    _ _______ _   ____ ____ ____ /||\\   ___ ____      ______\n      \\ Y \\/\\/ Y __ ___Y \\ / ___Y___ Y___// || \\  \\__Y___ \\   /Y    _/\n       \\· / \\\\ ·// Y|_/·_//__|/ ·| / ·\\  /-*()*-\\  / · |/  \\ / · ___/\n        \\_\\__/_/// ·\\_  \\/ \\___ ||/   \\\\// _||  \\\\ \\\\  /  ////  __/\n         \\_||_/ \\__ |\\___\\__||___|\\____/\\___||___/  \\_ ___/ \\_ _|\n           ·|      Y .   Y   .|           . |·        Y       Y\n                 ___/|_ ____/||\\___ ____  |\\__   _|   ·      ·\n                 \\_/ |/Y /_/ || \\__Y___ \\ |_  \\/Y |\n                  /  / ·/ /-*()*-\\|· \\|__\\|    \\·_|\n                 //  \\  \\// _||  \\\\_  __/ \\  \\   _|\n                 \\__ |\\__\\_ _||___/___|| _/__/\\__ |\n                    Y    Y Y ·|   Y     Y |      \\| [Seven M]\n                    ·    · ·      ·     ·         ·\n\n                          -* TekLords WHQ *-\n\n  Sysops: SouLCatcher                        CoSysops:  Percy\n          SkY                                           DIO+CAT/AFL\n          Genghis Khan                                  Ghostrider\n@endnode\n@node FlyingSaucer "Flying Saucer -=- Independent -=-"\n\n\n       .::::::::: ::::       ::::  :::: :::::::::: ::::  :::: .:::::::::\n       ::::       ::::       ::::  ::::    ::::    ::::: :::: ::::\n       :::::::::: ::::       `:::::::::    ::::    :::::::::: :::: :::::\n       ::::       ::::             ::::    ::::    :::: ::::: ::::  ::::\n       ::::       `::::::::: :::::::::'' :::::::::: ::::  :::: `::::::::''\n                                       .\n                           . . . . . . | . . . . . .\n                         /¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\\\n             ______/¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\\______\n                   \\_______________________________________/\n                                 \\___________/\n                                  |||||||||||\n                                  | || || | |\n                                    |     |\n       .::::::::: .::::::::. ::::  :::: .::::::::. .::::::::: :::::::::.\n       ::::       ::::  :::: ::::  :::: ::::  :::: ::::       ::::  ::::\n       `::::::::. :::::::::: ::::  :::: ::::       :::::::::: :::::::::''\n             :::: ::::  :::: ::::  :::: ::::  :::: ::::       ::::  ::::\n       :::::::::'' ::::  :::: `::::::::'' `::::::::'' `::::::::: ::::  ::::\n\n                     -= INDEPENDENT FLYING SAUCER EHQ  =-\n                                                                     Spads\n\n\n@endnode\n@node Amiga "Amiga ... Just The Best"\n\n                               ___   ___                                   \n                              /  /  /  /     /\\                            \n                             /  /  /  /     /  \\    