INSERT INTO door_catalog VALUES('mst_pa10','MST-PA10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MST-PA10.LHA','MST-PAGE','XIM','_____    ___    _____________.__. ____',NULL,'SieGeL/MST','MST','_/  v  \__/ ! \  /  _____.   ._(__)/  . \ \_ _:_ ______  \/\___  \ |   | |  \_  |_/\ _/  \ /  \_  v  __   v   \|   | |    _ |   \',replace('   _____    ___    _____________.__. ____   \n _/  v  \__/ ! \  /  _____.   ._(__)/  . \  \n \_ _:_ ______  \/\___  \ |   | |  \_  |_/\ \n_/  \ /  \_  v  __   v   \|   | |    _ |   \\n\    v    /  ___/\    ___/!___! !___/__-   /\n-\___:___/___/-ã!-\___/---------------\___/-\n   MST-PaGe V1.0 BY SieGeL/MST\n','\n',char(10)),'MST-PaGe.guide',replace('@database MST-PaGe.guide\n\n@node Main "MST-PaGe V1.0 - /X uTiL WRiTTeN BY SieGeL/MsT"\n\n            /\____________.__  _______________________   ________\n           /   ._.____    |  \/    ________ _     /___)_/   .___/\n         _/    | |    \___.   \____.   \_|   \___/          |______\n         \     | |     /  |    /   |    /|    |  |   ____   ¦     /\n          \ ___l_l___ /______ /_______ / |    |  l___ | \________/\n           \/       \/      \/       \/  l____|      \!·A×E·\n \n                              (MYSTiC/X-DeSiGN) \n\n                  iS BaCK WiTH aNoTHeR PRoDuCTioN CaLLeD :\n                                   \n                          MST-PaGe V1.0 BY SieGeL/MST\n\n	  		       @{" INTRODUCTION " LINK INTRODUCTION}\n			       @{" REQUIREMENTS " LINK REQUIREMENTS}\n			       @{" INSTALLATION " LINK INSTALLATION}\n			       @{"  TOOL-TYPES  " LINK TOOLTYPES}\n			       @{"GREETZ&ADVERTS" LINK GREETINGS}\n\n                         DoCFiLe WRiTTeN BY SieGeL/MST\n@endnode\n\n@node INTRODUCTION "FeaTuReS & iNTRoDuCTioN"\n\n                           iNTRoDuCTioN\n                           ~~~~~~~~~~~~\nYeah, a new MST-Release....but what does thiz Tool do ??? Well, it''s a new \nOPERATOR PAGER for /X3.xx (/X2.xx Users : It should work too, but I have no\nchance to test it !!) with many Features...like :\n \n  o Two different Page-Modi (Fast- and Slowpaging) \n\n  o Sysop can choose which Users could page every Time\n\n  o Displays a Ansi (If u want it, of coz :) ) instead of writing :\n    > Paging SieGeL/MST (CTRL-C TO ABORT) .... < \n\n  o Create a DataFile to count all Pagings that have been made...\n\n  o With `O ?'' u will see the "TOP TEN PAGERS" ...\n\n  o Comment to Sysop if he''s not at Home...\n\nIf U have Suggestions, cewl Ideas or simply wants to contact us, kall\n@{" DiaBoLo BBS " LINK ADVERT} and leave a messi to SieGeL/MST !\n@endnode\n@node REQUIREMENTS "What U need 2 run it..."\n\n                           ReQuiReMeNTS\n                           ~~~~~~~~~~~~\nYou Need...\n\n o first an Amiga (Tested on A500/A1200/A2000/A3000/A4000)\n\n o the installed OS 2.X/3.X \n\n o an correctly installed Amiex V3.xx\n\n o many Users, which wants to page U....:)\n\n\nLet''s go on with the @{" INSTALLATION " LINK INSTALLATION}...\n@endnode\n@node INSTALLATION "HoW To iNSTaLL it..."\n\n                           iNSTaLLaTioN\n                           ~~~~~~~~~~~~\nUnpack the Archive, u see the following Files :\n\n             MST-PaGe.........The Main Program\n             MST-PaGe.info....The ConfigFile\n             MST-PaGe.guide...The Docfile U ar still reading 8)\n             SieGeLaNSi.ans...A Sample-Ansi Picture\n             o.info.........../X-Command\n\nFirst, copy the "o.info" File to ur BBS:BBSCMD/ Drawer and change the Tool-\ntypes to your own choices.\nCreate a Drawer in DOORS: called "PAGE" and copy the other Files into it...\n\nNOTE:Don''t rename the DOORS:PAGE/ Drawer and the DOORS:PAGE/MST-PAGE.INFO \n     File, otherwise the Tool won''t work !!!\n\nThat''s all for Installation, now we @{" configure " LINK TOOLTYPES} the Pager...\n@endnode\n@node TOOLTYPES "TooLTYPeS FoR MST-PaGe V1.0"\n    \n                              TooLTYPeS\n                              ~~~~~~~~~\nHere are a complete List of all Tooltypes...\n\n ANSI=<path>        - If <path> is a valid path to an Ansipicture, MST-Page\n                      displays it instead of writing :\n                      "PAGING SieGeL/MST ...."\n                      \n                      NOTE : Don''t use Ansis with more than 10 Lines, coz\n                             the room for Ansis isn''t very great.\n\n USER.<x>=<name>    - <x> is a number between 0-???, <name> is the name of \n                      a User, which could page you everytime. No matter if\n                      the chatflag is on or off. Useful for Groupmembers,\n                      which should page you everytime.\n\n FASTPAGE=<access>  - MST-Page has two Pagemodi. The first (Slowpage) is \n                      the normal Paging. If Chatflag is on, MST-Page will\n                      page the Sysop one time and decrements the Page-\n                      counter by one.\n                      In FastPage-Mode, the User has the ability to page U\n                      three times at once, but decrements the Page-Counter \n                      only by one. Useful for Cosysops or Groupmembers.\n                      <access> is the needed Accesslevel from a User to use\n                      the Fastpagemodi. \n\n DATAFILE=<YES|NO>  - If this Tooltype is set to "YES", MST-PaGe creat a \n                      DataFile (DOORS:PAGE/PAGE.STAT) to count all pagings\n                      that will be made. \n                      The Top Ten List will be shown if U enter `O ?'' in \n                      the /X-Main Prompt.\n@endnode\n\n@node GREETINGS "GReeTZ & aDVeRTS"\n                              GReeTiNGS\n                              ~~~~~~~~~\n ByteAndi/MST  -  We aRe oN THe RiGHT WaY...LeT''S Go oN CoDiN''\n\n aRGoN/MST     -  HoPe YaR MiLiTaRY-TiMe iSN''T To HeaVY FoR U...\n \n SPY/MST       -  MoRe ReLeaSeS iN THe FuTuRe..."C" RuLeZ!\n\n KiLLRaVeN/MST -  CeWL /X-TooL...HoPe To See MoRe ReLeaSeS 8)\n\n eMPiRe/MST    -  No MoRe aReXX...CeeeeWL!!!\n\n aXe/MST       -  No NeeD oF CC''S...CoDiNG iS BeTTeR THaN TRaDiNG...:)\n\n SeCaM         -  WHY DoN''T U uSe NeWFiLeS V2.00 ??? iT''S GReaT !!!\n \n STRiDeR       -  i WiLL HeLP U aS MuCH aS PoSSiBLe...\n\n SK¡N&aMBLiN   -  U aR THe ReaL ASC¡¡-GoDS !!!\n\nTHaT''S aLL DuDeS...WaTCH ouT FoR oTHeR PRoDuCTioNS FRoM @{"(MYSTiC/X-DeSiGN)" LINK ADVERT}\n@endnode\n\n@node ADVERT "KALL DIZ OR DIE !!!!!"\n\n                         ·  :                 .     :     :\n -============-   \____ ¬V ¬V___ ¬V___ ¬V___ ¬V ¬|  |___ ¬| MANAGEMENT\n  MYSTIC           | ¬|  |  | ¬|  | ¬|  | ¬|  |  |  | ¬|  | -========-\n       GHQ         |  |  |  |  |  |  |  |  |  |  |  |  |  | ANDi/MST\n -============-    |  |  |  |     |    _|  |  |  |__|  |  | SPY/MST\n                   |  |  |  |  |  |  | ¬|  |  |  | ¬|  |  | FELDMAN\n -ELiTE oNLY-      |  |  |  |  |  |  |  |  |  |  |  |  |  | FuZzY/MsT\n                   |  |  |  |  |  |  |  |  |  |  |  |  |  | SYSTEM\n CALL US NoW FoR   |  |  |  |  |  |  |  |  |  |  |  |  |  | -====-\n THE NEWEST AMiGA/ |  |  |  |  |  |  |  |  |  |  |  |  |  | RUNS oN A3000\n PCSTUFF           |  |  |  |  |  |  |  |  |  |  |  |  |  | WiTH 25MHZ AND\n AND ALL MST-      |  |  |  |  |  |  |  |  |  |  |  |  |  | AMiEX (REG.)\n RELEASES.         |  |  |  |  |  |  |  |  |  |  |  |  |  |\n                 __|_____A__A__A__A_____A_____A_____A_____| SUPPoRTET BY\n WE oNLY ACCEPT    |     :  :     :     :     :     :D!   | -==========-\n 9600 - 16.800     :     ·  .     .           .     ·     : M Y S T I C\n BAUD CoNNECTS.    .        .                                      \n@endnode\n','\n',char(10)),NULL,NULL,24190,6,0,NULL,NULL,'mst_pa10_mst_page','scan',1780048619);
