INSERT INTO door_catalog VALUES('mst_sct1','MST-SCT1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MST-SCT1.LHA',NULL,'XIM','scout.xim',NULL,'Zeus/Mystic','MST','_____ \/  /  /  /  ___/__  \/  / _  \.aXY! : ¦  / \_  /\_   /\_  \   /  /  /  /__/      ¦ `-/  /  /  /  /  /  /  /  /  /  /  /-------''',replace('______  ___/\____/\____/\__  ·  /\__       ·\n_____ \/  /  /  /  ___/__  \/  / _  \.aXY! :\n¦  / \_  /\_   /\_  \   /  /  /  /__/      ¦\n`-/  /  /  /  /  /  /  /  /  /  /  /-------''\n /  /  /  /  /  /  /  /  /  /  /  / PRESENTS\n/__/  /\__  /\__  /--/  /  /\__  /--------->\n  /__/  /__/  /__/  /__/  ·  /__/  ..IN 1995\n  Scout v1.0! · (c)1995 Zeus/Mystic^Style!\n SysopAvail-like door for /X 4.x & DayDream\n','\n',char(10)),'mastrb8.txt',replace(replace('STILL GOING STRONG in 2014!\r\n\r\n                ___         ._            _______             ·\r\n   /\  _________)  \________| \___________)__   /_________:__ :________\r\n  /  \/\  __  \    ____ ___/|  \______  \_  / _/___  \_ ____/ ¦__ \___ \\r\n /   /  \ \__  \___  \  |   |   \  _/  __/ /    /\__  \  |¦   | /  \_|  \\r\n/  \/    \_ \   \ !   \_|   !    \_\    \_     /   \   \ ||   |·    /|   \_\r\n\___|     ___\  /__    /l________ /_\    /__  /_____\  / |¦   |    /_|    /\r\n    l____/-A×E\/  \___/_!       \/   \  /   \/       \/__|:   ¦__ /  l___/\r\n       ______            _____        \/      :    ____   ·   : \/\r\n    ___)     \___________)    \__________:___ ¦____)   \__________\r\n    \    _______     _______    \___    ____/ |\_____   \______   \\r\n   /\___   \/        |    _)    \/       ¦    |/    |    \    |    \\r\n _/    !    \        |    \      \_      |    |     !     \   |     \\r\n \______     \___    |_____\      /___   |    ¦            \  |      \_\r\n       \______/ \____!      \    /   \___|    :________     \_|       /\r\n                             \  /        ¦    ·       \______/|      /\r\n   YOUVE HEARD ABOUT IT!      \/         :    ·               l_____/\r\n       \r\n         MASTURBATiON STATiON AMIGA/PC/CONSOLE/ASCII-ANSI/C64        \r\n               Telnet: bbs.masturbationstationbbs.com\r\n\r\n           UPLOAD DATE: 04-27-16  TIME: 15:31:16  ON NODE: 1\r\n\r\n  UPLOADER: Black Beard            LOCATION: mSTATION.servebbs.com    \r\n\r\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',5102,1,0,NULL,NULL,'mst_sct1','scan',1780048619);
INSERT INTO door_catalog VALUES('mst_stat','MST-STAT.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MST-STAT.LHA',NULL,'XIM','LE-win5-96.exe',NULL,NULL,'MST','_/  v  \__/ ! \  /  _____.   ._(__)/  . \ \_ _:_ ______  \/\___  \ |   | |  \_  |_/\ _/  \ /  \_  v  __   v   \|   | |    _ |   \',replace('   _____    ___    _____________.__. ____   \n _/  v  \__/ ! \  /  _____.   ._(__)/  . \  \n \_ _:_ ______  \/\___  \ |   | |  \_  |_/\ \n_/  \ /  \_  v  __   v   \|   | |    _ |   \\n\    v    /  ___/\    ___/!___! !___/__-   /\n-\___:___/___/-ã!-\___/---------------\___/-\n--------------------------------------------\n            STATUS-MST\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.