INSERT INTO door_catalog VALUES('mst_stsh','MST-STSH.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MST-STSH.LHA','StripShit','XIM','StripShit',NULL,NULL,'MST','+---/    \ \/ / __/_  __/ / __/------------+ |--/ / / /\  /\  /-/ /-/ / /---Re/Y\o------| |--\/ / /-/ /\  /-/ /-/ /\ \----Mystic-----|',replace('     ______  __________________\n+---/    \ \/ / __/_  __/ / __/------------+\n|--/ / / /\  /\  /-/ /-/ / /---Re/Y\o------|\n|--\/ / /-/ /\  /-/ /-/ /\ \----Mystic-----|\n+---\/\/--\/--\/--\/--\/--\/-----/X-DeSign-+\n| StripShit 1.0 ... Removes Unneeded Lines |\n| Out Of The NetMail Before Transfering It |\n| Saves Some (K)Bytes For Being Transfered |\n+------------------------------------------+\n','\n',char(10)),'StripShit.doc',replace('**************************************************************************\n*                                                                        *\n*         FastDoc For StripShit v1.0 By Re/Y\o /Y\ystic/X-DeSiGn         *\n*                                                                        *\n**************************************************************************\n\nWhat Does it Do?\n~~~~~~~~~~~~~~~~\nIt will strip for each message in the net all lines that contain\n\n	--- /XNet v5.1 (703001.AX0001,144,BJP-12.0000)\n	* Origin: LightSpeed Technologies - (cla) ssi-fied - /X Developement\n\nexcept the last ones ...\n\nA message that looks like this:\n\n	Date   : Thu Dec 23 23:57:17 1993         Number: 2859\n	To     : crom                            Address: SF0003\n	From   : Alex Andruszkiw                 Address: 416003\n	Status : Public Message                   Recv''d: No\n	Subject: BBSGUARD\n\n	        My version is 2.0 ... You MUST have an ANCIENT version ;)\n	 ----( CRoM @ SF0003 )------------------------------------------------\n	\n	U must have an old version.. I''ve got v2.03!\n	\n	--- /XNet v4.9 (416003.AX0002,1156,SAG-15.0048)\n	* Origin: ]*>The Great Barrier (905)841-5343<*[ .oøCANADA HUBøo.\n	 ----( Alex Andruszkiw @ 416003 )-------------------------------------\n	\n        Eh, where could I get it?!?\n	\n	--- /XNet v4.9 (SF0003.AX0002,911,CPS-13.0193)\n	* Origin: sHOIKAn gROVe bBs - nO mORTAL wILL sURVIVE tHROUGH iT!\n	 ----( CRoM @ SF0003 )------------------------------------------------\n	\n	EEk!... man, it took like 8 days for me to get this reply from ya!?  Hmm,\n	i''d guess that we have to call out more often 8-)  I''ve sent BBSGuard v2.03\n	down the net... You should have it, since I put it like in this newsgroup!\n	\n	--- /XNet v5.1 (416003.AX0002,1251,SAG-15.0048)\n	* Origin: ]*>The Great Barrier (905)841-5343<*[ .oøCANADA HUBøo.\n	\nWill look afterwards look like:\n	\n	Date   : Thu Dec 23 23:57:17 1993         Number: 2859\n	To     : crom                            Address: SF0003\n	From   : Alex Andruszkiw                 Address: 416003\n	Status : Public Message                   Recv''d: No\n	Subject: BBSGUARD\n\n	        My version is 2.0 ... You MUST have an ANCIENT version ;)\n	 ----( CRoM @ SF0003 )------------------------------------------------\n	\n	U must have an old version.. I''ve got v2.03!\n	 ----( Alex Andruszkiw @ 416003 )-------------------------------------\n	\n	        Eh, where could I get it?!?\n	 ----( CRoM @ SF0003 )------------------------------------------------\n	\n	EEk!... man, it took like 8 days for me to get this reply from ya!?  Hmm,\n	i''d guess that we have to call out more often 8-)  I''ve sent BBSGuard v2.03\n	down the net... You should have it, since I put it like in this newsgroup!\n	\n	--- /XNet v5.1 (416003.AX0002,1251,SAG-15.0048)\n	* Origin: ]*>The Great Barrier (905)841-5343<*[ .oøCANADA HUBøo.\n	\nHow Does It Works?\n~~~~~~~~~~~~~~~~~~\n	\nYou can start it just before you are transfering netmail ... You simply\ngive it the pathname and it will look after those files which are going\nto be transfered and will strip all lines that are not needed ... It''s \nas simple as that ....\n	\nIt will remove tons of unneeded lines ... which for some people will make\na difference in your phonebill i guess :) ...\n\nEnjoy The Program ... Bugreports go to Re/Y\o /Y\ystic /X-DeSiGn ...\n\n','\n',char(10)),NULL,'auto-added',22710,9,0,NULL,NULL,'mst_stsh','scan',1780048619);
INSERT INTO door_catalog VALUES('mst_ts1','MST-TS1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MST-TS1.LHA',NULL,'XIM','LE-win5-96.exe',NULL,'Muad''Dib/MST!','MST','/\_/l_____  //\______/___\____ nUp!/  \  _  _/__/  \_______ _____/ _ _ _/    \/    \_ \__     \_ \/  \_ _ _',replace('             .     _ _         ___\n         /\_/l_____  //\______/___\____\n    nUp!/  \  _  _/__/  \_______ _____/\n  _ _ _/    \/    \_ \__     \_ \/  \_ _ _\n     \\____ /______/_______   /______//\n.--------÷\/÷------------÷\  /÷------------.\n| mYst!c /X diVisiOn rULes \/ with:        |\n|   TXTStyler v1.00 - Works with Back^Up,  |\n| include uploader info!  By Muad''Dib/MST! |\n`------------------------------------------''\n                                     >{d·h}<\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                       