INSERT INTO door_catalog VALUES('mst_us13','MST-US13.LZH','~/Code/amiexpress_doors/Archives/AmiExpress/MST-US13.LZH','u-stat','XIM','LE-win5-96.exe',NULL,NULL,'MST','_/  v  \__/ ! \  /  _____.   ._(__)/  . \ \_ _:_ ______  \/\___  \ |   | |  \_  |_/\ _/  \ /  \_  v  __   v   \|   | |    _ |   \',replace('   _____    ___    _____________.__. ____   \n _/  v  \__/ ! \  /  _____.   ._(__)/  . \  \n \_ _:_ ______  \/\___  \ |   | |  \_  |_/\ \n_/  \ /  \_  v  __   v   \|   | |    _ |   \\n\    v    /  ___/\    ___/!___! !___/__-   /\n-\___:___/___/-ã!-\___/---------------\___/-\n--------------------------------------------\n            PReSeNTS : U-STaT V1.3\n','\n',char(10)),'U-STAT.GUIDE',replace('@database U-STaT V1.3 DoCS\n\n@node Main "U-STaT V1.3 - /X uTiL WRiTTeN BY SieGeL/MsT"\n                                :                                          \n   ________               :     ¦                    /\                    \n   \       \  ____________¦    _|_ ___________ _____/_ \_ _ __________ __ _\n    \______ \/ __ _ _/    |    \\\\\_       /\\\_    /__/\\\\__      //_///\n     /     \  /     \     |    _/   /______/     _  /   \    _/     /      \n   _/       \/       \_____   _\______    \_      \/     \_  \_____/\_     \n   \        ||        /   /   \      /     /      |       /          /     \n    \ ______||______ /_________\_________ /_______|_____ /_________ /      \n     \/            \/                   \/             \/     Rpd!\/ \n                              (MYSTiC/X-DeSiGN) \n\n                  iS BaCK WiTH aNoTHeR PRoDuCTioN CaLLeD :\n                                   \n                          U-STaT V1.3 BY SieGeL/MST\n\n	  		    @{"     iNTRoDuCTioN     " LINK INTRODUCTION}\n			    @{" aLL FoR iNSTaLLATioN " LINK REQUIREMENTS}\n			    @{"      TOOL-TYPES      " LINK TOOLTYPES}\n                            @{"     FINAL SALUTE     " LINK END}\n\n                         DoCFiLe WRiTTeN BY SieGeL/MST\n@endnode\n\n@node INTRODUCTION "NeWS & FeaTuReS oF U-STaT V1.3..."\n                \n		              INTRODUCTION\n                              ~~~~~~~~~~~~\nThis tool replaces the built-in ''S'' command from da Amiex with a better\ninformationscreen, on which U can see more than enough about your account.\n\nSince Version 1.2 U are able to configure simply all of the output, i.e. \nall colors could be changed to your own choices, textoutputs for the \nchatflag and for the securitylevel of an user are editable via tooltypes. \n\nAnother new function is the ability to give a comment to the user about his\nupload/download Bytes...i.e. if a user has ULed 500000 Bytes and DLed the\nsame amount, U-STaT V1.2 calculates an amount of 100,which means 100% .\nIf the user ULed 500000 & DLed 100000 U-STaT calculates 500,  which means\nthe user has uploaded 5:1 Bytes from which he has DLed...so that means, any \nnumber below 100 is for Leech-Stats, and any number higher than 100 is for \nthe elite Traders :). But Numbers above 1000 are not usefull, coz greater \nnumbers weren''t recognized. Look in chapter @{"TOOLTYPES" LINK TOOLTYPES} for more information\nabout the comments...\n\nIf you have suggestions or find a bug in this or other Tools comin'' from\n(MYSTiC/X-DeSiGN), try to call @{"DiaBoLo BBS" LINK ADVERT} or one of the other\nMYSTiC-Boards and leave a mail to SieGeL/MsT, then I try to fix it as fast \nas possible...\n\nNOTE: Well, I''m a german guy, and therefore U would find me only on \n~~~~~ German Boards! (Hope that changes in the Future....:) )\n@endnode\n\n@node REQUIREMENTS "WHaT U NeeD To RuN U-STaT V1.3..."\n                \n		      REQUIREMENTS & INSTALLATION\nFirst U need...       ~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n   - any Amigamodel (A500-A4000T) with the installed Kickstart 2.04+...\n   - The installed Amiex-Software\n\nIf U want to change the colors or give comments to users U need at last \nthe Icon "DOORS:U-STAT.INFO", look chapter @{"TOOLTYPES" LINK TOOLTYPES} for more details !\n\nNOTE:It''s *NOT* recommended to have this icon, if U-STaT don''t find this \nthe internal Colors and the internal Chat on/off messages will be used.\n\nWell, I don''t know if U-Stat V1.3 runs correctly under /X V2.xx ... if \nsomeone could try it out please inform me ....:)\n\nAmiex V3.xx sysops should copy the Icon "s.info" to their BBS:BBSCMD/ \ndrawer.\n\nAs mentioned before, if u want to use the "advanced" options then u have \nto copy the Icon "U-STAT.INFO" to DOORS: ...\n@endnode\n\n@node TOOLTYPES "aLL TooLTYPe-DeSCRiPTioNS FoR U-STaT V1.3"\n                \n		             TOOLTYPES\n                             ~~~~~~~~~\n\nCHAT_ON=<comment>      = U-STaT displays <comment> if chatflag is on.\n			 Defaultstring (internal) is "aT HoMe!"\n\nCHAT_OFF=<comment>     = U-STaT displays <comment> if chatflag is off.\n			 Defaultstring (internal) is "NoT aT HoMe!"\n\nCOMMENT=ON/OFF         = If this Tooltype is switched to "ON", U-STaT adds\n			 four lines under the box. In any other case U-STaT\n			 won''t display this box. This allows you to show \n			 the online User what U think about his UL/DL .\n			 \nCOMMENT.<x>=<comment>  = Here U enter the comments for the user''s UL/DL \n			 statistics...<x> indicates a number between 0-1000\n			 decreasing by 10, that means 0,10,20,30,...the \n			 numbers describes the UL/DL stat. Number 100 means\n			 that he has the same UL/DL Bytes amount. Numbers\n			 below 100 means, he leeched more than he uploaded.\n 			 All numbers higher than 100 means, he uploaded more \n			 than he has downloaded...i.e. UL-BYTES=500000\n			 			       DL-BYTES=100000\n                         The calculated Number is 500, so u could write as\n			 Tooltype : COMMENT.500=   MAN..U R ELITE!\n			 If a tooltype with the specified number is not\n			 available, U-STaT searches for the next lower number \n			 by performing a -10 step (UGLY ENGLISH...SORRY :) )\n			 Look in the example-icon to see what i mean....\n\n			 NOTE:U need at least the ''COMMENT.0='' TOOLTYPE To \n			      give U-STaT the chance to find the end...\n\nLEVEL.<x>=<userdescr.> = Here U could enter a userdescription for the spec.\n			 userlevel. <x> is the userlevel, i.e. enter\n	\n			 LEVEL.255=MASTER OF THE UNIVERSE!...shows sysops \n							  as MASTERS...;)   \n			 NOTE:All STRINGS EXEPT THE COMMENT.<X> STRINGS \n			 SHOULD NOT BE LONGER THAN 24 CHARS...OR THEY WILL\n			 CUT UP ! \n			 COMMENT.<X> STRINGS COULD BE 76 CHARS LONG!\n\nCOLOR.<x>=<colorname>  = Here U define the different colors from U-STaT.\n			 For <x> enter a number between 0-5, which means:\n\n			 0 = Box (Default=BLUE)\n			 1 = Description (Default=TUERKIS)\n			 2 = UserEntries (Default=VIOLETT)\n			 3 = Sysopname (Default=WHITE)\n			 4 = BBSName (Default=WHITE)\n			 5 = Comments (DEFAULT=YELLOW)\n			\n			 Valid Colornames (case-insensitive) are:\n			\n  		            BLACK  (30)        BLUE  (34)  \n			    WHITE  (31)     VIOLETT  (35)\n			    GREEN  (32)     TUERKIS  (36)\n		    	   YELLOW  (33)         RED  (37)\n\n			 The Numbers in branches are the ESC-Values.\n@endnode\n\n@node END "GReeTiNGS...WHaT eLSe ?"\n\nDa GReeTiNGs FLY To...\n~~~~~~~~~~~~~~~~~~~~~~\n \n aRGoN/MsT	- MaRiNeSiCHeRuNGSBaTTaLioN 1 RuLeZ....:) FuCKiN'' BW!\n\n ByteAndi/MsT	- We have done the half of work...let''s do the rest!\n\n aXe/MsT	- MeeT U aT THe WoC...\n\n eX/PH!		- CeWL SYSoP...hope to chat ya next time...\n\n DeLTa-X	- Sorry ''bout uR Board, but perhaps u get another chance..\n\n SeCaM/MST	- THX for ur suggestion...FIXED !\n\n Re/Y\o		- Hope u enjoyed ur Berlin Trip...\n\n...and to all members of PROGRESS (Hi Strider...:)\n \n@endnode\n\n@node ADVERT "CaLL THiZ FuCKiN'' CeWL BoaRD!"\n\n                         ·  :                 .     :     :\n -============-   \____ ¬V ¬V___ ¬V___ ¬V___ ¬V ¬|  |___ ¬| MANAGEMENT\n  MYSTIC           | ¬|  |  | ¬|  | ¬|  | ¬|  |  |  | ¬|  | -========-\n       GHQ         |  |  |  |  |  |  |  |  |  |  |  |  |  | ANDi/MST\n -============-    |  |  |  |     |    _|  |  |  |__|  |  | SPY/MST\n                   |  |  |  |  |  |  | ¬|  |  |  | ¬|  |  | FELDMAN\n -ELiTE oNLY-      |  |  |  |  |  |  |  |  |  |  |  |  |  | FuZzY/MsT\n                   |  |  |  |  |  |  |  |  |  |  |  |  |  | SYSTEM\n CALL US NoW FoR   |  |  |  |  |  |  |  |  |  |  |  |  |  | -====-\n THE NEWEST AMiGA/ |  |  |  |  |  |  |  |  |  |  |  |  |  | RUNS oN A3000\n PCSTUFF           |  |  |  |  |  |  |  |  |  |  |  |  |  | WiTH 25MHZ AND\n AND ALL MST-      |  |  |  |  |  |  |  |  |  |  |  |  |  | AMiEX (REG.)\n RELEASES.         |  |  |  |  |  |  |  |  |  |  |  |  |  |\n                 __|_____A__A__A__A_____A_____A_____A_____| SUPPoRTET BY\n WE oNLY ACCEPT    |     :  :     :     :     :     :D!   | -==========-\n 9600 - 16.800     :     ·  .     .           .     ·     : M Y S T I C\n BAUD CoNNECTS.    .        .                                      \n@endnode\n','\n',char(10)),NULL,'auto-added',27684,6,0,NULL,NULL,'mst_us13','scan',1780048619);
INSERT INTO door_catalog VALUES('mst_vere','MST-VERE.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MST-VERE.LHA','Verenaris','XIM','Verenaris',NULL,'(Mystic/X-DeSign)','MST','+---/    \ \/ / __/_  __/ / __/------------+ |--/ / / /\  /\  /-/ /-/ / /---ByteAndi----| |--\/ / /-/ /\  /-/ /-/ /\ \-----MsT-------|',replace('     __________________________             \n+---/    \ \/ / __/_  __/ / __/------------+\n|--/ / / /\  /\  /-/ /-/ / /---ByteAndi----|\n|--\/ / /-/ /\  /-/ /-/ /\ \-----MsT-------|\n+---\/\/--\/--\/--\/--\/--\/------X-DeSign-+\n|  Vere-Naris V1.1 Conference WeekTop Tool |\n|       With TopWeek Statistic             |\n|     written by (Mystic/X-DeSign)         |\n`------------------------------------------''\n','\n',char(10)),'Verenaris.guide',replace('@database VerenarisDoc\n\nCopyright (C) 1993 Mystic/X-DeSign, Germany, B\nAll Rights Reserved\n\n@Remark $VER: Version V1.0 (Oct 28 1993, 19:01:21)\n@Remark AmigaGuide database for the Verenaris Documentation for /X\n\n@node MAIN "Verenaris AmigaGuide Document (C) 1993 Mystic/X-DeSign (Oct 28 1993, 19:01:21)"\n\n\n\n              .: C O N T E N T S  O F  D O C U M E N T A T I O N :.\n              ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n                          @{"        Introduction        " Link Part01}\n                          @{"        Requirements        " Link Part02}\n                          @{" How to install the /X Door " Link Part03}\n                          @{"         Greetings          " Link Part04}\n                          @{"            Bugs            " Link Part05}\n\n                Docs done by @{" Re/Y\o/TekLords/Mystic/X-DeSign " Link LastDesire}.\n                       Install And Enjoy The Program ...\n@endnode\n@node Part01 "Introduction To Verenaris by Byteandi (Mystic/X-DeSign)"\n\n                              .: Introduction :.\n                              ~~~~~~~~~~~~~~~~~~\n\nWell it is very easy ... Verenaris will keep track of all uploads made by\nevery single user ... Verenaris will keep the data for one week and than\ngenerate a bulletin with the ten best uploaders ... After this week Verenaris\nwill start again with a new datafile and keep all uploads for another\nweek ... and so on...\n\nVerenaris is run everytime a user logs off ...\n\n@endnode\n@node Part02 "Requirements"\n\n                              .: Requirements :.\n                              ~~~~~~~~~~~~~~~~~~\n\nAll you need is an ©Amiga and ©Ami-Express version whatever ... For the rest\nyou need a few uploads and a lot of users ... The rest is for the @{"Installation" Link Part03}.\nIf you find any BUGS or have some SUGGESTIONS please leave Andi/Mst or\nRe/Y\\o/Tls/Mst a messy ... You will most certainly be able to find us \nat Last Desire, Diabolo or in the /X WHQ!\n\n\n@endnode\n@node Part03 "How To Install Verenaris by Byteandi (Mystic/X-DeSign)"\n\n                            .:Installation Guide:.\n                            ~~~~~~~~~~~~~~~~~~~~~~\n\nThe Program runs on all versions of Ami-Express.\n\nJust Add this line to every Logoff-script from each node you run ...\n\n~~~~~~~~~~~~~ <- Cut Here :)\n~~~~~~~~~~~~~\n<path_to_Verenaris>Verenaris nodex:Callerslog <path_to_Verenaris>\n\n~~~~~~~~~~~~~ <- Cut Here :)\n~~~~~~~~~~~~~\nWhere x in nodex is the nodenumber ... And <path_to_Verenaris> is the path\nwhere the datafiles come ... Verenaris itself however may be situated in\nanother directory ...\n\nMore configuration can be done by @{" ToolTypes " Link ToolTypes} which will\nmake life easier ... no configuration files etc ... Verenaris now supports \nmultiple upload paths you don''t have to configure this yourself ...\n\nThat should be all folks ...\n\n@endnode\n@node ToolTypes "Verenaris ToolTypes"\n\n                            .:  The ToolTypes  :.\n                            ~~~~~~~~~~~~~~~~~~~~~\n\n                          @{"        USERDATA        " Link Userdata}\n                          @{"         Conf.x         " Link Conf}\n                          @{"         Name.x         " Link Name}\n                          @{"         SYSOP          " Link Sysop}\n                          @{"       NO_MESSAGE       " Link NoMessage}\n                          @{"         SYSOP          " Link SYSOP}\n                          @{"        TOP_WEEK        " Link TOP_WEEK}\n                          @{"      TOP_UPLOADER      " Link TOP_UPLOADER}\n                          @{"         MAX_USER       " Link MAX_USER}\n                          @{"         NO_SYSOP       " Link NO_SYSOP}\n\n@endnode\n@node Userdata "USERDATA ToolType"\n\n\n                        .:  The USERDATA-ToolType  :.\n                        ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nThis is very important ... It gives the place where Verenaris can find the\nuserdata ... Do NOT forget this ...\n\n\ne.g.:                       USERDATA=bbs:user.data\n\n\n@endnode\n@node Conf "Conf ToolType"\n\n\n                        .:  The Conf.x-ToolType  :.\n                        ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nThis tells Verenaris where the conferences are situated ... For each conference\nyou put in here it will keep track of the uploads ... Don''t forget the ''/''\nbehind the pathname ...\n\ne.g.:\n                             Conf.1=bbs:conf-2/\n                             Conf.2=bbs:conf-3/\n                             Conf.3=bbs:conf-4/\n\nThis will generate datafiles for conferences conf-2, conf-3 and conf-4 ...\n\nIMPORTANT! IMPORTANT! IMPORTANT! IMPORTANT! IMPORTANT! IMPORTANT! IMPORTANT! \n\n   WE GENERATE THE BULLETINS IN THE MSGBASE FROM THE CONFERENCES \n   IF YOU WANT TO SHOW THE BULLETINS EVERY TIMES, YOU MUST CREAT IN \n   YOUR CONFERENCE`S THE BULL10.TXT AND MUST INSERT IN THIS BULL:\n \n~~~~~~~~~~~~~ <- Cut Here :)\n~~~~~~~~~~~~~\n~\n~f\n~SS_bbs:conf-1/msgbase/verenaris.bull\n\n~~~~~~~~~~~~~ <- Cut Here :)\n~~~~~~~~~~~~~\n\nYOU SEE THE FIRST BULLETIN, IF A USER HAVE UPLOADED ANY FILES,\nOTHERWIESE WE DONT CREAT ANY BULLS!\n\nIMPORTANT! IMPORTANT! IMPORTANT! IMPORTANT! IMPORTANT! IMPORTANT! IMPORTANT! \n\n@endnode\n@node Name "Name ToolType"\n\n\n                        .:  The Name.x-ToolType  :.\n                        ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nThis tells Verenaris what the name of the conferences are ... For each\nconference you put the name in here ... Don''t mix up the names with the\nconferences ... Make sure @{" Conf.1 " Link Conf} is the path to the conference with name\nName.1 ...\n\ne.g.:\n                             Name.1=Console Paradise\n                             Name.2=PC Land\n                             Name.3=\\// Land of Home \\//\n\nThis means @{" Conf.1 " Link Conf} is called "Console Paradise", @{" Conf.2 " Link Conf} is called "PC Land" and\n@{" Conf.3 " Link Conf} is called "\\// Land of Home \\//" ... These Names will appear in the\nmessages it will generate at the end of the week if this option is enabled ...\n\n@endnode\n@node Sysop "SYSOP ToolType"\n\n\n                         .:  The SYSOP-ToolType  :.\n                         ~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n\nYou have to add this ToolType otherwise you will get a message from SYSOP and\nnot from the Sysopname of your bbs ...\n\n\ne.g.:                        SYSOP=Andi/mst\n\n\nThis will make sure the message comes from Andi/mst and not from SYSOP ...\n\n\n@endnode\n@node NoMessage "NO_MESSAGE ToolType"\n\n\n                       .:  The NO_MESSAGE-ToolType  :.\n                       ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n\nYou can add this ToolType if you don''t want to have the message generated at\nthe end of the week ... This has nothing to do with the bulletins Verenaris \ngenerates ... It just doesn''t generate the message in the messagebase ...\n\n\ne.g.:                         NO_MESSAGE\n\nNothing to add behind this ToolType ...\n\n@endnode\n\n@node TOP_UPLOADER "TOP_UPLOADER ToolType"\n\n\n                       .:  The TOP_UPLOADER-ToolType  :.\n                       ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n\nYou can add this ToolType if you want to see All Times the best \nUploader from this Conference in the Vere-Naris Bulletin!\n\ne.g.:                         TOP_UPLOADER\n\nNothing to add behind this ToolType ...\n\n@endnode\n\n@node TOP_WEEK "TOP_WEEK ToolType"\n\n\n                       .:  The TOP_WEEK-ToolType  :.\n                       ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n\nYou can add this ToolType if you want to see All Times the best \nWeek-Statistic from this Conference in the Vere-Naris Bulletin!\n\ne.g.:                         TOP_WEEK\n\nNothing to add behind this ToolType ...\n\n@endnode\n\n@node MAX_USER "MAX_USER ToolType"\n\n\n                       .:  The MAX_USER-ToolType  :.\n                       ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n\nYou can add this ToolType if you want to set up how many Top Uploader\nYou want to have, you can set it up from 1 to 15\n\ne.g.:                         MAX_USER=<x>\n\n       x <-- How many Uploader you want to have in the Bulletins\n\n\n@endnode\n\n\n@node NO_SYSOP "NO_SYSOP ToolType"\n\n\n                       .:  The NO_SYSOP-ToolType  :.\n                       ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n\nYou can add this ToolType if you dont want to search how many Uploads \nthe Sysop have done!\n\ne.g.:                         NO_SYSOP\n\nNothing to add behind this ToolType ...\n\n@endnode\n\n\n@node Part04 "Greetings To EveryOne"\n\n                               -G-R-E-E-T-I-N-G-S-\n\n  Many Greetings to Empire and the Other @{" Member from (Mystic/X-Design) "LINK MSTMEMBER}\n\n  Killraven, Fuzzy, Axe....\n\n  THX to Spy because he helped me to learn C  and invested many \n  Time in my Doors\n\n  Many Many THX To All my Beta tester for BugReports, Hints and Tips\n  to install Options....in that Door...\n\n  To All Friends over the Globe wich Knows us!\n\n             //\n  Thanx to \X/ Amiga For Being The Best Computer Ever made ...\n\n\n\n\n            And some other wonderfull Ami-Express Tool Programmers ...\n\n                                 @{" 5th  Dynasty " Link 5thDynasty}\n\n                            And Last But Not Least ...\n\n             All Ex-Members Of AFL That We Have Met Over The Years...\n\n\n@endnode\n\n@node 5thDynasty\n\n\n               5th______  ___  __  ___   _____  _. ___  ___\n               \\__   \\  \\/  /_|  |/___\\ / ___/_/ |_\\  \\/  /\n                |  |  \\_/ _/__\\  |  /  |___  \\_   _/\\_/ _/\n                |  |  ||  ||  \\\\_| /   |     ||   |  |  |\n                |  |  ||  ||  |\\_| \\_  |SNOW ||   |  |  |\n                |_____||__||__|__|__|__|_____||___|  |__|\n\nIf you want to program something yourself ... just ask us for the source and we\nwill see what we can do ... Will probable give you the source with\ndocumentation included so you know what you see in it ...\n\nP.S.: Nothing Personal ... Just nice to have some people around who can\nprogram as good as other people already did ... Always nice to have people\naround who want to give you their sources ...\n\n@endnode\n\n\n@node MSTMEMBER "ALL MEMBERS FROM (MYSTIC/X-DESIGN)"\n\n                      ______  __________________          \n               +-----/    \ \/ / __/_  __/ / __/----------+\n               |----/ / / /\  /\  /-/ /-/ / /----[ /X ]---|\n               |----\/ / /-/ /\  /-/ /-/ /\ \--[ DESiGN ]-|\n               +-----\/\/--\/--\/--\/--\/--\/-------------+\n               |                                          |\n               |   EMPiRE   -   @{"BYTEANDi" LINK DIABOLO}   -  CRACKDOWN   |\n               |   TYCOON   -   KiLLRAVEN  -   SiEGEL     |\n               |   FUZZY    -     SPY      - Re/Y\o       |\n               +------------------------------------------+\n@endnode\n@node DIABOLO "Advert"\n                        ·  :                 .     :     :\n-============-   \____ ¬V ¬V___ ¬V___ ¬V___ ¬V ¬|  |___ ¬|   MANAGEMENT\n(Mystic/X-Design) | ¬|  |  | ¬|  | ¬|  | ¬|  |  |  | ¬|  |   -========-\n      WHQ         |  |  |  |  |  |  |  |  |  |  |  |  |  |   ANDi/MST\n-============-    |  |  |  |     |    _|  |  |  |__|  |  |   SPY/MST\n                  |  |  |  |  |  |  | ¬|  |  |  | ¬|  |  |   FELDMAN\n-ELiTE oNLY-      |  |  |  |  |  |  |  |  |  |  |  |  |  |   FuZzY/MsT\n                  |  |  |  |  |  |  |  |  |  |  |  |  |  |   Wolfmann/TRSI\nCALL US NoW FoR   |  |  |  |  |  |  |  |  |  |  |  |  |  |   -====-\nTHE NEWEST AMiGA/ |  |  |  |  |  |  |  |  |  |  |  |  |  |   RUNS oN A3000\nPC&Console STUFF  |  |  |  |  |  |  |  |  |  |  |  |  |  |   WiTH 25MHZ AND\nAND ALL MST-      |  |  |  |  |  |  |  |  |  |  |  |  |  |   AMiEX (REG.)\nRELEASES.         |  |  |  |  |  |  |  |  |  |  |  |  |  |\n                __|_____A__A__A__A_____A_____A_____A_____|D! SUPPoRTED BY\nWE oNLY ACCEPT    |     :  :     :     :     :     :     |   -==========-\n9600 - 16.800     :     ·  .     .           .     ·     :   M Y S T I C\nBAUD CoNNECTS.    .        .                                      \n                         Node0  +49 (0) 30-6221994   HST\n                         Node1  +49 (0) 30-6212312   Zyxel\n                         Node2  +49 (0) 30-6218787   Dual\n\n@endnode\n\n@node Part05 "Bugs"\n\nVerenaris V1.1  changed the MsgData Routine because there to many sysops\n                wich fakes in the headerfiles!\n                changed some Routines to search for the UserName and Handle\n                in the User.Data and have no more stress with some errors \n                in the Callerslog\n\n\n@endnode\n\n','\n',char(10)),NULL,'auto-added',24813,5,0,NULL,NULL,'mst_vere','scan',1780048619);
INSERT INTO door_catalog VALUES('mst_vw10','MST-VW10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MST-VW10.LHA','MST-VieW','XIM','MST-VieW',NULL,NULL,'MST','+---/    \ \/ / __/_  __/ / __/------------+ |--/ / / /\  /\  /-/ /-/ / /-----SieGeL----| |--\/ / /-/ /\  /-/ /-/ /\ \---- MYSTiC----|',replace('     ______  __________________             \n+---/    \ \/ / __/_  __/ / __/------------+\n|--/ / / /\  /\  /-/ /-/ / /-----SieGeL----|\n|--\/ / /-/ /\  /-/ /-/ /\ \---- MYSTiC----|\n+---\/\/--\/--\/--\/--\/--\/---/X-DeSiGN---+\n|  MST-VieW V1.0 - TeXTVieWeR FoR /X V3.x  |\n| SUPPORTS WILDCARDS - LHA/LZH/DMS/ZIP/ARJ |\n| SHR/EXE VIEWING/TESTING - SYSOPVIEW - NS |\n+------------------------------------------+\n','\n',char(10)),'MST-VIEW.GUIDE',replace('@database MST-VieW V1.0 DoCS\n\n@node Main "MST-VieW V1.0 - /X uTiL WRiTTeN BY SieGeL/MsT"\n                                :                                          \n   ________               :     ¦ (MYSTiC/X-DeSiGN)  /\                    \n   \       \  ____________¦    _|_ ___________ _____/_ \_ _ __________ __ _\n    \______ \/ __ _ _/    |    \\\\\_       /\\\_    /__/\\\\__      //_///\n     /     \  /     \     |    _/   /______/     _  /   \    _/     /      \n   _/       \/       \_____   _\______    \_      \/     \_  \_____/\_     \n   \        ||        /   /   \      /     /      |       /          /     \n    \ ______||______ /_________\_________ /_______|_____ /_________ /      \n     \/         iS \/ BaCK WiTH aNoTHeR \/ PRoDuCTioN :\/     Rpd!\/ \n                                   \n                          MST-VieW V1.0 BY SieGeL/MST\n\n       ···C·O·N·T·E·N·T·S··O·F··T·H·I·S··D·O·C·U·M·E·N·T·A·T·I·O·N···\n       ·                                                            ·\n       ····>@{"     iNTRoDuCTioN     " LINK INTRODUCTION}<·····>@{" aLL FoR iNSTaLLATioN " LINK REQUIREMENTS}<····\n       ·                                                            ·\n       ·                        @{" FEATURES! " LINK FEATURES}                        ·\n       ·                                                            ·\n       ····>@{"      TOOL-TYPES      " LINK TOOLTYPES}<·····>@{"     FINAL SALUTE     " LINK END}<····\n       \n                      DoCFiLe WRiTTeN BY SieGeL/MST\n@endnode\n\n@node INTRODUCTION "iNTRoDuCTioN"\n\nMST-View...what''s that ? Well, after a long time of reading the boooring \nmessage "You may not include any special Symbols", I decided to write a \nnew Viewer for /X, coz I hate it to write down the complete name for a \nfile which i want to read. So here it is....MST-VIEW ! \n\nFeatures are :\n\n - Supports Wildcards (*)\n\n - Viewing Files directly from an LHA/LZH/SHRINK/ZIP-Archive\n\n - Integrated Sysop-View (editable via @{"Tooltypes" LINK TOOLTYPES})\n\n - Securitycheck for @{"RESTRICTED FILES" LINK RESTRICT} from ACP-Info\n\n - DMS/ARJ/EXE-Checker supported\n\n - Don''t break viewing if a character with ascii-value >128 was found...\n\n - Supports ''NS'' to view files NonStop...useful for BBS-Adverts..\n\n - Could Extract and show FILE_ID.DIZ from EXEcutables or DMS-Archives\n\n - Extraoption to choose at which Accesslevel a user could view (and test of\n   coz :-} ), otherwise he could only test files/archives...\n\nand many other cewl Functions....if ya now interested, then @{"install" LINK REQUIREMENTS} it \nto your /X-System...:)\n\n@endnode\n\n@node REQUIREMENTS "aLL FoR iNSTaLLaTioN"\n\n\nFirst U need...\n~~~~~~~~~~~~~~~\n\n - an Amigamodel (A500/A600/A1200/A2000/A3000/A4000) with Kickstart 2.04++\n\n - the installed /X-Software (Tested only on /X 3.xx..don''t know if it\n   runs correctly under /X 2.xx...if someone could test it please @{"inform" LINK ADVERT}\n   me !)\n\n - For LHA/LZH/SHRINK/DMS/ZIP/ARJ/EXE-Support you need the packers (Tested \n   with LHA V1.50r, DMS V1.11/V1.51/V1.53, SHRINK V1.11, UNZIP V5.13ß, \n   UnARJ V1.15,CHECKEXE V1.0ß)\n\n - For FILE_ID.DIZ - Support you need DMSDESCRIPT/EXEDESCRIPT written by\n   @{"Remo/Mystic" LINK MSTMEMBER}\n\n - The Device PIPE: already mounted (Used for testing archives...!)\n\n - Some files to view....:)\n\nTo install MST-VieW, copy ''MST-VieW'' & ''MST-VieW.info'' to the directory\nwhere you stored your /X-Tools.\n\nNOTE: Make sure that you place the icon in the same directory like the main\n      program, otherwise MST-VieW couldn''t find it...!\n\nNow copy the "V.INFO" icon to BBS:COMMANDS/BBSCMD/ \n\nNOTE: For SYSOPVIEW you don''t have to copy another Icon called ''VS'' into \n      your BBSCMD/ Drawer, coz MST-VieW checks it with his own ToolType!\n\nThat''s all for installation...now some words about the notable @{"FEATURES" LINK FEATURES} of \nMST-VieW...\n@endnode\n\n@node FEATURES "WHY USING MST-VIEW ?"\n\nI don''t believe that you have any problems, coz MST-VieW works similar\nto the original, but has some more powerful enhancements, like :\n\n1.) You could use NS\n~~~~~~~~~~~~~~~~~~~~\nIf you want to view a file Nonstop, that means that MST-VieW don''t prompt\nyou to continue,etc., all you have to do is to enter NS after the Filename,\ni.e.:\n\n                           Diabolo.doc NS \n\nwill show Diabolo.doc nonstop..or if you enter :\n\n                              Dia* NS \n\nMST-VieW search for all patterns matching "DIA*" and then show the desired \nfile nonstop.\n\nThis works anywhere, you could enter as third parameter NS and the file\nwill be shown nonstop.\n\n\n2.) Using WildCards \n~~~~~~~~~~~~~~~~~~~\nThis Feature was the main reason why I wrote MST-VieW ...:) \n\nYou could use wildcards as much as you want it to do so...:) , and in \ndifference to AmieX, you DON''T have to enter three real Chars before\nusing Wildcards, so you could call MST-VieW like:\n \n                       "V S:START*" \n\n...searches for files in S:, which contains the pattern START*..or \nenter something like this :\n\n                       "V S:SH*LL-ST*ART*P" NS\n\nwill search for all patterns which matches the pattern and then show the\ndesired file NonStop\n  \n                       "V S:*"\n\n...shows you ALL files which are found in Drawer S:...this works also for\nthe "normal" viewmode (NO SYSOPVIEW), i.e.\n\n                       "V *"\n\nshows you ALL files which are found in the current upload pathes. Nice eh ?! :)\n\n3.) Testing Archives\n~~~~~~~~~~~~~~~~~~~~\nIf you select a archive, you have always the choice to test it. If MST-VieW\nrecognize a archive, you were asked to view the contents/informations...\nenter now ''T'' and the desired archive will be tested...hope you enjoy the\nrealtime testings via PIPE: ...:)))\n\n@endnode\n\n\n\n@node TOOLTYPES "aLL FoR TooLTYPeS & oTHeR CoMMaNDS"\n\n                     All Tooltypes from MST-VieW V1.0 :\n                     ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n                             @{"    LHA_PATH    " LINK LHA}       \n                             @{"    DMS_PATH    " LINK DMS}\n                             @{"  SHRINK_PATH   " LINK SHRINK}       \n                             @{"    ZIP_PATH    " LINK ZIP}\n                             @{"    ARJ_PATH    " LINK ARJ}          \n                             @{"    EXE_PATH    " LINK EXE}\n                             @{"   EXE_FILEID   " LINK EXEID}\n                             @{"   DMS_FILEID   " LINK DMSID}            \n                             @{" SYSOPVIEWLEVEL " LINK SYSOPVIEW}       \n                             @{"   ONLY_CHECK   " LINK ONLYCHECK}\n                             @{"   CALLERSLOG   " LINK CALLERSLOG}\n                  \n@endnode\n\n@node LHA "LHA/LZH-SUPPORT"\n\n\n			   LHA_PATH=<path>  \n\nIf you want to allow users to view Files inside LHA/LZH-Archives, you \nhave to enter the complete path to your LHA,i.e.\n\n                          "LHA_PATH=C:LHA". \n\nIf you don''t specify the path and a user selects a LHA-Archive, MST-VieW \nquits with a message :\n                        "LHA-SUPPORT NOT ALLOWED"\n\nNOTES TO LHA-SUPPORT:\n~~~~~~~~~~~~~~~~~~~~~\nIf you specify <path> correctly, and a LHA-Archive is selected, MST-VieW\nasks you to view the contents of the selected archive. After reading the\ncontents, LHA shows you only the Filenames used inside the archive. \nWhen you are prompted to enter the complete Filename, you COULDN''T use\nWildcards. A leading space as a Filename is not allowed, too. I have\ndisabled the wildcardoption here, coz if you enter "*" or " " as filename, \nLHA extracts the whole archive into RAM: !!!! If you enter a Filename \nthat doesn''t exist in this archive, MST-VieW prompts you again to enter\nthe correct Filename. Filenames beginning with - could not be read coz LHA\ninterprets them as commands, not as filenames...don''t understand why, but\nwho carez...:) \n\nAfter some Betatesting, I included a Memorycheck,that means, the file you\nwant to extract from an archive will be checked if it fits into memory...\nif not, you will be asked to test the archive instead. I have to check it\ncoz if RAM: has not enough room an errorrequester appears which contains:\n"VOLUME RAM IS FULL!" ...and the Node fucks up!!! But now it couldn''t happen\nanymore (I hope so ...:> )\n\n@endnode\n\n@node DMS "DMS-SUPPORT"\n\n                          DMS_PATH=<path> \n\nHere you have to specify the complete path to your DMS-Checker, i.e. \n                              \n                         "DMS_PATH=C:DMS"\n                              \nIf a user selects a DMS-Archive and <path> is a valid pathname, MST-VieW \nasks you to view informations about the DMS-Archive, otherwise MST-VieW \nquits with the message:\n                      \n                      "DMS-SUPPORT NOT ALLOWED"\n\nNOTES TO DMS-SUPPORT:\n~~~~~~~~~~~~~~~~~~~~~\nFor DMS-Support I''m using DMS V1.53 . MST-VieW calls DMS with the argument \nVIEW and redirects output to a file. Then this file will be read and shown \nto the user. 				\n\nIf you specify the Tooltype @{"DMS_FILEID" LINK DMSID} MST-VieW searches\nfor the FILE_ID.DIZ after displaying the archiveinformations. If a \ndescription was found, MST-VieW asks you to view it or not. Thx goes\nto @{"ByteAndi/MST" LINK MSTMEMBER} for this suggestion and @{"Remo/MST" LINK MSTMEMBER} for the Program... \n\n@endnode\n\n@node SHRINK "SHRINK-SUPPORT"\n\n                        SHRINK_PATH=<path>\n\nHere you specify the complete path to your SHRINK-Packer, i.e.\n\n                      "SHRINK_PATH=C:SHRINK"\n\nIf a user selects a SHRINK-archive (extension *.SHR!) and <path> is a\nvalid pathname, you have the choice between viewing contents or not. If \nthis Tooltype is not set correctly, MST-VieW quits with the message:\n\n                   "SHRINK-SUPPORT NOT ALLOWED"\n\nIf you set it correctly, MST-VieW asks the user to view the contents of\nthe desired archive or not. After displaying the contents, you are \nprompted to enter the complete filename. Like @{"LHA/LZH-Support" LINK LHA}, Wild-\ncards are not allowed. Enter the complete name of the file you want to\nview and MST-VieW "unshrinks" the file and displays it to you.\n\nNOTE: In difference to LHA, you have to enter the complete Filename\n      with path, i.e.: \n    \nShrink: V1.1    ©1992 by Matthias Meixner                            \nAll rights reserved. Not for commercial use.                         \nPacker: shrink                                                       \nOriginal Packed Ratio  Date     Time   Mode Gen CRC  Name            \n-------- ------ ---- -------- -------- ---- --- ---- ----------      \n     146    109 25.3  5-07-93 14:46:18   7    1 1aa3 ASM-One.Pref    \n    4527   1833 59.5 12-12-93 16:00:52   7    1 7ced ced/Compile.ced \n\nif you want to view compile.ced, you have to enter "CED/COMPILE.CED", \notherwise MST-VieW can''t find the file...\n\nIf you have entered a name that doesn''t exist inside the archive, MST-VieW\ntries to unshrink it and aborts with a Errormessage. I try to fix this\nproblem, but Shrink doesn''t support the feature to show the contents\nof an archive only by names like LHA do...\n\n@endnode\n\n@node ZIP "ZIP-SUPPORT"\n\n                          ZIP_PATH=<path>\n\nHere you specify the complete path to your ZIP-Packer, i.e.\n\n                         "ZIP_PATH=C:UNZIP"\n\nIf you set ZIP_PATH to a valid path, users have the option to view files\nfrom ZIP-Archives, otherwise MST-VieW quits with an errormessage.\n\nWhen MST-VieW shows the contents of the desired ZIP-Archive, you are\nprompted to enter the Name you want to read. UnZIP writes a character (^)\nbefore each filename. You don''t have to enter this character, it''s only\nthe Characterconversion-Flag...don''t know what this means...\n\nNOTE: MST-VieW checks the length of the desired file to extract and compares\n      it with STDOUT, which will be normally the Drawer you started ACP from.\n      If the file is to large to extract to STDOUT, MST-VieW automatically\n      checks the desired archive instead. I don''t like the method to extract\n      only to STDOUT, but UnZIP don''t support specifing the extract path...\n      if someone has a version from UnZIP which supports this Feature, please\n      give it to me so i will implement this as fast as possible...look under\n      @{"CONTACT" LINK ADVERT} for adress...  \n\n@endnode\n\n@node arj "ARJ-Support"\n                          \n                          ARJ_PATH=<path>\n\nHere you specify the complete path to your ARJ-Packer, i.e.\n\n                         "ARJ_PATH=C:ARJ"\n\nIf you set ARJ_PATH to a valid path, users have the option to view the\ncontents of the desired .ARJ-archive, otherwise MST-VieW quits with an\nerrormessage.\n\nNOTE: I''m using ARJ V1.15 by Harald Schneider. In this version, you could\n      only extract the WHOLE (!) archive, not only single files. What a\n      lameless...so MST-VieW V1.0 could only show you the CONTENTS of\n      the desired archive. I don''t know if there''s another (better!) \n      version from ARJ which has the ability to extract single files, if\n      someone could send me such a version I will implement this feature\n      into MST-VieW as fast as possible in a later version. Look under\n      @{"CONTACT" LINK ADVERT} for address.\n\n@endnode\n\n@node EXE "EXEcutable-Support"\n\n                           EXE_PATH=<path>\n\nWell, until now the only EXE-Checker I know is ''CHECKEXE V1.0ß" written by \nShagratt/LSD! ...so if you specify the correct path to this checker, Users\ncould now check executables...and if you specify the Tooltype @{"EXE_FILEID" LINK EXEID}\nMST-VieW searches for the FILE_ID.DIZ, which could be added to Executables\nvia EXEDESCRIPT written by Remo/MST ...When a Description was found you were \nasked to view it or not...have fun ..:)\n\n@endnode\n\n@node EXEID "FileID.Diz - Support for Executables"\n\n                        EXE_FILEID=<path>\n\nWith this Tooltype you specify the path to EXEDESCRIPT, written by @{"Remo/MST" LINK MSTMEMBER}.\nThis Tool allows you to add/extract/Delete a Filedescription to an Exe-File.\nIf you specify this Tooltype, MST-VieW will search for a description, and \nif there is one, you will be asked to view it or not.\n\n@endnode\n\n@node DMSID "FileID.Diz - Support for DMS-Archives"\n\n                        DMS_FILEID=<path>\n\nWith this Tooltype you specify the path to DMSDESCRIPT, written by @{"Remo/MST" LINK MSTMEMBER}.\nThis Tool allows you to add/extract/Delete a Filedescription to an Exe-File.\nIf you specify this Tooltype, MST-VieW will search for a description, and\nif there is one, you will be asked to view it or not.\n\nDMSDESCRIPT/EXEDESCRIPT will be released with the newest Version from \n@{"ByteAndi''s" LINK MSTMEMBER} ''FileID'', which comes out in the next time...\n\n@endnode\n\n@node SYSOPVIEW "SYSOPVIEW ?!"\n\n                      SYSOPVIEWLEVEL=<level>\n\n\nHere U define at which Accesslevel a user could use SYSOP-VIEW...that \nmeans a user has the abillity to view files which are not be found in \nthe regular BBS-Path (i.e. S:SHELL-STARTUP).\nif a user has the correct Accesslevel to use this option, he could view \nyour @{"RESTRICTED FILES" LINK RESTRICT} with option "?", that means, enter "V ?" in /X \nMain Prompt and u get a list of all files not allowed to be viewed.\n\nIf a User has the accesslevel for Sysopviews, the @{"ONLY_CHECK" LINK ONLYCHECK} - Option\nis disabled, so this user could ALWAYS view files... \n\nNOTE TO SYSOPVIEW:\n~~~~~~~~~~~~~~~~~~\nIf someone tries to view @{"RESTRICTED FILES" LINK RESTRICT}, and you enabled adding \n@{"Comments to CallersLog" LINK CALLERSLOG}, MST-VieW adds a comment like : \n\n           "MST-VIEW:USER TRIED TO VIEW S:STARTUP-SEQUENCE..."\n\nIf you have disabled this option, MST-VieW quits with an errormessage.\n\nIf you want to use SYSOPVIEW-Option, you have to enter the complete path\nto the file you want to read...Wildcards allowed of course....:) \n\n@endnode\n\n@node ONLYCHECK "View or Test ? That''s the question..."\n\n                         ONLY_CHECK=<access>\n\nWith this Tooltype you specify at which Level a user could view files, i.e.\nif you set this to ONLY_CHECK=150 means, all users with accesslevel 150 or\nhigher could view files, all other users could only check/test files/archives.\n\nNOTE:If a user has the accesslevel to @{"SYSOPVIEW" LINK SYSOPVIEW}, this Tooltype\n     is disabled, of coz...\n\n@endnode\n\n@node CALLERSLOG "CALLERSLOG ?"\n\n                          CALLERSLOG=YES|NO\n\nIf you set CALLERSLOG=YES, MST-VieW will add a comment to the callerslog\nif a user tries to view restricted Files. \n\nSetting CALLERSLOG=NO disable the adding to callerslog. In this case,\nMST-View exits with a message.\n\nNOTE:If you enable this option and your BBS is a MultiNode-System, it \n     could happen that your computer crashes while MST-VieW is adding the\n     comment...that''s no Bug from me!!! /X has a bug which sometimes\n     produces a GURU MEDITATION while adding the comment. I can''t say\n     if all /X Versions have still this bug inside...if you don''t know it,\n     enable this option and try it out...if ya get Gurus, disable it!\n\nBig THX to @{"ByteAndi/MST" LINK MSTMEMBER} for this suggestion...\n\n@endnode\n\n@node RESTRICT "Infos about Restricted Files..."\n\nWell, /X has the ability to protect Files for downloading,deleting,etc.\nTo use this protection, you have to enter RESTRICT.<x>=<path> to your\nACP.ICON. <x> is the number of the restricted File, <path> is the full\npath to the file which should be protected, i.e.\n\n              RESTRICT.0=S:STARTUP-SEQUENCE\n\nif someone tries to view S:STARTUP-SEQUENCE, MST-VieW quits with an\nerrormessage and if @{"CALLERSLOG" LINK CALLERSLOG} is enabled, a comment will be \nadded to the callerslog, too.\n\nNOTE:Make sure that you start your BBS via Workbench, otherwise MST-VieW\n     can''t find your ACP.ICON, and @{"SYSOPVIEW" LINK SYSOPVIEW} is disabled !\n\n@endnode\n@node END "GREETZ AND ADVERTS"\n\nByteAndi/MST  - Thanx for the cewl help in the last few weeks..\n\nArgon/MST     - Everything went cewl...go on tradin'' man...:)\n\nSeCaM         - Don''t be worry...your Tools will be ready in the next days!\n\nExecutor/DCS  - Cewl Board...go on !\n\nDelta-X       - U.D.O.-Land roolez...ehehhehe....:)\n\nRapid/FTH!    - THX FoR diz great MYSTIC-Logo ... cewl Painting Dude !\n\nGEE           - A M I G A   R O O L E Z   ! ! !  ... :)))\n\nStrider/PGS   - Hi Guy...nothing heard from you too.....?? What''s up ?\n\nBloodRock/SDC - Cewl Library, will use it in a l8ter update...ASM ROOLEZ!\n\n SYNDICATE    - Cewl Production (5:12) ...Best Greetings back...:)\n\n          ...and of coz our ß-Tester and all other MST-Member...\n\nIf you find any Bugs or want to get in touch with @{"(MYSTiC/X-DeSiGN)," LINK MSTMEMBER}\ncall our Boards and leave a mail or call @{" DiaBoLo BBS " LINK ADVERT}.\n\n                         And always remember :\n\n "THE ONLY WAY TO MULTITASK ON MS-DOS, IS TO RUN IBeM TWICE ON AN AMIGA!"\n\n@endnode\n\n@node MSTMEMBER "aLL MeMBeRS FRoM (MYSTiC/X-DeSiGN)"\n\n                      ______  __________________           \n               +-----/    \ \/ / __/_  __/ / __/----------+\n               |----/ / / /\  /\  /-/ /-/ / /----[ /X ]---|\n               |----\/ / /-/ /\  /-/ /-/ /\ \--[ DESiGN ]-|\n               +-----\/\/--\/--\/--\/--\/--\/-------------+\n               |                                          |\n               |   EMPiRE   -   BYTEANDi   -  CRACKDOWN   |\n               |   TYCOON   -   KiLLRAVEN  -   SieGeL     |\n               |   FUZZY    -     SPY      -  Re/Y\o      |\n               |                [-Bobo-]                  |\n               +------------------------------------------+\n\n@endnode\n\n@node ADVERT "DiaBoLo BBS (MYSTiC/X-DeSiGN) WHQ"\n\n          \n           TO GET IN TOUCH WITH (MYSTiC/X-DeSiGN), CALL THE FAMOUS\n\n\n                         ·  :                 .     :     :\n -============-   \____ ¬V ¬V___ ¬V___ ¬V___ ¬V ¬|  |___ ¬| MANAGEMENT\n  MYSTIC           | ¬|  |  | ¬|  | ¬|  | ¬|  |  |  | ¬|  | -========-\n       GHQ         |  |  |  |  |  |  |  |  |  |  |  |  |  | ANDi/MST\n -============-    |  |  |  |     |    _|  |  |  |__|  |  | SPY/MST\n                   |  |  |  |  |  |  | ¬|  |  |  | ¬|  |  | FELDMAN\n -ELiTE oNLY-      |  |  |  |  |  |  |  |  |  |  |  |  |  | FuZzY/MsT\n                   |  |  |  |  |  |  |  |  |  |  |  |  |  | SYSTEM\n CALL US NoW FoR   |  |  |  |  |  |  |  |  |  |  |  |  |  | -====-\n THE NEWEST AMiGA/ |  |  |  |  |  |  |  |  |  |  |  |  |  | RUNS oN A3000\n PCSTUFF           |  |  |  |  |  |  |  |  |  |  |  |  |  | WiTH 25MHZ AND\n AND ALL MST-      |  |  |  |  |  |  |  |  |  |  |  |  |  | AMiEX (REG.)\n RELEASES.         |  |  |  |  |  |  |  |  |  |  |  |  |  |\n                 __|_____A__A__A__A_____A_____A_____A_____| SUPPoRTED BY\n WE oNLY ACCEPT    |     :  :     :     :     :     :D!   | -==========-\n 9600 - 16.800     :     ·  .     .           .     ·     : M Y S T I C\n BAUD CoNNECTS.    .        .                                      \n                       Node0  +49 (0) 30-6221994   HST  \n                       Node1  +49 (0) 30-6212312   Zyxel \n                       Node2  +49 (0) 30-6218787   Dual\n@endnode\n','\n',char(10)),NULL,'auto-added',104732,5,0,NULL,NULL,'mst_vw10','scan',1780048619);
INSERT INTO door_catalog VALUES('mst_wall','MST-WALL.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MST-WALL.LHA',NULL,'XIM','wall.020 (MST)',NULL,':','MST','_/  v  \__/ ! \  /  _____.   ._(__)/  . \ \_ _:_ ______  \/\___  \ |   | |  \_  |_/\ _/  \ /  \_  v  __   v   \|   | |    _ |   \',replace('   _____    ___    _____________.__. ____   \n _/  v  \__/ ! \  /  _____.   ._(__)/  . \  \n \_ _:_ ______  \/\___  \ |   | |  \_  |_/\ \n_/  \ /  \_  v  __   v   \|   | |    _ |   \\n\    v    /  ___/\    ___/!___! !___/__-   /\n-\___:___/___/-ã!-\___/---------------\___/-\n--------------------------------------------\n/X Tough Wall 1.0  XIM Door By : Dea & Neuro\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                                                .------''\n             `------------------------------------------------''\n','\n',char(10)),NULL,'XIM-BBSCmd',56157,7,0,NULL,NULL,'mst_wall','scan',1780048619);
INSERT INTO door_catalog VALUES('mst_wh20','MST-WH20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MST-WH20.LHA','Count','XIM','NI',NULL,NULL,'MST','+---/    \ \/ / __/_  __/ / __/------------+ |--/ / / /\  /\  /-/ /-/ / /---Spy---------| |--\/ / /-/ /\  /-/ /-/ /\ \----Mystic-----|',replace('     ______  __________________\n+---/    \ \/ / __/_  __/ / __/------------+\n|--/ / / /\  /\  /-/ /-/ / /---Spy---------|\n|--\/ / /-/ /\  /-/ /-/ /\ \----Mystic-----|\n+---\/\/--\/--\/--\/--\/--\/-----/X-DeSign-+\n| THE ULTIMATIVE WHO SEARCH FOR QUITE NODE |\n|AND FULL CONFIGURABLE TO SEE UP-DOWNLOADS!|\n|VERSION 2.0 SUPPORTING 32NODES&NEW OPTIONS|\n','\n',char(10)),'who_english.doc',replace('\n                WHO V1.0 Written by Spy (MySTiC /X DESiGN)\n                        GfX by Byteandi (MySTiC /X DESiGN)\n         NI (NodeIn) & NO (NodeOut) Written by Spy (MySTiC /X DESiGN)\n                 COUNT written by Spy (MySTiC /X DESiGN)\n\n\n\n************************ Tools-Description  ***********************************\n\nWHO   - WHO-DOOR also taken as Frontwho\n        Features :\n                   To the normal informations like username, location, node-\n                   number and action comes also now the phonenumber and the\n                   number of calls per node. You can also see the filenames\n                   per node, if an upload or a download is be made. Depending\n                   the userlevel you can show the filenames or not (to be changed\n                   in WHO.INFO). If you start up the WHO as a frontdoor the\n                   filenames will not be shown (SECURITY ;) )\n                   If quietnode is On it`s also not shown to the users. It`s\n                   not even shown if they switched on the quiet in the NI-DOOR\n                   (see NI-DOOR).\n                   Important for Sysops : You can change in WHO.INFO at\n                                          starting at which level you can see\n                                          the user, even if he did the\n                                          quietnode.\n\nNI    - NODEIN-DOOR Shows on the other nodes that a user enters the bbs. You\n                    can also allowed certain users in the NI.INFO that this\n                    message will not be shown on the other nodes. Then they are\n                    going to get a question if they want to be seen or not.\n                    If the quietnode was already switched on on this node\n                    the question will not be asked.\n\nNO    - NODEOUT-DOOR Shows on the other nodes that a user leaves the bbs.\n                     If the quietnode was already switched on on this node\n                     it will be automatically shut off by NO, depending if\n                     you changed it in the NO.INFO (see NO.INFO)\n\n\ncount - Counts every call on a node. You can start up this tool in the logoff\n        script.\n\n\n************************* Installation description ****************************\n\nAfter unpacking WHO.LHA there will be 2 directorys : doors/ and bbs/  .\nThe containing of the directory doors (the dir who/ ) will be copied in the\ndoors: directory.\nIn the directory bbs/ will be 2 underdirectories and 2 files :\n\nThe directory commands/ :\n-------------------------\nThere are also 2 underdirectories :\nbbscmd/ and syscmd/\nThe containing of the directories comes in certains directories in bbs:commands/\ndirectory.\n\nThe directory node-0/ :\n-----------------------\nIn this directory exists 1 file : logoff10.txt\nThe door NO will be started up at the logoff out of the logoff10.txt. Because\nof that the text out of the logoff10.txt must be hang up in front of the still\nexisting logoff.txt or the file logoff10.txt will be copied in each node\ndirectory\n\nIn the directory bbs/ will be 2 files left :\n--------------------------------------------\nbull10.txt - This file will be hang on in front of an still existing beginning\n             bulletin, or if this doesn`t exist it must be copied in the\n             directory bbs: . The door NO will be started out of this text.\n\nAddToYourLogoffBatch - The containing of this file must be shown in each\n                       logoff batch of each node. In this logoff batch the\n                       tool count will be started. It get`s the nodenumber\n                       For node 0 would be f.ex. : doors:who/count 0\n                       For node 1 would be f.ex. : doors:who/count 1\n                       That means, you copy the line out the\n                       AddToYourLogoffBatch file in each logoff batch file\n                       an changes the node number in case.\n\nThat was evereything about the installation\n\n\n\n******************** How to change the info files ****************************\n\nWHO.INFO : Following tooltypes are possible : Level_to_see_up/dl\n                                              Level_from_sysops\n                                              PhoneNumber.Number\n                                              Do_not_show_Node.Number\n\nLevel_to_see_up/dl : Here you can change the userlevel, where it depends\n                     that the user can see the upload or download filename.\n                     Level_to_see_up/dl=20 would allowed it starting at\n                     security level 20, that the user can see the up- or download\n                     filename. If the level is higer than 255, no user (not even\n                     the sysop) can see up or download filenames. If the level\n                     is 0, each user can see up or download filenames.\n                     But : You never see the up or download filenames in the\n                           Frontwho, no mattering how low the level is.\n\nLevel_from_sysops  : This tooltype shows, beginning when a user can also see\n                     users on nodes which are quiet. Level_from_sysops=255\n                     would only allowed users with level 255 to see nodes which\n                     are quiet. If this number is higer than 255 no user can see\n                     a quiet node. If the number is 0 every user can also see\n                     nodes which are quiet.\n\nPhoneNumber.Number : This tooltype shows which phonenumber will be shown on a\n                     node. PhoneNumber.0=+49 (0)30 745 20 93 would show on\n                     Node 0 the phonenumber +49 (0)30 745 20 93.\n                     PhoneNumber.1=+49 (0)30 745 20 94 would show on node 1\n                     the phonenumber +49 (0)30 745 20 94\n\nDo_not_show_Node.0 : This tooltype gives the possibility (out of the who) that\n                     the certain node will not be shown for example with a\n                     local node. At Do_not_show_Node.3 the who would not\n                     show the 3rd Node.\n\n\n\nNI.INFO : Here it gives only 1 possible tooltype :\n\nName.1=Spy/MST would allow Spy/MST to be not shown to other users. He would\nget a question if he wants to be seen from the other nodes.\n\nName.2=Cindarella/SR the same for a 2nd. user.\n\nhere you can enter as much users as you want.\n\n\n\nNO.INFO : Also here is only 1 tooltype existing :\n\nDo_not_change_quiet.4 would stop on Node 4 that after the logoff the quietnode\nwould be deleted. That would be usefull for local nodes, where for example\nthe quietnode should always be On.\n\nThat was everything about the tooltypes.\n\n*****************************************************************************\n\n\n\n                               -G-R-E-E-T-I-N-G-S-\n\n\n  Greetings To All\n                      ______  __________________\n               +-----/    \ \/ / __/_  __/ / __/----------+\n               |----/ / / /\  /\  /-/ /-/ / /----[ /X ]---|\n               |----\/ / /-/ /\  /-/ /-/ /\ \--[ DESiGN ]-|\n               +-----\/\/--\/--\/--\/--\/--\/-------------+\n               |                                          |\n               |   EMPiRE   -   BYTEANDi   -  CRACKDOWN   |\n               |   TYCOON   -   KiLLRAVEN  -   SiEGEL     |\n               |   FUZZY    -     SPY                     |\n               +------------------------------------------+\n\n  I hope we have a nice work and show the Developement Team what\n  to do with /X !\n\n  Special greetings to Van Damme... I hope you come Next Time\n  via C-Programming... Take a Look to Empire !\n\n  To Bytemaster, we hope for more Informations About Amiexpress\n\n  To CINDARELLA/SR for the fast translation :*\n\n  To Byteandi - Thx for the great ansis :)\n\n  To FAZWONGA!/PDY - THE UL/DL FILENAMES ARE ONLY FOR YOU ;)))))))\n\n  Many Many THX To All my Beta testers for BugReports, Hints and Tips\n  to install Options....in that Door...\n\n             //\n  Thanx to \X/ Amiga For Being The Best Computer Ever made ...\n\n\n*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-\n\n       THE   SECOND   BEST   THING   YOU   CAN   DO   BY   YOURSELF\n\n\n/¯¯¯¯¯¯ __/¯¯¯¯  _/¯¯¯¯¯¯ __/¯¯¯¯  _/¯¯ __/¯¯ __/¯¯ __/¯¯¯¯ _/¯¯ __/¯¯¯¯\n/¯¯¯¯¯¯ _/¯¯¯¯¯¯ _/¯¯¯¯¯¯ _/¯¯¯¯¯¯ _/¯¯ __/¯¯ __/¯¯ _/¯¯¯¯¯ _/¯¯ _/¯¯¯¯¯\n/¯¯  ¯¯ _/¯¯  ¯¯ _/¯¯  ¯¯ _/¯¯  ¯¯ _/¯¯ __/¯¯   /¯¯ _/¯¯  _ _/¯¯ _/¯¯\n/¯¯¯¯¯¯ _/¯¯¯¯¯¯ _/¯¯¯¯¯¯__/¯¯¯¯¯¯ _/¯¯ _____/¯¯ _____/¯¯  __/¯¯ __/¯¯\n/¯¯ _____/¯¯  ¯¯ _/¯¯ ¯¯  _/¯¯  ¯¯ _/¯¯     _/¯¯ ____  /¯¯ __/¯¯ _  /¯¯\n/¯¯ _____/¯¯  ¯¯ _/¯¯  ¯¯ _/¯¯  ¯¯ _/¯¯¯¯¯¯ _/¯¯ ___/¯¯¯¯¯___/¯¯ _/¯¯¯¯¯\n ¯¯       ¯¯  ¯¯   ¯¯  ¯¯   ¯¯  ¯¯   ¯¯¯¯¯    ¯¯     ¯¯¯¯     ¯¯  ¯¯¯¯¯\n\n·------------> AMIEXPRESS V3.6 / AMIGA 3000 / 24 H ONLINE <-----------·\n|                                                                     |\n|      PORT             NUMBER   MODEM   SPEED      NODETYPE          |\n·---+-------------------------------------------------------------+---·\n  D | NODE 1: +49(0)30 745 2093 USR DUAL 14400 RINGDOWN NODE 1-3! | C\n  I | NODE 2: +49(0)30 745 2094 USR DUAL 16800 DIRECT LINE ACCESS | A\n  A | NODE 3: +49(0)30 745 2095 USR DUAL 16800 DIRECT LINE ACCESS | L\n  L | NODE 4: +49(0)30 746 7782 USR HST  16800 DIRECT LINE ACCESS | L\n·---+-------------------------------------------------------------+---·\n|                                                                     |\n|        G . I . V . E       I . T       A       R . I . N . G        |\n|                                                                     |\n·--> SUPPORTING !PD-SOFTWARE ONLY! FOR: AMIGA, ATARI, IBM-PC & MAC <--·\n\n*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-\n','\n',char(10)),NULL,'auto-added',51536,6,0,NULL,NULL,'mst_wh20','scan',1780048619);
INSERT INTO door_catalog VALUES('mst_who','MST_WHO.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MST_WHO.LHA',NULL,'XIM','_____    ___    _____________.__. ____',NULL,':','MST','_/  v  \__/ ! \  /  _____.   ._(__)/  . \ \_ _:_ ______  \/\___  \ |   | |  \_  |_/\ _/  \ /  \_  v  __   v   \|   | |    _ |   \',replace('   _____    ___    _____________.__. ____   \n _/  v  \__/ ! \  /  _____.   ._(__)/  . \  \n \_ _:_ ______  \/\___  \ |   | |  \_  |_/\ \n_/  \ /  \_  v  __   v   \|   | |    _ |   \\n\    v    /  ___/\    ___/!___! !___/__-   /\n-\___:___/___/-ã!-\___/---------------\___/-\n--------------------------------------------\n/X Tough Who 1.0   XIM Door By : Dea & Neuro\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                                                .------''\n             `------------------------------------------------''\n','\n',char(10)),NULL,NULL,53798,7,0,NULL,NULL,'mst_who','scan',1780048628);
INSERT INTO door_catalog VALUES('mst_wt10','MST-WT10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MST-WT10.LHA',NULL,'XIM','What000.x',NULL,NULL,'MST','\   /\ | /\ __/\ . /\ |\ . /| BOBO/MYSTiC | / V \/_. \/_.¬\/_| \/ |/ |_\| ~~~~~~~~~~~ | /  |  \¬|  \¬¦  \¬|  \ |  ¦ ¬\  PRESENTS:  |',replace(' _/\___/¦___/\___/\___/¦_/\__.-------------.\n \   /\ | /\ __/\ . /\ |\ . /| BOBO/MYSTiC |\n / V \/_. \/_.¬\/_| \/ |/ |_\| ~~~~~~~~~~~ |\n/  |  \¬|  \¬¦  \¬|  \ |  ¦ ¬\  PRESENTS:  |\n\__¦  /__  /__  / ¦__/_¦___  /  ~~~~~~~~~  |\n.---\/---\/---\/-/X-Power!-\/^-------------|\n|:.Upload Activities (WHAT) (Version 1.0).:|\n|:  Intended for Multinode systems only!  :|\n|:!This command/door should be a standard!:|\n|:  Compatable with S-Express and /X2.xx  :|\n`------------------------------------------''\n','\n',char(10)),'What.Guide',replace('@DATABASE What.Guide\n@$VER: Guide for Upload Activities (3rd May 1994)\n\n@REMARK Copyright (c) 1994 Mystic.\n@REMARK All Rights Reserved.\n@REMARK Main Program and Document by Bobo/Mystic.\n\n@REMARK You need MultiView, Amigaguide or any other GUIDE viewer.\n\n@NODE MAIN "What: Contents."\n\n--------------------------------------------------------------------------\n    Upload Activities (WHAT) (Version 1.0) [RELEASE 1] - 3rd May 1994\n--------------------------------------------------------------------------\n\n          @{"[ Background and Purpose ]" Link Background}      @{"[ Available Tooltypes ]" Link Tooltypes}\n          @{"[    Notable Features    ]" Link Features  }      @{"[   Program History   ]" Link History}\n          @{"[  Install into Express  ]" Link Install   }      @{"[  Thanks and Greets  ]" Link Greets}\n\n--------------------------------------------------------------------------\n                 Copyright (c) 1994 by Bobo/Mystic\n--------------------------------------------------------------------------\n\n Example Outputs/Scripts come in seperate files with the release archive.\n@ENDNODE\n@NODE Background "What: Background and Purpose"\n[------------( Background and Purpose )-----------------------------------]\n\nUpload Activities is a door for amiexpress intended for MULTINODE systems\nonly and can''t be used on single node systems. The main purpouse of this\ndoor is to show if a user on any other node is uploading something, and if\nso, it tells you what''s in his batch queue and what files in his batch have\nalready been finished uploading.\n\nNOTE: Take a look at the included output example (What.Output)\n\nWHAT can be made resident. I really recommend you to do this, since\nit will speed this door up quite much, specially on 68000-68020 computers!\n@ENDNODE\n@NODE Features "What: Notable Features"\n[------------( Notable Features )-----------------------------------------]\n\nSeveral reasons to use Upload Activities:\n\n* Written entirely in C for fast code.\n* Can be made resident.\n* First kind of this door for amiexpress.\n* Configable playpen directories.\n* Special optimized versions for all CPU types.\n* 32-Node compatable. (Actually how many nodes you want)\n* Using Icons (/X3.x Standard Nowadays), but should work fine with /X2.x\n  and Sigma Express.\n@ENDNODE\n@NODE Install "What: Install into Express"\n[------------( Install into Express )-------------------------------------]\n\nThis door should be installed as a standard amiexpress door.\nOn /X3.x you have you have to edit (or create) a file called WHAT.INFO in\nyour BBSCmd directory. On /X2.x and SExpress you have to edit the\nBBS.Cmd in the usual way. Remember to give it a high stack (example 50000)\nand make it multinode. The door is an XIM type ofcourse!\n\nAlso, for added speed, you may make the door resident with your normal\n"resident" command (CLI: "Resident What.x PURE"). But if you do, make\nsure that Express runs just the doorfilename, without its path. On /X3.x\nyou also need the tooltype RESIDENT in the icon.\n\nYou also need a icon in doors:. Just create a info file named WHAT.INFO.\nMake it as a drawer icon to your DOORS:WHAT dir. Here you can put any\nof the available tooltypes listed later in this document.\n@ENDNODE\n@NODE Tooltypes "What: Available Tooltypes"\n[------------( Available Tooltypes )--------------------------------------]\n\nHere are the available tooltypes.\n\nTooltype-Name:                    Description:\n---------------------------------------------------------------------------\nNODES=<#nodes>                  - This tooltype is really not necessarly.\n                                  This is how many nodes you have. (Or how\n                                  many nodes you want to search through).\n                                  If this tooltype is not found, it will\n                                  search through all 32 nodes.\n\nDONOTSHOW_NODE<node>            - This will skip the search for upload on\n                                  the specified node.\n\nPLAYPEN_<node>                  - This is ONLY needed if you have external\n                                  playpen directories.\n@ENDNODE\n@NODE History "What: Program History"\n[------------( Program History )------------------------------------------]\n\n{ + }-New feature(s)         { - }-Removed feature\n{ * }-changed feature        { ! }-fixed feature (Bug)\n{ # }-Information            { ? }-let me know if this work\n\nWhat v0.5 (10-12-93 > 11-01-93) - [Private version for my board]\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nFirst version, coded in Arexx by Bobo\n\n10-12-93 { + } I started coding this door.\n - ^^ -  { + } Main source for listing a directory coded. (Using C:LIST)\n10-13-93 { * } Now using AREXXs inbuilt LIST command instaid of using C:LIST\n10-15-93 { * } Fixed a nicer design.\n10-17-93 { # } WHAT do not list the playpen directory in the correct order.\n               Hope i found away to do that in the future..\n\nWhat v1.0 (01-30-94 > 04-19-94) - [First public release version]\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nFirst C version, no bugs known!\n\n01-30-94 { + } Recoded the AREXX version of WHAT into C\n02-02-94 { ! } Now sorting the files in correct order.\n02-04-94 { * } Now using comma-seperator at the filelengths\n02-10-94 { + } Now showing Total files and Total bytes.\n02-13-94 { ! } Now unlocking files, libs and free allocated memory when a\n               error occur.\n02-16-94 { * } Now more optimized routine when reading from icons.\n03-14-94 { ! } ** MAJOR BUG DETECTED ** "What" did not lock the playpen dir\n               in shared mode! This means it could bug and guru when it\n               was used on two nodes at the same time.\n - ^^ -  { # } I would really need the routines to check if a node is quiet\n               or not! Tell me at once if you have any!\n - ^^ -  { + } Now you can have a icon in doors: WHAT.INFO.\n               Available tooltypes: SKIP_NODE<node>,NODES=<nodes>\n                                    START_NODE=<node>,PLAYPEN<node>=<dir>\n04-19-94 { - } Registration routines removed.\n               Final size: 14672 (Source 11414 with comments)\n@ENDNODE\n@NODE Greets "What: Thanks and Greets"\n[------------( Thanks and Greets )----------------------------------------]\n\nGreetings to: Pacific/2000 AD, Looby/Insane, Dee/Delight, Agressor/Anthrox,\n              Reactor/Mystic, Easy Rider/Mystic, Ufok/Mystic, Screwball!\n\nMany thanx to Byteandi/TRSI and Remo/Mystic for all help and support!\n\nAnd many many thanx to all my beta testers for bug-reports, suggestions and\nhints & tips to improve this door.\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',27704,9,0,NULL,NULL,'mst_wt10','scan',1780048628);
INSERT INTO door_catalog VALUES('mst_wt11','MST-WT11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MST-WT11.LHA',NULL,'XIM','_/\___/¦___/\___/\___/¦_/\__.-------------.',NULL,NULL,'MST','\   /\ | /\ __/\ . /\ |\ . /| BOBO/MYSTiC | / V \/_. \/_.¬\/_| \/ |/ |_\| ~~~~~~~~~~` | /  |  \¬|  \¬¦  \¬|  \ |  ¦ ¬\  PRESENTS:  |',replace(' _/\___/¦___/\___/\___/¦_/\__.-------------.\n \   /\ | /\ __/\ . /\ |\ . /| BOBO/MYSTiC |\n / V \/_. \/_.¬\/_| \/ |/ |_\| ~~~~~~~~~~` |\n/  |  \¬|  \¬¦  \¬|  \ |  ¦ ¬\  PRESENTS:  |\n\__¦  /__  /__  / ¦__/_¦___  /  ~~~~~~~~~  |\n.---\/---\/---\/-/X-Design-\/^-------------|\n|:.Upload Activities (WHAT) (Version 1.1).:|\n|:  Intended for Multinode systems only!  :|\n|:This is a must for boards with more then:|\n|:one node!  -32 Node Version (/X3.x ONLY):|\n`------------------------------------------''\n','\n',char(10)),'What.Doc',replace('\n             Upload Acitivities (Version 1.1) [RELEASE 2]\n                 All Coding by Bobo (Mystic/X-Power)\n                 -----------------------------------\n                        Release date 07-31-94\n\nHello again, and welcome to another fine product.  This door is intended\nfor MULTINODE systems only and can''t be used on single node systems. The\nmain purpouse  of this door  is to show  if a user on any other  node is\nuploading something, and if so,  it tells you what''s in his batch  queue\nand  what  files in his  batch have  already been   finished  uploading.\n\nPlease note  that this door ONLY works  on the 32 node version of amiex!\nA version  for the old /X 2.x/3.x and SExpress  will be done on request!\n\nNotable Features:\n~~~~~~~~~~~~~~~~~\n* WHAT is written entirely in C for fast code.\n* WHAT is the fist kind of this door for amiexpress.\n* WHAT have been tested and works 100% on multinode systems.\n* WHAT comes in 000/020+ version to get the maximum speed on your\n  system.\n\n\n                              INSTALLATION\n                              ~~~~~~~~~~~~\nWHAT requires a fully installed and running amiexpress 3.x (32 node).\nIt will NOT work on eairlier versions of amiexpress or S-Express.\n\nTo install WHAT, start with copying the included icon where it should be\nlocated.\n\n------------( Snap this lines )---------------------------\nCopy RAM:Commands/BBSCmd/WHAT.info BBS:Commands/BBSCmd/\n----------------------------------------------------------\n\nContinue  with making  a directory  in doors: called ''WHAT'' and copy the\nmain program, docs etc.\n\n------------( Snap this lines )---------------------------\nMakedir Doors:WHAT\nCopy RAM:Doors/What/What.#? Doors:What/\n----------------------------------------------------------\n\nNow  copy  the executable  file ''What.<cpu>''  (depending on what CPU you\nmay have) to ''What.x''\n\n(THIS IS JUST TO MAKE SURE YOU HAVE EVERYTHING INCASE YOU  LOOSE THE LHA\nPACKAGE)\n\nEG: Copy What020.x What.x\n(If you have 68020+ cpu)\n\nThat''s it!  Please  feel free  to contact me  if you  are having trouble\ninstalling the tools.  My numbers  are at the  bottom of this  document.\n\n\n                                GREETINGS\n                                ~~~~~~~~~\nI personally want to thank all my beta-testers at THE EAST BBS.\nIn no particular order, they are (two columns):\n\nL.A.Style  [GER]  (Terminal Obs.)  Demax      [SWE]  (UnderCover)\nBoozer     [SWE]  (Shadow Zone)    FireHawk   [SWE]  (Hardware Tower)\nUffe       [SWE]  (TNT)            Distler    [SWE]  (The Slammer)\nJLM&Snoopy [SWE]  (Eagles Nest)    BlueLight  [ITA]  (Asylum)\nDanzig     [SWE]  (Kyron Dome)     FCKW       [GER]  (Second World)\nReverend D [SWE]  (Trespass)       Natas      [ITA]  (Temple of dest.)\nRhys       [SWE]  (Neurobashing)   Double     [NOR]  (Fatal Chaos)\nEzco       [SWE]  (Serpent Hill)   Zcandaler  [SWE]  (Total Eclipse)\n[StN]      [FIN]  (MNC)\n\nAlso greetings to the following people:\n-- LOOBY/iNSANE, KiLLRAVEN/MYSTiC, EMPiRE/MYSTiC, BYTEANDI/TRSI,\n   UFOK/MYSTIC, REMO/MYSTIC, REACTOR/MYSTIC, PACIFIC/2000 AD\n\nAnyone can become a beta-tester, simply make a call to THE EAST BBS.\nYou''ll find the number at the bottom of this document.\n\n\n                             FINAL COMMENTS\n                             ~~~~~~~~~~~~~~\nThis program is Copyright (C)1994 by Bobo/Mystic.  If you are  intrested\nto join MYSTIC/X-POWER,  simply make a  call to your  nearest MYSTIC HQ!\n\nIf your hard-drive or  anything else goes wrong  when you are using this\ndoor, i  am not responsible.  This tool has been  thouroughly  tested on\nmany  boards all  around  the world,  but "there is always one more bug"\n\nThat''s it for now, i hope you enjoy this door.\n\n-Bobo (Mystic/X-Power)\n\n\n                              CONTACT INFO\n                              ~~~~~~~~~~~~\nIf you have any questions, bug reports, suggestions,  you can contact me\nat the following boards:\n\nThe East BBS: +46(8)940614  [16.8DS]   SYSOP: BOBO/MYSTIC\n              +46(8)940615  [16.8DS]   SYSOP: BOBO/MYSTIC\n              +46(8)940919  [14.4HST]  SYSOP: BOBO/MYSTIC\n              Username: GUEST, Password: PASSWORD\nLost Outpost: +31-72157682  [16.8DS]   SYSOP: EMPIRE/MYSTIC\n              +31-72201182  [16.8DS]   SYSOP: EMPIRE/MYSTIC\nChannel-X   : +31-229062244 [16.8DS]\n\nor write me a mail on internet: [email removed]\n','\n',char(10)),NULL,NULL,19265,2,0,NULL,NULL,NULL,'scan',1780048628);
INSERT INTO door_catalog VALUES('mst_wt20','MST-WT20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MST-WT20.LHA','WHAT','XIM','WHAT',NULL,NULL,'MST','\   /\ | /\ __/\ . /\ |\ . /| bObO/mYStiC | / V \/_. \/_.¬\/_| \/ |/ |_\| ~~~~~~~~~~~ | /  |  \¬|  \¬¦  \¬|  \ |  ¦ ¬\  PRESENTS:  |',replace(' _/\___/¦___/\___/\___/¦_/\__.-------------.\n \   /\ | /\ __/\ . /\ |\ . /| bObO/mYStiC |\n / V \/_. \/_.¬\/_| \/ |/ |_\| ~~~~~~~~~~~ |\n/  |  \¬|  \¬¦  \¬|  \ |  ¦ ¬\  PRESENTS:  |\n\__¦  /__  /__  / ¦__/_¦___  /  ~~~~~~~~~  |\n.---\/---\/---\/-/X-pOwEr!-\/^-------------|\n|  WHAT: Transfer Activities v2.0 (REL 2)  |\n| * Intended for Multinode systems only! * |\n| NEW: Supports now uploads/downloads/cps! |\n| Sourcecode and Conftop screenshots incl. |\n`------------------------------------------''\n','\n',char(10)),'WHAT.doc',replace('\n---------------------------------------------------------------------------\n        Transfer Acitivities [RELEASE 2] - Public Release Version!\n                   All Coding by Bobo (Mystic/X-Power)\n---------------------------------------------------------------------------\n\nHi all sysops.  There have been  quite some time since  the last release\nfrom me, but here it is.  This is one of the  last doors i am ever going\nto release on the amiga, due to lack of time.\n\nWell, I guess the most of you sysops know  what this door is and what it\ndoes, but to the ones that  have been lost for some years, here''s a fast\nintroduction:\n\nThis door is  intended for MULTINODE systems only and  cannot be used on\nsingle node systems. The main purpouse of this door is to show if a user\non any other node is transfering something, and if so, it tells you  the\ncurrent  file that  he is transfering  and what files in his batch  have\nalready been finished.\n\nAS A BONUS, the sourcecode to this door is included in the archive.\nAS AN EXTRA BONUS, screenshots of the new Conftop 3.0!\n\n\nAn example output may look like this:\n.----------------------------------------------------------------------------.\n| WHAT: Transfer Activities v2.0 [REL 2] - Copyright (c)1994-95 Bobo/Mystic! |\n|--v----------------------v----------------v--------------v-----------v------|\n|Nd| Username (Handle)    | Status/Action  | File(s)      | Filesize  | CPS  |\n|--+----------------------+----------------+--------------+-----------+------|\n| 1| UFOk                 | Uploaded - OK! | ADTOHT21.LHA |   100.142 |  -   |\n| 1| UFOk                 | Uploaded - OK! | ALGOMUS.LHA  |    72.810 |  -   |\n| 1| UFOk                 |*Uploading file | DELIT214.LHA |           | 1253 |\n|--+----------------------+----------------+--------------+-----------+------|\n| 2| FLATLINE             | Uploaded - OK! | FORDSIM1.ZIP | 1.464.904 |  -   |\n| 2| FLATLINE             |*Uploading file | FORDSIM2.ZIP |           | 3230 |\n|--+----------------------+----------------+--------------+-----------+------|\n| 3| sNOOpY!              |*DL''ing file... | 351RC110.ZIP | 1.998.541 |  -   |\n|--^----------------------^----------------^--------------^-----------^------|\n| Upload   Activities -> Total files: [   3 ]   Total bytes: [   1.637.856 ] |\n| Download Activities -> Total files: [   0 ]   Total bytes: [           0 ] |\n`----------------------------------------------------------------------------''\n\nIf you run a  multinode bbs,  this door is almost a must and should be a\nstandard on all boards.  This door also fully supports quiet nodes, so a\nuser can exclude himself from WHAT easy - just to use the ''Q'' command in\namiexpress.\n\nKeep in mind that this door ONLY works on the new versions of amiexpress\nthat supports 32 nodes. A version for the old amiexpress 2/3 series and\nSExpress may be done if requested.\n\n--------------------------------------------------------( Installation )---\n\nWHAT requires a fully installed and running amiexpress 3.x (32 node).\nIt WON''T work on eairlier versions of amiexpress or S-Express.\n\nWHAT doesn''t require any configuration.\n+++++++++++++++++++++++++++++++++++++++\n\nAll sysops should know how to install a standard XIM-door, but you''ll\nnever know, so here''s a fast breif.\n\nTo install WHAT, start with copying the included icon where it should be\nlocated.\n\n------------( Snap this lines )---------------------------\nCopy RAM:Doors/WHAT/WHAT.info BBS:Commands/BBSCmd/\n----------------------------------------------------------\n\nContinue  with making  a directory  in doors: called ''WHAT'' and copy the\nmain program, docs etc.\n\n------------( Snap this lines )---------------------------\nMakedir Doors:WHAT\nCopy RAM:Doors/What/#? Doors:What/ ALL\n----------------------------------------------------------\n\nThat''s it!  Please  feel free  to contact me  if you  are having trouble\ninstalling the tools.\n\n------------------------------------------------------( Final Comments )---\n\n                              CONTACT INFO\n                              ~~~~~~~~~~~~\nIf you have been tring to reach me on internet, you''ll probably noticed\nthat my email address ([email removed]) doesn''t work. TRUE, it doesn''t\nwork! However, try to reach me on IRC sometime. My nickname is: bobomst\n\n\nIf YOU are interested to join one of the finest groups in the scene: MYSTiC\n- Make sure you call one of our headquarters in your nearest country and\nleave the sysop a message.\n\n---------------------------------------------------------------------------\n\nMore quality doors/tools will be available very soon!\nKeep in touch with the best coders - MYSTiC!\n','\n',char(10)),NULL,'auto-added',25347,1,1,'WHAT','Doors/What','mst_wt20','scan',1780048628);
INSERT INTO door_catalog VALUES('mstgd121','MSTGD121.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MSTGD121.LHA','Nuclear','XIM','Nuclear',NULL,NULL,NULL,'/  V  ¼\   V ¼\   ____  _   _____/  .   / /  \ /   \__.   \___  ¼\/    |   ¼\  |__/_ /    V     \ |    \ V    \    |     \ |   ¼\',replace('   __ ___ ___ __ _____________.____________ \n  /  V  ¼\   V ¼\   ____  _   _____/  .   / \n /  \ /   \__.   \___  ¼\/    |   ¼\  |__/_ \n/    V     \ |    \ V    \    |     \ |   ¼\\n\____|___  /____  /____  / ___|___  /____  /\n½-#e#----\/-----\/-----\/\/-------\/-----\/-\n:::   GifDesc V 1.2.1  Public Release    :::\n::: Add&Extract FILE_ID.DIZ to .GIF''s !! :::\n:::   Use with Byteandi''s FILEID Door    :::\n:::(nOw worKs %100!!!!!!!!!!!!!!!!!!!!!!):::\n:::::::::::::::::::::::::MIT/MYSTIC:::::::::\n','\n',char(10)),'gifdesc.doc',replace('\n   _____ ____   _____ ___    _______________  /\____________  _____________\n  _\___ ¥ _ ¬\_/¯    ¥  ¬\__/  ________/____\/_______/______)_\ ___     __/ \n_/     \_/    ¬\______    ¬\______     ¬\/        ¬\_       ¬\_\/ |_____/__ \n\       |       \_   !      \_   !       \_         ¬\_       /   !       ¬\_\n \ _____|        /____       /____        /___        /_____ /_____         /\n  \/¯  ¯l______ /   ¯\_____ /   ¯\______ /  ¯\______ /    ¯\/    ¯\_______ / \n-c0!         ¯\/         ¯\/          ¯\/         ¯\/                   ¯\/\n\n================================pReSeNts====================================\n\n                              GifDesc V1.2\n\n============================================================================\nOk... after the betatester-release(1.0a) and the quick-release(1.1) here is\nGifDesc v1.2..\n\nUSAGE:\n======\nThe usage is so simple..\n\n-gifdesc e <source> <destination-description>\n\nLets assume that we have a file_id''ed gifnamed a.gif. To extract file_id \nto a file named b.diz type\n\n        gifdesc e a.gif b.diz\n\n-gifdesc a <source> <description>\nLets assume that we are going to add a file_id to a gif named a.gif. The \nfile_id name is b.diz.So you must type\n\n        gifdesc a a.gif b.diz\n\n*NOTE:You can add more then one file_id''s to a file. But only first file_id\nwill be used as a file_id. So if you want to strip all, use d parameter\nof GifDesc.(will be explaned later.)\n\n-gifdesc r <source/destination> <description>\n\nStill we have same files.. But i would like to replace the description\nwith c.diz.. So type..\n\n        gifdesc r a.gif c.diz\n\n*NOTE:Two trunking techniques used in this part.. If the one that Commodore\nput in V37 didn''t work, GifDesc will open a temp file in t: So if you don''t\nhave enough memory assign t: to harddisk.\n\n-gifdesc d <source/destination>\n\nTo remove all file_is''s only give name of the file & use parameted d.\n\n        gifdesc d a.gif\n\n*NOTE:Two trunking techniques used in this part.. If the one that Commodore\nput in V37 didn''t work, GifDesc will open a temp file in t: So if you don''t\nhave enough memory assign t: to harddisk.\n\nBUGS:\n=====\n\n-Problem:Why we cannot change the description ? \n         [Reported by Master/Clique-Clinique BBS]\n\n *FIXED*... now you can change the description.\n\n-Problem:Why GifDesc puts file_id.diz in non gif files too?\n         [Reported by Mit/Mystic-tEcHnIqUe BBs]\n\n *FIXED*... a quick .gif checking added.\n\n-Problem:GifDesc didn''t work.\n         [Reported by FisherKing-Rocka Rolla BBS]\n\n *FIXED*... now you can make it work. Only kick yar other sysop. :-)\n\n-Problem:Some probs with allocation of memory.\n         [Reported by Mit/Mystic-tEcHnIqUe BBs]\n\n *FIXED*... Ok.. no more malloc() errors! Because no more malloc() used!\n\n-Problem:Couldn''t find any version information.\n         [Reported by Master/Clique-Clinique BBS]\n\n *FIXED*... now the version string added.\n\n-Problem:If you try to replace decription of a non descripted file, the\n         file became ~500 byte shorter.\n         [Reported by Mit/Mystic-tEcHnIqUe BBs]\n\n *FIXED*.. Nnnn.. kOOl!.. In fact,i was compressing gifs and ...then...\n           ok.. ok. It was my bug... ok.. I fixed it!..\n\nEXTRAS:\n=======\n\n-Added own description extract routine.\n-Now you can remove file_id.diz from the file.\n-Added a small checksum in key-file.Because some *LAME* guy had access\nto one of our betatesters site.So he has got some keys too.But don''t worry!\nGifDesc 1.2 still works %100 without keyfile.\n\nIMPORTANT:\n==========\n\nIf you have an old file, you must replace it with the new one. I gave keys\nonly to betatesters, but donno. Maybe someone have keyfiles too. If you use \nthe old keyfile,GifDecs''s task will be suspended forever. !!AGAIN!! Don''t \ntry to remove checksum! Because this utility works %100 without keyfile \ntoo. !!\n\nQUICK & ALL INFO! [:-)]:\n========================\n\nadd these tooltypes to your DOORS:FILEID/FILEID.info\n\nGIF_EX=c:GifDesc e %P %WFILE_ID.DIZ\nGIF_AD=c:GifDesc r %P %WFILE_ID.DIZ\n\nthat''s all! If you want to be registered user, mail me your systems phone\nnumber,bbsname,sysop name. I''ll send you the key file & lastest version of\nthis utility a.s.a.p.!! Please note that=>" The key file isn''t for blocking\nillegal use! "<= Because.. there''s nothing to be illegal.\nThis utility is freeware! You can still use it %100 without keyfile. But i \nwould like to know how many persons are using this utility. So i can inform \nyou about new versions of this utility and my other utilities easily&faster.\nThank you! If you have acces to Internet, send me your address too.. I''ll\ninclude a newest version to my reply.\n\nsigned Mit/Mystic\n   23.7.94\n\n=My Beta-Sites=\n* Clinique BBS    : Clique wHq           : Master/Clique : 90-216-349-9519 \n* Rocka Rolla BBS : ??????????           : FisherKing    : 90-216-363-8601\n                                                         : 90-216-363-5742\n* tEcHnIqUe BBS   : Mystic hQ            : Mit/Mystic    : 90-216-347-5892\n                    Clique Technical wHq \n\n==Thanx===== [not longer than docs!]\n* Fisherking      : Ok.. hard-life.. but let''s kick some user!(incl.sysops)\n* Master/Clique   : Why don''t we code a Chunky-2-Planer / XWin game?\n* Vigo/Mystic     : pArTy of Da CenTuRy I is comin.. huh?\n* Matt Dillon     : for his Dice C !\n* All others not mentioned here...\n\n==Sorry=====\n*Spy/Mystic       : we waited your code.. but our sysops requested soooo much,\n                    so i coded.\n==Dicks to==\n* Dr.Know         : I understand you.. It''s hard to be a lamer, but it wasn''t\n                    a good idea spreading our betatester files..so fuck u!\n','\n',char(10)),NULL,'auto-added',33692,7,0,NULL,NULL,'mstgd121','scan',1780048628);
INSERT INTO door_catalog VALUES('mstmt211','MSTMT211.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MSTMT211.LHA','MultiTop','XIM','MultiTop','2.1','BOBO/MYSTIC!',NULL,'- Coding by BOBO/MYSTIC! ============================================ NEWS: · Supporting top ul/dl cps',replace('MultiTop v2.1ß [BETA 1]\n- Coding by BOBO/MYSTIC!\n============================================\nNEWS: · Supporting top ul/dl cps\n      · New load/sort routine=50% faster\n      · New config program=easier to use\n============================================\n** MYSTIC-BETA CONFERENCE(S) ONLY **\n','\n',char(10)),'MTopDLBytes1.txt',replace('INSERT INTO door_catalog VALUES('mstrip11','MSTRIP11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MSTRIP11.LHA','MAStripper','XIM','LE-win5-96.exe','1.1',NULL,NULL,'Removes all MCI-&ANSI-sequences from a file ===========================================',replace('========= MCI-ANSI-Stripper V1.1 ==========\nRemoves all MCI-&ANSI-sequences from a file\n===========================================\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                                                .------''\n             `------------------------------------------------''\n','\n',char(10)),NULL,'auto-added',10194,5,0,NULL,NULL,'mstrip11','scan',1780048628);
INSERT INTO door_catalog VALUES('mstwho','MSTWHO.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MSTWHO.LHA','Count','XIM','LE-win5-96.exe','1.0','Spy',NULL,NULL,replace('WHO V1.0 Written by Spy (MySTiC /X DESiGN)\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                                                .------''\n             `------------------------------------------------''\n','\n',char(10)),NULL,'auto-added',46080,8,0,NULL,NULL,'mstwho','scan',1780048628);
INSERT INTO door_catalog VALUES('msy_lr10','MSY-LR10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MSY-LR10.LHA','Lha','XIM','HuntVirus',NULL,'SPEEDWOLF/MSY!','MSY','_ _ ________ _\___/· ___/· ___/  _ ·/  /· / ____/  /  / //· /__   /  __/   /  /  /  /_ |:::/  /  /  /  /  /  /  / ·/  _ _/\_   /::|',replace(' __ _ ______/\/\___/\____/\____/\____/\____\n_ _ ________ _\___/· ___/· ___/  _ ·/  /· /\n ____/  /  / //· /__   /  __/   /  /  /  /_\n|:::/  /  /  /  /  /  /  / ·/  _ _/\_   /::|\n|::/  /  /  /  /  /  /     /  /  \/¯/  /:::|\n ¯/__/__/  /__/_____/_____/__/___/____/¯¯¯¯\nsW      \___ make ya gonna cry with ___\n···»» LHA-Runner V1.0 by SPEEDWOLF/MSY! ««···\n   ·····»» dA bEst cHacka for /X!! ««·····\n','\n',char(10)),'LhaRunner.doc',replace('                __ _ ______/\/\___/\____/\____/\____/\____\n               _ _ ________ _\___/· ___/· ___/  _ ·/  /· /\n          __________/  /  / //· /__   /  __/   /  /  /  /_______\n         |:::::::::/  /  /  /  /  /  /  / ·/  _ _/\_   /::::::::|\n         |::::::::/  /  /  /  /  /  /     /  /  \/¯/  /:::::::::|\n          ¯¯¯¯¯¯¯/__/__/  /__/_____/_____/__/___/____/¯¯¯¯¯¯¯¯¯¯\n               sW      \________________________________\n\n                          ...presents the¡r...\n\n             A·M·¡  E·×·P·R·E·S·S  -  M·A·N·¡·A   S·E·R·¡·E·S\n\n                            Th¡z t¡me ¡t''s.....\n  \n                                    /\\n                             __    /./\__ /\\n  !AM¡-EXPRESS!             /./\  /// / // .\                 !AM¡-EXPRESS!\n  !AM¡-EXPRESS!            /// / ///_/.//./\\\                !AM¡-EXPRESS!\n  !AM¡-EXPRESS!           /°/_/_/°__ ///// /\\\               !AM¡-EXPRESS!\n  !AM¡-EXPRESS!          /_______/ ///////¯¯¯ °\              !AM¡-EXPRESS!\n  !AM¡-EXPRESS!          \_______\/°//°/ \¯¯¯¯¯¯\             !AM¡-EXPRESS!\n  !AM¡-EXPRESS!         sW        \/ \/ / ¯¯¯¯¯¯¯             !AM¡-EXPRESS!\n  !AM¡-EXPRESS!                    \/ \/ R·U·N·N·E·R  V1.0    !AM¡-EXPRESS!\n +-------------------------------------------------------------------------+\n | Coded,Ans¡ des¡gn¡ng and ¡dea by.........................SPEEDWOLF/MSY! |\n +-------------------------------------------------------------------------+\n \n Well,a new Group,a new /X-Tool.\n Th¡s ¡s our 2nd Release but our f¡rst /X-Tool an ¡ hope you l¡ke ¡t!\n LHA-Runner checks the Arch¡ve,str¡pps and adds Adver¡sements and all ¡n\n a very short t¡me.¡ th¡nk ¡t''s one of the fastet but who knows ??\n has everybody made a contest between two Lha-Checkers ??\n\n -THE ¡NSTALLAT¡ON-\n ------------------\n The ¡nstallat¡on of LHA-Runner ¡s very easy!\n S¡mply copy the F¡le ''LhaRunner'' ,wh¡ch can also be started from CL¡ (more\n ¡nfos about th¡s com¡ng up...), ¡nto your C: d¡rectory.\n Then the Conf¡g-F¡les ''Lha.str¡p'' and Lha.add'' ¡nto your S: drawer!\n All you now have to do ¡s to tell Am¡Express to use LhaRunner on uploaded\n Arcs.If you want LhaRunner to check *.LHA-Files then copy the file\n LHA.info into your FCheck-dir (BBS:FCheck/LHA.info)...\n \n LhaRunner supports the following Arcs...\n *.LHA				- The Usual!\n *.RUN				- Selfextrracting LHA-Arcs\n *.LZH				- The Usual!\n *.LZA				- The Usual!\n\n Now,try to upload something to look if LhaRunner works correctly like it\n should whe you have installed it correctly.\n -THE CONF¡GURAT¡ON-\n -------------------\n You can ed¡t the work of LhaRuner ¡n d¡fferent ways.\n To make th¡s more understand¡ng let''s have a look at the Cl¡/Shell Use!\n \n USAGE: [PATH:]LhaRunner <Arch¡veName> [Add¡ng]\n        Opt¡ons ¡n brackets are opt¡onal.\n        PATH:             Where LhaRunner ¡s on your HD.\n        Arh¡vename:       Wh¡ch Arch¡ve should be checked.\n        Add¡ng:           Wh¡ch F¡le should be added to the LHa-Arc.\n\n The Checker works ¡n the follow¡ng order:...\n F¡rst he checks the Arch¡ve ,and when ¡t''s bad ¡t g¡ves back an Error\n Message.When ¡t''s good,¡t str¡ps all the Advert¡semnets ¡n the Arc you\n want to delete.Therefore ¡t looks ¡n S:Lha.str¡p to know what to delete.\n You can ed¡t th¡s F¡le by Double-Cl¡ck¡ng on Wb or load¡ng ¡t ¡nto any\n Text-Ed¡tor.\n After Str¡pp¡ng,he beg¡ns to add your Advert¡sements.\n F¡rst LhaRunner looks for an arguement after the Arch¡vename.\n ¡f there''s a f¡le g¡ven ¡t adds ¡t and ex¡ts the programm.\n Otherw¡se,¡f there''s no f¡lename g¡ven he looks ¡n S:Lha.add to know what\n to add. Note: ¡f you add v¡a the conf¡g-f¡le you can add as many Adver-\n t¡semenst as you l¡ke. ¡f you g¡ve the Advert¡sement as Arguement you can\n only add one f¡le per check.\n\n SPEC¡AL THANKS TO..\n -------------------\n MAXHEADROOM/TEX.........................................for h¡s l¡ttle help!\n PSYCHO/M¡SERY!............................................for Moral Support!\n M¡LLE/M¡SERY!.............................................for Moral Support!\n\n THE USUAL GREET¡NGS GO TO...\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n      ·] RENDERMAN/EXPLORERS - MAX HEADROOM/TEX - UNDERTAKER/X-ACT [·\n        ·] METALL¡CA/X-ACT - TW¡L¡GHT/LEGO - VAMP/¡A - CUSAK/¡A [·\n    ·] TURNER/CYBERAKT¡F - DULUX/PR¡ME DES¡GN - EXTERM¡NATOR/REMEDY [·\n          ·] AL¡EX/MYST¡C - COOLSPOT/¡NDP. - EAGLE-EYE/DEFECT [·\n      ·] CHRUSHER/SH¡N¡NG 8 - KERM¡T/EXPLORERS - MAD - JEFF·STA¡NE [·\n          ·] BLUE/PROTECH - DR.BYTE/SCANDAL - FLASHY - DJ J¡M¡ [·\n\n $VER:M¡SERY!-DOCF¡LE V1.0\n','\n',char(10)),NULL,'auto-added',88965,4,0,NULL,NULL,'msy_lr10','scan',1780048628);
