INSERT INTO door_catalog VALUES('mth_ca10','MTH-CA10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MTH-CA10.LHA','KeroCac','XIM','KeroCac',NULL,'KEROSENE/MYTH','MTH','\_    \/    _/___|   \    |__\____  | /    \_/   \    |    \   _______/  |____. /      \     \___.    /   \    \    .    |',replace(' ______  ______   .___ ____.  _______.\012 \_    \/    _/___|   \    |__\____  |\012  /    \_/   \    |    \   _______/  |____.\012 /      \     \___.    /   \    \    .    |\012/________\     \  |   /______    \___|    |\012·-----/_________\____/-------\____\nK|____|\012|                                         |\012|          /X DiViSiON PRESENTS:          |\012|      CONFERNCE ACCESS CHECKER 1.0       |\012|            BY KEROSENE/MYTH             |\012`-----------------------------------------''\012','\012',char(10)),'KeroCac.doc',replace('                     _________                           _______._\n   __________ /\_____\        \  ________________________\_     |_______\n   \         /_       \        \/      _._______         /      |       |\n  /         \/_________\___    /      __|      /________/       _       |\n /___________\           /_____________\l_______|      /________|       |\n                                                                l_______|\n\n                                 Presents\n\n                      Conference Access Checker v1.0\n\n                                    By\n\n                               KeroSene/Myth\n\n\n                   This program is freely distributed as\n                   long as all files remain unmodified.\n                   I will not take any reponsibility of\n                 any problems that this program may cause.\n                         (it shouldn''t cause any.)\n\n\n\nThis archive (mth-ca10.lha) should contain these files:\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nDoors/KeroCac/\n   KeroCac              11152 bytes   The main file.\n   KeroCac.doc           5834 bytes   This doc file.\n\nCommands/BBSCmd/\n   CAC.info              1109 bytes   The icon file for checking the uploads.\n\n\n\n\nInstallation!\n~~~~~~~~~~~~~~\nCopy all files from Doors/ and Commands/ to BBS: ... And then your\ninstallation is done. Now you only need to configure the holdchecker.\n\n\n\n\nUsage!\n~~~~~~~\nEnter CAC ? at the main prompt, and usage screen will popup! =)\n\n\n\n\nWhat is it!\n~~~~~~~~~~~~\nIt''s a door made by KeroSene of Myth. Coded in C (SAS/C 6.55).\nIt lists all the users that has access to the current conf.\n\n\n\n\nHistory!\n~~~~~~~~~\n0.1ß - 95-05-09 - Just a ßeta release (And its slow gotta fix faster output).\n\n0.2ß - 95-05-21 - The door is faster now, and the output is fixed.\n\n1.0  - 95-06-14 - First public release. Everything is fixed (I hate writing\n                  history)!!!!!!\n\n\n\n\n\n                                Greetings:\n                               ~~~~~~~~~~~\n       amon. aquarius. bionic. biscrok. exeron&maniac. nero. diablo\n       cray-1. crawl. dansken. dildo. boogeyman. activate. cenotaph\n       v-cut. neptune. recall. frosty. qen. vegas. stryper. wingnut\n        black beard. mr.wishbone. the violater. vital. magz. storm\n           punisher. sinister. wraith. skize. vietcong. twister.\n                            azazel. thc. delite\n\n                                     +\n\n                         >>> All who i forgot <<<\n\n\n\n\n                            Places to find me!\n                           ~~~~~~~~~~~~~~~~~~~~\n                               Acid Attack.\n                                Death Row.\n                             Future Entrance.\n                           Masturbation Station.\n                             Mystical Places.\n                                The Payoff.\n                               Wasted Time.\n\n','\n',char(10)),NULL,'auto-added',14950,5,0,NULL,NULL,'mth_ca10','scan',1780048628);
INSERT INTO door_catalog VALUES('mth_fa1','MTH-FA1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MTH-FA1.LHA','fUCKADDER','XIM','fUCKADDER',NULL,'wHIRLWIND/MTH!','MTH','\_    \/    _/___|   \    |__\____  | /    \_/   \    |    \   _______/  |____. /      \     \___.    /   \    \    .    |',replace(' ______  ______   .___ ____.  _______.      \012 \_    \/    _/___|   \    |__\____  |      \012  /    \_/   \    |    \   _______/  |____. \012 /      \     \___.    /   \    \    .    | \012/________\     \  |   /______    \___|    | \012·-/X--/_________\____/-dESIGN\____\nK|____| \012           pRESENTS: fUCKADDER V1.0!        \012    oNE oF tHE fASTEST aDDER!, mAKES hIS    \012  oWN cONFIG! cAN aPPEND aDVERTS oR aN oNE  \012lINER! gET iT nOW :) cODED bY wHIRLWIND/MTH!\012--------------------------------------------\012','\012',char(10)),'fUCKADDER.dOC',replace('   .\n   |______________________          ._______.\n   ___________  ______.  /     .____|__     |______._________.\n   \_         \/      |_ ______|     _/  __________|__       |__\n    /         \/       /       |     \   \           /       . /________.\n   /___________\      /________.      \___          /________|          |\n             /_______/    \    |  .____\ /_________/nK       |__________|\n                           \______|                   /X-dESIGN!\n               pRESENTS:\n\n                              fUCKADDER v1.0\n                              ~~~~~~~~~~~~~~\n\nIntroduction:\n~~~~~~~~~~~~~\n\nfUCKADDER was coded by me (wHIRLWIND), because of all the txtadder\nI ever had, none of them was fast enough. This util is able\nto add a 2k advert on a 300 kb file in 0.25 second. \n\n\nInstallation:\n~~~~~~~~~~~~~\n\nCopy the fUCKADDER dir in DOORS: . Copy the contents of the FILECHECK\ndir in BBS: .\nThat''s all!\n\n\nConfig:\n~~~~~~~\n\nThe config of this program is simple. Just go to the CLI window and\nenter ''DOORS:FUCKADDER/FUCKADDER C''. The C option will turn on the\nconfig mode. \nThen you will get 2 questions, the second question depends on the \nanswer you gave on the first one.\n\nCONFIG MODE:\n\n1..Append advert\n2..Append Board Info\n\nIf you choose for 1 then you will be prompted to enter the path to the\nadvert. For example ''S:ADVERT.TXT''.\n\nIf you choose for 2 then you will be prompted to enter ONE line. This\nline may contain for example your board name and number etc. This option\ncan be used if you don''t want to add an advert, but still want to show\nthat the file passed your board.\n\nThe config will be saved in S: .If you already have a config the program\nwill ask if you want to overwrite the old one.\n\nGuess that''s all, but hey it''s just a txtadder ;)\n\n\nGreetings:\n~~~~~~~~~~\n\nGreetz go to:\n\nc3PO         - Thanks for the help!\nAl Capone    - Thanks for bugchecking! :)\nTeak/Myth    - The long chats! :)\nTakashi/Myth - Will you ever read this? /X is better than EVO! :)\nTHC/Myth     - I''ll lazerquest U! :)\nSlime!       - When are you going to call me again? :)\nWaldo        - You still need to learn me more swedish! At least I know what \n               SUG KUK stands for :)\nTFH/Reality  - School suxx! :)\nApollo/DDS   - How''s life as DDS Worldleader? :)\nMark''Oh      - I want some diamonds! :)\nIKilledHer   - Bitch! :)\nSal1         - Thanx for the cool chats dude!\nBug Rogers   - Still Runnin'' Runners Point? :)\nNos!         - Hehe when are you going to ring my bell again?\n\nAnd to all the other dudes I know and I forgot! :)\n\n\nBugreport, gifts, presents:\n~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nYou can reach me at my board:\n \n        dUTCH dREAMS      - +31(0)53319325\n\nOr:\n        mYSTICAL pLACES   - hOLLAND (wHIRLWIND)\n        bOONDOCKS         - hOLLAND (wHIRLWIND)\n        rUNNER''S pOINT    - gERMANY ([rING+rING^wHIRLWIND])\n        eUROPE''S cHAOS    - gERMANY ([rING+rING^wHIRLWIND])\n        dEVIL''S pOINT     - gERMANY ([rING+rING^wHIRLWIND])\n        tHE mADHOUSE      - sWEDEN  (wHIRLWIND)\n        bIO hAZARD        - cANADA  ([rING+rING^wHIRLWIND])\n        bABYLON 5         - sPAIN   ([rING+rING^wHIRLWIND])\n\n\n\n                .____.              _____.\n_____ ______.___|    |____  ________\_   | ____________________ __ _  _   _\n      \     |   |    |   /__\__      /   |____.\n________    |   |    |   _____/  ___/_   _    |   dUTCH dREAMS!\n\      /    |   |    |   |    |  \    |  |    |                \n_\_____     |____    |____    |___    |__|    | _______________ __ _  _   _\n      `-----''   `----''   `----''  `----''  `----''\n_   _  _ __ _____ ______.________ ________________.____ ______________ ____\n                  \     |   ____/   ______/___    |    Y       ______/\n            ________    |   \        ___/_   /    |         |____    |\n            \      /    |   |    |   \    |       |    Y    |   /    |\n_   _  _ __ _\_____     |___|    |____    |___    |____|    |____    | ____\n                  `-----''   `----''   `----''  `----''    `----''nK `----''\n  \n[DD sTYLE wHQ] [mYTH dHQ] [rELIGION! dHQ] [nETWORK dST] [dIAMONDS&rUST eHQ]\n[oFFICIAL DD sTYLe /X-bETATEST sITE!] [7oo mB oNLINE!] [68o3o/68882^25 mHZ]\n       [aMIGA & sNES ONLY] [o-1 dAYZ wAREZ!] [nEWUSERPW: pLEASE ]\n                  \n       [dA sYSOP: wHIRLWIND/mYTH/DD sTYLE/rELIGION/dIAMONDS&rUST]\n  [cOS!: rING+rING!/rBS/rLG/d&R][tIB/TFA!][dENNIS tHE mENACE/DD sTYLE!]\n  [jOHN sINCLAIR/rLG!][sADUS/oVl!][mEGA fORTRESS/DD sTYLE (/X dESIGN!)]\n                    [cREW-oNE/mYTH!][oRLINGO/DD sTYLE!]\n                 \n                [nODE1: +31-53319325] [nODE2: +31-pRIVATE!]\n\n','\n',char(10)),NULL,'auto-added',44712,10,0,NULL,NULL,'mth_fa1','scan',1780048628);
INSERT INTO door_catalog VALUES('mth_fa12','MTH-FA12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MTH-FA12.LHA','fUCKADDER','XIM','fUCKADDER',NULL,'wHIRLWIND/mYTH!','MTH','\_    \/    _/___|   \    |__\____  | /    \_/   \    |    \   _______/  |____. /      \     \___.    /   \    \    .    |',replace(' ______  ______   .___ ____.  _______.     \012 \_    \/    _/___|   \    |__\____  |     \012  /    \_/   \    |    \   _______/  |____.\012 /      \     \___.    /   \    \    .    |\012/________\     \  |   /______    \___|    |\012·-/X--/_________\____/-dESIGN\____\nK|____|\012          pRESENTS: fUCKADDER V1.2\012[XIM] dOOR cODED bY wHIRLWIND/mYTH! tHIS nEW\012uPDATE hAS sOME nEAT tHINGS, lIKE uSING a \012fILE rEQUESTER fOR sELECTING aDVERT! cHECK \012iT oUT! oNE oF tHE fASTEST aDDERS aROUND !\012 aPPENDS a 1k aDVERT tO 300 kB in 0.25 sEC !\012','\012',char(10)),'fUCKADDER.dOC',replace('   .\n   |______________________          ._______.\n   ___________  ______.  /     .____|__     |______._________.\n   \_         \/      |_ ______|     _/  __________|__       |__\n    /         \/       /       |     \   \           /       . /________.\n   /___________\      /________.      \___          /________|          |\n             /_______/    \    |  .____\ /_________/nK       |__________|\n                           \______|                   /X-dESIGN!\n               pRESENTS:\n\n                              fUCKADDER v1.2\n                              ~~~~~~~~~~~~~~\n\nIntroduction:\n~~~~~~~~~~~~~\n\nfUCKADDER was coded by me (wHIRLWIND), because of all the txtadder\nI ever had, none of them was fast enough. This util is able\nto add a 2k advert on a 300 kb file in 0.25 second. Further more\nthis txtadder has a fine config, build in the mainprogram. (Sorry,\nno GUI, but that would make the util bigger without any purpose).\n\nInstallation:\n~~~~~~~~~~~~~\n\nCopy the fUCKADDER dir in DOORS: . Copy the contents of the FILECHECK\ndir in BBS: .\nThat''s all!\n\n\nConfig:\n~~~~~~~\n\nThe config of this program is simple. Just go to the CLI window and\nenter ''DOORS:FUCKADDER/FUCKADDER C''. The C option will turn on the\nconfig mode. \nThen you will get 2 questions, the second question depends on the \nanswer you gave on the first one.\n\nCONFIG MODE:\n\n1..Append advert\n2..Append Board Info\n\nIf you choose for 1 then you will be prompted to enter the path to the\nadvert. For example ''S:ADVERT.TXT''. You can also press return, and\nthen you will get a requester.\n\nIf you choose for 2 then you will be prompted to enter ONE line. This\nline may contain for example your board name and number etc. This option\ncan be used if you don''t want to add an advert, but still want to show\nthat the file passed your board. After entering the name, the program\nwill ask if you want to center this line.\n\nThe config will be saved in S: .If you already have a config the program\nwill ask if you want to overwrite the old one.\n\nGuess that''s all, but hey it''s just a txtadder ;)\n\n\nGreetings:\n~~~~~~~~~~\n\nGreetz go to:\n\nc3PO         - Thanks for the help!\nAl Capone    - Thanks for bugchecking! \nTHC/Myth     - Where does THC stand for? :)\nApollo/DDS   - God of wisdom eh? :)\nYankee Rose  - This time I didn''t forget you!! :)\n\nAnd to all the other dudes I know and I forgot! :)\n\n\nBugreport, gifts, presents:\n~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nYou can reach me at my board:\n \n        dUTCH dREAMS      - +31(0)53319325\n\nOr:\n        mYSTICAL pLACES   - hOLLAND (wHIRLWIND)\n        bOONDOCKS         - hOLLAND (wHIRLWIND)\n        rUNNER''S pOINT    - gERMANY ([rING+rING^wHIRLWIND])\n        eUROPE''S cHAOS    - gERMANY ([rING+rING^wHIRLWIND])\n        dEVIL''S pOINT     - gERMANY ([rING+rING^wHIRLWIND])\n        tHE mADHOUSE      - sWEDEN  (wHIRLWIND)\n        bIO hAZARD        - cANADA  ([rING+rING^wHIRLWIND])\n        aLTERNATE rEALITY - cANADA  ([rING+rING^wHIRLWIND])\n        bABYLON 5         - sPAIN   ([rING+rING^wHIRLWIND])\n\n\n\n                .____.              _____.\n_____ ______.___|    |____  ________\_   | ____________________ __ _  _   _\n      \     |   |    |   /__\__      /   |____.\n________    |   |    |   _____/  ___/_   _    |   dUTCH dREAMS!\n\      /    |   |    |   |    |  \    |  |    |                \n_\_____     |____    |____    |___    |__|    | _______________ __ _  _   _\n      `-----''   `----''   `----''  `----''  `----''\n_   _  _ __ _____ ______.________ ________________.____ ______________ ____\n                  \     |   ____/   ______/___    |    Y       ______/\n            ________    |   \        ___/_   /    |         |____    |\n            \      /    |   |    |   \    |       |    Y    |   /    |\n_   _  _ __ _\_____     |___|    |____    |___    |____|    |____    | ____\n                  `-----''   `----''   `----''  `----''    `----''nK `----''\n  \n[DD sTYLE wHQ] [mYTH dHQ] [rELIGION! dHQ] [nETWORK dST] [dIAMONDS&rUST eHQ]\n[oFFICIAL DD sTYLe /X-bETATEST sITE!] [7oo mB oNLINE!] [68o3o/68882^25 mHZ]\n       [aMIGA & sNES ONLY] [o-1 dAYZ wAREZ!] [nEWUSERPW: pLEASE ]\n                  \n       [dA sYSOP: wHIRLWIND/mYTH/DD sTYLE/rELIGION/dIAMONDS&rUST]\n  [cOS!: rING+rING!/rBS/rLG/d&R][tIB/TFA!][dENNIS tHE mENACE/DD sTYLE!]\n  [jOHN sINCLAIR/rLG!][sADUS/oVl!][mEGA fORTRESS/DD sTYLE (/X dESIGN!)]\n                    [cREW-oNE/mYTH!][oRLINGO/DD sTYLE!]\n                 \n                [nODE1: +31-53319325] [nODE2: +31-pRIVATE!]\n\n','\n',char(10)),NULL,'auto-added',25488,10,0,NULL,NULL,'mth_fa12','scan',1780048628);
INSERT INTO door_catalog VALUES('mth_fl10','MTH-FL10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MTH-FL10.LHA','fUCK-lHA','XIM','fUCK-lHA',NULL,'wHIRLWIND/mYTH','MTH','\_    \/    _/___|   \    |__\____  | /    \_/   \    |    \   _______/  |____. /      \     \___.    /   \    \    .    |',replace(' ______  ______   .___ ____.  _______.      \012 \_    \/    _/___|   \    |__\____  |      \012  /    \_/   \    |    \   _______/  |____. \012 /      \     \___.    /   \    \    .    | \012/________\     \  |   /______    \___|    | \012·-/X--/_________\____/-dESIGN\____\nK|____| \012 iS bACK aGAIN pRESENTING: fUCK-lHA v1.o!   \012[XIM] dOOR fOR /X, cODE bY wHIRLWIND/mYTH   \012 tHIS dOOR iS aBLE tO sTRIP *ALL* aDVERTS,  \012    sHIT eTC! aLSO a vERY fAST cHECKER!     \012','\012',char(10)),'fUCK-lHA.dOC',replace('   .\n   |______________________          ._______.\n   ___________  ______.  /     .____|__     |______._________.\n   \_         \/      |_ ______|     _/  __________|__       |__\n    /         \/       /       |     \   \           /       . /________.\n   /___________\      /________.      \___          /________|          |\n             /_______/    \    |  .____\ /_________/nK       |__________|\n                           \______|                   /X-dESIGN!\n               pRESENTS:\n\n                              fUCK-lHA v1.o\n                              ~~~~~~~~~~~~~\n\nIntroduction:\n~~~~~~~~~~~~~\n\nfUCK-lHA was coded by me (wHIRLWIND) because of all the LHA\ncheckers I ever had, no ONE of them stripped ALL the adverts,\nso I made this piece of shit. It will remove ALL adverts !\n\nInstallation:\n~~~~~~~~~~~~~\n\nCopy the fUCK-lHA dir in DOORS: . Copy the contents of the FILECHECK\ndir in BBS: .\nThat''s all!\n\n\nConfig:\n~~~~~~~\nThere is almost no config. The file needs only ONE other file,\nthat is the file S:fUCK-lHA.ADD . In this file you have to\nput the files (and their path) which need to be added.\nSomething like this:\n--- cut here ---\nS:ADDME.BOARD\nS:TRILALAL.BOARD\n--- cut here ---\n\nYou can put as much files as you want.\nBTW use LHA V1.50r! It worked fine on it on my board!\n\nGreetings:\n~~~~~~~~~~\n\nGreetz go to:\n\ncREW oNE/mTH - THC Chat is cool!\nTHC/Myth     - Use this thing! :)\nApollo/DDS   - How long do we know eachother now? :)\nYankee Rose  - And I still haven''t forgot you :)\n\nAnd to all the other dudes I know and I forgot! :)\n\n\nBugreport, gifts, presents:\n~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nYou can reach me at my board:\n \n        dUTCH dREAMS      - +31(0)53319325\n\nOr:\n        mYSTICAL pLACES   - hOLLAND (wHIRLWIND)\n        bOONDOCKS         - hOLLAND (wHIRLWIND)\n        rUNNER''S pOINT    - gERMANY ([rING+rING^wHIRLWIND])\n        eUROPE''S cHAOS    - gERMANY ([rING+rING^wHIRLWIND])\n        dEVIL''S pOINT     - gERMANY ([rING+rING^wHIRLWIND])\n        tHE mADHOUSE      - sWEDEN  (wHIRLWIND)\n        bIO hAZARD        - cANADA  ([rING+rING^wHIRLWIND])\n        aLTERNATE rEALITY - cANADA  ([rING+rING^wHIRLWIND])\n        bABYLON 5         - sPAIN   ([rING+rING^wHIRLWIND])\n\n\n\n                .____.              _____.\n_____ ______.___|    |____  ________\_   | ____________________ __ _  _   _\n      \     |   |    |   /__\__      /   |____.\n________    |   |    |   _____/  ___/_   _    |   dUTCH dREAMS!\n\      /    |   |    |   |    |  \    |  |    |                \n_\_____     |____    |____    |___    |__|    | _______________ __ _  _   _\n      `-----''   `----''   `----''  `----''  `----''\n_   _  _ __ _____ ______.________ ________________.____ ______________ ____\n                  \     |   ____/   ______/___    |    Y       ______/\n            ________    |   \        ___/_   /    |         |____    |\n            \      /    |   |    |   \    |       |    Y    |   /    |\n_   _  _ __ _\_____     |___|    |____    |___    |____|    |____    | ____\n                  `-----''   `----''   `----''  `----''    `----''nK `----''\n  \n[DD sTYLE wHQ] [mYTH dHQ] [rELIGION! dHQ] [nETWORK dST] [dIAMONDS&rUST eHQ]\n[oFFICIAL DD sTYLe /X-bETATEST sITE!] [7oo mB oNLINE!] [68o3o/68882^25 mHZ]\n       [aMIGA & sNES ONLY] [o-1 dAYZ wAREZ!] [nEWUSERPW: pLEASE ]\n                  \n       [dA sYSOP: wHIRLWIND/mYTH/DD sTYLE/rELIGION/dIAMONDS&rUST]\n  [cOS!: rING+rING!/rBS/rLG/d&R][tIB/TFA!][dENNIS tHE mENACE/DD sTYLE!]\n  [jOHN sINCLAIR/rLG!][sADUS/oVl!][mEGA fORTRESS/DD sTYLE (/X dESIGN!)]\n                    [cREW-oNE/mYTH!][oRLINGO/DD sTYLE!]\n                 \n                [nODE1: +31-53319325] [nODE2: +31-pRIVATE!]\n\n','\n',char(10)),NULL,'auto-added',13724,5,0,NULL,NULL,'mth_fl10','scan',1780048628);
