INSERT INTO door_catalog VALUES('mth_hc20','MTH-HC20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MTH-HC20.LHA','HoldCheck','XIM','HoldCheck',NULL,'KEROSENE/MYTH','MTH','\_    \/    _/___|   \    |__\____  | /    \_/   \    |    \   _______/  |____. /      \     \___.    /   \    \    .    |',replace(' ______  ______   .___ ____.  _______.\012 \_    \/    _/___|   \    |__\____  |\012  /    \_/   \    |    \   _______/  |____.\012 /      \     \___.    /   \    \    .    |\012/________\     \  |   /______    \___|    |\012·-----/_________\____/-------\____\nK|____|\012|                                         |\012|          /X DiViSiON PRESENTS:          |\012|            HOLDCHECKER 1.0              |\012|            BY KEROSENE/MYTH             |\012`-----------------------------------------''\012','\012',char(10)),'HoldCheck.doc',replace('                     _________                           _______._\n   __________ /\_____\        \  ________________________\_     |_______\n   \         /_       \        \/      _._______         /      |       |\n  /         \/_________\___    /      __|      /________/       _       |\n /___________\           /_____________\l_______|      /________|       |\n                                                                l_______|\n\n                                 Presents\n\n                             HoldChecker v2.0\n\n                                    By\n\n                               KeroSene/Myth\n\n\n                   This program is freely distributed as\n                   long as all files remain unmodified.\n                   I will not take any reponsibility of\n                 any problems that this program may cause.\n                         (it shouldn''t cause any.)\n\n\n\n\nThis archive (mth-hc20.lha) should contain these files:\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nDoors/Kero-HoldCheck/\n   HoldCheck            11196 bytes   The main file.\n   HoldCheck.info         905 bytes   The Icon Config File!\n   HoldCheck.doc         5397 bytes   This doc file...\n\nCommands/SYSCMDCmd/\n   EXAMINE×.info         1069    The icon file for checking the uploads.\n\n\n\n\nIntruduction!\n~~~~~~~~~~~~~~\nHave you thought about that there is some unknown files in your hold dir\nthat you didn''t know about, well this door will write a mess to the sysop\nand notify the sysop by writing the filename, file_id.diz and ofcourse the\nuploader. this door will be started everytime someone uploads and if the\nuploader uploads a file to the hold dir this door will detect that the\nfile is uploaded to hold and writing the mess. This door is total uniqe,\nand its copyright KeroSene/Myth.\n\n\n\n\nInstallation!\n~~~~~~~~~~~~~~\nCopy all files from Doors/ and Commands/ to BBS: ... And then your\ninstallation is done. Now you only need to configure the holdchecker.\n\n\n\nTooltypes : HoldChecker.info!\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n------------------------------------------------------------------------\nsyntax : TO_NAME.x=<SYSOPS NAME>\nexample: TO_NAME.1=CRAWL\n\nthis tooltype is users/cosysop/sysop that is going to recive the message\nwhen a user has uploaded something in hold.\n\n------------------------------------------------------------------------\nsyntax : REASON=<REASON>\nexample: REASON=- Hold Upload -\n\nthis tooltype is the reason of the mess that the sysops going to recive.\n\n------------------------------------------------------------------------\nsyntax : OUTPUT=<ALWAYS/ONLY>\nexample: OUTPUT=ALWAYS\n\nthis tooltype can be ALWAYS or ONLY. If ALWAYS the output on holdcheck\nwill be shown everytime that the door runs, or ONLY the ouput will only\nbe shown when a holdupload is done!\n\n------------------------------------------------------------------------\n\n\n\n\nWhat is it!\n~~~~~~~~~~~~\nIt''s a door made by KeroSene of Myth. Coded in C (SAS/C 6.55).\nIt checks for hold uploads. if the door discovers a hold upload it\nwill notify sysop by create a message.\n\n\n\n\nHistory!\n~~~~~~~~~\n(ß) 0.1 - 95-05-12 - Just a ßeta release (non working shit).....\n\n(ß) 0.2 - 95-05-21 - New output and it won''t fuckup. (i hate writing history).\n\n(P) 1.0 - 95-06-14 - First public release.\n\n(ß) 1.2 - 95-06-18 - The sysop can define the output (yes/only). Bugg fixed.\n                     Nicer output. The door will write a private mess to the\n                     sysop instead of public. The third beta release.\n\n(P) 2.0 - 95-21-10 - Some Mini bugs fixed. Releze is now spelled Release.\n                     MailLock is locked (it means that your msgbase can''t\n                     crash, not by runing this door) Can also write a \n                     message to more than one sysop.\n\n\n\n\n\n\n                            Places to reach me!\n                           ~~~~~~~~~~~~~~~~~~~~~\n                                Acid Attack\n                                 Death Row\n                              Future Entrance\n                           Masturbation Station\n                              Mystical Places\n                                The Payoff\n                                Wasted Time\n                                \n                        and ofcourse at #amigascene\n\n\n\n\n\n                                Messages!\n                               ~~~~~~~~~~~\n                         Amon - Burzum = yuck, NM8 = rewlez!\n\n                       Azazel - I love your modules!!!\n                       \n                  Black Beard - Start beta testing the CAC door to =)\n\n                        Crawl - Sorry for not calling your board (i have not\n                                enuff money to do that =(((\n                                \n                      Dalamar - No more lame crapp about me (i hope)?\n\n                       Delite - Thanx for joining me into myth\n                       \n                       Diablo - What is "Abuse your ratio" =))))\n                       \n                         Mode - What about getting some info before screaming\n                                out the shit?\n\n                       Recall - Move.l #kerosene #NIL:\n\n                        Vital - Axe Man.\n\n                          Qen - Sorry mate, the myth guys was faster than\n                                you =)\n\n\n\n\n\n                                Greetings!\n                               ~~~~~~~~~~~~\n       amon. aquarius. bionic. biscrok. exeron&maniac. nero. diablo\n       cray-1. crawl. dansken. dildo. boogeyman. activate. cenotaph\n       v-cut. neptune. recall. frosty. qen. vegas. stryper. wingnut\n        black beard. mr.wishbone. the violater. vital. magz. storm\n           punisher. sinister. wraith. skize. vietcong. twister.\n                            azazel. thc. delite\n\n                             and all i forgot\n\n\n\n','\n',char(10)),NULL,'auto-added',17257,5,0,NULL,NULL,'mth_hc20','scan',1780048628);
