NE MESSAGES AND MULTi-CHATS |\n  `::::::::::::::`------------+  NUP IS REQUIRED SO ASK WHOEVER POSTED  |\n   `::::::::::::::::::::::::::|    THIS ADVERT FOR THE NUMBER AND NUP   |\n    `:::::::::::::::::::::::::`-----------------------------------------''\n','\n',char(10)),NULL,'auto-added',44562,5,0,NULL,NULL,'mth_ir12','scan',1780048628);
INSERT INTO door_catalog VALUES('mth_ir3','MTH-IR3.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MTH-IR3.LHA',NULL,'XIM','29-07-95',NULL,'cREW^oNE','MTH','\_    \/    _/___|   \    |__\____  | /    \_/   \    |    \   _______/  |____. /      \     \___.    /   \    \    .    |',replace(' ______  ______   .___ ____.  _______.\012 \_    \/    _/___|   \    |__\____  |\012  /    \_/   \    |    \   _______/  |____.\012 /      \     \___.    /   \    \    .    |\012/________\     \  |   /______    \___|    |\012·dDT!-/_________\____/-------\____\nK|____|\012       /X dIVISION rELEASED tODAY:\012      bIRC-cHAT V1.03 bY cREW^oNE !\012 nEW! hOTKEYS fOR mOST uSED cOMMANDS !\012\012\012','\012',char(10)),'uzi.txt',replace('                                            .---------------------------.\n    _______.-----------------._______/|     |     4NODEZ  RiNGDOWN      |\n    \_     |     .------     |________|.....| 73 GiG OF AMiGA CoNSoLE PC|\n   .:|     |     |     ______|        |:::::|  uZiSUiCiDE.sERVEBBS.ORG  |\n  .::|     |     |     |     |        |-----+-----.      TELNET         |\n .:::|           |     |     |       :|     |     |                     |\n.::::\___________|___________|________|     `-----+---------------------''\n:::::::::::::::::|                                | 24HR 7DAY STATiC iP! \n_________________|___________/|__________________/|______________________\n\_     ______    |     _______|          |_____________      _/    _____/\n_|_____    |     |     |      |    |_____|        |   |      |     ___|_ \n|     |    |     |     |      |    |     |        |   |      |     |    |\n|     |    |     |     |     :|          |       :|   |      |     |    |\n|__________|_____|_____|______|__________|________|__________|__________|\n:::::::::::::::::|            |                                         |\n`::::::::::::::::|            |ALWAYS THE LATEST VERSION oF AMi-EXPRESS |\n `:::::::::::::::|            | TONS OF ONLiNE MESSAGES AND MULTi-CHATS |\n  `::::::::::::::`------------+  NUP IS REQUIRED SO ASK WHOEVER POSTED  |\n   `::::::::::::::::::::::::::|    THIS ADVERT FOR THE NUMBER AND NUP   |\n    `:::::::::::::::::::::::::`-----------------------------------------''\n','\n',char(10)),NULL,'auto-added',31321,7,0,NULL,NULL,'mth_ir3','scan',1780048628);
INSERT INTO door_catalog VALUES('mth_md1','MTH-MD1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MTH-MD1.LHA','mOREdOORZ','XIM','______  ______   .___ ____.  _______.',NULL,'cREW^oNE!','MTH','\_    \/    _/___|   \    |__\____  | /    \_/   \    |    \   _______/  |____. /      \     \___.    /   \    \    .    |',replace(' ______  ______   .___ ____.  _______.\012 \_    \/    _/___|   \    |__\____  |\012  /    \_/   \    |    \   _______/  |____.\012 /      \     \___.    /   \    \    .    |\012/________\     \  |   /______    \___|    |\012·dDT!-/_________\____/-------\____\nK|____|-\012       /X dIVISION rELEASED tODAY:\012 mOREdOORZ mULTISTARTER v1.00 bY cREW^oNE!\012   Now you can start FILECHECK doors as\012            EXAMINE doors !!\012\012','\012',char(10)),'MoreDoorz.guide',replace('@DATABASE MoreDoorz V1.0 Documentation © PLL Developments 1995\012@REM This is an AmigaGuide® - Document\012@REM Please use Multiview or any similar program to read this documentation\012@REM Otherwise ignore the @-Commands in this text.\012@NODE MAIN "MoreDoorz V1.0 © 1995 bY CREW^ONE!MYTH!DDT!"\012   .\012   |______________________          ._______.\012   ___________  ______.  /     .____|__     |______._________.\012   \_         \/      |_ ______|     _/  __________|__       |__\012    /         \/       /       |     \   \           /       . /________.\012   /___________\      /________.      \___          /________|          |\012             /_______/    \    |  .____\ /_________/nK       |__________|\012                           \______|\012                                  ·    /________________________________.\012                                                                        |\012\012                                 PRESENTS:\012@{b}\012                        MoreDoorz V1.0 - 28 Jul 1995\012                        Copyright (c) 1995 cREW^oNE!\012                    Documentation Copyright (c) 1995 PLL\012                            All rights reserved\012                           A mYTH! Release <MTH>\012@{ub}\012                            @{"   Introduction   " LINK INTRO}\012                            @{"   Installation   " LINK INSTALL}\012                            @{"  Configuration   " LINK CONFIG}\012                            @{" Revision History " LINK VERSION}\012                            @{" Acknowledgements " LINK GREETS}\012\012                            @{"     Releases     " LINK RELEASES}\012                            @{"   Myth boards    " LINK MYTH}\012                            @{" Mystical Places  " LINK MP}\012@ENDNODE\012\012@NODE INTRO "Introduction..."\012\012MoreDoorz from the Myth Door Development Team makes it possible to\012launch multiple programs for one command, since inserting multiple commands\012is not supported in AmiExpress. For example: you can use it for the\012FILECHECK in BBS:Commands/SysCmd/ but it also allows you to start multiple\012doors for a normal command on the AmiExpress main prompt, therefore,\012MoreDoorz is only limited to your imagination.\012\012MoreDoorz requires OS2.04 (V37) and AmiExpress V4.xx or higher.\012\012    @{"BACK TO MAIN" link "Main" 0}\012@ENDNODE\012\012@NODE INSTALL "Installation..."\012\012To install MoreDoorz, just copy ALL files in the MoreDoorz/BBS drawer to\012your BBS: directory, that means that you need the logical assignment BBS:\012BBS: is an assignment to the root directory of AmiExpress. (configured in\012the ACP.info, for example, BBS_LOCATION=BBS:) Further you need the logical\012assignment DOORS: (DOORS: is an assignment to your BBS:Doors directory).\012\012MoreDoorz is 100% compatible with 5d-multistart, exept for the\012PASSWORD tooltype.\012\012If you have done all this then you have installed MoreDoorz correctly,\012congratulations!\012\012    @{"BACK TO MAIN" link "Main" 0}\012@ENDNODE\012\012@NODE CONFIG "Configuration..."\012\012If the installation part went right, you now have an extra directory in your\012BBS:Commands/ path, named MultiCmd. In this directory are the icons which\012will be processed by MoreDoorz.\012\012ToolTypes in BBS:COMMANDS/SYSCMD/<NAME>.info AND/OR\012             BBS:COMMANDS/BBSCMD/<NAME>.info\012---------------------------------------------------\012\012============== CUT HERE =============\012LOCATION=BBS:Doors/MoreDoorz         - Specifies the location of the door\012MULTINODE=YES                        - tells /X if the module may be\012                                       simultaneously accessed from other\012                                       nodes.\012ACCESS=10                            - tells /X the access level required\012                                       to run this door.\012TYPE=<XIM|AIM|TIM|IIM|SIM|MCI>         tells /X which type of module it is\012                                       to support\012STACK=4096                           - Specifies the stack needed to\012                                       launch the door.\012============== CUT HERE =============\012\012\012TOOLTYPES IN BBS:COMMANDS/MULTICMD/<NAME>.info\012----------------------------------------------\012\012======== CUT HERE =======\012LOCATION.(NUM)=<LOCATION>\012STACK.(NUM)=<STACKSIZE>\012PRIORITY.(NUM)=<PRIORITY>\012DOORNAME.(NUM)=<NAME>\012CONVERT_FILECHECK.(NUM)\012======== CUT HERE =======\012\012\012LOCATION.(NUM)=<LOCATION>\012-------------------------\012\012This Tooltype let you specify the location of the door.\012\012Example:\012\012LOCATION.1=DOORS:5D-Who/5D-Who\012LOCATION.2=DOORS:5D-JoinConf/5D-JoinConf\012\012\012STACK.(NUM)=<STACKSIZE>\012-----------------------\012\012This tooltype specifies the stack needed to launch the door.\012\012Example:\012\012STACK.1=4096\012STACK.2=8192\012\012\012PRIORITY.(NUM)=<PRIORITY>\012-------------------------\012\012This tooltype let you specify the priority needed to launch the door.\012\012Example:\012\012PRIORITY.1=0\012PRIORITY.2=-10\012\012\012DOORNAME.(NUM)=<NAME>\012-------------------\012\012This tooltype let you specify the doorname.\012\012Example:\012\012DOORNAME.1=5D-Who\012DOORNAME.2=5D-JoinConf\012\012This serves no real purpose, except for letting AmiExpress think that\012''5D-Who'' was executed in stead of ''mOREdOORZ''. With some doors, you\012can fool the built in security with this.\012\012CONVERT_FILECHECK.(NUM)\012-----------------------\012\012This tooltype specifies the filecheck door which can be runned on the\012examine position.\012\012Example:\012\012CONVERT_FILECHECK.1\012CONVERT_FILECHECK.2\012\012This tooltype has only purpose when mOREdOORZ is located in one of the\012EXAMINE-door positions. (e.g. EXAMINE1)\012\012When you put this tooltype (e.g. CONVERT_FILECHECK.1) in you icon, the\012corresponding location (in this case LOACTION.1) must point to a\012FILECHECK door. Then mOREdOORS will convert the examine-door aguments\012string to an filecheck-door string. This will allow you to run\012filecheck door in EXAMINE-door.\012\012\012    @{"BACK TO MAIN" link "Main" 0}\012@ENDNODE\012\012@NODE VERSION "Revision History..."\012\012 V1.0 - 28 Jul 1995\012      - First public release\012\012If you have any suggestions, bug reports or questions, please contact Crew\012One at one of the electronic mail addresses.\012\012When sending in bug reports, please state exactly under what circumstances\012the bug occurred, what equipment was used and what happened. If possible\012also try to give me enough information to reproduce the bug. It is very\012difficult to find bugs when you don''t know exactly what happened. Please\012don''t just send messages like "MoreDoorz doesn''t work", that really doesn''t\012help me. If possible, submit the offending ''error'' to me so I can test it\012myself, or give me a pointer where I can find the error.\012\012    @{"BACK TO MAIN" link "Main" 0}\012@ENDNODE\012\012@NODE GREETS "Acknowledgements..."\012\012                gREETINGS tO tHEZE dUDEZ: (iN aLPHABETICAL oRDER!)\012\012        Badsector - EMPIRE - Fury - MARIO - MEGA^FORTRESS - Muad''Dib\012     One - Phantom - Price - SAL-1 - sLIME - Snake & Delboy - wHIRLwIND\012\012\012                           All mYTH betatesters!\012                             All mYTH members!\012                             All rOYAL members!\012\012    @{"BACK TO MAIN" link "Main" 0}\012@ENDNODE\012\012@NODE RELEASES "Releases..."\012\012MTH-IR12.LHA                      ______  ______   .___ ____.  _______.\012                                  \_    \/    _/___|   \    |__\____  |\012                                   /    \_/   \    |    \   _______/  |____.\012                                  /      \     \___.    /   \    \    .    |\012                                 /________\     \  |   /______    \___|    |\012                                 ·-----/_________\____/-------\____\nK|____|\012                                        /X dIVISION rELEASED tODAY:\012                                       bIRC v1.2 uPDATE (27-Jun-95!)\012                                            cODED bY: cREW^oNE\012                                 ·------------------------------------------·\012MTH-RW12.LHA                      ______  ______   .___ ____.  _______.\012                                  \_    \/    _/___|   \    |__\____  |\012                                   /    \_/   \    |    \   _______/  |____.\012                                  /      \     \___.    /   \    \    .    |\012                                 /________\     \  |   /______    \___|    |\012                                 ·-----/_________\____/-------\____\nK|____|\012                                        /X dIVISION rELEASED tODAY:\012                                       rEAL tIME wHO V2.1 (27-Jun-95)\012                                             cODED bY: cREW^oNE\012                                 ·------------------------------------------·\012MTH-VIEW.LHA                               _ _______ _______     .......\012                    