INSERT INTO door_catalog VALUES('mth_nu11','MTH-NU11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MTH-NU11.LHA','nup','XIM','nup',NULL,'wHIRLWIND!','MTH','\_    \/    _/___|   \    |__\____  | /    \_/   \    |    \   _______/  |____. /      \     \___.    /   \    \    .    |',replace(' ______  ______   .___ ____.  _______.      \012 \_    \/    _/___|   \    |__\____  |      \012  /    \_/   \    |    \   _______/  |____. \012 /      \     \___.    /   \    \    .    | \012/________\     \  |   /______    \___|    | \012·-/X--/_________\____/-dESIGN\____\nK|____|-\012        pRESENTS : aBREV-nUP v1.1!          \012nO lOCAL lAMERS aNYMORE! tHIS dOOR rEPLACES \012tHE iNTERNAL nUP! gIVES aN aBBREVATION, aSKS\012fOR iTS mEANING! cONFIGABLE, rANDOMLY       \012cHOOSES tHE aBBREVATION! cODED bY wHIRLWIND!\012--------------------------------------------\012----------------------------)) PLLDM ((-','\012',char(10)),'nup.doc',replace('   .\012   |______________________          ._______.\012   ___________  ______.  /     .____|__     |______._________.\012   \_         \/      |_ ______|     _/  __________|__       |__\012    /         \/       /       |     \   \           /       . /________.\012   /___________\      /________.      \___          /________|          |\012             /_______/    \    |  .____\ /_________/nK       |__________|\012                           \______|                   /X-dESIGN!\012               pRESENTS:\012\012                             aBBREVATION-nUP v1.1\012                             ~~~~~~~~~~~~~~~~~~~~\012\012Introduction:\012~~~~~~~~~~~~~\012\012aBBREVIATION-nUP is a NUP door! It can be used if you don''t want any\012new users who are not known with the scene/elite concept! It has its own\012config file and it chooses RANDOMLY every time an abbreviation.\012It has a nice lay-out and you can also show a file if you want to.\012\012\012Installation:\012~~~~~~~~~~~~~\012\012Very simple, just copy the contents of this archive to ur BBS: directory.\012Don''t forget to copy the NUP.CFG in S:! Copy the AEDOOR.LIBRARY in LIBS:\012et voila!\012\012\012Config:\012~~~~~~~\012\012S:NUP.CFG:\012~~~~~~~~~~\012\012Only one line containing the path to your config file!\012For example:\012-- cut here --\012DOORS:NUP/NUP.CFG\012-- cut here --\012\012I''ve made this so you can put ur configfile everywhere u want without\012any probs! :)\012\012DOORS:NUP/NUP.CFG:\012~~~~~~~~~~~~~~~~~~\012\012Ofcourse this config can have another name or/and path, but this is \012just an example!\012The config :\012\012-- cut here --\01211\012\0126\0121000\012PDX\012PARADOX\012FLT\012FAIRLIGHT\012CLS\012CLASSIC\012TDR\012TRADERS DREAM\012MTH\012MYTH\012PSG\012PRESTIGE\012FUCK\012FORGIVE US CRAZY KIDS\012TRSI\012TRISTAR RED SECTOR INCORPORATED\012LNS\012LOONS\012ACS\012ACCES\012MST\012MYSTIC\012-- eof --\012\012First line is how many abbrevations you want to use!\012\012Second line is optional, the path to a textfile you want to show.\012if you would enter ANYTHING it would disable the third line and it\012would not show any returns. (for example DOORS:NUP/NUP.TXT)\012\012Third line will only be used if the second line is empty. It contains\012how many returns should be entered before showing the abbrev.!\012\012Fourth line is the random interval. For example 1000\012would give 1000 combinations. This doesn''t mean that there are 1000\012abbreviations!\012\012And the rest of the config should contain the abbrevations and their\012meanings:\012<abbrev>\012<what it should be :) >\012etc..\012\012That''s all!\012\012CAUTION!:\012~~~~~~~~~\012\012You need to pay attention when configing this door! I tried it on a\012fellow /X coder in my group, and he didn''t know them all! So if you\012want some users at all (also the ''rookies'') then don''t put abbreviations\012which will be unknown to him! :) On the other hand now you can config it\012how you want it, if you want only ''real'' elite dudes who know a lot\012of the scene then u should put the names of the not so known groups\012as well. Anyway, I have implented 3 retries and every time it should\012be different, so if the new user doesn''t know one, he maybe will know\012the other! :)\012\012Using in /X\012~~~~~~~~~~~\012\012You need to use MCI commands, becoz /X has not the ability to use\012a NUP door (yet?)! So you should put in GuestLogon.TXT  (located in\012your screens dir) something like this:\012\012-- cut here --\012~ \012~CC_NEWUSER \012~SS_BBS:SCREENS/NODE/NEW.TXT \012-- cut here --\012\012If you don''t know how to work with MCI commands, then I advise you to\012look it up in the /X docs!\012\012Don''t forget to remove the internal new user password procedure in\012the NodeX icon!\012\012\012Greetings:\012~~~~~~~~~~\012\012Greetz go to:\012\012Sintax/OTL/WOT        - Thanx for ur help & the right units!\012Venom                 - Thanx for ur help!\012GMC!                  - Thanx for the FAST upcase routine!\012Crew One/Myth         - Thanx for the moral support :)\012DeltaForce            - Nice chatting to u & thanx for ur help!\012THC/Myth              - Thanx for being a cool leader! :)\012Apollo/DDS            - Gosh, another cool leader :)\012Yankee Rose           - 2 bad ur computer blew up! :(\012Frantik/TRSI          - Thx for betatesting!\012Slime/BP/Myth!        - Thx for betatesting!\012Keyboard Kid/Acs/Myth - This Kid can''t be from Canada! :)\012RaJ!/Acs/Myth         - Trading gives me an orgasm! :)\012\012And to all members of RLG/D&R/DDS/MTH and ofcoz the dudes I didn''t\012mention!\012\012\012Bugreport, gifts, presents:\012~~~~~~~~~~~~~~~~~~~~~~~~~~~\012\012You can reach me at my board:\012 \012        dUTCH dREAMS      - +31(0)53319325\012\012Or:\012        mYSTICAL pLACES   - hOLLAND  (wHIRLWIND)\012        bOONDOCKS         - hOLLAND  (wHIRLWIND)\012        dEVIL''S pOINT     - gERMANY  (wHIRLWIND)\012        sPIRITS oF sOUL   - gERMANY  (wHIRLWIND)\012        tHE mADHOUSE      - sWEDEN   (wHIRLWIND)\012        bABYLON 5         - sPAIN    (wHIRLWIND)\012        lITHIUM           - USA      (wHIRLWIND)\012        dARK sUN          - oZZYLAND (wHIRLWIND)\012\012And at any MYTH/DDS/D&R/RLG board!\012\012 ______  ______   .___ ____.  _______.                                         \012 \_    \/    _/___|   \    |__\____  |                                         \012  /    \_/   \    |    \   _______/  |____.   cALL oNE oF THE mYTH bOARDS      \012 /      \     \___.    /   \    \    .    |            wORLDWIDE               \012/________\     \  |   /______    \___|    |                                    \012·-----/_________\____/-------\____\nK|____|------ -- -- --- -- --  --  - - -   \012                                                                               \012   mYSTICAL pLACES     WHQ        +31-10-4779507    [3 nODEZ,21k6,rING]        \012                                  +31-10-4774218    [1 nODE, 28k8 oNLY]        \012                                                                               \012   dUTCH dREAMS        DHQ        +31-53-319325     [1 nODE, 14k4]             \012                                                                               \012   rED lIGHT dISTRICT  CHQ        +1-905-508-7356   [1 nODE, 28K8]             \012                                                                               \012   hOMeLESS            GHQ        +49-aSK-uS!-nOW   [1 nODE, 14k4]             \012                                                                               \012   oFF-lIMITS          dIST-SITE  +49-aSK-uS!-nOW   [1 nODE, 19k2]             \012                                                                               \012------------------------------------------------ -- -- --- -- --  --  - - -\012\012','\012',char(10)),NULL,'auto-added',24254,8,0,NULL,NULL,'mth_nu11','scan',1780048628);
