INSERT INTO door_catalog VALUES('mth_st12','MTH-ST12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MTH-ST12.LHA','MTHStats12','XIM','MTHStats12',NULL,'pLL/mYTH','MTH','\_    \/    _/___|   \    |__\____  | /    \_/   \    |    \   _______/  |____. /      \     \___.    /   \    \    .    |',replace('______  ______   .___ ____.  _______.\012\_    \/    _/___|   \    |__\____  |\012 /    \_/   \    |    \   _______/  |____.\012/      \     \___.    /   \    \    .    |\012________\     \  |   /______    \___|    |\012-/X--/_________\____/-dESIGN\____\nK|____|\012»»--------------------------------------««\012        pRESENTS: mYTH sTATUS v1.2   \012  "S" rEPLACEMENT fOR /X 3.xx & /X 4.xx\012            cODED bY pLL/mYTH              \012»»--------------------------------------««\012','\012',char(10)),'MTHStats12.dOC',replace('$VER: /X\ STATS V1.2 - © PLL Developments 1994 - 29 Nov 1994 19:12:39\n\n\nNAME\n     MTHStats V1.2 - Requires V37 and /X V3.9 as well as aedoor.library\n     in your libs: directory.\n\nSYNOPSIS\n    Shows /X Statistics. MTHStats12 is a XIM DOOR.\n\nFUNCTION\n    Show Statistics of Sysop and User.\n    To use, copy MTHStats12 in your DOORS: directory, and make an icon in\n    BBS:Commands/BBSCmd with the tooltypes:\n\n    LOCATION=BBS:DOORS/MTHStats12\n    MULTINODE=<YES|NO>\n    ACCESS=<num>\n    TYPE=XIM\n    STACK=<num>\n    PASSWORD=<string>\n\n    An example is included in this release.\n\nINPUTS\n    None. Just type the name of the icon in BBS:Commands/BBSCmd.\n\nRESULTS\n    Various statistics about user and sysop.\n\nNOTES\n    Should work on all /X versions (Tough I''m not sure).\n\nSEE ALSO\n    "I haven''t lost my mind -- it''s backed up on tape somewhere."\n\nACKNOWLEDGEMENTS\n    Regards must go to (In random order!): RAJ!, Blade/PSI, EuroSoft,\n    Taz Devil, THC, Sigh, TDB, CrewOne, DELITE, Rubyx, TUS, Zack, Whirly,\n    Teak, Takashi, NIKE, Kylix, Apollo, ICE, T/\rget, NSC, Dextron,\n    Babyface, PinHead, D-Lorean, Mad Max, Telekinetic, You, and everyone\n    else I forgot...\n\nREVISION:\n    V1.0 - 10 Jul 1994 - Initial release.\n    V1.1 - 15 Jul 1994 - Changes in design.\n                       - New options rATIO, rATIOTYPE, cURRENT cONFERENCE\n                         cONFERENCE aCCESS, sYSOP sTATUS.\n                       - Displays eNcRyPtEd Message in password.\n                       - optimized code.\n    V1.1b- 17 Jul 1994 - Bug Fix: UpLoad Bytes=Download Bytes.\n    V1.1c- 17 Jul 1994 - Bug Fix: Ratio = 3:1 instead of 1:3.\n    V1.2 - 29 Nov 1994 - /X\ Stats is now in ANSI Colors.\n\nBUGS\n    None known.\n\n\n                DON''T FORGET TO CALL ONE OF OUR MYTH BOARDS\n\n ____ _ _  X  __/\__ __ _ _      .                             .  ___ _\n/_/\ __ _ /:\ \-oo-/             :_____________________________: /\_\_ _\n\_\/__   /:: \/_- _\/\           ¡ ¬\                       / :¡ \/_/__\n        /::·  \ \/ /  \__________|   \________     ________/  :|________\n       /::·    \  /    \       ::|         ¬\       |         :|.::::.::\\n      /::·      \/      \      ::¡           \    .:|      ____¡       ·:\\n     /::·                \                   /    ::|      \  ¬         ·:\\n    /::·     \____/       \_______          /     ::|       \___         ·:\\n   /::·       ¬|::         \   ::|         /      ::|        ::|          ·:\\n__/::·         |::          \   :¡        /|      ·:|        ::|           ·:\\n\:::·          |::           \           /:|       :|         :|             /\n \_____________|::            \_________/::¡________¡__________¡____________/\n÷%÷%÷%÷%÷%÷%÷%÷|::              /÷%÷%÷%÷%÷%÷%÷%÷%÷%÷%÷%÷%÷%÷%÷%÷%÷%÷%÷%÷ ZACK\n               ¡_______________/\n   -     -    -  -  -  - - - - - - - -- ---[÷tHANX÷fOR÷cALLING÷mYTH÷WHQ!÷]-- -\n\n\nmYSTICAL pLACES    [4 nODEZ]  (WhQ)       +31-10-4779507 (3 noDEZ rINGDOWN)\n                                          +31-10-4774218 (1x 28k8 oNLY)\n\ndUTCH dREAMS       [1 nODE]   (DHQ)       +31-53-319325\n\noFF-lIMITS         [1 nODE]   (dIST-sIDE) +49-543-937-20\n\nrED lIGHT dISTRICT [1 nODE]   (CHQ]       +1-905-508-7356\n\n','\n',char(10)),'{"LOCATION":"BBS:DOORS/MTHStats12","ACCESS":"<num>","TYPE":"XIM","STACK":"<num>"}','auto-added',14331,2,0,NULL,NULL,'mth_st12','scan',1780048628);
INSERT INTO door_catalog VALUES('mth_tc23','MTH-TC23.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MTH-TC23.LHA','THC-CHATTER','XIM','THC-CHATTER',NULL,NULL,'MTH','\_    \/    _/___|   \    |__\____  | /    \_/   \    |    \   _______/  |____. /      \     \___.    /   \    \    .    |',replace(' ______  ______   .___ ____.  _______.\012 \_    \/    _/___|   \    |__\____  |\012  /    \_/   \    |    \   _______/  |____.\012 /      \     \___.    /   \    \    .    |\012/________\     \  |   /______    \___|    |\012·-----/_________\____/-------\____\nK|____|\012--------------------------------------------\012--> THC-CHATTER V2.30 <> FINAL RELEASE <----\012->                                        <-\012--> CODED BY: CREW ONE / (M)yth /X )-Sign <-\012--------------------------------------------\012','\012',char(10)),'THC-CHATTER.GUIDE',replace('@database THCCHAT.guide\n## August 28, 1994\n## This is a doc file in the amigaguide.library format.\n@width 75\n\n@Node Main "Help"\n\n _____________ ________________  _________________ ________________________\n \___  _____  Y    ____  .____/::\___  .________  Y    _______   ____  ___/: \n. / ¬   \/ ¬  _    \/ ¬  I    \:+:/ ¬  I    \/ ¬  _     /   _¬   \/ ¬   \:+.\n /      /     |    /           >:/          /     |    /    |    /       >::\n \______\_____|    \__________/::\__________\_____|    \_________\______/Rbx\n ~~~~~~~~~~~~~|____/~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~|____/~~~~~~~~~~~~~~~~~~~~~\n\n\n\n           @{" Introduction           " Link Introduction}\n              @{" Requirements            " Link Requirements}\n               @{" Installation             " Link Installation}\n                @{" Changes since V2.10/11    " Link Changes}\n              @{" Bugreports & To do.      " Link Bugreports}\n           @{"  Greetinx               " Link Greetinx}\n\n              |                                           .\n    -    - -- --- ----------------------------------------+·\n              |        THe (M)yth DuTCH HeaDQuaRTeRS!     |           \n            . ____ _____ _____________ __________________ :. .\n           .. \_  Y \_  Y \_  _ \_    Y \_    \____ \_  7__. .    \n           . .:| \ / |__`  |_  \_|  7_|  |  |__|  _  |  |  |:. .\n            .+:|  Y  ( Y   ( \_  (  ( |  (  l  (  l  (  |  (+:\n           . .:l__|__/_____/_____/__/ l__/_____/_____/_____/: .\n           _________________ __________________________________\n           \__________ \_  7_\____ \_    \_ __ \_  _ \________/   \n             \_____| |  |  |  |  _  |  |__|  ___|_  \_______/\n              :\___|  _/|  |  (  |  (  l  (  |  ( \_  (___/ \n              |  \_l__| l_____/_____/_____/_____/_____/_/ :\n              |   ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~  |Rbx\n              `--------------------------------------- ---- -- - -   -\n                                                          | \n\n@EndNode\n\n@Node Introduction "Introduction"\n\n                        THC-CHAT V2.30  (09-11-94)\n\n\nWell... congratulations with this great door. I (Crew One) Started developing\nthis door because there was no real good chatter for multinode boards.\n(I''m still surprised that there is no other multinode/splitscreen chatter \nat this moment.) The final releaseversion, (Verion 2.00... Version 1.00 was an \ninternal release with many bugs.) was finished early in 1994. Since then sysops\nover all the globe start using this chatter. (And now.. maybe you are one of\nthem!) I hope you will use my door with pleasure, and if you find a bug or have\nan idea... dont hesitate to call: MYSTICAL PLACES BBS. (My ''home'' bbs.)\n\n					Crew One /   /X\ \/ T H   /X )-Sign.\n						         /\n\n@EndNode\n\n@Node Requirements "Requirements"\n`\n                     WHAT IS REQUIRED FOR THIS DOOR ?\n\nTo run this door you will need:\n\n	- /X 2.xx or above.\n	- OS 2.00 or above.\n	- 200 Kb free space.\n	- A 68020 processor or above.\n	- An Amiga computer.\n	- Many mony to send to me.\n\n@EndNode\n\n@Node Installation "Installation"\n\n                         HOW TO INSTALL THIS DOOR.\n\nTo run this door properly, the correct files have to be in the correct \ndirectories. The chatter is pre-set to use the "DOORS:THC-CHAT/" directory.\nAll the files must be present in this directory. Please note that you must\ncopy ''THC-CHATTER.LOGFILE'' , ''THC-CHATTER.LASTUSERS'' , ''THC-CHATTER.HISCORES''\nin this directory. (Or the logfile,lastusersrecors & hi-score table will not\nfunction instantly.)\n\n@EndNode\n\n@Node Bugreports "Bugreports & To Do."\n\n                                BUGREPORTS\n\nSend your bugreports / ideas to:\n\n                            MYSTICAL PLACES BBS\n\n[ Node1: +31-104-779-507 (DS 21k6) ][ Node2: R I N G D O W N           ]\n[ Node3: R I N G D O W N           ][ Node4: +31-104-774-218 (DS 21k6) ]\n\n\n\n\n                                   TO DO\n\nFuture ideas for this chatter are:\n	- User-definable settings\n	- Individual hi-scores.\n	- sections. (Especially for Hoffi / QTX)\n	- Improved paging.\n	- .......... (Space 4 rent)\n\n@EndNode\n\n@Node History "HISTORY"\n\n                                  HISTORY\n\nChanges are:\n	- New version number ;-)\n	- Improved ''LOST CARRIER'' support.\n	- Ask join.\n	- Messages implementation. (Still in development.)\n\n\nChanges in V2.11b:\n	- Bugs in remote-quit & join fixed.\n	- Added names in messages.\n	- ''Chatted xxx minutes'' does not reset anymore when joining..etc.\n	- Fixed various bugs & colors.\n	\nChanges in V2.11c:\n	- Hi-Score fields DO scroll now. I wondered why the damn thing\n	  didn''t scroll down, until I realized I never coded a scroll \n	  routine for it !!! ( Pretty stupid eh ! )\n\n\nChanges in V2.30:\n	- Complete re-design in ANSI\n	- Sum bugfixes\n	- Correct LOST-CARRIER support.\n	- Auto quit if user does not type something within 5 mins.\n	- WB-Chat, betatested.. and rejected !! (Sorry.. no wb-chatter!)\n\n\n@EndNode\n\n@Node Greetinx "Greetinx"\n\n             \n             GREETINX GO TO:\n\n\n            ___  \n     /\/\ \/ / / ® \nAll  \  / / / /\   members.\n      \__/ ____/\n\nHoffi.\nKayo.\nVektor.\nEmpire.\nPrice.\nOverlord.\nAnd all others i forgot.\n\n@EndNode\n','\n',char(10)),NULL,'auto-added',22320,5,0,NULL,NULL,'mth_tc23','scan',1780048628);
INSERT INTO door_catalog VALUES('mth_view','MTH-VIEW.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/MTH-VIEW.LHA','View','XIM','View',NULL,'PLL','MTH','______  \\\      |   ___/_____:____ : /      \____\____   __\____________/_:____ /________\     \/_____\  _ /    \___       \',replace('          _ _______ _______     .......\012  ______  \\\      |   ___/_____:____ :\012 /      \____\____   __\____________/_:____\012/________\     \/_____\  _ /    \___       \\012       /________\nK     ///______\./       /\012 (--------------------------------/_______/\012          mYTH! /X )-SIGN pRESENTS:\012   VIEW V1.0 THE ULTIMATE VIEW DOOR BY PLL\012   WILL DISPLAY THE CONTENTS OF *ANY* FILE\012      ONLY LIMITED TO YOUR IMAGINATION\012 (----------------------------------------)\012','\012',char(10)),'View.guide',replace('@DATABASE /X\YTH View V1.0 Documentation\012@REM This is an AmigaGuide® - Document\012@REM Please use Multiview or any similar program to read this documentation\012@REM Otherwise ignore the @-Commands in this text.\012@NODE MAIN "/X\YTH VIEW v1.0 © PLL Developments 1995"\012   .\012   |______________________          ._______.\012   ___________  ______.  /     .____|__     |______._________.\012   \_         \/      |_ ______|     _/  __________|__       |__\012    /         \/       /       |     \   \           /       . /________.\012   /___________\      /________.      \___          /________|          |\012             /_______/    \    |  .____\ /_________/nK       |__________|\012                           \______|\012                                  ·    /________________________________.\012                                                                        |\012\012                                 PRESENTS:\012@{b}\012                          View V1.0 - 06 Mar 1995\012                    Copyright (c) 1995 PLL Developments\012                            All rights reserved\012                           A /X\YTH Release <MTH>\012@{ub}\012\012                            @{"     Contents     " LINK CONTENTS}\012                            @{"   Introduction   " LINK INTRO}\012                            @{"     Features     " LINK FEATURES}\012                            @{"   Requirements   " LINK REQUIRE}\012                            @{"   Installation   " LINK INSTALL}\012                            @{"  Configuration   " LINK CONFIG}\012                            @{"      Usage       " LINK USAGE}\012                            @{" Acknowledgements " LINK GREETS}\012                            @{" Revision History " LINK VERSION}\012\012                            @{"     Releases     " LINK RELEASES}\012                            @{" Mystical Places  " LINK MP}\012@ENDNODE\012\012@NODE CONTENTS "Contents..."\012\012This LHA-archive contains the following files:\012\012Directory ROOT:\012\012View                              Dir\012View.info                         384\012\012Directory ROOT:View\012\012BBS                               Dir\012BBS.info                          384\012\012Directory ROOT:View/BBS\012\012Commands                          Dir\012DOORS                             Dir\012Commands.info                     384\012DOORS.info                        384\012\012Directory ROOT:View/BBS/Commands\012\012BBSCmd                            Dir\012BBSCmd.info                       384\012\012Directory ROOT:View/BBS/Commands/BBSCmd\012\012V.info                            567\012View.info                         567\012\012Directory ROOT:View/BBS/DOORS\012\012View                              Dir\012View.info                         384\012\012Directory ROOT:View/BBS/DOORS/View\012\012LHADIZ                            333\012LZXDIZ                            333\012SHRDIZ                            336\012UserView.txt                     5987\012View                            39252\012View.guide                      24882\012View.info                        2721\012ZIPDIZ                            339\012\012    @{"BACK TO MAIN" link "Main" 0}\012@ENDNODE\012\012@NODE INTRO "Introduction..."\012\012View is a small, fast and no-nonsense replacement door for the built-in ''v''\012command in AmiExpress. Unfortunately, the built-in ''v'' command is only\012capable of reading text files and cannot handle exotic formats such as\012LHA-archives, DMS, ZIP etc. View is a /X door that allows you to view the\012contents of a file in the filelisting and it will identify different\012fileformats. This enables you to check the file before you wish to download.\012It is not only limited to view the contents of an archive, but you can also\012add your own custom filetypes, so you are able to view almost *any* text\012output in AmiExpress. You can even execute AmigaD*S script files for optimal\012configuraton.  This door differs from other view doors, you don''t need to\012have a special version of an archiver to make it function, alternatively, if\012a new archiver comes out, like LZX for example, you can easily add it into\012the filetypes.\012\012    @{"BACK TO MAIN" link "Main" 0}\012@ENDNODE\012\012@NODE FEATURES "Features..."\012\012 · Automagically recognizes EXE/TXT/DOC/NFO files\012\012 · Accepts arguments\012\012 · Hexadecimal view implemented\012\012 · On-line help file\012\012 · Very straightforward and easy to use\012\012 · Works for all conferences/dirs\012\012 · Fully configurable\012\012 · Able to execute AMIGAD*S script files\012\012 · Able to identify foreign filetypes\012\012 · Optionally FILE_ID.DIZ for each filetype\012\012    @{"BACK TO MAIN" link "Main" 0}\012@ENDNODE\012\012@NODE REQUIRE "Requirements..."\012\012View requires OS2.04 (V37) and AmiExprexx V3.xx or higher. If you want to\012make use of LHA, LZX, DMS etc. you need the following programs in your c:\012directory (it depends on your own needs and configuration).\012\012   LHA         - LHA V1.50r by Stefan Boberg\012\012   LZX         - LZX V1.00 by Data Compression Technologies\012\012   DMS         - DMS V1.03/V1.11/V1.51/V1.53/V2.01 by SDS Software\012\012   ZIP         - UnZip V5.1 by S.H. Smith\012\012   ARJ         - UnARJ V1.15 by Harald Schneider\012\012   GUIDE       - GuideToDoc V1.0 by ByteAndi/TRSi\012\012   SHRINK      - SHRINK V1.1 by Matthias Meixner\012\012   FILE_ID.DIZ - DMSDESCRIPT/EXEDESCRIPT/TXTEXTRACT by Remo/MST\012\012and don''t forget the other archivers like ZOOM, TAR, DEX, ARC, ZOO etc...\012\012btw. this is just an example, you don''t need to use the versions of the\012programs above, if you have an older or newer version as described above,\012you can also use it without problems, just keep in mind that older/newer\012versions may have different command line options as used in the default\012configuration supplied in this release.\012\012    @{"BACK TO MAIN" link "Main" 0}\012@ENDNODE\012\012@NODE INSTALL "Installation..."\012\012To install View, just copy ALL files in the View/BBS drawer to your BBS:\012directory (configured in the ACP.info, for example, BBS_LOCATION=BBS:)\012Further you need the logical assignment DOORS: (DOORS: is an assignment to\012your BBS:Doors directory). Alternatively, you can adapt the script files and\012configuration to fit your own needs.\012\012    @{"BACK TO MAIN" link "Main" 0}\012@ENDNODE\012\012@NODE CONFIG "Configuration..."\012\012View is fully configurable, that means that you can edit 85 tooltypes in the\012DOORS:View/View.info icon. 20 filetypes (filetype1 refers to CUSTOM1,\012CHECK1,VIEWID1,ID1) plus the COMEBACK, TEXTID, TEXTCOM, EXEID, EXECOM\012tooltypes. Where (x) is from 1 to 20. Note when using filetypes, almost ANY\012program that generates text can be viewed on screen, just remember to\012redirect the output to RAM:PLLVIEW and the contents will be showed on screen.\012\012                VIEW IS ONLY LIMITED TO YOUR IMAGINATION!!!\012\012\012TOOLTYPES IN BBS:Commands/BBSCmd/v.info and/or BBS:Commands/BBSCmd/View.info\012----------------------------------------------------------------------------\012\012LOCATION=BBS:DOORS/View/View        <<=== Location of the door\012MULTINODE=<YES|NO>                  <<=== Multinode door??\012ACCESS=<num>                        <<=== Min. access to enter the door\012TYPE=XIM                            <<=== View is a XIM door\012STACK=<num>                         <<=== Stack of 4096 is sufficient\012PASSWORD=<string>                   <<=== Password to enter the door\012\012\012TOOLTYPES IN DOORS:VIEW/View.info\012---------------------------------\012\012COMEBACK=<ON/OFF>\012-----------------\012\012This tooltype let you specify whether you want to restart the door after a\012text is displayed on screen, or to quit. This is useful for batch file\012viewing. If you set this tooltype to OFF, the door exits immediately after\012viewing a file in the filelisting.\012\012\012FileTypes for ASCII/ANSI\012========================\012\012TEXTID=<ON/OFF>\012---------------\012\012This tooltype let you specify if you want to view the FILE_ID.DIZ for\012.TXT, .DOC or .NFO files. If you set this tooltype to OFF, the TEXTCOM\012tooltype is ignored and you won''t be bothered with the quesion:\012\012Do you want to view the FILE_ID.DIZ? (Y/n)\012\012You can optionally switch this tooltype, because most people scan the\012filelisting first (which already contains the FILE_ID.DIZ) before viewing\012a file.\012\012\012TEXTCOM=<Command>\012-----------------\012\012This tooltype let you specify the AmigaD*S command for viewing the\012FILE_ID.DIZ. Typically if you use TXTEXTRACT, this tooltype contains:\012\012TEXTCOM=c:TxtExtract e RAM:PLLVIEW\012\012If the TEXTID tooltype is set to OFF, this command will be ignored.\012\012\012FileTypes for Executable files\012==============================\012\012EXEID=<ON/OFF>\012--------------\012\012This tooltype let you specify if you want to view the FILE_ID.DIZ for\012executable files (EXE). If you set this tooltype to OFF, the EXECOM\012tooltype is ignored and you won''t be bothered with the quesion:\012\012Do you want to view the FILE_ID.DIZ? (Y/n)\012\012You can optionally switch this tooltype, because most people scan the\012filelisting first (which already contains the FILE_ID.DIZ) before viewing\012a file.\012\012\012EXECOM=<Command>\012----------------\012\012This tooltype let you specify the AmigaD*S command for viewing the\012FILE_ID.DIZ for executable files which have the suffix .EXE. Typically if\012you use EXEDESCRIPT, this tooltype contains:\012\012EXECOM=c:EXEDescript x RAM:PLLVIEW\012\012If the EXEID tooltype is set to OFF, this command will be ignored.\012\012\012Custom tooltypes\012================\012\012CUSTOM(x)=<Command>\012-------------------\012\012This tooltype let you specify an AmigaD*S command to process a file in the\012filelisting. This could be *ANY* command which generates a text. Note to\012keep in mind that the text file you want to display on screen needs to be\012redirected to RAM:PLLVIEW, for an example just look at the\012DOORS:VIEW/View.info or consult your AmigaD*S manual about how to accomplish\012this.\012\012CHECK(x)=<Extention>\012--------------------\012\012This tooltype let you specify the extention or suffix of the program you\012wish to view from the filelisting. For example the suffix of the program:\012\012FILE.LHA    = LHA\012FILE.GUIDE  = GUIDE\012FILE.LZX    = LZX\012FILE.ABCDEF = ABCDEF or BCDEF or CDEF or DEF or EF\012\012As you can see the suffix can be any text of any length, you can yourself\012determine the suffix of the program for optimal configurability.\012\012\012VIEWID(x)=<ON/OFF>\012------------------\012\012This tooltype let you specify if you want to view the FILE_ID.DIZ for custom\012filetype (x). If you set this tooltype to OFF, the ID(x) tooltype is ignored\012and you won''t be bothered with the quesion:\012\012Do you want to view the FILE_ID.DIZ? (Y/n)\012\012You can optionally switch this tooltype, because most people scan the\012filelisting first (which already contains the FILE_ID.DIZ) before viewing a\012file, and not every filetype supports a FILE_ID.DIZ.\012\012\012ID(x)=<Command>\012---------------\012\012This tooltype let you specify the AmigaD*S command for viewing the\012FILE_ID.DIZ for custom filetype (x) which have the suffix specified in\012CHECK(x). If the VIEWID(x) tooltype is set to OFF, this command will be\012ignored. Since not every filetype supports an executable command for viewing\012the FILE_ID.DIZ you can also write AmigaD*S script files to view the\012FILE_ID.DIZ on screen. An example for ZIP is showed below, if you want to\012adapt it for another program to view the FILE_ID.DIZ, you only have to adapt\012the row:\012\012c:UNZIP -o "{file}" FILE_ID.DIZ -d RAM:\012\012to your own command, say, ARJ for example. If you are doing this be sure to\012read the manual for the program to let it work correctly, and study the\012command line options, alternatively read the chapter about script files in\012your AmigaD*S manual.\012\012\012================================= CUT HERE =================================\012; $VER ZIPDIZ V1.0 26 Feb 1995 PLL\012.key file/a\012.bra {\012.ket }\012\012; For different archivers edit the line below ONLY and customize the icon!\012c:UNZIP -o "{file}" FILE_ID.DIZ -d RAM:\012\012IF NOT EXISTS RAM:FILE_ID.DIZ\012 Echo >RAM:PLLVIEW "This file has no FILE_ID.DIZ"\012 Skip END\012ENDIF\012c:Type >RAM:PLLVIEW RAM:FILE_ID.DIZ\012c:Delete RAM:FILE_ID.DIZ\012END\012================================= CUT HERE =================================\012\012    @{"BACK TO MAIN" link "Main" 0}\012@ENDNODE\012\012@NODE USAGE "Usage..."\012\012By typing ''v'' or ''view'' you can actually launch the door. The following text\012is displayed on screen:\012\012          [»«] wELCOME tO mYTH-vIEW v1.0 © pLL mYTH /X D-sIGN [»«]\012               pRESS eNTER tO qUIT oR tYPE hELP oR ? fOR hELP\012\012Enter filename of file to view? :\012\012Here, you can type *ANY* filename you wish to view, If you select a file\012which isn''t supported in the sysops configuration or if View cannot\012recognize the filetype, an appropriate error message will be generated, and\012it will prompt you with a small menu, which asks you whether you wish to\012text-read the file or hex-dump the file. (If you don''t type any filename,\012and press enter, View will exit abnormally.)\012\012Filetype not found!\012\0121. TextRead file\0122. HexView  file\0123. Quit\012\012Enter your choice? (1/2/3):\012\012View automagically identifies the filetypes TXT/DOC/NFO/EXE and 20\012sysop-definable filetypes, so you will get this menu only if View cannot\012recognize the file, this is probably just an ordinary executable or text\012file. (If you are sure this is a often used filetype, ask the sysop for\012including it in the config file.) Press 1 to read the file as text, 2 to do\012a hexdump or optionally 3 to quit. In hexdump mode, press any key or ''y'' to\012continue the hexdump, or press ''n'' to quit. View detects the LINES PER\012SCREEN option in the user configuration in /X. You can access the user\012configuration with the ''w'' command in the main prompt in /X. So if View\012hasn''t the desired output (short pages), you have to use the ''w'' option\012(LINES PER SCREEN) in the user config in /X.\012\012View also accepts arguments, the command template for View or ''v'' is:\012\012View <filename>\012\012or enter View ? or View HELP for this online help text file.\012\012As soon as you have typed the correct filename, View searches through\012all dirs in the current conference to find the file and displays the\012contents on screen. The output that View generates is dependent of the\012sysop''s configuration, but most likely with a LHA archive it will display\012the filename, size, date and compressionratio. DMS can''t show the files\012in the archive, but can show you other information like creation date\012or low/hightrack in the archive. But there are a zillion file archivers\012with all a different output.\012\012Optionally, after viewing the contents of the text, View asks you to display\012the FILE_ID.DIZ on screen.\012\012Do you want to view the FILE_ID.DIZ? (Y/n)\012\012Press ''y'' or ENTER to view the FILE_ID.DIZ, or press ''n'' to skip. If View\012cannot find the FILE_ID.DIZ in the selected file an appropriate error\012message will be generated. ''This file has no FILE_ID.DIZ''\012\012\012Error Messages\012==============\012\012File does not exist!\012--------------------\012\012The file you selected does not exist, maybe you have typed the wrong\012filename or the sysop has deleted the file from the conference.\012\012Assignments not supported!\012--------------------------\012\012You tried to view a file which is not in the supported conferences.\012\012Filetype not found!\012-------------------\012\012This is probably just an ordinary text file or executable, if you are sure\012this is an often used filetype, ask the SYSOP for including it in the\012configuration.\012\012Unable to open temporary file!\012------------------------------\012\012Due to low memory conditions View cannot access the file RAM:PLLVIEW which\012is used to view the output on screen, or, temporary, due to an occupied\012lock, the file RAM:PLLVIEW cannot be opened.\012\012    @{"BACK TO MAIN" link "Main" 0}\012@ENDNODE\012\012@NODE GREETS "Acknowledgements..."\012\012This door was made on request for EUROSOFT, who uses it to see if an upload\012is a fake (hint).\012\012                gREETINGS tO tHEZE dUDEZ: (iN rANDOM oRDER!)\012\012     nIKE, pINOKIO, t/\RGET, tUS, iNCOGNITO, eMPiRE, nITRATE, bADSECTOR\012   tELEKINETIC, aIRCO, vECTOR, sANTA cLAUS, kYLIX, pINHEAD, bABYFACE, tDB\012 tRIANGLE, hOFFI, rAJ!, mUAD''dIB, tIB, vANGOLEN, mAD mAX, rUBYX, gREENHOUSE\012     mWB, mAGOO, mINDEX, dEXTRON, sCOPE, tORCH, cHOQ, hELLCAT, aNALYZER\012 rEMOTE cONTROL, iCE, dIABLO, cRAZY wH¡TE, UFOk, tHE fLASH, dELITE, vETERAN\012  jAKE, dEATHKNIGHT, sIGH, mSW, oVERLORD, aPOLLO, nIGHTCRAWLER, pROSATANOS\012             sAL-1, sCHWARZENEGGER, tAZ dEVIL, nSC, bLADE, hAWK\012\012\012         gREETINGS tO tHESE /X dOOR dUDEZ: (kEEP uP tHE gOOD wORK)\012\012          TRSi /X Innovation, MST /X Dezign, yODEL, oTT /X dESIGN,\012           WOA - /X - iNSPiRATiON, cALYPSO, /X Development Team.\012\012    @{"BACK TO MAIN" link "Main" 0}\012@ENDNODE\012\012@NODE VERSION "Revision History..."\012\012 V1.0 - 06 Mar 1995\012      - Initial release\012\012If you have any suggestions, bug reports or questions, please contact PLL\012Developments at one of the electronic mail addresses.\012\012When sending in bug reports, please state exactly under what circumstances\012the bug occurred, what equipment was used and what happened. If possible\012also try to give me enough information to reproduce the bug. It is very\012difficult to find bugs when you don''t know exactly what happened. Please\012don''t just send messages like "View doesn''t work", that really doesn''t help\012me. If possible, submit the offending ''error'' to me so I can test it myself,\012or give me a pointer where I can find the error.\012\012    @{"BACK TO MAIN" link "Main" 0}\012@ENDNODE\012\012@NODE RELEASES "Releases..."\012\012MTH-FLH3.LHA                      ______  ______   .___ ____.  _______.\012                                  \_    \/    _/___|   \    |__\____  |\012                                   /    \_/   \    |    \   _______/  |____.\012                                  /      \     \___.    /   \    \    .    |\012                                 /________\     \  |   /______    \___|    |\012                                 ·-----/_________\____/-------\____\nK|____|\012                                 ·                                         ·\012                                 »» pRESENTS: fUCKLHA V3.0 ** bY cREW oNE **\012                                   cAN sTRIPP aLL FILE, oN-LINE & oFF-LINE\012                                  vERSION iNCLUDED. wITH