INSERT INTO door_catalog VALUES('n_ext102','N!EXT102.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/N!EXT102.LHA',NULL,'XIM','LE-win5-96.exe',NULL,'Xad)',NULL,'___ _:__ _____   __:_____________    __ |   \ |__) ___/--/  | ___/___/ \  |__|  |__ |     |  | /  ¡     |  |  _) .  \ !  |  !  |',replace('                              (-fAZ!)\n ___ _:__ _____   __:_____________    __\n|   \ |__) ___/--/  | ___/___/ \  |__|  |__\n|     |  | /  ¡     |  |  _) .  \ !  |  !  |\n`--\__|--´----´--\__|--´--´--l___\---´-----´\n<=====(  n  i  G  h  t  F  A  L  l  ]======>\n    Extractor V1.02 (Registered by Xad)\n       By Roland Szerletics (c) 1995\ntHANX tO: [HaRDsEquEnCer] aT aTLANTIC\n-³³.6]--÷ *SWEDENS DRUNK STATION* ÷--[-³³.6 \n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n     