INSERT INTO door_catalog VALUES('nb_bv1','NB-BV1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NB-BV1.LHA','Arc','XIM','ARJ',NULL,NULL,'NB','|    l  _/  .   _/__)  ____/__\    / |       |   i   |   !__\   |  /   / *BELCH!* |___|   l_______|   |______l_    /',replace(':____._____________:________  ______\n|    l  _/  .   _/__)  ____/__\    / \n|       |   i   |   !__\   |  /   / *BELCH!*\n|___|   l_______|   |______l_    /\n·«--l___|---==l_____|=--=/_______\=-(fAZ!)-»\nBelchView v0.8 -for S!X and possibly /X.info\n  ARC   ARJ   DMS   LHA   LZH   RUN   SFX\n  SHR   TXT   WRP   ZIP   ZOM   ZOO **IFF**\n and of course the files inside the archive\n','\n',char(10)),'BelchView.doc',replace('\n                     BelchView v0.8 by Noisy Belch (S!X)\n______________________________________________________________________________\n:::::::::::::::::::::::::::::::::: Features ::::::::::::::::::::::::::::::::::\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n   Supports ARC ARJ DMS LHA LZH RUN SFX SHR TXT WRP ZIP ZOM ZOO\n   - more than any other ViewDoor I know\n   It also checks the archive and views the inside files\n\n******************************************************************************\n\n   Im not shure but it might also work with /X when you edit the old good\n   BBS:CONF/PATHS files containing the upload dirs heh... icons are lame...\n\n******************************************************************************\n______________________________________________________________________________\n:::::::::::::::::::::::::::::::: Installation ::::::::::::::::::::::::::::::::\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n   Make sure all paths in the belchview.cfg file are right\n\n   --------------------- cut ------------------\n   shr=c:shrink\n   arj=c:arj\n   dms=c:dmscli\n   zom=c:zoomchk\n   wrp=c:warpck\n   lha=lha\n   zip=c:unzip\n   zoo=c:zoo\n   arc=c:arc\n   acc=255\n   --------------