INSERT INTO door_catalog VALUES('nb_olm13','NB-OLM13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NB-OLM13.LHA','BelchOLM','XIM','BelchOLM',NULL,'Noisy','NB','/  \  /    \/  \/  ___/ |  _/BelchOLM v1.3¦ /      \  |  \   \___  \ ''  \by Noisy Belch¦ \__\___/_____/___/_____/____/--------------''',replace('  __ _/\/\__  __  ____/\_._/\_             .\n /  \  /    \/  \/  ___/ |  _/BelchOLM v1.3¦\n/      \  |  \   \___  \ ''  \by Noisy Belch¦\n\__\___/_____/___/_____/____/--------------''\n \n            The Worlds BEST Olm\n \nS!X only - The MEGA LAME /X.info is UNWORTHY\n','\n',char(10)),'BelchOLM.guide',replace('@node main "Main"\n\n\n\n                   __ _/\/\__  __  ____/\_._/\_             .\n                  /  \  /    \/  \/  ___/ |  _/BelchOLM v1.3¦\n                 /      \  |  \   \___  \ ''  \by Noisy Belch¦\n                 \__\___/_____/___/_____/____/--------------''\n\n                              The Worlds BEST Olm\n\n                 S!X only - The MEGA LAME /X.info is UNWORTHY\n\n\n\n                                   @{" Features " link "features"}\n\n                                   @{" History " link "history"}\n\n                                   @{" Install " link "install"}\n\n             @{" The fastest Independent Console Only Board in Europe " link "4Ndz Console Only"}\n\n\n\n@endnode\n@node "Features"\n\n\n   Supports as many nodes as you want\n   OLM can be send ANONYMOUS\n   OLM all nodes at the same time\n   3 lines for your Messages\n   Supports the S!X intern OLM.message.txt routine\n   Faststart with Commandline options... Example: [OLM 1] for node 1\n   (Optional) Instant Reply (even if the sender was anonymous!!!!)\n   The Instant Reply can be generally disabled by the (lame) sysop\n\n   You will love it...\n@endnode\n\n@node "History"\n\n   0.1ß  lame\n   0.2ß  a few improvements and better design\n   0.3ß  added a scale, global and other stuff\n   0.4ß  added the Anonymous function and changed the design a bit\n   0.5ß  cosmetical changes\n   0.6ß  only a few cosmetical changes...\n   0.7ß  total re-written and optimized version\n   0.8ß  Translated from Arexx into C\n   0.9ß  WHO shows now "Using OLM" instead of "Module"\n   1.0   added hotkey at "should i.." question.. public release..\n   1.1   added a new powerful feature... INSTANT REPLY after receiving\n         an message the OLM itself will popup and you can reply automatically\n         or just press CR if you are not interested.. \n\n         EXAMPLE....\n\n         Someone poststs anonymous an OLM to you and you CAN reply.. but still\n         without knowing who he was haha...\n\n         This feature needs new commands in the bbs.cmd file...\n \n         -------------------------------- cut -----------------------------\n	 *olm      XM030doors:olm/olm\n	 *reply0   XM030doors:olm/olm\n	 *reply1   XM030doors:olm/olm\n	 *reply2   XM030doors:olm/olm\n	 *reply3   XM030doors:olm/olm\n	 *reply4   XM030doors:olm/olm\n         -------------------------------- cut -----------------------------\n\n         this is for an 5 nodes board if you have more nodes just add more\n         reply commands with the node number... reply5, reply6, reply7 ...\n   1.2   Instant Reply is now OPTIONAL... you''ll be asked.. \n   1.3   worked a bit on the Insant reply stuff again.. now the sysop can\n         disable it generally by creating or not creating a dummy file called\n\n         DOORS:BelchOLM/NOREPLY\n\n         If BelchOLM find the file the Instant reply mode is deactivated\n\n@endnode\n@node "Install"\n\n         put the olm somewhere and add this to you bbs.cmd\n\n         -------------------------------- cut -----------------------------\n	 *olm      XM030doors:olm/olm\n	 *reply0   XM030doors:olm/olm\n	 *reply1   XM030doors:olm/olm\n	 *reply2   XM030doors:olm/olm\n	 *reply3   XM030doors:olm/olm\n	 *reply4   XM030doors:olm/olm\n         -------------------------------- cut -----------------------------\n\n         this is an example for a 5 nodes board if you have more nodes just\n         add more reply commands with the node number...\n         reply5, reply6, reply7 ...\n\n         Since version 1.3 the Sysop can disable the Instant Reply generally\n         by creating or not creating a dummy file called\n\n         DOORS:BelchOLM/NOREPLY\n\n         If BelchOLM find the file the Instant reply mode is deactivated\n@endnode\n\n@node "4Ndz Console Only"\n\n             The fastest Independent Console Only Board in Europe\n\n                                          \n                               __             __\n                    /\________/ /    .::.:.   \ \________/\\n                    \  .·.      \  .:; `;;:.  /      .·.  /\n                 ___/.o:; _(\    \ :·    `.:./    /)_ ;:o.\___\n                 \_ .:::·(__ \    `::.  .;:;''    / __)·:::. _/\n                   \ ::;    \ \___.:;.   .;:.___/ /    ::: /\n                    \ :::.   \____;:·      ;`____/   .::: /\n                     \ ;:. ·      / o     o \      · .:; /\n                     / ______._.  \___/ \___/  ._,______ \\n                     \/     .     .:\     /:.     .     \/\n                           / ·     '':\   /''`     · \\n                          /.:. .     / · \     . .:.\\n                          \`:;.     / \ / \     .;:''/\n                           \ O:;:; /   Y   \ ;:;:O /\n                           / _·___,\   |   /.___·_ \\n                           \/ Y     `--^--''     Y \/\n                              `                 ''\n                   __ _/\/\__  __  ____/\____/\______/\____/\\n                  /  \  /    \/  \/  ___/  ___/   _   _/ ___/\n                 /      \  |  \   \___  \  _)_|   \   \  _)_\n                 \__\___/_____/___/_____/_____)___/___/_____)nb\n\n                           4 Nodes and Console Only\n\n               USRobotics 16.8 Dual Standart [28.8 coming soon]\n\n                         USRobotics 14.4 Dual Standart\n\n                               2x Euro ISDN 64.0\n\n@next "main"\n@endnode\n','\n',char(10)),NULL,'auto-added',16293,5,0,NULL,NULL,'nb_olm13','scan',1780048634);
