INSERT INTO door_catalog VALUES('nb_sj04','NB-SJ04.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NB-SJ04.LHA','superjoint','XIM',':____._____________:________  ______',NULL,NULL,'NB','|    l  _/  .   _/__)  ____/__\    / |       |   i   |   !__\   |  /   / *BELCH!* |___|   l_______|   |______l_    /',replace(':____._____________:________  ______\n|    l  _/  .   _/__)  ____/__\    / \n|       |   i   |   !__\   |  /   / *BELCH!*\n|___|   l_______|   |______l_    /\n·«--l___|---==l_____|=--=/_______\=-(fAZ!)-»\nSuperJoint v0.4 (S!X) now working w 25 confs\nJoin with < from the first conf  to the last\nor  with  > from the last conf to the  first\n         (Not /X.info Compatible!)\n','\n',char(10)),'superjoint.doc',replace('\n           SuperJoint v0.4 by Noisy Belch (Not /X.info Compatible!)\n______________________________________________________________________________\n:::::::::::::::::::::::::::::::::: Features ::::::::::::::::::::::::::::::::::\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nJoin with > from the last conference into the first\nJoin with < from the first conference into the last\n\nJoin with << from somewhere into the first conference\nJoin with >> from somewhere into the last conference\n\nReJoin a conference with RJ  ... heh\n______________________________________________________________________________\n::::::::::::::::::::::::::::::: How to Install :::::::::::::::::::::::::::::::\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n*>        XM010Doors:SuperJoint/SuperJoint\n*<        XM010Doors:SuperJoint/SuperJoint\n*>>       XM010Doors:SuperJoint/SuperJoint\n*<<       XM010Doors:SuperJoint/SuperJoint\n*RJ       XM010Doors:SuperJoint/SuperJoint\n\nYou must disable NODE* RELATIVE_CONFERENCES but SuperJoint has it inside\n______________________________________________________________________________\n:::::::::::::::::::::::::::::::::: History :::::::::::::::::::::::::::::::::::\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n   0.1ß  lame\n   0.2ß  Different Bugs fixed\n   0.3ß  Translated from Arexx into C\n   0.4   Updated to 25 Conferences support\n______________________________________________________________________________\n::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n                               .\n                               ¡\n                               o\n           [-fAZ!]            _O_ __ __ _ ______________________\n                    _ _ _ ___/__/\                              |\n                  ______     \__\/                      ____    !\n             _____\    /_____ _:_______________________/__ /____O___\n            _\    /   /   _  |   \_   _____/ __   /  ____/__/ __   /_\n          _/_/       /   /   |    /__    /   /___/   /    /   /___/ /\n          \ \__\    /________|   /_/    /_______/   /____/_______/\/\n           \/___\  /_________l__/\/_____\______/___/\____\_______\/\n             . \_\/         l___\/______/      \___\/           :\n             |       .:.+                                       |\n             |__________________________________________________|\n\n                        -[ 4 Nodes and Console ONLY ]-\n\n                           Euro ISDN with Ringdown!\n                           USRobotics with Ringdown\n\n                           -[ Sysop: Noisy Belch ]-\n\n\n','\n',char(10)),NULL,NULL,12504,5,0,NULL,NULL,'nb_sj04_superjoint','scan',1780048634);
