      / o     o \      · .:; /\n                     / ______._.  \___/ \___/  ._,______ \\n                     \/     .     .:\     /:.     .     \/\n                           / ·     '':\   /''`     · \\n                          /.:. .     / · \     . .:.\\n                          \`:;.     / \ / \     .;:''/\n                           \ O:;:; /   Y   \ ;:;:O /\n                           / _·___,\   |   /.___·_ \\n                           \/ Y     `--^--''     Y \/\n                              `                 ''\n                   __ _/\/\__  __  ____/\____/\______/\____/\\n                  /  \  /    \/  \/  ___/  ___/   _   _/ ___/\n                 /      \  |  \   \___  \  _)_|   \   \  _)_\n                 \__\___/_____/___/_____/_____)___/___/_____)nb\n\n                           4 Nodes and Console Only\n\n               USRobotics 16.8 Dual Standart [28.8 coming soon]\n\n                         USRobotics 14.4 Dual Standart\n\n                               2x Euro ISDN 64.0\n\n@next "main"\n@endnode\n','\n',char(10)),NULL,'auto-added',15574,5,0,NULL,NULL,'nb_stats','scan',1780048634);
INSERT INTO door_catalog VALUES('nb_v11','NB-V11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NB-V11.LHA','BelchVIEW','XIM','BelchVIEW',NULL,'Noisy','NB','/  \  /    \/  \/  ___/ |  _/BelchVIEWv1.1¦ /      \  |  \   \___  \ ''  \by Noisy Belch¦ \__\___/_____/___/_____/____/--------------''',replace('  __ _/\/\__  __  ____/\_._/\_             .\n /  \  /    \/  \/  ___/ |  _/BelchVIEWv1.1¦\n/      \  |  \   \___  \ ''  \by Noisy Belch¦\n\__\___/_____/___/_____/____/--------------''\n \n         ARC ARJ DMS LHA LZH LZX RUN\n         SFX SHR TXT WRP ZIP ZOM ZOO\n \nSupports WILDCARDS and Filenames with SPACES\n  Now WITH LZX and WITHOUT the SHUTDOWN BUG\n`----------------------------[27 Mar 1995]---\n','\n',char(10)),'BelchVIEW.guide',replace('@node main "Main"\n\n\n\n                   __ _/\/\__  __  ____/\_._/\_             .\n                  /  \  /    \/  \/  ___/ |  _/BelchVIEWv1.1¦\n                 /      \  |  \   \___  \ ''  \by Noisy Belch¦\n                 \__\___/_____/___/_____/____/--------------''\n \n                          ARC ARJ DMS LHA LZH LZX RUN\n                          SFX SHR TXT WRP ZIP ZOM ZOO\n \n                 Supports WILDCARDS and Filenames with SPACES\n                   Now WITH LZX and WITHOUT the SHUTDOWN BUG\n\n\n\n                                   @{" Features " link "features"}\n\n                                   @{" History " link "history"}\n\n                                   @{" Install " link "install"}\n\n             @{" The fastest Independent Console Only Board in Europe " link "4Ndz Console Only"}\n\n\n\n@endnode\n@node "Features"\n\n   Supports ARC ARJ DMS LHA LZH LZX RUN SFX SHR TXT WRP ZIP ZOM ZOO\n\n   It also views files from inside the archive with SPACES in the Filename\n   MEGA-VIEW does not...\n\n   It was tested on S!X but might also work with /X.info\n\n@endnode\n\n@node "History"\n\n   0.1ß  lame\n   0.2ß  \n   0.3ß  \n   0.4ß  \n   0.5ß  \n   0.6ß  \n   0.7ß  \n   0.8   translated from Arexx to C\n   0.9   Wildcards added\n   1.0   Some small changes\n   1.1   Canged the design a bit and removed the stupid Shutdown bug..\n         also included LZX of course... but i still preffer LHA ehee\n\n         Please add lzx=c:lzx or something to your .config file\n\n@endnode\n@node "Install"..\n\n   Make sure all paths in the DOORS:BelchVIEW/BelchVIEW.config file are ok..\n\n   I doesnt matter in which order you enter them..\n\n   --------------------- cut ------------------\n   shr=c:shrink\n   arj=c:arj\n   dms=c:dmscli\n   zom=c:zoomchk\n   wrp=c:warpck\n   lha=lha\n   zip=c:unzip\n   zoo=c:zoo\n   arc=c:arc\n   acc=255\n   lzx=c:lzx\n   --------------------- cut ------------------\n\n   [acc=] is the account level minimum to view files which are\n          not in the upload dir\n\n   Install it like a XIM door as V and VS in your BBS.CMD\n@endnode\n\n@node "4Ndz Console Only"\n\n\n\n\n\n\n\n\n\n                   __ _/\/\__  __  ____/\____/\______/\____/\\n                  /  \  /    \/  \/  ___/  ___/   _   _/ ___/\n                 /      \  |  \   \___  \  _)_|   \   \  _)_\n                 \__\___/_____/___/_____/_____)___/___/_____)nb\n\n             The fastest Independent Console Only Board in Europe\n\n                        4 Nodes USRobotics and EuroISDN\n\n@next "main"\n@endnode\n','\n',char(10)),NULL,'auto-added',218101,5,0,NULL,NULL,'nb_v11','scan',1780048634);
