INSERT INTO door_catalog VALUES('ne_log10','NE-LOG10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NE-LOG10.LHA','bYEBYE','XIM','LE-win5-96.exe',NULL,'tHE','NE','\   \|    /   ____/  __  /   \|    /------. _/  _ \    \_ ___/__   /  \_ _ \    \_     | \    \ \_   / \    / _/    /  \ \_   /     |',replace(' ____  _______________________  _____       \n \   \|    /   ____/  __  /   \|    /------.\n_/  _ \    \_ ___/__   /  \_ _ \    \_     |\n\    \ \_   / \    / _/    /  \ \_   /     |\n|\___|\    /______/_______/___|\    /      |\n`------\  /---------------------\  /-Rpd!--''\n        \/   P.R.E.S.E.N.T.Z     \/         \n \nnEON lOGOFF v1.0 - ©bY tHE pROPHET/nJOY^nEON\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENC