INSERT INTO door_catalog VALUES('njy_fc10','NJY-FC10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NJY-FC10.LHA','rexxdoor','XIM','rexxdoor',NULL,NULL,'NJY','/ \/ __)) __   (__ (___  (   /__ / _ \  \  /_/\ __/  /  /  /  /  / /___\ __/  \_\//____/_____/\__  /',replace('         _  ___         ___ _____ ____     \n        / \/ __)) __   (__ (___  (   /__   \n       / _ \  \  /_/\ __/  /  /  /  /  /   \n      /___\ __/  \_\//____/_____/\__  /    \n  <-  <- <-\/--------\/{jO-MtS}\_____/-->  \n              N-Joy Presents:              \n      The FileTransfer Chekker v1.00\n[44;33m )X( .DOWNLOADED FROM /\LiEN F/\CTORY!. )X( [0m\n','\n',char(10)),'DOWNLOADMSG.TXT',replace('~\n~CC_DOWNLOAD\n','\n',char(10)),NULL,'auto-added',79726,9,0,NULL,NULL,'njy_fc10','scan',1780048634);
INSERT INTO door_catalog VALUES('njy_nuo1','NJY-NUO1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NJY-NUO1.LHA',NULL,'XIM','.-(10.01.1995)---------------------(23:15)-.',NULL,'C/\NN¡B/\L^NJY^OXY!)------''','NJY','|        _  ___         ______________     | |       / \/ __)) __   (__ (___  (   /__   | |      / _ \  \  /_/\ __/  /  /  /  /  /   |',replace('.-(10.01.1995)---------------------(23:15)-.\n|        _  ___         ______________     |\n|       / \/ __)) __   (__ (___  (   /__   |\n|      / _ \  \  /_/\ __/  /  /  /  /  /   |\n!     /___\ __/  \_\//____/_____/\__  /    !\n¦ <-  <- <-\/--------\/{jO-MtS}\_____/-->  ¦\n¡                                          ¡\n|    N-Joy /X CoDiNG TeaM `95 PReSeNTS:    |\n|       NUO v1.0 - New User Observer       |\n:------------------------------------------:\n| This Tool Keeps You BBS Free From Lamers |\n`------(Coded By C/\NN¡B/\L^NJY^OXY!)------''\n','\n',char(10)),'NUO.GUIDE',replace('@database 0df65ce8-0\n@master NUO.GUIDE\n@remark Created with Heddley v1.0 (c) Edd Dumbill 1994\n\n@node "Main" ""\n  .---------------------------------------------------------------------.\n  |                     NUO v1.0 - NEW USER OBSERVER                    |\n  :---------------------------------------------------------------------:\n  |                      Pleaz State u''re Buisness:      _____          |\n  |            __ ____                 ____ _________ __/    /          |\n  |          ((_((_   \  /\   __      (_   (______   (__    /____       |\n  |               /    \/  \ (__) _____/    /    /    /    /    /       |\n  |             _/   _  \   \    /    /    /    /    /\___     /        |\n  |             \_____\ ____/    \ _______/_________/   ______/         |\n  |      <-  <- <------\/---------\/-------{jO-MtS}/____/-------->      |\n  :---------------------------------------------------------------------:\n  |                       @{"    About NOU v1.0     " link "Document_0" 0}                       |\n  |                       @{"  System Requirements  " link "Document_1" 0}                       |\n  |                       @{"     Installation      " link "Document_2" 0}                       |\n  |                       @{"      ConfigFile       " link "Document_3" 0}                       |\n  |                       @{"      The Future       " link "Document_4" 0}                       |\n  |                       @{"        Greetz         " link "Document_5" 0}                       |\n  :---------------------------------------------------------------------:\n  |           Coded By C/\NN¡B/\L - N-JOY /X CoDiNG tEAM ¹995           |\n  `---------------------------------------------------------------------''\n                  \n@endnode\n\n@node "Document_0" ""\n                                ABOUT NUO v1.0\n                               ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n        »»» THIS PROGRAMM WILL KEEP YOUR BBS FREE FROM LAMERS ! «««\n\n      NUO - NEW USER OBSERVER - IS A PROGRAM THAT CHECKS A USERS CALLS\n      AND UPLOADED BYTES.    IF A USER DID`NT UPLOAD A VARIABEL AMOUNT \n      OF BYTES IN  A VARIABEL AMOUNT OF CALLS,  HE WILL BE SET DOWN TO\n      A USERLEVEL YOU CHOOSE.  \n    \n          I INCLUDED A CONFIGFILE WHICH YOU CAN EDIT TO YOUR NEEDS.\n\n      IN THIS FILE YOU CAN EDIT ...\n \n           · THE NR. OF CALLS BEFORE FIRST WARNING (EG. 10)\n           · THE NR. OF CALLS FOR SETBACK          (EG. 15)\n           · THE AMOUNT OF BYTES TO UPLOAD         (EG. 100000)\n           · 3 AREAS TO SKIP THE TEST              (EG. COSYSOP...)\n           · SETBACK USERAREA                      (EG. VALIDATION)\n           · SETBACK USERLEVEL                     (EG. 10)\n\n      LETS TAKE AN EXAMPLE.\n      A USER LOGS NEW INTO YOUR SYSTEM.  AT HIS FIRST CALL "NUO" WILL\n      INFORM THE USER THAT HE MUST UPLOAD 100000 BYTES IN 15 CALLS,\n      AS YOU`VE EDITED IT IN THE CONFIGFILE. (LOOK AT EG. ABOVE)\n      IF THE USER DONT WANT TO DO AS THE PROGRAMM SAYS HE WILL BE IN-\n      FORMED AT HIS 10`TH CALL THAT HE MUST! UPLOAD THE 100000 BYTES!\n      (THIS IS THE FIRST REAL WARNING).  IF THE USER STILL DON`T WANT\n      TO UPLOAD THOSE FUCKING 100000 BYTES HE WILL BE INFORMED AT HIS\n      14`TH CALL THAT  THIS IS HIS  LAST CHANCE  TO UPLOAD THE  GIVEN\n      AMOUNT OF BYTES.  IF HE DON`T, HE WILL BE SET BACK TO THE GIVEN\n      USERLEVEL AND AREA (WHICH YOU HAVE EDITED IN THE CONFIGFILE!)\n\n      IF YOU DID`NT UNDERSTAND THAT, TAKE  A LOOK AT THE  SCREENSHOTS\n      INCLUDED IN THIS ARCHIVE!\n\n      @{"BACK TO MAIN" link "Main" 0}  \n@endnode\n\n@node "Document_1" ""\n                            SYSTEM REQUIREMENTS\n                           ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n    TO RUN "NUO v1.0" YOU HAVE NEED ...\n\n    · A INSTALLED WORKBENCH 2.01 OR HIGHER\n    · A AMIGA MODEL 500,1000,1200,2000,2500,3000,3000T,4000,4000T\n    · A CORRECTLY INSTALLED VERSION OF /X 3.xx, /X 4.xx or /X 5.xx\n\n    THATS ALL YOU NEED.\n\n    @{"BACK TO MAIN" link "Main" 0}     \n@endnode\n\n@node "Document_2" ""\n                                INSTALLATION\n                               ¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n    · COPY ALL THE FILES IN THIS ARCHIVE TO THE CORRECT DRAWERS.\n    · EDIT THE @{"CONFIGFILE" link "Document_3" 0} TO YOUR NEEDS.\n\n    SORRY, BUT I DON`T KNOW HOW TO INSTALL /X DOORS IN V2.xx OF /X.\n    IF YOU RUN /X 2.xx, YOU MAY KNOW HOW TO INSTALL DOORS ...\n\n    TO RUN THE DOOR, YOU MUST CALL IT VIA. MCI COMMAND.\n    YOU SHOULD PLACE THE DOOR IN THE LOGONxx.TXT, SO EVERY USER MUST\n    PASS THE DOOR.  \n\n    -------CUT HERE--------\n    ~CC_NUO\n    -----------------------\n\n    THATS ALL ... EASY, IS`NT IT ???\n \n    @{"BACK TO MAIN" link "Main" 0}      \n@endnode\n\n@node "Document_3" ""\n                               THE CONFIGFILE\n                               ¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n                          "DOORS:NJOY/NUO/NUO.CFG"\n\n    ALL YOU HAVE TO DO IS TO EDIT THE CONFIGFILE TO YOUR NEEDS:\n\n    EXAMPLE CONFIGFILE:\n    ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n    -------CUT HERE-------\n    10\n    15\n    100000\n    SYSOP\n    COSYSOP\n    NJOY\n    VALIDATION\n    10          \n    ----------------------\n    *------------------------------------------------------------------*\n     LINE 1: AMOUNT OF CALLS BEFORE "REAL" WARNING.\n     ¯¯¯¯¯¯¯     (EG. 10)\n                    THE USER WILL BE INFORMED, THAT HE MUST UPLOAD NOW\n    *------------------------------------------------------------------*\n     LINE 2: AMOUNT OF CALLS TO SET A USER BACK TO CHOOSEN NEWUSERLEVEL.\n     ¯¯¯¯¯¯¯\n                (EG. 15)\n                    THE USER WILL BE SET BACK TO NEWUSERLEVEL AT HIS\n                    15TH CALL\n    *------------------------------------------------------------------*\n     LINE 3: AMOUNT OF BYTES TO UPLOAD\n     ¯¯¯¯¯¯¯\n                (EG. 100000)\n                    THE USER MUST UPLOAD 100000 BYTES IN THE IN LINE\n                    2 GIVEN AMOUNT OF CALLS.\n    *------------------------------------------------------------------*\n\n     LINE 4,5,6: SKIP AREA 1,2 AND 3\n     ¯¯¯¯¯¯¯¯¯¯¯\n                (EG. SYSOP)\n                    ALL USERS WHO HAVE ACCESS TO THOSE AREAS WILL NOT\n                    BE TESTED.\n    *------------------------------------------------------------------*\n     LINE 7: SETBACK AREA\n     ¯¯¯¯¯¯¯\n                (EG. VALIDATION)\n                    THE USER WILL BE SET BACK TO THIS AREA, IF HE DON`T\n                    UPLOAD THE IN LINE 3 GIVEN AMOUNT OF BYTES. \n    *------------------------------------------------------------------*\n    LINE 8: SETBACK LEVEL\n    ¯¯¯¯¯¯¯  \n                (EG. 10)\n                    THE USER WILL BE SET BACK TO THIS USERLEVEL, IF HE\n                    DON`T UPLOAD THE IN LINE 3 GIVEN AMOUNT OF BYTES.\n    *------------------------------------------------------------------*\n\n    AND THAT WAS ALL YOU NEED TO KNOW ABOUT THE CONFIGFILE ... I`VE \n    PLACED A LITTLE HELPTEXT IN THE CONFIGFILE ...\n\n    @{"BACK TO MAIN" link "Main" 0}      \n@endnode\n\n@node "Document_4" ""\n                       RELEASES COMING IN THE FUTURE\n                       ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n    FROM C/\NN¡B/\L\n    ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n    · WUS V1.0   "W" COMMAND REPLACEMENT ... NOTHING TO SAY ABOUT THAT!\n    · NUO V1.1   ADDED SPECIAL USER SKIP ...\n\n    FROM [SATAN+GOD]\n    ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n    · NEW VERSION OF ANSI-FORZE\n\n    @{"BACK TO MAIN" link "Main" 0}  \n@endnode\n\n@node "Document_5" ""\n    SOME GREETINGS TO THE FOLLOWING DUDES ...\n\n    [SATAN+GOD]^NJY -    BUST IS`NT CEWL, IS`NT IT ???\n    PICARD^SHT^PHN  -    CAN I HELP YOU ???\n    STARTFOX^OXY    -    CALL DUDE !!!\n    \n    ALL N-JOY AAND OXYRON MEMBERS\n    AND TO ALL USERS OF MY BBS ...\n \n    @{"BACK TO MAIN" link "Main" 0}  \n@endnode\n\n','\n',char(10)),NULL,NULL,22224,5,0,NULL,NULL,NULL,'scan',1780048634);
