INSERT INTO door_catalog VALUES('njy_ts10','NJY-TS10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NJY-TS10.LHA','rexxdoor','XIM','rexxdoor',NULL,NULL,'NJY','/ \/ __)) __   (__ (___  (   /__ / _ \  \  /_/\ __/  /  /  /  /  / /___\ __/  \_\//____/_____/\__  /',replace('         _  ___         ___ _____ ____     \n        / \/ __)) __   (__ (___  (   /__   \n       / _ \  \  /_/\ __/  /  /  /  /  /   \n      /___\ __/  \_\//____/_____/\__  /    \n  <-  <- <-\/--------\/{jO-MtS}\_____/-->  \n              N-Joy Presents:              \n        The Userstatus Door v1.00\n[33m[-[-> U know where diz Warez come from <-]-][0m\n','\n',char(10)),'The_Userstatus.doc',replace('  .---------------------------------------------------------------------.\n  |        The Userstatus v1.00 - Coded by The Prophet of N-Joy         |\n  :---------------------------------------------------------------------:\n  |                      Pleaz State u''re Buisness:      _____          |\n  |            __ ____                 ____ _________ __/    /          |\n  |          ((_((_   \  /\   __      (_   (______   (__    /____       |\n  |               /    \/  \ (__) _____/    /    /    /    /    /       |\n  |             _/   _  \   \    /    /    /    /    /\___     /        |\n  |             \_____\ ____/    \ _______/_________/   ______/         |\n  |      <-  <- <------\/---------\/-------{jO-MtS}/____/-------->      |\n  :---------------------------------------------------------------------:\n  | to go where no one has gone before...! The journey will never end ! |\n  `---------------------------------------------------------------------''\n\n           <*> One of the best Status Door for /X u ever see <*>\n            <*> The Userstatus v1.00  © 1994 by The Prophet <*>\n                       All rights Reserved Worldwide!\n\n     Trademarks\n\n     Commodore is a registered trademark of Commodore Electronics.\n\n         AmiExpress is a registered trademark of Joseph Hodge!.\n\n\n     System Requirements\n\n     Pager requires an Amiga 500, 600, 1000, 1200, 2000, 3000, 3000T,\n     4000 with at least 512K of ram!\n\n             Filetransfer Chekker requires an /X 3.xx - 4.xx\n     \n     Installation:\n\n     Installing the door is very simple!\n\n     Installing to AmiExpress v3.xx - v4.xx\n     --------------------------------------\n     \nCopy all files which are in the ''Libs'' and ''BBS'' directory of the archive\ninto your libs and bbs directory.\n\nContents of archive:\n===================\n\nLibs/                       AEDoor.library\n                            Rexxsupport.library\n\nBBS/ Commands/ BBSCmd/      S.info      ( for Status.Rexx )\n     Doors/    Status/      Status.Rexx ( Default )\n                            Status_2.Rexx\n                            Status_3.Rexx\n                            ACP.info    ( for Status.Rexx )\n                            ACP_2.info  ( for Status_2.Rexx )\n                            ACP_3.info  ( for Status_3.Rexx )\n                            This Documentation\n     Utils/                 Rexxdoor\n                            Rexxport\n\n     Sorry for this short Description, but the work cry!  ;((\n     \n     \n     Alien Factory\n     N-Joy World Hq - Neon Distributor Side - Akira German Hq\n     24/24 Online\n     ++49-Ask-The-Elite\n     Sysop : The Prophet\n\n     \n     Releases:\n     \n     Logoff Door ( in progress )\n     Filetransfer Chekk ( in progress ) - finished\n     New Files\n     Zippy Search\n     Status Door ( in progress )        - finished\n     FileDescription\n     Who Door\n     Fair Trader\n     Operator Pager\n     Comment Door with Full Screen Editor\n     Lha/Lzh, Dms, Exe, Zip, Txt Chekker\n     Dupe Chekk\n     \n     and many many more :))\n     \n\n\n     Thanks goes to :\n     \n     jOKER/MtS      : for his Great Ansi''s and Azkii''s and help working\n                      in Arexx ;))\n     Joseph Hodge   : for developing this cool AmiExpress =8-))\n\n                      and a big and bigger thanx to some mythos members,\n                      for joining now my Group!\n     \n     Greetings goes to :\n     \n     All Members of : N-Joy, Akira and Neon\n     Murdoc         : Wo bleiben sie denn ? hehe\n     Delta-X        : Thanx for few weeks of a Sysop Axxess ;)\n     jOKER/MtS      : Bust Suxx - Und schon was gehoert von den\n                      Werder Fans ?? ;((\n     Rainman        : Thanx for supporting my BBS\n     Flashlight     : /T\ Tempest suxx - /X roolz .. hehehehe\n     Grandmaster    : Cool pics dude! - Make much more .. hahaha\n     Sargor         : Hope u are online soon again\n     ByteAndi/TRSi  : Bytekiller v2.0 - The best faker i ever saw!\n\n                      and all others i have been forgotten !!!\n\n\n\n   Joining N-Joy:\n     \n   We are always searching for new Members, Coders ( any language ), Trader,\n        cool Sysops, Crackers, Game-Trainers, Supplier. Interested ???\n\n    Call these Boards now, and drop a Message to The Prophet or Hooligan!\n\n- Country -------- Board Name ------ Board Numba ----- Write to -----------\n\n  Germany          Heavens Gate      ++49-Elite-Knows  Hooligan\n  Germany          Black Zone        ++49-Elite-Knows  Hooligan\n> Germany          Alien Factory     ++49-Elite-Knows  The Prophet <\n  Germany          Teutonic Place    ++49-Elite-Knows  The Prophet\n  Germany          Pirates Gold      ++49-Elite-Knows  The Prophet\n  Germany          Desert Strike     ++49-Elite-Knows  The Prophet\n  Germany          Broken Hope       ++49-Elite-Knows  The Prophet\n  Germany          Wild Boyz Home    ++49-Elite-Knows  The Prophet\n  Germany          Top In            ++49-Elite-Knows  The Prophet\n  Germany          Off Limits        ++49-Elite-Knows  The Prophet\n  \n---------------------------------------------------------------------------\n\n           > For the quickest answers call Alien Factory <\n           \n\n                     [-----[-[ The End ]-]-----]\n                     \n','\n',char(10)),NULL,'auto-added',32467,1,0,NULL,NULL,'njy_ts10','scan',1780048634);
