                OFF LIMITS             +49 ASK ELITE!\n                 AKIRA KEY              +49 ASK ELITE!\n                 THE PUB                +49 ASK ELITE!\n                 EUROPES CHAOS          +49 ASK ELITE!\n \n      It`s getting late ... Good Night!\n','\n',char(10)),NULL,'auto-added',15823,2,0,NULL,NULL,'njy_x','scan',1780048634);
INSERT INTO door_catalog VALUES('nmess1c','NMESS1C.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NMESS1C.LHA','nmess','XIM','+------------------------------------------+',NULL,'Compy!:',NULL,'| New doors by Compy!:                     | | ~~~~~~~~~~~~~~~~~~~~                     | | Nmess      0.1c - Next user message door |',replace('+------------------------------------------+\n| New doors by Compy!:                     |\n| ~~~~~~~~~~~~~~~~~~~~                     |\n| Nmess      0.1c - Next user message door |\n+------------------------------------------+\n<<<<------------[ MEN-TEL BBS ]--------->>>>\n','\n',char(10)),'Analsex.txt',replace('                MS-DOS - AMIGA - CD32 Stuff only 0-1 DAY\n            ___________________ __________   ___.   ________\n            \_     /  _______  \\_____    \ /   |   \______ \[JZ]\n             /    /   \/   !/   \/   /_____\    !___ /  !/   \\n            /    /\    \   |     \   _    \_    /   \_ _/     \_        \n            \__________/_________/___/_____/_________/_________/        \n                 ____                                                   \n            ____/   T___________________  ________  ___________         \n           /     __________    ________ \ \______ \ \__ ______/         \n          /______\  T /   /_____\   !/   \ /  !/   \ /  ___)__          \n             /      |/    _    \_   _     \  _/     \_  \     \_        \n            /_______|\____/_____/___T______\_________/_________/        \n                                            ____                        \n      __________ ____________________  ____/   T____________________    \n      \______   \\__ ______________  \/     _______ ____________    \   \n       /    /____\/  ___)__ /   \L   /______\  T /  ___)__ /   /_____\  \n      /     \    \_  \     \_    /   /  /      |/   \     \_   _    \_  \n      \___________/_________/___/___/  /_______|\__________/___/_____/  \n                                                                        \n               S- H- |- N- |- N- G- 8-    W- 0- R- L- D- H- Q-          \n       4 Nodes & ISDN                            1st Operator - cHAOS                     \n              soon 7 Nodes, 3 Gig, Cyberstorm 68060, Vfast      \n','\n',char(10)),NULL,NULL,22076,13,0,NULL,NULL,'nmess1c','scan',1780048634);
INSERT INTO door_catalog VALUES('nmr_axg','NMR_AXG.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NMR_AXG.LHA',NULL,'XIM','__    _____BnS /\ NtF_______',NULL,NULL,'NMR','----/  \--/  /  \--/  \--/  /    \---------- /    \/  /    \/    \/  /   > /The Bloody /  /\    /  /\    /\    /  /\  \  Nimrod',replace('     __    _____BnS /\ NtF_______\n----/  \--/  /  \--/  \--/  /    \----------\n   /    \/  /    \/    \/  /   > /The Bloody\n  /  /\    /  /\    /\    /  /\  \  Nimrod\n-/  /--\  /  /--\  /--\  /  /-/  /----------\n \_/    \/\_/    \/    \/\_/  \_/  Presents\n------ THe LaMeR GuiDe To aMi-eXPReSS ------\n--- QuiCK SeTuPS FoR THe BeGiNNiNG SySoP ---\n','\n',char(10)),'acs.guide',replace('@database "ae"\n\n\nCopyright (c) 1992 Light Speed Technologies, Radford, VA\nAll Rights Reserved\n\n@master "acs.guide"\n\n@Remark $VER: acs.guide 1.00 (18.12.92)\n@Remark AmigaGuide database for the /X ACS ToolTypes\n\n@Node Main "acs.guide"\n@{" ACS.ACCOUNT_EDITING        " Link "ACS.ACCOUNT_EDITING"}\n@{" ACS.COMMENT_TO_SYSOP       " Link "ACS.COMMENT_TO_SYSOP"}\n@{" ACS.DOWNLOAD               " Link "ACS.DOWNLOAD"}\n@{" ACS.ENTER_MESSAGE          " Link "ACS.ENTER_MESSAGE"}\n@{" ACS.FILE_LISTINGS          " Link "ACS.FILE_LISTINGS"}\n@{" ACS.JOIN_CONFERENCE        " Link "ACS.JOIN_CONFERENCE"}\n@{" ACS.NEW_FILES_SINCE        " Link "ACS.NEW_FILES_SINCE"}\n@{" ACS.PAGE_SYSOP             " Link "ACS.PAGE_SYSOP"}\n@{" ACS.READ_MESSAGE           " Link "ACS.READ_MESSAGE"}\n@{" ACS.DISPLAY_USER_STATS     " Link "ACS.DISPLAY_USER_STATS"}\n@{" ACS.UPLOAD                 " Link "ACS.UPLOAD"}\n@{" ACS.VIEW_A_FILE            " Link "ACS.VIEW_A_FILE"}\n@{" ACS.EDIT_USER_INFO         " Link "ACS.EDIT_USER_INFO"}\n@{" ACS.REMOTE_SHELL           " Link "ACS.REMOTE_SHELL"}\n@{" ACS.ZIPPY_TEXT_SEARCH      " Link "ACS.ZIPPY_TEXT_SEARCH"}\n@{" ACS.OVERIDE_CHAT           " Link "ACS.OVERIDE_CHAT"}\n@{" ACS.EDIT_USER_NAME         " Link "ACS.EDIT_USER_NAME"}\n@{" ACS.EDIT_USER_LOCATION     " Link "ACS.EDIT_USER_LOCATION"}\n@{" ACS.EDIT_PHONE_NUMBER      " Link "ACS.EDIT_PHONE_NUMBER"}\n@{" ACS.EDIT_PASSWORD          " Link "ACS.EDIT_PASSWORD"}\n@{" ACS.SYSOP_READ             " Link "ACS.SYSOP_READ"}\n@{" ACS.EALL_MESSAGES          " Link "ACS.EALL_MESSAGES"}\n@{" ACS.DUPE_FILECHECK         " Link "ACS.DUPE_FILECHECK"}\n@{" ACS.READ_BULLETINS         " Link "ACS.READ_BULLETINS"}\n@{" ACS.SYSOP_DOWNLOAD         " Link "ACS.SYSOP_DOWNLOAD"}\n@{" ACS.SYSOP_VIEW             " Link "ACS.SYSOP_VIEW"}\n@{" ACS.SYSOP_READ             " Link "ACS.SYSOP_READ"}\n@{" ACS.FREE_RESUMING          " Link "ACS.FREE_RESUMING"}\n@{" ACS.MESSAGE_EDIT           " Link "ACS.MESSAGE_EDIT"}\n@{" ACS.LIST_NODES             " Link "ACS.LIST_NODES"}\n@{" ACS.DELETE_MESSAGE         " Link "ACS.DELETE_MESSAGE"}\n@{" ACS.ATTACH_FILES           " Link "ACS.ATTACH_FILES"}\n@{" ACS.ZOOM_MAIL              " Link "ACS.ZOOM_MAIL"}\n@{" ACS.MCI_MESSAGE            " Link "ACS.MCI_MESSAGE"}\n@{" ACS.EDIT_DIRS              " Link "ACS.EDIT_DIRS"}\n@{" ACS.BREAK_CHAT             " Link "ACS.BREAK_CHAT"}\n@{" ACS.SYSOP_COMMANDS         " Link "ACS.SYSOP_COMMANDS"}\n@{" ACS.WHO_IS_ONLINE          " Link "ACS.WHO_IS_ONLINE"}\n@{" ACS.QUIET_NODE             " Link "ACS.QUIET_NODE"}\n@{" ACS.EDIT_FILES             " Link "ACS.EDIT_FILES"}\n@{" ACS.OVERRIDE_TIMES         " Link "ACS.OVERRIDE_TIMES"}\n@{" ACS.RELOGON                " Link "ACS.RELOGON"}\n@{" ACS.ULSTATS                " Link "ACS.ULSTATS"}\n@{" ACS.XPR_RECEIVE            " Link "ACS.XPR_RECEIVE"}\n@{" ACS.XPR_SEND               " Link "ACS.XPR_SEND"}\n@{" ACS.CONFERENCE_ACCOUNTING  " Link "ACS.CONFERENCE_ACCOUNTING"}\n@{" ACS.SYSOP_COMMANDS         " Link "ACS.SYSOP_COMMANDS"}\n@{" ACS.PRI_MSGFILES           " Link "ACS.PRI_MSGFILES"}\n@{" ACS.PUB_MSGFILES           " Link "ACS.PUB_MSGFILES"}\n@{" ACS.MAX_PAGES              " Link "ACS.MAX_PAGES"}\n@EndNode\n\n@Node "ACS.ACCOUNT_EDITING"\nACS.ACCOUNT_EDITING\n\n         -Version 3.0\n         -OPTIONAL\n         -ToolType for { Access.info or ACS.info icons }\n\nDescription\n\n   This tooltype will grant account editing to a user.\n@EndNode\n\n@Node "ACS.COMMENT_TO_SYSOP"\nACS.COMMENT_TO_SYSOP\n\n         -Version 3.0\n         -OPTIONAL\n         -ToolType for { Access.info or ACS.info icons }\n\nDescription\n\n   This tooltype will allow a user to leave a comment directly to the sysop\n   via the msgbase editor.\n@EndNode\n\n@Node "ACS.DOWNLOAD"\nACS.DOWNLOAD\n\n         -Version 3.0\n         -OPTIONAL\n         -ToolType for { Access.info or ACS.info icons }\n\nDescription\n\n   This tooltype will allow a user to download files from your BBS.\n@EndNode\n\n@Node "ACS.ENTER_MESSAGE"\nACS.ENTER_MESSAGE\n\n         -Version 3.0\n         -OPTIONAL\n         -ToolType for { Access.info or ACS.info icons }\n\nDescription\n\n   This tooltype will allow a user to enter a message via the message base\n   editor.\n@EndNode\n\n@Node "ACS.FILE_LISTINGS"\nACS.FILE_LISTINGS\n\n         -Version 3.0\n         -OPTIONAL\n         -ToolType for { Access.info or ACS.info icons }\n\nDescription\n\n   This tooltype will allow a user to view file catalogs that are in a \n   conference.\n@EndNode\n\n@Node "ACS.JOIN_CONFERENCE"\nACS.JOIN_CONFERENCE\n\n         -Version 3.0\n         -OPTIONAL\n         -ToolType for { Access.info or ACS.info icons }\n\nDescription\n\n   This tooltype will allow a user to join different conferences on the BBS.\n@EndNode\n\n@Node "ACS.NEW_FILES_SINCE"\nACS.NEW_FILES_SINCE\n\n         -Version 3.0\n         -OPTIONAL\n         -ToolType for { Access.info or ACS.info icons }\n\nDescription\n\n   This tooltype will allow a user to view a list of files that were \n   uploaded to the BBS since the last time the user was on the system.\n@EndNode\n\n@Node "ACS.PAGE_SYSOP"\nACS.PAGE_SYSOP\n\n         -Version 3.0\n         -OPTIONAL\n         -ToolType for { Access.info or ACS.info icons }\n\nDescription\n\n   This tooltype allows the user to request a chat with the sysop.\n@EndNode\n\n@Node "ACS.READ_MESSAGE"\nACS.READ_MESSAGE\n\n         -Version 3.0\n         -OPTIONAL\n         -ToolType for { Access.info or ACS.info icons }\n\nDescription\n\n   This tooltype allows the user to Read Messages.\n@EndNode\n\n@Node "ACS.DISPLAY_USER_STATS"\nACS.DISPLAY_USER_STATS\n\n         -Version 3.0\n         -OPTIONAL\n         -ToolType for { Access.info or ACS.info icons }\n\nDescription\n\n   This tooltype allows a user to view his/her statistics via the ''S''\n   menu prompt command.\n@EndNode\n\n@Node "ACS.UPLOAD"\nACS.UPLOAD\n\n         -Version 3.0\n         -OPTIONAL\n         -ToolType for { Access.info or ACS.info icons }\n\nDescription\n\n   This tooltype allows a user to upload files to your BBS.\n@EndNode\n\n@Node "ACS.VIEW_A_FILE"\nACS.VIEW_A_FILE\n\n         -Version 3.0\n         -OPTIONAL\n         -ToolType for { Access.info or ACS.info icons }\n\nDescription\n\n   This tooltype will allow a user to view ASCII files that are available\n   for downloading on the system.\n@EndNode\n\n@Node "ACS.EDIT_USER_INFO"\nACS.EDIT_USER_INFO\n\n         -Version 3.0\n         -OPTIONAL\n         -ToolType for { Access.info or ACS.info icons }\n\nDescription\n\n   This tooltype will give the user access to the User Account Editing\n   menu. This menu allows the user to change specific indicitive data\n   concerning his/her account.\n@EndNode\n\n@Node "ACS.REMOTE_SHELL"\nACS.REMOTE_SHELL\n\n         -Version 3.0\n         -OPTIONAL|RESERVED\n         -ToolType for { Access.info or ACS.info icons }\n\nDescription\n\n   This tooltype allows a user to enter a AmigaDos SHELL. \n\n   This tooltype currently is not recognized by /X, but future releases\n   may use it.\n@EndNode\n\n@Node "ACS.ZIPPY_TEXT_SEARCH"\nACS.ZIPPY_TEXT_SEARCH\n\n         -Version 3.0\n         -OPTIONAL\n         -ToolType for { Access.info or ACS.info icons }\n\nDescription\n\n   This tooltype will allow a user to use the search features of /X to locate\n   files available for downloading based on some keywords that the user \n   supplies.\n@EndNode\n\n@Node "ACS.OVERIDE_CHAT"\nACS.OVERIDE_CHAT\n\n         -Version 3.0\n         -OPTIONAL\n         -ToolType for { Access.info or ACS.info icons }\n\nDescription\n\n   This tooltype allows a user page the sysop regardless of the state of the\n   sysop page flag.\n@EndNode\n\n@Node "ACS.EDIT_USER_NAME"\nACS.EDIT_USER_NAME\n\n         -Version 3.0\n         -OPTIONAL\n         -ToolType for { Access.info or ACS.info icons }\n\nDescription\n\n   This tooltype allows the user to changes his/her handle on the BBS via\n   the User Account Editor.\n@EndNode\n\n@Node "ACS.EDIT_USER_LOCATION"\nACS.EDIT_USER_LOCATION\n\n         -Version 3.0\n         -OPTIONAL\n         -ToolType for { Access.info or ACS.info icons }\n\nDescription\n\n   This tooltype allows the user to change his/her LOCATION on the BBS via\n   the User Account Editor.\n@EndNode\n\n@Node "ACS.EDIT_PHONE_NUMBER"\nACS.EDIT_PHONE_NUMBER\n\n         -Version 3.0\n         -OPTIONAL\n         -ToolType for { Access.info or ACS.info icons }\n\nDescription\n\n   This tooltype allows the user to change his/her PHONENUMBER on the BBS\n   via the User Account Editor.\n@EndNode\n\n@Node "ACS.EDIT_PASSWORD"\nACS.EDIT_PASSWORD\n\n         -Version 3.0\n         -OPTIONAL\n         -ToolType for { Access.info or ACS.info icons }\n\nDescription\n\n   This tooltype will allow a user to change his/her PASSWORD on the BBS\n   via the User Account Editor.\n@EndNode\n\n@Node "ACS.OVERIDE_TIMES"\nACS.OVERIDE_TIMES\n\n         -Version 3.0\n         -OPTIONAL\n         -ToolType for { Access.info or ACS.info icons }\n\nDescription\n\n   This tooltype allows a user to bypass any time restrictions placed on the\n   connect rate.\n@EndNode\n\n@Node "ACS.SYSOP_READ"\nACS.SYSOP_READ\n\n         -Version 3.0\n         -OPTIONAL\n         -ToolType for { Access.info or ACS.info icons }\n\nDescription\n\n   This tooltype will allow a user to read all mail on the system. This\n   includes mail that normally would not have been addressed to him/her.\n@EndNode\n\n@Node "ACS.EALL_MESSAGES"\nACS.EALL_MESSAGES\n\n         -Version 3.0\n         -OPTIONAL\n         -ToolType for { Access.info or ACS.info icons }\n\nDescription\n\n   This tooltype allows a user to enter messages that will alert all\n   USERS when they first logon during the message base mail scan.\n@EndNode\n','\n',char(10)),NULL,NULL,104824,12,0,NULL,NULL,NULL,'scan',1780048643);
INSERT INTO door_catalog VALUES('no_l24','NO-L24.LZH','~/Code/amiexpress_doors/Archives/AmiExpress/NO-L24.LZH',NULL,'XIM','.------------------------------------------.',NULL,NULL,'NO','|NEW    ____________   ____________  BRINGS| |ORDER  \    \      \  \           \    YOU| |       /     \     /\ /    \      /\      |',replace(replace('.------------------------------------------.\r\n|NEW    ____________   ____________  BRINGS|\r\n|ORDER  \    \      \  \           \    YOU|\r\n|       /     \     /\ /    \      /\      |\r\n- - ---/    \      /--/     /     /-/ -- ---\r\n - - -/______\____/--/___________/-/- - - --\r\n|     \_______\___\/ \___________\/<md>    |\r\n|------------------------------------------|\r\n| LAST24HRS UPLOADS BOTH AMI/X & SYSTEM/X  |\r\n`------------------------------------------''\r\n','\r',char(13)),'\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 20:18:42  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,NULL,59778,3,0,NULL,NULL,NULL,'scan',1780048643);
INSERT INTO door_catalog VALUES('noc_af10','NOC-AF10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NOC-AF10.LHA',NULL,'XIM','AutoFree',NULL,'nocTurne','NOC',': \_____ \/  \/ __/ __/ /  \/  \/ ____/ :___ / / / / / / / / / / / / / / __/  · \  // / / / / / / / / / /\/ / / / //\ :',replace('  · _______  __  ____________  __  ______   \n  : \_____ \/  \/ __/ __/ /  \/  \/ ____/   \n  :___ / / / / / / / / / / / / / / __/  ·   \n  \  // / / / / / / / / / /\/ / / / //\ :   \n  |\/ \/\/\__/\__/\/\__/\/  \/\/\__//__\¦   \n  `=----------------------[ design ]---=''   \n        ·-= /X noC-AutoFree V1.0 =-·        \n  .=-----------------------------------=.   \n  | Automatically makes  uploaded files |   \n  ¦   with certain prefixes FREE DL''s   ¦   \n  :   By nocTurne deSign/MST in 1994    :   \n','\n',char(10)),'AutoFree.doc',replace('   __ ____________________________________  :\n   \//____/\__________  ________/\__  ___/d ¦\n    ____ /  \__ \/ __/ / / /   /  \/ __/¦ e |  noC-AutoFree Version 1.00\n    \  // / / / / / / / / / / / / / / / | s |  ©1994 nocTurne deSign/MST\n     \// / / / / / / / / / /\/ / / / /  | i l____________________ __ _\n   /\ / / /\  /\  / /\  / / / / /\  //\ | g  \n   noC\/\/  \/  \/\/  \/\/  \/\/  \//__\| n    Automatic Free-Download Util\n    _ __ _______________________________j    __________________________ __ _\n   |                                        ¦\n   |                                        l______________________________\n   |                                                                       |\n   |                                                    O V E R - V I E W  |\n   l_ __ __________________________________________________________________j\n\n   Say  you  are  a  THrobbing-Grissle  WHQ.    All  THG  releases are to be\n   free-downloads  on  your board, but it gets a bit tedious having to use a\n   FreeDL-maker  utility  every  time one gets uploaded.  (THG is a prolific\n   group, you see.)  You then decide to use noC-AutoFree and configure it to\n   watch for uploads with the prefix ''THG-'' and automatically make them free\n   to download.  Life is then MUCH more enjoyable at the THG WHQ.\n\n    _ __ __________________________________________________________________\n                                                                           |\n                                                  I N S T A L L A T I O N  ¦\n            _ __ __________________________________________________________j\n\n   To  install  noC-AutoFree, first copy the main program, "AutoFree" to your\n   "C:"  directory.  You must have the ReqTools library installed in ''LIBS:''.\n   Next  you  must  create  a  configuration  file,  "S:AutoFree.config".   A\n   template  has  been  included in the package.  AutoFree can be run up to 9\n   times, with separate configurations.  The ''.x'' after each config parameter\n   should  be  replaced  with  the  configuration  number  you  are defining.\n   Following are the options you may set:\n\n   CONFPATH.x:\n   Use this to set the path of the conference you want AutoFree to be active\n   in.       This    parameter    is    REQUIRED    to    be set.  (Example:\n   ''CONFPATH.1=BBS:elite/'')\n\n   FILEPREFIX.x:\n   Files  uploaded  with the filename-prefix defined here will automatically\n   become  free downloads.  This parameter is REQUIRED to be set.  (Example:\n   ''FILEPREFIX.1=THG-''  ...   meaning if a file ''THG-FOO.lha'' is uploaded it\n   will become free, while ''THGENER.lha'' will not.)\n\n   FREEDLTEXT.x:\n   You  may  set the text appended to file descriptions of files meeting the\n   above  FILEPREFIX.    This will automatically be indented 35 characters.\n   ANSI  codes  may  be  used.  This is not a required parameter.  (Example:\n   ''FREEDLTEXT.1=>>> FrEe DoWnLoAd!!!'')\n\n   UPLOADPATH.x:\n   If  the conference''s upload path is not simply CONFNAME + ''upload/'', you\n   must define the path here. (Example: ''UPLOADPATH.1=UL:'')\n\n    _ __ __________________________________________________________________\n                                                                           |\n                                                                U S A G E  |\n            _ __ __________________________________________________________j\n\n\n   It  is suggested that you run AutoFree from your startup-sequence so that\n   it  will  be  in  memory  after a reboot.  Following are some examples of\n   usage.\n\n             ''AUTOFREE 2''   - Run autofree with configuration #2.\n             ''AUTOFREE 2 K'' - Terminate autofree config''ed #2.\n\n   If  you  have  several conferences you want this utility to be active in,\n   simply  run  AutoFree  as  many times  as  needed with different configs.\n   AutoFree  installs  itself  in the background as a ready-waiting process,\n   (IE  no  CPU time is used until it actually does some work), and detaches\n   itself from the CLI process.\n\n   AutoFree  is  NOT  a  door.   It is a resident task, (or tasks if you use\n   multiple  configs),  which  watches   for   uploads   in   the designated\n   conference.    When  an   upload   having   the   prefix   defined in the\n   configuration  is  detected,  the FREEDLTEXT will be appended to the file\n   description  and  the  file will be made free for downloading.  When this\n   occurs the screen will flash and AutoFree will go back to sleep.  Reques-\n   ters will notify you of any problems.\n\n    _ __ __________________________________________________________________\n                                                                           |\n                                                            C R E D I T S  |\n            _ __ __________________________________________________________j\n\n   noC-AutoFree  is  created  by  nocTurne  deSign  in  1994.  Any questions\n   regarding  the  use  of  this  program should be addressed to nocTurne on\n   Sarcophagus BBS (+1.503.548.0532) or any other board you see me on.\n\n   * This utility is BACKDOOR and VIRUS FREE.  All nocTurne deSign products\n     are created with a dedication to quality and stability.\n\n       Greetings are directed to:\n\n       BloodWolf/TRZ USHQ......... A CHALLENGE...Thanks for testing, man.\n :     Mr.Vain/PDY................ DIZ-Ed is almost here, just settle down.\n ¦     /\donis/OBS................ Get that HD stable!!\n ¦     Dierberger/COMUG........... You suck.\n |     Tango/BLC/HMN&VTY/???...... Soooo....?\n |     Crocodile/OBS.............. Just remember to pronounce the ''J''\n l_________________________________________________________________________\n                                                                           |\n                                                           T H E    E N D  |\n            _ __ __________________________________________________________j\n','\n',char(10)),NULL,'auto-added',15896,5,0,NULL,NULL,'noc_af10','scan',1780048643);
INSERT INTO door_catalog VALUES('noc_cp10','NOC-CP10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NOC-CP10.LHA',NULL,'XIM','noC-Coupon.x',NULL,'nocTurne','NOC','\//____/\__________  ________/\__  ___/d ¦ ____ /  \__ \/ __/ / / /   /  \/ __/¦ e | \  // / / / / / / / / / / / / / / / | s |',replace(' __ ____________________________________  : \n \//____/\__________  ________/\__  ___/d ¦ \n  ____ /  \__ \/ __/ / / /   /  \/ __/¦ e | \n  \  // / / / / / / / / / / / / / / / | s | \n   \// / / / / / / / / / /\/ / / / /  | i | \n /\ / / /\  /\  / /\  / / / / /\  //\ | g ¦ \n noC\/\/  \/  \/\/  \/\/  \/\/  \//__\| n : \n .- -- -------------------------------''   : \n :   -÷< /X noC-Coupon Version 1.00 >÷-     \n ¦   A comprehensive, easy to use sysop     \n |   and cosysop free-download creator.     \n |    By nocTurne deSign/MST in 1994        \n','\n',char(10)),'noC-Coupon.doc',replace('.                                     _ __:__ _                  _ __ _____:__\n: _______  __  ____________  __  ______   ¦                                :\n: \_____ \/  \/ __/ __/ /  \/  \/ ____/ d      noC-Coupon Version 1.00     ¦\n¦___ / / / / / / / / / / / / / / __/  : e :  (C)1994 nocTurne deSign/MST   ¦\n\  // / / / / / / / / / /\/ / / / //\ ¦ s ¦      - --------------- -       |\n|\/ \/\/\__/\__/\/\__/\/  \/\/\__//__\| i |  Comprehensive Free-DL System  |\n|___________________________ _ _ __ __j g l_ _ __ _________________________j\n¦                                     \ n /\n:                                      \ /\n                                        Y\n_ _:____________________________________j\n   ¦\n   |  P·R·O·G·R·A·M   D·E·S·C·R·I·P·T·I·O·N\n_ _¦__________________________________________________ __ _\n   :\n\n    noC-Coupon allows sysops and other appointed users to EASILY make files\n    downloadable  without any loss of credits to the leecher.  When used in\n    conjunction  with noC-AutoFree, creating and maintaining free-downloads  :\n    is MUCH less of a hassle.                                                ¦\n                                                                             |\n_ _:_________________________________________________________________________|__\n   ¦                                                                         ¦\n   |  I·N·S·T·A·L·L·A·T·I·O·N                                                :\n_ _¦__________________________________________________ __ _\n   :\n\n    This program requires OS2.0 or greater.\n\n    Simply copy the ''noC-Coupon'' drawer into ''DOORS:'' and mount the door as\n    is  convention  with  your particular version of Ami/Sigma Express.  (A\n    BBSCMD icon is provided for 3.xx users).\n\n    Within  the  program  drawer there is a sample configuration file which\n    should  be  edited,  called ''noC-Coupon.config''.  You may configure the\n    following:\n\n    ACCESS:\n    Those  with  security levels equal to or greater than the number placed\n    there  will  automatically  gain  access to the program.  Omitting this\n    parameter will mean only explicitly defined users may use noC-Coupon.\n    (Example: ''ACCESS=200'')\n\n    USER.xx:\n    You  may appoint up to 40 users to have access to this utility.  As you\n    define  each user you must increment the number in ''.xx''.  Correct caps\n    are not neccessary.  (Example: ''USER.1=nocTurne'' ''USER.2=Jimmy Hoffa'')\n\n    COMMENT.xx:\n    Comments may be directed to individual users of the util when they use\n    it.  (Example: ''COMMENT.1=Dont make EVERYTHING free, man!'' ''COMMENT.2=\n    Where the hell ARE you?'')\n\n    FREEDLTEXT:\n    The text written here will override the default free-download text.  It\n    will  automatically be indented 35 spaces, so keep it under 45 chars in\n    length.  (Example: ''FREEDLTEXT=>>> FrEe dOwnLOad, LeECHES!'')             :\n                                                                             ¦\n_ _:_________________________________________________________________________|__\n   ¦                                                                         ¦\n   |  P·R·O·G·R·A·M   L·O·G·I·C                                              :\n_ _¦__________________________________________________ __ _\n   :\n\n    When  first  run,  (after  typing  ''Coup''),  the program will check the\n    user''s  security  level  in comparison to the access level required for\n    entry  (if  defined).    If the user fails this check, his name will be\n    searched  for  in  the configuration file.  The program will exit if he\n    fails this as well.\n\n    The user, if passing these security measures, will then be greeted with\n    any COMMENT to him that may exist in the configuration file.  Following\n    he  will  be prompted to enter the COMPLETE name(s) of file(s) he wants\n    to  make  free-downloads.    Hitting  the  enter key on a blank line or\n    entering 20 filenames will progress to the next stage.\n\n    A request will be posed to the user verifying that he DOES in fact want\n    to make the files he listed free.\n\n    The  user will then be asked if he wishes the file descriptions altered\n    to  denote the leechability of the files he entered.  If he chooses not\n    to,  the  files  will be made free, but their descriptions will give no\n    indication of this.\n\n    If he DOES choose to, the UPLOAD file-listings will be searched for the\n    descriptions  to  alter.    After  each  entry  is  found,   the edited\n    description  with  the  appended  FREEDLTEXT  will  be shown.  Once the\n    file-listing  has  finished  being  processed,  another   request   for\n    verification  will be posed.  The user may opt to bail out, or continue\n    and have the edited listing saved.\n\n    The  last  stage  entails  the  actual  files  being   tagged   so that\n    Ami-Express  will recognize them as being free.  The success or failure\n    to change each file will be shown.\n\n    Of course during the course of program usage, the user will be notified\n    of any errors that may take place, and they;ll be handled appropriately. :\n                                                                             ¦\n_ _:_________________________________________________________________________|__\n   ¦                                                                         ¦\n   |  C·R·E·D·I·T·S                                                          :\n_ _¦__________________________________________________ __ _\n   :\n\n   noC-Coupon is created  by  nocTurne  deSign/MST  in  1994.  Any questions\n   regarding  the  use  of  this  program should be addressed to nocTurne on\n   Sarcophagus BBS (+1.503.548.0532) or any other board you see me on.\n\n   * This utility is BACKDOOR and VIRUS FREE.  All nocTurne deSign products\n     are created with a dedication to quality and stability.\n\n     2 Hello''s:\n\n     BloodWolf/TRZ USHQ........Now talk to Samir!\n     Blitter...................You''ve always wanted a COOL free download\n                               maker, haven''t ya?                            :\n                                                                             ¦\n_ _:_________________________________________________________________________|__\n   ¦                                                                         ¦\n   |  T·H·E  E·N·D                                                           :\n_ _¦__________________________________________________ __ _\n   :\n    ','\n',char(10)),'{"ACCESS":"200'')"}','auto-added',16476,4,0,NULL,NULL,'noc_cp10','scan',1780048643);
INSERT INTO door_catalog VALUES('noc_flc1','NOC-FLC1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NOC-FLC1.LHA',NULL,'XIM','FLC',NULL,'nocTurne','NOC','\__ \   \_ \   ___  ____/  __ _/  \   \____/ / \ \  / \ \  \ /  \  /  /\  \  \ \  / _/\ /___\  /_____\___\  /\___/__\__\__\  /_____\',replace('__/\____________________________/\__________\n\__ \   \_ \   ___  ____/  __ _/  \   \____/\n / \ \  / \ \  \ /  \  /  /\  \  \ \  / _/\ \n/___\  /_____\___\  /\___/__\__\__\  /_____\\n-====\/===========\/===============\/=deSign\n    noC-FLC (File-Listing Creator) V1.O     \n     ---------------------------------      \n Creates an Ami-Express style chronological \n file-listing  from  a  directory  of files \n with FILE_ID''s...by nocTurne deSign in ''94 \n-==========================================-\n','\n',char(10)),'FLC.doc',replace('     :   :  __/\___________________________________/\_____________ :   :\n     ¦   ¦  \__ \   \__  \    ___  _____/   ___  _/  \   \_____  / ¦ d ¦\n     !   !  /  \ \  /  \  \  /  /  \   /   / \   \  \ \  /  __/\/  ! e !\n     | 1 | /____\  /_______\___/   /\_____/___\___\__\  /_______\  | s |\n     | 9 |       \/            \  /                   \/      noC  | i |\n     | 9 |                      \/                                 | g |\n     | 4 |     noC-File-Listing-Creator (noC-FLC) Version 1.OO     | n |\n     l___j               (C)1994 nocTurne deSign/MST               l___j\n\n____________________________.\n                            ¦\n           O V E R V I E W  |\n____________________________| \n\n This CLI-based tool allows you  to create a text-file which lists filenames,\n sizes,  dates, and descriptions, given a directory of wares with  FILE_ID''s. \n The  produced  text  is  of ami-express style format and is in chronological\n order,  (ie  the newest files are listed last).  This utility will be useful\n if  you  are  a sysop and lose listings, or are a trader and want to have an\n itemized list of your software, or ... some other reason.\n____________________________.\n                            ¦\n   R E Q U I R E M E N T S  |\n____________________________j\n\n   LHA   - (optional) If you intend to be dealing with LHA archives.\n   UNZIP - (optional) If you intend to be dealing with ZIP archives.\n____________________________.\n                            ¦\n                 U S A G E  |\n____________________________j\n\n Information is provided within the program if you supply the argument ''?'' or\n supply  no  arguments  at  all.  This info shall be repeated with more depth\n here:\n\n    Usage:  flc [directory] [textfile] [S|A|D]\n     Args:  [directory] - This is the directory whose files will be\n                          processed.  All dirs within will be ignored.\n             [textfile] - This is where the directory listing will be\n                          written to.  If it already exists, the listing\n                          will be APPENDED to this file.\n                    [S] - This is the default flag: Files will be\n                          omitted from the output text if they have\n                          no FILE_ID.\n                    [A] - This flag will add files without FILE_ID''s\n                          to the list, but with the description:\n                          ''Description Unknown''.\n                    [D] - You may describe the files with no FILE_ID''s\n                          yourself, if this flag is set.\n                          (The three flags are mutually-exclusive)\n\n    Examples:  flc BBS:newusers/upload BBS:dir1 A\n               flc term:downloads term:listings/mywares.txt\n\n Of  course if you have a lot of files, the process may take a while.  Errors\n will  be  displayed  to  the  console,  AND  will be written to a text file:\n "T:noC-FLC.log".  Aborts by CONTROL-C are supported at any time.\n____________________________.\n                            ¦\n   C R E D Z / G R E E T S  |\n____________________________j\n\n The  idea  for this program was originally suggested by DOC WHOO and ignored\n by  me  until now.  THANKS DOC!  If you want to contact me, (nocTurne), FAST\n for  any  reason, call Sarcophagus (+1.503.548.0532).  All my releases visit\n there FIRST.\n\n    ''Zup?''s go out to:\n\n        Rofoe/LGC - Did you HAVE to make that message PUBLIC??  Anyway, glad \n                    you aren''t TOO mad at me.  Thanks for the testing.\n         Caffeine - Happy Late B-Day.\n          /\donis - Enjoy(ing) the internships?\n       Doctor DMA - Eager to see this board prog...\n        Byte Max. - Its a fucking LEGO clone.\n       Dierberger - You suck.\n      Deep Forest - Those Pygmies really know how to jam.\n           Enigma - So do those Gregorian Monks.\n____________________________.\n                            ¦\n               E X E U N T  |\n____________________________j\n','\n',char(10)),NULL,'auto-added',21670,10,0,NULL,NULL,'noc_flc1','scan',1780048643);
INSERT INTO door_catalog VALUES('noc_fr13','NOC-FR13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NOC-FR13.LHA',NULL,'XIM','_/\___/\___/\___/\___/\___/\___/\___/\__',NULL,'nocTurne','NOC','\  _ \_ _ \_ _ \_ _ \_ | \_ _ \_ _ \_ _ \_ -/  |  / |  / |\_/ |  / |  / . _/ |  / ___/- /   |  \_|  \_|  \_|_/  |  \_|  \_|  \_|  \_',replace(' _/\___/\___/\___/\___/\___/\___/\___/\__   \n \  _ \_ _ \_ _ \_ _ \_ | \_ _ \_ _ \_ _ \_ \n-/  |  / |  / |\_/ |  / |  / . _/ |  / ___/-\n/   |  \_|  \_|  \_|_/  |  \_|  \_|  \_|  \_\n\___|   /    /    /|\___    /|   /|   /    /\n-sAL1__/¯\__/¯\__/dESIGN\__/¯\__/¯\__/¯\__/-\n<==========================================>\n FR(Files-Reverse) V1.3 * Numeric Flagging  \n by nocTurne deSign/MST * Nuke call ability \n ---------------------- * Design Changes    \n  Unregistered Release  * More...           \n<==========================================>\n','\n',char(10)),'FR.guide',replace('@database noC-WHO Documentation\n******************************************************************************\n@NODE MAIN "FR Version 1.30 Complete Guide - by nocTurne deSign/MST in ''94"\n\n\n            @{b}FR (Files-Reverse) - The /X Reverse File Lister V1.3@{ub}\n                         (C)1994 nocTurne deSign/MST                     \n              -------------------------------------------------\n              @{" Overview       " LINK OVER   } General Description of Features\n              @{" Installation   " LINK INSTALL} Installing/Configuring FR\n              @{" Usage          " LINK USAGE  } Door Usage/Theory\n              @{" Changes        " LINK CHANGES} History of Implementation\n              @{" Credits/Greets " LINK CREDS  } Where to reach me/Messages\n              -------------------------------------------------\n         (Users of V1.0-1.2 need only to read the ''Changes'' section)\n\n@ENDNODE\n*******************************************************************************\n@NODE OVER "Files-Reverse V1.3 - Overview"\n\n FR  allows users to view a file listing in its reverse order, ie the newer\n descriptions  are  outputted  first.    It  should be of value to users of\n relatively  competitive  boards, where the newest uploads of the day are a\n priority.  This door works under AmiExpress 2.x-3.x and Sigma Express.\n\n@ENDNODE\n*******************************************************************************\n@NODE INSTALL "Files-Reverse V1.3 - Installation"\n\n This program is an XIM and should be installed as such.  Knowledge of door\n installation is assumed.  Icons have been provided for 3.x owners.\n\n               @{b}"FR.x" Icon ToolTypes Available in Version 1.3@{ub}\n               ----------------------------------------------\n               @{" Dividers      " LINK TT1} Set Divider Lines as Default\n               @{" Colors        " LINK TT2} Set Color Display as Default   \n               @{" ShowNewDate   " LINK TT3} Set Date Line as Default   \n               @{" FileNumbers   " LINK TT4} Set File Numbering as Default\n               @{" NocWhoCompat  " LINK TT5} Make Compatible with noC-WHO    \n               @{" Nuker         " LINK TT6} Nuke Door''s Name \n               @{" NukeAccess    " LINK TT7} Access Required to Nuke\n               @{" LowMemory     " LINK TT8} Engage Low Memory Mode Always\n               ----------------------------------------------\n@ENDNODE\n******************************************************************************\n@NODE TT1 "Files-Reverse V1.3 Icon ToolType - Dividers"\n\n @{b}Template: @{ub}Dividers=[YES/NO]\n  @{b}Example: @{ub}Dividers=YES \n\n If you want to enable by default the dividing lines between each filename,\n simply  set  this  tooltype  to  YES.    The  text in "FR-Div.txt" will be\n utilized as the divider graphic.  Please keep the file ONE line long, with\n NO RETURN at the end.  You may use ansi colors in the file.\n\n@ENDNODE\n******************************************************************************\n@NODE TT2 "Files-Reverse V1.3 Icon ToolType - Colors"\n\n @{b}Template: @{ub}Colors=[YES/NO]\n  @{b}Example: @{ub}Colors=YES \n\n To  make colors in the listings default, set this tooltype to YES.  Colors\n will be used in the file number, (if used), and file information.\n \n@ENDNODE\n******************************************************************************\n@NODE TT3 "Files-Reverse V1.3 Icon ToolType - ShowNewDate"\n\n @{b}Template: @{ub}ShowNewDate=[YES/NO]\n  @{b}Example: @{ub}ShowNewDate=YES \n\n To  enable the date-divider graphic, ie what is shown when there is a date\n change  in  the  listing,  set this tooltype to YES.  The text in the file\n "FR-Date.txt"  will  be  utilized  as  the date-divider graphic.  The file\n should  be  ONE  line  long  with  no  tail  return.   To denote where (if\n anyplace) the date should be written, write "@THEDATE".\n\n@ENDNODE\n******************************************************************************\n@NODE TT4 "Files-Reverse V1.3 Icon ToolType - FileNumbers"\n\n @{b}Template: @{ub}FileNumbers=[YES/NO]\n  @{b}Example: @{ub}FileNumbers=YES \n\n If  you  want file-numbers to be shown and want number flagging available,\n set  the  "FileNumbers"  tooltype to YES.  With this option, filenames are\n assigned 1 to 2 digit numbers, which makes for easier file flagging.\n\n@ENDNODE\n******************************************************************************\n@NODE TT5 "Files-Reverse V1.3 Icon ToolType - NocWhoCompat"\n\n @{b}Template: @{ub}NocWhoCompat=[YES/NO]\n  @{b}Example: @{ub}FileNumbers=YES \n\n If  you are using a nocTurne deSign who door (noC-WHO), set "NocWhoCompat"\n to YES.  Files-Reverse usage will be then recognized by the door\n\n@ENDNODE\n******************************************************************************\n@NODE TT6 "Files-Reverse V1.3 Icon ToolType - Nuker"\n\n @{b}Template: @{ub}Nuker=[DOORNAME]\n  @{b}Example: @{ub}Nuker=NUKE \n \n Files-Reverse  has  the ability to call a nuker any time during the use of\n the program.  The default door-name called is ''NUKE''.  To change this, set\n the  ''Nuker=''  tooltype  in the ''FR.x'' icon.  The nuker is called with the\n ''X'' key at the pause prompt.\n\n@ENDNODE\n******************************************************************************\n@NODE TT7 "Files-Reverse V1.3 Icon ToolType - NukeAccess"\n\n @{b}Template: @{ub}NukeAccess=[NUMBER]\n  @{b}Example: @{ub}NukeAccess=250\n\n To  set  the  security  level  needed  to access the Nuke feature, set the\n ''NukeAccess='' tooltype.\n\n@ENDNODE\n******************************************************************************\n@NODE TT8 "Files-Reverse V1.3 Icon ToolType - LowMemory"\n\n @{b}Template: @{ub}LowMemory=[YES/NO]\n  @{b}Example: @{ub}LowMemory=NO\n\n A  Low-Memory  mode is available in FR, which is normally activated in low\n memory  situations.   However to turn this feature on permanently, set the\n "LowMemory"  tooltype to YES.  Benefits to this include 10K of memory used\n at  any  one time (as opposed to memory the size of the directory itself),\n and  faster  startup,  (as  FR does not have to load the whole directory). \n Side effects include disk accessing during the usage of the program, and a\n subtle  slow  down.\n\n@ENDNODE\n*****************************************************************************\n@NODE USAGE "Files-Reverse V1.3 - Usage"\n\n After  typing ''FR'' without any arguments from the command line, files from\n the  upload  directory  of  the current conference are displayed newest to\n oldest.    (Please  note:  The  door  name  ''FR'' should never be altered).\n Several  options are available to the user.  Some of the fundamental usage\n arguments are:\n\n\n ''FR ?'' will bring up information on the program and its usage.\n\n ''FR O''  will  run the door with configurable parameters.  The user will be\n prompted  for  the  date  from  which  the  listing  should  start and the\n directory  to  list.    If  there is more than one directory, the user may\n select from the alternatives.\n     \n ''FR E''  will  allow  the  user  to  configure  FR   to   his   own  taste.\n Configuration data will be stored in the file "DOORS:noC-FR/fr-users.dat".\n     \n\n When  the  listing  is paused, the user may flag files, abort the listing,\n set the listing to nonstop mode, nuke files, (if he has proper access), or\n continue.   CTRL-C aborts are supported.  Usage is very intuitive, I don''t\n think any more detail is neccessary.\n\n@ENDNODE\n******************************************************************************\n@NODE CREDS "Files-Reverse V1.3 - Credits/Greetings"\n\n Files-Reverse  is  created  by nocTurne deSign/MST in 1994.  Any questions\n regarding  the  use  of  this  program  should be addressed to nocTurne on\n Sarcophagus BBS (+1.503.548.0532) or any other board you see me on.\n\n *  This  utility is BACKDOOR and VIRUS FREE.  All nocTurne deSign products\n    are created with a dedication to quality and stability.\n\n        Thanks for the help on this release: \n        \n        * Wraith/GeistHaus,\n        * SaL-1/BoonDocks (Nice Ascii),\n        * Zion/Zion''s Hideout,\n        * Arch-Magi/Tower of Sorcery, \n        * GuMby/Double Vision,\n        * Rotor/Gates of Asgard\n\n nocTurne  deSign  is looking to be adopted by a *COOL* group so direct any\n offers  to my account  on Sarcophagus or another board you may find me on. \n ASCII logos are needed as well...\n\n@ENDNODE\n******************************************************************************\n@NODE CHANGES "Files-Reverse V1.3 - Changes/Enhancements"\n\n@{b}Version 1.2->1.3:@{ub}\n\n-  @{" LowMemory " LINK TT8} tooltype may be set to permanently engage Low-Memory mode.\n(ie, a 10K memory buffer and incremental directory reading).  PLEASE read\nthe section describing this option.\n\n-  A  Nuke  program  may  be  called from within FR, using the "X" command\nduring listing pause.  The nuker name may be set with the @{" Nuker " LINK TT6} tooltype\nand access required may be set with the @{" NukeAccess " LINK TT7} tooltype.\n\n-  A  file  numbering system has been integrated.  Files may be flagged by\ntheir  filename as well as by their number.  To adopt this as default, set\nthe  @{" FileNumbers " LINK TT4} tooltype to YES.  The user may turn this option on/off\nwith  config  option  7.    (The  side  effects of using file numbers: the\nfile-check byte will not be shown in the listing, and the year will be cut\noff from the date.)\n\n-  I  have taken  the popular registration approach.  How do you register? \nWell,  disableds are nice.  Personal Checks are GREAT.  Source code to ACP\n3.XX  is  spectacular.  Calling cards are keen.  A nocTurne deSign logo is\nfucking EXCELLENT.  Or you can tear out the old hex editor, I suppose. \n\n\n@{b}Version 1.1->1.2:@{ub}\n\n-  Incremental  directory  reading is now available.  Versions prior to this\none  required  an amount of memory equal to the size of the file listings to\nbe  available.    Now,  if  that  memory  is  unavailable, FR will engage in\nlow-memory  mode,  and use a buffer of 10K.  Of course the program will slow\ndown  a  bit  for  intermittant  disk accessing.  DATE-SCANS ARE DISABLED in\nLow-Memory Mode.  (Does anybody USE them anyway??)\n\n-  All  information  is now stored in the drawer ''noC-FR'' which should be in\n''DOORS:''.\n\n-  Bug-Fixes:  Last entry in a file listing is now displayed,  nuke messages\nare now  handled properly,  file-flag  field may now be cleared with CTRL-X,\nand other internal changes...\n\n\n@{b}Version 1.0->1.1:@{ub}\n\n-  File-flagging  has  a new look, and no longer shifts the list up when you\nhit enter.\n\n-  Now no longer PAUSES 2 TIMES with newer /X versions.\n\n-  Other various design changes and bug-fixes.\n\n@ENDNODE\n','\n',char(10)),'{"ACCESS":"[NUMBER]"}',NULL,38881,6,0,NULL,NULL,NULL,'scan',1780048643);
INSERT INTO door_catalog VALUES('noc_sd10','NOC-SD10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NOC-SD10.LHA',NULL,'XIM','· _______  __  ____________  __  ______',NULL,'nocTurne','NOC',': \_____ \/  \/ __/ __/ /  \/  \/ ____/ :___ / / / / / / / / / / / / / / __/  · \  // / / / / / / / / / /\/ / / / //\ :',replace('  · _______  __  ____________  __  ______   \n  : \_____ \/  \/ __/ __/ /  \/  \/ ____/   \n  :___ / / / / / / / / / / / / / / __/  ·   \n  \  // / / / / / / / / / /\/ / / / //\ :   \n  |\/ \/\/\__/\__/\/\__/\/  \/\/\__//__\¦   \n  `=----------------------[ design ]---=''   \n         ·-= /X noC-SDOPP V1.0 =-·          \n  .=-----------------------------------=.   \n  |   Senseless Destruction of Public   |   \n  ¦ Property WALL XIM. Very attractive! ¦   \n  :   By nocTurne deSign/MST in 1994    :   \n','\n',char(10)),'noC-SDOPP.doc',replace('.                                     _ __:__ _                  _ __ _____:__\n: _______  __  ____________  __  ______   ¦                                :\n: \_____ \/  \/ __/ __/ /  \/  \/ ____/ d       noC-SDOPP Version 1.0      ¦\n¦___ / / / / / / / / / / / / / / __/  : e :  (C)1994 nocTurne deSign/MST   ¦\n\  // / / / / / / / / / /\/ / / / //\ ¦ s ¦      - --------------- -       |\n|\/ \/\/\__/\__/\/\__/\/  \/\/\__//__\| i |    Cool Looking Wall Door      |\n|___________________________ _ _ __ __j g l_ _ __ _________________________j\n¦                                     \ n /\n:                                      \ /\n                                        Y\n_ _:____________________________________j\n   ¦\n   |  P·R·O·G·R·A·M   D·E·S·C·R·I·P·T·I·O·N\n_ _¦__________________________________________________ __ _\n   :\n\n    noC-SDOPP, (Senseless Destruction of Public Property), is a simple wall\n    door  with  a  great  looking  display.    Possibly one of the simplest\n    products  of nocTurne deSign to date, it is still well-tested and looks\n    cool.                                                                    :\n                                                                             ¦\n                                                                             |\n_ _:_________________________________________________________________________|__\n   ¦                                                                         ¦\n   |  I·N·S·T·A·L·L·A·T·I·O·N                                                :\n_ _¦__________________________________________________ __ _\n   :\n\n    This program requires OS2.0 or greater.\n\n    Simply  copy the ''noC-SDOPP'' drawer into ''DOORS:'' and mount the door as\n    is  convention  with  your particular version of Ami/Sigma Express.  (A\n    BBSCMD icon is provided for 3.xx users).\n\n    Most sysops choose to install walls as a part of their login procedure.\n    noC-SDOPP may be run from an MCI command, or from the main menu.  It is  ·\n    up to you how to use it.                                                 :\n                                                                             ¦\n_ _:_________________________________________________________________________|__\n   ¦                                                                         ¦\n   |  P·R·O·G·R·A·M   L·O·G·I·C                                              :\n_ _¦__________________________________________________ __ _\n   :\n\n    Usage  is  very  intuitive.   The user, after being shown an attractive\n    wall decorated with phrases of grandeur, may choose to enter his own 76\n    character  contribution.    All  text  data   is   kept   in   the file\n    "DOORS:noC-SDOPP/noC-SDOPP.data".   To clear the wall, this file should  .\n    be deleted.                                                              :\n                                                                             ¦\n_ _:_________________________________________________________________________|__\n   ¦                                                                         ¦\n   |  C·R·E·D·I·T·S                                                          :\n_ _¦__________________________________________________ __ _\n   :\n\n    noC-SDOPP  is  created  by  nocTurne  (deSign)  in 1994.  Any questions\n    regarding  the  use  of this program should be addressed to nocTurne on\n    Sarcophagus BBS (+1.503.548.0532) or any other board you see me on.\n\n   * This utility is BACKDOOR and VIRUS FREE.  All nocTurne deSign products\n     are created with a dedication to quality and stability.                 :\n                                                                             ¦\n_ _:_________________________________________________________________________|__\n   ¦                                                                         ¦\n   |  T·H·E  E·N·D                                                           :\n_ _¦__________________________________________________ __ _\n   :\n','\n',char(10)),NULL,NULL,13446,4,0,NULL,NULL,NULL,'scan',1780048643);
INSERT INTO door_catalog VALUES('noc_wh15','NOC-WH15.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NOC-WH15.LHA',NULL,'XIM','noC-WHO.x',NULL,NULL,'NOC','\//____/\__________  ________/\__  ___/d ¦ ____ /  \__ \/ __/ / / /   /  \/ __/¦ e | \  // / / / / / / / / / / / / / / / | s |',replace('__ ____________________________________  :  \n\//____/\__________  ________/\__  ___/d ¦  \n ____ /  \__ \/ __/ / / /   /  \/ __/¦ e |  \n \  // / / / / / / / / / / / / / / / | s |  \n  \// / / / / / / / / / /\/ / / / /  | i |  \n/\ / / /\  /\  / /\  / / / / /\  //\ | g |  \nnoC\/\/  \/  \/\/  \/\/  \/\/  \//__\| n |  \n- -- --------------------------------''   |  \n NOC-WHO V1.5 - USER-Selectable designs  |  \n   (C) 1994   - Designs are CREATABLE    |  \n   nocTurne   - Several features/options |  \n    deSign    - EASY TO INSTALL          :  \n[---------( mIDNIGHT eXPRESS bBS )---------]\n','\n',char(10)),'noC-WHO.guide',replace('@database noC-WHO Documentation\n******************************************************************************\n@NODE MAIN "noC-WHO Version 1.50 Complete Guide - by nocTurne deSign/MST in ''94"\n\n              noC-WHO Version 1.5 - (C)1994 nocTurne deSign/MST\n              -------------------------------------------------\n              @{" Overview       " LINK OVER   } General Description of Features\n              @{" Installation   " LINK INSTALL} Installing/Configuring noC-WHO\n              @{" Usage          " LINK USAGE  } Door Usage/Theory\n              @{" Style Creation " LINK STYLE  } How to create your own designs\n              @{" The Future     " LINK FUTURE } Plans for next release\n              @{" Credits/Greets " LINK CREDS  } Where to reach me/Messages\n              -------------------------------------------------\n\n@ENDNODE\n*******************************************************************************\n@NODE OVER "noC-WHO Overview..."\n\n noC-WHO is the one of most full-featured and flexible WHO doors available,\n from  both  the standpoint of the SYSOP and the USER.  Following is a list\n of the available features of this release:\n \n   · SIMPLE TO INSTALL: Just drag the drawer into "DOORS:".\n   · Compatible with Ami-Express V3.3X+ (32 node version),\n     3.2X- (10 node version), and Sigma Express.\n   · 9 DESIGN STYLES are included for the user to choose from.\n   · All styles are fully EDITABLE/CREATABLE.\n   · Sysops may appoint PRIVILEGED users who can:\n        · Set their action string.\n        · See ALL nodes/fields.\n        · Constantly monitor nodes using the update option.\n   · noC-WHO may serve MULTIPLE purposes, (frontdoor, etc...)\n   · No more ''IN A DOOR'' texts.  All doors may be recognized/named.\n   · A miscellaneous field may be configured by the sysop.\n   · All action texts are configurable.\n   · noC-WHO knows when OTHERS are using it.\n   · Calls per day are known WITHOUT any additional doors, and are\n     reset at midnight automatically.\n   · Given the Blitter ''Lick of Approval''\n\n@ENDNODE\n*******************************************************************************\n@NODE INSTALL "noC-WHO Installation..."\n\n noC-WHO  is  compatible with Ami-Express versions 2.xx thru 3.xx and Sigma\n Express.    Follow  the  conventional  door  installation methods for your\n version.    Then, simply  copy the "noC-WHO" directory, (found in the path\n "noC-WHO1.5/doors/" when  you  dearchived this package), into "DOORS:" and\n the door is ready to be used.\n\n To  define  the  available  settings  for  noC-WHO,  edit  the   text file\n "DOORS:noC-WHO/who.config".    All  of  the  OPTIONS and DESIGN-STYLES are\n located  in  this  file.    The following parameters may be set within the\n configuration file:\n\n----------------------------------------------------------------------------\n  @{" FILENAMES_DISABLED " link opt2} @{" COOLUSER.[NUM] " link opt7 } @{" TITLE.[NUM]   " link opt16} @{" [DOOR].NAME    " link opt12}\n  @{" DIVIDERS_DISABLED  " link opt3} @{" MISC.[NUM]     " link opt8 } @{" HEAD.[NUM]    " link opt17} @{" [CALL].STYLE   " link opt13}\n  @{" PUBLIC_UPDATE      " link opt4} @{" SYSOP_ACTION   " link opt9 } @{" BODY.[NUM]    " link opt18}\n  @{" DOOR_NAMES         " link opt5} @{" YOURNODE.TEXT  " link opt10} @{" TAIL.[NUM]    " link opt19} @{" @BEGIN_ACTIONS " link opt14}\n  @{" CLEAR_SCREEN       " link opt6} @{" SOMEONE.TEXT   " link opt11} @{" DIVIDER.[NUM] " link opt20} @{" @END_ACTIONS   " link opt15}\n----------------------------------------------------------------------------\n@ENDNODE\n*******************************************************************************\n@NODE opt2 "noC-WHO Configuration Option: FILENAMES_DISABLED"\n\n Template: FILENAMES_DISABLED=[YES/NO]\n  Example: FILENAMES_DISABLED=YES \n\n If  you  want  that  filenames  NOT be listed with all upload and download\n operations, set this to YES.\n\n@ENDNODE\n*******************************************************************************\n@NODE opt3 "noC-WHO Configuration Option: DIVIDERS_DISABLED"\n\n Template: DIVIDERS_DISABLED=[YES/NO]\n  Example: DIVIDERS_DISABLED=YES\n\n If  you have more than 6 nodes or so, you may want to DISABLE the DIVIDING\n LINES between node texts to make the display more COMPACT.  If this is the\n case, set this parameter to YES.\n\n@ENDNODE\n*******************************************************************************\n@NODE opt4 "noC-WHO Configuration Option: PUBLIC_UPDATE"\n\n Template: PUBLIC_UPDATE=[YES/NO]\n  Example: PUBLIC_UPDATE=NO\n\n Some  sysops may not want the general public to be able to use the ''WHO U''\n option  to  CONSTANTLY  MONITOR  other  nodes,  and can use this option to\n DISABLE it.\n\n@ENDNODE\n*******************************************************************************\n@NODE opt5 "noC-WHO Configuration Option: DOOR_NAMES"\n\n Template: DOOR_NAMES=[YES/NO]\n  Example: DOOR_NAMES=YES\n\n If  this option is set to YES, noC-WHO will replace the "IN A DOOR" action\n text  with  the  name of the door a user is in.  In order for this to work\n you must have the door-log turned on for each node.\n\n If you want that full names be used, (ie "NewFiles V1.5" rather than "N"),\n use the @{"[DOOR].NAME" link opt12} option.\n\n@ENDNODE\n*******************************************************************************\n@NODE opt6 "noC-WHO Configuration Option: CLEAR_SCREEN"\n\n Template: CLEAR_SCREEN=[YES/NO]\n  Example: CLEAR_SCREEN=YES\n\n If  this  is  set  to  YES,  noC-WHO  will  simply clear the screen before\n displaying the node information.\n\n@ENDNODE\n*******************************************************************************\n@NODE opt7 "noC-WHO Configuration Option: COOLUSER.[NUM]"\n\n Template: COOLUSER.[NUM]=[USERNAME]\n  Example: COOLUSER.1=nocTurne\n           COOLUSER.2=/\donis\n\n Trusted  users should be listed with this parameter.  They will be able to\n see  EVERYTHING  and  have privileged access to the door.  As each user is\n added you must increment [NUM].  Up to 20 users may be listed.\n\n@ENDNODE\n*******************************************************************************\n@NODE opt8 "noC-WHO Configuration Option: MISC.[NUM]"\n\n Template: MISC.TITLE=[TEXT]\n  Example: MISC.TITLE=Phone #\n\n noC-WHO  features  a  configurable column which you may use as you please.\n (Ideas: Phone numbers, modem types, node info, etc..) To define this field\n for your OWN purposes you must first create a title. \n\n Template: MISC.[NUM]=[TEXT]\n  Example: MISC.0=LOCAL\n           MISC.1=555-1212\n           MISC.2=555-1213\n\n You may define what is printed in the configurable field of EACH NODE.  If\n you want any of them to display the BAUD, set those to ''@''.\n\n@ENDNODE\n*******************************************************************************\n@NODE opt9 "noC-WHO Configuration Option: SYSOP_ACTION"\n\n Template: SYSOP_ACTION=[TEXT]\n  Example: SYSOP_ACTION=Hanging in the John. \n\n Some  sysops  like  to  have  themselves  listed  on  a  local node.  This\n parameter  allows them to customize exactly what their ACTION field says. \n\n@ENDNODE\n*******************************************************************************\n@NODE opt10 "noC-WHO Configuration Option: YOURONE.TEXT"\n\n Template: YOURNODE.TEXT=[TEXT]\n  Example: YOURNODE.TEXT=>> Your Node <<\n\n The  text  listed  here will be used in place of the user''s name, when HIS\n node is being shown to him.\n\n@ENDNODE\n*******************************************************************************\n@NODE opt11 "noC-WHO Configuration Option: SOMEONE.TEXT"\n\n Template: SOMEONE.TEXT=[TEXT]\n  Example: SOMEONE.TEXT=New Caller\n\n This  text  will be used as the name of a person just logging in or who is\n registering with the system.\n\n@ENDNODE\n*******************************************************************************\n@NODE opt12 "noC-WHO Configuration Option: [DOOR].NAME"\n\n Template: [DOOR].NAME=[TEXT]\n  Example: COUP.NAME=noC-Coupon V1.0\n           N.NAME=NewFiles V2.0\n          \n If the @{"DOOR_NAMES" link opt5} option is on and the door logs are active, you may give\n specific  names  to  each of your doors.  Normally if the user is in, say,\n noC-Coupon,  only the CALLED name will be shown in the action field: COUP.\n If  you want a more  SPECIFIC representation, use the first example shown. \n Then the action field would read "noC-Coupon V1.0".\n\n@ENDNODE\n*******************************************************************************\n@NODE opt13 "noC-WHO Configuration Option: [CALL].STYLE"\n Template: [CALL].STYLE=[NUM]\n  Example: FRONTEND.STYLE=6\n\n If  you  want  a  specific  style  to be used when the door is called by a\n particular  name,  such  as in the case of a login who display (FRONTEND),\n you may select the style to be used with this option.  (In the example, if\n noC-WHO  is  called  by  the name FRONTEND, it will use the 6th design, [A\n compact node display]).  If you want that the user NOT have the ability to\n select  a  design,  you  can  SET  the style by using this command.  (eg. \n WHO.STYLE=1)\n\n@ENDNODE\n*******************************************************************************\n@NODE opt14 "noC-WHO Configuration Option: @BEGIN_ACTIONS"\n\n If  you  want  to  customize  the  action  texts  you  can  edit the texts\n proceeding the "@BEGIN_ACTIONS" string in the included config file.  These\n are  the  default  texts  for  every action, (Awaiting call, Beginning UL,\n etc...).    When  you  EDIT  these  texts,  be sure to keep them around 18\n characters  long  and  KEEP  THEM  IN THE ORDER THEY CAME.  Any additional\n carriage  returns or alterations to the arrangement of the file may result\n in incorrect action displays.\n\n@ENDNODE\n*******************************************************************************\n@NODE opt15 "noC-WHO Configuration Option: @END_ACTIONS"\n\n This string TERMINATES the action text list.\n\n@ENDNODE\n*******************************************************************************\n@NODE opt16 "noC-WHO Configuration Option: TITLE.[NUM]"\n\n Template: TITLE.[NUM]=[TEXT]\n  Example: TITLE.1=Simple Design\n\n Use  this  string  to designate a NAME for a particular who design.  [NUM]\n may be a number from 1 to 9, as you may have up to 9 screen-styles for the\n user  to  select  from.   The title will be shown during the CONFIGURATION\n session  and  should  convey  the  ''MOOD''  of its respective design, while\n remaining under 18 characters.\n\n@ENDNODE \n*******************************************************************************\n@NODE opt17 "noC-WHO Configuration Option: HEAD.[NUM]"\n\n Template: HEAD.[NUM]=[TEXT]%\n  Example: \n-----------------------8< Cut Here -------------------------------\n HEAD.1=\n =========================================================\n NODE      NAME                      @MISC..........  CONF\n =========================================================\n %\n -----------------------8< Cut Here -------------------------------\n\n This  defines  the  HEADER  for  the  design number [NUM].  This text will\n comprise  the  top  part  of  the  who screen and may be used to title the\n fields you  will define in the @{"BODY.[NUM]" link opt18} section, or it may simply be an\n interesting  looking  design to preceed the node texts.  ANSI codes may be\n used  anywhere.  Look at one of the 9 examples included for more examples.\n Note that the text may have as many carriage returns as you like, but must\n be TERMINATED by a ''%'' sign.\n\n See @{"Header Commands" link HEADCMDS} for the ''@'' commands available.\n@ENDNODE \n*******************************************************************************\n@NODE opt18 "noC-WHO Configuration Option: BODY.[NUM]"\n\n Template: BODY.[NUM]=[TEXT]%\n  Example: \n -----------------------8< Cut Here -------------------------------\n BODY.1=\n  @#       @NAME.................... @MISC..........   @$\n %\n -----------------------8< Cut Here -------------------------------\n\n The  text  written  after  this  argument will compose the BODY of the who\n display  [NUM].   This text will repeatedly be displayed for each node and\n information  will be filled in accordingly.  As with all design texts, the\n body-text  must  be terminated by a ''%'', and may be composed of any number\n of ANSI codes.\n\n See @{"Body Commands" link HEADCMDS} for the ''@'' commands available.\n\n@ENDNODE\n*******************************************************************************\n@NODE opt19 "noC-WHO Configuration Option: DIVIDER.[NUM]"\n\n Template: DIVIDER.[NUM]=[TEXT]%\n  Example: \n -----------------------8< Cut Here -------------------------------\n DIVIDER.1=\n (======================================================)\n %\n -----------------------8< Cut Here -------------------------------\n\n If  you  have  node  dividers enabled, the text written here will separate\n each  of  the  body(node)  texts.    You  may  use as many rows of text to\n separate the node informations; however, one row is suggested.  Again, the\n text must end with a ''%'' and may be composed of ANSI sequences.\n\n@ENDNODE\n*******************************************************************************\n@NODE opt20 "noC-WHO Configuration Option: TAIL.[NUM]"\n\n Template: TAIL.[NUM]=[TEXT]%\n  Example: \n -----------------------8< Cut Here -------------------------------\n TAIL.1=\n (======================================================)\n  @VERSIONTEXT - (C)1994 nocTurne deSign - Time: @TIME\n %\n -----------------------8< Cut Here -------------------------------\n\n This  text  will  be  the last string emitted.  You may use it to show the\n time,  the number of calls for the day, or to give yourself credit for the\n design  you  created.  Any number of lines may be used, ANSI sequences are\n allowed, and the text must be terminated with a ''%''.\n\n See @{"Tail Commands" link HEADCMDS} for the ''@'' commands available.\n\n@ENDNODE\n*******************************************************************************\n@NODE USAGE "noC-WHO Usage..."\n\n Information  on  program usage may be obtained with "WHO ?".  To CONFIGURE\n noC-WHO  to  one of the nine styles available, the user may enter "WHO E",\n which  will prompt him to select his preference.  A DATA FILE with all the\n users''  preferences will be kept named "DOORS:noC-WHO/data/who-users.dat".\n\n If  the UPDATE option has been made available to all users, or the user is\n privileged,  he may use this door to actively monitor the actions of those\n online.    "WHO  U"  will cause noC-WHO to update its display every second\n until  a  key  is pressed.  If the "PUBLIC_UPDATE" config option is set to\n "NO",  only  privileged users will be able to have display updates.  Those\n with  privileged  access  may  also  set their ACTION text.  Setting it to\n NOTHING will cause all actions to be displayed normally.\n\n Nodes  that   are   QUIETED   are   EXEMPT   from   being   displayed   to\n ''underpriviledged''  users.  Nodes that are disabled or unavailable will be\n shown as such.  At midnight, a task spawned by the door upon its first run\n will AUTOMATICALLY RESET the call counter to 0.\n\n@ENDNODE\n*******************************************************************************\n@NODE STYLE "Creating Custom noC-WHO Screens..."\n\n  -----------------------------------------------------------------------\n  @{" Command Set Usage    " link CMDUSE  }........How to use the ''@'' commands\n  @{" Header/Tail Commands " link HEADCMDS}........Descriptions of header/tail text commands\n  @{" Body Commands        " link BODYCMDS}........Descriptions of body text commands\n  -----------------------------------------------------------------------\n@ENDNODE\n*******************************************************************************\n@NODE CMDUSE "noC-WHO Command Set Utilization..."\n\n noC-WHO  features  an  ''@''  command set, (each command begins with the ''@''\n character),  which  may  be  used  to  call  up particular strings in your\n header, body, and tail texts.  This is best explained with examples:\n\n Take  the  ''@TIME'' command.  When noC-WHO finds this text in the header or\n tail texts, it will replace it with the current system time.\n\n If your tail text in the config file reads:\n ----------------------------------------------8< Cut Here -----------\n ===============================================================\n  @VERSIONTEXT - This WHO-Door Smells - The Time: @TIME\n ----------------------------------------------8< Cut Here -----------\n\n When displayed it would read:\n ----------------------------------------------8< Cut Here -----------\n ===============================================================\n  noC-WHO V1.50 - This WHO-Door Smells - The Time: 01:20\n ----------------------------------------------8< Cut Here -----------\n\n You  may  use  periods  to extend the length of the text.  For example, to\n display the system time WITH seconds:\n\n "The Time: @TIME..."-----=would yield=----->"The Time: 01:20:12"\n\n An example from the body-text command set; if this were your body string:\n\n ----------------------------------------------8< Cut Here -----------\n  @# | @NAME............... | @LOC................... | @ACTION.......\n ----------------------------------------------8< Cut Here -----------\n\n The output text (body only, for three nodes) would then be:\n\n ----------------------------------------------8< Cut Here -----------\n  01 | nocTurne             | ·-÷« MST^CoDeR »÷-·     | NUN''A''YOR''BIZ!\n  02 |                      |                         | Awaiting Call \n  03 | Jake Steinfeld       | From body-building heav | Viewing Dirs  \n ----------------------------------------------8< Cut Here -----------\n\n As  you  can  see from node 3, where there are no periods the text will be\n cut  off.    If  you  only used "@NAME", without any of the periods, names\n would extend no longer than 5 characters.\n\n This concludes your lesson of the noC-WHO command-set.\n@ENDNODE\n*******************************************************************************\n@NODE HEADCMDS "noC-WHO Header/Tail Commands..."\n\n                     4 Header/Tail Commands Available:\n                     ---------------------------------\n                          @{"         @CL          " link cmd1}\n                          @{"        @MISC         " link cmd2}\n                          @{"        @TIME         " link cmd3}\n                          @{"     @VERSIONTEXT     " link cmd4}\n                     ---------------------------------\n@ENDNODE\n*******************************************************************************\n@NODE BODYCMDS "noC-WHO Body Commands..."\n\n                       8 Body Commands Available:\n                       --------------------------\n                               @{" @#      " link cmd5}\n                               @{" @$      " link cmd6}\n                               @{" @ACTION " link cmd7}\n                               @{" @BAUD   " link cmd8}\n                               @{" @LOC    " link cmd9}\n                               @{" @MISC   " link cmd10}\n                               @{" @NAME   " link cmd11}\n                               @{" @WHEN   " link cmd12}\n                       --------------------------\n@ENDNODE\n*******************************************************************************\n@NODE cmd1 "noC-WHO Header/Tail Command: @CL"\n\n  Command: @CL\n   Result: Number of calls today\n\n If  you  expect more than a thousand calls in one day (!), you may want to\n extend the field to 4 characters, ("@CL.").\n\n@ENDNODE\n*******************************************************************************\n@NODE cmd2 "noC-WHO Header/Tail Command: @MISC"\n\n  Command: @MISC\n   Result: Text defined in MISC.TITLE config parameter\n\n This  string  will  be  replaced with the title of the miscellaneous field\n you''ve  defined.  ie, whatever has been defined in the @{" MISC.TITLE " link opt8} config\n argument will be displayed here.\n\n@ENDNODE\n*******************************************************************************\n@NODE cmd3 "noC-WHO Header/Tail Command: @TIME"\n\n  Command: @TIME\n   Result: System time\n\n By  default,  a five character time display will replace the command text,\n ("@TIME"  is  five characters long).  Thus only the hours and seconds will\n be  shown.  Extending the field to eight characters will show the complete\n system time, (ie "@TIME..."--->"01:12:20").\n\n@ENDNODE\n*******************************************************************************\n@NODE cmd4 "noC-WHO Header/Tail Command: @VERSIONTEXT"\n\n  Command: @VERSIONTEXT\n   Result: "noC-WHO V1.5" string\n\n This  command  text  will  be replaced with the version string of noC-WHO.\n THIS  COMMAND  MUST  BE  SOMEWHERE  IN  YOUR  HEADER/TAIL  TEXT or else an\n annoying  version string will be appended to the who display.  Be warned. \n\n@ENDNODE\n*******************************************************************************\n@NODE cmd5 "noC-WHO Body Command: @#"\n\n  Command: @#\n   Result: Current node number being showed\n\n This is simply a two character field that will be replaced with the number\n of  the  NODE  that  is currently being displayed.  As each node is shown,\n this number will be incremented respectively.\n\n@ENDNODE\n*******************************************************************************\n@NODE cmd6 "noC-WHO Body Command: @$"\n\n  Command: @$\n   Result: User''s current conference\n\n This command will show the current node''s user CONFERENCE NUMBER.   Please\n note,  in  order  for this to function correctly you MUST HAVE THE CALLERS\n LOG for each node TURNED ON.\n\n@ENDNODE\n*******************************************************************************\n@NODE cmd7 "noC-WHO Body Command: @ACTION"\n\n  Command: @ACTION\n   Result: What the user is doing\n\n This  string  will reflect what ACTION the user of the node being shown is\n taking.    It  is  suggested  you extend the field to around 18 characters\n length, (ie "@ACTION...........").\n\n@ENDNODE\n*******************************************************************************\n@NODE cmd8 "noC-WHO Body Command: @BAUD"\n\n  Command: @BAUD\n   Result: Users connect rate\n\n This  string  will  be  replaced with the BAUD of the user currently being\n shown.\n\n@ENDNODE\n*******************************************************************************\n@NODE cmd9 "noC-WHO Body Command: @LOC"\n\n  Command: @LOC\n   Result: User''s Location/Group\n\n This  field  should be extended to around 16 characters to fit the average\n user''s location line, (ie, "@LOC............")\n\n@ENDNODE\n*******************************************************************************\n@NODE cmd10 "noC-WHO Body Command: @MISC"\n\n  Command: @MISC\n   Result: Misc field definition for current node\n\n This command will show what is defined in the @{"MISC" link opt8} field for each node.\n\n@ENDNODE\n*******************************************************************************\n@NODE cmd11 "noC-WHO Body Command: @NAME"\n\n  Command: @NAME\n   Result: The user''s name/handle\n\n To  show  most user''s full names/handles, this field should be extended to\n around 14 characters, (ie, "@NAME.........").\n\n@ENDNODE\n*******************************************************************************\n@NODE cmd12 "noC-WHO Body Command: @WHEN"\n\n  Command: @WHEN\n   Result: User''s time of login\n\n This  will  show  the  time,  (hours  and minutes), of the currently shown\n user''s  login.  If you wish seconds to be shown as well, this field should\n be  extended to 8 characters, (ie, "@WHEN...").  YOU MUST HAVE THE CALLERS\n LOG ON FOR THIS COMMAND TO FUNCTION.\n  \n@ENDNODE\n*******************************************************************************\n\n@NODE FUTURE "The Future of noC-WHO..."\n\n · YOU tell ME!\n\n@ENDNODE\n*******************************************************************************\n@NODE CREDS "noC-WHO Credits and Greetings..."\n\n noC-WHO  is  created  by  nocTurne  deSign/MST  in  1994.    Any questions\n regarding  the  use  of  this  program  should be addressed to nocTurne on\n Sarcophagus BBS (+1.503.548.0532) or any other board you see me on.\n\n   * This utility is BACKDOOR and VIRUS FREE.  All nocTurne deSign products\n     are created with a dedication to quality and stability.\n\n Greetings:  Arch-Magi: My MAN! Tanks, and tell YOGI and BEAR I said hi.\n            The Wraith: Things should PICK UP!  Tnx for the help.\n              Doc Whoo: Test - whats a pointer?\n             BloodWolf: Thanks, and tremendous luck in your ventures.\n               Mr.Vain: Need the logo collection... NOW!\n                 Samir: Let me join... C''mon. I''ll supply the pot.\n            Dierberger: You suck.\n         ASCII gfxians: I need nocTurne deSign logos/noC-WHO designs!\n                   All: Soon coming - DIZ-Ed v2.0, Zippy Multiple v1.0\n\n@ENDNODE\n*******************************************************************************\nwhoa, whats this I found in my ear?.......\n','\n',char(10)),NULL,'auto-added',58192,5,0,NULL,NULL,'noc_wh15','scan',1780048643);
