_)  _  )(  _  )(  _  )(   |/   (  |  )(     )\n            /   \/  __/\/   ) \/     \/   |    /     \/  |  \\n           /     \      \      \  |   \        \  |   \      \\n           \_____/______/__|___/__|___/___|____/__|___/______/<md>\n\n\n\nTHE TERAWHO DOC: THIS DOOR DON''T NEED A DOC ... JUST US IT !!!!\n\n\n\nGREETINGS TO: MINDEX - DUSTY - OXBOW - DR.BADVIBES - ANDABATA - WIZZ\n              WIZZBIT - BITBULL - THE BIG BROTHER - SEMTEX - DISORDER\n              WUPPE - CHEESE - DEVASTATOR - VINDICATOR - VILLA - OVERKILL\n              RAINBOW BEARS - CMA - SOUNDWAVE - EMPHARIO - BUSSY - JAKE\n              THC - SAL ONE - ZACK - POWERBYTE - FLETCHER - SPEED - TYCOON\n              PYROMANIAC M.C. - DOPE - WOLF - DELITE - THE RAVER - MOBY\n              MEGA FORTRESS - RUBYX - DEMENSION - FACET - CREW ONE - PURNO\n              TAZ DEVIL - CAPTIAN PIZZA - BAMBAM - SKIN - NIKE - ZOUF - MAD\n              ANDY - DPAC - TOMCAT - DARKVADER - HELL BOOSTER - PHOENIX\n              MOTIVE POWER - INCUBUS - THURLOG - MDJ - APOLLO - NOTORIOUS\n              EVERT - FASTBOY AND THE REST OF THE BEST !!!!\n\n\n============================================================================\n============================================================================\n\n   ___________________  _____   ________________________________________\n   \   \    \      \  \ \    \  \       \       \       \       \       \\nmd /    \   /  ____/  /_/    /\ /   /   /  \    /  \    /  _____/  \    /\\n  /        /  __/__  / /    /--/   /   /      \/   /   /  __/__/      \/ /\n /   \    /       /        /  /       /   /   /       /       /   /    \/\n/_____\__/_______/________/--/_______/___/___/_______/_______/___/_____/\\n\______\_\_______\________\/ \_______\___\___\_______\_______\___\_____\/\n                                                      the party group ''95\n\n\n                     WANNA JOIN THE PARTY GROUP ''95\n\n\n                       JUST LEAVE A MSG TO MINDEX\n\n                        ON ONE OF THE NO BOARDZ!\n\n              <this is a group for phun and cool releases>\n\n\n\n\n                           MEMBERS UNTIL NOW:\n\n   MINDEX - TERABYTE - DUSTY - OXBOW - DR.BADVIBES - ANDABATA - WIZZBIT \n      BITBULL - THE BIG BROTHER - SEMTEX - DISORDER - WUPPE - CHEESE\n    DEVASTATOR - VINDICATOR - VILLA - OVERKILL - RAINBOW BEARS - WIZZ \n   CMA - SOUNDWAVE - EMPHYRIO - POWERBYTE - BUSSY - THE RAVER - TYCOON\n                             CAPTIAN PIZZA\n\n                           BOARDS UNTIL NOW:\n\n         SUBSTANCE - THE FIRM - THE CATHEDRAL - SUDDEN IMPACT\n             THE LAST RESORT - SOUTHERN TRIBE - NOSE FUCK\n','\n',char(10)),NULL,'auto-added',48230,5,0,NULL,NULL,'no_who12','scan',1780048643);
