INSERT INTO door_catalog VALUES('nrv_av10','NRV-AV10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NRV-AV10.LHA','nirvanaavail','XIM','nirvanaavail',NULL,'iCE.','NRV','|.__\_    \__\,  /___  /___.18''th Mar 1997 | -|  _ \_   \    /|   \/    |-              | -l__/       \____|_________|- NirvanaAvail |',replace('.---______---_____----__-------------------.\n|.__\_    \__\,  /___  /___.18''th Mar 1997 |\n-|  _ \_   \    /|   \/    |-              |\n-l__/       \____|_________|- NirvanaAvail |\n!CE/_________\     [NiRVANA]     v1.0      |\n|   coded&designed by iCE. /X sysop avail  |\n|door. Xim coded in AmigaE for speed.      |\n|preview pic included in archive           |\n`------------------------------------------''\n33.6 DigITal-X Prd/NirVana Dist Site! 33.6\n','\n',char(10)),NULL,NULL,NULL,'auto-added',16436,4,0,NULL,NULL,'nrv_av10','scan',1780048643);
