INSERT INTO door_catalog VALUES('nrv_or12','NRV-OR12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NRV-OR12.LHA','nirvanaorder12','XIM','.---______---_____----__-------------------.',NULL,'iCE.','NRV','|.__\_    \__\,  /___  /___.25''th Feb 1997 | -|  _ \_   \    /|   \/    |-              | -l__/       \____|_________|- NirvanaOrder |',replace('.---______---_____----__-------------------.\n|.__\_    \__\,  /___  /___.25''th Feb 1997 |\n-|  _ \_   \    /|   \/    |-              |\n-l__/       \____|_________|- NirvanaOrder |\n!CE/_________\     [NiRVANA]     v1.2      |\n|    coded&designed by iCE. Xim asciiorder |\n|door with cursorkey support for 9 artists,|\n|commentline and the tag for each artist.  |\n|order to all artist function, create msg''s|\n|to artist, cool design. Preview picture   |\n|included in the archive. - bugfixed -     |\n`------------------------------------------''\n','\n',char(10)),'NIRVANAORDER12.DOC',replace('\n\n-   -  - -- ---------------------------------------------------- -- -  -   -\n .____       ....  ______\n |    \______:..:__\    /____     ................____.    ................\n |     \     :\ :   \  /_\  /_____:::::::....  ::|    |____:::::::....  :::\n l__   _\    : \:     /|  \//      |::     ..  ::|  _ |    \:::     ..  :::\n   //__/ \_  :  \______l___________l::         ::l__/ l     \::         :::\n      /______:___\                ::::.........::: /_________\:.........:::\n             :..:                                                       !CE\n-   -  - -- -----------[ n . i . r . v . a . n . a ]------------ -- -  -   -\n\n         presents today Nirvana-order v1.2 coded&designed by iCE\n\n\n\n                               -[WHAT?!]-\n\n yeah, what the fuck is a orderdoor?, well you may say it''s a\n little helpdoor for people wanna order sume ascii from asciiartists\n in sume cool boards.\n\n\n\n                            - installation -\n\n· copy the order.info icon into yar <BBSPATH>:COMMANDS/BBSCMD/ directory.\n· copy everything within the doors/ dir into yar DOORS: drawer\n· The it''s time to config tha \n  doors:nirvana/nirvanaorder/nirvanaorder.info file.\n\n\n\n                               - config -\n\nARTISTS=                  ; guess what? I think its the number of artists \n                            you wanna have!. Was I wrong again?\n\nNAME.1=                   ; oh!, not to hard for ya, is it?\nNAME.2=\nNA.....\n\nCOMM.1=                   ; write a cool slogan for artist #1\nCOMM.2=                   ; write a cool slogan for artist #3½\nCOMM.3=                   ; write a cool slogan for Kurt Cobain\n\nTAG.1=                    ; wadd''ya think? his date of birth or what?\n\nCONFPATH=                 ; here you may write the name of your mother.\n                            eeeehm? fullpath to conf where you want the \n                            mess''s. For example BBS:ASKEE/ or sumething.\n\n well, when you have configged this, about ten hours later, you may \n test the door and figure out you don''t wanna have the door cause you \n don''t realize the cool thing with it,.. \n\n\n\n                              - features -\n\n · cursor keys support\n · upto 9 different artists\n · cool design\n · comment for each artist\n · tag for each artist\n · order from all artist option\n · writes a mess to the artist(s)\n\n\n\n                               - history -\n\n v0.1  fuckin'' lame arexx door with no speed, no tooltype-readings and no\n       message maker. Never released.\n\n v0.2  amigaE? /X-xim doors? simple? let''s party! fixed a cool working\n       version in amigaE.\n\n v1.0  [07''th JAN 1997] this release! fully working with features listed\n                        in the features list above.\n\n v1.1  [17''th Feb 1997] Fixed the design a little.\n\n v1.2  [25''th Feb 1997] Removed a shitty little bug, no more gurus!\n\n\n\n                              - known bugs -\n\n · time when message was written will always be some day in 1996,\n   i''m workin with it and it will probobly be fixed in the near future.\n\n · the handles of the artists can''t override 10 letters. WILL be fixed\n   in future versions.\n\n\n\n                              - future plans -\n\n · fixing the known bugs.\n · more artists\n · more lines to describe what to order\n · some kinda bulletin-file\n · hotkeys for every command and artist\n · anim option, case you want a more animated outlook\n · preview''s from the artists option\n · counter for each artist, how many orders he got.\n · several small design fixes.\n\n\n\n                         - bugreports or support -\n\n If you find any bugs or want the latest version of nirvanaorder\n have a call to nirvana whq:\n\n access denied       +46-371-82218       nup: nirvana\n\nNiRVANA homepage: www.geocities.com/area51/8439/INDEX.HTM\n\n                                - members -\n\n · iCE\n · tWEZZER\n\n\n\n\n\n                   - other doors available 25''th Feb 97 -\n\n · NirvanaWall  v1.3  A fast wall with cursorkey-support and coloursupport.\n · NirvanaQuick v1.0  Quick-logon door with cursor&hotkey support.\n · NirvanaBaud  v1.0  A baudchecker door.\n','\n',char(10)),NULL,NULL,17783,5,0,NULL,NULL,'nrv_or12_nirvanaorder12','scan',1780048643);
INSERT INTO door_catalog VALUES('nrv_pa10','NRV-PA10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NRV-PA10.LHA','nirvanapager','XIM','.---______---_____----__-------------------.',NULL,'iCE.','NRV','|.__\_    \__\,  /___  /___. 6''th Mar 1997 | -|  _ \_   \    /|   \/    |-              | -l__/       \____|_________|- NirvanaPager |',replace('.---______---_____----__-------------------.\n|.__\_    \__\,  /___  /___. 6''th Mar 1997 |\n-|  _ \_   \    /|   \/    |-              |\n-l__/       \____|_________|- NirvanaPager |\n!CE/_________\     [NiRVANA]     v1.0      |\n|   coded&designed by iCE. Xim /X pagesysop|\n|door. Add line to callslog, cool animated.|\n|Ask if you wanna leave a comment. cool    |\n|design. Preview pics incl. in the archive |\n`------------------------------------------''\n','\n',char(10)),'NIRVANAPAGER10.DOC',replace('\n\n-   -  - -- ---------------------------------------------------- -- -  -   -\n .____       ....  ______\n |    \______:..:__\    /____     ................____.    ................\n |     \     :\ :   \  /_\  /_____:::::::....  ::|    |____:::::::....  :::\n l__   _\    : \:     /|  \//      |::     ..  ::|  _ |    \:::     ..  :::\n   //__/ \_  :  \______l___________l::         ::l__/ l     \::         :::\n      /______:___\                ::::.........::: /_________\:.........:::\n             :..:                                                       !CE\n-   -  - -- -----------[ n . i . r . v . a . n . a ]------------ -- -  -   -\n\n         presents today Nirvana-Pager v1.0 coded&designed by iCE\n\n\n\n                               -[WHAT?!]-\n\n A door to page the sysop and give a reason for doing that. \n\n\n\n                            - installation -\n\n· copy the O.info icon into yar <BBSPATH>:COMMANDS/BBSCMD/ directory.\n· copy everything within the doors/ dir into yar DOORS: drawer\n\n\n\n\n                              - features -\n\n · add line to callerslog\n · cool design&anim\n · cursorkey support\n · ask if you wanna leave a comment\n\n\n                               - history -\n\n v1.0  [ 6''th MAR 1997] this release! fully working with features listed\n                        in the features list above.\n\n\n                              - known bugs -\n\n · No known bugs.\n\n\n                              - future plans -\n\n · Some kinda stats for the most paging users or something.\n · a bulletin-file.\n · last 5 reasons list\n · more animated layout.\n · several small design fixes.\n\n\n\n                                - support -\n\n If you want the latest version of nirvanapager\n have a call to these boards:\n\n  access denied       +46-371-82218          WHQ         (nup: nirvana)\n\n  digit/\l-x          +31-570-637050         The neatherlands dist site\n  illusions           +46-371-80141          Sweden dist site\n  moldavia            +46-480-411887         Sweden dist site\n\n                                - members -\n\n · iCE\n · tWEZZER\n · AleX\n\n\n\n\n                   - other doors available 6''th Feb 97 -\n\n · NirvanaWall  v1.3  A fast wall with cursorkey-support and coloursupport.\n · NirvanaQuick v1.0  Quick-logon door with cursor&hotkey support.\n · NirvanaBaud  v1.0  A baudchecker door.\n · NirvanaOrder v1.2  A cool orderdoor, cursorkeys-support, many artists,..\n\n','\n',char(10)),NULL,NULL,24023,7,0,NULL,NULL,'nrv_pa10_nirvanapager','scan',1780048643);
INSERT INTO door_catalog VALUES('nrv_spa1','NRV-SPA1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NRV-SPA1.LHA','screampager','XIM','.---______---_____----__-------------------.',NULL,'iCE.','NRV','|.__\_    \__\,  /___  /___.13''th May 1997 | -|  _ \_   \    /|   \/    |-              | -l__/       \____|_________|-  SCREAMPAGER |',replace('.---______---_____----__-------------------.\n|.__\_    \__\,  /___  /___.13''th May 1997 |\n-|  _ \_   \    /|   \/    |-              |\n-l__/       \____|_________|-  SCREAMPAGER |\n!CE/_________\     [NiRVANA]      v1.0     |\n|                                          |\n|       A PAGER door for /X by iCE.        |\n|                                          |\n`---------------------[nrv /X-development]-''\n','\n',char(10)),'SCREAMPAGER.DOC',replace('\n\n-   -  - -- ---------------------------------------------------- -- -  -   -\n .____       ....  ______\n |    \______:..:__\    /____     ................____.    ................\n |     \     :\ :   \  /_\  /_____:::::::....  ::|    |____:::::::....  :::\n l__   _\    : \:     /|  \//      |::     ..  ::|  _ |    \:::     ..  :::\n   //__/ \_  :  \______l___________l::         ::l__/ l     \::         :::\n      /______:___\                ::::.........::: /_________\:.........:::\n             :..:                                                       !CE\n-   -  - -- -----------[ n . i . r . v . a . n . a ]------------ -- -  -   -\n\n         presents today SCREAM-PAGER v1.0 coded&designed by iCE\n\n\n\n                               -[WHAT?!]-\n\n         This is a Pager door for /X coded in AmigaE language. \n\n                        - archive should include -\n\n\n\n                 · FiLE_iD.DiZ          [ file desc.   ]\n                 · FreePhone.jipegg     [ nrv advert   ]\n\n  bbs/doors/nirvana/SCREAMPAGER/\n                \n                 · SCREAMPAGER          [ main file    ]\n                 · SCREAMPAGER.doc      [ this file    ]\n\n  bbs/commands/bbscmd/\n\n                 · O.info               [ command file ]\n\n\n                            - installation -\n\n· copy everything within the doors/ dir into yar DOORS: drawer\n· copy S.info into yar <BBSPATH>:commands/BBSCMD/ drawer\n\n                              - features -\n\n · Cool anims&design!\n\n                               - history -\n\n v1.0  [ 13''th May 1997]  This release.\n\n\n\n\n                              - known bugs -\n\n · No known bugs yet.\n\n\n                             - future plans -\n\n\n · Line to callerslog\n · page again, comment to sysop or quit options\n · more anims\n \n \n\n\n                         - bugreports or support -\n\n If you find any bugs or want the latest version of SCREAMPAGER\n have a call to theese nirvana sites:\n\n  access denied       +46-0371-82218          WHQ         (nup: nirvana)\n  subzero             +44-01689-844244        UKHQ\n  boqwort             +44-01623-799318        UKHQ #2\n  illusions           +46-0371-80141          SHQ    \n  digit/\l-x          +31-0570-637050         The neatherlands dist site\n  moldavia            +46-0480-411887         Sweden dist site\n\n\n\n\n                                - members -\n\n                     -   iCE   -   SiMS   -   STALKER   -\n            -   tWEZZER   -   AleX   -   CREEP   -   FREAKY B   -\n\n\n                   - other doors available 13''th May 97 -\n\n                                   /X\n                                  ¯¯¯¯\n\n · NirvanaWall    v1.3  A fast wall with cursorkey-support and coloursupport.\n · NirvanaQuick   v1.0  Quick-logon door with cursor&hotkey support.\n · NirvanaBaud    v1.0  A baudchecker door.\n · NirvanaOrder   v1.2  A cool orderdoor, cursorkeys-support, many artists\n · NirvanaPager   v1.0  A pager-door with cool anim, callerlog-writing, .. \n · NirvanaAvail   v1.0  Sysop avail door.\n · NirvanaComment v1.0  Comment to sysop door.\n · NirvanaStat    v1.0  Status door.\n\n                                   DD\n                                  ¯¯¯¯\n · NirvanaQuick   v1.1  A cool qiucklogin door coded in 100% PURE ASM.\n\n\n\n\n\n\n\n                        - future doors coming soon -\n\n                                    /X\n                                   ¯¯¯¯\n                       · SCREAMCOMMENT\n                       · SCREAMSTAT\n                       · NirvanaReallylogoff\n                       · NirvanaAddBBS\n                       · NirvanaTime\n                       · NirvanaWho\n                       · NirvanaWHOF\n                       · NirvanaJoin\n                       · NirvanaLast15\n\n                                    DD\n                                   ¯¯¯¯\n                       · NirvanaStat\n                       · NirvanaAvail\n             \n               and ofcourse updates for already present doors.\n\n\n\n\n\n                 n i r v a n a    N E E D S   ! ! ! !\n\n                   DD coders\n                   S!X coders\n                   Tempest coders\n                   FAME coders\n                   /X coders\n\n                   ascii artists  (!!!!!!!!!!)\n\n                   traders        (!!!)\n                   headquarters\n\n                   PcB coders\n                   SystemX coders\n                   dESiRE coders\n\n\n                 PLEASE contact me if you''re interested!\n\n\n                                                            Signed: iCE\n\n','\n',char(10)),NULL,NULL,33186,6,0,NULL,NULL,'nrv_spa1_screampager','scan',1780048643);
