INSERT INTO door_catalog VALUES('nrv_wa12','NRV-WA12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NRV-WA12.LHA','nirvanawall12','XIM','nirvanawall12',NULL,'iCE.','NRV','|.__\_    \__\,  /___  /___.   97-02-15    | -|  _ \_   \    /|   \/    |-              | -l__/       \____|_________|- Nirvana-Wall |',replace('.---______---_____----__-------------------.\n|.__\_    \__\,  /___  /___.   97-02-15    |\n-|  _ \_   \    /|   \/    |-              |\n-l__/       \____|_________|- Nirvana-Wall |\n!CE/_________\     [NiRVANA]     v1.2      |\n|    coded&designed by iCE. Xim walldoor   |\n|for /X & S!X. Cool design. Bugfixed       |\n`------------------------------------------''\n','\n',char(10)),'NIRVANAWALL12.DOC',replace('\n\n-   -  - -- ---------------------------------------------------- -- -  -   -\n .____       ....  ______\n |    \______:..:__\    /____     ................____.    ................\n |     \     :\ :   \  /_\  /_____:::::::....  ::|    |____:::::::....  :::\n l__   _\    : \:     /|  \//      |::     ..  ::|  _ |    \:::     ..  :::\n   //__/ \_  :  \______l___________l::         ::l__/ l     \::         :::\n      /______:___\                ::::.........::: /_________\:.........:::\n             :..:                                                       !CE\n-   -  - -- -----------[ n . i . r . v . a . n . a ]------------ -- -  -   -\n\n         presents today Nirvana-wall v1.2 coded&designed by iCE\n\n\n\n\n -[WHAT?!]-\n\n eeeh? case you don''t now the purpose with a simple wall, you shouldn''t\n read this doc.\n\n\n\n- installation\n\n· copy the WALL.info icon into yar <BBSPATH>:BBSCMD/ directory.\n· copy everything within the doors/ dir into yar DOORS: drawer.\n\n\n\n- features\n\n · just a cool wall. No special functions\n\n\n\n- history\n\n v1.0  [14''th Jan 97] Just a simple wall without any features\n v1.1  [17''th Jan 97] Two small bugs fixed \n v1.2  [15''th Feb 97] Eehm. Sorry, but I found a BiG lame bug, but that''s \n                      history now.\n\n- known bugs\n\n · New lines since last doorcall is not in function.\n\n\n\n- future plans\n\n · fixing the known bugs.\n · A color option.\n · Anonymous option.\n · Real time color, backgroundcolor, bold, italic and underline switching.\n · Topadder function.\n · Sysops commands like Clear wall, Delete line.\n · A blacklist, case you dont want a special user to add.\n\n\n\n- bugreports or support\n\n If you find any bugs or want the latest version of nirvanawall\n have a call to nirvana whq:\n\n access denied       +46-371-82218       nup: nirvana\n NiRVANA homepage soon available.\n\n\n- other doors available 15''th Feb 97\n\n · Nirvanaorder v1.0  (working on it!, soon another release)\n\n\n','\n',char(10)),NULL,'auto-added',10275,4,0,NULL,NULL,'nrv_wa12','scan',1780048643);
