INSERT INTO door_catalog VALUES('nrv_lwal','NRV_LWAL.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NRV_LWAL.LHA',NULL,'XIM','-- /\/iR\/ANA presents ----------- 02/15/98',NULL,'iCE','NRV','_ [ LiGH| WALL ] v1.0 coded by iCE _',replace('-- /\/iR\/ANA presents ----------- 02/15/98\n           _\n     [ LiGH| WALL ] v1.0 coded by iCE\n _\n |he ultimate xim-wall.  Fast, simple and\n     no damn configuring. Preview pic\n          included in archive.\n-------------------------------------------\n','\n',char(10)),'light.doc',replace('                    n i r v a n a  p r e s e n t s\n \n                              02-15-98\n        ______                            ___          .\n       .\   _(_____. _______ ._______    _) /_______   l_\n       l_   \      |_________|_  ___/----|  _      /_   _\______.\n        /__________|)        |/________ _|--/_______|   \      _l\n                   :_________|     | ___)           l__________\\n                   ·               l___\\n \n                   light wall v1.0  coded by ice^nrv\n \n      a xim-wall for /X and S!X and other xim-compatible bbs-proggz\n         12 lines and the multicolor function with the cursorkeys\n               no boring anonymous option and no configuring\n                     simple and easy, just install it\n','\n',char(10)),NULL,NULL,7969,1,0,NULL,NULL,NULL,'scan',1780048643);
