ME: 20:59:11  ON NODE: 1\r\n\r\n  UPLOADER: Black Beard            LOCATION: mSTATION.servebbs.com    \r\n\r\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',152321,14,0,NULL,NULL,'nsv_modp','scan',1780048643);
INSERT INTO door_catalog VALUES('ns_jc10','NS_JC10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NS_JC10.LHA',NULL,'XIM','JoyComment.xim',NULL,'AtomiX','NS','|::::\°  __   \°  __   \°    __ \°  __   \| |::::/   //   /  /_/   /    /  \/  /_/   /| |:::/   //   /   _    /\___    /   _    /:|',replace('|::::____________________________________:|\n|::::\°  __   \°  __   \°    __ \°  __   \|\n|::::/   //   /  /_/   /    /  \/  /_/   /|\n|:::/   //   /   _    /\___    /   _    /:|\n|::/   //   /   //   /    /   /   //   /::|\n|::\__//___/\__//___/\_______/\__//___/:::|\n|:::::::::::::::::::::::::::::::::::::::::|\n|JoyComment V1.0 by AtomiX [/X 2.x & 3.x]:|\n|Release Date : 03-19-94 :::::::::::::::::|\n`-----------------------------------------''\n','\n',char(10)),'JoyComment.doc',replace('____________________________________________________________________\n::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nListing of archive ''RAM:NS-JC10.lha'':\nOriginal  Packed Ratio    Date     Time    Name\n-------- ------- ----- --------- --------  -------------\n     384     163 57.5% 05-Nov-92 06:24:40  bbs/Commands.info\n     384     163 57.5% 05-Nov-92 06:24:40  bbs/Doors.info\n     384     163 57.5% 05-Nov-92 06:24:40  bbs/doors/JoyComment.info\n    3771    1101 70.8% 16-Mar-94 15:38:00  bbs/doors/joycomment/JoyComment.doc\n     351     246 29.9% 16-Mar-94 14:52:06  bbs/doors/joycomment/JoyComment.doc.info\n   15328    7993 47.7% 16-Mar-94 15:41:12  bbs/doors/joycomment/JoyComment.xim\n     663     376 43.2% 16-Mar-94 15:24:42  bbs/doors/joycomment/JoyComment.xim.info\n    1328     338 74.5% 20-Feb-94 22:57:28  !Chaos_Line!.add\n     384     163 57.5% 05-Nov-92 06:24:40  BBS.info\n      47      47  0.0% 16-Mar-94 15:43:26  bbs/commands/BBS.CMD\n     384     163 57.5% 05-Nov-92 06:24:40  bbs/commands/BBSCmd.info\n    1054     463 56.0% 16-Mar-94 15:43:58  bbs/commands/bbscmd/C.info\n     440     173 60.6% 16-Mar-94 15:46:06  FILE_ID.DIZ\n-------- ------- ----- --------- --------\n   24886   11552 53.5% 16-Mar-94 15:46:26   13 files\n\n____________________________________________________________________\n::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\nJoyComment V1.0 Wed Mar 16 15:31:21 1994\n--------------\n\nV1.0 -   First Release\n\n____________________________________________________________________\n::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\nHow to Install ?\n----------------\n\nThis is a XIM Door\n\nCopy just all to the BBS i prepared it so that is working\nAutomaticaly ;^))\n\nOk Doki and now the Introducing or so ;))\n\nConfigure the "DOORS:JOYCOMENNT/JoyComment.xim.info"\n\n------------------------------------------------------------------------\nToolTypes:\n\n          SYSOPS=              <Add the MAX Number of Sysops you want>\n         SYSOP.x=              <Here the Name of the Sys/CoSysop>\n       COMMENT.x=              <"    "   Comment of the " ">\n\n------------------------------------------------------------------------\n\nso that''s all i you have a Problem with my Door/s then leave me\na mail or call me.\n\n____________________________________________________________________\n::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nWhat is JoyComment ?\n--------------------\n\nJoyComment is a MultipleComment Door for Sysops and Cosysops\nbla bla . i think you all now what is Comment Door..\n____________________________________________________________________\n::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\nFuture :\n--------\n\n      NO FEAUTURE hehe\n____________________________________________________________________\n::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nI noticed that a Lamer Called "VESUVIUS" Releasing /X Tools\nunder the Cover of NASA , he is *NOT* a member of the almighty\nNASA Team we kicked he''m for 4 Months, we can *NOT* warranty\nthat the Doors from he''m are Backdoor free use the "VES-" Doors on\nyour own Risk.. only the real NASA Releases are BD free "NS-"\nokay i hope we understand us my Friends.\nciao\n____________________________________________________________________\n::AtomiX::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n','\n',char(10)),NULL,'auto-added',19815,11,0,NULL,NULL,'ns_jc10','scan',1780048643);
