INSERT INTO door_catalog VALUES('ntfl101','NTFL101.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NTFL101.LHA','Freeloader','XIM','Freeloader','1.01',NULL,NULL,'fast XIM freeleech door with tooltype config to control byte limits and/or leech period. Also supports file flags from all dir utils!',replace('Needful Things Freeloader v1.01 /X 3.x door\nfast XIM freeleech door with tooltype config\nto control byte limits and/or leech period.\nAlso supports file flags from all dir utils!\n','\n',char(10)),'Freeloader.doc',replace('Freeloader v1.01	©1994 by Leland Gaunt - Needful Things - 508-663-6451\n\nFEATURES:\n\n	- Allows you to give a user access to free downloading,\n      regardless of ratio. Good for "donation" accounts\n	- Downloads & Bytes in user.data remain unchanged\n	- Can control access by bytes or dates.\n	- Full configuration from icon tooltypes.\n	- Freeload flagged files, works with any standard flagging util.\n	- Keeps records of total Freeload bytes in s:ntfl.db\n	- Sysop can view records database online.\n	- Callerslog messages report access & errors\n	- Written in ANSI C\n	- XIM door\n \nFiles included:\n\ndoors/FL/Freeloader.doc       \ndoors/FL/Freeloader.info\ndoors/FL/Freeloader\nCommands/BBSCmd/FL.info\n\nTo install the Freeloader door, copy the files into the appropriate\ndrawers on BBS: as shown above. Now you need to edit the Tooltypes\non doors/FL/Freeloader by opening a window to the directory, clicking\nonce on the Freeloader icon, and then selecting the infomation selection\nfrom the Icons Workbench menu.\n\nCurrently Freeloader supports the userame tooltype with 3 options.\nThese are edited on doors/FL/Freeloader.info\n\nM:x			Maxium bytes dl ''x'' is # of megabytes allowed\nS:MMDDYY	Date you can start Freeloading\nE:MMDDYY	Last day you can freeload\n\nThe tooltype is the users name, exactly as it is in user.data\n(upper/lower case counts) no extra spaces or quotes. A tooltype\nwith a username alone allows the user to Freeload with no restrictions\non how much or when he can Freeload. The username tooltype supports\n3 different restriction options, which should follow the username\nas in this example:\n\nLeland Gaunt=M:500,S:072194,E:083094\n\nthis tooltype entry would give me Freeload access starting on July 7 1994\nand ending on August 30 1994. It also limits me to a Maximum of 500 megabytes.\nEach option must be followed by a colon ":" and then the value.\neach option must be seperated by a comma '',''. The dates must be in the format\nMMDDYY. You can include/exclude any combinations of options you like.\nFor instance if you leave out the byte specifier M then there is no byte limit\nfor that user. or if you put an S start date but no E end date, then after the\nstart date the user can Freeload until you remove his tooltype entry or add an\nend date. You can add bytes in as little as 1 meg increments to the M: option \nin the users tooltype to extend his byte limits or adjust the date in the E:\noption to extend the users time.\n\nThere are several tooltype examples on doors/FL/Freeloader.info\n\nUSAGE:\n\nWhen the user runs the FL door he will be greeted and shown his\naccess limits if he has any and then, if his access restrictions\nare met, he is allowed to download regardless of his ratio\nIn addition the Sysop, as well as any user with access of 255, can view\nthe records databased, and will be asked if they''d like to do so everytime\nthe start Freeloader.\n\n\nFuture possible features:\n\nSysop online function to remove/reset users records... \ncurrently you must delete the 48 byte block associated with \nthe user from s:ntfl.db if you really want to delete his dl record.\n\nKeep record of users last access.\n\n??? Let me know your ideas! \n','\n',char(10)),NULL,'auto-added',18858,5,0,NULL,NULL,'ntfl12','scan',1780048643);
INSERT INTO door_catalog VALUES('ntfl12','NTFL12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NTFL12.LHA','Freeloader','XIM','Freeloader','1.2',NULL,NULL,'manages ''leech'' and ''subscription'' accounts with new sysop menu and Faster C code! <SOCIAL-DIZEASE>-<4-NODES>',replace('Needful Things'' Freeloader v1.2 /X XIM door\nmanages ''leech'' and ''subscription'' accounts\nwith new sysop menu and Faster C code!\n[1;32;44m<SOCIAL-DIZEASE>-<4-NODES>[0m','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                                                .------''\n             `------------------------------------------------''\n','\n',char(10)),NULL,'auto-added',21439,6,0,NULL,NULL,'ntfl12','scan',1780048643);
INSERT INTO door_catalog VALUES('ntr_amf','NTR-AMF.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NTR-AMF.LHA','AMF-ENHANCER','XIM','AMF-ENHANCER',NULL,NULL,'NTR','/~¯ \\ ___/  / \\ ___/__ \\/~¯  \\   \\ /  /  /__/__ /   / ¬\  \  _/_ /   / /  /\ /__/__/___ ,/____/_ //___\  ¯¬\___/_/__/ /',replace('    __/\_________/\________/\  ___/\___/\\n   /~¯ \\ ___/  / \\ ___/__ \\/~¯  \\   \\\n  /  /  /__/__ /   / ¬\  \  _/_ /   / /  /\\n /__/__/___ ,/____/_ //___\  ¯¬\___/_/__/ /\n \__\__\___\/\____\_\/\____\___/\__\_\__\/\n  ~~~~~~~~~~\/~~~~~~~\/~~~~~\__\/~~~~~~~~\n    [ NEUTRON /X iNSPiRATiON BRINGS YA ]\n\n      eNHANCEMENT fOR aMFETAMIN v2.21\n            (c) tHE sILENCER/tDC\n NOW YOU CAN ADD RANDOM LASTCALLER LOGOS !\n[ RELEASED AT COSMIC CIRCUS - NEUTRON WHQ! ]\n','\n',char(10)),'AMF-ENHANCER.guide',replace('@DataBase The Dox for Neutron''s AMFETAMIN ENHANCER\n\nCopyright (c) 1995 Gravedancer of Neutron\n\n@Remark $VER: Neutron Amfetamin Enhancer v1.o\n@Remark AmigaGuide database for the Neutron Amfetamin Enhancer v1.o Dox\n\n@node MAIN "Neutron Amfetamin Enhancer v1.o by Gravedancer of Neutron"\n\n      ______                      ____ _ _____________________\n      \____ \___________________,/   /_________  \_____ \____ \_____\n        /  \ \    \_  _____/    /   /    /  __/ _/    /  \   \ \    \_\n       /    \ \    /,____)__ __/   /   \/   \   \_   /    \   \ \-gD /\n      /______\____/_________\_____/_____\____\___/________/____\____/\n\n                     [. nEUTRON - /X - iNSPiRATiON .]\n\n                          [ Amfetamin Enhancer ]\n\n---------------------------------------------------------------------------- \n\n         >>> C·O·N·T·E·N·T·S  O·F  D·O·C·U·M·E·N·T·A·T·I·O·N <<<\n\n                         @{"      Introduction      " Link Cap01}\n                         @{"      Requirements      " Link Cap02}\n                         @{"      Installation      " Link Cap03}\n                         @{"      The Creditz!      " Link Cap04}\n                         @{"       Greetings!       " Link Cap05}\n                         @{"   How to Contact me?   " Link Cap06}\n\n         ---------------------------------------------------------\n         Neutron Amfetamin Enhancer v1.o by Gravedancer of Neutron\n         ---------------------------------------------------------\n       The Documentation has been written by Gravedancer of Neutron\n\n@endnode\n@node Cap01 "Introduction"\n  =======================================================================\n\n                Well ... let me tell ya a little story ...\ni am using silencer''s amfetamin  last  callers  door, and i was happy !!!\ntill mogue! presented his board style including  five  genius  lastcaller\nlogos ...  and i  wanted to use them !!! then my problem  was  solved  by\nslac/decision who  wrote  the ampfix utility which allows to fix a banner\nto amfetamins bulletin ...  but  there  were  FIVE  logos  from  -mO! !!!\nso  i  finally  picked  up  my  golded and started my own "ampfix" called\n                        Neutron Amfetamin Enhancer\nit  features  random  last  caller  logos  (via mci)  so  i have included\nmogue''s          logos             as                an       example ...\n\n  =======================================================================\n@endnode\n@node Cap02 "Requirements"\n  =======================================================================\n\n  - an  Amiga Model (500/600/1000/1200/2000/2500/3000/4000/CDTV/CD³²)\n  - the installed Version of OS\2, OS\3 or higher\n    (Soft- or Hardware Version)\n  - AmiExpress V2.xx , v3.xx or higher. And surely S-Express hehe.\n\n  - installed (and of course running) amfetamin (c) the silencer\n\n  =======================================================================\n@endnode\n@node Cap03 "How to install"\n  =======================================================================\n\nmix the included bull.txt to your bbs:bull.txt  and  the  logoffx with\nevery logoffx in your bbs:commands/syscmd ... now copy amf-enhancer to\nyour             bbs:utils               directory      and wonder ...\n\n  =======================================================================\n@endnode\n@node Cap05 "Greetings go to the following guys:"\n  =======================================================================\n\nfirst of all i''d like to greet all the great names in /X programming like ...\n\n                               Dr.Dre!/tRSi\n                               ByteAndi/tRSi\n                                SieGeL/tRSi\n                                 Spy/tRSi\n                               Delta-X/tRSi\n                                 2fAST/aVT\n                               kNUCKLES/aVT\n                                 sTc/TaSK\n                                CALYPSO/GOD\n\n          next i''d like to say hello to the best ascii heroes ...\n\n                          mOGUe!/P¡MoK^-aRTcORE!\n                            2fAST/aC!^nEON^hLM\n                   mR.vAIN/bONZAI/SUNFLEX ¡NC/aRT-cORE!\n                       aLL oTHER mEMBAS oF aRT-cORE\n\n                and last but not least the real greetz ...\n\n                          GENERAT¡ON/nTR^pDY^iLS\n                                  DAN/nTR\n                                M¡CK/bP^dCN\n                              MAGNET¡C/bP^dCN\n                              eCS^mARIO/tRS¡\n                              sPELLF¡RE/tRS¡\n                           dJ mELLOWNOISE/¡NFECT\n                               dONALD/sHOOT\n\n          [. hOPE tO sEE yA sOON oN tHE cOSM¡C c¡RCUS mEET¡NG .]\n\n  =======================================================================\n@endnode\n@node Cap06 "How to contact me:"\n  =======================================================================\n\nyou can find me on this nice bbs ...\n\n                                                         /\\n________________________________________________ _______/ \\________________\n\_______       \________   /  _________________ Y _____/   \\______        /\n  /     \______/_      /   \________    \      \_/     \____/      \______/_\n /-gD   /        \    /     \      7     \      7      |   /       /        \\n \________________\_________/____________/______l______|___\_________________\\n\n_________________/\______________________________________,____________________\n\_______        / \\___________     \_____       \_      /    _/  ___________/\n  /     \______/_  \\/      __/    _/     \______/_     /      \_______    \\n /      /        \__/       \       \_    /        \  _/        \     7     \\n \________________\ |________\_______/______________\___________/___________/\n              ______|\n\n            [«» nEUTRON! wHQ «» pRODIGY gHQ «» iLLUSION eHQ «»]\n\n                  «[» sYSOP : gENERATION/nTR^pDY^iLS «]»\n\n         »[« eCS & mARIO xXx 2fAST xXx cAOS xXx dAN xXx mR.bIG »]«\n\n  =======================================================================\n@endnode\n@node Cap04 "The Creditz:"\n  =======================================================================\n\n              Main Idea, Coding (about five minutes of work)\n                        The Gravedancer of Neutron\n\n                        Supplied Last Caller Logos\n                                Mogue!/aC!\n\n                              Message to -mO!\n   sorry, ich hatte keine Zeit zu fragen, ob ich die logos nehmen darf !\n\n  =======================================================================\n@endnode\n','\n',char(10)),NULL,'auto-added',57112,11,0,NULL,NULL,'ntr_amf','scan',1780048643);
