INSERT INTO door_catalog VALUES('ntr_di','NTR-DI.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NTR-DI.LHA','nTR-dIRiNTER','XIM','exe.-l0S-eND0S-bBS-.exe',NULL,NULL,'NTR','____  \_ _  /_\ _/:__ _ _:_  \____ \\___  \_ /   / \_/  \_\ :..   .:/  _/ _/  \_ /   / /___/__      /___ :__:__\   \______//___/',replace('______ ______ ____........___ _____ ______\n____  \_ _  /_\ _/:__ _ _:_  \____ \\___  \_\n   /   / \_/  \_\ :..   .:/  _/ _/  \_ /   /\n  /___/__      /___ :__:__\   \______//___/\n_/  gD!/______/NTr\/:..:   \___\  /___\     \n--------------------------------------------\nnEUTRON pRESENTS a rEVOLUTION fOR aMIeX 4.X!\ntHE nTR-dIRiNTERFACE iS tHE "dIFFERENT" dIR-\nsCANNER dOOR fOR yOUR bULLETIN bOARD sYSTEM!\n','\n',char(10)),'nTR-dIRiNTER.dOC',replace('                            _______ __                 .:.....  _\n _____________________  ____\      |\_\________________ :    __ /______________\n_\  \___   ___\  __/ /-|.    \_    |  _______/\__  ___/______\/__\  \___      /\n\______/   \________/  |_\_________|     \_________      /\  /\/\______/     /\n      /_____/  \__________\         \_____\       /     /_ \/         /_____/\n                                                 /_____/ \   ....:. -tre!/(!\n                                                                 :\n                      Neutron AmiExpress Inspiration\n                           presents in late 1995\n                        the alternative/ultimative\n\n           FileScanner for AmiExpress 4.x - called DirInterface\n\n.----------------------------------------------------------------------------.\n|                            Table of contents                               |\n`----------------------------------------------------------------------------''\n\n Features table, installation, usage, credits, more to come? and registration\n\n.----------------------------------------------------------------------------.\n|                             Features table                                 |\n`----------------------------------------------------------------------------''\n\nWhy  look  all the filescanners equal ??? Why confuse the caller with  endless\nlists of file_id''s, filenames, filesizes and other stuff ??? Don''t  you  never\nget nerved when the last lines of a file_id are beyond the last line  of  your\nscreen and you have to turn to next page to see the rest of it ???  This  door\noffers you smart display of all needful information in an effective  and  nice\nlooking way, too. It is the most easy to use door of its kind, but with nearly\nall elements a filescanner needs: displays filename, filedate, filesize, file-\nstatus, file_id. The user is able to flag files. So! take a look a the preview\npicture and wonder ...\n\n.----------------------------------------------------------------------------.\n|                              Installation                                  |\n`----------------------------------------------------------------------------''\n\nStep One - Copy all files to their drawers.\n\nStep Two - If you have allready a file S:RMS.CONFIG then add my one to your\n           one.\n\n.----------------------------------------------------------------------------.\n|                                  Usage                                     |\n`----------------------------------------------------------------------------''\n\nNothing to say, but: FR starts DirInterface with last uploaded file and F with\nthe first one. In this public release the N -x, N S U and N T U  commands  are\nnot included. So: Register it ...\n\n.----------------------------------------------------------------------------.\n|                          The Credits for this                              |\n`----------------------------------------------------------------------------''\n\n                Idea, Coding ... Gravedancer/Neutron^Shoot\n\n.----------------------------------------------------------------------------.\n|               More to come ? What''ll bring the future ...                  |\n`----------------------------------------------------------------------------''\n\nOff course there will be a interpretation of the thing  called  sent-by-line.\nBut this will only work  if  you  use  the  file-id  door  by  byteandi/trsi!\nMaybe  i  decide  to  include  the  following:  search  mode,  nuke/fake  ...\n\n.----------------------------------------------------------------------------.\n|                           Registration Notice                              |\n`----------------------------------------------------------------------------''\n\nAs i said above you have to register this door, but it costs just a call to a\nbbs where you find me ...\n','\n',char(10)),NULL,'auto-added',73023,5,0,NULL,NULL,'ntr_di','scan',1780048643);
INSERT INTO door_catalog VALUES('ntr_dir','NTR-DIR.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NTR-DIR.LHA','NTR-DIRSTYLER','XIM','NTR-DIRSTYLER',NULL,NULL,'NTR','\ \/ /\_ __\ |  /\_  ___  _ \ __ /\ \/ / /  \ \/ __)/ l_ \ |  |/ __/_/ l_ \/  \ \ /  \   \ l  \     \|  /  \  \\     \ \   \',replace('  __  /\__/\_________/\___/\____/\____  /\\n  \ \/ /\_ __\ |  /\_  ___  _ \ __ /\ \/ /\n  /  \ \/ __)/ l_ \ |  |/ __/_/ l_ \/  \ \\n /  \   \ l  \     \|  /  \  \\     \ \   \\n \__/\__/____/_____/l__\__/\  /_____/_/\__/\n============================\/==============\n[ [ NEUTRON /X DIVISION ] [ [ BRINGS YOU ] ]\nTHE ULTIMATE DIRSTYLE UTILITY FOR YOUR BOARD\nFULLY SYSOP AND USER CONFIGURABLE OUTPUT DSG\n','\n',char(10)),'NTR-DIRSTYLER.doc',replace('                                _ __ ____\n       _______________________   __     /__   _____   ________   ______\n     __\___  \_   ___   /    /____    ____/___\__  \_/   ____/___\___  \_\n    /    /    /   \____/    /    /    /    /  __/ __/    /    /    /    /\n   /____/    / \________________/_________/___\    \_________/____/    /\n       /____/                                  \____\-jD!        /____/\n\n                   Documentation for Neutron-DirStyler !\n                  ---------------------------------------\n\nIntroduction:   Just a Dir-Styler, nothing special.\n                \nRequirements:   Any Amiga Computer with installed/working /X.\n                \nInstallation:   Copy the NTR-DIR.info to your syscmd drawer.\n                Copy all from doors/ to your doors:.\n                \n                This Tool must be run after every upload so make sure\n                that it is run in your dupechecker (Task,SuperDupe,...)\n                or rename the NTR-DIR.info to EXAMINE1.info\n\n                This tool needs a file RMS.config in s: !!! If you have\n                allready such a config add the supplied to yours otherwise\n                copy s/ to s: ... have fun!\n\nRegister-info:  If you want to register call the COSMIC CIRCUS and leave\n                me a mail. Maybe there will be updates in the future and\n                as allways the updates are restricted to  my  registered\n                users.\n\nThe Future:     The registered version offers a "MAKE-YOUR-OWN-DESIGN"-\n                feature! That means you are able to design a GLOBAL output\n                and a "SENT" replacement is included so that every user can\n                design HIS OWN SENT-BYLINE.\n','\n',char(10)),NULL,'auto-added',41040,1,0,NULL,NULL,'ntr_dir','scan',1780048643);
INSERT INTO door_catalog VALUES('ntr_ds2','NTR-DS2.LZX','~/Code/amiexpress_doors/Archives/AmiExpress/NTR-DS2.LZX',NULL,'XIM','NTR-DIRSTYLE',NULL,NULL,'NTR',NULL,NULL,NULL,NULL,NULL,'auto-added',37517,0,0,NULL,NULL,'ntr_ds2','scan',1780048643);
INSERT INTO door_catalog VALUES('ntr_fd2','NTR-FD2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NTR-FD2.LHA','NTR-FRONT','XIM','NTR-FRONT',NULL,NULL,'NTR','\ \/ /\_ __\ |  /\_  ___  _ \ __ /\ \/ / /  \ \/ __)/ l_ \ |  |/ __/_/ l_ \/  \ \ /  \   \ l  \     \|  /  \  \\     \ \   \',replace('  __  /\__/\_________/\___/\____/\____  /\\n  \ \/ /\_ __\ |  /\_  ___  _ \ __ /\ \/ /\n  /  \ \/ __)/ l_ \ |  |/ __/_/ l_ \/  \ \\n /  \   \ l  \     \|  /  \  \\     \ \   \\n \__/\__/____/_____/l__\__/\  /_____/_/\__/\n============================\/==============\n NEUTRON FRONT AND WHO RELEASE II - PUBLIC!\n THIS  IS THE FIRST AND ONLY PUBLIC VERSION\nOF RELEASE 2 FROM THE BEST FRONT^WHO FOR /X!\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 20:18:08  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',70242,1,0,NULL,NULL,'ntr_fd2','scan',1780048643);
INSERT INTO door_catalog VALUES('ntr_fd21','NTR-FD21.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NTR-FD21.LHA','List','XIM','List',NULL,NULL,'NTR','/~¯ \\ ___/  / \\ ___/__ \\/~¯  \\   \\ /  /  /__/__ /   / ¬\  \  _/_ /   / /  /\ /__/__/___ ,/____/_ //___\  ¯¬\___/_/__/ /',replace('    __/\_________/\________/\  ___/\___/\\n   /~¯ \\ ___/  / \\ ___/__ \\/~¯  \\   \\\n  /  /  /__/__ /   / ¬\  \  _/_ /   / /  /\\n /__/__/___ ,/____/_ //___\  ¯¬\___/_/__/ /\n \__\__\___\/\____\_\/\____\___/\__\_\__\/\n  ~~~~~~~~~~\/~~~~~~~\/~~~~~\__\/~~~~~~~~\n    [ NEUTRON /X iNSPiRATiON BRINGS YA ]\n\n   NEUTRON FRONT DOOR PUBLIC VERSION 2.1\n      FAAST, NICE DESIGN, BACKDOORFREE\n  BUGFIXED! BUGFIXED! BUGFIXED! BUGFIXED!\n[ RELEASED AT COSMIC CIRCUS - NEUTRON WHQ! ]\n','\n',char(10)),'NTR-FRONT.guide',replace('@DataBase Neutron FRONT^WHO Dox\n\nCopyright (c) 1995 Gravedancer of Neutron\n\n@Remark $VER: Neutron FRONT^WHO v2.o public\n@Remark AmigaGuide database for the FRONT^WHO Dox\n\n@node MAIN "Neutron FRONT^WHO Dox (c)1995 Gravedancer of Neutron"\n\n      ______                      ____ _ _____________________\n      \____ \___________________,/   /_________  \_____ \____ \_____\n        /  \ \    \_  _____/    /   /    /  __/ _/    /  \   \ \    \_\n       /    \ \    /,____)__ __/   /   \/   \   \_   /    \   \ \-gD /\n      /______\____/_________\_____/_____\____\___/________/____\____/\n\n                     [. nEUTRON - /X - iNSPiRATiON .]\n\n               [. bRINGS yA tHE uLTIMATE fRONTDOOR fOR /X .]\n\n\n---------------------------------------------------------------------------- \n\n         >>> C·O·N·T·E·N·T·S  O·F  D·O·C·U·M·E·N·T·A·T·I·O·N <<<\n\n                         @{"      Introduction      " Link Cap01}\n                         @{"      Requirements      " Link Cap02}\n                         @{"      Installation      " Link Cap03}\n                         @{"       The Header       " Link Cap07}\n                         @{"    How To Register?    " Link Cap08}\n                         @{"       Greetings!       " Link Cap05}\n                         @{"   How to Contact me?   " Link Cap06}\n                         @{"   = == History! == =   " Link Cap09}\n\n         ---------------------------------------------------------\n                   Complete Docs for Neutron FRONT^WHO!\n         ---------------------------------------------------------\n       The Documentation has been written by Gravedancer of Neutron\n\n@endnode\n@node Cap01 "Introduction"\n  =======================================================================\n\n                  The Neutron FRONT^WHO Door features ...\n\n        ... nice design\n         ... faast ^ optimized with rexxmasher\n          ... shows sysop is available/or not\n           ... shows actual time\n            ... can display a header (logo/animation)\n             ... supports one node systems too\n              ... included WHO bbs-command\n               ... other front^who doors show "uPLOADING ..." oR sTH.\n                   lIKE tHIS ... tHIS iS rUBBISH !!!!!!!!!!!!!!!!!!!!\n                   nEUTROn fRONT^wHO sHOWS "UL: NTR-FD20.LHA" !!!!!!!\n\n  =======================================================================\n@endnode\n@node Cap02 "Requirements"\n  =======================================================================\n\n         To install FRONT^WHO you must have the following things:\n\n  - an  Amiga Model (500/600/1000/1200/2000/2500/3000/4000/CDTV/CD³²)\n  - the installed Version of OS\2, OS\3 or higher\n    (Soft- or Hardware Version)\n  - AmiExpress V2.xx , v3.xx or higher. And surely S-Express hehe.\n\n  =======================================================================\n@endnode\n@node Cap03 "How to install FRONT^WHO:"\n  =======================================================================\n\nfirst  copy  all in  c to c:, all from libs to libs:, all from doors to doors:\nand   all   from commands/bbscmd  to  your  bbs:commands/bbscmd  directory ...\nafterwards copy all from commands/syscmd to your syscmd drawer !!!!!!!!!!!!!!!\nthen start rpstart in your user-startup. the next  step  depends  on  the fact\nwhether you are already using an rms door or not ... if not just  copy s to s:\nbut if you run another rms''ed door load up your editor and add the  lines from\nmy       rms.config     to      your     rms.config      ...     thats all ...\n\n  =======================================================================\n@endnode\n@node Cap05 "Greetings go to the following guys:"\n  =======================================================================\n\n           gENERATIOn (*) dAN (*) mICK (*) hOMEBOY (*) mAGNETIC\n          eCs (*) mARIO (*) dONALD (*) dJ mELLOWNOISE (*) rAINMAN\n      jORDAN (*) sLIME (*) pRIMUS (*) fURY (*) jAKE (*) rEBEL (*) dOC\n\n            aND lAST bUT nOT lEAST mY hELD iN tHE eRDBEERFELD -\n                  dER mEISTER oF tHE aSCII^aNSI sCENE !!!\n                                m O G U e !\n\n  =======================================================================\n@endnode\n@node Cap06 "How to contact me:"\n  =======================================================================\n\nyou can find me on this nice bbs ...\n                   ________ __                          _____ __ __\n  _____ _____    _/        \__)_____      _____ __    _/    _/  |  \_____\n_/    _/     \___\_  |  |  _/_/     |   _/     (__)___\_  l_\_  | _/     \_\n\_  l_\_  |  _/   \_ |  |  | \_  l__|   \_  l__| _/     \_|__|  | \_  l___/\n |  |__|  |  | l___/ |  |  |  |  |__     |  |__| \_  l___/l  |  |  l__   |\n |  l  |  |  |_   l__|__|  l__|  l  |    |  l  |  |  | l__   l_____|  |  |\n l__   l_____| |  |     `--''  l__   |    l__   l__|  |    `--''     l__   |\n<-- `--''- --l__   |- - -- -÷2F÷- `--''-- - --`--''--l__|---- --- ---- --`--''->\n               `--''\n        pRODIGY gHQ «» nEUTRON wHQ «» iLLUSION wHQ «» nEW^dEAL gHQ\n\n                       sYSOP: gENERATION/pDY^nTR^iLS\n\n          cOSYSOP: 2fAST «» cAOS «» dAN «» mR.bIG «» eCS & mARIO\n\n    2 * cREDITS fOR mAJORS! 3 * cREDITS fOR mAJORS fROM yOUR oWN gROUP!\n\n                   - -+-rUNNING aMIEXPRESS v4.xX !-+- -\n\n           - -+-sUPPORTING dA lATEST aMIGA & cONSOLE sTUFF-+- -\n\n  =======================================================================\n@endnode\n@node Cap07 "The Header"\n\n  =======================================================================\n\nas  you  know  from  the features table, NTR-FRONT is able to display a header\nfile  before  showing  the node stats ... if you want to use this  nice  bonus\nfeature of this door just save an ansi/ascii under the following name !!!!!!!!\n\n                      [ BBS:DOORS/NTR-FRONT/HEADER ]\n\nmake sure that your header has an screen cleare like CTRL-L on its beginning !\nin this demo release the file header must exist ... but if you want no  header\nuse           the     supplied        file    ...      thats           all ...\n\n  =======================================================================\n\n@endnode\n@node Cap08 "How to register"\n\n  =======================================================================\n\nthis  is  the public release of the ntr-frontdoor utility for /X. All upcoming\nupdates are  only available  to registered users. for example the regd version\nwill offer 10 nodes support ... this door is  callware! this  means  that  you\nhave  to call  COSMIC CIRCUS and upload some nice things to get a personalized \nversion of this kuhl tool ... by the way: you have to find out the numbers^pws\nfor  cosmic circus  on your own ... just leave there a mail to gravedancer !!!\nthe contents of this mail must be : your name (as configured in acp.info)\n                                     bbs name (as configured in acp.info)\notherwise    the    registered    version    will  not  run on your system ... \n\n  =======================================================================\n\n                      Features of the full version :\n\n        ... 10 node support\n         ... different designs\n          ... a private node management system ...\n\nall  updates  will  be  only acessable for registered user, so if ya like it :\nplease register. we demand no money for registering, cause this is not kuhl !!\n\n  =======================================================================\n\n@endnode\n@node Cap09 "The History ..."\n\n  =======================================================================\n\nV1.0 initial release\nV2.0 added feature: show current upload transfer file (UL:NTR-FD21.lha)\nV2.1 some really big bugs fixed\n\n  =======================================================================\n\n@endnode\n','\n',char(10)),NULL,'auto-added',57946,5,0,NULL,NULL,'ntr_fd21','scan',1780048643);
