INSERT INTO door_catalog VALUES('ntr_join','NTR-JOIN.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NTR-JOIN.LHA','MAKEDATA','XIM','MAKEDATA',NULL,NULL,'NTR','__cDr\_ __/_ | _/_____ /__ \_____\e^d___ _/ \ _/  _/  / !   \   \/ _/ _/ \/  / \ _/ \  \\  \____/-------\---\-\____\---/  \\  \',replace('       ________._____\_____________\n  __cDr\_ __/_ | _/_____ /__ \_____\e^d___\n_/ \ _/  _/  / !   \   \/ _/ _/ \/  / \ _/\n\  \\  \____/-------\---\-\____\---/  \\  \\n \--\___\ - n  E  U  T  R  O  n - /____\___\\nNEUTRON JOIN-A-CONF DOOR FOR AMI EXPRESS 4.X\nINCLUDING NEVER SEEN FEATURES FOR A "J" CMD!\n','\n',char(10)),'NTR-JOINCNF.doc',replace('         _____    _____   ____      ________ _____    _____    _____\n       __\_   \___\_   \_/   /\_____\_     /\\_   \___\_   \___\_   \_\n      /   /    /   /____/   /   _    /____  __/  __/   /    /   /    /\\n     /   /    /   __/\_/   /    /\_  \_  /  \    \    /    /   /    /  \\n    /___/   ___  /   ___  /    /  /   /\/___/   ___  /   _____/    /   /\n    \  /____/\ \_____/\ \_____/  /___/  \  /____/\ \_____/\  /____/   /\n     \_\      \_\      \_\       \      /\_\      \_\      \_\       /\n        \_____/  \_____/  \_____/ \____/    \_____/  \_____/  \_____/sYz\n\n[ ] []  [] [] NEUTRON - SOFTWARE SUPERIOR BY DESIGN & QUALITY [] []  [] [ ]\n\n              [ ] []  [] [] NTR JOIN CONFERENCE [] []  [] [ ]\n\n[ o1 ] ABOUT THIS TOOL\n\nWEEKS AGO THERE WAS THE HOMELESS MEETING IN THE RHEINAUE IN BONN. FIRST: IT\nWAS GREAT! I MET THERE LOTS OF NICE DUDES UNDER THEM H20! HE HAD THE IDEA 2\nCOMBINE A JOIN CONFERENCE DOOR WITH SOME STATISTIC DATA DOOR ABOUT HOW MUCH\nFILES / BYTES HAVE BEEN UPLOADED ON A DAY TO EACH CONFERENCE. WELL - AS YOU\nCAN SEE: HERE IT IS ...\n\n[ o2 ] INSTALLATION\n\nJUST COPY THE ICONS TO THEIR DRAWERS AND THE WHOLE NTR-JOINCNF DRAWER TO UR\nDOORS: DIRECTORY. THEN YOU HAVE TO COPY THE FILE RMS.CONFIG TO YOUR S: DIR.\nIF THERE ALLREADY EXISTS A FILE UNDER THAT NAME YOU HAVE TO APPEND THE SUP-\nPLIED TO YOURS. IF YOU CHANGE THE "NAME" OF THE EXAMINE PART OF  THIS  DOOR\nFROM EXAMINE1 TO EXAMINE2 OR EXAMINE3 AND SO ON YOU HAVE TO CHANGE THE NAME\nIN THE RMS.CONFIG TOO. THATS ALL ...\n\n[ o3 ] MAKING THE DATA FILE\n\nBEFORE YOU CAN THE RUN THE DOOR FOR THE FIRST TIME YOU HAVE TO  CREATE  THE\nDATA FILE BY YOURSELF. LOAD IT UP INTO YOU FAVOURITE TEXT EDITOR. AT  FIRST\nYOU HAVE TO WRITE THE NAME FOR EACH CONFERENCE ENDING WITH A RETURN,EXAMPLE\nAS FOLLOWS:\n\n[CUT!]\nAMIGA\nDEMOS\nMODULES\n[CUT!]\n\nTHEN YOU HAVE TO ADD FOR EACH CONFERENCE TWO LINES WITH AN "0", EXAMPLE  AS\nFOLLOWS:\n\n[CUT!]\n0\n0\n0\n0\n0\n0\n[CUT!]\n\nTHAT IT WAS ... IN THE REGISTERED VERSION YOU WILL GET AN TOOL  WHICH  DOES\nSAME AS ABOVE STATED BASED UPON THE INFORMATION IN THE CONFCONFIG.INFO  ...\n\n[ o4 ] TECHNICALS - OR: HOW THIS SHIT WORKS?\n\nAS YOU CAN SEE THERE IS A EXAMINE DOOR WHICH COUNTS FOR EACH CONFERENCE THE\nUPLOAD FILES AND BYTES OF A DAY. AFTER THE FIRST UPLOAD OF A DAY  THE  DATA\nWILL BE RESET. IN THE DOOR: WELL USE CURSOR UP / CURSOR DOWN  TO  MOVE  THE\nPOINTER, RETURN TO SELECT AND SPACE TO QUIT. OFF COURSE IT  SHOW  ONLY  THE\nCONFERENCES THE USER HAS ACCESS TO.\n\n[ o5 ] REGISTRATION\n\nTHE EVALUATION VERSION / PUBLIC VERSION IS LIMITED TO 3 CONFERENCES. IF YOU\nWANT TO REGISTER YOU HAVE TO CALL COSMIC CIRCUS BBS. GO THERE INTO THE NTR-\nREGISTER CONFERENCE AND USE THE DOOR "REGISTER". THE DOOR TELLS YOU ALL IM-\nPORTANT THINGS ABOUT REGISTERING. BY THE WAY: YOU PAY ONLY ONCE THE  AMOUNT\nOF 10 GERMAN MARKS / 10 AMERICAN DOLLARS AND YOU WILL GET ALLWAYS AS  FIRST\nNEW VERSIONS, UPDATES, BETA-VERSIONS OF UPCOMING TOOLS AND FULL SUPPORT !!!\n\n[ o6 ] CREDITZ\n\n                CODING WAS DONE BY ... GRAVEDANCER/NTR^SHT\n             THE DESIGN WAS CREATED BY ... RAMIS!/NTR^SHT^RNG\n                 THANX TO ... NOISY BELCH (FOR SOME HELP)\n                      AND THE IDEA CAME FROM ... H2O!\n\n[ o7 ] HOW TO CONTACT\n\n                  /\                        . __ .\n      ______ ____/__\_________   _/\  _____ :_\/_:______       sHOOt eHq\n    _/ ____/_\  /    \  / ___/____  \/   _/_|\/\/| ____/____ nEUTROn wHq\n    \   \     \/      \/_____    /  \/      :/   |  \      / pRODIGy gHq\n     \--._____/\      /\________/____\      X    |--._____/ iLLUSIOn wHq\n             /__\____/__\             \    /|____|        _:__ _   _\n                 \  /                  \  /                |       /\n                  \/         . __ .     \/                 |      /\n                    _______  :_\/_: _________  _______ ____|_    /____\n                  _/ _____/__|\/\/|_\___    /_/ _____/_\__ |    / ___/____\n                  \   \      :/   :   _/  _/_\__ \      \/ !   /_____    /\n                   \--.______X    :___\        /-.______/\    /_________/\n                          cDr!____!e^d \      /           \  /\n                                        \    /             \/\nSORRY, BUT YOU HAVE TO FIND THE # ON YOUR\  /OWN ! BUT I AM SURE THAT YOU CAN\nFIND THEM - IF YOU WANT !                 \/\n','\n',char(10)),NULL,'auto-added',73973,1,0,NULL,NULL,'ntr_join','scan',1780048643);
INSERT INTO door_catalog VALUES('ntr_lc','NTR-LC.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NTR-LC.LHA','NTR-LASTCALLERS','XIM','NTR-LASTCALLERS',NULL,NULL,'NTR','\ \/ /\_ __\ |  /\_  ___  _ \ __ /\ \/ / /  \ \/ __)/ l_ \ |  |/ __/_/ l_ \/  \ \ /  \   \ l  \     \|  /  \  \\     \ \   \',replace('  __  /\__/\_________/\___/\____/\____  /\\n  \ \/ /\_ __\ |  /\_  ___  _ \ __ /\ \/ /\n  /  \ \/ __)/ l_ \ |  |/ __/_/ l_ \/  \ \\n /  \   \ l  \     \|  /  \  \\     \ \   \\n \__/\__/____/_____/l__\__/\  /_____/_/\__/\n============================\/==============\n NEUTRON /X DiViSiON HITS YAR FACE WITH DA\n  BEST LAST-10-CALLERS UTILITY EVER CODED\n       FOR AMIEXPRESS 4.X OR HIGHER.\n    LOTS OF FUNCTIONS - CREATE YOUR OWN\n OUTPUT DESIGN OR USE ONE OF THE SUPPLIED!\n       INCREDIBLE FAST! NICE EXTRAS!\n','\n',char(10)),'NTR-LASTCALLERS.doc',replace('                                _ __ ____\n       _______________________   __     /__   _____   ________   ______\n     __\___  \_   ___   /    /____    ____/___\__  \_/   ____/___\___  \_\n    /    /    /   \____/    /    /    /    /  __/ __/    /    /    /    /\n   /____/    / \________________/_________/___\    \_________/____/    /\n       /____/                                  \____\-jD!        /____/\n\n                   Documentation for Neutron-LastCallers\n                  ---------------------------------------\n\nIntroduction:\n\n                This is a powerful Last-10-Callers (Door?) for\n                AmiExpress (/X) 4.x. It is faast, nice looking\n                and can handle a lot of errors that could ocur\n                during a user connect time. (carrier loss, sys\n                tem crash, and so on...)In the registered vers\n                ion you will be able to create your own design\n                for this great door. In this version are two d\n                esigns included: Number one is designed by my-\n                self and the second one was taken from Amfetam\n                in / © The Silencer.\n\nRequirements:   \n                Any Amiga Computer with installed/working /X.\n\nFeatures:       \n                Shows:  Handle\n                        Location\n                        Logindate\n                        Logintime\n                        Logofftime\n                        Download\n                        failed Download\n                        Upload\n                        failes Upload\n                        new User\n                        Bulletins Viewer (if supported)\n                        operator Paged (if supported)\n                        Operator Chat\n                        examine Restricted Files\n                        file scan\n                        conference scan\n                        pw failures / hack tries\n                        account edit\n                        carrier lost\n\nInstallation:   \n                Just copy the drawer to your doors directory.\n                Add the following line to every logoffbatch\n                in your bbs:commands/syscmd drawer:\n\n                doors:ntr-lastcallers/ntr-lastcallers x\n\n                the x stands for each node number (off course)\n                the bulletin will be created as:\n\n                bbs:bulletins/lastc.txt\n\n                you have just to view it in /X with something like:\n\n                ~\n                ~SS_BBS:BULLETINS/LASTC.txt\n\n                Now you have to create the datafiles.\n\n                1) Open a cli window.\n                2) type "doors:ntr-lastcallers/ntr-lastcallers 0"\n                   (you have just created the datas for node 0)\n                3) repeat step 2 for each node you have, remember\n                   to replace the 0 with the nodenumber!\n\nConfiguration:  \n                There is a CONFIG file in the drawer.\n\n                First Line / Sysop:\n\n                        Put here a "1" to show the sysop in the bull\n                     or put here a "0" to hide the sysop in the bull.\n\n                Secon Line / Design:\n\n                        1 : Gravedancers Design,     No ANSI-Header\n                        2 : Design from Amfetamin,   No ANSI-Header\n                        3 : Gravedancers Design,   With ANSI-Header\n                        4 : Design from Amfetamin, With ANSI-Header\n                        5 : Use your own design (registered Version only)\n\n                        The Ansi-Header is © by Tango/aC!\n\n                Example configuration is set to:\n\n                No Sysop in the bulletin\n                Gravedancer Design with Header\n\nMaking your own design:\n\nFirst you have to create a file called "DESIGN.1". It includes the information\nyou want to be shown in the bull. The followin keywords can be used:\n\n                             ND ... NODENUMBER\n                     =====HANDLE===== ... THE USERNAME\n                    ====!LOCATION!==== ... THE LOCATION\n                           BAUD ... CONNECT BAUD\n                            ==D== ... LOGONDATE\n                            XX:XX ... LOGONTIME\n                           YY:YY ... LOGOFFTIME\n                         ?U ... NUMBER OF UPLOADS\n                        ?D ... NUMBER OF DOWNLOADS\n                           =U!= ... UPLOADBYTES\n                          =D!= ... DOWNLOADBYTES\n                    STATS ... STATUSLINE #1 (SEE BELOW)\n                  STATS-TWO ... STATUSLINE #2 (SEE BELOW)\n                 % ... USERSTATUS (WHETHER NEWUSER OR NOT)\n\nSTATUSLINE #1 INCLUDES INFORMATION ABOUT:\n                                          CARRIER LOST\n                                          NEWUSER\n                                          HACKEDPW\n                                          SYSOP PAGE\n                                          FILESCAN\n\nSTATUSLINE #1 INCLUDES INFORMATION ABOUT: \n                                          PWFAIL\n                                          UPLOAD\n                                          DOWNLOAD\n                                          SYSOP PAGE\n                                          FILESCAN\n                                          BULLETINS\n                                          CARRIER LOST\n                                          ACCOUNT EDITOR\n                                          RESTRICTED FILES\n\nEXAMPLE:\n\n[36mND [0m=====HANDLE===== ====!LOCATION!====  [33mXX:XX[35m-[33mYY:YY STATS ?U:=U!= ?D:=D!= [36mBAUD[0m\n\n(this looks like the included Amfetamin design, doesn''t it?)\n\nSecond step is to design the complete layout, called DESIGN.2.\n\nEXAMPLE: (again looking like the amfetamin design ...)\n\nINSERT INTO door_catalog VALUES('ntr_mchk','NTR-MCHK.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NTR-MCHK.LHA','NTR-CHECKER','XIM','NTR-CHECKER',NULL,NULL,'NTR','-gD__\   _/_\  ___/_./  |____________   /  | /   \  \  ____)   |   l   \   \ __/ _/   | _/   \____\_________|_____  /____\\   \____|',replace('     ______ _______   __.________________<-.\n-gD__\   _/_\  ___/_./  |____________   /  |\n  /   \  \  ____)   |   l   \   \ __/ _/   |\n_/   \____\_________|_____  /____\\   \____|\n\_____)                   \/       \___\  /|\n        [ NEUTRON /X bRINGS yA ]       /  \|\nNEUTRON  MULTICHECKER,  THE  ULTIMATE /    \\nFILECHECKER SYSTEM FOR  /X 3.X,4.X !_ _____/\nIT CHECKS LHA/LZH/LZX/ZIP/ARJ/TEXT& __\  _/|\nTHE WORLDS FIRST DMS CHECKER  WHICH/   \  \|\nADDS HANDLE, LOCATION, TIME^DATE!_/   \____\\n<--------------------------------\_____)---''\n','\n',char(10)),'OTHER_TOOLS.txt',replace('         ____________________ ________ 2F_________________________\n        _\      _\    ___\   |  _\   (___\      _\      _\       /_\n        \_   |  \_   _/_\_   |  \_   _/_\_   l__\_   |  \_   |   _/\n         |   |   |   l   |   |   |   l   |   |   |   |   |   | . |\n         l___|   l___    l_______l___    l___|   l_______l___|.::.\n             `---''   `---''           `---''                   `--··\n\n        [· NEUTRON /X DIVISION - QUALITY NEVER GOES OUT OF STYLE ·]\n\n                    LIST OF ALL PREVIOUS RELEASED TOOLS\n\n[ NEUTRON FRONT^WHO^LAST10 ]\n\nTHIS IS A MIGHTY FRONTSTATS AND WHO DOOR WITH INTEGRATED LAST-10-CALLERS\nPART. THE LAST-CALLERS BULLETIN IS GENERATED DURING THE LOGIN, HIDDEN TO\nTHE USER. THE FRONTDOOR PART OFFERS A LOT OF EXTRA FEATURES LIKE PRIVATE\nNODE SYSTEM. THIS MEANS THAT YOU CAN DEFINE A NODE WHICH IS PROTECTED BY\nA SPECIAL PASSWORD. MOREOVER THERE IS A ANSI/NOANSI QUESTIONARY INCLUDED\n\nTHE WHO DOOR SHOWS QUITE EVERYTHING INTERESTING OF ALL ACTIVE NODES LIKE\nHANDLE, LOCATION, ACTION, BAUD RATE, UPLOAD FILENAME AND SO ON.\n\nTHE LAST-CALLERS OFFERS DIFFERENT DESIGNS. THE FIRST ONE IS MADE BY MYSE\nLF AND THE SECOND ONE HAS BEEN ADAPTED FROM SILENCERS AMFETAMIN UTILITY.\n\n[ NEUTRON LAST-CALLERS ]\n\nSAME AS THE LAST-CALLERS PART IN NEUTRON FRONT^WHO^LAST10, BUT AS STAND-\nALONE SOLUTION. THIS DOOR WAS NEVER RELEASED PUBLIC AND IT IS ONLY ACCES\nSABLE FOR MY REGISTERED USERS.\n\n[ NEUTRON STATUS DOOR ]\n\nJUST A SIMPLE STATUS DOOR. I AM ABOUT TO REDESIGN IT TO RE-RELEASE IT IN\nTHE NEAR FUTURE.\n\n\n                CURRENT PROJECTS, OR: WHAT I AM WORKING ON\n\n[ NEUTRON MULTI TOOL ]\n\nLET ME TELL YOU SOME  ADVANTAGES OF  THIS TOOL! IT IS VERY SMALL AND FAST AND\nIT HAS SOME  KUHL ASCII-DESIGN  BY SOME OF THE BEST IN  THIS BIZZNEEZ ... THE\nNEUTRON  MULTI-TOOL  FEATURES A BULLETIN  VIEWER,   OFF  COURSE   USING   THE \n CURSOR KEYS ("8" AND "2" SUXX ...), A OPEN/DOORS  REPLACEMENT, A REQUEST AND\nA  ASCII-ORDER  DOOR  AND  A  OPERATOR-PAGE  AND   A  COMMENT-2-SYSOP   DOOR!\nTHE SEVENTH TOOL I ADDED IS A  ULTRA-FAST  DIR  STYLER  DOOR  LIKE   THE  ONE\nJORDAN/AKIRA RELEASED YEARS  AGO, BUT THIS IS ONE IS NICER^FASTER, THE EIGHTH\nTOOL IS ANOTHER WALL AND THE TOOL NUMBER TEN IS JUST A ANSI/NOANSI SWITCHER !\n\n[ NEUTRON NEW UPLOADS ]\n\nTHIS PROJECT IS IN THE VERY FIRST STAGE OF DEVELOPMENT! IT SHOULD BE SOMETHING\nLIKE A ONLINE NEW UPLOADS TODAY VIEWER ... IF YOU HAVE SOME SUGGESTIONS PLEASE\nLET ME KNOW ...\n','\n',char(10)),NULL,'auto-added',83402,4,0,NULL,NULL,'ntr_mchk','scan',1780048650);
