INSERT INTO door_catalog VALUES('nvx_vaw1','NVX-VAW1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NVX-VAW1.LHA','V-Await','XIM','V-Await',NULL,NULL,'NVX','\_____    \     /   \___  / ___/ tGø/aC!/.   /    /.   /    /.   _   \ //   /    //   /    //   /    /',replace('       ________________________________\n       \_____    \     /   \___  / ___/\ntGø/aC!/.   /    /.   /    /.   _   \\n      //   /    //   /    //   /    /\n     /____/    /\________/____/    /\n         /____/              /    /\n   { V-AWAiT v1.O1 - VENOM / NERVE AXiS }\nAn AwaitScreen replacement, Needs SAmiLog!\n','\n',char(10)),'awaitscreen.txt',replace('~\n~CC_V-AWAIT|\n','\n',char(10)),NULL,'auto-added',14735,1,0,NULL,NULL,'nvx_vaw1','scan',1780048650);
INSERT INTO door_catalog VALUES('nvx_vcf1','NVX-VCF1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/NVX-VCF1.LHA','V-ChatFlag','XIM','___ ___ ____       ___    ___  _  _ . ___',NULL,'VENOM/NERVE','NVX','(  //__/_\   ''/___\/__/_  (___\`_\\_ |`---. - --- ---------------------------------\_| V-CHATFLAG 1.oo BY VENOM/NERVE AXiS ''96',replace(' ___ ___ ____       ___    ___  _  _ . ___\n(  //__/_\   ''/___\/__/_  (___\`_\\_ |`---.\n - --- ---------------------------------\_|\n   V-CHATFLAG 1.oo BY VENOM/NERVE AXiS ''96\n Allows chatflag 2 be -  on 4 everyone\n                      - off 4 everyone\n                      -  on 4 certain users\n By use of a nice''n''simple GUI on Workbench\n - --- --[tGø/-T!]------------------- --- -\n','\n',char(10)),'V-ChatFlag.doc',replace('\n     .......   .......  ........  .... ....  .......\n    :::: :::: :::: :::: .....:::: :::: :::: :::: ::::\n    :::: :::: ::::      :::: :::'' :::: :::: ::::\n    :::: :::: ::::...   :::: :::: :::: :::: ::::...\n    :::: :::: :::: .... :::: :::: :::: :::: :::: ....\n    :::: :::: :::: :::: :::: :::: :::: :::: :::: ::::\n    :::: :::: :::: :::: :::: :::: :::: :::: :::: ::::\n    :::: :::: :::: :::: :::: :::: :::: :::: :::: ::::\n    :::: :::: `:::.:::'' :::: :::: `:::.:::'' `:::.:::''\n         ::::                :::: .______________  ___     _   __________\n                                  |.  __    /    \/   \___//__/.   _____/\n - --- -------------------- --- - | \\\_    \ _ _/ ___/   //  \______   |\n   The Phunky Happy Crew Of ''96   |    |    | \\\_    |       |     |   |\n                                  |:   |    |:   |    |:      |:    :   |\n     Present A New Production     |::  |    |::  |    |::     |::       |\n - --- -------------------- --- - |:::.|    |:::.|    |:::.   |:::.     |\n                                  `----|    |----|    |-------`---------''\n                                    tGø`----''    `----''-T!\n\n\n Doors so simple ... the fucking ascii takes more space than the info! =)\n\n\n                          .                            .\n    - ---------------- -./-                       - -./ ----------------- -\n      V-CHATFLAG 1.oo  //    yet another door =)    //  VENOM/NERVE AXiS\n   - --------------- -//-                       - -// ------------------ -\n                      ·                            ·\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                     .\n - -------------- -./-\n    iNTRODUCTiON  //\n - ------------- -//-\n                 ·\n\nEver  had  the problem of not wanting to switch off the chat flag in case a\nparticular user calls?  Well now it''s all solved for ya.\n\nInstall this door, and then tell it whether you want to:\n\nLeave chat on  [permanently]\nLeave chat off [permanently]\nLeave chat on  [selectively]\n\nYup,  you  can  choose WHEN you''re in for a chat!  In the /X door directory\nfor  this  door  you''ll  find  a text file and you get to write in the user\nnames  that  you  want  to  be  here for ...  all other people are ignored!\nSound great to you?  Then read on!\n\n\n\n\n\n\n\n\n\n\n                     .\n - -------------- -./-\n    iNSTALLATiON  //\n - ------------- -//-\n                 ·\n\n              Simple enuff ... if ya can''t figure it out ...\n                you shouldn''t be allowed near Ami-Express!\n\n\n\n\n\n\n\n\n\n\n              .\n - ------- -./-\n    USAGE  //\n - ------ -//-\n          ·\n\nThe program "V-ChatFlag" opens a window on WB, this sets the status for the\ndoor itslef.\n\nThe door "V-ChatFlagAX" (SETFLAG) should be put in the NODEx/BULL.TXT\nfile as a MCI command, ie.\n\n~CC_SETFLAG|\n\nThen  when someone logs, on it''ll check the status from the program and set\nthe flag.  If the status is set to "CHECK NAME" then it''ll look in the text\nfile "COOLGUYS.TXT" and see if their name is in it (case insensitive) if it\nis then the flag is on, if not then it''s off.\n\nIt supports as many lovely people as you want to include, just put one name\non  each  line (usernames with spaces in, just type as normal on same line)\nand then it''s done!  Simple stuff eh?\n\n\n\n\n\n\n\n\n\n\n                     .\n - -------------- -./-\n    REGiSTRATiON  //\n - ------------- -//-\n                 ·\n\nLets be honest ...  it''s taken us a few hours ...  we did it for fun not for\nmoney ...  so DONT send us any cash for a special registered version as this\nis  IT!   All future updates will be free and we have NO intention of making\nyou  pay money to have your name on our door.  What is it?  /X door creation\nor advertising?\n\n\n\n\n\n\n\n\n\n\n                         .\n - ------------------ -./-\n    CREDiTS & GREETS  //\n - ----------------- -//-\n                     ·\n\n              CODiING, ViKiNG HAT & GAME PLAYiNG   ... VENOM\n              ASCii, DOCUMENTATiON & COKE DRINKiNG ... TANGo\n\n\n          VENOM says hello to the following bodacious individuals\n\n MDR, Turbo, Real McCoy, Icon (upload god hehe), TANGo, Ace, Memo, Biggles\n  Cyber, Bill, Hybrid, Crash, Mic Flair ... and all other NVX members ...\n\n\n\n\n\n\n\n\n\n\n                           .\n - -------------------- -./-\n    CONTACT THE AUTHOR  //\n - ------------------- -//-\n                       ·\n\n                        ....     .........    .____.    .____:    .\n                     ..:::::   .:::::::::::.  |.   |__  |.  _|    |\n - --- --------- --- - :::::   :::::    ::::  |    __///| \\\_    |\n   NERVE AXiS UKHQ     :::::         :::::::  |    |____|    |    |\n - --- --------- --- - :::::            ::::  |:   |    |:   |    |\n AQUARiUS ^ TWiSTED!   :::::   ::::.   .::::  |::       |::  |    |\n  DiSTRiBUTiON SiTE ..:::::::..`:::::::::::''  |:::.     |:::.|    |\n - --- --------- --- -                     tGø`---------`----|    |-T!\n                                                             `----''\n\n         + 4 · 4   (O) · 1 · 7 · O · 4       5 · O · 5 · 8 · 4 · 5\n\n.____:    .           .____.____.__________\n|.  _|    | ..:::::.. |.   |    |.  __ ___/ - --- -------------------- --- -\n| \\\_    |::::· ·::::|    |    | \\\_    |   ACE · VENOM · TANGo · BiGGLES\n|    |    :::·     ·:::    |    |    |    |       · CYBER · CRASH ·\n|:   |    :::       ::::   |    |:   |    | - --- -------------------- --- -\n|::  |    :::.     .:::::  |    |::  |    | /X DOORS · AMiGA · MUSiC · SCi-Fi\n|:::.|    |::::. .::::|:::.     |:::.|    | GRAPHiCS · ASCii · /X UK REG SiTE\n`----|    | ··:::::·· `---------`----|    | - --- -------------------- --- -\n     `----''                          `----''\n','\n',char(10)),NULL,NULL,13292,6,0,NULL,NULL,NULL,'scan',1780048650);
