INSERT INTO door_catalog VALUES('o_ed_10','O-ED_10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/O-ED_10.LHA','OED','XIM','OED',NULL,NULL,NULL,'BBS',replace('OnlineEditor (TextEditor via StdIO) for all\nBBS\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 02-23-19  TIME: 10:10:45  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',55637,4,0,NULL,NULL,'o_ed_10','scan',1780048650);
INSERT INTO door_catalog VALUES('obs_ae38','OBS-AE38.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OBS-AE38.LHA',NULL,'XIM','ACP',NULL,NULL,'OBS','\____ \____  \ ___/ .   / ___/ __ \  ___/ /  |  \ |/  /___ \ |__/  __|_ |/  \ __/_ /   |   \|\  \  |  \|  \  |   \/   / |   \',replace(' _________________________________________  \n \____ \____  \ ___/ .   / ___/ __ \  ___/  \n  /  |  \ |/  /___ \ |__/  __|_ |/  \ __/_  \n /   |   \|\  \  |  \|  \  |   \/   / |   \ \n \_______/____/_____/____\_____/\  /______/ \n               >:PRESENTS:<      \/[C]      \nAmIeXpReSs v3.38 FuLlY CrAcKeD WiTh All DoX \nInCluDeS UpGrAdE SeT AnD ClEaN DaTA !!!!    \n','\n',char(10)),'AE-Update.Guide',replace('@DATABASE AE-Update.guide\n@$VER: AE-Update.Guide v3.18-3.36 (19-Feb-94)\n\n@REM Copyright (c) 1993 LightSpeed Technologies Inc.\n@REM All Rights Reserved\n@REM Merged together by RaJ-Ban - Swedish Dist site !\n\n@node MAIN "/X Update Documentation (1993-1994)"\n               .: U P D A T E  D O C U M E N T A T I O N :.\n               --------------------------------------------\n\n             Choose the version you want to review for Updates!\n             (If this is the 1st time you read this Guide, then read\n              them all to get all changes !)\n\n                     @{" Updates in v3.18             " Link UPDATE318}\n                     @{" Updates in v3.19             " Link UPDATE319}\n                     @{" Updates in v3.31             " Link UPDATE331}\n                     @{" Updates in v3.34             " Link UPDATE334}\n                     @{" Updates in v3.35             " Link UPDATE335}\n                     @{" Updates in v3.36             " Link UPDATE336}\n                     @{" Updates in v3.37             " Link UPDATE337}\n\n\n                  ------------------------------------\n\n  Documentation written by:\n  Joseph Hodge\n  LightSpeed Technologies Developement\n\n  Updated by:\n  The Outlaw /X WHQ\n  RaJ-Ban\n  Swedish /X-Dist\n\n  Copyright (c) 1993-94 LightSpeed Technologies Inc.  All Rights Reserved.\n  Any copy or illegal distribution of this Documentation is prohibited.\n\n@endnode\n\n@node UPDATE318 "/X Update 3.18 (c)1993 LightSpeed Technologies Inc."\n               .: U P D A T E  D O C U M E N T A T I O N :.\n\n             The following is a list of changes to version 3.18\n             of AmiExpress. (01-Nov-93)\n\n                     @{" Custom Commands              " Link Update31801}\n                     @{" MCI Commands                 " Link Update31802}\n                     @{" Message Base                 " Link Update31803}\n                     @{" Account Editor               " Link Update31804}\n                  ------------------------------------\n\n  Copyright (c) 1993 LightSpeed Technologies Inc.  All Rights Reserved.\n  Any copy or illegal distribution of this Documentation is prohibited.\n\n@endnode\n@node Update31801 "Custom Commands (Doors)"\n  =========================================================================\n  We added a configuration option to the module icons called:\n\n  PASS_PARAMETER=4\n\n  This option will tell AmiExpress to bypass checking the BBSCMD modules.\n\n  This option was primarily introduced to allow a sysop to invoke an\n  INTERNAL command from a ConfXCMD and forcing it to bypass checking the\n  BBSCMD directory for the INTERNAL command.\n\n@endnode\n@node Update31802 "MCI Update"\n  =========================================================================\n  Modified the following commands:\n\n  ~SR  - Show Random Files\n\n  SYNTAX: ~<num>SR_<fileid>\n\n           ^    ^  ^\n           |    |  |\n           |    |  ---------- pathname without security level and file\n           |    |             extension\n           |    ------------- Command to show random file\n           ------------------ Number of Random files\n\n  IE: ~10SR_BBS:Logon\n\n  This will look for a random file between 1-10, the syntax for the file\n  to display is:\n\n  SYNTAX: PathName<seq>.FileName[security level]<extension>\n\n  IE: BBS:001.Logon200.txt\n\n\n  This would be the first of ten files to create to be displayed\n  by the random function, the ''200'' is the security level which is\n  optional.\n\n  -----------------------------------------------------------------------\n  ~SX  - Show Sequentual Files\n\n  SYNTAX: ~SX_<fileid>\n\n           ^  ^\n           |  |\n           |  ---------- pathname without security level and file\n           |             extension\n           ------------- Command to show sequentual file\n\n  IE: ~SX_BBS:Logon\n\n  1. This will look for a file called BBS:Logon which will store the last\n     sequence of the <fileid> that was displayed. If this file does not\n     exist, the ''SX'' command will create it.\n  2. Then it will construct a display file name based on the next sequence\n     number as follows:\n\n     SYNTAX: PathName<seq>.FileName\n\n  3. It will then look for the appropriate file to display. The actual\n     ASCII file should contain the following information for the filename:\n\n     SYNTAX: PathName<seq>.FileName[security level]<extension>\n\n     IE: BBS:001.Logon200.txt --v\n         BBS:001.Logon100.txt ----- notice the different security levels\n                                    keeping in mind that they are optional.\n         BBS:002.Logon200.txt\n\n@endnode\n@node Update31803 "Message Base Changes"\n  =========================================================================\n  Following is a list of changes to the MessageBase system\n\n  Due to popular demand we revamped the mailscan. Now AmiExpress will\n  scan each conference for mail that pertains to the user that is online.\n\n  While scanning, AmiExpress will store the msg numbers in memory until\n  the end of the scan, at the end of the scan AmiExpress will proceed to\n  show the user the originator of each message and then proceed to prompt\n  the user if he/she wishes to read the mail.\n\n  This method of scanning has 3 advantages:\n\n  1. The user will now know who left him/her mail prior to reading it.\n  2. The NewMail Scan pointer will not be updated until all the mail is\n     read. So if the user has 2 messages ''100'' and ''101'' and he/she\n     reads message 101 and not 100, then the next time the user logs on\n     or does a mail scan, he/she will still  be notified of message 100.\n  3. The NewMailScan will now remember the last valid message left to\n     the user when the user losses carrier or logs off.\n\n@endnode\n@node Update31804 "Account Editor Changes"\n  =========================================================================\n  Following is a list of changes to the Account Editor\n\n  A bug was introduced in version 3.17 of AmiExpress which was intended\n  to allow the sysop to globally store a preset''s ratio into all\n  conferences for a given user.\n\n  This change caused an error condition in that once the last conference\n  was filled with a ratio, AmiExpress retained the last conference''s\n  attributes instead of the current conference. So this could have\n  resulted in message base corruption in the last conference, especially\n  if the current conference and last conference where not of the same\n  message base type. This bug would only occur while validating users\n  that are online or when validating a user from the message base.\n\n  We have removed this bug and now everything should be fine.\n\n@endnode\n\n@node UPDATE319 "/X Update 3.19 (c)1993 LightSpeed Technologies Inc."\n               .: U P D A T E  D O C U M E N T A T I O N :.\n\n             The following is a list of changes to version 3.19\n             of AmiExpress. (12-Nov-93)\n\n                     @{" Message Base                 " Link Update31901}\n                     @{" Account Editor               " Link Update31902}\n                     @{" Time Routines                " Link Update31903}\n                     @{" Suggestions and Bug Reports  " Link Update31904}\n                     @{" Upcoming Releases            " Link Update31905}\n                     @{" Developement Issues          " Link Update31906}\n                     @{" Beta Testers                 " Link Update31907}\n                  ------------------------------------\n\n  Copyright (c) 1993 LightSpeed Technologies Inc.  All Rights Reserved.\n  Any copy or illegal distribution of this Documentation is prohibited.\n\n@endnode\n@node Update31901 "Message Base Changes"\n  =========================================================================\n  Following is a list of changes to the MessageBase system\n\n  We removed the ''...'' which was being displayed during each conference new\n  mail scan.\n\n  Fixed a problem with deleting accounts from the message base.\n  The previous version would not properly restore the current conference\n  location after reseting the user''s conference stats in each conference.\n  This could have resulted in possible msgbase corruption.\n\n  *REMARKS*\n\n  A couple of releases ago we introduced a bug in AmiExpress which caused\n  user''s accounts to improperly reflect the number of messages the user\n  has posted. Since the incorrect figures overwrote the user''s original\n  message posted stats, we had no way of correcting the damage that was\n  already done, but in version 3.18 we introduced a conference maintenance\n  function ''F5'' which contains a new command option ''6'' which allows a\n  sysop to reset the message posted field of the conf.db for each account\n  for a given conference. So those who have experienced this problem,\n  please proceed to CONFERENCE MAINTENANCE to reset the message posted\n  field.\n\n@endnode\n@node Update31902 "Account Editor Changes"\n  =========================================================================\n  Following is a list of changes to the Account Editor\n\n  Fixed the account editor so if user updates his own Time_Used\n  using the ''1'' menu prompt command, the change will effect the daily\n  time used and not only the session time used.\n@endnode\n@node Update31903 "Time Routines"\n  =========================================================================\n  Following is a list of changes to the Time Routines\n\n  Fixed the F2 and F3 online menu commands so that the user''s time\n  change will effect the daily time limits as well as the session time.\n@endnode\n@node Update31904 "Suggestions and BugReports"\n  =========================================================================\n  Following is a list of Suggestions and BugReports we would like to\n  address.\n\n  BUGREPORT:\n  -------------------------------------------------------------------------\n  [11-12-93] CHB of Blizzard\n\n  Hi,\n  there is a nasty bug also in the /X 3.18 release!\n  XPR uploads and downloads are not counted, so anyone who uses XPR\n  protocolls can suck without end!\n  Please remaove that bug quick!\n\n  CHB of Blizzard\n\n  COMMENTS FROM AUTHOR:\n\n     We have researched this problem on more than one occassion and from\n     our research have concluded that this problem is isolated to 1\n     zmodem xpr library which we feel is an error in the xpr library\n     itself. If you experience this problem from more than 1 library\n     please let us know the library names so that we may properly research\n     the problem.\n\n  -------------------------------------------------------------------------\n  [11-10-93] THE CHAMP\n\n  /X 3.18 - MessageBase-Counters still destroyed...\n            MCI-Command xxSR_" isn''t working... only when entering\n            values higher than 9... so that we use two numbers...\n            the sec. level after the FileName isn''t work, too\n\n\n  COMMENTS FROM AUTHOR:\n\n     Please read the *REMARKS* in the messagebase updates section of\n     this guide to resolve the problem with your message posted values.\n     If the problem still persists after that please inform us immediately.\n\n     Please refer to the changes text in version 3.18 for the new file\n     naming conventions for the SR and SX command. We will research this\n     problem on our end as well.\n\n  -------------------------------------------------------------------------\n  [11-08-93] Rad!\n\n  Message base problems :\n\n  The messages are again becoming blank on my bbs using 3.18 for the first\n  conference and the first conference only??? Dunno what is causing this\n  problem but no messages are able to be read, and I don''t want to loose my\n  message base... snief.. hehe\n\n  - Rad!\n\n  COMMENTS FROM AUTHOR:\n\n     This problem is probably the direct result of deleting an account\n     from the message base. This should be fixed in this release.\n\n\n@endnode\n@node Update31905 "Upcoming Releases"\n  =========================================================================\n  Following is a list of changes and additions to upcoming releases of\n  AmiExpress. These changes may or may not come to pass but we would like\n  to keep you informed.\n\n  We are currently Testing a 32 node capable version of AmiExpress. This\n  version is being developed along side the 9 node version ''3.19''. The\n  most important difference besides the 32 node capability is the fact\n  that the 32 node version is ''pure'' so that only one copy needs to be\n  in memory at a time. During the process of making the 32 node version\n  ''pure'' we had to temoporarily disable the XPR interface capability which\n  is what we are working on right now. The Assembly code for the XPR\n  interface was not coded in a way that permits us to make it ''pure'' so\n  we are recoding it right now. We bring this information to you mainly\n  because we want some feedback. If we release the 32 node version to the\n  public there will more than likely be a revision fee.\n\n  Those that maybe interested in testing the 32 node version should\n  consult The primary support board for details on obtaining a copy.\n  This will most likely me signing some agreements forms to include\n  a non-disclosure form and an upgrade fee.\n\n  Concerning all versions of AmiExpress:\n\n  1. We intend on providing more internal functions to the program, to\n     include a built in last callers routine which will be configurable\n     from MCI commands.\n  2. We plan on modifying the msgbase routines so that you can read a\n     message and suppress the READ MESSAGE flag. This will be useful\n     in instances where you read some mail and do not wish the orginator\n     to know that you have read it yet. This is an important option to\n     most sysops.\n@endnode\n@node Update31906 "Developement Issues"\n  =========================================================================\n\n  Those of you wishing to write modules or utilities for AmiExpress to\n  obtain a profit, please consult the primary support board for information\n  on obtaining licensing agreements and any associated fees.\n\n  We will also be opening the 3 developer support Bulletin Boards in a\n  couple of weeks. These boards will be devoted to providing the developer\n  with any technical information at our disposal for assistance in\n  developing and maintaining utilities and modules for AmiExpress.\n\n  We will be charging an annual development fee to compensate for the\n  time required to provide the information and assitance you may need.\n\n  Those interested in becoming registered developers please consult\n  the primary support board for further details.\n\n@endnode\n@node Update31907 "Beta Testing"\n  =========================================================================\n\n  The developement of any large scale program undoubtably requires the\n  assistance of BetaTesters. AmiExpress is no exception (we all know that).\n\n  Those interested in beta testing AmiExpress please consult the primary\n  support board to obtain a non-disclosure form.\n\n@endnode\n\n@node UPDATE331 "/X Update 3.31 (c)1992-1994 LightSpeed Technologies Inc."\n               .: U P D A T E  D O C U M E N T A T I O N :.\n\n             The following is a list of changes to version 3.31\n             of AmiExpress. (02-Jan-94)\n\n                     @{" MultiComm Port               " Link Update33101}\n                     @{" Program Execution            " Link Update33102}\n                     @{" MCI Commands                 " Link Update33103}\n                     @{" Internal Zmodem Protocol     " Link Update33104}\n                     @{" XPR Protocols                " Link Update33105}\n                     @{" Custom Commands              " Link Update33106}\n                     @{" Message Base                 " Link Update33107}\n                     @{" AmiXnet Updates              " Link Update33108}\n                  ------------------------------------\n\n  Copyright (c) 1994 LightSpeed Technologies Inc.  All Rights Reserved.\n  Any copy or illegal distribution of this Documentation is prohibited.\n\n@endnode\n@node Update33101 "MultiComm Port"\n  =========================================================================\n  Following is a list of changes to the MultiComm Port\n\n  Since version 3.30 of AmiExpress we have increased the Maximum Number\n  of Nodes that ACP can handle. ACP can now handle a maximum of 32 Nodes.\n\n  This change involved changing the internal MultiComm structure to handle\n  32 nodes vs 9 nodes. This change means that the old NewChat and some of\n  the older Online Message Send Modules may not work any longer. We have\n  released an update to the NewChat door so that it will handle the 32\n  node configuration.\n\n@endnode\n@node Update33102 "Program Execution"\n  =========================================================================\n\n  Since version 3.30 of AmiExpress you now have the ability to make\n  AmiExpress resident. Doing this should speed up program execution\n  and also conserve memory.\n\n  Making AmiExpress resident:\n\n  1. change all nodestart tooltypes in the NODE icons to reflect the\n     following:\n\n     NODESTART=express\n\n  2. Update your s:user-startup script by adding the following after\n     your BBS Assignment:\n\n     RESIDENT EXPRESS BBS:EXPRESS\n\n\n@endnode\n@node Update33103 "MCI Commands"\n  =========================================================================\n  Following is a list of changes to the MCI Commands\n\n  I have modified the ~CC command to allow the execution of MENU PROMPT\n  commands. This will allow you to run the internal WHO command from any\n  MCI text. Simply add this MCI command to your MCI Text File:\n\n  ~CC_WHO\n\n  NOTE: It is important to realise that most MENU COMMANDS should only\n        be run from the MENU PROMPT. For Instance , forcing the READING\n        of mail at the FRONTEND of express would not be wise because the\n        BBS does not know who is logging onto the system. So use your\n        own judgement on these matters.\n\n@endnode\n@node Update33104 "Internal Zmodem Protocol"\n  =========================================================================\n  Following is a list of changes to the Internal Zmodem Protocol\n\n  I added the tooltype HDTRANSBUFFER, this tooltype is for the node icons.\n\n  HDTRANSBUFFER allows you to change the buffer size from serial to\n  harddisk. This option is a better alternative than using a RAMPEN because\n  it works on a file by file basis, whereas the RAMPEN method has to wait\n  until all uploads are complete.\n\n  HDTRANSBUFFER has the following syntax:\n\n  HDTRANSBUFFER=<buffers>\n\n      You may specifiy as many buffers as you like. The number of buffers\n      default to 8 if this tooltype is not used. Here is a formula for\n      determining how much memory will be allocated for transfers when the\n      node is started:\n\n      ((buffers+2)*1024)*2\n                         ^--- This is required due to the double buffering.\n\n      ie:\n\n      HDTRANSBUFFER=20 would require 45,056 bytes of memory\n\n      1. ((20+2)*1024)*2\n      2. (22*1024)*2\n      3. (22528)*2\n      4. 45056\n\n    Version 3.30 a bug was introduced with this HDTRANSBUFFER addition.\n  AmiExpress was not freeing the memory it allocated for the buffers. This\n  is the primary reason for releasing this version.\n\n@endnode\n@node Update33105 "XPR Protocols"\n  =========================================================================\n  Following is a list of changes to the XPR Protocols Interface:\n\n  We have temporarily removed the XPR interface and placed it in a SYSCMD.\n  We will most likely put this back into AmiExpress in a month or so.\n\n  One of the important changes to AmiExpress besides this is now all batch\n  Protocol Icons must contain the tooltype AE_BATCH instead of BATCH.\n\n@endnode\n@node Update33106 "Custom Commands"\n  =========================================================================\n\n  I added the tooltype ''QUICKMODE'' for the module icons. This tooltype\n  simply tells AmiExpress not to run the Module in question if the user\n  has logged onto the sysop using the QUICK logon option.\n\n@endnode\n@node Update33107 "Message Base"\n  =========================================================================\n\n  Since Version 3.30 the message base has been modified to re-display\n  the original message if a reply to a message was aborted.\n\n@endnode\n@node Update33108 "AmiXnet Updates"\n  =========================================================================\n\n  Due to the expansion of the Net, including more sales and increased\n  volume of mail, we realized the need for a more optimized method of\n  packing netmail. AmiXnet currently recalculates the MailRoute for\n  every net mail conference when it is packing mail and unpacking mail.\n  This in itself is not efficient. Therefore I modified all of the NETMAIL\n  utilities to recognize pre computed mailroutes, this greatly speeds up\n  the mail packing process for those with only one Node Id.\n\n  In order to invoke the optimized method of packing mail you will need to\n  do the following:\n\n  1. Modify the scripts that run MRUPDATE with an additional commandline\n     option ''AUTOUPDATE''. AUTOUPDATE should be the last commandline option\n     to MRUPDATE. This will force MRUPDATE to create pre-calculated\n     mailroutes when new maps come down the net.\n\n  2. Create a directory in BBS:AmiXnet named your node id. For instance I\n     have a directory called:\n\n     BBS:AmiXnet/703001 because 703001 is my nodeid.\n\n  Once you have done the above, the next time mail is packed the netutils\n  will create pre-computed route files and place them into the newly\n  created directory.\n\n  NOTE: ONLY DO THIS IF YOU HAVE ONLY 1 NODE ID. THERE IS A COUPLE OF\n        BBSs WITH MULTIPLE NODE IDS, THIS OPTION WILL NOT WORK FOR THEM\n        AT THE MOMENT. I HOPE IN THE NEAR FUTURE I WILL HAVE THIS SOLVED.\n\n\n\n@endnode\n@node UPDATE334 "/X Update 3.34 (c)1992-1994 LightSpeed Technologies Inc."\n               .: U P D A T E  D O C U M E N T A T I O N :.\n\n             The following is a list of changes to version 3.34\n             of AmiExpress. (13-Feb-94)\n\n                     @{" Foreword                     " Link Update33401}\n                     @{" Internal Commands            " Link Update33402}\n                     @{" Multinode Chat               " Link Update33403}\n                     @{" Conference tooltypes         " Link Update33404}\n                     @{" Custom Commands              " Link Update33405}\n                     @{" Doors                        " Link Update33406}\n                     @{" Final words                  " Link Update33407}\n                  ------------------------------------\n\n  Copyright (c) 1994 LightSpeed Technologies Inc.  All Rights Reserved.\n  Any copy or illegal distribution of this Documentation is prohibited.\n\n@endnode\n@NODE update33401 "Forewords about the v3.34"\n  =========================================================================\n\n  First of all I think all of you guys, should tip your hat off to\n  Joe this month for all the extra work he has done for this release.\n  he has been putting in all his days and nights over the last few\n  weekends to make all these changes. THANKS JOE.\n\n  Personally I am very excited about the changes that are being incorp-\n  orated into express and a lot more coming.\n\n@endnode\n@NODE update33402 "Internal Commands"\n  =========================================================================\n\n  1. There is a new command called ''CF''. This command will allow your users\n     to set the way express handles conferences. From here they can set the\n     ''NEW FILE SCAN'', ''NEW MESSAGE SCAN'', and turn ''OFF'' and ''ON'' what\n     conferences they want to ZOOM mail from.\n\n     In the Conference Maintainance option in the Account editor you can\n     also Globaly set these options (F5).\n\n  2. In the ''W'' option for users, is now the ability for the user to pick\n     what kind of Zoom they want. They can pick QWK, or the old ascii\n     zoom option.\n     NOTE: You must first install some new Icons in the ZOOM dir, otherwise\n           it wont work. Samples are included in the ''UPDATE.LHA'' archive.\n           Edit them to fit your needs !\n\n@endnode\n@NODE update33403 "Multinode Chat update"\n  =========================================================================\n\n  The second biggest feature is that /X now has ''MESSAGE QUE'' capabilty for\n  multinode chat. Remember when you would chat someone on another node, and\n  they were busy doing something, and they would never get the message,\n  well now when the user is done, they will receive the mesaage you sent\n  them. There is a new ''NEWCHAT'' door online to grab, that uses this new\n  capability. (also included in the UPDATE.LHA package)\n\n@endnode\n@NODE update33404 "New TOOLTYPES to the conf icons"\n  =========================================================================\n\n  New options in the conf icons for you sysops:\n\n  FORCE_NEWSCAN\n  -------------\n  This will force your users to have a New Mail scan whether they\n  have selected it or not.\n\n  NO_NEWSCAN\n  ----------\n  This will Force No New Mail scan whether a uers has turned it off or\n  not.\n\n  SHOW_NEW_FILES\n  --------------\n  This is not a new command, but if used in the conf icon, will act\n  like the above force command for messages\n  IE: Force your users to get a new file scan whether they have chosen\n      it or not.\n\n@endnode\n@NODE update33405 "Custom Commands"\n  =========================================================================\n\n  Another new option is for your commands Dir. You can now make an icon\n  called ''NODE#CMD'' This is used like your CONF#CMD Option. Now your node\n  can use it as well.\n\n@endnode\n@NODE update33406 "BugFix for Door icon Tooltype"\n  =========================================================================\n\n  In this version there was also a BUG FID in the doors icons.\n  PRIORITY=<xx> has now been fixed. If you use PRIORITY=SAME,\n  it will use the same Priority that express uses.\n\n@endnode\n@NODE update33407 "Final Words"\n  =========================================================================\n\n  Well I think that is all. If I have forgotten to tell you everything I\n  will leave a message. Wow what a month. Ok enjoy the new express.\n  Included in archieve, is also the icons needed to put in your zoom dir.\n  For those of you useing utilities that delete everything in your Zoom\n  directory, I advise you to stop useing them. It will delete these icons\n  needed.\n  Ok that''s it for now.\n\n  /LIGHTSPEED TECHNOLOGIES INC.\n\n@endnode\n@node UPDATE335 "/X Update 3.35 (c)1992-1994 LightSpeed Technologies Inc."\n               .: U P D A T E  D O C U M E N T A T I O N :.\n\n             The following is a list of changes to version 3.35\n             of AmiExpress. (14-Feb-94)\n\n                     @{" User access                  " Link Update33501}\n                  ------------------------------------\n\n  Copyright (c) 1994 LightSpeed Technologies Inc.  All Rights Reserved.\n  Any copy or illegal distribution of this Documentation is prohibited.\n\n@endnode\n@NODE update33501 "Access tooltype"\n  =========================================================================\n\n  Added a new tooltype For Access.info or /access/ACS.xxx.info !\n\n  ACS.CONFFLAGS\n  -------------\n  This tooltype sets at what access a user can use the CF command.\n\n@endnode\n@node UPDATE336 "/X Update 3.36 (c)1992-1994 LightSpeed Technologies Inc."\n               .: U P D A T E  D O C U M E N T A T I O N :.\n\n             The following is a list of changes to version 3.36\n             of AmiExpress. (14-Feb-94)\n\n                     @{" Bug Fixes                    " Link Update33502}\n                  ------------------------------------\n\n  Copyright (c) 1994 LightSpeed Technologies Inc.  All Rights Reserved.\n  Any copy or illegal distribution of this Documentation is prohibited.\n\n@endnode\n@NODE update33502 "Bug Fixes"\n  =========================================================================\n\n  Found a bug in the way /X handled the PRIORITY=X In the doors icons.\n  This has been fixed.\n\n  Modified the ''CF'' Command to display double lines if a user has access\n  to more than 10 Conferences.\n\n@endnode\n@node UPDATE337 "/X Update 3.37 (c)1992-1994 LightSpeed Technologies Inc."\n               .: U P D A T E  D O C U M E N T A T I O N :.\n\n             The following is a list of changes to version 3.37\n             of AmiExpress. (13-Mar-94)\n\n                     @{" What''s New                   " Link Update33503}\n                     @{" Bug Fixes                    " Link Update33504}\n                  ------------------------------------\n\n  Copyright (c) 1994 LightSpeed Technologies Inc.  All Rights Reserved.\n  Any copy or illegal distribution of this Documentation is prohibited.\n\n@endnode\n@NODE update33503 "What''s New"\n  =========================================================================\n\n     The release of 3.37 requires that a utility be run against the\n   user.data file called ''CLEANDATA'' this will insure that the obsolete\n   areas in your user data are initialized for the use of the new ''MULTICHAT''\n   fields and the new ''CREDIT MAINTAINENCE'' fields. The syntax for running\n   this utility is:\n\n   CLEANDATA bbs:user.data\n\n   This will create a backup of the user data prior to making any changes,\n   into a file called bbs:user.data.old.\n\n  =========================================================================\n\n     Added ACCOUNT CREDIT MAINTENANCE.  This feature allows you to keep\n   track of paying users, The assumption is that if a user pays, then they\n   are paying for a DISABLED ratio. CREDIT MAINTENANCE will let you establish\n   the number of days that the credit account is to be in effect. During this time\n   period the user will be given an ''EFFECTIVE'' DISABLED ratio. Their ratio\n   does not actually change, but express will treat there account as a\n   disabled ratio. So during the credit period an ''FS'' command or ''S'' command\n   will reflect a DISABLED ratio. Once the credit account has expired, express\n   will then use the ratio established for the user.\n\n     There are 2 new tooltypes for the ACCESS icons, which help maintain\n   CREDIT ACCOUNTS:\n\n        ACS.SHOW_PAYMENTS = using this access, the user will be able to see\n                            when there credit account will expire via the\n                            ''S'' command.\n\n        ACS.CREDIT_ACCESS = this tooltype will allow a user (cosysop/sysop)\n                            to view CREDIT ACCOUNTS as long as they have\n                            ACCOUNT EDITING access.\n\n     There is a new option which is not reflecting in the ACCOUNT MAINTENANCE\n   screen, ''!'' , this will invoke the CREDIT MAINTENANCE screen for that\n   particular account.\n\n   NOTE: Only Sysops on the LOCAL side of the BBS will be allowed to SAVE any\n   changes to CREDIT MAINTENANCE.\n\n   Credit Maintenance will maintain a log called CREDITLOG in the BBS:\n   directory.\n\n     Modified Comsetics to CREDIT MAINTENANCE, and CONFERENCE\n   MAINTENANCE and ACCOUNT MAINTENANCE.\n\n     Modified CREDIT MAINTENANCE to allow you to turn on/off\n   download/upload tracking for the account.\n\n  =========================================================================\n\n     Modified express to not display negative numbers when showing the\n   total time awarded for upload.\n\n  =========================================================================\n\n     All OVERIDE tooltypes have been replaced with OVERRIDE, please make\n   this change in all of your ACS icons and ACCESS icon.\n\n  =========================================================================\n\n     Modified AmiExpress so that you can run a N S U or S door from the\n   SYSCMD at logon.\n\n  =========================================================================\n\n     Added new tooltype to the ACP icon ''LONG_WHO''. This tooltype will\n   provide a seperater between each node listed in the WHO command.\n\n  =========================================================================\n\n     Modified the cosmetics of the ''W'' (User Account Edit) function.\n\n  =========================================================================\n\n     Modified the who command to show if a user is available for chat or\n   online messaging.\n\n  =========================================================================\n\n     Added new tooltype to the node icons: ''COPYBUFFER'' this allows you\n   to specify the maximum amount of memory that you wish express to use when\n   copying files from one partition to another. If you do not specify this,\n   then express will try and allocate memory enough to copy the file with 1\n   WRITE. If course, if there is not enough memory, it will decrement by 8K\n   blocks, until it can copy it, regardless of the COPYBUFFER.\n\n                ie: COPYBUFFER=100000\n\n                               ^---------100K copy buffer\n\n     Added new tooltype to the node icon: ''MAX_MSG_QUE'' this allows you\n   to specify the maximum number of messages (olm/chat) that can be queued to\n   that node. Anything that is sent after the maximum will be ignore. If this\n   tooltype is not specified then express defaults to 5.\n\n  =========================================================================\n\n     Credited a new tooltype for the Node icon called ''SCREENPENS'' this\n   tooltype is primarily there for testing the color configurations of the\n   upload file requestor and overall screen color appearances, It is hard to\n   explain how this works, but we have 12 color pens we can config that make\n   up the look of the screen, and the best I can do for testing is to let you\n   the sysop define what those 12 colors will be, so here is an example:\n\n        SCREENPENS=101010110110\n\n        0 = BLACK\n        1 = WHITE\n        2 = GREEN\n        3 = YELLOW\n        4 = BLUE\n        5 = MAGENTA\n        6 = CYAN\n        7 = RED\n\n     Now for a 1 bitplane screen (2 colors) you will use only 1 and 0,\n   so you experiment with this, and see what you can come up with.\n\n  =========================================================================\n\n     Added ''Time_Total'' field to the account editor, this field keeps\n   track of the actually maximum time the user has acrued for the day. This\n   value has always been in the User.Data, but I decided to place it in the\n   account editor so that the value can be manipulated.\n\n  =========================================================================\n\n     Modified Logon routines so that you do not need a password to login\n   locally, regardless of account.\n\n     Modified express to update time used directly after the download is\n   finished.\n\n     Modified express to check time remaining after each file is\n   downloaded in a batch transfer. If the time has expired, it will not allow\n   the rest of the batch transfer to complete.\n\n  =========================================================================\n\n     Modified AmiExpress to report ''WHO'' to acp when running the\n   internal who command.\n\n  =========================================================================\n\n     Added ability to accept a module''s name to display in the action\n   window for a given node.\n     Added #28 status code ''Online Message'' to acp.\n\n  =========================================================================\n\n     Added new tooltype to the node icons: DEF_SCREENS\n\n        DEF_SCREENS tells AmiExpress to use non security screens before\n   looking for security screens. ie:\n\n        BULL30.TXT\n        BULL.TXT\n\n        In the above case, express would start it''s search for screens with\n   BULL.TXT, this can be a considerable time savings if the majority of your\n   screens are not security oriented.\n\n        Under this scheme, BULL0.TXT is now a valid security designator.\n\n     As many of you know, AmiExpress searches for security oriented text\n   in increments of 5 based on the user''s password. So if a user has an access\n   level of 255, and there is only a BULL30.TXT, then express would have to\n   check for the existance of 88 screens prior to locking in on BULL30.TXT. By\n   default express does this now. I am just saying, if you do not have\n   security text or most of your texts aren''t security oriented, then I\n   recommend using the DEF_SCREENS.\n\n        NOTE: if you use the DEF_SCREENS option but you have security\n   oriented menus to display, then instead of having:\n\n        BULL30.txt\n        BULL.txt\n\n        use:\n\n        BULL30.txt\n        BULL0.txt\n\n        and simply do not have a BULL.TXT for that bulletin.\n\n  =========================================================================\n\n     Modified express to use AmigaDos Time vs UnixTime routines.\n   NOTE: Time is still recorded based on a UnixTimeBase.\n\n     This should remove 95-99% of the ENV:TZ accesses. There may be some\n   doors that use some of the old glue routines which may still use the unix\n   time routines.\n\n  =========================================================================\n\n     Changed the display of Chat_Left in the account editor to reflect\n   Chat time used.\n\n     Changed the WHO outline color from green to blue.\n\n     Added new access tooltype ''ACS.HIDE_FILES''. This access will\n   prevent the user from seeing which files are being transfered via the WHO\n   command and ''NEWCHAT (who)''.\n\n  =========================================================================\n\n       Added internal Online Message Sender. Introduces new Access\n   tooltype ''ACS.OLM''.\n\n     Added the ability to send OLM messages to ALL Nodes. Specify ''*''\n   when asked for the destination node.\n\n     Added MultiNode Chat Time Limits to the Account Editor. These\n   limits will be utilized by the ''NEWCHAT'' door. Once we are comfortable that\n   the ''NEWCHAT'' door is streamlined we maybe hard coding it into express.\n\n\n     Added new menu prompt option ''OLM'' for online message sending.\n\n     Online Messages will be queued at the destination node. The Online\n   Messages sent to other nodes are Allocated by the originating Node, and\n   deallocated by express at the destination Node.\n\n@endnode\n@NODE update33504 "Bug Fixes"\n  =========================================================================\n\n     Fixed bug with the awarding of time for uploads. If there is any\n   other problems that you can spot with the awarding of time for uploads,\n   please let me know.\n\n  =========================================================================\n\n\n     There is an OLD tooltype in the node icons, called\n   ''KEEP_UPLOAD_CREDIT'' this tooltype can have 1 of 2 values ''0'' or ''1''.\n   There meaning is as follows:\n\n        KEEP_UPLOAD_CREDIT=0 = Do not penalize a user ''time'' for uploads.\n\n        KEEP_UPLOAD_CREDIT=1 = Do not penalize a user ''time'' for uploads\n                               and give them an additional %50 time\n                               increase to the remaining time online for\n\n  =========================================================================\n\n     Fixed problem with ANSI stripper routines, when a double <ESC>\n   sequence was issued, the stripper would not strip right hehe.\n\n  =========================================================================\n\n     Modified File Check routines, fixes a bug in the ERROR detection\n   phase of the checking.\n\n  =========================================================================\n\n     Fixed bug in OLM, that was created with the last version.\n\n     I had a report that the time awarded actually displayed a negative,\n   number, if this occurs, then in this version express will annotate it into\n   the callerslog, so if you notice it, please let me know.\n\n  =========================================================================\n\nNewChat 3.37\n\n     Modified NewChat to not display a user as active ''CTRL-A'' if the\n   user has run out of time in the door.\n\n     Added recognition of the ''Online Message'' status.\n\n\n     Added stat #28 ''Online Message'' status to express.\n\n     Added new tooltype to the module icons: NAME=whatever\n   The Module Name can be upto 15 characters in length, this name will\n   be reported to the ACP window when the module is invoked, if you do not\n   supply a name, AmiExpress will substitute it with the modules icon name.\n\n     Modified the WHO command, to show the ''Online Message'' status.\n\n     Changed WHO colors from Green to Blue.\n\n     Modified Paging Method, to allow the destination node of the page\n   to deallocate the interport communications. This means that the NewChat\n   door does not have to wait on a reply to the message from the destination\n   node.\n\n     Made some cosmetic changes.\n\n     Fixed a problem with semaphore releasing in versions prior to 3.3\n   if a user ran out of time in the chat door and then re-entered the door\n   then it would cause a multinode lockup.\n\n     Changed WHO colors from Green to Blue.\n\n     Modified Paging Method, to allow the destination node of the page\n   to deallocate the interport communications. This means that the NewChat\n   door does not have to wait on a reply to the message from the destination\n   node.\n\n     Made some cosmetic changes.\n\n     Fixed a problem with semaphore releasing in versions prior to 3.3\n   if a user ran out of time in the chat door and then re-entered the door\n   then it would cause a multinode lockup.\n@endnode\n','\n',char(10)),'{"PRIORITY":"<xx>","ACCESS":"this"}','auto-added',355655,2,0,NULL,NULL,'obs_ae38','scan',1780048650);
INSERT INTO door_catalog VALUES('od_bs15','OD-BS15.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OD-BS15.LHA',NULL,'XIM','Best-Scan.XIM',NULL,'CALYPS0/G0D','OD','\____/   ______//    /  \\______   \____/ \_/    \_   \/    /\   \|    |\   \_/ \     |    \    \/   /|   /\/   /',replace('  ______/\________ _____/\ ________________\n  \____/   ______//    /  \\______   \____/\n    \_/    \_   \/    /\   \|    |\   \_/\n      \     |    \    \/   /|   /\/   /\nEXPRESS\__  _____/\_______/ |___\  __/DESIGN\n<---------\/- ·p·R·E·S·E·N·T·S· -\/-------->\n       Best-Scan V1.5 by CALYPS0/G0D !\nThe FASTEST and BEST-LOOKING Newfiles Door !\n New Update ! Now it is FREEWARE ! Use it !\n  ASM XIM POWER ! Why use something else ?\n<------------------------------------------>\n','\n',char(10)),'Best-Scan.Doc',replace('                                    .    :\n.______ ______________.   __________|    |____ __________ _____. __________.\n|:::· ·/    _____     |__/__  _    ¬\     _  ¬\______   ¬\     |_____· ·:::|\n|:·  _/    |    ¬\_   |    ¬\_ |     \_  |     \_         \_   |    ¬\_   :| \n|·   \     |      /   |      / |      /  |  ÷e÷ /   |      /   |      /_ _·|\n|.  .\\__________/__________/________/_________/__________/__________//   .|\n|             .__                        .    ·                            |  \n|  _______ ___| ¬\ ________ _________ ___|    :_______  _________________  |\n: /  _   ¬\   |   \       ¬\_____   ¬\  _     ¦  _   ¬\/     ____       ¬\ :\n_/    |    \_ |    \_  |    \_ _/   _/   |    :   |    \____    ¬\_  |    \_\n\     |     / |     /  ______/ \    \__  |    :   |     /   |     /  ______/\n:\_________/_______/____________\     /_______¦________/_________/_______ _: \n+--------------------------------\___/-------------------------------------+\n¦                                                                          ¦\n:                                                                          :\n                                    PRESENTS\n\n                    Best-Scan V1.5 coded by CALYPSO/GOD !\n\n    PROFESSIONAL TOOLS FOR PROFESSIONAL SYSOPS - GET THE REAL QUALITY !\n\n\nWHAT''S THE USE OF THIS TOOL ?\n-----------------------------\n\n        This is the FASTEST and BEST-LOOKING newfiles door ever !!!\n\n        It can be used as N and F command !\n\n        Fully configurable !\n\n        You will LOVE it !\n\n  .-----------------------------------------------------------------------.\n  |       PLEASE READ THE REGISTER!.TXT INCLUDED IN THIS ARCHIVE !!!      |\n  `-----------------------------------------------------------------------''\n\n        I think it''s worth to register my utils... they are the BEST\n        and so thank me for my work, dudes ! (not very expensive)\n\n        If you think it''s not necessary, then you can wait long\n        for an update ! Will make updates probably for registered\n        users only !\n\n\n	Note : This door is 68020+ optimized !\n	------\n\nHOW TO INSTALL :\n----------------\n\n        S-Express and /X 2.x :\n        ----------------------\n\n        Copy these files in the archive to your directories,\n        they are :\n\n        BBS:Doors/Best-Scan/Best-Scan.Config\n        BBS:Doors/Best-Scan/Best-Scan.Doc\n        BBS:Doors/Best-Scan/Best-Scan.Help\n        BBS:Doors/Best-Scan/Best-Scan.XIM\n        LIBS:AEDoor.library (© Sintax)\n\n        Append the BBS:Commands/BBS.CMD to your BBS.CMD !\n\n        If you use a 0.38x version of S-Express then copy also\n        the ''Best-Scan.XIM'' as ''NewFiles'' to your BBS:System Dir !\n\n        \n        /X 3.x :\n        --------\n\n        Copy these files in the archive to your directories,\n        they are :\n\n        BBS:Doors/Best-Scan/Best-Scan.Config\n        BBS:Doors/Best-Scan/Best-Scan.Doc\n        BBS:Doors/Best-Scan/Best-Scan.Help\n        BBS:Doors/Best-Scan/Best-Scan.XIM\n        BBS:Commands/BBSCMD/N.Info        \n        BBS:Commands/BBSCMD/F.Info        \n\n	If you don''t have it : Create a file called ''NDirs'' in every\n	Conference with the Number of Dirs you have, e.g. :\n\n	------------(cut here)-------------\n	2\n	------------(cut here)-------------\n\n\n        No worries, the door refers to DOORS: , so you can put\n        your doors wherever you want !\n\n\n        Now take a look at the Best-Scan.Config :\n\n\n        ------------(cut here)-------------\n        255                                     ; Access Level for Hold Dir !\n        [0m                                    ; Filename Color\n        [35m                                   ; Flag Color (P/N)\n        [33m                                   ; Size Color\n        [36m                                   ; Date Color\n        [0m                                    ; Description Color\n        [35m ~\/\)=====[[32m Black Moon [35m]====(/\/~ [36m@@-@@-@@ [35m~\/\)====[ [32mBlack Moon [35m]=====(/\/~\n         [32m-+[35m( [33m@@ [35m)[32m+-[0m \n        ------------(cut here)-------------\n        \n        The next-to-last line is the line you want to show when a new day\n        begins ! It MUST include the ''@@-@@-@@'' cause this will\n        be replaced by the date !\n\n        The last line is the text shown on flag-by-number... this\n        text has to be 10 chars without the colorcodes !!!\n        ''@@'' will be replaced with the filenumber !\n\n        If you upgrade from V1.0 then be sure to change your config !\n        \n\n        Next you should make ALL (in every conference) your\n        File-Help.txt(.gr) e.g. in this way :\n\n-------------------------------(cut here)--------------------------------\n\n          Dir 1 ----> Deleted files !\n\n          Dir 2 ----> Files online !\n-------------------------------(cut here)--------------------------------\n\n        Means for every directory you have, you need a blank line and\n        then the description to the directory (2 lines for each\n        directory) !\n\n        I think you got it... if you make it in an other way it will look\n        ugly !\n        \n        So you are ready to go ! Enjoy !\n\n  .-----------------------------------------------------------------------.\n  |       PLEASE READ THE REGISTER!.TXT INCLUDED IN THIS ARCHIVE !!!      |\n  `-----------------------------------------------------------------------''\n\nDOOR FEATURES:\n--------------\n\n        I think you will see by yourself.. here some hints which\n        are not seen on the first look :\n\n        Default Dir is U, so it''s enough when you write ''N S'' or ''N -1'' !\n \n        Use option S (e.g. N S U S) to show single line mode ! This\n        will show only the first line of each description !\n\n        Use option NS (e.g. N T NS) to scroll Non-Stop !\n\n        Use option # (e.g. N S #) to use flag-by-number !\n\n        All special commands can be stacked, e.g. :\n\n                N S U NS #\n             or N T # NS\n             or whatever you like...\n\n        On wrong inputs Best-Scan shows the Help-Page !\n\n\n        At the prompt use these commands :\n \n        C - Clear Screen and continue scrolling (fucking fast) !\n        N - Stop scrolling !\n       NS - Switch to Non-Stop scrolling !\n        F - Flag Files ! Use SPACE to separate filenames/numbers !\n            (Write perhaps an EALL, some users don''t recognize this !)\n        V - View a special file ! (Done for Big Boss, hi mate !)\n\nLAST WORDS :\n------------\n        \n        Now have fun with this great tool !\n\n        For Bugs (there are none), Ideas (yeah !) or just for fun\n        call my BBS :\n\n                 bLACK m00N            G·O·D GERMAN HEADQUARTERS !        \n                ~~~~~~~~~~~~     \n               +49-7071-51144         L^O^G^I^C wORLDHEADQUARTERS !\n                                    iLLUSION/gELBSUCHT hEADQUARTERS !\n          (3x 16.8 Dual Ringdown)   bIZARRE fASCINATION hEADQUARTERS !\n\n          Current NUP : ANALYSIS\n\n        See ya soon mates...\n                                                   Calypso !\n                                                   ~~~~~~~\n\n  .-----------------------------------------------------------------------.\n  |       PLEASE READ THE REGISTER!.TXT INCLUDED IN THIS ARCHIVE !!!      |\n  `-----------------------------------------------------------------------''\n\nHISTORY :\n---------\n\n        V1.0    -       First Public Release !\n\n        V1.5    -       Some small changes, bug fixes.\n                        Fucking cool flag-by-number !\n                        \nFUTURE :\n--------\n\n	V2.0	-	User configurable !\n\n\nTHANX TO :\n----------\n\n        Special thanx go to Dalai Lama for the idea to the fastest\n        search-algorithm ever !!!\n\n\n        My beta-testers :\n        -----------------\n                Zion/Zions Hideout\n                Rotor/Gates of Asgard\n                Freddy Krueger/Boiler Room\n                BloodWolf/Mortuary\n\n        You also can reach me on these boards !\n\n\nGREETINGS:\n----------\n\n   - Runt&Scottie - Polaris - Skin - XAD - Deltaforce - Andy - Wedlock -\n     - Blackbird - Planet Master - Sid Vicious - Sigma Seven - Whiz -\n      - Linebacker - Raider - Mitch - Mr.T - Samir - Power - Sisko -\n              - Atomix - Castor - Scout - Ventor - Nocturne -\n\n                       - All GOD and LOGIC Members -\n\n··············································································\n\n          - GLOBAL OVERDOSE GERMAN HQ - LOGiC WHQ - iLLUSiON HQ -\n               _ ________           _ ______________\n         /\_______    _ /     _____   ________     /__: _____  sYSOPS:\n        /____  _ /    //_____/o  _/___  /    /____/   |/    /  """""""\n      _____:/  //     /     //   \    \/    /    //   /    /   cALYPSO/GOD\n     /     |\  /__________ /.   /_\   /________ /.    \    \   cASTOR/PDX\n __|/____________\       \/_____________\     \/______|\____\  mIKE & dAVE/CLS\n   |                                                  :        sPIKE\n                      ·b·L·A·C·K· ·m·O·O·N·       :_______|__\n         /\ __ /\             _______________     |    _ /|    cALL :\n        // \\//  \____________\________   _ /____ |    //      """" "\n       /.   \/    \________   _ /     /   //     \|   o/     +49-70-eLITE !\n      /    \  /    \      /   //\    /    /|      \  ./      """"""""""""\n     /      \/______\    /    /  \_______/ |    \    /   3 nODES rINGDOWN !\n    /_______|        \_______/             |_____\  /    " """"" """"""""\n            :                                Sk!n \/   aLL nODES 16.8 DST !\n                                                       """ """"" """" """\n     rUNNiNG (LATEST!) S-eXPRESS - sUPPORTiNG aMiGA aND cONSOLE oNLY !\n         aLL {<GOD>|<LOGiC>|<iLLUSiON>}-rELEASES fREE dOWNLOAD !!!\n          cALL nOW ! LOTSA iNTERNATiONAL cALLERS ! SiMPLY eLiTE !\n','\n',char(10)),NULL,'auto-added',54316,5,0,NULL,NULL,'od_bs15','scan',1780048650);
INSERT INTO door_catalog VALUES('odir130','ODIR130.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ODIR130.LHA',NULL,'XIM','ODIR.x',NULL,NULL,NULL,NULL,replace('Filelist downloader\n','\n',char(10)),'odir.guide',replace('@database ODIR.guide\n\n@node Main "ODIR V1.3 - ©1993 GrooVy G Prøductiøns"\n                   __________________________________\n\n                              O-DIR V1.3\n                    A Directory Listing Uploader for\n                            AmiExpress BBS\n                   __________________________________\n\n                          Program by GrooVy G\n\n                       @{" Introductory Description " link "Intro"    }\n                       @{"       Installation       " link "Install"  }\n                       @{"          Usage           " link "Usage"    }\n                       @{"       Other Shtuff       " link "Shtuff"   }\n\n@endnode\n\n@node Intro "O-DIR Introduction"\n\nWhat''s the deal??  I haven''t seen any  other /X doors that do this one\nsimple task:  Archive the file listings  and  upload them to the user.\nInstead, the user is forced to use inconvenient and time-wasting text-\ncapture methods.  This program  uses  the  LHA  archiver  to, upon the\nuser''s  request,  pack  all   directory   listings   for  the  current\nconference, and ZModem upload them   to   the  user.   The  design  is\ncrude at the moment, but shall be expanded soon.\n\n@endnode\n\n@node Install "O-DIR Installation Procedure"\n\n\n                         Installation Instructions:\n\n                        @{"For AmiExpress Version 3.x" link "3.0" }\n                        @{"For AmiExpress Version 2.x" link "2.0" }\n\n@endnode\n\n@node 3.0 "O-DIR Installation for /X 3.0+"\n\nTo install O-DIR you  must  have  an  assignment  to a directory named\n"DOORS:" (Most doors use this path...)  and into this directory should\nbe dragged the drawer named  "ODIR_Dir",  (included with the archive).\nInto  your  "BBS:Commands/bbscmd"  directory  should  be  dragged  the\nODIR.info file, (also present in  the  archive).   The door can now be\ncalled by typing "ODIR" at a menu prompt.\n\n@endnode\n\n@node 2.0 "O-DIR Installation for /X 2.x"\n\nTo install O-DIR you must edit the "BBS:Commands/bbs.cmd" file, adding\nto it:\n\n"ODIR        XS010DOORS:ODIR_Dir/ODIR.x"\n\nThis line is subject to error....\n\n@endnode\n\n@node Usage "O-DIR Usage"\n\nOnce ''ODIR'' is typed at the main prompt, the user is to enter the\ndate from  which entries  should be archived.  If the users types\n''A'', all  entries will be packed.  You  MUST have LHA in the ''C:''\ndirectory for this to work.   If any problems arise, they will be\nnoted in  the activity log.   After the listings have been sorted \nand archived, they will be sent via ZModem to the user.\n\n\n@endnode\n\n@node Shtuff "O-DIR Post-Boredom Addendum"\n\n\n         If you encounter any problems with this version (1.3)\n            or wanna suggest as to the improvement of O-DIR\n               contact me, (GrooVy G) on Sarcophagus BBS:\n\n                       (<·   +1 503 548 0532   ·>)\n\n        Sarcophagus is now accepting offers for Cosysops and Groops\n                    that need a(nother) headquarter...\n\n                         ------------------------\n\n       If you want the C source to this and would like to benefit a\n     malnourished high-school student, stash a fiver and your address\n                    in a heavy envelope and send it to:\n\n                                 GrooVy G\n                                PO Box 4361\n                          Sunriver, OR 97707-1361\n                                   USA\n\n      Also, I am looking for a groop cuz my current one, (TeNeBres),\n         is getting boring...   Contact the above addy or BBS if\n                   ya needz a coder/graphician/musician.\n\n\n\n\n\n\n                             Until Later, GVG\n\n@endnode\n','\n',char(10)),NULL,'auto-added',11573,3,0,NULL,NULL,'odir130','scan',1780048650);
INSERT INTO door_catalog VALUES('ody_stat','ODY-STAT.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ODY-STAT.LHA','x-stats','XIM','.------------------------------------------.',NULL,NULL,'ODY','|  ÷/X÷P÷R÷E÷S÷S÷-÷U÷S÷E÷R÷-÷S÷T÷A÷T÷U÷S÷  | |  --------------------------------------  | |   oRdYNe''s /X USER STATUS DOOR - BETA    |',replace('.------------------------------------------.\n|  ÷/X÷P÷R÷E÷S÷S÷-÷U÷S÷E÷R÷-÷S÷T÷A÷T÷U÷S÷  |\n|  --------------------------------------  |\n|   oRdYNe''s /X USER STATUS DOOR - BETA    |\n|                                          |\n| Released at the request of those sysops  |\n|   who saw this door on beta-test and     |\n|      wanted a copy for themselves.       |   \n|                              9-Feb-1996  |\n`------------------------------------------''\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-23-18  TIME: 12:05:56  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,NULL,7826,3,0,NULL,NULL,'ody_stat_x_stats','scan',1780048650);
INSERT INTO door_catalog VALUES('offmes10','OFFMES10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OFFMES10.LHA','OffMesser','XIM','8',NULL,NULL,NULL,'|              OffMesser V1.0              | |    THE utility for Sysop''s using /X !    | |------------------------------------------|',replace('.------------------------------------------.\n|              OffMesser V1.0              |\n|    THE utility for Sysop''s using /X !    |\n|------------------------------------------|\n|Features: * NO login needed!              |\n|          * Global and local message scan |\n|          * Post and reply message        |\n|          * Easy to use GUI               |\n`------------------------------------------´\n','\n',char(10)),'OffMesser.txt',replace('\n   OffMesser V1.0 by Jonas Niklasson ©1995\n\n\n\nINTRODUCTION\n\n    OffMesser is an excellent tool for sysop''s using AmiExpress. \n\n    Every time You normally scan letters You will have to login localy\n   and use a global message scanner... Not anymore, because OffMesser\n   allows You to scan for letters in any conference, delete, reply\n   and post messages without having to login.\n\n    The OffMesser opens on any public screen and the user-interface is\n   constructed so that anyone can use it. Most of the gadget''s responds\n   to hotkeys as well.\n\n\n\nDISCLAIMER\n\n    There is no part in the program that has any intention to harm your\n   system. But I can not be held responsible for any accidents due\n   to missuse of OffMesser.\n\n\n\nREGISTRATION\n\n    This is a easy part. All functions that post a message is locked\n   if You don''t have a proper keyfile. The registration for the\n   key file will cost You 50:- skr.\n\n    To register call me, Jonas, at +46 40-89398 and I will inform You\n   how to send the payment, and when I recieve it I will leave the\n   keyfile at your board.\n\n\n\nPLEASE NOTE\n\n    OffMesser can be used at the same time as users are using /X, BUT\n   if You are logged in as sysop, it is wise to have OffMesser in the\n   iconified state.\n\n\n\nINSTALLATION\n\n    Place the program and it''s icon anywhere You like, it doesn''t matter.\n   The info file called OMAPP.INFO should be placed in Your S: together\n   with the keyfile (If You have one)\n\n    Your amiexpress must be located at the assign BBS: otherwhise the\n   program will fail. After that OffMess will find out itself\n   where your conferences are located.\n\n\n\nHOW TO USE IT\n\n    There are three major functions:\n\n\n   POST MESSAGE\n\n       As the normal E command. You will be presented a list of the\n      users, including ALL and EALL. Simply press on the desired one.\n\n       Enter the subject as usual.\n\n       When You enter the text, You can easily edit a proceding line\n      by just clicking on it.\n\n       With the cycle gadget You can at any time change between\n      PUBLIC and PRIVATE message.\n   \n       When You are finished You press DONE, and if You change your mind,\n      simply press abort.\n\n\n   GLOBAL SCAN\n\n       Enters every conference in the order that they appear in the icon. It\n      works just like SCAN CONFERENCE with the exception that You can\n      exit with the ABORT-button.\n     \n\n   SCAN CONFERENCE\n\n       With the little button just to the right You can choose which\n      conference to scan.\n\n       The to buttons << and >> allows You to move forward or backward\n      in this conference. The arrow-keys have the same function. Otherwhise\n      You can jump directly to a message by entering it''s number.\n\n       The up and down arrow-keys functions as the buttons to the left.\n\n       REPLY allows You to answer the message. First You are asked to\n      enter the lines You want to quote. Either enter the lines by hand\n      or click on the appropriate lines with the mouse. After that you\n      go to the POST MESSAGE routine.\n\n       DELETE has no shortkey. It does what it sounds to do.\n\n       DONE exits the SCAN\n\n   \n   MINOR FUNCTIONS OF NOTE\n\n       The window is quite big because everything had to fit. In the\n      right bottom corner You will find a little button which will\n      iconify OffMess, so You can have it running all the time.\n\n       Whenever a user is currently in a conference messagebase, the\n      program will halt until it can save safely. When this\n      situation occurs You will be informed in the status row.\n\n       The program takes for granted that You, the sysop, is\n      the first user on the base (i.e. user.data). If not You\n      must change this otherwhise the letters will be posted\n      in the first name that occurs in the user.data.\n\n       If You delete a headerfile and mailstats in a conference, You\n      MUST replace those before scanning that peticular conference.\n\n\n\nLAST WORD\n\n    If You are a regular user of AmiExpress You will have no problem\n   with using this program. My intention was to make it as similar\n   as possible, and at the same time, a powerful tool.\n\n   Hope You enjoy it, Jonas Niklasson\n\n\n\nHISTORY\n\n   V1.0  11-11-95  First official release\n\n','\n',char(10)),NULL,'auto-added',27299,5,0,NULL,NULL,'offmes10','scan',1780048650);
INSERT INTO door_catalog VALUES('ogn_nc12','OGN-NC12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OGN-NC12.LHA',NULL,'XIM','noC-COUPON.x',NULL,'nocTurne','OGN','|                         | _______ |_________________________|_______ /   _   \/   ___/   \   ___   |    /   _   \',replace('        _._________________________._\n         |                         |\n _______ |_________________________|_______\n/   _   \/   ___/   \   ___   |    /   _   \\n\_______/____j /_____\____/   l___/____/___/\n         |        _ __ _______/    |noC\n _ ______| ________________________|_____ _\n         `                         ''\n noC-COUPON V1.2O by nocTurne deSign/ORiGiN\n Free-Download Maker - Bug-Fix/New Features\n _ ______,_ __________________ _ __,_____ _\n         |                         |\n','\n',char(10)),'noC-Coupon.doc',replace('.                                     _ __:__ _                  _ __ _____:__\n: _______  __  ____________  __  ______   ¦                                :\n: \_____ \/  \/ __/ __/ /  \/  \/ ____/ d      noC-Coupon Version 1.20     ¦\n¦___ / / / / / / / / / / / / / / __/  : e :  (C)1994 nocTurne deSign/OGN   ¦\n\  // / / / / / / / / / /\/ / / / //\ ¦ s ¦      - --------------- -       |\n|\/ \/\/\__/\__/\/\__/\/  \/\/\__//__\| i |  Comprehensive Free-DL System  |\n|___________________________ _ _ __ __j g l_ _ __ _________________________j\n¦                                     \ n /\n:                                      \ / Users of 1.0 should READ "CHANGES"\n                                        Y\n_ _:____________________________________j\n   ¦\n   |  P·R·O·G·R·A·M   D·E·S·C·R·I·P·T·I·O·N\n_ _¦__________________________________________________ __ _\n   :\n\n    noC-Coupon allows sysops and other appointed users to EASILY make files\n    downloadable  without any loss of credits to the leecher.  When used in\n    conjunction  with noC-AutoFree, creating and maintaining free-downloads  :\n    is MUCH less of a hassle.                                                ¦\n                                                                             |\n_ _:_________________________________________________________________________|__\n   ¦                                                                         ¦\n   |  I·N·S·T·A·L·L·A·T·I·O·N                                                :\n_ _¦__________________________________________________ __ _\n   :\n\n    This program requires OS2.0 or greater.\n\n    Simply copy the "noC-Coupon" drawer into "DOORS:" and mount the door as\n    is  convention  with  your particular version of Ami/Sigma Express.  (A\n    BBSCMD icon is provided for 3.xx users).\n\n    Within  the  program  drawer there is a sample configuration file which\n    should  be  edited,  called "noC-Coupon.config".  You may configure the\n    following:\n\n    ACCESS:\n    Those  with  security levels equal to or greater than the number placed\n    here  will  automatically  gain  access to  the program.  Omitting this\n    parameter will mean only explicitly defined users may use noC-Coupon.\n    (Example: "ACCESS=200")\n\n    USER.[NUM]:\n    You  may appoint up to 40 users to have access to this utility.  As you\n    define  each user you must increment the number in [NUM].  Correct caps\n    are not neccessary.  (Example: "USER.1=nocTurne" "USER.2=Jimmy Hoffa")\n\n    COMMENT.[NUM]:\n    Comments may be directed to individual users of the util when they use\n    it.  (Example: "COMMENT.1=Dont make EVERYTHING free, man!" "COMMENT.2=\n    Where the hell ARE you?")\n\n    FREEDLTEXT.[NUM]:\n    You may  define the  texts which will  denote a  free-download  in the\n    file listing here.  Up to 20 may be set which the user may choose from\n    during program usage.  They will  automatically be indented 35 spaces, \n    so keep them  under 45 chars in length.   ANSI codes may be used,  but\n    if you do you should terminate the text with an ESC[0m sequence.\n\n    (Examples: "FREEDLTEXT.1=>>>FrEe dOwnLOad, LeECHES!" \n               "FREEDLTEXT.2=>>>A FREE RELEASE FROM THG!" ) \n                                                                             ¦\n_ _:_________________________________________________________________________|__\n   ¦                                                                         ¦\n   |  P·R·O·G·R·A·M   L·O·G·I·C                                              :\n_ _¦__________________________________________________ __ _\n   :\n\n    When  first  run,  (after  typing  ''COUP''),  the program will check the\n    user''s  security  level  in comparison to the access level required for\n    entry  (if  defined).    If the user fails this check, his name will be\n    searched  for  in  the configuration file.  The program will exit if he\n    fails this as well.\n\n    The user, if passing these security measures, will then be greeted with\n    any COMMENT to him that may exist in the configuration file.  Following\n    he  will  be prompted to enter the COMPLETE name(s) of file(s) he wants\n    to  make  free-downloads.    Hitting  the  enter key on a blank line or\n    entering 20 filenames will progress to the next stage.\n\n    The user may then choose from the available FREEDLTEXT''s or press Enter\n    to abort the  entire operation.   The text he chooses  will be appended\n    to the  file-description(s) of  the  files he  has chosen to make free.\n    A request will be posed to the user verifying that he DOES in fact want\n    to make the files he listed free.\n\n    The  user will then be asked if he wishes the file descriptions altered\n    to  denote the leechability of the files he entered.  If he chooses not\n    to,  the  files  will be made free, but their descriptions will give no\n    indication of this.\n\n    If he DOES choose to, the UPLOAD file-listings will be searched for the\n    descriptions  to  alter.    After  each  entry  is  found,   the edited\n    description  with  the  appended  FREEDLTEXT  will  be shown.  Once the\n    file-listing  has  finished  being  processed,  another   request   for\n    verification  will be posed.  The user may opt to bail out, or continue\n    and have the edited listing saved.\n\n    The  last  stage  entails  the  actual  files  being   tagged   so that\n    Ami-Express  will recognize them as being free.  The success or failure\n    to change each file will be shown.\n\n    Finally,  Coupon will ask the user if he wishes an EALL message be sent\n    notifying users that these file(s) are free.   He may then enter a one-\n    line tag which will be appended to the message.\n\n    Of course during the course of program usage, the user will be notified\n    of any errors that may take place, and they''ll be handled appropriately. :\n                                                                             ¦\n_ _:_________________________________________________________________________|__\n   ¦                                                                         ¦\n   |  C·H·A·N·G·E·S                                                          :\n_ _¦__________________________________________________ __ _\n   :\n\n    VERSION 1.00 -> 1.20:\n\n    * Major buffer overflow bug repaired.\n    * Allows EALLS regarding the files to be made.  A message\n      with the files and their descriptions, plus an optional\n      one-line message may be sent.\n    * Now accepts arguments. (eg, "COUP foo.lha bar.dms").\n    * Multiple FREEDLTEXT''s may be set, for the user to choose from.\n    * Added quick user docs ("COUP ?")\n    * Will now search ALL upload dirs for physical files.\n    * Design alterations                                                     :\n                                                                             ¦\n_ _:_________________________________________________________________________|__\n   ¦                                                                         ¦\n   |  C·R·E·D·I·T·S                                                          :\n_ _¦__________________________________________________ __ _\n   :\n\n   noC-COUPON  is coded  by  nocTurne deSign/Origin  in 1994.  Any  questions\n   regarding  the  use  of  this program should be addressed to "nocTurne" on\n   Mortuary,  Domino  Effect,  or  any other board you see me on.  Or you may\n   direct mail to "[email removed]". \n\n   -------------------------------------------------------------------------\n   * This  utility is BACKDOOR and VIRUS FREE.  All nocTurne deSign products\n     are created with a dedication to quality and stability.\n   -------------------------------------------------------------------------\n\n   Thanks to:\n   SHADOWER/DARK TOWER - The creative mind behind the EALL idea.\n    RAD!/MEGA-LO-MANiA - For criticizing the name of this ute, and testing.\n\n   No Thanks to:\n   BLooDWoLF/MORTUARY - You dunno what you''re missing, big boy.              :\n                                                                             ¦\n_ _:_________________________________________________________________________|__\n   ¦                                                                         ¦\n   |  T·H·E  E·N·D                                                           :\n_ _¦__________________________________________________ __ _\n   :\n','\n',char(10)),'{"ACCESS":"200\")"}','auto-added',17888,3,0,NULL,NULL,'ogn_nc12','scan',1780048650);
