INSERT INTO door_catalog VALUES('online01','ONLINE01.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ONLINE01.LHA',NULL,'XIM','LE-win5-96.exe',NULL,'BLACK',NULL,'ONLINE V0.01 BY BLACK BEARD & THE WIZ! TELNET SERVERS STAY ON LINE 24HRS WITH YOUR PROVIDER. YOU DONT NEED A DEDICATED',replace('=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n  ONLINE V0.01 BY BLACK BEARD & THE WIZ! \n  TELNET SERVERS STAY ON LINE 24HRS WITH\n YOUR PROVIDER. YOU DONT NEED A DEDICATED\n  LINE. THIS WILL KEEP YOU ON EVEN WITH\n  THE 10 MIN INACTIVITY! WILL CALL BACK\n FOR YOU IF CARRIER IS LOST. 24HR''S ONLINE! \n=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n[9NoDeZ]=-[ mASTURBATiON sTATiON ]-=[TELNET]\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/