INSERT INTO door_catalog VALUES('onx_cs12','ONX-CS12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ONX-CS12.LHA','axstatus','XIM','axstatus',NULL,'Axetro/Onx:','ONX','______       __________       _________ .. /      \______\__      /_______\       /. : /       \\       /    //       //      / :',replace('      Onyx Amiexpress Division Presents\n    ______       __________       _________\n.. /      \______\__      /_______\       /.\n: /       \\       /    //       //      / :\n:/________________/     /_______//      /  :\n:               /_______\       /_______\  :\n:ColliStatus v1.2ß - (c) 1997 By Axetro/Onx:\n:------------------------------------------:\n: User Status door with Some nice Features :\n:..........................................:\n','\n',char(10)),'axstatus.doc',replace('                                     ________           _ ______________ __\n         ______________ __________ __)    __/_____                       \//\n         \     _    __/_\_       /   \    \      (_____                   ø\n          \    \    \    /      /     \___.\    _/    /.    ·OnyX!·      /\n          /_________/\  /_______\______\  |_____\______|\n      <- -------------\/-Mo!\aL- ----------------------- -             /\n\n                             .x(· presents ·)x.\n\n               ColliStatus v1.2 a Status door for AmiExpress\n\n                         Copyright ©1997 by Axetro\n\n                 Permission is granted to freely distribute\n               this product for non-commercial purposes only,\n                  as long as all files remain unmodified.\n\n\n\nArchive (ONX-CS12.LHA) Contents:\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n   Filename:        Size:  Description:\n\n   axstatus         7492   XIM Status Door\n   axstatus.doc     2565   Documentation File for ColliStatus\n   file_id.diz       444   File description\n\n\nIntroduction\n¯¯¯¯¯¯¯¯¯¯¯¯\nColliStatus is a door that shows the user statistics, with some nice\nfeatures that the builtin status viewer in Amiexpress, Fame and\nSigmaExpress doesn''t have.\n\n\nFeatures\n¯¯¯¯¯¯¯¯\nIt shows all the most inportant things like uploaded/downloaded bytes/files\netc, and if you have telnet nodes it will show the ip address if you are\nconnected to inet(only amitcp)\n\n\nRequirements\n¯¯¯¯¯¯¯¯¯¯¯¯\nAn Amiga with OS 2.0 or higher.\nAmiExpress, it also works with SigmaExpress and FAME\nAmitcp, if you want it to show your ip number when you''re connected to\ninet and have your telnet nodes up.\n\n\nInstallation\n¯¯¯¯¯¯¯¯¯¯¯¯\nJust copy the axstatus file to your favorite directory and make an icon\ncalled S in your bbs:commands/bbscmd/ dir and if you want it to be started\nin the login also copy it to bbs:commands/syscmd/. If this doesn''t work\nyou shouldn''t have a board..\n\n\nConfiguration\n¯¯¯¯¯¯¯¯¯¯¯¯¯\nThere are no configurations, except setting up the icon like a normal\n/X door icon.\n\n\nGreetings\n¯¯¯¯¯¯¯¯¯\n                          Greetings goes out to:\n\n  herakles·dmg·doyle·orlando·orion·mogue·boheme·franky·folar·newt·converse\nvezire·trance·nastyboy·godfather·octoplex·sealapex·crusader·candyman·shelter\nblack line·jupiter8·acidflash·zap·wraith·cosmo·size·twilek·soxius·slowrider\n james west·the shining ones·sticky·james dean·ramis·citruz·the mask·bubba\n hostile·mr.coke·morgoth·magz·energy·2fast·boo-ya·nebraska·axeblade·harpoon\n\n                                         - and everyone else i have forgot..\n\n','\n',char(10)),NULL,'auto-added',12973,2,0,NULL,NULL,'onx_cs12','scan',1780048657);
