INSERT INTO door_catalog VALUES('opager13','OPAGER13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OPAGER13.LHA',NULL,'XIM','LE-win5-96.exe',NULL,NULL,NULL,'===========|   ¬|   ¬|  ¬|   ¬|=========== :::::::::::|    | .  | |_| .  |::::::::::: ::AtomiX:::| |  |    |_  |    |:::AtomiX::',replace('            ____ ____ ___ ____\n===========|   ¬|   ¬|  ¬|   ¬|===========\n:::::::::::|    | .  | |_| .  |:::::::::::\n::AtomiX:::| |  |    |_  |    |:::AtomiX::\n:::::::::::| |  | |  | | | |  |:::::::::::\n===========|_|__|_|__|___|_|__|===========\n\X/\X/\X/   ·P·R·E·S·E·N·T·S·    \X/\X/\X/\n /X 2.xx    Operator Pager V1.3    /X 3.xx\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.        