INSERT INTO door_catalog VALUES('opq_hs0','OPQ-HS0.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OPQ-HS0.LHA','HypnoStats','XIM','___ ___ ___',NULL,NULL,'OPQ','|°. Y°. Y°. |-. Opaque Developers Division . | | | | | | | ]          Presents          [ | | | | | | | ]-==========================-[',replace(' ___ ___ ___\n|°. Y°. Y°. |-. Opaque Developers Division .\n| | | | | | | ]          Presents          [\n| | | | | | | ]-==========================-[\n| | | | | | | ]      HypnoStats v0.1b      [\n| | | | | | | ]-==========================-[\n| | | | | | | ]                            [\n| | | '' | ` | ]/X XIM Status door with nice[\n| | | __|__ | ]"slow    draw"   and   "char[\n| | | |   | | ]     shuffle" effects.      [\n| | | |   | | ]                            [\n|___|_|---|_|-''                            `\n','\n',char(10)),'HypnoStats.doc',replace('############################################################################\n\n                                 HypnoStats\n\n                           Coded by Melanc/Opaque\n\n                                ©1997 Opaque\n\n\n                      !! This Project Is ShareWare !!\n\n############################################################################\n\n\n\n\n-==========================================================================-\n                                INTRODUCTION\n-==========================================================================-\n\nThis is an AmiExpress XIM status door to replace the original. There''s\nnothing much to it except from the "slow draw" and "char shuffle" effects.\nWhat I''m saying is that it is better looking than any other! :)\n\n\n\n\n-==========================================================================-\n                                 DISCLAIMER\n-==========================================================================-\n\nThis software package (program and documentation) is provided "as is" and\ncomes with no warranty, either expressed or implied. The author is in no way\nresponsible for any damage or loss that may occur due to direct or indirect\nusage of this software. You use this software entirely at your own risk.\n\n\n\n\n-==========================================================================-\n                                DISTRIBUTION\n-==========================================================================-\n\nThis EVALUATION package is SHAREWARE. This means that you are allowed to\nredistribute this package as long as you follow these points:\n\n * Everybody who uses or distributes this software automatically accepts the\n   Disclaimer, Copyright and Usage/Distribution conditions.\n\n * This package may be freely distributed via BBS''s, InterNet/UseNet,\n   software libraries such as Fred Fish and AmiNet CD-ROM, and other similar\n   electronic channels.\n\n * Disk magazines and services that charge extra for file transfers may NOT\n   distribute it without written permission by the developer.\n\n\n\n\n-==========================================================================-\n                                REQUIREMENTS\n-==========================================================================-\n\nThe following is required to run the door:\n\n * OS 1.3 or newer!\n\n * AmiExpress v4.x!\n\n\n\nIt has been tested on the following system configurations:\n\n                   A2000/030/882/OS3.1 - AmiExpress V4.20\n\n\n\n\n-==========================================================================-\n                                INSTALLATION\n-==========================================================================-\n\nJust drag the BBS drawer the the directory where you keep your BBS drawer!\n\n\n\n\n-==========================================================================-\n                                   USAGE\n-==========================================================================-\n\nType "S" at the main prompt of AmiExpress.\n\n\n\n\n-==========================================================================-\n                                  REGISTRATION\n-==========================================================================-\n\nThe registered version contains:\n\n * Full ANSI colors.\n\n * More info.\n\n * Possible customized look/info.\n\n\n\n                 Registration costs 25 dkk, 8 D-Mark or 5 US$.\n\n\nYou can register by using one of the following methods:\n\nDenmark:\n\n Pay 25 dkk on the Giro account number below. Remember to write your full\n name, address and EMail address on the Giro form. If you haven''t got an\n Email address then we''ll send a disk containing the newest version.\n\n\n\nOther:\n\n Send the appropriate amount of money either CASH or using an EuroCheque to\n The Opaque Organisation. Remember to include your full name and address AND\n your EMail address if you want to receive the full version via EMail. If\n you want to receive it via snail mail, you must also include a DD disk.\n\n\n\nIf you want to receive your registered version using EMail you''ll\nautomaticly receive any new updates for free. Those who needs shipping via\ndisk has to send us a disk including name, address and money for postage!\n\n\n                  Expect a couple of weeks of delivery though\n                      it shouldn''t last more than a week.\n\n\n\n\n-==========================================================================-\n                                    HISTORY\n-==========================================================================-\n\n############################################################################\n### 01-Mar-97 (v0.1) #######################################################\n############################################################################\n\n * The developing started...\n\n * Rewritten to work using my amix handler routines!\n\n * Cleaned up a few things and added a version string.\n\n * Released!\n\n\n\n\n-==========================================================================-\n                                   TO DO\n-==========================================================================-\n\nThis is a list of improvements (in no particular order) that should be\napplied to the project:\n\n[On Hold]\n\n * An AmigaGuide manual!\n\n * An installer script.\n\n\n\n[In Progress]\n\n\n\n\n-==========================================================================-\n                                 GREETINGS\n-==========================================================================-\n\n * Thanks goes to Lionheart for beta-testing this door at The Heaven Party.\n\n * Everyone else in Opaque, on OpqNet, on #AmigaCafe, etc! :)\n\n\n\n\n-==========================================================================-\n           CONTACT, CONTRIBUTIONS, REGISTRATION, BUGS AND SUGGESTIONS\n-==========================================================================-\n\nIf you have any kind of comments, suggestions, bug reports etc, then please\ndon''t hesitate to send it to me!\n\nMy EMail address is "[email removed]".\n\n\n\n\n-==========================================================================-\n\n\n\n\n                            The Opaque Organisation\n\n                                 Egelundsvej 35\n\n                                   4600 Køge\n\n                                    Denmark\n\n\n\n                             www.opaque.home.ml.org\n\n\n\n                                 Giro: 309-3565\n\n\n\n\n-==========================================================================-\n','\n',char(10)),NULL,NULL,19816,2,0,NULL,NULL,'opq_hs0_hypnostats','scan',1780048657);
