INSERT INTO door_catalog VALUES('ops_cd10','OPS-CD10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OPS-CD10.LHA','CD-DOOR','XIM','CD-DOOR',NULL,NULL,'OPS','\_____  /_\_____  /_\  ___   \   ______/ |pdy!/    |    /    |   _/   /_____   \ ._|   /     |   /     |   \___/.    /    \-.',replace('  _________ _________ ____________________\n  \_____  /_\_____  /_\  ___   \   ______/\n  |pdy!/    |    /    |   _/   /_____   \\n._|   /     |   /     |   \___/.    /    \-.\n| l_________:_________|    |   l_________/ |\n|      -/X Developmentl____|Presents:      |\n|                                          |\n|  CD-Transfer v1.0                        |\n|  CD Door For Use With: Euroscene 1&2 CD  |\n|                                          |\n`------------------------------------------''\n','\n',char(10)),'CD-DOOR.DOC',replace('\n\n                   _________ _________ ____________________\n                   \_____  /_\_____  /_\  ___   \   ______/\n                   |pdy!/    |    /    |   _/   /_____   \\n                   |   /     |   /     |   \___/.    /    \\n                   l_________:_________|    |   l_________/\n                        -/X Developmentl____|Presents:     \n \n                               CD-Transfer v1.0\n                     cODE:WHIZZKID   dESIGN & dOC:PRODiGY\n\n         This Door Is Public Domain, And May Be Freely Distributed.\n\n ** INSTALLATION **\n\n This Pack Contains The Following Files:\n \n - CD-DOOR\n - CD-DOOR.CFG\n - CD-DOOR.DOC (You Are Reading It Now!)\n\n Copy CD-DOOR To Your Doors:OOPS/\n Copy CD-DOOR.CFG To Your Doors:OOPS/\n Copy CD-DOOR.DOC To Your Doors:OOPS/\n\n ** FOR /X USERS! **\n\n Just put the CD.info in your BBS:commands/bbscmd/\n\n ** FOR S-EXPRESS USERS! **\n\n Place The Following Line In Your BBS:Commands/BBS.CMD\n\n ----------------------------------------------------Cut Here\n*CD        XM020Doors:OOPS/CD-DOOR\n ----------------------------------------------------Cut Here\n\n ** HOW TO CONFiGURE THE CD-DOOR.CFG **\n\n Very simple.\n In this first release you can only use the Euroscene 1 or 2 CD. \n So if you want to put the Euroscene 1 CD online just enter 1 in the\n CD-DOOR.CFG\n If you want to put the Euroscene 2 CD online just enter 2 in the\n CD-DOOR.CFG\n That''s it!\n\n Future releases of CD-Transfer will also handle CD''s like:\n Aminet, MOD collections etc etc. \n\n ** Disclaimer:\n We Accept No Responsibility Whatsoever For Any Damage You Might\n Cause To Your System, Use This Door At Your Own Risk **\n\n If You Have Any Questions/Problems/Bugs/Money, Then You Can Contact Us At:\n The Origin BBS:  +31-0314-362687/+31-0314-378863\n\n Quick Greetz To:\n All Our Contacts & Door/Tool Users.\n','\n',char(10)),NULL,'auto-added',11360,2,0,NULL,NULL,'ops_cd10','scan',1780048657);
