INSERT INTO door_catalog VALUES('or_ct04','OR-CT04.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OR-CT04.LHA',NULL,'XIM','fALCON-bryggtPÅrentKÄLLAVATTEN',NULL,'Jaf','OR','CpsTop V0.4 Beta by Jaf :::::/X3.x & /X4.x::::: :::::::::::::::::::::::',replace(':::::::::::::::::::::::\nCpsTop V0.4 Beta by Jaf\n:::::/X3.x & /X4.x:::::\n:::::::::::::::::::::::\n','\n',char(10)),'cpstop.guide',replace('@Database "CpsTop v0.4 Beta Documentation"\n@Author "Jaf"\n@$VER: CpsTop Documentation v0.4 Beta (05.12.94)"\n\n@Node Main "CpsTop v0.4 Beta Documentation"\n\n       @{b}Table of contents for CpsTop v0.4 Beta by Jaf@{ub}\n\n\n\n\n    @{b}1.@{ub} @{"Introduction" Link "Intro"} .............. What is the purpose of this TopCps''er\n    @{b}2.@{ub} @{"Copyright" Link "Copy"} ................. Copyright information\n    @{b}3.@{ub} @{"Usage" Link "Usage"} ..................... How to use this program\n    @{b}4.@{ub} @{"History" Link "History"} ................... Versions of this program\n    @{b}5.@{ub} @{"Greetings" Link "Greetings"} ................. Personal greetings\n    @{b}6.@{ub} @{"Future plans" Link "Future"} .............. The future of this Program\n\n\n\n       @{i}Final Note i will never program anything for /X anymore it''s\n       a overrated bbs program take a look at ®Tempest it''s better.@{ui}\n\n\n\n\n@EndNode\n\n@Node "Intro" "Introduction"\n\n @{u}@{b}1. Introduction of this TopCps Prg@{uu}@{ub}\n\n I had this program for sometime now and some users asked me if i could\n release it.\n Well i don''t work with /X anymore and started to make utils for ®Tempest\n so what the hell i release it for those who like it.\n What it does is not much it will display the Usersname,OnlineBaud,Cpsup\n and Cpsdown..\n and there is nothing new about that, there are plenty of those around.\n Like i said i just released it since a few users asked me about it.\n\n@EndNode\n\n@Node "Usage" "Usage"\n\n @{u}@{b}3. Program usage@{uu}@{ub}\n\n CpsTop is a ®RMS Compiled Arexx script so it needs a arexx setup\n\n Just put it in your logoff script\n\n Cps Top v0.4 Beta by Jaf/oUTER rIM\n\n Usage: CpsTop Path/User.keys Path/Output\n \n1. The Main Prg CpsTop\n2. Path to User.Keys (i.e. bbs:User.Keys)\n3. Path to Output File (i.e. Ram:Bull.txt)\n\n@EndNode\n\n@Node "Copy" "Copyright"\n\n @{u}@{b}2. Copyright information about this program@{uu}@{ub}\n\n You read this shit? hehehe\n Get real no copyright for this stuff do with it what ever you like.\n\n@EndNode\n\n@Node "History" "Program history"\n\n @{u}@{b}4. Program history...@{uu}@{ub}\n\n Program releases:\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nv0.1/v0.3 beta just for my own bbs\n\nv0.4 Beta public release\n\nv0.5 forget v0.4b it this is my final /X util\n\n@EndNode\n\n@Node "Greetings" "Personal greetings"\n\n @{u}Greetings and Thanks @{uu}\n\n         ..::.          +31-79-219299/521171                 . \n      ..:::            .                                 ..::: \n      .::_______    ___:  ._____________________________.:::   \n     ---/.     ¬\--/. ¬|  ¬\__    ____/  ____________   \---   \n      -//   |   .\//   |   .\|:   | /.  ____)_|.   _¬  _/-     \n      /     l    \\    l    \\|   |//        ¬\    |.   \ 28k8 \n      \___________/__________/    |\__________/____||    \rules\n     .::.         Y          |  __:_               |______\    \n      :: _ _ _ __ ____________ |_ ._| ___  ___         .::.    \n      :     \\\\_\  _______   \ _\/_ /. ¬\/  ¬\        .:      \n                    |.   _¬  _/| \/.|/        .\   oNLINE sINCE\n  sYSOP: Jaf        ||   |.   \|   ||    \/    \\    09/27/90  \ncODUDES: -TCB!-/GoD >____||    \____|____||      \ __ _ _ _    \n         Gordon/Trsi-=-=-|______/-=-=-=-=-|______//_////       \n\nJPS            for being my top uploader and giving me some upgrades\n \nDark           helping me out, chats and h/p\n \nJay            To bad you are no able to call at the moment mate\n               lets hope things will come back.\n\nOB1            We should have a chat again about fixing a line hehe\n\nGazzer         for helping me with the info about the Tollfree numbers\n\nGreen Baret    One nice Sysop\n\nPlanet Master  What the hell is up with your system? i hate EOF to soon\n\nGordon         Best friend ever long time no see mate, we have to set a\n               date to get drunk again either your place or mine.\n\n-TCB!-         To bad things took the wrong way, how''s the bbs doing?\n\nPurple Haze    Piet bel me even heb wat info nodig als je hebt over een\n               VAX\n\nZACK           See if you can get your Ansi''s copyrighted =8->\n\n                       and all i seems to forget again\n\n@EndNode\n\n@Node "Future" "Future plans"\n\n @{u}@{b}10. Future applications@{uu}@{ub}\n\n There is NO future in /X so the same thing with this util 9-)\n\n@EndNode\n','\n',char(10)),NULL,'auto-added',14546,4,0,NULL,NULL,'or_ct04','scan',1780048657);
INSERT INTO door_catalog VALUES('ors_cp11','ORS_CP11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ORS_CP11.LHA','AmigaGuide','XIM','AmigaGuide',NULL,NULL,'ORS','/  _  \_/   _/__/___/_\_   \/___/   _/__ /   /   /___    /   /   /   /   /___    / /       /   /   /   /  _   _/   /   /   /',replace('   _____   _____   ____ _____  _________   \n  /  _  \_/   _/__/___/_\_   \/___/   _/__ \n /   /   /___    /   /   /   /   /___    / \n/       /   /   /   /  _   _/   /   /   /  \n\______/_______/___/___\___\___/_______/CoZ\n<-- -  -     .p.r.e.s.e.n.t.s.     -  - -->\n.-----------------------------------------.\n|CHAT-OVERIDE-EMERGENCY-CREDITS-PAGE V1.10|\n`-----------------------------------------''\n','\n',char(10)),'COECP11.GUiDE',replace('@DATABASE "COECP10.ENGLISH.GUIDE"\n@REMARK .------------------------------------------------------------------.\n@REMARK | This document is written in AmigaGUIDE format, so please read it |\n@REMARK | with AmigaGUIDE or your favourite guide reader.... ciao now...   |\n@REMARK `------------------------------------------------------------------''\n@REMARK $VER: COECP V1.0\n@WIDTH 80\n@NODE MAIN "Guide to Chat-Overide-Emergency-Credits-Page V1.1"\n                                   /\            /\            \n               ___________________/  \__________/  \__________ \n               \_  _   _    _    /  __   _     /  __    _    / \n               /   |   \    |___/\__/\  _|   _/\__/\    |___/_ \n              /    |    \____     \   \  \      /   \____     \\n              \    |    /   /     /   /  |\    /    /   /     /\n               \_______/_________/___/___| \  /____/_________/ \n                                            \/         ©JoKER\n                            ¿S pROUD tø pRESENT:\n\n                          >»»»»> COECP V1.1 <««««<\n\n                          @{"-*-   INTRODUCTION   -*-" LINK INTRODUCTION}\n                          @{"-*-     FEATURES     -*-" LINK FEATURES}\n                          @{"-*-   INSTALLATION   -*-" LINK INSTALLATION}\n                          @{"-*-   EDIT CONFIGS   -*-" LINK CONFIGFILES}\n                          @{"-*- TROUBLE-SHOOTING -*-" LINK PROBS}\n                          @{"-*-    WHO DID IT    -*-" LINK CREDITS}\n                          @{"-*-    GREETINGS!    -*-" LINK GREETINGS}\n@ENDNODE\n\n@NODE INTRODUCTION "INTRODUCTION OF COECP V1.1"\n\nCOECP V1.1 IS NOT ONLY ANOTHER NEW SYSOP PAGER. IT HAS @{"FEATURES" LINK FEATURES} THAT OTHER \nPAGERS DOESN''T HAVE. YOU SHOULD NOT REPLACE COECP V1.0 WITH YOUR OLD PAGER.\nLET IT RUN BESIDE YOUR OLD PAGER JUST WITH ANOTHER COMMAND TO START IT.\nSET THE CHAT-OVERRIDE-LEVEL TO AN AMMOUNT THAT EVERY USER IS ABLE TO PAGE\nYOU AT ANY TIME. \n\nTHE USER HAS TO PAY WITH HIS CREDITS IF HE WANTS TO PAGE THE SYSOP AND HE\nWILL DO THIS ONLY IF THERE IS SOMETHING REALLY IMPORTANT. SO, NEVER WILL\nPAGE THE SYSOP JUST FOR FUN AND THE SYSOP CAN BE PAGED AT EVERY TIME.  \n\n@ENDNODE\n\n@NODE FEATURES "FEATURES OF COECP V1.1"\n\nCOECP V1.1 LOOKS HOW MANY UPLOAD BYTES THE USER WHO WANTS TO PAGE THE SYSOP\nHAS AND CALCULATES HOW MANY BEEPS THE USER CAN USE. IF THE USER HAS ACCESS\nTO THE FREE-MODE HE DOES NOT HAVE TO PAY FOR HIS BEEPS. THE AMMOUNT HOW MUCH\nA BEEP DOES COST, WHICH USERS HAVE ACCESS TO THE FREE-MODE AND HOW HIGH IS\nTHE CHAT-OVERIDE-LEVEL ARE IN THE @{"CONFIGFILES" LINK CONFIGFILES}.\n\nAFTER THE USER PAGED THE SYSOP COECP V1.1 CALCULATES THE NEW AMMOUNT OF\nCREDITS THE USER HAS LEFT (IS SHOWN TO THE USER) AND STORES THIS TO HIS\nUSERDATA.\n\n@ENDNODE\n\n@NODE INSTALLATION "INSTALLATION OF COECP V1.1"\n\nINSTALLATION TO @{"AMI EXPRESS V2.xx" LINK AMIEXPRESSV2.xx}.\n\nINSTALLATION TO @{"AMI EXPRESS V3.xx" LINK AMIEXPRESSV3.xx}.\n\n@ENDNODE\n\n@NODE AMIEXPRESSV2.xx "INSTALLATION TO AMI EXPRESS V2.xx"\n\nTO INSTALL THE DOOR LOAD UP THE CUSTOMCOMMANDS (/X V2.2x OR BELOW) OR\nBBS.CMD (/X V2.3x) AND ADD THE FOLLOWING LINE TO THE LIST.\n\n\n          11 SPACES IN         \n          |\n-----------------------------------------------          \n*PAGE     RM010MODULES:ABSTURZ/COECP/COECP.REXX\n-----------------------------------------------\n||        |||  |           \n||        |||  ` ''MODULES:ABSTURZ/COECP/COECP.REXX'' IS THE LOCATION OF\n||        |||     THE FILE.\n||        |||\n||        ||` 020 THE MINIMUM ACCESS TO USE THIS DOOR. CHANGE IT TO WHAT\n||        ||      YOU LIKE.\n||        ||\n||        |` ''M'' FOR A MULTINODE BBS (''S'' FOR A SINGLE NODE BBS).\n||        |\n||        ` ''R'' FOR A REXX DOOR WHICH WILL USE THE ''REXXDOOR''-UTIL.\n||\n|`COMMAND TO START THE DOOR.\n|\n`-RETARD OPTION. TO MAKE SURE THEY ONLY USE ''S'' & ONLY  ''S'' TO GET THE\n  DOOR TO COME UP. IF NOT USED, THINGS SUCH AS ''START'' AND ''SA'' WOULD\n  STILL BRING UP THE DOOR.\n\n\n  USE THE LINE BETWEEN THE LINES ONLY. THE OTHER PARTS ARE JUST AN\n  EXPLANATION TO MAKE SURE YOU KNOW WHAT EACH PART IS DOING (SINCE\n  NOONE WOULD TELL ME BACK IN THE DAYS WHERE I DIDN''T KNOW WHAT WAS\n  GOING ON!)  \n\n  NOW COPY THE DIRECTORY ''MODULES'' FROM THE LHA-ARCHIEV TO YOUR BBS.\n\n  AT LAST EDIT THE @{"CONFIGFILES" LINK CONFIGFILES}. YOU FIND WILL THEM IN\n \n  ''BBS:MODULES/ABSTURZ/COECP''.\n\n@ENDNODE\n\n@NODE AMIEXPRESSV3.xx "INSTALLATION TO AMI EXPRESS V3.xx"\n\nYOU ONLY NEED TO COPY THE FILES FROM THE LHA-ARCHIEVE TO YOUR BBS. THEN\nEDIT THE @{"CONFIGFILES" LINK CONFIGFILES}. YOU WILL FIND THEM IN ''BBS:MODULES/ABSTURZ/COECP''.\n\n@ENDNODE\n\n@NODE CONFIGFILES "HOW TO EDIT THE CONFIGFILES?"\n\n1. CREDITSPAGE.NAMES\n \n   - THIS IS THE LIST OF USER''S NAMES WHO HAVE ACCESS TO THE FREE-MODE.\n     \n     E.G.:\n\n     - Line 1 = MuMu\n     - Line 2 = HELiON\n     - Line 3 = SPIDER\n\n\n     ALL USERS IN THIS LIST DO NOT HAVE TO PAY IF THEY WANT TO PAGE THE\n     SYSOP. \n\n     CAN ADD AS MANY USERS AS YOU WANT TO.\n\n\n2. CREDITSPAGE.CFG\n\n   - Line 1 = 20      <- CHAT-OVERIDE-LEVEL\n   - Line 2 = 102400  <- AMMOUNT HOW MUCH A BEEP DOES COST\n   - Line 3 = 10      <- THE MAXIMUM NUMBER OF BEEPS THE COECP V1.0 WILL\n                         DO, IF THE USER HAS ENOUGH CREDITS  \n\n@ENDNODE       \n\n@NODE CREDITS "CREDITS FOR COECP V1.1"\n\n   IDEA          : MuMu øf OSiRiS\n   \n   AREXX-CODING  : MuMu & nEW uSER øf OSiRiS\n   \n   DOCUMENTATION : MuMu øf OSiRiS\n\n   BETA TESTING  : MuMu - KEY WEST - OSiRiS EHQ - SCANDAL DiST SiTE\n                   DOC ICE - HEADCRASH - TSB WHQ / KBP WHQ\n                   \n@ENDNODE\n\n@NODE GREETINGS "FRIENDSHIP RULEZ"\n\n               GREETINGS FROM MuMu TO THE FOLLOWING PEOPLE:\n              ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nCREEPY/TFP          - HOW iS iT GOiN''?\nGANDALF/SCL         - WELL, iT WAS A NiCE TiME IN FAiTH.\nRAPiD/SCL           - THANX FOR THE ANSiS.\nRAF/TFP             - THANX FOR THE KEY WEST LOGO. iT iS PRETTY NiCE.\nDiCE/TFP            - THANX FOR THE BBS-ADVERT YOU CODED FOR ME.\nMURDOC/NEON         - YOUR AT&T''S ARE 100% NO ViRGiN CARDS. BETTER TRY\n                      TO GET A BETTER CARD-SUPPLiER.\n \n\n                  AND A BiG HELLO TO ALL OSiRiS MEMBERS !\n\n@ENDNODE\n\n@NODE PROBS "DO YOU HAVE ANY PROBLEMS?"\n\n               FOR TROUBLE-SHOOTING OR LATEST UPDATES CALL:\n              ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n                 sYSOP: MuMu    «·»    1 nODE - 16.8k DHST       \n      - -- --- --------------------------------------------- --- -- -\n               ___                 \          /                      \n        ______/  /___  __  __    ___\        /____  _______________  \n        \_   /  /__  \/  \/  \   \   \      /___  \/  ____/\__    /  \n         | _/ _/ _/  /   /   /    \  /\    /  _/  /\____ \_   \__/   \n         | \  \  \__/\__    /  ·   \   \  /   \__/|    /  /     \    \n         |__\  \___________/        \/\  /________|______/|      \   \n             \__\                      \/              EaZ|_______\  \n                  OSiRiS EHQ & SCANDAL DiSTRiBUTiON SiTE             \n      - -- --- --------------------------------------------- --- -- -\n\n                    » aMIGA · /X · cONSOLE · mODULES «               \n\n               aMIXPRESS v3.XX   ø   nUP & sYSTEM pW nEEDED          \n\n                    -:) cALL nOW fOR a goOD rATIO (:-                \n\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',138197,11,0,NULL,NULL,'ors_cp11','scan',1780048657);
