INSERT INTO door_catalog VALUES('ors_fc11','ORS-FC11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ORS-FC11.LHA','FC','XIM','FC',NULL,NULL,'ORS','.:::: / . \/ ___)___)/ ___) (___) ___):::::. :::::/  ¦  \___ ¬\  ¬\  ¦  \/   \___ ¬\::::: :::::\_____/___  /_  /__|   \_  /___  /:::::',replace(' ____  ___  ____ ___  ____   ___ ____  ___\n.:::: / . \/ ___)___)/ ___) (___) ___):::::.\n:::::/  ¦  \___ ¬\  ¬\  ¦  \/   \___ ¬\:::::\n:::::\_____/___  /_  /__|   \_  /___  /:::::\n`-[AMO]------- \/--\/--¬¦____\\/--- \/÷÷---''\n FileCreator 1.1  - Just for SySoPs 26.8.95\n    Creats 0-Byte Files out of filedirs. \n','\n',char(10)),'ORS-FC11.DOC',replace('\n                              (*) TRADERS ¡NN (*)\n\n                   (*) rENEGADE wORLD lEADER hEADQUARTER (*)\n                      (*) f¡X lTD  gERMAN hEADQUARTER (*)\n\n           (*) cOME aND jO¡N tHE nEW f¡X÷lTD gERMAN hEADQUARTERS (*)\n\n                                        (*) wELCOME (*)\n                             .--.\n         __    _____ _____ __|  |___________ _____      __ _____ _____\n       _/  l__/     \_    \_   _/  ___/     \_    \_   (__)     \_    \_\n       \_  _/\_  l___/ |  _/ | \_  _/\_  l___/ l___/   | \_  |  _/ |  _/\n        |  |  |  |  |     |  |  |  |  |  |  l__   |    |  |  |  |  |  |\n        |  l  |  |  |  |  |  |  |  l  |  |  |  |  |    |  |  |  |  |  |\n        l__   l__|  l__|  l_____l__   l__|  l__   |    l__l__|  l__|  |\n           `--''        `--''        `--''  ÷2F÷  `--''          `--''  `--''\n\n              -÷[sYSOP : RAMiS!^rENEGADE·fIX^Ltd·nEUTRON·sHOOT]÷-\n             -÷[cOSYSOP : cQBS!^rENEGADE  sLIME!^rENEGADE·sHOOT]÷-\n\n     (cRED¡TS * 2 fOR mAJORS, cRED¡TS * 3 fOR mAJORS fROM yOUR oWN gROUP)\n           (28k8 mULTiNODE sYSTEM)=(aLL nODES @115.2k oN mULT¡CARDS)\n                 (nO sYSTEM pASSWORD aND/oR nEW uSER pASSWORD)\n                 (fREE d/L oN aLL rENEGADE & f¡X·lTD rELEASES)\n                      (sUPPORT¡NG aM¡GA & cONSOLEN sTUFF)\n                