INSERT INTO door_catalog VALUES('ors_sa11','ORS-SA11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ORS-SA11.LHA','aLaRM','XIM','RAWPLAY',NULL,NULL,'ORS','/  _______    \   _______    \  __________/ /        |    //     \   /  __/\________ .\ \_____________/_______\      \____________/',replace('  __________________________________________\n /  _______    \   _______    \  __________/\n/        |    //     \   /  __/\________ .\\n\_____________/_______\      \____________/\n |  - o.S.i.R.i.s -    \______\  -tRN!    |\n |                                        |\n |  SYSOP-ALARMiNATOR V1.1 -  FOR ALL /X  |\n `----------------------------------------´\n','\n',char(10)),'ALARM11.GUiDE',replace('@DATABASE "ALARM11.ENGLiSH.GUiDE"\n@REMARK .------------------------------------------------------------------.\n@REMARK | This document is written in AmigaGUiDE format, so please read it |\n@REMARK | with AmigaGUiDE or your favourite guide reader.... ciao now...   |\n@REMARK `------------------------------------------------------------------''\n@REMARK $VER: SYSOP-ALARMiNATOR V1.1\n@WiDTH 80\n@NODE MAiN "Guide to iCH SYSOP-ALARMiNATOR V1.1 WRiTTEN BY MuMu OF OSiRiS"\n                                   /\            /\            \n               ___________________/  \__________/  \__________\n               \_  _   _    _    /  __   _     /  __    _    /\n               /   |   \    |___/\__/\  _|   _/\__/\    |___/_\n              /    |    \____     \   \  \      /   \____     \\n              \    |    /   /     /   /  |\    /    /   /     /\n               \_______/_________/___/___| \  /____/_________/\n                                            \/         ©JoKER\n                            ¿S pROUD tø pRESENT:\n\n                 >»»»»> SYSOP-ALARMiNATOR VERSiON 1.10 <««««<\n\n                          @{"-*-   iNTRODUCTiON   -*-" LiNK iNTRODUCTiON}\n                          @{"-*-     FEATURES     -*-" LiNK FEATURES}\n                          @{"-*-   iNSTALLATiON   -*-" LiNK iNSTALLATiON}\n                          @{"-*-  EDiT TOOLTYPES  -*-" LiNK TOOLTYPES}\n                          @{"-*-  PRiVATE SCREEN  -*-" LiNK SCREENS}\n                          @{"-*- TROUBLE-SHOOTiNG -*-" LiNK PROBS}\n                          @{"-*-    WHO DiD iT    -*-" LiNK CREDiTS}\n                          @{"-*-     HiSTORY!     -*-" LiNK HiSTORY}\n                          @{"-*-    GREETiNGS!    -*-" LiNK GREETiNGS}\n                          @{"-*-    OUR SLOGAN    -*-" LiNK SLOGAN}\n@ENDNODE\n\n@NODE iNTRODUCTiON "iNTRODUCTiON OF SYSA VERSiON 1.1"\n\nSYSOP-ALARMiNATOR VERSiON 1.1 iS A TOOL WHO iNFORMS THE SYSOP ABOUT\nCERTAiN USERS WHEN THEY ARE LOGGiNG iNTO THE BBS.\niT HAS @{"FEATURES" LiNK FEATURES} THAT OTHER TOOLS DOESN''T HAVE.\n\n@ENDNODE\n\n@NODE FEATURES "FEATURES OF SYSA VERSiON 1.1"\n\ni DECiDED TO CODE THiS TOOL BECAUSE i LiKED THE USER-ALARMiNATOR V1.0\nRELEASED BY ABSTURZ-DESiGN LONG TiME AGO. THE USER-ALARMiNATOR V1.0\nFROM ABSTURZ-DESiGN iS VERY NiCE, BUT iT HAS SOME FEATURES MiSSiNG.\niT ONLY LOOKS iNTO A CONFiG-FiLE FOR THE USER-NAMES AND THEN WHEN iT\nFiNDS THE USER WHiCH iS LOGGiNG iNTO YOUR BBS SiMPLY PLAYS A SAMPLE\nTO iNFORM THE SYSOP.\n\niT HAS NO CONFiG-FiLES AND WORKS FULLY WiTH TOOL-TYPES iN THE iCON.\n\nMY VERSiON HAS LOTSA MORE OPTiONS. iT LOOKS FOR THE FOLLOWiNG THiNGS:\n\n 1. USER-NAME\n 2. ACCESS-AREA\n 3. ACCESS-LEVEL\n\n    OR ANY COMBiNATiON OF THOSE...\n\n\niF YOU WANT TO SEND A PERSONAL MESSAGE ALSO TO THE USER EVEN WHEN YOU\nDON''T WANT TO ALERTED WHEN HE iS LOGGiNG ON... NO PROBLEM!\n\nSYSOP-ALARMiNATOR V1.1 LOOKS WHENEVER THE TOOL iS STARTED FOR A SPECiAL\nTEXTFiLE WHiCH iS ONLY FOR THE USER WHO iS LOGGiNG ON.\n\nLOOK iNTO @{"PRiVATE SCREEN" LiNK SCREENS} FOR MORE iNFORMATiON.\n\nAND NOW i THiNK i GAVE YOU ENOUGH REASONS TO iNSTALL SYSA V1.1 :)\n\n@ENDNODE\n\n@NODE iNSTALLATiON "iNSTALLATiON OF SYSA VERSiON 1.1"\n\niNSTALLATiON TO @{"AMi EXPRESS V2.xx" LiNK AMiEXPRESSV2.xx}.\n\niNSTALLATiON TO @{"AMi EXPRESS V3.xx" LiNK AMiEXPRESSV3.xx}.\n\n@ENDNODE\n\n@NODE AMiEXPRESSV2.xx "iNSTALLATiON TO AMi EXPRESS V2.xx"\n\nTO iNSTALL THE DOOR LOAD UP THE CUSTOMCOMMANDS (/X V2.2x OR BELOW) OR\nSYS.CMD (/X V2.3x) AND ADD THE FOLLOWiNG LiNE TO THE LiST.\n\n\n          11 SPACES iN         \n          |\n-------------------------------------------          \n*ALARM    RM010MODULES:MM_TOOLS/ALARM/ALARM\n-------------------------------------------\n||        |||  |           \n||        |||  ` ''MODULES:MM_TOOLS/ALARM/ALARM'' iS THE LOCATiON OF\n||        |||     THE FiLE.\n||        |||\n||        ||` 001 THE MiNiMUM ACCESS TO USE THiS DOOR. CHANGE iT TO WHAT\n||        ||      YOU LiKE.\n||        ||\n||        |` ''M'' FOR A MULTiNODE BBS (''S'' FOR A SiNGLE NODE BBS).\n||        |\n||        ` ''R'' FOR A REXX DOOR WHiCH WiLL USE THE ''REXXDOOR''-UTiL.\n||\n|`COMMAND TO START THE DOOR.\n|\n`-RETARD OPTiON. TO MAKE SURE THEY ONLY USE ''ALARM'' & ONLY  ''ALARM''\n  TO GET THE DOOR TO COME UP. iF NOT USED, THiNGS SUCH AS ''ALARMO''\n  AND ''ALARMATRON'' WOULD STiLL BRiNG UP THE DOOR.\n\n\n  USE THE LiNE BETWEEN THE LiNES ONLY. THE OTHER PARTS ARE JUST AN\n  EXPLANATiON TO MAKE SURE YOU KNOW WHAT EACH PART iS DOiNG (SiNCE\n  NOONE WOULD TELL ME BACK iN THE DAYS WHERE i DiDN''T KNOW WHAT WAS\n  GOiNG ON!)  \n\n  NOW COPY THE DiRECTORY ''MODULES'' FROM THE LHA-ARCHiEV TO YOUR BBS.\n\n  AT LAST EDiT THE @{"TOOLTYPES" LiNK TOOLTYPES} OF ''ALARM.iNFO''. YOU\n  WiLL FiND iT iN ''BBS:MODULES/MM_TOOLS/ALARM/''.\n\n\n  NOW ADD THE FOLLOWiNG TO YOUR LOGON.TXT AND LOGON.TXT.GR\n\n  --------------CUT HERE----------------\n  ~CC_ALARM\n  --------------CUT HERE----------------\n\n \n  THAT''S ALL...\n\n@ENDNODE\n\n@NODE AMiEXPRESSV3.xx "iNSTALLATiON TO AMi EXPRESS V3.xx"\n\n  COPY ALL THE FiLES FROM THE LHA-ARCHiEV TO YOUR BBS AND\n\n  ADD THE FOLLOWiNG TO YOUR LOGON.TXT AND LOGON.TXT.GR\n\n\n  --------------CUT HERE----------------\n  ~CC_ALARM\n  --------------CUT HERE----------------\n\n\n\n  AT LAST EDiT THE @{"TOOLTYPES" LiNK TOOLTYPES} OF ''ALARM.iNFO''. YOU\n  WiLL FiND iT iN ''BBS:MODULES/MM_TOOLS/ALARM/''.\n\n@ENDNODE\n\n@NODE TOOLTYPES "HOW TO EDiT THE TOOLTYPES?"\n\n  ACSTYPE=<number>                       THE <number> DEFiNES FOR WHAT THE\n                                         SYSOP WANTS TO BE ALERTED.\n                                         1 = NAMES ONLY\n                                         2 = ACCESS-AREA ONLY\n                                         3 = ACCESS-LEVEL ONLY\n                                         4 = NAMES & ACCESS-AREA\n                                         5 = NAMES & ACCESS-LEVEL\n                                         6 = ACCESS-AREA & ACCESS-LEVEL\n                                         7 = NAMES & ACCESS-AREA &\n                                             ACCESS-LEVEL\n\n                                         E.G.: ACSTYPE=1 <- iS LOOKiNG\n                                                            FOR USER-NAME\n                                                            ONLY !!!\n\n\n  ACSLEVEL=<number>                      THE <number> DEFiNES THE \n                                         ACCESS-LEVEL OF THE USER BY WHiCH\n                                         THE SYSOP WANTS TO BE ALERTED WHEN\n                                         THiS OPTiON iS CHOSEN.\n\n                                         E.G.: ACSLEVEL=200\n\n\n  ACSAREA=<area>                         THE <area> DEFiNES THE ACCESS-AREA\n                                         OF THE USER BY WHiCH THE SYSOP\n                                         WANTS TO BE ALERTED WHEN THiS\n                                         OPTiON iS CHOSEN.\n\n                                         E.G.: ACSAREA=OSiRiS\n\n\n  USER.01=<user>                          THE <user> DEFiNES THE USER-NAME BY\n                                         WHiCH THE SYSOP WANTS TO BE ALERTED\n                                         WHEN THiS OPTiON iS CHOSEN.\n\n                                         E.G.: USER.01=MUMU\n                                               USER.02=SPiDER\n                                               USER.03=HELiON\n\n                                         !!! YOU CAN ADD AS MANY USERS AS\n                                             YOU WANT !!!\n\n\n  SAMPLECONFiG=<path&options>            THE <path&options> DEFiNES THE PATH\n                                         OF THE SAMPLE-PLAYER AND THE SAMPLE\n                                         WiTH iTS OPTiONS WHiCH WiLL BE\n                                         PLAYED WHEN THE SYSOP iS ALERTED.\n\n  E.G.:\n\n  SAMPLECONFiG=SYS:C/RAWPLAY 430 63 BBS:MODULES/MM_TOOLS/ALARM/ALARM.SAMPLE\n\n  THAT SHOULD BE ALL FOR NOW...\n\n\n@ENDNODE       \n\n@NODE SCREENS "HOW TO BUiLT iN THE PRiVATE SCREENS?"\n\niF YOU WANT TO SEND A PERSONAL MESSAGE TO A USER EVEN WHEN YOU\nDON''T WANT TO ALERTED WHEN HE iS LOGGiNG ON... NO PROBLEM!\n\nSYSOP-ALARMiNATOR V1.1 LOOKS WHENEVER THE TOOL iS STARTED FOR A SPECiAL\nTEXTFiLE WHiCH iS ONLY FOR THE USER WHO iS LOGGiNG ON.\n\nMAKE A TEXTFiLE THAT SHOULD BE SHOWN TO THE SPECiAL USER AND NAME HiM\n''ALARM.USER.<number>''. THE <number> iS THE SLOTNUMBER OF THE USER WHO\nSHOULD GET THE TEXTFiLE.\n\nEXAMPLE: ''ALARM.USER.3''    <--- NOW THE USER WiTH THE SLOTNUMBER 3\n                                WiLL GET THE TEXTFiLE.\n\n !!! ATTENTiON !!!\n\nMAYBE YOU JUST WANT TO ANNOY A USER WiTH A PERSONAL TEXTFiLE BEFORE\nDELETiNG HiM. AFTER YOU DELETED THE USER iT MAY BE HAPPEN THAT ANOTHER\nUSER HAS NOW THE SAME SLOTNUMBER WHiCH THE DELETED USER HAD. NOW THE NEW\nUSER WiLL GET THE PRiVATE TEXTFiLE. TAKE CARE OF THE PRiVATE TEXTFiLES\nSO NOBODY WiLL GET A TEXTFiLE WHO SHOULD NEVER GET ONE.\n\nNOW COPY THE ''ALARM.USER.<number>'' iNTO ''BBS:MODULES/MM_TOOLS/ALARM/''.\n\nTHAT SHOULD BE ALL...\n\n@ENDNODE\n\n@NODE CREDiTS "CREDiTS FOR SYSA V1.1"\n\n   iDEA          : MuMu øf OSiRiS\n   \n   AREXX-CODiNG  : MuMu øf OSiRiS\n   \n   DOCUMENTATiON : MuMu øf OSiRiS\n\n   ANSi-ARTiST   : JOKER øf TAURUS\n\n   BETA TESTiNG  : MuMu   - KEY WEST - OSiRiS EHQ - SCANDAL DiST SiTE\n                   \n\n@ENDNODE\n\n@NODE GREETiNGS "FRiENDSHiP RULEZ"\n\n               GREETiNGS FROM MuMu TO THE FOLLOWiNG PEOPLE:\n              ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nCREEPY/TFP          - HOW iS iT GOiN''?\nGANDALF/SCL         - ARE YOU DEAD?\n                      i''VE HEARD YOU HAVE A GiRL-FRiEND NOW\nJOKER/TAU           - THANX FOR THE ALARM-ANSi!\nRAF/TFP             - STiLL UPSET, DUDE?\nMURDOC/NEON         - i WiSH YA FUN WiTH YOUR GROUP.\nJESTER/POD          - THANX FOR YOUR HELP iN AREXX.\n \n\n                  AND A BiG HELLO TO ALL OSiRiS MEMBERS !\n\n@ENDNODE\n\n@NODE PROBS "DO YOU HAVE ANY PROBLEMS?"\n\n               FOR TROUBLE-SHOOTiNG OR LATEST UPDATES CALL:\n              ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n                 sYSOP: MuMu    «·»    1 nODE - 16.8k DHST       \n      - -- --- --------------------------------------------- --- -- -\n               ___                 \          /                      \n        ______/  /___  __  __    ___\        /____  _______________  \n        \_   /  /__  \/  \/  \   \   \      /___  \/  ____/\__    /  \n         | _/ _/ _/  /   /   /    \  /\    /  _/  /\____ \_   \__/   \n         | \  \  \__/\__    /  ·   \   \  /   \__/|    /  /     \    \n         |__\  \___________/        \/\  /________|______/|      \   \n             \__\                      \/              EaZ|_______\  \n                  OSiRiS EHQ & SCANDAL DiSTRiBUTiON SiTE             \n      - -- --- --------------------------------------------- --- -- -\n\n                    » aMiGA · /X · cONSOLE · mODULES «               \n\n               aMiXPRESS v3.XX   ø   nUP & sYSTEM pW nEEDED          \n\n                    -:) cALL nOW fOR a goOD rATiO (:-                \n\n@ENDNODE\n\n@NODE SLOGAN "OUR SLOGAN..."\n\n                                   /\            /\            \n               ___________________/  \__________/  \__________ \n               \_  _   _    _    /  __   _     /  __    _    / \n               /   |   \    |___/\__/\  _|   _/\__/\    |___/_ \n              /    |    \____     \   \  \      /   \____     \\n              \    |    /   /     /   /  |\    /    /   /     /\n               \_______/_________/___/___| \  /____/_________/ \n                                            \/         ©JoKER\n\n                        - WE DON''T WANNA BE THE BEST -\n \n                       - WE JUST WANNA HAVE MORE FUN! -\n\n@ENDNODE\n\n@NODE HiSTORY "THE HiSTORY OF ''SYSOP-ALARMiNATOR''"\n\n                     THE HiSTORY OF ''SYSOP-ALARMiNATOR''\n                  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nVERSiON 0.1 - 0.9 : iNTERNAL BETA-RELEASES\n\nVERSiON 1.0       : FiRST PUBLiC RELEASE\n                    - NO BUGS KNOWN -\n\nVERSiON 1.1 -     : PUBLiC RELEASE\n                    - TOOLTYPE FUNCTiON REWRiTTEN - NOW TO 50% FASTER\n                    - NO EXTERNAL PROGRAMS NEEDED\n\n\n                     !!! FUTURE VERSiONS WiLL FOLLOW !!!\n\n@ENDNODE\n','\n',char(10)),'{"TYPE":"<number>"}','auto-added',75640,3,0,NULL,NULL,'ors_sa11','scan',1780048657);
