INSERT INTO door_catalog VALUES('otl_ac14','OTL-AC14.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OTL-AC14.LHA',NULL,'XIM','_ _/\____/\_ ___/\__/\_ __/\__ _/\____/\__ _',NULL,NULL,'OTL','_____  __  / __   __  /_____  \__/ /   ____ :/  /  /  /  //  //  /__/  ¬  / / / /\_  \:: /  /  /  /  //  //  /  / _/  / / / /  /  /::',replace('_ _/\____/\_ ___/\__/\_ __/\__ _/\____/\__ _\n_____  __  / __   __  /_____  \__/ /   ____\n:/  /  /  /  //  //  /__/  ¬  / / / /\_  \::\n/  /  /  /  //  //  /  / _/  / / / /  /  /::\n\__  /\__  //  //___  /__\  /\__  /___  /:::\nbIS\/====\/==\/=====\/====\/====\/====\/===>\n[/X 2.x]    AtomiX presents         [/X 3.x]\nAtomControl v1.4 - The confinue from the\n                   Legendary System Control\n','\n',char(10)),'AtomControl.guide',replace('@DATABASE "AtomControl.guide"\n@$VER: Atom-Control V1.3\n@(C) ©1994 by AtomiX / Outlaws\n@AUTHOR AtomiX\n\n@HEIGTH 640\n@WIDTH 256\n@NODE MAIN "AtomiX presents"\n\n                        @{B}  Atom-Control V1.3 @{UB}\n               written by AtomiX in Wed May 25 1994\n \n            @{"    Copyright Note    " LINK COPRIGHT} -1- @{"   Urheberechte    " LINK URHEBERECHT}\n            @{"    Product Info      " LINK Produkt } -2- @{"   Produkt Info''s  " LINK PRODUKT}\n            @{"    Installation      " LINK INSTALL } -3- @{"   Installation    " LINK INSTALLATION}\n            @{"    Bug Report        " LINK BUG     } -4- @{"   FehlerReporte   " LINK FEHLER}\n            @{"    Changes           " LINK CHANGES } -5- @{"   Changes         " LINK CHANGES}\n\n                              READ THE CHANGES\n\n\n@ENDNODE\n\n@NODE COPRIGHT\n@TITLE "Copyrighted"\n\n - AmiExpress is Copyrighted by LightSpeed Technologies\n\n - MultView , AmigaGuide , is Copyrighted by C=\n\n\n								@{"Main Menu" LINK MAIN}\n\n@ENDNODE\n\n@NODE URHEBERECHT\n@Urheberechte\n\n - AmiExpress ist Urheberechtlich geschützt von LightSpeedTechnologies\n\n - MultiView , Amiga Guide , ist Urheberechtlich geschützt von Commodore\n\n\n								@{"Main Menu" LINK MAIN}\n\n@ENDNODE\n\n@NODE PRODUkT\n@TITLE "Product Informations"\n\n  This is a AmiExpress Door for Replacement the Sysop Commands\n  for more Sercurity and better Design\n\n  You must Enter a Master Password in the .info File\n\n   Tooltype:\n\n   PASSWORD=<your Password>\n    |\n    `---> No Comments needed ,Note : Case Sensitive\n\n   CALLERSLOG\n    |\n    `----> Writes a Comment when the Co/Sysop enters\n           a wrong Master Password to the Callerslog\n\n\n\n\n								@{"Main Menu" LINK MAIN}\n@ENDNODE\n\n@NODE INSTALL\n@TITLE "Atom-Control 1.2 - Installation"\n\n * INSTALLATION *\n\n - Copy all file to BBS:Doors/<or where you like it>\n\n\n AE 3.xx Installation\n --------------------\n\n  - Copy Open.info to BBS:Commands/BBScmd/\n\n    Or add to <Command>.info:\n\n      ACCESS=   <Access Level>\n      LOCATION= <Door Location>\n      MULTINODE=<Multi Node ?>\n      PRIORITY= <Priority dont change it>\n      TYPE=XIM\n\n\n								@{"Main Menu" LINK MAIN}\n@ENDNODE\n\n@NODE INSTALLATION\n@TITLE "Atom-Control - Installation"\n\n * INSTALLATION *\n\n - Kopieren Sie alle Files in folgenden Pfad \n\n   "BBS:DOORS/"\n\n   AE 3.xx Installation\n   ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n - Kopieren Sie das "<Command>.info zu "BBS:COMMANDS/BBSCMD/"\n\n   Oder fügen Sie folgende Befehle in "<command>.info" ein\n\n      ACCESS=   <Access Level>\n      LOCATION= <Door Location>\n      MULTINODE=<Multi Node ?>\n      PRIORITY= <Priority dont change it>\n      TYPE=XIM\n\n								@{"Main Menu" LINK MAIN}\n@ENDNODE\n\n@NODE BUG\n@TITLE "Bug Reports"\n\n BUG REPORT & SUGGESTIONS\n ------------------------\n\n   It''s possible that a mistake will occur.... nobody is perfect.\n   If you have any suggestions or comments please leave a message\n   to me on the CHAOS LINE (German /X Distributor)\n\n   Node 1 : +49 (0)5723 74340  16.8DST\n   Node 2 : +49 (0)5723 SøøN   ISDN RingDown (16.6.94 the number available)\n   Node 3 : +49 (0)5723 SøøN   ISDN \n								@{"Main Menu" LINK MAIN}\n@ENDNODE\n\n@NODE FEHLER\n@TITLE "Fehler Report"\n\n\n Fehler Reporte & Vorschläge\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n   Es ist möglich das Fehler passieren ... niemand ist perfekt.\n   Wenn Sie vorschläge oder Fehler Reporte zu unseren Tools haben\n   dann rufen sie unser Hauptquatier an und hinterlassen Sie eine\n   Nachricht für mich auf der Chaos Line (Deutscher /X Händler)\n\n   Node 1 : +49 (0)5723 74340  16.8DST\n   Node 2 : +49 (0)5723 SøøN   ISDN RingDown (16.6.94 wird die Nummer bekannt)\n   Node 3 : +49 (0)5723 SøøN   ISDN \n								@{"Main Menu" LINK MAIN}\n@ENDNODE\n\n@NODE CHANGES\n@TITLE "Changes in Atom-Control V1.3"\n\n   V1.0    Some bugs and to slow\n\n   V1.1    New Password Routine\n           Works now on AmiExpress 2.x with Password Protection\n           Source Code modiefied for Faster Managment\n           Added a new Callerslog Function\n   V1.2    Test PW Routine Removed \n           have shows the Master PW before the Co/Sysop enters the PW\n           Sorry for the nasty bug ..\n\n   V1.3    absolute REWRITEN new Password Routine ,faster Screen Output\n           better Error Handling\n\n\n@ENDNODE\n\n@NODE RELEASED\n@TITLE "Tools from AtomiX"\n\n   .------[Name]------. .-[$VER]-. .--[Archive]--.\n   | Ansi Skipper     | |  v1.0  | | ANSISV10.LHA|\n   | Atom(Joy)Comment | |  v1.1  | | LGC-JC11.LHA|\n   | Atom(Joy)Status  | |  v1.1  | | NS-JS11.LHA |\n   | Bull View        | |  v1.2  | | BULLV12.LHA |\n   | DoorMenu         | |  v1.3  | | DOORM13.LHA |\n   | FastLhaCheck     | |  v1.0  | | OTL-FLC.LHA |\n   | FrontEnd         | |  v1.2  | | NS-JF11.LHA |\n   | LHA-Server       | |  v1.0  | | *********** | REGISTERED ONLY\n   | Logon Batch      | |  v1.0  | | NS-LB10.LHA |\n   | OperatorPage     | |  v1.3  | | OPAGER13.LHA|\n   | PW Failure       | |  v1.9  | | PWFAil19.LHA|\n   | System Control   | |  v1.3  | | OTL-SC13.LHA|\n   | UserInformation  | |  v1.4  | | -Forgotten- |\n   | UserList v1.0    | |  v1.0  | | OTL-UL10.LHA|\n   `------------------'' `--------'' `-------------''\n\n    NOTE- I think that''s not all my Released Tools\n          because i dont know what i all have written\n          keep it on your mind ;^)\n\n          Greets AtomiX  - Friendship is more than a word\n\n@ENDNODE\n','\n',char(10)),'{"ACCESS":"<Access","LOCATION":"<Door","PRIORITY":"<Priority","TYPE":"XIM"}',NULL,20531,4,0,NULL,NULL,NULL,'scan',1780048664);
INSERT INTO door_catalog VALUES('otl_an20','OTL-AN20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OTL-AN20.LHA','AnnLogoff','XIM','AnnLogoff','2.0',NULL,'OTL','__ _/\______/\___/\_ _\  /_________________. __ ___  ___  ____  /_ \\//                 | /  /  / /  / /  /__  \/ A great /X tool  |',replace('[-aNNOUNCE v2.0-]     ____  [-aQUARIUS/oTL-]\n__ _/\______/\___/\_ _\  /_________________.\n__ ___  ___  ____  /_ \\//                 |\n  /  /  / /  / /  /__  \/ A great /X tool  |\n /  /  / /  / /  /  / which notifies users |\n_\__  /_/  /_/___  /   on other nodes of   |\n____ /___ /__ ___ /  logons and logoffs,   |\nbIS\/   \/      \/  with ability to queue  |\n    messages when a user is uploading e.g. |\n-- -  -    - -- -   ---- - ---- -----------''\n','\n',char(10)),'Announce.guide',replace('@database Announce\n\nCopyright © 1994 Aquarius/Outlaws\n\n@Remark $VER: Announce v2.0 AmigaGuide doc\n\n@node MAIN "Announce v2.0 Documentation"\n\n       _ _ ___/\______/\__ ____/\___/\__ _ _/\____ _/\_ __ __/\______\n      __ ________   __   /   _   ___   / ______   \___/__/     _____/\n         bIS/   /   /   /   //   //   /___/ __¬   /  /  /  /\__   \\n           /   /   /   /   //   //   /   /  \    /  /  /  /   /   /\n    __  _ _\____  /\____  //_  //_____  /___/\  /\_____  /\ _/   /___\n     _  ___ _   \/  _  _\/_  \/____ __\/ ___ _\/_______\/____   /_ _/\n                                                            \  /\n                                  present                    \/\n                      a tool for AmiExpress 2.xx/3.xx:\n\n                 >>> Announce v2.0 by Aquarius/Outlaws <<<\n\n                      [- Contents of documentation -]\n\n                @{"   Copyright Note   " Link Copyright   }   @{" Miscellaneous Info " Link MiscInfo}\n                @{"  Archive Contents  " Link Archive     }   @{"  How to Reach Me   " Link ContactMe}\n                @{"    Introduction    " Link Introduction}   @{"      History       " Link History}\n                @{"    Requirements    " Link Requirements}   @{"     Greetings      " Link Greetings}\n                @{"    Installation    " Link Installation}\n@endnode\n\n@node Copyright "Announce v2.0 Documentation"\n\n                          Copyright ©1994 Aquarius\n\n                 Permission is granted to freely distribute\n               this product for non-commercial purposes only,\n                  as long as all files remain unmodified.\n\n@endnode\n\n@node Archive "Announce v2.0 Documentation"\n\nArchive (OTL-AN20.LHA) Contents\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nDoors/Announce/\n   AnnLogon.10             9724 bytes  10-node version of the door.\n   AnnLogon.32             9812 bytes  32-node version (for /X 3.30+)..\n   AnnLogoff               7884 bytes  CLI util for logoff messages.\n   Announce.doc            6805 bytes  Ascii version of the doc.\n   Announce.guide         12578 bytes  This document file!\n\nCommands/SYSCmd/\n   AnnLogon.info           1249 bytes  Command icon for /X 3.xx.\n\n@endnode\n\n@node Introduction "Announce v2.0 Documentation"\n\nIntroduction\n~~~~~~~~~~~~\nIf you are running a multi-node board, you just HAVE to try this tool!\nIt''s a really pleasant thing to have installed, for you and your users.\n\nWhat is does? Well, when a user logs on, it notifies the users who are\nalready online (on the other nodes) of the logon. You can also make it\nnotify them of logoffs (and loss carriers). If a message can''t be sent\nbecause the user is doing something (uploading, reading bulletins etc),\nthe message is queued. When he becomes idle again, he instantly gets all\nhis waiting logon/logoff messages. Here is an example of how that can\nlook:\n\n>>> Announce v2.0 by Aquarius/OTL <<<\n     ( Current time: 17:14:00 )\n\nHardHack logged in on node 3 at 17:07:37.\nErod logged off from node 1 at 17:09:13.\n\n>>>>\n@endnode\n\n@node Requirements "Announce v2.0 Documentation"\n\nRequirements\n~~~~~~~~~~~~\nAn Amiga with OS 2.0 or higher.\nAmiExpress/SigmaExpress.\n(The door works for sure on /X v2.20-3.38 and possibly on other versions\ntoo.)\n\n@endnode\n\n@node Installation "Announce v2.0 Documentation"\n\nInstallation\n~~~~~~~~~~~~\nFirst create the directory ''Doors:Announce'', and copy the correct version\nof the door there. AnnLogon.10 is for AmiExpress versions below 3.30 and\nfor SigmaExpress. AnnLogon.32 is for AmiExpress 3.30 or higher.\n\n/X 2.xx, SigmaExpress:\n\nAdd the following line to your SYS.Cmd file:\n\n-----Cut-here-------------------------------\n*ANNLOGON XM005Doors:Announce/AnnLogon.10\n-------Cut-here-----------------------------\n\n/X 3.xx:\n\nCopy ''annlogon.info'' to your SYSCmd directory and check that its tooltype\nLOCATION is correct.\n\n\nRun the door with MCI in the Logon.txt. Don''t worry, the door is totally\ninvisible to the on-logging users. Every Logon.txt should start with the\nfollowing:\n\n-----Cut-here-------------\n~\n~CC_ANNLOGON|\n-------Cut-here-----------\n\n\nThe logoff notifier is not necessary to install (in contrast to the logon\nnotifier) but I really recommend that you do it (it''s nice!). Then copy\nAnnLogoff to Doors:Announce/. Run it in the logoff scripts, preferably\namong the first commands. You must supply two arguments: the node number\nand the node location (defined in ACP.info for /X 3.xx) which for most\nsysops is the same as the bbs location (bbs:). For example, in the logoff\nscript for node 2, write this line:\n\n-----Cut-here------------------------\nDoors:Announce/AnnLogoff 2 BBS:\n-------Cut-here----------------------\n\n(Provided that the location for the directory ''Node2'' is ''BBS:''.)\n\nPerhaps you shouldn''t put it in the script for your local node, since you\nprobably always logon with F1 and therefore by-pass Logon.txt and the\nlogon notifier. It would probably confuse your users if they only got the\nmessage that you logged off, and they hadn''t even noticed that you were\nonline.\n@endnode\n\n@node MiscInfo "Announce v2.0 Documentation"\n\nMiscellaneous Info\n~~~~~~~~~~~~~~~~~~\nThe first time the door (AnnLogon.xx) is used, it stays in memory as a\n''host task'' that will perform all the actual message sending to the nodes\nat the right times. Therefore, no logoff messages can be sent before the\nlogon notifier has been used. But the logon notifier is normally started\nfirst so this shouldn''t be any problem. If the logoff notifier is run\nfirst, nothing happens (no system crash if that''s what you thought).\n\nIf you want to change to another version of the door (from 10-node to\n32-node for example) or you want to reset Announce (clear all waiting\nmessages), you will first need to remove the door from memory.\n\nThat is accomplished by sending it a CTRL-C signal, for example by using\nthe AmigaDOS ''break'' command. If you don''t know how to do that I can tell\nyou... Open a shell and type ''status'', which shows all loaded processes.\nOne of them should be Doors:Announce/AnnLogon or something. Notice the\nprocess number for it. Then type ''break <process>'', for example ''break 8''\nif the process number was 8. Type ''status'' again and the process should be\ngone.\n@endnode\n\n@node ContactMe "Announce v2.0 Documentation"\n\nContact Me!\n~~~~~~~~~~~\nIf you have any cool ideas for improvement of this tool, bug reports,\nquestions, or whatever, leave me a message on one of the following boards:\n\n@{"NIGHTFALL" Link Nightfall} ................ Prof Do Right ..... +46-90-120369\n@{"OVERLOAD" Link OverLoad} (OTL SHQ) ....... Vegas ............. +46-8-54063666\nHYSTERIA ................. JAC ............... +46-21-842939\nRAISING HELL ............. Psychopath ........ +46-23-26893\nINSIDE OUT ............... C/\TE¥E ........... +46-346-58697\n@{"SNAKE''S DEN" Link SnakesDen} (OTL WHQ) .... Snake ............. +1-513-683-2330\nTHE HOLE ................. Oldman ............ +1-419-899-2754\n\n@endnode\n\n@node History "Announce v2.0 Documentation"\n\nHistory\n~~~~~~~\n1.0  (1993-08-04) First release. It was then called ''AnnounceLogon''.\n\n2.0  (1994-04-24) Release version. The tool name was changed to just\n     ''Announce'' because I added logoff notification.\n\n     Messages are queued until the user becomes idle.\n\n     Messages are now sent without going via ARexx.\n\n     There are more news but I''m too lazy to describe them all.\n\n@endnode\n\n@node Greetings "Announce v2.0 Documentation"\n\nGreetings\n~~~~~~~~~\n               Greetings must go to (in no special order):\n\n      - All Members of Outlaws!! - Prof Do Right/Classic - JAC/TDS -\n    - C/\TE¥E/Insane - Ace Caze/Obscene - Wilsom/Obscene - Kid Curry -\n   - Psychopath - Vinzi - Karma - Zin - Shapechanger - Rize - Seagull -\n    - Remix/Classic - RaJ-Ban - fanta/Therion - Static/Therion - CaT -\n     - Dansken - AXL/Attention - Rad!/LSD - Vileius! - Marwin/Duplo -\n      - Freddy Kreuger/GOD - Chig/TDS - The Silencer - Vampire/PDY -\n       - Crocodile/Obscene - Sal-One - Nojje - Zune/HCD - MadCap -\n           - Metalbasher - WarDancer/H&V - The Ones I Forgot! -\n\n@endnode\n\n@node Nightfall "Announce v2.0 Documentation"\n+-------------------------------------------------------------------------+\n|         iNTO tOTAL dARKNESS, tHE uNKNOWN; cOME wALK wiTH mE...          |\n| a3ooo    ___/\       ___/\ ____/\__________/\ ___/   __/\ _________9ooMB|\n+----------\__  \______\__  \____  __________  \  /   \__  \   _____/-----+\n|         tS/    __    \/      /  /_____   /     /     /        /         |\n·          /      /    /      /     /     /           /        /          ·\n rEG. /X! /      /    /      /     /     /     /     /        /ClAsSiC SHQ\n         /______/    /______/___________/_____/     /________/\n  lOTs oF      /____/                        /     /      2ooo AD (PC) WHQ\n /X uTiLS!          ·3 uSR nODES·aMiGa&pC!· /     /\n    ___/\ _________/\ _________/\ ___   ___/     / sTAFF : pROF dO riGHT,\n    \__  \ ________  \_________  \  /   \__     / aQUARiUS, riZE, rEMiX,\n·    /    _____/ /     __    /     /_____/     /_____ mASTERmAN, nEMESiS  ·\n:   /      /    /      /    /     /     /     /     /                     :\n|  /      /    /      /    /     /     /     /     /   eNJOY tHE sPEED!   |\n+-/______/----/______/    /___________/___________/-----------------------+\n|                   /____/                                                |\n| node#1: +46-90-120369   node#2: +46-90-178169   node#3: +46-90-142969   |\n|      (14.4k DS)              (16.8k DS)              (14.4k HST)        |\n+-------------------------------------------------------------------------+\n@endnode\n\n@node OverLoad "Announce v2.0 Documentation"\n                             .\n                             :\n                             |__       ___                   __\n        _____________________|  \_____/   \_________________/  \\n        \________     __     |     __      ________________     \_\n   .______/     U     \/     |     \/      __)____/      |/   ___/_____.\n   |:::::/ _ _         \     :      \_     |/     \      |       \:::::|\n   |:::  \___/_________/____   ______/_______      \_____A  _ _   \__::|\n   |:       / |            \___/       __   \______/      \/ _______/ :|\n   |  _____/  |   ____________________/  \________________/    \____  .|\n   |. \__     |___\__________      ________      _________       __/  :|\n   |:.  /     |    ___/     U      \/     |\     \/      |\      \   .:|\n   |::s/      :     \               \     _/      \_      /       \s.::|\n   |::c\_________    \______________/     A________/_________     /c:::|\n   °-----------\_____/-------\___________/------------------\____/-----°\n   ::::::                                                         ::::::\n   |::               »»»  O U T L A W S   S H Q  «««                 ::|\n   |:                                                                 :|\n   |SYSOPS: VEGAS/OTL, BiSCROK/OTL, PURE PAiN/DCS, CRUGER/SR, NATAS/HZ |\n   |:                 SUPPORTING: AMiGA & CONSOLE!                    :|\n   |::     CALL AND MAKE SOME TRANSFERS NOW AT: +46-8-540-63666      ::|\n   |::: CALL TO GET THE LATEST OUTLAWS RELEASES FOR FREEDOWNLOAD!   :::|\n   |:::::::.             .:::NO NUP NEEDED!:::.                .:::::::|\n   `-------------------------------------------------------------------''\n@endnode\n\n@node SnakesDen "Announce v2.0 Documentation"\n\n<----------------------------OUTLAWS--W-H-Q----------------------------->\n   ___________  ______    _______ _____  ______ _________   ___________\n   \     ____/__\  __ \  _\  ___ \     |/     /_\  ___   \_''\     ____/_\n   _\  ___     \_\/ /  \/  \/  /  \    /    _/   \/  /____/ _\  ___     \_\n  /  \/  /      /  /    \_   _     \_ _      \_    _____)__/  \/  /      /\n /             /  /      /   /      /  \      /    \      /             /\n/_____________/__/______/___/______/____\    /___________/_____________/\n<----------------------------------------\__/SyK!------------------------>\n       Sysop`s: Snake & Nazgul          _________  _________   ______\n   cosys`s: Rofoe/LGC & SIGMA 909/OTL  _\  ___   \_\  ___   \__\  __ \\n   _   __  __ ___ ____ _____ ________ /  \/  /    \_\/  /____/  \/ /  \\n  //  / / / //  //   //    //       //      /      /  _____)__    /    \_\n //  /_/ /_//__//___//____//_______//      /      /   \      /   /      /\n                                   /_____________/__________/___/______/\n\n<---------------wOrKiN` oN: A 4ooo/4o-1omb-54ombHD-2GigDat--------------->\n\n<--------DiAL:   + 1 - 5 1 3 - 6 8 3 - 2 3 3 0  -  3 NoDeZ RiNGdOwN!----->\n\n<----------------MoDeM`s: 21.6k & 16.8k DST`s + 14.4k HST---------------->\n@endnode\n\n[EOF]','\n',char(10)),NULL,'auto-added',51274,3,0,NULL,NULL,'otl_an20','scan',1780048664);
INSERT INTO door_catalog VALUES('otl_aq10','OTL-AQ10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OTL-AQ10.LHA','AquaQuiet','XIM','AquaQuiet','1.0',NULL,'OTL','__ _/\______/\___/\_ _\  /_________________. __ ___  ___  ____  /_ \\//                 | /  /  / /  / /  /__  \/  Replacement for |',replace('[-aQUAqUIET v1.0-]    ____  [-aQUARIUS/oTL-]\n__ _/\______/\___/\_ _\  /_________________.\n__ ___  ___  ____  /_ \\//                 |\n  /  /  / /  / /  /__  \/  Replacement for |\n /  /  / /  / /  /  /   the AmiExpress ''Q'' |\n_\__  /_/  /_/___  / command. Configurable |\n____ /___ /__ ___ /  "quiet on/off" texts. |\nbIS\/   \/      \/ Small and residentable! |\n-- -  -    - -- -   ---- - ---- -----------''\n','\n',char(10)),'AquaQuiet.doc',replace('\n       _ _ ___/\______/\__ ____/\___/\__ _ _/\____ _/\_ __ __/\______\n      __ ________   __   /   _   ___   / ______   \___/__/     _____/\n         bIS/   /   /   /   //   //   /___/ __¬   /  /  /  /\__   \\n           /   /   /   /   //   //   /   /  \    /  /  /  /   /   /\n    __  _ _\____  /\____  //_  //_____  /___/\  /\_____  /\ _/   /___\n     _  ___ _   \/  _  _\/_  \/____ __\/ ___ _\/_______\/____   /_ _/\n                                                            \  /\n                                  present                    \/\n\n                    a door for AmiExpress/SigmaExpress:\n\n                >>> AquaQuiet v1.0 by Aquarius/Outlaws <<<\n\n\n                          Copyright ©1994 Aquarius\n\n                 Permission is granted to freely distribute\n               this product for non-commercial purposes only,\n                  as long as all files remain unmodified.\n\n\n\nArchive (OTL-AQ10.LHA) Contents\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nDoors/AquaQuiet                 3460 bytes    The door.\nDoors/AquaQuiet.doc             4712 bytes    This document.\nCommands/BBSCmd/q.info          1250 bytes    Command icon for /X 3.xx.\nENV/AquaQuiet.OffText             95 bytes    A sample "quiet off" text.\nENV/AquaQuiet.OnText              77 bytes    A sample "quiet on" text.\n\n\nIntroduction\n~~~~~~~~~~~~\nThis is a replacement for the internal Q command, to toggle whether a node\nis quiet (not visible to others) or not. The bad thing about the internal\nQ command is that it never displays anything! AquaQuiet shows if the node\nwas made quiet or if the "quietness" was turned off. You can define the\ntexts to be shown yourself. Also, if the user hasn''t got access to make\nthe node quiet the internal Q command says nothing! He has to use WHO to\ncheck if it worked or not. AquaQuiet on the other hand displays "Commands\nrequires higher access."\n\n\nInstallation\n~~~~~~~~~~~~\nInstallation is very easy. You can put the door anywhere, for example in\nDoors:. It is an XIM type door. A command icon for AmiExpress 3.x+ is\nprovided. Put it in your BBSCmd drawer.\n\nFor AmiExpress 2.xx and SigmaExpress, insert this line in your BBS.CMD:\n---- Cut here --------------------------------\n*Q        XM001Doors:AquaQuiet\n------ Cut here ------------------------------\n\nNote that the door access can be set to 1 (the lowest possible) because\nAquaQuiet checks if the user has access to make the node quiet, which in\n/X 3.xx is determined by the presence of ACS.QUIET_NODE in the user''s\naccess icon.\n\nThe default text shown when a node is made quiet is "Quiet On". If you\nwant something else to be shown, write that in ''ENV:AquaQuiet.OnText''. The\ndefault text for making a node NOT quiet is "Quiet Off". If you want\nsomething else to be shown, write that in ''ENV:AquaQuiet.OffText''. Put\nthese two files in ENVARC: as well, so that they are always copied to ENV:\nat reboot.\n\nThis door can be made resident. But you won''t gain much in doing so - it\nis very small and is loaded in no-time.\n\n\nContact Me!\n~~~~~~~~~~~\nIf you have any cool ideas for improvement of this door, questions, bug\nreports or whatever, leave me a message on one of the following boards:\n\nNIGHTFALL ................ Whoosh ............ +46-90-120369  <---  Safest\nHALL OF FAME ............. Dansken ........... +46-910-26665      place to\nHYSTERIA ................. JAC ............... +46-21-842939     reach me!\nMASTURBATION STATION ..... Black Beard ....... +1-305-552-1192\nZION''S HIDEOUT ........... Zion .............. +1-614-876-0807\nDARK TOWER ............... Shadower .......... +1-801-476-9068\nMORTUARY ................. Bloodwolf ......... +1-312-284-7577\nBOONDOCKS ................ Sal-One! .......... +31-548-040-653\n\n\nHistory\n~~~~~~~\n1.0  (09-17-94) First release version.\n\n\nGreetings\n~~~~~~~~~\n                Greetings must go to (in no special order):\n\n           - Vegas/OTL - Biscrok/OTL - Toxic/OTL - AtomiX!/OTL -\n       - Whoosh/OTT^KRL^OTL^CLS - Snake/OTL - Nashua/OTL - SMS/OTL -\n    - Genghis Khan/OTL - The Other OTL Members! - Dansken - CornFlake -\n  - Ace Caze/Obscene - Firehawk! - fanta/THR - Static/THR - FAX! - Juan -\n - Psychopath - Danzig - Foss - Karma - Seagull - Marwin - CaT - Sal-One -\n - Metalbasher - No Limit - BoneIdle - Wilsom/Obscene - Stab - Kid Curry -\n - Chig/TDS - HardHack - Rize - Frosty - JAC/TDS - C/\TE¥E - AXL - Norad -\n - Crocodile - Freddy Kreuger/GOD - Doc Whoo - Zion! - Nocturne - Brutus -\n  - FireFlash/OTT - MDR/OTT - Neutralizer/OTT - Bytehunter/OTT - Remix! -\n    - WarDancer - Json/Kingdom - Slobo & Whale - [-HSR & MM-] - HiFly -\n      - Uffe - Gi Joe - Princip - The Silencer - Ezco - Vampire/PDY -\n          - Nero - Deltaforce! - Afterlife - The Ones I Forgot! -\n\n\n\n[EOF]\n','\n',char(10)),NULL,'auto-added',7464,3,0,NULL,NULL,'otl_aq10','scan',1780048664);
INSERT INTO door_catalog VALUES('otl_aq11','OTL-AQ11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OTL-AQ11.LHA','AquaQuiet','XIM','AquaQuiet','1.1',NULL,'OTL','._________ ___ __ _/\______/  _/_ _/\__ ___. |               //____   __  ___/_/   /___ | | Replacement    /   /   /   /   /   /   / |',replace('[-aQUAqUIET v1.1-]          /\__[-aQUARIUS-]\n._________ ___ __ _/\______/  _/_ _/\__ ___.\n|               //____   __  ___/_/   /___ |\n| Replacement    /   /   /   /   /   /   / |\n| for the ''Q''   _\___   /\___   /____   /__|\n| command in     _ ___ /__ ___ /_ ____ /__/|\n| /X, S!X etc.       \/      \/ -bIS!\/    |\n| Now even smaller, and 100% safe!         |\n`------------------------------------------''\n','\n',char(10)),'AquaQuiet.guide',replace('@database AquaQuiet\n@author Aquarius/Outlaws\n@$VER: AquaQuiet.guide 1.1 (28.1.95)\n\n@node MAIN "AquaQuiet v1.1 Documentation"\n       _ _ ___/\______/\__ ____/\___/\__ _ _/\____ _/\_ __ __/\______\n      __ ________   __   /   _   ___   / ______   \___/__/     _____/\n         bIS/   /   /   /   //   //   /___/ __¬   /  /  /  /\__   \\n           /   /   /   /   //   //   /   /  \    /  /  /  /   /   /\n    __  _ _\____  /\____  //_  //_____  /___/\  /\_____  /\ _/   /___\n     _  ___ _   \/  _  _\/_  \/____ __\/ ___ _\/_______\/____   /_ _/\n                                                            \  /\n                                  present:                   \/\n\n                >>> AquaQuiet v1.1 by Aquarius/Outlaws <<<\n\n                      [- Contents of Documentation -]\n\n                @{"   Copyright Note   " Link Copyright   }   @{"      History       " Link History}\n                @{"  Archive Contents  " Link Archive     }   @{"  How to Reach Me   " Link ContactMe}\n                @{"    Introduction    " Link Introduction}   @{"    Other Tools     " Link AquaTools}\n                @{"    Requirements    " Link Requirements}   @{"     Greetings      " Link Greetings}\n                @{"    Installation    " Link Installation}\n\n           @{" Comment on AQUA-FUQ.TXT " Link FuckText}   @{" Note about AquaSettings " Link AquaSettings}\n@endnode\n\n@node Copyright "AquaQuiet v1.1 Documentation"\n\n                          Copyright ©1995 Aquarius\n\n                 Permission is granted to freely distribute\n               this product for non-commercial purposes only,\n                  as long as all files remain unmodified.\n@endnode\n\n@node Archive "AquaQuiet v1.1 Documentation"\n\nArchive (OTL-AQ11.LHA) Contents\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nDoors/AquaQuiet              1460 bytes   The door itself.\nDoors/AquaQuet.guide        17229 bytes   This AmigaGuide doc!\nCommands/BBSCmd/Q.info       1265 bytes   Command icon for /X 3.0+.\nENV/AquaQuiet.OffText          95 bytes   A sample "quiet off" text.\nENV/AquaQuiet.OnText           77 bytes   A sample "quiet on" text.\n@endnode\n\n@node Introduction "AquaQuiet v1.1 Documentation"\n\nIntroduction\n~~~~~~~~~~~~\nThis is a replacement for the internal Q command, to toggle whether a node\nis quiet (not visible to others) or not. The bad thing about the internal\nQ command is that it never displays anything! AquaQuiet shows if the node\nwas made quiet or if the "quietness" was turned off. You can define the\ntexts to be shown yourself. Also, if the user hasn''t got access to make\nthe node quiet the internal Q command says nothing! He has to use WHO to\ncheck if it worked or not. AquaQuiet on the other hand displays "Commands\nrequires higher access."\n@endnode\n\n@node Requirements "AquaQuiet v1.1 Documentation"\n\nRequirements\n~~~~~~~~~~~~\n- An Amiga with OS 2.0 or higher.\n\n- AmiExpress, SigmaExpress or any compatible program.\n@endnode\n\n@node Installation "AquaQuiet v1.1 Documentation"\n\nInstallation\n~~~~~~~~~~~~\nInstallation is very easy. You can put the door anywhere, for example in\n''Doors:''. It is an XIM type door. A command icon for AmiExpress 3.0+,\n''Q.info'', is provided. Put it in your ''BBSCmd'' drawer.\n\nFor AmiExpress 2.xx and SigmaExpress, insert this line in your BBS.CMD:\n---- Cut here --------------------------------\n*Q        XM001Doors:AquaQuiet\n------ Cut here ------------------------------\n\nNote that the door access can be set to 1 (the lowest possible), because\nAquaQuiet checks if the user has access to make the node quiet, which in\n/X 3.0+ is determined by the presence of ''ACS.QUIET_NODE'' in the user''s\naccess icon.\n\nThe default text shown when a node is made quiet is "Quiet On". If you\nwant something else to be shown, write that in ''ENV:AquaQuiet.OnText''. The\ndefault text for making a node NOT quiet is "Quiet Off". If you want\nsomething else to be shown, write that in ''ENV:AquaQuiet.OffText''. Put\nthese two files in ''ENVARC:'' as well, so that they are always copied to\n''ENV:'' at reboot.\n\nAquaQuiet is "pure" and is therefore perfectly safe to make resident.\n@endnode\n\n@node History "AquaQuiet v1.1 Documentation"\n\nHistory\n~~~~~~~\n\n1.0  (09-17-94) First release version.\n\n\n1.1  (01-28-95) Second release. Version 1.0 could hang the node,\n                particularly if it was resident. Fixed that!\n\n                Made some internal changes that halved the size of the\n                executable!\n\n\n        I usually do more changes than this before releasing an update of\n        a door, but I can''t see what more can be improved...\n@endnode\n\n@node ContactMe "AquaQuiet v1.1 Documentation"\n\nContact Me!\n~~~~~~~~~~~\nIf you have any cool ideas for improvement of this tool, questions, bug\nreports or whatever, contact me on one of the following boards:\n\n@{"NIGHTFALL" Link NIGHTFALL} ................ Whoosh ............ +46-90120369  <---  Safest\nHALL OF FAME ............. Dansken ........... +46-91026665      place to\nACES HIGH ................ Norad ............. +46-41044886     reach me!\nINTERCHANGE .............. Princip ........... +46-86082339\nZION''S HIDEOUT ........... Zion .............. +1-PRIVATE!!\nDEATH ROW ................ Shadower .......... +1-PRIVATE!!\nBOONDOCKS ................ Sal-One ........... +31-PRIVATE!!\n@endnode\n\n@node AquaTools "AquaQuiet v1.1 Documentation"\n\nThe AquaTools Collection\n~~~~~~~~~~~~~~~~~~~~~~~~\nHere is the complete list of my released tools (the latest versions):\n\nTool Name              File Name     Short Description\n---------------------- ------------- ------------------------------------------\nDisable v1.1           AQDSBL11.LHA  Payuser handling system.\nDisplayer v1.0         AQDSPL10.LHA  Text displayer. Perfect for door menu e.g.\nNetEdit v1.0           AQNETE10.LHA  Editor for certain netmail systems.\nConfReplace v1.0       OTL-CR10.LHA  Find and replace area names in User.Data.\nListSpeeder v2.1       OTL-LS21.LHA  Filelist downloader.\nAnnounce v2.0          OTL-AN20.LHA  Notifies online users of logons/logoffs.\nAquaWho v2.0           OTL-AW20.LHA  Totally configurable WHO door!\nSpeedCheck v2.1        OTL-SC21.LHA  Disables download at too low connect rates.\nStripper v1.2          OTL-ST12.LHA  Strips log files to desired file sizes.\nAquaScan v1.0          OTL-AS10.LHA  File scanner! (F, N, CS, FR.)\nAquaCreateAcc v1.0     OTL-CA10.LHA  Door to create new accounts with.\nAquaMoveFiles v1.0     OTL-MF10.LHA  File and description mover, by date.\nAquaSafety v1.0        OTL-SA10.LHA  Anti-BBS-downtime utility.\nAquaAdder v1.0         OTL-AA10.LHA  Text adder.\nAquaBulls v2.0         OTL-AB20.LHA  Bulletin viewer.\nAquaQuick v1.0         OTL-QK10.LHA  Quick-logon door.\nRestoreQuietness v1.0  OTL-RQ10.LHA  Restores the nodes'' "quietness" at logoff.\nAquaSettings v1.0      OTL-SE10.LHA  ''W'' replacement. Menu of config commands.\nAquaQuiet v1.1         OTL-AQ11.LHA  ''Q'' replacement. Toggles quiet node.\nAquaPWFail v1.0        OTL-PW10.LHA  Password failure door.\nAquaTopChat v1.0       OTL-TC10.LHA  Top-chat door.\n\n(...and more are coming!)\n\nYou can find them all on @{"Nightfall" Link NIGHTFALL} +46-90-120369 (free download)!\n@endnode\n\n@node BetaTesters "AquaQuiet v1.1 Documentation"\n\nBeta Testers\n~~~~~~~~~~~~\nThese are my beta testers. My tools wouldn''t have been as good as they\nare now if it hadn''t been for them. Many thanks dudes!\n\nACE CAZE ................. Dragon''s Lair ........ +46-16147118\nEZCO ..................... Serpent Hill ......... +46-8800293\nDANSKEN .................. Hall of Fame ......... +46-91026665\nFIREHAWK ................. Hardware Tower ....... +46-OFFLINE!\nKID CURRY ................ Pet Sematary ......... +46-PRIVATE!\nLOCKJAMMER ............... Substate ............. +46-OFFLINE!\nMARKY & POWER ............ Spread Draft ......... +49-PRIVATE!\nNASHUA ................... MegaByte ............. +45-42881885\nPLAYMATE ................. Northern Empire ...... +45-39619420\nPRINCIP .................. Interchange .......... +46-PRIVATE!\nPSYCHOPATH ............... Raising Hell ......... +46-243227029\nRIZE & FROSTY ............ Another World ........ +46-48088100\nSANDMAN .................. reference-board ............ +46-31918587\nSTATIC & FANTA ........... Frosen Assets ........ +46-322665225\nVEGAS & BISCROK .......... Overload ............. +46-OFFLINE!\nVITAL .................... Future Entrance ...... +46-60574467\nWHOOSH ................... @{"Nightfall" Link NIGHTFALL} ............ +46-90120369\nWIZE & HIFLY ............. Waterdeep ............ +46-PRIVATE!\n@endnode\n\n@node Greetings "AquaQuiet v1.1 Documentation"\n\nGreetings\n~~~~~~~~~\n                Greetings must go to (in no special order):\n\n           - Vegas/OTL - Biscrok/OTL - Toxic/OTL - Nashua/OTL -\n     - Snake/OTL - Whoosh/OTT^DVS^CLS^OTL^R2 - AtomiX!/OTL - SMS/OTL -\n   - Genghis Khan/OTL - The Other OTL Members - Ace Caze - Dansken/ACS -\n  - Princip! - Sandman - Rize & Frosty - Static & fanta - Marky & Power -\n  - Psychopath - Norad - Firehawk - Marwin - Danzig! - Lockjammer - MDR -\n  - HardHack - Chig - Kid Curry - Ezco - Enzo - Playmate - HiFly - Wize -\n   - Wild Thing - Juan! - Wilsom - Gi Joe - Sal-One - Zion! - Shadower -\n    - Doc Whoo - FAX - JAz - Bowen/OTT - Json - WarDancer - CornFlake -\n       - Bilbo Baggins - Sasha - Metalbasher - Psyche - CountZero! -\n               - Vital - Karma - Kain - Vileius - Nike/DLT -\n                       - And The Friends I Forgot! -\n\n\n                    Special thanks to my @{"beta testers" Link BetaTesters}!!\n\n\n                         A few personal messages:\n\nWhoosh         - Whooopssss... Nice chatting with you every day. :)\n\nToxic/OTL      - Hard getting cards isn''t it? If you can, call Nightfall\n                 (new pwfail door hehe)!\n\nVegas/OTL      - Yeah let''s get the Swedish section rocking! I mean, MORE!\n                 Btw, Norrland is such a nice place, don''t you think? :)\n\nBiscrok/OTL    - The master of strange (tüffa) modules. ;)\n\nDansken        - Great friend and beta tester! Learn C soon!! hehe\n\nMarky & Power  - Hope you can find a new way to call...\n\nEzco           - Great Who designs!!\n\nAce Caze       - Funny dude and great beta tester! Ok, nothing wrong with\n                 topaz 8! You just need a magnifying glass..\n\nSnowman/Ex.OTL - Where did you disappear??? Get in touch, mate..\n@endnode\n\n@node NIGHTFALL "AquaQuiet v1.1 Documentation"\n+-------------------------------------------------------------------------+\n|         iNTO tOTAL dARKNESS, tHE uNKNOWN; cOME wALK wiTH mE...          |\n| a3ooo    ___/\       ___/\ ____/\__________/\ ___/   __/\ _________9ooMB|\n+----------\__  \______\__  \____  __________  \  /   \__  \   _____/-----+\n|         tS/    __    \/      /  /_____   /     /     /        /         |\n· /X 4.xx  /      /    /      /     /     /           /        /    r2 sHQ·\n          /      /    /      /     /     /     /     /        /    dVS sHQ\n   eNJOY /______/    /______/___________/_____/     /________/    oTT  sHQ\n   tHE         /____/                        /     /         oTL diST siTE\n sPEED!             ·3 uSR nODES riNGDOWN!· /     /\n    ___/\ _________/\ _________/\ ___   ___/     / sTAFF: wHOOSH, aQUARiUS,\n    \__  \ ________  \_________  \  /   \__     / riZE, mASTERmAN, nEMESiS\n·    /    _____/ /     __    /     /_____/     /_____                     ·\n:   /      /    /      /    /     /     /     /     /    mORE tHAN 1200   :\n|  /      /    /      /    /     /     /     /     / aMiX tOOLS oNLiNE!!  |\n+-/______/----/______/    /___________/___________/-----------------------+\n|                   /____/                                                |\n| nODE#1: +46-90-120369   nODE#2: +46-riNGDOWN!!  nODE#3: +46-riNGDOWN!!  |\n|      (14.4k DS)              (16.8k DS)              (28.8k DS)         |\n+-------------------------------------------------------------------------+\n@endnode\n\n@node FuckText "AquaQuiet v1.1 Documentation"\n\nComment on AQUA-FUQ.TXT\n~~~~~~~~~~~~~~~~~~~~~~~\n\n--vv-vv----------------- START OF "AQUA-FUQ.TXT" ------------------vv-vv--\n\n@BEGIN_FILE_ID.DIZ\n--------------------------------------------\nPot-Noodle speaks: All of AQUARIUS /X doors\nare MY sources that HE edited! This is fuqn\nLAME! I bet he put alot of BACKDOORS in them\ntoo! DONT USE THEM! There''s PROOF in this\ntext that shows that I made all the doors!\n-------------------------[ P0t-N00dle/atx ]-\n@END_FILE_ID.DIZ\n\nI''m UPSET! About 1 year ago, Aquarius were a active user of my bbs, and he\ntold me he were an /X tool developer, so i gave him access to my /X tool/source\nconferance, and he leeched all of my unreleased utils in this conf.\nNow, 1 year later, i see more and more of them poppin up as ''quack-wa-scan''\nand whatever. I have no idea what he might have added more then just his\nname to my doors, but i would suggest you NOT to use them.\n\n                                                           >p0t-n00dle/anThrox<\n\n--^^-^^------------------ END OF "AQUA-FUQ.TXT" -------------------^^-^^--\n\nIf you''ve had the bad luck to have seen this text, you have probably\nfigured out that it is total bullshit. Then you''re absolutely right! It is\nplain lies! I haven''t even called P0T-NOoDLE''s BBS, EVER! This text is\njust another attempt from some lame "wanna-be" to destroy for a guy\nworking hard to supply the scene with backdoor-free, quality /X tools. It\nmakes me sad, whoever it is being attacked with lies like that. Can''t the\npitiful lamers producing such crap do something positive, instead of just\ntrying to destroy for others? I guess not... But then they should get the\nfuck out of the scene, at least until they''ve grown up!!\n\nThe lamer who wrote AQUA-FUQ.TXT is also abusing the highly respected name\nP0T-NOoDLE (great tools man!). Of course it''s not P0T-NOoDLE who wrote it.\nA few observations to make:\n\n* P0T-NOoDLE is English and I don''t think he would write "Aquarius were a\n  active user"... I''m sure the real writer has done his best to get it\n  right.\n\n* As far as I know, P0T-NOoDLE codes his tools in assembler (and some in\n  ARexx). I write mine in C, so how could I have stolen and edited his\n  sources??\n\n* P0T-NOoDLE has never used icons as config. I do it in most of my tools.\n\nAnd so on... If you still (!) have any doubts, take a look at the doc for\nP0T-NOoDLE''s excellent Super-DupeCheck v1.03 and the list of his\nunreleased tools. Then you''ll see that I haven''t made a single one like\nany of those.\n\nYou can also ask any of my @{"beta testers" Link BetaTesters}. They can assure you that my tools\nhave been DEVELOPED and weren''t just suddenly finished. For example\nAquaScan - it was rather simple in the beginning; no scroll-back, no\nflagging by number, no date/file separators etc.\n\nAnd about the "accusation" of backdoors... Do you think I would spend most\nof my spare time writing lame backdoors?! Of course not! I code /X tools\nfor fun and for others to enjoy. And obviously people DO enjoy them. :)\nAs an example, Sasha (Datalus BBS, UK) just told me about AquaScan:\n"every (and i mean every) bbs in the uk uses it!"... That''s the only\nreward I want for my work; to hear that my tools are appreciated.\n\nSo if you see AQUA-FUQ.TXT somewhere, or any other text like that, nuke it\nto hell!\n\nOk, enough about this CRAP!\n@endnode\n\n@node AquaSettings "AquaQuiet v1.1 Documentation"\n\nNote about AquaSettings\n~~~~~~~~~~~~~~~~~~~~~~~\nFirst of all, I''m glad so many boards are using AquaSettings! Just a few\ndays after release and suddenly it''s installed on every other board! Cool!\n\nBut it seems I made a little mistake in the AquaSettings v1.0 archive..\nIn the provided configuration icon ''AquaSettings.info'', the ''CMD.1''\ntooltype was set to ''W''. It SHOULD have been ''W_INTERNAL''. This only goes\nfor AmiExpress 3.xx/4.xx. The icon was correct for SigmaExpress and\nAmiExpress 2.xx. I did write about that in the doc, but there I assumed\n''CMD.1'' was ''W_INTERNAL'' from the beginning.\n\nSo what''s the difference? Well, when you start AquaSettings you get a menu\nof different configuration stuff. The first entry is "Basic settings", or\nwhatever you name it, i.e. it starts the internal W command. But if\n''CMD.1=W'' then the door won''t be able to return to the menu again. That''s\nbecause of a limitation in AmiExpress/S-Express which doesn''t let any door\nrun an internal command (with the same name as a door), without quitting\nthe door first. But the W_INTERNAL command is a way around this. If you\nuse ''CMD.1=W_INTERNAL'' with AmiExpress 3.xx/4.xx, then "Basic settings"\nwill behave like all the other menu entries: you will be taken back to the\nAquaSettings menu afterwards.\n\nI haven''t seen it changed on any board, so what I have learnt from this is\nthat the contents of provided configuration files are very important, and\nthat most sysops don''t bother to read the doc entirely and check the\nconfiguration, which is a bit unfortunate.\n\n  .------------------------------------------------------------------.\n  | If you''re running AmiExpress 3.xx/4.xx, change ''CMD.1=W'' to      |\n  | ''CMD.1=W_INTERNAL'' in ''Doors:AquaSettings/AquaSettings.info'',    |\n  | and make sure you have copied ''W_INTERNAL.info'' from the archive |\n  | (OTL-SE10.LHA) to your ''BBSCmd'' drawer (NOT ''SYSCmd'').           |\n  `------------------------------------------------------------------''\n@endnode\n\n[EOF]\n','\n',char(10)),NULL,'auto-added',11211,3,0,NULL,NULL,'otl_aq10','scan',1780048664);
INSERT INTO door_catalog VALUES('otl_as10','OTL-AS10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OTL-AS10.LHA','AquaScanConfig','XIM','AquaScan.000','1.0',NULL,'OTL','__ _/\______/\___/\_ _\  /_________________. __ ___  ___  ____  /_ \\//                 | /  /  / /  / /  /__  \/The best filelist |',replace('[-aQUAsCAN v1.0-]     ____  [-aQUARIUS/oTL-]\n__ _/\______/\___/\_ _\  /_________________.\n__ ___  ___  ____  /_ \\//                 |\n  /  /  / /  / /  /__  \/The best filelist |\n /  /  / /  / /  /  / scanner ever for /X! |\n_\__  /_/  /_/___  /  Can be used as F, N, |\n____ /___ /__ ___ /  FR (reverse scan) and |\nbIS\/   \/      \/ CS (conf scan).  FAST!! |\n  Go back with UpArrow. Fully configurable |\n for both sysop and users.  And much more! |\n-- -  -    - -- -   ---- - ---- -----------''\n','\n',char(10)),'AquaScan.doc',replace('\n       _ _ ___/\______/\__ ____/\___/\__ _ _/\____ _/\_ __ __/\______\n      __ ________   __   /   _   ___   / ______   \___/__/     _____/\n         bIS/   /   /   /   //   //   /___/ __¬   /  /  /  /\__   \\n           /   /   /   /   //   //   /   /  \    /  /  /  /   /   /\n    __  _ _\____  /\____  //_  //_____  /___/\  /\_____  /\ _/   /___\n     _  ___ _   \/  _  _\/_  \/____ __\/ ___ _\/_______\/____   /_ _/\n                                                            \  /\n                                  present                    \/\n\n                the AmiExpress file scanner of your dreams:\n\n                 >>> AquaScan v1.0 by Aquarius/Outlaws <<<\n\n\n                          Copyright ©1994 Aquarius\n\n                 Permission is granted to freely distribute\n               this product for non-commercial purposes only,\n                  as long as all files remain unmodified.\n\n\nArchive (OTL-AS10.LHA) Contents\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nDoors/AquaScan/\n   AquaScan.000             34856 bytes  The door (for any CPU.)\n   AquaScan.020             33164 bytes  020+ version of the door.\n   AquaScanConfig           26048 bytes  An executable that AquaScan uses.\n   AquaScan.info              473 bytes  Sample configuration icon.\n   AquaScan.doc             22339 bytes  This document file!\n   AquaScan.Date.1            120 bytes  Date divider\n   AquaScan.Date.2            187 bytes  Date divider\n   AquaScan.Div.1              77 bytes  File divider\n   AquaScan.Div.2              78 bytes  File divider\n   AquaScan.Div.3              77 bytes  File divider\n   AquaScan.Div.4              78 bytes  File divider\n   AquaScan.Div.5              77 bytes  File divider\n   AquaScan.Div.6              79 bytes  File divider\n   AquaScan.Help.CS.txt       947 bytes  Help text for the CS command.\n   AquaScan.Help.F.txt        685 bytes  Help text for the F command.\n   AquaScan.Help.FR.txt       479 bytes  Help text for the FR command.\n   AquaScan.Help.N.txt        944 bytes  Help text for the N command.\n   AquaScan.Help.NSU.txt      965 bytes  Help text for the NSU command.\n   AquaScan.Help.SCAN.txt     983 bytes  Help text for the SCAN command.\n\nCommands/BBSCmd/\n   f.info                    1274 bytes  Command icon for /X 3.x/4.x.\n   n.info                    1274 bytes  Command icon for /X 3.x/4.x.\n   fr.info                   1274 bytes  Command icon for /X 3.x/4.x.\n   cs.info                   1274 bytes  Command icon for /X 3.x/4.x.\n   nsu.info                  1274 bytes  Command icon for /X 3.x/4.x.\n   scan.info                 1274 bytes  Command icon for /X 3.x/4.x.\n\nCommands/SYSCmd/\n   n.info                    1274 bytes  Command icon for /X 3.37+.\n\n\nIntroduction\n~~~~~~~~~~~~\nAquaScan is a very powerful, flexible and convenient file scanner for\nAmiExpress boards. It can be used as the normal F command, as a newscan\ndoor (the N command), files-reverse door (FR) and a confscan door (CS, NSU\netc). All this in ONE door! Since a file scanner is one of the most used\ndoors on a BBS, I have coded AquaScan so that it is ''pure'' and can be made\nresident. It is written in highly optimized C code for great performance.\nI even had an assembler expert (hi Chig) take a look at the output code to\nsee if the routines could be made any faster in assembler but he said I\nwould gain almost nothing. You have to try this door, you won''t be\ndisappointed! Just take a look at all the features...\n\n\nFeatures\n~~~~~~~~\n* If you want to go back in the filelist, that''s not a problem! Just press\n  the UpArrow key and it''ll take you one page back.\n\n* Any command/door can be started from the pause prompt! For example, you\n  can view archives (if you have an archive viewer installed) directly\n  when you see the files in the filelist. If you spot a fake, just press a\n  key and your favourite nuker will be loaded and you can delete the file.\n  Afterwards, the last page of files will be rewritten and you can\n  continue scanning files. If you change the filelist with a pause prompt\n  command (like the nuker), you will not see those changes because the\n  whole filelisting is loaded in memory, but by pressing L it will be\n  re-loaded and you will see the changes you made.\n\n* You can flag files by numbers. AquaScan can also be made to ask for file\n  numbers to pass as argument to certain pause prompt commands/doors, for\n  example to a file viewer, a faker/nuker and Whof (by Spock). This is\n  very convenient! Try it!\n\n* As first filescan door ever, AquaScan has the ability to show "the x\n  newest files". For example ''N !12'' shows the 12 newest files in the\n  current conference, ''CS !4'' shows the 4 newest files in every\n  conference. This is very practical, especially for you, the sysop. When\n  you logon, AmiExpress might say "Conference [- Amiga Elite -] has 13 new\n  uploads." Then just type ''n !13'' and those files will be listed...\n\n* Listing the files in reverse chronological order can not only be done\n  with FR but with all AquaScan commands. The R option does the trick. For\n  example, ''CS R'' lists files reversely in all conferences. When you have\n  seen enough in a conference, press S = ''Skip conf''.\n\n* There is a quick-scan mode. The user will only see the first line of\n  every file description when that is used.\n\n* You can break the filelisting and abort AquaScan with CTRL-C.\n\n* It is fully user configurable! The following settings are available:\n\n    - The colour of every part of a file can be configured - name, test\n      char, size, date, description etc. Available colours are the usual\n      white, red, green, yellow, blue, violet and cyan, but also RANDOM\n      colour!\n\n    - Divider between files - none, empty line or any of the custom\n      dividers you make available to your users. You can make up to 8\n      custom separator styles.\n\n    - Date dividers - none or any of the custom date dividers you provide.\n      You can make up to 8 custom date divider styles.\n\n    - Full description with the C (Clear) command at the pause prompt?\n\n    - Full description with Enter/Y/Space? If YES, the file at the top\n      of the screen will always be complete, never broken.\n\n    - Clear screen with Enter/Y/Space?\n\n    - Clear screen when skipping dir/conf?\n\n    - Clear screen at door startup?\n\n    - Verify non-stop scrolling? AquaScan is the first scanner ever with\n      this feature! It could happen that you type N (for "No more") and\n      then change your mind about quitting and press S (for "Skip conf").\n      Then you will get a last chance to verify if you really want to\n      scroll non-stop. Of course you can break the file listing with\n      CTRL-C but sometimes with bad lines the CTRL-C doesn''t seem to go\n      though.\n\n    - Non-stop scroll delay (in ticks). If you have problems breaking the\n      file listing you can set a delay so that the scrolling gets slower.\n      This only applies when you''re scrolling non-stop, so you will only\n      get slower scrolling in non-stop mode. 1 tick is 1/50 seconds.\n\n    - Detect CTRL-C only in non-stop mode?\n\n    - Always show only first line of every description? If YES, the Q\n      option ("Quick scan") will always be enabled.\n\n    - Which conferences to scan with CS, SCAN etc is user configurable.\n      The users will of course only be able to scan the conferences that\n      they have access to and that aren''t disabled for conference scanning\n      by the sysop.\n\n* The sysop configuration can be made in an icon, or in a textfile if you\n  prefer that! Among other things, you can configure the following:\n\n    - Conferences to disable for confscan. It would be possible that the\n      door detected mail-only conferences and just didn''t display them,\n      but this way you get more SPEED! Strictly private conferences\n      could be written here too if you want the users with access to them\n      to be forced to join them (and enter a conference password perhaps)\n      in order to see the files there.\n\n    - You can define every command, if it is a filescan, newscan or\n      confscan command, or a reverse lister. AquaScan doesn''t do any\n      automatic command detection (which would be a limitation).\n\n    - Access level required to scan HOLD directories can be configured.\n\n    - Default colours in the file listing, for users who don''t bother\n      to configure the colours themselves.\n\n    - Default date and file divider, and if file numbers should be enabled\n      by default or not.\n\n\nRequirements\n~~~~~~~~~~~~\nAquaScan is written for AmiExpress 3.xx+ but it is possible to use it with\nearlier version and SigmaExpress. You just have to make sure that you have\ncertain icons that AmiExpress 3.xx uses: Conference icons, AREA icons and\nConfConfig.info. Ask any sysop with AmiExpress 3.xx+ if you want help with\nwhat they should contain.\n\nYou need enough memory to hold your largest dir listing. So keep your dir\nlistings small if you have little memory! Use my utility AquaMoveFiles if\nyou need one that moves files + descriptions that are older than x days\nfrom one dir to another.\n\n\nInstallation\n~~~~~~~~~~~~\nJust copy the AquaScan directory (the inner one) from the archive to\nDoors:.\n\nNOTE!!\nMake sure that the file comments of the divider/separator files are\npreserved! They are used in the configuration editor (when the user gives\nW as argument) as descriptions for the different dividers.\n\nCopy the provided command icons to your BBSCmd drawer and edit its\ntooltypes if they don''t suit you. Note that AquaScan.020 is for\n68020/030/040/060 only. Set LOCATION=Doors:AquaScan/AquaScan.000 if you\nhave a slower processor.\n\nAs of AmiExpress 3.37 you can put N.info in SYSCmd/ as well, if you want\nAquaScan to be used for filescan at login (configurable via the AmiExpress\nCF command).\n\nAquaScan can be made resident. This means that ONLY ONE copy of the door\nis in memory AT ALL TIMES. You will get rid of the loading times and get\nless memory usage. To make it resident, do like this:\n\n1. Execute the following line and insert it in your ''S:User-Startup'':\n   "resident AquaScan Doors:AquaScan/AquaScan.0X0 pure"\n\n     the version you want to use, 000 or 020 -^^^\n\n2. Add the tooltype RESIDENT to ALL command icons for AquaScan.\n\n3. Alter the tooltype LOCATION in the command icons so that it says\n   ''LOCATION=AquaScan'' instead of the full path.\n\n\nTo sum up, the command icon tooltypes should look like this if you want to\nuse the resident copy of AquaScan:\n\nACCESS=20\nLOCATION=AquaScan\nRESIDENT\nMULTINODE=YES\nTYPE=XIM\nSTACK=4096\n\n\nNow you should look through the configuration...\n\n\nSysop Configuration\n~~~~~~~~~~~~~~~~~~~\nSome people like icons, some don''t. The sysop configuration can be done\neither in an icon (Doors:AquaScan/AquaScan.info), or in a textfile if you\nprefer that (Doors:AquaScan/AquaScan.config). AquaScan first looks for the\nicon so if you want to use the textfile you have to delete the icon. The\ntextfile should simply contain the tooltypes that would be in the icon\notherwise.\n\nThese are the various tooltypes in AquaScan.info or AquaScan.config:\n\n\nTemplate: DOORUSE.<cmd>=<keyword>\nExample : DOORUSE.N=NEWSCAN\n\nYou must have one tooltype like this for every AquaScan command (F, N, FR,\nCS etc)! It tells the door how the command should behave. The possible\nkeywords are: NEWSCAN, FILESCAN, REVSCAN and CONFSCAN. NEWSCAN means that\nthe command should act like an N command. A FILESCAN command works like F.\nREVSCAN is used for reverse-listing commands (FR for example). CONFSCAN is\nused for commands that can scan all conferences globally (CS, NSU, SCAN\nfor example).\n\n\nTemplate: NOSCAN_CONF.<conf number>\nExample : NOSCAN_CONF.2\n\nWith these tooltypes you can disable certain conferences so that they\nwon''t be scanned by CONFSCAN commands. The conference numbers to use here\nis the same as in your BBS:ConfConfig.info. If you for example have\nNOSCAN_CONF.2 in the config icon, conference 2 from BBS:ConfConfig.info\nwill be skipped by CS. You should disable all conferences that don''t have\na filebase. The scanning will go faster then and it will look better.\n\n\nTemplate: NOSCAN_FROMCONF=<conf number>\nExample : NOSCAN_FROMCONF=14\n\nIf you have LOTS of conferences without a filebase, for example AmiXnet\nconferences, this tooltype could come in handy. If you use it, the\nconference number specified and all following conferences will be disabled\nfor CONFSCAN commands. For example, if you set NOSCAN_FROMCONF=14,\nconference 14, 15, 16, 17 etc will won''t be scanned by CS.\n\n\nTemplate: HOLD_LEVEL=<access level>\nExample : HOLD_LEVEL=200\n\nHere you specify the access level required for a user to scan the HOLD\ndirectories (the private sysop directories).\n\n\nTemplate: CALLERSLOG=(YES|NO)\nExample : CALLERSLOG=YES\n\nIf CALLERSLOG=YES then it will be noted in the CallersLogs when users are\nscanning files with AquaScan. "Directory Scan with AquaScan by Aquarius"\nor "Conference Scan with AquaScan by Aquarius" (for CONFSCAN commands)\nwill be written there.\n\n\nTemplate: WHITE_IS_ZERO=(YES|NO)\nExample : WHITE_IS_ZERO=YES\n\nAmiExpress has the ANSI codes for red and white mixed up. Esc[31m should\nbe red but it is white locally. Esc[37m should be white but it is red\nlocally. But Esc[0m is white BOTH locally and for remote users! If you set\nthe tooltype WHITE_IS_ZERO=YES in the AquaScan config then Esc[0m will be\nused instead of Esc[37m for white.\n\n\nTemplate: LONG_NUKE=(YES|NO)\nExample : LONG_NUKE=NO\n\nIf you are using a nuker/faker that overwrites the filecheck test\ncharacter with its comment, then set LONG_NUKE=YES.\n\nEFXP161.LHA  P 131898  08-28-94  FIX PATCH FOR IMAGE F/X-EGS FROM NOVA -\n                                 FIXES THE STRING BUG PLUS OTHER SHIT!\n             ^\n             `------ This is the filecheck test character.\n\nEFXP161.LHA  OLD&GONE! 08-28-94  FIX PATCH FOR IMAGE F/X-EGS FROM NOVA -\n                                 FIXES THE STRING BUG PLUS OTHER SHIT!\n\nIf your nuker overwrites that character, like above, set LONG_NUKE=YES.\nIf it leaves it (or changes it), like below, set LONG_NUKE=NO.\n\nEFXP161.LHA  D DELETED 08-28-94  FIX PATCH FOR IMAGE F/X-EGS FROM NOVA -\n                                 FIXES THE STRING BUG PLUS OTHER SHIT!\n\n\nTemplate: COLOUR.FILE_NAME=<colour>\nExample : COLOUR.FILE_NAME=CYAN\n\nThis tooltype specifies the default colour for file names.\n\nAvailable colours: WHITE, RED, GREEN, YELLOW, BLUE, VIOLET, CYAN, RANDOM.\n\n\nTemplate: COLOUR.FILE_TEST=<colour>\nExample : COLOUR.FILE_TEST=BLUE\n\nThis tooltype specifies the default colour for filecheck test characters.\n(See LONG_NUKE.)\n\nAvailable colours: WHITE, RED, GREEN, YELLOW, BLUE, VIOLET, CYAN, RANDOM.\n\n\nTemplate: COLOUR.FILE_SIZE=<colour>\nExample : COLOUR.FILE_SIZE=GREEN\n\nThis tooltype specifies the default colour for file sizes. If a file size\nif non-numerical, the nuke colour will be used instead.\n\nAvailable colours: WHITE, RED, GREEN, YELLOW, BLUE, VIOLET, CYAN, RANDOM.\n\n\nTemplate: COLOUR.FILE_DATE=<colour>\nExample : COLOUR.FILE_DATE=YELLOW\n\nThis tooltype specifies the default colour for file dates.\n\nAvailable colours: WHITE, RED, GREEN, YELLOW, BLUE, VIOLET, CYAN, RANDOM.\n\n\nTemplate: COLOUR.FILE_DESC=<colour>\nExample : COLOUR.FILE_DESC=WHITE\n\nThis tooltype specifies the default colour for description bodies.\n\nAvailable colours: WHITE, RED, GREEN, YELLOW, BLUE, VIOLET, CYAN, RANDOM.\n\n\nTemplate: COLOUR.SEPARATOR=<colour>\nExample : COLOUR.SEPARATOR=BLUE\n\nThis tooltype specifies the default colour for file separators.\n\nAvailable colours: WHITE, RED, GREEN, YELLOW, BLUE, VIOLET, CYAN, RANDOM.\n\n\nTemplate: COLOUR.NUKE_SIZE=<colour>\nExample : COLOUR.NUKE_SIZE=WHITE\n\nThis tooltype specifies the default colour for file sizes that are\nnon-numerical (for nuked files).\n\nAvailable colours: WHITE, RED, GREEN, YELLOW, BLUE, VIOLET, CYAN, RANDOM.\n\n\nTemplate: COLOUR.FILE_NUMBER=<colour>\nExample : COLOUR.FILE_NUMBER=WHITE\n\nThis tooltype specifies the default colour for the "File #x" strings.\n\n[ File #9 ]\nAEM103.LHA   P  35483  08-28-94  Amiga Entertainment Monthly - Sept 94\n                                 This is a monthly magazine that replaces\n                                 CD32 View magazine.\n\nAvailable colours: WHITE, RED, GREEN, YELLOW, BLUE, VIOLET, CYAN, RANDOM.\n\n\nTemplate: DATE_LINE=<number>\nExample : DATE_LINE=3\n\nThis tooltype specifies the default date divider.\n\n0 = none, 1-8 are custom date dividers: Doors:AquaScan/AquaScan.Date.x\n\n\nTemplate: SEPARATOR=<number>\nExample : SEPARATOR=4\n\nThis tooltype specifies the default file separator.\n\n0 = none, 1 = empty line, 2-9 are custom separators.\n\nIf SEPARATOR=4, then ''Doors:AquaScan/AquaScan.Div.3'' will be the default\nseparator.\n\n\nTemplate: FILE_NUMBERS=(YES|NO)\nExample : FILE_NUMBERS=YES\n\nThis tooltype specifies whether file numbers should be on or off as\ndefault.\n\n\nTemplate: PPC_CMD.<num>=<command>\nExample : PPC_CMD.1=FAKE\n\nYou can define an unlimited number of commands (doors and internal\nAmiExpress commands) to be started directly from the pause prompt with a\nsingle keystroke. This tooltype defines the command itself. You can\ninclude arguments here if you want, for example ''B 1'' (to view last ten\ncallers maybe).\n\n\nTemplate: PPC_KEY.<num>=<key>\nExample : PPC_KEY.1=X\n\nThis defines the key that will start the command.\n\n\nTemplate: PPC_ACS.<num>=<access level>\nExample : PPC_ACS.1=20\n\nHere you enter the access level required to use the command. The\nACCESS=xxx tooltype in the command icon will not be used unfortunately.\n\nIf a user hasn''t got access to use it then it won''t show up in the help\nwhen he presses H or ? at the pause prompt.\n\n\nTemplate: PPC_DSC.<num>=<description string>\nExample : PPC_DSC.1=Enter the faker\n\nThe string you write here will be shown in the help (when the user presses\nH or ? at the pause prompt) as description for the command.\n\n\nTemplate: PPC_CNF.<num>=(YES|NO)\nExample : PPC_CNF.1=NO\n\nCan the command ONLY be used in your CURRENT conference (while you''re\nusing CS)?\n\nUnfortunately, AmiExpress (at least up to v4.6) has a serious bug: It\nmakes all files in the current conference free download (or not free\ndownload if all files are supposed to be free). This happens when you''re\nusing a custom prompt command in another conference than the current.\n\nSo, until this has been fixed in AmiExpress, set all PPC_CNF.x=YES !\n\nIf the bug HADN''T been there, you should have followed these rules:\n\n "Set this tooltype to YES for:\n\n  * the internal V command.\n\n  * doors using the internal V command to show text files. That won''t work\n    in other conferences than the current. (But maybe you can live with\n    that because archive viewing will work.)\n\n  * doors using the conference NUMBER for something important. (It does\n    not matter if it uses the conference name or location.)\n\n  Set it to NO for every other command."\n\nI stress again: The above only holds when the bug in AmiExpress has been\nfixed!! Until then, set PPC_CNF.x=YES !\n\n\nTemplate: PPC_NUM.<num>=(YES|NO)\nExample : PPC_NUM.1=YES\n\nCan the command take file names as argument? If so, set this to YES and\nyou will be prompted for file numbers when you use the command from the\npause prompt (provided that you have file numbers turned on of course).\n\n\nNote!\n~~~~~\nI have not made any effort to make a download door that checks in which\nconferences the user has flagged files and then jumps between the confs. A\ndoor on the A command and one on G would also have been necessary then. I\nthink that''s too much for a filescanner. AmiExpress itself must be changed\nto allow batch downloads from different conferences. Another reason is,\nthat in AmiExpress 4.x, HYDRA doesn''t seem to work if a door is active\n(the D door).\n\nHowever, a clever way to make it possible to flag files in different\nconferences and then download them all at once is to enter every\nconference''s download paths in every conference icon! Many thanks to Ace\nCaze for hinting this out to me!\n\nIt could for example look like this in DH3:AEUTILS.info:\n\nNDIRS=1\nULPATH.1=DH3:AEUTILS/UPLOAD/\nDLPATH.1=DH3:AEUTILS/UPLOAD/\nDLPATH.2=DH1:PUBLIC_DOMAIN/\nDLPATH.3=BBS:ASCII/UPLOAD/\nDLPATH.4=DH3:REQUESTS/UPLOAD/\nDLPATH.5=DH3:ELITE/UPLOAD\nDLPATH.6=DH3:ELITE/OLDUPLOAD/\n\nAnd in DH3:ELITE.info:\n\nNDIRS=2\nULPATH.1=DH3:ELITE/UPLOAD/\nDLPATH.1=DH3:ELITE/UPLOAD/\nDLPATH.2=DH3:ELITE/OLDUPLOAD/\nDLPATH.3=DH3:AEUTILS/UPLOAD/\nDLPATH.4=DH1:PUBLIC_DOMAIN/\nDLPATH.5=BBS:ASCII/UPLOAD/\nDLPATH.6=DH3:REQUESTS/UPLOAD/\n\nThis requires of course that it doesn''t matter from which conference the\nuser downloads. For example, it''s not very smart to use this method\ntogether with conference accounting. Or if you have everything as free\ndownload in a conference and not the rest, figure out how that would\nwork...\n\n\nContact Me!\n~~~~~~~~~~~\nIf you have any cool ideas for improvement of this door, questions, bug\nreports or whatever, leave me a message on one of the following boards:\n\nNIGHTFALL ................ Whoosh ............ +46-90-120369  <---  Safest\nHALL OF FAME ............. Dansken ........... +46-910-26665      place to\nHYSTERIA ................. JAC ............... +46-21-842939     reach me!\nMASTURBATION STATION ..... Black Beard ....... +1-305-552-1192\nZION''S HIDEOUT ........... Zion .............. +1-614-876-0807\nDARK TOWER ............... Shadower .......... +1-801-476-9068\nMORTUARY ................. Bloodwolf ......... +1-312-284-7577\nBOONDOCKS ................ Sal-One! .......... +31-548-040-653\n\n\nHistory\n~~~~~~~\n1.0  (09-17-94) First release version.\n\n\nGreetings\n~~~~~~~~~\n                Greetings must go to (in no special order):\n\n           - Vegas/OTL - Biscrok/OTL - Toxic/OTL - AtomiX!/OTL -\n       - Whoosh/OTT^KRL^OTL^CLS - Snake/OTL - Nashua/OTL - SMS/OTL -\n    - Genghis Khan/OTL - The Other OTL Members! - Dansken - CornFlake -\n  - Ace Caze/Obscene - Firehawk! - fanta/THR - Static/THR - FAX! - Juan -\n - Psychopath - Danzig - Foss - Karma - Seagull - Marwin - CaT - Sal-One -\n - Metalbasher - No Limit - BoneIdle - Wilsom/Obscene - Stab - Kid Curry -\n - Chig/TDS - HardHack - Rize - Frosty - JAC/TDS - C/\TE¥E - AXL - Norad -\n - Crocodile - Freddy Kreuger/GOD - Doc Whoo - Zion! - Nocturne - Brutus -\n  - FireFlash/OTT - MDR/OTT - Neutralizer/OTT - Bytehunter/OTT - Remix! -\n    - WarDancer - Json/Kingdom - Slobo & Whale - [-HSR & MM-] - HiFly -\n      - Uffe - Gi Joe - Princip - The Silencer - Ezco - Vampire/PDY -\n          - Nero - Deltaforce! - Afterlife - The Ones I Forgot! -\n\n\n[EOF]\n','\n',char(10)),'{"LOCATION":"Doors:AquaScan/AquaScan.000","ACCESS":"20","TYPE":"XIM","STACK":"4096"}','auto-added',66748,2,0,NULL,NULL,'otl_as10','scan',1780048664);
INSERT INTO door_catalog VALUES('otl_aw','OTL-AW.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OTL-AW.LHA','ULCounter','XIM','[-aQUAwHO -]      ____  [-aQUARIUS/oTL-]','2.0',NULL,'OTL','__ _/\______/\___/\_ _\  /_________________. __ ___  ___  ____  /_ \\//                 | /  /  / /  / /  /__  \/ THE ULTIMATE WHO |',replace('[-aQUAwHO v2.0-]      ____  [-aQUARIUS/oTL-]\n__ _/\______/\___/\_ _\  /_________________.\n__ ___  ___  ____  /_ \\//                 |\n  /  /  / /  / /  /__  \/ THE ULTIMATE WHO |\n /  /  / /  / /  /  /    DOOR for /X !!!   |\n_\__  /_/  /_/___  / TOTALLY CONFIGURABLE! |\n____ /___ /__ ___ /(OUTPUT, STRINGS & MORE)|\nbIS\/   \/      \/   Can be made to show:  |\n  name, loc, action, conf, acs level, baud,|\n  multichat avail, calls, UL stats, time!  |\n-- -  -    - -- -   ---- - ---- -----------''\n[THE]=--=]--[WeLsh]=[CoAsT]-[L.S.D]=---[BBS]\n','\n',char(10)),'AquaWho.doc',replace('\n       _ _ ___/\______/\__ ____/\___/\__ _ _/\____ _/\_ __ __/\______\n      __ ________   __   /   _   ___   / ______   \___/__/     _____/\n         bIS/   /   /   /   //   //   /___/ __¬   /  /  /  /\__   \\n           /   /   /   /   //   //   /   /  \    /  /  /  /   /   /\n    __  _ _\____  /\____  //_  //_____  /___/\  /\_____  /\ _/   /___\n     _  ___ _   \/  _  _\/_  \/____ __\/ ___ _\/_______\/____   /_ _/\n                                                            \  /\n                                  present                    \/\n\n                      a door for AmiExpress 2.xx/3.xx:\n\n                  >>> AquaWho v2.0 by Aquarius/Outlaws <<<\n\n\n                          Copyright ©1994 Aquarius\n\n                 Permission is granted to freely distribute\n               this product for non-commercial purposes only,\n                  as long as all files remain unmodified.\n\n\n\nArchive (OTL-AW20.LHA) Contents\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n   Filename:        Size:  Description:\n\nDoors/AquaWho/\n   AquaWho.10.000   27264  Version for 68000+ and older /X than 3.30.\n   AquaWho.10.020   26576  Version for 68020+ and older /X than 3.30.\n   AquaWho.32.000   27284  Version for 68000+ and /X 3.30+.\n   AquaWho.32.020   26596  Version for 68020+ and /X 3.30+.\n   AquaWho.doc      39013  This document file.\n   AquaWho.guide    55365  AmigaGuide version of the doc.\n   CallsCounter      5728  CLI command which keeps track of # calls.\n   ULCounter         7480  Door which keeps track of uploads.\n   LookGenerator    31372  CLI command which generates look files\n   who.info          2339  Standard configuration icon.\n   who.look          1343  A sample look file (defines the output).\n   frontend.info     2199  Config icon for Shapechanger''s frontend design.\n   frontend.look     1845  Look file by Shapechanger. Suits as frontend.\n\nDoors/AquaWho/MiscIcons/\n   intex.info        2159  Cfg icon for /X internal who + conf (LookGen.).\n   nstat.info        1256  Cfg icon for Biscrok''s frontend look (LookGen).\n   vnz.info          2641  Cfg icon for Vinzi''s designs (vnz.look* below).\n   zin!.info         2340  Config icon for Zin!''s design (in LookGen.).\n\nDoors/AquaWho/MiscLooks/\n   block.look.4ndz   1189  Look by Aquarius for 4 nodes (easy to extend).\n   flash.look.3ndz   1038  Look by Aquarius for 3 nodes. Edit phone #''s.\n   nfl.look.3ndz      964  Look by Aquarius for 3 nodes. Edit board name.\n   nfl.look.4ndz     1145  Same style but for 4 nodes.\n   vnz.look.2ndz      680  Look file by Vinzi! Really nice as frontend!\n   vnz.look.3ndz      800  Same but for 3 nodes.\n   vnz.look.4ndz      920  4-nd v. Use MiscIcons/vnz.info as config icon.\n\nCommands/BBSCmd/\n   who.info          1282  Command icon for AmiExpress 3.xx.\n   wh.info           1282  Command icon for AmiExpress 3.xx.\n\nCommands/SYSCmd/\n   filecheck.info    1043  Use this to install ULCounter.\n   frontend.info     1268  Use this to have AquaWho as frontend.\n\nPreviews/\n   bis.iff           9808  Picture of Biscrok''s design (LookGenerator).\n   col.iff           5824  A nice design by Aquarius (LookGen.).\n   fire.iff          7564  A hot (hehe) look by Aquarius (LookGen).\n   full.iff          7214  Another nice design by Aquarius (LookGen.).\n   sc1.iff           9334  Shapechanger''s frontend style (LookGen).\n   vnz.iff           4916  Vinzi''s funky design (in dir MiscLooks).\n   zin!.iff          7630  Zin!''s design (in LookGenerator).\n\n\nIntroduction\n~~~~~~~~~~~~\nAquaWho is an AmiExpress door for multinode boards. Briefly you could say\nthat it gives the user information about what''s happening on the other\nnodes. There are lots of who doors out there, but this is simply the most\npowerful ever made! Just look at all the features...\n\n\nFeatures\n~~~~~~~~\nIts output (design, look) is totally configurable!\n\nSeveral design examples are included, some by well-known ascii artists. I\nam sure that you will find one that you like! If not, just make your own\ndesign! You can have different designs on different commands (who, wh,\nnode, frontend etc), so you don''t need a separate frontend who door.\n\nAll strings (action strings for example) can be reconfigured!\n\nIt is able to display: name/handle, location, action, current conference,\naccess level, multichat/OLM availability (for /X 3.37+), number of calls\ntoday (for every node or for all nodes together), number of uploaded files\nand bytes today, and current time and date! It can even make pauses of any\nlength, which can be used to accomplish nice animation effects.\n\nQuiet nodes are supported. The default action string for a quiet node is\n"Secret action" but that can easily be reconfigured to whatever you like,\n"Node inactive" for example to give the impression that no-one is there.\n\nIf a user has a certain access level (configurable of course), he can see\nwho is on a quiet node. The user name will then have a "(Q)" appended.\n\nOf course, it can show file names, but it can also be configured not to\nshow them when the UL/DL takes place in a conference which the user\ndoesn''t have access to. An access value required to see filenames can be\nset as well.\n\nThe door command being used on another node can be shown! You can\nconfigure the access level required to see the command. Conference access\nchecking is also available, meaning that the door command will only be\nshown if it is clear that the AquaWho user has access to the conference in\nwhich that door is being used. This is probably not a very needed feature\n(the conf checking), but it''s there if you want it!\n\nThe access level required to see the conference numbers can be configured.\nAlso, the conference number can be hidden if the AquaWho user doesn''t have\naccess to that conference.\n\nIf a new user is logging into the BBS for the first time, AquaWho displays\n"A new user!" (configurable of course) as user name when he is typing in\nanswers to all the new-user questions. When he is done his name/handle is\ndisplayed, with the note "(NEW)" added. If he gets validated when he is\nonline, the "(NEW)" thing will disappear.\n\nIf a node is reserved for a user, that user''s name is displayed in\nuppercase letters between parentheses. You can make it show a certain\nstring instead if you want to (''Reserved'' for example).\n\nAquaWho is written in highly optimized C code for best performance!\n\n\nRequirements\n~~~~~~~~~~~~\nAn Amiga with OS 2.0 or higher.\nAmiExpress/SigmaExpress.\n(The door works for sure on /X v2.20-3.38 and possibly on other versions\ntoo.)\n\n\nInstallation\n~~~~~~~~~~~~\nYou should read the entire installation text completely, since it contains\nlots of important information.\n\n\nFirst create the directory ''Doors:AquaWho'', and copy the correct version\nof the door there.\n\nAquaWho.10.000 is for S-Express & earlier /X than 3.30, and 68000/010.\nAquaWho.10.020 is for S-Express & earlier /X than 3.30 and 68020/030/040.\nAquaWho.32.000 is for /X 3.30 or higher, and 68000/010.\nAquaWho.32.020 is for /X 3.30 or higher, and 68020/030/040.\n\nIt could also be a good idea to copy the documentation to that directory,\nbecause you will probably need it in the future.\n\nNow you must decide what commands you want to have AquaWho on, probably\n''who'', ''wh'' and perhaps ''frontend'' and some more.\n\n\nFor every command, you need to fix THREE things.....\n\n\n1. The normal XIM door installation...\n\n   /X 3.xx:\n\n   Copy Commands/BBSCmd/who.info from the archive to your BBSCmd directory\n   as <command>.info (who.info, wh.info etc) and check that its tooltypes\n   LOCATION and ACCESS are correct.\n\n   If you will install it as frontend, copy the same icon to Frontend.info\n   in your SYSCmd directory.\n\n\n   /X 2.xx, SigmaExpress:\n\n   Add a line to your BBS.CMD, for example:\n\n   -----Cut-here-------------------------------\n   *WHO      XM020Doors:AquaWho/AquaWho.10.020\n   --------Cut-here----------------------------\n                  ^--- File name of the door with full path.\n               ^^^\n    ^          Access required to use the door.\n    |\n    ` The command that will invoke AquaWho.\n\n   For frontend installation, add this to your SYS.CMD file:\n   -----Cut-here-------------------------------\n   FRONTEND  XM020Doors:AquaWho/AquaWho.10.020\n   --------Cut-here----------------------------\n\n\n2. You must have a look file, ''Doors:AquaWho/<command>.look''. It tells the\n   door what to display. For a quick installation, I recommend that you\n   use the LookGenerator utility to create the look file. Just open a\n   shell window and start it, and you''ll see how to use it. It contains\n   many nice designs.\n\n\n3. You must also have a configuration icon for every command:\n   ''Doors:AquaWho/<command>.info''. Use the supplied icon\n   ''Doors/AquaWho/who.info'' and check that its tooltypes are correct.\n   Especially all access values (ACS.*) should be thoroughly checked!!\n   That they are alright for ONE look file doesn''t mean they''re good for\n   another. If they are set wrong, too little or too much info could be\n   shown (security!), or the door could be slower than what is possible\n   (see ACS.SEE_CONFS e.g.). All tooltypes are described in detail in a\n   section below.\n\n\nThe CallersLog must be turned on if you are going to use a who design that\nshows the current conference.\n\nIf you are using relative conferences, the conference numbers AquaWho\nshows might not be the same for all users on your board. But if they all\nhave access to the x first conferences, there''s no problem. For example,\nit''s not good if you''re using relative conferences and some users'' access\nlooks like this: XX_X__X__ or X_XXX____. Better: XXX______ and XXXX_____,\nas examples. (AmiExpress 3.xx doesn''t have these conference access\nstrings, but you get the point anyway.) So if you have the "bad" case,\neither turn off relative conferences, or don''t use a look file with\nconference codes.\n\nThe DoorLog must be turned on if you have /X 3.xx and you don''t have the\ntooltype DISABLE_EXTRA in the config icon. The DoorLog is then used to\ndetermine if the logoff module is running.\nYou also need to have it turned on if you want the door commands being\nused on other nodes to be shown (if ACS.SEE_DOORS is 255 or lower).\n\nTo turn on the DoorLog with /X 2.xx, put ''NODE* DOORLOG'' in ACP.STARTUP.\nFor /X 3.xx, put the tooltype ''DOOR_LOG'' in the node icons.\n\nThe DoorLog grows very large quickly I''m afraid... The best solution to\nthis is to use my utility "Stripper" (released separately) about once a\nday. It rips off the beginning of the file, to a size of your choice. 1000\nbytes is appropriate I guess. Use it like this: "Strip BBS:Node(x)/DoorLog\n1000".\n\nIf you are going to use a who design that shows number of calls, you must\ninstall the CallsCounter utility. Run it in your logoff scripts with the\nnode number as its only argument. For example, in the logoff script for\nnode 3, add "Doors:AquaWho/CallsCounter 3".\n\nTo use a look file with uploaded files or bytes today, ULCounter must be\ninstalled as the FILECHECK door. It''s possible that you already have\nanother tool installed there. If it is Sigma Seven''s DupeChecker, you can\ninstall ULCounter as the SERVER command (in SYSCmd) instead. But if your\nFILECHECK door doesn''t offer such a possibility, you can use\n''5D-MultiStart'' (by Sven the Creator/5D). Then you can have as many\nFILECHECKers as you want!\n\n\nConfiguration\n~~~~~~~~~~~~~\n\nThe Tooltypes\n=============\n\nA tip: For you who didn''t know this, ANSI codes can be used in tooltypes.\nTo write the escape character, press lamiga+ctrl+esc...\n\nHere follows descriptions of all tooltypes possible to have in a\nconfiguration icon (''Doors:AquaWho/<command>.info''):\n\n\nRESET_LINES                         optional\n\nIf this tooltype is present in the config icon, the number of lines viewed\nis first set to zero, to prevent the pause prompt from appearing too soon.\nThis can be useful when the door is used as frontend or is started with\nMCI, but it makes no difference when the door is started from the main\nprompt.\n\n\nNONSTOP                             optional\n\nIf you never want any pause prompt in the who door, use this tooltype. It\nturns on non-stop scrolling when the door starts and turns it off when it\nquits.\n\n\nFRONTEND                            optional\n\nIf you want to run the door before the logon prompt (handle/password), for\nexample by using MCI in Private.txt or BBSTitle.txt, or as FRONTEND door,\nthen put this tooltype in the config icon. Actually, it is not needed for\ntrue FRONTEND usage - the door can detect that. The effect is, among other\nthings, that the door user''s access level is considered to be 0.\n\n\nGET_BAUD                            optional\n\nIf the look file has baud codes in it, this tooltype must be in the icon.\nThe door will complain if it finds a baud code but not this tooltype. If\nyou don''t want connect baud to be shown, you should not have this\ntooltype, because it would make the who door a bit slower (perhaps not\nnoticably but still).\n\n\nDISABLE_EXTRA                       optional\n\nIf this is present in the icon, AquaWho will act more like every other who\ndoor in the sense that it will not show "(NEW)" for new users and not read\nthe DoorLog to check if the logoff module is running (/X 3.xx).\n\n\nDOORCMD_UPCASE                      optional\n\nIf this tooltype is present, door commands are shown in uppercase letters,\notherwise in lowercase.\n\n\nDOORCMD_INITIAL                     optional\n\nIf this tooltype is present, the first letter in the door command is\nwritten in lowercase if the other letters are to be written in uppercase\n(determined by the tooltype DOORCMD_UPCASE), and in uppercase if the other\nletters are to be written in lowercase.\n\nExample (''dis'' command):\n\nDOORCMD_UPCASE  DOORCMD_INITIAL  : dIS\n-               DOORCMD_INITIAL  : Dis\nDOORCMD_UPCASE  -                : DIS\n-               -                : dis\n\n\nACS.SEE_FILES=<access level>        required\n\nThis is the minimum access level required to see the names of the files\nbeing uploaded or downloaded.\n\n\nACS.SEE_CONFS=<access level>        required\n\nThis is the minimum access level required to see conference numbers. If\nthe look file doesn''t contain any conference codes, set this higher than\n255. That will possibly make the door faster beacause it won''t read the\nCallersLogs then (unless it needs to check conference access, see\nACS.NO_CONF_ACS_CHECK.FILES and company).\n\n\nACS.SEE_ACCESS=<access level>       required\n\nThis is the minimum access level required to see other users'' access\nlevel. If there are no access codes in the look file, set this higher than\n255. That will make the door a bit faster.\n\n\nACS.SEE_QUIET_NODES=<access level>  required\n\nThis is the minimum access level required to get all information about a\nnode which is quiet. A "(Q)" will be appended to the handles on quiet\nnodes.\n\n\nACS.SEE_NEW=<access level>         required (unless DISABLE_EXTRA is used)\n\nThis is the minimum access level required to see if a user is new (not\nvalidated and calling for the first time). "(NEW)" is appended to those\nusers'' names.\n\n\nACS.SEE_DOORS=<access level>        required\n\nThis is the minimum access level required to see what door commands are\nbeing used on the other nodes.\n\n\nACS.NO_CONF_ACS_CHECK.FILES=<access level>  req. (if ACS.SEE_FILES <= 255)\n\nThis is the minimum access level required to avoid conference access\nchecking that could hide filenames. If a user has a lower access, he can\nONLY see the filenames IF it is clear that he has access to the conference\nwhere the upload/download takes place.\n\n\nACS.NO_CONF_ACS_CHECK.CONFS=<access level>  req. (if ACS.SEE_CONFS <= 255)\n\nThis is the minimum access level required to avoid conference access\nchecking that could hide conference numbers. If a user has a lower access,\nhe can ONLY see the conference number of another user IF it is clear that\nhe has access to that conference.\n\n\nACS.NO_CONF_ACS_CHECK.DOORS=<access level>  required\n\nThis is the minimum access level required to avoid conference access\nchecking that could hide door commands. If a user has a lower access, he\ncan ONLY see the door command being used by another user IF it is clear\nthat he has access to that conference.\n\n\nMETACHAR=<character>                optional, default: ''°''\n\nThis is the character that is the beginning of the special codes in look\nfiles. See the section that describes the look files in detail.\n\n\nNOCONFCHAR=<character>              optional, default: ''-''\n\nWhen there is no user on a node or he hasn''t joined a conference yet, or\nthe conference number couldn''t be determined for some reason, this\ncharacter is shown instead of the conference number.\n\nIf padding with zeros is turned on, the space reserved will be filled with\nthis character.\n\n\nSECRETCONFCHAR=<character>          optional, default: ''x''\n\nIf a node is quiet or the door user hasn''t got access to see conference\nnumbers, this character will be shown instead.\n\n\nNOACCESSCHAR=<character>            optional, default: ''-''\n\nIf the access level can''t be determined, for example when there is no user\non the node, this character is shown instead.\n\n\nSECRETACCESSCHAR=<character>        optional, default: ''x''\n\nIf the node is quiet or the door user hasn''t the access set by\nACS.SEE_ACCESS, this character is shown instead of the access level.\n\n\nNOBAUDCHAR=<character>              optional, default: '' ''\n\nWhenever the connect bps can''t be determined, for example when there is no\nuser on the node, this character is shown instead.\n\n\nSECRETBAUDCHAR=<character>          optional, default: ''x''\n\nIf a node is quiet, this character will be shown instead of the connect\nbps.\n\n\nADD_TO_BAUD=<string>                optional, default: ''''\n\nThis tooltype lets you specify a string which will be appended to the\nconnect bps when that can be determined, or the node is quiet (and\nSECRETBAUDCHAR isn''t a space). For example, if you enter '' bps'' here, this\ncould be shown:\n\n14000 bps   Joining a conf   ('' bps'' was added)\n            Awaiting connect (could not determine baud -> no '' bps'')\n    x bps   Secret action    (quiet node, '' bps'' was added)\n\n\nCHAT_NO=<string>                    optional, default: ''NO ''\n\nThis string is inserted as multichat/OLM availability when the user is NOT\navailable. Its length should be the same as CHAT_YES.\n\n\nCHAT_YES=<string>                   optional, default: ''YES''\n\nThis string is inserted as multichat/OLM availability when the user IS\navailable. Its length should be the same as CHAT_NO.\n\n\nNOTACTIVENAME=<string>              optional, default: ''Nobody''\n\nThis is the string that is shown as user name when the node is resetting\nitself (when the action is NOTACTIVE).\n\n\nAWAITCONNECTNAME=<string>           optional, default: ''Nobody''\n\nThis is the string that is shown as user name when the node is ready to\nreceive a call (when the action is AWAITCONNECT).\n\n\nSHUTDOWNNAME=<string>               optional, default: ''Nobody''\n\nThis is the string that is shown as user name when the node is shutdown,\nnot active (when the action is SHUTDOWN).\n\n\nSUSPENDNAME=<string>                optional, default: ''Nobody''\n\nThis is the string that is shown as user name when the node is suspended\n(when the action is SUSPEND).\n\n\nRESERVENAME=<string>                optional\n\nIf you don''t want the name of the user whom the node is reserved for to be\nshown (like this: "( USERNAME )"), then use this tooltype to determine\nwhat should be shown instead (''Reserved'' for example).\n\n\nNOWHERE=<string>                    optional, default: ''Nowhere''\n\nThis is the string that is shown as location when nobody is on the node.\n\n\nSOMEBODY=<string>                   optional, default: ''Somebody''\n\nThis string is shown as user name when somebody is connecting to the BBS\n(when the action is CONNECT), and at all other occasions when somebody is\nonline but the name cannot be determined.\n\n\nSOMEWHERE=<string>                  optional, default: ''Somewhere''\n\nThis string is shown as location when:\n - a new user is logging on (action ACCOUNTSEQ).\n - a user is connecting to the BBS (action CONNECT).\n - the node is reserved for a user (action RESERVE).\n - somebody is online but the name cannot be determined.\n\n\nSECRETNAME=<string>                 optional, default: ''Somebody''\n\nThis string is shown as user name when a node is quiet (and the AquaWho\nuser hasn''t got the access defined by ACS.SEE_QUIET_NODES). The action\nstring will then be what is defined by the tooltype SECRET.\n\n\nSECRETLOC=<string>                  optional, default: ''Somewhere''\n\nThis string is shown as location when a node is quiet (and the AquaWho\nuser hasn''t got the access defined by ACS.SEE_QUIET_NODES). The action\nstring will then be what is defined by the tooltype SECRET.\n\n\nNEWUSER=<string>                    optional, default: ''A new user!''\n\nThis is the string that is shown as user name when a new user is logging\non, answering new-user questions. The action is then ACCOUNTSEQ.\n\n\nUSERNAME=<string>                   optional\n\nIf you don''t want ANY of the users'' names to be shown, then use this\ntooltype to set the replacement string. (The AquaWho user''s name is not\naffected by this, see YOURNAME.) This is primarily intended for frontend\nusage, where you can write ''USERNAME=**BUSY**'' for example.\n\n\nYOURNAME=<string>                   optional, default for frontend: ''You!''\n\nIf you don''t want the AquaWho user''s name to be shown, then use this\ntooltype to set the replacement string. When AquaWho is used as frontend\ndoor, this tooltype defines the user''s name.\n\n\nYOURNAMEQ=<string>                  optional, default: ''You! (Quiet)''\n\nThis string is shown as name for the AquaWho user when the node is quiet\nand one of the following criteria holds:\n - it is a frontend command\n - YOURNAME is present in the config icon\n - the user doesn''t have the access set by ACS.SEE_QUIET_NODES\n\n\nYOUFRONTLOC=<string>                optional, default: ''''\n\nThis is the location string for the AquaWho user when the door is used as\nfrontend.\n\n\nTooltypes describing actions:\n-----------------------------\n\nIDLE=<string>                       optional, default: ''Doing nothing''\n\nThis is the string shown when the user is at the main prompt, perhaps\ntyping a command.\n\n\nDOWNLOADING=<string>                optional, default: ''Downloading''\n\nThe user is downloading but the filename is not shown. Possible reasons:\n 1. The door user''s access level is lower than what is specified in\n    ACS.SEE_FILES.\n 2. ACS.NO_CONF_ACS_CHECK.FILES is set higher than the AquaWho user''s\n    access level (therefore conf access checking is done), and he doesn''t\n    have access to the conference in which the download takes place.\n 3. He is typing file names to download and has not yet begun the\n    transfer.\n 4. He chose ''goodbye after transfer'' and is logging off.\n 5. The AquaWho user doesn''t have the access defined by\n    ACS.NO_CONF_ACS_CHECK.FILES and you are using relative conferences.\n    Then you must either remove conference access checking by setting\n    ACS.NO_CONF_ACS_CHECK.FILES to 0 (also ACS.NO_CONF_ACS_CHECK.CONFS and\n    ACS.NO_CONF_ACS_CHECK.DOORS) or stop using relative conferences,\n    because the conference access checking doesn''t work with relative\n    conferences (unless the conference numbers for all users are the same\n    with, as without relative conferences)!\n\n\nDLFILE=<string>                     optional, default: ''DL: ''\n\nThis string is shown as action with the filename appended, when a user is\ndownloading. Note that no space is automatically inserted between this\nstring and the filename (for more configuration freedom).\n\n\nUPLOADING=<string>                  optional, default: ''Uploading''\n\nThe user is uploading, but the filename is not shown. Possible reasons:\n 1. The door user''s access level is lower than what is specified in\n    ACS.SEE_FILES.\n 2. ACS.NO_CONF_ACS_CHECK.FILES is set higher than the AquaWho user''s\n    access level (therefore conf access checking is done), and he doesn''t\n    have access to the conference in which the upload takes place.\n 3. The actual transfer has not yet begun.\n 4. He chose ''goodbye after transfer'' and is logging off.\n 5. The AquaWho user doesn''t have the access defined by\n    ACS.NO_CONF_ACS_CHECK.FILES and you are using relative conferences.\n    Then you must either remove conference access checking by setting\n    ACS.NO_CONF_ACS_CHECK.FILES to 0 (also ACS.NO_CONF_ACS_CHECK.CONFS and\n    ACS.NO_CONF_ACS_CHECK.DOORS) or stop using relative conferences,\n    because the conference access checking doesn''t work with relative\n    conferences (unless the conference numbers for all users are the same\n    with, as without relative conferences)!\n\n\nULFILE=<string>                     optional, default: ''UL: ''\n\nThis string is shown as action with the filename appended, when a user is\ndownloading. Note that no space is automatically inserted between this\nstring and the filename (for more configuration freedom).\n\n\nDOORS=<string>                      optional, default: ''Using a door''\n\nThe user is using a door, an external module, but the door command is not\nshown. Possible reasons:\n 1. The door user''s access level is lower than what is specified in\n    ACS.SEE_DOORS.\n 2. ACS.NO_CONF_ACS_CHECK.DOORS is set higher than the AquaWho user''s\n    access level (therefore conf access checking is done), and he doesn''t\n    have access to the conference in which the door is being used.\n 3. The last line in the DoorLog didn''t contain a door command.\n 4. There was an error reading the DoorLog. Make sure that the tooltype\n    DOOR_LOG is present in the BBS:Node(x).info icons (for /X 3.xx).\n 5. The AquaWho user doesn''t have the access defined by\n    ACS.NO_CONF_ACS_CHECK.DOORS and you are using relative conferences.\n    Then you must either remove conference access checking by setting\n    ACS.NO_CONF_ACS_CHECK.DOORS to 0 (also ACS.NO_CONF_ACS_CHECK.FILES\n    and ACS.NO_CONF_ACS_CHECK.CONFS) or stop using relative conferences,\n    because the conference access checking doesn''t work with relative\n    conferences (unless the conference numbers for all users are the same\n    with, as without relative conferences)!\n\n\nDOORCMD=<string>                    optional, default: ''Using door: ''\n\nThis string is shown as action with the door command appended when a user\nis using a door. If the door command isn''t shown, see the tooltype DOORS\nfor reasons. Note that no space is automatically inserted between this\nstring and the door command (for more configuration freedom).\n\n\nMAIL=<string>                       optional, default: ''R/W mail''\n\nThis is the action string shown when the user is reading or writing mail\n(not at logon, which is SCANNING).\n\n\nSTATS=<string>                      optional, default: ''Checking status''\n\nThis is the action string shown when the user is using the ''w'' or ''s''\nstandard AmiExpress command.\n\n\nACCOUNT=<string>                    optional, default: ''Account editing''\n\nThis is the action string shown when the user is editing accounts, or at\nleast it should be but I don''t think that AmiExpress uses it at all. When\nthe account editor is used (command ''1'') the action is SYSOP.\n\n\nZOOM=<string>                       optional, default: ''Zooming mail''\n\nThis is the action string shown when the user is zooming mail (collecting\nfor download).\n\n\nFILES=<string>                      optional, default: ''Scanning files''\n\nThis is the action string shown when the user is viewing a filelist.\nInternal /X commands resulting in this action: ''f'', ''n'', ''z'' and ''a''.\n\n\nBULLETINS=<string>                  optional, default: ''Reading bulletins''\n\nThis is the action string shown when the user is reading bulletins (the\n''b'' command).\n\n\nVIEWING=<string>                    optional, default: ''Viewing text file''\n\nThis is the action string shown when the user is viewing a file, with the\n''v'' or ''vs'' command.\n\n\nACCOUNTSEQ=<string>                 optional, default: ''Logging on''\n\nThis is the action string shown when the user is logging on the BBS for\nthe first time (answering new-user questions etc).\n\n\nLOGOFF=<string>                     optional, default: ''Logging off''\n\nThis is the action string shown when the user is logging off.\n\n\nSYSOP=<string>                      optional, default: ''Sysop activities''\n\nThis string is shown as action when the user is using a sysop command such\nas ''1'', ''2'' and ''5''.\n\n\nSHELL=<string>                      optional, default: ''Using Shell''\n\nThis is the action string shown when the user is in the Shell.\n\n\nEMACS=<string>                      optional, default: ''Using EMACS''\n\nThis is the action string shown when the user is editing using EMACS.\nAmiExpress commands: ''3'' and ''4''.\n\n\nJOIN=<string>                       optional, default: ''Joining a conf''\n\nThis is the action string shown when the user is joining a conference.\n\n\nCHAT=<string>                       optional, default: ''Chatting''\n\nThis is the action string shown when the user is chatting with the sysop.\n\n\nNOTACTIVE=<string>                  optional, default: ''Awaiting connect''\n\nThis is the action string shown when someone just logged off and the node\nis being resetted.\n\n\nREQ_CHAT=<string>                   optional, default: ''Paging Sysop''\n\nThis is the action string shown when the user is paging the sysop\n(requesting chat).\n\n\nCONNECT=<string>                    optional, default: ''Connecting to BBS''\n\nThis is the action string shown when someone is connecting to the BBS.\n\n\nLOGGINGON=<string>                  optional, default: ''Logging on''\n\nThis is the action string shown when the user is logging on the BBS.\n\n\nAWAITCONNECT=<string>               optional, default: ''Awaiting connect''\n\nThis is the action string shown when the node is free for call.\n\n\nSCANNING=<string>                   optional, default: ''Scanning for mail''\n\nThis is the action string shown when the user just logged on and is\nscanning for mail.\n\n\nSHUTDOWN=<string>                   optional, default: ''Node inactive''\n\nThis is the action string shown when the node is not active.\n\n\nSHUTDOWN.<node>=<string>            optional\n\nWith this tooltype you can define a string that will be shown only for the\nspecified node when it is shutdown. The intended use was to have "Sysop\ncalling out!" or something similar for the nodes that can be used for\nthat. For example, if you always use node 3 for calling out, write\n"SHUTDOWN.3=Sysop calling out!". It can be used for any info on why that\nnode is down.\n\n\nMULTICHAT=<string>                  optional, default: ''MultiNd chatting''\n\nThis is the action string shown when the user is using a multi-node chat\ndoor.\n\n\nSUSPEND=<string>                    optional, default: ''Node suspended''\n\nThis is the action string shown when the node is suspended.\n\n\nRESERVE=<string>                    optional, default: ''Node reserved''\n\nThis is the action string shown when the node is reserved.\n\n\nOLM=<string>                        optional, default: ''Writing OLM''\n\nThis is the action string shown when the user is writing an online\nmessage. This far, it''s probably only the internal OLM command in /X\n3.37+ that can cause this action.\n\n\nNUKE=<string>                       optional, default: ''Nuking files''\n\nThis is the action string shown when the user is using a faker/nuker door.\nNot all nukers support this, so for some the action could be "Using door:\nnuke", "Using door: fake", or just "Using a door" (if ACS.SEE_DOORS is too\nhigh). Information for door coders: The environment code for this is 99.\n\n\nSECRET=<string>                     optional, default: ''Secret action''\n\nThis is the action string shown when the node is quiet and the AquaWho\nuser hasn''t got the access defined by ACS.SEE_QUIET_NODES.\n\n\nAQUAWHO=<string>                    optional, default: ''Using AquaWho!''\n\nThis is the action always shown for the AquaWho user (unless the node is\nquiet and he hasn''t got the access defined by ACS.SEE_QUIET_NODES).\n\n\nUNKNOWN=<string>                    optional, default: ''Unknown action!''\n\nThis is the action string shown when the action couldn''t be determined\n(AmiExpress'' environment value was unknown).\n\n\n\nThe Look File\n=============\n\nA look file is an ordinary ascii/ansi text file, but with special code\nsequences which AquaWho replaces with the item that they stand for.\n\nEvery item specification starts with the metachar, which is defined in the\nconfiguration icon, tooltype METACHAR. The default is ° (alt-w). If that\ncharacter is used in the look file for other purposes ("decoration"),\nchange the metachar to another, unique, character.\n\n\n    °D   Door name ("AquaWho").\n\n    °V   Door version, for example "2.0".\n\n    °P   Programmer ("Aquarius/OTL").\n\n    °T   Current time (HH:MM:SS).\n\n    °E   Current date (MM-DD-YY).\n\n    °F   Full time and date string (DDD MMM dd hh:mm:ss YYYY),\n         for example "Wed Sep 04 15:13:22 1985".\n    ^\n    |\n    `-- Metachar\n\n\n    °W24    Wait for 24/50 (=0.48) seconds. This can be used to accomplish\n      ^^    nice animation effects.\n      ||\n      ``\n       There must always be TWO digits. Write °W08 to wait for 8/50 s.\n       If you need a longer delay than 99/50 s, use multiple wait codes.\n\n\n    °0N18L           The door will replace this with the name of the\n     ^^^ ^           user on node 0. 18 spaces will be reserved for it\n     ||| |           and it will be left justified.\n     ||| |\n     ||| |\n     ||| `-- Justification info: L - left justified\n     |||                         R - right justified\n     |||                         C - centered\n     |||\n     ||`-- Field width (the number of spaces to be reserved).\n     ||    For conf, baud, access, calls, uploads and uploaded bytes: If\n     ||    the field width starts with a zero, then zeros will be used for\n     ||    padding instead of spaces in front of the number, and if the\n     ||    field width is too small for the number to fit then it will be\n     ||    extended to whatever is needed. Look below to see what the\n     ||    field width limits are.\n     ||\n     |`-- Type of data: N - name\n     |                  L - location\n     |                  A - action\n     |                  C - conference\n     |                  B - connect bps\n     |                  X - access level\n     |                  S - calls (requires the CallsCounter util to be\n     |                             run in the logoff scripts)\n     |                  U - uploads (requires the ULCounter door to be run\n     |                               for every uploaded file, for example\n     |                               as FILECHECK)\n     |                  Y - uploaded bytes (requires the ULCounter door to\n     |                           be installed as FILECHECK, nothing else!)\n     |\n     |\n     `-- Node number (0-9 for the 10-node v., 0-31 for the 32-node v.)\n         NOTE! For calls, uploads and uploaded bytes you can leave this\n         out! Then the TOTAL count (the sum from all nodes) will be\n         inserted.\n\n\n    °0H  MultiChat/OLM availability. See CHAT_YES and CHAT_NO.\n     ^\n     |\n     `-- Node number\n\n\n Here follows the field width limits:\n\n  9 <= Name       <= 38\n  1 <= Location   <= 30\n  1 <= Action     <= 50\n  1 <= Conf       <=  8\n  1 <= Baud       <= 30\n  1 <= Access     <=  4\n  1 <= ChatAvail  <= 40\n  1 <= Calls      <=  8\n  1 <= UL''d Files <=  8\n  1 <= UL''d Bytes <= 12\n\n\n\nSome examples:\n\n Code     Explanation                                     Sample results\n ¯¯¯¯¯¯¯¯ ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯ ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n "°2S3R"  # calls today on node 2.                     "  8", " 13", "102"\n "°2S03R" Same but padded with zeros.                  "008", "013", "102"\n "°S3L"   # calls today on all nodes together.         "9  ", "35 ", "102"\n\n\n\nError Messages\n~~~~~~~~~~~~~~\nThese are all the error messages that AquaWho can give you. An explanation\nof them is given, why they appear and what you can do about it.\n\n\nCouldn''t find multicom port! Check ACP.info!\n\n   The tooltype MULTICOM_PORT must be in your ACP icon. (/X 3.xx)\n\n\nCouldn''t open icon.library!\n\n   This will probably never occur...\n\n\nOut of memory!\n\n   You are really low on memory if this comes up. AquaWho doesn''t consume\n   much.\n\n\nCouldn''t load config icon!!\n\n   Doors:AquaWho/<command>.info couldn''t be opened.\n\n\nError in config icon! Access value missing or invalid!\n\n   Check the tooltypes ACS.SEE_FILES, ACS.SEE_CONFS,\n   ACS.SEE_QUIET_NODES, ACS.SEE_NEW, ACS.SEE_DOORS, ACS.SEE_ACCESS,\n   ACS.NO_CONF_ACS_CHECK.FILES, ACS.NO_CONF_ACS_CHECK.CONFS and\n   ACS.NO_CONF_ACS_CHECK.DOORS.\n\n\nError in look file, line <nr> column <nr>!\n\n   This tells you where the first error in Doors:AquaWho/<command>.look\n   was encountered. Load the look file into an ordinary text editor and\n   locate the error.\n\n\nCouldn''t open look file!\n\n   Doors:AquaWho/<command>.look couldn''t be opened.\n\n\nError reading look file!\n\n   An error occurred when AquaWho was reading\n   Doors:AquaWho/<command>.look. The file could be opened but there was a\n   read error.\n\n\nError in config icon, tooltype <tooltype>!\n\n   The tooltype is one of METACHAR, NOCONFCHAR, SECRETCONFCHAR,\n   NOACCESSCHAR, SECRETACCESSCHAR, NOBAUDCHAR and SECRETBAUDCHAR.\n   Check that there is exactly one character there. Note that the error\n   can NOT mean that the tooltype doesn''t exist. There are default\n   characters for all of them.\n\n\nError! Connect bps can''t be shown unless the GET_BAUD tooltype\nis present in the config icon!\n\n   What this means should be obvious. Put GET_BAUD in the config icon.\n\n\nContact Me!\n~~~~~~~~~~~\nI want new nice look files (and their config icons if they are special)!\nGive them to me and I might include them in the next release of AquaWho or\nin a separate design collection. Of course I won''t mind if you release\nyour own collection...\n\nAlso if you have any cool ideas for improvement of this tool, bug reports,\nquestions, or whatever, leave me a message on one of the following boards:\n\nNIGHTFALL ................ Prof Do Right ..... +46-90-120369\nOVERLOAD (OTL SHQ) ....... Vegas ............. +46-8-54063666\nHYSTERIA ................. JAC ............... +46-21-842939\nRAISING HELL ............. Psychopath ........ +46-23-26893\nINSIDE OUT ............... C/\TE¥E ........... +46-346-58697\nSNAKE''S DEN (OTL WHQ) .... Snake ............. +1-513-683-2330\nTHE HOLE ................. Oldman ............ +1-419-899-2754\n\n\nHistory\n~~~~~~~\nHistory restarted! There are so many news from v1.2 (the previous release)\nthat I don''t have the time to explain them all.\n\n2.0  (1994-04-24) Release version.\n\n\nGreetings\n~~~~~~~~~\n               Greetings must go to (in no special order):\n\n      - All Members of Outlaws!! - Prof Do Right/Classic - JAC/TDS -\n    - C/\TE¥E/Insane - Ace Caze/Obscene - Wilsom/Obscene - Kid Curry -\n   - Psychopath - Vinzi - Karma - Zin - Shapechanger - Rize - Seagull -\n    - Remix/Classic - RaJ-Ban - fanta/Therion - Static/Therion - CaT -\n     - Dansken - AXL/Attention - Rad!/LSD - Vileius! - Marwin/Duplo -\n      - Freddy Kreuger/GOD - Chig/TDS - The Silencer - Vampire/PDY -\n       - Crocodile/Obscene - Sal-One - Nojje - Zune/HCD - MadCap -\n           - Metalbasher - WarDancer/H&V - The Ones I Forgot! -\n\n\n[EOF]','\n',char(10)),'{"ACCESS":"<access"}',NULL,105249,1,0,NULL,NULL,NULL,'scan',1780048664);
INSERT INTO door_catalog VALUES('otl_aw20','OTL-AW20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OTL-AW20.LHA','CallsCounter','XIM','[-aQUAwHO -]      ____  [-aQUARIUS/oTL-]','2.0',NULL,'OTL','__ _/\______/\___/\_ _\  /_________________. __ ___  ___  ____  /_ \\//                 | /  /  / /  / /  /__  \/ THE ULTIMATE WHO |',replace('[-aQUAwHO v2.0-]      ____  [-aQUARIUS/oTL-]\n__ _/\______/\___/\_ _\  /_________________.\n__ ___  ___  ____  /_ \\//                 |\n  /  /  / /  / /  /__  \/ THE ULTIMATE WHO |\n /  /  / /  / /  /  /    DOOR for /X !!!   |\n_\__  /_/  /_/___  / TOTALLY CONFIGURABLE! |\n____ /___ /__ ___ /(OUTPUT, STRINGS & MORE)|\nbIS\/   \/      \/   Can be made to show:  |\n  name, loc, action, conf, acs level, baud,|\n  multichat avail, calls, UL stats, time!  |\n-- -  -    - -- -   ---- - ---- -----------''\n','\n',char(10)),'AquaWho.guide',replace('@database AquaWho\n\nCopyright © 1994 Aquarius/Outlaws\n\n@Remark $VER: AquaWho v2.0 AmigaGuide doc\n\n@node MAIN "AquaWho v2.0 Documentation"\n\n       _ _ ___/\______/\__ ____/\___/\__ _ _/\____ _/\_ __ __/\______\n      __ ________   __   /   _   ___   / ______   \___/__/     _____/\n         bIS/   /   /   /   //   //   /___/ __¬   /  /  /  /\__   \\n           /   /   /   /   //   //   /   /  \    /  /  /  /   /   /\n    __  _ _\____  /\____  //_  //_____  /___/\  /\_____  /\ _/   /___\n     _  ___ _   \/  _  _\/_  \/____ __\/ ___ _\/_______\/____   /_ _/\n                                                            \  /\n                                  present                    \/\n                      a door for AmiExpress 2.xx/3.xx:\n\n                  >>> AquaWho v2.0 by Aquarius/Outlaws <<<\n\n                      [- Contents of documentation -]\n\n                @{"   Copyright Note   " Link Copyright   }   @{"   Configuration    " Link Configuration}\n                @{"  Archive Contents  " Link Archive     }   @{"   Error Messages   " Link Errors}\n                @{"    Introduction    " Link Introduction}   @{"  How to Reach Me   " Link ContactMe}\n                @{"      Features      " Link Features    }   @{"      History       " Link History}\n                @{"    Requirements    " Link Requirements}   @{"     Greetings      " Link Greetings}\n                @{"    Installation    " Link Installation}\n@endnode\n\n@node Copyright "AquaWho v2.0 Documentation"\n\n                          Copyright ©1994 Aquarius\n\n                 Permission is granted to freely distribute\n               this product for non-commercial purposes only,\n                  as long as all files remain unmodified.\n\n@endnode\n\n@node Archive "AquaWho v2.0 Documentation"\n\nArchive (OTL-AW20.LHA) Contents\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n   Filename:        Size:  Description:\n\nDoors/AquaWho/\n   AquaWho.10.000   27264  Version for 68000+ and older /X than 3.30.\n   AquaWho.10.020   26576  Version for 68020+ and older /X than 3.30.\n   AquaWho.32.000   27284  Version for 68000+ and /X 3.30+.\n   AquaWho.32.020   26596  Version for 68020+ and /X 3.30+.\n   AquaWho.doc      39013  Ascii version of the doc.\n   AquaWho.guide    55365  This document file!\n   CallsCounter      5728  CLI command which keeps track of # calls.\n   ULCounter         7480  Door which keeps track of uploads.\n   LookGenerator    31372  CLI command which generates look files\n   who.info          2339  Standard configuration icon.\n   who.look          1343  A sample look file (defines the output).\n   frontend.info     2199  Config icon for Shapechanger''s frontend design.\n   frontend.look     1845  Look file by Shapechanger. Suits as frontend.\n\nDoors/AquaWho/MiscIcons/\n   intex.info        2159  Cfg icon for /X internal who + conf (LookGen.).\n   nstat.info        1256  Cfg icon for Biscrok''s frontend look (LookGen).\n   vnz.info          2641  Cfg icon for Vinzi''s designs (vnz.look* below).\n   zin!.info         2340  Config icon for Zin!''s design (in LookGen.).\n\nDoors/AquaWho/MiscLooks/\n   block.look.4ndz   1189  Look by Aquarius for 4 nodes (easy to extend).\n   flash.look.3ndz   1038  Look by Aquarius for 3 nodes. Edit phone #''s.\n   nfl.look.3ndz      964  Look by Aquarius for 3 nodes. Edit board name.\n   nfl.look.4ndz     1145  Same style but for 4 nodes.\n   vnz.look.2ndz      680  Look file by Vinzi! Really nice as frontend!\n   vnz.look.3ndz      800  Same but for 3 nodes.\n   vnz.look.4ndz      920  4-nd v. Use MiscIcons/vnz.info as config icon.\n\nCommands/BBSCmd/\n   who.info          1282  Command icon for AmiExpress 3.xx.\n   wh.info           1282  Command icon for AmiExpress 3.xx.\n\nCommands/SYSCmd/\n   filecheck.info    1043  Use this to install ULCounter.\n   frontend.info     1268  Use this to have AquaWho as frontend.\n\nPreviews/\n   bis.iff           9808  Picture of Biscrok''s design (LookGenerator).\n   col.iff           5824  A nice design by Aquarius (LookGen.).\n   fire.iff          7564  A hot (hehe) look by Aquarius (LookGen).\n   full.iff          7214  Another nice design by Aquarius (LookGen.).\n   sc1.iff           9334  Shapechanger''s frontend style (LookGen).\n   vnz.iff           4916  Vinzi''s funky design (in dir MiscLooks).\n   zin!.iff          7630  Zin!''s design (in LookGenerator).\n@endnode\n\n@node Introduction "AquaWho v2.0 Documentation"\n\nIntroduction\n~~~~~~~~~~~~\nAquaWho is an AmiExpress door for multinode boards. Briefly you could say\nthat it gives the user information about what''s happening on the other\nnodes. There are lots of who doors out there, but this is simply the most\npowerful ever made! Just look at all the @{"features" Link Features}...\n\n@endnode\n\n@node Features "AquaWho v2.0 Documentation"\n\nFeatures\n~~~~~~~~\nIts output (design, look) is totally configurable!\n\nSeveral design examples are included, some by well-known ascii artists. I\nam sure that you will find one that you like! If not, just make your own\ndesign! You can have different designs on different commands (who, wh,\nnode, frontend etc), so you don''t need a separate frontend who door.\n\nAll strings (action strings for example) can be reconfigured!\n\nIt is able to display: name/handle, location, action, current conference,\naccess level, multichat/OLM availability (for /X 3.37+), number of calls\ntoday (for every node or for all nodes together), number of uploaded files\nand bytes today, and current time and date! It can even make pauses of any\nlength, which can be used to accomplish nice animation effects.\n\nQuiet nodes are supported. The default action string for a quiet node is\n"Secret action" but that can easily be reconfigured to whatever you like,\n"Node inactive" for example to give the impression that no-one is there.\n\nIf a user has a certain access level (configurable of course), he can see\nwho is on a quiet node. The user name will then have a "(Q)" appended.\n\nOf course, it can show file names, but it can also be configured not to\nshow them when the UL/DL takes place in a conference which the user\ndoesn''t have access to. An access value required to see filenames can be\nset as well.\n\nThe door command being used on another node can be shown! You can\nconfigure the access level required to see the command. Conference access\nchecking is also available, meaning that the door command will only be\nshown if it is clear that the AquaWho user has access to the conference in\nwhich that door is being used. This is probably not a very needed feature\n(the conf checking), but it''s there if you want it!\n\nThe access level required to see the conference numbers can be configured.\nAlso, the conference number can be hidden if the AquaWho user doesn''t have\naccess to that conference.\n\nIf a new user is logging into the BBS for the first time, AquaWho displays\n"A new user!" (configurable of course) as user name when he is typing in\nanswers to all the new-user questions. When he is done his name/handle is\ndisplayed, with the note "(NEW)" added. If he gets validated when he is\nonline, the "(NEW)" thing will disappear.\n\nIf a node is reserved for a user, that user''s name is displayed in\nuppercase letters between parentheses. You can make it show a certain\nstring instead if you want to (''Reserved'' for example).\n\nAquaWho is written in highly optimized C code for best performance!\n@endnode\n\n@node Requirements "AquaWho v2.0 Documentation"\n\nRequirements\n~~~~~~~~~~~~\nAn Amiga with OS 2.0 or higher.\nAmiExpress/SigmaExpress.\n(The door works for sure on /X v2.20-3.38 and possibly on other versions\ntoo.)\n\n@endnode\n\n@node Installation "AquaWho v2.0 Documentation"\n\nInstallation\n~~~~~~~~~~~~\nYou should read the entire installation text completely, since it contains\nlots of important information.\n\n\nFirst create the directory ''Doors:AquaWho'', and copy the correct version\nof the door there.\n\nAquaWho.10.000 is for S-Express & earlier /X than 3.30, and 68000/010.\nAquaWho.10.020 is for S-Express & earlier /X than 3.30 and 68020/030/040.\nAquaWho.32.000 is for /X 3.30 or higher, and 68000/010.\nAquaWho.32.020 is for /X 3.30 or higher, and 68020/030/040.\n\nIt could also be a good idea to copy the documentation to that directory,\nbecause you will probably need it in the future.\n\nNow you must decide what commands you want to have AquaWho on, probably\n''who'', ''wh'' and perhaps ''frontend'' and some more.\n\n\nFor every command, you need to fix THREE things.....\n\n\n1. The normal XIM door installation...\n\n   /X 3.xx:\n\n   Copy Commands/BBSCmd/who.info from the archive to your BBSCmd directory\n   as <command>.info (who.info, wh.info etc) and check that its tooltypes\n   LOCATION and ACCESS are correct.\n\n   If you will install it as frontend, copy the same icon to Frontend.info\n   in your SYSCmd directory.\n\n\n   /X 2.xx, SigmaExpress:\n\n   Add a line to your BBS.CMD, for example:\n\n   -----Cut-here-------------------------------\n   *WHO      XM020Doors:AquaWho/AquaWho.10.020\n   --------Cut-here----------------------------\n                  ^--- File name of the door with full path.\n               ^^^\n    ^          Access required to use the door.\n    |\n    ` The command that will invoke AquaWho.\n\n   For frontend installation, add this to your SYS.CMD file:\n   -----Cut-here-------------------------------\n   FRONTEND  XM020Doors:AquaWho/AquaWho.10.020\n   --------Cut-here----------------------------\n\n\n2. You must have a @{"look file" Link LookFile}, ''Doors:AquaWho/<command>.look''. It tells the\n   door what to display. For a quick installation, I recommend that you\n   use the LookGenerator utility to create the look file. Just open a\n   shell window and start it, and you''ll see how to use it. It contains\n   many nice designs.\n\n\n3. You must also have a configuration icon for every command:\n   ''Doors:AquaWho/<command>.info''. Use the supplied icon\n   ''Doors/AquaWho/who.info'' and check that its tooltypes are correct.\n   Especially all access values (ACS.*) should be thoroughly checked!!\n   That they are alright for ONE look file doesn''t mean they''re good for\n   another. If they are set wrong, too little or too much info could be\n   shown (security!), or the door could be slower than what is possible\n   (see @{"ACS.SEE_CONFS" Link ACS.SEE_CONFS} e.g.). All @{"tooltypes" Link Tooltypes} are described in detail in a\n   section below.\n\n\nThe CallersLog must be turned on if you are going to use a who design that\nshows the current conference.\n\nIf you are using relative conferences, the conference numbers AquaWho\nshows might not be the same for all users on your board. But if they all\nhave access to the x first conferences, there''s no problem. For example,\nit''s not good if you''re using relative conferences and some users'' access\nlooks like this: XX_X__X__ or X_XXX____. Better: XXX______ and XXXX_____,\nas examples. (AmiExpress 3.xx doesn''t have these conference access\nstrings, but you get the point anyway.) So if you have the "bad" case,\neither turn off relative conferences, or don''t use a @{"look file" Link LookFile} with\nconference codes.\n\nThe DoorLog must be turned on if you have /X 3.xx and you don''t have the\ntooltype @{"DISABLE_EXTRA" Link DISABLE_EXTRA} in the config icon. The DoorLog is then used to\ndetermine if the logoff module is running.\nYou also need to have it turned on if you want the door commands being\nused on other nodes to be shown (if @{"ACS.SEE_DOORS" Link ACS.SEE_DOORS} is 255 or lower).\n\nTo turn on the DoorLog with /X 2.xx, put ''NODE* DOORLOG'' in ACP.STARTUP.\nFor /X 3.xx, put the tooltype ''DOOR_LOG'' in the node icons.\n\nThe DoorLog grows very large quickly I''m afraid... The best solution to\nthis is to use my utility "Stripper" (released separately) about once a\nday. It rips off the beginning of the file, to a size of your choice. 1000\nbytes is appropriate I guess. Use it like this: "Strip BBS:Node(x)/DoorLog\n1000".\n\nIf you are going to use a who design that shows number of calls, you must\ninstall the CallsCounter utility. Run it in your logoff scripts with the\nnode number as its only argument. For example, in the logoff script for\nnode 3, add "Doors:AquaWho/CallsCounter 3".\n\nTo use a look file with uploaded files or bytes today, ULCounter must be\ninstalled as the FILECHECK door. It''s possible that you already have\nanother tool installed there. If it is Sigma Seven''s DupeChecker, you can\ninstall ULCounter as the SERVER command (in SYSCmd) instead. But if your\nFILECHECK door doesn''t offer such a possibility, you can use\n''5D-MultiStart'' (by Sven the Creator/5D). Then you can have as many\nFILECHECKers as you want!\n@endnode\n\n@node Configuration "AquaWho v2.0 Documentation"\n\nConfiguration\n~~~~~~~~~~~~~\n\n@{" The Config Icon Tooltypes " Link Tooltypes}\n\n@{" Look File Specification   " Link LookFile}\n\n@endnode\n\n@node Tooltypes "AquaWho v2.0 Documentation"\n\nThe Tooltypes\n=============\n\nA tip: For you who didn''t know this, ANSI codes can be used in tooltypes.\nTo write the escape character, press lamiga+ctrl+esc...\n\nHere follows descriptions of all tooltypes possible to have in a\nconfiguration icon (''Doors:AquaWho/<command>.info''):\n\n"On/off" tooltypes:\n\n@{" RESET_LINES     " Link RESET_LINES      } @{" NONSTOP         " Link NONSTOP          } @{" FRONTEND        " Link FRONTEND         } @{" GET_BAUD        " Link GET_BAUD         }\n@{" DISABLE_EXTRA   " Link DISABLE_EXTRA    } @{" DOORCMD_UPCASE  " Link DOORCMD_UPCASE   } @{" DOORCMD_INITIAL " Link DOORCMD_INITIAL  }\n\nAccess tooltypes:\n\n@{" ACS.SEE_FILES               " Link ACS.SEE_FILES                } @{" ACS.SEE_CONFS               " Link ACS.SEE_CONFS                }\n@{" ACS.SEE_ACCESS              " Link ACS.SEE_ACCESS               } @{" ACS.SEE_QUIET_NODES         " Link ACS.SEE_QUIET_NODES          }\n@{" ACS.SEE_NEW                 " Link ACS.SEE_NEW                  } @{" ACS.SEE_DOORS               " Link ACS.SEE_DOORS                }\n@{" ACS.NO_CONF_ACS_CHECK.FILES " Link ACS.NO_CONF_ACS_CHECK.FILES  } @{" ACS.NO_CONF_ACS_CHECK.CONFS " Link ACS.NO_CONF_ACS_CHECK.CONFS  }\n@{" ACS.NO_CONF_ACS_CHECK.DOORS " Link ACS.NO_CONF_ACS_CHECK.DOORS  }\n\nCharacter tooltypes:\n\n@{" METACHAR         " Link METACHAR        } @{" NOCONFCHAR       " Link NOCONFCHAR      } @{" SECRETCONFCHAR   " Link SECRETCONFCHAR  } @{" NOACCESSCHAR     " Link NOACCESSCHAR    }\n@{" SECRETACCESSCHAR " Link SECRETACCESSCHAR} @{" NOBAUDCHAR       " Link NOBAUDCHAR      } @{" SECRETBAUDCHAR   " Link SECRETBAUDCHAR  }\n\nMiscellaneous Strings:\n\n@{" ADD_TO_BAUD      " Link ADD_TO_BAUD     } @{" CHAT_NO          " Link CHAT_NO         } @{" CHAT_YES         " Link CHAT_YES        } @{" NOTACTIVENAME    " Link NOTACTIVENAME   }\n@{" AWAITCONNECTNAME " Link AWAITCONNECTNAME} @{" SHUTDOWNNAME     " Link SHUTDOWNNAME    } @{" SUSPENDNAME      " Link SUSPENDNAME     } @{" RESERVENAME      " Link RESERVENAME     }\n@{" NOWHERE          " Link NOWHERE         } @{" SOMEBODY         " Link SOMEBODY        } @{" SOMEWHERE        " Link SOMEWHERE       } @{" SECRETNAME       " Link SECRETNAME      }\n@{" SECRETLOC        " Link SECRETLOC       } @{" NEWUSER          " Link NEWUSER         } @{" USERNAME         " Link USERNAME        } @{" YOURNAME         " Link YOURNAME        }\n@{" YOURNAMEQ        " Link YOURNAMEQ       } @{" YOUFRONTLOC      " Link YOUFRONTLOC     }\n\nTooltypes describing actions:\n\n@{" IDLE            " Link IDLE             } @{" DOWNLOADING     " Link DOWNLOADING      } @{" DLFILE          " Link DLFILE           } @{" UPLOADING       " Link UPLOADING        }\n@{" ULFILE          " Link ULFILE           } @{" DOORS           " Link DOORS            } @{" DOORCMD         " Link DOORCMD          } @{" MAIL            " Link MAIL             }\n@{" STATS           " Link STATS            } @{" ACCOUNT         " Link ACCOUNT          } @{" ZOOM            " Link ZOOM             } @{" FILES           " Link FILES            }\n@{" BULLETINS       " Link BULLETINS        } @{" VIEWING         " Link VIEWING          } @{" ACCOUNTSEQ      " Link ACCOUNTSEQ       } @{" LOGOFF          " Link LOGOFF           }\n@{" SYSOP           " Link SYSOP            } @{" SHELL           " Link SHELL            } @{" EMACS           " Link EMACS            } @{" JOIN            " Link JOIN             }\n@{" CHAT            " Link CHAT             } @{" NOTACTIVE       " Link NOTACTIVE        } @{" REQ_CHAT        " Link REQ_CHAT         } @{" CONNECT         " Link CONNECT          }\n@{" LOGGINGON       " Link LOGGINGON        } @{" AWAITCONNECT    " Link AWAITCONNECT     } @{" SCANNING        " Link SCANNING         } @{" SHUTDOWN        " Link SHUTDOWN         }\n@{" SHUTDOWN.<node> " Link SHUTDOWN.<node>  } @{" MULTICHAT       " Link MULTICHAT        } @{" SUSPEND         " Link SUSPEND          } @{" RESERVE         " Link RESERVE          }\n@{" OLM             " Link OLM              } @{" NUKE            " Link NUKE             } @{" SECRET          " Link SECRET           } @{" AQUAWHO         " Link AQUAWHO          }\n@{" UNKNOWN         " Link UNKNOWN          }\n@endnode\n\n@node RESET_LINES "AquaWho v2.0 Documentation"\n\nRESET_LINES                         optional\n\nIf this tooltype is present in the config icon, the number of lines viewed\nis first set to zero, to prevent the pause prompt from appearing too soon.\nThis can be useful when the door is used as frontend or is started with\nMCI, but it makes no difference when the door is started from the main\nprompt.\n@endnode\n\n@node NONSTOP "AquaWho v2.0 Documentation"\n\nNONSTOP                             optional\n\nIf you never want any pause prompt in the who door, use this tooltype. It\nturns on non-stop scrolling when the door starts and turns it off when it\nquits.\n@endnode\n\n@node FRONTEND "AquaWho v2.0 Documentation"\n\nFRONTEND                            optional\n\nIf you want to run the door before the logon prompt (handle/password), for\nexample by using MCI in Private.txt or BBSTitle.txt, or as FRONTEND door,\nthen put this tooltype in the config icon. Actually, it is not needed for\ntrue FRONTEND usage - the door can detect that. The effect is, among other\nthings, that the door user''s access level is considered to be 0.\n@endnode\n\n@node GET_BAUD "AquaWho v2.0 Documentation"\n\nGET_BAUD                            optional\n\nIf the look file has baud codes in it, this tooltype must be in the icon.\nThe door will complain if it finds a baud code but not this tooltype. If\nyou don''t want connect baud to be shown, you should not have this\ntooltype, because it would make the who door a bit slower (perhaps not\nnoticably but still).\n@endnode\n\n@node DISABLE_EXTRA "AquaWho v2.0 Documentation"\n\nDISABLE_EXTRA                       optional\n\nIf this is present in the icon, AquaWho will act more like every other who\ndoor in the sense that it will not show "(NEW)" for new users and not read\nthe DoorLog to check if the logoff module is running (/X 3.xx).\n@endnode\n\n@node DOORCMD_UPCASE "AquaWho v2.0 Documentation"\n\nDOORCMD_UPCASE                      optional\n\nIf this tooltype is present, door commands are shown in uppercase letters,\notherwise in lowercase. See @{"DOORCMD_INITIAL" Link DOORCMD_INITIAL}.\n@endnode\n\n@node DOORCMD_INITIAL "AquaWho v2.0 Documentation"\n\nDOORCMD_INITIAL                     optional\n\nIf this tooltype is present, the first letter in the door command is\nwritten in lowercase if the other letters are to be written in uppercase\n(determined by the tooltype @{"DOORCMD_UPCASE" Link DOORCMD_UPCASE}), and in uppercase if the other\nletters are to be written in lowercase.\n\nExample (''dis'' command):\n\nDOORCMD_UPCASE  DOORCMD_INITIAL  : dIS\n-               DOORCMD_INITIAL  : Dis\nDOORCMD_UPCASE  -                : DIS\n-               -                : dis\n@endnode\n\n@node ACS.SEE_FILES "AquaWho v2.0 Documentation"\n\nACS.SEE_FILES=<access level>        required\n\nThis is the minimum access level required to see the names of the files\nbeing uploaded or downloaded.\n@endnode\n\n@node ACS.SEE_CONFS "AquaWho v2.0 Documentation"\n\nACS.SEE_CONFS=<access level>        required\n\nThis is the minimum access level required to see conference numbers. If\nthe look file doesn''t contain any conference codes, set this higher than\n255. That will possibly make the door faster beacause it won''t read the\nCallersLogs then (unless it needs to check conference access, see\n@{"ACS.NO_CONF_ACS_CHECK.FILES" Link ACS.NO_CONF_ACS_CHECK.FILES} and company).\n@endnode\n\n@node ACS.SEE_ACCESS "AquaWho v2.0 Documentation"\n\nACS.SEE_ACCESS=<access level>       required\n\nThis is the minimum access level required to see other users'' access\nlevel. If there are no access codes in the look file, set this higher than\n255. That will make the door a bit faster.\n@endnode\n\n@node ACS.SEE_QUIET_NODES "AquaWho v2.0 Documentation"\n\nACS.SEE_QUIET_NODES=<access level>  required\n\nThis is the minimum access level required to get all information about a\nnode which is quiet. A "(Q)" will be appended to the handles on quiet\nnodes.\n@endnode\n\n@node ACS.SEE_NEW "AquaWho v2.0 Documentation"\n\nACS.SEE_NEW=<access level>        required (unless @{"DISABLE_EXTRA" Link DISABLE_EXTRA} is used)\n\nThis is the minimum access level required to see if a user is new (not\nvalidated and calling for the first time). "(NEW)" is appended to those\nusers'' names.\n@endnode\n\n@node ACS.SEE_DOORS "AquaWho v2.0 Documentation"\n\nACS.SEE_DOORS=<access level>        required\n\nThis is the minimum access level required to see what door commands are\nbeing used on the other nodes.\n@endnode\n\n@node ACS.NO_CONF_ACS_CHECK.FILES "AquaWho v2.0 Documentation"\n\nACS.NO_CONF_ACS_CHECK.FILES=<access level> req. (if @{"ACS.SEE_FILES" Link ACS.SEE_FILES} <= 255)\n\nThis is the minimum access level required to avoid conference access\nchecking that could hide filenames. If a user has a lower access, he can\nONLY see the filenames IF it is clear that he has access to the conference\nwhere the upload/download takes place.\n@endnode\n\n@node ACS.NO_CONF_ACS_CHECK.CONFS "AquaWho v2.0 Documentation"\n\nACS.NO_CONF_ACS_CHECK.CONFS=<access level> req. (if @{"ACS.SEE_CONFS" Link ACS.SEE_CONFS} <= 255)\n\nThis is the minimum access level required to avoid conference access\nchecking that could hide conference numbers. If a user has a lower access,\nhe can ONLY see the conference number of another user IF it is clear that\nhe has access to that conference.\n@endnode\n\n@node ACS.NO_CONF_ACS_CHECK.DOORS "AquaWho v2.0 Documentation"\n\nACS.NO_CONF_ACS_CHECK.DOORS=<access level>  required\n\nThis is the minimum access level required to avoid conference access\nchecking that could hide door commands. If a user has a lower access, he\ncan ONLY see the door command being used by another user IF it is clear\nthat he has access to that conference.\n@endnode\n\n@node METACHAR "AquaWho v2.0 Documentation"\n\nMETACHAR=<character>                optional, default: ''°''\n\nThis is the character that is the beginning of the special codes in look\nfiles. See the section that describes the @{"look files" Link LookFile} in detail.\n@endnode\n\n@node NOCONFCHAR "AquaWho v2.0 Documentation"\n\nNOCONFCHAR=<character>              optional, default: ''-''\n\nWhen there is no user on a node or he hasn''t joined a conference yet, or\nthe conference number couldn''t be determined for some reason, this\ncharacter is shown instead of the conference number.\n\nIf padding with zeros is turned on, the space reserved will be filled with\nthis character.\n@endnode\n\n@node SECRETCONFCHAR "AquaWho v2.0 Documentation"\n\nSECRETCONFCHAR=<character>          optional, default: ''x''\n\nIf a node is quiet or the door user hasn''t got access to see conference\nnumbers (see @{"ACS.SEE_CONFS" Link ACS.SEE_CONFS}), this character will be shown instead.\n@endnode\n\n@node NOACCESSCHAR "AquaWho v2.0 Documentation"\n\nNOACCESSCHAR=<character>            optional, default: ''-''\n\nIf the access level can''t be determined, for example when there is no user\non the node, this character is shown instead.\n@endnode\n\n@node SECRETACCESSCHAR "AquaWho v2.0 Documentation"\n\nSECRETACCESSCHAR=<character>        optional, default: ''x''\n\nIf the node is quiet or the door user hasn''t the access set by\n@{"ACS.SEE_ACCESS" Link ACS.SEE_ACCESS}, this character is shown instead of the access level.\n@endnode\n\n@node NOBAUDCHAR "AquaWho v2.0 Documentation"\n\nNOBAUDCHAR=<character>              optional, default: '' ''\n\nWhenever the connect bps can''t be determined, for example when there is no\nuser on the node, this character is shown instead.\n@endnode\n\n@node SECRETBAUDCHAR "AquaWho v2.0 Documentation"\n\nSECRETBAUDCHAR=<character>          optional, default: ''x''\n\nIf a node is quiet, this character will be shown instead of the connect\nbps.\n@endnode\n\n@node ADD_TO_BAUD "AquaWho v2.0 Documentation"\n\nADD_TO_BAUD=<string>                optional, default: ''''\n\nThis tooltype lets you specify a string which will be appended to the\nconnect bps when that can be determined, or the node is quiet (and\n@{"SECRETBAUDCHAR" Link SECRETBAUDCHAR} isn''t a space). For example, if you enter '' bps'' here, this\ncould be shown:\n\n14000 bps   Joining a conf   ('' bps'' was added)\n            Awaiting connect (could not determine baud -> no '' bps'')\n    x bps   Secret action    (quiet node, '' bps'' was added)\n@endnode\n\n@node CHAT_NO "AquaWho v2.0 Documentation"\n\nCHAT_NO=<string>                    optional, default: ''NO ''\n\nThis string is inserted as multichat/OLM availability when the user is NOT\navailable. Its length should be the same as @{"CHAT_YES" Link CHAT_YES}.\n@endnode\n\n@node CHAT_YES "AquaWho v2.0 Documentation"\n\nCHAT_YES=<string>                   optional, default: ''YES''\n\nThis string is inserted as multichat/OLM availability when the user IS\navailable. Its length should be the same as @{"CHAT_NO" Link CHAT_NO}.\n@endnode\n\n@node NOTACTIVENAME "AquaWho v2.0 Documentation"\n\nNOTACTIVENAME=<string>              optional, default: ''Nobody''\n\nThis is the string that is shown as user name when the node is resetting\nitself (when the action is @{"NOTACTIVE" Link NOTACTIVE}).\n@endnode\n\n@node AWAITCONNECTNAME "AquaWho v2.0 Documentation"\n\nAWAITCONNECTNAME=<string>           optional, default: ''Nobody''\n\nThis is the string that is shown as user name when the node is ready to\nreceive a call (when the action is @{"AWAITCONNECT" Link AWAITCONNECT}).\n@endnode\n\n@node SHUTDOWNNAME "AquaWho v2.0 Documentation"\n\nSHUTDOWNNAME=<string>               optional, default: ''Nobody''\n\nThis is the string that is shown as user name when the node is shutdown,\nnot active (when the action is @{"SHUTDOWN" Link SHUTDOWN}).\n@endnode\n\n@node SUSPENDNAME "AquaWho v2.0 Documentation"\n\nSUSPENDNAME=<string>                optional, default: ''Nobody''\n\nThis is the string that is shown as user name when the node is suspended\n(when the action is @{"SUSPEND" Link SUSPEND}).\n@endnode\n\n@node RESERVENAME "AquaWho v2.0 Documentation"\n\nRESERVENAME=<string>                optional\n\nIf you don''t want the name of the user whom the node is reserved for to be\nshown (like this: "( USERNAME )"), then use this tooltype to determine\nwhat should be shown instead (''Reserved'' for example).\n@endnode\n\n@node NOWHERE "AquaWho v2.0 Documentation"\n\nNOWHERE=<string>                    optional, default: ''Nowhere''\n\nThis is the string that is shown as location when nobody is on the node.\n@endnode\n\n@node SOMEBODY "AquaWho v2.0 Documentation"\n\nSOMEBODY=<string>                   optional, default: ''Somebody''\n\nThis string is shown as user name when somebody is connecting to the BBS\n(when the action is @{"CONNECT" Link CONNECT}), and at all other occasions when somebody is\nonline but the name cannot be determined.\n@endnode\n\n@node SOMEWHERE "AquaWho v2.0 Documentation"\n\nSOMEWHERE=<string>                  optional, default: ''Somewhere''\n\nThis string is shown as location when:\n - a new user is logging on (action @{"ACCOUNTSEQ" Link ACCOUNTSEQ}).\n - a user is connecting to the BBS (action @{"CONNECT" Link CONNECT}).\n - the node is reserved for a user (action @{"RESERVE" Link RESERVE}).\n - somebody is online but the name cannot be determined.\n@endnode\n\n@node SECRETNAME "AquaWho v2.0 Documentation"\n\nSECRETNAME=<string>                 optional, default: ''Somebody''\n\nThis string is shown as user name when a node is quiet (and the AquaWho\nuser hasn''t got the access defined by @{"ACS.SEE_QUIET_NODES" Link ACS.SEE_QUIET_NODES}). The action\nstring will then be what is defined by the tooltype @{"SECRET" Link SECRET}.\n@endnode\n\n@node SECRETLOC "AquaWho v2.0 Documentation"\n\nSECRETLOC=<string>                  optional, default: ''Somewhere''\n\nThis string is shown as location when a node is quiet (and the AquaWho\nuser hasn''t got the access defined by @{"ACS.SEE_QUIET_NODES" Link ACS.SEE_QUIET_NODES}). The action\nstring will then be what is defined by the tooltype @{"SECRET" Link SECRET}.\n@endnode\n\n@node NEWUSER "AquaWho v2.0 Documentation"\n\nNEWUSER=<string>                    optional, default: ''A new user!''\n\nThis is the string that is shown as user name when a new user is logging\non, answering new-user questions. The action is then @{"ACCOUNTSEQ" Link ACCOUNTSEQ}.\n@endnode\n\n@node USERNAME "AquaWho v2.0 Documentation"\n\nUSERNAME=<string>                   optional\n\nIf you don''t want ANY of the users'' names to be shown, then use this\ntooltype to set the replacement string. (The AquaWho user''s name is not\naffected by this, see @{"YOURNAME" Link YOURNAME}.) This is primarily intended for frontend\nusage, where you can write ''USERNAME=**BUSY**'' for example.\n@endnode\n\n@node YOURNAME "AquaWho v2.0 Documentation"\n\nYOURNAME=<string>                   optional, default for frontend: ''You!''\n\nIf you don''t want the AquaWho user''s name to be shown, then use this\ntooltype to set the replacement string. When AquaWho is used as frontend\ndoor, this tooltype defines the user''s name.\n@endnode\n\n@node YOURNAMEQ "AquaWho v2.0 Documentation"\n\nYOURNAMEQ=<string>                  optional, default: ''You! (Quiet)''\n\nThis string is shown as name for the AquaWho user when the node is quiet\nand one of the following criteria holds:\n - it is a frontend command\n - @{"YOURNAME" Link YOURNAME} is present in the config icon\n - the user doesn''t have the access set by @{"ACS.SEE_QUIET_NODES" Link ACS.SEE_QUIET_NODES}\n@endnode\n\n@node YOUFRONTLOC "AquaWho v2.0 Documentation"\n\nYOUFRONTLOC=<string>                optional, default: ''''\n\nThis is the location string for the AquaWho user when the door is used as\nfrontend.\n@endnode\n\n@node IDLE "AquaWho v2.0 Documentation"\n\nIDLE=<string>                       optional, default: ''Doing nothing''\n\nThis is the string shown when the user is at the main prompt, perhaps\ntyping a command.\n@endnode\n\n@node DOWNLOADING "AquaWho v2.0 Documentation"\n\nDOWNLOADING=<string>                optional, default: ''Downloading''\n\nThe user is downloading but the filename is not shown. Possible reasons:\n 1. The door user''s access level is lower than what is specified in\n    @{"ACS.SEE_FILES" Link ACS.SEE_FILES}.\n 2. @{"ACS.NO_CONF_ACS_CHECK.FILES" Link ACS.NO_CONF_ACS_CHECK.FILES} is set higher than the AquaWho user''s\n    access level (therefore conf access checking is done), and he doesn''t\n    have access to the conference in which the download takes place.\n 3. He is typing file names to download and has not yet begun the\n    transfer.\n 4. He chose ''goodbye after transfer'' and is logging off.\n 5. The AquaWho user doesn''t have the access defined by\n    @{"ACS.NO_CONF_ACS_CHECK.FILES" Link ACS.NO_CONF_ACS_CHECK.FILES} and you are using relative conferences.\n    Then you must either remove conference access checking by setting\n    ACS.NO_CONF_ACS_CHECK.FILES to 0 (also @{"ACS.NO_CONF_ACS_CHECK.CONFS" Link ACS.NO_CONF_ACS_CHECK.CONFS} and\n    @{"ACS.NO_CONF_ACS_CHECK.DOORS" Link ACS.NO_CONF_ACS_CHECK.DOORS}) or stop using relative conferences,\n    because the conference access checking doesn''t work with relative\n    conferences (unless the conference numbers for all users are the same\n    with, as without relative conferences)!\n@endnode\n\n@node DLFILE "AquaWho v2.0 Documentation"\n\nDLFILE=<string>                     optional, default: ''DL: ''\n\nThis string is shown as action with the filename appended, when a user is\ndownloading. Note that no space is automatically inserted between this\nstring and the filename (for more configuration freedom).\n@endnode\n\n@node UPLOADING "AquaWho v2.0 Documentation"\n\nUPLOADING=<string>                  optional, default: ''Uploading''\n\nThe user is uploading, but the filename is not shown. Possible reasons:\n 1. The door user''s access level is lower than what is specified in\n    @{"ACS.SEE_FILES" Link ACS.SEE_FILES}.\n 2. @{"ACS.NO_CONF_ACS_CHECK.FILES" Link ACS.NO_CONF_ACS_CHECK.FILES} is set higher than the AquaWho user''s\n    access level (therefore conf access checking is done), and he doesn''t\n    have access to the conference in which the upload takes place.\n 3. The actual transfer has not yet begun.\n 4. He chose ''goodbye after transfer'' and is logging off.\n 5. The AquaWho user doesn''t have the access defined by\n    @{"ACS.NO_CONF_ACS_CHECK.FILES" Link ACS.NO_CONF_ACS_CHECK.FILES} and you are using relative conferences.\n    Then you must either remove conference access checking by setting\n    ACS.NO_CONF_ACS_CHECK.FILES to 0 (also @{"ACS.NO_CONF_ACS_CHECK.CONFS" Link ACS.NO_CONF_ACS_CHECK.CONFS} and\n    @{"ACS.NO_CONF_ACS_CHECK.DOORS" Link ACS.NO_CONF_ACS_CHECK.DOORS}) or stop using relative conferences,\n    because the conference access checking doesn''t work with relative\n    conferences (unless the conference numbers for all users are the same\n    with, as without relative conferences)!\n@endnode\n\n@node ULFILE "AquaWho v2.0 Documentation"\n\nULFILE=<string>                     optional, default: ''UL: ''\n\nThis string is shown as action with the filename appended, when a user is\ndownloading. Note that no space is automatically inserted between this\nstring and the filename (for more configuration freedom).\n@endnode\n\n@node DOORS "AquaWho v2.0 Documentation"\n\nDOORS=<string>                      optional, default: ''Using a door''\n\nThe user is using a door, an external module, but the door command is not\nshown. Possible reasons:\n 1. The door user''s access level is lower than what is specified in\n    @{"ACS.SEE_DOORS" Link ACS.SEE_DOORS}.\n 2. @{"ACS.NO_CONF_ACS_CHECK.DOORS" Link ACS.NO_CONF_ACS_CHECK.DOORS} is set higher than the AquaWho user''s\n    access level (therefore conf access checking is done), and he doesn''t\n    have access to the conference in which the door is being used.\n 3. The last line in the DoorLog didn''t contain a door command.\n 4. There was an error reading the DoorLog. Make sure that the tooltype\n    DOOR_LOG is present in the BBS:Node(x).info icons (for /X 3.xx).\n 5. The AquaWho user doesn''t have the access defined by\n    @{"ACS.NO_CONF_ACS_CHECK.DOORS" Link ACS.NO_CONF_ACS_CHECK.DOORS} and you are using relative conferences.\n    Then you must either remove conference access checking by setting\n    ACS.NO_CONF_ACS_CHECK.DOORS to 0 (also @{"ACS.NO_CONF_ACS_CHECK.FILES" Link ACS.NO_CONF_ACS_CHECK.FILES}\n    and @{"ACS.NO_CONF_ACS_CHECK.CONFS" Link ACS.NO_CONF_ACS_CHECK.CONFS}) or stop using relative conferences,\n    because the conference access checking doesn''t work with relative\n    conferences (unless the conference numbers for all users are the same\n    with, as without relative conferences)!\n@endnode\n\n@node DOORCMD "AquaWho v2.0 Documentation"\n\nDOORCMD=<string>                    optional, default: ''Using door: ''\n\nThis string is shown as action with the door command appended when a user\nis using a door. If the door command isn''t shown, see the tooltype @{"DOORS" Link DOORS}\nfor reasons. Note that no space is automatically inserted between this\nstring and the door command (for more configuration freedom).\n@endnode\n\n@node MAIL "AquaWho v2.0 Documentation"\n\nMAIL=<string>                       optional, default: ''R/W mail''\n\nThis is the action string shown when the user is reading or writing mail\n(not at logon, which is @{"SCANNING" Link SCANNING}).\n@endnode\n\n@node STATS "AquaWho v2.0 Documentation"\n\nSTATS=<string>                      optional, default: ''Checking status''\n\nThis is the action string shown when the user is using the ''w'' or ''s''\nstandard AmiExpress command.\n@endnode\n\n@node ACCOUNT "AquaWho v2.0 Documentation"\n\nACCOUNT=<string>                    optional, default: ''Account editing''\n\nThis is the action string shown when the user is editing accounts, or at\nleast it should be but I don''t think that AmiExpress uses it at all. When\nthe account editor is used (command ''1'') the action is @{"SYSOP" Link SYSOP}.\n@endnode\n\n@node ZOOM "AquaWho v2.0 Documentation"\n\nZOOM=<string>                       optional, default: ''Zooming mail''\n\nThis is the action string shown when the user is zooming mail (collecting\nfor download).\n@endnode\n\n@node FILES "AquaWho v2.0 Documentation"\n\nFILES=<string>                      optional, default: ''Scanning files''\n\nThis is the action string shown when the user is viewing a filelist.\nInternal /X commands resulting in this action: ''f'', ''n'', ''z'' and ''a''.\n@endnode\n\n@node BULLETINS "AquaWho v2.0 Documentation"\n\nBULLETINS=<string>                  optional, default: ''Reading bulletins''\n\nThis is the action string shown when the user is reading bulletins (the\n''b'' command).\n@endnode\n\n@node VIEWING "AquaWho v2.0 Documentation"\n\nVIEWING=<string>                    optional, default: ''Viewing text file''\n\nThis is the action string shown when the user is viewing a file, with the\n''v'' or ''vs'' command.\n@endnode\n\n@node ACCOUNTSEQ "AquaWho v2.0 Documentation"\n\nACCOUNTSEQ=<string>                 optional, default: ''Logging on''\n\nThis is the action string shown when the user is logging on the BBS for\nthe first time (answering new-user questions etc).\n@endnode\n\n@node LOGOFF "AquaWho v2.0 Documentation"\n\nLOGOFF=<string>                     optional, default: ''Logging off''\n\nThis is the action string shown when the user is logging off.\n@endnode\n\n@node SYSOP "AquaWho v2.0 Documentation"\n\nSYSOP=<string>                      optional, default: ''Sysop activities''\n\nThis string is shown as action when the user is using a sysop command such\nas ''1'', ''2'' and ''5''.\n@endnode\n\n@node SHELL "AquaWho v2.0 Documentation"\n\nSHELL=<string>                      optional, default: ''Using Shell''\n\nThis is the action string shown when the user is in the Shell.\n@endnode\n\n@node EMACS "AquaWho v2.0 Documentation"\n\nEMACS=<string>                      optional, default: ''Using EMACS''\n\nThis is the action string shown when the user is editing using EMACS.\nAmiExpress commands: ''3'' and ''4''.\n@endnode\n\n@node JOIN "AquaWho v2.0 Documentation"\n\nJOIN=<string>                       optional, default: ''Joining a conf''\n\nThis is the action string shown when the user is joining a conference.\n@endnode\n\n@node CHAT "AquaWho v2.0 Documentation"\n\nCHAT=<string>                       optional, default: ''Chatting''\n\nThis is the action string shown when the user is chatting with the sysop.\n@endnode\n\n@node NOTACTIVE "AquaWho v2.0 Documentation"\n\nNOTACTIVE=<string>                  optional, default: ''Awaiting connect''\n\nThis is the action string shown when someone just logged off and the node\nis being resetted.\n@endnode\n\n@node REQ_CHAT "AquaWho v2.0 Documentation"\n\nREQ_CHAT=<string>                   optional, default: ''Paging Sysop''\n\nThis is the action string shown when the user is paging the sysop\n(requesting chat).\n@endnode\n\n@node CONNECT "AquaWho v2.0 Documentation"\n\nCONNECT=<string>                    optional, default: ''Connecting to BBS''\n\nThis is the action string shown when someone is connecting to the BBS.\n@endnode\n\n@node LOGGINGON "AquaWho v2.0 Documentation"\n\nLOGGINGON=<string>                  optional, default: ''Logging on''\n\nThis is the action string shown when the user is logging on the BBS.\n@endnode\n\n@node AWAITCONNECT "AquaWho v2.0 Documentation"\n\nAWAITCONNECT=<string>               optional, default: ''Awaiting connect''\n\nThis is the action string shown when the node is free for call.\n@endnode\n\n@node SCANNING "AquaWho v2.0 Documentation"\n\nSCANNING=<string>                   optional, default: ''Scanning for mail''\n\nThis is the action string shown when the user just logged on and is\nscanning for mail.\n@endnode\n\n@node SHUTDOWN "AquaWho v2.0 Documentation"\n\nSHUTDOWN=<string>                   optional, default: ''Node inactive''\n\nThis is the action string shown when the node is not active. See also\n@{"SHUTDOWN.<node>" Link SHUTDOWN.<node>}.\n@endnode\n\n@node SHUTDOWN.<node> "AquaWho v2.0 Documentation"\n\nSHUTDOWN.<node>=<string>            optional\n\nWith this tooltype you can define a string that will be shown only for the\nspecified node when it is shutdown. The intended use was to have "Sysop\ncalling out!" or something similar for the nodes that can be used for\nthat. For example, if you always use node 3 for calling out, write\n"SHUTDOWN.3=Sysop calling out!". It can be used for any info on why that\nnode is down.\n@endnode\n\n@node MULTICHAT "AquaWho v2.0 Documentation"\n\nMULTICHAT=<string>                  optional, default: ''MultiNd chatting''\n\nThis is the action string shown when the user is using a multi-node chat\ndoor.\n@endnode\n\n@node SUSPEND "AquaWho v2.0 Documentation"\n\nSUSPEND=<string>                    optional, default: ''Node suspended''\n\nThis is the action string shown when the node is suspended.\n@endnode\n\n@node RESERVE "AquaWho v2.0 Documentation"\n\nRESERVE=<string>                    optional, default: ''Node reserved''\n\nThis is the action string shown when the node is reserved.\n@endnode\n\n@node OLM "AquaWho v2.0 Documentation"\n\nOLM=<string>                        optional, default: ''Writing OLM''\n\nThis is the action string shown when the user is writing an online\nmessage. This far, it''s probably only the internal OLM command in /X\n3.37+ that can cause this action.\n@endnode\n\n@node NUKE "AquaWho v2.0 Documentation"\n\nNUKE=<string>                       optional, default: ''Nuking files''\n\nThis is the action string shown when the user is using a faker/nuker door.\nNot all nukers support this, so for some the action could be "Using door:\nnuke", "Using door: fake", or just "Using a door" (if @{"ACS.SEE_DOORS" Link ACS.SEE_DOORS} is too\nhigh). Information for door coders: The environment code for this is 99.\n@endnode\n\n@node SECRET "AquaWho v2.0 Documentation"\n\nSECRET=<string>                     optional, default: ''Secret action''\n\nThis is the action string shown when the node is quiet and the AquaWho\nuser hasn''t got the access defined by @{"ACS.SEE_QUIET_NODES" Link ACS.SEE_QUIET_NODES}.\n@endnode\n\n@node AQUAWHO "AquaWho v2.0 Documentation"\n\nAQUAWHO=<string>                    optional, default: ''Using AquaWho!''\n\nThis is the action always shown for the AquaWho user (unless the node is\nquiet and he hasn''t got the access defined by @{"ACS.SEE_QUIET_NODES" Link ACS.SEE_QUIET_NODES}).\n@endnode\n\n@node UNKNOWN "AquaWho v2.0 Documentation"\n\nUNKNOWN=<string>                    optional, default: ''Unknown action!''\n\nThis is the action string shown when the action couldn''t be determined\n(AmiExpress'' environment value was unknown).\n@endnode\n\n@node LookFile "AquaWho v2.0 Documentation"\n\nThe Look File\n=============\n\nA look file is an ordinary ascii/ansi text file, but with special code\nsequences which AquaWho replaces with the item that they stand for.\n\nEvery item specification starts with the metachar, which is defined in the\nconfiguration icon, tooltype @{"METACHAR" Link METACHAR}. The default is ° (alt-w). If that\ncharacter is used in the look file for other purposes ("decoration"),\nchange the metachar to another, unique, character.\n\n\n    °D   Door name ("AquaWho").\n\n    °V   Door version, for example "2.0".\n\n    °P   Programmer ("Aquarius/OTL").\n\n    °T   Current time (HH:MM:SS).\n\n    °E   Current date (MM-DD-YY).\n\n    °F   Full time and date string (DDD MMM dd hh:mm:ss YYYY),\n         for example "Wed Sep 04 15:13:22 1985".\n    ^\n    |\n    `-- Metachar\n\n\n    °W24    Wait for 24/50 (=0.48) seconds. This can be used to accomplish\n      ^^    nice animation effects.\n      ||\n      ``\n       There must always be TWO digits. Write °W08 to wait for 8/50 s.\n       If you need a longer delay than 99/50 s, use multiple wait codes.\n\n\n    °0N18L           The door will replace this with the name of the\n     ^^^ ^           user on node 0. 18 spaces will be reserved for it\n     ||| |           and it will be left justified.\n     ||| |\n     ||| |\n     ||| `-- Justification info: L - left justified\n     |||                         R - right justified\n     |||                         C - centered\n     |||\n     ||`-- Field width (the number of spaces to be reserved).\n     ||    For conf, baud, access, calls, uploads and uploaded bytes: If\n     ||    the field width starts with a zero, then zeros will be used for\n     ||    padding instead of spaces in front of the number, and if the\n     ||    field width is too small for the number to fit then it will be\n     ||    extended to whatever is needed. Look below to see what the\n     ||    field width limits are.\n     ||\n     |`-- Type of data: N - name\n     |                  L - location\n     |                  A - action\n     |                  C - conference\n     |                  B - connect bps\n     |                  X - access level\n     |                  S - calls (requires the CallsCounter util to be\n     |                             run in the logoff scripts)\n     |                  U - uploads (requires the ULCounter door to be run\n     |                               for every uploaded file, for example\n     |                               as FILECHECK)\n     |                  Y - uploaded bytes (requires the ULCounter door to\n     |                           be installed as FILECHECK, nothing else!)\n     |\n     |\n     `-- Node number (0-9 for the 10-node v., 0-31 for the 32-node v.)\n         NOTE! For calls, uploads and uploaded bytes you can leave this\n         out! Then the TOTAL count (the sum from all nodes) will be\n         inserted.\n\n\n    °0H  MultiChat/OLM availability. See @{"CHAT_YES" Link CHAT_YES} and @{"CHAT_NO" Link CHAT_NO}.\n     ^\n     |\n     `-- Node number\n\n\n Here follows the field width limits:\n\n  9 <= Name       <= 38\n  1 <= Location   <= 30\n  1 <= Action     <= 50\n  1 <= Conf       <=  8\n  1 <= Baud       <= 30\n  1 <= Access     <=  4\n  1 <= ChatAvail  <= 40\n  1 <= Calls      <=  8\n  1 <= UL''d Files <=  8\n  1 <= UL''d Bytes <= 12\n\n\n\nSome examples:\n\n Code     Explanation                                     Sample results\n ¯¯¯¯¯¯¯¯ ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯ ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n "°2S3R"  # calls today on node 2.                     "  8", " 13", "102"\n "°2S03R" Same but padded with zeros.                  "008", "013", "102"\n "°S3L"   # calls today on all nodes together.         "9  ", "35 ", "102"\n@endnode\n\n@node Errors "AquaWho v2.0 Documentation"\n\nError Messages\n~~~~~~~~~~~~~~\nThese are all the error messages that AquaWho can give you. An explanation\nof them is given, why they appear and what you can do about it.\n\n\nCouldn''t find multicom port! Check ACP.info!\n\n   The tooltype MULTICOM_PORT must be in your ACP icon. (/X 3.xx)\n\n\nCouldn''t open icon.library!\n\n   This will probably never occur...\n\n\nOut of memory!\n\n   You are really low on memory if this comes up. AquaWho doesn''t consume\n   much.\n\n\nCouldn''t load config icon!!\n\n   Doors:AquaWho/<command>.info couldn''t be opened.\n\n\nError in config icon! Access value missing or invalid!\n\n   Check the tooltypes @{"ACS.SEE_FILES" Link ACS.SEE_FILES}, @{"ACS.SEE_CONFS" Link ACS.SEE_CONFS},\n   @{"ACS.SEE_QUIET_NODES" Link ACS.SEE_QUIET_NODES}, @{"ACS.SEE_NEW" Link ACS.SEE_NEW}, @{"ACS.SEE_DOORS" Link ACS.SEE_DOORS}, @{"ACS.SEE_ACCESS" Link ACS.SEE_ACCESS},\n   @{"ACS.NO_CONF_ACS_CHECK.FILES" Link ACS.NO_CONF_ACS_CHECK.FILES}, @{"ACS.NO_CONF_ACS_CHECK.CONFS" Link ACS.NO_CONF_ACS_CHECK.CONFS} and\n   @{"ACS.NO_CONF_ACS_CHECK.DOORS" Link ACS.NO_CONF_ACS_CHECK.DOORS}.\n\n\nError in look file, line <nr> column <nr>!\n\n   This tells you where the first error in Doors:AquaWho/<command>.look\n   was encountered. Load the @{"look file" Link LookFile} into an ordinary text editor and\n   locate the error.\n\n\nCouldn''t open look file!\n\n   Doors:AquaWho/<command>.look couldn''t be opened.\n\n\nError reading look file!\n\n   An error occurred when AquaWho was reading\n   Doors:AquaWho/<command>.look. The file could be opened but there was a\n   read error.\n\n\nError in config icon, tooltype <tooltype>!\n\n   The tooltype is one of @{"METACHAR" Link METACHAR}, @{"NOCONFCHAR" Link NOCONFCHAR}, @{"SECRETCONFCHAR" Link SECRETCONFCHAR},\n   @{"NOACCESSCHAR" Link NOACCESSCHAR}, @{"SECRETACCESSCHAR" Link SECRETACCESSCHAR}, @{"NOBAUDCHAR" Link NOBAUDCHAR} and @{"SECRETBAUDCHAR" Link SECRETBAUDCHAR}.\n   Check that there is exactly one character there. Note that the error\n   can NOT mean that the tooltype doesn''t exist. There are default\n   characters for all of them.\n\n\nError! Connect bps can''t be shown unless the GET_BAUD tooltype\nis present in the config icon!\n\n   What this means should be obvious. Put @{"GET_BAUD" Link GET_BAUD} in the config icon.\n@endnode\n\n@node ContactMe "AquaWho v2.0 Documentation"\n\nContact Me!\n~~~~~~~~~~~\nI want new nice look files (and their config icons if they are special)!\nGive them to me and I might include them in the next release of AquaWho or\nin a separate design collection. Of course I won''t mind if you release\nyour own collection...\n\nAlso if you have any cool ideas for improvement of this tool, bug reports,\nquestions, or whatever, leave me a message on one of the following boards:\n\n@{"NIGHTFALL" Link Nightfall} ................ Prof Do Right ..... +46-90-120369\n@{"OVERLOAD" Link OverLoad} (OTL SHQ) ....... Vegas ............. +46-8-54063666\nHYSTERIA ................. JAC ............... +46-21-842939\nRAISING HELL ............. Psychopath ........ +46-23-26893\nINSIDE OUT ............... C/\TE¥E ........... +46-346-58697\n@{"SNAKE''S DEN" Link SnakesDen} (OTL WHQ) .... Snake ............. +1-513-683-2330\nTHE HOLE ................. Oldman ............ +1-419-899-2754\n\n@endnode\n\n@node History "AquaWho v2.0 Documentation"\n\nHistory\n~~~~~~~\nHistory restarted! There are so many news from v1.2 (the previous release)\nthat I don''t have the time to explain them all.\n\n2.0  (1994-04-24) Release version.\n\n@endnode\n\n@node Greetings "AquaWho v2.0 Documentation"\n\nGreetings\n~~~~~~~~~\n               Greetings must go to (in no special order):\n\n      - All Members of Outlaws!! - Prof Do Right/Classic - JAC/TDS -\n    - C/\TE¥E/Insane - Ace Caze/Obscene - Wilsom/Obscene - Kid Curry -\n   - Psychopath - Vinzi - Karma - Zin - Shapechanger - Rize - Seagull -\n    - Remix/Classic - RaJ-Ban - fanta/Therion - Static/Therion - CaT -\n     - Dansken - AXL/Attention - Rad!/LSD - Vileius! - Marwin/Duplo -\n      - Freddy Kreuger/GOD - Chig/TDS - The Silencer - Vampire/PDY -\n       - Crocodile/Obscene - Sal-One - Nojje - Zune/HCD - MadCap -\n           - Metalbasher - WarDancer/H&V - The Ones I Forgot! -\n\n@endnode\n\n@node Nightfall "AquaWho v2.0 Documentation"\n+-------------------------------------------------------------------------+\n|         iNTO tOTAL dARKNESS, tHE uNKNOWN; cOME wALK wiTH mE...          |\n| a3ooo    ___/\       ___/\ ____/\__________/\ ___/   __/\ _________9ooMB|\n+----------\__  \______\__  \____  __________  \  /   \__  \   _____/-----+\n|         tS/    __    \/      /  /_____   /     /     /        /         |\n·          /      /    /      /     /     /           /        /          ·\n rEG. /X! /      /    /      /     /     /     /     /        /ClAsSiC SHQ\n         /______/    /______/___________/_____/     /________/\n  lOTs oF      /____/                        /     /    