INSERT INTO door_catalog VALUES('otl_ca10','OTL-CA10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OTL-CA10.LHA','AquaCreateAcc','XIM','[-aQUAcREATEaCC -]____  [-aQUARIUS/oTL-]','1.0',NULL,'OTL','__ _/\______/\___/\_ _\  /_________________. __ ___  ___  ____  /_ \\//                 | /  /  / /  / /  /__  \/   An /X door for |',replace('[-aQUAcREATEaCC v1.0-]____  [-aQUARIUS/oTL-]\n__ _/\______/\___/\_ _\  /_________________.\n__ ___  ___  ____  /_ \\//                 |\n  /  /  / /  / /  /__  \/   An /X door for |\n /  /  / /  / /  /  /   the sysop/cosysops |\n_\__  /_/  /_/___  /  to easily create new |\n____ /___ /__ ___ /   accounts. Works with |\nbIS\/   \/      \/ /X 3.7+ (including 4.x).|\n-- -  -    - -- -   ---- - ---- -----------''\n','\n',char(10)),'AquaCreateAcc.doc',replace('\n       _ _ ___/\______/\__ ____/\___/\__ _ _/\____ _/\_ __ __/\______\n      __ ________   __   /   _   ___   / ______   \___/__/     _____/\n         bIS/   /   /   /   //   //   /___/ __¬   /  /  /  /\__   \\n           /   /   /   /   //   //   /   /  \    /  /  /  /   /   /\n    __  _ _\____  /\____  //_  //_____  /___/\  /\_____  /\ _/   /___\n     _  ___ _   \/  _  _\/_  \/____ __\/ ___ _\/_______\/____   /_ _/\n                                                            \  /\n                                  present                    \/\n\n                   a door for AmiExpress v3.7 and higher:\n\n               >>> AquaCreateAcc v1.0 by Aquarius/Outlaws <<<\n\n\n                          Copyright ©1994 Aquarius\n\n                 Permission is granted to freely distribute\n               this product for non-commercial purposes only,\n                  as long as all files remain unmodified.\n\n\n\nArchive (OTL-CA10.LHA) Contents\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nDoors/AquaCreateAcc/\n   AquaCreateAcc            15556 bytes   The door.\n   AquaCreateAcc.doc         7944 bytes   This document.\n   AquaCreateAcc.info         842 bytes   A sample config icon.\n\nCommands/BBSCmd/\n   create.info               1291 bytes   Command icon.\n\n\nIntroduction\n~~~~~~~~~~~~\nHave you ever wanted to create a new account on your board without logging\nin as new user or searching for an inactive account to use? Then this is\nthe tool for you! It appends a new account to your User.Data. (User.Keys\nand User.Misc will also be updated.) You can decide the name of the\naccount, the location, password, access level, conference access (area\nname), conference to auto-rejoin, ratio, ratio type, byte limit, time\nlimit and chat limit. There are presets for everything (except the user\nname).\n\nAs a security measure, you are not allowed to create an account with\nhigher access level than you have yourself.\n\nThis door does not support conference accounting. If you use that, you\nhave to check all conference data manually when you have created an\naccount. If I get enough requests I might fix this for later versions.\n\n\nRequirements\n~~~~~~~~~~~~\n- An Amiga with OS 2.0 or higher.\n\n- AmiExpress 3.7 or higher, at least(!) up to 4.6. Why it doesn''t work on\n  earlier versions than 3.7 is because it encrypts the password!\n\n\nInstallation\n~~~~~~~~~~~~\nCopy the ''AquaCreateAcc'' directory from the archive to Doors:, and put the\nprovided command icon in your BBSCmd drawer. Now you must configure the\ndoor...\n\n\nTooltypes in Doors:AquaCreateAcc/AquaCreateAcc.info:\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n-  ---  ------ ---------- -------------------------------- ------ ---  --\nTemplate: INITMISC_PATH=<path>\nExample : INITMISC_PATH=BBS:InitMisc\n\nIMPORTANT!!\nIf your AmiExpress version uses a file called User.Misc then you MUST USE\nthis tooltype! Enter the path to the InitMisc utility that came with the\nAmiExpress package. If your AmiExpress version doesn''t use any User.Misc\nfile (all 3.x versions) then you MUST REMOVE this tooltype (by putting\nparentheses around it).\n\n-  ---  ------ ---------- -------------------------------- ------ ---  --\nTemplate: USERDATA_PATH=<path>\nExample : USERDATA_PATH=BBS:User.Data\n\nThis tooltype specifies where your User.Data file is located.\n\n-  ---  ------ ---------- -------------------------------- ------ ---  --\nTemplate: USERKEYS_PATH=<path>\nExample : USERKEYS_PATH=BBS:User.Keys\n\nThis tooltype specifies where your User.Keys file is located.\n\n-  ---  ------ ---------- -------------------------------- ------ ---  --\nTemplate: USERMISC_PATH=<path>\nExample : USERMISC_PATH=BBS:User.Misc\n\nThis tooltype specifies where your User.Misc file is located. It is only\nused if the tooltype INITMISC_PATH also is present.\n\n-  ---  ------ ---------- -------------------------------- ------ ---  --\nTemplate: PRESET.LOCATION=<string>\nExample : PRESET.LOCATION=- Created Account -\n\nThis tooltype specifies the default location for new accounts.\n\n-  ---  ------ ---------- -------------------------------- ------ ---  --\nTemplate: PRESET.PASSWORD=<string>\nExample : PRESET.PASSWORD=NEWUSER\n\nThis tooltype specifies the default password.\n\n-  ---  ------ ---------- -------------------------------- ------ ---  --\nTemplate: PRESET.ACCESS=<number>\nExample : PRESET.ACCESS=100\n\nThis tooltype specifies the default access level.\n\n-  ---  ------ ---------- -------------------------------- ------ ---  --\nTemplate: PRESET.AREA=<area name>\nExample : PRESET.AREA=Elite\n\nThis tooltype specifies the default conference access (area name).\n\n-  ---  ------ ---------- -------------------------------- ------ ---  --\nTemplate: PRESET.CONF_REJOIN=<conference number>\nExample : PRESET.CONF_REJOIN=1\n\nThis tooltype specifies the default conference for the new user to\nauto-rejoin.\n\n-  ---  ------ ---------- -------------------------------- ------ ---  --\nTemplate: PRESET.RATIO=<number>\nExample : PRESET.RATIO=3\n\nThis tooltype specifies the default ratio. 0 = disabled ratio.\n\n-  ---  ------ ---------- -------------------------------- ------ ---  --\nTemplate: PRESET.RATIO_TYPE=(0|1|2)\nExample : PRESET.RATIO_TYPE=1\n\nThis tooltypes specifies the default ratio type.\n\n0 = Byte ratio\n1 = Byte/File ratio\n2 = File ratio\n\n-  ---  ------ ---------- -------------------------------- ------ ---  --\nTemplate: PRESET.BYTE_LIMIT=<number of bytes>\nExample : PRESET.BYTE_LIMIT=10000000\n\nThis tooltypes specifies the default daily byte limit.\n\n-  ---  ------ ---------- -------------------------------- ------ ---  --\nTemplate: PRESET.TIME_LIMIT=<number of minutes>\nExample : PRESET.TIME_LIMIT=83\n\nThis tooltypes specifies the default daily time limit in minutes.\n\n-  ---  ------ ---------- -------------------------------- ------ ---  --\nTemplate: PRESET.CHAT_LIMIT=<number of minutes>\nExample : PRESET.CHAT_LIMIT=30\n\nThis tooltypes specifies the default multi-node chat limit in minutes.\n\n-  ---  ------ ---------- -------------------------------- ------ ---  --\n\n\nContact Me!\n~~~~~~~~~~~\nIf you have any cool ideas for improvement of this door, questions, bug\nreports or whatever, leave me a message on one of the following boards:\n\nNIGHTFALL ................ Whoosh ............ +46-90-120369  <---  Safest\nHALL OF FAME ............. Dansken ........... +46-910-26665      place to\nHYSTERIA ................. JAC ............... +46-21-842939     reach me!\nMASTURBATION STATION ..... Black Beard ....... +1-305-552-1192\nZION''S HIDEOUT ........... Zion .............. +1-614-876-0807\nDARK TOWER ............... Shadower .......... +1-801-476-9068\nMORTUARY ................. Bloodwolf ......... +1-312-284-7577\nBOONDOCKS ................ Sal-One! .......... +31-548-040-653\n\n\nHistory\n~~~~~~~\n1.0  (09-17-94) First release version.\n\n\nGreetings\n~~~~~~~~~\n                Greetings must go to (in no special order):\n\n           - Vegas/OTL - Biscrok/OTL - Toxic/OTL - AtomiX!/OTL -\n       - Whoosh/OTT^KRL^OTL^CLS - Snake/OTL - Nashua/OTL - SMS/OTL -\n    - Genghis Khan/OTL - The Other OTL Members! - Dansken - CornFlake -\n  - Ace Caze/Obscene - Firehawk! - fanta/THR - Static/THR - FAX! - Juan -\n - Psychopath - Danzig - Foss - Karma - Seagull - Marwin - CaT - Sal-One -\n - Metalbasher - No Limit - BoneIdle - Wilsom/Obscene - Stab - Kid Curry -\n - Chig/TDS - HardHack - Rize - Frosty - JAC/TDS - C/\TE¥E - AXL - Norad -\n - Crocodile - Freddy Kreuger/GOD - Doc Whoo - Zion! - Nocturne - Brutus -\n  - FireFlash/OTT - MDR/OTT - Neutralizer/OTT - Bytehunter/OTT - Remix! -\n    - WarDancer - Json/Kingdom - Slobo & Whale - [-HSR & MM-] - HiFly -\n      - Uffe - Gi Joe - Princip - The Silencer - Ezco - Vampire/PDY -\n          - Nero - Deltaforce! - Afterlife - The Ones I Forgot! -\n\n\n                    Thanks for the help with this door:\n\n                          - Whoosh (Nightfall) -\n                     - Rize & Frosty (Another World) -\n                         - Dansken (Hall of Fame) -\n                            - AXL (Disneyland) -\n\n\n[EOF]\n','\n',char(10)),'{"LOCATION":"<string>","ACCESS":"<number>","TYPE":"(0|1|2)"}',NULL,30645,4,0,NULL,NULL,'otl_ca10_aquacreateacc','scan',1780048664);
INSERT INTO door_catalog VALUES('otl_cr10','OTL-CR10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OTL-CR10.LHA','ConfReplace','XIM','ConfReplace',NULL,'Aquarius','OTL','_____  __  / __   __  /_____  \__/ /   ____ :/  /  /  /  //  //  /__/  ¬  / / / /\_  \:: /  /  /  /  //  //  /  / _/  / / / /  /  /::',replace('_ _/\____/\_ ___/\__/\_ __/\__ _/\____/\__ _\n_____  __  / __   __  /_____  \__/ /   ____\n:/  /  /  /  //  //  /__/  ¬  / / / /\_  \::\n/  /  /  /  //  //  /  / _/  / / / /  /  /::\n\__  /\__  //  //___  /__\  /\__  /___  /:::\nbIS\/====\/==\/=====\/====\/====\/====\/===>\n  ConfReplace v1.0 by Aquarius of Outlaws\n','\n',char(10)),'ConfReplace.doc',replace('_ _________________:_ __ ___ ___________________ ___ __ _:________________ _\n                   |                                     |\n      ______________  ___________________________  ___  _______________\n      \__________   \/   /   /  ____/  /\______  \/  /\/  /  _________/\n       \____/   /   /   /   /  /\__/  / /\_/  /  /  / /  /      \____/\n           /   /   /   /   /  / / /  / /  /     /  /\/  /\___   /\\n          /   /   /   /   /  / / /  /_/__/  /  /       /       / /\n          \______/\______/  / / /_______/__/  /\______/_______/ /\n           \_____\/\____/__/ /  \_______\_/__/ /\_____\_______\/\n                        \__\/             \__\/                        -ToX-\n_ _________________|_ __ ___ ___________________ ___ __ _|________________ _\n                   :                                     :\n                                   present\n\n                             an AmiExpress tool:\n\n                 >>> ConfReplace v1.0 by Aquarius/Outlaws <<<\n\n\n                          Copyright ©1993 Aquarius\n\n                 Permission is granted to freely distribute\n               this product for non-commercial purposes only,\n                  as long as all files remain unmodified.\n\n\nArchive (OTL-CR10.LHA) contents\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nConfReplace            5256 bytes       The executable file.\nConfReplace.doc        3743 bytes       This document file!\n\n\nDescription\n~~~~~~~~~~~\nThis is a simple CLI command that searches a user.data file and replaces all\noccurences of a given conference access string with another. It could be very\nuseful if you for example are switching from AmiExpress 2.xx to 3.xx and are\ngoing to have more than 9 conferences. Then it''s not so suitable to still use\nthose X and _ strings. And just imagine the work editing all your users''\naccounts manually...\n\n\nUsage\n~~~~~\nThe command line syntax is as follows:\n\nConfReplace <user.data file> <old access string> <new access string>\n\n\nExamples:\n  ConfReplace bbs:user.data X_XXX_X__ Normal\n                                          ; typical 2.xx -> 3.xx conversion\n\n  ConfReplace bbs:user.data Lamer "Beta man"\n                                          ; use quotes if more than one word\n\n  ConfReplace bbs:user.data XX_X_____ XX_XX____\n                                          ; a new conference perhaps\n\n\nContact me!\n~~~~~~~~~~~\nIf you have any cool ideas for improvement of this tool, leave me a message on\none of the following boards:\n\nNiGHTFALL ............... Prof Do Right ..... +46-90-120369\nOVERLOAD (Outlaws SHQ) .. Vegas ............. +46-8-54063666\nHYSTERiA ................ JAC ............... +46-21-842939\niNSiDE OUT .............. C/\TE¥E ........... +46-346-58697\nTRADERS NATiON .......... RaJ-Ban ........... +46-176-55202\n\nYou can also mail me through AmiXnet (@SWE001) in the ChatterBox or AmiXnet\nInfo conference.\n\nIf you want to be sure to have a copy free of hacks and "backdoors", call the\nboards above or any Outlaws HQ and download the archive from there. If you\ndon''t, at least make a backup of your user.data before using the tool for the\nfirst time.\n\n\nGreetings\n~~~~~~~~~\nT             All members of Outlaws,\n O           Prof Do Right/Classic,\n  :         Lightspeed/Obscene,\n           Freddy Kreuger/GOD,\n          C/\TE¥E/Taurus,\n         JAC/ADDONIC,\n        Blade/Triad,\n       Zune/HCD,\n      Seagull,\n     AXL/ASH,\n    RaJ-Ban,\n   Nojje,\n  Saxon,\n Chig,\nNero\n\n + all the folks I forgot!\n\n\nDisclaimer\n~~~~~~~~~~\nNo responsibility is taken by the author for what effect this program might\nhave on your system.\n\n\nHistory\n~~~~~~~\n1.0  (1993-12-30) Initial release\n\n\n\nThat''s all for now. See ya in my next release!\n\n                                                   - Aquarius/OTL\n','\n',char(10)),NULL,'auto-added',10177,8,0,NULL,NULL,'otl_cr10','scan',1780048664);
INSERT INTO door_catalog VALUES('otl_dy15','OTL-DY15.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OTL-DY15.LHA','Dynamite','XIM','Dynamite',NULL,'Modem','OTL','____ \  / /\__  __/  \  / /\__ \ \/  \ _/ /\ \/ / /\/ / / /\ \/ / / /\/ / /\ \ / / / / / / / / /  \/ / / / / / /\   \/\',replace('_____    ____________    __    __  __       \n____ \  / /\__  __/  \  / /\__ \ \/  \      \n_/ /\ \/ / /\/ / / /\ \/ / / /\/ / /\ \     \n/ / / / / / / / /  \/ / / / / / /\   \/\    \n\ \/ /\ \/ / / /_/\  /\ \/  \/ /\ \/ / /    \n \__/ /\__/_/\____/_/ /\__/\__/ /\__/ /     \n  \_\HMN\_\_\/\___\_\/  \_\/\_\/  \_PRESENTS\n   Dynamite V1.5 (Update) By Modem Boy/oTL  \nTHE FASTEST LhA/LZh CHECKER-STRIPPER-ADDER!!\n Minor BUG fixed and new option added! Now  \n   can open a File-Requester. Useful for    \n                 CLI usage!                 \n','\n',char(10)),'Dynamite.Doc',replace('      ____      ___ ______________   ____      ___   ___      ____    \n     /\_  \    /  /\\  __   ___  /\ /\_  \    /  /\  \  \    /\_  \   \n    /  /\  \  /  / /_\/ /  /  /\/ //  /\  \  /  /_/___\  \  /  /\  \  \n   /  / /\  \/  / /\  \/  /  / /\//  / /\  \/  / \   /\\  \/  / /\__\ \n  /  / / /  /  / / /  /  /  / /  /  /_/_/  /  / //  / //  /  /_/__\__\\n /  / / /  /  / / /  /  /  / /__/  ____   /  / //  / //  /\_____   /\ \n \  \/ /  /\  \/ /  /  /  / /  /  / / /  /\  \//  / //  / /__  /  / / \n  \  \/  / /\  \/  /  /\  \/  /  / / /  / /\  /  /_//  / /\  \/  / /  \n   \/___/ /  \/___/__/ /\____/__/ / /__/ /  \/__/_____/ /  \/___/ /   \n    \___\/    \______\/  \___\__\/  \__\/    \________\/HMN \___\/    \n\n                            P·R·E·S·E·N·T·S\n\n                >>  Dynamite V1.5 by Modem Boy/oTL!  <<\n                       Asl.Library V38+ Required.\n\nIntroduction:\n~~~~~~~~~~~~~\nDynamite  is  a  fast and small (3704 bytes) LhA Checker-Stripper-Adder\nwritten in Amiga_E!!!\n\nThere is no big differences from other checkers, but Dynamite is one of\nthe fastest (or the faster???) around, so use it and have fun!\n\n\nBug Fixed:\n~~~~~~~~~~\nNow  you  can  process  a file in "Ram Disk:" or in any other directory\nthat haves one or more spaces in its name.\n\n\nOptions:\n~~~~~~~~\nThere is a ''-r'' option that allows you to open a file-requester, useful\nfor CLI usage!  Asl.Library V38+ is needed.\n\n\nAmi-Express Usage:\n~~~~~~~~~~~~~~~~~~\nMake  sure  that the files Dynamite.Strip & Dynamite.Add are in your s:\ndirectory  (otherwise  Dynamite  will  perform  only  an integrity test\nwithout  stripping  or  adding  anything!), then edit ''em with a normal\ntext editor.\n\nLhA  must  be  in your c:  directory (of coz!), or make it resident for\nmaximum speed and low memory usage (on multinodes systems).\n\n      Usage: resident c:LhA pure\n\n\nThe file "bbs:fcheck/lha.info" must have the following tool-types:\n\n------------------->cut here<--------------------\nCHECKER=C:DYNAMITE\nERROR.1=WARNING: Skipping corrupt/extraneous data\nERROR.2=Operation not entirely successful\nERROR.3=Failed\n------------------->cut here<--------------------\n\nBetter using the lha.info included in this archive, so there will be no\nchance of mistakes.\n\n\n-------------------------------[ NOTE ]--------------------------------\n\nDynamite  may  be  used  from  CLI and with any other BBS program (like\nCNet, Dialog...)!\n\n      CLI Usage: Dynamite [<options>] <filename>\n\n        Options:  -r = File-Requester (Multi-Selection is allowed!)\n\n-----------------------------------------------------------------------\n\n\nHistory:\n~~~~~~~~\nV1.0ß  -  Never released.\nV1.1ß  -  Fixed some bugs and optimized. Never released.\n\nV1.2   -  First Public Version.\n\nV1.3ß  -  Minor Bug fixed. -r option added. Never Released.\nV1.4ß  -  Added Multi-Selection (-r) and optimized. Never Released.\n\nV1.5   -  Second Public Version. 08-Jul-94.\n          Release Date: 10-Jul-94.\n\n\nDynamite  is  "Callware"...   if  you  use it, you must call my BBS and\nupload some nice warez ;)\n\n            DELTA CiTY / OUTLAWS & DELiGHT iHQ ++39-931-760203\n            ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n\nThat''s all folks!\n\n\n-EOF-\n\n','\n',char(10)),NULL,'auto-added',14711,4,0,NULL,NULL,'otl_dy15','scan',1780048664);
INSERT INTO door_catalog VALUES('otl_dy20','OTL-DY20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OTL-DY20.LHA','DYNAMITE','XIM','DYNAMITE',NULL,'Modem','OTL','/   \/  |  \  __  /  |_/   \  \/\/  /  ___/ /    \\  |  \\/  \/   / \_  \\     //\___  \ \_____/______/____\______/____\_/\_/\______/',replace('  ___  __.____________.  ______    ___._____\n /   \/  |  \  __  /  |_/   \  \/\/  /  ___/\n/    \\  |  \\/  \/   / \_  \\     //\___  \\n\_____/______/____\______/____\_/\_/\______/\n-+--------------( present: )-----------mk-+-\n   Dynamite V2.0 (Update) By Modem Boy/oTL  \n   THE BEST LHA/LZH CHECKER-STRIPPER-ADDER  \n      o Configurable via ToolTypes          \n      o File_Id Support                     \n      o 2 Differents Looks!                 \n      o Usable from CLI/WB and with any     \n        BBS prog (/X,CNet,Dialog...)        \n-+------------------------------15-Sep-94-+-\n','\n',char(10)),'Dynamite.Doc',replace('      ____      ___ ______________   ____      ___   ___      ____    \n     /\_  \    /  /\\  __   ___  /\ /\_  \    /  /\  \  \    /\_  \   \n    /  /\  \  /  / /_\/ /  /  /\/ //  /\  \  /  /_/___\  \  /  /\  \  \n   /  / /\  \/  / /\  \/  /  / /\//  / /\  \/  / \   /\\  \/  / /\__\ \n  /  / / /  /  / / /  /  /  / /  /  /_/_/  /  / //  / //  /  /_/__\__\\n /  / / /  /  / / /  /  /  / /__/  ____   /  / //  / //  /\_____   /\ \n \  \/ /  /\  \/ /  /  /  / /  /  / / /  /\  \//  / //  / /__  /  / / \n  \  \/  / /\  \/  /  /\  \/  /  / / /  / /\  /  /_//  / /\  \/  / /  \n   \/___/ /  \/___/__/ /\____/__/ / /__/ /  \/__/_____/ /  \/___/ /   \n    \___\/    \______\/  \___\__\/  \__\/    \________\/HMN \___\/    \n\n                            P·R·E·S·E·N·T·S\n\n                >>  Dynamite V2.0 by Modem Boy/oTL!  <<\n                       Asl.Library V38+ Required.\n\n\nIntroduction:\n~~~~~~~~~~~~~\nDynamite  is  a  fast and small (6948 bytes) LhA Checker-Stripper-Adder\nwritten in Amiga_E!!!\n\n\nFeatures:\n~~~~~~~~~\nConfigurable  via  ToolTypes,  possibility to switch ON/OFF any option,\nFile_Id support, uses ASL.Library to open a File-Requester, usable from\nCLI/WB and with any BBS program (/X,CNet,Dialog etc.  etc.)!\n\n\nOptions:\n~~~~~~~~\nThere is a "-r" option that allows you to open a File-Requester, useful\nfor CLI usage!  Asl.Library V38+ is needed.\n\nNOTE:  if the "REQ" ToolType is used the "-r" option will be ignored!\n\n\nAmi-Express Usage:\n~~~~~~~~~~~~~~~~~~\nMake  sure  that the files Dynamite.Strip & Dynamite.Add are in your s:\ndirectory  (otherwise  Dynamite  will  perform  only  an integrity test\nwithout  stripping  or  adding  anything!), then edit ''em with a normal\ntext editor.\n\nLhA  must  be  in your c:  directory (of coz!), or make it resident for\nmaximum speed and low memory usage (on multinodes systems).\n\n      Usage: resident c:LhA pure\n\n\nThe file "bbs:fcheck/lha.info" must have the following ToolTypes:\n\n------------------->cut here<--------------------\nCHECKER=C:DYNAMITE\nERROR.1=WARNING: Skipping corrupt/extraneous data\nERROR.2=Operation not entirely successful\n------------------->cut here<--------------------\n\nBetter using the lha.info included in this archive, so there will be no\nchance of mistakes.\n\nNOTE:   make  sure  that  the  "REQ" ToolType is not used, otherwise /X\ncan''t process the file(s)!!!\n\n\nToolTypes:\n~~~~~~~~~~\n           STRIP                - Strips useless files.\n             ADD                - Adds your own adverts.\n           CHECK                - Checks the archive integrity.\n          FILEID                - Displays the FILE_ID.DIZ.\n             REQ                - Automatically opens a File-Requester.\n         NEWLOOK                - Uses a New Look! :-)\n            PATH=<your path>    - Specify where all your LHA/LZH files\n                                - are (usually) stored.\n\n\n   >>    MAKE SURE THAT "Dynamite.info" IS IN THE SAME DIRECTORY    <<\n                 >>    WHERE "Dynamite" IS PLACED!    <<\n\n\nHistory:\n~~~~~~~~\nV1.0ß  -  Never released.\nV1.1ß  -  Fixed some bugs and optimized. Never released.\n\nV1.2   -  First Public Version.\n\nV1.3ß  -  Minor Bug fixed. -r option added. Never Released.\nV1.4ß  -  Added Multi-Selection (-r) and optimized. Never Released.\n\nV1.5   -  Second Public Version. 08-Jul-94.\n          Release Date: 10-Jul-94.\n\nV1.6ß  -  Never released.\nV1.7ß  -  Never released.\nV1.8ß  -  Never released.\nV1.9ß  -  Many new features added and optimized. Now It''s Icon-Based.\n          Never released.\n\nV2.0   -  3rd Public Version. 31-Aug-94.\n          Release Date: 15-Sep-94.\n\n\nDynamite  is  "Callware"...   if  you  use it, you must call my BBS and\nupload some nice warez ;)\n\n              DELTA CiTY / OUTLAWS iHQ +39-931-760203\n              ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n\nThat''s all folks!\n\n\n-EOF-\n\n','\n',char(10)),NULL,'auto-added',14059,3,0,NULL,NULL,'otl_dy20','scan',1780048664);
INSERT INTO door_catalog VALUES('otl_fc10','OTL-FC10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OTL-FC10.LHA','FastCheck','XIM','FastCheck',NULL,'AtomiX','OTL','_____  __  / __   __  /_____  \__/ /   ____ :/  /  /  /  //  //  /__/  ¬  / / / /\_  \:: /  /  /  /  //  //  /  / _/  / / / /  /  /::',replace('_ _/\____/\_ ___/\__/\_ __/\__ _/\____/\__ _\n_____  __  / __   __  /_____  \__/ /   ____ \n:/  /  /  /  //  //  /__/  ¬  / / / /\_  \::\n/  /  /  /  //  //  /  / _/  / / / /  /  /::\n\__  /\__  //  //___  /__\  /\__  /___  /:::\nbIS\/====\/==\/=====\/====\/====\/====\/===>\n  Fast LHA Check V1.0 by AtomiX of Outlaws\n','\n',char(10)),'FastCheck.doc',replace('\n       _ _ ___/\______/\__ ____/\___/\__ _ _/\____ _/\_ __ __/\______\n      __ ________   __   /   _   ___   / ______   \___/__/     _____/\n         bIS/   /   /   /   //   //   /___/ __¬   /  /  /  /\__   \\n           /   /   /   /   //   //   /   /  \    /  /  /  /   /   /\n    __  _ _\____  /\____  //_  //_____  /___/\  /\_____  /\ _/   /___\n     _  ___ _   \/  _  _\/_  \/____ __\/ ___ _\/_______\/____   /_ _/\n                                                            \  /\n                                    PRESENTS                 \/\n\n                        FastCheck V1.0 coded by AtomiX/Outlaws\n\n\nWHAT''S THE USE OF THIS TOOL ?\n-----------------------------\n\n        This is a nice LHA Checker for AmiExpress or \n        S-Express or simply for the DoS on ThE Amiga\n\n		  You are able to Strip''n Add and Test LHA Archives\n        via Scripts . The Checker is fully Configurable\n\n        OrginalFileLength:  FastCheck 6992 bytes\n\nHISTORY :\n---------\n\n	V1.0ß - Never Released just for fun ;))\n\n         - Added Icon Support it''s now fully Icon Configurable\n           \n         - New Tooltype added for Low Memory Systems\n           Last bugs fixed..\n         \n   V1.0  - First official Release after 2 months beta testing\n\n\nHOW TO INSTALL :\n----------------\n\n		  Copy all Drawers to your Path where you ever Like it\n        it must not be Specify you can Copy FastCheck to C:\n        or S: ,it''s not intresting where it is located\n\n        ToolTypes:\n        ---------\n			LHA_LOCATION=C:LHA       < Location for your LHA Packer>\n                                  < if not ? C:LHA is Default   >\n			WORK_DIR=T:              < Path where you want to Check>\n                                  < &add the Temponary LHA File >\n                                  < for People with a lot of    >\n                                  < memory (gelle Rüdiger)      >\n         REMOVE=ON / OFF          < Write ON if you want to Rem.>\n                                  < BBS Adverts                 >\n         ADVERTS=ON / OFF         < ON if you want to Add BBS Adds >\n         TEST=ON / OFF            < "  "  "    "   "  Check Files  >\n\n\n\n        So that''s all i you have a Problem with my Door/s then leave me\n        a mail or call me.\n\n        iF YoU FoUnD BuGS or have Suggestion''s let me know on AmiXnet\n\n			@GR0003\n			@GR0004\n\n        ____________________________________________________________________\n        ::AtomiX::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::\n        ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬\n\n     _____  _____  _____  _____  _____       __     ___  _____  _____\n    /\    \/\   \\/\    \/\    \/\    \     /\ \   /\  \/\    \/\    \\n.__/  \____\ \___\\ \____\ \____\ \____\   /  \_\ /  \__\ \____\ \____\\n| /   /¯   ¬\/   /¬\/ __ ¬\/ __ ¬\/    ¬\ /   / ¬\   /  ¬\/  _ ¬\/    ¬\\n|/   /o /___/o  /  /o/_/  /o  /  / _____//   /o  /  /o   /o  /  /o ----/\n|\  // /   //     //     //  /  /____  / \  //  /_\//   //  /  // ____/\n| \/___   /___/  /___/  /___   /___   /   \/___   /__  /___/  /___   /\n|    \/__/  \/__/  \/__/NL\/__/  \/__/       \/__/ \/_/   /__/  \/__/\n|                             |\n|  da cRew: AtomiX & No LiMit |    \n|           Flake , KiWi      |\n|_____________________________|    .__________________________________.\n·                             ·    |  NoDe1: +49-(sE)-cReT!!! <- DhST |\n                                   |  NoDe2: +49-(Pr)-iVAt!!! <-- LOC |\n                                   !__________________________________!\n                                   ·                                  ·\n                                                                      ·\n¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬\n\n','\n',char(10)),'{"LOCATION":"C:LHA"}','auto-added',48596,5,0,NULL,NULL,'otl_fc10','scan',1780048664);
INSERT INTO door_catalog VALUES('otl_fc11','OTL-FC11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OTL-FC11.LHA','FastCheck','XIM','FastCheck',NULL,'AtomiX','OTL','_____  __  / __   __  /_____  \__/ /   ____ :/  /  /  /  //  //  /__/  ¬  / / / /\_  \:: /  /  /  /  //  //  /  / _/  / / / /  /  /::',replace('_ _/\____/\_ ___/\__/\_ __/\__ _/\____/\__ _\n_____  __  / __   __  /_____  \__/ /   ____\n:/  /  /  /  //  //  /__/  ¬  / / / /\_  \::\n/  /  /  /  //  //  /  / _/  / / / /  /  /::\n\__  /\__  //  //___  /__\  /\__  /___  /:::\nbIS\/====\/==\/=====\/====\/====\/====\/===>\n  Fast LHA Check V1.1 by AtomiX of Outlaws\n   is a Checker , Wildcard Stripper & Adder\n    for AmiExpress & CLI .. fully Icon Confi\n     gurable with many Options written in\n      pure ''C'' for maximum Power\n       Requester & CLI/BBS Version Included\n','\n',char(10)),'FastCheck.doc',replace('\n       _ _ ___/\______/\__ ____/\___/\__ _ _/\____ _/\_ __ __/\______\n      __ ________   __   /   _   ___   / ______   \___/__/     _____/\n         bIS/   /   /   /   //   //   /___/ __¬   /  /  /  /\__   \\n           /   /   /   /   //   //   /   /  \    /  /  /  /   /   /\n    __  _ _\____  /\____  //_  //_____  /___/\  /\_____  /\ _/   /___\n     _  ___ _   \/  _  _\/_  \/____ __\/ ___ _\/_______\/____   /_ _/\n                                                            \  /\n                                    PRESENTS                 \/\n\n                        FastCheck V1.1 coded by AtomiX / Outlaws\n                        +Requester Version\n\nWHAT''S THE USE OF THIS TOOL ?\n-----------------------------\n\n        This is a nice LHA Checker for AmiExpress or \n        S-Express or simply for the DoS on ThE Amiga\n\n        You are able to Strip and Add and Test LHA Archives\n        with Scripts . The Checker is fully Configurable\n\n        Dont forget the .info File MUST exists\n\n        OrginalFileLength:    FastCheck 5508bytes   [BBS & CommandLine]\n        OrginalFileLength:Req-FastCheck 6260bytes   [Requester version]\n\n\nHISTORY :\n---------\n\n	V1.0ß - Never Released just for fun ;))\n\n         - Added Icon Support it''s now fully Icon Configurable.\n           \n         - New Tooltype added for Low Memory Systems.\n           Last bugs fixed..\n         \n   v1.0  - First official Release after 2 months beta testing.\n\n   v1.1  - Code Optimized (1.5KB shorter haha).\n           You can now Configure the Script Locations & Names.\n           Test Archives is changed to Default ON.\n           New Option Dont Show LHA Files (Optional)\n\n\nHOW TO INSTALL :\n----------------\n\n        Copy all Drawers to your Path where you ever Like it\n        it must not be Specify you can Copy FastCheck to C:\n        or S: ,it''s not intresting where it is located\n\n        ToolTypes:\n        ---------\n        LHA_LOCATION=C:LHA        * Location for your LHA Packer   *\n                                  * if not ? C:LHA is Default      *\n\n        WORK_DIR=T:               * Path where you want to Check   *\n                                  * &add the Temponary LHA File    *\n                                  * for People with a lot of       *\n                                  * memory (gelle Rüdiger)         *\n\n        REMOVE=ON / OFF           * Write ON if you want to Strip  *\n                                  * BBS Adverts from Archives      *\n\n        ADVERTS=ON / OFF          * ON if you want to Add BBS Adds *\n\n        TEST=ON / OFF             * "  "  "    "   "  Check Files  *\n                                  * Default is ON                  *\n\n        STRIP_SCRIPT=<Path&Name>  * Set the Path and Name from the *\n                                  * Strip Script,Default Dir&Name  *\n                                  * is "S:FastCheck.Strip"         *\n\n        ADD_SCRIPT=<Path&Name>    * Set the Path and Name from the *\n                                  * Add Script,Default Dir&Name is *\n                                  * S:FastCheck.add                *\n \n        DONT_DISPLAY              * When this Tooltype is set then *\n                                  * the LHA Files will not shown   *\n\n        _____________________________________________________________________\n        ::Requester Version::::::::::::::::::::::::::::::::::::::::::::::::::\n        ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n        The ReqTools.library is written and © by Niço Françes\n\n        You need the Library for the Requester Version of Fast-Lha-Check\n        no Extra docs needed because it have the same Functions as the\n        Normaly CLI & BBS Version.\n\n        You must start the Requester Version from the CLI (otherwise it\n        have no Output ;^)) i will change this little bug in one of the\n        Next Updates.\n\n        _____________________________________________________________________\n        :::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::\n        ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n        future of Fast LHA Check (BBS Version ONLY)\n\n        will add Current Upload Time , Node , Uploader Name & Location.\n        Script Checker wich checking for Double FileNames in the strip\n        script (already Finished but with some bugs).\n        Random File Adverts , that mean that you are able to change in time\n        your AdvertNames Automaticle NO LAME .DOCS or so REALY RANDOM.\n\n        _____________________________________________________________________\n        :::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::\n        ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n        So that''s all i you have a Problem with my Door/s then leave me\n        a mail or call me.\n\n        _____________________________________________________________________\n        :::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::\n        ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n        iF YoU FoUnD BuGS or have Suggestion''s let me know on AmiXnet\n\n			@GR0001\n                        @305003\n\n        _____________________________________________________________________\n        ::AtomiX:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::\n        ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n____/\___                __/\____          __/\                 __/\_____\n\__  _  ¬\      __/\____ \  __  ¬\         \   \       __/\____ \   ____/\\n \/. /___/\__/\ \  ___ ¬\/.  /   /\_____   /.  /\__/\_ \  __  ¬\/. __/__\/\n // /       /  \/. \_   //  /      _____) //  /  \   ¬\/.  /   //     /\\n/_____ /.  _   //  /   /______ /.___ ¬\_\/______ /.   //  /   /_____ / /\n\____\//  /   /___/__ /\_____\//      /\ \_____\//   /___/__ /\____\/ /\n     /___/__ /\___\_\/ / ·N£·/______ / /       /___ /\___\_\/ /     \/\n     \___\_\/ /      \/      \_____\/ /        \__\/ /      \/\n            \/                      \/             \/\n                  TH¡§ l¡Ne b®eaK§ THe ®µle§ ..\n     We HaVe THe laTe§T V¡®µ§ K¡lle®§ ØNl¡Ne .. AM¡XNeT Wø®ld W¡de\n      THe AM¡GA øNly ZøNe . ØµTlaW§ GHQ , Ge®MaN AM¡E×P®eSS Ð¡ST.\n \n     da ç®eW ¡§ , ATøM¡X / ØT£ , Nø £¡M¡T / QTX & I£§ , FlaKe / TR§I\n \n                     .---------------------------.\n                     |  Nøde ¹ : +49-57²³ 74³40  |\n                     |  Nøde ² : +49-I§ÐN-§ØØN   |\n                     |  Nøde ³ : +49-I§ÐN-§ØØN   |\n                     `---------------------------''\n','\n',char(10)),'{"LOCATION":"C:LHA"}','auto-added',21370,5,0,NULL,NULL,'otl_fc11','scan',1780048664);
INSERT INTO door_catalog VALUES('otl_flc','OTL-FLC.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OTL-FLC.LHA','FastCheck','XIM','FastCheck',NULL,'AtomiX','OTL','_____  __  / __   __  /_____  \__/ /   ____ :/  /  /  /  //  //  /__/  ¬  / / / /\_  \:: /  /  /  /  //  //  /  / _/  / / / /  /  /::',replace('_ _/\____/\_ ___/\__/\_ __/\__ _/\____/\__ _\n_____  __  / __   __  /_____  \__/ /   ____ \n:/  /  /  /  //  //  /__/  ¬  / / / /\_  \::\n/  /  /  /  //  //  /  / _/  / / / /  /  /::\n\__  /\__  //  //___  /__\  /\__  /___  /:::\nbIS\/====\/==\/=====\/====\/====\/====\/===>\n  Fast LHA Check V1.0 by AtomiX of Outlaws\n','\n',char(10)),'FastCheck.doc',replace('\n       _ _ ___/\______/\__ ____/\___/\__ _ _/\____ _/\_ __ __/\______\n      __ ________   __   /   _   ___   / ______   \___/__/     _____/\n         bIS/   /   /   /   //   //   /___/ __¬   /  /  /  /\__   \\n           /   /   /   /   //   //   /   /  \    /  /  /  /   /   /\n    __  _ _\____  /\____  //_  //_____  /___/\  /\_____  /\ _/   /___\n     _  ___ _   \/  _  _\/_  \/____ __\/ ___ _\/_______\/____   /_ _/\n                                                            \  /\n                                    PRESENTS                 \/\n\n                        FastCheck V1.0 coded by AtomiX/Outlaws\n\n\nWHAT''S THE USE OF THIS TOOL ?\n-----------------------------\n\n        This is a nice LHA Checker for AmiExpress or \n        S-Express or simply for the DoS on ThE Amiga\n\n		  You are able to Strip''n Add and Test LHA Archives\n        via Scripts . The Checker is fully Configurable\n\n        OrginalFileLength:  FastCheck 6992 bytes\n\nHISTORY :\n---------\n\n	V1.0ß - Never Released just for fun ;))\n\n         - Added Icon Support it''s now fully Icon Configurable\n           \n         - New Tooltype added for Low Memory Systems\n           Last bugs fixed..\n         \n   V1.0  - First official Release after 2 months beta testing\n\n\nHOW TO INSTALL :\n----------------\n\n		  Copy all Drawers to your Path where you ever Like it\n        it must not be Specify you can Copy FastCheck to C:\n        or S: ,it''s not intresting where it is located\n\n        ToolTypes:\n        ---------\n			LHA_LOCATION=C:LHA       < Location for your LHA Packer>\n                                  < if not ? C:LHA is Default   >\n			WORK_DIR=T:              < Path where you want to Check>\n                                  < &add the Temponary LHA File >\n                                  < for People with a lot of    >\n                                  < memory (gelle Rüdiger)      >\n         REMOVE=ON / OFF          < Write ON if you want to Rem.>\n                                  < BBS Adverts                 >\n         ADVERTS=ON / OFF         < ON if you want to Add BBS Adds >\n         TEST=ON / OFF            < "  "  "    "   "  Check Files  >\n\n\n\n        So that''s all i you have a Problem with my Door/s then leave me\n        a mail or call me.\n\n        iF YoU FoUnD BuGS or have Suggestion''s let me know on AmiXnet\n\n			@GR0003\n			@GR0004\n\n        ____________________________________________________________________\n        ::AtomiX::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::\n        ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬\n\n     _____  _____  _____  _____  _____       __     ___  _____  _____\n    /\    \/\   \\/\    \/\    \/\    \     /\ \   /\  \/\    \/\    \\n.__/  \____\ \___\\ \____\ \____\ \____\   /  \_\ /  \__\ \____\ \____\\n| /   /¯   ¬\/   /¬\/ __ ¬\/ __ ¬\/    ¬\ /   / ¬\   /  ¬\/  _ ¬\/    ¬\\n|/   /o /___/o  /  /o/_/  /o  /  / _____//   /o  /  /o   /o  /  /o ----/\n|\  // /   //     //     //  /  /____  / \  //  /_\//   //  /  // ____/\n| \/___   /___/  /___/  /___   /___   /   \/___   /__  /___/  /___   /\n|    \/__/  \/__/  \/__/NL\/__/  \/__/       \/__/ \/_/   /__/  \/__/\n|                             |\n|  da cRew: AtomiX & No LiMit |    \n|           Flake , KiWi      |\n|_____________________________|    .__________________________________.\n·                             ·    |  NoDe1: +49-(sE)-cReT!!! <- DhST |\n                                   |  NoDe2: +49-(Pr)-iVAt!!! <-- LOC |\n                                   !__________________________________!\n                                   ·                                  ·\n                                                                      ·\n¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬\n\n','\n',char(10)),'{"LOCATION":"C:LHA"}','auto-added',45982,3,0,NULL,NULL,'otl_flc','scan',1780048664);
INSERT INTO door_catalog VALUES('otl_jc12','OTL-JC12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OTL-JC12.LHA',NULL,'XIM','JoyComment.xim',NULL,'AtomiX','OTL','/ _  /  / /_   _/  /\ /___ /\/\/\/ ___/\ /  / /  / / /  //  /_// \_ / / / /__  /\/ /____/____/ /__//_____/__/_/_____/____/ /',replace('    ___________________ NL_____      _____\n   / _  /  / /_   _/  /\ /___ /\/\/\/ ___/\\n  /  / /  / / /  //  /_// \_ / / / /__  /\/\n /____/____/ /__//_____/__/_/_____/____/ /\n \____\____\/\__\\_____\__\_\_____\____\/\n   JoyComment V1.2 by AtomiX of Outlaws\n','\n',char(10)),'JoyComment.doc',replace('\n       _ _ ___/\______/\__ ____/\___/\__ _ _/\____ _/\_ __ __/\______\n      __ ________   __   /   _   ___   / ______   \___/__/     _____/\n         bIS/   /   /   /   //   //   /___/ __¬   /  /  /  /\__   \\n           /   /   /   /   //   //   /   /  \    /  /  /  /   /   /\n    __  _ _\____  /\____  //_  //_____  /___/\  /\_____  /\ _/   /___\n     _  ___ _   \/  _  _\/_  \/____ __\/ ___ _\/_______\/____   /_ _/\n                                                            \  /\n                                     PRESENTS                \/\n\n                     JoyComment V1.2 coded by AtomiX/OTL\n\n\nWHAT''S THE USE OF THIS TOOL ?\n-----------------------------\n\n        This is a nice Comment-Door (hard to guess, eyh) !\n\n        You can specify Sysops and Comments via tooltypes,\n        you also can specify what access-level the cosysops\n        will be shown (so new users only see main-sysop) !\n\n\n        OrginalFileLength:  JoyComment/JoyComment.xim=16212 bytes\n\nHISTORY :\n---------\n\n        V1.0 -   First Release\n        V1.1 -   Optimized and writen a new Turbo Routine for faster\n                 Screen Output\n        V1.2 -   Turbo Routine rewritten ... Internal changes\n\n\nHOW TO INSTALL :\n----------------\n\n        This is a XIM Door !\n\n        Copy just all to the BBS i prepared it so that it is working\n        automatically ;^)) !\n\n\n        Configure the "DOORS:JOYCOMENNT/JoyComment.xim.info"\n\n        ToolTypes:\n        ---------\n\n        SYSOPS=               <Add the MAX Number of Sysops you want>\n        SYSOP.x=              <Here the Name of the Sys/CoSysop>\n        COMMENT.x=            <  "   " Comment of the " ">\n        MENU_LEVEL=           <  "   " Access Level which is allowed\n                                to view the Sysop Menu (Default is 20)>\n\n        So that''s all i you have a Problem with my Door/s then leave me\n        a mail or call me.\n\n        iF YoU FoUnD BuGS or have Suggestion''s let me know on AmiXnet\n\n	@GR0003\n	@GR0004\n\n        ____________________________________________________________________\n        ::AtomiX::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::\n        ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬\n\n     _____  _____  _____  _____  _____       __     ___  _____  _____\n    /\    \/\   \\/\    \/\    \/\    \     /\ \   /\  \/\    \/\    \\n.__/  \____\ \___\\ \____\ \____\ \____\   /  \_\ /  \__\ \____\ \____\\n| /   /¯   ¬\/   /¬\/ __ ¬\/ __ ¬\/    ¬\ /   / ¬\   /  ¬\/  _ ¬\/    ¬\\n|/   /o /___/o  /  /o/_/  /o  /  / _____//   /o  /  /o   /o  /  /o ----/\n|\  // /   //     //     //  /  /____  / \  //  /_\//   //  /  // ____/\n| \/___   /___/  /___/  /___   /___   /   \/___   /__  /___/  /___   /\n|    \/__/  \/__/  \/__/NL\/__/  \/__/       \/__/ \/_/   /__/  \/__/\n|                             |\n|  da cRew: AtomiX & No LiMit |    .__________________________________.\n|           Flake , KiWi      |    |                                  |\n|_____________________________|    |  NoDe0: +49-(sE)-cReT!!! <- DHST |\n·                             ·    |  NoDe1: +49-(sE)-cReT!!! <- SOON |\n                                   |  NoDe2: +49-(Pr)-iVAt!!! <-- LOC |\n                                   !__________________________________!\n                                   ·                                  ·\n                                                                      ·\n¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬\n\n','\n',char(10)),NULL,'auto-added',14366,2,0,NULL,NULL,'otl_jc12','scan',1780048664);
INSERT INTO door_catalog VALUES('otl_jc13','OTL-JC13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OTL-JC13.LHA',NULL,'XIM','JoyComment.xim',NULL,'AtomiX','OTL','_____  __  / __   __  /_____  \__/ /   ____ :/  /  /  /  //  //  /__/  ¬  / / / /\_  \:: /  /  /  /  //  //  /  / _/  / / / /  /  /::',replace('_ _/\____/\_ ___/\__/\_ __/\__ _/\____/\__ _\n_____  __  / __   __  /_____  \__/ /   ____ \n:/  /  /  /  //  //  /__/  ¬  / / / /\_  \::\n/  /  /  /  //  //  /  / _/  / / / /  /  /::\n\__  /\__  //  //___  /__\  /\__  /___  /:::\nbIS\/====\/==\/=====\/====\/====\/====\/===>\n   AtomComment V1.3 by AtomiX of Outlaws\n    a Multi Comment Door for /X2.x & /X3.x+\n     written in pure ''C'' for maximum Speed\n      Released Sun May 29 15:11:03 1994\n','\n',char(10)),'JoyComment.doc',replace('           ___________  _______________     ___________  ___________\n     :::::/  __   /  /\/  /__   ___/  /\:::/  __   /  /\/  /   ____/\:\n     ::::/  / /  /  / /  /\_/  /\_/  / /::/  / /  /  /\/  /   /\___\/:\n     :::/  / /  /  / /  / //  / //  / /::/  /\/  /  /  \ /__  \ \:::::\n     ::/   \/  /   \/  / //  / //  /_/__/  /\/  /  /    /\_/   \ \::::\n     :/_______/_______/ //__/ //_______/__/ /__/_______/_______/ /::::\n     :\______ \______ \/:\_ \/:\______ \_ \/\_ \______ \______ \/:::::\n     ::::::::\/::::::\/::::\/:::::::::\/:\/:::\/::::::\/::::::\/::ToX:\n                               PRESENTS                     \n\n                  JoyComment V1.3 coded by AtomiX/OTL\n\n\nWHAT''S THE USE OF THIS TOOL ?\n-----------------------------\n\n        This is a nice Comment-Door (hard to guess, eyh) !\n\n        You can specify Sysops and Comments via tooltypes,\n        you also can specify what access-level the cosysops\n        will be shown (so new users only see main-sysop)\n        you can select a Default Sysop when the User press only\n        Return the Comment will be written to the Default Sysop !\n\n\n        OrginalFileLength:  JoyComment/JoyComment.xim=13944 bytes\n\nHISTORY :\n---------\n\n        V1.0 -   First Release\n        V1.1 -   Optimized and writen a new Turbo Routine for faster\n                 Screen Output\n        V1.2 -   Turbo Routine rewritten ... Internal changes\n        V1.3ß-   New Tooltypes Added and little gramatic bug fixed\n                 New Design bar Added with current Time , Conference\n                 and Default Sysop.\n                 Code Optimized.\n\n\n*  =  New Options in this Version\n\n\nHOW TO INSTALL :\n----------------\n\n        This is a XIM Door !\n\n        Copy just all to the BBS i prepared it so that it is working\n        automatically ;^)) !\n\n\n        Configure the "DOORS:JOYCOMENNT/JoyComment.xim.info"\n\n        ToolTypes:\n        ---------\n\n        SYSOPS=               <Add the MAX Number of Sysops you want>\n\n        SYSOP.x=              <Here the Name of the Sys/CoSysop>\n\n        COMMENT.x=            <  "   " Comment of the " ">\n\n        MENU_LEVEL=           <  "   " Access Level which is allowed\n                              < to view the Sysop Menu (Default is 20)>\n\n*       SKIP_SYSOP_PRV        <To skip the Private Question by the    >\n                              <main Sysop                             >\n\n*       DEF_SYSOP=            <Number for Default Sysop (when pressing>\n                              <Return at the Prompt Line) must be     >\n                              <Configured with SYSOP.x                >\n\n        So that''s all i you have a Problem with my Door/s then leave me\n        a mail or call me.\n\n        iF YoU FoUnD BuGS or have Suggestion''s let me know on AmiXnet\n\n	@GR0003\n	@GR0004\n\n        ____________________________________________________________________\n        ::AtomiX::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::\n        ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬\n\n     _____  _____  _____  _____  _____       __     ___  _____  _____\n    /\    \/\   \\/\    \/\    \/\    \     /\ \   /\  \/\    \/\    \\n.__/  \____\ \___\\ \____\ \____\ \____\   /  \_\ /  \__\ \____\ \____\\n| /   /¯   ¬\/   /¬\/ __ ¬\/ __ ¬\/    ¬\ /   / ¬\   /  ¬\/  _ ¬\/    ¬\\n|/   /o /___/o  /  /o/_/  /o  /  / _____//   /o  /  /o   /o  /  /o ----/\n|\  // /   //     //     //  /  /____  / \  //  /_\//   //  /  // ____/\n| \/___   /___/  /___/  /___   /___   /   \/___   /__  /___/  /___   /\n|    \/__/  \/__/  \/__/NL\/__/  \/__/       \/__/ \/_/   /__/  \/__/\n|                             |\n|  da cRew: AtomiX & No LiMit |    .__________________________________.\n|           Flake , KiWi      |    |                                  |\n|_____________________________|    |  NoDe0: +49-(sE)-cReT!!! <- DHST |\n·                             ·    |  NoDe1: +49-(sE)-cReT!!! <- SOON |\n                                   |  NoDe2: +49-(Pr)-iVAt!!! <-- LOC |\n                                   !__________________________________!\n                                   ·                                  ·\n                                                                      ·\n¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬¬\n\n','\n',char(10)),NULL,'auto-added',31930,5,0,NULL,NULL,'otl_jc13','scan',1780048664);
INSERT INTO door_catalog VALUES('otl_lo10','OTL-LO10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OTL-LO10.LHA','Logoff','XIM','Logoff','1.0','Neptune','OTL','._________ ___ __ _/\______/  _/_ _/\__ ___. |               //____   __  ___/_/   /___ | | LOGOFF   v1.0  /   /   /   /   /   /   / |',replace('[-LOGOFF-]                  /\__    [-v1.0-]\n._________ ___ __ _/\______/  _/_ _/\__ ___.\n|               //____   __  ___/_/   /___ |\n| LOGOFF   v1.0  /   /   /   /   /   /   / |\n| [ RELEASE 1 ] _\___   /\___   /____   /__|\n|                _ ___ /__ ___ /_ ____ /__/|\n| A cool logoff      \/      \/ -bIS!\/    |\n| door that gives an prompt with timeout   |\n| when a user is about to logoff! UNIQUE!! |\n| Code by Neptune and Aquarius of Outlaws. |\n`------------------------------------------''\n·             _                   _         \n','\n',char(10)),'Logoff.doc',replace('\n                         .____.    .____.\n       ________._________|    |___ |    | ____________________________\n     ./   __   |    |    |  _____/_|    |_\____   |      /   |   ____/_.\n __  |     /   |    |    |   \     |    |    _    |     /    |\______  |  __\n-\/--|    /    |    |    |    \    |    |    /    |    /\    |    /    |--\/-\n-----|_________|_________|_________|____|_________|____/\____|_________|-p!--\n\n                            -  p r e s e n t s  -\n\n\n                          LOGOFF v1.00 [RELEASE 1]\n                         COPYRIGHT 1994-95, NEPTUNE\n\n\nIndex\n~~~~~\n  Contents of the archive\n  Introduction / Features\n  Requirements\n  Installation\n  Copyrights\n  Greetings / Personal hellos\n  File_id.diz\n  Bug reports, Suggestions & How to contact!\n\n\nContents of the archive\n~~~~~~~~~~~~~~~~~~~~~~~\n  BBS:Commands/BBSCmd/\n    G.info                  1020 bytes - Provided command icon for /X 3.x+.\n\n  BBS:Doors/Logoff/\n    Logoff                  4704 bytes - The door for any cpu.\n    Logoff.doc              3106 bytes - This documentation.\n\n\nIntroduction / Features\n~~~~~~~~~~~~~~~~~~~~~~~\n  This door is another production from outlaws/therion and it''s fully\n  programmed in c to accomplish some speed. This logoff door has timeout\n  (5 s), and direct commandline choice "G Y"..\n\n\nRequirements\n~~~~~~~~~~~~\n  - Amiexpress, S-Express or simular.\n\n\nInstallation\n~~~~~~~~~~~~\n  (CLI) : Copy Doors/Logoff to Doors:\n\n  2.x\n    (CLI) : Edit BBS:Commands/BBS.CMD\n      --- cut --- cut --- cut --- cut --- cut ---\n      *G         XM001Doors:Logoff/Logoff\n      --- cut --- cut --- cut --- cut --- cut ---\n\n  3.x, 4.x\n    (CLI) : Copy Commands/BBSCmd/G.info to BBS:Commands/BBSCmd/\n\n\nCopyrights\n~~~~~~~~~~\n  Permission is granted to freely distribute this product for non-commercial\n  purposes only, as long as all files remain unmodified. I take no charge\n  for the door but you could leave me a mail and tell me that you use it and\n  perhaps support my board.\n\n\nGreetings / Personal hellos\n~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n                Aquarius/Otl - Hijacker/Cls - Sandman/Flt\n            Dexter/Afl - Guardian/Ind - Juan/Trsi - Phase!/Frs\n         Kid Curry/Cls - Ezco/Dpl - Twister/Dcs? - Amigaspirit/Ind\n       B.B.King/Atm - Dalamar/Led - Nike/Crz - Whoosh/Otl - Nero/Pdx\n      Zcandaler/Ind - Karma/Acl? - Bobo/Mst - Vegas/Otl - Biscrok/Otl\n\n\nFile_id.diz\n~~~~~~~~~~~\n[-LOGOFF-]                  /\__    [-v1.0-]\n._________ ___ __ _/\______/  _/_ _/\__ ___.\n|               //____   __  ___/_/   /___ |\n| LOGOFF   v1.0  /   /   /   /   /   /   / |\n| [ RELEASE 1 ] _\___   /\___   /____   /__|\n|                _ ___ /__ ___ /_ ____ /__/|\n| A cool logoff      \/      \/ -bIS!\/    |\n| door that gives an prompt with timeout   |\n| when a user is about to logoff! UNIQUE!! |\n| Code by Neptune and Aquarius of Outlaws. |\n`------------------------------------------''\n\n\nBug reports, Suggestions & How to contact!\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n  If you have any suggestions or bug-reports please contact me on..\n\n                  ---  FROZEN ASSETS  +46-322-665225  ---\n\n','\n',char(10)),NULL,'auto-added',12586,6,0,NULL,NULL,'otl_lo10','scan',1780048664);
INSERT INTO door_catalog VALUES('otl_ls20','OTL-LS20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OTL-LS20.LHA',NULL,'XIM','ListSpeeder.000',NULL,'Aquarius','OTL','_____  __  / __   __  /_____  \__/ /   ____ :/  /  /  /  //  //  /__/  ¬  / / / /\_  \:: /  /  /  /  //  //  /  / _/  / / / /  /  /::',replace('_ _/\____/\_ ___/\__/\_ __/\__ _/\____/\__ _\n_____  __  / __   __  /_____  \__/ /   ____\n:/  /  /  /  //  //  /__/  ¬  / / / /\_  \::\n/  /  /  /  //  //  /  / _/  / / / /  /  /::\n\__  /\__  //  //___  /__\  /\__  /___  /:::\nbIS\/====\/==\/=====\/====\/====\/====\/===>\n  ListSpeeder v2.0 by Aquarius of Outlaws\n','\n',char(10)),'ListSpeeder.doc',replace('\n       _ _ ___/\______/\__ ____/\___/\__ _ _/\____ _/\_ __ __/\______\n      __ ________   __   /   _   ___   / ______   \___/__/     _____/\n         bIS/   /   /   /   //   //   /___/ __¬   /  /  /  /\__   \\n           /   /   /   /   //   //   /   /  \    /  /  /  /   /   /\n    __  _ _\____  /\____  //_  //_____  /___/\  /\_____  /\ _/   /___\n     _  ___ _   \/  _  _\/_  \/____ __\/ ___ _\/_______\/____   /_ _/\n                                                            \  /\n                                  present                    \/\n\n                      a door for AmiExpress 2.xx/3.xx:\n\n                >>> ListSpeeder v2.0 by Aquarius/Outlaws <<<\n\n\n                          Copyright ©1993 Aquarius\n\n                 Permission is granted to freely distribute\n               this product for non-commercial purposes only,\n                  as long as all files remain unmodified.\n\n\nArchive (OTL-LS20.LHA) contents\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nDoors/ListSpeeder/ListSpeeder.000   13072 bytes   All-processors version.\nDoors/ListSpeeder/ListSpeeder.020   13040 bytes   Optimized version for 020''s.\nDoors/ListSpeeder/ListSpeeder.doc    9381 bytes   This document file!\nDoors/ListSpeeder/ListSpeeder.info   1129 bytes   A sample configuration icon.\nDoors/ListSpeeder/NoPack.bat          278 bytes   A no-packer script.\nCommands/BBSCmd/fd.info              1281 bytes   Command icon for /X 3.xx.\n\n\nDescription\n~~~~~~~~~~~\nListSpeeder lets the user download the filelists in the current conference so\nthat he can check them offline.\n\n\nFeatures\n~~~~~~~~\n- Multi-node compatible!\n\n- AmiExpress 3.x compatible (reads NDIRS from an icon for those versions).\n\n- Lets the user select for which directories in the current conference he wants\n  to download the filelist(s).\n\n- *NEW*: The user can view filehelp.txt by typing ''?'' when selecting\n  directories.\n\n- *NEW*: The door accepts directories as arguments. For example, if the user\n  starts it with ''fd u'', the filelist for the upload directory will be sent.\n\n- It converts the filelists to PC/IBM text format on request (adds a Carriage\n  Return before each Line Feed), so that they will look fine to PC users as\n  well.\n\n- Time and date of filelist download is written at the top of the list as well\n  as board name, conference name and directory number.\n\n- The sysop can give the user up to 9 different packers to choose from.\n  Although ListSpeeder is made to CRUNCH the filelists, the user can choose\n  NOT to pack, with the help of a certain script, which is included.\n\n- Displays the name of the archive before sending it, so that the user can make\n  sure he doesn''t have a file with that name in the download path already.\n  *NEW*: The archive size is also displayed.\n\n- Gives free download for the list(s).\n\n\nRequirements\n~~~~~~~~~~~~\nIt requires AmigaDOS 2.0 or higher to run. Since it is made to gain time for\nthe user, the computer of the board should be rather fast, at least if the\nfilelists are big. A 68000 Amiga is probably too slow to have any use for this\ntool, but on 030s it should run fast enough.\n\nListSpeeder works for sure on AmiExpress 2.34 up to 3.19, but I think it will\nwork on ANY version. Please contact me if you encounter any problems.\n\n\nInstallation\n~~~~~~~~~~~~\nMake a directory in "Doors:" called "ListSpeeder". Then copy\n"ListSpeeder.info", "NoPack.bat", and the suitable version of ListSpeeder\n(depending on what CPU you have) to that directory. Rename the door (the\nexecutable) you copied as "ListSpeeder" (not required though).\n\nFor AmiExpress 2.xx, add a line to your BBS.CMD (or Customcommands).\nFor example:\n\n----Cut here------------------------------------\n*FD       XM050Doors:ListSpeeder/ListSpeeder\n----Cut here------------------------------------\n               ^^^^^^^^^^^^^^^^^^^^^- File name of the door with full path.\n            ^^^\n ^^^        Access required to use the door.\n The command that will invoke the door.\n\nFor AmiExpress 3.x, just copy "fd.info" to your "Commands/BBSCmd" drawer and\nedit its tooltypes if they don''t suit you.\n\n\nConfiguration\n~~~~~~~~~~~~~\nThe way to configure the door has changed from v1.2. An icon,\n"Doors:ListSpeeder/ListSpeeder.info" is now used instead of a text file.\n\nTooltypes:\n\nFILENAME=<name of archive>\n    This is the name of the filelist archive without suffix. I suggest you use\n    a name that contains the name of your board, or an abbreviation of it. For\n    example, the board Nightfall uses "NFLFLS" (Nightfall files). If you have\n    PC users on your board, make sure that the filename (without the suffix)\n    won''t be longer than 8 characters when the conference number has been added\n    to it, if you have that option turned on. This tooltype is optional. The\n    default archive name is "FILES".\n\nADDCONF\n    If this tooltype is present, the conference number will be added to the\n    filename.\n\nThe following tooltypes describe the packers that the users will be able to\nchoose between. You can at most specify 9 packers. If you don''t give any\npackers, LhA will be used (with the default options). In the following syntax,\n''x'' must be a positive number. For the first packer x is 1, for the next it''s\n2, and so on. Look at the supplied config icon for examples.\n\nPCK.x=<desc. of packer no. x>\n    Description (name and perhaps a comment) of the packer. The door doesn''t\n    care what''s here. The text will only be displayed to the users.\n\nCMD.x=<command for packer no. x>\n    Here you give ListSpeeder information about how to use the packer, how to\n    call it. Write "{d}" where the name of the destination file should be\n    inserted, and "{s}" for the source file. Turn off as much output as\n    possible for the packer. For LhA, "-q" accomplishes that. Nobody will see\n    the output from the packer anyway, and turning it off will probably make\n    the packer a bit faster.\n\nSUF.x=<file suffix for packer no. x>\n    Here you specify the suffix that you want archives made by that packer to\n    have.\n\nACT.x=<action desc. for packer no. x>\n    This is a *NEW* feature of v2.0. You can give your own description for the\n    "action" of the packer. When a user has chosen packer, something like this\n    will be displayed: "Preparing list for dir 1... Squeezing... OK!". This\n    tooltype determines what should be written in place of "Squeezing".\n    Suitable expressions to use: "Zipping", "Crunching", "Imploding",\n    "Shrinking", "Wait", "Hang on" etc...\n\n\nContact me!\n~~~~~~~~~~~\nIf you have any cool ideas for improvement of this door, bug reports or\nwhatever, leave me a message on one of the following boards:\n\nNIGHTFALL ............... Prof Do Right ..... +46-90-120369\nOVERLOAD (Outlaws SHQ) .. Vegas ............. +46-8-54063666\nHYSTERIA ................ JAC ............... +46-21-842939\nINSIDE OUT .............. C/\TE¥E ........... +46-346-58697\nTRADERS NATION .......... RaJ-Ban ........... +46-176-55202\n\nYou can also mail me through AmiXnet (@SWE001) in the ChatterBox or AmiXnet\nInfo conference.\n\n\nGreetings\n~~~~~~~~~\nGreetings to: All members of Outlaws! And all my other friends.\n\nSpecial greetings to:\n\nJAC/ADDONIC            <<< I want more great ideas from you!\nPROF DO RIGHT/CLASSIC <<< Greetz, my favourite sysop!\nCHIG/INDEPENDENT     <<< No more quiz?\nFREDDY KREUGER/GOD  <<< Thanx for the feedback!\nC/\TE¥E/TAURUS     <<< A big greeting to you mate!\nVEGAS/OUTLAWS     <<< I rule don''t I no you think you rule I know hmm we rule..\nBISCROK/OUTLAWS  <<< I just love your asciis! I want more!\nRAJ-BAN/INDY?   <<< Netmail rules!\n\n\nDisclaimer\n~~~~~~~~~~\nNo responsibility is taken by the author for what effect this program might\nhave on your system.\n\n\nHistory\n~~~~~~~\n0.1  Non-public version used at Nightfall and Disneyland.\n\n1.0  Added check for V36.\n\n     The door now displays the name of the file before sending it.\n\n     Config file with different packers. User can choose packer.\n\n1.1  Made it /X 3.x compatible by reading ndirs from the conf icon\n     for those versions (and higher).\n\n     Forgot to check that no more than 9 packers were read from the\n     config file. Now it says "Error reading config file!" if you have\n     more than 9 packers there.\n\n     Added a CR at the beginning of the file lists, if PC format was\n     selected, which makes the no-packer script work better with PC format.\n\n     Speeded up the "preparing" for non-PC format.\n\n1.2  (1993-08-04) First release version.\n\n     Removed some unnecessary parts of the code, which decreased the size of\n     the executable a little.\n\n     The packers no longer have to junk directory names, because ListSpeeder\n     now makes the work directory the current.\n\n2.0  (1993-12-30) Public release, the first for Outlaws.\n\n     The configuration file has been replaced with an icon and its tooltypes.\n\n     The word "Squeezing" in the previous versions can be freely configured\n     now - different expressions can be used for every packer.\n\n     The size of the archive is now displayed before transfer.\n\n     It can take directories as arguments, just like the ''f'' command. Well not\n     quite, more than one directory can be specified.\n\n     ''U'' and ''u'' are now supported as synonyms for the upload directory.\n\n     By typing a ''?'' when selecting dirs, the filehelp.txt will be displayed.\n\n\n\nThat''s all for now. See ya in my next release!\n\n                                                   - Aquarius/OTL\n','\n',char(10)),NULL,'auto-added',25133,3,0,NULL,NULL,'otl_ls20','scan',1780048664);
INSERT INTO door_catalog VALUES('otl_ls21','OTL-LS21.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OTL-LS21.LHA','Append','XIM','Append',NULL,'Aquarius','OTL','_____  __  / __   __  /_____  \__/ /   ____ :/  /  /  /  //  //  /__/  ¬  / / / /\_  \:: /  /  /  /  //  //  /  / _/  / / / /  /  /::',replace('_ _/\____/\_ ___/\__/\_ __/\__ _/\____/\__ _\n_____  __  / __   __  /_____  \__/ /   ____\n:/  /  /  /  //  //  /__/  ¬  / / / /\_  \::\n/  /  /  /  //  //  /  / _/  / / / /  /  /::\n\__  /\__  //  //___  /__\  /\__  /___  /:::\nbIS\/====\/==\/=====\/====\/====\/====\/===>\n  ListSpeeder v2.1 by Aquarius of Outlaws\n','\n',char(10)),'ListSpeeder.doc',replace('\n       _ _ ___/\______/\__ ____/\___/\__ _ _/\____ _/\_ __ __/\______\n      __ ________   __   /   _   ___   / ______   \___/__/     _____/\n         bIS/   /   /   /   //   //   /___/ __¬   /  /  /  /\__   \\n           /   /   /   /   //   //   /   /  \    /  /  /  /   /   /\n    __  _ _\____  /\____  //_  //_____  /___/\  /\_____  /\ _/   /___\n     _  ___ _   \/  _  _\/_  \/____ __\/ ___ _\/_______\/____   /_ _/\n                                                            \  /\n                                  present                    \/\n\n                      a door for AmiExpress 2.xx/3.xx:\n\n                >>> ListSpeeder v2.1 by Aquarius/Outlaws <<<\n\n\n                          Copyright ©1994 Aquarius\n\n                 Permission is granted to freely distribute\n               this product for non-commercial purposes only,\n                  as long as all files remain unmodified.\n\n\nArchive (OTL-LS21.LHA) contents\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nDoors/ListSpeeder/ListSpeeder.000   13296 bytes   All-processors version.\nDoors/ListSpeeder/ListSpeeder.020   13260 bytes   020/030/040 version.\nDoors/ListSpeeder/ListSpeeder.doc   10850 bytes   This document file!\nDoors/ListSpeeder/ListSpeeder.info   1200 bytes   A sample configuration icon.\nDoors/ListSpeeder/NoPack.bat          201 bytes   A no-packer script.\nCommands/BBSCmd/fd.info              1267 bytes   Command icon for /X 3.xx.\nC/Append                             5612 bytes   My Append command.\n\n\nDescription\n~~~~~~~~~~~\nListSpeeder lets the user download the filelists in the current conference so\nthat he can check them offline.\n\n\nFeatures\n~~~~~~~~\n- Multi-node compatible!\n\n- AmiExpress 3.x compatible (reads NDIRS from an icon for those versions).\n\n- Lets the user select for which directories in the current conference he wants\n  to download the filelist(s).\n\n- The user can view filehelp.txt by typing ''?'' when selecting directories.\n\n- The door accepts directories as arguments. For example, if the user starts\n  it with ''fd u'', the filelist for the upload directory will be sent.\n\n- It converts the filelists to PC/IBM text format on request (adds a Carriage\n  Return before each Line Feed), so that they will look fine to PC users as\n  well.\n\n- Time and date of filelist download is written at the top of the list as well\n  as board name, conference name and directory number.\n\n- The sysop can give the user up to 9 different packers to choose from.\n  Although ListSpeeder is made to CRUNCH the filelists, the user can choose\n  NOT to pack, with the help of a certain script, which is included. This\n  modularity offers many possibilities. For example, texts can be added to the\n  filelists, they can be encrypted, and so on.\n\n- Displays the name of the archive before sending it, so that the user can make\n  sure he doesn''t have a file with that name in the download path already.\n  The archive size is also displayed.\n\n- Gives free download for the list(s).\n\n\nRequirements\n~~~~~~~~~~~~\nListSpeeder requires AmigaDOS 2.0 or higher to run.\n\nIt works for sure on AmiExpress 2.20 up to 3.32, but I think it will work on\nANY version. Please contact me if you encounter any problems.\n\n\nInstallation\n~~~~~~~~~~~~\nMake a directory in ''Doors:'' called ''ListSpeeder''. Copy ''ListSpeeder.info'',\n''NoPack.bat'', and the suitable version of ListSpeeder (depending on what CPU\nyou have) to that directory. Rename the door (the executable) you copied as\n''ListSpeeder'' (not required though). Copy the ''Append'' command to ''C:''.\n\nFor AmiExpress 2.xx, add a line to your BBS.CMD (or Customcommands).\nFor example:\n\n----Cut here------------------------------------\n*FD       XM020Doors:ListSpeeder/ListSpeeder\n----Cut here------------------------------------\n               ^^^^^^^^^^^^^^^^^^^^^- File name of the door with full path.\n            ^^^\n ^^^        Access required to use the door.\n The command that will invoke the door.\n\nFor AmiExpress 3.x, just copy ''fd.info'' to your ''Commands/BBSCmd'' drawer and\nedit its tooltypes if they don''t suit you.\n\n\nConfiguration\n~~~~~~~~~~~~~\nThe way to configure the door changed from v1.2 to v2.0. An icon,\n''Doors:ListSpeeder/ListSpeeder.info'', is now used instead of a text file.\n\nTooltypes:\n\nFILENAME=<name of archive>\n    This is the name of the filelist archive without suffix. I suggest you use\n    a name that contains the name of your board, or an abbreviation of it. For\n    example, the board Nightfall uses "NFLFLS" (Nightfall files). If you have\n    PC users on your board, make sure that the filename (without the suffix)\n    won''t be longer than 8 characters when the conference number has been added\n    to it, if you have that option turned on. This tooltype is optional. The\n    default archive name is "FILES".\n\nADDCONF\n    If this tooltype is present, the conference number will be added to the\n    filename.\n\nThe following tooltypes describe the packers that the users will be able to\nchoose between. You can at most specify 9 packers. If you don''t give any\npackers, LhA will be used (with the default options). In the following syntax,\n''x'' must be a positive number. For the first packer x is 1, for the next it''s\n2, and so on. Look at the supplied config icon for examples.\n\nPCK.x=<desc. of packer no. x>\n    Description (name and perhaps a comment) of the packer. The door doesn''t\n    care what''s here. The text will only be displayed to the users.\n\nCMD.x=<command for packer no. x>\n    Here you give ListSpeeder information about how to use the packer, how to\n    call it. Write "{d}" where the name of the destination file should be\n    inserted, and "{s}" for the source file. *NEW* for version 2.1 is that\n    "{t}" will be replaced with a filename that can be used temporarily by the\n    the packer, and "{p}" will be replaced with "1" if PC text format was\n    selected, "0" otherwise. For example, this can be used in an ARexx script\n    to determine which textfile to add to the dir file. Turn off as much output\n    as possible for the packer. For LhA, "-q" accomplishes that. Nobody will\n    see the output from the packer anyway, and turning it off will probably\n    make the packer a bit faster.\n\nSUF.x=<file suffix for packer no. x>\n    Here you specify the suffix that you want archives made by that packer to\n    have.\n\nACT.x=<action desc. for packer no. x>\n    You can give your own description for the "action" of the packer. When a\n    user has chosen packer, something like this will be displayed: "Preparing\n    list for dir 1... Squeezing... OK!". This tooltype determines what should\n    be written in place of "Squeezing". Suitable expressions to use: "Zipping",\n    "Crunching", "Imploding", "Shrinking", "Wait", "Hang on" etc...\n\nADD.x=<command to use on the ready archive>\n    This is a *NEW* tooltype for version 2.1. It can be used to add a board ad\n    to the archive, for example. For the no-packer alternative you could write\n    a textadder here. Note that this command will only be run once, and that is\n    when all the filelists have been processed.\n\n\nThe Append command\n~~~~~~~~~~~~~~~~~~\nI wrote this CLI command to make the no-packer script faster and less memory-\ndemanding. It appends a file (its first argument) to another file (the second\nargument). Using the standard ''join'' command requires a temporary file to be\ncreated, copied back and deleted. I mean, instead of writing:\n\n    join {out} {in} TO {tmp}\n    copy {tmp} {out}\n    delete {tmp}\n\nyou can write:\n\n    Append {in} {out}\n\n\nContact me!\n~~~~~~~~~~~\nIf you have any cool ideas for improvement of this door, bug reports or\nwhatever, leave me a message on one of the following boards:\n\nNIGHTFALL ............... Prof Do Right ..... +46-90-120369\nOVERLOAD (Outlaws SHQ) .. Vegas ............. +46-8-54063666\nHYSTERIA ................ JAC ............... +46-21-842939\nINSIDE OUT .............. C/\TE¥E ........... +46-346-58697\nTRADERS NATION .......... RaJ-Ban ........... +46-176-55202\n\nYou can also mail me through AmiXnet (AQUARIUS@SWE001) in the ChatterBox or\nAmiXnet Info conference.\n\n\nGreetings\n~~~~~~~~~\nT            All members of Outlaws,\n O          Prof Do Right/Classic,\n  :        Lightspeed/Obscene,\n          Freddy Kreuger/GOD,\n         C/\TE¥E/Taurus,\n        JAC/ADDONIC,\n       Blade/Triad,\n      Zune/HCD,\n     Seagull,\n    AXL/ASH,\n   RaJ-Ban,\n  DANSKEN\n Marwin\nNojje\n\n + all the folks I forgot!\n\n\nHistory\n~~~~~~~\n0.1  Non-public version used at Nightfall and Disneyland.\n\n1.0  Added check for V36.\n\n     The door now displays the name of the file before sending it.\n\n     Config file with different packers. User can choose packer.\n\n1.1  Made it /X 3.x compatible by reading ndirs from the conf icon\n     for those versions (and higher).\n\n     Forgot to check that no more than 9 packers were read from the\n     config file. Now it says "Error reading config file!" if you have\n     more than 9 packers there.\n\n     Added a CR at the beginning of the file lists, if PC format was\n     selected, which makes the no-packer script work better with PC format.\n\n     Speeded up the "preparing" for non-PC format.\n\n1.2  (1993-08-04) First release version.\n\n     Removed some unnecessary parts of the code, which decreased the size of\n     the executable a little.\n\n     The packers no longer have to junk directory names, because ListSpeeder\n     now makes the work directory the current.\n\n2.0  (1993-12-30) Public release, the first for Outlaws.\n\n     The configuration file has been replaced with an icon and its tooltypes.\n\n     The word "Squeezing" in the previous versions can be freely configured\n     now - different expressions can be used for every packer.\n\n     The size of the archive is now displayed before transfer.\n\n     It can take directories as arguments, just like the ''f'' command. Well not\n     quite, more than one directory can be specified.\n\n     ''U'' and ''u'' are now supported as synonyms for the upload directory.\n\n     By typing a ''?'' when selecting dirs, the filehelp.txt will be displayed.\n\n2.1  (1994-01-16) Public release version. ''Append'' command included.\n\n     Version 2.0 caused a guru when the user lost carrier... Fixed!\n\n     New for the CMD.x tooltype command template: "{t}" gives a temporary\n     filename (which packer scripts can use for multinode compatability), "{p}"\n     yields 1 for PC format, 0 for normal.\n\n     New packer tooltype: ADD.x=. (Optional.) This specifies a command that\n     will be used on the ready archive. "{d}" in the command template means the\n     archives filename (the "destination"). "{t}" and "{p}" are also allowed\n     here. This can be used to add a board ad for example.\n\n     The no-packer script was changed to make use of my Append command.\n\n     Speeded up the "preparing" for non-PC format some more...\n\n\n\nThat''s all for now. See ya in my next release!\n\n                                                   - Aquarius/OTL\n','\n',char(10)),NULL,'auto-added',26704,2,0,NULL,NULL,'dd_tr112','scan',1780048664);
INSERT INTO door_catalog VALUES('otl_mc','OTL-MC.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OTL-MC.LHA','MComment','XIM','[-MULTICOMMENT-]            /\__    [--]','1.0','Neptune','OTL','._________ ___ __ _/\______/  _/_ _/\__ ___. |               //____   __  ___/_/   /___ | | MCOMMENT v1.0  /   /   /   /   /   /   / |',replace('[-MULTICOMMENT-]            /\__    [-v1.0-]\n._________ ___ __ _/\______/  _/_ _/\__ ___.\n|               //____   __  ___/_/   /___ |\n| MCOMMENT v1.0  /   /   /   /   /   /   / |\n| [ RELEASE 1 ] _\___   /\___   /____   /__|\n|                _ ___ /__ ___ /_ ____ /__/|\n| We are proud to    \/      \/ -bIS!\/    |\n| present the best multicomment door ever  |\n| made for any /X. This one features great |\n| design and cursor handling!, unl. users. |\n| Code by Neptune and Odyssey of Outlaws.  |\n`------------------------------------------''\n','\n',char(10)),'MComment.doc',replace('\n\n                         .____.    .____.\n       ________._________|    |___ |    | ____________________________\n     ./   __   |    |    |  _____/_|    |_\____   |      /   |   ____/_.\n __  |     /   |    |    |   \     |    |    _    |     /    |\______  |  __\n-\/--|    /    |    |    |    \    |    |    /    |    /\    |    /    |--\/-\n-----|_________|_________|_________|____|_________|____/\____|_________|-p!--\n\n                            -  p r e s e n t s  -\n\n\n                       MULTICOMMENT! v1.0 [RELEASE 1]\n                     COPYRIGHT 94-95, NEPTUNE & ODYSSEY\n\n\nIndex\n~~~~~\n  Contents of the archive\n  Introduction / Features\n  Requirements\n  Installation\n  Tooltypes (Configuration)\n  Copyrights\n  Greetings / Personal hellos\n  File_id.diz\n  Buggreports, Suggestions & How to contact!\n\n\nContents of the archive\n~~~~~~~~~~~~~~~~~~~~~~~\n  BBS:Commands/BBSCmd/\n    C.info                  1024 bytes - Provided command icon for /X 3.x+.\n\n  BBS:Doors/MComment/\n    MComment                8712 bytes - The door for any cpu.\n    MComment.info           1016 bytes - Sample configuration icon.\n    MComment.doc            5130 bytes - This documentation.\n\n\nIntroduction / Features\n~~~~~~~~~~~~~~~~~~~~~~~\n  This door is another production from outlaws/therion and it''s fully\n  programmed in c to accomplish some speed. The special features included:\n\n  * Extraordinary sexy.\n  * Arrow select.\n  * Header usage.\n  * How many users as you want!.\n  * Different users in selected conferences.\n  * Front names.\n  * Users says.\n  * Dirrect comment via the mainline ex. "c 1"\n\n\nRequirements\n~~~~~~~~~~~~\n  - Any amiga with os2.0+.\n  - Amiexpress, S-Express or simular.\n\n\nInstallation\n~~~~~~~~~~~~\n  (CLI) : Copy Doors/MComment to Doors:\n\n  2.x\n    (CLI) : Edit BBS:Commands/BBS.CMD\n      --- cut --- cut --- cut --- cut --- cut ---\n      *REQ       XM001Doors:MComment/MComment\n      --- cut --- cut --- cut --- cut --- cut ---\n\n  3.x, 4.x\n    (CLI) : Copy Commands/BBSCmd/C.info to BBS:Commands/BBSCmd/\n\n\nTooltypes (Configuration)\n~~~~~~~~~~~~~~~~~~~~~~~~~\n  This door configures by tooltypes in (Doors:MComment/MComment.x.info).\n  If you whoud like different users to be included in different confereces\n  just copy the *.info to a conf and rename if to "Commentcfg.info"..\n\n  ------------------------------------------------------------------------\n\n  Template: HEADER=<path:filename>\n  Example : HEADER=Doors:MComment/MComment.header\n\n  Header file to show at the top of the screen.\n\n  ------------------------------------------------------------------------\n\n  Template: USR.<nr>.REALNAME=<Username>\n  Example : USR.1.REALNAME=Neptune/Otl\n\n  REAL username (The username that the door will give the message to)!!\n\n  ------------------------------------------------------------------------\n\n  Template: USR.<nr>.FRONTNAME=<Username>\n  Example : USR.1.FRONTNAME=NEPTUNE/OUTLAWS\n\n  The name to show on the comment screen!\n\n  ------------------------------------------------------------------------\n\n  Template: USR.<nr>.USERCOMMENT=<Username> (Max. 48 chars)\n  Example : USR.1.USERCOMMENT=THE ALLMIGHTY AND YOUR SYSOP.\n\n  Usercomment that is shown on the screen next to the front-username.\n\n  ------------------------------------------------------------------------\n\n  Template: USR.<nr>.USERSAYS=<Comment> (Max. 54 chars)\n  Example : USR.1.USERSAYS=NICE, BUT DO LEAVE SOME OTHERS A MAIL TO!\n\n  You can choose if you''d like to include this one!.. if you dont it just\n  won''t be shown! Test and see how you''d like it!\n\n  ------------------------------------------------------------------------\n\n\nCopyrights\n~~~~~~~~~~\n  Permission is granted to freely distribute this product for non-commercial\n  purposes only, as long as all files remain unmodified. I take no charge\n  for the door but you could leave me a mail and tell me that you use it and\n  perhaps support my board.\n\n\nMega ultra hello to megaultramightyblastkillerboost.. (Greetings)\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n                Aquarius/Otl - Hijacker/Cls - Sandman/Flt\n            Dexter/Afl - Guardian/Ind - Juan/Trsi - Phase!/Frs\n         Kid Curry/Cls - Ezco/Dpl - Twister/Dcs? - AmigaSpirit/Ind\n       B.B.King/Atm - Dalamar/Led - Nike/Crz - Whoosh/Otl - Nero/Pdx\n      Zcandaler/Ind - Karma/Acl? - Bobo/Mst - Vegas/Otl - Biscrok/Otl\n\n\nFile_id.diz\n~~~~~~~~~~~\n[-MULTICOMMENT-]            /\__    [-v1.0-]\n._________ ___ __ _/\______/  _/_ _/\__ ___.\n|               //____   __  ___/_/   /___ |\n| MCOMMENT v1.0  /   /   /   /   /   /   / |\n| [ RELEASE 1 ] _\___   /\___   /____   /__|\n|                _ ___ /__ ___ /_ ____ /__/|\n| We are proud to    \/      \/ -bIS!\/    |\n| present the best multicomment door ever  |\n| made for any /X. This one features great |\n| design and cursor handling!, unl. users. |\n| Code by Neptune and Odyssey of Outlaws.  |\n`------------------------------------------''\n\n\nBug reports, Suggestions & How to contact!\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n  If you have any suggestions or bug-reports please contact us on..\n\n                  ---  FROZEN ASSETS  +46-322-665225  ---\n\n','\n',char(10)),NULL,NULL,13293,5,0,NULL,NULL,'otl_mc10_mcomment','scan',1780048664);
