INSERT INTO door_catalog VALUES('otl_tc10','OTL-TC10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OTL-TC10.LHA','AquaTopChatEnd','XIM','[-aQUAtOPcHAT -]        /\__[-aQUARIUS-]','1.0',NULL,'OTL','._________ ___ __ _/\______/  _/_ _/\__ ___. |               //____   __  ___/_/   /___ | | Measures the   /   /   /   /   /   /   / |',replace('[-aQUAtOPcHAT v1.0-]        /\__[-aQUARIUS-]\n._________ ___ __ _/\______/  _/_ _/\__ ___.\n|               //____   __  ___/_/   /___ |\n| Measures the   /   /   /   /   /   /   / |\n| sysop-user    _\___   /\___   /____   /__|\n| chats and      _ ___ /__ ___ /_ ____ /__/|\n| creates a nice     \/      \/ -bIS!\/    |\n| bulletin with the longest chats.         |\n`------------------------------------------''\n','\n',char(10)),'AquaTopChat.guide',replace('@database AquaTopChat\n@author Aquarius/Outlaws\n@$VER: AquaTopChat.guide 1.0 (28.1.95)\n\n@node MAIN "AquaTopChat v1.0 Documentation"\n       _ _ ___/\______/\__ ____/\___/\__ _ _/\____ _/\_ __ __/\______\n      __ ________   __   /   _   ___   / ______   \___/__/     _____/\n         bIS/   /   /   /   //   //   /___/ __¬   /  /  /  /\__   \\n           /   /   /   /   //   //   /   /  \    /  /  /  /   /   /\n    __  _ _\____  /\____  //_  //_____  /___/\  /\_____  /\ _/   /___\n     _  ___ _   \/  _  _\/_  \/____ __\/ ___ _\/_______\/____   /_ _/\n                                                            \  /\n                                  present                    \/\n\n               >>> AquaTopChat v1.0 by Aquarius/Outlaws <<<\n\n                      [- Contents of Documentation -]\n\n                @{"   Copyright Note   " Link Copyright   }   @{"   Configuration    " Link Configuration}\n                @{"  Archive Contents  " Link Archive     }   @{"      History       " Link History}\n                @{"    Introduction    " Link Introduction}   @{"  How to Reach Me   " Link ContactMe}\n                @{"    Requirements    " Link Requirements}   @{"    Other Tools     " Link AquaTools}\n                @{"    Installation    " Link Installation}   @{"     Greetings      " Link Greetings}\n\n           @{" Comment on AQUA-FUQ.TXT " Link FuckText}   @{" Note about AquaSettings " Link AquaSettings}\n@endnode\n\n@node Copyright "AquaTopChat v1.0 Documentation"\n\n                          Copyright ©1995 Aquarius\n\n                 Permission is granted to freely distribute\n               this product for non-commercial purposes only,\n                  as long as all files remain unmodified.\n@endnode\n\n@node Archive "AquaTopChat v1.0 Documentation"\n\nArchive (OTL-TC10.LHA) Contents\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nDoors/AquaTopChat/\n   AquaTopChatEnd           5712 bytes   Door to start from EndChat.txt.\n   AquaTopChatStart         1300 bytes   Door to start from StartChat.txt.\n   AquaTopChat.guide       18149 bytes   This AmigaGuide doc!\n\nCommands/SYSCmd/\n   ChatEnd.info             1282 bytes   Command icon for /X 3.0+.\n   ChatStart.info           1284 bytes   Command icon for /X 3.0+.\n\nNodeX/\n   EndChat.txt                29 bytes   Sample EndChat.txt.\n   StartChat.txt              54 bytes   Sample StartChat.txt.\n@endnode\n\n@node Introduction "AquaTopChat v1.0 Documentation"\n\nIntroduction\n~~~~~~~~~~~~\nThis door will time the "user - sysop" chats. When a chat is over, the\nlength of the chat is displayed and if it was long enough to be in the\ntoplist, the door says so and creates the top-chat bulletin. The bulletin\nwill also show two other records: the day with most chat time and the day\nwith most chats.\n@endnode\n\n@node Requirements "AquaTopChat v1.0 Documentation"\n\nRequirements\n~~~~~~~~~~~~\n- An Amiga with OS 2.04 or higher.\n\n- AmiExpress, SigmaExpress or any compatible program.\n@endnode\n\n@node Installation "AquaTopChat v1.0 Documentation"\n\nInstallation\n~~~~~~~~~~~~\nJust copy the ''AquaTopChat'' directory (the inner one) from the archive to\n''Doors:'', and (for /X 3.0+) put the provided command icons\n''ChatStart.info'' and ''ChatEnd.info'' in your ''SYSCmd'' drawer.\n\nBoth AquaTopChatStart and AquaTopChatEnd are perfectly safe to make\nresident.\n\nYou must edit your StartChat.txt(s) to contain the MCI command\n''~CC_ChatStart''. Edit your EndChat.txt(s) to contain ''~CC_ChatEnd''.\n\nIn case you didn''t know: Any MCI text must start with a ''~'', and every MCI\ncommand must end with a ''|'', a space ('' '') or a newline!\n@endnode\n\n@node Configuration "AquaTopChat v1.0 Documentation"\n\nConfiguration\n~~~~~~~~~~~~~\nAs configuration, AquaTopChat uses two environment variables:\n\n1. ''AquaTopChat_Entries'' - Determines the maximum number of chats to\n                           include in the bulletin.  Default: ''10''.\n\n2. ''AquaTopChat_Bull''    - Determines the filename of the bulletin that\n                           the door should create.\n                           Default: ''Doors:AquaTopChat/AquaTopChat.bull''.\n\nFor example, if you want the bulletin to contain the 15 longest chats\ninstead of only 10, type ''SetEnv AquaTopChat_Entries 15'' in a shell\nwindow. To make it permanent type ''SetEnv ENVARC:AquaTopChat_Entries 15''\nas well.\n@endnode\n\n@node History "AquaTopChat v1.0 Documentation"\n\nHistory\n~~~~~~~\n\n0.1 (11-02-94) Started..\n\n    (12-15-94) Made it residentable.\n\n    (12-27-94) Worked on it alot..\n\n    (12-31-94) Fixed a few bugs. Made the bulletin output.\n\n\n0.2 (01-04-95) It now stores chat records (both time and #chats) and the\n               dates they were set (the chat END date - it wouldn''t work\n               with start date).\n\n               Had to change to format of the data file.\n\n               Replaced some ANSI C functions with own ones/library\n               functions. Exe-code decreased by ~1500 bytes.\n\n               Polished the bulletin look. HH:MM time format, really\n               centered texts.\n\n\n1.0 (01-05-95) Discovered "AllocDosObject(DOS_FIB, TAG_DONE)" in the\n               source instead of "AllocDosObjectTags(DOS_FIB, TAG_DONE)".\n               (Not good..)\n\n    (01-27-95) It now clears the unused part of the strings in the data\n               file.\n\n    (01-28-95) First public release!\n@endnode\n\n@node ContactMe "AquaTopChat v1.0 Documentation"\n\nContact Me!\n~~~~~~~~~~~\nIf you have any cool ideas for improvement of this tool, questions, bug\nreports or whatever, contact me on one of the following boards:\n\n@{"NIGHTFALL" Link NIGHTFALL} ................ Whoosh ............ +46-90120369  <---  Safest\nHALL OF FAME ............. Dansken ........... +46-91026665      place to\nACES HIGH ................ Norad ............. +46-41044886     reach me!\nINTERCHANGE .............. Princip ........... +46-86082339\nZION''S HIDEOUT ........... Zion .............. +1-PRIVATE!!\nDEATH ROW ................ Shadower .......... +1-PRIVATE!!\nBOONDOCKS ................ Sal-One ........... +31-PRIVATE!!\n@endnode\n\n@node AquaTools "AquaTopChat v1.0 Documentation"\n\nThe AquaTools Collection\n~~~~~~~~~~~~~~~~~~~~~~~~\nHere is the complete list of my released tools (the latest versions):\n\nTool Name              File Name     Short Description\n---------------------- ------------- ------------------------------------------\nDisable v1.1           AQDSBL11.LHA  Payuser handling system.\nDisplayer v1.0         AQDSPL10.LHA  Text displayer. Perfect for door menu e.g.\nNetEdit v1.0           AQNETE10.LHA  Editor for certain netmail systems.\nConfReplace v1.0       OTL-CR10.LHA  Find and replace area names in User.Data.\nListSpeeder v2.1       OTL-LS21.LHA  Filelist downloader.\nAnnounce v2.0          OTL-AN20.LHA  Notifies online users of logons/logoffs.\nAquaWho v2.0           OTL-AW20.LHA  Totally configurable WHO door!\nSpeedCheck v2.1        OTL-SC21.LHA  Disables download at too low connect rates.\nStripper v1.2          OTL-ST12.LHA  Strips log files to desired file sizes.\nAquaScan v1.0          OTL-AS10.LHA  File scanner! (F, N, CS, FR.)\nAquaCreateAcc v1.0     OTL-CA10.LHA  Door to create new accounts with.\nAquaMoveFiles v1.0     OTL-MF10.LHA  File and description mover, by date.\nAquaSafety v1.0        OTL-SA10.LHA  Anti-BBS-downtime utility.\nAquaAdder v1.0         OTL-AA10.LHA  Text adder.\nAquaBulls v2.0         OTL-AB20.LHA  Bulletin viewer.\nAquaQuick v1.0         OTL-QK10.LHA  Quick-logon door.\nRestoreQuietness v1.0  OTL-RQ10.LHA  Restores the nodes'' "quietness" at logoff.\nAquaSettings v1.0      OTL-SE10.LHA  ''W'' replacement. Menu of config commands.\nAquaQuiet v1.1         OTL-AQ11.LHA  ''Q'' replacement. Toggles quiet node.\nAquaPWFail v1.0        OTL-PW10.LHA  Password failure door.\nAquaTopChat v1.0       OTL-TC10.LHA  Top-chat door.\n\n(...and more are coming!)\n\nYou can find them all on @{"Nightfall" Link NIGHTFALL} +46-90-120369 (free download)!\n@endnode\n\n@node BetaTesters "AquaTopChat v1.0 Documentation"\n\nBeta Testers\n~~~~~~~~~~~~\nThese are my beta testers. My tools wouldn''t have been as good as they\nare now if it hadn''t been for them. Many thanks dudes!\n\nACE CAZE ................. Dragon''s Lair ........ +46-16147118\nEZCO ..................... Serpent Hill ......... +46-8800293\nDANSKEN .................. Hall of Fame ......... +46-91026665\nFIREHAWK ................. Hardware Tower ....... +46-OFFLINE!\nKID CURRY ................ Pet Sematary ......... +46-PRIVATE!\nLOCKJAMMER ............... Substate ............. +46-OFFLINE!\nMARKY & POWER ............ Spread Draft ......... +49-PRIVATE!\nNASHUA ................... MegaByte ............. +45-42881885\nPLAYMATE ................. Northern Empire ...... +45-39619420\nPRINCIP .................. Interchange .......... +46-PRIVATE!\nPSYCHOPATH ............... Raising Hell ......... +46-243227029\nRIZE & FROSTY ............ Another World ........ +46-48088100\nSANDMAN .................. reference-board ............ +46-31918587\nSTATIC & FANTA ........... Frosen Assets ........ +46-322665225\nVEGAS & BISCROK .......... Overload ............. +46-OFFLINE!\nVITAL .................... Future Entrance ...... +46-60574467\nWHOOSH ................... @{"Nightfall" Link NIGHTFALL} ............ +46-90120369\nWIZE & HIFLY ............. Waterdeep ............ +46-PRIVATE!\n@endnode\n\n@node Greetings "AquaTopChat v1.0 Documentation"\n\nGreetings\n~~~~~~~~~\n                Greetings must go to (in no special order):\n\n           - Vegas/OTL - Biscrok/OTL - Toxic/OTL - Nashua/OTL -\n     - Snake/OTL - Whoosh/OTT^DVS^CLS^OTL^R2 - AtomiX!/OTL - SMS/OTL -\n   - Genghis Khan/OTL - The Other OTL Members - Ace Caze - Dansken/ACS -\n  - Princip! - Sandman - Rize & Frosty - Static & fanta - Marky & Power -\n  - Psychopath - Norad - Firehawk - Marwin - Danzig! - Lockjammer - MDR -\n  - HardHack - Chig - Kid Curry - Ezco - Enzo - Playmate - HiFly - Wize -\n   - Wild Thing - Juan! - Wilsom - Gi Joe - Sal-One - Zion! - Shadower -\n    - Doc Whoo - FAX - JAz - Bowen/OTT - Json - WarDancer - CornFlake -\n       - Bilbo Baggins - Sasha - Metalbasher - Psyche - CountZero! -\n               - Vital - Karma - Kain - Vileius - Nike/DLT -\n                       - And The Friends I Forgot! -\n\n\n                    Special thanks to my @{"beta testers" Link BetaTesters}!!\n\n\n                         A few personal messages:\n\nWhoosh         - Whooopssss... Nice chatting with you every day. :)\n\nToxic/OTL      - Hard getting cards isn''t it? If you can, call Nightfall\n                 (new pwfail door hehe)!\n\nVegas/OTL      - Yeah let''s get the Swedish section rocking! I mean, MORE!\n                 Btw, Norrland is such a nice place, don''t you think? :)\n\nBiscrok/OTL    - The master of strange (tüffa) modules. ;)\n\nDansken        - Great friend and beta tester! Learn C soon!! hehe\n\nMarky & Power  - Hope you can find a new way to call...\n\nEzco           - Great Who designs!!\n\nAce Caze       - Funny dude and great beta tester! Ok, nothing wrong with\n                 topaz 8! You just need a magnifying glass..\n\nSnowman/Ex.OTL - Where did you disappear??? Get in touch, mate..\n@endnode\n\n@node NIGHTFALL "AquaTopChat v1.0 Documentation"\n+-------------------------------------------------------------------------+\n|         iNTO tOTAL dARKNESS, tHE uNKNOWN; cOME wALK wiTH mE...          |\n| a3ooo    ___/\       ___/\ ____/\__________/\ ___/   __/\ _________9ooMB|\n+----------\__  \______\__  \____  __________  \  /   \__  \   _____/-----+\n|         tS/    __    \/      /  /_____   /     /     /        /         |\n· /X 4.xx  /      /    /      /     /     /           /        /    r2 sHQ·\n          /      /    /      /     /     /     /     /        /    dVS sHQ\n   eNJOY /______/    /______/___________/_____/     /________/    oTT  sHQ\n   tHE         /____/                        /     /         oTL diST siTE\n sPEED!             ·3 uSR nODES riNGDOWN!· /     /\n    ___/\ _________/\ _________/\ ___   ___/     / sTAFF: wHOOSH, aQUARiUS,\n    \__  \ ________  \_________  \  /   \__     / riZE, mASTERmAN, nEMESiS\n·    /    _____/ /     __    /     /_____/     /_____                     ·\n:   /      /    /      /    /     /     /     /     /    mORE tHAN 1200   :\n|  /      /    /      /    /     /     /     /     / aMiX tOOLS oNLiNE!!  |\n+-/______/----/______/    /___________/___________/-----------------------+\n|                   /____/                                                |\n| nODE#1: +46-90-120369   nODE#2: +46-riNGDOWN!!  nODE#3: +46-riNGDOWN!!  |\n|      (14.4k DS)              (16.8k DS)              (28.8k DS)         |\n+-------------------------------------------------------------------------+\n@endnode\n\n@node FuckText "AquaTopChat v1.0 Documentation"\n\nComment on AQUA-FUQ.TXT\n~~~~~~~~~~~~~~~~~~~~~~~\n\n--vv-vv----------------- START OF "AQUA-FUQ.TXT" ------------------vv-vv--\n\n@BEGIN_FILE_ID.DIZ\n--------------------------------------------\nPot-Noodle speaks: All of AQUARIUS /X doors\nare MY sources that HE edited! This is fuqn\nLAME! I bet he put alot of BACKDOORS in them\ntoo! DONT USE THEM! There''s PROOF in this\ntext that shows that I made all the doors!\n-------------------------[ P0t-N00dle/atx ]-\n@END_FILE_ID.DIZ\n\nI''m UPSET! About 1 year ago, Aquarius were a active user of my bbs, and he\ntold me he were an /X tool developer, so i gave him access to my /X tool/source\nconferance, and he leeched all of my unreleased utils in this conf.\nNow, 1 year later, i see more and more of them poppin up as ''quack-wa-scan''\nand whatever. I have no idea what he might have added more then just his\nname to my doors, but i would suggest you NOT to use them.\n\n                                                           >p0t-n00dle/anThrox<\n\n--^^-^^------------------ END OF "AQUA-FUQ.TXT" -------------------^^-^^--\n\nIf you''ve had the bad luck to have seen this text, you have probably\nfigured out that it is total bullshit. Then you''re absolutely right! It is\nplain lies! I haven''t even called P0T-NOoDLE''s BBS, EVER! This text is\njust another attempt from some lame "wanna-be" to destroy for a guy\nworking hard to supply the scene with backdoor-free, quality /X tools. It\nmakes me sad, whoever it is being attacked with lies like that. Can''t the\npitiful lamers producing such crap do something positive, instead of just\ntrying to destroy for others? I guess not... But then they should get the\nfuck out of the scene, at least until they''ve grown up!!\n\nThe lamer who wrote AQUA-FUQ.TXT is also abusing the highly respected name\nP0T-NOoDLE (great tools man!). Of course it''s not P0T-NOoDLE who wrote it.\nA few observations to make:\n\n* P0T-NOoDLE is English and I don''t think he would write "Aquarius were a\n  active user"... I''m sure the real writer has done his best to get it\n  right.\n\n* As far as I know, P0T-NOoDLE codes his tools in assembler (and some in\n  ARexx). I write mine in C, so how could I have stolen and edited his\n  sources??\n\n* P0T-NOoDLE has never used icons as config. I do it in most of my tools.\n\nAnd so on... If you still (!) have any doubts, take a look at the doc for\nP0T-NOoDLE''s excellent Super-DupeCheck v1.03 and the list of his\nunreleased tools. Then you''ll see that I haven''t made a single one like\nany of those.\n\nYou can also ask any of my @{"beta testers" Link BetaTesters}. They can assure you that my tools\nhave been DEVELOPED and weren''t just suddenly finished. For example\nAquaScan - it was rather simple in the beginning; no scroll-back, no\nflagging by number, no date/file separators etc. In this doc, I have\nincluded the @{"history" Link History} for the early beta versions of this tool. I usually\ndon''t do that. But just so that you can see that it is MY work! (sigh)\n\nAnd about the "accusation" of backdoors... Do you think I would spend most\nof my spare time writing lame backdoors?! Of course not! I code /X tools\nfor fun and for others to enjoy. And obviously people DO enjoy them. :)\nAs an example, Sasha (Datalus BBS, UK) just told me about AquaScan:\n"every (and i mean every) bbs in the uk uses it!"... That''s the only\nreward I want for my work; to hear that my tools are appreciated.\n\nSo if you see AQUA-FUQ.TXT somewhere, or any other text like that, nuke it\nto hell!\n\nOk, enough about this CRAP!\n@endnode\n\n@node AquaSettings "AquaTopChat v1.0 Documentation"\n\nNote about AquaSettings\n~~~~~~~~~~~~~~~~~~~~~~~\nFirst of all, I''m glad so many boards are using AquaSettings! Just a few\ndays after release and suddenly it''s installed on every other board! Cool!\n\nBut it seems I made a little mistake in the AquaSettings v1.0 archive..\nIn the provided configuration icon ''AquaSettings.info'', the ''CMD.1''\ntooltype was set to ''W''. It SHOULD have been ''W_INTERNAL''. This only goes\nfor AmiExpress 3.xx/4.xx. The icon was correct for SigmaExpress and\nAmiExpress 2.xx. I did write about that in the doc, but there I assumed\n''CMD.1'' was ''W_INTERNAL'' from the beginning.\n\nSo what''s the difference? Well, when you start AquaSettings you get a menu\nof different configuration stuff. The first entry is "Basic settings", or\nwhatever you name it, i.e. it starts the internal W command. But if\n''CMD.1=W'' then the door won''t be able to return to the menu again. That''s\nbecause of a limitation in AmiExpress/S-Express which doesn''t let any door\nrun an internal command (with the same name as a door), without quitting\nthe door first. But the W_INTERNAL command is a way around this. If you\nuse ''CMD.1=W_INTERNAL'' with AmiExpress 3.xx/4.xx, then "Basic settings"\nwill behave like all the other menu entries: you will be taken back to the\nAquaSettings menu afterwards.\n\nI haven''t seen it changed on any board, so what I have learnt from this is\nthat the contents of provided configuration files are very important, and\nthat most sysops don''t bother to read the doc entirely and check the\nconfiguration, which is a bit unfortunate.\n\n  .------------------------------------------------------------------.\n  | If you''re running AmiExpress 3.xx/4.xx, change ''CMD.1=W'' to      |\n  | ''CMD.1=W_INTERNAL'' in ''Doors:AquaSettings/AquaSettings.info'',    |\n  | and make sure you have copied ''W_INTERNAL.info'' from the archive |\n  | (OTL-SE10.LHA) to your ''BBSCmd'' drawer (NOT ''SYSCmd'').           |\n  `------------------------------------------------------------------''\n@endnode\n\n[EOF]\n','\n',char(10)),NULL,NULL,15877,3,0,NULL,NULL,'otl_tc10_aquatopchatend','scan',1780048664);
INSERT INTO door_catalog VALUES('otl_ul10','OTL-UL10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OTL-UL10.LHA',NULL,'XIM','_ _/\____/\_ ___/\__/\_ __/\__ _/\____/\__ _',NULL,NULL,'OTL','_____  __  / __   __  /_____  \__/ /   ____ :/  /  /  /  //  //  /__/  ¬  / / / /\_  \:: /  /  /  /  //  //  /  / _/  / / / /  /  /::',replace('_ _/\____/\_ ___/\__/\_ __/\__ _/\____/\__ _\n_____  __  / __   __  /_____  \__/ /   ____\n:/  /  /  /  //  //  /__/  ¬  / / / /\_  \::\n/  /  /  /  //  //  /  / _/  / / / /  /  /::\n\__  /\__  //  //___  /__\  /\__  /___  /:::\nbIS\/====\/==\/=====\/====\/====\/====\/===>\n[/X 2.x]    AtomiX presents         [/X 3.x]\n UserList v1.0 - a tool to list the UserData\n                 Online written in pure ''C''\n','\n',char(10)),'UserList.guide',replace('@DATABASE "UserList.guide"\n\n@WIDTH 80\n@NODE MAIN "AtomiX of Outlaws"\n\n                          UserList v1.0\n               written by AtomiX / OTL in Wed May 25 1994\n \n            @{"    Copyright Note    " LINK COPRIGHT} -1- @{"   Urheberechte    " LINK URHEBERECHT}\n            @{"    Product Info      " LINK Produkt } -2- @{"   Produkt Info''s  " LINK PRODUKT}\n            @{"    Installation      " LINK INSTALL } -3- @{"   Installation    " LINK INSTALLATION}\n            @{"    Bug Report        " LINK BUG     } -4- @{"   FehlerReporte   " LINK FEHLER}\n            @{"    Changes           " LINK History } -5- @{"   Changes         " LINK History}\n\n                               READ THE CHANGES\n\n\n@ENDNODE\n\n@NODE COPRIGHT\n@TITLE "Copyrighted"\n\n - AmiExpress is (C) by LightSpeed Technologies\n\n - MultView , AmigaGuide , is (C) C=\n\n\n								@{"Main Menu" LINK MAIN}\n\n@ENDNODE\n\n@NODE URHEBERECHT\n@Urheberechte\n\n - AmiExpress ist Urheberechtlich geschützt von LightSpeedTechnologies\n\n - MultiView , Amiga Guide , ist Urheberechtlich geschützt von Commodore\n\n\n								@{"Main Menu" LINK MAIN}\n\n@ENDNODE\n\n@NODE PRODUkT\n@TITLE "Product Informations"\n\n   This is a UserLister .. hmm that is all ;^))\n\n   ohh before i forget it User Data''s must be located\n   and called "BBS:USER.DATA"\n\n\n\n								@{"Main Menu" LINK MAIN}\n@ENDNODE\n\n@NODE INSTALL\n@TITLE "UserList v1.0 - Installation"\n\n * INSTALLATION *\n\n - Copy all file to BBS:Doors/<or where you like it>\n\n\n AE 3.xx Installation\n --------------------\n\n  - Copy UserList.info to BBS:Commands/BBScmd/\n\n    Or add to UserList.info:\n\n      ACCESS=   <Access Level>\n      LOCATION= <Door Location>\n      MULTINODE=<Multi Node ?>\n      PRIORITY= <Priority dont change it>\n      STACK=50000\n      TYPE=XIM\n\n\n\n								@{"Main Menu" LINK MAIN}\n@ENDNODE\n\n@NODE INSTALLATION\n@TITLE "UserList - Installation"\n\n * INSTALLATION *\n\n - Kopieren Sie alle Files in folgenden Pfad \n\n   "BBS:DOORS/"\n\n   AE 3.xx Installation\n   ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n - Kopieren Sie das "UserList.info zu "BBS:COMMANDS/BBSCMD/"\n\n   Oder fügen Sie folgende Befehle in "UserList.info" ein\n\n      ACCESS=   <Access Level zum Starten>\n      LOCATION= <Pfad für das Door>\n      MULTINODE=YES\n      PRIORITY=0\n      STACK=50000\n      TYPE=XIM\n\n\n								@{"Main Menu" LINK MAIN}\n@ENDNODE\n\n@NODE BUG\n@TITLE "Bug Reports"\n\n BUG REPORT & SUGGESTIONS\n ------------------------\n\n   It''s possible that a mistake will occur.... nobody is perfect.\n   If you have any suggestions or comments please leave a message\n   to me on the CHAOS LINE (German /X Distributor)\n\n   Node 1 : +49 (0)5723 74340  16.8DST\n   Node 2 : +49 (0)5723 SøøN   ISDN RingDown (16.6.94 the number available)\n   Node 3 : +49 (0)5723 SøøN   ISDN \n\n								@{"Main Menu" LINK MAIN}\n@ENDNODE\n\n@NODE FEHLER\n@TITLE "Fehler Report"\n\n Fehler Reporte & Vorschläge\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\n   Es ist möglich das Fehler passieren ... niemand ist perfekt.\n   Wenn Sie vorschläge oder Fehler Reporte zu unseren Tools haben\n   dann rufen sie unser Hauptquatier an und hinterlassen Sie eine\n   Nachricht für mich auf der Chaos Line (Deutscher /X Händler)\n\n   Node 1 : +49 (0)5723 74340  16.8DST\n   Node 2 : +49 (0)5723 SøøN   ISDN RingDown (16.6.94 wird die Nummer bekannt)\n   Node 3 : +49 (0)5723 SøøN   ISDN \n\n\n								@{"Main Menu" LINK MAIN}\n@ENDNODE\n\n\n@NODE History\n@TITLE "History"\n\n   v0.5  - (INTERN) Slighty Memory bug     \n\n   v1.0  - Memory bug Removed . First Release\n\n@ENDNODE\n\n\n@NODE Releases\n@TITLE "Tools from AtomiX"\n\n   .------[Name]------. .-[$VER]-. .--[Archive]--.\n   | Ansi Skipper     | |  v1.0  | | ANSISV10.LHA|\n   | Atom(Joy)Comment | |  v1.1  | | LGC-JC11.LHA|\n   | Atom(Joy)Status  | |  v1.1  | | NS-JS11.LHA |\n   | Bull View        | |  v1.2  | | BULLV12.LHA |\n   | DoorMenu         | |  v1.3  | | DOORM13.LHA |\n   | FastLhaCheck     | |  v1.0  | | OTL-FLC.LHA |\n   | FrontEnd         | |  v1.2  | | NS-JF11.LHA |\n   | LHA-Server       | |  v1.0  | | *********** | REGISTERED ONLY\n   | Logon Batch      | |  v1.0  | | NS-LB10.LHA |\n   | OperatorPage     | |  v1.3  | | OPAGER13.LHA|\n   | PW Failure       | |  v1.9  | | PWFAil19.LHA|\n   | System Control   | |  v1.2  | | NS-SC12.LHA |\n   | UserInformation  | |  v1.4  | | -Forgotten- |\n   | UserList v1.0    | |  v1.0  | | OTL-UL10.LHA|\n   `------------------'' `--------'' `-------------''\n\n    NOTE- I think that''s not all my Released Tools\n          because i dont know what i all have written\n          keep it on your mind ;^)\n\n          Greets AtomiX  - Friendship is more than a word\n\n@ENDNODE\n','\n',char(10)),'{"ACCESS":"<Access","LOCATION":"<Door","PRIORITY":"<Priority","STACK":"50000","TYPE":"XIM"}',NULL,16168,5,0,NULL,NULL,NULL,'scan',1780048664);
INSERT INTO door_catalog VALUES('otl_us10','OTL-US10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OTL-US10.LHA','UploadStats','XIM','[-UPLOADSTATS-]             /\__   [--]','1.20','Neptune','OTL','._________ ___ __ _/\______/  _/_ _/\__ ___. |               //____   __  ___/_/   /___ | | ULSTATS v1.20  /   /   /   /   /   /   / |',replace('[-UPLOADSTATS-]             /\__   [-v1.20-]\n._________ ___ __ _/\______/  _/_ _/\__ ___.\n|               //____   __  ___/_/   /___ |\n| ULSTATS v1.20  /   /   /   /   /   /   / |\n| [ RELEASE 1 ] _\___   /\___   /____   /__|\n|                _ ___ /__ ___ /_ ____ /__/|\n| We are proud to    \/      \/ -bIS!\/    |\n| present a cool stats door that only sho- |\n| ws upload and downloads. Sexy design as  |\n| usual. Use in your upload text. Le cool! |\n| Code by Neptune and Odyssey of Outlaws.  |\n`------------------------------------------''\n','\n',char(10)),'UploadStats.doc',replace('\n                         .____.    .____.\n       ________._________|    |___ |    | ____________________________\n     ./   __   |    |    |  _____/_|    |_\____   |      /   |   ____/_.\n __  |     /   |    |    |   \     |    |    _    |     /    |\______  |  __\n-\/--|    /    |    |    |    \    |    |    /    |    /\    |    /    |--\/-\n-----|_________|_________|_________|____|_________|____/\____|_________|-p!--\n\n                            -  p r e s e n t s  -\n\n\n                       UPLOADSTATS! v1.0 [RELEASE 1]\n                    COPYRIGHT 94-95, NEPTUNE ''N ODYSSEY\n\n\nIndex\n~~~~~\n  Contents of the archive\n  Introduction / Features\n  Requirements\n  Installation\n  Copyrights\n  Greetings / Personal hellos\n  File_id.diz\n  Bug reports, Suggestions & How to contact!\n\n\nContents of the archive\n~~~~~~~~~~~~~~~~~~~~~~~\n  BBS:Commands/SYSCmd/\n    UL_STATS.info           1030 bytes - Provided command icon for /X 3.x+.\n\n  BBS:Doors/UploadStats\n    UploadStats            10372 bytes - The door for any cpu.\n    UploadStats.doc         3336 bytes - This documentation.\n\n\nIntroduction / Features\n~~~~~~~~~~~~~~~~~~~~~~~\n  This door is another production from outlaws/therion and it''s fully\n  programmed in c to accomplish some speed. Simple info/stats door for\n  usage in upload-bulletins etc.\n\n\nRequirements\n~~~~~~~~~~~~\n  - Amiexpress, S-Express or simular.\n\n\nInstallation\n~~~~~~~~~~~~\n  (CLI) : Copy Doors/UploadStats to Doors:\n\n  2.x\n    (CLI) : Edit BBS:Commands/SYS.CMD\n      --- cut --- cut --- cut --- cut --- cut ---\n      *G         XM001Doors:UploadStats/UploadStats\n      --- cut --- cut --- cut --- cut --- cut ---\n\n  3.x, 4.x\n    (CLI) : Copy Commands/SYSCmd/UL_STATS.info to BBS:Commands/SYSCmd/\n\n  Any..\n    (CLI) : Edit BBS:Conf/Uploadmsg.txt\n      --- cut --- cut --- cut --- cut --- cut ---\n      ~ ~CC_UL_STATS\n      --- cut --- cut --- cut --- cut --- cut ---\n\nCopyrights\n~~~~~~~~~~\n  Permission is granted to freely distribute this product for non-commercial\n  purposes only, as long as all files remain unmodified. I take no charge\n  for the door but you could leave me a mail and tell me that you use it and\n  perhaps support my board.\n\n\nGreetings / Personal hellos\n~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n                Aquarius/Otl - Hijacker/Cls - Sandman/Flt\n            Dexter/Afl - Guardian/Ind - Juan/Trsi - Phase!/Frs\n         Kid Curry/Cls - Ezco/Dpl - Twister/Dcs? - Amigaspirit/Ind\n       B.B.King/Atm - Dalamar/Led - Nike/Crz - Whoosh/Otl - Nero/Pdx\n      Zcandaler/Ind - Karma/Acl? - Bobo/Mst - Vegas/Otl - Biscrok/Otl\n\n\nFile_id.diz\n~~~~~~~~~~~\n[-UPLOADSTATS-]             /\__   [-v1.20-]\n._________ ___ __ _/\______/  _/_ _/\__ ___.\n|               //____   __  ___/_/   /___ |\n| ULSTATS v1.20  /   /   /   /   /   /   / |\n| [ RELEASE 1 ] _\___   /\___   /____   /__|\n|                _ ___ /__ ___ /_ ____ /__/|\n| We are proud to    \/      \/ -bIS!\/    |\n| present a cool stats door that only sho- |\n| ws upload and downloads. Sexy design as  |\n| usual. Use in your upload text. Le cool! |\n| Code by Neptune and Odyssey of Outlaws.  |\n`------------------------------------------''\n\n\nBug reports, Suggestions & How to contact!\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n  If you have any suggestions or bug-reports please contact me on..\n\n                  ---  FROZEN ASSETS  +46-322-665225  ---\n\n','\n',char(10)),NULL,NULL,10948,5,0,NULL,NULL,'otl_us10_uploadstats','scan',1780048664);
INSERT INTO door_catalog VALUES('otl_m134','OTL_M134.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OTL_M134.LHA',NULL,'XIM','LE-win5-96.exe',NULL,NULL,'OTL','/   \/  |  \  __  /  |_/   \  \/\/  /  ___/ /    \\  |  \\/  \/   / \_  \\     //\___  \ \_____/______/____\______/____\_/\_/\______/',replace('  ___  __.____________.  ______    ___._____\n /   \/  |  \  __  /  |_/   \  \/\/  /  ___/\n/    \\  |  \\/  \/   / \_  \\     //\___  \\n\_____/______/____\______/____\_/\_/\______/\n.---------------( present: )-----------mk--.\n:       MaPuS v1.34 (c)1994-95 Eniac       :\n:           THE BEST DMS CHECKER           :\n:             * REAL UPDATE! *             :\n:    Directly from the NEW Support BBS!    :\n:         >> READ INFOS INSIDE! <<         :\n`------------------------------[20-10-95]--''\n','\n',char(10)),'MaPuS.guide',replace('@database MaPuSDoc\n\nCopyright (c) 1993-94-95 by Caton\nAll Rights Reserved\n\n@Remark $VER: MaPuS Dox AmigaGuide format 1.6 (4.10.95) by Caton\n\n@node MAIN "MaPuS"\n\nSelect language please:\n\n                    @{" ITALIANO " Link ITA}      -      @{" ENGLISH " Link ENG}\n\n\n               .------------------------------------------.\n               |  _____/\  __________  ___  /\____        |\n               |  \____  \/  _¬\___ ¬\/ |¬\/  ___/--------|\n               |   |  ..  \     \  __/  |  \___ ¬\        |\n               |   |__||__/__|__/__| \_____/_____/--------|\n               | <------( DMS checker By Eniac )--------> |\n               `--------------------------------------mk--''\n\n@endnode\n\n@node ITA "Istruzioni di ''MaPuS''."\n\n                             @{b}INDICE GENERALE:@{ub}\n\n@{" ATTENZIONE " Link Cap01}\n@{" INTRODUZIONE A MaPuS " Link Cap02}\n@{" PERCHE'' USARE MaPuS E NON UN ALTRO CHECKER? " Link Cap03}\n@{" COME FUNZIONA " Link Cap04}\n@{" ESEMPI " Link Cap05}\n@{" USO DI MaPuS CON AMIEXPRESS o DLG " Link AXuso}\n@{" GLOSSARIO " Link Cap06}\n@{" UPDATES DEL MaPuS " Link Cap07}\n@{" FUTURI SVILUPPI " Link Cap08}\n@{" RINGRAZIAMENTI " Link Cap09}\n@{" COME CONTATTARCI " Link Cap10}\n\n@endnode\n\n@node Cap01 "ATTENZIONE:"\n\n\nE''  stato  deciso  di  immettere  questo  programma  nel  Pubblico Dominio,\nimponendo l''opzione dello Shareware qualora venisse usato regolarmente.\n\nQuindi se lo hai installato nella tua BBS o lo utilizzi di routine, faresti\nbene a registrarti per premiare il lavoro di chi lo sviluppa.\n\nLa  cifra  di  registrazione  (simbolica) e` di 15$ o 15000 Lire da spedire\ninclusa  nella  busta  o  come cheque o come vaglia postale al seguente\nindirizzo:\n\n                             Antonino Pintaudi\n                                P.O. Box 11\n                         98125 Contesse (Messina)\n                                  ITALIA\n\nL''archivio originale MaPuS???.LHA (in cui ???  e` il numero della versione)\nnon puo'' essere modificato.  Non possono essere aggiunti o tolti file salvo\nle normali "pubblicita''" delle BBS.\n\nLa lista dei file che contiene l''archivio originale e` la seguente:\n\n---\nbbs/fcheck/DMS                      ;Configurazione per @{"AmiExpress" Link AXuso}\nbbs/fcheck/DMS.Info                 ;Configurazione per @{"AmiExpress v3.+" Link AXuso}\nbin/MaPuS.???                       ;Eseguibile (??? sta per n. di ver.)\nbin/MAPUS_NOTE.TXT                  ;Informazioni su questa versione\nDLGConfig/Batch/UPLOAD1.BATCH       ;/\nDLGConfig/Text/Banner.displayme     ;| Files necessari per @{"DLG" Link AXuso}\nDLGConfig/Text/PreDesc.txt          ;\\ndoc/MaPuS.GUIDE                     ;Istruzioni in formato AmigaGuide\nlibs/arp.library                    ;arp.library V39.1\nMAPUS.LHA                           ;Copia di BackUp di questo archivio\n---\n\nIn  caso  avessi  qualche  tua proposta per migliorare il programma (ad es.\nuno  script  per  il  tuo  programma  di BBS) DEVI contattare l''autore, che\nincludera''  (con  i  dovuti ringraziamenti) il tuo lavoro in ogni revisione\ndel programma.\n\nNessuno  e` responsabile in alcun modo degli eventuali (e remoti) danni che\nMaPuS potrebbe arrecare al tuo sistema.\n\nMaPuS e` stato scritto totalmente in @{i}Assembly@{ui}!\n\n@endnode\n\n@node Cap02 "INTRODUZIONE A MaPuS:"\n\n\nCos''e`  MaPuS?   MaPuS  e`  la soluzione ideale per il trattamento dei file\nDMS.    Puoi   manipolarli   come  piu''  ti  aggrada.   Puoi  controllarli,\naggiungere,  rimuovere e creare @{"front, tail e track banner" Link Cap06}; tutto in un\nmodo alquanto funzionale.\n\n@endnode\n\n@node Cap03 "PERCHE'' USARE MaPuS E NON UN ALTRO CHECKER?"\n\n\nSemplice.   Alcuni  checker  non funzionano perfettamente su tutti i files,\naltri  non  ti  forniscono  le  informazioni in modo completo, e nessuno ti\npermette  di  creare  e aggiungere banner.  MaPuS puo'' essere usato con una\n@{"BBS"  Link AXuso} o nei tuoi file @{"script" Link Cap05} o semplicemente per  @{"testare i file DMS" Link Cap04}.\nMaPuS e` garantito al 100% su queste funzioni.\n\n@endnode\n\n@node Cap04 "COME FUNZIONA:"\n\nSe invochi MaPuS con solo il suo nome ti fornira'' la sintassi:\n\nMaPuS [-<options>] FileName[.DMS] [DestFile]\n\nOpzioni:\n\n@{" Operazioni sui front banner " Link FrontOpt}\n@{" Operazioni sui track banner " Link TrackOpt}\n@{" Operazioni sui tail banner " Link TailOpt}\n            @{" Varie " Link VarieOpt}\n\nSe invochi MaPuS con il solo nome file sorgente, questo sara'' controllato e\nti verranno mostrate alcune informazioni sullo stato.\n\nLa specifica del file sorgente puo'' contenere le wildcards * o ? o #?.\n\n@{b}NOTA: Ad ogni revisione di MaPuS ricordati di ricreare il MaPuS.cfg@{ub}\n\n@endnode\n\n@node FrontOpt "Operazioni sui front banner:"\n\n\n\n\n\n@{" a " Link Opta} aggiunge un front banner.\n@{" r " Link Optr} rimuove i front banner.\n@{" m " Link Optm} crea un front banner.\n\n\n\n\n\n@endnode\n\n@node TrackOpt "Operazioni sui track banner:"\n\n\n\n\n@{" t " Link Opta} aggiunge un track banner.\n@{" k " Link Optr} rimuove i track banner.\n@{" n " Link Optm} crea un track banner.\n\n\n\n\n\n@endnode\n\n@node TailOpt "Operazioni sui tail banner:"\n\n\n\n\n@{" A " Link Opta} aggiunge un tail banner.\n@{" R " Link Optr} rimuove i tail banner.\n@{" M " Link Optm} crea un tail banner.\n\n\n\n\n@endnode\n\n@node Opta "Aggiungi banner:"\n\n\nDevi  fornire  il  "FileName"  sorgente  (con o senza l''estenzione .DMS) ed\nopzionalmente un file destinazione "DestFile".\n\nMaPuS  testera''  il  file  ed  aggiungera''  il  banner al file destinazione\n(creando  quindi una copia del file sorgente) o direttamente al sorgente in\ncaso mancasse il destinazione.\n\nQualora  non  fornissi  alcun  nome  di  file  come parametro, apparira'' un\nrequester ARP, che ti permettera'' di sceglierne uno.\n\n@{b}NOTA:@{ub} Se devi creare il file destinazione in RAM: usa l''opzione @{"s" Link VarieOpt}.\n\nIl  "FileName" puo'' essere privo di estensione, ma e` indispensabile che la\nscriva tu per il file destinazione.\n\n\n@endnode\n\n@node Optr "Rimuovi i banner:"\n\n\nSpecifica   come   parametri   il  nome  del  file  sorgente  e  di  quello\ndestinazione.   MaPuS,  dopo aver testato il file sorgente, creera'' un file\ndestinazione privo dei banner.  Se non hai specificato il file destinazione\ni banner verranno "strippati" direttamente dal file sorgente.\n\nQualora  mancasse  anche  quest''ultimo,  apparira''  un requester ARP che ti\npermettera'' di sceglierlo.\n\n@{b}NOTA:@{ub} Se usi la RAM: specifica l''opzione @{"s" Link VarieOpt}.\n\n@endnode\n\n@node Optm "Crea i banner:"\n\n\nSpecifica  il  nome  del  file  di  testo  da  usare come banner o se no ti\napparira''  un  requester  che  ti permettera'' di sceglierlo.  MaPuS creera''\nnella  S:   un  file  chiamato  "MaPuS.cfg", che ti permettera'' di usare le\nopzioni di adding.\n\nIl formato del file testo e`:  64 colonne (return compreso) per 16 linee.\n\n\n@endnode\n\n@node VarieOpt "Opzioni varie:"\n\n@{b} s @{ub}  -  Non  controllare  lo  spazio disponibile.  Indispensabile se\n        lavori nella RAM:  che e` sempre piena al 100%.\n\n@{b} v @{ub}  -  Visualizza delle informazioni sul file DMS, ma non testarlo.\n\n@{b} d @{ub}  -  Metti la data di upload nel track banner da aggiungere.\n\n@{b} g @{ub}  -  Visualizza alcuni ringraziamenti.\n\n@{b} u @{ub}  -  Per scegliere, in ogni caso, il file DMS da un requester ARP.\n\n@{b} f @{ub}  -  Visualizza dettagliate informazioni su ogni traccia del file\n        DMS.\n\n@{b} c @{ub}  -  Restituisce un codice di ritorno di 15 in caso di fallito\n        checking.\n\n@{b} i @{ub}  -  Esclude alcuni reports.\n\n@{b} I @{ub}  -  Esclude altri reports.\n\n@endnode\n\n@node Cap05 "ESEMPI:"\n\n\n1) Controlla un file:\n In questo esempio immaginiamo di avere un file nella tua directory DL:\nchiamato TEST.DMS e che tu voglia controllarlo.\n\nMaPuS dl:TEST.dms o MaPuS dl:TEST\n\nsara''  controllato  e  ti verranno mostrate alcune informazioni sullo stato\ndello stesso.\n\n2) Crea un @{"tail banner" Link TailOpt}:\n\nMaPuS -M \n\n3) Aggiungi un @{"front banner" Link FrontOpt} e rimuovi i @{"tail" Link TailOpt} e @{"track banner" Link TrackOpt}:\n\nMaPuS -AskR dl:TEST[.dms] ram:newTEST.dms\n\n(Nota l''opzione @{"s" Link VarieOpt} per la ram:)\n\n4) Testa tutti i file di una directory:\n\nMaPuS dl:*.dms ovvero MaPuS dl:#?.dms\n\n@endnode\n\n@node AXuso "Uso con /X o DLG:"\n\n\nSe vuoi usare MaPuS con AmiExpress usa lo script incluso: @{b}bbs/fcheck/DMS@{ub}\n\n<----- CONTENUTO DEL FILE: ---------- CUT ------------------------------->\nMaPuS\n\nError\n<------------------------------------ CUT ------------------------------->\n\nNOTA: La seconda linea contiene le opzioni per il MaPuS.\n\n@{b} RICORDA: @{ub} Il file deve contenere esclusivamente queste 3 linee!\n\n  Se  possiedi  una  versione  superiore  alla  3.0  di  AmiExpress  piazza\nsemplicemente  il file incluso nell''archivio - "DMS.info" - nella directory\nBBS:FCheck.\n\nInclusi nell''archivio i file necessari per l''uso di MaPuS con DLG:\n\nDLGConfig/Batch/UPLOAD1.BATCH\nDLGConfig/Text/Banner.displayme\nDLGConfig/Text/PreDesc.txt\n\n@endnode\n\n@node Cap06 "GLOSSARIO:"\n\n@{"Tail Banner" Link TailOpt}:  e` il testo che sara'' aggiunto in coda al file DMS.\n              (e` l''ultimo che verra'' mostrato nella scompattazione)\n\n@{"Front Banner" Link FrontOpt}: e` il testo che sara'' aggiunto in fronte al file DMS.\n              (e` il primo che verra'' mostrato nella scompattazione)\n\n@{"Track Banner" Link TrackOpt}: e` la traccia zero che sara'' mostrata come se fosse un testo.\n\n@endnode\n\n@node Cap07 "UPDATES DEL MaPuS:"\n\n0.** Versioni sperimentali mai rilasciate.\n\n0.84 Prima versione pubblica. Per mia decisione tutte le versioni pubbliche\n     da ora in poi non implementeranno l''opzione @{"-k" Link TrackOpt}.\n \n0.85 Prima versione registrata, rilasciata a chi ne faceva richiesta\n     chiamando @{"DELTA CITY BBS" Link Cap10}.\n \n0.86-0.91 Versioni private\n     Sistemati alcuni bug, fra cui l''opzione @{"-k" Link TrackOpt} che corrompeva l''archivio\n     se vi erano un track banner e subito dopo un front banner.\n\n0.92 Versione pubblica.\n     Implementata l''opzione @{"-f" Link VarieOpt}.  Se specificata mostra informazioni\n     dettagliate su ogni traccia del file DMS.\n\n0.93 Versione registrata.\n \n0.94 Versione mai rilasciata.\n \n0.95 Versione Shareware.\n     Sistemato un bug il quale non faceva funzionare l''opzione @{"-f" Link VarieOpt} se\n     il file era selezionato dal requester.\n \n0.96 Versione Shareware.\n     Su segnalazione di Felix rimosso un bug per il quale MaPuS non poteva\n     essere reso residente. Sistemate alcune piccolezze.\n\n0.97 Versione registrata.\n\n0.98-0.99 Versioni private.\n\n1.00 Versione Shareware, non completa a causa della MANCANZA totale di\n     registrazioni!\n     Chi desidera la versione completa deve versare la quota di\n     registrazione o contattare @{"DELTA CITY BBS" Link Cap10}.\n     Aggiunta delle wildcards (*,?,#?).  Velocizzata la routine di\n     stripping,  in alcuni casi e` piu'' veloce del 200%!!!  Creata la guide\n     che contiene sia le istruzioni in italiano che in inglese, modificata\n     la struttura dell''archivio.\n\n1.01 Versione registrata.\n\n1.02-1.09 Versioni private.\n\n1.10 Versione rilasciata allo SMAU 1993.  Aggiunta la possibilita'' di\n     inserire la data di upload (utile per le BBS) nei track banner\n     (opzione @{"-d" Link VarieOpt}).  Ora l''esecuzione di MaPuS puo'' essere bloccata con\n     CTRL-C (solo dopo il test).\n\n1.11 Versione registrata.\n\n1.12 Sistemata l''opzione @{"-t" Link Trackopt}. Per un bug nella 1.10 quest''opzione\n     non funzionava correttamente su 68000.\n\n1.13 Versione registrata.\n\n1.14 Sistemati due problemi:\n     1) Se il nome del file conteneva il carattere "-", MaPuS\n        non interpretava correttamente la linea di comando.\n     2) A volte l''add di un track banner corrompeva l''archivio.\n\n1.15 Versione registrata.\n\n1.16 Rimossi due bug:\n     1) Qualora durante il check di un file venisse premuto CTRL-C il\n        programma faceva bloccare il sistema.\n     2) Piccolo problema con la command line.\n     Ora le informazioni che da'' MaPuS sono compatibili con il DMS V1.51+.\n     Modifiche alla guide, eliminati i doc in formato ASCII.\n\n1.17 Versione registrata.  (I_I)\n\n1.18-1.29 Versioni Private mai rilasciate.\n          Nota: ho visto girare una versione 1.20. Questa versione non e`\n          mai stata creata da me, percio'' sconsiglio l''utilizzo.\n\n1.30 Sistemati alcuni bug: ora il checking di un file vuoto non produce\n     problemi.\n\n     Aggiunto il supporto delle virgolette: ora il nome del file\n     puo'' contenere spazi, se fra virgolette.\n\n1.31 Versione registrata.\n\n1.32 Implementata l''opzione @{"-c" Link VarieOpt} per far restituire un codice di ritorno di 15\n     in caso di fallito checking (su segnalazione di Jay Ruyle).\n\n1.33 Versione registrata.\n\n1.34 Correzione di qualche bug. Nuove opzioni @{"-i e -I" Link VarieOpt}.\n\n1.35 Versione registrata.\n\n\n@endnode\n\n@node Cap08 "FUTURI SVILUPPI:"\n\n- MaPuS potra'' prendere da un file la lista dei file su cui operare.\n\n- Utilizzo di un migliore requester, mantenendo la compatibilita'' con il SO\n  1.3.\n\n- View dei banner.\n\n- Script per fallimento o riuscita del test (utile per BBS).\n\n- Aggiunta della data al tail e al front banner.\n\n- Possibilita'' di rendere random la scelta del banner da aggiungere (ottimo\n  per le BBS).\n\n\n@endnode\n\n@node Cap09 "RINGRAZIAMENTI:"\n\n\n\nMolte grazie a (in ordine alfabetico):\n\nAlex,  /\rc,  Atomos, Batblaster, Blulight, Caton, Crier, Deus, Doc, Doctor\nRevenge,  DR.Dream/FTH,  DR.G,  Exodus,  Fashion Light, Felix, Gandalf/FTH,\nGhost,  GiapDJ,  Godfather,  Guile, Highlander, Høøk/FTH, Jay Ruyle, Joseph\nHodge  (/X  author), Kenshiro, Kris, Laurent, Leo, LoneWolf, Mad Harlequin,\nMad  Lemming,  MAUI BBS (2:335/602@fidonet), /\/\aster T/4WD, Metalbasher!,\nMF   the  Best,  Modem  Boy,  Mondrian,  MR.IRQ,  MR.Swapper,  /\/ightmare,\n/\/ikita/4WD,  Nosferatu,  Pier, Pixie, Polaris, Pork, Pows, Randy, Sauzer,\nSeven  /\/\,  Shady,  Splatter, T-Rexx, The Outlaw, Top, Tron/RPK, Warrior,\nWoodelf, tutti i miei utenti, e tutti coloro che dimentico...\n\n\n@endnode\n\n@node Cap10 "CONTATTI:"\n\nPuoi contattarci (in Matrix) ai seguenti indirizzi:\n\n2:335/[email removed]\n\no via posta "classica" a:\n\n                             Antonino Pintaudi\n                                P.O. Box 11\n                         98125 Contesse (Messina)\n                                  ITALIA\n\n\noppure chiamando la *NUOVA* BBS di supporto:\n\n                              Delta City BBS\n                            +39-(0)931-760203\n                   [ Lasciare un messaggio ad "Eniac" ]\n@endnode\n\n@node ENG "MaPuS dox:"\n\n                             @{b}GENERAL INDEX:@{ub}\n\n@{" WARNING " Link Cap01E}\n@{" INTRODUCING MaPuS " Link Cap02E}\n@{" WHY SHOULD YOU USE MaPuS AND NOT ANOTHER CHECKER? " Link Cap03E}\n@{" HOW IT WORKS " Link Cap04E}\n@{" EXAMPLES " Link Cap05E}\n@{" USING OF MaPuS WITH AMIEXPRESS OR DLG " Link AXusoE}\n@{" GLOSSARY " Link Cap06E}\n@{" MaPuS UPDATES " Link Cap07E}\n@{" FUTURE FEATURES " Link Cap08E}\n@{" GREETINGS " Link Cap09E}\n@{" CONTACTS " Link Cap10E}\n\n@endnode\n\n@node Cap01E "PAY ATTENTION:"\n\n\nMaPuS is Shareware, you must register yourself if you use it regularly.\n\nThe registration charge is 15$. You can send it enclosed on the envelope\nor as cheque at the following address:\n\n\n                             Antonino Pintaudi\n                                P.O. Box 11\n                         98125 Contesse (Messina)\n                                  ITALY\n\nThe  original  archive  MaPuS???.LHA  (???  is the version number) can''t be\nmodified.  You can''t add or remove files except BBS advertisements.\n\nThe archive files list is the following:\n\n---\nbbs/fcheck/DMS                       ;@{"AmiExpress" Link AXusoE} config\nbbs/fcheck/DMS.info                  ;@{"AmiExpress v3.+" Link AXusoE} config\nbin/MaPuS.???                        ;Executable program (??? =n. of version)\nbin/MAPUS_NOTE.TXT                   ;Info about this version\nDLGConfig/Batch/UPLOAD1.BATCH        ;/\nDLGConfig/Text/Banner.displayme      ;| @{"DLG" Link AXusoE} Config\nDLGConfig/Text/PreDesc.txt           ;\\ndoc/MaPuS.GUIDE                      ;AmigaGuide ITALIAN & ENGLISH dox.\nlibs/arp.library                     ;arp.library V39.1\nMAPUS.LHA                            ;BackUp copy of this archive\n---\n\n   If  you  want  to include any your proposition for MaPuS in the archive,\nyou MUST contact the author; he''ll include your work into the next versions\nand he will thank you.\n\nNO-ONE  is  responsable  of  (remote) damages that MaPuS can create to your\nsystem.\n\nMaPuS is written entirely in @{i}Assembly@{ui}!\n\n@endnode\n\n@node Cap02E "INTRODUCING MaPuS:"\n\n\nWhat  is  MaPuS?  MaPuS is the ultimate solution for DMS files.  You can do\nall  you  want  on  these  files.  You can check them, make, remove and add\ntail, track, front banners; all in a good and functional way.\n\n@endnode\n\n@node Cap03E "WHY SHOULD YOU USE MaPuS AND NOT ANOTHER CHECKER?"\n\n\nSimple.   Some  doesn''t  work perfectly on all files, others don''t give you\nall  informations  about the file, and no-one lets you add your text files.\nMaPuS can be used with a @{"BBS" Link AXusoE} or into your @{"script files"\nLink  Cap05E} or simply to @{"check" Link Cap04E}\nyour DMS files.  MaPuS is 100% tested for these functions.\n\n@endnode\n\n@node Cap04E "HOW DOES IT WORK:"\n\nIf you invoke MaPuS with only his name, you''ll get the syntax:\n\nMaPuS [-<options>] FileName[.DMS] [DestFile]\n\nOptions:\n\n@{" Operations on front banners " Link FrontOptE}\n@{" Operations on track banners " Link TrackOptE}\n@{" Operations on tail banners " Link TailOptE}\n        @{" Other options " Link VarieOptE}\n\n\nIf you invoke MaPuS with the source file name only, the file will be tested\nand are printed on the screen many informations about it.\n\nYou can also specify wildcards in source file name:  *, ?, #?.\n\n@{b}Please update your MaPuS.cfg on every revision of MaPuS.@{ub}\n\n@endnode\n\n@node FrontOptE "Operations on front banners:"\n\n\n\n\n\n@{" a " Link OptaE} add a front banner.\n@{" r " Link OptrE} remove front banners.\n@{" m " Link OptmE} make a front banner.\n\n\n\n\n\n@endnode\n\n@node TrackOptE "Operations on track banners:"\n\n\n\n\n@{" t " Link OptaE} add a track banner.\n@{" k " Link OptrE} remove track banners.\n@{" n " Link OptmE} make a track banner.\n\n\n\n\n\n@endnode\n\n@node TailOptE "Operations on tail banners:"\n\n\n\n\n@{" A " Link OptaE} add a tail banner.\n@{" R " Link OptrE} remove tail banners.\n@{" M " Link OptmE} make a tail banner.\n\n\n\n\n@endnode\n\n@node OptaE "Add a banner:"\n\n\nSpecify  source  "FileName"  (with  or  without .DMS extention) and, if you\nwant, a destination file "DestFile".\n\nMaPuS  will  test  that  file  and  add  the  banner to the destination one\n(making,  so,  a  copy  of  the  source  file) or if the destination is not\nspecified to the source file directly.\n\nIf the source file name were absent, an ARP requester would appear.\n\n@{b}NOTE:@{ub} If you want to create the destination file in RAM: use the @{"s" Link VarieOptE} option.\n\n"FileName"  can  be  without  extention,  but  you MUST write the extention\nyourself in the destination file name.\n\n@endnode\n\n@node OptrE "Remove banners:"\n\nPass  source FileName and/or DestFile name and MaPuS will search and remove\nfront  banners and report to you operation results.  If no destination file\nwere specified, the banners would be stripped to the source file directly.\n\nIf you don''t specify FileName, an ARP requester will appear.\n\n@{b}NOTE:@{ub} If you use the RAM: specify the @{"s" Link VarieOpt} option.\n\n@endnode\n\n@node OptmE "Create banners:"\n\n\nPass  the  text  file  name  or a requester will appear and it will let you\nselect  a  filename  as  banner.   MaPuS  will  place in S:  a file, called\n"MaPuS.cfg".  Now you can add it to your DMS files.\n\nText file format is:  64 colums (with linefeed) for 16 lines.\n\n\n@endnode\n\n@node VarieOptE "Other options:"\n\n@{b} s @{ub}  -  Don''t check free space. You should use it if you work with RAM:\n\n@{b} v @{ub}  -  View DMS file informations only, and don''t check it.\n\n@{b} d @{ub}  -  Add to track banners the uploading date.\n\n@{b} g @{ub}  -  Show some greetings.\n\n@{b} u @{ub}  -  Use an ARP requester to select the DMS file.\n\n@{b} f @{ub}  -  Show informations about every track of the DMS file.\n\n@{b} c @{ub}  -  Activate return codes. If the checking fails a return code of\n        15 will be returned.\n\n@{b} i @{ub}  -  Don''t show informations.\n\n@{b} I @{ub}  -  Don''t show other informations.\n\n@endnode\n\n@node Cap05E "EXAMPLES:"\n\n1) Check a file:\n In this example I will suppose that you''ve a file in your DL: directory\ncalled TEST.DMS and you want to test it.\n\nType: MaPuS DL:TEST or MaPuS dl:TEST.dms\n\nit will be tested and you''ll get some infos about the file.\n\n2) Make a @{"tail banner" Link TailOptE}:\n\nType: MaPuS -M\n\n3) Add a @{"front banner" Link FrontOptE} and remove @{"tail" Link TailOptE} and @{"track banners" Link TrackOptE}:\n\nType: MaPuS -AskR dl:TEST.dms ram:newTEST.dms\n\n(Note @{"s" Link VarieOptE} option for RAM:)\n\n4) Test all files of a directory:\n\nMaPuS dl:*.dms or MaPuS dl:#?.dms\n\n@endnode\n\nCiao...\n\n@node AXusoE "/X or DLG using:"\n\n\nIf you want to use MaPuS with AmiExpress have a look at: @{b}bbs/fcheck/DMS@{ub}\n\n<----- THERE''s THE CONTENTS OF THE FILE ---------- CUT HERE ------------->\nMaPuS\n\nError\n<------------------------------------------------- CUT HERE ------------->\n\nNOTE: the 2nd line contains the options for MaPuS.\n\n@{b} REMEMBER: @{ub} The file must contains these 3 lines only!\n\nIf you''ve AmiExpress v3+ place file "DMS.info" into BBS:FCheck directory.\n\nThe  scripts  to  use  MaPuS with DLG are included in the archive, and they\nare:\n\nDLGConfig/Batch/UPLOAD1.BATCH\nDLGConfig/Text/Banner.displayme\nDLGConfig/Text/PreDesc.txt\n\n@endnode\n\n@node Cap06E "GLOSSARY:"\n\n@{"Tail Banner" Link TailOptE}: it''s a text file that will be appended to the end of file.\n             (it''s the last text that will be displayed unpacking)\n\n@{"Front Banner" Link FrontOptE}: it''s a text file that will be appended to the front of file.\n              (it''s the first text that will be displayed unpacking)\n\n@{"Track Banner" Link TrackOptE}: it''s the zero-track that will displayed as text file.\n\n@endnode\n\n@node Cap07E "MaPuS UPDATES:"\n\n0.** Sperimental versions never released.\n\n0.84 First public version.  For our decision, public versions don''t\n     implement @{"-k" Link TrackOptE} command.\n\n0.85 First registered version, got if you''ve called @{"DELTA CITY BBS" Link Cap10E}.\n\n0.86-0.91 Private versions.\n     Fixed some bugs: Before @{"-k" Link TrackOptE} command corrupted archives if there were\n     track and front banner.\n\n0.92 Public version.\n     New  option @{"-f" Link VarieOptE}.  If you specify it, MaPuS will show you informations\n     about every track.\n\n0.93 Registered version.\n\n0.94 Sperimental version never released.\n\n0.95 Shareware version.\n     Fixed a bug in @{"-f" Link VarieOptE} option (the infos were not displayed if the file\n     had been selected from requester).\n\n0.96 Shareware version.\n     Fixed a bug. Now MaPuS can be resident. Thanks to Felix for bug\n     reporting.\n\n0.97 Registered version.\n\n0.98-0.99 Private versions.\n\n1.00 Shareware version, not 100% beacause no one has registered his copy of\n     MaPuS! If you want the complete version you must pay the registration\n     fee or call @{"DELTA CITY BBS" Link Cap10E}.\n     Wildcards added (*,?,#?).  Speeded up stripping routine.\n     Docs  are  now  also  in Amiga-Guide format, that contains english and\n     italian ones. Archive structure modified.\n\n1.01 Registered version.\n\n1.02-1.09 Private versions.\n\n1.10 Special version released at SMAU 1993.  Added the uploading date\n     (useful for BBS) on track banners (use @{"-d" Link VarieOptE} option).  Now you can stop\n     MaPuS with CTRL-C (after the test).\n\n1.11 Registered version.\n\n1.12 Fixed a problem in @{"-t" Link TrackoptE} option. A bug made 1.10 not working on 68000\n     systems.\n\n1.13 Registered version.\n\n1.14 Fixed two problems:\n     1) If the filename started with a minus character the command line\n        parsing didn''t worked.\n     2) Sometimes the track banners adding did corrupt the archive.\n\n1.15 Registered version.\n\n1.16 Fixed two bugs:\n     1) If CTRL-C was pressed during a file check, the program crashed the\n        system.\n     2) Small command line bug.\n     Now MaPuS informations are compatible with DMS V1.51+.\n     Guide corrected, ASCII docs deleted.\n\n1.17 Registered version.\n\n1.18-1.29 Private, not released, versions.\n         Note: I saw a "1.20" version. This version hasn''t been created by us,\n         you shouldn''t use it..\n\n1.30 Fixed some bugs: now an empty file checking doesn''t do problems.\n\n     Now supporting "": file name can contain spaces, if between "".\n\n1.31 Registered version.\n\n1.32 Added return codes with @{"-c" Link VarieOptE} option. It  returns a code of 15 if the\n     checking fails. Signaled by Jay Ruyle.\n\n1.33 Registered version.\n\n1.34 Bug fixes. New options @{"-i and -I" Link VarieOptE}.\n\n1.35 Registered version.\n\n@endnode\n\n@node Cap08E "FUTURE FEATURES:"\n\n\n- MaPuS will take the file list to operate over from a text file.\n\n- Use of a better requester.\n\n- Banner display.\n\n- Scripts for failed or successful tests (useful for BBSes).\n\n- Date adding on tail and front banners.\n\n- MaPuS will select a random banner to add.\n\n\n@endnode\n\n@node Cap09E "GREETINGS:"\n\nMany thanks go to (alphabetic order):\n\nAlex,  /\rc,  Atomos, Batblaster, Blulight, Caton, Crier, Deus, Doc, Doctor\nRevenge,  DR.Dream/FTH,  DR.G,  Exodus,  Fashion Light, Felix, Gandalf/FTH,\nGhost,  GiapDJ,  Godfather,  Guile, Highlander, Høøk/FTH, Jay Ruyle, Joseph\nHodge  (/X  author), Kenshiro, Kris, Laurent, Leo, LoneWolf, Mad Harlequin,\nMad  Lemming,  MAUI BBS (2:335/602@fidonet), /\/\aster T/4WD, Metalbasher!,\nMF   the  Best,  Modem  Boy,  Mondrian,  MR.IRQ,  MR.Swapper,  /\/ightmare,\n/\/ikita/4WD,  Nosferatu,  Pier, Pixie, Polaris, Pork, Pows, Randy, Sauzer,\nSeven  /\/\,  Shady,  Splatter, T-Rexx, The Outlaw, Top, Tron/RPK, Warrior,\nWoodelf, all my users, all friends and all the ones I forget...\n\n@endnode\n\n@node Cap10E "CONTACTS:"\n\n\nYou can contact us (via NetMail) at these addresses:\n\n2:335/[email removed]\n\nor via "old" mail at:\n\n                             Antonino Pintaudi\n                                P.O. Box 11\n                         98125 Contesse (Messina)\n                                  ITALIA\n\n\nor calling the *NEW* support BBS:\n\n                              Delta City BBS\n                            +39-(0)931-760203\n                      [ Leave a message to "Eniac" ]\n@endnode\n\nWhere you''re looking in????\nFINE!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!\n','\n',char(10)),NULL,'auto-added',78949,5,0,NULL,NULL,'otl_m134','scan',1780048664);
INSERT INTO door_catalog VALUES('otm_cu11','OTM_CU11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OTM_CU11.LHA','MDB-ConfUpdater','XIM','MDB-ConfUpdater',NULL,NULL,'OTM','|  _____/\ _____/\  _____/\       THe      | |  \  _  / \  ___/ /  / \  \  GRaVeDiGGeRS | |  /\/ | \  \/ \  /  /\_/\  \              |',replace('.------------------------------------------.\n|  _____/\ _____/\  _____/\       THe      |\n|  \  _  / \  ___/ /  / \  \  GRaVeDiGGeRS |\n|  /\/ | \  \/ \  /  /\_/\  \              |\n| / /__|  \ /  /  \  \   /  / /X DeSiGn    |\n| \____/  / \  \   \__\ /  /  100% pure    |\n|      \_/   \_/        \_/   XIM-assembly |\n| >> Conference Updater 1.1 <<             |\n| * oTM * MDB PRoDuCTioNS * NiGHTCRaWLeR * |\n`------------------------------------------''\n','\n',char(10)),'ConfUpdater.GUIDE',replace('@database MDB-ConferenceUpdater 1.1\n\nCopyright (C) 1994 (MDB Productionc/OTM The Gravediggers) \nAll Rights Reserved\n\n@Remark $VER: Version V1.1 (13 Mrt 1994)\n@Remark AmigaGuide database for the ConferenceUpdater 1.1\n\n@node MAIN "MDB-ConferenceUpdater 1.1 AmigaGuide Document (C) 1994 (MDB Productions)"\n\n                         _____/\   ______/\  _____/\ \n                        /  / \  \  \  ___  \ \  ___ \\n                       /  /\_/\  \ /\/| /  / /\/ /  /\n                       \  \   /  //   |/  / /  |/   \\n                        \__\ /  / \___   /  \__|_   /\n                             \_/      \_/        \_/ \n\n                   MDB Productions  iS PRouD To PReSeNT :\n\n                  C O N F E R E N C E - U P D A T E R 1.1\n\n          ·:·C·O·N·T·E·N·T·S··O·F··D·O·C·U·M·E·N·T·A·T·I·O·N·:·\n\n                             @{"  INTRODUCTION  " LINK PART_01}\n                             @{"  REQUIREMENTS  " LINK PART_02}\n                             @{"  INSTALLATION  " LINK PART_03}\n                             @{"   TOOL-TYPES   " LINK PART_04}\n                             @{"    CHANGES!    " LINK PART_05}\n                             @{"     ADVERT     " LINK PART_06}\n@endnode\n\n@node PART_01 "Introduction"\n\nFor sysops it''s hard to keep their conferences up to date. This door\nchecks if the files stated in the catalogs still exist. If they don''t\nexists anymore, the filesize in the catalog will be changed to a text\nlike ''OFFLINE'', ''DELETED'' or something simular.\n\nThe door is very smart, so the less installation you have to do. It\nchecks the following icons BBS:CONFCONFIG and CONF<num>. Lets enjoy\nthis one.\n\n@endnode\n\n@node PART_02 "Requirements"\n\nWhat U need to run it...\n~~~~~~~~~~~~~~~~~~~~~~~~\n\n - an Amigamodel (A500/A600/A1200/A2000/A3000/A4000) with Kickstart 2.04++\n\n - the installed /X-Software (V3.20+) in the drawer BBS:\n\nNow let''s go on by explaining the @{"Installation" LINK PART_03}...\n\n@endnode\n\n@node PART_03 "Installation for ConfUpdater 1.1"\n\nHow to install it to your /X-System...\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nFirst make a Drawer into Doors: called ''MDB-ConfUpdater'' and copy the Files\n - ''MDB-ConfUpdater''\n - ''MDB-ConfUpdater.INFO''\ninto it.\n\nSecond copy the Icon ''CU.INFO'' into the BBSCmd Drawer.\n\nThats all there is. Simple he!\n\n@endnode\n\n@node PART_04 "ToolTypes for ConfUpdater 1.1"\n\n                                ToolTypes\n                                ~~~~~~~~~\n\n                    @{" TOOLTYPES FOR MDB-ConfUpdater 1.1" LINK PART_04_LC}\n\n                    @{" TOOLTYPES FOR CU                 " LINK PART_04_LO}\n\n@endnode\n\n@node PART_04_LC "ToolTypes for MDB-ConfUpdater 1.1\n\n                 ToolTypes for MDB-ConfUpdater 1.1\n                 ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nDELETE.num=<string>             - The DELETE.num tooltype specifies the text\n                                  that will be passed to your catalogs. The\n                                  maximum string length is 8 characters. Do\n                                  not overide this one. The maximum of\n                                  DELETE.num is 9.\n                                  Eg. DELETE.1=OFFLINE\n\nDESTINATION=<path>              - This tooltype specifies where the DIR<num>\n                                  catalogs will be stored. It is a backup-\n                                  mechanism, so you have to move them your\n                                  self to active them. The catalogs will be\n                                  be stored as CONF<num>_DIR<num>. The path\n                                  must end with a '':'' or a ''/'' like:\n                                  DESTINATION=RAM: or\n                                  DESTINATION=Work:Tmp/\n@endnode\n\n@node PART_04_LO "ToolTypes For CU"\n\n                       ToolTypes for CU\n                       ~~~~~~~~~~~~~~~~\n\nACCESS=<acs.level>              - This tooltype specifies the access level\n                                  that the user must have to run the door.\n                                  Eg. ACCESS=200\n\nLOCATION=<filename>             - This tooltype specifies where the Door\n                                  is located.\n                                  Eg. LOCATION=Doors:MDB-ConfUpdater/MDB-ConfUpdater\n\nMULTINODE=<YES|NO>              - This tooltype specifies if the Door may\n                                  started in different nodes.\n                                  Eg. MULTINODE=YES\n\nPRIORITY=<num>                  - This tooltype specifies the AmigaDos\n                                  priority when the Door is executed.\n                                  Eg. PRIORITY=2\n\nSTACK=<size>                    - This tooltype specifies the Door stack.\n                                  Eg. STACK=8096\n\nTYPE=<AIM|SIM|TIM|XIM>          - This tooltype specifies the Door-type.\n                                  This Door is written in 100% pure\n                                  Assembly so TYPE=XIM\n\n@endnode\n\n@node PART_05 "Changes"\n\n1.1 (13 Mar 1994) \n    - The term ''catalog'' changed to ''dir'' for better understanding\n      for some persons.\n    - Using ANSI-codes instead of CSI-codes. The screens must work\n      remote now!\n\n@endnode\n\n@node PART_06 "Death Simple ... OTM The GraveDiggers"\n\n/X 3.3+    :+                   WELCOME TO                            /X 3.3+\n          .::.       ____________  ______________._          .+.\n         .:+.       |__  \  ____/ / _ \      _/  | \         .:.\n   AscII  +::+.     |  \  \  .)\_/     \/   | |  |  \       ::+.    AscII\n \  B Y  /   :.     |  /   \ |  |   :   \   | |  _   \     :+:.  \   B Y   /\n _\ MSW /_          |______/\___|\__|___/\__| |__|___/     .     _\  MSW  /_ \n-=-=-=-=-=-=-=-         -=-            -=-=-=-=-             -=-=-=-=-=--=-=-\n.°*DEATH                                                             DEATH*°.\n   SIMPLE*°.                                                      .°*SIMPLE\n=-=-=-               -=-=-=-=-=-=-=-            -=-=-          -=-=-=   -=-=-\n                ___/\____/\  __ _/\  /\_____/\__      /\____\n-24 HoUrS      /     \____/ /  Y   \/___  _ \  |     /  .  |    ..::.\n-chataBle     /   ___/    \/   :    \  / ___/  |__  /   |__|     +::.+\n-SysOp        \___   \____ \___ ____ \/  |\  __|  \/_    __/   .+::+\n-CeWl Area''s  /   \__/    \/   Y    \/\__| \/      \ \__/  \   .:\n              \  ___/\____/\___|__  /__  |  \______ \____  /\n               \/                 \/   \/          \/    \/ +31-(0)2152-68786\n\n    __/\__ __ ___ _ _ _   :-)   2 OPERATOR 2  (-:      ___ __ __ __/\__\n    \ Oo /__ ______ _ _       ~~~~~~~~~~~~~~~          __ __ __\ oO /\n    /_--_\__ ___ __ __       2-)  COSYSOP  (-2        __ ____ _ _/_--_\\n      \/                                                           \/\n\n@endnode\n','\n',char(10)),'{"ACCESS":"<acs.level>","LOCATION":"<filename>","PRIORITY":"<num>","STACK":"<size>","TYPE":"<AIM|SIM|TIM|XIM>"}','auto-added',16387,7,0,NULL,NULL,'otm_cu11','scan',1780048664);
INSERT INTO door_catalog VALUES('otm_cu13','OTM_CU13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OTM_CU13.LHA','MDB-ConfUpdater','XIM','MDB-ConfUpdater',NULL,NULL,'OTM','|  _____/\ _____/\  _____/\       THe      | |  \  _  / \  ___/ /  / \  \  GRaVeDiGGeRS | |  /\/ | \  \/ \  /  /\_/\  \              |',replace('.------------------------------------------.\n|  _____/\ _____/\  _____/\       THe      |\n|  \  _  / \  ___/ /  / \  \  GRaVeDiGGeRS |\n|  /\/ | \  \/ \  /  /\_/\  \              |\n| / /__|  \ /  /  \  \   /  / /X DeSiGn    |\n| \____/  / \  \   \__\ /  /  100% pure    |\n|      \_/   \_/        \_/   XIM-assembly |\n| >> Conference Updater 1.3 <<             |\n| >> Including ''Erase entry'' action <<     |\n| * oTM * MDB PRoDuCTioNS * NiGHTCRaWLeR * |\n`------------------------------------------''\n','\n',char(10)),'ConfUpdater.GUIDE',replace('@database MDB-ConferenceUpdater 1.3\n\nCopyright (C) 1994 (MDB Productionc/OTM The Gravediggers) \nAll Rights Reserved\n\n@Remark $VER: Version V1.3 (13 Mar 1994)\n@Remark AmigaGuide database for the ConferenceUpdater 1.3\n\n@node MAIN "MDB-ConferenceUpdater 1.3 AmigaGuide Document (C) 1994 (MDB Productions)"\n\n                         _____/\   ______/\  _____/\ \n                        /  / \  \  \  ___  \ \  ___ \\n                       /  /\_/\  \ /\/| /  / /\/ /  /\n                       \  \   /  //   |/  / /  |/   \\n                        \__\ /  / \___   /  \__|_   /\n                             \_/      \_/        \_/ \n\n                   MDB Productions  iS PRouD To PReSeNT :\n\n                  C O N F E R E N C E - U P D A T E R 1.3\n\n          ·:·C·O·N·T·E·N·T·S··O·F··D·O·C·U·M·E·N·T·A·T·I·O·N·:·\n\n                             @{"  INTRODUCTION  " LINK PART_01}\n                             @{"  REQUIREMENTS  " LINK PART_02}\n                             @{"  INSTALLATION  " LINK PART_03}\n                             @{"   TOOL-TYPES   " LINK PART_04}\n                             @{"    THE DOOR    " LINK PART_05}\n                             @{"    CHANGES!    " LINK PART_06}\n                             @{"     ADVERT     " LINK PART_07}\n@endnode\n\n@node PART_01 "Introduction"\n\nIntroduction...\n~~~~~~~~~~~~~~~\nFor sysops it''s hard to keep their conferences up to date. This door\nchecks if the files stated in the catalogs still exist. If they don''t\nexists anymore, the filesize in the catalog will be changed to a text\nlike ''OFFLINE'', ''DELETED'' or something simular.\n\nThe door is very smart, so the less installation you have to do. It\nchecks the following icons BBS:CONFCONFIG and CONF<num>. Lets enjoy\nthis one.\n\n@endnode\n\n@node PART_02 "Requirements"\n\nWhat U need to run it...\n~~~~~~~~~~~~~~~~~~~~~~~~\n\n - an Amigamodel (A500/A600/A1200/A2000/A3000/A4000) with Kickstart 2.04++\n\n - the installed /X-Software (V3.20+) in the drawer BBS:\n\nNow let''s go on by explaining the @{"Installation" LINK PART_03}...\n\n@endnode\n\n@node PART_03 "Installation for ConfUpdater 1.3"\n\nHow to install it to your /X-System...\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nFirst make a Drawer into Doors: called ''MDB-ConfUpdater'' and copy the Files\n - ''MDB-ConfUpdater''\n - ''MDB-ConfUpdater.INFO''\ninto it.\n\nSecond copy the Icon ''CU.INFO'' into the BBSCmd Drawer.\n\nThats all there is. Simple he!\n\n@endnode\n\n@node PART_04 "ToolTypes for ConfUpdater 1.3"\n\n                                ToolTypes\n                                ~~~~~~~~~\n\n                    @{" TOOLTYPES FOR MDB-ConfUpdater 1.3" LINK PART_04_LC}\n\n                    @{" TOOLTYPES FOR CU                 " LINK PART_04_LO}\n\n@endnode\n\n@node PART_04_LC "ToolTypes for MDB-ConfUpdater 1.3\n\n                 ToolTypes for MDB-ConfUpdater 1.3\n                 ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nDELETE.num=<string>             - The DELETE.num tooltype specifies the text\n                                  that will be passed to your catalogs. The\n                                  maximum string length is 8 characters. Do\n                                  not overide this one. The maximum of\n                                  DELETE.num is 9.\n                                  Eg. DELETE.1=OFFLINE\n\nDESTINATION=<path>              - This tooltype specifies where the DIR<num>\n                                  catalogs will be stored. It is a backup-\n                                  mechanism, so you have to move them your\n                                  self to active them. The catalogs will be\n                                  be stored as CONF<num>_DIR<num>. The path\n                                  must end with a '':'' or a ''/'' like:\n                                  DESTINATION=RAM: or\n                                  DESTINATION=Work:Tmp/\n@endnode\n\n@node PART_04_LO "ToolTypes For CU"\n\n                       ToolTypes for CU\n                       ~~~~~~~~~~~~~~~~\n\nACCESS=<acs.level>              - This tooltype specifies the access level\n                                  that the user must have to run the door.\n                                  Eg. ACCESS=200\n\nLOCATION=<filename>             - This tooltype specifies where the Door\n                                  is located.\n                                  Eg. LOCATION=Doors:MDB-ConfUpdater/MDB-ConfUpdater\n\nMULTINODE=<YES|NO>              - This tooltype specifies if the Door may\n                                  started in different nodes.\n                                  Eg. MULTINODE=YES\n\nPRIORITY=<num>                  - This tooltype specifies the AmigaDos\n                                  priority when the Door is executed.\n                                  Eg. PRIORITY=2\n\nSTACK=<size>                    - This tooltype specifies the Door stack.\n                                  Eg. STACK=8096\n\nTYPE=<AIM|SIM|TIM|XIM>          - This tooltype specifies the Door-type.\n                                  This Door is written in 100% pure\n                                  Assembly so TYPE=XIM\n\n@endnode\n\n@node PART_05 "The Door"\nThe Door...\n~~~~~~~~~~~\nhe works very simple, just follow the menus. The header gives some\ninformation about your bbs. The name of your board, the current conference\nnumber and name, and at least the maximum dir number will be showed.\n\nAt the right-hand of the menu you can find the text options and action. \nThe former value will be put in your DIR<num> file when you update the\ndir and the occurence doesn''t exists. The latter will delete the occurence\nin DIR<num>.\n\nBelow the header information you see the actions you can do:\n A  Shows some little information about us.\n D  Allows you to change the DIR<num> file you want to process. The\n    maximum value in the number stated in the header (No of dirs).\n U  This one actually updates the DIR<num>.\n Q  Goes without saying!\n -  Decreases the DIR<num> by 1.\n -  Increases the DIR<num> by 1.\n\n@endnode\n\n@node PART_06 "Changes"\n\nChanges...\n~~~~~~~~~~\n.3 (16 Mar 1994)\n    - Faster screenhandling.\n    - New action available, directory occurences will be deleted when\n      the file is not available.\n\n1.2 (14 Mar 1994)\n    - Returncode $a removed. This value meant LINE DOWN in stead\n      of NEW LINE in ANSI-codes.\n\n1.1 (13 Mar 1994) \n    - The term ''catalog'' changed to ''dir'' for better understanding\n      for some persons.\n    - Using ANSI-codes instead of CSI-codes. The screens must work\n      remote now!\n\n@endnode\n\n@node PART_07 "Death Simple ... OTM The GraveDiggers"\n\n/X 3.3+    :+                   WELCOME TO                            /X 3.3+\n          .::.       ____________  ______________._          .+.\n         .:+.       |__  \  ____/ / _ \      _/  | \         .:.\n   AscII  +::+.     |  \  \  .)\_/     \/   | |  |  \       ::+.    AscII\n \  B Y  /   :.     |  /   \ |  |   :   \   | |  _   \     :+:.  \   B Y   /\n _\ MSW /_          |______/\___|\__|___/\__| |__|___/     .     _\  MSW  /_ \n-=-=-=-=-=-=-=-         -=-            -=-=-=-=-             -=-=-=-=-=--=-=-\n.°*DEATH                                                             DEATH*°.\n   SIMPLE*°.                                                      .°*SIMPLE\n=-=-=-               -=-=-=-=-=-=-=-            -=-=-          -=-=-=   -=-=-\n                ___/\____/\  __ _/\  /\_____/\__      /\____\n-24 HoUrS      /     \____/ /  Y   \/___  _ \  |     /  .  |    ..::.\n-chataBle     /   ___/    \/   :    \  / ___/  |__  /   |__|     +::.+\n-SysOp        \___   \____ \___ ____ \/  |\  __|  \/_    __/   .+::+\n-CeWl Area''s  /   \__/    \/   Y    \/\__| \/      \ \__/  \   .:\n              \  ___/\____/\___|__  /__  |  \______ \____  /\n               \/                 \/   \/          \/    \/ +31-(0)2152-68786\n\n    __/\__ __ ___ _ _ _   :-)   2 OPERATOR 2  (-:      ___ __ __ __/\__\n    \ Oo /__ ______ _ _       ~~~~~~~~~~~~~~~          __ __ __\ oO /\n    /_--_\__ ___ __ __       2-)  COSYSOP  (-2        __ ____ _ _/_--_\\n      \/                                                           \/\n\n@endnode\n','\n',char(10)),'{"ACCESS":"<acs.level>","LOCATION":"<filename>","PRIORITY":"<num>","STACK":"<size>","TYPE":"<AIM|SIM|TIM|XIM>"}','auto-added',33173,11,0,NULL,NULL,'otm_cu13','scan',1780048664);
INSERT INTO door_catalog VALUES('ott_pmc','OTT-PMC.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OTT-PMC.LHA','Pro-MultiCheck_020','XIM','Pro-MultiCheck_020',NULL,NULL,'OTT','/   .   \___    __!__    ___/   o.V.E.R  | /    !    \/      \:/      \     t.H.E    ! \_________/\______/:\______/     t.O.P    |',replace('   _________________________________________\n  /   .   \___    __!__    ___/   o.V.E.R  |\n /    !    \/      \:/      \     t.H.E    !\n \_________/\______/:\______/     t.O.P    |\n                                           :\n    o\/eR tHe tOp is proud to present       \nPro-MultiCheck 0.91 DMS and LHA file checker\n           Minor update to 0.9ß\n','\n',char(10)),'Pro-MultiCheck.Guide',replace('@database Pro-MultiCheck.guide\n@$VER: Pro-MultiCheck.guide v0.91 (17-Sep-94)\n@width 75\n\n@node MAIN "Pro-MultiCheck Contents"\n                    @{u}Documents for Pro-MultiCheck v0.91@{uu}\n\n          Pro-MultiCheck was written by Exodous/TLS, XPR & O.T.T\n                           Released on 17-Sep-94\n\n                     1)  @{" What is Pro-MultiCheck ? " link WHAT_IS_PMC}\n                     2)  @{"       Installation       " link PMC_INSTALL}\n                     3)  @{"    How do I use PMC ?    " link USAGE}\n                     4)  @{"       Distribution       " link DISTRIBUTION}\n                     5)  @{" Registration Information " link REGISTRATION}\n                     6)  @{"     Future Versions      " link FUTURE}\n                     7)  @{"      Contacting Me       " link CONTACT_ME}\n                     8)  @{"         History          " link HISTORY}\n                     9)  @{"      Other Programs      " link OTHER_PROGS}\n                     10) @{"     Acknowledgements     " link ACKNOWLEDGE}\n                     11) @{"        Disclaimer        " link DISCLAIMER}\n                     12) @{"     Registered Users     " link REG_USERS}\n\n               Pro-MultiCheck was written in 100% assembler.\n@endnode\n\n@node WHAT_IS_PMC "What is Pro-MultiCheck"\n                         @{u}What is Pro-MultiCheck ?@{uu}\n\nPro-MultiCheck is (c) 1994 TLS Software and may only be distributed if\nthe appropriate @{" distribution " link DISTRIBUTION} conditions are met.\n\nPro-MultiCheck (PMC) is a file checking program aimed for use by Bulletin\nBoard Systems (BBS''s).\n\nIt''s main aim is to check a lots of different file formats simply in one\nprogram, using a consistent interface.\n\nI think that PMC is unique in the fact that it is the first file checker\nthat can handle multiple file types.\n\nCurrently Pro-MultiCheck is that fastest LhA and DMS checker / stripper\n                                 ^^^^^^^\navailable on the Amiga.\n\nAs this is only version 0.9ß it isn''t as optimised, or as fast as it\ncould be, but for version 1.0 LhA checking, stripping and adding will\nbe significantly faster - I estimate at least 50% faster!!, and PMC will\nbe able to handle other file types.\n\nSee @{" Future versions " link FUTURE} for information on planned features.\n\nThe LHA section covers LHA, LZH, SFX and RUN files.\n\nThe Pro-MultiCheck package was developed in 680x0 assembly language using\nthe following software :\n\n                · Devpac 3.04\n                · CygnusEd Professional\n                · MultiView\n                · Installer 2.15.\n\nPro-MultiCheck needs Kickstart and Workbench 2.04 or better.\nPro-MultiCheck_020 also needs a Motorola 68020 or better CPU fitted to\n yor Amiga.\n\n@endnode\n\n@node PMC_INSTALL "How do I install Pro-MultiCheck ?"\n                     @{u}How do I install Pro-MultiCheck ?@{uu}\n\n@{b}NOTE@{ub} : Pro-MultiCheck v1.0 will come with an installer script for easy\n       installation of Pro-MultiCheck.\n\n                           @{u}General instructions@{uu}\n\nPro-MultiCheck currently needs LhA, by Stefan Boberg, to check LhA files.\n\nMake sure that your LhA file is @{b}NOT@{ub} crunched, if it is then\ndecrunch it, otherwise Pro-MultiCheck will crash.\n\nIf your LhA executable doesn''t reside in the ''C:'' directory then add the\nfollowing line to your ''S:User-Startup'' :\n\n        SetEnv PMC "<location of LhA>"\n\nWhere @{b}<location of LhA>@{ub} is where your LhA executable can be found, eg :\n\n        SetEnv PMC "Work:Utilities/LhA"\n\n\nIf you have a Motorola 68020 processor or better then delete\n''Pro-MultiCheck'' and rename ''Pro-MultiCheck_020'' as ''Pro-MultiCheck''\n\n\n                           @{u}Specific instructions@{uu}\n\nInstallation instructions for :\n\n                       @{" Ami-Express 3.x - 4.x " link INSTALL_AX3}\n                       @{"  CLI or Shell Usage   " link INSTALL_SHELL}\n\nIn version 1.0 there will be documentation on how to install PMC for\nother BBS systems, if you sucessfully install it for a BBS system not\nlisted above then please @{" e-mail " link CONTACT_ME} details to me so that I can put them\nin this documentation.\n\n@endnode\n\n@node INSTALL_AX3 "Installation instructions for Ami-Express 3.x - 4.x"\n            @{u}Installation instructions for Ami-Express 3.x - 4.x@{uu}\n\nType the following lines into a CLI/Shell screen.\n\n1> Copy S/#? all S: QUIET\n1> Copy AX3/#? all BBS: QUIET\n1> Copy Pro-MultiCheck DOORS:\n\nTo change the checking options go into your BBS:FCheck drawer, select the\nicon for the filetype, and select ''Information'' from the menu''s, find the\nline that says ''OPTIONS='' and type in your selected options.\n\nTo edit the banners / adverts to suit your needs see @{" Editing adverts " link EDIT_ADS}.\n\n@endnode\n@node INSTALL_SHELL "Installation instructions for CLI or Shell usage"\n             @{u}Installation instructions for CLI or Shell usage@{uu}\n\nType the following lines into a CLI/Shell screen.\n\n1> Copy S/#? all S: QUIET\n1> Copy Pro-MultiCheck  C:\n\nTo edit the banners / adverts to suit your needs see @{" Editing adverts " link EDIT_ADS}.\n\n@endnode\n\n@node EDIT_ADS "Editing adverts and banners to suit your needs"\n              @{u}Editing adverts and banners to suit your needs@{uu}\n\nOpen a CLI and got to the ''S:PMC'' directory.\n\n@{u}LHA Adverts@{uu}\n\nThe adverts that are added to an LHA file are in the LHA directory,\nthese can be anything from a text file to a 300k demo (not recommended!)\n\nIf any of the files start with ''PMC'', eg ''PMC.txt'' or ''PMC.exe'', when\nthey are added the ''PMC'' will be replaced with a 6 digit random number,\nthis has the advantage that it makes ripping them @{b}VERY@{ub} difficult!\n\nThe file ''LHA.Strip'' is used to store adverts in that PMC doesn''t already\nknow. To add an advert, load the file into an editor, eg CygnusEd and add\nit to the bottom of the file.\n\nIf the advert contains wildcards ( ''*'', ''#'', or ''?'' ), eg ''-?-?-?-'' then\nput square brackets round each wildcard... ''-[?]-[?]-[?]-''\n\n\n@{u}DMS Adverts@{uu}\n\nThe banners that are added to a DMS file are in the DMS directory.\n\nThe following file should be present :\n\n        ''Banner_Front''\n        ''Banner_Rear''\n        ''Track_Zero''\n\nThe files ''Banner_Front''and ''Banner_Rear'' are added to the front and rear\nof the DMS file respectively and should be normal text files.\n\nThe file ''Track_Zero'' is added as the track zero and @{b}MUST@{ub} be 960 bytes\nlong. It should be 15 lines long and 64 characters wide (including the\nreturn character at the end of the line) so that it is display correctly\nwhen the archive is decrunched.\n\n@endnode\n\n@node USAGE "How do I use Pro-MultiCheck ?"\n                       @{u}How do I use Pro-MultiCheck ?@{uu}\n\nTo use Pro-MultiCheck to check an @{b}LHA@{ub} file type the following :\n\nPro-MultiCheck LHA [OPTIONS] <filename>\n\n  @{b}<filename>@{ub} is the file to check and @{b}[OPTIONS]@{ub} are an optional choice\n  from any of these choices :\n\n        @{b}KILL@{ub}    - Remove existing BBS adverts.\n        @{b}ADD@{ub}     - Add your own BBS''s adverts.\n        @{b}COMMENT@{ub} - Add a file comment to the added adverts containing\n                   the date and time that the file was checked.\n\n\nTo use Pro-MultiCheck to check an @{b}DMS@{ub} file type the following :\n\nPro-MultiCheck DMS [OPTIONS] <filename>\n\n  @{b}<filename>@{ub} is the file to check and @{b}[OPTIONS]@{ub} are an optional\n  choice from any of these choices :\n\n        @{b}FRONT@{ub}    - Add a front banner to the file.\n        @{b}REAR@{ub}     - Add a rear banner to the file.\n        @{b}TRACK@{ub}    - Add a track zero banner to the file.\n        @{b}DATE@{ub}     - Add the date and time that the files was checked\n                   to any of the banners, replacing ''##-###-##'' with the\n                   date, and ''##:##'' with the time.\n\n@{b}Examples@{ub}\n\nCheck an LhA file called ''TLS-PMC.LHA''.\n\n    Pro-MultiCheck LHA TLS-PMC.LHA\n\nCheck an LhA file called ''TLS-PMC.LHA'', kill all known adverts from the\nfile, add out own adverts, and add the date/time of the check to the\nadded adverts comments.\n\n    Pro-MultiCheck LHA KILL ADD COMMENT TLS-PMC.LHA\n\nCheck a DMS file called ''DEMO.DMS'', and remove existing banners.\n\n    Pro-MultiCheck DMS demo.dms\n\nCheck a DMS file called ''ABC D.DMS'', remove existing banners and add\nour own banners, with the date and time of upload.\n\n    Pro-MultiCheck DMS FRONT REAR TRACK DATE ABC D.DMS\n\nor\n\n    Pro-MultiCheck DMS FRONT REAR TRACK DATE "ABC D.DMS"\n\n@{b}NOTE@{ub} : The filename @{b}MUST@{ub} be the last item on the line, but it doesn''t\n        have to have quotes round it if it contains spaces.\n\n@endnode\n\n@node DISTRIBUTION "Distribution information"\n                         @{u}Distribution information@{uu}\n\nPro-MultiCheck can be distributed in @{b}ANY@{ub} way as long as @{b}NO MONEY@{ub} changes\nhands, obvoiusly this rules out PD libraries.... do I really need to\nspell it out?? here it is anyway!\n\n             PD libraries @{b}MUST NOT@{ub} distribute Pro-MultiCheck.\n\nAlso on-line systems which charge users, either to connect, or have\non-line charges, @{b}MUST NOT@{ub} distribute Pro-MultiCheck.\n\nExamples of these types of system are :\n\n                   CompuServe Information Service (CIS)\n                   Compulink Information eXchange (CIX)\n\n@endnode\n\n@node REGISTRATION "Registration information"\n                         @{u}Registration information@{uu}\n\nRegistration of Pro-MultiCheck is @{b}FREE@{ub} (ie @{b}NO CHARGE@{ub})\n\nUnlike PrO-DmScHeCk and PrO-MuLtIcHeCk @{b}I AM NOT@{ub} going to make future\nversions disabled in any way so that you have to register.\n\nI am offering a form of registration whereby you e-mail me the following\n''form'' :\n\n--------------------------------------------------------------------------\n\nBBS name      : _____________________     Include BBS information\nBBS number(s) : _____________________      in PMC''s documentation  YES/NO\n                _____________________\n                _____________________\nSysops handle\n     or name  : _____________________\n\nBBS Software  : _____________________\n\nComments regarding version 0.9ß or Pro-MultiCheck\n        __________________________________________________________\n        __________________________________________________________\n        __________________________________________________________\n        __________________________________________________________\n        __________________________________________________________\n\nComments / features you would like to see in future versions\n        __________________________________________________________\n        __________________________________________________________\n        __________________________________________________________\n        __________________________________________________________\n        __________________________________________________________\n\n--------------------------------------------------------------------------\n\nWhen I recieve the form, your BBS name and number, and your handle will\nbe added to the documentation (if you want) ..... - ''@{b}free@{ub}'' publicity!!!!,\nand I will take into account your comments / suggestions regarding\nPro-MultiCheck when developing future versions.\n\n@endnode\n\n@node FUTURE "Planned features for future versions"\n                   @{u}Planned features for future versions@{uu}\n\n@{u}Planned features for version 1.0@{uu}\n\n        · LhA stripping and adding speed improved by at least 50%.\n\n        · Text checking and stripping (another unique feature!!).\n\n        · Amiga executable hunk checking.\n\n@{u}Planned features for version 2.0@{uu}\n\n        · Improve LhA checking by removing the need for the LhA\n          executable. I have already got LhA decompression working\n          in a beta form - ie it needs testing and optimising, but\n          after preliminary tests it''s at least 50% faster than LhA\n          at decompressing archives!!\n\n        · FILE_ID advert adding / stripping.\n\n@{u}Planned features for version 3.0@{uu}\n\n        · Advert adding to Amiga executable files.\n\n        · ZIP checking.\n\nIf you would like any features not mentioned above, or have any\nsuggestions on how the above features should work then @{" e-mail " link CONTACT_ME} me.\n\n@endnode\n\n@node CONTACT_ME "How to contact Exodous"\n                             @{u}How to contact me@{uu}\n\nI can be contacted on the following BBS''s as ''Exodous''\n\nQ.E.D       : +44 (0)91-372-1911 ( 2 nodes - 28.8DS )\n              Sysop : Grasshopper\n\nThe Tower   : +44 (0)204-384-543 ( 2 nodes ringdown - 14.4DS )\n              Sysop : FireFlash\n\nWelsh Coast : +44 (0)792-561-196 ( 1 node 28.8DS )\n              Sysop : Sonny\n\nOr via internet :\n\n     [email removed]   (until early October)\n  or [email removed]            (after October 3rd)\n\n@endnode\n\n@node HISTORY "The history of Pro-MultiCheck"\n                         @{u}History of Pro-MultiCheck@{uu}\n\n| Ver   | Date          | Comment\n+-------+---------------+--------------------------------------------\n| 0.9ß  | 03-Sep-94     | First release version.\n+-------+---------------+--------------------------------------------\n| 0.91  | 17-Sep-94     | Fixed the bug that allowed track 0''s to be\n|       |               | added to any part of a multi-disk DMS file.\n+-------+---------------+--------------------------------------------\n@endnode\n\n@node OTHER_PROGS "Other programs that I have written"\n           @{u}Here is a list of other programs that I have written@{uu}\n\n@{b}BootUte@{ub}        : Degrader type utility for @{i}newer@{ui} Amiga''s....\n                 Needs Kickstart 2.0+. Features easy to use gadtools\n                 interface.\n\n@{b}BullRead@{ub}       : Bulletins door for /X that allows users to search\n                 bulletins while they are on-line, or download the bulletins\n                 for viewing whilst off-line.\n\n@{b}X-Zippy@{ub}        : Replacement zippy search door for /X that can search\n                 for multiple items at a time, about 3 times faster\n                 than the built in zippy!!\n\n@{b}UserCom@{ub}        : Door for /X that allows users to make comments to files\n                 so that others will know if the file is old, fake etc.\n\n@{b}PrO-DmScHeCk@{ub}   : DMS file checker - for user with most BBS systems.\n                 Strips and adds front, rear and track texts.\n\n@{b}PrO-LhAcHeCk@{ub}   : LHa file checker - for user with most BBS systems.\n                 Strips most other adverts and adds own adverts that are\n                 virtually unstrippable.\n\n@{b}PrO-LogInfo@{ub}    : An Ami-Express door to inform on-line users when another\n                 user logs on to, or off from, another node.\n\n@{b}Decrunch@{ub}       : CLI based decruncher to decrunch loads of different\n                 packed files.\n\n@{b}PPPatch@{ub}        : PowerPacker Patcher... Patches the headers of PowerPacked\n                 files so that they can''t be decrunched.\n\n@{u}Projects I''m working on@{uu}\n\n@{b}BootUte 2@{ub}      : Updated version of BootUte, but a @{b}LOT@{ub} better.\n\n@{b}Pro-NewUser@{ub}    : Ami-Express new user questionnaire door that doesn''t\n                 let new users skip questions, they have to insert something\n                 ''intelligent'', eg phone numbers can only have certain\n                 characters in them..\n\nIf you have any suggestions for features that you would like to see in\nany of the programs then e-mail me with your suggestions.\n\n@endnode\n\n@node ACKNOWLEDGE "Acknowledgements, Copyrights and Trademarks."\n                @{u}Acknowledgements, Copyrights and Trademarks@{uu}\n\n@{u}Copyrights@{uu}\n\nLhA             (c) Copyright 1991,1992 Stefan Boberg.\nDMS             (c) Copyright 1993-94 Parcon Software\nDevpac          (c) Copyright 1985-93 Hisoft.\nCygnusEd        (c) Copyright 1987-1991 CygnusSoft Software.\nMultiView       (c) Copyright 1991-1993 Commodore-Amiga Inc.\nInstaller       (c) Copyright 1991-93 Commodore-Amiga Inc.\n\nBootUte         (c) Copyright 1993-94 TLS Software.\nPPPatch         (c) Copyright 1993-94 TLS Software.\nBootUte 2       (c) Copyright 1994 TLS Software\nPro-MultiCheck  (c) Copyright 1994 TLS Software.\n\n@{u}Trademarks@{uu}\n\nKickstart and Workbench are trademarks of Commodore-Amiga Inc.\n\n@{u}Acknowledgements@{uu}\n\nI acknowledge all other copyrights and trademarks not specifically stated\nin this documentation, and in the entire Pro-MultiCheck package.\n\n@endnode\n\n@node DISCLAIMER "Disclaimer"\n                                @{u}Disclaimer@{uu}\n\nThis software is provided "as is" without warranty of any kind, either\nexpressed or implied. By using it, you agree to accept the entire risk as\nto the quality and performance of the program. Should the software prove\ndefective, you assume the cost of all necessary servicing, repair or\ncorrection.\n\n@endnode\n\n@node REG_USERS "Registered users"\n                         @{u}List of registered users@{uu}\n\nGrasshopper     : Q.E.D         +44 (0)91-372-1911\nFireFlash       : The Tower     +44 (0)204-384-543\nSonny           : Welsh Coast   +44 (0)792-561-196\n\n@endnode\n','\n',char(10)),NULL,'auto-added',45512,5,0,NULL,NULL,'ott_pmc','scan',1780048664);
INSERT INTO door_catalog VALUES('ott_dms','OTT_DMS.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OTT_DMS.LHA','PrO-DmScHeCk','XIM','PrO-DmScHeCk',NULL,NULL,'OTT','/   .   \___    __!__    ___/   o.V.E.R | /    !    \/      \:/      \     t.H.E   ! \_________/\______/:\______/     t.O.P.! |',replace('    _________________.__________           :\n   /   .   \___    __!__    ___/   o.V.E.R |\n  /    !    \/      \:/      \     t.H.E   !                                            \n  \_________/\______/:\______/     t.O.P.! |\n                                            \n/X UTILS DIV.     EL?`--------->   <-------''\n   -== PrO-DmScHeCk v1.0 - DMS checker ==-  \n   -==   Fastest DMS checker around    ==-  \n®®®---------- ®®® MEN-TEL BBS ®®®--------®®®\n','\n',char(10)),'PrO-DmScHeCk.Guide',replace('@database PrO-DmScHeCk.guide\n@$VER: PrO-DmScHeCk.guide v1.0 (15-Jun-94)\n\n@node MAIN "PrO-DmScHeCk Contents"\n            @{b}@{u}Documents for PrO-DmScHeCk v1.0@{ub}@{uu}\n\n             PrO-DmScHeCk was written by Exodous/TLS & XPress\n                           Released on 15-Jun-94\n\n                      1)  @{" What is PrO-DmScHeCk ? " link WHAT_IS_PDC}\n                      2)  @{" Command line options   " link PDC_OPTS}\n                      3)  @{" Installation           " link INSTALLATION}\n                      4)  @{" Distribution           " link DISTRIBUTION}\n                      5)  @{" Greetings              " link GREETINGS}\n                      6)  @{" Contacting me          " link CONTACTING_ME}\n                      7)  @{" Call These BBS''s       " link BBS_ADS}\n                      8)  @{" History                " link HISTORY}\n                      9)  @{" Other programs         " link OTHER_PROGS}\n\n                PrO-DmScHeCk was written in 100% assembler.\n@endnode\n\n@node WHAT_IS_PDC "What is PrO-DmScHeCk"\n                     @{u}What is PrO-DmScHeCk ?@{uu}\n\nPrO-DmScHeCk is a DMS file checker meant to be run from a BBS when a\nDMS file has been uploaded.\n\nIt allows other BBS adverts to be stripped from the file, and your own\nBBS adverts can be added to advertise your BBS.\n\nPrO-DmScHeCk was originally written for @{"THE TOWER" link BBS_ADS}, and was written\nin 680x0 assembler using Devpac 3 from HiSoft.\n\n@endnode\n\n@node PDC_OPTS "PrO-DmScHeCk Options"\n               @{u}PrO-DmScHeCk''s command line options@{uu}\n\nUsage : @{b}PrO-DmScHeCk@{ub} [-<options>] <filename>\n\nWhere options is one or more of :\n\n   @{b}b@{ub} - Add a tail banner (from @{b}S:PDC_Banner_Rear@{ub})\n\n   @{b}f@{ub} - Add a front banner (from @{b}S:PDC_Banner_Front@{ub})\n\n   @{b}t@{ub} - Add a track 0 banner (from @{b}S:PDC_Track_Zero@{ub}\n                             this file @{b}MUST@{ub} be 960 bytes long.)\n\n   @{b}d@{ub} - Add the current time and/or date to one/all of the\n                text to be added.\n\n      When ''##-###-###'' appears in a file the date will be added,\n       and when ''##:##'' appears the current time will be added.\n\n  @{b}R@{ub} - Remove existing front/tail banners.\n\n  @{b}T@{ub} - Remove existing track 0 banners.\n\n@endnode\n\n@node INSTALLATION "How to install PrO-DmScHeCk"\n                    @{u}Installation instructions@{uu}\n\n@{u}Installation for normal command line usage@{uu}\n\nCopy @{b}Utils/PrO-DmScHeCk@{ub} to anywhere in your path (usually C:).\n\n@{u}Installation for Ami-Express BBS usage@{uu}\n\nCopy @{b}Utils/PrO-DmScHeCk@{ub} to @{b}BBS:Utils/PrO-DmScHeCk@{ub}\nCopy @{b}FCheck/DMS.info@{ub} to @{b}BBS:FCheck/DMS.info@{ub}\nCopy @{b}S/PDC_Banner_Front@{ub} to @{b}S:PDC_Banner_Front@{ub}\nCopy @{b}S/PDC_Banner_Rear@{ub} to @{b}S:PDC_Banner_Rear@{ub}\nCopy @{b}S/PDC_Track_Zero@{ub} to @{b}S:PDC_Track_Zero@{ub}\n\nEdit the files @{b}S:PDC_Banner_Front@{ub} (any size),\n               @{b}S:PDC_Banner_Rear@{ub} (any size)\n           and @{b}S:PDC_Track_Zero@{ub} (960 bytes)\n\n to suit your own BBS.\n\nNow when a DMS file is uploaded it will be automatically checked for\nvalidity and integrity by PrO-DmScHeCk.\n@endnode\n\n@node DISTRIBUTION "Distribution restrictions"\n                  @{u}Distribution of PrO-DmScHeCk@{uu}\n\nPrO-DmScHeCk is (c)1994 Exodous/TLS & XPR and may be distributed in any\nway as long as the following conditions are met :\n\n  @{b}o@{ub}  All of the files are included, unchanged.\n  @{b}o@{ub}  No money changes hands (ie @{b}NO@{ub} PD library distribution)\n\n@endnode\n\n@node GREETINGS "Greetings"\n\nGreetings to the following people :\n\n    @{b}Oll¿e@{ub}\n    @{b}GrassHopper@{ub}\n    @{b}FireFlash@{ub}\n    @{b}M¿sta Are@{ub}\n    @{b}Mike@{ub}\n\nAll members of @{b}TLS@{ub} and @{b}XPress@{ub}.\n@endnode\n\n@node CONTACTING_ME "How to contact me"\n                          @{u}How to contact me@{uu}\n\nI can be contacted via E-Mail in the following ways :\n\n @{"Q.E.D" link BBS_ADS}     : Exodous\n @{"The Tower" link BBS_ADS} : Exodous\n\n Internet :\n\n  [email removed]      (If this address bounces then use the next one)\n  [email removed]\n@endnode\n\n@node BBS_ADS "Call these BBS''s"\n                  @{u}Call these great XPress BBS''s@{uu}\n\n@{b}Q.E.D@{ub} (WHQ)         : +44 (0)91-372-1911 (2 Nodes) - @{b}GRASSHOPPER@{ub}.\n\n@{b}SLEEZY BBS@{ub} (UKHQ)   : +44 (0)422-367-163 (1 Node)  - @{b}BONEIDLE@{ub}.\n\n@{b}MEDUSA DOMAIN@{ub} (CHQ) : +1 905-574-7791    (6 Nodes) - @{b}MEDUSA@{ub}.\n\n@{b}BIO HAZARD@{ub} (CHQ)    : +1 905-841-0965    (3 Nodes) - @{b}KAPT. KAOS@{ub}.\n\n@{b}THE LAB@{ub} (CHQ)       : +1 514-745-7420    (3 Nodes) - @{b}P.R SINISTER@{ub}.\n\n@{b}WAREZ DEPOT@{ub} (USHQ)  : +1 305-819-9925    (3 Nodes) - @{b}AMIGAMAN@{ub}.\n\n                  @{u}Call these other great BBS''s@{uu}\n\n@{b}THE TOWER@{ub} (LsD UKHQ): +44 (0)204-384-453 (2 Nodes) - @{b}FIREFLASH@{ub}.\n                      +44 (0)204-371-868\n\n@endnode\n\n@node HISTORY "The history of PrO-DmScHeCk"\n                     @{u}History of PrO-DmScHeCk@{uu}\n\n| Ver   | Date          | Comment\n+-------+---------------+--------------------------------------------\n| 1.0   | 15-Jun-94     | First version.\n+-------+---------------+--------------------------------------------\n@endnode\n\n@node OTHER_PROGS "Other programs that I have written"\n         @{u}Here is a list of other programs that I have written@{uu}\n\n@{b}BootUte@{ub}      : Degrader type utility for @{i}newer@{ui} Amiga''s....\n               Needs Kickstart 2.0+. Features easy to use gadtools\n               interface.\n\n@{b}BullRead@{ub}     : Bulletins door for /X that allows users to search\n               bulletins while they are on-line, or download the bulletins\n               for viewing whilst off-line.\n\n@{b}X-Zippy@{ub}      : Replacement zippy search door for /X that can search\n               for multiple items at a time, about 3 times faster\n               than the built in zippy!!\n\n@{b}UserCom@{ub}      : Door for /X that allows users to make comments to files\n               so that others will know if the file is old, fake etc.\n\n@{b}PrO-LhAcHeCk@{ub} : LhA file checker - for user with most BBS systems.\n               Strips most other adverts and adds own adverts that are\n               virtually unstrippable.\n\n@{b}Decrunch@{ub}     : CLI based decruncher to decrunch loads of different\n               packed files.\n\n@{b}PPPatch@{ub}      : PowerPacker Patcher... Patches the headers of PowerPacked\n               files so that they can''t be decrunched.\n\n@{u}Projects I''m working on@{uu}\n\n@{b}EBBS@{ub}         : En¿gma Bulletin Board System\n               My own host BBS, written entirely in Assembler with loads\n               of features : Kickstart 2.0+ only.\n\n@{b}xxxx-NuKe@{ub}    : Program similar to Boss-Nuke (for /X) that allows files\n               to be nuked, givent extra credits etc., will run from /X\n               as a door, or from the CLI/WB and display a user interface\n               (Kickstart 2.0+ only)\n\n@{b}GFC@{ub}          : Graphics Format Converter\n               A great graphics converter for loads of different formats...\n               (Kickstart 2.0+ only)\n\n@{b}Shell Menu@{ub}   :\n               A program similar to Tools-Daemon and the like, but to\n               add menu''s to the Shell window.\n\n@{b}E-Dos@{ub}        : Enigma-DOS\n               Replacement floppy-disk filing system with in-line\n               encryption for transferring/storing private information.\n\n\nIf you have any suggestions for features that you would like to see in\nany of the programs then e-mail me with your suggestions.\n\n@endnode\n','\n',char(10)),NULL,'auto-added',23756,8,0,NULL,NULL,'ott_dms','scan',1780048664);
INSERT INTO door_catalog VALUES('ott_lha','OTT_LHA.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/OTT_LHA.LHA','PrO-LhAcHeCk','XIM','PrO-LhAcHeCk',NULL,NULL,'OTT','/   .   \___    __!__    ___/   o.V.E.R | /    !    \/      \:/      \     t.H.E   ! \_________/\______/:\______/     t.O.P.! |',replace('    _________________.__________           :\n   /   .   \___    __!__    ___/   o.V.E.R |                                            \n  /    !    \/      \:/      \     t.H.E   !                                            \n  \_________/\______/:\______/     t.O.P.! |\n                                            \n/X UTILS DIV.     EL?`--------->   <-------''\n   -== PrO-LhAcHeCk v1.0 - LHA checker ==-  \n  -==   Fastest LHA checker around    ==-   \n..----------- . . MEN-TEL BBS . .---------..\n','\n',char(10)),'PrO-LhAcHeCk.Guide',replace('@database PrO-LhAcHeCk.guide\n@$VER: PrO-LhAcHeCk.guide v1.0 (15-Jun-94)\n\n@node MAIN "PrO-LhAcHeCk Contents"\n            @{b}@{u}Documents for PrO-LhAcHeCk v1.0@{ub}@{uu}\n\n             PrO-LhAcHeCk was written by Exodous/TLS & XPress\n                           Released on 15-Jun-94\n\n                      1)  @{" What is PrO-LhAcHeCk ? " link WHAT_IS_PLC}\n                      2)  @{" Installation           " link INSTALLATION}\n                      3)  @{" Distribution           " link DISTRIBUTION}\n                      4)  @{" Greetings              " link GREETINGS}\n                      5)  @{" Contacting me          " link CONTACTING_ME}\n                      6)  @{" Call These BBS''s       " link BBS_ADS}\n                      7)  @{" History                " link HISTORY}\n                      8)  @{" Other programs         " link OTHER_PROGS}\n\n                PrO-LhAcHeCk was written in 100% assembler.\n@endnode\n\n@node WHAT_IS_PLC "What is PrO-LhAcHeCk"\n                     @{u}What is PrO-LhAcHeCk ?@{uu}\n\nPrO-LhAcHeCk is a LHA file checker meant to be run from a BBS when an\nLHA, LZH, LZA or SFX file has been uploaded.\n\nIt allows other BBS adverts to be stripped from the file, and your own\nBBS adverts can be added to advertise your BBS.\n\nPrO-LhAcHeCk was originally written for @{"THE TOWER" link BBS_ADS}, and was written\nin 680x0 assembler using Devpac 3 from HiSoft.\n\n@endnode\n\n@node INSTALLATION "How to install PrO-LhAcHeCk"\n                    @{u}Installation instructions@{uu}\n\n@{b}NOTE :@{ub} You will need LhA (by Stefan Boberg), and depending on your\n       operating system depends on where it needs to be installed.\n\n@{u}LhA on 1.2+@{uu}\nThe @{b}LhA@{ub} executable must be called @{b}LhA@{ub} and reside in the @{b}C:@{ub}\ndirectory\n\n@{u}LhA on 2.0+@{uu}\nLhA can be installed as 1.2+ or :\n\nPut the @{b}LhA@{ub} executable anywhere and do either of the following :\n\n @{b}o@{ub} Add the following line to the @{b}S:User-Startup@{ub} file\n\n              SetEnv PDC=<path and name of LhA>\n           eg @{i}SetEnv PDC=Work:Utilities/LhA@{ui}\n\n @{b}o@{ub} Type the following at the CLI, then wait a few seconds then\n            reboot your Amiga.\n\n              Echo >ENVARC:PDC "<path and name of LhA>"\n           eg @{i}Echo >ENVARC:PDC "Work:Utilities/LhA"@{ui}\n\n@{u}Installation for normal command line usage@{uu}\n\nCopy @{b}Utils/PrO-LhAcHeCk@{ub} to anywhere in your path (usually C:).\n\n@{u}Installation for Ami-Express BBS usage@{uu}\n\nCopy @{b}Utils/PrO-LhAcHeCk@{ub} to @{b}BBS:Utils/PrO-LhAcHeCk@{ub}\nCopy @{b}FCheck/LHA.info@{ub} to @{b}BBS:FCheck/LHA.info@{ub}\nCopy @{b}FCheck/LZH.info@{ub} to @{b}BBS:FCheck/LZH.info@{ub}\nCopy @{b}FCheck/LZA.info@{ub} to @{b}BBS:FCheck/LZA.info@{ub}\nCopy @{b}FCheck/SFX.info@{ub} to @{b}BBS:FCheck/SFX.info@{ub}\nCopy @{b}S/PLC/#?@{ub} to @{b}S:PLC/#?@{ub}\n\nEdit the files @{b}S:PLC/#?@{ub}\n\n to suit your own BBS.\n\n@{b}NOTE :@{ub} All files that are added will have the date and time of\n       upload added as their comment.\n\n       @{b}Also@{ub} all files that start as @{b}PLC@{ub} will be give a random\n       number instead of PLC so that it is very difficult to strip them\n       from the file automatically.\n\n    eg if a file called @{i}PLC.txt@{ui} exists then on one occurance it\n       could be called @{i}256133.txt@{ui}, on the next occurance something\n       totally different like @{i}725531.txt@{ui}.\n\nNow when an LHA file is uploaded it will be automatically checked for\nintegrity, existing BBS adverts will be killed and your BBS adverts\nwill be added by PrO-LhAcHeCk.\n@endnode\n\n@node DISTRIBUTION "Distribution restrictions"\n                  @{u}Distribution of PrO-LhAcHeCk@{uu}\n\nPrO-LhAcHeCk is (c)1994 Exodous/TLS & XPR and may be distributed in any\nway as long as the following conditions are met :\n\n  @{b}o@{ub}  All of the files are included, unchanged.\n  @{b}o@{ub}  No money changes hands (ie @{b}NO@{ub} PD library distribution)\n\n@endnode\n\n@node GREETINGS "Greetings"\n\nGreetings to the following people :\n\n    @{b}Oll¿e@{ub}\n    @{b}GrassHopper@{ub}\n    @{b}FireFlash@{ub}\n    @{b}M¿sta Are@{ub}\n    @{b}Mike@{ub}\n\nAll members of @{b}TLS@{ub} and @{b}XPress@{ub}.\n@endnode\n\n@node CONTACTING_ME "How to contact me"\n                          @{u}How to contact me@{uu}\n\nI can be contacted via E-Mail in the following ways :\n\n @{"Q.E.D" link BBS_ADS}     : Exodous\n @{"The Tower" link BBS_ADS} : Exodous\n\n Internet :\n\n  [email removed]      (If this address bounces then use the next one)\n  [email removed]\n@endnode\n\n@node BBS_ADS "Call these BBS''s"\n                  @{u}Call these great XPress BBS''s@{uu}\n\n@{b}Q.E.D@{ub} (WHQ)         : +44 (0)91-372-1911 (2 Nodes) - @{b}GRASSHOPPER@{ub}.\n\n@{b}SLEEZY BBS@{ub} (UKHQ)   : +44 (0)422-367-163 (1 Node)  - @{b}BONEIDLE@{ub}.\n\n@{b}MEDUSA DOMAIN@{ub} (CHQ) : +1 905-574-7791    (6 Nodes) - @{b}MEDUSA@{ub}.\n\n@{b}BIO HAZARD@{ub} (CHQ)    : +1 905-841-0965    (3 Nodes) - @{b}KAPT. KAOS@{ub}.\n\n@{b}THE LAB@{ub} (CHQ)       : +1 514-745-7420    (3 Nodes) - @{b}P.R SINISTER@{ub}.\n\n@{b}WAREZ DEPOT@{ub} (USHQ)  : +1 305-819-9925    (3 Nodes) - @{b}AMIGAMAN@{ub}.\n\n                  @{u}Call these other great BBS''s@{uu}\n\n@{b}THE TOWER@{ub} (LsD UKHQ): +44 (0)204-384-453 (2 Nodes) - @{b}FIREFLASH@{ub}.\n                      +44 (0)204-371-868\n\n@endnode\n\n@node HISTORY "The history of PrO-LhAcHeCk"\n                     @{u}History of PrO-LhAcHeCk@{uu}\n\n| Ver   | Date          | Comment\n+-------+---------------+--------------------------------------------\n| 1.0   | 15-Jun-94     | First version.\n+-------+---------------+--------------------------------------------\n@endnode\n\n@node OTHER_PROGS "Other programs that I have written"\n         @{u}Here is a list of other programs that I have written@{uu}\n\n@{b}BootUte@{ub}      : Degrader type utility for @{i}newer@{ui} Amiga''s....\n               Needs Kickstart 2.0+. Features easy to use gadtools\n               interface.\n\n@{b}BullRead@{ub}     : Bulletins door for /X that allows users to search\n               bulletins while they are on-line, or download the bulletins\n               for viewing whilst off-line.\n\n@{b}X-Zippy@{ub}      : Replacement zippy search door for /X that can search\n               for multiple items at a time, about 3 times faster\n               than the built in zippy!!\n\n@{b}UserCom@{ub}      : Door for /X that allows users to make comments to files\n               so that others will know if the file is old, fake etc.\n\n@{b}PrO-DmScHeCk@{ub} : DMS file checker - for user with most BBS systems.\n               Strips and adds front, rear and track texts.\n\n@{b}Decrunch@{ub}     : CLI based decruncher to decrunch loads of different\n               packed files.\n\n@{b}PPPatch@{ub}      : PowerPacker Patcher... Patches the headers of PowerPacked\n               files so that they can''t be decrunched.\n\n@{u}Projects I''m working on@{uu}\n\n@{b}EBBS@{ub}         : En¿gma Bulletin Board System\n               My own host BBS, written entirely in Assembler with loads\n               of features : Kickstart 2.0+ only.\n\n@{b}xxxx-NuKe@{ub}    : Program similar to Boss-Nuke (for /X) that allows files\n               to be nuked, givent extra credits etc., will run from /X\n               as a door, or from the CLI/WB and display a user interface\n               (Kickstart 2.0+ only)\n\n@{b}GFC@{ub}          : Graphics Format Converter\n               A great graphics converter for loads of different formats...\n               (Kickstart 2.0+ only)\n\n@{b}Shell Menu@{ub}   :\n               A program similar to Tools-Daemon and the like, but to\n               add menu''s to the Shell window.\n\n@{b}E-Dos@{ub}        : Enigma-DOS\n               Replacement floppy-disk filing system with in-line\n               encryption for transferring/storing private information.\n\n\nIf you have any suggestions for features that you would like to see in\nany of the programs then e-mail me with your suggestions.\n\n@endnode\n','\n',char(10)),NULL,'auto-added',19350,8,0,NULL,NULL,'ott_lha','scan',1780048664);
INSERT INTO door_catalog VALUES('p0t_sel1','P0T-SEL1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/P0T-SEL1.LHA','Super-Select','XIM','Super-Select','1.00','P0T-NOoDLE','P0T','by P0T-NOoDLE of Gods''Gift / Anthrox, 1995! Will insert a randomly chosen string  (such as a filename  or a fortune-cookie)  into a',replace('Super-Select v1.00 [RELEASE 1] for AmigaDOS\nby P0T-NOoDLE of Gods''Gift / Anthrox, 1995!\nWill insert a randomly chosen string  (such\nas a filename  or a fortune-cookie)  into a\ncommand-line.  Great for random boot-stuff!\n','\n',char(10)),'Super-Select.Guide',replace('@database "Super-Select_DOCS"\n@REMARK History at the end.\n@REMARK .----------------------------------------------------------------.\n@REMARK | Super-Select, HyperText docs written by P0T-NOoDLE of ANTHROX. |\n@REMARK `----------------------------------------------------------------''\n@REMARK You need Multiview, AmigaGuide, or some other .Guide viewer.\n@REMARK Don''t be a fucking loser and read this with a standard ASCII viewer!!\n@REMARK I have not included a non-Guide doc file to make you go and get\n@REAMRK AmigaGuide, coz it IS suck a cool program.\n@REMARK $VER: Guide for Super-Select v1.00 (04-Jan-95)\n@NODE MAIN "Super-Select: Contents."\n                     .--------------------------------.\n          .----------'' Super-Select v1.00 [RELEASE 1] `---------.\n          | Written by P0T-NOoDLE of ANTHR0X, (C)1995 Gods''Gift. |\n          `------------------------------------------------------''\nRELEASED  ..::::::. `-. For AmigaDOS v2.1 and above. .-'' .::::.:.\n04-Jan-95  :.:::::::. `------------------------------'' .::::::::\n                            100% Assembler Code.\n\n                       @{" DONATE: Children of the Storm " LINK Charity}\n\n                           @{" Description           " LINK Description}\n                           @{" Usage                 " LINK Usage}\n                           @{" Examples              " LINK Examples}\n                           @{" History               " LINK History}\n                           @{" Contacting the Author " LINK Contact}\n\n\nPS:\n\nIf anyone has some old (or even NEW!) GameBoy games that they don''t want\nanymore, I''ll be very happy to take them as a form of thank-you!!\n\n(Maybe you don''t think it''s worth it for this util, but loads of people\nuse some of the other more complex programs I''ve written!)...\n\nOh, and I know I''ve always said CONSOLES are TOYS, but the GameBoy lets\nme play Toilet-tris and wasn''t very expensive!\n@ENDNODE\n@NODE Description "Super-Select: Description."\n	Super-Select is a program which will pick a random string, insert\nit between two other strings, and execute the result as if it were typed in\na shell window.\n	Can''t think of how that could be usefull?\n	Well, say you want a random picture displayed whenever you boot your\nAmiga. The "random string" could be chosen from a file conatining a list of\nthe files in your pictures drawer, and the turned into a command line which\ndisplayed that picture!\n	Or, you could make it copy one of the files in the list somewhere so\nthat it appeared as your Workbench backdrop-picture...\n	You could even use it as a fortune cookie program, making the "say"\ncommand speak a randomly selected phrase...\n	It is even possible to have a random command executed!\n\n	I hope that you can think of some cool use for this program to make\nyour Amiga a bit different everytime you boot...\n	Personally, I have a random Bevis''n''Butthead sample played just\nbefore my Startup-Menu appears. If I select one of the startups that takes\na while to load, I have a random picture displayed and a randomly selected\n70''s TV Theme-tune sample played! (The music from Mission Impossible is\nperfect while booting, and takes EXACTLY the same time as my Workbench\nstartup-option, down to the very last drum-beat... :)\n\nWhy did I write it?\n\n	I have see one or two programs which do similar things to\nSuper-Select, but instead of taking the random string from a file, they\nget directory and randomly choose a file within it. This meant that it\nwould have wasted a few seconds getting a directory of all 80 or so of my\npictures. I thought it would be much better to be able to have a program\nwhich randomly picked the filename from a text-file which would load much\nquicker than a directory-scan.\n\n	Using the code from Super-AmiLog which chose the random comments\nI slapped together a program which did the job for me, but was unreleasable\nbecause it had everything hard-coded into it.\n	...until now: I finally decided to turn it into a propper util with\na ReadArgs() interface which allows you to specify the strings and files it\nshould use.\n\n	I hope you like it!\n@ENDNODE\n@NODE Usage "Super-Select: Usage."\nTyping "Super-Select ?" will bring up the ReadArgs() command template:\n\nH = @{" Help     " LINK Arg_Help} (Switch)\nL = @{" ListFile " LINK Arg_ListFile} (String)\nB = @{" Before   " LINK Arg_Before} (String)\nA = @{" After    " LINK Arg_After} (String)\nD = @{" Delay    " LINK Arg_Delay} (Number)\nS = @{" NoSpaces " LINK Arg_NoSpaces} (Switch)\nR = @{" Report   " LINK Arg_Report} (Switch)\nE = @{" NoExec   " LINK Arg_NoExec} (Switch)\n\n@{" ListFile " LINK Arg_ListFile} is the only required argument, all others may be left out.\n\nAll of the arguments have abbreviations which are those characters before\nthe "=" symbol and can be used instead of the full names.\n\nA switch-argument is activated if it is given on the command-line.\n	For example: "Super-Select Help"\n	Activates the @{" Help " LINK Arg_Help} switch.\n\nA number-argument expects a number (surprise!)\n	For example: "Super-Select Delay 5"\n	Sets the @{" Delay " LINK Arg_Delay} time to five seconds.\n\nA string-argument expects a string of text.\n	For example: "Super-Select ListFile S:SampleList.TXT"\n	Tells the program that the @{" ListFile " LINK Arg_ListFile} is S:SampleList.TXT"\n\n	To include spaces in your string, "surround it with quotes".\n\n	To include quotes in your string, use *" instead of "\n	For example:  "He said *"HELLO*"!"  =  He said "HELLO"!\n\n\nIf you''re still confused, see the @{" Examples " LINK Examples} section.\n\n@ENDNODE\n@NODE Arg_Help "Super-Select: Usage, The ''Help'' Argument."\nHELP\n	Will bring up the more detailed help text.\n\n	If the help switch is given, the rest of the command-line is\n	ignored and no command-line is built or executed.\n@ENDNODE\n@NODE Arg_ListFile "Super-Select: Usage, The ''ListFile'' Argument."\nListFile\n	Expects the filename of the list of strings, one of which will be\n	chosen at random.\n\n	This file should be a normal ASCII text file with one string per\n	line, and with a return at the end of EVERY line (it''s quite\n	easy to forget the return on the last line).\n\n	Currently there is a limit of 65535 lines (should be enough).\n@ENDNODE\n@NODE Arg_Before "Super-Select: Usage, The ''Before'' Argument."\nBefore\n	Expects a string which will be placed before the randomly chosen\n	string when the command-line is build.\n\n	You do NOT have to have a Before-string - leaving it out will\n	mean that the randomly chosen string is first in the command-line\n	and the program will run a randomly chosen command!\n@ENDNODE\n@NODE Arg_After "Super-Select: Usage, The ''After'' Argument."\nAfter\n	Expects a string which will be placed after the randomly chosen\n	string when the command-line is build.\n\n	You do NOT have to have an After-string.\n@ENDNODE\n@NODE Arg_Delay "Super-Select: Usage, The ''Delay'' Argument."\nDelay\n	Expects the number of seconds to wait after executing the\n	command-line. This allows you to "RUN" things while giving them\n	time to load all their config files, or whatever, without other\n	things getting in their way.\n\n	If you specify Delay=0 or don''t even use the "Delay" argument, no\n	delay will take place.\n@ENDNODE\n@NODE Arg_NoSpaces "Super-Select: Usage, The ''NoSpaces'' Argument."\nNoSpaces\n	Normally, a space is inserted before and after the randomly chosen\n	string because most of the time this string will be a filename\n	which must be separated from everything else on the command-line.\n\n	If you specify the NoSpaces switch, these spaces will not be added.\n@ENDNODE\n@NODE Arg_Report "Super-Select: Usage, The ''Report'' Argument."\nReport\n	If you specify the "Report" switch, the resultant command-line\n	which is generated by the program will be output to the Shell\n	window so that you can check that everthing is working OK.\n\n	So that you can see things such as spaces at the end of the line\n	and control-codes (such as colour-changes) which would normally be\n	interpreted by the Shell console, it is often a good idea to\n	redirect Super-Select''s output and view it in an editor such as\n	CygnusEd.\n\n	Redirection with the Report switch can also be very useful when\n	running Super-Select in a script (which is what it''s intended for!)\n	as you can send all the Reports to a file and make sure all the\n	commands were build correctly.\n\n	Remember that you can use ">>" instead of ">" when redirecting a\n	program''s output so that it will APPEND rather than overwrite\n	whatever used to be there.\n\n	e.g:  Super-Select >>RAM:SS_Log.TXT B "TEST" L "S:List"\n\n	See also: @{" NoExec " LINK Arg_NoExec}\n@ENDNODE\n@NODE Arg_NoExec "Super-Select: Usage, The ''NoExec'' Argument."\nNoExec\n	If you specify this switch the program will generate a command-line\n	as normal, but not execute it.\n\n	Used in conjunction with the @{" Report " LINK Arg_Report} switch, the "NoExec" switch\n	makes it easy for you to make sure the program is generating the\n	right command-lines without it actually executing them and wasting\n	a lot of time.\n	(The "NoExec" switch is of little use without the @{" Report " LINK Arg_Report} one).\n@ENDNODE\n@NODE Examples "Super-Select: Examples."\nYour archive should have come with an example script called "execute.me"\nwhich will ECHO a random quote from another included file.\n\nTyping:\n---------------------------------------------------------------------------\nSuper-Select ListFile S:PicsList Before DH0:Art/Viewtek Delay 2\n---------------------------------------------------------------------------\n\n...where S:PicsList contains the following:\n---------------------------------------------------------------------------\nDH2:Pictures/Sex/Pervert/Cindy_Crawford.IFF\nDH2:Pictures/Sex/Pervert/LittleGirl.IFF\nDH2:Pictures/Sex/Pervert/Sheep.IFF\nDH2:Pictures/Sex/Pervert/Amiga4000_040.IFF\nDH2:Pictures/Sex/Pervert/Your_Mum.IFF\n---------------------------------------------------------------------------\n\n...would run a command-line such as:\n---------------------------------------------------------------------------\nDH0:Art/Viewtek DH2:Pictures/Sex/Pervert/Amiga4000_040.IFF\n---------------------------------------------------------------------------\n\n...and then wait 2 seconds.\n\n\n\nTyping\n---------------------------------------------------------------------------\nSuper-Select L S:PicsList B "Copy >NIL: FROM" A "TO DH0:WBBackdrop.PIC"\n---------------------------------------------------------------------------\n\n....would run a command-line such as:\n---------------------------------------------------------------------------\nCopy >NIL: FROM DH2:Pictures/Sex/Pervert/Sheep.IFF TO DH0:WBBackdrop.PIC\n---------------------------------------------------------------------------\n\n\nI hope you''ve got the idea by now! That''s really all I can be bothered to\ndo as far as examples go!\n@ENDNODE\n@NODE Contact "Super-Select: Contacting Mr.Nudel!"\nYou can reach me on any of the following UK Boards:\n---------------------------------------------------------------------------\n    Bad Dreams,  Beyond Reality,  Burger Bar,  Cement City,  Dawn Raid.\n---------------------------------------------------------------------------\n\nYou can EMail me via:\n---------------------------------------------------------------------------\n [email removed]\n---------------------------------------------------------------------------\n...but if you do, please write "C/O Leo Davidson" as it is NOT MY ACCOUNT.\n(I probably won''t even know you''ve written to me for at least a week if you\ndo EMail me - I''d rather your called one of the above boards).\n@ENDNODE\n@NODE Charity "Super-Select: Children of the Storm!"\n	OK, this text is a few months old, and some new things have\nhappened since then, but that shouldn''t really matter! Please consider\ndonating, even if you don''t use this program!\n\n\n	I know that most you out there won''t pay anything at all, but I am\ndoing this in the hope that at least a few people donate even a small amount\nof money, because every little penny can be put to some good!\n	Please, at least read about the charity, Children of the Storm.\nI not going to say that anyone who doesn''t send off some money should feel\nreally guilty, just that anyone who does send off some money should feel\nreally great, knowing that they''ve helped someone out.\n	Even if you don''t want to send any money (for whatever reasons),\nyou could always send a letter of support, or spread the word to other\npeople.\n\n	I have never asked for any money for all the work I put into these\nutils, and I do not gain anything from your donations except knowing that\nI have helped some people out. I know that my work is used by a lot of\npeople and that because of that, I have helped them out in one way or\nanother, so why not help someone else now! Scene members do have hearts,\ndon''t they? Make it worth my while typing all of this info!\n\n\n\n\nWho are the CHILDREN OF THE STORM?\n----------------------------------\nIn Britain this year, over a hundred young children will be accepted into\nthe country by the Home Office, seeking political asylum. They may be just\neleven or twelve years old. Often they have travelled across continents\nalone. They may have just lost their parents, seen brothers and sisters\nbrutally murdered, or suffered beatings or torture themselves. Whilst our\nGovernment offers them basic shelter and the long-term possibility of\nwar-refugee status in the UK, they can live here for weeks and months under\nthe threat of instand deportation, sometimes forced to live rough without\nprovision for food, clothing and other simple necessities. Far from their\nhome and their culture, hungry, fearful and insecure, these children\nattempt, often with an astounding dignity and human spirit, to survive and\ngrow despite the weight of unbearable memories they carry deep within...\n\n\n\nBackground\n----------\nSince 1989 several members of the staff at Hampstead School have been\nbuilding up a support network for refugee children attending the school\nwho have little or no family back-up, few resources, and are often in a\ncritical emotional state.\n\nAchievements to date include:\n- providing food, shelter and income for regugee children, working with\n  the Tavistock Clinic which is providing counselling services and\n  advising teachers,\n- forging links with the local authority (London Borough of Camden) to\n  put children and carers in touch with any relevant support agencies,\n- establishing a social club in which refugee children are offered\n  additional tuition and emotional support by their fellow pupils at\n  the school,\n- acting as the children''s advocates in relation to housing, social\n  services, social security etc.\n\n\n\nStatus\n------\nRegistered Charity number 1035774\nConsultant: Sheila Kasabova, Refugee Co-ordinator, Camden Council\nConsultant Psychologist: Maureen Fox, Consultant Psychotherapist at the\n                         Tavistock Clinic\nLegal Consultants: Bindmans (services at no charge)\nAccountants: Alan Heywood, Chartered Accountants (services at no charge)\n\n\n\nAims and Objectives\n-------------------\n1	To continue to build on the existing project achievements outlined,\n2	To extend knowledge acquired by staff and pupils of the school to\n	other schools and bodies dealing with refugee children through\n	teacher-training programmes, conferences, booklets etc.\n\n\n\nSummary of Projects in Progress or Anticipated\n----------------------------------------------\n1	Publishing a booklet: the Hampstead Story, by those involved in the\n	project, outlining the problems Hampstead School itself has\n	encountered with refugee children and strategies for dealing with\n	them. To be delivered free of charge to every school in the country.\n	Cost: £9,000. Project in progress.\n2	Expanding the social club outlined above to include students from\n	other local schools including primary schools.\n	Cost: £50 per month. Project in progress.\n3	Employing a full-time counsellor at Hampstead School to counsel\n	children and train staff in counselling techniques.\n	Cost: £38,000 pa.\n4	Employing an administrative assistant to manage the charity.\n	Cost: £20,000 pa.\n5	Holding a national conference on problems faced by refugee children\n	in Britain, and strategies for overcoming them, open to any persons\n	or organisations working with regugee children (teachers, welfare\n	and social servicesm volunteer groups etc.)\n6	Employing a fundraiser.\n	Cost: £15,000 pa.\n\n\n\nConclusion\n----------\nThe project originated at Hampstead School is the only one of its kind. Due\nlargely to recent wide coverage and acclaim in local, national and\ninternational media, it is increasingly being recognised by local\nauthorities as a role model for other schools.\nCentral to the project''s success is teacher Athy Demetriades, who has\nassisted on training days in schools around the country. Regular requests\nfor her to speak now come from solicitors, educational psychologists,\nwelfare services and radio programmes as well as schools. On average, she\nfulfils one such engagement per week. She is, in effect, becoming one of few\nexperts on the all-round care of children suffering a unique combination of\nproblems - the destruction of the childhood together with the loss of\ncitizenship and any automatic recourse to law and welfare that citizenship\nentails.\n\nSponsorship for Children of the Storm would ensure that the work originated\nat Hampstead School can continue. It would also lay the foundations for a\ntraining programme enabling teachers and carers right across the country to\nprovide the basics of security and education to refugee children.\n\n\n\n\nFurther Information\n===================\nThis is basically what you would find on the letter head:\n\nChildren Of The Storm\nHampstead School\nWestbere Road\nLondon\nNW2 3RT\nUnited Kingdom\n\nThere is a telephone and fax number, but I feel that it would be unwise to\ninclude it here, as there are a few idiots out there who might abuse it.\n\nCharity registration number 1035774\n\nPatrons:\n	Dame Judi Dench,\n	Lindsay Duncan,\n	Geraldine James,\n	Griff Rhys Jones,\n	John Gordon Sinclair.\n\nTrustees:\n	A. Demetriades,\n	A. Berkeley,\n	M. Janota Bzowski,\n	S. Pickford,\n	G. Walker,\n	M. Johnson,\n	F. Capone.\n\nConsultants:\n	M. Fox THE TAVISTOCK CLINIC,\n	M. Martin LEGAL ADVISER,\n	A. Heywood A.C.A,\n	S. Kasabova CAMDEN L.E.A.\n\n\n	The address is up there, so go on, donate! \n	If you think you can offer something other than money, write!\n\n	I want to say a huge thanks to anyone who does donate some money.\nMy one request is that anyone donating money writes in their letter that\nthey found out about the charity from this util. If you wish, include your\nscene-handle and I will make a list of everyone who has donated.\n\n	Thanks for at least reading this... and sorry for any mistakes in\nthe above text - my typing can go a bit haywire sometimes!!\n@ENDNODE\n@NODE History "Super-Select: History."\n.=[*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]=.\n[*] Version v1.00 [====] Release #01 [====] Released on 4th January 1995 [*]\n`=[*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]=''\n\n- First public release.\n- Only problem is that the Random-number generator is not the best in the\n  world, however, I think it does the job well enough! If anyone has a\n  routine which they think is even better, send it to me.\n- Limited to 65535 random lines (I think that''s enough!)\n- No future updates planned, unless you have some ideas!\n@ENDNODE\n@REMARK  Dates in history, Contents, Version string.\n','\n',char(10)),NULL,'auto-added',46303,7,0,NULL,NULL,'p0t_sel1','scan',1780048671);
INSERT INTO door_catalog VALUES('p0t_trix','P0T-TRIX.LZX','~/Code/amiexpress_doors/Archives/AmiExpress/P0T-TRIX.LZX',NULL,'XIM','8',NULL,NULL,'P0T',NULL,NULL,NULL,NULL,NULL,'auto-added',46109,0,0,NULL,NULL,'p0t_trix','scan',1780048671);
INSERT INTO door_catalog VALUES('passente','PASSENTE.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PASSENTE.LHA',NULL,'XIM','LE-win5-96.exe',NULL,'The',NULL,'With Many Features And Fully Configurable By The SysOp As Well As Being Easy To SetUp...',replace('Pass Word Entry Door For MAX''s BBS\nWith Many Features And Fully\nConfigurable By The SysOp As Well\nAs Being Easy To SetUp...\n    * XyonicS BBS *\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                                                .------''\n             `------------------------------------------------''\n','\n',char(10)),NULL,'auto-added',33002,6,0,NULL,NULL,'passente','scan',1780048671);
INSERT INTO door_catalog VALUES('pb_mlt3','PB-MLT3.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PB-MLT3.LHA','8','XIM','8',NULL,NULL,'PB','<========\_______    \_______    \=========> :::::::::|:   |/    /|:  _|/____/::::::::: :::::::::|.   .____/ |.  \__    \:::::::::',replace('         __________/\__________/\\n<========\_______    \_______    \=========>\n :::::::::|:   |/    /|:  _|/____/:::::::::\n :::::::::|.   .____/ |.  \__    \:::::::::\n :::::::::;____|PnG!  ;____|/____/:::::::::\n<=========[ POLAR BASE  PRESENTS ]=========>\nMeLTeR fONT vERSiON 3.0 - The BEST fonts\nfor your WB-Screen, /X screen, and all the\nothers application! DOWNLOAD it, SPREAD\naround the world and READ the doc inside!\n.. and ENJOY with this new look of fonts!!!\n','\n',char(10)),'MeLTeRfONTs.README',replace('         ---------------------------------------------------------\n\n                 MiNd MeLTeR presents: MELTER FONTS VER.3!\n\n         ---------------------------------------------------------\n\nFirst  off  all,  please check if my files included in the .LHA archive has\nthe ORIGINAL lenght:\n\n MeLTeR/8           ->  3240 bytes\n MeLTeRiBM/8        ->  3240 bytes \n MeLTeR.font        ->   264 bytes\n MeLTeRiBM.font     ->   264 bytes\n MeLTeRfONTs.iff    -> 20050 bytes\n MeLTeRfONTs.README ->  6641 bytes\n\n         ---------------------------------------------------------\n\nHi  to  all!   This  is my first VERY production, a complete package of the\nmost popular font used in the Amiga-scene!\nYes,  becouse  after my first work, a lot of months ago, i''ve received much\nmessages  of  some  users  that  has installed my fonts, and were very very\nhappy of the new look of the applications!\n\nThe package is arrived at the 3rd version, and now i''ve made TWO version of\nmy fonts:\n\nMeLTeR.font\nMeLTeRiBM.font\n\nWhy??  Simple:  you can use the MeLTeR font in the Workbench screen, and in\nALL  applications  that  DON''T  use  the  ansi-set.   I  use it also in the\nAmiExpress  screen,  becouse the boards that running under /X don''t use the\nIBM-graphics.   Most of all applications can be configurated with this type\nof font!\n\nMeLTeRiBM  can  be  used  in  the  programs  like the ANSI-EDITORS, and all\nprograms that use the ANSI-SET.\n\nA  special thing about the TERM or JRCOMM or NCOMM or TERMINUS, that can be\nconfigurated in this mode:\n\n- The board running under Amiga (e.g. /X): MELTER\n- The board running under PC (e.g. Frontdoor): MELTERIBM\n\nYou can set the different type of fonts in the PHONEBOOK.\n\n         ---------------------------------------------------------\n\nA note for the sysops:  for configure AmiExpress with different fonts, edit\nthe tooltype of NODEx.info and add this:\n\nEXPFONT=Melter.font\n\n         ---------------------------------------------------------\n\nOK,  after all this (i hope u''ve had the patience to read all hehe), i want\nto  give the thanks to my friends and write the last notes for the users of\nmy fonts.\n\n         ---------------------------------------------------------\n\nI want precise some thing: \n\n1) THIS FONTS ARE MAKED WITH THE ''INSPIRATION'' OF TWO OTHERS FONTS:\n\n   - THE ONE I''VE SEEN IN AN IFF OF THE DOOR ''GLOBAL USER STATUS 1.9'', THAT\n     I''VE INSTALLED IN MY BOARD;\n   - THE ONE I''VE SEEN IN THE FANSI PROGRAM, A KEWL ANSI EDITOR\n   - THE ANSI CHARS (IN THE MELTERIBM) ARE THE CHATS THAT I''VE FOUND IN THE\n     BBSDRAW.FONT.\n\nWith this THREE models, i''ve maked the definitive version of MeLTeR.font.\n\n\n2)  FOR THE CREATION OF THE FONTS, I''VE USED THE MOST SIMPLE PROGRAM THAT I\nKNOW  FOR  THE  FONTS  EDITOR:   THE  FED  (AMIGA FONT EDITOR) VERSION 1.3,\nINCLUDED IN THE EXTRAS 1.3.\n\n\n3)  PLEASE DON''T CHANGE MY FONTS, OR IF YOU WILL DO PLEASE TELL ME WHAT ARE\n(OR COULD BE) THE CANGES.\n\n         ---------------------------------------------------------\n\n                           THANKSSSSSSS TO......\n\nI  want  to  thanks  this  persons  becouse  they''re my friends and becouse\nthey''ve  helped  me for the support, the realization, and the success of my\nboard,  and  they''ve used most of them time to chat with me, and have given\nme them experience, them brain and them liking and patience for me!\n\nmAnuBrIo            > Prendi la mia mano..... ZINGARA!!\ndAVe mUSTAiNe       > Finisci presto la naja!!\ndHS/Soundwavers     > Internet ruuuules!!!\nsTReeT sHAMAn       > mAnuBrIo non ha ancora cambiato alias...\nlARs uLRiCh         > Il tuo libro del C fa skifo!\ncRoSSFiRe/iNFiNiTY  > Why you don''t call me, guy??\nRoAMEr              > I miss you, friend!\nMetalbasher!        > Grazie per le schermate di PRiMAL ORDeR!\nSaUzEr              > Grazie per l''add nella lista italiana di P.O.!\nAlx Sty/dTs iNC.    > Ci vediamo a dicembre! (spero!)\nFatal Kiss          > Le tue telefonate mi mancano! I''m crying!\nAir Pez             > Le tue invece NO!! :)\nRobin Hood/pB       > Quando ti deciderai a usare le MAIUSC./minusc.?\nPiNgUiNo/pB         > Quando fottiamo /-//-)/_9000??? ByZ friend!\nSIRiO/NA            > Ma hai la board offline??\nAxl Rose            > Anche se sei passato ai pc........... :(\nFoXaT               > A quando l''acquisto di un modem?? KAZZ!\nMark Phoenix        > Sto ancora aspettando qualcosa dalla BREAND :)\nG                   > Senza di te l''area PC non esisterebbe! THX!\nKubla Khan/aE       > Hai visto senza di me che fine hanno fatto gli AE? :)\nPapalagi/aE         > Vale anche per te quello detto al KK...\nDee Bop/aE          > Idem..\nQuartin ¼ /aE       > E mollala la ragazza!!\nMukka/aE            > Rulla l''Atari?? Uazuazuaz!\nImago/aE            > Mi hanno detto che serve il biglietto per vederti..?\nGomulka             > Mi servono ripetizioni di Calcolo ed Elettronica!\nKallo               > Ennio, forza torna al Marconi! uazuazuaz!\nNuke                > BarbaBlu RULES!\nAlex/pdx            > Qui ci sono ancora i tuoi diski del 3000...\nJerry Drake         > Ancora vivo dopo l''avventura con il Pez? :)))\nRaffa/hrs           > Le tue lezioni mi sono servite.. THX!\n(Mad)Max            > La tua GENIALITA'' e'' immensa! Thx friend!\nWoodelf             > Ue'' quando sostituisci Dave famme gli sconti eh! :)\nDiamante/Niko       > Come va il 125?\nPao                 > Mi devi ancora presentare tua sorella... :)\nPentium             > Mi hai salutato Veronica???\n/\/\erlin           > Virtual Reality rules!\nbRiSTOl             > L''unico vero abbonato di PRiMAL ORDeR hehehe!! :)\nDigital Guru        > L''unico vero TRADER di PRiMAL ORDeR! :)\nJenfry              > Mi manchi tanto!!\nmAS!                > Pure tu!!\n-ppX                > Thanks for your PRiMAL ORDeR''s screens!\n/\L(E)X             > SaTaNiKa esige una 24h/24h!!!\nBeRSeKeR            > NON amo ancora i giochi di ruolo.. checcipossofa''?\nbLOOd wIll          > Ti compri il 4000 o no? :)\n\n...If i''ve forget some guys that i know, please don''t murder me :)\n...and a BIG thanks to ALL member of Nova Acies, Infinity and Polar Base!\n         ---------------------------------------------------------\n\n                                  THE END\n\nThanks to all, if you want to contact me, here''s my info:\n\n                                MiNd MeLTeR\n                         sYsOp oF PRiMAL ORDeR bbs\n                           pHONe +39.45.8011137\n                  Nova Acies / Polar Base / iNFiNiTY iHQ\n                  Hardware A4ooo/o4o - 28.8oo baud modem\n\n Greetings from Verona, Italy! See ya l8er! And thanks for YOUR attention!\n\n                                                             =(>MeLTeR<)=\n','\n',char(10)),NULL,'auto-added',14285,2,0,NULL,NULL,'pb_mlt3','scan',1780048671);
INSERT INTO door_catalog VALUES('pdc201','PDC201.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PDC201.LHA','PrO-DmScHeCk','XIM','PrO-DmScHeCk',NULL,NULL,NULL,'/   .   \___    __!__    ___/   o.V.E.R | /    !    \/      \:/      \     t.H.E   ! \_________/\______/:\______/     t.O.P.! |',replace('    _________________.__________           :\n   /   .   \___    __!__    ___/   o.V.E.R |\n  /    !    \/      \:/      \     t.H.E   !\n  \_________/\______/:\______/     t.O.P.! |\n                                            \n/X UTILS DIV.     EL?`--------->   <-------''\n  -== PrO-DmScHeCk v2.01 - DMS checker ==-  \n  -==    Fastest DMS checker around    ==-  \n','\n',char(10)),'8N43.gUIDe',replace('@database "Cool Corona BBS - It''s The fuckin'' FuTure!"\n@Node MAIN "Cool Corona BBS +31-50-134058"\n\n.------------------------------------------------------------------------.\n|                   c O O l c O R O N a   ß ß §                          |\n|                                                                        |\n|  cOOl cORONa rUNNINg fASt aMIGa wARES! aMIx cONf! sNEs cONf! x-RATEd!  |\n|                                                                        |\n| oNLINe 1500 mEGABYTEs hARDDISk dEFENATLy tHE bESt sYSTEm iN gRONINGEn! |\n|                                                                        |\n|                   nOdE #1 +31-50-134058 ZOOM 24k0 v-FASt               |\n`------------------------------------------------------------------------''\n <«· oVERLORDs wHq! nD1 +31(0)50-134058 pHANTOm & pROSATANOS oVERLORDs ·»>\n `-----------------------------------------------------------------------''\n                          +31(0)50-134058 ZoOM V-FaST\n\n                        @{" Why should I call this BBS? " link "menu"}                   \n@endnode\n\n@node "menu" "Corona"\n@toc "menu"\n\n                 Why should I call this BBS? very simple!\n============================================================================\n                                 - Fine ratio''s\n                                 - Great wares!\n                             - 1500 Megabyte online\n                                 - Zoom V-Fast\n                               - Friendly sysops\n                                 - 40 Mhz Speed\n                                 - Amiga Wares\n                                  - Snes Wares\n                                 - xXx Pictures\n                                - Trainers&fixes\n                                  - Raytrace \n                                   - AX-Utils\n                                    - Utils\n                                 - request area\n                                    - Ect...\n\n                      Question: "How do I get the number?"\n\n                              Dial +31(0)50-134058\n\n                        But Please Remember! Elite ONLY!\n\n============================================================================\n@endnode\n','\n',char(10)),NULL,'auto-added',37364,6,0,NULL,NULL,'pdc201','scan',1780048671);
INSERT INTO door_catalog VALUES('pdchk21','PDCHK21.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PDCHK21.LHA','PrO-DmScHeCk','XIM','PrO-DmScHeCk',NULL,NULL,NULL,'/   .   \___    __!__    ___/   o.V.E.R  | /    !    \/      \:/      \     t.H.E    ! \_________/\______/:\______/     t.O.P    |',replace('   _________________________________________\n  /   .   \___    __!__    ___/   o.V.E.R  |\n /    !    \/      \:/      \     t.H.E    !\n \_________/\______/:\______/     t.O.P    |\n                  PrEsEnTs                 :\n              PrO-DmScHeCk 2.1             :\n   Now 68000, and multi-node compatible!!  :\n--------------------------------------------\n','\n',char(10)),'PrO-DmScHeCk.Guide',replace('@database PrO-DmScHeCk.guide\n@$VER: PrO-DmScHeCk.guide v2.1 (03-Jul-94)\n\n@node MAIN "PrO-DmScHeCk Contents"\n                      @{u}@{b}Documents for PrO-DmScHeCk v2.1@{ub}@{uu}\n\n           PrO-DmScHeCk was written by Exodous/TLS, XPR & O.T.T\n                           Released on 03-Jul-94\n\n                      1)  @{" What is PrO-DmScHeCk ? " link WHAT_IS_PDC}\n                      2)  @{" Command line options   " link PDC_OPTS}\n                      3)  @{" Installation           " link INSTALLATION}\n                      4)  @{" Distribution           " link DISTRIBUTION}\n                      5)  @{" Registration Info      " link REGISTRATION}\n                      6)  @{" Greetings              " link GREETINGS}\n                      7)  @{" Contacting me          " link CONTACTING_ME}\n                      8)  @{" Call These BBS''s       " link BBS_ADS}\n                      9)  @{" History                " link HISTORY}\n                     10)  @{" Other programs         " link OTHER_PROGS}\n\n                PrO-DmScHeCk was written in 100% assembler.\n@endnode\n\n@node WHAT_IS_PDC "What is PrO-DmScHeCk"\n                     @{u}What is PrO-DmScHeCk ?@{uu}\n\nPrO-DmScHeCk is a DMS file checker meant to be run from a BBS when a\nDMS file has been uploaded.\n\nIt allows other BBS adverts to be stripped from the file, and your own\nBBS adverts can be added to advertise your BBS.\n\nPrO-DmScHeCk was written in 680x0 assembler using Devpac 3 from HiSoft.\n\nPrO-DmScHeCk needs kickstart 2.0 or better installed on your Amiga in\norder for it to run, if there is enough need (ie at least 10 people\nwanting it) then I''ll do a 1.3 compatible version.\n\n@endnode\n\n@node PDC_OPTS "PrO-DmScHeCk Options"\n               @{u}PrO-DmScHeCk''s command line options@{uu}\n\nUsage : @{b}PrO-DmScHeCk@{ub} [<options>] <filename>\n\nWhere options is one or more of :\n\n   @{b}BACK@{ub} - Add a tail banner (from @{b}S:PDC_Banner_Rear@{ub})\n\n   @{b}FRONT@{ub} - Add a front banner (from @{b}S:PDC_Banner_Front@{ub})\n\n   @{b}TRACK@{ub} - Add a track 0 banner (from @{b}S:PDC_Track_Zero@{ub}\n                             this file @{b}MUST@{ub} be 960 bytes long.)\n\n@{u}Option in the @{b}REGISTERED@{ub} version @{b}ONLY@{ub}@{uu}\n\n   @{b}DATE@{ub} - Add the current time and/or date to one/all of the\n                text to be added.\n\n      When ''##-###-###'' appears in a file the date will be added,\n       and when ''##:##'' appears the current time will be added.\n\n@endnode\n\n@node INSTALLATION "How to install PrO-DmScHeCk"\n                    @{u}Installation instructions@{uu}\n\n@{u}Installation for normal command line usage@{uu}\n\nCopy @{b}PrO-DmScHeCk@{ub} to anywhere in your path (usually C:).\n\n@{u}Installation for Ami-Express BBS usage@{uu}\n\nLoad Workbench and double click on the ''@{b}Install_PLC@{ub} icon, or\nopen a shell and type ''@{b}execute Install_PLC@{ub}''\n\nEdit the files @{b}S:PDC_Banner_Front@{ub} (any size),\n               @{b}S:PDC_Banner_Rear@{ub} (any size)\n           and @{b}S:PDC_Track_Zero@{ub} (960 bytes)\n\n to suit your own BBS.\n\nNow when a DMS file is uploaded it will be automatically checked for\nvalidity and integrity by PrO-DmScHeCk.\n@endnode\n\n@node DISTRIBUTION "Distribution restrictions"\n                  @{u}Distribution of PrO-DmScHeCk@{uu}\n\nPrO-DmScHeCk is (c)1994 TLS and may be distributed in any way as long as\n the following conditions are met :\n\n  @{b}o@{ub}  All of the files are included, unchanged.\n  @{b}o@{ub}  No money changes hands (ie @{b}NO@{ub} PD library distribution)\n\n@{b}NOTE :@{ub} It is @{b}ILLEGAL@{ub} to distribute the registered versions.\n\n@endnode\n\n@node REGISTRATION "Registration information"\n                         @{u}Registration information@{uu}\n\n@{u}Why register???@{uu}\n\nIf you register you will get :\n\n @{b}o@{ub} A personal version of PrO-DmScHeCk\n @{b}o@{ub} Your BBS number appearing at the bottom of track zero''s\n @{b}o@{ub} Optionally the upload date and/or time can be added to the banners.\n @{b}o@{ub} At least one update to PrO-DmScHeCk\n @{b}o@{ub} A disk containing unregistered versions of my other Ami-Express doors,\n         with the registered version of PrO-DmScHeCk\n\n\n@{u}How much is it to register ?@{uu}\n\nRegistration is £5.00 (Five UK pounds)\n\n@{u}How do I register then ?@{uu}\n\nPrint out (or write by hand) the file ''@{i}Register.doc@{ui}'' and mail it to me\n(see @{"contacting me" link CONTACTING_ME}), along with the 5 pounds in @{b}CASH@{ub}, and you will recieve\nthe latest registered version via return of post.... if your BBS is in\nthe UK then I will personally call and upload the latest version.\n@endnode\n\n@node GREETINGS "Greetings"\n\nGreetings to the following people :\n\n    @{b}Oll¿e@{ub}\n    @{b}M¿sta Are@{ub}\n    @{b}Mike@{ub}\n\nGreets, and thanks for registering go to these cool guyz :\n\n    @{b}Grasshopper@{ub}\n    @{b}Fireflash@{ub} - I''ll make a start on Pro-MultiCheck soon.\n    @{b}Sonny@{ub} - Guess what... it''s now 68000 compatible :-)\n\nAll members of @{b}TLS@{ub}, @{b}XPR@{ub} and @{b}O.T.T@{ub}.\n@endnode\n\n@node CONTACTING_ME "How to contact me"\n                          @{u}How to contact me@{uu}\n\nI can be contacted via E-Mail on the following BBS''s as ''Exodous'' :\n\n @{"Q.E.D" link BBS_ADS}\n @{"The Tower" link BBS_ADS}\n @{"Welsh Coast" link BBS_ADS}\n\nor via internet :\n\n  [email removed]\n\nNormal mail (coders and registrations only please) :\n\n  Paul              <--- please use ''Paul'', @{b}NOT@{ub} ''Exodous''.\n  1 Sherrard Drive\n  Loughborough\n  Leics\n  LE12 7SG\n\nI am interested in contacting other coders so that we can exchange ideas,\nalgorithms etc., NO source code swapping... so that rules out lamers who\njust want my source code.\n\nPlease note @{b}NO PROGRAM SWAPPERS@{ub}, I am not interested in swapping programs,\nso if I recieve any disks with file lists etc. then the lists will be\nbinned, and the disks will be used to send the registered versions out on.\n(ie there is a high chance... @{b}100%@{ub} that you won''t see your disk ever again)\n\n@endnode\n\n@node BBS_ADS "Call these BBS''s"\n                         @{u}Call these Xpress BBS''s@{uu}\n\n@{b}Q.E.D@{ub} (WHQ)         : +44 (0)91-372-1911 (2 Nodes) - @{b}GRASSHOPPER@{ub}.\n\n@{b}SLEEZY BBS@{ub} (UKHQ)   : +44 (0)422-367-163 (1 Node)  - @{b}BONEIDLE@{ub}.\n\n@{b}MEDUSA DOMAIN@{ub} (CHQ) : +1 905-574-7791    (6 Nodes) - @{b}MEDUSA@{ub}.\n\n@{b}BIO HAZARD@{ub} (CHQ)    : +1 905-841-0965    (3 Nodes) - @{b}KAPT. KAOS@{ub}.\n\n@{b}THE LAB@{ub} (CHQ)       : +1 514-745-7420    (3 Nodes) - @{b}P.R SINISTER@{ub}.\n\n@{b}WAREZ DEPOT@{ub} (USHQ)  : +1 305-819-9925    (3 Nodes) - @{b}AMIGAMAN@{ub}.\n\n                          @{u}Call these other BBS''s@{uu}\n\n@{b}THE TOWER@{ub}           : +44 (0)204-384-453 (2 Nodes) - @{b}FIREFLASH@{ub}.\n                      +44 (0)204-371-868\n\n@{b}WELSH COAST@{ub}         : +44 (0)792-586-225 (1 Node)  - @{b}SONNY@{ub}.\n\n@endnode\n\n@node HISTORY "The history of PrO-DmScHeCk"\n                     @{u}History of PrO-DmScHeCk@{uu}\n\n| Ver   | Date          | Comment\n+-------+---------------+--------------------------------------------\n| 1.0   | 15-Jun-94     | First version.\n+-------+---------------+--------------------------------------------\n| 1.1   | 18-Jun-94     | Fixed a problem making the backup file in\n|       |               | case of an error.\n|       |               | Improved the speed of the checking.\n+-------+---------------+--------------------------------------------\n| 2.0   | 21-Jun-94     | Total re-write due to :\n|       |               |  @{b}o@{ub} 1.1 corrupted DMS files on 68030\n|       |               |  @{b}o@{ub} Was a lot slower than Mapus.\n|       |               | As a consequence of the re-write :\n|       |               |  @{b}o@{ub} Code is a @{b}LOT@{ub} smaller.\n|       |               |  @{b}o@{ub} Now 20% faster than Mapus.\n+-------+---------------+--------------------------------------------\n| 2.01  | 22-Jun-94     | Fixed a bug that caused it not to add texts\n|       |               | even though it could have been able to.\n|       |               | Now displays banners and track zero''s when\n|       |               | the file is unpacked with DMS versions\n|       |               | below 2.0\n+-------+---------------+--------------------------------------------\n| 2.1   | 03-Jul-94     | Now kickstart 2.0 only, a 68000 version\n|       |               |  (reg. users only). Fixed a bug that caused\n|       |               |  PDC to fail on multi-node BBS''s.\n+-------+---------------+--------------------------------------------\n@endnode\n\n@node OTHER_PROGS "Other programs that I have written"\n         @{u}Here is a list of other programs that I have written@{uu}\n\n@{b}BootUte@{ub}        : Degrader type utility for @{i}newer@{ui} Amiga''s....\n                 Needs Kickstart 2.0+. Features easy to use gadtools\n                 interface.\n\n@{b}BullRead@{ub}       : Bulletins door for /X that allows users to search\n                 bulletins while they are on-line, or download the bulletins\n                 for viewing whilst off-line.\n\n@{b}X-Zippy@{ub}        : Replacement zippy search door for /X that can search\n                 for multiple items at a time, about 3 times faster\n                 than the built in zippy!!\n\n@{b}UserCom@{ub}        : Door for /X that allows users to make comments to files\n                 so that others will know if the file is old, fake etc.\n\n@{b}PrO-DmScHeCk@{ub}   : DMS file checker - for user with most BBS systems.\n                 Strips and adds front, rear and track texts.\n\n@{b}PrO-LhAcHeCk@{ub}   : LHa file checker - for user with most BBS systems.\n                 Strips most other adverts and adds own adverts that are\n                 virtually unstrippable.\n\n@{b}PrO-LogInfo@{ub}    : An Ami-Express door to inform on-line users when another\n                 user logs on to, or off from, another node.\n\n@{b}Decrunch@{ub}       : CLI based decruncher to decrunch loads of different\n                 packed files.\n\n@{b}PPPatch@{ub}        : PowerPacker Patcher... Patches the headers of PowerPacked\n                 files so that they can''t be decrunched.\n\n@{u}Projects I''m working on@{uu}\n\n@{b}BootUte 2@{ub}      : Updated version of BootUte.\n\n@{b}EBBS@{ub}           : En¿gma Bulletin Board System\n                 My own host BBS, written entirely in Assembler with loads\n                 of features : Kickstart 2.0+ only.\n\n@{b}PrO-MuLtIcHeCk@{ub} : Multiple file checker for most BBS systems, will\n                 incorporate PrO-DmScHeCk and PrO-LhAcHeCk, along with a\n                 text checker/adder.\n\n@{b}PrO-NewScan@{ub}    : Ami-Express new file scanner, like Turbo-NewScan,\n                 only faster!!\n\n@{b}PrO-NewUser@{ub}    : Ami-Express new user questionnaire door that doesn''t\n                 let new users skip questions, they have to insert something\n                 ''intelligent'', eg phone numbers can only have certain\n                 characters in them..\n\n@{b}<xxxx>Asm@{ub}      : 680x0 assembler with loads of features.\n                 The assembler is going to be written by me, and Oll¿e is\n                 writing a cool editor for it, with some excellent features.\n                 (note <xxxx>Asm as I have thought of a name, yet!)\n\nIf you have any suggestions for features that you would like to see in\nany of the programs then e-mail me with your suggestions.\n\n@endnode\n','\n',char(10)),NULL,'auto-added',22479,11,0,NULL,NULL,'pdchk21','scan',1780048671);
INSERT INTO door_catalog VALUES('pdms_chk','PDMS_CHK.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PDMS_CHK.LHA','PrO-DmScHeCk','XIM','PrO-DmScHeCk',NULL,NULL,'PDMS','\:::::::/  / \\____  \____  \:::::::::::\ \:::::/-   _//  ____/  _   /\:::::::::::\ \:::/__/  //_  /\_/_  /\  \/:::XPRESS:::\',replace('_________/\__ __________________________\n\:::::::/  / \\____  \____  \:::::::::::\\n \:::::/-   _//  ____/  _   /\:::::::::::\\n  \:::/__/  //_  /\_/_  /\  \/:::XPRESS:::\\n  /:::\_/__/ \_\/ /:\_\/ /\  \::PRESENTS::/\n /::::::\__\/:::\/GH''94\/::\__>::::::::::/\n/:::::::::::::::::::::::::::::::::::::::/\n -== PrO-DmScHeCk v1.0 - DMS checker ==-\n -==   Fastest DMS checker around    ==-\n©MAYDAY.. MAYDAY.. INTRUDERS ENTER MEN-TEL!©\n','\n',char(10)),'PrO-DmScHeCk.Guide',replace('@database PrO-DmScHeCk.guide\n@$VER: PrO-DmScHeCk.guide v1.0 (15-Jun-94)\n\n@node MAIN "PrO-DmScHeCk Contents"\n            @{b}@{u}Documents for PrO-DmScHeCk v1.0@{ub}@{uu}\n\n             PrO-DmScHeCk was written by Exodous/TLS & XPress\n                           Released on 15-Jun-94\n\n                      1)  @{" What is PrO-DmScHeCk ? " link WHAT_IS_PDC}\n                      2)  @{" Command line options   " link PDC_OPTS}\n                      3)  @{" Installation           " link INSTALLATION}\n                      4)  @{" Distribution           " link DISTRIBUTION}\n                      5)  @{" Greetings              " link GREETINGS}\n                      6)  @{" Contacting me          " link CONTACTING_ME}\n                      7)  @{" Call These BBS''s       " link BBS_ADS}\n                      8)  @{" History                " link HISTORY}\n                      9)  @{" Other programs         " link OTHER_PROGS}\n\n                PrO-DmScHeCk was written in 100% assembler.\n@endnode\n\n@node WHAT_IS_PDC "What is PrO-DmScHeCk"\n                     @{u}What is PrO-DmScHeCk ?@{uu}\n\nPrO-DmScHeCk is a DMS file checker meant to be run from a BBS when a\nDMS file has been uploaded.\n\nIt allows other BBS adverts to be stripped from the file, and your own\nBBS adverts can be added to advertise your BBS.\n\nPrO-DmScHeCk was originally written for @{"THE TOWER" link BBS_ADS}, and was written\nin 680x0 assembler using Devpac 3 from HiSoft.\n\n@endnode\n\n@node PDC_OPTS "PrO-DmScHeCk Options"\n               @{u}PrO-DmScHeCk''s command line options@{uu}\n\nUsage : @{b}PrO-DmScHeCk@{ub} [-<options>] <filename>\n\nWhere options is one or more of :\n\n   @{b}b@{ub} - Add a tail banner (from @{b}S:PDC_Banner_Rear@{ub})\n\n   @{b}f@{ub} - Add a front banner (from @{b}S:PDC_Banner_Front@{ub})\n\n   @{b}t@{ub} - Add a track 0 banner (from @{b}S:PDC_Track_Zero@{ub}\n                             this file @{b}MUST@{ub} be 960 bytes long.)\n\n   @{b}d@{ub} - Add the current time and/or date to one/all of the\n                text to be added.\n\n      When ''##-###-###'' appears in a file the date will be added,\n       and when ''##:##'' appears the current time will be added.\n\n  @{b}R@{ub} - Remove existing front/tail banners.\n\n  @{b}T@{ub} - Remove existing track 0 banners.\n\n@endnode\n\n@node INSTALLATION "How to install PrO-DmScHeCk"\n                    @{u}Installation instructions@{uu}\n\n@{u}Installation for normal command line usage@{uu}\n\nCopy @{b}Utils/PrO-DmScHeCk@{ub} to anywhere in your path (usually C:).\n\n@{u}Installation for Ami-Express BBS usage@{uu}\n\nCopy @{b}Utils/PrO-DmScHeCk@{ub} to @{b}BBS:Utils/PrO-DmScHeCk@{ub}\nCopy @{b}FCheck/DMS.info@{ub} to @{b}BBS:FCheck/DMS.info@{ub}\nCopy @{b}S/PDC_Banner_Front@{ub} to @{b}S:PDC_Banner_Front@{ub}\nCopy @{b}S/PDC_Banner_Rear@{ub} to @{b}S:PDC_Banner_Rear@{ub}\nCopy @{b}S/PDC_Track_Zero@{ub} to @{b}S:PDC_Track_Zero@{ub}\n\nEdit the files @{b}S:PDC_Banner_Front@{ub} (any size),\n               @{b}S:PDC_Banner_Rear@{ub} (any size)\n           and @{b}S:PDC_Track_Zero@{ub} (960 bytes)\n\n to suit your own BBS.\n\nNow when a DMS file is uploaded it will be automatically checked for\nvalidity and integrity by PrO-DmScHeCk.\n@endnode\n\n@node DISTRIBUTION "Distribution restrictions"\n                  @{u}Distribution of PrO-DmScHeCk@{uu}\n\nPrO-DmScHeCk is (c)1994 Exodous/TLS & XPR and may be distributed in any\nway as long as the following conditions are met :\n\n  @{b}o@{ub}  All of the files are included, unchanged.\n  @{b}o@{ub}  No money changes hands (ie @{b}NO@{ub} PD library distribution)\n\n@endnode\n\n@node GREETINGS "Greetings"\n\nGreetings to the following people :\n\n    @{b}Oll¿e@{ub}\n    @{b}GrassHopper@{ub}\n    @{b}FireFlash@{ub}\n    @{b}M¿sta Are@{ub}\n    @{b}Mike@{ub}\n\nAll members of @{b}TLS@{ub} and @{b}XPress@{ub}.\n@endnode\n\n@node CONTACTING_ME "How to contact me"\n                          @{u}How to contact me@{uu}\n\nI can be contacted via E-Mail in the following ways :\n\n @{"Q.E.D" link BBS_ADS}     : Exodous\n @{"The Tower" link BBS_ADS} : Exodous\n\n Internet :\n\n  [email removed]      (If this address bounces then use the next one)\n  [email removed]\n@endnode\n\n@node BBS_ADS "Call these BBS''s"\n                  @{u}Call these great XPress BBS''s@{uu}\n\n@{b}Q.E.D@{ub} (WHQ)         : +44 (0)91-372-1911 (2 Nodes) - @{b}GRASSHOPPER@{ub}.\n\n@{b}SLEEZY BBS@{ub} (UKHQ)   : +44 (0)422-367-163 (1 Node)  - @{b}BONEIDLE@{ub}.\n\n@{b}MEDUSA DOMAIN@{ub} (CHQ) : +1 905-574-7791    (6 Nodes) - @{b}MEDUSA@{ub}.\n\n@{b}BIO HAZARD@{ub} (CHQ)    : +1 905-841-0965    (3 Nodes) - @{b}KAPT. KAOS@{ub}.\n\n@{b}THE LAB@{ub} (CHQ)       : +1 514-745-7420    (3 Nodes) - @{b}P.R SINISTER@{ub}.\n\n@{b}WAREZ DEPOT@{ub} (USHQ)  : +1 305-819-9925    (3 Nodes) - @{b}AMIGAMAN@{ub}.\n\n                  @{u}Call these other great BBS''s@{uu}\n\n@{b}THE TOWER@{ub} (LsD UKHQ): +44 (0)204-384-453 (2 Nodes) - @{b}FIREFLASH@{ub}.\n                      +44 (0)204-371-868\n\n@endnode\n\n@node HISTORY "The history of PrO-DmScHeCk"\n                     @{u}History of PrO-DmScHeCk@{uu}\n\n| Ver   | Date          | Comment\n+-------+---------------+--------------------------------------------\n| 1.0   | 15-Jun-94     | First version.\n+-------+---------------+--------------------------------------------\n@endnode\n\n@node OTHER_PROGS "Other programs that I have written"\n         @{u}Here is a list of other programs that I have written@{uu}\n\n@{b}BootUte@{ub}      : Degrader type utility for @{i}newer@{ui} Amiga''s....\n               Needs Kickstart 2.0+. Features easy to use gadtools\n               interface.\n\n@{b}BullRead@{ub}     : Bulletins door for /X that allows users to search\n               bulletins while they are on-line, or download the bulletins\n               for viewing whilst off-line.\n\n@{b}X-Zippy@{ub}      : Replacement zippy search door for /X that can search\n               for multiple items at a time, about 3 times faster\n               than the built in zippy!!\n\n@{b}UserCom@{ub}      : Door for /X that allows users to make comments to files\n               so that others will know if the file is old, fake etc.\n\n@{b}PrO-LhAcHeCk@{ub} : LhA file checker - for user with most BBS systems.\n               Strips most other adverts and adds own adverts that are\n               virtually unstrippable.\n\n@{b}Decrunch@{ub}     : CLI based decruncher to decrunch loads of different\n               packed files.\n\n@{b}PPPatch@{ub}      : PowerPacker Patcher... Patches the headers of PowerPacked\n               files so that they can''t be decrunched.\n\n@{u}Projects I''m working on@{uu}\n\n@{b}EBBS@{ub}         : En¿gma Bulletin Board System\n               My own host BBS, written entirely in Assembler with loads\n               of features : Kickstart 2.0+ only.\n\n@{b}xxxx-NuKe@{ub}    : Program similar to Boss-Nuke (for /X) that allows files\n               to be nuked, givent extra credits etc., will run from /X\n               as a door, or from the CLI/WB and display a user interface\n               (Kickstart 2.0+ only)\n\n@{b}GFC@{ub}          : Graphics Format Converter\n               A great graphics converter for loads of different formats...\n               (Kickstart 2.0+ only)\n\n@{b}Shell Menu@{ub}   :\n               A program similar to Tools-Daemon and the like, but to\n               add menu''s to the Shell window.\n\n@{b}E-Dos@{ub}        : Enigma-DOS\n               Replacement floppy-disk filing system with in-line\n               encryption for transferring/storing private information.\n\n\nIf you have any suggestions for features that you would like to see in\nany of the programs then e-mail me with your suggestions.\n\n@endnode\n','\n',char(10)),NULL,'auto-added',12125,7,0,NULL,NULL,'pdms_chk','scan',1780048671);
INSERT INTO door_catalog VALUES('peb_ch01','PEB-CH01.LZH','~/Code/amiexpress_doors/Archives/AmiExpress/PEB-CH01.LZH','checker','XIM','PacMan',NULL,NULL,'PEB',':    /  _   /  ____/  __ \  The BBS That   : :   /  /_/ /  /_  /  /_/ /  Brings You Even: |  /  ___ /  __/ /  __ _/   The Utils You  |',replace('.     ___________________                  .\n:    /  _   /  ____/  __ \  The BBS That   :\n:   /  /_/ /  /_  /  /_/ /  Brings You Even:\n|  /  ___ /  __/ /  __ _/   The Utils You  |\n| /  /   /  /___/  /_/ /        Need ...   |\n|/__/   /______/______/         With       |\n`------------------------------------------''\nChecker v0.1 : Checks what is diffrent\nbetween 2 filelists and tells you what the\ndifrence is.\nGreat traders tool!!!!\n','\n',char(10)),'PacMan.Guide','FORM',NULL,'auto-added',72864,3,0,NULL,NULL,'peb_ch01','scan',1780048671);
INSERT INTO door_catalog VALUES('pfe_litt','PFE-LITT.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PFE-LITT.LHA','LittleStatus','XIM','_ _/\______/\______/\___ _',NULL,'Charlie/Lsd','PFE','___  ___ __  ______  ____ _ _ ___/   ____/  _____/ ____/\ _ /____  /_____  /_____  /\/______________',replace('    _ _/\______/\______/\___ _\n    ___  ___ __  ______  ____ _\n_ ___/   ____/  _____/ ____/\\n _ /____  /_____  /_____  /\/______________\n|  \____\/\_____\/\_____\/ /               |\n|   ¯¯¯¯ \/¯¯¯¯¯ \/¯¯¯¯¯ \/   [ pROFiLE ]  |\n|  Little Status v1.0  For /X 2.3x+        |\n|        Code : Charlie/Lsd^PFE            |\n!                                          !\n`÷----------------------------------÷RandY÷''\n\n\n\n','\n',char(10)),'LittleStatus.DOC',replace('\n\n                   LittleStatus v1.0 By Charlie/LSD^PFE \n                  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n\nThis little status door was coded by me Charlie/LSD^PFE in AmigaE v3.2a.\nIt toke about 30-40 Mins to code. \n\n\nInstalling LittleStatus\n~~~~~~~~~~~~~~~~~~~~~~~\nJust copy Little(DIR) into Doors: \n	  Aedoor.library into LIBS: \n          S.Info into BBS:COMMANDS/BBSCMD/ \n	  S.Info into BBS:Commands/SYScmd/\n\nAnd that''s it!. \n\n\n\n\nGreetings to the following people.\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nDANSKEN,BOGGAN,WINGNUT,RECALL,RANDY,MATHEWS,BAGGEN \nWizard.\n\nIf you want to contact me then call these boards, and leave a mail to Charlie\n\nHall Of Fame  Node 1# +46 (0)910-26665    DANSKEN     ACCESS        SHQ (NUP) \n              Node 2# +46 (0)910-36665\n\nDual Access   Node 1# +46 (0)910-779578   Boggan      Dual Access   HQ \n              Node 2# +46 (0)910-77XXXX\n\nSkyLine       Node 1# +46 (0)691-30800    ReCall      Inhumans      WhQ (NUP)\n              Node 2# +46 (0)691-30996                LSD           SHQ \n              Node 3# +46 (0)691-30599                HellFire      SHQ \n\nHoliday Inn   Node 1# +46 (0)911-17887    Wingnut     PFE           WHQ\n\n','\n',char(10)),NULL,NULL,13470,4,0,NULL,NULL,'pfe_litt_littlestatus','scan',1780048671);
INSERT INTO door_catalog VALUES('pgs_sc10','PGS-SC10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PGS-SC10.LHA',NULL,'XIM','___________  ____________________ ____  ____',NULL,'Amiga/Pc','PGS','\____ \__  \_\_  \ ______  \ ___// __/ / __/ /_/  //  /  /  / \  \ /  /__/__\__ \_\__ \ _/ \__//  /\ /  /  /  //  /\   /   / /-Zo/ /',replace('___________  ____________________ ____  ____\n\____ \__  \_\_  \ ______  \ ___// __/ / __/\n  /_/  //  /  /  / \  \ /  /__/__\__ \_\__ \\n_/ \__//  /\ /  /  /  //  /\   /   / /-Zo/ /\n\___/__\___/___/_____/_\___/__/_____/_____/\n+- -- ----[ PROGRESS /X DIVISION ]---- -- -+\nSys-Call  v1.o  /X 3.x  &  /X 4.x   XiM-Tool\nDifferent Output  Screens For Amiga/Pc Users\nExample IFF Pictures Included. Read Docs For\nMore Infos!  Use It!  Written By ZoLDAN/PGS!\n','\n',char(10)),'Sys-Call.Guide',replace('@database Sys-Call v1.o By ZoLDAN/PGS\n\n(c) 1994 By ZoLDAN/PGS\n\n@Remark $VER: Version v1.o\nRemark AmigaGuide DataBase for Sys-Call v1.o By ZoLDAN/PGS\n\n@node MAIN "Sys-Call v1.o By ZoLDAN/PGS - Documentation For AmiExpress"\n\n   ________________ ________ __________________  _________________________\n:_/ ____    /_____/_\  ____/_\  ______________/__\_____\   _____/\  _____/_\n|   \______/\___   ¬\_ \/   ¬\_ \__  ¬\_\___ __¬\_ __/__\______  ¬\_____  ¬\_\n|    ¬|  |    |/     /        /   /    /  |/_\/_ / \|      / \/    /  \/    /\n|__   |  |____|_    /________/___     /___|_\/\//____     /_      /__      /\n:  \__|        ¯\__/            ¯\___/-TRE!¯\__/aC!  \___/ ¯\____/  ¯\____/\n\n\n          P R O G E S S   A M I E X P R E S S   D I V I S I O N\n \n                            P R E S E N T S\n\n                        S Y S - C A L L   V 1.o\n\n                   W R I T T E N   B Y   Z o L D A N\n\n                    @{"    P R E S S   B U T T O N    " Link start}\n\n@endnode\n@node start " Contents"\n\nContents Of This Documentation :\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n@{" Purpose             " Link Purpose}\n@{" Requirements        " Link Requirements}\n@{" Installation        " Link Installation}\n@{" Using This Tool     " Link Using}\n@{" Error Messages      " Link Error}\n@{" Credits             " Link Credits}\n@{" History             " Link History}\n@{" Greetings           " Link Greetings}\n\n@endnode\n@node Purpose " Purpose"\n\n        Purpose\n        ~~~~~~~\n        Well, why another damned AmiEx Tool, which is (you think so)\n        released millions times before? An Operator Chat door? I''ve\n        already installed one, so fuck off! No! Stop! Befor you close\n        this docs, let me tell you, what this door *CAN*, which other\n        doors *CAN NOT*!\n        This door is one of my special Ansi-Style doors. AmiEx has the\n        option for the user, to choose between different Ansi-Styles.\n        And nowerdays, where many Amiga & Pc users calls on AmiEx-Systems,\n        why not make different ansi screens for them! Look in your\n        bbs:screenstypes.info icon, there you can define different screen\n        types (but more to that later!). This door recognises *WHICH*\n        ScreenType the user has choosen, and displays a different screen\n        for Amiga and Pc Users!\n        (Look for the example iff-picture in this archive!)\n\n                                                            @{" Main Menu  " Link start}\n\n@endnode\n@node Requirements " Requirements"\n\n        Requirements\n        ~~~~~~~~~~~~\n        Amiga 500/600/1000/1200/2000/2500/3000/4000/CD³²\n        Kickstart 2.x or higher\n        AmiExpress 3.x/4.x (It will not run on /X 2.x or S-Express !)\n\n                                                            @{" Main Menu  " Link start}\n\n@endnode\n@node Installation " Installation"\n\n        Installation\n        ~~~~~~~~~~~~\n        - Copy the O.info in your bbs:commands/bbscmd dir\n        - Copy the Sys-Call.XiM to your DOORS:PROGRESS/ dir\n          (well, if you do not have one - make one 8=) )\n        - Installation of your BBS:ScreenTypes.Info\n          an example screentypes.info icon should look like this:\n\n          ----------------- cut ------------------\n          TYPE.1=TXT\n          TITLE.1=AMiGA ANSi\n          TYPE.2=IBM\n          TITLE.2=PC ANSi\n          ----------------- cut ------------------\n\n          as you see, all amiga-screens have now the termination .txt,\n          like bbs:bull.txt, bbs:node0/logoff.txt etc.\n          and all pc-screens have now the termination .ibm, like\n          bbs:bull.ibm, bbs:node1/login.ibm etc.\n          right now, only these two screentypes (TXT & IBM) are supported,\n          so do not use terminations like .pc or .amiga etc.\n          in a future version i will do this configurable in a config-file.\n          just use the included ScreenTypes.info Icon in this archive and\n          you will not have any problems!\n          (by the way, if a user has selected IBM-Screens, and you haven''t\n          any special ibm-screens like bbs:bull.ibm, AmiEx shows\n          automaticly bbs:bull.txt !!)\n\n                                                            @{" Main Menu  " Link start}\n\n@endnode\n@node using " Using This Tool"\n\n        Using This Tool\n        ~~~~~~~~~~~~~~~\n        Well, it''s really not that complicate to use this tool. But there\n        are some features which are worth to mention.\n        The normal use of this tool is sysop-calling by the user. He has\n        to write a reason, why he wants to chat. This reason is stored\n        in a special Answer-Log. If now the sysop enters the system and\n        HE starts the tool, an extra sysop screen is opened where this\n        Answer-Log is displayed! The sysop can now read the reasons and\n        delete this answer-log if he wants.\n        Another way is displaying this Answer-Log as a bulletin at a\n        sysop-login or whatever! The filename is\n\n        DOORS:PROGRESS/Sys-Call.Answers\n\n        Do it like this ...\n\n        --------------- cut --------------------\n        ~\n        ~f\n        ~SS_BBS:Screens/LastCallers.txt\n        ~SP\n        ~f\n        ~SS_DOORS:PROGRESS/Sys-Call.Answers\n        --------------- cut --------------------\n\n        This may be a bbs:node3/bull0.txt or login.txt or or or or.\n        Be sure to do this only at your sysop-node :)\n        Well think this way is much better than searching the chat-reasons\n        through the callerslog .. (which you can still do, of coz :)\n\n                                                            @{" Main Menu  " Link start}\n\n@endnode\n@node Error " Error Messages"\n\n        Error-Messages\n        ~~~~~~~~~~~~~~\n        `o-> Please Tell Sysop To Check BBs:ScreenTypes.info\n\n             Well, you haven''t made your bbs:screentypes.info icon\n             correct. Look in the Installation part or just copy\n             the supported icon to your bbs: dir!\n\n                                                            @{" Main Menu  " Link start}\n\n@endnode\n@node Credits " Credits"\n\n        Credits\n        ~~~~~~~\n                  This Door And This Documentation Is\n                (c) 1994 by [·ZoLDAN^PROGRESS^ESQUIRE·]\n                          All Rights Reserved\n\n                 Thanks to Mogue! for the Sysop-Ascii!\n             Thanks to SantaCruz for the Great Face-Ascii!\n\n          To get in touch with me try to reach me on any elite-bbs.\n            Please tell me all bugs, suggetions etc. to make these\n         doors more perfect! Remember: They are made for your pleasure!\n\n                                                            @{" Main Menu  " Link start}\n\n@endnode\n@node History " History"\n\n        History\n        ~~~~~~~\n        o.x  -> Many many ß-Versions, not worth to mention!\n\n        1.o  -> First official release. No Known bugs.\n\n        Future plans: - Your suggest!!\n\n                                                            @{" Main Menu  " Link start}\n\n@endnode\n@node Greetings " Greetings"\n\n        Greetings\n        ~~~~~~~~~\n        Some greetins are flying to .....\n\n        sILVEr!, Ghandy, Matt, mAZ!, sLE, SantaCruz, Mercury, Blackbird\n        Transformer, Kane, redSkin!,  Faceman, Mogue!, MaxiLine, Sargor\n        -fRB, Perry,  Aliex, Cujo, Hoppi, Maverick, Paranoid, Gamma Ray\n        Deathrider, Calypso, Jeff Staine, Dr.Byte, Darkman, MDB, DefJam\n\n                                ... and to all PGS-Members worldwide 8)\n\n        Some special greetings to my beta-testers, namely:\n\n                       Dr. Byte - StarGlider\n                       Mercury  - Doom Of Extasy\n                       Perry    - Solar System\n                       Maverick - Cryptic Slaughter\n                       Solaris  - Solarko\n                       MDB      - Love Like Blood\n\n          Hey Paranoid, come to Mortuary and we''ll meet again 8=)\n\n                                                            @{" Main Menu  " Link start}\n\n@endnode\n','\n',char(10)),NULL,NULL,33609,2,0,NULL,NULL,NULL,'scan',1780048671);
INSERT INTO door_catalog VALUES('pgs_sm38','PGS-SM38.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PGS-SM38.LHA','rexxmast','XIM','rexxmast',NULL,'wILDSTYLE/pROGRESS`94!]','PGS','+\______  ¬\  ______/  _____/--------------+ |_/    /   /  \_  ¬\_____ ¬\_ $ PROGRESS $ | |\   _____/    /    /   /   / /X-Division! |',replace(' ____________________________               \n+\______  ¬\  ______/  _____/--------------+\n|_/    /   /  \_  ¬\_____ ¬\_ $ PROGRESS $ |\n|\   _____/    /    /   /   / /X-Division! |\n+-\__/----\________/_______/---------------+\n| [!SMPage v3.8 by wILDSTYLE/pROGRESS`94!] |\n| [small vers. ^ Operator Win ^ +Sourcec.] |\n+------------------------------------------+\n','\n',char(10)),'small-page.doc',replace('\n\n\n\n\n\n\n\n _ __ _________________________________________________________________ __ _\n \\\_\\____    /  _    /  _   /  ______/  _   /  _____/  _____/  _____//_///\n    _/    _    \_ _   /_  \   \_ \_   \_  _  /_  _/   \___    \___    \_\n    \_    \_____  \     \_    _/      _/  \    \_     _/      _/      _/\n _ ____ ___/ \____/ CoZ  _________________/     ____________________ _____ _\n      \/         \  _____/   a m i e x   \  ____/  d i v i s i o n  \/\n\n\n\n\n\n\n\n\n\n                          ____                              ._\n                _____/\__(____)__  /\  _____/\ .__/\_  .____| \__\n               /__      /(____)  \/  \ \      \|    _) |    |   /\n              _\\/ __  /\|    |     __\_\___   \    |__/\   |   \\n             |  \___ \/  \_   |     \/ \_       \   |    \___    \_\n             |_/\________ /___|__\/____ /_ _____/_______ /____/\_ /\n             |    _______/____|  ||____/   |   |______  /______  /\n             |____|coZ      |____|    |  /\:          \/       \/\n                _ __ _____/\  _____/\ :\/  |______________ __ _\n               \\\\ \\      \|       \|__       /        // ////\n                \\\\_\\___   \    _   \\/   ___/_   ____//_////\n                    |         \        \_  (     |  _/    |\n                    |/\  _____/___|_/\_ /_____/\_|____  /\|\n                    |  \/|   |    |__  /_____    |____\/  |\n                    |____|   |____|  \/     |____|   |____|\n\n\n\n                             SMALL VERSION OF THE\n\n                 sIMPLY-pAGE! V3.8 © 199³ bY wILDSTYLE/pROGRESS\n                             ® 1993/94 by pROGRESS!            \n                                 mADE iN gERMANY!\n\n                           ( * = public released )\n\n                   V0.1ß - Private Testing.. With Many Bugs\n                   V1.0  - A Little Arexx Speed Improvement.\n                   V1.2  - A few Improvements\n                 * V1.6  - First Public Release Version.\n                   V1.8  - Bug fixed\n                   V2.3  - Azci total update , new samples\n                           new features                     \n                 * V2.6  - Ascii total update , some bug`s\n                           fixed , operator window includet,\n                           config file changed , minimum word\n                           checker includet\n                   V2.7  - The first Sm version.. with some\n                           Bugs..\n                 * V3.8  - Small version codet with the same\n                           op-window.. without samples\n                           for all computer types with uncrunched\n                           arexx routine\n \n\n                 note: this tool requiers /X 3.xx or higher!    \n\n\n\nz=( A B O U T )=zZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZ\n\nwelcome...\n\nprogress presents a sysop pager , the simply page (:\nsimply doesnt mean that this tool is build up simpel... it should mean that\nthis tool is easy and special configured... and so also one of the best chat\ntoolz.\n\nbecause not every lamer shall page the sysop, i have turn`d my pager\nalmost 24 hours off. this pager lets you, eventhough the chat flag is turned\noff, page the operator...\nthis is possible with different pass/key - words... these pass/key - words are\nfreely configureable...hehehe.. yoU can also give those fucking lamers no chat\naccess anymore. or not even let them finish the command line hehehe\nthe operator page protocols every comment from the users.\n\n"simply" is the name under witch lots of my toolz will be realeased! this tool\nis written in arexx... Nah.. its not compiled! look in the routine if u interested\non the code.\n\n\nz=( I N S T A L l )=zZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZ\n\nafter you have decruched the file like into the RAM: and put all files into\nthe right paths. i think that that isen`t the main problem for the sysop\n\ncopy the simply (dir) in the doors: assignment , and the "o.info" in the\nbbs:commands/bbscmd.\n\ncopy the Progress.library in the libs!.. dont forget that!\n         ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n\nz=( C O N F I G )=zZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZ\n\nyou found the config file in "doors:simply/smpage/Small-page.cfg"\n\n----------------(cut here)\nSPECIAL_PASSWORD=jay\nWAIT_WINDOW_MAX=5\nALL_TIMES_CHATABLE.LEVEL=254\nWINDOW_TOGGEL=On\n----------------(cut here)\n\nSPECIAL_PASSWORD   => you can chat the sysop every times (denied ,or not!)\n                      with this passwords.. nice ey?\nWAIT_WINDOW_MAX    => the second how long the pagewindow will be display`d\nALL_TIMES_CHATABLE => security level ; all users they have this level , or \n                      higher can chats 24h without any on/off toggels\nWINDOW_TOGGEL      => (ON/OFF).. u dont interested on the call window?\n                      then toggel this switch off and the standart page\n                      option will be displayed\n\n\nz=( I N F O S ! )=zZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZ\n\n          I don`t take any warrenty for backdoors or other shit\n      like that, but be sure that my source is totally free of any\n                                backdoors !!!\n\n\nz=( C r e d i t s )=zZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZzZ\n\n\n                  code - idea and dezign by wildstyle/pgs\n                library and pagewindow codet by strider/pgs\n\n                     \n                           gangstars district bbs\n                            2ndz 16.8 / reg amix\n                              +49-30-348-2915\n                              +49-30-ask-forit\n                             sysop : wildstyle\n                            only legal stuff (;\n\n\n\n\n\n\n\n\n                          g   r   e   e   t   s   :\n\n                  to all who knows me , can feel greeted.\n\n                             s i g n    o f  \n\n\n                        .________________________.                 \n                        |_________               |                 \n               ________ \      _ /     _____     |                 \n               \ _    / |\     //\    /.   /   /\|________         \n                \\   /_/\_\   o/__\  //   /___/_____   _ /         \n                 \    /  \    /    \/    /    /    /   //          \n                  \____/\____//    /_________/    /   ./           \n         _ __ __       .|   /________\      /________ /   __ __ _  \n       _ ___ /_/\      ||                        |  \/   /\_\ ___ _\n         _ __\_\/      :|  W i l d    s t y l e  |:      \/_/ __ _ \n           ________/\   |                  _____ ||                \n           \ _    ___\  /\______          /  _ / |___________      \n            \\     \   / o _   /____/\___/   //__|\___      /       \n           __\.     \ /   \\__/    /    /    /    /  /_____/_      \n           \ ________\      \/____     /_________/    \     /      \n            \/      /________\   /    /          \________ /          \n                        |  /_________/           |   Sk!n\/        \n                        |________________________|                 \n                        :                        :    \n\n\n\n\n\n\n\n\n\n\n\n              o           t           h           e           r                       \n\n\n                           * /X D I V I S I O N *\n\n    ________  ________  ________  _____________  ________  _______   _______\n   _\___   ¬\_\___   ¬\_\___   ¬\/    /\___   ¬\_\___   ¬\_\___   ¬\_\___  ¬\\n  /÷   /    /÷   /____/÷   /    /÷   /÷   /____/÷   /____/÷   /    /÷   /___/\n /         /        \/    /    /    /    ____>     /    /    /____/\____  ¬\ \n/    /____/    /    /    /    /    /    /    /    /    /    /    /     /   / \n\___/     \___/____/\________/    /\________/\________/\___/     \________/  \n                        /   /    /\n                        \_______/\n\n             * LOGOFF V1.4          WILDSTYLE/PGS `n MURDOC/AFL\n             % LOGOFF V3.01         WILDSTYLE/PGS\n             · SPC BULLETIN V2.2    WILDSTYLE/PGS\n             * SIMPLYPAGE V1.6      WILDSTYLE/PGS\n             % DELUX-WHO V1.5       STRIDER/PGS `n WILDSTYLE/PGS\n             % DigiClock v1.57      STRIDER/PGS\n             · X-NET V2.1           WILDSTYLE/PGS\n             * S-SECURITY V1.01     WILDSTYLE/PGS\n             * SIMPLY COMMENT 2.1   WILDSTYLE/PGS\n             · VOTE NOW 2.2         WILDSTYLE/PGS\n             · SIMPLYPAGE 2.3       WILDSTYLE/PGS\n             * SIMPLYPAGE 2.7       WILDSTYLE/PGS\n             % ULTopCps V1.07       STRIDER/PGS\n             % TodayUp Deluxe       STRIDER/PGS\n             * SStatus v1.46        STRIDER/PGS\n             % SSecurity 1.3        WILDSTYLE/PGS\n            >* SMpage v3.8          WILDSTYLE/PGS<\n\n                              (*) RELEASED!\n                            (%) INCOMMING SOON!\n                            (·) INTERN RELEASED\n\n\n','\n',char(10)),NULL,'auto-added',97374,5,0,NULL,NULL,'pgs_sm38','scan',1780048671);
INSERT INTO door_catalog VALUES('pgs_ss10','PGS-SS10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PGS-SS10.LHA',NULL,'XIM','___________  ____________________ ____  ____',NULL,'Amiga/Pc','PGS','\____ \__  \_\_  \ ______  \ ___// __/ / __/ /_/  //  /  /  / \  \ /  /__/__\__ \_\__ \ _/ \__//  /\ /  /  /  //  /\   /   / /-Zo/ /',replace('___________  ____________________ ____  ____\n\____ \__  \_\_  \ ______  \ ___// __/ / __/\n  /_/  //  /  /  / \  \ /  /__/__\__ \_\__ \\n_/ \__//  /\ /  /  /  //  /\   /   / /-Zo/ /\n\___/__\___/___/_____/_\___/__/_____/_____/\n+- -- ----[ PROGRESS /X DIVISION ]---- -- -+\nStatus  Scan  v1.o /X 3.x & /X 4.x  XiM-Tool\nDifferent Output  Screens For Amiga/Pc Users\nExample IFF Pictures Included. Read Docs For\nMore Infos!  Use It!  Written By ZoLDAN/PGS!\n','\n',char(10)),'Status.Guide',replace('@database Status Scan v1.o By ZoLDAN/PGS\n\n(c) 1994 By ZoLDAN/PGS\n\n@Remark $VER: Version v1.o\nRemark AmigaGuide DataBase for Status Scan v1.o By ZoLDAN/PGS\n\n@node MAIN "Status Scan v1.o By ZoLDAN/PGS - Documentation For AmiExpress"\n\n   ________________ ________ __________________  _________________________\n:_/ ____    /_____/_\  ____/_\  ______________/__\_____\   _____/\  _____/_\n|   \______/\___   ¬\_ \/   ¬\_ \__  ¬\_\___ __¬\_ __/__\______  ¬\_____  ¬\_\n|    ¬|  |    |/     /        /   /    /  |/_\/_ / \|      / \/    /  \/    /\n|__   |  |____|_    /________/___     /___|_\/\//____     /_      /__      /\n:  \__|        ¯\__/            ¯\___/-TRE!¯\__/aC!  \___/ ¯\____/  ¯\____/\n\n\n          P R O G E S S   A M I E X P R E S S   D I V I S I O N\n \n                            P R E S E N T S\n\n                    S T A T U S   S C A N   V 1.o\n\n                  W R I T T E N   B Y   Z o L D A N\n\n                    @{"    P R E S S   B U T T O N    " Link start}\n\n@endnode\n@node start " Contents"\n\nContents Of This Documentation :\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n@{" Purpose             " Link Purpose}\n@{" Requirements        " Link Requirements}\n@{" Installation        " Link Installation}\n@{" Error Messages      " Link Error}\n@{" Credits             " Link Credits}\n@{" History             " Link History}\n@{" Greetings           " Link Greetings}\n\n@endnode\n@node Purpose " Purpose"\n\n        Purpose\n        ~~~~~~~\n        Well, why another damned AmiEx Tool, which is (you think so)\n        released millions times before? A Status Scan door? I''ve\n        already installed one, so fuck off! No! Stop! Befor you close\n        this docs, let me tell you, what this door *CAN*, which other\n        doors *CAN NOT*!\n        This door is one of my special Ansi-Style doors. AmiEx has the\n        option for the user, to choose between different Ansi-Styles.\n        And nowerdays, where many Amiga & Pc users calls on AmiEx-Systems,\n        why not make different ansi screens for them! Look in your\n        bbs:screenstypes.info icon, there you can define different screen\n        types (but more to that later!). This door recognises *WHICH*\n        ScreenType the user has choosen, and displays a different screen\n        for Amiga and Pc Users!\n        (Look for the example iff-picture in this archive!)\n\n                                                            @{" Main Menu  " Link start}\n\n@endnode\n@node Requirements " Requirements"\n\n        Requirements\n        ~~~~~~~~~~~~\n        Amiga 500/600/1000/1200/2000/2500/3000/4000/CD³²\n        Kickstart 2.x or higher\n        AmiExpress 3.x/4.x (It will not run on /X 2.x or S-Express !)\n\n                                                            @{" Main Menu  " Link start}\n\n@endnode\n@node Installation " Installation"\n\n        Installation\n        ~~~~~~~~~~~~\n        - Copy the S.info in your bbs:commands/bbscmd dir\n        - Copy the Status.XiM to your DOORS:PROGRESS/ dir\n          (well, if you do not have one - make one 8=) )\n        - Installation of your BBS:ScreenTypes.Info\n          an example ScreenTypes.Info icon should look like this:\n\n          ----------------- cut ------------------\n          TYPE.1=TXT\n          TITLE.1=AMiGA ANSi\n          TYPE.2=IBM\n          TITLE.2=PC ANSi\n          ----------------- cut ------------------\n\n          as you see, all amiga-screens have now the termination .txt,\n          like bbs:bull.txt, bbs:node0/logoff.txt etc.\n          and all pc-screens have now the termination .ibm, like\n          bbs:bull.ibm, bbs:node1/login.ibm etc.\n          right now, only these two screentypes (TXT & IBM) are supported,\n          so do not use terminations like .pc or .amiga etc.\n          just use the included ScreenTypes.info Icon in this archive and\n          you will not have any problems!\n          (by the way, if a user has selected IBM-Screens, and you have not\n          any special ibm-screens like bbs:bull.ibm, AmiEx shows\n          automaticly bbs:bull.txt !!)\n\n                                                            @{" Main Menu  " Link start}\n\n@endnode\n@node Error " Error Messages"\n\n        Error-Messages\n        ~~~~~~~~~~~~~~\n        `o-> Please Tell Sysop To Check BBs:ScreenTypes.info\n\n             Well, you haven''t made your BBS:ScreenTypes.Info icon\n             correct. Look in the Installation part or just copy\n             the supported icon to your bbs: dir!\n\n                                                            @{" Main Menu  " Link start}\n\n@endnode\n@node Credits " Credits"\n\n        Credits\n        ~~~~~~~\n                  This Door And This Documentation Is\n                (c) 1994 by [·ZoLDAN^PROGRESS^ESQUIRE·]\n                          All Rights Reserved\n\n          To get in touch with me try to reach me on any elite-bbs.\n            Please tell me all bugs, suggetions etc. to make these\n         doors more perfect! Remember: They are made for your pleasure!\n\n                                                            @{" Main Menu  " Link start}\n\n@endnode\n@node History " History"\n\n        History\n        ~~~~~~~\n        o.x  -> Many many ß-Versions, not worth to mention!\n\n        1.o  -> First official release. No Known bugs.\n\n        Future plans: - Your suggest!!\n\n                                                            @{" Main Menu  " Link start}\n\n@endnode\n@node Greetings " Greetings"\n\n        Greetings\n        ~~~~~~~~~\n        Some greetins are flying to:\n\n        sILVEr!, Ghandy, Matt, mAZ!, sLE, SantaCruz, Mercury, Blackbird\n        Transformer, Kane, redSkin!,  Faceman, Mogue!, MaxiLine, Sargor\n        -fRB, Perry,  Aliex, Cujo, Hoppi, Maverick, Paranoid, Gamma Ray\n        Deathrider, Calypso, Jeff Staine, Dr.Byte, Darkman, MDB, DefJam\n\n                                ... and to all PGS-Members worldwide 8)\n\n        Some special greetings to my beta-testers, namely:\n\n                       Dr. Byte - StarGlider\n                       Mercury  - Doom Of Extasy\n                       Perry    - Solar System\n                       Maverick - Cryptic Slaughter\n                       Solaris  - Solarko\n                       MDB      - Love Like Blood\n\n          Hey Paranoid, come to Mortuary and we''ll meet again 8=)\n\n                                                            @{" Main Menu  " Link start}\n\n@endnode\n','\n',char(10)),NULL,NULL,48263,3,0,NULL,NULL,NULL,'scan',1780048671);
INSERT INTO door_catalog VALUES('pgs_ssta','PGS-SSTA.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PGS-SSTA.LHA',NULL,'XIM','___________________________',NULL,'Strider','PGS','+-\______  ¬\  _____/  _____/--------------+ | _/    /   /  \_ ¬\_____ ¬\_ $ PROGRESS $ | | \   _____/    /   /   /   / /X-Division! |',replace('  ___________________________               \n+-\______  ¬\  _____/  _____/--------------+\n| _/    /   /  \_ ¬\_____ ¬\_ $ PROGRESS $ |\n| \   _____/    /   /   /   / /X-Division! |\n+--\__/----\_______/_______/---------------+\n| [SStatus v1.46 by Strider of ÷pROGRESs÷] |\n| [ animated formed Status for /X in XIM ] |\n+------------------------------------------+\n','\n',char(10)),'ZZC-TakeOver.guide',replace('@database "ByTeR¡DeRs - A CODERS DREAM COMES TRUE!"\n@Node MAIN "ByTeR¡DeRs"\n                 _______________________  _____________  ____               \n                 \  _ \  ___   _ \__  _ \/__/   \__  _ \/    \              \n                 /    /\/  /  / \/\/   _/ \ \  ¯¯\/   _/   __/              \n              /\/  /  \ /\/  /  __/    \  /  \  ¯¯\   \\__  \               \n              \_____/\/ \___/  __/  /\_/\/  / \___//\_/¯    /               \n              -¡££- \___/   \___/\_/   \______/ \_/   \____/                \n                                                                           \n                       ZIG ZAG CORPORATION GERMAN HQ\n\n                 Sysops: Joker/ZZC        - Ernesto/Indy  \n                         Illuminator/Indy - Jazzytech/Indy\n\n\n                        @{" Why should I call this BBS? " link "menu"}                   \n@endnode\n\n@node "menu" "ByTeR¡DeRs - Coders Paradise"\n@toc "menu"\n\n        Did you ever wonder where you can get in contact with a lot\n        of coders and cool scene people, not the usual scum lurking\n                      around on all the other BBS´s?\n            Did you ever had the opportunity to rummage through\n          an arsenal of 50+ Megs of Docs/Coding-Hints/Solutions?\n     Ever desperately looked for some way old game that wasn´t online\n                   anymore at all those "elite" boards?\n  Did you ever wanted to have all those nice /X tools that were floating\n   around over the year, and you did not dare to install them in fear of\n                                backdoors?\n         Ever had the feeling that everyone is able to BB but you?\n   Did you ever wanted to know where all those nice little programs are\n          tested before they get released weeks and months later?\n  Did you ever wonder where you can find all the new Public Domain stuff?\n \n            Well, this BBS is the answer to all these problems.\n\n              There is just one tiny little drawback for you:\n\n            Question: "How do I get the number?"\n            Answer:   "You don´t. If we feel you belong here, \n                       we will invite you."\n\n@endnode\n','\n',char(10)),NULL,NULL,26682,2,0,NULL,NULL,NULL,'scan',1780048671);
INSERT INTO door_catalog VALUES('pgs_who2','PGS-WHO2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PGS-WHO2.LHA',NULL,'XIM','What000.x',NULL,NULL,'PGS','\___  \__  \    \ ______  \ ___/ ___/ ___/ _/  ___/_  _/COZ / \  /_  _/_/ \__  \__  \ \__/ /__\__\____/____/_\__\____/____/____/',replace(' __________________________________________\n \___  \__  \    \ ______  \ ___/ ___/ ___/\n_/  ___/_  _/COZ / \  /_  _/_/ \__  \__  \ \n\__/ /__\__\____/____/_\__\____/____/____/ \n[--AMIGA SECTiON--][--/X TOOLS DiViSiON--] \n  AMI-EXPRESS VERSION WHO 2.1 DOOR [V]     \n   [INCLUDES BOBO/MYSTIC "WHAT" DOOR]\n','\n',char(10)),'What.Guide',replace('@DATABASE What.Guide\n@$VER: Guide for Upload Activities (3rd May 1994)\n\n@REMARK Copyright (c) 1994 Mystic.\n@REMARK All Rights Reserved.\n@REMARK Main Program and Document by Bobo/Mystic.\n\n@REMARK You need MultiView, Amigaguide or any other GUIDE viewer.\n\n@NODE MAIN "What: Contents."\n\n--------------------------------------------------------------------------\n    Upload Activities (WHAT) (Version 1.0) [RELEASE 1] - 3rd May 1994\n--------------------------------------------------------------------------\n\n          @{"[ Background and Purpose ]" Link Background}      @{"[ Available Tooltypes ]" Link Tooltypes}\n          @{"[    Notable Features    ]" Link Features  }      @{"[   Program History   ]" Link History}\n          @{"[  Install into Express  ]" Link Install   }      @{"[  Thanks and Greets  ]" Link Greets}\n\n--------------------------------------------------------------------------\n                 Copyright (c) 1994 by Bobo/Mystic\n--------------------------------------------------------------------------\n\n Example Outputs/Scripts come in seperate files with the release archive.\n@ENDNODE\n@NODE Background "What: Background and Purpose"\n[------------( Background and Purpose )-----------------------------------]\n\nUpload Activities is a door for amiexpress intended for MULTINODE systems\nonly and can''t be used on single node systems. The main purpouse of this\ndoor is to show if a user on any other node is uploading something, and if\nso, it tells you what''s in his batch queue and what files in his batch have\nalready been finished uploading.\n\nNOTE: Take a look at the included output example (What.Output)\n\nWHAT can be made resident. I really recommend you to do this, since\nit will speed this door up quite much, specially on 68000-68020 computers!\n@ENDNODE\n@NODE Features "What: Notable Features"\n[------------( Notable Features )-----------------------------------------]\n\nSeveral reasons to use Upload Activities:\n\n* Written entirely in C for fast code.\n* Can be made resident.\n* First kind of this door for amiexpress.\n* Configable playpen directories.\n* Special optimized versions for all CPU types.\n* 32-Node compatable. (Actually how many nodes you want)\n* Using Icons (/X3.x Standard Nowadays), but should work fine with /X2.x\n  and Sigma Express.\n@ENDNODE\n@NODE Install "What: Install into Express"\n[------------( Install into Express )-------------------------------------]\n\nThis door should be installed as a standard amiexpress door.\nOn /X3.x you have you have to edit (or create) a file called WHAT.INFO in\nyour BBSCmd directory. On /X2.x and SExpress you have to edit the\nBBS.Cmd in the usual way. Remember to give it a high stack (example 50000)\nand make it multinode. The door is an XIM type ofcourse!\n\nAlso, for added speed, you may make the door resident with your normal\n"resident" command (CLI: "Resident What.x PURE"). But if you do, make\nsure that Express runs just the doorfilename, without its path. On /X3.x\nyou also need the tooltype RESIDENT in the icon.\n\nYou also need a icon in doors:. Just create a info file named WHAT.INFO.\nMake it as a drawer icon to your DOORS:WHAT dir. Here you can put any\nof the available tooltypes listed later in this document.\n@ENDNODE\n@NODE Tooltypes "What: Available Tooltypes"\n[------------( Available Tooltypes )--------------------------------------]\n\nHere are the available tooltypes.\n\nTooltype-Name:                    Description:\n---------------------------------------------------------------------------\nNODES=<#nodes>                  - This tooltype is really not necessarly.\n                                  This is how many nodes you have. (Or how\n                                  many nodes you want to search through).\n                                  If this tooltype is not found, it will\n                                  search through all 32 nodes.\n\nDONOTSHOW_NODE<node>            - This will skip the search for upload on\n                                  the specified node.\n\nPLAYPEN_<node>                  - This is ONLY needed if you have external\n                                  playpen directories.\n@ENDNODE\n@NODE History "What: Program History"\n[------------( Program History )------------------------------------------]\n\n{ + }-New feature(s)         { - }-Removed feature\n{ * }-changed feature        { ! }-fixed feature (Bug)\n{ # }-Information            { ? }-let me know if this work\n\nWhat v0.5 (10-12-93 > 11-01-93) - [Private version for my board]\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nFirst version, coded in Arexx by Bobo\n\n10-12-93 { + } I started coding this door.\n - ^^ -  { + } Main source for listing a directory coded. (Using C:LIST)\n10-13-93 { * } Now using AREXXs inbuilt LIST command instaid of using C:LIST\n10-15-93 { * } Fixed a nicer design.\n10-17-93 { # } WHAT do not list the playpen directory in the correct order.\n               Hope i found away to do that in the future..\n\nWhat v1.0 (01-30-94 > 04-19-94) - [First public release version]\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nFirst C version, no bugs known!\n\n01-30-94 { + } Recoded the AREXX version of WHAT into C\n02-02-94 { ! } Now sorting the files in correct order.\n02-04-94 { * } Now using comma-seperator at the filelengths\n02-10-94 { + } Now showing Total files and Total bytes.\n02-13-94 { ! } Now unlocking files, libs and free allocated memory when a\n               error occur.\n02-16-94 { * } Now more optimized routine when reading from icons.\n03-14-94 { ! } ** MAJOR BUG DETECTED ** "What" did not lock the playpen dir\n               in shared mode! This means it could bug and guru when it\n               was used on two nodes at the same time.\n - ^^ -  { # } I would really need the routines to check if a node is quiet\n               or not! Tell me at once if you have any!\n - ^^ -  { + } Now you can have a icon in doors: WHAT.INFO.\n               Available tooltypes: SKIP_NODE<node>,NODES=<nodes>\n                                    START_NODE=<node>,PLAYPEN<node>=<dir>\n04-19-94 { - } Registration routines removed.\n               Final size: 14672 (Source 11414 with comments)\n@ENDNODE\n@NODE Greets "What: Thanks and Greets"\n[------------( Thanks and Greets )----------------------------------------]\n\nGreetings to: Pacific/2000 AD, Looby/Insane, Dee/Delight, Agressor/Anthrox,\n              Reactor/Mystic, Easy Rider/Mystic, Ufok/Mystic, Screwball!\n\nMany thanx to Byteandi/TRSI and Remo/Mystic for all help and support!\n\nAnd many many thanx to all my beta testers for bug-reports, suggestions and\nhints & tips to improve this door.\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',55023,6,0,NULL,NULL,'pgs_who2','scan',1780048671);
INSERT INTO door_catalog VALUES('pgs_eck','PGS_ECK.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PGS_ECK.LHA','EXCHK','XIM','EXCHK',NULL,'PANACEA','PGS','=========================================== EXCHK BY PANACEA - EXECUTABLE FILE CHECKER FOR /X AND/OR CLI USAGE.',replace('PROGRESS - FORWARD EVER - BACKWARD NEVER !!\n===========================================\nEXCHK BY PANACEA - EXECUTABLE FILE CHECKER\nFOR /X AND/OR CLI USAGE.\n','\n',char(10)),'EXCHK.guide',replace('@DataBase Executable Checker (EXCHK) Documentation\n@Author PANACEA\n@Index Documentation\n\n\n\n@Remark $VER: EXCHK-Doc. 1.0\n\n@node MAIN "Main Overview"\n\n\n  ______   ______   _______    ______    ______   ______   ______    ______\n:_\___  \__\___  \__\ ____/_: _\ ___/_: _\___  \__\  __ \__\  __/_  _\  __/_\n|     _._/    _  _/_  \/    |/   \_   |/    _  _/_  _____/\_____  \_\_____  \_\n|______|/_____/    /________|___  /  _|_____/    /_______\   ___.__/    ___._/\n:  ·p. :     /____/         : /______\:    /____/      /_______\|_/_______\|_\n                                                                :          :\n                      [·fORWARd eVEr, bACKWARd nEVEr!·]\n\n                                  PRESENTS\n\n                     EXCHK 1.5 - Executable File Checker\n\n                    Coded in 1994 by PANACEA of PROGRESS!\n\n                               @{" DOCUMENTATION " Link Doc}\n\n@endnode\n@node Doc\n\n\n\n\n\n\n                            @{"   WHAT''S EXCHK ?   " Link About}\n                            @{"  INSTALLING EXCHK  " Link Installation}\n                            @{"    FUTURE PLANS    " Link Plan}\n                            @{"      TROUBLES      " Link Important}\n                            @{"     GREETINGS!     " Link Greetings}\n                            @{"  ..AND REMEMBER..  " Link Remember}\n@endnode\n@node About "About EXCHK in general"\n\n        As the name says, EXCHK is a checker for executable files.\n        EXCHK has been tested on a non-accelerated Amiga 1200 and\n        it checked a file (size: 1.5 MB) in less than two seconds.\n\n        If you have the File_ID.library copied to your LIBS: directory,\n        EXCHK will give an information about the file''s structure, e.g.\n        which packer was used to crunch the checked file.\n\n        The usage is very simple, you will only have to specify the\n        filename ("EXCHK <file>"), and the rest is done automatically.\n\n@endnode\n@node Installation "How to install EXCHK"\n\n        If you want to run EXCHK from your bbs, copy EXCHK to your C:\n        directory and the EXE and RUN icons to your BBS:FCHECK\n        dir. Damaged files will be moved to your private directory\n        automatically.\n\n        EXCHK is no XIM door. You can run it from /X as well as from CLI.\n\n        If you have the FileID.library (Version 6.0 is recommended)\n        copied to your libs: directory, EXCHK will try to distinguish\n        if the file is executable at all, and if so if it''s packed with\n        a special cruncher (like RNC, CrM or PP).\n\n        Don''t forget to spell the name like this: FileID.library !\n        "fileid.library" will NOT work !\n\n@endnode\n@node Plan "Future Plans ..."\n\n        The continuity of EXCHK depends on the ideas which I would like\n        to realise and the ones I receive from other people. So if you\n        have an option/function/idea for EXCHK then try to reach me\n        on the BBS I am on (sorry, but I won''t say any name...).\n\n@endnode\n@node Important "Last Infos"\n\n        There are packers existing, which use a modified hunk structure,\n        e.g. the TITANICS-Cruncher does. It is not possible to\n        check whether the file is okay or not, thus EXCHK won''t move\n        them to private directory. Reason: These files mostly work.\n\n        Remember: If you have an executable file that EXCHK claimed\n        to be damaged anyway, please check it yourself before deleting it.\n        The File might work! Do not take the uploader''s credits at once!\n\n@endnode\n@node Greetings "Greetings"\n\n\n\n\n                         PRIMUS OF BIRDHOUSE PROJECTS\n\n\n\n\n                       ALL MEMBERS OF THE PROGRESS TEAM\n\n\n             BLOODROCK of SYNDICATE for his FileID.library V6.0 !\n\n\n@endnode\n@node Remember "Never forget ..."\n\n\n\n\n\n\n\n                        Scene - live long and prosper.\n\n                        Gebt Gravenreuth KEINE Chance!\n\n\n\n\n\n@endnode\n','\n',char(10)),NULL,'auto-added',15390,5,0,NULL,NULL,'pgs_eck','scan',1780048671);
INSERT INTO door_catalog VALUES('phinfo10','PHINFO10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PHINFO10.LHA','PhoneInfo','XIM','PhoneInfo',NULL,NULL,NULL,'| o _.   o _|  (_  _ _|_ _|_     _.._ _ |_|(_||_||(_|  __)(_) | _ |_\/\/(_|| (/_ |                 | \ _  _ o _ ._',replace('                __     _            \n| o _.   o _|  (_  _ _|_ _|_     _.._ _  \n|_|(_||_||(_|  __)(_) | _ |_\/\/(_|| (/_\n     |                 | \ _  _ o _ ._ \n        [ presents ]   |_/(/__> |(_|| |  \n                                 __|    \nPhoneInfo 1.0 - Tells callers how much their \n  call is costing them while calling you.\n .. A MAXs BBS door (c)1997 Steve Clack ..\n','\n',char(10)),'PhoneInfo.Guide',replace('@DATABASE "PhoneInfo 1.0"\n@NODE main "PhoneInfo 1.0"\n@{u}PhoneInfo 1.0 Docs ©1997 by Steve Clack of Liquid Software Design@{uu}\n\n  _:_____________________________:__\n   :                             :\n   :tHE eDGE! cALL:0(31)165385919:\n_ _:_____________________________:__\n   :                             :aB!\n\n\n\n    ____                         o\n   /   / /___  ____  ____  ____    ____  ____  ____\n  /___/ /   / /   / /   / /___/ / /   / /___  /   /\n /     /   / /___/ /   / /___  / /   / /     /___/  v 1 . 0\n\n                       United Kingdom\n   \n  > 1. @{" Introduction " LINK intro} <\n  > 2. @{" Disclaimer " LINK disclaimer} <\n  > 3. @{" Installation " LINK install} <\n  \n  > 4. @{" How to use " LINK use} <\n  \n  > 5. @{" Credits, Contacts & Greetings " LINK credits} <\n  > 6. @{" History " LINK history} <\n  \n       -=- PhoneInfo requires the LSD DOORS keyfile -=-\n\n@ENDNODE\n\n\n@NODE intro "Introduction"\n@{u}Introduction@{uu}\n\n   This little door tells your users how much their call is costing by working\nout where they live, asking their phone company then figuring what the cost\nband is and finally comming up with the cost (phew).\n\n   It works by holding all the known rates in a directory for each phone\ncompany, it then sees what time it is - peak, cheap or weekend rate, and then\nlooks in a list of local STD codes and regional STD codes for the phone company\nthey chose and if it is then it displays the appropriate cost.\n\n@{u}Requirements@{uu}\n\nMAX''s BBS v1.52 - V1.54 68000 version or MAX''s Pro (any version).\n''Date'' in ''C:''.\nA BT Phone Book, or at least a list of your local and regional STD codes.\n''LSD_Doors.key'' in ''S:''\n\nThats ya lot :).\n\n@ENDNODE\n\n\n@NODE "Disclaimer" "Disclaimer & Distribution"\n@{u}Licence@{uu}\n\nLicensed to be used on any system with the LSD_DOORS.key keyfile, this means\nyou must be registered for LSD DOORS to use this door, see the file ''Regform''\ncontained in this archive.\n\nThis software and accompaning archive must not be altered in any way.\nThis may only be freely distributed with no additional cost except a small\ncharge for the media that it is contained on, no charge must be made if \ndownloading via modem or ISDN for example.\n\nThis is not a GNU public release, but is licensed as ''private shareware''.\n@{i}\nNO WARRANTY \n@{ui}@{b}\nTHE PROGRAM IS LICENSED SHAREWARE, THERE IS NO WARRANTY FOR THE PROGRAM,\nTO THE EXTENT PERMITTED BY APPLICABLE LAW. STEVE CLACK PROVIDES THIS PROGRAM\n"AS IS" WITHOUT WARRANTY OF ANY KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING \nBUT NOT LIMITED TO, THE IMPLIED WARRANTIES OF MERCHANTABILITY AND FITNESS FOR A\nPARTICULAR PURPOSE. THE ENTIRE RISK AS TO THE QUALITY AND PERFORMANCE OF THE \nPROGRAM IS WITH YOU. SHOULD THE PROGRAM PROVE DEFECTIVE, YOU ASSUME THE COST \nOF ALL NECESSARY SERVICING, REPAIR OR CORRECTION.\n  \nIN NO EVENT UNLESS REQUIRED BY APPLICABLE LAW WILL THE COPYRIGHT HOLDER, OR ANY\nOTHER PARTY WHO MAY MODIFY AND/OR REDISTRIBUTE THE PROGRAM AS PERMITTED ABOVE, \nBE LIABLE TO YOU FOR DAMAGES, INCLUDING ANY GENERAL, SPECIAL, INCIDENTAL OR \nCONSEQUENTIAL DAMAGES ARISING OUT OF THE USE OR INABILITY TO USE THE PROGRAM \n(INCLUDING BUT NOT LIMITED TO LOSS OF DATA OR DATA BEING RENDERED INACCURATE\nOR LOSSES SUSTAINED BY YOU OR THIRD PARTIES OR A FAILURE OF THE PROGRAM TO\nOPERATE WITH ANY OTHER PROGRAMS), EVEN IF SUCH HOLDER OR OTHER PARTY HAS BEEN\nADVISED OF THE POSSIBILITY OF SUCH DAMAGES.@{ub}\n@{i}\nEND OF TERMS AND CONDITIONS\n@{ui}\nAdditional note: This program has been tested and should not damage your \nsystem.\n@ENDNODE\n\n\n@NODE install "Installation"\n@{u}Installation@{uu}\n\n   OK. This may seem a little long-winded (sorry) and may change in future\nversions, it also only applies to the phone companies currently in the archive,\nif you wish to install more then you will have to research on the phone company\n(contact me if you like and i''ll do all the work for you!).\n\nUnarchive or copy these files to ''Doors:'' so everything resides in \n''Doors:PhoneInfo/'', you should then see 6 directories and a few files in the\ndirectory, each directory represents a telecommunications company and contains\nseveral files, one for each ''location rate'' (e.g. Local, Regional) and one\nfor the rest, e.g. National.\n\nThe rate files are named ''Rates.1'', ''Rates.2'', etc and you can have as many as\nyou like, its preferable (as they are displayed in this order) to have the\nLocal first, then Regional, etc. and ''Rates.Main'' is for the rest and last.\n\n@{b}The file format for ''Rates.#'' is:@{ub}\n\nName of Rate\nPeak rate cost,Cheap rate cost,Weekend rate cost\n[List of STD codes]\n\nThe costs are in pence per minute and must be separated by a comma.\nPeak rate is weekdays 8am-6pm, Cheap rate is weekdays 6pm-8am, Weekend rate is\nSaturday midnight to Monday midnight.\nThe list of STD codes may be obtained from your BT Phone Book or some other\nlist.\nFree calls are 0p per minute :o).\n\n@{b}The file format for ''Rates.Main'' is:@{ub}\n\nConnection free (pence)\nMinimum charge (pence)\nCharges for national rate (Peak rate cost,Cheap rate cost,Weekend rate cost)\n\nThe same rules apply as the above.\n\n@{b}DON''T WORRY!!@{ub}\n\nAll the phone companies I have come across have already been set-up in this\narchive! This will be fine for most people, but heres how you set up the stuff:\n\nMake an ASCII file containing a plain list of STD codes (no blank lines) of all\nyour Local STD codes, then one of all your Regional STD codes (this should do,\nif you have any more rates then you will have to set these up yourself).\n\nThen for the supplied phone company settings do:\n\ne.g. if you called your files LocalCodes and RegionalCodes...\n\nType LocalCodes >>Doors:PhoneInfo/BT/Rates.1\nType LocalCodes >>"Doors:PhoneInfo/EastCoast Cable/Rates.1"\nType LocalCodes >>Doors:PhoneInfo/Mercury/Rates.1\nType LocalCodes >>Doors:PhoneInfo/Nynex/Rates.1\nType LocalCodes >>Doors:PhoneInfo/Telecential/Rates.1\nType LocalCodes >>Doors:PhoneInfo/VideoTron/Rates.1\nType RegionalCodes >>Doors:PhoneInfo/BT/Rates.2\nType RegionalCodes >>"Doors:PhoneInfo/EastCoast Cable/Rates.1"       (Note: Yes, Rates.1)\nType RegionalCodes >>Doors:PhoneInfo/Nynex/Rates.2\nType RegionalCodes >>Doors:PhoneInfo/Telecential/Rates.2\nType RegionalCodes >>Doors:PhoneInfo/VideoTron/Rates.2\n\nKeep the files for any future phone companies you might want to add.\n\nRight, now after all that, you can finally get around to using PhoneInfo!\n\nYou should put it in two places:\n\no  Doors:Introdoor.text\no  On your main menu.\n\n   On main menu you should run it with ! as the argument - this will go into\nmenu mode, if you don''t have ! as an argument it will just quit after it is \nrun, this is meant for the Introdoor.text -- ie. take any screen clears out of your\nIntro.text and it will look quite good!!\n\n   You may also run it as a Max''s Pro door (cos it is, just with Max''s Pro\nemulation if you don''t have it) in which case you put + in the command line\nwhen running it.\n\n   The LSD_DOORS.key must be present in s: for this proggy to work, which means\nyou must be a registered LSD DOORS user. This is a MAX''s BBS door only.\n\n@ENDNODE\n\n\n@NODE use "In use"\n@{u}In use@{uu}\n\n   Once you have @{" installed " LINK install} the prog, its time to check it out,\nlog-in as normally and it will pop up JUST BEFORE your Introdoor.text if you\ninstalled it as recommended, it will then ask you what phone company you want,\nyou''ll probably want to disable it as your logins cost nothing! :)\n\n   Each user''s settings are written to ''UserSettings.cfg'' - it writes the\ndirectory name as the users option incase the order of directories changes\n(don''t change the directory names tho).\n\n   If you come across any other phone companies, send me the details and I can\nthen include it in later versions and make files for you if you don''t know how\nto make them yourself (explained in the @{" install " LINK install} section.\n\n   Thats about it I think, if you have any questions then feel free to contact\nme, If I get around to it I will make the configuration easier, but I don''t\nthink it will be in the immediate future.\n\n   Don''t forget you will need the LSD DOORS keyfile in S: for this to work,\nread the Regform and everything for more info.\n\n@ENDNODE\n\n\n@NODE Credits "Credits, Contacts & Greetings"\n@{u}Credits@{uu}\n\n©1997 Steve Clack of Liquid Software Design.\n\nWith thanks to Niki Murkett to the AMOS Multitasking patch.\n\n@{u}Contacts@{uu}\n\nI can be reached at:\n\nTotal Eclipse BBS: +44(0)1983 522428 - 24 hours - 33.6k - I''m the sysop\nInternet E-Mail: [email removed]\nFluffyNet: 888:104/0\n\nSteve Clack\n9 Buckbury Heights\nNewport\nIsle of Wight\nPO30 2LX\nEngland\n\nSee the ''Regform'' for more information on registering LSD DOORS.\n\n@{u}Greetings@{uu}\n\nAll registered LSD DOORS users!\n\nNiki Murkett, Techn!x, Leigh Russ, Dr. X, Wendell Watanabe, Luigi, Bradman,\nChris Jeffrey, Ozz Scott, the guys on fluffy, the guys on e-mail, and everyone\nelse! Sorry if I forgot you!\n\n@ENDNODE\n\n\n@NODE History "History"\n@{u}History@{uu}\n\nV1.0 - The first version!\n \n@ENDNODE\n','\n',char(10)),NULL,'auto-added',55888,6,0,NULL,NULL,'phinfo10','scan',1780048671);
INSERT INTO door_catalog VALUES('phinfo11','PHINFO11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PHINFO11.LHA','PhoneInfo','XIM','PhoneInfo',NULL,NULL,NULL,'| o _.   o _|  (_  _ _|_ _|_     _.._ _ |_|(_||_||(_|  __)(_) | _ |_\/\/(_|| (/_ |                 | \ _  _ o _ ._',replace('                __     _            \n| o _.   o _|  (_  _ _|_ _|_     _.._ _  \n|_|(_||_||(_|  __)(_) | _ |_\/\/(_|| (/_\n     |                 | \ _  _ o _ ._ \n        [ presents ]   |_/(/__> |(_|| |  \n                                 __|    \nPhoneInfo 1.1 - Tells callers how much their \n  call is costing them while calling you.\n .. A MAXs BBS door (c)1997 Steve Clack ..\n','\n',char(10)),'PhoneInfo.Guide',replace('@DATABASE "PhoneInfo 1.1"\n@NODE main "PhoneInfo 1.1"\n@{u}PhoneInfo 1.1 Docs ©1997 by Steve Clack of Liquid Software Design@{uu}\n\n    ____                         o\n   /   / /___  ____  ____  ____    ____  ____  ____\n  /___/ /   / /   / /   / /___/ / /   / /___  /   /\n /     /   / /___/ /   / /___  / /   / /     /___/  v 1 . 1\n\n                       United Kingdom\n   \n  > 1. @{" Introduction " LINK intro} <\n  > 2. @{" Disclaimer " LINK disclaimer} <\n  > 3. @{" Installation " LINK install} <\n  \n  > 4. @{" How to use " LINK use} <\n  \n  > 5. @{" Credits, Contacts & Greetings " LINK credits} <\n  > 6. @{" History " LINK history} <\n  \n       -=- PhoneInfo requires the LSD DOORS keyfile -=-\n\n@ENDNODE\n\n\n@NODE intro "Introduction"\n@{u}Introduction@{uu}\n\n   This little door tells your users how much their call is costing by working\nout where they live, asking their phone company then figuring what the cost\nband is and finally comming up with the cost (phew).\n\n   It works by holding all the known rates in a directory for each phone\ncompany, it then sees what time it is - peak, cheap or weekend rate, and then\nlooks in a list of local STD codes and regional STD codes for the phone company\nthey chose and if it is then it displays the appropriate cost.\n\n@{u}Requirements@{uu}\n\nMAX''s BBS 1.54 68000 version or MAX''s Pro.\n''Date'' in ''C:''.\nA BT Phone Book, or at least a list of your local and regional STD codes.\n''LSD_Doors.key'' in ''S:''\n\nThats ya lot :).\n\n@ENDNODE\n\n\n@NODE "Disclaimer" "Disclaimer & Distribution"\n@{u}Licence@{uu}\n\nLicensed to be used on any system with the LSD_DOORS.key keyfile, this means\nyou must be registered for LSD DOORS to use this door, see the file ''Regform''\ncontained in this archive.\n\nThis software and accompaning archive must not be altered in any way.\nThis may only be freely distributed with no additional cost except a small\ncharge for the media that it is contained on, no charge must be made if \ndownloading via modem or ISDN for example.\n\nThis is not a GNU public release, but is licensed as ''private shareware''.\n@{i}\nNO WARRANTY \n@{ui}@{b}\nTHE PROGRAM IS LICENSED SHAREWARE, THERE IS NO WARRANTY FOR THE PROGRAM,\nTO THE EXTENT PERMITTED BY APPLICABLE LAW. STEVE CLACK PROVIDES THIS PROGRAM\n"AS IS" WITHOUT WARRANTY OF ANY KIND, EITHER EXPRESSED OR IMPLIED, INCLUDING \nBUT NOT LIMITED TO, THE IMPLIED WARRANTIES OF MERCHANTABILITY AND FITNESS FOR A\nPARTICULAR PURPOSE. THE ENTIRE RISK AS TO THE QUALITY AND PERFORMANCE OF THE \nPROGRAM IS WITH YOU. SHOULD THE PROGRAM PROVE DEFECTIVE, YOU ASSUME THE COST \nOF ALL NECESSARY SERVICING, REPAIR OR CORRECTION.\n  \nIN NO EVENT UNLESS REQUIRED BY APPLICABLE LAW WILL THE COPYRIGHT HOLDER, OR ANY\nOTHER PARTY WHO MAY MODIFY AND/OR REDISTRIBUTE THE PROGRAM AS PERMITTED ABOVE, \nBE LIABLE TO YOU FOR DAMAGES, INCLUDING ANY GENERAL, SPECIAL, INCIDENTAL OR \nCONSEQUENTIAL DAMAGES ARISING OUT OF THE USE OR INABILITY TO USE THE PROGRAM \n(INCLUDING BUT NOT LIMITED TO LOSS OF DATA OR DATA BEING RENDERED INACCURATE\nOR LOSSES SUSTAINED BY YOU OR THIRD PARTIES OR A FAILURE OF THE PROGRAM TO\nOPERATE WITH ANY OTHER PROGRAMS), EVEN IF SUCH HOLDER OR OTHER PARTY HAS BEEN\nADVISED OF THE POSSIBILITY OF SUCH DAMAGES.@{ub}\n@{i}\nEND OF TERMS AND CONDITIONS\n@{ui}\nAdditional note: This program has been tested and should not damage your \nsystem.\n@ENDNODE\n\n\n@NODE install "Installation"\n@{u}Installation@{uu}\n\n   OK. This may seem a little long-winded (sorry) and may change in future\nversions, it also only applies to the phone companies currently in the archive,\nif you wish to install more then you will have to research on the phone company\n(contact me if you like and i''ll do all the work for you!).\n\nUnarchive or copy these files to ''Doors:'' so everything resides in \n''Doors:PhoneInfo/'', you should then see 6 directories and a few files in the\ndirectory, each directory represents a telecommunications company and contains\nseveral files, one for each ''location rate'' (e.g. Local, Regional) and one\nfor the rest, e.g. National.\n\nThe rate files are named ''Rates.1'', ''Rates.2'', etc and you can have as many as\nyou like, its preferable (as they are displayed in this order) to have the\nLocal first, then Regional, etc. and ''Rates.Main'' is for the rest and last.\n\n@{b}The file format for ''Rates.#'' is:@{ub}\n\nName of Rate\nPeak rate cost,Cheap rate cost,Weekend rate cost\n[List of STD codes]\n\nThe costs are in pence per minute and must be separated by a comma.\nPeak rate is weekdays 8am-6pm, Cheap rate is weekdays 6pm-8am, Weekend rate is\nSaturday midnight to Monday midnight.\nThe list of STD codes may be obtained from your BT Phone Book or some other\nlist.\nFree calls are 0p per minute :o).\n\n@{b}The file format for ''Rates.Main'' is:@{ub}\n\nConnection free (pence)\nMinimum charge (pence)\nCharges for national rate (Peak rate cost,Cheap rate cost,Weekend rate cost)\n\nThe same rules apply as the above.\n\n@{b}DON''T WORRY!!@{ub}\n\nAll the phone companies I have come across have already been set-up in this\narchive! This will be fine for most people, but heres how you set up the stuff:\n\nMake an ASCII file containing a plain list of STD codes (no blank lines) of all\nyour Local STD codes, then one of all your Regional STD codes (this should do,\nif you have any more rates then you will have to set these up yourself).\n\nThen for the supplied phone company settings do:\n\ne.g. if you called your files LocalCodes and RegionalCodes...\n\nType LocalCodes >>Doors:PhoneInfo/BT/Rates.1\nType LocalCodes >>"Doors:PhoneInfo/EastCoast Cable/Rates.1"\nType LocalCodes >>Doors:PhoneInfo/Mercury/Rates.1\nType LocalCodes >>Doors:PhoneInfo/Nynex/Rates.1\nType LocalCodes >>Doors:PhoneInfo/Telecential/Rates.1\nType LocalCodes >>Doors:PhoneInfo/VideoTron/Rates.1\nType RegionalCodes >>Doors:PhoneInfo/BT/Rates.2\nType RegionalCodes >>"Doors:PhoneInfo/EastCoast Cable/Rates.1"       (Note: Yes, Rates.1)\nType RegionalCodes >>Doors:PhoneInfo/Nynex/Rates.2\nType RegionalCodes >>Doors:PhoneInfo/Telecential/Rates.2\nType RegionalCodes >>Doors:PhoneInfo/VideoTron/Rates.2\n\nKeep the files for any future phone companies you might want to add.\n\nRight, now after all that, you can finally get around to using PhoneInfo!\n\nYou should put it in two places:\n\no  Doors:Introdoor.text\no  On your main menu.\n\n   On main menu you should run it with ! as the argument - this will go into\nmenu mode, if you don''t have ! as an argument it will just quit after it is \nrun, this is meant for the Introdoor.text -- ie. take any screen clears out of your\nIntro.text and it will look quite good!!\n\n   You may also run it as a Max''s Pro door (cos it is, just with Max''s Pro\nemulation if you don''t have it) in which case you put + in the command line\nwhen running it.\n\n@{u}ANSI Screens@{uu}\n\nThere are three screens:\n\nIntro.text - displayed when a user hasn''t used the door before.\nFullmenu.text - displayed as the menu.\nDisabledmenu.text - for the disabled PhoneInfo menu. \n\nThese screens should not have screen clears or ANSI resets in them! But you can\nedit them to whatever you like.\n       \n   The LSD_DOORS.key must be present in s: for this proggy to work, which means\nyou must be a registered LSD DOORS user. This is a MAX''s BBS door only.\n\n@ENDNODE\n\n\n@NODE use "In use"\n@{u}In use@{uu}\n\n   Once you have @{" installed " LINK install} the prog, it''s time to check it out,\nlog-in as normally and it will pop up JUST BEFORE your Introdoor.text if you\ninstalled it as recommended, it will then ask you what phone company you want,\nyou''ll probably want to disable it as your logins cost nothing! :)\n\n   Each user''s settings are written to ''UserSettings.cfg'' - it writes the\ndirectory name as the users option incase the order of directories changes\n(don''t change the directory names tho).\n\n   If you come across any other phone companies, send me the details and I can\nthen include it in later versions and make files for you if you don''t know how\nto make them yourself (explained in the @{" install " LINK install} section.\n\n   You should have it installed on your main menu, when you access it from\nthere you will be displayed with a menu (if PhoneInfo has been disabled it will\nonly be a small menu with two options on it..) here is what the options do:\n\n@{b}(L)ist of area codes to this BBS@{ub}\n\nLists all the area codes to the BBS except national codes (Local and Regional\ncodes may vary from company to company).\n\n@{b}(P)rice of calls when calling this BBS@{ub}\n\nShows the price of calls per minute for the current phone company, the 3 most\npopular price bands (Premium, Cheap and Weekend) and the distances.\n\n@{b}(S)et your phone company@{ub}\n\nBrings up the menu you see when you first use the program, although you can\nhit enter and it will keep the company you had set before.\n\n@{b}(C)ost calculator (work out how much a call cost you)@{ub}\n\nLets callers work out how much a call cost them, they are asked a few questions\nand then it tells them how much it cost.\n\n@{b}(Q)uit PhoneInfo@{ub}\n\nTakes over the world.\n\n   Thats about it I think, if you have any questions then feel free to contact\nme, If I get around to it I will make the configuration easier, but I don''t\nthink it will be in the immediate future.\n\n   Don''t forget you will need the LSD DOORS keyfile in S: for this to work,\nread the Regform and everything for more info.\n\n@ENDNODE\n\n\n@NODE Credits "Credits, Contacts & Greetings"\n@{u}Credits@{uu}\n\n©1997 Steve Clack of Liquid Software Design.\n\nWith thanks to Niki Murkett to the AMOS Multitasking patch.\n\n@{u}Contacts@{uu}\n\nI can be reached at:\n\nTotal Eclipse BBS: +44(0)1983 522428 - 24 hours - 33.6k - I''m the sysop\nInternet E-Mail: [email removed]\nFluffyNet: 888:104/0\n\nSteve Clack\n9 Buckbury Heights\nNewport\nIsle of Wight\nPO30 2LX\nEngland\n\nSee the ''Regform'' for more information on registering LSD DOORS.\n\n@{u}Greetings@{uu}\n\nAll registered LSD DOORS users!\n\nNiki Murkett, Techn!x, Leigh Russ, Dr. X, Wendell Watanabe, Luigi, Bradman,\nChris Jeffrey, Ozz Scott, Chris Hearn, the guys on fluffy, the guys on e-mail, \nand everyone else! Sorry if I forgot you!\n\n@ENDNODE\n\n\n@NODE History "History"\n@{u}History@{uu}\n\nV1.0 - The first version!\n\nV1.1 - If the area code can''t be evaluated but PhoneInfo has been disabled, it\n       won''t ask if you want to change it.\n       \n       Added ANSI screens so you can configure the text, "Intro.text" for the\n       Introductory text, "Fullmenu.text" for the full PhoneInfo menu, and\n       "Disabledmenu.text" for the disabled PhoneInfo menu (these screens\n       should not have screen clears or ANSI resets in them!).\n       \n       Changed some of the menu item names.\n       \n       Added a Call Cost Calculator, which allows users to figure how much a\n       call costed them on their phone company. Asks for the rate, distance\n       and the length of the call.\n       \n       Updated the National Rate for BT peak rate (cut by 10%) - I don''t about\n       other companies so please send me info if rates change.\n       \n       If it thinks the area code doesn''t conform at all (doesn''t begin with\n       01) it won''t suggest that you forgot a space or dash.\n\n       Forgot to include the Regform with the last release.\n             \n@ENDNODE\n','\n',char(10)),NULL,'auto-added',59919,6,0,NULL,NULL,'phinfo11','scan',1780048671);
INSERT INTO door_catalog VALUES('phn_an11','PHN-AN11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PHN-AN11.LHA','AMIGAGUIDE','XIM','AMIGAGUIDE',NULL,'PICARD/PHN!','PHN',':/\________________________________________: :\___  /  /  /__ ____ _\ ._ __  / ___/___ _/ :_/ __/     /    /  / /// /    /__  / / / /:',replace('........................................LNF.\n:/\________________________________________:\n:\___  /  /  /__ ____ _\ ._ __  / ___/___ _/\n:_/ __/     /    /  / /// /    /__  / / / /:\n:\  //__/__/_/__/__/__/__/_/__/____/_/_/_/ :\n: \/  )=( pReSeNtS aNøThEr fInE tØøl )=(   :\n:..........................................:\n[ PHN-ANSI V1.1 - /X-TOOL - BY PICARD/PHN! ]\n:··········································:\n:   Works with /X3.xx - /X4.xx or higher   :\n: Written in ARexx - Install it / Love it! :\n············································\n','\n',char(10)),'PHN-ANSI.GUIDE',replace('@Database PHN-ANSI V1.1 \n\n(C) & (W) bY pICARD of sHT^pHN oN 24th fEBRUARY 1995\n\n@Remark $VER: (February 24 1995, 20:58:34)\n@Remark AmigaGuide Database for PHN-ANSI V1.1\n\n@node MAIN "GUIDE MAIN"\n          __ _.\n     _______  |\n    |       \_|___ _______ _______ __________ ____ _______ ___________\n    |   |   _/    \_      \_      \_        /     \_      \_          \_\n    |   |___| |   _/  |   _/  |   _/|   |  /  |   _/  |____/  |   |   _/\n    |   | |   |   |       |   |   |_|   l_/       |___    |   |   |   |\n    |   | |   |   |   |   |   |   | |   | |   |   |   |   |   |   |   |\n    |   | l___|___l___|   l___|___| l___| l___|   l___    l___|___|___|\n    l___|  ¹995       \___|                   \___|   \___|By LNF!     \n                                  PRESENTS\n\n                          < PHN-ANSI VERSION 1.1 >\n\n                           CODED BY PICARD/PHN^SHT\n                   ---------------------------------------\n\n                         @{" <1> About thiz Tool     " Link Part01}\n                         @{" <2> System Requirements " Link Part02}\n                         @{" <3> Installation        " Link Part03}\n                         @{" <4> Configuration       " Link Part04}\n                         @{" <5> Lengths             " Link Part09}\n                         @{" <5> History             " Link Part05}\n                         @{" <6> Future Projects     " Link Part06}\n                         @{" <7> Some Greetz         " Link Part07}\n                         @{" <8> Contact Me          " Link Part08}\n\n                   ---------------------------------------\n@endnode\n@node Part01 "About thiz Tool"\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n This Tool, currently Version 1.1, is written in ARexx and placed as\n FreeWare. It is one of my first Projects in programming Tools for\n AmiExpress.\n \n I''m still learning how to code in "C". ARexx is nice, but not a real\n language for programmers! (I hope, that I learn it fast hehe)\n\n I know, there is an another Tool like thiz out there (Hi Satan+God),\n but also thiz time, I tried to code my own one, and I think, it is\n really nice.....\n\n Install it / Use it / Love it!\n\n @{" GO BACK!  " Link MAIN}\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@endnode\n@node Part02 "System Requirements"\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n  To use thiz Tool you need :\n\n  · COMMODORE AMIGA (TM) OS 2.0 OR HIGHER\n  · AN AMIGA MODEL 500,600,1000,1200,2000,2500,3000,3000T,4000,4000T\n  · A WELL INSTALLED VERSION OF AMI EXPRESS /X3.xx ; /X4.xx OR HIGHER\n\n @{" GO BACK! " Link MAIN}\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@endnode\n@node Part03 "Installation"\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n  Installation under /X3.xx ÷ /X4.xx (or higher) :\n\n    · Copy all Files of this archive to the correct bbs-drawers. \n\n  Installation under /X1.xx ÷ /X2.xx ÷ S!X :\n\n    · Sorry dudes! But I don''t know how to install /X-Doors in Ami Express\n      2.xx / 1.xx or S!X, but I think, if you run a bbs with this versions\n      you know how to install this door ;)\n\n @{" GO BACK! " Link MAIN}\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@endnode\n@node Part04 "Config PHN-ANSI"\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n You find the Config-File of "PHN-ANSI" after the complete Installation\n in following Dir :\n\n BBS:DOORS/PHN/ANSI/ANSI.CFG\n\n The Config-File is very simple..... You can edit the lines with your\n favourite Text-Editor and create Lines like this :\n\n  tHIS bBS-sYSTEM iS aNSI oNLY !!!\n  aNSI/rIP/aSCII (A/R/N ?¿?) YEAH, ANSI !!!\n  wHAT aBOUT aNSI ?¿? - yES! yES! yES!\n  nO oTHER mODES aVAILABLE! - aNSI rULEZ...\n  a bIG hELLO tO aMIGA - tHE aNSI-mASTER!\n\n                                          ^-- Important for the Style of\n                                              my Tool, do not use more\n                                              characters as is!\n\n @{" GO BACK!  " Link MAIN}\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@endnode\n@node Part05 "History"\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n V1.0ß  -->  Internal Release to test it on my own bbs.\n\n V1.0   -->  Never Released!\n\n V1.1   -->  First Released Public Version.\n\n @{" GO BACK!  " Link MAIN}\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@endnode\n@node Part06 "Future Projects"\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n · A new Version of my PHN-ANSI completly rewritten in "C" with a Save-\n   Option for each user. So the user choose one time his favorite Display-\n   Mode (Ansi/RIP/ASCII etc), PHN-ANSI saves this, so the user needn''t to\n   choose it again on further logins.  \n\n · Also a new Version of my PHN-PAGER, full rewritten in "C" with Chat-\n   Requester (Reqtools?) for WB-Screen and/or a Replay-Option for Samples\n   or NT/PT-Modules.\n\n · A Security Checker against Hacking AmiExpress.\n\n @{" GO BACK!  " Link MAIN}\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@endnode\n@node Part07 "Some Greetz"\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n C/\NN¡B/\L^NJY    HOPE TO SEE YA ON NEXT PADDY ¿?\n [SATAN+GOD]^NJY   STILL WORKING ON A NEW BBS?\n MOSH^PSI^PHN      28K8 RULEZ!\n BLADE^PSI         SOMETHING NEW ABOUT BB ¿?\n GRANDMASTER^PGY   THX FOR NUMBAS....\n JOE PUNK (INDEP)  HOPE TO SEE YA ON MY BBS SOON!\n JSINCL.^PSI       THX FOR REGISTERED TIME-STAMP\n\n ........ AND TO ALL SHT^PHN MEMBERS OUT THERE!\n\n @{" GO BACK!  " Link MAIN}\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@endnode\n@node Part08 "Contact Me"\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n You can reach me as <PICARD> on following boards.......\n\n DEVILS POINT II  - TRSI GHQ\n DRIVE BY SHOOTIN - PSI GHQ\n MINDLOSS         - N-JOY GHQ\n TOONTOWN         - OSIRIS GHQ\n DANZIG           - PHN GHQ\n\n or directly on my own bbs.... Start at 01.04.95!\n\n TRESPASS         - SHT EHQ / PHN GHQ\n\n @{" GO BACK!  " Link MAIN}\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@endnode\n@node Part09 "Lengths"\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n THIS MUST BE IN THE ORIGINAL-ARCHIVE :\n\n\n > PHN-ANSI\n\n PHN-ANSI.GUIDE                          LENGHT :  7554 BYTES\n \n > PHN-ANSI/C\n\n AMIGAGUIDE (POWERPACKER (tm) VERSION)   LENGHT :  7952 BYTES\n\n > PHN-ANSI/BBS/COMMANDS/SYSCMD/\n\n ANSI.INFO                               LENGHT :  1060 BYTES\n\n > PHN-ANSI/BBS/DOORS/PHN/ANSI/\n\n PHN-ANSI.REXX                           LENGHT :  2352 BYTES\n ANSI.CFG                                LENGHT :   194 BYTES\n\n > PHN-ANSI/LIBS\n\n REXXUTIL.LIBRARY                        LENGHT : 10676 BYTES\n POWERPACKER.LIBRARY                     LENGHT :  6128 BYTES\n\n ---------------\n\n IF YOU WANT TO BE SURE THAT ALL WORKS 100%, YOU CAN LEECH THE ORIGINAL\n 100% PERCENT VERSION ON FOLLOWING BOARDS IN THE LATEST VERSIONS....\n\n MINDLOSS         - N-JOY GHQ\n DANZIG           - PHN GHQ\n TRESPASS         - SHT EHQ / PHN GHQ\n\n ---------------\n\n TRY TO FIND US, ASK MEMBERS OF PHN / SHT & N-JOY!\n \n @{" GO BACK!  " Link MAIN}\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@endnode\n','\n',char(10)),NULL,'auto-added',23610,3,0,NULL,NULL,'phn_an11','scan',1780048671);
INSERT INTO door_catalog VALUES('phn_j11','PHN-J11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PHN-J11.LHA','PHN-Join','XIM','PHN-Join',NULL,'tHE','PHN','(    \               ____ |  ·  )__ ___________)  (_____ ________  _ | ___/ l \) . ()    (_  _) . ((  __  ) \/(',replace(' ____\n(    \               ____\n|  ·  )__ ___________)  (_____ ________  _\n| ___/ l \) . ()    (_  _) . ((  __  ) \/(\n|  (     /     \  |  |  /     /\_  \/     \\n|   \_l_/   l___)_l__l_/   l_(_____/   \/\_)\nl____)-(_____)-bRiNgS-(_____)-ppx-(_____)---\n \n        ... PHN-Join V1.1 for /X ...\n       ... dONe bY tHE aLIEN/pHN! ...\n','\n',char(10)),'PHN-Join.guide',replace('@database PHN-Join.guide\n@Remark $VER: PHN-Join Guide V1.1 (19.9.95) © 1995 tHE aLIEN / pHANTASM\n\n@node MAIN "PHN-Join Guide copyright © 1995 tHE aLIEN / pHANTASM"\n           __ _.\n      _______  |\n     |       \_|___ _______ _______ __________ ____ _______ ___________\n     |   |   _/    \_      \_      \_        /     \_      \_          \_\n     |   |___| |   _/  |   _/  !   _/:   !  /  |   _/  |____/  |   |   _/\n     |   | |   |   |       |   !   !_|   l_/       |___    |   !   !   |\n     |   | |   |   |   |   !   !   ! |   | |   |   !   !   !   |   |   |\n     |   | l___|___l___|   l___!___! l___| l___|   l___    l___!___!___|\n     l___|             \___|                   \___|   \___|By LNF!\n\n                             ... bRINGz yA ...\n\n                   PHN-Join V1.1 for /X by tHE aLIEN/pHN\n\n                             @{"[ iNTRODUCTIOn ]" link INTRODUCTION}\n                             @{"[ rEQUIREMENTS ]" link REQUIREMENTS}\n                             @{"[ iNSTALLATIOn ]" link INSTALLATION}\n                             @{"[   hISTORy!   ]" link HISTORY}\n                             @{"[  gREETINGs!  ]" link GREETINGS}\n                             @{"[   cALL NOw   ]" link CALLNOW}\n\n                           this tool is FREEWARE\n                    copyright © 1995 tHE aLIEN/pHANTASM\n@endnode\n\n@node INTRODUCTION "Introduction..."\n                          This is PHN-Join V1.1 ...\n                     ... a new Join-Door for AmiExpress!\n\n         Features:\n         - a greate XIM-Door without backdoor\n         - join a conference by num or NAME!!!\n         - select your conf via listview-like selection\n         - abort conf-selection with q,a,x \n         - supports Background-ANSI\n\nWhen you are in the listview-like selection then you can abort the selection\nwith the keys: q, a or x.\nYou can select the new conference with the keys: Return, Enter, Space.\n@endnode\n\n@node REQUIREMENTS "Requirements..."\n                           Everyone can run it!!!!\n\n         - you only need an AMIGA\n         - and the great AmiExpress V4.x\n@endnode\n\n@node INSTALLATION "Installation..."\nThe installation is very simple...\n\n- copy the directory PHN with all the files to DOORS:\n\n- copy the directory COMMANDS with all the files to BBS:\n\n- copy an ANSI-Text called PHN-Join.txt to DOORS:PHN/Join/ (optional)\n\n- change the tooltype JOIN_STARTLINE in the file BBS:Commands/BBSCmd/J.info (if needed) (optional)\n\nready...\n@endnode\n\n@node HISTORY "History..."\nHistory:\n\n  V1.0 (16.9.1995):\n    - first official release\n\n  V1.1 (19.9.1995):\n    - now supports Background-ANSI\n    - optimized\n@endnode\n\n@node GREETINGS "Greetings..."\n                          ... GReeTz fLYIng To ...\n\n      spEZIaL greETz 2:\n\n      saXOn , InTENsiTy , DoC waTSoN , GoroNIt , REvOlVer\n\n      anD tO aLl PhANTasM MeMBerS...\n@endnode\n\n@node CALLNOW "Call now..."\n           _______  ___________________    __________________  ________\n          /ø  °  ¬\/°   _ ¬\_________ ¬\  /°    \________   ¬\/ø    ° ¬\\n         / !  \___/ø  _/ \  \|ø ° |  \  \/ø   |___/ø  _|/    / !   \___/\n        /  :  /° / !  \  /  °\!   |  /  °\!    _)_\!  \_    °\_:_     ¬\\n        \    /   \ :   \/    /:   |_/    /:   | ° /:   |\    /   \    °/\n         \____    \____     /|_____     /\____    \____| \   \     ___/\n              \___/    \___/       \   /      \___/       \__/\   /\n                                    \_/                        \_/\n                   _______  _________________________..__  .___.\n                  /ø  °  ¬\/   __ °\________  ¬\ø   ¬||ø \ |  ¬|\n                 / !  \___/ø  _|/   \|ø °_|/   /!    ||!  \|   |\n                /  :  /° / !  \_     \!  \__  °\:    ||:       |\n                \    /   \ :  °|     /:   |/    \    ||.  °:   |\n                 \____    \____|    /|_____     /    ||    |   |\n                      \___/    |___/       \   /|____||____|   |\n                                            \_/            |___|\n\n                                 PHANTASM GHQ\n\n         24 hØµ®s øN£¡nE                               $ysøP: tHE aLIEN\n                               +49-(0)4131-63965\n       2.400 - 28.800 BaµÐ                                 1.6 G¡gs\n@endnode\n','\n',char(10)),NULL,'auto-added',9595,1,0,NULL,NULL,'phn_j11','scan',1780048671);
INSERT INTO door_catalog VALUES('phn_join','PHN-JOIN.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PHN-JOIN.LHA','PHN-Join','XIM','LE-win5-96.exe','1.1',NULL,'PHN',NULL,replace('... PHN-Join V1.1 for /X ...\n','\n',char(10)),'PHN-Join.guide',replace('@database PHN-Join.guide\n@Remark $VER: PHN-Join Guide V1.1 (19.9.95) © 1995 tHE aLIEN / pHANTASM\n\n@node MAIN "PHN-Join Guide copyright © 1995 tHE aLIEN / pHANTASM"\n           __ _.\n      _______  |\n     |       \_|___ _______ _______ __________ ____ _______ ___________\n     |   |   _/    \_      \_      \_        /     \_      \_          \_\n     |   |___| |   _/  |   _/  !   _/:   !  /  |   _/  |____/  |   |   _/\n     |   | |   |   |       |   !   !_|   l_/       |___    |   !   !   |\n     |   | |   |   |   |   !   !   ! |   | |   |   !   !   !   |   |   |\n     |   | l___|___l___|   l___!___! l___| l___|   l___    l___!___!___|\n     l___|             \___|                   \___|   \___|By LNF!\n\n                             ... bRINGz yA ...\n\n                   PHN-Join V1.1 for /X by tHE aLIEN/pHN\n\n                             @{"[ iNTRODUCTIOn ]" link INTRODUCTION}\n                             @{"[ rEQUIREMENTS ]" link REQUIREMENTS}\n                             @{"[ iNSTALLATIOn ]" link INSTALLATION}\n                             @{"[   hISTORy!   ]" link HISTORY}\n                             @{"[  gREETINGs!  ]" link GREETINGS}\n                             @{"[   cALL NOw   ]" link CALLNOW}\n\n                           this tool is FREEWARE\n                    copyright © 1995 tHE aLIEN/pHANTASM\n@endnode\n\n@node INTRODUCTION "Introduction..."\n                          This is PHN-Join V1.1 ...\n                     ... a new Join-Door for AmiExpress!\n\n         Features:\n         - a greate XIM-Door without backdoor\n         - join a conference by num or NAME!!!\n         - select your conf via listview-like selection\n         - abort conf-selection with q,a,x \n         - supports Background-ANSI\n\nWhen you are in the listview-like selection then you can abort the selection\nwith the keys: q, a or x.\nYou can select the new conference with the keys: Return, Enter, Space.\n@endnode\n\n@node REQUIREMENTS "Requirements..."\n                           Everyone can run it!!!!\n\n         - you only need an AMIGA\n         - and the great AmiExpress V4.x\n@endnode\n\n@node INSTALLATION "Installation..."\nThe installation is very simple...\n\n- copy the directory PHN with all the files to DOORS:\n\n- copy the directory COMMANDS with all the files to BBS:\n\n- copy an ANSI-Text called PHN-Join.txt to DOORS:PHN/Join/ (optional)\n\n- change the tooltype JOIN_STARTLINE in the file BBS:Commands/BBSCmd/J.info (if needed) (optional)\n\nready...\n@endnode\n\n@node HISTORY "History..."\nHistory:\n\n  V1.0 (16.9.1995):\n    - first official release\n\n  V1.1 (19.9.1995):\n    - now supports Background-ANSI\n    - optimized\n@endnode\n\n@node GREETINGS "Greetings..."\n                          ... GReeTz fLYIng To ...\n\n      spEZIaL greETz 2:\n\n      saXOn , InTENsiTy , DoC waTSoN , GoroNIt , REvOlVer\n\n      anD tO aLl PhANTasM MeMBerS...\n@endnode\n\n@node CALLNOW "Call now..."\n           _______  ___________________    __________________  ________\n          /ø  °  ¬\/°   _ ¬\_________ ¬\  /°    \________   ¬\/ø    ° ¬\\n         / !  \___/ø  _/ \  \|ø ° |  \  \/ø   |___/ø  _|/    / !   \___/\n        /  :  /° / !  \  /  °\!   |  /  °\!    _)_\!  \_    °\_:_     ¬\\n        \    /   \ :   \/    /:   |_/    /:   | ° /:   |\    /   \    °/\n         \____    \____     /|_____     /\____    \____| \   \     ___/\n              \___/    \___/       \   /      \___/       \__/\   /\n                                    \_/                        \_/\n                   _______  _________________________..__  .___.\n                  /ø  °  ¬\/   __ °\________  ¬\ø   ¬||ø \ |  ¬|\n                 / !  \___/ø  _|/   \|ø °_|/   /!    ||!  \|   |\n                /  :  /° / !  \_     \!  \__  °\:    ||:       |\n                \    /   \ :  °|     /:   |/    \    ||.  °:   |\n                 \____    \____|    /|_____     /    ||    |   |\n                      \___/    |___/       \   /|____||____|   |\n                                            \_/            |___|\n\n                                 PHANTASM GHQ\n\n         24 hØµ®s øN£¡nE                               $ysøP: tHE aLIEN\n                               +49-(0)4131-63965\n       2.400 - 28.800 BaµÐ                                 1.6 G¡gs\n@endnode\n','\n',char(10)),NULL,'auto-added',15296,5,0,NULL,NULL,'phn_join','scan',1780048671);
INSERT INTO door_catalog VALUES('phn_mp51','PHN-MP51.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PHN-MP51.LHA','display','XIM','display',NULL,NULL,'PHN','/ __  /\ /  /  /\ / /\/ /\ /   / /\ /  ___/ //     / // /\/ / //     / /___ /__/\__\//__/__/ //_____/ //__/__/ //__/\',replace('    ______   ______   __  __   ______       \n   / __  /\ /  /  /\ / /\/ /\ /   / /\      \n  /  ___/ //     / // /\/ / //     / /___   \n /__/\__\//__/__/ //_____/ //__/__/ //__/\  \n \__\/    \__\__\/ \_____\/ \__\__\/ \__\/  \n--------------- PreSeNTs ------------------ \n MAJORPAGE V5.1 - /X Pager Door for /X 3.x\n','\n',char(10)),'MajorPage.guide',replace('@database © Major Death/P.H.U.N. ''95 / SABOTAGE PC / CYBRIX Pager V5.1\n@Author Major Death / Spiders Web +32 2 270 34 20\n@Index MAIN\n\nCopyright © Major Death / Spiders Web +32 2 270 34 20\n\n@Remark $VER: (December 20, 1994, 21:00:)\n@Remark AmigaGuide database for the Pager Documentation\n\n@node MAIN "MajorPage Documentation © Major Death / Spiders Web\n\n\n                         @{"      Introduction      " Link Cap01}\n                         @{"      Requirements      " Link Cap02}\n                         @{"      Installation      " Link Cap03}\n                         @{"      Ken & Ryu Pub ;)  " rxs "address command ''display ken&ryu''"}\n                         @{"       Greetings        " Link Cap05}\n                         @{"   How to Contact me    " Link Cap06}\n\n\n         ---------------------------------------------------------\n                    Complete Docs for MajorPage V5.1\n         ---------------------------------------------------------\n             The Documentation has been written by Major Death\n\n@endnode\n@node Cap01 "Introduction"\n  =======================================================================\n  Well nothing much to tell you on what it does :) . It is another pager\n  door, an update of the earlier versions with some bug/enhancements. \n  I altered a lot of things due to the fact that /X Colors SUCK for PC\n  callers, since /X only uses 8 colors instead of the 16 used by PC. So\n  /X users have to use the 1m (instead of the 0m) to have some NICE \n  looking screens for PC-callers. And then Amiga-Callers are screwed\n  since they get BOLD lettertypes with the 1m all the time..so i fixed\n  the pager to be nice-looking for both users on your bbs (if you have a\n  PC conference at all that is :)\n \n  To avoid problems, Major Death is the latest handle of Ex-KEN & RYU, \n  and EX-Chaplin & Stony..since it is back to me,myself and I :) soo if\n  all you sysops out there still have a chaplin & stony account, please\n  change it to Major Death..thx in advance...also Shotokan Palace, UiC,\n  has now been called forever : SPIDERS WEB, PHUN WHQ (amiga) ofcoz :)\n  SaBoTaGe Bhq (PC), and CyBriX Bhq (pC)..number to be found elsewhere in\n  this doc. \n  Have fun..\n  =======================================================================\n@endnode\n@node Cap02 "Requirements"\n  =======================================================================\n  To install MajorPage you must have the following things:\n\n    Programm     Location           Description\n    ----------   --------           -----------\n    MajorPage    Whereever          Main program\n    .always      SYS:S dir	    data file\n    .never       SYS:S dir          data file\n    .goodbye     SYS:S dir          data file\n\n  - an  Amiga Model (500/600/1000/1200/2000/2500/3000/4000/CDTV/CD³²)\n  - the installed Version of OS\2, OS\3 or higher\n    (Soft- or Hardware Version)\n  - the installed .INFO Files in the directories.\n  - AmiExpress v3.xx or higher. (might work on 2.x ?)\n\n  =======================================================================\n@endnode\n@node Cap03 "How to install MajorPage"\n  =======================================================================\n  To install MajorPage you must have all Requirements which are\n  mentioned below. You need the following things.\n\n  --------------------------\n    Doors:MajorPage (dir) (Well in fact wherever you wanna put it is fine)\n      ^^^ MajorPage\n    BBS:Commands/BBSCmd (dir)\n      ^^^ O.info\n  --------------------------\n\n  Decruch the PHN-MP51 Archive. Go to your ''Doors:'' Directory\n  and make a Directory called ''MajorPage/''. Copy ''MajorPage.x into\n  the Directory. Go to your ''BBS:Commands/BBSCmd/'' Directory.\n  Copy ''o.info'' into it.\n  Now the .never and .always files are located in the S dir, and are used\n  for the purposes you can already guess. Put handles in them as they are\n  used on your bbs (with the /X.32) in it. Never means even if the page \n  status (F7) is on, he will get the SYSOP NOT HERE message, with always\n  it is just the otherway around, and on request the .goodbye is very\n  simple, anybody inhere who pages gets an auto-logoff ... (where did he\n  want that for ?) ..:-) ..anywayz, just copy into your S dir.\n  That''s it.\n  =======================================================================\n@endnode\n@node Cap05 "Greetings go to..."\n  =======================================================================\n\n                        Greetingz to:\n\n    \n    Bytemaster .........For programming /X!..Btw: NeTmail Remember? :((\n    \n    And everybody worldwide, who thinks he/she should be in it. Give\n    me a buzz and I''ll put you in next time. (Soon coz more modules\n    coming up very soon) If you have a module that you want for your\n    bbs, feel free to call, made within 7 dayz, free of charge !\n                                        ^\n					| due to TO popular demand 4 dayz\n					       has become impossible! :)\n\n                       GreeTings OfCoZ To :\n\n                  >>> All MeMBeRs oF PHUN ''95 <<<\n\n			 and also to :\n\n    BLACK BEARD, WILKINS, BUTTERBALL, SAMSON, HERO, ELVIN NOX, LOLO,\n    JANNO, ARTUR, MR.SOLO, STERNONE, TOXIC, SINTAX, PLANET MASTER, \n    SNOW, ASCENDER, AGNUS, CALYPSO, CASTOR, COSMIC, GHOSTRIDER,\n    ROFOE, SCAMPY, TRAVELLER, TRONIX, WARHAWK, XENTEC, SNAKE/NAZGUL,\n    TYCOON, KILLRAVEN, MARC, GORDON :), and all dudes i forgot ...\n\n\n    TO AVOID PROBS : TO ALL SYSOPS WORLDWIDE WHERE THE ACCOUNT \n \n			CHAPLIN & STONY \n\n		     IS STILL ACTIVE, PLEASE CHANGE IT TO \n \n			MAJOR DEATH\n \n		     THX!\n\n  =======================================================================\n@endnode\n@node Cap06 "How to contact us..."\n  =======================================================================\n\n \n \n \n      ::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::\n     :::______:::::::::______:::::::::__::__:::::::::______::::::::\n    :::/ __  /\:::::::/  /  /\:::::::/ /\/ /\:::::::/   / /\::::::::\n   :::/  ___/ /___:::/     / /___:::/ /\/ / /___:::/     / /___::::::\n  :::/__/\__\//__/\:/__/__/ //__/\:/_____/ //__/\:/__/__/ //__/\::::::\n ::::\__\/::::\__\/:\__\__\/:\__\/:\_____\/:\__\/:\__\__\/:\__\/:::::::\n::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::\n                    CALL OUR P.H.U.N. BOARDS :                  28.8oo\n                    ~~~~~~~~~~~~~~~~~~~~~~~~~~\n \n    SPIDERS WEB      4 NODES    + 32 2270-34-20 (RING)    P.H.U.N. WHQ\n    WORLD OF ELITE   3 NODES    + 31 7752-12-93           P.H.U.N. EHQ\n    FUCK ST. EUROPE  1 NODE     + 35 PRI-VA-TE!           P.H.U.N. FHQ\n \n\n\n@endnode\n','\n',char(10)),NULL,'auto-added',42540,2,0,NULL,NULL,'lgc_op41','scan',1780048671);
INSERT INTO door_catalog VALUES('phn_op46','PHN-OP46.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PHN-OP46.LHA',NULL,'XIM','______   ______   __  __   ______',NULL,NULL,'PHN','/ __  /\ /  /  /\ / /\/ /\ /   / /\ /  ___/ //     / // /\/ / //     / /___ /__/\__\//__/__/ //_____/ //__/__/ //__/\',replace('    ______   ______   __  __   ______       \n   / __  /\ /  /  /\ / /\/ /\ /   / /\      \n  /  ___/ //     / // /\/ / //     / /___   \n /__/\__\//__/__/ //_____/ //__/__/ //__/\  \n \__\/    \__\__\/ \_____\/ \__\__\/ \__\/  \n--------------- PreSeNTs ------------------ \n  /X 2.x - /X 3.x  © OpeRaToR PaGe V4.6 ©   \n -LasT P.H.U.N. Release, Next MsT/X-DeSiGN  \nDrEaM_PhASE wAS fIRST wITH tHIS fILE!!','\n',char(10)),'Operator.guide',replace('@database Operator Page V4.6\n@Author CHAPLIN / P.H.U.N.\n@Index MAIN\n\nCopyright © ChaPLiN / U.I.C. +32 2 270 04 07\n\n@Remark $VER: (January 16 1994, 03:00:00)\n@Remark AmigaGuide database for the Operator Page Documentation\n\n@node MAIN "Operator Page Documentation © ChaPLiN / P.H.U.N. / U.I.C.\n\n  ___________________________________________________________________________\n |\                                                                         /|\n | \_______________________________________________________________________/ |\n |  |     _____________    _____   _____    ____   ____    _____    _____ |  |\n |  |    /   ______   /\  /    /\ /    /\  /   /\ /   /\  /    /\  /    /\|  |\n |  |   /   /\    /  /  \/    /  /    /  \/   /  /   /  \/     \ \/    /  \  |\n |  |  /   /__\__/  /   /    /__/    /   /   /  /   /   /       \/    /   /  |\n |  | /    ________/   /            /   /   /  /   /   /             /   /|  |\n |  |/    /\       \  /    ___     /   /   /__/   /   /    /\       /   / |  |\n |  /    /  \_______\/    /\ /    /   /          /   /    /  \     /   /  |  |\n | /____/   /       /____/  /____/   /__________/   /____/   /____/   /   |  |\n | \    \  /        \    \  \    \  /\          \  /\    \  /\    \  /    |  |\n |  \____\/          \____\/ \____\/  \__________\/  \____\/  \____\/     |  |\n |  |_____________________________________________________________________|  |\n | /                                                                       \ |\n |/________________________________________________________________ChaPLiN__\|\n\n                      W o R l D   H e a D Q u a R T e r S\n\n 		     MySTiC /X DeSiGn BeLGiaN HeaDQuaRTeRS\n\n\n                         @{" Introduction & History " Link Cap01}\n                         @{"      Requirements      " Link Cap02}\n                         @{"       Greetings        " Link Cap05}\n                         @{"   How to Contact Us    " Link Cap06}\n\n\n         ---------------------------------------------------------\n                  Complete Docs for OpeRaTor Pager V4.6\n         ---------------------------------------------------------\n           The Documentation has been written by ChaPLiN/P.H.U.N.\n\n@endnode\n@node Cap01 "Introduction"\n  =======================================================================\n  V 4.1\n  ~~~~~\n  Again some people requested that i made the opposite of the Boring ba..\n  that are int the S:Operator.cfg. So know you can put the ones that can\n  ALWAYS page you, no mather how the CHATFLAG is (ON or OFF) they will \n  override it, and well all is written in your callerslog...just check it\n  out. I forgot to mention that in the docs that there are 5 remarks in\n  you callerslog. \n \n		1. No Reason, No Chat + Message\n                2. Chatflag On        + Message\n                3. Chatflag Off       + Message\n                4. Override Chatflag  + message  >operator.pw\n                5. Boring Bas...      + Message  >operator.cfg\n\n  V 4.2\n  ~~~~~\n  Little Beta release for the Beta testers..seems fine...but not much\n  different, except then for a CTRL-C aborts. :) Forgot about that ..oups\n\n  V 4.3\n  ~~~~~\n  Hmm here a lot has changed, some bugs that the pager kept paging untill\n  the User press CTRL-C, fixed now. Also the Operator.pw has been changed\n  into Operator.Always and the Operator.cfg into Operator.Never. Sorry\n  about this but otherwise it''s getting confusing. :)\n  Don''t see why i still should make Operator.pw since this is of no use\n  with the .Never and .Always :)\n  Also added ACP SUPPORT, this will show you when the module is activated\n  in the ACP. I suggest EVERYBODY does this coz then it is really nice \n  when your windows are iconified. Now you can see what the user does, \n  besides all the time "MODULE" into acp..\n\n  well that''s it for now. If any more ideas, requests, whatever..give me\n  a buzz..also if you want personalized doors for you bbs only. :)\n\n 					KeN/LoGiC\n  V 4.4\n  ~~~~~\n\n  Well for those who know already skip some lines now, for those who are\n  not aware of the change, read the PHN.KEN&RYU file on all bbs''s spread.\n  I won''t be typing the same thing twice :-)\n\n  What is new in 4.4. Simple, there was a request from "CENSORED" who \n  asked me if i could include a "REAL LAME DUDE SOLUTION". Well first no-\n  body is lame (so that''s clear now ain''t it!) and secondly, if somebody\n  wants something he''ll get''s it. That''s what PHUN is all about no ?\n  So 4.4 was born. There is a new file, called S:operator.goodbye\n  This ones scans for Handles that will automagically, whether the chat\n  is ON or OFF, be logged out. (Who ever wants a thing like this ?) I DO!\n  YeK YeK...well anyway, that''s it for now folks, as I don''t have a new\n  suggestion received for further improvements, I think this will be\n  enough... Of course, you are always welcome to get your Private Pager\n  and to exchange ideas about /X Tools of any kind.\n\n					ChaPLiN/P.H.U.N.\n\n  V 4.5\n  ~~~~~\n\n  Oups, Big Bug in there and I didn''t notice that since /X versions are\n  different ...strange...well fixed now.\n  Thx to SnoW/LoGiC for pointing that out!\n\n					ChaPLiN/P.H.U.N.\n\n\n  V 4.6\n  ~~~~~\n  Another problem that was reported is that the callerslog missed a \n  returnstring so Amilog couldn''t find the logoff time. Didn''t look good.\n  Thanx to Scorpio for pointing that out to me.\n  \n  Oki now just for some legal mumbo jumbo. All my tools released and pre-\n  released, are free of charge and can always be downloaded FREE at the\n  P.H.U.N. Whq...just give it a buzz...and one last thing, yes this is \n  the last P.H.U.N /X Tool released, as future Tools will have the MsT\n  /X-DeSiGN Label on them. So next update will be /Y\ystic/X-DeSiGn...\n\n\n  				   ChaPLiN/P.H.U.N/MsT/X-DeSiGn.\n  -EoF-\n\n  =======================================================================\n@endnode\n@node Cap02 "Requirements"\n  =======================================================================\n  To install Operator Pager you must have the following things:\n\n    Programm         Location        Description\n    ----------       --------        -----------\n    Operator.exe     Wherever        Main program\n    Operator.always  S:              blacklist file\n    Operator.never   S:              Cosysops, friends, etc...\n    Operator.goodbye S:              Guess what...\n\n  - an  Amiga Model (500/600/1000/1200/2000/2500/3000/4000/CDTV/CD³²)\n  - the installed Version of OS\2, OS\3 or higher\n    (Soft- or Hardware Version)\n  - the installed .INFO Files in the directories.\n  - AmiExpress v2.xx & v3.xx.\n\n  =======================================================================\n@endnode\n@node Cap05 "Greetings go to..."\n  =======================================================================\n\n                        Greetingz to:\n\n    \n Re/Y\o-/X-DeSiGN...................................Well now ya got it ;)\n ByteAndi/MsT ...........................Your FileId V1.3b is Working! :)\n SnoW.........................................::..MeGa SeGa BuG FiNDeR :)\n ScoRPio................................................BuG JouRNaLiST :)\n Bytemaster .........................................So read my mail ? :)\n Mr.Solo (BuTTeR Cup)..............................Still EgoTripping ? :-()=\n\n\n  And everybody worldwide, who thinks he/she should be in it. Give\n  me a buzz and I''ll put you in next time. (Soon coz more modules\n  coming up very soon) If you have a module that you want for your\n  bbs, feel free to call, made within 4 dayz, free of charge !\n                                      ^\n	 	 		      | due to TO popular demand 2 dayz\n					  has become impossible! :)\n\n  Btw, are there any female sysops around who need a "leave HER a mesage"\n  version ? Just call me up and i''ll fix that. :) Don''t wanna be a sexist.\n\n\n                       GreeTings OfCoZ To :\n\n                  >>> All MeMBeRs oF LoGiC <<<\n\n    !SNOW!, ASCENDER, AGNUS, !CALYPSO!, !CASTOR!, COSMIC, GHOSTRIDER,\n    !ROFOE!, SCAMPY, TRAVELLER, TRONIX, WARHAWK, XENTEC, !SNAKE/NAZGUL!,\n\n 	       Let''s noT forget OUR friendship mates !!\n\n\n                  >>> All MeMBeRs oF /X DeSiGn <<<\n\n	EmPiRe, ReMo, AnDi, AxE, SieGeL, .. i don''t have a member list\n         				    yet...if any exists :)\n\n    \n  =======================================================================\n@endnode\n@node Cap06 "How to contact us..."\n  =======================================================================\n \n .....'' U.N.I.T.E.D. I.N.T.E.R.N.A.T.I.O.N.A.L. C.O.N.N.E.C.T.I.O.N. ''.....\n \n     GoVeRNoRs: ChaPLiN & SToNy         Co-AmBaSSaDoRs: SPaCe FoR HiRe \n Workin''On: A5001/CuRY ''o80 8761.01Gb SeaCraTe 98Gb Rom DuAl Without PoWeR\n\n	 Node0.0: +32-2-270-04-07  Node0.1: +32-2-270-04-07\n	 Node0.2: +32-2-270-04-07  Node0.3: +32-2-270-04-07\n	 Node0.4: +32-2-270-04-07  Node0.5: +32-2-270-04-07\n	 Node0.5: +32-2-270-04-07  Node0.6: +32-2-270-04-07\n	 Node0.7: +32-2-270-04-07  Node0.8: +32-2-270-04-07\n	 Node0.9: +32-2-270-04-07  \n                              ...32...\n\n          AMIGA 0-3 YeaRS/Warez - BaSiC/AreXX, C-64 & VIC-20 /X Tools\n   \n         Ami-Express V5.0 - BuGGeD Chat System V933.442 - OlD Warez -\n    SloW Belgian BBS - UglY Design - OFFline 48Hourz A Day - CloSeD Since:\n 01/01/1990 - LaMe Confs! - NO /X ToolS At ReQuesT - CoDeD WithIn 4 YeaRs -\n\n   ______         ______         __  __         ______\n  / __  /\       /  /  /\       / /\/ /\       /   / /\       WoRlD\n /  ___/ /___   /     / /___   / /\/ / /___   /     / /___\n/__/\__\//__/\ /__/__/ //__/\ /_____/ //__/\ /__/__/ //__/\ HeaDQuaRTeRs\n\__\/    \__\/ \__\__\/ \__\/ \_____\/ \__\/ \__\__\/ \__\/\n\n\n		MySTiC /X DeSiGn BeLGiaN HeaDQuaRTeRS\n                                                                          \n  =======================================================================\n@endnode\n','\n',char(10)),NULL,NULL,17000,2,0,NULL,NULL,NULL,'scan',1780048671);
INSERT INTO door_catalog VALUES('phn_pg10','PHN-PG10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PHN-PG10.LHA',NULL,'XIM','REXXUTIL.LIBRARY',NULL,'PICARD/PHN','PHN',':/\________________________________________: :\___  /  /  /__ ____ _\ ._ __  / ___/___ _/ :_/ __/     /    /  / /// /    /__  / / / /:',replace('........................................LNF.\n:/\________________________________________:\n:\___  /  /  /__ ____ _\ ._ __  / ___/___ _/\n:_/ __/     /    /  / /// /    /__  / / / /:\n:\  //__/__/_/__/__/__/__/_/__/____/_/_/_/ :\n: \/  )=( pReSeNtS aNøThEr fInE tØøl )=(   :\n:..........................................:\n[ PHN-PAGER V1.0 - /X-TOOL - BY PICARD/PHN ]\n:··········································:\n:   Works with /X3.xx - /X4.xx or higher   :\n: Written in ARexx - Install it / Love it! :\n············································\n','\n',char(10)),'PHN-PAGER.DOC',replace('\n          __ _.\n     _______  |\n    |       \_|___ _______ _______ __________ ____ _______ ___________\n    |   |   _/    \_      \_      \_        /     \_      \_          \_\n    |   |___| |   _/  |   _/  |   _/|   |  /  |   _/  |____/  |   |   _/\n    |   | |   |   |       |   |   |_|   l_/       |___    |   |   |   |\n    |   | |   |   |   |   |   |   | |   | |   |   |   |   |   |   |   |\n    |   | l___|___l___|   l___|___| l___| l___|   l___    l___|___|___|\n    l___|  ¹995       \___|                   \___|   \___|By LNF!     \n \n                                  PRESENTS\n\n                          < PHN-PAGER VERSION 1.0 >\n\n                           CODED BY PICARD/PHN^SHT\n\n                   ---------------------------------------\n\n                          --> SHORT INSTRUCTIONS <--\n\n                           <1> About thiz Pager\n                           <2> System Requirements\n                           <3> Installation\n                           <4> Config File\n                           <5> History\n                           <6> Future Projects\n                           <7> Greetings\n                           <8> Contact Me\n\n                   ---------------------------------------\n\n\n\n <1> About thiz Pager\n --------------------\n\n The Pager (V1.0) is written in ARexx. It is my first project in\n programming AmiExpress-Tools.\n\n I''m still learning how to code in "C". ARexx is nice, but not a \n language for programmers! (Hope, that I learn it fast hehe)\n\n I know there are a lot of other nice pagers out there, but I tried\n to create my own one, and I think, It is really nice.....\n\n Install it / Love it!\n\n\n <2> System Requirements\n -----------------------\n\n  To use my "PHN-PAGER" you need :\n\n  · COMMODORE AMIGA (TM) OS 2.0 OR HIGHER\n  · AN AMIGA MODEL 500,600,1000,1200,2000,2500,3000,3000T,4000,4000T\n  · A WELL INSTALLED VERSION OF AMI EXPRESS /X3.xx ; /X4.xx OR HIGHER\n\n\n <3> Installation\n ----------------\n\n  Installation under /X3.xx ÷ /X4.xx (or higher) :\n\n    · Copy all Files of this archive to the correct bbs-drawers. \n\n  Installation under /X1.xx ÷ /X2.xx ÷ S!X :\n\n    · Sorry dudes! But I don''t know how to install /X-Doors in Ami Express\n      2.xx / 1.xx or S!X, but I think, if you run a bbs with this versions\n      you know how to install this door ;)\n\n\n <4> Config-File\n ---------------\n\n You find the Config-File of "PHN-PAGER" after the complete Installation\n in following Dir :\n\n BBS:DOORS/PHN/PAGER/PAGER.CONFIG\n\n The Config-File is very simple..... You can edit the lines with your\n favourite Text-Editor and create Lines like this :\n\n TRY AN ANOTHER TIME, IT''S TO LATE FOR A CHAT\n SYSOP IS STONED AND NOT ABLE TO CHAT WITH YA \n IT''S PAADDYY TIME... TRY TO PAGE ME TOMORROW\n SHIT! I''M OUT OF DOPE - NOTHING TO SAY, BYE!\n\n                                            ^ Important for the Style of\n                                              my Pager, don''t use more\n                                              characters as is!\n\n\n <5> History\n -----------\n\n V1.0ß   =   Internal Release to test it on my own bbs.\n\n V1.0    =   First Released Public Version.\n\n\n <6> Future Projects\n -------------------\n\n · A new pager full coded in "C" with a Chat-Requester for WB-Screen\n   and a Replay-Routine for Samples and/or short Modules.\n\n · A Security Checker against Hacking AmiExpress.\n\n\n <7> Greetings\n -------------\n\n C/\NN¡B/\L^NJY    YEAH! MY FIRST /X-TOOL, NICE EH ?¿\n [SATAN+GOD]^NJY   STILL WORKING ON A NEW BBS?\n MOSH^PSI^PHN      WORK SUXX EH ¿?\n BLADE^PSI         HI! WHERE ARE THE BREAKABLE LINES?\n TEAK^MYTH         HI MY DUTCH FRIEND, HOW ARE YOU?\n DR.DRE^TRSI       YA TOOLS ARE REALLY KEWL DUDE!\n\n\n ........ AND TO ALL SHT^PHN MEMBERS OUT THERE!\n\n\n <8> Contact Me\n --------------\n\n You can reach me on following boards.......\n\n DEVILS POINT II  - TRSI GHQ\n DRIVE BY SHOOTIN - PSI GHQ\n MINDLOSS         - N-JOY GHQ\n TOONTOWN         - OSIRIS GHQ\n DANZIG           - PHN GHQ\n\n or directly on my own bbs.......\n\n TRESPASS         - SHT EHQ / PHN GHQ\n\n\n ÷-----------------------÷\n ÷ THAT WAS ALL FOLKS :) ÷\n ÷-----------------------÷\n','\n',char(10)),NULL,'auto-added',13529,1,0,NULL,NULL,'phn_pg10','scan',1780048671);
INSERT INTO door_catalog VALUES('phn_pg11','PHN-PG11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PHN-PG11.LHA','AMIGAGUIDE','XIM','AMIGAGUIDE',NULL,'PICARD/PHN!','PHN',':/\________________________________________: :\___  /  /  /__ ____ _\ ._ __  / ___/___ _/ :_/ __/     /    /  / /// /    /__  / / / /:',replace('........................................LNF.\n:/\________________________________________:\n:\___  /  /  /__ ____ _\ ._ __  / ___/___ _/\n:_/ __/     /    /  / /// /    /__  / / / /:\n:\  //__/__/_/__/__/__/__/_/__/____/_/_/_/ :\n: \/  )=( pReSeNtS aNøThEr fInE tØøl )=(   :\n:..........................................:\n[ PHN-PAGER V1.1 - UPDATE - BY PICARD/PHN! ]\n:··········································:\n:   Works with /X3.xx - /X4.xx or higher   :\n: Written in ARexx - Install it / Love it! :\n············································\n','\n',char(10)),'PHN-PAGER.GUIDE',replace('@Database PHN-PAGER V1.1 \n\n(C) & (W) bY pICARD of sHT^pHN oN 18th fEBRUARY 1995\n\n@Remark $VER: (February 18 1995, 12:42:34)\n@Remark AmigaGuide Database for PHN-PAGER V1.1\n\n@node MAIN "GUIDE MAIN"\n          __ _.\n     _______  |\n    |       \_|___ _______ _______ __________ ____ _______ ___________\n    |   |   _/    \_      \_      \_        /     \_      \_          \_\n    |   |___| |   _/  |   _/  |   _/|   |  /  |   _/  |____/  |   |   _/\n    |   | |   |   |       |   |   |_|   l_/       |___    |   |   |   |\n    |   | |   |   |   |   |   |   | |   | |   |   |   |   |   |   |   |\n    |   | l___|___l___|   l___|___| l___| l___|   l___    l___|___|___|\n    l___|  ¹995       \___|                   \___|   \___|By LNF!     \n                                  PRESENTS\n\n                          < PHN-PAGER VERSION 1.1 >\n\n                           CODED BY PICARD/PHN^SHT\n                   ---------------------------------------\n\n                         @{" <1> About thiz Pager    " Link Part01}\n                         @{" <2> System Requirements " Link Part02}\n                         @{" <3> Installation        " Link Part03}\n                         @{" <4> Configuration       " Link Part04}\n                         @{" <5> Lengths             " Link Part09}\n                         @{" <5> History             " Link Part05}\n                         @{" <6> Future Projects     " Link Part06}\n                         @{" <7> Some Greetz         " Link Part07}\n                         @{" <8> Contact Me          " Link Part08}\n\n                   ---------------------------------------\n@endnode\n@node Part01 "About thiz Pager"\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n The PHN-PAGER V1.1 is written in ARexx and placed as FreeWare.\n It is one of my first Projects in programming Tools for Ami Express.\n \n I''m still learning how to code in "C". ARexx is nice, but not a\n language for programmers! (I hope, that I learn it fast hehe)\n\n I know there are a lot of other nice pagers out there, but I tried\n to code my own one, and I think, is is really nice.....\n\n Install it / Use it / Love it!\n\n @{" GO BACK!  " Link MAIN}\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@endnode\n@node Part02 "System Requirements"\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n  To use "PHN-PAGER" you need :\n\n  · COMMODORE AMIGA (TM) OS 2.0 OR HIGHER\n  · AN AMIGA MODEL 500,600,1000,1200,2000,2500,3000,3000T,4000,4000T\n  · A WELL INSTALLED VERSION OF AMI EXPRESS /X3.xx ; /X4.xx OR HIGHER\n\n @{" GO BACK! " Link MAIN}\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@endnode\n@node Part03 "Installation"\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n  Installation under /X3.xx ÷ /X4.xx (or higher) :\n\n    · Copy all Files of this archive to the correct bbs-drawers. \n\n\n  Installation under /X1.xx ÷ /X2.xx ÷ S!X :\n\n    · Sorry dudes! But I don''t know how to install /X-Doors in Ami Express\n      2.xx / 1.xx or S!X, but I think, if you run a bbs with this versions\n      you know how to install this door ;)\n\n @{" GO BACK! " Link MAIN}\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@endnode\n@node Part04 "Config the Pager"\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n You find the Config-File of "PHN-PAGER" after the complete Installation\n in following Dir :\n\n BBS:DOORS/PHN/PAGER/PAGER.CONFIG\n\n The Config-File is very simple..... You can edit the lines with your\n favourite Text-Editor and create Lines like this :\n\n TRY AN ANOTHER TIME, IT''S TO LATE FOR A CHAT\n SYSOP IS STONED AND NOT ABLE TO CHAT WITH YA \n IT''S PAADDYY TIME... TRY TO PAGE ME TOMORROW\n SHIT! I''M OUT OF DOPE - NOTHING TO SAY, BYE!\n\n                                            ^ Important for the Style of\n                                              my Pager, don''t use more\n                                              characters as is!\n\n @{" GO BACK!  " Link MAIN}\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@endnode\n@node Part05 "History"\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n V1.0ß  -->  Internal Release to test it on my own bbs.\n\n V1.0   -->  First Released Public Version.\n\n V1.1   -->  - Shit bug found.... Sometimes the Pager crashes, cause\n               a mistake in the main code.... now fixed!\n             - If a user didn''t enter a reason why paging the sysop,\n               the pager should abort page, but the pager continue\n               paging the sysop.... now fixed!\n             - Doc rewritten as a Guide Txt\n\n @{" GO BACK!  " Link MAIN}\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@endnode\n@node Part06 "Future Projects"\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n · A major Update of my PHN-PAGER completly rewritten in "C" with a\n   Chat-Requester for WB-Screen and a Replay-Routine for Samples and/or\n   NT/PT-Modules.\n\n · A new Version of my PHN-ANSI completly rewritten in "C" too with a\n   Save-Option for each user. So the user choose one time his favorite\n   Display-Mode (Ansi/RIP/ASCII etc), PHN-ANSI saves this, so the user\n   needn''t to choose it again on further logins.  \n\n · A Security Checker against Hacking AmiExpress.\n\n @{" GO BACK!  " Link MAIN}\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@endnode\n@node Part07 "Some Greetz"\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n C/\NN¡B/\L^NJY    HOPE TO SEE YA ON NEXT PADDY ¿?\n [SATAN+GOD]^NJY   STILL WORKING ON A NEW BBS?\n MOSH^PSI^PHN      28K8 RULEZ!\n BLADE^PSI         SOMETHING NEW ABOUT BB ¿?\n GRANDMASTER^PGY   THX FOR NUMBAS....\n JOE PUNK (INDEP)  HOPE TO SEE YA ON MY BBS SOON!\n JSINCL.^PSI       THX FOR REGISTERED TIME-STAMP\n\n ........ AND TO ALL SHT^PHN MEMBERS OUT THERE!\n\n @{" GO BACK!  " Link MAIN}\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@endnode\n@node Part08 "Contact Me"\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n You can reach me as <PICARD> on following boards.......\n\n DEVILS POINT II  - TRSI GHQ\n DRIVE BY SHOOTIN - PSI GHQ\n MINDLOSS         - N-JOY GHQ\n TOONTOWN         - OSIRIS GHQ\n DANZIG           - PHN GHQ\n\n or directly on my own bbs.... Start at 01.04.95!\n\n TRESPASS         - SHT EHQ / PHN GHQ\n\n @{" GO BACK!  " Link MAIN}\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@endnode\n@node Part09 "Lengths"\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n THIS MUST BE IN THE ORIGINAL-ARCHIVE :\n\n\n > PHN-PAGER\n\n PHN-PAGER.GUIDE                         LENGHT :  7811 BYTES\n \n > PHN-PAGER/C\n\n AMIGAGUIDE (POWERPACKER (tm) VERSION)   LENGHT :  7952 BYTES\n\n > PHN-PAGER/BBS/COMMANDS/BBSCMD/\n\n O.INFO                                  LENGHT :  1086 BYTES\n\n > PHN-PAGER/BBS/DOORS/PHN/PAGER/\n\n PHN-PAGE.REXX                           LENGHT :  2557 BYTES\n PAGER.CONFIG                            LENGHT :   181 BYTES\n\n > PHN-PAGER/LIBS\n\n REXXUTIL.LIBRARY                        LENGHT : 10676 BYTES\n POWERPACKER.LIBRARY                     LENGHT :  6128 BYTES\n\n ---------------\n\n IF YOU WANT TO BE SURE THAT ALL WORKS 100%, YOU CAN LEECH THE ORIGINAL\n 100% PERCENT VERSION ON FOLLOWING BOARDS IN THE LATEST VERSIONS....\n\n MINDLOSS         - N-JOY GHQ\n DANZIG           - PHN GHQ\n TRESPASS         - SHT EHQ / PHN GHQ\n\n ---------------\n\n TRY TO FIND US, ASK MEMBERS OF PHN / SHT & N-JOY!\n \n @{" GO BACK!  " Link MAIN}\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@endnode\n','\n',char(10)),NULL,'auto-added',21345,1,0,NULL,NULL,'phn_pg11','scan',1780048671);
INSERT INTO door_catalog VALUES('phn_pg12','PHN-PG12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PHN-PG12.LHA','AMIGAGUIDE','XIM','AMIGAGUIDE',NULL,'PICARD/PHN!','PHN',':/\________________________________________: :\___  /  /  /__ ____ _\ ._ __  / ___/___ _/ :_/ __/     /    /  / /// /    /__  / / / /:',replace('........................................LNF.\n:/\________________________________________:\n:\___  /  /  /__ ____ _\ ._ __  / ___/___ _/\n:_/ __/     /    /  / /// /    /__  / / / /:\n:\  //__/__/_/__/__/__/__/_/__/____/_/_/_/ :\n: \/  )=( pReSeNtS aNøThEr fInE tØøl )=(   :\n:..........................................:\n[ PHN-PAGER V1.2 - UPDATE - BY PICARD/PHN! ]\n:··········································:\n:   Works with /X3.xx - /X4.xx or higher   :\n: Written in ARexx - Install it / Love it! :\n············································\n','\n',char(10)),'PHN-PAGER.GUIDE',replace('@DATABASE PHN-PAGER V1.2 \n\n(C) & (W) BY PICARD OF PHN^SHT ON 20TH MARCH 1995\n\n@REMARK $VER: (MARCH 20 1995, 00:00:00)\n@REMARK AMIGAGUIDE DATABASE FOR PHN-PAGER V1.2\n\n@NODE MAIN "GUIDE MAIN"\n          __ _.\n     _______  |\n    |       \_|___ _______ _______ __________ ____ _______ ___________\n    |   |   _/    \_      \_      \_        /     \_      \_          \_\n    |   |___| |   _/  |   _/  |   _/|   |  /  |   _/  |____/  |   |   _/\n    |   | |   |   |       |   |   |_|   l_/       |___    |   |   |   |\n    |   | |   |   |   |   |   |   | |   | |   |   |   |   |   |   |   |\n    |   | l___|___l___|   l___|___| l___| l___|   l___    l___|___|___|\n    l___|  ¹995       \___|                   \___|   \___|By LNF!     \n                                  PRESENTS\n\n                          < PHN-PAGER VERSION 1.2 >\n\n                           CODED BY PICARD/PHN^SHT\n                   ---------------------------------------\n\n                           @{" About the Pager     " Link Part01}\n                           @{" System Requirements " Link Part02}\n                           @{" Installation        " Link Part03}\n                           @{" Configuration       " Link Part04}\n                           @{" Error-Log           " Link Part05}\n                           @{" Lengths             " Link Part06}\n                           @{" History             " Link Part07}\n                           @{" Future Projects     " Link Part08}\n                           @{" Some Greetz         " Link Part09}\n                           @{" Contact Me          " Link Part10}\n\n                   ---------------------------------------\n@ENDNODE\n@NODE PART01 "About thiz Pager"\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n The PHN-PAGER V1.2 is written in ARexx and placed as FreeWare.\n This is one of my first projects in programming Tools 4 Ami Express.\n\n I''m still learning how to code in "C". ARexx is nice, but not a\n coding-language 4 programmers!\n\n (So I think, I have to learn it fast! hehe)\n\n I know there are a lot of other cool pagers out there, some are really\n good and other are shitty, so I tried to code my own one, and I think\n it is really nice....\n\n Install it! / Use it! / Love it!\n\n\n @{" GO BACK!  " Link MAIN}\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@ENDNODE\n@NODE PART02 "System Requirements"\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n  To use "PHN-PAGER" you need :\n\n  · AN AMIGA MODEL (500,600,1000,1200,2000,2500,3000,3000T,4000,4000T)\n  · A COMMODORE AMIGA (TM) OS 2.0 OR HIGHER ROM.\n  · A WELL INSTALLED VERSION OF AMI EXPRESS /X3.xx ; /X4.xx OR HIGHER\n    (MAYBE IT WORKS WITH /X1.xx - /X2.xx - S!X - TEMPEST OR DAYDREAM)\n\n @{" GO BACK! " Link MAIN}\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@ENDNODE\n@NODE PART03 "Installation"\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n  Installation under AmiExpress V3.xx - V4.xx (or higher) :\n\n    · Just copy all Files of this Archive to the correct bbs-drawers.\n\n  Installation under AmiExpress V1.xx - V2.xx - S!X - Tempest - Daydream :\n\n    · AEHHMM.... Sorry dudes! But I don''t know how to install my door in\n      these BBS-Programs.... But I think, If you run a BBS with these\n      Programms, you know how to install it (?) ;)\n\n @{" GO BACK! " Link MAIN}\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@ENDNODE\n@NODE PART04 "Config the Pager"\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n You''ll find the Config-File of "PHN-PAGER" after the complete\n Installation in following Dir :\n\n BBS:DOORS/PHN/PAGER/ called PAGER.CONFIG\n\n The Config-File is very simple..... Just edit the Lines with your\n favourite Text-Editor (CED, GOLD ED etc.) or add new ones......\n\n PAGER.CONFIG :\n\n TRY AN ANOTHER TIME, IT''S TO LATE FOR A CHAT\n SYSOP IS STONED AND NOT ABLE TO CHAT WITH YA \n IT''S PAADDYY TIME... TRY TO PAGE ME TOMORROW\n SHIT! I''M OUT OF DOPE - NOTHING TO SAY, BYE!\n\n                                            ^ Important for the Style of\n                                              my Pager, don''t use more\n                                              characters as is!\n\n You can use a maximum of 10 Lines, otherwise my pager will crash....\n (In the final "C"-Version I''ll fix that shitty Bug!)\n\n @{" GO BACK!  " Link MAIN}\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@ENDNODE\n@NODE PART05 "Error-Log"\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n Jepp, a new feature since this Version. The "PHN-PAGER" checks itself!\n If it founds an Error it writes an Error-Description to a File\n placed in :\n\n BBS:DOORS/PHN/PAGER/ called ERRORS.LOG.\n\n Just have a look on it, if the Pager doesn''t work!\n\n @{" GO BACK!  " Link MAIN} \n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@ENDNODE\n@NODE PART06 "LENGHTS"\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n THIS MUST BE IN THE ORIGINAL-ARCHIVE......\n\n > PHN-PAGER\n\n PHN-PAGER.GUIDE                         LENGHT :  9917 BYTES\n \n > PHN-PAGER/C\n\n AMIGAGUIDE (POWERPACKER (tm) VERSION)   LENGHT :  7952 BYTES\n\n > PHN-PAGER/BBS/COMMANDS/BBSCMD/\n\n O.INFO                                  LENGHT :  1086 BYTES\n\n > PHN-PAGER/BBS/DOORS/PHN/PAGER/\n\n PHN-PAGE.REXX                           LENGHT :  4180 BYTES\n PAGER.CONFIG                            LENGHT :   181 BYTES\n\n > PHN-PAGER/LIBS\n\n REXXUTIL.LIBRARY                        LENGHT : 10676 BYTES\n POWERPACKER.LIBRARY                     LENGHT :  6128 BYTES\n\n ------------------------------------------------------------------------\n\n IF YOU WANT TO BE SURE THAT ALL WORKS 100%, BETTER LEECH THE ORIGINAL\n "100% PERCENT" VERSION ON FOLLOWING BOARDS IN THE LATEST VERSIONS....\n\n TRESPASS - PHANTASM GHQ / SHOOT EHQ\n DANZIG   - PHANTASM GHQ\n MINDLOSS - N-JOY GHQ\n\n -----------------------------------------------------------------------\n\n TRY TO FIND US, ASK MEMBERS OF PHANTASM / SHOOT & N-JOY!\n\n @{" GO BACK!  " Link MAIN} \n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@ENDNODE \n@NODE PART07 "HISTORY"\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n The "PHN-PAGER" History :\n\n V1.2   -->  - Code improved and optimized\n             - Code checks itself 4 errors\n             - Error-Log Handling Feature added\n             - Some Guide-Parts rewritten\n\n V1.1   -->  - Shit bug found.... Sometimes the Pager crashes, cause\n               a mistake in the main code.... now fixed!\n             - If a user didn''t enter a reason why paging the sysop,\n               the pager should abort page, but the pager continued\n               paging the sysop.... now fixed!\n             - Doc rewritten to Guide-Text Style\n\n V1.0   -->  - First Released Public Version\n \n V1.0ß  -->  - Internal Release to test it on my own bbs.\n\n @{" GO BACK!  " Link MAIN}\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@ENDNODE\n@NODE PART08 "FUTURE PROJECTS"\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n · I''m still working on a major Update of this Pager. Completly rewritten\n   in "C" with a Chat-Requester 4 WB-Screen (Chat/Do Nothing/Denial) and\n   with a Replay-Routine for Samples and/or Noisetracker / Protracker\n   Modules.\n\n · I don''t know, maybe after the "C-Rewritten-Pager" I rewrite my\n   "PHN-ANSI" too. I have some ideas, like a Save-Option for each user,\n   so the user just only chooses one time his favorite Display-Mode :\n   ANSI/RIP OR ASCII etc. and PHN-ANSI saves this, so the user needn''t\n   to choose it again and again and again......\n\n · The Next Project : A Security Checker against Hacking AmiExpress\n   "online". I''m still working on it, too.\n\n @{" GO BACK!  " Link MAIN}\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@ENDNODE\n@NODE PART09 "SOME GREETZ"\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n Some Greetz must go to......\n\n C/\NN¡B/\L  ^  NJY  WHAT ABOUT A MEGA-MEETING OF ALL /X-BBS IN OUR AREA?\n [SATAN+GOD] ^  NJY  HEY! WHERE ARE YOU ? - BACK TO HELL ???? (hehe)\n MOSH        ^  PHN  HI MY FRIEND! SEE YA ON NEXT PHN-MEETING...\n LATEX       ^  PHN  THX 4 DA NUMBAS.... I FORGOT THEM (hui)\n RIKER       ^  INP  I WANT "SUPER STATUS V2.0" YEAH!\n M. HACKMAN  ^  INP  SOME''THIN NEW ABOUT BB OR CC ?¿?\n\n SPECIAL GREETS TO SILICONSURFER & RICO (BOTH IN PHANTASM!)\n COOL MUZAKS RICO.... GO ON! - NICE ROOMS YOU HAVE S.SURFER (hehe)\n\n MUSIC GREETS TO..... MINISTRY (Yeah... Burning Inside)\n                      DANZIG   (Mother Rulez)\n                      SODOM    (Meine Pornos sind mir lieber hehe)\n                      \n                      & TANKARD (4 Space Beer! ... hick ...) \n\n and to all other Members of PHN^SHT in thiz terrible fuck''in world!\n\n @{" GO BACK!  " Link MAIN}\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@endnode\n@node Part10 "Contact Me"\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n You can reach me as <PICARD> on following boards......\n\n Elite  :   "NEW" DEVILS POINT  -  TRSI GHQ\n            DRIVE BY SHOOTIN    -  PSI GHQ\n            MINDLOSS            -  N-JOY GHQ\n            TOONTOWN            -  OSIRIS GHQ\n          ! DANZIG              -  PHANTASM GHQ !\n          ! PARANOIA COMPLEX    -  SHOOT WHQ    !\n\n LEGALY :   NOTRE DAME  +49-(0)40-247-816\n            WUSELMANIA  +49-(0)481-716-48\n\n or directly on my own bbs.... (Re-)Start at 01.04.95!\n\n TRESPASS         - SHOOT EHQ / PHANTASM GHQ\n\n @{" GO BACK!  " Link MAIN}\n\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@endnode\n','\n',char(10)),NULL,'auto-added',24296,5,0,NULL,NULL,'phn_pg12','scan',1780048671);
INSERT INTO door_catalog VALUES('phn_sd10','PHN-SD10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PHN-SD10.LHA','PHN-SysopDownload','XIM','PHN-SysopDownload',NULL,'tHE','PHN','(    \               ____ |  ·  )__ ___________)  (_____ ________  _ | ___/ l \) . ()    (_  _) . ((  __  ) \/(',replace(' ____\n(    \               ____\n|  ·  )__ ___________)  (_____ ________  _\n| ___/ l \) . ()    (_  _) . ((  __  ) \/(\n|  (     /     \  |  |  /     /\_  \/     \\n|   \_l_/   l___)_l__l_/   l_(_____/   \/\_)\nl____)-(_____)-bRiNgS-(_____)-ppx-(_____)---\n \n   ... PHN-SysopDownload V1.0 for /X ...\n       ... dONe bY tHE aLIEN/pHN ...\n[ M-E ]·-·-·-·-·-·-·-·-·-·-·-·-·-·-·-[ M-E ]\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 19:00:55  ON NODE: 1\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',13139,5,0,NULL,NULL,'phn_sd10','scan',1780048671);
INSERT INTO door_catalog VALUES('pi_st10a','PI-ST10A.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PI-ST10A.LHA','Statusbbs','XIM','Statusbbs',NULL,NULL,'PI','/o___//o___//o___//o _¬\o  _ /\  / /o___/ /\_ ø\// !__//__)_// ___/\_/  \/\/\// !__ // (  \\  : ¬\ )  ¬\  ¬\   //   \   \  : ¬\',replace('   _____ _____ _____ _______________  _____\n  /o___//o___//o___//o _¬\o  _ /\  / /o___/\n /\_ ø\// !__//__)_// ___/\_/  \/\/\// !__ \n// (  \\  : ¬\ )  ¬\  ¬\   //   \   \  : ¬\\n\ _____/_____/_____/___/[F]\____/___/___ _/\n-Y - --÷  Piwi $ceptic /X-Design  ÷-- - Y- \nNew Status Door V1.0 XIM-Door for /X2.x&3.x\n','\n',char(10)),'Status.doc',replace('\n                  __/\_____  _____ ____  )\_____/\\n RUNNING ON:      \°      °\ \°   V   °\ \°      °\        S N E S\n ----------        \_____   \ \___¡___  \ \_____   \      A M I G A\n /X V3.37           ____//  /  ___:__//  \ __ _ \\  \\n A1200 / 12MEG RAM /° ___   \ /°  V__     \\°V°\//   \\n 850 HD           //  \_//   \\\  ¡\ \\   ///¡       / \n                  \_______   / \\ ./  \\ //_ : _____/  \n        _        _        \ /   \ /    \/_  )¡(           _\n_______/( _______)\ __ _   V   _ V _   _ )\___  _____   _ )\_ ____    _\n\°      °\\°     °//° V°\  ¡   \)¡(°\ /°V    °\ \°  °\ /°V  °\\° °\  /°\\n \_____   \\\ ___///  ¡ /  :   //:  /// ¡ ____/ //   /// ¡_   \\\  \ \  \\n  ____//  /// \___\\  :/(F)¡  // ¡ ///  :/ ___ //   ///  / \\  \\\  \//  \\n /° ___   \\\ /____\\ ;\_ __/\\\ . \\\  ¡\/° °\\\   \\\  \ //  /// /\\    \\n//  \ //   \\\    °\\\   V   °\\\   \\\ .      \\\   \\\  V   ///  \ \\   /\n\\  / \____//_____  \\___¡ ___/// __/ \____/\  ///_ _/ \__   / \_ _/  \  /\n \ /              \ /    \/    \ /           \/ \/ V      \ /    V     \/\n  V                V            V                  ¡       V     ¡\n  ¡ SYSOP: Z/\<Ke / $CEPTIC     !                  ;       ¡     :\n       CO: MR.VAIN / $CEPTIC    .  +49-4638-8306                 .\n       CO: WOTAN / INDEPENDENT\n\n\n\n\n                                DISCLAIMER\n                               ------------\n\nOk Guys, let''s start.\n\n\nPurpose:\n--------\n\n -First Door:\n ------------\n\nFirst of all i would like to say that this Door was written because there are\nso many Status-Doors out there which dont show the right kind of thing.The\nfirst shows only a few things, which could be important, but not all of those\nkind of Doors have this things.The second thing i dont like is the rating\nwhich is choosen by someone who could be really mad.This Door makes it poss-\nible to show the User which is using this Door which Commands are available\nfor him.He will shown a Text-File wich shows him all available Commands.The \nonly thng is that the Sysop have to Edit it.Further Explaination follows at\nthe Installation\nThis Time i changed the Door from AIM to XIM Door because its much faster than\nArexx. Ok try it out.\n\n -Second Door:\n -------------\n\nYes! There is a second Door!! Do you see the shit Status which is shown by\n/X 2.xx and /X 3.xx. I saw a Status in the fine S-Express so i decided to \nwrite a similar one for /X-Users. So try it and enjoy it!\n\nInstallation:\n-------------\n\nFirst of all it is an XIM-Door which could be used in /X2.xx & /X3.xx\n\n - Installation on /X 2.xx:\n --------------------------\n\nThe Installation on /X2.xx is to be like the following:\nFirst of all copy all files of the Door-Directory in this Archive to Yours\nand then add the following lines to your BBSCMD:\n\n-------^Cut here^-----------------------\nS         XM010DOORS:PIWI/STATUSBBS\n-------^and here^-----------------------\n\nThe Installation of the second Door is only to add a Command to your SYSCMD\nbecause the File which is needed is in the Door-Directory too. So just add\nfollowing Lines to Your SYSCMD:\n\n-------^Cut here^-----------------------\nS         XM010DOORS:PIWI/STATUSSYS\n-------^and here^-----------------------\n\nOk the next thing you have to do is to edit a Textfile which contains all\nthe Commands to the Security-Level someone has\nI.e.:Edit the File Access(Access-Level) --> Access200\n     This File must contain all available Commands for Security-Level\nThats all Folks.\n\n - Installation on /X 3.xx:\n --------------------------\n\nThe Installation for /X3.xx-Users is much easier to handle. Just copy the\ncomplete Door-irectory to yours and copy all the Commands to yours. Be sure\nthat BOTH, either the bbscmd- AND the syscmd-Command-Infos are copied.\nOk the next thing you have to do is to edit a Textfile which contains all\nthe Commands to the Security-Level someone has\nI.e.:Edit the File Access(Access-Level) --> Access200\n     This File must contain all available Commands for Security-Level\n\nThats all for doing  under /X3.xx\n\n\nHistory:\n--------\n\n\nV0.1 First only Internal Release, Bugs in Formatting the Output\n     Never released\n\nV0.2 Bugs in Formatting removed, added some Kind of Color-Formatting\n     Never released too\n\nV0.5 All Kind of Formatting corrected and building some colors in output.\n     Released: 15-04-94\n\nV0.6 Some Bugs Fixed; Sorry you cant use any Other BBS-Name than ''BAD RELIGION'' - Bug fixed ;\n     Some cosmetical Changes made\n     Released: 18-04-94\nV1.0 Some Additional work done, compiled in C-Language, able to show all \n     available Commands at Security-Level which someone has\n	 Released: 05-05-94\n\nFuture Planings:\n----------------\n\nI planned to do some more Modules for /X 2.xx and of course /X 3.xx.But they\nall would be XIM-Modules.\nThere Would be:\n               - A new Time Door\n               - A new Wall\n               - A cool Calling-Card-Registrater\n               - and some more Tools\n\nEnjoy the waiting!!!!\n\nGreetings:\n---------\n\nOK Greetings are going to Zacke/Sceptic Wotan/Sceptic and Mr.Vain/Sceptic.\n\nSuggestions:\n------------\n\nOk If you have any Suggestions to do please leave me a Messy on a Board of\nthe folowing ones:\n\n                            BAD RELIOGION +49-4638-8306\n                            DEAD LINE     +40-461-ELITE\n\n     Leave a Messy for Zacke or Mr.Vain or Wotan which are my Partners\n\n\n\n\n                  __/\_____  _____ ____  )\_____/\\n RUNNING ON:      \°      °\ \°   V   °\ \°      °\        S N E S\n ----------        \_____   \ \___¡___  \ \_____   \      A M I G A\n /X V3.37           ____//  /  ___:__//  \ __ _ \\  \\n A1200 / 12MEG RAM /° ___   \ /°  V__     \\°V°\//   \\n 850 HD           //  \_//   \\\  ¡\ \\   ///¡       / \n                  \_______   / \\ ./  \\ //_ : _____/  \n        _        _        \ /   \ /    \/_  )¡(           _\n_______/( _______)\ __ _   V   _ V _   _ )\___  _____   _ )\_ ____    _\n\°      °\\°     °//° V°\  ¡   \)¡(°\ /°V    °\ \°  °\ /°V  °\\° °\  /°\\n \_____   \\\ ___///  ¡ /  :   //:  /// ¡ ____/ //   /// ¡_   \\\  \ \  \\n  ____//  /// \___\\  :/(F)¡  // ¡ ///  :/ ___ //   ///  / \\  \\\  \//  \\n /° ___   \\\ /____\\ ;\_ __/\\\ . \\\  ¡\/° °\\\   \\\  \ //  /// /\\    \\n//  \ //   \\\    °\\\   V   °\\\   \\\ .      \\\   \\\  V   ///  \ \\   /\n\\  / \____//_____  \\___¡ ___/// __/ \____/\  ///_ _/ \__   / \_ _/  \  /\n \ /              \ /    \/    \ /           \/ \/ V      \ /    V     \/\n  V                V            V                  ¡       V     ¡\n  ¡ SYSOP: Z/\<Ke / $CEPTIC     !                  ;       ¡     :\n       CO: MR.VAIN / $CEPTIC    .  +49-4638-8306                 .\n       CO: WOTAN / INDEPENDENT\n','\n',char(10)),NULL,'auto-added',27675,8,0,NULL,NULL,'cp_ps12','scan',1780048671);
INSERT INTO door_catalog VALUES('picfil_1','PICFIL~1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PICFIL~1.LHA','MagicDiz','XIM','MagicDiz',NULL,'Extractor/Packer',NULL,'Use With BoBo''s XIM Door! Config Included! INSTALL NOW!!!',replace('GIF, JPG And IFF FileID Extractor/Packer To\nUse With BoBo''s XIM Door! Config Included!\nINSTALL NOW!!!\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 19:00:54  ON NODE: 1\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',29341,5,0,NULL,NULL,'picfil_1','scan',1780048671);
INSERT INTO door_catalog VALUES('pin_win','PIN-WIN.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PIN-WIN.LHA',NULL,'XIM','A NEW /X DOOR CALLED PIN+WIN...',NULL,NULL,'PIN',NULL,replace('A NEW /X DOOR CALLED PIN+WIN...\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 19:00:53  ON NODE: 1\n','\r',char(13)),'\n',char(10)),NULL,NULL,29482,3,0,NULL,NULL,NULL,'scan',1780048671);
INSERT INTO door_catalog VALUES('piw_st05','PIW-ST05.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PIW-ST05.LHA','rexxdoor','XIM','REXXPLSLIB.LIBRARY',NULL,NULL,'PIW','*=- Status V0.5 -=* First Public Release for all /X2.x&3.x Users and of course for S-Xpress Users',replace('PIWI/Independent - /X-Development presents:\n           *=- Status V0.5 -=*\nFirst Public Release for all /X2.x&3.x Users\n     and of course for S-Xpress Users\n','\n',char(10)),'Status.doc',replace('\n				DISCLAIMER\nOk Guys, let''s start.\n\nPurpose:\n\n -First Door:\n\nFirst of all i would like to say that this Door was written because there are\nso many Status-Doors out there which dont show the right kind of thing.The\nfirst shows only a few things, which could be important, but not all of those\nkind of Doors have this things.The second thing i dont like is the rating\nwhich is choosen by someone who could be really mad.I dont like rating at all\nbut i use ONE in my Door too.The only rating is to show if someone is an Elite\nor not.Ok i think thats enough because i couldnt write as much as i thought.\n\n -Second Door:\n\nYes! There is a second Door!! Do you see the shtt Status which is shown by\n/X 2.xx and /X 3.xx. I saw a Status in the fine S-Express so i decided to \nwrite a similar one for /X-Users. So try it and enjoy it!\n\nInstallation:\n\nFirst of all it is an AIM-Door which could be used in /X2.xx & /X3.xx\n\nThe Installation on /X2.xx is to be like the following:\nFirst of all copy all files of the Door-Directory in this Archive to Yours\nand then add the following lines to your BBSCMD:\n\n-------^Cut here^-----------------------\nS         AM010DOORS:PIWI/STATUSBBS.REXX\n-------^and here^-----------------------\n\nThe Installation of the second Door is only to add a Command to your SYSCMD\nbecause the File which is needed is in the Door-Directory too. So just add\nfollowing Lines to Your SYSCMD:\n\n-------^Cut here^-----------------------\nS         AM010DOORS:PIWI/STATUSSYS.REXX\n-------^and here^-----------------------\n\nThats all Folks.\n\nThe Installation for /X3.xx-Users is much easier to handle. Just copy the\ncomplete Door-irectory to yours and copy all the Commands to yours. Be sure\nthat BOTH, either the bbscmd- AND the syscmd-Command-Infos are copied.\nThats all for doing  under /X3.xx\n\nHistory:\n\n\nV0.1 First only Internal Release, Bugs in Formatting the Output\n     Never released\n\nV0.2 Bugs in Formatting removed, added some Kind of Color-Formatting\n     Never released too\n\nV0.5 All Kind of Formatting corrected and building some colors in output.\n     15-04-94\n\nFuture Planings:\n\nI planned to do some more Modules for /X 2.xx and of course /X 3.xx.But they\nall would be XIM-Modules.\nThere Would be:\n               - A new Time Door\n               - A new Wall\n               - A cool Calling-Card-Registrater\n               - and some more Tools\n\nEnjoy the waiting!!!!\n\nGreetings:\nOK Greetings are going to Zacke/Sceptic and Mr.Vain/Sceptic.\n\nSuggestions:\n\nOk If you have any Suggestions to do please leave me a Messy on a Board of\nthe folowing ones:\n	BAD RELIOGION +49-04638-8306\n        DEAD LINE     +40-0461-ELITE\n','\n',char(10)),NULL,'auto-added',49829,3,0,NULL,NULL,'piw_st05','scan',1780048671);
INSERT INTO door_catalog VALUES('plchk13','PLCHK13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PLCHK13.LHA','PrO-LhAcHeCk','XIM','PrO-LhAcHeCk',NULL,NULL,NULL,'/   .   \___    __!__    ___/   o.V.E.R | /    !    \/      \:/      \     t.H.E   ! \_________/\______/:\______/     t.O.P.! |',replace('  _________________.__________           :  \n /   .   \___    __!__    ___/   o.V.E.R |  \n/    !    \/      \:/      \     t.H.E   !  \n\_________/\______/:\______/     t.O.P.! |  \n                  EL?`--------->   <-------''\n               PrEsEnTs                     \n           PrO-LhAcHeCK 1.3                 \nNow 68000, and multi-node compatible!!      \n','\n',char(10)),'PrO-LhAcHeCk.Guide',replace('@database PrO-LhAcHeCk.guide\n@$VER: PrO-LhAcHeCk.guide v1.3 (03-Jul-94)\n\n@node MAIN "PrO-LhAcHeCk Contents"\n                      @{b}@{u}Documents for PrO-LhAcHeCk v1.3@{ub}@{uu}\n\n          PrO-LhAcHeCk was written by Exodous/TlS, XpR and O.T.T\n                           Released on 03-Jul-94\n\n                      1)  @{" What is PrO-LhAcHeCk ? " link WHAT_IS_PLC}\n                      2)  @{" Installation           " link INSTALLATION}\n                      3)  @{" WARNING                " link WARNING}\n                      3)  @{" Distribution           " link DISTRIBUTION}\n                      4)  @{" Registration Info      " link REGISTRATION}\n                      4)  @{" Greetings              " link GREETINGS}\n                      5)  @{" Contacting me          " link CONTACTING_ME}\n                      6)  @{" Call These BBS''s       " link BBS_ADS}\n                      7)  @{" History                " link HISTORY}\n                      8)  @{" Other programs         " link OTHER_PROGS}\n\n                PrO-LhAcHeCk was written in 100% assembler.\n@endnode\n\n@node WHAT_IS_PLC "What is PrO-LhAcHeCk"\n                     @{u}What is PrO-LhAcHeCk ?@{uu}\n\nPrO-LhAcHeCk is a LHA file checker meant to be run from a BBS when an\nLHA, LZH, LZA or SFX file has been uploaded.\n\nIt allows other BBS adverts to be stripped from the file, and your own\nBBS adverts can be added to advertise your BBS.\n\nPrO-LhAcHeCk was written in 680x0 assembler using Devpac 3 from HiSoft.\n\nPrO-LhAcHeCk needs kickstart 2.0 or better installed on your Amiga in\norder for it to run, if there is enough need (ie at least 10 people\nwanting it) then I''ll do a 1.3 compatible version.\n\n@endnode\n\n@node INSTALLATION "How to install PrO-LhAcHeCk"\n                    @{u}Installation instructions@{uu}\n\n@{b}NOTE :@{ub} You will need LHa (by Stefan Boberg)\n\nLHa can be installed in the C: directory (as @{i}C:LHa@{ui}) or :\n\nPut the @{b}LHa@{ub} executable anywhere and do either of the following :\n\n @{b}o@{ub} Add the following line to the @{b}S:User-Startup@{ub} file\n\n              SetEnv PDC=<path and name of LHa>\n           eg @{i}SetEnv PDC=Work:Utilities/LHa@{ui}\n\n @{b}o@{ub} Type the following at the CLI, wait a few seconds then\n   reboot your Amiga.\n\n              Echo >ENVARC:PDC "<path and name of LHa>"\n           eg @{i}Echo >ENVARC:PDC "Work:Utilities/LHa"@{ui}\n\n@{u}Installation for normal command line usage@{uu}\n\nCopy @{b}PrO-LhAcHeCk@{ub} to anywhere in your path (usually C:).\n\n@{u}Installation for Ami-Express BBS usage@{uu}\n\nLoad Workbench and double click on the ''@{b}Install_PLC@{ub}'' icon, or\nopen a shell and type ''@{b}execute Install_PLC@{ub}''\n\nAdd BBS''s adverts that @{b}PrO-LhAcHeCk@{ub} doesn''t strip to the file\n @{b}S:PDC.Strip@{ub}, by editing it with your favourite editor.\n\nEdit the files @{b}S:PLC/#?@{ub} to suit your own BBS.\n\nNow when an LHA file is uploaded it will be automatically checked for\nintegrity, existing BBS adverts will be killed and your BBS adverts\nwill be added by PrO-LhAcHeCk.\n\n@{b}IMPORTANT : DON''T PACK LHa... see @{"WARNING" link WARNING}@{ub}\n\n                     @{u}For the @{b}REGISTERED@{ub} versions @{b}ONLY@{ub}@{uu}\n\nAll files that are added will have the date and time of upload, and your\nBBS number added as their comment.\n\n@{b}Also@{ub} all file names that start as @{b}PLC@{ub} will be give a random\nnumber instead of PLC so that it is very difficult to strip them from the\nfile automatically.\n\n    eg if a file called @{i}PLC.txt@{ui} exists then on one occurance it\n       could be called @{i}256133.txt@{ui}, on the next occurance something\n       totally different like @{i}725531.txt@{ui}.\n\nPLC will strip all files listed @{b}S:PLC.Strip@{ub} along with the 1200 or so\nthat it already knows.\n\n@endnode\n\n@node WARNING "This is a warning that WILL be repeated"\n               @{u}This is a warning that @{b}WILL@{ub} be repeated@{uu}\n\nPlease make sure that your LHa executable file (C:LHa) is @{b}NOT@{ub} crunched\nwith anything as this will call PrO-LhAcHeCk to crash....\n\nI could make PrO-LhAcHeCk work with crunched LHa''s BUT it would be at\nleast 3 times slower..\n@endnode\n\n@node DISTRIBUTION "Distribution restrictions"\n                  @{u}Distribution of PrO-LhAcHeCk@{uu}\n\nPrO-LhAcHeCk is (c)1994 TLS and may be distributed in any way as long as\n the following conditions are met :\n\n  @{b}o@{ub}  All of the files are included, unchanged.\n  @{b}o@{ub}  No money changes hands (ie @{b}NO@{ub} PD library distribution)\n\n@{b}NOTE :@{ub} It is @{b}ILLEGAL@{ub} to distribute the registered versions.\n\n@endnode\n\n@node REGISTRATION "Registration information"\n                         @{u}Registration information@{uu}\n\n@{u}Why register???@{uu}\n\nIf you register you will get :\n\n @{b}o@{ub} A personal version of PrO-LhAcHeCk\n @{b}o@{ub} Your BBS number, date and time of upload appears on the file\n   comments of the adverts that are added to the LHa files.\n @{b}o@{ub} Adverts that are added can be given a random number to make them\n   a lot harder to strip.\n @{b}o@{ub} Adverts that PLC doesn''t strip can be added to the file @{b}S:PLC.Strip@{ub}\n   so that it will strip them.\n @{b}o@{ub} At least one update to PrO-LhAcHeCk\n @{b}o@{ub} A disk containing unregistered versions of my other Ami-Express doors,\n   along with the registered version of PrO-LhAcHeCk\n\n\n@{u}How much is it to register ?@{uu}\n\nRegistration is £5.00 (Five UK pounds)\n\n@{u}How do I register then ?@{uu}\n\nPrint out (or write by hand) the file ''@{i}Register.doc@{ui}'' and mail it to me\n(see @{"contacting me" link CONTACTING_ME}), along with the 5 pounds in @{b}CASH@{ub}, and you will recieve\nthe latest registered version via return of post.... if your BBS is in\nthe UK then I will personally call and upload the latest version.\n@endnode\n\n@node GREETINGS "Greetings"\n\nGreetings to the following people :\n\n    @{b}Oll¿e@{ub} - Hope the editor''s coming on well, I''ll start the assembler\n             in a few days when BootUte 2''s done.\n    @{b}M¿sta Are@{ub}\n    @{b}Mike@{ub}\n\nGreets, and thanks for registering go to these cool guyz :\n\n    @{b}Grasshopper@{ub}\n    @{b}Fireflash@{ub} - I''ll make a start on Pro-MultiCheck soon.\n    @{b}Sonny@{ub} - Hey, it now works on a 68000!!\n\nAll members of @{b}TLS@{ub}, @{b}Xpress@{ub} and @{b}O.T.T@{ub}.\n@endnode\n\n@node CONTACTING_ME "How to contact me"\n                          @{u}How to contact me@{uu}\n\nI can be contacted via E-Mail on the following BBS''s as ''Exodous'' :\n\n @{"Q.E.D" link BBS_ADS}\n @{"The Tower" link BBS_ADS}\n @{"Welsh Coast" link BBS_ADS}\n\nor via internet :\n\n  [email removed]\n\nNormal mail (coders and registrations only please) :\n\n  Paul              <--- please use ''Paul'', @{b}NOT@{ub} ''Exodous''.\n  1 Sherrard Drive\n  Loughborough\n  Leics\n  LE12 7SG\n\nI am interested in contacting other coders so that we can exchange ideas,\nalgorithms etc., NO source code swapping... so that rules out lamers who\njust want my source code.\n\nPlease note @{b}NO PROGRAM SWAPPERS@{ub}, I am not interested in swapping programs,\nso if I recieve any disks with file lists etc. then the lists will be\nbinned, and the disks will be used to send the registered versions out on.\n(ie there is a high chance... @{b}100%@{ub} that you won''t see your disk ever again)\n\n@endnode\n\n@node BBS_ADS "Call these BBS''s"\n                      @{u}Call these Xpress BBS''s@{uu}\n\n@{b}Q.E.D@{ub} (WHQ)         : +44 (0)91-372-1911 (2 Nodes) - @{b}GRASSHOPPER@{ub}.\n\n@{b}SLEEZY BBS@{ub} (UKHQ)   : +44 (0)422-367-163 (1 Node)  - @{b}BONEIDLE@{ub}.\n\n@{b}MEDUSA DOMAIN@{ub} (CHQ) : +1 905-574-7791    (6 Nodes) - @{b}MEDUSA@{ub}.\n\n@{b}BIO HAZARD@{ub} (CHQ)    : +1 905-841-0965    (3 Nodes) - @{b}KAPT. KAOS@{ub}.\n\n@{b}THE LAB@{ub} (CHQ)       : +1 514-745-7420    (3 Nodes) - @{b}P.R SINISTER@{ub}.\n\n@{b}WAREZ DEPOT@{ub} (USHQ)  : +1 305-819-9925    (3 Nodes) - @{b}AMIGAMAN@{ub}.\n\n                          @{u}Call these other BBS''s@{uu}\n\n@{b}THE TOWER@{ub}           : +44 (0)204-384-453 (2 Nodes) - @{b}FIREFLASH@{ub}.\n                      +44 (0)204-371-868\n\n@{b}WELSH COAST@{ub}         : +44 (0)792-586-225 (1 Node)  - @{b}SONNY@{ub}.\n\n@endnode\n\n@node HISTORY "The history of PrO-LhAcHeCk"\n                     @{u}History of PrO-LhAcHeCk@{uu}\n\n| Ver   | Date          | Comment\n+-------+---------------+--------------------------------------------\n| 1.0   | 15-Jun-94     | First version.\n+-------+---------------+--------------------------------------------\n| 1.1   | 18-Jun-94     | Fixed a bug that caused adverts not to be\n|       |               | added to the LHa archive.\n+-------+---------------+--------------------------------------------\n| 1.2   | 21-Jun-94     | Added a few more adverts for PLC to strip.\n|       |               | Added ability to strip files listed in\n|       |               |  S:PLC.Strip\n+-------+---------------+--------------------------------------------\n| 1.3   | 03-Jul-94     | Now kickstart 2.0 only, 68000 compatible,\n|       |               | and can be run on multi-node BBS''s\n+-------+---------------+--------------------------------------------\n@endnode\n\n@node OTHER_PROGS "Other programs that I have written"\n         @{u}Here is a list of other programs that I have written@{uu}\n\n@{b}BootUte@{ub}        : Degrader type utility for @{i}newer@{ui} Amiga''s....\n                 Needs Kickstart 2.0+. Features easy to use gadtools\n                 interface.\n\n@{b}BullRead@{ub}       : Bulletins door for /X that allows users to search\n                 bulletins while they are on-line, or download the bulletins\n                 for viewing whilst off-line.\n\n@{b}X-Zippy@{ub}        : Replacement zippy search door for /X that can search\n                 for multiple items at a time, about 3 times faster\n                 than the built in zippy!!\n\n@{b}UserCom@{ub}        : Door for /X that allows users to make comments to files\n                 so that others will know if the file is old, fake etc.\n\n@{b}PrO-DmScHeCk@{ub}   : DMS file checker - for user with most BBS systems.\n                 Strips and adds front, rear and track texts.\n\n@{b}PrO-LhAcHeCk@{ub}   : LHa file checker - for user with most BBS systems.\n                 Strips most other adverts and adds own adverts that are\n                 virtually unstrippable.\n\n@{b}PrO-LogInfo@{ub}    : An Ami-Express door to inform on-line users when another\n                 user logs on to, or off from, another node.\n\n@{b}Decrunch@{ub}       : CLI based decruncher to decrunch loads of different\n                 packed files.\n\n@{b}PPPatch@{ub}        : PowerPacker Patcher... Patches the headers of PowerPacked\n                 files so that they can''t be decrunched.\n\n@{u}Projects I''m working on@{uu}\n\n@{b}BootUte 2@{ub}      : Updated version of BootUte.\n\n@{b}EBBS@{ub}           : En¿gma Bulletin Board System\n                 My own host BBS, written entirely in Assembler with loads\n                 of features : Kickstart 2.0+ only.\n\n@{b}PrO-MuLtIcHeCk@{ub} : Multiple file checker for most BBS systems, will\n                 incorporate PrO-DmScHeCk and PrO-LhAcHeCk, along with a\n                 text checker/adder.\n\n@{b}PrO-NewScan@{ub}    : Ami-Express new file scanner, like Turbo-NewScan,\n                 only faster!!\n\n@{b}PrO-NewUser@{ub}    : Ami-Express new user questionnaire door that doesn''t\n                 let new users skip questions, they have to insert something\n                 ''intelligent'', eg phone numbers can only have certain\n                 characters in them..\n\n@{b}<xxxx>Asm@{ub}      : 680x0 assembler with loads of features.\n                 The assembler is going to be written by me, and Oll¿e is\n                 writing a cool editor for it, with some excellent features.\n                 (note <xxxx>Asm as I have thought of a name, yet!)\n\nIf you have any suggestions for features that you would like to see in\nany of the programs then e-mail me with your suggestions.\n\n@endnode\n','\n',char(10)),NULL,'auto-added',22638,7,0,NULL,NULL,'plchk13','scan',1780048671);
INSERT INTO door_catalog VALUES('plha_chk','PLHA_CHK.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PLHA_CHK.LHA','PrO-LhAcHeCk','XIM','PrO-LhAcHeCk',NULL,NULL,'PLHA','\:::::::/  / \\____  \____  \:::::::::::\ \:::::/-   _//  ____/  _   /\:::::::::::\ \:::/__/  //_  /\_/_  /\  \/:::XPRESS:::\',replace('_________/\__ __________________________\n\:::::::/  / \\____  \____  \:::::::::::\\n \:::::/-   _//  ____/  _   /\:::::::::::\\n  \:::/__/  //_  /\_/_  /\  \/:::XPRESS:::\\n  /:::\_/__/ \_\/ /:\_\/ /\  \::PRESENTS::/\n /::::::\__\/:::\/GH''94\/::\__>::::::::::/\n/:::::::::::::::::::::::::::::::::::::::/\n -== PrO-LhAcHeCk v1.0 - LHA checker ==-\n -==   Fastest LHA checker around    ==-\n::----------- : : MEN-TEL BBS : :---------::\n','\n',char(10)),'PrO-LhAcHeCk.Guide',replace('@database PrO-LhAcHeCk.guide\n@$VER: PrO-LhAcHeCk.guide v1.0 (15-Jun-94)\n\n@node MAIN "PrO-LhAcHeCk Contents"\n            @{b}@{u}Documents for PrO-LhAcHeCk v1.0@{ub}@{uu}\n\n             PrO-LhAcHeCk was written by Exodous/TLS & XPress\n                           Released on 15-Jun-94\n\n                      1)  @{" What is PrO-LhAcHeCk ? " link WHAT_IS_PLC}\n                      2)  @{" Installation           " link INSTALLATION}\n                      3)  @{" Distribution           " link DISTRIBUTION}\n                      4)  @{" Greetings              " link GREETINGS}\n                      5)  @{" Contacting me          " link CONTACTING_ME}\n                      6)  @{" Call These BBS''s       " link BBS_ADS}\n                      7)  @{" History                " link HISTORY}\n                      8)  @{" Other programs         " link OTHER_PROGS}\n\n                PrO-LhAcHeCk was written in 100% assembler.\n@endnode\n\n@node WHAT_IS_PLC "What is PrO-LhAcHeCk"\n                     @{u}What is PrO-LhAcHeCk ?@{uu}\n\nPrO-LhAcHeCk is a LHA file checker meant to be run from a BBS when an\nLHA, LZH, LZA or SFX file has been uploaded.\n\nIt allows other BBS adverts to be stripped from the file, and your own\nBBS adverts can be added to advertise your BBS.\n\nPrO-LhAcHeCk was originally written for @{"THE TOWER" link BBS_ADS}, and was written\nin 680x0 assembler using Devpac 3 from HiSoft.\n\n@endnode\n\n@node INSTALLATION "How to install PrO-LhAcHeCk"\n                    @{u}Installation instructions@{uu}\n\n@{b}NOTE :@{ub} You will need LhA (by Stefan Boberg), and depending on your\n       operating system depends on where it needs to be installed.\n\n@{u}LhA on 1.2+@{uu}\nThe @{b}LhA@{ub} executable must be called @{b}LhA@{ub} and reside in the @{b}C:@{ub}\ndirectory\n\n@{u}LhA on 2.0+@{uu}\nLhA can be installed as 1.2+ or :\n\nPut the @{b}LhA@{ub} executable anywhere and do either of the following :\n\n @{b}o@{ub} Add the following line to the @{b}S:User-Startup@{ub} file\n\n              SetEnv PDC=<path and name of LhA>\n           eg @{i}SetEnv PDC=Work:Utilities/LhA@{ui}\n\n @{b}o@{ub} Type the following at the CLI, then wait a few seconds then\n            reboot your Amiga.\n\n              Echo >ENVARC:PDC "<path and name of LhA>"\n           eg @{i}Echo >ENVARC:PDC "Work:Utilities/LhA"@{ui}\n\n@{u}Installation for normal command line usage@{uu}\n\nCopy @{b}Utils/PrO-LhAcHeCk@{ub} to anywhere in your path (usually C:).\n\n@{u}Installation for Ami-Express BBS usage@{uu}\n\nCopy @{b}Utils/PrO-LhAcHeCk@{ub} to @{b}BBS:Utils/PrO-LhAcHeCk@{ub}\nCopy @{b}FCheck/LHA.info@{ub} to @{b}BBS:FCheck/LHA.info@{ub}\nCopy @{b}FCheck/LZH.info@{ub} to @{b}BBS:FCheck/LZH.info@{ub}\nCopy @{b}FCheck/LZA.info@{ub} to @{b}BBS:FCheck/LZA.info@{ub}\nCopy @{b}FCheck/SFX.info@{ub} to @{b}BBS:FCheck/SFX.info@{ub}\nCopy @{b}S/PLC/#?@{ub} to @{b}S:PLC/#?@{ub}\n\nEdit the files @{b}S:PLC/#?@{ub}\n\n to suit your own BBS.\n\n@{b}NOTE :@{ub} All files that are added will have the date and time of\n       upload added as their comment.\n\n       @{b}Also@{ub} all files that start as @{b}PLC@{ub} will be give a random\n       number instead of PLC so that it is very difficult to strip them\n       from the file automatically.\n\n    eg if a file called @{i}PLC.txt@{ui} exists then on one occurance it\n       could be called @{i}256133.txt@{ui}, on the next occurance something\n       totally different like @{i}725531.txt@{ui}.\n\nNow when an LHA file is uploaded it will be automatically checked for\nintegrity, existing BBS adverts will be killed and your BBS adverts\nwill be added by PrO-LhAcHeCk.\n@endnode\n\n@node DISTRIBUTION "Distribution restrictions"\n                  @{u}Distribution of PrO-LhAcHeCk@{uu}\n\nPrO-LhAcHeCk is (c)1994 Exodous/TLS & XPR and may be distributed in any\nway as long as the following conditions are met :\n\n  @{b}o@{ub}  All of the files are included, unchanged.\n  @{b}o@{ub}  No money changes hands (ie @{b}NO@{ub} PD library distribution)\n\n@endnode\n\n@node GREETINGS "Greetings"\n\nGreetings to the following people :\n\n    @{b}Oll¿e@{ub}\n    @{b}GrassHopper@{ub}\n    @{b}FireFlash@{ub}\n    @{b}M¿sta Are@{ub}\n    @{b}Mike@{ub}\n\nAll members of @{b}TLS@{ub} and @{b}XPress@{ub}.\n@endnode\n\n@node CONTACTING_ME "How to contact me"\n                          @{u}How to contact me@{uu}\n\nI can be contacted via E-Mail in the following ways :\n\n @{"Q.E.D" link BBS_ADS}     : Exodous\n @{"The Tower" link BBS_ADS} : Exodous\n\n Internet :\n\n  [email removed]      (If this address bounces then use the next one)\n  [email removed]\n@endnode\n\n@node BBS_ADS "Call these BBS''s"\n                  @{u}Call these great XPress BBS''s@{uu}\n\n@{b}Q.E.D@{ub} (WHQ)         : +44 (0)91-372-1911 (2 Nodes) - @{b}GRASSHOPPER@{ub}.\n\n@{b}SLEEZY BBS@{ub} (UKHQ)   : +44 (0)422-367-163 (1 Node)  - @{b}BONEIDLE@{ub}.\n\n@{b}MEDUSA DOMAIN@{ub} (CHQ) : +1 905-574-7791    (6 Nodes) - @{b}MEDUSA@{ub}.\n\n@{b}BIO HAZARD@{ub} (CHQ)    : +1 905-841-0965    (3 Nodes) - @{b}KAPT. KAOS@{ub}.\n\n@{b}THE LAB@{ub} (CHQ)       : +1 514-745-7420    (3 Nodes) - @{b}P.R SINISTER@{ub}.\n\n@{b}WAREZ DEPOT@{ub} (USHQ)  : +1 305-819-9925    (3 Nodes) - @{b}AMIGAMAN@{ub}.\n\n                  @{u}Call these other great BBS''s@{uu}\n\n@{b}THE TOWER@{ub} (LsD UKHQ): +44 (0)204-384-453 (2 Nodes) - @{b}FIREFLASH@{ub}.\n                      +44 (0)204-371-868\n\n@endnode\n\n@node HISTORY "The history of PrO-LhAcHeCk"\n                     @{u}History of PrO-LhAcHeCk@{uu}\n\n| Ver   | Date          | Comment\n+-------+---------------+--------------------------------------------\n| 1.0   | 15-Jun-94     | First version.\n+-------+---------------+--------------------------------------------\n@endnode\n\n@node OTHER_PROGS "Other programs that I have written"\n         @{u}Here is a list of other programs that I have written@{uu}\n\n@{b}BootUte@{ub}      : Degrader type utility for @{i}newer@{ui} Amiga''s....\n               Needs Kickstart 2.0+. Features easy to use gadtools\n               interface.\n\n@{b}BullRead@{ub}     : Bulletins door for /X that allows users to search\n               bulletins while they are on-line, or download the bulletins\n               for viewing whilst off-line.\n\n@{b}X-Zippy@{ub}      : Replacement zippy search door for /X that can search\n               for multiple items at a time, about 3 times faster\n               than the built in zippy!!\n\n@{b}UserCom@{ub}      : Door for /X that allows users to make comments to files\n               so that others will know if the file is old, fake etc.\n\n@{b}PrO-DmScHeCk@{ub} : DMS file checker - for user with most BBS systems.\n               Strips and adds front, rear and track texts.\n\n@{b}Decrunch@{ub}     : CLI based decruncher to decrunch loads of different\n               packed files.\n\n@{b}PPPatch@{ub}      : PowerPacker Patcher... Patches the headers of PowerPacked\n               files so that they can''t be decrunched.\n\n@{u}Projects I''m working on@{uu}\n\n@{b}EBBS@{ub}         : En¿gma Bulletin Board System\n               My own host BBS, written entirely in Assembler with loads\n               of features : Kickstart 2.0+ only.\n\n@{b}xxxx-NuKe@{ub}    : Program similar to Boss-Nuke (for /X) that allows files\n               to be nuked, givent extra credits etc., will run from /X\n               as a door, or from the CLI/WB and display a user interface\n               (Kickstart 2.0+ only)\n\n@{b}GFC@{ub}          : Graphics Format Converter\n               A great graphics converter for loads of different formats...\n               (Kickstart 2.0+ only)\n\n@{b}Shell Menu@{ub}   :\n               A program similar to Tools-Daemon and the like, but to\n               add menu''s to the Shell window.\n\n@{b}E-Dos@{ub}        : Enigma-DOS\n               Replacement floppy-disk filing system with in-line\n               encryption for transferring/storing private information.\n\n\nIf you have any suggestions for features that you would like to see in\nany of the programs then e-mail me with your suggestions.\n\n@endnode\n','\n',char(10)),NULL,'auto-added',17004,7,0,NULL,NULL,'plha_chk','scan',1780048671);
INSERT INTO door_catalog VALUES('pltrej02','PLTREJ02.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PLTREJ02.LHA','PlutReject','XIM','PlutReject',NULL,NULL,NULL,NULL,replace('Lets TrapDoor skip an incoming file.\n','\n',char(10)),'PlutReject.doc',replace('            ------------------------------------------------\n\n                               PlutReject\n\n          Utility to bypass receiving a file you already have\n\n                       by Peter Deane (3:622/401)\n\n                      Version 0.2 16 October 1994\n\n                           in GFA BASIC V3.51\n\n            ------------------------------------------------\n\n\n                              Introduction\n                              ============\n\n\nIn the TRAPDOOR support echo, Mike Hall asked this question:\n\n MH> I''ve got a few file echo''s set up and manually poll for a some of\n MH> them, sometimes I''ve already got the files and so am wondering is\n MH> there a way to skip the current transfer and not abort the whole\n MH> trapdoor session?  It''s painful when calling STD watching a 500k\n MH> file come in when you''ve allready got it!  :8-/\n\n\nGood point, I thought, and supplied Mike with this answer:\n\n\n PD> Hey, it''s even worse polling INTERNATIONALLY and having this happen\n PD> as well!\n\n PD> But there IS something you can do about it.  Sit down while I tell you a\n PD> tale of partial files and resuming transfers....\n\n PD> When TrapDoor receives a partial file it renames it.  The filenaming\n PD> scheme used is:\n\n PD>  !.Filename.A.B.C.D\n\n PD> Where "Filename" is the original filename of the file and A.B.C.D\n PD> is the address of the system sending you that file.\n\n PD> For example if you were receiving a file called Foo.lha, from\n PD> 3:622/401 (me) and it was aborted halfway through for some reason\n PD> the filename of the partial file would be:\n\n PD>  !.Foo.lha.3.622.401.0\n\n PD> This partial file would ALSO contain a filenote.  This consists of\n PD> three parts terminated by a semicolon:\n\n PD>  Length 123456; FileName Foo.lha; Time d17089c8;\n\n PD> Okay, so using this information we can fool TrapDoor into resuming\n PD> a file transfer at ANY stage.  What we want to do is for it to\n PD> resume at an offset equal to the length of the file.\n\n PD> Let''s assume we have received a file called TD_1_84.lha from a\n PD> system, and now ANOTHER system is also trying to send us that file,\n PD> which we don''t want.  Let''s also assume the filesize is 300,000\n PD> bytes long, and the address of the system now trying to send it to\n PD> us is 1:234/567.8.\n\n PD> When the other end starts to send us the file, we hangup.  Okay\n PD> what you need to do now is copy the _original_ file into your\n PD> inbound directory.  Use a copy so you can delete it later.  The\n PD> file has to be exactly the right length, BTW\n\n PD> Firstly we rename this temporary file using the above convention:\n\n PD>  Rename TD_1_84.lha as !.TD_1_84.lha.1.234.567.8\n\n PD> Then we need to set the filenote.  We only need the Length and\n PD> Filename fields, the time isn''t necessary.\n\n PD> FileNote !.TD_1_84.lha.1.234.567.8 "Length 300000; FileName TD_1_84.lha; "\n\n PD> And with that in the inbound directory we call back.\n\n PD> The result will be "Resuming Transfer from Offset 300000", and\n PD> since 300000 is the actual size of the file, 0 bytes of it will be\n PD> transferred and then the system will send you the next file it has\n PD> for you.\n\n PD> Since the system thinks it has succesfully sent you the file, it\n PD> shouldn''t try sending it again (if it was a TrapDoor, a tilde would\n PD> be prepended to the filename in the FLO file).\n\n PD> Regards,\n PD> -Peter!\n\n PD> PS:  TrapDoor will rename our temporary file in inbound to the\n PD> correct name doing this, BTW!  :-)\n\n\nThe answer was well received except for one small point:  it''s a bit\ncomplicated, isn''t it?  Well, I couldn''t argue with that.  Andy McArdle\nsuggested that this would be a candidate for a Plutonic utility.\n\nAnd so was born PlutReject, a small utility to take a lot of the hard\nwork out of the above steps, but still resulting in a renamed file in\nthe inbound directory with the relevant FileNote to enable TrapDoor to\nresume transfer at the offset equal to the length of the file - in\neffect "cancelling" the incoming file.\n\n\n                            Using PlutReject\n                            ================\n\nTo save PlutReject a bit of work, the first thing you need to do is to\nput a copy of the file you don''t want into the inbound directory.\n\nSince the file is going to be safe, if you''re running short of\ndrivespace you can use your only copy if you like, and then move it back\nto where it belongs later.  Alternatively, use a copy in the inbound,\nand then you can delete it from there when the transfer is finished.\n\nOnce the file is in the inbound, you need to run PlutReject and tell\nPlutReject two things:\n\nFirstly the full path and filename of the file.  (EG\nMAIL:Inbound/NodeDiff.L87).  If you CD to the inbound directory before\nrunning PlutReject, then just the filename itself will suffice (ie\nNodeDiff.L87).  You can use an assignment as well (eg IN:NodeDiff.L87)\n\nPlutReject will complain if it can''t find this file, and exit.\n\nSecondly you need to tell PlutReject the node number of the system\nsending you the file.  If this is in zone 3, you may omit the zone.  If\nthis is a point zero (ie a BBS, not a point), you can omit the point\nnumber.  So, to PlutReject these numbers mean the same thing:\n3:622/401.0, 3:622/401, 622/401 and 622/401.0\n\nThis number has to be the PRIMARY address of the system sending you the\nfile - !NOT! one of the system''s AKAs.  You could be in for a shock if\nthe system is on a rotary group for instance and presents a different\nprimary node number on your next call.  Unfortunately there''s not much\nwe can do about that...\n\nThe node number must be in a valid fido node number format.  If not,\nPlutReject will complain and again, exit.\n\n[Don''t forget you MUST specify the zone if it''s not in Zone 3]\n\nThe file you are receiving must match exactly with the length of the\nfile you already have.  If it''s out by as much as 1 byte, TrapDoor will\nthink this is a different file, and PlutReject won''t work as you expect\nit.  You could always adjust the length of the dummy file you have to\nmatch what the system is sending you if this causes a problem.  In this\ncase, I''d recommend the dummy file in your inbound is a COPY of the\noriginal file :-)\n\nAlso, this will only work if the other end supports transfer resuming\n(virtually ALL systems do these days under a Zmodem derivative, eg\nZedZap, TrapZap, etc)\n\n\n                                Examples\n                                ========\n\n1.> PlutReject Mail:Inbound/NodeDiff.L87 3:711/501\n\n1.> PlutReject IN:NodeDiff.L87 711/501\n\n1.> CD Mail:Inbound\n1.> PlutReject NodeDiff.L87 3:711/501.0\n\n\n\n                                Test Run\n                                ========\n\nTo test this out, I sent away a freq for a NodeDiff I already have.\nFirstly I used a directory utility to whip a copy over into the inbound.\n\nI then ran PlutReject using one of the above examples, and called\n3:711/501.  The TrapDoor log went like so (I sent and picked up a bit of\nmail during this test call, but I''ve cut out those lines):\n\n\n+ 16-Oct-94 15:12:42  Calling Sentry''s Shadow (3:711/501.0)\n~ 16-Oct-94 15:13:05  CONNECT 12000/REL\n: 16-Oct-94 15:13:18   Name: Sentry''s Shadow (3:711/501.0)\n: 16-Oct-94 15:13:18  Sysop: Trev Roydhouse\n: 16-Oct-94 15:13:18  Using: BinkleyTerm 2.59\n: 16-Oct-94 15:13:18  Offer: WaZoo FReqs ZedZap ArcMail \n: 16-Oct-94 15:13:19  TrxID: 2ea14302\n* 16-Oct-94 15:13:19  Password-protected session\n= 16-Oct-94 15:13:19  Protocol: WaZoo/ZedZap\n\n| 16-Oct-94 15:13:31  Sending 02c701f5.req (14 bytes)\n| 16-Oct-94 15:13:32  Took 0:00, Cps: 23, Efficiency: 1%\n| 16-Oct-94 15:13:32  Sent 02c701f5.req (14 bytes) successful\n\n| 16-Oct-94 15:15:30  Receiving nodediff.l87 (65245 bytes)\n| 16-Oct-94 15:15:30  Resuming transfer from offset 65245\n| 16-Oct-94 15:15:31  Took 0:00, Cps: 0, Efficiency: 0%\n| 16-Oct-94 15:15:31  Received nodediff.l87 (65245 bytes) successful\n\n= 16-Oct-94 15:15:42  Session connect time 2:36, cost 0.31\n~ 16-Oct-94 15:15:42  Hanging up modem\n\n\nSo as you can see, rather than taking some time to receive the file,\nthis takes only 1 second, saving a substantial amount of transfer time\nreceiving a file you already have!\n\n\n                              Limitations\n                              ===========\n\nThis will NOT work if the file you are receiving has spaces in it.  DO\nNOT USE INVERTED COMMAS in the arguments - we don''t parse them at all.\n\n\n                                Remember\n                                ========\n\nThe dummy file in your inbound directory will be renamed back to the\nproper filename after TrapDoor calls back.  Don''t forget to clean the\ndirectory up by copying the file back to where it belongs or deleting\nit.\n\n\n                       Distribution and Politics\n                       =========================\n\nThe PlutReject archive currently consists of these files:\n\n        PlutReject                Executable\n        PlutReject.doc            This file\n        PlutReject.lst            GFABASIC Source (ascii)\n\nIt may NEVER be distributed without all the above files being present in\nthe distribution copy.  No charge over and above a small copying fee may\never be levied on the distribution of the program.\n\nAll copyrights are retained by the author.  If you use any part of the\nsource in other programs, acknowledgement must be given.\n\nThe liability of the author for any damages caused by this program is\nlimited to the amount the user has paid directly to the author for the\nright to use the software (ie nil). Claims for amounts greater than this\nwill be refused.\n\nThe author can be contacted:\n\nPeter Deane\n\nFidoNet:   3:622/401        Postal: PO Box 228\nGlobalNet: 54:6101/401              Swansea  NSW  2281\nAmigaNet:  41:200/401               AUSTRALIA\n\nBBS:    from O/S   +61-49-72-1647\n(24hrs) from Aust  (049) 72-1647\n\n            ------------------------------------------------\n\n','\n',char(10)),NULL,'auto-added',19642,2,0,NULL,NULL,'pltrej02','scan',1780048671);
INSERT INTO door_catalog VALUES('pod_bbsb','POD-BBSB.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/POD-BBSB.LHA','BBSBcs','XIM','BBSBcs',NULL,NULL,'POD','the TRUE Logfileanalyzer  V0.01a',replace('BBSBasics\nthe TRUE Logfileanalyzer  V0.01a\n','\n',char(10)),'BBSBcs.doc',replace('=============================================================================\n=============================================================================\n== BBSBasics -- the TRUE Logfileanalyzer  V0.01a Thu Jan 13 17:21:17 1994 ===\n=============================================================================\n=============================================================================\n\nFor more convinience this document should be read from top to bottom.\n\nThis is an updated document (see history, changes) for new options.\nBBSbcs is growing, young, strong, upcoming and under development.\n\nWhy another blood` damn Express util ?\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nI`ve seen so many (so called) stat-tools for LightSpeed Technology`s AmiExpress\nBBS, so I decided to write my own - a fast and easy to handle logfileanalyzer.\n\nLet`s get to the real thing:\n~~~~~~~~~~~~~~~~~~~~~~~~~~~\nCall BBSbcs via the commandline with the Path/Name of the logfiles.\n\nDo something like this:\n~~~~~~~~~~~~~~~~~~~~~~~\nBBSbcs bbs:node1/callerslog bbs:node2/callerslog bbs:node3/callerslog etc.\n\nWithout any parameter, BBSbcs will display:\n\n/X Bulletin Basics\n\n   by Satori - 100 % Backdoor free /X Software\n   Give us a rrrrrring at Placebo Effect for improvments.\n\n   Usage:\n   BBSbcs Logfile <Logfile> <Logfile> <Logfile> etc.\n\n   Have a nice Day...\n\n...or something similiar.\n\n\nThis is what you get:\n~~~~~~~~~~~~~~~~~~~~~\n                   +------------------------+\n                   | /X BBS Bulletin Basics |\n+------------------+------------------------+------------------+\n|   10 Connections at  2400 BPS | Operator paged   136 times   |\n|    7 Connections at  4800 BPS | Carrier lost      61 times   |\n|    7 Connections at  9600 BPS | Normal logoff    291 times   |\n|   14 Connections at 12000 BPS | Download total   214 files   |\n|  183 Connections at 14400 BPS | Upload total     117 files   |\n|   81 Connections at 16800 BPS | Zoom Downloads     8 times   |\n|   24 Connections at 19200 BPS | Password fails    26 times   |\n+-------------------------------+------------------------------+\n| Placebo Effect BBS Production | Idea/Codez/Art (C)`94 Satori |\n+--------------------------------------------------------------+\n\n...or something similiar.\n\nSimple eh`?\n\nFamous last note:\n~~~~~~~~~~~~~~~~~\nIn this version BBSbcs will not write any file or Bulletin. If you \nwanna get some `stored` information, do it like `dis:\n\nBBSbcs >[your file] [logfile] [optional logfiles] []\n\nThis stores the statistical information in the file that you want.\n\nIf you have something to improve, give me rrrrrring at Placebo Effect.\n\nI need some betatesters,if you like drop a message somewhere.\n\nThankyous:\n~~~~~~~~~~\n* Puzzler & Darklord for support.\n* Rex Dildo for the phonecall and let me join POD.\n* Moral support by Jester.\n* Commodore Amiga for being the best computer ever ! \n\nLegal bla bla:\n~~~~~~~~~~~~~~\nCommodore & Commodore Amiga are trademarks of Commodore Business Machines.\n\nThere ist NO (and I repeat NO! NO! NO!) warranty for this little peace of\nbinary. The Author can not be held or made responsilbe for any damages. But\nif you detect any bugs, please give the Placebo Effect a rrrrring and drop me\n(Satori) a message.\n\nBBSbcs and all other files in this archive are tested unter /X Version 3.09.\n\n\nFuture Versions:\n~~~~~~~~~~~~~~~~\nBBSbcs is strict under development. Future versions will have full ansi support\nand more...\n\nDistribution of BBSbcs:\n~~~~~~~~~~~~~~~~~~~~~~~\nBBSbcs will be distributed freely, but is INVE$T-Ware. This means the\nsupplied BBSbcs executables & docs are copyrighted by Satori/POD. If you want\na personal version of BBSbcs for your BBS, send me some money, and we will send\nyou your personal version of BBSbcs. Please distribute only the selfextracting\nBBSbcs.run archive.\n\n\nCRC-List:\n~~~~~~~~~\nV 0.01a:\n\nBBSBcs    : CRC Checksum = $984BD15D Size: 14884 (to short for a backdoor)\nWall.rexx : CRC Checksum = $A90B70AD Size:  2322\n\nV 0.09:\n\nBBSBcs    : CRC Checksum = $814928BE Size: 19760\n\n\nBonus:\n~~~~~~\nThis archive contains a bonus rexx script for /X from Lightspeed Technology.\n\nWall.rexx  - a write on the wall tool from Giap, updated and revised by Puzzler\n             & Satori. We added some wired random ansi colors for each line\n             and made a few cleanups.\n\nPlease consult the script for further information.\n\nYours..\n\nSatori/POD Fri Jan 14 16:56:53 1994\n\nHistory:\n~~~~~~~\n\nV 0.01a -- inital release to some betatest boards\n\nV 0.04  -- internal release, not public\n\nV 0.05  -- internal release, not public\n\nV 0.07  -- internal release, not public\n\nV 0.09  -- bugfixed, release version\n\nChanges:\n~~~~~~~~\n\nV 0.04  general cleanup, improved disk i/o\n\nV 0.05  fixed bug in disk i/o\n\nV 0.07  another damn bug in disk i/o routines, i have to rework the whole code\n        added a cpu detect routine, should be capable to detect 68000, 68010,\n        68020, 68030 an 68040 cpu.\n\nV 0.09 supports generic ansi control codes, for an ansified output type\n       bbsbcs <logfile> <logfile> ANSI for ansi output.\n\n','\n',char(10)),NULL,'auto-added',16178,3,0,NULL,NULL,'pod_bbsb','scan',1780048671);
INSERT INTO door_catalog VALUES('pottysrc','POTTYSRC.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/POTTYSRC.LHA',NULL,'XIM','Source to Pot-Noodle''s AmiExpress BBS Utils.',NULL,NULL,NULL,'-------------------------------------------- I''m not planning on updating any of this, so I have decided to release it in case someone',replace('Source to Pot-Noodle''s AmiExpress BBS Utils.\n--------------------------------------------\nI''m not planning on updating any of this, so\nI have decided to release it in case someone\nelse wants to, and for others to learn from.\n','\n',char(10)),'Pot.readme',replace('-----BEGIN PGP SIGNED MESSAGE-----\n\nRight - because of how old all of this stuff is, some of it could need\nsome playing around with to get it to assemble with the newer routines\nand includes files. Don''t expect any of it to be easy!!\n\nI hasten to add that the programs I''m writing at the moment are a lot\nbetter coded than anything you''ll find in this archive. It goes without\nsaying that you improve your coding with time, so please don''t laugh if\nyou see some really stupid way of coding!! :-)\n\n\nWARNING: Most of my AmiExpress utils have some simpl checksums in them to\n         make sure some lame fuck doesn''t change my name! Of course, if\n         you''re gunna update this stuff or play with my source, you''re\n         probably going to want to change the output texts and stuff.\n         I SUGGEST YOU REMOVE THE CHECKSUM CODE FIRST! It isn''t hard to\n         remove, just find the routines which call the checksum macro near\n         the start of the source. (If just remove the checksum macro and\n         attempt to assemble you should get told which routines are looking\n         for it!).\n\n         If you stuff-up the checksum, the program will disable the FreeMem()\n         call, and you''ll gradually run out of memory (it doesn''t do anything\n         nasty to your harddrive, I''m not that big an asshole!).\n\n         I thought I''d better warn you about that!\n\n\nAnother thing of note: Some of the programs use things like this:\n\nDOS_CLIRITE = Y	Write text using CLI_Hdl(a5) as output handle.\nDOS_FILEXIS = N	Check if a file exists. Also locks the file.\nDOS_FILSIZE = Y	Measure size of a file.\nDOS_FILALOC = N	Allocate Memory for file.\nDOS_FILDALO = N	DeAllocate Memory for file.\n\nwhile others will do it like this:\n\nDOS_CLIRITE	; Write text using CLI_Hdl(a5) as output handle.\nDOS_FILSIZE	; Measure size of a file.\n\nYou should convert everything to use the SECOND method (i.e., all lines\nwith "= Y", you can leave included, but if they say "= N" you can remove\nthem).\n\nThese things are used to set options and control whether bits of code from\nother files get included at assembly time. Check out the Routines/ files\nto see what I mean.\n\n\nGood luck getting this stuff to assemble! I hope I haven''t forgotten anything.\nIf you have trouble, please try to contact me and I''ll attempt to help you\nout.\n\n	Leo.\n\n- -----BEGIN PGP PUBLIC KEY BLOCK-----\nVersion: 2.6.2i\n\nmQBNAi89RoQAAAECANqcKhCP7W7aaOUlVoSXoFAkIJGfm9yB1WJAozUiD7uXVR5P\nqgVtzMXXYFPs8G6mOjnn7Bv+eTeCKnLDCXCfqb0ABRG0J0xlbyBEYXZpZHNvbiA8\nbGVvQGhhbXBzY2hsLmRlbW9uLmNvLnVrPokAVQMFEC/4q4wqcsMJcJ+pvQEBlB0B\n/AxLJzmgVE+jy9/hb48vRVs+rf2x6fETTWzxXfEB/T7a1W8d91+a5ju3J9mQc1XJ\nkkcqhPRDaTybi5CkyNYNBb+0GmFrYSAiTnVkZWwiIG9uIElSQywgI0FtaWdhtCRh\na2EgUG90LU5vb2RsZSAvIEdvZHMnR2lmdCBVdGlsaXRpZXM=\n=XhVP\n- -----END PGP PUBLIC KEY BLOCK-----\n\n-----BEGIN PGP SIGNATURE-----\nVersion: 2.6.2i\n\niQBVAwUBMEoK1Cpywwlwn6m9AQFy3AIAuVTlp/HTVx9r4Jh5gRiLGoDJyjg9XdwN\nbvpzzFkd3Obfs2Bj7gsqOdip+tMANIlmP68tBi3Tfl8/rqvrFB4kRQ==\n=A1O8\n-----END PGP SIGNATURE-----\n','\n',char(10)),NULL,NULL,461212,5,0,NULL,NULL,NULL,'scan',1780048671);
INSERT INTO door_catalog VALUES('powera12','POWERA12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/POWERA12.LHA','Access','XIM','Access',NULL,NULL,NULL,'for MAXsBBS (v1.2)',replace('Fully Featured Access Management System \nfor MAXsBBS (v1.2) \n','\n',char(10)),'Access.Guide',replace('@Database "PowerDOORS.Guide"\n@Author "Techn!x of Sub-Bass BBS"\n@(c) "Copyright © 1997 Sub-Bass Software. All Rights Reserved."\n@WordWrap\n@Width 78\n\n@Node MAIN "An Instructional Guide to PowerDOORS..."\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n            @{b} P o w e r A C C E S S  -  V e r s i o n   1 . 2 @{ub}\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n         Programmed by Techn!x of Sub-Bass BBS - (01473) 412 842\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                         @{i} Please Select a Topic: @{ui}\n\n  @{" [A] " Link INTR} @{b}Introduction@{ub}     @{" [B] " Link INST} @{b}Installation@{ub}      @{" [C] " Link CONF} @{b}Configuration@{ub}\n  @{" [D] " Link USIN} @{b}Usage@{ub}            @{" [E] " Link CRED} @{b}Credits@{ub}           @{" [F] " Link GREE} @{b}Greetings@{ub}\n  @{" [G] " Link COPY} @{b}Copyright@{ub}        @{" [H] " Link DISC} @{b}Disclaimer@{ub}        @{" [I] " Link CONT} @{b}Contact Details@{ub}@{ub}\n  @{" [J] " Link HIST} @{b}History@{ub}          @{" [K] " Link LICE} @{b}Software License@{ub}  @{" [L] " Link REGI} @{b}Registration@{ub}\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n           < < < Magic-File  - Makes Automated File Menus > > >\n\n           Programmed by: Steve Clack of Liquid Software Design\n\n  [email removed]             Total Eclipse on +44 [0] (1983) 522428\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@EndNode Main\n\n@Node INTR "Introduction to this PowerDOOR"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                        Introduction - What is it?\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   Power Access is a Door which allows each level of user (1-10000) have\n   a different Bulletin and Main Door Script. This allows the Sysops and\n   Co-Sysops to have a Quick Login whereas normal users have a long\n   delay with many doors such as questionnaires.\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                        What does this Door offer?\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   This door offers different access scripts for every single Access\n   available from 1 to 10000. It will even support more if Niki Murkett\n   decides to revamp the Access system on MAXsBBS Professional.\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode INTR\n\n@Node INST "Installing PowerDOORS"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                     Installation of this PowerDOOR...\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   All PowerDOORS are installed in the same way. Simply, make sure that\n   there is a directory in your Doors directory or assignment called\n   `POWER''. This is where all PowerDOORS are stored. If you do not have\n   your DOORS directory assigned, then you should add an Assign to your\n   Startup-Sequence or User-Startup File.\n\n        C:Assign >NIL: DOORS: BBS:Doors/\n                              ^^^^^^^^^^\n                              Change this to your Doors directory path\n\n   Now, Create a directory inside the `DOORS:Power/'' Directory with\n   the name of the Door. This is the word to the right of the `Power''\n   in the Archive filename. So, For example, if the PowerDOOR was called\n   PowerACCESS, then you would create a directory in the `DOORS:Power/''\n   directory called `ACCESS''.\n\n   Now, Locate the Archive you downloaded or received. It will probably\n   be in the `LhA'' or `LZX'' form. Simply use a version of `LhA'' or `LZX''\n   to Extract the files into the desired path.\n\n   C:LhA x PowerACCESS_??.LHA DOORS:Power/????/  \  Where `????'' is the\n                                                  } Name of the PowerDOOR\n   C:LZX x PowerACCESS_??.LZX DOORS:Power/????/  /  For example, `ACCESS''\n\n   Now, all the files including some File Descriptions `File_ID.DIZ'' and\n   some Configuration files `Access.CFG''. Other files will also be\n   included which are not Doors such as those that have the File\n   Extension of `.Text''. These files are ANSIs. If you find a file with\n   an extension of `DAT'', then do not try and edit these.\n\n   Now, Simply add the following line to your `DOORS:IntroDoor.Text''\n   File...\n\n                          Power/Access/Access\n\n   Now, Simply create a Directory in your `Doors'' path or assignment\n   called `Scripts'', and in this directory, you can create as many\n   different Access files called `MainDoor.Text.?'' and\n   `BulletinDoor.Text.?'' where the `?'' Question Mark can be anything\n   from 1 `MainDoor.Text.1'' to 10000 `MainDoor.Text.10000''.\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode INST\n\n@Node CONF "Configuring PowerDOORS"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                       Configuration of PowerDOORS\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   As of this version, There is no Configuration File needed for\n   Power Access. Simply create scripts in the `DOORS:Scripts/'' directory\n   that you created during installation and create the actual Access\n   Door scripts in there...\n\n   Call the scripts...  `MainDoor.Text.?'' and `BulletinDoor.Text.?''\n   where `?'' can be from 1 to 10000...\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode CONF\n\n@Node USIN "Using the PowerDOOR"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                           Using the PowerDOOR...\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   When the Door is loaded during Logon, An ANSI Screen will appear\n   saying that the BBS Logon Process is being configured for the\n   relevant access. The User''s access level will be represented by a\n   Figure in the Access text box and by a small Graph representing\n   your access against the highest access (10000).\n\n   When the Process is complete, the Door will exit automatically\n   allowing the normal BBS Logon process to continue...\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode USIN\n\n@Node CRED "Credits for PowerDOORS"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                    Production Credits for PowerDOORS\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n   @{b}Production Credits@{ub}\n   ~~~~~~~~~~~~~~~~~~\n     @{b}Programming, Routines & Coding@{ub} .............. @{i} Techn!x @{ui}\n\n     @{b}Ideas and Concepts@{ub} .......................... @{i} Anthony Barrett @{ui}\n\n     @{b}ANSI, Documentation and Support Files@{ub} ....... @{i} Techn!x @{ui}\n\n   @{b}Resources@{ub}\n   ~~~~~~~~~\n     @{b}AMOS Professional 2.1@{ub} ....................... @{i} François Lionet @{ui}\n     @{b}                     @{ub}                         @{i} Europress Limited @{ui}\n\n     @{b}KewlDoors v2.10@{ub} ............................. @{i} Niki Murkett @{ui}\n     @{b}               @{ub}                               @{i} Fosters @{ui}\n     @{b}               @{ub}                               @{i} Liquid Software @{ui}\n\n     @{b}GUI Extension v1.60@{ub} ......................... @{i} Piettro Ghizzoni @{ui}\n     @{b}                   @{ub}                           @{i} DairySoft Productions @{ui}\n\n     @{b}ANSI-Draw v0.97@{ub} ............................. @{i} Kjell Andersson @{ui}\n\n   @{b}Thanks Go To:@{ub}\n   ~~~~~~~~~~~~~\n     @{b}Niki Murkett@{ub} ................................ @{i} For KewlDoors @{ui}\n     @{b}Fosters     @{ub}\n\n     @{b}Philip Saunders@{ub} ............................. @{i} For Ideas @{ui}\n\n     @{b}Steve Clack@{ub} ................................. @{i} For the Best @{ui}\n     @{b}           @{ub}                                   @{i} Filebase for @{ui}\n     @{b}           @{ub}                                   @{i} MAXsBBS 1.5x @{ui}\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode CRED\n\n@Node GREE "Greetings..."\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                     Greetings go to the Following...\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n  \n   Philip Saunders, Niki Murkett, Steve Clack, Simon Knock, !n5ane,\n   Pinball, Headphones, Ricky Rodgers, Anthony Barrett, Lore, Dr. X,\n   BitMapp, Ian Chapman, Kegg, Leigh Russ, All the Peeps on FluffyNet,\n   MAXsNET II and other great MAXsBBS Networks, and to anyone else that\n   I know, but have forgotten...\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode GREE\n\n@Node COPY "Copyright Details for PowerDOORS"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                      Copyright and Legal Details\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   The Name `PowerDOORS'' and any other associated names are Copyright\n   Material of Sub-Bass Software. All of the included Door Executables\n   as well as ANSI and Documentation Files are Copyright Material of\n   Sub-Bass Software.\n\n   Any infringement of this Copyright Protection may result in Criminal\n   Prosecution (Copyright Act, 1984) in a Court of Law.\n\n   Any persons caught changing parts or all of any Executable, Document\n   or ANSI and Distributing the altered part can be prosecuted under\n   the Copyright Act of 1984.\n\n   Any persons found distributing `Hacked'' Registered Versions or\n   Key Files associated with PowerDOORS can be prosecuted under the\n   Software Theft Act of 1986.\n\n   PowerDOORS are Copyright Material of Sub-Bass Software.\n   All Rights Reserved.\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode COPY\n\n@Node DISC "Disclaimer for PowerDOORS"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                    Disclaimer Details for PowerDOORS\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   Neither Sub-Bass BBS nor any other related Persons or Companies\n   accept any responsibility for any Loss, Damage or Changes to Data\n   (Digital or otherwise), Equipment or any other product whilst\n   downloading, installing, removing, using, configuring, maintaining,\n   hacking, uploading or checking this product.\n\n   This Product is Safe and should not cause any of the above Problems.\n   Use these Products at your Risk.\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode DISC\n\n@Node CONT "Contacting PowerDOORS Associates"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                    Contacting PowerDOORS Associates\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   There are many ways of Contacting the author and associates of the\n   PowerDOOR Suite...\n\n   @{b}Telephone (Voice):@{ub}\n   ~~~~~~~~~~~~~~~~~~\n    From UK:  (01473) 401 404     International: +44-1473-401-404\n\n   @{b}BBS Modem:@{ub}\n   ~~~~~~~~~~\n    From UK:  (01473) 412 842     International: +44-1473-412-842\n\n   @{b}Netmail:@{ub}\n   ~~~~~~~~\n       SubNET: 2000/1/0\n    FluffyNET: 888/105/0\n    MAXsNET 2: Not Available!\n\n   @{b}Internet:@{ub}\n   ~~~~~~~~~\n          WWW: http://www.subbass.demon.co.uk/ (Online Soon)\n       E-Mail: [email removed]\n\n   @{b}Mail:@{ub}\n   ~~~~~\n     Techn!x,\n     c/o Sub-Bass BBS,\n     10, Ellenbrook Road,\n     Ipswich,\n     Suffolk,\n     England,\n     IP2 9RN.\n    \n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode CONT\n\n@Node LICE "Licensing Information on this Door"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                            Power Access v1.2\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   This Door was coded by Techn!x of Sub-Bass Design with the intention\n   of making no money. This Door is released under the Licensing\n   Principle of `FreeWare'' or `GiftWare''. This Product is classed as\n   Public Domain for Distribution Purposes. However, The Documentation,\n   Executables and Source Code are still Copyright Material of\n   Sub-Bass Design.\n\n   THIS PRODUCT IS FREEWARE AND DOES NOT REQUIRE REGISTRATION FEES TO\n   BE PAID TO EXPERIENCE THE FULL VERSION.\n\n   THIS IS THE FULL VERSION (NOT EVALUATION) OF POWER RAW DOWNLOAD AND\n   NO MONEY SHOULD BE CHARGED EXCEPT TO COVER DELIVERY COSTS.\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode LICE\n\n@Node HIST "The History of this Door..."\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                          History of this Door\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n    Version 1.2 (23rd April 1997)\n    ~~~~~~~~~~~\n   O - Now works with Multi-Node BBS''s Thanks to NSA''s Multitask Patcher.\n\n    Version 1.1 (24th March 1997)\n    ~~~~~~~~~~~\n   O - Removed ShareWare Routines as PowerDOORS are now FreeWare.\n   O - Updated Included ANSI File to Speed up Operation.\n\n    Version 1.0 (2nd March 1997)\n    ~~~~~~~~~~~\n   O - Added Graph and Cycling Number Routines to improve Aesthetics\n       of the Door.\n   O - Added `BulletinDoor.Text'' and `GuestDoor.Text'' support as well\n       as `MainDoor.Text'' which has always been available.\n\n    Version 0.9 (1st Februrary 1997) - Private Sub-Bass Version\n    ~~~~~~~~~~~\n   O - Added Configuration Support.\n   O - Added Script/ANSI File\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode HIST\n\n@Node REGI "Registration Details..."\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                 Power Access Does Not Require Registration\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   @{" [K] " Link LICE} Power Access Licensing Agreement\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode REGI\n\n','\n',char(10)),NULL,'auto-added',25050,4,0,NULL,NULL,'powera12','scan',1780048671);
INSERT INTO door_catalog VALUES('powerp13','POWERP13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/POWERP13.LHA','Poll','XIM','Poll',NULL,NULL,NULL,'| S | u | B | - | B | a | S | S | `---|---''---''---''---''---''---|---'' | D - E - S - ! - G - N |',replace('     .---.---.---.---.---.---.---.---.\n     | S | u | B | - | B | a | S | S |\n     `---|---''---''---''---''---''---|---''\n         | D - E - S - ! - G - N |\n   .-----`-----------------------''-----.\n   | Coded by: Techn!x of Sub-Bass BBS |\n   `-----.-----------------------.-----''\n (01473) |   P o w e r P O L L   | (01473)\n 412 842 `-----------------------'' 412 842\nO------------------------------------------O\n| PowerPOLL v1.3 - Polling & Voting System |\nO------------------------------------------O\n','\n',char(10)),'Poll.Guide',replace('@Database "PowerDOORS.Guide"\n@Author "Techn!x of Sub-Bass BBS"\n@(c) "Copyright © 1997 Sub-Bass Software. All Rights Reserved."\n@WordWrap\n@Width 78\n\n@Node MAIN "An Instructional Guide to PowerDOORS..."\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n              @{b} P o w e r P O L L  -  V e r s i o n   1 . 3 @{ub}\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n         Programmed by Techn!x of Sub-Bass BBS - (01473) 412 842\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                         @{i} Please Select a Topic: @{ui}\n\n  @{" [A] " Link INTR} @{b}Introduction@{ub}     @{" [B] " Link INST} @{b}Installation@{ub}      @{" [C] " Link CONF} @{b}Configuration@{ub}\n  @{" [D] " Link USIN} @{b}Usage@{ub}            @{" [E] " Link CRED} @{b}Credits@{ub}           @{" [F] " Link GREE} @{b}Greetings@{ub}\n  @{" [G] " Link COPY} @{b}Copyright@{ub}        @{" [H] " Link DISC} @{b}Disclaimer@{ub}        @{" [I] " Link CONT} @{b}Contact Details@{ub}\n  @{" [J] " Link HIST} @{b}History@{ub}          @{" [K] " Link LICE} @{b}Software License@{ub}  @{" [L] " Link REGI} @{b}Registration@{ub}\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n           < < < Magic-File  - Makes Automated File Menus > > >\n\n           Programmed by: Steve Clack of Liquid Software Design\n\n  [email removed]             Total Eclipse on +44 [0] (1983) 522428\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@EndNode Main\n\n@Node INTR "Introduction to this PowerDOOR"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                        Introduction - What is it?\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   Power Poll is a Voting System that allows Users of any MAXs Bulletin\n   Board System to vote on any topic specified by the SysOp of the BBS.\n\n   This allows SysOps to vote on whether to change certain aspects of\n   their BBS which means that Users will not be upset if you change the\n   Filebase or whatever.\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                        What does this Door offer?\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   This Door offers Two unique doors. One is the main Voting Door which\n   includes a Sysop Menu and a Previous Results viewing System. The\n   other door is intended to add to LogOff Scripts or in LogOn scripts.\n   The second Door is a results Door which displays the current poll\n   results and then exits after a key is pressed.\n\n   This Door also offers Logging capabilities. It logs whenever a New\n   Poll Question is devised storing the Questions in the Log-File as\n   well. Whenever someone votes, Their details are recorded with the\n   Reply they voted for. The log-file can be found in `BBS:LogFiles''\n   and is called `PowerPOLL_Log.Text''.\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode INTR\n\n@Node INST "Installing PowerDOORS"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                     Installation of this PowerDOOR...\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   All PowerDOORS are installed in the same way. Simply, make sure that\n   there is a directory in your Doors directory or assignment called\n   `POWER''. This is where all PowerDOORS are stored. If you do not have\n   your DOORS directory assigned, then you should add an Assign to your\n   Startup-Sequence or User-Startup File.\n\n        C:Assign >NIL: DOORS: BBS:Doors/\n                              ^^^^^^^^^^\n                              Change this to your Doors directory path\n\n   Now, Create a directory inside the `DOORS:Power/'' Directory with\n   the name of the Door. This is the word to the right of the `Power''\n   in the Archive filename. So, For example, if the PowerDOOR was called\n   PowerPOLL, then you would create a directory in the `DOORS:Power/''\n   directory called `POLL''.\n\n   Now, Locate the Archive you downloaded or received. It will probably\n   be in the `LhA'' or `LZX'' form. Simply use a version of `LhA'' or `LZX''\n   to Extract the files into the desired path.\n\n    C:LhA x PowerPOLL_??.LHA DOORS:Power/POLL/  \  Where `????'' is the\n                                                 } Name of the PowerDOOR\n    C:LZX x PowerPOLL_??.LZX DOORS:Power/POLL/  /  For example, `POLL''\n\n   Now, all the files including some File Descriptions `File_ID.DIZ'' and\n   some Configuration files `Poll.CFG''. Other files will also be\n   included which are not Doors such as those that have the File\n   Extension of `.Text''. These files are ANSIs. If you find a file with\n   an extension of `.DAT'', then do not try and edit these.\n\n   Now, You must add the Door to a MAXsBBS Menu or to one of the\n   Log-on Scripts.\n\n    MAXsBBS Menu\n    ~~~~~~~~~~~~\n   Simply go to the relevant Menu where you want to add the Polling Door\n   or Results Door and enter the following details in the Menu Editor.\n\n   Key  Func  Extra  Lo Acc  Hi Acc  Path/Filename/Extra...\n   ~~~  ~~~~  ~~~~~  ~~~~~~  ~~~~~~  ~~~~~~~~~~~~~~~~~~~~~~\n   ???    34      0   ?????   ?????  POWER:Poll/Poll\n   ???    34      0   ?????   ?????  POWER:Poll/Results\n\n    Logon Scripts\n    ~~~~~~~~~~~~~\n   Load in either `DOORS:IntroDoor.Text'' or `DOORS:MainDoor.Text'' into\n   any AmigaDOS Text Editor such as `Ed'' or `Memacs'' and add the\n   following wherever you would like to Doors to run...\n\n      Power/Poll/Poll         <- Poll Door\n      Power/Poll/Results      <- Results Door\n\n   As from version 1.2, You will now be able to record who votes for\n   what thanks to a unique log recording feature. Simply check the File\n   called `PowerPOLL_Log.Text'' located in the `BBS:LogFiles/'' Directory.\n\n   @{" [C] " Link CONF} Configuration\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode INST\n\n@Node CONF "Configuring PowerDOORS"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                       Configuration of PowerDOORS\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   All PowerDOORS are configured in the same way. In the PowerDOOR\n   archive (or Directory if extracted), You will find file(s) with an\n   extension of `.CFG'', These are @{b}C@{ub}on@{b}F@{ub}i@{b}G@{ub}uration files.\n\n   Simply load these Configuration (CFG) Files into a Text Editor and\n   either follow the simple guide located at the end of the Configuration\n   files or use the more complex guide which is located in the Door Guide.\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n    Layout for the Configuration                               PowerPOLL\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n  << @{b}Line 01@{ub} >> - @{i} Path & Filename @{ui}\n  ~~~~~~~~~~~~~\n   This line should contain the Path and Filename of an ANSI/Text File\n   that is displayed during the main operation of the Voting Door.\n   Please check the Example ANSI (`Poll.Text'') for more details on\n   Layout and Positions.\n\n  << @{b}Line 02@{ub} >> - @{i} Path & Filename @{ui}\n  ~~~~~~~~~~~~~\n   This line should contain the Path and Filename of an ANSI/Text File\n   that represents the SysOp''s Control Menu for PowerPOLL. This menu\n   must contain the Key shortcuts that reset the Poll counts and start\n   new counts. Check the (`SysOp.Text'') ANSI File for more information.\n\n  << @{b}Line 03@{ub} >> - @{i} Path & Filename @{ui}\n  ~~~~~~~~~~~~~\n   This line should contain the Path and Filename of an ANSI/Text File\n   that displays the Previous Poll Results. See ''Results.Text'' for more\n   Details.\n\n  << @{b}Line 04@{ub} >> - @{i} Path & Filename @{ui}\n  ~~~~~~~~~~~~~\n   This line should contain the Path and Filename of an ANSI/Text File\n   that is displayed when displaying the Results of the Current Poll\n   from the seperate `Results'' door that is included. Check the ANSI\n   File called `Final_Results.Text'' for more details.\n\n  << @{b}Line 05@{ub} >> - @{i} Number - Y Coordinate @{ui}\n  ~~~~~~~~~~~~~\n   This line should contain a Number that represents the Y coordinate\n   at which the Question set by the SysOp on line 7 of this Configuration\n   is displayed (Centred) on. The default is about `8'' or `9''.\n\n  << @{b}Line 06@{ub} >> - @{i} Title @{ui}\n  ~~~~~~~~~~~~~\n   This line should contain a Title that will appear at the top of\n   the Screen. This Title should represent the Title of the current\n   Polling Topic such as `The Great Spice Girls Poll''.\n\n  << @{b}Line 07@{ub} >> - @{i} The Polling Question @{ui}\n  ~~~~~~~~~~~~~\n   This line should contain the actual Polling Question that is\n   displayed on the screen for the Users to vote for.\n\n   For example, `Who is the Best Spice Girl?''\n\n  << @{b}Line 08@{ub} >> - @{i} Option A @{ui}\n  ~~~~~~~~~~~~~\n   This line should contain the first Reply that is available to the\n   Users when they Vote on the Question set on Line 7 of this\n   configuration file.\n\n   For example, `Geri''\n\n  << @{b}Line 08@{ub} >> - @{i} Option B @{ui}\n  ~~~~~~~~~~~~~\n   This line should contain the Second Reply that is available to the\n   Users when they Vote on the Question set on Line 7 of this\n   configuration file.\n\n   For example, `Emma''\n\n  << @{b}Line 10@{ub} >> - @{i} End of Configuration @{ui}\n  ~~~~~~~~~~~~~\n   As with all PowerDOORS, The Hash (#) at the end of the Configuration\n   signifies its end. Any text after this Hash (either to the right or\n   below it) will be ignored by the Door making it useful to add comments\n   about the configuration below.\n   \n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   Now, Save the Configuration File as a Plain ASCII File and not a\n   Wordworth or other WP Document. Make sure that the File is saved in\n   Plain ASCII otherwise it will not work.\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode CONF\n\n@Node USIN "Using the PowerDOOR"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                           Using the PowerDOOR...\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   Polling/Voting Door\n   ~~~~~~~~~~~~~~~~~~~\n    Main Operation\n    ~~~~~~~~~~~~~~\n   When the Door loads, You can do one of many things. You can exit\n   back to the BBS by pressing [ESC]. You could also Vote on the topic\n   by Pressing either [A] or [B].\n\n   You can access the Previous Poll Sections by pressing [L] or you\n   can access the SysOp Menu by Pressing [S]\n\n    [ESC] - Exit to BBS\n    ~~~~~~~~~~~~~~~~~~~\n   Pressing [ESC] (Escape) will quit PowerPOLL and return you back to\n   the BBS. This can be done at anytime except when Disk Access is\n   occuring.\n\n    [A] - Voting\n    ~~~~~~~~~~~~\n   Pressing [A] will add a Vote to the Poll count of `Reply A''. This\n   will cause the Poll Count Boxes to update as well as the Percentage\n   and Results Graph. After a short burst of Disk access, the Door will\n   exit back to the BBS.\n\n    [B] - Voting\n    ~~~~~~~~~~~~\n   As with [A], Pressing [B] will increase the Poll count of `Reply B''.\n   The Results Tables and Graphs will update and you will be returned\n   back to the BBS.\n\n    [L] - Previous Results\n    ~~~~~~~~~~~~~~~~~~~~~~\n   Pressing [L] will take you to the Last Results part of the Door.\n   This part will consist of the results and graphs of the Last\n   PowerPOLL Vote that occured. You can press [R] to return to the\n   main Voting section or press [Q] to exit back to the BBS.\n\n    [S] - SysOp''s Menu\n    ~~~~~~~~~~~~~~~~~~\n   In the SysOp''s Menu, You can reset the Poll Count for Reply `A'' back\n   to Zero by pressing [1]. You can reset the Poll Count of `B'' by\n   pressing [2]. To Reset both Poll Counts back to Zero, You can simply\n   press [3]. Alternatively, You can start an entirely new poll by\n   pressing [4] and then using Keys [1], [2], [A] and [B], You can set\n   new Titles, Question and Replies. When done, You can save changes by\n   pressing [S] or Quit back to the Poll without saving by pressing [Q].\n\n   [R] will return you to the Main Voting Section and [Q] will exit back\n   to the BBS.\n\n   Results Door\n   ~~~~~~~~~~~~\n   This Door will load and display the Current Poll results in Table\n   and Graphical form. Simply press any key to exit back to the BBS.\n\n  @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode USIN\n\n@Node CRED "Credits for PowerDOORS"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                    Production Credits for PowerRawDL\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n   @{b}Production Credits@{ub}\n   ~~~~~~~~~~~~~~~~~~\n     @{b}Programming, Routines & Coding@{ub} .............. @{i} Techn!x @{ui}\n\n     @{b}Ideas and Concepts@{ub} .......................... @{i} Techn!x @{ui}\n\n     @{b}ANSI, Documentation and Support Files@{ub} ....... @{i} Techn!x @{ui}\n\n   @{b}Resources@{ub}\n   ~~~~~~~~~\n     @{b}AMOS Professional 2.1@{ub} ....................... @{i} François Lionet @{ui}\n     @{b}                     @{ub}                         @{i} Europress Limited @{ui}\n\n     @{b}KewlDoors v2.10@{ub} ............................. @{i} Niki Murkett @{ui}\n     @{b}               @{ub}                               @{i} Fosters @{ui}\n     @{b}               @{ub}                               @{i} Liquid Software @{ui}\n\n     @{b}GUI Extension v1.60@{ub} ......................... @{i} Piettro Ghizzoni @{ui}\n     @{b}                   @{ub}                           @{i} DairySoft Productions @{ui}\n\n     @{b}ANSI-Draw v0.97@{ub} ............................. @{i} Kjell Andersson @{ui}\n\n   @{b}Thanks Go To:@{ub}\n   ~~~~~~~~~~~~~\n     @{b}Niki Murkett@{ub} ................................ @{i} For KewlDoors @{ui}\n     @{b}Fosters     @{ub}\n\n     @{b}Philip Saunders@{ub} ............................. @{i} For Ideas @{ui}\n\n     @{b}Steve Clack@{ub} ................................. @{i} For the Best @{ui}\n     @{b}           @{ub}                                   @{i} Filebase for @{ui}\n     @{b}           @{ub}                                   @{i} MAXsBBS 1.5x @{ui}\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode CRED\n\n@Node GREE "Greetings..."\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                     Greetings go to the Following...\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n  \n   Philip Saunders, Niki Murkett, Steve Clack, Simon Knock, !n5ane,\n   Pinball, Headphones, Ricky Rodgers, Anthony Barrett, Lore, Dr. X,\n   BitMapp, Ian Chapman, Kegg, Leigh Russ, All the Peeps on FluffyNet,\n   MAXsNET II and other great MAXsBBS Networks, and to anyone else that\n   I know, but have forgotten...\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode GREE\n\n@Node COPY "Copyright Details for PowerDOORS"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                      Copyright and Legal Details\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   The Name `PowerDOORS'' and any other associated names are Copyright\n   Material of Sub-Bass Software. All of the included Door Executables\n   as well as ANSI and Documentation Files are Copyright Material of\n   Sub-Bass Software.\n\n   Any infringement of this Copyright Protection may result in Criminal\n   Prosecution (Copyright Act, 1984) in a Court of Law.\n\n   Any persons caught changing parts or all of any Executable, Document\n   or ANSI and Distributing the altered part can be prosecuted under\n   the Copyright Act of 1984.\n\n   Any persons found distributing `Hacked'' Registered Versions or\n   Key Files associated with PowerDOORS can be prosecuted under the\n   Software Theft Act of 1986.\n\n   PowerDOORS are Copyright Material of Sub-Bass Software.\n   All Rights Reserved.\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode COPY\n\n@Node DISC "Disclaimer for PowerDOORS"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                    Disclaimer Details for PowerDOORS\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   Neither Sub-Bass BBS nor any other related Persons or Companies\n   accept any responsibility for any Loss, Damage or Changes to Data\n   (Digital or otherwise), Equipment or any other product whilst\n   downloading, installing, removing, using, configuring, maintaining,\n   hacking, uploading or checking this product.\n\n   This Product is Safe and should not cause any of the above Problems.\n   Use these Products at your Risk.\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode DISC\n\n@Node CONT "Contacting PowerDOORS Associates"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                    Contacting PowerDOORS Associates\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   There are many ways of Contacting the author and associates of the\n   PowerDOOR Suite...\n\n   @{b}Telephone (Voice):@{ub}\n   ~~~~~~~~~~~~~~~~~~\n    From UK:  (01473) 401 404     International: +44-1473-401-404\n\n   @{b}BBS Modem:@{ub}\n   ~~~~~~~~~~\n    From UK:  (01473) 412 842     International: +44-1473-412-842\n\n   @{b}Netmail:@{ub}\n   ~~~~~~~~\n       SubNET: 2000:1/0\n    FluffyNET: 888:105/0\n    MAXsNET 2: Not Available!\n\n   @{b}Internet:@{ub}\n   ~~~~~~~~~\n          WWW: http://www.subbass.demon.co.uk/ (Online Soon)\n       E-Mail: [email removed]\n\n   @{b}Mail:@{ub}\n   ~~~~~\n     Techn!x,\n     c/o Sub-Bass BBS,\n     10, Ellenbrook Road,\n     Ipswich,\n     Suffolk,\n     England,\n     IP2 9RN.\n    \n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode CONT\n\n@Node LICE "Licensing Information on this Door"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                              Power Poll v1.3\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   This Door was coded by Techn!x of Sub-Bass Design with the intention\n   of making no money. This Door is released under the Licensing\n   Principle of `FreeWare'' or `GiftWare''. This Product is classed as\n   Public Domain for Distribution Purposes. However, The Documentation,\n   Executables and Source Code are still Copyright Material of\n   Sub-Bass Design.\n\n   THIS PRODUCT IS FREEWARE AND DOES NOT REQUIRE REGISTRATION FEES TO\n   BE PAID TO EXPERIENCE THE FULL VERSION.\n\n   THIS IS THE FULL VERSION (NOT EVALUATION) OF POWER RAW DOWNLOAD AND\n   NO MONEY SHOULD BE CHARGED EXCEPT TO COVER DELIVERY COSTS.\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode LICE\n\n@Node HIST "The History of this Door..."\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                          History of this Door\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n   \n    Version 1.3 (23rd April 1997)\n    ~~~~~~~~~~~\n   O - Now works on Multi-Node BBS''s thanks to NSA Designs Patching\n       System.\n\n    Version 1.2 (25th March 1997)\n    ~~~~~~~~~~~\n   O - Added `Setup New Poll'' Section meaning Configuration File format\n       had to change to accomodate the New Setup ANSI File.\n   O - Removed some Bugs as well as annoying ShareWare Message at the\n       End of the Door.\n   O - Optimised Code a bit for quicker operation.\n    \n    Version 1.1 (24th March 1997)\n    ~~~~~~~~~~~\n   O - Changed the PowerPOLL License to FreeWare and removed Key-File\n       Search Routines.\n   O - Also removed the `Registered to'' statements.\n   O - Corrected some minor bugs in the Graph routine. It drawed one\n       extra box than it should of when the Percentage equals 100%.\n\n    Version 1.0 (3rd February 1997)\n    ~~~~~~~~~~~\n   O - Added Graph Options as well as Previous Poll Options.\n\n    Version 0.8 (9th December 1996) - Internal Version Only\n    ~~~~~~~~~~~\n   O - Corrected Some Major Bugs\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode HIST\n\n@Node REGI "Registration Details..."\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                 Power Poll Does Not Require Registration\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   @{" [K] " Link LICE} Power Poll Licensing Agreement\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode REGI\n','\n',char(10)),NULL,'auto-added',51440,4,0,NULL,NULL,'powerp13','scan',1780048671);
INSERT INTO door_catalog VALUES('powrdl13','POWRDL13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/POWRDL13.LHA','RawDL','XIM','RawDL',NULL,NULL,NULL,'| S | u | B | - | B | a | S | S | `---|---''---''---''---''---''---|---'' | D - E - S - ! - G - N |',replace('     .---.---.---.---.---.---.---.---.\n     | S | u | B | - | B | a | S | S |\n     `---|---''---''---''---''---''---|---''\n         | D - E - S - ! - G - N |\n   .-----`-----------------------''-----.\n   | Coded by: Techn!x of Sub-Bass BBS |\n   `-----.-----------------------.-----''\n (01473) |  P o w e r R a w D L  | (01473)\n 412 842 `-----------------------'' 412 842\nO------------------------------------------O\n   PowerRawDL v1.3 - Raw Download System\nO------------------------------------------O\n','\n',char(10)),'PowerRawDL_13.ReadMe',replace('Short:    Fully Featured Raw Download System for MAXsBBS (v1.3)\nUploader: [email removed] (Techn!x)\nAuthor:   [email removed] (Techn!x)\nType:     comm/maxs\nRequires: MAXsBBS V1.5x, MAXsBBS Professional 1.1+ or MAXsBBS Emulator\nReplaces: comm/maxs/powerrawdl_*.lha\nVersion:  1.3\n  __   __         __  __    __  __        _                  __\n |__| |  | |   | |_  |_/   |_/ |__| |  | | \  |    \  / |   `__)\n |    |__| |_|_| |__ | \   | \ |  | |/\| |__| |__   \/  | o .__)\n\n    Power Raw Download v1.3 - Raw Download System for MAXsBBS\n                << A MAXsBBS Door (C)''97 Techn!x >>\n\n o  Features Full `ReqTools'' Multi-Select File Requesting System\n\n o  Allows the Presetting of 10 most Popular Files to be Downloaded\n    at any one Key-Press\n\n o  Features either ANSI or `ReqTools'' GUI Option Requests\n\n o  Features Full Logging System\n\n o  Uses Five ANSI Files to cover each choice or result such as\n    `No Files Selected'' and ''Do you want to send more Files?''\n\n o  Features Fully Comprehensive Documentation in AmigaGuide Format\n\n o  Power Raw Download v1.3 is FreeWare - No Registration Needed\n\n','\n',char(10)),NULL,'auto-added',26437,4,0,NULL,NULL,'powrdl13','scan',1780048671);
INSERT INTO door_catalog VALUES('powrul13','POWRUL13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/POWRUL13.LHA','RawUL','XIM','RawUL',NULL,NULL,NULL,'| S | u | B | - | B | a | S | S | `---|---''---''---''---''---''---|---'' | D · E · S · I · G · N |',replace('     .---.---.---.---.---.---.---.---.\n     | S | u | B | - | B | a | S | S |\n     `---|---''---''---''---''---''---|---''\n         | D · E · S · I · G · N |\n   .-----`-----------------------''-----.\n   | Coded by: Techn!x of Sub-Bass BBS |\n   `-----.-----------------------.-----''\n Online  |  P o w e r R a w U L  | Online\n   Soon  `-----------------------'' Soon\nO------------------------------------------O\n    PowerRawUL v1.2 - Raw Upload System\nO------------------------------------------O\n','\n',char(10)),'RawUL.Guide',replace('@Database "PowerDOORS.Guide"\n@Author "Techn!x of Sub-Bass BBS"\n@(c) "Copyright © 1997 Sub-Bass Software. All Rights Reserved."\n@WordWrap\n@Width 78\n\n@Node MAIN "An Instructional Guide to PowerDOORS..."\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n             @{b} P o w e r R a w U L  -  V e r s i o n   1 . 3 @{ub}\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n          Programmed by Techn!x of Sub-Bass BBS - (01473) 412 842\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                         @{i} Please Select a Topic: @{ui}\n\n  @{" [A] " Link INTR} @{b}Introduction@{ub}     @{" [B] " Link INST} @{b}Installation@{ub}      @{" [C] " Link CONF} @{b}Configuration@{ub}\n  @{" [D] " Link USIN} @{b}Usage@{ub}            @{" [E] " Link CRED} @{b}Credits@{ub}           @{" [F] " Link GREE} @{b}Greetings@{ub}\n  @{" [G] " Link COPY} @{b}Copyright@{ub}        @{" [H] " Link DISC} @{b}Disclaimer@{ub}        @{" [I] " Link CONT} @{b}Contact Details@{ub}\n  @{" [J] " Link HIST} @{b}Product History@{ub}  @{" [K] " Link LICE} @{b}License Details@{ub}   @{" [L] " Link REGI} @{b}Registration@{ub}\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n          < < < Kewl-RAW  - Raw Download System for MAXsBBS > > >\n\n           Programmed by: Steve Clack of Liquid Software Design\n\n  [email removed]             Total Eclipse on +44 [0] (1983) 522428\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@EndNode Main\n\n@Node INTR "Introduction to this PowerDOOR"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                        Introduction - What is it?\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   Power Raw Upload is a Door that allows the Sysop to allow users to\n   send/upload files privately to the Sysop. This is a quicker method\n   than using a Filebase or Attaching them to messages...\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                        What does this Door offer?\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   This Door allows users to send more than one file at a time by using\n   Z-Modem features and also by offering the User a choice to upload\n   more files when the transfer is complete.\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode INTR\n\n@Node INST "Installing PowerDOORS"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                     Installation of this PowerDOOR...\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   All PowerDOORS are installed in the same way. Simply, make sure that\n   there is a directory in your Doors directory or assignment called\n   `POWER''. This is where all PowerDOORS are stored. If you do not have\n   your DOORS directory assigned, then you should add an Assign to your\n   Startup-Sequence or User-Startup File.\n\n        C:Assign >NIL: DOORS: BBS:Doors/\n                              ^^^^^^^^^^\n                              Change this to your Doors directory path\n\n   Now, Create a directory inside the `DOORS:Power/'' Directory with\n   the name of the Door. This is the word to the right of the `Power''\n   in the Archive filename. So, For example, if the PowerDOOR was called\n   PowerRAWUL, then you would create a directory in the `DOORS:Power/''\n   directory called `RawUL''.\n\n   Now, Locate the Archive you downloaded or received. It will probably\n   be in the `LhA'' or `LZX'' form. Simply use a version of `LhA'' or `LZX''\n   to Extract the files into the desired path.\n\n    C:LhA x PowerRawUL_??.LHA DOORS:Power/RawUL/  \  Where `????'' is the\n                                                   } Name of the PowerDOOR\n    C:LZX x PowerRawUL_??.LZX DOORS:Power/RawUL/  /  For example, `NEWS''\n\n   Now, all the files including some File Descriptions `File_ID.DIZ'' and\n   some Configuration files `RawUL.CFG''. Other files will also be\n   included which are not Doors such as those that have the File\n   Extension of `.Text''. These files are ANSIs. If you find a file with\n   an extension of `DAT'', then do not try and edit these.\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode INST\n\n@Node CONF "Configuring PowerDOORS"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                       Configuration of PowerDOORS\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   All PowerDOORS are configured in the same way. In the PowerDOOR\n   archive (or Directory if extracted), You will find file(s) with an\n   extension of `.CFG'', These are @{b}C@{ub}on@{b}F@{ub}i@{b}G@{ub}uration files.\n\n   Simply load these Configuration (CFG) Files into a Text Editor and\n   either follow the simple guide located at the end of the Configuration\n   files or use the more complex guide which is located in the Door Guide.\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n    Layout for the Configuration                              PowerRawUL\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n  << @{b}Line 01@{ub} >> - @{i} Path & Filename @{ui}\n  ~~~~~~~~~~~~~\n   This line should contain the Path and Filename of an ANSI/Text File\n   which is basically the Front-End of the main Raw Upload Door. Make\n   sure that lines 14, 19 and 20 are all blank as these are used for\n   Status, Information and Copyright details.\n\n  << @{b}Line 02@{ub} >> - @{i} Section Number @{ui}\n  ~~~~~~~~~~~~~\n   This line should contain the MAXsBBS File Section Number where all\n   Sysop Files are kept. So, Enter the number of the Sysops File Section\n   as this is where all Raw Uploads will be sent to.\n\n  << @{b}Line 03@{ub} >> - @{i} Optional Path @{ui}\n  ~~~~~~~~~~~~~\n   This line should contain a Path for where the Files are kept as many\n   Sysops don''t like to mix the Sysop files with the rest of the files,\n   So use better FileBases such as MagicFile which allow optional paths\n   for each file section. Make sure the Path ends in either a Colon (:)\n   or a Forward Slash (/).\n\n  << @{b}Line 04@{ub} >> - @{i} End of Configuration @{ui}\n  ~~~~~~~~~~~~~\n   As with all PowerDOORS, The Hash (#) at the end of the Configuration\n   signifies its end. Any text after this Hash (either to the right or\n   below it) will be ignored by the Door making it useful to add comments\n   about the configuration below.\n   \n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   Now, Save the Configuration File as a Plain ASCII File and not a\n   Wordworth or other WP Document. Make sure that the File is saved in\n   Plain ASCII otherwise it will not work.\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode CONF\n\n@Node USIN "Using the PowerDOOR"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                           Using the PowerDOOR...\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   When the Door is loaded, The Main ANSI Screen will appear asking you\n   to press any key to begin transfers.\n\n   After you press a key, then the message will change telling the Remote\n   user to start Uploading files.\n\n   The MAXsBBS File Transfer window will now appear with status of the\n   Uploads. When complete, the Door will ask the user if he/she would\n   like to send any more files.\n\n   Either the Sysop or User can answer this. If `Y'' is pressed, then the\n   Transfer window will reappear. If anything else is pressed, the Door\n   will exit back to the BBS.\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode USIN\n\n@Node CRED "Credits for PowerDOORS"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                    Production Credits for PowerDOORS\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n   @{b}Production Credits@{ub}\n   ~~~~~~~~~~~~~~~~~~\n     @{b}Programming, Routines & Coding@{ub} .............. @{i} Techn!x @{ui}\n\n     @{b}Ideas and Concepts@{ub} .......................... @{i} Niki Murkett @{ui}\n\n     @{b}ANSI, Documentation and Support Files@{ub} ....... @{i} Techn!x @{ui}\n\n   @{b}Resources@{ub}\n   ~~~~~~~~~\n     @{b}AMOS Professional 2.1@{ub} ....................... @{i} François Lionet @{ui}\n     @{b}                     @{ub}                         @{i} Europress Limited @{ui}\n\n     @{b}KewlDoors v2.10@{ub} ............................. @{i} Niki Murkett @{ui}\n     @{b}               @{ub}                               @{i} Fosters @{ui}\n     @{b}               @{ub}                               @{i} Liquid Software @{ui}\n\n     @{b}GUI Extension v1.60@{ub} ......................... @{i} Piettro Ghizzoni @{ui}\n     @{b}                   @{ub}                           @{i} DairySoft Productions @{ui}\n\n     @{b}ANSI-Draw v0.97@{ub} ............................. @{i} Kjell Andersson @{ui}\n\n   @{b}Thanks Go To:@{ub}\n   ~~~~~~~~~~~~~\n     @{b}Niki Murkett@{ub} ................................ @{i} For KewlDoors @{ui}\n     @{b}Fosters     @{ub}\n\n     @{b}Philip Saunders@{ub} ............................. @{i} For Ideas @{ui}\n\n     @{b}Steve Clack@{ub} ................................. @{i} For the Best @{ui}\n     @{b}           @{ub}                                   @{i} Filebase for @{ui}\n     @{b}           @{ub}                                   @{i} MAXsBBS 1.5x @{ui}\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode CRED\n\n@Node GREE "Greetings..."\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                     Greetings go to the Following...\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n  \n   Philip Saunders, Niki Murkett, Steve Clack, Simon Knock, !n5ane,\n   Pinball, Headphones, Ricky Rodgers, Anthony Barrett, Lore, Dr. X,\n   BitMapp, Ian Chapman, Kegg, Leigh Russ, All the Peeps on FluffyNet,\n   MAXsNET II and other great MAXsBBS Networks, and to anyone else that\n   I know, but have forgotten...\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode GREE\n\n@Node COPY "Copyright Details for PowerDOORS"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                      Copyright and Legal Details\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   The Name `PowerDOORS'' and any other associated names are Copyright\n   Material of Sub-Bass Software. All of the included Door Executables\n   as well as ANSI and Documentation Files are Copyright Material of\n   Sub-Bass Software.\n\n   Any infringement of this Copyright Protection may result in Criminal\n   Prosecution (Copyright Act, 1984) in a Court of Law.\n\n   Any persons caught changing parts or all of any Executable, Document\n   or ANSI and Distributing the altered part can be prosecuted under\n   the Copyright Act of 1984.\n\n   Any persons found distributing `Hacked'' Registered Versions or\n   Key Files associated with PowerDOORS can be prosecuted under the\n   Software Theft Act of 1986.\n\n   PowerDOORS are Copyright Material of Sub-Bass Software.\n   All Rights Reserved.\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode COPY\n\n@Node DISC "Disclaimer for PowerDOORS"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                    Disclaimer Details for PowerDOORS\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   Neither Sub-Bass BBS nor any other related Persons or Companies\n   accept any responsibility for any Loss, Damage or Changes to Data\n   (Digital or otherwise), Equipment or any other product whilst\n   downloading, installing, removing, using, configuring, maintaining,\n   hacking, uploading or checking this product.\n\n   This Product is Safe and should not cause any of the above Problems.\n   Use these Products at your Risk.\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode DISC\n\n@Node CONT "Contacting PowerDOORS Associates"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                    Contacting PowerDOORS Associates\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   There are many ways of Contacting the author and associates of the\n   PowerDOOR Suite...\n\n   @{b}Telephone (Voice):@{ub}\n   ~~~~~~~~~~~~~~~~~~\n    From UK:  (01473) 401 404     International: +44-1473-401-404\n\n   @{b}BBS Modem:@{ub}\n   ~~~~~~~~~~\n    From UK:  (01473) 412 842     International: +44-1473-412-842\n\n   @{b}Netmail:@{ub}\n   ~~~~~~~~\n       SubNET: 2000/1/0\n    FluffyNET: 888/105/0\n    MAXsNET 2: Not Available\n\n   @{b}Internet:@{ub}\n   ~~~~~~~~~\n          WWW: http://www.subbass.demon.co.uk/ (Online Soon)\n       E-Mail: [email removed]\n\n   @{b}Mail:@{ub}\n   ~~~~~\n     Techn!x,\n     c/o Sub-Bass BBS,\n     10, Ellenbrook Road,\n     Ipswich,\n     Suffolk,\n     England,\n     IP2 9RN.\n    \n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode CONT\n\n@Node LICE "Licensing Information on this Door"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                          Power Raw Upload v1.3\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   This Door was coded by Techn!x of Sub-Bass Design with the intention\n   of making no money. This Door is released under the Licensing\n   Principle of `FreeWare'' or `GiftWare''. This Product is classed as\n   Public Domain for Distribution Purposes. However, The Documentation,\n   Executables and Source Code are still Copyright Material of\n   Sub-Bass Design.\n\n   THIS PRODUCT IS FREEWARE AND DOES NOT REQUIRE REGISTRATION FEES TO\n   BE PAID TO EXPERIENCE THE FULL VERSION.\n\n   THIS IS THE FULL VERSION (NOT EVALUATION) OF POWER RAW DOWNLOAD AND\n   NO MONEY SHOULD BE CHARGED EXCEPT TO COVER DELIVERY COSTS.\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode LICE\n\n@Node HIST "The History of this Door..."\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                          History of this Door\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n    Version 1.3 (23rd April 1997)\n    ~~~~~~~~~~~\n   O - Patched the Main Door Executable with Niki Murkett''s Multitasking\n       AMOS Patch which allows the program to be ran more than one copy\n       at a time, which is intended for multi-node BBS''s.\n   \n    Version 1.2 (19th March 1997)\n    ~~~~~~~~~~~\n   O - Corrected Some Major Bugs such as the one which didn''t let the\n       User Upload any Files [:)\n\n   O - Added the Configuration File where the Sysop can set in which\n       File Section the Raw Uploads go to and also set an Optional\n       File Path (like MagicFile)\n\n    Version 1.1 (10th February 1997) - Internal Version\n    ~~~~~~~~~~~\n   O - Heavily Bugged. Upload System did not even work at all\n\n   O - Added `Upload More Files'' Option\n\n    Version 1.0 (1st February 1997) - Internal Version\n    ~~~~~~~~~~~\n   O - This was not a Door, a Random Number Generator could have written\n       better code than me on this version, So I re-wrote the entire\n       Door. :p\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode HIST\n\n@Node REGI "Registration Details..."\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n              Power Raw Upload Does Not Require Registration\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   @{" [K] " Link LICE} Power Raw Upload Licensing Agreement\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode REGI\n\n','\n',char(10)),NULL,'auto-added',26627,4,0,NULL,NULL,'powrul13','scan',1780048671);
INSERT INTO door_catalog VALUES('powsen17','POWSEN17.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/POWSEN17.LHA','Send','XIM','Send',NULL,NULL,NULL,'| S | u | B | - | B | a | S | S | `---|---''---''---''---''---''---|---'' | D - E - S - ! - G - N |',replace('     .---.---.---.---.---.---.---.---.\n     | S | u | B | - | B | a | S | S |\n     `---|---''---''---''---''---''---|---''\n         | D - E - S - ! - G - N |\n   .-----`-----------------------''-----.\n   | Coded by: Techn!x of Sub-Bass BBS |\n   `-----.-----------------------.-----''\n (01473) |   P o w e r S E N D   |  (01473)\n 412 842 `-----------------------''  412 842\nO------------------------------------------O\n     PowerSEND v1.7 - Message Addresser\nO------------------------------------------O\n','\n',char(10)),'Send.Guide',replace('@Database "PowerDOORS.Guide"\n@Author "Techn!x of Sub-Bass BBS"\n@(c) "Copyright © 1997 Sub-Bass Software. All Rights Reserved."\n@WordWrap\n@Width 78\n\n@Node MAIN "An Instructional Guide to PowerDOORS..."\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n              @{b} P o w e r S E N D  -  V e r s i o n   1 . 7 @{ub}\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n          Programmed by Techn!x of Sub-Bass BBS - (01473) 412 842\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                         @{i} Please Select a Topic: @{ui}\n\n  @{" [A] " Link INTR} @{b}Introduction@{ub}     @{" [B] " Link INST} @{b}Installation@{ub}      @{" [C] " Link CONF} @{b}Configuration@{ub}\n  @{" [D] " Link USIN} @{b}Usage@{ub}            @{" [E] " Link CRED} @{b}Credits@{ub}           @{" [F] " Link GREE} @{b}Greetings@{ub}\n  @{" [G] " Link COPY} @{b}Copyright@{ub}        @{" [H] " Link DISC} @{b}Disclaimer@{ub}        @{" [I] " Link CONT} @{b}Contact Details@{ub}\n  @{" [J] " Link HIST} @{b}Product History@{ub}  @{" [K] " Link LICE} @{b}License Details@{ub}   @{" [L] " Link REGI} @{b}Registration@{ub}\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n          < < < KewlPAGE  - Kewl Paging System for MAXsBBS > > >\n\n           Programmed by: Steve Clack of Liquid Software Design\n\n  [email removed]             Total Eclipse on +44 [0] (1983) 522428\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@EndNode Main\n\n@Node INTR "Introduction to this PowerDOOR"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                        Introduction - What is it?\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   Power Send is a Door that replaces the MAXsBBS Internal Function 16\n   which is the Send Message Function. After being on Fluffynet for\n   a while and other Nets, I found that whilst scanning through the\n   Mail, I found Messages for myself addressed to the wrong person or\n   Spelt incorrectly.\n \n   This Door features one of the features that MAXsBBS was originally\n   bereft of. It features a great `SysOp'' Mail Diversion system which\n   will automatically redirect mail addressed to `SysOp'' to whoever\n   is specified in the `Send'' configuration...\n\n   This Door brings up a Normal `Who is the Message For?'' requester\n   but this time, It gives the user the choice to press [RETURN] on\n   a Blank line to activate the Search List.\n\n   The User can now use the cursor keys as well as the previous versions\n   `<'' and `>'' keys to search through the list of Users for the User\n   they want. A small description of the User is provided to aid in\n   the Search. When the relevant person is found, Simply press [RETURN]\n   and hopefully...\n\n   The Message will be sent...\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                        What does this Door offer?\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n  \n   This Door offers a unique User Listing system that allows the User\n   to select who he/she wants to send a message to...\n\n   They can also press any Letter key and the System will jump to the\n   next name in the list with the same first letter as that pressed.\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode INTR\n\n@Node INST "Installing PowerDOORS"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                     Installation of this PowerDOOR...\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   All PowerDOORS are installed in the same way. Simply, make sure that\n   there is a directory in your Doors directory or assignment called\n   `POWER''. This is where all PowerDOORS are stored. If you do not have\n   your DOORS directory assigned, then you should add an Assign to your\n   Startup-Sequence or User-Startup File.\n\n        C:Assign >NIL: DOORS: BBS:Doors/\n                              ^^^^^^^^^^\n                              Change this to your Doors directory path\n\n   Now, Create a directory inside the `DOORS:Power/'' Directory with\n   the name of the Door. This is the word to the right of the `Power''\n   in the Archive filename. So, For example, if the PowerDOOR was called\n   PowerSEND, then you would create a directory in the `DOORS:Power/''\n   directory called `SEND''.\n\n   Now, Locate the Archive you downloaded or received. It will probably\n   be in the `LhA'' or `LZX'' form. Simply use a version of `LhA'' or `LZX''\n   to Extract the files into the desired path.\n\n    C:LhA x PowerSEND_??.LHA DOORS:Power/RawUL/  \  Where `????'' is the\n                                                  } Name of the PowerDOOR\n    C:LZX x PowerSEND_??.LZX DOORS:Power/RawUL/  /  For example, `SEND''\n\n   Now, all the files including some File Descriptions `File_ID.DIZ'' and\n   some Configuration files `Send.CFG''. Other files will also be\n   included which are not Doors such as those that have the File\n   Extension of `.Text''. These files are ANSIs. If you find a file with\n   an extension of `DAT'', then do not try and edit these.\n\n   Now, Go through all your MAXsBBS Menus and look for every entry that\n   has Function `16'' setup. This is a `Send Message'' Command. Now,\n   Change that `16'' to `34''. Now, in the `Filename/Path'' box, Enter in\n   the path of PowerSEND followed by the Section Number where the\n   Message is to be posted...\n\n   Key   Function   Extra   Lo Acc   Hi Acc   Path/Filename\n   ~~~   ~~~~~~~~   ~~~~~   ~~~~~~   ~~~~~~   ~~~~~~~~~~~~~\n     ?         34       0        ?        ?   POWER:Send/Send <SECTION_NO>\n\n   Where <SECTION_NO> is the actual MAXsBBS Mail Section in which the\n   Message is to be posted. `0'' for Private Mail etc.\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode INST\n\n@Node CONF "Configuring PowerDOORS"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                       Configuration of PowerDOORS\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   All PowerDOORS are configured in the same way. In the PowerDOOR\n   archive (or Directory if extracted), You will find file(s) with an\n   extension of `.CFG'', These are @{b}C@{ub}on@{b}F@{ub}i@{b}G@{ub}uration files.\n\n   Simply load these Configuration (CFG) Files into a Text Editor and\n   either follow the simple guide located at the end of the Configuration\n   files or use the more complex guide which is located in the Door Guide.\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n    Layout for the Configuration                               PowerSend\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n  << @{b}Line 01@{ub} >> - @{i} Path & Filename @{ui}\n  ~~~~~~~~~~~~~\n   This line should contain the Path and Filename for the Main ANSI\n   File that is displayed during the Doors usage. Check the included\n   ANSI File `Send.Text'' for the Table and positioning Layout.\n\n  << @{b}Line 02@{ub} >> - @{i} Path & Filename @{ui}\n  ~~~~~~~~~~~~~\n   This line should contain the Path and Filename for the ANSI that\n   contains information on the Keyboard Shortcuts used in PowerSEND.\n   This ANSI is the Help File. Check the included File `Help.Text''\n   for the available Keyboard Shortcuts.\n\n   (Note: [<-],[->],[/\],[\/] represent Cursor Keys L,R,U and D)\n\n  << @{b}Line 03@{ub} >> - @{i} Number @{ui}\n  ~~~~~~~~~~~~~\n   This line should contain a Number that represents the Y coordinate\n   on which the Doors Status information will be centred on.\n\n   By default this is set to `20'', so the Door Information and Status\n   details will appear centred on Line 20 (at the bottom of the screen)\n\n  << @{b}Line 04@{ub} >> - @{i} User Name @{ui}\n  ~~~~~~~~~~~~~\n   This line should contain the Name of the BBS SysOp. This is the\n   name at which mail addressed to `SysOp'' is diverted to, So double\n   check spelling etc. as otherwise you may lose a bit of mail.\n\n  << @{b}Line 05@{ub} >> - @{i} End of Configuration @{ui}\n  ~~~~~~~~~~~~~\n   As with all PowerDOORS, The Hash (#) at the end of the Configuration\n   signifies its end. Any text after this Hash (either to the right or\n   below it) will be ignored by the Door making it useful to add comments\n   about the configuration below.\n   \n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   Now, Save the Configuration File as a Plain ASCII File and not a\n   Wordworth or other WP Document. Make sure that the File is saved in\n   Plain ASCII otherwise it will not work.\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   With PowerSEND, You can have upto 9 List configurations, These are\n   called `List.CFG.?'' where `?'' is a number from 1 to 9. Now, These\n   files contain the Users and Descriptions.\n\n   The First Line should contain a Description of the User-List such as\n   `Fluffy Net - The Users from Fluffy Net'' or something like that.\n\n   The rest of the lines should contain the `Name'' of the User, then on\n   the next line, the `Description'' of the User...\n\n   Example File\n   ~~~~~~~~~~~~\n    Fluffy Net User List - The Peepz from the Land of Fluffy\n    Niki Murkett\n    SysOp of Redrum BBS\n    Steve Clack\n    SysOp of Total Eclipse BBS\n    Techn!x\n    SysOp of Sub-Bass BBS\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode CONF\n\n@Node USIN "Using the PowerDOOR"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                           Using the PowerDOOR...\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   When the Door is loaded, The Main ANSI Screen will appear asking you\n   to enter in the Destination (Name) of the User who you want to send\n   a message to.\n\n   You can either:-\n\n    i)  Enter in the Name of the User and press [RETURN], The door will\n        now exit and the BBS will return on the `Enter Subject'' Prompt.\n\n or...  You can simply press [RETURN] without entering a name...\n\n   After a short while, The User Database will load and all the Users\n   contained in the Database will appear. Now, You will see the Names\n   of the Users on the Left hand side of the screen.\n\n   Using either the `<'' `['' and `>'' `]'' keys, or the Cursor Keys,\n   You can scroll up and down the list to search for the relevant user.\n   The Selected User will be displayed in White at the top of the list.\n   A brief description of the selected user will be displayed on the\n   Status line.\n\n   You use the Cursor Keys `/\'' and `\/'' to search through the Users\n   but as from Version 1.3, You can use the Cursor Keys `<'' and `>''\n   to cycle through the available User-Lists. These are the Lists that\n   contain the User details. Included in the PowerSEND archive are two\n   example Configurations `List.CFG.1'', `List.CFG.2'' and `List.CFG.3''.\n\n   When you have found the right user, Simply press [RETURN] and the\n   Door will exit to the BBS at the `Enter Subject'' prompt. Now,\n   Continue as you would when sending a message...\n\n   You can search for a specific user by using the `#'' Hash key.\n   Simply press the Hash (#) key and the `TO:'' prompt will change\n   to a `SEARCH:'' prompt. Now, Enter the first few letters of the\n   name and the System will search for that user...\n\n   So, entering `Nik'' would find... `Niki Murkett''\n\n   NOTE: As from Version 1.2, You will not be able to send a message\n         to yourself as the Door checks your User Name and if you\n         try to send a message to that user-name using either the\n         Text box or the Listing method, You will get a message\n         saying that you can''t post a message to yourself.\n\n   NOTE: As from Version 1.5, PowerSEND uses MAXsBBS Text lines 51 and\n         264 which are `Send Message to:...'' and ''You cannot Send Mail\n         to Yourself!''. Please feel free to change theses to ANSI Files\n         using the `<BBS:Text/Example.Text'' method as it does make the\n         Door look better.\n\n   Alternatively, You can simply press any Letter (A-Z) key and the\n   System will automatically jump to the next name that starts with\n   the letter you pressed. Once you have reached the last entry that\n   begins with the letter key you pressed, The system will jump back\n   to the top.\n\n   When you are in the Listing mode, You can press the `?'' Question Mark\n   key to obtain Online Help on the available Keyboard Shortcuts.\n\n   To exit from the `List'' mode back to the `Enter Destination''\n   prompt, Simply press either the Backspace Key or the [SPACE] Bar.\n\n   You can exit back to the BBS at any time by pressing the [ESCAPE]\n   Key. This will perform a FINISH command which will Exit immediately\n   back to the BBS without no copyright or credits appearing.\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode USIN\n\n@Node CRED "Credits for PowerDOORS"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                    Production Credits for PowerDOORS\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n   @{b}Production Credits@{ub}\n   ~~~~~~~~~~~~~~~~~~\n     @{b}Programming, Routines & Coding@{ub} .............. @{i} Techn!x @{ui}\n\n     @{b}Ideas and Concepts@{ub} .......................... @{i} Techn!x @{ui}\n\n     @{b}ANSI, Documentation and Support Files@{ub} ....... @{i} Techn!x @{ui}\n\n   @{b}Resources@{ub}\n   ~~~~~~~~~\n     @{b}AMOS Professional 2.1@{ub} ....................... @{i} François Lionet @{ui}\n     @{b}                     @{ub}                         @{i} Europress Limited @{ui}\n\n     @{b}KewlDoors v2.10@{ub} ............................. @{i} Niki Murkett @{ui}\n     @{b}               @{ub}                               @{i} Fosters @{ui}\n     @{b}               @{ub}                               @{i} Liquid Software @{ui}\n\n     @{b}GUI Extension v1.60@{ub} ......................... @{i} Piettro Ghizzoni @{ui}\n     @{b}                   @{ub}                           @{i} DairySoft Productions @{ui}\n\n     @{b}ANSI-Draw v0.97@{ub} ............................. @{i} Kjell Andersson @{ui}\n\n   @{b}Thanks Go To:@{ub}\n   ~~~~~~~~~~~~~\n     @{b}Niki Murkett@{ub} ................................ @{i} For KewlDoors @{ui}\n     @{b}Fosters     @{ub}\n\n     @{b}Philip Saunders@{ub} ............................. @{i} For Ideas @{ui}\n\n     @{b}Steve Clack@{ub} ................................. @{i} For the Best @{ui}\n     @{b}           @{ub}                                   @{i} Filebase for @{ui}\n     @{b}           @{ub}                                   @{i} MAXsBBS 1.5x @{ui}\n\n     @{b}Niki Murkett@{ub} ................................ @{i} For the Usage @{ui}\n     @{b}Roger Wilco @{ub}                                  @{i} of FluffyNet  @{ui}\n     @{b}            @{ub}                                  @{i} User Data!    @{ui}\n\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode CRED\n\n@Node GREE "Greetings..."\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                     Greetings go to the Following...\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n  \n   Philip Saunders, Niki Murkett, Steve Clack, Simon Knock, !n5ane,\n   Pinball, Headphones, Cryogenics, Anthony Barrett, Lore, Dr. X,\n   BitMapp, Ian Chapman, Kegg, Leigh Russ, All the Peeps on FluffyNet,\n   MAXsNET II and other great MAXsBBS Networks, and to anyone else that\n   I know, but have forgotten...\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode GREE\n\n@Node COPY "Copyright Details for PowerDOORS"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                      Copyright and Legal Details\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   The Name `PowerDOORS'' and any other associated names are Copyright\n   Material of Sub-Bass Software. All of the included Door Executables\n   as well as ANSI and Documentation Files are Copyright Material of\n   Sub-Bass Software.\n\n   Any infringement of this Copyright Protection may result in Criminal\n   Prosecution (Copyright Act, 1984) in a Court of Law.\n\n   Any persons caught changing parts or all of any Executable, Document\n   or ANSI and Distributing the altered part can be prosecuted under\n   the Copyright Act of 1984.\n\n   Any persons found distributing `Hacked'' Registered Versions or\n   Key Files associated with PowerDOORS can be prosecuted under the\n   Software Theft Act of 1986.\n\n   PowerDOORS are Copyright Material of Sub-Bass Software.\n   All Rights Reserved.\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode COPY\n\n@Node DISC "Disclaimer for PowerDOORS"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                    Disclaimer Details for PowerDOORS\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   Neither Sub-Bass BBS nor any other related Persons or Companies\n   accept any responsibility for any Loss, Damage or Changes to Data\n   (Digital or otherwise), Equipment or any other product whilst\n   downloading, installing, removing, using, configuring, maintaining,\n   hacking, uploading or checking this product.\n\n   This Product is Safe and should not cause any of the above Problems.\n   Use these Products at your Risk.\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode DISC\n\n@Node CONT "Contacting PowerDOORS Associates"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                    Contacting PowerDOORS Associates\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   There are many ways of Contacting the author and associates of the\n   PowerDOOR Suite...\n\n   @{b}Telephone (Voice):@{ub}\n   ~~~~~~~~~~~~~~~~~~\n    From UK:  (01473) 401 404     International: +44-1473-401-404\n\n   @{b}BBS Modem:@{ub}\n   ~~~~~~~~~~\n    From UK:  (01473) 412 842     International: +44-1473-412-842\n\n   @{b}Netmail:@{ub}\n   ~~~~~~~~\n       SubNET: 2000/1/0\n    FluffyNET: 888/105/0\n    MAXsNET 2: Not Available\n\n   @{b}Internet:@{ub}\n   ~~~~~~~~~\n          WWW: http://www.subbass.demon.co.uk/ (Online Soon)\n       E-Mail: [email removed]\n\n   @{b}Mail:@{ub}\n   ~~~~~\n     Techn!x,\n     c/o Sub-Bass BBS,\n     10, Ellenbrook Road,\n     Ipswich,\n     Suffolk,\n     England,\n     IP2 9RN.\n    \n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode CONT\n\n@Node LICE "Licensing Information on this Door"\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                             Power Send v1.7\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   This Door was coded by Techn!x of Sub-Bass Design with the intention\n   of making no money. This Door is released under the Licensing\n   Principle of `FreeWare'' or `GiftWare''. This Product is classed as\n   Public Domain for Distribution Purposes. However, The Documentation,\n   Executables and Source Code are still Copyright Material of\n   Sub-Bass Design.\n\n   THIS PRODUCT IS FREEWARE AND DOES NOT REQUIRE REGISTRATION FEES TO\n   BE PAID TO EXPERIENCE THE FULL VERSION.\n\n   THIS IS THE FULL VERSION (NOT EVALUATION) OF POWER RAW DOWNLOAD AND\n   NO MONEY SHOULD BE CHARGED EXCEPT TO COVER DELIVERY COSTS.\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode LICE\n\n@Node HIST "The History of this Door..."\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                          History of this Door\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n    Version 1.7 (20th April 1997)\n    ~~~~~~~~~~~\n   O - As from 20th April 1997, All PowerDOORS have been Patched with\n       Niki Murkett''s `Multitasking'' Patch System to allow usage on\n       Multi-Node BBS''s.\n\n    Version 1.6 (31st March 1997) - "Two New Versions in One Day!"\n    ~~~~~~~~~~~\n   O - Added Shortcuts [1] to [9] for selecting User-Lists.\n   O - Added [0] Zero Key to add current User to the Global List (1)\n\n    Version 1.5 (31st March 1997)\n    ~~~~~~~~~~~\n   O - Replaced in-built `Enter Message To:'' and `You Cannot Send Mail\n       to Yourself` Messages with the MAXsBBS Internal Text Editor\n       Lines (51 & 264) to make Style of PowerSEND for suitable to\n       many BBS''s.\n\n   O - Enhanced Code to prevent ANSI Screen Redraws after User-List\n       selected using Cursor Keys.\n    \n    Version 1.4 (29th March 1997)\n    ~~~~~~~~~~~\n   O - Added Search Facility to allow quick searches for Users.\n   O - Added the `SysOp'' diversion system which diverts messages\n       addressed to `SysOp'' to the correct name, ie. `Techn!x''\n   O - Added FluffyNet and Developers User-Lists to archive.\n\n    Version 1.3 (28th March 1997)\n    ~~~~~~~~~~~\n   O - Added Multiple User Lists and optimised Cursor routines.\n   O - Speeded up Scrolling System by eliminating Error Checking.\n   O - Configuration File Changed to accomodate new Help ANSI File\n       which is accessed by pressing `?'' in the Main Door.\n\n    Version 1.2 (26th March 1997)\n    ~~~~~~~~~~~\n   O - Corrected Cursor Key procedure. Cursor Up Key made the list\n       scroll down and Vice Versa. So, Had to change that before\n       Public Release.\n\n   O - Added `Aminet'' Readme files as well as `File_ID.DIZ'' files to\n       all PowerDOOR Archives.\n\n   O - Sorted Introduction Bug out. The `Version'' String at the Start\n       was corrupt, so the AmigaDOS `Version'' command would not\n       recognise the Version string.\n       It should be `PowerSEND (Mail Destinator) v?.?''.\n    \n    Version 1.1 (25th March 1997)\n    ~~~~~~~~~~~\n   O - Added Cursor Key Support to make the Door easier to use.\n    \n    Version 1.0 (21st March 1997)\n    ~~~~~~~~~~~\n   O - Removed Description Column as it slowed the Door down to much.\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode HIST\n\n@Node REGI "Registration Details..."\n\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n                 Power Send Does Not Require Registration\n  -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n   @{" [K] " Link LICE} Power Send Licensing Agreement\n\n   @{" [0] " Link MAIN} Return to the Main Menu\n\n@EndNode REGI\n\n','\n',char(10)),NULL,'auto-added',32748,4,0,NULL,NULL,'powsen17','scan',1780048671);
INSERT INTO door_catalog VALUES('prc_po2','PRC-PO2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PRC-PO2.LHA','dfc','XIM','PutOnline',NULL,'Caffeine','PRC','|___  \___  \/   \/  __/  ___/  ___/  ___/| c| /  /  /  /  |  \_ |/_  _) \__ \ \__ \  | Y|  _/|  \  \_ |   / |/ \ |__/ |  \/ |  \ |',replace('.___________  ___  _______________________.\n|___  \___  \/   \/  __/  ___/  ___/  ___/|\nc| /  /  /  /  |  \_ |/_  _) \__ \ \__ \  |\nY|  _/|  \  \_ |   / |/ \ |__/ |  \/ |  \ |\nb|  | |  |\__/____/_____/_________/_____/ |\n`|__|-|__|---------------------[PRESENTS]-''\n       PutOnline by Caffeine (v0.3)        \n       ~~~~~~~~~ ~~ ~~~~~~~~ ~~~~~~        \n» No More Local-Uploads  » FCheck Routines \n» Perfect For Sysops     » Prompts for Desc\n-------------------------------------------\nSent By: <OJ Simpson> from L.A. COUNTY JAIL\n-------------------------------------------\n','\n',char(10)),'PutOnline2.doc',replace(' _________________.__________________________  Earth has a lot of things \n \____  \ _  \    |  ___/  ___/   ___/   ___/  other folks might want,\ncYb/ |  / /  / |  |  |__| _/\ \__.  |\__.  |   like the whole planet.\n  /  __/  \  \    |  |  |    \|  |  ||  |  |   And maybe these folks would\n /   |/___|\  \___|_____|_____\ ____|| ____|   like a few changes made,\n/____|------\__\---PRESENTS---|/-----|/-----*  like more carbon dioxide \n                                               in the atmosphere, and \n       PUTONLINE V0.2 BY CAFFEINE/PROCESS      room for their way of life.\n\nI made this util coz I was sick of leeching stuff and having to local-upload\nit to /X.  I didn''t want it to be such a big "hit", since it took me a whole\nfive minutes to code it. But you know how things are...\n\nREQUIREMENTS:\n~~~~~~~~~~~~~\n[1] A file (duh). Currently supported FILE_ID.DIZ filetypes:\n    LHA/ DMS/ LZH/ DOC/ DOX/ NFO/ TXT/ GIF/ EXE/ ZIP.\n[2] c:copy  (since renaming across devices is illegal)\n    c:lha  \n    c:dmsdescript  from RE/Y\O/MST\n    c:txtextract   from RE/Y\O/MST\n    c:exedescript  from SPY/MST\n    c:gifdesc      from MIT/MST\n    c:unzip\n[3] BBS: (assigned or as a volume), BBS:confconfig.info, BBS:Fcheck/\n[4] The right DIR in the conference \n    (PO will enter the desc in the highest dir, listed as NDIRS in the conf\n     icon)\n\nUSAGE:\n~~~~~~\nPutOnline <path/file> <conference#>\n\nExample:  PutOnline work:newstuff/PRC-PO2.LHA 4\n\nThis would add the file work:newstuff/PRC-PO2.LHA to Conference #4.\n( gee I wonder where I got that filename from... )\n\nCHANGES SINCE v0.1\n~~~~~~~~~~~~~~~~~~\n[1] Added FCHECK support. Uses the checker specified in "BBS:FCHECK/"\n[2] Now uses Amiga specific commands which increased speed.\n[3] If no FILE_ID found, prompts for a single-line description.\n[4] Deletes the file after it''s online, so don''t freak out if its not there.\n    It will check for the file to make sure it''s online before deleting it.\n\nERRORS, BUGS, THANKS, NAME-CALLING, ECT:\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nCaffeine@410001 or LAST RiGHTS [Process WHQ] +1(410)-653-2845\n\nGREETINGS:\n~~~~~~~~~~\nShuyki Tanaka, EMPiRE, nocTurne, Numb, Sigma Seven, The Champ@GR0007, \nApprentice/Process, Sir Garbagetruck/Process, Cyborg/Process.\n\nTHANKS:\n~~~~~~~\nSkinny Puppy, Ministry, Front Line Assembly, Nine Inch Nails, KMFDM, \nand countless other industrial bands for keeping me awake and coding. Also\nmany MANY Marlboro''s :)\n\nSCRIPTS:\n~~~~~~~~\nJust to make it easier for you sysops (myself included), here''s my \nDiskMaster script...\n\n---------------------( Start Cutting Right About Here.. )------------------\nAddMenu Files, PO SNES , 2, StdIO "CON:0/1/640/100/Putting File(s) Online";Extern c:PutOnline %s 2;StdIO CLOSE\nAddMenu Files, PO AMIGA, 3, StdIO "CON:0/1/640/100/Putting File(s) Online";Extern c:PutOnline %s 3;StdIO CLOSE\nAddMenu Files, PO PICS , 4, StdIO "CON:0/1/640/100/Putting File(s) Online";Extern c:PutOnline %s 4;StdIO CLOSE\nAddMenu Files, PO IBM  , 5, StdIO "CON:0/1/640/100/Putting File(s) Online";Extern c:PutOnline %s 5;StdIO CLOSE\n---------------------( You Can Stop Now )----------------------------------\n\nJust cut the above out, open up S:STARTUP.DM, paste it, and load DM up.\nYou might want to edit it, since this is for my bbs :)\n','\n',char(10)),NULL,'auto-added',22048,4,0,NULL,NULL,'prc_po2','scan',1780048671);
INSERT INTO door_catalog VALUES('prc_reqs','PRC-REQS.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PRC-REQS.LHA',NULL,'XIM','.___________  ___  _______________________.',NULL,NULL,'PRC','|___  \___  \/   \/  __/  ___/  ___/  ___/| c| /  /  /  /  |  \_ |/_  _) \__ \ \__ \  | Y|  _/|  \  \_ |   / |/ \ |__/ |  \/ |  \ |',replace('.___________  ___  _______________________.\n|___  \___  \/   \/  __/  ___/  ___/  ___/|\nc| /  /  /  /  |  \_ |/_  _) \__ \ \__ \  |\nY|  _/|  \  \_ |   / |/ \ |__/ |  \/ |  \ |\nb|  | |  |\__/____/_____/_________/_____/ |\n`|__|-|__|---------------------[PRESENTS]-''\n        >> Caffeine-Request v1.0 <<        \n           ~~~~~~~~ ~~~~~~~ ~~~~           \n    » Simply the *BEST* Request Door! «    \n','\n',char(10)),NULL,NULL,NULL,NULL,10789,4,0,NULL,NULL,NULL,'scan',1780048671);
INSERT INTO door_catalog VALUES('prc_zmsg','PRC-ZMSG.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PRC-ZMSG.LHA',NULL,'XIM','.___________  ___  _______________________.',NULL,'Caffeine/Process!','PRC','|___  \___  \/   \/  __/  ___/  ___/  ___/| c| /  /  /  /  |  \_ |/_  _) \__ \ \__ \  | Y|  _/|  \  \_ |   / |/ \ |__/ |  \/ |  \ |',replace('.___________  ___  _______________________.\n|___  \___  \/   \/  __/  ___/  ___/  ___/|\nc| /  /  /  /  |  \_ |/_  _) \__ \ \__ \  |\nY|  _/|  \  \_ |   / |/ \ |__/ |  \/ |  \ |\nb|  | |  |\__/____/_____/_________/_____/ |\n`|__|-|__|---------------------[PRESENTS]-''\n   »» Z-MSG v1.0 by Caffeine/Process! ««   \n  Users/Sysop Can Upload Msgs With Zmodem  \n      NO  MORE  MESSY  ASCII - SENDS!      \n  Works With /XNetMail And Normal E-Mail!  \n','\n',char(10)),'uzi.txt',replace('                                            .---------------------------.\n    _______.-----------------._______/|     |     4NODEZ  RiNGDOWN      |\n    \_     |     .------     |________|.....| 73 GiG OF AMiGA CoNSoLE PC|\n   .:|     |     |     ______|        |:::::|  uZiSUiCiDE.sERVEBBS.ORG  |\n  .::|     |     |     |     |        |-----+-----.      TELNET         |\n .:::|           |     |     |       :|     |     |                     |\n.::::\___________|___________|________|     `-----+---------------------''\n:::::::::::::::::|                                | 24HR 7DAY STATiC iP! \n_________________|___________/|__________________/|______________________\n\_     ______    |     _______|          |_____________      _/    _____/\n_|_____    |     |     |      |    |_____|        |   |      |     ___|_ \n|     |    |     |     |      |    |     |        |   |      |     |    |\n|     |    |     |     |     :|          |       :|   |      |     |    |\n|__________|_____|_____|______|__________|________|__________|__________|\n:::::::::::::::::|            |                                         |\n`::::::::::::::::|            |ALWAYS THE LATEST VERSION oF AMi-EXPRESS |\n `:::::::::::::::|            | TONS OF ONLiNE MESSAGES AND MULTi-CHATS |\n  `::::::::::::::`------------+  NUP IS REQUIRED SO ASK WHOEVER POSTED  |\n   `::::::::::::::::::::::::::|    THIS ADVERT FOR THE NUMBER AND NUP   |\n    `:::::::::::::::::::::::::`-----------------------------------------''\n','\n',char(10)),NULL,NULL,14838,4,0,NULL,NULL,NULL,'scan',1780048671);
INSERT INTO door_catalog VALUES('priv_new','PRIV-NEW.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PRIV-NEW.LHA',NULL,'XIM','Best PRIVATE.TXT ever seen on AmiExpress.',NULL,NULL,'PRIV',NULL,replace('Best PRIVATE.TXT ever seen on AmiExpress.\n','\n',char(10)),'NewUserPw.txt',replace(replace('~\n iF You aRe uNaBLe To MaKe THe FoLLoWiNG STaTeMeNTS oR THeY aRe NoT BiNDiNG\n ^" "^^ ^"^ ^"^""^ "^ "^"^ ""^ "^""^"^"" ""^"^"^""" ^" ""^" ^"^ "^" "^""^""\n        iN YouR CaSe THeN TeRMiNaTe CoNNeCTioN WiTH THiS SYSTeM NoW\n        ^" "^^" "^"^ ""^" "^""^"^"^ "^""^""^^" "^"" ""^" """"^" "^"\n     This is a private system for the exclusive use of our membership.  Any\nattempt at illegal entry, hacking, or access other than by authorization is\na violation of federal regulations and/or a violation of members'' rights of\nprivacy, assembly, free speech and other lawful regulations.\n     In accessing this system you agree to all terms and conditions stated\nherein, specifically all BULLETINS in Conferences where access is granted.\n     No person is to violate FCC, copyright, or other lawful regulations.\nAll programming received is assumed within the Public Domain. We reserve the\nright to one copy for the purposes of testing, archiving, and usage for the\nservices we provide authors/members herein in communications.  Should any\nmember advise us to the contrary, we will investigate and remove materials\nnot compatible with these regulations and is our sole extent of liability.\n     The views expressed are those of the membership.  While every effort is\nmade to insure privacy, legally can not guarantee or be held liable therefor.\nMaterial submitted is the sole responsibility of the members.  We assume no\nliability for content, usage, ownership, reliability, or accuracy thereof.\n~SP\n\n    All new and current users are required to read the following notices.\nIf you are unwilling to abide by the terms of this bulletin, then you\nshould stop using this BBS.  No one will receive access until they\nhave read and agree with this. By using this system, you are showing your\nacknowledgment that you have read and agreed to the terms and conditions\ndescribed in this bulletin. This is a private system of the System Operator.\nYou are only allowed access to this Bulletin Board System if you understand\nand agree to the conditions of access which are listed below.\n\n    You agree that no liability of any kind for any matters relating directly\nor indirectly to your use, or the use of anyone else, whether authorized or\nnot, of this computer system, will impugn to the system operator.  You agree\nto hold harmless and to indemnify the system operator from any action relating\ndirectly or indirectly to matters relating to this computer system.\n\n~SP\n\n    You acknowledge that you have been expressly warned that files on this\nbulletin board carry no warranty of any kind and may not work and may even\ncause damage to your computer system if downloaded.  The System Operator\nmakes no warranties, either express or implied, with regard to software\nobtained from this system and hereby disclaims any and all implied\nwarranties of merchantability and fitness for a particular purpose.  In\nno event will the system operator be liable for incidental or\nconsequential damages, including, but not limited to, destruction of\ndata or damage to your equipment.  The system operator cannot be held\nresponsible for the software on this system.  All software is taken by you\n"as is" and you assume the entire risk of any harm that might occur through\nyour use of this software.\n\n~SP\n\n    You acknowledge that messages may be offensive in content and agree not\nto bring any action of any kind against either the system operator or other\nusers of the system as a result of the messages and their content available\non this system.  Some messages and files are intended for users of 18\nyears of ago or older, it is up to the users sole disgression in the\nmaterial you access on this system.  The System Operator Disclaims any\nresponsibility for results due to the accessing of this material by under\nage users.\n\n~SP\n\n    You expressly agree not to post offensive messages yourself or to\nencourage others to do so.\n\n    You agree not to use the system for any illegal purpose or activity,\nor to discuss or advocate any illegal things, whether in private or in public.\nYou agree not to do anything on this computer that may damage the computer\nhardware, software, or data files, or the system''s operation in any way at all.\n\n    All "private" mail to and from you is not private and may be read and\npassed on to third parties by the system operator and his designated\nrepresentatives if he so chooses.  All messages become the property of the\nsystem operator and may not be displayed elsewhere without his permission.\n\n      Pursuant to the Electronic Communications Privacy Act of 1986\n      (18 U.S.C. 2510 et seq.), notice is hereby given that there are no\n      facilities provided by this system for sending or receiving truly\n      private or confidential electronic communications.\n~SP\n\nThe System Operator can, and often will, read all messages left on this\nsystem, including "Private" messages addressed to persons other than the\nsystem operator, not normally available to other users.  The system operator\nreserves the right to delete any message, regardless of whether such message\nhas been received by its intended recipient(s).  The system operator also\nreserves the right to change the status of a message designated "Private"\nso that such message is public and available to all callers.  The status\nof a message may be changed whenever, in the sole discretion of the system\noperator, it is believed appropriate to do so.  Your continued use of this\nBBS constitutes acceptance of the system operator''s discretion in this\nregard.  Your Sysop will exercise the utmost discretion in this regard; I\ngenerally change status of a message only when it is an informational message,\nof value to other users, and really should not be "private".\n\n~SP\n\n    The system operators reserve the right, without limitation, to grant\n"Sysop" status to other persons.  Such persons have access to all\ncommunications on this BBS and may have all rights of a system operator,\nincluding the ability to delete or change the status of messages.\n\n    You agree that the opinions expressed on this board do not necessarily\nreflect the views of anyone other than the person posting the message.\n\n    You have no rights of access to this system and may find your access\nrestricted or removed and your messages censored or deleted at the system\noperator''s absolute discretion.\n\n    Although the system operator tries to screen all files and messages for\nillegal content, he can not always screen them all.  That is why you agree\nthat it is up to the users sole disgression as to what should be uploaded,\ndownloaded, and posted.  And in no event shall the System Operator be liable\nfor yours or other''s actions on this system.\n~SP\n\n    You agree to these terms, conditions and policies.  All limitations of\nliability are additive rather than exclusive in this message.\n\n NOTE:\n  If you are, or have ever worked for ANY Law Enforcemant agency\nOR ANY regulatory commision of any sort then you MUST leave the\nSysOp feedback saying what company, agency, and what your purpose for\ncalling this BBS System is; Or If You Report To Any Regualatory\nAgencies, Or Work For Or Report To Software Companies.\n\n     Failure to do so would be construed as entrapment if any legal action\n     is taken against the system administrator at any time.\n~SP\n\nBy procedeing on this bbs you agree to the above statement(s) and release\nthe Sysop and all Users of this bbs of any actions that can be taken.\nIf you dont agree with the above statement you are asked to hangup and\nnever call this system again. \n\n By continuing use of this system, you are agreeing that you are able to\n truthfully make the following statements. Further use of this system by\r\n persons not able to comply with the above constitutes trespassing, and is\n punishable by law.\n~SP\n   1> I am not and have never been affiliated in ANY WAY with any law\n      enforcement agency.  This would include Federal workers, Police,\n      Firemen, Politicians AND any other worker drawing ANY pay from ANY\n      government agency.\n   2> I do not report to ANY federal agency or agency personnel in any\n      form, directly or indirectly.\n   3> I agree that any information obtained through the use of said system\n      is for private use ONLY.  I accept ALL responsibility for any data\n      obtained from the system which is not destroyed in its entirity\n      within a one (1) hour period after previewing.\n   4> The operator of this system cannot be held responsible for any of\n      the data available within the system, as the data is provided by the\n      users of the system, not the operator.  By contributing data, the\n      users have agreed that the data could not be used to incriminate\n      ANYONE.\n   5> Should my status concerning the first four statements ever change, I\n      will take the following steps:\n~SP\n      A> Log in to this system\n      B> Notify the system operator of my new status through electronic\n         mail\n      C> Log off of the system without using ANY additional system\n         functions\n      D> Destroy all records of information contained within said system\n         within a two (2) hour period\n      E> Cease to call said system\n\n                ENTER "YES" IF YOU AGREE TO ALL OF THE ABOVE\n         IF YOU DO NOT OR CANNOT AGREE ON ANY ONE (1) OF THE ABOVE,\n                   ** DROP CARRIER NOW ** DO NOT CONTINUE\n','\r',char(13)),'\n',char(10)),NULL,NULL,5490,2,0,NULL,NULL,NULL,'scan',1780048671);
INSERT INTO door_catalog VALUES('pro_open','PRO-OPEN.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PRO-OPEN.LHA',NULL,'XIM','_/\___________________/\____',NULL,NULL,'PRO','\_______   \_____    \_    /--------------. /   ______/   /    //    /____ PROTOCOL  | /    /        /    //    /    /  IN ''95   |',replace(' _/\___________________/\____               \n \_______   \_____    \_    /--------------.\n  /   ______/   /    //    /____ PROTOCOL  |\n /    /        /    //    /    /  IN ''95   |\n/____/[AdK]   /____//_________/  --------  |\n +-----------------------------------------''\n++++++=================================+++++\nPro-Open... the profesional Ami-Express OPEN\nCommand...   TOTALLY sysop configurable!    \n+supports multiple user/sysop access levels+\nworks perfectly on AMix version 3.x and over\n','\n',char(10)),'PROOPEN.DOC',replace('----------------------------------------------------------------------------\n!cOASTaLcARNaGe!--+--!cOASTaLcARNaGe!--!cOASTaLcARNaGe!--+--!cOASTaLcARNaGe!\n----------------------------------------------------------------------------\n__/\\________/\\_________/\\_____/\\____ __/\\_____/\\______/\\_____\n\__  __    ___  .  _____    ~ ____      \             ~ ____     __/\n_/    |____//   !   \_/~  _!  ¼\/|   l___\_    \_/  _!  ¼\_/     |_____\n\     !  _ ¼\_  :    \_   \_    \_.__      \    \   \_    \_     !  _  \_\n \    : _//  /        /    ³     /          \    \   ³     /     : _//  /\n  \____     /________/l____:    /   ³        \    \__:    /_______     /\n      l____/               l___/\________    /_____) l___/-DtN   l____/\n                                       \____/\n__/\\__________/\\________/\\____/\\_________/\\______/\\______/\\_____\n\__  __    ___    ~ _____      __       ____    ~ ____  _______   _____)\n_/    |____//~  _!  ¼\     !___/_  \__   \/~  _!  ¼\_/  \_    \    __/_\n\     !    ¼\_  \_    \_   _     \_ :     \   \_    \_   !  _  \_  I  ¼\_\n \    :      /   ³     /          / i­     \   ³     /   : _//  /        \_\n  \____     /____:    /____:     /  !.      \__:    /_____     /          /\n      l____/Ott  l___/    l_____/___|:        /l___/     l____/__________/\n                                     !_______/\n----------------------------------------------------------------------------\naMIgA-hPa-pEcE-aMIxPREsS-0-dAY-fILEs-28800-cHATTinG-sYsOPs-rUNNiNG-AmIXpREss\n----------------------------------------------------------------------------\n  tHe-fUNkY-bRoS-pEArL-nUoZ-fREAkNET-sTONedMOnkS-cDs-vIDeOs-tO-mUCh-mORe\nkALL-aUStRAlIa-+61[0]75-273648-nODe-tWooo-iS-pRIVaTe-nUp-iS-gOInG-tO-hAPPeN-\n----------------------------------------------------------------------------\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n        ProOpen OPEN DOOR VERSION 2.0 By TRESPASS/[PROTOCOL][CLIQUE]\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n			    WHAT IS PRO-OPEN\n\n\n\n\nPRO-OPEN is a replacement for your current OPEN /x command.. It is totally\nconfigurable by YOU.. <the sysop I hope :)> It will display up to five\ndifferent door menus for you users always in relation to there access\nlevel.\n\nYou can have a user on say access 100 who has no door access so he will be\nshown nothing at the open prompt.. Where as soon as he is upgraded to a\nuser status say... 200  he will be promted with a full menu of YOUR\ndoors. Again the same thing would happen when he was upgraded to another\nlevel.\n\nYou pick the access levels. You pick how may access menus you want\ndisplayed. I have default as 4. this is how many levels I have on my\nboard.\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                                HOW TO INSTALL\n\n\n\nINSTALLING PRO-OPEN  is very simple as long as you pay attention to these\ninstructions.\n\n*FIRST*  a complete list of files included in the arcive.\n\nBBS:DOORS/PROTOOLS/axsnum.001                 <ACCESS CONFIG\nBBS:DOORS/PROTOOLS/axsnum.002                 <ACCESS CONFIG\nBBS:DOORS/PROTOOLS/axsnum.003                 <ACCESS CONFIG\nBBS:DOORS/PROTOOLS/axsnum.004                 <ACCESS CONFIG\nBBS:DOORS/PROTOOLS/axsnum.005                 <ACCESS CONFIG\nBBS:DOORS/PROTOOLS/confnum.config             <LEVELS CONFIG\nBBS:DOORS/PROTOOLS/OPEN.info                  <TOOLTYPE<STARTS DOOR>\nBBS:DOORS/PROTOOLS/proopen.rexx               <PRO-OPEN FILE>\nBBS:DOORS/PROTOOLS/PROOPEN.DOC                <THIS DOCUMENTATION\n\n\nBBS:DOORS/PROTOOLS/SCREENS/001.txt            <001 ACCESS MENU\nBBS:DOORS/PROTOOLS/SCREENS/002.txt            <002 ACCESS MENU\nBBS:DOORS/PROTOOLS/SCREENS/003.txt            <003 ACCESS MENU\nBBS:DOORS/PROTOOLS/SCREENS/004.txt            <004 ACCESS MENU\nBBS:DOORS/PROTOOLS/SCREENS/005.txt            <005 ACCESS MENU\n\n\n\n\n*NOW*    Copy *ALL* these files to the corrct directories within your BBS:\ndir thats to easy to make an error on.\n\nYou now must know how many door menus you wish to display ..  eg how many\naccess levels you have.\n\nI use\n                              : 100 - newuser\n                                200 - user\n                                250 - special people\n                                255 - sysop\n\nso this makes 4 levels... In the file BBS:DOORS/PROTOOLS/confnum.config\nyou should change the number to <x>  maximum 5 <sorry about that> where X\nis your amount of access levels.. Default is 4\n\n\n\nUsing the default of 4 only uses the 4 files \n\n\n\nBBS:DOORS/PROTOOLS/axsnum.001\nBBS:DOORS/PROTOOLS/axsnum.002\nBBS:DOORS/PROTOOLS/axsnum.003\nBBS:DOORS/PROTOOLS/axsnum.004\n\n\n\nwhere if you had a 2 in this file BBS:DOORS/PROTOOLS/confnum.config\nPro-Open would only use the files\n\n\n\nBBS:DOORS/PROTOOLS/axsnum.001\nBBS:DOORS/PROTOOLS/axsnum.002\n\n\n\nand so on\n\n\n\nNow to explain what BBS:DOORS/PROTOOLS/axsnum.001  and so on are for!!\n\nin these files you insert your actuall access level to display to the\nuser..\n\nso in BBS:DOORS/PROTOOLS/axsnum.001  I have the number 100  <newuser>\nThis config file points to the BBS:DOORS/PROTOOLS/SCREENS/001.txt\n\nin BBS:DOORS/PROTOOLS/axsnum.002 I have the number 200 <user>\nThis config file points to the BBS:DOORS/PROTOOLS/SCREENS/002.txt\n\nin BBS:DOORS/PROTOOLS/axsnum.002 I have the number 250 <cosys/special>\nThis config file points to the BBS:DOORS/PROTOOLS/SCREENS/003.txt\n\nin BBS:DOORS/PROTOOLS/axsnum.002 I have the number 255 <sysop>\nThis config file points to the BBS:DOORS/PROTOOLS/SCREENS/004.txt\n\n\n\nanyone with access 100 will only see the menu YOU insert at \n\n             :   BBS:DOORS/PROTOOLS/SCREENS/001.txt\n\nand so forth until you reach the last number  mine is 4\n\n yours would be X  <your total access levels>\n\nif you only had 3 access levels 3 ... 2 would be 2 etc etc... DOnt forget\nthis... This number must be correct.. Or CRASH!!!!!!!!!\n\n\n\n\n\n\nSo all you have to do now is insert your access 100 menus at \n\n                  BBS:DOORS/PROTOOLS/SCREENS/001.txt\n\nyour access 200 menus at \n\n                  BBS:DOORS/PROTOOLS/SCREENS/002.txt\n\nyour access 250 menus at\n\n                  BBS:DOORS/PROTOOLS/SCREENS/003.txt\n\nyour access 255 menus at \n\n                  BBS:DOORS/PROTOOLS/SCREENS/004.txt\n\n\n\n\nALL THESE SETTINGS ARE DEFAULT TO MY BBS... UNLESS YOU USE THE SAME LEVELS\nDO NOT USE THESE DEFAULTS... IF YOU HAVE A USER WHO HAS AN ACCESS OF 124\nFOR SOME REASON AND YOU DO NOT DEFINE A 124 ACCESS LEVEL IN THE PRESETS HE\nWILL NOT RECIEVE ANY MENU AT THE OPEN PROMPT.\n\nIM PRETTY USELESS AT WRITTING DOCS.. MAKE THINGS SOUND MORE COMPLICATED\nTHAN THEY REALLY ARE.. WHY MY WIFE DIVORCED ME :)  < NOOOOoooOOOOOOO!\n\nanyway look at the files it all makes perfect sense... Just experiment if\nyou have trouble  else delete this file eheh ...and give up sysopsing /x\nsystems.. its all to easy!!!!!!!!\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n----------------------------------------------------------------------------\n!cOASTaLcARNaGe!--+--!cOASTaLcARNaGe!--!cOASTaLcARNaGe!--+--!cOASTaLcARNaGe!\n----------------------------------------------------------------------------\n__/\\________/\\_________/\\_____/\\____ __/\\_____/\\______/\\_____\n\__  __    ___  .  _____    ~ ____      \             ~ ____     __/\n_/    |____//   !   \_/~  _!  ¼\/|   l___\_    \_/  _!  ¼\_/     |_____\n\     !  _ ¼\_  :    \_   \_    \_.__      \    \   \_    \_     !  _  \_\n \    : _//  /        /    ³     /          \    \   ³     /     : _//  /\n  \____     /________/l____:    /   ³        \    \__:    /_______     /\n      l____/               l___/\________    /_____) l___/-DtN   l____/\n                                       \____/\n__/\\__________/\\________/\\____/\\_________/\\______/\\______/\\_____\n\__  __    ___    ~ _____      __       ____    ~ ____  _______   _____)\n_/    |____//~  _!  ¼\     !___/_  \__   \/~  _!  ¼\_/  \_    \    __/_\n\     !    ¼\_  \_    \_   _     \_ :     \   \_    \_   !  _  \_  I  ¼\_\n \    :      /   ³     /          / i­     \   ³     /   : _//  /        \_\n  \____     /____:    /____:     /  !.      \__:    /_____     /          /\n      l____/Ott  l___/    l_____/___|:        /l___/     l____/__________/\n                                     !_______/\n----------------------------------------------------------------------------\naMIgA-hPa-pEcE-aMIxPREsS-0-dAY-fILEs-28800-cHATTinG-sYsOPs-rUNNiNG-AmIXpREss\n----------------------------------------------------------------------------\n  tHe-fUNkY-bRoS-pEArL-nUoZ-fREAkNET-sTONedMOnkS-cDs-vIDeOs-tO-mUCh-mORe\nkALL-aUStRAlIa-+61[0]75-273648-nODe-tWooo-iS-pRIVaTe-nUp-iS-gOInG-tO-hAPPeN-\n----------------------------------------------------------------------------\n','\n',char(10)),NULL,NULL,11045,8,0,NULL,NULL,NULL,'scan',1780048671);
INSERT INTO door_catalog VALUES('prolzx','PROLZX.LZX','~/Code/amiexpress_doors/Archives/AmiExpress/PROLZX.LZX',NULL,'XIM','pROlZX',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'auto-added',30574,0,0,NULL,NULL,'prolzx','scan',1780048671);
INSERT INTO door_catalog VALUES('prot192','PROT192.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PROT192.LHA',NULL,'XIM','Protector','1.92','Guru',NULL,'prevent your BBS from beeing blocked by Guru Meditations and Requesters.',replace('Protector v1.92 - The Protector is able to\nprevent your BBS from beeing blocked by Guru\nMeditations and Requesters.\n','\n',char(10)),'Protector_D.Guide',replace('@DATABASE "Protector.guide"\n\n## Dieses Docfile ist im amigaguide.library Format. Benutze AmigaGuide/\n## HyperText/Multiview um es korrekt anzeigen zu lassen oder benutze ein-\n## fach dein Lieblings ASCII-Anzeigeprogramm da diese Anleitung auch fuer\n## menschliche Augen lesbar ist.\n\n@WIDTH 80 \n@NODE MAIN "Protector"\n\n                                 ProtectorV1.92\n                            BBS-Sichereits-Programm\n\n Wie jeder leicht in der Geschichte sehen kann, gab es eine grosse Verzoegerung\n   zwischen den Versionen 1.7 und 1.8. Vor Version 1.8 habe ich alle 3 Monate\n  eine neue Version veroeffentlicht und Version 1.8 war nach dieser Zeit auch\n    fast fertig. Aber nachdem mir niemand etwas schickte (keine Mails, keine\n  Registrierung, NICHTS) seit der Veroeffentlichung von Version 1.6, habe ich\n      mein Interesse an diesem Projekt verloren und ich habe _nichts_ mehr\n veroeffentlicht, fuer ueber ein Jahr. Aber es hat mich krank gemacht ein paar\n  nette Tools zu haben und nur einen, der sie benutzt, naemlich mich. So habe\n ich begonnen, meine Arbeiten wieder zu veroeffentlichen und ich habe auch den\n   Protector vollendet. Er hat nun alle Features, die ich brauche und laeuft\n               sauber, also wird es die endgueltige Version sein.\n\n  Da V1.8 nicht korrekt mit Grafikkarten laeuft, habe ich einen neuen Release\n                gemacht, welcher dieses Problem beheben sollte.\n\n                                 @{"BESCHREIBUNG" LINK DESCRIPTION}\n                                 @{" KOPIERRECHT" LINK COPYRIGHT}\n                                 @{" ERKLAERUNG " LINK DISCLAIMER}\n                                 @{"   INHALT   " LINK CONTENTS}\n                                 @{"  BENUTZUNG " LINK USAGE}\n                                 @{"   EXTRAS   " LINK FEATURES}\n                                 @{" GESCHICHTE " LINK HISTORY}\n                                 @{"    DANKE   " LINK THANX}\n                                 @{"   FEHLER   " LINK BUGS}\n                                 @{"    PLÄNE   " LINK PLANS}\n                                 @{"  SHUTDOWN  " LINK SHUTDOWN}\n                                 @{"   SUPPORT  " LINK SUPPORT}\n                                 @{"   KONTAKT  " LINK CONTACT}\n                                 @{"   LYRICS   " LINK LYRICS}\n\n@ENDNODE\n===============================================================================\n@NODE COPYRIGHT\n                                  KOPIERRECHT\n\n          Der Protector ist Shareware © 1993-1995 von @{"Peter Stegemann" LINK CONTACT}.\n\n       Wer dieses Programm mag und benutzt, muss es fuer 15.- DM bei mir\n   registrieren, wer gleich die neueste Version haben will, muss noch 5.- DM\n   drauflegen und mir Bescheid geben, welche Version er im Moment hat und wie\n     ich ihm die neue zukommen lassen soll (z.b. Brief oder Crash). Wer im\n   Ausland wohnt, sollte 10.- DM dazulegen. Kommentarlose Geldsendungen sehe\n                         ich dankbar als Spenden an :-)\n            \n                            Alle Rechte vorbehalten.\n\n          Kickstart 2.04 und Workbench 2.0 sind Copyright © 1985-1992\n                           der Commodore-Amiga, Inc.\n\n               ShutDown 2.0 ist Copyright © 1992 by Olaf Barthel.\n\n@ENDNODE\n===============================================================================\n@NODE DISCLAIMER\n                                   ERKLAERUNG\n\n   Dieses Softwarepacket ist frei verteilbar, solange wie keine Files dieses\n   Archives veraendert oder entfernt werden. Es ist nicht erlaubt, Geld fuer\n  das verteilen und kopieren zu verlangen, jeglicher Vertrieb ueber Firmen ist\n  illegal! Erlaubt ist das verbeiten ueber die AmiNet- und die Fred-Fish-CDs.\n\n Diese Software ist "wie sie ist". Es werden keine Garantien vergeben in Bezug\n    auf die Nuetzlichkeit, Leistung und Sicherheit dieser Software und jede\nBenutzung geschieht auf dein eigenes Risiko. Der Autor ist nicht verantwortlich\n   fuer jeglichen Schaden, der durch deine Nutzung dieser Software entsteht.\n\n@ENDNODE\n===============================================================================\n@NODE CONTENTS\n                                    INHALT\n\nDieses Softwarepaket besteht aus folgenden Files:\n\nProtector               - das Programm selbst.\nProtector.info          - sein Piktogramm.\n\nProtector_E.Guide       - die englische Amigaguide-Anleitung.\nProtector_E.Guide.info  - sein Piktogram.\n\nProtector_D.Guide       - die deutsche Amigaguide-Anleitung.\nProtector_D.Guide.info  - sein Piktogram.\n\nLibs/Shutdown.library   - die shutdown.library von Olaf Barthel.\n\n@ENDNODE\n===============================================================================\n@NODE DESCRIPTION\n                                  BESCHREIBUNG\n\n       Der Protector kann deinen Rechner davor schuetzen, von Alerts oder\n                        Requestern blockiert zu werden.\n\n         Er benoetigt @{"Kickstart 2.04" LINK COPYRIGHT}, @{"Workbench 2.0" LINK COPYRIGHT} oder besser\n               und die @{"shutdown.library" LINK SHUTDOWN}.\n\n    Der Protector besitzt eine korrekte VersionID im CBM-Format, welche mit\n      dem Shell-Kommando VERSION der Workbench 2.0 angezeigt werden kann.\n\n      Alle Programmkomponenten wurden getested mit dem Enforcer V37.28 und\n                              dem MungWall V37.55.\n\n@ENDNODE\n===============================================================================\n@NODE USAGE\n                                   BENUTZUNG\n\n  Lege den Protector einfach in das WBStartup-Verzeichniss oder starte ihn vom\n CLI aus. Um ihn zu entfernen musst du ihn einfach noch einmal starten, oder du\n                   benutzt das Commodities Exchange Programm.\n\n Die CLI-Argumente und Tooltypes sind:\n \n CX_POPUP/K                 - Oeffne das Fenster beim Start.\n                              Default: An.\n DISABLED/S                 - Deaktiviere den Protector beim Start.\n                              Default: Aus. (Enabled)\n LOGFILE/K                  - Filename fuer das Log.\n                              Default: Aus ("").\n ENABLECMD/K                - Kommando, das beim aktivieren ausgefuehrt wird.\n                              Default: Execute S:ProtectorEnableCMD.\n DISABLECMD/K               - Kommando, das beim deaktivieren ausgefuehrt wird.\n                              Default: Execute S:ProtectorDisableCMD.\n SHUTDOWNCMD/K              - Kommando, das beim Shutdown ausgefuehrt wird.\n                              Default: Execute S:ProtectorShutDownCMD.\n XPOS/N                     - X-Position des Protector-Fensters.\n                              Default: 0.\n YPOS/N                     - Y-Position des Protector-Fensters.\n                              Default: Unter dem Titelbalken.\n MAXEVENTS/N                - Die maximale Zahl der Ereignisse (Requester,\n                              Alerts), die in 10 Sekunden auftreten duerfen.\n                              Default: Aus.\n REQDELAY/N                 - Die Zeit, nach der ein Requester automatisch ge-\n                              canceled wird.\n                              Default: Aus.\n RETRYMATCH/K               - Wenn ein Requestertext mit diesem Text anfaengt,\n                              wird der Requester retried, nicht gecancelt.\n                              Default: off\n\n                                DEAKTIVIERT IN UNREGISTRIERTER VERSION\n\n TRAPPATCH/S                - Aktiviert das Patchen der Trapvektoren. Dadurch\n                              fuehren folgende Exceptions sofort zum Reset:\n\n                                BusError\n                                AddressError\n                                IllegalInstruction\n                                DivisionByZero\n\n                              Ein Logfileeintrag wird _nicht_ vorgenommen.\n\n                              Warnung: Die Chance, dass dieses "Feature" das\n                              System eher stoert als dass es ihm nuetzt, ist\n                              hoch. Ich rate von der Aktivierung ab.\n                              Default: Aus.\n\n@ENDNODE\n===============================================================================\n@NODE FEATURES\n                                    EXTRAS\n\n - Nutzt die @{"shutdown.library" LINK SHUTDOWN} fuer einen Reset.\n - Leicht entfernbar, da es ein Commodity ist.\n - Fenster mit Aktivierungsschalter.\n - Sichere Rueckpatchroutinen.\n - Unterstuetzt CLI-Argumente und Tooltypes.\n - Legt ein Logfile an.\n - Fensterpositionen lassen sich angeben.\n - Loesst einen Shutdown aus, wenn mehr als eine Angegebene Zahl von Requestern\n   und Alerts innerhalb von 10 Sekunden ausgeloest werden.\n - Kann Kommandos beim An- und Abschalten sowie beim ShutDown ausfuehren.\n - Canceled Requester nach einer definierten Zeit.\n - Kann bestimmt Requester retryen.\n\n@ENDNODE\n===============================================================================\n@NODE HISTORY\n                                  GESCHICHTE\nV1.0>\n\n  - Requester werden gepatched.\n  - Alerts werden gepatched.\n  - Fenster zum Entfernen.\n\nV1.1> (19.03.93)\n\n  - Verbesserter Code.\n  - Wartezeit vor dem Reset.\n\nV1.2> (03.08.93)\n\n  - Umprogrammiert zum Commodity.\n  - Fenster entfernt.\n\nV1.3> (29.08.93)\n\n  - Fenster mit Aktivierungsknopf eingefuegt.\n  - CLI-Args eingefuegt.\n  - Tooltypes eingefuegt.\n\nV1.4> (02.11.93)\n\n  - Logfile hinzugefuegt.\n  - Reset auf Shutdown geaendert.\n\nV1.5> (30.12.93)\n\n  - Fensterpositionen hinzugefuegt.\n  - Maxevents hinzugefuegt.\n  - Logfileausgabe ueberarbeitet.\n\nV1.6> (01.03.94)\n\n  - EnableCMD und DisableCMD hinzugefuegt.\n  - Fenster ist jetzt Fontsensitiv.\n  - Code etwas ueberarbeitet.\n\nV1.7> (03.05.94)\n\n  - ShutDownCMD hinzugefuegt.\n  - Verzoegerte Requester hinzugefuegt.\n  - Code weiter ueberarbeitet.\n  - Deadlocks bei Logfileproblemen entfernt.\n  - Kleinere Fehler in der Logfileausgabe entfernt.\n  - Der Protector ist jetzt Shareware.\n\nV1.8> (22.03.95)\n\n  - Schwerer BUG in den Rueckpatchroutinen entfernt.\n  - Trappatch hinzugefuegt.\n  - Logfileroutinen ueberarbeitet.\n\nV1.9> (06.05.95)\n\n  - Easyrequestargs-funktion an Grafikkarten angepasst.\n  - Retrymatch hinzugefuegt.\n\n@ENDNODE\n===============================================================================\n@NODE BUGS\n                                     FEHLER\n\n     Um richtig zu funktionieren muss der Protector unbedingt _nach_ Tools\n                           wie ARQ gestartet werden.\n\n    Das Logfile sollte man unbedingt auf eine eigene Partition legen, da das\n        Risiko, dass das System beim schreiben abstuerzt, waehrend einer\n        Fehlfunktion natuerlich hoeher ist. Eine winzige Partition fuer\n                    Logfiles sollte jeder entbehren koennen!\n\n@ENDNODE\n===============================================================================\n@NODE THANX\n                                     DANKE\n\n Ein besonderes Dankeschoen geht an folgende Leute:\n\n Robert Hofmann    - fuer Tips, Vorschlaege, Betatests und Support.\n Olaf Barthel      - fuer sein Shutdownsystem.\n Eric Delord       - einziger registrierter User & Spender.\n Thomas Soeffing   - durch den ich herrausfand, dass die shutdown.library in\n                     Version 1.5 xpk-gepackt war. (Mist) :-(\n\n@ENDNODE\n===============================================================================\n@NODE PLANS\n                                     PLÄNE\n\n Folgendes will ich noch in den Protector einbauen:\n\n - Alle Bugs finden :-)\n - RETRYMATCH mit Patternmatching.\n \n@ENDNODE\n===============================================================================\n@NODE SHUTDOWN\n                                   SHUTDOWN\n\n    Das @{"Shutdownsystem" LINK COPYRIGHT} von @{"Olaf Barthel" LINK THANX} dient dazu, einen Reset so lange\n        zu verzoegern, bis alle Filezugriffe beendet sind. Um die volle\n   Funktionsfaehigkeit des Shutdownsystems zu garantieren, muss es aber auch\n  komplett installiert werden. Die shutdown.library wird nur mit diesem Paket\n   mitgeliefert, damit der Protector auch sofort einsetzbar ist. Um Shutdown\n    voll nutzen zu koennen, sollte man sich daher das gesamte Paket besorgen\n                               und installieren.\n\n@ENDNODE\n===============================================================================\n@NODE SUPPORT\n                                    SUPPORT\n\n Neue Versionen des Protectors und das Shutdownsystem sind bei mir zu beziehen.\n     Wer moechte, kann sich die neueste Version auch gegen einen Betrag von\n        10.- von mir zukommen lassen, sofern er bereits registriert ist!\n\n@ENDNODE\n===============================================================================\n@NODE CONTACT\n                                    KONTAKT\n\n          Fuer Tips, Fehlerreporte und Geld bin ich erreichbar unter:\n\n                 Schneckenpost: Peter Stegemann\n                                 Unter Stad 56\n                                79353 Bahlingen\n\n                         Kohle: 3260 59-759\n                                Postbank Karlsruhe\n                                660 100 75\n\n                       Fidonet: 2:2476/[email removed]\n                        Gernet: 21:498/[email removed]\n                      Amiganet: 39:173/[email removed]\n                          NeST: 90:400/[email removed]\n                       Fido.de: 242:2000/[email removed]\n                        Usenet: [email removed]\n                         Voice: +49(0)7663-912011\n                          Data: +49(0)7663-50103  (ZyX16k8)\n                                +49(0)7663-912013 (X.75/V.110)\n\n@ENDNODE\n===============================================================================\n@NODE LYRICS\n                                    LYRICS\n\n                        Anything that happens, happens.\n         Anything that, in happening, causes something else to happen,\n                        causes something else to happen.\n   Anything that, in happening, causes itself to happen again, happens again.\n          It doesn`t necessarily do it in chronological order, though.\n\n                    by Douglas Adams, in "Mostly Harmless".\n\n@ENDNODE\n\n','\n',char(10)),NULL,'auto-added',31478,5,0,NULL,NULL,'prot192','scan',1780048671);
INSERT INTO door_catalog VALUES('protec17','PROTEC17.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PROTEC17.LHA',NULL,'XIM','Protector',NULL,NULL,NULL,NULL,'Protector...A very neat BBSGuard!','Protector_D.Guide',replace('@DATABASE "Protector.guide"\n\n## Dieses Docfile ist im amigaguide.library Format. Benutze AmigaGuide/\n## HyperText/Multiview um es korrekt anzeigen zu lassen oder benutze ein-\n## fach dein Lieblings ASCII-Anzeigeprogramm da diese Anleitung auch fuer\n## menschliche Augen lesbar ist.\n\n@WIDTH 80 \n@NODE MAIN "Protector"\n\n                                 ProtectorV1.7\n                            BBS-Sichereits-Programm\n\n                                 @{"BESCHREIBUNG" LINK DESCRIPTION}\n                                 @{" KOPIERRECHT" LINK COPYRIGHT}\n                                 @{" ERKLAERUNG " LINK DISCLAIMER}\n                                 @{"   INHALT   " LINK CONTENTS}\n                                 @{"  BENUTZUNG " LINK USAGE}\n                                 @{"   EXTRAS   " LINK FEATURES}\n                                 @{" GESCHICHTE " LINK HISTORY}\n                                 @{"    DANKE   " LINK THANX}\n                                 @{"   FEHLER   " LINK BUGS}\n                                 @{"    PLÄNE   " LINK PLANS}\n                                 @{"  SHUTDOWN  " LINK SHUTDOWN}\n                                 @{"   SUPPORT  " LINK SUPPORT}\n                                 @{"   KONTAKT  " LINK CONTACT}\n                                 @{"   LYRICS   " LINK LYRICS}\n\n@ENDNODE\n\n===============================================================================\n@NODE COPYRIGHT\n                                  KOPIERRECHT\n\n          Der Protector ist Shareware © 1993-1994 von @{"Peter Stegemann" LINK CONTACT}.\n\n      Wer dieses Programm mag und benutzt, sollte es fuer 15.- DM bei mir\n   registrieren, wer gleich die neueste Version haben will, muss noch 5.- DM\n   drauflegen und mir bescheid geben, welche Version er im Moment hat und wie\n     ich ihm die neue zukommen lassen soll (z.b. Brief oder Crash). Wer im\n   Ausland wohnt, sollte 10.- DM dazulegen. Kommentarlose Geldsendungen sehe\n                         ich dankbar als Spenden an :-)\n            \n                            Alle Rechte vorbehalten.\n\n          Kickstart 2.04 und Workbench 2.0 sind Copyright © 1985-1992\n                           der Commodore-Amiga, Inc.\n\n               ShutDown 2.0 ist Copyright © 1992 by Olaf Barthel.\n\n@ENDNODE\n\n===============================================================================\n@NODE DISCLAIMER\n                                   ERKLAERUNG\n\n   Dieses Softwarepacket ist frei verteilbar, solange wie keine Files dieses\n   Archives veraendert oder entfernt werden. Es ist nicht erlaubt, Geld fuer\n  das verteilen und kopieren zu verlangen, jeglicher Vertrieb ueber Firmen ist\n  illegal! Erlaubt ist das verbeiten ueber die AmiNet- und die Fred-Fish-CDs.\n\n Diese Software ist "wie sie ist". Es werden keine Garantien vergeben in Bezug\n    auf die Nuetzlichkeit, Leistung und Sicherheit dieser Software und jede\nBenutzung geschieht auf dein eigenes Risiko. Der Autor ist nicht verantwortlich\n   fuer jeglichen Schaden, der durch deine Nutzung dieser Software entsteht.\n\n@ENDNODE\n\n===============================================================================\n@NODE CONTENTS\n                                    INHALT\n\nDieses Softwarepaket besteht aus folgenden Files:\n\nProtector               - das Programm selbst.\nProtector.info          - sein Piktogramm.\n\nProtector_E.Guide       - die englische Amigaguide-Anleitung.\nProtector_E.Guide.info  - sein Piktogram.\n\nProtector_D.Guide       - die deutsche Amigaguide-Anleitung.\nProtector_D.Guide.info  - sein Piktogram.\n\nLibs/Shutdown.library   - die shutdown.library von Olaf Barthel.\n\n@ENDNODE\n\n===============================================================================\n@NODE DESCRIPTION\n                                  BESCHREIBUNG\n\n       Der Protector kann deinen Rechner davor schuetzen, von Alerts oder\n                        Requestern blockiert zu werden.\n\n         Er benoetigt @{"Kickstart 2.04" LINK COPYRIGHT}, @{"Workbench 2.0" LINK COPYRIGHT} oder besser\n               und die @{"shutdown.library" LINK SHUTDOWN}.\n\n    Der Protector besitzt eine korrekte VersionID im CBM-Format, welche mit\n      dem Shell-Kommando VERSION der Workbench 2.0 angezeigt werden kann.\n\n      Alle Programmkomponenten wurden getested mit dem Enforcer V37.28 und\n                              dem MungWall V37.55.\n\n@ENDNODE\n\n===============================================================================\n@NODE USAGE\n                                   BENUTZUNG\n\n  Lege den Protector einfach in das WBStartup-Verzeichniss oder starte ihn vom\n CLI aus. Um ihn zu entfernen musst du ihn einfach noch einmal starten, oder du\n                   benutzt das Commodities Exchange Programm.\n\n Die CLI-Argumente und Tooltypes sind:\n \n CX_POPUP/K                 - Oeffne das Fenster beim Start.\n                              Default: An.\n DISABLED/S                 - Deaktiviere den Protector beim Start.\n                              Default: Aus. (Enabled)\n LOGFILE/K                  - Filename fuer das Log.\n                              Default: Aus ("").\n ENABLECMD/K                - Kommando, das beim aktivieren ausgefuehrt wird.\n                              Default: Execute S:ProtectorEnableCMD.\n DISABLECMD/K               - Kommando, das beim deaktivieren ausgefuehrt wird.\n                              Default: Execute S:ProtectorDisableCMD.\n SHUTDOWNCMD/K              - Kommando, das beim Shutdown ausgefuehrt wird.\n                              Default: Execute S:ProtectorShutDownCMD.\n XPOS/N                     - X-Position des Protector-Fensters.\n                              Default: 0.\n YPOS/N                     - Y-Position des Protector-Fensters.\n                              Default: Unter dem Titelbalken.\n MAXEVENTS/N                - Die maximale Zahl der Ereignisse (Requester,\n                              Alerts), die in 10 Sekunden auftreten duerfen.\n                              Default: Aus.\n REQDELAY/N                 - Die Zeit, nach der ein Requester automatisch ge-\n                              canceled wird.\n                              Default: Aus.\n\n@ENDNODE\n\n===============================================================================\n@NODE FEATURES\n                                    EXTRAS\n\n - Nutzt die @{"shutdown.library" LINK SHUTDOWN} fuer einen Reset.\n - Leicht entfernbar, da es ein Commodity ist.\n - Fenster mit Aktivierungsschalter.\n - Sichere Rueckpatchroutinen.\n - Unterstuetzt CLI-Argumente und Tooltypes.\n - Legt ein Logfile an.\n - Fensterpositionen lassen sich angeben.\n - Loesst einen Shutdown aus, wenn mehr als eine Angegebene Zahl von Requestern\n   und Alerts innerhalb von 10 Sekunden ausgeloest werden.\n - Kann Kommandos beim An- und Abschalten sowie beim ShutDown ausfuehren.\n - Canceled Requester nach einer definierten Zeit.\n\n@ENDNODE\n\n===============================================================================\n@NODE HISTORY\n                                  GESCHICHTE\nV1.0>\n\n  - Requester werden gepatched.\n  - Alerts werden gepatched.\n  - Fenster zum Entfernen.\n\nV1.1> (19.03.93)\n\n  - Verbesserter Code.\n  - Wartezeit vor dem Reset.\n\nV1.2> (03.08.93)\n\n  - Umprogrammiert zum Commodity.\n  - Fenster entfernt.\n\nV1.3> (29.08.93)\n\n  - Fenster mit Aktivierungsknopf eingefuegt.\n  - CLI-Args eingefuegt.\n  - Tooltypes eingefuegt.\n\nV1.4> (02.11.93)\n\n  - Logfile hinzugefuegt.\n  - Reset auf Shutdown geaendert.\n\nV1.5> (30.12.93)\n\n  - Fensterpositionen hinzugefuegt.\n  - Maxevents hinzugefuegt.\n  - Logfileausgabe ueberarbeitet.\n\nV1.6> (01.03.94)\n\n  - EnableCMD und DisableCMD hinzugefuegt.\n  - Fenster ist jetzt Fontsensitiv.\n  - Code etwas ueberarbeitet.\n\nV1.7> (03.05.94)\n\n  - ShutDownCMD hinzugefuegt.\n  - Verzoegerte Requester hinzugefuegt.\n  - Code weiter ueberarbeitet.\n  - Deadlocks bei Logfileproblemen entfernt.\n  - Kleinere Fehler in der Logfileausgabe entfernt.\n  - Der Protector ist jetzt Shareware.\n\n@ENDNODE\n\n===============================================================================\n@NODE BUGS\n                                     FEHLER\n\n     Um richtig zu funktionieren muss der Protector unbedingt _nach_ Tools\n                           wie ARQ gestartet werden.\n\n    Das Logfile sollte man unbedingt auf eine eigene Partition legen, da das\n        Risiko, dass das System beim schreiben abstuerzt, waehrend einer\n        Fehlfunktion natuerlich hoeher ist. Eine winzige Partition fuer\n                    Logfiles sollte jeder entbehren koennen!\n\n@ENDNODE\n\n===============================================================================\n@NODE THANX\n                                     DANKE\n\n Ein besonderes Dankeschoen geht an folgende Leute:\n\n Robert Hofmann    - fuer Tips, Vorschlaege, Betatests und Support.\n Olaf Barthel      - fuer sein Shutdownsystem.\n Eric Delord       - erster registrierter User & Spender.\n Thomas Soeffing   - durch den ich herrausfand, dass die shutdown.library in\n                     Version 1.5 xpk-gepackt war. (Mist) :-(\n\n@ENDNODE\n\n===============================================================================\n@NODE PLANS\n                                     PLÄNE\n\n Folgendes will ich noch in den Protector einbauen:\n\n - Trapvektoren verbiegen (Hack!).\n - Alle Bugs finden :-)\n - Support fuer GFA-Basic-Requester.\n \n@ENDNODE\n\n===============================================================================\n@NODE SHUTDOWN\n                                   SHUTDOWN\n\n    Das @{"Shutdownsystem" LINK COPYRIGHT} von @{"Olaf Barthel" LINK THANX} dient dazu, einen Reset so lange\n        zu verzoegern, bis alle Filezugriffe beendet sind. Um die volle\n   Funktionsfaehigkeit des Shutdownsystems zu garantieren, muss es aber auch\n  komplett installiert werden. Die shutdown.library wird nur mit diesem Paket\n   mitgeliefert, damit der Protector auch sofort einsetzbar ist. Um Shutdown\n    voll nutzen zu koennen, sollte man sich daher das gesamte Paket besorgen\n                               und installieren.\n\n@ENDNODE\n\n===============================================================================\n@NODE SUPPORT\n                                    SUPPORT\n\n  Neue Versionen des Protectors und das Shutdownsystem sind bei Robert Hofmann\n  in der "Professional Amiga" oder von mir zu beziehen. Wer moechte, kann sich\n     die neueste Version auch gegen einen Betrag von 10.- von mir zukommen\n                  lassen, sofern er bereits registriert ist!\n\n               Sysop: Robert Hofmann\n            BBS Name: Professional Amiga ISDN Multiline\n     Phone Number(s): ZyXEL 19.2k: +49(0)911-429747, ISDN: -994168-1, -2\n     Network Address: 2:2490/1015@fidonet, 39:171/101@amiganet\n                      16:100/9024@zyxelnet, 47:52/23@fisnet\n              Online: 24 hours (filerequests only!)\n\n@ENDNODE\n\n===============================================================================\n@NODE CONTACT\n                                    KONTAKT\n\n          Fuer Tips, Fehlerreporte und Geld bin ich erreichbar unter:\n\n                 Schneckenpost: Peter Stegemann\n                                 Unter Stad 56\n                                79353 Bahlingen\n\n                          Geld: 3260 59-759\n                                Postbank Karlsruhe\n                                660 100 75\n\n                          Fido: 2:2476/[email removed]\n                           Ger: 21:492/[email removed]\n                          Kult: 23:550/[email removed]\n                         Amiga: 39:171/XXX@amiganet (Soon!)\n                          VNet: 46:9490/[email removed]\n                          NeST: 90:400/[email removed]\n                        FidoDe: 242:2000/[email removed]\n                      InterNet: [email removed]\n                         Voice: +49(0)7663-50103 (14.00 - 22.00)\n                          Data: +49(0)7663-50103 (22.00 - 14.00)\n                                 Nur Filerequests!\n \n                                 Magics: Files\n                                         Newfiles\n                                         Protector\n                                         SetPicasso\n\n@ENDNODE\n\n===============================================================================\n@NODE LYRICS\n                                    LYRICS\n\n                        Anything that happens, happens.\n         Anything that, in happening, causes something else to happen,\n                        causes something else to happen.\n   Anything that, in happening, causes itself to happen again, happens again.\n          It doesn`t necessarily do it in chronological order, though.\n\n                    by Douglas Adams, in "Mostly Harmless".\n\n@ENDNODE\n\n','\n',char(10)),NULL,'auto-added',23262,2,0,NULL,NULL,'protec17','scan',1780048671);
INSERT INTO door_catalog VALUES('prowho21','PROWHO21.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PROWHO21.LHA',NULL,'XIM','sonnenbrand.exe','2.1','Trebor.',NULL,'WHO replacement featuring auto-updating so you can watch what''s happening and an easy to use config editor like VisEd. CNet/3 and',replace('Professional Who v2.1 (4.5.97) by Trebor.\nWHO replacement featuring auto-updating so\nyou can watch what''s happening and an easy\nto use config editor like VisEd. CNet/3 and\nCNet 4.26e+ compatible.\n','\n',char(10)),'ProWho.guide',replace('@DATABASE "ProWho.guide"\n@$VER: Professional Who, v2.1 (04-May-97) by Trebor of The Funhouse BBS\n@NODE "MAIN" "Professional Who Version 2.1 04/05/1997 [Unregistered]"\n@TOC "MAIN"\n@{b}\n               Professional Who Version 2.1 [Unregistered]\n                   (C) 1997 by Robert Hewick (Trebor)\n                         Release Date: 04/05/97\n\n                  @{"The Funhouse BBS #1 [+44-1482-897738]" LINK "BBSAD}\n                  @{"The Funhouse BBS #2 [+44-1482-899792]" LINK "BBSAD}\n@{ub}\nThis software is subject to the "Standard Amiga FD-Software Copyright Note"\nIt is Mailware as defined in paragraph 4b. For more information please read\n                  @{"AFD-COPYRIGHT" link "AFD-COPYRIGHT/main"} (Version 1 or higher).\n\n@{"                               Copyright                                    " LINK "COPYRIGHT"    }\n@{"            What is Professional Who and why should i use it ?              " LINK "INTRO"        }\n@{"                  Registry and how to Contact Trebor!                       " LINK "REGISTRY"     }\n@{"                         What are the Features ?                            " LINK "FEATURES"     }\n@{"                         Files in this archive                              " LINK "FILES"        }\n@{"            Click here to view SnapShots of ProWho in action!               " LINK "SNAPSHOTS"    }\n\n@{"               How do i  I N S T A L L  this Program then ?                 " LINK "INSTALLATION" }\n\n@{"             Upgrading Version 1.9  --> 2.1 [Public Release]                " LINK "UPGRADE3"     }\n@{"                     History of Professional Who                            " LINK "HISTORY"      }\n@{"                        Things for the Future                               " LINK "FUTURE"       }\n@{b}\n                         Thanks go to the following                           \n                                                                               \n     Nuts     (  MegaByte BBS  ) - for finding bugs (u were good at it)\n     Beast    ( Shelob`z Lair! ) - for being yourself:>\n     Duval    (   Duval City   ) - for the suggestions from you and Bob.\n     Jeepster (  The Avenues   ) - for Beta Testing.\n     Midi-Man ( Grounded Grid! ) - For testing it online (lots of times)!\n     Dotoron  ( Frontier''s BBS ) - for helping me with new Getusers!\n     Snoopy   (  Nirvana Zone  ) - for Beta Testing.\n     Hunter   ( Phantasy Island) - for listening to me all the time ;>\n     HMetal   (  Metal Shopee  ) - for continuing the support on CNet/4\n                                                                              \n                     If i missed anyone out then sorry!\n@{ub}\n@ENDNODE\n\n@NODE "BBSAD"        "T h e   F u n h o u s e   B B S   + 4 4 - 1 4 8 2 - 8 9 7 7 3 8 / 8 9 9 7 9 2"\n\n                Running on a 4ooo / o4o / 26Mb Ram                    \n                       ________________________                        \n                       \     ___/ |   \   ____/                       \n    AMIGA / PEEcEE      \/   |         \  __/__      6 GIG ONLINE     \n     ADULT / HPA        /    |    T    /      /        2 CDRoms       \n                       /_____|____|___/______/                        \n                 _        _                  _                        \n        ________| \_____ | \________________| \__________________     \n       |  _____/|  \    \|  \  |  \   _  \  |  \   ____/   _____/     \n       |  ___/  |   \    \   \     \ |/   \ |   \_____ \   __/__      \n       |   |    |    \ \     / T   / |    / |    \   |  \      /      \n       |___|_________/__\   /__|__/______/_______/______/_____/       \n                         \_/                                          \n     FidoNet 2:2502/24    AmigaNet 39:139/47    MegaNet 922:444/106   \n            69erNet WHQ - 96:69/0 - The Adult Network                 \n\n                 Email: [email removed]                  \n\n    Line#1:  +44 - 1482 - 897738    Line#2:  +44 - 1482 - 899792       \n     Sysops  Trebor / Hawk        Co-Sysops  Phillo / Midi-Man / Lat   \n\n@ENDNODE\n\n@NODE "INTRO"        "Introduction"\n\n     I Started this tool over a year a go now, and it has been vastly \n     improved since then!\n\n     I recommend you read the *WHOLE* of this Guide before you run this tool.\n\n     This Professional Tool is a Replacement for CNet`s "WHo" command,\n     Which allows auto updating instead of having to type WHo every second.\n     You can also configure it very easily with its built in Visual Editor.\n     \n     If you have more than one node this Tool will be used to its full \n     potential, making users life hell of lot easier, but if you only have\n     one node, it`s still better than the standard WHo :).\n\n     This program has been tested on the following machines sucessfully:-\n\n     Amiga 4000/040/26MEG RAM  -  CNet 4.26e <-- Mine :)\n     Amiga 4000/030            -  CNet 3.05\n     Amiga 2000                -  CNet 4.26\n     Amiga 1200/030	       -  CNet 3.05\n     Amiga 1200                -  CNet 3.05\n\n     If you find that this program does not work on your computer then \n     please inform me!\n\n@ENDNODE\n\n@NODE "COPYRIGHT"    "Copyright"\n                                                                  \n     This Professional Tool is Copyright (C)1997 by Trebor.  Freely usable. \n     Nobody is allowed to modify this Professional Tool or this Docfile\n     without permission!. \n\n@ENDNODE\n\n@NODE "SNAPSHOTS"    "Heres some snapshots of Professional Who In Action!"\n\n     If you don''t have Multiview installed then you will have look at the\n     snapshots some other way!, otherwise just click away:)\n\n     @{" ProWho1.IFF    " SYSTEM "MultiView Snapshots/ProWho1.IFF"} This is a snapshot of the main screen\n     @{" ProWho2.IFF    " SYSTEM "MultiView Snapshots/ProWho2.IFF"} This is a snapshot of me sending an olm in ProWho\n     @{" ProWho3.IFF    " SYSTEM "MultiView Snapshots/ProWho3.IFF"} This is a snapshot of me recieving an olm in ProWho\n     @{" ProConfig1.IFF " SYSTEM "MultiView Snapshots/ProConfig1.IFF"} This is a snapshot of the main screen in the config program\n     @{" ProConfig2.IFF " SYSTEM "MultiView Snapshots/ProConfig2.IFF"} This is a snapshot of the main screen changed\n     @{" ProConfig3.IFF " SYSTEM "MultiView Snapshots/ProConfig3.IFF"} This is a snapshot of me changing the Colours!\n\n@ENDNODE\n\n@NODE "REGISTRY"     "How to register, or contact Trebor!"\n\n     If you do not register this Tool, you will not be able to send OLM`s\n     in the program.  Registration is completely !FREE!.\n     This tool is Mail-Ware, if you wish to register this Professional tool\n     then all you have to do is write EMail or Snail Mail to me at the \n     following addresses.\n\n     [email removed]   [ Internet EMail ]\n     trebor@2:2502/24.0             [  FidoNet Mail  ]\n\n          Robert Hewick            [  Home address! ]\n        30 George Street,          [  Feel free to  ]\n          Hedon, Hull,             [ send donations ]\n      East Riding of Yorks.        [ for future up- ]\n         United Kingdom            [     dates      ]\n            HU12 8JH               [    direct.     ]\n\n     Run the program ProWho2.rexx with arguments REGISTER and then you\n     will find a file in RAM: called RegisterMe.txt. Simply Mail this\n     to me at any of the above addresses and you''ll recieve a keyfile\n                              F R E E \n                             of charge.\n\n              (eg. {#0 Pfiles:ProWho/ProWho2.rexx REGISTER}\n\n@ENDNODE\n\n@NODE "FEATURES"     "Features"\n                                                                     \n     + Auto updates, so you can watch people logging on/off and moving.\n     + Tells you when a New User is logging on unlike other WHo`s\n     + You can type WHO for a full WHO or type WH for a quick WHo!\n     + You can ask people to chat while using the Program\n     + You can send/receive OLM`s in the Program without quitting.\n     + You can change your WHo Banner while in the Program.\n     + You can hide from people and they wont know your there.\n     + You can skip Idle ports in the program by using CNet''s Config \n     + You can specify ports to watch, not just all of them.\n     + It''ss 100% Compatible with CNet 4.11-4.24  and CNet 3.05c\n     + Has an easy to use Config Editor.\n     + Easy to use for sysops, and especially for new Users.                        \n     + Has a very configurable look, you can change colours etc.\n     + Looks Nice.\n\n@ENDNODE\n\n@NODE "FILES"        "Files in the archive"\n     \n     In this archive you should have the following main files in a directory\n     call ProWho. (Excluding the adverts of cause:)\n\n     AFD-COPYRIGHT         7266 bytes - AFD Copyright Notice\n     ProWho.doc           13907 bytes - The ASCII documentation!\n     ProWho.guide         18206 bytes - Your looking at it :)!\n     ProWho2.rexx         24833 bytes - The main rexx file\n     ProConfig2.rexx      17496 bytes - The config editor\n     Snapshots              Directory - This directory contains snapshots \n\n     If these files do not have the correct names/sizes, please don''t run them\n     and report them to me immediately!\n\n@ENDNODE\n\n@NODE "INSTALLATION" "Installation"\n\n1.   Copy the programs ProWho2.rexx and ProConfig2.rexx to a directory.\n                         (Usually Pfiles:ProWho/)\n\n        @{"Click Here to copy files auto-matically to Pfiles:ProWho/" SYSTEM "Copy #? PFiles:ProWho"}\n\n2.   Next you must load up the file BBStext (Which is located in your CNet:)\n     into your favourite editor and change lines 42 and 62 so that they \n     read:-\n\nLine #42 : Add this to the    End    "#0Pfiles:ProWho/ProWho2.rexx NEW}"\nLine #62 : Add this to the Beginning "#0Pfiles:ProWho/ProWho2.rexx NEW}"\n                                      ^         ^-[ This is the path you choose ]\n                                      `-----------[      This is a CTRL+Q       ]\n\n     Then Save ''n Exit.\n\n                @{"Click here to choose your favourite Editor!" SYSTEM "SetEnv PWHO `RequestFile C:`"}\n\n              @{"Click here to load CNet:BBSText into an Editor!" SYSTEM "$PWHO CNet:BBSText"}\n\n3.   Next you must load up the file BBSMenu (Which is located in your CNet:)\n     into your favourite editor and perform the following changes under menu\n     "2; Available Everywhere"\n\n a.  Find the line which says WHo on it, once found change it to say\n     !WHo if not already done.\n\n b.  Goto the bottom of menu #2 and add these commands:-\n\n     WH              |       #0 Pfiles:ProWho/ProWho2.rexx   }\n     WHO             |       #0 Pfiles:ProWho/ProWho2.rexx   }\n     WHOCONFIG `31-  |       #0 Pfiles:ProWho/ProConfig2.rexx }\n                ^            ^          ^[ This is the path you choose ]\n                |            `-----------[      This is a CTRL+Q       ]\n                `----[    This allows only sysops to run the command   ] \n\n     Then Save ''n Exit.\n\n              @{"Click here to load CNet:BBSMenu into an Editor!" SYSTEM "$PWHO CNet:BBSMenu"}\n\n4.   Then you have to load the file "Systext:new/comp" into your favourite\n     editor and this line to the beginning \n     \n          #0 Pfiles:ProWho/ProWho2.rexx NEW NewUser}\n          ^          ^--------------[ You must know what this is by now :)\n          `-------------------------[ And this :)\n\n     Then Save ''n Exit.\n\n            @{"Click here to load Systext:new/comp into an Editor!" SYSTEM "$PWHO Systext:new/comp"}\n\n5.   Go to your control panel and type Right Amiga + T or use your mouse\n     to do a Text/Menu Reload!\n\n6.   Now that the hard bit is out of the way, you can configure this \n     Excellent tool:). \n\n     Login to your BBS and once at the main menu type "WHOCONFIG", this will\n     load a Vis Ed type screen, you should configure all of the parts to\n     suit your needs.  You can now configure the colours and some of the\n     wording in the Who program.\n\n7.   After you have successfully configured Professional Who, type WHO and\n     See if it works, if not then you have done something wrong.  Remember\n     that WH does a quick who.  If you have futhur problems, please email\n     me telling me what goes wrong.\n\n8.   Tell yours users about this program and send me (Trebor) loads of money:)\n\n@ENDNODE\n\n@NODE "UPGRADE3"     "Upgrading 1.9 --> 2.1 [Public Release]"\n\n     To upgrade from ProWho V1.9 to ProWho V2.1, just follow the steps.\n\n                @{"Click here to choose your favourite Editor!" SYSTEM "SetEnv PWHO `RequestFile C:`"}\n\n1.   Delete the all the files in the old ProWho directory\n\n       @{"Click Here to delete files auto-matically in Pfiles:ProWho/" SYSTEM "Delete PFiles:ProWho"}\n\n2.   Copy files ProWho2.rexx, and ProConfig2.rexx to your default directory \n     for ProWho (Usually Pfiles:ProWho/).\n\n       @{"Click Here to copy files auto-matically to Pfiles:ProWho/" SYSTEM "Copy #? PFiles:ProWho"}\n\n3.   Run the conversion program (Update2.rexx) from CNet and you will be\n     ready to go apart from the below ;>\n\n4.   Load CNet:BBSMenu into your favourite editor and locate the lines with\n     WHO, WHo, WHOCONFIG on and change the names from ProWho.rexx to\n     ProWho2.rexx, and also change ProConfig.rexx to ProConfig2.rexx\n\n              @{"Click here to load CNet:BBSMenu into an Editor!" SYSTEM "$PWHO CNet:BBSMenu"}\n\n5.   Next you must load up the file BBStext into your favourite editor and \n     change lines 42 and 62 so that they read instead of ProWho.rexx\n\nLine #42 : Add this to the    End    "#0Pfiles:ProWho/ProWho2.rexx NEW}"\nLine #62 : Add this to the Beginning "#0Pfiles:ProWho/ProWho2.rexx NEW}"\n                                      ^         ^-[ This is the path you choose ]\n                                      `-----------[      This is a CTRL+Q       ]\n\n              @{"Click here to load CNet:BBSText into an Editor!" SYSTEM "$PWHO CNet:BBSText"}\n\n6.   Also load the file "Systext:new/comp" into your favourite editor and \n     make sure you change it to ProWho2.rexx like below.\n     \n          #0 Pfiles:ProWho/ProWho2.rexx NEW NewUser}\n          ^          ^--------------[ You must know what this is by now :)\n          `-------------------------[ And this :)\n\n            @{"Click here to load Systext:new/comp into an Editor!" SYSTEM "$PWHO Systext:new/comp"}\n\n     ** DONT FORGET TO DO A TEXT/MENU RELOAD AND TO TRY OUT THE NEW **\n                         ** CONFIG PROGRAM **\n\n     ** ALSO REMEMBER THAT THE KEYFILE HAS CHANGED, YOU MUST EMAIL ME **\n                          ** FOR A NEW ONE **\n\n7.   That`s it, you have now installed Professional Who V2.0, if you find \n     any bugs you know what to do:).\n\n@ENDNODE\n\n@NODE "HISTORY"      "History of Professional Who"\n\n     V2.1     04/05/97   Re-Written Olm Routine to use new time stamping \n                         which was very complicated and took over 2 hours \n                         with help from Ken Hood.  Fixed little bugs.\n\n     V2.0h    27/04/97   Fixed bug in Be Right Back when it was Unregistered\n                         And fixed Olming not to work at all if its \n                         Unregistered.\n\n     V2.0g    25/04/97   Getusers have changed for CNet 4.26d, so had to\n                         put the new ones in, also Olming Routine has changed\n                         so it has a time stamp now, not fixed for ProWho\n                         but better than before!\n                         \n     V2.0f    04/04/97   Fixed bug with the Super user flag, and sum colour\n			 problems.\n\n     V2.0e    01/04/97   Finished NEW config editor, now able to change the\n			 all the main Colours in the Who program, and also\n                         Works fully with CNet 4.26.\n\n     V2.0c    23/03/97   Started working on NEW config editor, alowing you to\n                         change colours, etc!\n\n     V2.0b    17/02/97   Changeg Some getusers to work with the getuser shift!\n\n     V2.0a    01/01/97   Released to Beta testers, to find Bugs!\n\n     V2.0     07/12/96   Added Be Right Back option, and changed some wording.\n                                                                            \n     V1.9     24/10/96   Now works 100% with CNet V4.24, there was yet another\n                         bug with hiding/muffling, not  my fault, it was CNet''s:)\n                         Also added new feature for port arguments, i.e.\n                         Who 1 3-4 10, would only show Ports 1,3,4,and 10.\n                         And for people with CNet V4.2x i have added the Super\n                         User flag.\n\n     V1.8     05/09/96   Now works 100% with Cnet V4.21, there was a bug with\n                         hiding/muffling, not my fault, it was CNet''s :)\n\n     V1.7     01/09/96   Public Release and uploaded to Aminet!\n                         Changed olming routine, and now looks nicer and can\n                         handle upto 380 characters (ThanX to Duval).\n                         Also allowed the program to go over 10 ports (For you\n                         Lucky people out there with the money:))\n\n     V1.6b    28/07/96   Optimised Config editor to make it a bit faster \n                         and Fixed Hide, Muffle command on CNet 4.11+.\n                         Should now be 100% Compatible with CNet 4.11+ and\n                         CNet 3.05c!\n\n     V1.5b    24/07/96   Fixed bug in olm routine, and also added newuser\n                         part.\n\n     V1.4b    23/06/96   Added Vis Editor look config editor!\n\n     V1.1b    26/05/96   Made the program CNet 4.1xx compatible!\n\n     V1.0b    15/03/96   Total Rewrite, to make it faster!\n\n     V0.7b    19/01/96   Made the program receive OLM''s instead of quitting\n                                                                            \n     V0.6b    05/01/96   Made ports only refresh if something happens\n                         (Suggestion by Duval and Bob)\n\n     V0.5b    02/01/96   Added keyfile\n\n     V0.2b    26/12/95   Hide, Muffle command was added.\n\n     V0.1b    05/07/95   First Release.\n\n@ENDNODE\n\n@NODE "FUTURE"       "For the Future"\n\n     To allow you to see what file is been uploaded/downloaded on another port\n     and time to completion, while been in the Who!\n\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',54293,5,0,NULL,NULL,'prowho21','scan',1780048671);
