INSERT INTO door_catalog VALUES('psn_tst1','PSN-TST1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PSN-TST1.LHA',NULL,'XIM','X[ POiSON-TSTAT o ]÷[ 14''TH JUNE 1996 ]X','1.',NULL,'PSN','--- -- -  -                  -  - -- ---- iCE/pSN presents today a /X XiM door called POiSON-TRANSFERSTATS. It''s a simple FAST',replace('X[ POiSON-TSTAT v1.o ]÷[ 14''TH JUNE 1996 ]X\n --- -- -  -                  -  - -- ----\niCE/pSN presents today a /X XiM door called\nPOiSON-TRANSFERSTATS. It''s a simple FAST \ndoor to place in your download.txt or \nwherever u may want the user to be reminded\nabout his UL/DL stats.   BBS ADDS iS LAME!','\n',char(10)),'ami.doc',replace(':·········································································:\n:         _______           ___  ______   _______.   ___  ________        :\n:       ._\______|_ __      ___ / ____/_ _\______|_ .___ /·      ¬|       :\n:       |.    __////__\  __|:_¬Y.`\__  ¬Y.    __///''|. ¬Y  _______|_.     :\n:       |:    ¬'' |:  ¬\\/__///''|:  ¬''   |:    ¬'' |  |:  |___,      ¬|     :\n:       |:.      |:.   \/  |:. |:.      |:.      |  |:. |:.         |     :\n:       `--------^-----/___|---^--------^--------''  `---^-----------''     :\n:                                              /                          :\n:              _______ _____       ___        /_                          :\n:            ._\______Y_   /       ___ ______/ ¬\ ___________             :\n:            |.    __///__/_______|: ¬Y.    /    Y._ __,    ¬|            :\n:            |:    ¬'' |:\,       ¬|:  |:  \/     |///________|_.          :\n:            |:.      |:.         |:. |:.        |:.          ¬|          :\n:            `--------^-----------^---^----------^-----------!CE          :\n:                                                                         :\n:pOiSON hQ!, aSKEE oRDERiNG, aMiGA oNLY, pOiSON-dOORS, jAMMiNG, gOOD rATiO:\n:   nO nUP, eLiTE oNLY, nEW wAREZ,.. tHA cREW: iCE/pOiSON  rACOON/wARD    :\n:                                                                         :\n:              node 0: +46-037182218   node 1: +46-0371LOCAL              :\n:·········································································:\n','\n',char(10)),NULL,NULL,6796,1,0,NULL,NULL,NULL,'scan',1780048679);
INSERT INTO door_catalog VALUES('psn_wa1b','PSN-WA1B.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PSN-WA1B.LHA',NULL,'XIM','[POiSON-WALL]----[b]---[16''th MAY -96]','1.1','iCE/pOiSON','PSN','- the very best WALL-DOOR for /X with features never seen before like:',replace('[POiSON-WALL]----[v1.1b]---[16''th MAY -96]\n-\nthe very best WALL-DOOR for /X with \nfeatures never seen before like:\nmany walls, topadders, configureable \namount of lines, nice dezign, minimum axx\nfor each wall and a lot more details,...\npreview pics in tha archive!\n-\nNOTE!!: small bug in v1.1!!!fixed!!!!!\n-\n-------   coded by iCE/pOiSON   ----------\n','\n',char(10)),'poison-wall.doc',replace('               _____  _____  __   ______/\   _____  _______/\.\n    .---------/   ·:\/   ·:\/·:\./ _______\./   ·:\/    ·:|·:|-------.\n    .       ./       \      \__/|_______ ·:|       \    _ |  |iCE    .\n       __   |   __    \ o    \  |          |   o    \   | |  |   __\n      _\/_  | ________/      /  |          |        /   | `  |  _\/_\n      \/\/  |:._____|:._____/.__|:.________|:._____/.___|____|  \/\/\n \n        .---- -  -       -×÷ P R E S E N T S ÷×-       -  - ----.\n        :o                                                     o:\n        :                    POiSON-WALL v1.1                   :\n        :                                                       :\n        `-------------------------------------------------------''\n \n        .-------------------------------------------------------.\n        :·  All code, dezign and ideas by iCE/pOiSON 16-05-96  ·:\n        :                                                       :\n        `-------------------------------------------------------''\n \n        .-------------------------------------------------------.\n        :·                                                     ·:\n        :            This is a AIM door for /X 4.x              :\n        :                                                       :\n        `-------------------------------------------------------''\n \n        .-------------÷[ What the hell is it? ]÷----------------.\n        :·                                                     ·:\n        :   It is a wall door with a lot of features never      :\n        :   seen in wall-doors before. It is a clean rexx door  :\n        :   so it isn''t that VERY FAST wall, but it is fast     :\n        :   enough. It''s very configureable and thats one thing :\n        :   I like with doors like this one. Well, it''s a door  :\n        :   were the user can add his slogan in one of the many :\n        :   walls you can configure.                            :\n        :                                                       :\n        `-------------------------------------------------------''\n \n        .--------------÷[ Why did I made it? ]÷-----------------.\n        :·                                                     ·:\n        :   It''s a lot of wall-doors out there and it''s kinda   :\n        :   stupid to make another one. But if you look at the  :\n        :   other doors you can see there is none with features :\n        :   like this one, none I''ve seen. When I log into a    :\n        :   board and a wall comes up I got in a better mood.   :\n        :   But when I see tha sentences in the wall I nearly   :\n        :   gonna phuk!. They havn''t written about ANYTHING I   :\n        :   like to read about and if they have, one dumb idiot :\n        :   has changed the subject or one MEGADUMB idiot has   :\n        :   add a board-add and totally destroyed the whole     :\n        :   wall. That''s things which makes peoples MAD!        :\n        :   ( sorry, my english isn''t the very best! )          :\n        :                                                       :\n        `-------------------------------------------------------''\n \n        .--------------------÷[ FEATURES ]÷---------------------.\n        :·                                                     ·:\n        :   · It has more than 1 wall.                          :\n        :   · Nice dezign, by me ofcoz! =)                      :\n        :   · Top adders                                        :\n        :   · Many stats like new add since last on and so on.  :\n        :   · Very configureable:                               :\n        :            - Amount of lines in the walls..           :\n        :            - Wall names and amount of walls..         :\n        :            - Anonyous option.                         :\n        :            - Wall comment were you can place the      :\n        :              rules or subject of the wall..           :\n        :            - Different axx for tha walls.             :\n        :            - Write a line to callerslog?              :\n        :            - Bulletinfile for the topadders?          :\n        :   · Help function.                                    :\n        :   · Colours and anonymous option when adding.	        :\n        :   · Logfile for every wall.                           :\n        :                                                       :\n        `-------------------------------------------------------''\n \n        .-------------------÷[ INSTALLING ]÷--------------------.\n        :·                                                     ·:\n        :   It''s kinda simple. Just                             :\n        :                                                       :\n        :   · Copy everything in doors/ into your doors:        :\n        :   · Copy wall.info to your bbs:commands/bbscmd/       :\n        :   · Add ~CC_WALL to your logon.txt                    :\n        :                                                       :\n        :   Then it''s time to configure the wall, it is working :\n        :   with the default config,..                          :\n        :                                                       :\n        `-------------------------------------------------------''\n\n        .---------------------÷[ HiSTORY ]÷---------------------.\n        :·                                                     ·:\n        :   v1.o  - No history yet!                             :\n        :   v1.1  - Changed logo and some other dezign,.        :\n        :           Added axx for each wall                     :\n        :           Fixed a bug in topadders                    :\n        :           Made the hole thing safer from crashing,.   :\n        :                                                       :\n        `-------------------------------------------------------''\n \n        .----------------÷[ OTHER DOORS FROM ME ]÷--------------.\n        :·                                                     ·:\n        :                                                       :\n        :   · POiSON-ORDER    a simple ascii-order door         :\n        :   · POiSON-CALLERS  not released!,.. it suxx! =(      :\n        :   · POiSON-STAT     kinda crazy one,..                :\n        :   · BAUD-CHECKER    in cooperation with dEAMO.        :\n        :                                                       :\n        `-------------------------------------------------------''\n\n         -------------÷[ FOR SUPPORT HAVE A CALL TO ]÷----------\n\n        ____________.______  _____________  __________    ____________.\n     ___\______    _|\     \/     _(______)_\   _____/____\______     | \n     \       _     \       \/     \       |     \      \       _      | \n      \      \      \_______\      \      |     _\      \      \      |  \n       \____________| pHS!/_______/ \_____|______________\____________|\n            _ __ __                                     __ __ _          \n   _   _ __ ___ /\_\      [¡?] i S  A L i V E [!¿]     /_/\ ___ __ _   _ \n            _ __\/_/                                   \_\/__ _          \n\n             AMiGA iS ALiVE fEATURES: iCE/pOiSON, rACOON/wARd  \n A12oo/4MB OF RAM, 14k4, /X 4.9, AMiGAFiLES! , pEZE STUFF KiND''a HATED  \n    AMiGALAND,jAMMERS iNN,DEMOMANiA,/X SUPPORT,COMPOS,CODERSHiDEOUT,\n ARTS,REQUESTED FiLES... AND ONE OF THE FiNEST CONF iN SWEDEN: LAMERSHOLE!\n CALL iT!, iT WONT BE DiSAPPOiNTMENT! NUMBER: +46(O)371-82218 (24H OFCOZ!)\n              WE JUST W8iNG FOR YOUR CALL! DON''T HESiTATE!\n                   Down during the nights!!!! sorry!\n','\n',char(10)),NULL,NULL,23166,2,0,NULL,NULL,NULL,'scan',1780048679);
INSERT INTO door_catalog VALUES('psn_xs10','PSN-XS10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PSN-XS10.LHA',NULL,'XIM','ward.exe',NULL,NULL,'PSN','| | |)\--.-:--------.--.  / /   \o·/ | | <./o : :__--\''o  \ \\/ /    / ^\ |.`-/`---''-''----''----''--\_/!ce   \/|',replace('  .- ___----_----------------__---_/\_\n  | | |)\--.-:--------.--.  / /   \o·/\n  | | <./o : :__--\''o  \ \\/ /    / ^\\n  |.`-/`---''-''----''----''--\_/!ce   \/|\n  |`--÷> P R E S E N T S ÷-----------|\n  |...                      ÷1÷9÷9÷6 |\n  |: `-÷ /X-STARTER v1.00 <÷------.  |.\n  |:                              `--/\n  |: A TOOL TO STARTUP /X WHEN      //\n  |: YOUR COMPUTER FUCK-UP!        //\n  |:........... .... ... .. .     //\n  `------------------------------''/\n                                 .\n','\n',char(10)),'AmiE-starter.doc',replace('          .\n               o                       °   .                 .\n _ _ __________________/\__ .                        .            __/\__\n ..     ..  :::        ·. /  _________________/\            ______\ O- /\n   ..  .  .:::       /_^ _\_/::            ____/__    °   __):::::/_\/_\\n    ..  .::.         / \/   ::             /      \       \:::···    /  .\n  _ ___________     / ___\  :             /        \      /\··      /\n    :      /\_/    /  \   \     \       _/\         \    /::\      / o    .\n°   :     /::     / /\ \  /\     \     (   \  /\   \ \  /  ::\    /\n    :    /::...  /-/::\ \/  /\    \    /-----/::\   \ \/     :\  /       .\n    :   /_____  / /  ::\   /  \    \  /\    /  ::\   \ \        /\n    :        :\/ /__ :://\/    \    \/  \  /__ ::/    \ \      /\n    :        :     ''.://  \     \        \   ''.:/     /\      /  o    .\n    .        :\______//____\     \,       \____/\____/  \    /\n    .        :         /::\/              /!ce    ·      \  /\n    :        :  o ____/::.          _____/               /  \\n             .   /__________________/          °          \/       .\n               | \/                                                        .\n    .          `--÷[ p O i S O N ]÷---- ----  ---  -    -\n                 .\n \n             P R E S E N T S  J U S T  F O R  Y A !!!\n \n        /X - S T A R T E R  v 1 . o o    8 T H  M A Y  - 9 6\n \nwhy?                 C O D E D  B Y  i C E\n.---------------------------------------- ---------- ------- ----- ---- -- -\n| I made this to make sure my /X always was on when I wasn''t home.\n| Of course /X will not fuck up the computer normally, but it did once for me\n| and that was one time to much.\n:\n:\n.\n \nfeatures:\n.------------------------------------ --------- -------- ---- --- --  --\n| Well, this isn''t a complicated tool. It just opens a window and waits\n| three seconds for the sysop to press enter, otherwise it will start acp.\n|\n:\n \n.\n \ninstalling?\n.---------------------------------------- -------- ------ ----- -- -   -\n:\n: Copy AmiE-starter.exe into your c: and add this to your s:user-startup\n.\n  C:AmiE-starter.exe\n \n  and make sure you have your acp in your BBS: drawer\n\ncommands:\n.------------------------- ---------- ------- ----- ---- -- - -   -\n| [ENTER]  Skip the /X startup\n| [S]      Stop the counter\n| [R]      Restart the counter if it''s stoped\n: [A]      About\n.\n \n \nH A V E  A  C A L L  T O  T H i S  B O A R D:\n \n \n      °              ___                 /\            ·\n          ·          ) (  _    · .      / :\\n    ________  /\     \: \//  ____/\    /   :\  ___ __  ________ _\n::..        \/ (      \  /  /:·_   )__/___  :\ \ (/ /  \    __/// _/  ·  ¸\n ····_______   / \  /\-\/--/  /(__/__    /   (_ \  /  __\    )/\\n     )::·  /  (  /\/  \ · /  /   ·::7   /      \ \/--'':·''   /\°·/      ·\n.    \:·  /    \/  \ ·:\_/   )    ·:|  /_\      \\  ·:/    / /^ \   __\n  ·   \  /_\    \ \ /   (    \     ·|    ¬      :\\  / ___/\  \/   _\/_    ¤\n. :·::     ¬ ..::\.Y  .:`\__________; _ ___   .::(/\/      :\      \/\/  o\n   _ __ ________ (-^----''\)      ·:: __/ (________7-------.::\\n               \ /  ·:\    _      ·:(_  ___    _/      ______(----.          o\n                /     `\   )\________/__) Ç   /_______/·:::/   ·::(_ ·    °\n   °       `.__/        \  \        7-\  _;---\/---,     ·/      ·:7\n       · ð   \   /       \  \       \  \/  ·:/  ·:/      /   ____  `.  ·\n   o      .  /  /_\      ·\        ::\     :/    (|     /    _  /___;\n            /     ¬     .::\    ..::: \   ./\     ¬    /_     \/   /\n     _  __|/_________  .:::(--------:  \  /  \       ___/         /---·   ·\n          |  ·     )_____  /           _\/ °  \     .\____________ .:/\n          .  :     \/    \/         .  \/      \  .:/!ce         \.:/\n      °      |                              ¤   \::/              \/   ·\n             `-÷[ AMiGA iS ALiVE ]÷-- -  -   -   \/\n \n               /X 4.8  sYSOPS: iCE & rACOON  14k4  24h\n           ART, jAMMiNG, rEQUESTS, CODERSHiDEOUT, /X SUPPORT, ...\n \n            - -- ---÷[ + 4 6 ( 0 ) 3 7 1 - 8 2 2 1 8 ]÷--- -- -\n','\n',char(10)),NULL,'auto-added',22216,3,0,NULL,NULL,'psn_xs10','scan',1780048679);
