EHQ * ROYAL MAC SCHQ *  \n                             \n                          THE PROTECTORS ARE:\n        ZINKO^PLAYMATE^SISko^BILBO BAGGIn^NEIL/FLT^BLACK PANTHER/PSG\n           UFOK/MsT^LsD^PsG^iHS^FURY/PSG/M!/SYS/HLM^RECALL/CLS^QTX\n \n                         <0>  +45 58ASK4IT  <0>\n                         <0>  +FIND ON IRC  <0>\n\n\n\n','\n',char(10)),NULL,'auto-added',4962,3,0,NULL,NULL,'pst_gdal_2','scan',1780048679);
