INSERT INTO door_catalog VALUES('ptq_gj11','PTQ-GJ11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PTQ-GJ11.LHA','GenieJoin','XIM','GenieJoin',NULL,NULL,'PTQ','|   Y |_| _ Y _)|   Y_Y   Y | Y __|        | | | | l |   |_  l_| | | | | | | _/. deZiGn | |  _l_  l_| l_'' | l_l_l_  l___l_  |        |',replace('.___ _. .___ __ .___ _ ___ _ _ ___. «------.\n|   Y |_| _ Y _)|   Y_Y   Y | Y __|        |\n| | | l |   |_  l_| | | | | | | _/. deZiGn |\n|  _l_  l_| l_'' | l_l_l_  l___l_  |        |\n`-'' - `-'' `-'' `-'' ----- `-'' --- `-'' ·------''\n.------------------------------------------.\n| GenieJoin version 1.1 for SigmaExpress!  |\n|------------------------------------------|\n| Not really an update, but a totally new  |\n| door, screenshots included...            |\n`------------------------------------------''\n','\n',char(10)),'GenieJoin.guide',replace('@DATABASE "Geniejoin guide"\n@NODE "MAIN" "Geniejoin"\n@TOC "MAIN"\n\n@{fg text}                                        __ _.___\n     _______ ___     _______  ____   ___)//¬|___)_______ ___ ___ _____\n     \ ___ ¬|\  |___\\___  ¬|/ __/__(_    __!\ ¬|\  .  ¬|\  |  ¬|\ __/__\n    |¯ \____|¯  |  ¬|   /   |----- ¬||    | |¯  |¯  !   |¯  !   |¯ -''  ¬|\n    l___!   l_______l___|___l_______!l____! l___l___._  l_______l_______!\n@{fg shine}    -------------------------------------------------@{fg text}\__)@{fg shine}----------------@{fg text}\n    Twilight subdivision / Plastique Design                      ©gNS^pTQ\n@{fg shine}    ---------------------------------------------------------------------@{fg text}\n\n                            @{b}    P r e s e n t s@{ub}\n\n\n@{fg shine}------------------------------------------------------------------------------@{fg text}\n                  @{b}***@{ub} GENIEJOIN VERSION 1.1 BY GENIUS/PTQ @{b}***@{ub}\n@{fg shine}------------------------------------------------------------------------------@{fg text}\n@{b}                                                                        \n                           @{"        " LINK "INTRODUCTION"} Introduction                                \n                                                                        \n                           @{"        " LINK "INSTALLATION"} Installation                                \n                                                                        \n                           @{"        " LINK "CONTACT"} How to contact us?\n\n@{ub}\n\n\n\n\n\n\n@ENDNODE\n\n@NODE "INTRODUCTION" "Introduction"\n@PREV "MAIN"\n@TOC "MAIN"\n\n                        ×X×  - @{b}1, Introduction!@{ub} -  ×X×\n@{fg shine}\n                         (___                   ___)\n                            /___________________\\n\n@{fg text}\n\n-------------------------------------------------------------------------------\n\n        A simple join door, with all features needed for easy use...\n\n   Features two designs, (look at screenshots) - the door checks how many\n\n           conferences you have and selects the design that fits.\n\n    The door also finds the conference-names itself, so it don''t need any\n\n                       configuration... plug&play?! 8)\n\n\n  note: the door ONLY runs on S!X becoz'' of specific S!X commands being use\n\n                     to find the users conf-access... 8(\n\n\n                               @{"  Bug reports?  " LINK "CONTACT"}                           \n\n                               @{"  Installation  " LINK "INSTALLATION"}                         \n\n\n\n  \n@ENDNODE\n\n@NODE "INSTALLATION" "Installation"\n@TOC "MAIN"\n\n                       ×X×  -@{b} 2, Installation!@{ub} -  ×X×\n@{fg shine}\n                         (___                   ___)\n                            /___________________\\n\n@{fg text}\n\n-------------------------------------------------------------------------------\n\n   Copy door to ANY dir, and make a new BBSCMD entry, with the command "J"\n\n           "<" and ">" ain''t needed since S!X have them built-in!\n\n                          Hmm.. that''s about it...\n\n\n\n\n@ENDNODE\n\n@NODE "CONTACT" "How to contact"\n@TOC "MAIN"\n \n                       ×X×  - @{b}7, How To Contact!@{ub} -  ×X×\n@{fg shine}\n                         (___                   ___)\n                            /___________________\\n\n@{fg text}\n\n-------------------------------------------------------------------------------\n\n     If you wan''t to contact pLASTiQUE DeSiGN give my @{b}cool@{ub} board a call:\n@{b}\n                                                                           \n              _ _______               _ _______________________________ _. \n              \\\    ·/-.     ·     ._)\\                             (_)| \n              |\\\   / _|   .       |                                    | \n              : ¯ \¡/  =|           | @{ub} This, our worldHQ board is where@{b}  | \n              | __ _ __-|  :·       | @{ub} you can contact us, just leave  @{b}  | \n              | (\)^(/) :  ..       : @{ub} a message, or talk to the sysop!@{b}  ! \n _______      `-.¯._,¯,-''   . ________                                   : \n( O-    )------/|  "  |\---·-(     -O )@{ub}Supports: coding, lightwave rayt.@{b} | \n(¯¯¯¯¯¯¯  ¯   /.(:_|_.)_\_.·  ¯¯¯¯¯¯¯¯)@{ub}          amiga warez, HPA,      @{b} | \n )        . _//.|"""(_(_¯(@ ._       ( @{ub}          and lots, lots more!   @{b} ! \n(_       ( /_/::(""!"").¯\_\ )       (                                   | \n(_        )¯/:::.\___(:::.\¯(        _)                                  | \n@{fg shine}    ____   .___ __ . ______   ____  . ______   ____  .___ __ .@{fg text}          _|_\n@{fg shine}  // __/___|___` //|\\ .  ¬|// __/__|\\__  _)// __/__|___` //|@{fg text}    ©gNS ___/\n@{fg shine} |------  ¬|  ¬\   |   |   |   -''  ¬|   .  ¬|   |   ¬|  ¬\   |@{fg text}__ ______(   \n@{fg shine} l_________l_______l___|___l________l___|___l________l_______!@{fg text} `-'' :       \n@{fg shine}     .___   ____  . ______. ___  ____ _______. ______.___     @{fg text}     |       \n@{fg shine}  ___|_ /|// __/__|\\ .  ¬|\\  \/   ¬\\___  ¬|\\__  _)  ¬|--.  @{fg text}    |       \n@{fg shine} |  __/  |   -''  ¬|   |   |    \/    |   /   |   .  ¬|   .  ¯\  @{fg text}   |       \n@{fg shine} l_______l________l___|___l____||____l___|___l___|___l___|____) @{fg text}   |       \n   :                                                               |       \n   |@{ub}  Plastique Whq · Hamstarz Whq      Node 1 ( +45-3990-2992 ) @{b}  ¦       \n   |@{ub}  Flatline Dkhq · Twilight dkhq     Node 2+( +irc-amielite ) @{b}  |       \n   !__                                                           __!       \n      )____ _ _________________________ @{ub}Sysop  : Genius/ptq@{b} ____(          \n          ((_))                       `---------------------''              \n\n@{ub}      Or you can write to Twilight''s/Plastique''s @{b}E-mail@{ub} adress which is:\n         \n                        @{fg shine}    [email removed]@{fg text}\n\n\n                                     or\n\n                     Genius e-mail : @{fg shine}[email removed]@{fg text}\n\n\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',24776,4,0,NULL,NULL,'ptq_gj11','scan',1780048679);
INSERT INTO door_catalog VALUES('pugglory','PUGGLORY.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PUGGLORY.LHA','trimlog','XIM','sonnenbrand.exe','2.0','Charles',NULL,'Enter the Boxing world! Create boxers and let ''em fight ''till the last knockout! This versions features bug fixes, price fighting,',replace('Pugilistic Glory v2.0 by Charles van Tuyl.\nEnter the Boxing world! Create boxers and\nlet ''em fight ''till the last knockout! This\nversions features bug fixes, price fighting,\na champion ladder and more! CNet Arexx PFile\n','\n',char(10)),'trompete.txt',replace('\n\n\n\n\n ___(\·----------------------- ----  ---  --   -     -        - \n      \)       IN A WORLD OF DREAMS - IN A WORLD OF PASSION\n\n            THIS FILE DECIDED TO PASS ONE OF THE LAST AND REAL\n                 BULLETIN BOARD SYSTEMS IN CENTRAL EUROPE\n\n                     THE ONLY WAY TO SURVIVE - FAITH!       (\ ___\n          -      -    ---  --- ------- ----------------------·\)\n\n\n\n\n\n','\n',char(10)),NULL,'auto-added',101857,64,0,NULL,NULL,'pugglory','scan',1780048679);
INSERT INTO door_catalog VALUES('pumpkin','PUMPKIN.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PUMPKIN.LHA',NULL,'XIM','Pumpkin.exe',NULL,NULL,NULL,'.-''                                      `-. |             ·P·U·M·P·K·I·N·              | |                                          |',replace('  .--------------------------------------.\n.-''                                      `-.\n|             ·P·U·M·P·K·I·N·              |\n|                                          |\n|   Grey''s AGA contribution to Halloween   |\n`-.                                      .-''\n  `--------------------------------------''\n','\n',char(10)),'ansimquest.txt',replace('\n\n                 \n                                  ·     ·\n                               _ __\   /__ _\n                            _ _)\\  \ /  //(_ _\n                           -\   __\° X °/__   /-\n                    _ __ ___ ___)  \/_\/  (___ ___ __ _\n           ((- \ - -\\\_\\__\\__  _ /¦\ _  __//__//_///- - / -))\n                       _.      \__)_¯_¯_(__/      ._          \n           _/          \|_       | | | | |       _|/          \_\n         __\ ___ _/\____\/__ __ _| | | | |_ __ __\/____/\_ ___ /__\n       _/   \  (_)  \_  \/  /_/\\| |_|_| |//\_\  \/  _/  (_)  /   \_\n       |                    \_\/ | | | | | \/_/                    |\n      _|___                   __ | | | | | __                   ___|_\n      \|__/                   \/_| | | | |_\/                   \__|/\n       |                     · _)  ¯_¯_¯  (_ ·                     |\n       |  ·H2o!·              \\___ \ / ___//                      |\n       ¯\_______________________ _)  Y  (_ _______________________/¯\n             __                  \___ ___/                  __\n        - -->\__ fRIENDS oNLY! <<-  (_)  ->> fRIENDS oNLY! __/<-- -\n                           \n\n\n','\n',char(10)),NULL,'auto-added',65894,3,0,NULL,NULL,'pumpkin','scan',1780048679);
INSERT INTO door_catalog VALUES('pupl10','PUPL10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/PUPL10.LHA',NULL,'XIM','rexxplslib.library','1.00','The',NULL,'Coded by The Bird/T-R-S-i -COCKtAILS BBS-',replace('PartUpload Mover v1.00\nCoded by The Bird/T-R-S-i \n                             -COCKtAILS BBS-\n','\n',char(10)),'PUPLOAD.DOC',replace('******************************************************************************\n** 02-05-93               PartUpload Mover v1.00                            **\n**                                                                          **\n**                   --> Coded by The Bird/T-R-S-i <--                      **\n******************************************************************************\n\n                  --> FULL OVERWRITTEN DOCUMENTATION <--\n\n\nNow I want to present you one more Utility of my collection. I made this\nutility because of an request of my friend ANDY/MoTiON. He had the Idea to\ncode a utility which will move the not finished uploaded files in the\nPARTUPLOAD directories after a System Crash. So i decided to do him a\nfavour an code such a utility, because i though it will not be difficult to\ndo this. Because this utility works like my famous Dirstyle utility i use\nsome codes from the dirstyle utility to have the new utility very fast work.\nNow iam ready to provide you this utility which can be very usefull for some\nSysops, where the system crashes more than one time in a day.\n\nInstallation:\n~~~~~~~~~~~~\nThe installation is very simple. Just take PUPLOAD.EXE and start it with\nthe "CONFIG" argument. This will pop up a CONFIEDITOR were you can fully\nedit a Config which will be saved to S:. Answer all question correctly and\nthe Utility should work correctly.\nNow at the last step you only have to install the Utility in your normal\nSTARTUP-SEQUENCE so that it will be started after every system CRASH or\nRESET.\n\nHow the Mover works:\n~~~~~~~~~~~~~~~~~~~\nEverytime the utility will be started it will check the BBS:NODE<x>/PLAYPEN\ndirectory if there are files which are not finished. If the utility will find\nsome files it will scan the callerslog for the last user who was in the bbs\nand try to find out if he has an lost carrier and then the utility will move\nthese files with the correct usernumber to the BBS:<CONF>/PARTUPLOAD\ndirectory. If now the user logs in the bbs again he will be prompted to\nfinished his uploads before going on.\n\nConfiguartion:\n~~~~~~~~~~~~~\nThis utility is totally self configurable. Just start the Configeditor with\nthe following command in the Shell:\n\n1> PUPLOAD.EXE CONFIG\n\nNow you will be in a Configeditor where you have to answer some questions\nand then the utility will start to transfer all datas from the ACP.STARTUP\nor the 3.0+ depending CONFCONFIG.INFO Icon.\n\nThe Help Page:\n~~~~~~~~~~~~~\nI have installed a little Help Function where you can view all Options and\nthings you can do with PUPLOAD. Start PUPLOAD this way ''PUPLOAD.EXE ?''\nand you will go to the Help Page which will be like that:\n\n--------------------------------------------------------------------------\nPartUpload Mover v1.00 - Coded by The Bird/T-R-S-i\n~~~~~~~~~~~~~~~~~~~~~~   /X Developement Team Util.\n\nUsage:      PUPLOAD.Exe [commando]\nCommandos:  CONFIG = Will start a CONFIGEDITOR           <<< OPTIONAL\n~~~~~~~~~   ?      = This Screen....\n--------------------------------------------------------------------------\n\nBugReports:\n~~~~~~~~~~\nIf you are finding any bugs in this Utility please call my BBS and tell me\nthis bugs and i will fix them as fast as possible.\n\nKNOWN PROBLEMS:\n~~~~~~~~~~~~~~\nThe only known problem in DIRSTYLE is that some people can`t use this \nUTILITY on their 68040 TURBO because the REXXPLUSCOMPILER doesn`t support\nthis TURBOCARD. All other TURBOCARDS should work and i was tested up to\n68030. For solving this i need a 68040 BETATESTER...\n\nLast Words:\n~~~~~~~~~~\nThis Utility depends to the Amiexpress Development and should be only used\nfrom registered users of Amiexpress V2.0+. In this Utility are NO BACKDOORS\nand it was tested for month on my and other bbs`s, but I take no response\non Errors or damages to your system by using this Utility. It is totally\nFREEWARE and can be spreaded all over the world. All i expect from you\nis that you give my BBS a call and say some cool words to me.\nI hope you will not have problems with this utility, because i programmed\nit in a very save code and it should not crash on your bbs.\n\nBETATESTERS:\n~~~~~~~~~~~\nFirst greetings should go to my hard working BETATESTER ''ZIG ZAG'' because\nhe reported me all bugs and i fixed them all. All other old BETATESTERS\nare kicked because they don`t report their BUGS and i only want BETATESTERS\nwho report me 1 time per week whats going up with my utility, if it works\nor not.\n\nGreetings:\n~~~~~~~~~\nFirst to my GIRLFRIEND because of loving she very much and for being my best\nGIRLFRIEND i ever had.\n\nZIG ZAG     - Thanx for your GREAT BETATESTING\nPIGEON      - Thanx for your Ideas and support\nALI BABA    - Keep on coding in ASSEMBLER....\nSIGMA SEVEN - Thx for your Moral Support and lots of Amiex BETATESTING..\nSinatra     - For his last Bugreports\nMTD         - Keep on coding fine and short utils (GET BETTER IDEAS)\nKool Falco  - for calling my bbs and being cøøl\nByteMaster  - for coding the BEST BBS program ever made.\nP0T-NOODLE  - for some great Utilities you brought out.. GREAT WORK\nAndy/MoTioN - for his Moral Support on coding.. Thx my friend\nNosferatu   - for beeing cool and staying cool...\n\n       And to all the other Guyz with a great Amiex Knownledge...\n       Send ME greetings and my greetings will come back to ya...\n\n==========================[+49-711-777-5990]===============================\n              _|____  ______________._________/\    ___\n               |    \/    |o   _    |        /  \  |   |\n  EqUiPmEnT:   |o         ||  |_\___|o  |   //   \ |:  |       EmPeRaToRs:\n  ~~~~~~~~~~   ||  \  /   |:   _|___||  |__//     \|_  |._/\   ~~~~~~~~~~~\n 21øMb OnBoard |:  |\/|   |.  |_/   ||  | /.  /\    /  ||   \   ThE BiRD\n  384øø/Os2.0  |.  |  |___|___|_____|___|/   ___\  /   |____/ AnDY!/MoTiON\n AMiX 2.xx Reg |___|          |          \  /    \/|___|     CeLLaT&SleDGE\n            _______  _________._________. \/\ ._______  _________.\n           |       \|    _    |o   _    | /  \|       \|    _    |\n===========|o  |\_  \_  |_\___||  | \___|//   \o  |\_  \_  |_\___|=========\n CaLL NoW! ||  | /   /   _|___||  |  ___//     \__| /   /   _|____ ------>>\n===========|:  |/   /:  |_/   |:  |_/  /.  /\    /|/   /:  |_/   |=========\n           |___/___/|.  |_____|_______/   ___\  /_/___/|.  |_____|\n                    | __|             \  /    \/       | __|     [eNf]     \n                    |/                 \/              |/     \n  ø-2 DayZ WaREZ !  |  ...where the warez come from... |  ø-2 Dayz WaREZ !\n\n==========================[+49-711-777-5990]===============================\n','\n',char(10)),NULL,'auto-added',42315,3,0,NULL,NULL,'pupl10','scan',1780048686);
