INSERT INTO door_catalog VALUES('qwk','QWK.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/QWK.LHA','AmiQWK_II','XIM','AmiQWK_II',NULL,NULL,NULL,'from /X 3.33+ systems.',replace('Offline MailReader. To Read Zoomed Mail\nfrom /X 3.33+ systems.\n','\n',char(10)),'AmiQWK.guide',replace('@database AmiQWK.Guide\n@node Main "AmiQWK II Help."\n\n            AmiQWK II Version 1.0    -    June 30, 1993\n\n                QWKMail format Offline mail reader\n            for the Commodore Amiga personal computer\n\n    AmiQWK II Copyright (c)1992, 1993 Jim Dawson, All Rights Reserved.\n\n    @{" Disclaimers      " link Disclaimer}  And other legal stuff.\n    @{" License          " link License}  License and Shareware Info.\n\n    @{" QWKMail          " link QWKMail}  What is QWKMail anyway?\n    @{" About AmiQWK II  " link AboutAQ}  About AmiQWK II.\n    @{" Support          " link TechSupport}  How to contact the author\n    @{" Registration     " link RegisterAQ}  How to register AmiQWK.\n\n    @{" Setup            " link Setup}  Setting up AmiQWK.\n\n    @{" Packet Selection " link PacketSelect}  Select packet to read.\n    @{" Configuration    " link Config_Main}  Configure AmiQWK II.\n    @{" Read Selection   " link SelRead}  Select item to read.\n    @{" Read Text        " link ReadText}  Read Text file or bulletins.\n    @{" Read Messages    " link ReadMail}  Read Messages.\n    @{" Replies/New Msg  " link NewMsg}  Enter Replies or New Messages.\n\n    @{" The Future       " link Future}  The future of AmiQWK.\n    @{" Credits          " link Credits}\n\n\n@endnode\n@node Disclaimer "Disclaimers and other legal stuff..."\n\n    No warranties are expressed or implied with regard to the fitness or\nsuitability of AmiQWK II for any particular purpose.\n\n    All risks and damages, incidental or otherwise, arising from the use,\nmisuse, or inability to use AmiQWK are entirely the responsibility of the\nuser.\n\n    AmiQWK II software and documentation are copyright (c) 1993 by\nJames Dawson, All Rights Reserved.\n\n    AmigaGuide, AmigaGuide.info, amigaguide.library (c) Copyright 1992\nCommodore-Amiga, Inc. All Rights Reserved. Reproduced and distributed\nunder license from Commodore.\n\n    AMIGAGUIDE SOFTWARE IS PROVIDED "AS-IS" AND SUBJECT TO CHANGE; NO\nWARRANTIES ARE MADE.  ALL USE IS AT YOUR OWN RISK.  NO LIABILITY OR\nRESPONSIBILITY IS ASSUMED.\n\n    ReqTools and Reqtools.library are Copyright (c) Nico François.\n\n    All product names used in this document are trademarks of their\nrespective owners.\n\n@endnode\n@node License "AmiQWK License and Shareware Information"\n\n    AmiQWK II is distributed as SHAREWARE is not and never has been public\ndomain or freeware.\n\n    AmiQWK II is licensed for individual personal use and evaluation for a\nperiod of time not to exceed thirty days after initial usage. Registration\nis required for use after the initial 30 day trial period.\n\n    Distribution is limited to the original shareware distribution archive\nonly, none of the member files may be omitted. Furthermore, no profit or\nother material gain may be realized for the distribution of AmiQWK II with\nthe exception of normal distribution fees, not to exceed $7.00 US. AmiQWK II\nmay not be included with any commercial product without permission from\nJim Dawson.\n\n    Permission is hereby given to distribute AmiQWK II in the Fred Fish\nshareware collection.\n\n@endnode\n@node QWKMail "About the QWKMail format."\n\nWhat is QWKMail? And why do I need it?\n\n    QWKmail is a popular offline message format used by many BBS programs.\nThe QWKMail offline message format was created by Mark ''Sparky'' Herring\nin 1987 to reduce the cost involved in calling bulletin boards long\ndistance. QWKMail has since become available for most BBS packages either\ninternally or via an external ''door'' program.\n\nHere''s how QWKMail works. While online to a BBS, the caller selects the\n''QWK'' packer. The BBS then all waiting messages in the discussion areas\nthe caller has selected to read in (Consult the online documentation on\nyour favorite BBS for information on how to configure the QWKMail packer)\nare compiled into a message packet. The packet is then packed with an\narchive program such as ZIP or LHArc to reduce its size and the amount of\ntime required to transfer it. The packet, which normally has a file\nextension of ''.QWK'', is then transferred as a binary file using a transfer\nprotocol such as XModem or ZModem. After the caller has logged off of the\nBBS, he or she starts the QWKMail reader and selects the message packet\nto read. The reader will then extract the packet and allow the user to read\nand enter messages. When the user has finished reading messages, the\nreplies are packed into a reply packet to be uploaded to the mail packer\nthe next time the user calls the BBS.\n\nThe benefits of using an offline mail reader include:\n\n*	Less time is spent online, reducing long distance fees and allowing\nothers to use the BBS in the time saved.\n\n*	Instead of the slow, cryptic editors used on most BBS programs, you\ncan use any editor that saves text in ASCII format. Which also means you\ncan use tools such as spelling and grammar checkers, Import text from\nother sources, etc.\n\n*	Because less time is spent online, you can spend more time reading\nmessages,\n\n*   QWKMail is supported by most major BBS programs.\n\nHowever, QWKMail does have some shortcomings.\n\n*	To, From, and Subject fields are limited to 25 characters. Not much of\na problem for local messages, but can cause problems with long network\naddress names.\n\n*	The .QWK format is not very well documented, resulting in\nincompatibilities between some readers and packers.\n\n@endnode\n@node AboutAQ "About AmiQWK II\n\nWhat is AmiQWK?\n\nAmiQWK II is a full featured QWKMail offline message reader for the\nCommodore Amiga computer. My goals for AmiQWK are (in no particular order)\n\n*	To be the most stable and compatible QWKMail reader available for the\nCommodore Amiga computer.\n\n*	To be the most full featured QWKMail reader for the Commodore Amiga\ncomputer.\n\n*	To take advantage of features found Release 2 and higher of the Amiga\noperating system.\n\n*	To be easy to use.\n\n*	to be highly configurable.\n\n\n@endnode\n@node Future "The future of AmiQWK"\n\n    The future of AmiQWK II is up to you. The amount of time I spend\nworking on AmiQWK depends on how much feedback (and more importantly, how\nmany registrations) I get.\n\n    Immediate plans are to clean up the existing code and add some\nadditional features, such as the re-editing of replies, ANSI display\nscreen, bulk saving/printing of messages, TeX documentation, etc. Long term\nplans include support for other mail formats.\n\n    I have already begun designing AmiQWK III. If you have any ideas, or if\nyou have specs on other mail formats, please let me know.\n\n@endnode\n@node Requirements "System Requirements"\n\nAmiQWK II requires the following hardware to run:\n\n*	512Kb RAM. (1MB or more recommended)\n\n*	Floppy Drive. (Second floppy drive or hard drive highly recommended.)\n\n*	Mouse.\n\n*	Printer. (if you want to print messages.)\n\n*	Monitor.\n\nAmiQWK II also requires the following software:\n\n*	Workbench 2.0 or higher.\n\n*	A text editor that can save ASCII text without any formatting info.\n(ED and MEMACS that come with Workbench are fine.)\n\n*	Any archivers you plan to use (ZIP, LHA/LHArc, ZOO, and ARC are\nsupported).\n\n*	reqtools.library. (included with AmiQWK II distribution archive.)\n\n*	amigaguide.library. (included with AmiQWK II distribution archive,\nonly required for online help.)\n\n@endnode\n@node Setup "Setting up AmiQWK for the first time."\n\n    To setup AmiQWK, just extract the AmiQWK distribution archive and\ndouble click on the install icon. This will copy the required libraries to\nyour libs: directory.\n\n    After the libraries are installed, start AmiQWK by double clicking on\nits icon. Once AmiQWK is running, click on the gadget labeled\n''Config AmiQWK'' to take you to the @{" configuration  " link Config_Main} editor. Press the Help key\nfor help configuring AmiQWK.\n\n    Once you have AmiQWK configured, click on the ''Save'' gadget in the main\nconfig window to save your configuration.\n\n@endnode\n@node TechSupport "Support"\n\n    The latest version of AmiQWK can be obtained from The Hackers Guild II\n    BBS (phone number below) as well as Portal. New versions of AmiQWK will \n    also be posted to the AmiNet FTP sites.\n\n    For technical support, bug reports, sugguetions, and constructive\n    criticism, send email to:\n\n    USENET:     [email removed]\n    INTERNET:   thg2![email removed] OR [email removed]\n\n        Use the Portal address only if other two addresses cannot be\n        reached. I only call Portal about 2-3 times a month, so a response\n        may take several weeks.\n\n\n    Or, call The Hackers Guild II BBS\n\n        1 (618) 997-2591 (24 Hrs, 7 Days)\n        300-14,400 BPS USR Dual Standard (v.32/v.32bis/Courier HST)\n        Full Duplex, 8 data bits, No parity, 1 stop bit.\n\n\n    And if all else fails, try snail mail.\n\n        Jim Dawson\n        508 S. Madison St.\n        Marion, IL. 62959\n        USA\n\n    Please send me as much information as possible with bug reports so I\n    can reproduce the problem.\n\n@endnode\n@node RegisterAQ "Registration"\n\n        AmiQWK is Shareware. If you use AmiQWK please send me $15.00 in U.S.\n    funds. Registration is required after the 30 day evaluation period.\n    Fill out the registration form (register.doc) and mail it with $15.00\n    in U.S. funds or a check from a U.S. or Canadian bank to:\n\n        Jim Dawson\n        509 S. Madison St.\n        Marion, IL. 62959\n        U.S.A.\n\n        In lieu of the $15 shareware fee, users from outside North America\n    can send me a HARDCOVER copy of a book by one of your countries better\n    Science Fiction writers. (ENGLISH ONLY please) (Australian AmiQWK Users,\n    I would love a copy of anything by Terry Dowling.)\n\n        With your registration you will get a registration key number.\n    Enter it and your name into the registration window (select ''register''\n    from the main config window) and the shareware reminder requester that\n    pops up at various times. If you have an Internet or Usenet email\n    account I will send the registration key to you via email.\n\n@endnode\n@node PacketSelect "Packet Selection"\n\n    Packet Selection.\n\n    @{" Open Packet    " link OpenPacket}  Open packet for reading.\n    @{" Config AmiQWK  " link Config_Main}  Configure AmiQWK II.\n    @{" About AmiQWK   " link AboutAQ}  Information about AmiQWK II.\n    @{" Help!          " link Help}  Help with AmiQWK II.\n    @{" Rename Packet  " link RenamePacket}  Rename a QWKMail packet.\n    @{" Delete Packet  " link DeletePacket}  Delete a QWKMail packet.\n    @{" Quit and Exit  " link QuitAndExit}  Quit and exit AmiQWK.\n\n    @{" Main Help Menu " link Main}  Return to the main help menu.\n\n@endnode\n@node OpenPacket "Open Packet"\n    Pressing this gadget will display a file requester. Use it to select\nthe packet you want to read.\n\n    The directory to be searched and the pattern to search for to\nlocate .QWK packets can be set in the @{"configuration" link Config_Main} section.\n\n@endnode\n@node AboutAQ "About AmiQWK II"\n\n    AmiQWK II is a BBS offline mail reader compatible with the QWKMail\noffline mail format developed by Mark ''Sparky'' Herring.\n\n    Pressing this gadget displays important information about AmiQWK II,\nincluding version number, compile date, Copyright notice, Where to send\nbug reports, etc.\n\n    AmiQWK II was written by Jim Dawson and is copyright (c) 1992-1993 by\nJim Dawson. All Rights Reserved.\n\n@endnode\n@node help "Online Help"\n\n    AmiQWK II supports online help using AmigaGuide from Commodore.\n\n  AmigaGuide, AmigaGuide.info, amigaguide.library (c) Copyright 1992\n  Commodore-Amiga, Inc.  All Rights Reserved.\n  Reproduced and distributed under license from Commodore.\n\n     AMIGAGUIDE SOFTWARE IS PROVIDED "AS-IS" AND SUBJECT TO CHANGE;\n     NO WARRANTIES ARE MADE.  ALL USE IS AT YOUR OWN RISK.  NO LIABILITY\n     OR RESPONSIBILITY IS ASSUMED.\n\n@endnode\n@node RenamePacket "Rename Packet"\n\n    Press this gadget to rename .QWK packets. A file requester will be\ndisplayed to select the packet to rename. Once a packet is selected, a\nsecond file requester is presented to select the new file name.\n\n    If you select a different path but the same name, the packet will be\nmoved to the new directory.\n\n@endnode\n@node DeletePacket "Delete Packet"\n\n    Press this gadget to delete .QWK packets. A file requester will be\ndisplayed to select the packet to be deleted. Once a file is selected, a\nrequester will appear asking if you are sure you want to delete the file.\n\n@endnode\n@node QuitAndExit "Quit And Exit"\n\n    Press this gadget to exit the program. A requester will appear asking\nif you are sure you want to exit.\n\n@endnode\n@node SelRead "Read Select"\n\n    Select item to read.\n\n    @{" Packet    " link PacketName} Name of the QWKMail packet. @{" Hello File   " link HelloFile} Logon text.\n    @{" BBS       " link BBSName} Name of the BBS.            @{" Bulletins    " link Bulletins} Bulletins.\n    @{" Location  " link BBSLocation} Location of the BBS.        @{" News         " link News} News File.\n    @{" Sysop     " link BBSSysop} Sysop of the BBS.           @{" Read Mail    " link ReadMailGad} Read Messages.\n    @{" Phone     " link BBSPhone} Phone number of the BBS.    @{" New Files    " link NewFiles} New Files List.\n    @{" Packet ID " link PacketID} Packet ID                   @{" Goodbye Text " link GoodbyeFile} Logoff text.\n    @{" Time      " link PacketTime} Time packet was created.    @{" Close Packet " link ClosePacket} Exit Packet.\n    @{" Date      " link PacketDate} Date packet was created.    @{" Exit AmiQWK  " link ExitAmiQWK} Exit Program.\n    @{" User Name " link UserName} Person who downloaded packet.\n\n    @{" Main Help Menu " link Main}  Return to the main help menu.\n\n@endnode\n@node PacketName "Packet Name"\n\n    This is the filename of the .QWK packet you are reading.\n\n@endnode\n@node BBSName "BBS Name"\n\n    This is the name of the BBS the .QWK packet came from.\n\n@endnode\n@node BBSLocation "BBS Location"\n\n    This is the location of the BBS where the .QWK packet came from.\n\n@endnode\n@node BBSSysop "BBS Sysop Name"\n\n    This is the name of the sysop of the BBS where the .QWK packet came\nfrom.\n\n@endnode\n@node BBSPhone " BBS Phone Number"\n\n    This is the phone number for the BBS that the .QWK packet came from.\n\n@endnode\n@node PacketID "Packet ID"\n\n    This is the packet ID for the .QWK packet.\n    \n    It is used to determine the filename for reply packets.\n\n@endnode\n@node PacketTime "Packet Time"\n\n    This is the time the .QWK packet was created.\n\n@endnode\n@node PacketDate "Packet Date"\n\n    This is the date on which the .QWK packet was created.\n\n@endnode\n@node UserName "User Name"\n\n    This is your name. (or the name of the person who downloaded the .QWK\npacket.)\n\n@endnode\n@node HelloFile "Hello File"\n\n    Pressing this gadget will display the hello text.\n\n    The hello text is generally a message welcoming you to the BBS system.\n\n    Not all .QWK packets have a hello text. This gadget will be ghosted if\nthe hello text is not available.\n\n@endnode\n@node Bulletins "Bulletins"\n\n    Press the Bulletins to read bulletins.\n\n    A file requester will be displayed to select the bulletin to read.\n    \n    Not all .QWK packets have bulletins. This gadget will be ghosted if\nbulletins are not available.\n\n@endnode\n@node News "News"\n\n    Pressing this gadget will display the BBS News text.\n\n    Not all .QWK packets have a News text. This gadget will be ghosted if\nthe News text is not available.\n\n@endnode\n@node ReadMailGad "Read Mail"\n\n    Press the Read Mail gadget to read messages.\n\n@endnode\n@node NewFiles "New Files"\n\n    Pressing this gadget will display a list of new files available on\nthe BBS.\n\n    Not all .QWK packets have a new files list. This gadget will be ghosted if\nthe New Files text is not available.\n\n@endnode\n@node GoodbyeFile "Goodbye File"\n\n    Pressing this gadget will display the goodbye text.\n\n    Not all .QWK packets have a goodbye text. This gadget will be ghosted if\nthe Goodbye text is not available.\n\n@endnode\n@node ClosePacket "Close Packet"\n\n    Press this gadget to close the current packet, pack replies, and return\nto the packet select window.\n\n@endnode\n@node ExitAmiQWK "Exit AmiQWK"\n\n    Press this gadget to exit the program. Replies will be packed before\nexiting.\n\n@endnode\n@node ReadText "Read Text"\n\n    @{" Print          " link PrintText}  Print Text.\n    @{" Save           " link SaveText}  Save Text to ASCII file.\n    @{" Quit           " link QuitReadText}  Quit Reading this text.\n\n    @{" Top of Text    " link TopOfText}  Move to top of text.\n    @{" Page Up        " link PageUp}  Move up 1 page of text.\n    @{" Line Up        " link LineUp}  Move up 1 line of text.\n    @{" Line Down      " link LineDown}  Move down 1 line of text.\n    @{" Page Down      " link PageDown}  Move down 1 page of text.\n    @{" Bottom of Text " link BottomOfText}  Move to bottom of text.\n\n    @{" Page Forward   " link PageDown}  Move forward 1 page of text.\n    \n    The text reader displays text files and bulletins. In addition to the\nfunctions above, there is a scroll bar at the bottom of the screen which\ncan be used to scroll through the text.\n\n@endnode\n@node PrintText "Print Text"\n\n    Press ''P'' or select ''Print...'' from the ''Commands'' menu to print the\ntext you are currently reading.\n\n    While the text is being printed, the mouse pointer will change to a\n''wait'' pointer and no input will be accepted in the reader window.\n\n@endnode\n@node SaveText "Save Text"\n\n    Press ''S'' or select ''Save...'' from the ''Commands'' menu to append the\ntext you are currently reading to an ASCII file.\n\n    A file requester will be displayed for you to select the file to be\nappended to.\n\n    If the file does not exist, it will be created.\n\n    You can set the default path and filename for the saved text in the\nconfiguration editor.\n\n    While the text is being saved, the mouse pointer will change to a ''wait''\npointer and no input will be accepted in the reader window.\n\n@endnode\n@node QuitReadText "Quit Reading Text"\n\n    Press ''Q'' or select ''Quit Reading Text.'' from the ''Command'' menu to\nquit reading the text currently displayed and return to the read select\nwindow.\n\n@endnode\n@node TopOfText "Top of Text"\n\n    Press ''7'' on the numeric keypad or select ''Top of Text'' from the ''Move''\nmenu to move to the beginning of the text you are currently reading.\n\n@endnode\n@node PageUp "Page Up"\n\n    Press ''9'' on the numeric keypad or select ''Page Up'' from the ''Move''\nmenu to move up one page in the text you are currently reading.\n\n@endnode\n@node LineUp "Line Up"\n\n    Press ''8'' on the numeric keypad, the up arrow key, or select ''Up 1 Line''\nfrom the ''Move'' menu to move up 1 line in the text you are currently reading.\n\n@endnode\n@node LineDown "Line Down"\n\n    Press ''2'' on the numeric keypad, the down arrow key, or select\n''Down 1 Line'' from the ''Move'' menu to move down 1 line in the text you are\ncurrently reading.\n\n@endnode\n@node PageDown "Page Forward"\n\n    Press ''3'' on the numeric keypad or select ''Page Down'' from the ''Move''\nmenu to move down one page in the text you are currently reading.\n\n@endnode\n@node BottomOfText "Bottom of Text"\n\n    Press ''1'' on the numeric keypad or select ''Bottom of Text'' from the\n''Move'' menu to move to the end of the text you are currently reading.\n\n@endnode\n@node ReadMail "Read Mail"\n\n    The read mail window consists of 3 parts, the message header at the top\nof the screen, The message text in the center, and an optional scroll bar\nat the bottom of the screen.\n\n    The header contains information about the message currently being read,\nincluding name of the sender, who the message is addressed to, subject of\nthe message, Time and date message was entered into the BBS, Conference\nname and number, Message number, etc. There is also 6 gadgets on the right\nside of the screen marked @{" Index " link MsgIndex}, @{" Conf " link ConfSel}, @{" Reply " link NewMsg}, @{" Help " link Help}, @{" << " link PrevMsg}, and @{" >> " link NextMsg}.\n\n    @{" Index " link MsgIndex}   Index of messages in this conference.\n    @{" Conf  " link ConfSel}   Select a new conference to read.\n    @{" Reply " link NewMsg}   Reply to the message currently being displayed.\n    @{" Help  " link Help}   Enter online help.\n    @{"  <<   " link PrevMsg}   Read Previous Message.\n    @{"  >>   " link NextMsg}   Read next Message.\n\n    In addition to the gadgets mentioned above, the following functions are\navailable.\n\n    @{" Print Message           " link PrintMsg}  Print current message.\n    @{" Save Message            " link SaveMsg}  Save Current Message to ASCII file.\n    @{" Enter New Message       " link NewMsg}  Enter a new message.\n    @{" Kill Reply              " link KillReply}  Delete this reply from .REP packet.\n    @{" ''Steal'' Tagline         " link StealTagline}  Steal tagline from this message.\n    @{" Quit Reading Messages   " link QuitMsgs}  Return to read select window.\n\n    The following commands are used to\n\n    The following functions are available if the mail door supports them.\n\n    @{" Add Conference          " link AddConference}  Add a conference to your scan list.\n    @{" Drop Conference         " link DropConference}  Remove a conference from your scan list.\n    @{" Reset Last Read Pointer " link ResetLastRead}  Reset the last read pointer in selected conference.\n    @{" Download Attached File  " link DownloadAttach}  Download file attached to this message.\n\n    Use the following functions to navigate messages.\n\n    @{" Top of Text      " link TopOfMsg}  Move to top of message text.\n    @{" Page Up          " link PageUpMsg}  Move up 1 page of message text.\n    @{" Line Up          " link LineUpMsg}  Move up 1 line of message text.\n    @{" Line Down        " link LineDownMsg}  Move down 1 line of message text.\n    @{" Page Down        " link PageDownMsg}  Move down 1 page of message text.\n    @{" Bottom of Text   " link BottomOfMsg}  Move to bottom of message text.\n    @{" Next Message     " link NextMsg}  Read next message.\n    @{" Previous Message " link PrevMsg}  Read previous message.\n    @{" Page Forward     " link PageForwardMsg}  Page forward through messages.\n\n@endnode\n@node PrevMsg "Previous Message"\n\n    Read the message before the one currently being read. If the message\nbeing read is the first message in a conference, the conference select\nwindow will be opened to select a new conference to read. By default the\nfirst conference with messages before the one being read will be selected.\n\n@endnode\n@node NextMsg "Next Message"\n\n    Read the message after the one currently being read. If the message\nbeing read is the last message in a conference, the conference select\nwindow will be opened to select a new conference to read. By default the\nnext conference with messages before the one being read will be selected.\n\n@endnode\n@node KillReply "Delete Reply"\n\n    Press ''K'' to delete the reply currently being read from the .REP\npacket.\n\n    Of course this only works when reading replies.\n\n    Careful, Once a reply is deleted, you can''t get it back!\n\n@endnode\n@node StealTagline "Enter Tagline"\n\n    Pressing ''T'' will open the ''Enter Tagline'' window. Here you can enter a\ntagline to be added to your tagline file.\n\n@endnode\n@node QuitMsgs "Quit Reading Messages"\n\n    Press ''ESC'' to exit the message reader and return to the read select\nwindow.\n\n@endnode\n@node AddConference\n\n    Selecting ''Add Conference'' will generate a request to add a conference\nto your list of conferences to be scanned. The Conference Select window\nwill be opened to select which conference to add.\n\n    Note that if the BBS does not support add conference requests this\nfeature will not be available.\n\n@endnode\n@node DropConference\n\n    Selecting ''Drop Conference'' will generate a request to remove a\nconference to your list of conferences to be scanned. The Conference Select\nwindow will be opened to select which conference to drop.\n\n    Note that if the BBS does not support drop conference requests this\nfeature will not be available.\n\n@endnode\n@node ResetLastRead\n\n    Selecting ''Reset Last Read Pointer'' will generate a request to reset\nthe lastread pointer in a specific conference. The Conference Select window\nwill be opened to select which conference to reset, and then you will be\nasked which message number to start scanning at.\n\n    Note that if the BBS does not support reset lastread pointers this\nfeature will not be available.\n\n@endnode\n@node DownloadAttach\n\n    Some BBSes allow files to be attached to messages. If a message has a\nfile attached to it, you can request that the file be sent with the next\nQWKMail packet you download.\n\n    Note that if the BBS does not support download attached file requests\nthis feature will not be available.\n\n@node TopOfMsg "Top Of Message"\n\n    Press the ''7'' key on the numeric keypad to jump to the top of the\nmessage.\n\n@endnode\n@node PageUpMsg "Page Up"\n\n    Press the ''9'' key on the numeric keypad to scroll up 1 page.\n\n@endnode\n@node LineUpMsg "Line Up"\n\n    Press the ''8'' key on the numeric keypad or the ''up arrow'' key to scroll\nup 1 line.\n\n@endnode\n@node LineDownMsg "Line Down"\n\n    Press the ''2'' key on the numeric keypad or the ''down arrow'' key to\nscroll down 1 line.\n\n@endnode\n@node PageDownMsg "Page Down"\n\n    Press the ''3'' key on the numeric keypad to scroll down 1 page.\n\n@endnode\n@node BottomOfMsg "Bottom of message"\n\n    Press the ''1'' key on the numeric keypad to jump to the end of the\nmessage.\n\n@endnode\n@node PageForwardMsg "Page Forward"\n\n    Press the ''Space Bar'' to page forward through the message. If the end\nof the message is reached, the next message is read.\n\n@endnode\n@node PrintMsg "Print Message"\n\n    Press ''P'' to print the current message.\n\n    The information in the message header will be printed before the\nmessage.\n\n    While the text is being printed, the mouse pointer will change to a\n''wait'' pointer and no input will be accepted in the reader window.\n\n@endnode\n@node SaveMsg "Save Message to ASCII file."\n\n    Appends the current message to an ASCII file.\n\n    A file requester will be displayed for you to select the file to be\nappended to.\n\n    If the file does not exist, it will be created.\n\n    You can set the default path and filename for the saved text in the\nconfiguration editor.\n\n    While the text is being saved, the mouse pointer will change to a ''wait''\npointer and no input will be accepted in the reader window.\n\n    The information in the message header will be included with the\nmessage.\n\n    While the text is being printed, the mouse pointer will change to a\n''wait'' pointer and no input will be accepted in the reader window.\n\n@endnode\n@node NewMsg "Enter a new message/Reply"\n\n    Use the ''New Message'' and ''Reply'' functions to enter new messages or\nreply to existing ones. The only difference between these two operations is\nthat Reply will quote the text of the original message and fill out the\n''To'' and ''Subject'' fields for you (Assuming that you wish to address your\nreply to the person who wrote the message you are replying to and you want\nto keep the subject the same [or optionally prefixed by ''RE:'', see\nconfiguration])\n\n    Depending on how your configuration is set, the reply window will be\npresented before, after, or both before and after you edit your message\ntext. Here you can change the following:\n\n    @{" From           " link RepFrom} Who the message is from.\n    @{" To             " link RepTo} Who the message is to.\n    @{" Subject        " link RepSubj} Subject of the message.\n    @{" Conference     " link RepConf} Conference to post message to.\n    @{" Public Status  " link RepPubStatus} Public/Private status of message.\n    @{" Return Receipt " link RetReceipt} Generate return receipt (if supported by BBS).\n    @{" Tagline        " link RepTagline} Tagline to add to end of message.\n\n    To accept the settings, press ''O'' or the ''Enter'' key, or click on the\n''OK'' button. To cancel the reply, press ''ESC'' or ''C'', or click on either\nthe ''Cancel'' or the close button in the upper left corner of the window.\n\n    Depending on how AmiQWK II is configured, AmiQWK will start your editor\neither before or after opening the Reply window. After editing your reply,\nexit your text editor and AmiQWK will import the message into the reply\npacket.\n\n@endnode\n\n@node RepFrom "New Message - From"\n\n    This is the name of the sender of the message. By default it is set to\nthe user name in the control.dat file.\n\n    Most BBS programs will use the name of the person uploading the .REP\npacket instead of reading this field.\n\n    This field is limited to 25 characters.\n\n@endnode\n@node RepTo "New Message - To"\n\n    This is the name of the person who the message is addressed to.\n\n    This field is limited to 25 characters.\n\n@endnode\n@node RepSubj "New Message - Subject"\n\n    This is the subject of the message.\n\n    This field is limited to 25 characters.\n\n@endnode\n@node RepConf "New Message - Conference"\n\n    Enter the conference number to post the message to here. You can either\ntype the conference number into the integer gadget (activate it by clicking\non it or by typing ''SHIFT-N'') or click the Conference button or type ''N''\n(no shift) for a @{" conference requester " link ConfSel}.\n\n    If you enter a conference number that doesn''t exist, the conference\nnumber will reset to it''s previous setting.\n\n@endnode\n@node RepPubStatus "New Message - Public Status"\n\n    This is the public status of the message. Set this to ''Public'' if you\nwant everyone to be able to read this message, or ''Private'' if you want the\nmessage read only by the person the message that the message is addressed\nto.\n\n@endnode\n@node RetReceipt "New Message - Return Receipt"\n\n    Select this gadget if you want a return receipt generated when the\nperson you are sending this message to reads it.\n\n    Note that this gadget is disabled if the BBS does not support Return\nReceipts.\n\n@endnode\n@node RepTagline "New Message - Tagline"\n\n    A tagline is a short 1 line message appended to the end of a message.\n\n    AmiQWK selects a message at random each time a new message is entered.\nIf you don''t like the tagline AmiQWK has selected, press ''L'' or click on\nthe ''Select Another Tagline'' button and a new tagline will be selected at\nrandom. Or you can select the one you like from the list gadget.\n\n    Optionally you can enter a new tagline in the string gadget below the\ntagline list.\n\n    AmiQWK can be set to select taglines randomly, sequentially, or not to\nadd taglines at all in the Configuration Editor.\n\n@endnode\n\n@node MsgIndex "Message Index"\n\n    The Message Index window lists all messages in a conference. You can\nselect a message to read by double clicking on it, or by selecting it and\npressing the ''OK'' gadget or typing ''O'' or the ''Enter'' key.\n\n    The Message Index list gadget lists who the message is from, who the\nmessage is addressed to, the subject of the message, and various flags.\n\n    ''*''     The message is addressed to you (''Personal'' message).\n    ''R''     The message has been read.\n    ''P''     The message is private.\n    ''M''     The message has been marked to be saved/printed.\n\n@endnode\n\n@node ConfSel "Select Conference"\n\n    The conference selection window is used to select a conference for\nreading, Determining which conference to post new messages to, and any\nother operation where a conference needs to be selected. The operation of\nthe conference requester may differ slightly depending on the context in\nwhich it is being used. For instance, when reading, only conferences that\nhave messages in them will be displayed, When entering new messages, all\nconferences except ''Replies'' and ''Personal'' are displayed, etc.\n\n    The conference select window will display a list of available\nconferences in a listview gadget. Here''s a sample of what you can expect to\nsee in the conference requester list gadget.\n\n                   +----------------------------------+-+\n                   |           << Replies  >>  (   1) |*|\n                   |           << Personal >>  (   3) |*|\n                   | [    0]   LocalMail       (  48) |*|\n                   | [    1]   For Sale        (   7) | |\n                   | [   25]   Amiga           ( 120) |_|\n                   | [   30]   AmiQWK Help     (  10) |^|\n                   | [   50]   IBM Clones      (  23) |v|\n                   +----------------------------------+-+\n                   | [  100]   AmiQWK Help     (  10)   |\n                   +------------------------------------+\n\n    The number on the left [in brackets] is the conference number.\n(''Replies'' and ''Personal'' are maintained internally and do not correspond to\nregular conference numbers.) In the middle are the names of the conferences,\nand the numbers on the right (in parentheses) are the number of messages\nin that conference.\n\n    To select a conference, either double-click on the conference you want\nto select, or select a conference and select ''OK'' by clicking on the ''OK''\ngadget or by typing ''O'' or the return key. You can also move up and down\nthe list by pressing the up and down arrow keys (as well as ''8'' and ''2'' on\nthe numeric keypad). The currently selected conference is displayed in the\ntext gadget below the list.\n\n    To return from the conference select window without selecting a\nconference, type ''C'', lick on the ''Cancel'' gadget, close button in the\nupper left corner of the window.\n\n\n@endnode\n@node Config_Main "Config Main Window"\n\n    Select item to configure.\n\n    @{" Operation " link Config_Operation} Set how AmiQWK operates.\n    @{" Replies   " link Config_Replies} Configure reply operation\n    @{" Paths     " link Config_Paths} Tell AQ where to find and put files.\n    @{" Archivers " link Config_Archivers} Tell AQ how to extract/compress archives\n    @{" Graphics  " link Config_Graphics} Set screen mode, fonts, colors, etc.\n    @{" Register  " link Register} Enter Registration key.\n\n    @{" Save      " link Save} Save config.\n    @{" Use       " link Use} Use this config (but don''t save)\n    @{" Cancel    " link Cancel} Discard changes to configuration.\n\n@endnode\n@node Config_Operation "Configure Operation"\n\n    Scroll Bar in text window:\n        If selected, a scroll bar will appear at the bottom of the screen.\n        The scroll bar can be used to scroll through the current text using\n        the mouse.\n\n\n    Tab Size:\n        This is the number of spaces between tab stops.\n\n\n    Ask Before Exit:\n        If selected, you will be asked if you are sure you wish to exit the\n        program before exiting.\n\n\n    After Read:\n        Use this gadget to select what actions are performed on packets\n        after they are read. the choices are:\n\n            No Action       No action is taken on the mail packet.\n            Rename Packet   Mail packet is renamed.\n            Delete Packet   Mail packet is deleted.\n            Ask             User is prompted for which action is to be\n                                taken.\n\n\n    Packet Search Pattern Match:\n        Pattern to search for when looking for mail packets.\n\n\n    Editor:\n        Command to start your text editor. Note that the editor must not\n        detach itself from the CLI that started it. If the editor\n        detaches itself from the CLI that called it, consult the\n        documentation for the editor to see if there is a command line\n        switch to prevent it from detaching. For example, TurboText users\n        should enter\n\n            C:TTX WAIT\n\n        in the editor gadget.\n\n        NOTE: There is a bug in the CygnusEd Pro activator in version 2.12.\n        Despite what it says in the manual, specifying the ''-sticky'' option\n        will not keep CED from detaching itself from the CLI. If you use\n        CED, there is a third party replacement for the ED activator which\n        does not have this bug, and is much more flexible than the one\n        supplied by ASDG. It can be downloaded from the support BBS\n        (filename CEDED4A.LZH in the AmiQWK file area) as well as many\n        BBSes, FTP sites, and online services such as BIX and Portal.\n\n\n    Spawn Window:\n        This is the specifications for the console device for the con\n        window used for running external commands. it is the same as the\n        console setting when calling the NewShell command. Consult your\n        AmigaDos manual for information on console window specifications.\n\n\n    Requesters:\n        Select which library to use for file and font requesters, ASL or\n        ReqTools. Note that this will have no effect if you are using a\n        program to patch requester libraries. Also note that even if ASL\n        requesters are selected, the ReqTools.library must still be in the\n        libs: directory as AmiQWK needs it for other functions.\n\n\n    Use:\n        Use the current settings and return to the main config window.\n\n\n    Cancel:\n        Discard changes and return to the main config window.\n\n@endnode\n@node Config_Reply "Reply Configuration"\n\n    Edit Header:\n        Select when to edit message header information. Headers can be\n        edited before, after, or both before and after editing a new\n        message.\n\n\n    Quote Prefix:\n        This is the prefix before quoted text when replying to an existing\n        message.\n\n\n    Header Info in Replies:\n        If this gadget is selected, header info such as who the original\n        message was addressed to and from, subject, conference, etc....\n        will appear at the top of the reply text.\n\n\n    RE: Prefix for reply subject:\n        If selected, ''RE:'' will be added to the beginning of the subject\n        of the message when replying, unless the subject already starts\n        with ''RE:''. This only affects replies, entering a new message will\n        not be affected.\n\n\n    Wrap/Trunc:\n        Reply text can be either be word wrapped or truncated. Use this\n        gadget to specify what operation is to be performed on reply text.\n\n\n    Column Number:\n        Enter the column number to wrap or truncate reply text here.\n\n\n    Use:\n        Use current settings and return to main config window.\n\n\n    Cancel:\n        Discard changes and return to main config window.\n\n@endnode\n@node Config_Paths "Paths Configuration"\n\n    The paths configuration window contains 4 string gadgets with a\n    ''Getfile'' button to the side. You can enter the path directly into\n    the string gadget, or click on the getfile button for a file requester.\n\n    Packet Directory:\n        This is the directory where AmiQWK looks for mail packets. This\n        should be set to the same directory your term program uses for\n        downloads.\n\n    Reply Directory:\n        This is the directory where AmiQWK stores replies. This should be\n        set to the same directory your term program uses for uploads.\n\n    Work Directory:\n        This is where AmiQWK stores work files and extracts packets to.\n        Put this in RAM if you have enough.\n\n    Saved Text:\n        This is the default filename for saved text.\n\n    Use:\n        Use current settings and return to main config window.\n\n    Cancel:\n        Discard changes and return to main config window.\n\n@endnode\n@node Config_Archivers "Archivers Configuration"\n\n    There are two string gadgets, labeled ''Compress'' and ''Extract'' for\n    each of the four supported archivers: LHArc, ZIP, ZOO, and ARC.\n    Enter the command and any options for each archiver here.\n\n    Use:\n        Use current settings and return to main config window.\n\n\n    Cancel:\n        Discard changes and return to main config window.\n\n@endnode\n@node Config_Graphics "Graphics Configuration"\n\n    Screen Mode:\n        This is the name of the currently selected display mode.\n        \n    Width, Height:\n        This is the width and height of the currently selected screen mode.\n\n    Select Screen Mode:\n        Select this gadget to choose a new screen display mode.\n\n    Edit Palette:\n        Select this gadget to change the colors AmiQWK uses.\n\n    Select Font:\n        Select the font that AmiQWK uses for message text.\n\n    Use:\n        Use current settings and return to main config window.\n\n\n    Cancel:\n        Discard changes and return to main config window.\n\n@endnode\n@node Register "Registration"\n    \n    Your Name:\n        Enter your name here.\n        \n    Registration Key:\n        Enter your registration key here.\n        \n    Status:    \n        If you have a valid registration key, this will display your serial \n        number. Otherwise it will display ''UNREGISTERED EVALUATION COPY''\n\n    Use:\n        Use current settings and return to main config window.\n\n\n    Cancel:\n        Discard changes and return to main config window.\n\n@endnode\n@node Credits "Credits"\n\n            AmiQWK II was written using the following software:\n\n    SAS/C C Development System                  SAS Institute\n    CygnusEd Professional                       ASDG Inc.\n    Quma Version Control System                 Quma Software\n    GadToolsBox                                 Jan van den Baard\n    Reqtools.library                            Nico François\n    AmigaGuide.library                          Commodore Business Machines\n\n            Thanks to the following persons for their help\n\n    Jefferey Foy            QWKMail specs and MSBIN conversion routines.\n    Greg Hewgill            Specs on DOOR.ID file and related features.\n    Patrick Y. Lee          QWKMail specs\n\n\n                            My beta testers...\n\n    Chris Hurley    Guy Bartoli     Dave Birdsong   Dennis Jann\n    Mike Soucy      Kipling Cooper  Steve Stewart   Matt Weatherford\n\n\n        And most importantly, Thanks to everyone who registered AmiQWK.\n\n\n@endnode\n','\n',char(10)),NULL,'auto-added',62375,1,0,NULL,NULL,'qwk','scan',1780048686);
