INSERT INTO door_catalog VALUES('rad_mw10','RAD-MW10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RAD-MW10.LHA',NULL,'XIM','rexxtricks.library',NULL,NULL,'RAD',':·____ / ---- ______. --- /| ---------_\/_-. \ __//\ ____\____ | ___/_|__  RAPiD \/\/ | _    _\   __     |/ ______/ dESiGN!     |',replace('________                   .           __   \n:·____ / ---- ______. --- /| ---------_\/_-.\n  \ __//\ ____\____ | ___/_|__  RAPiD \/\/ |\n   _    _\   __     |/ ______/ dESiGN!     |\n___/     \\  l/ ____j _ l  ¬\  PRESENTS    |\n ./________\ ___j  /__\\_____\  iN ''96     |\n `-------------------- \\ -----[960817]----''\n mONGOWALL 1.0 fOR AMiEXPRESs aNd dAYdREAM! \n    cOdE bY: sNÖARN & dESIGN bY: jOYCe      \n      tHE mOSt hANDy WALL dOOR EVER!        \n   wITh tHE nICESt dESIGn YOU eVER SEEN!    \n','\n',char(10)),'mastrb8.txt',replace(replace('STILL GOING STRONG in 2014!\r\n\r\n                ___         ._            _______             ·\r\n   /\  _________)  \________| \___________)__   /_________:__ :________\r\n  /  \/\  __  \    ____ ___/|  \______  \_  / _/___  \_ ____/ ¦__ \___ \\r\n /   /  \ \__  \___  \  |   |   \  _/  __/ /    /\__  \  |¦   | /  \_|  \\r\n/  \/    \_ \   \ !   \_|   !    \_\    \_     /   \   \ ||   |·    /|   \_\r\n\___|     ___\  /__    /l________ /_\    /__  /_____\  / |¦   |    /_|    /\r\n    l____/-A×E\/  \___/_!       \/   \  /   \/       \/__|:   ¦__ /  l___/\r\n       ______            _____        \/      :    ____   ·   : \/\r\n    ___)     \___________)    \__________:___ ¦____)   \__________\r\n    \    _______     _______    \___    ____/ |\_____   \______   \\r\n   /\___   \/        |    _)    \/       ¦    |/    |    \    |    \\r\n _/    !    \        |    \      \_      |    |     !     \   |     \\r\n \______     \___    |_____\      /___   |    ¦            \  |      \_\r\n       \______/ \____!      \    /   \___|    :________     \_|       /\r\n                             \  /        ¦    ·       \______/|      /\r\n   YOUVE HEARD ABOUT IT!      \/         :    ·               l_____/\r\n       \r\n         MASTURBATiON STATiON AMIGA/PC/CONSOLE/ASCII-ANSI/C64        \r\n               Telnet: bbs.masturbationstationbbs.com\r\n\r\n           UPLOAD DATE: 05-01-16  TIME: 04:20:37  ON NODE: 1\r\n\r\n  UPLOADER: Black Beard            LOCATION: mSTATION.servebbs.com    \r\n\r\nSTILL GOING STRONG in 2014!\r\n\r\n                ___         ._            _______             ·\r\n   /\  _________)  \________| \___________)__   /_________:__ :________\r\n  /  \/\  __  \    ____ ___/|  \______  \_  / _/___  \_ ____/ ¦__ \___ \\r\n /   /  \ \__  \___  \  |   |   \  _/  __/ /    /\__  \  |¦   | /  \_|  \\r\n/  \/    \_ \   \ !   \_|   !    \_\    \_     /   \   \ ||   |·    /|   \_\r\n\___|     ___\  /__    /l________ /_\    /__  /_____\  / |¦   |    /_|    /\r\n    l____/-A×E\/  \___/_!       \/   \  /   \/       \/__|:   ¦__ /  l___/\r\n       ______            _____        \/      :    ____   ·   : \/\r\n    ___)     \___________)    \__________:___ ¦____)   \__________\r\n    \    _______     _______    \___    ____/ |\_____   \______   \\r\n   /\___   \/        |    _)    \/       ¦    |/    |    \    |    \\r\n _/    !    \        |    \      \_      |    |     !     \   |     \\r\n \______     \___    |_____\      /___   |    ¦            \  |      \_\r\n       \______/ \____!      \    /   \___|    :________     \_|       /\r\n                             \  /        ¦    ·       \______/|      /\r\n   YOUVE HEARD ABOUT IT!      \/         :    ·               l_____/\r\n       \r\n         MASTURBATiON STATiON AMIGA/PC/CONSOLE/ASCII-ANSI/C64        \r\n               Telnet: bbs.masturbationstationbbs.com\r\n\r\n           UPLOAD DATE: 12-11-16  TIME: 18:31:05  ON NODE: 1\r\n\r\n  UPLOADER: Black Beard            LOCATION: mSTATION.servebbs.com    \r\n\r\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',25949,1,0,NULL,NULL,'rad_mw10','scan',1780048686);
INSERT INTO door_catalog VALUES('rad_sb10','RAD-SB10.LZX','~/Code/amiexpress_doors/Archives/AmiExpress/RAD-SB10.LZX',NULL,'XIM','rad sb10',NULL,NULL,'RAD',NULL,NULL,NULL,NULL,NULL,NULL,5078,0,0,NULL,NULL,NULL,'scan',1780048686);
INSERT INTO door_catalog VALUES('ratio11','RATIO11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RATIO11.LHA','Ratio000','XIM','Ratio000',NULL,NULL,NULL,'/ ____/ /\/  / / ____//    \\___  \/ ____/ \____ \/  \ /_/\ _/__/  /\  \ _/  /\____ \ /_____/\  /_____\____\_/ /  //___/ /_____/',replace('  ______    ___  ______ ____ ______  ______\n / ____/ /\/  / / ____//    \\___  \/ ____/\n \____ \/  \ /_/\ _/__/  /\  \ _/  /\____ \\n /_____/\  /_____\____\_/ /  //___/ /_____/\n +=SNT===\/  -+PRESENTS+-/__/============+\n |        Ratio v1.1 For AmiExpress      |\n |This Util Will Find All The Leechers On|\n |Your Board, Write Them A Msg And Give  |\n |Them A New Ratio (Optional).           |\n `---------------------------------------''\nThis File wAs DownloAded From DReaMPHaSe..','\n',char(10)),'Ratio.doc',replace('----------------------------------------------------------------------------\n\n                         Ratio v1.1 For AmiExpress\n\n                             Coded By Dux/TsL\n\n----------------------------------------------------------------------------\n\n\nFor Changes Since v1.0 Please Look At The End Of This File.\n\n\n\nThis Util Will Find All The Leechers On Your Board, Write Them A Msg And Give\nThem A New Ratio (Optional).\n\nRATIO Does Not Write In Your Original BBS:User.data File, But Creates A New\nOne In RAM:User.data_NEW.\n\n\n\nThe Syntax of RATIO is:\n\nRATIO [Confpath] [Max Ratio] [New Ratio] [Msgpath] [Min Dnload Bytes]\n\n[Confpath] Is The Full Path To Your CONFERENCE, Not Your MSGBASE! Eg.\nBBS:Market, DON''t Put A ''/'' Behind The Path.\n\n[Max Ratio] Is The Ratio RATIO Will React On. If The Users Ratio Is Above\nThis, The User Will Recieve A Msg.\n\n[New Ratio] Is The NEW Ratio The User Will Recieve. To Turn This OFF The New\nRatio Should Be 0. If You Need To Give The Leechers A Disabled Please Let Me\nKnow And I''ll Choose Something Else To Turn If Off.\n\n[Msgpath] Is The FULL Path To The Textfile To Send The Users. Eg.\nBBS:Market/Leecher.txt\n\n[Min Dnload Bytes] Is The Minimum Downloaded Bytes RATIO Will React On. Eg. If\nA User Only Have Downloaded 100000 bytes But Haven''t Uploaded Anything, Then\nIf You Set [Min Dnload Bytes] To 1000000 He Will NOT Show Up In The\nLeecherlist.\n\n\n\nRATIO v1.1 Have Been Tested On /X v2.33 (But All Regged Users Have v2.33!) And\nIs Compiled With OS2.0!\n\n\n\nChanges Since v1.0:\n\nA Major Bug Sneaked In, The Writer Of All Msgs Would Be ''PETER''. I Forgot To\nRemove This. But It Have Now Been Fixed So That All Msgs Will Come From The\nUser In Slot 1.\n\nAlso Made The Minimum Downloaded Bytes To React On.\n\nAnd A Few Minor Bugs Where Fixed.\n\n\n\nHellos Fly Out To:\n\nFrostie - Thanks For Betatesting This Util. Too Bad I Got The Bugreport Too\n          Late For v1.0 :)\n\nLector - Looking Forward To Your Board. Let''s Kick Some Unregistred Butts!\n\nRamirez\n\nAlzheimer - Wrote You A Letter Yesterday And I''ve Mailed It Today - Believe It\n            Or Not :)\n\nThe Bird - Nice Utils From You... Keep ''em Coming!\n\n\n\nREMEMBER 2 B AT THIS YEARS MAJOR EVENT: THE PARTY ''92! 27-29 DEC IN DK!\n','\n',char(10)),NULL,'auto-added',19156,5,0,NULL,NULL,'ratio11','scan',1780048686);
INSERT INTO door_catalog VALUES('rbs_cs15','RBS_CS15.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RBS_CS15.LHA','ConferenceSecurity','XIM','ConferenceSecurity',NULL,'Psw/Interval','RBS','Conan&Newton:  Conference Security V1.50 __  __ /__\/__\    o 100% recoded! since V1.30',replace('·-========================================-·\n Conan&Newton:  Conference Security V1.50\n   __  __\n  /__\/__\    o 100% recoded! since V1.30\n  \__/\__/ __ o Cursor Support added\n \________/_/ o MultiConf Configuration\n        \__/  o Psw/Interval Override\n         --   o Different Psw Fail Actions\n\n  The fucking best/safest JoinConf/Logoff\n    Amix-Door (includes many features!)\n·-========================================-·\n','\n',char(10)),'ConferenceSecurity.Guide',replace('@DATABASE Conference Security Documentation V1.50\n@NODE main "Conference Security Documentation V1.50"\n\n                         .oO· Conference Security ·Oo.\n\n                         @{" Introduction                " LINK intro}\n                         @{" General Door Info           " LINK info}\n                         @{" Installation                " LINK install}\n                         @{" Join Conference         ''J'' " LINK join}\n                         @{" Add Conference          ''>'' " LINK add}\n                         @{" Sub Conference          ''<'' " LINK sub}\n                         @{" Logoff                  ''G'' " LINK logoff}\n                         @{" Logoff Batch                " LINK batch}\n                         @{" Configuration               " LINK config}\n                         @{" Example Of A Configuration  " LINK configex}\n                         @{" Disclaimer & Copyright      " LINK discopy}\n                         @{" Final Words                 " LINK final}\n\n                    All was done by *CoNaN&NeWToN* in 1994!\n\n@ENDNODE\n@NODE intro "Introduction"\n\n   » Introduction «\n·-==================-·\n\nThis door is not a usual JoinConf program because it has been created in the\nbeleif that security can not be safe enough therefor this program will also\npatch the logoff door because of some extra options included here.\n\nIf you install this door correctly your board and more important your\nconferences should be safer than with any other Conference Door.\n\nSaying this you can not be safe from inside people abusing their Access!\n\nAll options have been tested with Normal and Relative Conferences.\nOnly Available For AmiX V3.x! (I doubt that many people are still using 2.xx)\n\nThis Is An Assembler XIM Door! Assembled with Asm-OneV100! (Personal Version)\n\nThis door can as most doors be crunched, but only if the packer does not trash\nregisters upon decrunch. Powerpacker,Imploder and CrunchMania should work.\n\nThe previous releases of this door seemed to be very difficult for sysop'' to\ninstall and I apologize for the lack of user friendly documentation.\nThis file should hopefully be more easy to understand and render nobody\nserious problems. (unless ofcoz you fail utterly to understand english :)\n\nI hope nobody takes any of my ideas and copies them, it''s all right if you find\nnew options or make same major improvement if not there is no cause to copy\nthem besides wanting a name for yourself in saying this I hope that it''s\nobvious that the likeness that a joinconf door exist with the features from\nthis door are non-existent!\n\nI excuse the size of the executables not that they are huge but they could be\na bit smaller because I have developped some standard routines I include\nwithout removing the ones not used, an excelent options for my macro-assembler.\n@ENDNODE\n@NODE info "General Door Info"\n\n   General Door Info\n·-===================-·\n\nThis door does not use any options restricted to any kickstart but Amix3.x only\nruns on KS2.0+ systems so KS2.0+ required by default. Only supports AmiX3.x\n\nThis archive only contains 68000 compatible code because there is no need for\nspecial processor optimations when the code is optimized, unlike compiler code!\n\nHandles 1-999 Conferences and 1-32 nodes.\n\nIn non internal menutype "Screens=<path>" is used to display texts.\nConfirm LogOff configuration optional.\nFeatures for Netmail Conferences.\n\nNon case sensitive and case sensitive password for conferences.\nPassword failures are kept on track by a file in ENV: which means failures\ncount for the whole time users are online. (Env:PswFailStats@%node)\nUpon password failure access level can be lowered and/or kicked off.\nPsw Failures will be entered in CallersLog.\nWhen you have 3 failures you can not any other conference with password\ncontrol.\n\nI''m afraid you will have to think of the advantages yourself if you decide to\nuse it, I hope there are options enough to satisfy everybody''s needs.\n@ENDNODE\n@NODE install "Installation"\n\n   » Installation «\n·-==================-·\n\nThe following files will be needed in order for Amix to aknowledge them.\n\nBBS:Commands/BBSCmd/\n  J.info                    "J" Join Conference.\n  <.info                    "<" Fast Join Lower Conference.\n  >.info                    ">" Fast Join Higher Conference.\n  G.info                    "G" Logoff.\n\nThe door files can be placed anywhere on your system.\n\neg.: Doors:C+N_ConfSec/\n\n  ConferenceSecurity         The XIM Door\n    Version 1.50             (Instruction Below)\n\n  ConferenceSecurity.info    The Configuration File! (AmiX 3.x Standard)\n    No Version?!             Use Wb.Info Or Dopus.\n\n  ConferenceSecurity.Exe     The Logoff.Batch File (Handling Safe Confs.)\n    Version 1.02             If You Use This Don''t Use ConfSecCleanUp.Exe Too!\n                             (Usage Information Below)\n\n  ConfSecCleanUp.Exe         Use In LogOff Batch If You Don''t Use The LogOff\n    Version 1.01             For Safe Conferences. (Usage Information Below)\n\n  ConferenceSecurity.Doc     Documentation in plain Ascii Format.\n\n  ConferenceSecurity.Guide   Documentation in AmigaGuide Format.\n\n(Progdir: is used by the program. So no specific dir used by the program!)\n\nUse c:Version to make sure the versions in this doc corresponds to the files\nin the archive.\n@ENDNODE\n@NODE join "Join Conference"\n\n   » Join Conference "J" «\n·-=========================-·\n\nJoin Conference allows people to change conference by parameter (eg. "J 5")\nor by displaying a menu if users don''t know the number for the conference they\nwish to join.\n\nUsers are also capable of adding password as a parameter instead of being\nprompted for it.\n\nPSW.5=WERULE\n\n"J 5 WeRule"\n\nYou can also assign keywords to a conference. This means that besides using\na conference number as a parameters you can use a conference keyword.\n\nie.\n\nKEYWORD.5=Amiga\n\n"J Amiga"\n\nThere are 3 different menutype which can be used, only the internal one\nhandles cursor keys. But besides the different display all actions are the\nsame.\n\nOptional Checks for:\nAccess Level\nPassword\nTimeInterval\nInclusing List\n\nSee Configuration for MenuTypes!\n\nParameters will ofcoz be recognized for shortcuts!\n  "J <confnr.>|<confkeyword> [password]"\n@ENDNODE\n@NODE add "Add Conference"\n\n   » Add Conference  ">" «\n·-=========================-·\n\nJoin the next Conferences.\n\nAccepts parameter which affects the amount of conferences you wish to skip.\nIt is ofcoz optional to add negative confereces in which case you wlll go\nbackwards.\n\nDefault is +1\n\nParameters will ofcoz be recognized for shortcuts!\n\n"> 2" = "> +2" ; forwards\n\nor\n\n"> -3"         ; backwards\n\nIt goes into Join Conference Menu if any problem occours. (See Above!)\n@ENDNODE\n@NODE sub "Sub Conference"\n\n   » Sub Conference  "<" «\n·-=========================-·\n\nJoin the previous Conferences.\n\nAccepts parameter which affects the amount of conferences you wish to skip.\nIt is ofcoz optional to sub negative confereces in which case you wlll go\nforwards.\n\nDefault is -1\n\nParameters will ofcoz be recognized for shortcuts!\n\n"< 3" = "< +3" ; backwards\n\nor\n\n"< -3"         ; forwards\n\nIt goes into Join Conference Menu if any problem occours. (See Above!)\n@ENDNODE\n@NODE logoff "Logoff"\n\n   » Logoff          "G" «\n·-=========================-·\n\nWhen a user logs off you may wish that some conferences can not be autojoined.\nThis was the idea behind the door.\n\nIf users is about to logoff In a "HOT", he will be forced to select a safe\nautojoin conference using the same menu as joinconference. However the internal\nmenu will not display safe conferences. Using any of the 3 menus will ofcoz not\nallow user to logoff in a safe conference.\n\nParameters will ofcoz be recognized for shortcuts!\n  "G <safe confnr.>"\n\nYou can ofcoz also give password as a parameter ie. "J".\n@ENDNODE\n@NODE batch "Logoff Batch"\n\n   » Logoff Batch «\n·-==================-·\n\nIn order to ensure that this door will work corretly you have to add some\ncommands in your logoff batch. The reason for this is because password failures\nare stored in a file in ENV:, so if you don''t want the next user to fall under\nany effect of the previous user, read the following instructions.\n\nTo ensure that people who loose carrier can not Auto-Join a "Safe Conference",\nin case an Account should get hacked and the intruder just happends to\nAuto-Join a Restricted Conference.\n\nConfSecCleanUp.Exe\n This one only deletes the "PSWFAILSTATS@#" that the JoinConference uses\n to control the amount of Password Failures.\n\nUsage:\n ConfSecCleanUp.Exe          Deletes all "PSWFAILSTATS@#" in Env:\n ConfSecCleanUp.Exe <node>   Deletes the "PSWFAILSTATS@#" for the <node> to\n                             be Reset!\n\nConferenceSecurity.Exe\n Changes the AutoJoin Conference in the User.Data if something needs\n to be changed. Handling of Safe Conferences.\n\nUsage:\n ConferenceSecurity.Exe          Checks AutoJoin Conference for all users.\n ConferenceSecurity.Exe <node>   Checks AutoJoin Conference for the last user\n                                 for the <node> to be reset.\n                                    Use In LogOff.Batch.\n@ENDNODE\n@NODE config "Configuration"\n\n   » Configuration «\n·-===================-·\n\nIn Order To Maintain The Same "Style" As AmiX I Have Made The Configuration\nAs An .info File ("ConferenceSecurity.info").\nYou Can Use Dopus or Workbench To Alter .info Files.\n(The Door.info Should Ofcoz Be Made According To AmiX.Docs!)\n\n<confnr.> ranges from 1 to 999.\n\nFollowing things will be recognized in the .info:\n\no MENUTYPE=<menu type>\n  <menu type>      There are 3 different menu types:\n    STANDARD       <Screens>JoinConf<access level>.<language>|.<gr>\n    AREA           <Screens>JoinConf.<area><access level>.<language>|.<gr>\n    INTERNAL       Will calculate internal menus. No bother creating files\n                   for Relative Conferences!!\n\nRelative Conferences only can also be displayed by ~MCI Codes using the one of\nthe two first ones. But I doubt it''s faster than the internal and it does not\nsupport any of the features included in this door.\n\nDefault: MENUTYPE=STANDARD\nIf <Screens> Is Not In Your BBS:NodeX.info Then "BBS:Node<x>/" Is Default.\n\n»»»»»» The following options are only used if you use MENUTYPE=INTERNAL ««««««\n\no CURSOR_ON or CURSOR_OFF\n\nDecides wheither users can use conference keys in menu.\n\no LOGO=<PATHFILE>\n\nWill display an ansi above the Conference Menu.\n\no NAME.<confnr>[.<confnr>...]=<xtra>|<conf name>\n\n<conf name> will be right centered as normal and overide "ConfConfig.Info".\n<xtra> will ne left centered, useful for Net numbers.\n\nUsing <xtra> with no <confname> will left centre <xtra> and right center the\nConfConfig ConfName.\n\no NET=<netnumber>\n\n<netnumber> is the first Net Mail Conference.\nDecides when the Net seperator is to be display, if at all.\n\no NORM_COLUMNS=<column number>\n\nNumber of Columns in Normal/Local Conference Menu.\n\n<column number> minimum 1 and maximum 3.\nColumns are Auto Adjusted if there isn''t enough space for request Columns.\n\no NET_COLUMNS=<column number>\n\nNumber of Columns in Net Conference Menu.\n\n<column number> minimum 1 and maximum 3.\nColumns are Auto Adjusted if there isn''t enough space for request Columns.\n\n»»»»»»»»»»»»»»»»»»»»»»»»»»»»»»» General options «««««««««««««««««««««««««««««««\n\no KEYWORD.<confnr>=<keyword>\n\n<keyword> is a string with no spaces that can be used instead of conference\nnumbers when using parameters.\n\no AXX.<confnr.>[.<confnr.>...]=<access level>\n\nUser needs accesslevel higher or equal to <access level> to join conference.\n\n<access level> ranges from 1 to 255.\n\no PSW.<confnr.>=<password>\n\nPassword required before user can join conference. Non Case Sensitive.\n\n<password> can be 32 Characters.\n\no CPSW.<confnr.>=<password>\n\nPassword required before user can join conference. Case Sensitive.\n\n<password> can be 32 Characters.\n\no NOPSWAXX[.<confnr.>...]=<access level>\n\nUsers with accesslevel higher or equal to <access level> can join conference\nwithout having to enter password.\n\nNOPSWAXX=<access level> will be used as a default if none is specificly given\nto a conference.\n\n<access level> ranges from 1 to 255.\n\no AXXFAIL[.<confnr.>...]=<access level>\n\nUpon password failure users access level is dropped to <access level>.\nIf user has a lower access level than the one he should be give his access\nlevel will not be changed in which case it would have become higher.\n\nDefault: AXXFAIL=10\n\nAXXFAIL=<access level> will be used as a default if none is specificly given\nto a conference.\n\n<access level> ranges from 1 to 255.\n\no KICKFAIL[.<confnr.>...]\n\nUpon password failure user is kicked by dropping dtr. Does not work under\nsysop or local login.\n\nKICKFAIL without any specific conferences will kick user after password\nfailure whatever conference it way happend in.\n\no LIST.<confnr>[.<confnr.>...]=<listpathfile>\n\nThe name of an .info file where the names of all users allowed in conference\nare figured in the tooltypes.\n\n<listpathfile> must be without .info in the end.\n\no DAY.<confnr>[.<confnr.>...]=<Day On/Off>\n\n<Day On/Off> is made of 7 chars. One for each day. "X" for ok. First char\nis Sunday snd the last is Saturday.\n\nEg.: DAY.3=X__X__X. Conference 3 Can Be Joined On Sundays Wednesdays And\nSaturdays Only!\n\nSelect which days a conference can be joined. Each day can be either "X" for\nopen and "_" for closed. And ofcoz 7 of them.\n\nDefault: DAY.<confnr>[.<confnr.>]=XXXXXXX\n\no TIME.<confnr>[.<confnr.>...]=<HHMM>,<HHMM>\n\nSelect which time interval a conference can be joined. You can ofcoz configure\nmore than 1 interval for the same conference.\n\n<HHMM>,<HHMM> start time,end time of interval.\n\nDefault: TIME.<confnr>[.<confnr.>]=0000,2359\n\no NOINTAXX[.<confnr.>...]=<access level>\n\nUsers with accesslevel higher or equal to <access level> can join conference\nat any time independant of day and time intervals.\n\nNOINTAXX=<access level> will be used as a default if none is specificly given\nto a conference.\n\n<access level> ranges from 1 to 255.\n\no DAYTIME_PRIVATE[.<confnr.>...]\n\nIf user tries to join conference then days and time intervals where user can\njoin will be suspressed.\n\nDAYTIME_PRIVATE without any conference means that all conferences with an\ninterval will not display open/closed intervals.\n\n»»»»»»»»»»»»»»»»»» The following options only affect logoff ««««««««««««««««««\n\no HOT.<confnr.>[.<confnr.>...]\n\nA conference where users cannot AutoJoin!\n\no CONFIRM=<confirm type>\n<confirm type>   Different Types\n  NONE           User Does Not Have To Confirm LogOff.\n  NOTEXPERT      User In Non Expert Mode Has To Confirm LogOff.\n  EXPERT         User In Expert Mode Has To Confirm LogOff.\n  ALL            User Has To Confirm LogOff.\n\nDefault: CONFIRM=NONE\n\n\nMost of the options have the following [.<confnr.>...] and this means that\nyou do not have to add more conference numbers but you can if you need to.\n\nThe ones with .<confnr> means that at least one conference number is required\nfor this option to work.\n\nOfcoz when both are present alleast one is required but more conferences can\nbe assigned the same function.\n\nAll Strings Can Use Upper or Lower Case, The Door Is Not Case Sensitive.\nExcept of course Case Sensitive Passwords.\n\nMost Options Are Maybe Pretty Weird But Try Them And You Will Maybe Find\nOut Their Purpose And Future Purposes For You.\n@ENDNODE\n@NODE configex "Example Of A Configuration"\n\n   » Example Of A Configuration «\n·-================================-·\n\no MENUTYPE=Internal\n\nInternal menutype selected!\n\no CURSOR_ON\n\nCursor keys can be used in conference menu.\n\no LOGO=Doors:MST_ConfSec/JoinConf.Logo\n\n"JoinConf.Logo" will be display above the confmenu.\n\no NAME.5=[UN0001]|Hard Core\n\nA new conference name is assigned to conference 5 along with an extra left\ncentered string.\n\no NAME.4=Crap Request\n\nOnly a new name is assigned and nothing will appear on the lefthand side.\n\no NAME.2=Local|\n\nThis will not changed the original name for your conference only add a string\non the lefthand side.\n\no NET=4\n\nA seperator will appear between normal and net conferences\n\no NORM_COLUMNS=3\n\nNormal conferences will appear in 3 columns unless ofcoz there isn''t enough\nspace sideways!\n\no NET_COLUMNS=2\n\nNet conferences will appear in 2 columns unless ofcoz there isn''t enough\nspace sideways!\n\no KEYWORD.5=ELITE\n\nInstead of typing "J 5" you can type "J ELITE"\n\no AXX.3=100\n\nTo join conference 3 you need access level higher or equal to 100\n\no PSW.5=innersanctum\n\nPassword required to obtain access to conference 5\n\no CPSW.4=DuLpErT                         : Case Password For Conf 4\n\nCase Sensitive Password required to obtain access to conference 4\n\no NOPSWAXX=255\n\nUser with access level higher or equal to 255 will be able to join conferences\nwith password check.\n\no AXXFAIL=100\n\nUpon password failure users access level will drop to 100 unless it is lower\nthan 100 already!\n\no KICKFAIL\n\nAfter password failure user will be kicked off, this is checked after AXXFAIL\nso both can be applied at the same time.\n\no HOT.5\n\nUsers will not be able to autojoin conference 5\n\no LIST.2=Doors:MST_ConfSec/Conf2List\n\nA list of people allowed to join conference 2. This way even if a person\nmanages to convince a person that he is a member he will not be allowed to\njoin conference.\n\no DAY.3=XXX_XXX\n\nUser able to join conference 3 every day except wednesday\n\no TIME.3=1100,1300\n  TIME.3=1930,2300\n\nUsers are only allowed to join conference 3 in the before mentioned time\nintervals\n\no NOINTAXX=255\n\nUser with access level higher or equal to 255 will be able to join conferences\nin spite of day and time intervals.\n\no DAYTIME_PRIVATE\n\nUsers will not be shown a display with open/closed days and time intervals.\n\no CONFIRM=NOTEXPERT\n\nUpon logoff only people who are not in expert mode wll be asked to confirm\ntheir logoff.\n\n\nIn accordance to the paragraf before.\n\nYou can assign multiple conferences to most of the options.\n\nAXX.4.5=245\nAXXFAIL.3=100\nDAYTIME_PRIVATE.5.3\nHOT.3.4.5\nKICKFAIL.4.5\nNAME.2.3.4=LOCAL|\nNOINTAXX.3.5=200\nNOPSWAXX.3.5=200\n@ENDNODE\n@NODE discopy "Disclaimer & Copyright"\n\n   » Disclaimer&Copyright «\n·-==========================-·\n\nWe do not take any responsability for any loss of data using this or any other\nproducts by yours truly. Allthough how unlikely it may be!\nThis door should only be spread in its original states.\nThis is not public domain, no fee can be taken for this program!\n\n(©) 1993-94 by Conan&Newton.\n@ENDNODE\n@NODE final "Final Words"\n\n   » Final Words «\n·-=================-·\n\nThis door was created in 1993 and updated in mid 1994.\nAll coding by Conan&Newton.\n\nV1.00 -> V1.23 Beta testing by Mean/Mystic. Minor bug reported by Yobbo/Rebels.\n\nV2.00 is coming very soon as this version now includes all features needed and\nalso all features supported by other doors. And alot more that nobody else has!\n\nI would include the ASM source but since this increases the risc of people\nmaking lame versions I won''t but maybe we can arrange something.\n\nIf you wish to contact us for any reason, we can be reached by mail at:\n\nNet Contact...\nAmiXnet: @DK0001 (MAiNLiNE) .. handle: "CoNaN&NeWToN"\nFiDONET:\nE-Mail : N/A! :(\n\nor by modem at any of the following danish boards:\n\nBody Count\nMainline\nMegabyte\nMercyful Fate\nNonStop Up''n Down\nPlastic Passion\nSky Tower\nStatic Chaos\nSuffocation\nThe Larch\nWarez Unlimited\n\nWe travel under "CoNaN&NeWToN" so if you see us arround...\n\nSorry about not having any means of being contacted outside denmark but I\nneed a clean record for the jobs i''m gonna persue therefor no cheating.\n\nIt would be nice to know if people use our doors on their boards!\nSo please contact us just for fun. Or for suggestions,bugs and ideas.\n\nGreetings to all our friends!\nYou know who you are and most of you probably won''t be reading this anyway.\n@ENDNODE\n','\n',char(10)),'{"TYPE":"<menu"}','auto-added',44190,6,0,NULL,NULL,'rbs_cs15','scan',1780048686);
INSERT INTO door_catalog VALUES('rea_bc10','REA-BC10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/REA-BC10.LHA','BAUD-COUNTER','XIM','BAUD-COUNTER',NULL,'hIGH-SPEEd','REA','\______  \_  ___/ /    \ \_    /// |  __/ _/   _)__/   |_ \/   _/__ |     |  \    \_  |   \  __/  \   |   \    |',replace('     _________________  /\__  _______ _\n     \______  \_  ___/ /    \ \_    ///\n      |  __/ _/   _)__/   |_ \/   _/__\n|     |  \    \_  |   \  __/  \   |   \    |\n|nO#2 |___\    /____  /___|    \ ___  /    |\n+------hKWd\  /-----\/----|     \---\/-----+\n|===========\/ /X DIVISION ================|\n!            bAUD-cOUNTER V1.0             |\n:                                          :\n|      mADE By hIGH-SPEEd & [-sAxOn-]      |\n|                                          |\n^-[fLYING DRAGON]---------------[rEAL WHq]-^','\n',char(10)),'BAUD-COUNTER.DOC',replace('\n ____________  /\___________________  /\___________________  /\__________\n             \/                     \/                     \/\n\n01:                                                           \n                           · R E A L - L O G O ·\n\n\n                  _ _ ___________________/\___________ _ _ \n                   \\\\______  __  ______    ____    ////  \n                       |  __/ _/   _)__/   |_ \/   _/__    \n                      ||  \    \_  |   \  __/  \   |   \   \n                      ||___\    /____  /___|    \____  /   \n                      `-----\  /-----\/----|     \---\/-.  \n                             \/-PROUDLY PRESENT-           \n  \n                             There /X Tool #2 \n\n                            bAUD-COUNTEr V1.0! \n\n\n\n ____________  /\___________________  /\___________________  /\__________\n             \/                     \/                     \/\n\n02:\n                            · I N D E X ·\n\n\n                   01: REAL LOGO AND TOOL NAME !!!\n                   02: INDEX THIS PAGE\n                   03: FILE_ID\n                   04: INSTALLIATION\n                   05: REAL WHq\n                   06: TOOL-TYPES\n                   07: GREETINGS\n                   08: COPYRIGHTS\n\n\n ____________  /\___________________  /\___________________  /\__________\n             \/                     \/                     \/\n\n03:\n                         · F I L E _ I D ·\n\n\n@BEGIN_FILE_ID.DIZ    _________________  /\__  _______ _\n    \______  \_  ___/ /    \ \_    ///\n     |  __/ _/   _)__/   |_ \/   _/__\n|    |  \    \_  |   \  __/  \   |   \     |\n|    |___\    /____  /___|    \ ___  /     |\n+-----hKWd\  /-----\/----|     \---\/------+\n|==========\/ /X DIVISION =================|\n!        bAUD-cOUNTER! dOC V1.0            |\n:                                          :\n|          mADE By [-sAxOn-]               |\n|                                          |\n#-[fLYING DRAGON]--------------------------#\n@END_FILE_ID.DIZ\n\n\n ____________  /\___________________  /\___________________  /\__________\n             \/                     \/                     \/\n\n04:\n                        · I N S T A L A T I O N ·\n\n\n            fIRST DEPACK THE FILE rEA-BC10.LHA INTO RAM:\n          NOW COPY RAM:COMMANDS/SYSCMD/BAUD-COUNTER.INFO INTO\n                     YOURE BBS:COMMANDS/SYSCMD/\n        NEXT STEP IS TO COPY RAM:DOORS/REAL/ TO YOUR DOORS: DIR\n         AND FINALY YOU HAVE REACHED THE STARS COZ OF IT RUNNS\n\n            TO MANAGES THIS DOOR YOU MUST EDIT THE TOOLTYPES\n                 OF BAUD-COUNTER.INFO INTO YOUR SYSCMD\n              FOUR THIS CAPTURE LOOK INTO 06: 4 MORE INFOS\n\n\n\n\n ____________  /\___________________  /\___________________  /\__________\n             \/                     \/                     \/\n05:\n\n                       · R E A L - W H Q ·\n\n                      ____\n   _ _ _______________\   \__:::__________________ _ _\n    \\\\_   _____    / \   \ :::______   __  ____////\n       /   ____/   _/__ \    :::/    /   /   \__ \\n     |/    /  /    |   \/   /:::    /   /         \\n     /    /   \________/   /_:::___/   /\_________/\n     \   /-------------\  /--:::---\  /---------------------.\n      \_/               \/          \/                      |\n           .--(PRODIGY GHQ)--(DELIGHT GHQ)--(ILLUSION GHQ)--+\n           | _ _ _____\n           |  \\\\    \ _________  /\_____________________________\n           |    __\____\\______  \/    __   _____    __________   \\n           |   /    _____/  __/ _/   |_ \   \__ \   /   \/    /   /\n           |   \    \    \  \    \_ __/  \       \       \   /   /\n           |    \________/___\    /__|    \______/_______/__/   /\n           `------------------\  /---|     \-----(hKWd)-----\  /--.\n                               \/                            \/\n                     ----( REAL /X DIVISION WHQ )----\n\n\n             -( fLyInG dRAGon     rEsPeCt tO tHe maXIMum )-\n\n\n ____________  /\___________________  /\___________________  /\__________\n             \/                     \/                     \/\n\n06:\n                        · T O O L - T Y P E S ·\n\n               yOU fOUND ThIs Into The BAUD-COUNTER.INFO\n\n\n================================================================================\n\n            ---------------------------------------------\n                          BC_USER.1=NAME\n            ---------------[ CUT HERE ]------------------\n\nBC_USER.1=NAME\n\n The siGn NAME stANDs 4 Any Body U AllOWed To use With a 14.4Modem a\n                        28.8 Node .... z.b.\n\n                        BC_USER.1=aLPHA ONe\n\n     Now This gUy Can Use The Node Without A cheCK of The COnnecTion\n\n              BC_USER.1=aLPHA ONe       BC_USER.2=sIRIAX\n\n        fINAly U caN Give MAny PeoPle The axS wiThoUt a ChecK !!\n\n\n================================================================================\n\n             ---------------------------------------------\n                           BC_NODE.1=NODE \n             ---------------[ CUT HERE ]------------------\n\n          NODE stanDs 4 The nODE # aND Can Be REnAMed tO 1 or 2\n                      Or tO eAch OtheR nODe Nr.\n\n                           BC_NODE.1=1 \n\n             U cAN cHEck mORe ThaN 1 Note ...I`ve U wAnt\n\n                           BC_NODE.1=2 \n                           BC_NODE.2=4 \n\n                Now U cHecK note 2 ^ 4 Four Low BauD\n\n================================================================================\n\n                ---------------------------------------------\n                            BC_NODEBAUD.1=BAUD \n                ----------------[ CUT HERE ]-----------------\n\n                The BAUD sTAnds 4 The BaudConnecT U wiLl AXs \n                    19200 z.b. Gives A 19200 cOnnecT aNd\n                         aCzePt ThiS 4 thIs NotE !!\n                   And This Guy Can wIth 19200 Login !!\n\n\n                            BC_NODEBAUD.1=19200\n\n\n                 nOTE: NEver WriTe This 19.200 !!!!!!!!!!!!\n\n\n================================================================================\n\n                ---------------------------------------------\n                           BC_USERNOT.<num>=<name>\n                ---------------[ CUT HERE ]------------------\n\n             This Guy Can Now No Never LogIn In witH this HANdle\n\n                          BC_USERNOT.1=gENERATION\n\n                 i`Ve U Wanna LOg A uSer WitH This TooL \n                    dEfin The TexT BC_USERNOTTEXT\n\n\n================================================================================\n                    ---------------------------------------------\n                           BC_USERNOTTEXT=pATH:TEXTNAME\n                    --------------[ CUT HERE! ]------------------\n\n                    I`ll ThinG I`LL musT Now NotIng More Say This\n                          Is So eAsy ThaT everY PeoPle cAn\n                              Made It 4 Youre Own ....\n\n                            BC_USERNOTTEXT=pATH:TEXTNAME\n                            BC_BAUDNOTTEXT=PATH:TEXTNAME\n\n================================================================================\n\n ____________  /\___________________  /\___________________  /\__________\n             \/                     \/                     \/\n\n07:\n                         · G R E E T I N G S ·\n\n\n                       Some short greetings to:\n\n            =  pYRO = sIRIAX = aLPHA ONe = dECCA = tOLPAN =\n      = vOiCe = GaLaXy = rAY = sPEED = bEN.E = 5r = aZURE = rKR =\n   = gENERATION! = -Jd & gUZZMAN = nITRO = hITPOINT = tRON = dEVIL =\n       = jAYJALKER = kRYPTON = sCANDIC = dEETZ = gONZO = aWSON = \n        = jOHN SINCLAIr = bLADE = vAMPIRE = mARIO = aNTIBRAIN =\n     = sLAXX = gANDALF! = cRISI = aRGON = gENERAL CHAOs = sULTAN =\n        = cHAOS = cRASH = sLIME = cYCLONE = sPOON = bASHGUARD =\n     = rASSI! = pENTANGLE = sLIME&vOYAGe = lANCe = eTRON & jOKER =\n\n      = oF cOz To All MEMBERS oF ILLUSION^DELIGHT^PRODIGY^REAL! =\n\n\n\n[-sAxOn-]\n\n ____________  /\___________________  /\___________________  /\__________\n             \/                     \/                     \/\n08:\n                          · C O P Y R I G H T ·\n \n=========================================================================\n                         this tool is FREEWARE\n                   copyright © 1995 hIGH-SPEEd/rEAL!\n=========================================================================\n\n ____________  /\___________________  /\___________________  /\__________\n             \/                     \/                     \/\n\n\n','\n',char(10)),NULL,'auto-added',21430,4,0,NULL,NULL,'rea_bc10','scan',1780048686);
INSERT INTO door_catalog VALUES('rea_bc11','REA-BC11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/REA-BC11.LHA','bAUD-cOUNTER','XIM','bAUD-cOUNTER',NULL,'hIGH-SPEEd','REA','_ _______. _ _______ ___________|       : |  ____   /_\      _   |   ____|_ _ \______| /______/   \_____\   |   \',replace('    -[ REAL - /X DIVISION ]-    :       ·\n_ _______. _ _______ ___________|       :\n         |  ____   /_\      _   |   ____|_ _\n  \______| /______/   \_____\   |   \\n      |_________________________|________ __\n      :b!d\n      .      ... bRINGz yA ...\n \n             bAUD-cOUNTER V1.1\n \n    - dONe bY hIGH-SPEEd ^ [-sAxOn-] -\n','\n',char(10)),'bAUD-cOUNTER.doc',replace('                 .:::::.  .::::.      ..:::::.     ..:::::.\n               .::::::::.:::::::.   .:::··:::::   ::·:::::·\n             .:::::::::::::::::::  .:::·   ::::    .::::·\n         .:::::· :::::::·   :::::: ·::·    ::::   .:::·\n         :::::  ::::::::    ::::::    .... ::::  .:::·\n          :::.  :::::::;   ::::::; .::::::::::: .:::·          ...\n           :::. ·::::::...::::::· .::::··:::::: :::·          ::::.\n           ·:::. ··::::::::::··   ::::    ::::::::·            ::::\n            ·:::.  :::·        ..:::::    :::::::::.......:::::::::\n             ::::; :::    ...::::::::::..::::::::::::::::·····::::;\n              ···  ·::::::::::::· ·::::::::::·····b!d\n                    ·::::····\n\n                              ... bRINGz yA ...\n\n                              bAUD-cOUNTER V1.1\n\n                         - cODe dONe bY hIGH-SPEEd -\n\n                           - diZiGN bY [-sAxOn-] -\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\niNTRODUCTIOn\n\n              ... this is the greate bAUD-cOUNTER from rEAL ...\n\n  Features:\n\n          - check if Baud on Port is high enough for it\n          - kick user you don''t want\n          - full configurateable\n          - no backdoor\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\nrEGISTRATIOn\n\n   This tool is SHAREWARE, so if you use it, you have to register...\n   The registration cost you only 10,- DM or 10 US-$...\n   You only have to transfer the money to me...\n\n   Account Name    : Olaf Gramkow\n   Account Number  : 10141901\n   Bank Code Number: 24050110\n   Sparkasse Lüneburg\n\n   Use: - Registration bAUD-cOUNTER\n        - Name/Handle, Group, BBS-Name, State\n        - get the reg. Version from which BBS (fLYING dRAGON, tHE dUNGEON)\n\n   Example for Use:\n      hIGH-SPEEd, rEAL, tHE dUNGEON, Germany\n      get it from tHE dUNGEON\n\n   After you sent me the money, you can get your REGISTRATED VERSION\n   in one of the following BBSs:\n      fLYING dRAGON - rEAL wHQ\n      tHE dUNGEON   - rEAL gHQ\n   Please tell me which one...\n\n   but don''t forget... for the registration I need the following stuff:\n     Name/Handle, Group, BBS-Name, State\n\n   If you want to sent me the money by letter, then write a mail to\n   hIGH-SPEEd in tHE dUNGEON BBS or in the fLYING dRAGON BBS...\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\nrEQUIREMENTs\n\n                            Everyone can run it!!!\n\n          - you only need an AMIGA or compatible (DRACO)\n          - and the great AmiExpress V4.x\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\niNSTALLATIOn\n\n                      The installation is very simple...\n\n   - copy the directory rEAL with all the files to DOORS:\n   - copy the directory COMMANDS with all the files to BBS:\n   - include the following line in the BULL.txt:\n       ~CC_sEC-CHECk \n   - now change the Tooltypes in the bAUD-cOUNTER.info Icon in the\n     BBS:COMMANDS/SYSCMD directory (see also cONFIGURATIOn)\n\n   ready...\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\nwORKINg\n\n   This Door only looks at every logon of a user on a specified Node, if\n   the Baudrate is high enough for this Node. If not, a text will be shown\n   and the User will be kicked out.\n   But you can also define Users, which will kick out, too (don''t check\n   Baudrate) (only in the registered version).\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\ncONFIGURATIOn\n\n  You can configurate the Door. You have to change some Tooltypes in the\n  bAUD-cOUNTER.info Icon in the BBS:COMMANDS/SYSCMD directory.\n\n  Tooltypes:\n     BC_USER\n     BC_NODE\n     BC_NODEBAUD\n     BC_USERNOT (only registered version)\n     BC_USERNOTTEXT (only registered version)\n     BC_BAUDNOTTEXT\n\n  BC_USER:\n     Pattern : BC_USER.<num>=<name>\n     Function: Here you can select which Users will not be checked. After\n               the text "BC_USER." comes a number beginning with 1.\n               (in the demo version all user will be checked)\n     Example : BC_USER.1=hIGH-SPEEd\n               Don''t check the User hIGH-SPEEd.\n\n  BC_NODE:\n     Pattern : BC_NODE.<num>=<num>\n     Function: Here you can select a Node for the Baudchecking. After\n               the text "BC_NODE." comes a number beginning with 1. If you\n               use this Tooltypes you have to use the Tooltype BC_NODEBAUD\n               for this Number, too.\n     Example : BC_NODE.1=1\n               Check Baudrate of Node 1.\n               You must also have something like the following in the\n               Tooltypes: BC_NODEBAUD.1=2400 (see below)\n\n  BC_NODEBAUD:\n     Pattern : BC_NODEBAUD.<num>=<num>\n     Function: Here you can select the Baudrate for checking. After the\n               text "BC_NODEBAUD." comes a number beginning with 1. To take\n               effekt of this Tooltype you have to use the Tooltype BC_NODE\n               for this Number, too.\n     Example : BC_NODEBAUD.1=2400\n               Baudrate to check for on selected Node.\n               You must also have something like the following in the\n               Tooltypes: BC_NODE.1=1 (see above)\n\n  BC_USERNOT:\n     Pattern : BC_USERNOT.<num>=<name>\n     Function: The User here listed will be kicked out (Baudrate will not\n               be checked). After the text "BC_USERNOT." comes a number\n               beginning with 1.\n     Example : BC_USERNOT.1=SUPERMAN\n               If the user SUPERMAN has log on, a text will be shown\n               (selected with BC_USERNOTTEXT (see below)) and the user\n               will be kicked out.\n\n  BC_USERNOTTEXT:\n     Pattern : BC_USERNOTTEXT=<name>\n     Function: Select the text, which will be shown if the actual User\n               is not allowed on the Node.\n     Example : BC_USERNOTTEXT=DOORS:rEAL/bAUD-cOUNTER/UserNot.txt\n               This text will be shown if User not allowed on this Node.\n\n  BC_BAUDNOTTEXT:\n     Pattern : BC_BAUDNOTTEXT=<name>\n     Function: Select the text, which will be shown if the actual Baudrate\n               is not high enough for this Node.\n     Example : BC_USERNOTTEXT=DOORS:rEAL/bAUD-cOUNTER/BaudNot.txt\n               This text will be shown if Baudrate to slow.\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\ngREETINGs!\n\n                           ... GReeTz fLYIng To ...\n\n      spEZIaL greETz fROM hIGH-SPEEd 2:\n\n      InTENsiTy , DoC waTSoN , GoroNIt , REvOlVer , sILicON sUrFEr\n      anD tO aLl PhANTasM MeMBerS...\n\n      spEZIaL greETz fROM [-sAxOn-] 2:\n\n      SIRiAX , aLPHA ONe , pYRO , sLIME! , mARIO , vAMPIRE , JOHN SINCLAIR ,\n      gALAXY , HITPOINT , KRYPTON , 2FAST , DECCA , SIRE , CHAOS , PET ,\n      SABINE, cANNIBAL , sTARLIGHT , H2o , mAGGY , sPIRIT , aNETTE , aNDREA ,\n      SPEEDY , fRANK , jAYWALKER , pICARD , BASTARd^aPOLLO , 5r , Awson ,\n      dEETs , gONZO , BEN.E , aZURE! , trON,cRAsh , Gandalf , CRisi ,\n      SLaxx , pedl ^ dello\n\n      and of coz 2:\n\n                       sPIRIT and tHE aLIEN\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\nmEMBERs, iNFOs, bOARDs\n\nmEMBAS:\n        [-sAxOn-]   mAIN-oRGA , WHq , cODER , dZ\n        hIGH-SPEEd  mAIN-cODER , oRGA , GHq , dZ\n        Picard      EHq , AREXX-CODEr?\n        HawKwind    Dz\n        bASHGUARD   Dz\n\nbOARDS:\n        [-sAxOn-]   fLYING DRAGOn   - rEAL WHq - gERMANY\n        pICARD      pARADISE LOST   - rEAL EHq - gERMANY\n        hIGH-SPEEd  tHE dUNGEON     - rEAL Ghq - gERMANY\n        sTARLIGHT   tRADERS ASSAULt - rEAL diS - gERMANY\n\nbETA TESTER:\n        jOHN sINCLAIR dRIVE bY SHOOTING - rEAL bETA tESTER - gERMANY\n        cANNIBAL      eXTREME TERROR    - rEAL bETA tESTER - gERMANY\n\ntRADER:\n        rKR       [ dRAGON-TEAm ] nO rEAL mEMBER ....bOARD tEAM\n        dEVIL     [ dRAGON-TEAm ] nO rEAL mEMBER ....bOARD tEAM\n        TyROX     [ dRAGON-TEAm ] nO rEAL mEMBER ....bOARD tEAM\n        cALAVERA! [ dRAGON-TEAm ] nO rEAL mEMBER ....bOARD tEAM\n\n                  ..... rIGHT rEAL hAS nO rEAL tRADER ......\n                     \----------------------------------/\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\nrELEASEd\n\n   sYS-DOWn V1.0       nOW aVAILABLE...\n   bAUD-cOUNTER V1.1   nOW aVAILABLE...\n   sEC-CHECk V1.3      nOW aVAILABLE...\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\ncOMMING SOOn\n\n   sYS-DOWn V1.1       bETA tEST rUNNING (tHE dUNGEON, fLYING dRAGON,\n                                          dRIVE bY sHOOTING)\n   rEAL-CALLERs V1.0   bETA tEST rUNNING (tHE dUNGEON, fLYING dRAGON,\n                                          dRIVE bY sHOOTING)\n   cONF-MOVEr V1.0     bETA tEST rUNNING (tHE dUNGEON, fLYING dRAGON)\n   rEAL-pAGE V1.0      bETA tEST rUNNING (tHE dUNGEON)\n   rEAL-RECORDs V1.0   bETA tEST sOON\n   rEAL-WHO V1.0       bETA tEST rUNNING (tHE dUNGEON)\n   sTATUS dOOR V1.5    bETA tEST rUNNING (fLYING dRAGON)\n   fRONTWHO V1.7       bETA tEST rUNNING (fLYING dRAGON)\n   lOGOFF DOOR V1.0    bETA tEST sOON\n\n-===-==