INSERT INTO door_catalog VALUES('rea_cm10','REA-CM10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/REA-CM10.LHA','cONF-MOVEr','XIM','cONF-MOVEr',NULL,'hIGH-SPEEd/rEAL','REA','_ __:___  _ ______ __ _______ _ __:_ ___  /__    ___/__  ____   \   ___\__ __ \_      \   __\   \ \__     \  \',replace('      ...........[ REal ]............\n  _ __:___  _ ______ __ _______ _ __:_    \n    ___  /__    ___/__  ____   \   ___\__ __\n    \_      \   __\   \ \__     \  \\n _ ___\      \__\      \__\      \ __\n    b!d\______\  \______\  \______\ :\__ _ _\n      :                             :\n      :       cONF-MOVEr V1.0       :\n      ·                             .\n      .   dONE bY hIGH-SPEEd/rEAL\n \n         - directly from Party V -\n','\n',char(10)),'cONF-MOVEr.doc',replace('                 .:::::.  .::::.      ..:::::.     ..:::::.\n               .::::::::.:::::::.   .:::··:::::   ::·:::::·\n             .:::::::::::::::::::  .:::·   ::::    .::::·\n         .:::::· :::::::·   :::::: ·::·    ::::   .:::·\n         :::::  ::::::::    ::::::    .... ::::  .:::·\n          :::.  :::::::;   ::::::; .::::::::::: .:::·          ...\n           :::. ·::::::...::::::· .::::··:::::: :::·          ::::.\n           ·:::. ··::::::::::··   ::::    ::::::::·            ::::\n            ·:::.  :::·        ..:::::    :::::::::.......:::::::::\n             ::::; :::    ...::::::::::..::::::::::::::::·····::::;\n              ···  ·::::::::::::· ·::::::::::·····b!d\n                    ·::::····\n\n                              ... bRINGz yA ...\n\n                               cONF-MOVEr V1.0\n\n                         - dONe bY hIGH-SPEEd/rEAL -\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\niNTRODUCTIOn\n\n                ... this is the greate cONF-MOVEr from rEAL ...\n\n  Features:\n\n          - move files between confs (with date - to dir)\n          - fast search routine\n          - no backdoor\n\n-===-===-===-===-===-===-===-===-