INSERT INTO door_catalog VALUES('rea_rc11','REA-RC11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/REA-RC11.LHA','rEAL-CALLERs','XIM','exe.-l0S-eND0S-bBS-.exe',NULL,'hIGH-SPEEd/rEAL','REA','_ __:___  _ ______ __ _______ _ __:_ ___  /__    ___/__  ____   \   ___\__ __ \_      \   __\   \ \__     \  \',replace('      ...........[ REal ]............\n  _ __:___  _ ______ __ _______ _ __:_    \n    ___  /__    ___/__  ____   \   ___\__ __\n    \_      \   __\   \ \__     \  \\n _ ___\      \__\      \__\      \ __\n    b!d\______\  \______\  \______\ :\__ _ _\n      :                             :\n      :      rEAL-CALLERs V1.1      :\n      :                             :\n      : tHE bEST lAST-cALLER fOR /X :\n      :        nOW bUG fREE!        .\n      . - dONE bY hIGH-SPEEd/rEAL -\n','\n',char(10)),'rEAL-CALLERs.doc',replace('                 .:::::.  .::::.      ..:::::.     ..:::::.\n               .::::::::.:::::::.   .:::··:::::   ::·:::::·\n             .:::::::::::::::::::  .:::·   ::::    .::::·\n         .:::::· :::::::·   :::::: ·::·    ::::   .:::·\n         :::::  ::::::::    ::::::    .... ::::  .:::·\n          :::.  :::::::;   ::::::; .::::::::::: .:::·          ...\n           :::. ·::::::...::::::· .::::··:::::: :::·          ::::.\n           ·:::. ··::::::::::··   ::::    ::::::::·            ::::\n            ·:::.  :::·        ..:::::    :::::::::.......:::::::::\n             ::::; :::    ...::::::::::..::::::::::::::::·····::::;\n              ···  ·::::::::::::· ·::::::::::·····b!d\n                    ·::::····\n\n                              ... bRINGz yA ...\n\n                              rEAL-CALLERs V1.1\n\n                         - dONe bY hIGH-SPEEd/rEAL -\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\niNTRODUCTIOn\n\n                ... this is the greate LAST-CALLER from rEAL ...\n\n  Features:\n\n          - fully configurable\n          - you can make your own outfit (only registered version)\n          - no backdoor\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\nrEGISTRATIOn\n\n   This tool is SHAREWARE, so if you use it, you have to register...\n   The registration cost you only 10,- DM or 10 US-$...\n   You only have to transfer the money to me...\n\n   Account Name    : Olaf Gramkow\n   Account Number  : 10141901\n   Bank Code Number: 24050110\n   Sparkasse Lüneburg\n\n   Use: - Registration rEAL-CALLERs\n        - Name/Handle, Group, BBS-Name, State\n        - get the reg. Version from which BBS (fLYING dRAGON, tHE dUNGEON)\n\n   Example for Use:\n      hIGH-SPEEd, rEAL, tHE dUNGEON, Germany\n      get it from tHE dUNGEON\n\n   After you sent me the money, you can get your REGISTERED VERSION\n   in one of the following BBSs:\n      fLYING dRAGON - rEAL wHQ\n      tHE dUNGEON   - rEAL gHQ\n   Please tell me which one...\n\n   but don''t forget... for the registration I need the following stuff:\n     Name/Handle, Group, BBS-Name, State\n\n   If you want to sent me the money by letter, then write a mail to\n   hIGH-SPEEd in tHE dUNGEON BBS or in the fLYING dRAGON BBS.\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\nrEQUIREMENTs\n\n                            Everyone can run it!!!\n\n          - you only need an AMIGA or compatible (DRACO)\n          - and the great AmiExpress V4.x\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\niNSTALLATIOn\n\n                      The installation is very simple...\n\n   - copy the directory rEAL with all the files to DOORS:\n   - now you have to add a line to all your LogOff.script Files.\n     Example for Node 1: DOORS:rEAL/rEAL-CALLERs/rEAL-CALLERs 1\n     Number at the end is the NodeNumber.\n   - now you can configurate the Config-File of rEAL-CALLERs\n     (DOORS:rEAL/rEAL-CALLERs/rEAL-CALLERs.config)\n\n   ready...\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\nwORKINg\n\n   This is a last caller door. It creats a file with the last callers of\n   your box. The filename is: dOORS:rEAL/rEAL-CALLERs/Data/LastCalls.txt\n   You can display this file on logon in the bulletins or anywhere else.\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\ncONFIGURATIOn\n\n   You can completly configurate this Door. Look in the rEAL-CALLERs.config\n   File in the directory DOORS:rEAL/rEAL-CALLERs/\n\n   Now an example of the Config-File:\n      STARTTEXT=DOORS:rEAL/rEAL-CALLERs/StartText.txt\n      ENDTEXT=DOORS:rEAL/rEAL-CALLERs/EndText.txt\n      STRING=[33m%&Node[31m%&NewUser[32m%&Name|15| [35m%&Location|19| [36m%&Baud [33m%&OnTime [34m%&Actions|HCPSUDud| [33m%&Online [37m%&UpKB|5| %&DnKB|5|\n      NUSERS=10\n      NODENOT=0\n\n   STARTTEXT:\n      Text in front of the entries.\n\n   ENDTEXT:\n      Text behind the entries. In the moment you can use the following\n      variables (70) in the text:\n\n      %&UserCalls = Calls of last Caller\n\n      %&CallsTotal = Total Calls of the system\n\n      %&UserUploads = Uploads of last Caller (completly)\n\n      %&UserDownloads = Downloads of last Caller (completly)\n\n      %&UploadsTotal = Uploads to the system\n\n      %&DownloadsTotal = Downloads from the system\n\n      %&CallerDay = Caller today\n\n      %&CallerMonth = Caller in this month\n\n      %&CallerYear = Caller in this year\n\n      %&UploadsDay = Uploads today\n\n      %&UploadsMonth = Uploads in this month\n\n      %&UploadsYear = Uploads in this year\n\n      %&DownloadsDay = Downloads today\n\n      %&DownloadsMonth = Donwloads in this month\n\n      %&DownloadsYear = Downloads in this year\n\n      %&UploadsCall = Uploads of last caller\n\n      %&DownloadsCall = Downloads of last caller\n\n      %&UploadedKByteCall = Uploaded KByte of last caller\n\n      %&DownloadedKByteCall = Downloaded KByte of last caller\n\n      %&UploadedKByteDay = Uploaded KByte today\n\n      %&UploadedKByteMonth = Uploaded KByte in this month\n\n      %&UploadedKByteYear = Uploaded KByte in this year\n\n      %&DownloadedKByteDay = Downloaded KByte today\n\n      %&DownloadedKByteMonth = Downloaded KByte in this month\n\n      %&DownloadedKByteYear = Downloaded KByte in this year\n\n      %&HackedDay = Hacks today\n\n      %&HackedMonth = Hacks in this month\n\n      %&HackedYear = Hacks in this year\n\n      %&SysopPagedDay = Sysop paged today\n\n      %&SysopPagedMonth = Sysop paged in this month\n\n      %&SysopPagedYear = Sysop paged in this year\n\n      %&NewUserDay = NewUser today\n\n      %&NewUserMonth = NewUser in this month\n\n      %&NewUserYear = NewUser in this year\n\n      %&CallerYesterday = Caller yesterday\n\n      %&CallerLastMonth = Caller last month\n\n      %&CallerLastYear = Caller last year\n\n      %&UploadsYesterday = Uploads yesterday\n\n      %&UploadsLastMonth = Uploads last month\n\n      %&UploadsLastYear = Uploads last year\n\n      %&DownloadsYesterday = Downloads yesterday\n\n      %&DownloadsLastMonth = Downloads last month\n\n      %&DownloadsLastYear = Downloads last year\n\n      %&UploadedKByteYesterday = Uploaded KByte yesterday\n\n      %&UploadedKByteLastMonth = Uploaded KByte last month\n\n      %&UploadedKByteLastYear = Uploaded KByte last year\n\n      %&DownloadedKByteYesterday = Downloaded KByte yesterday\n\n      %&DownloadedKByteLastMonth = Downloaded KByte last month\n\n      %&DownloadedKByteLastYear = Downloaded KByte last year\n\n      %&HackedYesterday = Hacks yesterday\n\n      %&HackedLastMonth = Hacks last month\n\n      %&HackedLastYear = Hacks last year\n\n      %&SysopPagedYesterday = Sysop paged yesterday\n\n      %&SysopPagedLastMonth = Sysop paged last month\n\n      %&SysopPagedLastYear = Sysop paged last year\n\n      %&NewUserYesterday = NewUser yesterday\n\n      %&NewUserLastMonth = NewUser last month\n\n      %&NewUserLastYear = NewUser last year\n\n      %&RegName = Name of registered User\n\n      %&RegGroup = Group-Name of registered User\n\n      %&RegBBS = Name of Mailbox of registered User\n\n      %&RegState = Land of registered User\n\n      %&TopCaller = Maximum Calls on day\n\n      %&TopUploads = Maximum Uploads on day\n\n      %&TopDownloads = Maximum Downloads on day\n\n      %&TopUploadedKByte = Maximum Uploaded KByte on day\n\n      %&TopDownloadedKByte = Maximum Downloaded KByte on day\n\n      %&TopHacked = Maximum Hacks on day\n\n      %&TopSysopPaged = Maximum SysopPages on day\n\n      %&TopNewUser = Maximum NewUser on day\n\n   STRING:\n      Which Outfit have the Strings?\n      You can also use all variables of the ENDTEXT.\n      In the moment you can use the following variables (9):\n\n      %&Node = Node (2 Chars)\n\n      %&NewUser = * if NewUser\n\n      %&Name = Name   /   %&Name|15| = the Name, but max. 15 Chars\n\n      %&Location = Location   /   %&Location|19| = the Location,\n                                                   but max. 19 Chars\n\n      %&Baud = Baudrate (5 Chars)\n\n      %&OnTime = Loginzeit (8 Chars) (Format= HH:MM:SS)\n\n      %&OffTime = Logoffzeit (8 Chars) (Format= HH:MM:SS)\n\n      %&Actions = different Flags for what the User have done\n                  die Flags, which should be displayed, must be set in || Chars.\n                  for Example %&Actions|HCPSUDud|\n                  The Flags have the following meanings:\n                  H = HACKED\n                  C = CARRIER LOST\n                  P = SYSOP PACKED\n                  S = DIRECTORY SCANED\n                  U = UPLOAD\n                  D = DOWNLOAD\n                  u = UPLOAD FAILED\n                  d = DOWNLOAD FAILED\n                  F = TRANSFER FAILED\n                  N = NEW USER\n\n      %&Online = how long online? (5 Chars) (Format = HH:MM)\n\n   NUSERS:\n      How many entries in the last caller text (only 5 in the demoversion)?\n\n   NODENOT:\n      Don''t take this NodeNumber for LastCaller-Text.\n\n   You can limit the number of displayed chars on the following variables... if nothing is selected then\n   8 Chars will be displayed...\n   %&UserCalls, %&CallsTotal, %&UserUploads, %&UserDownloads, %&UploadsTotal, %&DownloadsTotal, %&CallerDay,\n   %&CallerMonth, %&CallerYear, %&UploadsDay, %&UploadsMonth, %&UploadsYear, %&DownloadsDay, %&DownloadsMonth,\n   %&DownloadsYear, %&UploadsCall, %&DownloadsCall, %&UploadedKByteCall, %&DownloadedKByteCall, %&UploadedKByteDay,\n   %&UploadedKByteMonth, %&UploadedKByteYear, %&DownloadedKByteDay, %&DownloadedKByteMonth, %&DownloadedKByteYear,\n   %&HackedDay, %&HackedMonth, %&HackedYear, %&SysopPagedDay, %&SysopPagedMonth, %&SysopPagedYear, %&NewUserDay,\n   %&NewUserMonth, %&NewUserYear, %&CallerYesterday, %&CallerLastMonth, %&CallerLastYear, %&UploadsYesterday,\n   %&UploadsLastMonth, %&UploadsLastYear, %&DownloadsYesterday, %&DownloadsLastMonth, %&DownloadsLastYear,\n   %&UploadedKByteYesterday, %&UploadedKByteLastMonth, %&UploadedKByteLastYear, %&DownloadedKByteYesterday,\n   %&DownloadedKByteLastMonth, %&DownloadedKByteLastYear, %&HackedYesterday, %&HackedLastMonth, %&HackedLastYear,\n   %&SysopPagedYesterday, %&SysopPagedLastMonth, %&SysopPagedLastYear, %&NewUserYesterday, %&NewUserLastMonth,\n   %&NewUserLastYear, %&TopCaller, %&TopUploads, %&TopDownloads, %&TopUploadedKByte, %&TopDownloadedKByte,\n   %&TopHacked, %&TopSysopPaged, %&TopNewUser\n\n   some Examples:\n   %&UserCalls|5| = max. 5 Chars will be displayed\n   %&UserCalls|2| = max. 2 Chars will be displayed\n   %&UserCalls    = max. 8 Chars will be displayed\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\ngREETINGs!\n\n                           ... GReeTz fLYIng To ...\n\n      spEZIaL greETz fROM hIGH-SPEEd 2:\n\n      InTENsiTy , DoC waTSoN , GoroNIt , REvOlVer\n      anD tO aLl PhANTasM MeMBerS...\n\n      spEZIaL greETz fROM [-sAxOn-] 2:\n\n      SIRiAX,aLPHA ONe,pYRO,sLIME!,mARIO,vAMPIRE,JOHN SINCLAIR,\n      gALAXY,HITPOINT,KRYPTON,2FAST,DECCA,SIRE,CHAOS,PET,SABINE,\n      cANNIBAL,sTARLIGHT,H2o,mAGGY,sPIRIT,aNETTE,aNDREA,SPEEDY,\n      fRANK,jAYWALKER,pICARD,BASTARd^aPOLLO,5r,Awson,dEETs,gONZO,\n      BEN.E,aZURE!,trON,cRAsh,Gandalf,CRisi,SLaxx,pedl ^ dello,\n\n      and of coz 2:\n\n                       sPIRIT and tHE aLIEN\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\nmEMBERs, iNFOs, bOARDs\n\nmEMBAS:\n        [-sAxOn-]   mAIN-oRGA , WHq , cODER , dZ\n        hIGH-SPEEd  mAIN-cODER , oRGA , GHq , dZ\n        Picard      EHq , AREXX-CODEr?\n        HawKwind    Dz\n        bASHGUARD   Dz\n\nbOARDS:\n        [-sAxOn-]   fLYING DRAGOn   - rEAL WHq - gERMANY\n        pICARD      pARADISE LOST   - rEAL EHq - gERMANY\n        hIGH-SPEEd  tHE dUNGEON     - rEAL Ghq - gERMANY\n        sTARLIGHT   tRADERS ASSAULt - rEAL diS - gERMANY\n\nbETA TESTER:\n        jOHN sINCLAIR dRIVE bY SHOOTING - rEAL bETA tESTER - gERMANY\n        cANNIBAL      eXTREME TERROR    - rEAL bETA tESTER - gERMANY\n\ntRADER:\n        rKR       [ dRAGON-TEAm ] nO rEAL mEMBER ....bOARD tEAM\n        dEVIL     [ dRAGON-TEAm ] nO rEAL mEMBER ....bOARD tEAM\n        TyROX     [ dRAGON-TEAm ] nO rEAL mEMBER ....bOARD tEAM\n        cALAVERA! [ dRAGON-TEAm ] nO rEAL mEMBER ....bOARD tEAM\n\n                  ..... rIGHT rEAL hAS nO rEAL tRADER ......\n                     \----------------------------------/\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\nrELEASEd\n\n   sYS-DOWn V1.2       nOW aVAILABLE...\n   bAUD-cOUNTER V1.1   nOW aVAILABLE...\n   sEC-CHECk V1.3      nOW aVAILABLE...\n   rEAL-sTAT V1.1      nOW aVAILABLE...\n   cONF-MOVEr V1.1     nOW aVAILABLE...\n   rEAL-CALLERs V1.1   nOW aVAILABLE...\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\ncOMMING SOOn\n\n   rEAL-pAGE V1.0      bETA tEST rUNNING (tHE dUNGEON)\n   rEAL-RECORDs V1.0   bETA tEST sOON\n   rEAL-WHO V1.0       bETA tEST rUNNING (tHE dUNGEON)\n   sTATUS dOOR V1.5    bETA tEST rUNNING (fLYING dRAGON)\n   fRONTWHO V1.7       bETA tEST rUNNING (fLYING dRAGON)\n   lOGOFF DOOR V1.0    bETA tEST sOON\n   gAME-MANAGEr V1.0   bETA tEST sOON\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\n                              ... cALL NOw ...\n     .                                                                :\n  - -+-----------------------[ ThE dUNgEon bBs ]----------------------+-- -\n     |            _______________.                                    |\n     ¦           /               |        ________________            |\n     |          /_______\      __|___.    \    ______    /            ¡\n     |   _ _ ____.       \____/      |_____\___\________/_            |\n     |   ////____|           /       _        /__________/            |\n     !     ______.          /________|       /_ _ ____________________| _ _\n     |    /      |                   |______/  \\\\___________________////\n_____|___/__     | _________. _____________         _________________ |\n\    ______/.____|_\        | \     ______/____.    \    _______    / |\n \__________|       \       |__\____\_.___     |_____\_____   _/   /__|_______.\n     |      |_______________|__       |________|______    /_______/__         |\n     |                |_______/       |b!d  \   \________/_ |_______/         |\n     |                       /________|      \____________/        /__________|\n     ¦                  _ _ __________.                               |\n     !                  ////__________|                               |\n     |                                                                |\n     |                  [ SysOP iZ HigH-SpEEd/rEaL ]                  |\n     |           [ CoSys iZ jACk-daNiEl/iLLuSion deSIgNEr ]           |\n     |           [ NuP iZ -sLimE- aNd sYsPW iZ -pARaDIse- ]           |\n     |                      [ 1.1 gIgZ ONlINe ]                       |\n     |          