INSERT INTO door_catalog VALUES('rea_sc12','REA-SC12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/REA-SC12.LHA','sEC-CHECk','XIM','exe.-l0S-eND0S-bBS-.exe',NULL,'hIGH-SPEEd','REA','_ __:___  _ ______ __ _______ _ __:_ ___  /__    ___/__  ____   \   ___\__ __ \_      \   __\   \ \__     \  \',replace('      ...........[ REal ]............\n  _ __:___  _ ______ __ _______ _ __:_\n    ___  /__    ___/__  ____   \   ___\__ __\n    \_      \   __\   \ \__     \  \\n _ ___\      \__\      \__\      \ __\n    b!d\______\  \______\  \______\: \__ _ _\n      :     -[ /X dIvisIOn ]-      :\n      ·                            .\n      .     ... bRINGz yA ...\n             sEC-CHECk V 1.2\n       - dONE mADE bY hIGH-SPEEd -\n','\n',char(10)),'sEC-CHECk.doc',replace('                 .:::::.  .::::.      ..:::::.     ..:::::.\n               .::::::::.:::::::.   .:::··:::::   ::·:::::·\n             .:::::::::::::::::::  .:::·   ::::    .::::·\n         .:::::· :::::::·   :::::: ·::·    ::::   .:::·\n         :::::  ::::::::    ::::::    .... ::::  .:::·\n          :::.  :::::::;   ::::::; .::::::::::: .:::·          ...\n           :::. ·::::::...::::::· .::::··:::::: :::·          ::::.\n           ·:::. ··::::::::::··   ::::    ::::::::·            ::::\n            ·:::.  :::·        ..:::::    :::::::::.......:::::::::\n             ::::; :::    ...::::::::::..::::::::::::::::·····::::;\n              ···  ·::::::::::::· ·::::::::::·····b!d\n                    ·::::····\n\n                              ... bRINGz yA ...\n\n                               sEC-CHECk V 1.2\n\n                         - dONE mADE bY hIGH-SPEEd -\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\niNTRODUCTIOn\n\n                   ... here is the sEC-CHECk from rEAL ...\n\n  Features:\n\n          - check if Sysoplevel or higher and lower access\n          - select the Sysop- and the Originallevel\n          - don''t check spezial user\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\nrEGISTRATIOn\n\n   This tool is SHAREWARE, so if you use it, you have to register...\n   The registration cost you only 10,- DM or 10 US-$...\n   You only have to transfer the money to me...\n\n   Account Name    : Olaf Gramkow\n   Account Number  : 10141901\n   Bank Code Number: 24050110\n   Sparkasse Lüneburg\n\n   Use: - Registration sEC-CHECk\n        - Name/Handle, Group, BBS-Name, State\n        - get the reg. Version from which BBS (fLYING dRAGON, tHE dUNGEON)\n\n   Example for Use:\n      hIGH-SPEEd, rEAL, tHE dUNGEON, Germany\n      get it from tHE dUNGEON\n\n   After you sent me the money, you can get your REGISTRATED VERSION\n   in one of the following BBSs:\n      fLYING dRAGON - rEAL wHQ\n      tHE dUNGEON   - rEAL gHQ\n   Please tell me which one...\n\n   but don''t forget... for the registration I need the following stuff:\n     Name/Handle, Group, BBS-Name, State\n\n   If you want to sent me the money by letter, then write a mail to\n   hIGH-SPEEd in tHE dUNGEON BBS or in the fLYING dRAGON BBS...\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\nrEQUIREMENTs\n\n                            Everyone can run it!!!\n\n          - you only need an AMIGA or compatible (DRACO)\n          - and the great AmiExpress V4.x\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\niNSTALLATIOn\n\n                      The installation is very simple...\n\n   - copy the directory rEAL with all the files to DOORS:\n   - copy the directory COMMANDS with all the files to BBS:\n   - include the following line in the BULL.txt:\n       ~CC_sEC-CHECk \n\n   ready...\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\nwORKINg\n\n   This Door only looks at every logon of a user if he have Sysopstatus!!!\n   If this User is not listed in the sEC-CHECk.info Icon in the directory\n   BBS:COMMANDS/SYSCMD the Door will set the accesslevel of the user to\n   the Originallevel.\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\ncONFIGURATIOn\n\n  You can configurate the Door. You have to change some Tooltypes in the\n  sEC-CHECk.info Icon in the BBS:COMMANDS/SYSCMD directory.\n\n  Tooltypes:\n     SC_SYSOPLEVEL\n     SC_ORIGINALLEVEL\n     SC_USER\n\n  SC_SYSOPLEVEL:\n     Pattern : SC_SYSOPLEVEL=<num>\n     Function: Select the Sysoplevel. If the accesslevel is this level or\n               is higher than this level than the accesslevel will be\n               lowered to the Originallevel.\n     Example : SC_SYSOPLEVEL=250\n               Check for a level about 250 or higher.\n\n  SC_ORIGINALLEVEL:\n     Pattern : SC_ORIGINALLEVEL=<num>\n     Function: This is the Originallevel to which the account is set, if a\n               Sysoplevel was detected.\n     Example : SY_ORIGINALLEVEL=10\n               Set Accesslevel to 10 (NEW USER).\n\n  SC_USER:\n     Pattern : SC_USER.<num>=<name>\n     Function: Here you can select which Users will not be checked. After\n               the text "SC_USER." comes a number beginning with 1.\n     Example : SC_USER.1=hIGH-SPEEd\n               Don''t check the User hIGH-SPPEd.\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\ngREETINGs!\n\n                           ... GReeTz fLYIng To ...\n\n      spEZIaL greETz fROM hIGH-SPEEd 2:\n\n      InTENsiTy , DoC waTSoN , GoroNIt , REvOlVer\n      anD tO aLl PhANTasM MeMBerS...\n\n      spEZIaL greETz fROM [-sAxOn-] 2:\n\n      SIRiAX,aLPHA ONe,pYRO,sLIME!,mARIO,vAMPIRE,JOHN SINCLAIR,\n      gALAXY,HITPOINT,KRYPTON,2FAST,DECCA,SIRE,CHAOS,PET,SABINE,\n      cANNIBAL,sTARLIGHT,H2o,mAGGY,sPIRIT,aNETTE,aNDREA,SPEEDY,\n      fRANK,jAYWALKER,pICARD,BASTARd^aPOLLO,5r,Awson,dEETs,gONZO,\n      BEN.E,aZURE!,trON,cRAsh,Gandalf,CRisi,SLaxx,pedl ^ dello,\n\n      and of coz 2:\n\n                       sPIRIT and tHE aLIEN\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\nmEMBERs, iNFOs, bOARDs\n\nmEMBAS:\n        [-sAxOn-]   mAIN-oRGA , WHq , cODER , dZ\n        hIGH-SPEEd  mAIN-cODER , oRGA , GHq , dZ\n        Picard      EHq , AREXX-CODEr?\n        cANNIBAL    dZ , Ghq , aREXX-cODER\n        HawKwind    Dz\n        bASHGUARD   Dz\n\nbOARDS:\n        [-sAxOn-]   fLYING DRAGOn  - rEAL WHq - gERMANY\n        pICARD      pARADISE LOST  - rEAL EHq - gERMANY\n        hIGH-SPEEd  tHE dUNGEON    - rEAL Ghq - gERMANY\n        cANNIBAL    eXTREME TERROR - rEAL Ghq - gERMANY\n        sTARLIGHT   aNOTHER WORLd  - rEAL diS - gERMANY\n\nbETA TESTER:\n\n        jOHN sINCLAIR dRIVE bY SHOOTING - rEAL bETA tESTER - gERMANY\n\ntRADER:\n        rKR       [ dRAGON-TEAm ] nO rEAL mEMBER ....dRAGON tEAM\n        dEVIL     [ dRAGON-TEAm ] nO rEAL mEMBER ....dRAGON tEAM\n        TyROX     [ dRAGON-TEAm ] nO rEAL mEMBER ....dRAGON tEAM\n        cALAVERA! [ dRAGON-TEAm ] nO rEAL mEMBER ....dRAGON tEAM\n\n                  ..... rIGHT rEAL hAS nO rEAL tRADER ......\n                     \----------------------------------/\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\nrELEASEd\n\n   sYS-DOWn V1.0       nOW aVAILABLE...\n   bAUD-cOUNTER V1.0   nOW aVAILABLE...\n   sEC-CHECk V1.2      nOW aVAILABLE...\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\ncOMMING SOOn\n\n   bAUD-cOUNTER V1.1   bETA tEST rUNNING (tHE dUNGEON)\n   sYS-DOWn V1.1       bETA tEST rUNNING (tHE dUNGEON, fLYING dRAGON,\n                                          dRIVE bY sHOOTING)\n   rEAL-CALLERs V1.0   bETA tEST rUNNING (tHE dUNGEON, fLYING dRAGON,\n                                          dRIVE bY sHOOTING)\n   cONF-MOVEr V1.0     bETA tEST rUNNING (tHE dUNGEON, fLYING dRAGON)\n   rEAL-pAGE V1.0      bETA tEST rUNNING (tHE dUNGEON)\n   rEAL-RECORDs V1.0   bETA tEST sOON\n   rEAL-WHO V1.0       bETA tEST rUNNING (tHE dUNGEON)\n   sTATUS dOOR V1.5    bETA tEST rUN