INSERT INTO door_catalog VALUES('rea_st2','REA-ST2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/REA-ST2.LHA',NULL,'XIM','rEAL-sTATUs00.exe',NULL,'JiM_bEAM','REA','_________/\  _ __ ____ _ ____/\ ___. REAL! \___.___  \\      ___/    .___\\   |______ |  /  _/___ ___)_____ ___/  \  l      \',replace('\n_________/\  _ __ ____ _ ____/\ ___. REAL!\n\___.___  \\      ___/    .___\\   |______\n    |  /  _/___ ___)_____ ___/  \  l      \\n yopl__\       \______  /_|      \______ //\n =======\_______\=====\/==l_______\=====\/=\n |                                        |\n |          * rEAL-sTATUs v2.0 *          |\n |  "S" cOMMANd rEPLACEMENt bY JiM_bEAM   |\n |                                        |\n `--[1/1]-----[ /X dOOR ]-----[05/30/98]--´\n','\n',char(10)),'rEAL-sTATUs.guide',replace('@DATABASE "rEAL-Status.guide"\n@NODE "Main" "rEAL-sTATUS V 1.0 bY JiM_bEAM / rEAL!"\n@TOC "MAIN"\n@{b}                _________/\\  _ __ _____ _ ____/\\ ___.@{ub}\n@{b}                \\___.___   \\\       ___/    .___ \\   |______@{ub}\n@{b}                    |  /  _/___  ___)_____ ___/  \\  l      \\@{ub}\n@{b}                     __\\       \\ ______  /_|      \\______ //@{ub}\n@{b}           <------ -----\\_______\\-- - -\\/--l_______\\yop -\\/- -- ->@{ub}\n\n@{b}          ... bRINGz yA ...@{ub}                    @{" iNTRODUCTIOn! " LINK "Introduction_Node"}\n@{b}                                       @{" rEQUIREMENTs! " LINK "Requirements_Node"}@{"tOOLz rELEASEd!" LINK "Tools_released_Node"}\n@{b}          rEAL-sTATUS V2.0!@{ub}            @{" iNSTALLATIOn! " LINK "Installation_Node"}@{" E-mAILWARe ?? " LINK "emailware_Node"}\n@{b}      tHE sTATUS /X dOOR bY rEAL@{ub}       @{" cONFIGURATIOn " LINK "Configuration_Node"}@{"   gREETINGs   " LINK "Greetings_Node"}\n@{b}                                       @{"    wORKINg    " LINK "Working_Node"}@{"    cONTACt    " LINK "Contact_Node"}\n@{b}      - cODED bY JiM_bEAM/rEAL -@{ub}       @{" dESIGn eXPLANATIOn! " LINK "DesignExplanation_Node"}@{"  rEAL!  " LINK "Real_Node"}\n@{b}    - dESIGN bY Trivial^JiM_bEAM -@{ub}            @{" e-mAILs aND iRC " LINK "E_Mails_and_IRC_Node"}\n\n\n@{b}     NOTE: THIS MIGHT BE MY LAST RELEASE UNDER THE "rEAL"-GROUPLABEL\n              BECAUSE THE GROUP "rEAL" IS OFFICIALLY DEAD NOW !!! @{ub}\n\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n                         this tool is E-MAILWARE\n                    copyright © 1998  JiM_bEAM / rEAL!\n-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-===-\n\n\n@ENDNODE\n\n@NODE "Introduction_Node" "Introduction"\n@TOC "MAIN"\n@{b}iNTRODUCTIOn@{ub}\n@{b}~~~~~~~~~~~~@{ub}\n\n           ... here is the rEAL-sTATUS Door by JiM_bEAM / rEAL ...\n\n\n  Features:\n\n          - Download Option: the user can download his Status-Info\n          - TWO different Status-Infos in ONE door:\n            BBS-Status and User-Status\n          - all code written in pure C language\n          - 68000, 68020+ versions\n          - Because of @{b}NO BACKDOOR@{ub} NO RISK\n            Disassemble the code if ya don''t believe me !!!\n\n          To see all features just install the door and enter "S"\n          in the mainprompt of /X\n\n\n  NEW Features in V2.0:\n\n          - completly reorganised\n          - added a main menu\n          - 3 different Status-Infos in ONE door:\n            Complete Status (BBS + User; long output)\n            BBS Status\n            User Status\n          - view option for every status info\n          - download option for every status info\n          - Quit option\n          - all code written in pure C language\n          - 68000, 68020+ versions\n          - Because of @{b}NO BACKDOOR@{ub} NO RISK\n            Disassemble the code if ya don''t believe me !!!\n\n          To see all features just install the door and enter "S"\n          in the mainprompt of /X\n\n\n@ENDNODE\n\n@NODE "Requirements_Node" "Requirements"\n@TOC "MAIN"\n@{b}rEQUIREMENTs@{ub}\n@{b}~~~~~~~~~~~~@{ub}\n\n                            Everyone can run it!!!\n\n          - you only need an AMIGA\n          - KS2.04 or higher\n          - the great AmiExpress V4.x\n          - the AEDoor.library V2.4+ in Libs:\n          - and rEALdOOR.library in Libs: (included in this archive)\n          - a assinged T: directory where "Status.log", "BBSStatus.log",\n            "USERStatus.log"-File will be stored for downloading\n\n\n@ENDNODE\n\n@NODE "Installation_Node" "Installation"\n@TOC "MAIN"\n@{b}iNSTALLATIOn@{ub}\n@{b}~~~~~~~~~~~~@{ub}\n\n                      The installation is very simple...\n\n   - copy the rEALdOOR.library to Libs:\n   - copy the directory rEAL with all the files to DOORS:\n   - copy the directory COMMANDS with all the files to BBS:\n\n   ready...\n\n\n@ENDNODE\n\n@NODE "Working_Node" "Working"\n@TOC "MAIN"\n@{b}wORKINg@{ub}\n@{b}~~~~~~~@{ub}\n\n   This Door is a replacement for the internal "S"-Command\n   in AmiExpress.\n   It shows the user info about his Status and about the\n   Status of the BBS.\n   There is a download option for the user so that he can\n   download the Status-Info if he need it.\n\n\n@ENDNODE\n\n@NODE "Configuration_Node" "Configuration"\n@TOC "MAIN"\n@{b}cONFIGURATIOn@{ub}\n@{b}~~~~~~~~~~~~~@{ub}\n\n  You can configure the door. My door uses the standard /X-Tooltype-Configuration !\n\n  S.info ICON:\n\n  Tooltypes:\n     ACCESS\n     TYPE\n     LOCATION\n     STACK\n     NAME\n     MULTINODE\n     BBSNAME\n     BBSLOCATION\n     HDCOUNT\n     HDTYPE\n     HDSTORE\n     NODES\n\n\n  ACCESS:\n     Pattern : ACCESS= <num>\n     Function: Tells /X the access level required to run this module.\n               This option is ignored for internal Module options.\n     Example : ACCESS=10\n               Check for a level about 10 or higher.\n\n  TYPE:\n     Pattern : TYPE= < XIM | AIM | TIM | IIM | SIM | MCI >\n     Function: This is the type of door you use.\n     Example : TYPE=XIM\n               For my door the TYPE should be XIM !!!\n\n  LOCATION:\n     Pattern : LOCATION= <string>\n     Function: Specifies the location of the module\n     Example1: LOCATION=DOORS:rEAL/rEAL-sTATUS/rEAL-sTATUS00.exe\n               If you are using the version for 68000 CPUs !\n\n     Example2: LOCATION=DOORS:rEAL/rEAL-sTATUS/rEAL-sTATUS020.exe\n               If you are using the version for 68020 CPUs !\n\n     Example3: LOCATION=DOORS:rEAL/rEAL-sTATUS/rEAL-sTATUS030.exe\n               If you are using the version for 68030 CPUs !\n\n     Example4: LOCATION=DOORS:rEAL/rEAL-sTATUS/rEAL-sTATUS0x0.exe\n               If you are using the version for 68040/60 CPUs !\n\n  STACK:\n     Pattern : STACK= <Value>\n     Function: Specifies the Stack-value for the door and should be\n               set to 10000 !\n     Example : STACK = 10000\n               Sets stack to 10000\n\n  NAME:\n     Pattern : NAME= <Doorname>\n     Function: Specifies the name to display in the /X-Server window\n     Example : NAME = rEAL-sTATUS\n\n  MULTINODE:\n     Pattern : MULTINODE= <YES|NO>\n     Function: Tells /X if the module may be simultaneously accessed\n               from other nodes.\n\n  BBSNAME:\n     Pattern : BBSNAME= <Textstring>\n     Function: Here you must enter the name of your BBS which should\n               be displayed in the Status-Output\n     Example : BBSNAME=tHE dUNGEON\n\n  BBSLOCATION:\n     Pattern : BBSLOCATION= <Textstring>\n     Function: Here you must enter the location of your BBS which should\n               be displayed in the Status-Output\n     Example : BBSLOCATION=USA\n\n  HDCOUNT:\n     Pattern : HDCOUNT= <Number>\n     Function: Here you must enter the number of Harddiskdrives you use for\n               your BBS and should be displayed in the Status-Output\n     Example : HDCOUNT=2\n               You use 2 Harddiskdrives for your BBS\n\n  HDTYPE:\n     Pattern : HDTYPE= <Textstring>\n     Function: Here you must enter what type of Harddiskdrive(s) you use\n               for your BBS and should be displayed in the Status-Output\n     Example1: HDTYPE=AT-BUS\n               You use AT-BUS Harddiskdrive(s)\n     Example2: HDTYPE=SCSI\n               You use SCSI Harddiskdrive(s)\n     Example3: HDTYPE=AT-BUS / SCSI\n               You use AT-BUS and SCSI Harddiskdrives\n\n  HDSTORE:\n     Pattern : HDSTORE= <Path and filename to uploads-storage>\n     Function: Here you must enter the complete path to your\n               BBS-Harddiskdrives where uploads are stored\n               !! IT''S IMPORTANT FOR DISPLAYING THE "Free HD Space" !!\n     Example1: HDSTORE=BBS:\n               All uploads are stored in "BBS:"\n     Example2: HDSTORE=BBS:Uploads/\n               All uploads are stored in "BBS:Uploads"\n               !! DON''T FORGET THE "/" IF THE PATH IS A DIRECTORY !!\n\n  NODES:\n     Pattern : NODES= <Number>\n     Function: The number of total nodes your BBS supports\n     Example : NODES=5\n               Your BBS supports 5 Nodes (0,1,2,3,4)\n\n\n@ENDNODE\n\n@NODE "Greetings_Node" "Greetings"\n@TOC "MAIN"\n@{b}gREETINGs!@{ub}\n@{b}~~~~~~~~~~@{ub}\n\n                           ... GReeTz fLYIng To ...\n\n\n      greETz fROM JiM_bEAM 2:\n\n      eXON, dIGIMAN, sHALLOW , cHUCK, TMN , hAMLET, lUCAS, lANCE,\n      sHADOW, zOD, dR.dRE, cOKE, wOober, pETRIEfIEd...\n      anD tO aLl mY cONTACTs oN #amielite anD dA rEST oF tHE cOOL sCENE...\n\n\n\n      sPECIAL gREETZ fROM JiM_bEAM :\n      ------------------------------\n\n      hIGH-SPEEd    nICHTs aLS dEN sERVEr iM kOPF wA ;)\n\n      jOULE         i''m sTILL w8ING fOR tHE rESt oF tHe aNSIs\n\n      iRON          nUR nOCH dEN rEAL-sERVER uND uNIx iM kOPf wA ;)\n                    "aMIGa iST tOD" ;)\n\n      jUDGE rAPID   wAR nEN eCHT cOOLEs gESPRÄCH aUF dER "cOMPUTER ''97"\n                    cOMPUtER ''98 ??\n\n      sLAPSHOt      "SLT" iS dEAD oDDA wAS ?\n                    mAN sIEHt, hÖRt nICHTs mEHr vON dIR... lEFT tHE sCENe ?\n      \n      sUNBEAM   