INSERT INTO door_catalog VALUES('rex2ex','REX2EX.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/REX2EX.LHA','ExecRexx','XIM','ExecRexx',NULL,NULL,NULL,'¦\__   | __ \   |  | __ \   |  |   ___/¦ |ct/   |     \  l  |    (_  l  |\__   \| |e/ ___l__l__ \____l__l__/\____l  ____/|',replace(' :/\____.________.__.________.__._____/\:    \n ¦\__   | __ \   |  | __ \   |  |   ___/¦    \n |ct/   |     \  l  |    (_  l  |\__   \|    \n |e/ ___l__l__ \____l__l__/\____l  ____/|    \n-+-\_/--------\_/-PrEsEnTs------\_/-----''\n + Arexx To Executable Converter v1.12a +\n `--------------------------------------''\n','\n',char(10)),'ExecRexx.doc',replace('ExecRexx\n--------\n\n  ExecRexx is a program that turns an ARexx script into an executable program\nthat can be run from the CLI or WorkBench. This is handy if you don''t wish to\ndistribute the source code for the original script, or want to make an ARexx\nscript that is easily run by a WorkBench user clicking on an icon for the\nexecutable.\n  The resulting executable still requires the rexxsyslib.library (ie the\nARexx server by Bill Hawes) as well as the dissidents rexxapp.library (a PD\nlibrary that allows programs to easily add ARexx implementations) to be in\nthe LIBS: drawer of the user''s boot disk. The ARexx server should be started\nvia RexxMast (by Bill Hawes). If either of these libs is not present, the\nexecutable will post an appropriate message to the user.\n  The resulting executable is fully re-entrant and can be made resident for\nimproved speed. Otherwise, there is no speed difference between the executable\nand the original script. The added size to the executable is minimal due to\nthe dissidents rexxapp.library.\n  You should write (and test) the original ARexx script as you would normally.\nOnce you have created the original script, you invoke ExecRexx to turn it into\nan executable. From the CLI:\n\nExecRexx <scriptname>\n\n  This will produce an executable with ".exe" appended to the original script-\nname (as well as an icon for the new executable).\n  If you do not supply a scriptname, the dissidents'' file requester will appear\nfor you to choose the scriptname. (Note that this requires the dissidents\nrequester.library. Haven''t you used it yet?)\n  From WB, you can either start ExecRexx alone and use the file requester to\nselect the scriptname, or change the script''s icon TOOL to ExecRexx and select\nthat icon (ie use WB''s Info menu item).\n','\n',char(10)),NULL,'auto-added',13494,2,0,NULL,NULL,'rex2ex','scan',1780048686);
INSERT INTO door_catalog VALUES('rexxlib','REXXLIB.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/REXXLIB.LHA',NULL,'XIM','rexxarplib.library',NULL,NULL,NULL,NULL,replace('All rexx libs needed for Ami-Express\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-23-18  TIME: 12:01:52  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',90505,3,0,NULL,NULL,'rexxlib','scan',1780048686);
INSERT INTO door_catalog VALUES('rfx_dc10','RFX-DC10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RFX-DC10.LHA','DupeCheck','XIM','DupeCheck',NULL,'[r]FoX','RFX','|\  /|   |  ))   ))||   )/\  |\  | |\\/ |/\ |_//  _// ||__//_\\ |\\ | |    / \\|\\_  //__|| _/___\\| \\|',replace('#  .    .   .__ ____ .o____     .   .  #\n   |\  /|   |  ))   ))||   )/\  |\  |\n   |\\/ |/\ |_//  _// ||__//_\\ |\\ |\n   |    / \\|\\_  //__|| _/___\\| \\|\n   |  -/+++\\-\  //\ |_)|_   _/\n   |  /     \\/\//--\|\\|___ /-27-2-98-\n   `fX!- - - \/\/- - ` \|- - - - - - -\n    /   mARZIpAN_dOORs_dEVELOPEMENT\n   ------------oo----------oo----------\n                  rELEASEd\n   DUPECHECK V1.0 by [r]FoX for SystemX\n#        a stoned colorflash Hack      #\n','\n',char(10)),'DupeCheck.guide',replace('@database 67ac5e90-0\n@master HeddleyCreation\n@$VER: 1.0\n@remark Created with Heddley v1.1 (c) Edd Dumbill 1994\n\n@node "Main" "No title"\n\n\n                   @{b}@{u}Welcome to DupeCheck V1.0@{ub}@{uu}\n\n\n       @{"Introducing" link "intro" 0}  -*-  @{"Requirements" link "require" 0}  -*- @{"Installation" link "install" 0}\n\n                     @{"Contact" link "contact" 0}  -*-  @{"Greetz" link "greetz" 0}\n\n                               |\n   \n        DupeCheck 1.0 is a small`n sexy Dupchecker for\n         SystemX. It was done by [r]FoX dedicated to \n                       @{b}dIGITAL.^cORRUPTIOn@{ub}\n\n @{">" link "intro" 0}\n@endnode\n\n@node "intro" "intro"\n\n @{b}@{u}Introducing:@{ub}@{uu}\n\nDupeCheck is a XIM Door for SystemX only. It checks the uploaded File for\nalready existing Files in the BBS. This was a stoned one night hack at the\nbase of Zed`s FileCheck, coz the output was not so cewl. Hmm, the results are\nvery colored, i wondered by myself at the next mornin.. However, we`ll see...\n\n  [r]FoX\n\n @{"<" link "Main" 0}  @{">" link "require" 0}\n@endnode\n\n@node "require" "require"\n@next "Document_1"\n@prev "intro"\n\n\n @{b}@{u}Requirements:@{ub}@{uu}\n\nYou need an Amiga. You need SystemX installed, otherwise the Door wont run.\nYou need the File `FileCheck.DAT` ( see @{"Installation" link "install" 0} ).\n\n @{"<" link "intro" 0}  @{">" link "install" 0}\n@endnode\n\n@node "install" "install"\n\n\n @{b}@{u}Installation:@{ub}@{uu}\n\n - You must have the File `@{b}sx:confs/confname/FileCheck.DAT@{ub}`\n  in that Conferences, you like to run DupeCheck after\n  Upload.\n\n - Add the following Lines to FileCheck.DAT :\n\n\n  @{i} 1 \n   doors:dupecheck@{ui}        /* use any path you like */\n\n\n  For more Information about Filecheck Doors read the SystemX\n  Guide.\n  If the File `DupeCheck.DAT` does not exist, you may create\n  it with any texteditor.\n\n @{"<" link "require" 0}  @{">" link "contact" 0}\n@endnode\n\n@node "contact" "contact"\n\n\n @{b}@{u}Contact:@{ub}@{uu}\n\n Any suggestions or Design hints are welcome at\n\n @{b}[email removed]@{ub}\n\n or catch me at Pulsarnet #elitecafe ...\n\n [r]FoX\n\n @{"<" link "install" 0}  @{">" link "greetz" 0}\n@endnode\n\n@node "greetz" "greetz"\n\n\n @{b}@{u}Greetings:@{ub}@{uu}\n\n For all you outa there....\n\n zED * tHEmIXXER * gET_mERYY * zEUS\mSR * rAMoNSTEr \n sAL-oNE * lEATHERfACE * r19 * MAZ\DLM * tHALER^!x\n oBLIGATOR * pHANTOM \n\n and all loveley Dudez i forgott atm (too much BSE)\n\n @{"<" link "contact" 0}  @{">" link "Main" 0}\n@endnode\n\n','\n',char(10)),NULL,'auto-added',11788,4,0,NULL,NULL,'rfx_dc10','scan',1780048686);
INSERT INTO door_catalog VALUES('rfx_ml12','RFX-ML12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RFX-ML12.LHA','SX_MSG','XIM','SX_MSG',NULL,'[r]FoX','RFX','|\  /|   |  ))   ))||   )/\  |\  | |\\/ |/\ |_//  _// ||__//_\\ |\\ | |    / \\|\\_  //__|| _/___\\| \\|',replace('   .    .   .__ ____ .o____     .   .   \n   |\  /|   |  ))   ))||   )/\  |\  |\n   |\\/ |/\ |_//  _// ||__//_\\ |\\ |\n   |    / \\|\\_  //__|| _/___\\| \\|\n   |  -/+++\\-\  //\ |_)|_   _/\n   |  /     \\/\//--\|\\|___ /_5.jUn.98\n   `rFx! - - \/\/- - ` \\_\n   ------------oo----------oo----------\n   SX_MSG V1.2 by [r]FoX Full Release !                \n  .containing a new Update/Guide to the. \n  | MessageLister for SystemX BBSware  |\n  |   visit the WebSupport Site at     |\n  |   HTTP://AMICHURCH.HOME.ML.ORG     |\n  `------------------------------------''\n','\n',char(10)),'SX_MSG.guide',replace('@database 67acfcc0-0\n@master AmiX:SX/Developer/SX_MSG/doc/SX_MSG.guide\n@$VER: 1.0\n@remark Created with Heddley v1.1 (c) Edd Dumbill 1994\n\n@node "Main" "No title"\n\n    @{b}@{u}wELCOME tO SX_MSG 1.2 wRITTEn bY [r]FoX@{ub}@{uu} \n              \n             fOR sYSTEM\X bY zED\n          \n        @{b}dA dOCu                dA pICs@{ub}\n        -------                -------\n\n    @{b}@{"-[  iNTROdz  ]-" link "intro" 0}       @{"-[ mAINmENUpIC ]-" system "multiview ml-main.gif"}  \n    @{"-[  iNZTALL  ]-" link "install" 0}       @{"-[ hELPmENUpIC ]-" system "multiview ml-help.gif"}\n    @{"-[   uSAGE   ]-" link "usage" 0}       @{"-[ mAILsCANpIC ]-" system "multiview ml-ms0.gif"}\n    @{"-[  fEATURe  ]-" link "features" 0}       @{"-[ mAILiDEXpIC ]-" system "multiview ml-ms1.gif"}\n    @{"-[   pLANs   ]-" link "plans" 0}       @{"-[ nEWmAIL pIC ]-" system "multiview ml-ms_found.gif"} \n    @{"-[  cONTAcT  ]-" link "contact" 0}       @{"-[ iNFOpAGEpIC ]-" system "multiview ml-info.gif"} \n    @{"-[    S\X    ]-" link "sx" 0}       @{"-[ mSGtOPICpIC ]-" system "multiview ml-msg_list.gif"}\n    @{"-[  gREETZz  ]-" link "greetz" 0}       @{"-[ lISTbYnRpIC ]-" system "multiview ml-list_nr.gif"}\n\n    A Messages Indexer for the only usage \n          with the XIM-port of the \n      System-X Bulletin Board Software\n@endnode\n\n@node "intro" "intro"\n \n @{b}Welcome to the MessageLister !@{ub}\n ------------------------------\n\n SX_MSG V1.2 is an XIM-Door for the usage with the @{"SystemX" link "sx" 0} BBS software\n only and cannot be used under other BBS programms.\n The MessageLister is nice to use with upcoming Fido software or other\n Netwares for @{"SystemX" link "sx" 0}.\n\n This Door is a basic instrument, to give overview to the MsgBases.\n It shows the existing MsgBases in a conference, total Msgs,\n new ones and a lot more...\n\n\n @{"<" link "Main" 0}  @{">" link "install" 0}  @{"Main" link "Main" 0}\n@endnode\n\n@node "install" "install"\n\n @{b}Installation:@{ub}\n -------------\n\n The MessageLister gives you a powerfull handling for the MessageBases\n of SystemX. The Door is so advanced in its handling, that i use the\n other Message Commands  like `E` or `R` to it, too.\n You may give any Commandname you like. `ML` as Commandname runs fine\n here, inculding the fingerdynamics ;)\n\n Now do it :\n\n - Copy all archive contents to SX:Doors/ML/ or any Directory you like.\n\n - configure the Door call\n\n   + by @{"MCI-File" link "inst_MCI" 0}    \n   + as @{"XIM Door" link "inst_XIM" 0} \n   + as @{"MailScan" link "inst_MS" 0}   \n \n - Restart SystemX, so the new settings will be activated\n\n Thats all.\n Now Login and call the Door in your selected way.\n While startup the Door shows you an Index about the installed MessageBases\n in the current Conference and a CommandPrompt were you may enter yer \n actions.\n Check one of the scan-functions to see, if all Conferences/MessageBases\n are scanned for you. if not, so check your Conference Access.\n\n\n @{"<" link "intro" 0}  @{">" link "usage" 0}  @{"Main" link "Main" 0}\n@endnode\n\n@node "usage" "usage"\n \n @{b}How to use that shit ?@{ub}\n ----------------------\n\n After calling the MessageLister, first an ansi-header comes up \n (@{i}if the sysop @{ui}@{"calls the Door by MCI-File" link "inst_MCI" 0}) or the Door starts\n direcly with an overview of the installed MsgBases in the\n actual conference, you are.\n\n ex:                \n                  +- current Conference Name\n                  |             +- current Date/Time            Last Call\n                  |             |           |                      |\n                  |             |           |                      |\n MessageBases in New User    05-18-98 | 14:30:52 LastCall: 05-18-98 14:30:34\n ---------------------------------------------------------------------------\n (  1) - New Users Chat   [ 278/ 8] |---------------------------------------\n ---|-----|------------------|---|---\n    |     |                  |   |\n    |     |                  |   +- Number of New Msgs\n    |     |                  +- Number of total Msgs in this Base\n    |     +- Name of the MsgBase    \n    +- Number of the MsgBase in current Conference\n\n \n TitleBar Informations : - current Conference Name\n                         - current Date\n                         - current Time\n                         - Last Call Date/Time\n\n          MsgBase List : - Number of MsgBase\n                         - Name of MsgBase\n                         - Total Msgs in Base\n                         - Total New Msgs in Base\n\n After that a Commandprompt comes up and you are able to use the following\n commands:\n\n ex:\n\n @{b}MsgLister Commands: ?,CR,E,R,L,I,S,s,+,-,#,(@{i}New Users Chat@{ui}) :@{ub} \n\n The name of the current MsgBase, you browse in, is shown in the parentieses\n on the Commandprompt were you enter the Commands you like to do.\n The CommandPrompt also accepts digits for the selected  \n MsgBase you like to join. (see `I`-command) \n\n The commands are :\n \n @{b}?@{ub}   - View the Helpmenu\n       This shows a small menuansi, explaining, what the commands are\n       doing.\n\n @{b}??@{ub}  - View an additional Helppage, with more explaination to the commands.\n\n @{b}CR@{ub}  - Press Return and the MsgLister will quit. The Door will quit, if\n       you enter any unknown command.\n\n @{b}E@{ub}   - Enter a Msg\n       Here you join Enter Msg by SystemX. You have to put the Reciver\n       and the subject into a normal way. Just enter a Msgs ...\n\n @{b}R@{ub}   - Read a Msg <Argumment>\n       You may give an Digit Argument here for the Msg you like to read.\n       For that, you write the Msgnumber you wich, like `r 13` or `r32` \n\n @{b}L@{ub}   - List Msgs <Argument>\n       This will list all Msgs Headers in the current MsgBase.\n       If a Digit Argument is given to the `L` command, the Messages are\n       listed from the MsgNumber <Argument> to Listend. If no MsgNumber is\n       given, the list starts at Msg #1.\n\n       The List will inform you about\n                                      - Name of MsgBase\n                                      - total Msgs in MsgBase\n                                      - Msg number\n                                      - Date/Time of Msg edit\n                                      - Name of writer\n                                      - Name of receiver\n                                      - Replaymarker\n                                      - New Marker\n                                      - Msg Subject\n                                      - `PRIVATE MSG` Flag\n                                      - `DELETED` Flag\n\n @{b}I@{ub}   - Index of MsgBases in the actual Conference.\n       This will show you the same, as you see at startup the Door.\n       If you enter a Number at the CommandPrompt, you automatic join\n       the selected MsgBase(Nr.) and see the list of last Msgs in the\n       new joined MsgBase.\n\n @{b}S@{ub}   - Scan for new Msgs. This Mailscan searches for new Msgs for you\n       and let you choose btw. READ, QUIT, IGNORE the new mail.\n       The Mailscan also accepts Msgs to `all` and `eall`. \n       After that, you return the CommandPrompt.\n       \n    @{b}@{i}! If you call the Door with additional Argument `s`, so only !\n    ! Mailscan will be executed. Ex:`ml s`.  @{ub}@{ui}see @{"Calling SX_MSG" link "install" 0}\n\n s   - scan for unreaded Msgs <Argument>  (see L.R.P)\n       A short Index of unreaded Msgs will shown here in the form of\n       the Mailscan. Unreaded Msgs including @{b}all@{ub}" link "inst_MS" 0}. Unreaded\n       Msgs including all unreaded Msgs.\n       If you give the `s` Command an Argument `o`, all unreaded Msgs\n       will reset to OLD (read already)\n\n @{b}+/-@{ub} - browse to next/previous MsgBase in this Conference\n\n @{b}#@{ub}   - List the last Msgs only\n       How many lines are listed, is given by the usersettings ScreenLegth.\n       Only the last Messages will be listed as Header List as same as\n       the `L` command does\n\n\n @{"<" link "install" 0}  @{">" link "features" 0}  @{"Main" link "Main" 0}\n@endnode\n\n@node "features" "features"\n       \n@{b} history/features:@{ub}\n -----------------\n         \n SX_MSG V1.2:\n         \n   10.2.98\n          - activ prompt, show current msgbase name\n          - msgbase selection with num. input direct at the prompt\n            then readtopic->user.screenlenght->listend only\n          - msgread selection with argument `r 12` or `r12` \n            here join Msg Options of sx\n          - complete msgs indexlist or only the last ones will shown\n            number,date,time,from,to,reply,subject\n          - ascii found and colored :) now MCI-file does \n            clearscreen at beginning (optional), then logo, then door\n            or what ever you want\n          - some bugs fixed\n          - double listing the MessageBases\n            titelbarinfo: current conference name, current time/date, last l\n                          max msgs/new msgs in current base\n   25.3.98\n          - bugfix - handles 256 MessageBases with maximal\n            10.000 Messages/MessageBase...enought or better 100k ?\n          - reply marker - shows, if the Message is answered  \n            if a msg is replyed more then 1 time, its a double reply marker\n          - new nice looking helpmenu added\n          - private-flag added  :   + if msg is private subject=`PRIVATE`\n                                    + private msg subject visible for \n                                      writer and reciver\n          - delete-flag added   :   + deleted msgs have `DELETED` in subject\n   3.4.98\n          - changed gfx-output a bit\n          - cut the timestring to 5 chars, swap time and date output\n          - move the actualbase(baseindex) function to trash.\n            found XIMFunction(507,0,0) JH_MCI :) for current msgbase\n            at the prompt\n          - bugfix - change the current LRP\n          - new msgs are shown now ! flagged in baseindex and subjectlist an\n            how many of them.\n          - bugfix - cut the messagebasename to 12 chars, coz output trouble\n          - optimised the code, i.e. done an argumentparsing for SX_Function\n          - tuned the gfx a bit\n          - added a small and raw info\n   22.5.98\n          - added a Mailscan what shows unreaded and new mails\n            Mailscan let you choose between read the new msg, do not read or\n            quit mailscan. If you like to read your new mail, Mailscan joins\n            the msg automatic, acceps `eall`,`all` and `username` to be acti\n          - call the door with argument `s` for mailscan only !\n          - added an argument for `s` (scan for unreaded msgs, named `o` to\n            switch all msgs in all msgbases to OLD. \n          - added an argument for `L` (Listview) were you can give a msgnumb\n            from what you like to view the list\n   28.5.98\n          - Mail/Msgscan has now a conference user access level check \n            If the User has no access to any conference, the mailscan\n            breaks\n          - an Informationpage was added with more detailed explaination abo\n            the commands        \n   30.5.98\n          - if Users Screenlength <= 27 lines, the informationpage switched\n            to a second part\n          - optimised the source, killed lamershit. source: 54k including al\n            Ansis\n    1.6.98\n          - make the conference axx check more advanced. checks now all confs\n            for axx, does not break after noaxx anymore. \n            Ex: Confaxx:  XXX_XX_X\n          - do some more small internal fixes, opts, gfx, funcs, ...\n            only penouts\n    3.6.98\n          - bugfix - after Mailscan found new mail, the CommandPrompt\n            is ok now. fixed some penouts, too\n          - finish this Guide\n\n @{"<" link "usage" 0}  @{">" link "plans" 0}  @{"Main" link "Main" 0}\n@endnode\n\n@node "plans" "plans"\n\n @{b}Future Plans:@{ub}\n -------------\n\n go to the net :)\n check out the fido transfer, build a router, a sorter, a spooler with\n inbound/ and outbound/ in Mail:\n Implement this into SystemX together with Zed. Results of such things \n can earliest be viewed in a year, coz there are a lot of other projects\n we are on, so please have patient :)\n\n next todo:\n               \n          - delete msg by nr. from subjectlist (SXFunction?) \n          - if a msg is replayed, add `re:` to the subject WHILE REPLAYING\n            need implementaion in sx, too, or i do it in the ML\n          - more optimisatione grande par code\n          - better gfx/infos\n          - begin some tests for networking ;)\n                    \n    \n @{"<" link "features" 0}  @{">" link "" 0}  @{"Main" link "Main" 0}\n      \n       \n      \n   \n\n@endnode\n\n@node "contact" "contact"\n\n @{b}Contact:@{ub}\n --------\n\n All your Suggestions, Hints and comments are welcome.\n Bugreports are importand for me to know, so i can fix anywhat.\n \n There are serveral way`s to connect me : \n\n My BBS:\n -------\n +49(0)451/55220      Node #1 with 288oo v.FC\n\n Internet:\n ---------\n\n  EMail : [email removed]\n                 [email removed]\n Telnet : 22.00-0.00 GMT daily at   house.dyn.ml.org   Port 23\n    WWW : http://amichurch.home.ml.org\n\n Feel free to write me. \n\n\n @{"<" link "plans" 0}  @{">" link "sx" 0}  @{"Main" link "Main" 0}\n@endnode\n\n@node "sx" "sx"\n\n @{b}SystemX Bulletin Board System@{ub}\n -----------------------------\n\n SystemX is a new Bulletin Board System in the Style of AmiExpress.\n It is available in a Conference based Version and in a Menu based\n Version.\n Its Doorsupport is great, coz many Types of standart Doors are alowed\n and some special ones, too.\n The Maincode is hacked by Zed in pur SASC. Connects to the Autor of\n SystemX may goto [email removed] or visit the SystemX Support Page\n at http://sx.denet.co.jp .\n\n \n @{"<" link "contact" 0}  @{">" link "greetz" 0}  @{"Main" link "Main" 0}\n@endnode\n\n@node "greetz" "greetz"\n\n @{b}gREETz:@{ub}\n -------\n\n Greetings un unordered form:\n\n Get_Merry, Thaler, Obligator, Wolfman, Phantom, Jungle, Sal-One, Wizzler,\n Woober, Ramonster, Stark, Case, Zed, Trantor, Kunglao, Digiman, Gandalf,\n DC`98, Rasta, Test, Shadow, Merlin, Badgirl, Raped, Prodigenator, Crusader,\n Wolfman, Jedi, Belzebuth, R19, Ubit, Shadow, GetMerry, ShenDC, SigmaSeven\n and many many more ...\n\n @{"<" link "sx" 0}  @{">" link "Main" 0}  @{"Main" link "Main" 0}\n@endnode\n\n@node "inst_MCI" "inst_MCI"\n\n @{b}Call ML by MCI-File:@{ub}\n --------------------\n \n If you call the MessageLister by an MCI_File, you may handle the startup\n in serveral ways. How to use MCI-Files you can read in the SX-Guide\n\n - open SXConfig -> Menus/Commands -> Main_Menu\n - add a new Command:\n\n   Command :  ML                               /* the Command Name       */\n   ExtraNr.:   0                               /* no Extra Number needet */\n   LowAxx  :  10                               /* Low Axx for the ML     */ \n   HighAxx : 255                               /* High Axx for the ML    */\n   Func.ID :  12                               /* show Ansi              */\n   Door/String/File : SX:doors/ml/sx_msg.ans   /* path to the ML-Header  */\n\n - check the Part in the @{b}SX_MSG.ans@{ub} (AnsiHeader), were the Door is\n   called like `@{b}~SX_doors/ml/sx_msg.ans@{ub}`, if its correct for you.\n\n Do not kill the `[2J` for clear Screen at the top of the file \n while editing with any AnsiEd !\n You may edit the HeaderFile like your whishes, a complete MCI-Command\n Reference for SystemX ca be found in the SX-Guide.\n\n Send me your own MessageLister Headeransi, i will spread it with the \n next update !!\n\n @{"<" link "install" 0}  @{">" link "inst_XIM" 0}  @{"Main" link "Main" 0}\n@endnode\n\n@node "inst_XIM" "inst_XIM"\n\n @{b}Call ML as XIM:@{ub}\n ---------------\n\n If you call the MessageLister direct as XIM-Door, it will start\n without any preactions with the Index of the MessageBases in the\n current Conference.\n\n - call SXConfig -> Menus/Commands -> Main_Menu\n - add a new Command:\n\n   Command :  ML                                  /* Command Name       */\n   ExtraNr.:   0                                  /* no ExtraNr. needed */\n   LowAxx  :  10                                  /* LowAxx for the ML  */\n   Highxx  : 255                                  /* HighAxx for the ML */\n   Func.ID : 120                                  /* XIM-Door !         */\n   Door/String/File :  sx:doors/ml/SX_MSG         /* the path to ML     */\n\n - Restart SystemX to activate the new Command.\n\n Now logon and check, if all went fine :)\n\n \n @{"<" link "install" 0}  @{">" link "inst_MS" 0}  @{"Main" link "Main" 0}\n@endnode\n\n@node "inst_MS" "inst_MS"\n\n @{b}Call ML as MailScan:@{ub}\n --------------------\n\n If you Login to yer SystemX, the MessageLister has a nice Feature \n to scan for new Msgs.\n If you call the MessageLister with an Argument `@{b}@{i}s@{ub}@{ui}`, only the \n MailScan function of the MessageLister will work.\n\n Example: `@{b}@{i}ml s@{ub}@{ui}`\n\n The MailScan found new Msgs for you, for `eall` and for `all`.\n If the MailScan found such Msg, you can select between\n \n -    Q ...... Quit/Abort the Mailscan\n -    N ...... No reading, but proceed scanning\n - CR/Y ...... Read the new Msgs\n\n This Function is beta for now. Updates can be found on the \n Amichurch Support-Page.\n\n @{"<" link "install" 0}  @{">" link "usage" 0}  @{"Main" link "Main" 0}\n@endnode\n\n','\n',char(10)),NULL,'auto-added',87872,4,0,NULL,NULL,'rfx_ml12','scan',1780048686);
INSERT INTO door_catalog VALUES('rfx_us05','RFX-US05.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RFX-US05.LHA','SXUserStatus','XIM','SXUserStatus',NULL,'[r]fOx','RFX','|\  /|   |   )    )||   )/\  |\  | | \/ |/\ |__/  __/ ||__//__\ | \ | |    /__\| \_  //__|| _/____\|  \|',replace('#  .    .   .___ ____.o____     .   .      #\n   |\  /|   |   )    )||   )/\  |\  |\n   | \/ |/\ |__/  __/ ||__//__\ | \ |\n   |    /__\| \_  //__|| _/____\|  \|\n       /    \    //\ |_)|_   _/\n             \/\//--\| \|___ /__\n     - - - - - - - - - - - - - - -f-X-!\n             SXUserStatus V0.5\n   ------------oo----------oo----------\n        sMALL dOOR uPdATE by [r]fOx \n      XIM Door for System\X by zEd^dC\n#                                         #\n','\n',char(10)),'SXUserStatus.doc',replace('\n===========================\nSXUserStatus v0.5 by [r]Fox\n===========================\n\niNTRODUCING\n-----------\nThis is my first Online door for SX and its the first i wrote in\nSASC. I use Exec Messages for SystemX only, so this door cannot\nrun under another bbs-software.\n\nvERSIONS\n--------\n\n- 0.1 get all the parms and values\n- 0.2 include the first gfx\n- 0.3 replace something and include the\n      `dISABLED` Function for File/Byteratios\n- 0.4 rework the finish\n- 0.5 rewrite the strings, implement a `flickering` at free ratio\n      on files or bytes and include a little info button\n\niNSTALLATIOn\n------------\n\nFor install it to SX do the following steps:\n\n- copy SXUserStatus to doors:\n\n- edit Commands/MainMenu/S as normal XIM-Command\n\n- you may call it in an MCI-text, i.e. postlogin.ans with\n  `SX_doors:SXUserStatus\120\0|`\n\n- shutdown node and restart SX \n\n\nbUGs\n----\n\nThere are no known bugs in this tool, but if you find some,\nso mail me at [email removed].\nThis Door was done on a A12ooT with 030/50/50mHz and 26 MB Ram.\nThe Scsi-Option servs an JVC-2010 CDRecorder and some gigs are\npresent too. This is done in C.\n\ncONTAcT\n-------\n\nYou can mail me at [email removed],\nor grab me on IRC Pulsarnet #elitecafe or Galaxynet #amiga_warez\n\ngREETz\n------\n\nzEd,vinyl,ironfist,wolfman,jungle,joule,sn00py,wizkid, thaler,\ntrantor, phantom... \n\n\n[r]FoX\n','\n',char(10)),NULL,'auto-added',12156,4,0,NULL,NULL,'rfx_us05','scan',1780048686);
INSERT INTO door_catalog VALUES('rfx_xv11','RFX-XV11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RFX-XV11.LHA','AxxView','XIM','AxxView',NULL,'[r]FoX','RFX','|\  /|   |  ))   ))||   )/\  |\  | |\\/ |/\ |_//  _// ||__//_\\ |\\ | |    / \\|\\_  //__|| _/___\\| \\|',replace('#  .    .   .__ ____ .o____     .   .   #\n   |\  /|   |  ))   ))||   )/\  |\  |\n   |\\/ |/\ |_//  _// ||__//_\\ |\\ |\n   |    / \\|\\_  //__|| _/___\\| \\|\n   |  -/+++\\-\  //\ |_)|_   _/\n   |  /     \\/\//--\|\\|___ /_11_3_98\n   `fX!- - - \/\/- - ` \|- - - - - - -\n    /   mARZIPAN dOORS dEVELOPEMENT\n   ------------oo----------oo----------\n    AxxView - Code&GfX dONE bY [r]FoX\n    Update V1.o1 - sexy Viewer for the\n          Accesssets on SystemX\n#                                       #','\n',char(10)),'axxview.readme',replace('\nwelcome to axxview v1.o\n=======================\n\niNTRODz\n-------\n\naxxview is a small viewer for the installed accesslevels\non SystemX by zED^dC.\nIt puts some values about the accessgroups to ansi.\nYou may call it from MainMenu, any MCI-File, or maybe as \ncommand in the BullsMenu.\n\niNSzTA|.|.\n----------\n\ninstall this shit as xim.\nkeep an eye at the accesslevel for this door, maybe you wont \nlet lowlevlers see all yer accesssets ?..\n\neXTRODz\n-------\n\nwow, a 60 mins.hack for all that shit :) my own record ;)\nin futuretimes i`ll add some features and i`m waiting for a \nheaderansi, too, but there are serveral projects here, so an\nupdate comes garanted.\nfor contacting me, writa mail to [email removed]\n\nwell brothz, l8tr :)\n\n[r]FoX\n','\n',char(10)),NULL,'auto-added',9878,4,0,NULL,NULL,'rfx_xv11','scan',1780048686);
INSERT INTO door_catalog VALUES('rg_ano10','RG-ANO10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RG-ANO10.LHA',NULL,'XIM','INSTRUCTIONS.RUNME',NULL,'zWiNx/rAGe''94####','RG','=====\_____  ¬\/~   ¬\_/~    \_/~ ___/====== !:::::7~  /  _/   !   7   l___7  ___)::::::! !:::::!   \  ¬\_  .   !   7  ¬7     ¬7:::::!',replace('     _________  _____   _____   ______\n=====\_____  ¬\/~   ¬\_/~    \_/~ ___/======\n!:::::7~  /  _/   !   7   l___7  ___)::::::!\n!:::::!   \  ¬\_  .   !   7  ¬7     ¬7:::::!\n!:::::l___j\___/__¡___j_______j______j:::::!\n!:::::::::::::pReSenTs:::ToDay:::::::::::::!\n============================================\n#/X mULTiNODe LOGON/LOGOFF mEssaGe & oNLiNe#\n####mESSAGe sENDeR mADe bY zWiNx/rAGe''94####\n','\n',char(10)),'Announce.doc',replace('Announce Util series, by Zwinx/Rage  1994.\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nThe Announce util series is made for multinode systems only. It certifies\nany user (with enough access) to broadcast online messages to any other\navailable node in the system. The user can broadcast messages anonymous or\n"public". He can broadcast messages to one specified node or to all nodes.\n\nAny logon/logoff''s to the system will result in a message sent to all avail-\nable nodes in the system (if you wish).\n\nContents of archive\n~~~~~~~~~~~~~~~~~~~\n     DOORS (dir)                                             \n          Announce (dir)                                     \n            Announce.cfg                     Announce.log    \n            Announce.rexx                    AnnounceOFF.rexx\n            AnnounceON.rexx                  Announce.doc\n     Commands (dir)\n          BBScmd (dir)\n            BROADCAST.info                   MESSAGE.info\n            OLM.info\n          SYScmd (dir)\n            ANNOUNCE_OFF.info                ANNOUNCE_ON.info\n\nInstallation\n~~~~~~~~~~~~\n>>AREXX DOORS MUST BE ABLE TO RUN ON YOUR SYSTEM, CONSULT MANUAL<<\n\nJust copy all files to the correct directories.\nEdit the file DOORS:Announce/Announce.cfg. Here''s how to edit the file:\n\nAll normal nodes should be present in this file. An example:\n--vv--cut--vv--\n0\n1\n2\nQUIETNODE 3\n--^^--cut--^^--\nThis will result in message sending to node 0-3. Node3 will, however,\nbecome "quiet". Noone will know that it''s there. I use it on my local node.\n\nNow, if you want a message to be sent during logon and logoff, you should\ninsert this on the top of your Logon.txt:\n--vv--cut--vv--\n~\n~CC_ANNOUNCE_ON\n--^^--cut--^^--\n...and this to the top of your Logoff.txt:\n--vv--cut--vv--\n~\n~CC_ANNOUNCE_OFF\n--^^--cut--^^--\n\nThat''s it!\n\nContact\n~~~~~~~\nDaGcEnTRaL 9o21o coNtrOlled bY ·zWiNx··yOGi··bIOTHECh·· at:\n+46-31-775-9391 (28k8V.F)  ·«·»·  +46-31-775-9390 (16k8DS)\n','\n',char(10)),NULL,'auto-added',63186,19,0,NULL,NULL,'rg_ano10','scan',1780048686);
INSERT INTO door_catalog VALUES('rg_avail','RG-AVAIL.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RG-AVAIL.LHA',NULL,'XIM','Frontavail',NULL,'XERXES^RAGE!','RG','<---!----------------------------------!---> ¡   ()        ()        ()         ¡ !    \--o      \--o      \--o      !',replace('    .----------------------------------.\n<---!----------------------------------!--->\n    ¡   ()        ()        ()         ¡\n    !    \--o      \--o      \--o      !\n    ¡   .-\__.    .-\__.    .-\__.     ¡\n    !   (      \_  (     \_ (      \_  !\n    ¡    ''-.-''      ''-.-''    ''-.-''     ¡\n    !!RAGE PRESENTS IN 1995 A NEW ÐOOR!!\n    ¡ !FRONTAVAIL v3.0 BY XERXES^RAGE! ¡ \n<---!----------------------------------!--->\n','\n',char(10)),'FrontAvail3ï½·0.Doc','',NULL,'auto-added',6865,4,0,NULL,NULL,'rg_avail','scan',1780048686);
INSERT INTO door_catalog VALUES('rg_check','RG-CHECK.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RG-CHECK.LHA',NULL,'XIM','7773_tIMES_aDDED.run',NULL,'xERXES!','RG','=====\_____  ¬\/~   ¬\_/~    \_/~ ___/====== !:::::7~  /  _/   !   7   l___7  ___)::::::! !:::::!   \  ¬\_  .   !   7  ¬7     ¬7:::::!',replace('      _________  _____   _____   ______\n =====\_____  ¬\/~   ¬\_/~    \_/~ ___/======\n !:::::7~  /  _/   !   7   l___7  ___)::::::!\n !:::::!   \  ¬\_  .   !   7  ¬7     ¬7:::::!\n !:::::l___j\___/__¡___j_______j______j:::::!\n !:::::::::::::PreSeNts:::toDAy:::::::::::::!\n ============================================\n =    tURBO lHA cHECKER v2.0 bY xERXES!     =\n =        wORKS oN /X v.#? aND S!X          =\n ============================================\n','\n',char(10)),'mYTH_sEARCH_nEW_mEMBERS!.txt',replace('                     (· wHERE tHE wAREZ cOME fRUM! ·)\012                  ___\012   .  /\  /\  ____|  \_____________________  _______________ ________\012  _:_// \/  \/~  ||   \_   _______   .__/__)/~        /~    \|.    _/__:_\012   |/        \__ `'' ___/_____  \/   .||~  .|    /____/   |   \|    |___|\012  _/    \/   \\|    |_/     |  \\_  |||   ||   / ~  \    _   \\    |   \_\012  \_____||     \____|\      _____/___||____|___     \\___|     \________/\012  -|-----|______/-----\_____/----Stz!---------\_______/--|______/------|-\012   |     _________________    _____  __________________/\___________  .|\012   |     \_______  \    _/   /~    \/~         /~ ____   /~   _____/  ||\012  _|______|.  __/   \   |___/   |   \    /____/  __/_\ //______   \____|\012   :      ||  \______)  |~  \_  _   \\_ / ~  \_       \/\_    /   \\_  .\012   .      |     | |__________/  |_____/_______/__________/__________/\012-:--------|_____|--------\______|---------------------------------------:-\012__________________________________________________________________________\012 : ····»»»»··»»»»»» +31-10-4779507 < 3 nODEZ rINGDOWN > ««««««··««««····: \012 : ····»»»»··»»»»»» +31-10-4774218 < 1 nODE 28k8 oNLY > ««««««··««««····: \012¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\012__________________________________________________________________________\012 :··»»»· mORE aS 3 yEARS oN-LINE «» nO sYSTEm oR nEWUSER pASSWORD ·«««··:\012 :······································································:\012 :····»·»»· rUNNING oN 68030/40 mHZ! «» lATEST /X v4.x vERSION ·««·«····:\012 :······································································:\012 :···«« mAJOR uPLOADS 2x cREDITS! «» gROUP mAJOR uPLOAD 3x cREDITS »»···:\012¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\012 ______  ______   .___ ____.  _______.\012 \_    \/    _/___|   \    |__\____  |            \012  /    \_/   \    |    \   _______/  |____.\012 /      \     \___.    /   \    \    .    |-----------------------------+ \012/________\     \  |   /______    \___|    |   wORLD hEADQUARTERS......  :\012·-----/_________\____/-------\____\nK|____|-----------------------------+\012:                                                                   \ \ :\012:                 «««««··  mYTH nEWS fLASH ··»»»»»                   \  :\012:                                                                       :\012:  mYTH ¡S sEARCH¡NG fOR mORE mEMBERS, wE aRE sEARC¡¡NG cODERS,         :\012:  gFX aRT¡STS, tRADERS, mUS¡C¡ANS & /X cODERS....                      :\012:  ¡F yOU wANT tO jO¡N, g¡VE a cALL tO mYST¡CAL pLACES (wHQ) aND pAGE   :\012:  tHE sYSOP... hE cAN g¡VE yOU sOME mORE ¡NFORMAT¡ON                   :\012:  wE aRE a fAST gROWING gROUP, lOOK aT oUR /X dOORS aND tHE sOON       :\012:  cOMM¡NG dISK-mAGAZ¡NE                                                :\012:                                                 sIGNED: tHC           :\012+-----------------------------------------------------------------------+\012','\012',char(10)),NULL,'auto-added',31991,9,0,NULL,NULL,'rg_check','scan',1780048686);
INSERT INTO door_catalog VALUES('rg_da120','RG-DA120.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RG-DA120.LHA','Ls','XIM','Date',NULL,NULL,'RG','=====\_____  ¬\/~   ¬\_/~    \_/~ ___/====== !:::::7~  /  _/   !   7   l___7  ___)::::::! !:::::!   \  ¬\_  .   !   7  ¬7     ¬7:::::!',replace('     _________  _____   _____   ______\n=====\_____  ¬\/~   ¬\_/~    \_/~ ___/======\n!:::::7~  /  _/   !   7   l___7  ___)::::::!\n!:::::!   \  ¬\_  .   !   7  ¬7     ¬7:::::!\n!:::::l___j\___/__¡___j_______j______j:::::!\n!:::::::::::::pReSenTs:::ToDay:::::::::::::!\n============================================\ndADD-the ultimate file-ul-info adder for /X!\nGives you configurable outputs like this....\n[·nODE1 14:46 ·3145·cPS ·108·% @ 28800 bPS·]\n...or >anything< you want. dONe by: ·zWiNX·!\n','\n',char(10)),'DADD.doc',replace('DaDD v1.01 ©1994 zWiNx/rAge\n~~~~~~~~~~~~~~~~~~~~~~~~~~~\nWhy?\n~~~~\nThis door is made to fill the dir-listings with even more information. It\nadds a fully configurable line to every uploaded file in all directories,\nwich can contain information about connect boardrate, upload time, cps-rate,\nnode number and upload efficency.\n\nInstallation\n~~~~~~~~~~~~\nJust be sure to:\n        × have DOORS: assigned.\n        × be able to run Arexx-doors (check out the /X doc''s!)\n        × copy all files to the correct directories.\n        × rename the included "EXAMINEx.info" file to EXAMINEn.info, where\n          n is the 1:st free number (usually 2). Check out the /X doc''s for\n          more information.\n        × configure the "DADD.cfg" file as you wish to have it. ONLY LINE 1\n          IN THE .CFG FILE IS RELEVANT!\n        × have your bbs in BBS: and the different nodes under BBS:NODEx/,\n          where x is the node number.\n        × normal /X udlog file must exist on all nodes.\n        × don''t change any filenames in the door. The door must be in\n          DOORS:Dadd/.\n\nSupport\n~~~~~~~\nIf you have any suggestions, bugreports or anything to comment, please\ncontact here:\n\n        × dAgcEnTRaL nOde0: +46-31-775-9390 USr 168oo DUAL\n\n        × dAgcEnTRaL nOde1: +46-31-775-9391 USr 288oo V.34\n\n        × iNTERnEt: [email removed]\n\n        × Voice hotline (telephone answering machine): +46-708-662-151\n             \nVersions/upgrades\n~~~~~~~~~~~~~~~~~\nv0.01   Beta testing version, tested on dAgcentral 9o21o and unicorn.\nv0.51   Udlog backscanning for faster check added.\nv1.01   .cfg file installed for easy fully configurable outputs.\nv1.21   Minor "last char" bug fixed. "Failure due to non-existing\n        file_id.diz" bug removed. 1st RELEASE VERSION!\n\n\n*&* Thanks to ·gUARdiAn· fOr ß-testing! *&*\n\n·zWiNx· -raGe on sTagE ''95-\n\nSaturday 04-Feb-95 18:41:27\n','\n',char(10)),NULL,'auto-added',22273,5,0,NULL,NULL,'rg_da120','scan',1780048686);
INSERT INTO door_catalog VALUES('rg_front','RG-FRONT.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RG-FRONT.LHA','Front','XIM','Front',NULL,'xERXES!','RG','=====\_____  ¬\/~   ¬\_/~    \_/~ ___/====== !:::::7~  /  _/   !   7   l___7  ___)::::::! !:::::!   \  ¬\_  .   !   7  ¬7     ¬7:::::!',replace('      _________  _____   _____   ______\n =====\_____  ¬\/~   ¬\_/~    \_/~ ___/======\n !:::::7~  /  _/   !   7   l___7  ___)::::::!\n !:::::!   \  ¬\_  .   !   7  ¬7     ¬7:::::!\n !:::::l___j\___/__¡___j_______j______j:::::!\n !:::::::::::::PreSeNts:::toDAy:::::::::::::!\n ============================================\n =       fRONT aVAIL v1.2 bY xERXES!        =\n =        wORKS oN /X v.#? aND S!X          =\n ============================================\n','\n',char(10)),'Front.Doc',replace('                             \n                               (13-mARS-95)\n\n\n                             FRONT AVAIL v1.2  \n                             ~~~~~~~~~~~~~~~~\n\n                                 CONTENTS:\n                                 ~~~~~~~~~\n\n                    Main File        - Front  (3,352K!)\n                Command Files        - FrontEnd.info\n\n\n                               INSTALLATION:\n                               ~~~~~~~~~~~~~\n\n                    · Copy the main file to doors:rage/\n            · Put the FrontEnd.info file into the Syscmd Dir! ·\n\n                            HOW TO CONTACT ME !\n\n             CALL : +46-(0)510-62682 GLOBAL EFFECT! rAGE EHQ! \n\n              I TOLD YA! U SHOULD HAVE KILLED ME LAST YEAR!!!\n\n','\n',char(10)),NULL,'auto-added',52371,5,0,NULL,NULL,'rg_front','scan',1780048686);
INSERT INTO door_catalog VALUES('rg_frv10','RG-FRV10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RG-FRV10.LHA','FrontAvail','XIM','FrontAvail',NULL,NULL,'RG','=====\_____  ¬\/~   ¬\_/~    \_/~ ___/===== !:::::7~  /  _/   !   7   l___7  ___):::::: !:::::!   \  ¬\_  .   !   7  ¬7     ¬7:::::',replace('     _________  _____   _____   ______\n=====\_____  ¬\/~   ¬\_/~    \_/~ ___/=====\n!:::::7~  /  _/   !   7   l___7  ___)::::::\n!:::::!   \  ¬\_  .   !   7  ¬7     ¬7:::::\n!:::::l___j\___/__¡___j_______j______j:::::\n!:::::::::::::PreSeNts:::toDAy:::::::::::::\n===========================================   \n=        A xERXES/rAGE pRODUCTION!        =\n=                                         =\n=     fRONT sTATUS v1.0 - fAST - xIM!     =\n===========================================\n','\n',char(10)),'Manual_Greetings.txt',replace('\n\n                        FrontAvail v1.0 [96-02-20]\n                        ~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n /X NOTE:\n               - Very easy to install!\n               - Lamer install description : \n               - Copy Frontend.info to bbs:commands/syscmd/\n               - Copy FrontAvail to Doors:Rage/\n               - Ready...\n\n\n S!X NOTE: \n\n             Just Use the S!X Frontend command included!\n\n\n Greetings:\n\n             Nike - Nu far du allt komma tillbaka!\n            Boone - Nasta gang hamtar ja dej inte i snodrivan nar du deckat.\n          Carabat - Vad haller du pa med!\n          Schille - U''r pervert!\n           Marwic - I wish I was a little bit taller!\n           Baffle - Sorry 4 not showing up at Kindergarten.\n             Mode - Mannen med basrosten.\n           Recall - Vad haller du pa med, bara dra sa dar!\n           Orchid - Go for the 2 gig upload!\n           Chewie - Nasta gang super vi ennu mer!\n           Exidor - Kom tillbaka!\n          Mr.Coke - Erat Demo var ganska bra :)\n            Excel - Alo chawon! Ja komme te Tapa nan gang!\n          Atheist - Good luck with the CD!\n         Snowfire - Haha, du kommer enda inte lasa det har !\n          Alkaron - Lets Party!\n          Mathews - Hope you dont go to jail man!\n            Saxon - I have found Jesus :)\n            Radix - U''r my Wonderwall...\n        Zcandaler - Never giving up the elite list :)\n             Juan - Make me some Ascii will ya!\n          Mad Max - How''s Asylum running?\n           Keldon - What would you trade if you only could trade one ware?\n            U-man - Larare, det later inte skojj...\n          Lacoste - Vill du ha ett piller eller ;)\nAce of spade Crew - Easy way to greet many at the same time ;)\n\n                  - And the rest I''ve forgotten, you know who you are...\n           \n\n                                    Over and out / xERXES^rAGE^bALANCE!\n\n\n+++ATH\nNO CARRIER...\n','\n',char(10)),NULL,'auto-added',7352,4,0,NULL,NULL,'rg_frv10','scan',1780048686);
