INSERT INTO door_catalog VALUES('rj_upt01','RJ-UPT01.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RJ-UPT01.LHA','Protector','XIM','Protector',NULL,'nIGHTSHADE','RJ','\___  ¬\___ ¬\____ ¬\  \___  |___ ¬\____ ¬\ |  .  _/  .   \ ||   \ /  |  |  .   \ ||   \ |__|__ \__|_  /_||_  / \  ___|__|_  /_||_  /',replace('____________________   ______.____________  \n\___  ¬\___ ¬\____ ¬\  \___  |___ ¬\____ ¬\ \n|  .  _/  .   \ ||   \ /  |  |  .   \ ||   \\n|__|__ \__|_  /_||_  / \  ___|__|_  /_||_  /\n- ÷e÷-\/----\/-----\/---\/--------\/-----\/-\n  uN-pROTECTOR v0.1 bY nIGHTSHADE - /X XIM  \n UNPROTECT''S ALL LAME PROTECTED FILE_ID.DIZ \n A MUST IF YOU DON''T WANT TO HAVE THE WHOLE \n DIR WITH THE SAME DESC BECAUSE SOME LAMERS \n      HAVE PROTECTED IF FROM DELETION!      \n- ---------------------------------------- -\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-24-18  TIME: 09:31:15  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',9510,5,0,NULL,NULL,'rj_upt0