INSERT INTO door_catalog VALUES('rj_gp11','RJ_GP11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RJ_GP11.LHA',NULL,'XIM','GPAGE11.RUNME',NULL,'DR.','RJ','\___  ¬\___ ¬\____ ¬\  \___  |___ ¬\____ ¬\ |  .  _/  .   \ ||   \ /  |  |  .   \ ||   \ |__|__ \__|_  /_||_  / \  ___|__|_  /_||_  /',replace('____________________   ______.____________\n\___  ¬\___ ¬\____ ¬\  \___  |___ ¬\____ ¬\\n|  .  _/  .   \ ||   \ /  |  |  .   \ ||   \\n|__|__ \__|_  /_||_  / \  ___|__|_  /_||_  /\n«-÷e÷-\/----\/-----\/---\/--------\/-----\/-\n G_PAGE by DR. G/rAM jAM - a new friendly &\n simply pager door for AMIEXPRESS... Get it\nif u got bored of your pager and were lookin\nfor sumthin'' of really simple & useful !!!!!\n    [Vers. 1.1 - Released on 06/02/96] \nThE SouRce:*THE HOUSE RAM JAM WHQ* of coz !\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-23-18  TIME: 12:01:06  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',13780,2,0,NULL,NULL,'rj_gp11','scan',1780048692);
INSERT INTO door_catalog VALUES('rj_gpage','RJ_GPAGE.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RJ_GPAGE.LHA',NULL,'XIM','___  ___           _____',NULL,'DR.','RJ','+--/ _ \/ _ \/\/\dêµ$-/ / _ \/\/\---+ : / / _/ _  /    \ /\/ / _  /    \  : /X : \/\ \_// (_/\/\ \\__/ //_/ /\/\_) : /X',replace('       ___  ___           _____\n   +--/ _ \/ _ \/\/\dêµ$-/ / _ \/\/\---+\n   : / / _/ _  /    \ /\/ / _  /    \  :\n/X : \/\ \_// (_/\/\ \\__/ //_/ /\/\_) : /X\n   :    \_) \/      \/   \/   \/       :\n   +in collaboration with DIGITAL CHAOS+\n G_PAGE by DR. G/rAM jAM - a new friendly &\n simply pager door for AMIEXPRESS... Get it\nif u got bored of your pager and were lookin\nfor sumthin'' of really simple & useful !!!!!\n[The House]--------------------[Ram Jam EHQ]\n','\n',char(10)),'G_PAGE.GuidE',replace('@DATABASE "Default"\n@NODE "MAIN" "[=G_PAGE=] V 1.0 by DR. G/rAM jAM"\n@TOC "MAIN"\n\n            [=G_PAGE=] V 1.0 by DR. G/rAM jAM - Copyright © 1995\n            ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n          \n @{" Disclaimer " LINK "DISCLAIMER"}  @{" Purpose " LINK "Purpose"}  @{" Installation " LINK "Installation"}  @{" Features " LINK "Features"}  @{" Bug reports " LINK "Bug reports"}  \n\n                        @{" Credits & Greetings " LINK "Credits & Greetings"}\n           \n@ENDNODE\n\n@NODE "Disclaimer" "Disclaimer"\n@TOC "MAIN"\n\n                            READ CAREFULLY\n                            --------------\nI take no responsibility for data corruption or lack of data caused by\nG_PAGE, anyway it''s tested many times and has shown no errors so far.\n\nTHIS WARE IS FREE, THAT MEANS YOU CAN FREELY DISTRIBUTE THE ARCHIVE.\nNOTHING CAN BE MODIFIED OR CHANGED WITHOUT THE AUTHOR PERMISSION !!!\nIF YOU LIKE THIS TOOL OR USE IT JUST CALL MY BOARD AND LET ME KNOW.\n\n@ENDNODE\n\n@NODE "Purpose" "Purpose"\n@TOC "MAIN"\n\nWell, due to the popular demand here''s a public version of this utility.\nIt''s just a simply Pager Door for amiexpress, but suggest you to install\nit if u got  bored of usual and  complicated  paging  utilities and were \nlooking for something of tiny, fast, reliable and 100% backdoors free !!\n\n@ENDNODE\n\n@NODE "Installation" "Installation"\n@TOC "MAIN"\nI guess you all figure out how to install an amiexpress door so I''m not\ngoing on explaining how to do it. I just included the main dir (move it\nin your DOORS: ) and an icon that must be placed into BBSCMD dir, that''s\nall.\n\n@ENDNODE\n\n@NODE "Features" "Features"\n@TOC "MAIN"\n o 100% ASM CODE (THANX TO KRS/DIGITAL CHAOS FOR CONVERTING THE ORIGINAL\n   AREXX CODE, ONLY 3316 BYTES OF POWER 8)\n                    ^^^^\n o FRIENDLY OUTPUT.\n\n o ADDS A COMMENT IN YOUR CALLERSLOG REPORTING THE USER PAGED YOU EVEN IF\n   THE CHAT FLAG WAS OFF INCLUDING DATE & TIME (PRETTY KEWL).\n\n o WHEN THE CHAT FLAG IS OFF THE USER IS ASKED TO LEAVE A COMMENT TO SYSOP,\n   PRESSING ''Y'' A LINE IN THE CALLERSLOG IS ADDED REPORTING A COMMENT WAS\n   LEFT AFTER PAGING. (SO YOU DON''T NEED TO LOG ON YOUR LOCAL NODE TO CHECK\n   IF NEW MAIL IS WAITING FOR U ! JUST GO THRU YOUR CALLERSLOG)\n\n o IF CHAT FLAG IS ON A REASON FOR PAGING IS REQUESTED (AND PROMPTED IN THE\n   CALLERSLOG): NO REASON MEANS NO PAGING PROCEDURE!\n  \n    \n@ENDNODE\n\n@NODE "Bug Reports" "Bug Reports"\n@TOC "MAIN"\nI''ve been testing it for ages and haven''t noticed any bug. Anyway you can\nkeep in touch with me calling my board, the RAM JAM EUROPEAN HQ AT:\n\n  .----------------------------------------------------------------------.\n  |THE HOUSE - +39-40-395286 - Running on 030/40mhz/FPU/28.8 v.everything|\n  `----------------------------------------------------------------------''\n\nNOTICE THAT I STOPPED CALLING & TRADING AROUND SINCE A LONG TIME SO PLEASE\nDON''T LEAVE MAIL AROUND I WILL NOT RECEIVE YOUR MESSY.\n\n@ENDNODE\n\n@NODE "Credits & Greetings" "Credits & Greetings"\n@TOC "MAIN"\n * Credit:\n\n Fly to KRS/DIGITAL CHAOS for his precious help !\n To me for this product 8)\n\n GREETINGS LIST:\n\nTo the italian and worldwide scene xpecially to:\n\n RED ALERT: Hey is your board still up? Call me...\n     ELVIN: Do u still remember me? Master & Servant rulez 8)\nMARIO/TRSI: Hey friend how are u? Call me sometimes, would like to get\n            in touch with SPIRIT OF SOUL hehehehe...\n     SAMIR: Hey my friend, I''m always waitin'' for U your account will be\n            alive forever ehheh... CIAO & greetings for ur girl.\n      FURY: Hello, Dial Hard rulez eh? U know why I can''t call anyway\n            waitin'' for your callback!\n OZONE&ROB: Dunno if u ever get this messy anyway tons of greetings for u\n            all, will be the best friends of mine.\n      RHYS: Yoo..is your board up? Call me if u''re still trading 8)\n  S/\L ONE: Hey my friend! Boondox is ruling isn''t it? Can''t call u at the\n            moment ehehe..\nSECTORCHARGER: Hello! 8)))\n   PRINCIP: Hi! I''m still here my friend It''s a long time I haven''t heard\n            from you...can u still call? If not don''t worry PIAGGIO RULEZ!\n GILTHANAS: Damn! I got lotsa probs with your board in getting a connection\n            Anyway you''re welcomed on THE HOUSE\n STEVE/D&R: Hello STEPHAN! Dunno if u can still call me anyway I''m gonna\n            visit my girl will send u a postcard 8) EDO RULEZ!\n    PRAYER: Call me!\n    PICARD: Yoo...long time no call u anyway don''t delete my account..maybe\n            one day will be back who knows 8)\n     HYDRO: CIAO...still with MEL ?\n     ZIGOR: EHI! News from EDDIE?\n     NITRO: I got my stats resetted..arghh why?????? ehehhe...\n SNAKE/PSG: MOSTRO...Thanx for being so KEWL & uploading so much 8)))\n MODEM BOY: Sorry for DELTA CITY...\n    SAUZER: Call me more often ehehehe... PAY TV RULEZ!\n    EMPIRE: Go on coding your great utils!\n BLUELIGHT: Naja suxx!\n     PAPAJ: Abso-bloody-lutely My best friend! Fuck business, fuck lamers,\n            fuck ... Alessietta 8)))) (sorry for being so strong) but I''m\n            your master! PROGRESSIVE/UNDERGROUND RULEZ! SEND ME A TAPE.\n     VIRUS: WHen shall we meet eachother ?\n    GURGLE: GET A 28.8...GET A LIFE 8)\n   ALX STY: Pezzo di LORDO!\nHIGHLANDER: Speed massive global trader...\nDR FAUSTUS: Hey! CIAO!\n       XAD: Have u lost my number ? 8) anyway CIAO!\n  HANTAREX: Got your 4000 ?\n      ACBS: HELLO RAM JAM LEADER !\nTHE RIPPER: Thanx for being a friend of mine !\n      BOBO: Come on! Let us have an update of Conftop and Filedescription\n            as soon as possible! CHeck''em using Dynamic cache! 8)\nP0T NOODLE: Hello LEO! I haven''t heard u for ages! I guess you can''t call\n            around anyway my board is still opened ehheh...Did u like the\n            modulez you download from my boards ? Hope so..anyway I got\n            your utility box, great as always, and what about your WB\n            background? Arghh it''s simply fantastic! Greetings from ALEX\n            (Metalbasher) he was busted in december anyway will be back!\n            Call me if u have a chance or let me have your news would like\n            swapping some mail with U. Keep on coding masterpieces...\n            PS: DUPECHECK GURUED 8) dunno why! Who carez...\n\nSorry if I''ve forgotten someone but no time lately...greeting to all my\nusers and people who know me.\n\n                        MESSAGE TO EVERYBODY: \n\nIF U''RE AN UNDERGROUND/PROGRESSIVE/TRANCE/TEKNO/RAVE LOVER I''M LOOKING\nFOR SOMEONE WHO IS WILLING TO SWAP COOL MIXED TAPES... CALL MY BOARD\nAND LEAVE ME A COMMENT!\n\n                <>R.A.M. .J.A.M. eUROPEAn hEADQUARTEr<>\n                 _______ _____________  ______________\n                 \      Y        /|   \ \_     - --- /\n                  \   _ :  ._  //:|   \\/     ______/\n                   \_// o  ||\_/ ___   \\     ___)__\n                     /     :|     |     \\     - --.|\n                   _/      .|    .|      \\        ||\n                   \________|    ||____ __/___     :|\n                        \_________|    Y      \_____|\n       ________    __ ____    ________ o  __________________________\n      /  .|    \  /  Y    \  /  .|    \  /                -  - --- /\n     /   ||    \\/   :    \\/   ||    \\/      _______      ______/\n    /    ___    \\   o |   \\   :|     \\______    .\/      ___)__\n   /     .|      \\    |    \\          \\     \    \\         --.|\n  /      ||       \\         .\          .\          \\          ||\n  \_______|        .\_________/___________/___________/____      :|\n==========|_________/=================================[rFx]\______|===\n\n        tHe cREw: DR. G/rAm jAm .. aLx sTy .. sNAKe/pRESTIGe\n\n    [oNLINe sINCe 1990] [oNLy aMIGa sTUFf..no pEECEe no cONSOLe]\n [...sYSTEm pERFORMEd by: o³o/4o mHz bOARd aNd 28.8 v34 cOURIEr...!]\n[rAm jAm cHARTs vOTINg dOOr iNSTALLEd] [rAm jAm rELEASEs fREEDOWNLOAd]\n[tEKNo-rAVe-hOUSe-hARDCORe gUYs wELCOMEd..am¡ga mUs¡c mODs cONFERENCe]\n                -[aSCIi dOMAIn] [nO nUp oR sYs. pW]-\n\n@ENDNODE\n','\n',char(10)),NULL,NULL,57475,6,0,NULL,NULL,NULL,'scan',1780048692);
