INSERT INTO door_catalog VALUES('rlg_ae12','RLG-AE12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RLG-AE12.LHA',NULL,'XIM','______   __.       _____.',NULL,'sHADOW','RLG','====/  _   \=/  |======/  .__|=[ rELIGION ]= S M/\    __//\  |__.  /\  |_ | / \\/   \/ \\    | / \\  ! | >>pRESENTS<<',replace('     ______   __.       _____.\n====/  _   \=/  |======/  .__|=[ rELIGION ]=\nS M/\    __//\  |__.  /\  |_ | \n  / \\/   \/ \\    | / \\  ! | >>pRESENTS<<\n /____\_  /____\___|/____\___|\n========\/==================================\n    aLPHA-eDIT v1.2!! iT`S a rEALLY nICE\n dESCRIPTION eDITOR wITH mANY nEW fEATURES!\n    xIM dOOR bY sHADOW mAN/rLG/aVT fOR\n   /X2.xx /X3.xx /X4.xx & sIGMA-EXPESS!\n============================================\n','\n',char(10)),'aLPHA-eDIT.gUIDE',replace('@database aLPHA-eDIT\n\nCopyright (c) 1994 by SHaDoW MaN\n\n@Remark $VER: (September 09 1994, 00:24:00)\n@Remark AmigaGuide DataBase "SHaDoW MaN" DoCuMeNTaTioN\n\n@node MAIN "aLPHA-eDIT v1.2 gUIDE (c) 1994 BY SHaDoW MaN/cARRIER iN sPACE bBS"\n /\____________________________________________________________________/\\n(  ____________________________________________________________________  )\n \/                                                                    \/\n ________       __       ________  ____       ________    ________\n=\       \====__\/__====/        \/    \=====/        \=/\\       \=======\n  \       \ __\    /__ /    /    /    _/    /         //  \\       \\n   \       \\  \  /  //       __/    /     /  __/____//    \\       \\n    \       \\  \/  //    /   \/    /___  /   \___ \ /  /\  \\       \\n     \       \\    //    /    /    /    \/    /    //__/  \__\\       \\n[S M] \       \\  //    /    /    /     /    /    /   /____\   \       \\n=======\_______\\//____/____/__________/\________/======/\======\_______\=\n                      ______________________________    ¯¯\n         /\          / ____________________________ \          /\\n       _/  \_       / /                            \ \       _/  \_\n      / _/\_ \      \_¯\ rELIGION fUCKS yOU wITH: /¯_/      / _/\_ \\n     / / /\ \ \_______\ \                        / /_______/ / /\ \ \\n    ( ( (  ) )    @{"aLPHA-eDIT v1.2 ..tHE sAGA cONTINUES.." LINK Edit}    ( (  ) ) )\n     \ \_\/_/ /¯¯¯¯¯¯¯/ /                        \ \¯¯¯¯¯¯¯\ \_\/_/ /\n      \_ \/ _/      /¯_/ cODE dONE bY sHADOW mAN! \_¯\      \_ \/ _/\n        \  /        \ \____________________________/ /        \  /\n         \/ @{"-iNDEX!-"LINK Index} \______________________________/ @{"fEATURES"LINK Feature} \/\n\n /\____________________________________________________________________/\\n(  ____________________________________________________________________  )\n \/                                                                    \/\n@endnode\n@node Edit "hEY iNSTALL iT..."\n         ____ ____ __________ __ ____          ___ __  ___________\n========/    |  _/=\_      / |  |    \========/   |  \=\__|______/========\n       / _j  |  |   |  -  /  |  |  i_ \ ____ / ___|   \ | \ | \\n      /  \_  |  |___|  __/|     |  _/  \\__//  _|_|  | \|  \|  \ v1.2\n     /    |  |  |   /  |  |  |  |  |    \  /      |  |  \   \   \\n=====\____|__|_____/|__|==|__|__|__|____/==\______|_____/___/___/===[S M]=\n\n                        iS fULLY wRITTEN iN `C` !!!\n  tHE cODER gIVE`S yOU oNLY tHE gUARANTY oF a 100% bACKDOOR fREE dOOR,\niF yOU hAVE dOWNLOADED tHE fULL pACKAGE fROM a rLG/aVT mEMBERSHIP bOARD,\n               a bETATEST bOARD (lOOK iNTO tHE @{"gREETS" LINK Greets!} !),\n                oR fROM tHE hOME oF tHIS gREAT pRODUCT !\n\n     sO dON`T mISS tO cALL tHE hOME aND cALL tHE @{"cARRIER iN sPACE!"LINK jOIN!!!}\n\n                         fILESIZES aND fILEHUNKS :\n\n       fILENAME:             sIZE:        hUNK_cODE:\n\n       aLPHA-eDIT.000        47752        (1001/$03E9) 44912 bYTES\n       aLPHA-eDIT.030        47272        (1001/$03E9) 44504 bYTES\n       aLPHA-eDIT.cFG         1841        -\n       aLPHA-eDIT.gUIDE      18905        -\n       aLPHA-eDIT.hISTORY     2356        -\n       fILEDESCRIPTION.lOGOS 78230        -\n\n==========================================================================\n@endnode\n\n@node Index "iT`S tHE iNDEX..."\n         ____ ____ __________ __ ____          ___ __  ___________\n========/    |  _/=\_      / |  |    \========/   |  \=\__|______/========\n       / _j  |  |   |  -  /  |  |  i_ \ ____ / ___|   \ | \ | \\n      /  \_  |  |___|  __/|     |  _/  \\__//  _|_|  | \|  \|  \ v1.2\n     /    |  |  |   /  |  |  |  |  |    \  /      |  |  \   \   \\n=====\____|__|_____/|__|==|__|__|__|____/==\______|_____/___/___/===[S M]=\n\n               =============================================\n               ============= i = N = D = E = X =============\n               =============================================\n               ===                                       ===\n               ===     @{"          fEATURES!          " LINK Feature}     ===\n               ===     @{"        iNSTALLATION!        " LINK Install}     ===\n               ===     @{"        rEQUIREMENTS!        " LINK Require}     ===\n               ===     @{"          gREETINGS          " LINK Greets!}     ===\n               ===     @{"   wANNA bE a bETA tESTER?   " LINK bETA!!!}     ===\n               ===     @{"    jOIN tHE sPACE pOWER!    " LINK jOIN!!!}     ===\n               ===                                       ===\n               =============================================\n               =============================================\n               =============================================\n\n==========================================================================\n@endnode\n@node Feature "tHE fEATURES oF tHIS dOOR !"\n         ____ ____ __________ __ ____          ___ __  ___________\n========/    |  _/=\_      / |  |    \========/   |  \=\__|______/========\n       / _j  |  |   |  -  /  |  |  i_ \ ____ / ___|   \ | \ | \\n      /  \_  |  |___|  __/|     |  _/  \\__//  _|_|  | \|  \|  \ v1.2\n     /    |  |  |   /  |  |  |  |  |    \  /      |  |  \   \   \\n=====\____|__|_____/|__|==|__|__|__|____/==\______|_____/___/___/===[S M]=\n\n                  hERE aRE tHE fEATURES oF tHIS kEWL dOOR:\n\n - *NEW* cFG fILE tO sET uP sOME aCCESS lEVELS ... rEAD aBOUT iT, aT tHE\n   iNSTALL pAGE! (wITH nAME oVERRIDE!)\n - yOU cAN eNTER uP tO 15 fILES fOR sCANING ! [* & ?] aLLOWED sOON !\n - tHE cURSOR kEYS fOR mOVING tHE cURSOR\n - yOU hAVE 15 lINES fOR yOUR dESCRIPTIONS !\n - [CTRL-L] cLEAR aLL lINES\n - [CTRL-Y] cLEAR oNE lINE\n - [CTRL-A] aDD lINE\n - [CTRL-F] iNSERT lINE\n - [cTRL-X] rEMOVE lINE\n - [cTRL-W] lINE oPTIONS\n   - [A] MOVE LINE FROM / TO\n   - [B] COPY LINE FROM / TO\n   - [C] CHANGE LINE x WITH LINE x\n - [cTRL-G] gROUP lOGO`S mENU\n   - iNSERT a gROUP nAME      (i.E. aLPHA-fLIGHT / oSIRIS / mYSTIC)\n   - iNSERT a gROUP dETECTION (i.E. aFL-         / oRS-   / mST-  )\n   - [?] aND yOU sEE a lIST oF aVAILABLE gROUP-lOGOS (rEALTIME lOADED!) !\n   - [A] aUTO-dETECT gROUP lOGO bY sEARCHING fOR tHE fIRST cHARS !\n     - iF tHE lOGO wAS fOUND:\n     - [V] vIEW tHIS lOGO\n     - [C] cONTINUE sEARCH\n     - [I] iNSERT tHIS lOGO\n       - yOU wANT tO iNSERT tHE lOGO!\n       - [C] cOPY tHE lOGO oVER tHE dESC             [oLD dESC=lOST!]\n       - [T] aDD tHE lOGO TO tHE tOP oF tHE oLD dESC [oLD dESC=kEEP!]\n       - [E] aDD tHE lOGO TO tHE eND oF tHE oLD dESC [oLD dESC=kEEP!]\n       - [A] aBORTS tHE iNSERT mODE !\n     - [Q] qUIT\n   - [Q] qUIT / baCK tO tHE eDITOR !\n - [cTRL-T] fILE mENU\n   - eDIT fILEfLAG\n   - eDIT fILEsIZE\n   - eDIT fILEdATE\n - [cTRL-N] fILE_iD.dIZ mENU!\n   - yOU hAVE tO sET tHE pATH fOR aLL tHE nEEDED tOOLS!\n   - sUPPORTING: LZH,LHA,DMS,ZIP,TXT,DOC,NFO FILE`S !\n   - [1] rEAD oUT fILE_iD.dIZ fILE! (wITH aCCESS lEVELSET iN tHE cFG-fILE!)\n   - [2] aDD fILE_iD.dIZ fILE!      (wITH aCCESS lEVELSET iN tHE cFG-fILE!)\n   - [3] dELETE fILE_iD.dIZ fILE!   (wITH aCCESS lEVELSET iN tHE cFG-fILE!)\n   - [Q] qUIT (bACK tO tHE eDITOR!)\n - [cTRL-Z] cURSOR pOSITION [  oN/ *oFF ]\n - [cTRL-V] iNSERT mODE     [  oN/ *oFF ]\n - aFTER sAVING oR aBORTING:               (aPEARS oNLY aT mULTIPLE fILES!)\n   - qUESTION tO rEAD tHE nEXT dESCRIPTION(S)\n   -                                (yES/nO/sKIP tO tHE nEXT! oR ? - hELP!)\n - hOPEFULLY aN eASY tO uSE dOOR !\n - aND iT wILL bE mORE & mORE nEXT tIME... sO dON`T mISS tO iNSTALL iT !\n - fOR mORE kEWL iDEAS oR bUGS... cALL mY bOARD !\n\n==========================================================================\n@endnode\n@node Install "iNSTALL pAGE..."\n         ____ ____ __________ __ ____          ___ __  ___________\n========/    |  _/=\_      / |  |    \========/   |  \=\__|______/========\n       / _j  |  |   |  -  /  |  |  i_ \ ____ / ___|   \ | \ | \\n      /  \_  |  |___|  __/|     |  _/  \\__//  _|_|  | \|  \|  \ v1.2\n     /    |  |  |   /  |  |  |  |  |    \  /      |  |  \   \   \\n=====\____|__|_____/|__|==|__|__|__|____/==\______|_____/___/___/===[S M]=\n\n         yEAH... yOU wANT tO iNSTALL tHIS dOOR... gREAT iDEA !!!\n       cOPY aLL fILES iNCLUDED iN tHE aRCHIV tO a dIRECTORY cALLED\n                             "dOORS:aLPHA-eDIT/"\n           nOW uSE tHE iCON iNCLUDED iN tHE aRCHIV aND cOPY iT tO\n                           "bBS:cOMMANDS/bBSCMD/"\n            nOW i hAVE iNSERTED a cONFIG fILE fOR yOUR pRIVATE\n                 aCCESS lEVELS aND fOR sOME oTHER tHINGS!\n              cOPY tHE aLPHA-eDIT.cFG fILE iNTO a dIR cALLED:\n                             "DOORS:aLPHA-eDIT/"\n                        @{" rEAD aBOUT tHIS cFG fILE! " LINK CFGFile}\n     iF yOU wANT tHE gROUP-lOGO mENU, tHEN yOU hAVE tO cOPY tHE fILE\n                     fILEDESCRIPTION.lOGOS iNTO tHIS dIR:\n                             "DOORS:aLPHA-eDIT/"\n                 dOC fOR uSING tHE fILEDESCRIPTION.lOGOS fILE:\n\n    aT fIRST i mUST sAY tHAT tHIS lOGO fILE wAS tAKEN fROM bOBO`S\n        fILE_ID.DIZ dOOR ! oK, lET mE sAY sOMETHING aBOUT iT:\n\ntHE lOGO`S mUST iN tHIS oRDER:\n===============================================================[cUT hERE]=\nGroup: <gROUPnAME>\nDetect: <dETECT>\n\n < gROUP-lOGO! (10*44/lINES*cHARS) >\n\n#\n===============================================================[cUT hERE]=\n\nlINE01: Group: -> eNTER hERE tHE nAME oF tHE gROUP (sPACES aLLOWED!) !\nlINE02: Detect: -> eNTER hERE tHE gROUP dETECT lIKE rLG- !\nlINE09: # -> tHAT iS tHE eND-oF-lOGO mARK! yOU mUST eND wITH tHAT mARK !\n\nnOTE: tHE dESCRIPTIONS sHOULD bE 10*44 cHARS, oTHERWISE iT wILL\n      bE cUT. iF tHE gROUP dON`T hAVE aNY ''dETECT'', eNTER NONE.\n      iF yOU wANT mORE lOGO`S fROM oNE gROUP!\n      nO pROBLEM: uSE tHE sAME nAME aND tHE sAME dETECT aND tHE dOOR\n                  wILL sEARCH fOR tHAT lOGO aFTER pRESSING tHE cONTINUE\n                  sEARCH kEY [C] !\n      yOU cAN uSE aS mANY lOGOS aS yOU wANT ! aND yOU dOESN`T nEED tO\n      uSE aNY nUMBERS lIKE <gROUPnAME.1> oR aNYTHING eLSE!\n      \n      aND nOW hAVE pLENTY oF pHUN wITH yOUR nEW dESCRIPTION-eDITOR!!!\n\n==========================================================================\n@endnode\n@node CFGFile "tHAT`S aN eXAMPLE fOR tHE cONFIG fILE..."\n         ____ ____ __________ __ ____          ___ __  ___________\n========/    |  _/=\_      / |  |    \========/   |  \=\__|______/========\n       / _j  |  |   |  -  /  |  |  i_ \ ____ / ___|   \ | \ | \\n      /  \_  |  |___|  __/|     |  _/  \\__//  _|_|  | \|  \|  \ v1.2\n     /    |  |  |   /  |  |  |  |  |    \  /      |  |  \   \   \\n=====\____|__|_____/|__|==|__|__|__|____/==\______|_____/___/___/===[S M]=\n\n------------[ cUT hERE ]------------\n;\n; aLPHA-eDIT v1.2 cFG-fILE ! uSE tHIS tO sET uP yOUR aLPHA-eDIT !\n; aLPHA-eDIT (tm) iS sEARCHING fOR tHE fILE `aLPHA-eDIT.cFG` iN tHIS dIR:\n; `dOORS:aLPHA-eDIT/` iF tHE dOOR dOESN`T fIND tHIS fILE... tHE dEFAULTS\n; wILL bE uSED !\n;\n; tHIS aRE tHE dEFAULTS:\n;\n; File-Menu-Access: 250                        fUNCTION iN tHE dOOR: [CTRL-T]\n; ^^^^^^^^^^^^^^^^^^^^^ tHIS aCCESS lEVEL sET uP iS fOR tHE [cTRL-T] oPTION !\n;                                              fUNCTION iN tHE dOOR: [CTRL-N]\n; FileID-Read: 020                                                    [KEY-1]\n; FileID-Add: 250                                                     [KEY-2]\n; FileID-Delete: 250                                                  [KEY-3]\n; ^^^^^^^^^^^^^^^^^^ tHIS aCCESS lEVEL sET uP`S aRE fOR tHE [cTRL-N] oPTION !\n; wRITE tHE aCCESS lEVELS aLWAYS wITH 3 cHARS (i.E. 005, 050 oR 150)\n;\n; Name-Access: <USERNAME>     tHIS fUNCTION oVERIDES aLL aCCESS lEVELS aBOVE!\n;                             ^ more then 100 are not allowed !\n;                             ^ no numbers needed (Name-Access.1:)!\n;                             ^ please write only the name and nothing other\n;                             ^ into this line!\n;\n; Diz-Tools-Dir: C:\n; ^^^^^^^^^^^^^^^^^ tHIS dIRECTORY iS fOR tHE fILE_iD.dIZ uTILS lIKE\n; dMSdESCRIPT,tXTeXTRACT,eXEdESCRIPT,lHA,zIP & uNZIP wHAT`S aBOUT tHE c: dIR!\n; dON`T fORGET tHE `:` oR ''/'' aT tHE eND !!!\n;\n; ^ aLL tHIS sETUP`S aRE nOT cASE sENITIVE ! ^\n;\n\nFile-Menu: 250        ; Access level for the filemenu !\nFileID-Read: 020      ; Access level to read out the FILE_ID.DIZ file!\nFileID-Add: 250       ; Access level to add a new FILE_ID.DIZ file!\nFileID-Delete: 250    ; Access level to delete the FILE_ID.DIZ file!\nDiz-Tools-Dir: C:     ; Directory for the FILE_ID.DIZ Tools !\nName-Access: spider\n\n; eND-oF-fILE!\n------------[ cUT hERE ]------------\n\nyOU nEED tHIS fILES iN yOUR Diz-Tools-Dir:\n\nMAKEDIR            -> TO MAKE A DIR IN THE RAM (RAM:NODEx/FILE_ID.DIZ)\nPROTECT            -> TO D`PROTECT THE FILE_ID.DIZ FILE IF IS IT PROTECTED!\n^-> tHIS aRE 100% wB fILES!\nLHA                -> NO COMMENT!\nZIP & UNZIP        -> FIND OUT YOUR SELF!\nDMSDESCRIPT        -> ALL FOR THE FILE_ID.DIZ FILES !!!\nEXEDESCRIPT        -> ALL FOR THE FILE_ID.DIZ FILES !!!\nTXTEXTRACT         -> ALL FOR THE FILE_ID.DIZ FILES !!!\n\ntHIS fILES aRE iNCLUDED iNTO tHE aRCHIVE!\n\ntHAT`S iT dUDE!                   @{" BACK " LINK Install}\n\n@endnode\n@node Require "yOU nEED tHIS tO iNSTALL tHIS dOOR..."\n         ____ ____ __________ __ ____          ___ __  ___________\n========/    |  _/=\_      / |  |    \========/   |  \=\__|______/========\n       / _j  |  |   |  -  /  |  |  i_ \ ____ / ___|   \ | \ | \\n      /  \_  |  |___|  __/|     |  _/  \\__//  _|_|  | \|  \|  \ v1.2\n     /    |  |  |   /  |  |  |  |  |    \  /      |  |  \   \   \\n=====\____|__|_____/|__|==|__|__|__|____/==\______|_____/___/___/===[S M]=\n\n                               yOU nEED:\n\n - a fULLY iNSTALLED aMI-eXPRESS 2.x/3.x/4.x oR sIGMA-eXPRESS !\n - aN aMIGA 500,1000,1200,2000,3000,4000 wITH iNSTALLED oS2.0 oR hIGHER!\n - a cOLOR mONITOR tO sEE tHE wONDERFULL sTYLE oF tHIS dOOR hEHEHE !!!\n\n==========================================================================\n@endnode\n@node Greets! "hERE aRE sOME gREETINGS..."\n         ____ ____ __________ __ ____          ___ __  ___________\n========/    |  _/=\_      / |  |    \========/   |  \=\__|______/========\n       / _j  |  |   |  -  /  |  |  i_ \ ____ / ___|   \ | \ | \\n      /  \_  |  |___|  __/|     |  _/  \\__//  _|_|  | \|  \|  \ v1.2\n     /    |  |  |   /  |  |  |  |  |    \  /      |  |  \   \   \\n=====\____|__|_____/|__|==|__|__|__|____/==\______|_____/___/___/===[S M]=\n\n                  gREETS aT fIRST tO mY bETA-tESTERS:\n\n nAME          bBS                               aMIGA/0x0/MHz/rAM  sOFTW.\n--------------|---------------------------------|-------------------------\n rED aLERT     tHE aDDICTION / /X sUPPORT bOARD  A1200/020/014/?  - /X4.5b\n iNTERCODE     lAMERS iNN                        A2000/040/028/10 - /X3.37\n fRANK/aFL     cRASH bBS                         ?\n mARKY & pOWER sPREAD dRAFT                      A4000/040/025/14 - S-Exp.\n eURoNYMOUS    ?                                 A1200/020/014/07 - /X4.5b\n lACOSTE!      dATA sTORM                        A2000....          /X3.38\n--------------|---------------------------------|-------------------------\n\n tHE tOOL wAS nOW tESTET oN /X4.xx aND sIGMA-eXPRESS, iT rUNS fINE!\n\n                           sOME gREETINGS tO:\n\n - sPIDER/oSi®iS ............... fOR tEACHING mE `C` aND fOR aLL yOUR hELP!\n - eMPIRE/mYSTIC ............... fOR hIS gREAT hELP iN `C` aND fOR cALLING!\n - tERRORIST/aFL ......................................... fOR tHE sUPPORT!\n - >> µ£¯|¯®å << ............................. fOR tHE gREAT mORAL sUPPORT!\n - cELATOR/aFL   .. fOR sOME hELP iN `C` aND fOR tHE bUG hELP oN cOLORWALL!\n - bOBO/mST      ...................................... gREAT fILE_iD tOOL!\n - kILLRAVEN/mST ............................. gREAT wORK oN yOUR cONFsCAN!\n - fATE          .......................... kEEP oN wRITING fOR c-nET hEHE!\n - -vINDEX!      ........................... tHX fOR aLL tHAT mAILS hAHAHA!\n - tHE cROW/aVT  ...... iT`S mY nEW cO-sYSOP ... tHX fOR tHE gREAT sUPPORT!\n - hKWD&nOS!/rLG ..................... vERY gREAT sUPPORT iN tHE lAST dAYS!\n - lACOSTE!      ............................... tHX fOR tHAT aWESOME cALL!\n - aND tO        ................................... aLL rLG & aVT mEMBERS!\n\n aT lAST i wANT tO gREET aLL mY uSERS oN mY oWN bBS!\n\n==========================================================================\n\n@endnode\n@node bETA!!! "i`AM lOOKING fOR bETA tESTER`S !!!"\n         ____ ____ __________ __ ____          ___ __  ___________\n========/    |  _/=\_      / |  |    \========/   |  \=\__|______/========\n       / _j  |  |   |  -  /  |  |  i_ \ ____ / ___|   \ | \ | \\n      /  \_  |  |___|  __/|     |  _/  \\__//  _|_|  | \|  \|  \ v1.2\n     /    |  |  |   /  |  |  |  |  |    \  /      |  |  \   \   \\n=====\____|__|_____/|__|==|__|__|__|____/==\______|_____/___/___/===[S M]=\n\n                      sEARCHING fOR bETA tESTER`S !!!\n\n  i nEED fOR mY dOORS sOME bETA tESTERS fOR tESTING tHE dOORS iN /X2.xx\n  aND sIGMA-eXPRESS ! bECAUSE mY bOARD rUNS wITH rEGISTRED /X3.xx, sO i\n                cAN`T tEST tHE dOORS oN /X2.xx vERSIONS yET !\n\n            iF yOU aRE iNTRESTED tHEN cALL tHE cARRIER iN sPACE!!\n         yOU cAN gET tHE nUMBER oN aN aLL rLG/aVT mEMBERSHIP bOARDS,\n                     oR oN oNE oF tHE bETA-tEST bOARDS!\n\n==========================================================================\n\n@endnode\n@node jOIN!!! "aND nOW tAKE tIME tO jOIN tHE sPACE pOWER !"\n  \n      _________   /\   _________ ________ _/\__ _______  _________\n_ _ _/         \_/  \_/         \_       \____/        \_         \_ _ _\n \ \\_    l_____/ oo \_    l_____/  l_____/   |    l____/    l_____// /\n     |    |____/      |    |   |    |    |    |    ___)_|    |\n     !    |    |  /\  !    |   !    |    !    !    ¦    !    |\n     l____     |      l____|   l____|    l____l____     l____|\n          \____| `---)   \       _ _ _/\__ _______ \____|\n           /              \       \ \\____|       \_ _ _    aVANTGARDE eHQ\n          /________________\          |   |   |   _// /      rELIGION eHQ  \n                                      |   |   |   |          \n                                      |   |   |   |         aMIGA&cONSOLE!\n        (º 2 nODEZ rINGDOWN º)        !   !   |   |         rUNNING /X4.xx\n                                      l___l___|___|         > aMIGA 2000 <\n      _________ _________ _________ _________ _________     gVP/030/40MHz!\n_ _ _/         \_        \_        \_        \_        \_ _ _\n \ \\_    |_____/   |    _/   |    _/   l_____/   l_____// /\n     l____     |    |____|         |    |    |    ___)_\n     |    !    |    |    !    |    |    |¯¯¯¯|    ¦    | aSK tHE eLITE fOR\n     l____     |    |    l____|    l____     l____     |   dA nUMBER aND\n          \____|    |         \____|    \____|    \____|     dA nUP!!!\n               l____|÷tC÷\n \n(º sYSOP: sHADOW mAN/aVT/rLG º cO-SYSOP`S: uLTRA / tERRORIST / tHE cROW º)\n@endnode\n','\n',char(10)),NULL,NULL,107691,6,0,NULL,NULL,NULL,'scan',1780048692);
INSERT INTO door_catalog VALUES('rlg_requ','RLG-REQU.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RLG-REQU.LHA',NULL,'XIM','______   __.       _____.',NULL,'iNNUENDO/rELIGION','RLG','====/  _   \=/  |======/  .__|=[ rELIGION ]= S M/\    __//\  |__.  /\  |_ | / \\/   \/ \\    | / \\  ! | >>pRESENTS<<',replace('     ______   __.       _____.                     \n====/  _   \=/  |======/  .__|=[ rELIGION ]=\nS M/\    __//\  |__.  /\  |_ |              \n  / \\/   \/ \\    | / \\  ! | >>pRESENTS<< \n /____\_  /____\___|/____\___|              \n========\/==================================\na rEALLY cOOL rEQUEST dOOR fOR /X aND s!X !!\n------- wRITTEN bY iNNUENDO/rELIGION -------\n============================================\n','\n',char(10)),'Request.guide',replace('@NODE MAIN "/1mi-Request V1.5 (AmigaGuide) Docs"\n\n[·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·]\n\n  ______________________________  ____:_________    ____:_______    ,______\n  \         \         /        / /    |        /   /    |       \___|___   \\n  _\____     \  _____/_       /\/_____|   ____/___/_____|        \     /    \\n /    |/    _/ ___/    \     /  \     |   \_      |     |         \   /     /\n/     /      \_         \   /    \    |     |     |     |         /  /     /\n\_____\_______/___      /_________\   |___________|     |________/  /_____/\n.=================\____/=====/________|========/________|====/_____/NoS!====.\n\n            bring you /1mi-Request V1.5 written by Innuendo/RLG\n\n                             @{"[ iNTRODUCTION ]"link Chap1}\n                             @{"[ REQUiREMENTS ]"link Chap2}\n                             @{"[ iNSTALLATION ]"link Chap3}\n                             @{"[  GREETINGS!  ]"link Chap4}\n                             @{"[   CALL NOW   ]"link Chap5}\n\n[·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·]\n\n@ENDNODE\n\n@NODE Chap1 "Introduction..."\n\n[·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·]\n\n                       This is /1mi-Request V1.5...\n                ...just another Request door for Express!\n                \n          Features:\n          - Write an EALL-Message in any conf (puah nothing exciting)\n          - Great design (That`s true!)\n          - Written in Rexx (hahahaha)\n          - Nothing to configure (argh)\n          - hmm..check out for the rest...\n\n[·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·]\n\n@ENDNODE\n\n@NODE Chap2 "Requirements..."\n\n[·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·]\n\n             Hah! Everyone can run it all you need to have is:\n\n          - SIGMA or Ami-Express\n          - Any Amiga from 500 - 4000\n            or you can run it on a Casio Calculator, in A4000-060\n            emulation mode, of course!\n          - Oh yes, and the Rexx crap (also installed) hehe!\n\n[·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·]\n\n@ENDNODE\n\n@NODE Chap3 "Installation..."\n\n[·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·]\n\nIf you have no Installation-Slave, then read this (if you are too lame\nto figure out)\n\n-> DO-IT-YOURSELF: Installing /1mi-Request! in 3 Steps! <-\n\n1)  Copy the file "Request.rexx" to "DOORS:Request/"\n2a) If you have Sigma-Express or /X 2.3x, load the file \n    "BBS:COMMANDS/BBS.cmd" into your Text-Editor and add this line:\n\n-- Cut here --\nREQ       RM001DOORS:REQUEST/REQUEST.rexx\n-- Cut here --\n\n2b) If you have Ami-Express 3.x+ then create a cool icon haha..\n\n3)  Jump into the file "DOORS:REQUEST/REQUEST.rexx" (which means you\n    should load it into your texteditor heh) and edit Line8:\n\nConfPath="Confs:Conf5"       /* Request shall be posted as an eall message!!! */\n\n    This is the Path to your Requests (or some other) conference where\n    the Request-Message will be posted!! Do not add a SLASH ("/") at\n    the end of the path...should be no problem!\n   \n                      That`s it for the installation!\n\n               Next version will DEFINITELY be written in C!!\n\n                   @{" CLICK HERE "link Use} to find out how to use it!\n\n[·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·]\n\n@ENDNODE\n\n@NODE Use "How to use it..."\n\n[·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·]\n\n   That shouldn`t be a problem for you, even my dog was able to request\n           some warez...just do what the door asks you to do...\n         hehe...if you are not able to use this door...BUY A DOG!\n\n[·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·]\n\n@ENDNODE\n\n@NODE Chap4 "Greetings...(oh yeah the best part of docwriting!)"\n\n[·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·]\n\n               Greetings to...hmm well these human beeings..\n\n - WaRLoCK/uTA/tUS/tUN/uNT     ich kommeeee\n - HiTMaN/uTA/tUS/tUN/uNT      hey die bulletins funken haha\n - [-The Addict/INDer]         hmm greets to machine\n - Murphy^Intercode            Die boesen Brueder\n - s!x                         PRUEGELKNABE!!! haha\n - Belgarath                   Cøøl C-Coding!\n - sIGMA sEVEN                 the COOOOOL Sigma-Express\n - Innuendo                    the best...\n\nSpecial Greetings to: \nMy Dog                      Thanks for telling me how to use this door!\n\nFuckings to:\nThe neighbour`s black cat   heheh \n\n[·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·]\n\n@ENDNODE\n\n@NODE Chap5 "Call these boards..."\n\n[·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·]\n\nGive these Religion Boards a Call...\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nAccess X                      RLG-UHQ +49-SooN\nRunner''s Point                RLG-WHQ +49-ASK\nBøøM-BBS 1nd                  RLG- HQ +49-0911-473601\nThe last outpost              RLG- HQ +49-ASK\nCarrier in Space              RLG-EHQ +49-ASK\nNo Carrier                    RLG-GHQ +49-ASK\nUnder Cover                   RLG- HQ +49-ASK\nDrive by Shootin''             RLG- HQ +49-ASK\nHomebase                      RLG- HQ +49-ASK\nLamer`s Inn                   RLG- HQ +49-ASK\nHall Of Fame                  RLG-Dist+49-ASK\n\nand my board, the @{">TERRA NOVA<"link Terra} BBS\n\n[·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·][·]\n\n@ENDNODE\n\n@NODE Terra "Terra Nova BBS..."\n\n     ______________________             ____________\n     \_____   _.     _____/_____________\______._   \  ____\n         /     |    ___/    \______._    /     l/  _/_/    \\n  .-----/      |_____________\     l/  _/_\____|     /      \------.\n  |     \______|              \____|     /     \____/ -s!x   \     `---.\n  |                                \____/          /__________\        |\n  |          ____________   ______/\             _____                 |\n  |          \_____._    \_/   ._/  \_____:_____/     \                |\n  |          /     l/     /    l/    \    |    /   |   \               |\n  |          \_____/     /\__________/\   :   /    _    \              |\n  |                \____/              \_____/     |_____\             |\n  |  rELIGION hQ!           UNT hQ!         /______|                   |\n  |                                                                    |\n  | --------- >>> Node 1 [ +49 - 702 - pRIV8! ] V32Terbo <<< --------- |\n  | --------- [ aM|Ga ] [ PeeCee ] [ Star Trek ] and more... --------- |\n  `--------------------------------------------------------------------''\n                      sYSTEM- aND nEWUSERPASSWORD nEEDED!\n\n@ENDNODE\n\n','\n',char(10)),NULL,NULL,29873,5,0,NULL,NULL,NULL,'scan',1780048692);
INSERT INTO door_catalog VALUES('rlx_do11','RLX-DO11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RLX-DO11.LHA',NULL,'XIM','ad-trash.exe',NULL,'EUPHORiA/WRD^RLX!','RLX','.    \______ \_____  / __/7___________    o |    /   __/  \ __ \/ __) | __ \  |  /    . |  _/     |   / \__/  |   | \__/     \',replace('     ________         ____                 \n.    \______ \_____  / __/7___________    o\n|    /   __/  \ __ \/ __) | __ \  |  /    .\n|  _/     |   / \__/  |   | \__/     \     \n|  \______|   \___/   l___j___/       \_   \n|         l_____/ \___j   nOc\____|____/   \n`-----------------------------------------.\n           ** DOORLiSTER V1.1 **          |\n        CODED BY EUPHORiA/WRD^RLX!        |\n  FAST C++ CODE FOR AMiXPRESS 2.XX & 3.XX |\n SHOWS THE USER A LiST OF AVAiLABLE DOORS |\n------------------------------------------''','\n',char(10)),'doorsv11.doc',replace('                        _             _\n              · ____/\_|¬\/\_______ _|¬\  ____________ _ __  ____/\ __ _\n              :/  ___/ |  \______  \ |  \/  _______   \ ___)/ ____//\n              /  __)_. |   \   ./  /_|   \  V  \  _\__/    |  V ¬\:\n        _ __ /   \   | :    \_ |__/ \_    \ :   \ \  ¬\    |  _   \\n            \\_______¦_______/ ¦ \___|____/_____/__\  _\___¦__|    \\n              ¦      :     `---''     :              \/     :  |____/\n              ¦pS!                                                \n              `--------- Brings You Today : DoorLister v1.0 beta\n\n\nSimply this door displays an list of all your available doors, and the\ncommands to run them.\n\n## INSTALLATION #############################################################\n\nGetting the door to run:\nSimply run this door as an normal amiexpress door, as methods of running doors\nvary between different versions of amiexpress that part was chosen not to be \nincluded. Just refer to your amiexpress documentation. The door is written \nin c++ and has been tested on amiexpress versions 2.34,2.39,3.9,3.20 and \n3.32 so there shouldn`t be any problem getting it to run. \n\nThe config file:\nThere should be a config file named ''doors.data'' that should be located\nin your s:. There`s a sample of the config file included in the pack,\nbut just to make sure you`ll get the hang of it i`ll explain it in the \ndoc to.\n\nIt could look something like this:\n*Sent                            ## The command to get it to run\n@Edit Your Private Sent-By Line  ## The description of the door!\n\nAnd you can have as many doors as you want in the file, just dont forget\nto place the config file in s:  (s:doors.data)\n\n## FILES INCLUDED IN THE ARCHIVE ############################################\n\nname						original filesize			description\n--------------------------------------------------------\ndoorsv11.exe    		13180							The compiled file to run\ndoorsv11.doc			2162							The documentation\ndoors.data				224							The config file\n\n## LOG OF VERSIONS ##########################################################\n\nv1.0					 Only released to members & beta-testers!\n						 Log writing added\nv1.1					 First public release\n','\n',char(10)),NULL,'auto-added',75638,12,0,NULL,NULL,'rlx_do11','scan',1780048692);
INSERT INTO door_catalog VALUES('rlx_li10','RLX-LI10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RLX-LI10.LHA','LogonInfo','XIM','LE-win5-96.exe',NULL,NULL,'RLX',':::::\      \   __/   __/ /   __/  |  /:::: :::::/  :\  /  __/    _/ /   __/      \:::: ::::/   |   \  | \   |   \/\ | \   .   \:::',replace('     __________________________________\n:::::\      \   __/   __/ /   __/  |  /::::\n:::::/  :\  /  __/    _/ /   __/      \::::\n::::/   |   \  | \   |   \/\ | \   .   \:::\n:::/____|____\____\__|______\___\__|____\::\n+==============[ PRESENTS! ]==============+\n  lOGONINFO v1.o - A New Kind of FrontEnd!\n Includes Logon Batch, Sysop in/out & More!\n            Written in 100% ASM!\n','\n',char(10)),'LogonInfo.guide',replace('@database lOGONINFO v1.o\n\nlOGON bATCH v1.o (1oo% ASM) - © 1994 by WHiZ/eNDLESS pIRACY/rEFLEX/tHERAPY\nAll Rights Are Reserved!\n\n@Remark $VER: lOGONINFO v1.0 (30.04.94)\n\n@node MAIN "lOGON bATCH v3.o Document In AmigaGuide Format"\n\n		____/\__ _/\______/\___/\_  _/\_____/\_/\__\n		\_____  \| ______   ___  |  | _____   |  _/\n 		C|  | _/| __)_  |  __|  |__| __)_ \_ _ _/\n 		r|     \| |   \ |  | |  |  \ |   \/  |  \___\n 		t|__|___\______\|__| |_____/______\__|_____/\n		=============-*( Presents )*-===============\n                    \n                               lOGONINFO v1.o\n\n                         @{"     Introduction      " Link Intro}\n                         @{"     Requirements      " Link Require}\n                         @{"     Installation      " Link Install}\n                         @{"     History           " Link History}\n                         @{"     Greetings...      " Link Greetz}\n\n@endnode\n@node Intro " Introduction"\n\nThis is very small (3372 Bytes) AmiExpress XiM Door with the\nfollowing features:\n\n- Displays the Nodenumber to which the User is Connected to.\n- Displays the Locked Baudrate of the Node.\n- Launches a Batch when a User Logs on, so your Logoff Batch\n  can be reduced to a very small size and will safe a lot of time.\n \n  Note:\n  Logon.Batch is executed with the RunBack command in your C: Dir\n  so you can have as much Utils as you want in your Batch File!\n\n- Displays if the Sysop is around or not.\n- Displays the Serial Device of the Node\n- Displays the Number of Nodes available.\n\nThis is how it looks like:\n--------------------------\n\n.---------------------------------------------------------------------------.\n| lOGONINFO v1.o (1oo% ASM) - © 1994 by WHiZ/eNDLESS pIRACY/rEFLEX/tHERAPY! |\n+-----------------------+-----------------------+---------------------------+\n| Connected to Node #1  | Locked at 115200 Baud | Launching Logon Batch ... |\n+-----------------------+-----------------------+---------------------------+\n|  Sysop is NOT Around! | DEV: duart.device     | NDZ: XXX                  |\n`-----------------------+-----------------------+---------------------------''\n\nHow this Util works:\n-------------------\n\nWhen a User Logs on this Util looks for the File "Logon.Batch" in your\nBBS: Dir:\n\n- If found, it''ll display "Launching Logon Batch" and executes the Batch.\n- If Not found, it''ll display "Logon Batch Not Found" and continues quietly.\n\nThen it checks if the chatflag is on or off.\n\n- If the Sysop is in, it''ll inform the User with the Message\n  "Sysop Can Be Paged", that the Sysop is available for Chatting.\n- If the Sysop is not around, it''ll display "Sysop is NOT Around!"\n\n\n                         @{"     Main Menu      " Link MAIN}\n\n@endnode\n@node Require " Requirements"\n\nAll you need to run this little Util is:\n\n- An Amiga, no matter which model.\n- Should work on Ami- or Sigma-Express version! (But only tested\n  on /X v3.37 & v3.38)\n- AEDoor.library v2.0+ by SiNTAX/WøT\n- RunBack Command in your C: Dir.\n- Logon.Batch in your BBS: Dir, protected with +s\n\nThats all...\n\n                         @{"     Main Menu      " Link MAIN}\n\n@endnode\n@node Install " Installation"\n\n- If you don''t have the AEDoor.library (v2.0+) by SiNTAX/WøT in your LIBS\n  dir already just copy the version included in this archive to your\n  LIBS Dir.\n\n- This little Door also requires the RunBack Command in your C: Dir.\n  If you don''t have this command just copy the version included in\n  this archive to your C: Dir.\n\n- This Door is executed via the FrontEnd.info icon. Either copy\n  the FrontEnd.info icon included in this archive to your\n  BBS:Commands/SYSCmd/ Dir or create a new FrontEnd.info icon with the\n  following Tooltypes:\n\n  LOCATION=DOORS:LogonInfo\n  TYPE=XIM\n  MULTINODE=YES\n  STACK=4096\n  ACCESS=001\n\n- Now create a Batch called BBS:Logon.Batch, and protect it with +s\n  for instance: Protect BBS:Logon.Batch +s\n \n                        That''s it folks ...\n\n  This Util has been tested for a couple of weeks without any crashs\n  or problems at all! Give my Board a Ring and see for yourself!\n\n  Thanks to Joker/ZZC & DEXter!/AFL for Beta-Testing!  \n\n  If you should find any Bugs or have any Suggestions, feel free to\n  contact me on PSYCHO TERMiNAL +1(914)682-1975 or via /XNet WHiZ@203001\n\n\n                         @{"     Main Menu      " Link MAIN}\n\n@endnode\n@Node History "History"\n\n  v1.0 - First Release\n\n@endnode\n@Node Greetz "Greetings"\n\n  JOKER/ZZC - PD Rulez!\n  THE CHAMP/XPR - Biste jetzt auch offline?\n  Freddy Krueger/GOD\n  The Fly/TRY - Upping Rulez!\n  Godhead/QTX - Thanx for the cool logo! Give me Ring!\n  Buster & Fuzz - Nix mehr mit callen oder was?\n  Dalai Lama/GOD - Great Utils m8!\n  EXoCET/ATX - 5x Credz Nuked!\n  Schwabenpower/ZZC - Bald biste Top Messywriter :)!\n  Red Alert - Netmail ruhlt!\n  BBC/MTN - Danke für deine Hilfe! Leider konnte ich den reply\n            nicht mehr lesen. Die Fastway wurde ja an dem Tag\n            gebusted :(\n  2-Cool/LSd - Thanx for your great help and time m8!\n  Sintax/WOT - Un grand merci pout ton aide! Great Library mec!\n  ScE/DTL - When are ya gonna release your Colly?\n  ErNeStO/RDC - Ich vermisse deine Megz :)\n  Foxx''n''Lynxx/ZZC - Schau mal wieder rein :)..Hab wieder ne Menge\n		     Fragen!\n  [«·cCs^eQx·»]/LGC - Thanx for your help m8s!\n  DEXter!/AFL - Sorry for all the Crashes :)\n  [- XSTAZ -] and JOC/ATX - You both know why :)\n\n  and of course to all eNDLESS pIRACY - rEFLEX - tHERAPY mEMBERS!\n\n\n                         @{"     Main Menu      " Link MAIN}\n@endnode\n','\n',char(10)),'{"LOCATION":"DOORS:LogonInfo","TYPE":"XIM","STACK":"4096","ACCESS":"001"}','auto-added',14110,5,0,NULL,NULL,'rlx_li10','scan',1780048692);
INSERT INTO door_catalog VALUES('rlx_move','RLX-MOVE.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RLX-MOVE.LHA','move','XIM','move',NULL,'THE','RLX','\_____  \| ______   ___  |  | _____   |   / C|  | _/| __)_  |  __|  |__| __)_ \_ _ _/ r|     \| |   \ |  | |  |  \ |   \/  |  \__',replace('____/\__ _/\______/\___/\_  _/\_____/\_/\__ \n\_____  \| ______   ___  |  | _____   |   / \n C|  | _/| __)_  |  __|  |__| __)_ \_ _ _/  \n r|     \| |   \ |  | |  |  \ |   \/  |  \__\n t|__|___\______\|__| |_____/______\__|_____\n=============-*( Presents )*-===============\nSLICK MOVE! .05 (C) 1994 REFLEX...........:\nTHIS IS THE ONE YOU''VE BEEN WAITING FOR!  :\nSOON TO BE A STANDARD! ONE OF A KIND!!!   :\nIF YOU ARE AN /X SYSOP, DONT BE STUPID!   :\nGRAB THIS AND INSTALL!! CODED BY THE      :\nONE AND ONLY BUGBYTE/RLX!! ANOTHER        :\n        SLICK UTILITY!!!                  ;\n','\n',char(10)),'MOVE.DOC',replace('\n\n            SLICK MOVE! 1.0   (C) 1994 REFLEX\n     Many lines of code typed late at night by:BUGBYTE/RLX\n     \n     These meaningless lines of bullshit \n     typed by that worthless asshole: THE MINSTREL/RLX\n\n\n1. Introduction...\n\n        Ever notice something about running an /X\nBBS? Files start to build up QUICKLY, and it seems\nNO ONE has the time to move files when they become too\nold to keep in the "new-files sections." When it finally\ncomes time to get those files offline, its can be such a bitch.\nThere has been NOTHING for /X Sysops to use, to makemoving\n files off-line easier... UNTIL NOW............\n        Get ready for a REVOLUTION!\n\n\n2. WHAT IT DOES..\n\n        Slick Mover will make running a BBS fun again..\nIt easilly moves files.. That is ALL it does.. Thats ALL its\nsuppose to do.. BUT, it does it in a PERFECT way. When you\nuse Slick Move, and give the required conference information, \nyou select where to move files to. This is specified in the \nconfiguration file.. You can have as many conferences as you \nlike, but also, there is an option for OFF-LINE, for when you\nget ready to back those babies up.. After you get that out of \nthe way, you are asked for the file names.. THIS IS WHERE IT GETS\nFUN... The special "DATE" mode is great! \n\n\n3. The DATE MODE...\n\n        When you are asked to enter the filenames, you may\ngo into DATE MODE, by simply typing "DATE" instead of a filename.\nThe door will kick into date mode, letting you move ALL files\nthat are older than specified length, offline.. AWESOME.\nIf you enter "30 d", it will move all files older than 30 days\noffline.. It will remove them from the file list in the conf,\nand will create a new (or update an existing) dir-list in the \noff-line dir.. This does not have to be an existing conference, \nit may just be like DH0:backupdir, or dh1:offline, or whatever.\nThis way, you can move all files (say after 30 days) to an off-line\ndir, and be able to backup that off-line dir, WITH a copy of the\nlist of off-line files in it.. \n        If you wish, you can have the mover move the files to an actual\n"older-stuff" conference, and it will just move the files into\nthe proper directory, and update the conference''s list.. Smooth,\nperfect, to the point.. Slick Move should be a STANDARD! This\nis the door that they should INCLUDE when you buy /X.\n        Now YOU may finally rest! You and your SubOps will never\nhave to move files one at a time again!.. Thank us later...\n\n\n4. INSTALLATION...\n\n        Installation could NOT be any easier for this door.\nThere is a command file, to be put into DOORS:  And there is\na config file that is to be edited, and put into S:  And\nfinally, there is a move.info to be put into BBS:Commands/BBSCMD.\nThats ALL there is to it.. NOW its time to edit the CONFIG..\nThis is VERY easy.. All you have to do is, edit the existing\nconfig file, and put the location of each of your conferences,\nwhere you see the supplied.. Then the last line is where you\nspecify your off-line path..Then you are ready to ROLL!\n        If you cannot get this door to run (under /X 3.++),\nyou must be retarded! Its about the EASIEST thing you can do!\n\n\n5. Where can I go for support on this, and other GREAT SLICK UTILS?\n\n        Well, we can be reached on the REFLEX World Headquarters,\nLOST IN TIME BBS- 608-755-1335.. I am the Sysop, and if your not\nTOO lame, I may be able to let ya on.. hehehe\n\n6. TIME FOR GREETS!!\n\nSAMIR/TRZ.............................My Hamster misses you! ;)\nBUGBYTE...............................Dont make me cry! hehehehe\nCRYPTH... ............................Dont be lame! Call me!\nTerrorizer............................You really need some cards!\n\nI am too tired to do anymore greets! FUCK YOU ALL! hehehehe\n\n        And PLEASE ALWAYS REMEMBER.....\n\n                "GOD IS PERFECT\n                 MAN IS NOT\n                 MAN MAKES BOOZE\n                 GOD MAKES POT!"\n\n                Support your local POT SMOKER! :)\n\n«««REFLEX''94»»» TAKING THE SCENE BY STORM!\n','\n',char(10)),NULL,'auto-added',74131,8,0,NULL,NULL,'rlx_move','scan',1780048692);
INSERT INTO door_catalog VALUES('rlx_sm10','RLX-SM10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RLX-SM10.LHA',NULL,'XIM','____/\__ _/\______/\___/\_  _/\_____/\_/\__',NULL,'A','RLX','\_____  \| ______   ___  |  | _____   |   / C|  | _/| __)_  |  __|  |__| __)_ \_ _ _/ r|     \| |   \ |  | |  |  \ |   \/  |  \__',replace('____/\__ _/\______/\___/\_  _/\_____/\_/\__ \n\_____  \| ______   ___  |  | _____   |   / \n C|  | _/| __)_  |  __|  |__| __)_ \_ _ _/  \n r|     \| |   \ |  | |  |  \ |   \/  |  \__\n t|__|___\______\|__| |_____/______\__|_____\n=============-*( Presents )*-===============\nSLICK MOVE! 1.0 (C) 1994 REFLEX...........:\nTHIS IS THE ONE YOU''VE BEEN WAITING FOR!  :\nSOON TO BE A STANDARD! ONE OF A KIND!!!   :\n******THIS IS THE REAL RELEASE******      |\n******NOT THE BETA THAT WAS   ******      :\n******LAMELY SPREAD BY A LAME ******      :\n******EX-REFLEX MEMBER!! 100% ******      ;\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯ \n','\n',char(10)),'MOVE.DOC',replace('\n\n            SLICK MOVE! 1.0   (C) 1994 REFLEX\n     Many lines of code typed late at night by:BUGBYTE/RLX\n     \n     These meaningless lines of bullshit \n     typed by that worthless asshole: THE MINSTREL/RLX\n\n\n1. Introduction...\n\n        Ever notice something about running an /X\nBBS? Files start to build up QUICKLY, and it seems\nNO ONE has the time to move files when they become too\nold to keep in the "new-files sections." When it finally\ncomes time to get those files offline, its can be such a bitch.\nThere has been NOTHING for /X Sysops to use, to makemoving\n files off-line easier... UNTIL NOW............\n        Get ready for a REVOLUTION!\n\n\n2. WHAT IT DOES..\n\n        Slick Mover will make running a BBS fun again..\nIt easilly moves files.. That is ALL it does.. Thats ALL its\nsuppose to do.. BUT, it does it in a PERFECT way. When you\nuse Slick Move, and give the required conference information, \nyou select where to move files to. This is specified in the \nconfiguration file.. You can have as many conferences as you \nlike, but also, there is an option for OFF-LINE, for when you\nget ready to back those babies up.. After you get that out of \nthe way, you are asked for the file names.. THIS IS WHERE IT GETS\nFUN... The special "DATE" mode is great! \n\n\n3. The DATE MODE...\n\n        When you are asked to enter the filenames, you may\ngo into DATE MODE, by simply typing "DATE" instead of a filename.\nThe door will kick into date mode, letting you move ALL files\nthat are older than specified length, offline.. AWESOME.\nIf you enter "30 d", it will move all files older than 30 days\noffline.. It will remove them from the file list in the conf,\nand will create a new (or update an existing) dir-list in the \noff-line dir.. This does not have to be an existing conference, \nit may just be like DH0:backupdir, or dh1:offline, or whatever.\nThis way, you can move all files (say after 30 days) to an off-line\ndir, and be able to backup that off-line dir, WITH a copy of the\nlist of off-line files in it.. \n        If you wish, you can have the mover move the files to an actual\n"older-stuff" conference, and it will just move the files into\nthe proper directory, and update the conference''s list..\nAND, you get the option to keep the origional file date, or use the\nnew date that the file was moved.  \n\nSmooth, perfect, to the point.. Slick Move should be a STANDARD! This\nis the door that they should INCLUDE when you buy /X.\n        Now YOU may finally rest! You and your SubOps will never\nhave to move files one at a time again!.. Thank us later...\n\n\n4. NEW COOL FEATURES...\n\n        FULL WILDCARD SUPPORT!\n        MULTIPLE FILE MOVE BY FILE NAME, OR DATE\n        REALLY GREAT COLORS!\n        FULL HOLD, UPLOAD DIR SUPPORT!\n        (did I mention really great colors?)\n        REALLY GREAT DOCS!\n\n\n5. INSTALLATION...\n\n        Installation could NOT be any easier for this door.\nThere is a command file, to be put into DOORS:  And there is\na config file that is to be edited, and put into S:  And\nfinally, there is a move.info to be put into BBS:Commands/BBSCMD.\nThats ALL there is to it.. NOW its time to edit the CONFIG..\nThis is VERY easy.. All you have to do is, edit the existing\nconfig file, and put the location of each of your conferences,\nwhere you see the supplied.. Then the last line is where you\nspecify your off-line path..Then you are ready to ROLL!\n        If you cannot get this door to run (under /X 3.++),\nyou must be retarded! Its about the EASIEST thing you can do!\n\n\n5. Where can I go for support on this, and other GREAT SLICK UTILS?\n\n        Well, we can be reached on the REFLEX World Headquarters,\nLOST IN TIME BBS- 608-756-2431.. I am the Sysop, and if your not\nTOO lame, I may be able to let ya on.. hehehe\n\n6. TIME FOR GREETS!!\n\nSAMIR/TRZ.............................My Hamster misses you! ;)\nBUGBYTE...............................Dont make me cry! hehehehe\nCRYPTH... ............................Dont be lame! Call me!\nTerrorizer............................You really need some cards!\n\nI am too tired to do anymore greets! FUCK YOU ALL! hehehehe\n\n        And PLEASE ALWAYS REMEMBER.....\n\n                "GOD IS PERFECT\n                 MAN IS NOT\n                 MAN MAKES BOOZE\n                 GOD MAKES POT!"\n\n                Support your local POT SMOKER! :)\n\n«««REFLEX''94»»» TAKING THE SCENE BY STORM!\n','\n',char(10)),NULL,NULL,24861,4,0,NULL,NULL,NULL,'scan',1780048692);
INSERT INTO door_catalog VALUES('rlx_sp15','RLX-SP15.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RLX-SP15.LHA',NULL,'XIM','____/\__ _/\______/\___/\_  _/\_____/\_/\__',NULL,NULL,'RLX','\_____  \| ______   ___  |  | _____   |   / C|  | _/| __)_  |  __|  |__| __)_ \_ _ _/ r|     \| |   \ |  | |  |  \ |   \/  |  \__',replace('____/\__ _/\______/\___/\_  _/\_____/\_/\__\n\_____  \| ______   ___  |  | _____   |   /\n C|  | _/| __)_  |  __|  |__| __)_ \_ _ _/\n r|     \| |   \ |  | |  |  \ |   \/  |  \__\n t|__|___\______\|__| |_____/______\__|____/\n=============-*( Presents )*-===============\n==  Simple Page V 1.5 For /X 2.xx & 3.xx  ==\n','\n',char(10)),'SPage.Doc',replace('    _______                   __________         ______  ________\n____¡     ø\__________________¡ø       / ________|ø    \_\     ø¡_______\n\     ____   /   _____   /  ___       /_ \       _____   /\     |_     /\n \____¡ _/  /____¡  _/  /___¡ø¡      / ø| \______¡  _/  /  \___ !/____/\n   /   ____/_  /   ____/_  /  |     /   |____  /   ____/_  __/  __ \__\n  /   __    ø\/    ¡    ø\/   l____/    ¡   ø\/    ¡    ø\/ø    ¡    ø\\n /     ¡      \    |      \ ____¡/      |     \    |      \     |      \\n/      |       \  _!       \   ¡/       !      \  _!       \    |       \\n\______!        \___        \__!\_______        \___        \___|        \\n       |         \ l__       \         /_________\ ¡         \  l______Crt\\n       l__________\   l______/                     l_________/\n\n                    Gives You Today : Simple Page V 1.5\n============================================================================\n \n      A Simple Pager For The Ami-Express BBS Sytems V 2.xx and 3.xx\n                  It Should Work Fine On S-Express Too...\n \nTo Install It Copy The Files SPage.Rexx And Spage.Doc Into The Directory\n \nDoors:SPage/ ... For /X 3.xx Copy The File O.Info Into Your BBS.CMD Dir...\n                 For /X 2.xx Add This To Your BBS.CMD File...\n \n \n-- cut --\n*O        RM010Doors:Spage/Spage.Rexx\n-- cut --\n  \n \nIn this version you need to do a little bit of configuration...\nIn the .Rexx file you''ll see a line\n \n\n-- cut --\nOkre = 200\n-- cut --\n \n \nChange the value of okre to your override chat level... I''ve found\nno way yet to retrieve this from /X so you''ll have to do it.. Sorry\nfor this inconveniance..\n(Fans of ''Reginald'' aka ''Geert Hoste'' will recognize this "yell" from his\nsong "Heyenoeist!" (om effe hallo aan de vlamingen te zeggen !)\n \nOki That''s It.. Quick Hy''s To My Bud''s EveryWhere...\n \n===========================================================================\n \nProgram History :\n \n   V 1.0  First release\n   V 1.1  Removed some leftovers from the beta\n   V 1.2  Added callerslog writing\n   V 1.3  Removed it again cuz it completely would fuck up your BBS\n   V 1.4  Altered the screen layout a bit\n   V 1.5  Added an override-chat level           -- Release --\n \n','\n',char(10)),NULL,NULL,35230,13,0,NULL,NULL,NULL,'scan',1780048692);
INSERT INTO door_catalog VALUES('rlx_sp16','RLX-SP16.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RLX-SP16.LHA',NULL,'XIM','____/\__ _/\______/\___/\_  _/\_____/\_/\__',NULL,NULL,'RLX','\_____  \| ______   ___  |  | _____   |   / C|  | _/| __)_  |  __|  |__| __)_ \_ _ _/ r|     \| |   \ |  | |  |  \ |   \/  |  \__',replace('____/\__ _/\______/\___/\_  _/\_____/\_/\__\n\_____  \| ______   ___  |  | _____   |   /\n C|  | _/| __)_  |  __|  |__| __)_ \_ _ _/\n r|     \| |   \ |  | |  |  \ |   \/  |  \__\n t|__|___\______\|__| |_____/______\__|____/\n-============-*( Presents )*-==============-\n[]  Simple Page V 1.6 For /X 2.xx & 3.xx  []\n','\n',char(10)),'SPage.Doc',replace('    _______                   __________         ______  ________\n____¡     ø\__________________¡ø       / ________|ø    \_\     ø¡_______\n\     ____   /   _____   /  ___       /_ \       _____   /\     |_     /\n \____¡ _/  /____¡  _/  /___¡ø¡      / ø| \______¡  _/  /  \___ !/____/\n   /   ____/_  /   ____/_  /  |     /   |____  /   ____/_  __/  __ \__\n  /   __    ø\/    ¡    ø\/   l____/    ¡   ø\/    ¡    ø\/ø    ¡    ø\\n /     ¡      \    |      \ ____¡/      |     \    |      \     |      \\n/      |       \  _!       \   ¡/       !      \  _!       \    |       \\n\______!        \___        \__!\_______        \___        \___|        \\n       |         \ l__       \         /_________\ ¡         \  l______Crt\\n       l__________\   l______/                     l_________/\n\n                    Gives You Today : Simple Page V 1.6\n\n     A Simple Pager For The Ami-Express BBS Sytems V 2.xx and 3.xx\n                  It Should Work Fine On S-Express Too...\n\nTo Install It Copy The Files SPage.Rexx And Spage.Doc Into The Directory\nDoors:SPage/ ... For /X 3.xx Copy The File O.Info Into Your BBS.CMD Dir...\n              For /X 2.xx Add This To Your BBS.CMD File...\n-- cut --\n*O        RM010Doors:Spage/Spage.Rexx\n-- cut --\n\n** NOTICE **\n\nSimple Page Is PostCardWare now !\nIf you use it, jou must send a postcard of the area you''re living in..\nSend them to :\n\nSmets P.\nWeldadigheidsstraat 45\nB-3000 Leuven\nBelgium\n\nOki That''s It.. Quick Hy''s To My Bud''s EveryWhere...\n\nProgram History :\n   V 1.0  First release\n   V 1.1  Removed some leftovers from the beta\n   V 1.2  Added callerslog writing\n   V 1.3  Removed it again cuz it completely would fuck up your BBS\n   V 1.4  Altered the screen layout a bit\n   V 1.5  Added an override-chat level           -- Release --\n   V 1.6  Removed the override-chat level because it was too buggy...\n          Now you can ALWAYS enter a chat reason\n          Callerslog-adding really works now\n          SPage is PostCardWare now              -- Release --\n\n\n','\n',char(10)),NULL,NULL,3877,2,0,NULL,NULL,NULL,'scan',1780048692);
