INSERT INTO door_catalog VALUES('rlx_xmas','RLX-XMAS.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RLX-XMAS.LHA',NULL,'XIM','_.____ ______  .     .   _ _______./\____',NULL,'C/\TEYE','RLX','_.____ ___    \ :     ._______     |     /. .c  ___ __/ ___/_¦     :    _/ \__  :  __/ . .r_:     __     /|     |    \ _/   ___   \_:',replace('  _.____ ______  .     .   _ _______./\____\n _.____ ___    \ :     ._______     |     /.\n.c  ___ __/ ___/_¦     :    _/ \__  :  __/ .\n.r_:     __     /|     |    \ _/   ___   \_:\n:t ¦______/_____\|___________\\_____¦_____/:\n`-refLex--------------------------preSents-''\n->  X-MASPAGER v1.0 by C/\TEYE of REFLEX  <-\n','\n',char(10)),'X-MASPAGE.DOC',replace('\n\n\n\n                                                              ____\n   _ _ __________________________________. ________________  /   /\n    \\\\______    /____    /\__  _____/  | \______    /\   \/   /\n        / \    __/ \______/_./   ___)    |__/_\______/_.\_    _/\n      _/   \    \    /_     |     ¦    __/    | /_     |/      \_ _ _\n   dZG\_____\    \__________|_____:___________|________|   /\___////\n «-----------\____/-----------------------------------/___/------------»\n\n\n\n                      P R E S E N T S  :  X-MASPAGE\n                     \n\n           X-MASPAGE is page-door from AmiExpress written in C.\n           And this is public domain, use it as long as you want.\n           I hate the built in pager in AmiExpress. Joe has to\n           do something with it soon!\n           I don''t think I have to explain how to install this\n           if you don''t know how to do it, you not deserve to\n           run it.\n\n                    X-MASPAGE.XIM      9400 bytes\n\n                Call InsideOut if you have another version.\n\n    Features:\n              * Fast\n              * Good looking\n              * Can add your own logo\n              * Comment the callerslog even if the CHAT-flag is turned off\n              * And many more...\n\n            Reflex needs more talant members, call InsideOut and get\n            more information about it!\n\n\n\n\nGreetz:\n        Bionic, Desecrator, Terrorizer,  AmigaSpirit, Vinzi, Karma,\n        Aquarius, Double,  Biztro, Dalamar, Zcandaler, Borre, Pete,\n        AXL, The Silencer, Psychlop, Vilieus, Reactor, Neuromancer,\n        Nightshade,  Zanok, Viper, Cruger,  Lionheart, Nero, Taccy,\n        Eazy-e, Wild-Child, Lightspeed, Slobo and Whale, Mr Saint,\n        Agamemnon, Cardiel... And the rest I know..\n\n\n        You can call InisdeOut if you want me something or why not\n      write me an e-mail. It''s popular now a days, [email removed]\n\n\n                        r   E   F   L   E   x  '' 9 5\n                        ~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                    - rEFLEx bOARDs aROUNd tHe wORLd ! -\n\n            InsideOut node #1 >: +46-(0)346-58697   28.8 bps\n            InsideOut node #2 >: +46-(0)346-59245   16.8 bps\n        Assembly Hall node #1 >: +46-(0)44-240816   21.6 bps\n        Global Effect node #1 >: +46-(0)510-62682   16.8 bps\n    Lost in time node #1 - #2 >: +1-608-755-1335    28.8 Ringdown\n       Dark moon node #1 - #2 >: +1-203-445-0113    21.6 Ringdown\n    Wearz deport node #1 - #4 >: +1-305-819-9925    28.8 Ringdown\n   Liquid assets node #1 - #2 >: +1-203-822-6225    21.6 Ringdown\n           Psycho Terminal #1 >: +49-PRIVATE!       16.8 bps\n             Dislexia node #1 >: +32-8971-6488      28.8 bps\n','\n',char(10)),NULL,NULL,9326,3,0,NULL,NULL,NULL,'scan',1780048692);
INSERT INTO door_catalog VALUES('rlx_fp10','RLX_FP10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RLX_FP10.LHA','FilePather','XIM','FilePather','1.0','Mitnick/.</RLX','RLX','to add/strip BBSADS!! - Creates a history file in an archive. - Strip adds from archives and textfiles! - Both BBS & User',replace('FilePather v1.0 by Mitnick/.</RLX - New way\nto add/strip BBSADS!! - Creates a history\nfile in an archive. - Strip adds from\narchives and textfiles! - Both BBS & User\nmode! Easy installation. - Written in 100%\nAssembler! - Requires OS2+\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                                                .------''\n             `------------------------------------------------''\n','\n',char(10)),NULL,'auto-added',25147,7,0,NULL,NULL,'rlx_fp10','scan',1780048692);
INSERT INTO door_catalog VALUES('rmc_mail','RMC-MAIL.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RMC-MAIL.LHA','Q5[aiD','XIM','Q5[aiD',NULL,NULL,'RMC','/ __  /  /  _ \  / __ \   /  ___\ /     /  /  _/  \/  _/  \ /  / /  /\  \ /   \       \    \\  \____',replace('    ______   ____    ____     _____\n   / __  /  /  _ \  / __ \   /  ___\\n  /     /  /  _/  \/  _/  \ /  /\n /  /\  \ /   \       \    \\  \____\n \__\ \__\\_______/\_______/ \_____/\n---+-------=-=-=-=-=-=-=-=-------+---\n<            Network BBS            >\n---+-------=-=-=-=-=-=-=-=-------+---\n/X-NetMail system (c)Equinox/Fortran5\n-------------------------------------\nNEW SCRIPT includes hotkeyed menus and\n[28.8]XOo. lICKed fROM trASH YarD .oOX[28.8]\n','\n',char(10)),'NETMAIL.GUIDE',replace('@database 002a9828-1\n@master DH1:PC/THE_MAG\n@$VER: 1.0\n@author ""\n@(c) ""\n@remark Created with Heddley v1.1 (c) Edd Dumbill 1994\n\n@node "Main" "R/\/\C MaG - 21:34 - 11-05-95"\n@next "Document_1"\n@prev "Document_0"\n\nOrigIonAl ScrIpTs:- EquinOx / The SilEnCEr\n\nGuIdEd By:- BiG H!\n\nThE AmI-x-MaIl DoOr ----\n\nupGraDeD By:- ReAl McCoY\n\n\n  KeEp ThE nEtWoRk AlIvE - dO sUmMiT fOr Us! - TrAdE - dIsTrIbUtE - bE kEwL!\n\n                                RMC NeTwOrK\n\n         @{"CHANGES" link "Document_0" 0}        @{"EXTRA COMMANDS" link "Document_3" 0}\n         @{"USAGE" link "Document_1" 0}          @{"INCLUDED FILES" link "Document_4" 0}\n         @{"COMMANDS" link "Document_2" 0}       @{"INSTALLATION" link "Document_5" 0}\n@endnode\n\n@node "Document_0" "Document_0"\nOnce I had installed the origional scripts of /XNetmail and started to use\nthem regulary, I found several bad points that needed to be changed:\n\nThe origional script (u.info) would not tell you what your serial\nnumber was, and therefor you could forget it! A bit of a pain having\nto enter your serial number in, especially with the chances of your\nserial being the same on different boards running at 1%!\n\nThis had been changed and the serial number is automatically entered\nand the system asks you for your personal /XNetMail password which is\nused globally throughout /XNetMail.\n\nIn the origional register script, it allowed users to start to use\n/Xnetmail if they were not registerd. It also allowed users to join\nthe /XNetMail system more than once, thus wasting serial numbers.\n\nJoining /XNetMail allowed users to use a different handle which could have\nbeen confusing for other users! This has been changed and now takes\nthe users name as the register name for /XNetMail, the system also\nasks for the users /XNetMail global password, and this is the only\ntime the password is shown to the user! Also, the new system\nwill not allow users to join /XNetMail more than once, and checks when\nthe system starts up wheather a user is a member or not. If not,\nautomatically joins the registration process, otherwise continues with the\nprogram.\n\nThere was no script to be able to show all the users who had joined\n/XnetMail. This has been added and shows the users serial number, with\nthe allocated user next to it. This information is updated everytime a new\nuser registers with /XNetMail.\n\nThere was no help file available to new users. In this version, the\nhelp file is very small, basically showing the origional small.dox file that\ncame with the origional archive!\n@endnode\n\n@node "Document_1" "Document_1"\nUsing /XNetMail has now been made even simpler by the fact that all the\norigional scripts have been "blended" into 1 script, and a "hotkeyed" menu\nsystem is now in operation.\n\nUsers who have not registered with /XNetMail are now detected automatically,\nand if they are not members, will execute the appropiate script to let then\njoin.\n\nWhen a registered user packs his mail to download, he is asked if he would\nlike to upload mail after file transfer has been completed, this is a change\nfrom the origional, and can be helpfull if users forget wheather they have\nuploaded mail  or not!! <like me!> After Xfer of packed mail has been\ncompleted, the upload routine is automatically activated.\n\nLinking mail is much easier now, and the command is not even listed in the\nmenu options. Linking uploaded mail to the message base is now done straight\nafter the system recieves the uploaded lha file from the registered user. \n\nIn the case of all options, except [E]nter mail, the user is asked for his\npersonal /XNetMail password, which must be entered correctly, otherwise the\nsystem will not continue with that routine.\n@endnode\n\n@node "Document_2" "Document_2"\n\n        E        Enter a message to other users via /XNetMail\n        -----------------------------------------------------\n\nEntering mail to the /XNetMail system is very easy. All you have to do\nis select option E and enter the users name at the prompt. As the\n/XNetMail system does not directly use the internal /X msgbase\nsystem, it does not check weather a user exists on your system. This\nis a must otherwise you can not send mail to users on another board!\nAfter the user has been entered, you have to enter a subject, now the\noption is to abort the enter mail command, just hit return to leave a\nblank line, this will prompt you to the pause; then the main menu.\n\n        P        Packing mail to download via Zmodem\n        --------------------------------------------\n\nPacking mail can be a curious thing, but this is one of the most\nimportant commands in /XNetMail. This command packs all the mail waiting to go\nout. Firstly it asks you to enter your serial number or enter the\ncommand [A].\n\nEntering the serial number will remember where the last pack was made\nand wont duplicate messages it packs. Entering the letter [A] will\npack all the mail in the message base from message number 1, which if\nthere is a lot of mail in there, could take sometime!\n\nAfter you have selected where to start to pack your mail from, it\nthen prompts you for your personal /XNetMail password. This should be\nentered correctly otherwise the system willl inform you an incorrect password\nhas been entered, and will signal the main menu. Continueing on if the\ncorrect password is entered, will give you a welcome message and ask\nyou if you wish to upload mail after you have downloaded the packed mail. \n\nIt then trotts off and starts to pack the mail from message 1 or where\nit was last packed to, as stated above. Once the mail has been packed a prompt\nasks you to hit any key to start Xfer.\n\n(If you pack mail locally to upload to other bbs`s, the LHA file is\ntransfered to directory T:, and remains there until deleted!)\n\nIf you chose to upload mail after downloading the system selects the\nUpload command, which is detailed below.\n\n                 U        Upload mail to message base\n                 ------------------------------------\n\nWhen you select to upload mail with [U], you are presented with your\nserial number and your logon name. You are then prompted to enter your\npersonal password, and an incorrect passsword will result in the\nsystem returning you to the main menu. Presuming you have\nentered the correct password, the system will then activate the upload\nrequestor window, and you should select the .lha file, containing the\npacked mail, to the /XNetMail system. After file transfer is\ncompleted, it will automatically link the uploaded mail to the\n/XNetMail`s message base, and then return you to the main menu.\n@endnode\n\n@node "Document_3" "Document_3"\nCommands:-\n----------\n\n            O	     Page the sysop\n            -----------------------                  \nPages the sysop using the installed pager\n\n\n            H        Help on using /XNetMail \n            -------------------------------- \nShows the file DOORS:NETMAIL/HELP.TXT file.\n\n            R        Read mail in the /XNetMail message base\n            -------------------------------------------------\nThis uses the internal mail reader of Ami-Express and offers you the\nnormal prompt to read unread mail to you, or goto any particular message\netc..\n\n            A        List registered users of /XNetMail\n            -------------------------------------------\nThis command is a bit of a chuck in and will showm the file\nDOORS:NETMAIL/NAMES.TXT. This is updated when a new user registers\nwith /XNetMail.\n\n            Q        Quit back to the BBS \n            -----------------------------\nThis command leaves /XNetMail and returns to the BBS, restoring all basic\ncommand functions.\n@endnode\n\n@node "Document_4" "Document_4"\nThe Included files:-\n--------------------\n\n  NETMAIL.REXX        the main /XNetMail program and must be located in\n                      DOORS:NETMAIL/\n\n  NAMES.TXT           the user list and must be located in DOORS:NETMAIL/\n\n  HELP.TXT            this is the help file and must be located in\n                      DOORS:NETMAIL/\n\n  MENU.TXT            this is the menu, you may customise it to your own\n                      preferences, location musy be DOORS:NETMAIL/\n\n  NETMAIL.INFO        This icon should be located in the\n                      BBS:COMMANDS/BBSCMD/ directory, and should have \n                      the following tooltypes:\n\n                          TYPE=AIM\n                          LOCATION=DOORS:NETMAIL/NETMAIL.REXX\n                          MULTINODE=NO\n                          STACK=4096\n                          NAME=R/\\C /XNETMAIL\n\nThe door can be started with ~CC_NETMAIL in a bullscript etc.... or by\nentering the command NETMAIL at the BBS prompt!\n@endnode\n\n@node "Document_5" "Document_5"\nTo use /XNetMail to its fullest, you should make a new conference and name\nit:\n\n                   AMI-XNETMAIL  in the confconfig.info icon\n\n          (conference name very important!)\n\n\nFaliure to do this will not allow /Xnetmail to run!\n\n(This saftey procedure has been included so users do not send /XNetMail to\nany conference on your bbs, and only to the /XNetMail confernece!)\n\n\nI think that is all the information available I can give you, and I hope you\nenjoy using /XNetMail as much as we all have done so far!\n\nAny comments / bug reports, please do not hesitate in contacting Real McCoy at\nRMC \//HeadQuarters, or just leave me mail on /XNet !! hehehe :-)\n\n---------------------------------------------------------------------------\nThanx go out to Silencer / Equinox for the origional scripts for /Xnetmail!\nand all copyrights remian with them, not Real McCoy / RMC Networks!\n---------------------------------------------------------------------------\n\nHave fun , speak soon: ReAl McCoy >>> RMC BBS on 0 (44) 1206 764533\n@endnode\n\n','\n',char(10)),'{"TYPE":"AIM","LOCATION":"DOORS:NETMAIL/NETMAIL.REXX","STACK":"4096"}','auto-added',21880,6,0,NULL,NULL,'rmc_mail','scan',1780048692);
INSERT INTO door_catalog VALUES('rmc_who3','RMC-WHO3.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RMC-WHO3.LHA','TextObj','XIM','ObjText',NULL,NULL,'RMC','|.  __ ____. _ Y _  |_\        \ | \\\_    | \\\ /// |      _   / |    |    |    Y    |      /__/',replace('      .______________ ____. _________\n      |.  __ ____. _ Y _  |_\        \\n      | \\\_    | \\\ /// |      _   /\n      |    |    |    Y    |      /__/\n      |::  |    |::  |    |::   /   |\n      |:::.|    |:::.|    |:::.     |\n `----|    |----|    |---------''\n------`----'' tG0`----''-T!-------- --- -\nUltimate WHO & FrontEnd door /X 4.x 100%FIX!\nEspecially kewl for Parnetted Systems, shows\nfull information on all nodes. (NET: etc...)\n-- ------ -------------- -    -------- --- -\n','\n',char(10)),'DOCS.TXT',replace('	    Quick dox for the WHO and FRONTEND door. (c)1996 R/\\C\n	   --------------------------------------------------------\n\nOk, Well, I suppose you are asking why I have written another WHO door?\n\nWell, if you are like me, and have more than 1 node, and run the other node(s)\non another machine, parnetted together, most of the WHO doors don`t actually\nwork!! hehe :( Bummer there! \n\nWell, this WHO door and the FRONTEND door, supplied in the archive \nactually read the ENV:STATS@x file, therefore being able to give you more\naccurate WHO information.\n\nStep 1:\n\nPut somewhere in one of the machines a new assign for ENV. Prefereably in the \nBBS-STARTUP sequence, but after the main S:STARTUP-SEQUENCE has done it`s stuf!\n\n    			  ASSIGN ENV: NET:RAM/ENV/\n\n(this is what i have on mine!)\n\nNext copy the RMCDOORS/xxx files to the DOORS: directory, and the other files\nto their correct homes! Easy! \n\n\nNow, in the WHO.INFO, and FRONTEND.INFO (doors: icon) there should be 1 tooltype\nnamley:\n\n			  NODES=x\n\nWhere x is, enter the amount of nodes your system is running! Mine says...\n\n			  NODES=3\n\nNow thats it, enjoy your new WHO and FRONTEND doors, and any complaints keep em\nto yaself!! hehe :-)\n\n\nBetter dox than NVX, hey Stoo? hehehe,... :-)\n\n-----------------------------------------------------------------------------\nR/\\C doors rule! (c) 1996 Real McCoy, R/\\C \//HQ - (+44) 1206 764533/765569\n-----------------------------------------------------------------------------\n\n\n\nP.S. REXX is SLOW and SHIT, so if anyone wants to convert these doors to C or \nbetter, they are welcome to, although, all Copyrights have to be left intact!\n\nP.P.S. (it`s all i can program in!! :-( )\n\n','\n',char(10)),NULL,'auto-added',14221,1,0,NULL,NULL,'rmc_who3','scan',1780048692);
INSERT INTO door_catalog VALUES('rmd_oans','RMD-OANS.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RMD-OANS.LHA','oNYXaNSI','XIM','_______  ________________________________',NULL,'FoX/Remedy^Aspect^Aliengroup','RMD','\______\/\_____________\___________\__\__\ \_____ \/ _________   / _______   /  /  / / /    _//____/  / /  / ____/  / //__  //',replace(' _______  ________________________________  \n \______\/\_____________\___________\__\__\ \n  \_____ \/ _________   / _______   /  /  / \n / /    _//____/  / /  / ____/  / //__  //  \n \/__/  /___  /__/_/ //___  /___ ./___  /   \n   \/__/    \/   \/__/    \/    \/    \/Sk!n\noNYxaNSi 1.0 by FoX/Remedy^Aspect^Aliengroup\n Replaces /X Ansi-Question with User-Config\n','\n',char(10)),'oNYXaNSI.doc',replace('.===========================================================================.\n|                   oNYXaNSI vERSION 1.0 - Documentation                    |\n`===========================================================================''\n\n-----------------------------«( Introduction )»------------------------------\n\nI Was Really Bored About The Nasty Ansi Y/N Question .. That''s Why I''ve Wrote\nThis Door ... \nIt Simply Removed The ANSI Question And Uses The User Configurated Setting\n*AFTER* The User LogOn With His Handle And PW\n(They Are Setted On The First Logon After Installation Or With The M Command)\n\nBy The Way I Know That There Are More ANSI-Door''s Flying Around But I haven''t\nSeen Any That Manages A QuickMode And Have Such Nice Design :)\n\n----------------------------«( Installation: )»------------------------------\n\nCopy The oNYXaNSI-Drawer To Your Doors: Directory\nCopy M.Info To Your BBS:Commands/BBSCMD Directory\nCopy ANSI.Info To Your BBS:Commands/SYSCmd Directory\nCopy ONYXANSI.Info To Your BBS:Commands/SysCmd Directory\n\nUse Any Editor To Add The "~CC_ONYXANSI|" -MCI Command To Your Bull.txt''s In\nYour Favority Node? Directory (Use The This MCI-Command As First!)\n\nThat''s All!\n\n--------------------------------«( Have Fun )»-------------------------------\n\nCredits:\n100% 68000 Code Was Done By fOX/rEMEDY ^ aSPECT Inc. ^ aLIENGROUP!\n\nIf You Have Any Suggestions Or BugReports Then Simply Try To Reach Me At My\nBBS: EViL MoON! +49-Invited-Only (aLIENGROUP wHQ, rEMEDY hQ, aSPECT iNC. hQ)\n\n','\n',char(10)),NULL,NULL,11105,3,0,NULL,NULL,'rmd_oans_onyxansi','scan',1780048692);
INSERT INTO door_catalog VALUES('rms05a','RMS05A.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RMS05A.LHA',NULL,'XIM','reqtools.library',NULL,NULL,NULL,'*                Presenting:               * *                                          * *     The `ReXXmaSHeR®'' v0.5a (update)     *',replace('********************************************\n*                Presenting:               *\n*                                          *\n*     The `ReXXmaSHeR®'' v0.5a (update)     *\n*     ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~     *\n*    ¤¤ The Arexx Programmer''s Dream ¤¤    *\n*                                          *\n*     Features: Encryption,compression,    *\n*      Reqtools support,optimisation,      *\n*       creates .exe AREXX programs,       *\n*     /X support and much much more !      *\n********************************************\n\n','\n',char(10)),'RMS.Guide',replace('@DataBase RexxMasher (RMS) Documentation\n@Author Phil Horney\n@Index Contents\n\n@Remark $VER: RMS V0.5a By Ray Norrish\n@Remark AmigaGuide DataBase\n\n@node MAIN "RexxMasher (RMS) Documentation Copyright © 1994 by Phil Horney and Ray Norrish."\n\n\n     REXXMASHER - THE ULTIMATE AREXX COMPRESSION AND SECURITY UTILITY!\n     ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n             RexxMasher (RMS) Copyright © 1994 by Ray Norrish.\n RexxMasher Documentation Copyright © 1994 By Phil Horney and Ray Norrish.\n\n\n                             TABLE OF CONTENTS\n                             ~~~~~~~~~~~~~~~~~\n\n            @{"   REGISTER TODAY!   " Link "Register"}      @{"    About RexxMasher    " Link "About"}   \n            @{" RexxMasher Features " Link "Features"}      @{"      Installation      " Link "Installation"}   \n            @{"   Using RexxMasher  " Link "Useage"}      @{" Using with Ami-Express " Link "AMIex"}   \n\n@endnode\n\n@node "Register" "RMS REGISTRATION INFORMATION."\n \nThank you for trying RexxMasher! We have spent many hours making this the\npremier Arexx compression, optimization and encryption utility. Although we\nfeel this program to be worth much more we are asking only the minimum fee\nfor a fully licensed copy. If you think our program is worth registering\nthen send in your registration fee per the following schedule:\n\n\n                       Single home user:  10.00 pounds UK\n                         Corporate user \n               (1 License per building):  29.00 pounds UK\n\n\nSend Postal Money Order or Cash in U.K. Funds and a formal request for a\nregistered copy to:\n \n                                @{"Ray Norrish" LINK "RAY"}\n                         5 Meadow Grove, Medowbank\n                            Winsford, CHESHIRE\n                          United Kingdom, CW7 1PQ\n                * Check same address as in main program *\n\nPlease remember to include your name, company name and mailing address.\nUpon Receipt and verification of funds we will mail you a fully working\nregistered version of RexxMasher. Please allow for a reasonable delivery\ntime based on your geographic location.\n\n@endnode\n@node "RAY" "A BIT ABOUT THE AUTHOR."\n \n                          A BIT ABOUT THE AUTHOR\n                          ~~~~~~~~~~~~~~~~~~~~~~\n\nRay was born at around 12:20pm in a very small bathroom in a restaurant\nin the nortern part of West Sussex England in 1989. Thanks the the mirracles\nof modern medicine combined with the enhanced learning speed derived from\nwatching entirely too much late-night telivision Ray has rocketed through the\nlast 5 years living a dog''s life, as you might say, and now at the age of 40\nhas decided to do something constructive with his life which has, up until\nnow, been of the most uninteresting and undoubtably boring sort. In his\nbrief stay on this planet Mr. Norrish has become severly addicted to \nFlintstones (tm) chewable vitamins, and has a tendency toward wearing women''s\nunder-garments. He thoroughly enjoys picking his nose when he thinks no one\nis looking in his direction and likes the wipe his "kill" in unusual places\nsuch as on public-telephone mouth-pieces or on the turning handles of \nstreetside parking meters. Exactly one third of Ray''s day is spent\nsleeping. The next third is spent sitting in front of his computer tapping\nout less-than-thrilling messages to fat, single women over 55 who have been\nmarried and divorced more than twice on a local BBS that caters to those\nsorts of sick, whacked-out kinds of people. The last third of Ray''s\noh-so-lively daily life is spent at the corner pub where he downs pint\nafter pint of cheap brew in hopes of forgetting who he is and the fact that\nhe is the oldest living virgin. Other than that he''s a really nice guy.\n\n@endnode\n@node "ABOUT" "A BIT ABOUT REXXMASHER"\n\n                          A BIT ABOUT REXXMASHER\n                          ~~~~~~~~~~~~~~~~~~~~~~\n\nRMS is a new utility for optimizing, compresing and encrypting ARexx scripts.\nIt is designed to be very easy to use via a GUI interface and will reduce the\nsize of your ARexx scripts while optimizing it and password-encrypting it.\nThe average size reduction is 50% and the optimized ARexx will run faster\nthan regular arexx while being unalterable by the end user.\n\nWHY? - We wanted a way to make arexx scripts run faster while making them\nresistant to tapering and alteration by the end user, and we wanted\na program whose output was self-contained - no libraries involved - and\ncould be freely distributable to anyone.  Until now the only product on\nthe market that sped up Arexx was the REXXPLUS COMPILER (tm) by the \nDineen Edwards Group, Inc. which though being a nice utility in and of\nitself had a few shortcomings, namely: The resulting compiled Arexx was\napproximately 600% larger than the source arexx (i.e. a 10k arexx script\nwound up being 60k in RexxPlus compiled format,) and it was not freely\ndistributable in compiled format except to other Registered owners of the\nRexxPlus compiler system.  The final output file of RMS is 100% self\ncontaind. Nothing else is needed to run the compiled arexx other than arexx\nitself.  Some applications that run arexx scripts as "doors" may need an\noptional custom startup script. The custom startup script included in this\npackage is for the Ami-Express BBS program.\n\n@endnode\n@node "installation" "INSTALLING REXXMASHER"\n\n                           INSTALLING REXXMASHER\n                           ~~~~~~~~~~~~~~~~~~~~~\n\nInstalling RexxMasher is as simple as copying the RexxMasher utility to\nyour C: or other assigned directory. You also need to copy your RMS.KEY\nfile into your L: directory. That''s it! Now you can run it from a CLI or\nfrom the Workbench. Just follow the requesters.\n\n@endnode\n@node "Features" "REXXMASHER FEATURES"\n\n                            REXXMASHER FEATURES\n                            ~~~~~~~~~~~~~~~~~~~\n\nRexxMasher has many features that make it the best (only?) utility on the\nmarket to optimize, compress and encrypt your arexx scripts.\n\n    @{" FULL GUI " Link "gui"}@{" OPTIMIZATION " Link "optimization"}@{" COMPRESSION " Link "compression"}@{" ENCRYPTION " Link "encryption"}@{" DECRYPTION " Link "decryption"}\n\n\n@endnode\n@node "GUI" "FULL GRAPHICAL USER INTERFACE (GUI)"\n\nFULL GRAPHICAL USER INTERFACE (GUI) - RexxMasher is equipped with a full\nGUI interface (Registered only) that makes it a snap to use. All you need \nto know is how to point and click!\n\n\n                              @{" FEATURES MENU " Link "features"}\n@endnode \n@node "optimization" "OPTIMIZATION"\n\nOPTIMIZATION - RexxMasher optimizes your arexx scripts by removing all the\ncomment lines, blank lines, extra blank spaces (indents) and placing the\nentire script onto one line. Since Arexx is what is called a LINE level\nlanguage placing the entire script on one line can have a dramatic increase\nin speed over the regular script.\n\n\n                              @{" FEATURES MENU " Link "features"}\n@endnode \n\n@node "compression" "COMPRESSION"\n\nCOMPRESSION - RexxMasher uses a built in compression algorythm to compress\nyour script by 50% or more on average and you can select the compression\ndepth to suit your needs from no compression to super compression!\n\n\n                              @{" FEATURES MENU " Link "features"}\n@endnode \n\n@node "ENCRYPTION" "ENCRYPTION"\n\nENCRYPTION - RexxMasher uses a key encryption method to make your arexx\nscripts tamper-resistant. You select the key whithout which the script\ncannot be decrypted.\n\n\n                              @{" FEATURES MENU " Link "features"}\n@endnode \n\n@node "DECRYPTION" "DECRYPTION"\n\nDECRYPTION AND RESOURCING - RexxMasher has the ability to decrypt is own\nfiles (provided you have the key,) and will output the original arexx\nscript to the designated path and filename so that you can modify it.\n(again, registered versions only)\n\n                              @{" FEATURES MENU " Link "features"}\n@endnode \n\n@node "USEAGE" "USING REXXMASHER"\n\n                             USING REXXMASHER\n                             ~~~~~~~~~~~~~~~~\n\nRMS is a snap to use. Just start it from the Workbench or a CLI and select\nthe source arexx script, compression depth, password for encryption and a\ndestination file and it does the rest, there really is nothing to it!\nRMSed files that do not call a port can be started from Workbench or CLI\nand others (like @{"Ami-Express arexx doors" LINK "AMIEX"}) may need a custom arexx startup\nscript like the one suplied specifically for Ami-Express. You need no external\nlibraries to use an RMSed script, you need only have Arexx installed and\noperational.\n\n@endnode\n\n@node "amiex" "USING RMS SCRIPTS WITH AMI-EXPRESS BBS"\n\n                  USING RMS SCRIPTS WITH AMI-EXPRESS BBS\n                  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nThe supplied startup script ''Ami-Express.rexx'' should be placed in your BBS:UTILS/\ndirectory. This short arexx script starts a particular RMS program based \non information about your BBS commands which are stored in the file \n@{"S:RMS.CONFIG" link "RMSCONFIG"}. This config file should contain the name and full\npath/filename of the RMS utilities it will be running.\n\n@endnode\n@node "RMSCONFIG" "THE RMS CONFIG FILE"\n \n                            THE RMS CONFIG FILE\n                            ~~~~~~~~~~~~~~~~~~~\nEXAMPLE CONFIG:\n \n----------------------------X8 CUT HERE 8X---------------------------------\nWHO DOORS:WHO/WHO.RMS\nAX DOORS:AXEDIT/AXEDIT.RMS\nUPDATE DOORS:UPDATE/UPDATE.RMS\n----------------------------X8 CUT HERE 8X---------------------------------\n\nIn this sample config the first word is the command name. The command name\nis the same as the name of the icon in your BBS:COMMANDS/BBSCMD/ drawer.\nLets say you have a command called ''WHO'' in your BBSCMD drawer. There is an\nicon in the BBSCMD drawer called ''WHO'' and it contains the path of the old\nwho door.  You would  go into the icon and change the path from\n''PATH=DOORS:WHO/WHO.AREXX'' to ''PATH=BBS:UTILS/RMS.START'' and leave all the\nother information intact. Remember, this is for RMS arexx doors only and will\nnot work for normal arexx doors.  Next you should edit the S:RMS.CONFIG file\nby adding the line ''WHO DOORS:WHO/WHO.RMS''.  The ''WHO'' is the name of the\nICON that you just edited and ''DOORS:WHO/WHO.RMS'' is the full path and name\nof the new RMSed Who door you are going to use.  When a user enters ''WHO''\non the command line Ami-Express runs the RMS.START script which gets the\ninformation from /X on what door you are trying to run. It then scans the\nconfig file for a match and if one is found it initiates all of the arexx\nstartup for /X and launches the RMSed WHO door!  The nice thing about using\na config file for your RMSed doors is that you need not edit the startup\nscript, only the config file to point to the proper script for each\ncommand. This means that you can use the same information in every BBSCMD\nicon that is going to run an RMSed script, you just need to change the\ncommand name!\n\n@endnode\n\n@node "contents" "RMS QUICK-INDEX."\n\n                              RMS QUICK INDEX\n                              ~~~~~~~~~~~~~~~\n@{"ENCRYPTION" LINK "ENCRYPTION"}\n@{"DECRYPTION" LINK "DECRYPTION"}\n@{"COMPRESSION" LINK "compression"}\n@{"OPTIMIZATION" LINK "optimization"}\n@{"USING REXXMASHER" LINK "USEAGE"}\n@{"REXXMASHER FEATURES" LINK "Features"}\n@{"THE RMS CONFIG FILE" LINK "RMSCONFIG"}\n@{"INSTALLING REXXMASHER" LINK "installation"}\n@{"A BIT ABOUT THE AUTHOR." LINK "RAY"}\n@{"RMS REGISTRATION INFORMATION." LINK "Register"}\n@{"FULL GRAPHICAL USER INTERFACE (GUI)" LINK "GUI"}\n@{"USING RMS SCRIPTS WITH AMI-EXPRESS BBS" LINK "amiex"}\n\n\n@endnode\n','\n',char(10)),NULL,'auto-added',82815,6,0,NULL,NULL,'rms05a','scan',1780048692);
INSERT INTO door_catalog VALUES('rms05a2','RMS05A2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RMS05A2.LHA',NULL,'XIM','reqtools.library',NULL,NULL,NULL,'*                Presenting:               * *      The `ReXXmaSHeR®'' v0.5a (fixed)     * *        (now contains the keyfile)        *',replace('********************************************\n*                Presenting:               *\n*      The `ReXXmaSHeR®'' v0.5a (fixed)     *\n*        (now contains the keyfile)        *\n*      ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~     *\n*    ¤¤ The Arexx Programmer''s Dream ¤¤    *\n*      ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~     *\n*     Features: Encryption,compression,    *\n*      Reqtools support,optimisation,      *\n*       creates .exe AREXX programs,       *\n*     /X support and much much more !      *\n********************************************\n\n','\n',char(10)),'RMS.Guide',replace('@DataBase RexxMasher (RMS) Documentation\n@Author Phil Horney\n@Index Contents\n\n@Remark $VER: RMS V0.5a By Ray Norrish\n@Remark AmigaGuide DataBase\n\n@node MAIN "RexxMasher (RMS) Documentation Copyright © 1994 by Phil Horney and Ray Norrish."\n\n\n     REXXMASHER - THE ULTIMATE AREXX COMPRESSION AND SECURITY UTILITY!\n     ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n             RexxMasher (RMS) Copyright © 1994 by Ray Norrish.\n RexxMasher Documentation Copyright © 1994 By Phil Horney and Ray Norrish.\n\n\n                             TABLE OF CONTENTS\n                             ~~~~~~~~~~~~~~~~~\n\n            @{"   REGISTER TODAY!   " Link "Register"}      @{"    About RexxMasher    " Link "About"}   \n            @{" RexxMasher Features " Link "Features"}      @{"      Installation      " Link "Installation"}   \n            @{"   Using RexxMasher  " Link "Useage"}      @{" Using with Ami-Express " Link "AMIex"}   \n\n@endnode\n\n@node "Register" "RMS REGISTRATION INFORMATION."\n \nThank you for trying RexxMasher! We have spent many hours making this the\npremier Arexx compression, optimization and encryption utility. Although we\nfeel this program to be worth much more we are asking only the minimum fee\nfor a fully licensed copy. If you think our program is worth registering\nthen send in your registration fee per the following schedule:\n\n\n                       Single home user:  10.00 pounds UK\n                         Corporate user \n               (1 License per building):  29.00 pounds UK\n\n\nSend Postal Money Order or Cash in U.K. Funds and a formal request for a\nregistered copy to:\n \n                                @{"Ray Norrish" LINK "RAY"}\n                         5 Meadow Grove, Medowbank\n                            Winsford, CHESHIRE\n                          United Kingdom, CW7 1PQ\n                * Check same address as in main program *\n\nPlease remember to include your name, company name and mailing address.\nUpon Receipt and verification of funds we will mail you a fully working\nregistered version of RexxMasher. Please allow for a reasonable delivery\ntime based on your geographic location.\n\n@endnode\n@node "RAY" "A BIT ABOUT THE AUTHOR."\n \n                          A BIT ABOUT THE AUTHOR\n                          ~~~~~~~~~~~~~~~~~~~~~~\n\nRay was born at around 12:20pm in a very small bathroom in a restaurant\nin the nortern part of West Sussex England in 1989. Thanks the the mirracles\nof modern medicine combined with the enhanced learning speed derived from\nwatching entirely too much late-night telivision Ray has rocketed through the\nlast 5 years living a dog''s life, as you might say, and now at the age of 40\nhas decided to do something constructive with his life which has, up until\nnow, been of the most uninteresting and undoubtably boring sort. In his\nbrief stay on this planet Mr. Norrish has become severly addicted to \nFlintstones (tm) chewable vitamins, and has a tendency toward wearing women''s\nunder-garments. He thoroughly enjoys picking his nose when he thinks no one\nis looking in his direction and likes the wipe his "kill" in unusual places\nsuch as on public-telephone mouth-pieces or on the turning handles of \nstreetside parking meters. Exactly one third of Ray''s day is spent\nsleeping. The next third is spent sitting in front of his computer tapping\nout less-than-thrilling messages to fat, single women over 55 who have been\nmarried and divorced more than twice on a local BBS that caters to those\nsorts of sick, whacked-out kinds of people. The last third of Ray''s\noh-so-lively daily life is spent at the corner pub where he downs pint\nafter pint of cheap brew in hopes of forgetting who he is and the fact that\nhe is the oldest living virgin. Other than that he''s a really nice guy.\n\n@endnode\n@node "ABOUT" "A BIT ABOUT REXXMASHER"\n\n                          A BIT ABOUT REXXMASHER\n                          ~~~~~~~~~~~~~~~~~~~~~~\n\nRMS is a new utility for optimizing, compresing and encrypting ARexx scripts.\nIt is designed to be very easy to use via a GUI interface and will reduce the\nsize of your ARexx scripts while optimizing it and password-encrypting it.\nThe average size reduction is 50% and the optimized ARexx will run faster\nthan regular arexx while being unalterable by the end user.\n\nWHY? - We wanted a way to make arexx scripts run faster while making them\nresistant to tapering and alteration by the end user, and we wanted\na program whose output was self-contained - no libraries involved - and\ncould be freely distributable to anyone.  Until now the only product on\nthe market that sped up Arexx was the REXXPLUS COMPILER (tm) by the \nDineen Edwards Group, Inc. which though being a nice utility in and of\nitself had a few shortcomings, namely: The resulting compiled Arexx was\napproximately 600% larger than the source arexx (i.e. a 10k arexx script\nwound up being 60k in RexxPlus compiled format,) and it was not freely\ndistributable in compiled format except to other Registered owners of the\nRexxPlus compiler system.  The final output file of RMS is 100% self\ncontaind. Nothing else is needed to run the compiled arexx other than arexx\nitself.  Some applications that run arexx scripts as "doors" may need an\noptional custom startup script. The custom startup script included in this\npackage is for the Ami-Express BBS program.\n\n@endnode\n@node "installation" "INSTALLING REXXMASHER"\n\n                           INSTALLING REXXMASHER\n                           ~~~~~~~~~~~~~~~~~~~~~\n\nInstalling RexxMasher is as simple as copying the RexxMasher utility to\nyour C: or other assigned directory. You also need to copy your RMS.KEY\nfile into your L: directory. That''s it! Now you can run it from a CLI or\nfrom the Workbench. Just follow the requesters.\n\n@endnode\n@node "Features" "REXXMASHER FEATURES"\n\n                            REXXMASHER FEATURES\n                            ~~~~~~~~~~~~~~~~~~~\n\nRexxMasher has many features that make it the best (only?) utility on the\nmarket to optimize, compress and encrypt your arexx scripts.\n\n    @{" FULL GUI " Link "gui"}@{" OPTIMIZATION " Link "optimization"}@{" COMPRESSION " Link "compression"}@{" ENCRYPTION " Link "encryption"}@{" DECRYPTION " Link "decryption"}\n\n\n@endnode\n@node "GUI" "FULL GRAPHICAL USER INTERFACE (GUI)"\n\nFULL GRAPHICAL USER INTERFACE (GUI) - RexxMasher is equipped with a full\nGUI interface (Registered only) that makes it a snap to use. All you need \nto know is how to point and click!\n\n\n                              @{" FEATURES MENU " Link "features"}\n@endnode \n@node "optimization" "OPTIMIZATION"\n\nOPTIMIZATION - RexxMasher optimizes your arexx scripts by removing all the\ncomment lines, blank lines, extra blank spaces (indents) and placing the\nentire script onto one line. Since Arexx is what is called a LINE level\nlanguage placing the entire script on one line can have a dramatic increase\nin speed over the regular script.\n\n\n                              @{" FEATURES MENU " Link "features"}\n@endnode \n\n@node "compression" "COMPRESSION"\n\nCOMPRESSION - RexxMasher uses a built in compression algorythm to compress\nyour script by 50% or more on average and you can select the compression\ndepth to suit your needs from no compression to super compression!\n\n\n                              @{" FEATURES MENU " Link "features"}\n@endnode \n\n@node "ENCRYPTION" "ENCRYPTION"\n\nENCRYPTION - RexxMasher uses a key encryption method to make your arexx\nscripts tamper-resistant. You select the key whithout which the script\ncannot be decrypted.\n\n\n                              @{" FEATURES MENU " Link "features"}\n@endnode \n\n@node "DECRYPTION" "DECRYPTION"\n\nDECRYPTION AND RESOURCING - RexxMasher has the ability to decrypt is own\nfiles (provided you have the key,) and will output the original arexx\nscript to the designated path and filename so that you can modify it.\n(again, registered versions only)\n\n                              @{" FEATURES MENU " Link "features"}\n@endnode \n\n@node "USEAGE" "USING REXXMASHER"\n\n                             USING REXXMASHER\n                             ~~~~~~~~~~~~~~~~\n\nRMS is a snap to use. Just start it from the Workbench or a CLI and select\nthe source arexx script, compression depth, password for encryption and a\ndestination file and it does the rest, there really is nothing to it!\nRMSed files that do not call a port can be started from Workbench or CLI\nand others (like @{"Ami-Express arexx doors" LINK "AMIEX"}) may need a custom arexx startup\nscript like the one suplied specifically for Ami-Express. You need no external\nlibraries to use an RMSed script, you need only have Arexx installed and\noperational.\n\n@endnode\n\n@node "amiex" "USING RMS SCRIPTS WITH AMI-EXPRESS BBS"\n\n                  USING RMS SCRIPTS WITH AMI-EXPRESS BBS\n                  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nThe supplied startup script ''Ami-Express.rexx'' should be placed in your BBS:UTILS/\ndirectory. This short arexx script starts a particular RMS program based \non information about your BBS commands which are stored in the file \n@{"S:RMS.CONFIG" link "RMSCONFIG"}. This config file should contain the name and full\npath/filename of the RMS utilities it will be running.\n\n@endnode\n@node "RMSCONFIG" "THE RMS CONFIG FILE"\n \n                            THE RMS CONFIG FILE\n                            ~~~~~~~~~~~~~~~~~~~\nEXAMPLE CONFIG:\n \n----------------------------X8 CUT HERE 8X---------------------------------\nWHO DOORS:WHO/WHO.RMS\nAX DOORS:AXEDIT/AXEDIT.RMS\nUPDATE DOORS:UPDATE/UPDATE.RMS\n----------------------------X8 CUT HERE 8X---------------------------------\n\nIn this sample config the first word is the command name. The command name\nis the same as the name of the icon in your BBS:COMMANDS/BBSCMD/ drawer.\nLets say you have a command called ''WHO'' in your BBSCMD drawer. There is an\nicon in the BBSCMD drawer called ''WHO'' and it contains the path of the old\nwho door.  You would  go into the icon and change the path from\n''PATH=DOORS:WHO/WHO.AREXX'' to ''PATH=BBS:UTILS/RMS.START'' and leave all the\nother information intact. Remember, this is for RMS arexx doors only and will\nnot work for normal arexx doors.  Next you should edit the S:RMS.CONFIG file\nby adding the line ''WHO DOORS:WHO/WHO.RMS''.  The ''WHO'' is the name of the\nICON that you just edited and ''DOORS:WHO/WHO.RMS'' is the full path and name\nof the new RMSed Who door you are going to use.  When a user enters ''WHO''\non the command line Ami-Express runs the RMS.START script which gets the\ninformation from /X on what door you are trying to run. It then scans the\nconfig file for a match and if one is found it initiates all of the arexx\nstartup for /X and launches the RMSed WHO door!  The nice thing about using\na config file for your RMSed doors is that you need not edit the startup\nscript, only the config file to point to the proper script for each\ncommand. This means that you can use the same information in every BBSCMD\nicon that is going to run an RMSed script, you just need to change the\ncommand name!\n\n@endnode\n\n@node "contents" "RMS QUICK-INDEX."\n\n                              RMS QUICK INDEX\n                              ~~~~~~~~~~~~~~~\n@{"ENCRYPTION" LINK "ENCRYPTION"}\n@{"DECRYPTION" LINK "DECRYPTION"}\n@{"COMPRESSION" LINK "compression"}\n@{"OPTIMIZATION" LINK "optimization"}\n@{"USING REXXMASHER" LINK "USEAGE"}\n@{"REXXMASHER FEATURES" LINK "Features"}\n@{"THE RMS CONFIG FILE" LINK "RMSCONFIG"}\n@{"INSTALLING REXXMASHER" LINK "installation"}\n@{"A BIT ABOUT THE AUTHOR." LINK "RAY"}\n@{"RMS REGISTRATION INFORMATION." LINK "Register"}\n@{"FULL GRAPHICAL USER INTERFACE (GUI)" LINK "GUI"}\n@{"USING RMS SCRIPTS WITH AMI-EXPRESS BBS" LINK "amiex"}\n\n\n@endnode\n','\n',char(10)),NULL,'auto-added',82578,5,0,NULL,NULL,'rms05a2','scan',1780048692);
