INSERT INTO door_catalog VALUES('rstdp13','RSTDP13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RSTDP13.LHA','rst-dirpack','XIM','Rst-DirPack',NULL,'SoFtLiNe',NULL,'!~  ~\___ __/\\~    ~//|  ____ __/\ __/\ |  O /~ ~Y~   !\    /| |  !~ ~Y~   Y~   ) |  _ \  -|   -| |  | | |__|  -|   -|   -|',replace('_:____         ________ _\n!~  ~\___ __/\\~    ~//|  ____ __/\ __/\\n|  O /~ ~Y~   !\    /| |  !~ ~Y~   Y~   )\n|  _ \  -|   -| |  | | |__|  -|   -|   -|\n|  |  \ -|-   |.|  |.|    |  -|-   |-   |\n|__|___)_A____!|____||____A___A____A____!_\n |       <-rst proudly presents->       :\n |  Update:                             |\n |            RsT-DirPack v1.3          |\n +      The Ultimate ReplaceMent For    +\n |         The  FD Dirpack Door.        |\n +--------------------------------------+\n |  RsT-DirPack Is XIM Modul, And Run''s |\n |      On  /X v4.xx And LogicBBS.      |\n |        ProGramed By  SoFtLiNe        |\n +--------------------------------------+\n +\n','\n',char(10)),'RsT-DirPack.Doc',replace('         :                  ·                            ·        \n         ¦       /\         :        /\        /\        :        :\n   __ ___|_____  /\_________¦________/\____    /\________|________|____ __\n  \\_\\____   ¬\/.  ____/   _________  \   |__/   ____/   ____/   ____//_//\n       |   )  _//  __/__\____  ¬\  /.   \  | ¬\  __/__\____  ¬\____  ¬\\n       |!  |   ¬\      ¬\   ¬\  \\//    \\ !  \\     ¬\    \  \\   \  \\\n       l___|   //_____ //______ //\____ //___ //____ //______ //_____ //\n         | !___/     ¬\/    | ¬\/     ¬\/   ¬\/    ¬\/ pr!de¬\/   | ¬\/\n         ¦                  ¦                            ¦        ¦\n         :                  :-------------- -- -  - -----+--- - --+--- -- -\n      - -+------    -    ---+ - -                        ¦        ¦\n         :                  ¦                            :        :\n         ·                  :                            ·        :\n                                                                  .\n\n                       P r o u d l y   P r e s e n t '' s\n\n                               RsT-DirPack v1.3.\n\n                           Programing By SoFtLiNe...\n   ------------------------------------------------------------------------\n Updated 16-09/95.\n\n History:\n ---------\n  RsT-DirPack Is The Ultimate ReplaceMent For The OLD FD DIRPack Door,\n  The FD Door Has Som Wery Nasty Bugs, As You Maby Aware Of.\n\n  So I Desided To Make One That Dont Have The Same Probs As FD Has,\n  And RsT-DirPack Is The Result''s Of That.\n\n  -----------------------------------------\n\n Instalation:\n -------------\n Wery Easy To Install, Copy RsT-DirPack Directory To You''r Door\n Directory, For LogicBBS Owners The DP ASII File Goes In BBSCmd Directory\n And For /X Owners The DP.Info Goes In BBSCmd.\n ---------------------------------------------\n\n\n How A User Use''s RsT-DirPack:\n ------------------------------\n  When RsT-DirPack Is Started The User Have 3 Different Packer Option''s\n\n  1) Pack The DIR Files In This Conference With  Lha\n\n  2) Pack The DIR Files In This Conference With  Zoo\n\n  3) Pack The DIR Files In This Conference With  Lzx\n ---------------------------------------------------\n  If The User Wanth To Pack DIR Files From Other Conference''s Too\n  Before Hee Start''s DownLoading.\n  Hee Just Press J And Jump''s In Then Next Conference.\n\n  If User Have Selected To Pack DIR Files As LHA From The 1 Conference\n  Hee Hash To Select 1) LHA Again In The Other''s Conference''s Too\n  It''s The Same Way For Zoo, Lzx.\n\n  When User Is Done Packing DIR Files From The Conference''s Hee Wanth''s,\n  Hee Then Have To Press D To Start DownLoading...\n -------------------------------------------------------------------------\n  In This Update Of RsT-DirPack I Changed The Screen OutPut, And RsT Logo\n  Now Included In The MainSource.\n  AlSoo Included A Help Menu For The User''s...\n  And Some Smaller Bug''s Corrected.\n -----------------------------------------------\n\n  This Is All For Now ( Enjoy Enjoy Enjoy ).\n','\n',char(10)),NULL,'auto-added',30476,9,0,NULL,NULL,'rst_d13','scan',1780048692);
INSERT INTO door_catalog VALUES('rstsl11','RSTSL11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RSTSL11.LHA','RstSoftLogOff','XIM','RstSoftLogOff',NULL,'SoftLine',NULL,'!~  ~\___ __/\\~    ~//|  ____ __/\ __/\ |  O /~ ~Y~   !\    /| |  !~ ~Y~   Y~   ) |  _ \  -|   -| |  | | |__|  -|   -|   -|',replace('_:____         ________ _\n !~  ~\___ __/\\~    ~//|  ____ __/\ __/\\n |  O /~ ~Y~   !\    /| |  !~ ~Y~   Y~   )\n |  _ \  -|   -| |  | | |__|  -|   -|   -|\n |  |  \ -|-   |.|  |.|    |  -|-   |-   |\n |__|___)_A____!|____||____A___A____A____!_\n  \       <-rst proudly presents->       /\n   <<                                  >>\n   <<       SoftLogOff v1.01  For      >>\n   <<  /X v4.xx  And  LogicBBS v1.xx   >>\n   <<            ( Update )            >>\n   <<    Programed In AmigaE Langue    >>\n   <<   By SoftLine ThunderBlock BBS.  >>\n   <<__________________________________>>\n \n','\n',char(10)),'Manual.Txt',replace('\n 29-6/95.\n\n                     R e S t L e S s  Proudly Present''s\n\n                             SoftLogOff v1.01\n\n --------------------------------------------------------------------------\n\n History:\n ---------\n SoftLogOff v1.01 Is ProGramed In AmigaE Langue\n\n And Is Designed So That The User Can Choose Betwene 4 LogOff\n\n Options, Show Either The LogOff1.Txt Or LogOff2.Txt, Or Leave A\n\n Comment To The SysOp, And LogOff3.Txt If User Press Return At LogOff\n\n This LogOff Door Can Bee Installed In AmiExPress BBS Or\n\n LogicBBS Systems...\n\n ----------------------------------------------------------------\n\n InStalation:\n -------------\n Just Copy The RsTSoftLogOff Directory To You''r DOORS: Directory\n\n In The LogOff.Cfg File You Write 2 Line''s,\n\n Those 2 Line''s Is The Information That Will Pop Up On The\n\n LogOff Screen The User Look''s At, When Hee''s Loggin Off.\n\n Here Is A Example Of The LogOff.Cfg File\n\n\n[35mReStLeSs [34mLogOff\n[35mExCaLiBuR [34mLogOff\n\n As You Can See ,You Can Use Ansi Sign''s Too \n\n To Give The Txt Colors With.\n\n The Door Is  XIM Modul And StackSize Is 4096 Byts.\n\n I Have Included AlSoo a G.Info file For /X User''s And a\n\n G  TxtFile For LogicBBS User''s.\n\n You Have To Place One Of Them In Your BBSCmd Drawer...\n\n And Also Remember To Place AEDoor.Library In The Libs: \n\n This Is Also The Case For LogicBBS Owner''s\n\n I Have Included AEDoor.Library In This Packed Too\n\n That''s All For Now Dude''s.\n ----------------------------------------------------------------\n     Hope You Like This Litle And Wery Fast LogOff Door....\n ----------------------------------------------------------------\n ProGramed By  SoftLine  ThunderBlock BBS (ReStLeSs <> ExCaLiBuR)\n\n\n','\n',char(10)),NULL,'auto-added',32749,8,0,NULL,NULL,'rst_sl9','scan',1780048692);
INSERT INTO door_catalog VALUES('rst_av1','RST_AV1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RST_AV1.LHA','RsT-ArcView','XIM','_____         ________ _',NULL,'Internal/External','RST','!~  ~\___ __/\\~    ~//|  ____ __/\ __/\ |  O /~ ~Y~   !\    /| |  !~ ~Y~   Y~   ) |  _ \  -|   -| |  | | |__|  -|   -|   -|',replace('_____         ________ _\n!~  ~\___ __/\\~    ~//|  ____ __/\ __/\\n|  O /~ ~Y~   !\    /| |  !~ ~Y~   Y~   )\n|  _ \  -|   -| |  | | |__|  -|   -|   -|\n|  |  \ -|-   |.|  |.|    |  -|-   |-   |\n|__|___)_A____!|____||____A___A____A____!\n !|-----------------------------------|! \n |!    RsT-ArcView v1.0 System For    !|\n |:        LogicBBS & /X v4.xx        :|\n |.-----------------------------------.|\n |!   A STRONG ReplaceMent For The    !|\n |: Internal/External V (View Files)  :|\n |! Cover''s LHA/LZX/ZIP/ZOO/DMS/.TXT  !|\n |!.    Files, Door Is XIM Modul.    .!|\n  ^-----------------------------------^ \n \n','\n',char(10)),'RsT-ArcView.Doc',replace('         :                  ·                            ·        \n         ¦       /\         :        /\        /\        :        :\n   __ ___|_____  /\_________¦________/\____    /\________|________|____ __\n  \\_\\____   ¬\/.  ____/   _________  \   |__/   ____/   ____/   ____//_//\n       |   )  _//  __/__\____  ¬\  /.   \  | ¬\  __/__\____  ¬\____  ¬\\n       |!  |   ¬\      ¬\   ¬\  \\//    \\ !  \\     ¬\    \  \\   \  \\\n       l___|   //_____ //______ //\____ //___ //____ //______ //_____ //\n         | !___/     ¬\/    | ¬\/     ¬\/   ¬\/    ¬\/ pr!de¬\/   | ¬\/\n         ¦                  ¦                            ¦        ¦\n         :                  :-------------- -- -  - -----+--- - --+--- -- -\n      - -+------    -    ---+ - -                        ¦        ¦\n         :                  ¦                            :        :\n         ·                  :                            ·        :\n\n                            << Proudly Present''s >>\n\n                            A r c V i e w   v 1.00.\n\n                              Programed In AmigaE\n\n                         By SoFtLiNe Released 27/5-95.\n ----------------------------------------------------------------------------\n History:\n ---------\n The ArcView Door Is Running On /X v4.xx And LogicBBS System''s And Is a\n Wery GOOD ReplaceMent for The Internal/External V (ArcHiv View)\n You Can Change Conference, Show The File DIR''s Normal/Reverse ,\n WithOut To Have To Leave The ArcView Door.\n\n It''s a Wery FAST Running Door, The Door Use''s Thease Packer Types\n Lha / Lzx / UnZip / Zoo / DMS / Also Normal .Txt / .Nfo Files\n Can Bee Viewe''d\n\n If You Dont Have One Of The Packere''s ,You Can Get It/Them On \n ThunderBlock BBS (+45-6443 2504) (DK).\n\n The ArcView Door Is a XIM Modul Door.....\n ---------------------------------------------------------------------------\n\n Instalation:\n -------------\n Move Thease Files To Doors:ArcView/\n ArchivView , Header , View.Cfg  \n -------------------------------\n Put The V.Info File In The BBSCmd Directory\n --------------------------------------------\n\n In The View.Cfg File You Have To Enter The Directory Name On Your Dir Were\n All Your Uploaded Files Are Beaing Keep''t.\n\n A Example:\n ------------\n You Have 3 Conference''s Were There Are Files For Download In a Directory\n Named   Passed  Or WathEver, Then In The View.Cfg File You Enter..\n\n ----Cut Here----------\nPassed/\n\n ----Cut Here----------\n\n The DirName Must Bee The Same In All Your Confs, And Dont Forget The\n / Slash Afther The DirName In The View.Cfg File..\n --------------------------------------------------------------------------\n Thats All Dudes  EnJoy EnJoy...\n\n','\n',char(10)),NULL,NULL,77223,9,0,NULL,NULL,'rst_av1_rst_arcview','scan',1780048692);
INSERT INTO door_catalog VALUES('ryl_be10','RYL-BE10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RYL-BE10.LHA',NULL,'XIM','.___.        .___.',NULL,NULL,'RYL','___________ __________|   |_______ |   | /X! \_ ___    / ____ \    |   |\____  \_   |___. |  _/  _/.    /  \____  _|   _    |   |   |',replace('                      .___.        .___.\n___________ __________|   |_______ |   | /X!\n\_ ___    / ____ \    |   |\____  \_   |___.\n |  _/  _/.    /  \____  _|   _    |   |   |\n |__\     |_______/   /  \_________|__ `   |\n ----\____|------/________\[pRESENTS!]\____|\n Buy-An-Eall v1.0 - Eall door for Express!\n Let users `pay'' for ealls! - Go grab! nOW!\n ------------------------------------------\n','\n',char(10)),'Eall.Doc',replace('\n                                    .____.            .____.\n        _____________ ______________|    | __________ |    |\n        \_  ___     / _____   \     |    |_\______   \_    |____.\n         |   _/   _/.     /    \_____   _|     ___    |    |    |\n         |___\      |__________/    /   \|____________|___ `    |\n        ------\_____|---------/__________\---[PRESENTS:]--\_____|-\n\n      - -- ---^(BUY-AN-EALL v1.0 by ¡CE/ROYAL^CDS 11-APR-95)^--- -- -\n\n\n\nBUY-AN-EALL? WHAT THE FUCK IS BUY-AN-EALL?\n------------------------------------------\nPlain and simple! I got sick and tired of a dude, I won''t tell his name\n(mAGIC/mIRAGE-mAGIC/mIRAGE-mAGIC/mIRAGE-mAGIC/mIRAGE >:^) ) who dumped\nadds for his board all the time when he came by.. So I decided to let him\npay for it! Now you can let your users `pay'' in u/l credits for an eall!\n\n\n\nREQUIREMENTS\n------------\n/X 3.xx (it might work with lower versions.. i dunno..) or higher. \nAssigned DOORS: and a running rexxmaster.\nAn amiga model would be nice.\n\n \n\nINSTALLATION\n------------\nSimple... Just copy all the files included in the archive to the correct\ndirs, and edit DOORS:RYL-EALL/EALL.CFG:\n\n 8<--------------------------------------------------\n250000       <- The amount of bytes you want to deduct\n150          <- Acces level wich allows `normal'' eall messages \n\n\n\nTESTING THE DOOR\n----------------\nLower your acces to a level below the `normal'' eall acces, and hit eall.. \nTATA!\n\n\nGREETINX\n--------\n\nApollo/ROYAL ( <- Can''t even link properly with SkidMarks ][! )\nAnaLyZer of HellCat (ofzo.... euh... )\nExotic/ACCES^POSSE^??? (gr8 chats!)\nJake/PSG^MRG (euh.. )\nKillRaven/MST (It''s WEL o-kee. Relikwie!)\nMuad''Dib/ROYAL^MST (Nee. jij bent gewoon stom. geen groet.  \ndA MSWeR/EFFECT (chatrecordjes roolen!)\nNightCrawler/OTM.The Gravediggers (Thanx voor yar help!)\nVeteran/Cocaine (Raarmans!)\nWhirlWind/ROYAL^RLG (ga toch heen jij!)\nZack/STD (Hehhe.e... pilletje pilletje aan de wand... )\nMotive Power/MST (Power-Eall!?)\nEurobyte/CCN (klok klok klok klok.... )\nAndabata/BARF!^NO^AA (idem dito)\nSadus/Myth/Ovl (euh.. ben ik iets vergeten?)\nDiablo/MTH (ik wil graag de ossestaartsoep, en de wijnkaart voor mevrouw..)\nThe Brain (euhmm.. tja.. wat zal ik zegguh.. HALLO!)\nMidnight Caller/CCN (Niet iets voor jou met je addgekte?)\nMega^Fortress (Xpret schiet ook niet op he.. )\nCody/CDS (euh.. hoi!)\nFreezer/CDS (idem dito)\nBuzzy/RLY&NO!? (geld te weinig, oog teveel.. )\n\nAnd all friends of my who don''t run a board or sumthing, I doubt you''ll\never read this :-)\n\nAND OFCOURSE ALL (*)  R O Y A L  (*)  &  .C.D.S. MEMBERS ALL OVER THE GLOBE!\n\n\n\nCONTACTING ME!\n--------------\n                             \n          ....................................... ....... . .....   .   .\n          :     .....  . . .  .  __________    .          .           .\n          :     :      _________/_______   \__   ________________________\n _______  .     :     /    ____   / ___/    \ \_/__         /__         /\n \_____/_______ .     \______  \_/  \_______/  \   \ \_____/_  \ \_____/.\n /     \ \     \_______\__  /   \      / /     /   / _/  \__/ _/ _/  \  :\n/       \ \     \_   _   /_______\____/ /_____/___/_______\    \______\ :\n\_______/  \    /     \_/        /_   \      ......... \___\     /      :\n    /_______\__/       \  \_____/_/  _/      : ..... :      \___/       :\n     :        /_________\ _/  \  \    \__    : :   : :..........mSW/mAD.:\n     :                 \_______\__\     /    : :   :.....................\n     `·····························\___/·····'' :                        :\n      NEW USER''S FIRST UPLOAD BATCH GETS 2*!   :     DIALING GUIDE:     :\n          ..............................       :  ADD SECS TO TIMEOUT!  :\n       ^  :                          ..:.......: TRY:+31-2290-35368W414 :\n       :  : CDS HAMSTER WORLD HQ !   :         : OR:+31229035368,,,,414 :\n       :  : LOCATED IN THE HORNY     : SiSSiEs :........................:\n       :  : PALACE OF THE ROYAL ¡CE! : ------->                   :\n       :  : ONLY ONE BLAZING NODE!   : ¡CE/CDS^ROYAL - CHIP/ROYAL : \n       :  : AMIGA - CONSOLES - AMI-X : THE BRAIN - DUTCHIE/CDS    :\n       :  :..........................: TTT/CDS - SPACE 4 RENT!    :\n       :                             :............................: \n       :\n       :............. CALL NOW! IT WILL ONLY HARM YOUR PHONEBILL! >:^)   \n\n           >> NUMBER WILL BE CHANGED SUMWHERE IN SUMMER 1995! <<\n\n                  Or try mailing iCE or iCE/CDS sumwhere!\n\n\n\nCALL OUR BOARDS:\n----------------\n                            .____.            .____.\n_____________ ______________|    | __________ |    |\n\_  ___     / _____   \     |    |_\______   \_    |____.\n |   _/   _/.     /    \_____   _|     ___    |    |    |\n |___\      |__________/    /   \|____________|___ `    |\n------\_____|---------/__________\----------------\_____|--------------------\n \n                         * bOARDS! *\n \n     Digital Extasy  - +1-ASK-ELITE! - USHQ [4 NODE RD/16K8]\n       Dutch Dreams  - +31-ASKELITE! - WHQ  [1 NODE/14K4 (SOON 3 NDS)]\n   The Undiscovered  - +31-ASKELITE! - EHQ  [3 NODE/28k8 USR]\n         StoneHenge  - +31-ASKELITE! - DHQ  [1 NODE/28K8]\n           Homeless  - +49-ASKELITE! - GHQ  [2 NODE/28K8]\n         Phoenix II  - +46-ASKELITE! - SHQ  [1 NODE/28K8]\n \n \n                    * aFFILIATED bOARDS! *\n \n             The Lab - +31-KILL4IT! - Prof B-Rom\n               Delta - +31-KILL4IT! - Eagle\n       MF Enterprise - +31-KILL4IT! - Mega Fortress\n          Dreamphase - +46-KILL4IT! - Bubba\n         ¡NTERSpHERE - +31-KILL4IT! - ¡CE\n \n---------------------------------------------------[KILL FOR THA NUMBERS!]---\n\n-EOF-\n','\n',char(10)),NULL,NULL,5287,2,0,NULL,NULL,NULL,'scan',1780048704);
INSERT INTO door_catalog VALUES('ryl_be13','RYL-BE13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RYL-BE13.LHA',NULL,'XIM','exe.-l0S-eND0S-bBS-.exe',NULL,'Copy/Cut','RYL','___________ __________|   |_______ |   | \_ ___    / ____ \    |   |\____  \_   |___. |  _/  _/.    /  \____  _|   _    |   |   |',replace('                      .___.        .___.\n___________ __________|   |_______ |   |    \n\_ ___    / ____ \    |   |\____  \_   |___.\n |  _/  _/.    /  \____  _|   _    |   |   |\n |__\     |_______/   /  \_________|__ `   |\n ----\____|------/________\[pRESENTS!]\____|\n         BetterEdit V1.3 (9-Feb-96)\nBlock/FileNameCompl/Copy/Cut/Paste/Word-\nSentence Jump-Del./In-Decrease etc. in \nstringgadgets - Like NewEdit but BETTER!\nShortName: RYL-BE13.LHA\n','\n',char(10)),'BetterEdit.Guide',replace('@DataBase BetterEdit.Guide\n@Author "Allan `Duff'' Odgaard"\n@(c) "Copyright © 1995 D&D Productions."\n@$VER: BetterEdit.Guide V1.3 (9-Feb-96)\n@Font Xen.font 9\n@WordWrap\n@Tab 8\n@TOC Main\n\n@Macro Prg "BetterEdit"\n@Macro Ver "V1.3"\n\n@Node Main "BetterEdit, AmigaGuide documentation."\n\n@{JCenter}Welcome to the @{FG HighLight}@{Prg} @{Ver}@{FG Text} @{AmigaGuide}.\n© 1996 Allan Odgaard\n@{JLeft}\n\n        @{" Intro " Link Intro} - What is @{Prg}\n\n      @{" Install " Link Install} - Very easy!\n\n   @{" Disclaimer " Link Disc} - Read your rights\n\n     @{"Functions " Link Funcs} - What @{Prg} offers\n\n        @{" To Do " Link ToDo} - Isn''t it perfect???\n\n         @{" Bugs " Link Bugs} - Write me if you have something beside this\n\n       @{" Author " Link Author} - Here is who you should thank!\n\n      @{" History " Link History} - If you are acquainted with @{Prg}\n\n@EndNode\n\n\n@Node Intro "What''s it all about"\n\nBetterEdit is yet another EditHook.\nIt adds ALOT of @{" functions " Link Funcs} to the stringgadgets, which are used by almost every program with GUI.\n\nThe most impressive functions are stuff such as Filename completion and visual blocking.\n\nSo if you use stringgadgets alot (who doesn''t?) you really should consider to @{" install " Link Install} @{Prg}.\n\n@EndNode\n\n\n@Node Install "How to install BetterEdit"\n\nYou should have atleast Kick V39+\n\nEither drag the icon to your WBStartup drawer or:\n\n\nCopy @{Prg} to C: and add this line to your User-Startup or Startup-Sequence:\n\nRun <>Nil: BetterEdit\n\nReboot your machine and test it!\n\n@EndNode\n\n\n@Node Disc "Bla bla bla..."\n\nStandard disclaimer:\n\nThere is no warranty for this program to the extent permitted by applicable law. Except where otherwise stated in writing the copyright holder and/or other parties provide the program "as is" without warranty of any kind, either expressed or implied, including, but not limited to, the implied warranties of merchantability and fitness for a particular purpose. The entire risk as to the quality and performance of the program is with you. Should the program prove defective, you assume the cost of all necessary servicing, repair or correction.\nIn no event unless required by applicable law or agreed to in writing will any copyright holder, or any other party who may redistribute the program as permitted above, be liable to you for damages, including any general, special, incidental or consequential damages arising out of the use or inability to use the program (including but not limited to loss of data or data being rendered inaccurate or losses sustained by you or third parties or a failure of the program to operate with any other programs), even if such holder or other party has been advised of the possibility of such damages.\n\n@EndNode\n\n\n@Node Funcs "Functions of BetterEdit"\n\nIf you use a common editor you should be familiar with some of the following keys, since they''re kind of standard.\n\nAmiga + b	 =	Go into @{" BlockMode " Link Blocking}.\nAmiga + c	 =	Copy either the hole string, or the blocked text.\nAmiga + d	 =	Decrease nearest number with one.\nAmiga + G	 =	Switch case from cursor to end of word.\nAmiga + g	 =	Switch case on current character.\nAmiga + i	 =	Increase nearest number with one.\nAmiga + q	 =	Undo all changes.\nAmiga + v	 =	Paste from clipboard\nAmiga + x	 =	Cut either the hole string, or the blocked text.\n         	 	In blockmode; to clipboard.\n\nAmiga + Tab	 =	@{" Complete filename " Link FNC}, hold down shift to cycle backwards.\nCtrl + Tab	 =	-||-\n\nAmiga + Key	 =	Send the pressed key to the window, use shift to send keys as q,b,c...\n\nEsc		 =	Inactivate gadget (this is non-confirming, in contrary of return)\n\nCtrl + Cr Left	 =	Move cursor to start of current word.\nCtrl + Cr Right	 =	Move cursor to start of next word.\nCtrl + Backspace =	Delete from cursor to start of current word.\nCtrl + Delete	 =	Delete from cursor to start of next word.\n\nAlt + Cr Left	 =	Move cursor left until it reach a dot.\nAlt + Cr Right	 =	Move cursor right until it reach a dot.\nAlt + Backspace	 =	Delete to the left until it reach a dot.\nAlt + Delete	 =	Delete to the right until it reach a dot.\n\nShft + Cr Left	 =	Move cursor to start of string.\nShft + Cr Right	 =	Move cursor to end of string.\nShft + Backspace =	Delete from cursor to start of string.\nShft + Delete	 =	Delete from cursor to end of string.\n\n@{B}Explanation of used terms:@{UB}\n\nSwitch case means; convert uppercase characters to lowercase, and lower to upper, e.g.fOO-bAR would be Foo-Bar.\n\nNearest number is more specific the first number placed under or on the right side of the cursor, if there is no match, it''ll then go from cursor pos and to the left.\n\nWords are separated by one or more non-alphanumerical characters, means that "foo_bar" are two words, since _ is non-alphanumerical.\n\n@EndNode\n\n\n@Node Blocking "How about it!"\n\n@{I}Have you ever wanted to copy the pre/suf-fix of the name in the stringgadget, or cut out the middle of it - move an argument or similar.@{UI}\n\nIf you know MS-Windows, you might have noticed that you, via the mouse, can block out text in stringgadgets. Unfortunately the global edithook (@{Prg}) is not called when user presses a mouse button inside a stringgadget.\n\nInstead move your cursor to where the block should start\nPress Amiga+b, and move the cursor to whereever you want the block to stop.\nPress Amiga+c to copy the block to the clipboard or press Amiga+x to move the block to the clipboard.\nYou can also press Amiga+b, which will leave the blockmode.\n\nIf you (in blockmode) activates another stringgadget or a program calls GadTools/SetAttrs on the current stringgadget, the blockmode will be disabled.\n\n@EndNode\n\n\n@Node FNC "Filename completion"\n\nThis can both complete a volume/assign/device or filename, but spaces in the volume/assign/device name will confuse the filename completion (will be fixed!)\n\nIf you need to enter a picture name like "Graphics:Own stuff/Great Logo.64Cols" you can save alot of typing by using the filename completion function, which I will explain via an example:\n\nFirst enter "gr", and press Ctrl+Tab, then @{Prg} will search the doslist for an volume/assign/device name starting with gr, the first match are then pasted into the stringgadget (a screen flash upon failure)\nPressing Ctrl+Tab again won''t give you next match, but instead the first file in Graphics: (this might change.)\n\nNow you need the sub dir "Own stuff/", so simply write ow followed by Ctrl+Tab, volla "Own stuff/" should be pasted.\nAnd last but not least the file "Great Logo.64Cols", you then enter gre, press Ctrl+Tab, and get "Great Font.8Cols", ups!, just press Ctrl+Tab again to get next match, if you get to far you press Ctrl+Shift+Tab for previous match.\n\n@EndNode\n\n@Node ToDo "Look forward to this..."\n\n"Amiga + Shift + c", append string to clipboard, like PowerSnaps "Multi Snap".\n\n"Amiga + Shift + v", clear string before pasting, idea from MCP!!!\n\nThese two suggestions would conflict with "Send key to win", since c would be impossible to send, and this is often used as Cancel, so I will think twice before implementing this.\n\n\nFirst time stringgad. is activated, everything should be blocked, a cursor move would then unblock, or a key press would clear...\nThis idea is adapted from Windows, and I''m not quite sure that I would like it implemented, but in some cases it would be cool (Performer!)\n\n\nPlease @{" SNail-/E-Mail " Link Author} me some more suggestions, or comment the Windows idea!\n\n@EndNode\n\n@Node Bugs "Bugs in BetterEdit"\n\nProblems so far...\n\nIf the last character in the block, or the character under the cursor (only in blockmode!) has negative textspacing, you might experience some cosmetical problems.\n\nWhen the cursor is placed last in the string gadget, and blockmode is on, I have some problems desiding how big the cursor actually is.\n\nUsing muFS be aware that if you start @{Prg} before multiuser.library has been activated, the @{Prg} process will belong to nobody, and you can''t @{" FileNameComplete " Link FNC} the contents of directories without the r-flag set for others.\n\nWhen the string gadget is empty, the cursor will not change color when @{" BlockMode " Link Blocking} is selected.\n\n\n@{B}If you find other bugs or just have some suggestions, call/write or visit me! @{" I''ll Do That " Link Author}@{UB}\n\n@EndNode\n\n\n@Node Author "I did it"\n\n@{Prg} was done by:\n@{JCenter}\nAllan "Duff" Odgaard\nDagmarsgade 36\nDK-2200 Copenhagen\nPhone: (+45)35821112\nEMail: [email removed]\n\nIt was released as @{B}rOYAL-WaReZ@{UB}, and if you like and use it, you should consider to call a Royal board, or you could send me a small donation!\n\n@{B}Atleast send me an EMail!@{UB}\n@EndNode\n\n\n@Node History "The making of BetterEdit."\n\n@{fg HighLight}@{Prg} V1.3  (9-Feb-96):@{fg Text}\n-----------------------------\nReleased on AmiNet!!!\n\nCan be stared from WB (Credits goes out to Cryo)\n\nSome minor bugfixes.\n\nNow Amiga-x will only copy the string into clipboard\nin blockmode; Demanded by Sune Foldager and Mads Henriksen\n-----------------------------\n\n@{fg HighLight}@{Prg} V1.2  (16-Jan-96):@{fg Text}\n-----------------------------\nFilename completion works with AmiFileSafePro,\nthis isn''t a bug in BetterEdit, but in AFSP!!!\n\nYou can now name-complete files starting with:\n''"'', ''>'' & ''='' - Unfortunatly you can''t use these\n3 characters as part of your volumename...\nE.g. Echo "foo" >T:b... (Would work)\n     Setting=EnvA... (Would also work)\n     "RAM:Clipbo... (Ofcoz'' it worls)\n\n(The filename analysation routine will soon be\n      rewritten, to a more clever routine....)\n-----------------------------\n\n@{fg HighLight}@{Prg} V1.1  (05-Nov-95):@{fg Text}\n-----------------------------\nWorks 100% with MUI and ReqTools Stringgadgets.\n\nAdded Amiga key as qualifier for Filename completion.\n\nEsc will now inactive the gadget (this is NOT the same as return)\n-----------------------------\n\n@{fg HighLight}@{Prg} V1.0  (30-Oct-95):@{fg Text}\n-----------------------------\nIn @{" BlockMode " Link Blocking}; the selected text is now inverted.\nAlso the cursor changes color.\n\n@{" Amiga + Key " Link Funcs} (optional shift), will send\na keypress to the active window.\n-----------------------------\n\n@{fg HighLight}@{Prg} V0.9ß (07-Oct-95):@{fg Text}\n-----------------------------\nBeta release.\n-----------------------------\n\n\n@EndNode\n','\n',char(10)),NULL,'auto-added',13244,5,0,NULL,NULL,'ryl_be13','scan',1780048704);
INSERT INTO door_catalog VALUES('ryl_cc10','RYL-CC10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RYL-CC10.LHA',NULL,'XIM','RexxSupport.library',NULL,NULL,'RYL','___________ __________|   |_______ |   | \_ ___    / ____ \    |   |\____  \_   |___. |  _/  _/.    /  \____  _|   _    |   |   |',replace('                      .___.        .___.    \n___________ __________|   |_______ |   |    \n\_ ___    / ____ \    |   |\____  \_   |___.\n |  _/  _/.    /  \____  _|   _    |   |   |\n |__\     |_______/   /  \_________|__ `   |\n ----\____|------/________\[pRESENTS!]\____|\n                                            \n  CCM V1.0 - HI QUALITY CC MANAGEMENT TOOL  \n                                            \n    -  - -------------------------- -  -    \n','\n',char(10)),'CCM.doc',replace('\n                 CCM V1.0 was written by Apollo of Royal!\n\niNTRODUCTION\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nWhat is this ? I''m not gonna tell you ! If you don''t know it, then it''s of\nno use to you.\n\n\niNSTALLATION\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n- Copy stuff to correct dirs, as always.\n- Put cards in Doors:CCM/CClist.txt. Like this:\n\n13097371936324\n01843753792340\n47194650164671\n32669976477672\n43326767466773\n.. etc ..\n\n- Edit Password.cfg and set a Master Entry PW.\n\n- Better protect CCList.txt and Password.cfg to restricted in ACP like this:\n\n  RESTRICT.<numb>=   - tells ACP to place a filenote on the specified\n                       file. This prevents users from viewing or\n                       downloading the restricted files.\n\n  and in your SHELL and SYSOPDOWNLOAD doors. Also protect the whole DOORS:CCM\n  and DOORS:CCM/ACCOUNTS dir. Now don''t say I didn''t warn you.\n\nNo more installation hassle.\n\n\nsHORT pROGRAM oVERVIEW\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nThis door offers:\n\n- One big entry PW (Doors:Password.cfg)\n- User-definable account PW''s for good security.\n- Easy to add ''n use Cardslisting (Doors:CCM/CClist.txt)\n- Easy to edit UserAccounts (Doors:CCM/Accounts/Username.ACC)\n- Cards in Cardslist get commented with username and time-date when sold.\n- Sysop can easy see amount of cards in list, amount sold and amount\n  available.\n- Possibillity for sysop to open account and give cards to user that didn''t\n  have an account before, without assigning the account a password.\n  (User does that on 1st time use)\n- Reliable code, no errors in Cards calculations, no backdoors, etc.\n\n\nhOW iT woRX\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nVery simple, just follow the prompts. Every user that knows the Master\nEntry PW can create an (empty) account at first time they enter the door.\n\nThis account will be stored in the Accounts/ directory, with the username\nand a .ACC appended. Not the standard username, coz that probably contains\nAmigados chars like : / * # and ? . these chars will be replaced by _\nchars. \n\nWhen New Users open this account, all they have to do is to pick their own\nPW for later entry in their account. When they succeeded in picking a valid\n(minimal 5 chars long) Password, the account will be saved. At that point\nit will look like this:\n\n---------------------------------[TOP]--------------------------------------\nUSERPW\n0\n--------------------------------[BOTTOM]------------------------------------\n\nUserPW is the PW the user picked and 0 is the amount of Cards the user has\non his balance. (This can only be raised by the SysOp). When account\ncreation has finished, the user will proceed to main section.\n\nHowever, a SysOp can choose to create an account for a user before the user\nhas entered the door. In this way the Sysop can give a certain user Cards\nbefore this user has entered the door. He creates an Accounts/UserName.ACC\nwith username ''converted'' as describes above. Only, the sysop BLANKS the\nUserAccount PW. When the Sysop would set the balance for such a user to 8\ncards, the username.acc file would look like this:\n\n---------------------------------[TOP]--------------------------------------\n\n8\n--------------------------------[BOTTOM]------------------------------------\n\nWhen the user enters the door and this account is located, the door will\nreport that there exists an pre-created account, created by Sysop.\nThe user will then be able to add an PW to it and from then, it''s just\nlike a normal account.  After this ''alternative'' account creation,\nuser will also proceed to main section.\n\nThe main section is the part where a user actually can get his cards.\nIt could look like this:\n\n---------------------------------[TOP]--------------------------------------\n\n\n\n         Name: -X# cEWLDUDe/nICEGROUp #X-\n Your Balance: 14\n\n\nWithdraw ? (y/N) \n----------------------------------------------------------------------------\n\nWhen a user has Sysop Access (255), it will look like this:\n\n---------------------------------[TOP]--------------------------------------\n\n\n\nSysop Extended Info\n\nList Contains: 250\n         Sold: 172\n     In Stock: 78\n\n         Name: -X# cEWLDUDe/nICEGROUp #X-\n Your Balance: 14\n\n\nWithdraw ? (y/N) \n----------------------------------------------------------------------------\n\nWhen a user hits Yes, the door could say ''Your balance is zero!'' but in\nthis example the dude has 14 cards he can withdraw. So, it will look like\nthis:\n\n----------------------------------------------------------------------------\nWithdraw how many: 3\n\nDo you really want to withdraw 3 pieces ? (Y/n) \n\nProcessing your request .....\n\n\nOrder processed.\n\nPress a key to download your withdrawal.\n\nInitiating Download.\n\n\nTransfer completed.\n\n\nThank you for using our service. Meet you again !\n----------------------------------------------------------------------------\n\nAnd the door will exit. But, also possible is the following situation:\n\n----------------------------------------------------------------------------\nList Contains: 250\n         Sold: 213\n     In Stock: 37\n\n         Name: Moron!/Nightshift\n Your Balance: 44\n\n\nWithdraw ? (y/N) \n\nWithdraw how many: 40\n\nDo you really want to withdraw 40 pieces ? (Y/n) \n\nProcessing your request .....\n\nWe are running low on stock. Unable to transfer 40 pieces.\nMaximum at the moment is 37.\n\n[KEY]\n----------------------------------------------------------------------------\n\nAnd another possibillity in this example is:\n\n----------------------------------------------------------------------------\nWithdraw ? (y/N) \n\nWithdraw how many: 46 \n\nDo you really want to withdraw 46 pieces ? (Y/n) \n\nProcessing your request .....\n\nMaximum withdrawal is only 44 !\n\n[KEY]\n----------------------------------------------------------------------------\n\nOf course withdrawals like 0 or -1 or -72172 or ddsg etc etc are not\naccepted. But back to the first example. The user downloads the cards. What\nactually does this download look like? well, like this:\n\n                        -  - ----------------- -  -\n                              CARDS DELIVERY\n                        -  - ----------------- -  -\n \n                              Transferred 02\n \n                              Old Balance 13\n                              New Balance 11\n \n                              Date: 10/02/95\n                              Time: 11:03:50\n \n                        -  - ----------------- -  -\n \n                              47164036736472\n                              37295759274952\n \n                        -  - ----------------- -  -\n                              USE ''M WISELY!\n                        -  - ----------------- -  -\n                              PLEASANT CALLS\n                        -  - ----------------- -  -\n\nThis textfile will be temporarily stored as T:Delivery.txt, and after the\ndoor exits will be deleted, and copied to Doors:CCM if download was\nunsuccessfull, to check things out.\n\nThe cards that are being sold get commented in the CClist.txt, like this:\n\n47164036736472 (SOLD to Moron!/Nightshift at 10/02/95 - 12:14:16)\n37295759274952 (SOLD to Moron!/Nightshift at 10/02/95 - 12:14:16)\n\nWell I think I covered all now. Any questions, just contact me, if you know\nhow.\n','\n',char(10)),NULL,'auto-added',10545,3,0,NULL,NULL,'ryl_cc10','scan',1780048704);
INSERT INTO door_catalog VALUES('ryl_cc11','RYL-CC11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RYL-CC11.LHA',NULL,'XIM','RexxDosSupport.library',NULL,NULL,'RYL','___________ __________|   |_______ |   | \_ ___    / ____ \    |   |\____  \_   |___. |  _/  _/.    /  \____  _|   _    |   |   |',replace('                      .___.        .___.    \n___________ __________|   |_______ |   |    \n\_ ___    / ____ \    |   |\____  \_   |___.\n |  _/  _/.    /  \____  _|   _    |   |   |\n |__\     |_______/   /  \_________|__ `   |\n-----\____|- /X -/________\-[dESIGN!]-\____|\n       PRESENTS: CCM V1.1  [/X DOOR!]       \n cOOL CC mANAGEMENT tOOL! eVERY *cOOL* cARD-\n   sUPPLIER sHOULD uSE iT! IOTSA fEATURES,  \n     tHE bEST oF tHE bEST! cHECK iT oUT!    \n','\n',char(10)),'CCM.doc',replace('==============================================================================\n              ROYAL /X DESIGN - ROYAL - WE ROOLED ONCE AGAIN!\n==============================================================================\n\n                    CCM was written by Apollo of Royal!\n\niNTRODUCTION\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nWhat is this ? A CC Account door, easy withdrawing of cards for your users,\nno need for them to take all cards at one time, just like a bankaccount.\n\nsHORT pROGRAM oVERVIEW\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nThis door offers:\n\n- Great Design by Whirlwind/RYL!\n- Very Userfriendly menu''s.\n- One big entry PW. (Doors:Password.cfg)\n- User-definable account PW''s for good security.\n- Easy to add ''n use Cardslisting (Doors:CCM/CClist.txt)\n- Easy to edit UserAccounts datafile (Doors:CCM/Account.dat)\n- Cards in Cardslist get commented with username and time-date when sold.\n- Manager can easy see (amount of) cards in list, amount sold, amount\n  available, userlisting, and a lot more.\n- Possibillity for Manager to give cards to user that didn''t have an account\n  before, without assigning a password to the account. (User does that ''mself)\n- Reliable code, no errors in Cards calculations, no backdoors (Check it,\n  it''s just AREXX), etc.\n- 2 backups are kept of accounts file and cards file, updated every startup.\n  (back one yourself also ofcoz)\n- Possibillity to add cards from remote, etc. Everything that the sysop could\n  do, can be done remotely by a Manager if he has Manager Access and the PW.\n- Lot more I can''t think of.\n\n\niNSTALLATION\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n- Copy stuff to correct dirs, as always.\n\n- Put cards in Doors:CCM/CClist.txt. Like this:\n\n13097371936324\n01843753792340\n47194650164671\n32669976477672\n43326767466773\n.. etc ..\n\nJust one card per line, cards must always be 14 digits long. If cards\nexist that are longer/shorter, I will fix in an update.\n\n- Edit the Doors:CCM/CCM.cfg . Should look like this:\n\n----------TOP OF FILE------------------------------------\nMain Entry PW\nManager Section PW\nName of dude 1 with Manager Access\nName of dude 2 with Manager Access\nName of dude 3 with Manager Access\netc...\n----------END OF FILE------------------------------------\n\n- Protect all files from CCM in ACP, Shell and DS doors.\n\n  I mean especially those files:\n\n  - CCM\n  - CCM.rexx\n  - CClist.txt\n  - CClist.txt.bak\n  - CClist.txt.bak.bak\n  - Account.dat\n  - Account.dat.bak\n  - Account.dat.bak.bak\n  - CCM.cfg\n  - Delivery.txt\n  - and all other valuable files.\n\n  Now don''t say I didn''t warn you.\n\n\nNo more installation hassle.\n\n\nhOW iT woRX\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nVery simple, just follow the prompts. Every user that knows the Master\nEntry PW can create an (empty) account at first time they enter the door.\nThis account will be stored in the Account.dat file.\n\nWhen New Users open this account, all they have to do is to pick their own\nPW for later entry in their account. When they succeeded in picking a valid\n(minimal 5 chars long) Password, the account will be saved. At that point\nit will look like this:\n\n.----------------------------------------------------------------------------.\n| -< CC MANAGER 1.0 ACCOUNT DATA FILE >-< DO NOT CHANGE POSITION LAYOUT ! >- |\n+-----.------------------------------.-------------------.-------------------+\n|CARDS| NAME                         | PASSWORD          | LAST WITHDRAWAL   |\n+-----+------------------------------+-------------------+-------------------+\n| 000 | UserName                     | User PW           |                   |\n`-----^------------------------------^-------------------^-------------------''\n\nUserPW is the PW the user picked and 0 is the amount of Cards the user has\non his balance. (This can be raised by the SysOp). When account creation has\nfinished, the user will proceed to main section. Note: All passwords with\nthis door are not case-sensitive. (I Hate That!)\n\nHowever, a SysOp can choose to create an account for a user before the user\nhas entered the door. In this way the Sysop can give a certain user Cards\nbefore this user has entered the door. He creates an entry in the account.dat\nwith username, and amount of cards. Only, the sysop BLANKS the UserAccount\nPW. When the Sysop would set the balance for such a user to 8 cards in an\nalready active account.dat file, it could look like this:\n\n.----------------------------------------------------------------------------.\n| -< CC MANAGER 1.0 ACCOUNT DATA FILE >-< DO NOT CHANGE POSITION LAYOUT ! >- |\n+-----.------------------------------.-------------------.-------------------+\n|CARDS| NAME                         | PASSWORD          | LAST WITHDRAWAL   |\n+-----+------------------------------+-------------------+-------------------+\n| 015 | mORON/nIGHTSHIFT             | beretta           | 03/12/94 12:41 08 |\n| 008 | NewDude/YouCreated           |                   |                   |\n| 043 | Bobbit/Jammerz               | CC CC CC 34       | 02/10/04 22:43 05 |\n`-----^------------------------------^-------------------^-------------------''\n\nWhen the user (Newdude/youcreated) enters the door and the account is located,\nthe door will report that there exists an pre-created account, created by\nSysop.  The user will then be able to add an PW to it and from then, it''s\njust like a normal account.  After this ''alternative'' account creation,\nuser will also proceed to main section.\n\nThe main section is the part where a user actually can get his cards.\nThis is a menu with some self-explainable options, one of them is Withdraw\nCards. The user has to enter the amount of cards he wants to withdraw from his\nbalance, and these cards (if enough stock) will get written to a temporary\nfile in T: , the T:Delivery.txt .. it will look like this:\n\n                        -  - ----------------- -  -\n                              CARDS DELIVERY\n                        -  - ----------------- -  -\n \n                              Transferred 02\n \n                              Old Balance 13\n                              New Balance 11\n \n                              Date: 10/02/95\n                              Time: 11:03:50\n \n                        -  - ----------------- -  -\n \n                              47164036736472\n                              37295759274952\n \n                        -  - ----------------- -  -\n                              USE ''M WISELY!\n                        -  - ----------------- -  -\n                              PLEASANT CALLS\n                        -  - ----------------- -  -\n\nafter download this file will get deleted, or moved to the FailTransfer dir\nif download failed, to check things out.\n\nThe cards that are being sold get commented in the CClist.txt, like this:\n\n47164036736472 (SOLD to Moron!/Nightshift at 10/02/95 - 12:14:16)\n37295759274952 (SOLD to Moron!/Nightshift at 10/02/95 - 12:14:16)\n\nand in the accounts.dat the sysop can see the date, time and amount of cards\nthe user took on his last withdrawal, of course the log also serves well\nfor this. the logname is always Username.log , with the DOS chars like / #\n? etc replaced by a ''_'', to not get troubles.\n\nWell I think I covered all important stuff now. Just check it out yourself,\nthe menu''s will guide you, it''s self-explanatory I guess.\n\nAny questions, bugreports, get new updates, just contact me, if you know how.\n\n==============================================================================\n              ROYAL /X DESIGN - ROYAL - WE ROOLED ONCE AGAIN!\n==============================================================================\n','\n',char(10)),NULL,'auto-added',21141,3,0,NULL,NULL,'ryl_cc11','scan',1780048704);
INSERT INTO door_catalog VALUES('ryl_ch10','RYL-CH10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RYL-CH10.LHA',NULL,'XIM','.___.        .___.',NULL,NULL,'RYL','___________ __________|   |_______ |   | \_ ___    / ____ \    |   |\____  \_   |___. |  _/  _/.    /  \____  _|   _    |   |   |',replace('                      .___.        .___.    \n___________ __________|   |_______ |   |    \n\_ ___    / ____ \    |   |\____  \_   |___.\n |  _/  _/.    /  \____  _|   _    |   |   |\n |__\     |_______/   /  \_________|__ `   |\n ----\____|------/________\[pRESENTS!]\____|\n ChatSelect 1.0 - Use a different Startchat\n for each sysop! - Check it out! - For /X!\n -------------------------------------------\n','\n',char(10)),'ChatSelect.Doc',replace('\n                                    .____.            .____.\n        _____________ ______________|    | __________ |    |\n        \_  ___     / _____   \     |    |_\______   \_    |____.\n         |   _/   _/.     /    \_____   _|     ___    |    |    |\n         |___\      |__________/    /   \|____________|___ `    |\n        ------\_____|---------/__________\---[PRESENTS:]--\_____|-\n\n                    - -- ---^(ChatSelect 1.0)^--- -- -\n                          © (?) iCE/CDS^RYL 1995\n\n\nWHAT IS THIS?\n-------------\nNothing very stunning... This is a tiny door that let''s you choose another\nSTARTCHAT, for instance if your cosysop is in the room, or is your brother\nor something.\n\n\n\nREQUIREMENTS:\n-------------\nProperly  running  Arexx.   Rexxdoor  in  BBS:Utils/ and an assigned DOORS:\ndrawer.   Tested  on a 2500/030 - 5 mb Ram - /X 4.8, but there should be no\nproblems with other configurations.\n\n\n\nINSTALLATION:\n-------------\n/X 3.xx+\n\nCopy All the files from the archive to the right drawers.\nNow copy your BBS:nodex/STARTCHAT.??? to doors:RYL-ChatSelect/StartChat.1.???\nMake the BBS:nodex/StartChat.??? like this:\n\n------------------\n~CC_CHATSELECT\n------------------\n\nOkay... now edit the file DOORS:RYL-CHATSELECT/CHATSELECT.NAMES.\nThis file works like this:\n\n------------------\n3           <- Number of sysops\niCE         <- Sysop #1 (This is the DEFAULT sysop!)\nDutchie     <- Sysop #2\nChip        <- Sysop #3\n------------------\n\nNow when you''ve entered all your cosysops, go on and edit the files\nDOORS:RYL-ChatSelect/STARTCHAT.X.??? (where X is the sysop number) \nto your needs.  \n                                 \nOkay.. the door handles the STARTCHAT.X just like /X does, ie with acces\nlevels and screentype extensions... You know what I mean, I suppose.. \n\nThat was it!\n\n/X 2.xx & S!X\n\nDunno,  but  it  won''t cause any problems if you install it as a normal AIM\ndoor, I suppose.\n\n\n\nUSING THE DOOR\n--------------\nWell.. that''s quite easy... You just enter the chat and ONLY YOU will see\nsomething like this:\n\n___________________________________________________________________________\nChatSelect 1.0                                               ¡CE/ROYAL 1995\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nChat with: [1] ¡CE  [2] Dutchie\n\n\nYou just hit the number of your startchat and there ya go!\nIf you''re drunk or just a very stoopid person, ya might hit a wrong key..\nin that case, the door will select sysop 1, wich shall be the sysop who''s\navailable most of the times.\nThe good part about this door is that the user probably don''t even notices\nit! Except for a blank line or something, nothing happens at the user''s\nside!\n\n\n\nCONTACT ME!\n-----------\nAnd that was all!  Hope you can use this little door!  Contacting me:  Call\nthe  ¡NTERSpHERE  at  +31-2290-35368W414, and page me!  The number probably\nwill  be  changed  in  april/may  so look around for the new one, then!  Or\nleave me mail at any major Dutch board.\n(ie: THE UNDISCOVERED - BEYOND LIMITS - ORGASM - hehehehe... Plugging\n     boards roolz! Hi mates!)\n\n\n\nBUGS!?\n------\nDon''t see any reason why the door would bug... \n\n\n\nBBS PLUG:\n---------\n\n\n        ________________.___________________________________      ·\n        \_________\_     \   \____    ____   ____\_    ___  \_    :\n        .|          \_    \    \_       \_    __\____    _   /__  ¦\n        :|           /          /        /    \     /    \     /  ¦\n        ¦l______   ·/____\    ·/_____  ·/______   ·/_____/    /::.¦\n        `------\___/------\___/-----\__/------\___/------\___/----''\n_______________________________.________________________________________\n\_    ______\_          \_     |    \_     _____\_          \_     _____\_\n |           |     l___  |     _     |     ______|     l_____|     ______|\n l______     |     ______|     |     |     l     |     |     |     l     |\n l___________l_____|     l_____|_____l___________l_____|!sCf!l___________|\n       Roøl¡Ng aT 14k4 (yEah RiTe) - +31-2290-35368-W414 - CDS WHQ \n    ÆM¡GÆ-/X-TøøLS-©øN5øLeS-mØd5-ReQµe5Ts-¡N5åNe s¥sOp-Nø FuCK¡N'' Pc''S!\n     \n                     Ya CaLLeD... And GoT nO CoNNecT!\n                  A. Add sum secs to yar dialer timeout!\n     B. You accidently got a dude on the phone, and hung op.. (DON''T!)\n                            C. You''re støøpiD!\n\n\n\nHISTORY:\n--------\nv 1.0 - First release, and guess what?? This version!\n\n\n\nFUTURE:\n-------\nErr, dunno... maybe an inproved design.. Contact me and make suggestions!\n\n\n\nGREETINGS!\n----------\n\n    Muad''Dib/IFT (o-kee!), WishBringer/HOS, LightNing ,Exotic/ACS^POSSE\n    Track/¿, Veteran/CCN, Sir IQ, (Good luck with MB dudes!), Pyxis/CCN\n  Funz/CCN, mAC/CCN, Midnight Caller/CCN, Eurobyte/CCN, Motive Power/MST\n    KillRaven/MST, The Brain/Nix, Delite/RYL^BTW^CRY, Pinokio/BTW^RYL,\n    ScarFace/Edge, Hawk,Radavi&MSW/EFFECT, D-Lorean/Myth (whahahha!),\n    THC/Myth,  PLL/Myth, Koud?, NightCrawler/Indy, aXeBlade/AC!/JeTsEt, The\nDesert Dancer (het font is lelijk!), Tom, Zack/STD, CHIP/ROYAL,Jake/PSG\n MEGA^FORTRESS/ROYAL,  PsYCHLOP  (crickits!), Jarre/Indy, D''Style,Magic/MRG\nWhirlWind & Apollo/ROYAL, The Edge, Stephen King, Neoplasia, Iris DK,\n Defiance Sweden, Sper/Spirit, all CDS members, the former Estate Staff &\n     his slaves and all dudes in Houten 1995 (including Courbois)...\n\n          And ofcourse all (*) R O Y A L (*) members worldwide!\n\n\n\nCALL OUR BOARDS:\n----------------\n                            .____.            .____.\n_____________ ______________|    | __________ |    |\n\_  ___     / _____   \     |    |_\______   \_    |____.\n |   _/   _/.     /    \_____   _|     ___    |    |    |\n |___\      |__________/    /   \|____________|___ `    |\n------\_____|---------/__________\----------------\_____|--------------------\n \n                         * bOARDS! *\n \n     Digital Extasy  - +1-ASK-ELITE! - USHQ [4 NODES RD/16K8]\n       Dutch Dreams  - +31-ASKELITE! - WHQ  [1 NODE/14K4 (SOON 3 NDS)]\n         StoneHenge  - +31-ASKELITE! - DHQ  [1 NODE/14K4 (SOON 28K8)]\n           Homeless  - +49-ASKELITE! - EHQ  [1 NODE/14K4 (SOON 2 NDS)]\n         Phoenix II  - +46-ASKELITE! - SHQ  [1 NODE/??K?]\n \n                    * aFFILIATED bOARDS! *\n \n             The Lab - +31-KILL4IT! - Prof B-Rom\n               Delta - +31-KILL4IT! - Eagle\n       MF Enterprise - +31-KILL4IT! - Mega Fortress\n             IQ Zero - +31-KILL4IT! - Pinokio\n          Dreamphase - +46-KILL4IT! - Bubba\n         ¡NTERSpHERE - +31-KILL4IT! - ¡CE\n \n----------------------------------------[YOU CAN RUN, BUT YA CAN''T HIDE!]----\n\n','\n',char(10)),NULL,NULL,6067,1,0,NULL,NULL,NULL,'scan',1780048704);
INSERT INTO door_catalog VALUES('ryl_cs16','RYL-CS16.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RYL-CS16.LHA','info','XIM','HuntVirus','1.6',NULL,'RYL',NULL,replace('ROYAL PRESENTS COOLSTATS V1.6 /X4.XX\n','\n',char(10)),'CoolStats.Doc',replace('\n                                    .____.            .____.\n        _____________ ______________|    | __________ |    |\n        \_  ___     / _____   \     |    |_\______   \_    |____.\n         |   _/   _/.     /    \_____   _|     ___    |    |    |\n         |___\      |__________/    /   \|____________|___ `    |\n        ------\_____|---------/__________\---[PRESENTS:]--\_____|-\n\n                    - -- ---^(CoolStats v1.6)^--- -- -\n                            © iCE/CDS^RYL 1995\n\nWHAT IS THIS?\n-------------\nWell,  what''s  this!?   Nothing  special,  just another status door for /X.\nThere are dozens of status doors, but they all didn''t show what I wanted to\nknow.   So I `coded'' my own in Arexx.  Nothing special.  Sum of the credits\nfor  the design must go out to Muad''dib `de kleine vervelende dwerg'' / DLT.\nI used his LHA/LZX checker design for ideas.\n\nREQUIREMENTS:\n-------------\nProperly  running  Arexx.   Rexxdoor  in  BBS:Utils/ and an assigned DOORS:\ndrawer.   Tested  on a 2500/030 - 5 mb Ram - /X 4.8, but there should be no\nproblems with other configurations.\n\n\nINSTALLATION:\n-------------\n/X 3.xx+\n\nCopy All the files from the archive to the right drawers. Finished!\n\n/X 2.xx & S!X\n\nDunno,  but  it  won''t cause any problems if you install it as a normal AIM\ndoor, I suppose.\n\n\nCONTACT ME!\n-----------\nAnd that was all!  Hope you can use this little door!  Contacting me:  Call\nthe  ¡NTERSpHERE  at  +31-2290-35368W414, and page me!  The number probably\nwill  be  changed  in  april/may  so look around for the new one, then!  Or\nleave me mail at any major Dutch board.\n\nBUGS!?\n------\nThe door will fuck up if you''ve a enourmes amount of bytes left.  Can''t fix\nthis.  :(\n\n\nBBS PLUG:\n---------\n\n\n        ________________.___________________________________      ·\n        \_________\_     \   \____    ____   ____\_    ___  \_    :\n        .|          \_    \    \_       \_    __\____    _   /__  ¦\n        :|           /          /        /    \     /    \     /  ¦\n        ¦l______   ·/____\    ·/_____  ·/______   ·/_____/    /::.¦\n        `------\___/------\___/-----\__/------\___/------\___/----''\n_______________________________.________________________________________\n\_    ______\_          \_     |    \_     _____\_          \_     _____\_\n |           |     l___  |     _     |     ______|     l_____|     ______|\n l______     |     ______|     |     |     l     |     |     |     l     |\n l___________l_____|     l_____|_____l___________l_____|!sCf!l___________|\n       Roøl¡Ng aT 14k4 (yEah RiTe) - +31-2290-35368-W414 - CDS WHQ \n    ÆM¡GÆ-/X-TøøLS-©øN5øLeS-mØd5-ReQµe5Ts-¡N5åNe s¥sOp-Nø FuCK¡N'' Pc''S!\n     \n                     Ya CaLLeD... And GoT nO CoNNecT!\n                  A. Add sum secs to yar dialer timeout!\n     B. You accidently got a dude on the phone, and hung op.. (DON''T!)\n                            C. You''re støøpiD!\n\nHISTORY:\n\nv 1.0 - Nutting new. First Release\nv 1.1-1.3 - Lotsa bugs fixed. Not released. \nv.1.4- You release a door. You sit back and relax. Then you try the door\n       again with sum changed stats and you see that the door fucks up totally.\n       So you release another version, 1 hour after the first. Ain''t life\n       great!? Thanx to Midnight Caller/Cocaine/Scepcis for helping me\n       testing!\nv.1.5- Added top Cps stats after a day of searching trough the source \n       why the damn thing didn''t want to read the user.keys.\n       Again, Thanx to Midnight Caller for bringing me a sourcecode!\nv.1.6- Bug fix.\n       Saw the "RED=WHITE" bug from /X at the Atmosphere.\n       (Call the Atmosphere - Sysop=Delite/Myth - +31-FIGHTFORIT!)\n       Released under ROYAL.\n\n\n\nFUTURE:\n-------\nMore facts to display. More configurable.\nContact me for more!\n\n\nGREETINGS!\n----------\n\n    Muad''Dib/IFT (o-kee!), WishBringer/HOS, LightNing ,Exotic/ACS^POSSE\n    Track/¿, Veteran/CCN, Sir IQ, (Good luck with MB dudes!), Pyxis/CCN\n  Funz/CCN, mAC/CCN, Midnight Caller/CCN, Eurobyte/CCN, Motive Power/MST\n    KillRaven/MST, The Brain/Nix, Delite/RYL^BTW^CRY, Pinokio/BTW^RYL,\n    ScarFace/Edge, Hawk,Radavi&MSW/EFFECT, D-Lorean/Myth (whahahha!),\n    THC/Myth,  PLL/Myth, Koud?, NightCrawler/Indy, aXeBlade/AC!/JeTsEt, The\nDesert Dancer (het font is lelijk!), Tom, Zack/STD, CHIP/ROYAL,Jake/PSG\n MEGA^FORTRESS/ROYAL,  PsYCHLOP  (crickits!), Jarre/Indy, D''Style,Magic/MRG\nWhirlWind & Apollo/ROYAL, The Edge, Stephen King, Neoplasia, Iris DK,\n Defiance Sweden, Sper/Spirit, all CDS members, the former Estate Staff &\n     his slaves and all dudes in Houten 1995 (including Courbois)...\n\n          And ofcourse all (*) R O Y A L (*) members worldwide!\n\n\n\nCALL OUR BOARDS:\n----------------\n                            .____.            .____.\n_____________ ______________|    | __________ |    |\n\_  ___     / _____   \     |    |_\______   \_    |____.\n |   _/   _/.     /    \_____   _|     ___    |    |    |\n |___\      |__________/    /   \|____________|___ `    |\n------\_____|---------/__________\----------------\_____|--------------------\n \n                         * bOARDS! *\n \n     Digital Extasy  - +1-ASK-ELITE! - USHQ [4 NODES RD/16K8]\n       Dutch Dreams  - +31-ASKELITE! - WHQ  [1 NODE/14K4 (SOON 3 NDS)]\n         StoneHenge  - +31-ASKELITE! - DHQ  [1 NODE/14K4 (SOON 28K8)]\n           Homeless  - +49-ASKELITE! - EHQ  [1 NODE/14K4 (SOON 2 NDS)]\n         Phoenix II  - +46-ASKELITE! - SHQ  [1 NODE/??K?]\n \n                    * aFFILIATED bOARDS! *\n \n             The Lab - +31-KILL4IT! - Prof B-Rom\n               Delta - +31-KILL4IT! - Eagle\n       MF Enterprise - +31-KILL4IT! - Mega Fortress\n             IQ Zero - +31-KILL4IT! - Pinokio\n          Dreamphase - +46-KILL4IT! - Bubba\n         ¡NTERSpHERE - +31-KILL4IT! - ¡CE\n \n-----------------------------------------------------------------------------\n\n-EOF-\n','\n',char(10)),NULL,'auto-added',18941,7,0,NULL,NULL,'ryl_cs16','scan',1780048704);
INSERT INTO door_catalog VALUES('ryl_dl13','RYL-DL13.LZX','~/Code/amiexpress_doors/Archives/AmiExpress/RYL-DL13.LZX',NULL,'XIM','DL-Today',NULL,NULL,'RYL',NULL,NULL,NULL,NULL,NULL,'auto-added',11733,0,0,NULL,NULL,'ryl_dl13','scan',1780048704);
INSERT INTO door_catalog VALUES('ryl_dsp2','RYL-DSP2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RYL-DSP2.LHA','cLICK-mE!','XIM','.___.        .___.                      :',NULL,NULL,'RYL','___________ __________|   |_______ |   |                      . \_ ___    / ____ \    |   |\____  \_   |___. |  _/  _/.    /  \____  _|   _    |   |   |',replace('                      .___.        .___.                      :\n___________ __________|   |_______ |   |                      .\n\_ ___    / ____ \    |   |\____  \_   |___.\n |  _/  _/.    /  \____  _|   _    |   |   |\n |__\     |_______/   /  \_________|__ `   |\n ----\____|------/________\[ /X dEV.!]\____|\n\n            ·p·r·e·s·e·n·t·s·\n         -( DISKSPACE V2.0.0! )-\n   An outstanding /X tool graphically\n   displays your BBS'' harddrive space.\n      fast code, eXcellent design!\n','\n',char(10)),'DISKSPACE.GUIDE',replace('@database Diskspace documentation\n\nCopyright (c) 1996 ROYAL /X Development.\nAll Rights Reserved\n\n@Remark $VER: (FEB-11-1996)\n@Remark Royal Diskspace documentaion guide.\n\n@node MAIN "Royal Diskspace documentaion guide (FEB-11-1996)"\n\n\n                                    .____.            .____.\n        _____________ ______________|    | __________ |    |\n        \_  ___     / _____   \     |    |_\______   \_    |____.\n         |   _/   _/.     /    \_____   _|     ___    |    |    |\n         |___\      |__________/    /   \|____________|___ `    |\n       .------\_____|---------/__________\----------------\_____|-.\n       |                                                          |\n       |    dISK sPACE V2.0.0 - ROYAL - fINAL rELEASE vERSION!    |\n       |                                                          |\n       `----------------------------------------------------------''\n\n  \n\n\n         \n\n    @{" Introduction                 " Link Cap01}\n    @{" Installation                 " Link Cap02}\n    @{" Version History              " Link Cap03}\n    @{" Copyright                    " Link Cap04}\n    @{" ROYAL!                       " Link Cap05}\n\n\n    Coding, idea and design by Floppy Robby and Clotug.\n    Big thanx to Ramirez/Virtual Theatre, Trion/The Hype,\n                 Minor Threat/TNT and Lord Coma/Lordscave\n    for Bèta-testing, bug reports, mental support etc. (8\n\n@endnode\n@node Cap01 "Introduction of Diskspace XIM"\n  =======================================================================\n\n  Diskspace is a 100% XIM module voor AmiExpress v4.Xx.\n  It checks your HD''s and displays valuabe information on them\n  as nicely designed ANSI graphics.\n  The ANSI design took twice as long as the code (-NOT!-).\n  Coded in Amiga-E with a shitload of help from several sceners (8\n\n  =======================================================================\n\n@endnode\n\n\n@node Cap02 "Installation"\n  =======================================================================\n\n  Unarchive the file RYL-DSP2.LHA and copy everything in the right place\n  Make sure you''ve got BBS:COMMANDS/BBSCMD/SPACE.INFO\n  and in DOORS: a directory ROYAL/DISKSPACE/\n  Diskspace''s icon is named SPACE.INFO, I know that Space Empire\n  does use the same /X command name (read: ICON name) but as we don''t\n  of any /X board that has it still installed nowadays, and because\n  SPACE is the most easy-to-remember word I could think of, we decided\n  to name it SPACE ! (8\n  If you would like to have diskspace to run before each upload, then\n  edit NODE<x>/UPLOADMSG.TXT and insert, preferably on the last line,\n  ~CC_SPACE.\n\n  =======================================================================\n\n@endnode\n\n@node Cap03 "Version History"\n  =======================================================================\n\n  v0.1   - First working CLI version\n\n  v0.3a  - Working Xenolink BBS version.\n           (yes we were running on Xeno then.. sorry (8 )\n\n  v0.6   - Removed a error with locking the information icon\n\n  v0.7   - Buggy /X version (we switched to /X BBS!)\n\n  v1.0   - First release of the working XIM module\n\n  v1.0.1 - Added a color switcher for the bar.\n           When disk is more then 90% full, the bar turns red.\n           (or purple.. if you like that)\n\n  v1.0.2 - Beta version. Only for Trion and Minor Threat.\n           Experimental speed-optimalisation.\n           (buggy!)\n\n  v1.0.3 - Bug report from Ramirez/Virtual theatre:\n           Bar goes mad when the total disksize (all partititions\n            counted together) is bigger then 2048 MB.\n\n  v1.0.5 - Bug doesn''t sem to be removed despite of some enhancements.\n           like a MB to GB switcher etc.\n\n  v1.0.8 - Still not removed. My drive is less then 2048 Mbytes so I''m\n           unable to test it myself.\n           Found a way out to ''cheat'' with the drive info.\n           I''m now able to make a virtual drive of unlimited Gigabytes,\n           even tera- and hexabytes (that''s 2.400.000.000.000.000.000.000\n                                            BYTES so 24 TB or 2.4 HB hehe\n\n  v1.0.9 - V1.0.9 is the first bug-fucking-free version, as it was called\n  v1.1.5   by me after fiddeling for hours with the dos library witout\n           making any progress untill I found the major problem /-: hehe\n           After that the beta-testers found the anims etc. annoying and\n           asked for a super-efficient fast tool.\n           Well I started it all again and did even check all ANSI codes\n           on maximum eficiency.\n\n  v1.1.6 - Release version! Therefor called Diskspace V2.0.0\n\n           Yeah I know that''s I''m a chaotic person!\n           So in order to make things clear, just read the descripion\n           of the FINAL version below. If everything happend as was\n           planned, this should be the only version where YOU can get\n           your hands on. (8\n\n  v2.0.0 - Same as v1.1.6, but wel ljust a V2 to avoid misunderstanding\n           with all those version numbers.\n           If you want to use diskspace, make sure U got V2.0.0 and\n           forget about all the shit above (8\n\n\n  Shit what a mess!\n\n  =======================================================================\n\n@endnode\n\n@node Cap04 "Copyright"\n  =======================================================================\n\n  Non-Royal members:\n  Diskspace is cALL-wARE.\n  What the heck is cALL-wARE?\n  Just gimme a call to my board, @{"Pandarve" Link Cap06}.\n  That''s it! No need for uploads (though I would appreciate it (; )\n\n  Royal members: Just dial 187 or Pandarve and leech the Regged to ROYAL\n  version.\n \n  Weird rules U think? Well I started this door just to learn Amiga E\n  and after a while I chnaged the CLI tool into a Xenolink module...\n  euh.. mistake! So Lord Coma helped me to recode it as a XIM version\n  for /X. But I did never release that version outside of the Royal\n  boards, but there were some non-Royal guys that would like to have\n  this tool so I did give it to them. And the worst thing I could think\n  of happend: A major bugreport! (See @{"Version History" Link Cap03}.\n  It took me a while to fix it, and well the result is here.\n  But to stay loyal to ROYAL members, I upgraded the tool for them in\n  the first place and to stay loyal with the whole scene, I just offer\n  a registration oppertunity! Just a call is enough!\n  (Maybe two if I''m not at home.. I will attach it to a message then,\n   so you can get it with your 2nd call).\n  If there''s a big demand for it I will code a online-free-register tool\n  hehe (8\n  \n  =======================================================================\n\n@endnode\n\n@node Cap05 "ROYAL!"\n  =======================================================================\n\n                                    .____.            .____.\n        _____________ ______________|    | __________ |    |\n        \_  ___     / _____   \     |    |_\______   \_    |____.\n         |   _/   _/.     /    \_____   _|     ___    |    |    |\n         |___\      |__________/    /   \|____________|___ `    |\n       .------\_____|---------/__________\----------------\_____|-.\n       |                                                          |\n       |    dISK sPACE V2.0.0 - ROYAL - fINAL rELEASE vERSION!    |\n       |                                                          |\n       `----------------------------------------------------------''\n\n  \n\n\n  =======================================================================\n\n@endnode\n\n@node Cap06 "PANDARVE"\n \n           [ -+pANdARVE!+- ] [ oNE oF tHE hIPPEST iN eUROPE !!! ]\n \n________________\___ :  _.________________________________:_________\n__ ___   / __    \  \:   :___    \ __    \_  ___  \    \  :_  __   /\n.|  |/  /  \/    /   \   : l/    / \/    /    l/  /  _//   /  l/__/\n|   l__/    \   /   \    | /    /   \   /|  _   _/   \/   /      \__\nl___/  \_____\______|\___|     /\____\___l__/\   \_______/:________/\n«·----------------------l_____/---------------\___/-----·-:-----»\n \n \n \n             ··[ (*) R O Y A L (*) -mACINTOSH dEVISION- DHQ ]··\n \n \n               .     tHE mOST tRENDY bOARD oF eUROPE!\n ·:············:·    \n  :rUNNING     :              -+  fEATURING  +-        oH yEAH\n  /X v4.8      :                                       oUR\n  a4000/030+   :      ___________aMIGA_wAREZ________   nUMBER iS\n  :68882/33Mhz :    ·( dAILY fRESH oVERSEAS iMPORTS )· +31-(0)570-564756\n  :18MB rAM    :      ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯  \n  cYBERvISION64:                                       sIGNED,\n  hPsCANJET²CX :      _______mACINTOSH_gOODIES______   pANDARVE sTAFF\n  eUH.. aND sOME    ·( hARD tO geT, sO gET iT hERE! )·\n  oTHER pRETTY :      ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯   fLOPPY rOBBY,\n  eQUIPmENT (8 :                                       cLOTUG,\n .:............:      _____sHAPEsHIFTER_hELPDESK____   wHIRLWIND,\n  :lIFE''S lIKE :    ·( pROBLEMS wITH mAC eMULATION? )· sTARdUCK aND\n     a bOX oF         ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯   lORD cOMA.\n  cHOCOLATEs...                                        \n   U nEVER kNOW       ________aMIGA_''E''_sTUFF_______   .. yUPPA tHAT''s\n   wHATCHA gONNA    ·(aLL /X-cODERS iN E: sEE tHIS! )· iT, I gUESS....\n       gET...         ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯  \n\n@endnode\n','\n',char(10)),NULL,NULL,15931,2,0,NULL,NULL,NULL,'scan',1780048704);
INSERT INTO door_catalog VALUES('ryl_lc39','RYL-LC39.LZX','~/Code/amiexpress_doors/Archives/AmiExpress/RYL-LC39.LZX',NULL,'XIM','ryl lc39',NULL,NULL,'RYL',NULL,NULL,NULL,NULL,NULL,NULL,13588,0,0,NULL,NULL,NULL,'scan',1780048704);
INSERT INTO door_catalog VALUES('ryl_np11','RYL-NP11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RYL-NP11.LHA','BANGDADRUMz','XIM','BANGDADRUMz',NULL,NULL,'RYL','___________ __________|   |_______ |   | \_ ___    / ____ \    |   |\____  \_   |___. |  _/  _/.    /  \____  _|   _    |   |   |',replace('                      .___.        .___.\n___________ __________|   |_______ |   |\n\_ ___    / ____ \    |   |\____  \_   |___.\n |  _/  _/.    /  \____  _|   _    |   |   |\n |__\     |_______/   /  \_________|__ `   |\n ----\____|------/________\[pRESENTS!]\____|\n NodePW v1.1 - Special NodePW door for /X!\n Easy 2 use! Easy 2 install! Check it out!\n ------------------------------------------\n','\n',char(10)),'nodepw.doc',replace('\n                                    .____.            .____.\n        _____________ ______________|    | __________ |    |\n        \_  ___     / _____   \     |    |_\______   \_    |____.\n         |   _/   _/.     /    \_____   _|     ___    |    |    |\n         |___\      |__________/    /   \|____________|___ `    |\n        ------\_____|---------/__________\---[PRESENTS:]--\_____|-\n\n        - -- ---^(NodePW v1.1 by iCE/ROYAL^CDS 23-MAR-95)^--- -- -\n\n\n\nWHAT IS NODEPW?\n---------------\nJust simple... If you have a private node, you might want a password on it,\nto prevent certain users, wich have found out the number,  to call that\nnode and keep the line busy. So you install a SystemPassword. But all the\nusers that want to connect to your private node have to enter this password\nover and over again, or maybe you already have a system password (ie\n`YES'')... \nWell all this door does is checks if the users name is in a file, and if it\nisn''t, it will ask him for the password. If the user knows it, his name\nwill be added to a file and he''ll never have to enter the password again... \nIf he doesn''t know it, the door will show him a textfile and drops\ncarrier.. And that''s it!\nI saw this idea at the famous, o so gr8 and cewl (hehehe... just call it)\nUndiscovered. The Sysop there, Muad''dib designed this door for his own use,\nbut since there wasn''t anything like this on the market I decided to make\nmy own one.. here it is! \n\n\n\nREQUIREMENTS\n------------\n/X 3.xx (it might work with lower versions.. i dunno..) or higher. \nAssigned DOORS: and a running rexxmaster.\nAn amiga model would be nice.\n\n \n\nINSTALLATION\n------------\nFairly simple.. just copy the files from the archive to the right dirs in\nyour bbs drawer.\nThen edit the following files to your needs:\n\nNodePW.names.X     -> The names file\nNodePW.PW.X        -> The password\nNodePW.X.TXT       -> The `enter password'' text\nNodePW-Fail.X.TXT  -> The `failed PW'' text\n\n(Where X is the nodenumber on wich the door should be active)\n\nMake sure all these files exist for the right node or else the door will\nexit.\nThe 2 textfiles are handles by /X as the usual textfiles... I think you\nknow what I mean, otherwise, close your board. \n\nNow add to your BBS:nodeX/LOGON.??? the line\n----\n~CC_NodePW\n----\n\nAnd that''s it.. you can protect as many nodes as you want with this door..\njust copy the textfiles and rename them to the right nodes... You know what\nI mean.. \n\n\n\nTESTING THE DOOR\n----------------\nCopy NodePW.info from the syscmd to the bbscmd drawer and enter NodePW...\ntata!\n\n\n\nBETA-TESTERS\n------------\nWhirlWind/Royal - 5 minutes, and we discovered the `red=white bug from /X''\nThanx dude!\n\n\n\nCONTACTING ME\n-------------\nJust call my own board, The Intersphere, any ROYAL board or any major Dutch\nboard.... Fight for the numbers!!\n\n\n\nGREETINGS\n---------\n    Muad''Dib/IFT (o-kee!), WishBringer/HOS, LightNing ,Exotic/ACS^POSSE\n    Track/¿, Veteran/CCN, Sir IQ, (Good luck with MB dudes!), Pyxis/CCN\n  Funz/CCN, mAC/CCN, Midnight Caller/CCN, Eurobyte/CCN, Motive Power/MST\n    KillRaven/MST, The Brain/Nix, Delite/RYL^BTW^CRY, Pinokio/BTW^RYL,\n    ScarFace/Edge, Hawk,Radavi&MSW/EFFECT, D-Lorean/Myth (whahahha!), \n    THC/Myth, PLL/Myth, Koud?, NightCrawler/Indy, aXeBlade/AC!/JeTsEt,\nThe Desert Dancer (het font is lelijk!), Tom, Zack/STD, CHIP/ROYAL,Jake/PSG\n MEGA^FORTRESS/ROYAL, PsYCHLOP (crickits!), Jarre/Indy, D''Style,Magic/MRG\nWhirlWind & Apollo/ROYAL, The Edge, Stephen King, Neoplasia, Iris DK, \n Defiance Sweden, Sper/Spirit, all CDS members, the former Estate Staff &\n     his slaves and all dudes in Houten 1995 (including Courbois)... \n\n          And ofcourse all (*)  R O Y A L  (*) members worldwide!\n\n\n\nCALL OUR BOARDS:\n----------------\n                            .____.            .____.\n_____________ ______________|    | __________ |    |\n\_  ___     / _____   \     |    |_\______   \_    |____.\n |   _/   _/.     /    \_____   _|     ___    |    |    |\n |___\      |__________/    /   \|____________|___ `    |\n------\_____|---------/__________\----------------\_____|--------------------\n \n                         * bOARDS! *\n \n     Digital Extasy  - +1-ASK-ELITE! - USHQ [4 NODES RD/16K8]\n       Dutch Dreams  - +31-ASKELITE! - WHQ  [1 NODE/14K4 (SOON 3 NDS)]\n         StoneHenge  - +31-ASKELITE! - DHQ  [1 NODE/14K4 (SOON 28K8)]\n           Homeless  - +49-ASKELITE! - EHQ  [1 NODE/14K4 (SOON 2 NDS)]\n         Phoenix II  - +46-ASKELITE! - SHQ  [1 NODE/??K?]\n \n                    * aFFILIATED bOARDS! *\n \n             The Lab - +31-KILL4IT! - Prof B-Rom\n               Delta - +31-KILL4IT! - Eagle\n       MF Enterprise - +31-KILL4IT! - Mega Fortress\n             IQ Zero - +31-KILL4IT! - Pinokio\n          Dreamphase - +46-KILL4IT! - Bubba\n         ¡NTERSpHERE - +31-KILL4IT! - ¡CE\n \n-----------------------------------------------------------------------------\n\n-EOF-\n','\n',char(10)),NULL,'auto-added',21317,8,0,NULL,NULL,'ryl_np11','scan',1780048704);
INSERT INTO door_catalog VALUES('ryl_np12','RYL-NP12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RYL-NP12.LHA',NULL,'XIM','.___.        .___.',NULL,NULL,'RYL','___________ __________|   |_______ |   | \_ ___    / ____ \    |   |\____  \_   |___. |  _/  _/.    /  \____  _|   _    |   |   |',replace('                      .___.        .___.\n___________ __________|   |_______ |   |\n\_ ___    / ____ \    |   |\____  \_   |___.\n |  _/  _/.    /  \____  _|   _    |   |   |\n |__\     |_______/   /  \_________|__ `   |\n ----\____|------/________\[pRESENTS!]\____|\n NodePW v1.2 - Special Password for a Node!\n New features! Easy 2 Use & Abuse! Abuse!\n ------------------------------------------\n','\n',char(10)),'nodepw.doc',replace('\n                                    .____.            .____.\n        _____________ ______________|    | __________ |    |\n        \_  ___     / _____   \     |    |_\______   \_    |____.\n         |   _/   _/.     /    \_____   _|     ___    |    |    |\n         |___\      |__________/    /   \|____________|___ `    |\n        ------\_____|---------/__________\---[PRESENTS:]--\_____|-\n\n        - -- ---^(NodePW v1.2 by iCE/ROYAL^CDS 29-MAR-95)^--- -- -\n\n\n\nWHAT IS NODEPW?\n---------------\nJust simple... If you have a private node, you might want a password on it,\nto prevent certain users, wich have found out the number,  to call that\nnode and keep the line busy. So you install a SystemPassword. But all the\nusers that want to connect to your private node have to enter this password\nover and over again, or maybe you already have a system password (ie\n`YES'')... \nWell all this door does is checks if the users name is in a file, and if it\nisn''t, it will ask him for the password. If the user knows it, his name\nwill be added to a file and he''ll never have to enter the password again... \nIf he doesn''t know it, the door will show him a textfile and drops\ncarrier.. Or, if the sysops wants so, shows him a menu with the options \nto [O] - Page, [C] Comment the sysop or [G] give up.. \nI got the idea for this door from the board, The Undiscovered, where the\nsysop (Muad''Dib) had coded his own one for private use. He didn''t want to\nrelease it, so I decide to make such a door myself, for the idiots that\nneed it! So.. use & abuse!\n\n\nREQUIREMENTS\n------------\n/X 3.xx (it might work with lower versions.. i dunno..) or higher. \nAssigned DOORS: and a running rexxmaster.\nAn amiga model would be nice.\n\n \n\nINSTALLATION\n------------\nFairly simple.. just copy the files from the archive to the right dirs in\nyour bbs drawer.\nThen edit the following files to your needs:\n\nNodePW.names.X     -> The names file\nNodePW.PW.X        -> The password & menu cfg\nNodePW.X.TXT       -> The `enter password'' text\nNodePW-Fail.X.TXT  -> The `failed PW'' text\nNodePW-Menu.X.TXT  -> The Failed PW Menu\n\n(Where X is the nodenumber on wich the door should be active)\n\nMake sure all these files exist for the right node or else the door will\nexit.\nThe 2 textfiles are handled by /X as the usual textfiles... I think you\nknow what I mean, otherwise, close your board. \nTake a look at the nodePW.PW.X... this is a sort of the config file:\n\n----\nPASSWORD <- guess what?\nYES      <- Failed-PW Menu (YES/NO)\n----\n\nNow add to your BBS:nodeX/LOGON.??? the line\n----\n~CC_NodePW\n----\n\nAnd that''s it.. you can protect as many nodes as you want with this door..\njust copy the textfiles and rename them to the right nodes... You know what\nI mean.. \n\n\n\nSHOWNP\n------\nThe tiny `ShowNP'' command supplied by this version will show the current\npassword for the active node... Just simple.. maybe sum-1 needs it.. \n\n\n\nTESTING THE DOOR\n----------------\nCopy NodePW.info from the syscmd to the bbscmd drawer and enter NodePW...\ntata!\n\nHISTORY\n-------\n1.0 - First, buggy version. Never released\n1.1 - First release version!\n1.2 - 2nd release version! Added a menu feature!\n      Added the ShowNP command.\n\nBETA-TESTERS\n------------\n1.1 -WhirlWind/Royal - 5 minutes, and we discovered the `red=white bug from /X''\n     Thanx dude!\n1.2 -Me, myself & I\n\n\nCONTACTING ME\n-------------\nJust call my own board, The Intersphere, any ROYAL board or any major Dutch\nboard.... Fight for the numbers!!\n\n\n\nGREETINGS\n---------\n\n  Muad''Dib/MST^RYL (o-kee!), WishBringer/HOS, LightNing ,Exotic/ACS^POSSE\n    Track/¿, Veteran/CCN, Sir IQ, (Good luck with MB dudes!), Pyxis/CCN\n  Funz/CCN, mAC/CCN, Midnight Caller/CCN, Eurobyte/CCN, Motive Power/MST\n    KillRaven/MST, The Brain/Nix, Delite/RYL^BTW^CRY, Pinokio/BTW^RYL,\n    ScarFace/Edge, Hawk,Radavi&MSW/EFFECT, D-Lorean/Myth (whahahha!), \n    THC/Myth, PLL/Myth, Koud?, NightCrawler/Indy, aXeBlade/AC!/JeTsEt,\nThe Desert Dancer (het font is lelijk!), Tom, Zack/STD, CHIP/ROYAL,Jake/PSG\n MEGA^FORTRESS/ROYAL, PsYCHLOP (crickits!), Jarre/Indy, D''Style,Magic/MRG\n  WhirlWind & Apollo/ROYAL, The Edge, Stephen King, Neoplasia, Iris DK, \n Defiance Sweden, Sper/Spirit, all CDS members, the former Estate Staff &\n     his slaves and all dudes in Houten 1995 (including Courbois)... \n\n          And ofcourse all (*)  R O Y A L  (*) members worldwide!\n\n\n\nCALL OUR BOARDS:\n----------------\n                            .____.            .____.\n_____________ ______________|    | __________ |    |\n\_  ___     / _____   \     |    |_\______   \_    |____.\n |   _/   _/.     /    \_____   _|     ___    |    |    |\n |___\      |__________/    /   \|____________|___ `    |\n------\_____|---------/__________\----------------\_____|--------------------\n \n                         * bOARDS! *\n \n     Digital Extasy  - +1-ASK-ELITE! - [4 NODES RD/16K8]\n       Dutch Dreams  - +31-ASKELITE! - [1 NODE/14K4 (SOON 3 NDS)]\n         StoneHenge  - +31-ASKELITE! - [1 NODE/14K4 (SOON 28K8)]\n           Homeless  - +49-ASKELITE! - [1 NODE/14K4 (SOON 2 NDS)]\n   The Undiscovered  - +31-ASKELITE! - [3 NODES/28k8 DS]\n         Phoenix II  - +46-ASKELITE! - SHQ  [1 NODE/??K?]\n \n                    * aFFILIATED bOARDS! *\n \n             The Lab - +31-KILL4IT! - Prof B-Rom\n               Delta - +31-KILL4IT! - Eagle\n       MF Enterprise - +31-KILL4IT! - Mega Fortress\n             IQ Zero - +31-KILL4IT! - Pinokio\n          Dreamphase - +46-KILL4IT! - Bubba\n         ¡NTERSpHERE - +31-KILL4IT! - ¡CE\n \n-----------------------------------------------------------------------------\n\n-EOF-\n','\n',char(10)),NULL,NULL,7162,4,0,NULL,NULL,NULL,'scan',1780048704);
INSERT INTO door_catalog VALUES('ryl_ppge','RYL-PPGE.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RYL-PPGE.LHA','psychopageprefs','XIM','.___.        .___.',NULL,'pSYCHoTRON','RYL','___________ __________|   |_______ |   | \_ ___    / ____ \    |   |\____  \_   |___. |  _/  _/.    /  \____  _|   _    |   |   |',replace('                      .___.        .___.\n___________ __________|   |_______ |   |\n\_ ___    / ____ \    |   |\____  \_   |___.\n |  _/  _/.    /  \____  _|   _    |   |   |\n |__\     |_______/   /  \_________|__ `   |\n ----\____|------/________\[pRESENTS!]\____|\n         pSYCHoPAGE by pSYCHoTRON\n Powerfull Pager Door For /X, s!X or FAME.\n','\n',char(10)),'pSYCHoPAGE.Guide',replace('@DATABASE "pSYCHoPAGE.Guide"\n@REMARK  .-----------------------------------------------------------.\n@REMARK  | This document should be read with AmigaGuide or MultiView |\n@REMARK  `-----------------------------------------------------------''\n@REMARK  $VER: pSYCHoPAGE Docs\n@INDEX MAIN\n@WIDTH 80\n@NODE MAIN "pSYCHoPAGE By pSYCHOTRON/rOYAL /X dEVELOPMENT"\n                               ________\n      ______________ __________)__    /____  ____________ ________\n     _)______      /:     _      /   /     \_\______     \)     _(_______\n    /      _/     /_:     \     /______     \_    _/      \_    )       /\n  _/       \________(__________/-/___________/____\________/___________/-->\n  \_________|-uMn/aL-\n                            pSYCHoPAGE BY pSYCHOTRON\n\n                        @{" INTRODUCTION & FEATURES " link INTRO}\n                        @{"      REQUIREMENTS       " link REQ}\n                        @{"      INSTALLATION       " link INST}\n                        @{"        CONFIG ME        " link CONFIG}\n                        @{"         CREDITS         " link CREDS}\n                        @{"          ROYAL          " link RYL}\n\n\n\n@ENDNODE\n@NODE INTRO "INTRODUCTION & FEATURES"\n\n\npSYCHoPAGE IS A HIGH-TECH PAGER DOOR FOR /X, S!X OR FAME.\nJUST CHECK OUT THESE COOL FEATURES!\n\n· 100% CONFIGURABLE OUTPUT FROM A USER-FRIENDLY MUI INTERFACE \n· ANSI CODES IN PAGING STRING WITHOUT ANY EXTRA DELAYS\n· POWERFUL BROWSE FUNCTION IN THE DESIGN PREFS PROGRAM, NO MORE \n  NEED TO MESS WITH CORDINATES \n· 2 DIFFRENT DESIGNS INCLUDED! MADE BY HAMLET AND NEWT (THANX M8S!)\n· MUI INTERFACE WHEN PAGING FOR QUICK JUMP TO CHAT\n· DISABLE PAGING WITHOUT LETTING THE USER KNOW IT\n· MODULE PLAYING, EXECUTE A PROGRAM, DISPLAYBEEP()\n· RANDOM DESIGNS OPTION\n· BLACKLIST USERS\n· LET SPECIAL USERS OVERRIDE CHATFLAG\n· WORKS WITH /X, S!X AND FAME\n\n                                                      @{" BACK " link MAIN}\n@ENDNODE\n@NODE REQ "REQUIREMENTS"\n\n\n· OS 2.04+\n· /X, S!X OR FAME\n· MUI v3.1+\n· DESTRACKER.LIBRARY FOR PLAYING MODS (INCLUDED)\n\n                                                      @{" BACK " link MAIN}\n@ENDNODE\n@NODE INST "INSTALLATION"\n\n\nCOPY THE FILES TO ITS RESPECTIVE DIRS IN YOUR BBS:, RUN THE CONFIG\nPROGRAM AND HIT IT! IF YOU CAN''T INSTALL A DOOR TO YOU BBS, CLOSE IT.\n\n\n                                                      @{" BACK " link MAIN}\n@ENDNODE\n@NODE CONFIG "Confiuration Of The pSYCHoPAGE Door"\n\n\n\n\nTHE pSYCHoPAGE IS CONFIGURED VIA THE @{"PREFS PROGRAM" link PREFS},\nAND OFFCOURSE, THE @{"DESIGNFILES" link DSGF}.\n\n                                                      @{" BACK " link MAIN}\n@ENDNODE\n@NODE PREFS\n\n\n\n@{"EDIT MESSAGES                " link A\n\n@{"EDIT BLACKLISTED USERS       " link B\n\n@{"EDIT CHATFLAG OVERRIDE STATUS" link C\n\n@{"ADVANCED DESIGN OPTIONS      " link D\n\n@{"ENABLE BLACKLISTED           " link E\n\n@{"ENABLE CF OVERRIDE           " link F\n\n@{"PAGING METHOD                " link G\n\n\n\n\n@ENDNODE\n@NODE A "EDIT MESSAGES"\n\n\nADD    - ADD A MESSAGE THAT YOU CAN SEND TO THE USER IF YOU DON''T WANT TO CHAT.\n\nDELETE - DELETE THE SELECTED MESSAGE.\n\n\n\n@ENDNODE\n@NODE B "EDIT BLACKLISTED USERS"\n\n\nADD    - ADD A USER TO THE BLACKLIST. THOSE USERS WILL ALLWAYS HAVE THE\n         CHATHFLAG OFF, EVEN IF YOU HAVE IT SET TO ON.\n\nDELETE - DELETE THE SELECTED USER FROM THE LIST.\n\n\n\n@ENDNODE\n@NODE C "EDIT CHATFLAG OVERRIDE STATUS"\n\n\nADD    - ADD A USER TO THE CHATFLAG OVERRIDE LIST. THOSE USERS WILL ALLWAYS\n         HAVE THE CHATFLAG ON, EVEN IF YOU HAVE IT SET TO OFF.\n\nDELETE - DELETE THE SELECTED MESSAGE USER FROM THE LIST.\n\n\n@ENDNODE\n@NODE D "ADVANCED DESIGN OPTIONS"\n\n\nTHERE ARE TWO DESIGNS INCLUDED. ONE BY HAMLET/ROYAL/DIGITAL CORRUPTION AND\nONE BY NEWT/ROYAL/CRUX. YOU CAN ENABLE/DISABLE ONE OR BOTH BY CLICKING\nON THE ''YES'' OR ''NO'' TEXT. IF ALL ARE SET TO YES, THE PAGER WILL RANDOM THEM.\n\nNEW    - ADD A DESIGN SET\n\nDELETE - DELETE SELECTED DESIGN SET\n\n@{" EDIT " link EDIT}\n\n\n@ENDNODE\n@NODE EDIT "EDITING THE DESIGN FILES"\n\nMOST OF THE OPTIONS ARE SELF-EXPLAINING, BUT I WILL EXPLAIN SOME\nOF THEM ANYWAY. \n\n\nNAME - THE NAME OF THE DESIGN SET\nPATH - THA PATH TO THE DESIGN SET\n\n@{" COMMENT - NO ANSWER " link ED1}\n\n@{" CHATFLAG OFF        " link ED2}\n\n@{" OTHER               " link ED3}\n@ENDNODE\n@NODE ED1 "COMMENT - NO ANSWER"\n\nTHESE OPTIONS WILL BE USED IF THE USER PAGED, BUT THE SYSOP\nDIDN''T ANSWER.\n\n\nASK FOR COMMENT  - ASK THE USER IF HE WANTS TO LEAVE A COMMENT.\n\nQUESTION/MESSAGE - CORDINATES FOR COMMENT QUESTION/MESSAGE.\n\nANSWER           - THE USERS ''LEAVE A COMMENT'' ANSWER''S CORDINATES.\n\n@{" BROWSE " LINK BROWSE}\n\nENTER MODE       - \n\nMESS COMMAND     - IF YOU WANT THE INTERNAL ''E SYSOP'' OR YOU ''C'' DOOR.\n\n@ENDNODE\n@NODE ED2 "CHATFLAG OFF"\n\nTHESE OPTIONS WILL BE USED IF THE CHATFLAG IS SET TO OFF.\n\n\nASK FOR COMMENT - ASK IF THE USER WANTS TO LEAVE A COMMENT.\n\nANSWER          - THE USERS ''LEAVE A COMMENT'' ANSWER''S CORDINATES.\n\n@{" BROWSE " LINK BROWSE}\n\nENTER MODE      -\n\nMESS COMMAND    - IF YOU WANT THE INTERNAL ''E SYSOP'' OR YOU ''C'' DOOR.\n@ENDNODE\n@NODE ED3 "OTHER"\n\n\n\nREASON        - THE REASON STRING''S LOCATION & LENGTH.\n\n@{" BROWSE " LINK BROWSE}\n\nPAGING STRING - THE PAGING INDICATOR''SS LOCATION & LENGTH.\n\n@{" BROWSE " LINK BROWSE}\n\nNO REASON     - THE NO REASON STRINGS LOCATION. USED IF THE USER\n                DIDN''T ENTER A REASON FOR PAGING.\n\n@{" BROWSE " LINK BROWSE}\n\nMESSAGES      - THE LOCATION WHERE THE MESSAGES YOU CAN SEND TO THE\n                USER WILL BE SHOWN.\n\n@{" BROWSE " LINK BROWSE}\n\nSYSOP COMING  - THE LOCATION OF THE ''SYSOP IS COMMING'' STRING.\n\n@{" BROWSE " LINK BROWSE}\n\nEND OF DESIGN - THE END OF THE DESIGNFILE.\n\n@{" BROWSE " LINK BROWSE}\n\n@ENDNODE\n@NODE BROWSE "THE POWERFULL BROWSER"\n\nTHIS IS A GREAT FEATURE. YOU DONT HAVE TO ENTER THE CORDINATES MANUALLY,\nYOU CAN USE THE BROWSER INSTEAD. THE USAGE IS SIMPLE.\n\n1. CLICK ON BROWSE.\n2. SELECT THE LOCATION YOU WANT WITH THE LEFT MOUSEBUTTON.\n3. CONFIRM WITH THE RIGHT MOUSEBUTTON.\n\nIF THERE MUST BE A LENGTH SPECIFIED AS E.G. WITH THE ''REASON'' OPTION,\nTHIS IS THE CORRECT WAY TO DO IT.\n\n1. CLICK ON BROWSE.\n2. SELECT THE LOCATION YOU WANT, HOLD DOWN THE LEFT MOUSEBUTTON AND\n   DRAG THE MOUSE.\n3. CONFIRM WITH THE RIGHT MOUSEBUTTON.\n\n@ENDNODE\n@NODE E "ENABLE BLACKLISTED"\n\n\nENABLE/DISABLE BLACKLIST.\n\n\n@ENDNODE\n@NODE F "ENABLE CF OVERRIDE"\n\n\nENABLE/DISABLE CHATFLAG OVERRIDE LIST.\n\n\n@ENDNODE\n@NODE G "PAGING METHOD"\n\n\n@{"DISPLAYBEEP()                            " link A1\n\n@{"DISPLAYBEEP() + PLAY MODULE              " link A2\n\n@{"DISPLAYBEEP() + RUN PROGRAM              " link A3\n\n@{"DISPLAYBEEP() + PLAY MODULE + RUN PROGRAM" link A4\n\n@{"PLAY MODULE                              " link A5\n\n@{"PLAY MODULE + RUN PROGRAM                " link A6\n\n@{"RUN PROGRAM                              " link A7\n\n@{"QUIET                                    " link A8\n\n\n\n@ENDNODE\n@NODE A1 "DISPLAYBEEP()"\n\n\nMAKES THE PAGER FLASH THE SCREEN AND PLAY THE DEFULT SYSTEM SOUND.\n\n\n@ENDNODE\n@NODE A2 "DISPLAYBEEP() + PLAY MODULE"\n\n\nMAKES THE PAGER FLASH THE SCREEN AND PLAY A MODULE.\n\n\n@ENDNODE\n@NODE A3 "DISPLAYBEEP() + RUN PROGRAM"\n\n\nMAKES THE PAGER FLASH THE SCREEN AND RUN A PROGRAM.\n\n@ENDNODE\n@NODE A4 "DISPLAYBEEP() + PLAY MODULE + RUN PROGRAM"\n\n\nMAKES THE PAGER FLASH THE SCREEN, PLAY A MODULE AND RUN A PROGRAM.\n\n@ENDNODE\n@NODE A5 "PLAY MODULE"\n\n\nMAKES THE PAGER PLAY A MODULE.\n\n@ENDNODE\n@NODE A6 "PLAY MODULE + RUN PROGRAM"\n\n\nMAKES THE PAGER PLAY A MODULE AND RUN A PROGRAM.\n\n@ENDNODE\n@NODE A7 "RUN PROGRAM"\n\n\nMAKES THE PAGER RUN A PROGRAM.\n\n@ENDNODE\n@NODE A8 "QUIET"\n\n\nMAKES THE PAGER SHUT UP.\n\n@ENDNODE\n@NODE DSGF "The Design Files."\n\n\n\n@{"STARTUPNORMAL.TXT" link 1\n\n@{"STARTUPOFF.TXT   " link 2\n\n@{"REASONHEADER.TXT " link 3\n\n@{"PAGINGHEADER.TXT " link 4\n\n@{"MESSAGEHEADER.TXT" link 5\n\n@{"PAGINGSTRING.TXT " link 6\n\n@{"SYSOPCOMING.TXT  " link 7\n\n@{"NOREASON.TXT     " link 8\n\n@{"LEAVECOMMENT.TXT " link 9\n\n@{"YES.TXT          " link 10\n\n@{"NO.TXT           " link 11\n\n\n@ENDNODE\n\n@NODE 1\n\n\nIS SHOWN WHEN PAGER STARTS AND CHATFLAG IS ON\n\n@ENDNODE\n@NODE 2\n\n\n\nIS SHOWN WHEN PAGER STARTS AND CHATFLAG IS OFF\n\n@ENDNODE\n@NODE 3\n\n\nIS SHOWN BEFORE USER TYPES IN THE REASON.  \nEXAMPLE: CHANGE THE COLORS FOR THE REASON TEXT\n\n@ENDNODE\n@NODE 4\n\n\nIS SHOWN BEFORE THE PAGING STRING IS SHOWN.\nEXAMPLE: CLEAR THE PAGING STRING AREA\n\n@ENDNODE\n@NODE 5\n\n\nIS SHOWN BEFORE A MESSAGE IS BEING SENT TO THE USER \n\n@ENDNODE\n@NODE 6\n\n\nTHE PAGING STRING. IT REPEATS ITSELF UNTIL THE PAGING IS FINISHED\n\n@ENDNODE\n@NODE 7\n\n\nIS SHOWN WHEN THE SYSOP HIT THE CHAT BUTTON IN THE WINDOW\n\n@ENDNODE\n@NODE 8\n\n\nIS SHOWN IF USER DOESN''T TYPE A REASON\n\n@ENDNODE\n@NODE 9\n\n\nIS SHOWN IF THE SYSOP DIDN''T ANSWER THE PAGE\nEXAMPLE: LEAVE A COMMENT (Y/n)?\n\n@ENDNODE\n@NODE 10\n\n\nIS SHOWN IF THE USER PRESS Y AT A LEAVE COMMENT QUESTION\n\n@ENDNODE\n@NODE 11\n\n\nIQ TEST! =)\n\n@ENDNODE\n\n@NODE CREDS "THE CREDITS"\n\n\n       CODE: PSYCHOTRON\n      GUIDE: HAMLET\n     DESIGN: NEWT & HAMLET\nBETATESTING: NEWT & HAMLET\n\n                                                      @{" BACK " link MAIN}\n@ENDNODE\n@NODE RYL "HOW TO CONTACT ROYAL"\n\n\n\n\n         .-----  - -------   - --- ---- ----   ----- -- ---- -- -- -.\n         ¡                                                          |\n         |          Digital Extasy   - +1-2013454315    RD          |\n         ¦         One Eight Seven   - +31-534337569                :\n         ·                             +31-534339671                ¡\n         ¡              Riot House   - +31-541355073                .\n         ¦            Metal Impact   - +32-15-212992    RD\n         |               Dial Hard   - +41-719500156    RD\n         ·                             +41-719526525\n                                       +41-7350-0157    ISDN, RD\n                   Northern Palace   - +45-5850-6081    RD\n                    First Division   - +46-303777993\n                        Checkpoint   - +47-51-593123    RD\n                           Nemezis   - +48-321038256\n                          Homeless   - +49-228319712\n                                       +49-228319762\n\n                    - --- -  -- -----------  - --- - - --\n\n\n                                                      @{" BACK " link MAIN}\n@ENDNODE\n','\n',char(10)),NULL,NULL,57308,7,0,NULL,NULL,NULL,'scan',1780048704);
INSERT INTO door_catalog VALUES('ryl_swh2','RYL-SWH2.LZX','~/Code/amiexpress_doors/Archives/AmiExpress/RYL-SWH2.LZX',NULL,'XIM','ryl swh2',NULL,NULL,'RYL',NULL,NULL,NULL,NULL,NULL,NULL,97718,0,0,NULL,NULL,NULL,'scan',1780048704);
INSERT INTO door_catalog VALUES('ryl_swh3','RYL-SWH3.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RYL-SWH3.LHA','SuperWHOPrefs','XIM','.___.        .___.',NULL,'pSYCHoTRON','RYL','___________ __________|   |_______ |   | \_ ___    / ____ \    |   |\____  \_   |___. |  _/  _/.    /  \____  _|   _    |   |   |',replace('                      .___.        .___.\n___________ __________|   |_______ |   |\n\_ ___    / ____ \    |   |\____  \_   |___.\n |  _/  _/.    /  \____  _|   _    |   |   |\n |__\     |_______/   /  \_________|__ `   |\n ----\____|------/________\[pRESENTS!]\____|\n        SuperWho 3.0 by pSYCHoTRON\n POWERFULL Who/Frontend For /X, s!X or FAME\n\n','\n',char(10)),'SuperWHO.guide',replace('@DATABASE "SuperWHO.Guide"\n@REMARK  .-----------------------------------------------------------.\n@REMARK  | This document should be read with AmigaGuide or MultiView |\n@REMARK  `-----------------------------------------------------------''\n@REMARK  $VER: SuperWHO 3.0\n@INDEX MAIN\n@WIDTH 80\n@NODE MAIN "SuperWHO 3.0 By pSYCHOTRON/rOYAL /X dEVELOPMENT"\n                               ________\n      ______________ __________)__    /____  ____________ ________\n     _)______      /:     _      /   /     \_\______     \)     _(_______\n    /      _/     /_:     \     /______     \_    _/      \_    )       /\n  _/       \________(__________/-/___________/____\________/___________/-->\n  \_________|-uMn/aL-\n                        SUPERWHO 3.0 BY pSYCHOTRON\n\n                        @{" INTRODUCTION & FEATURES " link INTRO}\n                        @{"      REQUIREMENTS       " link REQ}\n                        @{"      INSTALLATION       " link INST}\n                        @{" HOW TO CONFIG THE DOOR? " link CFG}\n                        @{"          ROYAL          " link RYL}\n                        @{"         CREDITS         " link CREDS}\n\n\n@ENDNODE\n@NODE INTRO "INTRODUCTION & FEATURES"\n\n\nSUPERWHO 3.0 IS A HIGH-TECH WHO AND FRONTEND DOOR FOR /X, S!X OR FAME.\nJUST CHECK OUT THESE COOL FEATURES!\n\n·  100% CONFIGURABLE OUTPUT FROM A USER-FRIENDLY MUI INTERFACE!\n·  POWERFUL BROWSE FUNCTION IN THE DESIGN PREFS PROGRAM, NO MORE \n   NEED TO MESS WITH COORDINATES!\n·  A REALTIME WHO THAT ONLY REDRAWS THE SCREEN WHEN NEEDED!\n·  DOESN''T SUCK THE SHIT OUT OF YOUR CPU. IT''S ACTUALLY REAL FAST!\n·  RANDOM DESIGN OPTION!\n·  QUIET NODE SUPPORT!\n·  SHOWS FILENAME AT UPLOAD/DOWNLOAD!\n·  SHOWS ''LAST'' STATISTICS ON NODES!\n·  2 WHODESIGNS & 2 FRONTEND DESIGNS BY HAMLET INCLUDED.\n·  1 FRONTEND DESIGN BY JOE COOL INCLUDED.\n·  WORKS WITH /X, S!X AND FAME\n·  ZILLIONS OF EXTRA OUTPUT FEATURES LIKE EG. USER''S ACTUAL CONFERENCE,\n   USER''S ACCESS LEVEL, A NODE OR THE TOTAL SYSTEM''S TODAYS CALLS,\n   UL FILES OR UL BYTES, CHATFLAG ON/OFF, LOCAL TIME OR DATE,\n   NUMBER OF NODES INCATIVE, FREE OR BUSY. + MUCH MORE!\n\n                                                      @{" BACK " link MAIN}\n@ENDNODE\n@NODE REQ "REQUIREMENTS"\n\n\n· OS 2.04+\n· /X, S!X OR FAME\n· MUI v3.1+\n\n                                                      @{" BACK " link MAIN}\n@ENDNODE\n@NODE INST "INSTALLATION"\n\nNOTHING HARD. JUST COPY THE FILES TO THEIR RESPECTIVE DIRECTORIES.\n\nIF YOU WANT TO USE THE OPTION ''TODAYS UL FILES & BYTES'' (OFFCOURSE YOU WANT)\nYOU MUST INSTALL THE FILE ''SWhoUlCounter'' AS AN EXAMINE DOOR.\nA GOOD IDEA FOR S!X USERS IS TO SIMPLY DROP THE FILE INTO BBS:SYSTEM\nAND RENAME IT TO EXAMINEx. WHERE x IS THE LOWEST FREE NUMBER OF YOUR\nEXAMINE DOORS.\n\nIF YOU WANT TO USE THE ''TODAYS CALLS'' (OFFCOURSE YOU WANT TO USE THIS TOO!)\nYOU HAVE TO ADD THE SWhoCallCounter COMMAND TO YOUR LOGOFFx BATCH FILES.\nWHERE x IS THE NODE NUMBER. THE CORRECT TEMPLATE FOR THE COMMAND IS\n''SWhoCallCounter x''. WHERE x IS THE NODENUMBER.\n\n\n                                                      @{" BACK " link MAIN}\n@ENDNODE\n@NODE CREDS "THE CREDITS"\n\n\n       CODE: PSYCHOTRON\n      GUIDE: HAMLET\n    DESIGNS: HAMLET & JOE COOL\nBETATESTING: HAMLET\n\n                                                      @{" BACK " link MAIN}\n@ENDNODE\n@NODE RYL "HOW TO CONTACT ROYAL"\n\n                         \n                                 \n                   Digital Extasy   -   +1-2013454315  4Ndz Rd     \n                  One Eight Seven   -   +31-534339671              \n                                        +31-534337569              \n                       Riot House   -   +31-541355073              \n             Electronic Confusion   -   +45-316095-51\n                                        +45-316095-50\n                   First Division   -   +46-303777993  Telnet\n                                        +46-303777026\n                          Pitstop   -   +47-333-84269\n                                        +47-333-87955\n                       CheckPoint   -   +47-515931-23  2Ndz Rd\n                          Nemezis   -   +48-321038256\n                         Homeless   -   +49-228319762\n                                        +49-228319712\n\n\n                                                      @{" BACK " link MAIN}\n@ENDNODE\n@NODE CFG "HOW TO CONFIGURATE THE DOOR"\n\n\n\n\nTHE SUPERWHO IS CONFIGURED VIA THE @{"PREFS PROGRAM" link PREFS},\nAND OFFCOURSE, THE @{"DESIGNFILE" LINK BG}.\n\n                                                      @{" BACK " link MAIN}\n@ENDNODE\n@NODE PREFS\n\nTHIS PART OF THE GUIDE IS DESIGNED TO BE A ''FOLLOW UP'' HELPGUIDE\nWHILE BROWSING IN THE GUI. THIS MEANS, IF YOU HAVE BOTH THE PREFS\nPROGRAM AND THIS GUIDE UP AT THE SAME TIME, YOU CAN PRESS THE SAME\nBUTTONS IN THE GUIDE AS IN THE PREFS PROGRAM, AND YOU WILL HAVE AN\nEXPLANATION RIGHT IN FRONT OF YOU.\n\n\nAFTER YOU HAVE STARTED UP THE PREFS PROGRAM THERE IS A LIST OF THE\nAVAILIBLE DESIGNS. HERE YOU CAN @{"ADD" LINK ADD}, @{"DELETE" LINK DELETE} AND @{"EDIT" LINK EDIT} DESIGNS.\nYOU CAN ALSO SET A DESIGN''S AREA OF USE BY SWITCHING THE \n@{"WHO, FRONTEND, BOTH OR NONE" LINK CYCLE} BUTTON.\nIF YOU PRESS ''CREATE STANDARD DESIGN'' THE PROGRAM WILL CREATE THE 5 INCLUDED\nDESIGNS. WITH THE @{"EDIT ACESS LEVELS" LINK EACS} BUTTON YOU CAN SET WHAT ACCESS\nA USER MUST HAVE TO SEE SOME OF THE OUTPUT OPTIONS.\n@ENDNODE\n@NODE ADD\n\nADD YOUR OWN DESIGN TO THE LIST.\n\n@ENDNODE\n@NODE DELETE\n\nDELETE A DESIGN FROM THE LIST.\n\n@ENDNODE\n@NODE CYCLE\n\nIF YOU SET THE DESIGN TO ''WHO'' IT WILL ONLY\nBE USED AS A WHO DESIGN. THE SAME GOES FOR ''FRONTEND''. IF YOU SET IT\nTO ''BOTH'' THE DESIGN WILL BE USED FOR BOTH WHO AND FRONTEND. IF YOU\nSET IT TO ''NONE'' THE DESIGN WILL BE INACTIVATED.\n\n@ENDNODE\n@NODE EACS\n\nSEE FILES:\n¯¯¯¯¯¯¯¯¯¯\nSEE CONFS:\n¯¯¯¯¯¯¯¯¯¯\nSEE ACCESS:\n¯¯¯¯¯¯¯¯¯¯¯\nTHE ACCESSLEVEL A USER MUST HAVE TO BE ABLE TO SEE ACCESS LEVELS.\n\nSEE QUIET NODES:\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nTHE ACCESSLEVEL A USER MUST HAVE TO BE ABLE TO SEE QUIET NODES.\n\nSEE DOORS:\n¯¯¯¯¯¯¯¯¯¯\nTHE ACCESSLEVEL A USER MUST HAVE TO BE ABLE TO SEE WHAT DOORS \nTHE OTHER USERS ARE RUNNING.\n\nSEE NEW USERS:\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nTHE ACCESSLEVEL A USER MUST HAVE TO BE ABLE TO SEE IF THERE IS A\nNEW USER LOGGING IN TO THE SYSTEM.\n\nSEE ALL FILES:\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nSEE ALL CONFS:\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n@ENDNODE\n@NODE EDIT\n\n@{"BACKGROUND" LINK BG}\n@{"CURSOR POSITION AFTER EXIT" LINK CPAE}\n@{"CLEAR SCREEN" LINK CLS}\n@{"FINETUNE VALUE" LINK FTV}\n@{"ITEMS" LINK ITEMS}\n@{"TEXTS" LINK TEXTS}\n\n\n@ENDNODE\n@NODE BG\n\nTHE ANSI DESIGNFILE TO USE AS A BACKGROUND AND PASTE THE\nOUTPUT ON.\n@ENDNODE\n@NODE CPAE\n\nTHE POSITION AT WHICH YOU WANT THE CURSOR TO BE AFTER THE DOOR EXITS.\n@ENDNODE\n@NODE CLS\n\nSET THIS TO ON IF YOU WICH THAT THE DOOR SHALL CLEAR THE SCREEN\nBEFORE IT LAUNCES. USEFULL IF YOU DON''T WANT A CLS IN THE FRONTEND\nDESIGNS.\n@ENDNODE\n@NODE FTV\n\n@ENDNODE\n@NODE ITEMS\n\nTHESE ARE THE OUTPUTS THAT YOU CAN PASTE OVER THE @{"DESIGNFILE" LINK BG}.\n\n@{"ADD" LINK AAD}\n@{"EDIT" LINK EDD}\n@{"DELETE" LINK DELL}\n\n@ENDNODE\n@NODE AAD\n\nITEM TYPE:\n¯¯¯¯¯¯¯¯¯¯\nTHE TYPE OF OUTPUT TO PASTE OVER THE @{"DESIGNFILE" LINK BG}, EG. USERNAME,\nLOCATION OR WHATEVER. THESE ARE THE AVAILIBLE @{"TYPES" LINK TYPES}.\n\nCOORDINATES:\n¯¯¯¯¯¯¯¯¯¯¯¯\nTHE COORDINATES ON THE @{"DESIGNFILE" LINK BG} WHERE THE ITEMS SHALL APPEAR.\nEITHER DO IT THE HARD WAY AND ENTER THE COORDINATES MANUALLY, OR DO IT THE\nEASY WAY AND PRESS @{"BROWSE" LINK BROWSE}. WITH ''JUSTIFICATION'' YOU SET IF\nYOU WANT THE ITEM TO BE CENTERED, TO THE LEFT OR TO THE RIGHT IN THE\nCOORDINATES FIELD.\n\nITEM TEXT:\n¯¯¯¯¯¯¯¯¯¯\nHERE YOU SET THE COLOR OF THE ITEM OUTPUT. IE. IF YOU WANT THE USERNAME\nTO BE PRINTED IN CYAN, JUST SET THE ''FG PEN'' (FOREGRUOND PEN) TO CYAN.\n''BG. PEN'' (BACKGROUND PEN) IS THE BACKGROUND COLOR OF THE FOREGROUND TEXT.\nYOU CAN FOR EXAMPLE PRINT THE USERNAME IN CYAN WITH GREEN BACKGROUND.\n\nBACKGROUND:\n¯¯¯¯¯¯¯¯¯¯¯\nHERE YOU SET THE BACKGROUND OF THE OUTPUT ITEM. INSTEAD OF SHOWING IE. THE\nUSERNAME LIKE THIS; ''HAMLET     '' YOU CAN SHOW IT LIKE THIS; ''HAMLET.....''.\nYOU CAN ALSO SET THE COLOR HERE. SEE ''ITEM TEXT''.\n@ENDNODE\n@NODE EDD\n\nEDIT AN ALREADY ADDED OUTPUT ITEM.\n\n@ENDNODE\n@NODE DELL\n\nDELETE AN EXISTING OUTPUT ITEM.\n@ENDNODE\n@NODE TYPES\n\nUSER NAME:\n¯¯¯¯¯¯¯¯¯¯\nDISPLAYS THE USERNAMES.\n\n\nUSER LOCATION:\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nDISPLAYS THE USERLOCATIONS.\n\n\nUSER ACTION:\n¯¯¯¯¯¯¯¯¯¯¯¯\nDISPLAYS THE USERS ACTION.\n\n\nUSER CONF:\n¯¯¯¯¯¯¯¯¯¯\nDISPLAYS THE CONF THE USERS ARE IN.\n\n\nUSER ACCESS:\n¯¯¯¯¯¯¯¯¯¯¯¯\nDISPLAYS THE USERS ACCESS LEVELS.\n\n\nUSER CONNECT BPS:\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nDISPLAYS THE USERS CONNECT SPEED.\n\n\nUSER CHAT/OLM:\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nDISPLAYS IF THE USERS ARE AVAILIBLE FOR CHAT/OLM.\n\n\nNODE TODAY''S CALLS:\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nDISPLAYS THE NUMBER OF CALLS TO ONE NODE SINCE 00:00.\n\n\nNODE TODAY''S UL BYTES:\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nDISPLAYS THE NUMBER OF BYTES UPLOADED TO ONE NODE SINCE 00:00.\n\n\nNODE TODAY''S UL FILES:\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nDISPLAYS THE NUMBER OF FILES UPLOADED TO ONE NODE SINCE 00:00.\n\n\nSYSOP CHATFLAG:\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nDISPLAYS IF THE CHATFLAG IS ON OR OFF.\n\n\nSYSTEM LOCAL TIME:\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nDISPLAYS THE SYSTEMS LOCAL TIME.\n\n\nSYSTEM LOCAL DATE:\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nDISPLAYS THE SYSTEMS LOCAL DATE.\n\n\nSYSTEM TODAY''S CALLS:\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nDISPLAYS THE NUMBER OF CALLS TO THE SYSTEM SINCE 00:00.\n\n\nSYSTEM TODAY''S UL BYTES:\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nDISPLAYS THE NUMBER OF UPLOAD BYTES TO THE SYSTEM SINCE 00:00.\n\n\nSYSTEM TODAY''S UL FILES:\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nDISPLAYS THE NUMBER OF UPLOAD FILES TO THE SYSTEM SINCE 00:00.\n\n\nSYSTEM NODES FREE:\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nDISPLAYS THE NUMBER OF UNOCCUPIED NODES IN THE SYSTEM.\n\n\nSYSTEM NODES BUSY:\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nDISPLAYS THE NUMBER OF BUSY NODES IN THE SYSTEM.\n\n\nSYSTEM NODES INACTIVE:\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nDISPLAYS THE NUMBER OF INCATIVE NODES IN THE SYSTEM.\n\n@ENDNODE\n@NODE BROWSE "THE POWERFULL BROWSER"\n\nTHIS IS A GREAT FEATURE. YOU DONT HAVE TO ENTER THE COORDINATES MANUALLY,\nYOU CAN USE THE BROWSER INSTEAD. THE USAGE IS SIMPLE.\n\n1. CLICK ON BROWSE.\n2. SELECT THE LOCATION YOU WANT WITH THE LEFT MOUSEBUTTON.\n3. CONFIRM WITH THE RIGHT MOUSEBUTTON.\n\nIF THERE MUST BE A LENGTH SPECIFIED AS E.G. WITH THE ''USERNAME'' OPTION,\nTHIS IS THE CORRECT WAY TO DO IT.\n\n1. CLICK ON BROWSE.\n2. SELECT THE LOCATION YOU WANT, HOLD DOWN THE LEFT MOUSEBUTTON AND\n   DRAG THE MOUSE.\n3. CONFIRM WITH THE RIGHT MOUSEBUTTON.\n\n@ENDNODE\n@NODE TEXTS\n\nHERE YOU CAN CHOOSE REPLACEMENTS FOR THE STANDARD ACTION OUTPUTS.\nFOR EXAMPLE, YOU CAN REPLACE ''Z'' WITH ''ZIPPY FILESEARCH''.\n\n@{"ADD" LINK AD}\n@{"EDIT" LINK ED}\n@{"DELETE" LINK DEL}\n@ENDNODE\n@NODE AD\n\nHERE YOU CHOOSE FROM A LIST OF AVAILIBLE COMMANDS TO REPLACE.\nYOU CAN ALSO CHOOSE ON WHAT NODES YOU WISH THAT THE REPLACEMENT\nSHALL BE ACTIVE. VERY USEFULL IF YOU EG. HAVE TELNET NODES,\nAND YOU INACTIVATE ONE OF YOUR NODES TO BE ABLE TO DIAL OUT.\nTHEN YOU CAN REPLACE THAT NODE''S ''NODE INACTIVE'' WITH \nEG. ''IN TELNET USE'' OR IF YOU HAVE YOUR TELNET NODES INACTIVE\nYOU CAN REPLACE IT WITH ''TELNET SHUTDOWN'' OR SIMILIAR.\n@ENDNODE\n@NODE ED\n\nEDIT ALREADY ADDED REPLACEMENTS.\n@ENDNODE\n@NODE DEL\n\nDELETE AN ENTRY.\n@ENDNODE\n','\n',char(10)),NULL,NULL,100093,1,0,NULL,NULL,NULL,'scan',1780048704);
INSERT INTO door_catalog VALUES('rylcsx11','RYLCSX11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RYLCSX11.LHA',NULL,'XIM','exe.-l0S-eND0S-bBS-.exe',NULL,'ByteJammer/Ryl',NULL,'____   \/   _  \/    Y  :   __   \/    /__. /   /   /    (   \____   |   \_    \   /   | \___\   \________/_______!____|____/_______|',replace(' _______  ______  ____ __.________  _____\n ____   \/   _  \/    Y  :   __   \/    /__.\n/   /   /    (   \____   |   \_    \   /   |\n\___\   \________/_______!____|____/_______|\n  tGø\___/-T!            :\n- --- -------------------^------------ --- -\n  CatStyler V1.1 /X Edition - Dec 3, 1995!\n  100% assembler written by ByteJammer/Ryl\n  >>>> Now supports Hydra-transfers!! <<<<\n- --- -------------------------------- --- -\n','\n',char(10)),'mastrb8.txt',replace(replace('STILL GOING STRONG in 2014!\r\n\r\n                ___         ._            _______             ·\r\n   /\  _________)  \________| \___________)__   /_________:__ :________\r\n  /  \/\  __  \    ____ ___/|  \______  \_  / _/___  \_ ____/ ¦__ \___ \\r\n /   /  \ \__  \___  \  |   |   \  _/  __/ /    /\__  \  |¦   | /  \_|  \\r\n/  \/    \_ \   \ !   \_|   !    \_\    \_     /   \   \ ||   |·    /|   \_\r\n\___|     ___\  /__    /l________ /_\    /__  /_____\  / |¦   |    /_|    /\r\n    l____/-A×E\/  \___/_!       \/   \  /   \/       \/__|:   ¦__ /  l___/\r\n       ______            _____        \/      :    ____   ·   : \/\r\n    ___)     \___________)    \__________:___ ¦____)   \__________\r\n    \    _______     _______    \___    ____/ |\_____   \______   \\r\n   /\___   \/        |    _)    \/       ¦    |/    |    \    |    \\r\n _/    !    \        |    \      \_      |    |     !     \   |     \\r\n \______     \___    |_____\      /___   |    ¦            \  |      \_\r\n       \______/ \____!      \    /   \___|    :________     \_|       /\r\n                             \  /        ¦    ·       \______/|      /\r\n   YOUVE HEARD ABOUT IT!      \/         :    ·               l_____/\r\n       \r\n         MASTURBATiON STATiON AMIGA/PC/CONSOLE/ASCII-ANSI/C64        \r\n               Telnet: bbs.masturbationstationbbs.com\r\n\r\n           UPLOAD DATE: 08-25-15  TIME: 17:29:36  ON NODE: 2\r\n\r\n  UPLOADER: Black Beard            LOCATION: mASTURBATIONSTATIONBBS.COM\r\n\r\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',23075,5,0,NULL,NULL,'rylcsx11','scan',1780048704);
INSERT INTO door_catalog VALUES('rylxcs10','RYLXCS10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RYLXCS10.LHA','CatStyler','XIM','CatStyler',NULL,'bYTEJAMMER/rOYAL!!!',NULL,'_._________________|   | __|_\_|_  |____   . \_   _    / _  \   |   |/  _____/  |   /   : w|   \___/  |   \___  _|  _|   \   `   \   |',replace('                   .___.   __  :---:\n_._________________|   | __|_\_|_  |____   .\n\_   _    / _  \   |   |/  _____/  |   /   :\nw|   \___/  |   \___  _|  _|   \   `   \   |\n |____\ |_______/  /  \___\_    \___    \_ |\n --------------/_______\---|_____\-|_____/-''\n CatStyler V1.0 /X Edition -- July 2, 1995!\n Written in 100% ASM by bYTEJAMMER/rOYAL!!!\nHighly configurable and very FAST dir-styler\nfor the AmiExpress BBS!! Adds DOWNLOADTIMES,\nUPLOADINFO, FILEDIVIDERs and kewl DATELINEs!\n** There are NO other stylers around that **\n** can compete with this! Leech & ENJOY!! **\n','\n',char(10)),'CatStyler.guide',replace('@DATABASE "CatStyler V1.0 /X Edition - Written in 100% ASM by BYTEJAMMER/ROYAL!\n\n@NODE MAIN "CatStyler V1.0 /X Edition - Written in 100% ASM by Bytejammer/Royal\n@AUTHOR "BYTEJAMMER/ROYAL"\n@VERSION "$VER: CatStyler.guide V1.0 by PICARD/PROJECT_A!"\n@{b}\n                     .:.........................         .\n                      :                       :  ...    .\n   . . ...............:    .     _ _/________ :..:.:   .   .     ...\n .____________________ ..:::· ·:.. /        /____:__  .·   ·.    :.:\n |      __           /::::      :::.       /     ·  |.:     :. ____.   ...\n |       /          /::::       ·:::.     /         .:·      :.    |   :.:\n |  .   /___       /::::R o Y a L::::    /__       .:::      ·:.   |\n |__._____|___________\\::       ::::·__________   .:::::. ...:::.__|_______\n    :        dto/e^d:::::::...::::::     /__________|            \\         \\\n    : .              ·::::::::::::·              :.... .   _ _______________\\\n    : :..               ········\n   .:......@{ub}[[-[   @{fg highlight}CatStyler V1.0, /X Edition - July 2, 1995!@{fg text}   ]-]]@{b}.......\n                                                                    ..: :\n                         .   .  . . ....................................:...\n                                                                        :\n CatStyler V1.0, /X Edition - July 2, 1995\n Copyright © 1995 BYTEJAMMER/ROYAL, All Rights Reserved\n\n @{ub}Documentation written by PICARD/PROJECT_A!! (OS3.0+ guide!)\n\n @{"  Introduction     " Link Introduction} Provides you with some initial information\n @{"  Requirements     " Link Requirements} What you require to run this on your setup\n @{"  Installation     " Link Installation} Supplies you with some info on installation\n @{"  Configuration    " Link Configuration} Vital info about CatStyler''s config\n @{"  Tips & Hints     " Link Tips_&_Hints} When CatStyler doesn''t work, click here\n @{"  Known bugs       " Link Known_bugs} Just to let you know about known problems\n @{"  History          " Link History} When was CatStyler born and what are the new features\n @{"  Acknowledgments  " Link Acknowledgments} Credits and greetings!\n@ENDNODE\n\n@NODE Introduction "Introduction"\n\nIntroduction\n************\n\n  "CatStyler - /X Edition"  is a  @{b}fully configurable@{ub}  file-catalog styler for\nthe  AmiExpress BBS.  It  can  add  several  types  of  information  to these\nfile-catalogs (also known as dirs), like:\n\n1. Amount of times a file has downloaded;\n2. Uploader''s info: - Handle, retrieved from CallersLog;\n                    - Node number, also retrieved from CallersLog;\n                    - File''s time of arrival, retrieved from FileInfoBlock;\n                    - CPS rate, and again retrieved from CallersLog.\n3. And some additional divider-lines and DATELINEs.\n\n  BTW: Before you start reading this documentation any further,  you  require\nsome knowledge about AmiExpress configuration files.  Because I won''t explain\nthat subject.\n\n  Before CatStyler,  I was working on a similar program for the DayDream BBS,\nwhich I called DreamScan; because it scanned logfiles for any file-transfers.\nWhen I released the first version, I, BYTEJAMMER/ROYAL/ENGINEERING!, received\na request  from SAL-1,  the  systems  operator  at @{" bOONDOCKs! " Link BOONDOCKS}, to create a\nsimilar utility for the AmiExpress BBS;  the BBS system where bOONDOCKs! runs\non.\n  Since the users over there often transfer a couple of 100 files a session!,\nthe system badly required a decent, configurable and most important FAST!!!!,\ndirstyler; this to keep the system more online than offline; because updating\nthe filecatalogs/dirs and bulletins USED TO (he, he) take a long time.\n  To achieve all this, CatStyler needed to be written, which I did.\n\n  SAL-1 has asked many programmers to build this sort of utility for his BBS.\nSeveral  people  said  that it wasn''t possible to code such a utility in ASM.\nOthers said they''d make one, but actually never did.  They were probably very\nlazy or did''t had the nescessary skills.\n\n  So, but what are the abilities/features of CatStyler? A summary:\n\n- 100% assmbler written (ASM-One V1.26) for maximum speed!!\n- highly configurable output;\n- easy to adapt, by changing the ASCII configuration file;\n- full testing of custumized configuration;\n- intelligent scanning on logfiles and file-catalogs;\n- ANSI color and style support;\n- CLI based;\n- and a bunch of other stuff I don''t want to bore you with.\n\n\n  The utility,  that used to update bOONDOCKs'' catalogs,  was DIRSTYLE;  which\nwas written in somesort of ARexx language.  ARexx  written pieces are known to\nbe VEEEEERY slow, to say the least.   So this explains  why SAL-1''s  system is\nalways busy, because it was always updating the catalogs.\n\n  CatStyler''s filelength  is very short. 7kb against DIRSTYLE''s 90kb!  This is\nbecause I build my utilities very optimized.  But ofcourse  the major part  of\nCatStyler''s short filelength is caused by the assembler language!  It''s direct\nand very effective, which result in NO unnescessary binary code.\n\n  By the way.. The filelength of CatStyler''s @{u}source@{uu}-code is 107kb.\n\n\n\n@ENDNODE\n\n@NODE Requirements "Requirements"\n\nRequirements\n************\n\n  In order to get CatStyler working on your system too,  you  ofcourse require\nthe AmiExpress BBS software.  I advise you  to use  one of the latest versions\navailable, V4.6+; since I''m  not  sure  how the logfiles  of previous versions\nlook like. Okay, among the AmiExpress BBS, you also need:\n\n- Amiga Operating System 2.0 (or better);\n\n- Motorola 68020 (or better) Central Processing Unit;\n\n- A descent ASCII editor to edit the configuration file (ED, CED or GoldED).\n\n\n\n@ENDNODE\n\n@NODE Installation "Installation"\n\nInstallation\n************\n\n- Copy ''CatStyler'' to  any  directory  you desire,  as long  as you know where\n  you''ve placed it (you require the pathname for the logoff scripts ofcourse).\n\n- Copy the file ''CatStyler.CFG'' to your S:, and start changing it to  your BBS\n  configuration  (amount of nodes,  locations of the callerslogs,  uploadpaths\n  and styler config).\n\n- Add the CatStyler to your logoff script(s), like this:\n------------------------------------------cut--\n<path>/CatStyler -n[node] [-<options>]\n------------------------------------------cut--\n\n  <options>:\n  -q = quiet; this deactivates error messages\n  -m = monitor; this displays every CatStyler action.\n                NOTE: with this switched on, the quiet option gets overruled!\n  -t = test configuration; this will  test  your  configuration file. It won''t\n                           verify your specified paths!\n                           NOTE: this option overrules every other option!\n    Examples: <path>/CatStyler -n1 -q\n              <path>/CatStyler -n2 -m\n              <path>/CatStyler -t\n\n- Make sure you have the MULTINODE flag on NO (see your LogOff<node>.info)\n\n  An example: commands/syscmd/logoff1.info\n\n    access=001\n    location=bbs:script1\n    MULTINODE=NO\n    priority=1\n    stack=50000\n    type=sim\n    name=logoff1\n\n\n  Okay, this all should do the trick!\n\n\n@ENDNODE\n\n@NODE Configuration "Configuration"\n\nConfiguration\n*************\n\n  The ''CatStyler.CFG'' needs to be located  in the S: assign.  The config-file\ncontrols the CatStyler actions.  It provides  CatStyler  with the  nescessary\ninformation about  locations of the  callerlogs,  conferences and the  styler\noutput.  Note that the flags are traced in CASE-SENSITIVITY by CatStyler.  So\nwhen you change something in your configuartion file,  make sure you keep the\nflag identification-name in the UPPER-CASE!!\n\n  CatStyler supports ANSI color and style commands, naturally.  That  is  you\ncan only use the ANSI codes ending with an ''m'', like <ESC>[32m or <ESC>[1m.\n\n  @{b}DO NOT REMOVE THE ''.''s BEHIND EVERY TOOLTYPE!\n  THE ''.''s ARE NOT ONLY THERE FOR SURVEYABILITY, CATSTYLER USES THEM!@{ub}\n\n@{"  EXTCATBUFSIZE  " Link EXTCATBUFSIZE}\n@{"  !CALLERLOGS    " Link !CALLERLOGS}\n@{"  !CONFERENCES   " Link !CONFERENCES}\n@{"  !STYLER        " Link !STYLER}\n\n  For a complete example on the configuration-file, ''S:CATSTYLER.CFG'', take a\nlook at the one that came with this package.\n\n@ENDNODE\n\n@NODE EXTCATBUFSIZE "EXTCATBUFSIZE"\n\nEXTCATBUFSIZE\n*************\n\n  EXTra CATalog BUFfer SIZE  is  used  to give  CatStyler  a bit more working\nspace,  which is  always  required  when you have  specified UPLOADINFO.  The\nbigger value you enter behind this flag,  the faster CatStyler gets.  This is\nbecause when CatStyler is out of free space,  the catalog needs to be written\nfirst and then read again, to open new memory. This ofcourse takes a  lot  of\nvaluable time. So the bigger the value, the faster CatStyler gets. Note that\nthe value is considered in kilobytes! An example:\n\nEXTCATBUFSIZE.... 32\n\n  This adds 32k (equals 32768 bytes) extra workspace to the catalog buffer.\n\n\n\n@ENDNODE\n\n@NODE !CALLERLOGS "!CALLERLOGS"\n\nConfiguring Callerlogs\n**********************\n\n  When you start editing your node configuration,  make sure you precede this\ninformation with a !CALLERLOGS, since CatStyler is scanning for this.\n\n  A decend 3 node log configuration should look like this:\n\n------------------------------------------cut--\n\n!CALLERLOGS\nLOG_NODE1........ BBS:NODE1/CALLERLOG\nLOG_NODE2........ BBS:NODE2/CALLERLOG\nLOG_NODE3........ BBS:NODE3/CALLERLOG\n~\n------------------------------------------cut--\n\n  When you''ve  completed  editing  your  node configuration,  don''t forget to\nnotify it to CatStyler by putting a single ''~'' at the end of it.\nNOTE: don''t remove the ''.''s behind each LOG_NODE<node>!  CatStyler  will  NOT\nwork properly when you do anyway!\n\n  When you''ve obeyed these rules, this part should work like a charm.\n\n\n\n@ENDNODE\n\n@NODE !CONFERENCES "!CONFERENCES"\n\nConfiguring Conferences\n***********************\n\n  As  similar  to  the  !CALLERLOGS,  the conference configuration  should be\npreceded by a !CONFERENCES. An example for one conference:\n\n------------------------------------------cut--\n\n!CONFERENCES\nCONF_NAME........ aMIGA\nCONF_UPLOADPATHS. EU:|EO:\nCONF_CATALOG..... BBS:CONFERENCES/AMIGA/DIR14\nCONF_FILEDIVIDER. |\nCONF_DATELINE.... [·NEW DAY!·]·[·TODAY: %o·]·[·YESTERDAY: %n, %f nEW fILES·]\nCONF_OLINECOL.... <ESC>[0m\nCONF_CLINECOL.... <ESC>[0m\n\n------------------------------------------cut--\n\n  CONF_NAME........ is used by the monitor option. You can enter any name you\nlike.\n\n  CONF_UPLOADPATHS. is used by CatStyler to determine in which conference the\nfile was uploaded on.  The name of this file is retrieved form the CALLERLOG,\nnaturaly. When you have multiple paths, divide your paths with ''|''.\n\n  CONF_CATALOG..... provides CatStyler  with the location of the to be styled\nfile-catalog  (or dir, as /X sysops say).  Note that the number, DIR<number>,\nwill decrease  when CatStyler  sees fit,  so keep the dir-number  as high  as\navailable.\n\n  CONF_FILEDIVIDER. when not ''-'', will make CatStyler place this string below\neach file,  to  divide the files from each other.  A ''|'' represents a RETURN!\nNOTE: You must end your string with a ''|''!!\n\n  CONF_DATELINE.... is the line that seperates two days.  When you don''t want\nsuch a line to appear  in your file-catalogs,  enter  a single ''-''.  You  can\nalso use a couple of % commands to use in this DATELINE, like:\n    %o = the date of the files below the DATELINE (date output is like /X)\n    %n = the date of the files above the DATELINE (date output is like /X)\n    %f = the amount of new files between two DATELINEs (= 1 day)\n  Note that the dates are retrieved from the file-catalog itself.\n  Also note that an extra RETURN is placed infront and behind the DATELINE.\n\n  CONF_OLINECOL.... is the Open LINE COLor.  This represents the color of the\nline that will always be printed above the CONF_DATELINE.\n\n  CONF_CLINECOL.... is the Close LINE COLor. This represents the color of the\nline that is printed below the CONF_DATELINE.\n\n  NOTE: the line mentioned at OLINECOL and CLINECOL are always 80 ''_''!!!\n\n\n  When you have more then 1 conference (ofcourse you do), seperate the\nconferences with a single ''*''. To notify CatStyler that the conferences are\nall configured, place a single ''~'' below the last CONF_CLINECOL.\n@ENDNODE\n\n@NODE !STYLER "!STYLER"\n\nStyler Configuration\n********************\n\n  The configuration of the styler output itself  is placed below the !STYLER.\nIt should look similar to this:\n\n------------------------------------------cut--\n\n!STYLER\nDOWNLOADTIMES.... D/L TiMES: [%%%]\nBELOWFILENAME.... N\nUPLOADINFO....... %19H Node %N / %T / %C CPS\nHANDLECOLOR...... -\nHANDLEOPEN....... [\nHANDLECLOSE...... ]\nZERODLTIMES...... Y\n\n------------------------------------------cut--\n\n  DOWNLOADTIMES.... is the string that will be placed at each file, once it''s\nuploaded (when ZERDOWNLOADTIMES is Y)  or  when the file is download at least\nonce. Everytime a user downloads the file,  the number increases.  The number\nconsists of three digits that are represented by three ''%%%''! So don''t forget\nto enter them in this string!!  You  control  the horizontal position  of the\nstring,  by placing spaces ('' '') infront of the text.  Be  sure to place  the\nANSI reset code, <ESC>[0m,  behind the last character  if you use ANSI colors\nand/or styles!\nNOTE: the amount of downloading is limited to 999 times! Should be sufficent.\n\n  BELOWFILENAME.... will place the DOWNLOADTIMES below the filename,  instead\nof positioning it  at the lowest spot  possible  (same height as UPLOADINFO).\nAcceptable parameters are ''Y'' or ''N''.\n\n  UPLOADINFO....... is the string  that contains info about  the person  that\nuploaded this file. If you don''t want UPLOADINFO, place one ''-'' here.\nYou can use following commands create a descent output:\n    %<width>H = uploader''s handle,  where width represents the maximum amount\n                of characters you want to be displayed.\n    %N = will place the node number on which the file was uploaded.\n    %T = the time on which the file arrived at the system.\n    %C = the CPS speed will be place on this position.\n\n  HANDLECOLOR...... this  ANSI color  is placed  in front of %<width>H,  that\nis if specified it. example: <ESC>[32m\nNOTE: If you do not wish to use ANSI colors, place a single ''-'' instead!\n\n  HANDLEOPEN....... these  character(s)  either ASCII and/or ANSI  are placed\ninfront of the %<width>H, that is if you use %<width>H. If you do not wish to\nuse HANDLEOPEN, place a single ''-''.\n\n  HANDLECLOSE...... these character(s) either ASCII and/or are  placed behind\nthe %<width>H. NOTE: If you don''t wish to use HANDLECLOSE, place one ''-''.\n@ENDNODE\n\n@NODE Tips_&_Hints "Tips & Hints"\n\nTips & Hints\n************\n\nWrite me a message if your CatStyler isn''t working. You can contact me at:\n\n@{" bOONDOCKs! " Link BOONDOCKS}, THE UNDISCOVERED, STONEHENGE or ENGINEERING!\n\n              ** Ask around for the numbers **\n@ENDNODE\n\n@NODE BOONDOCKS "bOONDOCKs!"\n           -( [ bOONDOCKS! ] [ oNE oF tHE fASTEST iN eUROPE ] )-\n    ________________________________________________________________________\n __/  __ __/   _ __/   _ __/   _ __/ ___ __/   _ __/   ____/   / __/   ____/\n \\_   _  \\_    / \\_    / \\_    / \\_    / \\_    / \\_    / \\_   _  \\_____  \\_\n  /   / ¯¯/  _/   /  _/   /   /   /  _/   /  _/   /  _/   /   / ¯¯/  _/   /\n /___     \\__     \\__     \\__/    \\__     \\__     \\__     \\__/    \\__     \\\n sAl1      \\/______\\/      \\/______\\/      \\/______\\/      \\/______\\/      \\\n   /        \\      /________\\      /        \\      /________\\      /\n  /          \\                    /          \\                    /\n   [·hELLFIRE wORLD HQ!·][·tRISTAR aND rED^sECTOR ¡NC!·&·lSD! aMIGA eHQ!·]\n                     [·oRIGIN!·&·iLLUSION! aMIGA eHQ!·]\n [·tRISTAR & rED^sECTOR ¡NC! cONSOLE·&·gERMAN cONSOLE sYNDICATE wORLD hQ!·]\n            [·pARADOX!·sUNFLEX iNC!·&·dEVIOUS dEZIGNS dUTCH hQ!·]\n                    [·pRO·ARTS·&·rOADHOGZ eUROPEAN hQ!·]\n \n      sTAFF: s/\\L-oNE·mARIO·sECTORCHARGER·aPOLLO·eCS·aSTRO·&·aRTIC cAT\n \n    2 * cREDITZ fOR mAJORS! 3 * cREDITZ fOR mAJORS fROM yOUR oWN gROUP!\n                 --»> lATEST aMIEXPRESS vERSION 4.xX! <«--\n         ---»> nO nEW uSER pASSWORD aND/oR sYSTEM pASSWORD! <«---\n \n-[ +31-(0)-548-540-653 ]--[ +31-(0)-548-521-716 ]--[ +31-(0)-548-521-848 ]-\n     -[ 16k8 dUAL ]-          -[ 16k8 dUAL ]-          -[ 16k8 dUAL ]-\n@ENDNODE\n\n@NODE Known_bugs "Known bugs"\n\nKnow Bugs\n*********\n\nNONE, but if you find one anyway,  be so kind to report it to me.  Credits  go\nwhere deserved!\n@ENDNODE\n\n@NODE History "History"\n\nHistory\n*******\n\nV1.0 Beta 1 - June 16, 1995\n- First test release!\n\nV1.0 Beta 2 - June 17, 1995\n- Program crashed while processing dirs for the second time;\n  This  was  caused  by some direct memory written codes,  I used for checking\n  CatStyler. I thought I removed them before release, but nope.. Dumb!\n\nV1.0 Beta 3 - June 18, 1995\n- Conflict: If CatStyler was busy  and a user added  a file  to  the  catalog!\n  Fixed this by checking the catalog''s FileInfoBlock before writing changes.\n- Crash was NOT fixed at all.  I  now  found  the  real  problem:  CatStyler''s\n  port wasn''t properly opened. It is now.\n- Added monitor option in commandline.\n- Added EXTCATBUFSIZE in config. With this you can adjust the extra Workbuffer\n  of Catstyler.  Small buffers  cause several writes while  large buffers  may\n  only take one write action. Large buffers make CatStyler faster.\n\nV1.0 - July 2, 1995 @{b}(First Public Release)@{ub}\n- Added CONF_NAME to the config file.\n- Improved monitor function;  current CONF_NAME and config-error messages  are\n  now shown too.\n- Added an option to  test  the configuration file.  To do this, use -t at the\n  commandline.\n- Added CONF_FILEDIVIDER.  This can  be used  to specifiy  your  own  line  to\n  divide the files from each other.\n- Improved catalog-scanning; it''s slightly faster now.\n- Added ''Free Downloading'' to the styler''s DOWNLOADTIMES detection.\n- Added ''|'' to the CONF_FILEDIVIDER. It''s used as a RETURN!\n- Added one extra RETURN infront and one behind the DATELINE.\n\nFUTURE\n- I might make the DATELINE @{u}fully@{uu} configurable.\n- Your suggestions and ideas are very welcome. See @{" Tips & Hints " Link Tips_&_Hints} if you want\n  to contact me!\n\n@ENDNODE\n\n@NODE Acknowledgments "Acknowledgments"\n\nAcknowledgments\n***************\n\nThanks to myself for writing this very nice piece of code, he, he..  =:^)\n\n  Musical support: Eagles / Hell Freezes Over\n                   Mariah Carey / Music Box\n                   Star Trek / Generations, Original Motion Picture Soundtrack\n                   Extreme / III Sides To Every Story\n                   Level 42 / Level Best\n                   Marillion / Misplaced Childhood\n                   Foreigner / The Very Best Of\n                   Rock Romances Vol. 1\n                   Star Trek: Deep Space Nine / THE EMISSARY\n\n\nAlso thanks to SAL-1 for giving me the opportunity to write this for /X.  Also\nthanks for the usefull ideas and for betatesting this kewl CLI utility.\n\n\nAnd thanks to my brother PICARD/PROJECT_A! for writing this guide.\n\n\n@{fg highlight}  ** Greetings go to all members of ROYAL, PROJECT_A! and all our friends! **@{fg text}\n@ENDNODE\n\n','\n',char(10)),'{"ACCESS":"001","LOCATION":"bbs:script1","PRIORITY":"1","STACK":"50000","TYPE":"sim"}','auto-added',16544,1,0,NULL,NULL,'rylxcs10','scan',1780048704);
INSERT INTO door_catalog VALUES('rz_xtol','RZ-XTOL.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/RZ-XTOL.LHA',NULL,'XIM','LE-win5-96.exe',NULL,NULL,'RZ','and MagicPager',replace('                Ansi-Skipper\n                    and\n                 MagicPager\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                                                .------''\n             `------------------------------------------------''\n','\n',char(10)),NULL,'auto-added',10967,5,0,NULL,NULL,'rz_xtol','scan',1780048704);
INSERT INTO door_catalog VALUES('r_d_lcna','R^D-LCNA.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/R^D-LCNA.LHA','LHA-CHECKnADD','XIM','LHA-CHECKnADD',NULL,'DjaX','R^D','\_____   ¬\_   _________/|    /  ___/_ _/  ¬_    <   .   ¬\_   !   /   _)  ¬\_ \____!\ ___\ _!____ / \    /_________ /',replace('  __________ ______________._____ _____\n  \_____   ¬\_   _________/|    /  ___/_\n   _/  ¬_    <   .   ¬\_   !   /   _)  ¬\_\n   \____!\ ___\ _!____ / \    /_________ /\n          \/         \/   \  /         \/\n       d.E.S.I.G.N.!  `95  \/  sHOWS yA...\n   <=- LHA-CHECKnADD V1.0 coded by DjaX -=>\n   <-------------------------------------->\n    The fastest and shortest LHA-Checker\n    in his efficiency only 2544 bytes!!!\n    freely configurable with many options!\n    -=-=- MIRROR ADD OPTION INCLUDED -=-=-\n         Why using something else ?????\n    <--100% ASM XIM POWER FOR AMI/X /S!X-->\n','\n',char(10)),'LHA-CHECKnADD.doc',replace('                              ___\n                           /\/  /\n_________   _________ _   /    /_____\n\____    \\/  ______/  \//    /  ___/    \n_/   _    <   .    \_   /    /   _) \/\_\n\____!\ ___\ _!____ /\      /_________ /.........\n       \/         \/__\    /__     __\/__·:::::::: /\   ___________\n    :               \__\  /.  \/\\/  ___/     ::::/  \\/  ._______ \/\\___\n    |               ___ \/ !     \_  _) \/\::::::·    \_  !/   \_ \   \   \_\n    |              (_____________ /_______ /::...... _ /_______ /__\______ /\n    !                           \/    ·::\/::::::::::\/       \/         \/\n    :                                                              :\n    |                                                              |\n    `-- ->>      Ami/X /S!X Door Developement Devision      <<- ---''\n            \n\n                                 PRESENTS\n\n               LHA-CHECKnADD V1.0 coded by DJAX/RAVE^DESIGN\n\n              pOWER nEEDS cONTROL .....CHOOSE FOUR QUALITY !!\n\n\nWHY SHOULD YA USE THIZ AND NO OTHER LHA-CKECKER IN YOUR BBS?\n------------------------------------------------------------\n\n        -> It`s the shortest and fastest LHA-Checker in his efficiency,\n        -> It`s 100% coded in Assembler (2544 Bytes!!)\n\n        Remove ALL BBS-ADDS via Strip-File !\n        Adds BBS-ADDS via Add-File as many as ya want !\n        \n        The special Feature is ya can add a BBS-Add with the turned \n        Name from the LHA/LZH Archive Name! (Mirror-Option)\n        \n        z.b.: The LHA/LZH Archive have the Name "THEBEST.lha" so ya\n              BBS-ADD will be added with the Name "TSEBEHT"\n\n        It`s freely configurable with many options !\n\n        Error-Handling routines included, so it will never crash\n        if ya haven`t enough memory or configured someting wrong !\n\n        DjaX make it possible :)\n\n\nHOW TO INSTALL :\n~~~~~~~~~~~~~~~~\n        Copy the files in your CHECKER: Directory or wherever you want\n        and make an ASSIGN to it called CHECKER: !\n\n        Change your FCheck-Files LHA and LZH to this :\n \n        >>--------------Cut here-------------<<\n        CHECKER:LHA-CHECKnADD\n        CHECK=ON STRIP=ON ADD=ON\n        WARNING: Skipping corrupt/extraneous data\n        Operation not entirely successful\n        >>--------------Cut-here-------------<<\n\n        Maybe you can swith some of this options :\n\n        CHECK=ON/OFF turn the check-option on/off\n \n        STRIP=ON/OFF turn the stripping option on/off\n\n        AMI/X 3.x User can make icons including this but\n        the easiest way is to copy the FCHECK DIR included\n        in your BBS:FCHECK Dir -!\n\n        IMPORTANT:\n        ----------\n\n        Your LHA must be available through an Amiga-Path !!!\n        I use LHA V1.92, I don`t know if it works with older versions.\n        but simply copy the LHA included in archive in your C: Drawer\n        and there should be no problems!!\n\n\nHOW TO STRIP AND ADD BBS-ADDS :\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n        There are three Config-Files : \n        LHA-CKECKnADD.strip\n        LHA-CHECKnADD.add\n        LHA-CKECKnADD.mirr\n\n        The Strip File includes all Filenames you want to be stripped\n        wildcards allowed (e.g. *.displayme) !\n\n        Be careful with Wildcards ! If you use them wrong it will\n        strip more files as you want !\n\n        You can strip ALL ILLEGAL FILENAMES, too !\n\n        THE Add File includes all Filenames you want to be added !\n        Be shure that the Path and Add-Names are correct !\n        Otherwise no file will added to archive !\n \n        The Mirr File is the BBS-ADD that will be added with the turned\n        name from the LZH/LHA Archive name !\n        Include thiz and no Stripper can Strip yor BBS-ADD ..cool eh???!!\n\n\nLAST WORDS :\n~~~~~~~~~~~~  \n        Now enjoy and have fun with thiz great tool !\n\n        For Bugs (nobody is perfect), Ideas (yeahh !!) or just 4 fun\n        call my BBS:\n\n                 Ho/Y\eBøy·£a/\/d      rAVE^dESIGN AUSTRIA HEADQUARTERS !\n                ~~~~~~~~~~~~~~~~~~     SIGMA SEVEN EUROPE HEADQUARTER !\n                                       S-eXPRESS dISTRIBUTION & sUPPORT BBS !\n\n         Keep the bytes mates...\n                                           DjaX !\n                                           ~~~~\n\nYou can also reach me at one of thiz great BBS:\n\nWORLD TRADE CENTRE /AUSTRIA\nDARK ILLUSION /AUSTRIA\nMETAL CHURCH /AUSTRIA\nBLACK MOON /GERMANY\nSYNERGY /GERMANY\nLAST OUTPOST /HOLLAND\nEVERY MEMBER BBS OF rAVE^dESIGN\n......and in every BBS ya can find me !!!\n\n\nTHANKS TO MY TWO TESTERS :\n--------------------------\n       \n        Prayer (World Trade Centre), Sigma Seven (Synergy)\n\n\nGREETINGS flow out to:\n~~~~~~~~~~~~~~~~~~~~~~\n\nSigma Seven       (4 da best BBS System)\nSintax/WOT        (4 da great lib) \nCalypso/GOD       (nice Doors)\nPrayer/TRSI       (User Terror rulez!!!!!!!!!)\nCø®TeX/TRSI       (Bundesheer rulez eh??)\nRico/S7           (Intel Inside ...Idiots outside!)\nStage             (Bleib cool du Pfeife)\nFanfare           (naja schmecken net so gut)\nALL rAVE^dESIGN Members       (macht euch mal locker)\n\nand all i have forgotten................\n\n»»»-·¯·-_·-·¯·-_·-·¯·-_·-·¯·-_·-·¯·-_·-·¯·-_·-·¯·-_·-·¯·-_·-·¯·-_·-·¯·-_·-«««\n\n          RAVE DESIGN AHQ ^ S-EXPRESS AUSTRIA - DISTRIBUTION SITE !!\n\n                              /\                              /\\n________: __ __________ ___  //\\ _________ __ ______  ..::::.. \ ______\n\       |_\_\\______  ¬\  ¬\/   \\.    __________   ¬\:::::::::: \_    ¬\\n \.     !¬\____    /   \\      _  \\   _)_/\    ¬    <_·::: :::\_____    \_\n  \\         ./   /    //    //    \     ¬ \\   !     .\::: ::::    ¬    ./\n   \·   :   //_________/__\\//______\______·/_________//::::::::________//\n    \___|___/              \/             \/         \/ ·:::::·        \/\n«--- --- -- - -- ---=» R A V E  ^ D E S I G N  A H Q ! «=--- -- --- - -- --+\n _______.                                                                  !\n \     ¬: _ __ _________          /\                                       :\n  \.   _!_____  .______/________ //\\           +- -- ---- -- -- -- -+     |\n   \\  \     /       ¬\ ____   ¬\   \\ ________ !  +.43.aSK 4 IT     ! «=--+\n    \·     //   :     .\   ¬\    \   /· __.   ¬\`-+-- -- - --- - -- -++    :\n     \_____/ ___l___   \\   \\     ./__/ ¬!    .\ ! sYSOPED bY..      !    |\n               _ __\   //_____\   //            \\_  dJAX ^ eL bUNDY  : «=-''\n                    \\//hOT_ __\\//______________ /    cOMMUNIcATOR   |\n                     \/         \/              \/`-- --- -- --- - ---''\n \n--[^rUNNING S!X0.x^68ø4ø^1 GIG oNLINE^cOOL sYSOPtEAM^lATEST aMIGA wAREZ^]--\n              --[^sUPORTING aMIGA^sNES^/X^xXx^mUSIC&aSCII^]--\n      --[^rAVE dESIGN `N tRSI rELEASES fREE dOWNLOAD!!!^cC-sUPPORT^]--\n\n·············································································\n                