INSERT INTO door_catalog VALUES('s_zip100','S!ZIP100.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/S!ZIP100.LHA','ZipChk','XIM','UnZip',NULL,NULL,NULL,'| ZipChk v1.00  | Zip Checker 4 AmiExpress | +---------------+--------------------------+ | © The Silencer / Repulse BBS, in 1995-96 |',replace('.---------------.--------------------------.\n| ZipChk v1.00  | Zip Checker 4 AmiExpress |\n+---------------+--------------------------+\n| © The Silencer / Repulse BBS, in 1995-96 |\n`------------------------------------------''\n[THE]=--=] cS!-^-sAD-^-hJB-^-KLF! [=--=[PUB]\n','\n',char(10)),'ZipChk.DOC',replace('\n                                 ·° °     °\n                                 : °     ° °·\n                                 ¦ REPULSE! :\n                                 |   _____  ¦\n       GdH_______________________|__/    /__|_____    __________________g''S\n        _/   _____/   ___________  ¬\   /¬\      /___/   _____/   _____/\n       /    __  ¬\   ___)_/     /    \ /   \    /  ¬\____   ¬\   ___)__\n      /      /    \_ /    ¬\_ _______//     \_ /     \_ /     \_ /    ¬\_\n      \_____/      /__      /_/ _______      /__      /__      /__      /\n            \_____/  \_____/     |    \_____/  \_____/  \_____/  \_____/\n                                 ¦          |\n                                 :° °     ° ¦ Core of the Underground\n                                 . °     ° °:\n                                            .\n\n\n                         Hey, The Silencer is back.\n\n   Reopened my board after the AT&T bust about 1 year ago and started\n to code again. Though I only have time to code on the weekends and\n at that time you don''t wanna spend time infront of a computer =C..\n\n   Small dilemma there.. anyways I released this tiny Zipchecker coz\n of a request from Crawl, Sysop at Another World...\n There are 2 other zipcheckers that I know of, and there are 2\n common error''s on zip archives.. Checker no.1 detects error #1\n but not error #2.... And checker no.2 detects err #2 but not #1..\n Catch my drift?\n This checker detects all errors that can occur, thats why\n you should juice it.\n\n   Simply copy all the philes where they belong.. No configs or\n anyhting to think about, it''s all there.\n\n   Nothing new about the bust either. The trial will be sometime\n in the beginning of next year.. suxx doesn''t it.. They said I was\n no.1 in Sweden abusing CC''s, yah right..\n\n   To register all ''Silencer'' quality prod''s just call Repulse BBS\n and type REG at the prompt to recieve a registered copy of\n desired util.\n\n                            +46-(0)8-998352\n\n\n\n                                                / The Silencer\n\n                                         [email removed]\n\n\n','\n',char(10)),NULL,'auto-added',62414,5,0,NULL,NULL,'s_zip100','scan',1780048704);
