INSERT INTO door_catalog VALUES('s7_st10b','S7-ST10B.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/S7-ST10B.LHA',NULL,'XIM','/\_____  ____/\_            __     ____',NULL,'DjaX/S7','S7','/_  ___/_ \__ ___) /\  _    /  \   /__  \ \   \/  \ // :__ // \/ \  / _: \  __/  / //   \\/\_\/  | \\/  :  \\/  \_  \_\_  _\',replace('  /\_____  ____/\_            __     ____\n /_  ___/_ \__ ___) /\  _    /  \   /__  \\n  \   \/  \ // :__ // \/ \  / _: \  __/  /\n //   \\/\_\/  | \\/  :  \\/  \_  \_\_  _\\n \  /__/___/___:  \\__|_   /___|___/ / /\n<-\/------------\__/----\ /----------\/--->\n  .     o                Y     o      \n   ·.· Sysop Transmit V1.0b by DjaX/S7 !\n THiz is a must for all ya Sysops!! GREAT!!\n Now with configfile and some more features \n ASM XIM POWER ! Why using something else?\n','\n',char(10)),'SysTerm.Doc',replace(' \n                   /\_____  ____/\_      [CTX] __     ____\n           /\     /_  ___/_ \__ ___) /\  _    /  \   /__  \        /\\n          /  \     \   \/  \ // :__ // \/ \  / _: \  __/  /        \/\n          \  /    //   \\/\_\/  | \\/  :  \\/  \_  \_\_  _\        :·\n          :\/:   :\  /__/___/___:  \\__|_   /___|___/ / /::         .\n    /\     .    :::\/            \__/::  \ /::        \/::::    /\ \n    \/    .      ·::·   o          ·:·    Y::·  o     ::::     /  \\n    :·      .       _          +          :  +        (_)      \  /\n     .             (_)     °              .       °            :\/:                           \n                           Sysop Transmit V1.0b                                       .\n                                                               .\n                                                                ·\nWHAT`S THE USE OF THIZ TOOL ?\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n      Have ya ever wanted to send something to a user which is not in\n      the BBS dir ??? - Please don`t say no hehheh!!\n      Ok so ya know its very awkward to copy the files into the dirs, or\n      using da SysopDownload Door (ds) ...but having to raise the sec level\n      of the user to sysops level...???!!!!!\n\n    *********************************************************************\n    ·****** A·L·L  T·H·A·T  B·O·R·I·N·G  T·I·M·E·S  A·R·E  O·V·E·R *****·\n    *********************************************************************\n\n      Sysop-Transmit allows ya to send file(s) to a user online via\n      ReqTools Filerequester...\n\n USAGE:\n ~~~~~~\n      After starting the door the user will get some infos.\n      Now you''ll be able to select the file via requester you which\n      to send.....try it out!!!\n\n      Multiple file sending from the same directory (by holding SHIFT-KEY)\n      is possible !!!\n\n\nThiz geat door requires follow things...\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n      - an Amiga Model like 500,600,1200,2000,3000,4000,VC20,C+4,C64\n      - installed Version of OS\2, OS\3 or higher\n        (Soft or Hardware Version)\n      - the command icon (included in package)\n      - Libs:AEDoor.library ( © Sintax/WOT )\n      -      ReqTools.library (Any Version)\n\n\nINSTALLATION:\n~~~~~~~~~~~~~\n      Copy the files in the archive to your directories,\n      they are:\n     \n      BBS:Commands/BBSCmd/ST.info\n      BBS:Doors/SysTerm/SysTerm.XIM\n      BBS:Doors/SysTerm/SysTerm.CFG\n      BBS:Doors/SysTerm/SysTerm.Doc\n      LIBS:AEDoor.library ( © Sintax/WOT )\n      LIBS:reqtools.library (if ya don`t have it)\n\n        PLEASE DON`T 4GET TO CHANGE THE PASSWORD IN THE COMMAND.ICON\n\n\nEXAMPLE FOR CONFIGFILE:\n~~~~~~~~~~~~~~~~~~~~~~~\n\n>>>>--------------Cut-here--------------<<<<\n; Sysop Transmit V1.0b by DjaX/S7 !!\n-------------------------------------\n#\nRam:                                   ; Default Path for Filerequester\n                                       ; Don`t forget the ":" at end!!!\n\n>>>>--------------Cut-here--------------<<<<\n\nYa will get a errormessage if ya don`t have installed the configfile!!!!!\n\n\nLAST WORDS :\n~~~~~~~~~~~~  \n        Now enjoy and have fun with thiz great tool !\n\n        For Bugs (nobody is perfect), Ideas (yeahh !!) or just 4 fun\n        call my BBS:\n\n                 Ho/Y\eBøy·£a/\/d      SIGMA SEVEN AUSTRIA HEADQUARTERS !\n                ~~~~~~~~~~~~~~~~~~     S·7 MEMBER AHQ !\n                 ++43-7612-75059\n\n         See ya soon mates...\n                                           DjaX/S7\n\nTHANX TO :\n~~~~~~~~~~\n\n         My beta-testers :\n         -----------------\n                 Cø®teX TRSI/DARK ILLUSION (thx 4 da textcoder)\n                 Jaydee/Chiemsee BBS\n                 PRAYER TRSI/WORLD TRADE CENTER (thx for ya logo)\n                 PAT/ECSTASY ISLE\n                 STAGE/S·7\n         You also can reach me on these boards !\n\nGREETINGS:\n~~~~~~~~~~\n       - Calypso/GOD - Prayer/TRSI - Cø®TeX/TRSI - TermX - Rico/S7 -\n       - Stage - Al Bundy - Sintax/WOT (4 da great lib) - Pee Wee - \n        - Pat - Fanfare - Psycho - Tekkno - Lion - \n                        - AND ALL S7 MEMBERS -\n\nLast words:\n~~~~~~~~~~~\n           \n                for a registered version of any door from me\n                             call +43-7612-75059!!\n\n»»»-·¯·-_·-·¯·-_·-·¯·-_·-·¯·-_·-·¯·-_·-·¯·-_·-·¯·-_·-·¯·-_·-·¯·-_·-·¯·-_·-«««\n\n        /\__ ___  /\_ /\___  ___ _/\______   _/\_____  /\_ /\__    /\\n        )   |  ¬|/  ¬\\_   \/  ¬\\__     ¬\  \_     ¬\/  ¬\\  ¬\  /  )\n        |   :   )  +  \|   _  _  \|  _/\__/  :|   :   ) _  \\   \/  /\n       :|       |  |   \    \/    \   __/_  ::|   +--(  |   \\    :/\n      ::|   :   |  :    \   ||    /      ¬\:::|   :   ) :    \:/  |::\n     :::|   l___j ______/___jl___/l_______/ ::l______/_______//   |:::\n      ::| __/                                ::·         [CTX]\__ |::\n       :l/ - SIG/Y\A SEVEN AHQ - AUSTRIA MEMBER·HEADQUARTER BBS -\j:\n                                                                 CøøL\n            /\       /\__      /\__  /\_____ /\______             SySoP\nS¡G/Y\a 7  /  \      )  ¬|    /   ¬\ )     ¬\\_     ¬\     /\      TeAm !!\n  aHQ      \  /     :|   |__ /      \|  -+   \|   :   \    \/    /\\n      /\   :\/:    ::|   | ¬\   Y    \   |    \   |    \   :·   /  \    C\n      \/    ·     :::|   :   \  |    /   |    /   l    /    .   \  /    ø\n      :·   . ·     ::l_______/__l_  /l___l___/|_______/:        :\/:    ø\n       .    .       :·            \/       ·:::::::::::· nUMBER    ·    L\n                    - pOWER nEEDs CønTrOL -              ~~~~~~ :· .\n                                                     +43-7612-75059     R\n                                                                        a\n      rUNNING AMI-eXPRESS V4.3 - cOOL sYSOPTEAM - lATEST aMIGAWARE      T\n      X/-sUPPORT - sNES - hOT X-rATED pICCYS - eVERY tIme Hot mUSIX     i\n    \<< SIGMA SEVEN>>|<<TRSI>>/-Releases fREE dOWNLOAD !!! CC-sUPPORT   O\n                                                                        S\n       */cALL nOW !!!! - aND eNJOY tHE rEAL wAY oF fRIENDSHIP !!! \*    !\n\n','\n',char(10)),NULL,NULL,20468,2,0,NULL,NULL,NULL,'scan',1780048704);
