INSERT INTO door_catalog VALUES('sad_jc11','SAD-JC11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SAD-JC11.LHA','GD-JOINCNF','XIM','GD-JOINCNF',NULL,'Mo/Al','SAD','_____ ___.  ____.   _____/  |_ _   ___. .__\   /   _|_/   _|___\   /    /__)_/  _|__ |  |\  \  |  /  _|  /  /  /    |    /  |   /',replace('                             __.\n   _____ ___.  ____.   _____/  |_ _   ___.\n.__\   /   _|_/   _|___\   /    /__)_/  _|__\n|  |\  \  |  /  _|  /  /  /    |    /  |   /\n|______/_____\______\ ___/\____|____\______\\n.------------------|___|---------------÷e÷-.\n|  GraveDancer''s JoinConference Door V1.1  |\n| BugFixed, Enhanced and New Layout ©Mo/Al |\n`----[ Sceptic AmiExpress Design 1996 ]----''\n[ 09:23 ]--------------[ TOWER OF SOULS ]- -\n','\n',char(10)),'GD-JOINCNF.GUIDE',replace('@database SAD-Checker.guide\n@$VER: 1.1\n@author "graveDancer/sAD ([email removed])"\n@(c) "(sCEPTIC /X dESIGN 1995/96)"\n@remark cREATED uSING cED 3.5\n@node "Main" "English Doc for Multi Checker)"\n\n      .:::::::::::::::::::: .:::::::::::::::::::. ::::::::::::::::::.\n      `:::::::::..........  :::::::::: :::::::::: :::::::::: :::::::::.\n      .......... :::::::::: ::::::::::::::::::::: :::::::::: ::::::::::\n      ::::::::::.:::::::::: :::::::::: :::::::::: :::::::::: ::::::::::\n      `:::::::::::::::::::'' :::::::::: :::::::::: ::::::::::::::::::::''\n                            ::::::::::\n                        .                            .\n                      .:::. sCEPTIC /X dESIGN 1996 .:::.\n\n                                  pRESENTERA\n\n           JoinConference Door by GraveDancer/Sceptic /X Design\n\n                                 @{"Coypright Notes" link "CopyRight" 0}\n                                 @{"Introductions  " link "Introducti" 0}\n                                 @{"Features       " link "Features" 0}\n                                 @{"Install to /X  " link "Install" 0}\n                                 @{"Registration   " link "registration" 0}\n                                 @{"SAD Members    " link "members" 0}\n                                 @{"Contact SAD    " link "contact" 0}\n\n        sAD - wE dON`t oNLY pLAY tHE gAME ... wE lEAD aND dOMINATE iT!\n\n@endnode\n@node "Copyright" "Copyright notes"\n                                @{b}Copyright Notes@{ub}\n\n          pERMISSION iS gRANTED tO fREELY dISTRIBUTE tHIS pRODUCT fOR\n     nON-cOMMERCIAL pURPOSES oNLY, aS lONG aS aLL fILES rEMAIN uNMODIFIED.\n\n              sELLING iS sTRICTLY fORBIDDEN wITHOUT aNY eXCEPTION!\n\n   Join Conference is a ..... ..... ©95-96 ................. GraveDancer/sAD\n   Design for this door is a ...... ©96-xx ....................... Mogue/Al!\n   AmiExpress is a ................ ©xx-95 ......... Lightspeed Technologies\n   Cygnus Ed is a ................. ©87-93 ................. Cygnus Software\n   RexxTricks.library is a ........ ©94-95 ................ Jürgen Kohrmeyer\n   RexxSupport.library is a ....... ©xx-94 ....................... Commodore\n   Amiga is a ..................... ©xx-96 ........................ Escom AG\n   LHA is a ....................... ©91-96 ................... Stefan Bøberg\n   LZX is a ....................... ©95-96 ... Data Compression Technologies\n\n     iF yOU wANT tO pUBLISH tHIS oR aNY oTHER "©sAD" lABELED pRODUCTION oN\n          a PD SERIES mEDIUM get iN cONTACT wITH tHE aUTHOR tO gET aN\n                             hANDSIGNED pERMISSION!\n\n                      Gravedancer / Sceptic /X Design\n\n     PS: If you want to become a DIST SITE / BETA SITE then get in Contact\n                              with me (the Author)\n\n                                    @{"Main Menu" link "Main" 0}\n@endnode\n@node "Introducti" "Introduction"\n@{b}Introduction@{ub}\n\nThis is an bugfixed and enhanced version of my "j" replacement...\n\nWell ... just have a look on the @{"FEATURES" link "Features" 0} and you`ll be amazed!\n\n                                    @{"Main Menu" link "Main" 0}\n@endnode\n@node "Features" "Features"\n@{b}Features@{ub}\n\n · designed by mogue/al!\n · real relative conferences\n · shows statistical information about the conferences\n\n                                    @{"Main Menu" link "Main" 0}\n@endnode\n\n@node "Install" "Installation to /X"\n@{b}Installation@{ub}\n\n1) Make a dir  named: "DOORS:SCEPTIC" and copy the dir "GD-JoinCnf" to\n   this location.\n\n2) Copy the "J.info" to your BBSCMD/.\n\n3) Copy the "Examine{x}.info to your SYSCMD/ and rename it, please make\n   sure to make this change also in F!-START.INFO !!!\n\n4) This door need the rexxtricks.library. Get it from aminet or from the\n   archive sad^libs.lha.\n\n\n                                  @{"Main Menu" link "Main" 0}\n@ENDNODE\n\n@node "Contact" "Contact SAD"\n\n                                 @{b}Contact SAD@{ub}\n\n     please call one of the listed Sceptic AmiExpress Division bbs''s below for\n any kind of suggestions/bug-reports or registration...\n\n\n           *The Pub          - Flite!          - +49-private! - WHq\n            Evil Moon        - Clyde Radcliffe - +49-private! - EHq\n            Raveland         - H2o!            - +49-private! - GHq\n            Silent Service   - Rudolf          - +61-private! - OzHq\n            Forbidden Planet - Green Beret     - +35-private! - IrlHq\n            Greyhound        - Gurgle          - +39-private! - IHq\n            God''s Harem      - Lance           - +49-private! - Dst\n            Planet Love      - Mephisto        - +49-private! - Dst\n            Traders Assault  - Starlight       - +49-private! - Dst\n          **Tower of Souls   - Gravedancer     - +49-private! - Dst\n\n                    Reach Me Also On These Fine Systems\n\n            Apocalypse Now   - Stylewars       - +49-PROTEST\n            Brain Crash      - Krypton         - +49-PRIVATE\n          **Endless Pain     - Mogue           - +49-ARCLITE\n            Fairy Land       - Data            - +49-PROTEST\n            Fast File System - Scandic         - +49-DECISION\n            Final Impact     - U-man           - +44-ARCLITE\n          **Homeless         - Slime           - +49-CONTRA\n            Masturbation S.  - Black Peard     - +1-PRIVATE\n            Rebellion in M.  - Dhm             - +47-PRIVATE\n          **Silent Moon      - Tolpan          - +49-SARDONYX\n           *Spirit Of Soul   - Mario           - +49-TRSI\n            Zillion Hours    - Traitor         - +47-PRIVATE\n            Zions Hideout    - Zion            - +1-PRESTIGE\n\n                      !Still searching for more worldwide!\n             Stars Mark Boards I Call Regulary Than The Others\n\n     You can also use [email removed] for email contact.\n\n                     Send your registration fee to...\n         Sebastian Bergmann, Aulgasse 14, 53721 Siegburg, Germany\n    (Don''t Abuse This Address - I Mean No Trading Etc - No Illegals...)\n\nSoon our hompage in http://users.aol.com will be open for you to get the\nlatest SAD releases 1 minute after release ...\n\n\n                                  @{"Main Menu" link "Main" 0}\n@endnode\n\n@node "members" "SAD Members"\n\n\n  ................................                  ..............\n  :                              :                  :            :\n  :                              :                  :            :\n  :                              :                  :............:...........\n__:____                   ______ :    ____________._      _______:          :\n\\   __/________ ______   / __  /_:___/  ___   ____|_______\\_____/_  ______  :\n \\______       / ____/__/_ \\__/      \\_ \\_____\\__      /           / ____/__:_\n..: \\_________/  \\        \\___________/__:___|  |     /__________ /  \\      : \\_\n:            /_____________/(rLf):              |       |     -T!/__________:__/\n:                 ......         :              l_______|                   :\n:....             :    :.....    :                                  ........:\n:...:     ........:         :    :....                              :\n          :...:             :....:   :                              :\n              :                  :...:............                  :\n              :                                  :                  :\n                ........................         :        .....     :\n                :                      :         :........:   :.....:\n            a.M.I.E.X.P.R.E.S.s        :                  :...:\n                :                      :\n                :               d.E.S.I:G.n\n                :......................:\n\n\n@{b}Sceptic /X Design members@{ub}\n~~~~~~~~~~~~~~~~~~~~~~~~~~\n@{b}Fli7e             @{ub}Leader, Rexx Coder, Sysop(WHQ), @{b}Caustic Style Artist@{ub}\n@{b}2fAST             @{ub}Rexx Coder, @{b}Contra Artist@{ub}\n@{b}GraveDancer       @{ub}Rexx Coder, @{b}Protest Artist@{ub}\n@{b}H2o               @{ub}Sysop(GHQ), @{b}Contra@{ub} Artist@{ub}\n@{b}Wigwam            @{ub}Asm Coder\n@{b}Bird              @{ub}Asm Coder\n@{b}Clyde Radcliffe   @{ub}Sysop(EHQ), Asm Coder\n@{b}Starlight         @{ub}Sysop(EDIST)\n@{b}Lance             @{ub}Sysop(GDIST), @{b}Pussy Posse Leader@{ub}\n@{b}X/\D               @{ub}Sysop(IDIST), @{b}Nightfall Leader@{ub}\n@{b}Rudolf H.         @{ub}Sysop(OZDIST)\n@{b}Green Beret       @{ub}Sysop(IRL HQ)\n@{b}Mephisto          @{ub}Sysop(EGDIST), @{b}DG! Leader@{ub}\n@{b}Picard            @{ub}Sysop(GDIST)\n\nNo one else! All who claim to be SAD are pure liers if they`re not listed\nin the one above!\n\n                                  @{"Main Menu" link "Main" 0}\n@endnode\n\n@node "Registration" "Registration details - taken from SAD-GDRG.TXT"\n\nHi folks,\n\nafter a long discussion with my maties fli7e and 2fast i came to the\nconclusion to demand a registartion fee for my "bigger" doors, such\nas my multichecker.\n\nThe registration fee will be 30,- german marks or 20,- american dollars\nif you do not live in germany.\n\nOff course "smaller" doors will be then released full working and will\ndisplay your registration string if you have the right keyfile...\n\nYou have to pay the fee only once and you will, after i recieved the money,\nget an keyfile which registers all my doors available to your bbs.\n\nI do not think that a fee of 30DM/20USD is too high for a bunch of high\nquality doors which are tested to run 100% and feature speed and nice\noutfit.\n\n- - -\n\n\nThis door is 100% usable in public release!\n\n\n                                  @{"Main Menu" link "Main" 0}\n\n@endnode\n','\n',char(10)),NULL,'auto-added',30542,3,0,NULL,NULL,'sad_jc11','scan',1780048711);
