INSERT INTO door_catalog VALUES('sad_np10','SAD-NP10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SAD-NP10.LHA',NULL,'XIM','__,.-==========================- -=======-.',NULL,NULL,'SAD','_\__:                                      : \  /:dOORNAME: nUSERpROCESSOR v1.o         : \/ :  aUTHOR: fLI7e/sAD                   :',replace(' __,.-==========================- -=======-.\n_\__:                                      :\n\  /:dOORNAME: nUSERpROCESSOR v1.o         :\n \/ :  aUTHOR: fLI7e/sAD                   :\n __ :                                      :\n___|:fEATURES:-eNHANCED NUSER aNSWER dOOR  :\n\__l:          wITH gREAT sYSOP fUNCTIONS  :\n    :          aND nICE lAYOUT!            :\n___|·                                    __:\n\__|·                                    \/:\n-==-·-===========[sCEPTIC /X dESIGN |995]=-''\n','\n',char(10)),'SAD-nUSERpROCESSOR.doc',replace('\n\n\n\n\n   _________               ________            ___________          ________\n_ _\   ____(_  ________  __\  _____l_  ________\__       (_  ____ __\  _____l_\n    \____    |_\  _____l_    __|     |_\   ___   /____     |_\__/__     |     |\n __ _________|     |     |___________|      \___/  l_______|       |__________|\n           l_____________| ÷f!÷     l________|           l_________|\n\n\n\n                 a·M·I   e·X·P·R·E·S·S   d·E·S·I·G·N   1·9·9·5\n\n                                p·R·E·s·E·N·T·z\n\n\n\n      .  .:.--¡!------------------------------------------------¡:----.\n : : :: :::|  !: sAD-nUSER pROCESSOR v1.o by fLI7e / SAD^C!^HJB !¡    |::: :: :\n      ·  ·:`--:-------------------------------------------------:!----''\n                                                                 :\n\n\n\n\n\n\n\n\n\n\n                                 .-==========-.\n                                 |  cONTENTS  |\n                                 `-==========-''\n\n                                ø  ©opyrights  ø\n                                ø iNTRODUCTION ø\n                                ø rEQUIREMENTS ø\n                                ø   fEATURES   ø\n                                ø iNSTALLATION ø\n                                ø cONTACT sAD  ø\n                                ø   hISTORY    ø\n                                ø  gREETINGS   ø\n                                ø sAD rELEASES ø\n                                ø  sAD mEMBAZ  ø\n\n\n\n\n\n\n\n\n\n\n-  - -= -===================»> (c)OPYRIGHT nOTES <«=================- =- -  -\n\n                  pERMISSION iS gRANTED tO fREELY dISTRIBUTE\n                tHIS pRODUCT fOR nON-cOMMERCIAL pURPOSES oNLY,\n                    aS lONG aS aLL fILES rEMAIN uNMODIFIED.\n\n    iT`S aLSO aLLOWED tO dISTRIBUTE tHE FULL pAKAGE tROUGH aNY NETWORK lIKE\n                              INTERNET aND AMINET!\n\n\n                            sIGNED: fLI7e / sAD 1995\n\n- -= -=================================================================- =- -\n\n\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                  iNTRODUCTION\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n  NUP  is  a great ENHANCED QUESTION door for /X!  All of you sysop know that\n  you  can  create  scriptfiles for new users to give some answers /X did not\n  want to know e.g LATEST MAJORS, WHERE HE GOT THE NUMBER FROM etc.\n\n  At  this point you as the sysop can install this door!  All answers will be\n  send to a datafile like tempans or answers file(s) in nodex drawers!\n\n  You  can also (as the sysop) VIEW these answers!  If you log in your system\n  and  a  new  user made his way to your user.data he had to use the door and\n  gave  some answers on the questions!  If there were some other users before\n  the  door recognice this and will prompt you just with the NEW answers (you\n  can review the old ones, too ..  sure)\n\n  The control is very simple, too.  You can browse through with + / - or jump\n  to the end or the beginning with < / >!  Easy and powerfull ...\n\n       Phuu ... i guess you better go on reading this doc! See you in the\n                                 install part!\n\n\n\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                  rEQUIREMENTS\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n                               /X 3.xx+, OS2.04+\n\n                           !!! REXX SERVER ACTIVE !!!\n\n\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                    fEATURES\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n\n  If  a  new  user  logged  on  you don`t have to browse ALL previously given\n      answers!  The door will jump to the beginning of the NEW entry(s)!\n\n                                  Nice outfit\n\n  Answers  on  the  user`s  REALNAME, PHONENUMBER and WHERE HE HOT THE NUMBER\n  can`t  be  overjumped!   He  MUST answer something!  (not possible with the\n                            script solution of /X!)\n\n\n\n\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                  iNSTALLATION\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n   mAKE  A  DIR  named:   "DOORS:SCEPTIC" and copy the dir "F!-nUP" to this\n                                   location.\n\n                Now copy the "NUP.info" to your BBSCMD location\n\n\n    I guess the node(x)/GUESTLOGON.txt will be a great place to start the door!\n                (right in front of the INTERNAL /X questions!)\n\n\n            This could be the contents of your GUESTLOGON.txt file\n\n   ie:  ~\n	~CC_NUP\n\n\n   This is just ment for nodes the user can log on!  The NODE0/Guestlogon.txt\n   might stay clean without adding this line .. But if you like to have it,\n   do it ...\n\n\n\n                                tHE cONFIG fILE\n                                ~~~~~~~~~~~~~~~\n\n\n  SAD-nUSERpROCESSOR.cfg\n  ~~~~~~~~~~~~~~~~~~~~~~\n  nuseraccess	= Access of NEW USERS\n  outfile	= Where to store the answers\n\n\n  ie: nuseraccess	= 10\n      outfile		= doordir"/SAD-nUSERpROCESSOR.answer"\n\n\n\n\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                   cONTACT sAD\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n                                                  __\n                                                 /\_\\n           -  - -- --- -------------