INSERT INTO door_catalog VALUES('sad_strp','SAD-STRP.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SAD-STRP.LHA','*','XIM','ESCSTRIP.exe',NULL,NULL,'SAD','\/__/   ___/___\_____ \___\_____ \_ \ __ /  \___    / _____    /       /  /  \/ -/      /   /  \       /       /  /--------.',replace(' __   _______   _______    _______   ____ _\n \/__/   ___/___\_____ \___\_____ \_ \ __\n  /  \___    / _____    /       /  /  \/\n-/      /   /  \       /       /  /--------.\n \_________/\_________/\_________/---------''\n.-=============«> pRESENTS <»=============-.\n|     LF STRIP and ESC[xxm STRIP v1.0      |\n|  Usefull for trader and pc<>amiga text   |\n|  conversion! Check`em! Start them from   |\n|  CLI to see how to use and 4 infos!!!!   |\n`-========================================-''\n','\n',char(10)),'mastrb8.txt',replace(replace('STILL GOING STRONG in 2014!\r\n\r\n                ___         ._            _______             ·\r\n   /\  _________)  \________| \___________)__   /_________:__ :________\r\n  /  \/\  __  \    ____ ___/|  \______  \_  / _/___  \_ ____/ ¦__ \___ \\r\n /   /  \ \__  \___  \  |   |   \  _/  __/ /    /\__  \  |¦   | /  \_|  \\r\n/  \/    \_ \   \ !   \_|   !    \_\    \_     /   \   \ ||   |·    /|   \_\r\n\___|     ___\  /__    /l________ /_\    /__  /_____\  / |¦   |    /_|    /\r\n    l____/-A×E\/  \___/_!       \/   \  /   \/       \/__|:   ¦__ /  l___/\r\n       ______            _____        \/      :    ____   ·   : \/\r\n    ___)     \___________)    \__________:___ ¦____)   \__________\r\n    \    _______     _______    \___    ____/ |\_____   \______   \\r\n   /\___   \/        |    _)    \/       ¦    |/    |    \    |    \\r\n _/    !    \        |    \      \_      |    |     !     \   |     \\r\n \______     \___    |_____\      /___   |    ¦            \  |      \_\r\n       \______/ \____!      \    /   \___|    :________     \_|       /\r\n                             \  /        ¦    ·       \______/|      /\r\n   YOUVE HEARD ABOUT IT!      \/         :    ·               l_____/\r\n       \r\n         MASTURBATiON STATiON AMIGA/PC/CONSOLE/ASCII-ANSI/C64        \r\n               Telnet: bbs.masturbationstationbbs.com\r\n\r\n           UPLOAD DATE: 04-26-16  TIME: 17:57:37  ON NODE: 1\r\n\r\n  UPLOADER: Black Beard            LOCATION: mSTATION.servebbs.com    \r\n\r\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',7522,4,0,NULL,NULL,'sad_strp','scan',1780048711);
