INSERT INTO door_catalog VALUES('sad_tpk1','SAD-TPK1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SAD-TPK1.LHA',NULL,'XIM','_/\__ _/\__ _/\__ ::::::.___  _/\_ _/\__',NULL,NULL,'SAD','._) __/_) __/_) __/_:::: ::)  |_\__/_) __/_. |\___     |    __)  ::::::·   _/       |   | |   (          )    ::::      |            |',replace('  _/\__ _/\__ _/\__ ::::::.___  _/\_ _/\__\n._) __/_) __/_) __/_:::: ::)  |_\__/_) __/_.\n|\___     |    __)  ::::::·   _/       |   |\n|   (          )    ::::      |            |\n¦      /X DESIGN    ::::    pRESENTS       ¦\n:             SAD TOOL PACK 1.o            :\n:                                          :\n:   CMD DEFRAG - MSGB DEFRAG - RMS CRACK   :\n: SIDDIZ - ScreenShots of latest /X-DOORS! :\n·..........................................·\n[TP] sAD /X dOORS rOq`s [::::::::::::::::::]\n','\n',char(10)),'SAD-CMDEFRAG.doc',replace('\n    .:::::::::::::::::::::::::::.\n    ::                         ::\n.-= :: SAD-COMMAND DEFRAG v1.o :: =-------[%] ©1996 fLi7e / SAD [%]-------.\n|   ::                         ::                                         |\n|   ·:::::::::::::::::::::::::::·                                         |\n|                                                                         |\n`-----------------------------------------[%] English Documentation [%]---''\n\n What is this for\n ~~~~~~~~~~~~~~~~\n CMD DEFRAG (CMD from now on) will check through all the subdirs of your\n BBS:COMMANDS dir and check ALL present .info files for their matching\n door set up in the LOCATION tooltype.\n\n If the door the command point on is not present anymore the command will\n be moved to a seperate drawer called BBS:COMMANDS/HOLDCMD for you to have\n a look on.\n\n This will always keep your command base clean and no useless commands\n which may result in ERROR MESSAGES in /X because the door has not been\n found!\n\n You may find this tool usefull as you may`ve installed lotsa doors previously\n and you removed the door as you don`t like it but you did not delete the\n command. (maybe)\n\n\n\n\n\n How to use\n ~~~~~~~~~~\n The Usage is 100% simple! Just call the tool... No options, no config! All\n SELFCONFIGURATING!\n\n\n\n\n\n Known bugs\n ~~~~~~~~~~\n As i tested this small tool for about 50 times i surely can report NO bugs\n at all. But as i`m not god, maybe you`ll find sum .. dunno ... If summit`ll\n went wrong with it ... just post me a fast email stateing the bug and i`ll\n try to fix it!\n\n\n\n\n\n Technical Properties\n ~~~~~~~~~~~~~~~~~~~~\n As CMD is a 100% arexx code you may find it slow! But lemme say that i use\n librarys to enhance some speed and the only thing beeing done is reading\n the tooltype(s) and MAYBE move the files.\n\n\n\n\n\n Requirements\n ~~~~~~~~~~~~\n Rexxtricks.library\n Rexxsupport.library\n A running /X 4.x like bbs\n\n\n\n\n\n History\n ~~~~~~~\n {v1.o} - No history .. just a fastcode!\n\n          -= FIRST PUBLIC RELEASE =-\n','\n',char(10)),NULL,NULL,113289,5,0,NULL,NULL,NULL,'scan',1780048711);
