INSERT INTO door_catalog VALUES('sad_ts2','SAD-TS2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SAD-TS2.LHA',NULL,'XIM','rexxtricks.library',NULL,NULL,'SAD','\    _/   _//  __/__)  _    /  |_\(_/   _/ \   \    \/  _\   |  _/   /   _/ \\    \ ._\   \    \_._____|  \___.    |    \    \_.',replace('______ _____ _____  _________ _  __  _____  \n\    _/   _//  __/__)  _    /  |_\(_/   _/  \n \   \    \/  _\   |  _/   /   _/ \\    \   \n._\   \    \_._____|  \___.    |    \    \_.\n|_____/\_____|-Mo!-|___|--|____|_____\_____|\n| Telnet Status / AmIRC © GraveDancer!/Sad |\n| Updated, Enhanced and Bugfixed Version 2 |\n`-[ Sceptic AmiExpress & Fame Design ''96 ]-''\n[nINO]^[HF^LSD^dCN]^[GANGSTA`S BBS]^[TELNET]\n','\n',char(10)),'Telnet.guide',replace('@database SAD-TelnetStatus.guide\n@$VER: 2.0\n@author "GraveDancer/Sad ([email removed])"\n@(c) "(sCEPTIC /X dESIGN 1996)"\n@remark cREATED uSING cED 3.5\n@node "Main" "English Doc for SAD-TelnetStatus"\n\n@{b}      .:::::::::::::::::::: .:::::::::::::::::::. ::::::::::::::::::.\n      `:::::::::..........  :::::::::: :::::::::: :::::::::: :::::::::.\n      .......... :::::::::: ::::::::::::::::::::: :::::::::: ::::::::::\n      ::::::::::.:::::::::: :::::::::: :::::::::: :::::::::: ::::::::::\n      `:::::::::::::::::::'' :::::::::: :::::::::: ::::::::::::::::::::''\n                            ::::::::::@{ub}\n                        .                            .\n                      .:::. sCEPTIC /X dESIGN 1996 .:::.\n\n                                 pRESENTS\n\n               @{b}Telnet Status for AmIRC V2.0 By GraveDancer/Sad!@{ub}\n\n @{"Coypright Notes" link "CopyRight" 0}     @{"Introductions  " link "Introducti" 0}     @{"Features       " link "Features" 0}     @{"History        " link "History" 0}\n @{"Install to /X  " link "Install" 0}     @{"SAD Members    " link "members" 0}     @{"Contact SAD    " link "contact" 0}     @{"Greetings      " link "greetin" 0}\n\n                Sceptic /X & FAME Design - Above And Beyond\n\n@endnode\n@node "Copyright" "Copyright notes"\n.-=========================================================================-.\n|.:::::::::::::::::::::::::::] @{b}Copyright Notes@{ub} [:::::::::::::::::::::::::::.|\n`-=========================================================================-''\n\n @{b}Copyright@{ub}\n This program is written and copyright © 1996 by Sebastian Bergmann. No parts\n of  this  program  may  be  altered by any means (this includes editing,\n reprogramming, crunching, resourceing etc.), except archiving.\n\n This program, means several parts of it, takes use of the following programs:\n\n amirc @{b}................@{ub} (C) [email removed]\n rexxtricks.library @{b}...@{ub} (C) [email removed]\n compressrexx @{b}.........@{ub} (C) robert hofmann\n\n @{b}Disclaimer@{ub}\n The  author  is in no way liable for any changes made to any part of the\n program,  or  consequences thereof as he is in no way liable for damages\n or loss of data directly or indirectly caused by this software.\n \n @{b}Distribution@{ub}\n Neither fees may be charged nor profits may be made by distributing this\n piece  of  software.  Only a nominal fee for costs of magnetic media may\n be  accepted,  the  amount  of  US  $5  shouldn''t be exceeded for a disk\n containing  Quick-Assign.  CD Manufactures are specifically granted the\n right to  include  this program on CD collections, as long as they are \n for the Public Domain.\n\n This software is provided @{b}as is@{ub} without warranty of any kind,\n either expressed or implied. By using this software package, you agree to\n accept the entire risk as to the quality and performance of this package.\n\n In no event (unless required by applicable law or agreed to in\n writing) will any copyright holder, or any other party who may\n redistribute this package as permitted above, be liable to you for\n damages, including any general, special, incidential or consequential\n damages arising out of the use or inability to use this package\n (including but not limited to loss of data or data being rendered\n inaccurate or losses sustained by you or third parties), even if such\n holder or other party has been advised of the possibility of such\n damages.\n\n @{b}The Author@{ub}\n Sebastian Bergmann a/k/a. GraveDancer/Sad\n ([email removed])\n Aulgasse 14\n 53721 Siegburg\n Germany\n\n                                    @{"Main Menu" link "Main" 0}\n@endnode\n@node "Introducti" "Introduction"\n.-=========================================================================-.\n|.::::::::::::::::::::::::::::] @{b}Introduction@{ub} [:::::::::::::::::::::::::::::.|\n`-=========================================================================-''\n\n If you run a bbs with telnet slots you can use this tool now to announce your\n presence on the net. No longer snapping your ip-address and  writing messages\n like this one manually: "bbs xyz on telnet at 255.255.255.255"\n\n Furthermore this tool gives information about how many telnet slots you  have\n online, are busy,how many are free and who is currently using ''em,have a look\n at this:\n\n Telnet Slot Status V2.0 (C) GraveDancer/Sad - TOWER OF SOULS at 0.0.0.0 -\n 1 slot(s) used, 2 slot(s) free - user(s) online (via telnet) are: graveDancer\n\n The output is fully configurable using @{"keywords" link "Keywords" 0}.\n\n                                    @{"Main Menu" link "Main" 0}\n@endnode\n@node "Features" "Features"\n.-=========================================================================-.\n|.::::::::::::::::::::::::::::::] @{b}Features@{ub} [:::::::::::::::::::::::::::::::.|\n`-=========================================================================-''\n\n Features\n @{b}·@{ub} Runs on AmiExpress and on FAME bbs systems\n @{b}·@{ub} Fully configurable\n\n\n Future\n @{b}·@{ub} Support for other bbs systems (SigmaExpress,DayDream,...)\n   But i need the datafiles these system create if a user is online, e.g.\n   bbs:node0.user is the name for node 0 on amiexpress.\n\n @{b}·@{ub} Support for other irc clients, e.g. Grapevine\n\n @{b}·@{ub} Everything you suggest and can be realised!\n\n                                    @{"Main Menu" link "Main" 0}\n@endnode\n\n@node "Install" "Installation to /X"\n.-=========================================================================-.\n|.::::::::::::::::::::::::::::] @{b}Installation@{ub} [:::::::::::::::::::::::::::::.|\n`-=========================================================================-''\n\n Installation\n [1] Copy the arexx script to AmIRC/Rexx\n\n [2] Add the following "alias" to your aliases list:\n telnet rexx/telnet.exe %p\n\n [3] If you have a dynamic ip-address then add this command to your startnet\n batch: SETENV IPADDRESS {IPADDRESS}\n\n Please note that this is obsolete if you are using IPDial © Jochen Wiedmann!\n\n [4] If you are using amiexpress copy the syscmd/telnetlogon.info to your syscmd,\n copy doors:/#? to your doors: and add the following line to your logon script\n for your telnet nodes:\n \n ~TELNETLOGON\n\n If Telnet.exe is NOT in Amitcp:Rexx you have to change the F!-START.info cfg,\n please refer to F!-START.doc for further information.\n\n [5] Configure it to your needs, as described in the script\n\n\n Configuration\n The configuration is done by the telnet.cfg file, explanation as follows:\n\n TELNET	        = "2 3 4"\n IPADR          = ""\n LAYOUT         = "Tower Of Souls at %IPADDRESS - %B slot(s) used, %F slot(s) free - user(s) online (via telnet) are: %ONLINE_USERS"\n\n [TELNET]       Your telnet node numbers, divided by spaces\n\n [IPADR]        Your ip address, if dynamic set to ""\n\n [LAYOUT]       This string will be send to the channel, you can use this\n                @{"keywords" link "Keywords" 0}.\n\n                                  @{"Main Menu" link "Main" 0}\n@ENDNODE\n\n@node "Contact" "Contact SAD"\n.-=========================================================================-.\n|.:::::::::::::::::::::::::::] @{b}How To Contact @{ub}[::::::::::::::::::::::::::::.|\n`-=========================================================================-''\n\n      @{b}Best way to reach me is my bbs Tower Of Souls (+49-2241-62384)@{ub}\n           OnLine From 18:00 - 08:00 (Parent''s Line, you know!)\n\n   THE PUB             [WHQ]         +49-SAD      28k8/ISDN       fLI7e\n   EVIL MOON           [EHQ]         +49-SAD      28k8            FOX\n   RAVELAND            [GHQ]         +49-SAD      28k8            h2o!\n   @{b}TOWER OF SOULS      [DST]         +49-SAD      28k8/TELNET     graveDancer@{ub}\n   GOD`s HAREM         [DST]         +49-SAD      28k8/ISDN       LANCE\n   PLANET LOVE         [DST]         +49-SAD      28k8            MEPHISTO\n   TRADERS ASSAULT     [DST]         +49-SAD      28k8/ISDN       STARLIGHT\n   PARADISE LOST       [DST]         +49-SAD      28k8/ISDN       Picard\n   BUMBLE BEE LAND     [NHQ]         +47-SAD      28k8            Baffle!\n   THE TRIP            [DKHQ]        +45-SAD      33k6            JAWLOG\n   GREYHOUND           [IHQ]         +39-SAD      28k8            Gurgle\n   HIDDEN POWER        [IDIST]       +39-SAD      28k8            X/\\D\n   SILENT SERVICE      [OZHQ]       +616-SAD      28k8            Rudolf\n   FORBIDDEN PLANET    [IRLHQ]      +353-SAD      28k8            Green Beret\n\n                      !Still searching for more worldwide!\n\nsoon our hompage in http://users.aol.com will be open for you to get the\nlatest SAD releases 1 minute after release ...\n\n\n                                  @{"Main Menu" link "Main" 0}\n@endnode\n\n@node "members" "SAD Members"\n.-=========================================================================-.\n|.:::::::::::::::::::::::::::::] @{b}SAD Members@{ub} [:::::::::::::::::::::::::::::.|\n`-=========================================================================-''\n\n@{b}Sceptic /X Design members@{ub}\n~~~~~~~~~~~~~~~~~~~~~~~~~~\n@{b}Fli7e             @{ub}Leader, Rexx Coder, Sysop(WHQ), @{b}Caustic Style Artist@{ub}\n@{b}GraveDancer       @{ub}Rexx Coder, @{b}Protest Artist@{ub}\n@{b}2fAST             @{ub}Rexx Coder, @{b}Contra Artist@{ub}\n@{b}H2o               @{ub}Sysop(GHQ), @{b}Contra@{ub} Artist@{ub}\n@{b}Wigwam            @{ub}Asm Coder\n@{b}Piwi              @{ub}C++ Coder\n@{b}Shadowmaster      @{ub}Arexx ^ Pascal Coder\n@{b}Bird              @{ub}Asm Coder\n@{b}Clyde Radcliffe   @{ub}Sysop(EHQ), Asm Coder\n@{b}Starlight         @{ub}Sysop(EDIST)\n@{b}Lance             @{ub}Sysop(GDIST), @{b}Pussy Posse Leader@{ub}\n@{b}X/\\D              @{ub}Sysop(IDIST), @{b}Nightfall Leader@{ub}\n@{b}Rudolf H.         @{ub}Sysop(OZDIST)\n@{b}Green Beret       @{ub}Sysop(IRL HQ)\n@{b}Mephisto          @{ub}Sysop(EGDIST), @{b}DG! Leader@{ub}\n@{b}Picard            @{ub}Sysop(GDIST)\n@{b}jAWLOG            @{ub}Sysop(DKHQ)\n@{b}Baffle!           @{ub}Sysop(NHQ)\n\n  18  Members  worldwide  and  NO ONE ELSE!  All who claim to be SAD are pure\n                 liers if they`re not listed in the one above!\n\n                                  @{"Main Menu" link "Main" 0}\n@endnode\n\n@node "greetin" "Greetings"\n.-=========================================================================-.\n|.:::::::::::::::::::::::::::::] @{b}-Greetings-@{ub} [:::::::::::::::::::::::::::::.|\n`-=========================================================================-''\n\n@{b}Mogue/Arclite@{ub} ..........: Thanks for the idea and the testing, Chris!\n@{b}U-Man/Arclite@{ub} ..........: Thanks for the betatesting, Anders!\n@{b}Scandic/Dcn@{ub} ............: Nice that you use this thingy, but Patrick, don''t\n                          change ever again the © notice to GraveHopper!!!\n\n                                  @{"Main Menu" link "Main" 0}\n@endnode\n\n@node "Keywords" "Keywords"\n\n@{b}%F@{ub}            = NUMBER OF FREE TELNET SLOTS\n@{b}%B@{ub}            = NUMBER OF BUSY TELNET SLOTS\n@{b}%IPADDRESS@{ub}    = YOUR IPADDRESS\n@{b}%USERS_ONLINE@{ub} = LIST OF USERS ONLINE VIA TELNET\n\n                                  @{"Main Menu" link "Main" 0}\n@endnode\n\n@node "History" "History"\n\n History\n @{b}Version 0.1@{ub} (21-Apr-96): @{b}·@{ub} First working version\n\n @{b}Version 0.2@{ub} (22-Apr-96): @{b}·@{ub} Added FAME support\n\n @{b}Version 1.0@{ub} (26-Apr-96): @{b}·@{ub} First public release\n                          @{b}·@{ub} Added who-is-online\n\n @{b}Version 1.1@{ub} (27-Apr-96): @{b}·@{ub} Optimized some code\n                          @{b}·@{ub} Checking now running bbs system and server connect\n                            and removed obsolete configuration strings\n\n @{b}Version 1.2@{ub} (02-May-96)  @{b}·@{ub} Sorry FAME sysops, messed up the busy  slot  count\n                            routine while speeding it up, now fixed!\n\n @{b}Version 1.3@{ub} (06-May-96)  @{b}·@{ub} Second public release\n                          @{b}·@{ub} Improved the layout and output a bit\n                          @{b}·@{ub} There was again a bug in the fame routines, now it\n                            should work 100% correctly\n\n @{b}Version 1.5@{ub} (08-May-96)  @{b}·@{ub} Fixed nasty bug in output:  After  the  last  user\n                            there was a ", ", too.\n\n @{b}Version 2.0@{ub} (23-May-96)  @{b}·@{ub} Third public release\n                          @{b}·@{ub} Recoded output code\n                          @{b}·@{ub} Added syscmd "Telnetlogon" for AmiExpress,\n                            now telnet status will automatically invoked if a user logs\n                            into the bbs via telnet.\n                          @{b}·@{ub} Configuration and output layout are now handled with\n                            external .cfg\n                          @{b}·@{ub} Recoded the who-is-using-telnet routine, now works for\n                            100% on amiex and fame.\n                          @{b}·@{ub} Compiled the rexx script with CompressREXX\n                          @{b}·@{ub} Replaced the plain documentation with this guide\n\n                                  @{"Main Menu" link "Main" 0}\n@endnode\n','\n',char(10)),NULL,'auto-added',65765,6,0,NULL,NULL,'sad_ts2','scan',1780048711);
