INSERT INTO door_catalog VALUES('sad_tt13','SAD-TT13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SAD-TT13.LHA','SAD-DSort','XIM','SAD-DSort',NULL,NULL,'SAD','_\  ___//\___ ___/\\___  \_ ______|_ _ /_ |  \______    Y   _____     Y   ____///   | l_____   ''    |   `    _____|   `    _____|',replace('  _______           ______          _____\n _\  ___//\___ ___/\\___  \_ ______|_ _ /_\n|  \______    Y   _____     Y   ____///   |\nl_____   ''    |   `    _____|   `    _____|\n- -- `--------`--------'' -- `--------'' --- -\n  TEAMTOP v1.3 (Known as ARTCHART!) Public\n              ©1995 fLI7e/sAD\n MonthTop for GROUPS! Unlimited Conferences\n   Nice output - Packing Month Stats LHA\n        Flexible Datafile and more\n- ---------------------------------------- -\n[iSDN][`] lEEChEd fRoM gOd''s hArEm [''][33.6]\n','\n',char(10)),'SAD-TeamTop.doc',replace('\n\n\n\n\n\n\n\n\n\n                                   .\n                                ·.:.·\n                                .:··.             .   .\n                               ::               ·..:.·\n                             .:·     .......     .·::\n                             ::   .:··     ··:.     ·:\n                             :: .:      __    ·:.    ::\n                              :::     _ °° _    :. .::\n                               ::     `-^--''    ::::·\n                               ::               ::\n                                ·:.            .:·\n                                  :::........:··\n                                .::·  ·····::.\n                              . ·:.         ::    .\n                             :::..::        ·::..::: xCz\n\n\n\n\n\n                     _ ____ __ _\n                        _ _\\_\\\  f.L.I.7.e\n     ________ _                                    _ __ ____ _\n ____\   ___///__   ________ _               o.F  ///_//_ _\n|     \____     //\_\  ____///__   ________ _                __\nl___      /             /      //\_\  ____///__   __________ \/\n   /______________                   ___/     //\_\     _   \__   ______ _\n                 /_______________                 _ ____/     //\_\  __///_____\n                                /_______________  \\\________       ______/   /\n                 ........................      /_______/   _ \__     /       /\n                 :                      :                  \\  /___     ____/\n             a.M.I.E.X.P.R.E.S.s        :                    _____\_____/_ _\n                 :                      :                __ |            ///\n                 :               d.E.S.I:G.n             \/ l___        /\n                 :......................:                   ___/    ___/\n                                                       __/\_\  ____///__ ÷f!÷\n                                                      |         /      /\n        .oO bRING yA iN tHE lATE dAYS oF 1995 Oo.     l___            /_\n                                                         /___________///\n\n\n\n                                 _ __\n                               ////_//\ _________________________ ___ __ _\n   _ __ ___ _________________________\ \\\n                                     \\ \\  aRTCHART v1.o now tEAMTOP\n     sAD-tEAM tOP v1.3p               \\ \\__________________________ ___ __ _\n _ __ ___ _____________________________\\ \ __ _\n                                         \//_////\n\n\n\n\n\n\n\n\n\n\n                                 !!! PLEASE !!!\n\n\n   SAD has released a bunch of doors the last years and I think it`s time for\n    YOU to give us some resonance on them! So if you LIKE the SAD doors then\n  contact FLI7e (Author of more than 30 doors and about 78 released versions)\n to put YOUR NAME to a list of doors and to the doors you wish to be registered\n                to (no reg. fee wanted .. just your resonance!)\n                                     Thanx!\n\n                                 !!! PLEASE !!!\n\n\n\n\n\n\n\n\n\n\n                                 .-==========-.\n                                 |  cONTENTS  |\n                                 `-==========-''\n\n                                ø  ©opyrights  ø\n                                ø iNTRODUCTION ø\n                                ø rEQUIREMENTS ø\n                                ø   fEATURES   ø\n                                ø iNSTALLATION ø\n                                ø cONTACT sAD  ø\n                                ø   hISTORY    ø\n                                ø  gREETINGS   ø\n                                ø sAD rELEASES ø\n                                ø  sAD mEMBAZ  ø\n\n\n\n\n\n\n\n\n\n\n-  - -= -===================»> (c)OPYRIGHT nOTES <«=================- =- -  -\n\n          pERMISSION iS gRANTED tO fREELY dISTRIBUTE tHIS pRODUCT fOR\n     nON-cOMMERCIAL pURPOSES oNLY, aS lONG aS aLL fILES rEMAIN uNMODIFIED.\n\n              sELLING iS sTRICTLY fORBIDDEN wITHOUT aNY eXCEPTION!\n\n     iF yOU wANT tO pUBLISH tHIS oR aNY oTHER "©sAD" lABELED pRODUCTION oN\n          a PD SERIES mEDIUM get iN cONTACT wITH tHE aUTHOR tO gET aN\n                             hANDSIGNED pERMISSION!\n\n          oFFICIAL dISTRIBUTED tHROUGH aMINET & wORLD wIDE bBS sYSTEMS\n\n          oFFICIAL sAD dISTRIBUTOR sITES: tHE pUB, eVIL mOON, rAVELAND\n\n                            sIGNED: fLI7e / sAD 1995\n\n- -= -=================================================================- =- -\n\n\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                  iNTRODUCTION\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n\n\n    Some History moments:  Artchart 1.o was (long ago) ment to be a SINGLE\n    CONF  MONTH  CHART  FOR  ASCII PURPOSES ONLY!  But it has changed to a\n    MULTI  CONFERENCE  OVERALL  MONTH  TOP ...  Well but erhm ...  ANOTHER\n    MONTH  TOP  ..  IN AREXX??  What a waste of time coding the 99th month\n    top ever?  WELL ...  It`s not a usually month top ...  It`s for GROUPS\n    instead of single users. For this reason I renamed it to tEAM tOP!\n\n                HEAR THE CROWD? They shout: WHOOOOOOOOOOOPPPPS!\n\n    Hmmm yepz ...  But anyway ...  Is this one usefull??  ..  Answer:  No!\n    But is any MONTH TOP KIND OF usefull?  Answer:  No!  So it seems to be\n    usefull!   Yes!   Hmm  ..  That`s tricky isn`t it?  Hmmm ...  No!  ...\n    You really think so?  YES!  OK ...  Your turn ...\n\n    BREAK!   I guess i ran out of information for you ..  Just read on and\n    discover the features or leave this viewer and catch an penalty!  It`s\n    YOUR decision!\n\n\n\n\n\n>By the way .. MANY MANY Thanxx to WIGWAM/SAD for coding the SAD-DSORT for me!<\n>A highly optimized 2 column sorter! This one`ll make my future  doors  damned<\n>fast!                                                                        <\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                  rEQUIREMENTS\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n\n\n\n\n\n                               /X 3.xx+, OS2.04+\n\n                           !!! REXX SERVER ACTIVE !!!\n\n\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                    fEATURES\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n\n\n\n\n\n        Can handle unlimited Conferences and unlimited group prefixes!\n\n           Kind of MONTH TOP but for groups instead of single user!\n\n           Seperate Group Statistic files in the DATAFILES DRAWERS!\n\n        Packing all datafiles in one LHA file at the end of the month!\n                       (Optional ... Must be activated!)\n\n                 Recognices if PRIVATE UPLOAD! (Skip updating!)\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                  iNSTALLATION\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n\n\n\n\n\n  mAKE  A  DIR  named:   "DOORS:SCEPTIC" and copy the dir "F!-tEAMtOP" to\n  this  location.\n\n  Now copy the "EXAMINE(x).info" to your SYSCMDdrawer and the "TEAMTOP.info"\n  to your bbscmd drawer.\n\n<<<<--- nOTIFY --->>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>\n\n\n  If You`ve installed ARTCHART copy the .dat file to the new location and\n  delete the "f!-artchart" drawer!\n\n  Also rename the ACHART.idx files in your confs to "TTOP.idx"\n\n<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<--- nOTIFY --->>>>\n\n\n\n\n\n                               To the config file\n\n\n\n\n\n\n\n\n\n\n  SAD-TeamTop.cfg\n  ~~~~~~~~~~~~~~~\n        SKIPDISPLAY	= if set to 1 the SKIPPING message will be displayed\n                          if set to 0 no output to screen if a conference is\n                          notofied where NOT TO USE tEAMTOP in.\n                          (if no indexfile is found ... )\n\n	OUTFILE		= FULL path & name to the OUTPUTFILE\n\n	MONTH		= Month to use for! When the next month will\n                          begin it`ll automatically updated!\n\n        ENTRYS		= Number of Chart Entrys\n\n        STOREMONTH	= If set to 1 the LHA file will be created, if 0 no\n                          LHA will scramble your small hd space\n\n        CLEANUPACCESS	= User access level who are allowed to CLEAN the\n                          monthly datafile BEFORE the end of the month for\n                          any reason.\n\n	ie:	SKIPDISPLAY	= 0\n		OUTFILE		= "doors:sceptic/F!-Teamtop/TeamTop.bullfile"\n		MONTH		= 12\n		ENTRYS		= 5\n		STOREMONTH	= 1\n		CLEANUPACCESS	= 250\n\n                                  ^^^->cosysop and higher at my bbs!\n\n\n\n\n  SAD-TeamTop.dat\n  ~~~~~~~~~~~~~~~\n\n1     2                        3         4      <<<< Example datline <<<<\n\nWell Well ... You can add/remove entry`s to your wishes! Just use the same\nlayout as in the original dat file supplied within this archive!\n\nStep by step:\n\n1          This is the FILE PREFIX filled up with SPACES and terminated with\n            ctrl-x.\n\n2          The FULL NAME of the group who`s prefix you used to enter.\n            Also filled with spaces and terminated with ctrl-x\n\n3          If you enter a NEW entry it must be 0 and terminated with ctrl-x.\n            Just have a look on the original! (these are the NUMBER OF\n            RELEASES this group made in the actual month!)\n\n4          If you enter a NEW entry it must be 0 and terminated with ctrl-x.\n            Just have a look on the original! (these are the BYTES OF THE\n            RELEASES this group made in the actual month!)\n\n\n\n\n\n<<<<--- nOTIFY --->>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>\n\n\n   The "CLEANUP.REXX" i used to supply with the 1.o version is now BUILD IN!\n                   Just use the C Command right after TEAMTOP!\n\n                                   "TEAMTOP C"\n\n    if your access level is the same or higher than CLEANUPACCESS is set to\n             you`ll be prompted if you want to clean up the datas!\n\n\n\n<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<--- nOTIFY --->>>>\n\n\n\n\n\n  Now load the "SAD-TeamTop.header" file and edit your personal header beeing\n                       placed right above the outputfile!\n\n            If you have decided which conferences to use for TeamTop\n   copy "TTOP.IDX" to all the conferences you like. (or rename the ACHART.idx\n                        as mentioned some lines above!)\n\n                                  THAT`S ALL!\n\n\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                   cONTACT sAD\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n\n\n\n\n\n    THE PUB             [WHQ]         +49-SAD      28k8        fLI7e\n    EVIL MOON           [EHQ]         +49-SAD      28k8        FOX\n    RAVELAND            [GHQ]         +49-SAD      28k8        h2o!\n    SILENT MOON         [OZHQ]       +616-SAD      28k8        Rudolf\n    FORBIDDEN PLANET    [IRLHQ]      +353-SAD      28k8        Green Beret\n    GREYHOUND           [IHQ]         +39-SAD      28k8        Gurgle\n    GOD`s HAREM         [DST]         +49-SAD      28k8/ISDN   LANCE\n    PLANET LOVE         [DST]         +49-SAD      28k8        MEPHISTO\n    TRADERS ASSAULT     [DST]         +49-SAD      28k8/ISDN   STARLIGHT\n\n\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                     hISTORY\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n\n\n\n\n\n                          v1.0   > fIRST pUBLIC rELEASE\n\n\n\n\n\n                          v1.1   > sECOND pUBLIC rELEASE\n                                 ø aDDED mULTI cONFERENCE uSE\n\n\n\n\n\n                          v1.2   · iNTERNAL bETA ...\n\n\n\n\n\n                          v1.3r  > tHIRD pUBLIC rELEASE (added REG STRING!)\n                                 ø rECODED mAIN rOUTINES\n                                   (gained 1483 bytes)\n                                 ø aDDED UPDATE ONLY function\n                                   by calling TEAMTOP fROM mAINLINE\n                                 ø aDDED sKIP cONF dISPLAY oN/oFF\n                                 ø rEMOVED nASTY dOUBLE oUTPUT bUG!\n                                 ø iNLCUDED "CLEANUP.REXX" tO tHE\n                                   mAINCODE ... aCCESSABLE uSING "C"\n                                   oPTION bEHIND "TEAMTOP"\n                                 ø aDDED uSER dEFINABLE eNTRY nUMBERS\n                                 ø aDDED pRIVATE uPLOAD rECOGNICING!\n                                 ø aDDED sTOREMONTH oPTION!\n                                 ø cHANGED iNTERNAL lAYOUT tO lOOK mORE\n                                   nICE aND hARMFULL.\n                                 ø fIXED NOENTRY bug! If NO known groups\n                                   were recogniced (empty datfile) then\n                                   errors came up! Bug made in late 1.1\n                                   version! Seems to be fixed now!\n\n\n\n\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                    gREETINGS\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n\n\n\n\n\n                        aLL cAUSTIC sTYLE mEMBAz wORLDWIDE\n                           aLL hAUJOBB mEMBAz wORLDWIDe\n                            tHE eSSENTIAL eSSENCE cREW\n                                mY pC mATES iN kLF\n\n       All Video Fans (over 2500 manga/Splatter etc orderable at THE PUB)\n\n mOGUE/Arclite                                                    (hijo nase!)\n Control/TRSI                                    (jaja, deine logos mach ich!)\n GrindCrusher/TRSI                                        (keep on your cd`s!)\n Mario/TRSI                                                          (wassup?)\n Capt.Crunch/TRSI                                                (was geht ..)\n Aquarius/Outlaws                                            (Still alive!???)\n Siegel/TRSI                            (Na das ARTORDER DOOR ueben wir noch!)\n BYTEANDI/TRSI                                         (Coolest FILE ID ever!)\n SVEN THE CREATOR/5D!                        (Sieht aus als ob du nachlaesst!)\n The Jailed Cougar Force                                  (keep on the drugs!)\n Treach/Contra                                     (Geiler Style mannnnnnnnn!)\n Starlight/Caustic Style                           (Welcome to uns my freund!)\n\n       And all who deserve and not mentioned ones! (what a lousy sentence!)\n\n\n\n\n\n\n\n\n\n\n                                   .\n                                ·.:.·\n                                .:··.             .   .\n                               ::               ·..:.·\n                             .:·     .......     .·::\n                             ::   .:··     ··:.     ·:\n                             :: .:      __    ·:.    ::\n                              :::     _ °° _    :. .::\n                               ::     `-^--''    ::::·\n                               ::               ::\n                                ·:.            .:·\n                                  :::........:··\n                                .::·  ·····::.\n                              . ·:.         ::    .\n                             :::..::        ·::..::: xCz\n\n\n\n\n\n\n\n\n\n\n  ................................                  ..............\n  :                              :                  :            :\n  :                              :                  :            :\n  :                              :                  :............:...........\n__:____                   ______ :    ____________._      _______:          :\n\   __/________ ______   / __  /_:___/  ___   ____|_______\_____/_  ______  :\n \______       / ____/__/_ \__/      \_ \_____\__      /           / ____/__:_\n..: \_________/  \        \___________/__:___|  |     /__________ /  \      : \_\n:            /_____________/(rLf):              |       |     -T!/__________:__/\n:                 ......         :              l_______|                   :\n:....             :    :.....    :                                  ........:\n:...:     ........:         :    :....                              :\n          :...:             :....:   :                              :\n              :                  :...:............                  :\n              :                                  :                  :\n                ........................         :        .....     :\n                :                      :         :........:   :.....:\n            a.M.I.E.X.P.R.E.S.s        :                  :...:\n                :                      :\n                :               d.E.S.I:G.n\n                :......................:\n\n\n\n\n\n          pLAN  : .. wE`LL rOOL tHE dOORsCENE fROM bEHIND tO tHE tOP!\n          rESULT: ................. wE mANAGED tO hIT tHE tOP 10 nOW!\n          fUTURE: ......................... wE`LL hIT 1ST pLACE sOON!\n\n\n\n\n\n                   ... tHE sTRONG oNEZ wILL sURF aND wIFE ...\n\n\n\n\n\n\n\n\n\n','\n',char(10)),'{"ACCESS":"User"}','auto-added',20050,8,0,NULL,NULL,'sad_tt13','scan',1780048711);
