INSERT INTO door_catalog VALUES('sad_ul10','SAD-UL10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SAD-UL10.LHA',NULL,'XIM','__   _______   _______    _______   ____ _',NULL,'fLI7e/SAD^HJB!','SAD','\/__/   ___/___\_____ \___\_____ \_ \ __ /  \___    / _____    /       /  /  \/ -/      /   /  \       /       /  /--------.',replace(' __   _______   _______    _______   ____ _\n \/__/   ___/___\_____ \___\_____ \_ \ __\n  /  \___    / _____    /       /  /  \/\n-/      /   /  \       /       /  /--------.\n \_________/\_________/\_________/---------''\n.-=============«> pRESENTS <»=============-.\n|   /X UserLister v1.0 by fLI7e/SAD^HJB!   |\n|                                          |\n|  dISPLAYS all ACTIVE users and not the   |\n|     inactives! nICE output and fast!     |\n`-========================================-''\n','\n',char(10)),'SAD-ULIST.doc',replace('\n\n\n\n\n   _________               ________            ___________          ________\n_ _\   ____(_  ________  __\  _____l_  ________\__       (_  ____ __\  _____l_\n    \____    |_\  _____l_    __|     |_\   ___   /____     |_\__/__     |     |\n __ _________|     |     |___________|      \___/  l_______|       |__________|\n           l_____________| ÷f!÷     l________|           l_________|\n\n\n\n                 a·M·I   e·X·P·R·E·S·S   d·E·S·I·G·N   1·9·9·5\n\n                                p·R·E·s·E·N·T·z\n\n\n\n     .  .:.--¡!-----------------------------------------------¡:----.\n: : :: :::|  !: SAD-User Lister v 1.o by fLI7e/SAD^HJB^NJY^C! !¡    |::: :: :\n     ·  ·:`--:------------------------------------------------:!----''\n                                                               :\n\n\n\n\n\n\n\n\n\n\n                                 .-==========-.\n                                 |  cONTENTS  |\n                                 `-==========-''\n\n                                ø  ©opyrights  ø\n                                ø iNTRODUCTION ø\n                                ø rEQUIREMENTS ø\n                                ø   fEATURES   ø\n                                ø iNSTALLATION ø\n                                ø cONTACT sAD  ø\n                                ø   hISTORY    ø\n                                ø  gREETINGS   ø\n                                ø sAD rELEASES ø\n                                ø  sAD mEMBAZ  ø\n\n\n\n\n\n\n\n\n\n\n-  - -= -===================»> (c)OPYRIGHT nOTES <«=================- =- -  -\n\n                  pERMISSION iS gRANTED tO fREELY dISTRIBUTE\n                tHIS pRODUCT fOR nON-cOMMERCIAL pURPOSES oNLY,\n                    aS lONG aS aLL fILES rEMAIN uNMODIFIED.\n\n    iT`S aLSO aLLOWED tO dISTRIBUTE tHE FULL pAKAGE tROUGH aNY NETWORK lIKE\n                              INTERNET aND AMINET!\n\n\n                            sIGNED: fLI7e / sAD 1995\n\n- -= -=================================================================- =- -\n\n\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                  iNTRODUCTION\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n  SAD-USER LIST v1.o is a small arexx made /X door which shows a nice list of\n  all ACTIVE users and the number of written mails and calls for every user &\n  a total of mails and calls to the system.\n\n  It also shows the number of NUKED(inaktive) users and features  number   of\n  lines/screen sensitivity.\n\n\n\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                  rEQUIREMENTS\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n  I  don`t  know If Mr.  J.  Hodge has changed the /X REXX PORT since /X $Ver\n  2.0!  But If he did so then you need at least /X 2.0+ to run this door!\n\n  Amiga  OS 2.04+ would also be very usefull because of the RexxMAST you need\n  to run this door!\n\n\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                    fEATURES\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n                      ø uSE sCREENHIGHT fOR oUTPUT\n                      ø yOU cAN HIT yOURSELF tHROUGH tHE lIST\n\n\n\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                  iNSTALLATION\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n  mAKE  A  DIR  named:   "DOORS:SCEPTIC" and copy the dir "F!-uSERLIST"  to\n  this location.  nOW copy the USER.info to your BBSCMD/ drawer.\n\n  Now  load  the  config  "SAD-ULIST.cfg"  file and  edit it to your needs.\n  Here`s what you can change ..  it`s not that much!\n\n\n  GCALLS		= lowest number of calls / user to mark out\n  ie: GCALLS		= 50\n\n  GMAILS		= lowest number of mails / user to mark out\n  ie: GMAILS		= 50\n\n\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                   cONTACT sAD\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n                                                  __\n                                                 /\_\\n           -  - -- --- ---------------------.----\/_/---- --- -- -  -   -\n  __________       ________                 | __________   _____________\n  \         \_____/       /_________        !_\_  ___  /__/       / ___/_____\n   \____      /  /       / ____    /       /        / /  /       /  \__     /\n     /       /          /  \______/__     /        __/  /       /     /    /\n     \______/__/       /____________/F!   \________/ \_________/\_________/\n-  -= -=-==-==/_______/==-==-=- =-  -   -   ¡\n                                            !\n                            SAD WHQ - +49-5551-65139\n                                            :\n                                  SYSOP: fLI7e\n                                            |\n                                            |     _  _ __ ______ _\n                                            |     \ \\\\ \\   __\n           _ __ __ __ _                     |      \ \\\\_\\  /___ __ _  _\n   .-----------\\//-------------------------''               \//__//_//// /\n   |            \/\n   |________   ______ ___________         _______   ______   ______   ______\n  _!\ _____/__/     /_\____/    /___    __\ _ _  \__\_    \__\_    \__\___  \\n /   _/   /  /     /      /    /   /   /    / /  /   /    /   /    /     /  /\n/        /  /     /      /        /   /    / /  /   /    /   /    /     /  /\n\_______/\_______/\_____/\_______