INSERT INTO door_catalog VALUES('sad_a2f1','SAD^A2F1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SAD^A2F1.LHA',NULL,'XIM','LE-window6.12',NULL,NULL,NULL,'___/ ___/_._/  _  \_._\____  \_    Sceptic \____     |         |     /   /_.   AmiEx /________|____|____|________//_|  De-Sign',replace('    _____    _____    _______\n___/ ___/_._/  _  \_._\____  \_    Sceptic\n\____     |         |     /   /_.   AmiEx\n /________|____|____|________//_|  De-Sign\n.                               `----------.\n.  AmiEx 2 Fame - AutoConvert Replacement  |\n|    $Ver 1.oß - ASM - ©1996 Fli7e/SAD!    |\n.                                          |\n|   !You wanna change to FAME? Get this!   |\n`------------------------------------------''\n','\n',char(10)),'SAD-A2F_PWStore.doc',replace('\n\n\n\n\n                                 Fli7e of\n\n\n\n\n        ________ _ ____________  _____________\n        \        _.)     _     \.)    _      /\n      _..\       \|      _      |     /     /  Sceptic /X Design 1996\n     /_||_________\______/______|________  /_.\n                                         \//_|·Mo!/aL·\n\n\n\n\n\n                       presents in the name of NUTT\n\n                    AmiEx 2 Fame Online Password Store\n\n\n\n\n\nWhat is this nutty tool doing?\n------------------------------\nWell,  this  is  just  the online deck for the A2F converter.  It`s made in\nAREXX  as  i made a kinda door 2 years ago for some secret data storage.  I\njust modified it and for sure there is no need of rewriting it to ASM.  (No\ntime eating routines!)\n\nThis  door will prompt and FORCE the user to enter his PASSWORD while he is\nlogging on.  This pw will be stored in a datafile to be read and handled by\nthe A2F.\n\nAll  in  all  it  is working like the AutoConvert but as i heard about some\ntrouble with it and Exon of the Los Endos bbs asked me for this door i did!\n\n\n\n\n\nWhat do I, as the sysop, have to do?\n------------------------------------\nWell,  not that much!  Copy the file SAD-A2F_PWStore.rexx to doors:sceptic/\nand the AE2FAME.info to where you store your BBSCMD`s.\n\nNow  go  to  your node(s) drawer(s) and edit the bulletin files executed at\nthe login procedure and add the ~CC_AE2FAME line to it somewhere.\n\nThe  user will NOW be prompted to enter his pw.  If he did once he`ll never\nsee the door again!\n\nAfter  some  weeks  (i  guess  a  month  is  enough!)  you  should  run the\nSAD-A2F.exe  to  get  the  up2date  FAME  data  files to switch to FAME bbs\nSystem.\n\nEOT (END OF TRICK)\n\n\n\nWhat do the USER himself need to do?\n------------------------------------\nNOTHING! only enter the PW once!\n\n\n\n\n\n    !Keep on using AMIEXPRESS - and keep on WAITING for UPDATES of A2F!\n\n\n\n\n      Fli7e ... SAD - The posse who`s doing the nuttiest doors^tools!\n\n\n\n\n','\n',char(10)),NULL,'auto-added',23393,6,0,NULL,NULL,'sad_a2f1','scan',1780048714);
INSERT INTO door_catalog VALUES('sad_ac11','SAD_AC11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SAD_AC11.LHA','SAD-DSort','XIM','SAD-DSort',NULL,NULL,'SAD',':___\  ___//\____/\\ _   /____/\\______ \_: ¡    \____   ___           ___        /   ¡ !_____________!______|______|_____________!',replace('    _______        _______      ________\n:___\  ___//\____/\\ _   /____/\\______ \_:\n¡    \____   ___           ___        /   ¡\n!_____________!______|______|_____________!\n:____ ___ __ _:                           :\n:\  //__//_///: -[ aRTcHART v1.1!       ]-:\n: \/          : -[ MAJOR UPDATE! Added  ]-:\n:             : -[ mULTIcONFERENCE uSE! ]-:\n`->/X dESIGN<-^---------------------------''\n-=[ fRESH fROM *tHE pUB* iT cAME aLONG ! ]=-\n[iSDN][°] lEEChEd fRoM gOd''s hArEm [°][33.6]\n[fOUND oN dA pROGRESS gHQ]-[dREAM pARK bBS!]\n','\n',char(10)),'SAD-ArtChart.doc',replace('\n\n\n\n\n   _________               ________            ___________          ________\n_ _\   ____(_  ________  __\  _____l_  ________\__       (_  ____ __\  _____l_\n    \____    |_\  _____l_    __|     |_\   ___   /____     |_\__/__     |     |\n __ _________|     |     |___________|      \___/  l_______|       |__________|\n           l_____________| ÷f!÷     l________|           l_________|\n\n\n\n                 a·M·I   e·X·P·R·E·S·S   d·E·S·I·G·N   1·9·9·5\n\n                                p·R·E·s·E·N·T·z\n\n\n\n      .  .:.--¡!-----------------------------------------¡:----.\n : : :: :::|  !: sAD-aRTcHART v1.1 by fLI7e / SAD^C!^HJB !¡    |::: :: :  :   :\n      ·  ·:`--:------------------------------------------:!----''\n                                                          :\n\n\n\n\n\n\n\n\n\n\n                                 .-==========-.\n                                 |  cONTENTS  |\n                                 `-==========-''\n\n                                ø  ©opyrights  ø\n                                ø iNTRODUCTION ø\n                                ø rEQUIREMENTS ø\n                                ø   fEATURES   ø\n                                ø iNSTALLATION ø\n                                ø cONTACT sAD  ø\n                                ø   hISTORY    ø\n                                ø  gREETINGS   ø\n                                ø sAD rELEASES ø\n                                ø  sAD mEMBAZ  ø\n\n\n\n\n\n\n\n\n\n\n-  - -= -===================»> (c)OPYRIGHT nOTES <«=================- =- -  -\n\n                  pERMISSION iS gRANTED tO fREELY dISTRIBUTE\n                tHIS pRODUCT fOR nON-cOMMERCIAL pURPOSES oNLY,\n                    aS lONG aS aLL fILES rEMAIN uNMODIFIED.\n\n    iT`S aLSO aLLOWED tO dISTRIBUTE tHE FULL pAKAGE tROUGH aNY NETWORK lIKE\n                              INTERNET aND AMINET!\n\n\n                            sIGNED: fLI7e / sAD 1995\n\n- -= -=================================================================- =- -\n\n\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                  iNTRODUCTION\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n                    ARTCHART is a nice ART GROUP MONTH TOP!\n\n          If you run a ASCII CONF and it`s good used then you may like\n               to support a seperate chart for ASCII GROUPS only!\n\n                    At this point ARTCHART is your solution!\n\n            ArtChart will generate and update a nice looking outfile\n            beeing good for bulletins or Bull.txt in the ASCII CONF!\n\n          The Header is 100% variable so you can have your own header!\n\n          You can also have a variable datafile where you can specify\n                    the groups prefixes and their fullnames!\n\n       All in all it`s a nice looking, fast and easy to handle MONTH TOP!\n     If you don`t wan`t to have ARTISTS ONLY well .. just change the header\n                             and add more prefixes!\n\n   The only limitation is that you can generate only ONE outfile! This means\n     that if you gonna use more than one conference the MONTH TOP will use\n   datas from all confs you copied the ACHART.idx file to but will NOT create\n    seperate outfiles! So you have eg: the ascii, the amiga and the pc conf\n      to be used for the month top but you`ll just get ONE single outfile\n                             for all them together!\n\n                  This may be a feature for further versions!\n\n     I`m also planning to release CONFIG EDITORS for all my FURTHER commin`\n       doors .. but JUST FOR REGISTERED users! Registration will NOT COST\n         any money! Just some calls to my bbs and some days of waiting!\n\n     So If you like my door(s) then consider calling the roots if it/them!\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                  rEQUIREMENTS\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n                               /X 3.xx+, OS2.04+\n\n                           !!! REXX SERVER ACTIVE !!!\n\n\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                    fEATURES\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n\n                                  Nice outfit\n\n              one Keycode can be placed to place the actual month!\n\n                            Pffft ... nuthin` more!\n\n           Seperate Group Statistic files in tjhe DATAFILES DRAWERS!\n\n         Packing all datafiles in one LHA file at the end of the month!\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                  iNSTALLATION\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n  mAKE  A  DIR  named:   "DOORS:SCEPTIC" and copy the dir "F!-ArtChart" to\n  this  location.\n\n  Now copy the "EXAMINE(x).info" to your SYSCMD/EXAMINE(x).info\n\n\n\n                             To the config file(s)\n\n\n  SAD-FIDEnhance.cfg (see examplefile)\n  ~~~~~~~~~~~~~~~~~~\n	OUTFILE		= FULL path & name to the OUTPUTFILE\n	MONTH		= Month to use for! When the next month will\n                          begin it`ll automatically updated!\n\n	IE: OUTFILE	= "doors:sceptic/F!-ArtChart/ArtChart.bullfile"\n	    MONTH	= 10\n\n\n\n\n     Also distributed with The SAD_AC11 Archive a file called CLEANUP.rexx!\n          Using this file will clean up ALL the DATAS in the DAT FILE!\n\n                Just call  RX CLEANUP.rexx  from any CLI/SHELL!\n\n\n    Load the #?.header file and you can edit it to your needs! If you insert\n             the "@@@@@" key the actual month/year will replace it!\n\n                       Just have a look on the original!\n\n        Now copy the ACHART.idx file to all conferences you like to use!\n\n\n                                  THAT`S ALL!\n\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                   cONTACT sAD\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n                                                  __\n                                                 /\_\\n           -  - -- --- ---------------------.----\/_/---- --- -- -  -   -\n  __________       ________                 | __________   _____________\n  \         \_____/       /_________        !_\_  ___  /__/       / ___/_____\n   \____      /  /       / ____    /       /        / /  /       /  \__     /\n     /       /          /  \______/__     /        __/  /       /     /    /\n     \______/__/       /____________/F!   \________/ \_________/\_________/\n-  -= -=-==-==/_______/==-==-=- =-  -   -   ¡\n                                            !\n                            SAD WHQ - +49-5551-65139\n                                            :\n                                  SYSOP: fLI7e\n                                            |\n                                            |     _  _ __ ______ _\n                                            |     \ \\\\ \\   __\n           _ __ __ __ _                     |      \ \\\\_\\  /___ __ _  _\n   .-----------\\//-------------------------''               \//__//_//// /\n   |            \/\n   |________   ______ ___________         _______   ______   ______   ______\n  _!\ _____/__/     /_\____/    /___    __\ _ _  \__\_    \__\_    \__\___  \\n /   _/   /  /     /      /    /   /   /    / /  /   /    /   /    /     /  /\n/        /  /     /      /        /   /    / /  /   /    /   /    /     /  /\n\_______/\_____