INSERT INTO door_catalog VALUES('sad_cs10','SAD^CS10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SAD^CS10.LHA','GD-CONFSTAT','XIM','GD-CONFSTAT',NULL,NULL,NULL,'_____ ___.  ____.   _____/  |_ _   ___. .__\   /   _|_/   _|___\   /    /__)_/  _|__ |  |\  \  |  /  _|  /  /  /    |    /  |   /',replace('                             __.\n   _____ ___.  ____.   _____/  |_ _   ___.\n.__\   /   _|_/   _|___\   /    /__)_/  _|__\n|  |\  \  |  /  _|  /  /  /    |    /  |   /\n|______/_____\______\ ___/\____|____\______\\n.------------------|___|---------------÷e÷-.\n| GraveDancer''s Conference Statistics V1.0 |\n|   Ultimate solution for your conference  |\n| related bulls: weektop,conftop, today-ul |\n`----[ Sceptic AmiExpress Design 1996 ]----''\n-[ 3 TELNET SLOTS FOR YOUR PLEASURE · TOS ]-\n','\n',char(10)),'GD-CONFSTAT.GUIDE',replace('@database SAD-CONFSTAT.guide\n@$VER: 1.0\n@author "graveDancer/sAD ([email removed])"\n@(c) "(sCEPTIC /X dESIGN 1995/96)"\n@remark cREATED uSING cED 3.5\n@node "Main" "English Doc for Conference Statistics)"\n\n      .:::::::::::::::::::: .:::::::::::::::::::. ::::::::::::::::::.\n      `:::::::::..........  :::::::::: :::::::::: :::::::::: :::::::::.\n      .......... :::::::::: ::::::::::::::::::::: :::::::::: ::::::::::\n      ::::::::::.:::::::::: :::::::::: :::::::::: :::::::::: ::::::::::\n      `:::::::::::::::::::'' :::::::::: :::::::::: ::::::::::::::::::::''\n                            ::::::::::\n                        .                            .\n                      .:::. sCEPTIC /X dESIGN 1996 .:::.\n\n                                  pRESENTERA\n\n          Conference Statistics Door by GraveDancer/Sceptic /X Design\n\n                                 @{"Coypright Notes" link "CopyRight" 0}\n                                 @{"Introductions  " link "Introducti" 0}\n                                 @{"Features       " link "Features" 0}\n                                 @{"Install to /X  " link "Install" 0}\n                                 @{"Registration   " link "registration" 0}\n                                 @{"SAD Members    " link "members" 0}\n                                 @{"Contact SAD    " link "contact" 0}\n\n        sAD - wE dON`t oNLY pLAY tHE gAME ... wE lEAD aND dOMINATE iT!\n\n@endnode\n@node "Copyright" "Copyright notes"\n                                @{b}Copyright Notes@{ub}\n\n          pERMISSION iS gRANTED tO fREELY dISTRIBUTE tHIS pRODUCT fOR\n     nON-cOMMERCIAL pURPOSES oNLY, aS lONG aS aLL fILES rEMAIN uNMODIFIED.\n\n              sELLING iS sTRICTLY fORBIDDEN wITHOUT aNY eXCEPTION!\n\n   Conference Statistics is a ..... ©95-96 ................. GraveDancer/sAD\n   Design for this door is a ...... ©96-xx ....................... Mogue/Al!\n   AmiExpress is a ................ ©xx-95 ......... Lightspeed Technologies\n   Cygnus Ed is a ................. ©87-93 ................. Cygnus Software\n   RexxTricks.library is a ........ ©94-95 ................ Jürgen Kohrmeyer\n   RexxSupport.library is a ....... ©xx-94 ....................... Commodore\n   Amiga is a ..................... ©xx-96 ........................ Escom AG\n\n  THERE IS NO LIABILITY TO THIS PROGRAM-PACKAGE, IN REFERENCE TO THE ASSERTED\n     LAWS. THE COPYRIGHT OWNERS, AND/OR A THIRD PARTY, PLACE THIS PROGRAM\n  PACKAGE AT YOUR DISPOSAL "AS IS" (EXCEPT WHERE THIS IS FIXED ANYWHERE ELSE\n    IN A WRITTEN WAY) WITHOUT ANY GUARANTEE IN ANY FORM (INDIRECT OR DIRECT\n    FORM). THE FULL RISK OF QUALITY AND FUNCTIONALITY OF THIS PROGRAM IS AT\n     YOUR OWN. IF THE PROGRAM HAS A BUG, YOU HAVE TO PAY ALL COSTS OF THE\n               NECESSARY SERVICE-WORKS AND REPAIRS FOR YOURSELF.\n\n  UNDER NO CIRCUMSTANCES, THE COPYRIGHT OWNERS OR A THIRD PARTY DISTRIBUTING\n  THIS PROGRAM PACKAGE, AS ALLOWED, JUST BEFORE, CAN NOT BE HELD RESPONSIBLE\n   FOR ANY DAMAGE CAUSED IN ANY USUAL, SPECIAL, OR ACCIDENTAL WAY OR BY THE\n  PROGRAM PACKAGE (SURROUNDING BUT NOT RESTRICTED ARE THE LOSS OF DATA OR NOT\n   CORRECTLY DISPLAYED DATA OR LOSSES CAUSED BY YOU OR A THIRD PARTY OR BY A\n  FAULTY WORK OF THIS PROGRAM PACKAGE WITH OTHER PROGRAMS), ALSO IF THE OWNER\n      OR A THIRD PARTY HAS BEEN POINTED AT SUCH POSSIBILITIES OF DAMAGE.\n\n                      Gravedancer / Sceptic /X Design\n\n     PS: If you want to become a DIST SITE / BETA SITE then get in Contact\n                              with me (the Author)\n\n                                    @{"Main Menu" link "Main" 0}\n@endnode\n@node "Introducti" "Introduction"\n@{b}Introduction@{ub}\n\nSceptic Conference Statistics is a multi-purpose bulletin creator\ndoor, which runs during the examine process.\n\nWell ... just have a look on the @{"FEATURES" link "Features" 0} and you`ll be amazed!\n\n                                    @{"Main Menu" link "Main" 0}\n@endnode\n@node "Features" "Features"\n@{b}Features@{ub}\n\n · Sceptic Conference Statistics runs during examination.\n · Can create conftop, weektop, uploads today seperated for each conf.\n · Excellent output design, again thanks to Mogue/Arclite.\n · Easy to configure - Tooltypes are used.\n\n                                    @{"Main Menu" link "Main" 0}\n@endnode\n\n@node "Install" "Installation to /X"\n@{b}Installation@{ub}\n\n1) Make a dir  named: "DOORS:SCEPTIC" and copy the dir "F!-FIDEnhance" to\n   this location.\n\n2) Copy the "EXAMINE<x>.info" to your SYSCMD/EXAMINE<x>.info\n\n   Make sure to update the tooltypes in F!-START.INFO if you (and you will)\n   change the name of EXAMINE<x>.info !!!\n\n3) Copy the "SENT.info" to your BBSCMD/SENT.info\n\n4) Copy the Dir "F!-START" + F!-Start.info to "doors:sceptic"\n\n   If you have already installed F!-START then copy the Tooltypes from\n   this infofile to the previously installed one!\n\n5) Configure the tooltypes...\n\n   ToolType "ALLTIME.X=<path/bulletin>"  - Write conftop bulletin for conf x\n                                           to file <path/file>.\n\n   ToolType "WEEKTOP.X=<path/bulletin>"  - Write weektop bulletin for conf x\n                                           to file <path/file>.\n\n   ToolType "NEWFILES.X=<path/bulletin>" - Write todayul bulletin for conf x\n                                           to file <path/file>.\n\n   ToolType "Eall=YES/NO"                - Enables/Disables sending of the eall\n                                           message at the end of the week.\n\n\n  In public version only the weektop bull will be created - register !!!\n\n\n                                  @{"Main Menu" link "Main" 0}\n@ENDNODE\n\n@node "Contact" "Contact SAD"\n\n                                 @{b}Contact SAD@{ub}\n\n     please call one of the listed Sceptic AmiExpress Division bbs''s below for\n any kind of suggestions/bug-reports or registration...\n\n\n           *The Pub          - Flite!          - +49-private! - WHq\n            Evil Moon        - Clyde Radcliffe - +49-private! - EHq\n            Raveland         - H2o!            - +49-private! - GHq\n            Silent Service   - Rudolf          - +61-private! - OzHq\n            Forbidden Planet - Green Beret     - +35-private! - IrlHq\n            Greyhound        - Gurgle          - +39-private! - IHq\n            God''s Harem      - Lance           - +49-private! - Dst\n            Planet Love      - Mephisto        - +49-private! - Dst\n            Traders Assault  - Starlight       - +49-private! - Dst\n          **Tower of Souls   - Gravedancer     - +49-private! - Dst\n\n                    Reach Me Also On These Fine Systems\n\n            Apocalypse Now   - Stylewars       - +49-PROTEST\n            Brain Crash      - Krypton         - +49-PRIVATE\n          **Endless Pain     - Mogue           - +49-ARCLITE\n            Fairy Land       - Data            - +49-PROTEST\n            Fast File System - Scandic         - +49-DECISION\n            Final Impact     - U-man           - +44-ARCLITE\n          **Homeless         - Slime           - +49-CONTRA\n            Masturbation S.  - Black Peard     - +1-PRIVATE\n            Rebellion in M.  - Dhm             - +47-PRIVATE\n          **Silent Moon      - Tolpan          - +49-SARDONYX\n           *Spirit Of Soul   - Mario           - +49-TRSI\n            Zillion Hours    - Traitor         - +47-PRIVATE\n            Zions Hideout    - Zion            - +1-PRESTIGE\n\n                      !Still searching for more worldwide!\n             Stars Mark Boards I Call Regulary Than The Others\n\n     You can also use [email removed] for email contact.\n\n                     Send your registration fee to...\n         Sebastian Bergmann, Aulgasse 14, 53721 Siegburg, Germany\n    (Don''t Abuse This Address - I Mean No Trading Etc - No Illegals...)\n\nSoon our hompage in http://users.aol.com will be open for you to get the\nlatest SAD releases 1 minute after release ...\n\n\n                                  @{"Main Menu" link "Main" 0}\n@endnode\n\n@node "members" "SAD Members"\n\n\n  ................................                  ..............\n  :                              :                  :            :\n  :                              :                  :            :\n  :                              :                  :............:...........\n__:____                   ______ :    ____________._      _______:          :\n\\   __/________ ______   / __  /_:___/  ___   ____|_______\\_____/_  ______  :\n \\______       / ____/__/_ \\__/      \\_ \\_____\\__      /           / ____/__:_\n..: \\_________/  \\        \\___________/__:___|  |     /__________ /  \\      : \\_\n:            /_____________/(rLf):              |       |     -T!/__________:__/\n:                 ......         :              l_______|                   :\n:....             :    :.....    :                                  ........:\n:...:     ........:         :    :....                              :\n          :...:             :....:   :                              :\n              :                  :...:............                  :\n              :                                  :                  :\n                ........................         :        .....     :\n                :                      :         :........:   :.....:\n            a.M.I.E.X.P.R.E.S.s        :                  :...:\n                :                      :\n                :               d.E.S.I:G.n\n                :......................:\n\n\n@{b}Sceptic /X Design members@{ub}\n~~~~~~~~~~~~~~~~~~~~~~~~~~\n@{b}Fli7e             @{ub}Leader, Rexx Coder, Sysop(WHQ), @{b}Caustic Style Artist@{ub}\n@{b}2fAST             @{ub}Rexx Coder, @{b}Contra Artist@{ub}\n@{b}GraveDancer       @{ub}Rexx Coder, @{b}Protest Artist@{ub}\n@{b}H2o               @{ub}Sysop(GHQ), @{b}Contra@{ub} Artist@{ub}\n@{b}Wigwam            @{ub}Asm Coder\n@{b}Bird              @{ub}Asm Coder\n@{b}Clyde Radcliffe   @{ub}Sysop(EHQ), Asm Coder\n@{b}Starlight         @{ub}Sysop(EDIST)\n@{b}Lance             @{ub}Sysop(GDIST), @{b}Pussy Posse Leader@{ub}\n@{b}X/\D               @{ub}Sysop(IDIST), @{b}Nightfall Leader@{ub}\n@{b}Rudolf H.         @{ub}Sysop(OZDIST)\n@{b}Green Beret       @{ub}Sysop(IRL HQ)\n@{b}Mephisto          @{ub}Sysop(EGDIST), @{b}DG! Leader@{ub}\n@{b}Picard            @{ub}Sysop(GDIST)\n\nNo one else! All who claim to be SAD are pure liers if they`re not listed\nin the one above!\n\n                                  @{"Main Menu" link "Main" 0}\n@endnode\n\n@node "Registration" "Registration details - taken from SAD-GDRG.TXT"\n\nREGISTERING\n~~~~~~~~~~~\nFrom  now  on  i  take  a small fee for a MULTI REGISTRATION KEYFILE which will\nregister all my doors to you (the name in the keyfile).\n\nYou`ll  get  all  my  new  doors without registering up to V1.o but bugfixed or\nenhanced  versions  are  NOT  given  to the PUBLIC anymore!  If a reg.  user is\nspreading  them,  well ...  I don`t mind ..  because the doors from v1.o+ won`t\nrun without a REAL KEYFILE!\n\nWhat  to  do  is a simple trick:  Send me DM30 / $US20 / £15 and you`ll receive\nyour own keyfile.\n\nMy address is: Sebastian Bergmann, Aulgasse 14, 53721 Siegburg, Germany !!!\n\n               Don''t abuse my address, means no illegal activities and so on,\n               i was, am and will ever be a LEGAL SCENE DUDE !!!\n\nGraveDancer\n\n\n- - -\n\nThis door is not 100% usable in public release, only the weektop bulletin\nwill be created.\n\n\n                                  @{"Main Menu" link "Main" 0}\n\n@endnode\n','\n',char(10)),NULL,'auto-added',36104,7,0,NULL,NULL,'sad_cs10','scan',1780048714);
