INSERT INTO door_catalog VALUES('sad_du10','SAD^DU10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SAD^DU10.LHA',NULL,'XIM','HAPPY_ENDiNGS.EXE',NULL,'FLI7E/SAD',NULL,'__|                                  |__\/ _) |  SCEPTIC AMIEXPRESS DESIGN 1996  | (_ |   L__________________________________|   |',replace('     __________________________________   __\n  __|                                  |__\/\n _) |  SCEPTIC AMIEXPRESS DESIGN 1996  | (_\n|   L__________________________________|   |\n|                                          |\n|   SAD-DUL V1.O .... BY FLI7E/SAD 1996!   |\n|                                          |\n| ANOTHER DAILY UPLOAD COUNTER/SHOWER WITH |\n|     NICE BULLOUT AND AVERAGLY FAST!      |\nL_                                        _|\n  )______________________________________(\n','\n',char(10)),'SAD-dul.doc',replace('\n\n\n\n\n\n\n\n\n\n                                   .\n                                ·.:.·\n                                .:··.             .   .\n                               ::               ·..:.·\n                             .:·     .......     .·::\n                             ::   .:··     ··:.     ·:\n                             :: .:      __    ·:.    ::\n                              :::     _ °° _    :. .::\n                               ::     `-^--''    ::::·\n                               ::               ::\n                                ·:.            .:·\n                                  :::........:··\n                                .::·  ·····::.\n                              . ·:.         ::    .\n                             :::..::        ·::..::: xCz\n\n\n\n\n\n                     _ ____ __ _\n                        _ _\\_\\\  f.L.I.7.e\n     ________ _                                    _ __ ____ _\n ____\   ___///__   ________ _               o.F  ///_//_ _\n|     \____     //\_\  ____///__   ________ _                __\nl___      /             /      //\_\  ____///__   __________ \/\n   /______________                   ___/     //\_\     _   \__   ______ _\n                 /_______________                 _ ____/     //\_\  __///_____\n                                /_______________  \\\________       ______/   /\n                 ........................      /_______/   _ \__     /       /\n                 :                      :                  \\  /___     ____/\n             a.M.I.E.X.P.R.E.S.s        :                    _____\_____/_ _\n                 :                      :                __ |            ///\n                 :               d.E.S.I:G.n             \/ l___        /\n                 :......................:                   ___/    ___/\n                                                       __/\_\  ____///__ ÷f!÷\n                                                      |         /      /\n        .oO bRING yA iN tHE lATE dAYS oF 1995 Oo.     l___            /_\n                                                         /___________///\n\n\n\n                                 _ __\n                               ////_//\ _________________________ ___ __ _\n   _ __ ___ _________________________\ \\\n                                     \\ \\  nO cOMMENT .. 1st vERSION\n     sAD-dAILY uPLOAD v1.o            \\ \\__________________________ ___ __ _\n _ __ ___ _____________________________\\ \ __ _\n                                         \//_////\n\n\n\n\n\n\n\n\n\n\n                                 !!! PLEASE !!!\n\n\n   SAD has released a bunch of doors the last years and I think it`s time for\n    YOU to give us some resonance on them! So if you LIKE the SAD doors then\n  contact FLI7e (Author of more than 30 doors and about 78 released versions)\n to put YOUR NAME to a list of doors and to the doors you wish to be registered\n                to (no reg. fee wanted .. just your resonance!)\n\n                                     Thanx!\n\n                                 !!! PLEASE !!!\n\n\n\n\n\n\n\n\n\n\n                                 .-==========-.\n                                 |  cONTENTS  |\n                                 `-==========-''\n\n                                ø  ©opyrights  ø\n                                ø iNTRODUCTION ø\n                                ø rEQUIREMENTS ø\n                                ø iNSTALLATION ø\n                                ø cONTACT sAD  ø\n                                ø   hISTORY    ø\n                                ø  gREETINGS   ø\n                                ø sAD rELEASES ø\n                                ø  sAD mEMBAZ  ø\n\n\n\n\n\n\n\n\n\n\n-  - -= -===================»> (c)OPYRIGHT nOTES <«=================- =- -  -\n\n          pERMISSION iS gRANTED tO fREELY dISTRIBUTE tHIS pRODUCT fOR\n     nON-cOMMERCIAL pURPOSES oNLY, aS lONG aS aLL fILES rEMAIN uNMODIFIED.\n\n              sELLING iS sTRICTLY fORBIDDEN wITHOUT aNY eXCEPTION!\n\n     iF yOU wANT tO pUBLISH tHIS oR aNY oTHER "©sAD" lABELED pRODUCTION oN\n          a PD SERIES mEDIUM get iN cONTACT wITH tHE aUTHOR tO gET aN\n                             hANDSIGNED pERMISSION!\n\n          oFFICIAL dISTRIBUTED tHROUGH aMINET & wORLD wIDE bBS sYSTEMS\n\n          oFFICIAL sAD dISTRIBUTOR sITES: tHE pUB, eVIL mOON, rAVELAND\n\n                            sIGNED: fLI7e / sAD 1995\n\n- -= -=================================================================- =- -\n\n\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                  iNTRODUCTION\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n\n\nDaily Up (DUL) is one of 1001 daily upload doors!  Erm ..  I just wanted to code\none myself (hmmm) ....\n\nNo  more  introduction needed i guess ...  Just check it and install it or don`t\ninstall it ..  it`s your turn ...\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                  rEQUIREMENTS\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n\n\n\n\n\n                               /X 3.xx+, OS2.04+\n\n                           !!! REXX SERVER ACTIVE !!!\n\n\n\n\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                  iNSTALLATION\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n\n  Make  a  dir called "doors:sceptic" and copy the "F!-DUL" dir with it`s\n  contents to it.\n\n  Now  copy  the  "commands/syscmd/examine.info"  to your syscmd and you`re\n  finished.\n\n  Now load the file  SAD-DUL.cfg and edit the following\n                     ~~~~~~~~~~~\n\n\n  datfile = "<file where DUL can work in>"\n  outfile = "<outputfile>"\n  actdate = date ...\n\n  eg: datfile = "doors:sceptic/F!-DUL/SAD-dul.dat"\n      outfile = "doors:sceptic/F!-DUL/SAD-dul.bull"\n      actdate = 19960107\n\n      If you run the door the first time just keep the day as it is! It`ll\n      be updated after you run the door the first time!\n\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                   cONTACT sAD\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n\n\n\n\n\n    THE PUB             [WHQ]         +49-SAD      28k8        fLI7e\n    EVIL MOON           [EHQ]         +49-SAD      28k8        FOX\n    RAVELAND            [GHQ]         +49-SAD      28k8        h2o!\n    SILENT MOON         [OZHQ]       +616-SAD      28k8        Rudolf\n    FORBIDDEN PLANET    [IRLHQ]      +353-SAD      28k8        Green Beret\n    GREYHOUND           [IHQ]         +39-SAD      28k8        Gurgle\n    GOD`s HAREM         [DST]         +49-SAD      28k8/ISDN   LANCE\n    PLANET LOVE         [DST]         +49-SAD      28k8        MEPHISTO\n    TRADERS ASSAULT     [DST]         +49-SAD      28k8/ISDN   STARLIGHT\n\n\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                     hISTORY\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n\n\n\n\n\n                          v1.0   > fIRST pUBLIC rELEASE\n\n\n\n\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                    gREETINGS\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                