INSERT INTO door_catalog VALUES('sad_fe40','SAD^FE40.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SAD^FE40.LHA',NULL,'XIM','exe.-l0S-eND0S-bBS-.exe',NULL,'fLI7e/sAD^cS!^hJB',NULL,'_) __/______\__  (______|__  (_ ._\___       ___        ____/    \_________. |    ¦       \          \                  |',replace('   _____      ______      ._____\n  _) __/______\__  (______|__  (_\n._\___       ___        ____/    \_________.\n|    ¦       \          \                  |\n¦                                          ¦\n: sAD-fIDE v4.o - mULTI uPLOAD fUNCTIONS   :\n:               - mANY dOORS cAN bE        :\n:               - rEPLACED wITH fIDE!      :\n.                                          .\n. 101% aREXX cODE bY fLI7e/sAD^cS!^hJB `96 .\n·..........................................·\n','\n',char(10)),'SAD-FIDEnhance.doc',replace('                     _ ____ __ _\n                        _ _\\_\\\  f.L.I.7.e\n     ________ _                                    _ __ ____ _\n ____\   ___///__   ________ _               o.F  ///_//_ _\n|     \____     //\_\  ____///__   ________ _                __\nl___      /             /      //\_\  ____///__   __________ \/\n   /______________                   ___/     //\_\     _   \__   ______ _\n                 /_______________                 _ ____/     //\_\  __///_____\n                                /_______________  \\\________       ______/   /\n                 ........................      /_______/   _ \__     /       /\n                 :                      :                  \\  /___     ____/\n             a.M.I.E.X.P.R.E.S.s        :                    _____\_____/_ _\n                 :                      :                __ |            ///\n                 :               d.E.S.I:G.n             \/ l___        /\n                 :......................:                   ___/    ___/\n                                                       __/\_\  ____///__ ÷f!÷\n                                                      |         /      /\n                                                      l___            /_\n                                                         /___________///\n\n\n\n                                 _ __\n                               ////_//\ _________________________ ___ __ _\n   _ __ ___ _________________________\ \\\n                                     \\ \\  bUGFIXED/Enhanced v3.3\n     sAD-fILE iD eHANCER v4.o         \\ \\__________________________ ___ __ _\n _ __ ___ _____________________________\\ \ __ _\n                                         \//_////\n\n\n\n\n\n\n\n\n\n\n                                 !!! PLEASE !!!\n\n\n   SAD has released a bunch of doors the last years and I think it`s time for\n    YOU to give us some resonance on them! So if you LIKE the SAD doors then\n  contact FLI7e (Author of more than 30 doors and about 78 released versions)\n to put YOUR NAME to a list of doors and to the doors you wish to be registered\n                to (no reg. fee wanted .. just your resonance!)\n                                     Thanx!\n\n                                 !!! PLEASE !!!\n\n\n\n\n\n\n\n\n\n\n                                 .-==========-.\n                                 |  cONTENTS  |\n                                 `-==========-''\n\n                                ø  ©opyrights  ø\n                                ø iNTRODUCTION ø\n                                ø rEQUIREMENTS ø\n                                ø   fEATURES   ø\n                                ø iNSTALLATION ø\n                                ø cONTACT sAD  ø\n                                ø   hISTORY    ø\n                                ø  gREETINGS   ø\n                                ø sAD rELEASES ø\n                                ø  sAD mEMBAZ  ø\n\n\n\n\n\n\n\n\n\n\n-  - -= -===================»> (c)OPYRIGHT nOTES <«=================- =- -  -\n\n          pERMISSION iS gRANTED tO fREELY dISTRIBUTE tHIS pRODUCT fOR\n     nON-cOMMERCIAL pURPOSES oNLY, aS lONG aS aLL fILES rEMAIN uNMODIFIED.\n\n              sELLING iS sTRICTLY fORBIDDEN wITHOUT aNY eXCEPTION!\n\n     iF yOU wANT tO pUBLISH tHIS oR aNY oTHER "©sAD" lABELED pRODUCTION oN\n          a PD SERIES mEDIUM get iN cONTACT wITH tHE aUTHOR tO gET aN\n                             hANDSIGNED pERMISSION!\n\n          oFFICIAL dISTRIBUTED tHROUGH aMINET & wORLD wIDE bBS sYSTEMS\n\n          oFFICIAL sAD dISTRIBUTOR sITES: tHE pUB, eVIL mOON, rAVELAND\n\n                            sIGNED: fLI7e / sAD 1996\n\n- -= -=================================================================- =- -\n\n\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                  iNTRODUCTION\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n\n\n\n\n\n                      FID is the Shortform for: File & ID\n\n                    So this doors name is: File & ID Enhance\n\n\n               So what the hell is this for? I`ll try to explain:\n\n\n                   All of you know those several doors like:\n\n                                 FREE DL MAKER\n                                   NOC COUPON\n                               FILE ID LINE ADDER\n                           ROADHOGZ ADDER BUG KILLER\n                               PC LINEFEED REMOVE\n                                   DIRSTYLER\n\n        Give them doors kick ass NOW! Cause SAD is back with a new GREAT\n                         and very powerfull MULTI DOOR!\n\n\n          It`s completely recoded and more powerfull than ever before!\n\n\n       Phuu ... i guess you better go on reading this doc! See you in the\n                                 install part!\n\n\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                  rEQUIREMENTS\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n                               /X 3.xx+, OS2.04+\n\n                           !!! REXX SERVER ACTIVE !!!\n\n                            RexxTricks Library v38+\n\n                               RexxSysLib.library\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                    fEATURES\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n\n\n\n\n\n                    Make files with special prefixes free dl\n\n                       Send EALL msg`s including file id\n\n       Unlimited different free dl infos for dirfile-add for EACH prefix\n\n           highly configurable handling (read install for this info)\n\n                   Add UPLOAD NODE and UPLOAD TIME to filedir\n\n                      STRIP PC LINEFEEDS out of TEXTFILES\n\n                         CORRECT THE ROADHOGZ adder BUG\n\n                Kinda NOC COUPON with EALL SEND option included\n\n                                SMASHING OUTFIT\n\n                    ADD A oneliner TO ZIP/LZX/LHA/TXT FILES\n                        (soon comin` GIF/MOD/MID files)\n\n    Kill FILE ID ADVERTISMENTS (like those you can add with this one, hehe)\n\n        Don`t mind the MAPUS FREE DL bug! Solved with an LOGOFF script!\n\n                      DID I LEFT SOMETHING OUT? Guess not!\n\n\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                  iNSTALLATION\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n\n\n\n\n\n  mAKE  A  DIR  named:   "DOORS:SCEPTIC" and copy the dir "F!-FIDEnhance" to\n  this  location.\n\n  Now copy the "EXAMINE(x).info" to your SYSCMD/EXAMINE(x).info\n\n\n\n\n\n\n\n\n\n\n                             To the config file(s)\n\n\n\n\n\n\n\n\n\n\n                               SAD-FIDENHANCE.cfg\n                               ~~~~~~~~~~~~~~~~~~\n\n- ADDDATA	= 1\n\n  ø SET TO 1 will ACTIVATE the NODE & Time adding\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n- USELFKILL	= 1\n\n  ø SET TO 1 will ACTIVATE the PC LINEFEED STRIPPER\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n- USERDZKILL	= 1\n\n  ø SET TO 1 will ACTIVATE the ROADHOGZ BUG CORRECTING\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n- IDADDER	= 1\n\n  ø SET TO 1 will ACTIVATE the FILE ID ADDER\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n- TXTEXTENSIONS	= "TXT NFO DOC DOK ANS ASC DIZ"\n\n  ø ADDDATA,USELFKILL & RDZKILL will affect on Files with these extensions!\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n- LHAEXTENSIONS	= "LHA LZH LHZ"\n\n  ø FILES to UNPACK using LHA\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n- ADDLINE	= "[THE]=--=] cS!-^-sAD-^-hJB-^-KLF! [=--=[PUB]"\n\n  ø FILE ID line .. max 44 chars wide! (possible esc codes excluded!)\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n- F4FCOMMAND	= "free"\n\n  ø COMMAND name of the "noc coupon" kinda door (free dl setter with\n    wilrdcards from the BBS mainline(build in the mainfile))\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n- F4FUSER	= 3\n\n  ø NUMBER of users allowed to use the MAINLINE FREE DL (fuck 4 free)\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n- FUSER		= "Fli7e"\n  FUSER		= "h2o"\n  FUSER		= "zaphod"\n\n  ø ALL USERNAMES allowed to use the FUCK FOR FREE (3 in this example)\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n- PFXNUM	= 5\n\n  ø Number of prefixes to check for FREE DOWNLOAD on ...\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n- PFX		= SAD\n  PFX		= HJB\n  PFX		= C!\n  PFX		= CS!\n  PFX		= KLF\n\n  ø ALL the prefixes matching files should be set to FREE DL ...\n    (5 in this example)\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                           FREELINES/xxx (xxx=Prefix)\n                           ~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n  Line1	  = # of following Free DL Lines\n  Line2   = Free Download Message Subject\n  Line2-x = Free DL Line\n\n  IE:\n      3\n      SAD - Free Release!\n      >>>>> iT`s fOR fREE sO lEECH iT dUDEZ! <<<<<\n      >>>>>   i wANNA sEE yOU lEECH dUDEZ!   <<<<<\n      >>>>>   iT`s fREE bECAUSE iT`s !SAD!   <<<<<\n\n\n  Every file represents one of the given FREE DOWNLOAD PREFIXES given in the\n  CONFIG FILE ... Every file can store unlimited DIFFERENT FREE DOWNLOAD\n  lines from which you can choose ONE if a FREE DOWNLOAD for THIS PREFIX has\n  been recogniced by the door ... Just put the AMOUNT of LINES in the first\n  line of the file(s) and you`re finished ...\n\n  REMEMBER: Don`t use lines longer than 44 chars! If you use ESC CODES the\n            choose menu of FIDE 3.o will scramble up the layout! So beware\n            of it! This feature will be added somewhen in the NEXT versions!\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                              SAD-FIDENHANCE.strip\n                              ~~~~~~~~~~~~~~~~~~~~\n\n  In this file all file id advertisment lines of your choice are stored! They\n                        are build up like the following:\n\n-------------------------------------------------------------------------------\n                         STARTING with an "CTRL-X" char\n\n      The line to strip itself without SPACES (GO AND STRIP > GOANDSTRIP)\n\n                          ENDING with an "CTRL-X" char\n-------------------------------------------------------------------------------\n\n                                EG: GOANDSTRIP\n\n  For further information have a closer look on the SAD-FIDENHANCE.strip file!\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                              SAD-FIDELogoff.rexx\n                              ~~~~~~~~~~~~~~~~~~~\n  Put the following line to your LOGOFF.BAT and any FREE DL DMS file WILL BE\n                                   FREE DL!\n\n           rx doors:sceptic/f!-fidenhance/sad-fidelogoff.rexx <node>\n\n            eg: rx doors:sceptic/f!-fidenhance/sad-fidelogoff.rexx 1\n\n Make sure you PUT this one to the logoff.bat because ALL free dl files beeing\n   uploaded will be set to free dl by this one! So even if you DON`T use the\n                MAPUS add this line or NO file will be FREE DL!\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                   cONTACT sAD\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n\n\n\n\n\n     THE PUB             [WHQ]         +49-SAD      28k8        fLI7e\n     EVIL MOON           [EHQ]         +49-SAD      28k8        FOX\n     RAVELAND            [GHQ]         +49-SAD      28k8        h2o!\n     SILENT MOON         [OZHQ]       +616-SAD      28k8        Rudolf\n     FORBIDDEN PLANET    [IRLHQ]      +353-SAD      28k8        Green Beret\n     GREYHOUND           [IHQ]         +39-SAD      28k8        Gurgle\n     GOD`s HAREM         [DST]         +49-SAD      28k8/ISDN   LANCE\n     PLANET LOVE         [DST]         +49-SAD      28k8        MEPHISTO\n     TRADERS ASSAULT     [DST]         +49-SAD      28k8/ISDN   STARLIGHT\n\n                      !Still searching for more worldwide!\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                     hISTORY\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n\n\n\n\n\nAug. 08th 1995 ...        v1.o - ø fIRST pUBLIC rELEASE\n                          -----------------------------------------------------\n                               ... SEVERAL INTERNAL RELEASES\n                          -----------------------------------------------------\nSep. 13th 1995 ...        v2.o - ø tOTALY nEW cODED aND\n                                 · Added my OWN TXT ID ADDER\n                                   because TXTEXTRACT is full\n                                   of BUGS!\n                          -----------------------------------------------------\n                               ... SEVERAL INTERNAL RELEASES\n                          -----------------------------------------------------\nNov. 04th 1995 ...        v3.o - ø Recoded 80%\n                                 · Fastened some routines\n                                 · Added RDZ Corrector\n                                 · Added ID Adverter\n                                 · Changed Layout\n                                 · FUCK 4 FREE is now\n                                   build in!\n                                 · Added LZX Type\n\n                                 · Ordered an ASM Version\n                                   of MY TXTADDER from\n                                   AVALON/SAD to speed up\n                                   TXT handling in the next\n                                   Version.\n                          -----------------------------------------------------\nDec. 11th 1995 ...        v3.1 - ø fIXED a mAJOR bUG iN tHE lOST cARRIER\n                                   dETECTION rOUTINE! iF a lOST cARRIER\n                                   oCCURED oR tHE uSER uSED tHE lOGOFF\n                                   aFTER uPLOAD fUNCTION bY fILE iD 2.x\n                                   bY bYTEANDI/TRSI eRROR mESSAGES cAME\n                                   uP! hOPEFULLY fIXED tHE pROBLEM!\n\n                                 ø aDDED "xxx" nOT sUPPORTET oUTPUT iF\n                                   uNKNOWN fILEEXTENSIONS aRE dETECTED.\n                          -----------------------------------------------------\nDec. 21th 1995 ...        v3.2 - ø fIXED a mAJOR bUG iN tHE EALL SEND\n                                   rOUTINE! iF a sTANDARD uSER uPLOADED\n                                   aN fREE dL fILE **NO** mESSAGE (nO tEXT)\n                                   wAS sEND! wHAT a jAMMER!\n                          -----------------------------------------------------\nDec. 24th 1995 ...        v3.3 - ø fIXED a mAJOR bUG iN tHE EALL SEND\n                                   rOUTINE! iF a SPECIAL uSER uPLOADED aN\n                                   fREE dL fILE aND sELECETD **NO**\n                                   aDDITIONAL mESSAGE tHE dOOR fUCKED! nO\n                                   TEXT in the MSG and a NOT REGISTERED\n                                   MSG LINE on screen! FIXED!\n\n                                 ø aDDED dIZWORK bY wIGWAM/sAD tO tHE fILE\n -------------------               iD pROCESSING ... nOW mY tXT eXTRACT aND\n   .h.A.P.P.y.                     aDD in AREXX iS nO lONGER nEEDED (sPEED!!)\n\n         .x.M.A.S.               ø aDDED FILE ID LINE Stripper! This one will\n   -------------------             sTRIP aDVERT lINES fROM Other bbs systems!\n\n                                 ø oPTIMIZED cODE! gAINED 1.582 bytes!\n                                   fASTENED sOME fILE oPERATIONS!\n                          -----------------------------------------------------\n                          v3.4 - · Internal betatest\n                          -----------------------------------------------------\nJan. 12th 1996 ...        v3.5 - ø Added nochoose if only one line is in the\n                                   FREE DL CONFIGFILE of a group!\n\n                                 ø Removed a nasty layout bug\n\n                                 ø Gained about 2826bytes of code in the\n                                   un-RexxOpt-imized version!\n                          -----------------------------------------------------\n                          v3.5 - · Internal beta\n                          -----------------------------------------------------\n                          v3.6 - · Internal beta\n                          -----------------------------------------------------\n                          v3.7 - · Internal beta\n                          -----------------------------------------------------\n                          v3.8 - · Internal beta\n                          -----------------------------------------------------\n                          v3.9 - · Internal beta\n                          -----------------------------------------------------\nFeb. 01th 1996 ...        v4.o - ø Now using 2 external librarys for hyperspeed\n                                   in Fileoperations!\n\n                                 ø Gained 1951 bytes of code!\n\n                                 ø Removed EALL FILE ID 7th LINE bug!\n                                   Always the 7th line was not there!\n\n                                 ø Added Keyfile routine for reg. user!\n\n                                 ø REMOVED: EALL USER! ... Now anybody can\n                                            Decide if he want`s to write an\n                                            EALL .. Guess it was the right\n                                            Descision ... But maybe not who\n                                            knows! Lemme know ...\n\n                                 ø Added REAL CURSORKEYS usage! WOW!\n \n                                 ø Added LOGOFF.BAT tool to the package to\n                                   solve the MAPUS bug! Mapus killed the\n                                   filenote and the file was not set to free\n                                   download ... This is solved by using the\n                                   2nd tool.\n\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                    gREETINGS\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n\n\n\n\n\n                        aLL cAUSTIC sTYLE mEMBAz wORLDWIDE\n                           aLL hAUJOBB mEMBAz wORLDWIDe\n                            tHE eSSENTIAL eSSENCE cREW\n                                mY pC mATES iN kLF\n\n           All Manga Anime Fans (over 300 Videos orderable at THE PUB)\n\n mOGUE/Arclite                                                    (hijo nase!)\n Control/TRSI                                    (jaja, deine logos mach ich!)\n GrindCrusher/TRSI                                        (keep on your cd`s!)\n Mario/TRSI                                                          (wassup?)\n Capt.Crunch/TRSI                                                (was geht ..)\n Aquarius/Outlaws                                            (Still alive!???)\n Siegel/TRSI                            (Na das ARTORDER DOOR ueben wir noch!)\n BYTEANDI/TRSI                                         (Coolest FILE ID ever!)\n SVEN THE CREATOR/5D!                        (Sieht aus als ob du nachlaesst!)\n The Jailed Cougar Force                                  (keep on the drugs!)\n Treach/Contra                                     (Geiler Style mannnnnnnnn!)\n Starlight/Caustic Style                           (Welcome to uns my freund!)\n\n       And all who deserve and not mentioned ones! (what a lousy sentence!)\n','\n',char(10)),NULL,'auto-added',18492,5,0,NULL,NULL,'sad_fe40','scan',1780048714);
INSERT INTO door_catalog VALUES('sad_fe45','SAD^FE45.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SAD^FE45.LHA',NULL,'XIM','SAD-FIDEnhance.exe',NULL,NULL,NULL,'__)  __/______\___   (______|___   (__ __ _ | \____         ___         ____/ |',replace('   ______      ________       _______\n __)  __/______\___   (______|___   (__ __ _\n| \____         ___         ____/\n|\n|   FILE ID ENHANCER 4.5! ©1996 FLI7E/SAD\n|\n| SUPER MEGA UPDATE! FILE ID + SENTBY ADDED!\n|_  & LOTZA MORE FEATURES AND MANY BUGFIXES\n  )____________________________________ __ _\n.OOO. (.-N¡NO!) OF [LSD^DCN^SLT^CB4!] .OOO.\n','\n',char(10)),'SAD-FIDEnhance.guide',replace('@database SAD-FIDEnhance.guide\n@$VER: 1.4\n@author "fLI7e/sAD ([email removed])"\n@(c) "(sCEPTIC /X dESIGN 1995/96)"\n@index fIDEaUTOiNDEX\n@remark cREATED uSING cED 3.5\n@node "Main" "English Doc for File Id Enhancer (FIDE)"\n\n@{b}      .:::::::::::::::::::: .:::::::::::::::::::. ::::::::::::::::::.\n      `:::::::::..........  :::::::::: :::::::::: :::::::::: :::::::::.\n      .......... :::::::::: ::::::::::::::::::::: :::::::::: ::::::::::\n      ::::::::::.:::::::::: :::::::::: :::::::::: :::::::::: ::::::::::\n      `:::::::::::::::::::'' :::::::::: :::::::::: ::::::::::::::::::::''\n                            ::::::::::@{ub}\n                        .                            .\n                      .:::. sCEPTIC /X dESIGN 1996 .:::.\n\n                                  pRESENTERA\n\n          File ID Enhancer (FIDE) v4.5 by fLI7e (sCEPTIC /X dESIGN)\n\n              ** mULTI fILE pROCESSOR fOR eXAMINE pROCEDURE **\n\n @{"Coypright Notes" link "CopyRight" 0}     @{"Introductions  " link "Introducti" 0}     @{"Features       " link "Features" 0}     @{"History        " link "History" 0}\n @{"Install to /X  " link "Install" 0}     @{"SAD Members    " link "members" 0}     @{"Contact SAD    " link "contact" 0}     @{"Greetings      " link "greetin" 0}\n\n        sAD - wE dON`t oNLY pLAY tHE gAME ... wE lEAD aND dOMINATE iT!\n\n@endnode\n@node "Copyright" "Copyright notes"\n.-=========================================================================-.\n|.:::::::::::::::::::::::::::] Copyright Notes@{ub} [:::::::::::::::::::::::::::.|\n`-=========================================================================-''\n\n   FIDE is a ...................... ©95-96 ....................... fLI7e/sAD\n   DIZWORK is a ................... ©95-96 ...................... wIGWAM/sAD\n   STRIPCR is a ................... ©95-96 ............... xAD/sAD^nIGHTFALL\n   AmiExpress is a ................ ©xx-95 ......... Lightspeed Technologies\n   Cygnus Ed is a ................. ©87-93 ................. Cygnus Software\n   RexxTricks.library is a ........ ©94-95 ................ Jürgen Kohrmeyer\n   RexxSupport.library is a ....... ©xx-94 ....................... Commodore\n   Amiga is a ..................... ©xx-96 ........................ Escom AG\n   MAGIC DIZ is a ................. ©95    ................ Icarurs/Hellfire\n   LHA is a ....................... ©91-96 ................... Stefan Bøberg\n   LZX is a ....................... ©95-96 ... Data Compression Technologies\n\n            WITH THE USAGE OF fILE iD eNHANCE vx.x yOU aGREE tHAT:\n            ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n  THERE IS NO LIABILITY TO THIS PROGRAM-PACKAGE, IN REFERENCE TO THE ASSERTED\n     LAWS. THE COPYRIGHT OWNERS, AND/OR A THIRD PARTY, PLACE THIS PROGRAM\n  PACKAGE AT YOUR DISPOSAL "AS IS" (EXCEPT WHERE THIS IS FIXED ANYWHERE ELSE\n    IN A WRITTEN WAY) WITHOUT ANY GUARANTEE IN ANY FORM (INDIRECT OR DIRECT\n    FORM). THE FULL RISK OF QUALITY AND FUNCTIONALITY OF THIS PROGRAM IS AT\n     YOUR OWN. IF THE PROGRAM HAS A BUG, YOU HAVE TO PAY ALL COSTS OF THE\n               NECESSARY SERVICE-WORKS AND REPAIRS FOR YOURSELF.\n\n  UNDER NO CIRCUMSTANCES, THE COPYRIGHT OWNERS OR A THIRD PARTY DISTRIBUTING\n  THIS PROGRAM PACKAGE, AS ALLOWED, JUST BEFORE, CAN NOT BE HELD RESPONSIBLE\n   FOR ANY DAMAGE CAUSED IN ANY USUAL, SPECIAL, OR ACCIDENTAL WAY OR BY THE\n  PROGRAM PACKAGE (SURROUNDING BUT NOT RESTRICTED ARE THE LOSS OF DATA OR NOT\n   CORRECTLY DISPLAYED DATA OR LOSSES CAUSED BY YOU OR A THIRD PARTY OR BY A\n  FAULTY WORK OF THIS PROGRAM PACKAGE WITH OTHER PROGRAMS), ALSO IF THE OWNER\n      OR A THIRD PARTY HAS BEEN POINTED AT SUCH POSSIBILITIES OF DAMAGE.\n\n                            sIGNED: fLI7e / sAD 1996\n\n     PS: If you want to become a DIST SITE / BETA SITE then get in Contact\n                              with me (the Author)\n\n                                    @{"Main Menu" link "Main" 0}\n@endnode\n@node "Introducti" "Introduction"\n.-=========================================================================-.\n|.::::::::::::::::::::::::::::] @{b}Introduction@{ub} [:::::::::::::::::::::::::::::.|\n`-=========================================================================-''\n\nFIDE is the Shortform for: File ID Enhancer. So what the hell is this for?\nI`ll try to explain: All of you know those several doors like:\n\n  FILE ID - SENTBY - FREE DOWNLOAD - NOC COUPON - FILE ID ADDER / STRIPPER\n ROADHOGZ ADDER BUG KILLER - PC LINEFEED REMOVE - DIRSTYLER - DEPROTECT ID\n\nGive them doors kick ass NOW! Cause SAD is back with a new GREAT and very\npowerfull MULTI DOOR! It`s completely recoded and more powerfull than ever\nbefore!\n\nFor example you can configure your packer (lha/lzx/zip/dms etc) using an\nexternal config file like the one from BOBO/Mystic for his Filedescription\ndoor. You can have unlimited Free Download lines for ANY prefix you want to\nset free DL ... You can add and incredible SAFELY strip advert lines from\nfile id`s and many many more things at ONE DOOR! You just need ONE EXAMINE\nfor about 8 doors ...\n\n· FULL FILE ID REPLACEMENT\n· SENTBY line REPLACEMENT\n· Free DL\n· File Id Adder/Stripper\n· Pc Linefeed Remove\n· Roadhogz Bugfix\n· Deprotect FILE ID\n· File ID CR Stripper\n\nWell ... just have a look on the @{"FEATURES" link "Features" 0} and you`ll be amazed!\n\n                                    @{"Main Menu" link "Main" 0}\n@endnode\n@node "Features" "Features"\n.-=========================================================================-.\n|.::::::::::::::::::::::::::::::] @{b}Features@{ub} [:::::::::::::::::::::::::::::::.|\n`-=========================================================================-''\n\n· Make files with special prefixes free dl (100% FREE DL! NO BUGS NO MISTAKES!\n                                           USING *REAL* UL PATH USING THE ONE\n                                           SPECIFIED IN THE conf.info file!)\n\n· Send EALL msg`s including file id\n\n· Unlimited different free dl infos for dirfile-add for EACH prefix\n\n· Highly configurable handling (read install for this info)\n\n· Add UPLOAD NODE/DATE/TIME/CPS of file to dirfile (100% Configurable!)\n\n· STRIP PC LINEFEEDS out of TEXTFILES\n\n· CORRECT THE ROADHOGZ adder BUG\n\n· Kinda NOC COUPON with EALL SEND option included\n\n· SMASHING OUTFIT\n\n· ADD A oneliner TO ZIP/LZX/LHA/TXT/GIF FILE ID`s (soon comin` MOD/MID files)\n\n· Kill FILE ID ADVERTISMENTS (like those you can add with this one, hehe)\n\n· Don`t mind the MAPUS FREE DL bug! Solved with an LOGOFF script!\n\n· Add UPLOAD NODE/DATE/TIME/CPS of file to FILE ID (100% Configurable!)\n\n· Using the GREAT Dizwork by Wigwam/SAD to ectract/Add/Delete the file id`s\n  of text related files! The known TXTEXTRACT has several hard bugs which\n  can destroy the txt files (i lost about 10megs of ascii collys using this\n  damned TXTEXTRACT and so WIGWAM did me the pleasure to code a new one (ASM)\n  for me and FIDE ... Only 4.2k, faster and more powerfull than TXTEXTRACT!\n\n· Added the FAAAAAAAAST Linefeed killer by XAD/SAD^NIGHTFALL to gain\n  unbelievable speed in LF killing!\n\n· Can deprotect the FILE ID! Some traders / Dudez ment to protect their id`s\n  from deleting .. well .. what a heck! RAMJAM released a small door which\n  did this job, and i got the idea to build it in fide ... just 2 lines and\n  not 2k like the ramjam one!\n\n· Kill senseless PC Linefeeds ($0a) in File ID.\n\n· REPLACE the FULL FILE ID and the SENTBY by Byteandi! Even more FEATURES!!!\n\nNo more words to say ... Just Have a look on the Install information and put\nit to your bbs!\n\n                                    @{"Main Menu" link "Main" 0}\n@endnode\n\n@node "Install" "Installation to /X"\n.-=========================================================================-.\n|.::::::::::::::::::::::::::::] @{b}Installation@{ub} [:::::::::::::::::::::::::::::.|\n`-=========================================================================-''\n\n1) Make a dir  named: "DOORS:SCEPTIC" and copy the dir "F!-FIDEnhance" to\n   this location.\n\n2) Copy the "EXAMINE(x).info" to your SYSCMD/EXAMINE(x).info\n\n3) Copy the "SENT.info" to your BBSCMD/SENT.info\n\n4) Copy the Dir "F!-START" + F!-Start.info to "doors:sceptic"\n\n   If you have already installed F!-START then copy the Tooltypes from\n   this infofile to the previously installed one!\n\n5) Copy the REXXTRICKS.LIBRARY (v38.4) and the REXXSUPPORT.LIBRARY\n   to your LIBS:!\n\n6) If you like you can include the text ANNOUNCE.TXT to your BBS and include\n   it to your Logon procedure! .. It just announces that a NEW sentbyline\n   must be entered! I`m working an an BYTEANDI SENTBY > SAD SENTBY converter\n   but it`s real hard because in my sentby the user only have 22 chars for\n   his Sentby!\n\n7) Join the Subdir "doors:sceptic/F!-FIDEnhance/CONFIG" and follow the\n   following discription.\n\n\n  @{b}SAD-FIDENHANCE.cfg\n  ~~~~~~~~~~~~~~~~~~@{ub}\n- # FIDE 4.4 ConfigFile ... This is the identifier line! Don`t kill/change it!\n-----------------------------------------------------------------------------\n- @{b}ADDDATA@{ub}	= 1\n  ~~~~~~~\n  SET TO 1 will ACTIVATE the NODE & Time adding\n-----------------------------------------------------------------------------\n- @{b}USELFKILL@{ub}	= 1\n  ~~~~~~~~~\n  SET TO 1 will ACTIVATE the PC LINEFEED STRIPPER\n-----------------------------------------------------------------------------\n- @{b}USERDZKILL@{ub}	= 1\n  ~~~~~~~~~~\n  SET TO 1 will ACTIVATE the ROADHOGZ BUG CORRECTING\n-----------------------------------------------------------------------------\n- @{b}IDSTRIP@{ub}	= 1\n  ~~~~~~~\n  SET TO 1 will ACTIVATE the FILE ID STRIPPER\n-----------------------------------------------------------------------------\n- @{b}ADDADVERT@{ub}	= 1\n  ~~~~~~~~~\n  SET TO 1 will ACTIVATE the FILE ID ADDER\n-----------------------------------------------------------------------------\n- @{b}PROMPTFREEDL@{ub}	= 1\n  ~~~~~~~~~~~~\n  SET TO 1 will ACTIVATE the "WANNA SET FILE FREE" at free dl recognicing!\n-----------------------------------------------------------------------------\n- @{b}ADDULCPS@{ub}	= 1\n  ~~~~~~~~\n  SET TO 1 will Place the UL CPS under the file entry in dirfile.\n-----------------------------------------------------------------------------\n- @{b}TXTEXTENSIONS@{ub}	= "TXT NFO DOC DOK ANS ASC DIZ"\n  ~~~~~~~~~~~~~\n  USELFKILL & RDZKILL will affect on Files with these extensions!\n-----------------------------------------------------------------------------\n- @{b}LHAEXTENSIONS@{ub}	= "LHA LZH LHZ"\n  ~~~~~~~~~~~~~\n  FILES to UNPACK using LHA\n-----------------------------------------------------------------------------\n- @{b}GFXEXTENSIONS@{ub}	= "GIG JPG IFF"\n  ~~~~~~~~~~~~~\n  FILES to HANDLE WITH MAGICDIZ\n-----------------------------------------------------------------------------\n- @{b}ADDLINE@{ub}	= "[THE]=--=] cS!-^-sAD-^-hJB-^-KLF! [=--=[PUB]"\n  ~~~~~~~\n  FILE ID line .. max 44 chars wide! (possible esc codes excluded!)\n                    You can INSERT time/date/node to this line by using\n                    these codes:\n\n                    ##:##:## for the TIMe (HH:MM:SS)\n                    @CPS@    for the Upload CPS\n                    @#:@#    for the TIMe (HH:MM)\n                    @@/@@/@@ for the DATe\n                    #@       for the NODe\n-----------------------------------------------------------------------------\n- @{b}WORKDIR@{ub}	= "RAM:T/"\n  ~~~~~~~\n  FULL PATH of Dir to work in (extracting/adding/stripping etc!)\n-----------------------------------------------------------------------------\n- @{b}SHOWDIZ@{ub}		= 1\n  ~~~~~~~\n  If set to 1 the file id will be displayed and all STRIP actions will be\n  marked during the file procedure! IF set to 0 no file id and no strip view\n  are displayed!\n-----------------------------------------------------------------------------\n- @{b}KILLCRINID@{ub}		= 1\n  ~~~~~~~~~~\n  If set to 1 the file id will be cleaned from PC Linefeeds! This only works\n  of IDSTRIP is set to 1, too!\n-----------------------------------------------------------------------------\n- @{b}DEPROID@{ub}		= 1\n  ~~~~~~~\n  If set to 1 the file id will be Deprotected from Deleting! Some Id don`t\n  have the D flag set and the /X can`t delete it after adding to dirfile and\n  all the uploads will have the same id ... suxx! Fixed by setting this\n  to 1!\n-----------------------------------------------------------------------------\n- @{b}RANDOMADD@{ub}		= 1\n  ~~~~~~~~~\n  If set to 1 one of the adds in the #?.ADD file will be taken in random\n  order! You can have unlimited different adds in this file! this will give\n  your adds a betterlook instead of using always the same add-line!\n\n  IF RANDOMADDS is set to 0 the ADDLINE from this configfile will be used!\n-----------------------------------------------------------------------------\n- @{b}F4FCOMMAND@{ub}	= "free"\n  ~~~~~~~~~~\n  COMMAND name of the "noc coupon" kinda door (free dl setter with\n  wilrdcards from the BBS mainline(build in the mainfile))\n-----------------------------------------------------------------------------\n- @{b}F4FUSER@{ub}	= 3\n  ~~~~~~~\n  NUMBER of users allowed to use the MAINLINE FREE DL (fuck 4 free)\n-----------------------------------------------------------------------------\n- @{b}F4ACCESS@{ub}	= 200\n  ~~~~~~~~\n  Default Access Level for Override the NAME CHECK! If a user is NOT in the\n  F4F Userlist but has an access level = > F4ACCESS then he`ll also get\n  access to FUCK 4 FREE.\n-----------------------------------------------------------------------------\n- @{b}FUSER@{ub}		= "Fli7e"\n  @{b}FUSER@{ub}		= "h2o"\n  @{b}FUSER@{ub}		= "zaphod"\n\n  ALL USERNAMES allowed to use the FUCK FOR FREE (3 in this example)\n-----------------------------------------------------------------------------\n- @{b}PFXNUM@{ub}	= 5\n  ~~~~~~\n  Number of prefixes to check for FREE DOWNLOAD on ...\n-----------------------------------------------------------------------------\n- @{b}PFX@{ub}		= "SAD"\n  @{b}PFX@{ub}		= "HJB"\n  @{b}PFX@{ub}		= "C!"\n  @{b}PFX@{ub}		= "CS!"\n  @{b}PFX@{ub}		= "KLF"\n\n  ALL the prefixes matching files should be set to FREE DL ...\n  (5 in this example)\n\n  ATTENTION: You *MUST* put the prefixes in "" from this version on because\n             arexx bugs if you place chars like "^&?·" etc in the prefixes\n             without "" ... not my fault! (I guess!)\n-----------------------------------------------------------------------------\n\nIf you are confused ... well, have a look on MY configfile i delivered with\nthis pack!\n\n  @{b}FREELINES/xxx (xxx=Prefix)\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~@{ub}\n\n  Line1	  = # of following Free DL Lines\n  Line2   = Free Download Message Subject\n  Line2-x = Free DL Line\n\n  IE:\n      3\n      SAD - Free Release!\n      >>>>> iT`s fOR fREE sO lEECH iT dUDEZ! <<<<<\n      >>>>>   i wANNA sEE yOU lEECH dUDEZ!   <<<<<\n      >>>>>   iT`s fREE bECAUSE iT`s !SAD!   <<<<<\n\n\nEvery file represents one of the given FREE DOWNLOAD PREFIXES given in the\nCONFIG FILE ... Every file can store unlimited DIFFERENT FREE DOWNLOAD lines\nfrom which you can choose ONE if a FREE DOWNLOAD for THIS PREFIX has been\nrecogniced by the door ... Just put the AMOUNT of LINES in the first line of\nthe file(s) and you`re finished ...\n\n  REMEMBER: Don`t use lines longer than 44 chars! (Esc Codes EXCLUDED)!\n\n\n  @{b}SAD-FIDENHANCE.strip\n  ~~~~~~~~~~~~~~~~~~~~@{ub}\n\nIn this file all file id advertisment lines of your choice are stored! They\nare build up like the following:\n\n-----------------------------------------------------------------------------\n              STARTING with an "CTRL-X" char (marked here as `X`)\n\n                                    Line\n\n                        ENDING with an "CTRL-X" char\n-----------------------------------------------------------------------------\n\n                              EG: `X`GOANDSTRIP`X`\n\nJust add the lines you want to be stripped in the future! If you want to gain\nspace by shorten the stripfile just run @{b}SAD-FIDEStrip.exe@{ub}\n\nand anything work fine! sMARTsTRIP removes all chars! Only letters from A-Z\nand a-z are left! This will make the stripping much more efficinet because\nthe most of the adverts include time/node/cps or whatever! Just check the\ngiven stripfile with now more than 130 lines in!\n\n\n  @{b}SAD-FIDELogoff.exe\n  ~~~~~~~~~~~~~~~~~~@{ub}\n\n     Put the following line to your LOGOFF.BAT and any FREE DL DMS file\n                              WILL BE FREE DL!\n\n           doors:sceptic/f!-fidenhance/sad-fidelogoff.exe <node>\n\n            eg: doors:sceptic/f!-fidenhance/sad-fidelogoff.exe 1\n\n Make sure you PUT this one to the logoff.bat because ALL free dl files beeing\n   uploaded will be set to free dl by this one! So even if you DON`T use the\n                MAPUS add this line or NO file will be FREE DL!\n\n Also put an "DELETE ram:t/AL<node>" to your logoff.bat because at the moment\n i haven`t found a better way to check if the Uploader used ALL command! So i\n create a DUMMYFILE but this has to be deleted somewhen! So just delete it in\n                your logoff.bat and anything should work fine!\n\n PS: Where <node> is the nodenumber (eg. for node1: DELETE ram:t/AL1"\n\n\n  @{b}SAD-FIDEnhance.arc\n  ~~~~~~~~~~~~~~~~~~@{ub}\nHere you can configure the Extract / Add command lines for the lha/dms/exe\nand related files! ... The usage is the same as in FILEDESCRIPTION by\nBOBO/MST ... So if you`ve his file id door you can take the lines from his\ncfg file!\n\n          *--------------------------------------------------------*\n          *    Keys for the command line are the same as bobos     *\n          *                                                        *\n          *  %P ... Full Path and Name for SOURCEFILE (INPUTFILE)  *\n          *  %W ... Work directory (CONFIGURABLE IN CONFIGFILE!)   *\n          *--------------------------------------------------------*\n\nDMS_ADD	= "DMSDescript a %W"\nDMS_EXT = "DMSDescript x %WFILE_ID.DIZ %P"\nEXE_ADD	= "EXEDescript a %W"\nEXE_EXT = "EXEDescript x %WFILE_ID.DIZ %P"\n\n...\n\nand so on ...\n\nWARNING: In this version of FIDE only the known files are supportet!\n         So you can`t add other prefix recognicing to this config!\n\n                                  @{"Main Menu" link "Main" 0}\n@ENDNODE\n\n@node "History" "History"\n@{b}History@{ub}\n\n  Thanx to all my BETATESTERS for supporting me with suggestions, bug reports\n                               and moral pushing!\n\n          See the file FIDE.HISTORY for detailed history and changes!\n\n                                  @{"Main Menu" link "Main" 0}\n@endnode\n\n@node "Contact" "Contact SAD"\n.-=========================================================================-.\n|.:::::::::::::::::::::::::::] @{b}How To Contact@{ub} [::::::::::::::::::::::::::::.|\n`-=========================================================================-''\n\n   THE PUB             [WHQ]         +49-SAD      28k8(ISDN SOON) fLI7e\n   EVIL MOON           [EHQ]         +49-SAD      28k8            FOX\n   RAVELAND            [GHQ]         +49-SAD      28k8            h2o!\n   GOD`s HAREM         [DST]         +49-SAD      28k8/ISDN       LANCE\n   PLANET LOVE         [DST]         +49-SAD      28k8            MEPHISTO\n   TRADERS ASSAULT     [DST]         +49-SAD      28k8/ISDN       STARLIGHT\n   BUMBLE BEE LAND     [NHQ]         +47-SAD      28k8            Baffle!\n   THE TRIP            [DKHQ]        +45-SAD      33k6            JAWLOG\n   GREYHOUND           [IHQ]         +39-SAD      28k8            Gurgle\n   HIDDEN POWER        [IDIST]       +39-SAD      28k8            X/\\D\n   SILENT MOON         [OZHQ]       +616-SAD      28k8            Rudolf\n   FORBIDDEN PLANET    [IRLHQ]      +353-SAD      28k8            Green Beret\n\n                      !Still searching for more worldwide!\n\nYou can also use [email removed] for inet contact, [email removed] for\nnormal email contact.\n\nSoon our hompage in http://users.aol.com will be open for you to get the\nlatest SAD releases 1 minute after release ...\n\n\n                                  @{"Main Menu" link "Main" 0}\n@endnode\n\n@node "members" "SAD Members"\n.-=========================================================================-.\n|.:::::::::::::::::::::::::::::] @{b}SAD Members@{ub} [:::::::::::::::::::::::::::::.|\n`-=========================================================================-''\n\n@{b}Sceptic /X Design members@{ub}\n~~~~~~~~~~~~~~~~~~~~~~~~~~\n@{b}Fli7e             @{ub}Leader, Rexx Coder, Sysop(WHQ), @{b}Caustic Style Artist@{ub}\n@{b}2fAST             @{ub}Rexx Coder, @{b}Contra Artist@{ub}\n@{b}GraveDancer       @{ub}Rexx Coder, @{b}Protest Artist@{ub}\n@{b}H2o               @{ub}Sysop(GHQ), @{b}Contra@{ub} Artist@{ub}\n@{b}Wigwam            @{ub}Asm Coder\n@{b}Piwi              @{ub}C++ Coder\n@{b}Shadowmaster      @{ub}Arexx ^ Pascal Coder\n@{b}Bird              @{ub}Asm Coder\n@{b}Clyde Radcliffe   @{ub}Sysop(EHQ), Asm Coder\n@{b}Starlight         @{ub}Sysop(EDIST)\n@{b}Lance             @{ub}Sysop(GDIST), @{b}Pussy Posse Leader@{ub}\n@{b}X/\\D              @{ub}Sysop(IDIST), @{b}Nightfall Leader@{ub}\n@{b}Rudolf H.         @{ub}Sysop(OZDIST)\n@{b}Green Beret       @{ub}Sysop(IRL HQ)\n@{b}Mephisto          @{ub}Sysop(EGDIST), @{b}DG! Leader@{ub}\n@{b}Picard            @{ub}Sysop(GDIST)\n@{b}jAWLOG            @{ub}Sysop(DKHQ)\n@{b}Baffle!           @{ub}Sysop(NHQ)\n\n  18  Members  worldwide  and  NO ONE ELSE!  All who claim to be SAD are pure\n                 liers if they`re not listed in the one above!\n\n                                  @{"Main Menu" link "Main" 0}\n@endnode\n\n@node "greetin" "Greetings"\n.-=========================================================================-.\n|.:::::::::::::::::::::::::::::] @{b}-Greetings-@{ub} [:::::::::::::::::::::::::::::.|\n`-=========================================================================-''\n\n@{b}DR. G/Ram Jam@{ub} ..........: Hey mate ... You asked me to give you some hellos\n                          in my next production(s)! Here we are! hehe, hope\n                          you are fine and will manage your inet/email soon\n                          as possible to have some mailing again! Always\n                          nice mails with you!\n\n@{b}Aquarius/Outlaws@{ub} .......: How are things going!? Long time no new releases\n                          from your factory of nice doors! Have you thought\n                          about joining SAD yet? Outlaws seems to be dead in\n                          /X Business!\n\n@{b}XAD/Nightfall^SAD@{ub} ......: Shit happens to your possibility of calling! Hope\n                          you`ll manage to fix this problem SOON! I miss\n                          ya chats and WORLDS BEST BETA JOB!\n\n@{b}Sven TC/5 Dynasty@{ub} ......: Hmmm ... also von dir is ja nun auch nich grad zu\n                          sagen das du HYPERAKTIV bist! Was macht die Kunst\n                          und warum is dein ZIPPY so saulangsam!?\n\n@{b}Siegel/TRSI@{ub} ............: Ja, also euer FAME is ja wohl nich ganz scheisse\n                          aber ne Antwort auf meine Fragen haette ich schon\n                          ganz gerne gehabt .. Naja .. ein AIM Developer\n                          weniger!\n\n@{b}Webster/SAD ^ More@{ub} .....: Welcome in mate and have a nice time. Nice emails\n                          with you, too!\n\n@{b}Mogue/Arclite@{ub} ..........: Yops ... Hab deinen account klargemacht! Musst\n                          nur noch callen und dann geht das schon klar mit\n                          uns!\n\n@{b}Gravedancer/Sad@{ub} ........: F!+GD PowerDuo never die! Hahah! ... Lass uns mal\n                          so`n fettes megadoor zusammen machen! Also so`n\n                          richtig fettes, nich so`n kleines wie FIDE (pfeif!)\n                          wo ich nur knappe 300 stunden gebraucht hab! hehe!\n\n@{b}Mario/TRSI@{ub} .............: Ein call und Tschuess oder was? Bist uebrigens\n                          VALIDATED! Nur so als Info!\n\n@{b}Control/TRSI@{ub} ...........: Jo Chef! TRSI RECORDZ ROQ`s ... Aber wo bleibt der\n                          call den du mir auf P5 zugesagt hast! Auch wegen\n                          euren Raytracten logo kram!\n\n@{b}IXXY/TRSI@{ub} ..............: Steht Muenchen noch?\n\n@{b}Sonny/LSD@{ub} ..............: Nice having you as BETA TESTER for the UK! Keep\n                          on working! PS: Haven`t received your Reg fee yet!\n\n@{b}2fAST/Viele Gruppen@{ub} ....: Mach so weiter und du bist ein ESAD! EX. sAD!\n                          Erst helf ich dir und dann machst du`n dicken!\n                                                   .·: KANN NICH SEIN!!! :·.\n@{b}bAFFLE!/sAD ^ More@{ub} .....: Nice to have Your BBL as NHQ!.\n\n                                  @{"Main Menu" link "Main" 0}\n@endnode\n','\n',char(10)),NULL,'auto-added',63689,7,0,NULL,NULL,'sad_fe45','scan',1780048714);
INSERT INTO door_catalog VALUES('sad_fi20','SAD^FI20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SAD^FI20.LHA','dmsdescript','XIM','EXEDescript',NULL,NULL,NULL,'_)                                      (_ |    sCEPTIC /X DESIGN presents in 1996    | |                                          |',replace('  ________________________________________\n _)                                      (_\n|    sCEPTIC /X DESIGN presents in 1996    |\n|                                          |\n|      FILC: File ID List Creator 2.o      |\n|                                          |\n| The Multi Dirfile /X Style list creator! |\n|                                          |\nl_  Supporting: 17 Filetypes/extensions   _|\n  )______________________________________(\n[THE]=--=] cS!-^-sAD-^-hJB-^-KLF! [=--=[PUB]\n','\n',char(10)),'filc20.doc',replace('   ______ _   ______ _   _______ _          _ ____      _ ______  ______ _\n  _\  __///___\  __///___\ ___ ///__________\\\  _|_____\\\_____|_\  __///__\n |  \____        ''         \__/       ____     ______/               ''      |\n l_________________________________   \_____________________________________|\n                                  l_____|\n\n                                Presents in 1996\n\n\n\n                           File Id List Creator v2.0\n\n\n\n                      "The Multi Conference List Creator"\n\n                Idea, concept, Coding and developing: fLI7e/sAD\n                        Some Ideas: Nightprowler/Hoodlum\n                       Beta testing: Nightprowler/Hoodlum\n\n\n\n\n-  - -= -===================»> (c)OPYRIGHT nOTES <«=================- =- -  -\n\n          pERMISSION iS gRANTED tO fREELY dISTRIBUTE tHIS pRODUCT fOR\n     nON-cOMMERCIAL pURPOSES oNLY, aS lONG aS aLL fILES rEMAIN uNMODIFIED.\n\n              sELLING iS sTRICTLY fORBIDDEN wITHOUT aNY eXCEPTION!\n\n     iF yOU wANT tO pUBLISH tHIS oR aNY oTHER "©sAD" lABELED pRODUCTION oN\n          a PD SERIES mEDIUM get iN cONTACT wITH tHE aUTHOR tO gET aN\n                             hANDSIGNED pERMISSION!\n\n                            sIGNED: fLI7e / sAD 1996\n\n\n\n\n\n                      To Contact the Author write/call to:\n\n                            [email removed]\n                                  [email removed]\n                           the pub: +49(0)5551-911080\n\n- -= -=================================================================- =- -\n\n\n\n\n\n\n\n\n\n\nInstall\n-------\nMake  sure  REXXMAST  is  active!   Copy the file FILC20.exe to any location you\nlike.   Copy  the  FILC.CFG  to  your  "SYS:S"  and  edit  it to your needs like\ndescripted in "HOW TO CONFIGURE".\n\nNow copy (if you don`t have them already) the files: DMSDESCRIPT\n                                                     EXEDESCRIPT\n                                                     GIFDESC\n                                                     SAD-DIZWORK.exe\n\nto your "SYS:C" drawer. To get FILC running 100% you need the files: LZX\n                                                                     LHA\n                                                                     UNZIP\n\nin  your  "SYS:C" drawer, too!  But as they are copyrighted (and i don`t want to\ndistribute the evaluation versions ...  OLD!) you need to get them your own!\n\n\n\n\n\n\n\n\n\n\nWhat is FILC\n------------\n\nFilc  is  a  small  arexx  (compiled&Crypted)  tool  that  can  scan unlimited\ndirectories  for  files and extract the file id`s of all supportet formats and\ncreate  a  list  in  a  slightly  different  style  than "©AMI EXPRESS by John\nHodge/Lightspeed Technologies".\n\nThe Supportet formats in version 2.0 are: TXT/NFO/ANS/ASC/DOC/DOK/INF/LHA/LZH\n                                          LHZ/LZA/LZX/DMS/EXE/ZIP/GIF/MOD\n\nThe  files  of  each  directory  will  be a-z sorted before the list is beeing\ncreated,  because i hate lists where disk 1/5 is at the bottom and disk 5/5 is\nin  the middle of the list!  Is not very comfortable and looks not that good i\nthink so i grabbed "©Shellsort V1.14 Made by ONE MAN GANG" to do the trick!\n\n\n\n\n\n\n\n\n\n\nHow to configure\n----------------\nCreate  a file named "FILC.cfg" and move it to your "sys:s" drawer.  This file\nwill store all your dorectories you like to have in the list and their names!\n\nExample: Line1: confs:amiga/upload     <<< Full path to dir\n         Line2: aMIGA wAREZ            <<< Name of the dircontents\n\nI  guess  most  of  the  people  who  will use this tool (if someone will) are\nsysops!  They`ll know what I mean.\n\nYou can have as many confs/dirs as you like. Mine looks like this at the moment\nand it`s running perfectly.\n\n                confs:demos-a/upload\n                aMIGA dEMOS\n                confs1:peecee/upload\n                pEcEE\n                confs1:demos-p/upload\n                pEcEE dEMOS\n\nFILC is CLI commandline based! The correct input is:\n\nFILC20.exe <listfile> \n\nWhere <listfile> is the OUTPUTFILE of all the file id`s!\n\nEG: filc20.exe ram:liste.txt\n\n\n\n\n\n\n\n\n\n\nExample Listoutput\n------------------\n===============================================================================\n-=> aMIGA dEMOS <==============================================================\n===============================================================================\n\n$CP-AGAT.LHA  255635  19-Nov-95   ____ _________________________________ _\n                                 :····/ ___/ ___/ ___/  _ /__  /__/ ___/\·:\n                                 ¡···/__  /    / ___/ ___/\/  /  /    /\/·¡\n                                 !··/____/____/____/__/\_\/__/__/____/ /··!\n                                 `--\____\____\____\__\/__\__\__\____\/---''\n                                 ·----------------------------------------·\n                                 :               IS BACK WITH             :\n                                 ¡                                        ¡\n                                 |          AGATHA - THE AGA DEMOS        |\n                                 !------------------------------------ -F!!\n                                 `----------------------------------------''\n                                 .· ThePub ·.oO wHERE THE fILES gO tHROUGH Oo\n-------------------------------------------------------------------------------\n3AD-ST13.LHA  190056  19-Nov-95  ############################################\n                                 #==========================================#\n                                 #     SVERIGETOPPEN #13 - MAY''95 ISSUE     #\n                                 #==========================================#\n                                 # SVERIGETOPPEN - THE SWEDISH TRADERCHART! #\n                                 #                                          #\n                                 # FEEL FREE TO SEND US MUSIC/GFX/ARTICLES  #\n                                 #                                          #\n                                 #    PRODUCED BY - TRIAD & TBL & REBELS    #\n                                 #                                          #\n                                 ############################################\n                                 .· ThePub ·.oO wHERE THE fILES gO tHROUGH Oo\n-------------------------------------------------------------------------------\nABS-PCHD.LHA 1664289  19-Nov-95      _ _________________  __________________\n                                   A/ \     \  __)   \  ||  |  |_  __)___|  |\n                                  D/   \ |  /__  \ |  \ ||  |  ||  |  __||  |\n                                 T/  |  \|  \ /  / |  / |/\ |  ||  |  |  |__|\n                                 /___|___\__/___/____/_____\___||__|_____(__)\n                                 ------------[ A·B·S·O·L·U·T·E·! ]-----------\n                                 - Special Party-Edition of Cult - Hd version\n                                       VIRTUAL ENERGY - AVT/DCN/DG GHQ\n                                 .· ThePub ·.oO wHERE THE fILES gO tHROUGH Oo\n-------------------------------------------------------------------------------\nAINTRO.LHA     28339  19-Nov-95  Short:    Ansi Intro by JTS/FRX.\n                                 Author:   Jotes/FRX\n                                 Uploader: [email removed] (Jon-Terje Staberg\n                                 Type:     demo/euro\n                                 .· ThePub ·.oO wHERE THE fILES gO tHROUGH Oo\n\nand so on ... Guess you know whatta mean!\n\n\n\n\n\n\n\n\n\n\nLast Word\n---------\nAs  i  hate  typing docs i stop now ...  Guess everything has been said.  If you\nstill  have no idea how to configure and use this neet little tool ...  well ...\nI really can`t help it and I guess you`re not worth using it!\n\n\n\n\n\n\n\n\n\n\nGreetings\n---------\n\n     Nightprowler/Hoodlum ^ Mario/TRSI ^ Control/TRSI ^ Irata & Flynn/TRSI\n      CoolCat/TRSI ^ GrindCrusher/TRSI ^ IXXY/TRSI ^ all HAUJOBB staffies\n    Zaphod/Caustic Style ^ H2o/Contra Mogue/Arclite ^ Relief/Twisted/Puzzle\n          Sven The Creator/5D ^ Zerocom/Aliengroup ^ All SAD staffies\n                                All KLF staffies\n                       All my friends in AOL/IRC/INTERNET\n                             All my users on my BBS\n                        All sYSgOD`s using my /X Doors!\n                         Rich for beeing a real friend!\n         Jaqueline, the sweetest girl in the entire world .. I love you\n\n                   And to all my friends and mates in scene!\n\n\n\n\n\n\n\n\n\n   ______ _   ______ _   _______ _          _ ____      _ ______  ______ _\n  _\  __///___\  __///___\ ___ ///__________\\\  _|_____\\\_____|_\  __///__\n |  \____        ''         \__/       ____     ______/               ''      |\n l_________________________________   \_____________________________________|\n                                  l_____|\n\n               ... We`ll come back soon to a screen near you ...\n\n                       And always remember: AMIGA ROOLZ!\n','\n',char(10)),NULL,'auto-added',42152,5,0,NULL,NULL,'sad_fi20','scan',1780048714);
