INSERT INTO door_catalog VALUES('sad_gb21','SAD_GB21.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SAD_GB21.LHA',NULL,'XIM','GBMDiz_21.exe',NULL,'the','SAD','._| _/_/ _/_( _/_\_  |_/  |_\_|_/ _/_. .-=| `--    `   -''   /__.   --''      `  |=-. |  `------------------'' `---------------''  |',replace('     .___  ___  ___ ____.  __. __.  ___\n   ._| _/_/ _/_( _/_\_  |_/  |_\_|_/ _/_.\n.-=| `--    `   -''   /__.   --''      `  |=-.\n|  `------------------'' `---------------''  |\n|     GBModule Dizzer v2.1 - Fli7e/SAD     |\n|     ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~     |\n|   MAJOR! Update for 2.o! Now everything  |\n|    is configurable by the user himself   |\n|  like manufacturer list, pack path aso!  | \n`---------. BEST GB DIZZER EVER! .---------''\n 09/27/96 `----------------------'' No. 0113\n','\n',char(10)),'GBMDiz.doc',replace('\n                                   GBMD V2.1\n\n        GBMod Dizzer by Fli7e/SAD vs. GBFComment by Dragon/Incal & HAX!\n        ---------------------------------------------------------------\n\n                              GBMD has 4 options:\n                         Make filecomment to GB Module\n                    Create FILE ID in ram for manual packing\n      Create FILE ID and pack it along with the GB Module as LHA Archive.\n                      Print Module Information to CLI only\n\n                    GBFC has only 1 option, the COMMENT one.\n\n   GBMD did not only extract the NAME! It detect the COMPANY, the MODULE TYPE\n        and the ROM BANKS used and print all these datas to the file id!\n\n         If the file you run GBMD on is for sure a GB Module it`ll 100%\n            extract the name! GBFComment fucked up on some modules.\n\n          ----------------------------------------------------------\n          Module                GBMod Dizzer              GBFComment\n          ----------------------------------------------------------\n          (?) TRSI RULES                  Ok                      Ok\n          (?) BRING YA BY GCS             OK                      Ok\n          RTYPE2                          Ok                      Ok\n          SUPERMARIO3                     Ok                      Ok\n          GB TEKKAMANBLADE                Ok                      Ok\n          ROCKMAN WORLD2                  Ok                      Ok\n          BURGER TIME                     Ok                      Ok\n          WINNING GOAL                    Ok                      Ok\n          JOE AND MAC                     Ok                      Ok\n          SOLARSTRIKER                    Ok                      Ok\n          SPARTAN X                       Ok                      Ok\n          SPIDER-MAN                      Ok                      Ok\n          TETRIS2                         Ok                      Ok\n          PROBOTECTOR 2                   Ok                      Ok\n          YOSSY NO TAMAGO                 Ok                      Ok\n          TOYSTORY                        Ok                    Fail\n          SPIROU                          Ok                    Fail\n          OLYMPIC GAMES                   Ok                    Fail\n          SOCCER                          Ok                    Fail\n          SUPER BLUES                     Ok                    Fail\n          ----------------------------------------------------------\n\n      You see 5 of 20 modules fucked - this is 25% - TOOO much to accept!\n       I haven`t had the time to test all modules i have but i guess this\n                                 tells enough!\n\n       Note to Dragon: Have you ever tested your tool before releaseing?\n\n          Seems a REXX Coder topped you C & ASM coder again isn`t it?\n\n     But as i`m learning ASM and released the first tools i`ll soon recode\n           the gbdm to asm for further speed and dynamic improvement!\n\n                                     Fli7e!\n','\n',char(10)),NULL,'auto-added',14702,1,0,NULL,NULL,'sad_gb21','scan',1780048719);
