INSERT INTO door_catalog VALUES('sad_lc10','SAD^LC10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SAD^LC10.LHA',NULL,'XIM','HAPPY_ENDiNGS.EXE',NULL,'fLI7e/SAD',NULL,'__|                                  |__\/ _) |  sCEPTIC aMIeXPRESS dESIGN 1996  | (_ |   l__________________________________|   |',replace('     __________________________________   __\n  __|                                  |__\/\n _) |  sCEPTIC aMIeXPRESS dESIGN 1996  | (_\n|   l__________________________________|   |\n|                                          |\n|   sAD-LAST v1.0 ... By fLI7e/SAD 1996!   |\n|                                          |\n|      NICE - FAST - 100% LASTCALLERS      |\n|     mANY fEATURES, # of entrys & more    |\nl_              configurable!             _|\n  )______________________________________(\n','\n',char(10)),'SAD-LAST.doc',replace('\n\n\n\n\n\n\n\n\n\n                                   .\n                                ·.:.·\n                                .:··.             .   .\n                               ::               ·..:.·\n                             .:·     .......     .·::\n                             ::   .:··     ··:.     ·:\n                             :: .:      __    ·:.    ::\n                              :::     _ °° _    :. .::\n                               ::     `-^--''    ::::·\n                               ::               ::\n                                ·:.            .:·\n                                  :::........:··\n                                .::·  ·····::.\n                              . ·:.         ::    .\n                             :::..::        ·::..::: xCz\n\n\n\n\n\n                     _ ____ __ _\n                        _ _\\_\\\  f.L.I.7.e\n     ________ _                                    _ __ ____ _\n ____\   ___///__   ________ _               o.F  ///_//_ _\n|     \____     //\_\  ____///__   ________ _                __\nl___      /             /      //\_\  ____///__   __________ \/\n   /______________                   ___/     //\_\     _   \__   ______ _\n                 /_______________                 _ ____/     //\_\  __///_____\n                                /_______________  \\\________       ______/   /\n                 ........................      /_______/   _ \__     /       /\n                 :                      :                  \\  /___     ____/\n             a.M.I.E.X.P.R.E.S.s        :                    _____\_____/_ _\n                 :                      :                __ |            ///\n                 :               d.E.S.I:G.n             \/ l___        /\n                 :......................:                   ___/    ___/\n                                                       __/\_\  ____///__ ÷f!÷\n                                                      |         /      /\n        .oO bRING yA iN tHE lATE dAYS oF 1995 Oo.     l___            /_\n                                                         /___________///\n\n\n\n                                 _ __\n                               ////_//\ _________________________ ___ __ _\n   _ __ ___ _________________________\ \\\n                                     \\ \\  mY 2nd tRY .... FAST! bUGFREE!\n     sAD-lAST v1.o                    \\ \\__________________________ ___ __ _\n _ __ ___ _____________________________\\ \ __ _\n                                         \//_////\n\n\n\n\n\n\n\n\n\n\n                                 !!! PLEASE !!!\n\n\n   SAD has released a bunch of doors the last years and I think it`s time for\n    YOU to give us some resonance on them! So if you LIKE the SAD doors then\n  contact FLI7e (Author of more than 30 doors and about 78 released versions)\n to put YOUR NAME to a list of doors and to the doors you wish to be registered\n                to (no reg. fee wanted .. just your resonance!)\n                                     Thanx!\n\n                                 !!! PLEASE !!!\n\n\n\n\n\n\n\n\n\n\n                                 .-==========-.\n                                 |  cONTENTS  |\n                                 `-==========-''\n\n                                ø  ©opyrights  ø\n                                ø iNTRODUCTION ø\n                                ø rEQUIREMENTS ø\n                                ø   fEATURES   ø\n                                ø iNSTALLATION ø\n                                ø cONTACT sAD  ø\n                                ø   hISTORY    ø\n                                ø  gREETINGS   ø\n                                ø sAD rELEASES ø\n                                ø  sAD mEMBAZ  ø\n\n\n\n\n\n\n\n\n\n\n-  - -= -===================»> (c)OPYRIGHT nOTES <«=================- =- -  -\n\n          pERMISSION iS gRANTED tO fREELY dISTRIBUTE tHIS pRODUCT fOR\n     nON-cOMMERCIAL pURPOSES oNLY, aS lONG aS aLL fILES rEMAIN uNMODIFIED.\n\n              sELLING iS sTRICTLY fORBIDDEN wITHOUT aNY eXCEPTION!\n\n     iF yOU wANT tO pUBLISH tHIS oR aNY oTHER "©sAD" lABELED pRODUCTION oN\n          a PD SERIES mEDIUM get iN cONTACT wITH tHE aUTHOR tO gET aN\n                             hANDSIGNED pERMISSION!\n\n          oFFICIAL dISTRIBUTED tHROUGH aMINET & wORLD wIDE bBS sYSTEMS\n\n          oFFICIAL sAD dISTRIBUTOR sITES: tHE pUB, eVIL mOON, rAVELAND\n\n                            sIGNED: fLI7e / sAD 1995\n\n- -= -=================================================================- =- -\n\n\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                  iNTRODUCTION\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n\n\n  Some  month  ago  (about  8 or more) I released and FRONT END with included\n  lastcallers  ...   But that one was SOOOOO buggy, slow and lame allover!  I\n  put  the  idea  of  making  an  lastcallers  to  the big box under my table\n  fullfilled  with  ideas UNRELEASABLE in arexx ...  But after trying, coding\n  and imprroving my skill i grabbed it out again and it`s smashing!  I got an\n  Idea  to  find  out  the LAST CALLER without reading the callerslog line by\n  line  and  WITHOUT  taking  the same caller twice or more (most LASTCALLERS\n  don`t  care about the last caller still processed!  eg.  you call your last\n  callers  once  it`ll read out the data of the last caller and put it to the\n  bullfile!   if  you call it the second time same procedure ...  but why the\n  hell the same user should be put to the lastcallers bullfile?  I fixed this\n  neet bug by creating a 2nd datafile with the last callers dataline in it!)\n\n  I  also didn`t mind of the length of the callerslog ..  it`s always running\n  same speed ...  And it`s finding the LAST caller 100%\n\n  But  what do i`ve to say now ...  Just that you should install it and check\n  it  your  own!\n\n                       Signed : fLI7e oF sAD^HJB^KLF^CS!\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                  rEQUIREMENTS\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n\n\n\n\n\n                               /X 3.xx+, OS2.04+\n\n                           !!! REXX SERVER ACTIVE !!!\n\n\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                    fEATURES\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n\n\n\n\n       Recognices Last user In LASTCALLER BULLFILE to prevent of double\n                              entrys in Bullfile\n\n      Can handle Connects up to 128000 (hahaha) (64000 is ISDN i guess!)\n\n                     Recognices F2 or SYSOP local logins!\n\n                 Count upload/download time, not ONLINE time!\n     (Online 40mins looks less interestimng than UPLOAD/DOWNLOAD 40mins!)\n\n                             User Definable header\n\n    Daily Status ... New Users/Day are Counted but not shown in the output!\n             (I`ll put the new users/day in the output next time!)\n\n                                  Nice layout\n\n                 Real fast if you remember it`s an arexx door!\n\n\n\n\n\n\n\n\n\n                               __________________\n                           _ __\_              _/__ _\n\n                                  iNSTALLATION\n                               _ ___        ___ _\n                                   \________/\n                       _ __ ___ ____ _    _ ____ ___ __ _\n                       \\\_\\__\\___\\\  ///___//__//_///\n                                      \\//\n                                       \/\n\n\n\n\n\n\n\n\n\n\n  mAKE  A  DIR  named:   "DOORS:SCEPTIC" and copy the dir "F!-LAST" to it.\n\n  FNISHED ...\n\n\n\n\n\n  SAD-LAST.cfg\n  ~~~~~~~~~~~~\n\n  BULLFILE	= Outputfile\n  HEADER	= Header (ascii???)\n  ENTRIES	= Number of last callers entrys in the bullfile\n\n  eg:	BULLFILE	= "doors:sceptic/F!-LAST/SAD-LAST.bull"\n  	HEADER		= "doors:Sceptic/F!-LAST/SAD-LAST.header"\n  	ENTRIES		= 10\n\n\n\n  Get your LOGOFF BATCH open and add the followng line:\n\n  -> cUT <---------------------------------------------