INSERT INTO door_catalog VALUES('sad_ls22','SAD_LS22.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SAD_LS22.LHA',NULL,'XIM','SAD-Lousy.xim',NULL,'Fli7e/SAD','SAD','._| _/_/ _/_( _/_\_  |_/  |_\_|_/ _/_. .-=| `--    `   -''   /__.   --''      `  |=-. `-.`------------------'' `---------------''.-''',replace('     .___  ___  ___ ____.  __. __.  ___\n   ._| _/_/ _/_( _/_\_  |_/  |_\_|_/ _/_.\n.-=| `--    `   -''   /__.   --''      `  |=-.\n`-.`------------------'' `---------------''.-''\n  `-( SAD-Lousy Caller 2.2 (ASM VERS.) )-''\n               by Fli7e/SAD\n      XIM & CLI Version for AMIEXPRESS\n      >>> CLI Version for F.A.M.E! <<<\n   Now even FAME sysops can use this dumma!\n New Design and CFG FILE for /X ONLINE VER.!\n','\n',char(10)),'SAD-Lousy.doc',replace('\n\n\n\n\n                                                                  _ _________\n  ·                         ________ _ ____________  _____________          //\n /_   Sceptic (/X·Design)   \        _.)     _     \.)    _      /          /_\n  /                       _..\       \|      _      |     /     /  ·Mo!/aL·  /\n //_______________ _     /_||_________\______/______|________  /_.          ·\n                                                             \//_|\n\n\n\n\n\n     - -- --- -----( SAD-Lousy Caller (ASM Version) v2.2 - ©1996 Fli7e/SAD )=-.\n.                                                                             |\n`-=( AmiExpress 3.x and S!X compatible )=-----------=( XIM Online VERSION! )=-''\n\n\n\n\n\n                    MY FIRST ASM TOOL - FINALY MADE - YEAH!\n\n\n\n\n$VER: 2.2\n---------\nChanged the design and added the TOTAL NUMBER OF USER IN USER.DATA to the\noutput.\n\n1st speedcheck made! 1000 user take about 0.96 seconds to analyze!\n(if you REDIRECT it to a file!)\n\n\n\n\n\nNow the sysop can configure the NUMBER OF DAYS to check the users for\nin the SAD-LOUSY.cfg file. Just enter a number between 1 and 999 and\nLOUSY CALLER will use this number instead of the fixed amount. I used\nto use the FIXED amount in the last version as i am a beginner in asm\nand had no knowledge of the StrToLong.\n\n\nWhat is this dumma for?\n~~~~~~~~~~~~~~~~~~~~~~~\nWell .. as the big brother, the CLI version this dumma is for only one\npurpose: SHOW LAMER!\n\nThe door will display all user who have not called for at least xx days!\nIf a user did not called for x days and 1 second he`ll be displayed in\nthe list. So you better do NOT include it in your login bull if you have\nlotsa user and many who haven`t called for more 30 days as the output\ncan become LOOOOOOOOOOOOOOOOOOONG!\n\nThe door is real fast! It uses a high quality DOS-COMPATIBILITY and\ndo not TRASH any registers or memory blocks! There are some doors\nout there kicking the big butt of the system!\n\nSoon there`ll be an ENHANCED version for the sysop to configure\nthe output colors and the number of days used to check the user for.\n\nAnd as this is an XIM door you`ll have no problems to run it! Just\ncopy the DOORS:/ drawer to your doors and the BBSCMD "Lousy" to your\nbbs cmd`s. You can also rename the command to whatya want. I don`t\ncheck the name!\n\n\n\n\n         To get in contact or get hold of any other SAD door or update\n                                  try to call\n\n\n\n\n\n                                _ _________________________________ _.\n                                                                  //_|\n                                                                     .\n                                 ·thE PuB·                           |\n                 ______                                ______________\n   _____  ______|     ( ________          ___________ _\      _.     |_______\n _|     \.)     |     _/     __/___     _/   _      /   \     \|     _      /\n \_      |      _     \     _/     |   /     /     /     \     |     /     /\n  |______|      |______\___________|  /      _____/____________|__________/\n         |______|                    /_______|-Mo!/aL\n  .\n  | SAD WHQ - SLT GHQ - NEON DIST - KLF EHQ - OMA MEMBER BOARD - LFC SUPPORT\n  .\n  |     !Only PRE-Created acocunts, Closed System, No ELITE 0-3 CRAP!\n  .\n  |  Principal: Fli7e - Staff: Shallow/SAD^RKM^LFC and SpeedFreak/SLT^C!\n  |__\n  |_//_____________________________ _\n\n\n\n\n\n  Try to catch me on: Pirates Delight, Evil Moon, Acid Slam or any other BBS\n                     you find me on to ask for an account!\n\n                                     Fli7e\n','\n',char(10)),NULL,'auto-added',39051,1,0,NULL,NULL,'sad_ls22','scan',1780048719);
INSERT INTO door_catalog VALUES('sad_ls2u','SAD^LS2U.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SAD^LS2U.LHA',NULL,'XIM','.___  ___  ___ ____.  __. __.  ___',NULL,'Fli7e/SAD',NULL,'._| _/_/ _/_( _/_\_  |_/  |_\_|_/ _/_. .-=| `--    `   -''   /__.   --''      `  |=-. `-.`------------------'' `---------------''.-''',replace('     .___  ___  ___ ____.  __. __.  ___\n   ._| _/_/ _/_( _/_\_  |_/  |_\_|_/ _/_.\n.-=| `--    `   -''   /__.   --''      `  |=-.\n`-.`------------------'' `---------------''.-''\n  `-( SAD-Lousy Caller 2.1 (ASM VERS.) )-''\n               by Fli7e/SAD\n      XIM & CLI Version for AMIEXPRESS\n      >>> CLI Version for F.A.M.E! <<<\n   Now even FAME sysops can use this dumma!\n','\n',char(10)),'SAD-Lousy21.doc',replace('\n\n\n\n\n                                                                  _ _________\n  ·                         ________ _ ____________  _____________          //\n /_   Sceptic (/X·Design)   \        _.)     _     \.)    _      /          /_\n  /                       _..\       \|      _      |     /     /  ·Mo!/aL·  /\n //_______________ _     /_||_________\______/______|________  /_.          ·\n                                                             \//_|\n\n\n\n\n\n     - -- --- -----( SAD-Lousy Caller (ASM Version) v2.1 - ©1996 Fli7e/SAD )=-.\n.                                                                             |\n`-=( F.A.M.E Version )=-------------------------------------------------------''\n\n\n\n\n\n                    MY FIRST ASM TOOL - FINALY MADE - YEAH!\n\n\n\n\nWhat is this dumma for?\n~~~~~~~~~~~~~~~~~~~~~~~\nSAD-Lousy  is a small and !!FAST!!  bulletin creator for /X & S!X and now available\nfor FAME to figure out user who did not have called for a specific number of days.\n\nThe SYSOP can have 2 ways of usage: 1) Display the bulletin to cli only\n                                    2) Redirect the bulletin to a file.\n\nThe  2nd  usage  can  be  realised  by  redirecting the output with the CLI ">"\noption!   I  don`t  want to include a fucking routine to the tool itself as the\nDOS features this rotten nice option internaly.\n\n\n\n\n\nHistory for this crap\n~~~~~~~~~~~~~~~~~~~~~\n\n$Ver: 1.0\n---------\nI firstly made this tool in AREXX but it became slow on hughe user.data files!\n\n$Ver: 1.5\n---------\nAfter  that  a  friend teached me how to realize it in C.  It became faster but\nLONG in executable file!\n\n$Ver: 2.0\n---------\nAt the end i used my OLD asm knowledge and the help from WIGWAM/SAD who teached\nme  lotsa  things  for asm i did not knew at the present time.  (Arexx coder do\nnot know anything about autodocs!  and dosbase ya know!)\n\nNow  the  tool  has  lotsa  text for error description and a hughe DESIGN!  The\nPLAIN executable without detailed error information and esc codes in the output\nhas  a length of 1143 bytes!  The RELEASE version is twice as long but 10 times\nnicer!\n\n$Ver: 2.1\n---------\n\nOPTIMIZED many routines as i learned some more tricks to play with!\n\nAfter  i  released  v2.0  some  days  ago i added some more info strings to the\noutput like Number of user und the number of days the sysop specified to create\nthe output.\n\nAlso included is the DATE & TIME of the output generating.\n\n2 Checks are also included: 1) If your internal system clock has wrong setts\n                               and the actual time value is lower than the\n                               time value of the user last called the user\n                               will not be processed.\n\n                            2) If you specify a number of days >999 the tool\n                               will interrupt as even 999 is much to high!\n                               Is there somebody who really have user which\n                               haven`t called for >3 years?\n\n$VER: 2.1 FIX RELEASE\n---------------------\nFixed a small bug in output!\n\n\n\n\nUsage (is there any!?)\n~~~~~~~~~~~~~~~~~~~~~~\nWell  well  ...  There`s realy nothing you need to know!  You only have to tell\nthe  tool  for which user it should look and WHERE the datas are stored!\nIf you e.g.  want to know which user did not have called for 30 days or more\nand your user.data are stored as default you simply type:\n\nSAD-Lousy2.exe 30 fame:userdata/user.data\n\nIf you want to have the output in a file you type\n\nSAD-Lousy2.exe 30 fame:userdata/user.data >file\n(e.g. SAD-Lousy2.exe 30 fame:userdata/user.data >bbs:Screens/Lousy.txt)\n\nThat`s it!\n\nSAD-Lousy2  also checks the USER.DATA for ERRORS!  If the user.data is CRIPPLED\nor corrupted it`ll tell ya and interrupt the work emediately!\n\n\n\n\n\n\n\n\n\n\n         To get in contact or get hold of any other SAD door or update\n                                  try to call\n\n\n\n\n\n                                _ _________________________________ _.\n                                                                  //_|\n                                                                     .\n                                 ·thE PuB·                           |\n                 ______                                ______________\n   _____  ______|     ( ________          ___________ _\      _.     |_______\n _|     \.)     |     _/     __/___     _/   _      /   \     \|     _      /\n \_      |      _     \     _/     |   /     /     /     \     |     /     /\n  |______|      |______\___________|  /      _____/____________|__________/\n         |______|                    /_______|-Mo!/aL\n  .\n  | SAD WHQ - SLT GHQ - NEON DIST - KLF EHQ - OMA MEMBER BOARD - LFC SUPPORT\n  .\n  |     !Only PRE-Created acocunts, Closed System, No ELITE 0-3 CRAP!\n  .\n  |  Principal: Fli7e - Staff: Shallow/SAD^RKM^LFC and SpeedFreak/SLT^C!\n  |__\n  |_//_____________________________ _\n\n\n\n\n\n  Try to catch me on: Pirates Delight, Evil Moon, Acid Slam or any other BBS\n                     you find me on to ask for an account!\n\n                                     Fli7e\n','\n',char(10)),NULL,NULL,38990,5,0,NULL,NULL,NULL,'scan',1780048719);
