INSERT INTO door_catalog VALUES('sad_sc20','SAD^SC20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SAD^SC20.LHA',NULL,'XIM','_____      ______      ._____',NULL,'FLI7E/SAD^CS!^HJB',NULL,'_) __/______\__  (______|__  (_ ._\___       ___        ____/    \_________. |    ¦       \          \                  |',replace('   _____      ______      ._____\n  _) __/______\__  (______|__  (_\n._\___       ___        ____/    \_________.\n|    ¦       \          \                  |\n¦                                          ¦\n: SAD-COM V2.O  - REAL GREAT COMMENT DOOR  :\n:               - WITH REAL CURSOR SUPPORT :\n:               - AND REAL MSG COUNTING!   :\n.                                          .\n. 101% AREXX CODE BY FLI7E/SAD^CS!^HJB `96 .\n·..........................................·\n','\n',char(10)),'SAD-COM.doc',replace('\n\n\n\n\n                                       ..\n                                     .::::.\n\n                         - 4 yEARS sCENE aNNIVERSARY -\n\n                                     ·::::·\n                                       ··\n\n\n\n\n                         _   _  _ __ ___ _\n                                      _/// wE`RE nOT jUST pLAYING tHE gAME ...\n                                     |\n                                     ·\n    _______   ________  ________   __________ _____       _____   ________\n_ __\  ___(___) _ ___/__)  ____/___)____    /_)   _|___ __)___/___) _ ___/___ _\n)))_ \____      \\\       __)       _ _/           ___/_\           \\\    _(((\n÷f!(______________________________  \\\____________________________________)cS!\n                                 (______|\n                                     .\n                                     |\n                                  _ _|\n  ... wE gONNA lEAD aND dOMINATE! \\\___ __ _  _   _    _\n\n\n\n                               sCEPTIC /X dESIGN\n\n                                    pRESENTS\n\n\n\n\n\n                            >>> sAD-cOMMENT v2.o <<<\n\n\n\n\n\n-  - -= -===================»> (c)OPYRIGHT nOTES <«=================- =- -  -\n\n          pERMISSION iS gRANTED tO fREELY dISTRIBUTE tHIS pRODUCT fOR\n     nON-cOMMERCIAL pURPOSES oNLY, aS lONG aS aLL fILES rEMAIN uNMODIFIED.\n\n              sELLING iS sTRICTLY fORBIDDEN wITHOUT aNY eXCEPTION!\n\n     iF yOU wANT tO pUBLISH tHIS oR aNY oTHER "©sAD" lABELED pRODUCTION oN\n            a PD SERIES mEDIUM get iN cONTACT wITH tHE aUTHOR fIRST!\n\n          oFFICIAL dISTRIBUTED tHROUGH aMINET & wORLD wIDE bBS sYSTEMS\n\n          oFFICIAL sAD dISTRIBUTOR sITES: tHE pUB, eVIL mOON, rAVELAND\n\n                            sIGNED: fLI7e / sAD 1996\n\n- -= -=================================================================- =- -\n\n\n\n\n\n\n\n\n\n\nwHAT iS tHIS oNE fOR\n~~~~~~~~~~~~~~~~~~~~\nSad-Comment  is  another  (yes ..  another) COMMENT TO SYSOP (COOP) AIM door!\nIt  features  all the general stuff like:  REAL cursorkeys usage, Comment for\neach Sysop and NUMBER OF WRITTEN MESSAGES for each sysop.\n\nThe  Message  counting  is 100% because the counter increases only if the MSG\nwas  SAVED!  not when the Sysop has been choosen and the MSG writing has been\naborted!\n\nI also NEVER saw REAL cursor keys Usage in AREXX doors (idenfieable as those)\nbefore!  Thanx to GRAVEDANCER ex NEUTRON now SAD for the hint ..  IT WORKED!\n\nAll  the  COLORS can be set by yourself!  Only the COPYRIGHT and the DOORNAME\ncolors  are  unchangeable!   So  you  can  have blue border, yellow border or\nmagenta or whatever color ..  Have a look and judge!\n\nAlso  the  LENGTH  is  very important I guess!  Why the hell should a COMMENT\ndoor eat about 10k or more of HD space!??  Mine is about 2.6k and it features\nall it need to!\n\nAlso  the  NUMBER  of sysops is unlimited!  I saw some comment doors having a\nlimit  of  9  or  10  (0-9)  sysops because theyy were handled using a simple\nGetchar  routine  ..   GET REAL YOU CODERS ..  WHAT YA GUESS YOU DO??  Such a\ndoor can be made in 10 lines and an external textfile!\n\n\n\n\n\n\n\n\n\n\nhOW tO iNSTALL\n~~~~~~~~~~~~~~\n\nMake a dir named "doors:sceptic" and copy the dir "F!-COM" to this location!\n\nNow copy the "c.info" to your "bbs:commands/bbcmd or node(x)cmd" drawer.\n\nLoad the SAD-COM.cfg file and edit it to your needs!\n\nFor   "How  to  edit  the  cfg  file"  load  the  config  file  and  see  the\ndocumentations on the end of the lines!  I guess they`ll explain anything!\n\n\n\n\n\n\n\n\n\n\n\n\nsOON cOMING sAD rELEASES\n~~~~~~~~~~~~~~~~~~~~~~~~\nJoinConf                      Like the one from EMPIRE. Maybe better but this\n                              is nearly impossible!\n<GRAVEDANCER>\n\n- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n\nFile ID Enhance v4.o          Lotsa news and Improvements!\n\n<fLI7e>\n\n- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n\nAnsiOrder                     Best ASCII ORDER DOOR available! Faster `n more\n                              powerfull as all da doors available (betatested\n<fLI7e>                       or weeks!)\n\n- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n\nTeamTop 2.o                   Will featuring seperate conf bulletins!\n\n<fLI7e>\n\n- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n\nMegaSqueeze                   Kind of MultiTop .. 100% ASM, 9k length!\n\n<wIGWAM>\n\n- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n\nLady Luck                     Omnline Cube game for /X!\n\n<fLI7e>\n\n- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n\nSys Security 2.o              New Version of the good old SYSSEC I released\n                              some months ago!\n<fLI7e>\n\n- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n\nFront Man 1.o                 New FrontDoor! Maybe you know my old with about\n                              9 features! Even more to come and more improved\n<fLI7e>                       source!\n\n- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n\nStyleBase                     Message Base replacement with TEXT STYLE option\n                              and many more! You can style your written msg`s\n<fLI7e>                       or upload them as textfiles .. You can use more\n                              then 9 different textstyles like\n                              sTYLE\n                              sTYLe\n                              §t¥£@\n                              and so on ... Nice for ASCII BBS!\n\n- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n\nDirstyler                     Kinda CATSTYLER but no idea when it`ll be out!\n\n<GRAVEDANCER>\n\nAnd  some  of my old ones with new code, new features, bugfixes and many more\nquality things!\n\n\n\n\n\n\n\n\n\n\nsAD mEMBERS\n~~~~~~~~~~~\n\n                                    gERMANY\n                                    -------\nfLI7e           ... fORMER, sYSgOD, aRTIST, dOOR cODING ................... wHQ\ncLADE rADCLIFFE ... sYSgOD, dOOR cODING ................................... eHQ\nh2o             ... sYSGOD ................................................ gHQ\nlANCE           ... sYSGOD ............................................. G-dIST\nsTARLIGHT       ... sYSgOD ............................................. E-dIST\nwIGWAM          ... fORMER, sAD aSM AIM dOOR aDD oN cODING ....................\ngRAVEDANCER     ... dOOR cODING ...............................................\n\n\n\n                                     iTALY\n                                     -----\ngURGLE          ... sYSGOD ................................................ iHQ\n\n\n\n                                   kIWI lAND\n                                   ---------\ngREEN bERET     ... sYSGOD .............................................. iRLHQ\n\n\n\n                                   aUSTRALIA\n                                   ---------\nrUDOLF          ... sYSGOD ............................................... oZHQ\n','\n',char(10)),NULL,NULL,17067,4,0,NULL,NULL,NULL,'scan',1780048719);
INSERT INTO door_catalog VALUES('sad_sc2r','SAD^SC2R.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SAD^SC2R.LHA',NULL,'XIM','exe.-l0S-eND0S-bBS-.exe',NULL,'fLI7e/sAD^cS!^hJB',NULL,'_) __/______\__  (______|__  (_ ._\___       ___        ____/    \_________. |    ¦       \          \  CRACKED !       |',replace('   _____      ______      ._____\n  _) __/______\__  (______|__  (_\n._\___       ___        ____/    \_________.\n|    ¦       \          \  CRACKED !       |\n¦                                          ¦\n: sAD-cOM v2.o  - rEAL gREAT cOMMENT dOOR  :\n:               - wITH REAL cURSOR sUPPORT :\n:               - aND rEAL mSG cOUNTING!   :\n.  98% aREXX cODE bY fLI7e/sAD^cS!^hJB `96 .\n.   2% aREXX cODE bY ReAllY bOreD sYsOp!   .\n·..........................................·\n','\n',char(10)),'SAD-COM.doc',replace('\n\n\n\n\n                                       ..\n                                     .::::.\n\n                         - 4 yEARS sCENE aNNIVERSARY -\n\n                                     ·::::·\n                                       ··\n\n\n\n\n                         _   _  _ __ ___ _\n                                      _/// wE`RE nOT jUST pLAYING tHE gAME ...\n                                     |\n                                     ·\n    _______   ________  ________   __________ _____       _____   ________\n_ __\  ___(___) _ ___/__)  ____/___)____    /_)   _|___ __)___/___) _ ___/___ _\n)))_ \____      \\\       __)       _ _/           ___/_\           \\\    _(((\n÷f!(______________________________  \\\____________________________________)cS!\n                                 (______|\n                                     .\n                                     |\n                                  _ _|\n  ... wE gONNA lEAD aND dOMINATE! \\\___ __ _  _   _    _\n\n\n\n                               sCEPTIC /X dESIGN\n\n                                    pRESENTS\n\n\n\n\n\n                            >>> sAD-cOMMENT v2.o <<<\n\n\n\n\n\n-  - -= -===================»> (c)OPYRIGHT nOTES <«=================- =- -  -\n\n          pERMISSION iS gRANTED tO fREELY dISTRIBUTE tHIS pRODUCT fOR\n     nON-cOMMERCIAL pURPOSES oNLY, aS lONG aS aLL fILES rEMAIN uNMODIFIED.\n\n              sELLING iS sTRICTLY fORBIDDEN wITHOUT aNY eXCEPTION!\n\n     iF yOU wANT tO pUBLISH tHIS oR aNY oTHER "©sAD" lABELED pRODUCTION oN\n            a PD SERIES mEDIUM get iN cONTACT wITH tHE aUTHOR fIRST!\n\n          oFFICIAL dISTRIBUTED tHROUGH aMINET & wORLD wIDE bBS sYSTEMS\n\n          oFFICIAL sAD dISTRIBUTOR sITES: tHE pUB, eVIL mOON, rAVELAND\n\n                            sIGNED: fLI7e / sAD 1996\n\n- -= -=================================================================- =- -\n\n\n\n\n\n\n\n\n\n\nwHAT iS tHIS oNE fOR\n~~~~~~~~~~~~~~~~~~~~\nSad-Comment  is  another  (yes ..  another) COMMENT TO SYSOP (COOP) AIM door!\nIt  features  all the general stuff like:  REAL cursorkeys usage, Comment for\neach Sysop and NUMBER OF WRITTEN MESSAGES for each sysop.\n\nThe  Message  counting  is 100% because the counter increases only if the MSG\nwas  SAVED!  not when the Sysop has been choosen and the MSG writing has been\naborted!\n\nI also NEVER saw REAL cursor keys Usage in AREXX doors (idenfieable as those)\nbefore!  Thanx to GRAVEDANCER ex NEUTRON now SAD for the hint ..  IT WORKED!\n\nAll  the  COLORS can be set by yourself!  Only the COPYRIGHT and the DOORNAME\ncolors  are  unchangeable!   So  you  can  have blue border, yellow border or\nmagenta or whatever color ..  Have a look and judge!\n\nAlso  the  LENGTH  is  very important I guess!  Why the hell should a COMMENT\ndoor eat about 10k or more of HD space!??  Mine is about 2.6k and it features\nall it need to!\n\nAlso  the  NUMBER  of sysops is unlimited!  I saw some comment doors having a\nlimit  of  9  or  10  (0-9)  sysops because theyy were handled using a simple\nGetchar  routine  ..   GET REAL YOU CODERS ..  WHAT YA GUESS YOU DO??  Such a\ndoor can be made in 10 lines and an external textfile!\n\n\n\n\n\n\n\n\n\n\nhOW tO iNSTALL\n~~~~~~~~~~~~~~\n\nMake a dir named "doors:sceptic" and copy the dir "F!-COM" to this location!\n\nNow copy the "c.info" to your "bbs:commands/bbcmd or node(x)cmd" drawer.\n\nLoad the SAD-COM.cfg file and edit it to your needs!\n\nFor   "How  to  edit  the  cfg  file"  load  the  config  file  and  see  the\ndocumentations on the end of the lines!  I guess they`ll explain anything!\n\n\n\n\n\n\n\n\n\n\n\n\nsOON cOMING sAD rELEASES\n~~~~~~~~~~~~~~~~~~~~~~~~\nJoinConf                      Like the one from EMPIRE. Maybe better but this\n                              is nearly impossible!\n<GRAVEDANCER>\n\n- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n\nFile ID Enhance v4.o          Lotsa news and Improvements!\n\n<fLI7e>\n\n- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n\nAnsiOrder                     Best ASCII ORDER DOOR available! Faster `n more\n                              powerfull as all da doors available (betatested\n<fLI7e>                       or weeks!)\n\n- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n\nTeamTop 2.o                   Will featuring seperate conf bulletins!\n\n<fLI7e>\n\n- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n\nMegaSqueeze                   Kind of MultiTop .. 100% ASM, 9k length!\n\n<wIGWAM>\n\n- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n\nLady Luck                     Omnline Cube game for /X!\n\n<fLI7e>\n\n- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n\nSys Security 2.o              New Version of the good old SYSSEC I released\n                              some months ago!\n<fLI7e>\n\n- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n\nFront Man 1.o                 New FrontDoor! Maybe you know my old with about\n                              9 features! Even more to come and more improved\n<fLI7e>                       source!\n\n- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n\nStyleBase                     Message Base replacement with TEXT STYLE option\n                              and many more! You can style your written msg`s\n<fLI7e>                       or upload them as textfiles .. You can use more\n                              then 9 different textstyles like\n                              sTYLE\n                              sTYLe\n                              §t¥£@\n                              and so on ... Nice for ASCII BBS!\n\n- - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n\nDirstyler                     Kinda CATSTYLER but no idea when it`ll be out!\n\n<GRAVEDANCER>\n\nAnd  some  of my old ones with new code, new features, bugfixes and many more\nquality things!\n\n\n\n\n\n\n\n\n\n\nsAD mEMBERS\n~~~~~~~~~~~\n\n                                    gERMANY\n                                    -------\nfLI7e           ... fORMER, sYSgOD, aRTIST, dOOR cODING ................... wHQ\ncLADE rADCLIFFE ... sYSgOD, dOOR cODING ................................... eHQ\nh2o             ... sYSGOD ................................................ gHQ\nlANCE           ... sYSGOD ............................................. G-dIST\nsTARLIGHT       ... sYSgOD ............................................. E-dIST\nwIGWAM          ... fORMER, sAD aSM AIM dOOR aDD oN cODING ....................\ngRAVEDANCER     ... dOOR cODING ...............................................\n\n\n\n                                     iTALY\n                                     -----\ngURGLE          ... sYSGOD ................................................ iHQ\n\n\n\n                                   kIWI lAND\n                                   ---------\ngREEN bERET     ... sYSGOD .............................................. iRLHQ\n\n\n\n                                   aUSTRALIA\n                                   ---------\nrUDOLF          ... sYSGOD ............................................... oZHQ\n','\n',char(10)),NULL,'auto-added',17682,5,0,NULL,NULL,'sad_sc2r','scan',1780048719);
INSERT INTO door_catalog VALUES('sad_st10','SAD^ST10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SAD^ST10.LHA',NULL,'XIM','LE-window6.12',NULL,NULL,NULL,'._| _/_/ _/_( _/_\_  |_/  |_\_|_/ _/_. .-=| `--    `   -''   /__.   --''      `  |=-. |  `------[AmiEx]-----'' `----[Design]---''  |',replace('     .___  ___  ___ ____.  __. __.  ___\n   ._| _/_/ _/_( _/_\_  |_/  |_\_|_/ _/_.\n.-=| `--    `   -''   /__.   --''      `  |=-.\n|  `------[AmiEx]-----'' `----[Design]---''  |\n|    FastStat v1.o - ©1995/96 FLi7e/SAD    |\n|   !Nice styled Status door with METER!   |\n|      Just watch and judge yourself!      |\n`------------------------------------------''\n','\n',char(10)),'CLASS.README',replace('                      ·\n     .:::::··   ·     : ·\n   .::''  _______    .:::.   _________     rIOT..: - WHQ  JORMAS..: - GHQ\n  .:''  ._\_    /__ .:   :.__\  _____/___. ABYSS.: - GHQ  NUANCE..: - EHQ\n  :·   |     _/   ::     ::  \----.     | GODS..: - GHQ  SYNDROME: - GHQ\n  :    :--.________:.   .:''_____________| mONO..: - GHQ  sUKMAS..: - GHQ\n  :                 :. .:                         ·\n  :               .  ::: .· >>LOS·ENDOS·BBS<<     :\n  :    ____________   :       _____   ________  .:::.    _________\n  :  ._\_____     /___·_____ |     |__\____   \.:    :.__\  _____/___.\n  :  |    _/_____/    |     \|     |      /   ::     ::  \----.     |\n  :  :--._____________|____\ \     |-.________/:.   .:''--.__________|\n  :                  cDr/e^d\______|            :. .:\n                                                 :::      _ _ __  _\nnODE0: +49-(0)-02103-lOCAL   -   33.6k v.34 sOON! :    __/\\__ _ __  _\nnODE1: +49-(0)-02103-52440   -   33.6k v.34 sPEED      \ Oo¯//_ _   _\nnODE2: TELNET 194.163.210.xx -   19.2k !vARIABLE!      / ø _\\__ _  __\nnODE3: TELNET 194.163.210.xx -   19.2k !vARIABLE!      ¯¯\//¯¯_    __\n                                                          ¯\n   - t H I S   i S   d A   b O A R D   f O R   t H E   d E M O S C E N E -','\n'