INSERT INTO door_catalog VALUES('salog107','SALOG107.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SALOG107.LHA','SAmiLog_v107','XIM','SAmiLog_v107','1.07','P0T-NOoDLE',NULL,NULL,replace('SAmiLog V1.07 by P0T-NOoDLE / AnTHRoX.\n','\n',char(10)),'readme.doc',replace('\nTo ensure that the util is never spread without the docs,\nThe Docs files are built into the utility!\n\nType "SAmilog" for command line help\n\nLook in the ATX_UTILS directory for an Example of SAmilogs output, as well\nas outputs from just some of the other great Anthrox Utilities!\n\n\n\nAlso included is SALD.REXX  -  This is a pretty straight forward ARexx\ndoor to replace the "*L" command. It will interface the userwith samilog\nso they can create their own last callers list while online.\nPlease edit the ARexx door in your favourate ASCII editor to configure\nthe Path for Super-Amilog.\n\n\n-- We know you''ll love and use our util! Stay tuned for more updates! --\n\n   P0T-NOoDLE / AnTHRoX\n\nV1.07 (RELEASE 3) Updates: (Released 25th October)\n==========================\n» Now detects when a new day has started in a newly-cleared storage file\n- EG: Now it won''t keep adding to the number of calls(etc) today when the\n- next day has arrived... (This problem didn''t exist if you had previously\n- make a storage file with an older version!)\n* Sorry that this bug was not fixed sooner! v1.06 was finished and released\n- the day before I went on a week-long trip, so as I have only just got home,\n- I''ve only just found out about this little bug (which was hella-easy to fix)\n- Please note that this bug was in an old routine I DIDN''T change, and that I\n- did bug test all the new routines...\n- I sat on it for another day just in case, and after having me brains blow\n- away by Metallica last night, I now have time to compile it and release it!\n\nNOW GET THE WORLD RUNNING SAMILOG!\n','\n',char(10)),NULL,'auto-added',11409,3,0,NULL,NULL,'salog107','scan',1780048719);
INSERT INTO door_catalog VALUES('salvuser','SALVUSER.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SALVUSER.LHA','salvuser','XIM','salvuser',NULL,NULL,NULL,'that has been corrupted.',replace('Salvuser. Salvs any user.data & user.keys\nthat has been corrupted.\n','\n',char(10)),'Salvuser.DOC',replace('                                May 30 1992\n                      Salvuser:  Written By Joe Hodge\n                      ~~~~~~~~\n            This great util is a must for all AmiExpress sysop\n  What this file does is fix any user.data & user.keys that may have been\n  corrupted. The Util will back up your old user.data file and user.keys\n  files with the .old appendix. This util will also squeeze the new files\n  down. Note after doing this delete all the partuploads and loss carrier\n          files you may have cause the slot numbers will change.\n\nUsage:\nBBS:>Salvuser BBS:user.data BBS:user.keys\n\n   I would like to thank Joe Hodge for writing this util, I have learned this\nfrom experience and told him my problem and the turn around time was within\none hour.\n\n      If you are not registered with AmiExpress I suggest you do so.\n\n                 Call BullDogs Freinds BBS (318)-793-4101\n\n                      Bigfoots'' BBS!   (216)-286-4611\n\n\nBigfoot/qtx \n- I hope these docs are simple ( which they are )\n','\n',char(10)),NULL,'auto-added',13914,3,0,NULL,NULL,'salvuser','scan',1780048719);
