INSERT INTO door_catalog VALUES('sbs_sta4','SBS-STA4.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SBS-STA4.LHA',NULL,'XIM','nWt  ________                 ________',NULL,NULL,'SBS','__\    __/___ .sUBSPACe. __\    __/___ /   \_____    \____      /   \_____    \ _/        \/     \_ /_____/__      \/     \_',replace('nWt  ________                 ________ \n   __\    __/___ .sUBSPACe. __\    __/___\n  /   \_____    \____      /   \_____    \\n_/        \/     \_ /_____/__      \/     \_\n\_________________/___       \_____________/ \n.----------. _/    \/         \_ .---------.\n|          `-\_________________/-''         |\n|                                          |\n| NewStatus v1.4 ..AWESOME design..USE IT! |\n!                                          !\n[·cODiNG bY: NEWt/sBS^sDX·]===[· 13-03-96 ·]\n','\n',char(10)),'ReadMe-NewStatus.txt',replace(' \n---------------------------------------------------------------------------------\n  READ ME...READ ME...READ ME...READ ME...READ ME...READ ME...READ ME...READ ME\n---------------------------------------------------------------------------------\n\n Introduction:\n -------------                          \n\n  This util is a Status-Door. It simply displays your status amongst other\n  stuff. Have you seen it before?..YES! But this one is good looking too! =)\n\n Installation:\n -------------\n\n  Just copy all the files as they are!\n\n\n History:\n --------\n\n  0.9: Looked like hell, fixed that too! =)\n\n  1.1: Replaced Ratiotype with Expert Mode\n\n  1.2: Fixed a minor bug! (Thanx B.B.King)\n\n  1.3: Made a shorter display so that you can have it in SYSCmd!\n\n  1.4: Discovered a BIG bug. Version 1.3 was never released.\n       This one comes with GREAT design and NO bugs at all.\n\n For Bug-reports & Comments:\n ---------------------------\n\n  Mystique        = +46-36-123029    SYSOP: Newt\n\n  OR:  \n \n  Digital Highway = +46-31-885248    SYSOP: Zalo \n  Global Effect   = +46-500-485978   SYSOP: Xerxes\n  City Of Joy     = +46-NOT 4 YOU!   SYSOP: B.B. King\n  Outpost         = +46-36-145544    SYSOP: Ironnuke!\n        \n\n		Greets must reach out to the following:\n     ------------------------------------------------------------------\n\n	Cenobite/Sardonyx		: Bye,bye friend\n	Electron/Sardonyx^Citron	: You`ll get your articles soon!\n	Zalo/Sardonyx^Subspace          : Hit med datorn! =)\n        Elusive/Sardonyx                : Well...Bye friend! =)\n\n	Xerxes/Balance^Insane		: How`s life?\n	Excel/Balance^Crux     		: Urg!...orkar inte mer! =)\n	Atheist/Balance^Ram Jam		: Where are you nowadays\n\n	Ironnuke/Cax Crew^Element	: Another Hd-Crash?\n	Apache/Cax Crew			: LAMER!! =)\n\n	Vacum/m22			: Nice music from you!\n	Zero!/m22			: Is the intro ready yet?\n\n	Cybergod/Ram Jam		: Where did I loose you?!\n	Vega/Ram Jam			: Any new modules?!\n\n	Decoy/Passion			: Sorry for not writing\n	Adonis/Passion?			: Still playing handball\n	\n	Paperboy/Mobile?		: Long time no see!\n	Gangsta/Scoopex			: Keep cool, you ruuuule!..hehe...\n	General Lee/?			: Jag har slutat swappa! =(\n	Keldon/Nine Design		: No trading at my place, sorry!\n	Iro/Depth			: Sorry for not answering..\n	Qix/Vacuum			: Thx for the postcard!\n	Neptune/Otl			: Great ascii/doors from you!\n	Desoto/e^d			: Nice to have you in Sbs\n	B.B King/Anathema		: Great board you`ve got!\n	Visitor/Fld^cls^sbs 		: How`s life in gtb?\n	Mr.Coke/Sunshine Prod.		: Any new projects?      \n	Trollet/?			: Trade at my place!\n	Kazer/Depth			: Hmm....\n	Pay/Neo                         : Sorry for not answering..\n	\n	Sorry for not making a comment to everyone but to those that \n        I didn`t write, well then I`ve got nothing to say to you. \n\n        ...I HAVE STOPPED SWAPPING SO DON`T WAIT FOR ANY MORE LETTERS...\n\n================================================================================\n			    ...BBS-ADVERTS BELOW...\n================================================================================\n','\n',char(10)),NULL,NULL,12155,4,0,NULL,NULL,NULL,'scan',1780048719);
