INSERT INTO door_catalog VALUES('sck_msgb','SCK-MSGB.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SCK-MSGB.LHA',NULL,'XIM','SUCK-MSGM.exe',NULL,NULL,'SCK','________/|  :___/|    :_____/|  .___/| _____ \¾  _____|__|¾   |____|¾  ___|__|¾   |/    / :\_______   |    |    |   V     |    /   _/:',replace('         .       .           .       .\n________/|  :___/|    :_____/|  .___/| _____\n\¾  _____|__|¾   |____|¾  ___|__|¾   |/    /\n:\_______   |    |    |   V     |    /   _/:\n.|!     V   |    !    |   |     |    \    \_\n||__________|_________|_________|____|\____/\n:===============( PRESENTS )===============|\n|      MsgBase Maker v1.0 Beta for /X      |\n)------------------------------------------(\n|      Have your own ''hugh'' msgbases!      :\n`------------------------------------------''\n» LOOKS LIKE METAL IMPACT BEAT YOU AGAIN ! «\n','\n',char(10)),'baffle2.txt',replace('                   _ __ ___.\n    .___ __ _          \\  |\n    |  //               \\_|  (   n  u  c  l  e  a  r    w  a  s  t  e   )\n    |_//                 \_.\n    ._/ ·aMIGA & cONSOLE·  |\n    |                      |  Roockin'' Six Nod''az System on usr & multiface\n  ___________     _____ ________ _______             _ ______________________\n  \_      __/____|    _/      _/      _/________ _   \\\    _      _        /\n   /      \      /    \       \|      |/     __///__/       _     _/      _/\n._/      /      /|     \       \_.    /     _\       .______/     \       \_.\n|________\______________\________|____\______________|-Mo! /_______\________|\n    .           ______  ___________________ ________ _____\n    |          |      ||      .     _      /      _//     |_ ______ _\n    |_         |      /\      |     _      \      \/      _/    __///___\n    ._\        |____  /\____________/      |\      \      |    _\       |\n    | \\            \/             /_______________/____________________|\n    |__\\__ _\n\n  EQUINOX EHQ · SRH EHQ · CRAZE SHQ · FLYING COWS SHQ · DATA DIVISION SHQ\n\n       STAFF:  mARWiC · nIKE · bAFFLE · xERXES · sTYLEwARS · oRCHId!\n\n        RUNNING: a4O4O/1OMb+112OMb · a3O3O/6Mb+755Mb · a5OO/cDROM!\n\n    nOdE#1: +46-find-out! · nOdE#2: +46-find-out! · nOdE#3: +46-find-out!\n nOdE#4: 130.244.tel.net · nOdE#5: 130.244.tel.net · nOdE#6: 130.244.tel.net\n\n                   (·tELNET·aVAiLBLE·aSK·mARWiC·oN·iRC·)\n\n','\n',char(10)),NULL,'auto-added',15342,5,0,NULL,NULL,'sck_msgb','scan',1780048719);
INSERT INTO door_catalog VALUES('sck_nubc','SCK-NUBC.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SCK-NUBC.LHA',NULL,'XIM','exe.-l0S-eND0S-bBS-.exe',NULL,NULL,'SCK','<==/.  _____/. V    |.      |.  |)    /==> :::\_____  \   |   :|   |___|   /   _/:::: :::|:   V  \\  :   ||:  |   |:  \\   \_:::',replace('    ___________ ____ ___________.______\n<==/.  _____/. V    |.      |.  |)    /==>\n:::\_____  \   |   :|   |___|   /   _/::::\n:::|:   V  \\  :   ||:  |   |:  \\   \_:::\n:::|________/_______|_______|___|\____/:::\n<==============( Presents )===========cN=>\n  NewUser BroadCaster v1.o for /X & S!X\n','\n',char(10)),'NUBC.Doc',replace('                        .        .           .       .\n              _________/|  :____/|    :_____/|  .___/| ______\n  - -- -------\·   _____|__|·    |____|·  ___|__|·   |/   cN/------- -- -\n    » ·«» _/\  \________   |     |    |   V     |    /    _/  /\_ «»· «\n               |!      V   |     !    |   |     |    \     \_\n  - -- --------|___________|__________|_________|____|\_____/------- -- -\n                ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~  ~~~~~\n                       P · R · E · S · E · N · T · S\n         _.____________________________________________________._\n          |                                                    | \n          |        NewUser BroadCaster v1.o for /X & S!X       |  \n         _|____________________________________________________|_\n          :                                                    :\n\n                             by Crimson!/Suck\n\n\n\n                               Introduction:\n                               ~~~~~~~~~~~~~\n\n    Nubc is door which sends an ''eall'' message stating that a newuser  \n   has applied. The message contains the name and location of the user.\n\n   (Like New User Inquier from Pharaoh, but his version 1.4 never worked\n                   on my board, so I wrote my own one!.)\n\n               NUBC is fast C code and is 14976 bytes long.\n\n\n\n                               Installation:\n                               ~~~~~~~~~~~~~\n\n           Just unpack the archive to the right directories or:\n\n           Make a directory in your doors: dir called SUCK_NUBC\n             and copy NUBC.x, NUBC.doc, NUBC.output.iff to it!\n                     Copy NEW.info to your Bbscmd dir.\n\n                  Doors:Suck_NUBC/NUBC.x\n                                   NUBC.Doc\n                                    NUBC.Output.iff\n\n                  Bbs:Commands/BbsCmd/NEW.info\n\n\n        The S: directory must contains ''NUBC.config'' and must have\n        the conference location where the message shall be written!\n   \n             Ex. BBS:CONF4/         <-- (ending with a ''/'' !!)\n\n    and the eof sign must end BEHIND the path and not on the next line,\n                         or the door will crash...\n\n\n             The best way to start your door from Joined.txt!\n\n  If you dont know how to start a door from a txtfile, you''re pathetic...\n\n\n\n                                 History:\n                                 ~~~~~~~~\n\n                         v1.o Release (31.Oct.95)\n\n\n\n                                Bug-Report\n                                ~~~~~~~~~~\n\n                If you find any Bugs or have suggestions, \n                     please leave a mail to CRiMSON! \n                 at ''Dawn Of Eternity'' or ''Metal Impact''!\n\n\n\n                                  Greets:\n                                  ~~~~~~~\n\n             Sal-1 - Colonel - -TCB-! - Uli - Circuit Breaker\n\n','\n',char(10)),NULL,'auto-added',21631,5,0,NULL,NULL,'sck_nubc','scan',1780048719);
INSERT INTO door_catalog VALUES('sclean17','SCLEAN17.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SCLEAN17.LHA','SentCleaner','XIM','SentCleaner',NULL,NULL,NULL,': _____._____/ _  \/  ___/ . \_____._____ : :-\___ |::::/  |   \  __/  |  \::::| ___/-: :  -\__|::::\__|   /  |/   .   \:::|__/-  :',replace('. PrEsEnTs    ____  _________    PrEsEnTs .\n: _____._____/ _  \/  ___/ . \_____._____ :\n:-\___ |::::/  |   \  __/  |  \::::| ___/-:\n:  -\__|::::\__|   /  |/   .   \:::|__/-  :\n·!911-\|:::::::|  /   |\   |   /:::|/-    ·\n       `-------''\/--\/+-\/`--------''       \n   AutoSent Data File Cleaner V1.7 Turbo   \n:.:.:.:.:.:.:.:.:.:.:.:.:.:.:.:.:.:.:.:.:.:\n','\n',char(10)),'SentCleaner.Doc',replace('sentcleaner v1.7 turbo by galaxy/tfa\n\n-------------------------------------------------------------------------------\n       note this is a fast overview because some dont know what i mean!\n-------------------------------------------------------------------------------\nwell  note:   it is right that autosent will ask a user again if his sentby was\ndeleted  by  some  reasons.   but  if you delete users!  the sent.dat will stay\nlonger  and  nothing  can  change  this only this tool (or do you sysop want to\ndelete  the sent.dat everytime ?) you think you dont like the option above then\nwatch  the  other  feature.  it will let you sysops make defaults for all those\nideots  who never made a sent line!  only choose the line to use and then press\nthe right button and all users who need a sentby will get a default\n-------------------------------------------------------------------------------\n\nattention attention!\n\ndon''t  run  any  version  lower than 1.3 if you do you are lossing you sent.dat\nwell  i  noticed a fucking damned bug in my util and managed to fix it hehe now\nit works 100% errorfree.  ( fucking error :) )\n\nwell  you might ask why the hell i wrote this util!  ok before i explain how to\nuse  it i will tell you the story ok you got fileid the great tool from mystic,\nyou  got  autosent?  well but what will happen when you delete users?  yeah the\nhandle  is  still  in  the  sent.dat.   what will happen when you use the great\nudcleaner from empire mystic which will overrun your user.data and clean it up?\nyeah  all  sentbys  has  to be created new because they are not in right places\nanymore  and what is, when some of your users are not able (how ever the reason\nis)  to  create  a sentby yeah it will get on yer nerves..  this util will help\nyou with everything..\n\nhere an example what udcleaner does:\n\nsysop	=	1		(1 = usernumber)\nkimbel	=	2\nrainer	=	3\n\nrainer  has  made  a  sentby  for  3 (because three is his usernumber) but what\nhappen  when  i  remove  kimbel?  yeah rainer will become usernumber 2 and this\nmeans  the  autosent  cant match the location anymore rainer has to write a new\nsentby!   isn''t  it a shit because you sysop want that all users use sentby and\nthat  poor  dude  thought that he already made one and then !!  everytime a new\nquestion  ''enter sentby...''!  what a fuck..  this util will place the sentby to\nits correct location.  other example if you got 500 users and you delete 200 of\nthem  the sent.dat will stay ultralong..  but this util doesn''t let it be..  it\nmakes it also shorter!...\n\nso  as  i  mentioned..   this tool will also cut the sent.dat down and sort all\nusers to their right places!\n\nhere an example what sentcleaner is able to do:\n\nisnt  it  a  fuck that users seem not be able to create a sentby with autosent?\nyeah  it often is and you sysop get nerved because the user is to stupid to use\nautosent..   this  tool is able to create custom sentbys for all users.  and is\nalso able to remove them again\n\nhow does it work!\n\nok  well  you  can  run  this  tool in shell and use it normaly, or you can run\nudclean first and after this imediately run this util to clean up your sent.dat\nyou are also able to put this into the button funktion of amiexpress if this is\nwhat you want (hehe i did it myself) then put this lines in your acp icon.  you\nare also able to run this tool in workbench mode!  just click on its icon.\n\n(-----------------------------------)\nBUTTON_NAME.x=SentClean\nBUTTON_COMMAND.x=Run >Nil: Doors:FileId/SentCleaner\n(-----------------------------------)\n\nmenu usage:\n\n	1 = Clean Up ''Sent.Dat'' Normaly\n\nif  you  use this option it will clean up your sent.dat to an actual length and\nwill  position all created sentbys correctly if you deletd lot of users it will\nalso cut the sent.dat down.\n\n	2 = Clean Up ''Sent.Dat'' And Add Custom Sentby For Missing Sentby\n\nthis  is  same as above but add custom sentbys for users..  this will look like\nthis continue reading you find an option where you can choose different layouts\nfor  sentbys.  this option will add the user name as sentby with a choosen line\nfor example\n\n                 (-- GALAXY ----------------------------)\n\nthis  is  an  example  instead  galaxy  there will be put every user who has no\nsentby..   all  users  who made a sentby will keep their (you see a intelligent\noption hehehe)\n\n	3 = Clean Up ''Sent.Dat'' And Remove Custom Sentby\n\nok  this  option  is  the  same  as  the first option.  if you also made custom\nsentbys this option will remove them but it only removes the custom sentbys all\nother sentbys which are not made customly will stay..  (intelligent eh?)\n\n	4 = Show Current Custon Sentby\n\nthis  option  let you see the actual sentby in memory you can define other look\nlike  sentbys  if  you  want..  this must be in the tooltypes of the icon which\nshould be in doors:fileid/ and called sentcleaner.info\n\nif no icon is present it takes the default sentby in memory.\n\n        5 = Get Next Custom Sentby\n\nwith  this option you can choose one of the sentby defaults which where located\nin the icon.  if no icon is present this option has no use.\n\n	Q = Quit\n\nthis option speaks for itself!\n\n	L = Toggle Log On/Off\n\npress  L once and a log will be opened good if you want to check all your users\nwith  type or ppmore so you can watch all actions closer because this util runs\nfast and you probably can''t see everything right because of the speed ;)\n\nhere an example how an icon looks like\n\nTOOLTYPES:\n\nLINES=xxx        (xxx = number of lines)\nSENTBY.x=yyy     (x = number of sentby, yyy = sentbyline\n\nEXAMPLE:\n\nLINES=2\nSENTBY.1=(-------------------------------------------)\nSENTBY.2=(===========================================)\n\nso thats all folx hope you enjoy this util soon more options!\n\nsigned galaxy...\n\n  .-- ----- - ------ - --/\-_--/\_--/\- /\-_--/\-_--/\__-- ----- - ------ -.\n  |  ...........        /  /¬\/  / /  \/\ /¬\/  /¬\/   ¬\                  |\n  | ...mAnAgEr...      /  /  /   \/\  /     /\ /  /\ \  /  cALL FoR fUn!   |\n  !  ..gALaXy!..      /  /  /    /  \/  / \/  \  /  \ \/   -^-[NODE0]-^-   !\n  :   .........      /  /  /    /   /  /  /   / /   / /  +49-(o)4488-eL¡Te :\n  ·   cOmAnAgEr     /  /  /    /   /  /  /   / /   / /     -^-[NODE1]-^-   ·\n  °   ..gHosT..    /  ·  /    /   /  /  /   / /   / /    +49-(o)4488-eL¡Te °\n  ·                \__  /\_  /\  /\_/  /\__· /\__· /|      -^-[NODE2]-^-   ·\n  :  .aM¡Ga, pC.    | \/  |\/  \/   |\/ |  \/  | \/ !    +49-(o)4488-iSdN! :\n  ¡ .cOdErcOnFs!.   !     !     |   :   !  !   !    ·      -^-[NODE3]-^-   ¡\n  |                 °     :     :   °   :  °   °    °    +49-(o)4488-iSdN! |\n  |- --- --- -- --------- °---- °- ---- °----- ---- -- ---- - - ------- - -|\n  |rUnnIn` oN uN¡X-aM¡EeXpReSs 3.²o ^ 32o mEgS oNL¡Ne ^ o-3 dAyZ oLD ^ NuP!|\n  |  [-cIceRo-] ! cETErAm cEnSEo, cArTHaG¿NeM EssE deLeNdAm ! [-cIceRo-]   |\n  `-------------------------------------------------------------------[cJ!]´\n\n','\n',char(10)),NULL,'auto-added',8733,2,0,NULL,NULL,'sclean17','scan',1780048719);
