INSERT INTO door_catalog VALUES('scx_adm','SCX-ADM.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SCX-ADM.LHA','Scx-AdiMenu','XIM','__/\__/\______:_____/\_____/\___/\__ /\__',NULL,'s!x','SCX','/\  ___  .____/. __  . \___ _ \ __/  Y   / /  \  \   |_/   |  \  |  \  ___/__/\_ . _/ /_____ /_____\ _____/_____/_ /____  /__!_ \',replace('   __/\__/\______:_____/\_____/\___/\__ /\__\n  /\  ___  .____/. __  . \___ _ \ __/  Y   /\n /  \  \   |_/   |  \  |  \  ___/__/\_ . _/\n/_____ /_____\ _____/_____/_ /____  /__!_ \ \n|----\/-------\/-----------\/-----\/---f!\/|\n|    I·S  P·R·O·U·D  T·O  P·R·E·S·E·N·T    |\n|  - Scx-AdiMenu V1.1 by s!x of Scoopex -  |\n|    - ASM XIM Door for maximum speed -    |\n|- Lets you handle Textfile like commands -|\n|- Update to 5D-AdiMenu by [tHE aDDiCT!]  -|\n`----- SCOOPEX -÷- GENERATIONS AHEAD! -----''\n','\n',char(10)),'Scx-AdiMenu.guide',replace('@database "Scoopex - AdiMenu 1.1"\n@author "s!x of Scoopex"\n@node Main "--> Scx-AdiMenu 1.1 by s!x of Scoopex <--"\n.....................................................................\n                                                 .::::::::::::::::::::.\n                                               .::::::::::::::::::::::::.\n  ___________________________________________________________________¦_____\n  \    __________     /\____    \_/\____    \_______    /\________   |    /\n  /\____  \/   l/____/_   l/     /    l/     /  _______/  ___/___\_  _  _/:. \n /     /   \_  /      /   /     /     /     /     /   /   \      /   |   \::\n/___________/________/_________/___________/_____/  _/__________/____|    \''\n                                             ::::::/-Mo:::::::::::::¦_____\\n               -÷- SCOOPEX - GENERATIONS AHEAD -÷-:::::::::::::::::::::::''\n                                                `::::::::::::::::::::·::''\n                    S·C·O·O·P·E·X   P·R·E·S·E·N·T·Z\n\n                       ---> Scx-AdiMenu 1.1 <---\n                           by s!x of Scoopex\n                      .---- -- - --- -- -- -- - .\n                      : @{"----> What is it? <----" Link What} |\n                      . @{"---> Installation! <---" Link Inst} :\n                      | @{"---> How 2 contact <---" Link Cont} .\n                      `- --- -- ---- -- ----- --''\n@endnode\n@node What "----> What is it? <----"\n  It''s a simple programm, orginally written by [tHE aDDiCT!] in C, but it''s\n                               real cool!\n   You can define Textfiles like commands with Accesslevels and Multi- or\n   Single-command options like in normal doors! The Door reads the command\n      line and it show''s a textfile with the same name located in\n  "Doors:Scx-AdiMenu/Text/" ... i decided to keep the name "AdiMenu" because\n  the idea came from [tHE aDDiCT!] and not from me and this should not be an\n     "Adi-Menu-clone"! It''s only an updated, optimized and much shorter\n    (his was 16k, mine is only 540 Bytes long) Version of this cool Door!\n@endnode\n@node Inst "---> Installation! <---"\n   It''s very easy, if you wanna show a textfile you just make an Icon in\n   "BBS:Commands/BBSCmd" with the name of the Command wich shall show the\n  Textfile! As location you put in "Doors:Scx-AdiMenu/Scx-AdiMenu" and as\n     Stack 4096 .. then you put a textfile called like the command in\n                        "Doors:Scx-AdiMenu/Text/"!\n    Now, every time you start the command the Textfile will be shown, it''s\n    very useful for Doormenu''s or Sysopmenu''s because you can specify the\n Accesslevel! I''ve included 3 Textfile of [tHE aDDiCT!] so you can see how\n              it works! Have Phun with this cool Door!\n@endnode\n@node Cont "---> How 2 contact <---"\nIf you have good suggestions for updates or found a bug (i think there can''t\n   be any, the Door is only 540 Bytes long) or want a Version with changed\n  colors (not needed, it''s only one line from the Door itself) then contact\n                             me if you can!\n@endnode\n','\n',char(10)),NULL,NULL,12846,5,0,NULL,NULL,'scx_adm_scx_adimenu','scan',1780048719);
INSERT INTO door_catalog VALUES('scx_fw10','SCX-FW10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SCX-FW10.LHA','SCX-FRONTWHO','XIM','__/\__/\______:_____/\_____/\___/\__ /\__',NULL,'Joe','SCX','/\  ___  .____/. __  . \___ _ \ __/  Y   / /  \  \   |_/   |  \  |  \  ___/__/\_ . _/ /_____ /_____\ _____/_____/_ /____  /__!_ \',replace('   __/\__/\______:_____/\_____/\___/\__ /\__\n  /\  ___  .____/. __  . \___ _ \ __/  Y   /\n /  \  \   |_/   |  \  |  \  ___/__/\_ . _/\n/_____ /_____\ _____/_____/_ /____  /__!_ \\n·----\/-------\/-----------\/-----\/---f!\/·\n|           IS PROUD TO PRESENT:           |\n|  FRONTWHO 1.0 BY Joe Cool OF SCOOPEX /X  |\n|    - Every cool Board should run it! -   |\n`----÷[ SCOOPEX -÷- GENERATIONS AHEAD]-÷---''','\n',char(10)),'scx-frontwho.guide',replace('@database "Scoopex /X - Scx-FRONTWHO 1.0"\n@author "Joe Cool of Scoopex /X"\n@node Main "Scx-FrontWHO by Joe Cool of Scoopex /X"\n __________ __ __ _  :                      _________                .\n/    ______ .__________  ________  ________ \_____   \_______________:_____\n\_____    \ |    _____/_/   __   \/   __   \|¬  ____/  ____    /\_   |   _/\n|¬   |     \|    \|    /    \/   /    \/    |     | |  ¬|_____/ /¬   _   ¬\\nl__________/l__________\_________\__________l_____| l__________/     |_____\\n                                                              /      |-cR\n    @{"(« s·C·O·O·P·E·x   e·X·P·R·E·S·s   d·I·V·i·S·i·O·n »)" Link SCX}   /_______|\n\n                                p·R·E·S·E·N·T·s\n\n                           .- -  - ---- - -- - -- ---.\n                           |     Scx-FrontWHO V1.0   |\n                           `--- - - ---- - --- - -- -''\n\n                            by Joe Cool of Scoopex /X\n\n                                @{"Main Documentation" Link Docu}\n@endnode\n@node Docu "Documentation of Scx-FrontWHO"\n\n                               Scx-FrontWHO V 1.0\n                         .- - -  ---- - -- - --- -  -.\n                    