INSERT INTO door_catalog VALUES('sdc_r4b3','SDC_R4B3.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SDC_R4B3.LHA',NULL,'XIM','Super-DupeCheck - Release 4, *BETA 3*.','1.03','Pot-Noodle/G''G/ATX]','SDC','-------------------------------------------- It doesn''t look like it''ll ever get finished so here''s the beta. Source-code can be found',replace('Super-DupeCheck v1.03 - Release 4, *BETA 3*.\n--------------------------------------------\nIt doesn''t look like it''ll ever get finished\nso here''s the beta. Source-code can be found\nin another archive.  [By Pot-Noodle/G''G/ATX]\n','\n',char(10)),'SDC_R4B3.readme',replace('Short:    Super-DupeCheck 1.03: Release 4, Beta 3\nUploader: Leo Davidson <[email removed]>\nAuthor:   Leo Davidson <[email removed]>\nType:     comm/amiex\n\nSuper-DupeCheck v1.03 [RELEASE 4 BETA 3]\nWritten by Leo Davidson (aka Pot-Noodle)\n\nSuper-DupeCheck is a DupeChecker for AmiExpress. Chances are that if\nyou run AmiExpress BBS software, you''ve probably heard of it already,\nand if not you''ll have heard of Super-AmiLog, which I also wrote.\n\nThis beta version has been around for ages and I just don''t have the\nmotivation to finish it off, so I thought I should just release it now,\nas it does have some extra features not in the last release (from ages\nago).\n\nI am also releasing the source code for this, Super-AmiLog3-beta, and\nperhaps some other of my BBS-utils, in case anyone out there would like\nto continue updating them or just needs to see how something is done.\n\n	Leo, 30-Aug-1995.\n','\n',char(10)),NULL,NULL,73292,1,0,NULL,NULL,NULL,'scan',1780048728);
INSERT INTO door_catalog VALUES('sdm_ct1o','SDM!CT1O.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SDM!CT1O.LHA',NULL,'XIM','Sdm!ChatTopEnd.exe',NULL,'Shallow/Sodium','SDM','/  //___\\_  \___\\ _/_(_// _\_    /_\\\__ \_     /  /   /   _/  (_  (_  /   / \   \ \ _/    /      /\   \    /   / /   /  /    \ \',replace(' ___     ____     ____  __   _______  _\n/  //___\\_  \___\\ _/_(_// _\_    /_\\\__\n\_     /  /   /   _/  (_  (_  /   / \   \ \\n_/    /      /\   \    /   / /   /  /    \ \\n\_____\ _____\/____\ _/___/______\_/_____/_/\n[«·Sodium Amiexpress Inspiration Presents·»]\n.------------------------------------------.\n| · Sdm!ChatTop v1.o  -  Last 1o Chatter · |\n| Displays user last chat & total chattime |\n| 9 nice random header files / cool design |\n|    Copyright © 1999 by Shallow/Sodium    |\n`-diP/a!-----------------[13.11.1999]-[o5]-''\n\n','\n',char(10)),'Sdm!ChatTop.doc',replace('\n\n\n\n\n                           ______\n             ______________\    /_____________\n           _)\              \  /             /(_\n     _____ |     diP/a!      \/   _____        |      _______\n    _)   //______   ______ ______\\  _/__    __  _____\_     \    __\n  __\_____      /__\\_    \_       _/   (_ _(_//_      /     /_ _\\ \___\n  \      /     /     /     /       \     /      (_    /     /   \    \  \\n  /    _/     /     /     /\        \   /        /   /     /    /     \  \\n /____________\          / /________/___\       /__________\   /       \  \\n           _ ____________\           _ _________\       _ ____/________/__/\n           .                                   .\n           | · Sodium Amiexpress Inspiration · |\n           |                                   |\n           |          p r e s e n t s          |\n           |                                   |\n           |     [«· Sdm!ChatTop  v1.o ·»]     |\n          _|_  _                           _  _|_\n           ·/-//---------------------------\\-\·\n\n\n\n\n\n\n                                 _____ _____\n                               __)  _/ \_  (__\n                              \\___ \ · / ___//\n                                 |   \ /   |\n                 . .. .......... |    /   .| .......... .. .\n                                 |        :|\n                                 |        .|\n                                 |         |\n                                 |         |\n                         · i n t r o d u c t i o n ·\n                                 |         |\n                                 |         |\n                                 |         |\n                                 |         |\n  _     ___    __   ____  ____    _____  ______       __   _   ____   ___\n (//_ _\\_ \_ / //_\\_ /_\\_  \__\\  _/_ \_   /_ ___ / //_(//_\\_  \_\\_ \_\n/   (_   /  //   _/ _/  /  /   /   _/  /  /  / _/  (_   _/   (_ /   /  /  /\n\    /  /   \    \  \   \_    /    \  /  /  /  \    /   \     /    /  /   \\n \___\ _\____\ ___\ _\___/____\\____\_\_____\ __\__/_____\ ___\ ___\ _\____\\n«--diP/a!------------------------------------------------------------------»\n\n\n         First, sorry for the short doc/guide but i hate doc/guide writing.\n\n              I bet you have seen a Top Chatter tool before. Sure you have!\n                              But why then use mine and not all the others?\n    Well, go ahead and use the others, but please keep these things in mind\n                                                  about my Sdm!ChatTop tool\n\n                                               Shows last chat with sysop -\n                                              Shows total chat statistics -\n                                           Shows total chattime from user -\n                                                      Shows random header -\n                                                      Add your own header -\n                                                       1oo% backdoor free -\n                                                          1oo% virus free -\n                                    It''s fast (written 100% in arexx!) :) -\n                                             It''s easy to use and Install -\n\n            This program is not shareware, not buyware, it''s Public Domain.  \n                           This means you can spread is to all your friends\n                                      and everybody else you possibly know!\n\n\n«--------------------------------------------------------------------------»\n                                 |        :|\n                                 |        .|\n                                 |         |\n                                 |         |\n                                 |         |\n                            · c o p y r i g h t ·\n                                 |         |\n                                 |         |\n                                 |         |\n                                 |         |\n            ____     ___ _ __      _____     _    _____        .___. ___\n   ___ _____\\_  \_ _/  (_   /____ \\_  /__ _(//_ \\ __/____ _.|   |/  //_\n  _) _/    /  /   / \    /  //   /  _/    /     (_   \_    /  ||   |    _/\n  \  \    /      /   \__/  //   /   \     \_     /    /   /   ||   |    \\n  /___\__/_______\ ____\ _    __\ ___\_____/_____\ _______\ __||   |_____\\n«-------------------------\___\-----------------------------diP|___|a!-----»\n\n\n                 Code, layout and doc of Sdm!ChatTop v1.o by Shallow/Sodium\n             All this fine (doc) and File_id.diz ansis done by diPSWiTCH/A!\n                     Packed with RexxCompile V1.2 - Code by Sunbeam/Shelter\n                                            other header ascii''s done by...\n                Mo! - [fL] - sox - .Mt - dNo - -rLF - sdn/ed - [hKWd] - yop\n\n                        If you find any errors or have any ideas for making\n                    this program better, please drop me a message or email.\n\n\n«--------------------------------------------------------------------------»\n                                 |        :|\n                                 |        .|\n                                 |         |\n                                 |         |\n                                 |         |\n                             · r e q u i r e s ·\n                                 |         |\n                                 |         |\n                                 |         |\n                                 |         |\n     _____    ____       _____    ________  _     _____    ____     ___\n   _\\_  /__ /   /___ __\\_   \_ _\_     /_(//_ _\\_  /__ /   /___ /  //____\n  _) _/    /    _/  (_    /    /   /    /     (_  _/    /    _/  (_\__     /\n  \  \     \_   \    /        /   /    /       /  \     \_   \    /  /    /\n  /___\_____/____\__/___\    _\ _______\ ______\ __\_____/____\__/________\\n«---------------------diP\___\a!-------------------------------------------»\n\n\n                                                 Amiga 68ooo+ (or better) -\n                                                     Os 2.o4+ (or higher) -\n                                            Running Amiexpress Bbs System -\n                                                        Running RexxMast! -\n\n                                                      Rexxsupport.library -\n                                                       Rexxtricks.library -\n\n\n«--------------------------------------------------------------------------»\n                                 |        :|\n                                 |        .|\n                                 |         |\n                                 |         |\n                                 |         |\n                              · i n s t a l l ·\n                                 |         |\n                                 |         |\n                                 |         |\n                                 |         |\n           __     _____    ___        ____     _____    ___    ___\n         _(_//_ _\\_   \_ /  //_____ /   //_ _\\_   \_ /  /_ _/  /\n        /     (_   /    / \___     //     _/    /    /  _/___  _/___\n«------ \      /  /     \   _/    /       \    _    /   \    \ \    \ -----»\n     diP \_____\ _\______\ _______\ _______\ __\____\ _______/______/ a!\n\n\n                                      Copy the `Sodium'' dawer to BBS:DOORS/\n              Copy the `Sdm!ChatTopStart.info'' icon to BBS:COMMANDS/BBSCMD/\n                Copy the `Sdm!ChatTopEnd.info'' icon to BBS:COMMANDS/BBSCMD/\n\n    Add the following line to all your Bbs:Node<×>/StartChat.txt scrips ...\n                             ----------------------------------------------\n                             ~CC_Sdm!ChatTopStart|\n                             ----------------------------------------------\n\n      Add the following line to all your Bbs:Node<×>/EndChat.txt scrips ...\n                             ----------------------------------------------\n                             ~CC_Sdm!ChatTopEnd|\n                             ----------------------------------------------\n\n                                     or copy the includet to the directorys\n\n\n                     Run Sdm!ChatTopCfg.Exe to edit the configurations file\n\n\n                                                     Thats all... easy hä!?\n\n\n«--------------------------------------------------------------------------»\n                                 |        :|\n                                 |        .|\n                                 |         |\n                                 |         |\n                                 |         |\n                              · h i s t o r y ·\n                                 |         |\n                                 |         |\n                                 |         |\n                                 |         |\n          .____.  __    ___        ____     _____     _____ _ _____\n     .___.|    |_(_//_ /  //_____ /   //_ _\\_   \_ _\\_  /__     /____\n     |   ||    |     (_\___     //     _/    /    /   _/    /    //   /\n«--- |   ||    |      /  _/    /       \         /    \     \_  //   / ----»\n diP |___||    |\_____\ _______\ _______\ _______\ ____\_____/__    _\ a!\n          |____|                                              \n\n\n                                        Sdm!ChatTop v1.o - My first release\n\n\n«--------------------------------------------------------------------------»\n                                 |        :|\n                                 |        .|\n                                 |         |\n                                 |         |\n                                 |         |\n                               · f u t u r e ·\n                                 |         |\n                                 |         |\n                                 |         |\n                                 |         |\n               _______  ________ ____     ________  _____    ____\n           _ _/      /__\_     //   //_ __\_     /_\\_  /__ /   /_____\n          /  \     _/    /    //     _/    /    /   _/    /    _/    /\n«-------- \   \____\    /    /       \    /    /    \     \_   \    / -----»\n       diP \_____\ __________\ _______\ _______\ ____\_____/____\__/ a!\n\n\n                                                             Fame release -\n\n\n«--------------------------------------------------------------------------»\n                                 |        :|\n                                 |        .|\n                                 |         |\n                                 |         |\n                                 |         |\n                            · g r e e t i n g s ·\n                                 |         |\n                                 |         |\n                                 |         |\n                                 |         |\n  _____    ____    ___       ___       ___    __    ____   _____     ___\n_\\ __/___\\_ /__ /  /_____ /  /_____ /  //_ (_//_ \\_  \_\\ __/___ /  //___\n\   \_   / _/   /   _/    //  _/    //    _/     (_  /   /   \_   / \_     /\n/    /  /  \    \_  \    /    \    /      \       / /    \    /  /  _/    /\n\_______\ __\____/___\__/______\__/ _______\ ____/__\_____\ _____\ _______\\n«--diP/a!------------------------------------------------------------------»\n\n\n        I would like to thank the following for their support/friendship...\n\n   · Inferno · Lance! · Flash/Cb4! · Ghandy · Slapshot · Fli7e · Jim^Beam ·\n     · Stimpy · Fletcher · Soulmaster · Kosjer D · Digiman · Sivle · Exon · \n      · Clairvoyant · Vampire · The Dentist · SunBeam · Dipswitch · Zaner ·\n      · Derrow · Rasterbalster · Diabolo · [-rKr-] · Darkstorm · Slapshot ·\n\n                                           ... and all in my dream land ...\n\n                     \n                                                  message to all sysops ...\n                 STOP adding GIF/IFF/JPEG & EXE files in Lha & Lzx archives\n\n\n«--------------------------------------------------------------------------»\n                                 |        :|\n                                 |        .|\n                                 |         |\n                                 |         |\n                                 |         |\n                              · c o n t a c t ·\n                                 |         |\n                                 |         |\n                                 |         |\n                                 |         |\n                     ____     ____    ____     ____             ____\n          ___ ____ _\\_  \_ _\\_  \_ /   //_ _\\_  \_ __ ____  /   //_\n         /  _/   (_   /   /    /   //     _/    /   /  _/   (_      _/\n«------- \  \     /      /    /    \      \    _   /   \     /      \ -----»\n      diP \__\___/_______\ ___\_____\ _____\ __\___\ ___\___/ _______\ a!\n\n\n                         You can contact me on the following bbs systems...\n\n                                                               Dream Land -\n                                                                 The Yard -\n                                                                Acid Slam -\n                                                              Last Legend -\n                                                               Liberation -\n                                                              Thunderdoom -\n                                                                Los Endos -\n                                                             King''s Crown -\n                                                                Boondocks -\n                                                                      Tnt -\n\n\n                                             or you can contact me at email\n\n                                                             [email removed]\n\n\n«--------------------------------------------------------------------------»\n                                 |         |\n                                 |         |\n                                 |         |\n                                 |         |\n                                 |         |\n                                 |         |\n                                 |    _    |\n                                 |_   |   _|\n                                 :/ __!__ \:\n                                 /__\ : /__\\n                                     \ /\n                                      \\n\n                               · S O D I U M ·\n','\n',char(10)),NULL,'auto-added',46157,7,0,NULL,NULL,'sdm_ct1o','scan',1780048728);
INSERT INTO door_catalog VALUES('sdm_gn1o','SDM!GN1O.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SDM!GN1O.LHA',NULL,'XIM','Sdm!GuyNews.Exe',NULL,'Shallow/Sodium','SDM','/  //___\\_  \___\\ _/_(_// _\_    /_\\\__ \_     /  /   /   _/  (_  (_  /   / \   \ \ _/    /      /\   \    /   / /   /  /    \ \',replace(' ___     ____     ____  __   _______  _\n/  //___\\_  \___\\ _/_(_// _\_    /_\\\__\n\_     /  /   /   _/  (_  (_  /   / \   \ \\n_/    /      /\   \    /   / /   /  /    \ \\n\_____\ _____\/____\ _/___/______\_/_____/_/\n[«·Sodium Amiexpress Inspiration Presents·»]\n.------------------------------------------.\n| · Sdm!GuyNews v1.o - Newuser Info Door · |\n|  Sends Eall msg to user''s / Easy to use  |\n|   Nice design and very easy to install   |\n|  Copyright ©1997-1999 by Shallow/Sodium  |\n`-diP/a!-----------------[18.1o.1999]-[o1]-''\n','\n',char(10)),'Sdm!GuyNews.Doc',replace('\n\n\n\n\n                           ______\n             ______________\    /_____________\n           _)\              \  /             /(_\n     _____ |     diP/a!      \/   _____        |      _______\n    _)   //______   ______ ______\\  _/__    __  _____\_     \    __\n  __\_____      /__\\_    \_       _/   (_ _(_//_      /     /_ _\\ \___\n  \      /     /     /     /       \     /      (_    /     /   \    \  \\n  /    _/     /     /     /\        \   /        /   /     /    /     \  \\n /____________\          / /________/___\       /__________\   /       \  \\n           _ ____________\           _ _________\       _ ____/________/__/\n           .                                   .\n           | · Sodium Amiexpress Inspiration · |\n           |                                   |\n           |          p r e s e n t s          |\n           |                                   |\n           |     [«· Sdm!GuyNews  v1.o ·»]     |\n          _|_  _                           _  _|_\n           ·/-//---------------------------\\-\·\n\n\n\n\n\n\n                                 _____ _____\n                               __)  _/ \_  (__\n                              \\___ \ · / ___//\n                                 |   \ /   |\n                 . .. .......... |    /   .| .......... .. .\n                                 |        :|\n                                 |        .|\n                                 |         |\n                                 |         |\n                         · i n t r o d u c t i o n ·\n                                 |         |\n                                 |         |\n                                 |         |\n                                 |         |\n  _     ___    __   ____  ____    _____  ______       __   _   ____   ___\n (//_ _\\_ \_ / //_\\_ /_\\_  \__\\  _/_ \_   /_ ___ / //_(//_\\_  \_\\_ \_\n/   (_   /  //   _/ _/  /  /   /   _/  /  /  / _/  (_   _/   (_ /   /  /  /\n\    /  /   \    \  \   \_    /    \  /  /  /  \    /   \     /    /  /   \\n \___\ _\____\ ___\ _\___/____\\____\_\_____\ __\__/_____\ ___\ ___\ _\____\\n«--diP/a!------------------------------------------------------------------»\n\n\n         First, sorry for the short doc/guide but i hate doc/guide writing.\n\n                  I bet you have seen a GuyNews tool before. Sure you have!\n                              But why then use mine and not all the others?\n    Well, go ahead and use the others, but please keep these things in mind\n                                                  about my Sdm!GuyNews tool\n\n                                                       1oo% backdoor free -\n                                                          1oo% virus free -\n                                    It''s fast (written 100% in arexx!) :) -\n                                             It''s easy to use and Install -\n\n            This program is not shareware, not buyware, it''s Public Domain.  \n                           This means you can spread is to all your friends\n                                      and everybody else you possibly know!\n\n\n«--------------------------------------------------------------------------»\n                                 |        :|\n                                 |        .|\n                                 |         |\n                                 |         |\n                                 |         |\n                            · c o p y r i g h t ·\n                                 |         |\n                                 |         |\n                                 |         |\n                                 |         |\n            ____     ___ _ __      _____     _    _____        .___. ___\n   ___ _____\\_  \_ _/  (_   /____ \\_  /__ _(//_ \\ __/____ _.|   |/  //_\n  _) _/    /  /   / \    /  //   /  _/    /     (_   \_    /  ||   |    _/\n  \  \    /      /   \__/  //   /   \     \_     /    /   /   ||   |    \\n  /___\__/_______\ ____\ _    __\ ___\_____/_____\ _______\ __||   |_____\\n«-------------------------\___\-----------------------------diP|___|a!-----»\n\n\n                 Code, layout and doc of Sdm!GuyNews v1.o by Shallow/Sodium\n                                 All this fine ascii''s done by diPSWiTCH/A!\n                     Packed with RexxCompile V1.2 - Code by Sunbeam/Shelter\n                 Ascii in Sdm!GuyNews.Ascii & Sdm!GuyNews.Msg done by Mogue\n\n                        If you find any errors or have any ideas for making\n                    this program better, please drop me a message or email.\n\n\n«--------------------------------------------------------------------------»\n                                 |        :|\n                                 |        .|\n                                 |         |\n                                 |         |\n                                 |         |\n                             · r e q u i r e s ·\n                                 |         |\n                                 |         |\n                                 |         |\n                                 |         |\n     _____    ____       _____    ________  _     _____    ____     ___\n   _\\_  /__ /   /___ __\\_   \_ _\_     /_(//_ _\\_  /__ /   /___ /  //____\n  _) _/    /    _/  (_    /    /   /    /     (_  _/    /    _/  (_\__     /\n  \  \     \_   \    /        /   /    /       /  \     \_   \    /  /    /\n  /___\_____/____\__/___\    _\ _______\ ______\ __\_____/____\__/________\\n«---------------------diP\___\a!-------------------------------------------»\n\n\n                                                 Amiga 68ooo+ (or better) -\n                                                     Os 2.o4+ (or higher) -\n                                            Running Amiexpress Bbs System -\n                                                        Running RexxMast! -\n\n                                                      Rexxsupport.library -\n                                                       Rexxtricks.library -\n                                                        Rexxextra.library -\n\n\n«--------------------------------------------------------------------------»\n                                 |        :|\n                                 |        .|\n                                 |         |\n                                 |         |\n                                 |         |\n                              · i n s t a l l ·\n                                 |         |\n                                 |         |\n                                 |         |\n                                 |         |\n           __     _____    ___        ____     _____    ___    ___\n         _(_//_ _\\_   \_ /  //_____ /   //_ _\\_   \_ /  /_ _/  /\n        /     (_   /    / \___     //     _/    /    /  _/___  _/___\n«------ \      /  /     \   _/    /       \    _    /   \    \ \    \ -----»\n     diP \_____\ _\______\ _______\ _______\ __\____\ _______/______/ a!\n\n\n                                      Copy the `Sodium'' dawer to BBS:DOORS/\n                         Copy the Joined.Txt to all BBS:NODE<×>/ directorys\n                          If allready exists then add the following line...\n\n                                                        ~f|~CC_Sdm!GuyNews|\n\n                                          (the best way to start this door)\n\n                     Run Sdm!GuyNewsCfg.Exe to edit the configurations file\n                         You can replace your own ascii (Sdm!GuyNews.Ascii)\n                                         and massage text (Sdm!GuyNews.Msg)\n\n                                       String''s inside Sdm!GuyNews.Ascii...\n\n                                                              Username - %u\n                                                    Location from User - %l\n                                                                  Time - %t\n                                                                  Date - %d\n                                                            Sysop name - %m\n                                                            witch Node - %s\n\n\n                                                     Thats all... easy hä!?\n\n\n«--------------------------------------------------------------------------»\n                                 |        :|\n                                 |        .|\n                                 |         |\n                                 |         |\n                                 |         |\n                              · h i s t o r y ·\n                                 |         |\n                                 |         |\n                                 |         |\n                                 |         |\n          .____.  __    ___        ____     _____     _____ _ _____\n     .___.|    |_(_//_ /  //_____ /   //_ _\\_   \_ _\\_  /__     /____\n     |   ||    |     (_\___     //     _/    /    /   _/    /    //   /\n«--- |   ||  