INSERT INTO door_catalog VALUES('server10','SERVER10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SERVER10.LHA','testserv','XIM','testserv','1.0',NULL,NULL,NULL,replace('ServerPort v1.0 - Messager for /X\n','\n',char(10)),'server10.readme',replace('Short: ServerPort v1.0 - Messager for /X\nAuthor: Kaare Johansen ([email removed])\nUploader: Kaare Johansen ([email removed])\nType: Dev/e\n\nWith these E modules, you can send commands to AmiExpress and magic\nthings will happend. You can go into chat mode from CLI or where ever\nyou are on the system, no need to access AmiExpress to go in chat-mode\nfor example.. Here are some usage examples how this is done:\n\nopen:=serverPort(''AEServer.0'',SV_CHAT)     - Enter chat-mode on node 0\nopen:=serverPort(''AEServer.0'',SV_SYSOPLOG) - SysOp login at node 0\nopen:=serverPort(''AEServer.1'',SV_SYSOPLOG) - SysOp login at node 1\n\n..... And so on ! :).... \n\nThanks to Splash/Megastyle for the ASM-routine... :)\n\nEnjoy these EModules E coders  !:)\n\n ----------------------------------------------------------------------------\n If anyone wants to contact me, write an EMAIL to:\n\n ->*<- [email removed] ->*<-\n\n Or Call my board on:\n\n +47-7847-1042\n\n Best regards,\n Dr. Ice/lISENCE\n\n','\n',char(10)),NULL,'auto-added',4299,3,0,NULL,NULL,'server10','scan',1780048728);
