INSERT INTO door_catalog VALUES('shd_pa10','SHD-PA10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SHD-PA10.LHA','Pager','XIM','Pager',NULL,'tROUBLE/sHD','SHD','_) _____) \_ \_) ___\_) _  \_)  __\_e! \____  \  __  \   _/ \  ¬\  \    __/_ ¬\  \_ ¬\  \_ \   \_  \  \_  \',replace('    ____ _ _____  _____  _____  _____\n   _) _____) \_ \_) ___\_) _  \_)  __\_e!\n   \____  \  __  \   _/ \  ¬\  \    __/_\n       ¬\  \_ ¬\  \_ \   \_  \  \_  \\n   - _ _________\_____\______________ _ -\n--------------------------------------------\n  bACKGrOUND-pAGER  v1.O - bY tROUBLE/sHD\n  tHIS iS  tHE pAGER oF tOMOROW!! pAGE dA\n  sYSOP iN dA bACK wHEN dA uSER iS oNLINE\n  wRITTEN iN 1OO pROCENT 68OOO aSSEMBLER!\n--------------------------------------------\n','\n',char(10)),'Pager.Guide',replace('@database "Background-Pager v1.O"\n@remark $Ver: v1.O - 19.O9.94\n\n@node "MAIN" "tROUbLE!/sHAdE pRESENTS...."\n   ___    _:_    ___    ___    ___\n _/ , \ _/ |°\ _/  °\ _/ _°\ _/ , \\n \_ \_/ \  |  \\  |  \\  |  \\  \_/\n /°\  \ /  _  //  _  //  |  //  /°\\n \  __/ \__|_/ \__|_/ \____/ \__  / Background-Pager v1.O - By Trouble/Shade\n--\/------·:-----·:·----:¦·[VSB]\/------------------------------------------\n\n                              @{" Introduction " link int}\n                              @{" Requirements " link req}\n                              @{" Installation " link ins}\n                              @{"     Usage    " link usa}\n                              @{"  Suggestion  " link bus}\n                              @{"    History   " link his}\n                              @{"   Greetings  " link gre}\n                              @{"  Contact Me  " link con}\n\n                      Amigaguide Design - By Bandit/Shade\n@endnode\n\n@node INT "Introduction"\n\n   Ok, this door is a Background-Pager, meaning that the SySop is paged\n   in the background while the user can continue using the system util \n   the sysop answers. So now you don''t have to wait for that anoying\n   . . . . . . and waiting for the sysop to enter the chat.\n@endnode\n\n@node REQ "Requirements"\n\nRequirements to run this door:\n\n       - Ami-Express v3.xx or v4.xx (Not tested with 1.x & 2.x)\n@endnode\n\n@node INS "Installation"\n\nYou should do the following things to run this door:\n\n   - Copy the Pager dir to doors:\n   - Copy the bbscmd dir to bbs:commands/\n   - Copy the AEDoor.library to libs:\n\n   That''s all...folks!\n@endnode\n\n@node USA "Usage"\n\n    All you have to do to use this util is to install it and type ''O'' at\n    the main prompt in /X. When someboddy is paging you, press enter in\n    the window to make it stop paging and go into the node to chat with\n    the dude on the line or press Node Chat and the node to chat with on\n    the ACP window....\n@endnode\n\n@node BUS "Bugs & Suggestions"\n\n   If you find a error or have suggestions to this door please let me know.\n   It''s best if YOU call MY board that way i get the report fastest...\n\n   Into Exile  +47-675-82545  -  A4OOO/O4O - USRobotics 16.8 Dual Standard\n@endnode\n\n@node HIS "History"\n\n   V1.O 19-O9-94 - First Release, 1OO% working (not?)\n@endnode\n\n@node GRE "Greetings"\n\n   Bandit/Shade      - You STILL have my 3OO,- kr for /X\n   Double/Duplo      - Eh what should i thank you for hmmm\n   Intercon/Indep.   - What are you coding now??\n@endnode\n\n@node CON "Contact Trouble/Shade"\n\n   To contact me, please call my board.....\n \n[««««««««««««««««««««««««]  i N T O  e X I L E  [»»»»»»»»»»»»»»»»»»»»»»»»]\n \n   _____  __________  _______ _  __________\n  _)   ¬\_)  __    ¬\_)   __    _)  __    ¬\\n  \      \     \     \     \__ _\     \     \\n   \      \_    \     \     \    \     \     \    nATIVE:\n    \____________\     \     \    \______     \\n                  \     \_____\          \_____\     tROUbLE!/sHADE\n                   \- - -\               _ ___\n        ___________ \     \_____    _____     \______  ___________\n       _)     ____¬\_\     \   ¬\_ _)   ¬\     \    ¬\_)     ____¬\_\n       \      ______/_\___      _/_\      \     \     \      ______/_ _\n        \     \_       \_    \      \_     \_    \_    \_    \_\n         \      _________     \__________________________      _______ _ -\n          \_____\        \_____\                       e!\_____\\n \n \n -- aM¡GA 4OOO - 68O4O pOWER - uSR 16.8 dS - 8 mEGS oF rAM - lATEST /X --\n \n        lOTS oF aMIX-uTILS fOR fREE dOWNLOAD!! - vOTEsITE fOR hYDRA\n\n              dA mAG¡C nUMBA iS: + 4 7 - 6 7 5 - 8 2 5 - 4 5\n \n[««««««««««««««««««««««««]  i N T O  e X I L E  [»»»»»»»»»»»»»»»»»»»»»»»»]\n@endnode\n','\n',char(10)),NULL,'auto-added',5821,2,0,NULL,NULL,'shd_pa10','scan',1780048728);
INSERT INTO door_catalog VALUES('shd_um10','SHD-UM10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SHD-UM10.LHA','UploadMover','XIM','UploadMover',NULL,'tROUBLE!/sHADE','SHD','_) _____) \_ \_) ___\_) _  \_)  __\_e! \____  \  __  \   _/ \  ¬\  \    __/_ ¬\  \_ ¬\  \_ \   \_  \  \_  \',replace('    ____ _ _____  _____  _____  _____       \n   _) _____) \_ \_) ___\_) _  \_)  __\_e!   \n   \____  \  __  \   _/ \  ¬\  \    __/_    \n       ¬\  \_ ¬\  \_ \   \_  \  \_  \       \n   - _ _________\_____\______________ _ -   \n--------------------------------------------\n    uPLOADMOVER v1.O - bY tROUBLE!/sHADE\n  uPLOAD yOUR fILES iN  aNY cONFERENCE yOU\n     lIKE aND tHEY wILL bE mOVED tO tHE \n    cORRECT cONFERENCE aFTER yOUR dONE!! \n \n          a mUST fOR aLL bOARDS!\n--------------------------------------------\n','\n',char(10)),'UploadMover.Guide',replace('@database "UploadMover v1.O"\n@remark $Ver: v1.O - 22.O9.94\n\n@node "MAIN" "tROUbLE!/sHAdE pRESENTS...."\n    ___    _:_    ___    ___    ___\n  _/ , \ _/ |°\ _/  °\ _/ _°\ _/ , \\n  \_ \_/ \  |  \\  |  \\  |  \\  \_/\n  /°\  \ /  _  //  _  //  |  //  /°\\n  \  __/ \__|_/ \__|_/ \____/ \__  / UploadMover v1.O - By Trouble/Shade\n --\/------·:-----·:·----:¦·[VSB]\/-----------------------------------------\n\n                              @{" Introduction " link int}\n                              @{" Requirements " link req}\n                              @{" Installation " link ins}\n                              @{"     Usage    " link usa}\n                              @{"  Suggestion  " link bus}\n                              @{"    History   " link his}\n                              @{"   Greetings  " link gre}\n                              @{"  Contact Me  " link con}\n\n                      Amigaguide Design - By Bandit/Shade\n@endnode\n\n@node INT "Introduction"\n\n   I got this idea from my friend (?!) Bandit. He wanted an util that could\n   sort all the files that a guy uploaded into diferent conferences!\n\n   ConfUploader is a small and VERY useful utility witch uses the great\n   AEDoor.library by SiNTAX/WøT. It allows you to upload in any conference \n   you want and then place the files in the conference where they belong.\n@endnode\n\n@node REQ "Requirements"\n\nRequirements to run this door:\n\n       - Ami-Express v3.x/v4.x (Not tested with v1.x/v2.x)\n@endnode\n\n@node INS "Installation"\n\nYou should do the following things to run this door:\n\n   - Copy the UploadMover dir to doors:\n   - Copy the syscmd dir to bbs:commands/\n   - Copy the AEDoor.library to libs:\n\n   If you allready have a icon named EXAMINE.info in your \n   BBS:COMMANDS/SYSCMD directory, be sure to rename MY EXAMINE.info to \n   EXAMINE1.info, EXAMINE2.info or EXAMINE3.info and so on, and so on.....\n   It is very important that you rename MY icon because this tool have to \n   be the last in the EXAMINE files.\n\n   That''s all...folks!\n@endnode\n\n@node USA "Usage"\n\n    All you have to do to use this util is to install it and type ''U'' at\n    the main prompt in /X and it will be executed after each upload.\n\n@endnode\n\n@node BUS "Bugs & Suggestions"\n\n   If you find a error or have suggestions to this door please let me know.\n   It''s best if YOU call MY board that way i get the report fastest...\n\n   Into Exile  +47-675-82545  -  A4OOO/O4O - USRobotics 28.8 Dual Standard\n@endnode\n\n@node HIS "History"\n\n   v1.O 22-O9-94 - First Public release, should be 1OO% working by now!\n@endnode\n\n@node GRE "Greetings"\n\n   Bandit/Shade      - You have my 3OO,- kr for /X\n   Double/Duplo      - Eh what should i thank you for hmmm\n   Intercon/Indep.   - What are you coding now??\n@endnode\n\n@node CON "Contact Trouble/Shade"\n\n   To contact me, please call my board.....\n \n[««««««««««««««««««««««««]  i N T O  e X I L E  [»»»»»»»»»»»»»»»»»»»»»»»»]\n \n   _____  __________  _______ _  __________\n  _)   ¬\_)  __    ¬\_)   __    _)  __    ¬\\n  \      \     \     \     \__ _\     \     \\n   \      \_    \     \     \    \     \     \    nATIVE:\n    \____________\     \     \    \______     \\n                  \     \_____\          \_____\     tROUbLE!/sHADE\n                   \- - -\               _ ___\n        ___________ \     \_____    _____     \______  ___________\n       _)     ____¬\_\     \   ¬\_ _)   ¬\     \    ¬\_)     ____¬\_\n       \      ______/_\___      _/_\      \     \     \      ______/_ _\n        \     \_       \_    \      \_     \_    \_    \_    \_\n         \      _________     \__________________________      _______ _ -\n          \_____\        \_____\                       e!\_____\\n \n \n -- aM¡GA 4OOO - 68O4O pOWER - uSR 28.8 dS - 8 mEGS oF rAM - lATEST /X --\n \n        lOTS oF aMIX-uTILS fOR fREE dOWNLOAD!! - vOTEsITE fOR hYDRA\n\n              dA mAG¡C nUMBA iS: + 4 7 - 6 7 5 - 8 2 5 - 4 5\n \n[««««««««««««««««««««««««]  i N T O  e X I L E  [»»»»»»»»»»»»»»»»»»»»»»»»]\n@endnode\n','\n',char(10)),NULL,'auto-added',5615,3,0,NULL,NULL,'shd_um10','scan',1780048728);
INSERT INTO door_catalog VALUES('shd_um20','SHD-UM20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SHD-UM20.LHA','UploadMover','XIM','UploadMover',NULL,'tROUBLE/sHADE','SHD','_) _____) \_ \_) ___\_) _  \_)  __\_e! \____  \  __  \   _/ \  ¬\  \    __/_ ¬\  \_ ¬\  \_ \   \_  \  \_  \   ''95',replace('   ____ _ _____  _____  _____  _____\n  _) _____) \_ \_) ___\_) _  \_)  __\_e!\n  \____  \  __  \   _/ \  ¬\  \    __/_\n      ¬\  \_ ¬\  \_ \   \_  \  \_  \   ''95\n  - _ _________\_____\______________ _ -\n--------------------------------------------\n    uPLOAD-mOVER v2.O - bY tROUBLE/sHADE\n nOW oPTIMISED aND a 1OO% dUPLICATE cHECKER\na mUST fOR bOARDS wITH a lOT oF cONFERENCES!\n--------------------------------------------\n','\n',char(10)),'UploadMover.Guide',replace('@database "Upload-Mover v2.O"\n@remark $Ver: v2.O - O2.O1.95\n\n@node "MAIN" "Upload-Mover v2.O - By Trouble / Shade!"\n\n       _.          _.          ._         ._        _.\n     _/ |_________/ |__________| \_    ___| \_    _/ |_____    .\n..._/  __________  __   \________  \../  __   \../  ______/...· ·   .........\n:  \______    \     |    \    __¬   \/    |    \/    _)   \      ·.·       e!\n: _/     |     \_   |     \_   (     \_   l     \_   l     \_               :\n: \______.     _____¦     _____.     __   .__________.      /   s´h´a´d´e   :\n·········:_____/····:_____/····:_____/____:··········:_____/·················\n\n\n                   Upload-Mover v2.O - By Trouble/Shade\n                   ------------------------------------\n\n                              @{" Introduction " link int}\n                              @{" Requirements " link req}\n                              @{" Installation " link ins}\n                              @{"     Usage    " link usa}\n                              @{"  Suggestion  " link bus}\n                              @{"    History   " link his}\n                              @{"   Greetings  " link gre}\n                              @{"  Contact Me  " link con}\n\n                    Amigaguide Design - By Bandit/Shade\n\n                         Ascii''s - By Elfin/Duplo\n\n\n@endnode\n\n@node INT "Introduction"\n\n   I got this idea from Bandit/Shade. He wanted a door that asked the\n   user after uploading what conf he would move the file to, ie. .dms\n   files in the amiga conference, .lzh files in the s-nes conference.\n   This way the sysop doesn''t have to move files every day. Very time\n   saving for the sysops who supports lots of platforms.\n\n   This version got a built in duplicate checker that can check up to\n   99 directories within one secound. Other duplicate checkers checks\n   only the dir files, if the file is in the list and not on hd, the\n   checker will never know that it is deleted, but this does!\n\n@endnode\n\n@node REQ "Requirements"\n\nRequirements to run this door:\n\n       - Any Amiga\n       - OS 2.+ (v37)\n       - AmiExpress v3.+\n\n@endnode\n\n@node INS "Installation"\n\nYou should do the following things to run this door:\n\n   - Copy the UploadMover dir to Doors:\n   - Copy the SysCmd dir to BBS:Commands/\n   - Copy the AEDoor.library to Libs:\n\n   If you allready have a icon named FILECHECK.info in your \n   BBS:COMMANDS/SYSCMD directory, check if it has a possibility to\n   be executed by the EXAMINE icon or has the oportunity to add a\n   door so you can execute UploadMover from that door. UploadMover\n     MUST  be executed by the FILECHECK icon for the checker to work!\n   Edit the UploadMover.icon, and it should work.\n\n   That''s all...folks!\n\n@endnode\n\n@node USA "Usage"\n\n    All you have to do to use this util is to install it and type ''U'' at\n    the main prompt in /X and it will be executed after each upload.\n\n@endnode\n\n@node BUS "Bugs & Suggestions"\n\n   If you find any bugs or have suggestions to this door you can contact\n   me on this board...\n\n   Into Exile +47-675-82545 - A4OOO/68O4O - USRobotics 28.8 Dual Standard\n\n@endnode\n\n@node HIS "History"\n\n   v1.O 22-O9-94 - First Public release, should be 1OO% working by now!\n\n   v1.x 15-11-94 - Lot''s of changes.. \n                   Including: Fixing a lot of bugs AcpName. (It now stands\n                              UM: "filename" in the ACP when UploadMover is\n                              executed.)\n\n   v2ß  24-12-94 - For BetaTesters ONLY... Now Added a checker THAT FINALY\n                   works...\n\n   v2.O O2-O1-95 - Third public release, optimised so it should be faster.\n\n@endnode\n\n@node GRE "Greetings"\n\n   Bandit/Shade      - I want my 3OO,-\n   Double/Duplo      - Nuke some more lamers!\n   Intercon/Indep.   - Hurry up with the musicdisk code!\n   JSon/Kingdom      - THX for a lot of help and cool chatting :)))\n\n@endnode\n\n@node CON "Contact Trouble/Shade"\n\n \n                    nORWAYS fASTEST tRANSFER sTATION...\n                                 \n           _.      ._         _.      ._\n    ______/ |______| \_______/ |______| \_     .\n....\_______________   \______ |_______   \...· ·   ........ \n:    /      |      |    \      |      |    \     ·.·       :    \n:  _/       ¦      |     \_    |      !     \_             : sHADE wORLD hQ!\n:  \________:______¦     __    ¦______.      /   ¡´n´t´o   : \n···················:_____/_____;······:_____/···············\n \n                          _.         _.          _.    _.         _.\n               .        _/ |________/ |_________/ |  _/ |___    _/ |_____\n    ..........· ·   .../  _______     |   \_______¦./   |   \../  ______/....\n    :            ·.·  /    _)   \___  _  __/      :/    |    \/    _)   \  e!\n    :               _/     l     \_   |    \_    _/     l     \_   l     \_ :\n    :   e´x´¡´l´e   \______.     _____¦    _____________.     _____.      / :\n    ·······················:_____/····:____/············:_____/····:_____/···\n\n    aMIGA 4O4O - uSR 28.8 v.eVERYTHING & uSR 16.8 dS - lOTS oF hD sPACE\n\n »> aMIGA wAREZ «» kIKKI''N aSCII cONF «» hYDRA vOTE sITE «» /X «» mODULES <«\n          »> tHE pOWER sTAFF: tROUbLE/sHADE! «» -dOUbLE/dUPLO! <«\n           \n                         + 4 7 - 6 7 5 - 8 2 5 4 5\n \n                          "aLWAYS uLTRA" fAST...\n\n@endnode\n','\n',char(10)),NULL,'auto-added',12167,4,0,NULL,NULL,'shd_um10','scan',1780048728);
INSERT INTO door_catalog VALUES('shell34','SHELL34.LZH','~/Code/amiexpress_doors/Archives/AmiExpress/SHELL34.LZH','Shell','XIM','Shell',NULL,NULL,NULL,NULL,replace('Ami Express 2.0+ Shell Version 3.4.\n','\n',char(10)),'Changes.Txt',replace('06-15-92 \n\n Version 2.5 Fixed a bug in File Protection for Zmodem Downloads...\n \n\n  2.4 Code...\n\nQuery "Filespec("C"): ";FILENAME = Upper(Strip(Result))\nOpen(''infile'',"DOORS:SHELL/SHELL-NOT",''R'')\nDo until eof(''infile'')\n  SEE = Upper(ReadLn(''infile''))\nIf LastPos(SEE,CLI) ~= 0 then\n\n  The Problem was the CLI was only "DZ" and when the SEE looked at CLI for a \nmatch, it NEVER found any.  I changed the code to...\n\nIf LastPos(See,Filename) ~=0 then\n\nThis fixes the bug!  Sorry.  Was in a hurry to get 2.4 out bcoz of the HACKER\n \nNow ya can feel safe ONCE MORE! :^)\n\n\n\n06-26-92\n\n        Found that if a user typed...\n \n        COPY UP: C: \n \n        It would copy all files in UP: to the C: directory....\n \n   \n\n\n        Why is this bad??? Bcoz someone could Upload a Format command as DIR\n \n        and it would be sittin in the UP: Directory...then they could copy\n\n        everything to C: and then they could use it.  Only other way to \n \n        avoid that was to protect the "CAN" (allowed) files... but ya don''t\n\n        have to now...\n\n\n\n        Also Copy UP:FMT C:\n\n        RENAME C:FMT C:DIR would RENAME the file to "DIR" and you''d get hosed\n\n        So now that is taken out.\n\n        Also if the hacker was able to delete one of the Shell- files...\n \n        Shell 2.6 now checks to make sure all files exists...If not it exits\n\n        telling the user to notify the sysop.  Otherwise it would lock up.\n\n06-30-92\n \n        OK! OK!\n\n        You guys win!  I was tired of you guyz Bitchin'' about my Shell\n \n        not hidding the Passwords.  So NOW you have it!  HAPPY!?!?!?\n\n        Latez Everyone!\n\n\n07-02-92\n\n        SHIT!  I bungled up the code for Zmodem Download in the Shell. I thought\n    \n        2.7 was the last.  Guess NOT! hehehe. Sorry everyone.  Well this new\n \n        Zmodem Code is SMARTER than the old.  It can distinguish between....\n\n        User.data and User.data1  (for example only).  Before it would not \n\n        allow User.data1 bcoz it found the code "USER.DATA"1.  So that''s fixed.\n \n        Please let me know if there are any additions or bugs so I can fix it\n \n        ASAP!!! Thankx.  And Happy(SAFE) BBS''ing.  Kinda like SAFE SEX!?!?!\n\n        Make Sure You Wear Your Bunjie Condoms everyone!\n\n\n08-05-92   Shell 3.0 Released.  Now written 100% in C\n\n\n\n08-08-92 (5:32 am)\n\n         Implemented an internal Ami Express CLI...\n\n         To enter type "."  This allows the users to execute Ami Express\n\n         commands as if they were NEVER in a DOOR.  0, 4, DS, VS do not\n\n         work.  I protected the shell so these options were disabled.\n\n         To exit hit "G" for good-bye. \n\n         Special Thankx goes to ByteMaster for this MAJOR increase in Shell\n\n         technology (hehehe).\n\n08-08-92 (8:21 pm)\n\n         Sysops complained they had to enter in names CASE SENSITIVE.\n\n         After discussing it with Indiana of Temple Of Doom BBS, I decided\n\n         to allow ANY CASE.  It doesn''t matter anymore. Passwords are still\n\n         CASE SENSITIVE.\n\n08-21-92 (8:33 pm)\n \n         Fixed the temp file to create a temp file with the node # included.\n\n         Just in case 2 users are online using the shell.\n\n         Also fixed when you exit from the AmiEx CLI (via ''.'' to enter, and\n\n         ''g'' to exit) so that when you exit the shell it does not duplicate\n\n         the last command used while in the AmiEx CLI.  Thankx ByteMaster!\n\n08-23-92 (1:43 am)\n\n         Ami 2.2 changed an internal feature that I was using.  I had to\n\n         modify my code to allow the Shell to work with the 2.2 Ami Express.\n\n08-25-92 (10:34 pm)\n\n         Fixed Bug when you used Zmodem Download, you could no longer use the\n\n         dos commands.  FIXED!\n\n         Fixed Bug where you could still copy DIRS.  FIXED!\n\n         Added a new command called "SPY". Used to Spy on Other Nodes.\n\n08-26-92 (8:36 pm)  VERSION 3.3\n\n         Fixed bug when you used DIR ASDF: (where ASDF was an invalid drive),\n \n         it would open a DOS requestor.  FIXED!\n\n         Added the ''?'' command to list the commands allowed to be used.\n\n         Changed the Spy Exit.  I think you''ll like this one better. hehehe\n\n\n09-10-92 (5:43 pm) VERSION 3.4\n\n         Now there is ONLY 1 config file.\n\n         Added "Copied..." to let the user know a file was copied.\n\n         Added a Logfile for the commands the user types.\n\n         Added the ability to allow devices specified in the Config File\n\n         Added MORE SYSOP Features.\n         --------------------------\n         1) Type Ratio or R to see all USERS with DISABLED RATIOS\n         2) Type Access or A to see all USERS with 200+ ACCESS LEVEL\n         3) Type New or N to see all NEW USERS\n\n','\n',char(10)),NULL,'auto-added',30702,3,0,NULL,NULL,'shell34','scan',1780048728);
INSERT INTO door_catalog VALUES('shk_fpro','SHK-FPRO.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SHK-FPRO.LHA',NULL,'XIM','FILEID professional - Express XiM by SHOCK!',NULL,'SHOCK!','SHK','The best fileid door available ever ! Confmover................Hydra users delight Sent/timeline............Tag-/timeline adder',replace(' FILEID professional - Express XiM by SHOCK!\n    The best fileid door available ever !   \nConfmover................Hydra users delight\nSent/timeline............Tag-/timeline adder\nViewfile..................View into the file\nCDE.......................Complex Diz editor\nStripper...............Strip BBsadvert lines\nGrouplogos................detect/choose/load\n     Containing.......FILEID/SENT/IDALL!    \n','\n',char(10)),'fpro.doc',replace('   _________ _____ _____                 _____\n  /   ______\____ /    /____ _________  /    /________   Pro v0.Xß Unregistered\n /   ---''  /    //         //  _______\/    //    _   \\n·----/    /    /·---------//     ----\·----//sk!  /    \ Express XiM by SHOCK!\n         ·----/           ·-----------·    ·-----------/\n------------------------------------------------------------------------------\n\n                                INTRODUCTION\n                                ¯¯¯¯¯¯¯¯¯¯¯¯\n  No unneccassary words ! This Fileid is just a step into future , nothing\n  compared to things in past . It has many great features .Though it is\n  very complex it is easy to install for the sysop and also easy to use\n  for the uploader.This doc has three main chapters .\n\n                              1.STANDARD DOC.1\n                                 - fileid -\n                                  - idall -\n                                  - sent -\n                                 * editor *\n\n                              2.INSTALLATION.2\n                           3.UPDATE-/FUTUREINFO.3\n               4.GERMAN VOTES SYSTEM CALLED "VOTES `N CHARTS".4\n\n                              ....GREETINGS....\n\n                * This archiv containes : [FileID/Sent/All]. *\n\n  ============================[×> FILEID <×]==============================\n\n          - First there is the simple ID extractor and adder -\n\n  If the uploaded file is an LHA/LZH/DMS/TXT[..]/ZIP.. ,the door checks\n  if there is an id supplied in it.If there is any it will be depacked\n  and shown to the user. There will be also an information field con-\n  taining the current conference ,filename ,filesize, date and time.But\n  this also depends on how many lines the ID has .If only one ,only the\n  conference Line will be shown.If two ,conference and Filename . etc.\n\n  >                                           <  Conference.:        Amiga\n  >                                           <  Filename...:     Test.lzh\n  >                                           <  Filelength.:       393481\n  >                                           <  Date.......:     31-10-75\n  >                                           <  Time.......:        12:00\n  >                                           <\n  >                                           <\n\n  Now you reach this Prompt menu wich counts from 5 down to zero.\n\n  W)ait,V)iew,C)onfmv,E)dit,A)ddTime,T)agline --- Use iD [y/n/c/s] ---- 05\n\n      While counting you are able to hit one of the prompt commands :\n\n        W) ait    : Now the counter will be frozen and you have time\n                    to step back and decide what to do .Same as <CR>.\n\n        R) eset   : Now the prompt counter will be resetted to the\n                    first value to gain a bit of time.\n\n        V) iew    : Now your Sysops view command will be called\n                    with the complete path and filename of file.\n                    The view command should check if the user`s\n                    level allows this command.If not "NoNo" will\n                    be displayed .\n\n        E) dit    : This calls the Fullscreen Diz editor .The most\n                    powerfull Fileid editor. It has an emacs like\n                    handling . Detailed information in the editor\n                    chapter.\n\n        C) onfmv  : This is a very handy feature .With this button\n                    you can change the destination conference for\n                    the CURRENT and the FOLLOWING files.If you hit\n                    the key ,the standard conference join menu will\n                    be shown. Now you can join a conference as normal\n                    an the files will be moved into this conference\n                    as you would have uploaded into it as normal.\n                    This is very handy for HYDRA users wich start\n                    one session with up- and downloads of their files.\n                    But now it plays no role if the upload files don`t\n                    belong to the current conference ,because they\n                    could be easily moved to their belonging conference.\n\n                    e.g : Your current conference plays no role.\n                          Just start uploading ten AMIGA and ten PC\n                          files with one step .And when you reach\n                          the fileid prompt you move them to their\n                          belonging conference.\n\n                    e.g : For uploading five AMIGA files and download\n                          six PC files you join the PC conference like\n                          everything is normal and when finished the\n                          HYDRA session you move the uploaded files\n                          when the fileid prompt appears.\n\n                    DON`T FORGET - When you move a file into another\n                    conference the rest would be by default moved to\n                    it too.So you have to rejoin if you don`t want the\n                    rest into this conference.( Thx to Fox for this\n                    idea .He was very first releasing a tool for it).\n\n        T) agline : If you press this button your configured tagline\n                    will be used as the last line of the file des-\n                    cription added to the dir file . Like this ..\n\n                       --( SHOCK! )-----/\/ BORN ON HALLOWEEN \/\--\n\n        A) ddtime : This is an tagline like feature ,but it uses a non\n                    configurable sentline wich is formatted like this\n\n                       =[ USERNAME ]=============[ TIME : 12.00 ]==\n\n                    Very helpful for traders and in some cases you can\n                    compare the speed between different bbs`s.From my\n                    opinion a must under every major and helpfull for\n                    charts etc.\n\n                    A) and T) are mutual exclusiv - that means that there\n                    can be only one .The last choosen will be taken.\n\n        F) reedl  : This option is for sysops only and should speak for\n                    itself . The file will be freedownlaod after logoff.\n                    Don`t forget that you need the file processor\n                    installed .Refer to fileprocessor chapter for details.\n\n        [y,n,c,s] : these are the standard input keys.They are answers to\n                    the question "Use this fileID as description"\n\n                    where [y] is "YES" .The counter exhausts ,so the iD\n                              will be used.Same effect as waiting until\n                              the counter ends.\n\n                          [n] is "NO" .This would call the editor and you\n                              can modify the ID as you like it.\n\n                          [c] is "CONTINUE" .This option should be used\n                              very carefully .The Prompt after every iD\n                              will be disabled ,so you aren`t bored after\n                              every file with the counter ,but you also\n                              lose control of the action.The prompt cmd`s\n                              will be disabled too.\n\n                          [s] is "SEND".Aborts and sends the file and the\n                              ID into the sysops hold directory with this\n                              description :\n\n                              / Aborted by USERNAME          [FileiD Pro]\n\n        In the registered version  options like l)ogoff wich kicks\n        you out of the line ,X)timer wich set the default value of the\n        counter and P)icksent wich calls the sent door and you can redefine\n        your sentline and other values are also available.\n\n ==============================[×> ALL <×]================================\n\n If you want let the user easily change some settings before upload\n then you should install id all .\n\n It will be called when the user starts to upload with the ''u''\n command of main menu prompt of /X .\n\n   --{ FileiD ALL }-- t)agline,a)ddtime,x)timer -- ALWAYS ASK [Y,n] --\n\n      The door asks you "Do you want FILEID prompt be shown ?"\n\n            [Y]   :  "YES" .This is default .It has no effect on the ID\n                     procedure.Same as hitting <CR>.\n\n            [n]   :  "NO" .This disables the Fileid prompt.Similar to\n                     hitting ''c'' at the id prompt.\n\n      t) agline   :  This is useful if you disabled your sentline (see\n                     chapter sent).Now it will be used for the uploads.\n                     It`s like a switch.if you press it the t char will\n                     be uppercased so it indicates it`s ON.Otherwise\n                     your default sent settings be used.\n\n      a) ddtime   :  Refer to the above t) option but timeline instead\n                     tagline.\n\n      x) time     :  Set the Fileid Prompt counter to an value.This will\n                     turn automatecally OFF when the user presses [n]\n                     at this prompt.\n\n      The idALL settings have higher priority then the sent main settings.\n      They are just created temporally (Env: vars) and will be deleted\n      when the user logs off.They don`t change anything at the main\n      settings and are not saved on disk.Read in the install capital for\n      more informtion.\n\n   ================================[×> SENT <x]=============================\n\n   Sent - the user tagline configurator.\n\n   This is an all in one door.Simply the best sent door arround.It has\n   every feature of other sent doors .And remember this door is for\n   FILEIDpro only.The main door:\n\n           #> --( SHOCK! )-----/\/ BORN ON HALLOWEEN \/\-- <#\n\n    [1] Use this sentline    YES        [4] Display fileid       YES\n    [2] Use timeline instead NO         [5] Fullscreen Editor    YES\n    [3] Show fileid prompt   YES        [6] Prompt wait value    10\n    ----------------------------------------------------------------\n    Input:                        [T]ag,[M]iddle,[S]AVE,[Q]UIT,[1-5]\n           ¯\n\n   You have these options.\n\n      [T] agline                - Press T (or anything inactiv) to get\n                                  into the line editor and edit your\n                                  personal tagline here.\n\n      [M] iddle                 - Write your sentline from start of the\n                                  line editor and press this key ONE\n                                  time to CENTER it into the middle of\n                                  the editor.If you would press it again\n                                  it would be moved to the right.\n\n      [1-5]                     - This are used for sentline and FILEIDpro.\n\n                                  1.if YES the tagline would be used under\n                                    your descriptions.Otherwise not.\n                                  2.Disable tagline and use timeline\n                                    instead (see FILEIDpro prompt keys).\n                                  3.With this you could turn the FILEIDpro\n                                    prompt on and off.BUt don`t forget :\n                                           No prompt no commands !\n                                  4.This should be turned on for normal.\n                                    If NO then the file_id.diz would`nt\n                                    be displayed when depacking it out of\n                                    the file at FILEIDpro.\n                                  5.If YES the Fullscreen (CDE) would be\n                                    used to edit the id files.Otherwise a\n                                    very lame line editor.This should be\n                                    YES .Only if you have great problems\n                                    with it turn it off.As said the line\n                                    editor is mega lame and should`nt be\n                                    used.\n\n      [S] ave                   - Quit this door with saving the settings.\n\n      [Q] uit                   - Quit without saving anything .Old values\n                                  will be used.\n\n   Don`t forget the idALL settings have higher priority.Also remember that\n   1 and 2 are mutual exclusiv !!\n\n  ---------------------( Dized - FILEID EDITOR )-----------------------\n\n  The integrated Fullscreen Dizeditor is a very powerfull utility.It`ll\n  be called if you press ''e'' at Fileid prompt or you uploaded a file\n  wich is one of the supported archives but has no FILE_ID.diz in it.\n  And if you have installed the Idgroups.txt file you could choose a id\n  file for this archiv ...to be used..\n\n  It`s handling is very emacs (Unix) like. So some of you should get it\n  it really fast.The Screen would look like this.\n\n  ------------------------------------------------------------------------\n  Type ''/'' as first character to move the file into SYSOPS HOLD directory.\n\n        .***************** <ESC>=CMD ****************.\n        *THIS IS A FULLS                             *  CTRL-W=SAVEQUIT\n        *              ¯                             *\n        *                                            *  <ESC>q=QUIT\n        *                                            *  <ESC>p=PACKSAVE\n        *                                            *\n        *                                            *\n        *                                            *\n        *                                            *\n        *                                            *\n        *                                            *\n        *                                            *\n        *                                            *\n        *                                            *\n        >                                            <\n        *                                            *\n        `* [?]=Help ******** DizEd v0.3 - bY ShoCK! *''\n\n  ------------------------------------------------------------------------\n\n If it is not started with ''e'' it starts from scratch with an empty display.\n It is devided into two inputs .Editor input with it`s arrow keys and just\n like an normal editor and the command input/modus reached/left by hitting\n the ESCAPE key ( from now on <ESC> ).\n\n If you would press <ESC> ? (from now [?]) this help menu would be displayed.\n\n               [i]nsert - Toggle insert mode on/off\n               [g]roup  - Insert a grouplogo into buffer\n               [h]ome   - Return to home (left uppercorner)\n               [c]ls    - Clear screen ..erase project\n               [r]edraw - Redraw the whole screen\n               (d)epack - extract id out of file\n               [p]ack   - Pack current id into file\n               [s]ave   - Save id & quit\n               [Q]uit   - Quit diZed without query\n\n In the registered version there is also an [j] option to jump to an second\n id buffer ,so you can edit two id`s and deceide wich to save ,or leave the\n old one in the one buffer and create the new in the new buffer ...or an\n powerfull prefix processor who calls scripts/doors/actions if filename\n matches special pattern and much more.\n\n -----------------( STRIPPING BBSADVERTS OUT OF ID`S )------------------\n\n If you want have stripped some nasty bbs adverts out of your fileid`s,\n then you should make a file called doors:FILEIDpro/Striplines.txt\n listing all the lines you want to strip.You may also use ''?'' as a joker\n for variable parts of the bbsadvertline.\n\n e.g. +-- downloaded from StripMeBBs --- Nd ?? --+\n\n ---------------------( USING THE GROUPLOGO FILE )----------------------\n\n The grouplogo data file called doors:fileidpro/Idgroups.txt includes\n grouplogos wich could be choosen from menu if there is no file_id.diz\n in the archiv or using the "g" command from the CDE.The configfile MUST\n start with this header "FILEIDpro by SHOCK!",otherwise it wouldn`t be\n detected as a idgroupfile.An group is identified like this :\n\n#GROUPNAME >DETECT\nBODY\n\n After the ">" char the DETECT field is supposed . It should be at least\n one charachter ,but isn`t limited. The begin of the archiv will be compared\n up to the last char of the detect field.The body should`nt oversize the\n normal id size of 12x44 chars ,otherwise it will be cut.\n\n e.g.\n\n#MISTRAL >MSL-\n           ___    _________     _____\n_____  ___(___)___\_.   ._/____/ __  \____\n\:.  \/    /.:|  __/| ·:||  __ /  _ ·:\  /__\n \   \/___/___|__   |___||     \__|____\/sk/\n  \___\      /_____/     |__|___\  /______/\n\n The size of the groupfile is limited in the unregistered version.And as\n special feature you could define a data file for every conference each.\n And in the grouplogo menu ,the detected groups will be marked with an ">".\n\n ×××××××××××××××××××××××× INSTALLATION OF THE DOOR ×××××××××××××××××××××\n\n The installation should be easy for a sysop who has a bit expreriance\n with /X or any other clone.All you need to run FILEIDpro is a full\n installed /X V 3.38+ (it should work an S!X or other clones too) and\n assign doors: where you create a dir called fileidpro/ with it`s files.\n\n 1.Copy the whole FILEIDpro/ directory into your DOORS: directory.\n 2.The unregistered version has no setup option for the different types\n   of (de)packer so you have to use these : You will need the normal\n   fileid extract/add utilities in your C: path.\n\n   DMSDescript (DMS)\n   EXEDescript (EXE)\n   TXTExtract  (TXT)\n   GIFDesc     (GIF) ?? IF YOU WANT !\n   Unzip       (ZIP)\n   LHA         (LHA)\n\n 3.The files in this archiv should be copied to there belonging dir like\n   done in this archiv.\n\n         SENT.info           -------------->      BBS:COMMANDS/BBSCMD/\n         EXAMINE.info        -------------->      BBS:COMMANDS/SYSCMD/\n         ALLASK.info         -------------->      BBS:COMMANDS/SYSCMD/\n         doors/fileidpro/#?  -------------->      doors:fileidpro/\n\n 4.For Fileid ALL paste this into BBS:<CONFERENCE>/uploadmsg.txt .\n\n------------ MARK HERE ----------------\n~CC_ALLASK\n---------------------------------------\n\n*  And you must add this line into your logoffbatch of your nodes :       *\n*  "delete env:#?.<node>" .Otherwise the env: settings would disturb the  *\n*  other users.                                                           *\n\n 5.For grouplogo selection you need a FILEIDpro logo file with file_id`s\n   called doors:fileidpro/Idgroups.txt .You also COULD INSTALL a file into\n   bbs:<conf>/idfiles.txt including the path and filename of the id logo\n   file used for this conference. An example is included into this archiv.\n   Be sure that the first line wouldn`t be changed because it`s used as an\n   identify for the data file.\n\n 6. Don`t search the File pre(FIX)processor in this archiv ..you`ll need\n    a registered version.\n\n  Thats it .... SHOCK!\n\n  >>>>>>>>>>>>>>>> UPDATE/FUTURE <<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<<\n\n  This is an UNREGISTERED version . Though it isn`t registered you could\n  use it for normal uses without any problems.But if you are really elite\n  you would like to have a FULL VERSION with all the extra options and\n  more speed.\n\n  You could ask me on any system where i on for a REGISTERED version .\n  Donations are of course welcome ,like : postCARDS,beer,Mary Jane and\n  presents (don`t forget i`m born on helloween).\n\n  FUTURE ADDITIONS and DEVELOPING are depending on donations and moral\n  support of YOU.Bug reports and good ideas are very welcome and i promise\n  to include `em in the next version of FILEIDpro naming the helper.\n\n          BETA SITES ARE OF COURSE WELCOME · MULTINODE PREFERED\n\n -----------------------------------------------------------------------------\n                            .---------------------.\n      GERMAN                | * CHART`S N VOTES * |                GERMAN\n                            `---------------------''\n\n   I and some other sysop`s are currently workin on a german chart and vote\n   system. But to get it really workin and representitiv we need more elite\n   systems to join as a vote side or just some busy guys as chart leaders to\n   support it and gather the standings.We have just finished the design.\n   The doors are already coded and are the best and fastest thing ever in this\n   section. They`ll do the most of the job , gather the votes ,calculate high-\n   scores and precalculate rates and print`em to file.Also an extra month top\n   etc. is uniquely coded so the sysops lean back and the vote leader has just\n   to download the datafiles etc.\n\n   If you are the opinion to be good enough then ask to join as a vote side.\n   But of course we are already in touch with the elite systems.\n\n   Wait for the first issue to come !\n -----------------------------------------------------------------------------\n\n           ..:::::                                       :::::..\n      ....:::::          gREETINGS TO THE USERS AND SYOP       :::::....\n\n                                      of\n\n                                 CRITICAL MASS\n                              MAXIMUM ROCK`N ROLL\n                                   EVIL MOON\n                                 HALL OF FAME\n                                TERMINAL FUCKUP\n                                  FREEK WORLD\n                               SUPER TOTAL KAOZ\n                                    SYNERGY\n                                  SYSTEM ONE\n                                   WILDSTYLE\n         ···::::::..          POINT OF NO REPEAT         ::::::······ \n                   :::::::                        ..::::::·\n                           ···                  ···\n             You may also can reach the coder on the above systems\n\n\n                         personal greetings fly out to\n\n                                     SHUT\n                                   Mr.DIESEL\n                                     SECAM\n                                     G.E.M.\n                                  THE VISITOR\n                                    ZELJKO\n                                      FOX\n                                     CQBS\n                                 BRAYN O`NEAL\n                                    SHAMEN\n                                 RAMSES`N PASO\n                                    SARGOR\n                                     MAZ!\n                                     COATL\n                                    SCORPIO\n                                     STEEL\n                                  RED HUNTER\n                                     FLASH\n                                   FAZWONGA!\n                                  SIGMA SEVEN\n                                   NOSTROMO\n                                     SKIN\n                                    VECSYS\n                                   RADIOSITY\n                                     AMOK\n                                   NO LIMIT\n\n                   ##########################################\n\n\n                                 and hello to\n\n                              ALL CONSOLE GROUPS\n\n                            ALL ASCII/ANSI ARTISTS\n\n                             ALL GRAFFITTY ARTISTS\n\n                                /X , S!X CODERS\n\n\n                     ::        .                      :.\n                     ::        :                      ::\n                     ::..   :  :  ::        :         ::\n                 .:::::''    :  : :''        .:        :: ...::''''\n                   .:::. . .:  :  :.      .: ..:''''''  :''''''\n                  .:''::: ::::  :  ''''     :::''             :\n                 :''  ::   .:''  :       ..''    ::          :.\n                     ::  .:''   :.     .::     ::         .:''\n                    .::         '''''':::''''''     ''''        .::\n                     ''               ''''''                ''''''\n','\n',char(10)),NULL,NULL,65938,4,0,NULL,NULL,NULL,'scan',1780048728);
INSERT INTO door_catalog VALUES('shk_prpr','SHK-PRPR.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SHK-PRPR.LHA',NULL,'XIM','2F_____ __ __ _____ _____ __',NULL,'SHOCK!|','SHK','._|    _Y  | _Y    _Y    _Y  |/\_==========. |\_  `-\_    \_  | \_  |_\_  / _/ /X 3.38+ | | |--,  |  |  |  |  |  l  |  |  \_(S!X) XiM|',replace(' 2F_____ __ __ _____ _____ __\n._|    _Y  | _Y    _Y    _Y  |/\_==========.\n|\_  `-\_    \_  | \_  |_\_  / _/ /X 3.38+ |\n| |--,  |  |  |  |  |  l  |  |  \_(S!X) XiM|\n| l_____l__|__l_____l_____l__|___/         |\n|                                          |\n| PREPRO (+mod) v.4 - Express XiM BY SHOCK!|\n|                                          |\n|   THE PSEUDOINTELLIGENT FILE PROCESSOR   |\n|  Autonuke/Autoreward/Autolog/Autocount   |\n|       - This is a worldinnovation -      |\n`------------------------------------------''\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                                                .------''\n             `------------------------------------------------''\n','\n',char(10)),NULL,NULL,52225,7,0,NULL,NULL,NULL,'scan',1780048728);
INSERT INTO door_catalog VALUES('sht_sd22','SHT-SD22.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SHT-SD22.LHA','gifdesc','XIM','SnatchDIZ',NULL,NULL,'SHT','.--_/  ___/___________\__   \_ _____   _   / | _\____    / _/    /   /    /_\_   \_ \__/. |/    _/   / _     /  _/    /   /    /  \  |',replace('     ______           ______       _ _______\n.--_/  ___/___________\__   \_ _____   _   /\n| _\____    / _/    /   /    /_\_   \_ \__/.\n|/    _/   / _     /  _/    /   /    /  \  |\n/_________/  /    /________/  _/    /____\ |\n|      \____/____/´95    \_________/Rpd!   |\n|            strikes again with            |\n|      ----->  SnatchDIZ V2.2  <-----      |\n|   BEST and QUICKEST file_id extractor!   |\n|   (DMS, LZX, LHA, EXE, TXT, ZIP, GIF)    |\n| 1oo% highly optimized asm!  Code: rASCAL |\n`------------------------------------------''\n','\n',char(10)),'SnatchDIZ.guide',replace('@database\n@node main "SnatchDIZ V2.2 docs"\n@{b}                    _         _         _         _         _\n              _____/ \_______/ \_______/ \_______/ \_______/ \___ __ _\n            _/  __/   \_____/   \_____/   \_____/   \_____/   \_//_///\n            \______    \   |     \   |     \   |     \   |     \\n     _ __ _/     \/     \_ .      \_ ·      \_ ·      \_ |      \_\n     \\\_\\_______       /_|       /__       /__       /_|       /\n      ------m!^DG|______/--|______/--|______/--|______/--|______/----@{ub}\n               @{fg highlight}SnatchDIZ V2.2 - © by rASCAL/SHOOT on 19.7.95@{fg text}\n\n\n			    @{"    Purpose     " link 1}\n			    @{"     Usage      " link 2}\n			    @{"  Requirements  " link 3}\n			    @{"   Greetings    " link 4}\n			    @{"    History     " link 5}\n\n                 @{b}kEEP tHE aMIGA aLIVE aND ... lEGALIZE iT!@{ub}\n\n@endnode\n@node 1 "What the fuck..."\n\nSnatchDIZ  is  another  FILE_ID.DIZ extractor for the Shell or for use with\nany bbs-system.  Features:\n\n - LHA-, LZX-, ZIP-, DMS-, EXE-, GIF-, TXT-support\n - SnatchDIZ is smaller than 3 KB and faaaaaaaaaaaaaaaaaaaast (1oo% asm)!\n - great code: SnatchDIZ does not produce HITS like WhaDIZ, SpeeDIZ etc.\n - reentrant (can be made resident)\n - good error handling: no problems with empty files or something\n\n-=> Use SnatchDIZ instead of all the other crap floating around!\n@endnode\n@node 2 "It''s easy..."\n\nUsage: SnatchDIZ FILE/A,S=SUPPRESS/S\n=====================================\n\nFor example:  "SnatchDIZ dh0:down/PPLAY41.LZX S K" will give you\n\n--------------------------------------\nPower Player 4.1 Final Omega Version\n* Latest Update! *\n--------------------------------------\n\nThis extracts and shows the file_id.diz and suppresses the credits and the\nfiletype indicator.\n\nWARNINGS: - SnatchDIZ is cli-only so don''t start from Workbench!\n@endnode\n@node 3 "You got this crap..."\n\nYou need:\n\n - an AMIGA w/Kick 2.04+ (as always).\n - the lha-, lzx- and UNzip-executable placed in your path.\n   A working UNzip is included in the SnatchDIZ-archive.\n\nThat''s it.\n@endnode\n@node 4 "Hallöle to..."\n\n                             all SHOOT members\n                                 CAFFEiNE\n                                   OMEN\n        STEELER and the rest/PHANTASM (thanks for the bug reports)\n                                Flake/TRSI\n                               MAVE/CRYSTAL\n@endnode\n@node 5 "Versions..."\n\nV0.9:	- not released but seems to work properly.\n\nV1.0:	1st release, 31.3.95 (CAFFEINE)\n	- added filetype indicator and the SUPPRESS option.\n	- 1st release (under CAFFEiNE label)!\n\nV2.0:	2nd release, 19.4.95 (SUPREME)\n	- added own routine for search in DMSs (MUCH FASTER than DMS VIEWDIZ)\n	- optimzed search in executables A LOT!\n\nV2.1:	(no public release)\n	- added own routine for search in GIFs (MUCH FASTER than GIFDESC)\n	- SnatchDIZ is now reentrant and can be made resident (PURE option)\n	- removed KEEPDIZ option because it was unnecessary at all\n	- now checks if dos.library is >= V36\n	- no longer crunched. V2.0 sometimes crashed on 040 systems due to\n	  the used packer (CrunchMania V1.9)\n\nV2.2:	3rd release, 19.7.95 (SHOOT) :-)\n	- fixed bug with filenames containing spaces/wildcards\n	- I was told SnatchDIZ even handles JPGs, check it out yourself\n@endnode\n','\n',char(10)),NULL,'auto-added',60262,3,0,NULL,NULL,'sht_sd22','scan',1780048728);
INSERT INTO door_catalog VALUES('sht_sd23','SHT-SD23.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SHT-SD23.LHA','UnZip','XIM','SnatchDIZ',NULL,NULL,'SHT','\   _/__  |_  |  _  |  _  |_   ._/sHOOt''95 | .\_.   /  _/  |  /  :  /  |/   | sTRIKES   | |  l  /___|   l_____l_____/    |aGAIN wITH :',replace('______ ___|___._____._____|_______ ________.\n\   _/__  |_  |  _  |  _  |_   ._/sHOOt''95 |\n.\_.   /  _/  |  /  :  /  |/   | sTRIKES   |\n|  l  /___|   l_____l_____/    |aGAIN wITH :\nl____/----l____/-:sc:----\_____|-------- - .\n.                                          :\n:     -----»>  SnatchDIZ V2.3  <«-----     .\n.                                          :\n:   BEST and QUICKEST file_id extractor!   .\n.   (DMS, LZX, LHA, EXE, TXT, ZIP, GIF)    :\n:  Now able to create /X style listfiles!  .\n. 1oo% highly optimized asm!  Code: rASCAL :\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-24-18  TIME: 10:08:12  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',67224,4,0,NULL,NULL,'sht_sd23','scan',1780048728);
INSERT INTO door_catalog VALUES('shx_gb10','SHX-GB10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SHX-GB10.LHA','GrapeBooth','XIM','GrapeBooth',NULL,'Pigeon','SHX','/    .____\   Y    \  .   \__ Y ___\_ Y ___\ \----,  .:/   .  .:/  | .:/   .  .:/  .  .:/ .\____.::/\_.:l.::/\__.::/\_.:|.::/\.:|.::/.',replace(' _____________ _______________ _______ ____ \n/    .____\   Y    \  .   \__ Y ___\_ Y ___\\n\----,  .:/   .  .:/  | .:/   .  .:/  .  .:/\n.\____.::/\_.:l.::/\__.::/\_.:|.::/\.:|.::/.\n·            [ GrapeBooth v1.0 ]           ·\n:      A new vote door for AmiX >v3.x      :\n¦   With lots of features + nice design    ¦\n| The BEST vote door ever! DL and use now! |\n`-- -  -   -By Pigeon of Shx^Sub-   -  - --''\n» LOOKS LIKE METAL IMPACT BEAT YOU AGAIN ! «\n','\n',char(10)),'GrapeBooth.Doc',replace('                 ______     ______.    ______.    ______.    ______\n             .__/ .____j.__/     ¬|.__/.    ¬|.__/  __.¬|.__/ .____j\n             |    |   ¬||    --   ||   l__   ||      \| ||    __j__.\n             |    |    ||   .   __j|   ._/   ||       '' ||    `   ¬|\n         .---|    `-   ||   |    ¬||   |     ||    |----''|         |---.\n         |   l____     |l___|     |l___|     |l____j     l____     |   |\n         |       `-----''    `-----''    `-----''            dMø`-----''   |\n         |       ______.    ______.    ______.    __.        ______.   |\n         |   .__/  __.¬|.__/ .   ¬|.__/ .   ¬|.__/  l____.__/|    ¬|   |\n         `---|     ¬\| ||    |    ||    |    ||     .___/|   l__   |---''\n             |     __'' ||    |    ||    |    ||     |  ¬||   ._/   |\n             |     ¬\| ||    l    ||    l    ||     l   ||   |     |\n             l____   '' |l____     |l____     |l____     |l___|     |\n                 `-----''    `-----''    `-----''    `-----''    `-----''\n                                   Version 1.0\n                                       BY\n                    Pigeon of Shoxx and SubDoors Development\n\n\n>------< What is it? >---------------------------------------------------------<\n\n It''s a vote door for AmiExpress >3.x!\n  You make a vote and people answer on a selection.\n  The user may also add his/her own choice.\n  You can watch the results, list all votes, list all unanswered votes,\n   delete one vote, delete all votes and some more features.\n\n\n>------< Copyright and stuff >-------------------------------------------------<\n\n I TAKE NO RESPONSOBILITY WHAT-SO-EVER IF THIS DOOR FOR ANY REASON \n  SHOULD CRASH YOUR SYSTEM!!  (It shouldn''t. :) )\n Your are free to spread this as you wish as long the archive and the files\n  remains unchanged and no fee is taken!\n\n\n>------< How do I install this nice door? >------------------------------------<\n\n These files are needed....\n\n GrapeBooth -----( The door )----------> Whereever you wan''t\n GrapeBooth.Doc -( This doc )----------> Not really needed..\n Config.Txt -----( The configfile )----> In the same <dir> as GrapeBooth\n Mainmenu.Txt ---( The mainmenu )------>           -- || --\n   Votes (DIR) --( The directorys )----> In the same <dir> as GrapeBooth\n   Users (DIR) --( must be there! )---->           -- || --\n AEDoor.Library -( A nice library )----> Libs:\n Vote.info ------( You know what. :) )-> BBS:Commands/BBScmd/\n\n Copy all files where they should be and just run it in /X with "Vote"..\n To run it you''ll need:\n    AEDoor.Library\n    AmiExpress 3.x or newer\n    c:Delete           <--- Must support this line.. \n                       <--- "Delete doors:Shoxx-Doors/GrapeBooth/Users/#? ALL"\n\n  It looks where it''s been copied and loads the Config.Txt and the other files\n   from there.\n  When you first run this door it will create some necesseary files.\n\n\n>------< The Config file? >----------------------------------------------------<\n\n  The config file needs 4 things.\n    1. ADD_CHOICE={YES/NO}\n    2. ANSWER_RESULT={YES/NO}\n    3. SYSOP_ACCESS={-NR-}\n    4. LISTNEW_ENTER={YES/NO}\n\n  1. ADD_CHOICE, if the user should be able to add his/her own choice then\n      this must be on.\n  2. ANSWER_RESULT, if the user should be able to see the results of votes\n      he/she haven''t answered on yet.\n  3. SYSOP_ACCESS, How high access a user should have to be able to\n      delete a single vote or delete all votes!!\n  4. LISTNEW_ENTER, if all unanswered votes should be listed upon entering.\n\n  If all of these aren''t in there, GrapeBooth will exit with an error!\n  They mustn''t be in this order. :)\n\n\n>------< How to use it?? >-----------------------------------------------------<\n\n  In the mainmenu there''s a lot of choices..\n\n  List all votes ---------(L)-> Lists all votes in numberorder.\n  List new votes ---------(N)-> Lists all unanswered votes.\n  Create a vote ----------(C)-> Lets you create a vote.\n  Results on votes -------(R)-> Lets you check the results on the votes.\n  Answer on votes --------(A)-> Lets you answer on the unanswered votes.\n  Quit from GrapeBooth ---(Q)-> You can only guess.. :)\n\n The sysop have a little choice to delete ALL votes.. you can''t see it..\n  Delete all votes--------(#)-> Deletes ALL votes!! :)\n\n  There''s nothing special with List votes, List new votes, Create vote\n   or Quit.. But Result and Answer has some nice things..\n\n\n>------< Result >--------------------------------------------------------------<\n\n  View the results of specific votes.\n  View the picture (GBResult.iff) to see how it looks.\n\n  When you first enter you may write:\n    1 <------------ To see the the result of nr 1\n    2 <------------ Same with number two and up!!\n    S <------------ To go back to mainmenu.\n    N <------------ To view results of new.. (Only if you have the \n                                         ANSWER_RESULT=YES in the configfile.)\n  <CR><------------ Enter to view nr 1!\n\n  Then you''ll be shown the result of chosen vote. (View the picture again)\n  At the prompt you can write:\n    S <------------ To stop.\n    D <------------ To delete this vote. (Only if the user have access over\n                                         the SYSOP_ACCESS= in the configfile,\n                                         and only shown to them!)\n  <CR><------------ Enter to view the next vote!\n\n\n>------< Answer >--------------------------------------------------------------<\n\n  When you choose answer in the mainmenu you''ll vote on all votes you\n   haven''t answered on.\n  Look at the picture "GBAnswer.iff" included.\n\n  There you may choose:\n    S <------------ To go back to mainmenu.\n    A <------------ Add your own choice. (If you have ADD_CHOICE=YES in the\n                                                               configfile!!)\n    1 <------------ To choose nr 1!!  Same with all other.. :)..\n\n  It''ll go on until you choose (S)top or when you''ve voted on all!!\n\n\n>------< History >-------------------------------------------------------------<\n\n  v0.ß -- Ready and about 10h of bugtesting from my side!!\n          [ INTERNAL RELEASE! ]\n\n  v1.0 -- Minor bugfix.\n          [ RELEASED 960418 ]\n\n\n>------< Future plans >--------------------------------------------------------<\n\n * Maybe a inline-edit-vote-system.\n\n * Or some kind of votesystem for diskmags and stuff like that!\n   Some kind of support to them anyway. :)\n\n * A percent-o-meter at the results!\n\n * Have your own ascii in it.\n\n\n>------< Greetings to you! >---------------------------------------------------<\n\n                     .--.\n Deamo of Shoxx/Sub -|--|-> Can I have the design to our door soon??\n Maytag of Sub ----. |.-|-> Hello... Gayfag... ;).. stop filming..\n Storm of Shoxx --.`-|''.|-> :) :) :) :) :) :) :) :) öhh.. bajs!!\n Floyd of Shoxx --|--'' |`-> Do I get a new member list soon or??\n Aryan of Dive -. |  .-|--> Why''s your brääda down?.. \n                | `--|-''\n                `----''\n  To ALL shoxxers: Gräjtings to you toooo...  yes. you..\n\n\n>------< Contact ME?? >--------------------------------------------------------<\n\n What is this??.. You really wan''t to contact me?..\n\n  If so then you can reach me at these boards:\n\n           <---> Hangar 18 <---> Cyber Design <---> Solid Motion <--->\n                      <---> Trespass <---> Time Zone <--->\n\n  Or just go to Ulan Bator and sit down for a cup of coffee.. :)\n\n\n>------< My released doors! >--------------------------------------------------<\n\n  Mmh-GrSt.lha <------> GrapeStatus v1.1 <-----> Kinda ugly.. 1:st door though..\n  Mmh-GT10.lha <------> GrapeTime v1.0 <-------> VERY bad door.. it stinks!\n  Mmh-GS13.lha <------> GrapeStatus v1.3 <-----> It''s becoming better..\n\n  Shx-GW10.lha <------> GrapeWall v1.0 <-------> Another wall like all other.\n  Shx-GC11.lha <------> GrapeComment v1.1 <----> Now we''re talking!!\n  Shx-GC12.lha <------> GrapeComment v1.2 <----> Added some things..\n  Shx-GS15.lha <------> GrapeStatus v1.5 <-----> Totally redone..\n  Shx-GS16.lha <------> GrapeStatus v1.6 <-----> BEST status door ever!!\n  Shx-GB10.lha <------> GrapeBooth v1.0 <------> BEST vote door EVER!!\n\n It''s been quite a lot door now..\n\n\n>------< Future door from me and SubDoors Design! >----------------------------<\n\n Right now we (SubDoors Design) are working on a pager called SubPager.\n  It got a VERY nice GUI and will have many nice features!!\n  \n Some new versions of GrapeBooth will most likely come.. (Look at futureplans)\n \n\n>------------------------------------------------------------------------------<\n\n[EOF]\n','\n',char(10)),'{"ACCESS":"{-NR-}"}','auto-added',24454,1,0,NULL,NULL,'shx_gb10','scan',1780048728);
INSERT INTO door_catalog VALUES('shx_gc11','SHX-GC11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SHX-GC11.LHA','GrapeComment','XIM','_______ ___ ___ _______ ___ ___ ___ ___',NULL,'Pigeon^Shx^Mmh','SHX','/   .   \   Y   \   .   \   Y   \   Y   \ /____`----\  .    \  :    \- . ---\- . ---\ \    ¦   ./  ¦   ./  ¦    /  ¦   ./  ¦   ./',replace('  _______ ___ ___ _______ ___ ___ ___ ___\n /   .   \   Y   \   .   \   Y   \   Y   \\n/____`----\  .    \  :    \- . ---\- . ---\\n\    ¦   ./  ¦   ./  ¦    /  ¦   ./  ¦   ./\n \   | .:/  .| .:/   | .:/  .| .:/  .| .:/\n  \__.::/_\.:|::/_\__.::/_\.:|::/_\.:|::/pGN\n.------------[ GrapeComment 1.1 ]----------.\n|  A Comment-2-Sysop XIM door for /X 3.x!  |\n|             by Pigeon^Shx^Mmh            |\n`------------------------------------------''','\n',char(10)),'Config.Txt',replace('NAME.1=Pigeon\nNAME.2=Shoxx\nNAME.3=MetaMorph\nCOMMENT.1=The quality choice of /X doors..\nCOMMENT.2=- Shoxx - Shoxx - Shoxx - Shoxx - Shoxx -\nCOMMENT.3= -- MetaMorph - MetaMorph - MetaMorph --\n','\n',char(10)),NULL,NULL,5521,1,0,NULL,NULL,'shx_gc11_grapecomment','scan',1780048728);
INSERT INTO door_catalog VALUES('shx_gs1','SHX-GS1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SHX-GS1.LHA','GrapeStatus','XIM','GrapeStatus',NULL,'Pigeon^Shx^Mmh','SHX','/   .   \   Y   \   .   \   Y   \   Y   \ /____`----\  .    \  :    \- . ---\- . ---\ \    ¦   ./  ¦   ./  ¦    /  ¦   ./  ¦   ./',replace('  _______ ___ ___ _______ ___ ___ ___ ___\n /   .   \   Y   \   .   \   Y   \   Y   \\n/____`----\  .    \  :    \- . ---\- . ---\\n\    ¦   ./  ¦   ./  ¦    /  ¦   ./  ¦   ./\n \   | .:/  .| .:/   | .:/  .| .:/  .| .:/\n  \__.::/_\.:|::/_\__.::/_\.:|::/_\.:|::/pGN\n.------------[ GrapeStatus 1.6 ]-----------.\n|  A Status XIM door for AmiExpress >3.x!  |\n|         Just a bugfix on v1.5!! :)       |\n|             by Pigeon^Shx^Mmh            |\n`------------------------------------------''','\n',char(10)),'GrapeStatus.Doc',replace('\n\n          _______ ________ _______  _______  ________\n         /  ____//  __   //   _   \/   __  \/  _____/\n       _/   `-   \_       \_  .    \_    __/     __\___\n    .--\__________/_l______/__l_____/____\\___________/--[ sTATUs v1.6 ]--.\n    `---------------------------------------------------------------------''\n\n                       Coded by Pigeon of Shoxx & MetaMorph\n                            Logo by Daemo of Shoxx\n\n\n--=( GrapeStatus ? - What? )=---------------------------------------------------\n\n  As you might have seen it''s a status-door for AmiExpress >3.x.\n  It''s nothing complicated and is easily installed.\n\n  You can most likely run it on S!X too..  I never tested it on S!X but...\n  It''s been tested on a plain Amiga1200 with AmiExpress 4.3..\n\n  Everything is coded i Amiga E v3.2a.. and it needs AEDoor.library which\n   is included. So it''s a XIM door.\n\n\n-------------------------------------------------------------------------------.\n                                                                               |\n--=( How does it look like then? ))=-------------------------------------------''\n\n  Just check out the picture included and enjoy..\n\n\n-------------------------------------------------------------------------------.\n                                                                               |\n--=( History )=----------------------------------------------------------------''\n\n951210......v1.0\n    The first version ready!!\n    My first /X door, it had some bugs but!\n\n951218......v1.1\n    Bug fix and change of design.\n    If you had ratio 0 it stood ''rATIO--[1:0'', this was\n    changed into ''rATIO--[dISABLED''.. :)\n\n951219......v1.2\n    Added the node number and how it all came up.\n    Now all the text comes up from below!!\n\n951222......v1.3\n    Added the Messages posted and the little timeshower.\n\n960310......v1.4\n    Changed the whole design of the door.\n    And added the "Chat Flag:".\n\n960319......v1.5\n    Recoded the whole thing.\n    And added the "Time Used:"!\n\n960328......v1.6\n    Fixed bug.. If you had ansicodes in the bbsname\n    it went berserk!! Thanx dEAMO!!\n    And i forgot to change the colours.. it were totally red\n    instead of white!!.. /X shit..\n\n\n-------------------------------------------------------------------------------.\n                                                                               |\n--=( Wanna reach me? )=--------------------------------------------------------''\n\nIf you for ANY reason wan''t to get in contact with me, just call these places!\n\n                         .--( Hangar 18 )----( Shoxx SHQ )--.\n                         ¦--( Solid Motion )----------------¦\n                         ¦--( Trespass )--------------------¦\n                         ¦--( Time Zone )-------------------¦\n                         `--( Illusion )--------------------''\n\n\n--------------------------------------------------------------------------------\n                                    -[EOF]-\n','\n',char(10)),NULL,'auto-added',11723,4,0,NULL,NULL,'shx_gs1','scan',1780048728);
INSERT INTO door_catalog VALUES('shx_gs15','SHX-GS15.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SHX-GS15.LHA','grapestatus','XIM','LE-win5-96.exe',NULL,'Pigeon^Shx^Mmh','SHX','/   .   \   Y   \   .   \   Y   \   Y   \ /____`----\  .    \  :    \- . ---\- . ---\ \    ¦   ./  ¦   ./  ¦    /  ¦   ./  ¦   ./',replace('  _______ ___ ___ _______ ___ ___ ___ ___\n /   .   \   Y   \   .   \   Y   \   Y   \\n/____`----\  .    \  :    \- . ---\- . ---\\n\    ¦   ./  ¦   ./  ¦    /  ¦   ./  ¦   ./\n \   | .:/  .| .:/   | .:/  .| .:/  .| .:/\n  \__.::/_\.:|::/_\__.::/_\.:|::/_\.:|::/pGN\n.------------[ GrapeStatus 1.5 ]-----------.\n|  A Status XIM door for AmiExpress >3.x!  |\n|             by Pigeon^Shx^Mmh            |\n`------------------------------------------''','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                                                .------''\n             `------------------------------------------------''\n','\n',char(10)),NULL,'auto-added',9782,5,0,NULL,NULL,'shx_gs15','scan',1780048728);
INSERT INTO door_catalog VALUES('shx_gs16','SHX-GS16.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SHX-GS16.LHA','GrapeStatus','XIM','GrapeStatus',NULL,'Pigeon^Shx^Mmh','SHX','/   .   \   Y   \   .   \   Y   \   Y   \ /____`----\  .    \  :    \- . ---\- . ---\ \    ¦   ./  ¦   ./  ¦    /  ¦   ./  ¦   ./',replace('  _______ ___ ___ _______ ___ ___ ___ ___\n /   .   \   Y   \   .   \   Y   \   Y   \\n/____`----\  .    \  :    \- . ---\- . ---\\n\    ¦   ./  ¦   ./  ¦    /  ¦   ./  ¦   ./\n \   | .:/  .| .:/   | .:/  .| .:/  .| .:/\n  \__.::/_\.:|::/_\__.::/_\.:|::/_\.:|::/pGN\n.------------[ GrapeStatus 1.6 ]-----------.\n|  A Status XIM door for AmiExpress >3.x!  |\n|         Just a bugfix on v1.5!! :)       |\n|             by Pigeon^Shx^Mmh            |\n`------------------------------------------''','\n',char(10)),'GrapeStatus.Doc',replace('\n\n          _______ ________ _______  _______  ________\n         /  ____//  __   //   _   \/   __  \/  _____/\n       _/   `-   \_       \_  .    \_    __/     __\___\n    .--\__________/_l______/__l_____/____\\___________/--[ sTATUs v1.6 ]--.\n    `---------------------------------------------------------------------''\n\n                       Coded by Pigeon of Shoxx & MetaMorph\n                            Logo by Daemo of Shoxx\n\n\n--=( GrapeStatus ? - What? )=---------------------------------------------------\n\n  As you might have seen it''s a status-door for AmiExpress >3.x.\n  It''s nothing complicated and is easily installed.\n\n  You can most likely run it on S!X too..  I never tested it on S!X but...\n  It''s been tested on a plain Amiga1200 with AmiExpress 4.3..\n\n  Everything is coded i Amiga E v3.2a.. and it needs AEDoor.library which\n   is included. So it''s a XIM door.\n\n\n-------------------------------------------------------------------------------.\n                                                                               |\n--=( How does it look like then? ))=-------------------------------------------''\n\n  Just check out the picture included and enjoy..\n\n\n-------------------------------------------------------------------------------.\n                                                                               |\n--=( History )=----------------------------------------------------------------''\n\n951210......v1.0\n    The first version ready!!\n    My first /X door, it had some bugs but!\n\n951218......v1.1\n    Bug fix and change of design.\n    If you had ratio 0 it stood ''rATIO--[1:0'', this was\n    changed into ''rATIO--[dISABLED''.. :)\n\n951219......v1.2\n    Added the node number and how it all came up.\n    Now all the text comes up from below!!\n\n951222......v1.3\n    Added the Messages posted and the little timeshower.\n\n960310......v1.4\n    Changed the whole design of the door.\n    And added the "Chat Flag:".\n\n960319......v1.5\n    Recoded the whole thing.\n    And added the "Time Used:"!\n\n960328......v1.6\n    Fixed bug.. If you had ansicodes in the bbsname\n    it went berserk!! Thanx dEAMO!!\n    And i forgot to change the colours.. it were totally red\n    instead of white!!.. /X shit..\n\n\n-------------------------------------------------------------------------------.\n                                                                               |\n--=( Wanna reach me? )=--------------------------------------------------------''\n\nIf you for ANY reason wan''t to get in contact with me, just call these places!\n\n                         .--( Hangar 18 )----( Shoxx SHQ )--.\n                         ¦--( Solid Motion )----------------¦\n                         ¦--( Trespass )--------------------¦\n                         ¦--( Time Zone )-------------------¦\n                         `--( Illusion )--------------------''\n\n\n--------------------------------------------------------------------------------\n                                    -[EOF]-\n','\n',char(10)),NULL,'auto-added',6178,2,0,NULL,NULL,'shx_gs16','scan',1780048728);
INSERT INTO door_catalog VALUES('sil_page','SIL-PAGE.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SIL-PAGE.LHA',NULL,'XIM','????? ?? ??   ??   ?? ???? ??????',NULL,NULL,'SIL','??       ??   ??   ?? ??   ?  ? ????? ?? ??   ??   ?? ???? ???? ?? ?? ??    ?? ??  ??   ? ?',replace('     ????? ?? ??   ??   ?? ???? ??????\n     ??       ??   ??   ?? ??   ?  ?\n     ????? ?? ??   ??   ?? ???? ????\n        ?? ?? ??    ?? ??  ??   ? ?\n     ????? ?? ????   ???   ???? ?  ?\n','\n',char(10)),'silverpage.doc',replace('\n             SILVER-PAGE V1.0 BY MR.ORION & JOSHUA - EXCALIBUR\n\n\n  well.. i''am not to good to that doc writing..but here are an simple\n  page door to ya sysop''s out ther.. thiz is the first version from os...\n  ther will come more update''s on thiz door.. so keep an eye open for\n  other doors and Update''s from os to... well we hope you will use thiz \n  door..BTW: don''t DELETE thiz file :rlf-slvhwk if you do then it\n  dos not work....\n  \n  here are how to install thiz door.. only for lamer''s but well..hee\n\n  copy the O.info icon from the SILVERPAGE dir into your bbscmd dir\n  copy the SILVERPAGE dir to your doors dir.. that''s all now you are ready\n  to go...\n\n  BUG''s:\n  if ther arE bug''s in thiz door then i/we like ya to call one of thiz \n  board''s : MENTAL INSANITY : +45 6594-3572  EXC SCHQ\n            CYCLONE ZONE    : +45 6538-2929  EXC WHQ\n\n  well.. that''s all for now dudez...allmost all..hehe forgot greets..\n\n  greet go''es to :\n\n  all CLS member''s, Devilstar, ramosys, mr.hyde, nsl, hrberg, yobbo,\n  all EXC member''s, Black death, Ghandy, princip, Ra!st, D-siya, \n  Bozo, tuff brain.....\n  \n                       and all other''s we forgot...\n\nMR.ORION & JOSHUA signed off...','\n',char(10)),NULL,NULL,3643,3,0,NULL,NULL,NULL,'scan',1780048728);
INSERT INTO door_catalog VALUES('sky_last','SKY-LAST.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SKY-LAST.LHA','SkyLastCaller','XIM','SkyLastCaller',NULL,NULL,'SKY','| Type: AmiNet:comm/bbs                    | |                                          | | Desc: Shows last callers of the day      |',replace('.------------------------------------------.\n| Type: AmiNet:comm/bbs                    |\n|                                          |\n| Desc: Shows last callers of the day      |\n`------------------------------------------''\n','\n',char(10)),'Readme.txt',replace('---------------------------------------------------------------------------\n                       SkyFly Mailbox  +49-6341-969295\n                  presents with SkyTools: SkyLastCaller 1.3\n---------------------------------------------------------------------------\n\nSkyLastCaller ersetzt den trostlosen Standard-Befehl "Protokoll" von\nPrometheus. Es stellt die bisherigen Tagesanrufer in Form und Farbe\ntabellarisch dar und bringt außerdem noch interessante statistische\nErgebnisse mit. SkyLastCaller verfügt auch über eine Konfiguration.\n\n\nHistory\n~~~~~~~\n1.3 - 28.9.96\n~~~~~~~~~~~~~\n- Zeilenzahl-Berücksichtigung auch bei Statistik.\n\n1.2 - 27.9.96\n~~~~~~~~~~~~~\n- Division-durch-Null-Fehler behoben.\n- Berücksichtigt nun die eingestellte Zeilenanzahl.\n\n1.1 - 7.7.96\n~~~~~~~~~~~~\n- Bug bei der Ausgabe behoben.\n\n1.0 - 15.6.96\n~~~~~~~~~~~~~\n- Erste Version.\n','\n',char(10)),NULL,'auto-added',20146,5,0,NULL,NULL,'sky_last','scan',1780048728);
INSERT INTO door_catalog VALUES('sky_list','SKY-LIST.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SKY-LIST.LHA','SkyLister','XIM','SkyLister',NULL,NULL,'SKY','| Type: AmiNet:comm/bbs                    | |                                          | | Desc: Lists board-contents in            |',replace('.------------------------------------------.\n| Type: AmiNet:comm/bbs                    |\n|                                          |\n| Desc: Lists board-contents in            |\n|       AmigaGuide & HTML format           |\n`------------------------------------------''\n','\n',char(10)),'Readme.txt',replace('---------------------------------------------------------------------------\n                      SkyFly Mailbox  +49-6341-969295\n                    presents with SkyTools: SkyLister 1.3\n---------------------------------------------------------------------------\n\nSkyLister ist ein Filelisten-Generator, der eine Fileliste von\nbeliebigen Box-Brettern erzeugt. Und zwar entweder im AmigaGuide\noder im modernen und formschönen HTML-Format! Der Liste kann\neine Hauptmenü-Gestaltung sowie weitere Dokumente angehängt\nwerden. Die HTML-Version läßt alle Arten von zusätzliche Daten\nzu (z.B. Bilder, Animationen). Die fertige Liste wird gepackt\nund in ein einstellbares Brett gelegt. Beide Programm-Versionen\nbesitzen getrennte Konfigurationen, die komfortabel über einen\nMUI-Einsteller bearbeitet werden.\nMit dieser Software wird die Fileliste Ihrer Mailbox zu einem\nhochmodernen Angebot, das Ihren Usern massig Freude bereiten\nwird!\n\nNeuerungen\n~~~~~~~~~~\n1.3 - 1.11.96\n~~~~~~~~~~~~~\n- Eine Routine geändert, die auf 040ern zum Absturz führen konnte.\n- Option NOBUF zugefügt, die das Versenden des fertigen Archives ins Brett\n  verhindert.\n- Die Shell-Ausgabe des Packers wird jetzt blau dargestellt.\n','\n',char(10)),NULL,'auto-added',42787,5,0,NULL,NULL,'sky_list','scan',1780048728);
INSERT INTO door_catalog VALUES('sky_logo','SKY-LOGO.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SKY-LOGO.LHA','SkyLogOffKom','XIM','SkyLogOffKom',NULL,NULL,'SKY','| Type: AmiNet:comm/bbs                    | |                                          | | Desc: Allows typing in a logoff-comment  |',replace('.------------------------------------------.\n| Type: AmiNet:comm/bbs                    |\n|                                          |\n| Desc: Allows typing in a logoff-comment  |\n|       (with censoring)                   |\n`------------------------------------------''\n','\n',char(10)),'Readme.txt',replace('---------------------------------------------------------------------------\n                 SkyFly Mailbox  +49-6341-969295 (Ringdown)\n                  presents with SkyTools: SkyLogOffKom 1.1\n---------------------------------------------------------------------------\n\nMit SkyLogOffKom kann jeder User einen Logoff-Kommentar eingeben,\nder dann beim Login angezeigt wird. Alle eingegebenen Kommentare\nwerden mit User-Angabe in eine Protokoll-Datei geschrieben. Es\nkönnen User für den Logoff-Kommentar gesperrt werden und Wörter\nkonfiguriert werden, die der User in seiner Eingabe nicht ver-\nwenden darf. Diese verbotenen Kommentare werden ebenfalls proto-\nkolliert.\n','\n',char(10)),NULL,'auto-added',19289,5,0,NULL,NULL,'sky_logo','scan',1780048728);
INSERT INTO door_catalog VALUES('sky_poll','SKY-POLL.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SKY-POLL.LHA','SkyPollKosten','XIM','SkyPollKosten',NULL,NULL,'SKY','| Type: AmiNet:comm/bbs                    | |                                          | | Desc: Shows poll-costs of every system   |',replace('.------------------------------------------.\n| Type: AmiNet:comm/bbs                    |\n|                                          |\n| Desc: Shows poll-costs of every system   |\n`------------------------------------------''\n','\n',char(10)),'Readme.txt',replace('---------------------------------------------------------------------------\n                       SkyFly Mailbox  +49-6341-969295\n                  presents with SkyTools: SkyPollKosten 1.0\n---------------------------------------------------------------------------\n\nSkyPollKosten wertet das Netz.prt von Prometheus aus und zeigt die\nPolls bei jedem System in den verschiedenen Tarifzonen, die Gesamtdauer\nder Polls, die Telefoneinheiten und die Kosten an.\nDiese Werte werden auch noch insgesamt angezeigt. Die Endsumme entspricht\ndann der Telefonrechnung der Telekom.\nAußer Polls bei anderen System können auch die Polls beim eigenen System\nberechnet und ausgegeben werden. Beides zusammen ist natürlich auch\nmöglich.\nFür jedes System kann in der Konfiguration die entsprechende Tarifzone\nangegeben werden, sodaß die Kosten korrekt ausgewertet werden.\n','\n',char(10)),NULL,'auto-added',27349,5,0,NULL,NULL,'sky_poll','scan',1780048728);
INSERT INTO door_catalog VALUES('sky_useb','SKY-USEB.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SKY-USEB.LHA','SkyUseBin','XIM','SkyUseBin',NULL,NULL,'SKY','| Type: AmiNet:comm/bbs                    | |                                          | | Desc: To use bins, join buffers, filter  |',replace('.------------------------------------------.\n| Type: AmiNet:comm/bbs                    |\n|                                          |\n| Desc: To use bins, join buffers, filter  |\n|       & forward mails                    |\n`------------------------------------------''\n','\n',char(10)),'Readme.txt',replace('---------------------------------------------------------------------------\n                      SkyFly Mailbox  +49-6341-969295\n                    presents with SkyTools: SkyUseBin 1.6\n---------------------------------------------------------------------------\n\nUseBin-Soft, Puffer-Joiner, Mailfilter und Weiterleiter!!\n\nKopiert alle eingehenden binären Files in Netzen nach frei definier-\nbare Bretter (z.B. zum Kopieren von Tools aus den Netzen in die lo-\nkale Filebase). Features: packen und repacken von Files; uudekodie-\nren; Musterübergabe für alle Einstellungen; Speicherbedarf und somit\nSpeed-Faktor einstellbar; Dupe-File Erzeugung für Upload-Skip o.a.;\nzwei unterschiedliche MUI-Oberflächen, je nach Geschmack; Einstel-\nlungs-Progamm für Grundeinstellungen; Bubble-Helps. Puffer-Joiner:\nPuffer werden zusammengefügt und Sorter-Speed drastisch erhöht! Mail-\nFilter: filtert Mails, die eingestellten Kriterien entsprechen. Wei-\nterleiten: Umleitung von ganzen Netzen und EMail-Adressen. \n\nHistory\n~~~~~~~\n1.6 - 30.10.96\n~~~~~~~~~~~~~\n- Der Mailfilter setzt nun auch bei binären Mails ein.\n- Weiterleitungs- bzw. Gate-Funktion eingebaut!\n- Protokoll enthält nun auch Informationen zu Box/Point und Puffer.\n- Beim Joinen werden detailiertere Angaben ausgegeben.\n- Info-Felder für Mailfilter und Weiterleiten dem SkyUseBin-Fenster\n  zugefügt\n- Kleines Autor-Info-System eingebaut \n','\n',char(10)),NULL,'auto-added',50048,6,0,NULL,NULL,'sky_useb','scan',1780048728);
INSERT INTO door_catalog VALUES('sky_vert','SKY-VERT.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SKY-VERT.LHA','SkyVerteiler','XIM','SkyVerteiler',NULL,NULL,'SKY','| Type: AmiNet:comm/bbs                    | |                                          | | Desc: Lists boards and their distrib.    |',replace('.------------------------------------------.\n| Type: AmiNet:comm/bbs                    |\n|                                          |\n| Desc: Lists boards and their distrib.    |\n|       systems                            |\n`------------------------------------------''\n','\n',char(10)),'SkyVerteiler.guide',replace('@database "SkyVerteiler.guide"\n@node main "SkyVerteiler V1.0 - © 1/1997 Matthias Kaulartz"\n\n                             @{b}SkyVerteiler V1.0@{ub}\n                             ~~~~~~~~~~~~~~~~~~~~\n                         @{i}1/1997 by Matthias Kaulartz @{ui}\n\n    @{"Einführung      " link einführung   }  Was ist SkyVerteiler?\n\n    @{"Programmstart   " link programmstart}  Der Aufruf\n\n    @{"Rechtliches     " link rechtliches  }  Registrierung und Garantie\n    @{"Danksagungen    " link greets       }  Danksagungen und Grüße\n\n    @{"Support         " link support      }  Wo bekomme ich Support?\n    @{"Weitere SkyTools" link skytools     }  Was gibt es noch?\n    @{"Das Sky-Netz    " link skynetz      }  Für alle Sysops\n\n\n@{b}>>>  Die brandneuste, bugfreie Version von SkyVerteiler ist immer in  <<<\n>>>  der SkyFly Mailbox zu  erhalten und natürlich  auch für  Gäste!  <<<\n>>>                        +49-6341-969295 (Ringdown)                  <<<@{b}\n@endnode\n\n@node einführung "Einführung"\n\n@{b}Einführung@{ub}\n~~~~~~~~~~\nDieses Tool listet beliebige Bretter auf und zeigt deren\nVerteilersysteme. Die Anzeige kann auch auf einzelne Verteiler\nbeschränkt werden.\nDes weiteren kann man auch die Sortierung umkehren, also für\neinen oder mehrere Boxen/Points die bestellten Bretter anzeigen\nlassen.\nSkyVerteiler wird einfach in der Shell gestartet.\n@endnode\n\n@node programmstart "Programmstart"\n\n@{b}Programmstart@{ub}\n~~~~~~~~~~~~~\nSkyVerteiler wird direkt und einfach aus einer Shell aufgerufen. Das Programm\nbesitzt folgende Aufrufschablone:\n\n@{b}SkyVerteiler B=BRETT/K,V=VERTEILER/K,SORT/K,NOHEAD/S@{ub}\n\nbzw.\n\n@{b}SkyVerteiler [B|BRETT <Brettname oder -muster>] [V|VERTEILER\n  <Verteilersystem oder auch Muster>] [S|SORT B|BRETTER|V|VERTEILER] [NOHEAD]@{ub}\n\nAlle Paramter sind optional. Wird gar nichts angegeben, werden alle Bretter\nund alle Verteiler benutzt. Die Sortierung erfolg dann standardmäßig nach\nBrettnamen.\n\nDer optionale Parameter @{i}BRETT @{ui}(oder abgekürzt `B'') benötigt die Angabe eines\nBrettes bzw. eines AmigaOS-Musters.\n\n@{i}VERTEILER @{ui}(oder kurz `V'') ist nahezu identisch; diesem Parameter wird ein\nVerteilersystem (Mailbox oder Point) übergeben. Mittels eines Musters kann man\nauch mehrere Systeme angeben.\n\nDer Befehl @{i}SORT @{ui}(`S'') legt die Sortierung fest. Wird @{i}BRETTER @{ui}(`B'') übergeben,\nwerden die Bretter gelistet und zu jedem Brett evtl. vorhandene Verteiler\nausgegeben.\nLegt man die Sortierung um auf @{i}VERTEILER @{ui}(`V''), dann werden die Bretter\ngelistet, die die übergebenen Verteilersysteme bestellt haben.\n@{i}BRETTER @{ui}ist übrigens voreingestellt.\n\nMit dem Schalter-Parameter @{i}NOHEAD @{ui}läßt sich die Titelzeile, die normalerweise\nausgegeben wird, abschalten. Dies hat Sinn, wenn man die Ausgabe mit `>''\nbeispielsweise in eine Datei umleiten möchte.\n\nWeg mit der trockenen Theorie und ran an die Beispiele - zum besseren\nVerständnis. :)\n\n@{u}Beispiele@{uu}:\n\n@{i}BRETT /!SKYFLY/INTERN @{ui}\nEs werden alle Boxen und Points angezeigt, die dieses Brett bestellt haben.\n\n@{i}BRETT /Z-NETZ/RECHNER/AMIGA/#? @{ui}\nAlle Bretter in diesem Oberbrett werden angezeigt und jeweils alle Systeme,\ndie dieses Brett bestellt haben.\n\n@{i}VERTEILER FODDER @{ui}\nEs werden alle Bretter gelistet und ggf. die Bretter, die die Mailbox bestellt\nhat, entsprechend markiert.\n\n@{i}BRETT /ALT/BINARIES#? VERTEILER LOLLI @{ui}\nAlle Alt/Bin-Bretter, die der Point Lolli bestellt hat, werden gelistet.\n\n@{i}BRETT /DE/COMP/#? VERTEILER HEINZ SORT VERTEILER @{ui}\nDiese Argumentzeile bewirkt, daß alle Bretter, die der Point Heinz in DE/COMP\nbestellt hat, gelistet werden. Probieren Sie zum Vergleich auch mal den\ngleichen Aufruf ohne @{i}SORT VERTEILER@{ui}.\n\n@{i}B /DE/COMP/#? V HEINZ S V @{ui}\nDas gleiche wie oben. ;)\n@endnode\n\n@node rechtliches "Rechtliches"\n\n@{b}Rechtliches@{ub}\n~~~~~~~~~~~\nDieses Programm ist Freeware und darf frei kopiert und weitergegeben werden,\nsolange keinerlei Modifikationen vorgenommen werden.\n\nGarantien zur korrekten Funktionalität werden @{u}KEINE@{uu} überkommen. Das Pro-\ngramm sollte allerdings 100% laufen. Fehler bitte sofort melden!\n@endnode\n\n@node support "Support"\n\n@{b}Support@{ub}\n~~~~~~~\nUpdates dieses Produkts gibts im @{"Sky-Netz" link skynetz} und außerdem direkt bei der @{"SkyFly" link skyfly}\nMailbox und können dort auch als Gast gesaugt werden. Hier liegt auch immer\ndie @{u}allerneuste@{uu} Version.\n\nFür Fragen, Kritik oder Vorschläge bin @{"ich" link autor} jederzeit zu erreichen!\n@endnode\n\n@node greets "Danksagungen & Grüße"\n\n@{b}Danksagungen & Grüße@{ub}\n~~~~~~~~~~~~~~~~~~~~\n@{b}BliZZeR@{ub}\n@{b}Helena@{ub}\n@{b}Milena@{ub}\n@{b}Maria@{ub}\n@{b}Maike@{ub}\n\nCyberfox, Arcus, Turrican, Monk, Panther, Thomas, Börni, Alex, Hightower,\nMihai (unsortiert)\n\nMartin Brückner (für Prometheus)\n\nUnd last but not least: Mutter, Vater, Markus, Michael.\n@endnode\n\n@node autor "Autor"\n\n@{b}Autor@{ub}\n~~~~~\n                             Matthias Kaulartz\n                          Müller-Thurgau-Str. 13\n                               76829 Landau\n\n                             Tel: 06341-969297\n                             Fax: 06341-969296\n                  SkyFly Mailbox: 06341-969295 (Ringdown)\n                         EMail: [email removed]\n\n     Bankverbindung: Sparkasse SüW, Blz: 548 500 10, Kto: 13 5050 987\n@endnode\n\n@node skyfly "SkyFly Mailbox"\n\n                    .---------                         .---------------\n                   //         \                       //              /\n                  //     ___   \                     //     _________/\n                 //     /  \\   \                   //     /____\n .-----         //     /    \\___\                 //          /\n \\    \       //     /                           //     _____/\n  \\    \     //     / .---  .-- .--   .--       //     / .---   .--   .--\n   \\    \---./     / //  / // /// /--// /      //     / //  /  // /--// /\n    \\             / //  /// _///__   __/ .----./     / //  /  //__   __/\n     \\           / //  __  \    //  /    \\         / //  /____ //  /\n      \\_________/ //__/ \\__\  //__/      \\_______/ //_______///__/\n\n                                                                 __ __\n                                                    /\  /\/\ || |  |  |\ /\n                                                   /  \/  \-\|| |-<   | X\n                                                  /        \ \|_|__|__|/ \\n\n\n                 ------>>>))  24 STUNDEN ONLINE  ((<<<------\n                   ------>>>))  MASSIG NETZE  ((<<<------\n  ------>>>))  INTERNATIONALER MAILVERKEHR DIREKT INS INTERNET ((<<<------\n                  ------>>>))  GROSSE FILEBASE  ((<<<------\n                  ------>>>))  ONLINE FEATURES  ((<<<------\n\n\n   P       U       R       E            P       O       W       E       R\n\n               ->>>  COME AND YOU WILL NEVER WANT TO GO  <<<-\n\n\n                     _  _              _   _   _   _   _   _\n                 _  (_  _) (_| |  __  (_) (_  (_)  _) (_) (_\n                (_) (_) _)   | |       _) (_)  _) (_   _)  _)\n\n                             V.32bis, V.32terbo\n\n\n\n                                 >> Netze <<\n                   - --  --- -- ------ - - -- --- -- -----\n\n       ALT - ANHALT - ASCII-ECKE - ASCII-NETZ - BLITZBASIC - CAAC-NETZ\n     CAMELOT - CE-MARKT - COMP - CONSOLE-NET - CONVOY - CL - CT - CYBER\n       DE - DOMINO - E-NETZ - EAGLE-NETZ - EBL-NETZ - FIDO - FLOHMARKT\n      FRAS - GELD - INKA - KA - KAOS-NETZ - KF-NETZ - LIFESTYLE - M-NET\n     MAUS - MAILBOS-TOOLS - NATUR - LAL - NEUSTADT - NETZWERK - PEGASUS\n      PLANETS - PROMETHEUS - PRONET - RADIONET - RAVE-NET - RHEIN-NETZ\n        SCHNEE - SCHULE - SEEROSE - SKYTOOLS - SOLINET - SPD - SPIDER\n          T-NETZ - TOPNET - TREK-NET - TREKWORLD - VOYAGER - Z-NETZ\n\n\n       **   J E T Z T   V O L L S T A E N D I G E S   U S E N E T   **\n           **   I N K L U S I V E   B I N A E R E   A R E A S   **\n\n\n\n                             >> Online-Games <<\n                   - --  --- -- ------ - - -- --- -- -----\n\n            TETRIS - FLOTTE - GLUECKSRAD - INQUISITION - KNIFFEL\n                NIMM - PAC - POKER - QUIRK - SCHACH - SLIDER\n\n                2-Spieler-Tetris: User<>Sysop & User<>User !\n\n                            ! Game-Competitions !\n\n\n\n                     ->> Bunte Filebase mit dem Besten\n                         vom Besten\n\n                     ->> Viele sortierte Musik-Module aus\n                         verschiedenen Bereichen\n\n                     ->> Grosser Cliparts-Bereich, nach\n                         Themen sortiert\n\n                     ->> Riesen Amiga-PD-Serien Bretter\n                         Fish: 500-1000\n                         Kickstart: 1-500\n                         AmiMag: `93-`94\n\n                     ->> Riesengrosser Demo/Intro Bereich,\n                         nach vielen Bereichen sortiert.\n\n                     ->> Hunderte von Spiele-Cheats\n\n\n       >>> Support für das Sprachenprogramm Learn A Language <<<\n\n                      -- Freedownload im FrAS-Zugang --\n\n\n         [hOME oF sKYtOOLS!] [hOME oF sKYtOOLS!] [hOME oF sKYtOOLS!]\n         [hOME oF sKYtOOLS!] [hOME oF sKYtOOLS!] [hOME oF sKYtOOLS!]\n\n\n\n               ** KEINE USER-GEBÜHREN! ** POINT KOSTENLOS! **\n\n  ------------------------------------------------------------------------\n  ***** KOSTENLOSE UND PRIVATE HOMEPAGE IM INTERNET FUER JEDEN USER! *****\n  ------------------------------------------------------------------------\n\n\n                                  CALL NOW:\n                     _  _              _   _   _   _   _   _\n                 _  (_  _) (_| |  __  (_) (_  (_)  _) (_) (_\n                (_) (_) _)   | |       _) (_)  _) (_   _)  _)\n\n                             V.32bis, V.32terbo\n@endnode\n\n@node skynetz "SkyNetz"\n\n@{b}SkyNetz@{ub}\n~~~~~~~\n- Updates der SkyTools.\n- Infos, Hilfestellungen, Fragen & Antworten zu den Tools.\n- Bugreports und Vorschläge.\n- Vorschläge für weitere Tools sind gerne willkommen.\n- Kontakt zu anderen Sysops und gegenseitige Hilfe.\n- Diskussionen über alles alles mögliche.\n\nDas Netz kann direkt bei der @{"SkyFly" link skyfly} gepollt werden. Schreibzugriff\ngibt es mit einem bestätigten @{"Netzantrag" system "ed NetzAntrag.txt"} von [email removed].\n@endnode\n\n@node skytools "Die SkyTools"\n\n@{b}Die SkyTools@{ub}\n~~~~~~~~~~~~\n@{"AutoSend       " link autosend       }  Versendet automatisch Mails. Viele Optionen und GUI-Prefs.\n  10,- Registrierungsbetrag. Keinerlei Einschränkungen in der unregistrierten Version.\n@{"SkyMLGate      " link skymlgate      }  DAS Programm zum Führen von Mailing-Listen mit PmbS!\n@{"SkyPollKosten  " link skypollkosten  }  Wertet Netzanrufe aus und veranschaulicht die Gebühren.\n@{"SkyUseBin      " link skyusebin      }  UseBin-Soft, Puffer-Joiner, Mailfilter und Weiterleiter!!\n  10,- Sharewaregebühr. Die unregistrierte Version ist zeitlich beschränkt lauffähig.\n@{"SkySetData     " link skysetdata     }  Setzt kaputte Boxstatistiken auf ihren alten Zustand.\n@{"SkyLastCaller  " link skylastcaller  }  Zeigt die bisherigen Tagesanrufer und Statistiken.\n@{"SkySetDupeCheck" link skysetdupecheck}  DupeCheck für jede einzelne Box/Point an-/abschalten!\n@{"SkyLister      " link skylister      }  Erstellt Filelisten im AmigGuide und HTML-Format!\n@{"SkyLogOffKom   " link skylogoffkom   }  Läßt Logoff-Kommentar eingeben. Mit Zensier-Funktion!\n@{"SkyWall        " link skywall        }  Sprüche-Wall mit vielen Funktionen!\n@{"SkyChat        " link skychat        }  Der funktionsreichste Chatruf für Prometheus!\n  5,- Registrierungsbetrag. Bald 10,- Sharewaregebühr für unregistrierte Benutzer.\n@{"SkyMoveBin     " link skymovebin     }  Archiviert nach einem bestimmten Zeitraum die Filebase\n@{"SkyAminetMirror" link skyaminetmirror}  Baut einen kompletten Mirror des Aminet auf!\n  30,- Sharewaregebühr. Die unregistrierte Version ist nicht alleine lauffähig.\n@{"SkyVerteiler   " link skyverteiler   }  Listet Bretter und deren Verteilersysteme\n@endnode\n\n@node autosend "AutoSend"\n\n@{b}AutoSend@{ub} - Versendet automatisch Mails. Viele Optionen und GUI-Prefs.\n~~~~~~~~\nAutoSend  ist - einfach ausgedrückt - ein Tool  zum automatischen Versenden\nvon Mails, beispielsweise Boxwerbungen, an beliebig viele Empfänger.\nAutoSend bringt dabei viele Features und Funktionen mit. Die Konfiguration\nkann komfortabel über ein Prefs-Programm vollzogen werden.\n@endnode\n\n@node skymlgate "SkyMLGate"\n\n@{b}SkyMLGate@{ub} - DAS Programm zum Führen von Mailing-Listen mit PmbS!\n~~~~~~~~~\nMLGate dient zum gaten von Mailing-Listen in die Mailbox, sodaß die Mails\nin Brettern gelesen werden können.\nWeiterhin funktioniert dies auch umgekehrt, d.h. die geschriebenen Mails\nin der Box werden in die Mailing-Liste weitergeführt.\n@endnode\n\n@node skypollkosten "SkyPollKosten"\n\n@{b}SkyPollKosten@{ub} - Wertet Netzanrufe aus und veranschaulicht die Gebühren.\n~~~~~~~~~~~~~\nSkyPollKosten wertet das Netz.prt von Prometheus aus und zeigt die\nPolls bei jedem System in den verschiedenen Tarifzonen, die Gesamtdauer\nder Polls, die Telefoneinheiten und die Kosten an.\nDiese Werte werden auch noch insgesamt angezeigt. Die Endsumme entspricht\ndann der Telefonrechnung der Telekom.\nAußer Polls bei anderen System können auch die Polls beim eigenen System\nberechnet und ausgegeben werden. Beides zusammen ist natürlich auch\nmöglich.\nFür jedes System kann in der Konfiguration die entsprechende Tarifzone\nangegeben werden, sodaß die Kosten korrekt ausgewertet werden.\n@endnode\n\n@node skyusebin "SkyUseBin"\n\n@{b}SkyUseBin@{ub} - UseBin-Soft, Puffer-Joiner, Mailfilter und Weiterleiter!!\n~~~~~~~~~\nKopiert alle eingehenden binären Files in Netzen nach frei definier-\nbare Bretter (z.B. zum Kopieren von Tools aus den Netzen in die lo-\nkale Filebase). Features: packen und repacken von Files; uudekodie-\nren; Musterübergabe für alle Einstellungen; Speicherbedarf und somit\nSpeed-Faktor einstellbar; Dupe-File Erzeugung für Upload-Skip o.a.;\nzwei unterschiedliche MUI-Oberflächen, je nach Geschmack; Einstel-\nlungs-Progamm für Grundeinstellungen; Bubble-Helps. Puffer-Joiner:\nPuffer werden zusammengefügt und Sorter-Speed drastisch erhöht! Mail-\nFilter: filtert Mails, die eingestellten Kriterien entsprechen. Wei-\nterleiten: Umleitung von ganzen Netzen und EMail-Adressen.\n@endnode\n\n@node skysetdata "SkySetData"\n\n@{b}SkySetData@{ub} - Setzt kaputte Boxstatistiken auf ihren alten Zustand.\n~~~~~~~~~~\nManchmal passiert es, daß nach einem harten Absturz die Anruferzahl oder\nanderes auf 0 zurückgesetzt worden ist, was natürlich sehr ärgerlich ist.\nMit SkySetData kann man diese Boxstatistiken-Daten auf ihren ursprüngli-\nchen Wert zurücksetzen. Möglich sind Gesamtanrufer, Netzanrufer, Uploads\nund Downloads. Das Programm läßt sich komfortabel über die Shell bediehen.\n@endnode\n\n@node skylastcaller "SkyLastCaller"\n\n@{b}SkyLastCaller@{ub} - Zeigt die bisherigen Tagesanrufer und Statistiken.\n~~~~~~~~~~~~~\nSkyLastCaller ersetzt den trostlosen Standard-Befehl "Protokoll" von\nPrometheus. Es stellt die bisherigen Tagesanrufer in Form und Farbe\ntabellarisch dar und bringt außerdem noch interessante statistische\nErgebnisse mit. SkyLastCaller verfügt auch über eine Konfiguration.\n@endnode\n\n@node skysetdupecheck "SkySetDupeCheck"\n\n@{b}SkySetDupeCheck@{ub} - DupeCheck für jede einzelne Box/Point an-/abschalten!\n~~~~~~~~~~~~~~~\nOft dauert der DupeCheck beim Prometheus-Sorter eine Ewigkeit,\nwenn große Puffer sortiert werden. Bei manchen Systemen kann so\nein DupeCheck überflüssig sein, da von diesen vielleicht keine\ndoppelten Mails hereinkommen können.\nSkySetDupeCheck erlaubt es nun, den DupeCheck für jede einzelne\nangeschlossene Box bzw. Point abzuschalten und somit die Sorter-\ngeschwindigkeit um ein Vielfaches zu erhöhen.\nDes weiteren kann man das Umgekehrte veranlassen, nämlich daß die\nKennungen der Mails von bestimmten Systemen gar nicht erst erfaßt\nwerden und deshalb beim Einsortieren nicht geprüft werden.\n@endnode\n\n@node skylister "SkyLister"\n\n@{b}SkyLister@{ub} - Erstellt Filelisten im AmigGuide und HTML-Format!\n~~~~~~~~~\nSkyLister ist ein Filelisten-Generator, der eine Fileliste von\nbeliebigen Box-Brettern erzeugt. Und zwar entweder im AmigaGuide\noder im modernen und formschönen HTML-Format! Der Liste kann\neine Hauptmenü-Gestaltung sowie weitere Dokumente angehängt\nwerden. Die HTML-Version läßt alle Arten von zusätzliche Daten\nzu (z.B. Bilder, Animationen). Die fertige Liste wird gepackt\nund in ein einstellbares Brett gelegt. Beide Programm-Versionen\nbesitzen getrennte Konfigurationen, die komfortabel über einen\nMUI-Einsteller bearbeitet werden.\nMit dieser Software wird die Fileliste Ihrer Mailbox zu einem\nhochmodernen Angebot, das Ihren Usern massig Freude bereiten\nwird!\n@endnode\n\n@node skylogoffkom "SkyLogOffKom"\n\n@{b}SkyLogOffKom@{ub} - Läßt Logoff-Kommentar eingeben. Mit Zensier-Funktion!\n~~~~~~~~~~~~\nMit SkyLogOffKom kann jeder User einen Logoff-Kommentar eingeben,\nder dann beim Login angezeigt wird. Alle eingegebenen Kommentare\nwerden mit User-Angabe in eine Protokoll-Datei geschrieben. Es\nkönnen User für den Logoff-Kommentar gesperrt werden und Wörter\nkonfiguriert werden, die der User in seiner Eingabe nicht ver-\nwenden darf. Diese verbotenen Kommentare werden ebenfalls proto-\nkolliert.\n@endnode\n\n@node skywall "SkyWall"\n\n@{b}SkyWall@{ub} - Sprüche-Wall mit vielen Funktionen!\n~~~~~~~\nSkyWall ist eine Wall, an der jeder User seine Sprüche ablassen\nkann. Alle eingegebenen Sprüche werden protokolliert. Für jeden\nSpruch kann die Textfarbe sowie die -position angegeben werden.\nUser können für das Schreiben an der Wall gesperrt werden, und es\nkönnen Zeichenfolgenden konfiguriert werden, die die User in\nihrer Eingabe nicht verwenden dürfen. Diese verbotenen Kommentare\nwerden ebenfalls protokolliert.\n@endnode\n\n@node skychat "SkyChat"\n\n@{b}SkyChat@{ub} - Der funktionsreichste Chatruf für Prometheus!\n~~~~~~~\nSkyChat ist DER Chatter für das Prometheus Mailbox-System!\nMit seinen zahlreichen Funktionen stellt er das absolute MUSS\nfür jeden Sysop dar! Rufgeschwindigkeit, Standard-Gründe,\nfrei editierbare Texte, Nachricht hinterlassen, externer Modul-\nPlayer (Skripte für DeliTracker liegen bei), Modulauswahl,\nStandard-Modul, Paßwortabfrage (mit Start- und Endzeit, Anzahl\nder Versuche), Infomails für den Sysop (Textform oder tabella-\nrisch), MUI-Prefsprogramm, MUI-Rufoberfläche mit Fortschritts-\nanzeige, eigener Line- u. PseudoChat, Abwesenheitsgründe für\neinstellbare Zeiten, Konfigkonverter von KFVipChatPro!\n@endnode\n\n@node skymovebin "SkyMoveBin"\n\n@{b}SkyMoveBin@{ub} - Archiviert nach einem bestimmten Zeitraum die Filebase\n~~~~~~~~~~\nSkyMoveBin checkt die eingestellten Filebase-Bretter und kopiert\nbzw. verschiebt alle vorhandenen Files, die älter als die vorge-\ngebene Zeitspanne sind. Die Dateien kommen in andere Bretter, die\nebenfalls konfiguriert werden. Diese Files werden dort als neu\nbetrachtet.\nDie Software besteht aus zwei Versionen, wobei Version A die Da-\nteien verschiebt und Version B nur kopiert.\n@endnode\n\n@node skyaminetmirror "SkyAminetMirror"\n@{b}SkyAminetMirror@{ub} - Baut einen kompletten Mirror des Aminet auf!\n~~~~~~~~~~~~~~~\nDieses Softwarepaket ermöglicht es, einen kompletten Aminet-\nMirror aufzubauen, der mittels eines IP-Zugangs die neusten Files\naus dem Aminet holt. Den Dateien wird das aminettypische .read-\nme-File als Langen Kommentar angehängt und die Aminet-Kurzbe-\nschreibung als Kurzkommentar. So werden komfortable Datenpakete\ngeschaffen, die SkyAminetMirror in die Box-Filebase legt. Es sind\nviele Funktionen vorhanden; z.B. kann man festlegen, aus welchen\nAminet-Verzeichnissen nur Files geholt werden sollen. Die kom-\nplett automatische Ansteuerung für Miami liegt bei.\nDies ist die unregistrierte Demoversion von SkyAminetMirror!\n@endnode\n\n@node skyverteiler "SkyVerteiler"\n\n@{b}SkyVerteiler@{ub} - Listet Bretter und deren Verteilersysteme\n~~~~~~~~~~~~\nDieses Tool listet beliebige Bretter auf und zeigt deren\nVerteilersysteme. Die Anzeige kann auch auf einzelne Verteiler\nbeschränkt werden.\nDes weiteren kann man auch die Sortierung umkehren, also für\neinen oder mehrere Boxen/Points die bestellten Bretter anzeigen\nlassen.\nSkyVerteiler wird einfach in der Shell gestartet.\n@endnode\n\n','\n',char(10)),NULL,'auto-added',16958,4,0,NULL,NULL,'sky_vert','scan',1780048728);
INSERT INTO door_catalog VALUES('sky_vorw','SKY-VORW.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SKY-VORW.LHA','SkyVorwahl','XIM','SkyVorwahl',NULL,NULL,'SKY','| Type: AmiNet:comm/bbs                    | |                                          | | Desc: Area code database for users       |',replace('.------------------------------------------.\n| Type: AmiNet:comm/bbs                    |\n|                                          |\n| Desc: Area code database for users       |\n`------------------------------------------''\n','\n',char(10)),'SkyVorwahl.guide',replace('@database "SkyVorwahl.guide"\n@node main "SkyVorwahl V1.3 - © 2/1997 Matthias Kaulartz"\n\n                               @{b}SkyVorwahl V1.3@{ub}\n                               ~~~~~~~~~~~~~~~\n                         @{i}2/1997 by Matthias Kaulartz @{ui}\n\n    @{"Einführung      " link einführung   }  Was ist SkyVorwahl?\n    @{"Was ist neu?    " link neu          }  Änderungen der neuen Version\n\n    @{"Installation    " link installation }  Das Einbinden in Prometheus\n\n    @{"Programmstart   " link programmstart}  Der Aufruf\n\n    @{"Rechtliches     " link rechtliches  }  Copyright und Registrierung\n    @{"Danksagungen    " link greets       }  Danksagungen und Grüße\n\n    @{"Support         " link support      }  Wo bekommt Ihr Support?\n    @{"Weitere SkyTools" link skytools     }  Was gibt''s noch?\n    @{"Das Sky-Netz    " link skynetz      }  Für Euch alle!\n\n\n@{b}>>>  Die brandneuste, bugfreie Version von SkyVorwahl ist immer in  <<<\n>>>  der SkyFly Mailbox zu erhalten und natürlich auch für Gäste!  <<<\n>>>                        +49-6341-969295 (Ringdown)              <<<@{b}\n@endnode\n\n@node einführung "Einführung"\n\n@{b}Einführung@{ub}\n~~~~~~~~~~\nEinfach eine Vorwahl eingeben, schon erscheint der zugehörige\nOrt. Ebenso auch umgekehrt: Man gibt einen Ort oder ein Land oder\nirgendein Muster an und nach der/den entsprechenden Vorwahl(en)\nwird gesucht. Das Ergebnis wird auf dem Bildschirm ausgegebn und\nkann zusätzlich als Textfile downgeloaded werden.\nDie Datenbank enthält alle Vorwahlnummern Deutschlands, interna-\ntionale Landesvorwahlen, die der Bundesstaaten der USA und von\ngrößeren amerikanischen Städten. Außerdem sind die Service-\nNummern der Telekom enthalten.\n@endnode\n\n@node neu "Was ist neu?"\n\n@{b}History@{ub}\n~~~~~~~\n@{b}1.3 - 22.02.97@{ub}\n~~~~~~~~~~~~~~\n- Man kann nun mehrmals eine Eingabe tätigen, ohne das Programm jedesmal\n  neu aufzurufen.\n- Auf die Zeilenzahl des Users wird nun geachtet und dementsprechend nach\n  jeder Seite pausiert.\n\n@{b}1.2a - 20.02.97@{ub}\n~~~~~~~~~~~~~~~\n- kein "Datenträger HD0:"-Bug mehr.\n\n@{b}1.2 - 18.02.97@{ub}\n~~~~~~~~~~~~~~\n- Downloadroutine ist jetzt wieder einwandfrei.\n- Download-Abfrage wird nun voreingestellt auf verneinend gesetzt.\n- Die Gebührenzone vom Standord der Mailbox bis zu der angezeigten Nummer\n  wird angezeigt. Hierbei wird auf die Vorwahlzonen von Prometheus zurück-\n  gegriffen - wenn sie vorhanden sind.\n- Das voreingstellte Muster vervollständigt korrekterweise nur die Endung\n  der angegebenen Nummer.\n\n@{b}1.1 - 31.01.97@{ub}\n~~~~~~~~~~~~~~\n- Bad Salzungen der Datenbank zugefügt.\n- Aufhänger beim Download vorrübergehend entfernt.\n@endnode\n\n@node installation "Installation"\n\n@{b}Installation@{ub}\n~~~~~~~~~~~~\nDiesmal habe ich auf einen Installer verzichtet - aufgrund der kleinen Größe des\nTools. Man gehe wie folgt vor:\n\n1. Verzeichnis anlegen: @{i}SkyTools:SkyVorwahl @{ui}\n   Wer das SkyTools-Assign noch nicht hat, der baut es in die User-Startup\n   oder sonstwo ein. Beispielsweise kann man es auf @{i}Prometheus:SkyTools @{ui}legen.\n\n2. @{i}SkyVorwahl@{ui}, @{i}SkyVorwahl.guide @{ui}und @{i}SkyVorwahl.dat @{ui}in dieses frisch\n   erzeugte Verzeichnis reinkopieren.\n\nSo, die Files wären installiert. Jetzt wird SkyVorwahl als Online-Befehl in\nPrometheus eingebaut. Hierzu wird der Befehlseditor gestartet und folgende\nKonfiguration übernommen:\n\n@{b}Name@{ub}:         Vorwahl\n@{b}Beschreibung@{ub}: @{i}Vorwahldatenbank @{ui}oder etwas in der Richtung...\n@{b}Parameter@{ub}:    Run SkyTools:SkyVorwahl/SkyVorwahl $PO\n@{b}Gruppe@{ub}:       So, daß keiner drankommt... (war nur Scherz ;)\n@{b}Typ@{ub}:          "Text"? Nein, nehmen wir "ARexx/Library"\n@{b}Shortcut@{ub}:     Am besten 2 oder 3 oder 4...\n@{b}Befehl@{ub}:       Klar\n@{b}Extern@{ub}:       Aktiv oder nicht aktiv, das ist hier die Frage bzw.\n              kann ganz nach Euren Wünschen geschehen.\n@endnode\n\n@node programmstart "Programmstart"\n\n@{b}Programmstart@{ub}\n~~~~~~~~~~~~~\nEinfach starten, der Rest sollte klar sein. :)\n@endnode\n\n@node rechtliches "Rechtliches"\n\n@{b}Rechtliches@{ub}\n~~~~~~~~~~~\nTja, das übliche: Blabla, nix verändern, nix umbauen, nix patchen. Und laßt\nbloß das Copyright drin! ;)\n\nDieses Produkt hat unser Haus in bester Qualität verlassen. Die Qualitäts-\nprüfung wird unter ständiger Aufsicht von Dr. Brinkmann durchgeführt. Sollten\nSie dennoch Mängel vorfinden, genießen Sie unsere vollste Rückgabegarantie.\nDr. Oetker wird sich freuen...\n\n@{b}Dieses Programm ist RegisterWare! Also, schnell in der SkyFly einloggen und\nden RegisterMan starten (im Extern-Menü auswählen oder im GeoNet "Reg"\neintippen). Dann bekommt Ihr eine Art persönliches kleines KeyFile geschickt\nund SkyVorwahl läuft! :-)@{ub}\n\nGarantien für das Programm kann ich von rechtlicher Sicht aus leider keine\nübernehmen, sonst gibt''s vielleicht noch Haue... Aus jeglicher sonstiger Sicht\ntue ich das aber, denn es ist fehlerfrei (zumindest solange, bis man es nicht\nprovoziert).\n\nFindet ihr trotzdem noch den einen oder anderen kleinen Bug, sagt''s mir bitte.\n\nIhr wißt: Ich liebe Euch alle!\n\n(PS: Kleine Anmerkung: Bleibt unserer gemeinsamen Freundin treu!)\n@endnode\n\n@node support "Support"\n\n@{b}Support@{ub}\n~~~~~~~\nUpdates hiervon gibt''s im @{"SkyNetz" link skynetz} und auch in der @{"SkyFly" link skyfly}. Dort könnt Ihr Euch\nnatürlich auch als Gast den Stuff ziehen. Daß dort auch immer die allerneuste\nVersion liegt, ist Ehrensache.\n\nFragen, Kritik, Vorschläge, Freundin zu vergeben? -> @{"Ich" link autor} bin immer für Euch\nda!\n@endnode\n\n@node greets "Danksagungen & Grüße"\n\n@{b}Danksagungen & Grüße@{ub}\n~~~~~~~~~~~~~~~~~~~~\n@{u}Herzlichen Dank für Vorschläge und Fehlerbeschreibungen an@{uu}:\n\nSunny@Circus\nJosh@Denzflor\n\n@{u}Gegrüßt werden folgende VVIP''s@{uu}:\n\n@{b}BliZZeR@{ub}\n@{b}Helena@{ub}\n@{b}Milena@{ub}\n@{b}Maria@{ub}\n@{b}Maike@{ub}\n\n@{u}Und diese VIP''s@{uu}:\n\nCyberfox, Arcus, Turrican, Monk, Panther, Thomas, Börni, Alex, Hightower,\nMihai (unsortiert)\n\n@{u}Und diese IP''s@{uu}:\n\nRest der Welt\n\n@{u}Und dieser Mensch@{uu}:\n\nMartin Brückner (für Prometheus)\n\n@{u}Und last but not least@{uu}:\n\nMutter, Vater, Markus, Michael\n@endnode\n\n@node autor "Autor"\n\n@{b}Autor@{ub}\n~~~~~\n                             Matthias Kaulartz\n                          Müller-Thurgau-Str. 13\n                               76829 Landau\n\n                             Tel: 06341-969297\n                             Fax: 06341-969296\n                  SkyFly Mailbox: 06341-969295 (Ringdown)\n                         EMail: [email removed]\n\n     Bankverbindung: Sparkasse SüW, Blz: 548 500 10, Kto: 13 5050 987\n@endnode\n\n@node skyfly "SkyFly Mailbox"\n                    .---------                         .---------------\n                   //         \                       //              /\n                  //     ___   \                     //     _________/\n                 //     /  \\   \                   //     /____\n .-----         //     /    \\___\                 //          /\n \\    \       //     /                           //     _____/\n  \\    \     //     / .---  .-- .--   .--       //     / .---   .--   .--\n   \\    \---./     / //  / // /// /--// /      //     / //  /  // /--// /\n    \\             / //  /// _///__   __/ .----./     / //  /  //__   __/\n     \\           / //  __  \    //  /    \\         / //  /____ //  /\n      \\_________/ //__/ \\__\  //__/      \\_______/ //_______///__/\n\n                                                                 __ __\n                                                    /\  /\/\ || |  |  |\ /\n                                                   /  \/  \-\|| |-<   | X\n                                                  /        \ \|_|__|__|/ \\n\n\n   P       U       R       E            P       O       W       E       R\n\n                     _  _              _   _   _   _   _   _\n                 _  (_  _) (_| |  __  (_) (_  (_)  _) (_) (_\n                (_) (_) _)   | |       _) (_)  _) (_   _)  _)\n                                 (Ringdown)\n\n                       V.32bis, V.32terbo, V.FC, V.34\n\n\n                                  N e t z e\n                   - -- --- -- ------ - - -- --- -- -----\n   ALT - AMIGACLUB - ANHALT - ANSI-ECKE - ASCII-NETZ - AUS - AQUARISTIK -\n BIONET - BLITZBASIC - CAAC-NETZ - CAMLEOT - CE-MARKT - CONSOLE-NET - CONVOY\n - CRYSTAL-NETZ - CL - COMP - CT - CYBER - DE - DFIDO - DOMINO - DT!-NETZ -\n E-NETZ - EAGLE-NETZ - EBL-NETZ - ENTERPRISE - ECSTASY-NET - FANTASTIC-NET -\n    FEUERWEHR - FLOHMARKT - FORMULA-ONE - HYPER-NET - INKA - KA - GELD -\n KAOS-NETZ - KF-NETZ - LIBERTY - LIFESTYLE - M-NET - MAUS - MAILBOX-TOOLS -\n NATUR - NEUSTADT - NETZWERK - PEGASUS - PLANETS - PLAYFIELD - PROMETHEUS -\n  PRONET - RADIONET - RAVE-NET - RAYTRACE-NET - REC - RHEIN-NETZ - SCHNEE -\n      SCHULE - SEEROSE - SKYNETZ - SOLINET - SOUNDNET - SPD - SPIDER -\n  SUPPORT-NETZ - T-NETZ - TOPNET - TREK-NET - TREKWORLD - TV-NET - Z-NETZ -\n                                     ZAK\n\n              **  V O L L S T A E N D I G E S   U S E N E T  **\n            **  I N K L U S I V E   B I N A E R E   A R E A S  **\n\n      Sechsmal täglich internationaler Mailverkehr direkt ins Internet\n       Zwölfmal täglich Netzaustausch zu Systemen in ganz Deutschland\n\n\n                           O n l i n e - G a m e s\n                   - -- --- -- ------ - - -- --- -- -----\n            TETRIS - FLOTTE - GLUECKSRAD - INQUISITION - KNIFFEL\n                NIMM - PAC - POKER - QUIRK - SCHACH - SLIDER\n\n                2-Spieler-Tetris: User<>Sysop & User<>User !\n\n\n         [hOME oF sKYtOOLS!] [hOME oF sKYtOOLS!] [hOME oF sKYtOOLS!]\n         [hOME oF sKYtOOLS!] [hOME oF sKYtOOLS!] [hOME oF sKYtOOLS!]\n\n\n                   ** Keinerlei Gebühren jeglicher Art! **\n\n  ------------------------------------------------------------------------\n  ***** KOSTENLOSE UND PRIVATE HOMEPAGE IM INTERNET FUER JEDEN USER! *****\n  ------------------------------------------------------------------------\n\n                                  CALL NOW:\n                     _  _              _   _   _   _   _   _\n                 _  (_  _) (_| |  __  (_) (_  (_)  _) (_) (_\n                (_) (_) _)   | |       _) (_)  _) (_   _)  _)\n                                 (Ringdown)\n\n                       V.32bis, V.32terbo, V.FC, V.34\n@endnode\n\n@node skynetz "SkyNetz"\n\n@{b}SkyNetz@{ub}\n~~~~~~~\n- Updates der SkyTools.\n- Infos, Hilfestellungen, Fragen & Antworten zu den Tools.\n- Bugreports und Vorschläge.\n- Vorschläge für weitere Tools sind gerne willkommen.\n- Kontakt zu anderen Sysops und gegenseitige Hilfe.\n- Diskussionen über alles alles mögliche.\n\nDas Netz kann direkt bei der @{"SkyFly" link skyfly} gepollt werden. Schreibzugriff\ngibt es mit einem bestätigten Netzantrag von [email removed].\n@endnode\n\n@node skytools "Die SkyTools"\n\n@{b}Die SkyTools@{ub}\n~~~~~~~~~~~~\n@{"AutoSend       " link autosend       }  Versendet automatisch Mails. Viele Optionen und GUI-Prefs.\n  10,- Registrierungsbetrag. Keinerlei Einschränkungen in der unregistrierten Version.\n@{"SkyMLGate      " link skymlgate      }  DAS Programm zum Führen von Mailing-Listen mit PmbS!\n@{"SkyPollKosten  " link skypollkosten  }  Wertet Netzanrufe aus und veranschaulicht die Gebühren.\n@{"SkyUseBin      " link skyusebin      }  UseBin-Soft, Puffer-Joiner, Mailfilter und Weiterleiter!!\n  10,- Sharewaregebühr. Die unregistrierte Version ist zeitlich beschränkt lauffähig.\n@{"SkySetData     " link skysetdata     }  Setzt kaputte Boxstatistiken auf ihren alten Zustand.\n@{"SkyLastCaller  " link skylastcaller  }  Zeigt die bisherigen Tagesanrufer und Statistiken.\n@{"SkySetDupeCheck" link skysetdupecheck}  DupeCheck für jede einzelne Box/Point an-/abschalten!\n@{"SkyLister      " link skylister      }  Erstellt Filelisten im AmigGuide und HTML-Format!\n@{"SkyLogOffKom   " link skylogoffkom   }  Läßt Logoff-Kommentar eingeben. Mit Zensier-Funktion!\n@{"SkyWall        " link skywall        }  Sprüche-Wall mit vielen Funktionen!\n@{"SkyChat        " link skychat        }  Der funktionsreichste Chatruf für Prometheus!\n  5,- Registrierungsbetrag. Bald 10,- Sharewaregebühr für unregistrierte Benutzer.\n@{"SkyMoveBin     " link skymovebin     }  Archiviert nach einem bestimmten Zeitraum die Filebase\n@{"SkyAminetMirror" link skyaminetmirror}  Baut einen kompletten Mirror des Aminet auf!\n  30,- Sharewaregebühr. Die unregistrierte Version ist nicht alleine lauffähig.\n@{"SkyVerteiler   " link skyverteiler   }  Listet Bretter und deren Verteilersysteme\n@{"SkyCookie      " link skycookie      }  Zeigt kleine Kuchen an... :)\n@{"SkyVorwahl     " link skyvorwahl     }  Vorwahlnummerndatenbank für die User\n@endnode\n\n@node autosend "AutoSend"\n\n@{b}AutoSend@{ub} - Versendet automatisch Mails. Viele Optionen und GUI-Prefs.\n~~~~~~~~\nAutoSend  ist - einfach ausgedrückt - ein Tool  zum automatischen Versenden\nvon Mails, beispielsweise Boxwerbungen, an beliebig viele Empfänger.\nAutoSend bringt dabei viele Features und Funktionen mit. Die Konfiguration\nkann komfortabel über ein Prefs-Programm vollzogen werden.\n@endnode\n\n@node skymlgate "SkyMLGate"\n\n@{b}SkyMLGate@{ub} - DAS Programm zum Führen von Mailing-Listen mit PmbS!\n~~~~~~~~~\nMLGate dient zum gaten von Mailing-Listen in die Mailbox, sodaß die Mails\nin Brettern gelesen werden können.\nWeiterhin funktioniert dies auch umgekehrt, d.h. die geschriebenen Mails\nin der Box werden in die Mailing-Liste weitergeführt.\n@endnode\n\n@node skypollkosten "SkyPollKosten"\n\n@{b}SkyPollKosten@{ub} - Wertet Netzanrufe aus und veranschaulicht die Gebühren.\n~~~~~~~~~~~~~\nSkyPollKosten wertet das Netz.prt von Prometheus aus und zeigt die\nPolls bei jedem System in den verschiedenen Tarifzonen, die Gesamtdauer\nder Polls, die Telefoneinheiten und die Kosten an.\nDiese Werte werden auch noch insgesamt angezeigt. Die Endsumme entspricht\ndann der Telefonrechnung der Telekom.\nAußer Polls bei anderen System können auch die Polls beim eigenen System\nberechnet und ausgegeben werden. Beides zusammen ist natürlich auch\nmöglich.\nFür jedes System kann in der Konfiguration die entsprechende Tarifzone\nangegeben werden, sodaß die Kosten korrekt ausgewertet werden.\n@endnode\n\n@node skyusebin "SkyUseBin"\n\n@{b}SkyUseBin@{ub} - UseBin-Soft, Puffer-Joiner, Mailfilter und Weiterleiter!!\n~~~~~~~~~\nKopiert alle eingehenden binären Files in Netzen nach frei definier-\nbare Bretter (z.B. zum Kopieren von Tools aus den Netzen in die lo-\nkale Filebase). Features: packen und repacken von Files; uudekodie-\nren; Musterübergabe für alle Einstellungen; Speicherbedarf und somit\nSpeed-Faktor einstellbar; Dupe-File Erzeugung für Upload-Skip o.a.;\nzwei unterschiedliche MUI-Oberflächen, je nach Geschmack; Einstel-\nlungs-Progamm für Grundeinstellungen; Bubble-Helps. Puffer-Joiner:\nPuffer werden zusammengefügt und Sorter-Speed drastisch erhöht! Mail-\nFilter: filtert Mails, die eingestellten Kriterien entsprechen. Wei-\nterleiten: Umleitung von ganzen Netzen und EMail-Adressen.\n@endnode\n\n@node skysetdata "SkySetData"\n\n@{b}SkySetData@{ub} - Setzt kaputte Boxstatistiken auf ihren alten Zustand.\n~~~~~~~~~~\nManchmal passiert es, daß nach einem harten Absturz die Anruferzahl oder\nanderes auf 0 zurückgesetzt worden ist, was natürlich sehr ärgerlich ist.\nMit SkySetData kann man diese Boxstatistiken-Daten auf ihren ursprüngli-\nchen Wert zurücksetzen. Möglich sind Gesamtanrufer, Netzanrufer, Uploads\nund Downloads. Das Programm läßt sich komfortabel über die Shell bediehen.\n@endnode\n\n@node skylastcaller "SkyLastCaller"\n\n@{b}SkyLastCaller@{ub} - Zeigt die bisherigen Tagesanrufer und Statistiken.\n~~~~~~~~~~~~~\nSkyLastCaller ersetzt den trostlosen Standard-Befehl "Protokoll" von\nPrometheus. Es stellt die bisherigen Tagesanrufer in Form und Farbe\ntabellarisch dar und bringt außerdem noch interessante statistische\nErgebnisse mit. SkyLastCaller verfügt auch über eine Konfiguration.\n@endnode\n\n@node skysetdupecheck "SkySetDupeCheck"\n\n@{b}SkySetDupeCheck@{ub} - DupeCheck für jede einzelne Box/Point an-/abschalten!\n~~~~~~~~~~~~~~~\nOft dauert der DupeCheck beim Prometheus-Sorter eine Ewigkeit,\nwenn große Puffer sortiert werden. Bei manchen Systemen kann so\nein DupeCheck überflüssig sein, da von diesen vielleicht keine\ndoppelten Mails hereinkommen können.\nSkySetDupeCheck erlaubt es nun, den DupeCheck für jede einzelne\nangeschlossene Box bzw. Point abzuschalten und somit die Sorter-\ngeschwindigkeit um ein Vielfaches zu erhöhen.\nDes weiteren kann man das Umgekehrte veranlassen, nämlich daß die\nKennungen der Mails von bestimmten Systemen gar nicht erst erfaßt\nwerden und deshalb beim Einsortieren nicht geprüft werden.\n@endnode\n\n@node skylister "SkyLister"\n\n@{b}SkyLister@{ub} - Erstellt Filelisten im AmigGuide und HTML-Format!\n~~~~~~~~~\nSkyLister ist ein Filelisten-Generator, der eine Fileliste von\nbeliebigen Box-Brettern erzeugt. Und zwar entweder im AmigaGuide\noder im modernen und formschönen HTML-Format! Der Liste kann\neine Hauptmenü-Gestaltung sowie weitere Dokumente angehängt\nwerden. Die HTML-Version läßt alle Arten von zusätzliche Daten\nzu (z.B. Bilder, Animationen). Die fertige Liste wird gepackt\nund in ein einstellbares Brett gelegt. Beide Programm-Versionen\nbesitzen getrennte Konfigurationen, die komfortabel über einen\nMUI-Einsteller bearbeitet werden.\nMit dieser Software wird die Fileliste Ihrer Mailbox zu einem\nhochmodernen Angebot, das Ihren Usern massig Freude bereiten\nwird!\n@endnode\n\n@node skylogoffkom "SkyLogOffKom"\n\n@{b}SkyLogOffKom@{ub} - Läßt Logoff-Kommentar eingeben. Mit Zensier-Funktion!\n~~~~~~~~~~~~\nMit SkyLogOffKom kann jeder User einen Logoff-Kommentar eingeben,\nder dann beim Login angezeigt wird. Alle eingegebenen Kommentare\nwerden mit User-Angabe in eine Protokoll-Datei geschrieben. Es\nkönnen User für den Logoff-Kommentar gesperrt werden und Wörter\nkonfiguriert werden, die der User in seiner Eingabe nicht ver-\nwenden darf. Diese verbotenen Kommentare werden ebenfalls proto-\nkolliert.\n@endnode\n\n@node skywall "SkyWall"\n\n@{b}SkyWall@{ub} - Sprüche-Wall mit vielen Funktionen!\n~~~~~~~\nSkyWall ist eine Wall, an der jeder User seine Sprüche ablassen\nkann. Alle eingegebenen Sprüche werden protokolliert. Für jeden\nSpruch kann die Textfarbe sowie die -position angegeben werden.\nUser können für das Schreiben an der Wall gesperrt werden, und es\nkönnen Zeichenfolgenden konfiguriert werden, die die User in\nihrer Eingabe nicht verwenden dürfen. Diese verbotenen Kommentare\nwerden ebenfalls protokolliert.\n@endnode\n\n@node skychat "SkyChat"\n\n@{b}SkyChat@{ub} - Der funktionsreichste Chatruf für Prometheus!\n~~~~~~~\nSkyChat ist DER Chatter für das Prometheus Mailbox-System!\nMit seinen zahlreichen Funktionen stellt er das absolute MUSS\nfür jeden Sysop dar! Rufgeschwindigkeit, Standard-Gründe,\nfrei editierbare Texte, Nachricht hinterlassen, externer Modul-\nPlayer (Skripte für DeliTracker liegen bei), Modulauswahl,\nStandard-Modul, Paßwortabfrage (mit Start- und Endzeit, Anzahl\nder Versuche), Infomails für den Sysop (Textform oder tabella-\nrisch), MUI-Prefsprogramm, MUI-Rufoberfläche mit Fortschritts-\nanzeige, eigener Line- u. PseudoChat, Abwesenheitsgründe für\neinstellbare Zeiten, Konfigkonverter von KFVipChatPro!\n@endnode\n\n@node skymovebin "SkyMoveBin"\n\n@{b}SkyMoveBin@{ub} - Archiviert nach einem bestimmten Zeitraum die Filebase\n~~~~~~~~~~\nSkyMoveBin checkt die eingestellten Filebase-Bretter und kopiert\nbzw. verschiebt alle vorhandenen Files, die älter als die vorge-\ngebene Zeitspanne sind. Die Dateien kommen in andere Bretter, die\nebenfalls konfiguriert werden. Diese Files werden dort als neu\nbetrachtet.\nDie Software besteht aus zwei Versionen, wobei Version A die Da-\nteien verschiebt und Version B nur kopiert.\n@endnode\n\n@node skyaminetmirror "SkyAminetMirror"\n@{b}SkyAminetMirror@{ub} - Baut einen kompletten Mirror des Aminet auf!\n~~~~~~~~~~~~~~~\nDieses Softwarepaket ermöglicht es, einen kompletten Aminet-\nMirror aufzubauen, der mittels eines IP-Zugangs die neusten Files\naus dem Aminet holt. Den Dateien wird das aminettypische .read-\nme-File als Langen Kommentar angehängt und die Aminet-Kurzbe-\nschreibung als Kurzkommentar. So werden komfortable Datenpakete\ngeschaffen, die SkyAminetMirror in die Box-Filebase legt. Es sind\nviele Funktionen vorhanden; z.B. kann man festlegen, aus welchen\nAminet-Verzeichnissen nur Files geholt werden sollen. Die kom-\nplett automatische Ansteuerung für Miami liegt bei.\nDies ist die unregistrierte Demoversion von SkyAminetMirror!\n@endnode\n\n@node SkyVerteiler "SkyVerteiler"\n\n@{b}SkyVerteiler@{ub} - Listet Bretter und deren Verteilersysteme\n~~~~~~~~~~~~\nDieses Tool listet beliebige Bretter auf und zeigt deren\nVerteilersysteme. Die Anzeige kann auch auf einzelne Verteiler\nbeschränkt werden.\nDes weiteren kann man auch die Sortierung umkehren, also für\neinen oder mehrere Boxen/Points die bestellten Bretter anzeigen\nlassen.\nSkyVerteiler wird einfach in der Shell gestartet.\n@endnode\n\n@node skycookie "SkyCookie"\n\n@{b}SkyCookie@{ub} - Zeigt kleine Kuchen an... :)\n~~~~~~~~~\nSkyCookie gibt einen zufälligen Spruch, Witz, Murphy-Message oder\nwas auch immer auf dem Port-Screen für den eigeloggten User aus.\nEin schönes Layout ist inklusive (ohne Werbung :). Die Sprüche\nwerden in einer Konfigurationsdatei festgehalten. Übrigens sind\nLeerzeilen in den Sprüchen möglich, auf eine Taste kann gewartet\nwerden, der Bildschirm kann vor der Ausgabe gelöscht werden und\ndie Ausgabe kann zentriert erfolgen.\n@endnode\n\n@node skyvorwahl "SkyVorwahl"\n\n@{b}SkyVorwahl@{ub} - Vorwahlnummerndatenbank für die User\n~~~~~~~~~~\nEinfach eine Vorwahl eingeben, schon erscheint der zugehörige\nOrt. Ebenso auch umgekehrt: Man gibt einen Ort oder ein Land oder\nirgendein Muster an und nach der/den entsprechenden Vorwahl(en)\nwird gesucht. Das Ergebnis wird auf dem Bildschirm ausgegebn und\nkann zusätzlich als Textfile downgeloaded werden.\nDie Datenbank enthält alle Vorwahlnummern Deutschlands, interna-\ntionale Landesvorwahlen, die der Bundesstaaten der USA und von\ngrößeren amerikanischen Städten. Außerdem sind die Service-\nNummern der Telekom enthalten.\n@endnode\n\n','\n',char(10)),NULL,'auto-added',55387,4,0,NULL,NULL,'sky_vorw','scan',1780048728);
