INSERT INTO door_catalog VALUES('slctp2_2','SLCTP2_2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SLCTP2_2.LHA',NULL,'XIM','slicktop2.2','2.2',NULL,'SLCTP2','#MAJOR UPDATE TO THE WORLDS BEST TOP U/LRS # #DOOR.    FEATURES INCLUDE:                # #OVERALL , SEPRATE CONF , MIXED LISTS, ECT #',replace('##############SLICKTOP V2.2#################\n#MAJOR UPDATE TO THE WORLDS BEST TOP U/LRS #\n#DOOR.    FEATURES INCLUDE:                #\n#OVERALL , SEPRATE CONF , MIXED LISTS, ECT #\n#CAN EVEN TAKE 2 SPECIFIED CONFS ADD THEM  #\n#AND MAKE A TOP U/L LIST FOR THE SPECIFIED #\n#CONFS ONLY!, OVERALL 13 DIFFRENT OUTPUTS  #\n#CAN CREATE ALL YOUR BULL NEEDS! GET IT NOW#\n###NOT A RENAME COMES DIRECT FROM WRITER!###','\n',char(10)),'DefenderoftheAddy.guide',replace('@database "ByTeR¡DeRs - A CODERS DREAM COMES TRUE!"\n@Node MAIN "ByTeR¡DeRs"\n\n                  Byteriders BBS - There can be only ONE!\n\n                       ZIG ZAG CORPORATION GERMAN HQ\n\n                 Sysops: Joker/ZZC        - Ernesto/RDC\n                         Illuminator/Indy - Jazzytech/TLS     \n\n Special greetings to @{"PBX&MCI" link "MCI"} who were so nice to actually\n         TAKE this addy here and ADD their name instead of mine...\n    As excuse for it MCI said he thought it was an add from an foreign\n    country and because of that he thought it wouldn´t hurt to use it.\n   So it seems we have to live with at least two of those addies now. :)\n      Maybe I should start to write "crack-addies" for some groups...\n    But remember the original one is only the one with this dot! ---> ·\n\n                        @{" Why should I call this BBS? " link "menu"}                   \n@endnode\n\n@node "menu" "ByTeR¡DeRs - Coders Paradise"\n@toc "menu"\n\n          This BBS is especially set up for coders, phreakers and\n          and people who know how to use their computer for more\n          than just stupid games.\n\n           Among other things, you will find here the following:\n           -----------------------------------------------------\n\n- Famous coders\n- HPA-Elite from all over the world\n- Some very talented crackers\n- 50+ Megs of Docs online\n  available for download\n- Tons of backdoor-free\n  (personally checked!) /X-tools\n- Many sourcecodes, coding tools and beta-versions\n  of not yet released tools and games\n- About 3 Gigabyte software for\n  Amiga, SNES, Gameboy from 1986 - today,\n  either online or requestable within minutes!\n- Public Domain software + the normal 0 day Elite wares\n- Nice sysops without any attitude problems\n- No hassle with ratios - every user gets a disabled!\n- Backup Units for Super Nintendo Entertainment System (SNES)\n- Cheap CC abos from the best hackers worldwide\n\n            Question: "How do I get the number?"\n            Answer:   "You don´t. If we feel you belong here, \n                       we will invite you."\n\n@endnode\n@node "MCI" "Special greetings to PBX&MCI/MST"\n@toc "MCI"\n\n       Soll ich diese lächerliche Drohung mit dem "BBS-Schaden" etwa\n         ernst nehmen? Dann bist Du wirklich lamer als ich dachte!\n       By the way, Ich wusste noch gar nicht dass Du die lines von \n     Foxx´s Den blockiert hattest! Schätze Du hast das so gut gemacht,\n             dass es nicht mal Foxx selbst auffiel. Heheheh. \n     Lass´ die Kindereien, für sowas sollten wir beide zu alt sein...\n     Interessant übrigens, dass Du Deine BBS als aktueller einstufst,\n                    ohne meine überhaupt zu kennen.. :)\n\n@endnode\n','\n',char(10)),NULL,'auto-added',30318,3,0,NULL,NULL,'slctp2_2','scan',1780048732);
INSERT INTO door_catalog VALUES('slha31','SLHA31.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SLHA31.LHA','LhA','XIM','LhA',NULL,NULL,NULL,'¦  Super LhA Checker Professional V3.1   ¦ ¦  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~   ¦ ¦   The far most advanced utility ever   ¦',replace('.----------------------------------------.\n¦  Super LhA Checker Professional V3.1   ¦\n¦  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~   ¦\n¦   The far most advanced utility ever   ¦\n¦ made. Lightning fast with many options ¦\n¦----------------------------------------¦\n¦  You have NEVER seen anything like it! ¦\n¦                                        ¦\n`-----( Copyright © 1993-95 fAktOR )-----''\n','\n',char(10)),'LhaChecker.doc',replace('\n\nSuper LhA Checker Professional V3.1\nCopyright © 1993-95 fAktOR.  All rights reserved.\nCommercial use of this unregistered program is prohibited.\n\n\n\n\nThank you for using the most advanced LhA Utility ever made.\n============================================================\n\n\n.\n\n\n\nHistory of updates:\n~~~~~~~~~~~~~~~~~~~\nLhAChECK''O''MaNIA vo.o2		- The first public release. It was enormous\n				  bug-full. Just a simple but fast LhAchecker\n\nLhaChecker v1.o			- New release within The Vikings.\n				  Added a buffered I/O routine.\n				  Now Icon-Based configuration.\n\nLhaChecker v2.o			- Added FileID Line-Adding.\n				  Much faster checking.\n\nLhaChecker v2.1			- Bug found. Didn''t close the icon.library.\n				  Bug found. A loss of 516 bytes each time\n				  the utility was executed. Fixed!\n\nSuper LhA Checker v3.0		- Added selective path to LhA.\n				  the util would crash if the config-file\n                                  was not found. Fixed. If a file didn''t\n				  contained a file_id.diz and the checker\n				  tried to add a liner into it, it would\n				  create a empty FileID.Diz. Fixed!\n                                  Minor bugs cleaned up.\n\nSuper LhA checker Pro v3.1	- Now you can add a FileID Liner in top of\n				  the FileID itself.\n				  Added a new function to list the contained\n				  files within the archive.\n				  Slightly faster code. Now removed all the\n				  optimizing to ensure safty on ALL amigas.\n\n\nConfiguration:\n~~~~~~~~~~~~~~\n\nADD=Y/N\n\nCHECK=Y/N\n\nREMOVE=Y/N\n\nLHA=Path to LhA; i.e ''c:lha''\n\nFileID_TOP=  This is the line which will appeare above the FileID\n\nFileID_END=  This is the line which will appeare below the FileID\n\nLIST=Y/N\n\nSHOW_FILEID=Y/N\n\nSCRIPT=path to script file. MUST be a script file (protect file +s)\n\nBUFFER=Number of Kilobytes; i.e ''128''\n\nWork=Device; i.e DH0:\n\n\n\n\n\nIf you have any questions, then don''t hesitate to give me a message at\nfollowing boards: (Faktor & Trance)\n\n			INTERCHANGE\n			EVERYWARE\n			SKY TOWER\n			and the rest...\n\n-EOF-\n','\n',char(10)),NULL,'auto-added',47117,5,0,NULL,NULL,'slha31','scan',1780048732);
