INSERT INTO door_catalog VALUES('slktop23','SLKTOP23.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SLKTOP23.LHA','USE_ME_TO_VIEW_OUTPUTS','XIM','USE_ME_TO_VIEW_OUTPUTS',NULL,NULL,NULL,'#    SLICK TOP 2.3 NEW UPDATE! XIM DOOR    # *                                          * #  Worlds BEST top u/l d/l list for ANY /X #',replace('*#*#*#*#*#*#*#*#*#*#*#*#*#*#*#**#*#*#*#*#*#*\n#    SLICK TOP 2.3 NEW UPDATE! XIM DOOR    #\n*                                          *\n#  Worlds BEST top u/l d/l list for ANY /X #\n*    can do overall top u/l d/l list       *\n#    or seprate Confs u/l d/l list         #\n*or even combined mixture of diffrent confs*\n#       now with 14 DIFFRENT outputs!      #\n*    can create all you Bulletin needs!    *\n*#*#*#*#*#*#*#*#*#*#*#*#*#*#*#**#*#*#*#*#*#*','\n',char(10)),'mastrb8.txt',replace(replace('STILL GOING STRONG in 2014!\r\n\r\n                ___         ._            _______             ·\r\n   /\  _________)  \________| \___________)__   /_________:__ :________\r\n  /  \/\  __  \    ____ ___/|  \______  \_  / _/___  \_ ____/ ¦__ \___ \\r\n /   /  \ \__  \___  \  |   |   \  _/  __/ /    /\__  \  |¦   | /  \_|  \\r\n/  \/    \_ \   \ !   \_|   !    \_\    \_     /   \   \ ||   |·    /|   \_\r\n\___|     ___\  /__    /l________ /_\    /__  /_____\  / |¦   |    /_|    /\r\n    l____/-A×E\/  \___/_!       \/   \  /   \/       \/__|:   ¦__ /  l___/\r\n       ______            _____        \/      :    ____   ·   : \/\r\n    ___)     \___________)    \__________:___ ¦____)   \__________\r\n    \    _______     _______    \___    ____/ |\_____   \______   \\r\n   /\___   \/        |    _)    \/       ¦    |/    |    \    |    \\r\n _/    !    \        |    \      \_      |    |     !     \   |     \\r\n \______     \___    |_____\      /___   |    ¦            \  |      \_\r\n       \______/ \____!      \    /   \___|    :________     \_|       /\r\n                             \  /        ¦    ·       \______/|      /\r\n   YOUVE HEARD