INSERT INTO door_catalog VALUES('slkviw20','SLKVIW20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SLKVIW20.LHA','DMS','XIM','DMS',NULL,NULL,NULL,'*     SLICKVIEW V2.0 ** NEW UPDATE **      # #''V'' Replacement door! view all filetypes  * *lha/dms/txt/doc/exe/ ect even a Hex output#',replace('#*#*#*#*#*#*#*#*#*#*#*#*#*#*#*#*#*#*#*#*#*#*\n*     SLICKVIEW V2.0 ** NEW UPDATE **      #\n#''V'' Replacement door! view all filetypes  *\n*lha/dms/txt/doc/exe/ ect even a Hex output#\n#automaticly figures out the filetype and  *\n*if it doesnt know it will ask you how to  #\n#view it.                                  *\n*sysops can also view from any hd path!    #\n#Another completly cool SLICK tool!!       *\n*#*#*#*#*#*#*#*#*#*#*#*#*#*#*#*#*#*#*#*#*#*#','\n',char(10)),'slickview.doc',replace('  \n\n                         SLICKVIEW 1.0 by BUGBYTE!\n\n\n            Completely important DOCS by The Minstrel/TRZ/LIT!\n\n                     --------TABLE OF CONTENTS--------\n\n\n1..................What the hell is it?\n\n2..................Why the hell do you need it?\n\n3..................Who suffers if you dont like it?\n\n4..................Arent these DOCS cool?\n\n5..................INSTALLATION\n\n6..................AFTER INSTALLATION\n\n7..................Why are SlickUtils the best?\n\n8..................Greets\n\n9..................FUCK OFFS\n\n10.................Contacts\n\n\n-------------------------------------------------------------[1]----------\nWhat the hell is it?\n\n	Slick View is a VERY powerful and configurable file viewer, which\n\nallows a user to read (or examine the contents of) a file.. SlickView can \n\nview many different file types, from actually displaying text files, and hex \n\ndisplaying .EXE files, it can also display the contents of an archive\n\n(LHA,LZH,ZIP,DMS,ect..) \n\n\n--------------------------------------------------------------[2]--------\nWhy the hell do I need it?\n\n	Users can use Slickview to view the contents of a certain archive, \n\nto get the full expanded file size, or use the program to simply view \n\ntext files.. The possibilities are ABSOLUTELY ENDLESS!!! Sysops and Subops\n\n(access level defined in the .info file) may view ANY files in the system \n\nthrough the HD path, regular users may only view files listed in the \n\nconference that they are in..\n\n----------------------------------------------------------------[3]------\nWho suffers if you dont like it?\n\n	The programmer of this software, BUGBYTE, has been assigned to the\n\ntask of making the worlds SPIFFIEST file viewer, which he HOPES he has\n\naccomplished. BUT, if for some unexplained reason, a user does NOT like\n\nthe program, or a Sysop using the program happens to view a file that he does \n\nnot agree with, this user may contact the programmer, at ANY time day or night\n\nand does have full permission to flog the programmer (BUGBYTE) at ANY time,\n\nday or night..\n\n\n----------------------------------------------------------------[4]--------\nArent these DOCS cool?\n\n	Are these not like the COOLEST docs you have ever seen? NO?!? Piss off!\n\nThe professional (yet slightly warped) DOC writer has spent MANY precious \n\nminutes preparing this wonderful document for your informational purposes, out\n\nof the goodness of his heart! (and he needed the money!) Please support your\n\nlocal DOC writer by buying him a new system, on which he may continue to write\n\ninformative, and useful DOCS for all your favorite programs, which the original\n\nprogrammers are just too damn lazy to do. If this sounds like alot of\n\nbullshit.... Well, it actually is.. OK there, I''ve said it..\n\n\n-----------------------------------------------------------------[5]------\nINSTALLATION\n\n	OK, before you stop reading this BULLSHIT doc, I suppose I''d better\n\nshow you how to get this amazing program to run on your machine.. The \n\ninstructions MUST be followed WORD FOR WORD, or MAJOR damage may occur \n\n(Dont believe him, hes full of shit!) to your system, your family, and your\n\ndog.. OK first, you must extract the archive.. This must be done with a \n\nprogram that extracts archives.. If you do not have one of these programs,\n\nI may be able to find you a good deal on a used IBM, that may be more \n\nsuitable for you! ;)  Now, you must move the files into their appropriate\n\nDIRS on your system. This may be difficult if you are not an experienced\n\nunderwater welder.. (For those of you who are lost, I will put it another\n\nway, Put the files in C  into your C:. Next put the files that came in\n\nDOORS dor into your DOORS:. If you made it that far, place the files\n\nthat came in COMMANDS into your bbs:commands dir.. G00D JOB!) After that,\n\nedit the tooltypes in your doors:slickview/slickview.info, and put your paths \n\nto your upload dirs for each conference in the icon.. This should be all you\n\nneed to run.. Now, sit back, have a drink, and press V from the prompt!! \n\n\n---------------------------------------------------------------[6]------\nAFTER INSTALLATION\n\n	After you see all your hard work pay off, its now time to repay \n\nyourself for all that hard work.. Get yourself a big tall glass of beer, or\n\nwhatever you like to get fucked up on, listen to some great music (whatever\n\nyou happen to listen to) and think about how great those darn DOCS were, \n\nand how you would NEVER have gotten the program to work without them..\n\nPlease dont get sick!\n\n\n-----------------------------------------------------------------[7]-----\nWhy are SLICKUTILS the best?\n\n	They are the best because they are coded by BUGBYTE! Why the fuck is\n\nTHAT so important?? Because I (the GOD of DOCS) say so!!!\n\n\n\n     ==----------------------GREETS!!!!!!---------------------------==\n\nThe Minstrel			    (i write the doors you do the dox :) )\nBIG BOSS                            (Thanx For The Help Man 		 )\nINDIO/CSL                           (wibble wibble!			 )\nYSL/CSL                             (speak up! heheh			 )\nSamir				    (Yo dewd chat toya soon thanx for TRZ)\nTIN MAN                             (ill get ya back you know what i mean)\nFLUX			 	    (thanx dewd for all you have done    )		\nSCOTT				    (stick em up!			 )\nANIMAL                              (alrite calm down!			 )\nYEKO				    (things will work out!		 )\nJERKY                               (miss ya man!			 )\nSHOCK				    (glad ya with us man :)		 )	\nCARDINAL			    (Hi dewd				 )\nBLASTER                             (sysop x-factor cool board dewd	 )\nJACKNIFE                            (call DD soon for a chat		 ) \nNAZGUL                              (been a long time! ill be seying ya  )\nSNAKE     			    (keep a eye on naz heh		 )	  \nNOXOUS (humm)                       (Hummmmm !!				 )\nLAVIATHON                           (thanx for the help dewd :) 	 )\nKEN D 				    (cya on DD				 )\nPOLARIS                             (we need to chat call dd 		 )\nMARIO                               (COOL trader!			 )\nSLEDGE				    (i want more time!!! on ph!		 )	\nRAPTOR				    (nice to have ya with us homi!	 )	\nROTOR                               (thanx for the spelling lessons :)   )\nLector				    (Hi dewd!! didnt forget ya this time!)\n			\n\n\n\n        +++++A BIG FROSTY FUCK YOU! GOES OUT TO THESE SCUMBAGS!!+++++\n\nummm i am friends with everyone really :))\n','\n',char(10)),NULL,'auto-added',162297,5,0,NULL,NULL,'slk_v1_0','scan',1780048732);
