INSERT INTO door_catalog VALUES('smartbnk','SMARTBNK.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SMARTBNK.LHA',NULL,'XIM','SmartBank.XIM','1.0','Calypso/GOD',NULL,'Yeah, check this out ! Let''s you move 0-100% of the global bytes to the current conference !',replace('SmartBank V1.0 by Calypso/GOD !\n \nYeah, check this out ! Let''s you\nmove 0-100% of the global bytes to the\ncurrent conference !\n \nLet''s you switch to conf-accounting,\nclear confs, whatever... great !\n \nRead docs... enjoy !\n','\n',char(10)),'SmartBank.Doc',replace('\n             .------------------------------------------------.                \n._________   | ________   ___:_  ____________.________________:_ _________     \n|\   ____/___:_\______ \_/   |___\____ \_    | ____     / _____/_\    ___/_____\n|    \/       /   ___/  ¬|   |       /_____  | \ \/    /____     /    \/      /\n|___         /    \|¯ ___|____      /   _____| _\_____/   \/    /_           / \n  ¯\________/\_______/aC!    ¯\____/___/¯   : _\/_|   ___      / ¯\_________/  \n             :                                \/\/       \____/-TRE!           \n             `------------------------------------------------''\n\n                                 PRESENTS\n\n                  -=> SmartBank V1.0 - ASM XIM DOOR <=-\n\n    PROFESSIONAL TOOLS FOR PROFESSIONAL SYSOPS - GET THE REAL QUALITY !\n\n\nWHAT''S THE USE OF THIS TOOL ?\n-----------------------------\n\n        This door moves a specified amount of Credits/FileNumbers\n        to the current conference !\n\n        You have to enter how many percent you want to move,\n        0-100% !\n\n        So you can clear conferences (0%) or if you want to use\n        conf-accounting you can set the credits for your conferences,\n        e.g. 70% Amiga, 30% Console !\n\n        Works on S-Express V0.39n+ and /X3.x+ !\n\n        This is fucking great, enjoy !\n\n        To see how it works, you can use two of my utils...\n        Use BESTUL to see global creds, move 50% to a conf, call\n        BESTCONF and you see that everyone has 50% of the global creds,\n        nice, eyh ?\n\n        If you notice big amounts (around 2GIG) or negative amounts,\n        then check with your account ed if some user has negative creds !\n        (Maximum bytes possible is about 2.147 GIG, this is what fits\n        in 31Bit)\n\n  .-----------------------------------------------------------------------.\n  |       PLEASE READ THE REGISTER!.TXT INCLUDED IN THIS ARCHIVE !!!      |\n  `-----------------------------------------------------------------------''\n\nHOW TO INSTALL :\n----------------\n\n        Copy the files in the archive to your directories,\n        they are :\n\n        BBS:Doors/SmartBank/SmartBank.Config\n        BBS:Doors/SmartBank/SmartBank.XIM\n        BBS:Doors/SmartBank/SmartBank.Doc\n        LIBS:AEDoor.library ( © Sintax/WOT )\n\n        The SmartBank.Config looks like this :\n \n        --------(cut here)--------\n        BBS:User.Data                      <- The Location of your User.Data !\n        --------------------------\n\n        Append the BBS:Commands/BBS.CMD to your BBS.CMD !\n\n        Ok, now the door is installed and you can call it typing BANK !\n        (Access should be set to 255, this is only for sysops !)\n\n        Ofcoz another ''realtime'' door !\n\n  .-----------------------------------------------------------------------.\n  |       PLEASE READ THE REGISTER!.TXT INCLUDED IN THIS ARCHIVE !!!      |\n  `-----------------------------------------------------------------------''\n\n\nLAST WORDS :\n------------\n        \nHave fun with my tools !\n\nIf you want to contact me for any reason, drop me some mail via\ninternet or on Synergy (S-Express Home BBS) !\n\nINTERNET : [email removed]\n\nFor S-Express registration call :\n\n         SYNERGY (Sysop : Sigma Seven)\n\n                +49-5731-40074\n                +49-5731-40076\n\n\n                                                           Calypso\nP.S. :\n------\nSince I currently do not know what''s up with GOD, I release this stuff\nunder my name ! I always wanted to continue the group but it looks like\nthat most members can not call for free/are inactive  ! If there is any\nactive member left I would be lucky if you can contact me (see above) !\n\nIf there is any good group which wants an allround-coder, simply contact\nme...\n\nLet the scene go back to the good old days... have fun out there !\n\nGREETINGS/MESSAGES:\n-------------------\n\nSigma Seven - S-Express rules !\nNoisy Belch - Good luck with coding in C ! Good designs !\nGalaxy - Resource-God :)\nNo Limit - Why don''t you switch to S-Express ?\nBBC - Keep coding !\nBilbo Baggins - Contact me (internet ?) !\nSisko - Hows ZIVI life ?\nRaider/Scout/Ventor - Still active ?\nWedlock - Call me !\nSid Vicious - Where are you ?!\nWhiz - Kick your BBS !\nCastor - Paradox suxx, hehe\nE.F.A. - Nothing to crack ?\nDoc - Keep those loooong messages !\nDalai Lama - Where are you ? Use internet !\nWormeater - Still no Playstation ? (it rules !)\nJAF - Contact me !\nMike & Dave - Where are you ?!\nSpike - Where have you been on the PARTY IV ?\nAutopsy - Hi ! New World-Charts coming ?\n-TCB!- - Just gimme a call...\nZion - If you have internet... write me !\n\nSorry if i forgot someone, hehe... that''s all folx !\n','\n',char(10)),NULL,'auto-added',4384,1,0,NULL,NULL,'smartbnk','scan',1780048732);
INSERT INTO door_catalog VALUES('smk_ied','SMK-IED.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SMK-IED.LHA','DOPUS_ICON','XIM','DOPUS_ICON',NULL,'JuNk/SMoKeY','SMK','/\_____/\  __  _/\__ ___/  \__/\____.___ _/ _____/  \/  \/  __ \| / __/ __ \_  |  /\ \___  \/   \/   \_ \/  \_   \  \___/_ | / /',replace('                            /\\n   /\_____/\  __  _/\__ ___/  \__/\____.___\n _/ _____/  \/  \/  __ \| / __/ __ \_  |  /\\n \___  \/   \/   \_ \/  \_   \  \___/_ | / /\n /  /   \_   \____/__    /    \___   /\ /_/\n/_____  _/_  _/\__\_l___/\__  _\_\__/ / ||\n\_____\/\__\/\\/     \__\/  \/\_\ \_\/__||\n       \/   \/   .pRESENT.   \/      \__\|\n  *iNFO-eD v1.0* wRITEN bY JuNk/SMoKeY\n tHIS iS A sMALL uTIL tO eDIT yOUR iNFO\n    fILES..vERY uSEFULL fOR sYSOP''S\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 03-15-19  TIME: 06:37:01  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',14241,5,0,NULL,NULL,'smk_ied','scan',1780048732);
INSERT INTO door_catalog VALUES('smk_lc10','SMK-LC10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SMK-LC10.LHA',NULL,'XIM','pizza_taxi.exe',NULL,NULL,'SMK','_/ _____/  \/  \/  __ \| / __/ __ \_  |  /\ \___  \/   \/   \_ \/  \_   \  \___/_ | / / /  /   \_   \____/__    /    \___   /\ /_/',replace('   /\_____/\  __  _/\__ ___/  \__/\____.___\n _/ _____/  \/  \/  __ \| / __/ __ \_  |  /\\n \___  \/   \/   \_ \/  \_   \  \___/_ | / /\n /  /   \_   \____/__    /    \___   /\ /_/\n/_____  _/_  _/\__\_l___/\__  _\_\__/ / || \n\_____\/\__\/\\/     \__\/  \/\_\ \_\/__||\n.------\/---\/-[ pRESENTS: ]-\/------\__\|-.\n|             LastInConf v1.0              |\n|  Shows the last dudes in a conference!   |\n`--------------------------------[SPREAD!]-''                               \n','\n',char(10)),'LastInConf.guide',replace('@DATABASE "LastInConfGuide"\n@AUTHOR "iCE/CDS^ROYAL^SMOKEY!"\n@REMARK $VER: (August 13 1996, 17:00:69)\n@REMARK AmigaGuide database for the Last\n\n@NODE "MAIN" "Last In Conf - tHe GuIdE!"\n@TOC "MAIN"\n                               /\\n                              /  \\n                             / /\ \                                     _\n                  __________/ /  \ \_______  ____   ___    __          (_)\n                  \__________/    \_______/ /___/  /__/   /_/         __\n               ____________________ _______ ___ __________ ___ ___   (__)  _\n               \   ______  _   _   Y       Y   Y   /  _   Y   Y   |       (_)\n     _        __\___   \/  |   |   |   |   |      /   ____l_.   .-'' \n    (_)  __   \_________\__l___l___l_______l___|  \________/|   |\n        (__)        __    ___   ____  ________ l___\________l___|\n        _           \_\   \__\  \___\ \______ \    / _________/\n       (_)                                   \ \  / /-InFeRnO-\n                                              \ \/ /\n                                               \  /\n                                       .--------\/--------- ---  --   -\n         iCE/SMOKEY^CDS^ROYAL Presents :\n                                       !  Last In Conference v1.0\n         -   --  --- ------------------''\n\n                      @{"iNTRODUCTION " LINK "INTRO"}   - What it does\n                      @{"iNSTALLATION " LINK "INSTALL"}   - What to do\n                      @{"cONTACTING mE" LINK "CONTACT"}   - Where to complain\n                      @{"iCE''S hOME!  " LINK "ADD"}   - What to call\n                      @{"GreetinX     " LINK "GRTZ"}   - Where to be \n\n                        -^( rEmEmBa: aMiGa rUlEz! )^-\n@ENDNODE\n@NODE "INTRO" "Introduction to the mighty Last In Conf!"\n@TOC "MAIN"\n\nLast In Conf won''t do anything special, and won''t get your board to the top\nof the bill, neither will it help you getting a girlee... \nWhen executed it only shows a nice bully, showing the last 5 users who\njoined the conference. Eh?.. roolz doesn''t it!? =)\n\nIt won''t update the bulletin by users who have acceslevel 255. (SysOp)\n\n@ENDNODE\n@NODE "INSTALL" "Installation of da gr8 Last In Conf!"\n@TOC "MAIN"\n\nWell, installing shouldn''t be a problem. Just copy the files to the right\ndirs. Settings are supplied for the mighty FAME bbs system, and icons for\n/X. If you''re running S!X orso, I think you''ll know the best how to install\nthis (AIM) door to your system. \n\nNow start your favorite editor, load the conference bulletins (yep, the one\nyou see all the times when you join the conference!), and add \n~CC_ConfLast to the bull, whereever you want to see the bull. \nIt doesn''t do a clearscreen at the top of the bull, so you can put your own\nfancy logo above it. \n\n(If you''re not using any other MCI (~.. ) commands in your bull, you''ll\nhave to add ~ to the top of your bull. (~f| clears the screen too!)\n\nOkey, now copy/rename the "DOORS:SMOKEY/LASTINCONF.TXT" to\n"DOORS:SMOKEY/LASTINCONF.<CONFNUM>.TXT", where <CONFNUM> is the REAL \nconference number. \n\nEx: DOORS:SMOKEY/LASTINCONF.23.TXT -> Bulletin for conference 23 \n\n@ENDNODE\n@NODE "CONTACT" "Contacting me!"\n@TOC "MAIN"\n\nContact me for a personalised version, bugs, suggestions, money, booze,\ngirls or whatever at any major Dutch board, preferably:\n\n                              One Eight Seven\n                             The Undiscovered\n                                 NightTown\n                                Wonderland\n                                The Origin\n                                 The Hype\n                                Atmosphere\n                                  Scepsis\n\n       ... or find me at #amielite as iCE^SMK / iCE^RYL / iCE^CDS.. \n\n              ... or call this gr8, cool, fast & sexy board:\n\n                               @{"TOTAL^CHAOS" LINK "ADD"}\n\n@ENDNODE\n@NODE "ADD" "Call4SupportOr4FuN!"\n@TOC "MAIN"\n     _____________________________        \n ___|____                     ____|___                       _________\n \    ___|______  ___________ \    ___|______  _____________|         |\n_/      _______/__\______    _/      _______/__\________    \_        |\n\        |/      /     _/    \        |/      /       _/      \       |\n \______________/\____________\______________/_______/         \______|\n    |         _________           |                 /___________\\n  __|________ \        |      ____|_________   _____________ ____________\n_/     _____/__    ____|_____ \_________    \__\______      \_   _______/__\n\      \/      \   \____     \/       _/      \     _/       /_________    \\n \_________     \___/         \______/    2s   \____________/_______________\\n    | /__________\ /___________\  | /___________\\n    |    T O T A L ^ C H A O S    |\n    |   da k¡Ck-aSs aMiGa sItE!   |      +31-229-272838 (33k6/v34/VFC)\n.---|_____________________________|-----------------------------------------.\n|  STAFF : iCE/CDS^RYL^SMK - dUTCH/CDS - JUNK/SMK^DCN^ULT^MTH - LiGHTNiNG!  |\n|    CHAOS d·SiGN WHQ - ULTiMATE, OOPS, ROYAL, TFC & SMOKEY DiST. SiTE!     |\n|   AMI WAREZ - ASCART - FAME - /X - RAYTRACE - GFX - MODS - DOCS - DEMOS   |\n`------------------------------------------( We have it all.. just call! )--''\n@ENDNODE\n@NODE "GRTZ" "Greet¡nX!"\n@TOC "MAIN"\n\n                                GREETINGS!\n                                ----------\n\n                  Greetings/thanx to the following dudes:\n                       (in no special order at all!)\n\n     WhirlWind, Apollo, SoulTaker, Trion, InterPhase, Funki, Andabata,\n               jUnk , Warp, Hi-Tech, Cloak, Flash, Pinokio,\n   Midnight Caller, mAC, Funz, Pyxis, Veteran, Sir Iq, Eurobier, koud?,\n  Array, Muad''Dib, WishBringer, Motive Power, Delite, Hawk, Radavi, MSW,\n   THC, PLL, Nightcrawler, Axeblade, Crew One, Zack, Braindead, orlingo,\n      Stone, Skinny, Odin, Prodigy, Hi-Fi, EX¡T Gee, HellCat&Analyzer\n                      ... and to all dudes I forgot!\n\n              SPECIAL GREETINGS TO ALL IN THE FEIGLING CREW:\n                          KILL MUTTAFUCKING BILL!\n\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',30772,4,0,NULL,NULL,'smk_lc10','scan',1780048732);
