INSERT INTO door_catalog VALUES('smn_jc20','SMN-JC20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SMN-JC20.LHA',NULL,'XIM','__',NULL,NULL,'SMN','______________________/ /_______________ (__ __(   __(___  (_   _(__  _ (___  (__ \ /  \  /  /  /  |  /    // |  | /  |  / |  |',replace('                         __                 \n  ______________________/ /_______________  \n (__ __(   __(___  (_   _(__  _ (___  (__ \ \n /  \  /  /  /  |  /    // |  | /  |  / |  |\n/     /  /  /     /     /  |  |/     /  |  |\n\____ \____ \___| \____ \__|  |\___| \__|  |\n|   \_/   \_/   |__|  \_/  |__|__| |__| |__|\n|       FaStEr ThAn YoU cAn ImAgInE!!      |\n|       PrEsEnTs FoR YoU tO pLaY wItH :->  |\n`------------------------------------------''\n            SMn-JoinConf V1.20               \n        Join conferans dörr till DD         \n','\n',char(10)),'SMn-JoinConf.doc',replace(' ______ ______ _________ ___________ ____      ____ ___________ _______   __\n|      |      |         |           |    \    /    |           |       | |  |\n|      |      |         |           |     \  /     |           |       | |  |\n|      |      |         |           |      \/      |           |       | |  |\n|      |      |         |           |              |           |       | |  |\n|   ___|   ___|   ___   |___     ___|              |    ___    |   _   | |  |\n|  |   |  |   |  |   |  |   |   |   |              |   |   |   |  | |  | |  |\n|  |   |  |   |  |   |  |   |   |   |   |\    /|   |   |   |   |  | |  | |  |\n|  |   |  |   |  |   |  |   |   |   |   | \  / |   |   |   |   |  | |  | |  |\n|  |   |  |   |  |   |  |   |   |   |   |  \/  |   |   |   |   |  | |  | |  |\n|  |___|  |   |  |___|  |   |   |   |   |      |   |   |___|   |  | |  | |  |\n|      |  |   |         |   |   |   |   |      |   |           |  | |  | |  |\n|      |  |   |         |   |   |   |   |      |   |           |  | |  | |  |\n|      |  |   |         |   |   |   |   |      |   |           |  | |  | |  |\n|      |  |   |         |   |   |   |   |      |   |           |  | |  | |  |\n|___   |  |   |   ___   |   |   |   |   |      |   |    ___    |  | |  | |  |\n    |  |  |   |  |   |  |   |   |   |   |      |   |   |   |   |  | |  | |  |\n    |  |  |   |  |   |  |   |   |   |   |      |   |   |   |   |  | |  | |  |\n    |  |  |   |  |   |  |   |   |   |   |      |   |   |   |   |  | |  | |  |\n    |  |  |   |  |   |  |   |   |   |   |      |   |   |   |   |  | |  | |  |\n ___|  |  |___|  |   |  |   |   |   |   |      |   |   |   |   |  | |  |_|  |\n|      |      |  |   |  |   |   |   |   |      |   |   |   |   |  | |       |\n|      |      |  |   |  |   |   |   |   |      |   |   |   |   |  | |       |\n|      |      |  |   |  |   |   |   |   |      |   |   |   |   |  | |       |\n|      |      |  |   |  |   |   |   |   |      |   |   |   |   |  | |       |\n|______|______|__|   |__|   |___|   |___|      |___|___|   |___|__| |_______|\n\n                        Presents   SMn-JoinConf   V1.20\n                             ©  By ScatMan 1996\n\nGe fan i såsen!!!!!!\n******************************************************************************\n\nJepp, ännu än onödig dörr till DD.\n\n******************************************************************************\n\nEn join conferance dörr i arexx.\nHmmm, ja man kanske inte ska göra en sådan dörr i arexx, men va fan gör man \nnär man är lam?????\n\nJAJa, varför jag överhuvud taget gjorde denna dörr varför att Toymenu inte \nverkar funka på A500''or, iaf inte (HIBBES)\n\n******************************************************************************\n\nHur man ska konfigurera "JoinConf.cfg"\n\nJapp det är inte så svårt hoppas jag.\n\nSELECTOR_XROW - här skriver man in X-ledden för Conf och Quit raden.\n\nT.ex.   SELECTOR_XROW\n        25\n\nSELECTOR_YROW - här skriver man in Y-ledden för Con och Quit raden.\n\nT.ex.   SELECTOR_YROW\n        18\n\nSELECTOR_COL - här väljer man text färg på Conf och Quit raden.  0-7\n\nT.ex.   SELECTOR_COL\n        3\n\nMIN_AXX_PRIV_AREAS - hmmm, här ska man skriva minsta axx för att få fram\ndom (GÖMDA) konferanserna.\n\nT.ex.   MIN_AXX_PRIV_AREAS\n        150\n\nNUMB_COL - här skriver man in vilken färg man vill ha på conf siffrorna. 0-7\n\nT.ex.   NUMB_COL\n        6\n\nTEXT_COL - här skriver man in vilken färg man vill ha på conf texterna. 0-7\n\nT.ex.   TEXT_COL\n        5\n\nCURS_COL - jupp, här väljer man färg på cursorn. 0-7\n\nT.ex.   CURS_COL\n        4\n\nROW1_X - här skriver man X-ledden för conf texterna. Rad 1\n\nT.ex.   ROW1_X\n        22\n\nROW1_Y - och här Y-ledden för con texterna. Rad 1\n\nT.ex.   ROW1_Y\n        12\n\nROW2_X - här skriver man X-ledden för conf texterna. Rad 2\n\nT.ex.   ROW2_X\n        45\n\nROW2_Y - och här Y-ledden för conf texterna. Rad 2\n\nT.ex.   ROW2_Y\n        12\n\nCURS1 - här väljer man hur curson ska se ut på vänster sida\n\nT.ex.   CURS1\n        (\n\nCURS2 - och här hur curson ska se ut på höger sida.\n\nT.ex.   CURS2\n        )\n\nCONF_NUMBS1 - här skriver man in hur många konferanser man vill ha i första\nraden. Om man vill ha (GÖMDA) konferanser för dom som inte har axx dit så\nmåste dom skrivas in sist. \nHmmm, nackdelen med det är att dina egna (GÖMDA)konferanser oxå måste va \nsist i Daydream.cfg.\nVill man bara ha en rad text så får man skriva - efter CONF_NUMBS2.\n\nT.ex.  Om man har 6 konferanser och konferns 6 är en (GÖMD) och man bara vill\nha en rad text skriver man så här:\n\nCONF_NUMBS1\n1\n2\n3\n4\n5\nVIP\nCONF_NUMBS2\n-\n\nAlla (GÖMDA) konferanser man har måste det stå VIP på, så skulle du ha 2 \n(GÖMDA) konferanser skulle det bli så här:\n\nCONF_NUMBS1\n1\n2\n3\n4\nVIP\nVIP\nCONF_NUMBS2\n-\n\nOm man vill ha 2 rader text så skulle det bli så här:\n\nCONF_NUMBS1\n1\n2\n3\nCONF_NUMBS2\n4\n5\nVIP\n\neller om man har 2 (GÖMDA) konferanser\n\nCONF_NUMBS1\n1\n2\n3\nCONF_NUMBS2\n4\nVIP\nVIP\n\nVARNING - tryck ALDRIG return efter sista raden i CONF_NUMBS2 - VARNING\n\n\n***************************************************************************\n\nINSTALLATION\n\n\nSkriv så här i Daydream.cfg\n\nDOOR_COMMAND.. J\nDOOR_TYPE..... 1\nDOOR_SECURITY. 5\nDOOR_EXECUTE.. Daydream:Doors/Rexx %N Doors:Rexxdir/SMn-JoinConf.dd\n+\nDOOR_COMMAND.. <\nDOOR_TYPE..... 1\nDOOR_SECURITY. 5\nDOOR_EXECUTE.. Daydream:Doors/Rexx %N Doors:Rexxdir/SMn-JoinConf.dd\n+\nDOOR_COMMAND.. >\nDOOR_TYPE..... 1\nDOOR_SECURITY. 5\nDOOR_EXECUTE.. Daydream:Doors/Rexx %N Doors:Rexxdir/SMn-JoinConf.dd\n\n****************************************************************************\n\nEGNA MENYER\n\nJa man kan ha egna menyer.\nRita bara en egen och döp den till JoinConf.gfx och lägg den i Diplay/ISO/\n\n****************************************************************************\n\nHISTORIA\n\nV1.05  Hmmmm vad ska man säga, en massa fel :(\n\nV1.20  Har tagit bort allt som har med password att göra i cfg filen,\nfanns ju färdigt redan.\nMinskat ner såsen lite.\n\n****************************************************************************\n\nFörslag på bättringar eller fel rapporter till:\n\n                  ___\n      __  ____  _/  /_________\n     (__)(__  \(_  ____\_ _ _/-----------------------------------------+\n     /  \/ |   /   /  \/  |  \          THiS oNE                       |\n    /   /  |  /       /   |   \           WIlL                         |\n    \___\__|  \____   \_______/         PeNETrATE                      |\n     |     |___|  \__/                  yOUr MInD!                     |\n     |                                                                 |\n     |                  ___                            ___             |\n     |         ________/  /______________  ____  __  _/  /_____ __     |\n     |        (_ ____(_  ___(_ ____(_ _  \(__  \(__)(_  ___(_  |  |    |\n     |        /  _)__/   /  /  _)__/  /   / |   /  \/   /  /   |  |    |\n     |       /  /   /      /   /  /  _   /  |  /   /      /       |    |\n     |:.     \____  \____  \____  \__/   \__|  \___\____  \___    |    |\n     |:::.       \__/   \__/   \__/ /______/|___|      \__/  |____|    |\n     |:::::.                                                           |\n     |                                                                 |\n     |  Amiga 1200, 540megs storage, CD-Rom, above 3800 files online   |\n     |                                                                 |\n     |                       OpeN: 22.oo - o6.oo                       |\n     |                                                                 |\n     |                       TelE: o293 - 514 21                       |\n     |                                                                 |\n     |                         SysOp: ScaTmaN                          |\n     |                       CoSysOp: JumMiS & SaM                     |\n     |                                                                 |\n     +-----------------------------------------------------------------+','\n',char(10)),NULL,NULL,6483,2,0,NULL,NULL,NULL,'scan',1780048732);
