INSERT INTO door_catalog VALUES('snatchdz','SNATCHDZ.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SNATCHDZ.LHA','gifdesc','XIM','SnatchDIZ',NULL,NULL,NULL,'_/  ___/__/_  ____  \_\____  \_ \_______    \_\______/   _/  _/_ .---_/      \/     /    _/     \      \_---.',replace('        ______   _________  _______\n      _/  ___/__/_  ____  \_\____  \_\n      \_______    \_\______/   _/  _/_\n.---_/      \/     /    _/     \      \_---.\n|   \_____________/_____\_______\      /   |\n|       SUPREME GIVES YA IN 1995 \____/    |\n|              SnatchDIZ V2.0              |\n|   BEST and QUICKEST file_id extractor!   |\n| For DMS, LHA, LZX, EXE, TXT, ZIP and GIF |\n| 100% highly optimized asm!  Code: rASCAL |\n`-------------------------------------m!^dG''\n','\n',char(10)),'SnatchDIZ.guide',replace('@database\n@node main "SnatchDIZ V2.0 docs"\n@{b}         ______   ___ ___  _______  _____  ________ ___ ___  ________\n       _/  ___/__/   Y   \/  ___  \_\___ \_  _____//   Y   \/  _____/\n       \______   \   |    \  \_____/ __/ _/_ _)_____        \  _)_____\n.___ _/     \/    \_ ·     \_   \_ __\      \       \_\_/    \        \_ ___.\n|   \\             /        /    // / \      \_      / ·      \_ m!^dG //   |\n|____\\___________/________/____//_/___\      /_____/__|       /______//____|\n·""""" """""""""""""""""""""""""""""""""\____/"""""""""|______/""""""" """""·@{ub}\n            @{fg highlight}SnatchDIZ V2.0 - © by rASCAL/SUPREME on 19.4.95@{fg text}\n\n\n			    @{"    Purpose     " link 1}\n\n			    @{"     Usage      " link 2}\n\n			    @{"  Requirements  " link 3}\n\n			    @{"   Greetings    " link 4}\n\n			    @{"    History     " link 5}\n\n\n                 @{b}kEEP tHE aMIGA aLIVE aND ... lEGALIZE iT!@{ub}\n\n@endnode\n@node 1 "What the fuck..."\n\nSnatchDIZ  is  another  FILE_ID.DIZ extractor for the Shell or for use with\nany bbs-system.  Features:\n\n - LHA-, LZX-, ZIP-, DMS-, EXE-, GIF-, TXT-Support\n - SnatchDIZ is smaller than 3 KB and faaaaaaaaaaaaaaaaaaaast!\n - great code: SnatchDIZ does not produce HITS like WhaDIZ, SpeeDIZ etc.\n - good error handling: No problems with empty files or something\n\n-=> Use SnatchDIZ instead of all the other crap floating around!\n@endnode\n@node 2 "It''s easy..."\n\nUsage: SnatchDIZ FILE/A,S=SUPPRESS/S,K=KEEPDIZ/S\n==============================================\n\nFor example:  "SnatchDIZ dh0:down/PPLAY41.LZX S K" will give you\n\n--------------------------------------\nPower Player 4.1 Final Omega Version\n* Latest Update! *\n--------------------------------------\n\nThis extracts and shows the FILE_ID, suppresses the About text and does NOT\ndelete  the  file  t:file_id.diz (which is temporarily created) so that you\nmay  use  it  in any way.  The file t:file_id.diz is only created for dms-,\nlha-, lzx- and zip-files.\n\n\nWARNINGS: - SnatchDIZ is cli-only so don''t start from Workbench!\n          - SnatchDIZ was NOT TESTED AT ALL with GIFs!\n@endnode\n@node 3 "You got this crap..."\n\nYou need:\n\n - an AMIGA w/Kick 2.04+ (as always).\n - the lha-, lzx-, GIFdesc- and UNzip-executable placed in your path.\n   A working UNzip and GIFdesc is included in the SnatchDIZ-archive.\n\nThat''s it.\n@endnode\n@node 4 "Hallöle..."\n\nGreetings to all SUPREME and CAFFEiNE membaz!\n@endnode\n@node 5 "Versions..."\n\nV0.9:	not released but seems to work properly.\nV1.0:	added filetype indicator and the SUPPRESS option.\n	1st release (under CAFFEiNE label)!\nV2.0:	added own routine for search in DMSs (MUCH FASTER than DMS VIEWDIZ)\n	optimzed search in executables A LOT!\n\n@endnode\n','\n',char(10)),NULL,'auto-added',64230,3,0,NULL,NULL,'snatchdz','scan',1780048740);
INSERT INTO door_catalog VALUES('sndiz2_3','SNDIZ2$3.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SNDIZ2$3.LHA','UnZip','XIM','SnatchDIZ',NULL,NULL,NULL,'\   _/__  |_  |  _  |  _  |_   ._/sHOOt''95 | .\_.   /  _/  |  /  :  /  |/   | sTRIKES   | |  l  /___|   l_____l_____/    |aGAIN wITH :',replace('______ ___|___._____._____|_______ ________.\n\   _/__  |_  |  _  |  _  |_   ._/sHOOt''95 |\n.\_.   /  _/  |  /  :  /  |/   | sTRIKES   |\n|  l  /___|   l_____l_____/    |aGAIN wITH :\nl____/----l____/-:sc:----\_____|-------- - .\n.                                          :\n:     -----»>  SnatchDIZ V2.3  <«-----     .\n.                                          :\n:   BEST and QUICKEST file_id extractor!   .\n.   (DMS, LZX, LHA, EXE, TXT, ZIP, GIF)    :\n:  Now able to create /X style listfiles!  .\n. 1oo% highly optimized asm!  Code: rASCAL :\n','\n',char(10)),'SnatchDIZ.guide',replace('@database\n@node main "SnatchDIZ V2.3 docs"\n@{b}                    _         _         _         _         _\n              _____/ \_______/ \_______/ \_______/ \_______/ \___ __ _\n            _/  __/   \_____/   \_____/   \_____/   \_____/   \_//_///\n            \______    \   |     \   |     \   |     \   |     \\n     _ __ _/     \/     \_ .      \_ ·      \_ ·      \_ |      \_\n     \\\_\\_______       /_|       /__       /__       /_|       /\n      ------m!^DG|______/--|______/--|______/--|______/--|______/----@{ub}\n               @{fg highlight}SnatchDIZ V2.3 - © by rASCAL/SHOOT on 17.8.95@{fg text}\n\n\n			    @{"    Purpose     " link 1}\n			    @{"     Usage      " link 2}\n			    @{"  Requirements  " link 3}\n			    @{"   Greetings    " link 4}\n			    @{"    History     " link 5}\n\n                 @{b}kEEP tHE aMIGA aLIVE aND ... lEGALIZE iT!@{ub}\n\n@endnode\n@node 1 "What the fuck..."\n\nSnatchDIZ  is  another  FILE_ID.DIZ extractor for the Shell or for use with\nany bbs-system.  Features:\n\n - LHA-, LZX-, ZIP-, DMS-, EXE-, GIF-, TXT-support\n - /X style listfile generation\n - SnatchDIZ is smaller than 3 KB and faaaaaaaaaaaaaaaaaaaast (1oo% asm)!\n - great code: SnatchDIZ does not produce HITS like WhaDIZ, SpeeDIZ etc.\n - reentrant (can be made resident)\n - good error handling: no problems with empty files or something\n\n-=> Use SnatchDIZ instead of all the other crap floating around!\n@endnode\n@node 2 "It''s easy..."\n\nUsage: SnatchDIZ FILE/A,S=SUPPRESS/S,LF=LISTFILE/K\n==================================================\n\nexample 1:  "SnatchDIZ dh0:down/PPLAY41.LZX S" will give you\n\n--------------------------------------\nPower Player 4.1 Final Omega Version\n* Latest Update! *\n--------------------------------------\n\nThis extracts and shows the file_id.diz and suppresses the credits and the\nfiletype indicator.\n\n                            ------------------\n\nexample 2:  "SnatchDIZ dh0:down/!s-w&f.lha S LF ram:listfile" will show you\nthe  file_id.diz  and add it to the listfile ram:listfile.  If ram:listfile\ndoes not exist it will be created.\n\nThe listfile looks like this:\n\n------------------------------------------------------------------------------\n!s-w&f.lha               37137     __/\____/\____/\____:_/\___/\____/\___/\__ \n                                   \  ___\_ _____ ___/ |  /___ ___\  ____  __\ \n                                  _/\_ \ /  |_/  __)/  l_ \/  __)_/\_ \ |  |\/ \n                                  \     \   ` \  l  \      \  l  \     \|  |lr\n                                  /_____/____ /_____/__/\__/_____/_____/l__!d \n                                  ======[ sCENESt pARTY cONTRiBUTiON ]========\n                                  -                                          -\n                                  -       wATER & fIRE - first place         -\n                                  -                                          -\n                                  -     a small *40kb* intro by tHERAPY      -\n                                  ==============================[09/04/95]====\n------------------------------------------------------------------------------\n\nIf  you  want to create a listfile of an entire directory, use the AmigaDOS\nscript SPat, which is supplied with every Amiga since OS 2:\n\nSPat SnatchDIZ dh0:down/#? lf ram:listfile\n\nMaybe I will add an own wildcard routine in a later version.\n\n                            ------------------\n\nWARNING: - SnatchDIZ is cli-only so don''t start from Workbench!\n@endnode\n@node 3 "You got this crap..."\n\nYou need:\n\n - an AMIGA w/Kick 2.04+ (as always).\n - the lha-, lzx- and UNzip-executable placed in your path.\n   A working UNzip is included in the SnatchDIZ-archive.\n\nThat''s it.\n@endnode\n@node 4 "Hallöle to..."\n\n                             all SHOOT members\n                                 CAFFEiNE\n                                   OMEN\n        STEELER and the rest/PHANTASM (thanks for the bug reports)\n                                Flake/TRSI\n                               MAVE/CRYSTAL\n@endnode\n@node 5 "Versions..."\n\nV0.9:	not released but seems to work properly.\n\nV1.0:	1st release, 31.3.95 (CAFFEINE)\n	- added filetype indicator and the SUPPRESS option.\n\nV2.0:	2nd release, 19.4.95 (SUPREME)\n	- added own routine for search in DMSs (MUCH FASTER than DMS VIEWDIZ)\n	- optimzed search in executables A LOT!\n\nV2.1:	(no public release)\n	- added own routine for search in GIFs (MUCH FASTER than GIFDESC)\n	- SnatchDIZ is now reentrant and can be made resident (PURE option)\n	- removed KEEPDIZ option because it was unnecessary at all\n	- now checks if dos.library is >= V36\n	- no longer crunched. V2.0 sometimes crashed on 040 systems due to\n	  the used packer (CrunchMania V1.9)\n\nV2.2:	3rd release, 19.7.95 (SHOOT) :-)\n	- fixed bug with filenames containing spaces/wildcards\n	- I was told SnatchDIZ even handles JPGs, check it out yourself\n\nV2.3:	4th release, 17.8.95\n	- added /X style listfile generation\n	- fixed small bugs concerning resident ability\n\n@endnode\n','\n',char(10)),NULL,'auto-added',57088,5,0,NULL,NULL,'sndiz2_3','scan',1780048740);
