INSERT INTO door_catalog VALUES('some1','SOME1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SOME1.LHA',NULL,'XIM','mUlT¡-cHAT.cap',NULL,'MR.ORION',NULL,'SOME-INFO V1.0b AN /X DOOR WRITTEN 100% IN AREXX NO BACKDOORS',replace('--------------------------------------------\n             SOME-INFO V1.0b \n \n     AN /X DOOR WRITTEN 100% IN AREXX\n              NO BACKDOORS \n \n       WRITTEN BY MR.ORION / REBELS\n--------------------------------------------\n','\n',char(10)),'someinfo.doc',replace('\n\n               S O M E - I N F O  V 1.0b  BY MR.ORION / REBELS\n\n\n   well.. here is an status door for you if you can use it ( i hope you\n   can!!) well.. ther is not much to say about it .. you know how to\n   install thiz shit.. if not then you are a lamer!!..\n   \n   okay.. now to some greeting''s :\n\n                    to all REBELS members in the world\n              \n\n\n   CALL THIZ REBELS BOARD''S :\n\n                  THE LARCH (WHQ)   2 NODEZ : +45 PRIVAT\n                  FASTRAX (USHQ)    3 NODEZ : +01 NOT FOR YOU\n                  INTERCHANGE (SHQ) 2 NODEZ : +46 ASK FOR IT!!\n                  MASTER & SERVANT  5 NODEZ : +49 GET IT!!\n\n   ','\n',char(10)),NULL,'auto-added',45336,2,0,NULL,NULL,'some1','scan',1780048740);
INSERT INTO door_catalog VALUES('space_em','SPACE_EM.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SPACE_EM.LHA','spaceemp','XIM','spaceemp',NULL,NULL,'SPACE','**** LAMEST /X DOOR GAME **** **** EVER!  ONLY FOR OLD **** **** SKEWL SYSOPS PLEASE ****',replace('**** SPACE EMPIRE FOR /X ****\n**** LAMEST /X DOOR GAME ****\n**** EVER!  ONLY FOR OLD ****\n**** SKEWL SYSOPS PLEASE ****\n**** GET THIS IF YOU ARE ****\n     SUPERtOM  tOMINATOR\n        BILL CLINtOM\n','\n',char(10)),'SpcEmp.DOC',replace('\n                               Space Empire V1.7a         \n\n                                      by\n\n                                John Errington   \n                                     and                \n                                Harold Scadden          \n\n                             Created by Jon Radoff      \n                          Version 1.7a  Documentation    \n                                   \n                      UPDATES:   Available at AMIGA MICRO      \n                             (804) 587-8661 (9600)       \n                             (804) 587-2594 (2400)       \n\n\nI.   Introduction\nII.  Running Your Empire\nIII. Covert Operations\nIV.  Battle\nV.   Other features\n\nI. Introduction\n\n        The object of Space Empire is simple.  You are the absolute\nruler of a set of worlds.  Your goal is to be the most powerful empire\nthrough diplomacy, economic ploys, and most of all, war.  The first\nperson to be "Space Lord" for seven days in a row ascends the iridium\nthrone of the galaxy and becomes Lord of the Universe.  To be Space Lord,\nyou must have at least 100,000 points and be the highest scorer if there\nis more than one empire with 100,000 points.\n\n\nII. Running Your Empire\n\n	At the beginning of each turn, you collect money in the form of\ntaxes from your people and ore mined from planets.  You also get a stock\nof food from agricultural worlds and a flow of weaponry from defense\nplanets.  Your governing planets, which are purely administrative worlds,\ndon''t do you any good and just sap your funds -- but you need one of them\nfor every 25 other planets. \n\n	After collecting this money, you are allowed to budget your money\nas you see fit.  Certain amounts will be requested which you are advised\nto stay close to.  Your people will also require food -- make sure you\neither buy enough food each round or have enough agricultural worlds to\nsupport your people!\n\n	When you are done feeding your worlds you can use the Galactic \nBank for a savings account at a 5% interest rate.  This interest rate\ngains interest on every turn.  There is also the option to borrow money\nfrom the Bank, this will cost you 5% interest and is posted every turn.\nIf you make a loan YOU MUST pay back at least 10% of the loan value per\nturn.  If you do not then the Galatic Repo Man will start taking your\nassests!!\n\n	Soon, you''ll be able to buy extra things, including more weaponry,\nplanets, etc.  Spend wisely.  Don''t use up all your money, or buy things\nwhich could sap all your money away in the future.\n\n	You must keep your populace happy!  Abusing them by not giving\nthem enough food and not allocating enough money to your planets will\nstir up unrest.  There are many factors which modify how happy your\npeople are.  Make sure you learn these and keep them that way.  Internal\nunrest is worse than the most powerful of enemy armies!\n\nHINTS:  People by nature are happier when they are well fed.  The food\nlevels suggested by the program are the MINIMUM levels required to keep\nthem at their present status.  Same with money needed for the planets the\nsuggested amount is the minimum required to maintain the Status QUO.\n\nTo build planets and defenses effectively during your first rounds in the\ngame. Start off by buying NOTHING BUT ORE PLANETS for the first ten turns on\nturn one you should buy all ore planets except for about 2 or three \nagricultural planets always keep the agricultural planets producing more\nthan the minimum required of food.  Planet costs start to esculate rapidly\nbut ore planets are the best investment.  Each planet requires 10K credits\nto maintain and each governing planet requires 20K credits each. Since ORE\nplanets produce 20K credits of income you profit 10K credits for every ORE\nplanet you have.  KEEP the levels of governing planets up to the minimum of\n1 gov planet for every 25 plus fraction thereof of the other planets.  Lack\ngovernment representation is extremely bad for your people.\n\nAfter round ten or fifteen start buying Defense Planets but make sure \nthat for every defense or agricultural planet you buy you alway buy at least\none ore planet to support it.  (Two ore planet to support the governing\nplanets.)\n\n\nIII. Covert Operations\n\n	Spy work as covert agents to obtain information on your oponents\nmilitary and government functions.  Spys also help prevent someone from\nsneaking in for a look on you!\n\nIV. Battle\n\n	Battle is an integral part of the game -- this is how you\nweaken your enemies and sieze planets from them.  The victor in battle\ndepends on many factors.\n\n	Each unit of battle force works a little differently.  Soldiers\nare the base unit of your military -- they have the weakest firepower in\nbattle, but you need them to back up all your other forces.  If you don''t\nback up your other weaponry with troops of soldiers, you are surely\ndoomed.  Fighter craft are offense only weapons, and are about twice as\neffective as soldiers when attacking.  The cost a little more, and for\nevery 100 fighters you have, you need a carrier to transport them.  Defense\nstations cost about the same as fighters, and are defense only.  Cruisers\nare both offensive and defensive, have more firepower than either fighters\nor cruisers, but cost about twice as much.\n\n	The morale of your military is a very important factor.  If you\ncontinuously lose battles, their morale will go down.  It will go up if\nyou win battles and allocate them extra money.  It is also changed by\nvarious other factors.  For instance, domestic unrest tends to demoralize\nyour army.\n\n	There is always an element of chance.  A lesser enemy always has\na slight chance of winning a battle if the two battle forces are close\nenough in size.\n\n	If the attacking battle force emerges the victor, he will gain\n10% of his enemy''s planets (rounded up).  His enemy will be wiped out of the\ngame if you take all of his planets.  This is one of the greatest moral\nboosters your army can get.\n\n	New players are protected from being attacked for a period of\n20 turns, unless they attack someone else first (note 20 turns ends at \nthe beginning of turn 21.)  If you fail to logon to the game for 7 days \nyou will lose your protection and made open game for the rest of the players.\nThis is done to benefit those who are actively playing the game and to \nclear room for other players to join the game.\n\nHINTS:  The best way to attack is to spy on the player you are about to \nattack if they are not part of an alliance send slightly more of troops,\nfighters (against defense stations), and heavy cruisers than your opponent\nhas.  If he has an alliance send your best guess or what you think his\nallaince has to support in addition to the normal required forces.\nNote: \nIn previous versions the full force of an alliance''s help could not be \nfelt due to a major coding error on the part of the original programmer.\nStarting in Version 1.5 the alliances now work to benefit those in the\nallaince.  Previously the more people you had in the allaince the less\nalliance support you got.  I have fixed this do that you always get the\nfull defense support of your alliance force that YOU own and 50% support\nfrom all remaining forces.  If in doubt as to what you current allied force\nleves are just select Info option in the allaince Menu.\n\nV.  TIPs, Tricks & Other features\n\n        Troops, defense stations, and heavy cruisers that are stock piled\nin the alliance cost you half of normal to maintain how ever they are\nnot counted as part of your personal wealth when point tallying time comes\nso while you can bank forces in the alliance they don''t count toward your\nscore while they are there. Using the restock option allows you to use\nthe alliance like an armament bank.  It returns all the forces you\ncontributed to you for you to redistribute back to the alliance or keep.\n       \n         Planets are taken from your enemy evenly from each of his types\nof planets so trying to take all of one type of his planets is useless\nunless you really want that type of planet yourself. i.e. player A has 4-ORE,\n2-AGRI, 1-Governing, and 5-Defense. Player B defeates Player A and gets\n4 planets. Player B takes 4 ORE planets leaving player A with 3-ORE,\n1-AGRI, 0-Governing, 4-Defense.\n\nTake advantage of your alliance''s defense capabilities and communicate with\nyour alliance''s members.  The alliance section was repaired and works like\na champ now.\n\nAlliance defenses operate like this:\n\nPlayer A has 1000 troops, 1000 defense stations, and 1000 heavy cruisers in\nhis alliance of one.\n\nPlayer A is given the additional protection then of 100% of the total \nalliance forces combined with his non-alliance forces for DEFENSE only.\n\nPlayer B joins the alliance and is immediately covered by the defensive\npower of player A''s contributed forces.  Player B decides to add 500 troops,\n500 Defense stations and 500 cruisers.  Now Player B not only has the power\nof his contributed forces but still 50% of player A''s contributed forces,\ngiving him a total protection of 1000 troops, 1000 DS, and 1000 HC.\nPlayer A on the othere hand has the total defesive power now of his original\ncontributed Forces (CF) but also 50% of the power of player B''s cf''s, for\na total defensive power of 1250 troops, 1250 DS, and 1250 HC.  As you can\nsee the more you contribute the better protected all players can be.\n\nThis was a major change from the way the alliance used to work which \nactually made it detrimental to ally with anyone but your self.  Now at \nleast there is some benefit to having an Alliance with someone else.  Forces\nlost during a battle are taken off poportionately from the areas that\nsupplied them.  In this manner every one shares the benefit and the loss.\n\nThe alliance also has a bank now.  Every member can deposit or take out\nmoney from a common account.  This can be helpful when a player gets on\nthe needy side.\n\n','\n',char(10)),NULL,'auto-added',34118,3,0,NULL,NULL,'space_em','scan',1780048740);
INSERT INTO door_catalog VALUES('spagent','SPAGENT.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SPAGENT.LHA',NULL,'XIM','sonnencreme.exe','1.02','P0T-NOoDLE',NULL,'(C)1994 Gods''Gift ritten and designed by P0T-NOoDLE',replace('Super-Page NT Pro IV Deluxe GTi Plus, v1.02\n(C)1994 Gods''Gift\nritten and designed by P0T-NOoDLE\n','\n',char(10)),'SPage.Doc',replace('Super-Page NT Pro IV Deluxe GTi Plus, v1.02 - (C)1994 Gods''Gift.\nWritten and designed by P0T-NOoDLE.\n\n\n\nDis-claimer:\n I would like to tell everyone that I thought of the following Dis''s*\no Your mum.\no Go take a flying fuck at a rolling doughnut.\no Your dad.\no Yeah?\no Startin?\no Let''s take this outside!\no C''mon then?\no BIFF!!\no BOFF!!!\no SMACK!!!!\no SHAZAM!!!!\no POWWW!!!!!!\no LUNGE!!!!!!!\no SPINNINGBIRDKICK!!!!!\no YATZEENATITITINAKIYAKEN!!!\no SOOOONIC-BOOOOOYAKA!!\no Ouch, you hurt me.\no Oh, sorry.\n\n\n\nTHIS PROGRAM IS ARSE-WARE:\n	If you ReSource this program and then, having printed it out, shove\nit up your arse just before relieving yourself of a very bad case of the runs,\nyou are legally obliged to send no less than one-third of the resulting\nshit-stained paper to the author of this program for his or her own personal\nenjoyment with may include, but is not limited to, shoving it up his or her\nown arse and allowing your shit to mix with the local secretions; nailing the\nprinter-DUMP on to the next-door-neighbour''s front door; and wrapping up\nTiddles with the print before splitting the cat and producing a blood/shit/\nSuper-Page NT Pro IV Deluxe GTi Plus v1.02 source code/fur/staple/scab stain\non the wall to go with the previously produced hampster purée design.³\n\n\n\nIntroduction:\n	Well, this is about the 3rd chat door I''ve written in my time, and\nthis one has been totally written and designed from scratch with all my newest\nroutines! This has been written for Hydro, Sweet Thing, and Dream Warrior (I\nthink) as they all wanted a chat door that both looked good and output the\nchat reasons to a log.\n	This is a really simple util (as are all that say "slapped together")\nand I don''t think that it is worth releasing on its own - it is just a custom\nutil for those who asked for it - so if you get this in a pack of utils or\nsomething (I''m thinking about releasing lots of my small, unreleased utils in\na second Box-of-tricks (the first one was in 1992, I think, and all in ARexx!)\nI hope you find it usefull, and if not, well, I never said it was anything\nspecial!! (Although the output does look fucking cool, if I do say so myself).\n\n\nRekwirementz:\no A dictionary.\no Any version of /X that supports doors. (inc. Sigma-Express)\n  (Although when /X4 arrives it''ll probably have changed everything, so you''ll\n  have to install the door upside down and convert the main executable into a\n  UUEncoded ASCII file and assign 5meg of RAM for use with the JH_AB¹ and\n  JH_BD commands using AmiHIMEM when booting, having run your AmiExpress4\n  mouse driver in SYS:AmiAUTOEXEC.BAT\no Any M68000 family CPU or emulator.\no AmigaOS 2 of above.\no DOOM.WAD\no To use this util you MUST use DirectoryOpus and not one of those lesser\n  programs.\n\n\n\nNew Features for v1.02:\no New sets the ACP Action ENV (so that the ACP name changes colour too).\no Now flashes/beeps (depending on your prefs) ALL screens, not just the\n  node screen.\no Added "Deluxe GTi Plus" to the name. Thanks to VitalSt* for the GTi.\no "III" in the name had to change to "IV" to fit on the output line!\no The name is approaching AmigaDOS limits! (as well as sanity limits).\no The name HAS reached VERSION string limits, so I had to abreviate it\n  in the version string (sorry for this little problem).\no HAHAHA!! I CONTROL YOU ALL.\no err, sorry don''t know what came over me.\no I think that the Bar "problem" DW was talking about may have been\n  "fixed" (just a problem with colours, I think).\no The demon which possessed previous versions has now be removed.\n  Many thanks to Father John for the exorcism.\n\nTRANSLATION CORNER: "colour" <==> "color".\n\n\n\n\nFeatures:\no Cool (FUCKING COOL) output.\no Percentage done bar! (a bit of a cheat really)\no Requests that the users say why they are paging for a chat.\n  (Blank answer = abort)\no Beeps the screen at the Sysops end only (or plays a sample/note, whatever\n  you set in your system SoundPrefs).\no After paging, allows users to page up to 2 times more, leave a comment,\n  or quit out of the door.\no While the door is paging, the user can press any key to abort, and the\n  sysop may jump into chat.\no After the user has paged, his name will turn red to indicate that he wants\n  to chat, as happens with the internal page command.\no Requires OS2 or above (1.3 sucks!!!). This is a feature because it means\n  that game playing nobby-nackers can''t use it.\no Writes the time of page and the reason for paging into the callerslog.\no Writes the username, the date, the time of page, and the reason for\n  paging into a seperate chatlog (created if it doesn''t exist, so when it\n  gets too big, you can just delete it).\no Will only let the chat if you have the chat-enabled (F7), OR if their\n  access if greater than or equal to 200.\no Shows the local time and day so that they know if you''re asleep/at work!\no Supports upto 32 Nodes (actually, upto 100 nodes, unlike /X).\no Speedy 100% Assembler code.\no Can be made resident.\no It has a really cool name!\n\n\nUn-Features:\no The only way in which to allow the user/sysop to break the paging (either\n  to abort it, or to jump into chat) is to use the "reserved" GetKey command.\n  There really is no other way to do it! However, I have no docs on this\n  command, and it is "reserved, not to be used" (even though virtually all of\n  the pager and File-Id doors do use this call!), so it is possible that it\n  will fail on new versions of express! If it does, I will attempt to fix\n  the problem, hopefully!\no No options, you cannot change the path to the chatlog, the access-override,\n  or anything like that, without hexediting the util (there are no checksums\n  etc, so you are welcome to if you like - just leave my NAME alone!).\n  (But, as I said, this is a custom util!)\no Doesn''t open a cool window with lots of nice faces to click on like OpWin.\no There is no way of a allowing damm you fuctional power to the gibberdrive.\no I''m not sure if the /X 3 function of limiting the number of times a user\n  can page the sysop will work or not. I certainly haven''t added any code\n  to support this! (Again, this feature appears to be undocumented in the\n  list of /X door commands - It wouldn''t surprise me if they forgot to add\n  the ability to access this information via the doorport).\no It has a really silly name!\n\n\nFuture:\no Add ability to display sysop defined text file telling the users not to\n  bother wasting their time paging coz the sysop never answers anyway.\n\n\n\n\n\nInstallation:\no Boot you harddrive, go to a shell window and type:\n--- CUT HERE ---\nCD SYS:System\nFORMAT DRIVE DH0: NAME SPINNINGGONADS NOICONS QUICK\n--- CUT HERE ---\n  and press returns a couple of times. Ignore the warning messages, they are\n  only there because I did not have enough time to finish coding the install\n  program which is an adaptation of the FORMAT command.\no On the other hand, if you with to install the program by hand, you should\n  use your hands to type to a shell, or control the mouse in DirOpus, and make\n  a directory in your DOORS: assign called SPage\n\nMakedir DOORS:SPage\n\n  (If you don''t have a Doors: assign, make one - it''s pretty standard these\n  days to have one if you''re running Express).\n\n  This directory MUST be made because the program will create a Chat-Log in\n  there! The path is hard-coded into the util! (See unfeatures).\n\n  Then copy the main program (SPageNTProIII.x) and the doc file\n  (SPageNTProIII.Doc) into this directory. (You should always keep the docs!)\n  Alternatively, you can put the docs in a dir with all your others and can\n  then spend ages looking for stuff at a later date like I do).\n\n  Then set the door up with Express.\n  Normally you would give it the name "O" (or "*O", or however you enable\n  the "retard commands" (their name, not mine) in your version of Express)\n  The door is an XIM type (Assembler), requires a very small stack (leave it\n  as the default), and can be made resident if you want to. Obviously, the\n  path to the door is "Doors:SPage/SPageNTProIII.x". Oh yeah, it IS multinode\n  compatable.\n\nThat''s it really.\n\nSome Greets to:\nHydro, Sweet Think, Dream Warrior, Thrash, Ice D, Marvin, Sigma Seven, Dan,\nPicard, Big Boss, Kool Falco, King Of Zombies, Caffeeiinnee, Wintermute,\nMumu and Thargy, Sprog!!, Bluelight, Metalbasher, Dr.G, 2-Cool, Retaliator,\nT.G.R, Rasta Catcha, Nameless, my friends at school, and everyone I forgot...\n(...and VitalStatistix who gets to be last for having an unspellable name.)\n(...and DreamScape, who gets to be double-last for lunching me).\n\n					P0T-NOoDLE, August 1994\n------------------------------------------------------------------------------\n¹ AB stands for Ambiguous.\n² BD stands for Badly Documented.\n³ Many thanks to DreamScape for inspiration.  huuuuuugghhhhh\n* OK, i Lied.\n^ There were no "^"s.\n% None of them either.\n@ RO stands for rip off.\n','\n',char(10)),NULL,'auto-added',11721,5,0,NULL,NULL,'spagent','scan',1780048740);
INSERT INTO door_catalog VALUES('spd_muna','SPD$MUNA.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SPD$MUNA.LHA',NULL,'XIM','-------------------------------------------',NULL,NULL,NULL,'#>>###>>>### WORLD RELEASE BY: ###<<<###<<# ------------------------------------------- » S·P·E·D·E·S·1·9·9·5 «',replace('-------------------------------------------\n#>>###>>>### WORLD RELEASE BY: ###<<<###<<#\n-------------------------------------------\n           » S·P·E·D·E·S·1·9·9·5 «\n        ->  /X diViSiON PRESENtS  <-\n           -----------------------\n              PENiS ChECK V1.0ß\n          tHE uLTIMATE uTILITY fOR\n     mESSAGE wRITING aND pENIS cHECKING   \n-------------------------------------------\n#>>###>>>### ANALTHUNDER BBS!! ###<<<###<<#\n-------------------------------------------','\n',char(10)),'PENiS.dOC',replace('\n PENiSChECk V1.0ß By hUMPPA-kEiKKA / SPEdES /X DiViSiON\n\n iNDEX\n\n 1.0 History\n 1.1 General Information\n 1.2 Huunouz!\n -\n 2.0 How To Install\n 2.1 How To UnInstall\n 2.2 How To ReInstall\n 2.3 How To Register\n -\n 3.0 Pd Notice\n 3.1 Spedes General Distribution Site\n 3.2 Comment And Know Bugs\n -\n\n\n 1.0 History\n\n History is long, penis was found over 1000 years ago.\n\n V0.1  hUMPPA-kEiKKA learned to code with arexx.\n V0.2  Source was stolen.\n V0.5  First public version, World release from Niggers arse BBS.\n V0.9  Major bug added.\n V1.0  Bug removed.\n V1.0ß This Version.\n\n 1.1 General Information\n\n No information avail in this version.\n\n 1.2 Huunouz!\n\n ?\n\n 2.0 How To Install\n\n huhu uhuhu h...Dunno.\n\n 2.1 HoW To Uninstall\n\n Delete user.data.\n\n 2.2 How To Reinstall\n\n Undelete user.data.\n\n 2.3 How To Register\n\n Send 100$ to SPEDE\n              MTV3\n              00300 MTV3\n\n 3.0 Pd Notice\n\n If Avesoft is trying to use this then you must call to local police.\n\n 3.1 Spedes SHit!\n\n ANALTHUNDER PPS\n\n ASK 4 NUP BUT NOT FOR NUMBER!\n\n 3.2 Known bugs\n\n If you are fag your pentiums processor might count it wrong.\n If using AmiExpress BBS software the program doesnt work.\n\n Signed : Dr.fAXi / SPEdES kOUVoLA diViSiON ANd MoRE!\n\n \n','\n',char(10)),NULL,NULL,3896,2,0,NULL,NULL,NULL,'scan',1780048740);
INSERT INTO door_catalog VALUES('speedtxt','SPEEDTXT.LZX','~/Code/amiexpress_doors/Archives/AmiExpress/SPEEDTXT.LZX',NULL,'XIM','SpeedText.exe',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'auto-added',29852,0,0,NULL,NULL,'speedtxt','scan',1780048740);
INSERT INTO door_catalog VALUES('spm_sm30','SPM-SM30.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SPM-SM30.LHA',NULL,'XIM','(------------------------------------------)',NULL,'POGI/Myth','SPM','$VER: STOCK-MARKET 1.30 (02.07.94) /X DOOR (------------------------------------------) ThE BeSt StOcK & CrEdIt-BaNk AvAiLaBlE !!!',replace('(------------------------------------------)\n $VER: STOCK-MARKET 1.30 (02.07.94) /X DOOR\n(------------------------------------------)\n ThE BeSt StOcK & CrEdIt-BaNk AvAiLaBlE !!!\n Written by POGI/Myth - New : Credit Bank .\n(------------------------------------------)\n','\n',char(10)),'stock.doc',replace('\n          ___\n         /     |            |       |\  /|          |         |\n         \__  -+-   __   __ | /     | \/ |  __      | /  __  -+-\n            \  |   /  \ /   |/  --- |    | /  | |_/ |/  /__\  |\n         ___/  \_/ \__/ \__ | \     |    | \__\ |   | \ \___  \_/\n         ========================================================\n\n                 ->   Stock-Market V1.30 By Pogi/Myth   <-\n                       ->  Call-Ware  Version   <-\n                   ->      Released on 02-07-94      <-\n              Call Myth BBS  +36-1-173-05-52  22.00-3.00 CET\n            Temp. number from 6 Jun for a month: +36-129-94-98\n            ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nPurpose:\n~~~~~~~~\n   This is a Credit-Win Door. You can buy Stocks & your\n   Stocks give you Dividend. It''s so simple.\n   It''s useful for those SysOps who give e.g. 1:3 ratio\n   for every user, because if a user upload a lot, he\n   can buy good Stocks & get Dividend, but those users\n   who upload only a few bytes can only buy worse Stocks\n   and get less Dividend...\n   Only for users with enabled ratio !!!\n   I''m a SysOp and I use this door. It''s fun!\n\n\nRequirements:\n~~~~~~~~~~~~~\n   /X 3.9++ running on any Amiga.\n   It requires REXXDOOR to be in your BBS:Utils\n   directory. REXXDOOR needs RexxMast & some Rexx\n   command in your REXX: assign.\n\n\nInstallation:\n~~~~~~~~~~~~~\n   See Update if you have already installed a previous version.\n   It''s very simple. Just copy all files into BBS:.\n   You can now start the door using the STOCK command\n   in the main menu of /X.\n   It writes a LOGFILE, which is ''BBS:Screens/Conf/Bulletins/Bull2.txt''\n   by default... You can change it by editing of the STOCK.rexx file in\n   the ''DOORS:STOCK/'' directory. Edit the line:\n\n   bullet    = ''BBS:Screens/Conf/Bulletins/Bull2.txt''\n\n   You can also edit other things here, e.g. the default stock rate.\n\n   That''s all folks!\n\n\nUpdate from a previous version:\n-------------------------------\n   All you need is to copy the file ''STOCK.rexx'' to your\n   ''BBS:Doors/Stock/'' directory. All data will be preserved.\n   There is a new file in this version called ''help.txt''.\n   You also have to copy this into ''BBS:Doors/Stock/''.\n   In this version there are several other files.\n   You should copy all of them to the given directory.\n\n\nUse:\n~~~~\n   If you type STOCK at the main menu of /X, the door will start.\n   If it is the first time you start it, you will get a stock\n   of yours for 250.000 ulcredit.\n   You will see a list of your dividends like this:\n\nStockName.......Dividend\n========================\nYourName...............0\n========================\n\n   It means that you got 0 ulcredits for Stocks of yours.\n   If you buy other Stocks this list can looks like this:\n\nStockName.......Dividend\n========================\nYourName..........123456\nPogi.............1234567\nLazyBoy................0\n========================\n\n   If you press space you will see another list:\n\n#...StockName........MidRate.All/Own..BuyRate.SellRate..TotalULB\n================================================================\n1...Pogi.............2431807...18/16..2796578..2067035..38521319\n2...YourName.........1163089....12/7..1337552...988625..11619427\n3...LazyBoy...........250000.....1/0...287500...212500...1340621\n================================================================\n\n\nYou have 878356 ULCredits.\n(L)ist - (B)uy - (S)ell - (H)elp - (A)bort - (Q)uit :\n\n   It is the list of the Stocks. # is the ID of the Stock.\n   You enter this if you buy or sell Stocks. StockName is the\n   name of the Stock (surpize :-). Your dividend:\n\n   Dividend = 0.5 * BytesUpload * Own / All\n\n   e.g. if you have 4 Stock of Pogi from 16 and Pogi uploaded\n   9876536 bytes :\n\n   Dividend = 0.5 * 9876536 * 4 / 16 = 1234567 (ULCredits)\n\n   You can sell your Stocks for SellRate and buy Stocks for BuyRate.\n\n   TotalULB is the total uploaded bytes by ''StockName'' (e.g. by Pogi).\n\n   You get the same list for the L command.\n\n   In the bank you can deposit and withdraw money. It gives you\n\n   average interest rates, so it''s safer to keep you credits here\n\n   rather than in stocks.\n\n   Use Q to quit with saving changes, otherwise use A to abort.\n\nIf you have any Questions or Suggestions, please call Myth BBS!\n\nI hope that the door is easy-to-use enough so that you can manage to use it.\n\n\nHistory:\n~~~~~~~~\n   V1.30- Several updates. Versions 1.19-1.29 is not released.\n          New menu: Go to the Bank - It''s not only a Stock-Market any more.\n          Wider lists & log. And more...\n\n   V1.18- Lists TotalULB in the list of the stock\n\n   V1.17- New menu: Abort --> faster than Q & N\n\n   V1.16- Bug Fixed: it wasn''t compatible with the\n          previous versions due to a minor bug.\n\n   V1.15- OnLine Help\n          Bug Fixed: used to make error messages if the\n           username contained ''/'' and chars like this.\n\n   V1.12- Some minor changes\n\n   V1.1 - Better LOG & Stock Listing\n          Bug Fixed: used to divide with 0 when ratio=0...\n          More docs\n\n   V1.0 - First public release\n\n\nRegistration:\n~~~~~~~~~~~~~\n   Call Myth BBS for info... & write a message to the SysOp!\n\n\n--------------------------------------------------------\nIf you have PGP, please have a look at ''STOCK.rexx.asc''.\nIt contains the signiture of ''STOCK.rexx''.\nIf you don''t have PGP, call Myth BBS & download it.\nMake sure that you have the original version!\n--------------------------------------------------------\n\nHave fun!\n\n--- END OF FILE ---\n','\n',char(10)),NULL,NULL,14270,10,0,NULL,NULL,NULL,'scan',1780048740);
INSERT INTO door_catalog VALUES('spr_sdiz','SPR-SDIZ.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SPR-SDIZ.LHA','gifdesc','XIM','SnatchDIZ',NULL,NULL,'SPR','_/  ___/__/_  ____  \_\____  \_ \_______    \_\______/   _/  _/_ .---_/      \/     /    _/     \      \_---.',replace('        ______   _________  _______\n      _/  ___/__/_  ____  \_\____  \_\n      \_______    \_\______/   _/  _/_\n.---_/      \/     /    _/     \      \_---.\n|   \_____________/_____\_______\      /   |\n|       SUPREME GIVES YA IN 1995 \____/    |\n|              SnatchDIZ V2.0              |\n|   BEST and QUICKEST file_id extractor!   |\n| For DMS, LHA, LZX, EXE, TXT, ZIP and GIF |\n| 100% highly optimized asm!  Code: rASCAL |\n`-------------------------------------m!^dG''\n','\n',char(10)),'SnatchDIZ.guide',replace('@database\n@node main "SnatchDIZ V2.0 docs"\n@{b}         ______   ___ ___  _______  _____  ________ ___ ___  ________\n       _/  ___/__/   Y   \/  ___  \_\___ \_  _____//   Y   \/  _____/\n       \______   \   |    \  \_____/ __/ _/_ _)_____        \  _)_____\n.___ _/     \/    \_ ·     \_   \_ __\      \       \_\_/    \        \_ ___.\n|   \\             /        /    // / \      \_      / ·      \_ m!^dG //   |\n|____\\___________/________/____//_/___\      /_____/__|       /______//____|\n·""""" """""""""""""""""""""""""""""""""\____/"""""""""|______/""""""" """""·@{ub}\n            @{fg highlight}SnatchDIZ V2.0 - © by rASCAL/SUPREME on 19.4.95@{fg text}\n\n\n			    @{"    Purpose     " link 1}\n\n			    @{"     Usage      " link 2}\n\n			    @{"  Requirements  " link 3}\n\n			    @{"   Greetings    " link 4}\n\n			    @{"    History     " link 5}\n\n\n                 @{b}kEEP tHE aMIGA aLIVE aND ... lEGALIZE iT!@{ub}\n\n@endnode\n@node 1 "What the fuck..."\n\nSnatchDIZ  is  another  FILE_ID.DIZ extractor for the Shell or for use with\nany bbs-system.  Features:\n\n - LHA-, LZX-, ZIP-, DMS-, EXE-, GIF-, TXT-Support\n - SnatchDIZ is smaller than 3 KB and faaaaaaaaaaaaaaaaaaaast!\n - great code: SnatchDIZ does not produce HITS like WhaDIZ, SpeeDIZ etc.\n - good error handling: No problems with empty files or something\n\n-=> Use SnatchDIZ instead of all the other crap floating around!\n@endnode\n@node 2 "It''s easy..."\n\nUsage: SnatchDIZ FILE/A,S=SUPPRESS/S,K=KEEPDIZ/S\n==============================================\n\nFor example:  "SnatchDIZ dh0:down/PPLAY41.LZX S K" will give you\n\n--------------------------------------\nPower Player 4.1 Final Omega Version\n* Latest Update! *\n--------------------------------------\n\nThis extracts and shows the FILE_ID, suppresses the About text and does NOT\ndelete  the  file  t:file_id.diz (which is temporarily created) so that you\nmay  use  it  in any way.  The file t:file_id.diz is only created for dms-,\nlha-, lzx- and zip-files.\n\n\nWARNINGS: - SnatchDIZ is cli-only so don''t start from Workbench!\n          - SnatchDIZ was NOT TESTED AT ALL with GIFs!\n@endnode\n@node 3 "You got this crap..."\n\nYou need:\n\n - an AMIGA w/Kick 2.04+ (as always).\n - the lha-, lzx-, GIFdesc- and UNzip-executable placed in your path.\n   A working UNzip and GIFdesc is included in the SnatchDIZ-archive.\n\nThat''s it.\n@endnode\n@node 4 "Hallöle..."\n\nGreetings to all SUPREME and CAFFEiNE membaz!\n@endnode\n@node 5 "Versions..."\n\nV0.9:	not released but seems to work properly.\nV1.0:	added filetype indicator and the SUPPRESS option.\n	1st release (under CAFFEiNE label)!\nV2.0:	added own routine for search in DMSs (MUCH FASTER than DMS VIEWDIZ)\n	optimzed search in executables A LOT!\n\n@endnode\n','\n',char(10)),NULL,'auto-added',58313,1,0,NULL,NULL,'spr_sdiz','scan',1780048740);
INSERT INTO door_catalog VALUES('sr_fc100','SR-FC100.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SR-FC100.LHA','FiLECOMMENT','XIM','FiLECOMMENT',NULL,'MFM/SKID','SR','\// ___/ | _/ |___ \   / __/ ___/ |_| \\/ 9 _\__  \ _ \  |  |  \ /  |/  |  \ | | /   9 \_____/_| /__|_____/ \__|\_____/____/    4',replace(' __ _____/|___/|____     /\_________ |\ __ 1\n \// ___/ | _/ |___ \   / __/ ___/ |_| \\/ 9\n  _\__  \ _ \  |  |  \ /  |/  |  \ | | /   9\n  \_____/_| /__|_____/ \__|\_____/____/    4\n.---------|/-[ /X UTILITIES DIVISION ]-----.\n| -> FileComment v1.00 by MFM/SKID ROW! <- |\n| The best ''fake'' comment door you''ve seen |\n| Now compatible with ByteKiller 2.0-fake, |\n| (but better^faster), so that you can use |\n| it with ByteKiller2! FAAAST! NICE! MFM''94|\n`------------------------------------------''\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-24-18  TIME: 09:56:13  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',7858,2,0,NULL,NULL,'sr_fc100','scan',1780048740);
INSERT INTO door_catalog VALUES('sr_fr131','SR-FR131.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SR-FR131.LHA','DioFront','XIM','DioFront','1.31',NULL,'SR','/  ____ ¬| _____)___ ¬|  \___ ____. ¬|¬|¬| ) \___ ¬\  _  /  ¬\  /  |  /  _  / ¬|  | | | \ /_____/__|  \_  /___  |  \__|  \___  l_____/',replace('DIOFRONT V1.31/\__FINAL  ________/|__._._._\n/  ____ ¬| _____)___ ¬|  \___ ____. ¬|¬|¬| )\n\___ ¬\  _  /  ¬\  /  |  /  _  / ¬|  | | | \\n/_____/__|  \_  /___  |  \__|  \___  l_____/\n        ¬`---''\/tGø`--''    ¬`---'' `--''\nDIOGENES/SKIDROW! IS NOT DEAD AND COMES BACK\nWITH DA MOST ASTONISHING WHO/FRONTEND EVER\nMADE. TRY TO BELIEVE IT, TRY IT, LOVE IT,\nKILL TO KEEP IT... NO NEED TO SAY MORE\nCODED FOR THE AWESOME TEMPEST BBS PROGRAM\n          SKIDROW ''96 - DA FAMILY\n[÷] dIZ 1 fROM [-nINO!] ÷ gANGSTAS ÷ I^C [÷]\n','\n',char(10)),'DioFront.Guide',replace('@database DIO-FRONT-DOC\n@Author DIOGENES / SKID ROW!\n@Index MAIN\n\nCopyright (c) 1995-1996 DIOGENES / SKID ROW!\n\n@Remark $VER: (January 22 1995, 19:39:37)\n@Remark AmigaGuide database for the DIO-FRONT Documentation\n\n@node MAIN "DIO-FRONT Documentation (c)1995-1996 DIOGENES of SKID ROW! (January 21 1995, 19:39:37)"\n                                          :              __\n                                          ¦             /\_\             .\n             .____________________________!___________/\\/_____________ _!_\n             |                           \|         __/\\/               |\n   __________l______ _____________________l         \_\/                 ¦\n _/    ________   ¬T/    /_____________   ¬\_                            ¦\n T______    ¬T     ¬    < |    ¬|    ¬T     T      >>> DIO-FRONT <<<     :\n |    ¬T     |     T     \|     |     |     |                            ·\n |___________¦_____|\     \_____¦___________¦ Code: DIOGENES / SKID ROW! |\n             ¦       \_____\              |                              |\n             |                            |                              ¦\n             |                      ______l________________        _____ ¦\n             :                      \______   ¬\         ¬|\      /    / :\n             `-----------------------T    _    /    |     | \    /    /--''\n                                     |    T    \_   |     |  \/\/    /\n                                     |____|     T_________¦         /\n                                          |_____¦      MpLx___/\___/\n\n\n         >>> C·O·N·T·E·N·T·S  O·F  D·O·C·U·M·E·N·T·A·T·I·O·N <<<\n\n                         @{"      Introduction       " Link Cap01}\n                         @{"      Requirements       " Link Cap02}\n                         @{"      Installation       " Link Cap03}\n                         @{"      Configuration      " Link Cap04}\n                         @{"     Special -Styles     " Link Cap09}\n                         @{"         History         " Link Cap05}\n                         @{"         Fu-ture         " Link Cap06}\n                         @{"    Other Tools By Me    " Link Cap10}\n                         @{"        Greetings        " Link Cap07}\n                         @{"    How To Contact Me    " Link Cap08}\n\n         ----------------------------------------------------------\n               Complete Docs for DIO-FRONT V1.31 [-SKID ROW!-]\n         ----------------------------------------------------------\n         The Documentation has been written by DIOGENES / SKID ROW!.\n\n@endnode\n@node Cap01 "Introduction."\n  =======================================================================\n\n  DIO-FRONT is at the same time a "Front-End" and a "Who" door for the\nTEMPEST BBS Program. DIO-FRONT is at this time still the best choice,\nthere is no other tool offering the same possibilities, and no coder\noffering the same support:\n\n\n - DIO-FRONT is at the same time a "Front-End" and a "Who". The door\n   will detect if it was called before or after the login procedure,\n   and you can configure DIO-FRONT for both modes.\n\n - DIO-FRONT is a fast TEMPEST door 100% coded in highly optimised\n   assembler with the experience of ages, based on plenty different\n   parameters stored in an ascii config. file, offering unlimited power,\n   features never seen in other stand alone WHO''s or FRONTEND''s.\n\n - DIO-FRONT is design modules-based. In short, DIO-FRONT consists in a\n   body, and several modules for the various displays. Nothing easier than\n   removing/adding/modifying a style. It is therefore possible for any\n   sysop to just draw the WHO / FRONTEND they''ve always dreamt of and send\n   me the ansi file. I will encode it.\n\n   Each style can be used for either the WHO mode, the FrontEnd mode, or\n   both at the same time.\n\n   DIO-FRONT currently offers 12 different styles. This will grow only if\n   sysops send me ansi defs.\n\n - DIO-FRONT is security level based: you can turn on selective output for\n   target users or ALL users so they can see only users of the same security\n   level and lower.\n\n - DIO-FRONT in WHO mode can monitor the nodes activities.\n\n - DIO-FRONT respects the HIDDEN flag (INV(isibility) command). I have never\n   seen a decent Front-End/Who hidding hidden users ;)\n\n - DIO-FRONT has been intensively tested during the coding phase, and has\n   been in hard ßeta testing phase during a full month before it was\n   released to reduce to 0.1% the possibility of remaining bugs which could\n   cause Bulletin Boards locks, crashes, and/or even HD damages. The\n   executable in your hands is now considered as stable and working. No hurry.\n\n - DIO-FRONT does not display the ugly programmer''s name, or any other\n   useless advertisement. This is the only professional way to code.\n\n - DIO-TOP is a DIOGENES production :)  This means bug fixes, improvements,\n   upgrades, and all this for free. Send me suggestions, bug reports, and I\n   will modify the program. Draw and send me a new style, and I will include\n   it.\n\n\n  Remember the "Diogenes" label: "listen to suggestions, improve, make\nit unbeatable" ;)\n\n  Using my tools also means reading the docs FIRST. Incorrect or incomplete\ninstallations mean probable errors and less power.\n\n  =======================================================================\n@endnode\n@node Cap02 "Requirements."\n  =======================================================================\n\n  In order to see DIO-FRONT running, and running well:\n\n  - You need Tempest V3.30+ running; The door was never tested with lower\n    versions;\n\n  - You have to follow the installation procedure strictly.\n\n\n  DIO-FRONT was not tested on 68000 but should work fine. I do not exclude\n  though odd adresses problems, I could have left some by mistake.\n\n  DIO-FRONT is not forseen to display more than 99 nodes for layout reasons.\n  If you have more, let me know.\n\n  Still for layout reasons, DIO-FRONT has room forseen for 99 conferences\n  max. If you have more, let me know.\n\n\n  =======================================================================\n@endnode\n@node Cap03 "How to install DIO-FRONT."\n  =======================================================================\n\n  1- Make a directory anywhere and copy in it the executables, data files and\n     sub-directories needed by the door.\n\n  2- Assign DIOGENES: to this directory\n\n     * in your startup-sequence to be able to use the doors/utils all the time;\n     * in Shell to be able to test it immediately :-)\n\n  3- Make a directory DATA in your DIOGENES: directory. This is NEEDED.\n\n  4- Read the documentation and change the config file to fit your needs.\n\n  5- Add this line to your TEMPEST:TEXT/language/TEXT-POSTCONNECT textfile:\n\n     ~TD(DIOGENES:DioFront)          ... if you wish to have a Front-End\n\n  6- Add this line to your TEMPEST:TEXT/language/TEXT-POSTLOGON textfile:\n\n     ~TD(DIOGENES:DioLogin)          ... NEEDED for several of my utils !\n\n  7- Add this line to your TEMPEST:OPTIONAL/GLOBALMENU.OPT textfile:\n\n     [10-,*,*,*,*]=WHO|T-DOOR|DIOGENES:DioFront\n\n     ... if you wish to replace the Tempest internal WHO by DIO-FRONT\n\n     You''ll probably also wish to KILL the WH and WHM commands which call\n     the Tempest internal WHO. Though, this is not very useful. I have asked\n     Skeleton to change his commands management several times, but he doesn''t\n     seem to wish to. As you might know, Tempest does not recognise commands\n     strictly but only looks at the first chars. Therefore, if you configure\n     WHO, kill WH and WHM, it will NOT prevent Tempest from poping up his\n     internal Who when you type Whom, or Whoooooo, or Whhhhhhh, or anything\n     beginning with ''Wh'' :(    Let''s hope he will consider my (numerous ;) )\n     suggestions one day.\n\n  The reason for this DIOGENES: is that several utils of me use the same data\n  files, and it is much more easy to have them all at the same place.\n\n  Don''t forget DIOLOGIN, this utility is used by DIO-FrontEnd, and ALSO by\n  other of my utils. You HAVE to call it in your TEXT-POSTLOGON textfile.\n \n  BE AWARE that the total calls value AND OTHER VALUES will be wrong till\n  DIOLOGIN is called from all of your nodes. Wait for a call to occur on each\n  of your nodes to see a correct calls total.\n\n  =======================================================================\n@endnode\n@node Cap05 "History."\n  =======================================================================\n\n V1.0:  First official release.\n\n V1.31: - Fixed a bug in the ''Fill BBS Number'' routines in Styles\n          #2, #6, #7 & #8\n\n        - Styles #3, #5, #7, #8, #9, & #12 did not display the footer\n          when hiding the last node. This is now fixed.\n\n        - Styles #3, #4, #5, #6, #7, #8, #10, #11, & #12 displayed\n          1 node separator too much when the last node displayed was\n          not the last real node (last node(s) hidden). This is now\n          fixed.\n\n        - Modified all styles a bit to avoid a possibly future bug\n          occuring.\n\n        Thanx to ULI for using his last node as his local node :-)\n        These bugs were really beginner mistakes, shame on me !\n\n        - Fixed a bug in one of the actions redefines routines.\n \n  =======================================================================\n@endnode\n@node Cap06 "Future."\n  =======================================================================\n\n  - Use "," for big calls value (4,213 instead of 4213 for example) if space\n    allows.\n\n  - Allow skipping local/custom nodes total calls for the System Total Calls.\n    Tell me if you need this.\n\n  - Redefinable fields names.\n\n  - Prompt line commands to be implemented once Tempest allows parameters\n    on the prompt line:\n\n    * ? (WHO ?) ... List 2 next line commands\n    * m (WHO m) ... Monitor nodes activities\n    * e (WHO e) ... Edit personal config\n\n    The door will thus of course support personal configurations, and\n    the following flags: FRONTEND_MAX_ACCESS, FRONTEND_CONF.x,\n    MONITOR_ACCESS, CONFIG_ACCESS, EDITNAME_ACCESS, EDITLOCATION_ACCESS,\n    HIDE_ACCESS. See extended descriptions in the documentation later.\n\n    Internal ßeta parameters:\n\n     FRONTEND_MAX_ACCESS=\n     FRONTEND_CONF.1=1\n     FRONTEND_CONF.2=2\n     MONITOR_ACCESS=50\n     CONFIG_ACCESS=50\n     EDITNAME_ACCESS=200\n     EDITLOCATION_ACCESS=200\n     HIDE_ACCESS=200\n\n    Though, opening a configuration file for each active node might\n    take too much time and the personal configurations feature could\n    be canceled. To be tested..\n\n  - Maybe a CONFERENCE_ALIAS parameter to replace the "00" when\n    FRONT/WHO_SHOW_CONF=No ?   or use FRONT/WHO_SHOW_CONF="xx" ?\n\n  =======================================================================\n@endnode\n@node Cap07 "Greetings go to..."\n  =======================================================================\n\n                        SHORT GREETS GO TO THESE SYSOPS:\n\n\n    ULI ............................................ Thnx for everything!\n    James West ...................................... Do you miss me ? ;)\n    Skeleton ................................................ Great Work!\n    Big Boss/Fairlight ..................... Hope to see ya back one day!\n    John Yaya/LSD .................................. Ma friend I miss ya!\n    Sintax/WoT/OTL ..................... I definitively hate Belgacom ;-)\n\n And in no f****ing order:\n\n    Yoda, Flasher, Josh, Dracs, VAX6410, Warlock, Rhys/Delirium, Insider,\n    Alkaid, MouseBuster, Colonel, Delirium & Kickface, XRay2000, Coydog,\n    TFX, Mr. Solo, Wargames (or Lando), Chelsea, Scouser, Rique,\n\n                           ... And the masses I cannot remember right now\n\n Groups omitted when not sure ;)\n\n\n                        >>> ALL SKID ROW MEMBERS!!! <<<\n\n                          >>> ALL TEMPEST SYSOPS! <<<\n\n  =======================================================================\n@endnode\n@node Cap08 "How to contact me."\n  =======================================================================\n                  ________  __________________  ____    ._\n                 /  ____/ |/   /_)___  \____  \/:   \__.|:\\n                 \____ \  /  _/ :| :|\  \ _/ _/  /\  \ ||  \.\n                 /:  /  \ \   \_ |  |/  / \_  \_ \/  / /\   \\n                 \______/:|\___/_|_____/  :|___/____/  /\___/\n                 -Stz-|___|- DIOGENES -|___|------\___/------\n\n                 Email: [email removed]\n\n                 Call these boards to find me and/or the latest\n                 updates of all my tools.\n\n\n PEACE CHAPEL .......... LB/Diogenes ...... +32-(0)2-331-38-09\n                                 SR!        +32-(0)2-RINGDOWN!\n                                            +32-(0)2-RINGDOWN!\n\n FLYING SAUCER ................. ULI ...... +32-(0)87-86-68-08\n                                            +32-(0)87-86-60-36\n                                            +32-(0)87-  ISDN\n                                            +32-(0)87-  ISDN\n\n DAWN OF ETERNITY ........ Skeleton ....... +1-515-255-3212\n                            /T\ WHQ         10Ndz RingDown\n\n 7 SEAS ................. James West ...... +1-612-522-6210\n                                            +1-612-522-9691\n                                            DO NOT REMEMBER.\n\n And maybe a board you are on, but I call less there :-)\n\n  =======================================================================\n@endnode\n@node Cap09 "Limitations & special styles."\n  =======================================================================\n\n I wished there were no limits ;-)\n\n - Style #03: Custom BBS names not allowed.\n\n - Style #09: Custom BBS names not allowed.\n\n - Style #12: Custom BBS names not allowed.\n\n As a matter of fact, long BBS names will of course trash the display for\n styles offering few room.\n\n ''Special'':\n\n - Style #08: Up to 11 chars allowed for the BBS number instead of 8.\n\n - Style #10: The username field will be used to show ''connecting'';\n\n - Style #11: The username field will be used to show ''connecting'';\n\n  =======================================================================\n@endnode\n@node Cap10 "Other DIOGENES Tools."\n  =======================================================================\n\n Private. Call me.\n\n  =======================================================================\n@endnode\n@node Cap04 "Configuration."\n  =======================================================================\n\n You can edit the following flags in the DIOGENES:DIOFRONT.CFG ascii file.\n\n A parameter is valid only if beginning at column 1, and if there is a\n carriage return right after, and nothing else... No space, no comment,\n just nothing :)\n\n                           .-----------------------.\n                           |  Standard Parameters  |\n                           `-----------------------''\n\n         @{"   BBSNAME_FRONT.x         " Link Tool01}     @{"   FRONT_HIDE_SHUTDOWN     " Link Tool13}\n         @{"   BBSNAME_WHO.x           " Link Tool02}     @{"   WHO_HIDE_SHUTDOWN       " Link Tool14}\n         @{"   FRONTEND_STYLE          " Link Tool03}     @{"   FRONT_HIDE_WAITING      " Link Tool15}\n         @{"   WHO_STYLE               " Link Tool04}     @{"   WHO_HIDE_WAITING        " Link Tool16}\n         @{"   FRONTEND_CLEARSCR       " Link Tool05}     @{"   FRONT_OWN_STRING        " Link Tool17}\n         @{"   WHO_CLEARSCR            " Link Tool06}     @{"   WHO_OWN_STRING          " Link Tool18}\n         @{"   SECURITY_ACCESS         " Link Tool07}     @{"   FRONT_SHOW_ULFILENAME   " Link Tool19}\n         @{"   HIDDEN_NAME             " Link Tool08}     @{"   FRONT_SHOW_DLFILENAME   " Link Tool20}\n         @{"   HIDDEN_LOCATION         " Link Tool09}     @{"   WHO_SHOW_ULFILENAME     " Link Tool21}\n         @{"   NUMBER.x                " Link Tool10}     @{"   WHO_SHOW_DLFILENAME     " Link Tool22}\n         @{"   FRONT_HIDE_NODE.x       " Link Tool11}     @{"   FRONT_SHOW_CONF         " Link Tool23}\n         @{"   WHO_HIDE_NODE.x         " Link Tool12}     @{"   WHO_SHOW_CONF           " Link Tool24}\n\n         @{"   Redefines               " Link Tool25}\n\n                        .------------------------------.\n                        |  User Preferences Parameters |\n                        `------------------------------''\n\n                                 --------------\n\n\n\n  =======================================================================\n@endnode\n@node Tool01 "Parameter BBSNAME_FRONT.x."\n  =======================================================================\n\n  BBSNAME_FRONT.x= Custom BBS Name\n\n    Tempest allows only plain ascii BBS names. DIO-FRONT allows you to\n    use a different BBS name in the Front-End display, and to use ansi\n    codes. One different BBS name can be used for each of the 12\n    available Front-End styles to be closer to the style.\n\n    The "[D" (1 character backwards) and "[C" (1 character forwards)\n    ansi codes can be used for fine/personal tuning of the BBS name position.\n\n    Example:     BBSNAME_FRONT.1=[42;33m Pe/\ce [43;32m Ch/\pel [0m\n                 BBSNAME_FRONT.2=[D[45;33m Pe/\ce [43;35m Ch/\pel [0m\n\n    WARNING:     The styles #3, #9 & #12 do NOT use custom BBS names because\n                 it was not possible predicting 100% correct output if ansi\n                 codes were used. I love perfection :)\n\n    If this parameter doesn''t exist, the real BBS name will be used.\n\n  =======================================================================\n@endnode\n@node Tool02 "Parameter BBSNAME_WHO.x."\n  =======================================================================\n\n  BBSNAME_WHO.x= Custom BBS Name\n\n    Tempest allows only plain ascii BBS names. DIO-FRONT allows you to\n    use a different BBS name in the WHO display, and to use ansi codes.\n    One different BBS name can be used for each of the 12 available WHO\n    styles to be closer to the style.\n\n    The "[D" (1 character backwards) and "[C" (1 character forwards)\n    ansi codes can be used for fine/personal tuning of the BBS name position.\n\n    Example:     BBSNAME_WHO.1=[42;33m Pe/\ce [43;32m Ch/\pel [0m\n                 BBSNAME_WHO.2=[D[45;33m Pe/\ce [43;35m Ch/\pel [0m\n\n    WARNING:     The styles #3, #9 & #12 do NOT use custom BBS names because\n                 it was not possible predicting 100% correct output if ansi\n                 codes were used. I love perfection :)\n\n    If this parameter doesn''t exist, the real BBS name will be used.\n\n  =======================================================================\n@endnode\n@node Tool03 "Parameter FRONTEND_STYLE."\n  =======================================================================\n\n  FRONTEND_STYLE= Style Number\n\n    DIO-FRONT currently integrates 12 standard Front-End/Who designs.\n    You can use a different one for the WHO and for the Front-End.\n\n    Example:     FRONTEND_STYLE=1\n\n    If this parameter doesn''t exist, the FIRST design will be used.\n\n  =======================================================================\n@endnode\n@node Tool04 "Parameter WHO_STYLE."\n  =======================================================================\n\n  WHO_STYLE= Style Number\n\n    DIO-FRONT currently integrates 12 standard Front-End/Who designs.\n    You can use a different one for the WHO and for the Front-End.\n\n    Example:     WHO_STYLE=2\n\n    If this parameter doesn''t exist, the SECOND design will be used.\n\n  =======================================================================\n@endnode\n@node Tool05 "Parameter FRONTEND_CLEARSCR."\n  =======================================================================\n\n  FRONTEND_CLEARSCR= Yes/No\n\n    When set, this parameter causes DIO-FRONT to clear the screen before\n    any output in Front-End mode.\n\n    If this parameter doesn''t exist, the screen is not cleared.\n\n  =======================================================================\n@endnode\n@node Tool06 "Parameter WHO_CLEARSCR."\n  =======================================================================\n\n  WHO_CLEARSCR= Yes/No\n\n    When set, this parameter causes DIO-FRONT to clear the screen before\n    any output in WHO mode.\n\n    If this parameter doesn''t exist, the screen is not cleared.\n\n  =======================================================================\n@endnode\n@node Tool07 "Parameter SECURITY_ACCESS."\n  =======================================================================\n\n  SECURITY_ACCESS= Security Level / "ALL"\n\n    This parameter is only checked in WHO mode !\n\n    SECURITY_ACCESS=ALL          ALL users, without any exception, will\n                                 see only users of the same security\n                                 level and below. The other nodes will\n                                 show "AWAITING CONNECT" as if there was\n                                 nobody on-line.\n\n    SECURITY_ACCESS=20           In this case, only users of security\n                                 level 20 and lower will be concerned\n                                 by the check. A user of security level\n                                 21 will see users of higher security\n                                 level. A user of security level 10 will\n                                 see only users of security level 10 and\n                                 below.\n\n    If this parameter doesn''t exist, everybody will see everybody ;)\n\n  =======================================================================\n@endnode\n@node Tool08 "Parameter HIDDEN_NAME."\n  =======================================================================\n\n  HIDDEN_NAME= Pseudo Name\n\n    You can specify a default name for hidden users (INV command) instead\n    of the internal one.\n\n    Example:     HIDDEN_NAME=Nobody knows\n\n    If this parameter doesn''t exist, "Someone" is used.\n\n  =======================================================================\n@endnode\n@node Tool09 "Parameter HIDDEN_LOCATION."\n  =======================================================================\n\n  HIDDEN_LOCATION= Pseudo Location\n\n    You can specify a default location for hidden users (INV command) instead\n    of the internal one.\n\n    Example:     HIDDEN_LOCATION=-*- Rest & Peace -*-\n\n    If this parameter doesn''t exist, "Somewhere" is used.\n\n  =======================================================================\n@endnode\n@node Tool10 "Parameter NUMBER.x."\n  =======================================================================\n\n  NUMBER.x= Phone Number\n\n    Some Front-End/Who styles display the node numbers as extra node\n    information. You have therefore to prepare a phone number string for\n    each node.\n\n    8 chars maximum (except for style #8 allowing 11 chars)! To be extended...\n\n                          [------]\n    Example:     NUMBER.1=331-3809\n                 NUMBER.2=PRIVATE!\n\n    If this parameter doesn''t exist, the space will stay blank.\n    If this parameter is longer than 8 chars, it will simply be stripped\n    (above 11 chars for style #11).\n\n  =======================================================================\n@endnode\n@node Tool11 "Parameter FRONT_HIDE_NODE.x."\n  =======================================================================\n\n  FRONT_HIDE_NODE.x= Yes/No\n\n    This parameter allows hiding nodes from the Front-End, like your local\n    node, so users don''t know when you are logged, and so you also show\n    only the real modem nodes.\n\n    "x" stands for the node number. The node number WILL NOT be omitted in\n    the display (01,03 for example), numbering will go as if this node\n    really didn''t exist (01,02 in our example).\n\n    If this parameter doesn''t exist, all nodes are then of course displayed\n    IF FRONT_HIDE_SHUTDOWN and FRONT_HIDE_WAITING are not set. These\n    4 parameters will be evaluated AFTER this FRONT_HIDE_NODE.x check.\n\n  =======================================================================\n@endnode\n@node Tool12 "Parameter WHO_HIDE_NODE.x."\n  =======================================================================\n\n  WHO_HIDE_NODE.x= Yes/No\n\n    This parameter allows hiding nodes from the WHO, like your local node,\n    so users don''t know when you are logged, and so you also show only the\n    real modem nodes.\n\n    "x" stands for the node number. The node number WILL NOT be omitted in\n    the display (01,03 for example), numbering will go as if this node\n    really didn''t exist (01,02 in our example).\n\n    If this parameter doesn''t exist, all nodes are then of course displayed\n    IF WHO_HIDE_SHUTDOWN and WHO_HIDE_WAITING are not set. These 4 parameters\n    will be evaluated AFTER this WHO_HIDE_NODE.x check.\n\n  =======================================================================\n@endnode\n@node Tool13 "Parameter FRONT_HIDE_SHUTDOWN."\n  =======================================================================\n\n  FRONT_HIDE_SHUTDOWN= Yes/No\n\n    This parameter allows hiding inactive nodes from the Front-End.\n\n    The node number WILL be omitted in the display (01,03 for example).\n\n    If this parameter doesn''t exist, all shutdown nodes are displayed,\n    EXCEPT the nodes concerned by the FRONT_HIDE_NODE.x parameter.\n\n  =======================================================================\n@endnode\n@node Tool14 "Parameter WHO_HIDE_SHUTDOWN."\n  =======================================================================\n\n  WHO_HIDE_SHUTDOWN= Yes/No\n\n    This parameter allows hiding inactive nodes from the Front-End.\n\n    The node number WILL be omitted in the display (01,03 for example).\n\n    If this parameter doesn''t exist, all shutdown nodes are displayed,\n    EXCEPT the nodes concerned by the WHO_HIDE_NODE.x parameter.\n\n  =======================================================================\n@endnode\n@node Tool15 "Parameter FRONT_HIDE_WAITING."\n  =======================================================================\n\n  FRONT_HIDE_WAITING= Yes/No\n\n    This parameter allows nodes waiting for a call from the Front-End.\n\n    The node number WILL be omitted in the display (01,03 for example).\n\n    If this parameter doesn''t exist, all free nodes are displayed,\n    EXCEPT the nodes concerned by the FRONT_HIDE_NODE.x parameter.\n\n  =======================================================================\n@endnode\n@node Tool16 "Parameter WHO_HIDE_WAITING."\n  =======================================================================\n\n  WHO_HIDE_WAITING= Yes/No\n\n    This parameter allows hiding nodes waiting for a call from the WHO.\n\n    The node number WILL be omitted in the display (01,03 for example).\n\n    If this parameter doesn''t exist, all free nodes are displayed,\n    EXCEPT the nodes concerned by the WHO_HIDE_NODE.x parameter.\n\n  =======================================================================\n@endnode\n@node Tool17 "Parameter FRONT_OWN_STRING."\n  =======================================================================\n\n  FRONT_OWN_STRING= Pseudo Name\n\n    This parameter allows using a custom string instead of the internal\n    "You!" string when users see their node at the Front-End.\n\n    So... if this parameter doesn''t exist, "You!" is used in the Front-End,\n    as you understood I''m sure :)\n\n  =======================================================================\n@endnode\n@node Tool18 "Parameter WHO_OWN_STRING."\n  =======================================================================\n\n  WHO_OWN_STRING= Pseudo Name\n\n    This parameter allows using a custom string instead of the internal\n    "You!" string when users see their node at the WHO.\n\n    So... if this parameter doesn''t exist, "You!" is used in the WHO,\n    as you understood I''m sure :)\n\n  =======================================================================\n@endnode\n@node Tool19 "Parameter FRONT_SHOW_ULFILENAME."\n  =======================================================================\n\n  FRONT_SHOW_ULFILENAME= Yes/No\n\n    When this parameter is set to NO, people will see "Uploading" (or\n    your own string defined using the action redefiners) at the Front-End.\n    Else, they will see "UL: filename" (redefined "Uploading" strings\n    won''t be used).\n\n    If this parameter doesn''t exist, YES is taken by default.\n\n  =======================================================================\n@endnode\n@node Tool20 "Parameter FRONT_SHOW_DLFILENAME."\n  =======================================================================\n\n  FRONT_SHOW_DLFILENAME= Yes/No\n\n    When this parameter is set to NO, people will see "Downloading" (or\n    your own string defined using the action redefiners) at the Front-End.\n    Else, they will see "DL: filename" (redefined "Downloading" strings\n    won''t be used).\n\n    If this parameter doesn''t exist, YES is taken by default.\n\n  =======================================================================\n@endnode\n@node Tool21 "Parameter WHO_SHOW_ULFILENAME."\n  =======================================================================\n\n  WHO_SHOW_ULFILENAME= Yes/No\n\n    When this parameter is set to NO, people will see "Uploading" (or your\n    own string defined using the action redefiners) at the WHO. Else, they\n    will see "UL: filename" (redefined "Uploading" strings won''t be used).\n\n    If this parameter doesn''t exist, YES is taken by default.\n\n  =======================================================================\n@endnode\n@node Tool22 "Parameter WHO_SHOW_DLFILENAME."\n  =======================================================================\n\n  WHO_SHOW_DLFILENAME= Yes/No\n\n    When this parameter is set to NO, people will see "Downloading" (or your\n    own string defined using the action redefiners) at the WHO. Else, they\n    will see "DL: filename" (redefined "Downloading" strings won''t be used).\n\n    If this parameter doesn''t exist, YES is taken by default.\n\n  =======================================================================\n@endnode\n@node Tool23 "Parameter FRONT_SHOW_CONF."\n  =======================================================================\n\n  FRONT_SHOW_CONF= Yes/No\n\n    When this parameter is set to NO, people will see "00" at the Front-End.\n    Else, they will see the real conference number.\n\n    If this parameter doesn''t exist, YES is taken by default.\n\n  =======================================================================\n@endnode\n@node Tool24 "Parameter WHO_SHOW_CONF."\n  =======================================================================\n\n  WHO_SHOW_CONF= Yes/No\n\n    When this parameter is set to NO, people will see "00" at the WHO.\n    Else, they will see the real conference number.\n\n    If this parameter doesn''t exist, YES is taken by default.\n\n  =======================================================================\n@endnode\n@node Tool25 "Redefines."\n  =======================================================================\n\n  REDEFINE_ACTION_FRONT.x= New Action Name\n  REDEFINE_ACTION_WHO.x= New Action Name\n\n    These REDEFINE parameters allow the sysop to choose custom action names\n    instead of the internal, generic ones. 37 action names are re-definable\n    in this first version of DIO-FRONT. Type the action number instead of "x".\n\n    WARNINGS: * REDEFINE_ACTION_FRONT.34\n                REDEFINE_ACTION_WHO.34      (Waiting For Call)\n\n                ... are a bit different, you can add a node number extension\n                to define an action name for each node. This was suggested\n                by ULI who wished to put his node numbers in this field.\n\n                EXAMPLE: REDEFINE_ACTION_FRONT.34.1=+32-(0)2-331-38-09\n\n              * Actions 10 (Downloading) & 32 (Uploading) are used ONLY if\n                (FRONT/WHO)_SHOW_(UL/DL)FILENAME=NO\n\n    Too long strings will simply be stripped.\n\n    If an internal command is replaced by a door which registers its own\n    name by itself, I don''t know which action name will have priority ;)\n    Will test this later.\n\n    Currently supported internal action names:\n\n     1: About to Download\n     2: About to Upload\n     3: Account Editing\n     4: Archiving Catalogs\n     5: Doors Area\n     6: Archiving Messages\n     7: Chatting Sysop\n     8: Comment to Sysop\n     9: Connecting\n    10: Downloading         REPLACED ONLY IF FRONT/WHO_SHOW_DLFILENAME=NO\n    11: E-Mail Area\n    12: File Listings\n    13: File Mail\n    14: File Maintenance\n    15: Flagging Files\n    16: Idle\n    17: Internode Msg Send\n    18: Internode Live Chat\n    19: Internode Line Chat\n    20: Joining Area\n    21: Logging Off\n    22: Logging On\n    23: New User\n    24: Paging Sysop\n    25: Reading Bulletins\n    26: Reading Messages\n    27: Viewing Text File\n    28: Remote Shell\n    29: Scanning Mail\n    30: Sysop DL\n    31: File Descriptions\n    32: Uploading           REPLACED ONLY IF FRONT/WHO_SHOW_ULFILENAME=NO\n    33: Viewing Archive\n    34: Waiting for Call\n    35: Posting a Message\n    36: Zippy Searching\n    37: Node ShutDown\n\n  =======================================================================\n@endnode\n   ','\n',char(10)),'{"ACCESS":"50","LOCATION":"Pseudo"}','auto-added',62715,12,0,NULL,NULL,'sr_fr131','scan',1780048740);
INSERT INTO door_catalog VALUES('sr_kcv10','SR-KCV10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SR-KCV10.LHA','5D-MultiStart','XIM','5D-MultiStart',NULL,NULL,'SR','/  ____ ¬| _____)___ ¬|  \___ ____. ¬|¬|¬| ) \___ ¬\  _  /  ¬\  /  |  /  _  / ¬|  | | | \ /_____/__|  \_  /___  |  \__|  \___  l_____/',replace(' ________.____/\______.  ________/|__._._._\n/  ____ ¬| _____)___ ¬|  \___ ____. ¬|¬|¬| )\n\___ ¬\  _  /  ¬\  /  |  /  _  / ¬|  | | | \\n/_____/__|  \_  /___  |  \__|  \___  l_____/\n        ¬`---''\/tGø`--''    ¬`---'' `--''\nDIOGENES STRIKES AGAIN WITH KCONVERT V1.0\nCONVERTS THE BYTE VALUES IN /X DIR LISTINGS\nINTO KBYTES VALUES ("1024"="100k"). NO NEED\nTO USE THE BUGGED CREDITS_BY_KBYTES FEATURE\nOF /X TO HAVE A NICE FILE LISTING. CLI\nAND REALTIME DOOR VERSIONS IMPLEMENTED !\n','\n',char(10)),'5D-MultiStart.Guide',replace('@database 5D-MultiStart Documentation\n@Author SvEN tHE CREAToR Of 5tH DyNASTY\n@Index Documentation\n\nCopyright © 1994 SvEN tHE CREAToR / 5tH DyNASTY\n\n@Remark $VER: 5D-MultiStart v0.01 by sTc/5D\n@Remark AmigaGuide database\n\n@node MAIN "5D-MultiStart Documentation © 1994 SvEN tHE CREAToR Of 5tH DyNASTY"\n                                                              :\n                                                       :      ¦             \n                   ________________  __________________¦      |\n            _______\_______       /  \             /   |      |______\n           |  __   _/     /______/____\  _     _  /    ¦      |  __  |\n           |  \/  _\________    \_\  / \/       \/     _      |  \/  |\n           |______\        /     / \/   |       |      /      |______|\n                   \___________ /       |_______|_____/       |Rpd!\n                              \/                     /________|\n                         :           :                                     :\n            ____   :     ¦     :     ¦      · 5 · T · H ·            :     ¦\n  __________\  /___¦    _|__/\ ¦     |_______ _______________________¦     |\n  \______   \\//   |    \____ \|     |   _   \\_____      /       /  |     |\n   /     \   \/    ¦     |   \ \     |   /    \/   /_____/    _  /   ¦     |\n _/       \   \_____     |    \ \_   |   _     \_____   \_     \/_____     |\n \       _/    /   /     |     \     |   /      /   /    /     |     /     |\n  \__________ /__________|     |\ ___|__/_____ /_______ /______|___________|\n            \/           |     ¦ \/          \/       \/\n                         ¦     :     · D · Y · N · A · S · T · Y ·\n                         :\n\n                        ##>>> P r E S E N T S <<<##\n\n                            5D-MultiStart v0.01\n\n                 Coded by SvEN tHE CREAToR of 5th Dynasty\n\n                           @{" Normal Documentation " Link Documentation}\n@endnode\n@node Documentation "5D-MultiStart Documentation"\n              _______________________________________________\n             |                                               |\n             | //                                            |\n             | /                                             |\n             |                                               |\n             |            @{" D e S C R I P T I O N " Link Description}           |\n             |                                               |\n             |           @{" I n S T A L L A T I O N " Link Installation}          |\n             |                                               |\n             |              @{" T o O L T Y P E S " Link Tooltypes}             |\n             |                                               |\n             |              @{" G r E E T I N G S " Link Greetings}             |\n             |                                               |\n             |                                             / |\n             |                                            // |\n             |_______________________________________________|\n\n@endnode\n@node Description "5D-MultiStart Description"\n5D-MultiStart has been coded by SvEN tHE CREAToR/5D!\n\nIt allows the sysop to insert more than one XIM-Door or script for\none command. For example for the FILECHECK in BBS:Commands/SysCmd/.\nI wanted to install a Double Upload Checker and the 5D-AutoFree but it\nwasn''t possible for me. So I coded 5D-MultiStart which allows you\nto start as much doors as you want for one command. You can also use\nit to start more doors for a normal command. You can protect any of\nthese doors with a password which you can enter in the icon in\nBBS:Commands/MultiCmd/. In that directory are ALL Icons for 5D-MultiStart.\nFor the normal Command (f.e.: BBS:Commands/SysCmd/FILECHECK) you should\nuse the icon in this archive in that directory. If you want to use\n5D-MultiStart for another command simply clone that icon and make a new\nicon in BBS:Commands/MultiCmd/ with the command name. Look in the\ntooltypes area to see what you can insert in the icon.\n@endnode\n@node Installation "5D-MultiStart Installation"\nCopy all files which are in the archive bbs directory\nto your bbs directory.\n\nContents of archive:\n===================\n\nBBS/\n    Commands/\n        BBSCmd/\n            TEST.info\n        MultiCmd/\n            FILECHECK.info\n            TEST.info\n        SYSCmd/\n            FILECHECK.info\n    Doors/\n        5D-MultiStart/\n            5D-MultiStart\n            5D-MultiStart.info\n            5D-MultiStart.Guide\n\n===================\n\n@endnode\n@node Greetings "5D-MultiStart Greetings"\nGreetings go to:\n\n           Celator ........... Thank you for helping me with /X!\n           ByteAndi ............ For helping me to learn coding!\n           Prophet .................... For being a nice friend!\n           Snow ...................... Sing mehr lieder, leader!\n           Airworx ................. Continue work as Co Leader!\n           Delta-X ................. When you will merry Murdoc?\n           Strider ........ We should spread our standard again!\n\nSorry to all people I forgot but as you know my brain isn''t so well! hehe\n\n@endnode\n@node Tooltypes "5D-MultiStart Tooltypes"\nYou can insert the following tooltypes in the icons in\nBBS:Commands/MultiCmd/\n\n===========\n\nDOORS=8                            - Number of Doors\nLOCATION.3=Doors:5D-Who/5D-Who     - Location of the Door\nSTACK.3=8192                       - Stack of the Door\nPRIORITY.4=3                       - Priority of the Door\nPASSWORD.2=BREULER                 - Password for the Door\n\n===========\n@endnode\n','\n',char(10)),NULL,'auto-added',45930,4,0,NULL,NULL,'sr_kcv10','scan',1780048740);
INSERT INTO door_catalog VALUES('sr_mes10','SR-MES10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SR-MES10.LHA','Messy','XIM','Messy',NULL,'Diogenes/Skid','SR','/ ____/ |   /_)____ \\_____ \/   \_ \/\/ _/ _\___ \    _/  |  |/  \|  _/ /  |  \ /  \ \ \______\_|  \__|______/|__|  \_____/__/\__/',replace('  ___________________ _______  ______    ___\n / ____/ |   /_)____ \\_____ \/   \_ \/\/ _/\n_\___ \    _/  |  |/  \|  _/ /  |  \ /  \ \\n\______\_|  \__|______/|__|  \_____/__/\__/\n+<=---Stz|___\--pRe$eN7$--|___\----------=>+\nMessy V1.0   by Diogenes/Skid Row    /X Util\nSmall but  great CLI  util  to use with Ami-\nExpress.  Intended to  create messages  from\ntextfiles.   Great  in  conjunction  with  a\nschedule  program  like   Cybercron  or  for\ndoors  which just create bulletins. 100% ASM\n','\n',char(10)),'Messy.Doc',replace('\n                 »» Messy V1.0 - /X 1/2/3/4.x CLI Utility ««\n\n                     ¡ CoDeD bY dIoGeNeS fOr SkId RoW ¡\n\n   .____________________________________________________________________.\n   |                                                                    |\n   | -> NeW nUmBeR ! <- nEw NuMbEr ! -> NeW nUmBeR ! <- nEw NuMbEr ! -> |\n   |                                                                    |\n   |    CaLl My BoArD nOw !  PeAcE cHaPeL bBs ->  +32-(0)2-331-38-09    |\n   |                                                                    |\n   | -> NeW nUmBeR ! <- nEw NuMbEr ! -> NeW nUmBeR ! <- nEw NuMbEr ! -> |\n   |____________________________________________________________________|\n   ''                                                                    `\n\n\nBeFoRe YoU gO oN...\n-*-*-*-*-*-*-*-*-*-\n\n This is NOT a door BUT this is a tool for /X though :)\n\n It''s XIM - Fast assembler :)\n\n You can reach me on these awesome boards for infos, contact, etc...:\n \n  Mirage          -  FLT WHQ   -  503-590-PRIVATE!\n\n  Unlawful Entry  -  SR  WHQ   -  612-755-PRIVATE!\n\n  Planet X        -  LSD USHQ  -  414-964-4977  -  3 Ndz Ringdown\n                     NUP: Lazardo\n                     My official ßeta-Tester ;)\n\n\nWhAt''S mEsSy ?\n-*-*-*-*-*-*-*\n\n >Messy< is basically a small CLI tool that will write public EALL or\nprivate messages from specified text files. It was intended to use with\nschedule programs OR doors which don''t create messages. If you want\na message to be written certain days/hours/minutes etc... I highly\nrecommend the use of Messy together with Cybercron schedule event program.\nIf you have a nice door which creates bulletins and you wish them as\npublic messages, you can use Messy as well. Just call it in your logoff\nscript or so.\n\n\nWaRnInG..\n*-*-*-*-*\n\n It sometimes happens that the first "character" in a textfile is a\nclearscreen ansi code. Messy will simply remove it from the new message\nin order to have the mail header displayed correctly at mail scanning.\n\n\nhOw To LaUnCh It ?\n*-*-*-*-*-*-*-*-*-\n\n Messy will need the following parameters in order to work:\n \n  * Path to target conference, with or without terminating "/".\n\n  * Path+Filename of the text file to be inserted in the message base.\n\n  * Source: name of the "user" who should have written the message.\n    Usually the sysop''s name :)\n\n  * Subject: you know what should be here ;)\n  \n  * Eventually a DESTINATION user. If specified, the message will be private.\n\n\n If you wish to use spaces in the source, destination and subject fields,\nthen use quotes ("string").\n\n\n Example:\n -------\n\n MESSY BBS:amigaworld bbs:amigaworld/msgbase/verenaris.bull\n   "Diogenes / Skid Row" "WEEKTOP RESULTS" John \n\n\nGrEeTiNgS\n-*-*-*-*-\n\n And as usual, here follow my very short & fast personal greetings :)\n\n In no fucking order ¡\n\n\n                           Big Boss/Fairlight\n                           John Yaya/LSD\n\n\n The others won''t even read this texfile ;-)\n','\n',char(10)),NULL,'auto-added',6100,2,0,NULL,NULL,'sr_mes10','scan',1780048740);
INSERT INTO door_catalog VALUES('sr_msfm','SR-MSFM.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SR-MSFM.LHA','8','XIM','8',NULL,'DIOGENES','SR','\// ___/ | _/ |___ \   / __/ ___/ |_| \\/ 9 _\__  \ _ \  |  |  \ /  |/  |  \ | | /   9 \_____/_| /__|_____/ \__|\_____/____/    5',replace(' __ _____/|___/|____     /\_________ |\ __ 1\n \// ___/ | _/ |___ \   / __/ ___/ |_| \\/ 9\n  _\__  \ _ \  |  |  \ /  |/  |  \ | | /   9\n  \_____/_| /__|_____/ \__|\_____/____/    5\n----------|/----------------------PRESENTS--\n MSFM File Backup Tagger For Express Server\n      Written by DIOGENES / SKID ROW !\n','\n',char(10)),'MSFM.Guide',replace('@database MSFM-DOC\n@Author DIOGENES / SKID ROW!\n@Index MAIN\n\nCopyright (c) 1994 DIOGENES / SKID ROW!\n\n@Remark $VER: (January 3 1995, 21:14:37)\n@Remark AmigaGuide database for the MSFM Documentation\n\n@node MAIN "MSFM Documentation (c)1994 DIOGENES of SKID ROW! (January 3 1995, 21:14:37)"\n                                          :              __\n                                          ¦             /\_\             .\n             .____________________________!___________/\\/_____________ _!_\n             |                           \|         __/\\/               |\n   __________l______ _____________________l         \_\/                 ¦\n _/    ________   ¬T/    /_____________   ¬\_                            ¦\n T______    ¬T     ¬    < |    ¬|    ¬T     T      >>> M.S.F.M. <<<      :\n |    ¬T     |     T     \|     |     |     |                            ·\n |___________¦_____|\     \_____¦___________¦ Code: DIOGENES / SKID ROW! |\n             ¦       \_____\              |                              |\n             |                            |                              ¦\n             |                      ______l________________        _____ ¦\n             :                      \______   ¬\         ¬|\      /    / :\n             `-----------------------T    _    /    |     | \    /    /--''\n                                     |    T    \_   |     |  \/\/    /\n                                     |____|     T_________¦         /\n                                          |_____¦      MpLx___/\___/\n\n\n         >>> C·O·N·T·E·N·T·S  O·F  D·O·C·U·M·E·N·T·A·T·I·O·N <<<\n\n                         @{"      Introduction      " Link Cap01}\n                         @{"      Requirements      " Link Cap02}\n                         @{"    Program  purpose    " Link Cap03}\n                         @{"     Using  M.S.F.M     " Link Cap04}\n                         @{"   Ascii Lists format   " Link Cap05}\n                         @{"    Technical Corner    " Link Cap06}\n                         @{"       The  author      " Link Cap07}\n                         @{"        Greetings       " Link Cap08}\n                         @{"         History        " Link Cap09}\n\n           Multi-Server File Manager V1.0 (c) Diogenes / Skid Row\n         ----------------------------------------------------------\n\n This program has been tested with Ami-Express ascii file listings but will\n be useful to most sysops because most BBS programs are basically using the\n same files listing system. If you are not using Ami-Express, you should\n immediately refer to the chapter concerning Ascii lists format in order to\n see if the program is able to handle your listings. If not, you can contact\n me to include your system in my list scanning algorithm. I will do it for\n free.\n\n         -----------------------------------------------------------\n                Complete Docs for M.S.F.M. V1.0 [-SKID ROW!-]\n         -----------------------------------------------------------\n         The Documentation has been written by DIOGENES / SKID ROW!.\n\n@endnode\n@node Cap01 "Introduction."\n  =======================================================================\n\n  M.S.F.M has been coded in a hurry to deserve my needs as soon as possible.\n  The main part was done in a week, and 3 more weeks were needed to test,\n  improve, add features, test again and again to finally have an acceptable\n  and releasable version 1.0, as other sysops have quickly showed much\n  interest in this program. At the same time, I had other obligations, and\n  most of the time, I had 30 mins / day to work on it.\n\n  Anyway, this should explain the poor user-friendliess. The screen size\n  is currently locked at 640*256 (PAL) or 640*200(NTSC), the gadgets are\n  not auto-sizing and the program is not font-sensitive. Feel free to make\n  suggestions but be sure I planned to make the user-interface more\n  configurable. This will be for the planned astonishing V2.0 ;)\n\n  =======================================================================\n@endnode\n@node Cap02 "Requirements."\n  =======================================================================\n\n  To install M.S.F.M. you must have the following things:\n\n    Program           Location                  Description\n    -------           --------                  -----------\n    MSFM              Anywhere                  Main program\n    reqtools.library  LIBS:                     Library by Nico François\n    P0T-NOoDLE.FONT   FONTS:                    Font by P0t-Noodle\n\n  - an  Amiga Model (500/600/1000/1200/2000/2500/3000/4000/CDTV/CD³²)\n  - the installed Version of OS\2, OS\3 or higher\n    (Soft- or Hardware Version)\n\n  =======================================================================\n@endnode\n@node Cap03 "Program purpose."\n  =======================================================================\n\n  For maintenance operations as for copies for friends, sysops have always\n  been obliged to simultaneously look at their file listing and flag the\n  files one by one in their file manager prior to selecting the appropriate\n  operation which is generally a copy/move, a deletion or a backup. This\n  way of doing is pretty slow. Other sysops rather prefer flagging by date\n  immediately. This method has proved to be quite unreliable as dates can be\n  changed during a crash recovery and files can be wrongly dated at\n  uploading if your clock suddenly became foolish.\n\n  There are though some few utilities, most often doors for Ami-Express and\n  Sigma-Express, which can be of some help in these operations. These\n  utilities are not numerous and are generally coded by beginners, unreliable\n  and slow.\n\n  Here comes M.S.F.M. :)  This first version is without any doubt *not*\n  astonishing, but is a revolution as well. M.S.F.M. performs the 3 main\n  operations which are "copy, move, delete" from an ascii file list, and at\n  lightning speed. The whole program is fully coded in highly optimised\n  assembly code and a special care has been taken in the main algorithms\n  development. M.S.F.M. will find himself the files, all you have to do is\n  click 2-3 times and then watch TV ;)\n\n  =======================================================================\n@endnode\n@node Cap04 "Using M.S.F.M."\n  =======================================================================\n\n  The first thing you have to do is loading an ascii file list in order to\n  be able to perform an operation on these files. When you are done, you can\n  copy these files somewhere else, move them somewhere else or just\n  delete them.\n\n  When you want to perform a copy or move operation, you are first asked\n  to select 1 or more source drawer(s) and then a target drawer. The source\n  drawers are drawers where the program could find your files. Numerous\n  source drawers are of course possible coz huge quantities of software have\n  to be stored on several devices. Just choose your directories one by\n  one and click "select". When you are done, click "cancel" and you are\n  asked to give a target drawer where the files should be copied/moved.\n  Clicking on the "cancel" gadget on the first source drawer requester or on\n  the target drawer requester will abort the operation.\n\n  When you want to perform a deletion, the only difference is that there is\n  no target drawer to select ;)\n\n  Trick: M.S.F.M. will try to find the files sequentially in your source\n         drawers. This physical operation takes time and it is therefore\n         advised to select as first drawers the biggest ones, or, in other\n         words, the drawers where your files will be more likely stored to\n         avoid unsuccessful locks as much as possible.\n\n  When there is not enough space anymore on the target device to go on with\n  the copy/move operation, the choice will be offered to skip the current\n  file, skip all the files which won''t fit, continue on another device or\n  simply abort the operation.\n\n  =======================================================================\n@endnode\n@node Cap05 "Ascii lists format."\n  =======================================================================\n\n  The main problem is to have a standard in ascii file lists. There is none,\n  but most are basically using the same system, which is very flexible.\n  Follow the few easy rules listed below and M.S.F.M. will work. If your\n  BBS program does not work this way, you can modify the list before calling\n  M.S.F.M. or ask me to include a routine for you. Ami-Express sysops\n  should not worry as well, M.S.F.M. was tested with Ami-Express files\n  listings.\n\n  If your files list contains NO valid filenames or some invalid filenames,\n  no action will be taken. You will be warned if a file was not found.\n\n\n   - A FileName may not exceed 12 characters;\n\n   - A FileName must begin at the first column and end:\n\n      * with a space\n      * with a carriage return\n\n\n     Example:\n\n\nGD1.0.LHA    N    39k  12-15-94  New Decruncher Program (decrunch +130 dec.)\n-------------------------------\n976-PIFX.TXT N    11k  12-16-94  \n                                 -----------------------------------------\n                                 \ CYBORG OF 976 EV!L GIVES YOU :        /\n                                 / HELP ON HOW TO FIX THE VIRUS INFECTED \\n                                 \ VERSION OF  PINBALL ILLUSIONS AGA     /\n                                 ----------------------------------------\n sqdfqdgqgqfg\nBC_LAMER.TXT\n\nSR-MSFM.LHA kdjfldsjgdqighqoihglqfghralhgq\nSR-MSFM.NFO       <- There must be a carriage return or space after "o"\n\n\n  Total: 5 files.\n\n  =======================================================================\n@endnode\n@node Cap06 "Technical corner."\n  =======================================================================\n\n  M.S.F.M. has been coded keeping in mind that it *had* to be fast.\n  Therefore, I have (as usual :) ) used the assembly language and highly\n  optimised routines. I spent alot of time in creating powerful algorithms\n  for the purpose, and especially on the copy/move algorithm which is\n  without any doubt the world''s fastest at this time. Its speed will always\n  depend on the amount of free memory (ever heard this somewhere hehe) but as\n  sysops do have huge amounts of memory, they should get astonishing\n  results.\n\n  M.S.F.M can perform a move operation (which takes the most time) on files\n  present on 5 different devices, listed in a 1.2Mb  ascii file list and\n  totalling +/- 200 megs in 11524 filenames in about 10 mins on a simple\n  68000. This is awesomely astonishing...\n\n  M.S.F.M. was developped on an A2000 Kick 2.04 68000 (but works fine with\n  Retina, Picasso and screen promoters).\n\n  M.S.F.M V2.0 is currently under development on my brand new A4000/040.\n  I own a Retina Z3 4Mb with a 17" monitor and a 14" monitor on the\n  standard Amiga output channel. Therefore, I am currently working on a fully\n  configurable program (everything sensitive) able to work in and use up to\n  16.7 millions colors (yes !), with a f***ing great design ;)\n\n  =======================================================================\n@endnode\n@node Cap07 "The Author."\n  =======================================================================\n\n  Handle:     Diogenes\n  Group:      Skid Row\n  Function:   Coder and sysop\n  BBS Name:   Peace Chapel\n  BBS Number: +32-(0)2-331-38-09\n\n  If you wish to get on touch with me for anything, just call the BBS if\n  you have a modem and can afford a call. To get into the server, type this\n  as name and password:\n\n  NAME:      DIO\n  PASSWORD:  DIO\n\n  =======================================================================\n@endnode\n@node Cap08 "Greetings go to..."\n  =======================================================================\n\n                        SHORT GREETS GO TO THESE SYSOPS:\n\n\n    Big Boss/Fairlight ..................... Hope to see ya back one day!\n    John Yaya/LSD .................................. Ma friend I miss ya!\n    Rhys / Delirium ................................. ''m also missing ya!\n    Tarzan ........................................ Long time ago, sorry!\n    Chucky ............................................ Still sysop ? ;-)\n    Sintax/WoT/OTL ..................... I definitively hate Belgacom ;-)\n    ULI ........................................... Ma own Beta-Tester ;)\n    Mousebuster / Prestige ........................ I prefer cats hehe ;)\n\n\n              >>> ALL SKID ROW MEMBERS!!! <<<\n\n\n  I wish to thank - ULI for having so nicely tested M.S.F.M.;\n                  - P0T-NOODLE for his nice font;\n                  - Nico François for his great Reqtools library\n                  - Mousebuster who owned the *only* Amiga MSFM did not\n                    work on !\n\n  I do not thank the other sysops who were supposedly testing it but never\n  reported me anything.\n\n  =======================================================================\n@endnode\n@node Cap09 "History."\n  =======================================================================\n\n V1.0:  First official release.\n\n  =======================================================================\n@endnode\n','\n',char(10)),NULL,'auto-added',60952,6,0,NULL,NULL,'sr_msfm','scan',1780048740);
INSERT INTO door_catalog VALUES('sr_qst10','SR-QST10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SR-QST10.LHA',NULL,'XIM','sr qst10',NULL,NULL,'SR',NULL,NULL,NULL,NULL,NULL,NULL,58676,0,0,NULL,NULL,NULL,'scan',1780048740);
INSERT INTO door_catalog VALUES('sr_ref12','SR-REF12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SR-REF12.LHA','Refer','XIM','Refer',NULL,'Diogenes/Skid','SR','/ _/_ __/  / \ \__ \__\  _   /\_\___\    / /\___ \ / _/\/ \/  \  \ \//__/ _/ \  /\ \/ /       \\  \/   \  /   \ /  \  \   \ ©ron\',replace('   ___     ____  ____   __________    ______\n  / _/_ __/  / \ \__ \__\  _   /\_\___\    /\n /\___ \ / _/\/ \/  \  \ \//__/ _/ \  /\ \/ \n/       \\  \/   \  /   \ /  \  \   \ ©ron\ \n\_______/_\  \___/______/_\   \_____/\/\  / \n+==========\__/=(pRESENTs)=\___/========\/=+\nRefer V1.2 by Diogenes/Skid Row  /X Util    \nAllows to refer users to the sysop on closed\nboards. Can now send EALL messages to get   \nusers advices ! Still the best Refer door :)\n100 % fast assembly.                        \n','\n',char(10)),'Refer.Doc',replace('\n       »» ReFeR V1.2 - /X 1/2/3.x CoMpAtIbLe - NeEdS AEDoor.Library ««\n\n                     ¡ CoDeD bY dIoGeNeS fOr SkId RoW ¡\n\n       CaLl My BoArD nOw !  PoIvRe BlAnC bBs ->  +32-(0)2-331-29-25\n\n\n\nBeFoRe YoU gO oN...\n-*-*-*-*-*-*-*-*-*-\n\n The doors needs:    AEDoor.Library in your LIBS:  (made by Sintax/WoT)\n                     Refer.info in Doors:Refer/\n                     ToolTypes explained below\n \n It''s XIM - Fast assembler :)\n\n\nWhAt''S rEfEr ?\n-*-*-*-*-*-*-*\n\n >Refer< is basically a door to refer users to the sysop on closed boards.\nThe user can give global informations about his friend, then the door\nwrites a messy to the sysop and the sysop can decide wether he will or\nnot open access for the user. The door can also send EALL messages, so the\nusers can tell the sysop wether the user is good or not.\n\n >Refer< is able to write a messy to any user specified in the config\nicon and not only to the sysop. This allow the sysop to have the point\nof vue of other users/co-sysops. That''s the only use as only the sysop\ncan create an access. If you specify EALL as name, then the door will\ncreate... EALL messages ;)   The contents are a bit different and this way\nyour users can tell you what they think about the refered user.\n\n\n''bOuT tHe ToOlTyPeS & iNsTaLlAtIoN\n*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-\n\n Make a directory REFER in your DOORS:  drawer (must be assigned) and copy\nthe door in it + its icon. Put in your BBS:Commands/BBSCmd drawer the door\nicon like for all doors. And again... if you don''t have the AEDoor.Library\nby Sintax/WoT installed, don''t expect the door to work !\n\n Sysops using /X v1.x -> 2.x will know better than me how to configurate\nthe whole thing. The only thing which changes is the door def. wich\ncorresponds to the icon located in Commands/BBSCmd (stack, type, location,\netc...)\n\nThe tooltypes are:\n\n SYSOP.x= ***             Users who will receive the message\n                          eg: Sysop.1=Diogenes\n                          Up to 4.294.967.295 "sysops" allowed hehe ;)\n                          \n                          If you type Sysop.x=EALL   the door will create\n                          a public EALL message instead with a different\n                          content. This way, your users can tell you what\n                          they think about the refered user.\n\n PATH= ***                *Very* important ! That''s the path to the\n                          conference where the mail must be sent.\n                          eg: Path=BBS:Amiga\n                          with or without terminating "/"\n \n EALL.x=***               That''s the conf path where the EALL messages must\n                          be sent. You can have several to advertise all\n                          traders: PC freaks, Amiga freaks, Console lovers\n                          etc...\n                          eg: EALL.1=BBS:AmigaWorld\n                              EALL.2=BBS:PC\n                          Etc...\n\n\nGrEeTiNgS\n-*-*-*-*-\n\n And as usual, here follow my fast personal greetings :)\n\n In no fucking order ¡\n\n                           Big Boss/Fairlight\n                           Malcar/Therapy\n                           John Yaya/LSD\n                           Sintax/WoT/TSL\n                           Stinger/Mystic\n                           Insider/Skid Row\n                           Mr. Hyde/Therapy\n                           Delirium & Kickface\n                           Dr.Pat/Chryseis\n                           Andi/Mst\n                           Vax6410/101 IO\n                           The SiLencer/TDS\n                           Chucky/Child''s Play\n                           Crocodile/GodSend\n                           Shock/Crystal\n                           Tarzan/Crystal\n\n\n I thinks that''s all :)  If I forgot your name or your group, don''t be\nangry ¡\n\n','\n',char(10)),NULL,'auto-added',8788,2,0,NULL,NULL,'sr_ref12','scan',1780048740);
INSERT INTO door_catalog VALUES('sr_ref13','SR-REF13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SR-REF13.LHA','Refer','XIM','Refer',NULL,'Diogenes/Skid','SR','/ ____/ |   /_)____ \\_____ \/   \_ \/\/ _/ _\___ \    _/  |  |/  \|  _/ /  |  \ /  \ \ \______\_|  \__|______/|__|  \_____/__/\__/',replace('  ___________________ _______  ______    ___\n / ____/ |   /_)____ \\_____ \/   \_ \/\/ _/\n_\___ \    _/  |  |/  \|  _/ /  |  \ /  \ \\n\______\_|  \__|______/|__|  \_____/__/\__/\n+<=---Stz|___\--pRe$eN7$--|___\----------=>+\nRefer V1.3   by Diogenes/Skid Row    /X Util\nAllows to refer users to the sysop on closed\nboards. Optimised  version,  100 % fast  ASM\n','\n',char(10)),'Refer.Doc',replace('\n\n     »» ReFeR V1.3 - /X 1/2/3/4.x CoMpAtIbLe - NeEdS AEDoor.Library ««\n\n                     ¡ CoDeD bY dIoGeNeS fOr SkId RoW ¡\n\n   .____________________________________________________________________.\n   |                                                                    |\n   | -> NeW nUmBeR ! <- nEw NuMbEr ! -> NeW nUmBeR ! <- nEw NuMbEr ! -> |\n   |                                                                    |\n   |    CaLl My BoArD nOw !  PeAcE cHaPeL bBs ->  +32-(0)2-331-38-09    |\n   |                                                                    |\n   | -> NeW nUmBeR ! <- nEw NuMbEr ! -> NeW nUmBeR ! <- nEw NuMbEr ! -> |\n   |____________________________________________________________________|\n   ''                                                                    `\n\n\nBeFoRe YoU gO oN...\n-*-*-*-*-*-*-*-*-*-\n\n The doors needs:    AEDoor.Library in your LIBS:  (made by Sintax/WoT)\n                     Refer.info in Doors:Refer/\n                     ToolTypes explained below\n \n It''s XIM - Fast assembler :)\n\n You can reach me on these awesome boards for infos, contact, etc...:\n \n  Mirage          -  FLT WHQ   -  503-590-PRIVATE!\n\n  Unlawful Entry  -  SR  WHQ   -  612-755-PRIVATE!\n\n  Planet X        -  LSD USHQ  -  414-964-4977  -  3 Ndz Ringdown\n                     NUP: Lazardo\n                     My official ßeta-Tester ;)\n\n\nWhAt''S rEfEr ?\n-*-*-*-*-*-*-*\n\n >Refer< is basically a door to refer users to the sysop on closed boards.\nThe user can give global informations about his friend, then the door\nwrites a messy to the sysop and the sysop can decide wether he will or\nnot open access for the user. The door can also send EALL messages, so the\nusers can tell the sysop wether the user is good or not.\n\n >Refer< is able to write a messy to any user specified in the config\nicon and not only to the sysop. This allow the sysop to have the point\nof vue of other users/co-sysops. That''s the only use as only the sysop\ncan create an access. If you specify EALL as name, then the door will\ncreate... EALL messages ;)   The contents are a bit different and this way\nyour users can tell you what they think about the refered user.\n\n\n''bOuT tHe ToOlTyPeS & iNsTaLlAtIoN\n*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-\n\n Make a directory REFER in your DOORS:  drawer (must be assigned) and copy\nthe door in it + its icon. Put in your BBS:Commands/BBSCmd drawer the door\nicon like for all doors. And again... if you don''t have the AEDoor.Library\nby Sintax/WoT installed, don''t expect the door to work !\n\n Sysops using /X v1.x -> 2.x will know better than me how to configurate\nthe whole thing. The only thing which changes is the door def. wich\ncorresponds to the icon located in Commands/BBSCmd (stack, type, location,\netc...)\n\nThe tooltypes are:\n\n SYSOP.x= ***             Users who will receive the message\n                          eg: Sysop.1=Diogenes\n                          Up to 4.294.967.295 "sysops" allowed hehe ;)\n                          \n                          If you type Sysop.x=EALL   the door will create\n                          a public an EALL message instead with a different\n                          content. This way, your users can tell you what\n                          they think about the refered user.\n\n PATH= ***                *Very* important ! That''s the path to the\n                          conference where the mail must be sent.\n                          eg: Path=BBS:Amiga\n                          with or without terminating "/"\n \n EALL.x=***               That''s the conf path where the EALL messages must\n                          be sent. You can have several to advertise all\n                          traders: PC freaks, Amiga freaks, Console lovers\n                          etc...\n                          eg: EALL.1=BBS:AmigaWorld\n                              EALL.2=BBS:PC\n                          Etc...\n\n\nGrEeTiNgS\n-*-*-*-*-\n\n And as usual, here follow my very short & fast personal greetings :)\n\n In no fucking order ¡\n\n\n                           Big Boss/Fairlight\n                           John Yaya/LSD\n\n\n The others won''t even read this texfile ;-)\n','\n',char(10)),NULL,'auto-added',35738,3,0,NULL,NULL,'sr_ref12','scan',1780048740);
INSERT INTO door_catalog VALUES('sr_rst10','SR-RST10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SR-RST10.LHA','Restrict','XIM','Restrict',NULL,'Diogenes/Skid','SR','/ _/_ __/  / \ \__ \__\  _   /\_\___\    / /\___ \ / _/\/ \/  \  \ \//__/ _/ \  /\ \/ /       \\  \/   \  /   \ /  \  \   \ ©ron\',replace('   ___     ____  ____   __________    ______\n  / _/_ __/  / \ \__ \__\  _   /\_\___\    /\n /\___ \ / _/\/ \/  \  \ \//__/ _/ \  /\ \/ \n/       \\  \/   \  /   \ /  \  \   \ ©ron\ \n\_______/_\  \___/______/_\   \_____/\/\  / \n+==========\__/=(pRESENTs)=\___/========\/=+\nRestrict V1.0 by Diogenes/Skid Row  /X Util \nAllows to kick users ! can be used to drop  \na carrier on the sysop on modem nodes,      \nrestrict some users at certain hourz only   \n(leechers). Great to prevent hacking &      \nleeching. ASM power ! Fully configurable... \n','\n',char(10)),'Restrict.Doc',replace('\n     »» Restrict V1.0 - /X 1/2/3.x CoMpAtIbLe - NeEdS AEDoor.Library ««\n\n                     ¡ CoDeD bY dIoGeNeS fOr SkId RoW ¡\n\n       CaLl My BoArD nOw !  PoIvRe BlAnC bBs ->  +32-(0)2-331-29-25\n\n\n\nBeFoRe YoU gO oN...\n-*-*-*-*-*-*-*-*-*-\n\n The doors needs:    AEDoor.Library in your LIBS:  (made by Sintax/WoT)\n                     Restrict.info in Doors:Restrict/\n                     ToolTypes explained below\n \n It''s XIM - Fast assembler :)\n\n\nWhAt''S rEsTrIct ?\n-*-*-*-*-*-*-*-*-\n\n >Refer< is basically a door to kick users from the board by dropping\na carrier. It can be *very* useful under certain circumstances :-)\nYou can for example prevent sysop logins on modem nodes and prevent\nhacking with your handle, you can restrict some users to call only at\ncertain hourz, select the user you wish but also kick everybody with\n"*" as name. Useful when you decide to close the board for a while. You just\nuse the door and nobody is allowed to call, except your friends if\nyou wish.\n\n\n''bOuT tHe ToOlTyPeS & iNsTaLlAtIoN\n*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-\n\n Make a directory RESTRICT in your DOORS:  drawer (must be assigned) and copy\nthe door in it + its icon. Put in your BBS:Commands/BBSCmd drawer the door\nicon like for all doors. And again... if you don''t have the AEDoor.Library\nby Sintax/WoT installed, don''t expect the door to work !\n\n Sysops using /X v1.x -> 2.x will know better than me how to configurate\nthe whole thing. The only thing which changes is the door def. wich\ncorresponds to the icon located in Commands/BBSCmd (stack, type, location,\netc...)\n\nThe tooltypes are:\n\n NAME.x= ***             Users to be kicked\n                          eg: Name.1=Diogenes\n \n PASSWORD.x= ***         This will cause the door to ask the user for\n                         a password. In case of password failure, the door\n                         will start the drop carrier procedure. Else the\n                         user will be allowed to log in. This can be used\n                         for the sysop to have a second password check,\n                         so he still can call his board from elsewhere.\n\n TEXT.x= ***             Here you type the string to send to the user\n                         before kicking him\n                                               OR\n                         a PATH to a text file. If TEXT.x doesn''t exist,\n                         the default string will be "ACCESS DENIED".\n \n FLAG.x= Path/Line       If you chose a path to a text file for TEXT.x,\n                         state here PATH. If not, TEXT.x will be considered\n                         as a simple string.\n \n TIME.x= 0000,2359       States the interval of time when the user MAY\n                         call. Outside, he will be kicked.\n                         It MUST be 4 digits long. A coma is needed between\n                         both hourz. The first is the earliest time allowed\n                         and the other the latest.\n                         eg: 1000,1700 means that the user may call between\n                             10.00 am and 05.00 pm (or 17.00).\n                         \n                         Only this format is allowed. And of course,\n                         above 2359 is forbidden too.\n                         \n                         0000 stands for midnight, beginning of the day.\n                         2359 is the end of the day.\n                         \n                         This is useful to prevent real leechers from\n                         calling when uploaders try to come.\n\n\n The little "x" stands for a number from 1 to 4.294.967.295. Enough ? ;-)\n\n Examples:\n --------\n \n 1] Name.1=Diogenes            Only Diogenes is kicked. Default string is\n                               used (ACCESS DENIED)\n \n 2] Name.1=Diogenes\n    Time.1=0000,2359\n    Name.2=*                   Diogenes may call all the day. All the other\n                               users will be kicked.\n                               Yeh, you can also specify users NOT to be\n                               kicked this way ;-)\n\n 3] Name.1=Diogenes            Sysop Diogenes can log in IF he knows the\n    Password.1=Zoup            password.\n\n 4] Name.1=Diogenes\n    Text.1=BBS:Screens/Node1/Bye.Txt\n    Flag.1=Path\n    Name.2=Bip\n    Text.2=Bye bye !           Guess what ;-)\n    \n \n For those who wonder how to call the door, here''s where I call it:\n BULLxx.TXT in my BBS:Screens/Nodex drawer.  The BULL.TXT of the local\n node shouldn''t call the door as one of the main purposes is to prevent\n sysop logins and leechers from calling at the busiest hourz. The sysop must\n still be able to enter his local node ;-)\n \n\n\nGrEeTiNgS\n-*-*-*-*-\n\n And as usual, here follow my fast personal greetings :)\n\n In no fucking order ¡\n\n                           Big Boss/Fairlight\n                           Malcar/Therapy\n                           John Yaya/LSD\n                           Sintax/WoT/TSL\n                           Stinger/Mystic\n                           Insider/Skid Row\n                           Mr. Hyde/Therapy\n                           Delirium & Kickface\n                           Dr.Pat/Chryseis\n                           Andi/Mst\n                           Vax6410/101 IO\n                           The SiLencer/TDS\n                           Chucky/Child''s Play\n                           Crocodile/GodSend\n                           Shock/Crystal\n                           Tarzan/Crystal\n\n\n I thinks that''s all :)  If I forgot your name or your group, don''t be\nangry ¡\n\n','\n',char(10)),NULL,'auto-added',10608,8,0,NULL,NULL,'sr_rst10','scan',1780048740);
INSERT INTO door_catalog VALUES('sr_rst11','SR-RST11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SR-RST11.LHA','Restrict','XIM','Restrict',NULL,'Diogenes/Skid','SR','/ ____/ |   /_)____ \\_____ \/   \_ \/\/ _/ _\___ \    _/  |  |/  \|  _/ /  |  \ /  \ \ \______\_|  \__|______/|__|  \_____/__/\__/',replace('  ___________________ _______  ______    ___\n / ____/ |   /_)____ \\_____ \/   \_ \/\/ _/\n_\___ \    _/  |  |/  \|  _/ /  |  \ /  \ \\n\______\_|  \__|______/|__|  \_____/__/\__/\n+<=---Stz|___\--pRe$eN7$--|___\----------=>+\nRestrict V1.1  by Diogenes/Skid Row  /X Util\nAllows  to  kick  target  users !  Great  to\nprevent  hacking  &  leeching. !!  Now  with\naccess level  implemented to  kick new users\netc...  Kick sysop  on modem nodes, restrict\nleechers at certain hourz, etc.. 200% ASM :)\n','\n',char(10)),'Restrict.Doc',replace('\n     »» Restrict V1.0 - /X 1/2/3.x CoMpAtIbLe - NeEdS AEDoor.Library ««\n\n                     ¡ CoDeD bY dIoGeNeS fOr SkId RoW ¡\n\n       CaLl My BoArD nOw !  PoIvRe BlAnC bBs ->  +32-(0)2-331-29-25\n\n\n\nBeFoRe YoU gO oN...\n-*-*-*-*-*-*-*-*-*-\n\n The doors needs:    AEDoor.Library in your LIBS:  (made by Sintax/WoT)\n                     Restrict.info in Doors:Restrict/\n                     ToolTypes explained below\n \n It''s XIM - Fast assembler :)\n\n\nWhAt''S rEsTrIct ?\n-*-*-*-*-*-*-*-*-\n\n >Refer< is basically a door to kick users from the board by dropping\na carrier. It can be *very* useful under certain circumstances :-)\nYou can for example prevent sysop logins on modem nodes and prevent\nhacking with your handle, you can restrict some users to call only at\ncertain hourz, select the user you wish but also kick everybody with\n"*" as name. Useful when you decide to close the board for a while. You just\nuse the door and nobody is allowed to call, except your friends if\nyou wish.\n\n\n''bOuT tHe ToOlTyPeS & iNsTaLlAtIoN\n*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-\n\n Make a directory RESTRICT in your DOORS:  drawer (must be assigned) and copy\nthe door in it + its icon. Put in your BBS:Commands/BBSCmd drawer the door\nicon like for all doors. And again... if you don''t have the AEDoor.Library\nby Sintax/WoT installed, don''t expect the door to work !\n\n Sysops using /X v1.x -> 2.x will know better than me how to configurate\nthe whole thing. The only thing which changes is the door def. wich\ncorresponds to the icon located in Commands/BBSCmd (stack, type, location,\netc...)\n\nThe tooltypes are:\n\n NAME.x= ***             Users to be kicked\n                          eg: Name.1=Diogenes\n \n PASSWORD.x= ***         This will cause the door to ask the user for\n                         a password. In case of password failure, the door\n                         will start the drop carrier procedure. Else the\n                         user will be allowed to log in. This can be used\n                         for the sysop to have a second password check,\n                         so he still can call his board from elsewhere.\n\n TEXT.x= ***             Here you type the string to send to the user\n                         before kicking him\n                                               OR\n                         a PATH to a text file. If TEXT.x doesn''t exist,\n                         the default string will be "ACCESS DENIED".\n \n FLAG.x= Path/Line       If you chose a path to a text file for TEXT.x,\n                         state here PATH. If not, TEXT.x will be considered\n                         as a simple string.\n \n TIME.x= 0000,2359       States the interval of time when the user MAY\n                         call. Outside, he will be kicked.\n                         It MUST be 4 digits long. A coma is needed between\n                         both hourz. The first is the earliest time allowed\n                         and the other the latest.\n                         eg: 1000,1700 means that the user may call between\n                             10.00 am and 05.00 pm (or 17.00).\n                         \n                         Only this format is allowed. And of course,\n                         above 2359 is forbidden too.\n                         \n                         0000 stands for midnight, beginning of the day.\n                         2359 is the end of the day.\n                         \n                         This is useful to prevent real leechers from\n                         calling when uploaders try to come.\n\n\n The little "x" stands for a number from 1 to 4.294.967.295. Enough ? ;-)\n\n Examples:\n --------\n \n 1] Name.1=Diogenes            Only Diogenes is kicked. Default string is\n                               used (ACCESS DENIED)\n \n 2] Name.1=Diogenes\n    Time.1=0000,2359\n    Name.2=*                   Diogenes may call all the day. All the other\n                               users will be kicked.\n                               Yeh, you can also specify users NOT to be\n                               kicked this way ;-)\n\n 3] Name.1=Diogenes            Sysop Diogenes can log in IF he knows the\n    Password.1=Zoup            password.\n\n 4] Name.1=Diogenes\n    Text.1=BBS:Screens/Node1/Bye.Txt\n    Flag.1=Path\n    Name.2=Bip\n    Text.2=Bye bye !           Guess what ;-)\n    \n \n For those who wonder how to call the door, here''s where I call it:\n BULLxx.TXT in my BBS:Screens/Nodex drawer.  The BULL.TXT of the local\n node shouldn''t call the door as one of the main purposes is to prevent\n sysop logins and leechers from calling at the busiest hourz. The sysop must\n still be able to enter his local node ;-)\n \n\n\nGrEeTiNgS\n-*-*-*-*-\n\n And as usual, here follow my fast personal greetings :)\n\n In no fucking order ¡\n\n                           Big Boss/Fairlight\n                           Malcar/Therapy\n                           John Yaya/LSD\n                           Sintax/WoT/TSL\n                           Stinger/Mystic\n                           Insider/Skid Row\n                           Mr. Hyde/Therapy\n                           Delirium & Kickface\n                           Dr.Pat/Chryseis\n                           Andi/Mst\n                           Vax6410/101 IO\n                           The SiLencer/TDS\n                           Chucky/Child''s Play\n                           Crocodile/GodSend\n                           Shock/Crystal\n                           Tarzan/Crystal\n\n\n I thinks that''s all :)  If I forgot your name or your group, don''t be\nangry ¡\n\n','\n',char(10)),NULL,'auto-added',15341,2,0,NULL,NULL,'sr_rst10','scan',1780048740);
INSERT INTO door_catalog VALUES('sr_sfm','SR-SFM.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SR-SFM.LHA','8','XIM','8',NULL,NULL,'SR','/  ____ ¬| _____)___ ¬|  \___ ____. ¬|¬|¬| ) \___ ¬\  _  /  ¬\  /  |  /  _  / ¬|  | | | \ /_____/__|  \_  /___  |  \__|  \___  l_____/',replace(' ________.____/\______.  ________/|__._._._\n/  ____ ¬| _____)___ ¬|  \___ ____. ¬|¬|¬| )\n\___ ¬\  _  /  ¬\  /  |  /  _  / ¬|  | | | \\n/_____/__|  \_  /___  |  \__|  \___  l_____/\n        ¬`---''\/tGø`--''    ¬`---'' `--''\nDIOGENES STRIKES AGAIN WITH M.S.F.M V1.01\nBEST AND ONLY ONE FILE MANAGER FOR SYSOPS\nWORKS ON ASCII FILE LISTS - SEVERAL BBS\nSYSTEMS SUPPORTED - FASTEST COPY ALGORITHM\nEVER CODED INCLUDED IN THIS MASTERPIECE ! ;)\nCOPY/MOVE/DELETE GIGS OF STUFF IN 5 MINS !\n ·A·T· *22/05/96*  ·L·A·N· 12:04 ·T·|·C· \n','\n',char(10)),'MSFM.Guide',replace('@database MSFM-DOC\n@Author DIOGENES / SKID ROW!\n@Index MAIN\n\nCopyright (c) 1994-1996 DIOGENES / SKID ROW!\n\n@Remark $VER: (January 3 1995/May 19 1996, 21:14:37)\n@Remark AmigaGuide database for the MSFM Documentation\n\n@node MAIN "MSFM Documentation (c)1994-1996 DIOGENES of SKID ROW! (January 3 1995/May 19 1996, 21:14:37)"\n                                          :              __\n                                          ¦             /\_\             .\n             .____________________________!___________/\\/_____________ _!_\n             |                           \|         __/\\/               |\n   __________l______ _____________________l         \_\/                 ¦\n _/    ________   ¬T/    /_____________   ¬\_                            ¦\n T______    ¬T     ¬    < |    ¬|    ¬T     T      >>> M.S.F.M. <<<      :\n |    ¬T     |     T     \|     |     |     |                            ·\n |___________¦_____|\     \_____¦___________¦ Code: DIOGENES / SKID ROW! |\n             ¦       \_____\              |                              |\n             |                            |                              ¦\n             |                      ______l________________        _____ ¦\n             :                      \______   ¬\         ¬|\      /    / :\n             `-----------------------T    _    /    |     | \    /    /--''\n                                     |    T    \_   |     |  \/\/    /\n                                     |____|     T_________¦         /\n                                          |_____¦      MpLx___/\___/\n\n\n         >>> C·O·N·T·E·N·T·S  O·F  D·O·C·U·M·E·N·T·A·T·I·O·N <<<\n\n                         @{"      Introduction      " Link Cap01}\n                         @{"      Requirements      " Link Cap02}\n                         @{"    Program  purpose    " Link Cap03}\n                         @{"     Using  M.S.F.M     " Link Cap04}\n                         @{"   Ascii Lists format   " Link Cap05}\n                         @{"    Technical Corner    " Link Cap06}\n                         @{"       The  author      " Link Cap07}\n                         @{"        Greetings       " Link Cap08}\n                         @{"         History        " Link Cap09}\n\n           Multi-Server File Manager V1.01 (c) Diogenes / Skid Row\n         -----------------------------------------------------------\n\n This program has been tested with Ami/Sigma-Express/DayDream ascii file\n listings but will be useful to most sysops because most BBS programs are\n basically using the same files listing system. If you are not using one\n of these 3 programs, you should immediately refer to the chapter concerning\n Ascii lists format in order to see if the program is able to handle your\n listings. If not, you can contact me to include your system in my list\n scanning algorithm. I will do it for free.\n\n A converter has been made for the /T\empest binary catalogs\n\n         -----------------------------------------------------------\n                Complete Docs for M.S.F.M. V1.0 [-SKID ROW!-]\n         -----------------------------------------------------------\n         The Documentation has been written by DIOGENES / SKID ROW!.\n\n@endnode\n@node Cap01 "Introduction."\n  =======================================================================\n\n  M.S.F.M has been coded in a hurry in January 1994 to deserve my needs as\n  soon as possible. The main part was done in a week, and 3 more weeks were\n  needed to test, improve, add features, test again and again to finally\n  have an acceptable and releasable version 1.0, as other sysops have\n  quickly showed much interest in this program. At the same time, I had\n  other obligations, and most of the time, I had 30 mins / day to work on\n  it.\n\n  Anyway, this should explain the poor user-friendliess. The screen size\n  is currently locked at 640*256 (PAL) or 640*200(NTSC), the gadgets are\n  not auto-sizing and the program is not font-sensitive. I planned an\n  "astonishing" V2.0 which I never finished...  One day will see this\n  release I guess ;)\n\n  Today, the 19th of May 1996, I changed the program a bit to allow filename\n  lenghts up to 31 chars. This is the only change since 1994. A converter\n  is also supplied for the /T\empest V3.40+ binary catalogs because I\n  switched to this great BBS program since then.\n\n  =======================================================================\n@endnode\n@node Cap02 "Requirements."\n  =======================================================================\n\n  To install M.S.F.M. you must have the following things:\n\n    Program           Location                  Description\n    -------           --------                  -----------\n    MSFM              Anywhere                  Main program\n    reqtools.library  LIBS:                     Library by Nico François\n    P0T-NOoDLE.FONT   FONTS:                    Font by P0t-Noodle\n\n  - an  Amiga Model\n  - the installed Version of OS\2, OS\3 or higher\n    (Soft- or Hardware Version)\n\n  =======================================================================\n@endnode\n@node Cap03 "Program purpose."\n  =======================================================================\n\n  For maintenance operations as for copies for friends, sysops have always\n  been obliged to simultaneously look at their file listing and flag the\n  files one by one in their file manager prior to selecting the appropriate\n  operation which is generally a copy/move, a deletion or a backup. This\n  way of doing is pretty slow. Other sysops rather prefer flagging by date\n  immediately. This method has proved to be quite unreliable as dates can be\n  changed during a crash recovery and files can be wrongly dated at\n  uploading if your clock suddenly became foolish.\n\n  There are though some few utilities, most often doors, which can be of some\n  help in these operations. These utilities are not numerous and are generally\n  coded by beginners.. Most often unreliable and slow.\n\n  Here comes M.S.F.M. :)  This first version is without any doubt *not*\n  astonishing, but is a revolution as well. M.S.F.M. performs the 3 main\n  operations which are "copy, move, delete" from an ascii file list, and at\n  lightning speed. The whole program is fully coded in highly optimised\n  assembly code and a special care has been taken in the main algorithms\n  development. M.S.F.M. will find himself the files, all you have to do is\n  click 2-3 times and then watch TV ;)\n\n  =======================================================================\n@endnode\n@node Cap04 "Using M.S.F.M."\n  =======================================================================\n\n  The first thing you have to do is loading an ascii file list in order to\n  be able to perform an operation on these files. When you are done, you can\n  copy these files somewhere else, move them somewhere else or just\n  delete them.\n\n  When you want to perform a copy or move operation, you are first asked\n  to select 1 or more source drawer(s) and then a target drawer. The source\n  drawers are drawers where the program could find your files. Numerous\n  source drawers are of course possible coz huge quantities of software have\n  to be stored on several devices. Just choose your directories one by\n  one and click "select". When you are done, click "cancel" and you are\n  asked to give a target drawer where the files should be copied/moved.\n  Clicking on the "cancel" gadget on the first source drawer requester or on\n  the target drawer requester will abort the operation.\n\n  When you want to perform a deletion, the only difference is that there is\n  no target drawer to select ;)\n\n  Trick: M.S.F.M. will try to find the files sequentially in your source\n         drawers. This physical operation takes time and it is therefore\n         advised to select as first drawers the biggest ones, or, in other\n         words, the drawers where your files will be more likely stored to\n         avoid unsuccessful locks as much as possible.\n\n  When there is not enough space anymore on the target device to go on with\n  the copy/move operation, the choice will be offered to skip the current\n  file, skip all the files which won''t fit, continue on another device or\n  simply abort the operation.\n\n  =======================================================================\n@endnode\n@node Cap05 "Ascii lists format."\n  =======================================================================\n\n  The main problem is to have a standard in ascii file lists. There is none,\n  but most are basically using the same system, which is very flexible.\n  Follow the few easy rules listed below and M.S.F.M. will work. If your\n  BBS program does not work this way, you can modify the list before calling\n  M.S.F.M. or ask me to include a routine for you. Ami/Sigma-Express/DayDream\n  sysops should not worry as well, M.S.F.M. was tested with such files\n  listings. /T\empest sysops will find enclosed in this archive a converter\n  to convert the .IDX binary file in an ascii file list.\n\n  If your files list contains NO valid filenames or some invalid filenames,\n  no action will be taken. You will be warned if a file was not found.\n\n\n   - A FileName may not exceed 31 characters;\n\n   - A FileName must begin at the first column and end:\n\n      * with a space\n      * with a carriage return\n\n\n     Example:\n\n\nGD1.0.LHA    N    39k  12-15-94  New Decruncher Program (decrunch +130 dec.)\n-------------------------------\n976-PIFX.TXT N    11k  12-16-94  \n                                 -----------------------------------------\n                                 \ CYBORG OF 976 EV!L GIVES YOU :        /\n                                 / HELP ON HOW TO FIX THE VIRUS INFECTED \\n                                 \ VERSION OF  PINBALL ILLUSIONS AGA     /\n                                 ----------------------------------------\n sqdfqdgqgqfg\nBC_LAMER.TXT\n\nSR-MSFM.LHA kdjfldsjgdqighqoihglqfghralhgq\nSR-MSFM.NFO       <- There must be a carriage return or space after "o"\n\n\n  Total: 5 files.\n\n  =======================================================================\n@endnode\n@node Cap06 "Technical corner."\n  =======================================================================\n\n  M.S.F.M. has been coded keeping in mind that it *had* to be fast.\n  Therefore, I have (as usual :) ) used the assembly language and highly\n  optimised routines. I spent alot of time in creating powerful algorithms\n  for the purpose, and especially on the copy/move algorithm which is\n  without any doubt the world''s fastest at this time. Its speed will always\n  depend on the amount of free memory (ever heard this somewhere hehe) but as\n  sysops do have huge amounts of memory, they should get astonishing\n  results. And anyway, the program itself helps sparing alot of time !\n\n  M.S.F.M can perform a move operation (which takes the most time) on files\n  present on 5 different devices, listed in a 1.2Mb  ascii file list and\n  totalling +/- 200 megs in 11524 filenames in about 10 mins on a simple\n  68000. This is awesomely astonishing...\n   |\n   `--> Old & obsolete test in our Mhz world today ;)\n\n  I began a real nice user-friendly V2.0 some months ago.. who knows, I will\n  maybe finish it one day :)\n\n  =======================================================================\n@endnode\n@node Cap07 "The Author."\n  =======================================================================\n\n  Handle:     Diogenes\n  Group:      Skid Row\n  Function:   Coder and sysop\n  BBS Name:   Peace Chapel\n  BBS Number: +32-(0)2-331-38-09\n  NUP:        BUZZHEAD\n\n  If you wish to get on touch with me for anything, just call the BBS if\n  you have a modem and can afford a call. Say that you come for MSFM,\n  or you won''t get access.\n\n  =======================================================================\n@endnode\n@node Cap08 "Greetings go to..."\n  =======================================================================\n\n                        SHORT GREETS GO TO THESE SYSOPS:\n\n\n    Big Boss/Fairlight ..................... Hope to see ya back one day!\n    John Yaya/LSD .................................. Ma friend I miss ya!\n    Rhys / Delirium ................................. ''m also missing ya!\n    Tarzan ........................................ Long time ago, sorry!\n    Chucky ............................................ Still sysop ? ;-)\n    Sintax/WoT/OTL ..................... I definitively hate Belgacom ;-)\n    ULI ........................................... Ma own Beta-Tester ;)\n    Mousebuster / Prestige ........................ I prefer cats hehe ;)\n\n And all the others since 1994 ;)\n\n\n              >>> ALL SKID ROW MEMBERS!!! <<<\n\n\n  I wish to thank - ULI for having so nicely tested M.S.F.M.;\n                  - P0T-NOODLE for his nice font;\n                  - Nico François for his great Reqtools library\n                  - Mousebuster who owned the *only* Amiga MSFM did not\n                    work on !\n\n  I do not thank the other sysops who were supposedly testing it but never\n  reported me anything.\n\n  =======================================================================\n@endnode\n@node Cap09 "History."\n  =======================================================================\n\n V1.00:  First official release on January 3th 1995.\n\n V1.01:  MSFM can now handle 31 chars filenames. See chapter about ascii\n         file lists for more. Released on May 19th 1996.\n\n         Thanks to WREC for suggesting.\n\n  =======================================================================\n@endnode\n','\n',char(10)),NULL,'auto-added',61374,3,0,NULL,NULL,'sr_sfm','scan',1780048740);
INSERT INTO door_catalog VALUES('sr_sfm10','SR-SFM10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SR-SFM10.LHA','8','XIM','8',NULL,NULL,'SR','/  ____ ¬| _____)___ ¬|  \___ ____. ¬|¬|¬| ) \___ ¬\  _  /  ¬\  /  |  /  _  / ¬|  | | | \ /_____/__|  \_  /___  |  \__|  \___  l_____/',replace(' ________.____/\______.  ________/|__._._._\n/  ____ ¬| _____)___ ¬|  \___ ____. ¬|¬|¬| )\n\___ ¬\  _  /  ¬\  /  |  /  _  / ¬|  | | | \\n/_____/__|  \_  /___  |  \__|  \___  l_____/\n        ¬`---''\/tGø`--''    ¬`---'' `--''\nDIOGENES STRIKES AGAIN WITH M.S.F.M V1.0\nBEST AND ONLY ONE FILE MANAGER FOR SYSOPS\nWORKS ON ASCII FILE LISTS - SEVERAL BBS\nSYSTEMS SUPPORTED - FASTEST COPY ALGORITHM\nEVER CODED INCLUDED IN THIS MASTERPIECE ! ;)\nCOPY/MOVE/DELETE GIGS OF STUFF IN 5 MINS !\n','\n',char(10)),'MSFM.Guide',replace('@database MSFM-DOC\n@Author DIOGENES / SKID ROW!\n@Index MAIN\n\nCopyright (c) 1994 DIOGENES / SKID ROW!\n\n@Remark $VER: (January 3 1995, 21:14:37)\n@Remark AmigaGuide database for the MSFM Documentation\n\n@node MAIN "MSFM Documentation (c)1994 DIOGENES of SKID ROW! (January 3 1995, 21:14:37)"\n                                          :              __\n                                          ¦             /\_\             .\n             .____________________________!___________/\\/_____________ _!_\n             |                           \|         __/\\/               |\n   __________l______ _____________________l         \_\/                 ¦\n _/    ________   ¬T/    /_____________   ¬\_                            ¦\n T______    ¬T     ¬    < |    ¬|    ¬T     T      >>> M.S.F.M. <<<      :\n |    ¬T     |     T     \|     |     |     |                            ·\n |___________¦_____|\     \_____¦___________¦ Code: DIOGENES / SKID ROW! |\n             ¦       \_____\              |                              |\n             |                            |                              ¦\n             |                      ______l________________        _____ ¦\n             :                      \______   ¬\         ¬|\      /    / :\n             `-----------------------T    _    /    |     | \    /    /--''\n                                     |    T    \_   |     |  \/\/    /\n                                     |____|     T_________¦         /\n                                          |_____¦      MpLx___/\___/\n\n\n         >>> C·O·N·T·E·N·T·S  O·F  D·O·C·U·M·E·N·T·A·T·I·O·N <<<\n\n                         @{"      Introduction      " Link Cap01}\n                         @{"      Requirements      " Link Cap02}\n                         @{"    Program  purpose    " Link Cap03}\n                         @{"     Using  M.S.F.M     " Link Cap04}\n                         @{"   Ascii Lists format   " Link Cap05}\n                         @{"    Technical Corner    " Link Cap06}\n                         @{"       The  author      " Link Cap07}\n                         @{"        Greetings       " Link Cap08}\n                         @{"         History        " Link Cap09}\n\n           Multi-Server File Manager V1.0 (c) Diogenes / Skid Row\n         ----------------------------------------------------------\n\n This program has been tested with Ami-Express ascii file listings but will\n be useful to most sysops because most BBS programs are basically using the\n same files listing system. If you are not using Ami-Express, you should\n immediately refer to the chapter concerning Ascii lists format in order to\n see if the program is able to handle your listings. If not, you can contact\n me to include your system in my list scanning algorithm. I will do it for\n free.\n\n         -----------------------------------------------------------\n                Complete Docs for M.S.F.M. V1.0 [-SKID ROW!-]\n         -----------------------------------------------------------\n         The Documentation has been written by DIOGENES / SKID ROW!.\n\n@endnode\n@node Cap01 "Introduction."\n  =======================================================================\n\n  M.S.F.M has been coded in a hurry to deserve my needs as soon as possible.\n  The main part was done in a week, and 3 more weeks were needed to test,\n  improve, add features, test again and again to finally have an acceptable\n  and releasable version 1.0, as other sysops have quickly showed much\n  interest in this program. At the same time, I had other obligations, and\n  most of the time, I had 30 mins / day to work on it.\n\n  Anyway, this should explain the poor user-friendliess. The screen size\n  is currently locked at 640*256 (PAL) or 640*200(NTSC), the gadgets are\n  not auto-sizing and the program is not font-sensitive. Feel free to make\n  suggestions but be sure I planned to make the user-interface more\n  configurable. This will be for the planned astonishing V2.0 ;)\n\n  =======================================================================\n@endnode\n@node Cap02 "Requirements."\n  =======================================================================\n\n  To install M.S.F.M. you must have the following things:\n\n    Program           Location                  Description\n    -------           --------                  -----------\n    MSFM              Anywhere                  Main program\n    reqtools.library  LIBS:                     Library by Nico François\n    P0T-NOoDLE.FONT   FONTS:                    Font by P0t-Noodle\n\n  - an  Amiga Model (500/600/1000/1200/2000/2500/3000/4000/CDTV/CD³²)\n  - the installed Version of OS\2, OS\3 or higher\n    (Soft- or Hardware Version)\n\n  =======================================================================\n@endnode\n@node Cap03 "Program purpose."\n  =======================================================================\n\n  For maintenance operations as for copies for friends, sysops have always\n  been obliged to simultaneously look at their file listing and flag the\n  files one by one in their file manager prior to selecting the appropriate\n  operation which is generally a copy/move, a deletion or a backup. This\n  way of doing is pretty slow. Other sysops rather prefer flagging by date\n  immediately. This method has proved to be quite unreliable as dates can be\n  changed during a crash recovery and files can be wrongly dated at\n  uploading if your clock suddenly became foolish.\n\n  There are though some few utilities, most often doors for Ami-Express and\n  Sigma-Express, which can be of some help in these operations. These\n  utilities are not numerous and are generally coded by beginners, unreliable\n  and slow.\n\n  Here comes M.S.F.M. :)  This first version is without any doubt *not*\n  astonishing, but is a revolution as well. M.S.F.M. performs the 3 main\n  operations which are "copy, move, delete" from an ascii file list, and at\n  lightning speed. The whole program is fully coded in highly optimised\n  assembly code and a special care has been taken in the main algorithms\n  development. M.S.F.M. will find himself the files, all you have to do is\n  click 2-3 times and then watch TV ;)\n\n  =======================================================================\n@endnode\n@node Cap04 "Using M.S.F.M."\n  =======================================================================\n\n  The first thing you have to do is loading an ascii file list in order to\n  be able to perform an operation on these files. When you are done, you can\n  copy these files somewhere else, move them somewhere else or just\n  delete them.\n\n  When you want to perform a copy or move operation, you are first asked\n  to select 1 or more source drawer(s) and then a target drawer. The source\n  drawers are drawers where the program could find your files. Numerous\n  source drawers are of course possible coz huge quantities of software have\n  to be stored on several devices. Just choose your directories one by\n  one and click "select". When you are done, click "cancel" and you are\n  asked to give a target drawer where the files should be copied/moved.\n  Clicking on the "cancel" gadget on the first source drawer requester or on\n  the target drawer requester will abort the operation.\n\n  When you want to perform a deletion, the only difference is that there is\n  no target drawer to select ;)\n\n  Trick: M.S.F.M. will try to find the files sequentially in your source\n         drawers. This physical operation takes time and it is therefore\n         advised to select as first drawers the biggest ones, or, in other\n         words, the drawers where your files will be more likely stored to\n         avoid unsuccessful locks as much as possible.\n\n  When there is not enough space anymore on the target device to go on with\n  the copy/move operation, the choice will be offered to skip the current\n  file, skip all the files which won''t fit, continue on another device or\n  simply abort the operation.\n\n  =======================================================================\n@endnode\n@node Cap05 "Ascii lists format."\n  =======================================================================\n\n  The main problem is to have a standard in ascii file lists. There is none,\n  but most are basically using the same system, which is very flexible.\n  Follow the few easy rules listed below and M.S.F.M. will work. If your\n  BBS program does not work this way, you can modify the list before calling\n  M.S.F.M. or ask me to include a routine for you. Ami-Express sysops\n  should not worry as well, M.S.F.M. was tested with Ami-Express files\n  listings.\n\n  If your files list contains NO valid filenames or some invalid filenames,\n  no action will be taken. You will be warned if a file was not found.\n\n\n   - A FileName may not exceed 12 characters;\n\n   - A FileName must begin at the first column and end:\n\n      * with a space\n      * with a carriage return\n\n\n     Example:\n\n\nGD1.0.LHA    N    39k  12-15-94  New Decruncher Program (decrunch +130 dec.)\n-------------------------------\n976-PIFX.TXT N    11k  12-16-94  \n                                 -----------------------------------------\n                                 \ CYBORG OF 976 EV!L GIVES YOU :        /\n                                 / HELP ON HOW TO FIX THE VIRUS INFECTED \\n                                 \ VERSION OF  PINBALL ILLUSIONS AGA     /\n                                 ----------------------------------------\n sqdfqdgqgqfg\nBC_LAMER.TXT\n\nSR-MSFM.LHA kdjfldsjgdqighqoihglqfghralhgq\nSR-MSFM.NFO       <- There must be a carriage return or space after "o"\n\n\n  Total: 5 files.\n\n  =======================================================================\n@endnode\n@node Cap06 "Technical corner."\n  =======================================================================\n\n  M.S.F.M. has been coded keeping in mind that it *had* to be fast.\n  Therefore, I have (as usual :) ) used the assembly language and highly\n  optimised routines. I spent alot of time in creating powerful algorithms\n  for the purpose, and especially on the copy/move algorithm which is\n  without any doubt the world''s fastest at this time. Its speed will always\n  depend on the amount of free memory (ever heard this somewhere hehe) but as\n  sysops do have huge amounts of memory, they should get astonishing\n  results.\n\n  M.S.F.M can perform a move operation (which takes the most time) on files\n  present on 5 different devices, listed in a 1.2Mb  ascii file list and\n  totalling +/- 200 megs in 11524 filenames in about 10 mins on a simple\n  68000. This is awesomely astonishing...\n\n  M.S.F.M. was developped on an A2000 Kick 2.04 68000 (but works fine with\n  Retina, Picasso and screen promoters).\n\n  M.S.F.M V2.0 is currently under development on my brand new A4000/040.\n  I own a Retina Z3 4Mb with a 17" monitor and a 14" monitor on the\n  standard Amiga output channel. Therefore, I am currently working on a fully\n  configurable program (everything sensitive) able to work in and use up to\n  16.7 millions colors (yes !), with a f***ing great design ;)\n\n  =======================================================================\n@endnode\n@node Cap07 "The Author."\n  =======================================================================\n\n  Handle:     Diogenes\n  Group:      Skid Row\n  Function:   Coder and sysop\n  BBS Name:   Peace Chapel\n  BBS Number: +32-(0)2-331-38-09\n\n  If you wish to get on touch with me for anything, just call the BBS if\n  you have a modem and can afford a call. To get into the server, type this\n  as name and password:\n\n  NAME:      DIO\n  PASSWORD:  DIO\n\n  =======================================================================\n@endnode\n@node Cap08 "Greetings go to..."\n  =======================================================================\n\n                        SHORT GREETS GO TO THESE SYSOPS:\n\n\n    Big Boss/Fairlight ..................... Hope to see ya back one day!\n    John Yaya/LSD .................................. Ma friend I miss ya!\n    Rhys / Delirium ................................. ''m also missing ya!\n    Tarzan ........................................ Long time ago, sorry!\n    Chucky ............................................ Still sysop ? ;-)\n    Sintax/WoT/OTL ..................... I definitively hate Belgacom ;-)\n    ULI ........................................... Ma own Beta-Tester ;)\n    Mousebuster / Prestige ........................ I prefer cats hehe ;)\n\n\n              >>> ALL SKID ROW MEMBERS!!! <<<\n\n\n  I wish to thank - ULI for having so nicely tested M.S.F.M.;\n                  - P0T-NOODLE for his nice font;\n                  - Nico François for his great Reqtools library\n                  - Mousebuster who owned the *only* Amiga MSFM did not\n                    work on !\n\n  I do not thank the other sysops who were supposedly testing it but never\n  reported me anything.\n\n  =======================================================================\n@endnode\n@node Cap09 "History."\n  =======================================================================\n\n V1.0:  First official release.\n\n  =======================================================================\n@endnode\n','\n',char(10)),NULL,'auto-added',68839,16,0,NULL,NULL,'sr_sfm10','scan',1780048740);
INSERT INTO door_catalog VALUES('sr_sfm11','SR-SFM11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SR-SFM11.LHA','8','XIM','8',NULL,NULL,'SR','/  ____ ¬| _____)___ ¬|  \___ ____. ¬|¬|¬| ) \___ ¬\  _  /  ¬\  /  |  /  _  / ¬|  | | | \ /_____/__|  \_  /___  |  \__|  \___  l_____/',replace(' ________.____/\______.  ________/|__._._._\n/  ____ ¬| _____)___ ¬|  \___ ____. ¬|¬|¬| )\n\___ ¬\  _  /  ¬\  /  |  /  _  / ¬|  | | | \\n/_____/__|  \_  /___  |  \__|  \___  l_____/\n        ¬`---''\/tGø`--''    ¬`---'' `--''\nDIOGENES STRIKES AGAIN WITH M.S.F.M V1.01\nBEST AND ONLY ONE FILE MANAGER FOR SYSOPS\nWORKS ON ASCII FILE LISTS - SEVERAL BBS\nSYSTEMS SUPPORTED - FASTEST COPY ALGORITHM\nEVER CODED INCLUDED IN THIS MASTERPIECE ! ;)\nCOPY/MOVE/DELETE GIGS OF STUFF IN 5 MINS !\nPE/\CE CH/\PEL ONLY! +32-2-331-38-09 4Ndz 33\n','\n',char(10)),'MSFM.Guide',replace('@database MSFM-DOC\n@Author DIOGENES / SKID ROW!\n@Index MAIN\n\nCopyright (c) 1994-1996 DIOGENES / SKID ROW!\n\n@Remark $VER: (January 3 1995/May 19 1996, 21:14:37)\n@Remark AmigaGuide database for the MSFM Documentation\n\n@node MAIN "MSFM Documentation (c)1994-1996 DIOGENES of SKID ROW! (January 3 1995/May 19 1996, 21:14:37)"\n                                          :              __\n                                          ¦             /\_\             .\n             .____________________________!___________/\\/_____________ _!_\n             |                           \|         __/\\/               |\n   __________l______ _____________________l         \_\/                 ¦\n _/    ________   ¬T/    /_____________   ¬\_                            ¦\n T______    ¬T     ¬    < |    ¬|    ¬T     T      >>> M.S.F.M. <<<      :\n |    ¬T     |     T     \|     |     |     |                            ·\n |___________¦_____|\     \_____¦___________¦ Code: DIOGENES / SKID ROW! |\n             ¦       \_____\              |                              |\n             |                            |                              ¦\n             |                      ______l________________        _____ ¦\n             :                      \______   ¬\         ¬|\      /    / :\n             `-----------------------T    _    /    |     | \    /    /--''\n                                     |    T    \_   |     |  \/\/    /\n                                     |____|     T_________¦         /\n                                          |_____¦      MpLx___/\___/\n\n\n         >>> C·O·N·T·E·N·T·S  O·F  D·O·C·U·M·E·N·T·A·T·I·O·N <<<\n\n                         @{"      Introduction      " Link Cap01}\n                         @{"      Requirements      " Link Cap02}\n                         @{"    Program  purpose    " Link Cap03}\n                         @{"     Using  M.S.F.M     " Link Cap04}\n                         @{"   Ascii Lists format   " Link Cap05}\n                         @{"    Technical Corner    " Link Cap06}\n                         @{"       The  author      " Link Cap07}\n                         @{"        Greetings       " Link Cap08}\n                         @{"         History        " Link Cap09}\n\n           Multi-Server File Manager V1.01 (c) Diogenes / Skid Row\n         -----------------------------------------------------------\n\n This program has been tested with Ami/Sigma-Express/DayDream ascii file\n listings but will be useful to most sysops because most BBS programs are\n basically using the same files listing system. If you are not using one\n of these 3 programs, you should immediately refer to the chapter concerning\n Ascii lists format in order to see if the program is able to handle your\n listings. If not, you can contact me to include your system in my list\n scanning algorithm. I will do it for free.\n\n A converter has been made for the /T\empest binary catalogs\n\n         -----------------------------------------------------------\n                Complete Docs for M.S.F.M. V1.0 [-SKID ROW!-]\n         -----------------------------------------------------------\n         The Documentation has been written by DIOGENES / SKID ROW!.\n\n@endnode\n@node Cap01 "Introduction."\n  =======================================================================\n\n  M.S.F.M has been coded in a hurry in January 1994 to deserve my needs as\n  soon as possible. The main part was done in a week, and 3 more weeks were\n  needed to test, improve, add features, test again and again to finally\n  have an acceptable and releasable version 1.0, as other sysops have\n  quickly showed much interest in this program. At the same time, I had\n  other obligations, and most of the time, I had 30 mins / day to work on\n  it.\n\n  Anyway, this should explain the poor user-friendliess. The screen size\n  is currently locked at 640*256 (PAL) or 640*200(NTSC), the gadgets are\n  not auto-sizing and the program is not font-sensitive. I planned an\n  "astonishing" V2.0 which I never finished...  One day will see this\n  release I guess ;)\n\n  Today, the 19th of May 1996, I changed the program a bit to allow filename\n  lenghts up to 31 chars. This is the only change since 1994. A converter\n  is also supplied for the /T\empest V3.40+ binary catalogs because I\n  switched to this great BBS program since then.\n\n  =======================================================================\n@endnode\n@node Cap02 "Requirements."\n  =======================================================================\n\n  To install M.S.F.M. you must have the following things:\n\n    Program           Location                  Description\n    -------           --------                  -----------\n    MSFM              Anywhere                  Main program\n    reqtools.library  LIBS:                     Library by Nico François\n    P0T-NOoDLE.FONT   FONTS:                    Font by P0t-Noodle\n\n  - an  Amiga Model\n  - the installed Version of OS\2, OS\3 or higher\n    (Soft- or Hardware Version)\n\n  =======================================================================\n@endnode\n@node Cap03 "Program purpose."\n  =======================================================================\n\n  For maintenance operations as for copies for friends, sysops have always\n  been obliged to simultaneously look at their file listing and flag the\n  files one by one in their file manager prior to selecting the appropriate\n  operation which is generally a copy/move, a deletion or a backup. This\n  way of doing is pretty slow. Other sysops rather prefer flagging by date\n  immediately. This method has proved to be quite unreliable as dates can be\n  changed during a crash recovery and files can be wrongly dated at\n  uploading if your clock suddenly became foolish.\n\n  There are though some few utilities, most often doors, which can be of some\n  help in these operations. These utilities are not numerous and are generally\n  coded by beginners.. Most often unreliable and slow.\n\n  Here comes M.S.F.M. :)  This first version is without any doubt *not*\n  astonishing, but is a revolution as well. M.S.F.M. performs the 3 main\n  operations which are "copy, move, delete" from an ascii file list, and at\n  lightning speed. The whole program is fully coded in highly optimised\n  assembly code and a special care has been taken in the main algorithms\n  development. M.S.F.M. will find himself the files, all you have to do is\n  click 2-3 times and then watch TV ;)\n\n  =======================================================================\n@endnode\n@node Cap04 "Using M.S.F.M."\n  =======================================================================\n\n  The first thing you have to do is loading an ascii file list in order to\n  be able to perform an operation on these files. When you are done, you can\n  copy these files somewhere else, move them somewhere else or just\n  delete them.\n\n  When you want to perform a copy or move operation, you are first asked\n  to select 1 or more source drawer(s) and then a target drawer. The source\n  drawers are drawers where the program could find your files. Numerous\n  source drawers are of course possible coz huge quantities of software have\n  to be stored on several devices. Just choose your directories one by\n  one and click "select". When you are done, click "cancel" and you are\n  asked to give a target drawer where the files should be copied/moved.\n  Clicking on the "cancel" gadget on the first source drawer requester or on\n  the target drawer requester will abort the operation.\n\n  When you want to perform a deletion, the only difference is that there is\n  no target drawer to select ;)\n\n  Trick: M.S.F.M. will try to find the files sequentially in your source\n         drawers. This physical operation takes time and it is therefore\n         advised to select as first drawers the biggest ones, or, in other\n         words, the drawers where your files will be more likely stored to\n         avoid unsuccessful locks as much as possible.\n\n  When there is not enough space anymore on the target device to go on with\n  the copy/move operation, the choice will be offered to skip the current\n  file, skip all the files which won''t fit, continue on another device or\n  simply abort the operation.\n\n  =======================================================================\n@endnode\n@node Cap05 "Ascii lists format."\n  =======================================================================\n\n  The main problem is to have a standard in ascii file lists. There is none,\n  but most are basically using the same system, which is very flexible.\n  Follow the few easy rules listed below and M.S.F.M. will work. If your\n  BBS program does not work this way, you can modify the list before calling\n  M.S.F.M. or ask me to include a routine for you. Ami/Sigma-Express/DayDream\n  sysops should not worry as well, M.S.F.M. was tested with such files\n  listings. /T\empest sysops will find enclosed in this archive a converter\n  to convert the .IDX binary file in an ascii file list.\n\n  If your files list contains NO valid filenames or some invalid filenames,\n  no action will be taken. You will be warned if a file was not found.\n\n\n   - A FileName may not exceed 31 characters;\n\n   - A FileName must begin at the first column and end:\n\n      * with a space\n      * with a carriage return\n\n\n     Example:\n\n\nGD1.0.LHA    N    39k  12-15-94  New Decruncher Program (decrunch +130 dec.)\n-------------------------------\n976-PIFX.TXT N    11k  12-16-94  \n                                 -----------------------------------------\n                                 \ CYBORG OF 976 EV!L GIVES YOU :        /\n                                 / HELP ON HOW TO FIX THE VIRUS INFECTED \\n                                 \ VERSION OF  PINBALL ILLUSIONS AGA     /\n                                 ----------------------------------------\n sqdfqdgqgqfg\nBC_LAMER.TXT\n\nSR-MSFM.LHA kdjfldsjgdqighqoihglqfghralhgq\nSR-MSFM.NFO       <- There must be a carriage return or space after "o"\n\n\n  Total: 5 files.\n\n  =======================================================================\n@endnode\n@node Cap06 "Technical corner."\n  =======================================================================\n\n  M.S.F.M. has been coded keeping in mind that it *had* to be fast.\n  Therefore, I have (as usual :) ) used the assembly language and highly\n  optimised routines. I spent alot of time in creating powerful algorithms\n  for the purpose, and especially on the copy/move algorithm which is\n  without any doubt the world''s fastest at this time. Its speed will always\n  depend on the amount of free memory (ever heard this somewhere hehe) but as\n  sysops do have huge amounts of memory, they should get astonishing\n  results. And anyway, the program itself helps sparing alot of time !\n\n  M.S.F.M can perform a move operation (which takes the most time) on files\n  present on 5 different devices, listed in a 1.2Mb  ascii file list and\n  totalling +/- 200 megs in 11524 filenames in about 10 mins on a simple\n  68000. This is awesomely astonishing...\n   |\n   `--> Old & obsolete test in our Mhz world today ;)\n\n  I began a real nice user-friendly V2.0 some months ago.. who knows, I will\n  maybe finish it one day :)\n\n  =======================================================================\n@endnode\n@node Cap07 "The Author."\n  =======================================================================\n\n  Handle:     Diogenes\n  Group:      Skid Row\n  Function:   Coder and sysop\n  BBS Name:   Peace Chapel\n  BBS Number: +32-(0)2-331-38-09\n  NUP:        BUZZHEAD\n\n  If you wish to get on touch with me for anything, just call the BBS if\n  you have a modem and can afford a call. Say that you come for MSFM,\n  or you won''t get access.\n\n  =======================================================================\n@endnode\n@node Cap08 "Greetings go to..."\n  =======================================================================\n\n                        SHORT GREETS GO TO THESE SYSOPS:\n\n\n    Big Boss/Fairlight ..................... Hope to see ya back one day!\n    John Yaya/LSD .................................. Ma friend I miss ya!\n    Rhys / Delirium ................................. ''m also missing ya!\n    Tarzan ........................................ Long time ago, sorry!\n    Chucky ............................................ Still sysop ? ;-)\n    Sintax/WoT/OTL ..................... I definitively hate Belgacom ;-)\n    ULI ........................................... Ma own Beta-Tester ;)\n    Mousebuster / Prestige ........................ I prefer cats hehe ;)\n\n And all the others since 1994 ;)\n\n\n              >>> ALL SKID ROW MEMBERS!!! <<<\n\n\n  I wish to thank - ULI for having so nicely tested M.S.F.M.;\n                  - P0T-NOODLE for his nice font;\n                  - Nico François for his great Reqtools library\n                  - Mousebuster who owned the *only* Amiga MSFM did not\n                    work on !\n\n  I do not thank the other sysops who were supposedly testing it but never\n  reported me anything.\n\n  =======================================================================\n@endnode\n@node Cap09 "History."\n  =======================================================================\n\n V1.00:  First official release on January 3th 1995.\n\n V1.01:  MSFM can now handle 31 chars filenames. See chapter about ascii\n         file lists for more. Released on May 19th 1996.\n\n         Thanks to WREC for suggesting.\n\n  =======================================================================\n@endnode\n','\n',char(10)),NULL,'auto-added',62473,2,0,NULL,NULL,'sr_sfm11','scan',1780048749);
INSERT INTO door_catalog VALUES('sre_ad11','SRE-AD11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SRE-AD11.LHA','Advertiser','XIM','Advertiser',NULL,NULL,'SRE','.____/\__|\\/___/\___/\__/\___\/  ___/\ ¡  ___/  | \/   _ \_ _ \_. \_ \/\/   . \_ |___ \   |  \_  |  / ___/i__/    \   i__/',replace('         .   / » CoSMoS of  « /\n.____/\__|\\/___/\___/\__/\___\/  ___/\\n¡  ___/  | \/   _ \_ _ \_. \_ \/\/   . \_\n|___ \   |  \_  |  / ___/i__/    \   i__/\n|  /  \_ |   /  __/   \  ._)  ¡¡  \_ ._)\n| /    / !  /   |   ¡  \_i \_ ||   / i \_\nl_____/____/\___|\__|   /_  /_||  /___  /\n>------------^aRYAN^l__/-\_/---l_/--.\_/\nPRESENTS <--------------------------''\n     ·»  ADVERTISER v1.11  «·\n- Advertiser/AddStripper for any bbS\nSoftware...\n','\n',char(10)),'Advertiser.doc',replace('                        Advertiser v1.11 Documentation\n                        ------------------------------\n\n\nProgram runs commands that are given in the config-file. It looks the suffix\nof the file that is given in commandline and search same suffix in config-\nfile and runs lines that are after the suffix.\n\n\nAdvertiser <file> [-N<number>] [-C<config-file>]\n\n<file> = File that is added to lines.\n\n<number> = If number exists, it is the line group number of the same suffix.\n\n<config-file> = Config-file. If it not exists, config-file is\n                DAYDREAM:Configs/Advertiser.cfg\n\n\nConfig-file:\n\nNo more than 1024 chars in the same line.\n\n!suffix (uppercase)\nlines (%F is replaced the file name)\n.\n.\n.\n+ or !suffix or ~ (if it is +, the same suffix has many line groups.\n.                  ~ is the char of the end of the file)\n.\n.\n','\n',char(10)),NULL,'auto-added',16361,3,0,NULL,NULL,'sre_ad11','scan',1780048749);
