INSERT INTO door_catalog VALUES('sre_delc','SRE-DELC.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SRE-DELC.LHA',NULL,'XIM','sre-join.exe',NULL,NULL,'SRE','.____/\____/\_____/\   .÷.  only (?) manual ¡  ____/   _ \_  .  \  :P÷   delete door! |____ \    ___/  i__/  ·r· Multipli flaging.',replace('  -(·mAd mOOse Of·)-          This is the\n.____/\____/\_____/\   .÷.  only (?) manual\n¡  ____/   _ \_  .  \  :P÷   delete door!\n|____ \    ___/  i__/  ·r· Multipli flaging.\n|   /  \_    \   ._)   ÷e·\n|  /    / |   \_ i \_  :s: This door also\nl______/__|    /__  /  ·e. lists the DirX\n ^aRYAN^  l___/  \_/   ÷n: file and let the\n                       ·t÷ SysOp/user flag\n mAD DELETE v 0.01c    :s: files from that\n>fOR /X 2.x - 4.x<     `÷'' point. *GREAT*\n ^^^^^^^^^^^^^^^^           »NEW UPDATE«\n','\n',char(10)),'mADdELETE.doc',replace('      /\  /\  ___/\_____/\      /\  /\  ___/\  ___/\_____/\____/\\n     /  \/  \/  .  \      \    /  \/  \/     \/     \  ____/   . \_ _\n     |       \_ !   \_ |   \_  |       \_ ¡   \_ ¡   \___ \    i__/ /\n     |  ¡¡    / .    / |    /  |  ¡¡    / |    / |    / /  \_  ._)\n     |  ||   /  ¡   /  l_  /   |  ||   /  !   /  !   / /    /  i \_\n     l__||  /\__|  /______/    l__||  /\_____/\_____/______/____  /\n         l_/    l_/                l_/                  ^aRYAN^\_/\n\n			      P R E S E N T S\n	\n		      m A D   D E L E T E   v  0 . 0 1 c\n\n\nThis is the fifth door from me. I''ve been missing one thing\nin /X, and that is that you have to delete files by hand!\nAnd my friend aRYAN have long been telling me to do a delete door.\nAnd now here it is!!! The first manual delete door! (I THINK?)\nThe door supports multiple flaging, soon also cursor flaging!\n\nStill it''s a little bit to sloooow, but I will see what I can do\nabout this... (blame arexx!)\n\nOne little bug is that the tag line get ''corrupted'' when the\nend of the file. This will be fixed later, it''s only a little bug!\n\n\n\n\nAbout the config file\n---------------------\n\nThe first line should contain a temporary path, (don''t forget :, /)\nthe second line should be the maximum number of DirX''s.\nIf you want a password, enter the password on the 3''rd line\nelse just write NOPASSWORD.\nIf you don''t want the program to check for names enter NONAMES\non the 4''th line else enter the number of names, then if you wrote\n2 on the 4''th line then you should enter one name on the next line\nand one on the next one!\n(^^CASE SENSITIVE^^)\nThe line after the names you should enter how many conferances\nyou have (EVERYONE!), the number should be followed by\nthe upload/download path to conferance x.\n\nExample config file:\n\nvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvv\n\nWork:Work/		< TEMP PATH\n6			< MAXIMUM DirX''s\nNOPASSWORD		< NOPASSWORD\n1			< NUMBER OF NAMES\nmAd mOOse 		< NAME ONE\n3			< NUMBER OF CONFERANCES\nUPLOAD:1/		< CONFERANCE UPLOAD PATH 1\nUPLOAD:2/		< CONFERANCE UPLOAD PATH 1\nUPLOAD:3/		< CONFERANCE UPLOAD PATH 1\n\n^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^\n\nHistory\n-------\n\n0.01a - First public release (?)\n0.01b - Found some bugs\n0.01c - Noticed that it created the dummy file at the wrong place, fixed!\n\n\nThat should be it folks!\n\nIf you don''t know how to install a door then shutdown your board!\n\nTo report bugs or if you have any comments about the program or maybe\nsome ideas how to make it better (if possible) then call:\n\n            .     .                                         .\n            ¡\    ¡\                                        _\  .\n  ____/\  __| \___| \____/\____/\  ___/\_____/\____/\  __/\/ \\/_  ___/\\n_/   __ \/  |  \ ¬|  \  .  \   . \/   . \_   . \_    \/  . \  \/¬\/   . \_\n\____/¬  \_ !   \_|   \_¡   \_ ¡  \_  i__/   i  /  ¡  \_ ¡  \_..  \_  i__/\n    /     / .    /|    /|    / |   /  ._)  . __/   |   / |   /¡¡   /  ._)\n    \    /  ¡   / !   / |   /  l_ /   i \_ ¡  \_   l_ /  !  / ||  /   i \_\n    .\  /\__|  /\____/__|  /_____/\____  /_|   /_____/\____/__!| /\____  /\n     \\/.  ¬l_/        ¬l_/          ¬\_/ ¬l__/ ^aRYAN^       :l/    ¬\_/\n      \/\n\n          -÷[ Sysop:CLAUDiA SCHiFFER ]÷-  -÷[ Hd Space .4GiG ]÷-\n \n           -÷[ 0-¹ Days Warez ]÷-  -÷[ No New User Password ]÷-\n \n    -÷[ Node1 +46(0)455-59060 ]÷-  -÷[ Supreme World HeadQuarter]÷-\n \n\nand leave a comment to mAd mOOse , with an extra space after the name!\n\n\n					/ mAd mOOse SiGNING oFF\n','\n',char(10)),NULL,'auto-added',48825,4,0,NULL,NULL,'sre_delc','scan',1780048749);
INSERT INTO door_catalog VALUES('sre_deld','SRE-DELD.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SRE-DELD.LHA',NULL,'XIM','::::::::::::::::::::::::::::::::::::::::::::',NULL,NULL,'SRE','::/ __/   /       /\-----------------------» :/_  / / /  /    /  \   mAD DELETE v 0.01d / / / / /  /____/    \',replace('::::::::::::::::::::::::::::::::::::::::::::\n::/ __/   /       /\-----------------------»\n:/_  / / /  /    /  \   mAD DELETE v 0.01d\n/ / / / /  /____/    \\n\  /  _/  ____ /      ) Probably the only\n:\/ / /  /    /      / manual delete door\n::\/ /  /    /      / for all /X versions!\n:::\/  /    /      / Multipli flaging etc.\n::::\      /      /  « WORLD RELEASE AT »\n:::::\    /      / » THUNDER DOME, SRE WHQ «\n::::::\  /      /--------------------------»\n:::::::\/______/::::::::::::::::::::::::::::\n','\n',char(10)),'mADdELETE.doc',replace('      /\  /\  ___/\_____/\      /\  /\  ___/\  ___/\_____/\____/\\n     /  \/  \/  .  \      \    /  \/  \/     \/     \  ____/   . \_ _\n     |       \_ !   \_ |   \_  |       \_ ¡   \_ ¡   \___ \    i__/ /\n     |  ¡¡    / .    / |    /  |  ¡¡    / |    / |    / /  \_  ._)\n     |  ||   /  ¡   /  l_  /   |  ||   /  !   /  !   / /    /  i \_\n     l__||  /\__|  /______/    l__||  /\_____/\_____/______/____  /\n         l_/    l_/                l_/                  ^aRYAN^\_/\n\n			      P R E S E N T S\n	\n		      m A D   D E L E T E   v  0 . 0 1 d\n\n\nThis is the fifth door from me. I''ve been missing one thing\nin /X, and that is that you have to delete files by hand!\nAnd my friend aRYAN have long been telling me to do a delete door.\nAnd now here it is!!! The first manual delete door! (I THINK?)\nThe door supports multiple flaging, soon also cursor flaging!\n\nStill it''s a little bit to sloooow, but I will see what I can do\nabout this... (blame arexx!)\n\nOne little bug is that the tag line get ''corrupted'' when the\nend of the file. This will be fixed later, it''s only a little bug!\n\n\n\n\nAbout the config file\n---------------------\n\nThe first line should contain a temporary path, (don''t forget :, /)\nthe second line should be the maximum number of DirX''s.\nIf you want a password, enter the password on the 3''rd line\nelse just write NOPASSWORD.\nIf you don''t want the program to check for names enter NONAMES\non the 4''th line else enter the number of names, then if you wrote\n2 on the 4''th line then you should enter one name on the next line\nand one on the next one!\n(^^CASE SENSITIVE^^)\nThe line after the names you should enter how many conferances\nyou have (EVERYONE!), the number should be followed by\nthe upload/download path to conferance x.\n\nExample config file:\n\nvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvv\n\nWork:Work/		< TEMP PATH\n6			< MAXIMUM DirX''s\nNOPASSWORD		< NOPASSWORD\n1			< NUMBER OF NAMES\nmAd mOOse 		< NAME ONE\n3			< NUMBER OF CONFERANCES\nUPLOAD:1/		< CONFERANCE UPLOAD PATH 1\nUPLOAD:2/		< CONFERANCE UPLOAD PATH 1\nUPLOAD:3/		< CONFERANCE UPLOAD PATH 1\n\n^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^\n\nHistory\n-------\n\n0.01a - First public release (?)\n0.01b - Found some bugs\n0.01c - Noticed that it created the dummy file at the wrong place, fixed!\n0.01d - Found out that this door won''t work with more than one user\n	able to delete files, fixed! Also found out that this door\n	will screw up the listing when running /X in interlaced,\n	shit, will fix this thing later!\n\nThat should be it folks!\n\nIf you don''t know how to install a door then shutdown your board!\n\nTo report bugs or if you have any comments about the program or maybe\nsome ideas how to make it better (if possible) then call:\n\n            .     .                                         .\n            ¡\    ¡\                                        _\  .\n  ____/\  __| \___| \____/\____/\  ___/\_____/\____/\  __/\/ \\/_  ___/\\n_/   __ \/  |  \ ¬|  \  .  \   . \/   . \_   . \_    \/  . \  \/¬\/   . \_\n\____/¬  \_ !   \_|   \_¡   \_ ¡  \_  i__/   i  /  ¡  \_ ¡  \_..  \_  i__/\n    /     / .    /|    /|    / |   /  ._)  . __/   |   / |   /¡¡   /  ._)\n    \    /  ¡   / !   / |   /  l_ /   i \_ ¡  \_   l_ /  !  / ||  /   i \_\n    .\  /\__|  /\____/__|  /_____/\____  /_|   /_____/\____/__!| /\____  /\n     \\/.  ¬l_/        ¬l_/          ¬\_/ ¬l__/ ^aRYAN^       :l/    ¬\_/\n      \/\n\n          -÷[ Sysop:CLAUDiA SCHiFFER ]÷-  -÷[ Hd Space .4GiG ]÷-\n \n           -÷[ 0-¹ Days Warez ]÷-  -÷[ No New User Password ]÷-\n \n    -÷[ Node1 +46(0)455-59060 ]÷-  -÷[ Supreme World HeadQuarter]÷-\n \n\nand leave a comment to mAd mOOse , with an extra space after the name!\n\n\n					/ mAd mOOse SiGNING oFF\n','\n',char(10)),NULL,NULL,5512,1,0,NULL,NULL,NULL,'scan',1780048749);
