INSERT INTO door_catalog VALUES('sre_movb','SRE-MOVB.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SRE-MOVB.LHA',NULL,'XIM','::::::::::::::::::::::::::::::::::::::::::::',NULL,NULL,'SRE','::/ __/   /       /\-----------------------» :/_  / / /  /    /  \    mAD MoVE v 0.01b / / / / /  /____/    \',replace('::::::::::::::::::::::::::::::::::::::::::::\n::/ __/   /       /\-----------------------»\n:/_  / / /  /    /  \    mAD MoVE v 0.01b\n/ / / / /  /____/    \\n\  /  _/  ____ /      ) Probably the first\n:\/ / /  /    /      / manual move door for\n::\/ /  /    /      / ALL /X versions.\n:::\/  /    /      / Multipli flaging etc.\n::::\      /      /  « WORLD RELEASE AT »\n:::::\    /      /    -·>THUNDER DOME<·-\n::::::\  /      /--------------------------»\n:::::::\/______/::::::::::::::::::::::::::::\n','\n',char(10)),'mADMoVE.doc',replace('      /\  /\  ___/\_____/\      /\  /\  ___/\  ___/\_____/\____/\\n     /  \/  \/  .  \      \    /  \/  \/     \/     \  ____/   . \_ _\n     |       \_ !   \_ |   \_  |       \_ ¡   \_ ¡   \___ \    i__/ /\n     |  ¡¡    / .    / |    /  |  ¡¡    / |    / |    / /  \_  ._)\n     |  ||   /  ¡   /  l_  /   |  ||   /  !   /  !   / /    /  i \_\n     l__||  /\__|  /______/    l__||  /\_____/\_____/______/____  /\n         l_/    l_/                l_/                  ^aRYAN^\_/\n\n                              P R E S E N T S\n\n                      m A D   M o V E   v  0 . 0 1 b\n\n\nI''ve been missing one thing in /X, and that is that you have to move\nfiles by hand! And my friend aRYAN have long been telling me to do\na move door. And now here it is!!! The first manual move door! (I THINK?)\nSupports multipli flaging, able to move whole DirX files.\n\nStill it''s a little bit to sloooow, but I will see what I can do\nabout this... (blame arexx!)\n\nOne little bug is that the tag line get ''corrupted'' when the\nend of the file. This will be fixed later, it''s only a little bug!\n\n\n\n\nAbout the config file\n---------------------\n\nThe first line should contain a temporary path, (don''t forget :, /)\nthe second line should be the maximum number of DirX''s.\nIf you want a password, enter the password on the 3''rd line\nelse just write NOPASSWORD.\nIf you don''t want the program to check for names enter NONAMES\non the 4''th line else enter the number of names, then if you wrote\n2 on the 4''th line then you should enter one name on the next line\nand one on the next one!\n(^^CASE SENSITIVE^^)\nThe line after the names you should enter how many conferances\nyou have (EVERYONE!).\nFirst:   Name of conferance\nSecond:  Upload/Download path\nThird:   Conferance path\nFourth:  Number of DirX files, 0 for none!\n\nExample config file:\n\nvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvvv\n\nWork:Work/		< TEMP PATH\n6			< MAXIMUM DirX''s\nNOPASSWORD		< NOPASSWORD\n1			< NUMBER OF NAMES\nmAd mOOse 		< NAME ONE\n3			< NUMBER OF CONFERANCES\ntRASH			< CONFERANCE NAME 1\nUPLOAD:1/		< CONFERANCE UPLOAD PATH 1\nBBS:1trash/		< CONFERANCE PATH 1\npD			< CONFERANCE NAME 2\nUPLOAD:1/		< CONFERANCE UPLOAD PATH 2\nBBS:2pd/		< CONFERANCE PATH 2\nPRiVATE			< CONFERANCE NAME 3\nUPLOAD:1/		< CONFERANCE UPLOAD PATH 3\nBBS:3private/		< CONFERANCE PATH 3\n\n^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^\n\nHistory\n-------\n\n0.01a - First public release\n0.01b - Found some bugs, sorry for releaseing v 0.01a noticed that\n        it wasn''t ready, sorry!!!!! Also noticed that it fucks up\n        if you run in interlaced mode, don''t know how to fix this,\n        will be fixed later on.\n\n\nThat should be it folks!\n\nIf you don''t know how to install a door then shutdown your board!\n\nTo report bugs or if you have any comments about the program or maybe\nsome ideas how to make it better (if possible) then call:\n\n            .     .                                         .\n            ¡\    ¡\                                        _\  .\n  ____/\  __| \___| \____/\____/\  ___/\_____/\____/\  __/\/ \\/_  ___/\\n_/   __ \/  |  \ ¬|  \  .  \   . \/   . \_   . \_    \/  . \  \/¬\/   . \_\n\____/¬  \_ !   \_|   \_¡   \_ ¡  \_  i__/   i  /  ¡  \_ ¡  \_..  \_  i__/\n    /     / .    /|    /|    / |   /  ._)  . __/   |   / |   /¡¡   /  ._)\n    \    /  ¡   / !   / |   /  l_ /   i \_ ¡  \_   l_ /  !  / ||  /   i \_\n    .\  /\__|  /\____/__|  /_____/\____  /_|   /_____/\____/__!| /\____  /\n     \\/.  ¬l_/        ¬l_/          ¬\_/ ¬l__/ ^aRYAN^       :l/    ¬\_/\n      \/\n\n          -÷[ Sysop:CLAUDiA SCHiFFER ]÷-  -÷[ Hd Space .4GiG ]÷-\n \n           -÷[ 0-¹ Days Warez ]÷-  -÷[ No New User Password ]÷-\n \n    -÷[ Node1 +46(0)455-59060 ]÷-  -÷[ Supreme World HeadQuarter]÷-\n \n\nand leave a comment to mAd mOOse , with an extra space after the name!\n\n\n					/ mAd mOOse SiGNING oFF\n','\n',char(10)),NULL,NULL,6342,1,0,NULL,NULL,NULL,'scan',1780048749);
INSERT INTO door_catalog VALUES('sre_msdb','SRE-MSDB.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SRE-MSDB.LHA',NULL,'XIM','13GOZY2WB4LCS.EXE',NULL,NULL,'SRE','.____/\__|\\/___/\___/\__/\___\/  ___/\   AT ¡  ___/  | \/   _ \_ _ \_. \_ \/\/   . \_ |___ \   |  \_  |  / ___/i__/    \   i__/T··',replace('         .   /  mAd mOOse oF \ WORLD RELEASE\n.____/\__|\\/___/\___/\__/\___\/  ___/\   AT\n¡  ___/  | \/   _ \_ _ \_. \_ \/\/   . \_\n|___ \   |  \_  |  / ___/i__/    \   i__/T··\n|  /  \_ |   /  __/   \  ._)  ¡¡  \_ ._)·H·D\n| /    / !  /   |   ¡  \_i \_ ||   / i \_U·O\nl_____/____/\___|\__|   /_  /_||  /___  /D·M\n>------------^aRYAN^l__/-\_/---l_/--.\_/·E·E\nPRESENTS <--------------------------''   ·R··\n         mAD SysDown v 0.01b  (2.x - 4.x)\nReplacement for DS. Multipli flaging, forb-\nidding of files, name check. «·NEW UPDATE·»\n','\n',char(10)),'mADSysDown.doc',replace('        /\  /\  ___/\_____/\      /\  /\  ___/\  ___/\_____/\____/\\n       /  \/  \/  .  \      \    /  \/  \/     \/     \  ____/   . \_ _\n       |       \_ !   \_ |   \_  |       \_ ¡   \_ ¡   \___ \    i__/ /\n       |  ¡¡    / .    / |    /  |  ¡¡    / |    / |    / /  \_  ._)\n       |  ||   /  ¡   /  l_  /   |  ||   /  !   /  !   / /    /  i \_\n       l__||  /\__|  /______/    l__||  /\_____/\_____/______/____  /\n           l_/    l_/                l_/                  ^aRYAN^\_/\n\n                              P R E S E N T S\n	\n                     m A D  S y s D o w n  v 0 . 0 1 b        (2.x - 4.x)\n\nThis is a replacement for the DS command in /X.\nThis door SHOULD be much, much safer. As I have seen\nthere ain''t many DS replacement out now so I coded this one.\nThis door allows multipli file selection, you are also able\nto forbid some files from being downloaded.\n\nmADSysDown.cfg\n--------------\n\nLine 1:  The password. Enter NOPASSWORD to disable.\nLine 2:  Number of users that should have access to this door.\n         NONAMES to disable name check.\nLine 3:  If defined name 1\nLine 4:  If defined name 2 etc.\n\n\nmADSysDown.dat\n--------------\n\nIn this file you can forbid some files from being downloaded.\nYou only need to enter a part of the filename.\nExample:\nIf you want to forbid BBS:User.data from being downloaded then\nyou just enter: .data in the mADSysDown.dat file.\nIf you want to forbid Term:Config/Term.prefs from being downloaded then\nyou just enter: .PREFS or TERM. in the mADSysDown.dat file.\n\n                    ^^ ACHTUNG ^^\n\nThere is still one little problem. When a user enters for\nexample: DH-: by misstake then the bbs will hang! That''s quite\na big problem but if any one of you out there have the program:\nDosReq and with that program you can disable all requesters.\nIf you have that program USE it otherwise the board might hang!\nOr you can enter DH-: in the mADSysDown.dat file.\n(a smart thing to do is to enter DF and FF in the mADSysDown.dat file,\nbecause that prevents the user from downloading from FFx: and DFx: !)\n\n                    ^^ ACHTUNG ^^\n\n\nHistory\n-------\n\n0.01a - The very first public release\n0.01b - Changed so that the door doesn''t quit if you enter a forbidden\n        or not existing file. Also changed so that you can''t download\n        a directory because /X doesn''t support this. Might be added in\n        later versions of this door. Some small cosmetic changes.\n\n\nThat should be it folks!\n\nIf you don''t know how to install a door then shutdown your board!\n\nTo report bugs or if you have any comments about the program or maybe\nsome ideas how to make it better (if possible) then call:\n\n            .     .                                         .\n            ¡\    ¡\                                        _\  .\n  ____/\  __| \___| \____/\____/\  ___/\_____/\____/\  __/\/ \\/_  ___/\\n_/   __ \/  |  \ ¬|  \  .  \   . \/   . \_   . \_    \/  . \  \/¬\/   . \_\n\____/¬  \_ !   \_|   \_¡   \_ ¡  \_  i__/   i  /  ¡  \_ ¡  \_..  \_  i__/\n    /     / .    /|    /|    / |   /  ._)  . __/   |   / |   /¡¡   /  ._)\n    \    /  ¡   / !   / |   /  l_ /   i \_ ¡  \_   l_ /  !  / ||  /   i \_\n    .\  /\__|  /\____/__|  /_____/\____  /_|   /_____/\____/__!| /\____  /\n     \\/.  ¬l_/        ¬l_/          ¬\_/ ¬l__/ ^aRYAN^       :l/    ¬\_/\n      \/\n\n          -÷[ Sysop:CLAUDiA SCHiFFER ]÷-  -÷[ Hd Space .4GiG ]÷-\n \n           -÷[ 0-¹ Days Warez ]÷-  -÷[ No New User Password ]÷-\n \n    -÷[ Node1 +46(0)455-59060 ]÷-  -÷[ Supreme World HeadQuarter]÷-\n \n\nand leave a comment to mAd mOOse , with an extra space after the name!\n\n\n					/ mAd mOOse SiGNING oFF\n','\n',char(10)),NULL,'auto-added',11261,3,0,NULL,NULL,'sre_msdb','scan',1780048749);
INSERT INTO door_catalog VALUES('sre_mspw','SRE-MSPW.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SRE-MSPW.LHA',NULL,'XIM','-(·mAd mOOse Of·)-',NULL,NULL,'SRE','.____/\____/\_____/\   .÷. ¡  ____/   _ \_  .  \  :P÷ |____ \    ___/  i__/  ·r·',replace('  -(·mAd mOOse Of·)-\n.____/\____/\_____/\   .÷.\n¡  ____/   _ \_  .  \  :P÷\n|____ \    ___/  i__/  ·r·\n|   /  \_    \   ._)   ÷e·\n|  /    / |   \_ i \_  :s:\nl______/__|    /__  /  ·e.\n ^aRYAN^  l___/  \_/   ÷n:\n                       ·t÷\n  mAD sYSPW v 0.01b    :s:\n   fOR /X 2.x-4.x      `÷''\n','\n',char(10)),'mADsYSPW.doc',replace('      /\  /\  ___/\_____/\      /\  /\  ___/\  ___/\_____/\____/\\n     /  \/  \/  .  \      \    /  \/  \/     \/     \  ____/   . \_ _\n     |       \_ !   \_ |   \_  |       \_ ¡   \_ ¡   \___ \    i__/ /\n     |  ¡¡    / .    / |    /  |  ¡¡    / |    / |    / /  \_  ._)\n     |  ||   /  ¡   /  l_  /   |  ||   /  !   /  !   / /    /  i \_\n     l__||  /\__|  /______/    l__||  /\_____/\_____/______/____  /\n         l_/    l_/                l_/                  ^aRYAN^\_/\n\n			      P R E S E N T S\n	\n		      m A D  s Y S P W  v  0 . 0 1 b\n\n\nThis is the third door from me. This is a replacement for the\nbuilt in system password. This door will ask for the syspw\nand the user gets three tries and then a menu will be displayed.\nThen he can page the sysop, leave a comment to the sysop or just logoff.                                                                                                                            knullla\n\nThe door will first display a text names: mADsYSPW.txt\nAnd ofcourse can you edit this file to what you want.\n\nYou could''t also create a textfile called: mADsYSPW.menu\nBut the program already have a built in menu, but edit\nit like you want.\n\n		^^^ ACHTUNG ^^^\n\nDon''t forget to turn off the internal syspw, and\ndon''t forget to copy the BBSTitle.txt from this archive!\n\n		^^^ ACHTUNG ^^^\n\nAbout the config file\n---------------------\n\nThe first line should contain the password,\nthe second the prompt and\nthe third should be ON or OFF\nON = If you want the password to be casesensitive\nOFF = If you don''t want the password to be casesensitive\n\nThat should be it folks!\n\nIf you don''t know how to install a door then shutdown your bbs!\n\n\nTo report bugs or if you have any comments about the program or maybe\nsome ideas how to make it better (if possible) then call:\n\n            .     .                                         .\n            ¡\    ¡\                                        _\  .\n  ____/\  __| \___| \____/\____/\  ___/\_____/\____/\  __/\/ \\/_  ___/\\n_/   __ \/  |  \ ¬|  \  .  \   . \/   . \_   . \_    \/  . \  \/¬\/   . \_\n\____/¬  \_ !   \_|   \_¡   \_ ¡  \_  i__/   i  /  ¡  \_ ¡  \_..  \_  i__/\n    /     / .    /|    /|    / |   /  ._)  . __/   |   / |   /¡¡   /  ._)\n    \    /  ¡   / !   / |   /  l_ /   i \_ ¡  \_   l_ /  !  / ||  /   i \_\n    .\  /\__|  /\____/__|  /_____/\____  /_|   /_____/\____/__!| /\____  /\n     \\/.  ¬l_/        ¬l_/          ¬\_/ ¬l__/ ^aRYAN^       :l/    ¬\_/\n      \/\n\n          -÷[ Sysop:CLAUDiA SCHiFFER ]÷-  -÷[ Hd Space .4GiG ]÷-\n \n           -÷[ 0-¹ Days Warez ]÷-  -÷[ No New User Password ]÷-\n \n    -÷[ Node1 +46(0)455-59060 ]÷-  -÷[ Supreme World HeadQuarter]÷-\n \n\nand leave a comment to mAd mOOse , with an extra space after the name!\n\n\n					/ mAd mOOse SiGNING oFF\n','\n',char(10)),NULL,NULL,33588,2,0,NULL,NULL,NULL,'scan',1780048749);
INSERT INTO door_catalog VALUES('sre_oedc','SRE-OEDC.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SRE-OEDC.LHA',NULL,'XIM','exe.-l0S-eND0S-bBS-.exe',NULL,NULL,'SRE','.____/\__|\\/___/\___/\__/\___\/  ___/\    N ¡  ___/  | \/   _ \_ _ \_. \_ \/\/   . \_  E |___ \   |  \_  |  / ___/i__/    \   i__/  W',replace('         .   /  mAd mOOse oF \             ^\n.____/\__|\\/___/\___/\__/\___\/  ___/\    N\n¡  ___/  | \/   _ \_ _ \_. \_ \/\/   . \_  E\n|___ \   |  \_  |  / ___/i__/    \   i__/  W\n|  /  \_ |   /  __/   \  ._)  ¡¡  \_ ._)   ·\n| /    / !  /   |   ¡  \_i \_ ||   / i \_  U\nl_____/____/\___|\__|   /_  /_||  /___  /  P\n>------------^aRYAN^l__/-\_/---l_/--.\_/   D\nPRESENTS <--------------------------''      A\n         oNLiNE EDiT v 0.01c   (2.x - 4.x) T\nLet you cosysops edit textfiles online!    E\n  ·»» World Release at Thunder Dome ««·    ^\n','\n',char(10)),'oNLiNeEDiT.doc',replace('       /\  /\  ___/\_____/\      /\  /\  ___/\  ___/\_____/\____/\\n      /  \/  \/  .  \      \    /  \/  \/     \/     \  ____/   . \_ _\n      |       \_ !   \_ |   \_  |       \_ ¡   \_ ¡   \___ \    i__/ /\n      |  ¡¡    / .    / |    /  |  ¡¡    / |    / |    / /  \_  ._)\n      |  ||   /  ¡   /  l_  /   |  ||   /  !   /  !   / /    /  i \_\n      l__||  /\__|  /______/    l__||  /\_____/\_____/______/____  /\n          l_/    l_/                l_/                  ^aRYAN^\_/\n\n                              P R E S E N T S\n\n                    o N L i N e  E D i T  v  0 . 0 1 c\n\n\nThis is the fourth door from me. This is some kind of editor\nso that your cosysop(s) can edit files when they are online.\nIt might be useful for some people, I don''t know really!\n\n\nAbout the config file\n---------------------\n\nThe only thing this file should contain is the password!\nIf you don''t want to use a password then enter NOPASSWORD\non the first line.\n\n\nAbout the names file\n--------------------\n\nThe first should contain the number of users that should\nhave access to this door. If you don''t want the program to\ncheck the name, then enter NONAMES in the first line.\nOtherwise enter number of users. And the next lines\nshould contain the users. (»» CASE SENSITIVE ««)\n\nHistory\n-------\n\n0.01a - No public release\n0.01b - First public release\n0.01c - Added Edit Line, fixed so that the user can delete any line.\n        Also added so that you see the line number in the list command.\n        Fixed some cosmetic stuff.\n\n\nThat should be it folks!\n\nIf you don''t know how to install a door then shutdown your bbs!\n\n\nTo report bugs or if you have any comments about the program or maybe\nsome ideas how to make it better (if possible) then call:\n\n            .     .                                         .\n            ¡\    ¡\                                        _\  .\n  ____/\  __| \___| \____/\____/\  ___/\_____/\____/\  __/\/ \\/_  ___/\\n_/   __ \/  |  \ ¬|  \  .  \   . \/   . \_   . \_    \/  . \  \/¬\/   . \_\n\____/¬  \_ !   \_|   \_¡   \_ ¡  \_  i__/   i  /  ¡  \_ ¡  \_..  \_  i__/\n    /     / .    /|    /|    / |   /  ._)  . __/   |   / |   /¡¡   /  ._)\n    \    /  ¡   / !   / |   /  l_ /   i \_ ¡  \_   l_ /  !  / ||  /   i \_\n    .\  /\__|  /\____/__|  /_____/\____  /_|   /_____/\____/__!| /\____  /\n     \\/.  ¬l_/        ¬l_/          ¬\_/ ¬l__/ ^aRYAN^       :l/    ¬\_/\n      \/\n\n          -÷[ Sysop:CLAUDiA SCHiFFER ]÷-  -÷[ Hd Space .4GiG ]÷-\n \n           -÷[ 0-¹ Days Warez ]÷-  -÷[ No New User Password ]÷-\n \n    -÷[ Node1 +46(0)455-59060 ]÷-  -÷[ Supreme World HeadQuarter]÷-\n \n\nand leave a comment to mAd mOOse...\n\n					/ mAd mOOse SiGNING oFF\n','\n',char(10)),NULL,'auto-added',10946,5,0,NULL,NULL,'sre_oedc','scan',1780048749);
