INSERT INTO door_catalog VALUES('sre_pw1c','SRE-PW1C.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SRE-PW1C.LHA',NULL,'XIM','-(·mAd mOOse Of·)-',NULL,NULL,'SRE','.____/\____/\_____/\   .÷. ¡  ____/   _ \_  .  \  :P÷ |____ \    ___/  i__/  ·r·',replace('  -(·mAd mOOse Of·)-\n.____/\____/\_____/\   .÷.\n¡  ____/   _ \_  .  \  :P÷\n|____ \    ___/  i__/  ·r·\n|   /  \_    \   ._)   ÷e·\n|  /    / |   \_ i \_  :s:\nl______/__|    /__  /  ·e.\n ^aRYAN^  l___/  \_/   ÷n:\n                       ·t÷\n  mAD sYSPW v 0.01b    :s:\n   fOR /X 2.x-4.x      `÷''\n','\n',char(10)),'mADsYSPW.doc',replace('      /\  /\  ___/\_____/\      /\  /\  ___/\  ___/\_____/\____/\\n     /  \/  \/  .  \      \    /  \/  \/     \/     \  ____/   . \_ _\n     |       \_ !   \_ |   \_  |       \_ ¡   \_ ¡   \___ \    i__/ /\n     |  ¡¡    / .    / |    /  |  ¡¡    / |    / |    / /  \_  ._)\n     |  ||   /  ¡   /  l_  /   |  ||   /  !   /  !   / /    /  i \_\n     l__||  /\__|  /______/    l__||  /\_____/\_____/______/____  /\n         l_/    l_/                l_/                  ^aRYAN^\_/\n\n			      P R E S E N T S\n	\n		      m A D  s Y S P W  v  0 . 0 1 c\n\n\nThis is the third door from me. This is a replacement for the\nbuilt in system password. This door will ask for the syspw\nand the user gets three tries and then a menu will be displayed.\nThen he can page the sysop, leave a comment to the sysop or just logoff.                                                                                                                            knullla\n\nThe door will first display a text names: mADsYSPW.txt\nAnd ofcourse can you edit this file to what you want.\n\nYou could''t also create a textfile called: mADsYSPW.menu\nBut the program already have a built in menu, but edit\nit like you want.\n\n		^^^ ACHTUNG ^^^\n\n           Don''t forget to turn off the internal syspw, and\n        don''t forget to copy the BBSTitle.txt from this archive!\n> Another thing that you must NOT forget is that to disable quick logon!!! <\n                              ^^^\n		^^^ ACHTUNG ^^^\n\nAbout the config file\n---------------------\n\nThe first line should contain the password,\nthe second the prompt and\nthe third should be ON or OFF\nON = If you want the password to be casesensitive\nOFF = If you don''t want the password to be casesensitive\n\nThat should be it folks!\n\nIf you don''t know how to install a door then shutdown your bbs!\n\n\nHistory\n-------\n\n0.01a - No public release\n0.01b - Final release\n0.01c - Fixed a little bug!!! Now it should be ok. Added a little\n        extra program to easy delete the syspwfail text file.\n\n\nTo report bugs or if you have any comments about the program or maybe\nsome ideas how to make it better (if possible) then call:\n\n            .     .                                         .\n            ¡\    ¡\                                        _\  .\n  ____/\  __| \___| \____/\____/\  ___/\_____/\____/\  __/\/ \\/_  ___/\\n_/   __ \/  |  \ ¬|  \  .  \   . \/   . \_   . \_    \/  . \  \/¬\/   . \_\n\____/¬  \_ !   \_|   \_¡   \_ ¡  \_  i__/   i  /  ¡  \_ ¡  \_..  \_  i__/\n    /     / .    /|    /|    / |   /  ._)  . __/   |   / |   /¡¡   /  ._)\n    \    /  ¡   / !   / |   /  l_ /   i \_ ¡  \_   l_ /  !  / ||  /   i \_\n    .\  /\__|  /\____/__|  /_____/\____  /_|   /_____/\____/__!| /\____  /\n     \\/.  ¬l_/        ¬l_/          ¬\_/ ¬l__/ ^aRYAN^       :l/    ¬\_/\n      \/\n\n          -÷[ Sysop:CLAUDiA SCHiFFER ]÷-  -÷[ Hd Space .4GiG ]÷-\n \n           -÷[ 0-¹ Days Warez ]÷-  -÷[ No New User Password ]÷-\n \n    -÷[ Node1 +46(0)455-59060 ]÷-  -÷[ Supreme World HeadQuarter]÷-\n \n\nand leave a comment to mAd mOOse , with an extra space after the name!\n\n\n					/ mAd mOOse SiGNING oFF\n','\n',char(10)),NULL,NULL,10289,5,0,NULL,NULL,NULL,'scan',1780048749);
INSERT INTO door_catalog VALUES('sre_pw1d','SRE-PW1D.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SRE-PW1D.LHA',NULL,'XIM','-(·mAd mOOse Of·)-',NULL,NULL,'SRE','.____/\____/\_____/\   .÷. ¡  ____/   _ \_  .  \  :P÷ |____ \    ___/  i__/  ·r·',replace('  -(·mAd mOOse Of·)-\n.____/\____/\_____/\   .÷.\n¡  ____/   _ \_  .  \  :P÷\n|____ \    ___/  i__/  ·r·\n|   /  \_    \   ._)   ÷e·\n|  /    / |   \_ i \_  :s:\nl______/__|    /__  /  ·e.\n ^aRYAN^  l___/  \_/   ÷n:\n                       ·t÷\n  mAD sYSPW v 0.01d    :s:\n   fOR /X 2.x-4.x      `÷''\n','\n',char(10)),'mADsYSPW.doc',replace('      /\  /\  ___/\_____/\      /\  /\  ___/\  ___/\_____/\____/\\n     /  \/  \/  .  \      \    /  \/  \/     \/     \  ____/   . \_ _\n     |       \_ !   \_ |   \_  |       \_ ¡   \_ ¡   \___ \    i__/ /\n     |  ¡¡    / .    / |    /  |  ¡¡    / |    / |    / /  \_  ._)\n     |  ||   /  ¡   /  l_  /   |  ||   /  !   /  !   / /    /  i \_\n     l__||  /\__|  /______/    l__||  /\_____/\_____/______/____  /\n         l_/    l_/                l_/                  ^aRYAN^\_/\n\n			      P R E S E N T S\n	\n		      m A D  s Y S P W  v  0 . 0 1 b\n\n\nThis is the third door from me. This is a replacement for the\nbuilt in system password. This door will ask for the syspw\nand the user gets three tries and then a menu will be displayed.\nThen he can page the sysop, leave a comment to the sysop or just logoff.                                                                                                                            knullla\n\nThe door will first display a text names: mADsYSPW.txt\nAnd ofcourse can you edit this file to what you want.\n\nYou could''t also create a textfile called: mADsYSPW.menu\nBut the program already have a built in menu, but edit\nit like you want.\n\n		^^^ ACHTUNG ^^^\n\n           Don''t forget to turn off the internal syspw, and\n        don''t forget to copy the BBSTitle.txt from this archive!\n> Another thing that you must not forget is that to disable quick logon!!! <\n\n		^^^ ACHTUNG ^^^\n\nAbout the config file\n---------------------\n\nThe first line should contain the password,\nthe second the prompt and\nthe third should be ON or OFF\nON = If you want the password to be casesensitive\nOFF = If you don''t want the password to be casesensitive\n\nThat should be it folks!\n\nIf you don''t know how to install a door then shutdown your bbs!\n\n\nTo report bugs or if you have any comments about the program or maybe\nsome ideas how to make it better (if possible) then call:\n\n            .     .                                         .\n            ¡\    ¡\                                        _\  .\n  ____/\  __| \___| \____/\____/\  ___/\_____/\____/\  __/\/ \\/_  ___/\\n_/   __ \/  |  \ ¬|  \  .  \   . \/   . \_   . \_    \/  . \  \/¬\/   . \_\n\____/¬  \_ !   \_|   \_¡   \_ ¡  \_  i__/   i  /  ¡  \_ ¡  \_..  \_  i__/\n    /     / .    /|    /|    / |   /  ._)  . __/   |   / |   /¡¡   /  ._)\n    \    /  ¡   / !   / |   /  l_ /   i \_ ¡  \_   l_ /  !  / ||  /   i \_\n    .\  /\__|  /\____/__|  /_____/\____  /_|   /_____/\____/__!| /\____  /\n     \\/.  ¬l_/        ¬l_/          ¬\_/ ¬l__/ ^aRYAN^       :l/    ¬\_/\n      \/\n\n          -÷[ Sysop:CLAUDiA SCHiFFER ]÷-  -÷[ Hd Space .4GiG ]÷-\n \n           -÷[ 0-¹ Days Warez ]÷-  -÷[ No New User Password ]÷-\n \n    -÷[ Node1 +46(0)455-59060 ]÷-  -÷[ Supreme World HeadQuarter]÷-\n \n\nand leave a comment to mAd mOOse , with an extra space after the name!\n\n\n					/ mAd mOOse SiGNING oFF\n','\n',char(10)),NULL,NULL,16431,3,0,NULL,NULL,NULL,'scan',1780048749);
INSERT INTO door_catalog VALUES('sre_wall','SRE-WALL.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SRE-WALL.LHA',NULL,'XIM','-(· /)arkElf Of ·)-',NULL,NULL,'SRE','.____/\____/\_____/\   .÷. ¡  ____/   _ \_  .  \  :P÷ |____ \    ___/  i__/  ·r·',replace('  -(· /)arkElf Of ·)-\n.____/\____/\_____/\   .÷.\n¡  ____/   _ \_  .  \  :P÷\n|____ \    ___/  i__/  ·r·\n|   /  \_    \   ._)   ÷e·\n|  /    / |   \_ i \_  :s:\nl______/__|    /__  /  ·e.\n ^aRYAN^  l___/  \_/   ÷n:\n                       ·t÷\n     Wall v1.30        :s:\n   >FOR DD 1.00<       `÷''\n   ^^^^^^^^^^^^^\n','\n',char(10)),'mastrb8.txt',replace(replace('STILL GOING STRONG in 2014!\r\n\r\n                ___         ._            _______             ·\r\n   /\  _________)  \________| \___________)__   /_________:__ :________\r\n  /  \/\  __  \    ____ ___/|  \______  \_  / _/___  \_ ____/ ¦__ \___ \\r\n /   /  \ \__  \___  \  |   |   \  _/  __/ /    /\__  \  |¦   | /  \_|  \\r\n/  \/    \_ \   \ !   \_|   !    \_\    \_     /   \   \ ||   |·    /|   \_\r\n\___|     ___\  /__    /l________ /_\    /__  /_____\  / |¦   |    /_|    /\r\n    l____/-A×E\/  \___/_!       \/   \  /   \/       \/__|:   ¦__ /  l___/\r\n       ______            _____        \/      :    ____   ·   : \/\r\n    ___)     \___________)    \__________:___ ¦____)   \__________\r\n    \    _______     _______    \___    ____/ |\_____   \______   \\r\n   /\___   \/        |    _)    \/       ¦    |/    |    \    |    \\r\n _/    !    \        |    \      \_      |    |     !     \   |     \\r\n \______     \___    |_____\      /___   |    ¦            \  |      \_\r\n       \______/ \____!      \    /   \___|    :________     \_|       /\r\n                             \  /        ¦    ·       \______/|      /\r\n   YOUVE HEARD ABOUT IT!      \/         :    ·               l_____/\r\n       \r\n         MASTURBATiON STATiON AMIGA/PC/CONSOLE/ASCII-ANSI/C64        \r\n               Telnet: bbs.masturbationstationbbs.com\r\n\r\n        