INSERT INTO door_catalog VALUES('sr_cra10','SR_CRA10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SR_CRA10.LHA',NULL,'XIM','CreAcc!.x',NULL,'B/\Zz/SKID','SR','/  ____  |/  /  \__. \____  \/   \/  \|  _/ \__. \|  /  /\__/  |  \  /  /  |  \_ /\  | |  |  \  \  \|  |  |   \ \  \_ |   /     |',replace(' ________. ___/\____________  ___  /\ .____\n/  ____  |/  /  \__. \____  \/   \/  \|  _/\n\__. \|  /  /\__/  |  \  /  /  |  \_ /\  | \n|  |  \  \  \|  |  |   \ \  \_ |   /     | \n|_____/  |\__\  |______/ |\__/____/__/\  | \n+Mb---|__|---|__|-----|__|-[ -hOTC- ]--\_|+\n - CreAcc! - Online Account Creator v1.0\n - Fully Configurable ,User Friendly \n - Made By B/\Zz/SKID ROW \n','\n',char(10)),'HELP.TXT',replace('\n           wE GoT iT bEFoRE yOU!,bUT wHERES iT fROM.!\n              hMMMM!!! oF cOURSe....tHE mANSiON.\n \n               Time: 10:13:00  Date: 28-Jun-94\n','\n',char(10)),NULL,'auto-added',24327,9,0,NULL,NULL,'sr_cra10','scan',1780048749);
INSERT INTO door_catalog VALUES('sr_ex2_3','SR_EX2_3.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SR_EX2_3.LHA','Ex!_Task_2_000','XIM','Ex!_CreateSLog',NULL,NULL,'SR','7~~___/~7/_/|~|__~\7~__7|~~~7~||~| _|___ 7    \ | | 7  ) 7  | l | /\ | 7_____l__7__7l_l___/l_|ovl___l_/\_:',replace(' _________ ________ _______________\n 7~~___/~7/_/|~|__~\7~__7|~~~7~||~|\n_|___ 7    \ | | 7  ) 7  | l | /\ |\n7_____l__7__7l_l___/l_|ovl___l_/\_:\n   Exorcist! v3.0 FINAL RELEASE!\n     for /X v2.3x & S-Express','\n',char(10)),'Ex!_User.guide',replace('@DATABASE "Ex!_User.guide"\n\n@NODE Main "Exorcist! v3.0 - ©1993-1994 sKID rOW"\n---------------------------------------------------------------------------\n                                 EXORCIST!\n                             The File Expeller\n                                   v3.0\n\n                   (c) 1993-1994  CFi & B/\Zz of sKID rOW\n---------------------------------------------------------------------------\n\n	Table of contents:\n\n	@{" Preface     " link exug_1} Introduction to Exorcist!\n	@{" Actions     " link exug_2} The list of commandos in the main menu and what the mean\n	@{" Questions   " link exug_3} A list of questions asked and what they mean\n	@{" Enter files " link exug_4} How to enter files, including use of wildcards\n	@{" Editor      " link exug_5} How to use the full screen comment editor\n\n\n\n\n\n\n\n\n\n@ENDNODE\n\n@NODE exug_1 "Exorcist! v3.0 - Preface"\n\nEverybody who logs onto a BBS, knows that not all uploads are of\nsimilar nature. Sometimes users upload things that have already been\nuploaded. And sometimes users upload something of such value that he ought\nto get more than his standard ratio for it. Also it would be nice to make\nfiles free-download without much fuss. To solve all these problems and\nmore, we made Exorcist!\n\nExorcist! is a /X utility that gives you the ability to perform certain\noperations on uploaded files. Although the most of the operations Exorcist!\ncan perform are also available in other programs (eg NosNUKE or BossNUKE),\nExorcist! combines a high speed with a greatly enhanced functionality. \n\nSome of the extra features are:\n- Processing multiple files in a single session.\n- File selection using wildcards (if allowed by sysop).\n- Full Screen editor for file comments. WYSIWYG!\n- All actions are performed. 100% guaranteed! Due to some nasty details\n  in the design of /X not all utilities can guarantee this!\n- Automagically handles all filedir utilities without messing up\n  the filedir! (Exorcist! is the ONLY known utility to do this!)\n- Also featuring in this release is the full support of all new\n  /X v3.xx features, such as node relocation, CONF.DB accounting, etc\n\nAlthough getting the grips with Exorcist! will probably not be as easy as\nwith simpler utilities like NosNUKE or BossNUKE, its benefits will surely\nbe worth the effort.\n\nExorcist! has been written to finally get a fast and reliable program to\ndo all those things essential for running a good BBS, but which were\nformerly only possible with slow and non friendly programs. We hope you\nenjoy using Exorcist!!\n\n@ENDNODE\n\n@NODE exug_2 "Exorcist! v3.0 - Actions"\n\n1. [A]ward files\n	Award files lets you award 1-999 times EXTRA credits to the uploader.\n  You will not be able to award credits to yourself.\n\n2. [D]educt files\n	Deduct files lets you deduct 1-999 times credits from the uploader.\n  You will not be able to deduct credits from yourself.\n\n3. E[x]pell files\n  This is the nuke option. With this option you can nuke files that do\n  not belong on the BBS. You can nuke 1-999 times credits from the uploader\n  and if you want it, you can give the download credits back to the users\n  who downloaded the file.\n  Another possibility of this option is that it can create files. This means\n  that you can create a list of files to prevent some from uploading them.\n\n4. [R]esurrect files\n  This option will only be shown if the sysop decides that he needs a \n  safety net for the expell option. All expelled files are moved to a\n  storage directory. You can bring the files back from there to the\n  original dir, if the file wasn''t a fake afterall.\n\n5. Make files [F]ree download\n  This option let''s you make files free downloadable, and it lets you add\n  commentlines why you wanted it to be free downloadable.\n\n6. [C]omment files\n  Here you can add your own commentlines to a file.\n\n7. [E]dit filecomments\n  When you want to edit file comments, this is the option you need.\n  You can add any logo you like with a single key combination, as long\n  as the sysop provides them.\n\n8. Cross-conference file [m]oving\n  This option lets you move files from the current conference to any other\n  conference on the BBS. The files will be moved INCLUDING the filecomment.\n\n@ENDNODE\n\n@NODE exug_3 "Exorcist! v3.0 - Questions"\n\nQuestion : "Send messages to the uploaders (Y/n)? "\n  Here you are asked if the uploader(s) of the selected file(s) should be\n  sent a message containing actions performed by you. This option does\n  not have any effect on messages sent to the sysop!\n  Default is YES.\n\nQuestion : "Return credits to downloaders (y/N)? "\n  If you want to give back credits to users that have downloaded an\n  expelled file, then you should answer YES to this question.\n  Default is NO.\n\nQuestion : "Return download credits individually (y/N)? "\n  If you want to return credits for expelled files only to some users,\n  then you should answer YES here. If you answer YES, you will see\n  the stats of the user and the question if you want to return\n  credits to him.\n  Default is NO.\n  \nQuestion : "Send messages to the downloaders (Y/n)? "\n  Here you are asked if the downloader(s) of the selected file should be\n  sent a message containing actions performed by you. This option does\n  not have any effect on messages sent to the sysop!\n  Default is YES;\n\nQuestion : "Do you want to use small comments (Y/n)? "\n  If you answer YES here, the commentlines you can enter will start\n  at the same place as normal filecomments. Actions will be printed\n  using a compact style, which will be placed directly under the\n  filesize.\n  For NO you will have full comment lines and an extra line containing\n  an action string.\n  \nQuestion : "Do you want to add commentlines (Y/n)? "\n	If you answer NO here, Exorcist! will only perform the action given.\n  You will not be able to add any commentlines. All action strings/lines\n  created by the action are still appended. The main advantage of no\n  commentlines is that the editor is not started.\n\nQuestion : "Stay anonymous (y/N)? "\n  Here you are asked if you want to remain anonymous for the uploaders\n  and downloaders. You can not be anonymous for the sysop or the logfile.\n\n@ENDNODE\n\n@NODE exug_4 "Exorcist! v3.0 - Enter files"\n\nWhen entering files you will be prompted like this:\nEnter filespec(1): \n\nNow you can enter a filename. This file name may contain wildcards, if\nthe sysop allows them for you. You can just try if wildcards are allowed,\nwithout any consequences. Entering an empty line means that you don''t\nwant to enter more filenames.\n\nWildcards allowed:\n\n	?	Matches a single character.\n	#	Matches the following expression 0 or more times.\n	(ab|cd)	Matches any one of the items seperated by ''|''.\n	~	Negates the following expression.  It matches all strings\n		that do not match the expression (aka ~(foo) matches all\n		strings that are not exactly "foo").\n	[abc]	Character class: matches any of the characters in the class.\n	[~bc]	Character class: matches any of the characters not in the\n		class.\n	a-z	Character range (only within character classes). \n	%	Matches 0 characters always (useful in "(foo|bar|%)").\n	*	Synonym for "#?"\n\nAfter you have completed entering the filenames, you are asked to confirm\nall files you have selected. This is the last possibility to remove files\nyou do not want to process from the list!\n\n@ENDNODE\n\n@NODE exug_5 "Exorcist! v3.0 - Full screen editor"\n\nAs of this release Exorcist! uses a full screen editor for changing file\ncomments. We have tried to make the editor as intuitive as possible, so\nthat it will be easy to use it. The use of hotkeys for activating commands\nhas been chosen, so that the editing speed will be increased.\nThe only restriction for use with the editor is that you set number of lines\nto a number that is fully visible on your terminal!\n\nAvailable keys:\ncursor keys: You can use the cursor keys to move around the editor screen.\n           : The cursor will only move to areas that can be edited. This\n           : was done to prevent users accidently destroying the filedir.\n\nENTER      : Insert a new line.\n\nDEL        : Delete character under cursor.\n\nBACKSPC    : Delete character before cursor, and move cursor 1 char left.\n\nCTRL-J     : Center line, this will center any entered comment, including\n           : size comment.\n\nCTRL-R     : Remove line, this will delete a comment line if possible.\n           : Even when there are no comment lines left, you will stay\n           : in the editor. Pressing ENTER will add a newline.\n\nCTRL-O     : Toggles the editor between insert and overwrite modus\n\nCTRL-L     : This option will list the available standard comments for\n           : the position where the cursor is. This list includes the\n           : ID code that must be entered to insert a standard comment.\n\nCTRL-W     : This will prompt for an ID. After entering the ID, the\n           : standard comment is added, using overwrite or insert modus.\n\nCTRL-T     : Toggles the Exorcist! comment line size between large and\n           : small. This option is only available for large comments!\n\nCTRL-X     : Exit\n\nother keys : These keys have no special function, and will be placed in the\n           : file comment, this allows for logos,etc.. CTRL-keys will be\n           : filtered out!\n\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',94847,5,0,NULL,NULL,'sr_ex2_3','scan',1780048749);
INSERT INTO door_catalog VALUES('sr_ex3_3','SR_EX3_3.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SR_EX3_3.LHA','Ex!_CreateSLog','XIM','Ex!_CreateSLog',NULL,NULL,'SR','7~~___/~7/_/|~|__~\7~__7|~~~7~||~| _|___ 7    \ | | 7  ) 7  | l | /\ | 7_____l__7__7l_l___/l_|ovl___l_/\_:',replace(' _________ ________ _______________\n 7~~___/~7/_/|~|__~\7~__7|~~~7~||~|\n_|___ 7    \ | | 7  ) 7  | l | /\ |\n7_____l__7__7l_l___/l_|ovl___l_/\_:\n   Exorcist! v3.0 FINAL RELEASE!\n           for /X v3.xx\n','\n',char(10)),'Ex!_Sysop.guide',replace('@DATABASE "Ex!_Sysop.guide"\n\n@NODE Main "Exorcist! v3.0 - ©1993-1994 sKID rOW"\n---------------------------------------------------------------------------\n                                 EXORCIST!\n                             The File Expeller\n                                   v3.0\n\n                   (c) 1993-1994  CFi & B/\Zz of sKID rOW\n---------------------------------------------------------------------------\n\n	Table of contents:\n\n	@{" Preface     " link exsg_1} Introduction to Exorcist!\n	@{" Changes     " link exsg_2} Changes in v3.0 compared to v2.1\n	@{" Installing  " link exsg_3} How to get Exorcist! working on your system\n	@{" Configuring " link exsg_4} How to configure Exorcist! to your wishes\n	@{" Access/     " link exsg_5} How to give access to Exorcist! for /X v3.xx\n	@{" Contact     " link exsg_6} How to contact the authors\n	@{" Disclaimer  " link exsg_7} Read this!\n\n\n\n\n\n\n\n@ENDNODE\n\n@NODE exsg_1 "Exorcist! v3.0 - Preface"\n\nEverybody who owns or maintains a BBS, knows that not all uploads are of\nsimilar nature. Sometimes users upload things that have already been\nuploaded. And sometimes users upload something of such value that he ought\nto get more than his standard ratio for it. Also it would be nice to make\nfiles free-download without much fuss. To solve all these problems and more,\nwe made Exorcist!\n\nExorcist! is a /X utility that gives you the ability to perform certain\noperations on uploaded files. Although the most of the operations Exorcist!\ncan perform are also available in other programs (eg NosNUKE or BossNUKE),\nExorcist! combines a high speed with a greatly enhanced functionality. \n\nAlthough getting the grips with Exorcist! will probably not be as easy as\nwith simpler utilities like NosNUKE or BossNUKE, its benefits will surely\nbe worth the effort.\n\nExorcist! has been written to finally get a fast and reliable program to\ndo all those things essential for running a good BBS, but which were\nformerly only possible with slow and non friendly programs. We hope you\nenjoy using Exorcist!!\n\n@ENDNODE\n\n@NODE exsg_2 "Exorcist! v3.0 - Changes"\n\nThe new version 3.0 has several new major options compared to v2.1:\n\n- @{"Background task" link exsg_3_2}   : A background task was added to Exorcist!, to\n                      provide the service of performing all actions\n                      asked for, whether the resources for that action\n                      are available at that moment or not.\n- @{"Speedlog" link exsg_3_1}          : Exorcist! uses a fast uploader search algorithm \n                      using a special log. Under normal conditions\n                      uploaders will be found within 0.1 secs.\n- Comment editor    : Exorcist! now uses a full screen editor to add or\n                      edit comments in the filedir.\n- Edit file comment : Exorcist! gives you the possibility to edit the \n                      filecomments in the filedir.\n- Inter-conf moving : Exorcist! can move files (including comments) from\n                      one conference to another.\n- Fully configurable: Exorcist! comments and messages can be COMPLETELY edited \n                      to your wishes.\n- ASCII std comments: Exorcist! can read standard ascii files to use as default\n                      standard comments.\n- Improved filecmt  : Exorcist! now has the ability to handle any filedir\n                      utilities additions. Lines upto 160 chars and/or\n                      lines containing ANSI codes will be handled\n                      the right way.\n\nOther options are improved and bugfixed:\n\n- Exorcist! can now find uploaders who logged in the day before 0:00 and\n  uploaded their files after 0:00.\n- Major crash bug when searching uploaders and comments has been fixed.\n- Award command has been split in the award and deduct commands.\n- several small bugs were removed.\n\n@ENDNODE\n\n@NODE exsg_3 "Exorcist! v3.0 - Installing"\nHow to install Exorcist!:\n\nExorcist! uses a CBM Installer compatible install script.\nTo install Exorcist! just doubleclick the Install_Ex! icon in the\ndirectory to which Exorcist! was extracted.\n\nDuring the installation process some questions are asked:\n\n  - Select BBS directory          \n      Here you must select the directory in which your bbs is located.\n\n  - Select directory for Exorcist!\n      Here you must select an existing directory. Exorcist! will be\n      installed into this directory.\n\n  - Do you want to add Exorcist! to ... \n      If you select yes here, an entry will be added to the bbs.cmd file\n      or the BBSCmd dir, so that Exorcist! can be started from /X. It\n      is adviced to keep the access level as low as possible, since there\n      are better ways to give access to Exorcist!\n\n  - Do you want to install the @{"speedlog" link exsg_3_1}?\n      If you select yes here, the speedlog will be installed on your system.\n      The speedlog will be installed as the FRONTEND door, if your system\n      already contains a FRONTEND door, then this door should be renamed\n      to FRONTEND2, so that the speedlog door can automatically start it.\n\n  - Install the @{"background task" link exsg_3_2} permanently?\n      If you want to use the speedlog, you MUST install the background task\n      permanently. Otherwise you have the choice of installing the\n      background permanently, or having Exorcist! start the background task\n      at each use. Installing the background task permanently has the\n      advantage that Exorcist! will startup much faster!\n\n@ENDNODE\n\n@NODE exsg_3_1 "What is the speedlog?"\n\nThe speedlog is a new feature for this release, and has been added to\nExorcist! to improve the search speed for uploaders and downloaders\neven more. The only way to use speedlog is to install it via the\ninstaller script of Exorcist!.\n\nThe speedlog consists of a file called ''Ex!_SpeedLog'' and a door called\n''Ex!_UpdateSLog.x'' both are in the directory where Exorcist! is located.\nThe Ex!_UpdateSLog.x door is automaticaly executed when a user logs in,\nand will transparently update the speedlog, without the online user\nnoticing anything.\n\nThe speedlog will be kept in RAM during the time that Ex!_Task is active,\nso that the maximum search speed can be obtained. The one minor\ndisadvantage of speedlog is that you will have to spend 16KB memory to\nkeep the speedlog in memory.\n\nA speed indication: on a system with a normal taskload, Exorcist! will\nbe able to find uploaders/downloaders within 0.1 sec out of the speedlog.\n\nNOTE for users of speedlog: \n  Due to the fact that /X will not execute the FRONTEND door when\n  a sysop login (F1) is performed, you may not perform a sysop login\n  on any node where uploads and/or downloads take place. It is adviced\n  the use a special private sysop node for this, and remember that on\n  this node no uploading or downloading may take place.\n\n@ENDNODE\n\n@NODE exsg_3_2 "What is the background task?"\n\nThe background task was added to Exorcist! because in previous releases\nof Exorcist! problems with updating user records and mailheaders appeared.\n\nTo get rid of these problems the background task was introduced. The\nbackground task is a small program that runs at priority 0, so that it will\nnot take away any processor time from /X.\n\nWhen there is any time left on the system, and the needed resources are\navailable, the background task will perform all changes that are needed due\nto actions performed in Exorcist! The one huge advantage over previous\nversions of Exorcist! is the fact that ANY action you specify will ALWAYS\nbe performed!\n\nDue to the nature of the amiga operating system, it can be possible that the\nbackground task will perform actions several seconds/minutes after you''ve\nfinished using Exorcist!. It also can happen that the background task will\nbe retrying a certain until it finally succeeds. This can result in activity\non your harddisk when you don''t expect it. This is normal, NOT a bug. So\ndon''t be surprised:-)\n\n@ENDNODE\n\n@NODE exsg_4 "Exorcist! v3.0 - Configuring"\n\nStarting with this revision, Exorcist! will use the ini.library for\nprocessing its configuration file called ''Exorcist!.ini''. Due to a bug\nin ini.library the Exorcist!.ini file must exist in the same directory\nas Exorcist!, or else an endless loop will occur.\n\nThe format of the Exorcist!.ini file is as followed. The file is a normal\nASCII file, and the only demand is that the file starts with '';INI''.\n\nFurthermore the file consist of sections, which start which the section\nname between [ ] brackets (eg. [Paths]). Each section can contain multiple\nvariables, of which none is needed, Exorcist! will run OK, even if you have\na completely empty Exorcist!.ini file.\n\nEach variable is placed on one line. There cannot be more than one variable\non a line! The format for the variable line is <varname>=<value>, where you\nmay not place white spaces between the <varname> and the ''='', or between the\n''='' and the <value>.\n\nIf a line starts with '';'' or ''*'' it is considered a commentline. \nif you use a '';'' on a normal line, then the rest of that line is considered\nto be a comment. Although it is not needed, it is best to place the <value>\ninbetween ''"'' signs, if it is a string, to make sure that no unwanted spaces\nare included in the <value> string.\n\nExample:\n\n[Paths]\nStats="BBS:Ex!_Stats"                 ;this is the path to the stats file\n\n\n	Possible Sections:\n\n	@{"[ActionStrings]" link exsg_4_1} The action strings placed in the filedir\n	@{"[Comments]     " link exsg_4_2} Options for added commentlines\n	@{"[Levels]       " link exsg_4_3} Access levels for actions (for /X v2.3x only)\n	@{"[Messages]     " link exsg_4_4} Options and layout for messages send\n	@{"[Misc]         " link exsg_4_5} Miscellaneous options\n	@{"[Paths]        " link exsg_4_6} Paths to important files\n\n@ENDNODE\n\n@NODE exsg_4_1 "Configuring - ActionStrings"\n@TOC exsg_4\n\nPossible variables are:\n\nAward_L     : This string defines the action string for awarding when using\n              large comments. use %d for times credits.\n\nDeduct_L    : This string defines the action string for deducting when using\n              large comments. use %d for times credits.\n\nExpell_L    : This string defines the action string for expelling when using\n              large comments. use %d for times credits.\n\nFree_L      : This string defines the action string used when a file is made\n              free downloadable using large comments.\n\nResurrect_L : This string defines the action string used when a file is\n              resurrected using large comments.\n\n\nFree_S      : This string defines the action string used when a file is made\n              free downloadable using small comments. (max 14 chars)\n\nResurrect_S : This string defines the action string used when a file is\n              resurrected using small comments. (max 14 chars)\n\n@ENDNODE\n\n@NODE exsg_4_2 "Configuring - Comments"\n@TOC exsg_4\n\nLineStart   : This is the string that is placed at the beginning of each\n              Exorcist! commentline to identify it as an Exorcist! comment\n              line. You may NOT use an empty string here!\n\nLineEnd     : This is the string that is placed at the end of each\n              Exorcist! commentline to identify it as an Exorcist! comment\n              line. You may NOT use an empty string here!\n\nSmallCmt    : This specifies if smallcomments may be used.\n              specify "YES" if all added comments should be small comments.\n              specify "NO"  if all added comments should be large comments.\n              specify "ASK" if you want to let the user choose.\n\nStripCmt    : This specifies if Exorcist! commentlines must be removed when\n              resurrecting files. Specify YES or NO. Note that this option\n              will not work when you want to remove commentlines which have\n              other LineEnds than the current LineEnd.\n\nMaxCmtLines : This specifies the maximum number of Exorcist! commentlines\n              that may be added. 0 to 8 are valid.\n\n@ENDNODE\n\n@NODE exsg_4_3 "Configuring - Levels"\n@TOC exsg_4\n\nAward     : This specifies the level needed to award files.\n            Valid range = 0-255.\n\nComment   : This specifies the level needed to comment files.\n            Valid range = 0-255.\n\nDeduct    : This specifies the level needed to deduct files.\n            Valid range = 0-255.\n\nEditCmt   : This specifies the level needed to edit filecomments.\n            Valid range = 0-255.\n\nExpell    : This specifies the level needed to expell files.\n            Valid range = 0-255.\n\nFree      : This specifies the level needed to make files freedownload.\n            Valid range = 0-255.\n\nMoveFiles : This specifies the level needed to use the file mover.\n            Valid range = 0-255.\n\nResurrect : This specifies the level needed to resurrect files.\n            Valid range = 0-255.\n\n\nAnonymous : This specifies the level needed to stay anonymous.\n            Valid range = 0-255.\n\nWildcard  : This specifies the level needed to use wildcard.\n            Valid range = 0-255.\n\n@ENDNODE\n\n@NODE exsg_4_4 "Configuring - Messages"\n@TOC exsg_4\n\nUploader         : Send a message to the uploader(s) of the file(s).\n                   Valid are "YES", "NO" and "ASK".\n\nDownloader       : Send a message to the downloader(s) of a file.\n                   Valid are "YES", "NO" and "ASK".\n\nSysop            : Send a duplicate of each message to the sysop.\n                   Valid are "YES" and "NO". \n\nPublic           : Make the messages that are sent public.\n                   Valid are "YES" and "NO". \n\n\nAnonymous        : String placed in the sender field when the user wants\n                   to remain anonymous.\n\nSubject          : String placed in the subject field.\n\nHeader           : Header string for the message. %s is the action.\n                   Max length = 1024.\n\nAction_Award     : Actionstring for awarded files.\n                   Max length = 30.\n\nAction_Comment   : Actionstring for commented files.\n                   Max length = 30.\n\nAction_Create    : Actionstring for created files.\n                   Max length = 30.\n\nAction_Deduct    : Actionstring for deducted credits.\n                   Max length = 30.\n\nAction_Edit      : Actionstring for edited file comments.\n                   Max length = 30.\n\nAction_Expell    : Actionstring for expelled files.\n                   Max length = 30.\n\nAction_Free      : Actionstring for files made freedownloadable.\n                   Max length = 30.\n\nAction_Move      : Actionstring for for moved files.\n                   Max length = 30.\n\nAction_Resurrect : Actionstring for resurrected files.\n                   Max length = 30.\n\nAction_Return    : Actionstring for returned credits.\n                   Max length = 30.\n\nFiles            : String used for each file. max length = 256\n                 : Valid format codes are:                   length\n                 : %FN = FileName                             (12)\n                 : %FS = FileSize                             ( 7)\n                 : %FC = FileComment                          (??)\n                 : %SC = SizeComment                          (10)\n                 : %TI = Times awarded or deducted            ( 3)\n                 : %TO = Total bytes (= FileSize * Times)     (10)\n                 : %BT = Byte Type (= "u/l" or "d/l")         ( 3)\n                 : %AC = Action (= "given" or "taken")        ( 5)\n\nFiles_NoTotal    : String used for each file. max length = 256\n                 : This string is used when no user credits are added or\n                 : deducted. Valid format codes are:\n                 : %FN,%FS,%FC,%SC are allowed\n\nResult           : String used to terminate the message.\n                 : Max length = 1024.\n                 : valid format codes are:                   length\n                 : %PB = Previous bytes                       (10)\n                 : %PF = Previous files                       ( 5)\n                 : %CB = Current bytes                        (10)\n                 : %CF = Current files                        ( 5)\n                 : %TB = Total bytes                          (10)\n                 : %TF = Total files                          ( 5)\n                 : %TY = Type (= "uploaded" or "downloaded")  (10)\n                 : %BT = Byte Type (= "u/l" or "d/l")         ( 3)\n                 : %AC = Action (= "given" or "taken")        ( 5)\n\nResult_NoTotal   : String used to terminate the message.\n                 : This string is used when no user credits are added or\n                 : deducted. No format codes are allowed!\n\n@ENDNODE\n\n@NODE exsg_4_5 "Configuring - Misc"\n@TOC exsg_4\n\nKeepLog             : This option enables the Ex!_Log in each conference\n                    : directory. In this log all actions performed in\n                    : Exorcist! will be noted.\n                    : Valid are "YES" and "NO".\n\nKeepStats           : This option enables the stats file for statistics\n                    : about how often users were expelled, awarded\n                    : or deducted.\n                    : The format of the stats file is public, so that\n                    : other utilities can make use of it.\n                    : The format is for each user is:\n                    :\n                    : struct  Ex_Stats\n                    :   {\n                    :   ULONG Award_Bytes;\n                    :   ULONG Deduct_Bytes;\n                    :   ULONG Expell_Bytes;\n                    :   UWORD Award_Files;\n                    :   UWORD Deduct_Files;\n                    :   UWORD Expell_Files;\n                    :   };\n                    :\n                    : The file consist of a number of these structures\n                    : packed back to back. Accessing of a certain user\n                    : means:\n                    : Search(File,(UserSlot-1)*sizeof(struct Ex_Stats),\n                    :        OFFSET_BEGINNING);\n\nIndividualReturning : This option allows individual returning of credits\n                    : to downloaders.\n                    : "YES" means that individual returning will always be on.\n                    : "NO"  means that individual returning is not possible.\n                    : "ASK" lets the user decide which option to use.\n\n@ENDNODE\n\n@NODE exsg_4_6 "Configuring - Paths"\n@TOC exsg_4\n\nAcp       : Path to acp.info. Must end with '':'' or ''/'' (for /X v3.xx only)\n\nUserData  : Path to user.data. Must include the filename (for /X v2.3x only)\n\nStats     : Path to file containing the Exorcist! stats. Make sure\n          : that this file is also accessible for other utils.\n          : Must include the filename.\n\nResurrect : Path to directory where expelled files will go.\n          : Must end with '':'' or ''/''.\n          : NOTE: if you remove this entry, Resurrect will be disabled,\n          :       and all files you expell are deleted instead of moved!\n\nAwardCmt  : Path to file containing standard award comments.\n          : Must include the filename.\n\nDeductCmt : Path to file containing standard deduct comments.\n          : Must include the filename.\n\nExpellCmt : Path to file containing standard expell comments.\n          : Must include the filename.\n\nLogosCmt  : Path to file containing standard logos.\n          : Must include the filename.\n\nSizeCmt   : Path to file containing standard size comments.\n          : Must include the filename.\n\nThe format of the standard comment files is as follows:\n\nEach line means a standard commentline.\nIf a line starts with '';'' then that line is considered to be a commentline.\nIf a line starts with ''@'' then that line is considered to be an ID-line.\nThis ID will be used in the editor to select the commentline that follows\nthe ID line.\nIf a line ends with ''@'' then this line will be linked with the next\nline into a multi-line standard comment.\n\nexample:\n\n;This is a commentline\nstandard comment #1\n\@ID\nstandard comment #2a@\nstandard comment #2b\n\n@ENDNODE\n\n@NODE exsg_5 "Exorcist! v3.0 - Access for /X v3.xx"\n\nExorcist! for /X v3.xx makes use of the standard access system as\ndescribed in the /X docs. The new tooltypes that can be added are:\n\n  - EX!.AWARD     : Let the user award credits to other users\n  - EX!.COMMENT   : Let the user comment files\n  - EX!.DEDUCT    : Let the user deduct credits from other users\n  - EX!.EDITCMT   : Let the user edit file comments\n  - EX!.EXPELL    : Let the user expell files\n  - EX!.FREE      : Let the user make files free download\n  - EX!.MOVEFILE  : Let the user do cross conference file moving\n  - EX!.RESURRECT : Let the user resurrect files\n  - EX!.ANONYMOUS : Let the user perform his actions anonymously\n  - EX!.WILDCARD  : Let the user use wildcards when selecting files\n\nJust add these to the .info for a level or a single person, so that\nExorcist! can determine which users have access.\n\n@ENDNODE\n\n\n@NODE exsg_6 "Exorcist! v3.0 - Contacting the authors"\n\nYou can contact us (CFi and B/\Zz) at:\n\n     Write to:\n     P.O. Box 11023\n     7502 LA ENSCHEDE\n     HOLLAND\n\n     Or leave mail at:\n     DoomBase  (sKIDrOW hOLLAND)\n       +31-10-2731172\n       +31-10-2731825\n     tHE sCORE (sKIDrOW hOLLAND)\n       +31-0575-044-471\n     /X-NetMail:\n     Eclipse DHQ@NL0002\n\n@ENDNODE\n\n@NODE exsg_7 "Exorcist! v3.0 - Disclaimer"\n\nDisclaimer:\n\nUse this software at your own risk. The authors will not be liable for\nany damage arising from the failure of this program to perform as described,\nor any destruction of other programs or data residing on a system\nattempting to run the program. While no damaging errors are known, the\nuser of this program uses it at his or her own risk.\nYou may spread the original, unchanged archive for non-commercial purposes.\nPD companies may not spread this product for anything more than the actual\ncopying costs, and only with written permission of one of the authors.\n\nThis program is GiftWare!\nIf you use this program often, a gift would be appreciated by the @{"authors" link exsg_6}!\n\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',96886,6,0,NULL,NULL,'sr_ex3_3','scan',1780048749);
INSERT INTO door_catalog VALUES('sr_fc099','SR_FC099.LZX','~/Code/amiexpress_doors/Archives/AmiExpress/SR_FC099.LZX',NULL,'XIM','FiLECOMMENT',NULL,NULL,'SR',NULL,NULL,NULL,NULL,NULL,'auto-added',10655,0,0,NULL,NULL,'sr_fc099','scan',1780048749);
INSERT INTO door_catalog VALUES('sr_inq14','SR_INQ14.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SR_INQ14.LHA','inquirer','XIM','exe.-l0S-eND0S-bBS-.exe',NULL,'PhARAOh/SR','SR','\// ___/ | _/ |___ \   / __/ ___/ |_| \\/ 9 _\__  \ _ \  |  |  \ /  |/  |  \ | | /   9 \_____/_| /__|_____/ \__|\_____/____/    4',replace(' __ _____/|___/|____     /\_________ |\ __ 1\n \// ___/ | _/ |___ \   / __/ ___/ |_| \\/ 9\n  _\__  \ _ \  |  |  \ /  |/  |  \ | | /   9\n  \_____/_| /__|_____/ \__|\_____/____/    4\n----------|/-[ /X UTILITIES DIVISION ]------\n    NEW USER INQUIRER V1.4 By PhARAOh/SR\n--------------------------------------------\n','\n',char(10)),'inquirer.guide',replace('@database inquirer.guide\n\n@node Main "NeW USeR INQUiReR V1.4 By PhARAOh/SR (AIM)"\n\n-----------------------------------------------------------------------------\n\n                    NEW USER iNQUiRER V1.4 By PhARAOh/SR\n\n-----------------------------------------------------------------------------\n\n                    @{"Introduction" link introduction}\n\n                    @{"Installation" link installation}\n\n                    @{"History" link history}\n\n                    @{"Greetings" link greetings}\n\n                    @{"Contact" link contact}\n\n                    @{"Skid Row HQs" link skidrow}\n\n@endnode\n\n@node Introduction "NeW USeR INQUiReR V1.4 - INTRoDUCTiON"\n\n-----------------------------------------------------------------------------\n\n                    NEW USER iNQUiRER V1.4 By PhARAOh/SR\n\n-----------------------------------------------------------------------------\n\nI really had no intention of writing such a door until OLDMAN of THE HOLE\nBBS approached me with an idea of a NEW USER BULLETIN door, and shortly\nafter FIREFLASH of THE TOWER UK BBS came up with his brilliant idea...\n\nNeW USeR INQUiReR is an AMiEXPRESS door which BROADCASTS an EALL message\nfrom the sysop to REPORT a new user/applicant.  All users who have access to\nthe specified conference will be able to respond to your message inquiring\nabout the new user.\n\nPhARAOh/SR\n\n@endnode\n\n@node installation "NeW USeR INQUiReR V1.4 - INSTALLATiON"\n\n-----------------------------------------------------------------------------\n\n                    NEW USER iNQUiRER V1.4 By PhARAOh/SR\n\n-----------------------------------------------------------------------------\n\nBasically STANDARD Door installation.  Included is the door in the proper\ndirectory and the icon for launching the door (if you are still not running\nAmiExpress V3.xx, go shoot yourself!).  \n\n1.  Move the included INQUIRER subdirectory and its contents into your\nBBS:DOORS (DOORS:) directory.  Move NEW.info into your BBS:COMMANDS/BBSCMD/\nsubdirectory.\n\n2.  Move the included S:INQUIRER.CONFIG to your S:  directory.\n\n3.  Edit S:INQUiRER.CONFIG to contain the proper conference pathname where\nyou want the EALL messages sent.\n\n4.  Here is the RATHER complicated part of the installation.  Add the\nfollowing lines to your JOINED.TXT in all your NODE sub-directories.  you\nMUST start the text file with the symbol ''~'' at the top left hand corner.\nNow add to the bottom of the text the following:\n\n-----------CUT HERE---------\n~CC_NEW|\n-----------CUT HERE---------\n\nand your''re done..\n\nNOTE:  if you have an access level higher than 10 and attempt to run the\ndoor, it will simply abort...this is a simple safekeep mechanism so that\nregular members and sysops do not accidentally type NEW and broadcast a\nrather embarrasing message, unless you consider it humourous!?\n\n@endnode\n\n@node history "NeW USeR INQUiReR V1.4 - HiSTORY"\n-----------------------------------------------------------------------------\n\n                    NEW USER iNQUiRER V1.4 By PhARAOh/SR\n\n-----------------------------------------------------------------------------\n\nV1.o    first attempt at it...major bugs!\nV1.1    added location detection\nV1.2    added ansi and bbsname detection\nV1.3    added safekeep for access levels higher than 10\nV1.4    changed text format, and added S:config\n\nNOTE: Many thanks to OLDMAN and FIREFLASH for BETA-TESTING the door.\n\n@endnode\n\n@node greetings "NeW USeR INQUiReR V1.4 - GReeTiNGS"\n\n-----------------------------------------------------------------------------\n\n                    NEW USER iNQUiRER V1.4 By PhARAOh/SR\n\n-----------------------------------------------------------------------------\n\nThis is in NO WAY in any particular order, just as I remember the names.\n\nTriaXal!        - My UK pal...what the hell do you look like?\nDeViouS DoZE    - You''re the ''Spectrum'' of my life!\nDataStream      - Organizer you are m8..keep up the good werk..!\nZandor-SR       - Welcome to SR - good work with the runners..!\nOldMan          - Are you REALLY that old?\nFireFlash       - B.Y.O.C...Buy your OWN condom/BBS...that is what happens\n                  when you use others..(smirk!)\nMajor Theft     - Hope you get those problem sorted out.\nFallen Angel    - Silent you are...!\n\n@endnode\n\n@node skidrow "NeW USeR INQUiReR V1.4 - SKiD RoW"\n\n                               |_______                         \n            ___________________|      //\___________________    \n            \      ______/     |     /(________)__________  \   \n            /\______     \          / /        \         /   \  \n           /       /      \        /\/          \_      /     \ \n         _/       /        \_  |     \           /     /       \_\n         \__________________/__|      \_________/_______________/\n                               |_______/RpD!     :              \n               ______________  __________  _____/|:______       \n               \________     \/          \/      ||      \      \n               /       /     /       \    \      ||       \     \n              /       /_____/         \    \_    /\        \    \n            _/      _      \_        _/     /               \_  \n            \_______/       /______________/_____/\__________/  \n                   /_______/                                    \n\n                      SKiD ROW WORLD WiDE HEADQUARTERS\n---------------------------------------------------------------------------\nThe Inquisition..........805-683-1087 The Hole.................419-899-2754\nCyBorg Command...........206-438-9037 DarkStar.................519-255-1073\nBeyond Akira.............416-461-9101 The Tower...............44 204-382612\nHustlers Haven...........215-324-6918 Spellbound...............46 184-63380\nLast Desire..............32 897-53737 Universe................49 421-415197\n\n@endnode\n\n@node contact "NeW USeR INQUiReR V1.4 - Contact"\n\n\n\n\n\n\n\n\n\n\n\n                  YOU MAY CONTACT ME AT ONE OF THESE SITES\n\n-----------------------------------------------------------------------------\n                BEYOND AKiRA +1 416 461-9101 (4 NODES) SR CHQ\n\n              UNLAWFUL ENTRY + 1 612 755 1347 (10 NODES) SR WHQ\n-----------------------------------------------------------------------------\n\n                    PhARAOh/SR (BEYOND AKIRA MANAGEMENT)\n\n\n\n\n\n\n\n\n@endnode\n','\n',char(10)),NULL,'auto-added',14688,5,0,NULL,NULL,'sr_inq14','scan',1780048749);
INSERT INTO door_catalog VALUES('sr_mc12','SR_MC12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SR_MC12.LHA','MFM-Comment','XIM','MFM-Comment',NULL,'MFM/SR','SR','/  ___/  /  /  / _  \  __ \     \  \ \ \ /\__  /    _/  /  /  /\    ¯\  \  \  \ \ \ /_____/__/__/__/_____//\\__\__\_____\______\',replace('   /\__________________________________/\\n  /  ___/  /  /  / _  \  __ \     \  \ \ \\n /\__  /    _/  /  /  /\    ¯\  \  \  \ \ \\n/_____/__/__/__/_____//\\__\__\_____\______\\n\_____\__\__\__\_____\__/__/__/_____/______/\n|SdN/e^d      p.r.e.s.e.n.t.s              |\n|-------- -- ----------- -- ----------- ---|\n|   /X  MFM-Comment v1.2 - By MFM/SR  /X   |\n|   Fast and goodlooking /X ''C'' command!   |\n`------------------------------------------''\n','\n',char(10)),'MFM-Comment.doc',replace('\n               __/\__:__/:/\ :_/\ _/\__:/\_____/\______/\_\n               \    ¬:   |  \:   Y   ¬\:  _ ¬\  _ _/  /  /\n                \ l____  l _/_   |___  \  l _/  |  \ /\  \\n                /\_ ¬\|  _  \/_  |~ |   \_   \__l   \  \  \\n               /  l   \  \    /  |  ''   / \    /    /     /\n               \_____ /__l\  /___l____ /__l\  /___ /_/\_NeB\n               =====\/=====\/========\/=====\/===\/========\n\n   This time we present ''MFM-Comment v1.2'' for AmiExpress, Coded by MFM!\n\n                          (c)1994 MFM/SR^iPl^bTd\n\n                ------------------------------------------\n\n  >> Purpose:\n\n  This is a comment-door for /X and I suppose that you know how a comment-\n  door works!\n\n  >> Features:\n\n  · Fast\n  · Good Looking\n  · Auto Configuration\n  · Built in Configuration Editor\n  · Small code size\n  · It DOESN''T got a comment-counter :-) (Hi SiL)\n  · Built in check so that lamers can''t modify code/credits/version\n  · NO backdoors (Get it at an SR HQ/DIST to be 200% sure of no\n                  backdoors)\n  · Etc!\n\n  >> What''s new since version 1.0?\n\n  The field for sysop comment is expanded from 39 to 53 characters!\n\n  >> Sample output (WITHOUT fancy colors):\n\n.------------------------------------------------------------------------------.\n| [=] MFM-Cømment v1.2 [=] (c)1994 by MFM / SKiD ROW! [=] MFM-Cømment v1.2 [=] |\n+----------------------+-------------------------------------------------------+\n| 1 MFM                | Ruler of it all!                                      |\n| 2 Rolemaster         | Some kind of cosysop                                  |\n| 3 The Silencer       | Mascot!                                               |\n`------------------------------------------------------------------------------''\n\nEnter the number of the sysop you want to write to:\n\n  >> How to install:\n\n  Copy BBSCmd/C.Info to BBS:Commands/BBSCmd/C.Info\n  Copy Doors/MFM-Comment to BBS:Doors/MFM-Comment\n  Copy Libs/AEDoor.library to Libs:AEDoor.library\n\n  And MFM-Comment v1.2 is installed!\n\n  >> How to configure mfm-comment:\n\n  When you have installed MFM-Comment just load /X, login as sysop and\n  enter "C", this will start the configuration editor automagically! It\n  will look like this:\n\n                        ---------------------------\n\n  Some Board [1:NEW USERS] Menu (99997 mins. left): C\n  \n  Instructions for configure-mode!\n  ································\n  Enter all sysops/comments when prompted and then a configfile will\n  be automagically created! Max length for (co)sysop name is 18 chars\n  and 53 for (co)sysop comments. And the first name MUST be the sysops\n  because of logical reasons (See DOC). To cancel configuration\n  creation press enter on the "How many..." prompt.\n\n  How many sysops AND cosysops : 2\n  Sysop/CoSysop name: MFM\n  Comment           : System Operator\n  Sysop/CoSysop name: Rolemaster\n  Comment           : Amiga/Hacking\n  Configuration completed and saved!\n\n                        ---------------------------\n\n  Quite selfexplaining I think... The name of the config-file will be\n  "BBS:MFM-c.cfg" and the configuration editor will be started automagically\n  if this file doesn''t exist AND you got sysop access (255) (it will always\n  check that you have sysop access). You MUST enter the main sysop''s name\n  as the first name, as the door uses the internal C command instead of E for\n  the first sysop because C usually got lower access-level then E(Many LAME\n  comment-doors always uses E). To start the configuration editor even\n  when the config exists enter "C -c". You can also edit the config file\n  with any texteditor such as CygnusEd 3.5,  and it''s structure is exactly\n  the same as when you entered it in the built-in editor:\n\n  2                        <-- Number of sysops\n  MFM                      <-- First sysop''s name       \n  Ruler of the world       <-- Comment for first sysop\n  ROLEMASTER               <-- Second sysop''s name\n  Amiga, PC & Hacking      <-- Comment for second sysop\n\n  ## Easy eh?\n\n  >> Notes:\n\n  Sorry for lousy docfile but I *HATE* making docs and it was made in\n  a hurry...\n\n  >> How to contact the author:\n\n                  Post a message to MFM at these systems:\n\n    ++1-IT''S-OFF-LiNE  THE HOLE          (SKiD ROW USHQ)  (INVITE ONLY!)\n    ++1-IT''S-PRi-VATE  CHAOTiC ENTiTY    (iNTERPOL WHQ)   (NO NUP)\n    ++1-IT''S-PRi-VATE  COMPLEX CORROSiON (DCS WHQ)        (INVITE ONLY)\n    +46-26-124467      iNFiNiTE LiNK     (BETRAYED SHQ)   (NUP: IWILLUL)\n\n                       Or some other cool us-boards!\n\n','\n',char(10)),NULL,'auto-added',17810,3,0,NULL,NULL,'btd_mc10','scan',1780048749);
INSERT INTO door_catalog VALUES('sr_who_1','SR_WHO!1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SR_WHO!1.LHA',NULL,'XIM','sonnencreme.exe',NULL,NULL,'SR','\// ___/ | _/ |___ \   / __/ ___/ |_| \\/ 9 _\__  \ _ \  |  |  \ /  |/  |  \ | | /   9 \_____/_| /__|_____/ \__|\_____/____/    4',replace(' __ _____/|___/|____     /\_________ |\ __ 1\n \// ___/ | _/ |___ \   / __/ ___/ |_| \\/ 9\n  _\__  \ _ \  |  |  \ /  |/  |  \ | | /   9\n  \_____/_| /__|_____/ \__|\_____/____/    4\n----------|/-[ /X UTILITIES DIVISION ]------\n  WHO! - FULL CONFIGURABLE NODEVIEWER V1.0\n','\n',char(10)),'Who!.guide',replace('@database who!.guide\n\n@node Main "Who! - nodeviewer for AmiExpress"\n\n\n---------------------------------------------------------------------------\n                                   WHO!\n                         nodeviewer for AmiExpress\n                           v1.0 by B/\\Zz/Skidrow\n---------------------------------------------------------------------------\n\n                           @{" Introduction   " link introduction}\n                           @{" Installation   " link installation}\n                           @{" Configuring    " link configuration}\n                           @{" Online Options " link options}\n                           @{" Disclaimer     " link important}\n                           @{" Bugs&Questions " link Contact}\n\n@endnode\n\n\n@node Introduction "Who! - Introduction"\n\nWhat''s Who!\n\nwho! is a nodeviewer like the standard ''who'' in AmiExpress. So you can\nuse who! to replace this standard ''who'' command.\n\nBut why should you replace it? Well, because Who! has several options you\nwill not find in the standard ''who'':\n- Full configurability  \n  Every piece of information displayed by Who! is alterable, so you can\n  completely design your own looks for Who!.\n- Send online message option\n  If you see someone you know on another node, Who! gives you the\n  possibility to send a line of text to his node.\n- Drop user option\n  Who! gives you the ability to drop a user from your BBS\n- Showing different information to different accesslevels\n  Who! can use specific config files for different accesslevels. This way\n  you can give Who! a complete different look for a new user than for a \n  co-sysop.\nWho! has several other options, which will be explained in the\n@{"configuration" link configuration} part of this guide.\n\n@endnode\n\n@node Installation "Who! - Installation"\n\nINSTALLATION\n\nTo install Who! you have to copy the following files to the directory you\nwant Who! installed in:\n- Who!.x           : the executable\n-@{" Who!_node.txt " link Who!_node.txt}  : the textfile telling Who! what to display\n-@{" Who!.ini      " link Who!.ini}  : the configuration file to alter the functioning of Who!\n\nCopy the file "ini.library" in the "libs" dir to your "SYS:libraries".\n\nNow you have to install who! as a door for AmiExpress:\n\nI.AMIEXPRESS 2.XX:\n\nAdd a line to the BBS.CMD file like this:\n*WHO      XM001BBS:Mydir/Who!.x\n - Where "WHO" is the command that must be typed in by the user to activate \n   the door. (You can use another word here if you want to be able to use the\n   standard /X who, for instance WHO!)\n - The "001" is the minimum securitylevel needed to use the door.\n - The "BBS:Doors/Who!.x" is the path where /X can find who!. (So replace\n   BBS:Doors with the path you have installed who!.\n        \n\nII.AMIEXPRESS 3.XX\n\nCopy the who!.info to your BBS:Commands/BBSCmd dir. And alter the tooltypes\nin it conform your wishes:\nMULTINODE=YES            : Who! can be used as a multinode door.\nTYPE=XIM                 : Who! is a XIM door\nACCESS=xxx               : xxx is the minimum accesslevel needed to use Who!		\nLOCATION=xxx             : xxx is the path to who!.x (for instance\n                           BBS:Doors/Who!.x)\n\n\nNow Who! is installed, but do not forget to @{"configure" link configuration} it!\n\n@endnode\n\n@node Configuration "Who! - Configuring the door"\n\nI.CONFIGURING WHO!\n\nAs Who! is made to be completely alterable to your wishes, the\nconfiguration of Who! exactly as you want it, is quite complicated.\nConfiguring consists of altering two types of file:\n\n-@{" Who!_node.txt " link Who!_node.txt}  : the textfile telling Who! what to display\n-@{" Who!.ini      " link Who!.ini}  : the configuration file to alter the functioning of Who!\n\n\nII.DIFFERENT CONFIGURATION FILES PER ACCESSGROUP\n\nA special option is that you can use different configuration files for an\naccess level, by adding a minimum level to the name of the file:\n\nEXAMPLE:\nYou want to have a special display of nodes for everybody with an\naccesslevel higher than 220. Then you create the following files:\n- Who!_node220.txt \n- Who!220.ini\nAnd you alter these to your wishes.\nNow, for all users with an accesslevel lower than 220, Who! will use the\nstandard Who!_node.txt and Who!.ini. And for all users with an accesslevel\nhigher than 220, Who! will use the Who!_node220.txt and Who!220.ini.\n\nThis way you can create different who ''looks'' with different node/user\ninformation for all your accesslevel groups.\nIMPORTANT: you can only use accesslevels that can divided by five\n(0,5,10,...250,255), all others will not be recognized! (So Who!213.ini will\nnot be recognized, change it to Who!210.ini or Who!215.ini.)\n\n\nIII.EXAMPLES\n\nIn the ''examples'' dir in the archive you will find several examples of\nWho!_node.txt''s and a pre defined Who!.ini.\nYou can use these instead of the standard one''s, or use them for\nAccesslevel dependant configuration files (see above) by copying them to\nyour who! dir and renaming them to the required names.\n\n@endnode\n\n@node Who!_node.txt "Who! - Configuring Who!_node.txt"\n\nThe Who!_node.txt file decides what will be printed when Who! is executed.\n\nThe format is as follows:\n\n1. The first lines before the line starting with an "@" will be printed\n   just once. They are the header of the nodeviewer.\n2. The lines between the first line starting with an "@" and the second\n   line starting with an "@" are the main body that will be printed\n   again for every node. This is the only part that may contain the commands\n   of what should be printed.\n3. The lines following the second line starting with an "@" will also be\n   printed just once. They are the footer of the nodeviewer.\n\nEXAMPLE:\nHeader ----\n\@\nInfo per node with commands \n\@\nFooter ----\n\nThe commands that may be used in the main body are of the following format:\n<name(num)> or <name>\nwhere\n  name = the name of the command (see list below)\n  num = the length of the information string obtained by using the command.\nWhen you not specify a length ''num'' (only <name>), the length of the\ninformation will depend on the size of the string only.\nEXAMPLE:\n  <LOCATION(25)> \n  This will print the location of the person on a node, using 25\n  characters. \n\nList of possible commands:\nNODE            NodeNumber\nNAME		Name of user online at node\nLOCATION	Location of user at node\nACTION		String telling about what the user does at the moment\n                (can contain filename of upped/downed file)\nPASSWORD	Users password (USE WITH CARE!!!)\nPHONE		Phonenumber of user at node\nSLOTNR		Slotnumber of user at node\nLEVEL		Securitylevel of user at node\nRATIOTYPE	Ratiotype of the user at node\nRATIO		Ratio of the user at node\nCOMPTYPE	ComputerType of the user (ONLY RETURNS A NUMBER)\nMSGPOSTED	Number of messages posted\nTIMESCALLED	Number of times user has called the bbs\nLASTON		Date user was last on (MM:DD:YY)\nMINSUSED	Minutes used by the user today \n                (Can be used for online time, although with multiple calls\n                 on one day the minutes will be added up.)\nSECSUSED	Same as above, only seconds\nMINSTOTAL	Total minutes the user has today\nSECSTOTAL	Total seconds the user has today\nMINSLIMIT	Daily time limit in minutes\nSECSLIMIT	Dailt time limit in seconds\nUPLOADS		Number of files user has uploaded\nDOWNLOADS	Number of files user has downloaded\nUPBYTES		Number of bytes user has uploaded\nUPKBYTES	Number of kilobytes user has uploaded\nUPMBYTES        Number of megabytes user has uploaded\nDOWNBYTES	Number of bytes user has downloaded\nDOWNKBYTES      Number of kilobytes user has downloaded\nDOWNMBYTES      Number of megabytes user has downloaded\n\n@endnode\n\n@node Who!.ini "Who! - Configuring Who!.ini"\n\nThe Who!.ini file can contain several keywords to enable extra options in\nWho! or to alter standard strings. They are seperated into to groups:\n[Options] and [Strings].\n\nHow to use the keywords:\n- Keywords in one group may stand in every order you want. \n- You can''t use keywords from one group in the other.\n- Who! will use default keywords is you remove the keyword. \n- All charactes after a ";" will be skipped, so you can use it for comments.\n- Don''t use spaces before or after the = sign \n- Use strings this way: "string"\n\n\nPossible keywords in the [Options] part:\n\n- Max_nodes=maximum number of nodes displayed (0-31) by Who!\n- UDBlock="YES"/"NO"  \n    Block output of node if user is up-/downloading. This prevents that Who!\n    will wait for several seconds on node information, when you use other \n    commands than NODE,NAME,LOCATION and ACTION in your @{"Who!_node.txt" link Who!_node.txt}\nAsk_commands="YES"/"NO"\n    Always display a line asking the user if he wants to use the special\n    online options: Send online message and Drop user.\nSendmessage_lvl=minimum level required to send cross node messages\nDropuser_lvl=minimum level required to drop users\n\n\nPossible keywords in the [Strings] part:\n\nRatiotype_byte="the word displayed when ratiotype of a user on a node is byte"\nRatiotype_b/f="the word displayed when ratiotype is byte/file"\nRatiotype_file="the word displayed when ratiotype is file"\nRatio_disabled="string displayed when ratio is disabled"\n\nNot_online_name="string displayed as name of the user on a node when there\n                 is nobody online"\nNot_online_location="string displayed as location of the user on a node\n                     when there is nobody online"\nYour_name="string displayed as name of the user who is using Who!"\n    Leaving this string empty ("") means his normal name should be used\nYour_location="string displayed as location of the user who is using Who!"\n    Leaving this string empty ("") means his normal name should be used\n    \nYour_action="string displayed as action of the user who is using Who!"\n\n(The following keywords are keywords that can be used to replace the\nstandard strings used for displaying the user''s action, the strings after\nthe ''='' can be replaced by your own.)\n\nIdle="Doing nothing (idle)"\nUpload="Uploading..."\n    (''%s'' used in this string will be replaced by filename of the file being \n    upped, eg Upload="Uploading: %s")\nDownload="DownLoading..."\n    (''%s'' used in this string will be replaced by filename of the file being\n    downed, eg Download="Downloading: %s")\nDoor="Using a module/door..."\n    (''%s'' will be replaced by the command to access this door. So if your \n    bbs.cmd lines are equal to your doornames, you will see which door is\n    being used! eg. Door="Using %s")\nMail="Reading/Writing Mail"\nEdit_stats="Editing his/her stats"\nAccount="Editing accounts"\nZoom="Zooming"\nScan_files="Scanning filedir"\nBulletins="Reading Bulletins"\nView_file="Viewing a file"\nAccount_seq="Account sequence"\nLog_off="Logging off"\nMaintenance="Doing sysop maintenance work (editing files/dirs etc.)"\nShell="Using the Shell"\nEdit_file="Editing a file"\nJoin_conf="Joining a conference"\nChat="Chatting"\nNot_active="Node not active"\n    (NOT USED)\nRequest_chat="Request chat"\nConnect="Connecting"\nLoggin_on="Logging on"\nAwait_connect="Awaiting connect"\nScan_mail="Scanning mail"\nShutdown="Node shutdown"\n    (NOT USED)\nMultichat="Multichatting"\nSuspend="Node suspended"\n    (NOT USED)\nReserve="Node reserved"\n    (NOT USED)\nUpload_start="Starting an upload"\nDownload_start="Starting a download"\n\n\nYou will find a clean standard.ini file and a special ''scene-slang'' .ini\nfile in the "Examples" dir in the archive.\n\n@endnode\n\n@node Options "Who! - Online options"\n\nWho! currently has 2 online options:\n\n- Send Online Message \n  This will send a message to another node, including who sent it, and from\n  what node. This message will break through all other things, including\n  Chats, doors, shells etc. Only when the user on the other node is\n  up-/downloading the message is not send.\n- Drop User\n  This will drop a user offline by setting his time limit to zero. Although\n  this should mean he can not log in anymore today, this is not the case,\n  as this operation is not saved to disk.\n  This way of dropping a user will work on both local and remote nodes.\n\nBoth options have their own minimum security level alterable in the @{"Who!.ini" link Who!.ini}\nfile. And can be accessed in two ways:\n- Who! can ask for them. This option can be switched on/off in the Who!.inifile.\n- From the AmiExpress prompt. By typing an ''s'' or ''d'' after the command to\n  execute Who!, eg WHO S or WHO D.\n\nMore online options will be added in future versions.\n\n@endnode\n\n@node Important "Who! - Important Messages"\n\nDisclaimer:\n\nUse this software at your own risk. The authors will not be liable for\nany damage arising from the failure of this program to perform as described,\nor any destruction of other programs or data residing on a system\nattempting to run the program. While no damaging errors are known, the\nuser of this program uses it at his or her own risk.\nYou may spread the original, unchanged archive for non-commercial purposes.\nPD companies may not spread this product for anything more than the actual\ncopying costs, and only with permission of the authors.\n\nThis program is FreeWare!\n\n\n\n\n\n@endnode\n\n@node Contact\n\nYou can contact me for bugs and questions:\n\nWrite to:\n\nB/\\Zz/Skidrow\nPO Box 11023\n7502 LA ENSCHEDE\nHOLLAND\n\nOr leave mail at:\n\nDoomBase - Skidrow HotC (press ''C''omment to sysop):\n   node 1:   ++31-10-2731172\n   node 2:   ++31-10-2731825\n\n@endnode\n','\n',char(10)),'{"TYPE":"XIM","ACCESS":"xxx","LOCATION":"xxx"}','auto-added',68042,16,0,NULL,NULL,'sr_who_1','scan',1780048749);
INSERT INTO door_catalog VALUES('ssplc100','SSPLC100.LZX','~/Code/amiexpress_doors/Archives/AmiExpress/SSPLC100.LZX',NULL,'XIM','SSP_LZXCheck.exe',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'auto-added',17337,0,0,NULL,NULL,'ssplc100','scan',1780048749);
INSERT INTO door_catalog VALUES('ssp_lc10','SSP_LC10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SSP_LC10.LHA',NULL,'XIM','SSP_LZXCheck.exe',NULL,NULL,'SSP','tbM_/   _______/_/   _______/    _     \_ . ____\_______  _\_\_______   \_    /      / |/          _/ /         _/    /  ________/.',replace('        ___________  ___________ _ _______\n   tbM_/   _______/_/   _______/    _     \_\n. ____\_______  _\_\_______   \_    /      /\n|/          _/ /         _/    /  ________/.\n/_____________/_______________/___/        |\n+--- - Sunshine Productions Presents: - ---+\n|          The Great LZX Checker!          |\n|                LZXCheck 1.0!             |\n|     Coded 100% Pure ASM By:  Blast       |\n`------------- -- -    - -- ---------------''\n','\n',char(10)),'SSP_LZXCheck.doc',replace('        -^-v-^- - - -- ---v-^- - -- - - --^-v-^- - -- --^-v--^-- -\n            SSP_LZXCheck v1.0  Code:Blast/Sunshine Productions\n      - -^- -- -^-v-^- -^-v-^- -  --- -- -- -v- --^-v-^-^-v-^-- -- -\n\n       Liability\n       ~~~~~~~~~\n       If your computer crashes, your car blows up, your\n       girlfriend leaves you, your cat becomes pregnant,\n       your dog begins to walk under the ceiling,or your\n       TV  begins  to  transmit ''V'' 24 hours a day, it''s\n       not  MY  fault,  and  I  take  NO  responsibility\n       whatsoever   for  the  (mis)performance  of  this\n       program...\n\n\n       General Information\n       ~~~~~~~~~~~~~~~~~~~\n     - What is this LZX anyway?\n\n     - LZX is a new compression algorithm developed by Jonathan\n       Forbes, the creator of many programs including the good\n       old LZ and XenoLink (the BBS system)...\n\n     - So ? What does that help me?\n\n     - The thing with LZX is that it''s quick, and compresses far\n       better than any other compression program including LHA and\n       Shrink.\n\n     - But is this something only for the Amiga or what?\n\n     - Nope! LZX will be coming in a PC version soon as well,\n       so it''ll be multiplatform available for the public..\n\n     - Ahuh, and what if I''ve got, say a BBS or something and\n       want to be able to use it, like check if files are ok\n       that are compressed with this LZX, what do I do?\n\n     - This is where LZXCheck comes in, you simply enter the\n       filename on the mainline and it checks the file!\n\n     - Wow! It''s just that simple.. wow..\n\n     - Yeah, and you can add files to the archive as well..\n       Adds and stuff.. But the limitation right now is\n       that LZX itself can''t add multiple files on one go,\n       that is only available when registered.. I''ll\n       be coming out with a new version as soon as I get my\n       hands on a registered LZX, so that it''ll be possible\n       to specify a file that LZX will read what files\n       to add to the archive...\n\n     - But I can still add one file, right?\n\n     - Yeah, right now you can add ONE file to the archive..\n       And in the registered LZX you''ll be able to strip\n       files from the archive as well... I''ll add that\n       feature like I said, when I get the registered\n       version...\n\n\n       Installation\n       ~~~~~~~~~~~~\n     - But how do I do for AmiExpress for example?\n\n     - You just copy the directory called SSP to your\n       DOORS: and the icon LZX.info to your BBS:FCheck/\n       and change the options to whatever suitable...\n\n     - Ok! How do I specify an add file?\n\n     - The information in the icon should look something\n       like this:\n\n                               ---- CUT ----\n       CHECKER=DOORS:SSP/SSP_LZXCheck/SSP_LZXCheck.exe\n       OPTIONS=-A DOORS:SSP/SSP_LZXCheck/AddFile\n                               ---- CUT ----\n\n       You can forget about the rest, it is set as it should,\n       don''t change it!\n\n       The CHECKER= is the path to the checker... Leave it at\n       that...\n       The OPTIONS= string is configured like this:\n\n       If there is a -A in it, then Adding is enabled, then\n       you change the S:MyAddFile to whatever you want,\n       this is the file that will be added...\n       If you DON''T want any adding, only testing, just delete\n       the OPTIONS= field or put a semicolon in front of it\n       like :\n       ;OPTIONS=-A DOORS:SSP/SSP_LZXCheck/AddFile\n\n       Nothing more, nothing less...\n\n       DON''T FORGET TO ADD THIS FILETYPE TO THE DIZ DOORS AS WELL!\n\n       For example for ByteAndi''s FileID door:\n\n       extern_LZX_ADD=c:LZX -q a %P %WFILE_ID.DIZ\n       extern_LZX_EX=c:LZX -q e %P %WFILE_ID.DIZ\n\n       Bugs\n       ~~~~\n       Bugs? Nah, ain''t none... But if you find one, just call\n       my Board and tell me about it and I''ll fix it right\n       away...\n\n       History\n       ~~~~~~~\n       V1.0 - First release... What you see is what you get!\n\n       Future\n       ~~~~~~\n       To make it work with the registered version with multifile\n       adding and stripping, I''ve got to get hold of the\n       registered version first though.. Well, any other ideas\n       are welcome! Just call Napalm at +46-8-894595 and tell me\n       about it!\n\n       Greetings goes to:\n       ~~~~~~~~~\n\n       The Eagle.: You''ll get it back soon.. I promise!\n\n       Mr.Coke...: Is your board ALWAYS busy or what?\n\n       Nightshade: Have you changed the output of that ''c'' door YET?\n','\n',char(10)),NULL,'auto-added',5443,5,0,NULL,NULL,'ssp_lc10','scan',1780048749);
INSERT INTO door_catalog VALUES('ssp_lc12','SSP_LC12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SSP_LC12.LHA',NULL,'XIM','SSP_LZXCheck.exe',NULL,NULL,'SSP','tbM_/   _______/_/   _______/    _     \_ . ____\_______  _\_\_______   \_    /      / |/          _/ /         _/    /  ________/.',replace('        ___________  ___________ _ _______\n   tbM_/   _______/_/   _______/    _     \_\n. ____\_______  _\_\_______   \_    /      /\n|/          _/ /         _/    /  ________/.\n/_____________/_______________/___/        |\n+--- - Sunshine Productions Presents: - ---+\n|          The Great LZX Checker!          |\n|                LZXCheck 1.2!             |\n|     Coded 100% Pure ASM By:  Blast       |\n`------------- -- -    - -- ---------------''\n','\n',char(10)),'SSP_LZXCheck.doc',replace('        -^-v-^- - - -- ---v-^- - -- - - --^-v-^- - -- --^-v--^-- -\n            SSP_LZXCheck v1.2  Code:Blast/Sunshine Productions\n      - -^- -- -^-v-^- -^-v-^- -  --- -- -- -v- --^-v-^-^-v-^-- -- -\n\n       Liability\n       ~~~~~~~~~\n       If your computer crashes, your car blows up, your\n       girlfriend leaves you, your cat becomes pregnant,\n       your dog begins to walk under the ceiling,or your\n       TV  begins  to  transmit ''V'' 24 hours a day, it''s\n       not  MY  fault,  and  I  take  NO  responsibility\n       whatsoever   for  the  (mis)performance  of  this\n       program...\n\n\n       General Information\n       ~~~~~~~~~~~~~~~~~~~\n     - What is this LZX anyway?\n\n     - LZX is a new compression algorithm developed by Jonathan\n       Forbes, the creator of many programs including the good\n       old LZ and XenoLink (the BBS system)...\n\n     - So ? What does that help me?\n\n     - The thing with LZX is that it''s quick, and compresses far\n       better than any other compression program including LHA and\n       Shrink.\n\n     - But is this something only for the Amiga or what?\n\n     - Nope! LZX will be coming in a PC version soon as well,\n       so it''ll be multiplatform available for the public..\n\n     - Ahuh, and what if I''ve got, say a BBS or something and\n       want to be able to use it, like check if files are ok\n       that are compressed with this LZX, what do I do?\n\n     - This is where LZXCheck comes in, you simply enter the\n       filename on the mainline and it checks the file!\n\n     - Wow! It''s just that simple.. wow..\n\n     - Yeah, and you can add files to the archive as well..\n       Adds and stuff.. But the limitation right now is\n       that LZX itself can''t add multiple files on one go,\n       that is only available when registered.. I''ll\n       be coming out with a new version as soon as I get my\n       hands on a registered LZX, so that it''ll be possible\n       to specify a file that LZX will read what files\n       to add to the archive...\n\n     - But I can still add one file, right?\n\n     - Yeah, right now you can add ONE file to the archive..\n       And in the registered LZX you''ll be able to strip\n       files from the archive as well... I''ll add that\n       feature like I said, when I get the registered\n       version...\n\n\n       Installation\n       ~~~~~~~~~~~~\n     - But how do I do for AmiExpress for example?\n\n     - You just copy the directory called SSP to your\n       DOORS: and the icon LZX.info to your BBS:FCheck/\n       and change the options to whatever suitable...\n\n     - Ok! How do I specify an add file?\n\n     - The information in the icon should look something\n       like this:\n\n                               ---- CUT ----\n       CHECKER=DOORS:SSP/SSP_LZXCheck/SSP_LZXCheck.exe\n       OPTIONS=-A DOORS:SSP/SSP_LZXCheck/AddFile\n                               ---- CUT ----\n\n       You can forget about the rest, it is set as it should,\n       don''t change it!\n\n       The CHECKER= is the path to the checker... Leave it at\n       that...\n       The OPTIONS= string is configured like this:\n\n       If there is a -A in it, then Adding is enabled, then\n       you change the S:MyAddFile to whatever you want,\n       this is the file that will be added...\n       If you DON''T want any adding, only testing, just delete\n       the OPTIONS= field or put a semicolon in front of it\n       like :\n       ;OPTIONS=-A DOORS:SSP/SSP_LZXCheck/AddFile\n\n       Nothing more, nothing less...\n\n       DON''T FORGET TO ADD THIS FILETYPE TO THE DIZ DOORS AS WELL!\n\n       For example for ByteAndi''s FileID door:\n\n       extern_LZX_ADD=c:LZX -q a %P %WFILE_ID.DIZ\n       extern_LZX_EX=c:LZX -q x %P FILE_ID.DIZ %W\n\n       Bugs\n       ~~~~\n     - What do I do if I find a bug in the program then?\n\n     - Nah, there aren''t no bugs... But if you find one, just\n       call any board that I''m active on and leave a mess to me..\n\n       History\n       ~~~~~~~\n       V1.0 - First release... What you see is what you get!\n\n       V1.1 - First release... Beta used for testing...\n              Second release.. Beta which fixed a few bugs,\n                               and added features...\n                               Speeded all approx. 20%\n              Third release... Beta, fixed major bug which\n                               was caused in 2nd rel...\n\n       V1.2 - First release... Added extra output, now\n                               also displays filename and\n                               filesize, org and new...\n                               Public release...\n\n\n       Future\n       ~~~~~~\n       To make it work with the registered version with multifile\n       adding and stripping, I''ve got to get hold of the\n       registered version first though.. Well, any other ideas\n       are welcome! Call any board that I''m active on (preferably\n       Bad Blow (+46-8-58081481)) and leave a mess to me (Blast).\n\n       Greetings goes to:\n       ~~~~~~~~~~~~~~~~~\n\n       The Eagle.: You''ll get it back soon.. I promise!\n\n       Mr.Coke...: Is your board ALWAYS busy or what?\n\n       Nightshade: Have you changed the output of that ''c'' door YET?\n\n       Opium.....: How the hell did you burn both par. ports ?!\n','\n',char(10)),NULL,'auto-added',20270,9,0,NULL,NULL,'ssp_lc12','scan',1780048749);
INSERT INTO door_catalog VALUES('ssp_ta10','SSP_TA10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SSP_TA10.LHA',NULL,'XIM','SSP_TXTADD.EXE',NULL,NULL,'SSP','tbM_/   _______/_/   _______/    _     \_ . ____\_______  _\_\_______   \_    /      / |/          _/ /         _/    /  ________/.',replace('        ___________  ___________ _ _______  \n   tbM_/   _______/_/   _______/    _     \_\n. ____\_______  _\_\_______   \_    /      /  \n|/          _/ /         _/    /  ________/. \n/_____________/_______________/___/        |\n+--- - Sunshine Productions Presents: - ---+\n|        The Fastest TxtAdder EVER!        |\n|                TXTADD V1.0               |\n|     Coded 100% Pure ASM By:  Mr.Coke     |\n|          rELEASED aT: bAD bLOW!          |\n`------------- -- -    - -- ---------------''\n','\n',char(10)),'SSP_TXTADDER.DOC',replace('        _____\n    __øØØØØØØ________.__________________\n   gØØØØØØØØØP       ¦     \        \   \------------------÷--.\n  ØØØØØØ@^°T"        |      \   \    \   \____ ___        xCz ¦\n  VØØØØØØØØØØøææ     ¯       \   \        \   \\  \ __        |\n   ¢ØØØØØØØØØØØØØm_          /    \        \___\\__\\_\       |\n      "T°°^¤**ØØØØØþ________/\_____\________\                 ¦\n       ¦    ___°ØØØØ  _øØØØØØØ_______.________________________: ___________\n ___ææøøØØØØØØØØØØØØ gØØØØØØØØP      ¦     \_______)      \   \/          /\nÆØØØØØØØØØØØØØØØØØP ØØØØØ@^°T"       ¯      \     |   \    \   \   ______/\n¬#ØØØØØØ*¤¤¤¤^°°~   VØØØØØØØØØøææ_   T       \    |    \        \  ____)_\n       ¦             ¢ØØØØØØØØØØØØm_ |       /    |     \        \       \\n       `-÷-------------""°°^¤**ØØØØØþ|______/_____|\_____\________\_______\\n                             ___°ØØØØ                         :\n                 ___æææøøØØØØØØØØØØØØ  P R O D U C T I O N S  .\n                ÆØØØØØØØØØØØØØØØØØØP\n                ¬#ØØØØØØØ*¤¤¤¤^°°°                            .\n                             BRINGS YOU TODAY:\n\nNAME:		SSP_TXTADD V 1.0\nTYPE:		/X-UTILITY	( The fastest TXT-Adder ever!)\nBY:		Mr.Coke\n\nIntroduction:\n=============\nFirst of all.. Excuse me for the bad English..\n\nWell not much to say,\nThis is simply a normal textadder used in the most boards nowdays.. \n\nWhy this ?? \n\nAfter a long time changing from one to another TXTADDER i didn'' found\nEven ONE that was only adding a Header and a Tail, also they were very slow\ncoz of options like Time/uploader/node/etc.. \n\nAlso the most txtadders have there AddFiles in S: so after changed to 10 \nDifferent versions i had about 20 Adds in my S: (other utils use S: to) , and\ni just hate having 1000000 files in S: .. \n\nAnother thing is that as a user on a board you dont'' like to wait for all files\nto be checked (and added) .. This thing takes pretty long time ..\nAlso the most adders get an OutPut Big as the whole Screen telling you to call\ntheir bbs''s:\n-[Screen Shoot]--------------------------------------------------------------\n\nxxxxxxx Vx.x by xxxxxxxxxxxxxxxxx\n\nDate of creation: xxxxxxxxxx       Contact me at:\nAdds: * xxxxxxxxx xxxx/xxxx        xxxxxxxxxxx xxxxxx xxx\n      * xxxxxxxx                   xxxxxxxxxxxxxx\n      * xxxx\n\nUsage: xxxxxxxx <SRC/DST>\n\n-[Screen Shoot]--------------------------------------------------------------\n\n           And in the TXTFILES ther''s a Fucking LINE to.. LIKE:\n-[Screen Shoot]--------------------------------------------------------------\n\n                                                   [xxxxxxxx vx.x By xxxxx]\n-[Screen Shoot]--------------------------------------------------------------\n\n(I''m Shore you know this Utility ) But it''s not ONLY this..\n\n\nHow It Works:\n=============\n\nSimpel.. It loads the file and append a HEAD.TXT & TAIL.TXT to it.\n(and it does it FAST!)\n\nUsage:\n======\n\nWell if you don''t know how to install this you''r probably not a sysop\nOkey this how to do..\n\nCLI/SHELL: SSP_TXTADD.EXE {Filename}\n\nor in /X\n\nJust Install all the icons in BBS:FCHECK/ (TXT.INFO/NFO.INFO/etc)\n\nCopy The archive to DOORS:\n\nPs. Or you can use the Installer..\n\nHISTORY:\n========\n\n	V0.9		First Working version (About 30 mins of work)\n			Adding HEAD.TXT and TAIL.TXT to File..\n\n	V0.99% 		Fixed a Bug in The memory allocation.\n			version 0.9 didn''t release memory after allocation.\n			First BETA verison .. Simpel TXT Output.\n\n	V1.0		Fixed some Ansi OutPut (WOW! haha) ..\n			Optimised som routines in it..\n			and got the size down to 3880 bytes..\nBETA TESTERS:\n=============\nMr.Coke		BadBlow (no shit)	+46-8-58081481	28k8 VFC\nBlast		Napalm			+46-8-894595	28k8 VFC\nLightSpeed	DarkRoom		+46-220-17744	16k8 DS\nOpium		Crystal of darkness 	+46-8-7734734	28k8 VFC\n','\n',char(10)),NULL,'auto-added',8666,6,0,NULL,NULL,'ssp_ta10','scan',1780048749);
INSERT INTO door_catalog VALUES('ss_cd13','SS_CD13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SS_CD13.LHA','CDDoor','XIM','CDDoor - A VERY configurable CD-Server','1.3',NULL,'SS','for /X. May be used for HD partitions as well... ©1995 Jonas Niklasson - NO REGISTRATION FEE!',replace('CDDoor V1.3 - A VERY configurable CD-Server\n              for /X. May be used for HD\n              partitions as well...\n\n©1995 Jonas Niklasson - NO REGISTRATION FEE!\n','\n',char(10)),'CDDoor.guide',replace('@database "CDDoor.Guide"\n@Node MAIN "CDDoor documentation"\n\n                      CDDoor V1.3 - ©1995 Jonas Niklasson\n                      ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n\n                            @{" Introduction to CDDoor " link ABOUT}\n\n                                 @{" Distribution " link DISTR}\n                                  @{" Disclaimer " link DISCL}\n                             @{" System  Requirements " link REQ}\n                                 @{" Installation " link INST}\n\n                               @{" How to configure " link CONF}\n                                  @{" How to use " link USING}\n\n                                @{" Supporting BBS " link BBS}\n                                  @{" The Author " link AUTHOR}\n                                   @{" History! " link HIST}\n\n\n   It is EXTREMELY crucial that You read the @{" Configuration " link CONF} explonation.\n@Endnode\n@Node ABOUT "Introduction"\n\n    CDDoor is a XIM-door for AmiExpress. It is designed to allow users\n   access a CD-Rom that is connected to the system. But it can as well be used\n   to access a specific partition of Your choice.\n\n    It is designed to remind the user of normal Shell, so that the user\n   easy can figure out how to operate it.\n\n    It can be configured to add a BBS-add in the archives it sends. And\n   You can forbid normal users to enter certain paths.\n\n    As a bonus, it also creates a bulletin of the users download habits.\n\n@Endnode\n@Node DISTR "Distribution of CDDoor"\n\n    CDDoor is ShareWare. This means that no fees may be charged nor profits\n   made by distributing this software. Only a nominal fee covering the media\n   should be accepted. \n\n    Public Domain distribution centres are allowed to place CDDoor in their\n   software pool, as long as they obey to rules mentioned above.\n\n   The AEDoor.library is made by stx Exp.\n\n@Endnode\n@Node DISCL "Disclaimer"\n\n    The program is intended as a support to Sysop''s. Any miss-use of CDDoor\n   by error in configuration are changes in the Executables may damage your\n   system.\n\n    I, the Author, cannot be held responsible of any damage to Your system\n   that is caused by miss-use of the software.\n\n   As conclusion, read the documentation completely before you install it.\n\n@Endnode\n@Node REQ "Requirements"\n\n    The requirements for usage of CDDoor is as followed:\n\n\n      * OS 2.x or higher\n\n      * AmiExpress 3.x or higher\n\n      * AEdoor.library V2.3 or higher (included)\n\n      * 10 MB of temporary storage (probably HD)\n\n      * Mapus\n\n      * LHA\n\n@Endnode\n@Node INST "Installation of CDDoor"\n\n    Place the directory called CDDoor in your BBS:Doors drawer. There must\n   be an assign to your BBS:Doors drawer called DOORS: for CDDoor to function.\n\n   The files that must be in the CDDoor drawer is as followed:\n\n      CDDoor   - The XIM door\n      Config   - CDDoor configuration file\n      Config2  - CDDoor bulletin configuration file\n\n    The command CD should be placed in the Commands drawer of your choice. The\n   name of the command, i.e. CD, can be changed of Your desire.\n\n    Make sure to add the temporary storage device name in the Download path in\n   the appropriate conference or conferences.\n   \n    Make sure that you have appropriate version of AEDoor.library in your\n   libs: drawer.\n\n    Begin the @{" Configuration " link CONF}\n\n@Endnode\n@Node CONF "Configuration"\n\n    Please note the @{" Disclaimer " link DISCL} before proceeding.\n\n\n    Configuring the @{" CDDoors " link CONFC} behavior...\n\n    Configuring the @{" Bulletins " link CONFB} behavior...\n\n    Configuring the @{" Forbidden " link CONFF} paths...\n\n@Endnode\n@Node CONFC "Configuring CDDoors behavior..."\n\n   The file to configure is ''Config''.\n\n\n   ''Device name of CD-rom'' \n\n       This is simply the physical devicename. For example CD0: and ZD0:.\n      You must specify the colon also. If you replace is with a physical\n      name of a partition the users may access that partition instead.\n\n\n>  ''Physical or logical device name to store and delete in''\n>\n>      Here CDDoor stores the files that the user flags. It is EXTREMELY\n>     important that it points to a device that is empty, as CDDoor DELETES\n>     all files in this drawer.\n\n\n   ''Autodir flag; 0=NO; 1=DIR; 2=LIST''\n\n       This is the flag which decides in what state AutoDir function should\n      be in upon starting CDDoor\n\n\n   ''BBS-Add to add to LHA, LZX & DMS archives''\n\n       Upon transfering files to the device explained above, the Add\n      written here will be added to the archive. Please note that the\n      entire path and file must be entered.\n\n       If none is entered, none will be added...\n\n\n   ''Access to override Forbidden routine''\n\n       This is the access-level needed to enter the path''s or files which\n      is specified in the Forbidden configuration. \n\n\n   ''Help-text''\n\n       The text that will be showed at startup and whenever the user asks\n      for it.\n\n@Endnode\n@Node CONFB "Configuring Bulletins behavior..."\n\n   The file to configure is ''Config2''.\n\n\n   ''Bulletin path'' \n\n       Path and file to create the bulletin in.\n\n\n   ''Repeat line''\n\n       The line which to repeat in the bulletin. This is the line which\n      contains the control characters. Please note that the count is started\n      from the top of the configuration file. I.E. line 0 is the top.\n\n\n   ''Number of shown users''\n\n       Simply the number of top users to show in the bulletin.\n\n\n   ''Design description:''\n\n       This is an explonation of the control characters that is useable in\n      the bulletin design.\n\n\n   ''Design:''\n\n       The design of the bulletin which is created.\n\n@Endnode\n@Node CONFF "Configuring the FORBIDDEN paths..."\n\n    Since some CD-manufacturers place commercial programs on the CD''s and\n   to prevent users to access path''s of your choice, CDDoor includes a\n   forbidden routine.\n\n    If You place an ASCII file in the CDDoor drawer of the same name as the\n   CD in the CD-rom, it will be read upon startup.\n\n    In the ASCII you simply enter the paths that you want to prevent users\n   from accessing. But You MUST enter the path completely from the device\n   name, for example: ''CD0:Commercial''\n\n    For each path or file you want to prevent, you simply enter a new row\n   in the ASCII file.\n\n    Please note that it will only be read is the CD has the same name, i.e.\n   You will have to place several ASCII files if You want to prevent paths\n   on several CD''s.\n\n\n>   All users of Security Level of 200 and higher will override this\n>  prevention routine!\n@Endnode\n@Node USING "How to use it..."\n\n    It functions almost as normal Shell.\n\n    If you enter a path, it will move to that drawer. A "\" will back\n   one drawer level and "\\" will back to the root.\n\n    If you instead enter a file or path and file, the file will be\n   flagged for download, and copied to the temporary device entered\n   in the configuration file.\n\n    Please note that ''FLAG'' only can be used to remove flagged files from\n   the flag list. It wont remove them from the temporary storage... Yet.\n\n    Also note that is You exit CDDoor all files from the temporary storage\n   will be deleted, but not the flaggings... Yet.\n\n    Other usable commands are shown at startup.\n\n@Endnode\n@Node AUTHOR "The Author of CDDoor"\n\n    If You want to contact me to report eventual bugs or suggestion, you can\n   either send snailmail to:\n\n      Jonas Niklasson\n      Augustenborgsgatan 8C\n      214 47 MALMOE\n      SWEDEN\n\n    Or call me at +46 (0)40 893 98\n\n    Or call the @{" Support BBS " link BBS}.\n\n\n    At the support BBS, You are certain to find updates and other programs,\n   doors and utilities which a create.\n\n@Endnode\n@Node HIST "History"\n\n   V1.0 - The platform of the CDDoor completed\n          Thanks to Benny Bengtsson and the users of South Side BBS\n          for the Beta-testing!\n\n   V1.1 - Added some commands\n\n   V1.2 - Included the bulletin routine\n\n   V1.3 - Included the Forbidden routine\n\n\n\n   To do:   * Construct an own Flag routine\n\n@Endnode\n@Node BBS "Support BBS"\n.--------------------------------------------------------------------------.\n| ¤                      ENJOY THE PD EXPERIENCE AT                      ¤ |\n|                                                                          |\n|.::::::: .::::::. :::   ::::::::: :::  :::  .::::::: ::: :::::::. .:::::::|\n|:::           ::: :::      :::    :::  :::  :::      ::: :::  ::: :::     |\n|`::::::. :::  ::: :::  ::: :::    ::::::::  `::::::. ::: :::  ::: `::::   |\n|     ::: :::  ::: :::  ::: :::    :::  :::       ::: ::: :::  ::: :::     |\n|:::::::'' `::::::'' `::::::'' :::    :::  :::  :::::::'' ::: :::::::'' `:::::::|\n|                                                                          |\n|               »»» ONLY FREELY REDISTRIBUTABLE SOFTWARE «««               |\n|   M               ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯               M   |\n|   o          FREEWARE/SHAREWARE/GIFTWARE/PUBLIC DOMAIN etc.          o   |\n|   T                        !! MEMBERS ONLY !!                        T   |\n|   o                           ¯¯¯¯¯¯¯¯¯¯¯¯                           o   |\n|   R        SYSTEM :                        OPERATING SYSTEM :        R   |\n|   o        ··················································        o   |\n|   L        => Amiga 3000 Tower/030 25mhz   => OS Release 3.1         L   |\n|   a        => 12.0 Gigs of Disk Storage    => Kickstart V40.70       a   |\n|               inc/cdrom                    => Workbench V40.42           |\n|   I                                                                  I   |\n|   n    THIS BBS IS FOR AMIGA USERS AND IS BASED UPON *FRIENDSHIP*    n   |\n|   S                                                                  S   |\n|   ¡    THIS BBS WILL NOT ACCEPT ANY ACT OF CRIME OR ANYTHING LIKE    ¡   |\n|   D   SOFTWARE SWAPPING AGAINST ANY LAW OF SWEDEN OR EUROPEAN LAW.   D   |\n|   e          IF YOU WANT PIRATED SOFTWARE, LOOK ELSEWHERE!!          e   |\n|                        *REMEMBER PIRACY IS THEFT*                        |\n| ¤ Node: 1 - +46-(0)40-939205 - 28.8   Node: 2 - ??-?????-?????? - ??.? ¤ |\n`--------------------------------------------------------------------------''\n@Endnode\n','\n',char(10)),NULL,NULL,16106,3,0,NULL,NULL,'ss_cd13_cddoor','scan',1780048749);
INSERT INTO door_catalog VALUES('ss_em14','SS_EM14.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SS_EM14.LHA','EM','XIM','.-----------------------------------------.',NULL,NULL,'SS','|        .- \  / _  _  .-   _   _         | |        |-  \/ |_)|_) |-  (_  (_         | |        l__ /\ l  l \ l__ __) __)        |',replace('.-----------------------------------------.\n|        .- \  / _  _  .-   _   _         |\n|        |-  \/ |_)|_) |-  (_  (_         |\n|        l__ /\ l  l \ l__ __) __)        |\n|           /  \                          |\n|     M A N A G E R  V1.4  ©  1 9 9 6     |\n|   THE FileListManager for AmiExpress.   |\n|     Far better editing routine than     |\n|      comperative doors can offer!.      |\n|                                         |\n|     WORLD RELEASE AT SOUTH SIDE BBS     |\n`-----------------------------------------''','\n',char(10)),'EM.guide',replace('@database "EM.Guide"\n@Node MAIN "Express Manager documentation"\n\n                  Express Manager V1.4 - ©1996 Jonas Niklasson\n                  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n\n                        @{" Introduction to Express Manager " link ABOUT}\n\n                                 @{" Distribution " link DISTR}\n                                  @{" Disclaimer " link DISCL}\n                             @{" System  Requirements " link REQ}\n                                 @{" Installation " link INST}\n\n                               @{" How to configure " link CONF}\n\n                                @{" Supporting BBS " link BBS}\n                                 @{" Registration " link AUTHOR}\n                                  @{" The Author " link AUTHOR}\n                                   @{" History! " link HIST}\n\n@Endnode\n@Node ABOUT "Introduction"\n\n    Express Manager is a XIM-door for AmiExpress. It is designed to be\n   as user-friendly as possible, but most of all to use very little\n   memory compared to other filedirmanagers.\n\n    A filedirmanager is used to edit the filelistings contents and copy,\n   move, delete files both on the host machine and online by modem.\n\n@Endnode\n@Node DISTR "Distribution of Express Manager"\n\n    Express Manager is ShareWare. This means that no fees may be charged\n   nor profits made by distributing this software. Only a nominal fee\n   covering the media should be accepted.\n\n    If you register you will be rid of the anoying extraline appearing\n   in the filedirlisting.\n\n    Public Domain distribution centres are allowed to place Express Manager\n   in their software pool, as long as they obey to rules mentioned above.\n\n@Endnode\n@Node DISCL "Disclaimer"\n\n    The program is intended as a support to Sysop''s. Any miss-use of\n   Express Manager by error in configuration or changes in the Executables\n   may damage your system.\n\n    I, the Author, cannot be held responsible of any damage to Your system\n   that is caused by miss-use of the software.\n\n    Furthermore can I, the Author, not be held responsible for any damage\n   to Your system that is caused by any programming bugs in the software.\n\n    As conclusion, read the documentation completely before you install it.\n\n@Endnode\n@Node REQ "Requirements"\n\n    The requirements for usage of Express Manager is as followed:\n\n\n      * OS 2.x or higher\n\n      * AmiExpress 3.x or higher\n\n      * AEdoor.library V2.3 or higher (included)\n\n      * FileID.library V2 (included)\n\n      * ReqTools.library V37 (included)\n\n      * TXTExtract (included)\n\n      * DMSDescript (included)\n\n      * LHA\n\n      * LZX\n\n      * ZIP\n\n      * UNZIP\n\n      * Approximately 260 KB memory per started EM\n\n@Endnode\n@Node INST "Installation of Express Manager"\n\n    Place the directory called EM in your BBS:Doors drawer. There must\n   be an assign to your BBS:Doors drawer called DOORS: for Express\n   Manager to function.\n\n   The files that must be in the EM drawer is as followed:\n\n      EM       - The XIM door\n      EM.cfg   - Express Manager configuration file\n\n    The command EM should be placed in the Commands drawer of your choice. The\n   name of the command, i.e. EM, can be changed of Your desire.\n\n    Make sure that you have appropriate version of AEDoor.library in your\n   libs: drawer.\n\n@Endnode\n@Node CONF "Configuration"\n\n    Allow multi-node use (Y/N)\n\n    [Y]es or [N]o flagged. Each EM started will use approximately 250 KB\n   of memory, which means that is you have many nodes and little memory\n   it is wise to suppress multi-node use.\n\n\n\n    Add tag to log (Y/N)\n\n    [Y]es or [N]o flagged. Logs certain events in the CallerLogs appropriate\n   for the current node. Useful if lots of people have access to EM and\n   you want to be able to examine uses of it.\n\n\n\n    Use Conference Accounting (Y/N)\n\n    [Y]es or [N]o flagged. Specifies if Awarded/Nuked credits should\n   be applied in /X Conference Accounting system. I.E. individual\n   upload/download ratios for different conferences.\n\n\n\n    Accesslevel for HOLD-access\n\n    Access-level entered as minumum required to enter HOLD-directory.\n\n\n\n    Accesslevel for UPLOAD-access\n\n    Access-level entered as minumum required to enter UPLOAD-directory.\n\n\n\n    Accesslevel for editing others uploads\n\n    Access-level entered as minimum required to edit other people''s upload''s.\n\n\n\n    Accesslevel for dummycreation\n\n    Access-level entered as minimum required to make a dummy file.\n\n\n\n    Accesslevel for Logo-editing\n\n    Access-level entered as minimum required to save changes in the logos.\n\n\n\n    Accesslevel for file maintenance\n\n    Access-level entered as minimum required to enter File Maintenance meny.\n\n\n\n    Accesslevel for Award/Nuke\n\n    Access-level entered as minimum required to Award and Nuke uploader.\n\n\n\n    Accesslevel for Copy/Move/Delete file\n\n    Access-level entered as minimum required to be able to copy, move and\n   delete a file.\n\n\n\n    Accesslevel for Filecomment\n\n    Access-level entered as minimum required to be able to change the\n   file comment on the file. \n\n\n\n    Accesslevel for Storing of File_Id.Diz\n\n    Access-level entered as minimum required to be able to save the\n   filedescription in the archive''s File_Id.Diz as well as the dirlist.\n\n@Endnode\n@Node AUTHOR "The Author of Express Manager"\n\n    Registration of Express Manager results in getting rid of the\n   extra commentline added in the fildirlisting. The price for this\n   function is 100:- skr or $20 .\n\n    If You want to contact me to register, report eventual bugs or suggestion,\n   you can either send snailmail to:\n\n      Jonas Niklasson\n      Augustenborgsgatan 8C\n      214 47 MALMOE\n      SWEDEN\n\n    Or call me at +46 (0)40 893 98\n\n    Or call the @{" Support BBS " link BBS}.\n\n\n    At the support BBS, You are certain to find updates and other programs,\n   doors and utilities which a create.\n\n@Endnode\n@Node HIST "History"\n\n   V1.0 - The platform of the Express Manager completed.\n          Thanks to Benny Bengtsson and the users of South Side BBS\n          for the Beta-testing!\n\n   V1.1 - Changed to conference-selection to a scroll window.\n   \n   V1.2 - Added online help.\n\n   V1.3 - Changed the memory allocation table.\n\n   V1.4 - The temporary dirlist is now created on the current conference\n          instead of RAM: to save memory usage.\n        - Fixed insertbug in View/Edit logos.\n        - Added support for Conference Accounting\n        - Added save option for File_Id.Diz\n        - Added support for ZIP\n\n\n@Endnode\n@Node BBS "Support BBS"\n.--------------------------------------------------------------------------.\n| ¤                      ENJOY THE PD EXPERIENCE AT                      ¤ |\n|                                                                          |\n|.::::::: .::::::. :::   ::::::::: :::  :::  .::::::: ::: :::::::. .:::::::|\n|:::           ::: :::      :::    :::  :::  :::      ::: :::  ::: :::     |\n|`::::::. :::  ::: :::  ::: :::    ::::::::  `::::::. ::: :::  ::: `::::   |\n|     ::: :::  ::: :::  ::: :::    :::  :::       ::: ::: :::  ::: :::     |\n|:::::::'' `::::::'' `::::::'' :::    :::  :::  :::::::'' ::: :::::::'' `:::::::|\n|                                                                          |\n|               »»» ONLY FREELY REDISTRIBUTABLE SOFTWARE «««               |\n|   M               ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯               M   |\n|   o          FREEWARE/SHAREWARE/GIFTWARE/PUBLIC DOMAIN etc.          o   |\n|   T                        !! MEMBERS ONLY !!                        T   |\n|   o                           ¯¯¯¯¯¯¯¯¯¯¯¯                           o   |\n|   R        SYSTEM :                        OPERATING SYSTEM :        R   |\n|   o        ··················································        o   |\n|   L        => Amiga 3000 Tower/030 25mhz   => OS Release 3.1         L   |\n|   a        => 12.0 Gigs of Disk Storage    => Kickstart V40.70       a   |\n|               inc/cdrom                    => Workbench V40.42           |\n|   I                                                                  I   |\n|   n    THIS BBS IS FOR AMIGA USERS AND IS BASED UPON *FRIENDSHIP*    n   |\n|   S                                                                  S   |\n|   ¡    THIS BBS WILL NOT ACCEPT ANY ACT OF CRIME OR ANYTHING LIKE    ¡   |\n|   D   SOFTWARE SWAPPING AGAINST ANY LAW OF SWEDEN OR EUROPEAN LAW.   D   |\n|   e          IF YOU WANT PIRATED SOFTWARE, LOOK ELSEWHERE!!          e   |\n|                        *REMEMBER PIRACY IS THEFT*                        |\n| ¤ Node: 1 - +46-(0)40-939205 - 28.8   Node: 2 - ??-?????-?????? - ??.? ¤ |\n`--------------------------------------------------------------------------''\n@Endnode\n','\n',char(10)),NULL,NULL,93676,1,0,NULL,NULL,'ss_em14','scan',1780048749);
INSERT INTO door_catalog VALUES('st_mav10','ST-MAV10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ST-MAV10.LHA','Status','XIM','Status',NULL,'Maverick!','ST','/_/  \\_   \ \ __// \/ _____   \ \   /  2 / \    \/\___\/ \ _\/ \ \   \\___\/ _/___0 _/   \/   \ __/ \  \/ \  \_\  / __/ \ \   /0',replace('    __/\ _____  _____ _  _________  _____\n   /_/  \\_   \ \ __// \/ _____   \ \   /  2\n  / \    \/\___\/ \ _\/ \ \   \\___\/ _/___0\n_/   \/   \ __/ \  \/ \  \_\  / __/ \ \   /0\n\____/ ©ron\_\   \____/___/__/___\   \___/ 0\n+===/_______/=\___/==(pRESENTs)===\___/====+\nUserDoor 1.0 TIMETRACE Release By Maverick!','\n',char(10)),'CO.TXT',replace('\nHey, [33mCoSysa[0m how are Ya!?! Nice Having You Here...\n','\n',char(10)),NULL,'auto-added',22667,2,0,NULL,NULL,'st_mav10','scan',1780048749);
INSERT INTO door_catalog VALUES('st_se_mo','ST-SE-MO.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ST-SE-MO.LHA',NULL,'XIM','sonnencreme.exe',NULL,NULL,'ST','fuer /X 3.xx und oder hoeher Version 0.05',replace('Setzen der Modeme wie sich es gehoert \nfuer /X 3.xx und oder hoeher\nVersion 0.05 \n\n','\n',char(10)),'FUN-AMI.DOC',replace('-------------COMMERCIAL BREAK-------------------------------------------------\n                 ___  _  _  _  ____  __  _____  ____________\n          _/\_  /   \/.\/ \/ \/ __/ /  \/ __/ \/\_   _/_/ . \ _/\_\n          \__/ /  /\/ _ \/\/\ \ _/ /  \/  _/    //  / _/    / \__/\n               \___/\/ \/ ¡££\/__/ \___/\__//\_//__/\__//\__\\n\n                            Game Center Ansbach\n\n------------------------------------------------------------------------------\n                            Hello, my friends!\n\n        This is Joker/ZigZagCorporation making a nice announcement\n             that will change the world as we know it forever!\n\n            (Well, almost... Actually.. uh... I think the world\n             won´t cease to exist if you don´t read this text!)\n\n----------------------------------------------------------------------------\n\nThis may be of interest to all of you who are interested\ninto the following things:\n\n- Public Domain, Shareware and Freeware software for\n  all Amigas, IBM/PC-compatibles and SuperNintendo\n\n- Sharing and gaining knowledge in coding and meeting\n  with famous coders from all over the world\n\n- Buying and selling all kinds of hardware and software\n  for AMIGA, IBM, SNES, SEGA, ATARI, C64, NEO-GEO, PC ENGINE,\n  GAMEBOY, LYNXX, GAMEGEAR, and whatever else there exists\n\n- Sound modules composed by famous scene-musicians and professional\n  Gamesoundtrack-composers\n\n- 100% virus- and backdoorfree Ami Express and Sigma Express Doors\n  (personally checked and/or approved uploads by the coders themselves\n\n- Buying the latest japanese MANGA- ANIME VHS/PAL\n  movies in english language (work on every european PAL-VCR!)\n\n- Buying several fandom articles like Manga-Baseballcaps,\n  Mr. Spock underwear, Akira metal pins, stickers \n  and whatever else there exists\n\n- The latest free distributable previews of new commercial\n  distributed games and tools from many wellknown software\n  companies all over the world\n\n- Tips, Tricks, Solutions, Patches and Cheats for tons of\n  new and old games for almost all systems\n\n- Online games like Space Empire, Yuppie Wars, Ansi Warriors\n  and much more\n\n----------------------------------------------------------------------------\n\n                 Enough to interest you for a quick call?\n                           I certainly think so.\n\nBut now some of you may think: "Where is the drawback in all this?"\n\nSimple: THERE IS NO DRAWBACK IN THIS OFFER!\n\n- Every new user calling gets access IMMEDIATELY! No waiting!\n- No phonenumbers are required to give\n- No money has to be paid for "membership" or for downloading \n  all the available software\n- Friendly chattable sysops aid you in your everlasting quest\n  for tips and help to all kinds of computer-related problems\n- Multinode chat ability to chat with other users online on\n  other nodes\n\n----------------------------------------------------------------------------\n\nAll you have to do is to call the following number:\n\nFrom foreign countries: +49-981-970900\nFrom Germany:              0981-970900     \n\nThis number is the Ringdown # for Node 1+2 currently\ninstalled (more to come soon!)\n\n                  Node 1: US Robotics 16.8 Dual Standart\n                  Node 2: US Robotics 14.4 Dual Standart\n\n             Allowing connections from 9600 - 16800 baud/bps!\n\nThe system is running on the latest version of Sigma Express\nand is very easy to use, even for people with almost no\nexperience in the usage of a Bulletin Board Systems (BBS).\n\nCall now and become a member to what soon will soon be\nknown as one of Germany´s most frequented and liked\nLEGAL Mailbox systems!\n\n          Your host Joker and his bunch of willing Mistresses is \n                            awaiting your call!\n','\n',char(10)),NULL,'auto-added',20717,5,0,NULL,NULL,'st_se_mo','scan',1780048749);
INSERT INTO door_catalog VALUES('st_sfl11','ST-SFL11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ST-SFL11.LHA','FILENOTE','XIM','FILENOTE',NULL,NULL,'ST','__________l   \____ .____________\_ ________     __/___________. |::::::::::::Y______  Y      Y:::::::::::::|',replace('                       .___\n             __________l   \____\n.____________\_ ________     __/___________.\n|::::::::::::Y______  Y      Y:::::::::::::|\n|::::::::::::l__  /   .__    !sT:::::::::::|\n||¯¯¯¯¯¯¯¯¯¯¯¯ \______| \____|¯¯¯¯¯¯¯¯¯¯¯¯||\n|| sUPERTOUCH/qTX! bRINGS yA tHIS /X uTIL ||\n:| --» sUPER-fREE-LEECH v1.o1 1ST rELEASE |:\n.| ----» mAKES cERTAIN cONFERENCES aND/oR |.\n.! ------» gROUP rELEASES fREE dOWNLOADS! !.\n :........................................:\n','\n',char(10)),'FREE.DOC',replace('                 ____________.____________________________\n              .__\_  ______  |   __  _   __  _   __  _   /__.\n              |::Y____   Y   |   Y   !   Y   ____Y   |   Y::|\n              |::|   !   |   !   |   ____|   !   |   |   |sT|\n              ¯¯¯l_______l_______l___|   l_______l___|¯¯¯¯¯¯¯\n                    .__.                         .__.\n                 ___|  |____________.____________|  |____\n              .__\___   __  _   __  |   __  _   __  _   /___.\n              |::::Y    Y   |   Y   |   Y   |___Y   |   Y:::|\n              |::::|    |   !   |   !   |   !   |   |   |:::|\n              ¯¯¯¯¯l____l_______l_______l_______l___|___|¯¯¯¯\n\n               bringin'' it down with another /X bit for you!\n\n           this time it is called (for want of a better name..)\n\n                          ! sUPER-fREE-LEECH !\n\n\nWhat?\n\nSimple... (as are most of my ideas). All it does is make files\nfreely downloadable if they fit the criteria.. ie if they are either\na special group release (eg QTX-#?) or if it has been uploaded into a\nconference that you can designate as a "FREE DOWNLOAD" conference.\nSupports up to 100 free-leech conferences and 100 group prefixes. (Should\nbe enough, right?)\n\nWhy?\n\nI wanted one and couldnt find one. Sorry if I''ve stepped in on your turf\nif you have made one already!\n\nWhere?\n\nMy underground dungeon that I call `home''. No place like it (probably just\nas well!)\n\nWhen?\n\nStarted on the 25th of August 1994. It''s now the 25th of August 1994 (still).\nAlright, so I''ve been adding bits in since then, but the bulk of the code is\nstill the stuff that took a couple of hours!\n\nHow?\n\nInstall the files that you have unpacked from the archive into their proper\ndirectories. It should be easy enough to work that out. If you''ve installed\na few /X utils before, then you should have no problem doing the same with\nthis one!\n\nPersonal Configuration?\n\nYes! There''s a few (very easy) things you will have to do to in order\nto get it working properly on your set-up.\nSo load up CED (why use anything else?) and load in the file "FREE.CFG"\nthat came with the archive - you should''ve put it in DOORS:SUPERTOUCH/\n\nAlright..lets get to work! In the example FREE.CFG file, the first 3 lines\nare taken up by file prefixes. Any file that has this prefix will be made\na free-download for anyone else. You may have up to 100 different file\nprefixes in your config file. This option is obviously (?) for boards that\nwant their group releases as free-downloads.\n\nThe line after your last file prefix must have the first 4 characters as\n****\nelse this utility wont work properly.\n\nThe next line(s) are the names of the conferences that allow free-downloads\n(These names are the ones used in the BBS:ConfConfig.info icon)\n\nYou may have up to 100 different conference names here.. (yes, pointless\nhaving that many, I know! But who cares?)\n\nThe line after your last canference same must have the first 4 characters as\n****\nelse this utility wont work properly. (Deja Vu?)\n\n\nThe following 5 lines are to do with text configuration.\nYou can change the language or whatever, its up to you! Neato!\nAll text must be between |''s, this is so you can have trailing & preceeding\nspaces in the text lines.\n\n\n  1) Text that is displayed to show what conference the user is in.\n\n  2) Text that is displayed when the file does not fit the criteria\n     of being made a free-leech file.\n\n  3) Text that is displayed when the file is released by a certain\n& 4) group (with a certain filename prefix.. eg QTX-   )\n     The included example would output..\n\n     < qUARTEX rELEASE! - mAKING xxxxxxxxx a fREE-LEECH! >\n\n     where xxxxxxxxx is the name of the uploaded file.\n\n  5) Text that is displayed when the file is uploaded into a free-leech\n     conference (all uploads into it are made free-downloads)\n\n\n\nOkay...that''s it.. if all is going well, then when someone uploads a file,\nit will go into sUPER-fREE-LEECH, and do its stuff.\ns.F.L has only been tested on /X 4.3, so I cant guarentee it''ll work on\nanything else...\nI dont expect you''ll have any problems with this since it is all very basic.\nIf however you do experience that it isnt working properly, and you think\nyou''ve followed the instructions properly, then track me down and get me to\ncheck it out.\n\nNOTE2: If you use a filechecker/stripper such as MasterStripper from\n       Delusion that adds a comment to the checked file, after\n       sUPER-fREE-LEECH has run through and added one, it will\n       not work. IE.. it WONT give the user free-downloads.\n       All I can suggest is you change strippers (you know the sort I mean) :)\n       A pity since MasterStripper is nice.\n\nNOTE2: sUPER-fREE-LEECH will not add a comment into DIRx.. like some other\n       utils. I cannot see any way to do this...yet. :)\n\nEND BITS:\n\nIf anyone has any suggestions to improve this small, versatile, courageous,\nyet kind-hearted little AREXX-MUTHA-FUCKA, then get in touch with me somehow!\nI shouldnt be too hard to track down.. just ask your local QTX member!\n\nAnyone want a GUI configurator for sUPER-fREE-LEECH? :)\n\n\n\n\n            THANKS AND GREETZ Gø øUT Tø ALL QUARTEX MEMBERS!\n                                             .___.\n        ______________.______________________|   l______________.____\n  ._____\_  __  ___   |  ___  __  ___  __  ___   ___  _______   l  _/______.\n  |:::::Y    |   Y    |   Y   ___  Y    |   Y     Y    ____Y   __   Y::::::|\n  |:::::|__  !   .__  !   .__  |   .__  |___.__   .__  !   .__  |   |::::::|\n  |:::::::\__.   |:\______|:\__|   |:\__|:::::\___|:\______|:\__|   |sT::::|\n  `----------;   `-------------;   `----------------------------;   `------''\n\n              ADDITIøNAL GREETZ Gø Tø THESE AMIGA SCENE GUYZ:\n\n      ^ kID aFRIKA ^ pUZZLER ^ sLIME ^ tHE wHITE kNIGHT ^ nO lIMIT ^\n\n         ^ aBRASAX ^ mARKSMAN ^ pARANOID ^ gAZZER ^ gREEN bERET ^\n\n             ^ jORDAN ^ sAL-ONE ^ sKEPTICAL ^ jESTER ^ G.E.M ^\n              \n                    ^ sTUSSY ^ sHOCK-G ^ mAZ ^ eARWAX ^\n\n                  ^ aLL vEGANS / vEGETARIANS oUT tHERE! ^\n\n            ^ aND nO dOUBT aNOTHER 50+ tHAT I hAVE fORGOTTEN! ^\n\n\n\nEnd of that crap.. now for some karaoke...\n\n\nDEAD WRONG  - INTEGRITY\n¯¯¯¯¯¯¯¯¯¯    ¯¯¯¯¯¯¯¯¯\n\nWHAT APPEARED TO BE SO INNOCENT\nJUST A FRONT TO COVER YOUR LIES\nYOU HAD IT ALL PLANNED FROM THE START\nTHEIR LOSS TO YOUR GAIN\nYOU DIDNT THINK IT OVER TOO CLEARLY\nBECAUSE YOU WERE...\nDEAD WRONG\n¯¯¯¯¯¯¯¯¯¯\nNO AVOIDING WHAT MUST BE DONE\nFIGHT TO WIN FIGHT TO OVERCOME\nYOU HAVE NO CHOICE OF WHAT YOU CAN DO\nENJOY THE PAIN AS IT SEERS THROUGH YOU\nTHERE WILL BE NO SECOND CHANCES\nNO ESCAPE THIS TIME\nGO AHEAD AND RUN\nTHERE''S NO PLACE YOU CAN HIDE\nWE''LL HUNT YOU DOWN\nTRACK YOU DOWN\nSO YOU KNOW EXACTLY\nHOW YOUR PREY FELT\nTHOUGHT IT WAS JUST A SIMPLE SPORT\nIN MY EYES YOU''RE JUST A MURDERER\nYOU DONT KILL FOR SURVIVAL\nYOU KILL FOR CRUELTY\nYOU WENT FROM BEING THE HUNTER TO BEING THE HUNTED\nYOU ARE DEAD...\n\nJust for you G.E.M :)\n','\n',char(10)),NULL,'auto-added',9351,1,0,NULL,NULL,'st_sfl11','scan',1780048749);
