INSERT INTO door_catalog VALUES('stn_a332','STN_A332.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/STN_A332.LHA','ACP','XIM','ACP',NULL,NULL,'STN','(_)_/ __|_   _/ __ \ \| |/ __ \''94 | StoNe! \___   \  \  \/ /    |  ___/ _  | Strikes /______/\__\___/  |\_|\___| (_) | With:',replace(' _   ________________ : : ____     :\n(_)_/ __|_   _/ __ \ \| |/ __ \''94 | StoNe!\n   \___   \  \  \/ /    |  ___/ _  | Strikes\n   /______/\__\___/  |\_|\___| (_) | With:\n==================|  |=============:========\n AMI EXPRESS 3.32 :  : REGISTRATION & CHECK \n 100% REMOVED - NEW CONNECTION BANNER WHICH\n ONLY DISPLAYS BBSNAME,LOCATION,NODE & BAUD\n','\n',char(10)),'STN-A332.DOC',replace('                 _   ________________ : : ____      \n                (_)_/ __|_   _/ __ \ \| |/ __ \''94 \n                   \___   \  \  \/ /    |  ___/ _  \n                   /______/\__\___/  |\_|\___| (_) \n==================================|  |===================================\n\n                          P R E S E N T S :\n\n                          AMI EXPRESS V3.32\n      *    REGISTRATION & REGISTRATION CHECK 100% REMOVED!\n      *    CONNECTION BANNER SLIGHTLY MODIFIED TO THE BETTER! \nEX:\n=========================================================================\nF2_LOCAL\n\nWelcome to BBS-Name, located in Houston,Texas\nYou are connected to Node 0 at 57600 baud\n\n[RETURN]\n\nEnter your Name: \n=========================================================================\n     THIS VERSION IS 100% FREE FROM BACKDOORS AND STUFF LIKE THAT!\n','\n',char(10)),NULL,'auto-added',147178,5,0,NULL,NULL,'stn_a332','scan',1780048759);
INSERT INTO door_catalog VALUES('stn_a335','STN_A335.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/STN_A335.LHA','AmiXnetBase','XIM','_   ________________ : : ____     :',NULL,NULL,'STN','(_)_/ __|_   _/ __ \ \| |/ __ \''94 | StoNe! \___   \  \  \/ /    |  ___/ _  | Strikes /______/\__\___/  |\_|\___| (_) | With:',replace(' _   ________________ : : ____     :\n(_)_/ __|_   _/ __ \ \| |/ __ \''94 | StoNe!\n   \___   \  \  \/ /    |  ___/ _  | Strikes\n   /______/\__\___/  |\_|\___| (_) | With:\n==================|  |=============:========\n AMIEXPRESS V3.35 - REGISTRATION CHECK 100%\n REMOVED! - FULL PACKAGE WITH DOCUMENTATION\n    AND COMPLETE SETUP INCLUDING AMIXNET\n','\n',char(10)),'AmiExpress.Guide',replace('@database AmiexDoc\n\nCopyright (c) 1993 Light Speed Technologies\nAll Rights Reserved\n\n@Remark $VER: (June 21 1993, 09:06:01)\n@Remark AmigaGuide database for the /X Documentation\n\n@node MAIN "/X Documentation (c)1993 L.Speed Technologies (June 21 1993, 09:06:01)"\n           .: C O N T E N T S  O F  D O C U M E N T A T I O N :.\n\n    @{" Introduction                 " Link Cap01}    @{" Copyrights Information       " Link Cap02}\n    @{" Requirements                 " Link Cap03}    @{" Installation of Amiexpress   " Link Cap04}\n    @{" How to install Configs       " Link Cap05}    @{" How to configurate Startup   " Link Cap06}\n    @{" All ToolTypes Informations   " Link Cap07}    @{" The Standard Documentation   " Link Cap08}\n    @{" Programlogic of AmiExpress   " Link Cap09}    @{" MainMenu Commands of /X      " Link Cap10}\n    @{" AmiExpress HOST Adresses     " Link Cap11}    @{" MCI imbedded ControlSequence " Link Cap12}\n    @{" Noteable Features            " Link Cap13}    @{" Note worthy of Mention       " Link Cap14}\n    @{" Trouble Shooting             " Link Cap15}    @{" Future planned Enhancements  " Link Cap16}\n    @{" 3.31+ Updates                " Link Cap17}\n\n          -------------------------------------------------------\n          Complete run-thru Doc for AmiExpress Professional v3.6\n          -------------------------------------------------------\n  Documentation written by Jens Langner (/X DocWriter).\n  Edited and updated by The Outlaw.\n  Copyright (c) 1993 Light Speed Technologies.  All Rights Reserved.\n  Any copy or illegal distribution of this Documentation is not allowed.\n\n@endnode\n@node Cap01 "Introduction & Explaination for /X"\n  =======================================================================\n  Ami-Express is a host Bulletin Board software program, allowing\n  the transfer of data, between host and remote terminals via a\n  telephone link. ( Obvious to some!! ). This data can be files\n  uploaded or downloaded from remote (user end) from the BBS\n  databases. Most Bulletin boards also contain message bases where\n  you can read and leave electronic mail to other users. It is\n  possible via some BBS`s to play online games, although these are\n  of a simple nature, they can still be quite entertaining. For\n  those of you that have been a user, either host or remote, for\n  some time, will have noticed the major changes that Ami-Express\n  has undergone. With the future proposed implementations Ami-Express\n  will soon become comparable to other Major BBS programs found on\n  Amiga and PC  computers.\n  =======================================================================\n\n@endnode\n@node Cap02 "Copyright Informations"\n  =======================================================================\n  If you own a an Illegal (Cracked copy) and you use it, then\n  consider buying the original. This will not only provide you with\n  support etc, but will encourage the further development of\n  Ami-Express.\n\n                    ------------------------------------\n                      AmiExpress, AmiX-Net, Utilities,\n                      docs, and its source code are\n               (c) Copyright 1993 by Light Speed Technologies\n\n       --------------------------------------------------------------\n        AmigaGuide, AmigaGuide.info, amigaguide.library, WDisplay,\n        WDisplay.info,\n        (c) Copyright 1992 Commodore-Amiga, Inc. All Rights Reserved.\n        Reproduced and distributed under license from Commodore.\n       --------------------------------------------------------------\n             AmiExpress is a comercial product, NOT shareware\n                      If you used it, please buy it!\n                    ------------------------------------\n  =======================================================================\n@endnode\n@node Cap03 "Requirements"\n  =======================================================================\n  To install AmiExpress V3.30 you must have the following things:\n\n    Program     Location     Description\n    ---------   --------     -----------\n    Express     BBS/Utils    Bulletin Board System\n    ACP         WBSTARTUP    Bulletin Board controller\n\n  - The Workbench should be installed to run ACP\n  - a stack of at least 50000 bytes\n  - a Amiga Model (500/600/1000/1200/2000/2500/3000/4000)\n  - the installed Version of Kickstart V2.0 (Soft or Hardware Version)\n  - at least 2 MB free Space to be able to get uploads\n  - the installed .INFO Files in the directories.\n\n  It is recommend to install AmiExpress on a Harddrive to increase\n  The Speed of AmiExpress and to have enough space for Uploading\n  software on the BBS. If you only want to test the AmiExpress Version\n  than you can install the BBS also on a Diskdrive.\n  =======================================================================\n@endnode\n@node Cap04 "How to install Amiexpress on your HardDisk"\n  =======================================================================\n  To install AmiExpress V3.30 you must have at least all the\n  Requirement which were mentioned below. Now lets going on with the\n  normal installation of AmiExpress.\n\n  Now take your registered LZH file which you downloaded from your\n  favorite Distribution Board of AmiExpress and decrunched it please\n  on a Disk or take your Disk on which AmiExpress is already installed.\n  Now you must know where you want to install AmiExpress on your hard-\n  drive. To explain the installation of AmiExpress much better it is\n  recommend that you install the whole AmiExpress into the BBS:\n  Directory on your Harddrive. If this Directory doesn''t exists you\n  have to make it on your Harddisk.\n  Now take your AmiExpress disk and take a look an it and you will\n  see the following things:\n\n  -------------------------\n       S (dir)\n       libs (dir)\n       Trashcan (dir)\n       BBS (dir)\n     BBS.DOX\n     REVISE.DAT\n     Trashcan.info\n  -------------------------\n\n  Now you must know how many Conferences do you want to install in your\n  bbs. Now i will explain you to install the new Express V3.6:\n\n  - The whole amiex can only be run if the Workbench has been installed\n    and the ACP has been started of Workbench otherwise express can`t be\n    installed.\n  - The whole way of installing Amiex has been changed from V2.30 till\n    V3.6. There is no longer an ACP.STARTUP to configurate your whole bbs.\n  - Now you need an .INFO files for every configuration.  This will be\n    described in the next section.\n  =======================================================================\n@endnode\n@node Cap05 "The Way to install the Configuration Files"\n  =======================================================================\n  The .INFO Files take now totally control over the express system. The\n  whole ACP.STARTUP has now been changed to single INFO Files where you\n  put in the configuration. First of all make sure you installed the\n  workbench, otherwise you can`t install the Amiex V3.6 version.\n\n  For further information look at the section which describes all info\n  files for installing amiex. But first you must decide how many nodes\n  you want to install to configurate your express the right way.\n\n  We highly suggest that you store AmiExpress and all associated\n  programs in a volume called BBS: this simplifies finding\n  any probs you may have. Installing AmiExpress is fairly complicated\n  so please be patient, even those who have run earlier version of\n  AmiExpress should notice a lot of setup changes, Therefore there\n  will not be any quick setup instructions.\n  =======================================================================\n@endnode\n@node Cap06 "How to install Express in your Startup"\n  =======================================================================\n  In order to get AmiExpress work perfectly you have to add the following\n  things at your User-StartUp or Startup-Sequence file in the S:\n  directory:\n\n   -----cut here-----------\n\n   ASSIGN BBS: SYS:BBS\n   PATH BBS:UTILS ADD\n\n   -----cut here-----------\n\n  Now to start the ACP.SERVER you should copy the ACP.CTRL & INFO FILE\n  into the WBSTARTUP directory at your harddisk directory.\n\n  You can also start ACP from a shell but the INFO file MUST be in the\n  same directory as ACP to have the correct settings.\n\n  The above mentioned ASSIGN statement indicates that you have your\n  BBS installed in a directory called BBS on the system drive.\n\n  Once all of this is complete you should be able to reset your system.\n\nNOTE: You should have a BBS:Utils directory. Use this directory to\n~~~~  put all amiexpress required utils.\n  =======================================================================\n@endnode\n@node Cap07 "ToolTypes in ICONS to run Amiex..."\n  =======================================================================\n     To run Amiex you need a lot of ICONS containing in different\n     directories. This ICONS contains much of information to run /X.\n     This Informations are stored as TOOLTYPES. Now i will list you\n     all needed ICONS and the depending TOOLTYPES for it. To change\n     the configuration of your BBS you should click on the icon and\n     go with the right mousebutton to the workbench menu to view the\n     information of the ICON. There you will find the TOOLTYPES\n     to configurate your personal Amiexpress. for better information look\n     at the example icons on disk.\n\n    @{" ACP.INFO ICON                " Link Cap0701}    @{" NODE(x).INFO ICON            " Link Cap0702}\n    @{" <CONF>.INFO ICON             " Link Cap0703}    @{" CONFCONFIG.INFO ICON         " Link Cap0704}\n    @{" DRIVES.INFO ICON             " Link Cap0705}    @{" SCREENTYPES.INFO ICON        " Link Cap0706}\n    @{" COMPUTERLIST.INFO ICON       " Link Cap0707}    @{" NAMESNOTALLOWED.INFO ICON    " Link Cap0708}\n    @{" PROTOCOLS <Directory>        " Link Cap0709}    @{" ACCESS.INFO ICON             " Link Cap0710}\n    @{" FCHECK    <Directory>        " Link Cap0711}    @{" NODE(x)   <Directory>        " Link Cap0712}\n    @{" COMMANDS  <Directory>        " Link Cap0713}    @{" STORAGE   <Directory>        " Link Cap0714}\n\n  =======================================================================\n@endnode\n@node Cap0701 "DH0:WBSTARTUP/ACP.INFO ICON ToolTypes Informations"\n  =======================================================================\n  ACP.INFO          - This ICON only represents the definition to\n  ~~~~~~~~            ACP, and required data for the BBS to operate\n                      and locate the other definition files.\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  NODES=1            - Tells ACP how many Nodes do you have\n  ICONFIED           - Will toggle ACP to start iconfied or not\n  ICONIFY.LEFTEDGE=  - tells ACP the number of pixels from the left edge\n                       of the screen to place iconify window.\n  ICONIFY.TOPEDGE=   - tells ACP the number of pixels from the top edge\n                       of the screen to place the iconify window.\n  BACKUP.<num>=      - tells ACP to make backup from specified file. A\n                       history of 5 backups will be made. <num> is the\n                       nth occurrence of this tooltype.\n  RESTRICT.<num>=    - tells ACP to place a filenote on the specified\n                       file. This prevents users from viewing or\n                       downloading the restricted files.\n  BUTTON_NAME.<num>= - defines the name of the specified button, the\n                       <num> can range from 1-15.\n  BUTTON_COMMAND.<num>\n                     - defines the command to be executed when this\n                       button is selected, <num> can range from 1-15.\n  NUTTON_NAME.<num>= - defines the name of the specified nutton, the\n                       <num> can range from 1-15.\n  NUTTON_COMMAND.<num>\n                     - defines the command to be executed when this\n                       nutton is selected, <num> can range from 1-15.\n                       All NUTTONS will be passed the selected NODE\n                       number as a command line argument.\n  PRIORITY= <num>    - Specifies the taskpriority for ACP to run.\n  BBS_NAME= <name>   - Specifies the name of your BBS.\n  BBS_STACK= <stack> - Specifies the STACK number of your System.\n  BBS_LOCATION= <dir>- Specifies the location of all BBS main files.\n                       This directory will be the directory where the\n                       Node(x) directories should be. Along with all\n                       of the .DEF files.\n                       If the location is a directory, then the directory\n                       name must have trailing ''/'' when specified in the\n                       tooltype.\n  BBS_GEOGRAPHIC=<geo> Specifies the Geographic position of Your BBS\n                       this will be mentioned in the LOGON Sequence...\n  SYSOP_NAME= <name> - Specifies your name.\n  MULTICOM_PORT      - If this tooltype is placed the MULTICOM PORT\n                       of amiexpress is turned on for multinode systems.\n  SHORT_DONOTMOVE    - if this tooltype is placed, then if the ''/X'' gadget\n                       is selected your ACP window will not move.\n  NODE<x>_LOCATION=  - This lets you specify the location of a given node\n  NODEx_NAME=<string>- This lets you specify a name for your node, the\n                       default is the same as the BBS_NAME\n  NODEx_SYSOP=<string> This lets you have a different sysop per node, this\n                       should effect comment to sysop and paging the sysop.\n                       The default is BBS_SYSOP.\n  NEW_ACCOUNTS=APPEND- This tells ACP to ADD new User to the End of\n                       the Databases.\n  =======================================================================\n@endnode\n@node Cap0702 "BBS:Node(x).INFO ICONS ToolTypes Informations"\n  =======================================================================\n  NODE(x).INFO       - This Icon will specify some information about\n  ~~~~~~~~~~~~         how to install the Node in amiex. (x) = Nodenumber\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  NODESTART=         - tells ACP where Express is located to start node.\n  IDLENODE           - tells ACP not to start the node and wait for click\n  BATCH.LOGOFF=      - tells ACP where the LOGOFFbatch is located. This\n                       Batch will be executed every time a user logs off\n                       from the specified node.\n  BATCH.SHUTDOWN=    - tells ACP to run a script file when the node is\n                       shutdown.\n  TRAPDOOR           - tells ACP that this node is going to run Express\n                       indirectly via another program. If this option is\n                       used then you should specify the program to be run\n                       externally in the NODESTART= tooltype.\n  PLAYPEN= <dir>     - tells ACP that this node is going to use a sysop\n                       directory for initial uploads to go into.\n                       !! USING RAM: FOR THIS IS HIGHLY DISCOURAGED !!\n                       You must create this directory for running.\n  STEALTH_MODE       - This will have express ask for the system password\n                       before the connect message and bbs name.\n  SYSTEM_PASSWORD=   - tells ACP that this node is going to require users\n                       to enter a password before allowing access to the\n                       system.\n  SYS_PWRD_PROMPT=   - This tooltype lets you specify the prompt to use\n                       for the system password prompt. default is >:\n  NAME_PROMPT=       - This tooltype lets you specify the prompt to use\n                       for the login procedure.\n  REMOTE_PASSWORD=   - tells ACP that a user is required to enter the\n                       specified password prior to gaining access to\n                       SHELL.\n  NEWUSER_PASSWORD=  - tells ACP that a user is required to enter the\n                       specified password prior to join as a new user.\n  PRIORITY= <num>    - tells ACP the priority for this Node in respects\n                       to the system.\n  QUIETNODE          - tells ACP to make this node quiet to the WHO\n                       command, and some 3rd party modules.\n  SENTBY_FILES       - tells /X that you wish to have user`s handle\n                       placed at the end of his/her files descriptions.\n  CHAT_ON            - tells /X that the node should have the CHAT FLAG\n                       ON, when the node is started.\n  CAPITOL_FILES      - tells /X to make all upload files names UPPER_CASE\n                       letters.\n  SYSOP_CHAT_COLOR=  - tells /X which ANSI color to use when display the\n                       Sysops Chat. (Range 31-37)\n  USER_CHAT_COLOR=   - tells /X which ANSI color to use when displaying\n                       the User`s Chat. (Range 31-37)\n  KEEP_UPLOAD_CREDIT=\n                     - specifies the user which upload credit will be\n                       kept if he downloaded something.\n  CALLERS_LOG        - tells /X to record all events to a file called\n                       CallersLog in the node directory.\n  UD_LOG             - tells /X to record all uploads & downloads to a\n                       file called UDLOG in the node directory.\n  DOOR_LOG           - tells /X to record the start and end time for\n                       Module use.\n  START_LOG          - tells /X to record the start & end times of the\n                       NODE.\n  NO_TIMEOUT         - tells /X to disable the keyboard timeout option.\n  NO_MCI_MSG         - tells /X to disable the ability to use MCI\n                       commands in the message base.\n  DISABLE_QUICK_LOGONS\n                     - Allows you to prevent a user from using the\n                       skipping of the Logon/offtexts in your BBS.\n  SCREENS=<location> - This will tell express to use one common area\n                       for locating .txt files, if you use this option for\n                       conferences, then you will need to have a\n                       bulletins drawer in that directory as well so the\n                       bulletins can be found.\n  FILESNOTALLOWED=<pathname>\n                     - <pathname> is a full path and file name to a ascii\n                       file which lists filenames you do not wish uploaded\n                       to your system.\n  FREE_RESUMING      - This tells Express to allow the FREE RESUMING of\n                       uploaded files for ALL Users in the BBS.\n  BREAK_CHAT         - This tells Express to allow the breaking out of\n                       the Sysop Chat by pressing CTRL-C for ALL users.\n  NO_WILDCARD_EXPANSION\n                     - This tells Express to don`t allow the using of\n                       wildcard expansions (*) in the specified NODE.\n  VIEW_PASSWORD      - This tooltype will allow you to see what users are\n                       typing in for there passwords and new user\n                       passwords.\n  USERDATA_NAME=<pat>- This lets you specify an alternate location for\n                       your user.data\n  USERKEYS_NAME=<pat>- This lets you specify an alternate location for\n                       your user.keys\n  PHONECHECK         - If this tooltype is activated, express will ask\n                       for the 4 last digits of the specified user\n                       phonenumber at every logon.\n  RINGCOUNT=<rings>  - This tooltype will instruct the node, to what the\n                       specified number of rings to come accross the modem\n                       sequentially before answering the modem.\n  TRAP_SERIAL        - This will Trap the A2232 Error Messages\n  DEBUG_LOG          - This turns on the DEBUGGING Log for Express\n  RAMWORK            - This tells the Node not to check for FREE SPACE\n                       like when wanting to use RAM: for Playpen.\n  CONF_DB=<string>   - This tooltype will specify the filename\n                       (not filepath) to use when loading msgbase pointers\n                       for a given node. The default is CONF.DB\n  =======================================================================\n@endnode\n@node Cap0703 "BBS:<CONF>.INFO ICON ToolTypes Informations"\n  =======================================================================\n  <CONF>.INFO        - This Icon will specify some information about\n  ~~~~~~~~~~~          how to install the Conference. <CONF> = ConfName\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  CUSTOM             - This will tell express that THIS conference is\n                       using AmiXNET Mail.\n  SCREENS=<location> - This will tell express to use one common area\n                       for locating .txt files, if you use this option for\n                       conferences, then you will need to have a\n                       bulletins drawer in that directory as well so the\n                       bulletins can be found.\n  NDIRS= <num>       - Required for all conferences which allow file\n                       transfers. Specifies the number of file catalogs\n                       for the conference.\n  DLPATH.<num>=<str> - Required for all conferences which allow downloads\n                       and file viewing. Specifies the directory of files\n                       available for downloading. <num> is the nth\n                       occurrence of the DLPATH tooltype.\n                       If the download path is a directory then the\n                       directory name in tooltype must have a\n                       trailing ''/''.\n  ULPATH.<num>=<str> - Specifies an overflow directory for uploads to goto\n                       , this is useful in instances where the default\n                       upload directory does not room for anymore files.\n                       <num> is the nth occurance of the ULPATH tooltype.\n                       If the upload path is a directory then the\n                       directory name in the tooltype must have a\n                       trailing ''/''.\n  FREEDOWNLOADS      - Tell /X that the current conference allows free\n                       downloads.\n  FORWARDMAIL= <str> - Redirects Comments to the sysop to another user.\n  MENU_PROMPT=       - This tooltype lets you specify the Menuprompt to\n                       use in this Conference.\n\n  CONFDB_SHARED=<confnum>\n                     - This tooltype allows you to tell a conference to\n                       use another conference''s CONF.DB file for storing\n                       and retrieving user''s file credits, and ratios.\n                       NOTE: ACS.CONFERENCE_ACCOUNTING is needed for this\n                       to take effect, and a CONFERENCE_ACCOUNTING account\n                       editor is required to make it worth while.\n  =======================================================================\n@endnode\n@node Cap0704 "BBS:CONFCONFIG.INFO ICON ToolTypes Informations"\n  =======================================================================\n  CONFCONFIG.INFO    - This ICON is required to be in the BBS directory\n  ~~~~~~~~~~~~~~~      This defines your conferences.\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  NCONFS= <num>      - tells /X the number of conferences your BBS has.\n  NAME.<num>=<name>  - tells /X the name of conference.\n  LOCATION.<num>=    - tells /X the location of conference (DIR).\n  RELATIVE_CONFERENCES\n                     - tells /X to only show user accessible confs vs.\n                       showing all conferences on the system.\n  =======================================================================\n@endnode\n@node Cap0705 "BBS:DRIVES.INFO ICON ToolTypes Informations"\n  =======================================================================\n  DRIVES.INFO        - This ICON should be placed in the BBS: Directory\n  ~~~~~~~~~~~          Here you place in your Upload directories.\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  DRIVE.<num>=<name> - tells /X which drives to use in determining free\n                       space for uploads. <num> is nth DRIVE tooltype.\n  =======================================================================\n@endnode\n@node Cap0706 "BBS:SCREENTYPES.INFO ICON ToolTypes Informations"\n  =======================================================================\n  SCREENTYPES.INFO   - This ICON should be placed in the BBS: Directory\n  ~~~~~~~~~~~~~~~~     Here you can put in information for different\n                       ScreenTypes like different languages.\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  TYPE.<num>=<ext>   - This specifies the Extension for the Screentype\n                       like "TXT","GER" & "ENG". you can make your own.\n  TITLE.<num>=<name> - This specifies the name of the Screentype you want\n                       to have like "AMIGA ANSI","GERMAN" & "ENGLISH".\n                       You can specify your own Title.\n  =======================================================================\n@endnode\n@node Cap0707 "BBS:COMPUTERLIST.INFO ICON ToolTypes Informations"\n  =======================================================================\n  COMPUTERLIST.INFO    - This ICON tooltypes specifies the ComputerTypes\n  ~~~~~~~~~~~~~~~~~      which the Users can select.\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  COMPUTER.NUM=<num>   - Specifies the total number of ComputerTypes you\n                         have in your BBS System.\n  COMPUTER.<num>=      - Specifies the Computerdescription the users can\n                         choose for there own User.Data.\n  =======================================================================\n@endnode\n@node Cap0708 "BBS:NAMESNOTALLOWED.INFO ICON ToolTypes Informations"\n  =======================================================================\n  NAMESNOTALLOWED.INFO - This ICON tooltypes specifies UserNames you\n  ~~~~~~~~~~~~~~~~~~~~   don`t want to use in your BBS System. In this\n                         tooltype Names like: ALL,EALL,SYSOP should be,\n                         to prevent user to log in the bbs with this Names\n                         This ICON should be placed in the BBS: directory.\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  NAME.<num>=          - Specifies the Name you want to prevent to be used\n                         in your BBS System.\n  =======================================================================\n@endnode\n@node Cap0709 "BBS:PROTOCOLS Directory Informations"\n  =======================================================================\n  Protocols.INFO       - This ICON only represents a Directory. This\n  ~~~~~~~~~~~~~~         Directory is required to be within the BBS:\n                         directory.\n\n  ABOUT: This directory will contain XPR definitions for Amiexpress.\n\n  The following list are ICONS which should be placed in this directory:\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n    @{" XPRTypes.INFO ICON           " Link Cap070901}    @{" <XFERlib>.INFO ICON          " Link Cap070902}\n\n  =======================================================================\n@endnode\n@node Cap070901 "BBS:PROTOCOLS/XPRTypes.INFO ICON ToolTypes Infos"\n  =======================================================================\n  XPRTypes.INFO        - This ICON tooltypes specify the XFER Protocols\n  ~~~~~~~~~~~~~          you want to be used for your BBS System. This\n                         ICON should be placed in the BBS:Protocols/\n                         directory.\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  TITLE.<num>=<title>  - Specifies the Title for the XFER Lib to be\n                         displayed in the BBS\n  LIBRARY.<num>=<library | INTERNAL>\n\n                       - Specifies the Library you want to use for the\n                         <num> Title in your BBS. Use "INTERNAL" for\n                         the normal AMiExpress Internal Protocoll.\n  =======================================================================\n@endnode\n@node Cap070902 "BBS:PROTOCOLS/<XFERLib>.INFO ICON ToolTypes Infos"\n  =======================================================================\n  <XFERLib>.INFO       - This ICON tooltypes specify the options for\n  ~~~~~~~~~~~~~~         for each XFERLibrary you use in your BBS system.\n                         e.g: XPRZmodem.INFO = xprzmodem.library\n                              XPRYmodem.INFO = xprymodem.library\n                         This ICON should be placed in the BBS:Protocols/\n                         directory.\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  OPTIONS=<opt>        - Allowed you to specify the Options for the\n                         XFERLibraries.\n                         e.g: OPTIONS=TN,AY,OR,KY,SN,RN,DN,F0,B32\n  =======================================================================\n@endnode\n@node Cap0710 "BBS:ACCESS.INFO ICON ToolTypes Informations"\n  =======================================================================\n  ACCESS.INFO          - This ICON tooltypes specify the access defaults\n  ~~~~~~~~~~~            assigned to a users account when he/she logs on.\n                         %References: ACS.DEF.INFO ICON\n                         These defaults can be used by using the\n                         ACS.OVERRIDE_DEFAULTS Option.\n\n  The following list are ICONS which should be placed in this directory\n  to have ACCESS Levels,AREA Names & PRESETS for the User Accounts:\n\n    @{" ACS.<level>.INFO ICONS       " Link Cap071001}    @{" AREA.<AXSName>.INFO ICONS    " Link Cap071002}\n    @{" PRESET.<x>.INFO ICONS        " Link Cap071003}\n\n  =======================================================================\n@endnode\n@node Cap071001 "BBS:ACCESS/ACS.<level>.INFO ICON ToolTypes Infos"\n  =======================================================================\n  ACS.<level>.INFO     - This ICON Must be placed in the ACCESS directory\n  <username>.INFO        and it can be the USERNAME or the Accesslevel.\n  ~~~~~~~~~~~~~~~~       i.e: ACS.010, ACS.200, ACS.255, BYTEMASTER, USER\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  ACS.OVERRIDE_DEFAULTS- OverRide access defined in the ACCESS Icon\n                         tooltypes above.\n  ACS.ACCOUNT_EDITING  - Gives Access to Account Editing\n  ACS.READ_BULLETINS   - Allows user to read the normal Bulletins\n  ACS.REMOTE_SHELL     - Allows user to gain access to the Remote Shell\n  ACS.OVERIDE_CHAT     - Allows user to OverRide the /X chat flag and\n                         successfully page the sysop.\n  ACS.OVERIDE_TIMES    - Allows user to bypass the time restrictions\n                         placed on a Node.\n  ACS.SYSOP_READ       - Allows user to read mail, regardless of whose it\n                         is.\n  ACS.SYSOP_VIEW       - Allows user to view Files like a SYSOP.\n  ACS.SYSOP_DOWNLOAD   - Allows user to make a SYSOPDOWNLOAD of any path\n  ACS.EALL_MESSAGES    - Allows user to enter EMAIL to All user that they\n                         are forced to read them.\n  ACS.LIST_NODES       - Allows user to view the Online Nodes\n  ACS.DELETE_MESSAGE   - Allows user to delete Messages\n  ACS.ATTACH_FILE      - Allows user to make a file attached to messages\n  ACS.MCI_MESSAGE      - Allows user to write MCI Messages in the BBS\n  ACS.EDIT_DIRS        - Allows user to Edit catalogs of Files\n  ACS.EDIT_FILES       - Allows user to Edit Files in your BBS\n  ACS.SYSOP_COMMANDS   - Allows user to make normal Sysop Commands\n  ACS.WHO_IS_ONLINE    - Allows user to view Nodes with "WHO" command\n  ACS.ZOOM_MAIL        - Allows user to Zoom Mailing from some message\n  ACS.COMMENT_TO_SYSOP - Allows user to leave comment to sysop\n  ACS.DOWNLOAD         - Allows user to download files.\n  ACS.UPLOAD           - Allows user to Upload files.\n  ACS.ENTER_MESSAGE    - Allows user to enter messages.\n  ACS.FILE_LISTINGS    - Allows to view catalog of available files.\n  ACS.JOIN_CONFERENCE  - Allows user to Join a Conference.\n  ACS.NEW_FILES_SINCE  - Allows user to list recent catalog entries.\n  ACS.PAGE_SYSOP       - Allows user to page sysop.\n                         If the sysop page flag on express is turned off\n                         the user will be notified that you are not\n                         available.\n  ACS.READ_MESSAGE     - Allows user to read messages\n  ACS.DISPLAY_USER_STATS\n                       - Allows user to view his/her status on the system\n  ACS.VIEW_A_FILE      - Allows user to view downloadable text files.\n  ACS.EDIT_USER_INFO   - Allows a user to edit his/her account.\n  ACS.EDIT_USER_NAME   - Allows user to change his/her handle.\n  ACS.EDIT_USER_LOCATION\n                       - Allows user to change his/her location.\n  ACS.EDIT_PHONE_NUMBER- Allows user to change his/her phone number.\n  ACS.EDIT_PASSWORD    - Allows user to change his/her password.\n  ACS.ZIPPY_TEXT_SEARCH- Allows user to search the catalog for key items\n                         with the online search features of /X.\n  ACS.BREAK_CHAT       - Allows user to break the sysopchat with CTRL-C\n  ACS.FREE_RESUMING    - Allows user the free resuming of partuploads.\n  ACS.QUIET_NODE       - Allows user to make himself invisible from other\n                         nodes by the "Q" command in Main Menu.\n  ACS.RELOGON          - Allows user to make a RELOGON by pressing "RL"\n                         in the Main Menu Prompt\n  ACS.XPR_RECEIVE      - Allows user to receive file with XPR Libraries.\n  ACS.XPR_SEND         - Allows user to send files with XPR Libraries.\n  ACS.ULSTATS          - Allows user to view number of new uploads since\n                         the last SYSOP login.\n  ACS.PUB_MSGFILES     - Allows user to upload a file into the MSGBASE\n                         and to make it automatically ATTACHED to (ALL)\n                         Users with "X"Option.\n  ACS.PRI_MSGFILES     - Allows user to upload a file into the MSGBASE\n                         and to make it automatically ATTACHED to another\n                         user with "X" Option.\n  ACS.MAX_PAGES=<num>  - This will set the maximum number of pages allowed\n                         per session. If a user goes above this limit,\n                         then page sysop will be translated to Comment to\n                         Sysop.\n  ACS.CONFERENCE_ACCOUNTING\n                       - This will turn on the Conference Account for a\n                         User. So now you can define a Ratio for each\n                         Conference to each User.\n  ACS.DUPE_FILECHECK   - This will turn on the DUPE FILECHECKING after\n                         the upload for the specified user.\n  ACS.FULL_EDIT        - Allows User to use the FULLSCREENEDITOR if\n                         one is located in the SYSCMD <dir>.\n  =======================================================================\n@endnode\n@node Cap071002 "BBS:ACCESS/AREA.<AXSName>.INFO ToolTypes Infos"\n  =======================================================================\n  AREA.<AXSName>.INFO  - This ICON should be placed in the ACCESS dir\n  ~~~~~~~~~~~~~~~~~~~    it defines the Access user have to Conferences\n                         the same name should be placed in the ACCOUNT\n                         EDITING at "AREA NAME"\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  CONF.<x>             - Allows user with that AREA NAME to join the\n                         specified conference you inserted at <x>\n  =======================================================================\n@endnode\n@node Cap071003 "BBS:ACCESS/PRESET.<x>.INFO ToolTypes Infos"\n  =======================================================================\n  PRESET.<x>.INFO      - Allows you to choose PRESETS for the Account\n  ~~~~~~~~~~~~~~~        editing over tooltypes. This ICON should be\n   <x> = 1 - 7           placed in the ACCESS directory.\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  PRESET.AREA=<name>   - Specifies the AREANAME for the UserAccess that\n                         the user has access to.\n  PRESET.ACCESS=<num>  - Specifies the Access for the Preset you want to\n                         set.\n  PRESET.RATIO_TYPE=   - Specifies the RatioType for the Preset you want\n                         to set.\n  PRESET.RATIO=<num>   - Specifies the Ratio you want to have for the\n                         preset.\n  PRESET.DAILY_BYTE_LIMIT=\n                       - Specifies the Daily ByteLimit for the Preset you\n                         want to set.\n  PRESET.TIME_LIMIT=   - Specifies the Time Limit for the Preset you want\n                         to set.\n  PRESET.CONFRJOIN=    - Specifies the Conference when a User is selected\n                         with this PRESET. Then he will automatically\n                         join this conf in his next login.\n  =======================================================================\n@endnode\n@node Cap0711 "BBS:FCHECK Directory Informations"\n  =======================================================================\n  FCHECK.INFO          - This ICON only represents a Directory. This\n  ~~~~~~~~~~~            Directory is required to be within the BBS:\n                         directory.\n\n  ABOUT: This directory will contain Checker definitions for Amiexpress.\n\n  The following list are ICONS which should be placed in this directory:\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                     @{" <EXTENSION>.INFO ICONS       " Link Cap071101}\n\n  =======================================================================\n@endnode\n@node Cap071101 "BBS:FCHECK/<EXT>.INFO ICON ToolTypes Infos"\n  =======================================================================\n  <EXT>.INFO           - This ICONS are used for the FCHECK in Express\n  ~~~~~~~~~~             and should be placed in the directory BBS:FCHECK\n                         <EXT> = The Extension of Files like "DMS", "WRP"\n                                 & "LHA"\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  CHECKER=<comp.Path>  - Specifies the complete Path to the FileChecker\n                         you want to have for the extension.\n  OPTIONS=<options>    - Specifies the option you want to start with the\n                         Filechecker. THiS WiLL be put after the executing\n                         of FileChecker.\n  STACK=<num>          - Here you can specify the Stack which you want to\n                         have for the checker.\n  PRIORITY=<num>       - Here you can specify the Taskpriority on which\n                         the Filechecker will be run.\n  ERROR.<num>=<name>   - Specifies the ErrorMessage if a file is corrupt\n                         and have to move to the Hold Directory. You\n                         can specify unlimited ErrorMessages by changing\n                         the <num>.\n  SCRIPT=<script path> - This will tell express to run that script after\n                         it finishes testing the file. Once that is\n                         finished then express will go ahead and move the\n                         file to where ever.\n                         NOTE: express will pass the file name as the\n                         ~~~~  first commandline argument to the SCRIPT.\n  =======================================================================\n@endnode\n@node Cap0712 "BBS:NODE(x) Directory Informations"\n  =======================================================================\n  NODE<x>.INFO         - This ICON represents a Directory. This\n  ~~~~~~~~~~~~           Directory is required to be within the BBS:\n                         directory.\n\n  The following list are ICONS which should be placed in this directory:\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n    @{" CONNECT.DEF.INFO ICON        " Link Cap071201}    @{" WINDOW.DEF.INFO ICON         " Link Cap071202}\n    @{" TIMES.DEF.INFO ICON          " Link Cap071203}    @{" NRAMS     <Directory>        " Link Cap071204}\n    @{" SERIAL    <Directory>        " Link Cap071205}    @{" MODEM     <Directory>        " Link Cap071206}\n\n  =======================================================================\n@endnode\n@node Cap071201 "BBS:NODE<x>/CONNECT.DEF.INFO ICON Infos"\n  =======================================================================\n  CONNECT.DEF.INFO     - This ICON should be placed in the NODE<x>\n  ~~~~~~~~~~~~~~~~       directory and specifies special Connect Messages\n                         to change the BaudRate.\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  <connectmsg>=<baud>  - if the Connectmessage is the same the BaudRate\n                         will be changed to the specifies one.\n  example:\n  CONNECT 2400/ARQ/MNP/MNP5=9600\n                       - if the Connect message is the above one the\n                         hardware baudrate will be changed to 9600 baud.\n  =======================================================================\n@endnode\n@node Cap071202 "BBS:NODE<x>/WINDOW.DEF.INFO ICON Infos"\n  =======================================================================\n  WINDOW.DEF.INFO      - This ICON should be placed in the NODE<x>\n  ~~~~~~~~~~~~~~~        directory and specifies the Window Prefs of the\n                         node.\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  WINDOW_NUM_COLORS=   - Specifies the Number of Colors you want to have\n                         for the NodeWindow.\n  WINDOW_INTERLACE=    - Specifies that you want to have this window in\n                         HighRes-Interlace Mode.\n  WINDOW_LEFTEDGE=     - Specifies the beginning of the NodeWindow in the\n                         Left Edge.\n  WINDOW_TOPEDGE=      - Specifies the beginning of the NodeWindow in the\n                         Top Edge.\n  WINDOW_WIDTH=<num>   - Specifies the WIDTH of the NodeWindow.\n  WINDOW_HEIGHT=<num>  - Specifies the HEIGHT of the NodeWindow.\n  WINDOW_STATBAR       - This turns on the STATBAR in the NodeWindow\n  WINDOW_ICONIFIED     - Specifies if you want to have the NodeWindow\n                         iconified if you start the ACP.CTRL\n  WINDOW.TO_FRONT      - Specifies if you want the NodeWindow\n                         to pop up automatically when starting ACP.\n  =======================================================================\n@endnode\n@node Cap071203 "BBS:NODE<x>/TIMES.DEF.INFO ICON Infos"\n  =======================================================================\n  TIMES.DEF.INFO       - This ICON should be placed in the NODE<x>\n  ~~~~~~~~~~~~~~         directory and specifies the special Times in\n                         which specifies BaudRate can call or not.\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  START.<baud>=<time>  - Specifies the StartTime of the BaudRate\n  END.<baud>=<time>    - Specifies the EndTime of the BaudRate\n                       - for maximal calling time place in:\n                         START.<baud>=0000\n                         END.<baud>=2359\n                         or choose the OVERIDE_TIMES\n  =======================================================================\n@endnode\n@node Cap071204 "BBS:NODE<x>/NRAMS Directory Infos"\n  =======================================================================\n  NRAMS.INFO           - This ICON only represents a Directory. This\n  ~~~~~~~~~~             Directory is required to be within the\n                         BBS:NODE<x>/ directory.\n\n  ABOUT: This directory will contain NRAMS definitions for the Modem.\n\n  The following list are ICONS which should be placed in this directory:\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                     @{" <name>.DEF.INFO ICON         " Link Cap07120401}\n\n  =======================================================================\n@endnode\n@node Cap07120401 "BBS:NODE<x>/NRAMS/<name>.DEF.INFO ICON Infos"\n  =======================================================================\n  <name>.DEF.INFO      - This ICON should be placed in the NODE<x>/NRAMS\n  ~~~~~~~~~~~~~~~        directory and specifies the NRAM prefs you want\n                         to have for your ACP.CTRL button "Set NRAMS"\n                       - You can <name> it with every name you want\n                         Acp will look for the #?.DEF.INFO file in the\n                         NRAMS dir. NO SPECIAL NAME NEEDED.\n                       - The NRAMS will be activated if you press the\n                         "Set NRAMS" button in ACP SERVER.\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  NRAM.<num>=<sets>    - Specifies the NRAM Settings of your Modem.\n                         You can have unlimited NRAM settings, just\n                         change the <num>.\n  =======================================================================\n@endnode\n@node Cap071205 "BBS:NODE<x>/SERIAL Directory Infos"\n  =======================================================================\n  SERIAL.INFO          - This ICON only represents a Directory. This\n  ~~~~~~~~~~~            Directory is required to be within the\n                         BBS:NODE<x>/ directory.\n\n  ABOUT: This directory will contain SERIAL definitions for Amiexpress.\n\n  The following list are ICONS which should be placed in this directory:\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                     @{" <name>.DEF.INFO ICON         " Link Cap07120501}\n\n  =======================================================================\n@endnode\n@node Cap07120501 "BBS:NODE<x>/SERIAL/<name>.DEF.INFO ICON Infos"\n  =======================================================================\n  <name>.DEF.INFO      - This ICON should be placed in the NODE<x>/SERIAL\n  ~~~~~~~~~~~~~~~        directory and specifies the SERIAL prefs of\n                         your Computer equipment.\n                       - You can <name> it with every name you want\n                         Acp will look for the #?.DEF.INFO file in the\n                         SERIAL directory. NO SPECIAL NAME NEEDED.\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  SERIAL.UNIT=<unit>   - Specifies the UNIT on your MULTISERIALCARD\n  SERIAL.BAUD=<baud>   - Specifies the INIT BaudRate for your EXPRESS\n  SERIAL.DRIVER=<name> - Specifies the SERIALDRIVER for your EXPRESS\n                         i.e: SERIAL.DEVICE\n  SERIAL.A2232_PATCH   - Turns the A2232 Multi user serial card Patch on.\n  SERIAL.NO_PURGELINE  - This command will cause express not to clear the\n                         serial port after a modem reset command is sent\n                         through the port. Doubt many would use this.\n  SERIAL.REPURGE       - This command will process the any data in the\n                         serial port after a modem reset, normally the\n                         port is just cleared, but on A2232 cards, it\n                         appears that the card will not accept a CLEAR\n                         port command so you need SERIAL.REPURGE to\n                         process the left over data.\n  SERIAL.LOGOFF_RESET  - This command will cause the modem to be reset\n                         before each call and after each call, this\n                         routine used to be default in the 1.x series of\n                         express. So if you are having problems at logoff\n                         you may wish to try this.\n  SERIAL.TRUE_RESET    - This command will force express to Reset the\n                         modem with the following modem strings:\n                         MODEM.RESET\n                         ATZ\n                         MODEM.INIT\n                         MODEM.RESET\n  =======================================================================\n@endnode\n@node Cap071206 "BBS:NODE<x>/MODEM Directory Infos"\n  =======================================================================\n  MODEM.INFO           - This ICON only represents a Directory. This\n  ~~~~~~~~~~             Directory is required to be within the\n                         BBS:NODE<x>/ directory.\n\n  ABOUT: This directory will contain MODEM definitions for Amiexpress.\n\n  The following list are ICONS which should be placed in this directory:\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                     @{" <name>.DEF.INFO ICON         " Link Cap07120601}\n\n  =======================================================================\n@endnode\n@node Cap07120601 "BBS:NODE<x>/MODEM/<name>.DEF.INFO ICON Infos"\n  =======================================================================\n  <name>.DEF.INFO      - This ICON should be placed in the NODE<x>/MODEM\n  ~~~~~~~~~~~~~~~        direcory and specifies the MODEM prefs of\n                         your Express.\n                       - You can <name> it with every name you want\n                         Acp will look for the #?.DEF.INFO file in the\n                         MODEM directory. NO SPECIAL NAME NEEDED.\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  MODEM.INIT=          - tells /X how to initialize your modem.\n  MODEM.RESET=         - tells /X how to reset the modem for receiving\n                         another call.\n  MODEM.RING=          - tells /X how to notice an incoming call from the\n                         modem\n  MODEM.ANSWER=        - tells /X how to respond an incoming call from a\n                         modem.\n  MODEM.OFFHOOK=       - tells /X how to take your modem off hook.\n  =======================================================================\n@endnode\n@node Cap0713 "BBS:COMMANDS Directory Informations"\n  =======================================================================\n  COMMANDS.INFO        - This ICON only represents a Directory. This\n  ~~~~~~~~~~~~~          Directory is required to be within the BBS:\n                         directory.\n\n  ABOUT: This directory will contain Module definitions for Modules that\n         are in different directories and will now be listed,\n\n    @{" BBSCmd    <Directory>        " Link Cap071301}    @{" SYSCmd    <Directory>        " Link Cap071302}\n    @{" CONF(x)   <Directory>        " Link Cap071303}\n\n  =======================================================================\n@endnode\n@node Cap071301 "BBS:COMMANDS/BBSCmd Directory Informations"\n  =======================================================================\n  BBSCmd.INFO          - This ICON only represents a Directory. This\n  ~~~~~~~~~~~            Directory is required to be within the COMMANDS\n                         directory.\n\n  ABOUT: This directory will contain Module definitions for Modules that\n         are allowed to be executed globally throughout the BBS.\n\n    The following list are ICONS which can be placed in this directory:\n    ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                     @{" <module>.INFO ICONS          " Link Cap0713011}\n\n  =======================================================================\n@endnode\n@node Cap071302 "BBS:COMMANDS/SYSCmd Directory Informations"\n  =======================================================================\n  SYSCmd.INFO          - This ICON only represents a Directory. This\n  ~~~~~~~~~~~            Directory is required to be within the COMMANDS\n                         directory.\n\n  ABOUT: This directory will contain Module definitions for Modules that\n         are allowed to be executed only from MCI Message/Textures or\n         internal Module execution but not from Main Menu prompt.\n\n    The following list are ICONS which can be placed in this directory:\n    ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                     @{" <module>.INFO ICONS          " Link Cap0713011}\n\n  =======================================================================\n@endnode\n@node Cap071303 "BBS:COMMANDS/CONF<x> Directory Informations"\n  =======================================================================\n  CONF<x>.INFO         - This ICON only represents a Directory. This\n  ~~~~~~~~~~~~           Directory is required to be within the COMMANDS\n                         directory.\n\n  ABOUT: This directory will contain Module definitions for Modules that\n         are allowed to be executed only in that Conference you choose by\n         changing <x>.\n\n    The following list are ICONS which can be placed in this directory:\n    ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                     @{" <module>.INFO ICONS          " Link Cap0713011}\n\n  =======================================================================\n@endnode\n@node Cap0713011 "<Module>.INFO ICONS ToolTypes Informations"\n  =======================================================================\n  <module>.INFO        - This ICON defines a MODULE for /X. The Name of\n                         the <module> should be the same as the executing\n                         in MainMenu prompt, and should be in one of the\n                         three Directories.\n\n     a> BBSCmd     - Modules in this directory are allowed to be\n                     executed from any menu prompt or MCI text file.\n\n     b> SysCmd     - Modules in this directory are only accessible by\n                     MCI text files and internal BBS operations.\n\n     c> Conf(x)    - Modules in this directory are allowed to be\n                     executed from conference (x) menu prompt or from\n                     any MCI text file in conference (x).\n  - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -\n  INTERNAL= <command>  - Specifies if you want to have this Module the\n                         same as a internal Amiexpress command. if you\n                         choose this option you don`t need the following\n                         tool types.\n  LOCATION= <string>   - Specifies the location of the Module\n  MULTINODE= <YES|NO>  - tells /X if the module may be simultaneously\n                         accessed from other nodes.\n  ACCESS= <num>        - tells /X the access level required to run this\n                         module. This option is ignored for internal\n                         Module options.\n  TYPE= <XIM | AIM | TIM | IIM | SIM | MCI >\n                       - tells /X which type of module it is to support:\n                         XIM = /X Standard Module\n                         AIM = Arexx Module (requires REXXDOOR in\n                               BBS:Utils directory)\n                         TIM = Traditional BBS Module (requires PARADOOR\n                               in the BBS:Utils directory)\n                         IIM = NO INTERFACE - This type of Module will\n                               SPAWN the specified MODULE and not wait on\n                               it to finish.\n                         SIM = Script BBS Module - This type will execute\n                               any normal BatchScript.\n                         MCI = MCI Commanding.\n  STACK= <num>         - tells /X the stacksize to use when launching this\n                         module. Default is 4096\n  PASSWORD= <string>   - force the user to enter password before executing\n                         this module.\n  PASS_PARAMETERS=<res>- This tooltype only takes effect if you use the\n                         INTERNAL tooltype as well, so the following\n                         result options are available:\n\n                         PASS_PARAMETERS=1 - This will tell express to not\n                                             execute the internal command.\n                         PASS_PARAMETERS=2 - This will tell express to\n                                             swap the customcommand with\n                                             the internal command but\n                                             retain the commandline pars.\n                         PASS_PARAMETERS=3 - This will do the same as the\n                                             previous entry except will\n                                             additionally tell express to\n                                             redo the menu command from\n                                             the top of the routines,\n                                             which means that express will\n                                             re-check the customcommands\n                                             to see if anything meets the\n                                             criteria.\n  TRAPON               - This makes Logon Output go to a Log for Error\n                         Checking.\n  =======================================================================\n@endnode\n@node Cap0714 "BBS:STORAGE Directory Informations"\n  =======================================================================\n  STORAGE.INFO         - This ICON only represents a Directory. This\n  ~~~~~~~~~~~~           Directory is required to be within the BBS:\n                         directory.\n\n  The following list are ICONS which should be placed in this directory:\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                     @{" ICONS     <Directory>        " Link Cap071401}\n\n  =======================================================================\n@endnode\n@node Cap071401 "BBS:STORAGE/ICONS Directory Informations"\n  =======================================================================\n  ICONS.INFO           - This ICON only represents a Directory. This\n  ~~~~~~~~~~             Directory is required to be within the\n                         BBS:STORAGE directory.\n\n  The following list are ICONS which should be placed in this directory:\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                     @{" ICONIFIED.INFO ICON          " Link Cap07140101}\n\n  =======================================================================\n@endnode\n@node Cap07140101 "BBS:STORAGE/ICONS/ICONIFIED.INFO ICON Infos"\n  =======================================================================\n  ICONIFIED.INFO       - This ICON should be placed in the\n  ~~~~~~~~~~~~~~         BBS:STORAGE/ICONS directory and represents the\n                         iconfied ICON for the ACP SERVER if you close the\n                         window.\n  =======================================================================\n@endnode\n@node Cap08 "Normal Documentation of AmiExpress"\n  =======================================================================\n  The following documentation is designed to let the System Operator\n  know exactly what is taking place in each step of the BBS operations.\n  Apart from being a descriptive account of how Ami-Express works, this\n  documentation also tries to help sysop''s optimize their systems for\n  maximum efficiency.\n\n  Well, the real update of the V3.6 DOCS have been needed for a long\n  time. Here they are, this time done by Jens Langner.\n  The most difficult process in any software commercial release is the\n  development of the Documentation. After my first release of a update\n  from the normal Documentation to a big V3.6 Doc found a very big\n  response on my bbs and so Bomber decided to let me write a real\n  update of the AmiExpress Doc which will be included in every future\n  version of AmiExpress. Anyway if you like this Documentation or you\n  have a problem with AmiExpress you can call my BBS and i will help\n  you with AmiEx as much as i can. It`s very hard to write\n  docs and i hope you like this new styling of the AmiExpress Docs.\n  But now lets go on with the normal Documentation of AmiExpress.\n\n  Now go with the mousecursor to the ACP.CTRL ICON and click on it\n  two times. You should notice a ICONIFIED window appear on the\n  WorkBench screen.\n  If ACP.CTRL did not appear on the Workbench Screen, ACP.CTRL\n  should have left you an error message. If the ACP.CTRL doesn`t\n  return a Error Message contact your local AMiEX support bbs for more        help. If there appears an Error message, please\n  correct the error that is displayed. Now you should click on the\n  ICONIFIED ICON of ACP.CTRL, this will expand the ACP window to\n  reflect a series of buttons. To the left of the window you should\n  see a NODE (x) button for each NODE you want to run. You\n  should also notice at the upper portion of the window, 4 categories:\n\n  ''User'', ''Location'', ''Action'' & ''Baud''. Under ''Action'' you should see\n  a message pertaining to each node saying ''Awaiting Connect''.\n  If you do not see the ''Awaiting Connect'' message please open a shell\n  and type Express x (where x is the node number), this should display an\n  error message, most common problems is that you did not setup the\n  configuration ICONS correctly, could mean that you misspelled the device\n  driver for the serial port, or it could be that you are missing some\n  files. Whatever it is, it should tell you.. Refer to later sections in\n  this documentation for corrective actions.\n\n  Below the node buttons you should see a series of 18 buttons. There\n  is 15 buttons in 3 columns on the left bottom of the window., These\n  buttons control AmiExpress, the way to implement one of these buttons is\n  to click on 1 of the 15 and then select a NODE button for action.\n\n  Now if all nodes are showing ''Awaiting Connect'' do the following:\n\n  1> Press the Accounts button\n  2> Press the NODE 0 button\n\n  This will take you into account editing, you should see the following:\n  -------------------------------------\n  S>earch by name  N>ew account editing ?\n  -------------------------------------\n\n  1> Type 1 then press <RETURN>\n\n  This will take you into account number one, which is yours.\n  You should see the following information:\n\n--------------------------------------------------------------------------------\n  ACTIVE [1]   BAUD: 14400\nA> Name: User Name-------------------30  B> Location ......: Location\nC> Pass ..........: Pass---8\nD> Phone Number ..: 800-555-1212   F> Area Name......: Standard\nE> Ratio .........: 0              H> Sec_Level .....: 255\nG> Ratio Type ....: 0     <-Byte)  J> AutoReJoin ....: 1\nI> Uploads .......: 0              L> Messages_Posted: 0\nK> Downloads .....: 0              N> New_User ......: No  #Calls: 0\nM> Bytes Uled ....: 1                 Last Called ...: Tue May 26 22:00:17 1992\nO> Bytes Dled ....: 0                 Computer Type .: Amiga 1000\nQ> Byte Limit ....: 0                 Screen Type ...: Amiga Ansi\n                                   Y> Cps Up: 0         Z> Cps DN: 0\nR> Time_Limit: [9600    ] secs    S> Time_Used: [0       ] secs  T> UUCP: 0\n\nX=EXIT-NOSAVE TAB=Cont  ~=SAVE  1-6=Presets  9=RE-ACTIVATE  DEL=DELETE\n--------------------------------------------------------------------------------\n\n  2> Press the letter A, this will let you put your name on your account.\n\n  3> Press the letter B, this will let you setup a address, group name\n     or whatever you like.\n\n  4> Press the letter C, this will let you assign yourself a password.\n\n  5> Press the letter D, this will let you out your phone number in.\n\n  6> Now you can press a number between 1 and 6 for account defaults.\n\n  7> Make sure that your Time_Limit is not 0.\n\n  8> Press the tilde ''~'' to save the account,.\n\n  Here is a sample of a completed sysop account:\n\n--------------------------------------------------------------------------------\n  ACTIVE [1]   BAUD: 14400\nA> Name: ByteMaster                      B> Location ......: Location\nC> Pass ..........: London\nD> Phone Number ..: 318-793-4101   F> Area Name......: Standard\nE> Ratio .........: 0              H> Sec_Level .....: 255\nG> Ratio Type ....: 0     <-Byte)  J> AutoReJoin ....: 1\nI> Uploads .......: 0              L> Messages_Posted: 0\nK> Downloads .....: 0              N> New_User ......: No  #Calls: 1\nM> Bytes Uled ....: 1                 Last Called ...: Tue May 26 22:00:17 1992\nO> Bytes Dled ....: 0                 Computer Type .: Amiga 1000\nQ> Byte Limit ....: 0                 Screen Type ...: Amiga Ansi\n                                   Y> Cps Up: 0         Z> Cps DN: 0\nR> Time_Limit: [9600    ] secs    S> Time_Used: [0       ] secs  T> UUCP: 0\n\nX=EXIT-NOSAVE TAB=Cont  ~=SAVE  1-6=Presets  9=RE-ACTIVATE  DEL=DELETE\nSave\n--------------------------------------------------------------------------------\n\n  9> Press the TAB key to complete the editing.\n\n         Now you should see the following:\n         -------------------------------------\n         S>earch by name  N>ew account editing ?\n         -------------------------------------\n\n  10> Press return to exit account editing.\n\n  11> Select the close gadget to return to the WorkBench screen. This\n      will also of course close the BBS Window.\n  =======================================================================\n@endnode\n@node Cap09 "The Programlogic of AmiExpress"\n  =======================================================================\n  We will now describe the program logic of the Express so you can\n  learn how to operate AmiExpress to it''s maximum potential.\n\n  The ACP window has 15 major buttons at the bottom of the window.\n  Here is a list of there names and function:\n\n   [ Sysop Login ].....Logs you into a node as the sysop\n   [ Local Login ].....Enters the initial long on phase of the Node\n                       This will require you to specify your name\n                       and password.\n   [ Instant Login ]...This will give a carrier detect command to the\n                       modem, this is good for re-establishing a\n                       connection to a user after talking to them voice\n                       on the same line.\n   [ Reserve Node ]....This allows you to tell the Node to only let a\n                       certain user on the BBS. After the user has called\n                       the node will no longer be reserved.\n   [ AEShell ].........This will open a shell on the Node screen.\n   [ Accounts ]........This takes you into account editing on a node.\n   [ Toggle Chat ].....This toggles the Node''s chat request flag, if a\n                       Nodes Chat request flag is off, then only user of\n                       a high enough security level be able to request a\n                       chat.\n   [ Init Modem ]......This re-initializes a modem of a particular node.\n   [ Exit Node  ]......This will shutdown the node in question.\n   [ Node(offhook) ]...This will shutdown the node in question and also\n                       make the line busy.\n   [ Node Config ].....This will bring up our config program for a\n                       particular node.\n   [ Node Chat ].......This button will take you into chat mode with a\n                       particular node.\n   [ Save Win ]........This button does not require a NODE(x) complement.\n                       This simply saves the window coordinates of ACP to\n                       a file called S:ACP.Config\n   [ Set NRAMS ].......This button will Set the NRAMS of your Modem and\n                       will save it to the EPROM.\n\n   NOTE: All of the above mentioned buttons unless said otherwise, require\n   ~~~~  you to press the Appropriate node button for them to take effect.\n\n\n  Once all of the NODES are started the following actions take place for\n  each node:\n\n  At this point the bbs will load up the computer types from a ICON\n  called:\n\n  BBS:COMPUTERLIST.INFO\n\n  Ami-Express then checks if the node is already running as another task,\n  and if it is, then the program halts and exits with an error message.\n\n  Next, Ami-Express will try to access the LIBS:REXXSYSLIB.LIBRARY for\n  it''s Arexx port routines, and if not found, will disable the Arexx port\n  and inform the user that the Rexx port is disabled.\n\n  Ami-Express will run thru it''s initialization process where it will take\n  the modem off-hook, and configure it for BBS operation.  This is done so\n  that an incoming call does not alter the configuration process.\n\n  While someone is online you have the following function keys available\n  to you:\n\n  F1  - Chat in/out\n  F2  - Increase Online time limit +10 mins\n  F3  - Decrease Online time limit -10 mins\n  F4  - Asks for a path/filename for a capture file (only on the sysops\n        side) or if one is already open then it closes the capture and\n        lets you know it did so. when you press F4 again the capture\n        will be stopped.\nS+F4  - This will pop up an ASL Requester to let you choose an ASCII File\n        to be send to the user.\n  F5  - Local Shell\n  F6  - Account Editing\nS+F6  - This will let you change the Account of a User only for that call\n        he is online. When he locks off the BBS will reset his Account\n        to the old one. Press Shift+F6 a second time and the changes will\n        be restated to the old ones.\n  F7  - Chat Flag toggle (whether you are to be paged or not)\n  F8  - Serial in on/off (User can`t write until you press F8 again)\n  F9  - Serial out on/off (User can`t see what you are typing)\n  F10 - Keyboard out on/off (Disconnect OnLine User *KICK*)\n\n  Now follows the normal reactions of AmiExpress when something happens\n  if the bbs is in the standby mode and the nodes are standing at\n  "Awaiting Connect".\n\n  (1). The bbs checks for F key input from the local keyboard.\n\n  (2). Or data coming in the serial port.\n\n  (3). Or data coming in the internal communication AmiExpress_Node(x)\n       msgport for commands either suspend, resume, or shutdown.\n\n  (4). Or data coming in from the AmiExpress window itself (Gadgets etc..)\n\n  (5). Or data coming in from AmiExpress Control.(ACP)\n\n       Once the modem picks up a RING DETECT, the bbs sends an Answer\n       string specified in the config file to the modem, and waits\n       for a response from the remote modem. If the resultant string\n       is a valid connect string, the bbs continues with normal\n       operations, if not, it resets the modem and the ACP screen will\n       return to "Awaiting Connect" state.\n\n       If the connect string was a valid one, AmiExpress first checks\n       a couple of things before performing the login routine:\n\n  (1). System checks for a file called:\n       BBS:NODE{x}/NOCALLERSAT{BAUD} where x is node number and\n       BAUD is the baud rate that is unaccepted. If this file\n       exists, and the current baud rate matches the BAUD, then\n       the BBS displays the file and disconnects.\n\n  (2). Displays the connect string received from the modem.\n\n  (3). Now, the BBS displays the standard welcome message,\n       and starts to perform the actual login procedure.\n\n  (4). Check to see if you have a Module called FRONTEND , if so it\n       executes it. see section regarding doors for more info.\n       Explanation:\n       To Install the frontend module you have to a ICON to the\n       BBS:COMMANDS/SYSCMD directory called "FRONTEND"\n\n  (5). BBS checks if there is a module called "ANSI" in the SYSCMD\n       Directory if so it will start the door you insert and will skip\n       the selecting of ANSI or ASCII Colors. Look at Point (4) above\n       for more infos about installing these doors.\n       If the BBS can`t find such a door it will asks if the user wants\n       ANSI graphics or not.  If a ''Q'' is specified at the end of the line\n       like: "YES Q" or "Y Q" etc. Then the BBS checks if the Option\n       DISABLE_QUICK_LOGONS is on or not if the option is on the BBS will\n       display the Logon.txt because you want to have the users seen it.\n       If the Option is off and the user answers "Y Q" or "YES Q" the BBS\n       will not display the logon or logoff screens.\n\n  (6). Then if the sysop has specified a SYSTEM PASSWORD it\n       displays a file called: BBS:NODE<x>/PRIVATE.txt then\n       asks for the SYSTEM PASSWORD you specifies. The system gives the\n       user three tries and if by then he hasn''t gotten it the bbs\n       hangs up, and displays in the callerslog that someone\n       attempted to get the SYSTEM PASSWORD.\n\n  (7). The bbs displays the file: BBS:NODE{x}/BBSTITLE.txt\n\n  (8). It now asks for the user to enter his FULL NAME, again wildcards\n       are usable and will expand and ask if correct.  A user gets\n       five tries at his user name, then the bbs hangs up.\n\n  (9). If the bbs can''t find the name supplied it will tell the user\n       and ask him if he would like to ''C''ontinue to join or ''R''etry\n       entering his name again.\n\n   [C]ontinue as a New User Selected:\n   ----------------------------------\n\n      (1). If the bbs has been reserved it will notify the user that\n           the bbs has been reserved for a specific member and will\n           then hangup.\n\n      (2). If the bbs hasn''t been reserved then the bbs checks to see if\n           the user''s baud rate is allowed during the time he has called.\n           If so, then the bbs allows the user to continue, otherwise it\n           displays the file: BBS:NODE{x}/NOTTIME{BAUD}.txt\n                 {x} = Node number, {BAUD} = Current Baud rate.\n\n      (3). If the sysop has specified a new user password in the config\n           file then the bbs displays the file:\n           BBS:NODE{x}/NEWUSERPW.txt\n           Then it asks for the new user password and if the user gets\n           the password wrong it goes back and asks for his FULL NAME\n           again, after 5 tries the bbs hangs up.\n\n      (4). If the System-Operator wishes to have no more NEW users the bbs\n           would look for the file BBS:NODE{x}/NONEWUSERS then displays it\n           and disconnect the User. And if you wishes to have no more NEW\n           users at a SPECIFIC BAUD RATES, the BBS would look for a file\n           called BBS:NODE{x}/NONEWAT{BAUD}, displays it and then\n           disconnecting the User.\n                  {x} = Node number, {BAUD} = Current Baud rate.\n\n      (5). Now it enters the New Account routines.\n\n            1. Search displays BBS:NODE{x}/JOIN.txt\n\n            2. Asks for full name. At this point wildcards are NOT\n               ALLOWED. The user only has 5 chances to enter it then\n               the bbs says "Too Many Errors, Goodbye!"\n\n            3. The bbs checks for use of a name that already exists.\n               If the name already exists it asks again.\n\n            4. The bbs checks the name given to see if not in the list\n               of names supplied in the icon BBS:NAMESNOTALLOWED\n               This is a file that contains names that the sysop does\n               not want to allow on the bbs.  If the file does not\n               exists the bbs will not allow any new users to log on\n               util the file has been added.  This is to prevent\n               someone getting on as ALL or EALL etc.  A notice will\n               be placed at the end of the BBS:NODE{x}/CALLERSLOG file.\n\n    WARNING: You should specify in that list SYSOP, ALL, and EALL\n\n            5. Next it asks for the City, State.\n\n            6. The it asks for Phone Number (xxx-xxx-xxxx)\n\n            7. Next, it asks for the Users personal Password\n\n            8. Number of lines on screen (1-255)\n\n            9. Clear Screen between Messages ?\n\n           10. Asks for which ScreenType the User want to have.\n\n           11. Display back all info and asks if it is correct if\n               the user needs to change something he just says no\n               its not correct and the process starts again at 2..\n\n           12. At this point the bbs checks to see if there is a\n               script Module in the SYSCMD Directory and if express\n               will find this module it will start it instead of the\n               normal SCRIPT questionnaire. And if express can`t find\n               such a Module it will start the normal SCRIPT\n               questionnaire to ask the user to fill out, it\n               checks for BBS:NODE{x}/SCRIPT{BAUD}\n                  {x} = Node number, {BAUD} = Current Baud rate.\n\n            NOTE: The {BAUD} should be specified as 1200,2400,4800,\n                  9600, 12000, 14400 and 16800 to allow for proper\n                  connect handling by USR HST modems.\n\n               Now the user is asked to fill out the script if existent.\n               A sample script may look like:\n\n                    -------------Cut Here--------------------\n\n                    What is your Real Name: ~\n                    What is your Real #   : ~\n                    What is your Sex,Age  : ~\n\n                    -------------Cut here--------------------\n\n               Here, the ~ character is used when a prompt for input\n               by the user is expected.  The answers are saved to\n               BBS:NODE{x}/TEMPANS before being validated by the sysop.\n               Once the Sysop validates the User, the answers are copied\n               over to BBS:NODE{x}/Answers.\n\n         13. The bbs then displays the file BBS:NODE{x}/JOINED.txt\n\n     (10). Once the system has loaded the users account, it checks to see\n           if the system has been reserved, if so and the user who just\n           logged in is not the reserved user the bbs displays that the\n           system has been reserved for that specific user, and then hangs\n           up.\n\n     (11). Then the BBS will display the BBS:NODE{x}/LOGON.txt text\n           where x stands for the Node.\n\n     (12). If the bbs hasn''t been reserved then the bbs checks to see if\n           the user''s baud rate is allowed during the time he has called.\n           If so, then the bbs allows the user to continue, otherwise it\n           displays the file: BBS:NODE{x}/NOTTIME{BAUD}.txt\n\n     (13). If the users Security level is 0 then the bbs displays the\n           file: BBS:NODE{x}/LOCKOUT-0.txt and then hangs up.\n\n     (14). If the users Security level is 1 then the bbs displays the\n           file: BBS:NODE{x}/LOCKOUT-1.txt and then hangs up.\n\n     NOTE: These two files allow a sysop to be either polite about not\n           allowing a user on the system, or if the user is an abuser,\n           the sysop can have a full blown rude as hell Lockout text for\n           those types of users.\n\n     (15). At this point the system adds to the end of\n           BBS:NODE{x}/CALLERSLOG that a user just logged in.\n\n     (16). Now the bbs asks the user for his password, every time the user\n           gets the password wrong the bbs adds what he tried to the end\n           of BBS:NODE{x}/CALLERSLOG. After 3 tries the bbs hangs up and\n           adds this to the Callerslog.\n\n     (17). Then the standard logon sequence takes place and puts the user\n           at the main command prompt\n\n  LOGON SEQUENCE FOR A PREVIOUS USER:\n  -----------------------------------\n\n  When a user with an existing account logs into the BBS, the login\n  procedure is a lot more simplified. The standard login procedure is\n  listed below:\n\n   (1). The bbs checks to see if the user has any time for the day\n        if not it displays BBS:NODE{x}/LOGON24HRS.txt file to the\n        user and hangs up.\n\n   (2). If no BULLBATCH files are specified, the BBS looks for any\n        Bulletin files in BBS:NODE{x}/BULL{SEC}.txt where\n        {x} = NODE NUMBER and {SEC} = USERS CURRENT SECURITY LEVEL.\n        If a file is found that matches the user`s security level,\n        it is displayed. For example, a last callers bulletin for\n        standard user security of 20 would be saved in the BBS:NODE{x}\n        directory as follows: BBS:NODE{x}/BULL20.TXT and\n        BBS:NODE{x}/BULL20.TXT. This routine has also been simplified\n        from the sysop''s end so that the appropriate bulletins are\n        searched for in a rounded off method.\n     ie: If a user level with security level of 20 has logged in, and\n         the bbs cannot find an entry for\nBBS:NODE{x}/BULL20.TXT but\n         finds a file called BBS:NODE{x}/BULL15.TXT, then this file\n         will be displayed. If there is also a file called\n         BBS:NODE{x}/BULL30.TXT, this file will be displayed to users\n         with security level of at least 30 or more. Once the BBS finds\n         the nearest file, it displays that file only.\n\n      NOTE: Routines have been added to AmiExpress to make sysop setup\n            a little easier and less annoying to the user.  The bbs will\n            scan for a particular file in this method:\n\n      Say a user with access level 30 just logged in, with ansi color,\n      now the BBS will check first if there is a BULL30.txt and if not\n      the bbs will go on with searching for bulls lower than 30.\n\n     Look here:\n\n      BBS:NODE{x}/BULL30.txt\n      BBS:NODE{x}/BULL25.txt\n      BBS:NODE{x}/BULL20.txt\n      BBS:NODE{x}/BULL15.txt\n      BBS:NODE{x}/BULL10.txt\n      BBS:NODE{x}/BULL5.txt\n      BBS:NODE{x}/BULL.txt\n\n   NOTE: because of this method of searching, all files to be\n         searched for must end in either 0 or 5 (as above), the\n         user access level will be rounded down to the nearest\n         multiple of 5 and the search will start there.\n\n       That''s an example of a search for a file to be displayed, once\n       a file is found that exists it displays ONLY that file.\n       This method is used on the following:\n\n       BBS:NODE{x}/BULL\n       BBS:NODE{x}/JOINCONF\n       BBS:CONF/MENU\n       BBS:CONF/BULL\n\n       In some cases it works a little different, in this case\n       the user security is not used, like:\n\n       BBS:CONF/Bulletins/BULLHELP.txt\n       BBS:CONF/Bulletins/BULLHELP.TXT\n\n       Thats how that one works and the following are like that:\n\n       BBS:NODE{x}/JOINED\n       BBS:NODE{x}/LOGON24HRS\n       BBS:NODE{x}/GUESTLOGON\n       BBS:NODE{x}/LOGON\n       BBS:NODE{x}/LOGOFF\n       BBS:NODE{x}/JOIN\n       BBS:NODE{x}/NOTTIMEbaud\n       BBS:NODE{x}/PRIVATE\n       BBS:CONF/FILEHELP\n\n    NOTE: For multiple bulletins upon login, a BULLBATCH script is used\n          to display the necessary bulletins in the correct order.  For\n          more information on this, please refer to the section under\n          BULLBATCH implementation.\n\n\n   (3). Initial User specific checks are made:\n\n     a> The bbs now scans thru all the conferences that the user has\n        access privilege to for any waiting mail. If mail is found, it\n        informs the user about it and asks the user if they want to view\n        it.\n\n     b> The bbs checks to see if there are any unfinished uploads.\n        If someone looses carrier uploading a file and calls back\n        he will be allowed to resume his/her upload.\n\n   (4). Then the bbs rejoins the conference the user was in the last time\n        he called.\n\n   (5). It then checks the ICON BBS:CONF to see how many, if any,\n        directories of files that specific conference has.\n        It will check if in the ICON the NDIRS is bigger than 0.\n\n        for example:\n        ~~~~~~~~~~~  NDIRS=2\n\n        This would specify that there are two file directories where files\n        are kept. A carriage return is necessary after the number.\n\n        If this file is unavailable, the conference will have NO files\n        available in it, meaning no uploads or downloads will be possible\n        from it.\n\n   (6). If the number of directories is greater than zero, the bbs looks\n        to see if a in the CONF ICON the Tooltyp "FREEDOWNLOADS" is turned\n        on, if so then all files in this particular conference are free to\n        download.\n\n   (7). Now, the BBS scans for any BBS:CONF/BULL{SEC}.TXT files in\n        the same method as described earlier on.\n\n      NOTE: This works exactly like the BBS:NODE{x}/BULL files.\n\n   (8). After displaying the available bulletins, if the user is not in\n        EXPERT mode, the bbs displays the available\n        BBS:CONF/MENU{SEC}.TXT and reaches the MAIN MENU PROMPT.\n\n      a> Any command entered at the MAIN MENU PROMPT will be looked up\n         in a BBS:Commands/BBSCMD directory. If the command is found as\n         a module name in the directory the module will be executed.\n         If the command cannot be found, then the command will be compared\n         to BBS:Commands/CONF{x}CMD directory and like wise be executed\n         if found. Otherwise the command will be considered an internal\n         command and maybe any of the commands listed below.\n  =======================================================================\n@endnode\n@node Cap10 "The MainMenu Commands of AmiExpress"\n  =======================================================================\n     This is a list of commands accessible from the main menu prompt:\n     ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n  AmiExpress has many functions that are part of the program code that\n  assist users in what they want out of the system. These commands are\n  mostly single letter commands that the user types and hits return for\n  the execution. AmiExpress does not work with a HOT-KEY type of user\n  input. This means that the user will be saved from having to look at\n  a screen load of data when they accidentally hit a wrong key.\n  A carriage return always indicates an intended execution.\n\n  This section is divided into two parts, The SYSOP ONLY COMMANDS, and the\n  Standard User Commands.\n\n    @{" SYSOP Only Main Commands     " Link Cap1001}    @{" STANDARD USER Main Commands  " Link Cap1002}\n\n  =======================================================================\n@endnode\n@node Cap1001 "SYSOP Only Commands....."\n  =======================================================================\n                           SYSOP ONLY COMMANDS:\n                           ~~~~~~~~~~~~~~~~~~~\n  These commands are the only commands that are called up by single digit\n  number codes.  They are available only to users with SYSOP SECURITY\n  LEVELS as defined in the config file by AmiConfig under ACCOUNT EDITING.\n\n    @{" Command: ''1'' <AccountEditing>" Link Cap100101}    @{" Command: ''2'' <CallerslogView>" Link Cap100102}\n    @{" Command: ''3'' <Edit File Dirs>" Link Cap100103}    @{" Command: ''4'' <Edit Text File>" Link Cap100104}\n    @{" Command: ''5'' <View Directory>" Link Cap100105}    @{" Command: ''0'' < Remote Shell >" Link Cap100106}\n    @{" Command: ''DS''<Sysop Download>" Link Cap100107}    @{" Command: ''VS''<  Sysop View  >" Link Cap100108}\n\n  =======================================================================\n@endnode\n@node Cap100101 "[ 1 ] - Account Editing...."\n  =======================================================================\n  [ 1 ] - Account Editing:\n          ~~~~~~~~~~~~~~~\n    This is used to either review existing accounts and modify them, or\n    scan for any new user logins that wish to be validated.  The account\n    editing module is very easy to use in that it is basically menu\n    driven. You can also get into the BBSInfo Conf. from here.\n    Before Express will start the normal Account Editing it will try\n    to open a MODULE called "ACCOUNTS" which should be located in the\n    SYSCMD Directory. This is for further coming releases of better\n    Account Editors.\n\n    The AccountEditing will look like this:\n\n--------------------------------------------------------------------------------\n  ACTIVE [1]   BAUD: 14400\nA> Name: ByteMaster                      B> Location ......: Location\nC> Pass ..........: London\nD> Phone Number ..: 318-793-4101   F> Area Name......: Standard\nE> Ratio .........: 0              H> Sec_Level .....: 255\nG> Ratio Type ....: 0     <-Byte)  J> AutoReJoin ....: 1\nI> Uploads .......: 0              L> Messages_Posted: 0\nK> Downloads .....: 0              N> New_User ......: No  #Calls: 1\nM> Bytes Uled ....: 1                 Last Called ...: Tue May 26 22:00:17 1992\nO> Bytes Dled ....: 0                 Computer Type .: Amiga 1000\nQ> Byte Limit ....: 0                 Screen Type ...: Amiga Ansi\n                                   Y> Cps Up: 0         Z> Cps DN: 0\nR> Time_Limit: [9600    ] secs    S> Time_Used: [0       ] secs  T> UUCP: 0\n\nX=EXIT-NOSAVE TAB=Cont  ~=SAVE  1-6=Presets  9=RE-ACTIVATE  DEL=DELETE\n--------------------------------------------------------------------------------\n\n  Press the following keys to change the data of the User:\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n  A> Let you change the name of the User you are looking at\n  B> Let you change the location where the user is living\n  C> Let you change the password of the user you are looking at\n  D> Let you change the phonenumber of the current user\n  E> Let you change the Ratio of the user you are looking at\n  F> Here you can change the Conf.Access of the User\n  G> Let you change the Ratio Type of the User. From here you have 3\n     different Ratio Types:\n                            - Ratio Type 0 = Bytes only\n                            - Ratio Type 1 = Bytes & Files\n                            - Ratio Type 2 = Files only\n\n     This ratio type are for choosing in which way the Ratio will be\n     calculated.\n  H> Let you change the Security Level of the user you are looking at\n  I> Let you change the number of Upload the user has done.\n  J> Let you change the Conference at which the User logged in the last\n     time he called the system.\n  K> Let you change the number of downloads the user has done.\n  L> Let you change the number of Messages the user posted in the bbs.\n  M> Let you change the number of Bytes the user uploaded.\n  N> Let you change if the user is a NEW USER or not. this is a flag\n     function. if it is in the "YES" mode the user will be found if you\n     search for new users. After you edit the Userdata with a present\n     the flag will be changed automatically to "NO".\n  O> Let you change the number of Bytes the user downloaded.\n  Q> Let you change the number Bytes which the can download at a day.\n  R> Let you change the Time Limit for a day.\n  S> Let you change the Time the user has already used today.\n  T> Let you change if the User is a User of UUCP or not.\n  Y> Let you change the Top Upload CPS the User ever had.\n  Z> Let you change the Top Download CPS the User ever had.\n  #> Let you change the Number of Calls a user has done to your System.\n\n  Now follows the normal commands in the Account Editing:\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n  [ X ]   - Exit the Account editing without saving the current changes\n  [ TAB ] - Let you go to the next user who matches to the username\n            you entered before.\n  [ ~ ]   - Will save the current changes of the User.Data.\n  [ 1-6 ] - Will set the User.Data to a Present of ACP.STARTUP\n  [ 9 ]   - This command will re-activate a deleted user.\n  [ DEL ] - This command will delete the user you are looking at.\n            you can re-activate a user by typing "9" at the AccountEditing\n  [ + ]   - Will go on the next user in the User.Data.\n  [ - ]   - Will go on the previews user in the User.Data.\n  =======================================================================\n@endnode\n@node Cap100102 "[ 2 ] - View CallersLog...."\n  =======================================================================\n  [ 2 ] - View CallersLog:\n          ~~~~~~~~~~~~~~~\n    This lets the sysop view the BBS:NODE{x}/CALLERSLOG file backwards.\n    The last line written to the callerslog will be displayed first\n    and the first line of the callerslog will be displayed last.\n    On system running more than one node, this command will ask which\n    NODE''s CALLERSLOG to view.\n  =======================================================================\n@endnode\n@node Cap100103 "[ 3 ] - Edit File Directories (EDITOR/EMACS)...."\n  =======================================================================\n  [ 3 ] - Edit File Directories (EDITOR/EMACS):\n          ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n    If you started this Command, the bbs will check if the one who started\n    the command is a remote or a local one. If the one who started it is\n    a local one it will search for a Door called "EDITOR" in the SYS.CMD\n    and if it exists it will be executed and the normal starting of the\n    EMACS will be skipped.\n\n    If the one who started the command is in REMOTE_LOGON then the command\n    will be executed as follows:\n    This command uses the command line version of MicroEmacs for on-line\n    directory editing.  For more information on how to use Emacs, you\n    should refer to the section on COMMON EMACS COMMANDS.\n    This command asks the user which directory to edit before it opens\n    up the appropriate AUX: or CNN: channel and executing EMACS.\n    NOTE: AUX{x}: is used only on remote connections and if active\n    ~~~~  a watchdog task that checks for carrier loss is also invoked.\n          If carrier is lost while editing directories, the computer\n          will be reset within two seconds.\n          A special note to MULTI NODE systems: The watchdog resets the\n          computer if a carrier is lost regardless of what the other\n          nodes are doing.  If users are logged in on other nodes, they\n          will be disconnected when the computer resets.  A later version\n          of AmiExpress will send a notification to the other nodes and\n          a time-out requestor locally will inform the sysop and users\n          that express wants to reset the computer and that everyone\n          should finish up what they''re doing.\n\n    Exiting from EMACS with CTRL-X CTRL-C key combination will return the\n    user to the MAIN MENU PROMPT.  While a user is in EMACS, the BBS will\n    notify the sysop by placing a line like:\n    User in Emacs........\n\n    WARNING! for those of you using the A2232 multi serial card\n             you may run into problems using the editor. We\n             are currently working on a fullscreen editor to\n             take it''s place.\n  =======================================================================\n@endnode\n@node Cap100104 "[ 4 ] - Edit any Text File on System (EDITOR/EMACS)...."\n  =======================================================================\n  [ 4 ] - Edit any Text File on System (EDITOR/EMACS):\n          ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n    This command is basically the same as the previous with the option\n    to specify full path and file name to edit. This commands prompts\n    the user for the necessary information.\n  =======================================================================\n@endnode\n@node Cap100105 "[ 5 ] - List System Directories...."\n  =======================================================================\n  [ 5 ] - List System Directories:\n          ~~~~~~~~~~~~~~~~~~~~~~~\n    This command works just like the AMIGADOS List command and displays\n    the directory and sub-directories available for the specified path.\n    The command can also display any comments (FILENOTES), attached to\n    the files themselves.  When selected, AmiExpress will ask for the\n    full path name and whether to include comments or not.\n  =======================================================================\n@endnode\n@node Cap100106 "[ 0 ] - Remote Shell...."\n  =======================================================================\n  [ 0 ] - Remote Shell:\n          ~~~~~~~~~~~~\n    This Command has been removed currently in this version of express.\n    There are some great door with the same capabilities soon to replace\n    this command. if you choose one of the great doors who are out.\n    Personallity I recommend the version of MALTESE FALCON. Install\n    it as a normal door in your BBSCMD directory and choose the 0\n    button for that.\n  =======================================================================\n@endnode\n@node Cap100107 "[ DS ] - Sysop Download...."\n  =======================================================================\n  [ DS ] - Sysop Download:\n           ~~~~~~~~~~~~~~\n    This Command is exactly the same as the normal User Download\n    command instead of the ability that with that command the sysop can\n    download files from each path on the harddisk. The WildCard searching\n    is removed in this command to prevent error in searching for files.\n    All files on the harddisk can be downloaded with this command instead\n    of that files that are RESTRICTED for downloading with the\n    File Comment "RESTRICTED", this prevent downloading of files you want\n    never to be downloaded by your CoSysOps.\n  =======================================================================\n@endnode\n@node Cap100108 "[ VS ] - Sysop Text View...."\n  =======================================================================\n  [ VS ] - Sysop Text View:\n           ~~~~~~~~~~~~~~~\n    This Command is exactly the same as the normal User Text View command\n    instead of the ability that with that command the sysop can View any\n    files from each path on the harddisk. All files can be viewed with\n    that command instead of the ones RESTRICTED with the file comment\n    "RESTRICTED", this prevent users for viewing private files of you.\n  =======================================================================\n@endnode\n@node Cap1002 "REGULAR USER Commands...."\n  =======================================================================\n                          REGULAR USER COMMANDS:\n                          ~~~~~~~~~~~~~~~~~~~~~\n  These commands are explained in detail. All the commands here can be\n  chosen in the ACCESS ICONS for EXPRESS.\n\n    @{" [<][>].....Fast Conf.joining " Link Cap100201}    @{" [ A ].......Alter File Flags " Link Cap100202}\n    @{" [ B ]......Bulletins reading " Link Cap100203}    @{" [ C ].......Comment to Sysop " Link Cap100204}\n    @{" [ D ].......Download File(s) " Link Cap100205}    @{" [ E ]..........Enter Message " Link Cap100206}\n    @{" [ F ]..........File Listings " Link Cap100207}    @{" [ FS ]......Full Status View " Link Cap100208}\n    @{" [ G ]........GoodBye(LOGOFF) " Link Cap100209}    @{" [ H ]..............Help Page " Link Cap100210}\n    @{" [ J ]........Join Conference " Link Cap100211}    @{" [ M ]......(COLOR/MONO) Mode " Link Cap100212}\n    @{" [ MC ].....Enter MCI Comment " Link Cap100213}    @{" [ ME ].....Enter MCI Message " Link Cap100214}\n    @{" [ N ]...New Files Since Date " Link Cap100215}    @{" [ O ]..........Operator Page " Link Cap100216}\n    @{" [ Q ].............Quiet Node " Link Cap100217}    @{" [ R ]..............Read Mail " Link Cap100218}\n    @{" [ RL ]...............ReLogon " Link Cap100219}    @{" [ S ].Status of On-Line User " Link Cap100220}\n    @{" [ T ]...................Time " Link Cap100221}    @{" [ U ].........Upload File(s) " Link Cap100222}\n    @{" [ V ].......View a Text File " Link Cap100223}    @{" [ W ]..Write User Parameters " Link Cap100224}\n    @{" [ WHO ].....Node Information " Link Cap100225}    @{" [ X ].....Expert Mode Toggle " Link Cap100226}\n    @{" [ Z ]......Zippy Text Search " Link Cap100227}    @{" [ ZOOM ].........Zoo Mailing " Link Cap100228}\n  =======================================================================\n@endnode\n@node Cap100201 "[<][>] Fast Conference Joining Command"\n  =======================================================================\n  [ < ] - Joining Conference Up&Down:\n  [ > ]   ~~~~~~~~~~~~~~~~~~~~~~~~~~\n    This two commands allows the user to join conferences by only using\n    the ''<'' ''>'' keys. This will let the user go up one conference and\n    down one conference. Example: User is in Conf. 3 and use the ''>'' key.\n    so he will automatically join the one higher conference he has access\n    to, and if he will use the ''<'' key again he will join Conf. 3 again.\n  =======================================================================\n@endnode\n@node Cap100202 "[ A ] - Alter File Flaging...."\n  =======================================================================\n  [ A ] - Alter File Flags:\n          ~~~~~~~~~~~~~~~~\n    This command allows the user to change the flagged file list\n    without having to do a file listings and get a PAUSE...MORE\n    prompt to change the flags.\n    Chaining data is allowed, or the routine will prompt the user\n    for the information.\n\n    First it will show the current list of flags.\n\n    No file flags\n    Filename(s) to flag: (C)lear, (Enter)=none?\n\n    At this prompt the user can:\n     1. Enter new files to add to the flag list\n     2. Enter ''C'' to goto the clear flag prompt\n\n    Filename(s) to Clear: (*)All, (Enter)=none?\n\n    At this prompt the user can:\n     1. Enter filenames to remove from the flag list,\n        wildcards are valid, however they will only\n        remove the first entry.\n     2. Use ''*'' to remove all entries in the list.\n     3. Hit Return to exit.\n\n    Once a user exits the Clear prompt, it will once\n    again show the list of flagged files and drop back\n    to the MAIN MENU PROMPT.\n  =======================================================================\n@endnode\n@node Cap100203 "[ B ] - Bulletins reading...."\n  =======================================================================\n  [ B ] - Bulletins:\n          ~~~~~~~~~\n    This command allows the user to view bulletins that the sysop\n    has made available.\n    - First, the BBS checks to see if the file\n      BBS:<CONF>/BULLETINS/BULLHELP.TXT is available; if not, it tells\n      the user that no bulletins are available in that conference.\n    - If the BBS:<CONF>/BULLETINS/BULLHELP.TXT is found, it is displayed\n      and the user is prompted to enter the bulletin # to view or ''?'' to\n      redisplay the BULLHELP.TXT which is the bulletins menu.\n    - If a user selects a valid bulletin #, it is displayed and the bbs\n      returns back to the bulletin prompt.\n    - If a user selects an invalid bulletin #, the bbs informs the user\n      that there is no bulletin #{x} where {x} = the specified bulletin.\n  =======================================================================\n@endnode\n@node Cap100204 "[ C ] - Comment to Sysop...."\n  =======================================================================\n  [ C ] - Comment to Sysop:\n          ~~~~~~~~~~~~~~~~\n    This command is exactly the same as the regular ENTER MESSAGE command\n    except that the message is addressed privately to the System-Operator.\n    The TO: field is automatically filled with the User name on SLOT 1,\n    which is the Sysop.\n    If the BBS located the tooltype "FORWARDMAIL= <str>" in the Conference\n    ICON is turned on, the Mail will be forwarded to the User named in\n    the <str>. This is very useful if you go to holiday and want your\n    cosysop to read the messages to yeah without typing "R" for read\n    messages.\n  =======================================================================\n@endnode\n@node Cap100205 "[ D ] - Download File(s)...."\n  =======================================================================\n  [ D ] - Download File(s):\n          ~~~~~~~~~~~~~~~~\n    This command accesses the file transfer procedure for sending files\n    from the system to the remote user. The flow-chart for this command\n    is quite complex and is outlined below:\n\n    1. If the ToolType NDIRS contains zero, the bbs informs the user\n       that there are no files to download from that conference.\n\n    2. The bbs displays the File BBS:CONF/DOWNLOADMSG.TXT\n\n    3. The bbs displays the users Download/Upload stats.\n\n    4. The bbs calculates the ratio limits the user has before uploading\n       files to the system.\n\n    5. Next, it displays the transfer protocol the user take for default.\n       The User can change this protocols by using the "W" command.\n\n    6. If the user had specified ''DS'' instead of just ''D'' the download\n       is considered a sysop download and if the user is allowed to\n       use SYSOPDOWNLOAD, the download can be made from any valid\n       AmigaDos path on the system.  If this is the case, the BBS asks\n       for the full path and filename. NO WILDCARDS ARE ALLOWED with a\n       Sysop Download.\n\n    7. The BBS asks the user to enter the filename(s).\n\n    8. Checks for special characters in the filename like ":/" etc.\n       If found, tells the users that special symbols may not be included\n       when downloading.\n\n    9. Full Wildcards are allowed when doing a regular download, but just\n       the * wildcard character alone is not allowed.\n\n   10. Now, the bbs scans the specified paths from the CONFICON and\n       when it finds the file that the user requested, it displays the\n       file length in Kbytes, time required to download it at current baud\n       rate, and checks if the user has enough credits to download the\n       file.  If so, AmiExpress checks the filename against what is in\n       existing File Flag list and if it isn''t already there, it adds it.\n       So, if the download sequence is aborted for any reason, just hitting\n       "D" again will download the flagged file.  To remove from flaglist,\n       the user would use the ''A'' command.\n\n   11. Now the BBS checks if there is an Comment at the File like\n       "RESTRICTED" or "FREE DOWNLOAD" ... if there is a Comment like this\n       then the BBS will display some messages when the File has a comment\n       like "RESTRICTED" it is not not allowed to download this file and\n       the bbs will write a comment into the BBS:NODE{x}/CALLERSLOG that a\n       user tried to download this File... and with this comment you can`t\n       download this file with a level of 255 and sysop download too.. so\n       the file is 100% save for downloading... if there is the comment\n       "FREE DOWNLOAD" the bbs will make this file free download and it\n       will costs no credits to download it...\n\n   12. After hitting return alone on a filespec prompt, the bbs re-checks\n       the totals to see if the batch is within the user''s limits.\n\n   13. If so, AmiExpress asks either to start, abort, or automatically\n       logoff at the end of the transfer.  The ''G''oodbye after transfer\n       gives the user 10 seconds to change his mind after the transfer\n       before performing an automatic disconnect sequence.\n\n   14. At this point the download sequence is about to begin and so the\n       necessary information is written to the BBS:NODE{x}/UDLOG.\n\n   15. At the end of the download, if the users'' security level is below\n       the one you choose for the tooltyp KEEP_UPLOAD_CREDIT, then the\n       user''s number of downloads and number of bytes downloaded get\n       updated with the new download stats.\n\n   16. At this point, the download sequence is completed, and the bbs tells\n       the user his new stats before returning back to the MAIN MENU\n       PROMPT.\n  =======================================================================\n@endnode\n@node Cap100206 "[ E ] - Enter a Message...."\n  =======================================================================\n  [ E ] - Enter a Message:\n          ~~~~~~~~~~~~~~~\n    This command allows the user to leave private or public mail to other\n    users on the system.  There are several options with this command and\n    they are outlined below.\n\n    1. Asks for who to send it to.  If a wildcard is used the search\n       will find the first user that fits the wildcard and will display\n       it and then ask if its correct, if the user says no then it\n       will search forward.  If it doesn''t find the user it will\n       exit back to the mainmenu prompt.\n\n    2. If the user just hits return on the TO: prompt it will send\n       the message to ALL.\n\n    3. A feature added in is to be able to leave a message to\n       "EALL" this means to EMAIL ALL people, this is only usable\n       by users you give access to writing EALL Messages by changing\n       the tooltype in the ACCESS ICON for the User. What this does is to\n       leave ONE message to ALL USERS , when a person calls\n       the system it searches for mail in that conference to that\n       user it will say they have mail, from the user that left the\n       "EALL" message.  The TO: will show the user who is receiving\n       the message with "(ALL)" after their name.  The message can\n       only be deleted by the sender or a user with SYSOP access\n\n    4. Another name that is valid in the TO: prompt is SYSOP, this\n       will be replaced by the Name of the SYSOP, in user slot 1\n\n    5. Next prompt is the Subject of the message, if the user just\n       hits return it will exit out of the enter message\n\n    6. The bbs will now ask if the message is to be readable only\n       by the receiver of the message or it will be public.\n\n    7. Now the user has entered the message editor.\n\n    8. Tabs now work in the editor, they are indicated by a ''|'' in\n       the header.\n\n    9. Ctrl-X in the message editor will delete the current line.\n\n   10. If you hit a return on a blank line you will exit the edit\n       to the edit command prompt.\n\n   11. The options are:\n\n        1. <A>bort   - Abort entering the message\n\n        2. <C>ont    - Continue entering the message, this option will\n                       print the last line with text and put the cursor\n                       at the end of the line.\n\n        3. <D>elete  - Allows a user to delete a specific line.\n\n        4. <E>dit    - Allows the user to change text within a line.\n\n        5. <F>ile    - Allows a user with tooltyp SYSOP_DOWNLOAD to attach\n                       a file to download to the message. This option\n                       will ask for the filename to attach to the message\n                       and if you wanted the file deleted with the\n                       message as its deleted.\n\n        6. <M>ci List- If you have a MCI Header in yar Message you are\n                       able to use this function. This function will\n                       display you the whole text with all MCI comment\n                       in it.\n\n        7. <L>ist    - List the message to the screen.\n\n        8. <S>ave    - Saves the message.\n\n        9. <X>fer    - Allows a User to upload a file into the MSGBASE\n                       and make this file automatically ATTACHED at a\n                       Message. To allow the user to do this he must\n                       have the tooltyp "ACS.PRI_MSGFILES" in his\n                       ACCESS ICON. If the Message the User writes is\n                       an ALL or EALL message the user must have\n                       "ACS.PUB_MSGFILES" turned on to do this.\n  =======================================================================\n@endnode\n@node Cap100207 "[ F ] - File Listings...."\n  =======================================================================\n  [ F ] - File Listings:\n          ~~~~~~~~~~~~~\n    This command allows the user get Full directory listings of the\n    catalogs maintained by the BBS. As mentioned before, this is\n    specified in the Tooltype NDIRS=<num> in the CONFICON.\n\n    1. If the number of directories in the conference is zero\n       or NDIRS is zero, then the bbs will display\n       "No files available in this conference." And drop the user\n       back to the main prompt.\n\n    2. Displays the file BBS:CONF/FILEHELP.txt only if\n       all the options were not specified on the command line\n\n    3. It will then ask for the directory to list including the\n       ''H''old directory. The hold directory can only be used\n       by a user with access greater than 200.\n\n    4. The specified directory will be displayed and will pause\n       if the NS hasn''t already been specified, at the users\n       lines per screen point.\n\n    5. On the pause prompt, you can select ''F'' for flaging files\n  =======================================================================\n@endnode\n@node Cap100208 "[ FS ] - Full Status View...."\n  =======================================================================\n  [ FS ] - Full Status View:\n           ~~~~~~~~~~~~~~~~\n    This option is used to allow the user to have a full view over his\n    access status in each conference. It will display Bytes Down/Uploaded\n    in each conference the user has access to and will display the RATIO\n    too.\n  =======================================================================\n@endnode\n@node Cap100209 "[ G ] - GoodBye (LOGOFF)...."\n  =======================================================================\n  [ G ] - Goodbye (LOGOFF):\n          ~~~~~~~~~~~~~~~~\n    This option is used to end the current session with the host\n    system by the remote user.  When the user hits ''G'', the bbs\n    performs several clean-up functions.\n\n    1. First checks to see if there was a ZooMail that hasn''t\n       been downloaded, if there was it would ask if the user\n       wanted to leave anyway.\n\n    2. The system then checks to see if there were any partial\n       uploads that the user hasn''t finished sending yet.  If\n       so then it would let the user know and ask if he wanted\n       to leave anyway.  If the user didn''t want to leave, then\n       the bbs would ask if the user wanted to view the files.\n       If the user did want to view them, then the bbs would go\n       into the resume routine showing the user the filename\n       and filesize, then ask if he wanted to resume on that\n       particular file.  If not then the bbs would ask if the user\n       wanted to delete the file.  If the user didn''t want to\n       delete the file then the bbs would go to the next file\n       that was to be resumed.\n\n    3. If the user hadn''t specified the ''Q'' at the ANSI color\n       prompt, or the SUPPRESS_QLOGON is given the bbs would\n       display the file: BBS:NODE{x}/LOGOFF.txt\n\n    4. Now the BBS will try to open a Module called "LOGOFF" or\n       "LOGOFF<node>". If the BBS will find such a module, it will\n       be started.\n  =======================================================================\n@endnode\n@node Cap100210 "[ H ] - Help Page...."\n  =======================================================================\n  [ H ] - Help:\n          ~~~~\n    This command displays the on-line help text file for the user to\n    refer to.\n    At this command, the bbs looks for and displays the file :\n    BBS:BBSHELP.TXT and if not found will say that No help is\n    currently available.\n  =======================================================================\n@endnode\n@node Cap100211 "[ J ] - Join Conference...."\n  =======================================================================\n  [ J ] - Join Conference:\n          ~~~~~~~~~~~~~~~\n    This command is used to switch from the current conference to\n    another conference that the user has access privilege to.\n    The BBS looks for the file BBS:NODE{x}/JOINCONF{SEC}.TXT and\n    tries to display it.  If not found, it will print a message\n    informing the user that the file is missing.\n    Then, prompts the user to enter the number of the conference they\n    wish to join.  If the user does not have access to the requested\n    conference, then the bbs will tell the user that they don''t have\n    access to that conference.\n    If the user has access to the requested conference, AmiExpress\n    switches to that conference and checks for mail for the user, and\n    then display any appropriate bulletin files if they exist.\n    If the Option "RELATIVE_CONFERENCES" is turned on in the CONF.DEF\n    ICON this will only display the Conferences on which the User have\n    access to.\n  =======================================================================\n@endnode\n@node Cap100212 "[ M ] - Mode Select...."\n  =======================================================================\n  [ M ] - Mode Select:\n          ~~~~~~~~~~~\n    This command switches between ANSI color output or Plain Monochrome\n    output on the users end.  When ansi is on, the bbs tries to display\n    files that have the extension by default. The normal plain\n    (.TXT) files are reverted to if extension files are not\n    found.\n  =======================================================================\n@endnode\n@node Cap100213 "[ MC ] - Enter MCI Comment...."\n  =======================================================================\n  [ MC ] - Enter MCI Comment:\n           ~~~~~~~~~~~~~~~~~\n    This command is the same as the normal "C"omment to Sysop command in\n    AMiEX. The only difference is that with that command you can enter\n    the comment to the Sysop MCI commands like displaying UserNames or\n    some other data over MCI. This command will implement the MCI header\n    so you don`t have to insert the MCI header by hand.\n  =======================================================================\n@endnode\n@node Cap100214 "[ ME ] - Enter MCI Message...."\n  =======================================================================\n  [ ME] - Enter MCI Message:\n          ~~~~~~~~~~~~~~~~~\n    This command is the same as the normal "E"nter Message command in\n    AmiEX. The only difference is that with that command you can enter\n    messages with MCI commands like displaying UserNames or some other\n    data over MCI. This command will implement the MCI header so you\n    don`t have to insert the MCI header by hand.\n  =======================================================================\n@endnode\n@node Cap100215 "[ N ] - New Files Since Date...."\n  =======================================================================\n  [ N ] - New Files Since Date:\n          ~~~~~~~~~~~~~~~~~~~~\n    This command allows the user to list files from specified date onwards\n    or from the last time they called the system. In other words, with\n    this command, users can see what the system has to offer in terms of\n    files since their last call.\n\n    1. If the number of directories in the conference is zero\n       then the bbs will display "No files available in this\n       conference." And drop the user back to the main prompt.\n\n    2. It will then ask for the date they want to list from.\n       The last date they were on will be the default, this is\n       selected by just hitting return alone.  Entering the date\n       to list from must be done as MM-DD-YY.\n\n    3. Next the bbs asks for the directory to search thru.  An ''A''\n       can be used to list all directories, also ''U'' can be\n       specified for the upload directory.  And H for the hold\n       directory. The hold directory can only be used by a user\n       with access greater than 200.\n\n    4. The Pause prompt works the same as described in the file\n       listing section.\n  =======================================================================\n@endnode\n@node Cap100216 "[ O ] - Operator Page...."\n  =======================================================================\n  [ O ] - Operator Page:\n          ~~~~~~~~~~~~~\n    This command is used by the remote user to call the system operator\n    for on-line chat.\n\n    1. First of all Express will check the SysopPagecounter to see if\n       the user already paged the sysop. If the user paged the sysop\n       more then the given maximum, express will automatically go to\n       comment writing instead of paging the sysop.\n\n    2. If the User is calling up the system operator for the first time\n       on the current session, the users name field be changed to a red\n       color when 3 bitplanes are active, and will have star preceding\n       his name if the bbs was booted in 1 bitplane. Also, if the\n       iconfied window is active, the name filed there will also be\n       highlighted a different color. In this way, a sysop can see if\n       the user on-line has requested to chat.\n\n    3. If the F7 Chat toggle flag is not set to allow paging\n       then the bbs says:\n\n          "Sorry, The SYSOP, is not around right now\n           You can use ''C'' to leave a comment."\n\n    4. If the chat toggle flag is set to allow paging, then the\n       bbs adds to BBS:NODE{x}/CALLERSLOG that the user paged\n       Then displays "Paging SYSOP (CTRL-C to Abort). ." followed\n       by bells and more dots.\n\n    5. If you, the SYSOP, wanted to chat with the user you would\n       Hit F1 to enter chat, then AmiExpress looks for the file\n       BBS:NODE{x}/STARTCHAT.TXT, and if found displays\n       it to the user. This can be a simple greeting to the user.\n       If this file is not found, then the standard sysop chat\n       active message is sent to the screen. The same F1 will exit\n       chat when you are finished and the bbs will display the File\n       BBS:NODE{x}/ENDCHAT.TXT. During chat, if ANSI mode is\n       selected, your text will be a different color than the user ones.\n  =======================================================================\n@endnode\n@node Cap100217 "[ Q ] - Quiet Node...."\n  =======================================================================\n  [ Q ] - Quiet Node:\n          ~~~~~~~~~~\n    This command will change the Quiet Node option you choose for a node.\n    With this command user can prevent other users for seeing them on\n    a node and can make himself like invisible.\n  =======================================================================\n@endnode\n@node Cap100218 "[ R ] - Read Mail...."\n  =======================================================================\n  [ R ] - Read Mail:\n          ~~~~~~~~~\n    This command is used to access the on-line mailing system to read\n    mail either to the user or for all users.  It is also used when a\n    certain message will be replied to.\n\n    1. First the bbs shows the read prompt\n\n    Msg. Options: A,D,F,R,Q,?,<CR> ( QUIT )>:\n\n     (1). <A>gain, displays the message currently on again.\n                   (specified by the ''a'' in the above line)\n\n     (2). <D>elete, allows the user to delete a message only\n                    if he left the message or the message is to him.\n                    Also a user with access of 210+ can delete any\n                    mail.\n\n     (3). <F>ile, will test if there is any Attached File to\n                 download.\n\n     (4). <R>eply, allowes the user to reply to the current message.\n                   The bbs will place the user on the SUBJECT: field\n                   with the previous subject and place the cursor on\n                   the end of the line. If the user wants to change\n                   the subject he can delete over the existing subject\n                   and enter a new one, or hitting return will keep the\n                   old subject.\n                   After this, the bbs will ask if the reply should\n                   be private, and by default this is set to No.\n                   Next, the bbs will ask whether to quote the current\n                   message in the reply, again the default is No.\n                   if the user selected Yes to quote the message, the\n                   entire message will be re-displayed and the bbs will\n                   prompt the user with the following:\n\n                   Enter Startline,Endline or (*=ALL, A=Abort):\n\n                   Where the user would have to type either a ''*'' to\n                   quote the whole message specify start and end\n                   lines separated by a comma.\n                   Then the user would be put in the on-line message\n                   editor to enter his message. Commands for the editor\n                   work in much the same way as the Enter Message\n                   command. For more information, please re-read the\n                   ENTER MESSAGE Command.\n\n    (5). <?>, this will display the full description of the packed\n              Mail Reading line and will help you.\n\n    (6). <CR=Next>, let you continue search for new messages\n\n    (7). "EH" - This allows the sysop to edit a messages\n                Header. You can change who the msg is to,\n                from, the subject and whether it is to be\n                a private message or not.\n\n    (8). "U"  - This will let the sysop go automatically to account\n                editing for the account the message is from. With this way\n                you can fast validate a newuser by reading the message and\n                go to account editing.\n  =======================================================================\n@endnode\n@node Cap100219 "[ RL ] - ReLogon...."\n  =======================================================================\n  [ RL ] - ReLogon:\n           ~~~~~~~\n    This command will make a RELOGON at the Node you start it. This will\n    drop the user back to the Normal Logon and will start a Module called\n    "RELOGON" or "RELOGON<node>" in SYSCMD Directory. If this Module\n    is available it will be started and if it is finished the user will\n    be dropped back to the Logonstring.\n  =======================================================================\n@endnode\n@node Cap100220 "[ S ] - Status of On-Line User...."\n  =======================================================================\n  [ S ] - Status of On-Line User:\n          ~~~~~~~~~~~~~~~~~~~~~~\n    This command simply reports the users'' current information pertaining\n    to his account. This is in the form of:\n\n       Caller Num.: 2049\n       Lst Date On: 05-14-93\n       Security Lv: 30\n       # Times On : 579\n       Ratio DL/UL: Disabled\n       Online Baud: 16800\n       Rate CPS UP: 0\n       Rate CPS DN: 0\n       Screen  Clr: NO\n       Protocol   : /X ZModem Internal\n\n       (Pause)...Space to Resume:\n\n                     Uploads            Downloads\n            Conf  Files    Bytes     Files    Bytes     Bytes Avail  Ratio\n            ----  -------  --------- -------  --------- -----------  -----\n               2>       0          0       0          0           0  DSBLD\n  =======================================================================\n@endnode\n@node Cap100221 "[ T ] - Time, at the system site...."\n  =======================================================================\n  [ T ] - Time, at the system site:\n          ~~~~~~~~~~~~~~~~~~~~~~~~\n    This command reports back to the user what the internal battery backed\n    up clock at the bbs site is set at.  Local time/date stamp function.\n  =======================================================================\n@endnode\n@node Cap100222 "[ U ] - Upload File(s)...."\n  =======================================================================\n  [ U ] - Upload File(s):\n          ~~~~~~~~~~~~~~\n    This command puts the bbs in the file receive mode, where the remote\n    user can send files to the system.\n\n    1. The bbs first checks to see if there are file directories to be\n       uploaded to, by looking at NDIRS=<num> tooltyp. If this type is\n       unavailable or reports zero, the user is returned back to the\n       MAIN MENU PROMPT after a message stating "No files available in this\n       conference."\n\n    2. If a file called BBS:CONF/UPLOADMSG.txt exists\n       the bbs displays that to the user.\n\n    3. The bbs now calculates free disk space, the first number\n       displayed, is the amount of free space on all the drives\n       listed in DRIVES.DEF.INFO in BBS: directory.\n\n       Only drives that contain download files for the bbs\n       should be included, this way the user knows how much\n       free space is left on the total system.\n\n       The second number displayed is the amount of free space\n       only in the BBS:CONF/UPLOAD directory. This is so the\n       bbs and the user know exactly how much space is available\n       to receive uploads until the sysop does some maintanence.\n\n       Currently the bbs is content to allow uploads until the\n       free space in BBS:CONF/UPLOAD is less than 2.000.000 bytes\n\n    4. At this point the bbs calls the resume routine to check\n       if there are any files to resume on, this works the same\n       as explained under the ''G''oodbye command.\n\n    5. The bbs will then ask the user to enter the filenames of the\n       files he will be uploading, or he can press return alone to\n       have zmodem tell the bbs the names.  Specifing an ''A'' will\n       abort out of upload altogether and drop the user back to the\n       main prompt.\n\n    6. If the user enters the filenames, the bbs will check to make\n       sure they don''t already exist in the conference, if not the\n       bbs will ask him to enter the description for each file.\n       Entering a blank line to end the description.\n\n    7. Next the bbs will display:\n       (Enter) to Start, (G)oodbye after transfer, (A)bort?\n       this works the same as specified in the download routines.\n\n       At this point the Sysop is able to press "L" for start a\n       local upload routine, which will pop up an Requester for\n       selecting files to upload LOCAL into the BBS without starting\n       the ZMODEM Tranfer over the Serial In/Output.\n\n    8. At this point if the user has not been added to the end of\n       BBS:NODE{x}/UDLOG he will be.\n\n    9. If the Upload will now be started the bbs will check in the file\n       you specified for the FILESNOTALLOWED=<pathname> option in NODE\n       ICON. If this file is not allowed to be uploaded it will skip\n       the upload.\n\n   10. The bbs displays the stats from the transfer for all the\n       files.\n\n   11. The users time is credited for the uploads.\n\n   12. Next the bbs goes thru the files sent and checks to see if\n       the name is longer than 12 characters, if so the bbs asks\n       the user to rename the file.\n\n   13. The bbs then checks to see if the user has already given\n       the descriptions for the file, if so it posts it accordingly.\n\n   14. If the user has not already given the description the bbs\n       asks for the description for the file. Again giving 8 lines\n       for the description.\n\n   15. If the user gets disconnected while entering the description\n       the bbs will put "LOSS CARRIER" for the description.\n       and place the file in the BBS:CONF/LCFILES directory\n       along with a Comment in the <usernumber>.lc which will contain\n       a list of all the files he will need to enter descriptions for\n       when he calls back. The Re-Enter description process is\n       done at log on with the PartUploads routine.\n\n   16. Once the description has been entered the bbs checks if there\n       is a door called "FILECHECK" in the SYSCMD directory it will be\n       executed and the normal "FCHECK" will be skipped. Here you can\n       use a internal door for checking your files.\n       If the door doesn`t exists express will check if there is a\n       file extension. (a file extension is usually on 3 characters\n       preceded by a ''.''.)\n\n          Express now compares the extension with any ICON\n          of the same extension name in the BBS:FCheck directory.\n\n          ICONS in the Fcheck directory specify that you are using\n          external file checkers. The format for each ICON has been\n          mentioned below.\n\n          If no external checker exists for the file then it\n          will be posted with a comment "N" for non checked.\n\n   17. If the archive is checked and it passes the bbs puts\n       a ''P'' between the filename and filesize in the listing.\n\n   18. If the archive is checked and if found bad then the bbs\n       puts a ''F'' between the filename and filesize in the listing.\n\n   19. If the file is not one of the above checkable file types\n       then the bbs puts a ''N'' between the filename and the\n       filesize in the listing.\n\n   20. Now the bbs will post the file in a listings area.  If the\n       user specified a ''/'' at the beginning of the description\n       for the file, or the file failed archive check, or the\n       user got disconnected then the bbs posts the file to the\n       end of BBS:CONF/HOLD/HELD  If the archive passed or wasn''t\n       checkable and the user didn''t specify a ''/'' at the beginning\n       of the description then the bbs will post the file to the\n       end of BBS:CONF/DIR{u} where u is the upload directory (or\n       the highest directory available)\n\n   21. If when the bbs goes to move the file, like to the hold\n       directory and there is already a file in the hold with the\n       same name, the bbs will add a ''_'' to the end of the filename\n       until it can rename it to there.\n\n   22. Once all the file are exhausted the bbs checks to make sure\n       there aren''t any free floating files in the BBS:NODEx/PLAYPEN\n       directory, if there are the bbs moves the files to\n       BBS:CONF/PARTUPLOAD as partially uploaded files from the\n       current user online.\n  =======================================================================\n@endnode\n@node Cap100223 "[ V ] - View a Text File...."\n  =======================================================================\n  [ V ] - View a Text File:\n          ~~~~~~~~~~~~~~~~\n    This command allows the user to view the contents of a TEXT file\n    located in the BBS:CONFNAME/UPLOAD directory. For Co-Sysop''s with\n    Access to SYSOP_VIEW in Access ICONS, TEXT files can be viewed\n    from any valid system path.\n\n    1. The bbs first checks to see if there are file dirs in that conf.\n       by looking the tooltyp NDIRS=<num>. If this type is unavailable or\n       reports zero, the user is returned back to the MAIN MENU PROMPT\n       after a message stating "No files available in this conference."\n\n    2. The bbs then asks the user for the filename to view.\n\n    3. If the user has ACCESS to the SYSOP_VIEW Option and he specified\n       ''VS'' instead of just ''V'' then allow the filename to\n       include the path. The sysop view is noted at the end\n       of BBS:NODE{x}/CALLERSLOG what file was viewed.\n\n    4. The bbs then displays the file as long as the characters\n       in the file are < 128 in value.  If a character is\n       greater than 127 then the bbs says "This file is not a\n       text file." And drops back to the main prompt.\n\n         NOTE: If a file has a comment of RESTRICTED then the user\n         ~~~~  will not be able to view the file. If an attempt was\n               made then the users name will be annotated in the\n               BBS:NODE{x}/CallersLog\n  =======================================================================\n@endnode\n@node Cap100224 "[ W ] - Write User Parameters...."\n  =======================================================================\n  [ W ] - Write User Parameters:\n          ~~~~~~~~~~~~~~~~~~~~~\n    This command allows the user to change some personal items pertaining\n    to his account on the system.\n    When called, this command brings up the following:\n\n            1. Name     : Mike Thomas\n            2. From     : Dover, NH\n            3. Phone    : 603-555-1212\n            4. Password : ??????\n            5. NumLines : 23\n            6. Computer : Amiga 2000/GVP030\n            7. Scr Type : Amiga Ansi\n            8. Protocol : /X ZModem INTERNAL\n            9. Scrn Clr : N\n\n            Which to change <CR>= QUIT ?\n\n     At this prompt, the user can select which item to change, or hit\n     return alone to exit from this routine.\n     The first four items can be security set by the config program so\n     that users without the necessary security cannot change their\n     Name, From, Phone or Password. For more information, refer to the\n     documentation for the AmiConfig program.\n  =======================================================================\n@endnode\n@node Cap100225 "[ WHO ] - Node Information...."\n  =======================================================================\n  [ WHO ] - Node Information:\n            ~~~~~~~~~~~~~~~~\n    This command shows the user which users are online on the other nodes\n    and what they are doing actually. If you choose QUIETNODE for a\n    specified node, this node will be skipped in displaying it at this\n    information.\n  =======================================================================\n@endnode\n@node Cap100226 "[ X ] - Expert Mode Toggle...."\n  =======================================================================\n  [ X ] - Expert Mode Toggle:\n          ~~~~~~~~~~~~~~~~~~\n    This command allows the user to switch between eXpert and Novice mode\n    where expert mode will not display the menu unless a ''?'' is specified\n    at the command line and Novice will redisplay the menu after every\n    command issued and completed.\n  =======================================================================\n@endnode\n@node Cap100227 "[ Z ] - Zippy Text Search...."\n  =======================================================================\n  [ Z ] - Zippy Text Search:\n          ~~~~~~~~~~~~~~~~~\n    This command allows the user to scan thru all the BBS:CONFNAME/DIR{x}\n    files for a match for a specified string.\n    When it finds a match, it displays the whole filespec including the\n    description.\n    If the NDIRS=<num> tooltype reports zero or does not exist, then\n    zippy search will not be functional.\n  =======================================================================\n@endnode\n@node Cap100228 "[ ZOOM ] - Zoo Mail...."\n  =======================================================================\n  [ ZOOM ] - Zoo Mail:\n             ~~~~~~~~\n       Zoo mail has been reinstalled into Ami-Express and now relies\n       on current compression schemes provided by modem manufacturers\n       instead of Zoo, as zoo has a tendency to crash the Amiga\n       in certain instances. ZOOM will compile all the user''s unread\n       mail from ALL accessible conferences into a freely downloadable\n       file that will be auto-matically added to the flaglist for\n       downloading.\n  =======================================================================\n@endnode\n@node Cap11 "AREXX Interface MODULES (AIM)...."\n  =======================================================================\n                         AmiExpress HOST Adresses\n                         ~~~~~~~~~~~~~~~~~~~~~~~~\n  Amiexpress allowes the use of external HOST Adresses to start Modules,\n  which can be executed by the user by a specified key. These host\n  addresses can be used by programmers to code Modules working with Amiex.\n  These HOST Adresses can be used in much program languages\n  (AREXX,C,ASSEMBLER aso.). To give the programmer more abilities\n  Amiexpress provides much COMMANDOS via the HOST Address to get and put\n  informations to the running amiexpress nodes. These commands are\n  shared in different areas.\n\n    @{" Standard HOST Commands       " Link Cap1101}    @{" Special Arexx HOST Cmds (AIM)" Link Cap1102}\n    @{" Traditonal HOST Cmds    (TIM)" Link Cap1103}    @{" AmiExpress Interface    (XIM)" Link Cap1104}\n    @{" AmiExpress Script HOST  (SIM)" Link Cap1105}\n\n  =======================================================================\n@endnode\n@node Cap1102 "Special Arexx HOST Cmds (AIM)...."\n  =======================================================================\n  The Arexx door interface requires a file called RexxDoor, It must be in\n  located in your UTILS: path. This will also require an directory\n  called BBSCMD or CONF{x} to be either located in the BBS:Commands\n  directory. RexxDoor will be launched each time an Arexx door is\n  requested.\n\n  NOTE: If a CARRIER LOSS is detected or a KeyBoard timeout is detect then\n  ~~~~  an error code of 10 will be sent to the Arexx Script and RexxDoor\n        will orderly close any ports to the BBS and itself from the Arexx\n        Script.\n\n  Now we want to discuss all the Arexx Commands which can be used to\n  read & write information of the User & the BBS. These Arexx commands\n  are only useful if you want to program some tools for AmiExpress, and\n  for that it is very hard to understand for a guy who never programmed\n  arexx. But now lets go on:\n\n  NOTE: These are internal and do not pertain to the Module Glue routines\n  ~~~~  for designing doors.\n\n  To register an AREXX Module to Amiexpress you must have the following\n  lines at first at your AREXX Modules:\n\n  ------ cut here ------\n  /* Arexx Module TEST */\n\n  parse arg NODE\n  options results\n  address value "AERexxControl"NODE\n  ------ cut here ------\n\n  Without this commandos at the first lines in your modules, the modules\n  will not work together with amiexpress, so be sure you have these\n  commandos at the beginning of each AIM Module.\n\n  The following Commandos are AmiEX AreXX HOST Commandos which are\n  used to give the ability to the programmer to design his modules.\n  To use this commandos the Initializing of Amiexpress Module must be\n  made as listed above.\n\nCOMMAND NAME   FUNCTION\n=========================================================================\nGETUSER <x>    This command will read DATA from the FUNCTION <x> of the\n               decimal HOST Commands. This DATA will be transferred to\n               the normal RESULT function of AREXX. With this command\n               you are able to get the BBSNAME or other things.\n               For more informations about the FUNCTION numbers, please\n               look at the ''Standard HOST Commands'' of Express.\n=========================================================================\nPUTUSER <x>    This command is exactly the same as the GETUSER command\n               with the difference that it will store DATA and not read\n               it from the FUNCTION <x>. To store the DATA to a\n               FUNCTION <x> you also need the PUTUSTR together with\n               PUTUSER because PUTUSER must know what to store into the\n               FUNCTION <x>.\n=========================================================================\nPUTUSTR <x>    This Arexx command will define the DATA depending to the\n               PUTUSER command for the HOST commandos of AmiEx.\n               Use this TWO Arexx HOST Commandos together to execute\n               Commandos which belongs to Express.\n               example:\n\n               PUTUSTR "g" <- the variable you want to put into the\n               PUTUSER 136 <- FUNCTION 136.\n\n               These two commandos together will execute the internal\n               GOODBYE Main Menu Commando and will leave the BBS.\n               The ''136'' depending on the other HOST COMMANDOS programmed\n               with decimal Codes.\n=========================================================================\nTRANSMIT ""    This commando is the most important HOST Commando of\n               the AREXX HOST Commandos of AmiExpress. This commando\n               will send text over the serial depending in "" to\n               the NODE Window the module was executed.\n               example:\n               TRANSMIT "HALLO"\n\n               Now HALLO should appear in the NODE Window the Module\n               was executed.\n=========================================================================\nSENDMESSAGE    This Commando is exactly the same as the TRANSMIT commando\n               with the only difference that it will not send an carriage\n               return after executing the commando, so you can store\n               text behind other text.\n=========================================================================\nGETCHAR        This Commando will wait for input from the User to insert\n               and this input will be later transferred to the RESULT\n               Command of normal AREXX. With this command you are able\n               to ask the user questions and transfer the answer to\n               different variables.\n=========================================================================\nPROMPT ""      This Commando is the mix of the TRANSMIT & GETCHAR\n               commandos. After displaying the TEXT in the "" it will\n               PROMPT the user to insert something until he pressed\n               return. Then the DATA will go to the normal RESULT\n               routine of AREXX.\n=========================================================================\n@endnode\n@node Cap1101 "Standard Amiexpress HOST Commandos...."\n=========================================================================\n                    Standard AmiExpress HOST Commandos\n                    ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n  The following list is a list of all Amiexpress HOST Commandos which\n  can be used in every program language to get/store information to the\n  AmiExpress Host Port. With this commandos you can get informations\n  like BBSNAME, USERNAME etc. Click on the Buttons for more informations.\n\n    @{" JH_LI            <Func: 000> " Link Cap1101000}    @{" JH_REGISTER      <Func: 001> " Link Cap1101001}\n    @{" JH_SHUTDOWN      <Func: 002> " Link Cap1101002}    @{" JH_WRITE         <Func: 003> " Link Cap1101003}\n    @{" JH_SM            <Func: 004> " Link Cap1101004}    @{" JH_PM            <Func: 005> " Link Cap1101005}\n    @{" JH_HK            <Func: 006> " Link Cap1101006}    @{" JH_SG            <Func: 007> " Link Cap1101007}\n    @{" JH_SF            <Func: 008> " Link Cap1101008}    @{" JH_EF            <Func: 009> " Link Cap1101009}\n    @{" JH_CO            <Func: 010> " Link Cap1101010}    @{" JH_BBSNAME       <Func: 011> " Link Cap1101011}\n    @{" JH_SYSOP         <Func: 012> " Link Cap1101012}    @{" JH_FLAGFILE      <Func: 013> " Link Cap1101013}\n    @{" DT_NAME          <Func: 100> " Link Cap1101100}    @{" DT_PASSWORD      <Func: 101> " Link Cap1101101}\n    @{" DT_LOCATION      <Func: 102> " Link Cap1101102}    @{" DT_PHONENUMBER   <Func: 103> " Link Cap1101103}\n    @{" DT_SLOTNUMBER    <Func: 104> " Link Cap1101104}    @{" DT_ACCESSLEVEL   <Func: 105> " Link Cap1101105}\n    @{" DT_RATIOTYPE     <Func: 106> " Link Cap1101106}    @{" DT_RATIO         <Func: 107> " Link Cap1101107}\n    @{" DT_COMPTYPE      <Func: 108> " Link Cap1101108}    @{" DT_MESSAGESPOSTED<Func: 109> " Link Cap1101109}\n    @{" DT_UPLOADS       <Func: 110> " Link Cap1101110}    @{" DT_DOWNLOADS     <Func: 111> " Link Cap1101111}\n    @{" DT_TIMESCALLED   <Func: 112> " Link Cap1101112}    @{" DT_TIMELASTON    <Func: 113> " Link Cap1101109}\n    @{" DT_TIMEUSED      <Func: 114> " Link Cap1101114}    @{" DT_TIMELIMIT     <Func: 115> " Link Cap1101115}\n    @{" DT_TIMETOTAL     <Func: 116> " Link Cap1101116}    @{" DT_BYTESUPLOAD   <Func: 117> " Link Cap1101117}\n    @{" DT_BYTEDOWNLOAD  <Func: 118> " Link Cap1101118}    @{" DT_DAILYBYTELIMIT<Func: 119> " Link Cap1101119}\n    @{" DT_DAILYBYTEDLD  <Func: 120> " Link Cap1101120}    @{" DT_EXPERT        <Func: 121> " Link Cap1101121}\n    @{" DT_LINELENGTH    <Func: 122> " Link Cap1101122}    @{" ACTIVE_NODES     <Func: 123> " Link Cap1101123}\n    @{" DT_DUMP          <Func: 124> " Link Cap1101124}    @{" DT_TIMEOUT       <Func: 125> " Link Cap1101125}\n    @{" BB_CONFNAME      <Func: 126> " Link Cap1101126}    @{" BB_CONFLOCAL     <Func: 127> " Link Cap1101127}\n    @{" BB_LOCAL         <Func: 128> " Link Cap1101128}    @{" BB_STATUS        <Func: 129> " Link Cap1101129}\n    @{" BB_MAINLINE      <Func: 131> " Link Cap1101131}    @{" RETURNCOMMAND    <Func: 136> " Link Cap1101136}\n    @{" ZMODEMSEND       <Func: 137> " Link Cap1101137}    @{" ZMODEMRECEIVE    <Func: 138> " Link Cap1101138}\n    @{" SCREEN_ADDRESS   <Func: 139> " Link Cap1101139}    @{" BB_TASKPRI       <Func: 140> " Link Cap1101140}\n    @{" RAWSCREEN_ADDRESS<Func: 141> " Link Cap1101141}    @{" BB_CHATFLAG      <Func: 142> " Link Cap1101142}\n    @{" DT_STAMP_LASTON  <Func: 143> " Link Cap1101143}    @{" DT_STAMP_CTIME   <Func: 144> " Link Cap1101144}\n    @{" DT_CURR_TIME     <Func: 145> " Link Cap1101145}    @{" DT_CONFACCESS    <Func: 146> " Link Cap1101146}\n    @{" BB_NODEID        <Func: 149> " Link Cap1101149}    @{" BB_CALLERSLOG    <Func: 150> " Link Cap1101150}\n    @{" BB_UDLOG         <Func: 151> " Link Cap1101151}    @{" EXPRESS_VERSION  <Func: 152> " Link Cap1101152}\n    @{" BB_CHATSET       <Func: 162> " Link Cap1101162}    @{" ENVSTAT          <Func: 163> " Link Cap1101163}\n    @{" NODE_DEVICE      <Func: 503> " Link Cap1101503}    @{" NODE_UNIT        <Func: 504> " Link Cap1101504}\n    @{" NODE_BAUD        <Func: 505> " Link Cap1101505}    @{" JH_MCI           <Func: 507> " Link Cap1101507}\n    @{" PRV_COMMAND      <Func: 508> " Link Cap1101508}    @{" BB_CONFNUM       <Func: 510> " Link Cap1101510}\n    @{" BB_DROPDTR       <Func: 511> " Link Cap1101511}    @{" BB_GETTASK       <Func: 512> " Link Cap1101512}\n    @{" NODE_BAUDRATE    <Func: 516> " Link Cap1101516}    @{" BB_LOGONTYPE     <Func: 517> " Link Cap1101517}\n    @{" BB_SCRLEFT       <Func: 518> " Link Cap1101518}    @{" BB_SCRTOP        <Func: 519> " Link Cap1101519}\n    @{" BB_SCRWIDTH      <Func: 520> " Link Cap1101520}    @{" BB_SCRHEIGHT     <Func: 521> " Link Cap1101521}\n    @{" BB_PURGELIN      <Func: 522> " Link Cap1101522}    @{" BB_PURGELINESTART<Func: 523> " Link Cap1101523}\n    @{" BB_PURGELINEEND  <Func: 524> " Link Cap1101524}    @{" BB_NONSTOPTEXT   <Func: 525> " Link Cap1101525}\n    @{" BB_LINECOUNT     <Func: 526> " Link Cap1101526}    @{" DT_LANGUAGE      <Func: 527> " Link Cap1101527}\n    @{" DT_QUICKFLAG     <Func: 528> " Link Cap1101528}    @{" DT_GOODFILE      <Func: 529> " Link Cap1101529}\n\n=========================================================================\n@endnode\n@node Cap1101000 "JH_LI             <Func: 000>"\n=========================================================================\nJH_LI          Requests a string of information from the user with a\n               default string.\n\n               msg->Command = 0\n               msg->String  = default result string\n               msg->Data    = Maximum length of response.\n\n               msg->Data will be set to a -1 if a loss carrier or console\n               timeout occurs, otherwise msg->Data will be 1\n\n               msg->String will be the response string from the user.\n(FUNCTION #: 0 )\n=========================================================================\n@endnode\n@node Cap1101001 "JH_REGISTER       <Func: 001>"\n=========================================================================\nJH_REGISTER    Registers a door or XIM with the current node.\n\n               msg->Command = 1\n\n               This must be the first command issued to the express node.\n               This increments the number of doors active for the current\n               node.\n(FUNCTION #: 1 )\n=========================================================================\n@endnode\n@node Cap1101002 "JH_SHUTDOWN       <Func: 002>"\n=========================================================================\nJH_SHUTDOWN   Tells the node that a door is shutting down, this decreases\n              the number of active doors indicator , which once at 0,\n              the AEDoorPort will close.\n\n              msg->Command = 2\n              msg->Data    = N/A\n(FUNCTION #: 2 )\n=========================================================================\n@endnode\n@node Cap1101003 "JH_WRITE          <Func: 003>"\n=========================================================================\nJH_WRITE        Allows you to send a text string to the user.\n\n                msg->Command = 3\n                msg->String  = text\n                msg->Data    = N/A\n(FUNCTION #: 3 )\n=========================================================================\n@endnode\n@node Cap1101004 "JH_SM             <Func: 004>"\n=========================================================================\nJH_SM           Allows you to send a text string to the user.\n\n                msg->Command = 4\n                msg->String  = text\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then a CR/LF combination will be sent.\n(FUNCTION #: 4 )\n=========================================================================\n@endnode\n@node Cap1101005 "JH_PM             <Func: 005>"\n=========================================================================\nJH_PM           Allows you to prompt the user for a specified number of\n                characters.\n\n                msg->Command = 5\n                msg->String  = prompt string\n                msg->Data    = maximum response length.\n\n                if msg->Data = -1, then a loss carrier has occurred or a\n                timeout condition has occurred, otherwise msg->Data = 1.\n\n                msg->String will be the user response.\n(FUNCTION #: 5 )\n=========================================================================\n@endnode\n@node Cap1101006 "JH_HK              <Func: 006>"\n=========================================================================\nJH_HK           Allows you to get a 1 character response from the user.\n\n                msg->Command = 6\n                msg->String  = text\n                msg->Data    = N/A\n\n                if msg->Data = -1, then a loss carrier has occurred or a\n                timeout condition has occurred, otherwise msg->Data = 1.\n\n                msg->String will be the result string.\n(FUNCTION #: 6 )\n=========================================================================\n@endnode\n@node Cap1101007 "JH_SG             <Func: 007>"\n=========================================================================\nJH_SG           Allows you to display a text file to the user.\n\n                msg->Command = 7\n                msg->String  = part file name.\n                msg->Data    = N/A\n\n                ie:\n\n                msg->String = "BBS:Node1/Bull\n\n                This would try to display BBS:Node1/Bull.txt\n                also takes into account language specifications.\n\n                This also searches for the access level patterns, ie:\n\n                Bull10.txt, Bull100.txt\n(FUNCTION #: 7 )\n=========================================================================\n@endnode\n@node Cap1101008 "JH_SF             <Func: 008>"\n=========================================================================\nJH_SF           Allows you to display a text file to the user.\n\n                msg->Command = 8\n                msg->String  = Complete pathname\n                msg->Data    = N/A\n\n                ie:\n\n                msg->String  = "BBS:Node1/Bull.txt"\n\n                This would show the file if it exists.\n(FUNCTION #: 8 )\n=========================================================================\n@endnode\n@node Cap1101009 "JH_EF             <Func: 009>"\n=========================================================================\nJH_EF          Allows you to use the internal msgbase editor to edit your\n               own files.\n\n               msg->Command = 9\n               msg->String  = Complete pathname\n               msg->Data    = 0\n\n               if msg->Data = -1, then a loss carrier has occurred or a\n               timeout has occurred, otherwise msg->Data will be 1.\n(FUNCTION #: 9 )\n=========================================================================\n@endnode\n@node Cap1101010 "JH_CO             <Func: 010>"\n=========================================================================\nJH_CO          Allows you to send text string to the console only.\n\n               msg->Command = 10\n               msg->String  = text\n               msg->Data    = 1 or 0\n\n               if msg->Data = 1, then a CR/LF combination will be sent in\n               addition to the text.\n(FUNCTION #: 10 )\n=========================================================================\n@endnode\n@node Cap1101011 "JH_BBSNAME        <Func: 011>"\n=========================================================================\nJH_BBSNAME      Allows you to retrieve the BBS Name.\n\n                msg->Command = 11\n                msg->Data    = N/A\n\n                msg->String will be the BBS name.\n(FUNCTION #: 11 )\n=========================================================================\n@endnode\n@node Cap1101012 "JH_SYSOP          <Func: 012>"\n=========================================================================\nJH_SYSOP        Allows you to retrieve the Sysop''s Name.\n\n                msg->Command = 12\n                msg->Data    = N/A\n\n                msg->String will be the Sysop name.\n(FUNCTION #: 12 )\n=========================================================================\n@endnode\n@node Cap1101013 "JH_FLAGFILE       <Func: 013>"\n=========================================================================\nJH_FLAGFILE     Allows you to add files to the list of flagged files.\n\n                msg->Command = 13\n                msg->String  = FileName\n                msg->Data    = N/A\n\n                Adds the msg->String to the list of flagged files for\n                downloading purposes,\n\n                NOTE: The files must be in the download path for this to\n                      work.\n(FUNCTION #: 13 )\n=========================================================================\n@endnode\n@node Cap1101100 "DT_NAME           <Func: 100>"\n=========================================================================\nDT_NAME         Allows you to retrieve or change users name/handle\n\n                msg->Command = 100\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String will be the name.\n                if msg->Data = 0, then name will be msg->String\n(FUNCTION #: 100 )\n=========================================================================\n@endnode\n@node Cap1101101 "DT_PASSWORD       <Func: 101>"\n=========================================================================\nDT_PASSWORD     Allows you to retrieve or change users password\n\n                msg->Command = 101\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String will be the password.\n                if msg->Data = 0, then the password will be msg->String.\n(FUNCTION #: 101 )\n=========================================================================\n@endnode\n@node Cap1101102 "DT_LOCATION      <Func: 102>"\n=========================================================================\nDT_LOCATION     Allows you to retrieve or change users location\n\n                msg->Command = 102\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String will be the location\n                if msg->Data = 0, then the location will be msg->String\n(FUNCTION #: 102 )\n=========================================================================\n@endnode\n@node Cap1101103 "DT_PHONENUMBER    <Func: 103>"\n=========================================================================\nDT_PHONENUMBER  Allows you to retrieve or change users phone number.\n\n               msg->Command = 103\n               msg->Data    = 1 or 0\n\n               if msg->Data = 1, then msg->String will be the phonenumber\n               if msg->Data = 0, ten phonenumber will be msg->String\n(FUNCTION #: 103 )\n=========================================================================\n@endnode\n@node Cap1101104 "DT_SLOTNUMBER     <Func: 104>"\n=========================================================================\nDT_SLOTNUMBER  Allows you to retrieve users slot number\n\n               msg->Command = 104\n               msg->Data    = 1\n\n               if msg->Data = 1, then msg->String will be the SLOTNUMBER.\n(FUNCTION #: 104 )\n=========================================================================\n@endnode\n@node Cap1101105 "DT_ACCESSLEVEL    <Func: 105>"\n=========================================================================\nDT_ACCESSLEVEL  Allows you to retrieve or change users access level.\n\n                msg->Command = 105\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String will be Accesslevel.\n                if msg->Data = 0, then Accesslevel will be msg->String.\n(FUNCTION #: 105 )\n=========================================================================\n@endnode\n@node Cap1101106 "DT_RATIOTYPE      <Func: 106>"\n=========================================================================\nDT_RATIOTYPE    Allows you to retrieve or change users RatioType\n\n                msg->Command = 106\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String will be RatioType.\n                if msg->Data = 0, then RatioType will be msg->String.\n(FUNCTION #: 106 )\n=========================================================================\n@endnode\n@node Cap1101107 "DT_RATIO          <Func: 107>"\n=========================================================================\nDT_RATIO        Allows you to retrieve or change users ratio\n\n                msg->Command = 107\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String will be ratio.\n                if msg->Data = 0, then ratio will be msg->String.\n(FUNCTION #: 107 )\n=========================================================================\n@endnode\n@node Cap1101108 "DT_COMPTYPE       <Func: 108>"\n=========================================================================\nDT_COMPTYPE     Allows you to retrieve or change users ComputerTypes code\n\n                msg->Command = 108\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String will be ComputerTypes.\n                if msg->Data = 0, then ComputerTypes will be msg->String.\n(FUNCTION #: 108 )\n=========================================================================\n@endnode\n@node Cap1101109 "DT_MESSAGESPOSTED <Func: 109>"\n=========================================================================\nDT_MESSAGESPOSTED Allows you to retrieve or change users MESSAGESPOSTED\n\n               msg->Command = 109\n               msg->Data    = 1 or 0\n\n               if msg->Data = 1, then msg->String will be MESSAGESPOSTED.\n               if msg->Data = 0, then MESSAGESPOSTED will be msg->String.\n(FUNCTION #: 109 )\n=========================================================================\n@endnode\n@node Cap1101110 "DT_UPLOADS        <Func: 110>"\n=========================================================================\nDT_UPLOADS      Allows you to retrieve or change number of useruploads.\n\n                msg->Command = 110\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String will be uploads.\n                if msg->Data = 0, then uploads will be msg->String.\n(FUNCTION #: 110 )\n=========================================================================\n@endnode\n@node Cap1101111 "DT_DOWNLOADS      <Func: 111>"\n=========================================================================\nDT_DOWNLOADS   Allows you to retrieve or change number of userdownloads.\n\n                msg->Command = 111\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String will be downloads.\n                if msg->Data = 0, then downloads will be msg->String.\n(FUNCTION #: 111 )\n=========================================================================\n@endnode\n@node Cap1101112 "DT_TIMESCALLED    <Func: 112>"\n=========================================================================\nDT_TIMESCALLED  Allows you to retrieve or change number of usercalls.\n\n                msg->Command = 112\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String will be timescalled.\n                if msg->Data = 0, then timescalled will be msg->String.\n(FUNCTION #: 112 )\n=========================================================================\n@endnode\n@node Cap1101113 "DT_TIMELASTON     <Func: 113>"\n=========================================================================\nDT_TIMELASTON   Allows you to retrieve or change time user last called.\n\n                msg->Command = 113\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String will be timescalled.\n                if msg->Data = 0, then timescalled will be msg->String.\n\n                NOTE: This is not a date stamp, this is the number of\n                      seconds since January 19something.\n(FUNCTION #: 113 )\n=========================================================================\n@endnode\n@node Cap1101114 "DT_TIMEUSED       <Func: 114>"\n=========================================================================\nDT_TIMEUSED     Allows you to retrieve or change TIMEUSED today.\n\n                msg->Command = 114\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String will be TIMEUSED.\n                if msg->Data = 0, then TIMEUSED will be msg->String.\n\n                NOTE: This is in seconds.\n(FUNCTION #: 114 )\n=========================================================================\n@endnode\n@node Cap1101115 "DT_TIMELIMIT      <Func: 115>"\n=========================================================================\nDT_TIMELIMIT    Allows you to retrieve or change timeallowed for a user.\n\n                msg->Command = 115\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String will be timelimit.\n                if msg->Data = 0, then timelimit will be msg->String.\n\n                NOTE: Time in seconds.\n(FUNCTION #: 115 )\n=========================================================================\n@endnode\n@node Cap1101116 "DT_TIMETOTAL      <Func: 116>"\n=========================================================================\nDT_TIMETOTAL   Allows you to retrieve or change total time remaining.\n               for a user today.\n\n               msg->Command = 116\n               msg->Data    = 1 or 0\n\n               if msg->Data = 1, then msg->String will be time remaining.\n               if msg->Data = 0, then time remaining will be msg->String.\n\n               NOTE: Time in seconds.\n(FUNCTION #: 116 )\n=========================================================================\n@endnode\n@node Cap1101117 "DT_BYTESUPLOAD    <Func: 117>"\n=========================================================================\nDT_BYTESUPLOAD  Allows you to retrieve or change bytes uploads per user.\n\n                msg->Command = 117\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String will be bytesuploaded.\n                if msg->Data = 0, then bytesuploaded will be msg->String.\n(FUNCTION #: 117 )\n=========================================================================\n@endnode\n@node Cap1101118 "DT_BYTEDOWNLOAD   <Func: 118>"\n=========================================================================\nDT_BYTEDOWNLOAD Allows you to retrieve or change bytes downloaded per\n                user.\n\n               msg->Command = 118\n               msg->Data    = 1 or 0\n\n               if msg->Data = 1, then msg->String will be bytesdownloaded.\n               if msg->Data = 0, then bytesdownloaded will be msg->String.\n(FUNCTION #: 118 )\n=========================================================================\n@endnode\n@node Cap1101119 "DT_DAILYBYTELIMIT <Func: 119>"\n=========================================================================\nDT_DAILYBYTELIMIT Allows you to retrieve or change a users daily byte\n                  download limit.\n\n                  msg->Command = 119\n                  msg->Data    = 1 or 0\n\n                  if msg->Data = 1, then msg->String will be bytelimit.\n                  if msg->Data = 0, then bytelimit will be msg->String.\n(FUNCTION #: 119 )\n=========================================================================\n@endnode\n@node Cap1101120 "DT_DAILYBYTEDLD   <Func: 120>"\n=========================================================================\nDT_DAILYBYTEDLD Allows you to retrieve or change daily bytes downloaded.\n\n                msg->Command = 120\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String will be dailybytes.\n                if msg->Data = 0, then dailybytes will be msg->String.\n(FUNCTION #: 120 )\n=========================================================================\n@endnode\n@node Cap1101121 "DT_EXPERT         <Func: 121>"\n=========================================================================\nDT_EXPERT         Allows you to retrieve or change expert mode.\n\n                  msg->Command = 121\n                  msg->Data    = 1 or 0\n(FUNCTION #: 121 )\n=========================================================================\n@endnode\n@node Cap1101122 "DT_LINELENGTH     <Func: 122>"\n=========================================================================\nDT_LINELENGTH     Allows you to retrieve or change user linelength specs.\n\n                  msg->Command = 122\n                  msg->Data    = 1 or 0\n\n                  if msg->Data = 1, then msg->String will be linelength.\n                  if msg->Data = 0, then linelength will be msg->String.\n(FUNCTION #: 122 )\n=========================================================================\n@endnode\n@node Cap1101123 "ACTIVE_NODES      <Func: 123>"\n=========================================================================\nACTIVE_NODES    Allows you to retrieve a string of active&inactive nodes.\n\n                msg->Command = 123\n                msg->Data    = N/A\n\n                msg->String will be a string 10 bytes in length, with\n                     ''X''s marking the active nodes.\n\n                NOTE: This command will surely be changing, the current\n                      limit is 9 nodes.\n(FUNCTION #: 123 )\n=========================================================================\n@endnode\n@node Cap1101124 "DT_DUMP           <Func: 124>"\n=========================================================================\nDT_DUMP           Allows you to dump the user''s data structure to a\n                  specified file.\n\n                  msg->Command = 124\n                  msg->String  = FileName\n(FUNCTION #: 124 )\n=========================================================================\n@endnode\n@node Cap1101125 "DT_TIMEOUT        <Func: 125>"\n=========================================================================\nDT_TIMEOUT       Allows you to retrieve or change the door timeout limit.\n\n                 msg->Command = 125\n                 msg->Data    = 1 or 0\n\n                 if msg->Data = 1, then msg->String will equal timeout.\n                 if msg->Data = 0, then timeout will equal msg->String.\n\n                 NOTE: This time is in seconds.\n(FUNCTION #: 125 )\n=========================================================================\n@endnode\n@node Cap1101126 "BB_CONFNAME       <Func: 126>"\n=========================================================================\nBB_CONFNAME       Allows you to retrieve or change the conference name.\n\n                  msg->Command = 126\n                  msg->Data    = 1 or 0\n\n                  if msg->Data = 1, then msg->String will be name.\n                  if msg->Data = 0, then name will be msg->String.\n(FUNCTION #: 126 )\n=========================================================================\n@endnode\n@node Cap1101127 "BB_CONFLOCAL      <Func: 127>"\n=========================================================================\nBB_CONFLOCAL    Allows you to retrieve or change the conference location.\n\n                msg->Command = 127\n                msg->Data    = 1 or 0\n\n                if msg->Data = 1, then msg->String will be location.\n                if msg->Data = 0, then location will be msg->String.\n(FUNCTION #: 127 )\n=========================================================================\n@endnode\n@node Cap1101128 "BB_LOCAL          <Func: 128>"\n=========================================================================\nBB_LOCAL          Allows you to retrieve the current BBS location.\n\n                  msg->Command = 128\n                  msg->Data    = N/A\n(FUNCTION #: 128 )\n=========================================================================\n@endnode\n@node Cap1101129 "BB_STATUS         <Func: 129>"\n=========================================================================\nBB_STATUS         Allows you to retrieve the current status of the node.\n\n                  msg->Command = 129\n                  msg->Data    = N/A\n\n                  msg->String will be ''OFFLINE'' or ''ONLINE'' depending on\n                  whether a user is logged onto the node.\n(FUNCTION #: 129 )\n=========================================================================\n@endnode\n@node Cap1101131 "BB_MAINLINE       <Func: 131>"\n=========================================================================\nBB_MAINLINE     Allows you to retrieve the menu prompt arguments prior to\n                the door being entered.\n\n                msg->Command = 131\n                msg->Data    = N/A\n\n                msg->String will be the menu prompt arguments.\n(FUNCTION #: 131 )\n=========================================================================\n@endnode\n@node Cap1101136 "RETURNCOMMAND     <Func: 136>"\n=========================================================================\nRETURNCOMMAND    Allows you to specify an internal command to be executed\n                 when the door is finished.\n\n                 msg->Command = 136\n                 msg->Data    = N/A\n\n                 command to be executed will be msg->String.\n(FUNCTION #: 136 )\n=========================================================================\n@endnode\n@node Cap1101137 "ZMODEMSEND        <Func: 137>"\n=========================================================================\nZMODEMSEND      Allows you to send files to the user via Zmodem protocol.\n\n                msg->Command = 137\n                msg->String  = filename (complete pathname)\n                msg->Data    = N/A\n\n                result of transfer will be in msg->Data, where\n\n                if msg->Data = 1 , then transfer successful.\n                if msg->Data = -2, then user lost carrier.\n                if msg->Data = 0 , then transfer unsuccessful.\n(FUNCTION #: 137 )\n=========================================================================\n@endnode\n@node Cap1101138 "ZMODEMRECEIVE     <Func: 138>"\n=========================================================================\nZMODEMRECEIVE    Allows you to receive batch uploads via Zmodem protocol.\n\n                 msg->Command = 138\n                 msg->String  = receive directory path\n                 msg->Data    = N/A\n\n                 result of transfer will be in msg->Data, where\n\n                 if msg->Data = 1 , then transfer successful.\n                 if msg->Data = -2, then user lost carrier.\n                 if msg->Data = 0,  then transfer unsuccessful.\n(FUNCTION #: 138 )\n=========================================================================\n@endnode\n@node Cap1101139 "SCREEN_ADDRESS    <Func: 139>"\n=========================================================================\nSCREEN_ADDRESS    Allows you to retrieve the screen address.\n\n                  msg->Command = 139\n                  msg->Data    = N/A\n\n                  msg->String will be a string containing the hexadecimal\n                  address of the Node screen.\n(FUNCTION #: 139 )\n=========================================================================\n@endnode\n@node Cap1101140 "BB_TASKPRI        <Func: 140>"\n=========================================================================\nBB_TASKPRI    Allows you to retrieve the priority the node is running at.\n\n              msg->Command = 140\n              msg->Data    = N/A\n\n              msg->String will contain the priority of the node.\n(FUNCTION #: 140 )\n=========================================================================\n@endnode\n@node Cap1101141 "RAWSCREEN_ADDRESS <Func: 141>"\n=========================================================================\nRAWSCREEN_ADDRESS Allows you to retrieve the screen address of the node.\n\n              msg->Command = 141\n              msg->Data    = N/A\n\n              msg->String will be a string containing the decimal address\n                   of the express node.\n(FUNCTION #: 141 )\n=========================================================================\n@endnode\n@node Cap1101142 "BB_CHATFLAG       <Func: 142>"\n=========================================================================\nBB_CHATFLAG       Allows you to retrieve the current chat setting.\n\n                  msg->Command = 142\n                  msg->Data    = N/A\n\n                  msg->String will be "ON" or "OFF".\n(FUNCTION #: 142 )\n=========================================================================\n@endnode\n@node Cap1101143 "DT_STAMP_LASTON   <Func: 143>"\n=========================================================================\nDT_STAMP_LASTON Allows you to retrieve a date string containing the date\n                of when the user last logged on.\n\n                msg->Command = 143\n                msg->Data    = N/A\n\n                msg->String will be the date string.\n(FUNCTION #: 143 )\n=========================================================================\n@endnode\n@node Cap1101144 "DT_STAMP_CTIME    <Func: 144>"\n=========================================================================\nDT_STAMP_CTIME    Allows you to retrieve a current time string.\n\n                  msg->Command = 144\n                  msg->Data    = N/A\n\n                  msg->String will be a current time string.\n(FUNCTION #: 144 )\n=========================================================================\n@endnode\n@node Cap1101145 "DT_CURR_TIME      <Func: 145>"\n=========================================================================\nDT_CURR_TIME     Allows you to retrieve the current time in seconds since\n                 January something.\n\n                 msg->Command = 145\n                 msg->Data    = N/A\n\n                 msg->String will be the current time.\n(FUNCTION #: 145 )\n=========================================================================\n@endnode\n@node Cap1101146 "DT_CONFACCESS     <Func: 146>"\n=========================================================================\nDT_CONFACCESS     Allows you to retrieve the users conference access.\n\n                  msg->Command = 146\n                  msg->Data    = 1 or 0\n\n                  if msg->Data = 1, then msg->String will be Areaname.\n                  if msg->Data = 0, then Areaname will be msg->String.\n\n(FUNCTION #: 146 )\n=========================================================================\n@endnode\n@node Cap1101149 "BB_NODEID         <Func: 149>"\n=========================================================================\nBB_NODEID         Allows you to retrieve the Node number for the current\n                  node\n\n                  msg->Command = 149\n                  msg->Data    = N/A\n\n                  msg->String will be the node number.\n(FUNCTION #: 149 )\n=========================================================================\n@endnode\n@node Cap1101150 "BB_CALLERSLOG     <Func: 150>"\n=========================================================================\nBB_CALLERSLOG     Allows you to add a line of text to the callerslog.\n\n                  msg->Command = 150\n                  msg->String  = text\n                  msg->Data    = N/A\n(FUNCTION #: 150 )\n=========================================================================\n@endnode\n@node Cap1101151 "BB_UDLOG          <Func: 151>"\n=========================================================================\nBB_UDLOG          Allows you to add a line of text to the udlog.\n\n                  msg->Command = 151\n                  msg->String  = text\n                  msg->Data    = N/A\n(FUNCTION #: 151 )\n=========================================================================\n@endnode\n@node Cap1101152 "EXPRESS_VERSION   <Func: 152>"\n=========================================================================\nEXPRESS_VERSION   Allows you to retrieve the current version string of\n                  express.\n\n                  msg->Command = 152\n                  msg->Data    = N/A\n(FUNCTION #: 152 )\n=========================================================================\n@endnode\n@node Cap1101162 "BB_CHATSET        <Func: 162>"\n=========================================================================\nBB_CHATSET     Allows you to retrieve or change the chat status.\n\n               msg->Command = 162\n               msg->Data    = 1 or 0\n\n               if msg->Data = 1, then msg->String will be current status.\n               if msg->Data = 0, then status will be msg->String.\n(FUNCTION #: 162 )\n=========================================================================\n@endnode\n@node Cap1101163 "ENVSTAT           <Func: 163>"\n=========================================================================\nENVSTAT          Allows you to retrieve or change the current environment\n                 stat variable code.\n\n                 msg->Command = 163\n                 msg->Data    = 1 or 0\n\n                 if msg->Data = 1, then msg->String will be status.\n                 if msg->Data = 0, then status will be msg->String.\n(FUNCTION #: 163 )\n=========================================================================\n@endnode\n@node Cap1101503 "NODE_DEVICE       <Func: 503>"\n=========================================================================\nNODE_DEVICE       Allows you to retrieve the node device name.\n\n                  msg->Command = 503\n                  msg->Data    = N/A\n\n                  msg->String will be the device string.\n(FUNCTION #: 503 )\n=========================================================================\n@endnode\n@node Cap1101504 "NODE_UNIT         <Func: 504>"\n=========================================================================\nNODE_UNIT         Allows you to retrieve the node unit number.\n\n                  msg->Command = 504\n                  msg->Data    = N/A\n\n                  msg->String will be the current node number.\n(FUNCTION #: 504 )\n=========================================================================\n@endnode\n@node Cap1101505 "NODE_BAUD         <Func: 505>"\n=========================================================================\nNODE_BAUD    Allows you to retrieve the initialized baud rate of the node.\n\n             msg->Command = 505\n             msg->Data    = N/A\n\n             msg->String will be the init baud rate.\n(FUNCTION #: 505 )\n=========================================================================\n@endnode\n@node Cap1101507 "JH_MCI            <Func: 507>"\n=========================================================================\nJH_MCI            Allows you to send mci text to express.\n\n                  msg->Command = 507\n                  msg->String  = text\n                  msg->Data    = N/A\n(FUNCTION #: 507 )\n=========================================================================\n@endnode\n@node Cap1101508 "PRV_COMMAND       <Func: 508>"\n=========================================================================\nPRV_COMMAND       Allows you to immediately execute an internal express\n                  menu command.\n\n                  msg->Command = 508\n                  msg->String  = commandstring\n                  msg->Data    = N/A\n(FUNCTION #: 508 )\n=========================================================================\n@endnode\n@node Cap1101510 "BB_CONFNUM        <Func: 510>"\n=========================================================================\nBB_CONFNUM     Allows you to retrieve the current conference number.\n\n               msg->Command = 510\n               msg->Data    = N/A\n\n               msg->String will be conference number ranging from 0 to 8.\n(FUNCTION #: 510 )\n=========================================================================\n@endnode\n@node Cap1101511 "BB_DROPDTR        <Func: 511>"\n=========================================================================\nBB_DROPDTR        Allows you to drop carrier on a user.\n\n                  msg->Command = 511\n                  msg->Data    = N/A\n(FUNCTION #: 511 )\n=========================================================================\n@endnode\n@node Cap1101512 "BB_GETTASK        <Func: 512>"\n=========================================================================\nBB_GETTASK        Finds the current nodes task address.\n\n                  msg->Command = 512\n                  msg->Data    = N/A\n\n                  msg->task will be the express task address.\n(FUNCTION #: 512 )\n=========================================================================\n@endnode\n@node Cap1101516 "NODE_BAUDRATE     <Func: 516>"\n=========================================================================\nNODE_BAUDRATE     Allows you to retrieve the current users connect rate\n\n                  msg->Command = 516\n                  msg->Data    = N/A\n\n                  msg->String will be the connect rate\n(FUNCTION #: 516 )\n=========================================================================\n@endnode\n@node Cap1101517 "BB_LOGONTYPE      <Func: 517>"\n=========================================================================\nBB_LOGONTYPE      Allows you to retrieve the LOGONTYPE.\n\n                  msg->Command = 517\n                  msg->Data    = N/A\n\n                  msg->Data will be:\n\n                  0 = AWAIT_LOGON\n                  1 = SYSOP_LOGON\n                  2 = LOCAL_LOGON\n                  3 = REMOTE_LOGON\n(FUNCTION #: 517 )\n=========================================================================\n@endnode\n@node Cap1101518 "BB_SCRLEFT        <Func: 518>"\n=========================================================================\nBB_SCRLEFT      Allows you to retrieve the screen coordinates.\n\n                msg->Command = 518\n                msg->Data    = N/A\n\n                msg->Data will be the Node''s Initial leftedge coordinate.\n(FUNCTION #: 518 )\n=========================================================================\n@endnode\n@node Cap1101519 "BB_SCRTOP         <Func: 519>"\n=========================================================================\nBB_SCRTOP        Allows you to retrieve the screen coordinates.\n\n                 msg->Command = 519\n                 msg->Data    = N/A\n\n                 msg->Data will be the Node''s Initial topedge coordinate.\n(FUNCTION #: 519 )\n=========================================================================\n@endnode\n@node Cap1101520 "BB_SCRWIDTH       <Func: 520>"\n=========================================================================\nBB_SCRWIDTH       Allows you to retrieve the screen coordinates.\n\n                  msg->Command = 520\n                  msg->Data    = N/A\n\n                  msg->Data will be the Node''s Initial screen height.\n(FUNCTION #: 520 )\n=========================================================================\n@endnode\n@node Cap1101521 "BB_SCRHEIGHT      <Func: 521>"\n=========================================================================\nBB_SCRHEIGHT      Allows you to retrieve the screen coordinates.\n\n                  msg->Command = 521\n                  msg->Data    = N/A\n\n                  msg->Data will be the Node''s Initial screen width.\n(FUNCTION #: 521 )\n=========================================================================\n@endnode\n@node Cap1101522 "BB_PURGELIN       <Func: 522>"\n=========================================================================\nBB_PURGELIN   Allows you to abort serial input.\n\n               msg->Command = 522\n               msg->Data    = N/A\n\n              aborts serial input and flushes the serial buffer and sends\n              a request for more input.\n(FUNCTION #: 522 )\n=========================================================================\n@endnode\n@node Cap1101523 "BB_PURGELINESTART <Func: 523>"\n=========================================================================\nBB_PURGELINESTART Allows you to CLEAR the serial buffer and request more\n                  serial input.\n\n                  msg->Command = 523\n                  msg->Data    = N/A\n(FUNCTION #: 523 )\n=========================================================================\n@endnode\n@node Cap1101524 "BB_PURGELINEEND   <Func: 524>"\n=========================================================================\nBB_PURGELINEEND   Allows you to CLEAR the serial buffer.\n\n                  msg->Command = 524\n                  msg->Data    = N/A\n(FUNCTION #: 524 )\n=========================================================================\n@endnode\n@node Cap1101525 "BB_NONSTOPTEXT    <Func: 525>"\n=========================================================================\nBB_NONSTOPTEXT    Allows you to change the NONSTOP text scrolling flag.\n\n                  msg->Command = 525\n                  msg->Data    = 1 or 0\n\n                  if msg->Data = 1, then display text will not pause.\n                  if msg->Data = 0, then display text will pause.\n(FUNCTION #: 525 )\n=========================================================================\n@endnode\n@node Cap1101526 "BB_LINECOUNT      <Func: 526>"\n=========================================================================\nBB_LINECOUNT   Allows you to retrieve or change the user''s current number\n               of lines viewed.\n\n               msg->Command = 526\n               msg->Data    = 1 or 0\n\n               if msg->Data = 1, then msg->String will be current line.\n               if msg->Data = 0, then current line will be msg->String.\n(FUNCTION #: 526 )\n=========================================================================\n@endnode\n@node Cap1101527 "DT_LANGUAGE       <Func: 527>"\n=========================================================================\nDT_LANGUAGE      Allows you to retrieve or change the current language\n                 specifications.\n\n                 msg->Command = 527\n                 msg->Data    = 1 or 0\n\n                 if msg->Data = 1, then msg->String will be language.\n                 if msg->Data = 0, then language will be msg->String.\n\n                NOTE: Languages need to be standardized, please what for\n                      guidelines.\n\n                ie:  Default language .txt\n                     English          .Eng\n                     German           .Ger\n\n                     note that this only effects the menus, bulletins &\n                     other screen text files.\n(FUNCTION #: 527 )\n=========================================================================\n@endnode\n@node Cap1101528 "DT_QUICKFLAG      <Func: 528>"\n=========================================================================\nDT_QUICKFLAG      Allows you to change the QUICKTEXT flag.\n\n                  msg->Command = 528\n                  msg->Data    = 1 or 0\n\n                  if msg->Data = 1, then the QuickFlag will be set.\n                  if msg->Data = 0, then the QuickFlag will not be set.\n(FUNCTION #: 528 )\n=========================================================================\n@endnode\n@node Cap1101529 "DT_GOODFILE       <Func: 529>"\n=========================================================================\nDT_GOODFILE       Allows you to set the results of a tested file after\n                  upload.\n\n                  msg->Command = 529\n                  msg->Data    = 1,0 or -1\n\n                  if msg->Data is 1, then the file was not tested.\n                  if msg->Data is 0, then the file passed the filetest.\n                  if msg->Data is -1, then the file failed the filetest.\n\n                  NOTE: This command is only useful with the sys.cmd door\n                  called FILECHECK.\n(FUNCTION #: 529 )\n=========================================================================\n@endnode\n@node Cap1103 "Traditonal Interface Module (TIM)\n=========================================================================\n\n  The Traditional interface provides the capability to run "DOORS"\n  designed for other Bulletin  Board Systems. This is not to say that it\n  will interpret all "DOORS" but some may work. The traditional interface\n  requires a file called PARADOOR, which is supplied with AmiExpress and\n  must be located in a path that AmiExpress can find. If a CARRIER LOSS\n  is detected or a keyboard timeout is detected, the BBS will notify the\n  Module, but it is up to the Module to do an orderly halt.  Most door\n  programmers know how to close their doors properly. AmiExpress\n  automatically launches the PARADOOR so please do not run it yourself.\n\n=========================================================================\n@endnode\n@node Cap1104 "AmiExpress Interface Module System (XIM)...."\n=========================================================================\n\n  My interface is by far the best of all of these put together, it\n  allows you to do a lot of stuff. The best part about this interface is\n  you don''t need a seperate program to access it. There will be a lot of\n  Modules out for this in the near future, we have several being made\n  right now.\n\n\n        ___________ message structure for use with the XIMs\n       |            NOTE: RexxDoors are translated to the same structure\n       v            ~~~~  via the RexxDoor utility\nstruct JHMessage\n{\n  struct Message Msg;   <----- msg structure\n  char String[200];     <----- info buffer\n  int Data;             <----- Read/Write & result indicator\n  int Command;          <----- Command sent from door.\n  int NodeID;           <----- reserved\n  int LineNum;          <----- reserved\n  unsigned long signal; <----- reserved\n  struct Process *task; <----- see BB_GETTASK below\n\n} ;\n\nPORTNAME: The portname for the XIMs is ''AEDoorPort(n)'' ie: AEDoorPort1\n=========================================================================\n@endnode\n@node Cap1105 "AmiExpress Script Module System (SIM)...."\n=========================================================================\n\n  This new interface can be used to execute Batchfiles instead of normal\n  Modules. This will execute Batchfiles normal as you execute it with\n  the EXECUTE Command.\n\n  TO USE this MODULETYPE the SCRIPT you want to be executed should have\n  the SCRIPT BIT turned on. You can do this like that:\n\n  1> protect S:SCRIPT s\n\n=========================================================================\n@endnode\n@node Cap12 "The MCI imbedded ControlSequence...."\n=========================================================================\n\n  Any text file may contain imbedded control sequences which will send out\n  variable text or cause certain things to happen.\n\n  MCI - Introducer:\n  ~~~~~~~~~~~~~~~~\n  ~ This is the MCI introducer, this must be at the beginning of\n    each text file by itself in order for Express to switch to the MCI\n    interpreter for displaying the text file.\n\n  MCI - User Specification:\n  ~~~~~~~~~~~~~~~~~~~~~~~~\n\n  ~N       User Name\n  ~UL      User Location\n  ~P       User PasswordP\n  ~#       User Phone\n  ~TC      Total User Calls\n  ~LC      User Last Call to the system\n  ~M       User Message Posted\n  ~A       User Access Level\n  ~S       User Slot Number\n  ~CA      User Conf. Access    **** NOTE CHANGED FROM X ****\n  ~BR      User BaudRate\n  ~HW      User Computer Equipment\n  ~TL      User Initial Time Limit at logon in Minutes\n  ~TR      User Number of Mins Remaining today\n  ~UB      User Bytes Uploaded\n  ~DB      User Bytes Downloaded\n  ~FU      User Files Uploaded\n  ~FD      User Files Downloaded\n  ~BD      User Byte Download Limit\n  ~LG      User Logged On-Node\n  ~Dx      Change the MCI command terminator.\n           i.e: ~D.| will change the ''|'' to ''.''\n\n\n  ~OD      Online Since Date\n  ~OT      Online Since Time\n  ~cx      Change foreground ansi color to anything from 0-f.\n  ~bx      Change background ansi color to anything from 0-f.\n  ~h       Back Space\n  ~q       Change to default ANSI mode.\n  ~f       Clear Screen.\n  ~nx      Newlines where x is the number of them you would like\n  ~~       This indicates you wish the ~ symbol to appear, you can\n           have as many of them as you like after the first ~ to display\n           them (NOTE: no '','' on this command)\n  ~xn      Goto X position on screen. ie: ~x10\n  ~yn      Goto Y position on screen. ie: ~y10\n\n  NOTE: The above commands allow you to specify a width identifier before\n  ~~~~  the action test.. ie:\n        ~10N would only display the first 10 letters of the username.\n\n  MCI - System Specification:\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n  ~SC     System Total calls\n  ~CT     Show current Time\n  ~DT     Show current Date\n\n  MCI - Extra Specification:\n  ~~~~~~~~~~~~~~~~~~~~~~~~~\n\n  ~CR         will wait for any key to be pressed.\n  ~CR_Prompt  will wait for and prompt the user to press any key.\n              ie: ~CR_PressAnyKey\n  ~SP         will do a standard pause, this is useful to put in\n              between each ~SS command.\n\n  ~<xx>SR_<screens>\n              This allows you to have random textfiles by using this\n              MCI Command. <xx> represents the maximal number of\n              random file you want to change. and <screens> is the full\n              path to the textfiles you want to be random displayed.\n              (without .TXT)\n\n  ~SS_Name    Show <name> file. This file may also be an MCI file.\n\n            WARNING: This command could cause a serious loop problem if\n            ~~~~~~~  you tell it to show the same file you are viewing.\n            WARNING: You may need to increase STACK if you nest to many\n            ~~~~~~~  of these files.\n\n            NOTE: If this command is accessed via the message base or the\n            ~~~~  View or ViewSysop commands, then the file you are going\n                  to view has to have a file comment of\n                  ''Allowed'' or ''{xxx}Allowed''\n\n                 {xxx} specifies security level or above ie:\n\n                 {050}Allowed, indicates that only those over or equal to\n                               access level of 50 are allowed to view the\n                               file.\n\n  ~CC_Name    Launch a door ''Name'' is the door''s name.\n              ie: ~CC_WHO will look in SYSCMD, BBSCMD and CONF<x>CMD\n                  directory which must be located in the\n                  BBS:Commands directory.\n\n  ~CL         this command will display a list of conferences,\n              commonly used in the JoinConf.txt file\n\n      *******************************************************************\n      NOTE: ALL MCI COMMANDS MUST END WITH EITHER A SPACE OR A ''|'' SYMBOL\n                     ALL COMMANDS ARE CASE SENSITIVE!!!!!!!!\n      *******************************************************************\n\n      Having a line in a text file that contains:\n      ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n      ~N , I hope everything is going well in ~L .\n\n      Might show:\n      ~~~~~~~~~~\n      Joseph Hodge, I hope everything is going well in Virginia.\n\n=========================================================================\n@endnode\n@node Cap13 "Noteable Features of AmiExpress..."\n=========================================================================\n\n 1. Command history has been added in to allow up to 20 history lines\n    to be remembered.  Once the limit of 20 has been released the\n    history will cycle thru. CTRL-B will reset the history pointer\n    to zero entries.\n\n 2. The HELP key performs a screen to background command\n\n 3. The bbs checks to make sure the AUXx: or CNN: device can be opened\n    and tells the user if there is a problem.\n\n 4. Baud Calling times has been added in, kind of a throw in and will\n    be changed, but for now, specify the time period a baud rate CAN\n    call, like to allow a baud to call all the time enter 0 for start\n    and 2359 for end.  Start time must be a lower number than end time.\n    As I stated this is not perfect and will be removed from the config\n    and a file will contain all the times a baud can''t call.  It will\n    allow more flexiblity.\n\n 5. AREXX port ''AmiExpress_Node.x'', supports the following features:\n\n     suspend - causes the bbs to close the serial port and iconify\n               and wait for a resume command.  If someone is online\n               the bbs will wait util they logoff to reply to the\n               suspend message, and then the bbs will suspend.  This\n               allows you to create a batch file that will automatically\n               suspend the bbs and load your terminal program and once\n               your finished with the terminal program put the bbs\n               back up.\n\n               a example Arexx Program should be like this that the\n               bbs will suspend:\n\n            ------------- cut here ------------------\n               /* The Suspend Command for AmiExpress V3.6 */\n               address ''AmiExpress_Node.1''\n               ''suspend''\n            ------------ cut here -------------------\n\n\n     resume  - this command is only used while the bbs is suspended.\n\n     shutdown - this command will cause the bbs to lower the users\n                time online to 2 mins and tell the user that it has\n                received an emergency shutdown notice.  Once the user\n                is off the bbs exits from memory.\n\n     NOTE: None of these features work without arexx.\n\n    There will be lots of AREXX commands in the future, including\n    node to node chatting..\n\n 6. Automatic zmodem upload, if a user starts a zmodem upload on\n    the main prompt the bbs will detect this and enter the zmodem\n    upload routines.\n\n 7. SYSOP now has the ability to run a node in the background just\n    for his local use.  To do this just remove the device name from\n    the config file and the bbs will not use the serial port.\n\n=========================================================================\n@endnode\n@node Cap14 "Note worthy of Mention...."\n=========================================================================\n\n  I would personally like to thank Mike Thomas, who originally wrote\n  AmiExpress, I still do not know to this day why he choose me to carry\n  on with AmiExpress but I sure am appreciative, It has been a wonderful\n  learning experience in both the programming world and friendships.\n\n  I would personally like to thank Phil Julias for his hard work on his\n  original documentation for AmiExpress 1.(x) series, It has helped\n  considerably in the development of the current documentation.\n\n  I would personally like to thank all of the wonderful people listed on\n  the ACP credits menu. They are great people, and have a lot of patience\n  and enthusiasm in making express the best BBS program around.\n\n  I would also like to thank all the users who have helped guide me in\n  the development of express. It is not to see the devotion that comes\n  from the registered users, more devotion then I ever expected.\n\n  Enjoy the BBS, once setup will assuredly become second nature to run.\n  It is a fantastic program, and we all have Mike Thomas to thank for\n  it''s creation.\n\n        Please report any errors in this file, or any other file to:\n\n                 ----------------------------------------\n                  LightSpeed Technologies (305) 964-4263\n                 ----------------------------------------\n\n                          Or Mail to:\n\n                          Light Speed Technologies\n                          P.O. Box 4435\n                          Hollywood, Fl. 33083\n\n=========================================================================\n@endnode\n@node Cap15 "Trouble Shooting...."\n=========================================================================\n\n  Problem                            Solution\n  --------------------------------   -----------------------------------\n  ACP will not start.                1. Make sure ACP is being run\n                                        from the startup-sequence or WB\n                                     2. Goto an AmigaDos shell, goto the\n                                        directory where the command is\n                                        located and type ACP, this\n                                        should give you an error message\n                                        indicating that perhaps a file is\n                                        missing.\n                                     3. Be sure that you have the ICON in\n                                        the same directory as the Main\n                                        Program\n  Express will not start, but\n  ACP will.                          1. Make sure that if you are using\n                                        a batch file to execute express\n                                        that the batch file has a ''s'' bit\n                                        assigned to it, ie:\n\n                                        PROTECT S:BBS.Startup +s\n                                                ^\n                                                |\n                                                batch filename\n                                      2. Goto the directory in which\n                                         express exists and type from\n                                         a shell:\n\n                                          Express 0\n                                                  ^\n                                                  |___ (node number)\n\n                                         This should tell you why the\n                                         program is not running.\n\n  ACP and EXPRESS run but express      1. The stack size of express is\n  gurus everytime someone enters          not getting set. You must have\n  the msgbase scan.                       a stacksize of 50000 for this\n                                          to work.\n\n  ACP comes up but there is no         1. Make sure the statement:\n  NODE buttons.                           NUMBER_OF_NODES x exists, where\n                                          <x> should be replaced with the\n                                          number of nodes you are going\n                                          to have.\n\n\n  My modems will not initialize        1. Make sure the UNIT statements\n                                          reflect the correct UNIT\n                                          number.\n\n                                       2. Make sure the DEVICE_NAME is\n                                          correct.\n\n                                       3. Make sure you have a\n                                          MODEM_INIT string in the MODEM\n                                          ICON.\n\n  In the Callerslog:                   1. Make sure you started the\n    Error Reading MsgBase Pointer         CONFDB Utility the Right way:\n  is listed                           1> CONFDB BBS:CONF/ <max.Usernumber>\n\n                                       2. Make sure CONF.DB is in each\n                                          conference you have.\n\n                                       3. Make sure that the Usernumber\n                                          you choosed in the creating of\n                                          CONF.DB is not lower than the\n                                          actual one.\n\n=========================================================================\n@endnode\n@node Cap16 "Future planned Enhancements.."\n=========================================================================\n\nByteMaster''s BBS or ''Programmer Fool''s BBS'' is now what is identified as an\n/X InfoNet Repeater, it simply is a relay station for netmail and is\nno longer a BBS.  We are experimenting with various ideas with express to\nallow  more diversity, some of the items coming up in the next few releases\n(or scheduled to) are:\n\n 1. We recently removed all the debugging hooks out of the code. This\n    will in effect speed up the code, and trimmed about 6K off the size.\n\n 2. We have opted to go with registrized parameters vs stack parameters,\n    this in effect saves about 9K of instruction overhead in the program\n    and significantly has increased the overall speed of express.\n\n 3. The MCI interpreter has FINALLY been optimized, and now is practically\n    transparent in operation.\n\n 4. There is currently several bytes of data in the user.data that is\n    not in use do to the fact that msgbase pointers are now stored in the\n    conf.db for each conference, therefore I have opted to use a portion\n    of these so called reserves to record voting booth data per account.\n    This will allow the sysop to have an internal voting booth.\n\n 5. Based on input from the users, (yes we listen) we are currently working\n    on several areas of express.\n\n    1. We are coming out with a new account editor for handling the\n       conference accounting options in express.\n\n    2. Depending on the amount of support of express we intend on investing\n       the time in designing a 1 stop configuration system, to give the\n       sysop the option of using icons or not.\n\n    3. We plan on modifying express to handle infinite nodes.\n\n    4. We plan on hard coding last caller data, which may be displayed and\n       organized in .txt files via MCI commands.\n\n    5. We will be modifying express to allow you to specify a font for the\n       ACP and express.\n\n    6. Re-entrancy is always on our minds when working with express, we\n       are slowly but surely going in that direction, please don''t let the\n       source code of express that was released publicly fool ya, there\n       has been major enhancements to the code since then.\n\n    We will be designing a standardized set of sysop utilities that we\n    believe should be hard coded into express. my prior outlook was to\n    make all enhancements to express external, but I now see the need\n    for some internal features that we rely on externally on a day to day\n    basis.\n\n    So people, hang in there, you will see a lot of enchancements in the\n    next couple of months.\n\n\n=========================================================================\n@endnode\n@node Cap17 "/X Update 3.31 (c)1992-1994 LightSpeed Technologies Inc."\n               .: U P D A T E  D O C U M E N T A T I O N :.\n\n             The following is a list of changes to version 3.31\n             of AmiExpress.\n                     @{" MultiComm Port               " Link Update01}\n                     @{" Program Execution            " Link Update02}\n                     @{" MCI Commands                 " Link Update03}\n                     @{" Internal Zmodem Protocol     " Link Update04}\n                     @{" XPR Protocols                " Link Update05}\n                     @{" Custom Commands              " Link Update06}\n                     @{" Message Base                 " Link Update07}\n                     @{" AmiXnet Updates              " Link Update08}\n                     @{" 3.34 Updates                 " Link Update09}\n                     @{" 3.35 Updates                 " Link Update10}\n                  ------------------------------------  \n  \n  Documentation written by: \n  Joseph Hodge\n  LightSpeed Technologies Developement\n\n  Copyright (c) 1994 LightSpeed Technologies Inc.  All Rights Reserved.\n  Any copy or illegal distribution of this Documentation is prohibited.\n\n@endnode\n@node Update01 "MultiComm Port"\n  =======================================================================\n  Following is a list of changes to the MultiComm Port\n\n  Since version 3.30 of AmiExpress we have increased the Maximum Number\n  of Nodes that ACP can handle. ACP can now handle a maximum of 32 Nodes.\n\n  This change involved changing the internal MultiComm structure to handle\n  32 nodes vs 9 nodes. This change means that the old NewChat and some of\n  the older Online Message Send Modules may not work any longer. We have\n  released an update to the NewChat door so that it will handle the 32\n  node configuration.\n\n@endnode\n@node Update02 "Program Execution"\n  =======================================================================\n  \n  Since version 3.30 of AmiExpress you now have the ability to make\n  AmiExpress resident. Doing this should speed up program execution\n  and also conserve memory. \n\n  Making AmiExpress resident:\n\n  1. change all nodestart tooltypes in the NODE icons to reflect the\n     following:\n     \n     NODESTART=express\n \n  2. Update your s:user-startup script by adding the following after\n     your BBS Assignment:\n\n     RESIDENT EXPRESS BBS:EXPRESS\n\n\n@endnode\n@node Update03 "MCI Commands"\n  =======================================================================\n  Following is a list of changes to the MCI Commands\n\n  I have modified the ~CC command to allow the execution of MENU PROMPT\n  commands. This will allow you to run the internal WHO command from any\n  MCI text. Simply add this MCI command to your MCI Text File:\n\n  ~CC_WHO\n\n  NOTE: It is important to realise that most MENU COMMANDS should only\n        be run from the MENU PROMPT. For Instance , forcing the READING\n        of mail at the FRONTEND of express would not be wise because the\n        BBS does not know who is logging onto the system. So use your\n        own judgement on these matters. \n\n@endnode\n@node Update04 "Internal Zmodem Protocol"\n  ===========================================================================\n  Following is a list of changes to the Internal Zmodem Protocol \n\n  I added the tooltype ''HDTRANSBUFFER'', this tooltype is for the node icons.\n\n  HDTRANSBUFFER allows you to change the buffer size from serial to harddisk.\n  This option is a better alternative than using a RAMPEN because it works\n  on a file by file basis, whereas the RAMPEN method has to wait until all\n  uploads are complete.\n\n  HDTRANSBUFFER has the following syntax:\n\n  HDTRANSBUFFER=<buffers>\n\n      You may specifiy as many buffers as you like. The number of buffers\n      default to 8 if this tooltype is not used. Here is a formula for\n      determining how much memory will be allocated for transfers when the\n      node is started:\n\n      ((buffers+2)*1024)*2\n                         ^----- This is required due to the double buffering.\n\n      ie:\n \n      HDTRANSBUFFER=20 would require 45,056 bytes of memory\n\n      1. ((20+2)*1024)*2\n      2. (22*1024)*2\n      3. (22528)*2\n      4. 45056\n\n    Version 3.30 a bug was introduced with this HDTRANSBUFFER addition.\n  AmiExpress was not freeing the memory it allocated for the buffers. This\n  is the primary reason for releasing this version.\n\n@endnode\n@node Update05 "XPR Protocols"\n  =======================================================================\n  Following is a list of changes to the XPR Protocols Interface:\n\n  We have temporarily removed the XPR interface and placed it in a SYSCMD.\n  We will most likely put this back into AmiExpress in a month or so. \n\n  One of the important changes to AmiExpress besides this is now all batch\n  Protocol Icons must contain the tooltype AE_BATCH instead of BATCH.\n\n@endnode\n@node Update06 "Custom Commands"\n  =======================================================================\n  \n  I added the tooltype ''QUICKMODE'' for the module icons. This tooltype\n  simply tells AmiExpress not to run the Module in question if the user\n  has logged onto the sysop using the QUICK logon option.\n\n@endnode\n@node Update07 "Message Base"\n  =======================================================================\n  \n  Since Version 3.30 the message base has been modified to re-display\n  the original message if a reply to a message was aborted.\n\n@endnode\n@node Update08 "AmiXnet Updates"\n  =======================================================================\n  \n  Due to the expansion of the Net, including more sales and increased\n  volume of mail, we realized the need for a more optimized method of\n  packing netmail. AmiXnet currently recalculates the MailRoute for\n  every net mail conference when it is packing mail and unpacking mail.\n  This in itself is not efficient. Therefore I modified all of the NETMAIL\n  utilities to recognize pre computed mailroutes, this greatly speeds up\n  the mail packing process for those with only one Node Id.\n\n  In order to invoke the optimized method of packing mail you will need to\n  do the following:\n\n  1. Modify the scripts that run MRUPDATE with an additional commandline\n     option ''AUTOUPDATE''. AUTOUPDATE should be the last commandline option\n     to MRUPDATE. This will force MRUPDATE to create pre-calculated \n     mailroutes when new maps come down the net.\n\n  2. Create a directory in BBS:AmiXnet named your node id. For instance I\n     have a directory called:\n\n     BBS:AmiXnet/703001 because 703001 is my nodeid.\n\n  Once you have done the above, the next time mail is packed the netutils\n  will create pre-computed route files and place them into the newly \n  created directory.\n\n  NOTE: ONLY DO THIS IF YOU HAVE ONLY 1 NODE ID. THERE IS A COUPLE OF\n        BBSs WITH MULTIPLE NODE IDS, THIS OPTION WILL NOT WORK FOR THEM\n        AT THE MOMENT. I HOPE IN THE NEAR FUTURE I WILL HAVE THIS SOLVED.\n\n\n  \n@endnode\n@node Update09 "3.34 Updates"\n  =======================================================================\n02/13/93\n\nREVISIONS FOR /Xpress 3.34\n\n    First of all I think all of you guys, should tip your hat off to\n    Joe this month for all the extra work he has done for this release.\n    he has been putting in all his days and nights over the last few\n    weekends to make all these changes. THANKS JOE.\n\n    Personally I am very excited about the changes that are being incorp-\n    orated into express and a lot more coming. Ok now for the changes:\n\n\nThere is a new command called ''CF''. This command will allow your users\nto set the way express handles conferences. from here they can set the\n''new file scan'', ''new message scan'', and turn ''OFF'' and ''ON'' what conferences\nthey want to ZOOM mail from.\nIn the Conference Maintainance option in the Account editor you can also\nGlobaly set these options.\n\n\nThe second biggest feature is that /X now has ''MESSAGE QUE'' capabilty for\nmultinode chat. Remember when you would chat someone on another node, and\nthey were busy doing something, and they would never get the message, well\nnow when the user is done, they will receive the mesaage you sent them.\nThere is a new ''NEWCHAT'' door online to grab, that uses this new capability.\n\nNew options in the conf icons for you sysops:\n\nFORCE_NEWSCAN\n\n    This will force your users to have a New Mail scan whether they\n    have selected it or not.\n\nNO_NEWSCAN\n\n   This will Force No New Mail scan whether a uers has turned it off or\n   not.\n\nSHOW_NEW_FILES\n\n    This is not a new command, but if used in the conf icon, will act\n    like the above force command for messages\n    IE:Force your users to get a new file scan whether they have chosen\n       it or not.\n\nIn the ''W'' option for users, is now the ability for the user to pick what\nkind of Zoom they want. They can pick QWK, or the old ascii zoom option.\n\n\n    Another new option is for your commands Dir. You can now make an icon\n    called ''NODE#CMD'' This is used like your CONF#CMD Option. Now your node\n    can use it as well.\n\nIn this version there was also a BUG FID in the doors icons. PRIORITY=\nhas now been fixed. If you use PRIORITY=SAME, it will use the same Priority\nthat express uses.\n\nWell I think that is all. If I have forgotten to tell you everything I will\nleave a message. Wow what a month. Ok enjoy the new express. Included in\narchieve, is also the icons needed to put in your zoom dir. For those of\nyou useing utilities that delete everything in your Zoom dir, I advise\nyou to stop useing them. It will delete these icons needed. Ok that''s it\nfor now.\n\nLIGHTSPEED TECHNOLOGIES INC.\n\n@endnode\n@node Update10 "3.35 Updates"\n  =======================================================================\n\n02/14/93\n\nVERSION 3.35\n\n  Added a new tooltype For Access\n\nACS.CONFFLAGS\n\n  this tooltype allows the CF command to work.\n\n@endnode\n','\n',char(10)),'{"PRIORITY":"<num>","STACK":"<stack>","LOCATION":"<dir>-","ACCESS":"<num>","TYPE":"-"}',NULL,333859,38,0,NULL,NULL,'stn_a335_amixnetbase','scan',1780048759);
INSERT INTO door_catalog VALUES('stopcps','STOPCPS.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/STOPCPS.LHA',NULL,'XIM','STopCPS_v1.06',NULL,NULL,NULL,NULL,replace('TOP CPS\n','\n',char(10)),'STOPCPS_V1.06.DOC',replace('Compared to the wholescale  violence  of  capital and government,  political\nacts of violence are but a  drop in the  ocean...  High strung like a violin\nstring, [the anarchists] weep and moan for life, so relentless, so cruel, so\nterribly inhuman. In a desperate moment the string breaks. Emma Goldman,1910\n\nSuper-TopCPS - Top CPS Recorder for /X - Docs, Code, Output ©1993 P0T-NOoDLE\n============================================================================\nFeatures:	Does NOT lose CPS Records when you cut your CallersLog!\n		MultiNode Compatable (And of course single node too).\n		FAST & SMALL 680x0 Assembler Coding! (AND I MEAN FAST!)\n		Beautiful & Informative Output! Look at Example output.\n		Upto a Top-20 with UserName,BaudRate,Filename,CPS-Speed...\n		Pure, re-entrant code (resident-able).\n		Gunna format your harddrive (NOT).\n\nMini-Index\n==========------------------------------------------------------------------\n	1	Command Line\n	2	Command: D-ocs\n	3	Command: C-Lear\n	4	Command: U-pdate\n	5	Command: O-utput\n	6	Command Stacking\n	7	Note: CPS Rates in Storage File\n	8	Thanx & Mini-Greetings\n	9	Slagging off for this util\n	10	BBS Numbers for Contact/BugReports/Etc\n	11	Program Release History\n	12	BOLLOX\n\n\n\nCOMMAND LINE\n============----------------------------------------------------------------\n	Super-TopCPS  has a very  flexible command line.  You may have it do\nmany operations in just one run by using command stacking (See below).  Each\ncommand is always preceeded with a "-", eg "-C" is command "C".  Most of the\ncommands also have extra options and requirements.\n	Output filenames may NOT contain either "-" or "ÿ".\n	Output filenames are converted to uppercase, not that it matters.\n	Entering an Output filename of "*" will output to your CLI window.\n\n	While reading the  docs on  each command,  I advise that you also be\nlooking at the CommandLine help text for the Command templates. (Now there''s\nsomething you can''t do on a fucking PC (or a toy(games console!))).\n\n\n\nCommand D-ocs\n=============---------------------------------------------------------------\n	This command creates this doc file by uncrunching it from the Super-\nTopCPS code and outputing it to the specified filename.  The  example  would\noutput the docs to `RAM:STC.DOC''\n\nSTopCPS -D"RAM:STC.DOC"\n\n	By the way,  this is done so that  the util is never spread  without\nit''s docs,  and so there is never the age old question of  HOW THE FUCK DOES\nTHIS WORK  when  you''re  setting up  a board  from  someone''s  HD-Backup  or\nwhatever.  It does not  slow down  the program  at all,  and as the docs are\ncrunched,  memory loss is hella-small  (You''d lose  three times as much just\nby using a shitty C program instead of STC!).\n\n\n\nCommand C-lear\n==============--------------------------------------------------------------\n	This will create a new and blank storage file  if it does not exist,\nor blank the already  existing  storage file.  A storage file  must  be made\nbefore Commands U and O will work.\n	The storage file is called `S:STopCPS.Store''  and is where STC keeps\nall its information about the fastest 20 uploads and downloads.\n\nExample: STopCPS -C\n\n\n\nCommand U-pdate\n===============-------------------------------------------------------------\n	This will check the  last caller  to your board for any  uploads  or\ndownloads  which were  fast enough to get them into your Top-20.  If any are\nfound, they will be added into the Storage file.\n	You must run this Command everytime someone logs off a node.\n	U-pdate  requires  the node number  which you wish  to update (0-9).\nExample1  would be used  after a user  has just  logged off Node0.  Example2\nwould be used after a user has just logged off Node1.\n\nExample1: STopCPS -U"0"\nExample2: STopCPS -U"1"\n\n	Note that  you can  use one logoff  script for all of your  nodes by\nputting  `.k node''  at the start of your logoff script, and having  `<NODE>''\nin place of the node number. See the included example logoff script.\n\n	NOTE: Due to the way that  STC  looks for the Baud Rates you have to\nhave your HST set to output FULL connect strings,  like any non-idiot would.\n(eg "CONNECT 9600/ARQ/HST/HST/V42BIS" NOT "CONNECT 9600")\n\n\n\nCommand O-utput\n===============-------------------------------------------------------------\n	This command outputs a list of all time fastest transfers, using the\ninfo in the storage file.  You must give it an output path and the number of\nusers you wish to be displayed (0-20).\n	Example1 will output the top 10 users to `RAM:TEST_BULL''.\n	Example2 will output the top 20 users to `BBS:NODE0/BULL100.TXT.GR''\n\nExample1: STopCPS -O"RAM:TEST_BULL"10\nExample2: STopCPS -O"BBS:NODE0/BULL100.TXT.GR"15\n\n                                             O-utput - Header & Tailer texts\n---------------------------------------------===============================\n	If  `S:STopCPS.Header.txt(.gr)''  exists, it will be added to the top\nof the output, and if  `S:STopCPS.Tailer.txt(.gr)''  exists, it will be added\nto the end of the output.  The ".gr" is dependant on  Option N being On/Off.\n\n                                                  O-utput - Option N: NoANSI\n--------------------------------------------------==========================\n	This option removes all ANSI codes from the text and slightly alters\nthe output so that it will look better without the ANSI. It will replace the\n"|"''s in the header line with "-"''s etc.\n	This option also effects what Header/Tailer text is used (See above)\n	The Example  will output  the top 20 speeds to  `RAM:BULL'' ,  with a\nNoANSI output, and add `S:STopCPS.Header.TXT'' &/or `S:STopCPS.Tailer.TXT'' if\neither/both exist.\n\nExample: STopCPS -ON"RAM:BULL"20\n\n                                     O-utput - Option U: UpperCase Filenames\n-------------------------------------=======================================\n	This option converts all the filename texts in the output into upper\ncase.  In my opinion it looks  better this way,  but some people may wish to\nhave the filenames left as they were originally.\n	The Example will output the top 5 speeds to  `T:FISHFINGER''  with an\nANSI output,  and filenames in UpperCase, adding `S:STopCPS.Header.TXT'' &/or\n`S:STopCPS.Tailer.TXT'' if either/both exist.\n\nExample: STopCPS -OU"T:FISHFINGER"5\n\n                                           O-utput - Option T: Text Dissable\n-------------------------------------------=================================\n	This option simply ignores and does not use the Header/Tailer texts\nin S:. Simple.\n	The Example will output the top 3 speeds to `RAM:ERP'' without ANSI,\nand with Uppercase filenames, and will NOT add any Head or Tail texts, even\nif they do exist.\n\nExample: STopCPS -ONUT"RAM:ERP"3\n\n\n\nCommand Stacking\n================------------------------------------------------------------\n	A user has just logged off node 1. You his/her transfers checked and\nadded to the store file if needed,  and you also want to update the ANSI and\nnon-ANSI TopCPS lists in the Amiga conf bulletins directory. No problem:\n\nSTopCPS -U"1" -O"BBS:Ami/Bulls/Bull1.TXT.GR" -ON"BBS:Ami/Bulls/Bull1.TXT"\n\n	Should be pretty clear to the non-stupid among you.\n\n\n\nNote\n====------------------------------------------------------------------------\n	The  CPS  rates in the  Storage  file are  checked  for tempering by\ncheating sysops. So don''t change them, and also, don''t touch my name!\n\n\n\nTHANX\n=====-----------------------------------------------------------------------\n	They all know who they are and why there are here,  but for the rest\nof you, I must thank the following people, without whom STopCPS would not be\nwhat it is.\n\nSquiz                 - Who wrote a TopCPS  Util in Basic for me a long time\n                      - ago (obviously before he left the scene!) from which\n                      - I''ve borrowed ideas,some of which were mine to start\n                      - with.\nThrash   of   Anthrox - Technical Assistance and Disk Drives!\nFay of the real world - <Insert musshy B.S. which has all been said before!>\nBluelight             - Quick Bug Reporting & Sending Logs/Outputs with it!\n\nMy other friends & group members in the scene.\nMy other friends & family outside of the scene.\n\nAnd, In No Duck-Fucking-Order... Oranges,Bananas,Fish Fingers,Beef Curtains,\nYour Mum,Pepsi,Pizza,Metallica,Megadeth-?,Anthrax,Slayer,C.O.C,Ugly Kid Joe,\nFaith No More,Nine-Inch Nails,D.R.I,Exodus,MortalSin,OverKill,Paradox,Toxik,\nFlotsam and Jetsam,Lawnmower Deth,Testament,Xentrix,Venom,Re-Animator,S.O.D,\nNuclear Assault,Guns''n''Roses,Possessed,Skid Row,Onslaught,MorotHead,Pantera,\nand people who talk like this: "swark swark swark swark" That''s you that is.\n\nFUCK THE REST OF THE WORLD\n\n\n\nP0T''S NOTE FOR THIS UTIL:\n=========================---------------------------------------------------\n	Aimed at people who make and use Archive-BBSAd-Adders that strip the\nother adds.  You idiots  are so fucking hypocritical.  If you dissagree with\nBBS Ads that''s fine, strip them all. BUT, if you strip and then add your own\nBBS Ad, you are  STUPID!  Think about this. If we all did this, when someone\ndownloads a file from a BBS, they simply get the add from that BBS.  I don''t\nthink that anyone''s users need to be asked to call a board that they already\ncall??  Or, do you think that you''re Board is so special that it should have\nit''s ad and  noone else''s in the file!?  Or is your Board so  shit  that you\nwanna remove other adds so that it looks like it got the file first??\n	Whatever the reason,  if you strip AND add,  you''re a stupid,  lame,\nno-thinking,  idiotic person,  and you will probably end up raping your  own\nchildren after your sex-partner gets a pair of glasses.\n\n	Also,  stupid  assholes  who strip the  front text from DMS files or\n"*.displayme" from LHAs are extra-extra-STUPID! These texts may (or may not)\ncontain important information about the archive they are in.  Nearly all the\nutilities  indiscriminately  delete these files,  whether they are important\ninfo or just another BBS-Ad.\n	While I''m on the subject, DMS-Boot-Block adds are a nice idea, pitty\nthat the util-makers didn''t fucking think. What if it''s a fix or part b of a\ndisk or whatever? Not all,but some of the Boot-Block adders don''t check that\nthe DMS file will actually write the  correct bootblock  after the Add-Block\nhas been written. EG: If it''s a fix that  doesn''t change  the bootblock, the\nfix is written and the  propper bootblock  of the disk has a  BBS-Ad written\nall over it,  thus totally screwing up the disk and getting someone a little\nbit pissed off! IT''S STUPID! DON''T DO IT!\n\n                     To the person who did that little "Ultimate Util" Joke:\n---------------------=======================================================\nHAHAHA You make me laugh man! I don''t know whether to be mad at you or what?\nWell, I take it as a joke, a fucking wierd one! Nice try, YOU MUTHERFUCKER!!\n\n\n\nContact\n=======---------------------------------------------------------------------\n	If you can call England, drop me a message on...\n<./\.|    (Anthrox UKHQ) +44-813466842 Sysop:P0T-NOoDLE\n	Or if you can''t, call...\nMartyrium (Anthrox USHQ) +713-460-8217 Sysop:Wintermute (5 nodes-Ringdown)\n\n	Contact me if you have any bug reports or ideas on any of our utils,\nor if you have a cool idea for a new util that you want written.\n\n\n\nHistory\n=======---------------------------------------------------------------------\nVersion - Release Number -------------------------------------- Release Date\nv1.00 ===-[01]-================================================ 2nd Jan 1993\n	Initial Release.\nv1.05 ===-[02]-=============================================== 16th Jan 1993\n	BUG FIX: If someone leeched and got a TopCPS, and the next caller\n	         did not upload at all, he would get the same speed/filename\n	         or he would get a wierd username. (I''m Hella-Stupid!)\n	O-utput and C-lear routines almost completely re-written.\n	Information output to CLI about operations performed.\n	New O-utput Oution: T - Dissables header/tailer texts.\nv1.06 ===-[03]-=============================================== 18th Jan 1993\n	BUG FIX: Root-Dir Download paths do not mess up filenames anymore.\n============================================================================\n	About this release, in detail:\nWhen working out the name of downloaded  files from the callerslog, the util\npreviously searched for "/" and would take the word after it,  assuming that\nall files would be  downloaded  from  a  directory  and not a root-dir or an\nassign (such as "Dh1:" or "FILES:". This was stupid, I know! Now it searches\nfor a "/" OR a ":" and should work fine!\n	Thanx (or no thanx!)  to  Bluelight  for once again finding this bug\nin record time (how long was it,  3 hours since release?) and sending me the\ncallerslog so that I could discover the obvious and stupid mistake I''d made!\n============================================================================\n','\n',char(10)),NULL,'auto-added',17169,1,0,NULL,NULL,'stopcps','scan',1780048759);
INSERT INTO door_catalog VALUES('stracker','STRACKER.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/STRACKER.LHA','StoneTracker','XIM','StoneTracker',NULL,NULL,NULL,'// __/. __/. __/ _ _). __/_. _) / / ¬Y / \__ ¬\  __)  \__ _ ¬\  __)// : .\/\__  \ /____/____)____/_|__/____)\__|____/____/',replace(' ________________________________  __ __\n// __/. __/. __/ _ _). __/_. _) / / ¬Y /\n\__ ¬\  __)  \__ _ ¬\  __)// : .\/\__  \\n/____/____)____/_|__/____)\__|____/____/\n-=S=e=c=r=e=t=l=y=-==-=p=r=e=s=e=n=t=s=-\n=->     StoneTracker v1.25 Demo      <-=\n-[ The best 8channel-protracker clone ]-\n=[ever seen! OS-friendly, multitask...]=\n-=-=-=-=-=-=-=-=-=-==-=-=-=-=-=-=-=-=-=-\n\n','\n',char(10)),'StoneTrackerDemo.Guide',replace('@database StoneTracker.Guide\n@author "Emmanuel MARTY & Michael LAVAIRE"\n@(c) "Copyright © 1995 E.MARTY & M.LAVAIRE"\n@$VER: StoneTrackerDemo.Guide 39.7 (27 sep 95)\n@index Main\n@toc Main\n@help Main\n\n@node Main "StoneTracker V1.25"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n			  Copyright © 1995\n		  Emmanuel MARTY & Michael LAVAIRE\n\n\n\n  @{"Introduction             " link Intro}  Introduction au StoneTracker\n  @{"Nouveautés               " link News}  Pour les utilisateurs de la 1.22\n  @{"Installation             " link Install}  Installation sur votre disque dur\n  @{"Mentions légales         " link Disclaimer}  Notes légales importantes\n  @{"Configuration matérielle " link Config}  Configuration nécessaire\n  @{"Auteurs & Editeur        " link Auth}  A propos des auteurs et de l''éditeur\n  @{"A propos de D-Stroy...   " link DStroy}  Pour faire baisser votre productivité\n  @{"Remerciements            " link Thanks}  A ceux qui nous ont aidé\n\n  @{"Principes de base        " link Basics}  Principes de base des trackers\n  @{"Particularités du Stone  " link Specs}  Ce qui rend StoneTracker différent\n  @{"Utilisation du Stone     " link Use}  Utilisation pratique du StoneTracker\n  @{"AREXX                    " link AREXX}  Le port AREXX de StoneTracker\n  @{"Développeurs             " link Devel}  Documentations pour les développeurs\n  @{"Programmes externes      " link Externals}  Programmes fournis avec StoneTracker\n  @{"Annexe                   " link Appendix}  Accès rapide aux parties importantes\n\n@endnode\n\n@node Intro "Introduction"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nBienvenue à bord de la distribution électronique de la version de\ndémonstration de StoneTracker.\n\nStoneTracker est un utilitaire permettant de créer des musiques, pour votre\nplaisir personnel ou pour une utilisation dans une application. Supposant\nune connaissance de l''utilisation de l''Amiga et de la musique en général,\ncette documentation couvre les concepts de base de la composition sur\ntracker, l''utilisation pratique du programme et l''intégration de musique\ndans les applications personnelles.\n\nPour obtenir la qualité désirée, il faut savoir que les auteurs ont travaillé\npendant un an et demi sur ce logiciel.\n\nStoneTracker représente :\n	- 1 an et demi de travail parsemé d''examens\n	- 1210 Ko de source entièrement en assembleur\n	- Un A1200 et un A4030 grillés\n	- 600 litres de Coca-Cola\n	- Une dizaine de désaccords\n\nSes principales caractéristiques sont :\n\n        - "System friendly" (respecte les règles de programmation sous\n          système) : look système 2.0 (avec notre touche personnelle, bien\n          entendu), pas de hit enforcer, s''installe en tant que commodité,\n          AppIcon, AppMenuItem... Alloue les canaux audio, possibilité de\n          les désallouer sans quitter le programme. Compatible avec les\n          écrans VGA/Multisync, etc. Tire le meilleur parti des ressources\n          de l''Amiga et vous place dans un environnement sécurisé.\n\n        - Support Locale, en Anglais et Français pour l''instant; Allemand\n          prévu. Tout traducteur est le bienvenu!\n\n        - Interface utilisateur ergonomique, de type "tout à l''écran",\n          étudiée avec un musicien sur tracker. Sécurisée contre les\n          opérations involontaires...\n\n	- Port AREXX complet\n\n        - Extrèmement configurable.\n\n        - Emulation des raccourcis clavier Noise/ProTracker.\n\n        - Format de module propre, permet la compression des banques\n          d''instruments avec trois méthodes différentes et dédiées à ce\n          type de données.\n\n        - Import de 13 formats existants (par exemple, ProTracker,\n          FastTracker, OctaMed, Oktalyzer, ThePlayer, Art of Noise...)\n\n        - Export du format ProTracker et FastTracker, en plus de son\n          propre format (indisponible sur cette version de démonstration).\n\n        - Gestion des compresseurs XPK. Mots de passe gérés.\n\n        - Gestion des compresseurs XFD, permettant la décompression de plus\n          de 100 compresseurs, dont CrunchMania, StoneCracker...\n\n        - Décompresseurs intégrés pour PowerPacker et CrunchMania (si XFD\n          n''est pas disponible).\n\n        - Multi-song (65.535 sont possibles) ! Commandes de synchronisation\n          de songs disponibles, pour créer des musiques interactives.\n\n        - Jusqu''à 65.535 patterns!, partagées entre les songs.\n\n	- Patterns séparées pour chaque voix, permettant par exemple de\n	  réutiliser un rythme de batterie ou une ligne de basse d''une\n	  position à une autre !\n	  Commande pour "éliminer" les patterns en double provenant des\n	  formats qui n''ont pas cette possibilité (ex. ProTracker), ce\n	  qui gagne beaucoup de mémoire !\n\n	- Jusqu''à 255 samples! Peuvent être chargés en mémoire FAST :\n	  pas de limitation de taille si ce n''est la taille de votre\n	  mémoire fast.\n\n	- 4 canaux ("d''origine") ou 5,6,7,8 voix, chaque mode ayant une\n	  qualité de mixage réglable, de 4 à 50 Khz (28 Khz sur les\n	  écrans PAL/NTSC "de base"). Tous les effets peuvent être\n	  utilisés dans tous les modes, pas de restrictions! La\n	  technique du mixage tient plus de TFMX que d''OctaMed ou\n	  ArtOfNoise par exemple, ce qui conduit à une grande qualité\n	  sonore. Chaque song peut avoir son propre nombre de voix,\n	  et vous pouvez sauter, par exemple, d''une song en 4 voix\n	  à une en 7 sans entendre le moindre craquement !\n\n	- Chaque voix possède son propre volume. La musique possède un\n	  volume général. Par-dessus ces deux volumes réglables par le\n	  musicien, il existe un volume "maître" contrôlé par le\n          programmeur.\n\n        - Jusqu''à SEPT effets par note par voix !\n\n        - Voix "FX" spéciale avec jusqu''à HUIT effets par ligne, dédiée\n	  au commandes de changement de vitesse et de contrôle général\n          de la musique.\n\n        - Effets étendus!\n\n	- Effet utilisé pour synchroniser votre programme sur la musique\n	  (appelle une fonction utilisateur lorsqu''il est rencontré).\n	  Idéal pour les intros de jeu, les démos, etc.\n\n	- Commande pour MIXER une position sous forme de sample ! Pour faire\n	  vos arpèges, vos batteries sur une seule voix, etc.\n\n	- Commande pour calculer le temps pris pour jouer une song; il n''est\n	  désormais plus nécessaire de jouer la song en entier pour connaitre\n	  le temps qu''elle prend.\n\n        - Routines de replay et de mixage extrèmement optimisées.\n\n        - Le player est une library partagée, utilisée même par l''éditeur !\n\n        - Documentation AmigaGuide en Anglais et Français (Allemand prévu).\n\n	- Sympathiques musiques d''exemple de 4 à 8 voix, composées par Jerôme\n	  Angelot, qui nous a également aidés à concevoir le tracker\n\n        - Script Installer pour l''installation sur disque dur fourni.\n\n	- Documentation développeur complète sur le player et le format de\n	  fichier, avec des exemples en Assembleur et en C, bibliothèque\n	  linkable pour le SAS; vous pouvez utiliser la library ou inclure\n	  le player dans vos programmes (versions "sous système" et "pas\n	  de système d''exploitation" (pour jeux et démos) fournies)\n          (indisponible sur cette version de démonstration).\n\n        - Players pour DeliTracker et EaglePlayer, et player indépendant\n          (indisponible sur cette version de démonstration).\n\n	- Editeur, player et compresseurs entièrement programmés en\n          Assembleur.\n\n	- Support constant. La plupart des demandes des utilisateurs ont été\n	  satisfaites jusqu''à présent, et nous continuerons ainsi.\n@endnode\n\n@node News "Nouveautés"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}Editeur : @{ub}\n\n   [] Utilisation de @{"XPK" link XPK} pour décompresser les modules, lors du chargement et\n      de la jonction. Mots de passe gérés. Il est donc enfin possible de\n      charger des modules ''squashés'' !\n\n   [] Utilisation de @{"XFD" link XFD} pour décompresser les modules, lors du chargement et\n      de la jonction. Mots de passe gérés. Les fichiers compressés avec\n      par exemple StoneCracker ou Imploder peuvent donc être chargés.\n\n   [] Ajouté chargeur ThePlayer 4.1A.\n\n   [] Ajouté chargeur Art Of Noise 4 et 8 voix.\n\n   [] Routine d''affichage des patterns réécrites, plus propres et plus\n      rapides.\n\n   [] Amélioré compatibilité future avec la library StonePlayer.\n\n   [] Bugs corrigés :\n      - désactivé bouton "Mix" lorsque le sample 0 est actif :)\n      - lors d''une insertion de song la position courante est ramenée à la\n        première position\n      - réparé chargeur ThePlayer 6.x (les samples compressés en Fibonacci\n        n''étaient plus décompressés)\n      - désormais, les soulignés (indiquant la présence d''effets avant ou\n        après l''effet actuel) sur la voix FX marchent !\n      - évité plantage possible après un ''Réorg''\n      - gadget ''BPM'' rafraichi seulement lorsque c''est nécessaire (il ne\n        l''est plus lorsqu''une commande @{"0Fxx" link "Set Speed"} qui change la temporisation\n        mais pas le BPM est exécutée)\n      - ajouté gestion des paramètres de l''AppMenuItem : il est maintenant\n        possible de sélectionner une ou des icône(s) de module(s) et de\n        sélectionner "StoneTracker" dans les menus du Workbench pour obtenir\n        les mêmes actions qu''en lâchant ces icônes sur l''AppIcon. Merci Brice!\n      - lorsque l''écran du tracker est caché et que l''on lâche un ou des\n        modules sur l''AppIcon où qu''on les sélectionne et qu''on sélectionne\n        "StoneTracker" dans les menus, ca ne bloque plus le système...\n        Merci Brice ;)\n      - le tracker plantait en chargeant certains modules ThePlayer 6.1A sans\n        identificateur, les prenant pour des modules 5.0A ou 6.0A, quasiment\n        identiques mais avec un système de compression totalement différent :\n        amélioré routine de différenciation qui conduit à un chargement\n        correct de ces modules. ajouté également sécurité qui en cas de\n        détection incorrecte du format chargerait un module incohérent mais\n        sans planter.\n      - lorsqu''on clique à la souris dans les patterns et que le curseur\n        change de ligne, le slider de droite est maintenant déplacé.\n      - lorsqu''on désactive le tracker (@{"Désactiv" link InterInactive}) et qu''on essaie de lancer\n        une deuxième fois le programme, ça ne plante plus.\n      - lorsqu''on est dans l''éditeur de @{"config" link InterConfig} et qu''on essaie de lancer une\n        deuxième fois le programme, ça ne plante plus.\n\n@{b}StonePacker library : @{ub}\n\n   Créée avec la version 1.25. Cette library contient les routines de\n   compression et de décompression de banque de samples StoneTracker.\n   Jusqu''à présent, ces routines étaient présentes à la fois dans\n   l''éditeur, dans PlayStone, dans DeliStone et dans EagleStone, ce\n   qui était idiot. Mieux vaut partager ce qui peut l''être ! D''autant\n   plus que cette library élimine certains problèmes de décompression\n   qui subsistaient inexplicablement dans ces players externes.\n\n@{b}PlayStone, DeliStone, EagleStone : @{ub}\n\n   Utilisent la nouvelle library ''stonepacker.library'' : plus de problèmes de\n   décompression. Mémoire nécessaire moins importante.\n\n@{b}Player (StonePlayer library et players binaires) : @{ub}\n\n   [] La gestion de l''interruption Soft utilisée par le player binaire\n      "hard" (sans système d''exploitation) est maintenant transparente.\n\n   [] La fin de la song n''était pas détectée dans les players binaires\n      lorsque la fin de la dernière position était atteinte. Réparé.\n\n   [] La commande @{"09xx" link "Sample Offset"} (Sample Offset) joue désormais la boucle du\n      sample quand offset>longueur du sample, pour la compatibilité avec\n      certains modules ProTracker tordus (Merci Loïc)\n\n   [] Les commandes @{"0Dxx" link "Break Position"} (Break Position) et @{"0Bxx" link "Position Jump"} (Position jump) ont\n      été débuggées et fonctionnent notamment maintenant avec des\n      modules ProTracker dinguissimes (Merci Loïc)\n@endnode\n\n@node XPK "Gestion des compresseurs XPK"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nXPK est un standard de compression de fichiers mis au point par Urban Dominik\nMueller et reconnu aujourd''hui par la majorité des programmes. En gros, ce\nstandard permet aux programmes le reconnaissant qui auraient des données\nà compresser, de ne pas s''occuper directement de la compression mais de\ndéléguer cette tâche à une entité externe, un compresseur XPK. L''avantage\npour le programmeur est qu''il est allégé du travail d''écriture d''un\ncompresseur, et pour l''utilisateur qu''il peut utiliser de nouveaux\ncompresseurs XPK qui apparaissent avec le programme qui le reconnait, sans\nmise à jour de celui-ci.\n\nActuellement, de nombreux musiciens semblent compresser leurs modules\nProTracker à l''aide de ce système et il nous a été régulièrement demandé de\nl''intégrer à StoneTracker pour ainsi pouvoir les charger; c''est chose faite.\nLors du chargement ou de la jonction d''un module, si XPK est installé\ndans votre système, il sera automatiquement utilisé pour charger et\ndécompresser le module, à condition que celui-ci utilise le format standard\nde fichiers XPK (utilisé par exemple par XFH, mais pas par DiskExpander).\nUn indicateur de progression du chargement a été installé pour les\ncompresseurs particulièrements lents à la détente (ex. xpkSHRI). Si un mot\nde passe est nécessaire, il vous le sera demandé.\n\nIl n''est pas possible de distribuer entièrement XPK avec StoneTracker pour\nune question de place et de droits, et pour respecter les voeux des auteurs\nnous nous refusons à le distribuer partiellement. Si vous ne l''avez dêja\nà votre disposition, ce standard est relativement facile à trouver, comme\npar exemple sur le site Aminet, dans le répertoire util/pack.\n@endnode\n\n@node XFD "Gestion de la library de décompression XFD"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nXFD est un standard de décompression de fichiers mis au point par Georg\nHörmann. Il s''agit d''un ensemble de libraries permettant la décompression\nde plus d''une centaine de compresseurs (ex. CrunchMania, StoneCracker...).\nXFD est appelé par StoneTracker lors du chargement de la jonction de\nmodule, dans le but de charger des modules, notamment au format ProTracker,\ncompressés des manières les plus diverses. Si un mot de passe est nécessaire,\nil vous le sera demandé. Si XFD est indisponible, StoneTracker est cependant\ncapable de décompresser les fichiers PowerPacker et CrunchMania par lui-même.\n\nSi vous ne possèdez pas dêja le système XFD, il est relativement facile à\nse procurer, notamment sur le site Aminet, dans le répertoire util/pack.\n@endnode\n\n@node Install "Installation"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nStoneTracker est fourni avec un script d''installation pour le désormais\nincontournable utilitaire Installer de Commodore, ce qui facilite grandement\nson installation sur votre disque dur. Il vous suffit, sous Workbench, de\ndouble-cliquer sur l''icone du script d''installation (disponible en Anglais et\nFrançais, je suppose que vous opterez pour la seconde solution) et de suivre\nles instructions à l''écran. A moins que vous ne soyez un réel débutant, je\nvous conseille de choisir le mode ''expert'', où le script ne fera pratiquement\nrien sans vous demander la permission avant.\n\nSi vous désirez installer vous-même StoneTracker sur votre disque dur (pour\nceux qui cherchent la complication), vous devez :\n\n. copier le programme StoneTracker et sa présentation StoneIntro se trouvant\n  sur la disquette 1 où vous désirez les mettre, le mieux étant dans un\n  répertoire séparé.\n\n. copier le fichier de préférences StoneTracker.Prefs se trouvant sur la\n  disquette 1 dans le répertoire ENVARC: de votre disque dur.\n\n. copier les bibliothèques StonePlayer.Library et StonePacker.Library\n  se trouvant sur la disquette 1 dans le répertoire LIBS: du disque dur\n  (vous pouvez aussi les copier dans le répertoire du StoneTracker mais\n  DeliStone et EagleStone ne les trouveront pas et refuseront de se lancer)\n\n. copier la bibliothèque de requète reqtools.library (© Nico François) se\n  trouvant sur la disquette 1 dans le répertoire LIBS: du disque dur.\n\n. copier le catalogue français StoneTrackerDemo.catalog dans le répertoire\n  locale:catalogs/français de votre disque dur.\n\n. copier les musiques d''exemple se trouvant dans le répertoire modules/ de la\n  disquette 2 où vous désirez les mettre, le mieux étant dans un répertoire\n  séparé.\n\n. copier la ou les documentations StoneTrackerDemo.Guide (Française) et\n  StoneTrackerDemo_E.Guide (Anglaise) se trouvant sur la disquette 2 où vous\n  désirez les mettre et modifier la ligne "Multiview=..." du fichier\n  StoneTracker.prefs pour indiquer le directory où la documentation se\n  trouve.\n\n. la version complète comprend une disquette supplémentaire. Cette version\n  contient également des programmes d''exemple, includes et bibliothèques\n  linkables pour le développement en C, des includes, autodocs et programmes\n  d''exemple pour le développement en Assembleur, des players à inclure dans\n  vos applications, des players pour DeliTracker et EaglePlayer, un player\n  autonome et deux mires, également intégrables dans vos applications.\n@endnode\n\n@node Disclaimer "Mentions légales"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nStoneTracker vous est fourni "tel quel" sans aucune garantie d''aucune sorte.\nLes auteurs et les autres parties engagées dans la distribution de ce\nlogiciel se dégagent de toute responsabilité quant aux dommages que le\nprogramme pourrait causer quelle que soit leur nature. Vous utilisez ce\nprogramme à vos risques et périls.\n\nStoneTracker, les routines sonores (stoneplayer.library et binaires), la\nlibrary de compression/décompression (stonepacker.library), la bibliothèque\nlinkée pour le C (stoneplayer.lib), les fichiers include, les players\nexternes (PlayStone, DeliStone, EagleStone) et toute la documentation sont\ncopyright 1995 Emmanuel MARTY & Michael LAVAIRE. Toute modification quelle\nqu''elle soit par une personne autre que nous ou toute autre opération non\nexplicitement autorisée ici sur les fichiers précités est illégale. Copier\nla version de démonstration (qui affiche explicitement ''démo'' dans une\nrequète au démarrage du programme et qui réaffiche cette requète à toute\ntentative de sauvegarde) est autorisé (à condition que soit distribué la\ntotalité des fichiers composant cette version de démonstration et ceux-ci\nsous leur forme originale, et que la personne ou l''entité distributrice ne\ndemande pas un prix supérieur à celui du support sur lequel le programme est\ndistribué) et même encouragé. Copier et/ou distribuer la version commerciale\n(complète, qui permet la sauvegarde) est formellement interdit à l''exception\nde détenteurs de contrats signés des auteurs.\n\nLa totalité des musiques d''exemple est copyright 1995 Jérôme ANGELOT. Toutes\nmodifications ou réutilisations de ces musiques sans l''accord écrit de leur\nauteur sont interdites, que ce soit partiellement ou entièrement, à des fins\ncommerciales ou non.\n\nL''image de présentation de StoneTracker est copyright 1995 Nicolas RIVIERE.\nToute modification ou réutilisation entière ou partielle de cette image sous\nquelque forme que ce soit, à des fins commerciales ou non (à l''exception d''un\narticle ou d''une publicité décrivant explicitement le StoneTracker) sans\nl''accord écrit de son auteur est interdite.\n\nToute personne enfreignant les règles précitées est passible de poursuites\njudiciaires de la part du ou des détenteurs du copyright qui a été violé.\n\nNous autorisons Peter Kunath et Frank Riffel (auteurs de DeliTracker) à\ninclure le programme "DeliStone" dans la distribution des versions\nprésentes et futures de leur player DeliTracker. Les conditions légales\ns''appliquant à DeliTracker et à ses players s''appliqueront alors au\n"DeliStone" distribué avec ce programme.\n\nNous autorisons Henryk Richter et Jan Blumenthal (auteurs d''EaglePlayer) à\ndistribuer le programme "EagleStone" dans la distribution des versions\nprésentes et futures de leur player EaglePlayer. Les conditions légales\ns''appliquant à EaglePlayer et à ses players s''appliqueront alors au\n"EagleStone" distribué avec ce programme.\n\nAvoir acquéri la version complète du programme vous donne le droit d''utiliser\nles "binaires" (les routines sonores du StoneTracker intégrables dans vos\napplications), des musiques composées sur StoneTracker et/ou la stoneplayer\nlibrary dans vos applications, même commerciales.\n@endnode\n\n@node Config "Configuration matérielle"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nLa puissance se paie... StoneTracker a été écrit dès le départ pour les\nnouvelles générations (plus très nouvelles maintenant) d''Amiga.\n\nPar conséquent, faire tourner StoneTracker et les players externes nécessite\nun processeur 68020 ou supérieur, et le système 2.04 (v37) ou plus récent\n(le programme tire cependant parti des fonctions du système 3.0 si il est\nprésent)\n\nLe programme ne demande pas les circuits AGA (ce serait idiot) ce qui veut\ndire que outre les Amiga 1200 et 4000, StoneTracker peut par exemple tourner\nsur un Amiga 2000 avec le système 2.04 et une carte accélératrice. Notez\ntoutefois que l''architecture plus évoluée des circuits AGA permet un\nrafraichissement de l''écran nettement plus rapide que sur les circuits\noriginaux ou les circuits ECS en mode 5-8 voix.\n\nL''éditeur musical StoneTracker et les players externes ont été programmés et\ntournent sans problème sur moniteur multisync, VGA ou autre. Il fonctionnent\nbien entendu sur les moniteurs ou téléviseurs PAL ou NTSC "de base".\n@endnode\n\n@node Auth "Auteurs & Editeur"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nReportez vous aux @{"mentions légales", link Disclaimer} pour des informations sur les copyrights\net sur ce que nous autorisons et interdisons.\n\n\nEmmanuel MARTY		Programmation de l''éditeur (StoneTracker), des\n                        routines d''importation de formats musicaux, du\n			compresseur de samples DeltaHuffman, de la library\n			de compression/décompression (stonepacker library)\n		        et des players externes : PlayStone, DeliStone et\n		        EagleStone. Traduction anglaise de la documentation.\n\nMichael LAVAIRE		Programmation des routines sonores (la stoneplayer\n			library et les players à inclure dans vos programmes)\n			du compresseur de samples StoneCruncher/Mickey, et\n			des deux mires.\n\nJérôme ANGELOT		Composition de toutes les musiques d''exemple.\n\nNicolas RIVIERE		Conception de l''image "StoneTracker Sound System".\n\nBenoit SAINT-MOULIN	Dessin de l''icône StoneTracker pour MagicWB en\n			quelques heures.\n\n\nVous êtes encouragés à contacter les auteurs pour fournir vos suggestions,\nrapports de bugs ou autres :\n\n@{u}Emmanuel MARTY@{uu}				@{u}Michael LAVAIRE@{uu}\n10 Impasse du Romarin			99 rue François Villon\n34920 Le Crès				34130 Mauguio\nFRANCE					FRANCE\n\nOu par courrier électronique : [email removed] (Internet)\n\n\nLa distribution exclusive de StoneTracker 1.25 en France a été accordée\npar contrat à l''équipe extrèmement dynamique de :\n\n@{u}Quartz Informatique@{uu}\nB.P. 27\n74401 CHAMONIX Cedex\nFRANCE\n\nTél/Fax/Rép : (+33) 50.53.82.62\n(reconnaissance automatique)\n\nSi vous désirez acquérir la version complète du programme, envoyez 190 Francs\nFrançais (TTC) à l''adresse ci-dessus. Vous pouvez également les contacter pour\nrecevoir le catalogue des autres programmes qu''ils distribuent ou pour faire\ndistribuer vos programmes si vous êtes développeur.\n\nLes distributeurs étrangers désireux de distribuer StoneTracker dans le ou\nles pays où ils sont implantés sont invités à contacter les auteurs pour\nobtenir un accord écrit.\n@endnode\n\n@node Thanks "Remerciements"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\nEmmanuel :\n\n [] Nicolas Rivière pour l''image de la mire StoneTracker, pour chanter des\n    chansons débiles et me faire mourir de rire à longueur de journée.\n\n [] Nicolas Daire pour avoir colorisé l''interface utilisateur du tracker et\n    provoqué l''apparition de bugs incroyables.\n\n [] Jérôme Angelot pour les idées et les musiques d''exemple.\n\n [] Brice Fromentin pour l''extension StoneTracker pour AMOS.\n\n [] Benoit Saint-Moulin pour l''icône 8 couleurs de StoneTracker, pour la\n    réparation du 4000, pour le hardware supplémentaire, pour le sympathique\n    séjour en Belgique et pour le job de rêve !\n\n [] Nico François pour reqtools.library.\n\n [] Cyprien Benezet pour me faire mourir de rire depuis de longues années\n    et pour les boites à con qui encombrent mon étagère.\n\n [] Patrick et Alban pour avoir pallié à l''absence de mon 4000 par un\n    1200 et une carte accélératrice.\n\n [] ZestOOn pour se coiffer avec une éponge et MIPS pour vivre sous\n    tranxène, et pour les deux utiliser leur talent d''infographistes\n    pour égayer les productions Christophe Clark.\n\n [] Fanny pour avoir été ma coiffeuse et mon photographe personnel à la GASP\n    et pour avoir gagné le premier prix du concours d''originalité rubrique\n    enveloppes.\n\n [] R.J. Mical, concepteur du système, Jay Miner, concepteur du hardware, et\n    tous les autres concepteurs de l''Amiga pour avoir inventé l''utilisation\n    de l''informatique par plaisir plus que par contrainte.\n\n [] Tous les utilisateurs qui nous ont envoyé des suggestions pour\n    StoneTracker. Qu''ils en soients remerciés.\n\n [] Tous ceux que j''ai rencontré à la GASP mais que je n''ai pas cités.\n\n\nMichael :\n\n [] Nicolas DAIRE pour son soutien et sa facheuse tendance à trouver les bugs\n    où il n''y en a pas.\n\n [] Jérome ANGELOT pour les essais du StoneTracker et sa connaissance de la\n    musique.\n\n [] Bruno MILLION pour avoir soutenu Jérome.\n\n [] A Chapter 8 pour les idées de projets ...\n\n [] Ma soeur pour me frapper quand je fais des fautes d''orthographe.\n\n [] Et à tous ceux que j''ai oublié mais qui m''ont soutenu pendant cette dure\n    année de travail.\n@endnode\n\n@node DStroy "A propos de D-Stroy..."\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nA propos de D-Stroy...\n\nUn jeu Shareware utilisant des musiques composées par Jerôme ANGELOT  (auteur\ndes musiques d''exemple) sur StoneTracker sera terminé en Octobre, à  la  fois\nsur PC et sur Amiga (AGA)... Il reprend le principe  de  jeu  de  Bomber  Man\n(DynaBlaster) mais avec beaucoup de nouvelles idées, des  monstres  utilisant\ndes algorythmes d''intelligence artificielle, des graphismes en  256  couleurs\nassez délirants (exemples de monstres : vampires, nains de jardin, fleurs..),\ndes musiques StoneTracker, beaucoup de niveaux, d''options, de configurabilité\net de codes secrets  débiles,  jusqu''à  4  joueurs  sur  une  machine  ou  en\nnull-modem (possible entre PCs, Amigas ou PC/Amiga). Programmé entièrement en\nassembleur sur PC (code 386 32 bits protégé,  nécessite aussi carte  SVGA  au\nstandard VESA) ainsi que sur Amiga (code 68020, AGA nécessaire).\n\nCode PC    : André RIEUSSEC (jeu)\n             David GALLO (éditeur de niveaux, compression, routines sonores)\n             Adam Seychell (DOS32 DosExtender)\nCode Amiga : Emmanuel MARTY (jeu & éditeur StoneTracker)\n	     Michael LAVAIRE (routines sonores & compression)\nGraphismes : Nicolas RIVIERE\nMusiques   : Jérôme ANGELOT\n\nAvec le StoneTracker est distribué un @{"texte  d''information", link DStroy.Presentation} écrit par\nl''instigateur du jeu, Nicolas RIVIERE.\n@endnode\n\n@node DStroy.Presentation "Présentation de D-Stroy ..."\n\n                           FULLY BUGGED SOFTWARE\n\n                                  D. STROY\n\n\n                              * PRESENTATION *\n\n\n         Salut...!\n    Fully Bugged Software est fier de vous présenter son Premier Jeu: D-STROY.\n    Sans grande prétention, ce jeu a surtout été realisé pour que le, ou\n    plutot les joueurs s''amusent un bon moment devant un p''tit jeu sympa.\n    \n    Disponible durant l''été sur P.C., ce jeu va etre adapté sur Amiga 1200\n    par Emmanuel Marty, co-programmeur du STONE TRACKER !\n    La version P.C. comprend d''ailleurs l''adaptation des routines sonores\n    du STONE TRACKER, et ses musiques seront composées par Jerome Angelot,\n    dont vous pouvez écouter les Musiques proposées en exemple sur le STONE !\n\n    D-STROY P.C. et AMIGA seront "compatibles" et vous pourrez Linker les \n    2 machines pour y jouer a plusieurs, ( 1 a 4 Joueurs )\n\n    D-stroy sera bientot disponible en version SHAREWARE un peu partout,\n    NE LE RATEZ PAS !\n\n    \n    Pour Tout Renseignement, Ecrivez a :\n\n    Version P.C.                                Version Amiga.\n    ------------                                --------------\n         F.B.S.                                 Emmanuel MARTY\n    Nicolas Riviere                             10 Impasse du Romarin\n    8 Rue Des Hospices                          34920 Le Crès\n    34090 Montpellier                           ([email removed])\n\n\n        J''espère que les 2 versions vous plairont,\n        Et vous remercie, Ami(e) du Bout des Ondes,\n        De votre Attention !\n\n        BAT.\n@endnode\n\n@node Basics "Principes de base"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n	Qu''est-ce qu''un @{"tracker" link Dico} ?\n\n	Un tracker est un programme dédié à la gestion du son de votre\nmachine, dans le but d''agencer des sons, de les traiter, et de les mettre en\nforme afin d''obtenir l''effet désiré, qui est le plus souvent une musique.\nL''édition de la partition de musique se fait le plus souvent note à note,\nc''est-à-dire que vous entrez les unes après les autres les notes constituant\nvotre future symphonie.\n\n	Cette partition est divisée en mesures, qui sont appelées @{"patterns" link Dico}\ndans la terminologie des trackers, qui sont en fait des "tableaux" de taille\négale à deux dimensions, composés de lignes (autant qu''il y a de @{"voix" link Dico}\n(pistes) sonores possibles, si vous préférez de sons pouvant être joués\nsimultanément), et de colonnes qui peuvent être remplies des notes à jouer\nsur chaque voix.  Le tracker joue les notes séquentiellement, les unes à la\nsuite des autres, à une vitesse que le musicien peut choisir, et qui est\nreprésentée par le @{"BPM" link Dico} (Beats per minute).  L''ordre dans lequel les patterns\nsont jouées peut bien entendu être choisi par le musicien, ce qui permet par\nexemple de répéter le refrain.\n\n	Les notes composant la musique ne sont bien évidemment pas suffisantes\npour reproduire un son. Il faut également leur associer un instrument, ou\n@{"sample" link Dico}. Les trackers utilisent la méthode naturelle de reproduction de sons\nsur l''Amiga, à savoir les instruments "échantillonnés", c''est à dire des\ninstruments dont une note a été jouée par un instrument réel puis convertie en\nnombres compréhensibles par l''Amiga par l''intermédiaire d''un échantilloneur\nsonore (@{"sampler" link Dico}). Le tracker demande alors de reproduire le son et peut\ndécliner toute la gamme à partir d''une seule note. Tous les sons naturels\npeuvent être ainsi "échantillonnés" et utilisés dans une musique composée sur\nun tracker, que ce soit des instruments, des bruits divers, ou même des voix,\nce qui peut conférer à cette méthode un grand réalisme. Au niveau, disons,\nprofessionnel, cette technique est utilisée pour composer les morceaux de\ndance music d''aujourd''hui...\n\n	A notre niveau plus modeste, nous disposons donc d''un véritable petit\nmagnéto numérique multipiste avec, sur la plupart des déclinaisons ou clones\ndu premier des trackers sur Amiga (SoundTracker de Karsten Obarski, que l''on\na parfois tendance à oublier), 4 voix sonores disponibles (ce qui veut dire\nque 4 sons échantillonés peuvent être simultanément reproduits, limitation\nimposée, si on ne se creuse pas un peu la tête, par l''Amiga... Il faudra donc\nparfois ruser un peu avec un nombre d''instruments plus important), et un\n@{"effet" link FX} associable à chaque note, qui est en fait une commande pouvant influer\nsur les propriétés du son (vitesse, volume sonore, etc. mais aussi vibrato,\ntremolo, crescendo, decrescendo...)\n\n\n\n	Afin de vous faciliter le travail, le clavier de votre machine\npréférée est transformé en veritable clavier de synthé s''entendant sur 3\noctaves :\n\n	Ainsi, par exemple, pour le premier octave:\n\n              do1#     re1#             fa1#      sol1#    la1#\n	  do1      re1      mi1      fa1      sol1      la1      si1\n\n	Se traduit sur votre clavier par :\n\n               S        D                G          H        J\n	   W        X        C        V        B         N       ,\n\n	Qui se traduira finalement sur l''editeur par:\n\n              C1#      D1#               F1#      G1#      A1#\n	  C1       D1       E1       F1       G1       A1       B1\n\n\n	En effet, aujourd''hui, pratiquement tous les trackers utilisent cette\n@{"notation Américaine" link USANotes} textuelle, qui bien qu''arbitraire est beaucoup plus\nconcise donc adaptée à la représentation des notes sur un écran où la place\nn''est pas infinie, et le nombre de "voix" affichées côte à côte sans cesse\ncroissant. Seuls quelques irréductibles continuent à proposer la notation sur\nportée qui bien que plus naturelle pour un musicien n''est pas forcément\npratique pour un tracker, dont l''approche de la gestion des sons diffère\ntotalement de celle de ses grands frêres, les logiciels MIDI. Mais les\ndeux groupes de logiciels ne servent pas le même but. Les trackers sont\nplutôt orientés vers la production ludique, tandis que les logiciels\nMIDI visent plutôt le public des "musiciens professionnels".\n\n\n\n	Comme décrit précédemment, une pattern de tracker se traduira ainsi :\n\n\n            Voix 1   |   Voix 2   |   Voix 3   |   Voix 4      ...\n      00| C-1 010000 | --- 000000 | --- 000000 | --- 000000|\n      01| --- 000000 | --- 000000 | --- 000000 | --- 000000|\n      02| --- 000000 | --- 000000 | --- 000000 | --- 000000|\n      03| --- 000000 | G#2 0F0482 | --- 000000 | --- 000000|\n		|	     |            |            |   \n		:	     :		  :	       :\n		.	     .		  .	       .\n		.	     .		  .	       .\n\n\n		et ceci sur autant de lignes que la mesure en comporte,\nchacune pouvant contenir une note et un @{"effet" link FX}. On peut aussi remarquer que les\nlignes sont numérotées à partir de 0. A droite de la note C1, en ligne 00 de\nla voix gauche, figure le chiffre 01. Il s''agit de l''affectation de\nl''échantillon sonore, c''est a dire que la note C1 sera jouée avec\nl''échantillon de numéro 01, ce qui correspondra à l''échantillon que vous aurez\ndécidé de placer en position 01 dans la liste des échantillons. Les divers\neffets que l''on peut appliquer sur chaque note sont eux aussi entrés sous\nforme de nombres lors de l''édition. Ainsi, à la ligne 03, voix droite, la note\nsol # de l''octave 2 ou G2# en notation Américaine sera jouée par l''instrument 0F\nsoit en @{"notation hexadécimale" link hexa} l''intrument 15 de la banque de sons. A cette note\nsera appliqué un effet: il s''agit de l''effet 04xx permettant d''appliquer un\nvibrato au son. Le x82 est le paramètre de l''effet, ici du vibrato, qui dans ce\ncas précis représente sa puissance... Mais nous verrons cela dans la\n@{"partie concernant les effets" link FX}.\n@endnode\n\n@Node Dico "Lexique"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n	@{b}tracker@{ub}		programme de création musicale basé sur la\n			restitution séquentielle de sons échantillonés, sur\n                        plusieurs voix (pistes) sonores simultanément.\n\n	@{b}track@{ub}		voix, piste, canal, etc. de restitution d''un seul\n			son échantilloné à un instant donné.\n\n	@{b}pattern@{ub}		mesure. "grille" qui contient un certain nombre\n			de notes (le même pour toutes les patterns)\n			destinées à être rejouées séquentiellement. sur\n			les trackers traditionnels, une pattern contient\n			les notes pour toutes les voix. sur le StoneTracker,\n			une pattern ne contient les notes que d''une voix.\n\n	@{b}position@{ub}	la liste des positions indique pour chaque mesure,\n			quelle pattern sera jouée (sur les trackers\n			traditionnel) ou quelle pattern sera jouée sur\n			quelle voix (sur le StoneTracker).\n\n	@{b}song@{ub}		litéralement "chanson". sur StoneTracker (cette\n			notion n''existant pas sur les trackers traditionnels)\n			représente la définition de la liste de positions,\n			du nombre de voix et du BPM (voir ci-dessous). Les\n			patterns étant partagées sur StoneTracker par toutes\n			les songs, vous pouvez donc créer des listes de\n			positions différentes et donc composer plusieurs\n			chansons en utilisant les mêmes instruments et mêmes\n			en réutilisant certaines patterns (celles-ci ne\n			contenant les notes que pour une seule voix, vous\n			pouvez par exemple réutiliser un rythme de batterie\n			ou une ligne de basse).\n\n	@{b}sample@{ub}		échantillon. représentation informatique (numérique)\n			de la variation de tension électrique caractéristique\n			d''un son réel, permettant à l''ordinateur et au\n			tracker de recréer cette variation de tension et donc\n			le son avec un certain réalisme.\n\n	@{b}sampling@{ub}	échantillonage. action consistant à\n			crée un sample à partir d''un son réel.\n\n	@{b}module@{ub}		"entité suprème", votre musique complète. regroupe\n			toutes les songs (donc toutes les positions), toutes\n			les patterns et tous les instruments. tout ce\n			que vous pouvez créer sur StoneTracker se retrouve\n			dans le module.\n\n	@{b}temporisation@{ub}	Deux facteurs entrent en jeu dans la vitesse de\n			reproduction de la musique : la temporisation\n			entre les lignes et le BPM (voir ci-dessous).\n			La temporisation entre les lignes est le temps\n			qu''attend StoneTracker avant de jouer la ligne\n			suivante de la pattern. Plus ce chiffre est grand,\n			moins la musique va vite. La vitesse normale\n			est de 6. Il peut varier entre 1 (vitesse maximale)\n			et 31 (vitesse minimale). Vous pouvez vous reporter\n			à l''effet @{"Set Speed",link "Set Speed"}.\n\n	@{b}BPM@{ub}		Beats per minute (battements par minute).\n			Le deuxième facteur déterminant la vitesse de\n			reproduction de la musique. Il s''agit ici du\n			"tempo" de la musique. Sa valeur normale est\n			de 125 (7D en @{"héxadécimal",link hexa}. Il peut varier entre 32,\n			soit 20 hexa (le plus lent) et 255, soit FF hexa (le\n			plus rapide). Vous pouvez vous reporter à l''effet\n			@{"Set Speed",link "Set Speed"}.\n@endnode\n\n@node USANotes "Notation Américaine"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n	Notation américaine :\n\n		C	Do\n		D	Ré\n		E	Mi\n		F	Fa\n		G	Sol\n		A	La\n		B	Si\n\n@endnode\n\n@node HEXA "Notation Hexadécimale"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n	La notation hexadécimale, très utilisée en informatique, est une base\nnumérique différente de la base décimale. Dans cette base, il n''y a pas dix\nchiffres comme en système décimal mais seize, symbolisés par les chiffres de\n0 à 9, et les lettres de A à F pour représenter les chiffres restants. Les\nopérations entières traditionnelles fonctionnent également dans cette base\net possédent les mêmes propriétés. Ainsi, de la même manière que 20-1=19 en\ndécimal, 20-1=1F en hexadécimal. On peut à priori se demander les avantages\nd''une telle notation ; ils sont multiples. Outre son intimité avec le\nfonctionnement de la machine, elle permet d''écrire les nombres avec souvent\nmoins de chiffres qu''en notation décimale. Ainsi, on peut avec deux chiffres\nécrire les nombres 00 à FF soit à décimal 000 à 255 (qui nécessite trois\nchiffres). Vous verrez avec de l''expérience que les nombres hexadécimaux sont\nbien plus faciles à retenir de par leur nombre de chiffres réduit, ce qui\npourra se révéler bien pratique si vous utilisez beaucoup d''instruments et ne\nvoulez pas perdre votre temps à rechercher leur numéro ou si vous désirez\néviter d''être sans cesse plongés dans la liste des effets pour rechercher\négalement leur numéro. De plus, certains nombres, entrant en jeu dans la\ncomposition de la musique, tombent "rond". Par exemple, les ingénieurs qui\nont conçu le circuit sonore Paula de l''Amiga ont prévu des niveaux de volume\nsonore variant de 0 (silence) à 64 (volume plein). En hexadécimal, ca devient\n00 à 40. Augmenter le volume "à la main" pourrait donc se traduire de la\nmanière suivante en décimal et en hexadécimal :\n\n	décimal		hexadécimal\n	0		0\n	8		8\n	16		10\n	24		18\n	32		20\n	40		28\n	48		30\n	56		38\n	64		40\n\nL''hexadécimal semble plus simple, cette fois-ci... terminons avec quelques\nopérations d''exemple en hexadécimal :\n\n	opération	résultat\n	5 + 5		A\n	10 - 1		F\n	28 + 28		50\n        2C + 2A         56\n	55 * 2		AA\n	40 / 2		20\n	50 / 2		28\n@endnode\n\n@node Binary "Notation Binaire"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n	La notation binaire, comme la notation @{"hexadécimale", Link Hexa}, est trés proche\ndu fonctionnement de la machine. Toutes les opérations internes du\nprocesseur se font en binaire.\n\nComme son nom l''indique, le ''bi'' de binaire signifie 2. Contrairement à\nl''hexadécimal, cette notation posséde seulement deux chiffres, 0 ou 1,\nappelés ''bits''.\n\nChaque paramètre lié à un effet, est composé de deux chiffres en hexadécimal.\nCes deux chiffres forment un octet qui est composé de huit bits.\nDonc pour chaque chiffre hexadécimal, il y a quatre bits.\n\n\n	Bit 7	Bit 6	Bit 5	Bit 4	Bit 3	Bit 2	Bit 1	Bit 0\n\n	  |       |       |       |	  |	  |	  |	  |\n           \____  |       |  ____/	   \____  |	  |  ____/\n	        \__\_   _/__/                   \__\_   _/__/\n                   \ \ / /                         \ \ / /\n\n		      x				      y\n\nLa table suivante vous donne la conversion de quatre bits au format binaire\nvers la notation hexadécimale et vice-versa.\n\n\n	      Binaire Héxa	      Binaire Héxa\n\n		0000	0		1000	8\n		0001	1		1001	9\n		0010	2		1010	A\n		0011	3		1011	B\n		0100	4		1100	C\n		0101	5		1101	D\n		0110	6		1110	E\n		0111	7		1111	F\n\n\nExemple :\n\n	Bit 7	Bit 6	Bit 5	Bit 4	Bit 3	Bit 2	Bit 1	Bit 0\n\n	  0	  1	  0	  1	  1	  1	  1	  0\n\n	  |       |       |       |	  |	  |	  |	  |\n           \____  |       |  ____/	   \____  |	  |  ____/\n	        \__\_   _/__/                   \__\_   _/__/\n                   \ \ / /                         \ \ / /\n\n		      5				      E\n@endnode\n\n@node AREXX "AREXX"\n \n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n  AREXX est le portage Amiga du langage REXX. Il ne serait qu''une sorte\n  de BASIC assez primitif s''il ne possèdait pas une faculté qui est plus ou\n  moins sa raison d''être, celle de contrôler d''autres applications prévues\n  pour et qui tournent en même temps que le programme AREXX. Ces applications\n  offrent au programmeur un certain nombre de commandes spécifiques par\n  l''intermédiaire d''un port AREXX. On peut ainsi automatiser par programmation\n  les opérations répétitives. Nous ne rentrerons pas plus dans les détails,\n  le but n''étant pas ici de faire un cours complet sur ce puissant langage.\n  Si vous n''y êtes pas dêja familier, vous êtes invités à lire l''abondante\n  littérature qui existe à ce sujet.\n\n\n  StoneTracker possède un port AREXX nommé ''StoneREXX''. Celui-ci gère toutes\n  les commandes nécessaires à sa "commande à distance" :\n \n\n  @{"GET              ", link AREXX.Get}  Lit la valeur d''un paramètre\n  @{"SET              ", link AREXX.Set}  Change la valeur d''un paramètre\n\n  @{"ACTIVATE         ", link AREXX.Activate}  Fait passer l''écran au premier plan\n  @{"ACTIVE           ", link AREXX.Active}  Réactive le programme\n  @{"APPEAR           ", link AREXX.Appear}  Fait apparaitre l''écran\n  @{"CLEAR            ", link AREXX.Clear}  Efface pos,songs,patterns ou samples\n  @{"CONTINUE         ", link AREXX.Continue}  Joue la musique à partir de l''endroit actuel\n  @{"DISK OPTIONS     ", link AREXX.DiskOptions}  Fait apparaitre les options disque\n  @{"EDIT             ", link AREXX.Edit}  Active/désactive le mode d''édition\n  @{"EXPORT MODULE    ", link AREXX.ExportModule}  Exporte le module actuel\n  @{"FILEREQUEST      ", link AREXX.FileRequest}  Affiche une requète de fichier\n  @{"FLUSH SAMPLES    ", link AREXX.FlushSamples}  Réorganise les samples\n  @{"HIDE             ", link AREXX.Hide}  Cache l''écran\n  @{"INACTIVE         ", link AREXX.Inactive}  Rend le programme inactif\n  @{"INFO             ", link AREXX.Info}  Affiche la requète d''information\n  @{"JOIN MODULE      ", link AREXX.JoinModule}  Fusionne un module avec l''actuel\n  @{"LOAD MODULE      ", link AREXX.LoadModule}  Charge un module\n  @{"LOAD SAMPLE      ", link AREXX.LoadSample}  Charge un sample/une banque\n  @{"LOCK INTERFACE   ", link AREXX.LockInterface}  Verrouille l''interface utilisateur\n  @{"MAIN             ", link AREXX.Main}  Fait apparaitre le menu principal\n  @{"NULL             ", link AREXX.Null}  Efface la pattern sous la voix courante\n  @{"PLAY             ", link AREXX.Play}  Démarre la musique\n  @{"PRINT SONG       ", link AREXX.PrintSong}  Imprime une song/toutes les songs\n  @{"QUIT             ", link AREXX.Quit}  Quitte le programme sans confirmation\n  @{"RECORD           ", link AREXX.Record}  Démarre l''enregistrement de notes\n  @{"REMAP PATTERNS   ", link AREXX.RemapPatterns}  Réorganise les patterns\n  @{"REQUEST          ", link AREXX.Request}  Affiche une requète\n  @{"SAVE BANK        ", link AREXX.SaveBank}  Sauve la banque actuelle\n  @{"SAVE CONFIG      ", link AREXX.SaveConfig}  Sauve la configuration\n  @{"SAVE EXEC        ", link AREXX.SaveExec}  Sauve un module exécutable\n  @{"SAVE FX          ", link AREXX.SaveFX}  Sauve des effets sonores\n  @{"SAVE MODULE      ", link AREXX.SaveModule}  Sauve le module actuel\n  @{"SAVE SAMPLE      ", link AREXX.SaveSample}  Sauve le samplec ouant\n  @{"SHOW             ", link AREXX.Show}  Fait apparaitre/passer au premier plan l''éditeur\n  @{"STOP             ", link AREXX.Stop}  Arrète la musique\n  @{"TIME SONG        ", link AREXX.TimeSong}  Chronomètre la song actuelle\n  @{"UNLOCK INTERFACE ", link AREXX.UnlockInterface}  Dévérouille l''interface utilisateur\n  @{"UPDATE           ", link AREXX.Update}  Sauve les modifications\n@endnode\n\n@node AREXX.Get "GET"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}GET <paramètre> @{ub}\n\n        Transfère le @{"paramètre", link AREXX.Parms} demandé dans result.\n@endnode\n\n@node AREXX.Set "SET"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}SET <paramètre> <valeur> @{ub}\n\n        Positionne le @{"paramètre", link AREXX.Parms} demandé à la valeur donnée.\n@endnode\n\n@node AREXX.Parms "Paramètres contrôlables par AREXX"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nParamètres contrôlables par AREXX :\n\n\nCURRENT SONG		Song en cours d''édition (décimal, 1-n)\nCURRENT POSITION	Position en cours d''édition (hexa, 0000-nnnn)\nCURRENT LINE		Ligne en cours d''édition (hexa, 000-nnn)\nCURRENT TRACK		Voix en cours d''édition (décimal, 1-8)\nCURRENT NOTE		Note sous le curseur (décimal, 0-35 pour --- à B-3)\nCURRENT SAMPLE NUMBER	Sample sélectionné (hexa, 00-FF)\nCURRENT SAMPLE		Sample sous le curseur (hexa, 00-FF)\nCURRENT COMMAND NUMBER	Commande affichée par la voix en cours (décimal, 0-7)\nCURRENT COMMAND		Commande sous le curseur (hexa, 0000-59FF)\nCURRENT PATTERN NUMBER	Pattern reliée à la voix en cours (décimal, 0-65535)\nMODULE NAME		Nom du module (ascii)\nSONG NAME		Nom de la song en cours d''édition (ascii)\nSAMPLE NAME		Nom du sample sélectionné (ascii)\nSAMPLE LENGTH		Longueur du sample sélectionné (décimal)\nSAMPLE REPEAT POINT	Point de répétition du sample sélectionné (décimal)\nSAMPLE REPEAT LENGTH	Longueur de répétition du sample sélectionné (décimal)\nSAMPLE VOLUME		Volume du sample sélectionné (hexa, 00-40)\nSAMPLE FINETUNE		Finetune du sample sélectionné (décimal, -16 à +15)\nMODULE CHANGED		Module modifié ou non (décimal, 0=non ou 1=oui)\nSAMPLES CHANGED		Banque modifiée ou non (décimal, 0=non ou 1=oui)\nFX ACTIVE		Voix FX active ou non (décimal, 0=non ou 1=oui)\nBPM			BPM de la song en cours d''édition (décimal, 32-255)\nTRACKS			Nb de voix de la song en cours (décimal, 1-8)\nMAXTRACKS (1)		Nb de voix max de la song en cours (décimal, 1-8)\nSONGS (1)		Nb de songs dans le module en cours (décimal, 1-x)\nPATTERNS (1)		Nb de patterns dans le module (décimal, 0-65535)\nFX PATTERNS (1)		Nb de patterns FX dans le module (décimal, 0-65535)\nPATTLEN			PatternLength de la song en cours (hexa, 000-nnn)\nMAXPATTLEN (1)		PatternLength MAX de la song (hexa, 000-nnn)\nFREQUENCY		Fréquence 5-8 voix du module en KHz (décimal, 4-50)\nSTATUS			Contenu de la barre de titre (ascii)\nAUTHOR			Nom de l''auteur dans "Ego Area" (ascii)\nLEGAL			Mentions légales du module dans "Ego Area" (ascii)\nCOMMENT			Commentaire sur le module dans "Ego Area" (ascii)\nMODULE PACKER (2)	Compresseur de la banque quand sauvegarde module (3)\nBANK PACKER (2)		Compresseur de la banque quand sauvegarde banque (3)\nBREAK NULL (2)	        Arrête player si vitesse nulle (décimal, 0=non/1=oui)\nKEY REPEAT (2)		Répétition touches hors édition (décimal, 0=non/1=oui)\nIFF SAMPLES (2)		Sauvegarde de samples IFF (décimal, 0=non/1=oui)\nFULL LOCK (2)		Verrouillage éditeur si inactif (décimal, 0=non/1=oui)\nPRINTER PATH (2)	Chemin imprimante, ex. "PRT:" (ascii)\nPAGE HEIGHT (2)		Hauteur de page imprimante (décimal, 1-n)\nFAST MODE (2)		Mode chargement samples en fast (4)\nFAST SIZE (2)		Taille KB chargement samples en fast (décimal, 1-n)\n\n\n(1) : Lecture seulement.\n(2) : modifie la configuration si écrit (si on change un de ces paramètres et\n      que la config est resauvée par @{"SAVE CONFIG",link AREXX.SaveConfig} les modifications seront\n      sauvegardées). ne peut pas être écrit pendant que l''éditeur de\n      configuration est actif.\n(3) : décimal, 0 : pas de compresseur\n               1 : compresseur DeltaHuffman\n               2 : compresseur CrunchMania/LZH+Delta\n	       3 : compresseur StoneCruncher/Mickey\n(4) : décimal, 0 : jamais\n               1 : si taille de samples >= FAST SIZE\n               2 : si mémoire chip libre <= FAST SIZE\n@endnode\n\n@node AREXX.Activate "ACTIVATE"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}ACTIVATE @{ub}\n\n	Fait passer l''écran de l''éditeur au premier plan si il est ouvert.\n@endnode\n\n@node AREXX.Active "ACTIVE"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}ACTIVE @{ub}\n\n        Réalloue les canaux sonores et, si l''allocation réussit, réactive le\n        programme.\n@endnode\n\n@node AREXX.Appear "APPEAR"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}APPEAR @{ub}\n\n        Réouvre l''écran de l''éditeur (si possible).\n@endnode\n\n@node AREXX.Clear "CLEAR"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}CLEAR [POSITIONS|SONGS|PATTERNS|SAMPLES|SAMPLE] @{ub}\n\n        POSITIONS : Efface toutes les positions\n        SONGS     : Efface toutes les songs\n        PATTERNS  : Efface toutes les patterns (et donc les songs)\n        SAMPLES   : Efface tous les samples\n	SAMPLE	  : Efface le sample du slot courant\n@endnode\n\n@node AREXX.Continue "CONTINUE"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}CONTINUE @{ub}\n\n        Identique à @{"PLAY SONG CURRENT", link AREXX.Play}.\n@endnode\n\n@node AREXX.DiskOptions "DISK OPTIONS"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}DISK OPTIONS @{ub}(ou @{b}DISK OPT.@{ub}) \n\n        Affiche la page des options disk.\n@endnode\n\n@node AREXX.Edit "EDIT"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}EDIT [ON|OFF] @{ub}\n\n        ON:  Active le mode d''édition\n        OFF: Désactive le mode d''édition\n        sans paramètre, bascule entre les deux\n@endnode\n\n@node AREXX.ExportModule "EXPORT MODULE"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}EXPORT MODULE <nom> @{ub}\n\n	Exporte le module actuel, soit en ProTracker (4 voix), soit en\n	FastTracker 6 canaux (5/6 voix), soit en FastTracker 8 canaux\n	(7/8 voix).\n\n	nom: nom du fichier (ascii)\n\n	Code de retour: RC=0 si ok, 1 si erreur\n@endnode\n\n@node AREXX.FileRequest "FILE REQUEST"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}FILEREQUEST <MODULE|SAMPLE|DEFAULT> [SAVE] @{ub}\n\n        Affiche un requète de fichiers.\n\n            MODULE  : utilise le chemin et le nom courant pour les modules.\n            SAMPLE  : utilise le chemin et le nom courant pour les samples.\n            DEFAULT : utilise le chemin et le nom courant "par défaut".\n            SAVE    : passe le requester en mode "sauvegarde" :\n                       double-clic désactivé et création de directories\n                       possibles (voir doc de ReqTools).\n\n        Place le nom complet dans result si tout s''est bien passé.\n\n        Code de retour: RC=0 si ok, 1 si erreur (cancel).\n@endnode\n\n@node AREXX.FlushSamples "FLUSH SAMPLES"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}FLUSH SAMPLES [UNUSED] [REMAP] @{ub}\n\n        Réorganise les samples\n\n           UNUSED : Efface les samples inutilisés dans la musique\n                    Efface les données après les boucles\n           REMAP  : Efface les slots vides entre les slots non vides\n@endnode\n\n@node AREXX.Hide "HIDE"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}HIDE @{ub}\n\n        Ferme l''écran de l''éditeur tout en laissant le programme actif.\n@endnode\n\n@node AREXX.Inactive "INACTIVE"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}INACTIVE @{ub}\n\n        Libère les canaux sonores et rend le programme inactif.\n@endnode\n\n@node AREXX.Info "INFO"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}INFO @{ub}\n\n        Affiche la requète d''information.\n@endnode\n\n@node AREXX.JoinModule "JOIN MODULE"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}JOIN MODULE <nom> @{ub}\n\n	Fusionne un nouveau module avec le module actuellement en mémoire,\n	en ajoutant ses songs et ses patterns à la suite de celles en\n	mémoire, et en chargeant les samples en mode "MAP" (élimination des\n	doubles). S''il s''agit d''un module à convertir le nom est quelconque.\n	Si c''est un module StoneTracker, le nom après le path débute par\n	"SPM.", comme pour LOAD MODULE.\n\n	nom: nom du fichier (ascii)\n\n	Code de retour: RC=0 si ok, 1 si erreur\n@endnode\n\n@node AREXX.LoadModule "LOAD MODULE"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}LOAD MODULE <nom> @{ub}\n\n	Charge un nouveau module dans l''éditeur.\n        S''il s''agit d''un module à convertir le nom est quelconque.\n        Si c''est un module StoneTracker, le nom après le path débute par "SPM."\n\n        nom: nom du fichier (ascii)\n\n	Code de retour: RC=0 si ok, 1 si erreur\n@endnode\n\n@node AREXX.LoadSample "LOAD SAMPLE"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}LOAD SAMPLE <nom> @{ub}\n\n	Charge un sample dans le slot actuel/une banque de samples.\n\n	nom: nom du fichier (ascii)\n\n	Code de retour: RC=0 si ok, 1 si erreur\n@endnode\n\n@node AREXX.LockInterface "LOCK INTERFACE"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}LOCK INTERFACE @{ub}\n\n	Verrouille l''interface utilisateur et met un pointeur busy (si\n	l''écran de l''éditeur est ouvert).\n	L''éditeur continue à répondre aux messages AREXX et Commodity.\n@endnode\n\n@node AREXX.Main "MAIN"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}MAIN @{ub}\n\n        Affiche la page des options principales.\n@endnode\n\n@node AREXX.Null "NULL"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}NULL @{ub}\n\n        Vide la pattern sous la voix courante.\n@endnode\n\n@node AREXX.Play "PLAY"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}PLAY [SONG|PATTERN] [TOP|CURRENT] [RESTART] @{ub}\n\n	Démarre la musique.\n\n	   SONG    : joue toute la song (comportement par défaut)\n           PATTERN : boucle sur la position courante\n           TOP     : démarre en haut des patterns (défaut)\n           CURRENT : démarre à la ligne courante\n           RESTART : démarre au début de la song\n@endnode\n\n@node AREXX.PrintSong "PRINT SONG"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}PRINT SONG [ALL] @{ub}\n\n	Imprime la song courante ou toute les songs si "ALL" est précisé.\n@endnode\n\n@node AREXX.Quit "QUIT"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}QUIT @{ub}\n\n        Quitte le programme sans requète.\n@endnode\n\n@node AREXX.Record "RECORD"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}RECORD [SONG|PATTERN] [TOP|CURRENT] [RESTART] @{ub}\n\n        Enregistre des notes tout en jouant la musique\n        Options identiques à @{"PLAY",link AREXX.Play}.\n@endnode\n\n@node AREXX.RemapPatterns "REMAP PATTERNS"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}REMAP PATTERNS @{ub}\n\n	Réorganise les patterns en éliminant les doubles.\n\n	Code de retour: RC=0 si ok, 1 si erreur\n@endnode\n\n@node AREXX.Request "REQUEST"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}REQUEST <titre> <corps> <gadgets> @{ub}\n\n        Affiche une requète.\n\n        titre:   titre du requester\n        corps:   texte dans le requester (caractère 10 pour nouvelle ligne)\n        gadgets: gadgets sélectionnables séparés par ''|'' style EasyRequest().\n                 exemple: "Ok|Cancel", "Resume"...\n\n        Code de retour:\n           result = "0" si gadget le plus à droite (en principe gadget\n           d''annulation) (ou gadget unique) sélectionné, sinon "1", "2" , etc.\n           pour les autres gadgets.\n	   exemple: "Oui|Peut-être|Non". Retour: 1,2 ou 0 respectivement.\n\n        Note:\n           Les trois arguments doivent etre entourés par des apostrophes plus\n           des guillemets intérieurs, vu la manière dont AREXX gère les\n           commandes. Exemple: ''"Téléphone maison"''.\n@endnode\n\n@node AREXX.SaveBank "SAVE BANK"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}SAVE BANK <start> <stop> <nom> @{ub}\n\n	Sauve la banque de samples actuelle.\n	Il est conseillé de faire débuter le nom après le path par "SPS."\n\n	start : no. de slot du sample de départ (hexa)\n	stop  : no. de slot du sample de fin (hexa)\n	nom   : nom de la banque de samples à créer\n\n	Code de retour: RC=0 si ok, 1 si erreur\n@endnode\n\n@node AREXX.SaveConfig "SAVE CONFIG"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}SAVE CONFIG @{ub}\n\n        Sauvegarde la configuration de l''éditeur (dont certains paramètres\n        peuvent être changés par AREXX - voir fonctions @{"GET",link AREXX.Get} et @{"SET",link AREXX.Set}).\n\n        Code de retour : RC=0 si ok, 1 si appelée alors que l''éditeur de\n                         configuration est actif (donc pas à partir du\n                         menu AREXX de StoneTracker...)\n@endnode\n\n@node AREXX.SaveExec "SAVE EXEC"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}SAVE EXEC <nom> @{ub}\n\n	Sauvegarde le module sous forme de programme exécutable.\n\n	nom: nom du fichier (ascii)\n\n	Code de retour: RC=0 si ok, 1 si erreur\n@endnode\n\n@node AREXX.SaveFX "SAVE FX"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}SAVE FX <nom> @{ub}\n\n	Sauve les patterns dans un module sans song (pour utilisation en\n	temps qu''effets sonores - voir documentation du player).\n	Le nom après le path débute par "SPM."\n\n	nom: nom du fichier (ascii)\n\n	Code de retour: RC=0 si ok, 1 si erreur\n@endnode\n\n@node AREXX.SaveModule "SAVE MODULE"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}SAVE MODULE <nom> @{ub}\n\n        Sauve le module actuel.\n        Le nom après le path débute par "SPM."\n\n        nom: nom du fichier (ascii)\n\n	Code de retour: RC=0 si ok, 1 si erreur\n@endnode\n\n@node AREXX.SaveSample "SAVE SAMPLE"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}SAVE SAMPLE <nom> @{ub}\n\n	Sauve le sample du slot courant dans un fichier.\n\n	nom: nom du fichier (ascii)\n\n	Code de retour: RC=0 si ok, 1 si erreur\n@endnode\n\n@node AREXX.Show "SHOW"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}SHOW @{ub}\n\n        Réouvre l''écran de l''éditeur (si possible).\n        Le fait passer au premier plan si il est dêja ouvert.\n@endnode\n\n@node AREXX.Stop "STOP"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}STOP @{ub}\n\n        Arrète la musique\n@endnode\n\n@node AREXX.TimeSong "TIME SONG"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}TIME SONG @{ub}\n\n	Chronomètre la song et renvoie son temps en secondes dans result.\n	NOTE: arrête le player s''il était en train de jouer.\n@endnode\n\n@node AREXX.UnlockInterface "UNLOCK INTERFACE"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}UNLOCK INTERFACE @{ub}\n\n	Déverrouille l''interface utilisateur (si l''écran de l''éditeur est\n	ouvert).\n@endnode\n\n@node AREXX.Update "UPDATE"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}UPDATE @{ub}\n\n	Resauve le module sous son nom.\n	Ne remet à jour que ce qui a été modifié, soit le module (SPM),\n	soit la banque de samples (SPS), soit les deux.\n\n	Code de retour: RC=0 si ok, 1 si erreur\n@endnode\n\n@node Use "Utilisation du StoneTracker"\n@font topaz.font 8\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n StoneTracker 1.25\n--------------------------------------------------------------------------------\n|Position|@{"JoueSong" link InterPlaySong}@{"JouePatt" link InterPlayPos}@{"Stopper " link InterStop}@{" Enreg. " link InterRecord}@{"Continue" link InterContinue}|Fréquence | MonoScope  |\n|@{"Nouveau" Link InterClearPos}|@{"  Edit  " link InterEditPat}@{" Efface " link InterClearPat}@{" AREXX  " link InterAREXX}@{"Désactiv" link InterInactive}@{" Cache  " link InterHide}|          |            |\n|@{"Editer " Link InterEditPos}|@{"  Aide  " link InterHelp}@{"Disk Op." link InterDiskOp}@{" Config " link InterConfig}@{"  Info  " link InterInfo}@{" Quitte " link InterQuit}|  24 Khz  |            |\n-------------------------------------------------------| @{"     # " Link InterFrequency} |            |\n|  Song  |     Samples    |@{"Mix" Link InterMixSample}@{"Réorg" Link InterFlushSample}@{"Choix" Link InterPickSample}@{"Efface" Link InterDeleteSmp}@{"Nouv" Link InterClearSample}|-----------------------|\n|@{"<" link InterButSong}@{"  1" link InterSongNum}@{">" link InterButSong}|  < >   Nome    Lng <> Rep <@{"    0" link InterSampleRep}> Vol <@{"40" Link InterVolumeSample}>| @{"ChannelMeters" Link InterChannelMeters}  | Cmd |\n|@{"Choisir" Link InterPickSong}|  @{"01" Link InterSampleNum} @{"Bass 01 " Link InterSampleName} @{"41200" Link InterSampleLength} Lng <@{"    0" link InterSampleRepLen}> FTU <@{" 0" Link InterFTUSample}>|@{"" Link InterMasterVolume}|               |@{"Suiv" Link InterNextCmd}|\n|@{"Nouveau" Link InterClearSong}|---------------------------------------------| |               |@{"Préc" Link InterNextCmd}|\n|@{"Editer " Link InterEditSong}| Nom Song    : @{"From the future ...          " Link InterSongName}| |               |@{"Edit" Link InterEditCmd}|\n|@{" Temps " Link InterTimeSong}| Nom Module  : @{"Cool baby II                 " Link InterModuleName}|Patt :@{"Nouv " Link InterClearPatt}@{"Edit" Link InterEditPatt}@{"Réorg" Link InterRemapPatt}|\n--------------------------------------------------------------------------------\n| BPM <@{"125" Link InterBPM}>  Pistes <@{"4" Link InterNbTracks}>  LongPat <@{"40" Link InterPattLen}>  @{"FX" Link InterFxSwitch} |@{" Patt:...  Banq:... Temps:...  " Link InterBigGad}|\n--------------------------------------------------------------------------------\n|@{"12" Link InterPosNum}|      @{"  5" Link InterPattNum}     |      @{"  2" Link InterPattNum}     |      @{" 13" Link InterPattNum}     |      @{"  1" Link InterPattNum}     | @{"  5" Link InterFxPattNum} |@{"^v" Link InterChgPos}|\n--------------------------------------------------------------------------------\n|POS|    Piste 1    |    Piste 2    |    Piste 3    |    Piste 4    |  FX  | @{"" Link InterLedState} |\n--------------------------------------------------------------------------------\n@endnode\n\n@Node "InterPlaySong" "Play Song"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nPlay Song permet de jouer la song depuis la position courante.\n@EndNode\n\n@Node "InterPlayPos" "Play Pos"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nPlay Pos permet de jouer en boucle la position courante.\n@EndNode\n\nInterRecord\n@Node "InterStop" "Stop"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nStoppe le player et coupe les sorties sonores.\n@EndNode\n\n@Node "InterRecord" "Record"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nPasse en mode enregistrement. L''enregistrement peut être en continu sur toute\nla song ou sur la position courante seulement.\n\nLe mode dépend de la dernière fois que vous avez fait jouer le tracker :\n\n. s''il jouait en mode position, l''enregistrement se fera sur la position\n  courante.\n. s''il jouait en mode song totale, l''enregistrement se fera à partir de la\n  position courante sur toute la song.\n@EndNode\n\n@Node "InterContinue" "Continue"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nContinue la song a partir de la position et de la ligne courante.\n@EndNode\n\n@Node "InterClearPos" "Clear Position"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nRetire toutes les positions de la song courante (après confirmation) et en\nrecrée une avec les numéros de pattern de chaque voie à 0.\n@EndNode\n\n@Node "InterEditPat" "Edit Pattern"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nPasse en mode édition de pattern.\n@EndNode\n\n@Node "InterClearPat" "Clear Pattern"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nEfface la pattern courante.\n@EndNode\n\n@Node "InterAREXX" "AREXX"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nAffiche le menu d''appel de macro AREXX.\n@EndNode\n\n@Node "InterInactive" "Désactiv"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nDésactive le tracker et désalloue les canaux sonores.\n@EndNode\n\n@Node "InterHide" "Hide"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nFerme l''écran du tracker. Pour l''ouvrir à nouveau, vous pouvez utiliser\nla Hot Key (touche d''appel du tracker), les commodities ou un double clic\nsur l''icone du StoneTracker sur le WorkBench.\n@EndNode\n\n@Node "InterHelp" "Help"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nPermet de lancer cette aide à partir du StoneTracker.\n@EndNode\n\n@Node "InterInfo" "Information"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nInformations concernant les auteurs et le distributeur.\n@EndNode\n\n@Node "InterQuit" "Quitte le StoneTracker."\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nQuitte le StoneTracker après confirmation.\n@EndNode\n\n@Node "InterFrequency" "Fréquence de restitution"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nChoisissez ici la fréquence de mixage des voix pour un mode différent\nde 4 voix. Si le processeur est surchargé par la demande, la fréquence\nredescendra automatiquement.\n\nSi vous possedez un écran multisync, la fréquence de mixage sera au\nmaximum de 50Khz sinon de 28Khz.\n@EndNode\n\n@Node "InterMixSample" "Mixage de la position courante"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nCette fonction permet de créer un sample à partir de la position courante.\nElle peut servir à générer des accords ou des rythmes de batterie.\n\nPour ce faire, positionnez vous dans un mode ou vous aurez le nombre de voix\nsuffisant pour votre rythme (par exemple). Ensuite positionnez les notes et\neffets. Vous pouvez écouter le resultat que vous obtiendrez en faisant un\n@{"PlayPos " link InterPlayPos}.\n\nUne fois le rythme (par exemple) fini, choisissez le numéro du sample qui\ncontiendra le mixage. Puis enfoncez le bouton Mix. Une requète vous demandera\nalors sur quelle note vous voulez effectuer ce mixage et à quel volume. Le\nvolume permet de régler la saturation. Pour un volume de 64 le sample sera de\nmême volume que la position lorsque vous la jouez.\n@EndNode\n\n@Node "InterFlushSample" "Flush Samples"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nAprés quelque heures de création intensive, vous avez chargé plein de\nsamples dans la mémoire de votre ordinateur. En utilisant cette fonction,\nvous effacerez les samples non utilisés et découperez la fin des samples\nne servant pas. Aprés un dur travail, le StoneTracker vous demandera si\nvous voulez regrouper les samples entre eux.\n\nPar exemple les samples numéro 1 et 3 sont utilisés mais le sample 2 non.\nAprés que le StoneTracker soit passé par là, le sample 2 est effacé de la\nmémoire. Maintenant, si vous répondez oui pour regrouper les samples entre\neux, le sample 3 prendra la place du sample 2, à la fois dans la liste\ndes samples et dans les patterns.\n@EndNode\n\n@Node "InterPickSample" "Pick Sample"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nOuvre une fenêtre avec la liste des samples, cela permet de choisir un sample\ntrés vite parmit la totalité des samples disponibles.\n@EndNode\n\n@Node "InterDeleteSmp" "Efface le sample courant"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nEfface, aprés confirmation, le sample courant.\n@EndNode\n\n@Node "InterClearSample" "Efface la totalitée des samples"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nEfface, aprés confirmation, la totalité des samples.\n@EndNode\n\n@Node "InterButSong" "Change le numéro de la song"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nCe bouton change le numéro de la song courante. Si le Tracker n''est pas en\ntrain de jouer, le changement est immédiat.\n\nEn revanche, si le tracker est en train de jouer, le changement ne se fera\nqu''en fin de position. Cela est très utile pour faire des essais de\nsynchronisation entre les songs. Lors de l''attente de la fin de la position,\nsi vous réappuyez sur le bouton, le changement se fera alors immédiatement.\n@EndNode\n\n@Node "InterSongNum" "Numéro de la song courante"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nIndique le numéro de la song courante, ou le numéro de la song à laquelle\nle tracker sautera à la fin de la position.\n\nDe même que lorsque vous appuyez sur @{"<" link InterButSong}@{">" link InterButSong} vous pouvez\nfaire des synchronisations de songs.\n@EndNode\n\n@Node "InterSampleRep" "Point de bouclage d''un sample"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nIndique le point de bouclage du sample. Si ce chiffre est petit, le point\nse situe près du début du sample. Si ce chiffre est proche de la longueur du\nsample, le point de répétition est proche de la fin du sample.\n@EndNode\n\n@Node "InterVolumeSample" "Volume du sample"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nCe chiffre indique le volume du sample en @{"hexadécimal" link HEXA}. Cette\nnotation a été utilisée car lorsque vous placez l''effet @{"Set Volume" link "Set Volume"}\nla notation est en @{"hexadécimal" link HEXA}.\n@EndNode\n\n@Node "InterChannelMeters" "Changement des modes de visions"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nBien qu''il n''y aie en apparence pas de gadget, vous pouvez utiliser la\nsouris pour plusieurs actions.\n\nBouton gauche:	Change le mode de visualisation des samples.\n\n		- Le mode réel\n		- Le mode simulation (Fake utilisé sur protracker)\n		- Le mode volume, vous montre l''etat des volumes\n		- Le mode fréquence, vous montre la hauteur des notes\n\nBouton droit:	Réactive toutes les voix qui auraient été coupées\n@EndNode\n\n@Node "InterPickSong" "Sélectionne une song parmi une liste"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nOuvre une fenêtre et affiche les songs disponibles. De la même facon qu''en\nchangeant de song à l''aide des flèches, vous pouvez enchainer des songs.\n@EndNode\n\n@Node "InterSampleNum" "Numéro du sample courant"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nCe chiffre indique le numéro du sample courant en @{"hexadécimal" link HEXA}. Cette\nnotation a été utilisé pour faciliter le positionnement de numéro de\nsample sur les @{"patterns" link Dico}.\n@EndNode\n\n@Node "InterSampleName" "Nom du sample"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nNom du sample.\n@EndNode\n\n@Node "InterSampleLength" "Longueur du sample"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nLongueur du sample.\n@EndNode\n\n@Node "InterSampleRepLen" "Longueur de répétition du sample"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nLongueur de répétition du sample. Si ce champ est à 0, le sample une fois\njoué s''arrètera. Sinon il recommencera à partir de @{"Rep" link InterSampleRep}\navec la longueur indiquée dans ce champ.\n@EndNode\n\n@Node "InterFTUSample" "Réglage de l''accord du sample."\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nPermet d''accorder le sample. La valeur peut aller de -16 à +15. Les valeurs\nde -8 à +7 sont compatibles avec Protracker.\n\nVoir l''effet @{"SetFineTune" link "SetFineTune"}.\n@EndNode\n\n@Node "InterMasterVolume" "Volume général de la musique"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nPermet de régler le volume général de la musique.\n@EndNode\n\n@Node "InterNextCmd" "Permet d''acceder à l''effet suivant"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nSur chaques piste, on peut insérer 7 effets. Pourtant un seul est affiché\nsur l''écran. Le bouton ''Next'' et ''Prev'' permettent de faire défiler les\neffets sur la piste où le curseur est positionné.\n@EndNode\n\n@Node "InterClearSong" "Efface toute les songs"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nEfface toutes les songs.\n@EndNode\n\n@Node InterSongName "Nom de la la song courante"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nCeci est le nom de la song courante (31 caractéres maximum).\n@EndNode\n\n@Node InterEditCmd "Edition des effets"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nOuvre une fenêtre pour éditer les effets sur la piste courante.\n@EndNode\n\n@Node InterTimeSong "Calcule le temps d''une song"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nStoppe toute activité du tracker et calcule la durée de la song courante.\n\nLa fin est marquée par :\n\n	- la fin de la dernière position\n	- une instruction de saut à une position antérieure\n	- une vitesse nulle : @{''0F00'' Link "Set Speed"}\n	- une instruction de changement de song\n@EndNode\n\n@Node InterModuleName "Nom du module"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nCeci est le nom du module courant (31 caractéres maximum).\n@EndNode\n\n@Node InterClearPatt "Efface le contenu de la song courante"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nRetire toutes les patterns et donc les positions de toutes les songs,\npuis recrée une pattern vide.\n@EndNode\n\n@Node InterRemapPatt "Réorganisation des patterns"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nRéorganise les patterns: ne garde qu''un exemplaire des patterns identiques\npuis remet à jour les numéros de pattern dans les positions. Cette fonction\nest très efficace lors de l''importation de modules aux formats ne disposant pas\nde patterns séparées pour chaque voix.\n@EndNode\n\n@Node InterBPM "Beat Per Minute"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nIndique/Change le @{"BPM" Link Dico} de la song courante.\n@EndNode\n\n@Node InterNbTracks "Nombre de voix"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nIndique/Change le nombre de voix de la song courante.\n@EndNode\n\n@Node InterPattLen "Longueur des patterns"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nIndique/Change le nombre de lignes des patterns, pour le module entier.\n@EndNode\n\n@Node InterFxSwitch "Voix Fx"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nActive/Désactive la voix de contrôle pour la song courante.\n@EndNode\n\n@Node InterBigGad "Informations diverses"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nAffiche alternativement en cliquant dessus,\n\n	soit :\n\nPatt:	  Taille DECOMPRESSEE des patterns en mémoire.\n	  Cette n''est pas indicative de la taille des patterns une fois le\n	  module sauvegardé.\nBank:	  Taille decompressée de la banque de samples en mémoire.\nTime:	  Temps écoulé depuis le lancement de la musique.\nPatt/Pos: Nombre de patterns(@{"en Hexadecimal" Link Hexa})/Nombre de positions de la\n	  song courante.\n	  Si le curseur est positionné sur une des voix musicales, ce chiffre\n	  indique le nombre de patterns musicales dans le module.\n          Si le curseur est positionné sur la voix de contrôle, ce chiffre\n          indique le nombre de patterns de contrôle.\n\n	soit :\n\nFast:	  Indique la taille de mémoire Fast libre.\nChip:	  Indique la taille de mémoire Chip libre.\nTime:	  Indique l''heure système.\nDate:	  Indique la date système.\n@EndNode\n\n@Node InterChgPos "Permet de changer de position"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nPermet de changer de position, dans la song courante\n@EndNode\n\n@Node InterLedState "Led d''état"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nLa couleur de la led vous informe de l''état actuel du tracker.\nLa couleur dépend de votre @{configuration link "InterConfig"}.\n\nLes couleurs indiquent les états suivants :\n\n	- En attente\n	- En train de jouer toute la musique en boucle\n	- En train de jouer la position courante en boucle\n	- En train d''éditer la position courant ou en enregistrement\n	- En mode pas à pas\n@EndNode\n\n@Node InterLoadMod "Charge un module"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nCharge un module, soit au format StoneTracker, soit dans un des formats\n@{"importés" link Imports}. Si il est possible de charger le module, les songs, les patterns\net les samples qui se trouvaient en mémoire seront effacés pour être\nremplacés par ceux contenus dans le module.\n\nSi le standard de compression @{"XPK" link XPK} est installé dans votre système, celui-ci\nsera automatiquement utilisé pour charger les modules compressés\navec une de ses méthodes.\n\nSi le standard de décompression @{"XFD" link XFD} est installé dans votre système, celui-ci\nsera également appelé pour décompresser par exemple les modules ProTracker\ncompressés avec Imploder ou StoneCracker.\n\nSi ces deux standards ne sont pas disponibles, StoneTracker peut décompresser\nles modules compressés par PowerPacker et CrunchMania; c''est le cas par\nexemple d''un nombre non négligeable de modules ProTracker.\n@EndNode\n\n@Node InterSaveMod "Sauve le module"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nSauve le module en cours d''édition. Sauve deux fichiers, à savoir le fichier\npartition (SPM.) qui contient la description des songs, des positions et\ndes patterns, et la banque de samples (SPS.).\n@EndNode\n\n@Node InterLoadSamp "Chargement de samples"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nCharge un sample ou une banque de samples.\n\nStoneTracker peut lire des samples au format RAW (brut), IFF/8SVX, RIFF/WAVE\n(les samples 16 bits ou stéréo sont reduits respectivement en 8 bits et en\nmono), ou un format reconnu par les DataTypes (à partir du système 3.0).\n\nSi une banque de samples au format StoneTracker est sélectionnée, il est\npossible de :\n\n	- Remplacer la banque de samples courante.\n	- L''inserer à la suite de celle-ci.\n	- Ne charger que les samples qui ne sont pas déjà présents dans la\n	  banque courante.\n@EndNode\n\n@Node InterJoinMod "Charge un module comme song(s) supplémentaire(s)"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nCharge un module en tant que song(s) suplémentaire(s). Les nouvelles patterns\nseront inserées à la suites de celle déjà présentes en mémoire. Seuls les\nsamples qui n''existent pas dêja seront chargés (si un sample du module joint\nest le même au niveau de ses données qu''un sample dêja existant dans la\nbanque de samples actuelle, il ne sera pas chargé et son numéro sera remplacé\npar l''original dans les patterns). Les songs supplémentaires sont insérées\nà la suite des songs actuelles.\n\nSi le standard de compression @{"XPK" link XPK} est installé dans votre système, celui-ci\nsera automatiquement utilisé pour charger les modules compressés\navec une de ses méthodes.\n\nSi le standard de décompression @{"XFD" link XFD} est installé dans votre système, celui-ci\nsera également appelé pour décompresser par exemple les modules ProTracker\ncompressés avec Imploder ou StoneCracker.\n\nSi ces deux standards ne sont pas disponibles, StoneTracker peut décompresser\nles modules compressés par PowerPacker et CrunchMania; c''est le cas par\nexemple d''un nombre non négligeable de modules ProTracker.\n@EndNode\n\n@Node InterEGOArea "Informations sur la musique"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nIndique/Permet d''éditer des informations sur la musique, à savoir le nom\nde son auteur, des informations légales (copyright, freeware, etc.), et un\ncommentaire. Chaque texte peut faire jusqu''à 26 caractères.\n@EndNode\n\n@Node InterDosCMD "Lance une commande DOS"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nPermet de lancer une commande DOS. Cette fonction est identique à la fonction\n"exécuter" du Workbench mais elle évite, justement, de retourner sous\nWorkbench.\n@EndNode\n\n@Node InterDelete "Effacement de fichier(s)"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nPermet d''effacer un ou plusieurs fichiers. Pour effacer plusieurs fichiers,\nil faut sélectionner plusieurs noms dans la requète de fichiers en maintenant\nla touche ''shift'' enfoncée pendant que vous sélectionnez un nom.\n@EndNode\n\n@Node InterUpDate "Actualise la sauvegarde du module"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nPermet de ne sauver que se qui à charger depuis la derniére sauvegarde.\n@EndNode\n\n@Node InterExport "Exporte le module"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nExporte la song courante dans un format différent de celui du StoneTracker.\n\nSi la song courante posséde 4 voix, le format sera du protracker.\nSi la song courante posséde 5 ou 6 voix, le format sera du FastTracker 6 voix.\nSi la song courante posséde 7 ou 8 voix, le format sera du FastTracker 8 voix.\n@EndNode\n\n@Node InterSaveBank "Sauvegarde de la banque de sample"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nSauvegarde la banque de sample courante.\n@EndNode\n\n@node Imports "Formats importés"\nStoneTracker est capable d''importer les formats suivants :\n\nSound/Noise/Star/ProTracker	Le format "module" standard sur Amiga et\n				très répandu sur PC également.\n\n				4 voix, 31 instruments, pas de multisong,\n				jusqu''à 128 positions, pas de patterns\n				séparées pour chaque voix, jusqu''à 64\n				patterns globales (128 ou 256 sur certains\n				trackers, StoneTracker les reconnait),\n				longueur fixe de 64 lignes par pattern.\n\n				Le format original (15 instruments) provient\n				de SoundTracker de Karsten Obarski (et n''est\n				pas chargé par StoneTracker, car il pose\n				beaucoup trop de problèmes), a été modifié par\n				Mahoney et Kaktus sur NoiseTracker pour gérer\n			        31 instruments, et a été repris tel quel (à\n				part l''effet "Vibrato" qui a été modifié) par\n				Amiga Freelancers puis Cryptoburners sur\n				leurs ProTracker respectifs.\n\n\nFastTracker			Le format d''un tracker 6/8 voix sur PC.\n\n				6 ou 8 voix, 31 instruments, pas de\n				multisong, jusqu''à 128 positions, pas de\n				patterns séparées pour chaque voix, jusqu''à 64\n				patterns globales, longueur fixe de 64 lignes\n				par pattern.\n\n				Créé par le groupe Triton sur PC. La version\n				1 du format ne s''agit en fait que de la bête\n				adaptation du format ProTracker en 6/8 voix,\n				il était donc facile de l''importer sous\n				StoneTracker, d''autant plus qu''il existe un\n				bon nombre de modules sympa dans ce format.\n				Il existe maintenant une version 2 du format\n				(eXtended Module) mais il n''est pas encore\n				reconnu par StoneTracker, dans la mesure où\n				la majorité des (au demeurant fabuleux et\n				pour la plupart signés Lizardking) modules\n				dans ce format utilisent 16 voix.\n\n\nOctaMED MMD0/MMD1		Le format d''un tracker 4-8 voix bien connu.\n\n				4 à 8 voix, 63 instruments, multisong (mais\n				seule la première song est chargée sur\n				StonTracker pour l''instant... ce n''est pas\n				de la mauvaise volonté mais la débilité de\n				ce format... ce sera fait ultérieurement),\n				jusqu''à 99 songs, jusqu''à 1000 positions,\n				pas de patterns séparées pour chaque voix,\n				jusqu''à 1000 patterns globales, patterns\n				de longueur variable, jusqu''à 3200 lignes\n				par pattern.\n\n				Créé par Teijo Kinnunen. OctaMED peut sauver\n				trois formats différents : MMD0, MMD1 et\n				MMD2. StoneTracker peut importer les deux\n				premiers formats, ce qui devrait etre\n				suffisant. Le MMD2 n''est pas chargé dans la\n				mesure où je ne possède aucune documentation\n				à son sujet et que je vois pas de différence\n				notable dans les fichiers par rapport au MMD1.\n				A l''heure actuelle, StoneTracker n''importe\n				que la première song dans le cas d''un module\n				multisong (cela sera étendu à toutes les songs\n				ultérieurement) et ne charge aucun instrument\n				synthétique ou hybride, dans la mesure où\n				ils ne sont pas, pour l''instant du moins,\n				implémentés.\n\n\nOktalyzer 1.1			Le format du premier tracker 8 voix pour\n				Amiga.\n\n				4, 6 ou 8 voix, 36 instruments, pas de\n				multisong, jusqu''à 128 positions, pas de\n				patterns séparées, jusqu''à 65535 patterns\n				globales, patterns de longueur variable,\n				jusqu''à 65535 lignes par pattern.\n\n				Créé par Armin Sander et précurseur de\n				toutes les routines de mixage 8 voix.\n\n\nArt Of Noise			Le format d''un tracker 8 voix pour Amiga.\n\n				4 ou 8 voix, 61 instruments, pas de\n				multisong, jusqu''à 256 positions, pas de\n				patterns séparées, jusqu''à 128 patterns\n				globales, longueur fixe de 64 lignes par\n				pattern.\n\n				Créé par Bastian Spiegel (Twice/Lego) et assez\n				récent donc pas encore utilisé dans quoi que\n				ce soit. Cela pourrait venir, d''où ce\n				chargeur.\n\n\nSoundFX 1.3			Le format d''un "concurrent" de SoundTracker.\n\n				4 voix, 15 instruments, pas de multisong,\n				jusqu''à 128 positions, patterns séparées\n				pour chaque voix, jusqu''à 64 patterns,\n				longueur fixe de 64 lignes par pattern.\n\n\nThePlayer 4.1A-6.1A		Un dérivé de format Protracker avec les\n				patterns compressées\n\n				4 voix, 31 instruments, pas de multisong,\n				jusqu''à 128 positions, pas de patterns\n				séparées pour chaque voix, jusqu''à 64\n				patterns globales, longueur fixe de 64\n				lignes par pattern.\n\n				Créé par Jarno Panaanen (Guru/Sahara\n				Surfers) et utilisé dans la plupart des\n				démos et des jeux actuels. Surement le\n				meilleur dérivé de format ProTracker\n				que je connaisse. StoneTracker charge\n				les versions de 4.1A à 6.1A (la plus\n				récente à l''heure où j''écris ceci) de ce\n				format. Les instruments compressés "avec\n				pertes" avec la méthode Fibonacci Delta\n				(option de la version 6.x) sont bien entendu\n				reconnus et décompressés.\n\n\nProRunner 1.0/2.0		Un dérivé du format ProTracker avec les\n				patterns compressées, créé par Cosmos/Sanity\n				et logiquement utilisé dans la plupart des\n				démos de son groupe. Il existe deux versions\n				de ce format totalement différentes, les\n				deux sont importées.\n\n\nNoisePacker 2.0/3.0		Un dérivé de format ProTracker avec les\n				patterns compressées.\n\n				4 voix, 31 instruments, pas de multisong,\n				jusqu''à 128 positions, patterns séparées\n				pour chaque voix, jusqu''à 256 patterns,\n				longueur fixe de 64 lignes par pattern.\n\n				Créé par Twins/Phenomena, le premier, je\n				crois, format ProTracker compressé et\n				certainement un des plus répandus dans les\n				jeux et les démos jusqu''il y a deux ans.\n			\n\nUnicTracker 1.0/2.0		Un dérivé de format ProTracker avec les\n				patterns compressées.\n\n				4 voix, 31 instruments, pas de multisong,\n				jusqu''à 128 positions, pas de patterns\n				séparées pour chaque voix, jusqu''à 64\n				patterns globales, longueur fixe de 64\n				lignes par pattern.\n\n				Créé par Laxity/Kefrens et utilisé dans\n				les démos de son groupe. Il existe deux\n				versions de ce format, les deux sont\n				importées.\n\n\nChannelPlayer			Un dérivé de format ProTracker avec les\n				patterns compressées.\n\n				4 voix, 31 instruments, pas de multisong,\n				jusqu''à 128 positions, patterns séparées\n				pour chaque voix, jusqu''à 64 KO de patterns,\n				longueur fixe de 64 lignes par pattern.\n\n				Créé par Alain Guyet, à ma connaissance, il\n				n''a été utilisé que pour les excellentes\n			        musiques du jeu "Fury of the Furies" de\n			        Frederic Motte (Moby). Ce format est un\n				des "compresseurs de modules ProTracker" les\n				plus intelligemment écrits qu''il m''ait été\n				donné d''étudier.\n\n\nKrisTracker			Un dérivé de format ProTracker avec les\n				patterns compressées.\n\n				4 voix, 31 instruments, pas de multisong,\n				jusqu''à 128 positions, patterns séparées\n				pour chaque voix, jusqu''à 256 patterns,\n				longueur fixe de 64 lignes par pattern.\n\n				Créé par un illustre inconnu, je n''ai\n				rencontré ce format que pour les modules de\n				4-Mat/Anarchy (ou Matthew Simmonds de Core\n				Design, ce qui est la même personne). Les\n				musiques de Chuck Rock, Car V-Up ou de\n				Madness II par exemple sont dans ce format.\n\n\nSkyTracker			Le format d''un clone de ProTracker.\n\n				4 voix, 31 instruments, pas de multisong,\n				jusqu''à 256 positions, patterns séparées\n				pour chaque voix, jusqu''à 256 patterns,\n				longueur fixe de 64 lignes par pattern.\n\n				Créé par Mr.Bluesky/Drifters et utilisé\n				dans les démos de son groupe.\n@endnode\n\n@node Externals "Programmes externes"\n \n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n  Trois programmes destinés à jouer des musiques StoneTracker "en dehors" de\n  celui-ci vous sont fournis. Ils ont été écrits dans un souci d''ouverture\n  du programme.\n\n  @{"DeliStone  ", link DeliStone}  Player pour DeliTracker\n  @{"EagleStone ", link EagleStone}  Player pour EaglePlayer\n  @{"PlayStone  ", link PlayStone}  Player indépendant\n  @{"Notes      ", link ExtNotes}  Notes communes\n@endnode\n\n@node DeliStone "DeliStone"\n \n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n  Comme son nom l''indique, DeliStone permet à l''excellent player de musiques\n  "DeliTracker" de Peter Kunath & Frank Riffel (dont la version 2.14 est\n  actuellement disponible sur Aminet) de jouer les musiques au format\n  StoneTracker. DeliTracker est en effet très ouvert et permet à qui le\n  veut bien de lui faire connaitre d''autre formats de musique, c''est ce que\n  fait DeliStone pour le format StoneTracker. Il suffit de le placer dans le\n  sous-répertoire "DeliPlayers" de DeliTracker pour que tout module au format\n  StoneTracker soit reconnu la prochaine fois que vous lancerez DeliTracker.\n  Si vous avez installé StoneTracker sur votre disque dur avec notre script\n  d''installation, celui-ci vous aura de toute manière dêja proposé\n  d''installer DeliStone.\n\n  NOTE : DeliStone nécessite la version 2.0 minimum de DeliTracker.\n@endnode\n\n@node EagleStone "EagleStone"\n \n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n  Ce programme est au non moins sympathique player "EaglePlayer" d''Henryk\n  Richter et Jan Blumenthal (également disponible sur Aminet) ce que DeliStone\n  est à DeliTracker. Il permet en effet à EaglePlayer de reconnaitre les\n  musiques au format StoneTracker. Il vous suffit de le placer dans le\n  répertoire "EaglePlayers" d''EaglePlayer et le tour sera joué, si cela n''a\n  pas dêja été fait par le script d''installation du StoneTracker sur votre\n  disque dur.\n\n  NOTE : Si vous utilisez l''option "EP-Batch" des dernières versions\n         d''EaglePlayer (reconnaissance des types de modules par leur nom\n         pour ne pas garder tous les players en mémoire), soit mettez à jour\n         le fichier de reconnaissance des formats, en rajoutant une ligne\n	 du type "SPM.* = EaglePlayers/EagleStone" dans le fichier\n         EaglePlayers.Batch qui doit se trouver dans le répertoire ENVARC:,\n         soit désactivez l''option.\n@endnode\n\n@node PlayStone "PlayStone"\n \n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n  Pour ceux qui ne possèdent ni DeliTracker ni EaglePlayer (si vous écoutez\n  souvent des modules, peut-être devriez vous penser à vous en procurer un des\n  deux), PlayStone est un petit programme tout à fait indépendant qui permet\n  de rejouer des musiques au format StoneTracker. Il dispose d''une interface\n  graphique GadTools simple mais complète. Pour un maximum de convivialité, il\n  est déclaré au système en tant que commodité, peut donc être contrôlé par le\n  programme "Exchange" du WorkBench et possède sa propre séquence de touches\n  d''appel (HotKey).\n\n  Sa syntaxe d''appel par le Shell est la suivante :\n\n  PlayStone FILE,PUBSCREEN/K,QUIT/S,CX_POPUP/K,CX_PRIORITY/N/K,CX_POPKEY/K\n\n  [FILE]=fichier\n\n    vous pouvez passer le nom d''un module (avec le chemin complet) à\n    PlayStone, celui-ci tentera de le charger et de le jouer dès le démarrage.\n    si aucun nom de module n''est précisé, PlayStone ne jouera aucun module à\n    son démarrage et attendra simplement que vous en sélectionnez un. Cette\n    option est prévue surtout pour les utilisateurs de programmes type\n    DirectoryOpus où vous pourrez détecter un module StoneTracker et lancer\n    PlayStone avec son nom lorsque vous double-clickez dessus, par exemple.\n    Le mot-clé "FILE" devant le nom n''est pas obligatoire.\n\n    NOTE: si PlayStone est dêja lancé et en train de jouer un module, le\n          nouveau nom de module lui sera communiqué et il tentera de le\n	  charger et de le jouer.\n\n  PUBSCREEN=nom_écran_public\n\n    par défaut, PlayStone s''ouvre sur l''écran du WorkBench. Si vous désirez\n    l''ouvrir sur un autre écran public (exemple tout à fait au hasard,\n    DOPUS.1), il suffit de donner son nom à PlayStone.\n\n  QUIT\n\n    si ce mot est présent dans la ligne de commande, il "suicidera" une\n    autre tâche PlayStone en train de jouer un module (même effet que de\n    sélectionner l''option "Quitter" du menu).\n\n  CX_POPUP=[YES|NO]\n\n    indique à PlayStone s''il doit ouvrir sa fenètre au démarrage ou non.\n    par défaut ou si "CX_POPUP=YES" est précisé, il le fera. si\n    "CX_POPUP=NO" est présent dans la ligne de commande, la fenètre ne\n    sera pas ouverte dès le démarrage.\n\n  CX_PRIORITY=priorité\n\n    permet de définir la priorité d''installation de la séquence de touches\n    d''appel du programme ("HotKey") (voir ci dessous). si deux programmes\n    utilisent la même séquence, le système la transmet au programme qui a\n    la plus haute priorité. cette option permet donc de choisir si ce sera\n    PlayStone où un autre programme utilisant la même séquence qui sera\n    appelé. La priorité varie entre -128 (la plus basse) et +127 (la plus\n    haute).\n\n  CX_POPKEY=touche\n\n    par défaut, PlayStone fait alternativement apparaitre et disparaitre sa\n    fenètre lorsque les touches control, alt et p sont pressées\n    simultanément. une autre combinaison de touches peut être choisie en la\n    précisant sous forme de texte au format standard des commodités\n    (exemples: "control alt p", "help", "shift x", "shift alt z", etc.)\n\n\n  Pour l''appel par le WorkBench, PlayStone gère les ToolTypes PUBSCREEN,\n  CX_POPUP, CX_PRIORITY et CX_POPKEY qui fonctionnent comme les paramètres\n  de la ligne de commande décrits ci-dessus.\n\n\n  Une fois PlayStone lancé, l''interface se présente ainsi :\n\n\n    	    Fichier [xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx] [*]\n	     Module [xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx]\n	       Song [xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx]\n\n            [ < ][<<][ Play ][>>][ > ][ || ][Stop][Eject]\n\n\n  Fichier : indique et permet de choisir le fichier contenant le module à\n            jouer. Vous pouvez soit entrer son nom directement dans la case\n            à droite de Fichier, soit cliquer sur le ''getfile'' à droite de\n	    cette case pour le sélectionner à l''aide d''une requète. Vous\n            devez comme sous StoneTracker sélectionner le fichier "SPM" du\n            module.\n\n  Module :  lorsqu''un module est chargé, indique son nom véritable (le même\n            que sous StoneTracker).\n\n  Song :    lorsqu''un module est chargé et qu''une song est jouée, indique son\n            nom (le même que sous StoneTracker).\n\n  Boutons type platine CD :\n\n	  <	  saute à la song précédente\n	  <<	  saute d''une position en arrière\n	  Play	  démarre la musique\n	  >>	  saute d''une position en avant\n	  >	  saute à la song suivante\n	  ||	  Pause\n	  Stop	  stoppe la musique\n	  Eject   éjecte la musique de la mémoire.\n\n  Notez que les mêmes commandes vous sont proposées dans un menu déroulant,\n  pour ceux qui préfèrent. A ce propos, comme toute commodité, le fait de\n  fermer la fenètre ne quitte pas la programme, la fenètre disparait et\n  un module éventuellement chargé continue d''être joué. Pour quitter\n  réellement le programme, il faut sélectionner l''option "Quitter" du menu\n  (si un module était joué, il sera éjecté automatiquement avant que le\n  programme ne quitte).\n\n  Notez également que, comme le StoneTracker, la bibliothèque de requètes\n  reqtools.library de Nico François doit se trouver dans LIBS: ou dans le même\n  répertoire que PlayStone pour que le programme fonctionne.\n\n  Notez pour finir que la fenètre de PlayStone est déclarée comme une\n  "AppWindow" et que, par conséquent, si vous travaillez sous WorkBench, vous\n  pouvez "lâcher" une icône de module StoneTracker sur la fenètre, PlayStone\n  le chargera et le jouera automatiquement.\n@endnode\n\n@node ExtNotes "Notes communes"\n \n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n  . Les players utilisent tout comme le StoneTracker les bibliothèques\n    stoneplayer.library et stonepacker.library qui contient respectivement\n    les routines sonores du StoneTracker et les routines de compression et\n    décompression de banques d''instruments. Elle doit donc se trouver\n    impérativement dans LIBS: ou dans le même répertoire que le programme\n    concerné (DeliTracker, EaglePlayer ou PlayStone). Rappelez-vous également\n    qu''elles nécessitent un processeur 68020 au minimum.\n\n  . Comme sur StoneTracker, les deux fichiers (partition et banque\n    d''instruments) doivent commencer respectivement par "SPM." et "SPS." et\n    se terminer par le même nom. Les trois programmes chargent les musiques\n    de cette manière.\n\n  . Les banques d''instruments compressées sont bien entendu gérées par les\n    trois programmes. Notez que cela ne nécessite pas de mémoire\n    supplémentaire.\n@endnode\n\n\n@node "Appendix" "Annexe"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n  Ce chapitre vous permet d''accéder directement aux notions importantes à\n  connaitre pour utiliser pleinement le StoneTracker, en particulier si vous\n  n''ètes pas familier de ce type de programme.\n\n\n  @{"Lexique               ", link Dico}  Terminologie du StoneTracker\n  @{"Raccourcis clavier    ", link Keyboard}  Raccourcis clavier utilisés sous l''éditeur\n  @{"Notation Américaine   ", link USANotes}  Tableau des notes en notation Américaine\n  @{"Notation hexadécimale ", link Hexa}  Explication de la base héxadécimale\n  @{"Notation binaire      ", link Binary}  Explication de la base binaire\n  @{"Généralités           ", link EffectGeneral}  Généralités sur les effets\n  @{"Effets                ", link FX}  Explication des effets du StoneTracker\n\n@endnode\n\n@node "FX" "Les effets"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nLe StoneTracker connait une cinquantaine de commandes. Elles sont numérotées\n(en @{"hexadécimal" link HEXA}) de 00 a 33. La zone de 00 à 1F est compatible avec celle de\nProTracker, cependant, les effets de type ''Exy'' ont été convertis en ''1x0y''.\nPour l''utilisation du multi-effet, reporter vous à la @{"généralités", link EffectGeneral}\nsur les effets.\n\n\n     Commande		Effet\n\n	00	@{"Arpeggio               " link "Arpeggio"}\n	01	@{"Portamento Up          " link "Portamento Up"}\n	02	@{"Portamento Down        " link "Portamento Down"}\n	03	@{"Tone Portamento        " link "Tone Portamento"}\n	04	@{"Vibrato                " link "Vibrato"}\n	05	@{"Tone + Vol Slide       " link "Tone + Vol Slide"}\n	06	@{"Vib + Vol Slide        " link "Vib + Vol Slide"}\n	07	@{"Tremolo                " link "Tremolo"}\n	08\n	09	@{"Sample Offset          " link "Sample Offset"}\n	0A	@{"Vol Slide              " link "Vol Slide"}\n	0B	@{"Position Jump          " link "Position Jump"}\n	0C	@{"Set Volume             " link "Set Volume"}\n	0D	@{"Break Position         " link "Break Position"}\n	0E	@{"Set Note               " link "Set Note"}\n	0F	@{"Set Speed              " link "Set Speed"}\n	10	@{"Set Filter             " link "Set Filter"}\n	11	@{"Fine Slide Up          " link "Fine Slide Up"}\n	12	@{"Fine Slide Down        " link "Fine Slide Down"}\n	13	@{"Glissando CTRL         " link "Glissando CTRL"}\n	14	@{"Vib WaveForm           " link "Vib WaveForm"}\n	15	@{"SetFineTune            " link "SetFineTune"}\n	16	@{"Loop CTRL              " link "Loop CTRL"}\n	17	@{"Tre WaveForm           " link "Tre WaveForm"}\n	18\n	19	@{"Retrig Note            " link "Retrig Note"}\n	1A	@{"FineVolUp              " link "FineVolUp"}\n	1B	@{"FineVolDown            " link "FineVolDown"}\n	1C	@{"Note Cut               " link "Note Cut"}\n	1D	@{"Note Delay             " link "Note Delay"}\n	1E	@{"Position Delay         " link "Position Delay"}\n	1F\n	20	@{"Set Dest Voice         " link "Set Dest Voice"}\n	21	@{"On Dest Voice          " link "On Dest Voice"}\n	22	@{"Off Dest Voice         " link "Off Dest Voice"}\n	23	@{"Set Abs Volume         " link "Set Abs Volume"}\n	24	@{"Add Abs Volume         " link "Add Abs Volume"}\n	25	@{"Sub Abs Volume         " link "Sub Abs Volume"}\n	26	@{"Fine Add Abs Volume    " link "Fine Add Abs Volume"}\n	27	@{"Fine Sub Abs Volume    " link "Fine Sub Abs Volume"}\n	28	@{"ID                     " link "ID"}\n	29	@{"Jump Abs Song          " link "Jump Abs Song"}\n	2A	@{"Jump Rel Song          " link "Jump Rel Song"}\n	2B	@{"Set Jump Song Position " link "Set Jump Song Position"}\n	2C	@{"Set Jump Song Line     " link "Set Jump Song Line"}\n	2D\n	2E\n	2F\n	30	@{"Next note              " link "Next note"}\n	31	@{"Previous note          " link "Previous note"}\n	32	@{"Next note Porta        " link "Next note Porta"}\n	33	@{"Previous note Porta    " link "Previous note Porta"}\n@endnode\n\n@node "Arpeggio" "Arpeggio"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Arpeggio			 @{ub}	Effet : 00xy\n\n"Arpeggio" crée une modulation de la fréquence du sample, il fait vibrer la\nnote. Le fonctionnement est basé sur 3 temps:\n\n	- Note normale\n	- Note normale + x demi-ton(s)\n	- Note normale + y demi-ton(s)\n\nCet effet est fonction du nombre de @{"BPM" link Dico} (Battements Par Minute). L''effet\ndoit être répété à chaque ligne pour être maintenu.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "Portamento Up" "Portamento Up"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Portamento Up		 	@{ub}	Effet : 01xx\n\n"Portamento Up" permet d''augmenter la frequence de la note.\n\n	- Fréquence du sample + xx\n\nxx est une valeur hexadecimale comprise entre 0(inutile) et FF(255)\n\nCette effet est fonction du nombre de @{"BPM" link Dico} (Battements Par Minute). L''effet\ndoit être répété à chaque ligne pour être maintenu.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "Portamento Down" "Portamento Down"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Portamento Down		 @{ub}		Effet : 02xy\n\n"Portamento Down" permet de diminuer la frequence de la note.\n\n	- Fréquence du sample - xx\n\nxx est une valeur hexadecimale comprise entre 0(inutile) et FF(255)\n\nCette effet est fonction du nombre de @{"BPM" link Dico} (Battements Par Minute). L''effet\ndoit être répété à chaque ligne pour être maintenu.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "Tone Portamento" "Tone Portamento"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Tone Portamento		 @{ub}		Effet : 03xx\n\n"Tone Portamento" permet de monter progressivement à la note editée sur la\nligne courante. Celle-ci n''est donc pas considérée comme une note à jouer mais\ncomme note de destination. La vitesse de transition est définie par xx. Si xx\nest petit, la vitesse sera lente, et inversement si xx est grand, la vitesse\nsera rapide. Si xx = 00, l''ancienne vitesse est conservée.\n\nPour une transition immédiate, utilisez @{"Set Note" link "Set Note"}.\n\nCette effet est fonction du nombre de @{"BPM" link Dico} (Battements Par Minute). L''effet\ndoit être répété à chaque ligne pour être maintenu.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "Vibrato" "Vibrato"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Vibrato		 @{ub}			Effet : 04xy\n\n"Vibrato" crée une modulation de la fréquence du sample, il fait vibrer la\nnote.\n\nx définit la vitesse de la modulation. 1 pour une vitesse lente jusqu''à F pour\nune vitesse maximale.\n\ny définit le taux de modulation. 1 pour une légére modification jusqu''à F pour\nune modification maximale.\n\nLes deux paramétres sont indépendants l''un de l''autre. Si l''un des paramétres\nest à zéro, l''ancienne valeur est conservée pour ce paramétre.\n\nLa modulation peut se faire selon trois formes :\n\n	- Sinusoïdale\n	- Triangulaire\n	- Carrée\n\nLe choix de la forme de modulation est effectué par l''effet @{"Vib WaveForm" link "Vib WaveForm"}.\n\nCette commande est fonction du nombre de @{"BPM" link Dico} (Battements Par Minute). L''effet\ndoit être répété à chaque ligne pour être maintenu.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "Tone + Vol Slide" "Tone + Vol Slide"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Tone + Vol Slide		 @{ub}	Effet : 05xy\n\n"Tone + Vol Slide" combine un @{"Tone Portamento" link "Tone Portamento"} et un @{"Vol Slide" link "Vol Slide"}.\n\nLes paramètres x et y sont les paramètres du @{"Vol Slide" link "Vol Slide"}. Le @{"Tone Portamento" link "Tone Portamento"}\nn''aura aucune valeur en entrée donc il gardera son ancienne vitesse.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "Vib + Vol Slide" "Vib + Vol Slide"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Vib + Vol Slide		 @{ub}		Effet : 06xy\n\n"Vib + Vol Slide" combine un @{"Vibrato" link "Vibrato"} et un @{"Vol Slide" link "Vol Slide"}.\n\nLes paramètres x et y sont les paramètres du @{"Vol Slide" link "Vol Slide"}. Le @{"Vibrato" link "Vibrato"}\nn''aura aucune valeur en entrée donc il gardera son ancienne vitesse et\namplitude.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "Tremolo" "Tremolo"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Tremolo		 @{ub}			Effet : 07xy\n\n"Tremolo" crée une modulation du volume du sample.\n\nx définit la vitesse de la modulation. 1 pour une vitesse lente jusqu''à F\npour une vitesse maximale.\n\ny définit le taux de modulation. 1 pour une légére modification jusqu''à F\npour une modification maximale.\n\nLes deux paramétres sont indépendants l''un de l''autre. Si l''un des\nparamétres est à zéro, l''ancienne valeur est conservée pour ce paramétre.\n\nLa modulation peut se faire selon trois formes :\n\n	- Sinusoïdale\n	- Triangulaire\n	- Carrée\n\nLe choix de la forme de modulation est effectué par l''effet @{"Tre WaveForm" link "Tre WaveForm"}.\n\nCette commande est fonction du nombre de @{"BPM" link Dico} (Battements Par Minute). L''effet\ndoit être répété à chaque ligne pour être maintenu.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "Sample Offset" "Sample Offset"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Sample Offset		 @{ub}		Effet : 09xx\n\n"Sample Offset" permet de sauter les premiers octets d''un sample. Le sample\ncommencera à l''octet xx*256 (xx*100 en @{"hexadécimal" link Hexa}). Cette effet est\ninstantané et peut être cumulé pour des samples longs.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "Vol Slide" "Vol Slide"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Vol Slide		 @{ub}		Effet : 0Axy\n\n"Vol Slide" permet de faire varier le volume courant du sample. Le volume sera\naugmenté de x et diminué de y.\n\nCette effet est fonction du nombre de @{"BPM" link Dico} (Battements Par Minute). L''effet\ndoit être répété à chaque ligne pour être maintenu.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "Position Jump" "Position Jump"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Position Jump		 @{ub}		Effet : 0Bxx\n\n"Position Jump" est une instruction de saut. Le StoneTracker sautera à la\n@{"position" link Dico} xx, aprés que la ligne courante soit complétement jouée.\n\nSi plusieurs saut sont insérés sur une même ligne, un seul sera executé.\nLa priorité sera pour la voix de contrôle, puis de la voix 1 à la voix 8.\n@endnode\n\n@node "Set Volume" "Set Volume"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Set Volume		 @{ub}		Effet : 0Cxx\n\n"Set Volume" charge instantanément le volume du sample courant avec la\nvaleur xx.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "Break Position" "Break Position"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Break Position		 @{ub}		Effet : 0Dxx\n\n"Break Position" est une instruction de saut. Le StoneTracker sautera à la\nposition suivante, ligne xx, aprés que la ligne courante soit complétement\njouée.\n\nSi plusieurs saut sont insérés sur une même ligne, un seul sera executé.\nLa priorité sera pour la voix de contrôle, puis de la voix 1 à la voix 8.\n@endnode\n\n@node "Set Note" "Set Note"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Set Note		 @{ub}		Effet : 0Exx\n\n"Set Note" permet de définir la note sans relancer le sample depuis le\ndébut. Cette commande remplace le fameux ''03FF''.\nLe changement de note se fera imédiatement si xx=0, sinon le passage\ninstantané de la nouvelle note se fera dans un délai definit par\nxx. Ce delai doit être inférieur à la temporisation définie par @{"Set Speed" link "Set Speed"}.\n\n! ATTENTION ! Cette commande ne provient pas de ProTracker !\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "Set Speed" "Set Speed"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Set Speed		 @{ub}		Effet : 0Fxx\n\n"Set Speed" définit le nombre de @{"BPM" link Dico} ou le temps de pause entre chaque ligne.\n\nSi xx>31, "Set Speed" change le BPM (par défaut 125).\n\nSi xx<32, "Set Speed" change le temps de pause entre chaque ligne (défaut 6).\nPlus x est grand, plus le temps sera long.\n\nPour la valeur particuliére xx=00, le Tracker s''arrète de jouer la musique.\n\nSi cette commande est insérée plusieurs fois sur une même ligne, elles seront\ntoutes exécutées.\n@endnode\n\n@node "Set Filter" "Set Filter"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Set Filter		 @{ub}		 Effet : 100x\n			     Correspondance ProTracker :  E0x\n\n"Set Filter" définit le fonctionnement du filtre passe-bas hardware.\n\nSi x=0 le filtre est activé.\nSi x est différent de 0 le filtre est désactivé.\n\nSi cette commande est insérée plusieurs fois sur une même ligne, elles seront\ntoutes exécutées, donc seul la derniére aura un effet sur le filtre.\n@endnode\n\n@node "Fine Slide Up" "Fine Slide Up"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Fine Slide Up		 	@{ub}	Effet : 110x\n			    Correspondance ProTracker :  E1x\n\n"Fine Slide Up" a la même fonction que @{"Portamento Up" link "Portamento Up"}, mais la transition se\nfait plus lentement.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "Fine Slide Down" "Fine Slide Down"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Fine Slide Down		 @{ub}		Effet : 120x\n			    Correspondance ProTracker :  E2x\n\n"Fine Slide Down" a la même fonction que @{"Portamento Down" link "Portamento Down"}, mais la\ntransition se fait plus lentement.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "Glissando CTRL" "Glissando CTRL"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Glissando CTRL		 @{ub}		Effet : 130x\n			    Correspondance ProTracker :  E3x\n\n"Glissando CTRL" permet de definir si un @{"Tone Portamento" link "Tone Portamento"}, doit être aligné avec\ndes demi-tons. Cette fonction peut servir pour appliquer cette effet avec un\nson de piano. On imagine trés bien que le piano peut se trouver désaccordé si\ncette fonction n''est pas activée.\n\nSi x=0, la fonction est désactivée.\nSi x est différent de 0, la fonction est activée.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "Vib WaveForm" "Vib WaveForm"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Vib WaveForm		 @{ub}		Effet : 140x\n			    Correspondance ProTracker :  E4x\n\n"Vib WaveForm" sert a configurer la forme de modulation du @{"Vibrato" link "Vibrato"}.\nLes voies peuvent être configurées individuellement.\n\nLa modulation peut se faire selon trois formes :\n\n	- x = 0 : Sinusoïdale (par défaut)\n	- x = 1 : Triangulaire\n	- x = 2 : Carrée\n\nLes autres valeurs ont pour effet d''annuler toute demande de @{"Vibrato" link "Vibrato"}.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "SetFineTune" "SetFineTune"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	SetFineTune		 @{ub}		Effet : 15xx\n			    Correspondance ProTracker :  E5x\n\n"SetFineTune" definit le "Fine Tune" (accord fin) du sample courant. Sur\nProTracker, x allait de 0 à F pour un FineTune de -8 à +7. Sur le StoneTracker\ncette fonction à été étendue.\n\n\n     FineTune	   Valeur de xx  |   FineTune	   Valeur de xx\n	-16		F0	 |	-15		F1\n	-14		F2	 |	-13		F3\n	-12		F4	 |	-11		F5\n	-10		F6	 |	-09		F7\n	-08		F8	 |	-07		F9\n	-06		FA	 |	-05		FB\n	-04		FC	 |	-03		FD\n	-02		FE	 |	-01		FF\n	+00		00	 |	+01		01\n	+02		02	 |	+03		03\n	+04		04	 |	+05		05\n	+06		06	 |	+07		07\n	+08		08	 |	+09		09\n	+10		0A	 |	+11		0B\n	+12		0C	 |	+13		0D\n	+14		0E	 |	+15		0F\n\nToute autre valeur de xx sera ignorée.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "Loop CTRL" "Loop CTRL"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Loop CTRL		 @{ub}		Effet : 16xx\n			    Correspondance ProTracker :  E6x\n\n"Loop CTRL" permet d''effectuer des boucles dans la position courante.\n\nSi xx=0, la ligne courante est définie comme point de début de bouclage.\n\nSi xx est différent de 0, le Tracker bouclera xx+1 fois entre la ligne\ncourante et la ligne définie comme point de début de bouclage.\n\nSur une même voix, les "Loop CTRL" ne peuvent être emboités. S''il est\nnécessaire de faire plusieurs boucles, alors ils doivent être positionnés\nsur plusieurs voix (un par voix).\n@endnode\n\n@node "Tre WaveForm" "Tre WaveForm"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Tre WaveForm		 @{ub}		Effet : 170x\n			    Correspondance ProTracker :  E7x\n\n"Tre WaveForm" sert a configurer la forme de modulation du @{"Tremolo" link "Tremolo"}.\nLes voies peuvent être configurées individuellement.\n\nLa modulation peut se faire selon trois formes :\n\n	- x = 0 : Sinusoïdale (par défaut)\n	- x = 1 : Triangulaire\n	- x = 2 : Carrée\n\nLes autres valeurs ont pour effet d''annuler toute demande de @{"Tremolo" link "Tremolo"}.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "Retrig Note" "Retrig Note"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Retrig Note		 @{ub}		Effet : 19xx\n			    Correspondance ProTracker :  E9x\n\n"Retrig Note" permet de relancer la note plusieurs fois pendant le temps de\npause à chaque ligne.\n\nSi xx=0 l''effet est ignoré.\n\nSi xx est différent de 0, le sample sera relancé suivant la temporisation\ndéfinie par @{"Set Speed" link "Set Speed"} divisée par xx.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "FineVolUp" "FineVolUp"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	FineVolUp		@{ub}		Effet : 1Axx\n			    Correspondance ProTracker :  EAx\n\n"FineVolUp" permet d''augmenter de xx le volume du sample.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "FineVolDown" "FineVolDown"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	FineVolDown		@{ub}		Effet : 1Bxx\n			    Correspondance ProTracker :  EBx\n\n"FineVolDown" permet de diminuer de xx le volume du sample.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "Note Cut" "Note Cut"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Note Cut		@{ub}		Effet : 1Cxx\n			    Correspondance ProTracker :  ECx\n\n"Note Cut" coupe le sample courant aprés un délai defini par xx. Ce délai est\nen rapport avec la temporisaton definie par la fonction @{"Set Speed" link "Set Speed"}.\nEn réalité, la fonction force le volume du sample à zéro.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "Note Delay" "Note Delay"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Note Delay		@{ub}		Effet : 1Dxx\n			    Correspondance ProTracker :  EDx\n\n"Note Delay" permet de retarder le départ du sample. xx définit la\ntemporisation avant de lancer le sample.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "Position Delay" "Position Delay"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Position Delay		@{ub}		Effet : 1Exx\n			    Correspondance ProTracker :  EEx\n\n"Position Delay" permet de retarder la lecture de la ligne suivante. xx\ndéfinit le nombre de temporisations (@{"Set Speed" link "Set Speed"}) avant de lancer le sample.\n\nSi plusieurs délais sont insérés sur une même ligne, un seul sera executé.\nLa priorité sera pour la voix de contrôle, puis de la voix 1 à la voix 8.\n@endnode\n\n@node "Set Dest Voice" "Set Dest Voice"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Set Dest Voice		@{ub}		Effet : 20xy\n\n"Set Dest Voice" définit les voix qui seront pilotées par la voix de\ncontrôle (voix FX).\n\nxy est défini en @{"binaire" link Binary} de la manière suivante :\n\n	Bit 7	Bit 6	Bit 5	Bit 4	Bit 3	Bit 2	Bit 1	Bit 0\n	Voix1	Voix2	Voix3	Voix4	Voix5	Voix6	Voix7	Voix8\n	  |       |       |       |	  |	  |	  |	  |\n           \____  |       |  ____/	   \____  |	  |  ____/\n	        \__\_   _/__/                   \__\_   _/__/\n                   \ \ / /                         \ \ / /\n                      x	                              y\n\nCette fonction n''est utilisable que dans la voix Fx.\n@endnode\n\n@node "On Dest Voice" "On Dest Voice"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	On Dest Voice		@{ub}		Effet : 21xy\n\n"On Dest Voice" permet d''ajouter les voix selectionnées dans xy aux voix qui\nseront pilotées par la voix de contrôle (voix FX).\n\nxy est défini en @{"binaire" link Binary} de la manière suivante :\n\n	Bit 7	Bit 6	Bit 5	Bit 4	Bit 3	Bit 2	Bit 1	Bit 0\n	Voix1	Voix2	Voix3	Voix4	Voix5	Voix6	Voix7	Voix8\n	  |       |       |       |	  |	  |	  |	  |\n           \____  |       |  ____/	   \____  |	  |  ____/\n	        \__\_   _/__/                   \__\_   _/__/\n                   \ \ / /                         \ \ / /\n                      x	                              y\n\nCette fonction n''est utilisable que dans la voix Fx.\n@endnode\n\n@node "Off Dest Voice" "Off Dest Voice"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Off Dest Voice		@{ub}		Effet : 22xx\n\n"Off Dest Voice" permet de retirer les voix selectionnées dans xy des voix qui\nseront pilotées par la voix de contrôle (voix FX).\n\nxy est défini en @{"binaire" link Binary"} de la manière suivante :\n\n	Bit 7	Bit 6	Bit 5	Bit 4	Bit 3	Bit 2	Bit 1	Bit 0\n	Voix1	Voix2	Voix3	Voix4	Voix5	Voix6	Voix7	Voix8\n	  |       |       |       |	  |	  |	  |	  |\n           \____  |       |  ____/	   \____  |	  |  ____/\n	        \__\_   _/__/                   \__\_   _/__/\n                   \ \ / /                         \ \ / /\n                      x	                              y\n\nCette fonction n''est utilisable que dans la voix Fx.\n@endnode\n\n@node "Set Abs Volume" "Set Abs Volume"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Set Abs Volume		@{ub}		Effet : 23xx\n\n"Set Abs Volume" définit avec xx le volume absolu de la voix courante.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "Add Abs Volume" "Add Abs Volume"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Add Abs Volume		@{ub}		Effet : 24xx\n\n"Add Abs Volume" augmente le volume absolu de la voix courante.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "Sub Abs Volume" "Sub Abs Volume"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Sub Abs Volume		@{ub}		Effet : 25xx\n\n"Sub Abs Volume" diminue le volume absolu de la voix courante.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "Fine Add Abs Volume" "Fine Add Abs Volume"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Fine Add Abs Volume	@{ub}		Effet : 26xx\n\n"Fine Add Abs Volume" augmente de xx le volume absolu de la voix courante.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "Fine Sub Abs Volume" "Fine Sub Abs Volume"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Fine Sub Abs Volume	@{ub}		Effet : 27xx\n\n"Fine Sub Abs Volume" diminue de xx le volume absolu de la voix courante.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "ID" "ID"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	ID			@{ub}		Effet : 28xx\n\nCette fonction n''est pas utile au musiciens. Elle permet de synchroniser la\nmusique avec des évènements extérieurs. Lorsque le player rencontre cette\nfonction, il appelle un vecteur définit par le programmeur.\n\nVoir la section @{"Développeurs" link Devel}.\n@endnode\n\n@node "Jump Abs Song" "Jump Abs Song"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Jump Abs Song		@{ub}		Effet : 29xx\n\n"Jump Abs Song" crée un saut a la song xx. Par défaut, le player sautera à\nla ligne 0 et position 0.\nPour paramétrer cela, voir @{"Set Jump Song Position " link "Set Jump Song Position"}\net @{"Set Jump Song Line" link "Set Jump Song Line"}.\n@endnode\n\n@node "Jump Rel Song" "Jump Rel Song"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Jump Rel Song		@{ub}		Effet : 2Axx\n\n"Jump Rel Song" crée un saut a la song (xx+numéro de song courante).\nPar exemple si vous êtes à la song 3 est que le player rencontre 2A01.\nLe player sautera donc à la song 3+1=4.\nPar défaut, le player sautera à la ligne 0 et position 0.\nPour paramétrer cela, voir @{"Set Jump Song Position " link "Set Jump Song Position"}\net @{"Set Jump Song Line" link "Set Jump Song Line"}.\n@endnode\n\n@node "Set Jump Song Position" "Set Jump Song Position"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Set Jump Song Position	@{ub}		Effet : 2Bxx\n\nPermet de définir quelle sera la position de départ pour le prochain\nchangement de song.\nLors d''un changement de song, la valeur est réinitalisé a 0.\n@endnode\n\n@node "Set Jump Song Line" "Set Jump Song Line"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Set Jump Song Line	@{ub}		Effet : 2Cxx\n\nPermet de définir quelle sera la ligne de départ pour le prochain\nchangement de song.\nLors d''un changement de song, la valeur est réinitalisé a 0.\n@endnode\n\n@node "Next note" "Next note"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Next note		@{ub}		Effet : 30xx\n\nPermet de jouer la note suivante de la gamme.\n\nLe changement de note se fera imédiatement si xx=0, sinon le passage\ninstantané à la nouvelle note se fera dans un délai definit par\nxx. Ce delai doit être inférieur à la temporisation définie par @{"Set Speed" link "Set Speed"}.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "Previous note" "Previous note"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Previous note		@{ub}		Effet : 31xx\n\nPermet de jouer la note précédente de la gamme.\n\nLe changement de note se fera imédiatement si xx=0, sinon le passage\ninstantané à la nouvelle note se fera dans un délai definit par\nxx. Ce delai doit être inférieur à la temporisation définie par @{"Set Speed" link "Set Speed"}.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "Next note Porta" "Next note Porta"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Next note Porta		@{ub}		Effet : 32xx\n\nCrée un @{"Tone Portamento" link "Tone Portamento"} avec la note suivante de\nla gamme.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "Previous note Porta" "Previous note Porta"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n@{b}	Previous note Porta	@{ub}		Effet : 33xx\n\nCrée un @{"Tone Portamento" link "Tone Portamento"} avec la note précédente de\nla gamme.\n\nSi cette commande est appliquée sur la voix de contrôle, toutes les voix\nsélectionnées par les commandes suivantes seront affectées.\n	20	@{"Set Dest Voice" link "Set Dest Voice"}\n	21	@{"On Dest Voice " link "On Dest Voice"}\n	22	@{"Off Dest Voice" link "Off Dest Voice"}\n@endnode\n\n@node "EffectGeneral" "Généralités sur les effets"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n	Le multieffet du StoneTracker vous permet de façon très simple de\ncomposer des musiques avec beaucoup d''effets sonores. Seulement, il existe\ndes subtilités qu''il est preférable de connaître pour éviter des mauvaises\nsurprises sur le rendu final.\n\n\n@{b}	Commandes de modification générale	@{ub}\n\n	0D	@{"Break Position         " link "Break Position"}\n	0F	@{"Set Speed              " link "Set Speed"}\n	16	@{"Loop CTRL              " link "Loop CTRL"}\n	1E	@{"Position Delay         " link "Position Delay"}\n	20	@{"Set Dest Voice         " link "Set Dest Voice"}\n	21	@{"On Dest Voice          " link "On Dest Voice"}\n	22	@{"Off Dest Voice         " link "Off Dest Voice"}\n	23	@{"Set Abs Volume         " link "Set Abs Volume"}\n	24	@{"Add Abs Volume         " link "Add Abs Volume"}\n	25	@{"Sub Abs Volume         " link "Sub Abs Volume"}\n	26	@{"Fine Add Abs Volume    " link "Fine Add Abs Volume"}\n	27	@{"Fine Sub Abs Volume    " link "Fine Sub Abs Volume"}\n	28	@{"ID                     " link "ID"}\n	29	@{"Jump Abs Song          " link "Jump Abs Song"}\n	2A	@{"Jump Rel Song          " link "Jump Rel Song"}\n	2B	@{"Set Jump Song Position " link "Set Jump Song Position"}\n	2C	@{"Set Jump Song Line     " link "Set Jump Song Line"}\n\nCes commandes sont des commandes de configuration générale de la musique.\nExceptées les commandes de 20 à 22, elles peuvent être positionnées ou l''on\nveut, dans la voix FX comme dans une voix musicale de 1 à 8. Cependant, il\nest préférable de les installer dans la voix FX dédiée à cette effet. Ainsi\nvos patterns seront propres, est pourront, par exemple, être réutilisables\nplus tard dans une autre song mais avec une temporisation différente.\nCes commandes seront toujours exécutées quelles que soient les voix adressées\npar la voix FX. Pour de plus amples renseignements voir @{"ici", link FxVoice}.\n\n\n@{b}	Commandes de saut	@{ub}\n\n	0B	@{"Position Jump          " link "Position Jump"}\n	0D	@{"Break Position         " link "Break Position"}\n	16	@{"Loop CTRL              " link "Loop CTRL"}\n	29	@{"Jump Abs Song          " link "Jump Abs Song"}\n	2A	@{"Jump Rel Song          " link "Jump Rel Song"}\n\nL''ordre de lecture de ces effets est le suivant :\n\nVoix FX, Voix 1, Voix 2, Voix 3, Voix 4, Voix 5, Voix 6, Voix 7, Voix 8.\n\nLorsque le tracker rencontre sur une même ligne les commandes précédentes,\nseule la première commande rencontrée sera exécutée.\n	\n\n@{b}	Commandes de portamento	@{ub}\n\n	03	@{"Tone Portamento        " link "Tone Portamento"}\n	05	@{"Tone + Vol Slide       " link "Tone + Vol Slide"}\n	0E	@{"Set Note               " link "Set Note"}\n	32	@{"Next note Porta        " link "Next note Porta"}\n	33	@{"Previous note Porta    " link "Previous note Porta"}\n\nSur une même voix, une seule de ces commandes peut être insérée.\nAttention! Si une de ces commandes est insérée sur la voix FX, toutes les voix\nsélectionnées par les commandes de 20 à 22 seront alors affectées par cette\ncommande.\n\n\n@{b}	Commandes de contrôle du volume	@{ub}\n\n	23	@{"Set Abs Volume         " link "Set Abs Volume"}\n	24	@{"Add Abs Volume         " link "Add Abs Volume"}\n	25	@{"Sub Abs Volume         " link "Sub Abs Volume"}\n	26	@{"Fine Add Abs Volume    " link "Fine Add Abs Volume"}\n	27	@{"Fine Sub Abs Volume    " link "Fine Sub Abs Volume"}\n\nCes commandes permettent de contrôler le volume de chaque voix.\nCe volume n''est pas à confondre avec le volume du sample appliqué sur la\ndite voix.\n\nEn résumé, vous avez à votre disposition deux volumes:\n - celui du sample qui est contrôlé par les commandes habituelles à Protracker\n - celui de la voix qui est contrôlé par les commandes indiquées précedemment\n\nSi ces commandes sont appliquées sur une voix autre que FX, elles\nn''affecteront que la voix en question.\n\nSi ces commandes sont appliquées sur la voix FX, alors elles affecteront\ntoutes les voix sélectionnées par les commandes de 20 à 22.\n\nElles peuvent servir, par exemple, si elles sont appliquées sur la voix FX,\nà descendre le volume général de la musique tout en utilisant des patterns\ndéjà utilisées précédemment mais avec un volume différent.\n@endnode\n\n@node "Specs" "Particularités du Stone"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nBeaucoup d''entre vous connaissent dêjà le fameux Protracker, avec lequel\nbeaucoup de musiciens ont trouvé leur inspiration.\nAvec le StoneTracker, vous disposez, en plus des capacités de Protracker,\nde beaucoup d''autres avantages.\n\nEn premier lieu, ce qui est le plus visible est l''extension de 4 à 8 voix.\nAinsi, il est possible de choisir pour une song le nombre de voix désirées\nentre 4, 5, 6, 7 ou 8. Pour plus de détails regarder @{"ici", link VoicesMix}.\n\nIl est désormais possible de créer plusieurs musiques dans un même module ou\nd''utiliser une pattern par voix. Pour plus de détails regarder @{"ici", link MultiSong}.\n\nSous Protracker, lorsque vous vouliez modifier le volume de départ d''un\nsample vous utilisiez la commande ''Cxx''. Mais si vous vouliez diminuer\nprogressivement ce volume, vous deviez utiliser la ligne suivante.\nDésormais, vous pouvez insérer jusqu''à 7 commandes par ligne par voix.\nPour plus de détails regarder @{"ici", link MultiEffect}.\n\nEn plus des propriétés précédentes, il existe dans le StoneTracker une voix\nappelée voix Fx ou voix de contrôle. Elle permet d''appliquer des effets sur la\ntotalité de la song. Pour plus de détails regarder @{"ici", link FxVoice}.\n\nLa limitation du hardware de l''Amiga faisait qu''il était impossible, sans\nune gestion plus poussée, de jouer un sample de plus de 128Ko. StoneTracker\nvous donne la possibilité d''utiliser la taille de sample que vous désirez.\nLa seule limitation est la taille de la mémoire de votre machine. De plus,\nsuivant votre @{configuration link "InterConfig"} du StoneTracker, il est possible\nd''utiliser la mémoire ''Fast'' pour l''installation des samples.\n\n@endnode\n\n@node "VoicesMix" "8 voix et mixage des voix"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nSur Protracker, l''ordre des voix est le suivant: Gauche Droite Droite Gauche\nPour ne pas contredire cette règle, les voix supplémentaires sont dans le même\nordre, ce qui donne :\n\n	Gauche Droite Droite Gauche  Gauche Droite Droite Gauche\n\nIl faut savoir que l''Amiga ne pouvant restituer que 4 sons simultanément,\nles voix supplémentaires sont mixées entre elles.\n\nAinsi pour un mode 8 voix, la configuration est la suivante :\n\n- Les voix 1 et 2 sont restituées par l''Amiga.\n- La voix 3 est mixée à partir de 6 voix avec la voix 6, et avec les voix 6\n  et 7 à partir de 7 voix.\n- La voix 4 est mixée à partir de 5 voix avec la voix 5, et avec les voix 5\n  et 8 en mode 8 voix.\n\nLes voix calculées peuvent avoir un rendu plus nasillard que les voix\nrestituées par l''Amiga. Ceci est la conséquence de la perte d''harmoniques\ndues au mixage, plus ou moins importante selon sa fréquence.\n\nLe mixage des voix est plus ou moins bon suivant la fréquence utilisée.\nA partir de 5 voix, vous pouvez modifier la fréquence de mixage grâce au\nslider "Fréquence" en haut à droite de l''écran du StoneTracker. Pour une\nbonne qualité, il est préférable de choisir une fréquence supérieure à\n20 KHz.\n\nLa capacité de mixage est proportionnelle à la machine que vous utilisez. Si\nvous possédez un Amiga 1200 sans extension mémoire, la fréquence de\nrestitution maximale sera à peu près de 20 KHz. Pour un Amiga 4000 ou un\nAmiga 1200 avec carte accélératrice, la fréquence de restitution pourra\nmonter jusqu''a 50 KHz.\n\nLa fréquence maximale possible dépend aussi du moniteur que vous utilisez.\nSur un moniteur ''classique'' 50 Hz, la fréquence maximale est de 28 KHz.\nSur un moniteur VGA, multisync, etc., la fréquence maximale est de 50 KHz.\nPour ceux qui ne voient pas le rapport entre la vidéo et le son, sachez que\nl''Amiga ne peut lire une donnée sonore qu''en début de chaque ligne vidéo.\nAinsi plus la vitesse d''affichage est grande, plus vous pouvez sortir de\ndonnées sonores par seconde.\n@endnode\n\n@node MultiSong "Multi-song et une pattern par voix ..."\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nLe StoneTracker possède une gestion de modules contenant plusieurs songs.\nCela permet de créer des environnements sonores interactifs en utilisant\nl''enchainement automatique des songs.\n\nUne pattern pour le Protracker est un tableau contenant les notes à jouer\npour toutes les voix. Ce tableau peut ainsi être appelé plusieurs fois dans\nune même song. A chaque position est attribuée une pattern.\n\nSur le StoneTracker, une pattern désigne un tableau contenant les notes\npour une seul voix. Ainsi lorsque vous créez une song, il est nécessaire\nd''indiquer une pattern par voix, par position.\n\nCela vous permet, par exemple, de définir un rythme sur une pattern est de\nl''utiliser sur plusieurs positions ou de le changer de voix (gauche ou\ndroite). Cela permet de gagner de la place en mémoire.\n\nLa taille, indiquée par le StoneTracker, que prennent les patterns en mémoire\nest une indication sur la taille décompressée des patterns en mémoire. Lorsque\nle module est sauvegardé, les patterns sont compressées mais utilisables\ndirectement par un player Stone externe.\n\nDe plus, il vous est possible de définir la taille, en nombre de lignes, des\npatterns. Ce changement s''applique à toutes les patterns en mémoire.\n@endnode\n\n@node MultiEffect "Multi-effets ..."\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nLe format d''une ligne d''une pattern est le suivant:\n\n	Note  Sample  Eff1   Eff2   Eff3   Eff4   Eff5   Eff6   Eff7\n\n	C#3     05    0C40   0A03   0434   090F   0000   0000   0000\n\nSur chaque ligne, il est possible d''insérer une note, un numéro de sample et\njusqu''à 7 effets. Ces effets seront lus de gauche à droite.\n\nDans cette exemple, le sample 5 est joué avec un DO de l''octave 3, en\nutilisant les effets suivants:\n\n	- Positionne le volume de départ du sample à 40\n	- Descend le volume progressivement par pas de 3\n	- Applique un vibrato de vitesse 3 et d''amplitude 4\n	- Coupe le début du sample de $F*$100 = $F00 ou 3840 octets\n\nSous l''interface du StoneTracker, vous ne verrez qu''un seul effet à la fois\n sur chaque voix. En choisissant la fonction ''Cmd Edit'', vous pourrez éditer\ntous les effets d''une ligne de la voix courante où est positionné le curseur.\n\nBien qu''un seul effet ne soit visible à la fois, un souligné apparait sur la\nligne courante pour vous indiquer qu''un effet est appliqué sur la droite ou\nla gauche de l''effet courant. Vous pouvez aussi utiliser les commandes\n''Cmd Suiv'' et ''Cmd Prev'' (ou leur équivalent au @{"clavier" link Keyboard}) pour faire défiler\ntous les effets.\n\nPour l''exemple précédent, si la voix visualise l''effet 4, l''affichage sera\nle suivant:\n		| C#3 05 @{u}0@{uu}90F |\n\nPour plus de reseignements consernant le multieffet, reportez-vous aux\n@{"généralités", link EffectGeneral} sur les effets.\n@endnode\n\n@node FxVoice "Voix de contrôle"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nLa voix FX possède ses propres patterns, car contrairement aux autres voix,\nla voix FX ne joue aucun son. Elle ne peut contenir des notes ou des numéros\nde samples mais possède 8 emplacements pour des commandes qui seront appliquées\nsur les voix sélectionnées.\n\nAinsi, sans changer les patterns d''une musique, vous pouvez appliquer un\nvibrato ou changer le volume d''une voix.\n\nPour sélectionner sur quelles voix seront appliqués les effets, il existe\ntrois commandes à votre disposition :\n\n	20	@{"Set Dest Voice         " link "Set Dest Voice"}\n	21	@{"On Dest Voice          " link "On Dest Voice"}\n	22	@{"Off Dest Voice         " link "Off Dest Voice"}\n\nExemple:\n\n	Eff1	Eff2	Eff3	Eff4	Eff5	Eff6	Eff7	Eff8\n	2003	0432	21F0	0A02	2203	0101	0F03	0000\n\n- La commande 1 n''autorise la modification que sur les voix 7 et 8.\n- Crée un @{"Vibrato" link "Vibrato"} sur les voix 7 et 8 comme si la commande avait été\n  appliquée sur ses voix.\n- La commande 3 active l''adressage sur les voix de 1 à 4. Ainsi les voix\n  concernées par la voix de contrôle sont 1,2,3,4,7 et 8.\n- Diminue progressivement le volume des samples sur les 6 voix concernées.\n- La commande 4 désactive l''adressage pour les voix 7 et 8. Seules les voix\n  de 1 à 4 sont concernées par la voix de contrôle.\n- Applique un @{"Portamento Up" link "Portamento Up"} sur les voix de 1 à 4.\n- La commande 7 change la vitesse de lecture des patterns.\n\nCette dernière commande fait partie d''une liste de commandes qui seront\ntoujours executées quelles que soient les voix addressées par la voix FX.\nPour plus d''informations voir @{"ici", Link EffectGeneral}.\n@endnode\n\n\n@Node InterPosNum "Numéro de la position courante"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nIndique/Change le numéro de position dans la song courante.\n\nEn utilisant le bouton droit de la souris, une fenêtre s''ouvrira où vous\npourrait choisir à quel position vous désirez aller.\n@EndNode\n\n@Node InterPattNum "Numéro de la pattern"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nNuméro de la pattern affectée à la voix située en dessous pour la\nposition courante.\n\nEn utilisant le bouton droit de la souris, une fenêtre s''ouvrira où vous\npourrait choisir quelle pattern vous désirez affecter à la voix, pour la\nposition courante.\n@EndNode\n\n@Node InterFxPattNum "Numéro de la pattern de contrôle"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nNuméro de la pattern affectée à la voix de contrôle pour la\nposition courante.\n\nEn utilisant le bouton droit de la souris, une fenêtre s''ouvrira où vous\npourrait choisir quelle pattern FX vous désirez affecter à la voix de\ncontrôle pour la position courante.\n@EndNode\n\n@Node InterDiskOp "Utilisation du StoneTracker"\n@font topaz.font 8\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n StoneTracker 1.25\n--------------------------------------------------------------------------------\n|Position|@{"ChargMod" link InterLoadMod}@{"        " link InterNothing}@{"ChargSmp" link InterLoadSamp}@{"Join Mod" link InterJoinMod}@{"Ego Area" link InterEGOArea}|Fréquence | MonoScope  |\n|@{"Nouveau" Link InterClearPos}|@{"SauveMod" link InterSaveMod}@{"        " link InterNothing}@{"SauveSmp" link InterAREXX}@{"Cmd Dos " link InterDosCMD}@{" Efface " link InterDelete}|          |            |\n|@{"Editer " Link InterEditPos}|@{"Resauver" link InterUpDate}@{" Export " link InterExport}@{"SauvBank" link InterSaveBank}@{"SauveObj" link InterSaveExec}@{" Retour " link Use}|  24 Khz  |            |\n-------------------------------------------------------| @{"     # " Link InterFrequency} |            |\n|  Song  |     Samples    |@{"Mix" Link InterMixSample}@{"Réorg" Link InterFlushSample}@{"Choix" Link InterPickSample}@{"Efface" Link InterDeleteSmp}@{"Nouv" Link InterClearSample}|-----------------------|\n|@{"<" link InterButSong}@{"  1" link InterSongNum}@{">" link InterButSong}|  < >   Nome    Lng <> Rep <@{"    0" link InterSampleRep}> Vol <@{"40" Link InterVolumeSample}>| @{"ChannelMeters" Link InterChannelMeters}  | Cmd |\n|@{"Choisir" Link InterPickSong}|  @{"01" Link InterSampleNum} @{"Bass 01 " Link InterSampleName} @{"41200" Link InterSampleLength} Lng <@{"    0" link InterSampleRepLen}> FTU <@{" 0" Link InterFTUSample}>|@{"" Link InterMasterVolume}|               |@{"Suiv" Link InterNextCmd}|\n|@{"Nouveau" Link InterClearSong}|---------------------------------------------| |               |@{"Préc" Link InterNextCmd}|\n|@{"Editer " Link InterEditSong}| Nom Song    : @{"From the future ...          " Link InterSongName}| |               |@{"Edit" Link InterEditCmd}|\n|@{" Temps " Link InterTimeSong}| Nom Module  : @{"Cool baby II                 " Link InterModuleName}|Patt :@{"Nouv " Link InterClearPatt}@{"Edit" Link InterEditPatt}@{"Réorg" Link InterRemapPatt}|\n--------------------------------------------------------------------------------\n| BPM <@{"125" Link InterBPM}>  Pistes <@{"4" Link InterNbTracks}>  LongPat <@{"40" Link InterPattLen}>  @{"FX" Link InterFxSwitch} |@{" Patt:...  Banq:... Temps:...  " Link InterBigGad}|\n--------------------------------------------------------------------------------\n|@{"12" Link InterPosNum}|      @{"  5" Link InterPattNum}     |      @{"  2" Link InterPattNum}     |      @{" 13" Link InterPattNum}     |      @{"  1" Link InterPattNum}     | @{"  5" Link InterFxPattNum} |@{"^v" Link InterChgPos}|\n--------------------------------------------------------------------------------\n|POS|    Piste 1    |    Piste 2    |    Piste 3    |    Piste 4    |  FX  | @{"" Link InterLedState} |\n--------------------------------------------------------------------------------\n@endnode\n\n@node InterNothing ""\n@endnode\n\n@Node InterSaveExec "Crée un executable"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nCrée un exécutable utilisant la library StonePlayer.Library pour jouer le\nmodule contenu en mémoire.\n\nEn lançant le programme généré, le module se joue normalement.\n\nPour arréter la musique il suffit de relancer le programme ou d''envoyer un\nCTRL-C à la task en mémoire.\n@EndNode\n\n\n@node Devel "Développeurs"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nCette section est réservée aux programmeurs désireux d''utiliser un module\nStoneTracker dans une application. Elle n''est disponible que dans la\ndocumentation de la @{"version commerciale" link Auth}.\n@endnode\n\n@Node "InterEditPos" "Editeur de positions"\n@font topaz.font 8\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nOuvre le menu d''édition de position.\n\n			Editeur position\n		@{" 1 " Link "PosEditTrack"}@{" 2 " Link "PosEditTrack"}@{" 3 " Link "PosEditTrack"}@{" 4 " Link "PosEditTrack"}@{" 5 " Link "PosEditTrack"}@{" 6 " Link "PosEditTrack"}@{" 7 " Link "PosEditTrack"}@{" 8 " Link "PosEditTrack"}@{"FX" Link "PosEditTrack"}\n		@{"  Ins  " Link PosEditIns}@{"  Sup  " Link PosEditRem}@{"  Copie  " Link PosEditCopy}@{"  Rept  " Link PosEditRept}\n		@{"  Ech  " Link PosEditExg}@{" Etale " Link PosEditSprd}@{"  Mirr   " Link PosEditDub}@{"  Inv   " Link PosEditSwap}\n\n@endnode\n\n@node PosEditTrack "Selection de voix"\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nLes chiffres permettent de sélectionner les voix qui seront affectées par\nles commandes situées en dessous.\n@endnode\n\n@node PosEditIns ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nInsère une position entre la position courante et la position suivante.\nLa position contient des numéros de patterns nuls.\n@endnode\n\n@node PosEditRem ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nSupprime la position courante.\n@endnode\n\n@node PosEditCopy ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nOuvre une fenêtre permettant de sélectionner la position de destination.\nLa position courante sera copiée sur cette position.\n@endnode\n\n@node PosEditRept ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nAprès sélection de la position de départ et de fin, copie la position courante\nentre les deux positions sélectionnées.\n@endnode\n\n@node PosEditExg ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nPermet d''échanger deux positions.\n@endnode\n\n@node PosEditSprd ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nRemplit les numéros de pattern de la position courante à la position\nsélectionnée avec des numéro de patterns compris entre les numéro de\ndébut et de fin spécifiés.\n@endnode\n\n@node PosEditDub ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nEn sélectionnant seulement deux voix, cette fonction permet de copier les\nnuméros de patterns de la première voix sur la seconde, de la position\ncourante à la position de fin.\n@endnode\n\n@node PosEditSwap ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nEn sélectionnant seulement deux voix, cette fonction permet d''échanger les\nnuméros de patterns de la première voix et de la seconde, de la position\ncourante à la position de fin.\n@endnode\n\n@Node InterEditPatt "Editeur de patterns"\n@font topaz.font 8\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nOuvre le menu d''édition des patterns.\n\n			Editeur pattern\n		@{"Coupe" Link PatEditCut}@{"Copie" Link PatEditCopy}@{"Pose " Link PatEditPaste}@{"Inver" Link PatEditSwap}\n		@{" Ech " Link PatEditExg}@{"Suppr" Link PatEditRem}@{" Ins " Link PatEditIns}@{" Eff " Link PatEditDel}\n		@{"OctUp" Link PatEditOctUp}@{"OctDw" Link PatEditOctDw}@{"NotUp" Link PatEditNotUp}@{"NotDw" Link PatEditNotDw}\n@EndNode\n\n@node PatEditCut ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nMémorise la pattern courante en effaçant son contenu.\n@endnode\n\n@node PatEditCopy ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nMémorise la pattern courante.\n@endnode\n\n@node PatEditPaste ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nCopie la pattern mémorisée sur la pattern courante.\n@endnode\n\n@node PatEditSwap ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nEchange la pattern mémorisée avec la pattern courante.\n@endnode\n\n@node PatEditExg ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nEchange la pattern courante avec la pattern de destination.\n@endnode\n\n@node PatEditRem ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nSupprime les patterns de la pattern courante à la fin de la liste des\npatterns.\n@endnode\n\n@node PatEditIns ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nInsère une ligne dans la pattern courante.\n@endnode\n\n@node PatEditDel ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n\nSupprime une ligne dans la pattern courante.\n@endnode\n\n@node PatEditOctUp ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nAugmente d''une octave les notes de la pattern courante.\n@endnode\n\n@node PatEditOctDw ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nDiminue d''une octave les notes de la pattern courante.\n@endnode\n\n@node PatEditNotUp ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nAugmente d''un demi-ton les notes de la pattern courante.\n@endnode\n\n@node PatEditNotDw ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nDiminue d''un demi-ton les notes de la pattern courante.\n@endnode\n\n@Node InterEditSong "Editeur de Songs"\n@font topaz.font 8\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nOuvre le menu d''édition des songs.\n\n			Editeur song\n		@{" Insère " Link SongEditInsert}@{" Suppr  " Link SongEditRemove}@{" Copie  " Link SongEditCopy}\n		@{"  Ech   " Link SongEditExchg}@{" Joint  " Link SongEditJoin}@{" Coupe  " Link SongEditSplit}\n		@{" Isole  " Link SongEditSingle}@{"Imprime " Link SongEditPrint}@{"ImpTout " Link SongEditPrtAll}\n@EndNode\n\n@node SongEditInsert ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nCrée une nouvelle song après avoir demandé certains paramètres par\nune requète et l''insère au numéro de song actuel, décalant toutes\nles suivantes d''un numéro de song.\n@endnode\n\n@node SongEditRemove ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nSupprime la song courante, décalant toutes les suivantes d''un numéro\nde song.\n@endnode\n\n@node SongEditCopy ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nCopie la song courante sur la song selectionnée comme destination.\n@endnode\n\n@node SongEditExchg ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nEchange la song courante avec la song sélectionnée.\n@endnode\n\n@node SongEditJoin ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nAjoute les positions de la song sélectionnée à la suite des positions de\nla song courante.\n@endnode\n\n@node SongEditSplit ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nCoupe en deux la song courante à partir de la position courante, et copie la\ndeuxième partie des positions sur la song de destination.\n@endnode\n\n@node SongEditSingle ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nAprés confirmation, efface toutes les songs, exceptée la song courante.\n@endnode\n\n@node SongEditPrint ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nImprime la song courante.\n@endnode\n\n@node SongEditPrtAll ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nImprime toutes les songs.\n@endnode\n\n@Node "InterConfig" "Configuration du StoneTracker"\n@font topaz.font 8\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n StoneTracker 1.25\n----------------------------------------------------------------------------\n|  Comp Mod @{"@| Non ", link CnfPackMode} |      Ouvre Pistes @{" 8", link CnfOpenTrk} |      Ouvre avec piste FX @{"V", Link CnfOpenFXChn} |\n| Comp Banq @{"@| Non ", link CnfPackMode} |  Ouvre max pistes @{" 1", link CnfMaxOpenTrk} |  Nouv song avec piste FX @{"V", Link CnfNewSongFXChn} |\n|--------------------| Pistes nouv. song @{" 1", link CnfNewSongTrk} | Stoppe sur vitesse nulle @{" ", Link CnfBreakOnNull} |\n| Def KHz : 21 @{"  # ", link CnfDefKHz} |    Pré-allocation @{"64", link CnfAllocTreshold} |    Valide répét. clavier @{"V", Link CnfEnableKeyRepeat} |\n|--------------------|----------------------|      Sauve samples en IFF @{"V", Link CnfSaveIFFSamples} |\n| LongPatt ouv $ @{"40", link CnfOpenPattLen} |    Action : @{"@| ouvre", Link CnfAction} |    Confirme recouvrement @{"V", Link CnfConfirmOverwrite} |\n| LongPatt max $ @{"40", link CnfMaxPattLen} |        Ajout patt @{" 8", link CnfAddPatt} |            Demande AREXX @{" ", Link CnfAskForAREXX} |\n|   Avertir patt @{"10", link CnfWarnPatAbove} |    Ajout patt. FX @{" 8", link CnfAddFXPatt} |   Garde position AppIcon @{" ", Link CnfKeepAppIconPos} |\n|   Avertir pos  @{"10", link CnfWarnPosAbove} |       Alloue pos. @{" 8", link CnfAllocPosition} | Auto fermeture Workbench @{" ", Link CnfAutoCloseWorkbench} |\n|                                            | Bloq. complet si inactif @{"V", Link CnfFullLockInInactive} |\n|--------------------------------------------------------------------------|\n|1@{"*", Link CnfNum} |Bor         |@{" ", Link CnfSlider1}| |Fond (4)           |@{" ", Link CnfSlider2}|  R:  0 @{"#         ", Link CnfSliderColor1} |       |\n|2@{" ", Link CnfNum} |Coul 1      |  | |Foncé (5)          |  |  V:  0 @{"#         ", Link CnfSliderColor1} |       |\n|3@{" ", Link CnfNum} |Coul 2      |@{"^", Link CnfSlider1}| |Brillant (6)       |@{"^", Link CnfSlider2}|  B:  0 @{"#         ", Link CnfSliderColor1} |       |\n|4@{" ", Link CnfNum} |Coul 3      |@{"v", Link CnfSlider1}| |Eclairé (7)        |@{"v", Link CnfSlider2}|                    |       |\n|--------------------------------------------------------------------------|\n|1@{"*", Link CnfNumMeter}  R:240 @{"     # ", Link CnfSliderColor2} |    |@{"", link CnfSlider3}|  Réel @{"*", Link CnfMeterType}| @{"   Chemins DOS ...   ",Link CnfDosPaths} | @{" Sauve  ", Link CnfSave} |\n|2@{" ", Link CnfNumMeter}  V:240 @{"     # ", Link CnfSliderColor2} |    | |   Vol @{" ", Link CnfMeterType}| @{"   Macros AREXX ...  ",Link CnfAREXXMacros} | @{"Utilise ", Link CnfUse} |\n|3@{" ", Link CnfNumMeter}  B:240 @{"     # ", Link CnfSliderColor2} |    | |  Fréq @{" ", Link CnfMeterType}| @{"Paramètres divers ...",Link CnfMiscParameters} | @{" Annule ", Link CnfCancel} |\n|4@{" ", Link CnfNumMeter}                 |@{"C", Link CnfC}@{"S", Link CnfS}| |  Faux @{" ", Link CnfMeterType}|                        |           |\n----------------------------------------------------------------------------\n@EndNode\n\n@node CnfPackMode ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nStoneTracker propose la compression des banques d''instruments (SampleBanks)\npour économiser de la place sur disquette/disque dur, au prix d''un\ntemps de sauvegarde et de chargement un peu plus long. Pour la version 1.25,\nquatres options sont disponibles (chacune adaptée à la compression\nd''instruments) :\n\n . Aucune \n\n   Les instruments sont sauvegardés tels quels sans être compressés.\n   Utiliser cette option si le temps de compression/décompression vous\n   parait interminable ou si vous sauvegardez le module pour l''utiliser\n   dans une de vos applications personnelles (dans ce cas là, les\n   instruments DOIVENT être décompressés !!).\n\n   (Notez que si vous utilisez la fonction ''update'' pour sauvegarder les\n    modifications, si vous n''avez pas changé les instruments la banque ne\n    sera pas re-sauvegardée, vous économisant le temps de compression\n    éventuel.)\n\n . DeltaHuffman \n\n   La méthode la plus rapide à compresser/décompresser et la moins efficace.\n   Taux de compression : 20-25% en moyenne.\n   Auteur : Emmanuel Marty\n\n . CrM / LZH-Delta\n\n   La méthode qui compresse le plus et qui est la plus lente.\n   Taux de compression : 35-40% en moyenne.\n   Auteur : Thomas Schwartz, auteur de CrunchMania.\n\n   ( Notez que cette méthode nécessite la bibliothèque CrM.Library dans\n     LIBS: pour la compression - la décompression se fait en interne.\n     Nous ne sommes pas autorisés à distribuer ce fichier avec\n     StoneTracker. )\n\n . StoneCruncher / Mickey\n\n   Une méthode intermédiaire entre DeltaHuffman et CrM/LZH-Delta.\n   Taux de compression : 25-30% en moyenne.\n   Auteur : Michael Lavaire\n@endnode\n\n@node CnfOpenTrk ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nNombre de voix par défaut que possèdera la song créée au démarrage du\nprogramme (entre 4 et 8).\n@endnode\n\n@node CnfOpenFXChn ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nIndique si la song créée au démarrage du programme possèdera une\nvoix de contrôle par défaut.\n@endnode\n\n@node CnfMaxOpenTrk ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nNombre de voix maximum que possèdera la song créée au démarrage du\nprogramme (entre 4 et 8).\n@endnode\n\n@node CnfNewSongFXChn ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nIndique si par défaut une nouvelle song possèdera une voix de contrôle\n(si ce paramètre n''est pas changé dans la requète de création d''une\nnouvelle song).\n@endnode\n\n@node CnfNewSongTrk ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nIndique le nombre de voix par défaut que possèdera une nouvelle song (si ce\nparamètre n''est pas changé dans la requète de création d''une nouvelle song).\n@endnode\n\n@node CnfBreakOnNull ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nIndique si le son doit être coupé lors de la rencontre d''une commande de\nvitesse nulle (@{"0F00" link "Set Speed"}), sinon le player s''arrète juste de jouer la\nmusique et laisse les notes en cours se terminer.\n@endnode\n\n@node CnfDefKHz ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nFréquence de mixage par défaut des modes "voix virtuelles" (5-8 voix). Cette\nfréquence et celle à laquelle sont recalculés tous les instruments. Bien\nentendu, plus elle est élevée, plus la qualité de restitution est grande,\net plus la machine est ralentie.\n\nSur un moniteur "normal" (PAL ou NTSC), c''est à dire qui affiche les images\nà une fréquence de balayage horizontal de 15.75 KHz, la fréquence peut être\nsélectionnée entre 4 et 28 KHz. Si vous possédez un moniteur type VGA,\nMultisynchrone etc. qui affiche les modes "désentrelacés" de l''ECS et de\nl''AGA à une fréquence de balayage horizontal de 31.5 Khz, la fréquence peut\nêtre choisie entre 4 et 50 KHz (l''Amiga est ainsi fait...)\n@endnode\n\n@node CnfAllocTreshold ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nStoneTracker possède un maximum de 65.536 patterns et, contrairement à\nProTracker (qui n''en a que 64 possibles), il ne peut réserver la\nmémoire nécessaire à ce nombre maximum de patterns dès le démarrage\ndu programme (pour 65.536 patterns, il faudrait 64 Mégaoctets de\nmémoire de travail [qui plus est n''est pas possible de mettre en mémoire\nvirtuelle sur le disque dur] !!).. StoneTracker réserve donc la\nmémoire nécessaire au patterns en fonction de vos besoins. Pour\néviter de fragmenter trop la mémoire, la mémoire des patterns n''est\npas réservée séparément pour chaque pattern mais par groupe de patterns.\n\nCe chiffre fixe le nombre de patterns reservées en une seule fois.\nPlus il est grand, moins la mémoire est fragmentée et plus il y a de\nchances de gaspiller de la mémoire (exemple, si le programme alloue\nles patterns 100 par 100 et que vous avez 101 patterns en mémoire,\nil y aura de la mémoire resérvée pour 200 patterns). \n\nLa plupart du temps vous n''aurez pas à vous soucier de ce paramètre,\nsa valeur par défaut de 64 semblant bien équilibrée (nous l''utilisons\ndepuis le début du développement de StoneTracker).\n@endnode\n\n@node CnfEnableKeyRepeat ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nIndique si la répétition clavier est autorisée en mode "édition de patterns"\nou en mode "enregistrement" (laisser la touche enfoncée répète la même note)\n@endnode\n\n@node CnfSaveIFFSamples ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nIndique si StoneTracker doit sauvegarder les samples au format IFF lors\nde l''utilisation de la commande de sauvegarde d''instrument séparé. Sinon\nles samples sont sauvegardés au format RAW (sans en-tête).\n@endnode\n\n@node CnfOpenPattLen ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nNombre de lignes des patterns créées au démarrage du programme. Entre $1 et\n$FFF lignes.\n@endnode\n\n@node CnfAction ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nPrécise à quelle action se rapportent les paramètres par défaut au dessous\n(nombre de @{"patterns" link CnfAddPatt}, de @{"patterns de contrôle" link CnfAddFxPatt} et de @{"positions" link CnfAllocPosition} auto-créées) :\ndémarrage du programme (création de la song présente au démarrage) ou\ncréation d''une nouvelle song.\n@endnode\n\n@node CnfConfirmOverwrite ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nIndique si StoneTracker doit demander de confirmer avant d''écrire par\ndessus un fichier dêja existant.\n@endnode\n\n@node CnfMaxPattLen ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nNombre de lignes que peut faire au maximum une pattern (entre $1 et $FFF).\nRéglez réellement ce chiffre en fonction de vos besoins! Plus ce chiffre\nest grand plus la mémoire nécessaire lors du travail sous l''éditeur sera\ngrande.\n@endnode\n\n@node CnfAddPatt ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nNombre de patterns automatiquement créées soit au démarrage du programme,\nsoit lors de la création d''une nouvelle song (voir @{"Action" link CnfAction}) (dans ce\ndernier cas il s''agit de la valeur par défaut, modifiable dans la\nrequète de création d''une nouvelle song).\n@endnode\n\n@node CnfAskForAREXX ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nIndique si StoneTracker doit vous avertir si lors de son démarrage il\nconstante que RexxMaster n''est pas lancé et que donc aucune commande\nAREXX ne pourra être appelée.\n@endnode\n\n@node CnfWarnPatAbove ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nLors de l''ajout de patterns en rentrant directement un numéro de pattern\n(non existant) dans les nos. de patterns au-dessus des voix, tout ajout d''un\nnombre de patterns dépassant le chiffre indiqué sera préalablement confirmé.\n@endnode\n\n@node CnfAddFXPatt ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nNombre de patterns de contrôle automatiquement créées soit au démarrage du\nprogramme, soit lors de la création d''une nouvelle song (voir @{"Action" link CnfAction})\n(dans ce dernier cas il s''agit de la valeur par défaut, modifiable dans la\nrequète de création d''une nouvelle song).\n@endnode\n\n@node CnfKeepAppIconPos ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nIndique si StoneTracker doit utiliser la position sur l''écran du Workbench\nenregistrée dans le fichier d''icône utilisé comme AppIcon, sinon\nil sera rendu "flottant" (le Workbench le positionnera où il pourra)\n@endnode\n\n@node CnfWarnPosAbove ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nLors de l''ajout de positions en rentrant directement un numéro de position\n(non existant) dans le nos. de position, tout ajout d''un nombre de positions\ndépassant le chiffre indiqué sera préalablement confirmé.\n@endnode\n\n@node CnfAllocPosition ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nNombre de positions automatiquement créées soit au démarrage du programme,\nsoit lors de la création d''une nouvelle song (voir @{"Action" link CnfAction}) (dans ce\ndernier cas il s''agit de la valeur par défaut, modifiable dans la\nrequète de création d''une nouvelle song).\n@endnode\n\n@node CnfAutoCloseWorkbench ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nIndique si StoneTracker doit essayer de fermer le Workbench lors de son\ndémarrage, pour gagner de la mémoire chip.\n@endnode\n\n@node CnfFullLockInInactive ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nIndique si l''écran de StoneTracker doit être verrouillé (plus rien n''est\nretracé) lorsque celui-ci n''est pas affiché, et que donc vous travaillez en\nmultitâche sur une autre application - cela permet de gagner beaucoup\nde temps machine. Si cette option est désactivée, StoneTracker se\ncontentera de redescendre la priorité de sa tâche (la rendre moins\ndemandeuse de temps processeur), au profit d''autres tâches en train de\ntourner.\n@endnode\n\n@node CnfNum ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nNuméro de palette. Vous pouvez définir jusqu''à quatre palettes différentes\npour l''écran du StoneTracker et en changer instantanément, selon l''humeur\ndu jour, à l''aide de ce bouton.\n@endnode\n\n@node CnfSlider1 ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nPermet de faire défiler la liste des couleurs disponibles sur la gauche.\n@endnode\n\n@node CnfSlider2 ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nPermet de faire défiler la liste des régions de l''écran du StoneTracker\ndisponibles sur la gauche.\n@endnode\n\n@node CnfSliderColor1 ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nPermet de choisir le niveau d''intensité de rouge, de vert et de bleu pour\nla couleur en cours d''édition\n@endnode\n\n@node CnfNumMeter ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nNuméro de palette de vu-mètres. Vous pouvez définir jusqu''à quatre\npalettes différentes pour les vu-mètres (ChannelMeters) et en changer\ninstantanément, selon l''humeur du jour, à l''aide de ce bouton.\n@endnode\n\n@node CnfSliderColor2 ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nPermet de choisir le niveau d''intensité de rouge, de vert et de bleu pour\nla ligne de vu-mètre en cours d''édition.\n@endnode\n\n@node CnfSlider3 ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nPermet de choisir la ligne de vu-mètre dont la couleur doit être éditée.\n@endnode\n\n@node CnfMeterType ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nPermet de sélectionner le type de vu-mètres utilisé au démarrage du tracker,\nc''est à dire soit "vrai" (volume sonore moyen de ce qui est en train d''être\njoué par la voix sonore correspondante - type ProTracker 3.xx), "volume"\n(volume du dernier instrument joué sur la voix), "fréquence" (hauteur de note\ndu dernier instrument joué) et "simulé" (volume mis au maximum lors du\ndémarrage d''un nouvel instrument, et qui redescend régulièrement ensuite -\ntype premiers trackers)\n@endnode\n\n@node CnfSave ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nSauvegarde la configuration pour que vous la retrouviez telle quelle lors\ndu prochain lancement du programme. La configuration est sauvegardée dans\n"ENVARC:StoneTracker.prefs".\n@endnode\n\n@node CnfUse ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nRetourne dans le programme avec la configuration actuelle, mais ne la\nsauvegarde pas - au prochain lancement de StoneTracker la configuration sera\ntelle qu''elle était avant d''avoir été modifiée.\n@endnode\n\n@node CnfCancel ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nAnnule les modifications faites à la configuration et retourne dans le\nprogramme avec la configuration telle quelle était avant de rentrer dans\nl''éditeur de configuration.\n@endnode\n\n@node CnfC ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nCopie une couleur d''une ligne de vu-mètre à une autre. Mode d''utilisation :\nsélectionner la ligne à copier, appuyer sur ce bouton, sélectionner la\nligne cible, et appuyer encore une fois sur ce bouton.\n@endnode\n\n@node CnfS ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n"Spreade", produit un dégradé entre deux lignes de vu-mètre. Mode\nd''utilisation : sélectionner la ligne de départ, appuyer sur ce bouton,\nsélectionner la ligne d''arrivée, et appuyer encore une fois sur ce bouton.\n@endnode\n\n@node CnfDosPaths "Fenêtre de configuration de répertoires par défaut"\n@font topaz.font 8\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nOuvre la fenêtre de configuration de répertoires par défaut.\n\n	  Chemins DOS...\n	-------------------------------------------\n	|   Chemin mod : @{"ST-00:               ",Link CnfModulePath}@{"G", Link CnfModulePathFile} |\n	|  Chemin samp : @{"RAM:                 ",Link CnfSamplePath}@{"G", Link CnfSamplePathFile} |\n	| Chemin défaut: @{"RAM:                 ",Link CnfDefaultPath}@{"G", Link CnfDefaultPathFile} |\n	|-----------------------------------------|\n	| Masque module: @{"~(SPS|SMPL)~(???|????).",Link CnfModuleMask} |\n	| Masque sample: @{"#?                     ",Link CnfSampleMask} |\n	|-----------------------------------------|\n	| Imprim. Dest.: @{"PRT:                   ",Link CnfPrinterPath} |\n	|  Haut. Page  : @{"64      ",Link CnfPageHeight}@{" Lecture ...  ",Link CnfFetch} |\n	-------------------------------------------\n@endnode\n\n@node CnfModulePath ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nChemin par défaut dans lequel StoneTracker ira chercher les modules lors des\ncommandes de chargement et de sauvegarde de module. Si vous travaillez\navec un disque dur, mettre ici le chemin où se trouve vos modules vous\névitera de le préciser à chaque démarrage du programme.\n\nNOTE: si vous changez ce chemin, le nouveau chemin ne sera pris en compte\n      que lors du redémarrage du programme.\n@endnode\n\n@node CnfModulePathFile ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nPermet de sélectionner le @{"chemin par défaut des modules" link CnfModulePath} à l''aide d''une\nrequète de fichiers.\n@endnode\n\n@node CnfSamplePath ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nChemin par défaut dans lequel StoneTracker ira chercher les samples lors des\ncommandes de chargement et de sauvegarde de samples et de banques de samples.\nSi vous travaillez avec un disque dur, mettre ici le chemin où se trouve vos\nsamples vous évitera de le préciser à chaque démarrage du programme.\n\nNOTE: si vous changez ce chemin, le nouveau chemin ne sera pris en compte\n      que lors du redémarrage du programme.\n@endnode\n\n@node CnfSamplePathFile ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nPermet de sélectionner le @{"chemin par défaut des samples" link CnfSamplePath}\nà l''aide d''une requète de fichiers.\n@endnode\n\n@node CnfDefaultPath ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nChemin par défaut de toutes les commandes de fichier ne se rapportant pas\nà un type de données précis, notamment la commande d''effacement de fichiers.\n@endnode\n\n@node CnfDefaultPathFile ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nPermet de sélectionner le @{"chemin par défaut des fichiers non typés" link CnfDefaultPath}\nà l''aide d''une requète de fichiers.\n@endnode\n\n@node CnfModuleMask ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n"Masque" par défaut utilisé dans les requètes de modules. Ce masque permet\nd''inclure et d''exclure des fichiers comportant certaines lettres ou certains\nmots dans leur nom. Son utilité principale ici est d''exclure les fichiers\ndes banque de samples, commençant par "SPS.".\n@endnode\n\n@node CnfSampleMask ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n"Masque" par défaut utilisé dans les requètes de samples et de banques de\nsamples. Ce masque permet d''inclure et d''exclure des fichiers comportant\ncertaines lettres ou certains mots dans leur nom.\n@endnode\n\n@node CnfPrinterPath ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nChemin utilisé par l''AmigaDOS pour l''imprimante, normalement "PRT:".\n@endnode\n\n@node CnfPageHeight ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nNombre de lignes par page de votre imprimante.\n@endnode\n\n@node CnfFetch ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nPermet d''aller lire dans vos fichiers de préférences le nombre de lignes par\npage de l''imprimante active.\n@endnode\n\n@node CnfAREXXMacros "Ouvre la fenêtre d''installation de macros AREXX"\n@font topaz.font 8\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nOuvre la fenêtre d''installation de macro AREXX.\n\n	  Macros AREXX ...\n	--------------------------------\n	| @{"A:                    ",Link CnfAREXXMacro} |@{" ", Link CnfSliderMacro}| |\n	| @{"B:                    ",Link CnfAREXXMacro} |  | |\n	| @{"C:                    ",Link CnfAREXXMacro} |@{"^", Link CnfSliderMacro}| |\n	| @{"D:                    ",Link CnfAREXXMacro} |@{"v", Link CnfSliderMacro}| |\n	|------------------------------|\n	| @{"                          ",Link CnfAREXXMacroString}@{"G", Link CnfSliderMacroFile}|\n	--------------------------------\n@endnode\n\n@node CnfAREXXMacro ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nListe des macros AREXX. Il est possible d''installer 14 macros AREXX\nsimultanément correspondant aux lettres de A à N (leur raccourci\nclavier étant CTRL + leur lettre).\n@endnode\n\n@node CnfSliderMacro ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nPermet de faire défiler la liste des macros AREXX.\n@endnode\n\n@node CnfAREXXMacroString ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nPermet d''éditer le nom du fichier contenant la macro AREXX à installer\nsur la lettre actuellement sélectionnée dans la liste au dessus.\n@endnode\n\n@node CnfSliderMacroFile ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nPermet de sélectionner à l''aide d''une requète de fichier le fichier contenant\nla macro AREXX à installer sur la lettre actuellement sélectionnée dans la\nliste au dessus.\n@endnode\n\n@node CnfMiscParameters "Ouvre la fenêtre de configuration de paramètre divers."\n@font topaz.font 8\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nOuvre la fenêtre de configuration de paramètre divers.\n\n	  Paramètres divers ....\n	----------------------------------------\n	|   App Icon: @{"StoneTracker.Info    ",Link CnfAppIcon}@{"G", Link CnfGetAppFile} |\n	|  AREXX I/O: @{"CON:0/0//100/StoneREXX/",Link CnfAREXXIO} |\n	|     Touche: @{"control alt s          ",Link CnfHotKey} |\n	| Mode écran: @{"PAL:High Res         ",Link CnfScreenMode}@{"G", Link CnfGetScreenMode} |\n	|--------------------------------------|\n	|  Smp fast : @{"@| TailleSmp  ",Link CnfFastLoad} KB @{"256 ", link CnfFastLoadSize} |\n	----------------------------------------\n@endnode\n\n@node CnfAppIcon ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nNom du fichier icône contenant l''AppIcon à utiliser pour le StoneTracker.\n@endnode\n\n@node CnfGetAppFile ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nPermet de sélectionner à l''aide d''une requète de fichier le fichier icône\ncontenant l''AppIcon à utiliser pour le StoneTracker.\n@endnode\n\n@node CnfAREXXIO ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nDéfinition de la fenètre de console utilisée pour les entrées/sorties des\ncommandes AREXX lancées à partir de StoneTracker.\n@endnode\n\n@node CnfHotKey ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n"Hot key" de StoneTracker. La combinaison de touches indiquée lorsqu''elle\nest effectuée fait soit passer l''écran de StoneTracker devant les autres\nsoit s''ouvrir cette écran si il était caché.\n@endnode\n\n@node CnfScreenMode ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nIndique le mode d''écran utilisé pour l''écran du StoneTracker (et l''écran de\nconfiguration).\n@endnode\n\n@node CnfGetScreenMode ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nPermet de sélectionner le mode d''écran utilisé pour l''écran du StoneTracker\n(et l''écran de configuration) à l''aide d''une requète de sélection de\nmode d''écran. A noter que StoneTracker nécessite au minimum une taille\nd''écran de 672 par 200 pixels, et qu''il faut 256 pixels de hauteur au moins\npour travailler confortablement.\n@endnode\n\n@node CnfFastLoad ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nStoneTracker propose le chargement des instruments en mémoire fast si vous\nne disposez pas de suffisamment de mémoire chip. Cette option ralentit\nlégèrement le programme en mode 4 voix, et peut l''accélerer en mode\nvoix virtuelles (5-8 voix).\n\nCe bouton règle la condition de chargement des instruments en mémoire\nfast. Trois possibilités :\n\n	- jamais\n\n	- si la taille des instruments dépasse une @{"certaine taille" link CnfFastLoadSize}\n\n	- si la taille de mémoire chip libre descend en dessous d''une\n	  @{"certaine taille" link CnfFastLoadSize}.\n@endnode\n\n@node CnfFastLoadSize ""\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\nStoneTracker propose le chargement des instruments en mémoire fast si vous\nne disposez pas de suffisamment de mémoire chip. Cette option ralentit\nlégèrement le programme en mode 4 voix, et peut l''accélerer en mode\nvoix virtuelles (5-8 voix).\n\nIndique en kilo-octets soit la taille d''instruments à partir de laquelle ils\nsont chargés en mémoire fast, soit la taille de mémoire chip libre en dessous\nde laquelle les instruments sont chargés en mémoire fast, selon le @{"mode" link CnfFastLoad}\nen cours.\n@endnode\n\n@node Keyboard "Raccourcis clavier ..."\n\n\n			@{fg Highlight}StoneTracker V1.25@{fg text}\n\n\n			@{u}Raccourcis clavier@{uu}\n\n\n@{u}Touches générales :@{uu}\n\nF1	      Sélectionne les octaves #1 et #2\nF2	      Sélectionne les octaves #2 et #3\nF6 à F10      Bouge le curseur dans la pattern (pour la compatibilité\n						avec les autres trackers)\nESPACE        Stoppe la musique, entre/sort du mode d''édition\nDEL           Efface la note sous le curseur (mode d''édition seulement)\nBACKSPACE     Efface la ligne sous le curseur (mode d''édition seulement)\nSHIFT BACKSP. Insère une nouvelle ligne sous le curseur (mode d''édition seulement)\nSHIFT DROITE  Démarre l''enregistrement   \  Avec la touche shift gauche\nAMIGA DROITE  Joue la position courante  /  (ou le bouton droit de la souris)\nALT DROITE    Joue la song courante     /   Démarre à la ligne courante\nLES DEUX ALT  Redémarre la song courante depuis le début\n<             Coupe la sortie de la voix courante\n`             Sélectionne une song par requête\nRETURN	      Entre en mode pas à pas, effectue un pas (avec shift sort du mode)\nHAUT          Déplace le curseur d''une ligne vers le haut\nSHIFT-HAUT    Déplace le curseur de 16 lignes vers le haut\nALT-HAUT      Place le curseur sur la premiére ligne\nCTRL-HAUT     Saute à la position précédente\nBAS           Déplace le curseur d''une ligne vers le bas\nSHIFT-BAS     Déplace le curseur de 16 lignes vers le bas\nALT-BAS       Place le curseur sur la premiére ligne\nCTRL-BAS      Saute à la position suivante\nGAUCHE	      Déplace le curseur d''un caractère sur la gauche\nSHIFT-GAUCHE  Déplace le curseur d''une voix sur la gauche\nALT-GAUCHE    Place le curseur sur la première voix\nCTRL-GAUCHE   Montre la commande précédente sur la voix courante (multi-effet)\nDROITE	      Déplace le curseur d''un caractère sur la droite\nSHIFT-DROITE  Déplace le curseur d''une voix sur la droite\nALT-DROITE    Place le curseur sur la derniére voix\nCTRL-DROITE   Montre la commande suivante sur la voix courante (multi-effet)\nTAB	      Déplace le curseur sur la voix suivante\n\n@{u}Touches de note (comme les autres trackers) :@{uu}\n\n 23 567 90 -		 23 567 90 -\nAZERTYUIOP^$		QWERTYUIOP{}\n SD GHJ LM		 SD GHJ L;\nWXCVBN,;:=		ZXCVBNM,./\n\n@{u}Touches du pavé numérique :@{uu}\n\nSans touche supplémentaire - Définissent le chiffre inférieur du sample\n\n[]/*	: x1,x2,x3,x4\n789-	: x5,x6,x7,x8\n456+	: x9,xA,xB,xC\n123	: xD,xE,xF\n.	: x0\n0 	: sélectionne le sample 0\nENTER   : sélectionne par requête\n\nAvec shift gauche - Définissent le chiffre supérieur du sample\n\n[]/*	: 1x,2x,3x,4x\n789-	: 5x,6x,7x,8x\n456+	: 9x,Ax,Bx,Cx\n123	: Dx,Ex,Fx\n.	: 0x\n0 	: sélectionne le sample 0\nENTER   : sélectionne par requête\n\n@{u}Touches de saut de ligne :@{uu}\n\nCTRL + 1-9	Définit le nouveau saut entre chaque entrée de note\n\n@{u}Touches utilisées dans les requêtes :@{uu}\n\nESC		\\nN		Réponse négative\nAmiga/B		/\n\nY		\ Réponse positive\nAmiga/V         /\n\nRETURN          Valide les requête simples (ex. Info)\n                Sélectionne un élément dans une liste (ex. Choisir Sample)\n\nUP/DOWN keys	Si la requête affiche une liste, monte et descend dans\n		la liste (vitesse par 16 avec shift gauche, directement\n		en haut et en bas avec alt gauche)\n\n@{u}Appel de macros AREXX (avec ctrl) :@{uu}\n\nA-N		Appelle les macros AREXX de A à N\n\n@{u}Raccourcis clavier (avec shift gauche) :@{uu}\n\nO		Charger Module\nW		Sauver Module\nL		Charger Sample\nM		Sauver Sample\nB		Sauver Bank\nU		Update\nD		Effacer Fichier(s)\nDEL		Effacer pattern courante\nR		Réorganiser patterns\nC		Effacer patterns\nV		Effacer positions\nG		Effacer songs\nA		Ajouter song\nT		Chronométrer song\nX		Mixer position dans un sample\nF		Réorganiser samples\nE		Editer commandes\n`		Choisir pattern par requète\n\		Fermer/Ouvrir Workbench\nN		Désactiver éditeur\nH		Cacher\nI		Information\nQ		Quit\n@EndNode\n','\n',char(10)),'{"PRIORITY":"priorité"}','auto-added',657485,7,0,NULL,NULL,'stracker','scan',1780048759);
