INSERT INTO door_catalog VALUES('suk_cc01','SUK-CC01.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SUK-CC01.LHA','CallCheck','XIM','______________________________ ______',NULL,NULL,'SUK','______________________________ ______ :+:./_    /  /  //  /  /  /    /  T/_    /.: .:./ ¬\\_/ _/  //  /  /  / \\_/   / ¬\\_/.:.',replace('\n     ______________________________ ______\n:+:./_    /  /  //  /  /  /    /  T/_    /.:\n.:./ ¬\\_/ _/  //  /  /  / \\_/   / ¬\\_/.:.\n:./\___ ¬\ ¬  /_   \ _   \ _  \   \___ ¬\:.:\n./   ¬~\\ \  / ¬\   \¬\   \¬\_/\  l__¬\\ \+.\n.\_________\/____\___\_\___\____\____\____\.\n>>Sukkels /X & S-Xpress division Presents<<\nCallCheck v0.1 No more Lamer-Attacks! [1/1]\n\n','\n',char(10)),'CallCheck.doc',replace('\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n       _____  _______  __________/\_________________________________\n       T __¬\/  _   / /       / /  \ _/    / /   /_   /   T        /:.:+.:\n       | ¬~\ \  ¬\\/ /_\     /_/    \¬    /_/   / ¬\\/    |_\     /:.:.\n       |    \ \    \/ ¬\\___/ ¬\    /    / ¬  _/     \    |¬\\___/:+.:\n      .|     \ \ \  \_____¬~\      /   _/     ¬\  _\  \   |____¬~\.:\n    .:+|     .\ \\\_/\  ¬~\\_\    /_   ¬\  _    \ ¬\\_/\  |  ¬~\\_\.\n .:.:.:|     // /  ¬  \    \¬ \  / ¬\    \ ¬\    \   ¬  \ l____ \¬ \\n.:+:.:.l_______/_______\_______\/____\____\__\____\______\_____\__[PAF]\n\n\n             De Sukkels /X & S!gma-Express division presents:\n\n                            Callcheck v0.01! \n\n\n\n\nWhats the use?\n\nWith this tool you can specify the maximum amount of calls a user can\nmake to your board! So no more last-callers filled with only 1 lamer\nwho doesnt understand one little fuck he is doing...! (jojojojojojo hiehii)\n\nINSTALLATION:\n\n- You have unpacked the archive, so the dirs already excist..\n  (DOORS:LC-TOOLS)\n\n- You have to call the door from a screen like LOGON.TXT or shit like that..\n  (Use MCI!)\n\n- Say you want to keep track of a user named "Pipo De Clown".\n   - Create an icon named "Pipo_De_Clown.Info" in Doors:lc-tools/users/\n     (NOT case-sensitive. use "_" for spaces in names!)\n   - Use this tool-type for the specification of the amount of calls:\n     MAXCALLS=3 (adjust this for your own needs..! eg MAXCALLS=392918)\n\n- Install it as a XIM door!\n\n- All paths are hard-coded! So DONT fuck around, or the tool will NOT work!\n\n\n\nNEWSFLASH -- NEWSFLASH -- NEWSFLASH -- NEWSFLASH -- NEWSFLASH -- NEWSFLASH --\n\n\n             DE SUKKELS are _NOT_ looking for new members!\n\n      So if you _DONT_ want to join us, CALL The Shop or NoseFuck!\n\n\nNEWSFLASH -- NEWSFLASH -- NEWSFLASH -- NEWSFLASH -- NEWSFLASH -- NEWSFLASH --\n\n\n\n   ___________________________________________________________________\n\n   Phone: +31-5750-70440 (Captain Pizza) & +31-5750-71510 (Interphase)\n   ___________________________________________________________________\n\n\n\n\n   Idea: Interphase\n Coding: Darkspot\nUseless: Captain Pizza (oh yeah i wrote this doc.. eheh..)\n\n\n\n\n\n\n\n@BEGIN_FILE_ID.DIZ     ______________________________ ______\n:+:./_    /  /  //  /  /  /    /  T/_    /.:\n.:./ ¬\\_/ _/  //  /  /  / \\_/   / ¬\\_/.:.\n:./\___ ¬\ ¬  /_   \ _   \ _  \   \___ ¬\:.:\n./   ¬~\\ \  / ¬\   \¬\   \¬\_/\  l__¬\\ \+.\n.\_________\/____\___\_\___\____\____\____\.\n>>Sukkels /X & S-Xpress division Presents<<\nCallCheck v0.01! Put a lit on local lamers!\n@END_FILE_ID.DIZ\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n','\n',char(10)),NULL,NULL,5259,2,0,NULL,NULL,'suk_cc01_callcheck','scan',1780048759);
