INSERT INTO door_catalog VALUES('sup_pv12','SUP-PV12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SUP-PV12.LHA',NULL,'XIM','_       __ ____ ___  _______  _',NULL,NULL,'SUP','`--.l__\\__)\__/,\  ''|\__/\  ''`--. --+2F -. /__|     \                    /__|        | .- - ------------       - - ----- - ------''',replace(' _       __ ____ ___  _______  _\n`--.l__\\__)\__/,\  ''|\__/\  ''`--. --+2F -.\n/__|     \                    /__|        |\n.- - ------------       - - ----- - ------''\n|               SUP-PAGE v1.2\n|               ~~~~~~~~~~~~~\n|   - This is a great SysOp Page door for\n|  AmiExpress v4.x. Useful changes is done\n|    since v1.1, so leech it right away!\n`- --   - - -  ---- ---------------------->\n','\n',char(10)),'SUP-Page.guide',replace('@DATABASE SUP-Page Documentation!\n@AUTHOR Nicko of Superiors^Skid Row!\n@NODE MAIN " Main-Menu"\n \n        Documention for SUP-Page v1.2!\n        ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n       @{"          Quick notes!         " LINK QUICK-NOTES}\n       @{"         Soon available        " LINK SOON-AVAILABLE}\n       @{"             Author            " LINK AUTHOR}\n       @{"         How to contact        " LINK HOW-TO-CONTACT}\n       @{"            History!           " LINK HISTORY}\n       @{"           Greetings!          " LINK GREETINGS}\n       @{"         Support boards        " LINK SUPPORT-BOARDS}\n       @{"           Copyrights          " LINK COPYRIGHTS}\n \n \n          Copyright 1995, Superiors.\n \n \n \n \n \n \n \n@ENDNODE\n@NODE QUICK-NOTES\n\n  Quick notes!!!\n  ~~~~~~~~~~~~~~\n \n 1. We take no responsability what-so-ever if anything at all crashes etc.\n 2. If you don''t know how to install this - THEN DON''T USE IT !!!\n 3. You also need to run Arexx in background to use it.\n@ENDNODE\n@NODE SOON-AVAILABLE\n \n  Soon available from Superiors:\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n \n 1. SUP-Wall v1.0 - Yeps! A new wall. W¡LL BE MAJOR DELAYED!!!\n 2. SUP-Stat v1.0 - A lovely Status-Door. The ßeta sure looks nice!!!\n@ENDNODE\n@NODE AUTHOR\n \n  Author:\n  ~~~~~~~\n \n Nicko of Superiors and Skid Row.\n@ENDNODE\n@NODE HOW-TO-CONTACT\n \n  How to contact:\n  ~~~~~~~~~~~~~~~\n \n Call our @{"support boards" LINK SUPPORT-BOARDS}. Or any board you see me at.\n@ENDNODE\n@NODE HISTORY\n \n  History:\n  ~~~~~~~~\n \n v1.0, 07-May-95. First release.\n \n v1.1, 08-May-95. Add''ed a ''SysOp-Can''t-Page-SysOp'' feature\n                - Should CLS the screen now.\n \n v1.2, 22-Jul-95. Dezign has some new small features.\n                - In v1.1 there still was some problems with CLS by the\n                  screen. SHOULD be fixed now 8)\n@ENDNODE\n@NODE GREETINGS\n \n  Greetings:\n  ~~~~~~~~~~\n Dizy of Vanity,\n Webster of Passion,\n Zarch&Xman of Passion,\n Marc of Skid Row,\n Josh(ua) of Prodigy, Zekt and Superiors,\n Macho of Superiors and Excalibur,\n Menace of Vanity and Opaque,\n \n AND OFCAUSE TO ALL IN SUPER¡ORS.\n@ENDNODE\n@NODE SUPPORT-BOARDS\n \n  Support boards:\n  ~~~~~~~~~~~~~~~\n \n           [WHQ!] -      Imperial      -  Ndz1  -  +45-582-86107\n           [SHQ!] -    Incubus  BBS    -  Ndz3  -  +46-521-14442\n           [SHQ!] -    Holiday  Inn    -  Ndz1  -  +46-911-17887\n           [NHQ!] -    Burning Hell    -  Ndz2  -  +47-221-65091\n           [NHQ!] -      Pitstop!      -  Ndz2  -  +47-333-87955\n           [SCHQ] -    The  Channel    -  Ndz2  -  +45-744-32379\n           [DKHQ] -   Fatal  Justice   -  Ndz1  -  +45-311-82284\n           [DKHQ] -  Conscious  Dream  -  Ndz2  -  +45-653-82929\n           [DKHQ] -      Atlantis      -  Ndz1  -  +45-OFF-LiNE!\n           [DKHQ] -  Somewhere Online  -  Ndz2  -  +45-596-54155\n           [DiST] -     Infectious     -  Ndz1  -  +45-316-38038\n@ENDNODE\n@NODE COPYRIGHTS\n  Copyrights:\n  ~~~~~~~~~~~\n \n Everything is copyright''ed to Superiors.\n@ENDNODE\n@ENDGUIDE\n','\n',char(10)),NULL,NULL,17300,2,0,NULL,NULL,NULL,'scan',1780048759);
INSERT INTO door_catalog VALUES('supass21','SUPASS21.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SUPASS21.LHA','SuperPass','XIM','SuperPass',NULL,NULL,NULL,'|      ORG. FILENAME: SuperPass21.lha      | |               [util/boot]                | |------------------------------------------|',replace('.------------------------------------------.\n|      ORG. FILENAME: SuperPass21.lha      |\n|               [util/boot]                |\n|------------------------------------------|\n|  SuperPassword v2.1 upgrade from v2.0b   |\n`----------------------------------baron--·''\n','\n',char(10)),'SuperPass.doc',replace('\n\n\n                                SuperPass 2.1\n                Copyright ©1994-95 WoytekWare Computer Services\n\n\n                                  DOCUMENT\n\n\n\n                           Author:  Jonathan Woytek\n                     RELEASE DATE:  7/9/95\n\n\n\n\n\nDISTRIBUTION\n\n	This program may be distributed via any electronic means, as long as\nit is provided WITHOUT EXTRA FEE.  A MINIMAL charge may be made to pay for\ndisks if you choose to distribute it via disk.  In either case, the\nfollowing files MUST be kept inside the archive:\n		SuperPass.doc\n		SuperPass\n		SP_install\n		Install_SuperPass\n		History\n		WWCS_History\n		README.FIRST\n		reboot.lzx \nAny archival format may be used as long as the above\nfiles are included, unchanged, and in their entirety.\n\n	This program is released as Freeware, which means if you like it,\ngood, if you don''t, good.  :) In either case, I would appreciate any and\nall comments (see the email address at the bottom of this document).  If\nyou want to send me something, like a copy of your newest program, you''ll\nrecieve a free personalized copy of the latest version of SuperPass\navailable.  See the bottom of this document for more information.\n\n	This program may not be included in any other releases of any kind,\nexcept those with my personal permission.  To obtain this, see the bottom\nof this document.  Permission is given to the following people for\ninclusion with their releases:\n		The Fred Fish Library (including the CD ROM releases)\n		The Fred Fish Library on CD ROM\n		The AmiNet CD ROM''s from Walnut Creek\n\n	The programs and items in the archive reboot.lzx are for the reboot\ncommand, which must be installed for SuperPass to operate correctly.\nPlease read the documentation concerning that program for it''s author and\ndistribution requirements.\n\n\nDISCLAIMER\n\nThe following disclaimer is for the program called ''SuperPass'', from now on\ncalled ''program''.\n\nI hereby reject any liability or responsibility for these or any other\nconsequences from the use of ''program'' whatsoever.  This includes, but is\nnot limited to, damage to your equipment, to your data, personal injuries,\nloss of money, loss of hair, loss of concience or any other kinds of side\neffects.\n\nAlthough ''program'' has been tested thoroughly on some different machines, I\ncannot rule out the possibility that ''program''\n\n   * is somehow incompatible to your equipment\n   * has bugs that show up on your equipment\n   * does not do what it is supposed to do on your equipment\n\nIt is your responsiblity to take any precautions necessary to protect\nyourself from these or any other effects.  I explicitly reject any\nliability or responsibility from the consequences of you using ''program''.\n\nThanks to David Swasbrook, from whom the disclaimer was ''borrowed''!\n ---------------\n\n\nIntro:\n\n	A few years ago, I was running into problems with other people using\nmy system without my permission.  Having confidential files on my machine\nmade it a priority to have a good, secure password-ing system in use to\nkeep out those who I did not want using it.  It was from this that\nJDWPassword was born.  JDWPassword was my first entry into the Amiga\ncomputer-programming market, and it was certainly a blast making it.  I\nused it for a year or so, and then it became an obsolete necessity.\nConsequentially, I put the project on a shelf and went on to do other\nthings with my life.  Recently, I''ve come back into a situation where I\nagain need such a program, and JDWPassword just wasn''t hacking it anymore\non my new A1200.  It was from that original JDWPassword code that SuperPass\nwas born.  Superpass 2.1 is a fully-functional, fully-confidential\npasswording system, offering customizability that I found lacking in other\npasswording programs.  And, best of all, IT''Z FREE!  :)\n\n\nINSTALLATION AND USE OF THE PROGRAM:\n\n	Requirements:\n		* Any Amiga system\n		* The REBOOT command package (included)\n		* Amiga''s "installer" if you want to use the install script\n		* A little knowledge of editing your system-startup or \n		  user-startup if you choose not to run the install script.\n\n	Installation is very very easy, finally!  Just use the\nInstall_SuperPass program (providing you have Installer in your path), and\nit will call everything it needs to complete it''s job.  From there, all\nyou''ll need to do is reboot to use it!  :) If you DO NOT have Installer\navailable to you, you may simply run the SuperPass_install program, which\nwill copy the appropriate files to their places, and tell you what must be\nadded to your startup-sequence or user-startup (depending on your OS\nversion).  If you do the manual install, KEEP THE SuperPass_install program\naround somewhere!  If you don''t, you won''t be able to change the passwords!\nSuperPass 2.1 has been coded to run on all machines.  If you would like a\n68020 version of the program, drop me a line in email (see the bottom of\nthis document) and I''ll get it out to ya via email.  Please note that if\nyou do not have OS 2.xx or better, you MUST add the line to your\nstartup-sequence BEFORE the "loadwb" line.  If this is not followed, the\nprogram won''t work as described here!  :)\n\n	SuperPass is very easy to use.  Simply install as instructed above,\nadd the lines you need if you did not use the Install_SuperPass script, and\nreboot!  That''s all there is to it!  You may change the passwords at any\ntime if you''d like simply by using the SuperPass_install program, which\nshould be in your C: directory if you used Install_SuperPass script, or\nwherever you put it if you used the manual install.  It will prompt you\nthrough it.  \n\n	SuperPass 2.0+ has been completely re-coded from the bottom up.\nAlthough based on JDWPassword 1.5IH (in-house test version), it may not be\nable to use the old password files if you used previous versions of\nJDWPassword.  Please just take a few seconds to re-create them with the\ninstaller, you''ll be much better off!  SuperPass 2.1 has also been\noptimized for space, but not for speed.  On my 68020 A1200 it takes about\n1/100th of a second to load off of my IDE hard-drive.  On other systems\nthis may vary, but it''s still a pretty small program.  I don''t think it can\nbe made resident, although I have no idea why anyone would WANT to!  :)  \n--------------------------------------------------------------------------\n\nWoytekWare Software Company Update:\n\n	WoytekWare Software is now WoytekWare Computer Services.  A new\nWWCS_history file is included that details my history, and the history of\nmy company.\n\n\nNotes:\n\n	A History file is now included in the archive.  It just gives a brief\nhistory of the changes in the program.  PLEASE copy and distribute ALL\nWoytekWare Software products to your friends and show them that quality is\nnot always in the big-name products!  Read the distribution notice at the\nbeginning of this document for more information.\n--------------------------------------------------------------------------\n\nFuture Additions:\n\n	The next major revision of SuperPass (planned to be 2.5) will\nhopefully include:\n		* Faster, smaller executable\n		* WB-Lockup for unattended machines\n		* Possibly a GUI setup utility!  :) (want to write one?  Email!)\n		  --->  Thanks Mats!  I now have one, and it will be included in\n			   the next release (2.5)!!\n		* AmigaGuide-format documentation\n--------------------------------------------------------------------------\n\nTo Reach Me:\n\n	Energy Telecommunications is the official support board for WoytekWare\nSoftware.  All new updates are available on Energy and Aminet.\n\n			Energy:	(412) 339-0590 [24.0k]\n					(412) 339-0591 [24.0k]			Mr. Technology\n					*** OFFICIAL SUPPORT BOARD\n\n			Email:	[email removed]      <--Preferred\n					[email removed]\n--------------------------------------------------------------------------\n\nBeta-Testing:\n\n	So, you want to be a beta-tester?  Well, it''s SIMPLE!  Just drop me a\nline in email to one of the above addresses, and I''ll start sending you a\ncopy of the newest BETA version UUEncoded via email!  Beta-testers will be\nthanked in future versions of the documentation.\n\n\nWhat''s this I hear about free personalized copies?\n\n	Yeah!  They''re out there!  All you have to do is send me the latest\nversion of a program you''re working on, and you''ll get a free personalized\ncopy via email!  Just don''t send me anything like:\nmain()\n{\n	printf( "Hello, world!" );\n	exit(0);\n}\nor you might not get anything!  \n--------------------------------------------------------------------------\n\nCurrent list of WWCS members/BETA testers:\n\n		Mats			--> GUI programmer/BETA tester\n--------------------------------------------------------------------------\n\n\n\n    Thank you for choosing to use SuperPass 2.1!\n\n','\n',char(10)),NULL,'auto-added',38335,3,0,NULL,NULL,'supass21','scan',1780048759);
INSERT INTO door_catalog VALUES('supdupc','SUPDUPC.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SUPDUPC.LHA',NULL,'XIM','pizza_taxi.exe','1.03','Pot-Noodle/G''G/ATX]',NULL,'-------------------------------------------- It doesn''t look like it''ll ever get finished so here''s the beta. Source-code can be found',replace('Super-DupeCheck v1.03 - Release 4, *BETA 3*.\n--------------------------------------------\nIt doesn''t look like it''ll ever get finished\nso here''s the beta. Source-code can be found\nin another archive.  [By Pot-Noodle/G''G/ATX]\n','\n',char(10)),'SDC_R4B3.readme',replace('Short:    Super-DupeCheck 1.03: Release 4, Beta 3\nUploader: Leo Davidson <[email removed]>\nAuthor:   Leo Davidson <[email removed]>\nType:     comm/amiex\n\nSuper-DupeCheck v1.03 [RELEASE 4 BETA 3]\nWritten by Leo Davidson (aka Pot-Noodle)\n\nSuper-DupeCheck is a DupeChecker for AmiExpress. Chances are that if\nyou run AmiExpress BBS software, you''ve probably heard of it already,\nand if not you''ll have heard of Super-AmiLog, which I also wrote.\n\nThis beta version has been around for ages and I just don''t have the\nmotivation to finish it off, so I thought I should just release it now,\nas it does have some extra features not in the last release (from ages\nago).\n\nI am also releasing the source code for this, Super-AmiLog3-beta, and\nperhaps some other of my BBS-utils, in case anyone out there would like\nto continue updating them or just needs to see how something is done.\n\n	Leo, 30-Aug-1995.\n','\n',char(10)),NULL,'auto-added',78525,4,0,NULL,NULL,'supdupc','scan',1780048759);
INSERT INTO door_catalog VALUES('supdupe2','SUPDUPE2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SUPDUPE2.LHA','converter','XIM','converter',NULL,NULL,NULL,'~~~~~~~~~ Copyright 1994-1995 fAktOR^iNDEPENDENT AmiExpress v4.x XIM door',replace('                SuperDupe\n                ~~~~~~~~~\n  Copyright 1994-1995 fAktOR^iNDEPENDENT\n         AmiExpress v4.x XIM door\n \n       The converter now works 100%\n\n   The only DupeChecker worth it''s name\n\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                                                .------''\n             `------------------------------------------------''\n','\n',char(10)),NULL,'auto-added',21592,6,0,NULL,NULL,'tvk_dc1','scan',1780048759);
INSERT INTO door_catalog VALUES('supedupe','SUPEDUPE.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SUPEDUPE.LHA','Converter','XIM','Converter',NULL,NULL,NULL,'~~~~~~~~~ Copyright 1994-1995 fAktOR^iNDEPENDENT AmiExpress v4.x XIM door',replace('                SuperDupe\n                ~~~~~~~~~\n  Copyright 1994-1995 fAktOR^iNDEPENDENT\n         AmiExpress v4.x XIM door\n \n   The only DupeChecker worth it''s name\n \n         ( Released 1995-08-21 )\n\n','\n',char(10)),'SuperDupe.doc',replace('\n\n\n\n\n\n\n\n                               _ _______\n             _________  _______   /    / _______ _________ ________\n    _ _______\______ ¬\_\_____¬\_/ ___/¬\__    /_\__   _ ¬\______ ¬\_ __\n              /    /___/   __/  /  \__ __/   ___/_/    /   /    /___/   |\n             /   ___/ /    /   /    /  \/    /   /    /   /    /        |\n        _ __/____/   /____    /____/   /____    /____    /____/__ _ _ __|\n           /            /____/   /____/   /____/kRm/____/    /\n\n     " THE NEXT GENERATION DUPECHECKER FOR AMIEXPRESS BASED SYSTEMS "\n\n                    SuperDupe is an established public\n             Copyright, from 1994-1995 by faktor/independent.\n\n\n         Original file size of superdupe is 9724 ($000025fc) bytes\n\n\n\n\n\n\n\n\n\n\n\n\nINTRODUCTION\n************\n\nMuch appreciated for you who have taken the time to view this text, as there\nare words in this text that I wish you to read.\n\nI would like to start this text off with a brief history of my reason\nproducing Superdupe. I have come to the conclusion that I had the knowledge\nto program a serious dupe checker. Since the scene is lacking a quality\ndupe checker for AmiExpress I took the opportunity.\n\nI have been programming Superdupe for the past year and will continue to\ndevelop it with as much sincere effort as always.\n\nSuperdupe is by release the far most reliable, robust and fastest\ndupe checker. The combination of safe and intelligent code with new thinking\nmade it the unbeatable solution.\n\n\nTHE FEATURES\n************\n\nI''m using an amazingly fast (intelligent) read routine combined with a\nclever usage of logfiles instead of the original filelistings.\n This results in very quick checking and operating. Take a look at the\nfollowing benchmarking;\n\n  A Logfile containing 200000 thousand 12 letter filenames will be scanned\n  thru in 4.7 seconds (more or less).\n\nEquipment used was A2000 G-Force 68030 25mhz 60ns Ram and a ReadSize of \n1MB.\n  \n\nSuperDupe is a replacement for your MultiStartDoor, because it is able to\nexecute a unlimited number of doors before and/or after itself.\n\n\nSuperDupe is able to move all the duplicate and/or private uploads to\nspecified path''s. This is of course optional.\n\n\nSuperDupe is able to delete all uploaded duplicates.\nThis is of course optional.\n\n\nIf you do not wish to delete duplicate files, SuperDupe will point out with\na marking in the Hold/Held file which file was a duplicate.\nHere is an example of a Held file:\n\nSER_V34.LHA  F  15250  07-26-95  A new faster and improved serial device for\n                                 using 28800 v34 modem. Just replace C=s own\n                                 serial.device with this one.\nAE.REA       <- WAS A DUPLICATE\nAE.REA       F  15205  08-03-95  An announcement from Joseph Hodge.\n\nSo the first file was a normal Private upload, but AE.REA was a dupe file.\n\n\n\nAs SysOp you are authorized to specify the I/O Size, meaning how much\nSuperDupe shall read from the Logfile at every read.\nPublic memory is taken. This means all memory, with Fast Ram first.\n\n\nSuperDupe can be dismisted be letting users with a specified security\nlevel skip the entire process. This is of course optional.\n\n\nSuperDupe will print out the number of duplicate uploads a user has at time\nwhen a duplicate file is found.\n\n\nSuperDupe is able to show a textfile as comment for every duplicate\nupload the user sent. This is of course optional.\n\n\nCertain conferences can be "dupe check free".\n\n\n\nINSTALLATION\n************\n\n\nSuperDupe will need the following to run:\n\n       AmigaDOS v2++\n       AmiExpress v3++\n       Libs:aedoor.library\n       Doors:SuperDupe/\n       Doors:SuperDupe/Texts/\n       Doors:SuperDupe/SuperDupe.info\n\n       SuperDupe MUST be installed in FILECHECK.info.\n\nTo convert all your filelistings the CLI utility named "Converter" must\nbe runned, or SuperDupe will not recognize duplicate files.\nThe converter shall only be runned ONCE. After you have converted all\nfilelistings, this file is no longer needed.\n The converter also creates a user configuration file which keep track of\nall users duplicates.\n\nHOW THE CONFIGURATE DOORS:SUPERDUPE/SUPERDUPE.INFO\n**************************************************\n\n    ReadSize= :Number of kilobytes to be read each time.\n Start_Doors= :Number of doors to be runned before SuperDupe (0=none)\n   End_Doors= :Number of doors to be runned after SuperDupe. (0=none)\n        Skip= :The security level and above that are allowed to skip the\n              :entire dupe-process.\nMove_Private= :The directory to move ALL private uploads to.\n   Move_Dupe= :The directory to move ALL duplicates uploads to.\n  Delete_Dupe :If you want to delete ALL duplicate uploads.\n\n\n\n\nHOW TO EXECUTE DOORS BEFORE AND AFTER SUPERDUPE\n***********************************************\n\nExample of SuperDupe.info:\n\n\n	End_Doors=2\n      Start_Doors=1\n\nFollowing commands will be executed -> BBS:Commands/BBSCmd/End_Door1.info\n				       BBS:Commands/BBSCmd/End_Door2.info\n\n				    -> BBS:Commands/BBSCmd/Start_Door1.info\n\n\nLet''s say you want ByteLog runned before and then ConfTop after,\nthen the following should be made:\n\n	End_Doors=1\n      Start_Doors=1\n\nBBS:Commands/BBSCmd/Start_Door1.info = Access=10\n				       Type=XIM\n				       Location=Doors:ByteLog\n\nBBS:Commands/BBSCmd/End_Door1.info   = Access=10\n				       Type=XIM\n				       Location=Doors:conftop\n\n\n\nTHE DUPLICATE COMMENT MESSAGES\n******************************\n\nIf a user has uploaded 5 duplicates, and now sends the 6th, SuperDupe\nwill then try to show the file "Doors:SuperDupe/Texts/Message6.txt"\n\n/X MCI is supported when showing textfiles via SuperDupe.\n\n\nSET CONFERENCES SUPERDUPE FREE\n******************************\n\nIf you''d like to have one or several conferences ''DupeCheck Free'', then\nmake sure that a file called ''NODUPECHECK'' is located directly in these\nconferences. \n\n\n\nHOW TO CONTACT ME\n*****************\n\nIf you for any reason would like to get in touch with me, please forward\na message at any major BBS in Stockholm, Sweden.\n\nMy account name is: fAktOR & tRANCE\n\n','\n',char(10)),'{"ACCESS":"10","TYPE":"XIM","LOCATION":"Doors:ByteLog"}','auto-added',19158,3,0,NULL,NULL,'supedupe','scan',1780048759);
INSERT INTO door_catalog VALUES('sx_bs_01','SX-BS-01.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SX-BS-01.LHA',NULL,'XIM','ER#?DHQ#?HIHI.E_XE!@?',NULL,'YOP]--''','SX','.---] SUPPLEX [---/      //-------------. |______/\ _ ___  /       / - SUPPLEX -  | __/¯  __ //____ ¯\/     __/  bRiNX 2dAY:  |',replace('                     /       /\n  .---] SUPPLEX [---/      //-------------.\n  |______/\ _ ___  /       / - SUPPLEX -  |\n__/¯  __ //____ ¯\/     __/  bRiNX 2dAY:  |\n ¬\____¬\/    ¬\         ¬\- bOARd StYlE -|\n_______________/ /\________\--[ VOl.o1 ]--|\n  |:::::/       /  A bbS-ANSi-COllY 4 All |\n  |::::/      //  SYSOPS ANd thEiR bbS''S! |\n  `---/       /---[21.o6.95 dONE bY YOP]--''\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 03-10-18  TIME: 10:46:45  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',119100,12,0,NULL,NULL,'sx_bs_01','scan',1780048759);
INSERT INTO door_catalog VALUES('sx_fbw11','SX-FBW11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SX-FBW11.LHA',NULL,'XIM','______  ________.___    /\    /\',NULL,NULL,'SX','/ _   /\/  ___/  |  //  //\\  / / /     / /\_  \\_\   /---///\\\/ /---------+ /__/__/ /  /  // / : \  ///  \\ /ARexx  ***|',replace('   ______  ________.___    /\    /\\n  / _   /\/  ___/  |  //  //\\  / /\n /     / /\_  \\_\   /---///\\\/ /---------+\n/__/__/ /  /  // / : \  ///  \\ /ARexx  ***|\n\__\__\_\____// /  |__\//^^^^/ $X-Group  **|\n|       \____/ \\__| _ //   / /\/X Doors  *|\n+----+\              ///   /_/  \\\Presents|\n       +-----------------------------------+\n                   --> FeedBacK Writer v1.1r\n  240% Faster Dn v1.0 - Supports multi cfg\n','\n',char(10)),'FEEDBACKW.GUIDE',replace('@DATABASE "Default"\n@NODE "MAIN" "ASX/X-FEEDBACKWRITER1.1"\n@TOC "MAIN"\n                    ______  ________.___    /\    /\\n                   / _   /\/  ___/  |  //  //\\  / /\n                  /     / /\_  \\_\   /---///\\\/ /---------+\n                 /__/__/ /  /  // / : \  ///  \\ /ARexx  ***|\n                 \__\__\_\____// /  |__\//^^^^/ $X-Group  **|\n                 |       \____/ \\__| _ //   / /\/X Doors  *|\n                 +----+\              ///   /_/  \\\Presents|\n                        +-----------------------------------+\n\n\n        ---------------------------------------------------------------\n        FEEDBACK WRITER v1.1 by 0xYrh / $X/X AReXX 4 /X / BlacK Bit bbs\n        ---------------------------------------------------------------\n\n                                   *-------*\n                                   *-------*\n\n                            @{"1.......InTr0........1" LINK "INTRODUCTION"}\n                            @{"2....In$tallAti0n....2" LINK "INSTALLATION"}\n                            @{"3......ExAmPl&.......3" LINK "EXAMPLE"}\n                            @{"4....CoNfiGuRe It....4" LINK "CONFIGURE"}\n                            @{"5..CoPyRiGHt$ Inf0s..5" LINK "COPYRIGHT"}\n                            @{"6.....GrEeTiNg$......6" LINK "GREETINGS"}\n@ENDNODE\n\n@NODE "INTRODUCTION" "FEEDBACK WRITER 1.1"\n@TOC "MAIN"\n                            --- IntroDu<TioN : ---\n\nFeedback Writer is a more flexible replacement of the <C> command of /X.\nIt allows you to use a list of $y$op$ per every conference.\n\n                           --- ChaNgEs to Ver1.1 ---\n\nSped up initialization routine of the door (240% faster!)\nNo OtHeR!\n\n@ENDNODE\n\n@NODE "INSTALLATION" "How To Install FW1.1"\n@TOC "MAIN"\n                            --- InStallAtioN : ---\n\nCopy FEEDBACK.AIM in DOORS:\nCopy C.INFO in :CoMMAnDS/BBSCMD/\nMake the main configuration file in S: called FEEDBACK.CFG\nFinally If you want, make others cfg files located in :CONFx/\n\n@ENDNODE\n\n@NODE "EXAMPLE" "A CFG E.g."\n@TOC "MAIN"\n                               --- ExAmpLe : ---\n\n1.> dir s:\n\nstartup-sequence\nuser-startup\n...\nFEEDBACK.CFG\n\n\n1.> dir bbs:conf5\n\nuploads (dir)\npartupload (dir)\n...\nFEEDBACK.CFG\n\n\nSo if ya have 8 conference, in whole the conferences the pgm will use the cfg\nfile located in S:, except conference 5, which will use the cfg file located in\n:CONF5/...\n\n@ENDNODE\n\n@NODE "CONFIGURE" "How To Configure FW1.1"\n@TOC "MAIN"\n                         --- How T0 <oNfiGUre iT : ---\n\nEvery cfg file must have in the odd lines (1-3-5-7..) the name of the $y$op.\n(Max 15 Chars) The even lines must contain the comments (max 40 chars).\n\ne.g.:\n\nFILE:< S:FEEDBACK.CFG > (or :CONFx/FEEDBACK.CFG)\n-8X-----------------Cut Here-----8X-------\n0xYRh\nD $y$0p of Black Bit BB$!\nVenus\nD first <o-$y$0p\nChassis\nD $econd <o-$y$0p\n-8X-----------------Cut Here-----8X-------\n\n@ENDNODE\n\n@NODE "COPYRIGHT" "Informations"\n@TOC "MAIN"\n                           --- c0pYriGht InF0$ : ---\n\nThis program is freely distributable at only two conditions:\n\n1> THE FILES IN THE ORIGINAL LHA-PACKET MUST NOT BE MODIFIED WITHOUT AUTHOR\n   AUTORIZZATION\n2> THE CONTENTS OF THIS PACKE CANNOT BE CHANGED (EXCEPT BBS ADDS)\n\n\n                   CONTENTS OF ARCHIVE  >>> SX-FW11.LHA <<<\n\n+\nS	BBS/\nX		DOORS/\n-			FEEDBACK.AIM  (Main AIM program)\nF		COMMANDS/\nW			BBSCMD/\n1				C.INFO  (Info file command)\n1\n.	FEEDBACKW.DOC  (English ASCII Doc File)\nL	FEEDBACKW.GUIDE  (English AMIGAGUIDE Doc File)\nH	BlacKBit.p0$tEr \ \nA	BlackBIT.TxT    / (My BBS AddS)   \n|	SX-AX.DOC         (/X Arexx Doors Development Group InfoS)\n+	\n@ENDNODE\n\n@NODE "GREETINGS" ">>> BlacK BiT BBS <<<"\n@TOC "MAIN"\n                            Have FuN!  &  C U S00n!\n                   0xYrh / $X/X AReXX 4 /X of BlacK BiT BBS\n                           ______                              ______\n              ____________/     / ________  ________________  /     /\n           ___\_____     /     / _\_____  \ \     _     /   |/     /\n           \       /  __/     /_/_    _/   \/     /____/   _/   __/\n            \    _/    \    _/    \   \     \   _/    /    \     \_\n            /__________/__________/____\     \_______/______\_____/\n                                        \_____\\n               StAff:         o - -- ---  ____  --- -- - o\n               ~~~~~~        ____________/   /________/\\n             0xYrh/V0/SX  ___\_____     /   //         / Music WoRLd\n              Venu$/V0    \       /  __/   / \_    ___/  HeaRtQuaKe!\n             Chassis/CHA   \    _/    \   /   /   /      ~~~~~~~~~~~\n                           /__________/ _/   /___/0x\n                                      \/\n A2ooo `030`882 * o$3.1 * ZyX 16800 6.13 * /X 4.4 * > V0 IHQ < * > SX HQ <\n\n  Music Modules/Seven Valley Records Support/Dj News Support/Dj Music Support\n                 Cloud City Support/AreXX Support/AmiX Support\n  V0\CHA Music Module Writers HQ -- SX-AX/X AmiExpress AreXX Doors Devel. HQ\n                             Ami & PC Public Domain\n\n                      N+U+M+B+E+R : +39 / 75 / 584 82 46\n\n@ENDNODE\n\n','\n',char(10)),NULL,NULL,11210,3,0,NULL,NULL,NULL,'scan',1780048759);
INSERT INTO door_catalog VALUES('sx_lhc11','SX-LHC11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SX-LHC11.LHA',NULL,'XIM','______  ________.___    /\    /\',NULL,'0xYRH/SX/V0','SX','/ _   /\/  ___/  |  //  //\\  / / /     / /\_  \\_\   /---///\\\/ /---------+ /__/__/ /  /  // / : \  ///  \\ /ARexx  ***|',replace('   ______  ________.___    /\    /\\n  / _   /\/  ___/  |  //  //\\  / /\n /     / /\_  \\_\   /---///\\\/ /---------+\n/__/__/ /  /  // / : \  ///  \\ /ARexx  ***|\n\__\__\_\____// /  |__\//^^^^/ $X-Group  **|\n|       \____/ \\__| _ //   / /\/X Doors  *|\n+----+\              ///   /_/  \\\Presents|\n       +-----------------------------------+\n       LhA ChecK v1.1u by 0xYRH/SX/V0\nFully cng.ble /X Checker. Supp. Add/Str/Bann\n        Public Unregistered Release\n','\n',char(10)),'CSA.DOC',replace('\n		   ______  ________.___    /\    /\\n		  / _   /\/  ___/  |  //  //\\  / /\n		 /     / /\_  \\_\   /---///\\\/ /---------+\n		/__/__/ /  /  // / : \  ///  \\ /ARexx  ***|\n		\__\__\_\____// /  |__\//^^^^/ $X-Group  **|\n		|       \____/ \\__| _ //   / /\/X Doors  *|\n		+----+\              ///   /_/  \\\Presents|\n		       +-----------------------------------+\n\n           - -- -*------------------------------------------*- -- -\n                CHECKSTRIPADD v1.1 by 0XYRH/V0/SX/BlacKBiT BBS\n           - -- -*------------------------------------------*- -- -\n\n                             UNREGISTERED VERSION\n\n###WhAT???---------------------------------------------------------------------\n\nCSA is a little tool for /|MiXpRe$$ that is a simple replacement of the LHA/LZH\ninternal checker.\n\nCSA Tests the uploaded archive, Strips the other BBS Bulls, Adds your BBS Bulls\nand  it can Add an Uploader-Banner (Poster), with Uploader name, date & time of\nthe upload.\n\n         >>> This Arexx Code needs REXXSUPPORT.LIBRARY Installed. <<<\n\n\n###SPEcIAL FeATURE$???---------------------------------------------------------\n\nIt`s FULLY (!) Configurable...\n\n-FEAT 1 : CHECK\nYou can override the whole check process for files length above X bytes...\n\n-FEAT 2 : STRIP BULLS\nYou can override the B-STRIP Function.  Else you must create a script file with\nname (Wild Allowed) of the bulls 2 be stripped.\n\n-FEAT 3 : ADD BULLS\nYou  can  override the B-ADD Function.  Else you must create a script file with\nfilename (Wild Allowed) & full path of the Bull(s).\n\n-FEAT 4 : POSTER\nWith this function (only registered users!) you can create a Bull where the\nprogram automatically will add uploader name, date & time of the upload. Then\nthis compiled bull will be added in the archive.\n\n-FEAT 5 : Sorry, no more! (Isn`t enough?!?!?)\n\n\n###INSTALLATION: -------------------------------------------------------------\n\nCopy the REXX-Coded Main File (CSA.REXX) in the REXX: Directory.\nCopy the FCheck icons in the BBS:FCHECK/ Directory.\nCopy the Files LHACHECK.STRIP & LHACHECK.ADD in the S: Directory.\n\n\n###CONFIGURE IT!: ------------------------------------------------------------\n\nTOOLTYPE§::::::\n\nOpen the BBS:FCHECK/ Drawer.\nOpen the LHA icon info (Amiga-I).\n\nThe tooltypes that you can see are:\n\nCHECKER=rx csa  ---> The syN of the Rexx prg (Don`t Change!)\n\nERROR.1=Archive Corrupted!!!  ---> /X Error Check Occourrence (Don`t Change!)\n\n\nOPTIONS   =   SAP@BBS:BULLS/BlacKBiT.P0sTer@ram:@0\n              ^^^ ^^^^^^^^^^^^^^^^^^^^^^^^^ ^^^^ ^\n               |              |               |  |\n               |              |               |  FileChecK ByteLimit\n               |              |               |\n               |              |               WorKDir\n               |              |\n               |              Poster Path+Name\n               |\n               CSA Options\n\nCSA OPTIONS:\n\nS = Strip the BBS ADDS in the archive. Pattern listed in S:LHACHECK.STRIP\nA = Add yours BBS ADDS in the archive. Path+Name listed in S:LHACHECK.ADD\nP = Add your POSTER in the archive. Path+Name explained in the 2nd option\n\nPOSTER PATH+NAME:\n\nThis is the path and the name of your poster name (Only Reg. Users!)\n\nWORKDIR:\n\nThe Work Directory. (Faster in Ram:)\n\nFILECHECK BYTELIMIT:\n\nThis  is  a numeric option.  You can specify any POSITIVE value (0..infinite!).\nIf a file is greater or equal than this number the prg will check it.  Else the\nChecker Function will be overridden.\n\n -->>> REMEMBER!!! BETWEEN EVERY OPTION YOU MUST INSERT A ''@'' (ASCII=64) <<<--\n\n\nS: FiLES :::::\n\nYou must now edit the files in S: (LHACHECK .ADD & .KILL).\n\nExample:\n\nLHACHECK.ADD\n\n---------------X8-CUT---------------------------\nBBS:bulls/BlacKBiT.DispLaYmE\nBBS:bulls/BlacKBiT.INF\n---------------X8-CUT---------------------------\n^^^^^^^^^ ^^^^^^^^^^^^^^^^^^^^^\nPath      Scripts Filenames\n\nLAHCHECK.STRIP\n\n---------------X8-CUT---------------------------\n#?.displayme\n#?lha.fix#?\n---------------X8-CUT---------------------------\n^^^^^^^^^^^^^^\nStrip Patterns\n\n\n###FUTURE IMPROVEMENTS: ------------------------------------------------------\n\nCPS & Baudrate in the POSTER\nConfigurable > or <LIMIT FileChecK Bypass procedure\nSpeed improvement\n\n\n###HOW TO REGISTER: ----------------------------------------------------------\n\n1-Call BlacK BiT BBS (+39/75/5848246).\n2-Enter with the handle <SXREG> (Password: SXREG)\n3-Fill the Registration Form launching the door <SXREG>\n4-Leave the BBS\n5-Send a contribution of 5$ (or 10.000 Lire) to the address specified in the\n  door.\n6-After 3-4 days recall BlacK BiT\n7-Download your registered program!\n\n>>>  Future  registrations for others SX programs will cost you only 3$ (5.000\n     Lire) per program!\n\n\n###COPYRIGHTS INFORMATIONS: --------------------------------------------------\n\nThe  Unregistered  Version is  Freely  Distributable,  but it can`t in any way\nmodified without author autorizzation.\n\n\n###SEE YA! -------------------------------------------------------------------\n\n                           ______                              ______\n              ____________/     / ________  ________________  /     /\n           ___\_____     /     / _\_____  \ \     _     /   |/     /\n           \       /  __/     /_/_    _/   \/     /____/   _/   __/\n            \    _/    \    _/    \   \     \   _/    /    \     \_\n            /__________/__________/____\     \_______/______\_____/\n                                        \_____\\n               StAff:         o - -- ---  ____  --- -- - o\n               ~~~~~~        ____________/   /________/\\n             0xYrh/V0/SX  ___\_____     /   //         / Music WoRLd\n              Venu$/V0    \       /  __/   / \_    ___/  HeaRtQuaKe!\n             Chassis/CHA   \    _/    \   /   /   /      ~~~~~~~~~~~\n                           /__________/ _/   /___/0x\n                                      \/\n A2ooo `030`882 * o$3.1 * ZyX 16800 6.13 * /X 4.4 * > V0 IHQ < * > SX HQ <\n\n  Music Modules/Seven Valley Records Support/Dj News Support/Dj Music Support\n                 Cloud City Support/AreXX Support/AmiX Support\n     V0/CHA Music Modules Writers HQ -- ASX/X /X AIM Doors Development HQ\n                             Ami & PC Public Domain\n\n                      N+U+M+B+E+R : +39 / 75 / 584 82 46\n\n\n0xYRH/V0/SX/BBBBS\n\n                 This program has been released on 07/Oct/1994\n','\n',char(10)),NULL,NULL,7582,3,0,NULL,NULL,NULL,'scan',1780048759);
INSERT INTO door_catalog VALUES('sx_lu10','SX-LU10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/SX-LU10.LHA',NULL,'XIM','______  ________.___    /\    /\',NULL,NULL,'SX','/ _   /\/  ___/  |  //  //\\  / / /     / /\_  \\_\   /---///\\\/ /---------+ /__/__/ /  /  // / : \  ///  \\ /ARexx  ***|',replace('   ______  ________.___    /\    /\\n  / _   /\/  ___/  |  //  //\\  / /\n /     / /\_  \\_\   /---///\\\/ /---------+\n/__/__/ /  /  // / : \  ///  \\ /ARexx  ***|\n\__\__\_\____// /  |__\//^^^^/ $X-Group  **|\n|       \____/ \\__| _ //   / /\/X Doors  *|\n+----+\              ///   /_/  \\\Presents|\n       +-----------------------------------+\n              LAST UPLOADS 1.0\nCrEaTeS KooL BullS witH LaSt X Uploads Listd\n                 MUST HAVE!\n','\n',char(10)),'LASTUP.GUIDE',replace('@DATABASE "Default"\n@NODE "MAIN" "ASX/X-LASTUPv1.0"\n@TOC "MAIN"\n                    ______  ________.___    /\    /\\n                   / _   /\/  ___/  |  //  //\\  / /\n                  /     / /\_  \\_\   /---///\\\/ /---------+\n                 /__/__/ /  /  // / : \  ///  \\ /ARexx  ***|\n                 \__\__\_\____// /  |__\//^^^^/ $X-Group  **|\n                 |       \____/ \\__| _ //   / /\/X Doors  *|\n                 +----+\              ///   /_/  \\\Presents|\n                        +-----------------------------------+\n\n            -*-- --- ------------------------------------ --- --*-\n            LASTUP v1.0 by 0xYrh / @{"$X/X AReXX 4 /X" LINK "ASX"} / BlacK Bit bbs\n            -*-- --- ------------------------------------ --- --*-\n                                   *-------*\n                                   *-------*\n\n                            @{"1.......InTr0........1" LINK "INTRODUCTION"}\n                            @{"2....In$tallAti0n....2" LINK "INSTALLATION"}\n                            @{"3......ExAmPl&.......3" LINK "EXAMPLE"}\n                            @{"4...Program..Logic...4" LINK "PROGRAM"}\n                            @{"5..CoPyRiGHt$ Inf0s..5" LINK "COPYRIGHT"}\n                            @{"6.....GrEeTiNg$......6" LINK "GREETINGS"}\n@ENDNODE\n\n@NODE "ASX" "ASX4/X AIM DEVELOPERS GROUP"\n@TOC "MAIN"\n\n                      WhAt`S ArExx Sx For AmiExpRess????\n\n It`s an AIM Arexx Developers Group. It was born in the july of 1994. Its only\n                 member is 0xYrH/V0/SX/BlacK BiT BBS (mE!)...\n\n                        Join me and support me please!\n\n  If you like my programs then call my BBS... 80% of the BBS doors are mine!\n\n                                      CU!\n@ENDNODE\n\n@NODE "INTRODUCTION" "LASTUP v1.0"\n@TOC "MAIN"\n                            --- IntroDu<TioN : ---\n\nLastUploads v1.0 is a small utility that allows you to create an last x uploads\nbulletin, where X is a number from 1 to infinite ;>\n\n                                 :::CREDITS:::\n\n                    Code : 0xYRH / V0 / SX / BlacK BiT BBS\n\n                    Idea : Dr. G / Ram Jam / The HoUsE BBS\n\n                BetaTest : Dr. G / Ram Jam / The HoUsE BBS\n                           0xYRH / V0 / SX / BlacK BiT BBS\n\n\nHere an example of its output:\n\n.-----------------------------------------------------------------------------.\n|             LAST UPLOADS v1.0 BY 0XYRH/V0/SX/BlacK BiT BBS                  |\n|                       : TODAY''S LAST <16> U`Ls ARE :                        |\n+--------------+---------+------+----------+-------+---------------------+----+\n|   FILENAME   |  BYTES  | KBPS |  ULDATE  | UTIME |   UPLOADER HANDLE   | CN |\n+--------------+---------+------+----------+-------+---------------------+----+\n| BLACKBIT.TXT |   10689 | 76.8 | 10-21-94 | 17:35 |        0xYRH        | 01 |\n| BB-ADV.LHA   |    4388 | 76.8 | 10-21-94 | 16:16 |        0xYRH        | 01 |\n| YDL-WW06.LHA |   27087 | 76.8 | 10-21-94 | 14:34 |        0xYRH        | 04 |\n| MDBCU19C.LHA |   46903 | 76.8 | 10-21-94 | 14:17 |        0xYRH        | 10 |\n| EMP-DD21.LHA |   19821 | 76.8 | 10-21-94 | 14:17 |        0xYRH        | 10 |\n| VTGABBER.LHA |  352139 | 76.8 | 10-21-94 | 15:26 |        0xYRH        | 04 |\n| TLMAN20.LHA  |  580051 | 76.8 | 10-21-94 | 14:59 |        0xYRH        | 04 |\n| AGWR1$02.LHA |   27493 | 76.8 | 10-21-94 | 14:58 |        0xYRH        | 04 |\n| PFS95.LHA    |  240350 | 76.8 | 10-21-94 | 14:48 |        0xYRH        | 04 |\n| INJECT2.LHA  |   97949 | 76.8 | 10-21-94 | 14:47 |        0xYRH        | 04 |\n| FREQS.LHA    |    4150 | 76.8 | 10-21-94 | 14:47 |        0xYRH        | 04 |\n| EX4-PR24.LHA |   64419 | 76.8 | 10-21-94 | 14:47 |        0xYRH        | 04 |\n| EX4-ASRC.LHA |   16995 | 76.8 | 10-21-94 | 14:47 |        0xYRH        | 04 |\n| 1084SIZ.TXT  |   13069 | 76.8 | 10-21-94 | 14:46 |        0xYRH        | 04 |\n| TEXTFILD.LHA |   62777 | 76.8 | 10-19-94 | 21:33 |        0xYRH        | 04 |\n| MUCHMR44.LHA |   91568 | 76.8 | 10-19-94 | 21:31 |        0xYRH        | 04 |\n.-----------------------------------------------------------------------------.\n|           TODAY''S U''LD BYTES : 2536789   TODAY''S U''LD FILES : 8             |\n`-----------------------------------------------------------------------------''\n\nNote that the first file line is the last uploaded file in the BBS!\n\nLastUp is written in ARexx language.\nThe packet contains two ARexx codes:\n\nLastUp.AIM - AIM (AmiExpress AReXX Interface Module) DOOR.\n             This PRG could be inserted as an EXAMINE Door.\n             (MOst of SysOp have already the EXAMINE Door, to solve this\n              problem rename the EXAMINE.INFO to EXAMINE1.INFO)\n\nLastUp.REXX - ARexx program. This could be executed in the LOGOFF batch script\n              as an ARexx script.\n\n@ENDNODE\n\n@NODE "INSTALLATION" "How To Install LastUp v1.0"\n@TOC "MAIN"\n                            --- InStallAtioN : ---\n\n1.Copy all files cointeined in the extractred dirs into respectives BBS:\ndirectories.\n\n2.Edit the file REXX:LastUp.cfg and configure it\n\n3.Launch : RX LASTUP REXX:LASTUP.CFG\n                     ^^^^^^^Configuration path & file arg\n  (this step is needed to create a floating cfg reference for AIM file)\n\n4.Edit your batch logoff script and add to it the line:\n\nRX LASTUP REXX:LASTUP.CFG\n\nI think that`s all. (:>)\n\n@ENDNODE\n\n@NODE "EXAMPLE" "A CFG E.g."\n@TOC "MAIN"\n\n----------X8--CuT-HeRe!-------------------------------------------------------\nBBS:BULLS/LASTUP.STORAGE\n18\nBBS:BULLS/LASTUPS.TXT\n1\n\n1\n----------X8--CuT-HeRe!-------------------------------------------------------\n\n                         ::: CFG LINES DESCRIPTION:::\n\nLine 1 : LastUploads Log / Storage file\nLine 2 : Max number of uploaded files showed\nLine 3 : Output Bull\nLine 4 : 1 = Bull start with cls 0 = Bull don`t start with cls\nLine 5 : PlayPen Path (Blank line will use : BBS:NODEx/Playpen/)\n         If you have different playpens dir (one per every node) you must\n         write the path of your personal playpen dirs using the simbol ''@''\n         (ASCII = 64) at the place of the node number ... E.g:\n\n         BBS:PLAYPEN@/ = BBS:PLAYPEN0/ (for node 0) etc...\nLine 6 : 1 = Center Uploader Handle\n         0 = Do not center Upl. Handle\n\n@ENDNODE\n\n@NODE "PROGRAM" "LOGIC"\n@TOC "MAIN"\n\n                            --- PrograM LoGiK : ---\n\nWell,  it`s  simple...   The  AIM Door is launched after the user upload.  This\nDoor retrieve user & upload informations and put it into a script log file (you\ncan   view   it   as   a   ULOG).    The   standard   path  &  file  output  is\n"BBS:LASTUP.STORAGE", but you can modify it simply editing the cfg file located\nin REXX:.\n\nAfter,  when  the  user logs off, the batch file execute the main REXX program.\nThis  prg  read  the  STORAGE file of AIM door and exits the output in the bull\n(selected in the cfg).\n\nThat`s all, folks!\n\n@ENDNODE\n\n@NODE "COPYRIGHT" "Informations"\n@TOC "MAIN"\n                           --- c0pYriGht InF0$ : ---\n\nThis program is freely distributable at only two conditions:\n\n1> THE FILES IN THE ORIGINAL LHA-PACKET MUST NOT BE MODIFIED WITHOUT AUTHOR\n   AUTORIZZATION\n2> THE CONTENTS OF THIS PACKE CANNOT BE CHANGED\n\n---> The program is distributed "as Is"... I could`nt give you any type of\nwarranty about using this program...\n\n\nBETATEST NOTES:\n\nThis program has been betatested for 15 days.  The first Beta version (1.0) had\nno  problems  and  no  incompatibilities.   It  worx with all Amigas and all /X\nversion over the 3.10.  (Examine icon upgrade)\n\n@ENDNODE\n\n@NODE "GREETINGS" ">>> BlacK BiT BBS <<<"\n@TOC "MAIN"\n                           ______                              ______\n              ____________/     / ________  ________________  /     /\n           ___\_____     /     / _\_____  \ \     _     /   |/     /\n           \       /  __/     /_/_    _/   \/     /____/   _/   __/\n            \    _/    \    _/    \   \     \   _/    /    \     \_\n            /__________/__________/____\     \_______/______\_____/\n                                        \_____\\n               StAff:         o - -- ---  ____  --- -- - o\n               ~~~~~~        ____________/   /________/\\n             0xYrh/V0/SX  ___\_____     /   //         / Music WoRLd\n              Venu$/V0    \       /  __/   / \_    ___/  HeaRtQuaKe!\n             Chassis/CHA   \    _/    \   /   /   /      ~~~~~~~~~~~\n                           /__________/ _/   /___/0x\n                                      \/\n A2ooo `030`882 * o$3.1 * ZyX 16800 6.13 * /X 4.4 * > V0 WHQ < * > SX WHQ <\n  Music Modules/Seven Valley Records Support/Dj News Support/Dj Music Support\n                 Cloud City Support/AreXX Support/AmiX Support\n  V0\CHA Music Module Writers HQ -- SX-AX/X AmiExpress AreXX Doors Devel. HQ\n                             Ami & PC Public Domain\n\n                      N+U+M+B+E+R : +39 / 75 / 584 82 46\n@ENDNODE\n\n','\n',char(10)),NULL,NULL,9589,3,0,NULL,NULL,NULL,'scan',1780048759);
