INSERT INTO door_catalog VALUES('taca113','TACA113.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TACA113.LHA',NULL,'XIM','TACall.exe',NULL,'ThE',NULL,'Converts your Tempest Callerslogs to /X Callerslog - FOR USING ALL /X UTILS Done by ThE BiRD - /X & TEMPEST DISTRIBUTOR',replace('  Tempest > AmiExpress Callerslog Converter\n   Converts your Tempest Callerslogs to /X\n    Callerslog - FOR USING ALL /X UTILS\n Done by ThE BiRD - /X & TEMPEST DISTRIBUTOR\n.------------------------------------------.\n| v1.13   LightSpeed Hard&Software   v1.13 |\n| A Utility for /X V3.x & Tempest v3.24 !! |\n`------------------------------------------''\n UPDATE - UPDATE - UPDATE - UPDATE - UPDATE\n','\n',char(10)),'TACALL.doc',replace('       .----------------------------------------------------------.\n       |      Tempest-Amiexpress Callerslog - Converter v1.13     |\n       |    Written by Jens Langner - LightSpeed Hard&Software    |\n       `----------------------------------------------------------''\n\n                              DOCUMENTATION:\n                              ~~~~~~~~~~~~~\n\nWhat is this Util for ?\n~~~~~~~~~~~~~~~~~~~~~~~\nThis Utility is a Callerslog Converter for Tempest BBS`s. With this Util\nyou can convert your Tempest Callerslog at every logoff to an /X Callerslog\nso that you can use ANY /X LastCallers or TOP UPLOADERS etc. Utility.\n\nWhy i wrote that Utility ?\n~~~~~~~~~~~~~~~~~~~~~~~~~~\nI wrote that utility because i wanted to make Tempest more /X compatible,\nand with that utility i think we are in the best way to make it 100%\ncompatible. There are MANY /X LastCallers, Top Uploaders etc. Utilities\nand now you can use all that utilities with Tempest, too.\n\nHow it works ?\n~~~~~~~~~~~~~~\nAll you have to do is add the following line to you Logoff.bat files of\nyour utility.\n \n---- cut here ----\nTACALL.exe TEMPEST:logs/Callerslog-[x] BBS:NODE[x]/Callerslog\n---- cut here ----\n\n[x] - The Node Number\n\nAnd if you have a allready installed AmiExpress you just have to start the\n/X Utilities after this Utility. The Most LastCallers etc. will search in\nthe BBS:Node[x]/Callerslog file for their Information.\nIf you don`t have a installed AmiExpress version you have to Assign BBS:\nto TEMPEST: and make a directory NODE[x] for every node you have.\nI Think that will be all for now...\n \n\nHistory !\n~~~~~~~~~\n\nv1.12 - First Release at 15.11.1994\n\nv1.13 - Little Bugfix in the Upload Convertation !\n\n\nBugReports & Ideas !\n~~~~~~~~~~~~~~~~~~~~\nIf you got any BugReports or Ideas for me Call my BBS :\n \nMETAL DECADE BBS - /X & TEMPEST DISTRIBUTOR - +49-(0)711-776380\n\nThanx & Greetings !\n~~~~~~~~~~~~~~~~~~~\nThanks must go to:\n \nMichael Bockert         - For his cool Tempest Updates\nVince                   - For beeing a cool friend\nCasa Nova               - For letting me Beta Test the TMS\nR.Vinco                 - For the cool TMS Server\nJoseph Hodge            - For his cool AmiExpress\nThe Outlaw              - For beeing a good friend\n\nand to all other peoples who helped me with that utility and TEMPEST.\n\nTEMPEST DISTRIBUTION:\n~~~~~~~~~~~~~~~~~~~~\n                                                                            \n                    TEMPEST AND AMIEXPRESS DISTRIBUTOR                      \n              _|____  ______________._________/\    ___                     \n               |    \/    |o   _    |        /  \  |   |     BIG TEMPEST &  \n  NO ILLEGAL   |o         ||  |_\___|o  |   //   \ |:  |      AMIEXPRESS    \n    WAREZ!     ||  \  /   |:   _|___||  |__//     \|_  |._/\   CONFERENCE   \n               |:  |\/|   |.  |_/   ||  | /.  /\    /  ||   \               \n               |.  |  |___|___|_____|___|/   ___\  /   |____/               \n               |___|          |          \  /    \/|___|     [eNf]          \n            _______  _________._________. \/\ ._______  _________.          \n SYSOP:    |       \|    _    |o   _    | /  \|       \|    _    |  OVER    \n ~~~~~     |o  |\_  \_  |_\___||  | \___|//   \o  |\_  \_  |_\___|   700    \n  ThE BiRD ||  | /   /   _|___||  |  ___//     \__| /   /   _|___  /X-UTILS \n           |:  |/   /:  |_/   |:  |_/  /.  /\    /|/   /:  |_/   |          \n           |___/___/|.  |_____|_______/   ___\  /_/___/|.  |_____|          \n                    | __|             \  /    \/       | __|                \n                    |/                 \/              |/                   \n                    |  + 4 9 - (0)7 1 1 - 7 7 6 3 8 0  |                    \n                                                                            \n             Offical Distribution BBS of Tempest BBS Software               \n            Offical Distribution BBS of AmiExpress BBS Software             \n                 Support BBS of LightSpeed Hard-&Software                   \n                                                                            \n  Call NOW for Newest Tempest & AmiExpress Versions - CHEAP HARD&SOFTWARE   \n','\n',char(10)),NULL,'auto-added',27271,3,0,NULL,NULL,'taca113','scan',1780048764);
INSERT INTO door_catalog VALUES('taca116','TACA116.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TACA116.LHA',NULL,'XIM','TACALL.cmp',NULL,'ThE',NULL,'Converts your Tempest Callerslogs to /X Callerslog - FOR USING ALL /X UTILS Done by ThE BiRD -> TEMPEST DISTRIBUTOR',replace('  Tempest > AmiExpress Callerslog Converter\n   Converts your Tempest Callerslogs to /X\n    Callerslog - FOR USING ALL /X UTILS\n   Done by ThE BiRD -> TEMPEST DISTRIBUTOR\n.------------------------------------------.\n| v1.16   LightSpeed Hard&Software   v1.16 |\n| A Utility for /X V3.x & Tempest v3.25+!! |\n`------------------------------------------''\n','\n',char(10)),'TACALL.doc',replace('       .----------------------------------------------------------.\n       |      Tempest-Amiexpress Callerslog - Converter v1.16     |\n       |    Written by Jens Langner - LightSpeed Hard&Software    |\n       `----------------------------------------------------------''\n\n NOW ONLY WORK WITH v3.25+    DOCUMENTATION:\n !!!!!!!!!!!!!!!!!!!!!!!!!    ~~~~~~~~~~~~~\n\nIncluded in Archive:\n~~~~~~~~~~~~~~~~~~~\nIn this version i included a RexxCompiled Version of the converter and a\nuncompiled version of the converter. the uncompiled is named TACALL.exe\nand the compiled is named TACALL.cmp .. I included this uncompiled version\nbecause the RexxPlus Compiler didn`t work on machines with CPU Cacheing and\nso it will crash under a A4000 and also A1200... \n\nWhat is this Util for ?\n~~~~~~~~~~~~~~~~~~~~~~~\nThis Utility is a Callerslog Converter for Tempest BBS`s. With this Util\nyou can convert your Tempest Callerslog at every logoff to an /X Callerslog\nso that you can use ANY /X LastCallers or TOP UPLOADERS etc. Utility.\n\nWhy i wrote that Utility ?\n~~~~~~~~~~~~~~~~~~~~~~~~~~\nI wrote that utility because i wanted to make Tempest more /X compatible,\nand with that utility i think we are in the best way to make it 100%\ncompatible. There are MANY /X LastCallers, Top Uploaders etc. Utilities\nand now you can use all that utilities with Tempest, too.\n\nHow it works ?\n~~~~~~~~~~~~~~\nAll you have to do is add the following line to you Logoff.bat files of\nyour utility.\n \n---- cut here ----\nTACALL.exe TEMPEST:logs/Callerslog-[x] BBS:NODE[x]/Callerslog\n---- cut here ----\n\n[x] - The Node Number\n\nAnd if you have a allready installed AmiExpress you just have to start the\n/X Utilities after this Utility. The Most LastCallers etc. will search in\nthe BBS:Node[x]/Callerslog file for their Information.\nIf you don`t have a installed AmiExpress version you have to Assign BBS:\nto TEMPEST: and make a directory NODE[x] for every node you have.\nI Think that will be all for now...\n \n\nHistory !\n~~~~~~~~~\n\nv1.12 - First Release at 15.11.1994\n\nv1.13 - Little Bugfix in the Upload Convertation !\n\nv1.14 - Just some bug fixes and convertation to new Callerslog Standard\nv1.16   of Tempest v3.25.....\n        \n\nBugReports & Ideas !\n~~~~~~~~~~~~~~~~~~~~\nIf you got any BugReports or Ideas for me Call my BBS :\n \nMETAL DECADE BBS - TEMPEST DISTRIBUTOR - +49-(0)711-776380\n\nThanx & Greetings !\n~~~~~~~~~~~~~~~~~~~\nThanks must go to:\n \nMichael Bockert         - For his cool Tempest Updates\nVince                   - For beeing a cool friend\nCasa Nova               - For letting me Beta Test the TMS\nR.Vinco                 - For the cool TMS Server\nBiLBO BaGGiNS           - ThX For Uploading me the "C" Stuff...\nIntercode               - For his great Support\nMurphy                  - For his calls ;)\nJoe Cool                - For being the CøøLest Guy Ever...\nNexus X                 - For his great uploads...\n\nand to all other peoples who helped me with that utility and TEMPEST.\n\nTEMPEST DISTRIBUTION:\n~~~~~~~~~~~~~~~~~~~~\n                                                                            \n············································································\n  _|____  ______________._________/\    ___                                 \n   |    \/    |o   _    |        /  \  |   |       sYSOPS:     /T\empest &  \n   |o         ||  |_\___|o  |   //   \ |:  |       """""""     AmiExpress   \n   ||  \  /   |:   _|___||  |__//     \|_  |._/\   ThE BiRD  Areas with over\n   |:  |\/|   |.  |_/   ||  | /.  /\    /  ||   \  NeXuS X       1000 Utils \n   |.  |  |___|___|_____|___|/   ___\  /   |____/                           \n   |___|          |          \  /    \/|___|     [eNf]                      \n _______  _________._________.\//\ ._______  _________.                     \n|       \|    _    |o   _    | /  \|       \|    _    |  nUMBERS:           \n|o  |\_  \_  |_\___||  | \___|//   \o  |\_  \_  |_\___|  """"""""           \n||  | /   /   _|___||  |  ___//     \__| /   /   _|___  +49-711-776380      \n|:  |/   /:  |_/   |:  |_/  /.  /\    /|/   /:  |_/   | +49-711-sOOn        \n|___/___/|.  |_____|_______/   ___\  /_/___/|.  |_____|                     \n         | __|             \  /    \/       | __|                           \n         |/                 \/              |/    A1200/o3o/5oMhZ ToWER     \n         |    /T\empest DiSTRiBUTiON SiTE   |     CheAP HaRD & SoFtWaRE     \n               LiGhTSpEED HaRD&SoFtWaRE                                     \n············································································\n','\n',char(10)),NULL,'auto-added',31498,2,0,NULL,NULL,'taca116','scan',1780048764);
INSERT INTO door_catalog VALUES('tacon100','TACON100.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TACON100.LHA',NULL,'XIM','TAConvert.exe','1.00','ThE',NULL,'Converts /X DirFiles to Tempest Catalogs Done by ThE BiRD - /X German Distributor .------------------------------------------.',replace('   Tempest <> AmiExpress Converter v1.00!\n  Converts /X DirFiles to Tempest Catalogs\n  Done by ThE BiRD - /X German Distributor\n.------------------------------------------.\n|         LightSpeed Hard&Software         |\n| A Utility for /X V3.x & Tempest v3.24+ ! |\n`------------------------------------------''\n','\n',char(10)),'TAConvert.doc',replace('       .----------------------------------------------------------.\n       |          Tempest <> Amiexpress Converter v1.00           |\n       |    Written by Jens Langner - LightSpeed Hard&Software    |\n       `----------------------------------------------------------''\n\n                              DOCUMENTATION:\n\nWho at hell has written this Utility??\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nMy Name is Jens Langner, other Guys know me under ''ThE BiRD''. Iam the\nGerman Distributor for AmiExpress. So many Guys will ask me why i write\nUtilities for Tempest also. \nI have swapped to Tempest because of writing this Utils and to make /X\nmore compatible to Tempest so that both programms can help each other.\n\nWhat is the Converter for ?\n~~~~~~~~~~~~~~~~~~~~~~~~~~~\nThis Converter is for people who has a AmiExpress BBS but want to swap to\nTempest. For that reason i wrote this Utility. With this Utility you can\nconvert your whole DirFile from AmiExpress Format to Tempest Format.\nI think that will be a very good Utility for many people. \n\n \nRequirements\n~~~~~~~~~~~~\nThe minimum requirements for running this Utility is a full installed \nAmiExpress v3.x+ and a fully installed Tempest v3.24+ version.\nIt is very important that you got the new Tempest v3.24+ with the new\nCatalogsystem, otherwise this utility will not work.\nAdditional you will need the CatalogIndexMaker Utility from Michael\nBockert. This Utility should be in the TEMPEST:utils Path.\n \nFunction\n~~~~~~~~\nThe Function of this Utility is very simple. Just get a Shell and start\nthe Utility with the Option "?". Then you will see all the needed Options.\n\nYour First Option will be the FullPath to you /X DirFile you want to\nconvert. The Second will be Conference (AREA) number of your Tempest BBS\nyou want to get it converted. And the third is the FULLPATH to your\nTEMPEST BBS Path. f.e.: TEMPEST:\n\ni.e.:\n------ cut here ------\n1> TAConvert.exe BBS:WAREZ/DIR1 2 TEMPEST:\n------ cut here ------\n\nThis will start the Utility and convert the BBS:WAREZ/DIR1 Dirfile to\nTEMPEST:Catalogs/Catalog.2.data & TEMPEST:Catalogs/Catalog.2.desc Files.\nWhen the Utility is finished with converting it will automatically start\nthe Utility TEMPEST:UTILS/CatalogIndexMaker. Now the whole DirFile should\nbe converted in Tempest format. If NOT ?!?!? Check you Pathes or\ncontact me.\n\nHistory & Greetings\n~~~~~~~~~~~~~~~~~~~\nAs a history i just want to say that the idea of this utility was born on\nswapping to Tempest. And i don`t wanted to LOCAL Upload all my files again\nbecause the Dates will be different to the originals. I thought writing a\nshort utility will be better.\n \nAnd i hope you like this Utility which is only usefull if you are \nregistered To AmiExpress or TEMPEST because many Guys spend lots of money\nto give you such Great programms, and you should support them !!\n \nMy Greetings go out to many people, but as now i only want to name some:\n \nAndy of Fastway BBS\nJoseph Hodge (ByteMaster)\nThe Outlaw\nMichael Bockert (The Skeleton)\n\nIf you are not a USER of AmiExpress and you want to register for it. Call the\nfollowing bbs`s in your local area. There you can get AmiExpress and it`s\nutilities.\n \n\n           The Last! Amiga BBS - USA -------- 1-305-456-0126\n           MainLine ------------ DENMARK ----- +45-981-53062\n           Channel X ----------- HOLLAND ---- +31-229-062535\n           Ruins of Wisdom ----- HOLLAND -- +31-(0)15-142400\n           DigitStar ----------- ITALY ---- +39-(0)40-632561\n           13TH HOUR BBS ------- ENGLAND - +44-[0]704-505845\n           Image World --------- FINLAND --- +358-71-2626775\n           Metal Decade -------- GERMANY ---- +49-711-776380\n           Chaos Line  --------- GERMANY ---- +49-5723-74340\n           Global Chaos -------- GERMANY ----- +49-8231-1068\n           Random Access ------- GERMANY --- +49-0471-417726\n           Traders Nation ------ SWEDEN ------ +46-176-55202\n\nThis program was written by the German Distributor & BetaTester "THE BIRD" \nwhichs BBS is called Metal Decade.\n','\n',char(10)),NULL,'auto-added',22545,3,0,NULL,NULL,'tacon100','scan',1780048764);
INSERT INTO door_catalog VALUES('tag_wa10','TAG!WA10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TAG!WA10.LHA','Tag!Wall','XIM','Tag!Wall',NULL,NULL,'TAG','_][__][__][__][__][__][__][__][__][__][__][_ [__][__][__][__][__][__][__][__][__][__][__] Tag!Wall Version 1.0 Code & Design cASE/dCS!',replace('_  __  __  __  __  __  __  __  __  __  __  _\n_][__][__][__][__][__][__][__][__][__][__][_\n[__][__][__][__][__][__][__][__][__][__][__]\n \nTag!Wall Version 1.0 Code & Design cASE/dCS!\nNot just another wall for AmiExpress 3.x/4.x\nCursor key support, selectable colors & more\n __  __  __  __  __  __  __  __  __  __  __\n[__][__][__][__][__][__][__][__][__][__][__]\n_][__][__][__][__][__][__][__][__][__][__][_\n','\n',char(10)),'Tag!Wall.DOC',replace('\n           .___________                     ____  ____  ____  ____ \n .______   |    __    /._________  ____  __[____][____][____][____]__  ____\n_|      |__|   __/   / |   _____/ [____][____][____][____][____][____][____]_\n\_   _____/    \_     \|   \     \ __[____][____][____][____][____][____][____\n |   \      _____\     \    \     \ ____[____][____][____][____][____][____] \n |_____     \     \___________     \ [____][____][____][____][____][____]·cASE\n __    \_____\   ____  ____   \_____\       .___________  [____] .______\n __]__  ____  __[____][____][___  _____:____|_   __    /.______  |  ____|_\n [____][____][____][____][____]  |     |     /  __/   / |  ____|_|  \     \\n  __[____][____][____][____][___ |    _|_   /   \_     \|  \     \   \     \\n [____][____][____][____][____]  |    \     ______\     \   \      ____     \\n  __[____][____][____][____]__   |______     \     \__________     \   \_____\\n                                        \_____\               \_____\\n\n ===( Introduction )==========================================================\n\n This is a /X Wall door with support for cursor keys, selectable colors and\n more. Take a look at the example output in this archive ( Tag!Wall.IFF )\n\n ===( Installation )==========================================================\n\n   You''ve seen it, you liked it, and now you want to install it? Well..\n\n - Create a directory in your Doors: path named Tag!Wall, and place the\n   executable there ( Doors:Tag!Wall/ ) This is important, since Tag!Wall\n   will place it''s DATA file in this directory\n\n - Install the door as usual (you should know how by now) in you\n   BBS:Commands/BBSCmd/ or BBS:Commands/SYSCmd/ directory\n   The door requires no more stack than default (4096) and should be ran\n   as a XIM module with the command Tag!Wall\n\n - Append this line to an #?.txt.gr file on your system\n   (For example the BBS:NODE{x}/LOGON.TXT.GR)\n\n   ~CC_Tag!Wall\n\n   It is important that the door will not be ran if the user has selected\n   non-ANSI output, since if it does it will look like SHIT! Therefore you\n   should leave the #?.txt files alone!\n\n - If you haven''t screwed up the door should now be installed\n\n ===( History )===============================================================\n\n Version 0.1 - First Beta Release\n Version 0.2 - Small ANSI bug fixed\n             - Cursor OFF when printing coordinates\n             - Clear Wall command added (Acc. 255)\n             - Moved DATA file to Doors:Tag!Wall/\n Version 0.3 - Removed BBS Name since it caused problems to Sysops with\n               colors in their BBS Name\n             - Added unlimited chars for Sysop (Acc. 255)\n             - Support for >128 ASCII chars added\n             - Cursor keys when selecting color added\n             - Minor output problems fixed\n             - Design altered\n             - Wall size increased to 10 lines instead of 8\n Version 1.0 - First (& last?) Public Release\n             - Added last tagger color information\n             - Cosmetic changes\n\n ===( Contact me! )===========================================================\n\n If you have any bugs to report, suggestions, ASCII requests or whatever\n feel free to contact me on any bigger BBS in Sweden I''m on\n\n For example: Flashback, Spellbound, Interchange, UnderCover & Prophet''s Hold\n\n Or via InterNet E-Mail [email removed]\n\n ===( Greetings  in alpha order )=============================================\n\n   Agressor            Bikealot            Biscrok             Boozer\n   Centurion           Crocodile           Cruger              Demax\n   Elv!s               Everslick           Ezco                Lizzard\n   Necrophiliac        Nero                Nighshade           Nike\n   Nup                 Pacific             Phailiure           Randall\n   Reactor             Savage              Sniffet             Sniper\n   Speed               Tbm                 Twister             Vegas\n   VietCong            Warhammer           Yipman              [KM]\n\n   Special greets to Nightshade/Insane for helping me with this door!..\n\n ==============================================( ..And everyone I forgot! )===\n\n','\n',char(10)),NULL,'auto-added',16041,1,0,NULL,NULL,'tag_wa10','scan',1780048764);
INSERT INTO door_catalog VALUES('tag_wa20','TAG!WA20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TAG!WA20.LHA','Tag!Wall','XIM','Tag!Wall',NULL,NULL,'TAG','_._______ __|    __    /._________/_ _______ _|       |__|   __/   / |   _____/ \_    _____/    \_     \|   \     \',replace('            .___________\n_._______ __|    __    /._________/_ _______\n_|       |__|   __/   / |   _____/\n\_    _____/    \_     \|   \     \\n |    \      _____\     \    \   . w A L L !\n_|______     \ ____\___________     \ ______\n        \_____\                \_____\\n \nTag!Wall 2.0 (Final) Code & Design cASE/dCS!\nFeatures cursor keys, color selection & more\nSimply *the* /X^S!X wall, example IFF inside\n','\n',char(10)),'Tag!Wall.DOC',replace(' \n           .___________                     ____  ____  ____  ____ \n .______   |    __    /._________  ____  __[____][____][____][____]__  ____\n_|      |__|   __/   / |   _____/ [____][____][____][____][____][____][____]_\n\_   _____/    \_     \|   \     \ __[____][____][____][____][____][____][____\n |   \      _____\     \    \     \ ____[____][____][____][____][____][____] \n |_____     \     \___________     \ [____][____][____][____][____][____].cASE\n __    \_____\   ____  ____   \_____\       .___________  [____] .______\n __]__  ____  __[____][____][___  _____:____|_   __    /.______  |  ____|_\n [____][____][____][____][____]  |     |     /  __/   / |  ____|_|  \     \\n  __[____][____][____][____][___ |    _|_   /   \_     \|  \     \   \     \\n [____][____][____][____][____]  |    \     ______\     \   \      ____     \\n  __[____][____][____][____]__   |______     \     \__________     \   \_____\\n                                        \_____\               \_____\\n\n ===( Introduction )==========================================================\n\n This is a /X Wall door with support for cursor keys, selectable colors and\n more. Take a look at the example output in this archive ( Tag!Wall.IFF )\n\n ===( Installation )==========================================================\n\n   You''ve seen it, you liked it, and now you want to install it? Well..\n\n - Create a directory in your Doors: path named Tag!Wall, and place the\n   executable there ( Doors:Tag!Wall/ ) This is important, since Tag!Wall\n   will place it''s DATA file in this directory\n\n - Install the door as usual (you should know how by now) in you\n   BBS:Commands/BBSCmd/ or BBS:Commands/SYSCmd/ directory\n   The door requires no more stack than default (4096) and should be ran\n   as a XIM module with the command Wall\n\n - Append this line to an MCI text file on your system\n   ( For example the BBS:NODE{x}/LOGON.TXT.GR )\n\n   ~CC_Wall\n\n   (Don''t forget the ~ at the beginning of the file, or /X will treat\n   the MCI codes as normal ASCII)\n\n - If you haven''t screwed up the door should now be installed\n\n ===( History )===============================================================\n\n Version 0.1 - First Beta Release\n Version 0.2 - Small ANSI bug fixed\n             - Cursor OFF when printing coordinates\n             - Clear Wall command added (Acc. 255)\n             - Moved DATA file to Doors:Tag!Wall/\n Version 0.3 - Removed BBS Name since it caused problems to Sysops with\n               colors in their BBS Name\n             - Added unlimited chars for Sysop (Acc. 255)\n             - Support for >128 ASCII chars added\n             - Cursor keys when selecting color added\n             - Minor output problems fixed\n             - Design altered\n             - Wall size increased to 10 lines instead of 8\n Version 1.0 - First (& last?) Public Release\n             - Added last tagger color information\n             - Cosmetic changes\n Version 2.0 - Cursor-remove ANSI sequences removed due to compability\n               problems.\n             - New design (looks good even without ANSI)\n             - This version is FINAL (unless any bugs are found)\n\n ===( Contact me! )===========================================================\n\n   .---- - -   _    _/_________ _                _ _        ......- ---.\n   |  _______/\ \ \ /    _     \ \    _________/\ \    ..:::::::::::.  |\n ._|_/    ____/__  /     :      \ ___/     _____/__   ::::··    :::::  |\n |         |     \/      ¦       \\__________      \ ::::   ..::::::   |\n |         |     \_______|        \_        |       \:::::::::::··    .::::.\n |         l      \______|_________/        l    ..::::::::::·      .:::· .·\n l___________       \_  _l________/___________ .:::·· \_·:::::....:::::|\n   |       |_________/   :  _ ___/          l__:::_____/  ··::::::::·· |\n   |:..    :                   _/            .:::                    .:|\n   `-e^d-----÷----- - -        ·    . ...:::::··    -  - ----÷---splat-''\n\n          E-Mail: [email removed]\n          Voice:  +46-70-7402556\n\n If you have any bugs to report, suggestions, ASCII requests or whatever\n feel free to contact me on any BBS I''m on\n\n Or via InterNet E-Mail [email removed]\n\n ============================================( ..And greets 2 my friends! )===\n\n','\n',char(10)),NULL,'auto-added',16952,7,0,NULL,NULL,'tag_wa20','scan',1780048764);
