INSERT INTO door_catalog VALUES('tai_add4','TAI-ADD4.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TAI-ADD4.LHA','dmsdescript','XIM','TextDiz',NULL,NULL,'TAI','--÷-[ wERNER^tAI - RELEASED : o4-o1-1996! ]- |    ___________.____________      : !    \___   ___/¡_.  \_______|     .',replace('\n--÷-[ wERNER^tAI - RELEASED : o4-o1-1996! ]-\n  |    ___________.____________      :\n  !    \___   ___/¡_.  \_______|     .\n  :      |     |  __¡   \       \    ¡\n  `- ÷ --|     |  \__    \       \---+- -÷\n         |_____|____|____/________\  |\n-+=( PRÄSENTiERt VOLLE KANNE )==[cP!]:====+-\n |          tAIaDD V1.3              . ^  |\n |  dA bESt fiD aDDeR aROUnD! lEECH! | ¡  !\n `-- - - - ------ --- ---÷- ---÷ - --'' :  :\n                         | <- --- --- -''  |\n  T A I  ruLEZ ! [dOOr tO heLL - tAI whQ]\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                                                .------''\n             `------------------------------------------------''\n','\n',char(10)),NULL,'auto-added',190345,5,0,NULL,NULL,'tai_add4','scan',1780048764);
INSERT INTO door_catalog VALUES('tai_ads','TAI-ADS.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TAI-ADS.LHA',NULL,'XIM','cHASING_cLOUDS!.aGa.eXe','1.0',NULL,'TAI','------------FOR LHA/LZH/LZX/ZIP-____------- ___ ____________  ______________\  /___ _//     __     \/     _     \   \/   /',replace('------------ tAI-AdSAddER V1.0 ------------\n------------FOR LHA/LZH/LZX/ZIP-____-------\n___ ____________  ______________\  /___\n _//     __     \/     _     \   \/   /\n   \_____/      /     __     /       /__ _\n   cD!_________/______/_____/_______//__\n-------------------------------------------\n-ADDS & REMOVES BBS-ADS! [ANSIS/TXTs/PRGs]- \n','\n',char(10)),'tAiAdSAddER.doc',replace('\n                      ______.           _______  ._______. \n                _____/      l__        /   _   \ |_______|\n                \_          ___)____  /    |    \|       |\n                /           |       \/     _     \       |\n               /            l        \     |      \      |\n              /                      /     |       \     |\n              \_______________      /______|_______/_____|\n            cD!`------------>\_____/<--------------------''\n\n                         pReSENtS tAi AdSAddER \n                        Version: 1.0 [bUGfiXEd]\n\n                    WRIttEN by rEdCR0W ^tAI/^Area51\n\n                 \n\n\nIntroduction\n~~~~~~~~~~~~\ntAi AdSAddER is a tool that adds bbs-advertisements to an archive\nand kills bbsads of other boards out of an archive !\n\n\nFeatures \n~~~~~~~~\n- You can add as many files as you want \n  [ansis, txt-files, little progs...]!\n- You can kill a lot of bbsads from other boards (max. : 255 chars of names)\n- Many archive types are supported : LHA,LZH,LZX & ZIP \n  (more in the next version)\n- Cool outfit\n\nRequirements\n~~~~~~~~~~~~~\n-LHA, LZX, ZIP [V2.01 or higher] in your c-dir!\n\n\nInstallation\n~~~~~~~~~~~~\nCreate a directory in your cnet-dir called "bbsads".\nCopy all of your ads that you wish to add to an uploaded archive to\nthis directory !!!\n\nCopy the file "tAiAdSAddER.rexx" to your pfiles.\n\n\nLoad your prefered texteditor and change the following line \nof your bbstext :\n\n1901 that says : TEST PASSED.\nchange it to   : TEST PASSED.#0pfiles:tAiAdSAddER.rexx}\n\nSAVE YOUR BBSTEXT AND RELOAD IT !\n\nCONFIGURE following lines in the file : "pfiles:tAiAdSAddER.rexx":\n\n/***************** CONFIG *****************/\n\nStartSize=10000; /* Start-Size of a File to call the tAi AdSAddER \n                    e.g. : The tAi AdSAddER won''t be called if the \n                           size of a file is smaller than (with this config.) \n                           10 kb (=10000 bytes)!!! */   \n\nFiles2AD="cnet:bbsads/#?"; /* The directory where the bbsads \n                              (textfiles, ansis...) are !!! \n                              DON''T FORGET THE "#?" AT THE END OF THE PATH */\n\nFiles2KILL="#?.displayme fuck.txt #?.schaumichan"; \n\n/* \n   The names of the files\n   to kill by tAi AdSAddER \n   NOT MORE THAN 255 CHARS \n   AND DON''T FORGET TO LEAVE A BLANK BETWEEN 2 NAMES !!! \n*/\n \n\n/****** DO NOT CHANGE ANYTHING ELSE  ******/\n\n\nVERY IMPORTANT !!!\n~~~~~~~~~~~~~~~~~~\nYour Subboard Flag "File Testing" has got to be at :"IMMEDIATE" !!!\nThe file will be tested immediatly and if the test is passed \ntAi AdSAddER will be called.\nIf the File Testing Flag is at "AMAINT" or "NO" tAi AdSAddER\nwon''t be called in this subboard !\n\n- USE ZIP-VERSION ZIP V2.01 OR HIGHER IN YOUR C-DIR !!! \n  OR BE SURE THAT YOUR ZIP_VERSION SUPPORTS "#?" !!! \n\n\nD0 ya KN0W tHIS C00l tAI-bOARd ???\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~                                                                              \n              Area51 WhQ / R.W.S. WhQ / tAI Hq / P0iSS0N Hq                  \n                                                                              \n                                                             __/\____         \n        ____/\___               __/\_____                    \       \        \n        \__  _   \      __/\____\   ____/\    __/\__/\_  ____/. / ___/\       \n         \/. / __/\____ \   ____/  __/_/\____ \    /   \/   // /    / /       \n         // /          \/. __/_      \       \/.  /.   /   /______ / /        \n        /______   _  __//     /\____ /.  /   //  //  /    /\_____\/ /         \n        \_____/   /  \ _____ / /\__\//  ____/__ /___/\__ / /      \/          \n             /__ /__ /\____\/ /    /__ /\___\_\/\___\/\\/ /                   \n             \_\/\_\/ /     \/     \_\/ /      \/       \/                    \n          __/\__\/  \/     __/\_  ____\/ __/\________/\__                     \n          \  ___  \        \    \/  __/\_\   ___\___  __/\  ____              \n          /  \_   /\_  ____/    /   \    /. __/_ \_/  \   \/   /\             \n         /   /   /   \/   /         /   //     /\ /   /   /   / /             \n        /___/__ /    /   /    /    /   /_____ / //   /       / /              \n        \___\_\/   /    /____/\__ /__ /\____\/ //__ /\ _    / /               \n              /___/\__ /\____\/\\/\_\/ /     \/ \_\/ /\/   / /                \n              \___\/\\/ /        \/  \/            \/ /__ / /                 \n                      \/                              \_\/ /                  \n                                                         \/                   \n                          !3 NOdES rUNNING!                                                          \n                            [+49-xxx-ASk]                                           \n\n  A4000/030 6MB RAM 1.7GB HD 2 CD-ROM-DRIVES  2 HIGHSPEED-PORTS CNET 3.05d   \n                                                        \n\n\nGREEtINGS tO All tAi-MEMbERS !!!\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nESPECIAllY: FOX ^tAi/LUZIfER ^tAi/CRYPtOR ^tAi/hAtER ^tAi\n            tHOR ^tAi/DARKANGEl ^tAi\n\nAND tO : NOVAliS ^Area51/BlACkfOX ^Area51/JORdAN ^rWS\n                                                         \n','\n',char(10)),NULL,'auto-added',20237,2,0,NULL,NULL,'tai_ads','scan',1780048764);
