INSERT INTO door_catalog VALUES('tai_sc2o','TAI-SC2O.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TAI-SC2O.LHA',NULL,'XIM','SoundPlay',NULL,'wERNER','TAI','---------------------------------____-------- ___ ____________  ______________\  /___ _//     __     \/     _     \   \/   /',replace('\n---------------------------------____--------\n ___ ____________  ______________\  /___\n  _//     __     \/     _     \   \/   /\n    \_____/      /     __     /       /__ _\n    cD!_________/______/_____/_______//__\n---------------------------------------------\n       SysopChatter V2.o by wERNER\n           Made for /X ''n S!X\n      Using requesters and many more !\n  It''s a Sysop-Page door written in AREXX\n---------------------------------------------\n>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>[10-03-95]\n','\n',char(10)),'Stat.guide',replace('@DATABASE "Stat.guide"\n@WIDTH 79\n@NODE MAIN "INHALTSVERZEICHNIS"\n _____________________        ___   __       /\      .____.          .\n \     __  __\  \  \  \  /\  /  / _|  |_    /  \____ |    |_________/\n  \    /   | /  /\  \  \/  \/  / |      |  /    \   \|    |    __  /\n   \__/    |/  /__\  \        /  |_    _|  \____/    \    |      \/\n   . /     |\        /\  /\  /     |__|    |    |   \     |    __/\n   :/      | \______/  \/  \/              |____|___|\    |    |\n   /_______|                                    :   : \___|____|\n  .        :                               .    .   .  .  :    :\n           .                                            . .    . The Edge\n\n                        ( * Done by WeRneR/tAi * )\n\n\n             @{" Was macht SysopStatus ? "LINK "DO"}\n             @{" Installation "LINK "INS"}\n             @{" Hqs "LINK "hqs"}\n	     @{" Das letzte ...." LINK "LAST"}\n@ENDNODE\n\n@NODE "DO"\n\n            Sysopstatus ist ein /X + S!X ARexx Door .\n            Es ersetzt den standart /X Befehl\n            ''Operator Page'' gegen ein leistungs-\n            fähigeres Programm .\n\n       !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!\n       !!!! Das Programm SysopStatusV2.o benötigt mindestens !!!!\n       !!!! OS 2.04 !                                        !!!!\n       !!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!!\n\n            Features :\n\n               V1.5\n                            - Requesters\n                            - Samples\n                            - Einstellbare Texte\n\n\n               V2.o (diese)\n                            - Comment to Sysop\n                            - Printerauswahl in Config eingebunden\n                            - Zuvor Text anzeigen (Requester Auswahl)\n                            - Besseres Design\n@ENDNODE\n@NODE "INS"\n   \n  Um SysopStatus zu installieren verfahre so :\n                                \n              Lha-pack Inhalt             | Kopiere nach\n              ----------------------------------------------\n               SysopChatter.config        | Beliebig\n               SysopChatter.rexx          | Doors:SysopChatter/\n               S/SysopStat.prefs          | S:\n               SysopStat.guide            | BBS:docs/\n               C/SoundPlay                | C:\n               libs/Reqtool.lib           | LIBS:\n               libs/RexxReqtools.library  | LIBS:\n               bbscmd/o.info              | bbscmd/\n  Samples/Example.smp | Den Pfad musst du in SysopChatter.config einstellen !\n\n    Es ist wurscht ob man den Example.smp verwendet oder einen anderen !\n                Der Sample muss aber IFF format haben !\n\n@ENDNODE\n@NODE "hqs"\n _____________________        ___   __       /\      .____.          .\n \     __  __\  \  \  \  /\  /  / _|  |_    /  \____ |    |_________/\n  \    /   | /  /\  \  \/  \/  / |      |  /    \   \|    |    __  /\n   \__/    |/  /__\  \        /  |_    _|  \____/    \    |      \/\n   . /     |\        /\  /\  /     |__|    |    |   \     |    __/\n   :/      | \______/  \/  \/              |____|___|\    |    |\n   /_______|                                    :   : \___|____|\n  .        :                               .    .   .  .  :    :\n           .                                            . .    . The Edge\n\n                        .:  Headquarters :.\n\n             -------  ------------------  -------------\n             WhQ    |    DooR To HeLL   | +49-6660-ELiTE\n             eHQ    |    TiME bOARD     | +49-6084-SPW!\n             dHQ    |    tHE lEECH      | +31-7039-12916\n             gHQ    |    pRiSON oF hELL | +49-6196-LAMe!\n              hQ    |    LiQuiDe        | +49-9231-GETIT\n             ghQ    |    ThE ZoNe       | +49-961-NO!\n\n                          and sum others !\n@ENDNODE\n@NODE "LAST"\n\n  Die Programme ,die in diesen Pack enthalten sind, sind Freeware.\n  Hiermit übernehme ich keinerleih Haftung von Schäden die durch\n  dieses Programm evtl. entstehen söllten.\n  Alle Programme wurden nach bestem Ermessen "durchgecheckt".\n\n  --------------------------------------------------------------------\n\n  Das Programm "SysopChatter.config" kann/muss/söllte vom Sysop von der\n  Workbench aus gestartet werden.\n  Es können Samples oder standart-beep Ton verwendet werden .\n  Wähle in SysopChatter.config "Kein Sample" an und es wird der\n  Beep-Ton verwendet .\n  Auch ist es moeglich die Logbuch-Fuehrung ueber Festplatte oder\n  Printer gehen zu lassen .\n  In dem File "SysopChatter.config" ist es natürlich auch möglich\n  den Standart "Sysop isn`t available"\n  oder "Sysop is available" Text zu verändern .\n  Aber vorsicht bei der Logführung ! Wenn du Printer eingestellt hast und\n  der Drucker ist nicht an dann bleibt das Programm hängen !!\n  Naja eigentlich ergibt sich das alles von selbst .\n\n  Just have a look !\n\n\n  Geplant in naechster version :\n\n  - Moeglichkeit den ChatRuf abzubrechen . (Keine Idee wie ! Kann mir einer helfen?)\n\n\n  --------------------------------------------------------------------\n\n  Aehm noch en paar greets :\n\n         - Thor              Na bald biste wieder da ...\n         - Hater             Auf auf ! Mach ma wieder was !\n         - Darkanel          Das gleiche gilt fuer dich auch !\n         - Fox/tB            Tja , wir sind wohl die einzigen die hier\n                             noch was machen ?!\n         - Tsr               Wann kommen die naechsten mods ?\n\nSTANDART SPRUCH :        Und alle die ich vergessen hab !\n\n\n@ENDNODE\n\n','\n',char(10)),NULL,'auto-added',72336,2,0,NULL,NULL,'tai_sc2o','scan',1780048764);
INSERT INTO door_catalog VALUES('tai_ust','TAI-UST.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TAI-UST.LHA',NULL,'XIM','exe.-l0S-eND0S-bBS-.exe',NULL,NULL,'TAI','______|     ./  /_____/ \     |    //__/\_____. \__._  _._/.___\\   .|',replace('        ._______   ______\n  ______|     ./  /_____/\n  \     |    //__/\_____.\n   \__._  _._/.___\\   .|\n:.    :    |  ___/ .\  :|\n::::  |____|__|      \__|.\n::::::::::::::|_______\:::::...\n      TAI pROUDLY pRESENTS \n   aNOTHER /T\EMPEST rELEASE\n    sTATUS tOOL vERSION 1.0\n       (c) fOX^TAI^TCE\n:::::::::::::::::::::::::::::::\n-------------------------------','\n',char(10)),'TAI-stat.guide',replace('@DATABASE "inSTALL.guide"\n\n@With 80\n\n@NODE MAIN "MAINPAGE"\n\n\n                      @{B}______.           _______  ._______. \n                _____/      l__        /   _   \ |_______|\n                \_          ___)____  /    |    \|       |\n                /           |       \/     _     \       |\n               /            l        \     |      \      |\n              /                      /     |       \     |\n              \_______________      /______|_______/_____|\n            cD!`------------>\_____/<--------------------''\n\n\n        TAI PRESENTS INSTALATIONSCRIPT FOR STATUS TOOL VERSION 1.0\n\n\n                 @{"          INSTALLATION           "LINK "installation"}\n                 @{"          INFORMATION            "LINK "BOARDS"}\n\n                                            \n\n                                                  @{" FOX^TAI^TCE "LINK "FOX"}\n\n\n@ENDNODE\n\n@Node "Installation"\n\n	@{b}	1:... _____________.       .       ....:1\n		2:... \  __ __  /  |__:___ :       ....:2\n		3:...  \//   \\/   _  \    :       ....:3\n		4:...   /     \    |   \   |       ....:4\n		5:...   \_____/\___l___/___|[FX]   ....:5\n		6:.....................................:6@{ub}\n\n                        - TAI /T\EMPEST rELEASE -\n                     - of sTATUS TOOL vERSION 1.0 -\n\n            It`s realy simple to install that Tool! Just copy\n            TAI-STAT.rexx to your REXX: and add at your \n            GlobalMenu.Opt\n\n        -----------------------insert here-----------------------------\n\n            [*,*,*,*,*]=ST |REXX|TEMPEST:REXX/TAI-stat.rexx\n\n        -----------------------insert here-----------------------------\n\n                        That`s all! realy simple !\n\n\n@ENDNODE\n\n@Node "BOARDS"\n\n@{b}\n                           DooR To HeLL      tAi WhQ          \n			   ThE ZoNE          tAi hQ\n			   tHEAtRE oF PAiN   tAi GhQ         \n			   EXtERmInAToR      tAi diS-SiDE\n			   PrisoN oF hELL    tAi hQ\n                           tHE lEEch         tAi dHQ\n                           TiME BOARD        tAI eHQ\n\n     	              FOR                __|  |    |\n     	     _____________.        .     \  __|    l__\n     	     \  __ __  /  |___:___ :      \ \        /\n     	      \//   \\/   _   \    :       \ \      /\n               /     \    |    \   |        \ \    /\n      	       \_____/\___l____/___|         \ \  /\n                                              \/\/\n                                          \n                                           cALL nOW !\n\n\n@ENDNODE\n\n@NODE "FOX"\n\n\n\n        -   -  - - -- --=» it`s time for TiME BOARD «=-- -- - -  -   -\n@{b}\n      ._______\n______|     ./_      /\\n\     :    //_.___  / \\____________          dA sTUFF are mUSIX\n \__._  _._/  :   \/   .\     _____/                       aM!GA\n    :    |    |   \/     \   ___)____                      PCeee\n    l____|____|___|:      \_____ _____                     a.s.o.\n                   l_______\   \/\n\n rUNNINg tEMPESt v3.29      .________/\_______/\  ____/\______/\_______/\\n  ..................        :   ____ //        \\/ .___\\____  \\_____  \\\n                            ¦   __  \/ \   |    .\ ___/ .\    __/__  /   ·\\n   dUDEZ:FOX^TAI^TCE^TB     |__________/_________/_:      \_:     .\______/\n         cARTER^TB                                 l_______\l_______\@{ub}\n\n            TAI-EUROPEAN hEADQUARTER TB-wORLD hEADQUARTER sILICOn GHQ\n\n              Node #1 ZYXEL E+ 192................ +49-6oxx-Ask-Now!\n              Node #2 USR DUAL STANDART 168....... +49-6oxx-Ask-Now!\n              Node #3 iSDN 64ooo.................. +49-6oxx-Ask-Now!\n              Node #4 iSDN 64ooo.................. +49-6oxx-Ask-Now!\n\n\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',10762,5,0,NULL,NULL,'tai_ust','scan',1780048764);
INSERT INTO door_catalog VALUES('tai_who','TAI-WHO.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TAI-WHO.LHA',NULL,'XIM','LE-win5-96.exe',NULL,'tAi','TAI','--------------------------------____------- ___ ____________  ______________\  /___ _//     __     \/     _     \   \/   /',replace('-------------- tAI-Wh0 V 1.1 --------------\n--------------------------------____-------\n___ ____________  ______________\  /___\n _//     __     \/     _     \   \/   /\n   \_____/      /     __     /       /__ _\n   cD!_________/______/_____/_______//__\n-------------------------------------------\n-- Wh0-T00l V1.1 bUGfiXEd VErSi0N by tAi --\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.       