INSERT INTO door_catalog VALUES('tainode','TAINODE.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TAINODE.LHA',NULL,'XIM','LE-win5-96.exe','1.1','tAi-',NULL,'--------------------------------____------- ___ ____________  ______________\  /___ _//     __     \/     _     \   \/   /',replace('------------ tAI-N0dEINf0 V1.1 ------------\n--------------------------------____-------\n___ ____________  ______________\  /___\n _//     __     \/     _     \   \/   /\n   \_____/      /     __     /       /__ _\n   cD!_________/______/_____/_______//__\n-------------------------------------------\n-bUGfiXEd VErSi0N 0f N0dEINf0 [V1.1]by tAi-\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                                                .------''\n             `------------------------------------------------''\n','\n',char(10)),NULL,'auto-added',7922,5,0,NULL,NULL,'tainode','scan',1780048764);
INSERT INTO door_catalog VALUES('tarext_','TAREXT!.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TAREXT!.LHA','TarExt','XIM','TarExt','1.0',NULL,'TAREXT',NULL,replace('presents: Tarext v1.0\n','\n',char(10)),'TarExt.doc',replace('\n                      WELL >> TARHEEL << STRIKES AGAIN!!\n                           presents: Tarext v1.0\n\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n Docs By /Y\issileman   -=* DEFCON 5 *=- BBS    [L]egend USHQ [206] 427-5244\n\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n     This utility here is one requested by MANY sysops !! It adds the .dms,\n.wrp, and .lzh extensions on to uploaded warez upon logoff. Unlike AmiAdder,\nthis version adds the Lzhtar.txt.displayme file to the .lzh archive, which\nallows you to view where the file was downloaded from upon un-archiving...\n     This version also allows you to choose MANY paths for the program to\ncheck, instead of just one...PLUS it checks the ''hold'' dirs as well, in case\nthe person gets disconnected!! Also you don''t have to assign any ''paths'' or\n''dirs'' in your ''startup-sequence'' as in amiadder.\n     I have tested this utility for days now, and have not come across any\nbugs in it. If any found, please let Tarheel or myself know. Since Thomas\nhas hardcoded so much garbage into the New Express, make sure to turn all\ncheck functions off in your config file. This utility (at least for now),\nuses the PD WARPCK (warpTXTmaster) by Vinorkis of AFL, which must be in your\n''C'' dir, along with LHARC and DMTAR...\n     Type ''Run TarExt'' and the program will guide you with a SIMPLE menu.\nThis is done the FIRST TIME only BEFORE you use it in express. This sets up\nthe necessary files for TarExt to run. It will create 2 files:\n          1> MT.com     ( This file is created for future releases ) \n          2> Ami_Paths  ( This stores the paths for your conferences)\n     When you run TarExt, make sure to hit RETURN after each path line, AND\nafter you are done once, on a blank line to make sure CLI prompt returns.\n     COPY your Warpsig text (or board add) to ram:  and RENAME it to......\n''LzhTar.txt.displayme'' and MOVE to your BBS: directory. The ''TarExt'' file can\ngo in your ''C'' dir, or wherever you run your Ami Utilities from.\n     Now edit your bbs script to include in the line before endcli to say:\n''run Tarext'' . Thats it... Any other questions...Call me.\n \n                                              /Y\issileman\n                                           -=* DEFCON 5 *=- BBS\n                                              [206] 427-5244\n\n*     FOR THOSE OF YOU WHO NEVER GOT ''DMTAR'' THEN I HAVE ALSO INCLUDED\n      IT IN THIS ARCHIVE FOR YOU...\n\n**    IF YOU ''ZAPPED'' YOUR EXPRESS PROGRAM TO USE DMTAR IN IT (WHICH\n      I DID) THEN YOU WILL WANT TO MAKE A FEW CHANGES TO YOUR PROGRAM !!\n         -=* IF YOU HAVEN''T ZAPPED EXPRESS THEN DON''T MESS WITH IT *=-\n      \n      1> Re-zap Express and change ''DMTAR'' to ''DMTAD''. COPY ''DMtar_end'' to\n         RAM: and RENAME ''DMTAD''. Then Move it back to the ''C'' dir. Make \n         sure the original DMTAR was the ''DMtar_plain'' that way, when they\n         send a file, it checks it realquick when uploaded, then STRIPS\n         the other messages and adds the test AFTER logoff.\n      2> Recap...\n\n             These files in your ''C:'' dir for DMS and WRP\n\n         a> DMTAR    (This file should be the ''dmtar_end, renamed)\n         b> DMTAD    (This file should be the ''dmtar_plain, renamed)\n         c> DMTAR_plain\n         d> DMATR_end\n         e> DMTAR_all\n         f> CLEANDIR\n         g> WARPCK\n         h> TAREXT   (THIS utility, or whatever path you choose)\n             \n             These files in your ''S:'' dir DMS and WRP\n\n         a> WARPSIG\n         b> TARHEEL\n         c> TARHEEL1\n      \n             These files in your ''BBS:'' dir\n\n         a> MT.COM                (Created by ''TarExt'')\n         b> AMI_PATHS             (Created by ''TarExt'')\n         c> LZHTAR.TXT.DISPLAYME  (This is your BBS add needed for .lzh)\n','\n',char(10)),NULL,'auto-added',46669,4,0,NULL,NULL,'tarext','scan',1780048764);
INSERT INTO door_catalog VALUES('tau_dm03','TAU-DM03.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TAU-DM03.LHA','dm','XIM','dm',NULL,NULL,'TAU','.__\__  ____ \/  |_\____  \/  |_/  ___/___. |    /  |  |  \  |  \  l  /   | \    \    | `---/   |  .   \ l   \ .  \   l  \--  \---''',replace('   __________  __. _______  __.  ______\n.__\__  ____ \/  |_\____  \/  |_/  ___/___.\n|    /  |  |  \  |  \  l  /   | \    \    | \n`---/   |  .   \ l   \ .  \   l  \--  \---''\n    \___|__|___/_____/_|___\_____/____/EaZ\n           PReZeNTZ aN /X uTiL\n            DeletedMover v0.3\n             - bug fixed -\n','\n',char(10)),NULL,NULL,NULL,'auto-added',10915,4,0,NULL,NULL,'tau_dm03','scan',1780048764);
INSERT INTO door_catalog VALUES('tau_gz01','TAU-GZ01.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TAU-GZ01.LHA','gz','XIM','gz',NULL,NULL,'TAU','.__\__  ____ \/  |_\____  \/  |_/  ___/___. |    /  |  |  \  |  \  l  /   | \    \    | `---/   |  .   \ l   \ .  \   l  \--  \---''',replace('   __________  __. _______  __.  ______\n.__\__  ____ \/  |_\____  \/  |_/  ___/___.\n|    /  |  |  \  |  \  l  /   | \    \    | \n`---/   |  .   \ l   \ .  \   l  \--  \---''\n    \___|__|___/_____/_|___\_____/____/EaZ\n           PReZeNTZ aN /X XiM DooR\n             GLoBaL ZiPP¥ v0.1\n  ZiPP¥ CoMMaND WHiCH SeaRCHeS aLL CoNFS\n       ReaLL¥ FaaaaaaaaaaaaaaaST\n','\n',char(10)),'gz.doc',replace('\n                      [---> -P- T·A·U·R·U·5 -P- <---]\n                              presents the\n     ____  ____  ___ __ _______ _____________________   _____________\n    /    /\    \/   \  :       \        /     :      : /    /       /\n   //           \___/  :___     \   ___/ ____ : ____ :/    /___    /____\n   \            /   \      \ /  /    /:       :      :        /   /    /\n    \____/\____/\___/______/___/____/ :_______:______:_______/________/\n                                 SeRieS\n   ====================================================================\n                             GLoBaL ZiPP¥ v0.1\n                     (c) 05/94 by WiLD THiNG/TauRuS\n   ====================================================================\n         Yep, here we go again with another of da GR8T WiLD TooLZ\n\nGlobal Zippy does the same as the normal Zippy, but it searches all confs a\nuser has axx to.  Doo Wop.  It is a XiM DooR WRiTTEN in Amiga E, that means\nSPEED.\n\n\nPROBLEMZ:\nJust  one  little thing, there''s one cute little bug which I wasn''þ able to\nremove  so  far,  if  u''re  searchin''  for a strig which stands at the very\nbeginning of a filelist GZ will FoCK uP, DuNNo eXaCTL¥ WH¥ ->\n\n        SoLuTioN: Put a line with 3 or 4  spaces at the beginning of each\n                  DIR file..\n\nINSTALLATION:\nU KNoW HoW To iNSTaLL aN /X XiM DooR, don''t ¥ou ???\n\n                 -======================================-\n                       Greetings go to(in no order)\n                 -======================================-\n\nall   Ex-Mannassas   &  FeaR  members,  Tic.,  R19,  Dragon/Motion,  Vince,\nAndy/Motion,  Sunset, Donald/Motion, Vince, The Generat, Wild Child/Taurus,\nEaZy-E/Taurus,  Zielu/Mad  Elks, uNReaL/Surprise Prod., Easy Rider/Mystic &\nTRSi,  EMPiRE/Mystic,  ByteAndi/TRSi,  Selz/Nova Acies(?), The Trader/FeaR,\nChipsi/Taurus,  Crazy  Squaw,  Calypso/Logic,  KC,  C/\Te¥e/Insane,  all by\nBeta-Testers, and all I forgot ....\n                                    ____\n ___________________________________\  /________________________________\n(__________________________________ \\// _______________________________)     \n \_________________________________\ \/ /______________________________/\n                                   \\  //\n                                    \\//\n                                     \/\n\n                     aND  LaZT  BuT  OF CoZ N°T LeaST\n              a BiG, FaT & HaiR¥ GReeT¥ T° a££ M¥ HoRNeD BRoS\n\n                  \n\nFranklin/Termos : YO, (I hate this RAP & similar shit), keep smilin'' & thx\n                  for da fonts\nDune/FeaR       : YeP that''s ¥ouR ASCii STuFF, ThX aN¥Wa¥\n      /\      Artie/Taurus : hi hope to chat to ye as soon as possible,\n ____/  \____                what about that new stuff ??\n \   /\/\   / Bionic/Yodel : w8in'' for another all-thru-the-night chat\n  \  \/\/  /  Fazer/Razor 1911: I''ll call as soon as I can, promised\n  /        \  Vinzi/Yodel     : Nice  txt in that intro (YC3+4)\n /___ () ___\ SiNTAX/WøT      : ...your examples in E and your AEDoor.library\n     \  /  Wouter van Oortmerssen : ... Amiga E compiler, it''s the BEST\n      \/  Big C & Amiga   : ... the best toy for bored programmers ;-)\n\nRage against ZK : Go on like this\nLogic           : hey yer checkers  are da best \nMystic PL       : Czesc maluchy\nYodel           : hello to all of you, nice intro\n\n                 -======================================-\n                              Fuckings go to\n                 -======================================-\nPolish telecom (TPSA): fucked up assholes\nall you stupid lamers here that even can''t do a simple file description\nZonder Lamando       : fuck yerself\nMcDonald''s           : this McChampion is BuLLSHiT\n','\n',char(10)),NULL,'auto-added',8161,2,0,NULL,NULL,'tau_gz01','scan',1780048764);
INSERT INTO door_catalog VALUES('tau_wn05','TAU-WN05.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TAU-WN05.LHA',NULL,'XIM','Install.exe',NULL,NULL,'TAU','.__\__  ____ \/  |_\____  \/  |_/  ___/___. |    /  |  |  \  |  \  l  /   | \    \    | `---/   |  .   \ l   \ .  \   l  \--  \---''',replace('   __________  __. _______  __.  ______\n.__\__  ____ \/  |_\____  \/  |_/  ___/___.\n|    /  |  |  \  |  \  l  /   | \    \    | \n`---/   |  .   \ l   \ .  \   l  \--  \---''\n    \___|__|___/_____/_|___\_____/____/EaZ\n           PReZeNTZ aN /X AIM DooR\n           WiLD NeW v0.5 (10/07/94)\n   Interactive New User Questionaire Door \n - NeW oPTioNS -+- BuGFiXeS -+- NeW LooK -\n','\n',char(10)),'WiLDNeW.doc',replace('                            [---> Taurus <---]\n\n                             presents from da\n     ____  ____  ___ __ _______ _____________________   _____________\n    /    /\    \/   \  :       \        /     :      : /    /       /\n   //           \___/  :___     \   ___/ ____ : ____ :/    /___    /____\n   \            /   \      \ /  /    /:       :      :        /   /    /\n    \____/\____/\___/______/___/____/ :_______:______:_______/________/\n                                 SeRieS\n \n===========================================================================\n                               WiLDNeW v0.5\n                          written by WiLD THiNG\n===========================================================================\nThis  is a new questionaire door for new users, it can give some answers or\ncomments on the questions and you can have your questinairs in ANSI and you\ncan have different questions for different baud-rates.  Furthermore you can\nask  new  questions on specified answers (you should now say WOW, no ?  na,\nmaybe   next   time). \n\n Now  you  can  have  your  questions in whatever language you want, i have\nsupplied  with  this  release  an English, Polish and German one, but don''t\nforget that the user will probably answer in the language he has been asked\nif you don''t tell him otherwise.\n\nThe  filled in questionaires will be saved in the WiLDTools/WiLDNew/answers\ndirectory with the user name as filename.\n\nuse  the  BBS  command  ''NEW'' to enter sysop mode and review new user apps,\ndon''t forget to set up the security level for the command.  With a security\nlevel higher than 2oo you will be also able to delete the apps.\n\nConfig file:\n~~~~~~~~~~~~\n(doors:WiLDTools//WiLDNeW/WiLDNew.cfg)\nYes here you must declare which languages you want to have, and the names\nof the quest files \neg.: \n==== cut here ====\nEnglish quest.eng\nPolski quest.pol\nDeutsch quest.ger \n==== cut here ====\nand whatever you want...\n\nWiLDNew will ask which language the user prefers.\n\nhere  are the recognition chars for the quest file, they have to be at the\nbeginning of every line:\n\n- print out line\n? Ask question\n§ Ask question which user MUST Answer \n^ Check answer \n+ Call the editor and let the user write you a comment, that \n        comment will be saved in .../answers/username.ext\n=xxxxx ask user with specified baud rate where xxxxx is the rate\n%xxxxx show line only to user calling at xxxxx baud\n\nYou can combine the answer checking with a new question:\n\n?Have you ever heard of WiLDTools ?             - ask question\n^yes                                            - if entered "yes" then\n§Why not ?                                      - user must answer why\n?Is there anything you want to tell me ?\n^yes\n+ext                                            - if the answer is\n                                                  yes - start the\n                                                  editor\n\nLook at the example config file to see some possibilities :)\n\n\nInstallation:\n~~~~~~~~~~~~~\nExecute  the  WNINST script, it''ll copy the stuff where it belongs and edit\nthe config files to yer needs\n\nHaVe PHµN aNÐ Ma¥ Ða Wa®eZ Be WiTH ¥øµ\n\nFor  any  bug reports, improvements or if you''d like me to write a door for\nyou  contact  me  at my board Dixie ++48-71-575825.\n\nTHiNGS LeFT Tø Dø:\n~~~~~~~~~~~~~~~~~~\n\n- Finally Do a Amiga E version of it for speed improvement\n\n\nHistory:\n~~~~~~~~\nv0.1            First Version\nv0.2            added Multilanguage option\nv0.3            some fixes and edit option\nv0.4            sysop mode was added\nv0.4b 25-06-94  fixed sysop mode option, ''NEW'' command works now,  \n                uses now custom ''V'' command TO view apps FOR more \n                convenience\nv0.5  10-07-94  Bugfixes over bugfixes , added ''View By Name'' TO sysop mode,\n                new look\n\n\n                          LooK ouT FoR THe oTHeR \n      ____  ____  ___ __ _______ _____________________   _____________\n     /    /\    \/   \  :       \        /     :      : /    /       /\n    //           \___/  :___     \   ___/ ____ : ____ :/    /___    /____\n    \            /   \      \ /  /    /:       :      :        /   /    /\n     \____/\____/\___/______/___/____/ :_______:______:_______/________/\n\n\n[----- NAME ------|------ DESCRIPTION -------|------- FEATURES ---------------]\n WiLDRead v0.13   | file/archive/log viewer  | text search\n                  | AIM door                 | file/arc info\n                  |                          | next/prev. page\n                  |                          | page selection\n[-----------------|--------------------------|--------------------------------]\n WiLDNeW v0.5     | new user questionaire    | multilanguage\n                  | AIM door                 | baud checking for questions\n                  |                          | multiple answers\n                  |                          | text comments (internal ed)\n                  |                          | sysop review of new users\n[-----------------|--------------------------|--------------------------------]\n WiLDBull v0.2    | global bulletins         | scroll bar selection\n                  | AIM door                 | all bulls in one dir\n[-----------------|--------------------------|--------------------------------]\n WiLDMenu v0.1    | multi level menus        | all menus in one file\n                  | AIM door                 |\n[-----------------|--------------------------|--------------------------------]\n WiLDKick v0.1    | unwanted users kick out  | show  msg to user & hang up\n                  | AIM door                 |\n[-----------------|--------------------------|--------------------------------]\n WiLDVote v0.9    | vote door                | configurable user add/delete\n                  | AIM door                 | of topics and itemz\n                  |                          | download of result file\n                  |                          | result output with graph bars\n[-----------------|--------------------------|--------------------------------]\n WiLDLiST v0.7    | file LIST dl             | download all filelists from\n                  | XIM door                 | conferences the user has \n                  |                          |  access TO in one file\n[-----------------|--------------------------|--------------------------------]\n Global Zippy     | Zippy command FOR all    | searches all confs for search\n                  | confs                    | string\n[-----------------|--------------------------|--------------------------------]\n\n\n                 -======================================-\n                           Special thanx for ...\n                 -======================================-\n\nEmpire/Mystic   : well you see, finally got away from that arexx stuff, and\n                  removed the old config and you can select the confs you\n                  want\nByteAndi/MST    : for da kewl stuff, ich hab ne liste mit einigen vielen\n                  bugs und Vorschlaegenn fuer Dich :-)\nGollum          : Thx for da reeeeeaall fast text converison proc\nZiPPER/Yodel    : THX for all\nZielu/Mad Elks  : thx for yer loooooooooong bug reports\nuNReaL/FeaR     : ...all the KeWL ASCII''s\nEasy Rider/MST  : ...beta-testing & fast ''distribution''\n                  and yer beta-testing\nWouter van Oortmerssen : ... Amiga E compiler, it''s the BEST\nSiNTAX/WøT      : ...your examples in E and your AEDoor.library\nBig C & Amiga   : ... the best toy for bored programmers ;-)\n\n                  \n\n\n                 -======================================-\n                       Greetings go to(in no order)\n                 -======================================-\n\n                      all Ex-Mannassas & FeaR members\nTic.,   R19,  Dragon/Motion,  Vince,  Andy/Motion,  Sunset,  Donald/Motion,\nVince,The  Generat, Wild Child/Taurus,EaZy-E/Taurus(ruf mal an, hab was mit\nDir zu schwätze), CatEye/Taurus, Artie/Taurus and all others who want to be\ngreeted...\n\nLogic           : hey yer checkers  are da best \nRage against ZK : Go on like this\n\n                 -======================================-\n                              Fuckings go to\n                 -======================================-\nPolish telecom (TPSA): fucked up assholes\nall you stupid lamers here that even can''t do a simple file description\nZonder Lamando       : fuck yerself ye bloody nazis\n\n','\n',char(10)),NULL,'auto-added',11766,3,0,NULL,NULL,'tau_wn05','scan',1780048764);
INSERT INTO door_catalog VALUES('tau_ws01','TAU-WS01.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TAU-WS01.LHA','ws','XIM','ws',NULL,NULL,'TAU','.__\__  ____ \/  |_\____  \/  |_/  ___/___. |    /  |  |  \  |  \  l  /   | \    \    | `---/   |  .   \ l   \ .  \   l  \--  \---''',replace('   __________  __. _______  __.  ______\n.__\__  ____ \/  |_\____  \/  |_/  ___/___.\n|    /  |  |  \  |  \  l  /   | \    \    | \n`---/   |  .   \ l   \ .  \   l  \--  \---''\n    \___|__|___/_____/_|___\_____/____/EaZ\n          PReZeNTZ aN /X XiM DooR\n               WiLD STaT v0.1 \n  NiCe LooKiN RePLaCeMeNT FoR Da /X STaT \n','\n',char(10)),'WiLDSTaT.GUiDe',replace('@database WiLDSTaT.guide\n\n@node MAIN "WiLD STaT v0.1 (c) 07/94  WiLD THiNG/Taurus"\n\n                      [---> -P- T·A·U·R·U·5 -P- <---]\n                              presents the\n     ____  ____  ___ __ _______ _____________________   _____________\n    /    /\    \/   \  :       \        /     :      : /    /       /\n   //           \___/  :___     \   ___/ ____ : ____ :/    /___    /____\n   \            /   \      \ /  /    /:       :      :        /   /    /\n    \____/\____/\___/______/___/____/ :_______:______:_______/________/\n                                 SeRieS\n   ====================================================================\n                              WiLD STaT v0.1\n                     (c) 07/94 by WiLD THiNG/TauRuS\n   ====================================================================\n              @{" Introduction        " link "introduction"} @{" Greetings         " link "greets"}\n              @{" Installation        " link "installation"} @{" Contact           " link "contact"}\n              @{" Other WiLDTooLS     " link "tools"} @{" History           " link "history"}\n\n\n           - READ THIZ DOCS BEFORE ASKING ME STUPID QUESTIONS -\n@endnode\n\n@node introduction "Introduction - lat.: inter ducere ~ put it in man"\n\nWiLD  STaT is meant TO replace the /X S command.  After logging in /X shows\nsum  statistics  etc.,  but  the outlook of it is quite ugly, so here comes\nWiLD  Stat  and  gives  ya da infos a user needs when he is ready to start,\nmost import of ''coz if the Sysop is chattable or not :-)\n\n                have fun and a horny day\n                                         WiLD THiNG/Taurus\n\n@endnode\n\n@node history\n                 -======================================-\n                               H I S T O R Y\n                 -======================================-\n\n-VeR----ReL.DaTe-----------------------CHaNGeD/uPDaTeD--------------------\n 0.1    26/05/94        First working version, only ßeta release\n--------------------------------------------------------------------------\n\n@endnode\n\n@node installation "Installation"\n\n                             _________________  \n                            |~ |___________| ~|\n                            |  |___________|  |\n                            |  |___________|  |\n                            |  |___________|  |\n                            |  |___________|  |\n                            |    _________    |\n                            |   |~_    ~| |   |\n                            |   || |    | |   |\n                            l   || |    | |   |\n                             \_,||_|____|_|___|\n\nWhen You have unpacked this little shit just copy the aedoor.library to yer\nlibs:  and then type copy bbs/* all bbs:  and WoP WiLD STaT is installed.\n(You must be ofcoz in the dir where you unpacked WiLDStat to)\n\n\n@endnode\n\n                                           \n@node greets "Greetings & Fuckings"\n                 -======================================-\n                       Greetings go to(in no order)\n                 -======================================-\n\nall   Ex-Mannassas   &  FeaR  members,  Tic.,  R19,  Dragon/Motion,  Vince,\nAndy/Motion,  Sunset, Donald/Motion, Vince, The Generat, Wild Child/Taurus,\nEaZy-E/Taurus,  Zielu/Mad  Elks, uNReaL/Surprise Prod., Easy Rider/Mystic &\nTRSi,  EMPiRE/Mystic,  ByteAndi/TRSi,  Selz/Nova Acies(?), The Trader/FeaR,\nChipsi/Taurus,   Crazy  Squaw,  Calypso/GOD,  KC,  C/\Te¥e/Insane,  all  my\nBeta-Testers, and all others I forgot ....\n                                    ____\n ___________________________________\  /________________________________\n(__________________________________ \\// _______________________________)     \n \_________________________________\ \/ /______________________________/\n                                   \\  //\n                                    \\//\n                                     \/\n\n                     aND  LaZT  BuT  OF CoZ N°T LeaST\n              a BiG, FaT & HaiR¥ GReeT¥ T° a££ M¥ HoRNeD BRoS\n\n                  \n\nFranklin/Termos : YO, (I hate this RAP & similar shit), keep smilin'' & thx\n                  for da fonts\nuFoK/MySTiC     : thx FøR äLL THøZë µPPZ\nDune/FeaR       : YeP that''s ¥ouR ASCii STuFF, ThX aN¥Wa¥\n      /\      Artie/Taurus : hi hope to chat to ye as soon as possible,\n ____/  \____                what about that new stuff ??\n \   /\/\   / Bionic/Yodel : w8in'' for another all-thru-the-night chat\n  \  \/\/  /  Fazer/Razor 1911: I''ll call as soon as I can, promised\n  /        \  Vinzi/Yodel     : Nice  txt in that intro (YC3+4)\n /___ () ___\ SiNTAX/WøT      : ...your examples in E and your AEDoor.library\n     \  /  Wouter van Oortmerssen : ... Amiga E compiler, it''s the BEST\n      \/  Big C & Amiga   : ... the best toy for bored programmers ;-)\n\nRage against ZK : Go on like this\nLogic           : hey yer checkers  are da best \nMystic PL       : Czesc maluchy\nYodel           : hello to all of you, nice intro\n\n                 -======================================-\n                              Fuckings go to\n                 -======================================-\nPolish telecom (TPSA): fucked up assholes\nall you stupid lamers here that even can''t do a simple file description\nZonder Lamando       : fuck yerself\nMcDonald''s           : this McChampion is BuLLSHiT\n\n\n@endnode\n\n@node contact "Contact me ..."\n                *** For any improvement or bug reports ***\n             *** write to WiLD THiNG at one of these boards ***\n\n\n   CRaZY WoRLD    ++48-2-6636797           DiXiE          ++48-71-575825\n   Edge Of Sanity ++46-346-81852           Matta          ++48-22-314328\n\n@endnode\n\n@node tools "Other WiLDToolz"\n                          LooK ouT FoR THe oTHeR \n      ____  ____  ___ __ _______ _____________________   _____________\n     /    /\    \/   \  :       \        /     :      : /    /       /\n    //           \___/  :___     \   ___/ ____ : ____ :/    /___    /____\n    \            /   \      \ /  /    /:       :      :        /   /    /\n     \____/\____/\___/______/___/____/ :_______:______:_______/________/\n\n\n[----- NAME ------|------ DESCRIPTION -------|------- FEATURES ---------------]\n WiLDRead v0.13   | file/archive/log viewer  | text search\n                  | AIM door                 | file/arc info\n                  |                          | next/prev. page\n                  |                          | page selection\n[-----------------|--------------------------|--------------------------------]\n WiLDNeW v0.4     | new user questionaire    | multilanguage\n                  | AIM door                 | baud checking for questions\n                  |                          | multiple answers\n                  |                          | text comments (internal ed)\n                  |                          | sysop review of new users\n[-----------------|--------------------------|--------------------------------]\n WiLDBull v0.2    | global bulletins         | scroll bar selection\n                  | AIM door                 | all bulls in one dir\n[-----------------|--------------------------|--------------------------------]\n WiLDMenu v0.1    | multi level menus        | all menus in one file\n                  | AIM door                 |\n[-----------------|--------------------------|--------------------------------]\n WiLDKick v0.1    | unwanted users kick out  | show  msg to user & hang up\n                  | AIM door                 |\n[-----------------|--------------------------|--------------------------------]\n WiLDVote v0.9    | vote door                | configurable user add/delete\n                  | AIM door                 | of topics and itemz\n                  |                          | download of result file\n                  |                          | result output with graph bars\n[-----------------|--------------------------|--------------------------------]\n WiLDLiST v0.7    | file LIST dl             | download all filelists from\n                  | XIM door                 | conferences the user has \n                  |                          |  access TO in one file\n[-----------------|--------------------------|--------------------------------]\n\n@endnode\n','\n',char(10)),NULL,'auto-added',8430,5,0,NULL,NULL,'tau_ws01','scan',1780048764);
INSERT INTO door_catalog VALUES('tau_wv10','TAU-WV10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TAU-WV10.LHA',NULL,'XIM','__________  __. _______  __.  ______',NULL,NULL,'TAU','.__\__  ____ \/  |_\____  \/  |_/  ___/___. |    /  |  |  \  |  \  l  /   | \    \    | `---/   |  .   \ l   \ .  \   l  \--  \---''',replace('   __________  __. _______  __.  ______\n.__\__  ____ \/  |_\____  \/  |_/  ___/___.\n|    /  |  |  \  |  \  l  /   | \    \    | \n`---/   |  .   \ l   \ .  \   l  \--  \---''\n    \___|__|___/_____/_|___\_____/____/EaZ\n           PReZeNTZ aN /X AIM DooR\n               WiLD Vote v0.10\n   The Best Multi-Purpose Vote Door eVeR\n  -+- MaJoR BuG FiXeS & NeW FeaTuReS -+-\n','\n',char(10)),'wildvote.guide',replace('@database WiLDVote.doc \n\n@node MAIN "WiLDVote v0.10 DoX (c) 07/94  WiLD THiNG/Mannassas"\n\n                           [---> Mannassas <---]\n                               presents the\n      ____  ____  ___ __ _______ _____________________   _____________\n     /    /\    \/   \  :       \        /     :      : /    /       /\n    //           \___/  :___     \   ___/ ____ : ____ :/    /___    /____\n    \            /   \      \ /  /    /:       :      :        /   /    /\n     \____/\____/\___/______/___/____/ :_______:______:_______/________/\n                                  SeRieS\n     ====================================================================\n                               WiLD VoTe v0.10\n                  written 01 - 07/94 by WiLD THiNG/Mannassas\n     ====================================================================\n\n                              C O N T E N T S\n              @{" Features            " link "overview"}    @{" Preface           " link "preface"}\n              @{" Installation        " link "installation"}    @{" Greetings         " link "greets"}\n              @{" Future improvements " link "improvements"}    @{" Contact           " link "contact"}\n              @{" other WiLDTooLS     " link "tools"}    @{" History           " link "history"}\n                                \n                                 \n\n@endnode\n@node preface\nThis is a multi-purpose vote door, you can use it for your mag, just for\nfun or anything else. I wrote this door 6 month ago in ARexx and am still\nfighting with myself to rewrite it in E for a better speed, but somehow I\ncan''t get my ass up... so I did sum really necessary bug fixes...\nAfter a long time /X got it''s own built-in voting booth (VO) but it''s quite\nshitty if you have seen it...\n\n             Sø HâVë â Hø®N¥ Ðâ¥ âNÐ Mâ¥ Ðâ Wâ®ëZ Bë W¡TH ¥øµ\n\n                         ¥øµ®S   WiLD THiNG/TauruS\n\n\n\n@endnode\n\n@node overview\n                          --- F E A T U R E S ---\n\n· scans for new topics at login and lists them\n· everyone can add/delete topics and items to vote on (access level\n  depending, differs on every topic if a user can add items or not)\n· creates complete result list for free download at wish\n· users votes will be stored, so he can look where he voted on and change\n  his vote - everyone can vote only once\n· results are shown sorted with percentage and graph bars\n· info who and when somebody created a topic and optional long description\n· optional logs to callerslog\n· show list of users\n\n\n              *** THIS DOOR DOESN''T CONTAIN ANY BACKDOORS ***\n\nThe  only  ''hidden''  function  is  the  command ''q'' which will exit without\nsaving(for access higher than 250)\n\n@endnode\n\n@node installation\n                      --- I N S T A L L A T I O N --\n\nExecute  the  SETUP  script,  it  will copy the files where they belong and\ncreate  some  needed  files  and dirctories, it won''t do any harm to yer HD\nthen edit the following files TO yer needs:\n\ndoors:wildtools/wildvote/tems/1         <- change Name of item to anything\n                                           you want\n\ndoors:wildtools/wildvote/tems.wv        <- change it according to this\n\n                     first line  - number of topics\n                     second line - name of the topics\n                     third line  - access level needed to add item\n\n\n\nIf  you  want  WiLDVote  to  be started automatically at every logon and to\ncheck  if  a  user hasn''t voted on a topic yet you''ll have to use two names\nfor  it,  for  the auto-start it MUST be ''WVC'' for the other anything else.\nNow put the ~CC_WVC command to your bull.txt.\nThe  problem  is  that  WiLDVote shouldn''t be used at more than one node at\nonce  but  as  WiLDVote has two different names there might be some problem\nwith the stats files.\nWV is an AIM type door, MULTINODE=NO\n\nHave a look at the WiLDVote.cfg file, here the access levels for the\ndifferent actions are defined.\n\n@endnode\n\n@node improvements\n                    ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                    The complete version will contain:\n                    ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n    - item deletion\n    - installation routine\n    - list of voters\n    - conversion to Amiga E for speed improvement\n\n@endnode\n\n@node history\n                    ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                                 History:\n                    ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n- v0.3          completely rewrote it after the old version was gone after\n                a HD crash\n- v0.4          added review with sorting\n- v0.5          first public beta release\n                Review improved with graph bars, access checking for\n                delete/add\n- v0.6          access checking for each topic\n- v0.7          improved vote scanning: now topics are shown at login,\n                topic menu  shown in two rows\n\n---------------------------------------------------------------------------\n                         v0.8 - released 08-Jan-94\ngrafical  output  improvements,  made  scan  routine look nicer, added save\nprogress  indicator,  searches  for  duplicate  items,  checks  now if item\nalready  exists,  removed  some  minor  bugs,  now  info  option  with long\ndescription possibility, configurable callerslog option\n---------------------------------------------------------------------------\n                         v0.9 \nagain improved the design a bit and made it more compact, updated helpfile,\nresult download  option as ANSI file\n---------------------------------------------------------------------------\n- v0.10 06/07/94        some bug fixes and little improvements like\n                        list of voters and minor improvements in operation\n---------------------------------------------------------------------------\n\n\nIf you want beta - test my tools @{"call me" link "contact"}.\n@endnode\n\n@node greets "Greetings & Fuckings"\n                 -======================================-\n                       Greetings go to(in no order)\n                 -======================================-\n\nall   Ex-Mannassas   &  FeaR  members,  Tic.,  R19,  Dragon/Motion,  Vince,\nAndy/Motion,  Sunset, Donald/Motion, Vince, The Generat, Wild Child/Taurus,\nEaZy-E/Taurus,  Zielu/Mad  Elks, uNReaL/Surprise Prod., Easy Rider/Mystic &\nTRSi,  EMPiRE/Mystic,  ByteAndi/TRSi,  Selz/Nova Acies(?), The Trader/FeaR,\nChipsi/Taurus,   Crazy  Squaw,  Calypso/GOD,  KC,  C/\Te¥e/Insane,  all  my\nBeta-Testers, and all others I forgot ....\n                                    ____\n ___________________________________\  /________________________________\n(__________________________________ \\// _______________________________)     \n \_________________________________\ \/ /______________________________/\n                                   \\  //\n                                    \\//\n                                     \/\n\n                     aND  LaZT  BuT  OF CoZ N°T LeaST\n              a BiG, FaT & HaiR¥ GReeT¥ T° a££ M¥ HoRNeD BRoS\n\n                  \n\nFranklin/Termos : YO, (I hate this RAP & similar shit), keep smilin'' & thx\n                  for da fonts\nuFoK/MySTiC     : thx FøR äLL THøZë µPPZ\nDune/FeaR       : YeP that''s ¥ouR ASCii STuFF, ThX aN¥Wa¥\n      /\      Artie/Taurus : hi hope to chat to ye as soon as possible,\n ____/  \____                what about that new stuff ??\n \   /\/\   / Bionic/Yodel : w8in'' for another all-thru-the-night chat\n  \  \/\/  /  Fazer/Razor 1911: I''ll call as soon as I can, promised\n  /        \  Vinzi/Yodel     : Nice  txt in that intro (YC3+4)\n /___ () ___\ SiNTAX/WøT      : ...your examples in E and your AEDoor.library\n     \  /  Wouter van Oortmerssen : ... Amiga E compiler, it''s the BEST\n      \/  Big C & Amiga   : ... the best toy for bored programmers ;-)\n\nRage against ZK : Go on like this\nLogic           : hey yer checkers  are da best \nMystic PL       : Czesc maluchy\nYodel           : hello to all of you, nice intro\n\n                 -======================================-\n                              Fuckings go to\n                 -======================================-\nPolish telecom (TPSA): fucked up assholes\nall you stupid lamers here that even can''t do a simple file description\nZonder Lamando       : fuck yerself\nMcDonald''s           : this McChampion is BuLLSHiT\n\n@endnode\n\n@node contact\n                *** For any improvement or bug reports ***\n             *** write to WiLD THiNG at one of these boards ***\n\n@endnode\n\n@node tools\n                          LooK ouT FoR THe oTHeR \n      ____  ____  ___ __ _______ _____________________   _____________\n     /    /\    \/   \  :       \        /     :      : /    /       /\n    //           \___/  :___     \   ___/ ____ : ____ :/    /___    /____\n    \            /   \      \ /  /    /:       :      :        /   /    /\n     \____/\____/\___/______/___/____/ :_______:______:_______/________/\n\n\n[----- NAME ------|------ DESCRIPTION -------|------- FEATURES ---------------]\n WiLDRead v0.13   | file/archive/log viewer  | text search\n                  |                          | file/arc info\n                  |                          | next/prev. page\n                  |                          | page selection\n[-----------------|--------------------------|--------------------------------]\n WiLDNeW v0.4     | new user questionaire    | multilanguage\n                  |                          | baud checking for questions\n                  |                          | multiple answers\n                  |                          | text comments (internal ed)\n                  |                          | sysop review of new users\n[-----------------|--------------------------|--------------------------------]\n WiLDBull v0.2    | global bulletins         | scroll bar selection\n                  |                          | all bulls in one dir\n[-----------------|--------------------------|--------------------------------]\n WiLDMenu v0.1    | multi level menus        | all menus in one file\n[-----------------|--------------------------|--------------------------------]\n WiLDKick v0.1    | unwanted users kick out  | show  msg to user & hang up\n[-----------------|--------------------------|--------------------------------]\n WiLDList v0.7    | global filelist dl       | packs filelists from all confs\n[-----------------|--------------------------|--------------------------------]\n WiLDStat v0.1    | Stats door               | replacement the syscmd/s door\n[-----------------|--------------------------|--------------------------------]\n@endnode\n','\n',char(10)),NULL,NULL,10962,1,0,NULL,NULL,NULL,'scan',1780048764);
INSERT INTO door_catalog VALUES('tbf_ak11','TBF-AK11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TBF-AK11.LHA',NULL,'XIM','ADDKRUSH.040',NULL,NULL,'TBF','|         |__        ______________ |      _____/----.  |       ______/ ._ |         |     _|-----.  -------'' _____.',replace('    _________\n   |         |__        ______________\n   |      _____/----.  |       ______/\n._ |         |     _|-----.  -------'' _____.\n|  |_________|     \__    |       |        |\n|[cP!]- ---|        |     |_______|[nO 001]|\n|:-------- |     _________| --------------:|\n|`-[tBF!]--`--------''-`-hoLLoW hEaRTeD!---''|\n| 2DAY IT IS : ADDKRUSH v.1.1 BBS adder    |\n| Coder      : aSPHYX^tBf                  |\n| Releasedate: 26.09.1997                  |\n`------------------------------------------''\n','\n',char(10)),'ADDKRUSH.readme',replace('\n- -- -------------------¡\n          .::.       [biNARY fOUNdAtiON]-[tbF]\n         .:· ::                         ____        _____\n         ::_______      ____ _____     |    |      |     |_\n        .:''   ___/-.___|    |_    \____|    |______|    __/____ ________ ____\n        ::    |    |   |    | |    \_ _|    |  ___/__    |-----''.   ___/-.   \\n      :::::   |               |     / \_       \_    \_         |   |   |     \_\n       .:·_________  _________|        |        |     /             |          /\n       :·        |_____|[cP!]-|__________   ____|  ____________        ___    /\n ·----::-----------------------------·|_____|·-·|___/·-------·|_________|____/\n      :·     WE ARE HEROICALLY BACK TO PRESENT YA THIS TIME .......       .\n     ::                                                                   |\n    .:·             ADDKRUSH v1.1 by aSPHYX^tBf                           |\n    ::                                                                    |\n   .:·         tHe bEsT txt-f!le BBS-aDDer/kRuSheR eVEr!                  |\n.: ::                                                                     |\n:. :·                                                                     |\n ::· ·--------------------------------------------------------------------''\n\n\nThis is the testimony of all that I have seen and all that I have learned:\n\nOn a night a full moon aSPHYX slept well and warm beneath the upper world \nin the realms of the UNdergrouND EMpiRE when, suddenly, his slumber was \ndisturbed by the voice of his humble servant WiiTigO who, after entering \nhis sleeping chamber, gesticulated in a somewhat aroused state:\n\n"Hell shit! Aquaadder is so fucking slow! And it can''t even remove the ads\nof Los Endos that is always faster than we are! I am desperate!"\n\n"Fear not, for help is here!"\n\nWith disbelief in his loyal eyes WiiTigO looked up at his master and felt\nthe passionate flame of perfection burning behind the somnolent but still\nmajestic figure.\n\n"Let the moon and the sun pass and your pain will be releaved!"\n\nAnd aSPHYX descended upon his coding chamber and was not seen until the\ndawn of the following day when he triumphantly opened wide the door to the\ninnermost sanctum.\nKing PEST, WiiTigO and after a while even Z-bOY gathered around the source\ncode of the all new ADDKRUSH BBS-Adder.\n\nAfter a short inspection King PEST could not hold his breath any more:\n\n HARK! THAT''S WHAT WE ALL HAVE WAITED FOR!\n THIS ONE \n *IS FASTER THAN ALL OTHERS BEING WRITTEN ENTIRELY IN OPTIMIZED ASSEMBLER!\n *CAN EVEN ADD TO THE MIDDLE OF A FILE, DIRECTLY ON TOP OF FILE_ID.DIZ!\n *ALLOWS YOU TO REMOVE THE ADS OF OTHER BOARDS VIA BRAINFILE!\n *ADDS DATE, TIME, BBS-NAME AND UPLOADER (if your bbs-soft supports this)!\n *COMES IN CPU-SPECIFIC EXECUTABLES!\n\n"But how" asked Z-bOY "do we use it?"\n\n"That''s all too easy, behold!\nJust run ADDKRUSH <txt-file> and if you want you may also give the name\nof your BBS and the name of the uploader.\nIf you have set the corrsponding options in the ADDKRUSH.config file\nADDKRUSH will then load the .header .tail and .mid data in order to add\nyour logos to the txt-file.\nSetting the KRUSHBRAIN option in your .config file will make ADDKRUSH scan\nthe txt-file for data that matches the patterns found in ADDKRUSH.brain and\nkill it off the txt-file.\nWell, no more to say."\n\n"But if tBf releases this program to the public, how do people know where\nto send bug-reports to?"\n\nFierce and wicked did aSPHYX look upon his co-sysop. Finally, he turned to\nspeak:\n\n"They may ask at any tBF-board or mail me directly at [email removed]!" \n\n"Ok. No more to ask!"\n\nAnd from that day on contentment and joy ruled the realms below and\n*hopefully* many other boards....\n\n \n   _______ __ _ _ /    _____________ __ __   / _______ ____ _ _ _   /  ___ _ _\n                 /  /                     /o/                     // /\n     . ·     ·  /////  TBF reAdMe        ///                     ////\n ______ __ __ _ //_   ____ ___ __ _ __   / /  _______ _ __ __ _ / /o ___ __ _\n                /                         /                      /\n               o\nEOF','\n',char(10)),NULL,'auto-added',24422,4,0,NULL,NULL,'tbf_ak11','scan',1780048764);
