************************************************************************\n\nInstalling :\n\n		-Just Copy All the File''s 2 there right Dir.\n\n*******************************************************************************\n\nProblems :\n\n		- If U Got Problems With the Installation ,\n		  then there are only 2 reasons :\n                \n                * There Is a Little Bug ( But I don''t think So );\n                * You are a Sysop for About 10 Min.\n\n                In Both reasone the best Solution is 2 call Us at\n                The Brothers BBS +31(0)164-255288\n\n\n\n\nTjauW TaGgY.','\n',char(10)),NULL,'auto-added',22187,4,0,NULL,NULL,'tbs_ascn','scan',1780048764);
INSERT INTO door_catalog VALUES('tbs_wbl3','TBS-WBL3.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TBS-WBL3.LHA',NULL,'XIM','friendsonly.exe',NULL,NULL,'TBS','\    _  _    /  _   \_     ____/ ! wORLD \__/    \__/      __/  ____  \  ¡ BBS /      \_    |    \_    /   \_! lIST',replace('________________________________ .          \n\    _  _    /  _   \_     ____/ ! wORLD\n \__/    \__/      __/  ____  \  ¡ BBS\n   /      \_    |    \_    /   \_! lIST\n   \___    /\_____    /_____    /¡       03\n.------\__/-------\__/------\__/ `---------.\n!                                          !\n¡          - wORLD BBS lIST 03 -           ¡\n!      - 6 new boards - new output -       !\n¡                                          ¡\n`----[ sELECTOR ]----------[ 03/mAY/98 ]---''\n','\n',char(10)),'ReadMeFirst.txt',replace(' \n[33m1>\n[31mI will have to tell you that the world bbs list\nis now being relaesed bij [33mTBS [31mmain reason for this is\nthat Selector hase left hIGHLIGHT not for any reason\nbut just because he wants to have more time for TBS.\n \n[33m2>\n[31mThere is a new option availble .. iT''S cALLED\n         [33mfORM cREATIOn uTILITIE\n[31mit is just a arexx proggie for you so you can edit the form\nand it will created a form bulletin.\n \n[33m3>\n[31mIf you have any idee''s for the WBL.\nPlease let me hear them.\n \ngREETZ selector^tbs\n','\n',char(10)),NULL,'auto-added',32033,4,0,NULL,NULL,'tbs_wbl3','scan',1780048764);
INSERT INTO door_catalog VALUES('tc_link','TC-LINK.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TC-LINK.LHA',NULL,'XIM','.\\--------------------------------------//.',NULL,NULL,'TC','|                                          | |How to Connect a Terminal program to a BBS| |                                          |',replace('.\\--------------------------------------//.\n|                                          |\n|How to Connect a Terminal program to a BBS|\n|                                          |\n|  Done via Ncomm -> Amiexpress (5000cps+) |\n|                                          |\n| have fun ;)                              |\n|_                          thundercat^dc _|\n //__________________________.[30-7-98]._\\\n','\n',char(10)),'ncomm->bbs.txt',replace('\012How to Connect a Terminal program to a BBS\012\012First of all i use AmiExpress and Ncomm in examples.. but will surely work on other\012systems too!\012\012\012I used my hypercom4 serialcard bcoz my serialport somehow fucked it up..\012i guess this problem has something to do localy here..\012\012Well..\012\012BBS Side:\012\0121. Write in you ''serial.device'' you are using in the bbs:node.x/serial.info\0122. Set the baud rate to 56700 (if both machines got Serialcards i guess 115200 works)\0123. done the bbs side ..RESET\012\012Linker side:\012\012just use Serial.device if you don''t have an serialcard..\012\0121.Load ncomm\0122.Go to macro menu\0123.Insert in F1 column OK\n\0124.Insert in F2 column RING\n\0125.Insert in F3 column CONNECT 57600\n\0126.Set the baudrate to 57600\0127.Enable Zmodem protocols\012\0128.you are ready to go..\012\012When the bbs has loaded and the linker are in ncomm ,the one in Ncomm will\012get the bbs sides Initstring in the ncomm screen..\012\012when bbs node is ready ..ncomm side presses f1,f2,f3 ..it can take some time\012before you get the connection but just press the macro keys like hell and it will work ;)\012\012[-]\012\012\012This is just an lame txt for you dudes that likes to link alot ..it is faster\012than normal serial link ,and a hell of a lot better than parallel link ;)..\012\012CPS will lay around 5000CPS ;)\012\012\012Thnx to Baffle\dlm for the info''s ;)\012\012other greets goes to all DC membahz(looooove yah!)\012 + #Amielite,#sid64 dudes ,and ofcoz others who deserves it =)\012\012\012\012ThunderCat^digital corruption','\012',char(10)),NULL,NULL,2853,3,0,NULL,NULL,NULL,'scan',1780048764);
