INSERT INTO door_catalog VALUES('tcomment','TCOMMENT.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TCOMMENT.LHA','TComm','XIM','TComm',NULL,NULL,NULL,NULL,replace('SYSOP COMMENT DOOR\n','\n',char(10)),'ThrashComment.readme',replace('Short:    Sysop comment door.\nUploader: Leo Davidson <[email removed]>\nAuthor:   Tony Witchet <NO EMAIL ADDRESS>\nType:     comm/amiex\n\nThrashComment - ThrashComment v1.00 by Thrash. (Assembler)\n\n- Sysop Comment Door.\n\n*** This archive is *not* *new*, I am just putting all the Gods''Gift utils\n*** on Aminet for everyone (and so that people can stop bothering me :-).\n\n .--------------------------------------------- ----- ---- --- -- -  -   -  |\n | Leo ''Nudel'' Davidson - Yr1 Computation - [email removed] |\n |  -   -  - -- --- ---- ----- ---------------------------------------------''\n','\n',char(10)),NULL,'auto-added',13572,6,0,NULL,NULL,'tcomment','scan',1780048764);
INSERT INTO door_catalog VALUES('td183','TD183.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TD183.LHA','clearacct','XIM','TrapCall',NULL,NULL,NULL,NULL,replace('TrapDoor Development\n','\n',char(10)),'Registration.txt',replace('\n\n\n\n\n                              How To Register\n                              ---------------\n\n\n     1.  Print out the "TrapLand Software Registration Form" (to be\n         found on the next page).  \n\n     2.  Please print or write LEGIBLY...  \n\n         2.a. Fill in your name and mailing address.  \n\n         2.b. Your fidonet address (not required, if present you will\n              be automatically notified when your copy is shipping).  \n\n         2.c. Your private voice telephone number (not compulsory).\n              If possible, use the form "+43-(222)-5567863", where 43\n              is the country code and 222 is the area code.  \n\n     3.  Calculate...  \n\n         3.a. Tick the items you would like to register (TrapDoor\n              and/or TrapToss). Fees are given in ATS (Austrian\n              Schillings).  \n\n         3.b. You are eligible for the special bonus reduction if you\n              are registering both TrapDoor and TrapToss at the same\n              time.  \n\n         3.c. Decide how to transfer the money. We would suggest\n              cash, a postal money order, a wire bank transfer or an\n              EuroCheque. If you decide against one of those and for\n              a foreign cheque, a bank draft or a money order, please\n              remember that this involves a surcharge.  \n\n         3.d. Sum up the amount for the ticked items, and fill in the\n              the "Total amount" field.  \n\n     4.  Send the registration form to TrapDoor Development.  \n\n                             TrapDoor Development\n                              Maximilian Hantsch\n                        Matzleinsdorfer Platz 3-4/3/10\n                                  A-1050 Wien\n                               Austria / Europe\n\n                             Fido: 2:310/6 \n                        Email/Fax: +43-1-603-8532 \n\n         Bank: Österreichische Postsparkasse (PSK), BLZ 60000, \n               Account 6.777.234, "Maximilian Hantsch" \n\n     5.  Wait for the mail man. Thank you for registering! \n         Please allow up to eight weeks for delivery.  \n\n\n\n\nINSERT INTO door_catalog VALUES('td183crk','TD183CRK.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TD183CRK.LHA','MakeTDKey','XIM','MakeTDKey','1.83',NULL,NULL,NULL,replace('TrapDoor For /X V1.83 CRacket\n','\n',char(10)),'2Nodez.TXT',replace('\n           -( [ DiGiT/\L X ] [ oNE oF tHE fASTEST iN eUROPE ] )-\n\n            PaRaDiSe wORLD iNNOVATION wORLD dISTRIBUTION sITE!\n\n              ________  ____________________  __   _/\  ___\n              \____   \/  / ___/  /_  _/    \/ /   \  \/ \/\n               \   \   \ / /__^  / / //  ^  /  \___ \    / \n               /_______//\___/__/ /_/ \_/\_/\_____/ /    \_\n               DREAM MACHINE WorLD DHQ CenTer ©    /__/\___\n\n            PaRaDiSe : wORLD iNNOVATION wORLD dISTRIBUTION sITE!\n            NirVaNa  : wORLD iNNOVATION wORLD dISTRIBUTION sITE!\n\n  Node [1] +31-570-637050  Node [2] +31-570-636468  Node [3] +31-570-677702\n\n  Amiexpress V4.20 Registered On An Amiga 2000 GVP-Tekmagic 68060 32MB KS3.1\n    Pioneer Changer DRM-604X + Toshiba Cd-Rom 4 HD''s 7110MB Space Total...         \n\n   2 * cREDITZ fOR mAJORS! 3 * cREDITZ fOR mAJORS fROM yOUR oWN gROUP!\n    pROVIDING yOU: Amiga ECS/AGA, PC, AmiExpress, Sex Pic, Sex Stories\n\n          ---»> nO nEW uSER pASSWORD aND/oR sYSTEM pASSWORD! <«---    \n                                                                      \n       -( [ DiGiT/\L X ] [ oNE oF tHE BesT FroM The EaSt SidE ] )-\n\n','\n',char(10)),NULL,'auto-added',65807,3,0,NULL,NULL,'td183crk','scan',1780048764);
INSERT INTO door_catalog VALUES('tdial165','TDIAL165.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TDIAL165.LHA','TDialC','XIM','TDialC',NULL,NULL,NULL,'Trapdoor Enhanced Redial Scheduler',replace('         TDial 1.65 \nTrapdoor Enhanced Redial Scheduler\n','\n',char(10)),'Quickie.doc',replace('\n0. Contents\n\n   1. Registered <-> Unregistered \n   2. ATTENTION - > KeyFile - Copying & Check\n   3. Commandline Parameters\n\n1. Registered <-> Unregistered \n\n   The Unregistered Version will not run in PMODE 2 & 3\n\n\n2. ATTENTION - > KeyFile - Copying and Check\n\n   >>>> The KeyFile will configure TrapDoor to the Node found in it! <<<<\n\n   CHECK THE FIRST PART OF THE KEYFILE! This Part is your uncrypted\n   Nodenumber. TDialC will set TrapDoor to this Node before calling \n   out!\n\n   Example:\n\n   Your Node Number is 2:249/49.0\n\n   The KeyFile MUST look like ( use the "c:type" command )\n\n      2:249/49.0   ( Your Node-Number     )\n      ##########   ( ## is The_Key_Itself )\n\n   In this case TrapDoor will be set to 2:249/49 as CALLING Node, which will\n   cause a lot of problems for you, because the originating address is\n   wrong! (e.g. passwords will not fit!)\n\n\n   !!!!!!!!!!!!!!!!!!!!!!!SO DON''T USE A COPIED KEYFILE!!!!!!!!!!!!!!!!!!!\n\n\n   3. Commandline Parameters\n  \n   TYPE ACDFOR               - Type of Packets to transfer\n                               You may combine them, e.g. TYPE CR\n                               for CRASH-Mails and Request''s\n\n   POLL "#:#/#.#[ #:#/#.#]"  - Poll these nodes instead of scanning Outbound\n                               The TYPE and the POLL - Parameter may not \n                               be used together! \n\n   RETRY num                 - Number of retries\n                            \n   PMODE 1|2|3               - PMode 1 will call [retry] times the first\n                               node (or until a connect). Then it will dial\n                               the next, and so on...\n\n                               PMode 2 (only registered Users!) will\n                               call each node one time, then start again \n                               the circle.\n\n                               PMode 3 (only registered Users!) will be \n                               only used together with the POLL - parameter.\n                               It is useful to call a "MultiLine - Node", \n                               because it stops dialling right after the\n                               first "CONNECT".\n\n   PORTNAME portname         - use <portname> as TrapDoor`s RexxPortName.\n                               (defaults to "TrapDoor")\n\n   DELAY secs                - Redial-Delay between the calls.\n\n   CONFIG filename           - TDial''s configfile, if it is not located \n                               in MAIL: as TDial.CFG\n\n   SCAN|SHOW                 - Show only, do not dial, for testing or just\n                               showing the files residing in outbound.\n\n\n','\n',char(10)),NULL,'auto-added',33837,5,0,NULL,NULL,'tdial165','scan',1780048764);
INSERT INTO door_catalog VALUES('tds_a20','TDS_A20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TDS_A20.LHA',NULL,'XIM','AMFETAMiN.000',NULL,'The','TDS','\   ______________    \_____  siL/ +--\   /     \/    /    /    /____/--------+ |   \ /      /    /    /\____   \  doodles |',replace('  __________________________________\n  \   ______________    \_____  siL/\n+--\   /     \/    /    /    /____/--------+\n|   \ /      /    /    /\____   \  doodles |\n|    X      /   _/    /     /   /   shock  |\n+---/______/_________/______\  /-----------+\n.----------------------------\/------------.\n| AMFETAMiN v2.00, By The Silencer in 1994 |\n+------------------------------------------+\n| New Good lookin'' /X Last Callers Utility |\n`------------------------------------------''\n','\n',char(10)),'AMFETAMiN.GUiDE',replace('@database AMFETAMiN v2.00 docs\n\n@remark $Ver: v2.00 (04-27-94)\n@remark published by dOoDLEs^sHOck\n@remark amigaguide transformation by d-Zire/DoOdLeS^ShoCK & The Silencer\n\n@node "MAiN" "AMFETAMiN v2.00 Documents"\n                 °\n               : .  /\___  °\n               ¦: ./     \  °\n               |¦:/  (__  \°\n               ||/      \  \\n               |/        \_ \ · M · F · E · T · A · M · i · N\n           - --+\_________/ /================================\n                      \____/           Version 2.0, Release I\n\n                [ Release date: Tue Apr 27 00:00:00 1994 ]\n =========================================================================\n                  (c)-94 by The Silencer / DoOdLeS^ShoCK\n =========================================================================\n @{"[           COVER PAGE           ]"link "About"       }     @{"[  EXAMPLE OUTPUT (PLAiN ASCii)  ]"link "Output"}\n @{"[      FEATURES, PERFORMANCE     ]"link "Features"    }     @{"[ ERRORMESSAGES, TROUBLESHOOTiNG ]"link "ErrorMsg"}\n @{"[   INSTALLATION, CONFiGURATiON  ]"link "Installation"}     @{"[        ADDiTiONAL NOTES!       ]"link "Additional"}\n @{"[                  T E C H N i C A L   S U P P O R T !                  ]"link "Contact"}\n =========================================================================\n                  (c)-94 by The Silencer / DoOdLeS^ShoCK\n =========================================================================\n       AMiGAGUiDE TRANSFoRMATioN AND DESiGN by d-Zire/DoOdLeS^ShoCK\n@endnode\n\n@node "About" "About AMFETAMiN v2.00"\n\n                               @{"[ MAiN MENU ]"link "MAiN"}\n                               @{"[ NEXT PART ]"link "Features"}\n\n =========================================================================\n                         - About AMFETAMiN v2.00 -\n =========================================================================\n\n                Last Callers Util for AmiExpress BBS Clones\n              Written by The Silencer / doodles^shock in 1994\n\n                       Copyright ©1994 The Silencer\n                Permission is granted to freely distribute\n              this product for non-commercial purposes only,\n                  as long as all files remain unmodified.\n\n   AMFETAMiN is written in highly optimized C code for best performance!\n\n·Why Did I Make a Last Caller Util ?\n\n Well, to be honest I decided to make one when I saw a local BBS that had\n Macromans PowerCaller installed that looked like shit and was written in\n ARexx. BTW He ripped the fucking code from a dude in the US that a friend\n of mine multichatted with on sum US board, he was quite pissed at\n macroman for this! Don''t remember the dudes name but I guess macroman do.\n\n Shortly after this release there will be another one with sum updates.\n Ascii output aswell, stripped code, more configurable etc..\n@endnode\n\n@node "Features" "Features in AMFETAMiN v2.00"\n\n                               @{"[ MAiN MENU ]"link "MAiN"}\n                               @{"[ NEXT PART ]"link "Installation"}\n\n =========================================================================\n                      - Features in AMFETAMiN v2.00 -\n =========================================================================\n\n· Quick As A Flash,\n  Totally Independent of Callerslog FileSize! Scans a 5Mb Callerslog\n  as fast as a 1kb Callerslog.\n  The Only Thing Slowing It Down Is Harddrive Fragmentation :)\n\n· Supports More Than 10 Nodes (0-9) Since New /X Can Handle Up To 32 Nodes\n  Amfetamin Can Handle Up To 99 Nodes So There Will Be No Conflict With\n  Future /X Upgrades.\n\n· Supports All Baudrates From 0(?) Up To 100.000 Baud (21.600,28.800+ etc)\n  No Conflict With New(Higher/Lower?) Baudrates/Modemtypes.\n\n· Supports CPS Rates Over 10.000 (21.600+ TextFileTransfers? Etc.)\n  Up To 99.999 CPS Can Be Recorded.\n\n· Byte Values Shown In Kilobytes Or Megabytes Depending On The Filesizes.\n\n· No Temporary DataFiles Or So Needed, It Uses It''s Own Output As Datafile\n\n· Doesn''t Crash & Burn, if it failures it exits safe with the apropriate\n  errormessage.\n\n· Are Able To Display As Many LastCallers As You Like, Say 100.000 ?\n\n· GREAT LOOKS!\n@endnode\n\n@node "Installation" "Installing - AMFETAMiN v2.00"\n\n                               @{"[ MAiN MENU ]"link "MAiN"}\n                               @{"[ NEXT PART ]"link "Output"}\n\n =========================================================================\n                      - Installing AMFETAMiN v2.00 -\n =========================================================================\n\n           AMFETAMiN.000 is the version optimized for 68000+ systems\n           AMFETAMiN.030 is optimized for 68020+ systems\n\n Just Add this To Your Logoff-Script:\n\n AMFETAMiN.xxx <output> <node> <calls> <sysop/nosysop>\n\n        <output> Is The Textfile That Is Generated... Try RAM:Test.TXT\n          <node> The Node To Process\n         <calls> How Many Calls That Should Be Shown (Unlimited Amount!)\n <sysop/nosysop> If Local_Sysop Logins Should Be Recorded\n\n All <arguments> Are Ofcuz cASEiNSENSiTiVe.\n\n Ex.\n ~~~\n AMFETAMiN BBS:Bull.TXT 1 12 NoSysop\n\n This Line Generates a Last Callers List For Node 1 Displaying Only The\n 12 Last Callers. Local Sysop Logins Will Not Show!\n@endnode\n\n@node "Output" "Ascii output!"\n\n                               @{"[ MAiN MENU ]"link "Main"}\n                               @{"[ NEXT PART ]"link "Output"}\n\n =========================================================================\n                            -  Example Output -\n =========================================================================\n\n ANSI Color Rules!, Check Out The Supplied iFF Image.\n\n\nNd User Name       Location            TimeOnBoard ACTVT U#/Byte D#/Byte Rate\n-- --------------- ------------------- ----------- ----- ------- ------- ----\n01 RAG             »¡mG HQ +46-381-304 20:37-20:38 --HP- --:---- --:---- 28.8\n01 Stain           (^)=-={2oooAd}=-=(^ 20:31-20:36 ----S --:---- --:---- 16.8\n10 SHAN            MANGA RULEZ!        20:13-20:22 ----S --:---- 01:519K 14.4\n00 MFM             = SKiD ROW ^ iPL =  20:01-20:07 ----S --:---- --:---- LOCL\n99 Aquarius        >> THE OUTLAWS <<   19:47-19:57 ---PS 03:017K --:---- 12.0\n01 LoXLeY          ·:..ÊqûÎñÔx..:·     19:26-19:30 C-H-S --:---- --:---- 19.2\n06 MFM             = SKiD ROW ^ iPL =  18:56-18:57 ---PS --:---- --:---- 9600\n03 sUBZERø^&^Gø®0! [B^A - THULERINGEN] 18:29-18:34 -N--- --:---- 02:053K 21.6\n04 [-BUTCH/TdS-]   -*[=DooDLEsHoCK=]*- 18:21-18:27 ----S --:---- 01:194K 21.6\n05 AldriN          +-+©>CyberdynE<©+-+ 18:06-18:20 ---PS 01:459K 01:628K 0300\n21 RAG             »¡mG HQ +46-381-304 17:59-18:03 C-H-- 01:012K 01:025K 12.0\n21 MR.AT&T         AT&T WORLD CONNECT  17:16-17:19 ---PS 02:004K --:---- 14.4\n32 MFM             = SKiD ROW ^ iPL =  17:11-17:13 C---- --:---- --:---- 9600\n-----------------------------------------------------------------------------\n(C)arrier Lost, (N)ew User, (H)acked Password, (P)aged SysOp, (S)canned Files\n-----------------------------------------------------------------------------\nCalls 04-25-94 [ 37 ] Time Online [08:37:23] HiCPS [3006] UL/DL [10.1M/02.3M]\nCalls 04-24-94 [0192] Time Online [14:17:41] HiCPS [3373] UL/DL [17.3M/22.5M]\n@endnode\n\n@node "ErrorMsg" "TroubleShooting!"\n\n                               @{"[ MAiN MENU ]"link "Main"}\n                               @{"[ NEXT PART ]"link "ErrorMsg"}\n\n =========================================================================\n             -  Error Messages (And What To Do About Them)  -\n =========================================================================\n\n This Util Is So Simple So I''m Sure There Won''t Be Any Trouble With It\n But If You Ever Get One Of These Errors (Non Fatal) And You Wonderen What\n They Are All About...\n\n @{"Load Error #1 (ENViroment Statistix)"link "Error1"} @{"Load Error (Callerslog)             "link "Error3"}\n @{"Load Error #2 (ENViroment Statistix)"link "Error2"} @{"**Skipping; Local Sysop Login Entry!"link "Error4"}\n                   \n                   \n@endnode\n\n@node "Error1" "Load Error #1"\n·Load Error #1 (ENViroment Statistix)\n ------------------------------------\n It Didn''t Find The ENV:STATS<node> File That Is Allways Present When A\n User Has Logged Of The System.\n\n Cause: · You Have Run The Util Before The BBS Even Has Started Or\n          Before You Got A Call.\n@endnode\n@node "Error2" "Load Error #2"\n·Load Error #2 (ENViroment Statistix)\n ------------------------------------\n The ENV:STATS<node> file was empty!\n\n Cause: · You Probably Have Shutdown The BBS Before You Run The Util.\n\n What2Do: Make sure you run it directly after a user has logged off.\n          Don''t shutdown the BBS. You can check for yourself if the\n          username is in the STAT file.\n@endnode\n@node "Error3" "Load Error Callerslog"\n·Load Error (Callerslog)\n ------------------------------------\n Couldn''t Process Callerslog For That Node.\n\n Cause: The Callerslog File Didn''t Exist Or Couldn''t Be Opened.\n@endnode\n@node "Error4" "**Skipping..."\n·**Skipping; Local Sysop Login Entry!\n ------------------------------------\n Not An Error, You Have Specified NOSYSOP As An Argument And It Just\n Skip To Record The Last Call If It Was A SYSOP_LOCAL.\n@endnode\n\n\n\n\n\n@node "Additional" "It''s better to burn out than to fade away!"\n\n                               @{"[ MAiN MENU ]"link "Main"}\n                               @{"[ NEXT PART ]"link "Contact"}\n\n =========================================================================\n                          -  Additional Stuff  -\n =========================================================================\n\n         A Thnx must go to Aquarius for helping me out when I run\n                           into wierd shit in C.\n\n\n        >> For Fun, Call the Ruling US Partyline +1-515-945-6700 <<\n       To reach me call my board or scream for me at the partyline!\n                         REPULSE! +46-(0)270-12138\n                            Current NUP: TRANCE\n\n\n Hello''s to:\n\n d-Zire For Doing The AmigaGuide Transformation.\n Borre, Karin, Mj0lkpaket for moral support.\n Latin Kings for music support!\n Coca Cola for making me be up late at night, sleeping in school.\n A Flying Dick Goes To Chopper & Macroman.\n Todays Quote, Excalibur / Complex:               "Utilen kan inte rekna."\n\n@endnode\n\n@node "Contact" "For technical support and/or other quality /X doors contact me at:"\n =========================================================================\n\n                              ·° °     °\n                              : °     ° °· Current NUP = TRANCE\n                              ¦ REPULSE! :\n                              |   _____  ¦\n    GdH_______________________|__/    /__|_____    __________________g''S\n     _/   _____/   ___________  ¬\   /¬\      /___/   _____/   _____/\n    /    __  ¬\   ___)_/     /    \ /   \    /  ¬\____   ¬\   ___)__\n   /      /    \_ /    ¬\_ _______//     \_ /     \_ /     \_ /    ¬\_\n   \_____/      /__      /_/ _______      /__      /__      /__      /\n         \_____/  \_____/     |    \_____/  \_____/  \_____/  \_____/\n                              ¦          |\n                              :° °     ° ¦ Core of the Underground\n                              . °     ° °:\n                                         .\n                             +46-270-12138\n\n =========================================================================\n@endnode\n\n@node "Help" "For technical support and/or other quality /X doors contact me at:"\n =========================================================================\n\n                              ·° °     °\n                              : °     ° °· Current NUP = TRANCE\n                              ¦ REPULSE! :\n                              |   _____  ¦\n    GdH_______________________|__/    /__|_____    __________________g''S\n     _/   _____/   ___________  ¬\   /¬\      /___/   _____/   _____/\n    /    __  ¬\   ___)_/     /    \ /   \    /  ¬\____   ¬\   ___)__\n   /      /    \_ /    ¬\_ _______//     \_ /     \_ /     \_ /    ¬\_\n   \_____/      /__      /_/ _______      /__      /__      /__      /\n         \_____/  \_____/     |    \_____/  \_____/  \_____/  \_____/\n                              ¦          |\n                              :° °     ° ¦ Core of the Underground\n                              . °     ° °:\n                                         .\n                             +46-270-12138\n\n =========================================================================\n@endnode\n','\n',char(10)),NULL,'auto-added',48635,5,0,NULL,NULL,'tds_a20','scan',1780048764);
