INSERT INTO door_catalog VALUES('tds_a22','TDS_A22.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TDS_A22.LHA',NULL,'XIM','AMFETAMiN.ANY',NULL,'The','TDS','\   ______________    \_____  siL/    O :  \   /     \/    /    /    /____/   o ¦   \ /      /    /    /\____   \  doodles',replace('. __________________________________ O\n  \   ______________    \_____  siL/    O\n:  \   /     \/    /    /    /____/   o\n¦   \ /      /    /    /\____   \  doodles\n|    X      /   _/    /     /   /   shock\n|   /______/_________/______\  /       .\n`----------------------------\/------------.\n  AMFETAMiN v2.21, By The Silencer iN 1994 |\n.------------------------------------------''\n| Now 100% BUGFREE, WoRKS oN ALL SYSTEMS !  \n`------------------------------------------>\n','\n',char(10)),'AMFETAMiN.GUiDE',replace('@database AMFETAMiN v2.21 docs\n\n@remark $Ver: v2.21 (06-14-94)\n@remark published by dOoDLEs^sHOck\n@remark amigaguide transformation by d-Zire/DoOdLeS^ShoCK & The Silencer\n\n@node "MAiN" "AMFETAMiN v2.21 Documents"\n                 °\n               : .  /\___  °\n               ¦: ./     \  °\n               |¦:/  (__  \°\n               ||/      \  \\n               |/        \_ \ · M · F · E · T · A · M · i · N\n           - --+\_________/ /================================\n                      \____/         Version 2.21, Release II\n\n                [ Release date: Tue Jun 14 00:00:00 1994 ]\n =========================================================================\n                  (c)-94 by The Silencer / DoOdLeS^ShoCK\n =========================================================================\n @{"[           COVER PAGE           ]"link "About"       }     @{"[  EXAMPLE OUTPUT (PLAiN ASCii)  ]"link "Output"}\n @{"[      FEATURES, PERFORMANCE     ]"link "Features"    }     @{"[ ERRORMESSAGES, TROUBLESHOOTiNG ]"link "ErrorMsg"}\n @{"[   INSTALLATION, CONFiGURATiON  ]"link "Installation"}     @{"[        ADDiTiONAL NOTES!       ]"link "Additional"}\n @{"[                  T E C H N i C A L   S U P P O R T !                  ]"link "Contact"}\n =========================================================================\n                  (c)-94 by The Silencer / DoOdLeS^ShoCK\n =========================================================================\n       AMiGAGUiDE TRANSFoRMATioN AND DESiGN by d-Zire/DoOdLeS^ShoCK\n@endnode\n\n@node "About" "About AMFETAMiN v2.21"\n\n                               @{"[ MAiN MENU ]"link "MAiN"}\n                               @{"[ NEXT PART ]"link "Features"}\n\n =========================================================================\n                         - About AMFETAMiN v2.21 -\n =========================================================================\n\n                Last Callers Util for AmiExpress BBS Clones\n              Written by The Silencer / doodles^shock in 1994\n\n                       Copyright ©1994 The Silencer\n                Permission is granted to freely distribute\n              this product for non-commercial purposes only,\n                  as long as all files remain unmodified.\n\n   AMFETAMiN is written in highly optimized C code for best performance!\n\n·Why Did I Make a Last Caller Util ?\n\n Well, to be honest I decided to make one when I saw a local BBS that had\n Macromans PowerCaller installed that looked like shit and was written in\n ARexx.\n\n@endnode\n\n@node "Features" "Features in AMFETAMiN v2.21"\n\n                               @{"[ MAiN MENU ]"link "MAiN"}\n                               @{"[ NEXT PART ]"link "Installation"}\n\n =========================================================================\n                      - Features in AMFETAMiN v2.21 -\n =========================================================================\n\n· Quick As A Flash,\n  Totally Independent of Callerslog FileSize! Scans a 5Mb Callerslog\n  as fast as a 1kb Callerslog.\n  The Only Thing Slowing It Down Is Harddrive Fragmentation :)\n\n· Supports More Than 10 Nodes (0-9) Since New /X Can Handle Up To 32 Nodes\n  Amfetamin Can Handle Up To 99 Nodes So There Will Be No Conflict With\n  Future /X Upgrades.\n\n· Supports All Baudrates From 0(?) Up To 100.000 Baud (21.600,28.800+ etc)\n  No Conflict With New(Higher/Lower?) Baudrates/Modemtypes.\n\n· Supports CPS Rates Over 10.000 (21.600+ TextFileTransfers? Etc.)\n  Up To 99.999 CPS Can Be Recorded.\n\n· Byte Values Shown In Kilobytes Or Megabytes Depending On The Filesizes.\n\n· No Temporary DataFiles Or So Needed, It Uses It''s Own Output As Datafile\n\n· Doesn''t Crash & Burn, if it failures it exits safe with the apropriate\n  errormessage.\n\n· Are Able To Display As Many LastCallers As You Like, Say 100.000 ?\n\n· GREAT LOOKS!\n@endnode\n\n@node "Installation" "Installing - AMFETAMiN v2.21"\n\n                               @{"[ MAiN MENU ]"link "MAiN"}\n                               @{"[ NEXT PART ]"link "Output"}\n\n =========================================================================\n                      - Installing AMFETAMiN v2.21 -\n =========================================================================\n\n           AMFETAMiN.ANY is the version optimized for 68000+ systems\n           AMFETAMiN.023 is optimized for 68020/30+ systems\n\n Just Add this To Your Logoff-Script:\n\n AMFETAMiN.xxx <output> <node> <calls> <sysop/nosysop>\n\n        <output> Is The Textfile That Is Generated... Try RAM:Test.TXT\n          <node> The Node To Process\n         <calls> How Many Calls That Should Be Shown (Unlimited Amount!)\n <sysop/nosysop> If Local_Sysop Logins Should Be Recorded\n\n All <arguments> Are Ofcuz cASEiNSENSiTiVe.\n\n Ex.\n ~~~\n AMFETAMiN BBS:Bull.TXT 1 12 NoSysop\n\n This Line Generates a Last Callers List For Node 1 Displaying Only The\n 12 Last Callers. Local Sysop Logins Will Not Show!\n@endnode\n\n@node "Output" "Ascii output!"\n\n                               @{"[ MAiN MENU ]"link "Main"}\n                               @{"[ NEXT PART ]"link "Output"}\n\n =========================================================================\n                            -  Example Output -\n =========================================================================\n\n ANSI Color Rules!, Check Out The Supplied iFF Image.\n Or Ascii send the EXAMPLE_OUTPUT.Ansi into your local node /X.\n\nNd User Name       Location            TimeOnBoard ACTVT U#/Byte D#/Byte Rate\n-- --------------- ------------------- ----------- ----- ------- ------- ----\n01 RAG             »¡mG HQ +46-381-304 20:37-20:38 --HP- --:---- --:---- 28.8\n01 Stain           (^)=-={2oooAd}=-=(^ 20:31-20:36 ----S --:---- --:---- 16.8\n10 SHAN            MANGA RULEZ!        20:13-20:22 ----S --:---- 01:519K 14.4\n00 MFM             = SKiD ROW ^ iPL =  20:01-20:07 ----S --:---- --:---- LOCL\n99 Aquarius        >> THE OUTLAWS <<   19:47-19:57 ---PS 03:017K --:---- 12.0\n01 LoXLeY          ·:..ÊqûÎñÔx..:·     19:26-19:30 C-H-S --:---- --:---- 19.2\n06 MFM             = SKiD ROW ^ iPL =  18:56-18:57 ---PS --:---- --:---- 9600\n03 sUBZERø^&^Gø®0! [B^A - THULERINGEN] 18:29-18:34 -N--- --:---- 02:053K 21.6\n04 [-BUTCH/TdS-]   -*[=DooDLEsHoCK=]*- 18:21-18:27 ----S --:---- 01:194K 21.6\n05 AldriN          +-+©>CyberdynE<©+-+ 18:06-18:20 ---PS 01:459K 01:628K 0300\n21 RAG             »¡mG HQ +46-381-304 17:59-18:03 C-H-- 01:012K 01:025K 12.0\n21 MR.AT&T         AT&T WORLD CONNECT  17:16-17:19 ---PS 02:004K --:---- 14.4\n32 MFM             = SKiD ROW ^ iPL =  17:11-17:13 C---- --:---- --:---- 9600\n-----------------------------------------------------------------------------\n(C)arrier Lost, (N)ew User, (H)acked Password, (P)aged SysOp, (S)canned Files\n-----------------------------------------------------------------------------\nCalls 04-25-94 [ 37 ] Time Online [08:37:23] HiCPS [3006] UL/DL [10.1M/02.3M]\nCalls 04-24-94 [0192] Time Online [14:17:41] HiCPS [3373] UL/DL [17.3M/22.5M]\n@endnode\n\n@node "ErrorMsg" "TroubleShooting!"\n\n                               @{"[ MAiN MENU ]"link "Main"}\n                               @{"[ NEXT PART ]"link "ErrorMsg"}\n\n =========================================================================\n             -  Error Messages (And What To Do About Them)  -\n =========================================================================\n\n This Util Is So Simple So I''m Sure There Won''t Be Any Trouble With It\n But If You Ever Get One Of These Errors (Non Fatal) And You Wonderen What\n They Are All About...\n\n @{"Load Error #1 (ENViroment Statistix)"link "Error1"} @{"Load Error (Callerslog)             "link "Error3"}\n @{"Load Error #2 (ENViroment Statistix)"link "Error2"} @{"**Skipping; Local Sysop Login Entry!"link "Error4"}\n                   \n                   \n@endnode\n\n@node "Error1" "Load Error #1"\n·Load Error #1 (ENViroment Statistix)\n ------------------------------------\n It Didn''t Find The ENV:STATS<node> File That Is Allways Present When A\n User Has Logged Of The System.\n\n Cause: · You Have Run The Util Before The BBS Even Has Started Or\n          Before You Got A Call.\n@endnode\n@node "Error2" "Load Error #2"\n·Load Error #2 (ENViroment Statistix)\n ------------------------------------\n The ENV:STATS<node> file was empty!\n\n Cause: · You Probably Have Shutdown The BBS Before You Run The Util.\n\n What2Do: Make sure you run it directly after a user has logged off.\n          Don''t shutdown the BBS. You can check for yourself if the\n          username is in the STAT file.\n@endnode\n@node "Error3" "Load Error Callerslog"\n·Load Error (Callerslog)\n ------------------------------------\n Couldn''t Process Callerslog For That Node.\n\n Cause: The Callerslog File Didn''t Exist Or Couldn''t Be Opened.\n@endnode\n@node "Error4" "**Skipping..."\n·**Skipping; Local Sysop Login Entry!\n ------------------------------------\n Not An Error, You Have Specified NOSYSOP As An Argument And It Just\n Skip To Record The Last Call If It Was A SYSOP_LOCAL.\n@endnode\n\n\n\n\n\n@node "Additional" "It''s better to burn out than to fade away!"\n\n                               @{"[ MAiN MENU ]"link "Main"}\n                               @{"[ NEXT PART ]"link "Contact"}\n\n =========================================================================\n                          -  Additional Stuff  -\n =========================================================================\n\n        >> For Fun, Call the Ruling US Partyline +1-515-945-6700 <<\n       To reach me call my board or scream for me at the partyline!\n                         REPULSE! +46-(0)270-12138\n                          Current NUP: AMFETAMiN\n\n\n Borre, fuck off, your mother is a pig shit farmer.\n You BBS-Ad textfile was the lamest We''ve ever seen!\n Highest ranked ? In what ? Triads Lamerchart ?! Mohahah\n Hitman, for him and his car, driving me the raeggerrund.\n I still have a cold.\n Studenten var 0000sfeeeeest....\n Thnx d-Zire For Doing The AmigaGuide Transformation.\n Excalibur for his nightchats! You are sooo sexy!\n\n@endnode\n\n@node "Contact" "For technical support and/or other quality /X doors contact me at:"\n =========================================================================\n\n                              ·° °     °\n                              : °     ° °· Current NUP = AMFETAMiN\n                              ¦ REPULSE! :\n                              |   _____  ¦\n    GdH_______________________|__/    /__|_____    __________________g''S\n     _/   _____/   ___________  ¬\   /¬\      /___/   _____/   _____/\n    /    __  ¬\   ___)_/     /    \ /   \    /  ¬\____   ¬\   ___)__\n   /      /    \_ /    ¬\_ _______//     \_ /     \_ /     \_ /    ¬\_\n   \_____/      /__      /_/ _______      /__      /__      /__      /\n         \_____/  \_____/     |    \_____/  \_____/  \_____/  \_____/\n                              ¦          |\n                              :° °     ° ¦ Core of the Underground\n                              . °     ° °:\n                                         .\n                             +46-270-12138\n\n =========================================================================\n@endnode\n\n@node "Help" "For technical support and/or other quality /X doors contact me at:"\n =========================================================================\n\n                              ·° °     °\n                              : °     ° °· Current NUP = AMFETAMiN\n                              ¦ REPULSE! :\n                              |   _____  ¦\n    GdH_______________________|__/    /__|_____    __________________g''S\n     _/   _____/   ___________  ¬\   /¬\      /___/   _____/   _____/\n    /    __  ¬\   ___)_/     /    \ /   \    /  ¬\____   ¬\   ___)__\n   /      /    \_ /    ¬\_ _______//     \_ /     \_ /     \_ /    ¬\_\n   \_____/      /__      /_/ _______      /__      /__      /__      /\n         \_____/  \_____/     |    \_____/  \_____/  \_____/  \_____/\n                              ¦          |\n                              :° °     ° ¦ Core of the Underground\n                              . °     ° °:\n                                         .\n                             +46-270-12138\n\n =========================================================================\n@endnode\n','\n',char(10)),NULL,'auto-added',45031,2,0,NULL,NULL,'tds_a22','scan',1780048764);
