INSERT INTO door_catalog VALUES('te_nfv11','TE-NFV11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TE-NFV11.LHA',NULL,'XIM','Docs for NewFront','1.1',NULL,'TE',NULL,replace('Docs for NewFront v1.1\n','\n',char(10)),'HELP!.TXT',replace('       ___________ ___ ________\n       \__   ___  |   |\   ___/          \n         /   | /  _   |/  _/__          -*- DYNAMiX UK.HQ -*-\n       _/    |/   |   /   \/  |   \n       \_____|\___|___\_______|              /\\n                                            / \\\n      ____  /\ ________  ___  ______________\__/ _____  ___  ______\n      \   \/  \\_      \|   \|    _/    ___/____/     \|   \|    _/\n      /        \/  _/|  \         |\___   \/    \  _|_ \         |\n     /    \/    \_ \__   \        |    |   \     \  |   \        |\n   _/     ||_____/  |____/   \____|______  /_____/______/   \____|\n+­­\______|Mb/______|­­­|____|­­­­­­­­­­­\/­­­­­­­­­­­­|____|­­­­­­­+\n                                                                     \n                      -*- +44-(0)623-825-017 -*-\n                                                                       \n     -*- YoU DoN`T KNoW WHaT YoUR MiSSiNG, TiLL YoU`vE CaLLeD -*-\n\n','\n',char(10)),NULL,NULL,24767,6,0,NULL,NULL,NULL,'scan',1780048775);
INSERT INTO door_catalog VALUES('tekday14','TEKDAY14.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TEKDAY14.LHA',NULL,'XIM','Tekday by Robert Blayzor For Amiexpress','1.4','Robert',NULL,'33.6 DigITal-X Prd/NirVana Dist Site! 33.6',replace('Tekday V1.4 by Robert Blayzor For Amiexpress\n33.6 DigITal-X Prd/NirVana Dist Site! 33.6\n','\n',char(10)),'TekDay.DOC',replace('\n    TEKDAY 1.4\n    ==========\n\nAn AREXX Today In History program for AMY.\n\nQuestions?  Contact Robert Blayzor on 1:267/131.0 @ FidoNet\n                      "       "    on 40:714/1.0  @ AmigaNet\n\nand as AGAIN IT''S GIFTWARE!!!!!!\n\n\nSETUP\n=====\n\nCopy TekDay.REXX to your REXX: dir.\n\nCopy all TODAY.??? files to any directory and assign it the name TODAY:\n\n\nUSEAGE\n======\n\n    RX TekDay             (if you want it to dump to the CLI or console)\n\n    RX TekDay >filename   (if you want output dumped to a file)\n\n\nOTHER\n=====\n\nPlease see format of TODAY.DAT files.  If you wish to create your own\nBirthdays and events, please use the TODAY.OWN file.\n\nThe format is easy to follow.\n\nExample:\n\n         +- This can be a "C" to continue onto next line or can be a day\n         |  of the week # (1=SUN, 7=SAT)\n         |\n         |\nB02041970 Blah Blah Blah....\n|\/\/\ /\n| | | |\n| | | +---- Year\n| | |\n| | +------ Day\n| |\n| +-------- Month\n|\n+---------- Type, any one character:\n                 (B=Births,D=Deaths,S=Events,R=Reminders,H=Holliday)\n\n\nPlease advise to TODAY.DAT docs for more information.  Which is not\navailable in my archive.  I figured it out, lets hope you can to.\n\nOne thing, please to not modify the script.  Give credit where credit is\ndue.  Support Giftware ... it''s better than Shareware...\n\n\n-Robert\n\n12-04-92\n\n','\n',char(10)),NULL,NULL,6819,7,0,NULL,NULL,NULL,'scan',1780048775);
INSERT INTO door_catalog VALUES('tel_tp01','TEL-TP01.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TEL-TP01.LHA',NULL,'XIM','_________/\  _ __ ____ _ ____/\ ___. REAL!',NULL,'hIGH-SPEEd/rEAL!','TEL','\___.___  \\      ___/    .___\\   |______ |  /  _/___ ___)_____ ___/  \  l      \ yopl__\       \______  /_|      \______ //',replace('_________/\  _ __ ____ _ ____/\ ___. REAL!\n\___.___  \\      ___/    .___\\   |______\n    |  /  _/___ ___)_____ ___/  \  l      \\n yopl__\       \______  /_|      \______ //\n«=======\_______\=====\/==l_______\=====\/=»\n              rEAL-uPLOAD V1.0\n  tHE rEAL-uPLOAD mANAGEMENT sYSTEM fOR /X\n    The first real UPLOAD tool with 100%\n background checking, stripping, adding ...\n         ... many many features ...\n       ... a must for all Sysops! ...\n        - dONE bY hIGH-SPEEd/rEAL! -\n','\n',char(10)),'rEAL-uPLOAD.guide',replace('@database "rEAL-uPLOAD.guide"\n@Version $VER: rEAL-uPLOAD.guide V1.0 - by hIGH-SPEEd/rEAL\n@Author "hIGH-SPEEd/rEAL"\n@(c) "Copyright © 1996 Olaf Gramkow (hIGH-SPEEd/rEAL)"\n@Index "Index"\n\n@Node Main "rEAL-uPLOAD V1.0 - Dokumentation - geschrieben von hIGH-SPEEd/rEAL"\n\n@{b}                _________/\\  _ __ _____ _ ____/\\ ___.@{ub}\n@{b}                \\___.___   \\\       ___/    .___ \\   |______@{ub}\n@{b}                    |  /  _/___  ___)_____ ___/  \\  l      \\@{ub}\n@{b}                     __\\       \\ ______  /_|      \\______ //@{ub}\n@{b}           <------ -----\\_______\\-- - -\\/--l_______\\yop -\\/- -- ->@{ub}\n\n@{b}         ... bRINGz yA ...@{ub}             @{"   eINLEITUNg!   " Link "Introduction"}@{"  aRBEITSWEISE!  " Link "Working"}\n                                       @{"  rEGISTRATIOn!  " Link "Registration"}@{"     sERVEr!     " Link "Server"}\n@{b}         rEAL-uPLOAD V1.00@{ub}             @{"  aNFORDERUNGEn  " Link "Requirements"}@{"  kONFIGURATIOn  " Link "Configuration"}\n@{b} dAS rEAL-uPLOAD mANAGEMENT sYSTEM@{ub}     @{"  iNSTALLATIOn!  " Link "Installation"}@{"  cOMMING SOOn!  " Link "Comming_Soon"}\n                                       @{" tOOLz rELEASEd! " Link "Tools_Released"}@{"    gREETINGs    " Link "Greetings"}\n@{b}- gESCHRIEBEN vON hIGH-SPEEd/rEAL -@{ub}    @{"      iNDEx      " Link "Index"}@{"  jETZT cALLEn!  " Link "The_Dungeon"}\n@{b} - dESIGN vON [-sAxOn-]^jOP/rEAL -@{ub}     @{"    mEMBERs, iNFOs, bOARDs!    " Link "Members_Infos_Boards"}@{"rEA" Link "rEA"}\n\n<--- --- --- - - ----  -- - ------ --- ----  --  ---- - - -- --- - ---- - ->\n                            this tool is SHAREWARE\n                copyright ©1996 Olaf Gramkow (hIGH-SPEEd/rEAL)\n<--- --- --- - - ----  -- - ------ --- ----  --  ---- - - -- --- - ---- - ->\n@EndNode\n\n@Node "Introduction" "eINLEITUNg"\n@Toc "Main"\n\n@{b}@{u}eINLEITUNg@{ub}@{uu}\n\n                  ... hier ist der rEAL-uPLOAD von rEAL ...\n\n  Herausragende Eigenschaften:\n\n     - das erste wirkliche Upload-Programm mit 100% Prüfungen im Hintergrund\n     - ersetzt den /X-Upload komplett\n     - Dateien uploaden und dann weiter arbeiten, während im Hintergrund\n       überprüft, Dateien entfernt, Texte addiert werden usw.\n     - entfernt und fügt FileID-Zeilen und Dateien zum Archive hinzu\n     - arbeitet mit einem Pseudo-Dir, so daß kein langsammer MultiDupeChecker\n       verwendet werden muß\n     - fügt Release-Zeile hinzu und schreibt EALL-Nachrichten bei einer\n       Veröffentlichung einer Gruppe\n     - schreibt das Veröffentlichungsdatum in das DIR\n     - fügt Handle, Node, Zeit, CPS... an jeden Upload hinzu\n     - unterstützt eigenen SENT-Text\n     - arbeitet komplett mit Memory-Pools!!!\n     - arbeitet miteigenem ConfTop, WeekTop, AllTimeTop... es wird kein\n       externes Programm benötigt!!!\n     - spitzen Design\n     - keine Backdoor\n\n  fertig...\n\n  In der DEMO-Version laufen CONFTOP, WEEKTOP, ALLTIMETOP nicht und es kann\n  nur ein LOKALER Upload gemacht werden!\n@EndNode\n\n@Node "Registration" "rEGISTRATIOn"\n@Toc "Main"\n\n@{b}@{u}rEGISTRATIOn@{ub}@{uu}\n\n   Dieses Programm ist SHAREWARE. Wenn Sie es benutzen, dann müssen\n   Sie sich registrieren...\n   Die Registration kostet 50,- DM oder 40 US-$...\n   Sie müssen einfach das Geld an mich überweisen...\n\n   Kontoinhaber: Olaf Gramkow\n   Kontonummer : 10 14 19 01\n   Bankleitzahl: 240 501 10\n                 Sparkasse Lüneburg\n\n   Verwendungszweck:\n        - Registration rEAL-uPLOAD\n        - Name/Handle, Group, BBS-Name, State, Processor\n        - hole die reg. Version von welcher BBS (fLYING dRAGON, tHE dUNGEON)\n\n   Beispiel für den Verwendungszweck:\n      Registration rEAL-uPLOAD\n      hIGH-SPEEd, rEAL, tHE dUNGEON, Germany, 68030\n      hole Version von tHE dUNGEON\n\n   Nachdem Sie mir das Geld überweisen haben, können Sie sich Ihre\n   REGISTRIERTE VERSION in einer der beiden Mailbox abholen:\n      fLYING dRAGON - rEAL wHQ\n      tHE dUNGEON   - rEAL gHQ\n   Bitte teilen Sie mir mit in welcher...\n\n   aber nicht vergessen... für die Registration brauche ich die folgenden\n   Dinge: Name/Handle, Group, BBS-Name, State, Processor\n\n   Wenn Sie mir das Geld mit einem Brief schicken möchten, dann schreiben\n   Sie mir eine Nachricht in der tHE dUNGEON oder fLYING dRAGON Mailbox...\n@EndNode\n\n@Node "Requirements" "aNFORDERUNGEn"\n@Toc "Main"\n\n@{b}@{u}aNFORDERUNGEn@{ub}@{uu}\n\n                     Jeder kann das Programm starten!!!\n\n          - Sie benötigen nur einen AMIGE oder kompatiblen (DRACO)\n          - und das gute AmiExpress V4.x\n@EndNode\n\n@Node "Installation" "iNSTALLATIOn"\n@Toc "Main"\n\n@{b}@{u}iNSTALLATIOn@{ub}@{uu}\n\n                     Die Installation ist sehr einfach...\n\n  Wenn Sie den Installer benutzen, dann werden die folgenden\n  Schritte für Sie erledigt (Sie können auch alles selber machen):\n    - löschen oder umbennen der EXAMINE und FILECHECK Icons im\n      "BBS:COMMANDS/SYSCMD" Verzeichnis (Der Installer kopiert\n      die Dateien in ein OLD-Verzeichnis.)\n    - kopiere das Verzeichnis rEAL mit allen Dateien nach DOORS:\n    - kopiere das Verzeichnis COMMANDS mit allen Dateien nach BBS:\n    - kopiere das Verzeichnis LIBS mit allen Dateien nach SYS:\n    - kopiere das Verzeichnis C mit allen Dateien nach SYS:\n    - kopiere das Verzeichnis WBStartup mit allen Dateien nach SYS:\n\n  Sie müssen noch folgendes tun:\n    - WEnn Sie das PseudoDir benutzen woll, dann müssen Sie alle\n      Conf-Icons ändern. Der letzte ULPATH sollte "BBS:PseudoDir/" sein.\n      Ein Merkmal muß auf jeden Fall "ULPATH.x=BBS:PseudoDir/" sein.\n    - nun können Sie einige @{"Merkmale" Link "Configuration"} der\n      U-, RZ-, CONFTOP-, WEEKTOP- und ALLTIMETOP-Icons im Verzeichnis\n      "BBS:COMMANDS/BBSCMD" ändern.\n\n  ready...\n@EndNode\n\n@Node "Working" "aRBEITSWEISe"\n@Toc "Main"\n\n@{b}@{u}aRBEITSWEISe@{ub}@{uu}\n\n   Mit diesem Door können Sie Ihre Dateien uploaden und dann weiter arbeiten.\n   Das Door überprüft die Dateien im Hintergrund. Dateien und FileID-Zeilen\n   werden gelöscht, addiert...\n\n   Wenn Sie den rEAL-uPLOAD starten (mit U), dann wird der UploadMSG.txt\n   von der aktullen Conference angezeigt und es werden verschiedene\n   Informationen ausgegeben. Und dann können Sie auswählen, was Sie machen\n   möchten. Sie können die folgenden Dinge tun:\n\n     A = Abbruch\n     P = Privater Upload\n     G = Goodbye nach dem Transfer\n\n   oder starten Sie den normalen Upload mit RETURN.\n\n   Wenn Sie mit RZ starten, dann werden nur die Informationen angezeigt\n   und der Upload startet sofort.\n\n   Wenn Sie im LOCAL-Modus sind, dann wird ein Filerequester geöffnet und\n   Sie können die Dateien auswählen, sonst wird der normale Upload gestartet.\n   Alle Dateinamen werden überprüft, ob Sie maximal 12 Zeichen lang sind.\n   Sollten sie länger sein, dann können Sie einen neuen Dateinamen eingeben.\n   Und zu letzt werden alle Dateinamen in einer kurzen Liste angezeigt.\n   Danach können Sie wieder mit /X arbeiten. Die geuploadeten Dateien werden\n   in Hintergrund überprüft.\n\n   Das Hintergrund-Check-System arbeit wie folgt:\n     - FileID von der Datei lesen\n     - andere Infomationen von der Datei lesen (Dateigröße usw.)\n     - Zeilen aus der FileID entfernen (BBS-Werbungen)\n     - eigene FileID-Zeile ans FileID hängen\n     - neue FileID in die geuploadete Datei schreiben\n     - Dateien aus dem Archive antfernen\n     - eigene Dateien ans Archive hängen\n     - FileID und weitere Informationen ins Dir-File der aktuellen\n       Conference schreiben\n     - EAll-Nachrichten bei einem Gruppen-Release schreiben\n     - noch ein paar andere Sachen machen und dann die nächste Datei prüfen\n\n   Die Prozedur ist nicht bei allen Dateien gleich. Wenn die Datei keine\n   FileID hat, dann wird die Datei in das Remember-Verzeichnis geschrieben\n   und es kann eine Datei-Beschreibung beim nächsten Upload gemacht werden.\n\n   Der Private Upload ist total anders als die eben beschriebene Prozedur.\n   Bei einem privaten Upload werden die Dateien einfach in das Hold- bzw.\n   Privat-Upload-Verzeichnis geschrieben und die FileID wird gelesen und\n   ein paar andere kleinen Dinge werden vorgenommen. Bei einem privaten\n   Upload muß die FileID nicht mit einem "/" beginnen. Privat geuploadete\n   Dateien werden nicht im Hintergrund überprüft.\n\n   Nachdem alle Dateien geprüft wurden, werden die internen Conftop, Weektop\n   und anderen Tops geschrieben. Der NewFiles Text wird ebenfalls geschrieben.\n\n   Sie können Ihren ersten Upload in Conf 1 machen und dann in eine andere\n   Conference gehen und einen weiteren Upload machen. Es gibt keine Probleme\n   bei der Dateiprüfung, denn der rEAL-uPLOAD ist ein sehr intelligentes\n   System.\n\n   rEAL-uPLOAD unterstützt 4 weitere Funktionen:\n     - SENT\n     - CONFTOP\n     - WEEKTOP\n     - ALLTIMETOP\n\n   SENT:\n     Hier können Sie einen kurze Sent-By Text eingeben.\n\n   CONFTOP:\n     - Die ConfTop-Uploader der aktuellen Conference werden angezeigt.\n     - Wenn Sie "CONFTOP <confnummer>" eingeben, dann werden die ConfTop-\n       Uploader der angegebenen Conference angezeigt.\n     - Wenn Sie "CONFTOP ?" eingeben, wird eine kurze Kommandoliste angezeigt.\n\n   WEEKTOP:\n     - Die WeekTop-Uploader des Systems werden angezeigt.\n     - Wenn Sie "WEEKTOP D" eingeben, dann werden die WeekTop-Downloader\n       angezeigt.\n     - Wenn Sie "WEEKTOP ?" eingeben, wird eine kurze Kommandoliste angezeigt.\n\n   ALLTIMETOP:\n     - Die AllTimeTop-Uploader des Systems werden angezeigt.\n     - Wenn Sie "ALLTIMETOP D" eingeben, dann werden die AllTimeTop-Downloader\n       angezeigt.\n     - Wenn Sie "WEEKTOP ?" eingeben, wird eine kurze Kommandoliste angezeigt.\n@EndNode\n\n@Node "Server" "sERVEr"\n@Toc "Main"\n\n@{b}@{u}sERVEr@{ub}@{uu}\n\n   Der rEAL-uPLOAD besitzt einen Server. Dieser Server sollte laufen, wenn\n   Sie die Mailbox starten. Normalerweise steht der Server im SYS:WBStartup\n   Verzeichnis. Sie müssen ein Merkmal im rEAL-uPLOAD.info Icon im\n   SYS:WBStartup Verzeichnis setzen. Dieses Merkmal lautet SERVER.\n\n   Der Server schaut ins Playpen und ins Work Verzeichnis der Nodes. Wenn\n   eine Datei gefunden wird, die nicht mehr benötigt wird, dann wird die\n   Datei gelöscht. Andere Dateien werden als "NEU" markiert. Es ist nicht\n   nötig mehr darüber zu wissen, es wird nur für interne Zwecke beim\n   rEAL-uPLOAD benötigt.\n\n   Wenn Sie den Server nicht im WBStartup starten wollen, dann können Sie\n   diesen auch von der Shell aus starten. Kopieren Sie die folgende Zeile\n   in Ihre User-Startup oder Startup-Sequence:\n     DOORS:rEAL/rEAL-uPLOAD/rEAL-uPLOAD SERVER\n@EndNode\n\n@Node "Configuration" "cONFIGURATIOn"\n@Next "ADD_FILEID_LINE"\n@Toc "Main"\n\n@{b}@{u}cONFIGURATIOn@{ub}@{uu}\n\n  Sie können die Door konfigurieren. Sie können verschiedene Markmale im\n  U.info, RZ.info, CONFTOP.info, WEEKTOP.info und ALLTIMETOP.info Icon\n  in dem BBS:COMMANDS/BBSCMD Verzeichnis und im EXAMINE.info Icon in dem\n  BBS:COMMANDS/SYSCMD Verzeichnis ändern. Normalerweise sollten die\n  U.info, RZ.info und EXAMINE.info Icons die gleiche Konfiguration haben.\n\n  Merkmale:                              Benutzbar bei folgenden Icons:\n     @{" ADD_FILEID_LINE                  " Link "ADD_FILEID_LINE"}     U.info, RZ.info, EXAMINE.info\n     @{" ALLTIME_TOP_DOWNLOADER_ENTRYS    " Link "ALLTIME_TOP_DOWNLOADER_ENTRYS"}     U.info, RZ.info, EXAMINE.info\n     @{" ALLTIME_TOP_DOWNLOADER_TEXT      " Link "ALLTIME_TOP_DOWNLOADER_TEXT"}     U.info, RZ.info, EXAMINE.info, ALLTIMETOP.info\n     @{" ALLTIME_TOP_DOWNLOADER_USERNOT   " Link "ALLTIME_TOP_DOWNLOADER_USERNOT"}     U.info, RZ.info, EXAMINE.info\n     @{" ALLTIME_TOP_UPLOADER_ENTRYS      " Link "ALLTIME_TOP_UPLOADER_ENTRYS"}     U.info, RZ.info, EXAMINE.info\n     @{" ALLTIME_TOP_UPLOADER_TEXT        " Link "ALLTIME_TOP_UPLOADER_TEXT"}     U.info, RZ.info, EXAMINE.info, ALLTIMETOP.info\n     @{" ALLTIME_TOP_UPLOADER_USERNOT     " Link "ALLTIME_TOP_UPLOADER_USERNOT"}     U.info, RZ.info, EXAMINE.info\n     @{" CHECKTASK_PRIORITY               " Link "CHECKTASK_PRIORITY"}     U.info, RZ.info, EXAMINE.info\n     @{" CONF_TOP_UPLOADER_ENTRYS         " Link "CONF_TOP_UPLOADER_ENTRYS"}     U.info, RZ.info, EXAMINE.info\n     @{" CONF_TOP_UPLOADER_TEXT           " Link "CONF_TOP_UPLOADER_TEXT"}     U.info, RZ.info, EXAMINE.info, CONFTOP.info\n     @{" CONF_TOP_UPLOADER_TIME           " Link "CONF_TOP_UPLOADER_TIME"}     U.info, RZ.info, EXAMINE.info\n     @{" CONF_TOP_UPLOADER_USERNOT        " Link "CONF_TOP_UPLOADER_USERNOT"}     U.info, RZ.info, EXAMINE.info\n     @{" CPS_UPLOAD_LINE                  " Link "CPS_UPLOAD_LINE"}     U.info, RZ.info, EXAMINE.info\n     @{" DELETE_???                       " Link "DELETE_???"}     U.info, RZ.info, EXAMINE.info\n     @{" DEPACK_???                       " Link "DEPACK_???"}     U.info, RZ.info, EXAMINE.info\n     @{" DEPACK_ALL_???                   " Link "DEPACK_ALL_???"}     U.info, RZ.info, EXAMINE.info\n     @{" DISPLAY_BEEP_AFTER_FILE          " Link "DISPLAY_BEEP_AFTER_FILE"}     U.info, RZ.info, EXAMINE.info\n     @{" FILE_ADD                         " Link "FILE_ADD"}     U.info, RZ.info, EXAMINE.info\n     @{" FILEID_LINES_MAX                 " Link "FILEID_LINES_MAX"}     U.info, RZ.info, EXAMINE.info\n     @{" FREE_RESUMING                    " Link "FREE_RESUMING"}     U.info, RZ.info, EXAMINE.info\n     @{" GROUP_ADDLINE                    " Link "GROUP_ADDLINE"}     U.info, RZ.info, EXAMINE.info\n     @{" GROUP_STRING                     " Link "GROUP_STRING"}     U.info, RZ.info, EXAMINE.info\n     @{" LOCAL_UPLOAD_DIR                 " Link "LOCAL_UPLOAD_DIR"}     U.info, RZ.info, EXAMINE.info\n     @{" LOCAL_UPLOAD_PASSWORD            " Link "LOCAL_UPLOAD_PASSWORD"}     U.info, RZ.info, EXAMINE.info\n     @{" MAKE_GROUP_RELEASE_FREE_DOWNLOAD " Link "MAKE_GROUP_RELEASE_FREE_DOWNLOAD"}     U.info, RZ.info, EXAMINE.info\n     @{" NEWFILE_UPLOADED_TEXT            " Link "NEWFILE_UPLOADED_TEXT"}     U.info, RZ.info, EXAMINE.info\n     @{" PACK_???                         " Link "PACK_???"}     U.info, RZ.info, EXAMINE.info\n     @{" PACK_ALL_???                     " Link "PACK_ALL_???"}     U.info, RZ.info, EXAMINE.info\n     @{" PRIVATE_UPLOAD_DIR               " Link "PRIVATE_UPLOAD_DIR"}     U.info, RZ.info, EXAMINE.info\n     @{" PRIVATE_UPLOAD_MESSAGE_TO        " Link "PRIVATE_UPLOAD_MESSAGE_TO"}     U.info, RZ.info, EXAMINE.info\n     @{" PSEUDO_DIR                       " Link "PSEUDO_DIR"}     U.info, RZ.info, EXAMINE.info\n     @{" RELEASE_DATE                     " Link "RELEASE_DATE"}     U.info, RZ.info, EXAMINE.info\n     @{" REMEMBER_DIR                     " Link "REMEMBER_DIR"}     U.info, RZ.info, EXAMINE.info\n     @{" STRIP_FILEID_LINES               " Link "STRIP_FILEID_LINES"}     U.info, RZ.info, EXAMINE.info\n     @{" STRIP_FILES                      " Link "STRIP_FILES"}     U.info, RZ.info, EXAMINE.info\n     @{" USE_LOCAL_FOR_NODE               " Link "USE_LOCAL_FOR_NODE"}     U.info, RZ.info, EXAMINE.info\n     @{" WEEK_TOP_DOWNLOADER_TEXT         " Link "WEEK_TOP_DOWNLOADER_TEXT"}     WEEKTOP.info\n     @{" WEEK_TOP_UPLOADER_ENTRYS         " Link "WEEK_TOP_UPLOADER_ENTRYS"}     U.info, RZ.info, EXAMINE.info\n     @{" WEEK_TOP_UPLOADER_TEXT           " Link "WEEK_TOP_UPLOADER_TEXT"}     U.info, RZ.info, EXAMINE.info, WEEKTOP.info\n     @{" WEEK_TOP_UPLOADER_TIME           " Link "WEEK_TOP_UPLOADER_TIME"}     U.info, RZ.info, EXAMINE.info\n     @{" WEEK_TOP_UPLOADER_USERNOT        " Link "WEEK_TOP_UPLOADER_USERNOT"}     U.info, RZ.info, EXAMINE.info\n     @{" WRITE_EALL_ON_GROUP_RELEASE      " Link "WRITE_EALL_ON_GROUP_RELEASE"}     U.info, RZ.info, EXAMINE.info\n     @{" WRITE_LOCAL_ON_LOCAL_MODE        " Link "WRITE_LOCAL_ON_LOCAL_MODE"}     U.info, RZ.info, EXAMINE.info\n     @{" WRITE_MESSAGE_ON_PRIVATE_UPLOAD  " Link "WRITE_MESSAGE_ON_PRIVATE_UPLOAD"}     U.info, RZ.info, EXAMINE.info\n@EndNode\n\n@Node "ADD_FILEID_LINE" "Mekrmal: ADD_FILEID_LINE"\n@Next "ALLTIME_TOP_DOWNLOADER_ENTRYS"\n@Prev "Configuration"\n@Toc "Configuration"\n\n  @{b}@{u}ADD_FILEID_LINE@{ub}@{uu}\n\n     Pattern : ADD_FILEID_LINE=<String>\n               ADD_FILEID_LINE.<num>=<String>\n               ADD_FILEID_LINE-<num>=<String>\n               ADD_FILEID_LINE-<num>.<num>=<String>\n     Funktion: Diese Zeile wird an das FILE_ID.DIZ angehängt.\n               Der String sollte maximal 44 Zeichen lang sein.\n               Wenn Sie eine Nodenummer hinter das ADD_FILEID_LINE schreiben,\n               dann wird diese FileID-Zeile nur bei der angegebenen Node\n               verwendet. ADD_FILEID_LINE ohne eine Nodenummer schreibt die\n               Zeile bei allen Nodes. ADD_FILEID_LINE-<node> hat eine\n               höhere Priorität als ADD_FILEID_LINE.\n               Wenn Sie das mehrfache FileID-Line-Add verwenden, dann nimmt\n               der rEAL-uPLOAD einen von den Strings (Zufall).\n               Sie können die aktuelle Zeit, das aktuelle Datum, die aktuelle\n               Node, Confnummer, Stunde, Minute und Sekunde in die FileID-Zeile\n               schreiben.\n               "%T" wird ersetzt durch die aktuelle Zeit    -> 00:00:00\n               "%D" wird ersetzt durch das aktuelle Datum   -> 00-00-00\n               "%N" wird ersetzt durch die aktuelle Node    - > 00\n               "%C" wird ersetzt durch die aktuelle Conf    -> 00\n               "%H" wird ersetzt durch die aktuelle Stunde  -> 00\n               "%M" wird ersetzt durch die aktuelle Minute  -> 00\n               "%S" wird ersetzt durch die aktuelle Sekunde -> 00\n     Beispiel: a) ADD_FILEID_LINE=- -[ tHE dUNGEON ]- -  -  - -[ rEAL gHQ ]- -\n                  Der String "- -[ tHE dUNGEON ]- -  -  - -[ rEAL gHQ ]- -"\n                  wird an die FILE_ID.DIZ gehängt.\n               b) ADD_FILEID_LINE.1=erster String\n                  ADD_FILEID_LINE.2=zweiter String\n                  ADD_FILEID_LINE.3=dritter String\n                  Einer von den Strings (Zufall) wird an die FILE_ID.DIZ\n                  gehängt.\n               c) ADD_FILEID_LINE-1=[%T] erste node!!! [%D]\n                  Ein String wie "[22:23:32] erste node!!! [01-04-96]" wird an\n                  die FILE_ID.DIZ gehängt, wenn der User seinen Upload auf\n                  Node 1 macht.\n               d) ADD_FILEID_LINE-1.1=erster String auf Node 1\n                  ADD_FILEID_LINE-1.2=zweiter String auf Node 1\n                  ADD_FILEID_LINE-1.3=dritter String auf Node 1\n                  Einer der Strings (Zufall) wird an die FILE_ID.DIZ gehängt,\n                  wenn der User seinen Upload auf Node 1 macht.\n@EndNode\n\n@Node "ALLTIME_TOP_DOWNLOADER_ENTRYS" "Merkmal: ALLTIME_TOP_DOWNLOADER_ENTRYS"\n@Next "ALLTIME_TOP_DOWNLOADER_TEXT"\n@Prev "ADD_FILEID_LINE"\n@Toc "Configuration"\n\n  @{b}@{u}ALLTIME_TOP_DOWNLOADER_ENTRYS@{ub}@{uu}\n\n     Pattern : ALLTIME_TOP_DOWNLOADER_ENTRYS=<Einträge>\n     Funktion: Hier werden die Einträge für den All-Time-Top-Downloader\n               festgelegt. Wenn die Einträge=-1 sind, dann gibt es kein\n               Limit (alle User).\n               Grundeinstellung=10\n     Beispiel: ALLTIME_TOP_DOWNLOADER_ENTRYS=15\n               Es werden 15 Einträge zum All-Time-Top-Downloader geschrieben.\n@EndNode\n\n@Node "ALLTIME_TOP_DOWNLOADER_TEXT" "Merkmal: ALLTIME_TOP_DOWNLOADER_TEXT"\n@Next "ALLTIME_TOP_DOWNLOADER_USERNOT"\n@Prev "ALLTIME_TOP_DOWNLOADER_ENTRYS"\n@Toc "Configuration"\n\n  @{b}@{u}ALLTIME_TOP_DOWNLOADER_TEXT@{ub}@{uu}\n\n     Pattern : ALLTIME_TOP_DOWNLOADER_TEXT=<Dateiname>\n     Funktion: Hier können Sie die Textdatei für den All-Time-Top-Downloader\n               angeben.\n               Wenn keine Datei angegeben wird, dann wird keine Datei ge-\n               schrieben.\n               Sie können den Text beim LOGIN, in einem BULL oder sonst wo\n               anzeigen.\n               Die All-Time-Top-Downloader können ebenfalls mit dem\n               ALLTIMETOP Befehl angezeigt werden.\n     Beispiel: ALLTIME_TOP_DOWNLOADER_TEXT=DOORS:rEAL/rEAL-uPLOAD/AllTimeTopDown.txt\n               Die All-Time-Top-Downloader werden in die Datei\n               "DOORS:rEAL/rEAL-uPLOAD/AllTimeTopDown.txt" geschrieben.\n@EndNode\n\n@Node "ALLTIME_TOP_DOWNLOADER_USERNOT" "Merkmal: ALLTIME_TOP_DOWNLOADER_USERNOT"\n@Next "ALLTIME_TOP_UPLOADER_ENTRYS"\n@Prev "ALLTIME_TOP_DOWNLOADER_TEXT"\n@Toc "Configuration"\n\n  @{b}@{u}ALLTIME_TOP_DOWNLOADER_USERNOT@{ub}@{uu}\n\n     Pattern : ALLTIME_TOP_DOWNLOADER_USERNOT.<num>=<Name>\n     Funktion: Mit diesem Merkmal können Sie User angeben, die nicht\n               in den All-Time-Top-Downloadern erscheinen sollen.\n     Beispiel: ALLTIME_TOP_DOWNLOADER_USERNOT.1=hIGH-SPEEd\n               Der User "hIGH-SPEEd" wird nicht bei den All-Time-Top-\n               Downloadern benutzt.\n@EndNode\n\n@Node "ALLTIME_TOP_UPLOADER_ENTRYS" "Merkmal: ALLTIME_TOP_UPLOADER_ENTRYS"\n@Next "ALLTIME_TOP_UPLOADER_TEXT"\n@Prev "ALLTIME_TOP_DOWNLOADER_USERNOT"\n@Toc "Configuration"\n\n  @{b}@{u}ALLTIME_TOP_UPLOADER_ENTRYS@{ub}@{uu}\n\n     Pattern : ALLTIME_TOP_UPLOADER_ENTRYS=<Einträge>\n     Funktion: Hier werden die Einträge für den All-Time-Top-Uploader\n               festgelegt. Wenn die Einträge=-1 sind, dann gibt es kein\n               Limit (alle User).\n               Grundeinstellung=10\n     Beispiel: ALLTIME_TOP_UPLOADER_ENTRYS=15\n               Es werden 15 Einträge zum All-Time-Top-Uploader geschrieben.\n@EndNode\n\n@Node "ALLTIME_TOP_UPLOADER_TEXT" "Merkmal: ALLTIME_TOP_UPLOADER_TEXT"\n@Next "ALLTIME_TOP_UPLOADER_USERNOT"\n@Prev "ALLTIME_TOP_UPLOADER_ENTRYS"\n@Toc "Configuration"\n\n  @{b}@{u}ALLTIME_TOP_UPLOADER_TEXT@{ub}@{uu}\n\n     Pattern : ALLTIME_TOP_UPLOADER_TEXT=<Dateiname>\n     Funktion: Hier können Sie die Textdatei für den All-Time-Top-Uploader\n               angeben.\n               Wenn keine Datei angegeben wird, dann wird keine Datei ge-\n               schrieben.\n               Sie können den Text beim LOGIN, in einem BULL oder sonst wo\n               anzeigen.\n               Die All-Time-Top-Uploader können ebenfalls mit dem\n               ALLTIMETOP Befehl angezeigt werden.\n     Beispiel: ALLTIME_TOP_UPLOADER_TEXT=DOORS:rEAL/rEAL-uPLOAD/AllTimeTopUp.txt\n               Die All-Time-Top-Uploader werden in die Datei\n               "DOORS:rEAL/rEAL-uPLOAD/AllTimeTopUp.txt" geschrieben.\n@EndNode\n\n@Node "ALLTIME_TOP_UPLOADER_USERNOT" "Merkmal: ALLTIME_TOP_UPLOADER_USERNOT"\n@Next "CHECKTASK_PRIORITY"\n@Prev "ALLTIME_TOP_UPLOADER_TEXT"\n@Toc "Configuration"\n\n  @{b}@{u}ALLTIME_TOP_UPLOADER_USERNOT@{ub}@{uu}\n\n     Pattern : ALLTIME_TOP_UPLOADER_USERNOT.<num>=<Name>\n     Funktion: Mit diesem Merkmal können Sie User angeben, die nicht\n               in den All-Time-Top-Uploadern erscheinen sollen.\n     Beispiel: ALLTIME_TOP_UPLOADER_USERNOT.1=hIGH-SPEEd\n               Der User "hIGH-SPEEd" wird nicht bei den All-Time-Top-\n               Uploadern benutzt.\n@EndNode\n\n@Node "CHECKTASK_PRIORITY" "Merkmal: CHECKTASK_PRIORITY"\n@Next "CONF_TOP_UPLOADER_ENTRYS"\n@Prev "ALLTIME_TOP_UPLOADER_USERNOT"\n@Toc "Configuration"\n\n  @{b}@{u}CHECKTASK_PRIORITY@{ub}@{uu}\n\n     Pattern : CHECKTASK_PRIORITY=<Priorität>\n     Funktion: Hier können Sie die Priorität des Check-Tasks setzen.\n               Grundeinstellung=0\n     Beispiel: CHECKTASK_PRIORITY=5\n               Setzt die Check-Task-Priorität auf 5.\n@EndNode\n\n@Node "CONF_TOP_UPLOADER_ENTRYS" "Merkmal: CONF_TOP_UPLOADER_ENTRYS"\n@Next "CONF_TOP_UPLOADER_TEXT"\n@Prev "CHECKTASK_PRIORITY"\n@Toc "Configuration"\n\n  @{b}@{u}CONF_TOP_UPLOADER_ENTRYS@{ub}@{uu}\n\n     Pattern : CONF_TOP_UPLOADER_ENTRYS.<Conf>=<Einträge>\n     Funktion: Hier werden die Einträge für die Conf-Top-Uploader festgelegt.\n               Grundeinstellung=10\n     Beispiel: CONF_TOP_UPLOADER_ENTRYS.1=15\n               Schreibe 15 Einträge in den ConfTop-Uploader für Conference 1.\n@EndNode\n\n@Node "CONF_TOP_UPLOADER_TEXT" "Merkmal: CONF_TOP_UPLOADER_TEXT"\n@Next "CONF_TOP_UPLOADER_TIME"\n@Prev "CONF_TOP_UPLOADER_ENTRYS"\n@Toc "Configuration"\n\n  @{b}@{u}CONF_TOP_UPLOADER_TEXT@{ub}@{uu}\n\n     Pattern : CONF_TOP_UPLOADER_TEXT.<Conf>=<Dateiname>\n     Funktion: Hier können Sie die Textdatei für den ConfTop-Uploader\n               angeben.\n               Wenn keine Datei angegeben wird, dann wird keine Datei ge-\n               schrieben.\n               Sie können den Text beim LOGIN, in einem BULL oder sonst wo\n               anzeigen.\n               Die ConfTop-Uploader können ebenfalls mit dem CONFTOP Befehl\n               angezeigt werden.\n     Beispiel: CONF_TOP_UPLOADER_TEXT.1=DOORS:rEAL/rEAL-uPLOAD/ConfTopUp_1.txt\n               Die Conftop-Uploader der Conference 1 werden in die Datei\n               "DOORS:rEAL/rEAL-uPLOAD/ConfTopUp_1.txt" geschrieben.\n@EndNode\n\n@Node "CONF_TOP_UPLOADER_TIME" "Merkmal: CONF_TOP_UPLOADER_TIME"\n@Next "CONF_TOP_UPLOADER_USERNOT"\n@Prev "CONF_TOP_UPLOADER_TEXT"\n@Toc "Configuration"\n\n  @{b}@{u}CONF_TOP_UPLOADER_TIME@{ub}@{uu}\n\n     Pattern : CONF_TOP_UPLOADER_TIME.<Conf>=<Tage>\n     Funktion: Mit diesem Merkmal können Sie festlegen nach wievielen\n               Tagen der ConfTop-Uploader geschrieben wird.\n               Grundeinstellung=14\n     Beispiel: CONF_TOP_UPLOADER_TIME.1=7\n               Der ConfTop-Uploader für Conference 1 wird jede Woche\n               geschrieben.\n@EndNode\n\n@Node "CONF_TOP_UPLOADER_USERNOT" "Merkmal: CONF_TOP_UPLOADER_USERNOT"\n@Next "CPS_UPLOAD_LINE"\n@Prev "CONF_TOP_UPLOADER_TIME"\n@Toc "Configuration"\n\n  @{b}@{u}CONF_TOP_UPLOADER_USERNOT@{ub}@{uu}\n\n     Pattern : CONF_TOP_UPLOADER_USERNOT.<num>=<Name>\n     Funktion: Mit diesem Merkmal können Sie User festlegen, die\n               nicht im ConfTop-Uploader erscheinen sollen.\n     Beispiel: CONF_TOP_UPLOADER_USERNOT.1=hIGH-SPEEd\n               Der User "hIGH-SPEEd" wird nicht für den ConfTop-Uploader\n               verwendet.\n@EndNode\n\n@Node "CPS_UPLOAD_LINE" "Merkmal: CPS_UPLOAD_LINE"\n@Next "DELETE_???"\n@Prev "CONF_TOP_UPLOADER_USERNOT"\n@Toc "Configuration"\n\n  @{b}@{u}CPS_UPLOAD_LINE@{ub}@{uu}\n\n     Pattern : CPS_UPLOAD_LINE\n     Funktion: Wenn dieses Mekrmal gesetzt ist, dann wird die CPS-Upload-Zeile\n               geschrieben.\n     Beispiel: CPS_UPLOAD_LINE\n               Die CPS-Upload-Zeile wird geschrieben.\n@EndNode\n\n@Node "DELETE_???" "Merkmal: DELETE_???"\n@Next "DEPACK_???"\n@Prev "CPS_UPLOAD_LINE"\n@Toc "Configuration"\n\n  @{b}@{u}DELETE_???@{ub}@{uu}\n\n     Pattern : DELETE_<Datei-Extension>=<Funktionsaufruf>\n     Funktion: Dies ist der Funktionsaufruf für den DELETE-Process vom\n               FILE_ID.DIZ eines Archives, Textes, Modules...\n               Die Datei-Extension ist LHA, LZX, TXT oder ähnliches.\n               "%P" wird durch den Archiv-Namen ersetzt.\n     Beispiel: DELETE_LHA=LHA -m d %P file_id.diz\n               Nutze den Funktionsaufruf "LHA -m d %P file_id.diz" für den\n               Delete-Prozess beim LHA-Archiv.\n@EndNode\n\n@Node "DEPACK_???" "Merkmal: DEPACK_???"\n@Next "DEPACK_ALL_???"\n@Prev "DELETE_???"\n@Toc "Configuration"\n\n  @{b}@{u}DEPACK_???@{ub}@{uu}\n\n     Pattern : DEPACK_<Datei-Extension>=<Funktionsaufruf>\n     Funktion: Dies ist der Funktionsaufruf für den DEPACK-Prozess vom\n               FILE_ID.DIZ beim Archiv, Text, Module...\n               Die Datei-Extension ist LHA, LZX, TXT oder ähnliches.\n               "%P" wird durch den Archiv-Namen ersetzt.\n               "%W" wird durch das Zielverzeichnis ersetzt.\n     Beispiel: DEPACK_LHA=LHA e %P file_id.diz %W\n               Benutzt den Funktionsaufruf "LHA e %P file_id.diz %W" für\n               den DEPACK-Prozess beim LHA-Archiv.\n@EndNode\n\n@Node "DEPACK_ALL_???" "Merkmal: DEPACK_ALL_???"\n@Next "DISPLAY_BEEP_AFTER_FILE"\n@Prev "DEPACK_???"\n@Toc "Configuration"\n\n  @{b}@{u}DEPACK_ALL_???@{ub}@{uu}\n\n     Pattern : DEPACK_ALL_<Datei-Extension>=<Funktionsaufruf>\n     Funktion: Dies ist der Funktionsaufruf für den DEPACK-Prozess beim\n               FileStrip-Prozess. Diese Funktion ist ausschließlich für\n               Archive. Die Datei-Extension ist LHA, LZX, TXT oder ähnliches.\n               "%P" wird durch den Archiv-Namen ersetzt.\n               "%W" wird durch das Zielverzeichnis ersetzt.\n     Beispiel: DEPACK_ALL_LHA=LHA x %P %W\n               Benutze den Funktionsaufruf "LHA x %P %W" für den DEPACK-\n               Prozess beim FileStrip-Prozess beim LHA-Archiv.\n@EndNode\n\n@Node "DISPLAY_BEEP_AFTER_FILE" "Merkmal: DISPLAY_BEEP_AFTER_FILE"\n@Next "FILE_ADD"\n@Prev "DEPACK_ALL_???"\n@Toc "Configuration"\n\n  @{b}@{u}DISPLAY_BEEP_AFTER_FILE@{ub}@{uu}\n\n     Pattern : DISPLAY_BEEP_AFTER_FILE\n     Funktion: Wenn dieses Merkmal gesetzt ist, wird nach jeder\n               geuploadeten (und überprüften) Datei ein DisplayBeep\n               ausgeführt.\n     Beispiel: DISPLAY_BEEP_AFTER_FILE\n               DisplayBeep ist eingeschaltet.\n@EndNode\n\n@Node "FILE_ADD" "Merkmal: FILE_ADD"\n@Next "FILEID_LINES_MAX"\n@Prev "DISPLAY_BEEP_AFTER_FILE"\n@Toc "Configuration"\n\n  @{b}@{u}FILE_ADD@{ub}@{uu}\n\n     Pattern : FILE_ADD.<num>=<Dateiname>\n     Funktion: Die Dateien, die hier aufgeführt sind, werden zu einem\n               LHA, LZH, LZX oder ZIP Archiv addiert.\n     Beispiel: FILE_ADD.1=BBS:BoxText.txt\n               Die Datei "BBS:BoxText.txt" wird hinzugefügt.\n@EndNode\n\n@Node "FILEID_LINES_MAX" "Merkmal: FILEID_LINES_MAX"\n@Next "FREE_RESUMING"\n@Prev "FILE_ADD"\n@Toc "Configuration"\n\n  @{b}@{u}FILE_ADD@{ub}@{uu}\n\n     Pattern : FILEID_LINES_MAX=<Zeilen>\n     Funktion: Hier können Sie angeben wieviel Zeilen maximal von einer\n               FILE_ID.DIZ ins DIR-File geschrieben werden.\n     Beispiel: FILEID_LINES_MAX=12\n               Es werden maximal 12 Zeilen der FILE_ID.DIZ ins DIR-File\n               geschrieben.\n@EndNode\n\n@Node "FREE_RESUMING" "Merkmal: FREE_RESUMING"\n@Next "GROUP_ADD_LINE"\n@Prev "FILEID_LINES_MAX"\n@Toc "Configuration"\n\n  @{b}@{u}FREE_RESUMING@{ub}@{uu}\n\n     Pattern : FREE_RESUMING\n     Funktion: Wenn dieses Merkmal gesetzt ist, dann kann jeder User Dateien,\n               die im Remember-Verzeichnis stehen beschreiben.\n     Beispiel: FREE_RESUMING\n               Free-Resuming ist eingeschaltet.\n@EndNode\n\n@Node "GROUP_ADD_LINE" "Merkmal: GROUP_ADD_LINE"\n@Next "GROUP_STRING"\n@Prev "FREE_RESUMING"\n@Toc "Configuration"\n\n  @{b}@{u}GROUP_ADD_LINE@{ub}@{uu}\n\n     Pattern : GROUP_ADD_LINE.<num>=<String>\n     Funktion: Wenn eine Gruppe gefunden wurde (GROUP_STRING) dann wird\n               die Zeile der Gruppe ins DIR-File geschrieben.\n               Der String darf maximal 44 Zeichen lang sein.\n     Beispiel: GROUP_ADDLINE.1=  gET tHIS gREAT nEW rEAL! rELEASE nOW!!!!  \n               Der String "  gET tHIS gREAT nEW rEAL! rELEASE nOW!!!!  "\n               wird addiert.\n@EndNode\n\n@Node "GROUP_STRING" "Merkmal: GROUP_STRING"\n@Next "LOCAL_UPLOAD_DIR"\n@Prev "GROUP_ADD_LINE"\n@Toc "Configuration"\n\n  @{b}@{u}GROUP_STRING@{ub}@{uu}\n\n     Pattern : GROUP_STRING.<num>=<String>\n     Funktion: Dies ist ein Pattern. rEAL-uPLOAD durchsucht die geuploadeten\n               Dateien und wenn der Anfang des Dateinamens dieser String ist,\n               dann ist es ein Gruppen-Release. Die Groß- und Kleinschreibung\n               ist bei dieser Funktion egal.\n     Beispiel: GROUP_STRING.1=rea-\n               Wenn der Dateiname mit "rea-" beginnt, dann ist es ein rEAL!\n               Release.\n@EndNode\n\n@Node "LOCAL_UPLOAD_DIR" "Merkmal: LOCAL_UPLOAD_DIR"\n@Next "LOCAL_UPLOAD_PASSWORD"\n@Prev "GROUP_STRING"\n@Toc "Configuration"\n\n  @{b}@{u}LOCAL_UPLOAD_DIR@{ub}@{uu}\n\n     Pattern : LOCAL_UPLOAD_DIR=<Verzeichnis>\n     Funktion: Dieses Verzeichnis wird als Default-Verzeichnis bei einem\n               LOCAL-Upload verwendet, wenn ein User online ist.\n     Beispiel: LOCAL_UPLOAD_DIR=BBS:\n               Das Verzeichnis "BBS:" wird als Default benutzt.\n@EndNode\n\n@Node "LOCAL_UPLOAD_PASSWORD" "Merkmal: LOCAL_UPLOAD_PASSWORD"\n@Next "MAKE_GROUP_RELEASE_FREE_DOWNLOAD"\n@Prev "LOCAL_UPLOAD_DIR"\n@Toc "Configuration"\n\n  @{b}@{u}LOCAL_UPLOAD_PASSWORD@{ub}@{uu}\n\n     Pattern : LOCAL_UPLOAD_PASSWORD=<Passwort>\n     Funktion: Dies ist das Passwort, das benötigt wird, wenn Sie einen\n               LOCAL-Upload machen wollen, wenn ein User online ist.\n               Die Groß- und Kleinschreibung wird bei dieser Funktion\n               beachtet.\n     Beispiel: LOCAL_UPLOAD_PASSWORD=SUXX\n               Das Passwort "SUXX" muß eingegeben werden, wenn Sie einen\n               LOCAL-Upload machen wollen, wenn ein User online ist.\n@EndNode\n\n@Node "MAKE_GROUP_RELEASE_FREE_DOWNLOAD" "Merkmal: MAKE_GROUP_RELEASE_FREE_DOWNLOAD"\n@Next "NEWFILE_UPLOADED_TEXT"\n@Prev "LOCAL_UPLOAD_PASSWORD"\n@Toc "Configuration"\n\n  @{b}@{u}MAKE_GROUP_RELEASE_FREE_DOWNLOAD@{ub}@{uu}\n\n     Pattern : MAKE_GROUP_RELEASE_FREE_DOWNLOAD\n     Funktion: Wenn dieses Merkmal gesetzt ist, wird ein Gruppen-Release\n               FREE DOWNLOAD geschaltet.\n     Beispiel: MAKE_GROUP_RELEASE_FREE_DOWNLOAD\n               Gruppen-Releases werden auf FREE DOWNLOAD geschaltet.\n@EndNode\n\n@Node "NEWFILE_UPLOADED_TEXT" "Merkmal: NEWFILE_UPLOADED_TEXT"\n@Next "PACK_???"\n@Prev "MAKE_GROUP_RELEASE_FREE_DOWNLOAD"\n@Toc "Configuration"\n\n  @{b}@{u}NEWFILE_UPLOADED_TEXT@{ub}@{uu}\n\n     Pattern : NEWFILE_UPLOADED_TEXT=<Dateiname>\n     Funktion: Die neuen Dateien von heute werden in diese Datei geschrieben.\n               Sie können es beim LOGIN, BULL oder sonstwo anzeigen.\n               Wenn keine Datei angegeben wird, wird keine Datei geschrieben.\n     Beispiel: NEWFILE_UPLOADED_TEXT=DOORS:rEAL/rEAL-uPLOAD/NewFiles.txt\n               Die neuen Datein werden in die folgende Datei geschrieben:\n               "rEAL/rEAL-uPLOAD/NewFiles.txt".\n@EndNode\n\n@Node "PACK_???" "Merkmal: PACK_???"\n@Next "PACK_ALL_???"\n@Prev "NEWFILE_UPLOADED_TEXT"\n@Toc "Configuration"\n\n  @{b}@{u}PACK_???@{ub}@{uu}\n\n     Pattern : PACK_<Datei-Extension>=<Funktionsaufruf>\n     Funktion: Dies ist der Funktionsaufruf für den DEPACK-Prozess vom\n               FILE_ID.DIZ beim Archiv, Text, Module...\n               Die Datei-Extension ist LHA, LZX, TXT oder ähnliches.\n               "%P" wird durch den Archiv-Namen ersetzt.\n               "%W" wird durch das Zielverzeichnis ersetzt.\n     Beispiel: PACK_LHA=LHA a %P %Wfile_id.diz\n               Benutzt den Funktionsaufruf "LHA a %P %Wfile_id.diz" für\n               den PACK-Prozess beim LHA-Archiv.\n@EndNode\n\n@Node "PACK_ALL_???" "Merkmal: PACK_ALL_???"\n@Next "PRIVATE_UPLOAD_DIR"\n@Prev "PACK_???"\n@Toc "Configuration"\n\n  @{b}@{u}PACK_ALL_???@{ub}@{uu}\n\n     Pattern : PACK_ALL_<Datei-Extension>=<Funktionsaufruf>\n     Funktion: Dies ist der Funktionsaufruf für den PACK-Prozess beim\n               FileStrip-Prozess. Diese Funktion ist ausschließlich für\n               Archive. Die Datei-Extension ist LHA, LZX, TXT oder ähnliches.\n               "%A" wird durch ein Pseudo-Assign ersetzt\n               "%P" wird durch den Archiv-Namen ersetzt.\n               "%W" wird durch das Zielverzeichnis ersetzt.\n     Beispiel: PACK_ALL_LHA=LHA a %P #?\n               Benutze den Funktionsaufruf "LHA a %P #?" für den PACK-\n               Prozess beim FileStrip-Prozess beim LHA-Archiv.\n@EndNode\n\n@Node "PRIVATE_UPLOAD_DIR" "Merkmal: PRIVATE_UPLOAD_DIR"\n@Next "PRIVATE_UPLOAD_MESSAGE_TO"\n@Prev "PACK_ALL_???"\n@Toc "Configuration"\n\n  @{b}@{u}PRIVATE_UPLOAD_DIR@{ub}@{uu}\n\n     Pattern : PRIVATE_UPLOAD_DIR=<Verzeichnis>\n     Funktion: Wenn dieses Merkmal gesetzt ist, dann werden die privaten\n               Uploads in dieses Verzeichnis geschrieben, sonst werden die\n               Dateien in das HOLD Verzeichnis der aktuellen Conference\n               geschrieben. Der Verzeichnisname muß mit ":" oder "/" enden.\n     Beispiel: PRIVATE_UPLOAD_DIR=BBS:Private/\n               Die privaten Uploads werden in das Verzeichnis "BBS:Private/"\n               geschrieben.\n@EndNode\n\n@Node "PRIVATE_UPLOAD_MESSAGE_TO" "Merkmal: PRIVATE_UPLOAD_MESSAGE_TO"\n@Next "PSEUDO_DIR"\n@Prev "PRIVATE_UPLOAD_DIR"\n@Toc "Configuration"\n\n  @{b}@{u}PRIVATE_UPLOAD_MESSAGE_TO@{ub}@{uu}\n\n     Pattern : PRIVATE_UPLOAD_MESSAGE_TO=<Dateiname\n     Funktion: Hier können Sie einen User angeben, der eine Nachricht\n               erhält, wenn ein privater Upload gemacht wurde. Das\n               Merkmal WRITE_MESSAGE_ON_PRIVATE_UPLOAD muß gesetzt sein.\n     Beispiel: PRIVATE_UPLOAD_MESSAGE_TO=hIGH-SPEEd\n               Der User "hIGH-SPEEd" bekommt die Nachrichten.\n@EndNode\n\n@Node "PSEUDO_DIR" "Merkmal: PSEUDO_DIR"\n@Next "RELEASE_DATE"\n@Prev "PRIVATE_UPLOAD_MESSAGE_TO"\n@Toc "Configuration"\n\n  @{b}@{u}PSEUDO_DIR@{ub}@{uu}\n\n     Pattern : PSEUDO_DIR\n     Funktion: Wenn dieses Merkmal gesetzt ist, dann werden die\n               geuploadeten Dateien zum Pseudo-Dir addiert.\n     Beispiel: PSEUDO_DIR\n               Pseudo-Dir wird benutzt.\n@EndNode\n\n@Node "RELEASE_DATE" "Merkmal: RELEASE_DATE"\n@Next "REMEMBER_DIR"\n@Prev "PSEUDO_DIR"\n@Toc "Configuration"\n\n  @{b}@{u}RELEASE_DATE@{ub}@{uu}\n\n     Pattern : RELEASE_DATE\n     Funktion: Wenn dieses Markmal gesetzt ist, dann wird das Release-Datum\n               angezeigt.\n     Beispiel: RELEASE_DATE\n               Release-Datum wird angezeigt.\n@EndNode\n\n@Node "REMEMBER_DIR" "Merkmal: REMEMBER_DIR"\n@Next "STRIP_FILEID_LINES"\n@Prev "RELEASE_DATE"\n@Toc "Configuration"\n\n  @{b}@{u}REMEMBER_DIR@{ub}@{uu}\n\n     Pattern : REMEMBER_DIR=<Verzeichnis>\n     Funciton: Mit dieser Funktion können sie das Remember-Verzeichnis\n               setzen. Wenn Sie das Merkmal nicht setzen, dann wird als\n               RememberDir das Verzeichnis "BBS:RememberDir/" verwendet.\n               Das Remember-Verzeichnis muß ein Verzeichnis sein, in dem\n               keine anderen Dateien sein.\n     Beispiel: REMEMBER_DIR=BBS:Files/RememberDir/\n               Das Remeber-Verzeichnis ist "BBS:Files/RememberDir/".\n@EndNode\n\n@Node "STRIP_FILEID_LINES" "Merkmal: STRIP_FILEID_LINES"\n@Next "STRIP_FILES"\n@Prev "REMEMBER_DIR"\n@Toc "Configuration"\n\n  @{b}@{u}STRIP_FILEID_LINES@{ub}@{uu}\n\n     Pattern : STRIP_FILEID_LINES=<Dateiname>\n     Funktion: Wenn dieses Mekrmal gesetzt ist, dann können Sie Zeilen aus\n               einer FILE_ID.DIZ Datei löschen. Sie müssen eine Datei angeben,\n               die die Zeilen enthält, die gelöscht werden sollen.\n     Beispiel: STRIP_FILEID_LINES=DOORS:rEAL/rEAL-uPLOAD/StripFileID\n               Die Zeilen der Datei "DOORS:rEAL/rEAL-uPLOAD/StripFileID"\n               werden aus der FILE_ID.DIZ Datei gelöscht.\n@EndNode\n\n@Node "STRIP_FILES" "Merkmal: STRIP_FILES"\n@Next "USE_LOCAL_FOR_NODE"\n@Prev "STRIP_FILEID_LINES"\n@Toc "Configuration"\n\n  @{b}@{u}STRIP_FILES@{ub}@{uu}\n\n     Pattern : STRIP_FILES=<Dateiname>\n     Funktion: Wenn dieses Merkmal gesetzt ist, dann können Dateien aus\n               einem LHA, LZH, LZX oder ZIP Archiv gelöscht werden. Sie\n               müssen eine Datei angeben, in welchem die Dateinamen aufge-\n               listet sind.\n     Beispiel: STRIP_FILES=DOORS:rEAL/rEAL-uPLOAD/StripFile\n               Die Dateinamen der Datei "DOORS:rEAL/rEAL-uPLOAD/StripFile"\n               werden aus dem Archiv entfernt.\n@EndNode\n\n@Node "USE_LOCAL_FOR_NODE" "Merkmal: USE_LOCAL_FOR_NODE"\n@Next "WEEK_TOP_DOWNLOADER_TEXT"\n@Prev "STRIP_FILES"\n@Toc "Configuration"\n\n  @{b}@{u}USE_LOCAL_FOR_NODE@{ub}@{uu}\n\n     Pattern : USE_LOCAL_FOR_NODE=<NodeNummer>\n     Funktion: Wenn dieses Merkmal gesetzt ist, wird die angegebene Node als\n               [!LOCAL!] und nicht als [NODE XX] dargestellt.\n     Beispiel: USE_LOCAL_FOR_NODE=0\n               Benutze Node 0 als "[!LOCAL!]" Node.\n@EndNode\n\n@Node "WEEK_TOP_DOWNLOADER_TEXT" "Merkmal: WEEK_TOP_DOWNLOADER_TEXT"\n@Next "WEEK_TOP_UPLOADER_ENTRYS"\n@Prev "USE_LOCAL_FOR_NODE"\n@Toc "Configuration"\n\n  @{b}@{u}WEEK_TOP_DOWNLOADER_TEXT@{ub}@{uu}\n\n     Pattern : WEEK_TOP_DOWNLOADER_TEXT=<Dateiname>\n     Funktion: Hier können Sie die Textdatei für den WeekTop-Downloader\n               angeben.\n               Wenn keine Datei angegeben wird, dann wird keine Datei ge-\n               schrieben.\n               Sie können den Text beim LOGIN, in einem BULL oder sonst wo\n               anzeigen.\n               Die WeekTop-Downloader können ebenfalls mit dem WEEKTOP Befehl\n               angezeigt werden.\n     Beispiel: WEEK_TOP_DOWNLOADER_TEXT=DOORS:rEAL/rEAL-uPLOAD/WeekTopDown.txt\n               Die WeekTop-Downloader werden in die Datei\n               "DOORS:rEAL/rEAL-uPLOAD/WeekTopDown.txt" geschrieben.\n@EndNode\n\n@Node "WEEK_TOP_UPLOADER_ENTRYS" "Merkmal: WEEK_TOP_UPLOADER_ENTRYS"\n@Next "WEEK_TOP_UPLOADER_TEXT"\n@Prev "WEEK_TOP_DOWNLOADER_TEXT"\n@Toc "Configuration"\n\n  @{b}@{u}WEEK_TOP_UPLOADER_ENTRYS@{ub}@{uu}\n\n     Pattern : WEEK_TOP_ENTRYS=<Einträge>\n     Funktion: Hier werden die Einträge für den WeekTop-Uploader\n               festgelegt.\n               Grundeinstellung=10\n     Beispiel: WEEK_TOP_ENTRYS.1=15\n               Es werden 15 Einträge zum WeekTop-Uploader geschrieben.\n@EndNode\n\n@Node "WEEK_TOP_UPLOADER_TEXT" "Merkmal: WEEK_TOP_UPLOADER_TEXT"\n@Next "WEEK_TOP_UPLOADER_TIME"\n@Prev "WEEK_TOP_UPLOADER_ENTRYS"\n@Toc "Configuration"\n\n  @{b}@{u}WEEK_TOP_UPLOADER_TEXT@{ub}@{uu}\n\n     Pattern : WEEK_TOP_UPLOADER_TEXT=<Dateiname>\n     Funktion: Hier können Sie die Textdatei für den WeekTop-Uploader\n               angeben.\n               Wenn keine Datei angegeben wird, dann wird keine Datei ge-\n               schrieben.\n               Sie können den Text beim LOGIN, in einem BULL oder sonst wo\n               anzeigen.\n               Die WeekTop-Uploader können ebenfalls mit dem WEEKTOP Befehl\n               angezeigt werden.\n     Beispiel: WEEK_TOP_UPLOADER_TEXT=DOORS:rEAL/rEAL-uPLOAD/WeekTopUp.txt\n               Die WeekTop-Uploader werden in die Datei\n               "DOORS:rEAL/rEAL-uPLOAD/WeekTopUp.txt" geschrieben.\n@EndNode\n\n@Node "WEEK_TOP_UPLOADER_TIME" "Merkmal: WEEK_TOP_UPLOADER_TIME"\n@Next "WEEK_TOP_UPLOADER_USERNOT"\n@Prev "WEEK_TOP_UPLOADER_TEXT"\n@Toc "Configuration"\n\n  @{b}@{u}WEEK_TOP_UPLOADER_TIME@{ub}@{uu}\n\n     Pattern : WEEK_TOP_UPLOADER_TIME=<Tage>\n     Funktion: Mit diesem Merkmal können Sie festlegen nach wievielen\n               Tagen der WeekTop-Uploader neu gestartet wird.\n               Grundeinstellung=7\n     Beispiel: WEEK_TOP_UPLOADER_TIME.1=14\n               Der WeekTop-Uploader wird alle 2 Wochen neu gestartet.\n@EndNode\n\n@Node "WEEK_TOP_UPLOADER_USERNOT" "Merkmal: WEEK_TOP_UPLOADER_USERNOT"\n@Next "WRITE_EALL_ON_GROUP_RELEASE"\n@Prev "WEEK_TOP_UPLOADER_TIME"\n@Toc "Configuration"\n\n  @{b}@{u}WEEK_TOP_UPLOADER_USERNOT@{ub}@{uu}\n\n     Pattern : WEEK_TOP_UPLOADER_USERNOT.<num>=<Name>\n     Funktion: Mit diesem Merkmal können Sie User festlegen, die\n               nicht im WeekTop-Uploader erscheinen sollen.\n     Beispiel: WEEK_TOP_UPLOADER_USERNOT.1=hIGH-SPEEd\n               Der User "hIGH-SPEEd" wird nicht für den WeekTop-Uploader\n               verwendet.\n@EndNode\n\n@Node "WRITE_EALL_ON_GROUP_RELEASE" "Merkmal: WRITE_EALL_ON_GROUP_RELEASE"\n@Next "WRITE_LOCAL_ON_LOCAL_MODE"\n@Prev "WEEK_TOP_UPLOADER_USERNOT"\n@Toc "Configuration"\n\n  @{b}@{u}WRITE_EALL_ON_GROUP_RELEASE@{ub}@{uu}\n\n     Pattern : WRITE_EALL_ON_GROUP_RELEASE\n     Funktion: Wenn eine Gruppe gefunden wurde (GROUP_STRING) und dieses\n               Merkmal gesetzt ist, dann wird eine EALL-Nachricht mit der\n               FileID, dem Uploader, der Upload-Zeit... geschrieben.\n     Beispiel: WRITE_EALL_ON_GROUP_RELEASE\n               Es wird eine EALL-Nachricht beim Gruppen-Release geschrieben.\n@EndNode\n\n@Node "WRITE_LOCAL_ON_LOCAL_MODE" "Merkmal: WRITE_LOCAL_ON_LOCAL_MODE"\n@Next "WRITE_MESSAGE_ON_PRIVATE_UPLOAD"\n@Prev "WRITE_EALL_ON_GROUP_RELEASE"\n@Toc "Configuration"\n\n  @{b}@{u}WRITE_LOCAL_ON_LOCAL_MODE@{ub}@{uu}\n\n     Pattern : WRITE_LOCAL_ON_LOCAL_MODE\n     Funktion: Wenn dieses Merkmal gesetzt ist wird der Text "[NODE XX]" als\n               "[!LOCAL!]" geschrieben, wenn bei der Eingabe ein "L" einge-\n               geben wurde.\n     Beispiel: WRITE_LOCAL_ON_LOCAL_MODE\n               Benutze "[!LOCAL!]" wenn "L" gedrückt wird.\n@EndNode\n\n@Node "WRITE_MESSAGE_ON_PRIVATE_UPLOAD" "Merkmal: WRITE_MESSAGE_ON_PRIVATE_UPLOAD"\n@Prev "WRITE_LOCAL_ON_LOCAL_MODE"\n@Toc "Configuration"\n\n  @{b}@{u}WRITE_MESSAGE_ON_PRIVATE_UPLOAD@{ub}@{uu}\n\n     Pattern : WRITE_MESSAGE_ON_PRIVATE_UPLOAD\n     Funktion: Wenn dieses Merkmal gesetzt ist dann wird eine Nachricht\n               bei einem privaten Upload an den Sysop oder einen anderen\n               User (PRIVATE_UPLOAD_MESSAGE_TO) geschrieben.\n     Beispiel: WRITE_MESSAGE_ON_PRIVATE_UPLOAD\n               Es wird eine Nachricht beim privaten Upload geschrieben.\n@EndNode\n\n@Node "Greetings" "gREETINGs!"\n@Toc "Main"\n\n@{b}@{u}gREETINGs!@{ub}@{uu}\n\n                           ... GReeTz fLYIng To ...\n\n      spEZIaL greETz fROM hIGH-SPEEd 2:\n\n      InTENsiTy , DoC waTSoN , GoroNIt , REvOlVer\n      anD tO aLl PhANTasM MeMBerS...\n\n      spEZIaL greETz fROM [-sAxOn-] 2:\n\n      SIRiAX,aLPHA ONe,pYRO,sLIME!,mARIO,vAMPIRE,JOHN SINCLAIR,\n      gALAXY,HITPOINT,KRYPTON,2FAST,DECCA,SIRE,CHAOS,PET,SABINE,\n      cANNIBAL,sTARLIGHT,H2o,mAGGY,sPIRIT,aNETTE,aNDREA,SPEEDY,\n      fRANK,jAYWALKER,pICARD,BASTARd^aPOLLO,5r,Awson,dEETs,gONZO,\n      BEN.E,aZURE!,trON,cRAsh,Gandalf,CRisi,SLaxx,pedl ^ dello,\n\n      and of coz 2:\n\n                       sPIRIT and tHE aLIEN\n@EndNode\n\n@Node "Members_Infos_Boards" "mEMBERs, iNFOs, bOARDs"\n@Toc "Main"\n\n@{b}@{u}mEMBERs, iNFOs, bOARDs@{ub}@{uu}\n\nmEMBAS:\n        [-sAxOn-]   mAIN-oRGA , sYSOP fLYING DRAGOn WHq , cODER , dZ\n        hIGH-SPEEd  mAIN-cODER , oRGA , sYSOP tHE dUNGEON GHq , dZ\n        sTEVE       sYSOP dIGITAL wORLD EHq\n        jOP!        aSCII-aNSI dZ\n\nbOARDS:\n        [-sAxOn-]   fLYING DRAGOn     - rEAL WHq - gERMANY\n        sTEVE       dIGITAL wORLD     - rEAL EHq - gERMANY\n        hIGH-SPEEd  tHE dUNGEON       - rEAL GHq - gERMANY\n@EndNode\n\n@Node "Tools_Released" "tOOLz rELEASEd"\n@Next "Comming_Soon"\n@Toc "Main"\n\n@{b}@{u}tOOLz rELEASEd@{ub}@{uu}\n\n   sYS-DOWn V1.2       nOW aVAILABLE...\n   bAUD-cOUNTER V1.1   nOW aVAILABLE...\n   sEC-CHECk V1.3      nOW aVAILABLE...\n   rEAL-sTAT V1.1      nOW aVAILABLE...\n   cONF-MOVEr V1.1     nOW aVAILABLE...\n   rEAL-CALLERs V1.1   nOW aVAILABLE...\n   sYS-cOMMENT V1.1    nOW aVAILABLE...\n   rEAL-pAGE V1.1      nOW aVAILABLE...\n   rEAL-wALL V1.2      nOW aVAILABLE...\n   rEAL-uPLOAD V1.0    nOW aVAILABLE...\n\n   hOL dIR dEINE rEGISTRIERTEN vERSIONEN jETZT!!!\n@EndNode\n\n@Node "Comming_Soon" "bALD ZU ERHALTEn"\n@Prev "Tools_Released"\n@Toc "Main"\n\n@{b}@{u}bALD ZU ERHALTEn@{ub}@{uu}\n\n   rEAL-LOGOFF V1.0    bETA tEST lÄUFT (tHE dUNGEON, fLYING dRAGON)\n   rEAL-WHO V1.0       bETA tEST lÄUFT (tHE dUNGEON, fLYING dRAGON)\n   sTATUS dOOR V1.5    bETA tEST lÄUFT (fLYING dRAGON)\n   fRONTWHO V1.7       bETA tEST lÄUFT (fLYING dRAGON)\n   gAME-MANAGEr V1.0   bETA tEST bALD\n   rEAL-RECORDs V1.0   bETA tEST bALD\n@EndNode\n\n@Node "The_Dungeon" "jETZT CALLEn"\n@Next "Flying_Dragon"\n@Toc "Main"\n\n                            ... jETZT CALLEn ...\n     .                                                                :\n  - -+-----------------------[ ThE dUNgEon bBs ]----------------------+-- -\n     |@{b}            _______________.                                    @{ub}|\n     ¦@{b}           /               |        ________________            @{ub}|\n     |@{b}          /_______\\      __|___.    \\    ______    /            @{ub}¡\n     |@{b}   _ _ ____.       \\____/      |_____\\___\\________/_            @{ub}|\n     |@{b}   ////____|           /       _        /__________/            @{ub}|\n     !@{b}     ______.          /________|       /_ _ ____________________@{ub}|@{b} _ _@{ub}\n     |@{b}    /      |                   |______/  \\\\\\\\___________________////@{ub}\n@{b}_____@{ub}|@{b}___/__     | _________. _____________         _________________ @{ub}|\n@{b}\\    ______/.____|_\\        | \\     ______/____.    \\    _______    / @{ub}|\n@{b} \\__________|       \\       |__\\____\\_.___     |_____\\_____   _/   /__@{ub}|@{b}___.@{ub}\n     |@{b}      |_______________|__       |________|______    /_______/__     |@{ub}\n     |@{b}                |_______/       |b!d  \\   \\________/_ |_______/     |@{ub}\n     |@{b}                       /________|      \\____________/        /______|@{ub}\n     ¦@{b}                  _ _ __________.                               @{ub}|\n     !@{b}                  ////__________|