S\n@EndNode\n\n@Node "rEA" "rEAL"\n@Toc "Main"\n\n@{b}                 .:::::.  .::::.      ..:::::.     ..:::::.\n               .::::::::.:::::::.   .:::··:::::   ::·:::::·\n             .:::::::::::::::::::  .:::·   ::::    .::::·\n         .:::::· :::::::·   :::::: ·::·    ::::   .:::·\n         :::::  ::::::::    ::::::    .... ::::  .:::·\n          :::.  :::::::;   ::::::; .::::::::::: .:::·          ...\n           :::. ·::::::...::::::· .::::··:::::: :::·          ::::.\n           ·:::. ··::::::::::··   ::::    ::::::::·            ::::\n            ·:::.  :::·        ..:::::    :::::::::.......:::::::::\n             ::::; :::    ...::::::::::..::::::::::::::::·····::::;\n              ···  ·::::::::::::· ·::::::::::·····b!d\n                    ·::::····\n\n                     [rEAL!] [tHE cHOICE oF qUALITY!]\n@{ub}\n@EndNode\n\n@Node "Index" "iNDEx"\n@Toc "Main"\n\n@{b}@{u}iNDEx@{ub}@{uu}\n\n   @{" ADD_FILEID_LINE                  " Link "ADD_FILEID_LINE"}\n   @{" ALLTIME_TOP_DOWNLOADER_ENTRYS    " Link "ALLTIME_TOP_DOWNLOADER_ENTRYS"}\n   @{" ALLTIME_TOP_DOWNLOADER_TEXT      " Link "ALLTIME_TOP_DOWNLOADER_TEXT"}\n   @{" ALLTIME_TOP_DOWNLOADER_USERNOT   " Link "ALLTIME_TOP_DOWNLOADER_USERNOT"}\n   @{" ALLTIME_TOP_UPLOADER_ENTRYS      " Link "ALLTIME_TOP_UPLOADER_ENTRYS"}\n   @{" ALLTIME_TOP_UPLOADER_TEXT        " Link "ALLTIME_TOP_UPLOADER_TEXT"}\n   @{" ALLTIME_TOP_UPLOADER_USERNOT     "  Link "ALLTIME_TOP_UPLOADER_USERNOT"}\n   @{" jETZT CALLEn                     " Link "The_Dungeon"}\n   @{" CHECKTASK_PRIORITY               " Link "CHECKTASK_PRIORITY"}\n   @{" bALD ZU ERHALTEn                 " Link "Comming_Soon"}\n   @{" CONF_TOP_UPLOADER_ENTRYS         " Link "CONF_TOP_UPLOADER_ENTRYS"}\n   @{" CONF_TOP_UPLOADER_TEXT           " Link "CONF_TOP_UPLOADER_TEXT"}\n   @{" CONF_TOP_UPLOADER_TIME           " Link "CONF_TOP_UPLOADER_TIME"}\n   @{" CONF_TOP_UPLOADER_USERNOT        " Link "CONF_TOP_UPLOADER_USERNOT"}\n   @{" CPS_UPLOAD_LINE                  " Link "CPS_UPLOAD_LINE"}\n   @{" DELETE_???                       " Link "DELETE_???"}\n   @{" DEPACK_???                       " Link "DEPACK_???"}\n   @{" DEPACK_ALL_???                   " Link "DEPACK_ALL_???"}\n   @{" DISPLAY_BEEP_AFTER_FILE          " Link "DISPLAY_BEEP_AFTER_FILE"}\n   @{" FILE_ADD                         " Link "FILE_ADD"}\n   @{" FILEID_LINES_MAX                 " Link "FILEID_LINES_MAX"}\n   @{" fLYING dRAGON                    " Link "Flying_Dragon"}\n   @{" FREE_RESUMING                    " Link "FREE_RESUMING"}\n   @{" gREETINGs                        " Link "Greetings"}\n   @{" GROUP_ADDLINE                    " Link "GROUP_ADDLINE"}\n   @{" GROUP_STRING                     " Link "GROUP_STRING"}\n   @{" iNSTALLATIOn                     " Link "Installation"}\n   @{" aNFORDERUNGEn                    " Link "Introduction"}\n   @{" kONFIGURATIOn                    " Link "Configuration"}\n   @{" LOCAL_UPLOAD_DIR                 " Link "LOCAL_UPLOAD_DIR"}\n   @{" LOCAL_UPLOAD_PASSWORD            " Link "LOCAL_UPLOAD_PASSWORD"}\n   @{" MAKE_GROUP_RELEASE_FREE_DOWNLOAD " Link "MAKE_GROUP_RELEASE_FREE_DOWNLOAD"}\n   @{" mEMBERs, iNFOs, bOARDs           " Link "Members_Infos_Boards"}\n   @{" NEWFILE_UPLOADED_TEXT            " Link "NEWFILE_UPLOADED_TEXT"}\n   @{" PACK_???                         " Link "PACK_???"}\n   @{" PACK_ALL_???                     " Link "PACK_ALL_???"}\n   @{" PRIVATE_UPLOAD_DIR               " Link "PRIVATE_UPLOAD_DIR"}\n   @{" PRIVATE_UPLOAD_MESSAGE_TO        " Link "PRIVATE_UPLOAD_MESSAGE_TO"}\n   @{" PSEUDO_DIR                       " Link "PSEUDO_DIR"}\n   @{" rEGISTRATIOn                     " Link "Registration"}\n   @{" RELEASE_DATE                     " Link "RELEASE_DATE"}\n   @{" REMEMBER_DIR                     " Link "REMEMBER_DIR"}\n   @{" rEQUIREMENTs                     " Link "Requirements"}\n   @{" sERVEr                           " Link "Server"}\n   @{" STRIP_FILEID_LINES               " Link "STRIP_FILEID_LINES"}\n   @{" STRIP_FILES                      " Link "STRIP_FILES"}\n   @{" tHE dUNGEON                      " Link "The_Dungeon"}\n   @{" tOOLz rELEASEd                   " Link "Tools_Released"}\n   @{" USE_LOCAL_FOR_NODE               " Link "USE_LOCAL_FOR_NODE"}\n   @{" WEEK_TOP_DOWNLOADER_TEXT         " Link "WEEK_TOP_DOWNLOADER_TEXT"}\n   @{" WEEK_TOP_UPLOADER_ENTRYS         " Link "WEEK_TOP_UPLOADER_ENTRYS"}\n   @{" WEEK_TOP_UPLOADER_TEXT           " Link "WEEK_TOP_UPLOADER_TEXT"}\n   @{" WEEK_TOP_UPLOADER_TIME           " Link "WEEK_TOP_UPLOADER_TIME"}\n   @{" WEEK_TOP_UPLOADER_USERNOT        " Link "WEEK_TOP_UPLOADER_USERNOT"}\n   @{" aRBEITSWEISe                     " Link "Working"}\n   @{" WRITE_EALL_ON_GROUP_RELEASE      " Link "WRITE_EALL_ON_GROUP_RELEASE"}\n   @{" WRITE_LOCAL_ON_LOCAL_MODE        " Link "WRITE_LOCAL_ON_LOCAL_MODE"}\n   @{" WRITE_MESSAGE_ON_PRIVATE_UPLOAD  " Link "WRITE_MESSAGE_ON_PRIVATE_UPLOAD"}\n@EndNode\n','\n',char(10)),'{"PRIORITY":"<Priorität>"}',NULL,665782,2,0,NULL,NULL,NULL,'scan',1780048775);
INSERT INTO door_catalog VALUES('tel_tp02','TEL-TP02.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TEL-TP02.LHA','RES-RL','XIM','_______________________________________',NULL,NULL,'TEL','\_     ____________.   \_    _________/ |     |     \_    |     \_______    \_ |     l      /    l_     /           /',replace('  _______________________________________\n  \_     ____________.   \_    _________/\n   |     |     \_    |     \_______    \_\n   |     l      /    l_     /           /\n   l______     /______     /______     /\n ·-------\____/------\____/--sCF!\____/--·\n  ¡CE of cDs is back once again with:\n        - CoolCallersLottery 1.0 -\n  A COOL callerslottery for /X and FAME!\n ·---------------------------------------·\n [rEmEmBa:aMiGa rUleZ! pC sUxX! kILL bILL]\n','\n',char(10)),'MegaTop.guide',replace('@DataBase MegaTop\n@(C) 1996 Looby/Insane\n@AUTHOR Looby/Insane\n@DOCS By Marx & Looby & Cluster!\n@$VER: MegaTop.guide v2.0 (03.01.96)\n\n@Rem ==================================================================\n@Node MAIN "MegaTop v2.0 Documentation"\n\n     ______._______  _____ _ _______ __________________  _______ _________\n     \_    |_      \|      /   ____/_______.    __     \|      /   _     /\n      /    |/       \     /____.      /    |_   \/      \     /    _)___/\n   s_/    _/      \     _/     l     /     _/    \_    \    _/     |    \_s\n   c\_____\_______|\____\___________/      l______/    |\___\____________/c\n<-- -------------------------------\_______|-----------''\n\n                              [ p.r.e.s.e.n.t.s ]\n\n             @{BG fill} @{fg Shine}>>> MEGATOP v2.0 @{fg text}- THE ULTIMATE CHART GENERATOR <<<@{BG Background}\n\n                  @{"      Copyright (c) 1996 Looby/Insane!     " Link Copyright}\n \n                    @{"  Introduction  " Link Introduction}  @{"   The Designfiles   " Link MakeDesign}\n                    @{"  Installation  " Link Installation}  @{"       Credits       " Link Credits}\n                    @{"  Requirements  " Link Requirements}  @{"       History       " Link History}\n                    @{"     Usage      " Link Usage}  @{"       Support       " Link Support}     \n\n                  @{"i n s a n e  w o r l d w i d e  b o a r d s" Link Boards}\n\n      ==================================================================\n\n@EndNode\n\n@Rem ==================================================================\n@Node Copyright "MegaTop v2.0 Documentation - Copyright!"\n\n\n                               @{fg Shine}= MegaTop v2.0 =@{fg text}\n\n                Copyright © 1996 Anders "Looby/Insane" Wahlgren\n\n               Permission is hereby granted to freely distribute\n                 this product for non-commercial purposes only\n                    as long as all files remain unmodified.\n\n\n\n                        @{"[ <<<< ]" Link Main}               @{"[ >>>> ]" Link Introduction}\n\n\n      ==================================================================\n\n@EndNode\n\n@Rem ==================================================================\n@Node Introduction "MegaTop v2.0 Documentation - Introduction!"\n\n@{fg Shine}Introduction@{fg Text}\n~~~~~~~~~~~~\n  MegaTop is currently the most advanced chart-generator for AmiExpress!\n  It creates statistical charts (both total and weekly) using\n  user-definable design-files. This means for example that the sysop\n  can virtually design his own total-uploads with customized design!\n\n@{fg Shine}Features@{fg Text}\n~~~~~~~~\n  * User-definable design-files\n  * Mixing of all items in the same chart\n  * Intelligent date handler\n  * Weekly chart-mailing\n  * Presets\n  * Scripts\n  * Large item database\n  * Design output preview in Shell\n  * Various debugging modes\n  * Logfile\n\n              @{"[ <<<< ]" Link Copyright}              @{"[ Main ]" Link Main}             @{"[ >>>> ]" Link Installation}\n@EndNode\n\n@Rem ==================================================================\n@Node Installation "MegaTop v2.0 Documentation - Installation!"\n\n@{fg Shine}Installation@{fg Text}\n~~~~~~~~~~~~\n  Just use the included install-script!\n\n  If you for some reason don''t want/can''t use the install-script\n  then all you have to do is make a directory (optional, e.g. MegaTop)\n  in DOORS: and a sub-directory (optional, e.g. Design) for the\n  design-files. That''s it!\n\n\n\n              @{"[ <<<< ]" Link Introduction}              @{"[ Main ]" Link Main}             @{"[ >>>> ]" Link Requirements}\n\n\n@EndNode\n\n@Rem ==================================================================\n@Node Requirements "MegaTop v2.0 Documentation - Requirements!"\n\n@{fg Shine}Requirements@{fg Text}\n~~~~~~~~~~~~\n  * An Amiga (at least Release 2)\n  *    AmiExpress (at least v3.x, not tested below!)\n    or Tempest BBS\n\n  * The DOORS: and T: assigns MUST be present!\n\n\n\n              @{"[ <<<< ]" Link Installation}              @{"[ Main ]" Link Main}             @{"[ >>>> ]" Link Usage}\n\n\n@EndNode\n\n@Rem ==================================================================\n@Node MakeDesign "MegaTop v2.0 Documentation - Usage : Make design files"\n\n@{fg Shine}Designfile formating@{fg Text}\n~~~~~~~~~~~~~~~~~~~~\n                             @{"     Cells     " Link Cells}\n                             @{"     Mail      " Link Mail} (AmiExpress)\n                             @{"    Presets    " Link Presets}\n\n\n\n          @{"[ <<<< ]" Link Usage}              @{"[ Main ]" Link Main}             @{"[ >>>> ]" Link Credits}\n\n@EndNode\n\n@Rem ==================================================================\n@Node Usage "MegaTop v2.0 Documentation - Usage : Usage"\n\n@{fg Shine}Usage@{fg Text}\n~~~~~\n  MegaTop is to be executed when a user logoff.\n\n  The LOGOFF1.SCRIPT for node one can look like this:\n\n  -- cut --\n  DOORS:MEGATOP/MEGATOP SCRIPT=DOORS:MEGATOP/MEGATOP.SCR\n  -- cut --\n\n@{fg Shine}Arguments@{fg Text}\n~~~~~~~~~\n  DSG=<file>      - @{I}Design file@{UI}\n                    Enter full path pointing to the designfile.\n\n  DATA=<file>     - @{I}Userdata file@{UI}\n                    Enter full path pointing to the ''User.data''.\n                    Default path is ''BBS:USER.DATA''.\n\n  USERKEYS=<file> - @{I}UserKeys file@{UI} (AmiExpress)\n                    Enter full path pointing to the ''User.keys''.\n                    Default path is ''BBS:USER.KEYS''.\n\n  OUTPUT=<file>   - @{I}Output file@{UI}\n                    Enter full path pointing to the output-file.\n\n  SCRIPT=<file>   - @{I}Script file@{UI}\n                    Enter full path pointing to the @{"script-file" Link Scripts}.\n\n@{fg Shine}Options@{fg Text}\n~~~~~~~\n  SYSOP=<n>       - @{I}Sysop counting@{UI}\n                    0 = Include sysop (default).\n                    1 = Count sysop stats but hide him/her.\n                    2 = Do not include sysop.\n         \n  NOZERO          - Do not show users/fields with zero values.\n\n  DEBUG=<n>       - @{I}Debug information@{UI}\n                    Bit#\n                       0 (0)  = No debugging information (default).\n                       1 (1)  = Show settings.\n                       2 (2)  = User.data & Megatop.dat comparison\n                                Output to screen.\n                    e.g.  ''1'' and ''2'' : (1) + (2) = 3 : DEBUG=3\n\n  LOG=<n>         - @{I}Logfile@{UI} ( DOORS:MegaTop.Log )\n                    Bit#\n                       0 (0) = Off\n                       1 (1) = On\n\n  TEST            - @{I}Test mode@{UI}\n                    To test the output in the current window.\n                    Output file will also be generated.\n                    No WeekReset nor Mailing will be made.\n                    No logdata will be saved (even if you use LOG=x).\n\n\n              @{"[ <<<< ]" Link Requirements}              @{"[ Main ]" Link Main}             @{"[ >>>> ]" Link MakeDesign}\n@EndNode\n\n@Rem ==================================================================\n@Node Cells "MegaTop v2.0 Documentation - Usage : Cells!"\n\n@{fg Shine}Cells@{fg Text}\n~~~~~\n\n  @{fg Shine}NOTE!@{fg Text} The cell MUST contain at least two dots ''.'' (Used as seperators).\n        And the SysNum_Progname and SysNum_Author cells must be included,\n        or else they will appear in the bottom of the output file..\n\n      %[1.15-.ITEM.P]\n        |  |   |   |\n        |  |   |   `----- @{" Preset " Link Presets}\n        |  |   |\n        |  |   `--------- @{" Item " Link Items}\n        |  |\n        |  `------------- @{" Width " Link Width}\n        |\n        `---------------- @{" User position " Link UserPos}\n\n  Ex. %[1.10.UL_TOT_NAME]  : Valid\n      %[..SYSSUM_AUTHOR]   : Valid\n      %[.UL_TOT_NAME]      : Not Valid\n\n\n\n              @{"[ <<<< ]" Link Presets}              @{"[ Main ]" Link MakeDesign}             @{"[ >>>> ]" Link Mail}\n\n@EndNode\n\n@Rem ==================================================================\n@Node Preset "MegaTop v2.0 Documentation - Usage : Cells : Preset!"\n\n@{fg Shine}Preset@{fg Text}\n~~~~~~\n  There are two main datatypes from which MegaTop gathers data from:\n\n  * System/Week totals\n  * User totals\n\n  (See also @{" Presets " Link Presets})\n\n\n@EndNode\n\n@Rem ==================================================================\n@Node Width "MegaTop v2.0 Documentation - Usage : Cells : Width!"\n\n@{fg Shine}Width@{fg Text}\n~~~~~\n  -n    // Right justified\n  n-    // Left justified\n  -n-   // Centered\n\n  ''n'' stands for the width of the cell.\n  (If you don''t give a number the cell won''t be formated).\n\n              @{"[ <<<< ]" Link Items}              @{"[ Main ]" Link Cells}             @{"[ >>>> ]" Link Userpos}\n\n@EndNode\n\n@Rem ==================================================================\n@Node UserPos "MegaTop v2.0 Documentation - Usage : Cells : User position!"\n\n@{fg Shine}User position@{fg Text}\n~~~~~~~~~~~~~\n  Specifies the user position in list.\n  Negative numbers equal position counted from the end of list.\n\n              @{"[ <<<< ]" Link Width}              @{"[ Main ]" Link Cells}             @{"[ >>>> ]" Link Items}\n\n@EndNode\n\n@Rem ==================================================================\n@Node Items "MegaTop v2.0 Documentation - Usage : Items!"\n\n@{fg Shine}Items@{fg Text}\n~~~~~\n  Two sorts of formats exist:\n\n\n  Used for items that doesn''t have any users connected to it.\n\n  - @{" SYSTEM/WEEK TOTALS " Link ChartModes}_ITEM\n                           |\n                           +-----@{" Week items   " Link WeekItems}\n                           `-----@{" System items " Link SysItems}\n\n  Used for items that have users connected th it.\n\n  - @{" SORT-ORDER " Link SortOrder}_@{" DATA " Link Data}_@{" ITEMS " Link UserItems}\n\n              @{"[ <<<< ]" Link Userpos}              @{"[ Main ]" Link Cells}             @{"[ >>>> ]" Link Width}\n \n@EndNode\n\n@Rem ==================================================================\n@Node ChartModes "MegaTop v2.0 Documentation - Usage : Items : Chart modes!"\n\n@{fg Shine}Chart modes@{fg Text}\n~~~~~~~~~~~\n  SYSSUM                   // System summary\n                           // ie. Total upload on system or calls.\n\n  WEEKSUM                  // Week period summary\n                           // ie. Total upload this week.\n\n              @{"[ <<<< ]" Link Sysitems}              @{"[ Main ]" Link Items}             @{"[ >>>> ]" Link WeekItems}\n\n@EndNode\n\n@Rem ==================================================================\n@Node SortOrder "MegaTop v2.0 Documentation - Usage : Items : Sort order!"\n\n@{fg Shine}Sort order@{fg Text}\n~~~~~~~~~~\n  UL                       // Upload bytes\n  DL                       // Download bytes\n  ULS                      // Upload files\n  DLS                      // Download files\n  CALL                     // Calls\n  MESS                     // Messages posted\n  CPSUL                    // Sort data on Cps upload rate   (AmiExpress)\n  CPSDL                    // Sort data on Cps download rate (AmiExpress)\n  SLOT                     // Sort on users slotnumber\n\n              @{"[ <<<< ]" Link UserItems}              @{"[ Main ]" Link Items}             @{"[ >>>> ]" Link Data}\n\n@EndNode\n\n@Rem ==================================================================\n@Node Data "MegaTop v2.0 Documentation - Usage : Items : Data!"\n\n@{fg Shine}Data@{fg Text}\n~~~~\n\n  What type of data to be used.\n\n  WEEK                     // Week totals\n\n  WEEKTOT                  // ie. If you want to get the total upload\n                           // from the user how is first on the weektop.\n\n  TOT                      // System totals\n\n  TOTWEEK                  // ie. If you want to see how many calls the\n                           // user who is number one on the weektop.\n\n              @{"[ <<<< ]" Link Sortorder}              @{"[ Main ]" Link Items}             @{"[ >>>> ]" Link UserItems}\n\n@EndNode\n\n@Rem ==================================================================\n@Node WeekItems "MegaTop v2.0 Documentation - Usage : Items : Week items!"\n\n@{fg Shine}Week items@{fg Text}\n~~~~~~~~~~\n  BYTESUP                  // Upload bytes\n  BYTESDOWN                // Download bytes\n  FILESUP                  // Upload files\n  FILESDOWN                // Download files\n  CALLS                    // Calls\n  MESSAGES                 // Messages posted\n  NEWUSERS                 // New users this week\n  DELUSERS                 // Deleted users this week\n  DAYSLEFT                 // Days left on week inkl. current day\n  DAYSPASSED               // Passed days on week including current day\n\n              @{"[ <<<< ]" Link Chartmodes}              @{"[ Main ]" Link Items}             @{"[ >>>> ]" Link Sysitems}\n\n@EndNode\n\n@Rem ==================================================================\n@Node SysItems "MegaTop v2.0 Documentation - Usage : Items : System items!"\n\n@{fg Shine}System items@{fg Text}\n~~~~~~~~~~~~\n  BYTESUP                  // Upload bytes\n  BYTESDOWN                // Download bytes\n  FILESUP                  // Upload files\n  FILESDOWN                // Download files\n  CALLS                    // Calls\n  MESSAGES                 // Messages posted\n  USERS                    // Total accounts\n  DATE                     // Date when top was generated, e.g. ''22-04-95''\n  TIME                     // Time when top was generated, e.g. ''18:01:49''\n  PROGNAME                 // Name of program\n  AUTHOR                   // Name of author\n\n              @{"[ <<<< ]" Link WeekItems}              @{"[ Main ]" Link Items}             @{"[ >>>> ]" Link Chartmodes}\n\n@EndNode\n\n@Rem ==================================================================\n@Node UserItems "MegaTop v2.0 Documentation - Usage : Items : User items!"\n\n@{fg Shine}User items@{fg Text}\n~~~~~~~~~~\n  SLOTNR                   // Slot number\n  NAME                     // Name\n  LOCATION                 // Location\n  BYTESUP                  // Upload bytes\n  BYTESDOWN                // Download bytes\n  FILESUP                  // Upload files\n  FILESDOWN                // Download files\n  CALLS                    // Calls\n  MESSAGES                 // Messages posted\n  LASTONDATE               // Users last logon data ex. ''14-08-94''\n  LASTONTIME               // Users last logon time ex. ''20:35:43''\n  LCFILES                  // Lost carrier files (AmiExpress)\n  BYTERATIO                // Byteratio ''BYTESUP/BYTESDOWN''\n                              ex 10000 up 20000 dl = -2\n                                 20000    10000    =  2\n                                 10000    10000    =  0\n                                 10000        0    =  10000\n                                     0    10000    = -10000\n  FILERATIO                // fileratio FILESUP/FILESDOWN\n                              Same tactics as ''BYTERATIO''\n  CPSU                     // Top CPS upload rate (AmiExpress)\n                           // (only in ''TOT'' and ''WEEKTOT'')\n  CPSD                     // Top CPS download rate (AmiExpress)\n                           // (only in ''TOT'' and ''WEEKTOT'')\n\n              @{"[ <<<< ]" Link Data}              @{"[ Main ]" Link Items}             @{"[ >>>> ]" Link Sortorder}\n\n@EndNode\n\n@Rem ==================================================================\n@Node Mail "MegaTop v2.0 Documentation - Usage : Mail!"\n\n@{fg Shine}Mail@{fg Text}\n~~~~~\n\n @{fg Shine}NOTE!@{fg Text} Mail is configured in @{"presets" Link Presets}\n\n\n  MAIL= <mode>     - Mail persion\n                     ''WEEK''  // Weekly ( mondays )\n\n  SUBJECT=<string> - The subject of the mail\n\n  TO=<string>      - Where the mail will be sent ex.\n\n  FROM=<string>    - From who the mail will be marked as.\n\n  CONFPATH=<path>  - The path to the conference where you want the\n                     mail to be posted.\n\n@{fg Shine}Example@{fg Text}\n~~~~~~~\n  -- cut --\n  BEGIN PRESET\n\n   MAIL=WEEK SUBJECT="Week result" TO="EALL" FROM="MegaTop" CONFPATH="BBS:CONF1/"\n\n   PRESET=1 B=0 V=M\n   PRESET=2 C=U\n   etc...\n  END PRESET\n   etc..\n  -- cut --\n\n              @{"[ <<<< ]" Link Cells}              @{"[ Main ]" Link MakeDesign}             @{"[ >>>> ]" Link Presets}\n\n@EndNode\n\n@Rem ==================================================================\n@Node Presets "MegaTop v2.0 Documentation - Usage : Presets!"\n\n@{fg Shine}Presets@{fg Text}\n~~~~~~~\n  @{fg Shine}NOTE!@{fg Text} You can''t mix BREAKPOINT''s and EQUAL''s.\n\n  PRESET=<presetnumber> - This is the presetnumber used in @{"cells" Link cells}.\n                          Has to be on EVERY preset row.\n\n  LEVEL=<levelnumber>   - Only used with ''B'' or ''E''.\n\n  MAIL=<period type>    - Mail period (See @{"mail" Link Mail})\n\n                          ''WEEK''  // Mail every week ( Monday )\n\n  V=<c>      - Output type\n\n               ''B'' = Bytes\n               ''K'' = Kilobytes\n               ''M'' = Megabytes\n               ''T'' = Thousand\n\n  B=<n>      - Breakpoints\n\n               Example:                                              Range\n\n               LEVEL=1 B=10 // Do that if value is 10 or less      ( x - 10 )\n               LEVEL=2 B=20 // Do that if value is 20 or less      ( 20- 11 )\n               LEVEL=3 B=30 // Do that if value is higher or equal ( 30-  x )\n\n  E=<n>      - Equal\n\n               Example:\n\n               LEVEL=1 E=10 // Do that if value is 10\n               LEVEL=2 E=20 // Do that if value is 20\n               LEVEL=3 E=!  // Otherwise do this.\n\n               If no criteria is valid an empty string will be returned.\n\n  M=<char>   - Type of seperator character, ( ONLY ONE CHAR ).\n               Works only on Numeric strings!\n\n               Example:\n\n               1.000.000 // M=.\n               1-000-000 // M=-\n\n  P=<string> - Prefix, String will be inserted added infront of item text/value\n\n  S=<string> - Suffix, String will be added last of item text/value\n\n  C=<c>      - Case mode\n\n               ''U'' = UPPER\n               ''L'' = lower\n               ''I'' = Indent\n\n@{fg Shine}Preset Example@{fg Text}\n~~~~~~~~~~~~~~\n\n  -- Cut --\n\n  BEGIN PRESET\n\n   PRESET=1 M=.\n\n   PRESET=2 V=K M='' P="Before " S=" After"\n\n   PRESET=3 LEVEL=1 V=B B=0        S=" Bytes"\n   PRESET=3 LEVEL=2 V=K B=1024     S=" Kb"\n   PRESET=3 LEVEL=3 V=M B=1024000  S=" Mb"\n\n  END PRESET\n\n  System total download : %[.-40.SYSSUM_BYTESDOWN.1]\n  System total download : %[.-40.SYSSUM_BYTESDOWN.2]\n  System total download : %[.-40.SYSSUM_BYTESDOWN.3]\n\n  -- Cut --\n\n@{fg Shine}Explanation@{fg Text}\n~~~~~~~~~~~\n\n Preset number 1 (PRESET=1) is a very simple one. It just puts\n  points (M=.) in value, ex 1.000.000.\n\n Preset number 2 (PRESET=2) Makes the valus as Kilobytes (V=K) and\n  puts the text ''Before'' in front of the value (P="Before ") and\n  the text string ''After'' (S=" After") after the value.\n\n Preset number 3 (PRESET=3) Here is a tricky one. If we want to control the\n  value we can use Breakpoints, that means if the valus is greater than a\n  number it changes. Every value lower and equal than 0 (B=0) will have\n  the suffix " Bytes" (S=" Bytes") and the value will be in bytes (B=0).\n\n\n              @{"[ <<<< ]" Link Mail}              @{"[ Main ]" Link MakeDesign}             @{"[ >>>> ]" Link Cells}\n\n@EndNode\n\n@Rem ==================================================================\n@Node Scripts "MegaTop v2.0 Documentation - Usage : Scripts!"\n\n@{fg Shine}Scripts@{fg Text}\n~~~~~~~\n\n  * Recommended strongly, for fast generation of output files.\n\n  * Comments begins with '';'' everything behind that is ignored.\n\n  * Option ''SYSOP=<n>'' in script file doesn''t work.\n    You have to specify ''SYSOP=n'' as command line argument if you\n    want sysop option.\n\n    ie. MegaTop SCRIPT=MegaTop.script SYSOP=2\n                                       ^^^^^^^\n                                         `-- This excludes sysop counting\n                                             in all outputs generated in\n                                             the script.\n\n    ie.  -- cut --\n         DSG=DOORS:MegaTop/Dsg/Weektop.dsg OUTPUT=RAM:WeekTop.txt NOZERO\n         DSG=DOORS:MegaTop/Dsg/Top10.dsg   OUTPUT=RAM:Top10.txt\n         --- cut ---\n\n              @{"[ <<<< ]" Link Usage}              @{"[ Main ]" Link Main}             @{"[ >>>> ]" Link Usage}\n\n@EndNode\n\n@Rem ==================================================================\n\n@Rem ==================================================================\n@Node Credits "MegaTop v2.0 Documentation - Credits!"\n\n                                    @{fg Shine}Credits@{fg Text}\n                                    ~~~~~~~\n  * Looby/Insane      - MegaTop executable, install-script, Documentation\n  * Marx/Insane       - Documentation\n  * Cluster/Insane    - Documentation, No.1 Beta tester, Ideas/Suggestions\n  * Nightshade/Insane - Beta Tester\n  * Shade/Insane      - Beta Tester\n  * MadMax/Insane     - Beta Tester\n\n  * Thanks to:\n\n    Bobo, BugByte, Cluster, Distler, Ezco & Sandman for the Designs ...\n\n\n\n              @{"[ <<<< ]" Link Makedesign}              @{"[ Main ]" Link Main}             @{"[ >>>> ]" Link History}\n\n@EndNode\n\n@Rem ==================================================================\n@Node History "MegaTop v2.0 Documentation - History!"\n\n@{fg Shine}History@{fg Text}\n~~~~~~~\n@{fg Shine}03-Jan-96 Rev1 v2.0@{fg Text}\n~~~~~~~~~~~~~~~~~~~\n  * First release!\n\n@{fg Shine}11-Apr-95 Rev1 v1.0@{fg Text}\n~~~~~~~~~~~~~~~~~~~\n  * MegaTop was born, as Requested by Cluster!\n\n\n\n              @{"[ <<<< ]" Link Credits}              @{"[ Main ]" Link Main}             @{"[ >>>> ]" Link Support}\n\n@EndNode\n\n@Rem ==================================================================\n@Node Support "MegaTop v2.0 Documentation - Support!"\n\n@{fg Shine}Contact Me!@{fg Text}\n~~~~~~~~~~~\n  To get in touch with me, try the following mediums:\n\n  BBS   - +46-8-7595847 [Insanitary: iNS-WHQ!]\n\n  IRC   - #amielite, Nick LOOBY\n\n  EMAIL - [email removed]\n\n\n@{fg Shine}Support@{fg Text}\n~~~~~~~\n  To get the latest version of MegaTop or new design files use:\n\n  WWW - http://www.canit.se/~andersw/megatop.html\n\n\n\n              @{"[ <<<< ]" Link History}              @{"[ Main ]" Link Main}             @{"[ >>>> ]" Link Boards}\n\n@EndNode\n\n@Rem ==================================================================\n@Node Boards "iNSANE wORLDWiDE bOARDS!"\n  ._________________________________________________________________________.\n  |                                                                         |\n  |              · Don''t Hesitate To Call These Insane HQ''s! ·              |\n  |                                                                         |\n  |     o1. Insanitary      -  World HeadQuarter     -   +46-8-7595847!     |\n  |         Insanitary      -  World HeadQuarter     -   +Ask-4-Telnet!     |\n  |     o2. The Chameleon   -  European HeadQuarter  -   +358-815409545     |\n  |         The Chameleon   -  European HeadQuarter  -   +358-815409589     |\n  |         The Chameleon   -  European HeadQuarter  -   +358-815546450     |\n  |     o3. Death Row       -  US HeadQuarter        -   +1-801-4769068     |\n  |         Death Row       -  US HeadQuarter        -   +1-801RingDown     |\n  |         Death Row       -  US HeadQuarter        -   +Ask-4-Telnet!     |\n  |     o4. Dial Hard       -  Swizz HeadQuarter     -   +41-735-065-25     |\n  |         Dial Hard       -  Swizz HeadQuarter     -   +41-73RingDown     |\n  |     o5. Sky Tower       -  Dannish HeadQuarter   -   +45-74-833886!     |\n  |         Sky Tower       -  Dannish HeadQuarter   -   +45-74RingDown     |\n  |     o6. Asylum          -  Swedish HeadQuarter   -   +46-303-798622     |\n  |         Asylum          -  Swedish HeadQuarter   -   +46-303-798920     |\n  |     o7. EveryWare       -  Norweigan HeadQuarter -   +47-639-541-90     |\n  |     o8. Fatal Justice   -  Distant HeadQuarter   -   +45-31118-2284     |\n  |__                                                                     __|_\n  |_/________  /\_________________________________________________________\_|\n  :          \/\n              @{"[ <<<< ]" Link Support}              @{"[ Main ]" Link Main}             @{"[ >>>> ]" Link Main}\n\n@EndNode\n','\n',char(10)),NULL,NULL,725180,10,0,NULL,NULL,NULL,'scan',1780048775);
INSERT INTO door_catalog VALUES('telfront','TELFRONT.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TELFRONT.LHA',NULL,'XIM','_',NULL,NULL,NULL,'^       / .------------------------------|----- / --. |                              |     /    |',replace('                                         _\n                                ^       /\n .------------------------------|----- / --.\n |                              |     /    |\n_|  :)-  tELNETfRONT V1.0  -(:  |   _/    _l_\n\__                             |          _/\n |  cODE : rEBEL/QUARTEX        |          |\n | dESIGN: nOP!/SAINTS          `------------>\n |                                         |\n | tHE cOOLEST fRONTEND dOOR fOR /X wITH   |\n |a lOOKING nICE dESIGN!               _   |\n |                                    /    |\n `---------------------------------- / ----''\n                                   _/\n','\n',char(10)),'TelnetFront.Guide',replace('@DATABASE "Telnet Frontend Door GUIDE"\n@WIDTH 80\n\n@NODE main "Telnet Frontend Who Door "\n@FONT Topaz 8\n\n                                   REbEL OF\n            ____________.____________________|  |____________.____\n         .__\\_ __   __  |   _____   __  _   __   __ _______  !  _/._.\n         |::Y   |   Y   |   Y  __   Y   |   Y    Y   ____Y   _   Y::|\n         |::|   !   |   !   |   !   |   l___|    |   !   |   |   |::|\n         ¯¯¯l____  _l_______l_______l___|   l____l_______l___l___|¯¯¯\n                \\___\\\n                                 - PRESENTS -\n\n                  Telnet Frontend Who Door For /X And AmiTCP        \n\n\n\n                  @{"[        i N T R O D U C T I O N        ]" LINK intro}\n\n                  @{"[        i N S T A L L A T I O N        ]" LINK install}\n\n                  @{"[       C O N F I G U R A T I O N       ]" LINK config}\n\n                  @{"[              U S E A G E              ]" LINK useage}\n\n                  @{"[     P R O G R A M   H I S T O R Y     ]" LINK history}\n\n                  @{"[   G R E E T S   A N D   T H A N K S   ]" LINK greets}\n\n                  @{"[ F U T U R E   D E V E L O P M E N T S ]" LINK future}\n\n                  @{"[          K N O W N   B U G S          ]" LINK bugs}\n\n                  @{"[             C R E D I T S             ]" LINK credits\n\n\n\n                            vERSiON 1.00 (24/12/96)\n\n\n------------------------------------------------------------------------------\n@ENDNODE\n\n@NODE intro "Introduction"\n\n                         [ i N T R O D U C T I O N ]\n\n\n This little AREXX (argghh.. yes that means it only runs at a decent speed\n on an 040/060 hehe) door is basically a frontend WHO door with one little\n addition. When used in conjunction with AmiTCP (ok...heres a good reason\n to dump Miami and make the effort with AmiTCP) it can determine the ip and\n host addresses of telnet callers.\n\n This little feature is suprisingly useful, and since the ip address and\n hostname are stored in environment variables its possibilities are endless.\n\n For example its very simple to echo them to the callers log from the logoff\n script, giving you a complete log of every users ip/hostname who logs onto\n a telnet node. I also use them to aid me when deciding whether or not to\n validate new users. If someone says they are from sweden and their hostname\n ends in .de you know they are really from germany.  \n\n@ENDNODE\n\n@NODE install "Installation"\n\n                         [ i N S T A L L A T I O N ]\n\n\nInstallation couldnt really be any easier. Copy all of the files from the\nBBS drawer in this archive to the same place in your BBS drawer.\n\nContents of BBS Drawer Should be:\n\n   BBS/\n      Doors/\n         TelnetFront/\n               TelnetFront.Aim\n               TelnetFront.Guide\n      Commands/\n         SysCmd/\n               Frontend.info\n\nIt doesnt require any special software, except you must be running AmiTCP\nas your tcp/ip stack if you designate any of the nodes as being telnet\n(see @{"Configuration" LINK config} for more on this) Oh and of course, /X or compatible.\n\n@ENDNODE\n\n@NODE config "Configuration"\n\n                        [ C O N F I G U R A T I O N ]\n\nFor this door to operate, it is necessary to provide information on the\nsetup of each node of your bbs. A simple modification to the program file\n(FRONT.AIM) in Doors:TelnetFront is all thats required.\n\nIt is only necessary to change one line in the code, and an understanding\nof ARexx is not required. The line in clearly marked and you should not\nchange anything else under any circumstances.\n\nAs default the line reads\n\n   nodestatus="LDDDTT"\n\nThis sets up your nodes as follows\n\n   Node 0 - local node\n   Node 1 - Dialup node (ie not a telnet node)\n   Node 2 - Dialup node \n   Node 3 - Dialup node\n   Node 4 - Telnet node\n   Node 5 - Telnet node\n\nTo change this to suit your own needs you only need change the bit in between\nthe two quote marks(") ie. the LDDDTT. Simply you replace LDDDTT with whatever\ncombination of letters that matches your bbs, with one character for each node\nstarting at 0 (leftmost character) going through all the nodes.\n\n    L = Local node\n    D = Dialup node\n    T = Telnet node\n\nSo for a bbs with one dialup line, two telnet lines and local node is 0 the\nstring would be LDTT and for a bbs with two dialup lines and three telnet\nnodes and the local node as node 5 the string would be DDTTTL.\n\n\n@ENDNODE\n\n@NODE useage "Useage"\n\n                               [ U S E A G E ]\n\nSince this program has a wide range of uses heres one or two suggestions as\nto what you can do with it.\n\nThe door will output the ip address and hostname for each telnet node to\nenvironment variables called NODExIP and NODExHOST (where x is the node).\nFor example node 2 will output variables called NODE2IP and NODE2HOST.\n\nThe NODExIP contains the ip address (the numeric address.. like 128.132.12.35)\nand the NODExHOST has the hostname (like [email removed]).\n\nIm sure you can think of many uses for these variables, personally i like to\necho them to the callerslog from the logoff script, with a line like\n\n   Echo >>BBS:NODE5/CALLERSLOG "Telnet login address:" $node5ip\n\nWhich basically adds a line at the end of each caller telling you there\ntelnet ip address.\n\n@ENDNODE\n\n@NODE history "Program History"\n\n                      [ P R O G R A M   H I S T O R Y ]\n\nYou may have seen very basic versions of this door running on my (or other\npeoples) boards, however this is the first real release.\n\n@{B}Version 1.00@{UB}\n\nFirst public release version\n\n24/12/96\n\n@ENDNODE\n\n@NODE greets "Greets and Thanks"\n\n                    [ G R E E T S   A N D   T H A N K S ]\n\n\n  I''d really like to greet everyone on the Amiga scene who knows me, but the\n  list is so huge since i went on IRC. So i just have to leave it to you to\n  judge if you get a greet or not.\n\n@ENDNODE\n\n@NODE future "Future Developments"\n\n                  [ F U T U R E   D E V E L O P M E N T S ]\n\n\nWell unless anyone comes up with suggestions for improvements or finds any\nbugs, then this is likely to be the one and only version (... theres no bugs\nhonest...)\n\n@ENDNODE\n\n@NODE bugs "Known Bugs"\n\n                           [ K N O W N   B U G S ]\n\n\nThere is currently one known bug in this door. Its a relatively minor bug\nand due to the way in which AmiTCP stores the addresses will be difficult\nif not impossible to overcome.\n\nIf a user logs onto a telnet node, and before the frontend door has had \nchance to store the ip/hostname another user logs on (ie within a matter of\na second or two) then the first users ip/hostname is likely to be shown\nas being the same as the second users. The reason for this being AmiTCP\nwill have placed the new users ip/hostname onto a stack above the old user\neffectively wiping it from our view.\n\n@ENDNODE\n\n@NODE credits "Credits"\n\n                              [ C R E D I T S ]\n\n\n  Program Design - REbEL/QTX\n\n  Program Implementation - REbEL/QTX\n\n  Output Design - NOP/STS (Great work)\n\n  Diz Design	- NOP/STS\n\n@ENDNODE\n','\n',char(10)),NULL,NULL,12162,5,0,NULL,NULL,NULL,'scan',1780048775);
INSERT INTO door_catalog VALUES('telnetd','TELNETD.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TELNETD.LHA',NULL,'XIM','telnetd.device.JAKE',NULL,NULL,NULL,'-> 000 version unregged -> 020+ versions regged I need a regged 000 version! fix it for me!',replace('TELNETD.DEVICE\n \n-> 000 version unregged\n-> 020+ versions regged\n \nI need a regged 000 version! fix it for me!\n','\n',char(10)),'New.Doc',replace('_ __ ________________________________________________________________ __ _\n                                                      ___\n    .,,,,     .---._ Oo  .::::. .::::. :::   :::    __\__\\n    ( oo)__   (¯oo) /..\ ::  :: ::  :: :::   :::    \ / Oo\o  (\(\\n   /\_  \__) /\_  \/\_,/ ::  .. ::..:: ::''   ::''    _\\`--_/ o/oO \\n   \__)_/   _\__)_/_/    :::::: :::::: ::....::.... \_ \  \  \.--''/\n   /_/_/    \ /_/_//     `::::'' ::  :: `:::::`:::::: /_/__/   /¯\ \___\n _(__)_)_,   (__)_/  .::::.                      ;::  |_|_    \_/_/\_/\\n  o    o      (__)) ,:'' `::::::::::::::::::::::::::'' (__)_)___(_(_)  ¯¯\n              ________  ____________________  __   _/\  ___ \n              \____   \/  / ___/  /_  _/    \/ /   \  \/ \/\n               \   \   \ / /__^  / / //  ^  /  \___ \    /     ___    __o \n               /_______//\___/__/ /_/ \_/\_/\_____/ /    \_   ___   _-\<,_ \n               DREAM MACHINE WorLD DHQ CenTer ©    /__/\___''97 ___ (_)/ (_)\n\n            NirVaNa  : wORLD iNNOVATION wORLD dISTRIBUTION sITE!\n       Dream Machine : wORLD iNNOVATION wORLD dISTRIBUTION sITE! \n        Cyber Dreams : wORLD iNNOVATION wORLD dISTRIBUTION sITE!\n               Exlex : wORLD iNNOVATION wORLD dISTRIBUTION sITE!\n         Wanted Team : wORLD iNNOVATION wORLD dISTRIBUTION sITE!\n\n  Node [1] +31-570-637050  Node [2] +31-570-636468  Node [3] +31-570-677702\n\n  Amiexpress V4.20 Registered On An Amiga 2000 GVP-Tekmagic 68060 32MB KS3.1\n    Pioneer Changer DRM-604X + Toshiba Cd-Rom 4 HD''s 7110MB Space Total...\n\n   2 * cREDITZ fOR mAJORS! 3 * cREDITZ fOR mAJORS fROM yOUR oWN gROUP!\n    pROVIDING yOU: Amiga ECS/AGA, PC, AmiExpress, Sex Pic, Sex Stories\n\n\n- -- ---------------------------------------------------------------- -- -\n\n','\n',char(10)),NULL,'auto-added',112677,7,0,NULL,NULL,'telnetd','scan',1780048775);
INSERT INTO door_catalog VALUES('telreg','TELREG.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TELREG.LHA','launchd','XIM','launchd',NULL,NULL,NULL,':        ___ _______  /\_ __/\         : :       / _ \\_____ \ \  Y  __)        : :      /  _  \|   |  \/  |  \          :',replace('........................................\n:        ___ _______  /\_ __/\         :\n:       / _ \\_____ \ \  Y  __)        :\n:      /  _  \|   |  \/  |  \          :\n:     /___|   \______/\ __  /          :\n:         |____\ AdVoCaTe \/           :\n:......................................:\n[ Presents TELSER 1.40                 :\n:······································:\n: Telser device with keyfile!          :\n:                                      :\n········································\n','\n',char(10)),'telser-Axsh-setup.guide',replace('@DATABASE "Axsh-setup.guide"\n\n@NODE MAIN "Axsh-setup.guide"\n\n  ---------------------------------------------------------\n		Spumoni''s "How To" Guide:\n	Setting up Axsh 1.31 for use with Telserd\n	 Written 12/27/94 By Nicholas J. Verenini\n  -----------------------------------------------------------\n\n    Copyright (c) 1994-1995, SpuSoft. No Rights reserved.\n\n@{" Legal Stuff         " Link Legal_Stuff}\n@{" Introduction        " Link Introduction}\n@{" Requirements        " Link Requirements}\n@{" What to change      " Link What_To_Change}\n@{" Common Problems     " Link Common_Problems}\n@{" Acknowledgements    " Link Acknowledgements}\n@{" Contact Information " Link Info}\n@{" Disclaimer          " Link Disclaimer}\n\n@ENDNODE\n\n@NODE Legal_Stuff "There is none!"\n\nIt reminds me of lawyers.\n\n@ENDNODE\n\n@NODE Introduction "Duh, what''s my name?"\n\nThis is, in short, a hopefully simple and straightforward guide to setting\nup telserd to use Axsh 1.31. If you don''t know what @{" Axsh " Link Axsh} is, this little essay\nwon''t help you any, so get out while you still can.\n\n@ENDNODE\n\n@NODE Requirements "What you need"\n\nIn order to sucessfully set this thing up, you will need the following:\n\no   Correctly installed TCP/IP stack (tested with Amitcp 4.0)\no   Correctly installed, hopefully registered telser package\no   Correctly installed Axsh 1.31 package\no   An IQ greater than your shoe size\n\n  ---------------------------------------------------------------------\n\nNOTE! (Or: ''In Case the Last Criteria Was Barely Met'')\n\nNotice my careful usage of the term ''correctly installed.'' This means that\nat the time of this writing, you have installed, and have complete mastery\nof, the aforementioned packages. It also follows that I will assume you,\ngentle reader, have at least above-slug intelligence.\n\n@ENDNODE\n\n@NODE What_To_change "Modify, change, or otherwise mangle"\n\nThis assumes you have the registered version of telser.device. The demo\nwill only allow one port, but you can use this section as a guide to\nsetting up the single unit for Axsh. Read on, D00D.\n\n  ---------------------------------------------------------------------\n		    Files that need modification\n\n    For demo use (unit 0 only):\n\no   Axsh\n\n    @{" Axsh:etc/rc.server<x>             " Link server}\n\n    For regged use (unlimited ports):\n\no   Axsh\n\n    @{" Axsh:etc/rc.server<x>             " Link server}\n    @{" Axsh:storage/DOSDrivers/NEWAUX<x> " Link newaux}\n\no   Telser.device\n\n    @{" Amitcp:db/telserd.conf            " Link telserd}\n    @{" Amitcp:db/telser.conf             " Link telser}\n\n@ENDNODE\n\n@NODE server "Axsh:etc/rc.server<x>"\n\nIf you have read the Axsh documentation (if you haven''t, go do it now,\ndammit) you will know that in Axsh:bin/ there is a program called\nax-server. What this program does is watch a serial device for connect\nrequests, and on those requests initialize Axsh through a device called\nNEWAUX:. In order to do this, it uses a config file, conventionally named\nhere as ''Axsh:etc/rc.server<x>,'' where <x> is the ax-server session you\nwant to run. The original file as included with the Axsh distribution is\nnamed ''Axsh:bin/rc.server,'' so this naming system is just for neatness. You\nmay name the config file whatever you so desire. If you had three of these\nconfig files, call them rc.server1, rc.server2, and rc.server3, you would\nrun ax-server once for each one, and this would give you the equivalent of\na three-line serial configuration, except each session will accept a telnet\nrequest instead of an incoming phone call.\n\nBasically, what you want to do is to change two things in the rc.server<x>\nconfig:\n\no   For the default, change all references to ''serial.device'' to\n    ''telser.device''\n\no   If you are setting up multiple rc.server<x> configs, you must also\n    replace all instances of NEWAUX: with another NEWAUX device that has a\n    different name (see section on NEWAUX for this).\n\no   Give telser.device a port to watch- in the unregged version, it will\n    only be able to watch port 0 (in which case you can ONLY use ONE\n    config file for ax-server), but the regged version can use a, uh, very\n    large number of ports (try somewhere in the billions).\n\n@{" Config file example " Link Configfile}\n\n@ENDNODE\n\n@NODE Configfile "Example config file for ax-server"\n\n;AXsh server configuration file in pasbox\n;by Pasi Ojala\n\n%bpslock:	/* lock the DTE speed (If present, %bps: has no effect) */\n19200\n%bps:		/* Default baudrate in ax-server (highest possible) *\n2400\n\n%serverpri:	/* AX-server priority *\n1\n\n%starthour:	/* server starts to monitor calls *\n25\n%stophour:	/* server goes to sleep *\n25\n\n%eventhour:	/* event time hours */\n25\n%eventmins:	/* event time minutes */\n0\n\n%eventnumber:	/* string we use for event-call */\natX4E0dt911\n%eventcommand:	/* command we execute after connection */\nAXsh:bin/net <newaux1:telser.device/10/raw/checkcd >newaux1:telser.device/10/raw/\n\n%newshell:	/* AXsh''s serial startup command in AX-server *\nnewshell >NIL: NEWAUX1:telser.device/10/shared from AXsh:etc/remote-startup\n\n%newcon:	/* startup for console(can use con: or newcon: handlers too)*/\nnewshell >NIL: con:0/0//216/AXsh/CLOSE from AXsh:etc/local-startup\n newshell >NIL: con:0/344/664/216/AXsh/CLOSE from AXsh:etc/local-startup\n\n%modem-reset:	/* modem reset command, CR not needed */\nATZ\n\n%modem-aa:	/* modem autoanswer command */\nAT&d0M0X4E0S0=1\n\n%modem-noaa:	/* modem autoanswer off command (not used) */\nATE1S0=0\n\n%ringflash:	/* DisplayBeeb() on 1=sleeping,2=waiting,3=always */\n0\n\n%device:	/* Device to monitor */\ntelser.device\n%unitnum:	/* Unit number on the device */\n10\n%handshake:	/* handshake type, "cts/rts" or "none" */\ncts/rts\n\n@ENDNODE\n\n@NODE newaux "NEWAUX:"\n\no	2.1=< users\n\nNEWAUX: setup is mercifully simple. Simply take the original mountlist\nand change the icon''s name to something else, ie. AX1: or NEWAUX1: or\nwhatever. When you mount this from WB (2.1 only) you will have an\nadditional NEWAUX: port that you can use for another ax-session. Make\nsure the file that the icon is associated with has the same name.\n\no	2.0 users\n\nPut the name of the device in as the first line in the mountlist (ie.\nNEWAUX1:)...then use the standard AmigaDOS ''mount'' command to mount it.\nThere you go.\n\n@ENDNODE\n\n@NODE telserd "Telserd.conf"\n\nThe port name you want to use for ax-server config must be in\namitcp:db/telserd.conf. A sample line for configuring port 10 follows (use\nthe existing telserd.conf as a template):\n\n#unit ring-interval max-rings	startup-command cleanup-command logfile\n#     (seconds)                 "" for none     "" for none     "" for none\n10	  2		1	""              ""              t:telserd.log\n\n@ENDNODE\n\n@NODE telser "Telser.conf"\n\nYou must also have some parameters defined for the port name you want to\nuse in amitcp:db/telser.conf. Observe:\n\n10  fraser  OpenWindow	 NOOPENWIN   LINGER   DEBUG  T:telser.log\n				     ^^^^^^\nThis is almost identical to the line already in the file, but notice that\nfor use with ax-server you MUST set LINGER on, because ax-server closes the\ndevice it uses (in this case telser.device) when it detects a caller. If\nLINGER is off that unit will be closed, and newaux: will have nowhere to\noutput, resulting in an input stream lockup. In short, LINGER off, bad. You\ncrash. Grunt.\n\nHope that was kinda clear.\n\n@ENDNODE\n\n@NODE Common_Problems "Some gotchas"\n\nHere are some common problems you may experience, and here are my utterly\nfantastic solutions:\n\nQ:	Arrgh! It doesn''t work! What should I do?\n\nA:	RTFM.\n\nThank you. :)\n\n@ENDNODE\n\n@NODE Acknowledgements "We give thee thanks, almighty PAYN...er, Telser"\n\nOf course, this document owes its existence to telser (and Axsh), without\neither of which I would be making no sense whatsoever. I also want to thank\nmy mother, for not beating me as a child, and, most of all, I want to thank\nmy agent, Bertha, without whom the world would be a much smaller place.\n\nThank you, thank you. <applause>\n\n@ENDNODE\n\n@NODE Info "Contact Information"\n\nI may be reached at:\n\[email removed]\n\nI also invite you to try out the telnet site at:\n\ntelnet nverenin.extern.ucsd.edu (sporadic)\n\n\n@ENDNODE\n\n@NODE Disclaimer "Disclaimer"\n\nI make no guarantees, implied or otherwise, about the relative usefulness\nof this documentation. I alse refuse to take responsibility if it somehow\nmanages to crash your hard drive, eat your cat, or steal your credit card\nand order me a WE 040 board. You have been warned.\n\n-Spu (Wednesday 28-Dec-94 20:49:01)\n\n@ENDNODE\n\n@NODE Axsh "What is Axsh?"\n\nAside from the fact you should know what Axsh is already, I want to briefly\ndelineate some advantages to running Axsh through a system such as Telser:\n\n1) Simple UNIX shell-like interface\n2) Has its own file protection\n3) Easily integrated into a Internet-type environment\n4) Reasonably fast\n5) Goes great with Cheez Whiz\n\n@ENDNODE\n\n\n\n','\n',char(10)),NULL,'auto-added',248154,3,0,NULL,NULL,'telreg','scan',1780048775);
INSERT INTO door_catalog VALUES('telser12','TELSER12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TELSER12.LHA','telser','XIM','TelserMon',NULL,NULL,NULL,'device file for use when logged into the Internet - it allows you to use your usual comms package to call any telnet bbs -',replace('telser.device - this is a replacement serial\ndevice file for use when logged into the \nInternet - it allows you to use your usual\ncomms package to call any telnet bbs -\nAND UPLOAD AND DOWNLOAD. works too!\n','\n',char(10)),'telser-Axsh-setup.guide',replace('@DATABASE "Axsh-setup.guide"\n\n@NODE MAIN "Axsh-setup.guide"\n\n  ---------------------------------------------------------\n		Spumoni''s "How To" Guide:\n	Setting up Axsh 1.31 for use with Telserd\n	 Written 12/27/94 By Nicholas J. Verenini\n  -----------------------------------------------------------\n\n    Copyright (c) 1994-1995, SpuSoft. No Rights reserved.\n\n@{" Legal Stuff         " Link Legal_Stuff}\n@{" Introduction        " Link Introduction}\n@{" Requirements        " Link Requirements}\n@{" What to change      " Link What_To_Change}\n@{" Common Problems     " Link Common_Problems}\n@{" Acknowledgements    " Link Acknowledgements}\n@{" Contact Information " Link Info}\n@{" Disclaimer          " Link Disclaimer}\n\n@ENDNODE\n\n@NODE Legal_Stuff "There is none!"\n\nIt reminds me of lawyers.\n\n@ENDNODE\n\n@NODE Introduction "Duh, what''s my name?"\n\nThis is, in short, a hopefully simple and straightforward guide to setting\nup telserd to use Axsh 1.31. If you don''t know what @{" Axsh " Link Axsh} is, this little essay\nwon''t help you any, so get out while you still can.\n\n@ENDNODE\n\n@NODE Requirements "What you need"\n\nIn order to sucessfully set this thing up, you will need the following:\n\no   Correctly installed TCP/IP stack (tested with Amitcp 4.0)\no   Correctly installed, hopefully registered telser package\no   Correctly installed Axsh 1.31 package\no   An IQ greater than your shoe size\n\n  ----