INSERT INTO door_catalog VALUES('tfauid11','TFAUID11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TFAUID11.LHA',NULL,'XIM','. PrEsEnTs    ____  _________    PrEsEnTs .',NULL,NULL,NULL,': _____._____/ _  \/  ___/ . \_____._____ : :-\___ |::::/  |   \  __/  |  \::::| ___/-: :  -\__|::::\__|   /  |/   .   \:::|__/-  :',replace('. PrEsEnTs    ____  _________    PrEsEnTs .\n: _____._____/ _  \/  ___/ . \_____._____ :\n:-\___ |::::/  |   \  __/  |  \::::| ___/-:\n:  -\__|::::\__|   /  |/   .   \:::|__/-  :\n·!911-\|:::::::|  /   |\   |   /:::|/-    ·\n       `¯¯¯¯¯¯¯¯\/¯¯\/¯¯¯\/¯¯¯¯¯¯¯¯''       \nUser Information Deluxe V1.1. - /X 2.x door \n:.:.:.:.:.:.:.:.:.:.:.:.:.:.:.:.:.:.:.:.:.:\n33.6 DigITal-X Prd/NirVana Dist Site! 33.6\n','\n',char(10)),'2Nodez.TXT',replace('_ __ ________________________________________________________________ __ _\n                                                      ___\n    .,,,,     .---._ Oo  .::::. .::::. :::   :::    __\__\\n    ( oo)__   (¯oo) /..\ ::  :: ::  :: :::   :::    \ / Oo\o  (\(\\n   /\_  \__) /\_  \/\_,/ ::  .. ::..:: ::''   ::''    _\\`--_/ o/oO \\n   \__)_/   _\__)_/_/    :::::: :::::: ::....::.... \_ \  \  \.--''/\n   /_/_/    \ /_/_//     `::::'' ::  :: `:::::`:::::: /_/__/   /¯\ \___\n _(__)_)_,   (__)_/  .::::.                      ;::  |_|_    \_/_/\_/\\n  o    o      (__)) ,:'' `::::::::::::::::::::::::::'' (__)_)___(_(_)  ¯¯\n              ________  ____________________  __   _/\  ___ \n              \____   \/  / ___/  /_  _/    \/ /   \  \/ \/\n               \   \   \ / /__^  / / //  ^  /  \___ \    /     ___    __o \n               /_______//\___/__/ /_/ \_/\_/\_____/ /    \_   ___   _-\<,_ \n               DREAM MACHINE WorLD DHQ CenTer ©    /__/\___''97 ___ (_)/ (_)\n\n            PaRaDiSe : wORLD iNNOVATION wORLD dISTRIBUTION sITE!\n            NirVaNa  : wORLD iNNOVATION wORLD dISTRIBUTION sITE!\n       Dream Machine : wORLD iNNOVATION wORLD dISTRIBUTION sITE!\n\n  Node [1] +31-570-637050  Node [2] +31-570-636468  Node [3] +31-570-677702\n\n  Amiexpress V4.20 Registered On An Amiga 2000 GVP-Tekmagic 68060 32MB KS3.1\n    Pioneer Changer DRM-604X + Toshiba Cd-Rom 4 HD''s 7110MB Space Total...\n\n   2 * cREDITZ fOR mAJORS! 3 * cREDITZ fOR mAJORS fROM yOUR oWN gROUP!\n    pROVIDING yOU: Amiga ECS/AGA, PC, AmiExpress, Sex Pic, Sex Stories\n\n          ---»> nO nEW uSER pASSWORD aND/oR sYSTEM pASSWORD! <«---\n\n- -- ---------------------------------------------------------------- -- -\n\n','\n',char(10)),NULL,NULL,15040,6,0,NULL,NULL,NULL,'scan',1780048775);
INSERT INTO door_catalog VALUES('tfa_rfw','TFA_RFW.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TFA_RFW.LHA','rfw','XIM','rfw',NULL,NULL,'TFA','33.6 DigITal-X Prd/NirVana Dist Site! 33.6',replace('Remote File Window (RFW)\n33.6 DigITal-X Prd/NirVana Dist Site! 33.6\n','\n',char(10)),'RFW.DOC',replace('                            Remote File Window (RFW)\n\n          Written by Price of T.F.A. in assembly (Asm-One V1.09) \n\n\n==============================================================================\n                                Installation:\n\nThis utility is stand alone. This means it has no need for hundreds of config\nfiles (hint hint). The only thing it needs is for you to put it in your\ncustomcommands file.\n\n---------------------------< cut here\nRFW       XM010DOORS:rfw\n---------------------------< cut here\n\n\n==============================================================================\n                               Specification:\n\nRFW will run on any amiga (tested on A500/A500+/A2000 so i \n			   don''t know about the A3000 or A1000)\n\nRFW will not take up much memory (about 30 Kb)\n\nRFW is multiuser. So multi node BBS''s shouldn''t have any problems\n\nRFW will automaticly detect the maximum lines on a screen for an user\n\nRFW will automaticly detect which dirlist is your upload dir and use that one\n\nRFW can handle upto 1024 files.\n\nRFW will show the directory starting with the latest warez and continueing\n    with the older warez\n\nRFW is key controlled.\n\n\n============================================================================\n\n                               How to use:\n\nThese are the key ''currently'' availeble in RFW :\n\n1	=	Jump to end of list\n\n2	=	Show next file\n\n3	=	Show next page\n\n7	=	Jump to top of list\n\n8	=	Show previous file\n\n9	=	Show previous page\n\nT	=	Tag file(s)\n		Just enter the letters infront of the file. Multiple\n		file selections are allowed\n\nJ	=	Jump to date\n		Just enter the date (as known in the ami-express N command)\n\nQ	=	End RFW.\n\n?	=	Help pages for the user\n\n\nWhen exiting from RFW the programm will check if any files are tagged. \nIf no taggs were found it return to the system.\n\nWhen there are taggs found the user will be asked if he wants to start\ndownloading rigth away.\n\nIf the user responds with (N)o he will be returned to the system. If the\nuser responds with (Y)es he will be returned to the system in download\nmode.\n\n===========================================================================\n\nRFW was originaly written for Remote Acces BBS (TM) for use on the PC.\n\nSince ami-express started with doors it''s become much more powerfull. Now it''s\nupto us to do something with that power !!!.\n\n\n===========================================================================\n\nMessage to Johsep Hodge :\n\nIf possible i would like the following function build in for door use :\n\n1.)	Check if ANSI = ON or OFF 	(shouldn''t be too hard)\n\n2.)	Turn ANSI ON or OFF\n\nIf you want to contact me just call Downtown (Dutch Ami-x distributer) and\nleave a message to PRICE\n\n(We had some contact before)\n\n===========================================================================\n\nMessage to all:\n\nContact T.F.A. \n\nWrite to :    	T.F.A.\n		P.O. Box 2249\n		1200 CE  HILVERSUM\n		Holland\n\nor call :	Total Confusion\n		+31-(0)35-855918\n\n\n','\n',char(10)),NULL,'auto-added',15318,6,0,NULL,NULL,'tfa_rfw','scan',1780048775);
INSERT INTO door_catalog VALUES('tff_sxv1','TFF-SXV1.LZX','~/Code/amiexpress_doors/Archives/AmiExpress/TFF-SXV1.LZX',NULL,'XIM','ACP',NULL,NULL,'TFF',NULL,NULL,NULL,NULL,NULL,'auto-added',437495,0,0,NULL,NULL,'tff_sxv1','scan',1780048775);
INSERT INTO door_catalog VALUES('tfp_td62','TFP-TD62.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TFP-TD62.LHA','TXTDiZ','XIM','LE-window5.exe',NULL,NULL,'TFP','___ ______  ______  __________    ¬\__ /.      .\      ____) |  ______/ _//        \\_      |   :    |',replace('     __ ______________________________\n   ___ ______  ______  __________    ¬\__\n         /.      .\      ____) |  ______/ \n       _//        \\_      |   :    |\n       \________   ./______|________|\n ·========TNT!l____/======================·\n .-----------[ PRESENTS 2DAY: ]-----------.\n |----------------------------------------|\n | TXTDiZ Vø.62 - RELEASE DATE : 1ø-12-95 |\n |  XTRACTS / ADDS FiLE_iD''s 2 TEXTFiLES  |\n | FAAAST!(500K/11 SECS) - SMAAALL!(3,1K) |\n |----------------------------------------|\n `---> TRACKERS - DAS BESTE AM NORDEN <---''\n','\n',char(10)),'TXTDiZ.DOC',replace('\n  ·========================= [ BEGIN OF FILE ] =========================·\n                     __ _____________________________\n                   ___ ______  ______  _________    ¬\__\n                         /.      .\     ____) |  ______/ \n                       _//        \\_     |   :    |\n                       \________   ./_____|________|\n                 ·========TNT!l____/=====================·\n\n    .-----------------------[ PRESENTS 2DAY: ]------------------------.\n    |-----------------------------------------------------------------|\n    | - TXTDiZ Vø.62 - FAAAAST! - SMAAALL!(3,1K!) - JUST BRiLLiANT! - |\n    |-----------------------------------------------------------------|\n    `-----------------------------------------------------------------''\n    ================ ALL CøDiNG DøNE BY: tENtAClE^tFP! ================\n\n  -----------------------------------------------------------------------\n\n      Yoho! Thought - "THE TRACKERS ARE DEAD!" ?? Well - FAILED !!!!!\n\n  The new member of the Trackers ( me - tENtAClE ) is gonna kick ya asses\n  with this new tool - TXTDiZ! And there are still sum more toolz 2 come!\n\n  -----------------------------------------------------------------------\n\n  OK, lets begin ...\n\n  This creepy tool is - as said above - like the good, old "TXTEXTRACT" -\n  but it''s much faster and smaller ... You can extract FILE_ID''s / add\n  a FILE_ID or something else !\n\n   .------------------------------------------------------------------.\n   |SMALL? YEZ: 3,1 KBYTE OF PURE HARDCORE CODING SESSIONS WITHIN IT!!|\n   |FAST?? YEZ: IT CHECKS 500K OF TEXT IN ABOUT 11 SECS FOR A FILE_ID!|\n   `==================================================================''\n\n  Note: TXTDiZ was coded, compiled and tested on a A12øø / ø3ø with\n        6 MB RAM, but I think it should be fast enough on other machines \n        like a normal A12øø, too.\n\n  -----------------------------------------------------------------------\n  === WARNING! - WARNING! - WARNING! - WARNING! - WARNING! - WARNING! ===\n\n  This tool needs enough ram 2 load the textfile into your ramdisk - so\n  be careful if you only have 2 Megs of ram! If you run a bbs with diz\n  configuration - B CAREFUL! I haven''t tested what happens when my A12øø\n  got out of ram with diz program ... but i''ll build in a special cache\n  function for those who don''t have much ram (Hey, Bongmaster - thx for\n  da bugtip!)\n\n  === WARNING! - WARNING! - WARNING! - WARNING! - WARNING! - WARNING! ===\n  -----------------------------------------------------------------------\n\n  - USAGE : TXTDiZ E/A [SOURCEPATH+FiLENAME] [DESTINATIONPATH+FiLENAME]\n\n  [E]: Extracts a FILE_ID from the sourcefile and writes it into the\n       destinationfile ... cøøl, huh? ;)\n\n  .--------------------------------------------------------------------.\n  |SOURCE : TXTFiLE  ->  DESTiNATiON : FiLE_iD (e.g. RAM:T/FiLE_iD.DIZ)|\n  `--------------------------------------------------------------------''\n\n  [A]: Adds a text to the front of another text - this time the source\n       is the FILE_ID or the text and the text where ya want it 2 b\n       placed is the destination (Sorry for that - I had no other chance,\n       but I''ve got diz one fixed søøn !)\n\n  .--------------------------------------------------------------------.\n  |SOURCE : FiLE_iD/TXT  ->  DESTiNATiON : TEXT WHERE SOURCE iZ PLACED |\n  `--------------------------------------------------------------------''\n\n          [SOURCEPATH+FiLENAME] / DESTINATIONPATH+FiLENAME] :\n\n  GOD, DAMNED! UHHM ... man , I just can''t remember what these mean! ;)\n\n  -----------------------------------------------------------------------\n\n  Well - why the heck this cute, little fuckin'' tool? I saw how big and\n  fuckin'' slow TXTEXTRACT was. Guess what? It can b faster and smaller!\n\n  OK - that''s it for now - but b sure - you''ll c some more toolz of TNT!\n\n  If you have any questionz - You can reach me in the following BBS''es:\n\n  ·=====================================================================·\n   LOST CARRiER          -  LEGO GHQ           -     +49 - iNViTED-ONLY!\n   STRANGE BREW          -  TRACKERS WHQ       -     +49 - iNViTED-ONLY!\n   OUT OF CONTROL BBS    -  TRACKERS GHQ       -     +49 - 421 - 5769126\n  ·=====================================================================·\n\n  -----------------------------------------------------------------------\n\n  Now a little history report [boring, I know, but did I say that YOU have\n  2 read it?]\n\n  Vø.1 - Vø.3 : Just these halfworkin'' testversions ...\n\n  Vø.4        : First working version, only was extracting FiLE_iD''s into\n                ram:t/\n\n  Vø.5        : Built in a function for adding a FiLE_iD 2 the front of\n                a text\n\n  Vø.55       : First pre-release  -  my first mistake!\n\n  Vø.60       : 2 BiiiiiiiiiiiiG bugfixes:\n                I .) The @END_FILE_ID was written into the destination-\n                    file ... haaarrrrm !\n                II.) An even BIGGER mistake : I''ve only tested TXTDiZ on\n                     Files containing a FiLE_iD. If there was no FiLE_iD\n                     in it - GOODBYE MY FRiEND!\n\n  Vø.62       : Second pre-release - with some optimized code\n\n  ·========================= [ END OF FILE! ] ==========================·\n\n','\n',char(10)),NULL,'auto-added',9420,3,0,NULL,NULL,'tfp_td62','scan',1780048775);
INSERT INTO door_catalog VALUES('thc_stat','THC-STAT.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/THC-STAT.LHA','thcstats11','XIM','____:  ___:______:______:______:_____:__',NULL,NULL,'THC','\   |  \  ___/\  ___/\  ___/\ __ \_____ \ /  _|__/_ _|/\/ |_  \/  _|/\/  |  \  |/  \ /        / |   \  |   \  |   \  |   \      \',replace(' ____:  ___:______:______:______:_____:__\n \   |  \  ___/\  ___/\  ___/\ __ \_____ \\n /  _|__/_ _|/\/ |_  \/  _|/\/  |  \  |/  \\n/        / |   \  |   \  |   \  |   \      \\n\____\  /_______\______\______\_|    \_____/\n      \/    /X )-sIGN rELEASED: |____/sD!\n»------------------------------------------«\n  tHC-sTATS, a /X tOOL tO sEE yoUR sTATs\ncODED by: pLL/lEGEND dESIGN bY: tHC/[L]eGEND\n»------------------------------------------«\n','\n',char(10)),'thcstats11.doc',replace('$VER: THCSTATS V1.1 - © PLL Developments 1994 [L] /X )-sIGN\n\n\nNAME\n     THCStats V1.1 - Requires V37 and /X V3.9 as well as aedoor.library\n     in your libs: directory.\n\nSYNOPSIS\n    Shows /X Statistics. THCStats11 is a XIM DOOR.\n\nFUNCTION\n    Show Statistics of Sysop and User.\n    To use, copy THCStats11 in your DOORS: directory, and make an icon in\n    BBS:Commands/BBSCmd with the tooltypes:\n\n    LOCATION=BBS:DOORS/THCStats11\n    MULTINODE=<YES|NO>\n    ACCESS=<num>\n    TYPE=XIM\n    STACK=<num>\n    PASSWORD=<string>\n\n    An example is included in this release.\n\nINPUTS\n    None. Just type the name of the icon in BBS:Commands/BBSCmd.\n\nRESULTS\n    Various statistics about user and sysop.\n\nNOTES\n    Should work on all /X versions (Tough I''m not sure).\n\nSEE ALSO\n    "I haven''t lost my mind -- it''s backed up on tape somewhere."\n\nACKNOWLEDGEMENTS\n    Thx must go to: THC for the dESIGN, CrewOne and OverLord for\n    bug reports and beta-testing...\n\nREVISION:\n    V1.0 - 10 Jul 1994 - Initial release.\n    V1.1 - 15 Jul 1994 - Changes in design.\n                       - New options rATIO, rATIOTYPE, cURRENT cONFERENCE\n                         cONFERENCE aCCESS, sYSOP sTATUS.\n                       - Displays eNcRyPtEd Message in password.\n                       - optimized code.\n    V1.1b- 17 Jul 1994 - Bug Fix: UpLoad Bytes=Download Bytes.\n    V1.1c- 17 Jul 1994 - Bug Fix: Ratio = 3:1 instead of 1:3.\n\nBUGS\n    None known.\n\n                              cONTACT uS aT:\n\n                     ·(-- oNE oF eUROPES fASTEST --)·\n                   ___\n    .  /\  /\  ____|  \_____________________  _______________ ________\n   _:_// \/  \/~  ||   \_   _______   .__/__)/~        /~    \|.    _/__:_\n    |/        \__ `'' ___/_____  \/   .||~  .|    /____/   |   \|    |___|\n   _/    \/   \\|    |_/     |  \\_  |||   ||   / ~  \    _   \\    |   \_\n   \_____||     \____|\      _____/___||____|___     \\___|     \________/\n   -|-----|______/-----\_____/----Stz!---------\_______/--|______/------|-\n    |     _________________    _____  __________________/\___________  .|\n    |     \_______  \    _/   /~    \/~         /~ ____   /~   _____/  ||\n   _|______|.  __/   \   |___/   |   \    /____/  __/_\ //______   \____|\n    :      ||  \______)  |~  \_  _   \\_ / ~  \_       \/\_    /   \\_  .\n    .      |     | |__________/  |_____/_______/__________/__________/\n -:--------|_____|--------\______|---------------------------------------:-\n ___________________________________________________________________________\n        mAJOR gROUP uPLOADS 3* cREDITZ ««»»  mAJOR uPLOADS 2* cREDITZ      \n                oN-lINE sINCE: fEB''92, 68030/68882 40 mHZ   \n                           nO NUP, nO sYSTEM PW\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n ___________________________________________________________________________\n             nODE 1.......   +31-(0)10-477-9507  (dUAL 21k6)\n             nODE 2.......   +31-(0)10-477-4218  (dUAL 14k4)\n             nODE 3.......   +31-(0)10-477-2519  (dUAL 21k6)\n             nODE 4.......   +31-(0)10-477-2985  (dUAL 21k6)\n ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n   aMIGA/sNES/sEGA/pC                                 aMIGA/sNES/sEGA/pC\n -:--------------------[L]eGeND WoRLD HeaDQuaRTeRS-----------------------:-\n\n','\n',char(10)),'{"LOCATION":"BBS:DOORS/THCStats11","ACCESS":"<num>","TYPE":"XIM","STACK":"<num>"}',NULL,13454,2,0,NULL,NULL,'thc_stat_thcstats11','scan',1780048775);
INSERT INTO door_catalog VALUES('thcc227r','THCC227R.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/THCC227R.LHA','Thc-Chatter','XIM','THC-CHATTER','2.00',NULL,NULL,'A multinode/splitscreen /X chatter XIM door. Chat with up to 9 nodes at a time! Ansi color supported.',replace('[L]egend presents: THC-CHATTER V2.00 Release\nA multinode/splitscreen /X chatter XIM door.\nChat with up to 9 nodes at a time!\nAnsi color supported.\nThe best chatter available for /X & S-Xpress\nCoded by: CREW ONE / [L]egend.\nDesign by: THC / [L]egend\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 19:23:46  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',11233,1,0,NULL,NULL,'mth_tc23','scan',1780048775);
INSERT INTO door_catalog VALUES('thewall','THEWALL.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/THEWALL.LHA',NULL,'XIM','The Wall - AmiExpress Version written',NULL,'/<ool',NULL,'by /<ool Falco 33.6 DigITal-X Prd/NirVana Dist Site! 33.6',replace('The Wall - AmiExpress Version written \n         by /<ool Falco\n33.6 DigITal-X Prd/NirVana Dist Site! 33.6\n','\n',char(10)),'TheWall.doc',replace('\n    The Wall - AmiExpress Version written by /<ool Falco\n    ----------------------------------------------------\n\n      Written in Arexx by /<ool Faclo. Well I was borred by seeing\nsome of the wall doors written for the amiexpress.. All of them, or\nlet say most of them were lame ones, (sorry no offend to anyone),\nin my door I have only 10 inputs, it deletes the top line (always),\nand adds new wall line to the end.. Simple.. nothing more to say.\nthe thewall.text will never grow to big, it will be always 10 lines\nlong.. whatever...\n\n      This is Shareware.  No charge may be made for this program\nwithout the written consent of it''s author.  This is also released\nAS-IS.  I tested this program quite a bit and never had any problem\nwith it so I do not expect any for you, but I am not responsible for\nany grief this program may cause you or your system.\n \n      Please do not alter any of the files in this archive.  You may\nedit, experimnet, or whatever on your personal system, but please\ndo not redistribute your altered version under my name. Or even do not\nremove my name from it. Only lamers do that..\n \n \nContents:\n          TheWall.rexx\n          TheWall.doc\n          TheWall.txt\n\nSetup\n-----\n \n       VERY SIMPLE!  Copy the main program to your Doors:TheWall.\nIn the Customcommands add something like this:\n\nWall      RM010doors:TheWall/TheWall.Rexx\n\nor if you want it to be run after user logs in to the system, you have\nto either call me, or support bbs and ask how to do it... If you are\nregistered user, the info will be given out to you but if you aren''t\nregistered, then fuck off.. $70 bucks is not that bad and if you use\nAE you should register. Help AE to be the finest BBS progy out there.\n\nNow Greets and thanx.\n  Well I just want to thank Bytemaster, Buldog, and Nameless for their\n    help and their C source codes, they are helpfull guys.\n  Hi to all the sysop friends around the globe.\n  Hi to my best friends in the scene\n  Giap Happy Birthday...\n \n       Anyway, HAVE FUN with this!  I am converting a couple Arexx door \ngames as well as writing some more of my own currently.  Call my BBS\nto get the latest releases!!\n \n  \n                              Trash City BBS\n                              (718) 318-8315\n\n                               /<ool Falco\n                                  Sysop\n','\n',char(10)),NULL,NULL,6098,5,0,NULL,NULL,NULL,'scan',1780048775);
INSERT INTO door_catalog VALUES('thr_d100','THR-D100.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/THR-D100.LHA',NULL,'XIM','Deletefiles',NULL,'Therion','THR','|  Deletefiles v1.0 developed by Therion   | |This door lets you Delete files within /X | |   Choose between Automatic or Manually   |',replace('+------------------------------------------+\n|  Deletefiles v1.0 developed by Therion   |\n|This door lets you Delete files within /X |\n|   Choose between Automatic or Manually   |\n|                                          |\n|   Like Newfiles but you delete or move   |\n|    files instead of downloading them     |\n|                                          |\n|  All code & dezign by fanta of Therion   |\n`------------------------------------------''','\n',char(10)),'Deletefiles.doc',replace('\012                              Deletefiles 1.0\012                       by fanta of JoyRide ^ Therion\012\012\012\012                              This is another\012\012                                    :::::::::::::::::::::::::::::::::::::::::\012:::::::::: ::::   :::: :::::::: ::::     :::  :::          ::      ::::    ::\012:::::::::: ::::   :::: :::::::: ::::      :    :            :        ::    ::\012   ::::    ::::   :::: ::::     :::::::   :    :    ::::    :        ::    ::\012   ::::    ::::::::::: ::::::   ::::      :    :    ::::    :    :   ::    ::\012   ::::    ::::::::::: ::::::   ::::    :::    :    ::::    :    ::   :    ::\012   ::::    ::::   :::: ::::     :::: ::  ::    :    ::::    :    ::        ::\012   ::::    ::::   :::: :::::::: :::: :::  :    :            :    ::        ::\012   ::::    ::::   :::: :::::::: :::: :::  ::  :::          ::    ::::      ::\012                                    :::::::::::::::::::::::::::::::::::::::::\012\012                                 Production\012\012                              What does it do?\012\012This door deletes file from a directory and changes in dirn that you\012have deleted the file. You can choose between a semiautomatic mode where\012you answer questions (ex [D]elete [M]ove or [S]kip file?). Or an automatic\012mode where it deletes from one date to another.\012\012\012                                    Why?\012\012Coz I needed one and I couldn''t find any door that came up to my special\012demands. Of course I made it in C to accomplish some speed.\012\012\012                                 Disclaimer\012\012I don''t take any responsibility for any damage this door make on your\012computer hardware or software. It has been fully tested so it shouldn''t\012give ya any problems. Remember that this door deletes files so test it\012with care until you now exactly how it works.\012\012\012                                Installation\012\012-Copy the file BBS/Doors/Deletefiles/Deletefiles to Doors:Deletefiles/ (or\012 wherever you keep your doors)\012\012\012                                  /X 2.xx\012\012-Modify your custom-commands and add the following line:\012\012*Delete   XM2550Doors:Deletefiles/Deletefiles\012\012^         ^     ^\012|         |     |_ Or wherever you put Deletefiles.\012|         |\012|         |___ Notice the "X" Deletefiles is an XIM door!\012|\012|______ The name to run.\012\012                                  /X 3.xx\012\012-Copy the icon BBS/Commands/BBsCmd/Delete.info to BBS/Commands/BBsCmd/ or\012 BBS/Commands/SysCmd/ if u don''t want that "Deletefiles" can be chosen\012 from the prompt.\012\012\012                                 Tooltypes\012\012-----------------------------------------+\012DIR_PATH=bbs:conf1.elite/dir1            }----+\012-----------------------------------------+    |\012This tooltype must have the path to the       |\012file containing the filelist.              <--+\012\012-----------------------------------------+\012UPLOAD_PATH=bbs:conf1.elite/upload       }----+\012-----------------------------------------+    |\012This tooltype must have the path to the       |\012directory where the files in the filelist  <--+\012are defined.\012\012------------------------------------------+\012MOVE_PATH=work:temp                       }----+\012------------------------------------------+    |\012This tooltype must have the path to the        |\012directory where the files will be moved.    <--+\012\012It''s very important that you get these Tooltypes right. Deletefiles 1.0 is\012dezigned to delete files!\012\012\012                        Take a walk on the wild side\012\012The first choice!\012-----------------\012\012-------------------( Deletefiles 1.0 produced by fanta of JoyRide ^ Therion )---\012\012Delete files [M]anually, [A]utomatic or [Q]uit:?>\012              ^           ^              ^\012              |           |              |\012              |           |              +--- Quit this door!\012              |           |\012              |           +--- Deletes files from date to date\012              |\012              +--- Choose this if ya want some control over the deletion\012\012\012\012Manually is chosen!\012--------------------\012\012Last Deletion date (MM-DD-YY):?> 05-15-94   <--- Last date to delete\012\012THR-LC10.LHA P  35677  05-15-94  +------------------------------------------+\012                                 |  LastCallers v1.0 developed by Therion   |\012                                 | This is a very configurable door that    |\012                                 | creates a lastcallerstextfile.           |\012                                 |- You decides how i should look.          |\012                                 |- Almost everything is configurable.      |\012                                 |- It''s fast.                              |\012                                 |- Made by fanta^Static^Zorlac.            |\012                                 `------------------------------------------''\012Make your choice [D]elete, [M]ove, [S]kip file or [Q]uit:?>\012                  ^         ^       ^              ^\012                  |         |       |              |\012                  |         |       |              +--- Quits the door\012                  |         |       |\012                  |         |       +--- Skipps this file\012                  |         |\012                  |         +--- Move the file to specified directory\012                  |\012                  +--- Delete file!\012\012When you choose [D]elete or [M]ove the door will change dir file... and the\012output will look like this!\012\012THR-LC10.LHA D DELETED 05-15-94  +------------------------------------------+\012                                 |  LastCallers v1.0 developed by Therion   |\012                                 | This is a very configurable door that    |\012                                 | creates a lastcallerstextfile.           |\012                                 |- You decides how i should look.          |\012                                 |- Almost everything is configurable.      |\012                                 |- It''s fast.                              |\012                                 |- Made by fanta^Static^Zorlac.            |\012                                 `------------------------------------------''\012\012Automatic is choosen!\012---------------------\012\012Delete files [M]anually, [A]utomatic or [Q]uit:?> Automatic!\012First Deletion date (MM-DD-YY):?> 01-01-94  <--- Delete from\012Last  Deletion date (MM-DD-YY):?> 05-15-94  <--- Delete to\012Do you want to continue  [y/N]:?> Yeah!     <--- Last chance to stop!\012\012Deleting: work:test/upload/THR-LC10.LHA\012Deleting: work:test/upload/THR-LHAP.LHA\012Deleting: work:test/upload/THR-LN11.LHA\012\012 ^\012 |\012 +--- All files from 01-01-94 to 05-15-94 is automaticly deleted\012\012\012                               Files included\012\012               Filename                             Org. Size\012\012       BBS/Commands/BBsCmd/Delete.info                 538\012\012       BBS/Doors/Deletefiles/Deletefiles             19164\012\012       BBS/Doors/Deletefiles/Deletefiles.Doc          8509\012\012\012                                 Greeting''s\012\012Ju/\n     ---> When are your next Ascii coll comming?\012Damien    ---> I love your mercedes!\012Sandman   ---> Still going strong?\012Guardian  ---> Thanx for Betatesting! Hope ya like it finished!\012Aquarius  ---> Your doors are best!\012Kid Curry ---> When is your first door coming up?\012Cybertron ---> Sorry about your elitearea ;)\012\012\012\012                 AND OFCOZE ALL THE ONES I HAVE FORGOTTEN!\012\012                              Special Greeting\012\012Static    ---> Thanx for all your support.\012\012\012\012\012 To provent any backdoors d¡al...    ..to get the orginal & latest version.\012\012\012\012  __________  ___________ ____________\012  \_____  _/  \__  _  __/ \__  |    _/\012   ___|    \  /    |    \  /   ¦     \  +¢6(°)³²²/¹9°97\012  /   |     \/     |     \/    :      \_________________ _ _  _    _\012 /    ¦      \     ¦      \_______     \\012/     :       \    :       \/           \     Sysop¹:fanta\012\             /            /            /     Sysop²:Static\012 \___________/____________/    ________/      Sysop³:Mooney\012        |                 \_____|             Sysop4:Marshal Law\012        |        14400         _________  _______ _________ _____________\012        |     DualStandard     \___   _ \ \___   |\______  \\_____  ____/\012        ¦                        /    |  \/      |  /  |    \  /    ___|\012        :  Kicking with /X ³.X  /     ___/__     | /   |     \/     |\012        ·                      /            \_   |/    ¦      \     l____\012        .    ·¹·Dayz warez    /     \        /   |     :       \         |\012              Therion WHQ     \      \      /    |     ·       /         |\012        . Online Door Ordering \______\    /_____|____________/__________|\012                                       \__/j\012\012\012\012\012\012[EOF]','\012',char(10)),NULL,'auto-added',20956,3,0,NULL,NULL,'thr_d100','scan',1780048775);
INSERT INTO door_catalog VALUES('thr_lc10','THR-LC10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/THR-LC10.LHA','Lastcaller','XIM','Lastcaller',NULL,'Therion','THR','|  LastCallers v1.0 developed by Therion   | | This is a very configurable door that    | | creates a lastcallerstextfile.           |',replace('+------------------------------------------+\n|  LastCallers v1.0 developed by Therion   |\n| This is a very configurable door that    |\n| creates a lastcallerstextfile.           |\n|- You decides how i should look.          |\n|- Almost everything is configurable.      |\n|- It''s fast.                              |\n|- Made by fanta^Static^Zorlac.            |\n`------------------------------------------''\n','\n',char(10)),'Lastcaller.doc',replace('\n                               Lastcaller v1.0\n                        by fanta^Zorlac^Static/aFl\n\n                      » Another The®¡øN Production «\n\n\n                                    Why?\n\nThis is our way to make an easy to user lastcallersbull who is easy to\nconfigure and YOU determines the look. Of course we made it in C to\naccomplish some speed.\n\n\n                                 Disclaimer\n\nWe don''t take any responsibility for any damage this door make on your\ncomputer hardware or software. It has been fully tested so it shouldn''t\ngive ya any problems.\n\n\n                                Installation\n\nJust put:\n\n-=====================================- <-- CUT HERE\nBBS:Doors/Lastcallers/lastcallers\n-=====================================- <-- CUT HERE\n\nin your logoff.bat file. Everything is configured in the icon so you just\nhave to run the program.\n\n                               Configuration\n\nCALLERSLOG=<path:callerslog>   <-- path & name to callerslog\nOUTTEXT=<path:file>            <-- path & name to textfile to create\nHEADERTXT=<path:file>          <-- path & name of text which should be displayed on the top\nBOTTOMTXT=<path:file>          <-- paht & name of text which should be displayed on the bottom\nUSERS=<number>                 <-- number of users that should be in list\nCLS                            <-- ~ ~f will be added on the top of the outputfile\nDATAFILE=<path:file>           <-- path & name of datafile. The door will create this file\n                                   and put the vital data in it.\nSIGN1=<sign>\nSIGN2=<sign>\nSIGN3=<sign>                   <---+ This is a character that are put in\nSIGN4=<sign>                       | output string.\nSIGN5=<sign>                       |\nSIGN6=<sign>                       |\n                                   |\n                                   |\n\n| Zorlac         | -*- tHERIOn -*-      | 00:04:37 |          0 |      43710 |\n^                ^                      ^          ^            ^            ^\n|- sign1         |-sign2                |- sign3   |- sign4     |- sign5     |- sign6\n\n\n                            For multinode-users\n\nJust put the path and name of the datafile to the same. Then the door will\ncreate a textfile from the same datafile and all nodes will be covered.\nIf you just want a lastcallerstextfile for every node just name different\nnames of the datafile.\n\n\n                               Exampel output\n\n    _/\_  _/\___   _/\_/\_____/\____/\____/\_  _/\_  _/\_____/\__   _/\_\n    \__ | \____ \_/ ____  __/\____ \____ \__ | \__ | \_  _______ \_/ __/\n     |o |__|o_j \____ \|o | .:|o |__jo_j  |o |__|o |__jo __j_o ! _)___ \\n   .:|¡ |  |¡\_  |o !  \¡ |:::|¡ |  |¡\_  |¡ |  |¡ |  |¡ |  |¡ _  |o !  \:.\n· .::l___  |__|  |___  /  |:::l___  |__|  |___  |___  |___  |__|  |___  /::. ·\n¡~~~~~~~l__j~~l__j~~l_/l__j~~~~~~l__j~~l__j~~l__j~~l__j~~l__j~~l__j~~l_/X\~~~¡\n`----------------.----------------------.----------.------------.------------''\n: hANDLe         | gROUp/lOCATIOn       | tIMe oN  | dL (BYTEZ) | uL (BYTEZ) :\n¦ - -------------+----------------------+----------+------------+------------¦\n| alesis         | /independent/        | 00:05:37 |     197855 |     407529 |\n| Zorlac         | -*- tHERIOn -*-      | 00:04:37 |          0 |      43710 |\n| Zorlac         | -*- tHERIOn -*-      | 00:15:27 |      28892 |          0 |\n| Zorlac         | -*- tHERIOn -*-      | 00:09:08 |     294750 |          0 |\n| Zorlac         | -*- tHERIOn -*-      | 00:11:15 |          0 |     350505 |\n| Tweed          | Bengtsfors           | 00:01:09 |          0 |          0 |\n| BoZ            | (%$»)  NEMøL  («$%)  | 00:04:32 |          0 |          0 |\n| Static/Afl     | -*- aLPHa fL¡GHt -*- | 00:05:11 |      28153 |          0 |\n| Zorlac         | -*- tHERIOn -*-      | 00:04:35 |          0 |     213246 |\n| Zorlac         | -*- tHERIOn -*-      | 00:04:09 |          0 |          0 |\n| Zorlac         | -*- tHERIOn -*-      | 00:07:01 |     503261 |          0 |\n| Static/Afl     | -*- aLPHa fL¡GHt -*- | 00:10:12 |          0 |      51461 |\n| Big Boss       | -=( ANATHEMA )=-     | 00:18:13 |          0 |    1465853 |\n| Static/Afl     | -*- aLPHa fL¡GHt -*- | 00:08:20 |          0 |     537116 |\n| Static/Afl     | -*- aLPHa fL¡GHt -*- | 00:01:36 |          0 |          0 |\n`----------------^----------------------^----------^------------^------------''\n\n\n                            Main Files included\n\n            Filename                                  Org. Size\n\n            BBS/Doors/lastcaller/lastcaller               18964\n\n            BBS/Doors/lastcaller/lastcaller.030           18956\n\n            BBS/Doors/lastcaller/lastcaller.040           18956\n\n            BBS/Doors/lastcaller/lastcaller.Doc            6016\n\n\n\n\n                                 Greating''s\n\n                          To all who deserves it.\n\n\n To provent any backdoors d¡al...    ..to get the orginal & latest version.\n\n\n\n  __________  ___________ ____________\n  \_____  _/  \__  _  __/ \__  |    _/\n   ___|    \  /    |    \  /   ¦     \  +¢6(°)³²²/¹9°97\n  /   |     \/     |     \/    :      \_________________ _ _  _    _\n /    ¦      \     ¦      \_______     \\n/     :       \    :       \/           \     Sysop¹:Static/aFL^Thr\n\             /            /            /\n \___________/____________/    ________/      Sysop²:fanta/Thr\n        |                 \_____|\n        |        14400         _________  _______ _________ _____________\n        |     DualStandard     \___   _ \ \___   |\______  \\_____  ____/\n        ¦    DualSysopPower      /    |  \/      |  /  |    \  /    ___|\n        :  Kicking with /X 2.3  /     ___/__     | /   |     \/     |\n        ·                      /            \_   |/    ¦      \     l____\n        .    ·¹·Dayz warez    /     \        /   |     :       \         |\n              Therion WHQ     \      \      /    |     ·       /         |\n        . Online Door Ordering \______\    /_____|____________/__________|\n                                       \__/j\n\n\n\n\n\n[EOF]','\n',char(10)),NULL,'auto-added',37568,5,0,NULL,NULL,'thr_lc10','scan',1780048775);
INSERT INTO door_catalog VALUES('thr_p204','THR-P204.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/THR-P204.LHA',NULL,'XIM','Pager',NULL,'STATiC/THERioN','THR','.-\__  \   /  /  ___/ _  \  \  _  \___  \--. |.:./  / _   /  __// _  _/  /  /  /  /  /.:| ¦o:/  /  /  /  /  /  /  )  /  /  /  /  /.o:¦',replace('  ___/\_____/\___/\____/\_/\____/\____/\    \n.-\__  \   /  /  ___/ _  \  \  _  \___  \--.\n|.:./  / _   /  __// _  _/  /  /  /  /  /.:|\n¦o:/  /  /  /  /  /  /  )  /  /  /  /  /.o:¦\n:+/  /\_/  /\____/\_/  /  /\____/\_/  /+.:.:\n+-\_/---\_/>Presents\_/\_/-->1994<-\_/>St^t+\n:  OPERATOR PAGER v2.04 BY STATiC/THERioN  :\n¦ o Use your own design.                   ¦\n| o Write a string 2 callerslog.           !\n| o Execute a command, 2 play samps etc.   +\n| o Lots of other small funktions..        ¦\n`------------------------------------------''\n','\n',char(10)),'Pager.doc',replace('             .____.                                  __.          ._______\n   __________|    |_______________________________. /__|___ _____ |      /\n   \   ___   |    |    \______    /\______    /___|/ \___  \\__  \|     /\n    \___/    | ___|    |/ \______/_./ \   ___/    |    |    \/  \ \    /\n      _/     | \____  _/    /_     |   \    \     |    !     \   \ \  /\n«--dZG\______l____|   \____________l____\    \____l__________/____\  /---»\n                  l____|                 \____/                    \/\n\n                                  PReSENtS\n\n                    OPeRAtORPaGER v1.04 BY STATiC/THERioN\n\n\n=============================================================================\n                                 SHORT INFO\n=============================================================================\n\nI think you all know what a pager is so i don''t think there is a need to\nspecific the description. What is so special about this pager you might say,\nwell... This one is totaly configurabe not like all the other ones available,\nsome funktions are: Show text when chat flag is on/off, directly comment when\nchat flag i off, write your own string to callerslog, etc. lot''s of small\noptions. Do check tooltype information for all funktions.\n\n\n=============================================================================\n                                INSTALLATION\n=============================================================================\n\n....2.xx\n\n1. Copy BBS/Doors/Pager/ to Doors:Pager/\n2. Modify your custom-commands and add the following line:\n\n*O        XM010Doors:Pager/Pager\n\n^         ^    ^\n|         |    `--> Or wherever you put the door door.\n|         |\n|         `---> Notice the "X", Thiz door is a pure XIM door!\n|\n`-------> The name to run.\n\n....3.xx\n\n1. Copy BBS/Doors/Pager/ to Doors:Pager/\n2. Copy BBS/Commands/BBSCMD/ to BBS:Commands/BBSCMD/\n\n\n\n=============================================================================\n                           TOOLTYPE CONFIGURATION\n=============================================================================\n\n    [!] INDEPENDENT FUNKTION         [X] IN NEED OF ANOTHER FUNKTION(S)\n\n                    [*] TURNS OFF SOME OF THE FUNKTIONS\n\n\nHOME=<Path:Textfile>        [!]  Will show <Textfile> if chat flag is ON.\n\nNOT_HOME=<Path:Textfile>    [!]  Will show <Textfile> if chat flag is OFF.\n\nUSE_DEFAULTS                [*]  Default mode, prompts for chat reason:\n\n        IE:  Enter chat reason (50 chars/One row)..\n            (----*----*----*----*----*----*----*----*----*----)\n\nGET_REASON=<Nr>             [!]  This is 4 all sysops that wanna add their\n                                 own design when having an input, add the\n                                 design at the end of ''HOMETXT'', Nr is\n                                 numbers of chars to allow.\n\nREASON_STR=<Str>            [X]  When ''GET_REASON=<Nr>'' is added Str will b\n                                 put b4 input at the same row.\n                                 IE: ''REASON_STR=        >''\n\nPASSWORDSTR.<Ax>=<Str>      [!]  Use a password for users with access ?, Str\n                                 is the password string 2 use.\n\nEXECUTE_COMMAND.<Ax>=<Str>  [*]  Execute a command, if u wanna have a\n                                 sampling played when users with access ?\n                                 pages. IE: ''EXECUTE_COMMAND.10=c:Play Samp''\n                                 This funktion turs the ordinary paging off.\n\nEXECUTE_COMMENT=<Str>       [X]  When ''EXECUTE_COMMAND.<Ax>=<Str>'' exists\n                                 Str is string 2 show after command is\n                                 executed.\n\nPROMPT_COMMENT              [!]  b4 leaving a comment when chat flag is off\n                                 the pager will ask if u wanna leave a\n                                 comment 4 the sysop.\n\nPROMPT_STR=<Str>            [X]  When ''PROMPT_COMMENT'' exists this is the\n                                 String 2 be put as a prompt. '' (Y/N)?'' will\n                                 b added in the end of the String.\n\nSTRING_YES=<Str>            [X]  When ''PROMPT_COMMENT'' exists this is the\n                                 String 2 be put when answer is ''y''.\n\nSTRING_NO=<Str>             [X]  When ''PROMPT_COMMENT'' exists this is the\n                                 String 2 be put when answer is ''n''.\n\nWRITE_CALLERSLOG=<Str>      [!]  String 2 b put in callerslog when trying 2\n                                 page. This will take effect even when chat\n                                 flag is off.\n\nNOTE: There is no need 2 add any of this tooltypes.\n\n\n=============================================================================\n                                 GREATINGS\n=============================================================================\niN No SPeCiAl ORdER.\n\n                                   JU/\N,\n                             AQUARIUS, DEXTER,\n                       SANDMAN, PROF DO RIGHT, DISC,\n                    HARPOON, KID CURRY, SKIN, BIG BOSS,\n                   LIME, MR BETA, BIBRONX, MOONY, FANTA,\n                      ZORLAC, GARDIAN, RHYS, BANDIDO,\n                         MAMMOTH, OZONE, CYBERTRON,\n\n                    AND ALL THE FORGOTTEN ONES!? OFCOZE!?\n\n\n\n=============================================================================\n                               COPYRIGHTS (c)\n=============================================================================\n\nU may spread the files as u like as long as u don''t sell it, 2 show that u\nlike this util or if u find any bugs or just wanna chat.. leave a comment 2\nme, (STATiC) i like messages...\n\n\n\n=============================================================================\n                            COMMING ATTRACTIONS!\n=============================================================================\n\nQUESTIONARY         A NEW USER QUESTIONARY THAT HAS IT ALL, ANSI STRIP ETC.\n\nUSERDELETE          A REVOLUTIONARY WAY 2 DELETE USERS, DATE, UL''S, ETC.\n\n=============================================================================\n','\n',char(10)),NULL,'auto-added',57288,5,0,NULL,NULL,'thr_p204','scan',1780048775);
INSERT INTO door_catalog VALUES('thr_req','THR-REQ.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/THR-REQ.LHA','request','XIM','request','1.',NULL,'THR','! Request v1.oO (c) 1994 Therion/X-Design. ! ×<-- -- -- - -- - -- - -- - -- - -- - -- ->× ¡ o Add request to bulletin.               ¡',replace('o--------------------------[Request v1.oO]-o\n! Request v1.oO (c) 1994 Therion/X-Design. !\n×<-- -- -- - -- - -- - -- - -- - -- - -- ->×\n¡ o Add request to bulletin.               ¡\n| o Leave messages (Configurable Design).  |\n| o Auto start when downloading.           |\n! o Multinode.                             !\n×<-- -- -- - -- - -- - -- - -- - -- - -- ->×\n¡ Programming by: FaNTA, Static & Aquarius ¡\n|         Design: Static                   |\n`------------------------------------------''\n','\n',char(10)),'request.doc',replace('\n                                   \|/\n                                  (©_©)\n                            ×<-ooO-(_)-Ooo->×\n\n                 (÷ Request v1.0 (c) Therion/X-Design ÷)    \n\n                  coding by fanta ^ Aquarius/oTL ^ Static\n                           dezign by Static\n\n\n               » Another TherioN /Xdezign Production «\n\n\n\n\n\n                       What does this door do?\n\n\nI wanted to make a requestdoor coz I couldn''t find any fast & good!\nIn my search for a good requestdoor i found that VD-request was the\nbest around, the only problem with that door is that it''s made in \nslow Arexx.\n\nThe door was coded in C using SasC 6.51 Development kit. The main code \nhas been created by fanta & Aquarius. Static has made the dezign.\n\nIt has been coded to be fully multinode. \n\nBetatesting has been done with the help from:\n\nFrosen Assets +46(0)322665225  \nPet Sematary  ask Elite for Number\nUniCorn       +46(031)581610\nAusgebombt    +46(0)52075518 \nDevils Toy    +46(0)303249744\n\n\n\n\n                            Disclaimer\n\n\nWe don''t take any responsibility for any damage this door make on your\ncomputer hardware or software. It has been fully tested so it shouldn''t\ngive you any problems.\n\n\n                    Main Executable File Included\n\n               File                             Size\n               ===================================== \n\n               Request                         23952\n\n\n\n\n                          Installation\n\n\n                            /X 2.xx\n\n\n-Modify your custom-commands and add the following line:\n\n*req        XM050Doors:request/request\n\n^         ^    ^\n|         |    |_ Or wherever you put Requester.\n|         |\n|         |___ Notice the "X" Request is an XIM door!\n|\n|______ The name to run.\n\n-Copy all files in BBS/doors/request/ to doors:request/\n\n\n\n\n\n\n                             /X 3.xx\n\n\n-Copy the icon BBS/Commands/Conf<x>cmd/req.info to BBS:Commands/Conf<x>cmd \n where the x stands for the number of the requestconference.\n\n-Copy all files in BBS/doors/request/ to doors:request/\n\n-Add ~CC_req to your downloadmsg.txt in the request-conf\n\n\n\n\n                    Tooltypes in request.info\n\n==============================>X<=============================\n\nBULLETIN_PATH=bbs:conf6.request/bull50.txt\n^\n+- Path to bullfile that will be created.\n\n==============================>X<=============================\n\nBULLETIN_HEAD=doors:request/bulletinhead.txt\n^\n+- Path to the head of the bulletin.\n\n==============================>X<=============================\n\nBULLETIN_TAIL=doors:request/bulletintail.txt\n^\n+- Path to the tail of the bulletin\n\n==============================>X<=============================\n\nCHARACTER=[36m|[0m\n^\n+- This is the character between colums in the bulletin.\n\nANSI codes can be used in tooltypes.\nTo write the escape character, press lamiga+ctrl+esc... \n\n==============================>X<=============================                                                              \n\nMESSAGE_PATH=bbs:Conf6.Requests/MsgBase/\n^                                      ^\n|                                      + do NOT forget the last /\n|\n+- Path to the MSgBase where the door will put your mezzez.\n\n==============================>X<=============================\n\nMESSAGE_REQUEST_TXT=bbs:conf6.request/message.txt\n^\n+- Path and filename of the asciitext that will be used to create letter\n\n==============================>X<=============================\n\nMESSAGE_REQUEST_TO=EALL\n^\n+- To who do ya want to write the requestmessages\n\n==============================>X<=============================¶\n\nMESSAGE_REQUEST_SUBJECT=Request!\n^\n+- A string that will be put as subject to requestletters that will be created.\n\n==============================>X<=============================\n\nDELETE_ACCESS=250\n^\n+- The minimum access for deletionoverride.\n\n==============================>X<=============================\n\nREQUEST_DATA=s:req.data\n^\n+- The path and filename to the datafile. \n\n==============================>X<=============================\n\n\n\n\n\n\n\n\n                 How to create a Messageletter\n\n\nThis is an ordinary asciifile use the following codes in the letter:\n\n°UserName          Prints out the username instead\n°Location          Prints out the location instead\n°FileDescription   Prints out the filedescription instead\n°UserComment1      Prints out the first line from the usercomment\n°UserComment2      Prints out the second line from the usercomment\n\nExampel follows:\n\n=========================================================>cut<=============\n\n          UserName:   °UserName \n      UserLocation:   °Location \n\n   FileDescription:  °FileDescription\n\n                                User Comment:\n (|-------|-------|-------|-------|-------|-------|-------|-------|-------|--)\n> °Usercomment1\n> °Usercomment2\n\n=========================================================>cut<=============\n\n\n\n\n\nGreeting''s\n\nAxy          Thanx for your agressive comments in the developing-stage ;)\nFlame        For Betatesting\nDamien       Best fakemaster around.\nMooney       Nordman rewls.\nSandman      Love your ascii.\nGuardian     Does GurdisWall still work?! Thanx for Betatesting!\nKid Curry    Thanx for betatesting on Europs fastest and friendliest board.\nCybertron    For Betatesting\nMarshal Law  When will the demo be released?!\n             \n\n\n\nAND OFCOZE ALL THE ONES I HAVE FORGOTTEN!\n\n\n\n\n To provent any backdoors dial...    ..to get the orginal & latest version.\n  \n  __________  ____________________.  : ____________________________________\n_/  _______ )/  _ _/  ___   ______\  ¦/  _ _/  ___   ___   ___     _/  ___/\n\_  _/\_  _ \_  | \____ \_  _/\_  \\ \_  _ \____ \____ \_  _/\__  _\____  |\n |  |  |  |  |  !  |  !  |  !  |  |\ ||  |  |  !  |  !  |  !  ||  | |  !  |\n l__¦_ l__|  l__   l__   l__   l__|  |l__|  l__   l__   l__   |l__¦_l__   |\n    :     l__|  \__|  \__|  \__|  l__|   l__|  \__|  \__|  \__|   : kRm\__|\n.-------------------------------------------------------------------------''\n`----------------/ fROSEN aSSETS / THERiON wHQ / lOOKiNG /--------------- -\n\n               101% fRESH!, 101% SEXY, 101% sAFE, 101% cOOL.\n   -^(-)^-    oNLiNE dOOR oRDERiNG!, aMiEXPRESS 4.x (HYDRA!),    -^(-)^-\n             mAiN cREW: STATiC, fANTA, dAMiEN, MOONEY. / tHR!.\n     ¸,¸                                                           ¸,¸\n    (©_©)   · ·· ··· #> +46(0)322665225 NUP=NO FEAR <# ··· ·· ·   (©_©)   .\n.ooO-(_)-Ooo---------------------------------------------------ooO-(_)-Ooo''\n`------------------/ pARENTAL aDViSORY, eXPLiCT LYRiCS /----------------- -\n\n\n[EOF]\n','\n',char(10)),'{"ACCESS":"250"}','auto-added',20729,2,1,'req','Doors/Request','thr_req','scan',1780048775);
INSERT INTO door_catalog VALUES('thr_wall','THR-WALL.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/THR-WALL.LHA','Wall','XIM','Wall',NULL,'fanta','THR','/_   __/  /  /  ___/  _ )  \     \   \ \SdN \/  /\/     /  ___/     ¯\  \  \  \ \   \ /__/ /__/__/_____/____l___\__\_____\_\___\',replace('  ______________________________________\n /_   __/  /  /  ___/  _ )  \     \   \ \SdN\n \/  /\/     /  ___/     ¯\  \  \  \ \   \\n /__/ /__/__/_____/____l___\__\_____\_\___\\n \  \ \  \  \     \    :   /  /     / /   /\n  \__\/\__\__\_____\___l__/__/_____/_/___/\n<«»W·H·E·R·E  D·O·O·R·S  C·O·M·E  T·R·U·E«»>\n         Wall 1.0ß by fanta & SøNy\n33.6 DigITal-X Prd/NirVana Dist Site! 33.6\n','\n',char(10)),'wall.doc',replace('\012\012\012                      Wall1.0ß by -fanta- & SøNy\012\012\012WHY?\012\012We couldn''t find any nice wall who was good enough for us, so we made a new\012one that supported our demands. Of course we made it in C to accomplish some\012speed.\012\012Disclaimer\012\012We don''t take any responsibility for any damage this door make on your\012computer hardware or software. It has been fully tested so it shouldn''t\012give ya any problems\012\012Installation\012\012Just copy the files to a drawer ex doors:wall/\012Install it in BBSCMD as a usual XIM-door.\012\012The door will create two files in the s: directory called\012s:walluser.dat    -> name of last user added\012s:wall.dat        -> the comments\012Do not touch these files, when the door is working.\012\012If the door doesn''t work as you want try to delete these two files...\012\012IMPORTANT\012\012The door will not work without the included lib\012AEDOOR.library v1.10\012\012Don''t try a l8er lib becouse they are not backcompatibel...\012\012\012Filename            Original 1.00ß Size\012\012Wall                  13988     -> Main program. No backdoors here, please\012\012\012Merry /X-mas & Happy new year goes to:\012\012Sandman         -» Heavy Ascii, heavy wareZ\012Ju/\n           -» Cool ascii, søøn Asylum\012Zorlac          -» lame doors (yet)\012Big Boss        -» gif???\012Guardian        -» fast warez too, SoNy''s mentor in /X\012BoZ             -» Nice board\012mr Beta         -» Nice board too\012Abram           -» We love your C - code\012\012not:\012\012KG Warrior      - lame 2400\012\012\012Enjoy our product, please don''t mezz with it.\012\012-fanta- & SoNy\012\012  __________  ___________ ____________\012  \_____  _/  \__  _  __/ \__  |    _/\012   ___|    \  /    |    \  /   ¦     \  +¢6(°)³²²/¹9°97\012  /   |     \/     |     \/    :      \_________________ _ _  _    _\012 /    ¦      \     ¦      \_______     \\012/     :       \    :       \/           \     Sysop¹:fanta\012\             /            /            /\012 \___________/____________/    ________/      Sysop²:S0Ny\012        |                 \_____|\012        |        14400         _________  _______ _________ _____________\012        |     DualStandard     \___   _ \ \___   |\______  \\_____  ____/\012        ¦    DualSysopPower      /    |  \/      |  /  |    \  /    ___|\012        :  Kicking with /X 2.3  /     ___/__     | /   |     \/     |\012        ·                      /            \_   |/    ¦      \     l____\012        .    ·¹·Dayz warez    /     \        /   |     :       \         |\012              Therion WHQ     \      \      /    |     ·       /         |\012        . Online Door Ordering \______\    /_____|____________/__________|\012                                       \__/j\012\012\012\012\012\012\012','\012',char(10)),NULL,'auto-added',16626,8,0,NULL,NULL,'thr_wall','scan',1780048775);
INSERT INTO door_catalog VALUES('thrashba','THRASHBA.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/THRASHBA.LHA',NULL,'XIM','TBar1.1',NULL,NULL,NULL,NULL,replace('lost desc\n','\n',char(10)),'Tbar.Guide',replace('@REMARK .-------------------------------------------------------------------.\n@REMARK |   Thrash-Bar, HyperText document written by Thrash of ANTHROX!.   |\n@REMARK |  If you don''t have Multiview (OS3) or AmigaGuide (OS2) installed  |\n@REMARK | in your system, I suggest you do so, because they''re brilliant!.. |\n@REMARK | If you cannot you''ll just have to read these in any ASCII viewer! |\n@REMARK `-------------------------------------------------------------------''\n@NODE MAIN\n@TITLE "ThrashBar: Contents"\n                __/\  _____________/|___  ________/\/\  /\\n                \   \/SP  \       / |   |/       /  \ \/ /\n                / _  \  /  \/  |_/  _   /  _/ __/    \  / \n               /  \   \/   /   |/   |  /   \   \    //  \ \n               \___\  /___/\___|\___|__\___|\  /\   / /\ \\n              - -- -\/=-==-===> PRESENT <===-\/-=\_/\/- \/\n\n             T-Bar Version 1.01, ©1992-1993 Thrash/Anthrox!\n         Top Bar-Chart utility for the AmiExpress BBS Software\n\n  @{" Introduction     " LINK INTRO} ...................... Introductory Note.\n  @{" Features         " LINK FEATURES} ...................... Brief OutLine Of Features.\n  @{" Installation     " LINK INSTALL} ...................... How To Install T-Bar.\n  @{" Text Display     " LINK DIRECT} ...................... Where you want the output.\n  @{" Command Line     " LINK CMDLINE} ...................... T-Bar Command Line.\n  @{" Optional Extras  " LINK EXTRAS} ...................... Extras options available\n\n  @{" Program History  " LINK HISTORY} ...................... When & Where.\n  @{" Contact          " LINK CONTACT} ...................... BBS To Contact Me.\n  @{" Greetings        " LINK GREETS} ...................... Hi to a few people.\n\n@ENDNODE\n\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE FEATURES "ThrashBar: Main Features"\n\n	Basically, Tbar is a multiple chart-displayer for use with any\nVersion of Ami-Express. Use it to compile upto 6 different types of chart,\n(ansi or non-ansi), which display information on any amount of users on \nyour bulletin board in a bar-chart format that is easy to read. Noteable \nfeatures built into it are:\n\n o 100% Assembly Language. (Each Chart only takes about 1 sec. to compile)\n o Top Byte @{" Uploaders Chart " LINK CHART}.\n o Top Byte @{" DownLoaders Chart " LINK CHART}.\n o Top File @{" Uploaders Chart " LINK CHART}.\n o Top File @{" DownLoaders Chart " LINK CHART}.\n o Top @{" Message Writers Chart " LINK CHART}.\n o Top @{" Callers Chart " LINK CHART}.\n o Overall status of bulletin board users.\n o Configurable @{" Ratios " LINK RATIO} for calculation of elite/normal/leech guys.\n\nOptional Features:\n o @{" Ansi mode on/off " LINK ANSI} (yes - you can still see the bars in non-ansi!).\n o Individual @{" logos/headertexts " LINK LOGOS} for each chart.\n o @{" Excluded Users " LINK EXCLUDE} file (for people you dont want shown in charts). This\n   will handle security levels as well as names.\n o One of upto 255 @{" Random Lines " LINK RANDOM} will appear underneath your chart.\n@ENDNODE\n\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE INTRO "ThrashBar: ForeWord"\n\n        Before you throw this util into that bottomless pile of crap\nutils that get released for Ami-Express. STOP! .. Dont even go to the\nbother of setting it up. Included in the archive you will find some\nexample outputs for you to view. They are all ansi versions so make\nsure to view them through an 8 colour workbench to see them in their\nfull glory. If you''re happy and i have managed to grab your attention\nthen continue reading. If not, then stick to the lame C or AREXX util\nyou''re currently running that wastes 30 seconds of your logoff script!\n\n        Lets face it, the main problem about Ami-Express utils is that\nthere are so bloody many of them! Some are really great but I''d say that\nabout 80% arent worth shit. Even those that are really good, sometimes\nfall down on the fact that they LOOK crap. This is one thing I hope to\nhave eliminated from my /Xpress utilities. The original ansi design was\ndone by Pot-Noodle and most sysops seem to agree that it is one of the\nbest and easiest to look at. I hope you agree!\n\n	If you think of a good feature this program doesnt include,then\nplease fell free to contact me. Without any comeback from sysops i cant\ndo shit!!  If you dont contact me then dont fuckin'' moan about it!\n\n@ENDNODE\n\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE HISTORY "ThrashBar: Program History"\n\nT-BAR History And Development:\n\n Version      Date              Comment\n -------     ------             ------\n\n  V0.05	    08/11/92   (ßeta)	First ßeta version to testers.\n  V0.08	    25/11/92   (ßeta)	Added logo selection,random lines\n                                and excluded file to options.\n  V0.09	    01/12/92   (ßeta)   Exclusion file will now handle\n                                security levels.\n  V1.00	    15/01/93            First public release.\n  V1.01	    12/04/93            Hanging Loop bug fixed. Number calculation\n                                extended to 10 digits. THIS VERSION!\n@ENDNODE\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE CONTACT "ThrashBar: Contact Me!"\n\n\n	Well, thats about it!.. All thats left is to leave you with a list\nof bulletin boards whose sysops have been a great help during production.\nRemember you can reach me on these boards, so if there''s sommit you wanna\nsee in a future release or get off your chest, then leave a message to \neither me or the sysop.\n\n	C.A.L		+44(0)81-3466842	Sysop - Pot-Noodle/ATX!\n	BurgerBar	+44(0)983-741324	Sysop - Ice D/Indy\n	EnterPrise	+01-4122332611		Sysop - Picard/ATX!\n	Synergy		+49-5731-41982		Sysop - Sigma7/Abandon\n	HyperSpace	+49-5916-4755		Sysop - Thargoid/ATX!\n	Bad Dreams	+44(0)81-6795693	Sysop - DreamWarrior/Indy\n	Arcadia		+44(0)923-893593	Sysop - Beast/Qtx\n\n@ENDNODE\n\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE INSTALL "ThrashBar: Installation"\n\nINSTALLATION ?:\n==============\n\n	In its very simplest form, Tbar requires NO setting up at all.\nHowever, if you spend the time to study these documents fully, I''m sure\nyou''ll find all the options that most sysops require nowadays.\n\n	To see an output before you install please refer to the example\ntexts you will find within the original archive.\n@ENDNODE\n\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE DIRECT "ThrashBar: REdirection"\n\nRE-DIRECTION OF TEXT:\n====================\n\n	The form of T-Bars command line is quite simple. Firstly please\nremember that T-Bar itself, will NOT create a file of the text displayed.\nWhy write the routines when Commodore have done it already? Yeah, you\nguessed it. You yourself will have to re-direct the file to the appropriate\nbulletin text. This redirection will obviously have to come BEFORE any of\nthe commandline options of TBar itself. In case you haven''t done this \nbefore (your kidding me?), here''s a quick example.\n\nTBAR >BBS:CONF1/BULL100.TXT.GR\n\n	If you type this line into your cli window the text display\nwill be output to a file called BBS:CONF1/BULL100.TXT.GR rather than\nthe normal cli display.\n\n@ENDNODE\n\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE CMDLINE "ThrashBar: Main CommandLine"\n\n\n\nTBAR COMMAND LINE SEQUENCE:\n==========================\n\n	The command line must always come in the order stated below. If\nit fails to find a file that it requires or runs out of memory it will\nALWAYS return a DOS error code. (Note this would be in the re-direction\nfile if used!)\n\n\nTBAR @{"[CHART]" LINK CHART} @{"[USERDATA-PATH]" LINK DATA} @{"[USERS-TO-DISPLAY]" LINK AMOUNT} @{"[RATIO]" LINK RATIO} @{"[ANSI OFF]" LINK ANSI}\n\n	Simple eh??\n\n@ENDNODE\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE CHART "ThrashBar: Charts Available"\n\nWHICH CHART YOU WANT:\n=====================\n	The chart option must ALWAYS be the FIRST command in a command-\nline sequence. There are six charts to choose from and simply changing\nthe FOUR letters at the beginning will tell TBar what chart you want to\nbe displayed. Those available to you are:\n\n	UPLD	-	Top byte uploaders\n	DNLD	-	Top byte downloaders\n	UPFL	-	Top file uploaders\n	DNFL	-	Top file downloaders\n	MESG	-	Top message writers\n	CALL	-	Top callers chart\n\n@ENDNODE\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE DATA "ThrashBar: Your UserData File"\n\nYOUR USERDATA FILE:\n==================\n	The FULL path and name of your userdata file must ALWAYS be set\nafter the TBar has been told which chart you want. If you are a person\nwho has changed the userdata filename to something like "USER DATA" for\nsafety reasons, then you will have to make a copy of it into ram: or some\nwhere as TBar will not (at this time) handle filenames with spaces in them.\nMaybe in the next version eh!\n\n\nNOTE:	A few people reading this will know that if I had wanted to, I could\nhave discovered the name of the userdata file by loading up the ACP.STARTUP\nfile. The problem with this is that so many people DONT know how to use the\nACP file correctly and just use it for starting the nodes. Maybe in a future\nversion of /Xpress, when people HAVE to use the ACP correctly, I will add \nthis simple feature.\n\n@ENDNODE\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE AMOUNT "ThrashBar: Amount Of Users To Display"\n\nHOW MANY USERS TO DISPLAY:\n==========================\n	Tbar determines the amount of users to display in the chart by the\nthree (T*H*R*E*E,3) digit figure that must ALWAYS follow the userdata file\nin the command line. If the amount of users to be displayed is less than\n100 then padding zeros MUST be used. Here''s a few examples.\n\nTBAR UPLD BBS:USER.DATA 010 5		Display top 10 byte uploaders\nTBAR MESG BBS:USER.DATA 025 5		Display top 25 message writers\nTBAR UPFL BBS:USER.DATA ALL 5		Display ALL users sorted in files\n					Uploaded format.\n@ENDNODE\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE RATIO "ThrashBar: Users Ratio Calculation"\n\nRATIO CALCULATION:\n==================\n	The Ratio is used in a quick calculation to determine if that\nparticular user has leeched or benefitted your bbs. It works exactly the\nsame way as the ratio in the users statistics. The ratio number must\nALWAYS be a number between 2 and 9 and must ALWAYS follow straight after\nthe amount of users to be displayed. IE\n\nTBAR UPLD BBS:USER.DATA 010 3		Top 10, ratio 3/1 calculation\nTBAR UPLD BBS:USER.DATA 010 7		Top 10, ratio 7/1 calculation\n\nNOTE:	The calculation is always performed on the uploaded and downloaded\n	BYTES. Ie if you choose UPFL (uploaded files chart), then the ratio\n	calcualtion WILL NOT be performed on the FILES uploaded. If people\n	want this though it could be changed.\n\n@ENDNODE\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE ANSI "ThrashBar: Ansi Graphics On/Off"\n\nNON-ANSI MODE:\n==============\n	Some sysops may want this utility to be displayed to ALL users\nwhen they logon. The problem is that they may logon to the bbs in non-\nansi mode and if the normal chart is displayed in non-ansi there are\njust a load of blank spaces where the bars are normally displayed. As\nfar as I know, most other (if not all) barchart displayers haven''t taken\nthis into account and so sysops just dont bother to run barcharts. This\nall stops from NOW!\n	If, at the end of your command line, you place a "-A", all \ncoloured spaces within the barchart section will be replaced with a "#"\nso that ANYBODY can see the chart. You would obviously need to run TBar\ntwice in your logff script. Once for ansi ON and another time with Ansi\nOFF. Here''s an example of a logoff script:\n\nTBAR >BBS:CONF1/BULL100.TXT UPLD BBS:USER.DATA 010 3 -A  (Ansi-OFF)\nTBAR >BBS:CONF1/BULL100.TXT.GR UPLD BBS:USER.DATA 010 3  (Ansi-ON)\n\n	NOTE: I have noticed that quite a few boards run the non-ansi\nverison on ansi text as well. This is fine cause ami-express has a built\nin ansi stripper and I must admit that I prefer it. (i think!).\n\n@ENDNODE\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE EXTRAS "ThrashBar: Optional Extras"\n\n\n T-Bar has a number of optional extras that the sysop may want to use\n in order for his chart to look different from others. These extras\n will grow as they are requested.\n\n  @{" Logos/Headers     " LINK LOGOS} .................. Display your own header texts.\n  @{" Exclude Users     " LINK EXCLUDE} .................. Exclude certain users from chart.\n  @{" Random Comments   " LINK RANDOM} .................. Humourous(?) random comments.\n\n@ENDNODE\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE LOGOS "ThrashBar: Optional Extras - Logo/Header Texts"\n\nDISPLAYING LOGO/HEADERTEXTS:\n============================\n	Tbar will simply use the four-letter chart option to get a logo or\nheaderfile from your S: directory. If the file isn''t found - it wont get\ndisplayed!\n\n	CHART		TBAR SEARCHES FOR\n	=====		=================\n	UPLD		S:TBARUPLD.HEADER	<- UpLoaded Bytes Logo\n	DNLD		S:TBARDNLD.HEADER	<- DownLoaded bytes Logo\n	UPFL		S:TBARUPFL.HEADER	<- UpLoaded files Logo\n	DNFL		S:TBARDNFL.HEADER	<- DownLoaded Files Logo\n	MESG		S:TBARMESG.HEADER	<- Top MessageWriters Logo\n	CALL		S:TBARCALL.HEADER	<- Top Callers Logo\n\n	It doesn''t matter if the texts are ansi-coloured as Ami-Express has\na built in stripper if the user is in non-ansi. If you find this method of\nlogo detection too restricting then please feel free to let me know and in\na future release I will possibly change it.\n\n@ENDNODE\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE EXCLUDE "ThrashBar: Optional Extras - Excluded Users"\n\nEXCLUDED USERS FILE:\n====================\n	This is where I''ve heard some people felt that TTOP fell down.\nThe file Tbar searches for is called "S:TBAR.EXCLUDES". This is simply\na file of people you DO NOT want included in the following charts:\n\n	UPLD	-	Top byte uploaders\n	DNLD	-	Top byte downloaders\n	UPFL	-	Top file uploaders\n	DNFL	-	Top file downloaders\n\nThe names in the file must be EXACTLY as they are written in the userdata\nfile and each one MUST end with a return.\n	These people are not actually excluded from the chart altogether.\nAll TBar does is zero their uploaded bytes/files and their downloaded\nbytes/files. If you use the "ALL" option they WILL get displayed but\nobviously they will be at the bottom of the chart. It is upto the sysop\nto place the correct number in the commandline so that these people do\nnot get show on the wrong chart!\n\nUPDATE:\n======\n	Thanks to the suggestion of Sigma7/Abandon, you can now also \nexclude people by their SECURITY LEVEL. Simply use the following line\nin the file "S:TBAR.EXCLUDES".\n\nSec_Level XXX\n\n	Note that as in the main command line, the XXX must be a THREE\ndigit figure corresponding to the security levels you want excluded. If\nthe security level is less than 100 then PADDING ZEROS MUST BE USED!\n\nSec_Level 010	- exclude people whose security level is 10.\n\n\nNOTE:	These peoples up/downloads WILL NOT be included in any chart in\n	the OVERALL stats line that appears at the bottom.\n@ENDNODE\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE RANDOM "ThrashBar: Optional Extras - Random Comments"\n\nRANDOM LINES:\n=============\n	This is a nice feature that I first saw used in Amilog coded by\nRetaliator/Anthrox so cheers to him and Pot-noodle for being so inventive!\n	After TBar has displayed both the logo/headertext and the main\nchart itself, it will search for a file called "S:TBAR.LINES". An example\nfile is included in this archive so check it out! The file is simply a\ntext file of upto 255 one liners. TBar will randomly select one of these\nand place it underneath the chart. Simple but effective. Each line MUST\nNOT be longer then 76 characters and MUST end in a return (otherwise TBar\nwont find the required line!). If you put more than 255 lines these will\nbe ignored. Once again, if TBar fails to find the file it DOESN''T MATTER.\nIt simply wont use a random line.\n@ENDNODE\n\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE GREETS "ThrashBar: Hi Guyz!"\n\nGreets :- As usual in my laziness means they are in no sheep-shagging\n          order!\n\nAnthrox	- Pot-Noodle - /X\arvin - Picard - Ice - ManxyBabe\n	- Thargoid - TGR - Retaliator - Graffiti - DreamScape\n	- RockWorm - Shredder - Fido - Dream Warrior - Sprog!!\n	- and all the other guyz I forgot!!\n\nOthers	- SigmaSeven - Dan! - Marigold - Ice D - Solo - MyMurth\n	- Vindex - The Black Cat - Astropath - Beast - Skol -\n	- Groo - Samir\n\n	  If I missed you out and you think you should be here then\n          gimme some shit and maybe Ill remember next time!\n\nTHANK YOU for taking the time to at least look at this utility!! There''s\ntoo many lazy fucker SysOps out there who just let the best utils slip by\nthem coz they don''t bother to look at the new stuff... If you liked this\nor any other Anthrox util, why not spread the word, and get the world\nrunning our Good Looking and FAST utils, and rid the modem world of Ugly,\nBadly designed, and SLOW (Like C and Basic and ARexx) Utils!! Only the\nBEST will do!\n\n			Thrash!	1993\n@ENDNODE\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n','\n',char(10)),NULL,'auto-added',32421,3,0,NULL,NULL,'thrashba','scan',1780048775);
INSERT INTO door_catalog VALUES('thrashbr','THRASHBR.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/THRASHBR.LHA',NULL,'XIM','exe.-l0S-eND0S-bBS-.exe',NULL,NULL,NULL,NULL,replace('BARCHARTS FOR UPLOAD MESSAGES CALLS ETC.\n','\n',char(10)),'Tbar.Guide',replace('@REMARK .-------------------------------------------------------------------.\n@REMARK |   Thrash-Bar, HyperText document written by Thrash of ANTHROX!.   |\n@REMARK |  If you don''t have Multiview (OS3) or AmigaGuide (OS2) installed  |\n@REMARK | in your system, I suggest you do so, because they''re brilliant!.. |\n@REMARK | If you cannot you''ll just have to read these in any ASCII viewer! |\n@REMARK `-------------------------------------------------------------------''\n@NODE MAIN\n@TITLE "ThrashBar: Contents"\n                __/\  _____________/|___  ________/\/\  /\\n                \   \/SP  \       / |   |/       /  \ \/ /\n                / _  \  /  \/  |_/  _   /  _/ __/    \  / \n               /  \   \/   /   |/   |  /   \   \    //  \ \n               \___\  /___/\___|\___|__\___|\  /\   / /\ \\n              - -- -\/=-==-===> PRESENT <===-\/-=\_/\/- \/\n\n             T-Bar Version 1.01, ©1992-1993 Thrash/Anthrox!\n         Top Bar-Chart utility for the AmiExpress BBS Software\n\n  @{" Introduction     " LINK INTRO} ...................... Introductory Note.\n  @{" Features         " LINK FEATURES} ...................... Brief OutLine Of Features.\n  @{" Installation     " LINK INSTALL} ...................... How To Install T-Bar.\n  @{" Text Display     " LINK DIRECT} ...................... Where you want the output.\n  @{" Command Line     " LINK CMDLINE} ...................... T-Bar Command Line.\n  @{" Optional Extras  " LINK EXTRAS} ...................... Extras options available\n\n  @{" Program History  " LINK HISTORY} ...................... When & Where.\n  @{" Contact          " LINK CONTACT} ...................... BBS To Contact Me.\n  @{" Greetings        " LINK GREETS} ...................... Hi to a few people.\n\n@ENDNODE\n\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE FEATURES "ThrashBar: Main Features"\n\n	Basically, Tbar is a multiple chart-displayer for use with any\nVersion of Ami-Express. Use it to compile upto 6 different types of chart,\n(ansi or non-ansi), which display information on any amount of users on \nyour bulletin board in a bar-chart format that is easy to read. Noteable \nfeatures built into it are:\n\n o 100% Assembly Language. (Each Chart only takes about 1 sec. to compile)\n o Top Byte @{" Uploaders Chart " LINK CHART}.\n o Top Byte @{" DownLoaders Chart " LINK CHART}.\n o Top File @{" Uploaders Chart " LINK CHART}.\n o Top File @{" DownLoaders Chart " LINK CHART}.\n o Top @{" Message Writers Chart " LINK CHART}.\n o Top @{" Callers Chart " LINK CHART}.\n o Overall status of bulletin board users.\n o Configurable @{" Ratios " LINK RATIO} for calculation of elite/normal/leech guys.\n\nOptional Features:\n o @{" Ansi mode on/off " LINK ANSI} (yes - you can still see the bars in non-ansi!).\n o Individual @{" logos/headertexts " LINK LOGOS} for each chart.\n o @{" Excluded Users " LINK EXCLUDE} file (for people you dont want shown in charts). This\n   will handle security levels as well as names.\n o One of upto 255 @{" Random Lines " LINK RANDOM} will appear underneath your chart.\n@ENDNODE\n\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE INTRO "ThrashBar: ForeWord"\n\n        Before you throw this util into that bottomless pile of crap\nutils that get released for Ami-Express. STOP! .. Dont even go to the\nbother of setting it up. Included in the archive you will find some\nexample outputs for you to view. They are all ansi versions so make\nsure to view them through an 8 colour workbench to see them in their\nfull glory. If you''re happy and i have managed to grab your attention\nthen continue reading. If not, then stick to the lame C or AREXX util\nyou''re currently running that wastes 30 seconds of your logoff script!\n\n        Lets face it, the main problem about Ami-Express utils is that\nthere are so bloody many of them! Some are really great but I''d say that\nabout 80% arent worth shit. Even those that are really good, sometimes\nfall down on the fact that they LOOK crap. This is one thing I hope to\nhave eliminated from my /Xpress utilities. The original ansi design was\ndone by Pot-Noodle and most sysops seem to agree that it is one of the\nbest and easiest to look at. I hope you agree!\n\n	If you think of a good feature this program doesnt include,then\nplease fell free to contact me. Without any comeback from sysops i cant\ndo shit!!  If you dont contact me then dont fuckin'' moan about it!\n\n@ENDNODE\n\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE HISTORY "ThrashBar: Program History"\n\nT-BAR History And Development:\n\n Version      Date              Comment\n -------     ------             ------\n\n  V0.05	    08/11/92   (ßeta)	First ßeta version to testers.\n  V0.08	    25/11/92   (ßeta)	Added logo selection,random lines\n                                and excluded file to options.\n  V0.09	    01/12/92   (ßeta)   Exclusion file will now handle\n                                security levels.\n  V1.00	    15/01/93            First public release.\n  V1.01	    12/04/93            Hanging Loop bug fixed. Number calculation\n                                extended to 10 digits. THIS VERSION!\n@ENDNODE\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE CONTACT "ThrashBar: Contact Me!"\n\n\n	Well, thats about it!.. All thats left is to leave you with a list\nof bulletin boards whose sysops have been a great help during production.\nRemember you can reach me on these boards, so if there''s sommit you wanna\nsee in a future release or get off your chest, then leave a message to \neither me or the sysop.\n\n	C.A.L		+44(0)81-3466842	Sysop - Pot-Noodle/ATX!\n	BurgerBar	+44(0)983-741324	Sysop - Ice D/Indy\n	EnterPrise	+01-4122332611		Sysop - Picard/ATX!\n	Synergy		+49-5731-41982		Sysop - Sigma7/Abandon\n	HyperSpace	+49-5916-4755		Sysop - Thargoid/ATX!\n	Bad Dreams	+44(0)81-6795693	Sysop - DreamWarrior/Indy\n	Arcadia		+44(0)923-893593	Sysop - Beast/Qtx\n\n@ENDNODE\n\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE INSTALL "ThrashBar: Installation"\n\nINSTALLATION ?:\n==============\n\n	In its very simplest form, Tbar requires NO setting up at all.\nHowever, if you spend the time to study these documents fully, I''m sure\nyou''ll find all the options that most sysops require nowadays.\n\n	To see an output before you install please refer to the example\ntexts you will find within the original archive.\n@ENDNODE\n\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE DIRECT "ThrashBar: REdirection"\n\nRE-DIRECTION OF TEXT:\n====================\n\n	The form of T-Bars command line is quite simple. Firstly please\nremember that T-Bar itself, will NOT create a file of the text displayed.\nWhy write the routines when Commodore have done it already? Yeah, you\nguessed it. You yourself will have to re-direct the file to the appropriate\nbulletin text. This redirection will obviously have to come BEFORE any of\nthe commandline options of TBar itself. In case you haven''t done this \nbefore (your kidding me?), here''s a quick example.\n\nTBAR >BBS:CONF1/BULL100.TXT.GR\n\n	If you type this line into your cli window the text display\nwill be output to a file called BBS:CONF1/BULL100.TXT.GR rather than\nthe normal cli display.\n\n@ENDNODE\n\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE CMDLINE "ThrashBar: Main CommandLine"\n\n\n\nTBAR COMMAND LINE SEQUENCE:\n==========================\n\n	The command line must always come in the order stated below. If\nit fails to find a file that it requires or runs out of memory it will\nALWAYS return a DOS error code. (Note this would be in the re-direction\nfile if used!)\n\n\nTBAR @{"[CHART]" LINK CHART} @{"[USERDATA-PATH]" LINK DATA} @{"[USERS-TO-DISPLAY]" LINK AMOUNT} @{"[RATIO]" LINK RATIO} @{"[ANSI OFF]" LINK ANSI}\n\n	Simple eh??\n\n@ENDNODE\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE CHART "ThrashBar: Charts Available"\n\nWHICH CHART YOU WANT:\n=====================\n	The chart option must ALWAYS be the FIRST command in a command-\nline sequence. There are six charts to choose from and simply changing\nthe FOUR letters at the beginning will tell TBar what chart you want to\nbe displayed. Those available to you are:\n\n	UPLD	-	Top byte uploaders\n	DNLD	-	Top byte downloaders\n	UPFL	-	Top file uploaders\n	DNFL	-	Top file downloaders\n	MESG	-	Top message writers\n	CALL	-	Top callers chart\n\n@ENDNODE\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE DATA "ThrashBar: Your UserData File"\n\nYOUR USERDATA FILE:\n==================\n	The FULL path and name of your userdata file must ALWAYS be set\nafter the TBar has been told which chart you want. If you are a person\nwho has changed the userdata filename to something like "USER DATA" for\nsafety reasons, then you will have to make a copy of it into ram: or some\nwhere as TBar will not (at this time) handle filenames with spaces in them.\nMaybe in the next version eh!\n\n\nNOTE:	A few people reading this will know that if I had wanted to, I could\nhave discovered the name of the userdata file by loading up the ACP.STARTUP\nfile. The problem with this is that so many people DONT know how to use the\nACP file correctly and just use it for starting the nodes. Maybe in a future\nversion of /Xpress, when people HAVE to use the ACP correctly, I will add \nthis simple feature.\n\n@ENDNODE\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE AMOUNT "ThrashBar: Amount Of Users To Display"\n\nHOW MANY USERS TO DISPLAY:\n==========================\n	Tbar determines the amount of users to display in the chart by the\nthree (T*H*R*E*E,3) digit figure that must ALWAYS follow the userdata file\nin the command line. If the amount of users to be displayed is less than\n100 then padding zeros MUST be used. Here''s a few examples.\n\nTBAR UPLD BBS:USER.DATA 010 5		Display top 10 byte uploaders\nTBAR MESG BBS:USER.DATA 025 5		Display top 25 message writers\nTBAR UPFL BBS:USER.DATA ALL 5		Display ALL users sorted in files\n					Uploaded format.\n@ENDNODE\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE RATIO "ThrashBar: Users Ratio Calculation"\n\nRATIO CALCULATION:\n==================\n	The Ratio is used in a quick calculation to determine if that\nparticular user has leeched or benefitted your bbs. It works exactly the\nsame way as the ratio in the users statistics. The ratio number must\nALWAYS be a number between 2 and 9 and must ALWAYS follow straight after\nthe amount of users to be displayed. IE\n\nTBAR UPLD BBS:USER.DATA 010 3		Top 10, ratio 3/1 calculation\nTBAR UPLD BBS:USER.DATA 010 7		Top 10, ratio 7/1 calculation\n\nNOTE:	The calculation is always performed on the uploaded and downloaded\n	BYTES. Ie if you choose UPFL (uploaded files chart), then the ratio\n	calcualtion WILL NOT be performed on the FILES uploaded. If people\n	want this though it could be changed.\n\n@ENDNODE\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE ANSI "ThrashBar: Ansi Graphics On/Off"\n\nNON-ANSI MODE:\n==============\n	Some sysops may want this utility to be displayed to ALL users\nwhen they logon. The problem is that they may logon to the bbs in non-\nansi mode and if the normal chart is displayed in non-ansi there are\njust a load of blank spaces where the bars are normally displayed. As\nfar as I know, most other (if not all) barchart displayers haven''t taken\nthis into account and so sysops just dont bother to run barcharts. This\nall stops from NOW!\n	If, at the end of your command line, you place a "-A", all \ncoloured spaces within the barchart section will be replaced with a "#"\nso that ANYBODY can see the chart. You would obviously need to run TBar\ntwice in your logff script. Once for ansi ON and another time with Ansi\nOFF. Here''s an example of a logoff script:\n\nTBAR >BBS:CONF1/BULL100.TXT UPLD BBS:USER.DATA 010 3 -A  (Ansi-OFF)\nTBAR >BBS:CONF1/BULL100.TXT.GR UPLD BBS:USER.DATA 010 3  (Ansi-ON)\n\n	NOTE: I have noticed that quite a few boards run the non-ansi\nverison on ansi text as well. This is fine cause ami-express has a built\nin ansi stripper and I must admit that I prefer it. (i think!).\n\n@ENDNODE\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE EXTRAS "ThrashBar: Optional Extras"\n\n\n T-Bar has a number of optional extras that the sysop may want to use\n in order for his chart to look different from others. These extras\n will grow as they are requested.\n\n  @{" Logos/Headers     " LINK LOGOS} .................. Display your own header texts.\n  @{" Exclude Users     " LINK EXCLUDE} .................. Exclude certain users from chart.\n  @{" Random Comments   " LINK RANDOM} .................. Humourous(?) random comments.\n\n@ENDNODE\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE LOGOS "ThrashBar: Optional Extras - Logo/Header Texts"\n\nDISPLAYING LOGO/HEADERTEXTS:\n============================\n	Tbar will simply use the four-letter chart option to get a logo or\nheaderfile from your S: directory. If the file isn''t found - it wont get\ndisplayed!\n\n	CHART		TBAR SEARCHES FOR\n	=====		=================\n	UPLD		S:TBARUPLD.HEADER	<- UpLoaded Bytes Logo\n	DNLD		S:TBARDNLD.HEADER	<- DownLoaded bytes Logo\n	UPFL		S:TBARUPFL.HEADER	<- UpLoaded files Logo\n	DNFL		S:TBARDNFL.HEADER	<- DownLoaded Files Logo\n	MESG		S:TBARMESG.HEADER	<- Top MessageWriters Logo\n	CALL		S:TBARCALL.HEADER	<- Top Callers Logo\n\n	It doesn''t matter if the texts are ansi-coloured as Ami-Express has\na built in stripper if the user is in non-ansi. If you find this method of\nlogo detection too restricting then please feel free to let me know and in\na future release I will possibly change it.\n\n@ENDNODE\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE EXCLUDE "ThrashBar: Optional Extras - Excluded Users"\n\nEXCLUDED USERS FILE:\n====================\n	This is where I''ve heard some people felt that TTOP fell down.\nThe file Tbar searches for is called "S:TBAR.EXCLUDES". This is simply\na file of people you DO NOT want included in the following charts:\n\n	UPLD	-	Top byte uploaders\n	DNLD	-	Top byte downloaders\n	UPFL	-	Top file uploaders\n	DNFL	-	Top file downloaders\n\nThe names in the file must be EXACTLY as they are written in the userdata\nfile and each one MUST end with a return.\n	These people are not actually excluded from the chart altogether.\nAll TBar does is zero their uploaded bytes/files and their downloaded\nbytes/files. If you use the "ALL" option they WILL get displayed but\nobviously they will be at the bottom of the chart. It is upto the sysop\nto place the correct number in the commandline so that these people do\nnot get show on the wrong chart!\n\nUPDATE:\n======\n	Thanks to the suggestion of Sigma7/Abandon, you can now also \nexclude people by their SECURITY LEVEL. Simply use the following line\nin the file "S:TBAR.EXCLUDES".\n\nSec_Level XXX\n\n	Note that as in the main command line, the XXX must be a THREE\ndigit figure corresponding to the security levels you want excluded. If\nthe security level is less than 100 then PADDING ZEROS MUST BE USED!\n\nSec_Level 010	- exclude people whose security level is 10.\n\n\nNOTE:	These peoples up/downloads WILL NOT be included in any chart in\n	the OVERALL stats line that appears at the bottom.\n@ENDNODE\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE RANDOM "ThrashBar: Optional Extras - Random Comments"\n\nRANDOM LINES:\n=============\n	This is a nice feature that I first saw used in Amilog coded by\nRetaliator/Anthrox so cheers to him and Pot-noodle for being so inventive!\n	After TBar has displayed both the logo/headertext and the main\nchart itself, it will search for a file called "S:TBAR.LINES". An example\nfile is included in this archive so check it out! The file is simply a\ntext file of upto 255 one liners. TBar will randomly select one of these\nand place it underneath the chart. Simple but effective. Each line MUST\nNOT be longer then 76 characters and MUST end in a return (otherwise TBar\nwont find the required line!). If you put more than 255 lines these will\nbe ignored. Once again, if TBar fails to find the file it DOESN''T MATTER.\nIt simply wont use a random line.\n@ENDNODE\n\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n@NODE GREETS "ThrashBar: Hi Guyz!"\n\nGreets :- As usual in my laziness means they are in no sheep-shagging\n          order!\n\nAnthrox	- Pot-Noodle - /X\arvin - Picard - Ice - ManxyBabe\n	- Thargoid - TGR - Retaliator - Graffiti - DreamScape\n	- RockWorm - Shredder - Fido - Dream Warrior - Sprog!!\n	- and all the other guyz I forgot!!\n\nOthers	- SigmaSeven - Dan! - Marigold - Ice D - Solo - MyMurth\n	- Vindex - The Black Cat - Astropath - Beast - Skol -\n	- Groo - Samir\n\n	  If I missed you out and you think you should be here then\n          gimme some shit and maybe Ill remember next time!\n\nTHANK YOU for taking the time to at least look at this utility!! There''s\ntoo many lazy fucker SysOps out there who just let the best utils slip by\nthem coz they don''t bother to look at the new stuff... If you liked this\nor any other Anthrox util, why not spread the word, and get the world\nrunning our Good Looking and FAST utils, and rid the modem world of Ugly,\nBadly designed, and SLOW (Like C and Basic and ARexx) Utils!! Only the\nBEST will do!\n\n			Thrash!	1993\n@ENDNODE\n@REMARK [*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*][*]\n','\n',char(10)),NULL,'auto-added',38926,7,0,NULL,NULL,'thrashbr','scan',1780048775);
INSERT INTO door_catalog VALUES('thrashc','THRASHC.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/THRASHC.LHA','TComm','XIM','TComm',NULL,NULL,NULL,NULL,replace('lost desc \n','\n',char(10)),'ThrashComment.readme',replace('Short:    Sysop comment door.\nUploader: Leo Davidson <[email removed]>\nAuthor:   Tony Witchet <NO EMAIL ADDRESS>\nType:     comm/amiex\n\nThrashComment - ThrashComment v1.00 by Thrash. (Assembler)\n\n- Sysop Comment Door.\n\n*** This archive is *not* *new*, I am just putting all the Gods''Gift utils\n*** on Aminet for everyone (and so that people can stop bothering me :-).\n\n .--------------------------------------------- ----- ---- --- -- -  -   -  |\n | Leo ''Nudel'' Davidson - Yr1 Computation - [email removed] |\n |  -   -  - -- --- ---- ----- ---------------------------------------------''\n','\n',char(10)),NULL,'auto-added',7088,2,0,NULL,NULL,'thrashc','scan',1780048775);
INSERT INTO door_catalog VALUES('thrashco','THRASHCO.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/THRASHCO.LHA',NULL,'XIM','TConf2.EXE',NULL,NULL,NULL,NULL,replace('lost desc \n','\n',char(10)),'TConf2.Guide',replace('@database "TConf_V2.14_DOCS"\n@REMARK History at the end.\n@REMARK .-------------------------------------------------------------------.\n@REMARK |   ThrashConfV2.20, HyperText docs written by Thrash of ANTHROX.   |\n@REMARK `-------------------------------------------------------------------''\n@REMARK You need Multiview, AmigaGuide, or some other .Guide viewer.\n@REMARK Don''t be a fucking loser and view this with a standard ASCII viewer!!\n@REMARK $VER: Guide for TConf v2.20 (23rd Aug 1994)\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@INDEX DIRECTORY\n@NODE MAIN "TConf: Contents."\n                    ___  _   _ _____ _   _ ____   _____  __     \n             __/\__/ _ \I \ I I_   _I I I I  _ \ / _ \ \/ /_/\__\n             \    / I_I I  \I I I I I I_I I I_) I I I \  /\    /\n             /_  _\  _  I I\  I I I I  _  I  _ <I I_I /  \/_  _\\n               \/ I_I I_I_I \_I I_I I_I I_I_I \_\\___/_/\_\ \/\n                              -*- PRESENTS -*-\n    .-------------------------------------------------------------------.\n    |          TCONF V2.20 RELEASE 2   (Conference Access Lister)       |\n    |         Written By THRASH Of ANTHR0X, ©1994/05 Gods''Gift.         |\n    |    (For ALL Versions And Variants Of Ami-Express BBS Software)    |\n    `-------------------------------------------------------------------''\n                              @{" What Is TConf? " Link WhatIs}\n                            @{" Noteable Features " Link Features}\n                      @{" Installation/Icon Requirements " LINK Installing}\n                           @{" Icon ToolTypes Used " LINK ToolTypes}\n                     @{" Running The Door From Ami-Express " LINK Running}\n                               @{" Main Index " LINK Directory}\n                            @{" Thanks And Greets " LINK Greets}\n                          @{" Other Gods''Gift Utils " LINK Others}\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE WhatIs "TConf: What IS it?"\n\n	TConf Is Quite Simply A Conference Access Lister Door. I Know Your\nThinking That The Two or Three Already In Exsistence Are Slow So How The\nHell Can This Be A Door? Well, TConf Can Update In REALTIME in Under A\nSecond Due To It Being Written Entirely In Assembler. Try It Once And You''ll\nThrow Away The Others For Good! Just Take A Look At Some Of The @{"Features"Link Features}.\nTConf Is Compatable With All Versions Of Ami-Express Including S-Express By \nSigma-Seven.\n\n        A Quick Note To Chart-Loosers. If Your Gonna Vote On Any Sad,\nFake,Fixed Charts, At Least Make Sure You Get It Right!. Dont Vote For\nEither Myself Or P0T-N00dle As Individuals. We BOTH Do all The Work -\nTake A Look At The @{"Releases" LINK Others} We Have Both Done For You\nAll So Far!. Please Vote For Us As:\n\n                          GODS''GIFT/ANTHROX\n\nPS: If Somebody Else Asks P0T-N00Dle About "HIS" Tbar/TTop Etc, Ill Blow\n    A Fuckin Fuse! HeHe.\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE Features "TConf: Features"\n\n     o - The GodsGift Seal Of Quality (Even More Rigorous Than Nintendo!)\n     o - 100% Assembly Language (As Always!).\n     o - 32 Node Compatable.(Actually 100!).\n     o - Compatable With ALL versions And Variants Of Ami-Express.\n     o - Can Be Run Resident.\n     o - RealTime Update Cause You Aint Never Seen One THIS Fast Before!\n     o - Using Nice And Easy Icon ToolTypes For ALL Command Options.\n     o - Can Display ANY Mixture Of conferences/Access "AREAS".\n     o - Optional HeaderFile Display.\n     o - Optional TailerFile Display.\n     o - Optional Statistics Bar.\n     o - Optional ClearScreen For Faster Ansi Displays & lazy Sysops.\n     o - Optional Password Protection (With Failure Comments To Callerslog).\n     o - Configurable Password Attempts.\n     o - One-Time-Passwords!!! (This one Is NICE for The Users!)\n     o - Fluffy Sheep Jumping On Pink Clouds All Over The Place.\n     o - I Was 100% Sober ThroughOut ALL coding.. (Well Almost!)\n     o - Not One Mention Of Fish-Fingers (SHIT!)\n     o - These Are Getting Silly.\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE Installing "TConf: Installation"\n\n\n\n\n\nWhich Version Of Expess Are You Running?\n\n\n         @{" Version 2.x +/Variant " Link InstallingV2}  ........ Non-Icon Versions\n         @{" Version 3.x +/Variant " Link InstallingV3}  ........ Icon/ToolType Versions\n\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE InstallingV3 "TConf: Installation Express V3.x+"\nMake An Icon In Your Commands/BBSCMD (Or Commands/ConfX) Directory With\nThe Following ToolTypes:\n\nLOCATION=Path And Name Of This Util (Ie DOORS:TCONF2)\nMULTINODE=YES\nTYPE=XIM\nSTACK=4096\n\nNow Make An Icon (One Is Supplied In This Archive) For TConf2 Itself. You\nCan Rename The Util To Whatever You Wish So You Can Run Multiple Versions\nFor Different Conferences/Areas. Just Remember To Make The Icons For EVERY\nCopy You Want To Use. All Options Are Controlled By The Doors Icon \n@{"ToolTypes"Link ToolTypes} For Ease Of Use For Users Of Ami-Express V3+.\nAn Example Icon Is Supplied WIthin This Archive.\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE InstallingV2 "TConf: Installation Express V2.x+ / Variant"\n\nCopy The Main Executable File To Your Doors Directory Or WhereEver You Want\nit. Make An Icon For The Util To Get Its Options From The @{"ToolTypes"Link ToolTypes}.\n\nYou Can Rename The Util To Whatever You Wish So You Can Run Multiple\nVersions For Different Conferences/Areas. Just Remember To Make An Icon And\nAn EXE For EVERY Different Copy You Want To Use. An Example Icon Is Supplied\nWIthin This Archive.\n\n\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n\n\n@NODE ToolTypes "TConf: Icon ToolTypes"\n\nThese Are All The ToolTypes Available To The Sysop:\n\n\n            @{" USER_DATA= " Link USER_DATA}  ........ Full Path/Name Of UserData.\n            @{" ACCESS_AREAS= " Link ACCESS_AREAS} ...... Area Names / Conference Numbers.\n            @{" HEADER_TEXT= " Link HEADER_TEXT} ....... Header Text To Be Displayed.\n            @{" TAILER_TEXT= " Link TAILER_TEXT} ....... Bottom Text To Be Displayed.\n            @{" CLEAR_SCREEN= " Link CLEAR_SCREEN} ...... Clear Sceen Before Any Output.\n            @{" STATS_BAR= " Link STATS_BAR} ......... Small Stats Bar Underneath Users.\n            @{" CONF_NAME= " Link CONF_NAME} ......... Name Of Conference To Be Displayed.\n            @{" PASSWORD= " Link PASSWORD} .......... Password Required To Continue.\n            @{" PASSWORD_TRIES= " Link PASSWORD_TRIES} .... Allowed Password Attempts.\n            @{" HACK_TEXT= " Link HACK_TEXT} ......... HangUp Text To Be Displayed.\n            @{" ONE_TIME_PASSWORD= " Link ONE_TIME_PASSWORD} . Special Type Of PassWord.\n            @{" EXPRESS_VERSION= " Link VERSION} ... Version/Variant Number Of Ami-Express.\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE USER_DATA "TConf: ToolTypes - USER_DATA"\n\nUSER_DATA=X\n\nThis ToolType MUST Exist. "X" Is Simply The FULL Path AND Name Of Your\nUserData File ie:\n\nUSER_DATA=BBS:USER.DATA\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE ACCESS_AREAS "TConf: ToolTypes - ACCESS_AREAS"\n\n\nWhich Version Of Expess Are You Running?\n\n\n         @{" Version 2.x +/Variant " Link ACCESS_AREAS_V2}  ........ Non-Icon Versions\n         @{" Version 3.x +/Variant " Link ACCESS_AREAS_V3}  ........ Icon/ToolType Versions\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE ACCESS_AREAS_V3 "TConf: ToolTypes - ACCESS_AREAS /X3+"\n\nACCESS_AREAS=AREANAME1;AREANAME2 Etc..\n\nThis Is The Name Of The Area Used In Your "Access" Drawer. Multiple Areas\nCan Be Used But Each Area MUST Be Seperated By a Semi-Colon ";". Ie..\n\nACCESS_AREAS=SYSOP;NEWUSERS        - Show Users Whose "AREA" Is SYSOP Or\n                                     NEWUSERS.\n\nOr\n\nACCESS_AREAS=SYSOP;SPECIAL_USERS;AMIGA;CONSOLE\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE ACCESS_AREAS_V2 "TConf: ToolTypes - ACCESS_AREAS /X2+"\n\nACCESS_AREAS=X;X;X Etc......\n\n\nWhere "X" Is The NUMBER Of the COnference You Want TConf To Display. You\nCan Use Multiple Conferences But Each Must Be Seperated By A Semi-Colon (;).\nIe:\n\nACCESS_AREAS=5          - Show Users With Access To Conf 5.\n\nOr\n\nACCESS_AREAS=5;9;1      - Show Users With Access To Confs 5;9 And 1.\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE HEADER_TEXT "TConf: ToolTypes - HEADER_TEXT"\n\nHEADER_TEXT=X\n\nWhere "X" Is The FULL Path AND Name Of A Header/Logo Text You Wish To Be \nDisplayed BEFORE Any User Information Is Shown.Ie\n\nHEADER_TEXT=BBS:SCREENS/AMIGA/ACCESS_LOGO1.TXT\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE TAILER_TEXT "TConf: ToolTypes - TAILER_TEXT"\n\nTAILER_TEXT=X\n\nWhere "X" Is The FULL Path AND Name Of A Tailer/Logo Text You Wish To Be \nDisplayed AFTER Any User Information Has Been Shown.Ie\n\nHEADER_TEXT=BBS:SCREENS/AMIGA/ACCESS_BOTTOM.TXT\n@ENDNODE\n@NODE CLEAR_SCREEN "TConf: ToolTypes - CLEAR_SCREEN"\n\nCLEAR_SCREEN=YES/NO\n\nIf You Wish The Screen To Be Cleared BEFORE Any Text Is Shown Then Make\nThis YES. It Just Saves Lazy Sysops From Including A Screen Clear On Logos.\nAnd Of Course Will Mean The Screen Update Will Be Slightly Faster Due To\nNo "Scroll-Up" By Ami-Express.\n\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE STATS_BAR "TConf: ToolTypes - STATS_BAR"\n\nSTATS_BAR=YES/NO\n\nIf You Wish The One Line Of Quick-Stats To Be Displayed At The Bottom Then\nSet This To YES. It Will Take The Util NO LONGER To Execute So You May As\nWell Leave It In, Unless You Simply Dont Like The Idea.\n@ENDNODE\n@NODE CONF_NAME "TConf: ToolTypes - CONF_NAME"\n\nCONF_NAME=YES/NO\n\nAfter The Logo/ClearScreen But BEFORE The Users Are Displayed To The Screen,\nYou Can Have The Conference Name From Which The Util Was Run Displayed At The\nTop Of The Ansi Output. Simply A Yes/No Option. NOTE: I said The Name Of\nThe Conference TConf Was Run FROM. *NOT* The Conference/s You Have Put Into\nThe @{" ACCESS_AREAS= " Link ACCESS_AREAS} ToolType.\n\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE PASSWORD "TConf: ToolTypes - PASSWORD"\n\nPASSWORD=XXXX....\n\nIf TConf Finds This ToolType Present With A Valid Password It Will Ask\nThe User To Input The Correct Password Before It Will Let Him Exit The\nUtil And Proceed Within The Conference. This Is Mainly Here For Those\nSysops Who Wish To Run This Door As Soon As A User Has Joined A Private\nConference. The Password Can be ANY combination Of Numbers/Letters Etc,\nUpto A Maximum Limit Of 59 Characters. The Check Made Is NOT Case Sensitive\nCause That Only Would Piss Legitimate Users Off! The User Will Be Given\n3 Attempts To Enter The Correct Password Followed By Return. If They\nFail All 3 Attempts TConf Will Legally Drop Carrier On The User And Notify\nThe Sysop By Leaving A Suitable Comment Attached To The Nodes CallersLog.\nAmi-Express Will Then Reset The Node And Await The Next Caller.\n\n\n\nSee Also: \n\n@{" PASSWORD_TRIES= " Link PASSWORD_TRIES},@{" ONE_TIME_PASSWORD= " Link ONE_TIME_PASSWORD},@{" HACK_TEXT= " Link HACK_TEXT}\n\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE PASSWORD_TRIES "TConf: ToolTypes - PASSWORD_TRIES"\n\nPASSWORD_TRIES=X\n\nWhere X Is A Number Between 1 And 9. This Tells TConf How Many Attempts\nAt Getting The Correct PassWord Are Allowed Before The User Is Kicked\nOff The Board. If This ToolType Is NOT Found Then TConf Will Default To\n3 Attempts If PassWords Are Required.\n\n\nSee Also: \n\n@{" ONE_TIME_PASSWORD= " Link ONE_TIME_PASSWORD},@{" HACK_TEXT= " Link HACK_TEXT},@{" PASSWORD= " Link PASSWORD}\n\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE HACK_TEXT "TConf: ToolTypes - HACK_TEXT"\n\nHACK_TEXT=X\n\nWhere X Is The FULL Name And Path Of A Text File The Sysop Wants To Be\nDisplayed Just Before A User/Hacker Is To Be Kicked Off The BBS. Ie\n\nHACK_TEXT=BBS:DOORS/TCONF/FUCK_OFF.TXT\n\n\n\nSee Also: \n\n@{" PASSWORD_TRIES= " Link PASSWORD_TRIES},@{" ONE_TIME_PASSWORD= " Link ONE_TIME_PASSWORD},@{" PASSWORD= " Link PASSWORD}\n\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE ONE_TIME_PASSWORD "TConf: ToolTypes - ONE_TIME_PASSWORD"\n\nONE_TIME_PASSWORD=YES/NO\n\nThis Is A Special PassWord Option. In Order For This To Run Correctly\nYou Will Need To Have An Assigned T: Directory. When A User Logs On\nAnd Correctly Gets The PassWord To A Particular Conference A SMALL File\nIn Your T: Dieectory Will Be Created By TConf. If He Rejoins This Same\nConf He Will NOT Need To Type In The PassWord Again. TConf Will Keep \nTrack Of ALL Conference PassWords Correctly Accessed By The User And \nNot Ask For Them A Second Time. This Even Tracks If The User Uses "RL" \nTo Re-Logon Or Simply Calls The Same Node Again Before Any Other Users.\n\n           Although A Good Idea (Thanks T.G.R!), This Way Of Doing\nThings Does Have A slight Problem. If A Hacking User Logs OnTo The Board\nStraight After The Legitimate User Has Called He Would Have Access\nTo The Protected Conference (DUMB!!). A Simple Way Of Stopping This \nProblem Is To Delete The File Created In The T: Directory In That \nParticular Nodes Logoff-Script. So Simply Add To Each Nodes Logoff-Script\nThe Following Line:\n\nDELETE T:TConfUser_NodeX     << "X" Is The Node Of The Logoff-Script!!\n\nThis Will Mean The User WOULD Be required To Insert The Correct PassWord\nIf He Re-Logs On Or Is The Next Person To Call The SAME Node, And Gets\nRid Of The Hacker Problem. I could Have Built This In But It Would Mean\nYou Would Have To Run A Second Util As Your "G" Or "RL" Commands And\nThis Was Thought To Be NOT A Good Idea. (Even If "G" Doors Do Suk In My\nBooks!)\n\n          Its A Little Hard To Explain How It Works So Try It Out And \nSee For YourSelf. A Nice Idea, But ,Of Course, Its Only Optional!\n\n   If This ToolType Does NOT Exist, Then TConf Will Default To NO.\n\nSee Also: \n\n@{" PASSWORD_TRIES= " Link PASSWORD_TRIES},@{" HACK_TEXT= " Link HACK_TEXT},@{" PASSWORD= " Link PASSWORD}\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE VERSION "TConf: ToolTypes - EXPRESS_VERSION"\n\nEXPRESS_VERSION=X\n\nWhere "X" Is the MAIN Version Number Of The Express/Express Variant You Are \nUsing. TConf Of Course CAN Find The Internal Version By Itself (Which It \nDoes By Default If This ToolType Does NOT Exist), However This Will Allow\nThe Variant Programmers Who Are Using The OLD! Version 2 Release To Upgrade\nTheir Version To Number To 3 Without This Util Screwing Up On Them. \nIe If your Version Of Express Uses Icon ToolTypes For Everything Then:\n\nEXPRESS_VERSION=3\n\nEXPRESS_VERSION=4\n\nIf,However You Are Using S-Express 3 (If There Ever Is One), But It DOESNT\nUse Icon ToolTypes Then You Should Have:\n\nEXPRESS_VERSION=2\n\n\nWas That Simple Enough For You???.. Now You Can Upgrade The Version Number\nProperly Stefan!\n\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE RUNNING "TConf: Running From Ami-Express."\n\nYou Have Two Choices For Running TConf. Any Sysop Should Know What They Are.\nSimply Have The User Type In Whatever You Have Setup For The Door TO Run. Ie\nIn This Archive They Would Type In "ACCESS" And Be Told What Users Have \nAccess To The Confs Desribed In The ToolTypes. Or You Can Set It Up To Run\nIn An MCI script. For Instance Your NewUsers/Bull100.Txt May Say...\n\n~\n~CC_ACCESS\n\nWhich In MCI-Script Language Tells Ami-Express To Run The Door Called\nACCESS Rather Than Display This As A text File. Simple Stuff Eh?\n\nAlso See Notes On @{"Installation "Link Installing}.\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE DIRECTORY "TConf: Main Index."\n\nHelpful Index Aint I???\n\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE Greets "TConf: Thanks And Greetings."\n                            ____.___.                               \n       _________._________I    I_  I____.________ _______ ____ ____ \n       \____    _   __   \    __/ _I    I_  _    \   _   \    I  _/ \n       /        I    I    \    I  \.    I  _/   _/   I    \_      \ \n       \___I    I    I____/    I___I    I___\    \________/   I____\\n           `----''----''    `----''   `----''    \____/      /____Ie  \n\nThanks To My Beta-Testers Who This Time Were: \n\n                    Ice D / Sysop BURGERBAR ATX-UKHQ.\n                 Picard / Sysop USS ENTERPRISE ATX-WHQ.\n\nGreetings To ALL The Following (And Many Forgotten) For Their FriendShip\nAnd Work (No Firkin Order!!) :-\n\n                   ALL MEMBERS Of ANTHROX WORLDWIDE\n\n             PRESTiGE, PARADOX, DELiRiUM, FAiRLiGHT, GOD\n\n\nIf You Feel The Need To Get Sommit Off Your Chest Or Wish To Bore Me\nShitless With Your "AMAZING" Ideas For A New Util Hehe. Then Call One Of\nThe WorldWide Anthrox Boards. If You Are Further Interested In GODSGiFT\nUtils Then A Special Conference Has Been Set Up On Our EHQ (BURGERBAR!),\nWhere You Can Chat To Myself And Pot-Noodle About Them.\n\n+-------------------------------------------------------------------------+\n| USS ENTERPRiSE ... +1-412-233-2611   USS ENTERPRiSE ... +1-RiNG-D0WN!!! |\n| USS ENTERPRiSE ... +1-RiNG-D0WN!!!   USS ENTERPRiSE ... +1-RiNG-D0WN!!! |\n| USS ENTERPRiSE ... +1-RiNG-D0WN!!!   USS ENTERPRiSE ... +1-RiNG-D0WN!!! |\n| BURGER BAR ....... +44-PRi-VATE!!!   BURGER BAR ....... +44-RiNG-D0WN!! |\n| CONSOLiA ......... +32-11-234-523!   CONSOLiA ......... +32-11-234-872! |\n| SYNERGY .......... +49-PRi-VATE!!!   SYNERGY .......... +49-PRi-VATE!!! |\n| SYNERGY .......... +49-***-ISDN!!!   SYNERGY .......... +49-***-ISDN!!! |\n| METROPOLIS ....... +34-XXXX-XXXX!!   METROPOLIS ....... +34-XXXX-XXXX!! |\n| TRADE LINE ....... +1-XXXX-XXXX!!!   TRADE LINE ....... +1-XXXX-XXXX!!! |\n| THE WALL ......... +44-PRI_VATE!!!       ***** SPACE F0R RENT!! *****   |\n+-------------------------------------------------------------------------+\n                         -* SPECiAL REGARDS TO -*-\n              PRESTiGE, PARADOX, REDNEX, DELiRiUM, FAiRLiGHT.\n\n\n\n\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE Others "TConf: Other Gods''Gift Releases"\nThere should be a directory that came with this archive containing lots of\nexample outputs from a selection of the utils featured below.\n\nContents: G''G Release History.\n=============================================================================\n:::::::::::::::::::::::::  GODS''GIFT/ATX RELEASES  ::::::::::::::::::::::::::\n=============================================================================\nDates are the release/completion dates of the latest update.\nLatest releases at the top!...\n=============================================================================\nATX-TC22.LHA | 16-Feb-95 | ThrashConf V2.20 (68000) Thrash of Anthrox\n-------------+-----------+---------------------------------------------------\n Release [2] | Purpose:  | Small bug fixed.\n             |           | \n=============================================================================\nATX-TC2.LHA  | 09-Sep-94 | ThrashConf V2.14 (68000) Thrash of Anthrox\n-------------+-----------+---------------------------------------------------\n Release [1] | Purpose:  | Conference Access Lister Door For ALL /X Versions\n-------------+-----------+---------------------------------------------------\n             | Extras:   | FAST code. Can be made RESIDENT.\n             |           | 32 Node/Multi-Node Compatable (Upto 100 nodes!!)\n             |           | Compatable With ALL Versions Of Ami-Express.\n             |           | Optional Header/Tailer TEXTS.\n             |           | Any Number Of Single/Mixed "Areas"/Conferences.\n             |           | REALTIME Updated Cause This One Is FAST!.\n             |           | Using Icon TOOLTYPES As Standard For The 1st Time.\n             |           | Optional User STATISTICS Bar At Bottom.\n             |           | Option To Display COnference Name.\n             |           | Optional SCREENCLEAR For Lazy Text Makers/Sysops.\n             |           | Optional PASSWORD Protection.\n             |           | PassWord HACK Attempts Logged To CallersLog.\n             |           | Optional Text Displayed On Drop Carrier.\n             |           | Configuarable Amount Of PassWord Attempts.\n             |           | One-Time-PassWords. User Has To Only Enter Pass-\n             |           | Word Once, Including Re-logons Etc! Till Node Is\n             |           | Used By Different User.\n=============================================================================\nATX-SDC1.LHA | 04-Apr-94 | Super-DupeCheck v1.0 (68000) P0T-NOoDLE of Anthrox\n-------------+-----------+---------------------------------------------------\n Release [1] | Purpose:  | Dupe-Checker & FileCheck Handler Door.\n-------------+-----------+---------------------------------------------------\n             | Extras:   | FAST code. Can be made resident.\n             |           | Can run infinite other filechecker-type doors.\n             |           | Can display infinite text files. (Global & Conf)\n             |           | Cool percentage-done progress bar!\n             |           | 32-Node compatable. (Actually, upto 100nodes)\n             |           | "Script"-style config file for versatility\n             |           | Skips archive-checking if file is duped.\n             |           | Allows for DupeChecking to be skipped for Named\n             |           | Allows for DupeChecking to be skipped for Access\n             |           | Allows for a special Dupe-Checker filelisting\n             |           |    that is checked by not viewable by users.\n             |           | Allows for DupeChecking only on selected DirFiles\n             |           | Allows for a special Global-Dupe-Dir listing that\n             |           |    is seached for uploads in ALL conferences.\n             |           | Actual DupeChecking does NOT have to be performed.\n             |           |    Can be used to display messages and run doors.\n             |           | Can check for Dupes where *.LHA = *.ZOO etc.\n             |           | Skips DupeCheck on private uploads.\n=============================================================================\nATX-TCOM.LHA | 01-Oct-93 | ThrashComment v1.00  (68000)     Thrash of Anthrox\n-------------+-----------+---------------------------------------------------\n             | Purpose:  | Sysop Comment Door.\n-------------+-----------+---------------------------------------------------\n             | Extras:   | Will use any number of sysops between 1 and 99.\n             |           | Header/Tailer texts. Special External file option\n             |           | to display your own ansi instead of the built-in\n             |           | defaults to make it look how YOU want it.\n=============================================================================\nATX-SAL5.LHA | 20-Aug-93 | Super-AmiLog v2.00   (68000) P0T-NOoDLE of Anthrox\n-------------+-----------+---------------------------------------------------\n Release [5] | Purpose:  | Create a list of the last callers.\n-------------+-----------+---------------------------------------------------\n             | Extras:   | Keeps records of best number of callers etc in\n             |           | one day. Outputs a list of weekly statistics with\n             |           | info on the last 7 days, and the weekly averages.\n             |           | MULTI-NODE compatable. 0 to 20 callers shown.\n             |           | Non-ANSI mode. Header/Tailer texts. Random 1 line\n             |           | messages. Can be made Resident. Docs built into\n             |           | the util. Mini-Callerslog made with compact info\n             |           | about each call. For each user, can show Baud,\n             |           | Node,Name,Location,Connect Time,Logoff Time,\n             |           | Time Spent Online, Up/Down KBytes,Actions.\n             |           | Actions include: Up/Download,Up/Download Failed,\n             |           | Password Hack,Lost Carrier,Paged Sysop,Sysop Cmds.\n             |           | Shows: Calls Today/Yesterday,Up/Down Files/Bytes\n             |           | today, and finally Hours used today.\n=============================================================================\nATX-NEWL.LHA | 12-Jun-93 | Super-NewLst v1.00   (68000) P0T-NOoDLE of Anthrox\n-------------+-----------+---------------------------------------------------\n             | Purpose:  | Make a list of all new users waiting for access.\n-------------+-----------+---------------------------------------------------\n             | Extras:   | Lists 3 users per line for compact output.\n             |           | Put it as a bulletin on your BBS and your users\n             |           | can let you know if any of the new guys are OK...\n=============================================================================\nATXTBAR1.LHA | 23-May-93 | ThrashBar    v1.01   (68000)     Thrash of Anthrox\n-------------+-----------+---------------------------------------------------\n             | Purpose:  | BarCharts of Top Up/Down Bytes, Up/Down Files,\n             |           | Callers, Message Writters. \n-------------+-----------+---------------------------------------------------\n             | Extras:   | Exclude users (by number or sec level).\n             |           | 0 to ALL users shown on Chart. User Ratings.\n             |           | Non-ANSI Mode. Header file. Random 1 Line Msgs.\n             |           | Shows overall BBS statistics: megs/files up/down,\n             |           | number of leeches/elites/normals. Built in Docs.\n             |           | Archive contains .GUIDE (hypertext) docs.\n=============================================================================\nATX-TT15.LHA | 23-May-93 | ThrashTop    v1.05   (68000)     Thrash of Anthrox\n-------------+-----------+---------------------------------------------------\n             | Purpose:  | Normal Chart of Top Up/Down Loaders.\n-------------+-----------+---------------------------------------------------\n             | Extras:   | Unlimited Header/Tailer texts.\n             |           | 0 to ALL users shown on Chart. User Ratings.\n             |           | Also shows users'' Location,Messages,Calls,Files up\n             |           | Shows overall BBS statistics: megs/files up/down,\n             |           | number of leeches/elites/normals. Built in Docs.\n=============================================================================\nATX-STAT.LHA | 23-May-93 | ThrashStat   v1.03   (68000)     Thrash of Anthrox\n-------------+-----------+---------------------------------------------------\n             | Purpose:  | Create a list of all users and their statistics.\n-------------+-----------+---------------------------------------------------\n             | Extras:   | Shows users'' Number,Name,Location,Up/Down Bytes,\n             |           | Up Files,Calls,Messages Written.\n             |           | Shows total number of Users,Uploads,Msgs, etc.\n=============================================================================\nATX-STC3.LHA | 18-Jan-93 | Super-TopCPS v1.06   (68000) P0T-NOoDLE of Anthrox\n-------------+-----------+---------------------------------------------------\n Release [3] | Purpose:  | Create a list of the best CPS rates.\n-------------+-----------+---------------------------------------------------\n             | Extras:   | Never "forgets" CPS rates because it stores then\n             |           | in it''s file! Shows 0 to 20 users. Head/Tail file.\n             |           | Shows: Username,Date of CPS rate,Filename used,\n             |           | wether it was an Up/Download,Baud Rate,CPS rate.\n=============================================================================\nATX-TCON.LHA | 02-Oct-92 | ThrashConf   v1.00   (68000)     Thrash of Anthrox\n-------------+-----------+---------------------------------------------------\n             | Purpose:  | Create a list of all users with access to a conf.\n-------------+-----------+---------------------------------------------------\n             | Extras:   | Shows 3 users per line for compact output.\n             |           | Great for those private conferences!\n=============================================================================\n:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::\n=============================================================================\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n','\n',char(10)),'{"LOCATION":"Path","TYPE":"XIM","STACK":"4096"}','auto-added',24837,2,0,NULL,NULL,'thrashco','scan',1780048775);
INSERT INTO door_catalog VALUES('thrashs','THRASHS.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/THRASHS.LHA',NULL,'XIM','TStat1.3',NULL,NULL,NULL,NULL,replace('lost desc \n','\n',char(10)),'ThrashStat.readme',replace('Short:    User statistics listing util.\nUploader: Leo Davidson <[email removed]>\nAuthor:   Tony Witchet <NO EMAIL ADDRESS>\nType:     comm/amiex\n\nThrashStat - ThrashStat v1.03 by Thrash. (Assembler)\n\n- Create a list of all users and their statistics, as well as BBS stats.\n\n*** This archive is *not* *new*, I am just putting all the Gods''Gift utils\n*** on Aminet for everyone (and so that people can stop bothering me :-).\n\n .--------------------------------------------- ----- ---- --- -- -  -   -  |\n | Leo ''Nudel'' Davidson - Yr1 Computation - [email removed] |\n |  -   -  - -- --- ---- ----- ---------------------------------------------''\n','\n',char(10)),NULL,'auto-added',3083,2,0,NULL,NULL,'thrashs','scan',1780048775);
INSERT INTO door_catalog VALUES('thrashto','THRASHTO.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/THRASHTO.LHA',NULL,'XIM','TTop1.5',NULL,NULL,NULL,NULL,replace('lost desc \n','\n',char(10)),'ThrashTop.readme',replace('Short:    Top uploader, message writter, etc.\nUploader: Leo Davidson <[email removed]>\nAuthor:   Tony Witchet <NO EMAIL ADDRESS>\nType:     comm/amiex\n\nThrashTop.lha - ThrashTop v1.05 by Thrash. (Assembler)\n\n- Normal Chart of Top Up/Down Loaders, message writters, and so on.\n* Like ThrashBar, but instead of barcharts displays user''s location, etc.\n\n*** This archive is *not* *new*, I am just putting all the Gods''Gift utils\n*** on Aminet for everyone (and so that people can stop bothering me :-).\n\n .--------------------------------------------- ----- ---- --- -- -  -   -  |\n | Leo ''Nudel'' Davidson - Yr1 Computation - [email removed] |\n |  -   -  - -- --- ---- ----- ---------------------------------------------''\n','\n',char(10)),NULL,'auto-added',12404,2,0,NULL,NULL,'thrashto','scan',1780048775);
