INSERT INTO door_catalog VALUES('thrshtop','THRSHTOP.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/THRSHTOP.LHA',NULL,'XIM','TTop1.5','1.04','Thrash/Anthrox',NULL,'--+  Top Uploaders/Msg Writers, Etc.  +--',replace('ThrasTop v1.04 (c> 1992 Thrash/Anthrox\n--+  Top Uploaders/Msg Writers, Etc.  +--\n','\n',char(10)),'ThrashTop.readme',replace('Short:    Top uploader, message writter, etc.\nUploader: Leo Davidson <[email removed]>\nAuthor:   Tony Witchet <NO EMAIL ADDRESS>\nType:     comm/amiex\n\nThrashTop.lha - ThrashTop v1.05 by Thrash. (Assembler)\n\n- Normal Chart of Top Up/Down Loaders, message writters, and so on.\n* Like ThrashBar, but instead of barcharts displays user''s location, etc.\n\n*** This archive is *not* *new*, I am just putting all the Gods''Gift utils\n*** on Aminet for everyone (and so that people can stop bothering me :-).\n\n .--------------------------------------------- ----- ---- --- -- -  -   -  |\n | Leo ''Nudel'' Davidson - Yr1 Computation - [email removed] |\n |  -   -  - -- --- ---- ----- ---------------------------------------------''\n','\n',char(10)),NULL,'auto-added',14106,5,0,NULL,NULL,'thrshtop','scan',1780048780);
INSERT INTO door_catalog VALUES('thr_lhap','THR_LHAP.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/THR_LHAP.LHA','lhapacker10','XIM','+------------------------------------------+',NULL,'Therion','THR','|  Lhapacker v1.0 developed by Therion     | | This door updates a lhapack for your     | | users to dl.                             |',replace('+------------------------------------------+\n|  Lhapacker v1.0 developed by Therion     |\n| This door updates a lhapack for your     |\n| users to dl.                             |\n|- Gives your user the newest version of   |\n|  sysopdeterimined files                  |\n|- Security with usernamecheck if ya want  |\n|- It''s fast.                              |\n|- Made by fanta^Static.                   |\n`------------------------------------------''\n','\n',char(10)),'lhapacker10.doc',replace('\012                               Lhapacker v1.0\012                              by fanta^Static\012\012» Another\012               ____/\_____/\___/\____/\_/\____/\____/\___\012               \___  \   /  /  ___/ _  \  \  _  \___  __/\012                  \   / _   /  __/  _  _/  /  /  /  /  /\012                  /  /  /  /  /  /  /  )  /  /  /  /  /\012                 /  /__/  /_____/__/  /  /_____/__/  /\012                /__/94/__/        /__/__/--------/__/>St\012                                                               Production «\012\012\012                                    Why?\012\012Kid Curry wanted this door so he could have an update made everytime\012a registered S-Express user wanted the newest version of S-Express.\012Of course we made it in C to accomplish some speed.\012\012                              What does i do?\012\012It packs n files with lha and put in to an archive defined by you. It then\012gives the user a chance to download it directly.\012\012                                 Disclaimer\012\012We don''t take any responsibility for any damage this door make on your\012computer hardware or software. It has been fully tested so it shouldn''t\012give ya any problems.\012\012\012                                Installation\012\012You must have C:Lha so the door can pack properly.\012\012                                  /X 2.xx\012\012-Modify your custom-commands and add the following line:\012\012*LHApack  XM010Doors:Lhapacker10/Lhapacker10\012\012^         ^    ^\012|         |    |_ Or wherever you put lhapacker\012|         |\012|         |___ Notice the "X" Lhapacker is an XIM door!\012|\012|______ name to be run from prompt.\012\012\012                                  /X 3.xx\012\012-Copy the icon BBS/Commands/BBsCmd/lhapacker.info to BBS/Commands/BBsCmd/\012 or BBS/Commands/SysCmd/ if u don''t want that LHAPacker can be runned by\012 the prompt.\012\012\012                               Configuration\012\012There are som tooltypes to configurate this door with\012\012OUTPUTLHA=<path:filename>     <--- This is the path and filename to\012                                   archive that will be created\012                                   (ex ram:output.lha)\012                                   This archive will only be temporary\012                                   and will be deleted after it''s dl:ed\012NAME0=<name>                  <--- Usernames allowed to use this door\012.\012.\012NAME99=<name>\012\012ALLNAMESALLOWED               <--- All users can use the door. This\012                                   disables NAMEn=<name>\012\012FILE0=<path:filename>         <--- Files that will be in lha-archive\012.\012.\012.\012FILE99=<path:filename>\012\012\012                            Main Files included\012\012            Filename                                  Org. Size\012\012            BBS/Doors/Lhapacker10/lhapacker10           13184\012            BBS/Doors/Lhapacker10/lhapacker10.030       13184\012            BBS/Doors/Lhapacker10/lhapacker10.040       13184\012            BBS/Doors/Lhapacker10/lhapacker10.doc        5268\012\012\012\012                               Exampel screenshots\012\012-==========->\012\012-(Joyride BBs)- [2:(-`*''-) Elite (-`*''-)] Menu (16630 mins. left): getanswers\012\012LhaPacker v1.0. by fanta/THR & Static/tHr\012\012Packing bbs:node0/answers ...ok!\012Packing bbs:node1/anwers ...ok!\012\012Do ya wish to download the packed file(s)?> Yeah!\012oK! let''s download..\012\012-==========->\012\012-(Joyride BBs)- [2:(-`*''-) Elite (-`*''-)] Menu (16614 mins. left): getanswers\012\012LhaPacker v1.0. by fanta/THR & Static/tHr\012\012Namecheck ...couldn''t find your name!\012Do ya wanna leave a mezz to the sysop?> Yeah!\012\012\012                       (------------------------------)\012     To: (Enter)=''ALL''? fanta\012Subject: (Blank)=abort? Give me axx please!\012\012-==========->\012\012\012\012\012\012\012\012\012\012\012                                 Greating''s\012\012                                   Ju/\n\012                                   Zorlac\012                                  Mr Beta\012                                    BoZ\012                                  Big Boss\012                                  Sandman\012                                  Aquarius\012                                   Dexter\012\012\012\012\012\012\012\012\012\012\012\012\012                            Special Greating to\012\012                     Kid Curry for idea and ßetatesting\012\012\012\012\012\012\012\012\012\012\012\012\012\012\012\012\012\012\012 To provent any backdoors d¡al...    ..to get the orginal & latest version.\012\012\012\012  __________  ___________ ____________\012  \_____  _/  \__  _  __/ \__  |    _/\012   ___|    \  /    |    \  /   ¦     \  +¢6(°)³²²/¹9°97\012  /   |     \/     |     \/    :      \_________________ _ _  _    _\012 /    ¦      \     ¦      \_______     \\012/     :       \    :       \/           \     Sysop¹:Static/aFL^Thr\012\             /            /            /\012 \___________/____________/    ________/      Sysop²:fanta/Thr\012        |                 \_____|\012        |        14400         _________  _______ _________ _____________\012        |     DualStandard     \___   _ \ \___   |\______  \\_____  ____/\012        ¦    DualSysopPower      /    |  \/      |  /  |    \  /    ___|\012        :  Kicking with /X 3.x  /     ___/__     | /   |     \/     |\012        ·                      /            \_   |/    ¦      \     l____\012        .    ·¹·Dayz warez    /     \        /   |     :       \         |\012              Therion WHQ     \      \      /    |     ·       /         |\012        . Online Door Ordering \______\    /_____|____________/__________|\012                                       \__/j\012\012\012\012\012\012[EOF]','\012',char(10)),NULL,NULL,30772,3,0,NULL,NULL,'thr_lhap_lhapacker10','scan',1780048780);
INSERT INTO door_catalog VALUES('thx_wh16','THX-WH16.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/THX-WH16.LHA',NULL,'XIM','LE-window5.exe',NULL,'tNT^tFP!','THX','___ ______  _____  __________    ¬\__ /.      .\     ____) |  ______/ _//        \\_     |   :    |',replace('     __ _____________________________\n   ___ ______  _____  __________    ¬\__\n         /.      .\     ____) |  ______/ \n       _//        \\_     |   :    |\n       \________   ./_____|________|\n ·========TNT!l____/======================·\n     THX-WHO! V1.6 FOR S!X & /X SYSTEMS \n       WHO-DOOR WiTH EXCELLENT DESiGN\n  [THX] ARTiFiCiAL CODiNG WORX BY tNT^tFP!\n .========================================.\n `---> TRACKERS - DAS BESTE AM NORDEN <---''\n[28k8] )-( lEECHED fROM pLANET-X! )-( [28k8]\n','\n',char(10)),'THX-WHO!.DOC',replace('\n  ·========================= [ BEGIN OF FILE! ] =========================·\n                     __ _____________________________\n                   ___ ______  ______  _________    ¬\__\n                         /.      .\     ____) |  ______/ \n                       _//        \\_     |   :    |\n                       \________   ./_____|________|\n                 ·========TNT!l____/=====================·\n\n  .-----------------------[ PRESENTS 2DAY: ]----------------------------.\n  |---------------------------------------------------------------------|\n  | - THX-WHO! V1.6 FOR S!X & /X - KiCK UGLY WHO-DOORS! USE THiS ONE! - |\n  |---------------------------------------------------------------------|\n  `---------------------------------------------------------------------''\n    ================ ALL CøDiNG DøNE BY: tENtAClE^tFP! ================\n\n    .-----------------------------------------------------------------.\n    |   [THX] (TRACKERS''S HANDS ON XPREZZ) ARE: tNT/tFP! - MAD/tFP!   |\n    `=================================================================''\n\n -------------------------------------------------------------------------\n\n  REQUIRES:\n\n  o SiGMA-EXPRESS Vx.xx / AMi-EXPRESS V3.xx\n\n  o AEDoor.library ( © SiNTAX/WOT) - included!\n\n -------------------------------------------------------------------------\n\n [=======================================================================]\n\n    AAAAAAAAAAAAAAAAAAAAALLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLLRIGHTY THEN!\n\n  Finally I''ve made it: My first coding artworx for epxress ... a lot of\n  work lies behind, many crashes, lots of cigarettes and my sense for\n  humor ... ;)\n\n  But anyway: I wanted 2 start with some easy tools, here is one of them.\n\n  WHO-Doors, WHO-Doors, WHO-DOORS! Thousands, no - MiLLiONS OF THEM you\n  can get in ANY bbs ... Well, but I just simply don''t like most of them,\n  either the style is too bad (Yeah, I know!) or they are coded in AREXX \n  (Sorry ''bout that - I HATE AREXX!)\n\n  That was the fact for me 2 work on an own WHO-Door with some good ansi-\n  style - and there u r : THX-WHO! is born ...\n\n [=======================================================================]\n\n  HOW 2 BUiLD iN:\n\n  I hate this part! Thousands of tools with a doc for building in a door\n  into a bbs, and I have 2 describe it, too ... JUST LEAVE ME ALONE! ;)\n\n  Ok, just as easy as that...\n\n  FOR S!X: Copy the THX-WHO!-Dir into your DOORS: - Directory. Now add\n           the following line 2 your "BBS:COMMANDS/BBS.CMD"-File:\n\n           *WHO      XM010DOORS:THX-WHO!/THX-WHO!.XiM\n             |          |\n             |          `-----------------> Accesslevel\n             `----------------------------> Command for S!X\n\n  The rest should be clear, i think ... ;=) If you can''t build it in like\n  this, then please refer to the textfile included in this archive ( 2 B\n  found in "COMMANDS/S!X/BBS.CMD" ).\n\n  ------------------------------------------------------------------------\n\n  FOR /X: Copy the THX-WHO!-Dir into your DOORS: - Directory. Copy the\n          included icons in this archive ( "COMMANDS/AX!/BBSCMD/WHO.info" )\n          into your "BBS:COMMANDS/BBSCMD/" - Directory.\n\n [=======================================================================]\n\n  LAST WORDS, HOW 2 REACH ME, GREETiNX ETC. :\n\n  No last words - shame on me!\n\n  How 2 reach me? Simple: Call -SYNERGY- (S!X HEADQUARTER) and just have a\n  message to "tENtAClE" for ideas, comments, bug reports etc.\n\n  ------------------------------------------------------------------------\n  Reach me 2 in: PLANET-X - TFP!^GHQ - OPERATOR: MADMAN! - +49-421-5769126\n  ------------------------------------------------------------------------\n\n  Greetinx are going to:\n\n  All members of TFP! - Calypso/GOD - ByteAndi/MST - NoisyBelch/LGC - \n  CøRTeX/TRSi - Aquarius/OTL - Sintax/WOT - Charlie/LSD - SiGMA SEVEN!\n\n                    -=- ... and all I forgot ... -=-\n\n  Special thx go to:\n\n  o SiGMA SEVEN! for the support on coding doors, I''ve never seen a dude\n    like him supporting people so friendly!\n\n  o MADMAN for his beta-testing on my lousy tools ... (HURM!)\n\n   ----------------------------------------------------------------------\n     P.S.: - -- ---+ I JUST LOOOOOOOOOOOOOOOVE SiGMA-EXPRESS! +--- -- -\n   ----------------------------------------------------------------------\n\n  ·========================== [END  OF FILE! ] ==========================·\n','\n',char(10)),NULL,'auto-added',14089,4,0,NULL,NULL,'thx_wh16','scan',1780048780);
