INSERT INTO door_catalog VALUES('tll_ssf','TLL-SSF.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TLL-SSF.LHA',NULL,'XIM','.------------------------------------------.',NULL,NULL,'TLL','| ________SSC!__  |T·H·E  L·O·W·L·I·F·E·S  | |/___  / /   / /  |------------------------. |   / / /___/ /___| THE LOWLIFES PRESENT   |',replace('.------------------------------------------.\n| ________SSC!__  |T·H·E  L·O·W·L·I·F·E·S  |\n|/___  / /   / /  |------------------------.\n|   / / /___/ /___| THE LOWLIFES PRESENT   |\n|  /_/_____/_____/|       TO YOU:          |\n|------------------------------------------|\n|      ««====TLL-STINKstripFile====»»      |\n|                                          |\n|            LHA/LZX Strip file            |\n|     with 523 adverts From JUNE ONLY!     |\n|    Wildcards Included..  JUST USE IT!    |\n`------------------------------------------''\n','\n',char(10)),'uzi.txt',replace('                                            .---------------------------.\n    _______.-----------------._______/|     |     4NODEZ  RiNGDOWN      |\n    \_     |     .------     |________|.....| 73 GiG OF AMiGA CoNSoLE PC|\n   .:|     |     |     ______|        |:::::|  uZiSUiCiDE.sERVEBBS.ORG  |\n  .::|     |     |     |     |        |-----+-----.      TELNET         |\n .:::|           |     |     |       :|     |     |                     |\n.::::\___________|___________|________|     `-----+---------------------''\n:::::::::::::::::|                                | 24HR 7DAY STATiC iP! \n_________________|___________/|__________________/|______________________\n\_     ______    |     _______|          |_____________      _/    _____/\n_|_____    |     |     |      |    |_____|        |   |      |     ___|_ \n|     |    |     |     |      |    |     |        |   |      |     |    |\n|     |    |     |     |     :|          |       :|   |      |     |    |\n|__________|_____|_____|______|__________|________|__________|__________|\n:::::::::::::::::|            |                                         |\n`::::::::::::::::|            |ALWAYS THE LATEST VERSION oF AMi-EXPRESS |\n `:::::::::::::::|            | TONS OF ONLiNE MESSAGES AND MULTi-CHATS |\n  `::::::::::::::`------------+  NUP IS REQUIRED SO ASK WHOEVER POSTED  |\n   `::::::::::::::::::::::::::|    THIS ADVERT FOR THE NUMBER AND NUP   |\n    `:::::::::::::::::::::::::`-----------------------------------------''\n','\n',char(10)),NULL,NULL,10914,6,0,NULL,NULL,NULL,'scan',1780048780);
INSERT INTO door_catalog VALUES('tls_pmc','TLS-PMC.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TLS-PMC.LHA','Pro-MultiCheck','XIM','Pro-MultiCheck',NULL,NULL,'TLS','|_   _|| |EdS| ___| `-| |-''| |__.|___ | |_|  |____||____|',replace('   ._____.._.   .____.\n   |_   _|| |EdS| ___|\n   `-| |-''| |__.|___ |\n     |_|  |____||____|\n     `-''  `----''`----''\n    >>>> Presents <<<<\n   Pro-MultiCheck 0.9b\n DMS and LHA file checker\n','\n',char(10)),'Pro-MultiCheck.Guide',replace('@database Pro-MultiCheck.guide\n@$VER: Pro-MultiCheck.guide v0.9ß (03-Sep-94)\n@width 75\n\n@node MAIN "Pro-MultiCheck Contents"\n                    @{u}Documents for Pro-MultiCheck v0.9ß@{uu}\n\n          Pro-MultiCheck was written by Exodous/TLS, XPR & O.T.T\n                           Released on 03-Sep-94\n\n                     1)  @{" What is Pro-MultiCheck ? " link WHAT_IS_PMC}\n                     2)  @{"       Installation       " link PMC_INSTALL}\n                     3)  @{"    How do I use PMC ?    " link USAGE}\n                     4)  @{"       Distribution       " link DISTRIBUTION}\n                     5)  @{" Registration Information " link REGISTRATION}\n                     6)  @{"     Future Versions      " link FUTURE}\n                     7)  @{"      Contacting Me       " link CONTACT_ME}\n                     8)  @{"         History          " link HISTORY}\n                     9)  @{"      Other Programs      " link OTHER_PROGS}\n                     10) @{"     Acknowledgements     " link ACKNOWLEDGE}\n                     11) @{"        Disclaimer        " link DISCLAIMER}\n                     12) @{"     Registered Users     " link REG_USERS}\n\n               Pro-MultiCheck was written in 100% assembler.\n@endnode\n\n@node WHAT_IS_PMC "What is Pro-MultiCheck"\n                         @{u}What is Pro-MultiCheck ?@{uu}\n\nPro-MultiCheck is (c) 1994 TLS Software and may only be distributed if\nthe appropriate @{" distribution " link DISTRIBUTION} conditions are met.\n\nPro-MultiCheck (PMC) is a file checking program aimed for use by Bulletin\nBoard Systems (BBS''s).\n\nIt''s main aim is to check a lots of different file formats simply in one\nprogram, using a consistent interface.\n\nI think that PMC is unique in the fact that it is the first file checker\nthat can handle multiple file types.\n\nCurrently Pro-MultiCheck is that fastest LhA and DMS checker / stripper\n                                 ^^^^^^^\navailable on the Amiga.\n\nAs this is only version 0.9ß it isn''t as optimised, or as fast as it\ncould be, but for version 1.0 LhA checking, stripping and adding will\nbe significantly faster - I estimate at least 50% faster!!, and PMC will\nbe able to handle other file types.\n\nSee @{" Future versions " link FUTURE} for information on planned features.\n\nThe LHA section covers LHA, LZH, SFX and RUN files.\n\nThe Pro-MultiCheck package was developed in 680x0 assembly language using\nthe following software :\n\n                · Devpac 3.04\n                · CygnusEd Professional\n                · MultiView\n                · Installer 2.15.\n\nPro-MultiCheck needs Kickstart and Workbench 2.04 or better.\nPro-MultiCheck_020 also needs a Motorola 68020 or better CPU fitted to\n yor Amiga.\n\n@endnode\n\n@node PMC_INSTALL "How do I install Pro-MultiCheck ?"\n                     @{u}How do I install Pro-MultiCheck ?@{uu}\n\n@{b}NOTE@{ub} : Pro-MultiCheck v1.0 will come with an installer script for easy\n       installation of Pro-MultiCheck.\n\n                           @{u}General instructions@{uu}\n\nPro-MultiCheck currently needs LhA, by Stefan Boberg, to check LhA files.\n\nMake sure that your LhA file is @{b}NOT@{ub} crunched, if it is then\ndecrunch it, otherwise Pro-MultiCheck will crash.\n\nIf your LhA executable doesn''t reside in the ''C:'' directory then add the\nfollowing line to your ''S:User-Startup'' :\n\n        SetEnv PMC "<location of LhA>"\n\nWhere @{b}<location of LhA>@{ub} is where your LhA executable can be found, eg :\n\n        SetEnv PMC "Work:Utilities/LhA"\n\n\nIf you have a Motorola 68020 processor or better then delete\n''Pro-MultiCheck'' and rename ''Pro-MultiCheck_020'' as ''Pro-MultiCheck''\n\n\n                           @{u}Specific instructions@{uu}\n\nInstallation instructions for :\n\n                       @{" Ami-Express 3.x - 4.x " link INSTALL_AX3}\n                       @{"  CLI or Shell Usage   " link INSTALL_SHELL}\n\nIn version 1.0 there will be documentation on how to install PMC for\nother BBS systems, if you sucessfully install it for a BBS system not\nlisted above then please @{" e-mail " link CONTACT_ME} details to me so that I can put them\nin this documentation.\n\n@endnode\n\n@node INSTALL_AX3 "Installation instructions for Ami-Express 3.x - 4.x"\n            @{u}Installation instructions for Ami-Express 3.x - 4.x@{uu}\n\nType the following lines into a CLI/Shell screen.\n\n1> Copy S/#? all S: QUIET\n1> Copy AX3/#? all BBS: QUIET\n1> Copy Pro-MultiCheck BBS:Utils/\n\nTo change the checking options go into your BBS:FCheck drawer, select the\nicon for the filetype, and select ''Information'' from the menu''s, find the\nline that says ''OPTIONS='' and type in your selected options.\n\nTo edit the banners / adverts to suit your needs see @{" Editing adverts " link EDIT_ADS}.\n\n@endnode\n@node INSTALL_SHELL "Installation instructions for CLI or Shell usage"\n             @{u}Installation instructions for CLI or Shell usage@{uu}\n\nType the following lines into a CLI/Shell screen.\n\n1> Copy S/#? all S: QUIET\n1> Copy Pro-MultiCheck  C:\n\nTo edit the banners / adverts to suit your needs see @{" Editing adverts " link EDIT_ADS}.\n\n@endnode\n\n@node EDIT_ADS "Editing adverts and banners to suit your needs"\n              @{u}Editing adverts and banners to suit your needs@{uu}\n\nOpen a CLI and got to the ''S:PMC'' directory.\n\n@{u}LHA Adverts@{uu}\n\nThe adverts that are added to an LHA file are in the LHA directory,\nthese can be anything from a text file to a 300k demo (not recommended!)\n\nIf any of the files start with ''PMC'', eg ''PMC.txt'' or ''PMC.exe'', when\nthey are added the ''PMC'' will be replaced with a 6 digit random number,\nthis has the advantage that it makes ripping them @{b}VERY@{ub} difficult!\n\nThe file ''LHA.Strip'' is used to store adverts in that PMC doesn''t already\nknow. To add an advert, load the file into an editor, eg CygnusEd and add\nit to the bottom of the file.\n\nIf the advert contains wildcards ( ''*'', ''#'', or ''?'' ), eg ''-?-?-?-'' then\nput square brackets round each wildcard... ''-[?]-[?]-[?]-''\n\n\n@{u}DMS Adverts@{uu}\n\nThe banners that are added to a DMS file are in the DMS directory.\n\nThe following file should be present :\n\n        ''Banner_Front''\n        ''Banner_Rear''\n        ''Track_Zero''\n\nThe files ''Banner_Front''and ''Banner_Rear'' are added to the front and rear\nof the DMS file respectively and should be normal text files.\n\nThe file ''Track_Zero'' is added as the track zero and @{b}MUST@{ub} be 960 bytes\nlong. It should be 15 lines long and 64 characters wide (including the\nreturn character at the end of the line) so that it is display correctly\nwhen the archive is decrunched.\n\n@endnode\n\n@node USAGE "How do I use Pro-MultiCheck ?"\n                       @{u}How do I use Pro-MultiCheck ?@{uu}\n\nTo use Pro-MultiCheck to check an @{b}LHA@{ub} file type the following :\n\nPro-MultiCheck LHA [OPTIONS] <filename>\n\n  @{b}<filename>@{ub} is the file to check and @{b}[OPTIONS]@{ub} are an optional choice\n  from any of these choices :\n\n        @{b}KILL@{ub}    - Remove existing BBS adverts.\n        @{b}ADD@{ub}     - Add your own BBS''s adverts.\n        @{b}COMMENT@{ub} - Add a file comment to the added adverts containing\n                   the date and time that the file was checked.\n\n\nTo use Pro-MultiCheck to check an @{b}DMS@{ub} file type the following :\n\nPro-MultiCheck DMS [OPTIONS] <filename>\n\n  @{b}<filename>@{ub} is the file to check and @{b}[OPTIONS]@{ub} are an optional\n  choice from any of these choices :\n\n        @{b}FRONT@{ub}    - Add a front banner to the file.\n        @{b}REAR@{ub}     - Add a rear banner to the file.\n        @{b}TRACK@{ub}    - Add a track zero banner to the file.\n        @{b}DATE@{ub}     - Add the date and time that the files was checked\n                   to any of the banners, replacing ''##-###-##'' with the\n                   date, and ''##:##'' with the time.\n\n@{b}Examples@{ub}\n\nCheck an LhA file called ''TLS-PMC.LHA''.\n\n    Pro-MultiCheck LHA TLS-PMC.LHA\n\nCheck an LhA file called ''TLS-PMC.LHA'', kill all known adverts from the\nfile, add out own adverts, and add the date/time of the check to the\nadded adverts comments.\n\n    Pro-MultiCheck LHA KILL ADD COMMENT TLS-PMC.LHA\n\nCheck a DMS file called ''DEMO.DMS'', and remove existing banners.\n\n    Pro-MultiCheck DMS demo.dms\n\nCheck a DMS file called ''ABC D.DMS'', remove existing banners and add\nour own banners, with the date and time of upload.\n\n    Pro-MultiCheck DMS FRONT REAR TRACK DATE ABC D.DMS\n\nor\n\n    Pro-MultiCheck DMS FRONT REAR TRACK DATE "ABC D.DMS"\n\n@{b}NOTE@{ub} : The filename @{b}MUST@{ub} be the last item on the line, but it doesn''t\n        have to have quotes round it if it contains spaces.\n\n@endnode\n\n@node DISTRIBUTION "Distribution information"\n                         @{u}Distribution information@{uu}\n\nPro-MultiCheck can be distributed in @{b}ANY@{ub} way as long as @{b}NO MONEY@{ub} changes\nhands, obvoiusly this rules out PD libraries.... do I really need to\nspell it out?? here it is anyway!\n\n             PD libraries @{b}MUST NOT@{ub} distribute Pro-MultiCheck.\n\nAlso on-line systems which charge users, either to connect, or have\non-line charges, @{b}MUST NOT@{ub} distribute Pro-MultiCheck.\n\nExamples of these types of system are :\n\n                   CompuServe Information Service (CIS)\n                   Compulink Information eXchange (CIX)\n\n@endnode\n\n@node REGISTRATION "Registration information"\n                         @{u}Registration information@{uu}\n\nRegistration of Pro-MultiCheck is @{b}FREE@{ub} (ie @{b}NO CHARGE@{ub})\n\nUnlike PrO-DmScHeCk and PrO-MuLtIcHeCk @{b}I AM NOT@{ub} going to make future\nversions disabled in any way so that you have to register.\n\nI am offering a form of registration whereby you e-mail me the following\n''form'' :\n\n--------------------------------------------------------------------------\n\nBBS name      : _____________________     Include BBS information\nBBS number(s) : _____________________      in PMC''s documentation  YES/NO\n                _____________________\n                _____________________\nSysops handle\n     or name  : _____________________\n\nBBS Software  : _____________________\n\nComments regarding version 0.9ß or Pro-MultiCheck\n        __________________________________________________________\n        __________________________________________________________\n        __________________________________________________________\n        __________________________________________________________\n        __________________________________________________________\n\nComments / features you would like to see in future versions\n        __________________________________________________________\n        __________________________________________________________\n        __________________________________________________________\n        __________________________________________________________\n        __________________________________________________________\n\n--------------------------------------------------------------------------\n\nWhen I recieve the form, your BBS name and number, and your handle will\nbe added to the documentation (if you want) ..... - ''@{b}free@{ub}'' publicity!!!!,\nand I will take into account your comments / suggestions regarding\nPro-MultiCheck when developing future versions.\n\n@endnode\n\n@node FUTURE "Planned features for future versions"\n                   @{u}Planned features for future versions@{uu}\n\n@{u}Planned features for version 1.0@{uu}\n\n        · LhA stripping and adding speed improved by at least 50%.\n\n        · Text checking and stripping (another unique feature!!).\n\n        · Amiga executable hunk checking.\n\n@{u}Planned features for version 2.0@{uu}\n\n        · Improve LhA checking by removing the need for the LhA\n          executable. I have already got LhA decompression working\n          in a beta form - ie it needs testing and optimising, but\n          after preliminary tests it''s at least 50% faster than LhA\n          at decompressing archives!!\n\n        · FILE_ID advert adding / stripping.\n\n@{u}Planned features for version 3.0@{uu}\n\n        · Advert adding to Amiga executable files.\n\n        · ZIP checking.\n\nIf you would like any features not mentioned above, or have any\nsuggestions on how the above features should work then @{" e-mail " link CONTACT_ME} me.\n\n@endnode\n\n@node CONTACT_ME "How to contact Exodous"\n                             @{u}How to contact me@{uu}\n\nI can be contacted on the following BBS''s as ''Exodous''\n\nQ.E.D       : +44 (0)91-372-1911 ( 2 nodes - 28.8DS )\n              Sysop : Grasshopper\n\nThe Tower   : +44 (0)204-384-543 ( 2 nodes ringdown - 14.4DS )\n              Sysop : FireFlash\n\nWelsh Coast : +44 (0)792-561-196 ( 1 node 28.8DS )\n              Sysop : Sonny\n\nOr via internet :\n\n     [email removed]   (until early October)\n  or [email removed]            (after October 3rd)\n\n@endnode\n\n@node HISTORY "The history of Pro-MultiCheck"\n                         @{u}History of Pro-MultiCheck@{uu}\n\n| Ver   | Date          | Comment\n+-------+---------------+--------------------------------------------\n| 0.9ß  | 03-Sep-94     | First release version.\n+-------+---------------+--------------------------------------------\n@endnode\n\n@node OTHER_PROGS "Other programs that I have written"\n           @{u}Here is a list of other programs that I have written@{uu}\n\n@{b}BootUte@{ub}        : Degrader type utility for @{i}newer@{ui} Amiga''s....\n                 Needs Kickstart 2.0+. Features easy to use gadtools\n                 interface.\n\n@{b}BullRead@{ub}       : Bulletins door for /X that allows users to search\n                 bulletins while they are on-line, or download the bulletins\n                 for viewing whilst off-line.\n\n@{b}X-Zippy@{ub}        : Replacement zippy search door for /X that can search\n                 for multiple items at a time, about 3 times faster\n                 than the built in zippy!!\n\n@{b}UserCom@{ub}        : Door for /X that allows users to make comments to files\n                 so that others will know if the file is old, fake etc.\n\n@{b}PrO-DmScHeCk@{ub}   : DMS file checker - for user with most BBS systems.\n                 Strips and adds front, rear and track texts.\n\n@{b}PrO-LhAcHeCk@{ub}   : LHa file checker - for user with most BBS systems.\n                 Strips most other adverts and adds own adverts that are\n                 virtually unstrippable.\n\n@{b}PrO-LogInfo@{ub}    : An Ami-Express door to inform on-line users when another\n                 user logs on to, or off from, another node.\n\n@{b}Decrunch@{ub}       : CLI based decruncher to decrunch loads of different\n                 packed files.\n\n@{b}PPPatch@{ub}        : PowerPacker Patcher... Patches the headers of PowerPacked\n                 files so that they can''t be decrunched.\n\n@{u}Projects I''m working on@{uu}\n\n@{b}BootUte 2@{ub}      : Updated version of BootUte, but a @{b}LOT@{ub} better.\n\n@{b}Pro-NewUser@{ub}    : Ami-Express new user questionnaire door that doesn''t\n                 let new users skip questions, they have to insert something\n                 ''intelligent'', eg phone numbers can only have certain\n                 characters in them..\n\nIf you have any suggestions for features that you would like to see in\nany of the programs then e-mail me with your suggestions.\n\n@endnode\n\n@node ACKNOWLEDGE "Acknowledgements, Copyrights and Trademarks."\n                @{u}Acknowledgements, Copyrights and Trademarks@{uu}\n\n@{u}Copyrights@{uu}\n\nLhA             (c) Copyright 1991,1992 Stefan Boberg.\nDMS             (c) Copyright 1993-94 Parcon Software\nDevpac          (c) Copyright 1985-93 Hisoft.\nCygnusEd        (c) Copyright 1987-1991 CygnusSoft Software.\nMultiView       (c) Copyright 1991-1993 Commodore-Amiga Inc.\nInstaller       (c) Copyright 1991-93 Commodore-Amiga Inc.\n\nBootUte         (c) Copyright 1993-94 TLS Software.\nPPPatch         (c) Copyright 1993-94 TLS Software.\nBootUte 2       (c) Copyright 1994 TLS Software\nPro-MultiCheck  (c) Copyright 1994 TLS Software.\n\n@{u}Trademarks@{uu}\n\nKickstart and Workbench are trademarks of Commodore-Amiga Inc.\n\n@{u}Acknowledgements@{uu}\n\nI acknowledge all other copyrights and trademarks not specifically stated\nin this documentation, and in the entire Pro-MultiCheck package.\n\n@endnode\n\n@node DISCLAIMER "Disclaimer"\n                                @{u}Disclaimer@{uu}\n\nThis software is provided "as is" without warranty of any kind, either\nexpressed or implied. By using it, you agree to accept the entire risk as\nto the quality and performance of the program. Should the software prove\ndefective, you assume the cost of all necessary servicing, repair or\ncorrection.\n\n@endnode\n\n@node REG_USERS "Registered users"\n                         @{u}List of registered users@{uu}\n\nGrasshopper     : Q.E.D         +44 (0)91-372-1911\nFireFlash       : The Tower     +44 (0)204-384-543\nSonny           : Welsh Coast   +44 (0)792-561-196\n\n@endnode\n','\n',char(10)),NULL,'auto-added',36334,5,0,NULL,NULL,'tls_pmc','scan',1780048780);
INSERT INTO door_catalog VALUES('tmh_axbd','TMH-AXBD.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TMH-AXBD.LHA','rpstart','XIM','birthday.rexx',NULL,NULL,'TMH','_\_________\_\_____  _____/ _\_  |_____ /      ______/   /      \w^s/     l     \ /_________|.cOLa./________\ /_____________\',replace('   ________/\  ______________  ___/|\n  _\_________\_\_____  _____/ _\_  |_____\n /      ______/   /      \w^s/     l     \\n/_________|.cOLa./________\ /_____________\\n::::::::::::::::::presents::::::::::::::::::\n::::::: FRaNKy''s BirthDay Door V 1.1 :::::::\n::::::::::::::::::::::::::::::::::::::::::::\n::::: Give your users a nice birthday ::::::\n:::::   present, they''ll love it !!   ::::::\n::::::::::::::::::::::::::::::::::::::::::::','\n',char(10)),'BirthDay.Guide',replace('@database "FRaNKy''s BirthDay Door V 1.1"\n@font topaz.font 8\n@author "FRaNKy/PTL"\n@(c) "Copyright © 1995 FRaNKy / Purple Turtle"\n@$VER: BirthDay.Guide V1.01  (28/09/95)\n@node Main "FRaNKy''s BirthDay Door V 1.1 - Main Menu"\n    FRaNKy''s BirthDay Door V 1.1 - Copyright 1995 FRaNKy / Purple Turtle\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n       Important!            Contacting The Author           The Door\n      ¯¯¯¯¯¯¯¯¯¯¯¯          ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯         ¯¯¯¯¯¯¯¯¯¯\n  @{"     Disclaimer      " link "disc"}    @{"   Bulletin Boards   " link "Fbss"}    @{"     What Is It ?    " link "what"}\n  @{"   Compiled Doors    " link "comp"}    @{"       FidoNet       " link "Ffido"}    @{"     Installation    " link "inst"}\n  @{"    PostCardWare     " link "post"}    @{"      InterNet       " link "Finter"}    @{"     Config File     " link "conf"}\n                                                      @{"  Credits & Hellos   " link "cred"}\n     ________/\  ______________  ___/|                @{"       History       " link "hist"}\n    _\_________\_\_____  _____/ _\_  |_____           @{"    The Story Off    " link "stor"}\n   /      ______/   /      \w^s/     l     \\n  /_________|.cOLa./________\ /_____________\             Contacting PTL\n  ::::::::::::::::::presents::::::::::::::::::           ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n  ::::::: FRaNKy''s BirthDay Door V 1.1 :::::::        @{"        BBS''s        " link "pbbs"}\n  ::::::::::::::::::::::::::::::::::::::::::::        @{"       FidoNet       " link "pfido"}\n  ::::: Give your users a nice birthday ::::::        @{"      Internet       " link "pinter"}\n  :::::   present, they''ll love it !!   ::::::\n  ::::::::::::::::::::::::::::::::::::::::::::        @{" Looking For Members " link "memb"}\n@endnode\n@node "disc"\n@title "Disclaimer"\n                                DISCLAIMER\n                               ¯¯¯¯¯¯¯¯¯¯¯¯\n     This software is "AS IS", the author can not be held responsible for\n    any damage caused to your system by this software, or the consequences\n                               of this damage...\n\n                    To say it simply : Use at your own risk !\n@endnode\n@node "post"\n@title "PostCardWare"\n                               POSTCARDWARE\n                              ¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n           All the doors included in this archive are PostCardWare\n      If you use one of included doors, you are kindly asked to send a\n                    postcard of the area you live in to :\n\n                          Peter Smets (FRaNKy / PTL)\n                          Weldadigheidsstraat 45\n                          3000 Leuven\n                          Belgium\n\n             Postcards received so far : Lady An      [   UK   ]\n                                         Killer Dwarf [ Sweden ]\n@endnode\n@node "comp"\n@title "Compiled Doors"\n                               COMPILED DOORS\n                              ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n  All doors in this archive are compiled using the RexxPlus Arexx Compiler.\n\n     To get the doors to work on you /X system, you must run RPStart and\n       have the libraries included in the archive copied to your LIBS:\n  It is advisable to put RPStart in you User-Startup so you won''t forget it\n\n   If you would like a copy of the uncompiled sources of the doors included\n      in this archive, send 1500 BEF (50 USD) to the author of the doors.\n           Cash money (no coins) or EuroCheque in BEF only please.\n\n  This can be a large amount of money, but if you see what money I spend in\n   my doors (time, phonecalls) and if you really want the sources to study\n                       them, this isn''t too much I think...\n\n        The adress where you can send the money to can be found under\n                              @{"postcardware" link "post"} button...\n\nNote :\n\n Compiled doors do not work on all systems (blame the /X RexxPort for this)\n                   but the advantage for me is much greater.\n\n  I decided to do this compilation of my doors because I noticed that more\n    and more people started using pieces of my doors, or sometimes just\n    renaming the door and then releasing it under their own name/group.\n            If you want you can buy the sources as staded above.\n\n                                                                    FRaNKy.\n@endnode\n@node "what"\n@title "FRaNKy''s BirthDay Door V 1.1 - What is it ?"\n                                WHAT IS IT ?\n                               ¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nBirthDay gives the user a ''gift'' on his/her bithday.  When the user is not\nin the Birthday file, it will ask the user to give in his birthday.\n\nWhen the user is in this Birthday file, the door will no longer show any\ntext output untill the birthday and then be silent again for another year.\n\nOn his/her birthday the user will receive the nr of Kb stated in the\n@{"config file" link "conf"}.  Ofcourse the user will only receive these once,\nso if the user calls back 15 mins later he won''t get anymore upload\ncredits.\n@endnode\n@node "inst"\n@title "FRaNKy''s BirthDay Door V 1.1 - Installation"\n                                INSTALLATION\n                               ¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nPut the files Birthday.#? in Doors:PTL/Birthday/ to get everything working.\nThe icon Birth.Info (rename it to whatever what you like) has to be placed\nin BBS:Commands/BBSCmd/.\n\nThe add the door to your Logon-sequence by adding ''~CC_BIRTH'' to the file\n''NodeX/bull.txt'' (where X is the node number)\n@endnode\n@node "conf"\n@title "FRaNKy''s BirthDay Door V 1.1 - Config File"\n                                CONFIGURATION\n                               ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nThe file Doors:PTL/Birthday/Birthday.Cfg has to be edited like this :\n\nLine 1 : Number of Kb given for birthday\nLine 2 : User that does not get any birthday gift\nLine 3 : User that does not get any birthday gift\nLine 4 : ...\n\nExample :\n\n--- cut ---\n500\nLamer\nUltraLamer\n--- cut ---\n\nAll users except for Lamer and Ultralamer will now receive 500 Kb upload\ncredits on their birthday.\n\nIf you DO NOT want any user to receive any credits the file\nDoors:PTL/Birthday/Birthday.Cfg has to be edited like this\n\nLine 1 : Number of Kb given for birthday (DO NOT FORGET THIS ONE !)\nLine 2 : EALL\n\nExample :\n\n--- cut ---\n0\nEALL\n--- cut ---\n@endnode\n@node "cred"\n@title "FRaNKy''s BirthDay Door V 1.1 - Credits"\n                                   CREDITS\n                                  ¯¯¯¯¯¯¯¯¯\n                             Coding       : FRaNKy\n                             Docs         : FRaNKy\n                             Ideas        : TFX & La Fayette\n                             Nagging      : Necrite\n                             Beta Testing : TFX & Killer Dwarf\n\n                                  GREETINGS\n                                 ¯¯¯¯¯¯¯¯¯¯¯\nHello''s & Greetings from FRaNKy fly out to : All PTL members and\nmy friends out there, you know who you are.\n\n@endnode\n@node "hist"\n@title "FRaNKy''s BirthDay Door V 1.1 - History"\n                                    HISTORY\n                                   ¯¯¯¯¯¯¯¯¯\n                 ... - 0.9  : Internal Beta Releases\n                       1.0  : First Worldwide Release\n                       1.1  : - Added an option so that no-one will\n                                receive a birthday gift (asshole-mode)\n                              - Some internal source updates\n                              - Some layout changes\n@endnode\n@node "stor"\n@title "FRaNKy''s BirthDay Door V 1.1 - The Story Off"\n                                 THE STORY OFF\n                                ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nTFX gave me a script of a CNet-Birthday door and asked me to make it for\nAmix... I didn''t felt much for doing it, but I started it anyway... About\n3 days later a first Beta release was ready and I upped it to Fortress.\n\nA day later Necrite said he didn''t wanted the door to show up if it wasn''t\nthe users birthday.. I didn''t wanted to do this so I started up a vote\n(I lost 4 to 0 AAAARGH) and now the door doesn''t show up anymore...\n\nI putted the door up for a big Test on Killer Dwarfs'' BBS and there I\nnoticed that users ALWAYS entered their birthdays the wrong way so I added\nsome text to make it more clear but it didn''t helped so I added a checker\nif they entered it correctly.  And even now some stupid people manage to\nenter their birthday''s in the wrong way but I don''t care anymore. It is\nclear enough HOW they have to enter their birthday and if they don''t want\nto receive any upload creds an their birthday, that''s their problem.\n@endnode\n@node "Fbss"\n@title "Contacting The Author On The PTL BBS''s"\n                            CONTACTING THE AUTHOR\n                           ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n   The Author of the door can be contacted on these Purple Turtle BBS''s\n\n    Fortress      (   PTL WHQ  ) Node 1 : +32-3-***.**.** (Zyxel 16.8)\n                                 Node 2 : +32-3-***.**.** (Vfast 28.8)\n\n    Bitch Board   (   PTL EHQ  ) Node 1 : +46-11-**.**.** (USR   28.8)\n\n    Enigma        (   PTL BHQ  ) Node 1 : +32-89-**.**.** (USR   16.8)\n\n    Secret Cinema (PTL Fun Site) Node 1 : +32-52-**.**.** (VFast 33.6)\n                                 Node 2 : +32-52-RINGDOWN (VFast 33.6)\n\n    Cyber Garden  (PTL Fun Site) Node 1 : +32-11-**.**.** (USR   16.8)\n\n    Rhythm Nation (   PTL FHQ  ) Node 1 : +33-82-**.**.** (???   14.4)\n@endnode\n@node "FFido"\n@title "Contacting The Author Through FidoNet"\n                            CONTACTING THE AUTHOR\n                           ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n    The Author of the doors included in this archive can be contacted by\n               sendin a Netmail to one of these point-numbers\n\n                                2:292/628.10\n\n@endnode\n@node "finter"\n@title "Contacting The Author Through Internet"\n                            CONTACTING THE AUTHOR\n                           ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n                            Send your E-Mails to:\n\n                             [email removed]\n\n                     IRC-fans can try to join the channel\n\n                                    #PTL\n\n                         If I''m online, I''ll be there.\n@endnode\n@node "Pbbs"\n@title "Purpe Turtle BBS''s"\n                             PURPLE TURTLE BBS''S\n                            ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n                                   BELGIUM\n                                  ¯¯¯¯¯¯¯¯¯\n    Fortress      (   PTL WHQ  ) Node 1 : +32-3-***.**.** (Zyxel 16.8)\n                                 Node 2 : +32-3-***.**.** (Vfast 28.8)\n\n    Enigma        (   PTL BHQ  ) Node 1 : +32-89-**.**.** (USR   16.8)\n\n    Secret Cinema (PTL Fun Site) Node 1 : +32-52-**.**.** (VFast 33.6)\n                                 Node 2 : +32-52-RINGDOWN (VFast 33.6)\n\n    Cyber Garden  (PTL Fun Site) Node 1 : +32-11-**.**.** (USR   16.8)\n\n                                   HOLLAND\n                                  ¯¯¯¯¯¯¯¯¯\n    Super Dancer  (   PTL HHQ  ) Node 1 : +31-570-***.*** (VFast 28.8)\n                                 Node 2 : +31-570-***.*** (USR   14.4)\n                                 Node 3 : +31-570-***.*** (USR   16.8)\n\n                                    SWEDEN\n                                   ¯¯¯¯¯¯¯¯\n    Bitch Board   (   PTL EHQ  ) Node 1 : +46-111-***.**  (USR   28.8)\n\n    Inferno       (   PTL SHQ  ) Node 1 : +46-øPRIVATE!ø  (USR   33.6)\n\n    rIVER wILD    (PTL Fun Site) Node 1 : +46-612-***.**  (USR   28.8)\n\n\n                                    FRANCE\n                                   ¯¯¯¯¯¯¯¯\n    Rhythm Nation (   PTL FHQ  ) Node 1 : +33-82-**.**.** (???   14.4)\n\n                                    NORWAY\n                                   ¯¯¯¯¯¯¯¯\n    Wizard Guild  (   PTL NHQ  ) Node 1 : +47-53-**.**.** (VFast 28.8)\n\n                                   GERMANY\n                                  ¯¯¯¯¯¯¯¯¯\n    Traders World (   PTL GHQ  ) Node 1 : +49-215-******* (VFast 28.8)\n@endnode\n@node "PFido"\n@title "Purple Turtle FidoNet Adresses"\n                        PURPLE TURTLE FIDONET ADRESSES\n                       ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n                  TFX      (  World Leader )   2:292/8010.14\n                  FRaNKy   (Co-World Leader)   2:292/628.10\n@endnode\n@node "pinter"\n@title "Purple Turtle On The Net"\n                          PURPLE TURTLE ON THE NET\n                         ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n                The Purple Turtle homepage can be visited at :\n\n                    http://www.ping.be/~ping2045/ptl.html\n\n                    You can also send E-Mails to FRaNKy at :\n\n                              [email removed]\n\n                         Or join the IRC-Channel #PTL\n@endnode\n@node "memb"\n@title "Purple Turtle Is Always Looking For New Members"\n                           LOOKING FOR NEW MEMBERS\n                          ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n  If you think you are the right guy (girl) for a cool group and you can do\n  some Coding (ASM-C-Arexx-...), Music, Graphics, Trading, Swapping or have\n      a BBS, then contact the Purple Turtle Leaders or Division Leaders\n                   for a certain reply on one of our HQ''s.\n\n   If you want to join with your BBS, we do not ask any donations for your\n    membership (in another way : it''s free !).  BBS''s outside Belgium are\n                              extremely welcome...\n\n        @{" Bulletin Boards " link "lbbs"}   @{"     FidoNet     " link "PFido"}   @{"    InterNet    " link "pinter"}\n@endnode\n@node "lbbs"\n@title "Contacting The Leaders"\n                           CONTACTING THE LEADERS\n                          ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n  You can contact the World Leaders and/or division leaders on these BBS''s.\n    People with a HQ in their country should adress themselves to that HQ.\n       If there isn''t a PTL BBS in your country, call the WHQ or a bbs\n                            in a country near you.\n\n    Fortress      (   PTL WHQ  ) Node 1 : +32-3-***.**.** (Zyxel 16.8)\n                                 Node 2 : +32-3-***.**.** (Vfast 28.8)\n\n    Bitch Board   (   PTL EHQ  ) Node 1 : +46-111-***.**  (USR   28.8)\n\n    Super Dancer  (   PTL HHQ  ) Node 1 : +31-570-***.*** (VFast 28.8)\n                                 Node 2 : +31-570-***.*** (USR   14.4)\n                                 Node 3 : +31-570-***.*** (USR   16.8)\n\n    Rhythm Nation (   PTL FHQ  ) Node 1 : +33-82-**.**.** (???   14.4)\n\n    Wizard Guild  (   PTL NHQ  ) Node 1 : +47-53-**.**.** (VFast 28.8)\n\n    Traders World (   PTL GHQ  ) Node 1 : +49-215-******* (VFast 28.8)\n@endnode\n\n\n','\n',char(10)),NULL,'auto-added',104981,1,0,NULL,NULL,'tmh_axbd','scan',1780048780);
INSERT INTO door_catalog VALUES('tms_dn11','TMS-DN11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TMS-DN11.LHA','dn','XIM','dn',NULL,NULL,'TMS','>::: > TMS < A New /X-Designer  :::< >::   ________ _  _   _______    ::< >::   \__  __// \/ \  \  ___/    ::<',replace('>::::::::::::::::::::::::::::::::::<\n>::: > TMS < A New /X-Designer  :::<\n>::   ________ _  _   _______    ::<\n>::   \__  __// \/ \  \  ___/    ::<\n>::     /  \ /   _  \ /___  \    ::<\n>::     \__/ \__/ \_/ \_____/    ::<\n>::                              ::<\n>::   For V3.xx And The V4.xx    ::<\n>::                              ::<\n>:::  User Transfer Statistics  :::<\n>::         VerSion V1.10        ::<\n>::::::::::::::::::::::::::::::::::<\n','\n',char(10)),'dn.doc',replace('\n\nHello This IS a New Little Tools For The Lasted Version Of /X\n\nNAme: User Transfer Statistics The Real Version\n\nCopy All Dirs To U One BBS Dir\n\nCopy BBS/Commands/BBSCMD TO YOUR BBS:COMMANDS/\nCopy BBS/Commands/SYSCMD TO YOUR BBS:COMMANDS/\n\nCopy ConfX/downloadmsg.txt TO YOUR BBS:CONF2/downloadmsg.txt\n\nCopy BBS:DOORS/TMS TO YOUR BBS:DOORS/\n\nIf You Wand More /X Tools Call Me  I Support More Then 1800 Tools For\nAll Versions Of /X From V1.xx To V4.xx\n\nCall The Super Dancer BBS +31-570-037-050 28K8 V.FAST 3Nodez\n\nCheck It Out New User Password > FAST\nAnd The System Password        > YES\n\nOk I There Is Any Bug Let Me Know....\n\nThnx. For Using This COol And The SEc. Tools From T-SPOON/TMS\n\nSoo Thats All   Sorry For This Little Doc I hOpe Lick The Tools\n\n\n If There Is A BUG On It Let Me No Ok Have Fun .....','\n',char(10)),NULL,'auto-added',22988,5,0,NULL,NULL,'tms_dn11','scan',1780048780);
INSERT INTO door_catalog VALUES('tms_lo11','TMS-LO11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TMS-LO11.LHA','logon','XIM','logon',NULL,NULL,'TMS','\_   ___/  |_(____)   )_|  |   _____) ---+/   /__|  |  \  /  O  /|__ \_ ____/+---> | :\_____/|______\/__   /____| /_____): |',replace('+  ___________.  ____ ___.____.________    +\n   \_   ___/  |_(____)   )_|  |   _____)\n---+/   /__|  |  \  /  O  /|__ \_ ____/+--->\n | :\_____/|______\/__   /____| /_____): |\n | `--------pReSeNtz-.\_/.---.|/.-+bC!+'' |\n\|/                  `---''   `--''       \|/\n V  ++       TMS  /X - Dezigner      ++  V\n\n           Little Logon Door V1.10 \n      Easy To InStall Lock In The Doc\n     For The Versions V3.xx And V4.xx    ','\n',char(10)),'Bull.txt',replace('~CC_LOGON\n~SP\n','\n',char(10)),NULL,'auto-added',33283,1,0,NULL,NULL,'tms_lo11','scan',1780048780);
