INSERT INTO door_catalog VALUES('tms_lo15','TMS-LO15.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TMS-LO15.LHA','logon','XIM','logon',NULL,NULL,'TMS','_\_ \\__//  __/\__/\_ _//  \|  |_ |   \ \  \\  \  |  \_/ \/ "  \  / \ |_____/_  /\____|_  /_  /_|__/____/-X',replace('   ___ ____ ______________ __  __     \n  _\_ \\__//  __/\__/\_ _//  \|  |_   \n |   \ \  \\  \  |  \_/ \/ "  \  / \  \n |_____/_  /\____|_  /_  /_|__/____/-X\n         \/  1997  \/  \/             \n  B r i n g s   Y o u   T o  D A Y..  \n--------------------------------------\nLogon Doors V1.5 For /X 4.xx\n','\n',char(10)),'logon20.txt',replace('~CC_LOGON\n','\n',char(10)),NULL,'auto-added',8452,1,0,NULL,NULL,'tms_lo15','scan',1780048780);
