INSERT INTO door_catalog VALUES('ton_nets','TON-NETS.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TON-NETS.LHA',NULL,'XIM','Relyscully.exe',NULL,NULL,'TON','____ _____ ____  _____:___ \_))    _/___ ___\_ _/   _/_ __/__\_  _|  (.___.  _/   _/_ \   / \  _/  / \   /  _ \_   |   |  \  _/  /',replace('      ·tYPE o''NEGAtiVE·       __ _______\n   ____ _____ ____  _____:___ \_))    _/___\n___\_ _/   _/_ __/__\_  _|  (.___.  _/   _/_\n\   / \  _/  / \   /  _ \_   |   |  \  _/  /\n/__/___\_____\_____\_____|___|___|  /\_____\\n -/----------------------- Mo!/aL-\/----- -\nType o'' Negative NetStatus for [FAME·AMITCP]\nDisplays *all* current ip connections (bull)\n - -------------------------------------\->\n','\n',char(10)),'NetStatus.guide',replace('@DATABASE Ton!NetStatus Guide\n@AUTHOR Gravedancer\n@(c) "Copyright (c)  by Type o'' Negative in `96"\n@$VER: Ton!NetStatus v1.0 Guide (09-23-96)\n\n@INDEX MENU\n\n@node MAIN "Gratulate Yourself, You''ve Downloaded A Door By:"\n\n\n\n      -tYPE o''NEGAtiVE PRoduCtioNS 1996-             __ _   ________\n                                                    (_______)      //\n        _______ ______    _____      _______   ____:            ___/___\n   _____\\     /     _/_ _/   _/___.__\\_     \\./    |_ __      _/     _/__\n   \\    /    \\    _/    \\    \\    |    _     |     _/   \\     \\    _/    |\n  ._\\  /_________________\\___/    |____\\_____|_____|_____\\     \\_________|\n  |_\\\\/                     (_____|               -Mo!\\aL-\\    /\n                                                         ._\\  ø\n                   @{"Mainpage" link "MENU"}                              |_\\\\/\n\n\n\n@endnode\n\n@node MENU "Ton!NetStatus Mainpage"\n\n\n    @{b}Ton!NetStatus v1.0@{ub}\n    ----------------\n\n    @{"  " link "ABOUT"} - Introduction               @{"  " link "CREDITS"} - Credits\n    @{"  " link "INSTALLATION"} - Installation               @{"  " link "GREETINGS"} - Greetings\n    @{"  " link "EXPLANATION"} - Output                     @{"  " link "DISCLAIMER"} - Disclaimer\n    @{"  " link "REQUIREMENTS"} - Requirements               @{"  " link "TONEGATIVE"} - Type o''Crew\n\n    @{"  " link "Register"} - How To Register            @{"  " link "HISTORY"} - History\n  \n\n\n@endnode\n\n@node ABOUT "About Ton!NetStatus v1.0"\n\n    Ton!NetStatus\n   ------------\n\n  This created a small bulletin with information about your ip connections. This\n  must be done with an bulletin, because this is written in arexx to communicate\n  with amitcp(tm) directly, and fame supports not (really) arexx doors.\n\n  For Sure There Come Some Updates For Further Comming Fame Versions\n  Or Sysops With Registered FAME Version.\n\n\n@endnode\n\n@node INSTALLATION "How To Install Ton!NetStatus"\n\n    The Installation\n   -------------------\n\n  Copy all files to their drawers and install the bulletin.\n\n                                                           That''s It\n \n\n@endnode\n\n@node EXPLANATION "What Is What?"\n\n    What Is What?\n    --------------\n\n    To Get A Overview Take A Look At The Included Screenshots\n    In The Example Drawer.\n\n@endnode\n\n@node REQUIREMENTS "What Do I Need?"\n\n    Requirements\n   ---------------\n\n    A Installed And Running FAME & AmiTCP/IP System.\n\n    Easy, Eh?\n\n@endnode\n\n\n@node HISTORY "Ton!NetStatus History"\n\n    The History\n    ------------\n\n  Version 1.o First Beta Version [Internal]\n\n@endnode\n\n@node CREDITS "The Credits For Ton!NetStatus"\n\n    The Credits\n   --------------\n\n   All Code And Layout Of Ton!NetStatus v1.0 Is Copyright © By Gravedancer\n                                  All Rights Reserved ® By Type o''Negative\n\n            Straight Hate Ascii (Guide) Is Copyright © By Mogue Of Arclite\n Silent Moon Ascii (Guide) Is Copyright © By Exocet Of Anthrox And Arclite\n            Tower Of Souls Ascii (Guide) Is Copyright © By Uman Of Arclite\n\n\n               Btw: This Is NO Ass, Drink Or Callware But Pure Arexx-Stuff\n\n@endnode\n\n@node GREETINGS "The Greetings Etc."\n\n    I Would Send Some Hippy Hellos To\n   -----------------------------------\n\nAdon, Allah, Archangel, Aweson, Beatnik, Bilbo Baggins, Budweiser, ByteAndi,\n    Dan, Danzig, Data, Deathknight, Deskline, Desoto, Dhm, Dr.Dre, Ecs,\nExeron^Maniac, Exocet, Ezco, Flite, Fury, Guzzman, H2o!, Hausfrau, HiJack,\nHunkpapa, Horny, Jack^Danielz, Jake, Karma, Lance, Magz, Mario, Mark Ryder,\nMaz, Mogue, MuadDib, Nike, Noisy Belch, Nup, Ramon, Ramirez, Rapid, RtM, RkR,\nScandic, Segoy, ShapeChanger, Siegel, Slime, Spellfire, Strider, Stylewars,\n         Stylez, Sys, Tango, Tolpan, Traitor, Treach, U-Man, Zinko\n                       and all sceners on #AmiElite.\n\n@endnode\n\n@node DISCLAIMER "Read Careful!"\n\n    The Disclaimer\n    ---------------\n\n    We Shall Not Be Held Responsible For Any Damages Or Losses,\n    Direct Or Consequential, Resulting From The Use, Or Inability To Use\n    The Software. This Applies Even If We Had Been Made Aware Of The\n    Possibility Of Losses Or Damage.\n\n@endnode\n\n@node TONEGATIVE "How To Contact The Type o''Negative Crew"\n\n Every Day Was A Fight Against Your Own Suicide - Parasites And Mites Suckled\n From The Inside - They Always Came Completely Mixed Up - Always Called Your\n Name Blood-Suckling Creatures.\n\n       We Can Give You Something, Something You Always Searching For\n              We Can Show You Something, You Never Had Before\n\n Arising Sensations For Your Flesh And Blood - But All These Fallacies At The\n Abyss Of Madness Makes You See That You Could Also Get Brainless It Is Your\n Decision About Life And Death\n\n     Promising Something - Like Power And Strenght - Promising Something\n                  Creatures Of Madness Dancing In Your Mind\n\n                Making A Promise, You Have Never Heard Before\n                You Can Get Something,  You Always Waited For\n\n                  Creatures Of Madness Dancing In Your Mind\n\n         Urgeing You To A Painkilling Suicide - Painkilling Suicide\n\n\n @{"  " link "StraightHate!"} - Straight Hate!    @{"  " link "SilentMoon"} - Silent Moon    @{"  " link "TowerOfSouls"} - Tower Of Souls    @{"  " link "E-Mail"} - E·Mail Adds\n\n@endnode\n\n@node StraightHate! "Straight Hate - Type o''Negative World Headquarter"\n\n                                         ______\n                                         \\____/           _____\n  ________________: _________   _______         _______  |     |_____ ____:\n  \\       _.      |_ _      /___\\_     \\.____ _/     _/__|__   |    /     |_\n  .\\      \\|      _/ /     /.     _     |     \\      \\     /   _    \\     _/\n  |________\\      |__\\______|_____\\_____|______\\_____/     \\___|_____\\____|\n           |      |                                 /\n     ______|      |  ________   _____: _______     ø\n     \\     |    _ |__\\_      \\./     |_     _/____/_  EiGht NodE PoWER oN\n     /     _    \\ |    _      |      _/   _/     /     AMiGA 2ooo toWER!\n    /______|______|____\\______|______|________  /    68o6o/5oMhZ·32Mb RAM\n                                       Mo!/aL-\\/\n\n MANAGMENt: Mogue!/SuNFLEx iNC, ARCLitE ANd tYPE o''NEGAtiVE & dESkLiNE!\n hELPEd bY: toLPAN/tYPE o''NEGAtiVE - SLiME!/RoYAL, MotioN ANd FAiRLiGht\n            GoLdMAN/SuNFLEx iNC - ExoCEt/ANthRox ANd ARCLitE\n\n         SuNFLEx iNC GERMAN hEAdQuARtER - ARCLitE EuRoPEAN hAEdQuARtER\n                    tYPE o''NEGAtiVE WoRLd hEAdQuARtER\n\n 2 tiMES uS RobotiCS 33k6oo - 2 tiMES EuRo iSdN - 4 tiMES tELNEt [StAtiC^iSdN]\n\n@endnode\n\n@node SilentMoon "Silent Moon - Type o''Negative European Headquarter"\n\n     [AMiGA]÷[CoNSoLE]÷[ASCii & ANSi]÷[biG x/RAtEd AREA]÷[No PC CRAP!]\n                              ______                              _____\n         _________ _ ____    /     /   _________      __________ /     |_\n   ______\\       /_ _____)__//    /___/__     __|_____\\___     //      _/\n.--\\     |\\      \\         /    _/|     /   _|     /     /     //      |\n|  /_____________/_________/____________\\__________\\    /_____/________|\n|                                                /______\\÷e÷\n|         ______  _______ _________  _________   __________\n|        _\\     \\/      //         \\/         \ _\\___     /   SiLENt^MooN\n|        \\        /     //          \\          \    /     /\n`------ - \\     \\/_____/\\___________/________/_/   /_____/ - -------------÷\n           \\_____\\                          /______\\\n\n            tYPE o''NEGAtiVE ANd NEutRoN EuRoPEAN hEAdQuARtER\n      oRGANiSAtioN oF MiGhthuNGRY ASCiiARtiStS EuRoPEAN hEAdQuARtER\n \n      SYStEMoPERAtoRS: toLPAN/tYPE o''NEGAtiVE\n                       MoGuE!/SuNFLEx iNC, ARCLitE ANd tYPE o''NEGAtiVE\n                       dESkLiNE - hAuSFRAu!/oMA! ANd AWESoN/iLLuSioN\n@endnode\n\n@node TowerOfSouls "Tower Of Souls - Type o''Negative German Headquarter"\n\n                                    ______ -uMn/aL·\n          ________  ________________\\__   \\    _________   _________\n        _|        |/     _      /     /    \\___\\_      /___\\_      /\n        \\_        /      \\     /     /\\    /    /_____/_    /     /_\n         |________\\____________\\_____/\\____\\___________(____\\______(\n\nsTAFF: gRAVEDANCER [TYPE O'' NEGATIVE/PROTEST/NEUTRON] · dATA [PROTEST/PARADOX]\n       mOGUE [ARCLITE/SUNFLEX INC./TYPE O'' NEGATIVE]\n\nnODES: tELNET (3tIMES/19.2oobPS/rINGDOWN), sERIAL(1tIME,28.8oobPS)\n\ngROUP: pROTEST [aSCII] wORLD hEADQUARTERS · tYPE o'' nEGATIVE [fAME] gERMAN hQ.\n       nEUTRON [cONSOLE!MAg] wORLD hEADQUARTERS\n                                           _________\n  _____________________   _________   _____\\____   /__________   ________\n /    _     /    _    /__ \\       /__/   _     /  /     /    /___\\      /__\n/     \\    /     /______/  \\        /    \\    /   \\    /     \\    \\       /\n\\__________\\________|      /________\\_________\\________\\__________/_______\\\n\n@endnode\n\n@node E-Mail "The Type o''Negative E·Mail Addresses"\n\n      To Get In Touch With Any Of The Ton! Crew Send Your E·Mail To\n\n Handle........: Mogue!\n Member Of.....: Type o''Negative, Sunflex Inc And Arclite\n E·Mail Add....: [email removed]\n\n Handle........: Tolpan\n Member Of.....: Type o''Negative\n E·Mail Add....: [email removed]\n\n Handle........: Gravedancer\n Member Of.....: Neutron And Type o''Negative\n E·Mail Add....: [email removed]\n\n@endnode\n\n@node Register "How To Register Ton! Doors"\n\n         To Register Any Ton! Door Try To Call One Of Our Boards\n      And Use Register At The Promptline And Fill Out The Questions\n\n@endnode\n\n','\n',char(10)),NULL,'auto-added',21143,7,0,NULL,NULL,'ton_nets','scan',1780048780);
INSERT INTO door_catalog VALUES('ton_ts11','TON-TS11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TON-TS11.LHA',NULL,'XIM','SAD-CLOG.EXE',NULL,'Gravedancer/Ton^Ntr','TON','____ _____ ____  _____:___ \_))    _/___ ___\_ _/   _/_ __/__\_  _|  (.___.  _/   _/_ \   / \  _/  / \   /  _ \_   |   |  \  _/  /',replace('Type o''Negative ·Bloody Roots·__ _______\n   ____ _____ ____  _____:___ \_))    _/___\n___\_ _/   _/_ __/__\_  _|  (.___.  _/   _/_\n\   / \  _/  / \   /  _ \_   |   |  \  _/  /\n/__/___\_____\_____\_____|___|___|  /\_____\\n -/----------------------- Mo!/aL-\/----- -\nTelnet Status [FAME/AMIEX/AMIRC] R.II - v1.1\nNow with finger & www support,and a 80% self\nconfiguration, © 1996 by Gravedancer/Ton^Ntr\n - -------------------------------------\->\n','\n',char(10)),'Telnet.guide',replace('@database Type o'' Negative (Telnet Status) - Documentation\n@$VER: 1.1\n@author "Sebastian Bergmann a/k/a. Gravedancer/Ton"\n@(c) "©1996 Copyright - All Rights Reserved"\n@remark Created with Heddley v1.1 (c) Edd Dumbill 1994\n\n@node "Main" "AmigaGuide Documentation for Type o'' Negative Telnet Status for IRC"\n\n         @{b}Type o'' Negative Telnet Status for Fame - V1.1 by Gravedancer/Ton!@{ub}\n\n         @{b}Introductions                       Informations@{ub}\n         @{"  " link "Features" 0} - Features                       @{"  " link "TypeON" 0} - Type o'' Negative\n         @{"  " link "Install" 0} - Installing                     @{"  " link "Updates" 0} - Updates\n         @{"  " link "Register" 0} - The Author                     @{"  " link "Credits" 0} - Credits\n \n         @{b}Miscellaneous@{ub}\n         @{"  " link "Legal" 0} - Legal things                   @{"  " link "Register" 0} - Registration\n         @{"  " link "Internal" 0} - Internals                      @{"  " link "Greetings" 0} - Greetings\n@endnode\n\n@node "Features" "The Features"\n \n @{b}THE FEATURES@{ub}\n\n · Simply the *best* Telnet Status Tool for use with telnet nodes on bbs\n   systems running fame or amiexpress.\n\n · Sends information about how many telnet slots you have online, which are\n   currently busy and most *important* your ip address.\n\n · Features autodetecting configuration assistent for fame bbs systems, means\n   it is able to determine bbsname and your telnet nodes in just a second.\n\n · The above stated information *and* a complete "who-door-output" can be\n   written to a file like "home:.plan". This file will be shown to a person\n   who does a finger operation on your ip like: FINGER towerofsouls.com\n\n · A file like the one for the finger operation can be created in *html*\n   markup language format. This is useful for you if you are running a www\n   server software on your system.\n\n · Easy to use, embedded configuration program which is automatically\n   started if you run the script for the first time.\n\n · Flexible way to obtain your *current* ip address. If it is not possible\n   to determine your ip, you can enter it manually.\n\n@endnode\n\n@node "Install" "How to install"\n \n @{b}HOW TO INSTALL@{ub}\n \n 1.) Copy Telnet.amirx to AMIRC:Rexx/\n\n 2.) Make an alias /TELNET /RX Telnet.amirx\n\n 3.) Start AmIRC and type /telnet\n\n@endnode\n\n@node "Updates" "Where to get Updates"\n \n @{b}WHERE TO GET THE UPDATES@{ub}\n \n @{b}WAY #1 MAILORDER@{ub} - (the slow way)\n\n Send @{"me" link "Register" 0} a empty disk and an envelope with an unused stamp, and I`ll put\n all new versions on the disk and will send them back within 1 Week.\n \n @{b}WAY #2 DISTRIBUTION SITE@{ub} - (the fast way)\n \n Call one of our @{"distribution sites" link "Tower of Souls" 0} to register your updates.\n@endnode\n\n@node "Credits" "Credit notes"\n \n @{b}@{u}BOUQUETS TO ALL WHO HELPED@{ub}@{uu}\n \n @{fg shine}Telnet Status!@{fg text}         v1.o written by Gravedancer/Ton\n                        © Copyright 1996 Sebastian Bergmann\n                        All Rights Reserved.\n\n @{fg shine}TON-ANSI·2·GUIDE@{fg text}       vo.3 written by Gravedancer/Ton\n                        © Copyright 1996 Sebastian Bergmann\n                        All Rights Reserved.\n \n @{fg shine}FAME BBS@{fg text}               v0.75ß written by David Wettig.\n                        ©1993-1996 David Wettig.\n                        All Rights Reserved.\n\n @{fg shine}Documentation layout@{fg text}   lend from Dr.Dre/Trsi ;)\n                        © Copyright 1996 Bodo Hoffmann\n                        All Rights Reserved.\n\n @{fg shine}HEDDLEY@{fg text}                v1.18 written by Edd Dumbill\n                        © Copyright 1994 Edd Dumbil\n                        All Rights Reserved.\n\n @{fg shine}AMIGAGUIDE@{fg text}             v34.3 by Commodore-Amiga\n                        © Copyright 1991-93 Commodore-Amiga, Inc.\n                        All Rights Reserved.\n                        Reproduced and distributed under license of Commodore.\n \n @{b}Registered trademarks are not marked separately.\n Therefore absence of a trademark does not imply they are free.@{ub}\n@endnode\n\n@node "Legal" "The Legal things"\n \n @{b}THE LEGAL STUFF@{ub}\n \n @{"  " link "Disclaimer" 0} - Disclaimer\n @{"  " link "Warranty" 0} - Warranty\n @{"  " link "Copyright" 0} - Copyright\n@endnode\n\n@node "Internal" "Internals"\n \n @{b}SOME INTERNAL AUTHOR INFORMATIONS@{ub}\n \n @{b}Program:@{ub}             Telnet Status, Fame&AmiEx Release\n @{b}Version:@{ub}             v1.1 PUBLIC VERSION\n @{b}Date:@{ub}                September, 13th 1996\n @{b}Coded by:@{ub}            Gravedancer/Type o'' Negative\n @{b}Compiled with:@{ub}       not available\n @{b}Machine:@{ub}             A1200, 68020, 6MB RAM\n @{b}Required:@{ub}            AmigaDOS 2.o or above, Fame system (demo/reg)\n\n@endnode\n\n@node "Register" "How to register"\n\n                ____\n           .ze""    "ec.\n        z$$$$         3$$$c\n      d$$$$$F          $$$$$b\n    z$$$$$$$b         .$$$$$$$c\n   z$$$$$$$$$b       .$$$$$$$$$L  