INSERT INTO door_catalog VALUES('topcps','TOPCPS.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TOPCPS.LHA','topcps','XIM','topcps','1.03',NULL,NULL,'Mod''s.: SiGMA SEVEN! 33.6 DigITal-X Prd/NirVana Dist Site! 33.6',replace('TOP CPS V1.03 - Original: Drakpak Ent. \n      Mod''s.: SiGMA SEVEN!\n33.6 DigITal-X Prd/NirVana Dist Site! 33.6\n','\n',char(10)),'2Nodez.TXT',replace('_ __ ________________________________________________________________ __ _\n                                                      ___\n    .,,,,     .---._ Oo  .::::. .::::. :::   :::    __\__\\n    ( oo)__   (¯oo) /..\ ::  :: ::  :: :::   :::    \ / Oo\o  (\(\\n   /\_  \__) /\_  \/\_,/ ::  .. ::..:: ::''   ::''    _\\`--_/ o/oO \\n   \__)_/   _\__)_/_/    :::::: :::::: ::....::.... \_ \  \  \.--''/\n   /_/_/    \ /_/_//     `::::'' ::  :: `:::::`:::::: /_/__/   /¯\ \___\n _(__)_)_,   (__)_/  .::::.                      ;::  |_|_    \_/_/\_/\\n  o    o      (__)) ,:'' `::::::::::::::::::::::::::'' (__)_)___(_(_)  ¯¯\n              ________  ____________________  __   _/\  ___ \n              \____   \/  / ___/  /_  _/    \/ /   \  \/ \/\n               \   \   \ / /__^  / / //  ^  /  \___ \    /     ___    __o \n               /_______//\___/__/ /_/ \_/\_/\_____/ /    \_   ___   _-\<,_ \n               DREAM MACHINE WorLD DHQ CenTer ©    /__/\___''97 ___ (_)/ (_)\n\n            PaRaDiSe : wORLD iNNOVATION wORLD dISTRIBUTION sITE!\n            NirVaNa  : wORLD iNNOVATION wORLD dISTRIBUTION sITE!\n       Dream Machine : wORLD iNNOVATION wORLD dISTRIBUTION sITE!\n\n  Node [1] +31-570-637050  Node [2] +31-570-636468  Node [3] +31-570-677702\n\n  Amiexpress V4.20 Registered On An Amiga 2000 GVP-Tekmagic 68060 32MB KS3.1\n    Pioneer Changer DRM-604X + Toshiba Cd-Rom 4 HD''s 7110MB Space Total...\n\n   2 * cREDITZ fOR mAJORS! 3 * cREDITZ fOR mAJORS fROM yOUR oWN gROUP!\n    pROVIDING yOU: Amiga ECS/AGA, PC, AmiExpress, Sex Pic, Sex Stories\n\n          ---»> nO nEW uSER pASSWORD aND/oR sYSTEM pASSW