INSERT INTO door_catalog VALUES('topdn200','TOPDN200.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TOPDN200.LHA','TopDN','XIM','TopDN',NULL,NULL,NULL,'33.6 DigITal-X Prd/NirVana Dist Site! 33.6',replace('-> List of Top Files downloaded <-\n33.6 DigITal-X Prd/NirVana Dist Site! 33.6\n','\n',char(10)),'Changes.DOC',replace('\n Bugs stomped since v1.50\n\n ======================\n  Version 1.7 25/03/90\n ======================\n\n - Clean up ANSI list.\n - Sometimes, if stack was to low, topdn got a GURU.\n - Speeded Up.\n\n ======================\n  Version 1.8 02/04/90\n ======================\n\n - Never release to public\n\n ======================\n  Version 1.9 07/04/90\n ======================\n\n - FINALLY fixed the bug that cause TopDN to not list some files !\n   Thanks to Carsten Lohmann and Maui !\n\n ======================\n  Version 2.0 05/10/90\n ======================\n\n - Now TopDn read Paragon config from ParCon.\n - Added Turbo Mode option.\n\n','\n',char(10)),NULL,'auto-added',22631,9,0,NULL,NULL,'topdn200','scan',1780048780);
INSERT INTO door_catalog VALUES('topfu10','TOPFU10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TOPFU10.LHA','TopFU','XIM','TopFU','1.0','Mr.Mad',NULL,'33.6 DigITal-X Prd/NirVana Dist Site! 33.6',replace('TopFU V1.0 by Mr.Mad & Coke\n33.6 DigITal-X Prd/NirVana Dist Site! 33.6\n','\n',char(10)),'TopFU.doc',replace('       __    __                          _________________________\n      / /   / /                         / _______________________/\n     / /   / /______ ______________    / /  ________ _____     ______ _______\n    / /   / // __  //__  _  ______ \  / /__/_____  // ___/___ / ____// _____/\n   / /   / // / / /__ / // /___ __\ \/ _______/ / // // ____// /___ / /____\n  / /   / // / / // // // ____// / \ \/  / /   / // // /    / ____//____  /\n / /___/ // / / // // // /___ / /___\ \ / /___/ // // /___ / /_________/ /\n/_______//_/ /_//_//_//_____//________//_______//_//_____//_____________/     \n  \n                    ------------------------------------\n                    -                                  -\n                    -   TopFU V1.0 by Mr.Mad & Coke    -\n                    -                                  -\n                    ------------------------------------\n                    -                                  -\n                    -   Touchdown BBS +49-531-501675   -\n                    -                                  -\n                    ------------------------------------\n \n \n 1. Introduction\n \n   This utility is for you, sysop!\n   - It`s displays the Top File Uploaders\n   - If you choose the -g option for including ANSI TopFU creates both\n     (.txt and .txt.gr) outputfiles! So you don`t have to run TopFU twice\n \n   Usage :\n   TopFU [UDat] [-g/-n] [OutPut] [NumUl]\n\n   All options must be entered in the order shown above. The [UDat] file\n   is the full path to your Userdata File. The -g option is for including\n   ANSI graphics in the outputfile and the -n to play Gameboy. One of\n   these options must be chosen. If you choose the -g option TopFD V1.0\n   generate Bullx.txt and Bullx.txt.gr Outputfiles. [NumUL] is the amount\n   of File Uploaders you want to display. Inactive Users or empty slots\n   are not displayed.\n\n   Example:\n   TopFU BBS:User.data -g BBS:Main/Bulletins/Bull5 100\n\n \n   Programming:    Mr.Mad - United Forces\n   Text & Design:  Coke - United Forces\n','\n',char(10)),NULL,'auto-added',6425,6,0,NULL,NULL,'topfu10','scan',1780048780);
INSERT INTO door_catalog VALUES('toplamer','TOPLAMER.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TOPLAMER.LHA','TOPLAMER','XIM','TOPLAMER',NULL,NULL,NULL,NULL,replace('TOP LAMER FOR AMIEXPRESS 3.x->\n','\n',char(10)),'TOPLAMER.DOC',replace('----------------------------TOP-LAMER (NOSNUKE VER) DOCS---------------------\n          CODED BY I.O FOR THE USS ENTERPRISE BBS ATX/AHQ +61-3-312-5747\n          DOCS/IDEA/CONFIG BY KIRK/ATX\n\nDESC.\n    Top lamer is a util which will create a bulletin file for ami express.\n    The bulletin created will list (top 15) in order users with the most deleted\n    files or bytes. This version of the util works with the nos-nuked text,\n    created by nosnuke when files are zapped. A "FAKER" version will soon be\n    completed! For sysops who hate nos!\n    The util runs mega fast, so it can be placed in your logoff script\n    The programm can list by files or bytes! The output file is directional and\n    can be of your own desgin(ive included mine as an example but you are free\n    to use it if you like..\n\nWHAT YOU NEED.\n    TOPLAMER (the main util)\n    TOPLAMER.CONFIG (must be placed in the S directory)\n    NOSNUKE.STATS ( should already be in the bbs directory)\n\nUSAGE.\n    TOPLAMER <FUNCTION> <OUTPUT>\n    Where the functions are either -B (list by bytes) -F (list by number of files)\n\n    example  TOPLAMER -B BBS:CONF1/BULLETINS/BULL1.TXT\n\nSETTING UP.\n    I have included my config file as an example, the important thing to\n    note is that the programm looks for the "~" so it knows were to place\n    the user,files nuked,bytes nuked (so leave enough space for the name ext)\n    There is a preset limit of the top 15 users and this cannot be changed!\n    You may have as many lines of text above and below these "~" and incoporate\n    ansi codes as you like.\n\nGREETS.\n    WINTERMOOTY Thanxs for the help!\n    HYDSTAR     The green grocer\n    SCUDLY      Sort out the new habit!\n    MANXSTAR    The vigin killer\n    HI T        The rexx god(step by step descriptions cool!\n    FOX/SKILLION,SHPINX,POETICALL,DEMONLORD, thanx for the bbs support.','\n',char(10)),NULL,'auto-added',6938,6,0,NULL,NULL,'toplamer','scan',1780048780);
INSERT INTO door_catalog VALUES('toplogon','TOPLOGON.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TOPLOGON.LHA','TopLogon','XIM','TopLogon',NULL,NULL,NULL,'33.6 DigITal-X Prd/NirVana Dist Site! 33.6',replace('TopLogon for AmiExpress\n33.6 DigITal-X Prd/NirVana Dist Site! 33.6\n','\n',char(10)),'TopLogon.doc',replace('\n                                   TopLogon \n                                   ~~~~~~~~\n                                for AmiExpress \n                                    by TWA\n                             Kludged¹ April 7 1991\n\nThis program does one simple task; it produces a toplist of the users\nthat has the greatest number of logons to your BBS.\n\nGreat for finding out who are the important users, and who are the\ncurious peepers, isn''t it ??\n\n                                  How to use\n                                  ~~~~~~~~~~\n\n                        Now how do we use it ? Simple!\n\nFrom CLI : TopLogon <Length> <gr>\nExamples:\n\n"TopLogon" 		will make a top 10 list with no colors.\n"TopLogon 15 gr" 	will make a top 15 list with ANSI colors.\n"TopLogon 15" 		will produce a top 15 list with no colors.\n\nOfcourse you can redirect output to anywhere you like.\nTyping a quiestionmark ("?") on the command line will give you a brief\nexplanation of the command.\n\n<Length> is a number between 1 and the number of users you''ve got.\n<gr>     is a flag telling TopLogon to produce colors in the listing.\n\n                                     Note!\n                                     ~~~~~\n- The SysOp (User #1) is NOT considered in the listing. (He''ll probably end\n  up at the top anyway...)\n\n- As I said, this program is a Kludge. Putting weird things on the command\n  line, would cause some even weirder effects.\n\n- This program *is* tested, so I know it works, but if your BBS files\n  (SystemStats and User.Data) isn''t in the BBS: directory, tough luck!\n\n                                   Greetings\n                                   ~~~~~~~~~\nNo docs without greetings, so here we go:\nDr.Excel/Motion, TIngo, AlfHead/NETWORK, Batman/Miranda, JVC, NIKI/CRB,\nand last but not least Fantomet, ånden som går.\nI also wanna thanks Neil Peart for inspiration, not for this program, but\nfor lots of other things more real-life.\n\nHow to reach me ?? Well, I''ve got a BBS, but why would you wanna call it ?\nYou take care of *your* board, and I''ll take care of mine.\n(This is to say that if you know who I am, you know who I am.)\n\nI CAN be reached on some boards under the name ''TWA'', but who cares...\n\nBIBI, TWA going to sleep......z-\n                                z-\n                                  z-z-z\n                                        z-z-z..........\n-----------------------------------------------------------------------------\n¹\nKludge .......................: A clever programming trick. Often the term \n                                kludge is applied to a piece of code that \n                                achieves results through some obscure trick \n                                rather than through a clear algorithm. A \n                                kludge is usually more respected than a hack.\n\n','\n',char(10)),NULL,'auto-added',23420,5,0,NULL,NULL,'toplogon','scan',1780048780);
INSERT INTO door_catalog VALUES('topmsg10','TOPMSG10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TOPMSG10.LHA','TopMSG','XIM','TopMSG','1.0','Mr.Mad',NULL,'33.6 DigITal-X Prd/NirVana Dist Site! 33.6',replace('TopMSG V1.0 by Mr.Mad & Coke\n33.6 DigITal-X Prd/NirVana Dist Site! 33.6\n','\n',char(10)),'TopMSG.doc',replace('       __    __                          _________________________\n      / /   / /                         / _______________________/\n     / /   / /______ ______________    / /  ________ _____     ______ _______\n    / /   / // __  //__  _  ______ \  / /__/_____  // ___/___ / ____// _____/\n   / /   / // / / /__ / // /___ __\ \/ _______/ / // // ____// /___ / /____\n  / /   / // / / // // // ____// / \ \/  / /   / // // /    / ____//____  /\n / /___/ // / / // // // /___ / /___\ \ / /___/ // // /___ / /_________/ /\n/_______//_/ /_//_//_//_____//________//_______//_//_____//_____________/     \n  \n                    ------------------------------------\n                    -                                  -\n                    -   TopMSG V1.0 by Mr.Mad & Coke   -\n                    -                                  -\n                    ------------------------------------\n                    -                                  -\n                    -   Touchdown BBS +49-531-501675   -\n                    -                                  -\n                    ------------------------------------\n \n \n 1. Introduction\n \n   This utility is for you, sysop!\n   - It`s displays the Top Messagewriters\n   - If you choose the -g option for including ANSI TopMSG creates both\n     (.txt and .txt.gr) outputfiles! So you don`t have to run TopDL twice\n   - You can include the sysop if you want\n \n 2. How to get started\n \n   Usage :\n   TopMSG [UDat] [-g/-n] [OutPut] [-s/-n] [NumW]\n\n   All options must be entered in the order shown above. The [UDat] file\n   is the full path to your Userdata File. The -g option is for including\n   ANSI graphics in the outputfile and the -n to smoke a joint. One of\n   these options must be chosen. If you choose the -g option TopMSG V1.0\n   generate Bullx.txt and Bullx.txt.gr Outputfiles. The -s option is for\n   including sysop and -n for users only. One of these options must be\n   chosen. [NumW] is the amount of MSGwriters you want to display. Inactive\n   Users or empty slots are not displayed.\n\n   Example:\n   TopMSG BBS:User.data -g BBS:Main/Bulletins/Bull3 -n 10\n\n \n   Programming:    Mr.Mad - United Forces\n   Text & Design:  Coke - United Forces\n','\n',char(10)),NULL,'auto-added',6472,6,0,NULL,NULL,'topmsg10','scan',1780048787);
INSERT INTO door_catalog VALUES('topul11','TOPUL11.LZX','~/Code/amiexpress_doors/Archives/AmiExpress/TOPUL11.LZX',NULL,'XIM','TopULDL-v1.1',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'auto-added',17449,0,0,NULL,NULL,'topul11','scan',1780048787);
INSERT INTO door_catalog VALUES('tosl_301','TOSL_301.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TOSL_301.LHA','ToSL','XIM','ToSL','3.01',NULL,'TOSL','CNet Select list utility! View, Add, remove selections in user''s select list. Features new PATTERN-SELECT mode when [A]dding',replace('ToSL v3.01 from MetalSoft - THE ultimate\nCNet Select list utility! View, Add, remove\nselections in user''s select list. Features\nnew PATTERN-SELECT mode when [A]dding\nselections. Also detects ONLINE or OFFLINE\nusers & select list is saved to online\nselections if user is on line.\n','\n',char(10)),'TOSL.doc',replace('                         ToSL (ToSelectList) v3.01\n\n                     Developed by Ray Akey for CNet/4\n    (This version of ToSL Will NOT work on C-Net versions before V4.0)\n\n                   Compiled using the SAS/C environment\n                        Released by Metal Software \n\nChanges 3.01\n------------\n1.  Recompiled due to internal CNet Amiga structure changes.\n\n\nChanges v3.0\n------------\n1.  Recompiled and updated for CNet Amiga v4.0 to use the new mail directory\n    naming convention.\n\n\nChanges v2.1\n------------\n1.  Trashed BROWSE-SELECT mode for the new PATTERN-SELECT mode.  This allows\n    you to use full AmigaDOS patterns for file matching.  (ie. if you enter\n    CNET:B#? at the pattern prompt when [A]dding files to the user''s\n    select list, all files in the CNET: directory beginning with the letter\n    "B" will be listed, one at a time, for you to select or not select.\n    Also, if you have a IBM wildstar (*) enabling commodity or util running\n    ToSL will allow that wildcard character as well (making "CNET:B*"\n    allowable as a valid pattern string)\n2.  Device/assign names are expanded to their FULL path (this is an\n    *AmigaDOS* feature that ToSL supports)\n3.  Fixed the bug where some selections were added TWICE to the same select\n    list.\n4.  Added SYSTEXT:MENU/SYS.TOSL.MAIN menu.  Also SYSTEXT:MENU/SYS.TOSL.EDIT\n    has been updated.  Please copy those files to your SYSTEXT:MENU\n    directory.\n5.  It is possible to enter an assignment operator (the equal sign "=") at\n    the "ENTER PATTERN" prompt during a select [A]dd.  When an "=" is entered\n    you will be given a list of your current assigns and may choose one of\n    them via it''s number in the list, or by entering ANY valid pattern at\n    the "Choose assign" prompt.  For example, if "UDBASE1" is listed as\n    assign number 13, entering "13" will cause "UDBASE1:#?" to be placed\n    in your "Enter Pattern" prompt where it will be re-prompted to you\n    (so that you may enter a different pattern or just hit enter to accept)\n\n**  The best thing to do is play with the new options.  The [R]emove and\n    a[B]ort options allow you to remove or abort any changes you have made,\n    so you need not worry about harming anyone''s "current" selections.\n\n\nChanges v2.01\n------------\n1.  Re-implemented carrier checking (oops!) to the "Add, Edit, etc.." prompt.\n\nChanges v2.0\n------------\n1.  Added EDITING of attributes in current select list.  Every parameter of\n    a user''s selection/list can be changed, EXCEPT for the "AO date".\n2.  Added "LIST" option to list current select list, whether the user is\n    online or offline.\n3.  Added REMOVE to allow removal of a selection from user''s select list.\n    "ALL" clears the complete select list that you are currently\n    editing/viewing.\n4.  Safe "SAVE" option added so your changes can be saved without exiting and\n    re-loading the current select list.\n5.  ABORT option allows you to exit without saving changes.\n6.  PATTERN-SELECT (during "ADD") allows to to specify a path & file-pattern\n    and you will be prompted (NO/Yes/Quit) whether to add files that match\n    that pattern to the select list.\n7.  Most functions use HOT KEYS and hot keys are in most cases expanded to\n    their FULL ASCII name, so that you know exactly what the key does before\n    giving command arguments.\n8.  Cursor positioning used in many places during editing to minimize screen\n    clearing where not required/desirable.\n9.  TempRem is a CNet variable used to denote selected items that are\n    currently saved ON DISK.  Although from my own checking, CNET doesn''t\n    *appear* to use this field, ToSL does; If you mark something TempRem''d,\n    and you are editing an ONLINE USER''s select list, items marked TEMPREM\n    will be saved ON DISK and those that are NOT marked TempRem are added to\n    his "RAM BASED" Select list.  This gives you a method of adding to an\n    online user''s select list while he/she is downloading.  If you don''t use\n    the TempRem method, the selection will be downloaded during that session.\n    Use of the TempRem method allows them to finish their current dload(s)\n    before CNet scans for "temporarily removed" selections (ie. at the "DS"\n    prompt the user is asked to "temporarily" deselect items he doesn''t wish\n    to dload presently).\n\n    Most changes are VERY intuitive and you''ll find that ToSL is very "SysOp\n    friendly" in how it operates.\n\n\n\nHistory\n-------\n	ToSL is a program that was originally whipped up and debugged in a couple\nof hours.  It began as a quickie way (and still is) to add a file to another\nuser''s select list, whether they are online or offline.  I originally intended\nfor it to be a "personal" thing for my own use, since a fellow sysop asked for\na copy of my BBSTEXT.  "Filemail" just doesn''t quite cut it, so I wrote ToSL.\n   Since, others have asked for me to release it as a METALSOFT product, here\nit is. ToSL has undergone many changes and I hope these changes are useful to\nyou as a CNet SysOp.\n\n   If you are running an older CNet and wish to see if ToSL will work with\nit, load a select list with ToSL.  If it loads and looks ok, then ToSL should\nwork fine with your version of CNet.  Also, make sure you try loading the\nselect list of an ONLINE user.  Internal operation is slightly different when\nToSL needs to access the select list of an online user.  If it works fine in\nboth cases then you can be relatively sure that ToSL will work fine.\n\n\nSetting it up:\n--------------\n	Simple.\n\n1) Copy the executable "ToSL" to your pfiles: directory or a suitable\n   alternate location.\n2) copy the .menu files to your SYSTEXT:MENU directory.\n3) Add the following to your BBSMENU on the next available blank line in the\n   "1: Maintenance Menu" section:\n\n                   TOSL, TOSelectList	|#2Pfiles:TOSL}\n\n                                        ^\n                                        |\n                                      CTRL-Q\n\nNOTE:  If you add TOSL to your pfiles listing, it may or may not operate\n       correctly as far as parsing the command line is concerned.\n       Data integrity would be fine though once a select list is loaded.\n       ToSL has only been tested as a MENU command as that is where it is\n       most useful.\n\n\nCommand convention\n------------------\n  Enter "ToSL" (or the menu command name you gave it in BBSMENU) with no\narguments and it will prompt you for a handle/account number.  Entering\n"ToSL" + an account/handle will bypass the "Enter Handle/Account" prompt\nand load the specified account/user select list.\n\n\n\n\n8<------------------------------------------------------------------------->8\n\n                        -= The Metal Shoppe BBS =-\n               -====== 519-256-0278  2400-19200 BAUD =====-\n            -========= 519-255-7378   1200-2400 BAUD ========-\n               -==========================================- \n                  -====================================-\n                     -==============================-\n                        -========================-\n                             ** CALL TODAY **\n','\n',char(10)),NULL,'auto-added',20305,6,0,NULL,NULL,'tosl_301','scan',1780048787);
INSERT INTO door_catalog VALUES('totyed11','TOTYED11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TOTYED11.LHA','ToolTypeEditor','XIM','ToolTypeEditor','1.1',NULL,NULL,'- Interface To Edit Icon Tooltypes',replace('ToolTypeEditor v1.1\n- Interface To Edit Icon Tooltypes\n','\n',char(10)),'ToolTypeEditor.guide',replace('@DATABASE "ToolTypeEditor.guide"\n@AUTHOR "Mark Ritter"\n@(c) "Copyright © 1995-1996 By Mark Ritter"\n@$VER: Tool Type Editor Documentation 1.1 (18.1.96)\n@WORDWRAP\n\n\n@NODE Main "Tool Type Editor Documentation"\n@{JCENTER}\nTool Type Editor\nBy: Mark Ritter\n\nVersion: 1.1     Released: 18.1.96\n\nA Swiss Army Knife Utility\n\nCopyright © 1995-1996   All Rights Reserved\n\n\n\n@{" Introduction " LINK Introduction}\n\n@{" System Requirements " LINK SystemRequirements}\n\n@{" Using Tool Type Editor " LINK UsingProgram}\n\n@{" GadTools " LINK GadTools}\n\n@{" Locale Support " LINK LocaleSupport}\n\n@{" Operation Notes " LINK OperationNotes}\n\n@{" Hints And Tips " LINK HintsAndTips}\n\n@{" Reporting Bugs " LINK ReportingBugs}\n\n@{" Incompatibilities " LINK Incompatibilities}\n\n@{" Distribution And Legal Notices " LINK DistributionAndLegalNotices}\n\n@{" Program History " LINK ProgramHistory}\n@{JLEFT}\n@ENDNODE\n\n\n@NODE Introduction "Introduction"\n@TOC Main\n\n    Tool Type Editor is a utility program to quickly and easily edit Tool Types in icon files.\n\n    A full collection of tools is supplied to make short work for updates and changes.\n\n    It can be started in WBStartup and iconified so it is always available.\n\n@ENDNODE\n\n\n@NODE SystemRequirements "System Requirements"\n@TOC Main\n\n    This program requires at least version V39 of the operating system software.  This is to take advantage of the new commands and new tags.  It is now easy enough to update your system so it should not pose a problem.\n\n    This program requires less than 512K of RAM, therefore it should operate on all systems.\n\n    To use the full potential, a harddrive is recommended but not required.\n\n@ENDNODE\n\n\n@NODE UsingProgram "Using Tool Type Editor"\n@TOC Main\n\n        @{" Starting Tool Type Editor " LINK StartingProg}\n\n        @{" Menu Strip " LINK MenuStrip}\n\n        @{" Main Editor " LINK MainEditor}\n\n@ENDNODE\n\n\n@NODE StartingProg "Starting Tool Type Editor"\n@TOC UsingProgram\n\n    This program may be started from the Workbench or the Shell window.\n\n    This program will detach from the Shell so you need not use Run or any other variant.  There are a few command line arguments you may use when loading:\n\n\n    @{b}FILE/K@{ub}\n        File to edit without the .info extension.\n\n    @{b}ICONIFY/S@{ub}\n        Start in iconified mode.\n\n    @{b}ICON_X/K@{ub}\n        X coordinate for AppIcon.\n\n    @{b}ICON_Y/K@{ub}\n        Y coordinate for AppIcon.\n\n    @{b}PUBSCREEN/K@{ub}\n        Name of public screen to open the interface on.\n\n    @{b}LANGUAGE/K@{ub}\n        Preferred locale strings language.\n        Language must be all lower case.\n\n    @{b}DONOTDETACH/S@{ub}\n        Do not detach from the Shell.\n\n\n    The arguments are not case sensitive and may be mixed in any order.\n    ex: ToolTypeEditor FILE MyProgram ICONIFY\n\n@ENDNODE\n\n\n@NODE MenuStrip "Menu Strip"\n@TOC UsingProgram\n\n    @{b}Load Preferences@{ub}\n        This will load the previously saved settings.\n\n    @{b}Save Preferences@{ub}\n        This will save the current settings.\n\n    @{b}Iconify@{ub}\n        Iconify the program and place an AppIcon on the default public screen.\n\n    @{b}About...@{ub}\n        Will open a large requester with some pertinent information about the program.\n\n    @{b}Quit@{ub}\n        Will terminate the program.\n\n    @{b}Cut@{ub}\n        Cut tooltype and replace the clipboard.\n\n    @{b}Copy@{ub}\n        Copy tooltype and replace the clipboard.\n\n    @{b}Cut And Append@{ub}\n        Cut tooltype and append it to the end of the clipboard.\n\n    @{b}Copy And Append@{ub}\n        Copy tooltype and append it to the end of the clipboard.\n\n    @{b}Paste@{ub}\n        Paste the clipboard contents behind the current node.\n\n@ENDNODE\n\n\n@NODE MainEditor "Main Editor"\n@TOC UsingProgram\n\n    @{b}Icon@{ub}\n        Icon currently being editted.\n\n    @{b}Stack@{ub}\n        Stack size for program.\n\n    @{b}Comment@{ub}\n        Comment for file.\n\n    @{b}Default Tool@{ub}\n        Project''s default tool.  A file picker is available to change tools.\n\n    @{b}Tool Types@{ub}\n        List of Tool Types.\n\n    @{b}Tool Type@{ub}\n        Selected Tool Type to be editted.\n\n    @{b}Top@{ub}\n        Move selected Tool Type to the top of the list.\n\n    @{b}Up@{ub}\n        Move selected Tool Type up one position.\n\n    @{b}Down@{ub}\n        Move selected Tool Type down one position.\n\n    @{b}Bottom@{ub}\n        Move selected Tool Type to the bottom of the list.\n\n    @{b}Sort@{ub}\n        Alphabetize list.\n\n    @{b}Script@{ub}\n        Set or clear Script protection bit.\n\n    @{b}Pure@{ub}\n        Set or clear Pure protection bit.\n\n    @{b}Archive@{ub}\n        Set or clear Archive protection bit.\n\n    @{b}Read@{ub}\n        Set or clear Read protection bit.\n\n    @{b}Write@{ub}\n        Set or clear Write protection bit.\n\n    @{b}Execute@{ub}\n        Set or clear Execute protection bit.\n\n    @{b}Delete@{ub}\n        Set or clear Delete protection bit.\n\n    @{b}New@{ub}\n        Append a new Tool Type to end of the list.\n\n    @{b}Insert@{ub}\n        Insert a new Tool Type before the selected Tool Type.\n\n    @{b}Copy@{ub}\n        Copy the selected Tool Type and place at end of the list.\n\n    @{b}Remove@{ub}\n        Remove the selected Tool Type.\n\n    @{b}Open@{ub}\n        Select a different icon to edit.\n\n    @{b}Load@{ub}\n        Re-load icon''s Tool Types.\n\n    @{b}Save@{ub}\n        Save Tool Types to icon.\n\n    @{b}Quit@{ub}\n        This will terminate the program.\n\n@ENDNODE\n\n\n@NODE GadTools "GadTools"\n@TOC Main\n\n    Thanks to Olaf `Olsen'' Barthel, author of gtlayout.library.  It is by far the best user interface package.\n\n    The user interface is totally font and screen mode sensitive.  All gadgets and the window will automatically adjust to match your preferences.\n\n    The latest features are utilized to get the most from the operating system and to make the program the best of it''s kind.\n\n@ENDNODE\n\n\n@NODE LocaleSupport "Locale Support"\n@TOC Main\n\n    This is program is totally localized to allow support for foreign languages.  A catalog may not be available for your language at this time, but one will hopefully be available soon.\n\n    If you are willing to translate the strings to another language, please let me know.  If you do offer, a perfect translation of all strings will be expected.  It is all or nothing.  I will also be seeking your assistance for future versions that have new strings.\n\n@ENDNODE\n\n\n@NODE OperationNotes "Operation Notes"\n@TOC Main\n\n    Press the Help key for AmigaGuide help.\n\n    It can be started in WBStartup and iconified so it is always available.\n\n    The icon file will not have it''s Execute flag set.  ex: ----RW-D\n\n@ENDNODE\n\n\n@NODE HintsAndTips "Hints And Tips"\n@TOC Main\n\n@ENDNODE\n\n\n@NODE ReportingBugs "Reporting Bugs"\n@TOC Main\n\n    I try to make sure all new additions or changes work correctly before releasing a new version, but, something might get by.  If you encounter a bug or a problem with hardware or other programs, please let me know.  Do not assume it will be fixed in the next version because if no one tells me, I may not find it.\n\n    Please be very specific about what the bug does, when it does it, how you found it, and how I can re-create it to test it.  Also let me know what your system consists of: Kickstart version, hard-drives, memory expansion, accelerator card, chip set (original, ECS, AGA), etc.\n\n    If you find a program that is not compatible with this program, please send it to me on a disk or via electronic mail.\n\n\n@{JCENTER}\nProgrammer: A red-eyed mammal capable of conversing with inanimate objects.\n@{JLEFT}\n\n\n    I can be reached at:\n\n    Mark Ritter\n    2008 Valley Vista Dr.\n    Bettendorf, IA  52722\n    USA\n\n\n    FIDO: 1:232/6.0\n\n    InterNet:\n\n@ENDNODE\n\n\n@NODE Incompatibilities "Incompatibilities"\n@TOC Main\n\n@ENDNODE\n\n\n@NODE DistributionAndLegalNotices "Distribution And Legal Notices"\n@TOC Main\n\n    This program may be freely distributed in it''s original form as long as no more than a nominal fee is charged to cover time and copying costs.\n\n    This program may be placed on any Public Domain distribution disk without prior consent from the author.  A copy of the disk would be appreciated.\n\n    This program may not be released with a commercial product without the author''s written consent.  No exceptions.\n\n\n\n    This program is @{b}NOT@{ub} Public Domain, it is Freeware.  Please respect it.\n\n    Because the program is licensed free of charge, there is no warranty for the program, to the extent permitted by applicable law. Except when otherwise stated in writing the copyright holders and/or other parties provide the program "as is" without warranty of any kind, either expressed or implied, including, but not limited to, the implied warranties of merchantability and fitness for a particular purpose.  The entire risk as to the quality and performance of the program is with you.  Should the program prove defective, you assume the cost of all necessary servicing, repair or correction.\n\n    In no event, unless required by applicable law or agreed to in writing, will any copyright holder, or any other party who may modify and/or redistribute the program as permitted above, be liable to you for damages, including any general, special, incidental or consequential damages arising out of the use or inability to use the program (including but not limited to loss of data or data being rendered inaccurate or losses sustained by you or third parties or a failure of the program to operate with any other programs), even if such holder or other party has been advised of the possibility of such damages.\n\n@ENDNODE\n\n\n@NODE ProgramHistory "Program History"\n@TOC Main\n\nVersion 1.0     Completed: 3.5.95\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n- Preliminary construction.\n\n- Added text gadget to display filename; should have been in original layout.\n\n- Added several new gadgets to make it a complete icon editor, not just the\n  tool types: Stack, Comment, Default Tool, Script, Pure, Archive, Read,\n  Write, Execute, and Delete.\n\n- Added Icon_X and Icon_Y arguments to place AppIcon where the user wants it.\n\n- Added command line argument [LANGUAGE <language>] to specify a preferred\n  language for locale strings.\n\n- Many code updates for handling ToolTypes and made ListView hook routine.\n\n- Can now only edit Drawers, Projects and Tools icons.\n\n- Added a check if started Iconified to verify termination or go back to\n  iconified mode.\n\n- Added Options menu with Icon Not Executable option to clear execute flag\n  from icon file.    ----RW-D\n\n- Added prefs file.\n\n- Split alot of set up and shut down code into a seperate file,\n  MyProgramSupport.c to speed up compilation and easier updating.\n\n- Fixed a small bug when can''t GetDiskObject().\n\n- Removed alot of extraneous code that I no longer needed or I overlooked in\n  gtlayout.library.\n\n- Updated routine to start iconified.\n\n- Exec lists updates.\n\n- Wrote AmigaGuide.\n\n- Public release.\n\n\n\nVersion 1.1     Completed: 18.1.96\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n- Added new menu:\n    Clipboard\n        Cut             X\n        Copy            C\n        ~~~~~~~~~~~~~~~\n        Cut And Append  N\n        Copy And Append M\n        ~~~~~~~~~~~~~~~\n        Paste           V\n\n  This isn''t a real clipboard, but hey!  Can now copy tooltypes between multiple\n  copies.\n\n- Took out Options menu and now automatically not set Execute flag in icon.\n\n- Updated list routines for Top, Up, Down, Bottom, New, and Insert.  Needed it\n  badly.\n\n- No longer needs/has a prefs file.\n\n- Updated AmigaGuide.\n\n- Public Release.\n\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',91498,5,0,NULL,NULL,'totyed11','scan',1780048787);
