INSERT INTO door_catalog VALUES('toybetas','TOYBETAS.LZX','~/Code/amiexpress_doors/Archives/AmiExpress/TOYBETAS.LZX',NULL,'XIM','ToyLZX',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'auto-added',46153,0,0,NULL,NULL,'toybetas','scan',1780048787);
INSERT INTO door_catalog VALUES('tpager10','TPAGER10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TPAGER10.LHA',NULL,'XIM','TopPager.030',NULL,NULL,NULL,'_/~____/\_/\_KZ_/~_______¬\_  _/~____/ 7___ ¬7  7  7__7  __)7~¬7  7  7___ ¬7 | ¬7  ¡  !  ¡ ¬¡    ¬|  |  !  ¡ ¬7  ¡',replace('     ______         _____________________\n   _/~____/\_/\_KZ_/~_______¬\_  _/~____/\n   7___ ¬7  7  7__7  __)7~¬7  7  7___ ¬7\n   | ¬7  ¡  !  ¡ ¬¡    ¬|  |  !  ¡ ¬7  ¡\n   l_____j__j_____j_____j__j__j__j_____j\n       TopPager v1.0 for /X v2.x-3.x\n','\n',char(10)),'TopPager.guide',replace('@DATABASE "TopPager v1.0 by Dux/Tsl"\n\n@NODE MAIN "TopPager v1.0 by Dux/Tsl"\nx×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x\nx                                                                         x\nx                             TopPager v1.0                               x\nx                               By Dux/Tsl                                x\nx                                                                         x\nx×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x×x\n\n   If you''re running a pirate version of AmiExpress, you may !NOT! use this\n              utility! If you''re using AmiExpress - Then BUY it!\n\n@{" Introduction " Link Introduction}\n@{" Requirements " Link Requirements}\n@{" Usage " Link Usage}\n@{" Bugs " Link Bugs}\n@{" Registration " Link Registration}\n@{" History " Link History}\n@{" How to contact " Link How_to_contact}\n@{" Hellos " Link Hellos}\n@ENDNODE\n\n@NODE Introduction "Introduction"\nHave you ever chatted for hours and wanted to know exactly how LONG you''ve\nbeen chatting?? Well then the Chat-O-Meter can solve your problem!\n\n\n\n@ENDNODE\n\n@NODE Requirements "Requirements"\n- AmiExpress (with a REAL registration!)\n- T: assigned somewhere\n\n\n\n@ENDNODE\n\n@NODE Usage "Usage"\n@{" Installation " Link Installation}\n@{" Daily use " Link Daily_use}\n@{" Syntax " Link Syntax}\n@ENDNODE\n\n@NODE Installation "Installation"\nJust copy the TopPager to a directory in your path. Eg. BBS:Utils/. Then\nrun it just once to make the datafile. More info is available with @{" Syntax " Link Syntax}.\n\n@ENDNODE\n\n@NODE Daily_use "Daily use"\nYou should run it in your logoff-script with the U option. This will update\nthe datafile.\n\nThen a couple of times a day you should update the bulletin with the C\noption, this will create a bulletin. More info is available with @{" Syntax " Link Syntax}.\n\n@ENDNODE\n\n@NODE Syntax "Syntax"\nSYNTAX: TopPager <U/C> <Callerslog/Outputfile> <Datafile>\n                   [No. of users] [Design no.]\n\n<U/C> (U)pdate the datafile or (C)reate a bulletin.\n\n<Callerslog/Outputfile> is the path for your callerslog when you UPDATE\nthe datafile and the outputfile is the path to the bulletin you wish to\nCREATE.\n\n<Datafile> is the path to the datafile where you wish to store the\ntoppagers.\n\n\nThe next 2 arguments are only used when CREATING a bulletin!\n\n[No. of users] is the number of users you want listed in your bulletin.\n\n[Design no.] is what look you want on your bulletin. 3 different designs\nare available at this moment.\n\n@ENDNODE\n\n@NODE Bugs "Bugs"\nThere''s no known bugs at the moment, but if any problems should occur,\nplease contact me at my board. @{" How to contact " Link How_to_contact}\n\n@ENDNODE\n\n@NODE Registration "Registration"\nI do no longer give out the free optimized and registred versions! BUT I\nwould like to know if you run my utils, so please contact me by calling\nmy board or send me a msg. @{" How to contact " Link How_to_contact}\n\n\n\n@ENDNODE\n\n@NODE History "History"\nv1.0 - First release. No known bugs.\n\n\n@ENDNODE\n\n@NODE How_to_contact "How to contact"\nI can be reached at my board: MAiNLiNE +45-981-53062 or by netmail through\nAmiXnet: Dux@DK0001.\n\n\n@ENDNODE\n\n@NODE Hellos "Hellos"\n@{" Alzheimer " Link Alzheimer}\n@{" Van Damme " Link Van_Damme}\n@{" Empire " Link Empire}\n@{" Tarzan " Link Tarzan}\n@{" Frostie " Link Frostie}\n@{" Fun Fun " Link Fun_Fun}\n@{" Scratch " Link Scratch}\n@{" Ice Q " Link Ice_Q}\n@{" Zany " Link Zany}\n@{" Lector " Link Lector}\n@{" Mr. Beer " Link Mr._Beer}\n@{" Danzig " Link Danzig}\n@ENDNODE\n\n@NODE Alzheimer "Alzheimer"\nI haven''t seen anything from you lately... Have you left the scene?\n\n@ENDNODE\n\n@NODE Van_Damme "Van Damme"\nHey, please contact me through Amixnet. I''ve got some bugreports and\nsuggestions for ya.\n\n@ENDNODE\n\n@NODE Empire "Empire"\nReally cool that you''ve converted the JoinCnf to C. Also nice hearing from\nya on Amixnet.\n\n@ENDNODE\n\n@NODE Tarzan "Tarzan"\nAmixnet rules, eh?\n\n@ENDNODE\n\n@NODE Frostie "Frostie"\nToo bad you closed down your board. It was nice.\n\n@ENDNODE\n\n@NODE Fun_Fun "Fun Fun"\nNo special msg.\n\n@ENDNODE\n\n@NODE Scratch "Scratch"\nNo special msg.\n\n@ENDNODE\n\n@NODE Ice_Q "Ice Q"\nNo special msg.\n\n@ENDNODE\n\n@NODE Zany "Zany"\nI hope you like your new vote-door for PacMag!\n\n@ENDNODE\n\n@NODE Lector "Lector"\nShame you closed the board down.\n\n@ENDNODE\n\n@NODE Mr._Beer "Mr. Beer"\nNo special msg.\n\n@ENDNODE\n\n@NODE Danzig "Danzig"\nI''ve got your door ready. Call me and pick it up.\n\n@ENDNODE\n\n','\n',char(10)),NULL,'auto-added',22765,5,0,NULL,NULL,'tpager10','scan',1780048787);
