INSERT INTO door_catalog VALUES('tport2','TPORT2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TPORT2.LHA','Teleport2','XIM','Teleport2','2.0',NULL,NULL,'.- Fastest nullmodem filetransfer program -. |------------------------------------------| |     880.000 bps with error correction    |',replace(' -  -- ----=[  Teleport v2.0  ]=---- --  -\n.- Fastest nullmodem filetransfer program -.\n|------------------------------------------|\n|     880.000 bps with error correction    |\n|           One Mb in nine seconds         |\n|     Ability to recover failed transfer   |\n|             Download / Upload            |\n|            Many new functions!           |\n|                                          |\n|   Faster than Parnet, Twin, Sernet etc.  |\n`------------------------------------------''\nBUNDYLAND:0551/44356(28k8)541709(ISDN+28k8)\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :            