INSERT INTO door_catalog VALUES('tra14c','TRA14C.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRA14C.LHA','TrapPrefs','XIM','exe.-l0S-eND0S-bBS-.exe','1.4',NULL,NULL,NULL,replace('Trapdoor 1.84+ Preferences v1.4c\n','\n',char(10)),'TrapPrefs.guide',replace('@database TrapPrefs.guide\n@master TrapPrefs.guide\n@$VER: 1.4c\n@author "Michael J. Barsoom"\n@(c) "1994-95 by Michael J. Barsoom"\n@index HeddleyAutoIndex\n@remark Created with Heddley v1.1 (c) Edd Dumbill 1994\n\n@node "Main" "TrapPrefs v1.4 documentation"\n\n                               TrapPrefs v1.4c\n                   Preference editor for TrapDoor v1.84+\n\nTrapPrefs and this documentation are Copyright © 1994-95 by Michael Barsoom.\n\n @{" Copyright & Disclaimer " link "Copyright_&_Disclaimer" 0}  --  Please read this first.\n @{" Features               " link "Features" 0}  --  What exactly does TrapPrefs do?\n @{" Requirements           " link "Requirements" 0}  --  What you need to run TrapPrefs.\n @{" Locale                 " link "Locale" 0}  --  Using TrapPrefs in your own language.\n @{" Usage                  " link "Usage" 0}  --  How do I get it to work?\n @{" Gadgets                " link "Gadgets" 0}  --  What do all the gadget do?\n @{" CLI and ToolTypes      " link "CLI" 0}  --  Other Options\n @{" Author''s Address       " link "Address" 0}  --  How do I reach the author.\n @{" Shareware              " link "Shareware" 0}  --  Shareware information.\n @{" Special Thanks         " link "Registered" 0}  --  Who has supported TrapPrefs\n @{" History                " link "History" 0}  --  What has changed.\n @{" Thanks To              " link "Thanks" 0}  --  Who helped make TrapPrefs\n @{" ToDo                   " link "ToDo" 0}  --  What''s in store for the future\n @{" Questions              " link "Questions" 0}  --  These are not bugs\n@endnode\n\n@node "Copyright_&_Disclaimer" "Copyright & Disclaimer"\n                   TrapPrefs and this documentation are\n                 Copyright © 1994-95 by Michael J. Barsoom\n\n\nTrapPrefs may be freely distributed as long as no charge is made other than to\ncover time and copying costs. If it is to be distributed via floppy disk, this\ncost should be no higher than $3.00 (three) dollars US.  If distribution is\nvia CDRom, the total cost should be no more than $25.00 (twenty-five) dollars\nUS.\n\nYou may not copy and/or distribute this program without the accompanying\ndocumentation unless you get permission from the author to do so.  Fred Fish\nand Walnut Creek already have my permission to include this program on their\nCDRom collections.\n\nIf you write a freely redistributable program and would like to include\nTrapPrefs with it, feel free to do so only if you send me a fully registered\nversion of your program and keep all the files included in this archive.\n\nFinally if you wish to include TrapPrefs on a disk magazine you are REQUIRED\nto get the author''s permission FIRST.  Usually this will require you to just\nsend me a copy of the issue with TrapPrefs free of charge AND register your\ncopy of TrapPrefs.\n\nPlease see @{"Address" link "Address" 0} for how to you can reach me.\n\n                           -+- Disclaimer -+-\n\nThis product is sold "as is" without representation or warranty of any kind,\neither expressed or implied.  The user assumes all risks and responsibilities\nrelated to its use.\n@endnode\n\n@node "Features" "Features"\nTrapPrefs is an intition based preference editor for TrapDoor.\n\nFeatures:\n    o Supports all of the features of TrapDoor 1.84+\n    o All options can be set with simple cycle gadgets, and string\n      gadgets.\n    o Log and Stat window sizes can be set simply by adjusting their\n      size and location and clicking on a close gadget.\n    o ReqTools screenmode and palette requesters.\n    o Full locale support.\n    o No anoying restrictions or requesters.\n    o Freely distributable @{"SHAREWARE" link "shareware" 0}.\n    o MUI interface.\n\n    o For register users the follow additional features are available\n         - Users of TIF can configure the Labels for the FKey gadgets\n\n@endnode\n\n@node "Thanks" "Thanks"\nI''d like to thank the follow people for their help is creating TrapPrefs:\n\nMy loving wife.\n     For being herself.\n\nPiergiorgio Ghezzo\n     For reporting many bugs, and helping in beta testing.\n\nEveryone who has or will have registered TrapPrefs\n     For supporting shareware.\n\nNico Francois\n     For ReqTools.\n\nMaximilian Hantsch and Martin Laubach\n     For TrapDoor.\n\nStefan Stuntz\n     For MUI, and for answering my programming questions.\n@endnode\n\n@node "Requirements" "Requirements"\nTrapPrefs does not require much, you just need to have the following:\n\n 1) Workbench 2.0+\n 2) ReqTools library (© Nico Francois)\n 3) @{"Magic User Interface" link "MUI" 0} v2.1 (will not work with 2.0 or before)\n 4) TrapDoor v1.84 or v1.85 (© Maximilian Hantsch and Martin Laubach)\n\nOptional\n 1) Traplist library and a nodelist\n 2) TIF (© Brian Jacobsen)\n@endnode\n\n@node "Locale" "Locale"\n TrapPrefs can be run in you prefered language.  To do this you need to copy\nthe appropriate trapprefs.catalog to you locale directory.  If your language\nis not included, feel free to translate the included .ct file and send it to\nme and I will send back to you the .catalog file.\n\nNOTE: If you intend to translate TrapPrefs to your language, please read the\n      included TrapPrefs.cd as there are some special instructions needed for\n      proper translation.\n\nNOTE:  As the number of registrations was very poor, only three, I will no\n       longer be contacting the authors about updating the translations, as\n       this takes too much time on my part and results in little gain.\n       I will include the translations with the archive if they are sent to\n       me however.  This will change if I start receiving more registrations.\n\nThanks to the following for their translations:\n\nPiergiorgio Ghezzo ([email removed])\n     for the Italian translation\n\nSteffen Salzmann (2:244/1544.2)\n    for the German translation\n\nFlorent Monteilhet ([email removed])\n    for the French translation\n\nThe following made translations for older versions of TrapPrefs, but were\nnot updated for v1.4\n\nMichael Berg (2:238/24.28 | [email removed])\n    for the Danish translation\n\nJanne Saarme ([email removed])\n    for the Finnish translation\n\nMagnus Holmgren (2:204/[email removed] | [email removed])\n    for the Swedish translation\n@endnode\n\n@node "Usage" "Usage"\nTrapPrefs\n\nAll of the buttons, cycle gadgets, and button gadgets set one of TrapDoor''s\nkeywords.  You just set the values as you want them they will automatically be\nsaved for you.  Please see TrapDoor.guide for a detailed explaination of each\noption.\n\nThe Menu:\n    Open    --  Loads a TrapDoor.cfg file into the prefs editor.\n    Open As --  Opens a filerequester so that you can specify the name\n                of the config to load.\n\n    Save    --  Save the current config with the current name or as\n                "Mail:TrapDoor.cfg" if none is specified\n    Save As --  Opens a filerequester so that you can specify the name\n                of the config to save.\n\n    About   --  duh :-)\n\n    Quit    --  Do I really need to tell you.\n\n    Reset to Defaults  --  set all options to TrapDoor''s default values.\n                           NOTE: the cycle gadgets have the default setting\n                                 in black, and the non default setting\n                                 in white or the style specified with the\n                                 COLOR tooltype\n\n    Save TIF Labels --  the state of this checkmark menu item tells TrapPrefs\n                        whether or not it should save the TIF labels.  This\n                        will automatically be set if the loaded config\n                        contains TIF labels, or you press return in one of\n                        the TIF label string gadget.  NOTE: this is only\n                        available in the registered version.\n\n    Snapshot window --  when this is checked, TrapPrefs will save its window\n                        position and size to disk when you quit.  NOTE: this\n                        is only available in the registered version.\n\nLoading configurations:\n    When loading a configuration, if an error is discovered you will be\n    notified of the error.  The error requester has three gadgets on it:\n         Abort:    Stop loading the config, and restore previous config.\n                   Note:  in order to restore the previous config the\n                   directory T: must exist.\n         Continue: Continue loading the config ignoring just this error\n         Ignore:   Continue loading the config ignoring this and future\n                   errors\n\nThe Window sizes:\n    Clicking this gadget opens two windows, one representing the Log window\n    and the other the Status window.  Just adjust the position and size as\n    you want them and click either close gadget.\n\n    If you change your mind just select ''Cancel'' from the menu.\n\nThe Palette requester:\n    If your screen mode is not Workbench or Active, a screen will open up\n    as defined in your preferences with a palette requester on it.  Just\n    adjust palette and click on OK to save the new palette.\n\n    If you want to save a copy of the current WorkBench palette select\n    ''Use WorkBench Palette''.\n\n\nThe Modem Mode:\n    This is were you set the default state for TrapDoor.\n    There are the following three options:\n\n    Answer     put TrapDoor in answer mode\n    Call BOSS  make TrapDoor call your boss\n    Call       with this option you need to fill in the ''Who'' string.  This\n               can be a node/point number or a phonenumber depending on if\n               you have a nodelist installed.\n\nOnline help:\n    Pressing ''HELP'' with the cursor over a gadget will automaticall open up\n    the appropriate page in TrapDoor.guide.  TrapDoor.guide must appear in\n    your AmigaGuide search path.\n    NOTE: Users of Workbench 2.x require MUI v2.3 in order for this to work.\n@endnode\n\n@node "Gadgets" "Gadgets"\nNOTE:  This page requires that TrapDoor.guide be found in you AmigaGuide\n       path.\n\nMain Pages\n\n    @{" System Settings  " link "System" 0}\n    @{" General Settings " link "General" 0}\n    @{" Modem Settings   " link "Modem" 0}\n    @{" System Settings  " link "Session" 0}\n    @{" Screen Settings  " link "Screen" 0}\n    @{" Function Keys    " link "TrapDoor.guide/4.3.43" 0}\n@endnode\n\n@node "System" "System Settings"\n\n    @{" Sysop Name  " link "TrapDoor.guide/4.3.111" 0}\n    @{" BBS Name    " link "TrapDoor.guide/4.3.71" 0}\n    @{" Node Number " link "TrapDoor.guide/4.3.72" 0}\n    @{" AKA''s       " link "TrapDoor.guide/4.3.8" 0}\n    @{" BOSS        " link "TrapDoor.guide/4.3.23" 0}\n    @{" Password    " link "TrapDoor.guide/4.3.75" 0}\n@endnode\n\n@node "General" "General Settings"\n Log File:   @{" LogFile          " link "TrapDoor.guide/4.3.58" 0}\n            @{" LogCallerID      " link "TrapDoor.guide/4.3.57" 0}\n            @{" MaxLogSecs       " link "TrapDoor.guide/4.3.63" 0}\n            @{" MaxLogLines      " link "TrapDoor.guide/4.3.62" 0}\n\n            @{" Log Groups       " link "TrapDoor.Guide/4.3.56" 0}\n\nOther:      @{" Inbound          " link "TrapDoor.guide/4.3.49" 0}\n            @{" OutBound         " link "TrapDoor.guide/4.3.74" 0}\n            @{" NodeList         " link "TrapDoor.guide/4.3.73" 0}\n\n            @{" ShowRexx         " link "TrapDoor.guide/4.3.97" 0}\n            @{" ARexx Port       " link "TrapDoor.guide/4.3.83" 0}\n            @{" TimeStamp        " link "TrapDoor.guide/4.3.114" 0}\n            @{" Priority         " link "TrapDoor.guide/4.3.113" 0}\n            @{" UseUserShell     " link "TrapDoor.guide/4.3.119" 0}\n            @{" Esc Resets Modem " link "TrapDoor.guide/4.3.39" 0}\n@endnode\n\n@node "Modem" "Modem Settings"\n Serial:         @{" Min Baud            " link "TrapDoor.guide/4.3.64" 0}\n                @{" Baud                " link "TrapDoor.guide/4.3.16" 0}\n                @{" Max Baud            " link "TrapDoor.guide/4.3.61" 0}\n                @{" Lock                " link "TrapDoor.guide/4.3.55" 0}\n                @{" FloatLock           " link "TrapDoor.guide/4.3.44" 0}\n                @{" DSR                 " link "TrapDoor.guide/4.3.37" 0}\n                @{" 7Wire               " link "TrapDoor.guide/4.3.1" 0}\n                @{" Shared              " link "TrapDoor.guide/4.3.96" 0}\n                @{" Serial Name         " link "TrapDoor.guide/4.3.94" 0}\n                @{" Serial Flags        " link "TrapDoor.guide/4.3.93" 0}\n                @{" Serial Unit         " link "TrapDoor.guide/4.3.95" 0}\n                @{" Adjust              " link "TrapDoor.guide/4.3.6" 0}\n                @{" SerialBufSize       " link "TrapDoor.guide/4.3.92" 0}\n                @{" SlowModem           " link "TrapDoor.guide/4.3.99" 0}\n\nDial Strings    @{" Modem Answer        " link "TrapDoor.guide/4.3.65" 0}\n                @{" Modem HangUp        " link "TrapDoor.guide/4.3.68" 0}\n                @{" Modem Dial Pre      " link "TrapDoor.guide/4.3.66" 0}\n                @{" Modem Dial Post     " link "TrapDoor.guide/4.3.67" 0}\n                @{" Modem Init          " link "TrapDoor.guide/4.3.69" 0}\n                @{" Dialer              " link "TrapDoor.guide/4.3.31" 0}\n                @{" Ring Command        " link "TrapDoor.guide/4.3.84" 0}\n\nDial Misc:      @{" KiwiPulse           " link "TrapDoor.guide/4.3.53" 0}\n                @{" SwePulse            " link "TrapDoor.guide/4.3.106" 0}\n                @{" Strip Dashes        " link "TrapDoor.guide/4.3.107" 0}\n\n                @{" Answer              " link "TrapDoor.guide/4.3.10" 0}\n                @{" Call                " link "TrapDoor.guide/4.3.24" 0}\n\n                @{" Rings               " link "TrapDoor.guide/4.3.86" 0}\n                @{" Ringings            " link "TrapDoor.guide/4.3.85" 0}\n                @{" Dial TimeOut        " link "TrapDoor.guide/4.3.32" 0}\n                @{" ModemResetInterval  " link "TrapDoor.guide/4.3.70" 0}\n                @{" Redial Delay        " link "TrapDoor.guide/4.3.80" 0}\n                @{" Retries             " link "TrapDoor.guide/4.3.82" 0}\n@endnode\n\n@node "Session" "Session settings"\n Connection:     @{" Emsi             " link "TrapDoor.guide/4.3.38" 0}\n                @{" FastEmsi         " link "TrapDoor.guide/4.3.40" 0}\n                @{" WaZoo            " link "TrapDoor.guide/4.3.122" 0}\n                @{" DietIFNA         " link "TrapDoor.guide/4.3.33" 0}\n                @{" ZedZip           " link "TrapDoor.guide/4.3.127" 0}\n                @{" ZedZap           " link "TrapDoor.guide/4.3.126" 0}\n                @{" DirectZap        " link "TrapDoor.guide/4.3.34" 0}\n                @{" TrapZap          " link "TrapDoor.guide/4.3.115" 0}\n                @{" Immediate        " link "TrapDoor.guide/4.3.48" 0}\n                @{" SniffARQ         " link "TrapDoor.guide/4.3.101" 0}\n\n                @{" ARQ String       " link "TrapDoor.guide/4.3.11" 0}\n\nTransfer:       @{" PickUp           " link "TrapDoor.guide/4.3.76" 0}\n                @{" Forbid XMail     " link "TrapDoor.guide/4.3.45" 0}\n                @{" Forbid All       " link "TrapDoor.guide/4.3.45" 0}\n                @{" ABS              " link "TrapDoor.guide/4.3.3" 0}\n                @{" Keep All         " link "TrapDoor.guide/4.3.51" 0}\n                @{" XMail            " link "TrapDoor.guide/4.3.125" 0}\n                @{" Forbid Freq      " link "TrapDoor.guide/4.3.45" 0}\n                @{" Allow Refusing   " link "TrapDoor.guide/4.3.9" 0}\n                @{" Keep XMail       " link "TrapDoor.guide/4.3.52" 0}\n\nBBS:            @{" BBS Mode         " link "TrapDoor.guide/4.3.21" 0}\n                @{" BBS Message      " link "TrapDoor.guide/4.3.20" 0}\n                @{" BBS Command      " link "TrapDoor.guide/4.3.18" 0}\n                @{" BBS Char         " link "TrapDoor.guide/4.3.17" 0}\n                @{" BBSInOut         " link "TrapDoor.guide/4.3.19" 0}\n                @{" Drop BBS Seconds " link "TrapDoor.guide/4.3.36" 0}\n                @{" Banner           " link "TrapDoor.guide/4.3.15" 0}\n\nMisc:           @{" After Session    " link "TrapDoor.guide/4.3.7" 0}\n                @{" File Request     " link "TrapDoor.guide/4.3.46" 0}\n                @{" Fax String       " link "TrapDoor.guide/4.3.42" 0}\n                @{" Fax Command      " link "TrapDoor.guide/4.3.41" 0}\n                @{" Turn around      " link "TrapDoor.guide/4.3.116" 0}\n                @{" Voice String     " link "TrapDoor.guide/4.3.121" 0}\n                @{" Voice Command    " link "TrapDoor.guide/4.3.120" 0}\n\nAccounting:     @{" Accounting       " link "TrapDoor.guide/4.3.4" 0}\n                @{" Cost             " link "TrapDoor.guide/4.3.29" 0}\n                @{" Account Limits   " link "TrapDoor.guide/4.3.5" 0}\n@endnode\n\n@node "Screen" "Screen Settings"\n\n    @{" Quiet              " link "TrapDoor.guide/4.3.79" 0}\n    @{" Auto Adjust        " link "TrapDoor.guide/4.3.12" 0}\n    @{" Beep Display       " link "TrapDoor.guide/4.3.22" 0}\n    @{" Wrap Lines         " link "TrapDoor.guide/4.3.123" 0}\n    @{" Zoom Full Size     " link "TrapDoor.guide/4.3.128" 0}\n    @{" Background         " link "TrapDoor.guide/4.3.14" 0}\n    @{" Interlace          " link "TrapDoor.guide/4.3.50" 0}\n    @{" Auto OverScan      " link "TrapDoor.guide/4.3.13" 0}\n    @{" Use System Font    " link "TrapDoor.guide/4.3.118" 0}\n    @{" Screen Mode        " link "TrapDoor.guide/4.3.89" 0}\n    @{" Public Screen Name " link "TrapDoor.guide/4.3.77" 0}\n    @{" DisplayID          " link "TrapDoor.guide/4.3.35" 0}\n    @{" Window Sizes       " link "TrapDoor.guide/4.3.60" 0}\n    @{" Palette            " link "TrapDoor.guide/4.3.26" 0}\n@endnode\n\n@node "CLI" "Tooltypes and CLI options"\nTrapPrefs supports the following tooltypes / cli options\n\nTooltype and/or CLI option\n\n    CONFIG - name of TrapDoor config file to load at startup.  For example\n             if you want TrapPrefs to automatically load\n             "Mail:TrapDoor.cfg" when it is first run just add the\n             following tooltype: ''CONFIG=Mail:TrapDoor.cfg''\n\nTooltypes only\n\n    COLOR - color or style TrapPrefs should use to display non default\n            options.  This option will be read even if TrapPrefs is started\n            from the CLI.\n\n            You can use any of the following:\n\n            u    Set the soft style to underline.\n            b    Set the soft style to bold.\n            i    Set the soft style to italic\n            n    Set the soft style back to normal.\n           <n>   Use pen number n (2..9) as front pen. n must be a valid\n                 DrawInfo pen as specified in "intuition/screens.h".\n\n@endnode\n\n@node "Address" "Address"\nyou can reach me at:\n\nMichael Barsoom 5524 Pine Street Omaha NE 68106 USA\n\n Internet:  [email removed]\n  Fidonet:  Michael Barsoom @ 1:285/5.9\n\n\n -----BEGIN PGP PUBLIC KEY BLOCK-----\n Version: 2.6.1\n\n mQA9Ai2jXm4AAAEBgLf/AeR6SwrnG8R58JzSTNa/mO4rlCE3ud7BiaiN+7qxpcWa\n LKYgruZG/ayIOQugSQAFEbQqTWlrZSBCYXJzb29tIDxtYmFyc0BibHVlamF5LmNy\n ZWlnaHRvbi5lZHU+\n =SMOG\n -----END PGP PUBLIC KEY BLOCK-----\n@endnode\n\n@node "Shareware" "Shareware"\nPLEASE SUPPORT SHAREWARE!\n\nTrapPrefs is shareware, you can set all of TrapDoor 1.84+ features in the\nevauation version.  However starting with v1.3 features above those required\nto configure TrapDoor will only be available in the evaulation version.\n\nThe following features which are available only in the registered version.\n    o You will be able to load, edit, and save the Labels for the gadgets\n      which are part of TIF.\n    o You can snapshot the size and position of the window to disk\n\nPlease, if you use TrapPrefs on a regular basis, concider sending me the\nregistration fee.  Once I receive your registration fee I will promptly send\nyou a key file which will personalize and unlock your copy of TrapPrefs and\nTrapListPrefs, the same keyfile works for both programs.\n\nThe following is the current price list for TrapPrefs/TrapListPrefs:\n Register with keyfile sent via e-mail:        $10.00 US.\n Register with keyfile send via regular mail:  $12.00 US. ($10 + $2 S&H)\n\nPlease see @{"Address" link "Address" 0} for how to you can reach me and where to send in your\nregistration fee.\n\n                       --- UK registration site ---\nIf you prefer you can register through my UK registration site.\nRegistrations at this site are handled by:\n\n	Dave Naylor\n	18 Campinot Vale\n	Slaithwaite West Yorkshire\n	HD7 5EY\n	England\n\n	Internet: [email removed]\n	 FidoNet: 2:250/366.0\n\nWith the following pricelist:\n Register with keyfile sent via e-mail:           8.50 UKP\n Register with keyfile send via regular mail:    10.00 UKP\n\n Please allow 2-4 weeks for delivery.\n\nSending in your registration fee will help ensure futhor developement of\nTrapPrefs.  Also I will give priority to suggestions and questions from\nregister users.\n\n@endnode\n\n@node "History" "History"\nWhat has changed - most recent release is first.\n\nv1.4c\n    o Added updated french catalog\n    o Updated docs to show addition of UK registration site.\n    o recompiled with SAS-C 6.55\n\nv1.4b\n    o Added a workaround to fix a bug in MUI, which causes enforcer hits\n      when string gadgets are cleared.\n    o If both the Boss and Call Who gadgets where blank, when loading a\n      config the mode would be changed to Call Boss, no matter what was\n      specified in the config.\n\nv1.4a\n    o Opps, TrapPrefs was not saving the log levels (fixed)\n    o Added German and Italian catalogs\n\nv1.4\n    o ReqTools is no longer be used for the file requesters, TrapPrefs will\n      now use the built in ASL functions of MUI.\n      NOTE:  ReqTools is still required for the palette and screen mode\n             requesters.\n    o "True Color" screen modes were only being filtered if a DisplayID\n      was already defined. (fixed)\n    o Added PublicScreen selector to Public Screen string gadget\n    o Completely changed the way TrapPrefs stores the current config in\n      memory.\n    o Added warning if config has been changed, but not saved.\n\nv1.3b\n    o Screen mode requester should no longer display the "True Color" modes\n      when using graphics boards.  I''m not sure if this actually works as\n      I don''t have a gfx board to try it out.\n    o Added Swedish, thanks to Magnus Holmgren for sending it to me.\n\nv1.3a\n    o ''Use workbench Palette'' gadget was not being disabled correctly\n      (fixed)\n    o Fixed some memory leaks.\n\nv1.3\n    o Fixed small error in installer script.\n    o The AutoOverScan and Interlace gadgets were not being disabled\n      correctly when a DisplayID was specified (fixed)\n    o Added French translation.\n    o Moved ''Select DisplayID'' to a popup gadget, and added ''Use Workbench\n      Colors''\n    o Added "Snapshot window" menu item, if this item is checked, the size\n      and position of the window will be saved when you quit TrapPrefs\n      (requires that C:Copy exist)\n      - available only in the registered version\n    o Added ability to save and edit the Labels for the gadgets on the\n      TIF screen. - available only in the registered version\n    o Screen Mode requester will now default to the current setting in\n      the DisplayID - suggested by Steffen Salzmann\n\nv1.2\n    o About requester said ''TrapListPrefs'' instead of ''TrapPrefs'' (fixed)\n      - reported by Steffen Salzmann\n    o ''Abort'' did not work correctly, requester would appear more than\n       once (fixed)\n      - reported by Steffen Salzmann\n    o If you click on ''Abort'', old config will be restored\n      - suggested by Steffen Salzmann\n\nv1.1\n    o Localized a few more strings.  You will need TrapPrefs catalog v1.1\n      for the new strings to be localized.\n    o Fixed a few spelling errors\n      - reported by Michael Berg\n    o Added keyfile support, now when you register you will receive a\n      keyfile to personalize your copy.  TrapPrefs itself still remains\n      completely non crippled, however the TrapListPrefs will require the\n      key file in order to work.\n    o Added Abort and Continue options to error requesters when loading\n      config.\n      - suggested by Steffen Salzmann\n    o Added hypertext link to TrapDoor.guide.  Now pressing HELP over a\n      gadget will bring up the appropriate page in TrapDoor.guide.  NOTE:\n      This feature requires that TrapDoor.guide be available in your\n      AmigaGuide path.\n      - requested by Piergiorgio Ghezzo\n    o Added NodeList support, now if you have a nodelist TrapPrefs will\n      read it and display the name and sysop of your boss.\n\nv1.0\n    o Fixed several enforcer hits when Resetting to Defaults\n      - reported by Andre Schenk\n    o Fixed an enforcer hit which magically appeared when I upgraded to\n      MUI 2.2.  I believe the problem is with MUI v2.2 not TrapPrefs.\n    o Dropped beta status.\n\n0.9ß - 0.99ß\n    o Anceint history\n@endnode\n\n@node "ToDo" "ToDo"\n The following are some ideas I still have for TrapPrefs, many of them will\ndepend on the response I get:\n\n    o Make editors for SetConfig, SetPassword and other TrapDoor programs.\n      This will depend on the response -- number of registrations I get :-)\n    o Add "Save and Notify" to menus.  This would save the current config,\n      and then tell TrapDoor, if it is running in memory, to read the new\n      config.\n\n\n    o Any good ideas you may have :-)\n@endnode\n\n@node "MUI" "MUI"\n\n                          This application uses\n\n\n                        MUI - MagicUserInterface\n\n                (c) Copyright 1993/94 by Stefan Stuntz\n\n\nMUI is a system to generate and maintain graphical user interfaces. With the\naid  of  a  preferences program, the user of an application has the ability to\ncustomize the outfit according to his personal taste.\n\nMUI is distributed as shareware. To obtain a complete package containing lots\nof examples and more information about registration please look for a  file\ncalled  "muiXXusr.lha"  (XX means the latest version number) on your local\nbulletin boards or on public domain disks.\n\n          If you want to register directly, feel free to send\n\n\n                         DM 30.-  or  US$ 20.-\n\n                                  to\n\n                             Stefan Stuntz\n                        Eduard-Spranger-Straße 7\n                             80935 München\n                                GERMANY\n@endnode\n\n@node "Questions" "Questions"\n1. I get an error while reading the config if my dial strings\n   contain ''='' in it.\n\n   This is a fault of AmigaDos.  I use ReadArgs() calls in order to read\n   the config, and this function uses the ''='' as a separator between key\n   words and arguments.  The fix for this is very easy, enclose the string\n   in quotes.  This is the way the examples in TrapDoor.guide are shown, and\n   how TrapPrefs will save them.\n\n   As an example use MODEMANSWER "~~~ATS7=25A|"\n                 not MODEMANSWER ~~~ATS7=25A|   <- this will report an error.\n\n2. I am using a white background for the cycle gadgets and I cannot read some\n   of the options.\n\n   The default options are shown in black and the non default are shown in\n   white by TrapPrefs per default.  This can be changed by setting the\n   tooltype @{"COLOR" link "CLI" 0}.  With this tooltype you can change the color, or even make\n   the items bold or italic.\n\n3. When I save my configuration, the labels I had set up for TIF are lost.\n\n   The ability to load, edit, and save the TIF labels are only available in\n   the registered version.  You will need to register in order to use these\n   features.\n@endnode\n\n@node "Registered" "Registered Users"\nI would like to thank the following people for supporting TrapPrefs with their\nshareware donations.\n\n 1) Steffen Salzmann\n 2) Magnus Holmgren\n 3) Scott D. Nolan\n 4) Dave Naylor\n 5) Eric Zufferey\n\nPlease see @{"Shareware" link "Shareware" 0} for information about registering.\n@endnode\n\n@node HeddleyAutoIndex "Index"\n@remark Index auto-generated by Heddley\nIndex of database TrapPrefs.guide\n\nDocuments\n\n@{"Address" link "Address"}\n@{"Copyright & Disclaimer" link "Copyright_&_Disclaimer"}\n@{"Features" link "Features"}\n@{"Gadgets" link "Gadgets"}\n@{"General Settings" link "General"}\n@{"History" link "History"}\n@{"Locale" link "Locale"}\n@{"Modem Settings" link "Modem"}\n@{"MUI" link "MUI"}\n@{"Questions" link "Questions"}\n@{"Registered Users" link "Registered"}\n@{"Requirements" link "Requirements"}\n@{"Screen Settings" link "Screen"}\n@{"Session settings" link "Session"}\n@{"Shareware" link "Shareware"}\n@{"System Settings" link "System"}\n@{"Thanks" link "Thanks"}\n@{"ToDo" link "ToDo"}\n@{"Tooltypes and CLI options" link "CLI"}\n@{"TrapPrefs v1.4 documentation" link "Main"}\n@{"Usage" link "Usage"}\n\nButtons\n\n@{" 7Wire               " link "TrapDoor.guide/4.3.1" 0}\n@{" ABS              " link "TrapDoor.guide/4.3.3" 0}\n@{" Account Limits   " link "TrapDoor.guide/4.3.5" 0}\n@{" Accounting       " link "TrapDoor.guide/4.3.4" 0}\n@{" Adjust              " link "TrapDoor.guide/4.3.6" 0}\n@{" After Session    " link "TrapDoor.guide/4.3.7" 0}\n@{" AKA''s       " link "TrapDoor.guide/4.3.8" 0}\n@{" Allow Refusing   " link "TrapDoor.guide/4.3.9" 0}\n@{" Answer              " link "TrapDoor.guide/4.3.10" 0}\n@{" ARexx Port       " link "TrapDoor.guide/4.3.83" 0}\n@{" ARQ String       " link "TrapDoor.guide/4.3.11" 0}\n@{" Author''s Address       " link "Address" 0}\n@{" Auto Adjust        " link "TrapDoor.guide/4.3.12" 0}\n@{" Auto OverScan      " link "TrapDoor.guide/4.3.13" 0}\n@{" Background         " link "TrapDoor.guide/4.3.14" 0}\n@{" Banner           " link "TrapDoor.guide/4.3.15" 0}\n@{" Baud                " link "TrapDoor.guide/4.3.16" 0}\n@{" BBS Char         " link "TrapDoor.guide/4.3.17" 0}\n@{" BBS Command      " link "TrapDoor.guide/4.3.18" 0}\n@{" BBS Message      " link "TrapDoor.guide/4.3.20" 0}\n@{" BBS Mode         " link "TrapDoor.guide/4.3.21" 0}\n@{" BBS Name    " link "TrapDoor.guide/4.3.71" 0}\n@{" BBSInOut         " link "TrapDoor.guide/4.3.19" 0}\n@{" Beep Display       " link "TrapDoor.guide/4.3.22" 0}\n@{" BOSS        " link "TrapDoor.guide/4.3.23" 0}\n@{" Call                " link "TrapDoor.guide/4.3.24" 0}\n@{" CLI and ToolTypes      " link "CLI" 0}\n@{" Copyright & Disclaimer " link "Copyright_&_Disclaimer" 0}\n@{" Cost             " link "TrapDoor.guide/4.3.29" 0}\n@{" Dial TimeOut        " link "TrapDoor.guide/4.3.32" 0}\n@{" Dialer              " link "TrapDoor.guide/4.3.31" 0}\n@{" DietIFNA         " link "TrapDoor.guide/4.3.33" 0}\n@{" DirectZap        " link "TrapDoor.guide/4.3.34" 0}\n@{" DisplayID          " link "TrapDoor.guide/4.3.35" 0}\n@{" Drop BBS Seconds " link "TrapDoor.guide/4.3.36" 0}\n@{" DSR                 " link "TrapDoor.guide/4.3.37" 0}\n@{" Emsi             " link "TrapDoor.guide/4.3.38" 0}\n@{" Esc Resets Modem " link "TrapDoor.guide/4.3.39" 0}\n@{" FastEmsi         " link "TrapDoor.guide/4.3.40" 0}\n@{" Fax Command      " link "TrapDoor.guide/4.3.41" 0}\n@{" Fax String       " link "TrapDoor.guide/4.3.42" 0}\n@{" Features               " link "Features" 0}\n@{" File Request     " link "TrapDoor.guide/4.3.46" 0}\n@{" FloatLock           " link "TrapDoor.guide/4.3.44" 0}\n@{" Forbid All       " link "TrapDoor.guide/4.3.45" 0}\n@{" Forbid Freq