" link "Questions" 0}\n@{" Quiet              " link "TrapDoor.guide/4.3.79" 0}\n@{" Redial Delay        " link "TrapDoor.guide/4.3.80" 0}\n@{" Requirements           " link "Requirements" 0}\n@{" Retries             " link "TrapDoor.guide/4.3.82" 0}\n@{" Ring Command        " link "TrapDoor.guide/4.3.84" 0}\n@{" Ringings            " link "TrapDoor.guide/4.3.85" 0}\n@{" Rings               " link "TrapDoor.guide/4.3.86" 0}\n@{" Screen Mode        " link "TrapDoor.guide/4.3.89" 0}\n@{" Screen Settings  " link "Screen" 0}\n@{" Serial Flags        " link "TrapDoor.guide/4.3.93" 0}\n@{" Serial Name         " link "TrapDoor.guide/4.3.94" 0}\n@{" Serial Unit         " link "TrapDoor.guide/4.3.95" 0}\n@{" SerialBufSize       " link "TrapDoor.guide/4.3.92" 0}\n@{" Shared              " link "TrapDoor.guide/4.3.96" 0}\n@{" Shareware              " link "Shareware" 0}\n@{" ShowRexx         " link "TrapDoor.guide/4.3.97" 0}\n@{" SlowModem           " link "TrapDoor.guide/4.3.99" 0}\n@{" SniffARQ         " link "TrapDoor.guide/4.3.101" 0}\n@{" Special Thanks         " link "Registered" 0}\n@{" Strip Dashes        " link "TrapDoor.guide/4.3.107" 0}\n@{" SwePulse            " link "TrapDoor.guide/4.3.106" 0}\n@{" Sysop Name  " link "TrapDoor.guide/4.3.111" 0}\n@{" System Settings  " link "System" 0}\n@{" System Settings  " link "Session" 0}\n@{" Thanks To              " link "Thanks" 0}\n@{" TimeStamp        " link "TrapDoor.guide/4.3.114" 0}\n@{" ToDo                   " link "ToDo" 0}\n@{" TrapZap          " link "TrapDoor.guide/4.3.115" 0}\n@{" Turn around      " link "TrapDoor.guide/4.3.116" 0}\n@{" Usage                  " link "Usage" 0}\n@{" Use System Font    " link "TrapDoor.guide/4.3.118" 0}\n@{" UseUserShell     " link "TrapDoor.guide/4.3.119" 0}\n@{" Voice Command    " link "TrapDoor.guide/4.3.120" 0}\n@{" Voice String     " link "TrapDoor.guide/4.3.121" 0}\n@{" WaZoo            " link "TrapDoor.guide/4.3.122" 0}\n@{" Window Sizes       " link "TrapDoor.guide/4.3.60" 0}\n@{" Wrap Lines         " link "TrapDoor.guide/4.3.123" 0}\n@{" XMail            " link "TrapDoor.guide/4.3.125" 0}\n@{" ZedZap           " link "TrapDoor.guide/4.3.126" 0}\n@{" ZedZip           " link "TrapDoor.guide/4.3.127" 0}\n@{" Zoom Full Size     " link "TrapDoor.guide/4.3.128" 0}\n@{"Address" link "Address" 0}\n@{"COLOR" link "CLI" 0}\n@{"Magic User Interface" link "MUI" 0}\n@{"SHAREWARE" link "shareware" 0}\n@endnode\n','\n',char(10)),NULL,'auto-added',72889,7,0,NULL,NULL,'tra14c','scan',1780048787);
INSERT INTO door_catalog VALUES('traco220','TRACO220.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRACO220.LHA',NULL,'XIM','sonnencreme.exe','2.20','Thrash',NULL,'Conference access lister for /X 2 and 3+',replace('Thrash Conf v2.20 by Thrash\nConference access lister for /X 2 and 3+\n','\n',char(10)),'TConf2.Guide',replace('@database "TConf_V2.14_DOCS"\n@REMARK History at the end.\n@REMARK .-------------------------------------------------------------------.\n@REMARK |   ThrashConfV2.20, HyperText docs written by Thrash of ANTHROX.   |\n@REMARK `-------------------------------------------------------------------''\n@REMARK You need Multiview, AmigaGuide, or some other .Guide viewer.\n@REMARK Don''t be a fucking loser and view this with a standard ASCII viewer!!\n@REMARK $VER: Guide for TConf v2.20 (23rd Aug 1994)\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@INDEX DIRECTORY\n@NODE MAIN "TConf: Contents."\n                    ___  _   _ _____ _   _ ____   _____  __     \n             __/\__/ _ \I \ I I_   _I I I I  _ \ / _ \ \/ /_/\__\n             \    / I_I I  \I I I I I I_I I I_) I I I \  /\    /\n             /_  _\  _  I I\  I I I I  _  I  _ <I I_I /  \/_  _\\n               \/ I_I I_I_I \_I I_I I_I I_I_I \_\\___/_/\_\ \/\n                              -*- PRESENTS -*-\n    .-------------------------------------------------------------------.\n    |          TCONF V2.20 RELEASE 2   (Conference Access Lister)       |\n    |         Written By THRASH Of ANTHR0X, ©1994/05 Gods''Gift.         |\n    |    (For ALL Versions And Variants Of Ami-Express BBS Software)    |\n    `-------------------------------------------------------------------''\n                              @{" What Is TConf? " Link WhatIs}\n                            @{" Noteable Features " Link Features}\n                      @{" Installation/Icon Requirements " LINK Installing}\n                           @{" Icon ToolTypes Used " LINK ToolTypes}\n                     @{" Running The Door From Ami-Express " LINK Running}\n                               @{" Main Index " LINK Directory}\n                            @{" Thanks And Greets " LINK Greets}\n                          @{" Other Gods''Gift Utils " LINK Others}\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE WhatIs "TConf: What IS it?"\n\n	TConf Is Quite Simply A Conference Access Lister Door. I Know Your\nThinking That The Two or Three Already In Exsistence Are Slow So How The\nHell Can This Be A Door? Well, TConf Can Update In REALTIME in Under A\nSecond Due To It Being Written Entirely In Assembler. Try It Once And You''ll\nThrow Away The Others For Good! Just Take A Look At Some Of The @{"Features"Link Features}.\nTConf Is Compatable With All Versions Of Ami-Express Including S-Express By \nSigma-Seven.\n\n        A Quick Note To Chart-Loosers. If Your Gonna Vote On Any Sad,\nFake,Fixed Charts, At Least Make Sure You Get It Right!. Dont Vote For\nEither Myself Or P0T-N00dle As Individuals. We BOTH Do all The Work -\nTake A Look At The @{"Releases" LINK Others} We Have Both Done For You\nAll So Far!. Please Vote For Us As:\n\n                          GODS''GIFT/ANTHROX\n\nPS: If Somebody Else Asks P0T-N00Dle About "HIS" Tbar/TTop Etc, Ill Blow\n    A Fuckin Fuse! HeHe.\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE Features "TConf: Features"\n\n     o - The GodsGift Seal Of Quality (Even More Rigorous Than Nintendo!)\n     o - 100% Assembly Language (As Always!).\n     o - 32 Node Compatable.(Actually 100!).\n     o - Compatable With ALL versions And Variants Of Ami-Express.\n     o - Can Be Run Resident.\n     o - RealTime Update Cause You Aint Never Seen One THIS Fast Before!\n     o - Using Nice And Easy Icon ToolTypes For ALL Command Options.\n     o - Can Display ANY Mixture Of conferences/Access "AREAS".\n     o - Optional HeaderFile Display.\n     o - Optional TailerFile Display.\n     o - Optional Statistics Bar.\n     o - Optional ClearScreen For Faster Ansi Displays & lazy Sysops.\n     o - Optional Password Protection (With Failure Comments To Callerslog).\n     o - Configurable Password Attempts.\n     o - One-Time-Passwords!!! (This one Is NICE for The Users!)\n     o - Fluffy Sheep Jumping On Pink Clouds All Over The Place.\n     o - I Was 100% Sober ThroughOut ALL coding.. (Well Almost!)\n     o - Not One Mention Of Fish-Fingers (SHIT!)\n     o - These Are Getting Silly.\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE Installing "TConf: Installation"\n\n\n\n\n\nWhich Version Of Expess Are You Running?\n\n\n         @{" Version 2.x +/Variant " Link InstallingV2}  ........ Non-Icon Versions\n         @{" Version 3.x +/Variant " Link InstallingV3}  ........ Icon/ToolType Versions\n\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE InstallingV3 "TConf: Installation Express V3.x+"\nMake An Icon In Your Commands/BBSCMD (Or Commands/ConfX) Directory With\nThe Following ToolTypes:\n\nLOCATION=Path And Name Of This Util (Ie DOORS:TCONF2)\nMULTINODE=YES\nTYPE=XIM\nSTACK=4096\n\nNow Make An Icon (One Is Supplied In This Archive) For TConf2 Itself. You\nCan Rename The Util To Whatever You Wish So You Can Run Multiple Versions\nFor Different Conferences/Areas. Just Remember To Make The Icons For EVERY\nCopy You Want To Use. All Options Are Controlled By The Doors Icon \n@{"ToolTypes"Link ToolTypes} For Ease Of Use For Users Of Ami-Express V3+.\nAn Example Icon Is Supplied WIthin This Archive.\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE InstallingV2 "TConf: Installation Express V2.x+ / Variant"\n\nCopy The Main Executable File To Your Doors Directory Or WhereEver You Want\nit. Make An Icon For The Util To Get Its Options From The @{"ToolTypes"Link ToolTypes}.\n\nYou Can Rename The Util To Whatever You Wish So You Can Run Multiple\nVersions For Different Conferences/Areas. Just Remember To Make An Icon And\nAn EXE For EVERY Different Copy You Want To Use. An Example Icon Is Supplied\nWIthin This Archive.\n\n\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n\n\n@NODE ToolTypes "TConf: Icon ToolTypes"\n\nThese Are All The ToolTypes Available To The Sysop:\n\n\n            @{" USER_DATA= " Link USER_DATA}  ........ Full Path/Name Of UserData.\n            @{" ACCESS_AREAS= " Link ACCESS_AREAS} ...... Area Names / Conference Numbers.\n            @{" HEADER_TEXT= " Link HEADER_TEXT} ....... Header Text To Be Displayed.\n            @{" TAILER_TEXT= " Link TAILER_TEXT} ....... Bottom Text To Be Displayed.\n            @{" CLEAR_SCREEN= " Link CLEAR_SCREEN} ...... Clear Sceen Before Any Output.\n            @{" STATS_BAR= " Link STATS_BAR} ......... Small Stats Bar Underneath Users.\n            @{" CONF_NAME= " Link CONF_NAME} ......... Name Of Conference To Be Displayed.\n            @{" PASSWORD= " Link PASSWORD} .......... Password Required To Continue.\n            @{" PASSWORD_TRIES= " Link PASSWORD_TRIES} .... Allowed Password Attempts.\n            @{" HACK_TEXT= " Link HACK_TEXT} ......... HangUp Text To Be Displayed.\n            @{" ONE_TIME_PASSWORD= " Link ONE_TIME_PASSWORD} . Special Type Of PassWord.\n            @{" EXPRESS_VERSION= " Link VERSION} ... Version/Variant Number Of Ami-Express.\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE USER_DATA "TConf: ToolTypes - USER_DATA"\n\nUSER_DATA=X\n\nThis ToolType MUST Exist. "X" Is Simply The FULL Path AND Name Of Your\nUserData File ie:\n\nUSER_DATA=BBS:USER.DATA\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE ACCESS_AREAS "TConf: ToolTypes - ACCESS_AREAS"\n\n\nWhich Version Of Expess Are You Running?\n\n\n         @{" Version 2.x +/Variant " Link ACCESS_AREAS_V2}  ........ Non-Icon Versions\n         @{" Version 3.x +/Variant " Link ACCESS_AREAS_V3}  ........ Icon/ToolType Versions\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE ACCESS_AREAS_V3 "TConf: ToolTypes - ACCESS_AREAS /X3+"\n\nACCESS_AREAS=AREANAME1;AREANAME2 Etc..\n\nThis Is The Name Of The Area Used In Your "Access" Drawer. Multiple Areas\nCan Be Used But Each Area MUST Be Seperated By a Semi-Colon ";". Ie..\n\nACCESS_AREAS=SYSOP;NEWUSERS        - Show Users Whose "AREA" Is SYSOP Or\n                                     NEWUSERS.\n\nOr\n\nACCESS_AREAS=SYSOP;SPECIAL_USERS;AMIGA;CONSOLE\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE ACCESS_AREAS_V2 "TConf: ToolTypes - ACCESS_AREAS /X2+"\n\nACCESS_AREAS=X;X;X Etc......\n\n\nWhere "X" Is The NUMBER Of the COnference You Want TConf To Display. You\nCan Use Multiple Conferences But Each Must Be Seperated By A Semi-Colon (;).\nIe:\n\nACCESS_AREAS=5          - Show Users With Access To Conf 5.\n\nOr\n\nACCESS_AREAS=5;9;1      - Show Users With Access To Confs 5;9 And 1.\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE HEADER_TEXT "TConf: ToolTypes - HEADER_TEXT"\n\nHEADER_TEXT=X\n\nWhere "X" Is The FULL Path AND Name Of A Header/Logo Text You Wish To Be \nDisplayed BEFORE Any User Information Is Shown.Ie\n\nHEADER_TEXT=BBS:SCREENS/AMIGA/ACCESS_LOGO1.TXT\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE TAILER_TEXT "TConf: ToolTypes - TAILER_TEXT"\n\nTAILER_TEXT=X\n\nWhere "X" Is The FULL Path AND Name Of A Tailer/Logo Text You Wish To Be \nDisplayed AFTER Any User Information Has Been Shown.Ie\n\nHEADER_TEXT=BBS:SCREENS/AMIGA/ACCESS_BOTTOM.TXT\n@ENDNODE\n@NODE CLEAR_SCREEN "TConf: ToolTypes - CLEAR_SCREEN"\n\nCLEAR_SCREEN=YES/NO\n\nIf You Wish The Screen To Be Cleared BEFORE Any Text Is Shown Then Make\nThis YES. It Just Saves Lazy Sysops From Including A Screen Clear On Logos.\nAnd Of Course Will Mean The Screen Update Will Be Slightly Faster Due To\nNo "Scroll-Up" By Ami-Express.\n\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE STATS_BAR "TConf: ToolTypes - STATS_BAR"\n\nSTATS_BAR=YES/NO\n\nIf You Wish The One Line Of Quick-Stats To Be Displayed At The Bottom Then\nSet This To YES. It Will Take The Util NO LONGER To Execute So You May As\nWell Leave It In, Unless You Simply Dont Like The Idea.\n@ENDNODE\n@NODE CONF_NAME "TConf: ToolTypes - CONF_NAME"\n\nCONF_NAME=YES/NO\n\nAfter The Logo/ClearScreen But BEFORE The Users Are Displayed To The Screen,\nYou Can Have The Conference Name From Which The Util Was Run Displayed At The\nTop Of The Ansi Output. Simply A Yes/No Option. NOTE: I said The Name Of\nThe Conference TConf Was Run FROM. *NOT* The Conference/s You Have Put Into\nThe @{" ACCESS_AREAS= " Link ACCESS_AREAS} ToolType.\n\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE PASSWORD "TConf: ToolTypes - PASSWORD"\n\nPASSWORD=XXXX....\n\nIf TConf Finds This ToolType Present With A Valid Password It Will Ask\nThe User To Input The Correct Password Before It Will Let Him Exit The\nUtil And Proceed Within The Conference. This Is Mainly Here For Those\nSysops Who Wish To Run This Door As Soon As A User Has Joined A Private\nConference. The Password Can be ANY combination Of Numbers/Letters Etc,\nUpto A Maximum Limit Of 59 Characters. The Check Made Is NOT Case Sensitive\nCause That Only Would Piss Legitimate Users Off! The User Will Be Given\n3 Attempts To Enter The Correct Password Followed By Return. If They\nFail All 3 Attempts TConf Will Legally Drop Carrier On The User And Notify\nThe Sysop By Leaving A Suitable Comment Attached To The Nodes CallersLog.\nAmi-Express Will Then Reset The Node And Await The Next Caller.\n\n\n\nSee Also: \n\n@{" PASSWORD_TRIES= " Link PASSWORD_TRIES},@{" ONE_TIME_PASSWORD= " Link ONE_TIME_PASSWORD},@{" HACK_TEXT= " Link HACK_TEXT}\n\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE PASSWORD_TRIES "TConf: ToolTypes - PASSWORD_TRIES"\n\nPASSWORD_TRIES=X\n\nWhere X Is A Number Between 1 And 9. This Tells TConf How Many Attempts\nAt Getting The Correct PassWord Are Allowed Before The User Is Kicked\nOff The Board. If This ToolType Is NOT Found Then TConf Will Default To\n3 Attempts If PassWords Are Required.\n\n\nSee Also: \n\n@{" ONE_TIME_PASSWORD= " Link ONE_TIME_PASSWORD},@{" HACK_TEXT= " Link HACK_TEXT},@{" PASSWORD= " Link PASSWORD}\n\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE HACK_TEXT "TConf: ToolTypes - HACK_TEXT"\n\nHACK_TEXT=X\n\nWhere X Is The FULL Name And Path Of A Text File The Sysop Wants To Be\nDisplayed Just Before A User/Hacker Is To Be Kicked Off The BBS. Ie\n\nHACK_TEXT=BBS:DOORS/TCONF/FUCK_OFF.TXT\n\n\n\nSee Also: \n\n@{" PASSWORD_TRIES= " Link PASSWORD_TRIES},@{" ONE_TIME_PASSWORD= " Link ONE_TIME_PASSWORD},@{" PASSWORD= " Link PASSWORD}\n\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE ONE_TIME_PASSWORD "TConf: ToolTypes - ONE_TIME_PASSWORD"\n\nONE_TIME_PASSWORD=YES/NO\n\nThis Is A Special PassWord Option. In Order For This To Run Correctly\nYou Will Need To Have An Assigned T: Directory. When A User Logs On\nAnd Correctly Gets The PassWord To A Particular Conference A SMALL File\nIn Your T: Dieectory Will Be Created By TConf. If He Rejoins This Same\nConf He Will NOT Need To Type In The PassWord Again. TConf Will Keep \nTrack Of ALL Conference PassWords Correctly Accessed By The User And \nNot Ask For Them A Second Time. This Even Tracks If The User Uses "RL" \nTo Re-Logon Or Simply Calls The Same Node Again Before Any Other Users.\n\n           Although A Good Idea (Thanks T.G.R!), This Way Of Doing\nThings Does Have A slight Problem. If A Hacking User Logs OnTo The Board\nStraight After The Legitimate User Has Called He Would Have Access\nTo The Protected Conference (DUMB!!). A Simple Way Of Stopping This \nProblem Is To Delete The File Created In The T: Directory In That \nParticular Nodes Logoff-Script. So Simply Add To Each Nodes Logoff-Script\nThe Following Line:\n\nDELETE T:TConfUser_NodeX     << "X" Is The Node Of The Logoff-Script!!\n\nThis Will Mean The User WOULD Be required To Insert The Correct PassWord\nIf He Re-Logs On Or Is The Next Person To Call The SAME Node, And Gets\nRid Of The Hacker Problem. I could Have Built This In But It Would Mean\nYou Would Have To Run A Second Util As Your "G" Or "RL" Commands And\nThis Was Thought To Be NOT A Good Idea. (Even If "G" Doors Do Suk In My\nBooks!)\n\n          Its A Little Hard To Explain How It Works So Try It Out And \nSee For YourSelf. A Nice Idea, But ,Of Course, Its Only Optional!\n\n   If This ToolType Does NOT Exist, Then TConf Will Default To NO.\n\nSee Also: \n\n@{" PASSWORD_TRIES= " Link PASSWORD_TRIES},@{" HACK_TEXT= " Link HACK_TEXT},@{" PASSWORD= " Link PASSWORD}\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE VERSION "TConf: ToolTypes - EXPRESS_VERSION"\n\nEXPRESS_VERSION=X\n\nWhere "X" Is the MAIN Version Number Of The Express/Express Variant You Are \nUsing. TConf Of Course CAN Find The Internal Version By Itself (Which It \nDoes By Default If This ToolType Does NOT Exist), However This Will Allow\nThe Variant Programmers Who Are Using The OLD! Version 2 Release To Upgrade\nTheir Version To Number To 3 Without This Util Screwing Up On Them. \nIe If your Version Of Express Uses Icon ToolTypes For Everything Then:\n\nEXPRESS_VERSION=3\n\nEXPRESS_VERSION=4\n\nIf,However You Are Using S-Express 3 (If There Ever Is One), But It DOESNT\nUse Icon ToolTypes Then You Should Have:\n\nEXPRESS_VERSION=2\n\n\nWas That Simple Enough For You???.. Now You Can Upgrade The Version Number\nProperly Stefan!\n\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE RUNNING "TConf: Running From Ami-Express."\n\nYou Have Two Choices For Running TConf. Any Sysop Should Know What They Are.\nSimply Have The User Type In Whatever You Have Setup For The Door TO Run. Ie\nIn This Archive They Would Type In "ACCESS" And Be Told What Users Have \nAccess To The Confs Desribed In The ToolTypes. Or You Can Set It Up To Run\nIn An MCI script. For Instance Your NewUsers/Bull100.Txt May Say...\n\n~\n~CC_ACCESS\n\nWhich In MCI-Script Language Tells Ami-Express To Run The Door Called\nACCESS Rather Than Display This As A text File. Simple Stuff Eh?\n\nAlso See Notes On @{"Installation "Link Installing}.\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE DIRECTORY "TConf: Main Index."\n\nHelpful Index Aint I???\n\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE Greets "TConf: Thanks And Greetings."\n                            ____.___.                               \n       _________._________I    I_  I____.________ _______ ____ ____ \n       \____    _   __   \    __/ _I    I_  _    \   _   \    I  _/ \n       /        I    I    \    I  \.    I  _/   _/   I    \_      \ \n       \___I    I    I____/    I___I    I___\    \________/   I____\\n           `----''----''    `----''   `----''    \____/      /____Ie  \n\nThanks To My Beta-Testers Who This Time Were: \n\n                    Ice D / Sysop BURGERBAR ATX-UKHQ.\n                 Picard / Sysop USS ENTERPRISE ATX-WHQ.\n\nGreetings To ALL The Following (And Many Forgotten) For Their FriendShip\nAnd Work (No Firkin Order!!) :-\n\n                   ALL MEMBERS Of ANTHROX WORLDWIDE\n\n             PRESTiGE, PARADOX, DELiRiUM, FAiRLiGHT, GOD\n\n\nIf You Feel The Need To Get Sommit Off Your Chest Or Wish To Bore Me\nShitless With Your "AMAZING" Ideas For A New Util Hehe. Then Call One Of\nThe WorldWide Anthrox Boards. If You Are Further Interested In GODSGiFT\nUtils Then A Special Conference Has Been Set Up On Our EHQ (BURGERBAR!),\nWhere You Can Chat To Myself And Pot-Noodle About Them.\n\n+-------------------------------------------------------------------------+\n| USS ENTERPRiSE ... +1-412-233-2611   USS ENTERPRiSE ... +1-RiNG-D0WN!!! |\n| USS ENTERPRiSE ... +1-RiNG-D0WN!!!   USS ENTERPRiSE ... +1-RiNG-D0WN!!! |\n| USS ENTERPRiSE ... +1-RiNG-D0WN!!!   USS ENTERPRiSE ... +1-RiNG-D0WN!!! |\n| BURGER BAR ....... +44-PRi-VATE!!!   BURGER BAR ....... +44-RiNG-D0WN!! |\n| CONSOLiA ......... +32-11-234-523!   CONSOLiA ......... +32-11-234-872! |\n| SYNERGY .......... +49-PRi-VATE!!!   SYNERGY .......... +49-PRi-VATE!!! |\n| SYNERGY .......... +49-***-ISDN!!!   SYNERGY .......... +49-***-ISDN!!! |\n| METROPOLIS ....... +34-XXXX-XXXX!!   METROPOLIS ....... +34-XXXX-XXXX!! |\n| TRADE LINE ....... +1-XXXX-XXXX!!!   TRADE LINE ....... +1-XXXX-XXXX!!! |\n| THE WALL ......... +44-PRI_VATE!!!       ***** SPACE F0R RENT!! *****   |\n+-------------------------------------------------------------------------+\n                         -* SPECiAL REGARDS TO -*-\n              PRESTiGE, PARADOX, REDNEX, DELiRiUM, FAiRLiGHT.\n\n\n\n\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n\n@NODE Others "TConf: Other Gods''Gift Releases"\nThere should be a directory that came with this archive containing lots of\nexample outputs from a selection of the utils featured below.\n\nContents: G''G Release History.\n=============================================================================\n:::::::::::::::::::::::::  GODS''GIFT/ATX RELEASES  ::::::::::::::::::::::::::\n=============================================================================\nDates are the release/completion dates of the latest update.\nLatest releases at the top!...\n=============================================================================\nATX-TC22.LHA | 16-Feb-95 | ThrashConf V2.20 (68000) Thrash of Anthrox\n-------------+-----------+---------------------------------------------------\n Release [2] | Purpose:  | Small bug fixed.\n             |           | \n=============================================================================\nATX-TC2.LHA  | 09-Sep-94 | ThrashConf V2.14 (68000) Thrash of Anthrox\n-------------+-----------+---------------------------------------------------\n Release [1] | Purpose:  | Conference Access Lister Door For ALL /X Versions\n-------------+-----------+---------------------------------------------------\n             | Extras:   | FAST code. Can be made RESIDENT.\n             |           | 32 Node/Multi-Node Compatable (Upto 100 nodes!!)\n             |           | Compatable With ALL Versions Of Ami-Express.\n             |           | Optional Header/Tailer TEXTS.\n             |           | Any Number Of Single/Mixed "Areas"/Conferences.\n             |           | REALTIME Updated Cause This One Is FAST!.\n             |           | Using Icon TOOLTYPES As Standard For The 1st Time.\n             |           | Optional User STATISTICS Bar At Bottom.\n             |           | Option To Display COnference Name.\n             |           | Optional SCREENCLEAR For Lazy Text Makers/Sysops.\n             |           | Optional PASSWORD Protection.\n             |           | PassWord HACK Attempts Logged To CallersLog.\n             |           | Optional Text Displayed On Drop Carrier.\n             |           | Configuarable Amount Of PassWord Attempts.\n             |           | One-Time-PassWords. User Has To Only Enter Pass-\n             |           | Word Once, Including Re-logons Etc! Till Node Is\n             |           | Used By Different User.\n=============================================================================\nATX-SDC1.LHA | 04-Apr-94 | Super-DupeCheck v1.0 (68000) P0T-NOoDLE of Anthrox\n-------------+-----------+---------------------------------------------------\n Release [1] | Purpose:  | Dupe-Checker & FileCheck Handler Door.\n-------------+-----------+---------------------------------------------------\n             | Extras:   | FAST code. Can be made resident.\n             |           | Can run infinite other filechecker-type doors.\n             |           | Can display infinite text files. (Global & Conf)\n             |           | Cool percentage-done progress bar!\n             |           | 32-Node compatable. (Actually, upto 100nodes)\n             |           | "Script"-style config file for versatility\n             |           | Skips archive-checking if file is duped.\n             |           | Allows for DupeChecking to be skipped for Named\n             |           | Allows for DupeChecking to be skipped for Access\n             |           | Allows for a special Dupe-Checker filelisting\n             |           |    that is checked by not viewable by users.\n             |           | Allows for DupeChecking only on selected DirFiles\n             |           | Allows for a special Global-Dupe-Dir listing that\n             |           |    is seached for uploads in ALL conferences.\n             |           | Actual DupeChecking does NOT have to be performed.\n             |           |    Can be used to display messages and run doors.\n             |           | Can check for Dupes where *.LHA = *.ZOO etc.\n             |           | Skips DupeCheck on private uploads.\n=============================================================================\nATX-TCOM.LHA | 01-Oct-93 | ThrashComment v1.00  (68000)     Thrash of Anthrox\n-------------+-----------+---------------------------------------------------\n             | Purpose:  | Sysop Comment Door.\n-------------+-----------+---------------------------------------------------\n             | Extras:   | Will use any number of sysops between 1 and 99.\n             |           | Header/Tailer texts. Special External file option\n             |           | to display your own ansi instead of the built-in\n             |           | defaults to make it look how YOU want it.\n=============================================================================\nATX-SAL5.LHA | 20-Aug-93 | Super-AmiLog v2.00   (68000) P0T-NOoDLE of Anthrox\n-------------+-----------+---------------------------------------------------\n Release [5] | Purpose:  | Create a list of the last callers.\n-------------+-----------+---------------------------------------------------\n             | Extras:   | Keeps records of best number of callers etc in\n             |           | one day. Outputs a list of weekly statistics with\n             |           | info on the last 7 days, and the weekly averages.\n             |           | MULTI-NODE compatable. 0 to 20 callers shown.\n             |           | Non-ANSI mode. Header/Tailer texts. Random 1 line\n             |           | messages. Can be made Resident. Docs built into\n             |           | the util. Mini-Callerslog made with compact info\n             |           | about each call. For each user, can show Baud,\n             |           | Node,Name,Location,Connect Time,Logoff Time,\n             |           | Time Spent Online, Up/Down KBytes,Actions.\n             |           | Actions include: Up/Download,Up/Download Failed,\n             |           | Password Hack,Lost Carrier,Paged Sysop,Sysop Cmds.\n             |           | Shows: Calls Today/Yesterday,Up/Down Files/Bytes\n             |           | today, and finally Hours used today.\n=============================================================================\nATX-NEWL.LHA | 12-Jun-93 | Super-NewLst v1.00   (68000) P0T-NOoDLE of Anthrox\n-------------+-----------+---------------------------------------------------\n             | Purpose:  | Make a list of all new users waiting for access.\n-------------+-----------+---------------------------------------------------\n             | Extras:   | Lists 3 users per line for compact output.\n             |           | Put it as a bulletin on your BBS and your users\n             |           | can let you know if any of the new guys are OK...\n=============================================================================\nATXTBAR1.LHA | 23-May-93 | ThrashBar    v1.01   (68000)     Thrash of Anthrox\n-------------+-----------+---------------------------------------------------\n             | Purpose:  | BarCharts of Top Up/Down Bytes, Up/Down Files,\n             |           | Callers, Message Writters. \n-------------+-----------+---------------------------------------------------\n             | Extras:   | Exclude users (by number or sec level).\n             |           | 0 to ALL users shown on Chart. User Ratings.\n             |           | Non-ANSI Mode. Header file. Random 1 Line Msgs.\n             |           | Shows overall BBS statistics: megs/files up/down,\n             |           | number of leeches/elites/normals. Built in Docs.\n             |           | Archive contains .GUIDE (hypertext) docs.\n=============================================================================\nATX-TT15.LHA | 23-May-93 | ThrashTop    v1.05   (68000)     Thrash of Anthrox\n-------------+-----------+---------------------------------------------------\n             | Purpose:  | Normal Chart of Top Up/Down Loaders.\n-------------+-----------+---------------------------------------------------\n             | Extras:   | Unlimited Header/Tailer texts.\n             |           | 0 to ALL users shown on Chart. User Ratings.\n             |           | Also shows users'' Location,Messages,Calls,Files up\n             |           | Shows overall BBS statistics: megs/files up/down,\n             |           | number of leeches/elites/normals. Built in Docs.\n=============================================================================\nATX-STAT.LHA | 23-May-93 | ThrashStat   v1.03   (68000)     Thrash of Anthrox\n-------------+-----------+---------------------------------------------------\n             | Purpose:  | Create a list of all users and their statistics.\n-------------+-----------+---------------------------------------------------\n             | Extras:   | Shows users'' Number,Name,Location,Up/Down Bytes,\n             |           | Up Files,Calls,Messages Written.\n             |           | Shows total number of Users,Uploads,Msgs, etc.\n=============================================================================\nATX-STC3.LHA | 18-Jan-93 | Super-TopCPS v1.06   (68000) P0T-NOoDLE of Anthrox\n-------------+-----------+---------------------------------------------------\n Release [3] | Purpose:  | Create a list of the best CPS rates.\n-------------+-----------+---------------------------------------------------\n             | Extras:   | Never "forgets" CPS rates because it stores then\n             |           | in it''s file! Shows 0 to 20 users. Head/Tail file.\n             |           | Shows: Username,Date of CPS rate,Filename used,\n             |           | wether it was an Up/Download,Baud Rate,CPS rate.\n=============================================================================\nATX-TCON.LHA | 02-Oct-92 | ThrashConf   v1.00   (68000)     Thrash of Anthrox\n-------------+-----------+---------------------------------------------------\n             | Purpose:  | Create a list of all users with access to a conf.\n-------------+-----------+---------------------------------------------------\n             | Extras:   | Shows 3 users per line for compact output.\n             |           | Great for those private conferences!\n=============================================================================\n:::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::::\n=============================================================================\n@ENDNODE\n\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n@REMARK -=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n','\n',char(10)),'{"LOCATION":"Path","TYPE":"XIM","STACK":"4096"}','auto-added',29063,6,0,NULL,NULL,'traco220','scan',1780048787);
INSERT INTO door_catalog VALUES('tracom10','TRACOM10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRACOM10.LHA','TComm','XIM','TComm','1.00','Thrash',NULL,'Sysop comment door',replace('ThrashComment v1.00 by Thrash\nSysop comment door\n','\n',char(10)),'Schnabeltasse.doc',replace('\n\n\n               /                                           \\n              ·/(_____ sPEEEEEEEED aND fRIENDS ONlY! _____)\·\n             /                                               \\n                          fILE pASSED tHE L.E.BBS             \n             \   _____                               _____   /\n              ·\(      sPEEEEEEEED aND fRIENDS ONlY!      )/·\n               \                                           /\n    \n\n','\n',char(10)),NULL,'auto-added',11304,6,0,NULL,NULL,'tracom10','scan',1780048787);
