INSERT INTO door_catalog VALUES('trb_rap','TRB-RAP.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRB-RAP.LHA','List','XIM','LE-win5-96.exe',NULL,'GreedySnitch/Trb','TRB','_j   l_ Presents |  ¬| \_   _/__.______ |   |___. |   |¯ ¬|   _ ¬\|   _  ¬|',replace('        .___. Turbulence.___.     \n       _j   l_ Presents |  ¬|     \n       \_   _/__.______ |   |___. \n        |   |¯ ¬|   _ ¬\|   _  ¬| \n        |   l   |   |___j   |   | \n        l_______j___j   l_______j \n        (:-=============[VLe]=-:) \n      RAPER V0.1·LhAChecker for /X\n Adds & Stripps as many adds as you want\n Nice Dezign... Fast... reliable........\n Coded by GreedySnitch/Trb - 1995  \n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rE