INSERT INTO door_catalog VALUES('trsi_ar1','TRSI-AR1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-AR1.LHA','ASKII-REQUEST','XIM','ASKII-REQUEST',NULL,'SieGeL/tRSi','TRSI','\    ____    )  /___/\_| & rED sECTOR ¡NC | .-\___\ | \___\__   /   |  /X ¡NNOVATION   | `---|___|___|______/____|---[ [RESENTS ]---''',replace(' _____________ ___Mo! __.<---[ tRISTAR ]---.\n \    ____    )  /___/\_| & rED sECTOR ¡NC |\n.-\___\ | \___\__   /   |  /X ¡NNOVATION   |\n`---|___|___|______/____|---[ [RESENTS ]---''\n.------------------------------------------.\n|    aSKII-rEQUEST V1.oo bY SieGeL/tRSi    |\n`------------------------------------------''\ngREAT rEQUEST-dOOR wITH fREELY cONFIGURABLE\n dEZIGN, pSEUDO-eALL mESSAGES, oUTPUT-bULL\n--------------------------------------------\n','\n',char(10)),'aSKII-rEQUEST.guide',replace('@database aSKII-rEQUEST V1.0 - English DataBase\n@author "SieGeL/tRSi"\n@(c) "Copyright © 1995 (tRSi/X-iNNOVATiON)"\n@$VER: aSKII-rEQUEST.guide 1.00 (06-04-95)\n\n@index Main\n\n@node Main "aSKII-rEQUEST - BBS uTIL wRITTEN bY SieGeL oF (tRSi/X-iNNOVATiON)"\n@{b}                                                                     ______\n .-----------[ TRSI (/X·INNOVATION) ]------------.       _  ________/     /\n | _________________________________       ______`-------\\//  __    \\    /---.\n | \\       _____________     /     /______(______)  _     /    \\     \\  /    |\n |  \\______\\    |    __/   _/\\______       /     | (/)   /     /\\     \\/ Mo! |\n | \\     |      |    \\      \\       |     /      |  ¯   /     / /\\     \\_    |\n | \\\\    l______|_____\\      \\___________/_______|    _/     /_/  \\_____/    |\n `---------------------\\______/-----------------------\\_____/-\\_____/--------''@{ub}\n\n                           iS pROUD tO pRESENT:\n\n@{APEN 2}                   aSKII-rEQUEST V1.0 written by SieGeL@{APEN 1}\n\n                      @{" COPYRIGHT! " LINK COPYRIGHT}     @{"DISTRIBUTION" LINK DISTRIBUTION}\n                      @{"INTRODUCTION" LINK INTRODUCTION}     @{"INSTALLATION" LINK INSTALLATION}\n                      @{" HOW TO USE " LINK HOW2USE}     @{" -CREDITZ!- " LINK GREETINGS}\n\n        aNOTHER tOOL cOMMIN'' fROM tHE "rEAL" (tRSi/X-iNNOVATiON) tEAM\n@endnode\n\n@NODE COPYRIGHT "Copyright-Information of this Production"\n\n     @{u}Copyright@{uu}\n\n   This Program is `FreeWare''.\n\n   It can be freely copied and distributed for non-commercial purposes,\n  provided that no file is added to or removed from the distribution\n  archive and no charge, beside a nominal fee, is requested.\n\n  The whole Copyright is reserved by the Author (myself!), and without\n  written Permission it''s not allowed to distribute this Program in any\n  comercial way.\n\n  This Version is the only one which will be released, all following\n  updates and bugfixings are only available for registered Users. To\n  become registered User, you have to pay a registration Fee (30,- DM / $20).\n\n  You don''t have to pay for every new BBS-Tool I wrote, this Fee has to\n  be paid only one time. To become registered User, call my @{"BBS" LINK ADDY1} and leave\n  a mail to SieGeL/tRSi about a Registration.\n\n  @{"Click here for a list of all available programs written by SieGeL" LINK PRGLIST}\n\n@ENDNODE\n\n@NODE DISTRIBUTION "Distribution of this Production"\n\n     @{u}Distribution@{uu}\n\n  It is allowed to put this archive on any PD-Magazine/-Pool (i.e. AMINET),\n  as long as no charge, beside a nominal fee, is requested and no file is\n  added to or removed from the distribution archive.\n@ENDNODE\n\n@NODE INTRODUCTION "Introduction...."\n\n@{u}Introduction@{uu}\n\nThis door is written during the fact that aRTcORE! decided to make my BBS\nto their German Headquarter. To let Users request something, they gave me\nAsciiOrder written by Duplo...well I don''t like this door, coz'' it''s a\nlittle bit to simple....and therefor I decided to write my own aSKII-request\ndoor....it has some nice features, like:\n\n - is able to simulate EALL messages to all painters\n\n - Additional Comment (3 Lines) possible, to give further infos ''bout the\n   request...\n\n - Hole design is freely configurable during external ANSI-Pictures\n\n - Every Painter gets his own Datafile, reg. Users got l8er an Auto-Answer\n   Mode, allowing aSKII-rEQUEST to automatically delete uploaded requests.\n\n - Creates a nice Bulletin about all Requests.\n\n...etc. etc. etc...:) If you need such a program, look in the @{"Installation" LINK INSTALLATION}\nchapter on how to install it...\n@ENDNODE\n\n@NODE INSTALLATION "How to install it to your BBS-System"\n\n@{u}Installation@{uu}\n\nThis door runs under Fame and Amiex BBS-Systems, but was mainly written for\nusage on Amiex, therefor special functions available under FAME aren''t\nsupported!\n\nThe easiest way for installing is the Usage of the Installer-Script found\nin this archive. This will install aSKII-rEQUEST and all needed files to\nyour system. If you want to install it by hand read now :\n\n@{b}Installation to Amiex@{ub}\n\n1. Copy aSKII-rEQUEST + aSKII-rEQUEST.info to your Doors: directory, I\n   recommend to create an own drawer for this Program, as it creates Data-\n   Files in the Program-Directory!\n\n2. Copy the supplied ''ASCII.INFO'' to your BBS:COMMANDS/BBSCMD/ drawer and\n   adjust the path to the drawer you have put in aSKII-rEQUEST.\n\n3. Now edit the ToolTypes. For more Informations take a look to chapter\n   @{"ToolTypes" LINK TOOLTYPES}.\n\n4. That''s it..:)\n\n\n@{b}Installation to FAME@{ub}\n\n1. Copy aSKII-rEQUEST + aSKII-rEQUEST.info to your FAME:Doors directory, I\n   recommend to create an own drawer for this Program, as it creates Data-\n   Files in the Program-Directory!\n\n2. Start the SystemEditor, go into the Doors-Menu and load in the supplied\n   ANSI Command (aSKII-rEQUEST/FAME/SETTINGS/DOORS/BBSMCMD/ANSI). Adjust\n   the Path to the Drawer where aSKII-reQUEST could be found.\n\n3. Now edit the ToolTypes. For more Informations take a look to chapter\n   @{"ToolTypes" LINK TOOLTYPES}.\n\n4. That''s it..:)\n@ENDNODE\n\n@NODE TOOLTYPES "Tooltype-Informations for aSKII-rEQUEST"\n\n@{u}ToolTypes@{uu}\n\naSKII-rEQUEST needs some Tooltypes to work correctly. Here''s a list :\n\nSLOT.(x)=<SLOTNR.>    -> Here you define the painters available on your BBS.\n                         You have to define here the Slot-Numbers to allow\n                         aSKII-rEQUEST to write to the correct persons.\n                         You need at least ONE painter to let the prg working.\n                         Of course you could have as many painters as you like.\n\n                         @{b}Example:@{ub}\n\n                                 SLOT.1=17\n                                 SLOT.2=82\n                                 SLOT.3=444\n\n\nSHOW_AS.(x)=<STRING>  -> Here you could define alternate Names for the\n                         painters. If you don''t define this Tooltype, the\n                         current Username is used. If you defined it, the\n                         Name you entered here will be displayed when showing\n                         the artists instead of the Painter''s real Username.\n\n                         @{b}Example:@{ub}\n\n                               SHOWN_AS.1=2fAST/aRTCORE\n                               SHOWN_AS.2=sTYLeZ/^nEON^aRTCORE\n                               SHOWN_AS.3=(-rAPiD-)/sCOOPeX^aRTCORE\n\n\nOUTPUT_BULL=<PATH>    -> Here you could enter an alternate Path for creating\n                         the Output-Bulletin containing the requests. If this\n                         Tooltype isn''t present, aSKII-rEQUEST uses his own\n                         Path-Location as path, and creates in it a Bull called\n                         ORDER.TXT. If you wish to create it in another path,\n                         you *MUST* enter here a complete path including the\n                         filename, otherwise aSKII-rEQUEST won''t create the\n                         BULL!\n\n                         @{b}Example:@{ub}\n\n                         You don''t defined this Tooltype. aSKII-rEQUEST is\n                         located in DOORS:ASKII-REQUEST/, then the Bull will\n                         be created in ''DOORS:ASKII-REQUEST/ORDER.TXT'' .\n\nCurrently no more Tooltypes available, but for registered Users will be a\nmajor update in the next month...so get registered!\n@ENDNODE\n\n@NODE HOW2USE "How to use this Program"\n\n@{u}How it works@{uu}\n\nTo allow Sysops to design this Door to their own needings, I have decided to\nread in all screens from HD...so if you want to change the Style of this \nDoor, simply edit the following files found in the drawer of aSKII-rEQUEST:\n\n        ASKII-MAIN.TXT     --> ANSI for MainMenu\n        ASKII-ENTER.TXT    --> ANSI for Menu ENTER REQUESTS\n        ASKII-LIST.TXT     --> ANSI for Menu SHOW ARTISTS\n        ASKII-DELETE.TXT   --> ANSI for Menu DELETE REQUESTS\n\nIncluded in this archive are the Ansis painted by sTYLeZ of da famous \naRT-cORE! posse...i think everyone will love them..:) You could of course\nalternately use this door without any ANSI-Pictures, but who wants this..:)\n\n@{u}Main-Usage of aSKII-rEQUEST@{uu}\n\nWhen starting aSKII-rEQUEST, you have the following choices :\n\n                    @{" 1 " LINK HELP_1} ->  rEQUEST aN aSCII\n                    @{" 2 " LINK HELP_2} ->  deLETE rEQUESTS\n                    @{" 3 " LINK HELP_3} ->  vIEW rEQUESTS\n                    @{" 4 " LINK HELP_4} ->  sHOW aRTISTS\n                    @{" 5 " LINK HELP_5} ->  qUIT pROGRAM\n\nClick on number (1-5) you want more informations about...\n\nThe Output-Bulletin will be created each time the user exits the program.\nSo if you want to see the Bull, simply start and exit immediatly the door ;)\n@ENDNODE\n\n@NODE HELP_1 "Help on ''REQUEST AN ASCII''"\n\n@{u}REQUEST AN ASCII@{uu}\n\nHere you request ansis..:) when selected, you were first prompted if you want\nto write a Pseudo-EALL Message to all available painters. If you answer here\nNo, you could choose the Painter you wish to request something. By pressing\nonly Enter, you got back to the main menu. \nAfter choosing the Painter, you were now asked about the Type of logo you \nwant to request. So you could enter here i.e. DMS-Banner, BBSTitle, etc... \nso the painter sees which type he should paint for you...:) Again only \npressing Enter brings yar back to the main prompt...\nNow you were asked for the Name on the Banner, here you should enter now the\nName you want to have painted...i.e. SieGeL etc..\nAt least, you could enter an additional comment to the painter(s) containing \nmax. 3 lines with 78 chars each line. Only pressing enter exits the comment-\neditor. Of course you could use this Comment-Editor as a real Line-Editor \nwith CRSR-Left/Right support, DEL/BACKSPACe etc...\n\nAfter all parameters are entered, aSKII-rEQUEST displays the complete\nmessage to you and asks you if you really want to save this Message. Select\nNo to abort saving...if you have selected to write to ALL Painters, aSKII-\nrEQUEST will now write a couple number of messages, depending on how many\npainters are available. After successful saving, you will kicked back to\nmain menu.\n@ENDNODE\n\n@NODE HELP_2 "Help on ''DELETE REQUESTS''"\n\n@{u}DELETE REQUESTS@{uu}\n\nThis Menu-Entry is only accessable for the Sysop and the Painters defined\nin the aSKII-rEQUEST.info. Here you could delete old requests. For registered\nUsers a new tool will be written, which deletes requests automatically. In\nthis FreeVersion all painters have to delete their Requests for themself.\n@ENDNODE\n\n@NODE HELP_3 "Help on ''VIEW REQUESTS''"\n\n@{u}VIEW REQUESTS@{uu}\n\nWith this point you could take a look to all available requests. When \nselecting this point, you where asked if you want to view the Requests from\nALL painters or from a single Painter. Depending on your choice you see the\nrequests.\n@ENDNODE\n\n@NODE HELP_4 "Help on ''SHOW ARTISTS''"\n\n@{u}SHOW ARTISTS@{uu}\n\nThis point allows you to see which painters are available on this BBS. I \nthink nothing more has to say about this point I think.......\n@ENDNODE\n\n@NODE HELP_5 "Help on ''QUIT PROGRAM''"\n\n@{u}QUIT PROGRAM@{uu}\n\nThis exits aSKII-rEQUEST.\n@ENDNODE\n\n@NODE GREETINGS "Da famous Greetings...what else :)"\n\nGreetings fly to :\n\naRGON/PDY       - for having now 336oo BPS Connects :(\nsTYLEZ/aC!      - for painting me the Pictures for this Door\n(-rAPiD-)/aC!   - for giving me the Idea to do this Door\n2fAST/aC!       - fOR painting me such nice cewl pictures\nmOGUE!/aC!      - I''m sorry that you leave the scene...suxx man!\nByteAndi/tRSi   - fOR his GREAT Edit-Routine...\nsPY/tRSi        - hope you run FAME sometime.:)\nsTRIDER/sDC     - tHE bEST BBS iS FAME, nothing else.......\nfLASHBACK!/SCX  - fOR the nice chat last time :) Hope to hear from U..\nbYSiS/iNDY      - Yeah, cODIN'' iS thE BEST, you will get them all...:)\nBloodRock/sDC   - full-chat roolez oldae ;)\ndEATH aNGEL/sDC - for beeing such a nice Beta-Tester & Friend\nBeatnik/sDC     - v34 roolez oda ?\n\nand all others I''ve forgot to list here...take it easy & don''t worry :-)\n@ENDNODE\n\n@NODE PRGLIST "List of all Programs written by SieGeL/tRSi"\n\n@{u}Program-List@{uu}\n\nTo give you an overview what you got if you are registered user, here''s a\nlist of all my programs I have made until now...\n\n@{b}Currently available for reg. Users:@{ub}\n\nCD-Server V1.00     - CD-Server for @{"FAME" LINK FAME}/AMIEX\nwORLD-cLOCK V1.18   - Great Worldtime-Door for @{"FAME" LINK FAME}/AMIEX\nmEGA-vIEW V2.08+    - Best TXT-Viewer ever written for @{"FAME" LINK FAME}/AMIEX\nlASTCALLERS V0.051  - Lastcaller-Util for @{"FAME" LINK FAME}, faster than SAMILOG!\nsOFT-dEL V1.01      - Fast Online-Softdeleter for @{"FAME" LINK FAME} & AMIEX\nU-sTAT V1.31        - User-Statistics Door, freely configurable (@{"FAME" LINK FAME} & /X)\nASKII-REQUEST V1.00 - Very cewl askii-requester @{"FAME" LINK FAME}/AMIEX\n\n@{b}Still in work or needs to be updated:@{ub}\n\nPage-Master V0.05   - A CEWL Page-Door for @{"FAME" LINK FAME} with Gadtools-driven Window\noRDER V.02          - Door for Ordering sites, i.e. sell hardware via BBS..\nBBS-VIEW V1.1       - CLI-Util for displaying ANSI-Pics, 100% ASM!\nU-Convert V0.3      - CLI-Util to convert /X user.data -> @{"FAME" LINK FAME} user.data\nBullcreator V1.0    - Highscore-Util for ByteKiller V1.0, will be updated\n\nI think 30,- DM (btw. $20) is not too much for such a list, eh ? And of\ncourse,if possible, I try to realize all your wishes/needs for any problem\nyou have with this doors...To get in contact, take a look to Chapter @{"BBS" LINK ADDY1}.\n@endnode\n\n@node FAME "WHAT THE HELL IS FAME ?????"\n\n@{u}Some informations about FAME@{uu}\n\nWhat is FAME, you may ask. FAME is a new BBS-System written by Strider of\nSyndicate, which is about 90% compatible to Amiex-Doors, but has also an\nown Message-Port to use more than 1000 (!) commands. The whole BBS is\ncompletly hardware-depend, meaning that the only limit this system has is\nyour computer-equipment !\nThe configuration and the control of the BBS is realized with a System-Editor\n(fully Gadtoolsdriven, NO ICONS ANYMORE!), and a very comfortable Server\n(Commodity- & Gadtools-driven).\n\nDuring the fact that this BBS is currently in Beta-Stage, it''s not avail-\nable until now, but if you want more informations, contact us and we will\ngive you all informations needed.\n@endnode\n\n@node ADDY1 "(tRSi/X-iNNOVATiON) WHQ & Beta Site"\n\n@{APEN 2}                           hOW tO cONTACT uS : @{aPEN 1}\n\n   _____________  __________               /\\\n  |     __     /__\\__      /___________   /  \\             _____\n  |   ________/    /      /_\\____      \\_//   \\___________|_____|_______\n  |     |  \\      /      /      /      _//     \\    ______________      \\_\n  l_____|   \\___________/______/       \\_______/\\______   \\_    l/       /\n                              \\________/      /____________/____/       /\n                                       _________________       \\_______/\n     ______ /\\____ ____________ _______\\______   ______/\n    /      /_      \\    __    /_\\_____      \\_    |\n  _/      \\/______/   _______/\\      /       /    |    · PUN¡sHMeNT ¡NC. ·\n  \\________\\    _/_____________\\____/  Mo!  /_____|\n                /                  \\_______/\n                                           /\\  ______________  ___________\n     1oo% LeGaL sTUFF oN aM¡Ga^PC         /  \\_\\_______      \\_\\    _____/___\n                                         //   \\       /       /     /       /\n     RUNN¡NG oN a4ooo/4o · V.FasT      _//     \\_____/       /_____________/\n                                       \\________/   \\_______/\n\n TR¡sTaR & ReD seCToR ¡NC. (/X·¡NNoVaT¡oN) WHQ, aRTcORE! GHQ & eTH¡C D¡sT s¡Te\n\n   [> +49-(o)-3o-694-84-7o <]  sYsoP: s¡eGeL/TRs¡  [> +49-(o)-3o-694-sOON! <]\n\n                     @{"> pARALYSIS BBS - dISTRIBUTION sITE <" LINK ADDY2}\n@endnode\n\n@node ADDY2 "(tRSi/X-iNNOVATiON) bETA & dIST SITE"\n       ____\n    ___\\  /______________________________________________________________\n   /   \\\\//                                                              \\\n  /     \\/ -[ THe BeST eQUiPPeD PuBLIC DoMAIN BoaRD IN BeRLIN ]-          \\\n /   -[ WiTH 4 GReaT U.S.ROBOTICS V.FAST CLASS MoDeMS WiTH FLaSH-RoMS ]-   \\\n/                                                                           \\\n\\                        -- -[ SYNDIC/\\TE WHQ ]- --                         /\n \\   _____  _____    _____   _____  __      ___ __  _____   ___ _____      /\n  \\ /  _  \\/  _  \\  /  _  \\ /  _  \\/  |___ /   |  \\/   __)_/ __|   __)_   /\n   /   |   \\  _   \\/   |  //   _   \\  |   \\\\_____  \\___    \\¯  |___    \\ /\n  /   _____/  |    \\_ __   \\_  |    \\ |    \\   |    \\|      \\  | |      \\\n  \\____| \\____|    /___|    /__|    /___   / _______/___    /__|____    /\n      \\       l___/    l___/   l___/  \\___/___/  [ViC!]\\___/       \\___/\n       \\                                                             /\n        \\SYSTeM CHieFS: SPY/TRSi,ARTHuR DeNT,PHaNToM,Cat,JTC,big-rat/\n         \\                                                         /\n          \\   1: +49(0) 30 721 6071 USR DuAL STaNDaRD V.34 28.8   /\n           \\  2: +49(0) 30 721 6072 USR DuAL STaNDaRD V.34 28.8  /\n            \\ 3: +49(0) 30 721 6073 USR DuAL STaNDaRD V.34 28.8 /\n             \\4: +49(0) 30 722 6065 USR DuAL STaNDaRD V.34 28.8/\n              \\                                   /\\          /\n               \\_________________________________//\\\\________/\n                                                 /__\\\n\n                        SUPPORTS ONLY PD-/SHAREWARE !\n@endnode\n','\n',char(10)),NULL,'auto-added',31814,3,0,NULL,NULL,'trsi_ar1','scan',1780048787);
INSERT INTO door_catalog VALUES('trsi_azk','TRSI-AZK.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-AZK.LHA','ASKII-REQUEST','XIM','ASKII-REQUEST',NULL,'SieGeL/tRSi','TRSI','\    ____    )  /___/\_| & rED sECTOR ¡NC | .-\___\ | \___\__   /   |  /X ¡NNOVATION   | `---|___|___|______/____|---[ [RESENTS ]---''',replace(' _____________ ___Mo! __.<---[ tRISTAR ]---.\n \    ____    )  /___/\_| & rED sECTOR ¡NC |\n.-\___\ | \___\__   /   |  /X ¡NNOVATION   |\n`---|___|___|______/____|---[ [RESENTS ]---''\n.------------------------------------------.\n|    aSKII-rEQUEST V1.oo bY SieGeL/tRSi    |\n`------------------------------------------''\ngREAT rEQUEST-dOOR wITH fREELY cONFIGURABLE\n dEZIGN, pSEUDO-eALL mESSAGES, oUTPUT-bULL\n--------------------------------------------\n','\n',char(10)),'aSKII-rEQUEST.guide',replace('@database aSKII-rEQUEST V1.0 - English DataBase\n@author "SieGeL/tRSi"\n@(c) "Copyright © 1995 (tRSi/X-iNNOVATiON)"\n@$VER: aSKII-rEQUEST.guide 1.00 (06-04-95)\n\n@index Main\n\n@node Main "aSKII-rEQUEST - BBS uTIL wRITTEN bY SieGeL oF (tRSi/X-iNNOVATiON)"\n@{b}                                                                     ______\n .-----------[ TRSI (/X·INNOVATION) ]------------.       _  ________/     /\n | _________________________________       ______`-------\\//  __    \\    /---.\n | \\       _____________     /     /______(______)  _     /    \\     \\  /    |\n |  \\______\\    |    __/   _/\\______       /     | (/)   /     /\\     \\/ Mo! |\n | \\     |      |    \\      \\       |     /      |  ¯   /     / /\\     \\_    |\n | \\\\    l______|_____\\      \\___________/_______|    _/     /_/  \\_____/    |\n `---------------------\\______/-----------------------\\_____/-\\_____/--------''@{ub}\n\n                           iS pROUD tO pRESENT:\n\n@{APEN 2}                   aSKII-rEQUEST V1.0 written by SieGeL@{APEN 1}\n\n                      @{" COPYRIGHT! " LINK COPYRIGHT}     @{"DISTRIBUTION" LINK DISTRIBUTION}\n                      @{"INTRODUCTION" LINK INTRODUCTION}     @{"INSTALLATION" LINK INSTALLATION}\n                      @{" HOW TO USE " LINK HOW2USE}     @{" -CREDITZ!- " LINK GREETINGS}\n\n        aNOTHER tOOL cOMMIN'' fROM tHE "rEAL" (tRSi/X-iNNOVATiON) tEAM\n@endnode\n\n@NODE COPYRIGHT "Copyright-Information of this Production"\n\n     @{u}Copyright@{uu}\n\n   This Program is `FreeWare''.\n\n   It can be freely copied and distributed for non-commercial purposes,\n  provided that no file is added to or removed from the distribution\n  archive and no charge, beside a nominal fee, is requested.\n\n  The whole Copyright is reserved by the Author (myself!), and without\n  written Permission it''s not allowed to distribute this Program in any\n  comercial way.\n\n  This Version is the only one which will be released, all following\n  updates and bugfixings are only available for registered Users. To\n  become registered User, you have to pay a registration Fee (30,- DM / $20).\n\n  You don''t have to pay for every new BBS-Tool I wrote, this Fee has to\n  be paid only one time. To become registered User, call my @{"BBS" LINK ADDY1} and leave\n  a mail to SieGeL/tRSi about a Registration.\n\n  @{"Click here for a list of all available programs written by SieGeL" LINK PRGLIST}\n\n@ENDNODE\n\n@NODE DISTRIBUTION "Distribution of this Production"\n\n     @{u}Distribution@{uu}\n\n  It is allowed to put this archive on any PD-Magazine/-Pool (i.e. AMINET),\n  as long as no charge, beside a nominal fee, is requested and no file is\n  added to or removed from the distribution archive.\n@ENDNODE\n\n@NODE INTRODUCTION "Introduction...."\n\n@{u}Introduction@{uu}\n\nThis door is written during the fact that aRTcORE! decided to make my BBS\nto their German Headquarter. To let Users request something, they gave me\nAsciiOrder written by Duplo...well I don''t like this door, coz'' it''s a\nlittle bit to simple....and therefor I decided to write my own aSKII-request\ndoor....it has some nice features, like:\n\n - is able to simulate EALL messages to all painters\n\n - Additional Comment (3 Lines) possible, to give further infos ''bout the\n   request...\n\n - Hole design is freely configurable during external ANSI-Pictures\n\n - Every Painter gets his own Datafile, reg. Users got l8er an Auto-Answer\n   Mode, allowing aSKII-rEQUEST to automatically delete uploaded requests.\n\n - Creates a nice Bulletin about all Requests.\n\n...etc. etc. etc...:) If you need such a program, look in the @{"Installation" LINK INSTALLATION}\nchapter on how to install it...\n@ENDNODE\n\n@NODE INSTALLATION "How to install it to your BBS-System"\n\n@{u}Installation@{uu}\n\nThis door runs under Fame and Amiex BBS-Systems, but was mainly written for\nusage on Amiex, therefor special functions available under FAME aren''t\nsupported!\n\nThe easiest way for installing is the Usage of the Installer-Script found\nin this archive. This will install aSKII-rEQUEST and all needed files to\nyour system. If you want to install it by hand read now :\n\n@{b}Installation to Amiex@{ub}\n\n1. Copy aSKII-rEQUEST + aSKII-rEQUEST.info to your Doors: directory, I\n   recommend to create an own drawer for this Program, as it creates Data-\n   Files in the Program-Directory!\n\n2. Copy the supplied ''ASCII.INFO'' to your BBS:COMMANDS/BBSCMD/ drawer and\n   adjust the path to the drawer you have put in aSKII-rEQUEST.\n\n3. Now edit the ToolTypes. For more Informations take a look to chapter\n   @{"ToolTypes" LINK TOOLTYPES}.\n\n4. That''s it..:)\n\n\n@{b}Installation to FAME@{ub}\n\n1. Copy aSKII-rEQUEST + aSKII-rEQUEST.info to your FAME:Doors directory, I\n   recommend to create an own drawer for this Program, as it creates Data-\n   Files in the Program-Directory!\n\n2. Start the SystemEditor, go into the Doors-Menu and load in the supplied\n   ANSI Command (aSKII-rEQUEST/FAME/SETTINGS/DOORS/BBSMCMD/ANSI). Adjust\n   the Path to the Drawer where aSKII-reQUEST could be found.\n\n3. Now edit the ToolTypes. For more Informations take a look to chapter\n   @{"ToolTypes" LINK TOOLTYPES}.\n\n4. That''s it..:)\n@ENDNODE\n\n@NODE TOOLTYPES "Tooltype-Informations for aSKII-rEQUEST"\n\n@{u}ToolTypes@{uu}\n\naSKII-rEQUEST needs some Tooltypes to work correctly. Here''s a list :\n\nSLOT.(x)=<SLOTNR.>    -> Here you define the painters available on your BBS.\n                         You have to define here the Slot-Numbers to allow\n                         aSKII-rEQUEST to write to the correct persons.\n                         You need at least ONE painter to let the prg working.\n                         Of course you could have as many painters as you like.\n\n                         @{b}Example:@{ub}\n\n                                 SLOT.1=17\n                                 SLOT.2=82\n                                 SLOT.3=444\n\n\nSHOW_AS.(x)=<STRING>  -> Here you could define alternate Names for the\n                         painters. If you don''t define this Tooltype, the\n                         current Username is used. If you defined it, the\n                         Name you entered here will be displayed when showing\n                         the artists instead of the Painter''s real Username.\n\n                         @{b}Example:@{ub}\n\n                               SHOWN_AS.1=2fAST/aRTCORE\n                               SHOWN_AS.2=sTYLeZ/^nEON^aRTCORE\n                               SHOWN_AS.3=(-rAPiD-)/sCOOPeX^aRTCORE\n\n\nOUTPUT_BULL=<PATH>    -> Here you could enter an alternate Path for creating\n                         the Output-Bulletin containing the requests. If this\n                         Tooltype isn''t present, aSKII-rEQUEST uses his own\n                         Path-Location as path, and creates in it a Bull called\n                         ORDER.TXT. If you wish to create it in another path,\n                         you *MUST* enter here a complete path including the\n                         filename, otherwise aSKII-rEQUEST won''t create the\n                         BULL!\n\n                         @{b}Example:@{ub}\n\n                         You don''t defined this Tooltype. aSKII-rEQUEST is\n                         located in DOORS:ASKII-REQUEST/, then the Bull will\n                         be created in ''DOORS:ASKII-REQUEST/ORDER.TXT'' .\n\nCurrently no more Tooltypes available, but for registered Users will be a\nmajor update in the next month...so get registered!\n@ENDNODE\n\n@NODE HOW2USE "How to use this Program"\n\n@{u}How it works@{uu}\n\nTo allow Sysops to design this Door to their own needings, I have decided to\nread in all screens from HD...so if you want to change the Style of this \nDoor, simply edit the following files found in the drawer of aSKII-rEQUEST:\n\n        ASKII-MAIN.TXT     --> ANSI for MainMenu\n        ASKII-ENTER.TXT    --> ANSI for Menu ENTER REQUESTS\n        ASKII-LIST.TXT     --> ANSI for Menu SHOW ARTISTS\n        ASKII-DELETE.TXT   --> ANSI for Menu DELETE REQUESTS\n\nIncluded in this archive are the Ansis painted by sTYLeZ of da famous \naRT-cORE! posse...i think everyone will love them..:) You could of course\nalternately use this door without any ANSI-Pictures, but who wants this..:)\n\n@{u}Main-Usage of aSKII-rEQUEST@{uu}\n\nWhen starting aSKII-rEQUEST, you have the following choices :\n\n                    @{" 1 " LINK HELP_1} ->  rEQUEST aN aSCII\n                    @{" 2 " LINK HELP_2} ->  deLETE rEQUESTS\n                    @{" 3 " LINK HELP_3} ->  vIEW rEQUESTS\n                    @{" 4 " LINK HELP_4} ->  sHOW aRTISTS\n                    @{" 5 " LINK HELP_5} ->  qUIT pROGRAM\n\nClick on number (1-5) you want more informations about...\n\nThe Output-Bulletin will be created each time the user exits the program.\nSo if you want to see the Bull, simply start and exit immediatly the door ;)\n@ENDNODE\n\n@NODE HELP_1 "Help on ''REQUEST AN ASCII''"\n\n@{u}REQUEST AN ASCII@{uu}\n\nHere you request ansis..:) when selected, you were first prompted if you want\nto write a Pseudo-EALL Message to all available painters. If you answer here\nNo, you could choose the Painter you wish to request something. By pressing\nonly Enter, you got back to the main menu. \nAfter choosing the Painter, you were now asked about the Type of logo you \nwant to request. So you could enter here i.e. DMS-Banner, BBSTitle, etc... \nso the painter sees which type he should paint for you...:) Again only \npressing Enter brings yar back to the main prompt...\nNow you were asked for the Name on the Banner, here you should enter now the\nName you want to have painted...i.e. SieGeL etc..\nAt least, you could enter an additional comment to the painter(s) containing \nmax. 3 lines with 78 chars each line. Only pressing enter exits the comment-\neditor. Of course you could use this Comment-Editor as a real Line-Editor \nwith CRSR-Left/Right support, DEL/BACKSPACe etc...\n\nAfter all parameters are entered, aSKII-rEQUEST displays the complete\nmessage to you and asks you if you really want to save this Message. Select\nNo to abort saving...if you have selected to write to ALL Painters, aSKII-\nrEQUEST will now write a couple number of messages, depending on how many\npainters are available. After successful saving, you will kicked back to\nmain menu.\n@ENDNODE\n\n@NODE HELP_2 "Help on ''DELETE REQUESTS''"\n\n@{u}DELETE REQUESTS@{uu}\n\nThis Menu-Entry is only accessable for the Sysop and the Painters defined\nin the aSKII-rEQUEST.info. Here you could delete old requests. For registered\nUsers a new tool will be written, which deletes requests automatically. In\nthis FreeVersion all painters have to delete their Requests for themself.\n@ENDNODE\n\n@NODE HELP_3 "Help on ''VIEW REQUESTS''"\n\n@{u}VIEW REQUESTS@{uu}\n\nWith this point you could take a look to all available requests. When \nselecting this point, you where asked if you want to view the Requests from\nALL painters or from a single Painter. Depending on your choice you see the\nrequests.\n@ENDNODE\n\n@NODE HELP_4 "Help on ''SHOW ARTISTS''"\n\n@{u}SHOW ARTISTS@{uu}\n\nThis point allows you to see which painters are available on this BBS. I \nthink nothing more has to say about this point I think.......\n@ENDNODE\n\n@NODE HELP_5 "Help on ''QUIT PROGRAM''"\n\n@{u}QUIT PROGRAM@{uu}\n\nThis exits aSKII-rEQUEST.\n@ENDNODE\n\n@NODE GREETINGS "Da famous Greetings...what else :)"\n\nGreetings fly to :\n\naRGON/PDY       - for having now 336oo BPS Connects :(\nsTYLEZ/aC!      - for painting me the Pictures for this Door\n(-rAPiD-)/aC!   - for giving me the Idea to do this Door\n2fAST/aC!       - fOR painting me such nice cewl pictures\nmOGUE!/aC!      - I''m sorry that you leave the scene...suxx man!\nByteAndi/tRSi   - fOR his GREAT Edit-Routine...\nsPY/tRSi        - hope you run FAME sometime.:)\nsTRIDER/sDC     - tHE bEST BBS iS FAME, nothing else.......\nfLASHBACK!/SCX  - fOR the nice chat last time :) Hope to hear from U..\nbYSiS/iNDY      - Yeah, cODIN'' iS thE BEST, you will get them all...:)\nBloodRock/sDC   - full-chat roolez oldae ;)\ndEATH aNGEL/sDC - for beeing such a nice Beta-Tester & Friend\nBeatnik/sDC     - v34 roolez oda ?\n\nand all others I''ve forgot to list here...take it easy & don''t worry :-)\n@ENDNODE\n\n@NODE PRGLIST "List of all Programs written by SieGeL/tRSi"\n\n@{u}Program-List@{uu}\n\nTo give you an overview what you got if you are registered user, here''s a\nlist of all my programs I have made until now...\n\n@{b}Currently available for reg. Users:@{ub}\n\nCD-Server V1.00     - CD-Server for @{"FAME" LINK FAME}/AMIEX\nwORLD-cLOCK V1.18   - Great Worldtime-Door for @{"FAME" LINK FAME}/AMIEX\nmEGA-vIEW V2.08+    - Best TXT-Viewer ever written for @{"FAME" LINK FAME}/AMIEX\nlASTCALLERS V0.051  - Lastcaller-Util for @{"FAME" LINK FAME}, faster than SAMILOG!\nsOFT-dEL V1.01      - Fast Online-Softdeleter for @{"FAME" LINK FAME} & AMIEX\nU-sTAT V1.31        - User-Statistics Door, freely configurable (@{"FAME" LINK FAME} & /X)\nASKII-REQUEST V1.00 - Very cewl askii-requester @{"FAME" LINK FAME}/AMIEX\n\n@{b}Still in work or needs to be updated:@{ub}\n\nPage-Master V0.05   - A CEWL Page-Door for @{"FAME" LINK FAME} with Gadtools-driven Window\noRDER V.02          - Door for Ordering sites, i.e. sell hardware via BBS..\nBBS-VIEW V1.1       - CLI-Util for displaying ANSI-Pics, 100% ASM!\nU-Convert V0.3      - CLI-Util to convert /X user.data -> @{"FAME" LINK FAME} user.data\nBullcreator V1.0    - Highscore-Util for ByteKiller V1.0, will be updated\n\nI think 30,- DM (btw. $20) is not too much for such a list, eh ? And of\ncourse,if possible, I try to realize all your wishes/needs for any problem\nyou have with this doors...To get in contact, take a look to Chapter @{"BBS" LINK ADDY1}.\n@endnode\n\n@node FAME "WHAT THE HELL IS FAME ?????"\n\n@{u}Some informations about FAME@{uu}\n\nWhat is FAME, you may ask. FAME is a new BBS-System written by Strider of\nSyndicate, which is about 90% compatible to Amiex-Doors, but has also an\nown Message-Port to use more than 1000 (!) commands. The whole BBS is\ncompletly hardware-depend, meaning that the only limit this system has is\nyour computer-equipment !\nThe configuration and the control of the BBS is realized with a System-Editor\n(fully Gadtoolsdriven, NO ICONS ANYMORE!), and a very comfortable Server\n(Commodity- & Gadtools-driven).\n\nDuring the fact that this BBS is currently in Beta-Stage, it''s not avail-\nable until now, but if you want more informations, contact us and we will\ngive you all informations needed.\n@endnode\n\n@node ADDY1 "(tRSi/X-iNNOVATiON) WHQ & Beta Site"\n\n@{APEN 2}                           hOW tO cONTACT uS : @{aPEN 1}\n\n   _____________  __________               /\\\n  |     __     /__\\__      /___________   /  \\             _____\n  |   ________/    /      /_\\____      \\_//   \\___________|_____|_______\n  |     |  \\      /      /      /      _//     \\    ______________      \\_\n  l_____|   \\___________/______/       \\_______/\\______   \\_    l/       /\n                              \\________/      /____________/____/       /\n                                       _________________       \\_______/\n     ______ /\\____ ____________ _______\\______   ______/\n    /      /_      \\    __    /_\\_____      \\_    |\n  _/      \\/______/   _______/\\      /       /    |    · PUN¡sHMeNT ¡NC. ·\n  \\________\\    _/_____________\\____/  Mo!  /_____|\n                /                  \\_______/\n                                           /\\  ______________  ___________\n     1oo% LeGaL sTUFF oN aM¡Ga^PC         /  \\_\\_______      \\_\\    _____/___\n                                         //   \\       /       /     /       /\n     RUNN¡NG oN a4ooo/4o · V.FasT      _//     \\_____/       /_____________/\n                                       \\________/   \\_______/\n\n TR¡sTaR & ReD seCToR ¡NC. (/X·¡NNoVaT¡oN) WHQ, aRTcORE! GHQ & eTH¡C D¡sT s¡Te\n\n   [> +49-(o)-3o-694-84-7o <]  sYsoP: s¡eGeL/TRs¡  [> +49-(o)-3o-694-sOON! <]\n\n                     @{"> pARALYSIS BBS - dISTRIBUTION sITE <" LINK ADDY2}\n@endnode\n\n@node ADDY2 "(tRSi/X-iNNOVATiON) bETA & dIST SITE"\n       ____\n    ___\\  /______________________________________________________________\n   /   \\\\//                                                              \\\n  /     \\/ -[ THe BeST eQUiPPeD PuBLIC DoMAIN BoaRD IN BeRLIN ]-          \\\n /   -[ WiTH 4 GReaT U.S.ROBOTICS V.FAST CLASS MoDeMS WiTH FLaSH-RoMS ]-   \\\n/                                                                           \\\n\\                        -- -[ SYNDIC/\\TE WHQ ]- --                         /\n \\   _____  _____    _____   _____  __      ___ __  _____   ___ _____      /\n  \\ /  _  \\/  _  \\  /  _  \\ /  _  \\/  |___ /   |  \\/   __)_/ __|   __)_   /\n   /   |   \\  _   \\/   |  //   _   \\  |   \\\\_____  \\___    \\¯  |___    \\ /\n  /   _____/  |    \\_ __   \\_  |    \\ |    \\   |    \\|      \\  | |      \\\n  \\____| \\____|    /___|    /__|    /___   / _______/___    /__|____    /\n      \\       l___/    l___/   l___/  \\___/___/  [ViC!]\\___/       \\___/\n       \\                                                             /\n        \\SYSTeM CHieFS: SPY/TRSi,ARTHuR DeNT,PHaNToM,Cat,JTC,big-rat/\n         \\                                                         /\n          \\   1: +49(0) 30 721 6071 USR DuAL STaNDaRD V.34 28.8   /\n           \\  2: +49(0) 30 721 6072 USR DuAL STaNDaRD V.34 28.8  /\n            \\ 3: +49(0) 30 721 6073 USR DuAL STaNDaRD V.34 28.8 /\n             \\4: +49(0) 30 722 6065 USR DuAL STaNDaRD V.34 28.8/\n              \\                                   /\\          /\n               \\_________________________________//\\\\________/\n                                                 /__\\\n\n                        SUPPORTS ONLY PD-/SHAREWARE !\n@endnode\n','\n',char(10)),NULL,'auto-added',37700,5,0,NULL,NULL,'trsi_azk','scan',1780048787);
INSERT INTO door_catalog VALUES('trsi_b22','TRSI-B22.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-B22.LHA','ByteComment','XIM','ByteComment',NULL,NULL,'TRSI','\___   _______    ¼\/   ___________/ TRiSTaR /     |    /    _/\____   ¼\     |  ReD /      |    \    \     V     \    | SeCToR',replace('___________________  _______________ _______\n\___   _______    ¼\/   ___________/ TRiSTaR\n  /     |    /    _/\____   ¼\     |  ReD  \n /      |    \    \     V     \    | SeCToR\n \_____ |____|\____\__________/____|________\n  \   /_____.__/  /  ______  \/    \___  \__\\n  / .   /  / _/ __/ ___/     /  /  /  /  /  /\n /_____/__   /__/_____/__/__/__/__/_____/__/\n    ________/of (tRSi/X-iNNOVATiON) \n                 PRESENTS       \n    ByteKiller V2.2 for /X3.+ and /X 4.+\n','\n',char(10)),'ByteKiller.eng.guide',replace('@database Bytekiller.guide\n@author "Byteandi/trsi"\n@$VER: Bytekiller.guide \n@node main "ByteKiller V2.2 Documentation (c) Byteandi/trsi"\n\n\n               _____         _____________  _____________\n               \   /_____.__/  /  ______  \/    \___  \__\\n               / .   /  / _/ __/ ___/     /  /  /  /  /  /\n              /_____/__   /__/_____/__/__/__/__/_____/__/ \n              ________/of (tRSi/X-iNNOVATiOn) presents:\n\n\n                           @{BG fill}@{"   ByteKiller V2.0    "   link Bytekiller}@{BG Background}\n                           @{BG fill}@{"   ByteComment V1.0   "   link ByteComment}@{BG Background}\n                           @{BG fill}@{" BytekillHandler V1.0 "   link Bytekillhandler}@{BG Background}\n                           @{BG fill}@{"     ByteLog V1.0     "   link ByteLog}@{BG Background}\n                           @{BG fill}@{"Registration & Updates" link updates}@{BG Background}\n                           @{BG fill}@{"      Greeting(s)     " link greetings}@{BG Background}\n                           @{BG fill}@{"      Other Tools     " link other_tools}@{BG Background}\n\n\n\n                           @{BG fill}@{"   Changes to  V2.2   "   link Changes}@{BG Background}\n\n\n@endnode\n@node Bytekiller "ByteKiller V2.0"\n\nByteKiller V2.0 is XIM Tool for /X 3.+ and /X 4.+\n\nWhat can Bytekiller :\n\nYou can start Bytekiller with "Nuke trsi* afl*.dms fake*.l*.txt"\n\nBytekiller search if the ToolType @{BG fill}@{"NUKER_ALL" link ToolTypes}@{BG Background}\nis installed or if there any Tooltypes looks like @{BG fill}@{"NUKER.<x>" link ToolTypes}@{BG Background} or @{BG fill}@{"PASSWORD.<x>" link ToolTypes}@{BG Background}\n\nIf there is NUKER_ALL, bytekiller starts for all who wanted to nuke and \nhave the right level,\nelse bytekiller search for the right name and if he have any PW-protection`s !\n\nBytekiller can write only one message to the Up-Downloader about all fakes\n\nIf bytekiller doesn`t can Lock Msgbase or Filelist, he wait a while and if \nthere is no chance for Lock, he aborted this routine..\n\nYou can Configure all Comments and Messages how ever you want..please \nsearch in @{BG fill}@{"Configuration" link mycfg}@{BG Background} for that\n\nBytekiller can search for hisself about Dl- and UlPathes or Path to Callerslog \nand any more, but it is important to install the Tooltype @{BG fill}@{"USER_DATA" link ToolTypes}@{BG Background}\nbecause I handle this for myself because some stupid changes in /X 4.+\n\nBytekiller can open an ASL-Requester if you have installed the Tooltype @{BG fill}@{"ASK_ASL" link ToolTypes}@{BG Background}\nbut this Option works only if you nuked from the Console..\n\nBytekiller have some extern Tools, if you use any of them you have the fastest\nNuker of the world...\n\nYou can set up All Options in Bytekiller !\n\n                           @{BG fill}@{"Start von Bytekiller"   link start_bytekiller}@{BG Background}\n\n@endnode\n@node start_bytekiller "ByteKiller V2.0"\n\nStart Bytekiller V2.0 :\n\nif you started bytekiller he ask (if exist) for the Password from the User,\nthan he shows, if there any UserComments about some fakes and ask if \nyou want to Nuke from List !\nYou can Insert so many Files you ever want with and without Wildcarts !\nNow Bytekiller Ask you if you want to nuke with Automodus and if you want to \nuse the same options for all Files.....\nif you use Automodus, you can set options for all files or options \nfrom file to file.\nnow Ask Bytekiller if you are interested to search for UpLoader and \nshow you his status if he have found the User..\nYou can take or give now so many Creditz you ever want..\nIf you have done this, bytekiller ask you to search for Downloader\nand do show you his status and ask if he can have some bytes back..\nIf that is Ok you can set up the comments for the Filelisting !\n\nNow Bytekiller changes the listing writes some messages to the \nUp-Downloader and ask you if you want to give some extra comments \nin that message (if you have install the Tooltype "EXTERN_COMMENT") !\n\n                              @{BG fill}@{"   ByteKiller V2.0    "   link Bytekiller}@{BG Background}\n                              @{BG fill}@{"ToolTypes" link ToolTypes}@{BG Background}\n@endnode\n\n@node ByteComment "ByteComment V1.0"\n\nByteComment V1.0 is XIM for /X 3+ \n\nThis Tool is for all User to add some comments in your Filelisting,\nthis comments are saved in your bytekiller/fakes/ dir and if you \nstarted Bytekiller and he found some Comments, he ask you to use this list !\n\n                              @{BG fill}@{"       Menue          "   link main}@{BG Background}\n                              @{BG fill}@{"   ByteKiller V2.0    "   link Bytekiller}@{BG Background}\n                              @{BG fill}@{"ToolTypes" link ToolTypes}@{BG Background}\n@endnode\n\n@node Bytekillhandler "Bytekillhandler V1.0"\n\nBytekillhandler is an external CLI-Tool to start in your logoff-batch, \nif you use this Tool, you doesn`t need to run ByteLog. \n\nthis Handler search in your Callerslog for any Uploads from the last user\nand saves his AccountNumber, this Handler doesn`t need DataFiles for that,\nso it doesn`t need any bytes from your HD`s\n\nmy tip : start bytekillhandler before all other in your Logoff-batch !\n\nexample for logoff-batch:\n----------------------------\n.key node\n\nDoors:Bytekilller/bytekillhandler BBS:node<node>/Callerslog\n\n---------------------------------------------------------------------------\n\n                           @{BG fill}@{"       Menue          "   link main}@{BG Background}\n                           @{BG fill}@{"   ByteKiller V2.0    "   link Bytekiller}@{BG Background}\n@endnode\n\n@node Bytelog "Bytelog V1.0"\n\nByteLog is XIM Tool for /X 3.+\n\nYou can start it with EXAMINE.INFO\n                      EXAMINE1.INFO .....  (/X 4.+)\n                      FILECHECK.INFO\n                      FILECHECK1.INFO .... (/X 4.+)\nin your SYSCMD/\n\nit saves the user and his Upload in one dataFile in your Conf,you can \nsay how many days you want to Log if you install @{BG fill}@{"LOG_DAYS=<tage>" link ToolTypes}@{BG Background}\nin your bytekiller.info, default is 7 days !\n\nByteLog doesn`t strip the UdLog, he search, if there is an Upload witch\nis older than your Log Days and overwrite this data !\n\nif you run this Door you doesn`t need Bytekillhandler !\n\n                              @{BG fill}@{"       Menue          "   link main}@{BG Background}\n                              @{BG fill}@{"   ByteKiller V2.0    "   link Bytekiller}@{BG Background}\n                              @{BG fill}@{"ToolTypes" link ToolTypes}@{BG Background}\n@endnode\n\n@node updates "Registration & Updates"\n\nUpdates :           !!!!! Only for Registered user from my Tools !!!!\n\nI want install the question if you like to see what Bytekiller \ndoes in autonukeModus, or if you want to do other nice thinks..\nHighscore List for Top nuked User\nRandom Comments for AutonukeModus...\nGive bytes to user who says any about fakes...\nall what you want....and what I can do\n\n IF YOU WANT TO BE REGISTERED FOR THAT OR NEXT COMMING TOOLS \n\n                PAY 20$ OR 30,-DM\n\n IF YOU WAS REGISTERED FOR FILEID AND TOOLS BEFORE, YOU GET THIS \n AND NEXT COMMING TOOLS FOR FREE\n\n                 # +49 (30) 7216071  4 Nodes Ringdown Dual 288er\n\n\n                              @{BG fill}@{"       Menue          "   link main}@{BG Background}\n\n@endnode\n\n@node greetings "Special Greeting(s)"\n\nSPEEDLOCK      for some tests in his BBS \nDeath Angel    because he installed all my Tools\n[-Amok-]       for his english changes in my Tool\nSpy/trsi       for his best Alloc() Routine...and some tips..\nByteAndi/trsi  for his very nice Tools\nsiegel/trsi    your Soft-Del is great, I like it and thx for your \n               configs\nTRSI           for the nice Group..\n\nMac LifeGuard  your TurboNews is Fast but Shit, I don`t like to hear \n               4MB ram is not enough or see my Listing in green or see\n               "can`t advange any furter..."\n\n\n                              @{BG fill}@{"       Menue          "   link main}@{BG Background}\n\n@endnode\n\n@node mycfg "All Informations about Configuration(s)"\n\nConfiguration from the messages :\n\n\n%L  ----->  List of all Fakes and Up-Download Day with \n            creditz taken/Given\n\n%N ------>  Name of the Nuker \n\n%F ------>  Name of the Faker or Downloader\n\n%T ------>  All bytes taken in this Session.......\n            (ONLY FOR UPLOADER.CFG)               \n          \n%G ------>  All bytes Given in this Session.......\n            (ONLY FOR UPLOADER.CFG)               \n\n%B ------>  All Dl-Bytes given back in this Session.......\n            (ONLY FOR DOWNLOADER.CFG)               \n\nexample :\n----------\n\n\nHey %F you are Lame ,\nI have taken you %T because some fakes.., here is a list of all\n\n%L\n\n             please Delete this Message !\n\n-----------------------------------------------------------------------------\nmeans :\n\nHey byteandi/trsi you are lame,\nI have taken you 32228 bytes because some fakes.., here is the list of all\n\nOld UpLoad Bytes   :                         8738\nBytekiller V2.0    : Nuked *( -5)              71  Uploaded on (10-23-94)\nLamerDoc.txt       : Nuked *( -5)              71  Uploaded on (10-23-94)\n-------------------------------------------------\nNew UpLoad Bytes   :                            1\n\n             please Delete this Message !\n\n-----------------------------------------------------------------------------\n\nConfiguration for your Comments in the Filelisting :\n\n%b  ---->  how many Creditz Taken/given\n%B  ---->  bytes from the Nuked File\n%N  ---->  Name of the Nuker\n\nExample :\n\nEnter FakeComment : ^^ %N Takes you %B Bytes * (%b) ^^\n\nmeans :\n\n                    ^^ Byteandi/trsi Takes you 32321 Bytes * (-5) ^^\n\n\n\n                              @{BG fill}@{"       Menue          "   link main}@{BG Background}\n                              @{BG fill}@{"   ByteKiller V2.0    "   link Bytekiller}@{BG Background}\n                              @{BG fill}@{"ToolTypes" link ToolTypes}@{BG Background}\n\n\n@endnode\n\n@node ToolTypes "All Informations about ToolTypes"\n\n\n\nUSER_DATA         -----> Path and Name from  UserData\n\nNUKER_ALL         -----> this means that there is no PW protection,\n                         All User with the right Level can nuke\n\nNUKER.<x>=<name>  -----> the name of the User who can Nuke \n                         x = Number from 1 to ..\n\nPASSWORD.<x>=<PW> -----> The Password from the User who can Nuke\n                         x = Number from 1 to ..\n\nANSI_MESSAGE      -----> if you doesn`t use this Tooltype, Bytekiller striped\n                         All Ansi-Codes in the messages...\n\nCOMMENT.x=<wieviel> ---> Comment for the Filelisting (default`s)\n                         x = Number from 1 to ..                 \n\nFAKE.<x>=<warum>  -----> Why you have Nuked the File (default`s)\n                         x = Number from 1 to ..                 \n\nSIZE.<x>=<shit!>  -----> Comments for the ByteSize in the Listing \n                         x = Number from 1 to ..                 \n\nFREE_COLOR=<36>   -----> Color for the Comment if you make the File to \n                         freedownload\n                         \nGIVE_COLOR=<32>   -----> Color for the Comment if you Give Creditz \n                         \n\nTAKE_COLOR=<44;39> ----> Color for the Comment if you Take Creditz \n                         \n\nEXTERN_COMMENT    -----> if you have this Toolstype, bytekiller ask\n                         if you want to write some lines to the \n                         Up-Downloader\n\nCREATE_FAKEFILE   -----> you can create Fakefiles if you want..\n\nASK_ASL           -----> Bytekiller ask you if you want to use an \n                         ASl-Requester to flag files\n\nSPY_LIST=<list>   -----> ONLY to use if you have installed SPY_LIST\n                         or you have the files and descriptions in more\n                         FileListings, than list = the last list of deleted\n                         Files..\nFREEDOWNLOAD=<text>  --> text = what ever you want to give as Comment in \n                         your Listing default is :\n                         "FREEDOWNLOAD FREEDOWNLOAD"\n\nLOG_DAYS=<days>   -----> for ByteLog, to say how many Days he must Log !\n                         \n\nCOM_COLOR=<44;39> -----> Color for ByteComment\n\n                              @{BG fill}@{"       Menue          "   link main}@{BG Background}\n                              @{BG fill}@{"   ByteKiller V2.0    "   link Bytekiller}@{BG Background}\n                              @{BG fill}@{"ToolTypes" link ToolTypes}@{BG Background}\n@endnode\n\n@node other_tools "All Informations about other Tools "\n\n\nSysopDownload V1.1     the best Tool for /X....\n\nNewFiles V2.1          with his funktions the first of his art...\n                       the last version was V2.5ß for any friends..\n                       I`m doesn`t interested this time to make some \n                       new versions of this Tool because there was \n                       to many out this moment ( Fuck TN or Task-NewScan)\n                       (Aqua-scan Rulez....I only can say..)\n\nBullView V1.5          one of the first Tools I have made\n                       1.5+ doesn`t from me it is shit...\n\nVereNaris V1.1         Cool work from re/Y\o and me \n\nFileId V1.5            Last FileId version I think to make some\n                       versions because I doesn`t like all other \n                       FileId Tools.....\n                       FileId V2.0 is in work and I think to bring \n                       this Tool January 95\n\nAutosent V1.6          Last Version for regidstered Sysops\n\nAutoCfg V1.0           only internal for some stupid User\n\nAFL-Quest V1.1         one of the first Tools I have made..\n                       \nFastDupe V1.0          nice programming of dre! and me hehe\n                       and nice to see how many lamer have made \n                       other versions\n\nByteMover V1.1         this Time Internal, but I think to release\n                       becuase all sysops like this Tool\n\nComment V1.2           Comment to Sysop, the first with Message-Upload\n                       \nFileDl V1.0            Download of All Filelistings from date \n                       \nRegister V1.5          Only Internal for (Mystic/X-Design)\n                       \nafl_Bull V1.0          The first Tool I have made, create 5 Bulls\n\n\n\n                              @{BG fill}@{"       Menue          "   link main}@{BG Background}\n                              @{BG fill}@{"   ByteKiller V2.0    "   link Bytekiller}@{BG Background}\n@endnode\n\n@node Changes "Changes to this Version V2.2 "\n\nSmall Bug in Memory-routines is now fixed..\n\nTooltype FREE_DOWNLOAD works now 100%\n\nI have added the "award.cfg", this txt is for Uploader if the sysop \nonly have Bytes given, if the sysop take and give Bytes he get the \nUploader.cfg !\n\nBytekiller is this Time by V2.3 (only for registered Sysops) and have \nmore new Futures, and I`m working to add some more Options\n\nKiloByte Option in Acp.Info works now 100%\n\n                              @{BG fill}@{"       Menue          "   link main}@{BG Background}\n                              @{BG fill}@{"   ByteKiller V2.0    "   link Bytekiller}@{BG Background}\n\n@endnode\n','\n',char(10)),NULL,'auto-added',58627,6,0,NULL,NULL,'trsi_b22','scan',1780048787);
INSERT INTO door_catalog VALUES('trsi_ba','TRSI-BA.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-BA.LHA','rexxdoor','XIM','REXXDOOR',NULL,'[-Dr.Dre!/tRSi]','TRSI','\        ____   \/   _________/   TRiSTAR \/    \/   _  _/\____  \/    \ RED SECTOR! +-/RtX!  \   |   \_   |   \     \----------+',replace(' /\______________  _____________\n \        ____   \/   _________/   TRiSTAR\n  \/    \/   _  _/\____  \/    \ RED SECTOR!\n+-/RtX!  \   |   \_   |   \     \----------+\n| \  ____/___|__  /_____  / ____/  pRESENTs|\n+--\/-----------\/------\/\/---------------+\n   BBS Advertiser v1.2 by [-Dr.Dre!/tRSi]\n--------------------------------------------\n','\n',char(10)),'BBSAdd.Guide',replace('@database BBS Advertiser 1.1 Final\n\nCopyright (C) 1993 by [-Dr.Dre!/tRSi], Germany\nAll Rights Reserved\n\n@Remark $VER: Version v1.1 (Monday 17-Jan-94 13:32:57)\nRemark AmigaGuide DataBase for BBS Advertiser 1.1final by [-Dr.Dre!/tRSi]\n\n@node MAIN "BBS Advertiser 1.1 (Monday 17-Jan-94 13:32:57) AmigaGuide Document for /X"\n             ____                        ___                     :\n           ._\  /________________________\_/ ____________________¦_ _\n           |  \/   __ _ _               _\_ /_      _/           |\n           |    _ _\         T.R.S.I      // \_    / \_ _     \\ |\n           | ____________________________//____________________\ |\n       ____| \        ___________      /_____        /______  /  |____\n      /\___\  \      /    .|   _/    _/\    /_______/       \/|  /___/\\n      \/___/   \  __/     ¦|   \      \_\_____     \_        ¦|  \___\/\n           |    \/ /      :|    \      /     /      /        :|  |\n           | \    /________|  _  \    /____________/|_________| _|\n           | \\         _ _  \_   \  /_ \\  _ __ _          _ _/ |\n           | \\\           \_/     \/ \_//       /__ _         \ |\n        _ _|________________\__________/ \__________________ /\ _|H2o!\n           ¦                           /\                   /__\\n     is proud to present: BBS Advertiser 1.1 (Monday 17-Jan-94 13:32:57)\n\n                         @{"     Introduction      " Link no1}\n                         @{"     Requirements      " Link no2}\n                         @{"     Installation      " Link no3}\n                         @{"      Menu Help!       " Link no4}\n                         @{"       Creditz!        " Link no5}\n                         @{"      Greetings!       " Link no6}\n                         @{"     tRSI Boards!      " Link no7}\n@endnode\n@node no1 " Introduction"\n\nThis Tool is usefull for all Sysop who hate all the fukkin BBSAdds in the\nMessagebase...\nBBS Advertise 1.1 allows a User to Add his BBS Add into the Door, and he\nneed to do this only one Time...\nEvery User can jump into the door and pick out the BBSAdd he want see...\nIf he like it or he need it then he can d/l it or he can d/l all Adds at\none Time....\n\nhave phun with the door...\n                       [-Dr.Dre!/tRSi]\n\n@endnode\n@node no2 " Requirements"\n\nYou need an Amiga 500/1000/2000/3000 (The Sysops with an A4ooo or A12oo \nshould call my BBS to receive an uncompiled Version)\nKickstart 2.0 or higher\nAmi Express 2.xx - 3.xx (Registered)\nAn running RPStart\nrexxplsextnd.library\nRexxplslib.library\nrexxsyslib.library\nrexxsupport.library\nin your Libs: but they are included\n\nThats all...\n\n@endnode\n@node no3 " Installation"\n\nFirst copy all Libs: (If you dont have them allready) into your libs: Dir\nCopy the Badd.info to your BBS:Commands/bbscmd/\nand make shure you run rpstart in your Startup-Sequence.\nThen create a Directory called BBSADD in your Doors...\nThere you copy all Files and Dirs from the Archive Directory \nBBS/Doors/BBSAdd/\n\nThere must be in all this Files and Dirs...\n\nadds       (dir)\nTemp       (Dir)\nadd.init   (ascii file)\nBBSAdd.AiM (The Door self)\nBBSAdd.Cfg (The Config File)\n\nAfter this jump into the BBSAdd.Cfg File and change the Levels for your BBS.\n------------------cut here------------------\n50\n100\n253\n------------------cut here------------------\nLine.1=from this Level on a User can view the Adds\nLine.2=from this Level on a User can Add an own Add to the Door\nLine.3=from this Level on a User can remove Adds from the Door\n\nThis is all what you have to do...\n\n@endnode\n@Node no4 " Menu Help"\n\n             ._______________________________________________.\n             |                                               |\n             |        1) .......View BBS Advert......        |\n             |        2) ...Download BBS Advert......        |\n          --+O---     3) ......Enter BBS Advert......     --+O---\n             |        4) .....Remove BBS Advert......        |\n             |        5) ..........Show Creditz......        |\n             |        Q) ...............Exiting......        |\n             !_______________________________________________!\n                                  __ :\n                                 /\_\: \n                                 \/_/:\n                                     ·\n\n                  This is the Main menu from the Door...\n\n1. View BBS Adverts\n2. Download Advert (or let the Door pack all Adds to one Lha File)\n3. Enter BBS Advert, here the User will be asked, if he want enter the\n   Advert in the MsgBase Editor or he want U/L The Advert, work from the\n   Local Node too...\n4. Here it is possible for Users with an specified Access level (CfgFile)\n   to remove ADverts from the Door...\n5. View Door Creditz and some Greetings...\nQ. Exit the Door\n@endnode\n@Node no5 " The Creditz!"\n\n              Copyright (C) 1994 by [-Dr.Dre!/tRSi], Germany\n                            All Rights Reserved\n\n             The AmigaGuide DataBase written by [-Dr.Dre!/tRSi]\n\n    For more good Doors call my BBS under 49 (0) 2131 275756 & 275634\n               · [ · MARLEYS COFFEE SHOP - tRSi GHQ · ] ·\n\n      Thanx to Skin! for using some of your great Style in my Doors!\n\n@endnode\n@Node no6 " Greetings"\n\n                   The Greets are going to this Dudes...\n\n ByteAndi/X-Design, Spy/X-Design, Remo/X-Design, X-Treme/TRSI, Saito/TRSI\n    Gandalf/Faith, Silver/Faith, McLoud/TRSI, Irata/TRSI, Triton/Fth\n Skylark/LSD, Nick, Metoner/TRSI, J.Walker/TRSI, Crazy/TRSI, Valshare/TRSI\n    Vicous/LSD, Richi/Flt, Steve/D&R, Amicom, -rS!, Empire/Mst, Mr.VAiN\n            APOLLO, BJoerN/Pdy, Jive/TRSi, Scope/Trsi, SkiN!\n          and simply all tRSi Member an other Doodes I forgot...\n\n@endnode\n@Node no7 " tRSi Boards Worldwide"\n\n                 To Contact me Call any of this Boards...\n           -==================================================-\n\n   Cauldron.......................German  hq............++49 Pure Elite\n   Marleys Coffee Shop............German  hq............++49 Pure Elite\n   Boondocks......................Europe  hq............+31-548-040-653\n   Final Impact...................Swedish hq............++46-54-113-486\n   Flying Spirits.................Swiss   hq............+41-217-282-524\n   Savage Amusement...............Austia  hq............+43-767-227-743\n   Zenlandia......................Finnish hq............+358-088-82-144\n\n\n           -==================================================-\n@endnode\n','\n',char(10)),NULL,'auto-added',115265,5,0,NULL,NULL,'nvx_rem5','scan',1780048787);
INSERT INTO door_catalog VALUES('trsi_bk2','TRSI-BK2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-BK2.LHA','ByteComment','XIM','ByteComment',NULL,NULL,'TRSI','\___   _______    ¼\/   ___________/ TRiSTaR /     |    /    _/\____   ¼\     |  ReD /      |    \    \     V     \    | SeCToR',replace('___________________  _______________ _______\n\___   _______    ¼\/   ___________/ TRiSTaR\n  /     |    /    _/\____   ¼\     |  ReD  \n /      |    \    \     V     \    | SeCToR\n \_____ |____|\____\__________/____|________\n  \   /_____.__/  /  ______  \/    \___  \__\\n  / .   /  / _/ __/ ___/     /  /  /  /  /  /\n /_____/__   /__/_____/__/__/__/__/_____/__/\n    ________/of (tRSi/X-iNNOVATiON) \n             is BACK and PRESENTS :      \n    ByteKiller V2.0 for /X3.+ and /X 4.+\n','\n',char(10)),'ByteKiller.eng.guide',replace('@database Bytekiller.guide\n@author "Byteandi/trsi"\n@$VER: Bytekiller.guide \n@node main "ByteKiller V2.0 Documentation (c) Byteandi/trsi"\n\n\n               _____         _____________  _____________\n               \   /_____.__/  /  ______  \/    \___  \__\\n               / .   /  / _/ __/ ___/     /  /  /  /  /  /\n              /_____/__   /__/_____/__/__/__/__/_____/__/ \n              ________/of (tRSi/X-iNNOVATiOn) presents:\n\n\n                           @{BG fill}@{"   ByteKiller V2.0    "   link Bytekiller}@{BG Background}\n                           @{BG fill}@{"   ByteComment V1.0   "   link ByteComment}@{BG Background}\n                           @{BG fill}@{" BytekillHandler V1.0 "   link Bytekillhandler}@{BG Background}\n                           @{BG fill}@{"     ByteLog V1.0     "   link ByteLog}@{BG Background}\n                           @{BG fill}@{"Registration & Updates" link updates}@{BG Background}\n                           @{BG fill}@{"      Greeting(s)     " link greetings}@{BG Background}\n                           @{BG fill}@{"      Other Tools     " link other_tools}@{BG Background}\n@endnode\n@node Bytekiller "ByteKiller V2.0"\n\nByteKiller V2.0 is XIM Tool for /X 3.+ and /X 4.+\n\nWhat can Bytekiller :\n\nYou can start Bytekiller with "Nuke trsi* afl*.dms fake*.l*.txt"\n\nBytekiller search if the ToolType @{BG fill}@{"NUKER_ALL" link ToolTypes}@{BG Background}\nis installed or if there any Tooltypes looks like @{BG fill}@{"NUKER.<x>" link ToolTypes}@{BG Background} or @{BG fill}@{"PASSWORD.<x>" link ToolTypes}@{BG Background}\n\nIf there is NUKER_ALL, bytekiller starts for all who wanted to nuke and \nhave the right level,\nelse bytekiller search for the right name and if he have any PW-protection`s !\n\nBytekiller can write only one message to the Up-Downloader about all fakes\n\nIf bytekiller doesn`t can Lock Msgbase or Filelist, he wait a while and if \nthere is no chance for Lock, he aborted this routine..\n\nYou can Configure all Comments and Messages how ever you want..please \nsearch in @{BG fill}@{"Configuration" link mycfg}@{BG Background} for that\n\nBytekiller can search for hisself about Dl- and UlPathes or Path to Callerslog \nand any more, but it is important to install the Tooltype @{BG fill}@{"USER_DATA" link ToolTypes}@{BG Background}\nbecause I handle this for myself because some stupid changes in /X 4.+\n\nBytekiller can open an ASL-Requester if you have installed the Tooltype @{BG fill}@{"ASK_ASL" link ToolTypes}@{BG Background}\nbut this Option works only if you nuked from the Console..\n\nBytekiller have some extern Tools, if you use any of them you have the fastest\nNuker of the world...\n\nYou can set up All Options in Bytekiller !\n\n                           @{BG fill}@{"Start von Bytekiller"   link start_bytekiller}@{BG Background}\n\n@endnode\n@node start_bytekiller "ByteKiller V2.0"\n\nStart Bytekiller V2.0 :\n\nif you started bytekiller he ask (if exist) for the Password from the User,\nthan he shows, if there any UserComments about some fakes and ask if \nyou want to Nuke from List !\nYou can Insert so many Files you ever want with and without Wildcarts !\nNow Bytekiller Ask you if you want to nuke with Automodus and if you want to \nuse the same options for all Files.....\nif you use Automodus, you can set options for all files or options \nfrom file to file.\nnow Ask Bytekiller if you are interested to search for UpLoader and \nshow you his status if he have found the User..\nYou can take or give now so many Creditz you ever want..\nIf you have done this, bytekiller ask you to search for Downloader\nand do show you his status and ask if he can have some bytes back..\nIf that is Ok you can set up the comments for the Filelisting !\n\nNow Bytekiller changes the listing writes some messages to the \nUp-Downloader and ask you if you want to give some extra comments \nin that message (if you have install the Tooltype "EXTERN_COMMENT") !\n\n                              @{BG fill}@{"   ByteKiller V2.0    "   link Bytekiller}@{BG Background}\n                              @{BG fill}@{"ToolTypes" link ToolTypes}@{BG Background}\n@endnode\n\n@node ByteComment "ByteComment V1.0"\n\nByteComment V1.0 is XIM for /X 3+ \n\nThis Tool is for all User to add some comments in your Filelisting,\nthis comments are saved in your bytekiller/fakes/ dir and if you \nstarted Bytekiller and he found some Comments, he ask you to use this list !\n\n                              @{BG fill}@{"       Menue          "   link main}@{BG Background}\n                              @{BG fill}@{"   ByteKiller V2.0    "   link Bytekiller}@{BG Background}\n                              @{BG fill}@{"ToolTypes" link ToolTypes}@{BG Background}\n@endnode\n\n@node Bytekillhandler "Bytekillhandler V1.0"\n\nBytekillhandler is an external CLI-Tool to start in your logoff-batch, \nif you use this Tool, you doesn`t need to run ByteLog. \n\nthis Handler search in your Callerslog for any Uploads from the last user\nand saves his AccountNumber, this Handler doesn`t need DataFiles for that,\nso it doesn`t need any bytes from your HD`s\n\nmy tip : start bytekillhandler before all other in your Logoff-batch !\n\nexample for logoff-batch:\n----------------------------\n.key node\n\nDoors:Bytekilller/bytekillhandler BBS:node<node>/Callerslog\n\n---------------------------------------------------------------------------\n\n                           @{BG fill}@{"       Menue          "   link main}@{BG Background}\n                           @{BG fill}@{"   ByteKiller V2.0    "   link Bytekiller}@{BG Background}\n@endnode\n\n@node Bytelog "Bytelog V1.0"\n\nByteLog is XIM Tool for /X 3.+\n\nYou can start it with EXAMINE.INFO\n                      EXAMINE1.INFO .....  (/X 4.+)\n                      FILECHECK.INFO\n                      FILECHECK1.INFO .... (/X 4.+)\nin your SYSCMD/\n\nit saves the user and his Upload in one dataFile in your Conf,you can \nsay how many days you want to Log if you install @{BG fill}@{"LOG_DAYS=<tage>" link ToolTypes}@{BG Background}\nin your bytekiller.info, default is 7 days !\n\nByteLog doesn`t strip the UdLog, he search, if there is an Upload witch\nis older than your Log Days and overwrite this data !\n\nif you run this Door you doesn`t need Bytekillhandler !\n\n                              @{BG fill}@{"       Menue          "   link main}@{BG Background}\n                              @{BG fill}@{"   ByteKiller V2.0    "   link Bytekiller}@{BG Background}\n                              @{BG fill}@{"ToolTypes" link ToolTypes}@{BG Background}\n@endnode\n\n@node updates "Registration & Updates"\n\nUpdates :           !!!!! Only for Registered user from my Tools !!!!\n\nI want install the question if you like to see what Bytekiller \ndoes in autonukeModus, or if you want to do other nice thinks..\nHighscore List for Top nuked User\nRandom Comments for AutonukeModus...\nGive bytes to user who says any about fakes...\nall what you want....and what I can do\n\n IF YOU WANT TO BE REGISTERED FOR THAT OR NEXT COMMING TOOLS \n\n                PAY 20$ OR 30,-DM\n\n IF YOU WAS REGISTERED FOR FILEID AND TOOLS BEFORE, YOU GET THIS \n AND NEXT COMMING TOOLS FOR FREE\n\n                 # +49 (30) 7216071  4 Nodes Ringdown Dual 288er\n\n\n                              @{BG fill}@{"       Menue          "   link main}@{BG Background}\n\n@endnode\n\n@node greetings "Special Greeting(s)"\n\nSPEEDLOCK      for some tests in his BBS \nDeath Angel    because he installed all my Tools\n[-Amok-]       for his english changes in my Tool\nSpy/trsi       for his best Alloc() Routine...and some tips..\nByteAndi/trsi  for his very nice Tools\nTRSI           for the nice Group..\nMac LifeGuard  FUCK UP\n                              @{BG fill}@{"       Menue          "   link main}@{BG Background}\n\n@endnode\n\n@node mycfg "All Informations about Configuration(s)"\n\nConfiguration from the messages :\n\n\n%L  ----->  List of all Fakes and Up-Download Day with \n            creditz taken/Given\n\n%N ------>  Name of the Nuker \n\n%F ------>  Name of the Faker or Downloader\n\n%T ------>  All bytes taken in this Session.......\n            (ONLY FOR UPLOADER.CFG)               \n          \n%G ------>  All bytes Given in this Session.......\n            (ONLY FOR UPLOADER.CFG)               \n\n%B ------>  All Dl-Bytes given back in this Session.......\n            (ONLY FOR DOWNLOADER.CFG)               \n\nexample :\n----------\n\n\nHey %F you are Lame ,\nI have taken you %T because some fakes.., here is a list of all\n\n%L\n\n             please Delete this Message !\n\n-----------------------------------------------------------------------------\nmeans :\n\nHey byteandi/trsi you are lame,\nI have taken you 32228 bytes because some fakes.., here is the list of all\n\nOld UpLoad Bytes   :                         8738\nBytekiller V2.0    : Nuked *( -5)              71  Uploaded on (10-23-94)\nLamerDoc.txt       : Nuked *( -5)              71  Uploaded on (10-23-94)\n-------------------------------------------------\nNew UpLoad Bytes   :                            1\n\n             please Delete this Message !\n\n-----------------------------------------------------------------------------\n\nConfiguration for your Comments in the Filelisting :\n\n%b  ---->  how many Creditz Taken/given\n%B  ---->  bytes from the Nuked File\n%N  ---->  Name of the Nuker\n\nExample :\n\nEnter FakeComment : ^^ %N Takes you %B Bytes * (%b) ^^\n\nmeans :\n\n                    ^^ Byteandi/trsi Takes you 32321 Bytes * (-5) ^^\n\n\n\n                              @{BG fill}@{"       Menue          "   link main}@{BG Background}\n                              @{BG fill}@{"   ByteKiller V2.0    "   link Bytekiller}@{BG Background}\n                              @{BG fill}@{"ToolTypes" link ToolTypes}@{BG Background}\n\n\n@endnode\n\n@node ToolTypes "All Informations about ToolTypes"\n\n\n\nUSER_DATA         -----> Path and Name from  UserData\n\nNUKER_ALL         -----> this means that there is no PW protection,\n                         All User with the right Level can nuke\n\nNUKER.<x>=<name>  -----> the name of the User who can Nuke \n                         x = Number from 1 to ..\n\nPASSWORD.<x>=<PW> -----> The Password from the User who can Nuke\n                         x = Number from 1 to ..\n\nANSI_MESSAGE      -----> if you doesn`t use this Tooltype, Bytekiller striped\n                         All Ansi-Codes in the messages...\n\nCOMMENT.x=<wieviel> ---> Comment for the Filelisting (default`s)\n                         x = Number from 1 to ..                 \n\nFAKE.<x>=<warum>  -----> Why you have Nuked the File (default`s)\n                         x = Number from 1 to ..                 \n\nSIZE.<x>=<shit!>  -----> Comments for the ByteSize in the Listing \n                         x = Number from 1 to ..                 \n\nFREE_COLOR=<36>   -----> Color for the Comment if you make the File to \n                         freedownload\n                         \nGIVE_COLOR=<32>   -----> Color for the Comment if you Give Creditz \n                         \n\nTAKE_COLOR=<44;39> ----> Color for the Comment if you Take Creditz \n                         \n\nEXTERN_COMMENT    -----> if you have this Toolstype, bytekiller ask\n                         if you want to write some lines to the \n                         Up-Downloader\n\nCREATE_FAKEFILE   -----> you can create Fakefiles if you want..\n\nASK_ASL           -----> Bytekiller ask you if you want to use an \n                         ASl-Requester to flag files\n\nSPY_LIST=<list>   -----> ONLY to use if you have installed SPY_LIST\n                         or you have the files and descriptions in more\n                         FileListings, than list = the last list of deleted\n                         Files..\nFREEDOWNLOAD=<text>  --> text = what ever you want to give as Comment in \n                         your Listing default is :\n                         "FREEDOWNLOAD FREEDOWNLOAD"\n\nLOG_DAYS=<days>   -----> for ByteLog, to say how many Days he must Log !\n                         \n\nCOM_COLOR=<44;39> -----> Color for ByteComment\n\n                              @{BG fill}@{"       Menue          "   link main}@{BG Background}\n                              @{BG fill}@{"   ByteKiller V2.0    "   link Bytekiller}@{BG Background}\n                              @{BG fill}@{"ToolTypes" link ToolTypes}@{BG Background}\n@endnode\n\n@node other_tools "All Informations about other Tools "\n\n\nSysopDownload V1.1     the best Tool for /X....\n\nNewFiles V2.1          with his funktions the first of his art...\n                       the last version was V2.5ß for any friends..\n                       I`m doesn`t interested this time to make some \n                       new versions of this Tool because there was \n                       to many out this moment ( Fuck TN or Task-NewScan)\n                       (Aqua-scan Rulez....I only can say..)\n\nBullView V1.3          one of the first Tools I have made\n                       1.3+ doesn`t from me it is shit...\n\nVereNaris V1.1         Cool work from re/Y\o and me \n\nFileId V1.5            Last FileId version I think to make some\n                       versions because I doesn`t like all other \n                       FileId Tools.....\n\nAutosent V1.6          Last Version for regidstered Sysops\n\nAutoCfg V1.0           only internal for some stupid User\n\nAFL-Quest V1.1         one of the first Tools I have made..\n                       \nFastDupe V1.0          nice programming of dre! and me hehe\n                       and nice to see how many lamer have made \n                       other versions\n\nByteMover V1.1         this Time Internal, but I think to release\n                       becuase all sysops like this Tool\n\nComment V1.2           Comment to Sysop, the first with Message-Upload\n                       \nFileDl V1.0            Download of All Filelistings from date \n                       \nRegister V1.5          Only Internal for (Mystic/X-Design)\n                       \nafl_Bull V1.0          The first Tool I have made, create 5 Bulls\n\n\n\n                              @{BG fill}@{"       Menue          "   link main}@{BG Background}\n                              @{BG fill}@{"   ByteKiller V2.0    "   link Bytekiller}@{BG Background}\n@endnode\n','\n',char(10)),NULL,'auto-added',66933,8,0,NULL,NULL,'trsi_bk2','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_c13','TRSI_C13.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI_C13.LHA','Comment','XIM','Comment',NULL,'Dr.Dre!/tRZ','TRSI','l___       /      \/    _/_______.: /       /   /  _/\___      /    : /_______/-rS!\_____\  _____/     |',replace('    ._________________  ______\n    l___       /      \/    _/_______.:\n      /       /   /  _/\___      /    :\n     /_______/-rS!\_____\  _____/     |\n           /_______|     \/`94/_______|\n   MS-Comment v1.3 (XiM) by Dr.Dre!/tRZ\n  many new Options like forwarding Mails\n   supporting PromptLine and mayn more\nat least the best & comformst MultiComment\n','\n',char(10)),'MSComment.guide',replace('@database MS-Comment v1.3 - by Dr.Dre!/TrSi\n\nCopyright (C) 1994 by Dr.Dre!/tRSi^zENITh Germany\nAll Rights Reserved\n\n@Remark $VER: v1.3 (Saturday 19-Mar-94 14:12:21)\nRemark AmigaGuide DataBase for MS-Comment v1.3\n\n@Node MAIN "MS_Comment v1.3 (Saturday 19-Mar-94 14:12:21) Document for /X"\n\n                   ._________________  ______\n                   l___       /      \/    _/_______.:  \n                     /       /   /  _/\___      /    :\n                    /_______/-rS!\_____\  _____/     |''94  \n                          /_______|     \/   /_______|\n\n                           is proud to present: \n          Multi_Sysop_Comment v1.3, XiM Module for /X 2.xx - 3.xx\n\n                          @{"     Introductions     "Link Intro}\n                          @{"   Update 1.2 to 1.3   "Link news}\n                          @{"     Requirements      "Link Requi}\n                          @{"     Installation      "Link Insta}\n                          @{"     All ToolTypes     "Link Toolt}\n                          @{"        Example        "Link Examp}\n                          @{"        Creditz        "Link Credi}\n                          @{"        History        "Link Histo}\n                          @{"       Greetings       "Link Greet}\n                          @{"      TRSI Boards      "Link Board}\n                          @{"    Exit Guidefile     "QUIT}\n\n@endnode\n@node Intro "MS-Comment v1.3 Introductions"\n\nFor shure you remember the Multi Sysop Comment v1.2 released few Weeks\nago. Well, the Version 1.2 was good as nothing else, but look what bet\nthe update, this is for shure the best Multi Commenter available right\nnow. This Version features the following Options:\n\n1. Unlimited Sysops & CoSysop\n2. Set up an default Sysop by pressing Return only\n3. Forwarding Mail to another Sys(CoSys)op\n4. Seperate Output for Sysops and CoSysops\n5. Supporting Prompt Line\n6. Better @{" Design "Link Examp}\n7. Complete Setup about an Icon\n8. Possible to make it resident\n9. Smaller and faster Code\nBut install it and enjoy the Power of this Door.\n\nNOTE: The MS-Comment v1.3 is 100% BackDoor Free, if you dont believe them\n      call @{" Marleys Coffee Shop "Link Marleys} for your private Version.\n\n                             @{" Main Menu "Link MAIN} @{" Exit "QUIT}\n\n@endnode\n\n@node Requi "Requirements to run MS-Comment 1.3"\n\nAll what you need is the following:\n\n1. Kickstart 2.0 or higher\n2. A full installed Version of AmiExpress vX.xx\n3. A assigned Directory called Doors:\n\nand nothing else...                  @{" Main Menu "Link MAIN} @{" Exit "QUIT}\n\n@endnode\n\n@node Insta "Installation of MS-Comment v1.3"\n\nAfter unpacking the TRSI-C13.LHA copy the whole Directory Comment from the\nArchive to your DOORS:\nCopy the BBS:Commands/BBSCmd/C.Info to your BBS:Commands/BBSCmd/\nAfter copying the Files jump into the Doors:Comment/ Directory and open the\nComment.Info for configuration the MS-Comment.\nThe following @{" ToolTypes "Link Toolt} are available.\nIf you have setup the Comment.Info the Installation is done, and you can join\nyour new Comment Door.\n\n@endnode\n\n@node Toolt "All ToolType Informations"\n\nNAME.<#>=<Sysop Name>\n---------------------\nEg:\nNAME.1=Dr.Dre!/TRSI\nNAME.2=J.Walker/TRSI\nNAME.3=McLoud/TRSI\nand so on set up how much Sysops you want.\n------------------------------------------\n\nDESC.<#>=<Sysop Funktion>\n-------------------------\nThis is the funktion from the Sysop(s). DESC.1 means thats this is the\nFunktion from Sysop #1 and so on....\nEg:\nDESC.1=The big Boss is watching you\nDESC.2=Console Cosysop & Nuker\nDESC.3=TRSI World Leader\n------------------------------------------\n\nANSWER.<#>=<Some Bullshit as Answer by choosen them>\n----------------------------------------------------\nThis are the Answer Lines which are displayed by choosen the different\nSysop(s). ANSWER.1 is the Answer Line from Sysop #1, and so on.\nEg:\nANSWER.1=Remember the other Sysops\nANSWER.2=Thanx for leavin Mail\nANSWER.3=Why me ??? \n----------------------------------------------------\n\nDEFAULT_SYSOP=<#>=<Number from the Sysop which should be the default Sysop>\n---------------------------------------------------------------------------\nHere you can setup a default Sysop, this Sysop will be choosen by pressing\nReturn only.\nEg:\nDEFAULT_SYSOP=1\nmeans default Sysop is Sysop #1\n----------------------------------------------------\n\nFORWARD_FROM=<#>=<Number from the Sysop which should be forwarding Mail>\nFORWARD_TO=<#>=<Number from the Sysop to send the forwarding Mails>\n------------------------------------------------------------------------\nThis ToolTypes are only together sensefull.\nMay you are the Sysop and you go to Holiday and wish thats are all your\nMails forward to another Sysop then setup this ToolTypes.\nEg:\nFORWARD_FROM=1\nFORWARD_TO=3\nThis means if a User choose Sysop 1 the Mail will go automatically to\nSysop 3.\nanother example:\nFORWARD_FROM=5\nFORWARD_TO=1\nThis means if a User choose Sysop 5 the Mail will go automatically to\nSysop 1.\nI hope this explains this usefull Option.\n----------------------------------------------------\n\nCOSYSOP_FROM=<#>=<Number where starts the Cosysop to insert a seperate Line>\n----------------------------------------------------------------------------\nHere you can specify from where on the CoSysops starts, to add a Line bet-\nween the Sysops and CoSysop(s)\nEg:\nCOSYSOP_FROM=4\nThis means Sysop 1-3 are Sysops, and all Sysops higher as 3 are Cosysops.\nMS-Comment adds now a line between the Sysops & Cosysops.\nLike this @{" Example "Link Examp}.\n----------------------------------------------------\n\nI hope everybody understand all the ToolTypes, it is a bit hard to explain\nthem coz my English is really sick...\n\n                             @{" Main Menu "Link MAIN} @{" Exit "QUIT}\n\n@endnode\n\n@node news "What is new in MS-Comment 1.3"\n\n\n\n                       UPDATE from MCS v1.2 to v1.3\n                       ~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n1. Supporting AmiExpress PromptLine.\n   If you press c 3 at the Prompt, you will not jump to the Sysop\n   Menu, now you jump directly to the msgbase. If the Sysop does not\n   exists you will jump into the Sysop Menu.\n2. Adding 2 new ToolTypes on XTC!`s Suggestion, called FORWARD_FROM=<#>\n   and FORWARD_TO=<#>, if you set this ToolTypes, then it is possible to\n   forward Mails from one Sysop to another Sysop.\n3. Faster and shorter Code.\n4. Adding new ToolType on AMICOM/MST`s Suggestion, called COSYSOP_FROM=<#>\n   If you set them the MSC will add a seperate Line between the Sysops\n   and CoSysops.\n5. New Design\n\n                             @{" Main Menu "Link MAIN} @{" Exit "QUIT}\n\n@endnode\n\n@node Credi "Creditz and some Informations"\n\n\n\n\n\n                      MS-Comment v1.3 was written by\n                         Dr.Dre!/TRSI in Mar 1994\n                 Original Size of MS-Comment : 12032 bytes\n\n                  The AMIGAGUIDE Database was written by\n                               Dr.Dre!/TRSI\n\n               The TRSI Logo in the MAINNODE was painted by\n                             redSkin/TRSI/art\n\n                             @{" Main Menu "Link MAIN} @{" Exit "QUIT}\n\n@endnode\n\n@node Histo "History of MS-Comment"\n\nJune 1993  -  first Version written in AREXX\nDec  1993  -  small changes in the AREXX Code\nFeb  1994  -  totally rewritten in C, first beta Version\nFeb  1994  -  v1.2 Release Version\n-------------------------------------------------------------------------\n[03-08-94] Dr.Dre!/tRZ\n\nAnother Bug in the Comment.x found and fixed now it dont will allocate any\nmemory and steal it..\n-------------------------------------------------------------------------\n[03-09-94] Dr.Dre!/tRZ\n\nCHANGES IN THE MS-COMMENT 1.2 to 1.2a\nNow you can call C 1 for Sysop #1 or C 5 for Sysop #5 and so on.\nThanx to XTC! for this Suggestion.\n\nNew ToolTypes:\n--------------\nFORWARD_FROM=<#>\nFORWARD_TO=<#>\nThis means you can now forwarding Mails from one Sysop to another Sysop.\nIf you want forwarding masil from Sysop #1 to Sysop #5 then set the\nToolTypes like this example.\nFORWARD_FROM=1\nFORWARD_TO=5\nnow are going all mails for sysop #1 to sysop n5 this is really usefull if\nyou go in Hollidays or so...\n----------------------------------------------------------------------------\n15-Mar-94 - Totally rewritten in a faster Code and with more Options.\n19-Mar-94 - Add on a Suggestion from AMICOM/MST a new ToolTypes which\n            allwos you to add a seperate Line between the Sysops and\n            CoSysops.\n            many thanx for this Suggestion looks nice...\n19-Mar-94 - MS-Comment 1.3 final release Version\n\n                             @{" Main Menu "Link MAIN} @{" Exit "QUIT}\n\n@endnode\n\n@node greet "Some Greetings..."\n\n                         Greetings to this Guys...\n                         ~~~~~~~~~~~~~~~~~~~~~~~~~\n ByteAndi/Mst - McLoud/TRSI - J.Walker/TRSI - Sal-One/TRSI - Nick - Xtreme\n   Irata/TRZ - Saito/TRZ - Siegel/Mst - Spy/Mst - MARIO/TRZ - RICHI/FLT\nViscous/LSD - Steve/D&R - -rS!/TRSi - Empire/Mst - Scope - BJoerN/Pdy Amicom\n        MetalbasheR! - Skylark/LSD - Samir/TRZ - Rotor/TRZ - RE/X\O\n                             and all i forgot\n\n                             to my BetaTesters\n                             ~~~~~~~~~~~~~~~~~\n      DEXter & lACOSTE! - NiCK - tRITON/PDY - DR. G/4WD - [-AmiCom-]\nMcloud/TRSi - vaLShAre/trsi - XTC! - [-s/\l-1!/tRSi^zENITh] - ByteAndi/MST\n\n         I`m still looking for BetaTesters with MultiNode Systems\n     if you like to be one of them call @{" Marleys Coffee Shop "Link Marleys}\n\n                             @{" Main Menu "Link MAIN} @{" Exit "QUIT}\n\n@endnode\n\n@node Examp "Simply an example Output form MS-Comment v1.3"\n\n                      MS-Comment v1.3 by Dr.Dre!/TRSI\n.--.-------------------------------.----------------------------------------.\n|01| Dr.Dre!/tRZ                   | Dont disturb while smoking Joints      |\n|02| J.Walker                      | Console Cosysop & Nuker                |\n)--+-------------------------------+----------------------------------------(\n|03| McLoud/tRSi                   | tRSi World Leader                      |\n|04| NiCK                          | Amiga CoSysop & Nuker                  |\n|05| RiCHi                         | Amiga CoSysop & Nuker                  |\n|--^-----------------.-------------^----------------------.-----------------|\n| Sysop`s total : 05 | Default Sysop : Dr.Dre!/tRZ        | Time : 14:42:02 |\n`--------------------^------------------------------------^-----------------''\n\nChoose Sysop (1-5), (A)bort, (<-'') = Default Sysop >:\n\nlook`s nice ???\n\n                             @{" Main Menu "Link MAIN} @{" Exit "QUIT}\n\n@endnode\n\n@node Marleys "Marleys Coffee Shop - Home of the Dr.Dre! Tools/Doors"\n\n\n               * tRiStAR & RED sECtOR * gERmAN hEADqUARtER *\n                                           _______    ._____\n      _______  ____.______  ______________/   .  /____|    /_______\n      \      \/    |      \/   _  \      /   ___/_    l   /   __  /\n       \           |      \\   /  /_    /_________l____  /\__   \/\n        \    \/____l________\  \____|______|    |_______/________\\n         \____\         /______|                       _______\n                 ____          _______________________/   .  /\n                /  __l_. _____/     __/     __/   .  /   ___/_.\n               /   |   |/     \     _/\     _/   ___/_________|\n              /________|      \\____|  \____|_________|\n                       \_______/         _____        \n                      __________________/     \__________ \n                     /   __  /    /    /      \\    .   / \n                    /\__   \/         /\_______/    ___/  \n                   /________\   /____/-rS!/aRt/_____|\n                          /____/  \n\n                             @{" Main Menu "Link MAIN} @{" Exit "QUIT}\n@endnode\n\n@node board " TRSI Boards Worldwide"\n\n\n\n                 To Contact me Call any of this Boards...\n\n   biohazard......................Canadian HQ............+1-905-841-0965\n   cauldron.......................German   HQ............++49 Pure Elite\n   marleys coffee shop............German   HQ............++49 Pure Elite\n   MayDay.........................German   HQ............++49 Pure Elite\n   boondocks......................European HQ............+31-548-040-653\n   final impact...................Swedish  HQ............++46-54-113-486\n   flying spirits.................Swiss    HQ............+41-217-282-524\n   savage amusement...............Austria  HQ............+43-767-227-743\n   zEnlandia......................Finnish  HQ............+358-088-82-144\n\n\n                                                     @{" Main Menu " Link main}\n@endnode\n','\n',char(10)),NULL,'auto-added',20506,5,0,NULL,NULL,'trsi_c13','scan',1780048806);
INSERT INTO door_catalog VALUES('trsi_c16','TRSI-C16.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-C16.LHA','WORLD-CLOCK','XIM','WORLD-CLOCK',NULL,NULL,'TRSI','\      _______  \   _______)---------------. :\__/  \|  __/  /___   \|  \   SieGeL/tRSi : ¦  /    \  \    \   \   \   \ /X-iNNOVATiON¦',replace('___________________________\n\      _______  \   _______)---------------.\n:\__/  \|  __/  /___   \|  \   SieGeL/tRSi :\n¦  /    \  \    \   \   \   \ /X-iNNOVATiON¦\n| /______\__\____\______/____\  PRESENTS   |\n)--mRV-------------------------------------(\n|       W.O.R.L.D. - C.L.O.C.K. V1.16      |\n)------------------------------------------(\n|aDDED uSER-cONFIGURATION & aNIMATION-mODE!|\n)------------------------------------------(\n|dA bEST /X-cLOCK eVER wRITTEN! iNSTALL iT!|\n`------------------------------------------''\n','\n',char(10)),'WoRLD-CLOCK.GUIDE',replace('@database World-Clock V1.16 by SieGeL/TRSi (/X-iNNoVaTioN) BeRLiN-GeRMaNY\n\n@Remark $VER: V1.16 (Sunday 11-13-1994)\n\n@node Main "WoRLD-CLoCK V1.16 - /X uTiL WRiTTeN BY SieGeL/tRSi"\n@{b}\n         __________   ________     __________ ______                     \n      ___\\__      /___\\__     \\ ___\\__      //_____/   @{ub}   SieGeL/tRSi@{b}\n____ /     /_____//     /     //     /_____/______ __________________________\n     \\_    \\_    /     /     /_\\____     \\ /     /                      \n sYz  /     /   /   __/   __//     /     //     /    @{ub}(/X-iNNOVATiON) 1994@{b}\n____ /     /__ /    \\     \\ /    _/     //     /_____________________________\n    /_____/   /_____/_____//___________//_____/                               \n@{ub}\n                             iS pROUD tO pRESENT :\n\n                               wORLD-cLOCK V1.16\n \n     GFX BY: AMBLIN/dEZiGN / COUNT ZER0/SCL / aXe/MST / -rEDSKIN/aRT\n-----------------------------------------------------------------------------\n                             @{" INTRODUCTION " Link INTRO}\n                             @{" INSTALLATION " Link INSTALLATION}\n                             @{"  TOOL-TYPES  " Link TOOLTYPES}\n                             @{"  ARGS IN /X  " Link ARGS}\n                             @{"  GREETINGS!  " Link GREETS}\n@endnode\n\n@node INTRO "INTRODUCTION"\n\n                              iNTRODUCTION\n                              ~~~~~~~~~~~~\nWell, I know what you said now..."FUCK, ANOTHER CLOCK, BULLSHIT!"... yeah you\nare right if you think so, but I want to release this version coz this is the\nlast update I''ve made on this piece of coding. \n\nIn this Version I''ve built in a very @{b}comfortable User-Configurator@{ub} and a nice\n@{b}Animation-Mode@{ub}. The whole code is now rewritten in an Amiga-Specific way and\ngets therefor the most power from your System. The Time-Routines where changed\nand all time-parameters getting from the system will be translated in the \nlanguage you set in Locale-Prefs, so if you use your System in German, the \ndays will be translated,i.E. ''Thursday'' will be translated to ''Donnerstag''.\n\nIn fact of so many changings please take a look into the @{b}History-File@{ub} included\nin this archive for further details...let''s go on with @{"Installation" LINK INSTALLATION}...\n\n@endnode\n\n@node INSTALLATION "INSTALLATION OF WORLD-CLOCK V1.16"\n\n                       rEQUIREMENTS & iNSTALLATION\n                       ~~~~~~~~~~~~~~~~~~~~~~~~~~~\nOf course you need any Amigamodel (500-4000T) with Kickstart V37++ and a full\ninstalled and working Amiex (Should work under /X V2.xx, too).\n\nPut wORLD-cLOCK V1.16 and the icon wherever you want, but I recommend to \ncreate an Directory for wORLD-cLOCK, coz wORLD-cLOCK is now able to save the\nuser-preferences, and they will be saved in the dir wORLD-cLOCK is started\nfrom.\n\nIn difference to previous versions, wORLD-cLOCK needs *NO* icon anymore to\nwork correct. If you don''t put the Icon with it you only get no World-Clock,\ncoz the GMT-Timezone is missing and therefore no calculatings about the other\nCities time could be made.\n\nCopy the icon `T.info'' to your BBSCMD/ drawer and change the Location to the\npath where wORLD-cLOCK V1.16 could be found. That''s all. To configure the Clock\nto your needs take a look to the @{"Tooltypes" link TOOLTYPES}.\n\nNOTE : From now on every user is able to configure the clock to his own \n~~~~~~ needs, and therefore it''s not neccessary that you configure the \n       clock in the icon. If you configure it in the Tooltypes, this\n       configuration is only the default one which will be overwritten by the\n       user''s config.\n\n@endnode\n\n@node TOOLTYPES "ALL TOOLTYPES USED BY WORLD-CLOCK V1.16"\n\n                                tOOLTYPES\n                                ~~~~~~~~~\n\n LOCATION=<string>       = Here you could enter the Location of your city,\n                           i.e. Berlin-Germany. If you don''t want to enter\n                           a Location, put this Tooltype in Branches. The\n                           Clock writes then as Location the name of your BBS.\n                           \n GMT=<GMT-Time>          = Here you must define your GMT-Time (GMT=Greenwich-\n                           MeanTime). For Germany, it''s +1. If U don''t define\n                           this Tooltype, the WoRLD-CLoCK wouldn''t be shown,\n                           you only see the time from your board.\n\n LINE_ART=<char>         = If you want to seperate the Clock from the cities,\n                           you could enter here *one* char (i.e. -, +, =) and\n                           this char will be used to create two lines between\n                           the clock and the cities. If you don''t want to \n                           seperate it, put this Tooltype in branches or don''t \n                           define a char for it.\n\n CHARSET=<number>        = I''ve included four different styles for the clock.\n                           Here you could choose which one will be used to\n                           show the time. Only 0,1,2 and 3 are allowed as \n                           valid numbers. The numbers are defined as follow:\n\n                           0 = Digits from Amblin (Default!) \n                           1 = Digits from Axe\n                           2 = Digits from Count Zero\n                           3 = Digits from -redSkin\n                     \n                           To check out the digits, take a look to @{"DIGITS" Link Digits}.\n\nAll following ToolTypes are the defines for the colors. Valid colornumbers are\n30-37, which represents the ANSI-Colors in /X. I recommend not to use 30, as \nthis color is black and you won''t see very much if you enter it...:)\n\n MAIN_COLOR=<color>      = The color for the Title and the Lines between the\n                           clock and the cities. Default is 33 (yellow).\n\n CITY_COLOR=<color>      = The color for "TIME SHOWING FROM.." and the cities.\n                           Default is 36 (light blue).\n\n DIGITS_COLOR=<color>    = The color for the digits and the citytimes. Default\n                           is 35 (lila).\n\n DATELINE_COLOR=<color>  = The Color for the Dateline ( MM-DD-YY (DAY) ).\n                           Default is 34 (dark blue).\n@endnode\n\n@node ARGS "KNOWN ARGUMENTS GIVEN AT THE AMIEX-PROMPT"\n\n                               aRGUMENTS\n                               ~~~~~~~~~\n\nYou could start the clock in three different ways...\n\n1) Normal Start ''T''\n~~~~~~~~~~~~~~~~~~~\nThis is the easiest way to start the clock...the actual time(s) will be shown\nand the clock quits.\n\n\n2) Configuration ''T E''\n~~~~~~~~~~~~~~~~~~~~~~\nIf you start the clock in this mode, you get an optionsscreen which allows \nall users to configure their ''own'' clock-style. In Configuration-Mode the \nfollowing options are accessable:\n\n1,2,3,4 - Changes the Colors of the clock\n\n   5    - Allows you to change the seperator char\n\n   6    - Select the Digitstyle, available are four different ones. Take a\n          look to @{"DIGITS" Link DIGITS} for some examples.\n\n   7    - Select one of five different Date-Formats.\n\n   S    - Save current settings as default ones and display the clock in the\n          current settings.\n\n   P    - ''Preview'' of current settings..use this if you don''t know how the\n          current settings looks like...:)\n\n   A    - Use current Settings and start wORLD-cLOCK in Animation-Mode.\n\n   Q    - No saving and reset Settings to default.\n\n\n3) Animation ''T A''\n~~~~~~~~~~~~~~~~~~\nIn this mode wORLD-cLOCK starts with displaying the time(s), but in \ndifference to the normal mode the Local-System-Time will be updated every\nsecond and the World-Times will be updated every minute. To stop the anim\nsimply press CTRL-C to return to mainprompt.\n\n@endnode\n\n@node Digits "SOME EXAMPLES FOR THE DIGIT-STYLES"\n\n--------------------------- aMBLiN/DeZiGN -----------------------------------\n\n  .######.  .####   .######. .######. ###   .  ######## .######. ########\n  ###  ###  #####   ##   ### ###  ### ###  .#  ###      ###  ###    .####\n  ###  ###   ####        ###      ### ### .##  ###      ###        .####\n  ### .###   ####   .######    #####  ### ###  #######. #######.   #### \n  ### ####   ####   ###          .### ########     .### ### .###   ####\n  ### ####   ####   ### #### ### ####    ####  ### #### ### ####   ####\n  ### ####   ####   ### #### ### ####    ####  ### #### ### ####  .####.\n  `######'' ######## ######## `######''   ###### `######'' `######''  ######\n                                              \n------------------------------ aXe/MYSTiC -----------------------------------\n\n  .######.  .###### #######. #######. ###  ### ######## .####### #######.\n  ######## .####### ######## ######## ###  ### ######## ######## ########\n  ###  ### ###''####    .####      ### ###  ### ###      ###           ###\n  ### ####     ####  .#####''   ###### ######## #######. #######.   ######\n  **** ***     **** .*****''    ****** `******* ******** ********   ******\n  ***  ***     **** ****''         ***      ***      *** ***  ***      *** \n  ***  ***     **** ******** ********      *** ******** ********      ***  \n  `******''     **** `******* *******''      *** *******'' `******''      ***\n\n-------------------------- CouNT ZeRo/SCaNDaL! ------------------------------\n\n.:::::::. :::::.    :::::.    :::::. ::::      ::::::    .:::::    .::::::::\n:::: ....   ....      ....      .... :::: .... ::::      ::::      :::: ....\n:::: ::::   :::: .:::::::·     ::::· ·:::::::: ::::::::. ::::::::.      ::::\n:::: ::::   :::: :::: .... :::: ::::      :::: .... :::: :::: ::::      ::::\n·:::::::·   :::: ·:::::::: ·:::::::·      :::: ·:::::::· ·:::::::·      ::::\n\n------------------------------ -redSkin/aRT ---------------------------------\n\n .......  .......    .....    .....   ... ...  .....    .....   ....... \n:::: :::    :::::: .....:::     .::: :::: ::: ::::...  ::::....  .::::::\n:::: :::    :::::: :::: ... .... ::: :::: ::: .... ::: :::: :::   ::::::\n:::: :::    :::::: :::: ::: :::: ::: :::: ::: :::: ::: :::: :::   ::::::\n:::: :::    :::::: :::: ::: :::: ::: :::: ::: :::: ::: :::: :::   ::::::\n:::: :::    :::::: :::: ::: :::: ::: ::::.::: :::: ::: :::: :::   ::::::\n:::: :::    :::::: :::: ::: :::: :::      ::: :::: ::: :::: :::   ::::::\n   `-''                `-''      `-''               `-''      `-''\n\n@endnode\n\n@node GREETS ".....THE AMAZING GREETINGS......"\n\naMBLiN/DeZiGN   - THX for the fast work. Personally my favourite digits...:)\n\naXe/MYSTiC      - CeWL digits Dude. Hope to see yar one time again..\n\nCount Zero/SCL  - Great paintings dude..should i write sTYLEz ? :)\n\n-redSkin/aRT    - Very cewl digits, hope to get a BBSTitle from U soon..:)\n\nByteAndi/tRSi   - Thx for your help...\n\nSpy/tRSi        - For givin'' me some useful tips...(Listen suxx..:))))\n\nDr.Dre/tRSi     - Very cewl weekend ..:) C ya in Berlin next time..hehe\n\nDelta-X/tRSi    - Welcome to @{"(/X-iNNOVATiON)" Link TRSIMEMBER} ...hope U enjoy it..\n\naRGoN/dTL       - THX 4 support and testing on my @{"BBS" Link BBSADVERT}..\n\ndEATH aNGEL/SDC - You''re my best Beta-Tester !! \n\n         and of course all tRSi-mEMBAS and all my users on my @{"BBS" Link BBSADVERT}\n\n-----------------------------------------------------------------------------\nMusical Support: Clawfinger, Death, Sepultura, Pink Floyd, Metallica\n\nTechnical Supp.: A4000/030, Ced V3.5, SAS-C V6.50\n-----------------------------------------------------------------------------\n\n@endnode\n\n@node TRSIMEMBER "TRSI (/X-iNNOVATiON)"\n\n                   ._________________  ______\n                   l___       /      \\/    _/_______.:  \n                     /       /   /  _/\\___      /    :\n                    /_______/-rS!\\_____\\  _____/     |''94  \n                          /_______|     \\/   /_______|\n                       (/X-iNNOVATiON) Members are:\n                    ----------------------------------\n                       Dr.Dre!/tRSi (/X-iNNOVATiON)\n                       ByteAndi/tRSi (/X-iNNOVATiON)\n                        SieGeL/tRSi (/X-iNNOVATiON)\n                         Spy/tRSi (/X-iNNOVATiON)\n                       Delta-X/tRSi (/X-iNNOVATiON)\n                    ----------------------------------\n               if you wanna join us so get in touch with : \n\n                       Dr.Dre!/tRSi or ByteAndi/tRSi\n\nIf you want to order a tool, give us Bugreports,hints and tips for this or \n\nother tools comin'' from (/X-iNNOVATiON), try to contact us on any TRSI Board\n\nWorldWide or try to contact my Board @{"PUNISHMENT INC." Link BBSADVERT}...\n\n@endnode\n\n@node BBSADVERT "HOW TO CONTACT SieGeL/tRSi"\n@{b}\n      ______    ___ ____   ___ ______    ___ _______   ______ ____   ______\n     _\\_   /___/  /_\\_  \\ /  /_\\_   /___/  /_\\_  _  \\ _\\_   /_\\_  \\ _\\_   /\n    /  /  //  /  //  /  //  //  /__//  /  //  /  /  //  /__//  /  //  /__/ \n   /  /  //  /  //  /  //  /_\\_  \\ /  /  //  /  /  //  _/_ /  /  / \\_ \\_   \n  / _/  //  /  //  /  //  //  /  //__/  //  /  /  //  /  //  /  /   /  /   \n / ____//  /  //  /  //__//  /  // \\   //  /  /  //  /  //  /  /   /  /    \n/__/    \\____//__/__/___ /_____//__/__//__/__/__/ \\____//__/__/   /__/     \n                    /__/____   ______              ___ _ . _               \n@{ub}+49(0)30 ELI-TE-!!@{b} ___ _\\_  \\ _\\_   /             |___|_|||_|(             \n                  /  //  /  //  /__/       __/\\______/.---.\\___._/\\        \n  __ _  _   _    /  //  /  //  /__  _  ____\\    ||||| `---'' \\__|   \\__     \n (___ _  _   _  /  //  /  //  /  /___  \\___|\\  _____.----._____|_    /     \n               /  //  /  //  /  //  /       ¯\\/`····|    |()) (_ \\__/      \n              /__//__/__/ \\____//__/               <|    |¯¯)  /           \n                                                    |    |  ¯\\/sYz         \n         @{ub}tRSi (/X-iNNOVATiON) dIST sITE gERMANY     @{b}`----''\n\n          @{ub}sYSOP-cRU iS SieGeL/tRSi & aRGON/dTL\n@endnode\n','\n',char(10)),'{"LOCATION":"<string>"}','auto-added',51250,6,0,NULL,NULL,'trsi_c16','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_c21','TRSI-C21.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-C21.LHA','dRE!COMMENt','XIM','/\__',NULL,NULL,'TRSI','_____/___/_____/\___________ .__________   // __________/---------------. |  /   /  / _/\____  \/   /dR.dRE! Of tRSi |',replace('      /\__\n_____/___/_____/\___________\n.__________   // __________/---------------.\n|  /   /  / _/\____  \/   /dR.dRE! Of tRSi |\n| /  //__/   \ ______/  //  /X iNNOVAtION  |\n|/__ /   \____\/-Mo!/__ /     PRESENtS     |\n`--\/-----------------\/-------------------''\n  *** dRE!COMMENt v2.1 PUBliC RElEASE ***\nbESt MUltiSYSOP COMMENt dOOR YOU EVER SEEN!\nfULL CRSR KEY SUPPORT, NO ICON SETUP YOU CAN\nADD/EDIT/REMOVE ALL SYSOPS ONLINE, MANY MORE\n    *** COMMODORE INSTALLER SUPPORT ***\n','\n',char(10)),'dRE!COMMENt.GUidE',replace('@database dRE!COMMENt\n@$VER: dRE!COMMENT v2.1\n@author "DR.DRE!/tRSi"\n@(c) "dR.dRE!/tRSi (tRSi /X·iNNOVAtiON)"\n@remark Created with Heddley v1.1 (c) Edd Dumbill 1994\n\n@node "Main" "CONtENtS Of tHiS GUidEfilE"\n@{fg highlight}                     /\\__\n               _____/___/_____/\\___________\n               @{fg fill}.@{fg highlight}__________   /@{fg text}/@{fg highlight} __________/@{fg fill}---------------.@{fg highlight}\n               @{fg fill}|@{fg highlight}  /   /  / _/\\____  \\/   /    @{fg text} tRSi  @{fg fill}     |@{fg highlight}\n               @{fg fill}|@{fg highlight} /  @{fg text}/@{fg highlight}/__/   \\ ______/  @{fg text}/@{fg highlight}/       @{fg text}/X@{fg fill}        |@{fg highlight}\n               @{fg fill}|@{fg highlight}/__ /   \\____\\/@{fg fill}-Mo!@{fg highlight}/__ /    @{fg text}iNNOVAtiON!@{fg fill}   |@{fg highlight}\n               @{fg fill}`--@{fg highlight}\\/@{fg fill}-----------------@{fg highlight}\\/@{fg fill}-------------------''@{fg text}\n\n                    @{fg highlight}iS pROUd tO pRESENt@{fg text}: @{fg fill}dRE!COMMENt v2.1@{fg text}\n                       @{"         iNtROdUCtiON         " link "Document_1" 0}          \n                       @{"         iNStAllAtiON         " link "Document_2" 0}           \n                       @{"  WHAt iS NEW ON dRE!COMMENt  " link "Document_3" 0}      \n                       @{"       MAiN MENU OPtiONS      " link "Document_4" 0}                     \n                       @{"      SYSOP  MENU OPtiONS     " link "Document_5" 0}                     \n                       @{"            CREDITS           " link "Document_6" 0}                  \n                       @{"           GREETINGS          " link "Document_7" 0}        \n                       @{"     (tRSi /X·iNNOVAtiON)     " link "Document_8" 0}         \n                       @{"      REGiStER dRE!tOOlS      " link "Document_9" 0}\n                       @{"   OthER dRE!tOOlS / dOORS    " link "Document_0" 0}\n                       @{"      DiStRiBUtiON SitE       " link "DistSite" 0}\n@endnode\n\n@node "Document_1" "         iNtROdUCtiON         "\n The Features of dRE!COMMENt v2.1\n --------------------------------\n\ndRE!COMMENt alowes you to handle as many Sysops as you want.\ndRE!COMMENt is full Cursor controlled (UP/DOWN/LEFT/RIGHT)\ndRE!COMMENt is able to add/edit/remove Sysops online, no Icon Setup !!!\ndRE!COMMENt works only in Memory for highest Performance\ndRE!COMMENt is able to configure your own Colours in the Mask\n            (in DOORS:DRE/DRE!COMENT/EDITOR.MASK) a raw Mask is included.\n            NOTE: THE MAIN MASK COLOUR MUST BE DARK BLUE !!!\ndRE!COMMENt is able to handle a default Sysop, that means that not the\n            BBS Main Sysop is the Default Sysop, you can set any other\n            Sysop as Defaut. (Usefull if you are on Holiday)\ndRE!COMMENt records all written Messages to the different Sysops, so\n            that you allways can see, which Sysop got the most Mails.\n\n@endnode\n\n@node "Document_2" "         iNStAllAtiON         "\n\n@endnode\n\n@node "Document_3" "  WHAt iS NEW IN dRE!COMMENt  "\n\nWHAt iS NEW IN dRE!COMMENt\n--------------------------\n\n1) Online Add/Edit/Remove for all Sysops.\n2) Full Cursor Control.\n3) Recording of all Mails written to the different Sysops.\n4) build in SysopEditor.\n5) External Configurable Editor Mask.\n6) A DataFile is replaced for the Icon Routine , \n   this allows you to edit all Options online.\n\n@endnode\n\n@node "Document_4" "       MAiN MENU OPtiONS      "\n\n\n.----.----------------------------.------------------------------------.-----.\n| NR | SYSOP NAME / HANdlE        | SYSOP fUNCtiON / dESCRiPtiON       |MAilS|\n|----+----------------------------+------------------------------------+-----|\n|@{" 01 " link "Main_Menu.1" 0}| DR.DRE!/TRSI               | MAStER SYSOP                       |00000|\n| 02 | BYtEANDi/tRSi              | coder                              |00002|\n|----+----------------------------+------------------------------------^-----|\n|@{" D) " link "Main_Menu.2" 0}| Default Sysop              | Write to default Sysop                   |\n|@{"[C)]" link "Document_5" 0}| SysopEditor                | For Sysops only                          |\n|@{" A) " link "Main_Menu.3" 0}| Abort                      | Exit dRE!COMMENt v2.10                   |\n|----^----------------------------+---------------------------.--------------|\n|@{"Default:" link "Main_Menu.4" 0} [DR.DRE!/TRSI          ]|@{"Cnf:" link "Main_Menu.5" 0} tESt aREa             |tiME 11:27:34 |\n|---------------------------------^---------------------------^--------------|\n| dRE!COMMENt v2.10ß - @{"REGiStEREd VERSiON" link "Document_9" 0} - (C) dR.dRE! (tRSi /X·iNNOVAtiON) |\n`----------------------------------------------------------------------------''\n            ***  MOVE CRSR UP/DOWN - PRESS RETURN TO SELECT  ***\n\n@endnode\n\n@node "Document_5" "      SYSOP  MENU OPtiONS     "\n\n.----------------------------------------------------------------------------.\n| SYSOPEditOR fOR dRE!COMMENt v2.1 by dR.dRE! of (tRSi /X iNNOVATiON) - 1994 |\n|--------------.---------------------.-------------------.-------------------|\n| SYSOP # [01] | DEFAUlt SYSOP [YES] | MAiLStAtS [00012] | tiME: [11:36:05]  |\n|-----.--------^----.----------------^-------------------^-------------------|\n| CMd | ACtiON      | StAtUS                                                 |\n|-----+-------------+--------------------------------------------------------|\n|@{" [1] " link "Sysop_Menu.1"}| NAME        | [DR.DRE!/TRSI              ]                           |\n|@{"  2  " link "Sysop_Menu.2"}| fUNCtiON    | [tRSi (/X·iNNOVAtiON) lEAdER       ]                   |\n|@{"  3  " link "Sysop_Menu.3"}| ANSWER MSG  | [tHNX fOR lEAViNG MAil...          ]                   |\n|@{"  4  " link "Sysop_Menu.4"}| DEF. SYSOP  | [YES]                                                  |\n|@{"  5  " link "Sysop_Menu.5"}| MAilStAtS   | [00012]                                                |\n|-----^-------------^--------------------------------------------------------|\n| @{"[1-5]" link "Sysop_Menu.6"}=OPtiON,  @{"+/-" link "Sysop_Menu.7"} =SCROll, @{" A " link "Sysop_Menu.8" 0}=ABORT, @{" S " link "Sysop_Menu.9" 0}=SAVE, @{" D " link "Sysop_Menu.10" 0}=DELETE, @{" N " link "Sysop_Menu.11" 0}=ADD SYSOP |\n`----------------------------------------------------------------------------''\n    *** (CRSR UP/DOWN) / (LEFt/RiGHt)=CHOOSE OPTION - (RETURN)=SELECT *** \n\n     @{fg highlight}NOTE: !!! DONT FORGET TO SAVE EACH SYSOP AFTER CHANGING ANY OPTION !!!@{fg text}\n\n@endnode\n\n@node "Document_6" "            CREDITS           "\n\n                             NOtEABlE CREDitS\n                             ----------------\n\n      dRE!COMMENt v2.1 WAS WRittEN bY dR.dRE! oF (tRSi /X·iNNOVAtiON)\n\n     tHE AMiGAGUidEFilE WAS WRittEN bY dR.dRE! oF (tRSi /X·iNNOVAtiON)\n\n             tHE AMiGAGUidEfilE WAS CREAtEd WitH HEddlEY v1.1\n                          (c) bY Edd Dumbill 1994\n\n@endnode\n\n@node "Document_7" "           GREETINGS          "\n\n                            SOME FAST GREETINGS\n                          - ------------------- -\n                               TO THIS DUDES\n\n   [·] MCLOUD/TRSI [·] MARIO [·] ECS [·] SIEGEL [·] BYTEANDI [·] SPY [·]\n    [·] VALSHARE [·] REDSKIN! [·] EMPIRE/MST [·] RICHI/FLT [·] NICK [·]\n    [·] SAL-1/TRSI [·] TRITON [·] VAMPIRE/PDY [·] XTREME [·] BJOERN [·]\n     [·] LINEBACKER [·] BLOODWOLF [·] JUAN/TRSI [·] BLIND GUARDIAN [·]\n\n          ... all i forgot and of course all registered Users...\n\n\n@endnode\n\n@node "Document_8" "     (tRSi /X·iNNOVAtiON)     "\n\n               (tRSi /X·iNNOVAtiON) ARE tHE fOllOWiNG dUdES\n\n                               dR.dRE!/tRSi\n                               bYTEANdi/tRSi\n                                SiEGEl/tRSi\n                                 SPY/tRSi\n\n      If you wanna join us just get in touch with one of the Dudes above.\n\n@endnode\n\n@node "Document_9" "      REGiStER dRE!tOOlS"\n\n\n                            REGISTER DRE!DOORS\n                          - ------------------ -\n\nTHE REGISTRATION FEE IS 2O$ ONLY. IF YOU THINK PHEW! QUITE A LOT OF MONEY, READ\nWHAT YOU WILL GET FOR YOUR MONEY.\n\n1. YOU WANNA BE \n   SURE THAT YOU`LL GET ONLY DOORS WITHOUT ANY BACKDOOR ? \n   OF COURSE THE REGISTERED USER(S) WILL GET ONLY PRIVATE VERSIONS \n   ALL PUBLIC VERSIONS HAVE A TIMELIMIT OR I REMOVED SOME MENU OPTIONS\n   ONLY!!! THE REG.USERS WILL GET THE FULL VERSION.\n\n2. YOU FOUND A BUG ? -> REPORT IT TO ME AND YOU`LL GET A FIXED VERSION SOON \n   NO NEED TO WAIT FOR A NEWER RELEASE VERSION.\n\n3. YOU HAVE SOME GOOD IMPROVEMENTS, TALK TO ME, AND I WILL SEE IF I CAN\n   REALISE IT.\n\n4. YOU NEED A PRIVATE DOOR ONLY FOR YOUR BBS, I WILL CODE IT !\n\n5. PRIVATE SUPPORT CONFERENCE IN A FUCKEN FAST TRSI BOARD IN NETHERLAND.\n   NEW DISTRIBUTION SITE IN GERMANY ALSO AVAILABLE.\n\n6. ALL DOORS/UTILS ARE INCLUDING YOUR REGISTER STRING.\n\n7. YOU`LL GET ALL LATER VERSIONS OR NEW DOORS FOR THE ABOVE PRICE.\n\n                  SIMPLY YOU`LL GET THE BEST SUPPORT AROUND.\n              THINK ABOUT AND KEEP THE PROGRAMMERS PROGRAMMING !!!\n\nIF YOU ARE INTERESTED  CONTACT ME AT ANY TRSI BOARD OR SIMPLY AT THE\ntRSi EHQ - bOONdOCkS OR AT tRSi GHQ SPiRitS Of SOUl\n\n\n@endnode\n\n@node "Main_Menu.1" "Choose Sysop"\n\nMENU OPtiON ChOOSE SYSOP\n------------------------\n\nHere you can select the Sysop you wanna write to.\nChoose it via CRSR UP/DOWN or press the Sysop Number.\nActivate with RETURN.\n\n@endnode\n\n@node "Main_Menu.2" " Choose Default Sysop"\n\nHere you can write to the Default Sysop, which Is setted up \nin the Sysopdata as Default Sysop.\nChoose via CRSR UP/DOWN or press the `d` Key.\nActivate with RETURN.\n\n@endnode\n\n@node "Main_Menu.3" "Exit dRE!COMMENt v2.1"\n\nThis Options will explain itself.\nChoose with CRSR UP/DOWN.\nActivate with RETURN.\n\n@endnode\n\n@node "Main_Menu.4" "Default Sysop"\n\nHere you can see which Sysop is the Default Sysop.\nChange them in the Sysop Editor Option @{"Add/Change Default Sysop" link "Sysop_menu.4"}.\n\n@endnode\n\n@node "Main_Menu.5" "Actual Conference"\n\nHere you can see the current Conference you are in.\n\n@endnode\n\n@node "Sysop_Menu.1" "Choose / Change SysopName"\n\n\nHere you can Add/Change the actual Sysop Name.\nSet the CRSR on Position @{"1-5 =OPtiON" link "Sysop_menu.6"} and choose via the\nCRSR UP/DOWN or press Key `1` for Position Number 1.\nActivate with Return.\n\nNow you enter the SysopName (WildCards DR.#? or *DRE#?t*i are allowed),\ndRE!COMMENt will search the AE User.Keys for existing Name, if found it\nwill set the choosen Name to NewSysop Data, if not it will notify \nthat it can`t locate any User with this Name.\n\n@{fg highlight}NOTE: !!! DONT FORGET TO SAVE EACH SYSOP AFTER CHANGING ANY OPTION !!!@{fg text}\n\n@endnode\n\n@node "Sysop_Menu.2" "Add / Change Sysop Function"\n\n\nHere you can Add / Change the Sysop Function displayed in the Sysopmenu.\nSet the CRSR on Position @{"1-5 =OPtiON" link "Sysop_menu.6"} and choose via the\nCRSR UP/DOWN or press key `2` for Position Number 2.\nActivate with Return.\nNow enter the new function.\n\n@{fg highlight}NOTE: !!! DONT FORGET TO SAVE EACH SYSOP AFTER CHANGING ANY OPTION !!!@{fg text}\n\n@endnode\n\n@node "Sysop_Menu.3" "Add / Change Sysops Answerline"\n\n\nHere you can Add / Change the Answerline for the different Sysops, displayed\nif the Sysop is choosen.\nSet the CRSR on Position @{"1-5 =OPtiON" link "Sysop_menu.6"} and choose via the\nCRSR UP/DOWN or press key `3` for Position Number 3.\nActivate with Return.\nEnter the new Answer Line.\n\n@{fg highlight}NOTE: !!! DONT FORGET TO SAVE EACH SYSOP AFTER CHANGING ANY OPTION !!!@{fg text}\n\n@endnode\n\n@node "Sysop_Menu.4" "Add / Change Default Sysop"\n\n\nHere you can change the Default Sysop.\nSet the CRSR on Position @{"1-5 =OPtiON" link "Sysop_menu.6"} and choose via the\nCRSR UP/DOWN or press key `4` for Position Number 4.\nActivate with Return.\n\nNOTE: Before you change the Default Sysop, you have to set the old default\n      Sysop to NO!, then you can set the new default Sysop.\n      THERE IS ONLY ONE DEFAULT SYSOP ALLOWED.\n\n@{fg highlight}NOTE: !!! DONT FORGET TO SAVE EACH SYSOP AFTER CHANGING ANY OPTION !!!@{fg text}\n\n@endnode\n\n@node "Sysop_Menu.5" "Reset / Change Sysop MailsStats"\n\nHere you can Add / Reset / Change the Mailstats for the different Sysops,\ndisplayed in the Main Sysop Menu.\n\nSet the CRSR on Position @{"1-5 =OPtiON" link "Sysop_menu.6"} and choose via the\nCRSR UP/DOWN or press key `5` for Position Number 5.\nActivate with Return.\nEnter the new Mailstats ( 0=RESET ).\n\n@{fg highlight}NOTE: !!! DONT FORGET TO SAVE EACH SYSOP AFTER CHANGING ANY OPTION !!!@{fg text}\n\n@endnode\n\n@node "Sysop_Menu.6" "Edit Options"\n\nSet the Cursor to this Position to edit the different Sysop Options (1-5).\nYou can choose the Options via CRSR UP/DOWN or press the specific\nOption Key.\nYou can jump to the Options Position via CRSR LEFT/RIGHT or press\nthe KEY `o`, the Shortkey is shown in pink colour\n\n@endnode\n\n@node "Sysop_Menu.7" "Scroll SysopData Forward/Backward"\n\nHere you can scroll all available Sysops in your SysopData.\nYou can choose this Option only via CRSR LEFT/RIGHT there is no Hotkey\ndefined for this Option\nIf you have selected them scroll the Sysops via CRSR UP/DOWN, if you want\nedit a Sysop, choose it with the scroll option, then place the\nCursor to the @{"1-5 =OPtiON" link "Sysop_menu.6"} and edit the Sysop.\n\n@{fg highlight}NOTE: !!! DONT FORGET TO SAVE EACH SYSOP AFTER CHANGING ANY OPTION !!!@{fg text}\n\n@endnode\n\n@node "Sysop_Menu.8" "Abort Sysop Editor"\n\n\nQuit the Sysop Editor.\nChoose this Option via CRSR LEFT/RIGHT or press the `a` KEY.\n\n!!! @{fg highlight} SAVE THE CHANGES BEFORE QUITTING THE EDITOR. @{df text} !!!\n\n\n@endnode\n\n@node "Sysop_Menu.9" "Save New / Changed Sysop"\n\n\nHere you can SAVE the changed or new added Sysop(s).\nDo this after changed/added any Sysop.\nThis means add / edit all Options and SAVE first before you add/edit\nanother Sysop !!! Otherwise all changed Datas are lost btw: resetted to the\nold Status.\nChoose this Option via CRSR LEFT/RIGHT or press the `S` KEY.\n@endnode\n\n@node "Sysop_Menu.10" "Delete Sysop"\n\n\nHere you can remove a Sysop from the Sysopdata.\nChoose the Sysop you like to remove with the @{"+/- =SCROLL" link "Sysop_Menu.7"} Option,\nscroll to the Sysop you wish to remove and Delete him.\nChoose this Option via CRSR LEFT/RIGHT or press the `D` KEY.\n\n@endnode\n\n@node "Sysop_Menu.11" "Add New Sysop to Datas"\n\n\nThis Option allows you to add a new Sysop to the SysopDatas.\nIf you choose it via CRSR LEFT/RIGHT or press `N` a cleared Mask\nwill be displayed. Place the Cursor on the @{"1-5 =OPtiON" link "Sysop_menu.6"} and add\nall new SysopFunctions like Name ect.\n\nNOTE: !!! @{fg highlight}DONT FORGET TO SAVE THE NEW SYSOP BEFORE YOU QUIT \n          OR CHOOSE OTHER OPTIONS@{fg text} !!!\n\n@endnode\n\n@node "Document_0" "Other dRE!tOOlS / dOORS"\n\n                           OTHER DRE!DOORS/TOOLS\n                         - --------------------- -\n\n NAME                  TYPE   VERSION\n---------------------+------+--------------------------------------------- \nDRE!WHO              | XiM  |  V1.1  PUBLIC \nDRE!FRONT            | XiM  |  V1.O  PUBLIC \nCHAT!ACCESS          | XiM  |  v1.2  PUBLIC \nDRE!COMMENT          | XiM  |  V2.1  PUBLIC & PRiVATE RELEASE FOR REG. USERS\nONLY DOORMENU        | XiM  |  v1.o  PUBLIC \nDRE!WALL             | XiM  |  v1.2  PRiVATE RELEASE FOR REG. USERS ONLY \nFAST!DUPE            | XiM  |  v1.11 PRIVATE COOP DR.DRE!^BYTEANDI\nMOST WANTED          | XiM  |  v1.52 PRiVATE RELEASE FOR REG. USERS ONLY \nLHA CHEKKO           | DOS  |  RENAMED INTO DRE!CHECK SINCE V2.1 \nSPEEDADD(TXT)        | DOS  |  RENAMED INTO DRE!ADD v1.0 REG. ONLY \nSPEEDZIP (ZIP)       | DOS  |  v1.o  BETA \nBULL!VIEW            | XiM  |  v1.02 PUPLIC \nLAST!JUNKZ           | AiM  |  v1.0  PRIVATE RELEASE FOR REG. USERS ONLY \nPWFAILURE            | XiM  |  v1.1  PUPLIC \nBETA!REPORT          | XiM  |  v0.92 BETATESTER(S) ONLY\nDRE!NODECHECK        | XiM  |  c0.ß  PUBLIC \nDRE!SENDLIST         | XiM  |  v1.2  PUBLIC \nNUP^SYSPW COMMENTER  | XiM  |  v1.2  PUBLIC \nNEWUSER SCRIPT       | XiM  |  v1.21 PUBLIC\nGLOBAL USER STATUS   | XiM  |  v1.9  PUBLIC \nSPEEDLIST (USERLIST) | XiM  |  v1.ß  PRIVATE RELEASE FOR REG. USERS ONLY\nDESCRIPTION!SNAP     | AiM  |  v1.o  PUPLIC \ndRE!CARD             | XiM  |  v2.1  BETA (PRIVATE^PUBLIC VERSION SOON)\nDRE!ADVERTISE        | XiM  |  v2.o  PRIVATE RELEASE FOR REG. USERS ONLY \nDRE!SENt             | XiM  |  v0.7  PRIVATE RELEASE FOR REG. USERS ONLY\nDRE!FREE             | XiM  |  v0.3  PRIVATE RELEASE FOR REG. USERS ONLY\nDRE!CHECK            | DOS  |  v2.2  PRIVATE RELEASE FOR REG. USERS ONLY\nDRE!REPORT           | XiM  |  v1.21 PRIVATE & PUBLIC PROTECTED RELEASE\n---------------------+------+---------------------------------------------\n\nTHERE ARE ALSO SOME OLDER (AiM) DOORS AVAILABLE WICH I CAN`T REMEMBER WHAT\nIT WAS  EXACTLY ...  JUST SEARCH FOR DR.DRE! \nIF YOU LIKE MY DOORS/UTILS THEN @{"REGISTER" link "Document_9" 0} IT PLEASE.\n!!! KEEP THE PROGRAMMERS PROGRAMMING !!!\n\n@endnode\n\n@node "DistSite" "DiStRiBUtiON SitE"\n\n\n  thE NEW GERMAN Distribution Site is the '' SPiRitS Of SOUl - tRSi GhQ ''\n                 The bOONdOCkS StAYS ANYWAY WORld diStSitE\n                   GEt thE NUMbERS fROM ANY tRSi MEMbER!\n         All Old REGiStEREd ACCOUNtS ARE StiLL AliVE iN BOth bbS`s\n\n    tHIS MESSAGE iS ESPECiAllY fOR JAkE & jUAN, PlEASE CAll tHE SPiRitS\n                  tO GEt YOUR PRiVATE VERSiONS tHERE !!!\n\n@endnode\n','\n',char(10)),NULL,NULL,45379,5,0,NULL,NULL,'trsi_c21_dre_comment','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_c24','TRSI-C24.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-C24.LHA','dRE!ChECk','XIM','Istrip',NULL,NULL,'TRSI','_____/___/_____/\___________ .__________   // __________/---------------. |  /   /  / _/\____  \/   /dR.dRE! Of tRSi |',replace('      /\__\n_____/___/_____/\___________\n.__________   // __________/---------------.\n|  /   /  / _/\____  \/   /dR.dRE! Of tRSi |\n| /  //__/   \ ______/  //  /X iNNOVAtiON  |\n|/__ /   \____\/-Mo!/__ /     PRESENtS     |\n`--\/-----------------\/-------------------''\ndRE!ChECk v2.4 (UNREGiStEREd PUbliC VERSiON)\n SiMPlY! tHE bESt ADDER/CHECKER/STRIPER fOR\n  LHA/LZH/LZA/SFX ARCHiVE, CYCliNG ADVERtS\n       SUPPORtS iStRiP, ANd MANY MORE\n    COMPlEtE COMMOdORE iNStAllER SUPPORT\n','\n',char(10)),'dRE!ChECk.ENG.GUidE',replace('@database dRE!ChECk\n@$VER: dRE!ChECk v2.4\n@author "DR.DRE!/tRSi"\n@(c) "dR.dRE!/tRSi (tRSi /X·iNNOVAtiON)"\n@remark Created with Heddley v1.1 (c) Edd Dumbill 1994\n\n@node "Main" "Contents of this Guidefile"\n@{fg highlight}                     /\\__\n               _____/___/_____/\\___________\n               @{fg fill}.@{fg highlight}__________   /@{fg text}/@{fg highlight} __________/@{fg fill}---------------.@{fg highlight}\n               @{fg fill}|@{fg highlight}  /   /  / _/\\____  \\/   /    @{fg text} tRSi  @{fg fill}     |@{fg highlight}\n               @{fg fill}|@{fg highlight} /  @{fg text}/@{fg highlight}/__/   \\ ______/  @{fg text}/@{fg highlight}/       @{fg text}/X@{fg fill}        |@{fg highlight}\n               @{fg fill}|@{fg highlight}/__ /   \\____\\/@{fg fill}-Mo!@{fg highlight}/__ /    @{fg text}iNNOVAtiON!@{fg fill}   |@{fg highlight}\n               @{fg fill}`--@{fg highlight}\\/@{fg fill}-----------------@{fg highlight}\\/@{fg fill}-------------------''@{fg text}\n                  @{fg highlight}iS pROUd tO pRESENt @{fg text}: @{fg fill}dRE!ChECk v2.4@{fg text}\n\n                   @{"  iNtROdUCtiON ON dRE!CHECk v2.4  " link "Document_0" 0}\n                   @{"          HOW tO iNStAll          " link "Document_1" 0}\n                   @{"           WhAt iS NEW            " link "Document_2" 0}\n                   @{"       HOW tO Add ANd StRiP       " link "Document_10" 0}\n                   @{"        MOdifY tHE AdVERt!        " link "Document_3" 0}\n                   @{"        MODiFYAbLE OPtiONS        " link "Document_4" 0}\n                   @{"              CREditS             " link "Document_5" 0}\n                   @{"             GREEtiNGS            " link "Document_6" 0}\n                   @{"       (tRSi /X·iNNOVAtiON)       " link "Document_7" 0}\n                   @{"        REGiStER dRE!tOOlS        " link "Document_8" 0}\n                   @{"      OthER dRE! tOOlS/dOORS      " link "Document_9" 0}\n\n  @{fg highlight} NOTE: THIS IS A UNREGISTERED VERSION, AND I REMOVED THE TEST OPTION@{fg text}\n@endnode\n\n@node "Document_0" "iNtROdUCtiON ON dRE!CHECk v2.4"\n\n                       Some hints of dRE!ChECk v2.4\n                       ----------------------------\n\nHints: Long time ago i start to write the first Version of dRE!ChECk,\n       for sure at this time dRE!CHECk was already the fastest and \n       powerfullest ADDER/STRIPER/CHECKER ... but now the new Version\n       will kick really asses ...\n\n1) If you build in this checker !!! NO ONE !!! will be able to remove your\n   Adverts, coz i use i special cycling routine and you never will add a\n   addi with the same Name. Your advert has a lenght of 8 chars, now \n   calculate 8 x 8 x 8 x 8 x 8 x 8 x 8 x 8 = 134,217,728 possibillitys to\n   add...\n   This means your BBS has to receive 134,217,728 Lha-Files to add one time\n   the same Advert !!!\n\n2) Now adding Uploader Name,Location,Node,Date,Time on any Place\n   you wish in your Advert. View @{"MOdifY tHE AdVERt" link "Document_4" 0}\n\n3) All Functions are optional.\n\n4) Best optimized Code for fastest Access.\n\n5) possible to make dRE!ChECk resident.\n\n6) New Design looks now still better as before ...\n\n  @{fg highlight} NOTE: THIS IS A UNREGISTERED VERSION, AND I REMOVED THE TEST OPTION@{fg text}\n\n  This Program is a public Version and can may be freely distributed for\n  non-commercial purposes, as long as all the files in the original\n  archive are present and have not been modified in any way.\n  If you want to register all my Doors/Tools so view @{"REGiStER dRE!tOOlS" link "Document_8" 0}\n\n   If you like a program so please buy it, keep the Programers Programing.\n\n@endnode\n\n@node	"Document_1" "HOW tO iNStAll"\n\n                   How to Install dRE!ChECk v2.4\n                   -----------------------------\n\nAfter unpacking the Archive TRSI-DC2.LHA, make a double Click on the\nInstall Icon, and follow the Instructions of the Installer.\n\n(Needs the Commodore Installer (C) by Commodore in any accessbale Path)\n\n\n                   How to Install without the Installer\n                   ------------------------------------\n\nCopy the whole directory dRE!ChECk to any Path, and add this Line to\nyour User-Startup or BBS-Startup.\n\n@{fg highlight}---------------Cut here-------------@{fg text}\nASSIGN dRE!ChECk: <YOUR PATH> >NIL:\n@{fg highlight}---------------Cut here-------------@{fg text}\n\nIf you wish to make dRE!ChECk resident add this Line to your your \nUser-Startup or BBS-Startup.\n\n@{fg highlight}-------------------Cut here----------------@{fg text}\nRESIDENT dRE!ChECk dRE!ChECk:dRE!ChECk PURE\n@{fg highlight}-------------------Cut here----------------@{fg text}\n\nCopy all Files from the "S" Directory to your S:, the FCHECK/LHA.INFO to\nyour BBS:FCHECK/ Directory.\n\nIf you have made dRE!ChECk Resident so modify the TOOLTYPE "@{fg highlight}CHECKER=@{fg text}" in\nyour BBS:FCHECK/LHA.INFO. The TOOLTYPE must now be: @{fg highlight}CHECKER=dRE!ChECk@{fg text}\n\nAfter this view @{"MOdifY tHE AdVERt!" link "Document_3" 0} @{"MODiFYAbLE OPtiONS" link "Document_4" 0}\n\nThats all...\n\n@endnode\n\n@node "Document_2" "WhAt iS NEW ON dRE!WAll v2.0"\n\n                              WhAt iS NEW ???\n                              ---------------\n\n1) 100% adding of different Advertnames to each LHA/LZH/LZA Files.\n   Since Version 2.1\n\n2) Addet a function wich allows you to add the Uploader Name/Location\n   Node/Date/Time to the Advert. CLI support also, the Uploader is then\n   Sysop and so on.... since Version 2.1\n\n3) Optimized the code, changed some routines against some faster ones.\n   Since this Version\n\n4) Supporting all versions of ISTRIP (C) - by TAS\n   (thnx for using your great stripper, hope you like my Adder)\n   Since Version 2.1\n\n5) Changed the Design. Since this Version\n\nBUGFIXES:\n\n1) Found a Bug with to hand over the checker options from the LHA.INFO.\n   Now it works really fine.\n\n2) Fixed the Bug with the cycling of the Advert Name, now dRE!CHECk \n   doesn`t support any special signs.\n   thnx to Mario/tRSi for report this Bug...\n\n@endnode\n\n@node "Document_10" "HOW tO Add ANd StRiP"\n            Short explainment of the Files LHA.ADD & LHA.STRIP\n            --------------------------------------------------\n\ndRE!ChECK:LHA.ADD:\nHere write in the full Paths to your Adverts, iE:\n-----------------------\ndRE!CHECK:MY-ADVERTS\nS:READ_ME_OR_DIE\n-----------------------\nand so on ...\n\ndRE!ChECK:LHA.STRIP:\nHere write in all Names of known bbs banners you wish to remove from\neach archive. iE:\n-------------------\n*.displayme\n*.add\nLive_in_ConZert.txt\n-------------------\nI included an already defined LHA.STRIP file.\n\n@endnode\n\n@node	"Document_3" "MOdifY tHE AdVERt!"\n\n                   How to take influence to the Advert ?\n                   -------------------------------------\n\nSince the Version v2.1 of dRE!ChECk you are able to add Uploader \nInformations to the Advert.\n\nOpen the dRE!CHECk:dRE!ChECk.Add and replace my addi against your\nfavorit advert.\nNow the following Options are possible:\n\n%U  =  UPLOADER NAME (31 Spaces)\n%L  =  HIS LOCATION  (30 Spaces)\n%N  =  UPLOAD NODE   (2  Spaces)\n%D  =  UPLOAD DATE   (8  Spaces)\n%T  =  UPLOAD TIME   (8  Spaces)\n\nPlace this Signs on any Place in your Advert and dRE!ChECk will replace\nit against the Uploader Informations.\n\nThe Spaces after the Signs are meaning this:\nIf you like to add the Uploader Name the do like this:\n\nUPLOADER : %U                             ; <- 31 Signs including the %U\n           ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^\n\nLOCATION : %L                            ; <- 30 Signs including the %U\n           ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^\nand so on ... hope this will explain this Options...\nyou can write Signs to any Place in your Advert, but don`t forget the\nfree Spaces after it...\n\n@endnode\n\n\n@node	"Document_4" "MODiFYAbLE OPtiONS"\n\nYou can modify all functions of dRE!ChECk v2.4\n\nThe following Options are possible.\n\na = enables adding Adverts from dRE!ChECk:LHA.ADD\ns = enables stripping Adverts from dRE!ChECk:LHA.STRIP\ni = enables IStrip (C) by TAS\nc = enables cycling adverts\nt = enables testing\n\nAll this Options you can set in the BBS:FCHECK/(LHA/LZH/LZA).INFO\n\nIE: @{fg highlight}OPTIONS=a i c t@{fg text}\nThis means dRE!ChECk will add, execute IStrip, cycle the Advert and test\nthe Archive.\n\n@endnode\n\n@node "Document_5" "CREditS"\n\n                             Noteable Credits\n                             ----------------\n\n      dRE!ChECk v2.4 was written by : dR.dRE! Of (tRSi /X·iNNOVAtiON)\n\n    tHE iNStAllER SCRiPt ARE WRittEN bY dR.dRE! Of (tRSi /X·iNNOVAtiON)\n\n    tHE AMiGAGUidEFilES ARE WRittEN bY dR.dRE! Of (tRSi /X·iNNOVAtiON)\n\n             tHE AMiGAGUidEfilE WAS CREAtEd WitH HEddlEY v1.1\n                          (c) bY Edd dUMBill 1994\n\n                  AMiGA APPliCAtiON iNStAllAtiON UtilitY\n                               VERSiON 1.24\n                COPYRiGHt ©1990-1992 COMMODORE-AMiGA, iNC.\n                           All RiGHtS RESERVEd.\n                         dESIGNED ANd dEVElOPEd bY\n                           SYlVAN tECHNiCAl ARtS\n\n@endnode\n\n@node "Document_6" "GREEtiNGS"\n\n                     ---------------------------------\n                     Greetings to the following dudes:\n                     ---------------------------------\n\n   bYTEANdi/tRSi - SiEGEl/tRSi -  SPY/tRSi -  DEltA-X/tRSi - MClOUd/tRSi\n    MARiO/tRSi - ECS/tRSi - ZOU^ZOU/tRSi - SAL-ONE/tRSi - VAMPiRE/tRSi\n   MOGUE - tRitON - VAlShARE - REDSkiN - X-CEllENt - BjOERN - RiCHi/flt\n                                 JUAN/TRSI\n\n            ANd tO All MY REGiStEREd USERS ANd All i fORGOt ...\n\n\n@endnode\n\n@node "Document_7" "(tRSi /X·iNNOVAtiON)"\n\n                        @{fg fill}(@{fg highlight}tRSi /X·iNNOVAtiON@{fg fill})@{fg text} ARE:\n                        @{fg fill}-------------------------@{fg text}\n\n                               @{fg highlight}dR.dRE!/tRSi\n                               @{fg fill}bYtEANdi/tRSi\n                                @{fg text}SiEGEl/tRSi\n                                 @{fg highlight}SPY/tRSi\n                               @{fg fill}dELtA-X/tRSi@{fg text}\n\n   If you wanna join us, so get in touch with any of the Dudes above...\n\n@endnode\n\n@node "Document_8" "REGiStER dRE!tOOlS"\n\n                            REGISTER DRE!DOORS\n                          - ------------------ -\n\nTHE REGISTRATION FEE IS 2O$ ONLY. IF YOU THINK PHEW! QUITE A LOT OF MONEY,\n                  READ WHAT YOU WILL GET FOR YOUR MONEY.\n\n1. YOU CAN BE SURE THAT YOU`LL GET ONLY DOORS WITHOUT ANY BACKDOOR !!!\n   OF COURSE THE REGISTERED USER(S) WILL GET ONLY PRIVATE VERSIONS \n   ALL PUBLIC VERSIONS HAVE A TIMELIMIT OR I REMOVED SOME MENU OPTIONS\n             ONLY !!! THE REG.USERS WILL GET THE FULL VERSION.\n2. YOU FOUND A BUG ? -> REPORT IT TO ME AND YOU`LL GET A FIXED VERSION SOON \n   NO NEED TO WAIT FOR A LATER RELEASE VERSION.\n3. YOU HAVE SOME GOOD IMPROVEMENTS, TALK TO ME, AND I WILL SEE IF I CAN\n   REALISE IT.\n4. YOU NEED A PRIVATE DOOR ONLY FOR YOUR BBS, I WILL CODE IT !\n5. PRIVATE SUPPORT CONFERENCE IN A FUCKEN FAST TRSI BOARD IN NETHERLAND.\n   NEW DISTRIBUTION SITE IN GERMANY ALSO AVAILABLE.\n6. ALL DOORS/UTILS ARE INCLUDING YOUR REGISTER STRING.\n7. UNTIL NOW ALL DOORS ARE WITH COMMODORE INSTALLER SUPPORT, NO HARD\n   INSTALL ANYMORE !!!\n8. YOU`LL GET ALL LATER VERSIONS OR NEW DOORS FOR THE ABOVE PRICE.\n                  SIMPLY YOU`LL GET THE BEST SUPPORT AROUND.\n              THINK ABOUT AND KEEP THE PROGRAMMERS PROGRAMMING !!!\nIF YOU ARE INTERESTED  CONTACT ME AT ANY TRSI BOARD OR SIMPLY AT THE\n                 tRSi GHQ`S tHE HiDDEN OR SPiRitS Of SOUl\n\n@{fg highlight}OR SEND YOUR MONEY TO THIS ADRESS: B. HOFFMANN\n                                   KAPITELSTRASSE 1\n                                   41460 NEUSS\n                                   GERMANY@{fg text}\n\nSOON AS THE MONEY IS HERE YOUL GET THE FULL PACKAGE OF ALL MY DOORS AND\nTOOLS...\n\nNOTE: I`m no longer Part of the illegal section so i have nothing to hide,\n      so the Cops can do nothing with my Adress, and in addition i already\n      was busted in the begining of this Year.\n\n@endnode\n\n@node "Document_9" "OthER dRE! tOOlS/dOORS"\n\n       All OtHER AlREAdY RElEASES Of dR.dRE! Of (tRSi /X·iNNOVAtiON)\n       -------------------------------------------------------------\n\n NAME                  TYPE   VERSION\n---------------------+------+--------------------------------------------- \nDRE!WHO              | XiM  |  V1.1  PUBLIC \nDRE!FRONT            | XiM  |  V1.O  PUBLIC \nCHAT!ACCESS          | XiM  |  v1.2  PUBLIC \nONLY DOORMENU        | XiM  |  v1.o  PUBLIC \nSPEEDZIP (ZIP)       | DOS  |  v1.o  BETA \nBULL!VIEW            | XiM  |  v1.02 PUPLIC \nLAST!JUNKZ           | AiM  |  v1.0  PRIVATE RELEASE FOR REG. USERS ONLY \nPWFAILURE            | XiM  |  v1.1  PUPLIC \nBETA!REPORT          | XiM  |  v0.92 BETATESTER(S) ONLY\nDRE!NODECHECK        | XiM  |  c0.ß  PUBLIC \nDRE!SENDLIST         | XiM  |  v1.2  PUBLIC \nNUP^SYSPW COMMENTER  | XiM  |  v1.2  PUBLIC \nNEWUSER SCRIPT       | XiM  |  v1.21 PUBLIC\nGLOBAL USER STATUS   | XiM  |  v1.9  PUBLIC \nSPEEDLIST (USERLIST) | XiM  |  v1.ß  PRIVATE RELEASE FOR REG. USERS ONLY\nDESCRIPTION!SNAP     | AiM  |  v1.o  PUPLIC \nFAST!DUPE            | XiM  |  v1.11 PRIVATE COOP DR.DRE!^BYTEANDI\nMOST WANTED          | XiM  |  v1.52 PRiVATE RELEASE FOR REG. USERS ONLY \ndRE!Add (tXt AddER)  | DOS  |  v2.0  PRIVATE RELEASE FOR REG. USERS ONLY \ndRE!CARD             | XiM  |  v2.1  BETA (PRIVATE^PUBLIC VERSION SOON)\nDRE!ADVERTISE        | XiM  |  v2.o  PRIVATE RELEASE FOR REG. USERS ONLY \nDRE!SENt             | XiM  |  v0.7  PRIVATE RELEASE FOR REG. USERS ONLY\nDRE!FREE             | XiM  |  v0.3  PRIVATE RELEASE FOR REG. USERS ONLY\nDRE!CHECK            | DOS  |  v2.4  PRIVATE RELEASE FOR REG. USERS ONLY\nDRE!REPORT           | XiM  |  v1.21 PRIVATE & PUBLIC PROTECTED RELEASE\nDRE!COMMENT          | XiM  |  V2.1  PUBLIC & PRiVATE RELEASE FOR REG. USERS\nDRE!WALL             | XiM  |  v2.0  PRiVATE RELEASE FOR REG. USERS ONLY \n---------------------+------+---------------------------------------------\n\nTHERE ARE ALSO SOME OLDER (AiM) DOORS AVAILABLE WICH I CAN`T REMEMBER WHAT\n               IT WAS  EXACTLY ...  JUST SEARCH FOR DR.DRE! \nIF YOU LIKE MY DOORS/UTILS THEN @{"REGISTER" link "Document_9" 0} IT PLEASE.\n                 !!! KEEP THE PROGRAMMERS PROGRAMMING !!!\n\n@endnode\n','\n',char(10)),NULL,'auto-added',48091,10,0,NULL,NULL,'trsi_c24','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_ca','TRSI-CA.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-CA.LHA','rexxdoor','XIM','chatax.AiM',NULL,'[-Dr.Dre!/tRSi]','TRSI','\        ____   \/   _________/   TRiSTAR \/    \/   _  _/\____  \/    \ RED SECTOR! +-/RtX!  \   |   \_   |   \     \----------+',replace(' /\______________  _____________\n \        ____   \/   _________/   TRiSTAR\n  \/    \/   _  _/\____  \/    \ RED SECTOR!\n+-/RtX!  \   |   \_   |   \     \----------+\n| \  ____/___|__  /_____  / ____/  pRESENTs|\n+--\/-----------\/------\/\/---------------+\n    Chat Access 1.o - by [-Dr.Dre!/tRSi]\nProtect your BBS against Multi MonsterChats!\n','\n',char(10)),'ChatAx.Guide',replace('@database Chat Access Door v1.o by [-Dr.Dre!/tRSi]\n\nCopyright (C) 1993 by [-Dr.Dre!/tRSi], Germany\nAll Rights Reserved\n\n@Remark $VER: Version v1.1 (Monday 17-Jan-94 13:32:57)\nRemark AmigaGuide DataBase for Chat Access Door v1.o by [-Dr.Dre!/tRSi]\n\n@node MAIN "Chat Access Door v1.o (Monday 17-Jan-94 13:32:57) AmigaGuide Document for /X"\n             ____                        ___                     :\n           ._\  /________________________\_/ ____________________¦_ _\n           |  \/   __ _ _               _\_ /_      _/           |\n           |    _ _\         T.R.S.I      // \_    / \_ _     \\ |\n           | ____________________________//____________________\ |\n       ____| \        ___________      /_____        /______  /  |____\n      /\___\  \      /    .|   _/    _/\    /_______/       \/|  /___/\\n      \/___/   \  __/     ¦|   \      \_\_____     \_        ¦|  \___\/\n           |    \/ /      :|    \      /     /      /        :|  |\n           | \    /________|  _  \    /____________/|_________| _|\n           | \\         _ _  \_   \  /_ \\  _ __ _          _ _/ |\n           | \\\           \_/     \/ \_//       /__ _         \ |\n        _ _|________________\__________/ \__________________ /\ _|H2o!\n           ¦                           /\                   /__\\n     is proud to present: Chat Access Door v1.o (Monday 17-Jan-94 13:32:57)\n                         @{"     Introduction      " Link no1}\n                         @{"     Requirements      " Link no2}\n                         @{"     Installation      " Link no3}\n                         @{"      Menu Help!       " Link no4}\n                         @{"       Creditz!        " Link no5}\n                         @{"      Greetings!       " Link no6}\n                         @{"     tRSI Boards!      " Link no7}\n@endnode\n@node no1 " Introduction"\n\nThis Door is for you, Sysop...\nIt should be protect your BBS against MultiUser Monster Chats, hehe\nFor shure you know the Proble, it is the best Caller Time an some crazy\nDudez are blokking your BBS with an Monster MultiUser Chat...\nThis Program allows you and your Cosysop to restrict specified Users from\nthe MultiUser Chat.\n\nhave phun with the door...\n[-Dr.Dre!/tRSi]\n\n@endnode\n@node no2 " Requirements"\n\nYou need an Amiga 500/1000/2000/3000 (The Sysops with an A4ooo or A12oo \nshould call my BBS to receive an uncompiled Version)\nKickstart 2.0 or higher\nAmi Express 2.xx - 3.xx (Registered)\nAn running RPStart\nrexxplsextnd.library\nRexxplslib.library\nrexxsyslib.library\nrexxsupport.library\nin your Libs: but they are included\n\nThats all...\n\n@endnode\n@node no3 " Installation"\n\nFirst copy all Libs: (If you dont have them allready) into your libs: Dir\nCopy the Chat.info and the MultiUserChat.Info to your BBS:Commands/bbscmd/\nand make shure you run rpstart in your Startup-Sequence.\nThen create a Directory called ChatAx in your Doors...\nThere you copy all Files and Dirs from the Archive Directory \nBBS/Doors/ChatAx/\n\nThere must be in all this Files and Dirs...\n\nChat.no                       67 (The DataFile with all restricted Users)\nChatax.aim                 63588 (The Door self)\nchat.cfg                       4 (The Config File)\nChatAx.Guide                6435 (The Guide File)\n\nAfter this jump into the Chat.Cfg File and change the Level...\n\n------------------cut here------------------\n253\n------------------cut here------------------\nLine.1=All Users with this Level (or higher) is it allowed to restrict\n       another Guys from the Chat...\n       may it is better to enable this Option only for Sysop`s\n\nNow edit in your bbscmd the MultiUserChat.Info and change the Location\nto your original MultiChatTool...\n\nThis is all what you have to do...\n\n@endnode\n@Node no4 " Menu Help"\n\n                            _ ___     __     ___ _\n                                /___ /\_\ ___\\n                               .::::.\/_/.::::.\n\n                      [®] MultiUserChat Access Door [©]\n                      [®]  © by Dr.Dre! - tRSi! `94 [©]\n              ._______________________________________________.\n              |                                               |\n              |        1) ... Enter_Multi_User_Chat ..        |\n              |        2) ............ Disable_User ..        |\n           --+O---     3) ............. Enable_User ..     --+O---\n              |        4) . View_all_Disabled_Users ..        |\n              |        Q) ................. Exiting ..        |\n              |                                               |\n              !_______________________________________________!\n                                   __ :\n                                  /\_\:Exiting...\n                                  \/_/:\n                                      ·\n\n   This is the Main menu from the Door, displayed only for the Sysops!!!\n\n1. Jump into the MultiChat\n2. Restrict User from the MultiChat\n3. Enable restrcited User for MultiChat Access\n4. View all Restricted Users\nQ. Exit the Door\n@endnode\n@Node no5 " The Creditz!"\n\n              Copyright (C) 1994 by [-Dr.Dre!/tRSi], Germany\n                            All Rights Reserved\n\n             The AmigaGuide DataBase written by [-Dr.Dre!/tRSi]\n\n    For more good Doors call my BBS under 49 (0) 2131 275756 & 275634\n               · [ · MARLEYS COFFEE SHOP - tRSi GHQ · ] ·\n\n      Thanx to Skin! for using some of your great Styles in my Doors!\n\n@endnode\n@Node no6 " Greetings"\n\n                   The Greets are going to this Dudes...\n\n ByteAndi/X-Design, Spy/X-Design, Remo/X-Design, X-Treme/TRSI, Saito/TRSI\n    Gandalf/Faith, Silver/Faith, McLoud/TRSI, Irata/TRSI, Triton/Fth\n Skylark/LSD, Nick, Metoner/TRSI, J.Walker/TRSI, Crazy/TRSI, Valshare/TRSI\n    Vicous/LSD, Richi/Flt, Steve/D&R, Amicom, -rS!, Empire/Mst, Mr.VAiN\n            APOLLO, BJoerN/Pdy, Jive/TRSi, Scope/Trsi, SkiN!\n          and simply all tRSi Member an other Doodes I forgot...\n\n@endnode\n@Node no7 " tRSi Boards Worldwide"\n\n                 To Contact me Call any of this Boards...\n           -==================================================-\n\n   Cauldron.......................German  hq............++49 Pure Elite\n   Marleys Coffee Shop............German  hq............++49 Pure Elite\n   Boondocks......................Europe  hq............+31-548-040-653\n   Final Impact...................Swedish hq............++46-54-113-486\n   Flying Spirits.................Swiss   hq............+41-217-282-524\n   Savage Amusement...............Austia  hq............+43-767-227-743\n   Zenlandia......................Finnish hq............+358-088-82-144\n\n\n           -==================================================-\n@endnode\n','\n',char(10)),NULL,'auto-added',51896,6,0,NULL,NULL,'trsi_ca','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_cad','TRSI_CAD.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI_CAD.LHA',NULL,'XIM','LE-window5.exe',NULL,'Dr.Dre!/tRSi^Zenith','TRSI','l___       /      \/    _/_______.: /       /   /  _/\___      /    : /_______/-rS!\_____\  _____/     |',replace('     ._________________  ______\n     l___       /      \/    _/_______.:\n       /       /   /  _/\___      /    :\n      /_______/-rS!\_____\  _____/     |\n            /_______|     \/`94/_______|\nChat·Access·Door v1.2 by Dr.Dre!/tRSi^Zenith\nProtect your BBS for Multi-User MonsterChats\n','\n',char(10)),'ChatAx.Guide',replace('@database Chat Access Door v1.2 - by Dr.Dre!/TrSi\n\nCopyright (C) 1994 by Dr.Dre!/tRSi^zENITh Germany\nAll Rights Reserved\n\n@Remark $VER: Version v1.2 (Tuesday 08-Mar-94 10:27:01)\nRemark AmigaGuide DataBase for Chat Access Door v1.2\n\n@Node MAIN "Chat Access Door v1.2 (Tuesday 08-Mar-94 10:27:01) Dcoument for /X"\n\n                   ._________________  ______\n                   l___       /      \/    _/_______.:  \n                     /       /   /  _/\___      /    :\n                    /_______/-rS!\_____\  _____/     |''94  \n                          /_______|     \/   /_______|\n\n                           is proud to present: \n           Chat Access Door v1.2, XiM Module for /X 2.xx - 3.xx\n\n                       English Doc     German Doc\n                     @{" Introduction  "Link no1} @{"  Einleitung   "Link nr1}\n                     @{" Requirements  "Link no2} @{" Anforderung   "Link nr2}\n                     @{" Installation  "Link no3} @{" Installation  "Link nr3}\n                     @{"   Copyright   "Link no4} @{"   Copyright   "Link no4}\n                     @{"   Greetings   "Link no5} @{"    Gruesse    "Link no5}\n                     @{"          TRSI Boards          "Link no6}\n@endnode\n@node no1 " Introduction"\n\nThe Chat Access Door v1.2 is best and fastest Door to protect your BBS for\nMulti User Monster Chats.\n\nDr.Dre!/tRSi                                         @{" Main Menu " Link main}\n@endnode\n@node nr1 " Einleitung"\n\nDie Chat Access Door v1.2 ist die beste und schnellste Door um eine BBS vor\nMulti User Monster Chats zu schützen.\n\nDr.Dre!/tRSi                                         @{" Main Menu " Link main}\n@endnode\n@node no2 " Requirements"\n\nOnly what you need is OS2.++ and any Version of AmiExpress (registered)\nand in Doors:ChatAccess/ the Access.Info Icon.\nNothing more...\n                                                     @{" Main Menu " Link main}\n\n@endnode\n@node nr2 " Anforderungen"\n\nDas einzige was die Door benoetigt ist Kickstart 2.++\nund in Doors:ChatAccess/ das Access.Info Icon.\n                                                     @{" Main Menu " Link main}\n\n@endnode\n@node no3 " Installation "\n\nAt first copy the whole Directory ChatAccess into your Doors:\nthen rename your old BBS:Commands/BBSCmd/Chat.Info into \nBBS:Commands/BBSCmd/MultiUserChat.info\nAt last open the Doors:ChatAccess/Access.Info and write down there all\nNames from all the User you want to restricit from the MultiChat, like\nthis Example.\nNAME.1=Steve\nNAME.2=Dr.Dre!/tRSi\nNAME.3=<NAME>\nand so on...\nlook the Example Icon...\n                                                     @{" Main Menu " Link main}\n@endnode\n@node nr3 " Installation"\n\nKopiert das komplette Verzeichnis ChatAccess aus meinem Archive in euer \nDoors: Verzeichnis. Renamed euer altes BBS:Commands/BBSCmd/Chat.Info\nin BBS:Commands/BBSCmd/MultiUserChat.Info.\nDann addet in das Doors:ChatAccess/Access.Info als ToolTypes all Namen\nvon den Usern die Ihr vom MultiChat ausschliessen wollt.\nBeispiel:\nNAME.1=Steve\nNAME.2=Dr.Dre!/tRSi\nNAME.3=<NAME>\nund soweiter, seht mein beigefuegtes Icon...\n\n                                                     @{" Main Menu " Link main}\n@endnode\n@node no4 " Copyright"\n\n\n        Chat Access Door v1.2 is written by Dr.Dre! of TRSI^Zenith\n                              ++ in fast C ++\n                         All Rights Reserved ©1994\n\n              ChatAx.x has a Original Size from : 9352 bytes\n\n          The AmigaGuide DataBase written by Dr.Dre!/tRSi^Zenith\n\n         If you have any Problems with the Door so contact me at \n                         @{" Marleys Coffee Shop " Link Coffee}\n\nI`m still looking for some good BetaTesters, if you are interested and are\nrunning a Multinode System so contact me at @{" Marleys Coffee Shop " Link Coffee}\n\n                                                     @{" Main Menu " Link main}\n\n@endnode\n@node no5 " Greetings"\n\n     Many thnx to all my Beta Testers who helps me to fix all Bugs !!!\n\n                   The Greets are going to these Dudes...\n\n   ByteAndi/X-Design, Spy/X-Design, Remo/X-Design, X-Treme, Saito/TRSI\n    Fugitive/DLM, MetalbasheR!, McLoud/TRSI, Irata/TRSI, Triton/Pdy\n Skylark/LSD, Nick, Metoner/TRSI, J.Walker/TRSI, Crazy/TRSI, Valshare/TRSI\n    Vicous/LSD, Richi/Flt, Steve/D&R, Amicom/Mst, -rS!/TRSi, Empire/Mst, \n   BJoerN/Pdy, Scope, SkiN!,Mario/TRSI, TCM!/DLM, -runt/TRSI, Prayer/TRSI\n                         Samir/trz, Rotor/trz ...\n       and simply all tRSi & tRZ Members an other Doodes I forgot...\n\n\n                                                     @{" Main Menu " Link main}\n@endnode\n@node no6 " TRSI Boards Worldwide"\n\n                 To Contact me Call any of this Boards...\n\n   biohazard......................Canadian HQ............+1-905-841-0965\n   cauldron.......................German   HQ............++49 Pure Elite\n   marleys coffee shop............German   HQ............++49 Pure Elite\n   MayDay.........................German   HQ............++49 Pure Elite\n   boondocks......................European HQ............+31-548-040-653\n   final impact...................Swedish  HQ............++46-54-113-486\n   flying spirits.................Swiss    HQ............+41-217-282-524\n   savage amusement...............Austria  HQ............+43-767-227-743\n   zEnlandia......................Finnish  HQ............+358-088-82-144\n\n\n                                                     @{" Main Menu " Link main}\n@endnode\n@node Coffee "Marleys Coffee Shop - TRZ german hQ"\n\n           * tRiStAR & RED sECtOR * zENITh * gERmAN hEADqUARtER\n                                           _______    ._____\n      _______  ____.______  ______________/   .  /____|    /_______\n      \      \/    |      \/   _  \      /   ___/_    l   /   __  /\n       \           |      \\   /  /_    /_________l____  /\__   \/\n        \    \/____l________\  \____|______|    |_______/________\\n         \____\         /______|                       _______\n                 ____          _______________________/   .  /\n                /  __l_. _____/     __/     __/   .  /   ___/_.\n               /   |   |/     \     _/\     _/   ___/_________|\n              /________|      \\____|  \____|_________|\n                       \_______/         _____    \n                      __________________/     \__________\n Dr.Dre!/tRSi        /   __  /    /    //      \    .   /\n                    /\__   \/         /\_______/    ___/\n  J.Walker/tRSi    /________\   /____/-rS!/aRt/_____|\n                          /____/\n\n                                                     @{" Main Menu " Link main}\n@endnode\n','\n',char(10)),NULL,'auto-added',20546,8,0,NULL,NULL,'trsi_cad','scan',1780048806);
