INSERT INTO door_catalog VALUES('trsi_cd1','TRSI-CD1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-CD1.LHA','CD-SERVER','XIM','CD-SERVER',NULL,'SieGeL','TRSI','\    ____    )  /___/\_| & rED sECTOR ¡NC | .-\___\ | \___\__   /   |  /X ¡NNOVATION   | `---|___|___|______/____|---[ [RESENTS ]---''',replace(' _____________ ___Mo! __.<---[ tRISTAR ]---.\n \    ____    )  /___/\_| & rED sECTOR ¡NC |\n.-\___\ | \___\__   /   |  /X ¡NNOVATION   |\n`---|___|___|______/____|---[ [RESENTS ]---''\n    CD-Server V1.00p by SieGeL & ByteAndi\n--------------------------------------------\n1ST "REAL" SERVER WITH FULL C-SHELL COMFORT,\nDL DIRECT FROM CD-ROM, PATHNAME-COMPLETITION\nFAST DIRSCAN-ROUTINES,AMIEX & FAME COMPAT.,\n   1oo% SAFETY AND INSTALLER SUPPORTED !\n--------------------------------------------\nA NEW tOOL fROM tHE REAL (tRSi/X-iNNOVATiON)\n','\n',char(10)),'CD-sERVER_DEUTSCH.guide',replace('@database CD-sERVER V1.0 - Deutsches DataBase\n@author "SieGeL/tRSi"\n@(c) "Copyright © 1995 (tRSi/X-iNNOVATiON)"\n@$VER: CD-SERVER.guide V1.01 (05-26-95)\n\n@index Main\n\n@node Main "CD-Server - BBS Tool geschrieben von SieGeL & ByteAndi (tRSi/X-iNNOVATiON)"\n@{b}                                                                     ______\n .-----------[ TRSI (/X·INNOVATION) ]------------.       _  ________/     /\n | _________________________________       ______`-------\\//  __    \\    /---.\n | \\       _____________     /     /______(______)  _     /    \\     \\  /    |\n |  \\______\\    |    __/   _/\\______       /     | (/)   /     /\\     \\/ Mo! |\n | \\     |      |    \\      \\       |     /      |  ¯   /     / /\\     \\_    |\n | \\\\    l______|_____\\      \\___________/_______|    _/     /_/  \\_____/    |\n `---------------------\\______/-----------------------\\_____/-\\_____/--------''@{ub}\n\n                           iS pROUD tO pRESENT:\n\n@{APEN 2}             CD-Server V1.00 public written by SieGeL & ByteAndi@{APEN 1}\n                                                                          \n                      @{" COPYRIGHT! " LINK COPYRIGHT}     @{"VERTREIBUNG!" LINK DISTRIBUTION}\n                      @{" EINFÜHRUNG " LINK EINFÜHRUNG}     @{"INSTALLATION" LINK INSTALLATION}\n                      @{" BEDIENUNG! " LINK HOW2USE}     @{" -CREDITZ!- " LINK GREETINGS}\n\n Der erste "@{b}ECHTE@{ub}" Server für jedes Amiga-DOS kompatible device,z.B. CD-Rom !\n@endnode\n\n@NODE COPYRIGHT "Copyright-Information für dieses Programm"\n\n     @{u}Copyright@{uu}\n\n   Dieses Programm ist ''FreeWare''.\n\n Es darf frei kopiert und für nicht kommerzielle Zwecke vertrieben werden,\n solange sicher gestellt ist, das kein file (ausser natuerlich BBS-Addys)\n zu diesem Archiv dazugepackt oder aus diesem Archiv entnommen wird, und \n das für diese Veröffentlichung nicht mehr Geld, als für die Erstattung des\n Datenträgers/Kopierkosten, notwendig ist, verlangt wird.\n\n Das volle Copyright auf den Programmcode liegt bei dem Author (also meine\n Wenigkeit!) selbst, und ohne meine schriftliche Genehmigung ist es nicht \n erlaubt, dieses Programm kommerziell zu vertreiben.\n\n Diese Version von CD-Server ist die EINZIGSTE, die unter dem Prinzip der\n ''FreeWare'' vertrieben wird, alle anderen Updates (Fehlerbereinigungen etc.)\n sind dann nur noch für registrierte User verfügbar. Wenn Sie registrierter\n User bei mir werden möchten, dann haben Sie eine Registrierungs-Gebühr in\n Höhe von 30.- DM ($20) zu bezahlen.\n\n Diese Registrierungsgebühr ist natürlich nur einmalig zu entrichten, nach\n der Bezahlung erhalten Sie vollen Zugriff auf mein Register-Door und können\n dann frei über ALLE meine Tools verfügen.\n\n Alles weitere können Sie dann mit mir in meiner @{"BBS" LINK ADDY1} besprechen. Einfach\n mal durchcallen und ''SieGeL/tRSi'' eine Mail hinterlassen, ich kläre dann\n alles weitere.\n\n            @{"LISTE ALLER BISHER VON MIR VERFASSTEN PROGRAMME" LINK PRGLIST}\n@endnode\n\n@NODE DISTRIBUTION "Vertreibung von CD-Server"\n\n     @{u}Verbreitung/Vertreibung@{uu}\n\n  Hiermit genehmige ich die Veröffentlichung von diesem Archiv, solange wie\n  nicht mehr Geld, als für die Erstattung der Kopier-kosten etc. notwendig\n  sind, verlangt wird, und solange dieses Archiv nur in seinem Original-\n  zustand vertrieben wird. \n\n  Das Copyright liegt bei dem Author (also mir !) selbst, und ohne meine \n  schriftliche Genehmigung darf dieses Programm nicht kommerziell vertrieben \n  werden.\n@ENDNODE\n\n@node EINFÜHRUNG "Einleitung, oder warum dieses Programm entstanden ist."\n\n@{uu}Einleitung@{uu}\n\nNachdem ich mein Quadraspeed CD-Rom gekauft hatte, wollte ich dieses Laufwerk\nauch meiner BBS zukommen lassen (ich fahre momentan noch Amiex), musste \njedoch feststellen, das das gar nicht so ohne weiteres moeglich ist, ein CD-\nRom in Amiex einzubinden, da man dann ja erstmal die DLPATHES alle setzen muß,\ndann müsste man sich auch noch ein Filelisting erstellen...nene, war mir echt\nzuviel des guten...\n\nAlso hab ich erstmal nach nem Tool gesucht, was die Arbeit mit dem CD-Rom und\nder guten (?!) Amiex möglich macht...und siehe da, ich hab sogar eins ge-\nfunden, und zwar CD/FTP-Server (oder so ähnlich :) von Sigma Seven...das war\ngenau das was ich wollte...wenn da nich ein Haken gewesen wäre...dieses Door\nhat die Angewohnheit, jedes File erstmal auf HD zu kopieren, und danach dem\nUser zu geben..und mit jedem mal kopieren wird die Platte fragmentierter...\nDa ich sowas nicht mag, hab ich mir gedacht, das es auch noch einen anderen\nWeg geben müßte, ein CD-Rom in Amiex einzubinden...nunja, daraus iss halt \ndieses Programm entstanden.\n\n@{u}Merkmale von CD-Server@{uu}\n\n - Ermöglicht Downloaden/Anzeigen von TXT-files @{b}DIREKT@{ub} von CD-Rom, ohne\n   lästige Kopierei!\n\n - @{b}Komplette C-Shell Bedienung@{ub}, z.B. @{b}TAB@{ub}-Taste für @{b}Pfadnamen-Erweiterung@{ub},\n   das ''@{b}!@{ub}'' Zeichen als Abkürzung von Befehlen im @{b}20-Zeilen Buffer@{ub}, voll-\n   ständige @{b}CRSR-Key@{ub} Simulierung (Hoch/runter für Buffer,links/rechts um\n   in der Zeile hin und her zu laufen) usw...\n\n - Unterstützt auch @{b}UNIX@{ub}-Kommandos, wie z.B. ''@{b}..@{ub}'' für Parent-Dir etc.\n\n - Eingebaute Unterstützung für GUIDE-Dateien, um diese als ANSI-Files\n   umzuwandeln und anzuzeigen\n\n - Benutzt BBS-interne Download- und FlagFile Routinen ohne das man @{b}ALLE@{ub}\n   Pfade in das Icon eintragen muss, daher auch flexibel im CD-Wechsel!\n\n - @{b}Amiex V3.++@{ub} und FAME (Final Amiga Mailbox Engine) kompatibel\n\n - Braucht bis auf das Guide2DocProf @{b}KEINE@{ub} weiteren Befehle aus dem C: dir.\n\n - Sau-schnelle Directory-Scan routine mit der selben Ausgabe wie der all-\n   seits bekannte und beliebte Directory Opus :)) \n\n   etc...\n\n@{u}Was man alles für den CD-Server braucht@{uu}\n\nBevor Sie dieses Programm installieren, müssen ein paar Bedingungen erfüllt\nsein...zum ersten , haben Sie ein Device (CD0: als Beispiel), welches Sie \nKOMPLETT als Datenträger der BBS zur Verfügung stellen können ? \n\n@{APEN 2}BITTE DARAN DENKEN, ASSIGNS SIND ZU UNSICHER, DA DER USER EVTL. IN DAS ROOT-\nDIR DES ASSIGNS KOMMEN KÖNNTE, ALSO BITTE IMMER NUR DH0:, CD0:, DF0: :) USW.@{APEN 1}\n\nDann ist in der Testphase aufgefallen, das bei Benutzung eines PCMCIA-\nControllers in Verbindung mit einem Mitsumi FX-400 CD-Rom ein Fehler auf-\ngetreten ist beim Anzeigen von Text-files. Dieser Fehler liegt nicht an\nunserer Dummheit (!!!), sondern einzig und allein daran, das dieses \npcmcia.device (oder wie auch immer) den FileInfoBlock von ADOS nicht richtig\nunterstützt, und von daher es zu merkwürdigen Fehlern kommt. Sollte dieses\nbei Ihnen der Fall sein, dann wenden Sie sich bitte an den Author dieses\nDevices, und bitten ihn um ein Update. Soweit es ging werden solche Fehler\ntransparent von CD-Server behandelt, Sie bekommen davon eigentlich nix mit.\n\nDann zu guter letzt iss natürlich klaro, das dieses Tool min. Kickstart V37\noder höher benötigt, aber wer hat schon noch 1.3 ;), und als BBS sollte\nmindestens eine Amiex V3.++ oder höher installiert sein, oder halt die FAME,\nwobei hier die Version noch nicht wichtig ist..:)\n\n                @{"ZUR INSTALLATION GEHTS HIER LANG :)" LINK INSTALLATION"}\n@endnode\n\n@node INSTALLATION "Wie man CD-Server auf Ihr System installiert."\n@NEXT HOW2USE\n\n@{u}Allgemeine Installation@{uu}\n\n1.Kopieren Sie das Directory ''CD/'' zu Ihrem Doors: Verzeichnis, oder wo immer\n  Sie Ihre BBS-Tools auch aufbewahren.\n\n2.Kopieren Sie das File CD-SERVER.HLP'' nach Ihr S: Directory, dieses File\n  ist die Online-Hilfe von CD-Server.\n\n3.Kopieren Sie das File ''GUIDE2DOCPROF'' nach Ihr C: Directory, dieses File\n  wird zum Umwandeln der AmigaGuides zu ANSI-Files benötigt.\n\n4.Editieren Sie die Tooltypes im Icon ''CD-Server.info'', im Moment existieren\n  zwei Tooltypes:\n\n    DEVICE=CD0:   -> Hier müssen Sie das Device angeben, mit dem CD-Server\n                     arbeiten soll, z.B. DH0:, CD0:, DF0: :), RAD: etc.\n\n@{u}ACHTUNG:@{uu} GEBEN SIE HIER AUF KEINEN FALL EIN ASSIGN, SONDERN IMMER NUR EIN\n         DEVICE NAMEN EIN !! ALLES ANDERE IST DEFINITIV ZU UNSICHER !\n\n    PACKDIR=RAM:  -> Hier können Sie optional ein Directory angeben, welches\n                     dann als temporäres Dir gilt, hierher werden die umge-\n                     wandelten Guides geschrieben. Wenn dieses Tooltype nicht\n                     gesetzt ist, wird standardmässig T: genommen.\n\n5.Als nächstes müssen Sie ein ASSIGN namens ''SERVER:'' erzeugen. \n  Dieses Assign sollte am besten nach T: assigned werden, da T: normalerweise\n  nach RAM:T/ zeigt, und von daher am schnellsten ist. Und keine Panik, ich\n  kopiere keine Files nach ''SERVER:'', CD-Server braucht dieses Assign nur,\n  um mit der BBS zu kommunizieren :) \n  Am besten Sie schreiben folgende Zeile in Ihre ''user-startup'' :\n\n                       ASSIGN >NIL: SERVER: T: DEFER\n\n6.Zu guterletzt müssen Sie CD-Server noch in Ihr BBS-System einbinden. Bitte\n  wählen Sie das System, das bei Ihnen installiert ist : @{"AMIEX" LINK AMIEX_INSTALL} oder @{"FAME" LINK FAME_INSTALL} .\n\n7.Nach einem Reset sollte jetzt CD-Server einsatzbereit sein...\n@endnode\n\n@node AMIEX_INSTALL "CD-Server auf ein Amiex-System installieren."\n@PREV INSTALLATION\n@NEXT INSTALLATION\n\n@{u}Installation für Amiex-Betreiber:@{uu}\n\n1. Kopieren Sie das Icon ''CD.INFO'' in das Directory ''BBS:COMMANDS/BBSCMD'',\n   und ändern Sie gegebenenfalls den Pfad im Icon zu CD-Server.\n\n2. Editieren Sie alle Conference-Icons, in denen CD-Server laufen soll,\n   und tragen Sie in diese bitte ein neues DLPATH-ToolType ein:\n\n                        DLPATH.(x)=SERVER:\n\n   wobei (x) fuer die nächsthöhere Nummer der DLPATHES im jeweiligen \n   Conference-Icon steht. Angenommen, Sie haben die folgenden Tooltypes in\n   Ihrem AMIGA.INFO Conference-Icon:\n\n                         DLPATH.1=BBS:AMIGA/UPLOAD/\n                         DLPATH.2=DH2:AMIGA/UPLOAD/\n\n   dann tragen Sie für den CD-Server ein :\n\n                         DLPATH.3=SERVER:\n\n   Sie müssen dieses Tooltype in JEDEM Conference-Icon eingeben, in denen auch\n   CD-Server korrekt funktionieren soll...\n\n3. Starten Sie nun Amiex neu, da der Server alle Icons im Speicher behält,\n   und von daher auch nicht auf die Änderungen reagieren kann (Bitte ändern,\n   ByteMaster, das iss ja nu wirklich das letzte...:( ).\n\nDas ist alles für die Installation auf Amiex.\n@endnode\n\n@node FAME_INSTALL "CD-Server auf ein FAME-System installieren."\n@PREV INSTALLATION\n@NEXT INSTALLATION\n\n@{u}Installation für FAME-Betreiber:@{uu}\n\n1. Starten Sie den SystemEditor, gehen Sie in das Menü ''DOORS'', und lesen Sie\n   das File ''CD'' ein, welches diesem Archiv beigefügt ist.\n\n2. Editieren Sie den Pfad zu CD-Server, Accesslevel etc. nach Ihren eigenen\n   Wünschen und speichern Sie es im Directory ''FAME:SETTINGS/DOORS/BBSCMD/''.\n  (Bitte daran denken, das dieses Door als XIM angelegt wird, nicht als FIM!)\n\n3. Nun müssen Sie noch das Assign ''SERVER:'' in den Erweiterten Suchpfaden der\n   jeweiligen Conferencen dazuschreiben. Normalerweise heisst dieses TXT-File\n   AdvDlPathes.txt, es kann jedoch je nach Ihrer Konfiguration auch anders \n   heissen. Dieses File laden Sie bitte mit einem TXT-Editor (ASCII) Ihrer \n   Wahl ein und fügen die folgende Zeile dazu:\n\n   SERVER:\n\n   Dann speichern Sie dieses File wieder ab, und das wars auch schon..:)\n\nNun können Sie bereits den CD-Server antesten...\n@endnode\n\n@node HOW2USE "Übersicht aller Kommandos von CD-Server"\n\n@{u}Kommando-Übersicht@{uu}\n\n  @{b}DOS-KOMMANDOS@{ub}            @{b}AMIEX-KOMMANDOS@{ub}        @{b}ANDERE KOMMANDOS@{ub}\n\n   @{"    CD    " LINK CD}               @{"  FLAG/A/F " LINK FLAG}            @{"   CLEAR   " LINK CLEAR}\n   @{"   .. /   " LINK PARENT}               @{"   DOWN/D  " LINK DOWN}            @{"   VER/$   " LINK VER}\n   @{"   INFO   " LINK INFO}               @{"   VIEW/D  " LINK VIEW}            @{"  HELP/#/? " LINK HELP}\n   @{" LIST/DIR " LINK DIR}               @{"   QUIT/G  " LINK QUIT}            @{"   INDEX   " LINK INDEX}\n   @{"   TYPE   " LINK VIEW}        \n   @{"  ENDCLI  " LINK QUIT}\n\n@{u}Allgemeine Bedienung@{uu}\n\n @{" ZEILEN-EDITOR " LINK LINE-EDITOR}           @{" DOWNLOADEN " LINK DOWNLOADING}            @{" MARKIEREN " LINK MARK&FLAG}\n@endnode\n\n@node CD "DOS-KOMMANDO : CD - ÄNDERE DIRECTORY"\n\n@{u}CD - Ändere Directory@{uu}\n\nMit diesem Kommando können Sie das aktuelle Directory wechseln, z.B. wenn Sie\nsich im Directory ''CD0:AMINET/'' befinden und Sie möchten in das Directory\n''CD0:AMINET/BIZ/'', dann geben Sie einfach ''CD BIZ/ ein'', und CD-Server \nwechselt zu diesem Directory.\n\nAlle Directories, zu denen Sie wechseln möchten, beziehen sich immer auf das\naktuelle Directory, und sollte CD-Server einmal nicht das Directory wechseln,\ndann ist entweder der Pfadname ein File oder es existiert gar nicht (vom\naktuellen Directory aus gesehen!).\n\nNatürlich müssen Sie nicht jedesmal das CD - Kommando eingeben, einfach nur \ndie Angabe des Pfadnamens reicht ebenfalls aus, um das Dir zu wechseln.\n\n@{u}ACHTUNG:@{uu} Aus Sicherheitsgründen wurde die '':'' Taste deaktiviert, sollte ein\n         User diese Taste drücken, dann wechselt CD-Server automatisch zu dem\n         angegebenen Device (im CD-Server.info).\n\nGucken Sie in das Kapitel @{"LINE-EDITOR" LINK LINE-EDITOR} für weitere Infos über gesperrte\nKommandos/Tasten.\n@endnode\n\n@node PARENT "DOS-KOMMANDO : .. / - GEHE ZUR NÄCHSTHÖHEREN VERZEICHNIS-EBENE"\n\n@{u} .. / - Wechsle zur nächsthöheren Verzeichnisebene@{uu}\n\nMit diesem Kommando können Sie vom aktuellen Directory aus eine Verzeichnis-\nebene höher gehen. Dies können Sie solange machen, bis Sie zum Hauptver-\nzeichnis kommen (z.B. CD0:).\n\nWeitere Informationen über das Wechseln von Dirs können Sie im Kapitel @{"CD" LINK CD}\nlesen.\n@endnode\n\n@node INFO "DOS-KOMMANDO : INFO - GIBT INFO ÜBER VERWENDETES DEVICE AUS."\n\n@{u}INFO - Zeigt Device-Spezifische Informationen an@{uu}\n\nDieses Kommando zeigt die Informationen des Devices an, welches vom CD-Server\nverwendet wird. Beispielsweise sieht die Ausgabe bei mir so aus :\n\nDevice used..: CD0: (AMINET5)                                        \nUnit Number..: 0                                                     \nDisc Status..: Write protected                                       \nR/W Errors...: 0                                                     \nFile-System..: DOS0 (OFS)                                            \n# of Blocks..: 326334                                                \nBytes/Block..: 2048                                                  \nBytes used...: 637 MB                                                \n\nFür weitere Informationen über Devices sehen Sie bitte in Ihrem DOS-Manual\nnach.\n@endnode\n\n@node DIR "DOS-KOMMANDO : DIR - ZEIGT DIRECTORY-INHALT AN."\n\n@{u}LIST / DIR - Zeigt den Inhalt eines Directories an@{uu}\n\nDieses Kommando zeigt Ihnen den Inhalt eines beliebigen Directories an. Geben\nSie keinen Pfadnamen an, dann wird das aktuelle Directory angezeigt. Die \nAusgabe erfolgt genauso wie bei dem bekannten Directory Opus, erst werden\n(natürlich alphabetisch sortiert :) die Dirs angezeigt, danach dann die \nFiles.\n@endnode\n\n@node VIEW "DOS-KOMMANDO : VIEW/V/TYPE - ZEIGT TXT- & GUIDEFILES AN"\n\n@{u}VIEW/V/TYPE - Zeigt TXT- & Amiga-Guide Files an@{uu}\n\nMit diesem Kommando können Sie sich ein beliebiges TXT-File auf dem ver-\nwendeten Datenträger ansehen. Sollte es sich bei dem von Ihnen ausgesuchten\nFile um eine Amiga-Guide Database handeln, und Sie haben das Tool \nGUIDE2DOCPROF von FOX/RMD/ALIENGROUP in das C:-Directory kopiert, dann werden\ndiese Databases umconvertiert und anschliessend als ANSI-File angezeigt.\n\nBenutzer meines mEGA-vIEW''s sollten mit der Bedienung keinerlei Probleme \nhaben, da dies die selbe Routine iss...:)\n\n@{u}ACHTUNG:@{uu} Bitte gucken Sie sich mit diesem Kommando nur TXT- & GUIDE-Files an,\n         bei Binär-Dateien kann es zu merkwürdigen Effekten auf dem Screen\n         kommen! \n@endnode\n\n@node QUIT "DOS-KOMMANDO : ENDCLI/QUIT/Q/G - CD-SERVER BEENDEN."\n\n@{u}ENDCLI/QUIT/Q/G - CD-SERVER BEENDEN@{uu}\n\nMit diesem Kommando beenden Sie CD-Server, die geflaggten Files bleiben jedoch\nerhalten!\n@endnode\n\n@node FLAG "BBS-KOMMANDO : FLAG - MARKIERE FILES FÜR DEN DOWNLOAD."\n\n@{u}FLAG/F/A - Markiere Files zum Downloaden@{uu}\n\nDieses Kommando ist exakt das selbe wie das Flag-Kommando der Amiex (FAME\nhat hier mehr zu bieten!) und es unterstützt natürlich auch Multi-Args,z.B.\n\n                       A TEST.LHA TH.LHA LABER.LHA\n\nund die Files ''TEST.LHA'', ''TH.LHA'' & ''LABER.LHA'' werden der Flag-Liste hinzu-\ngefügt (Pfad ist das aktuelle Directory!).\n\nAls spezielle Erweiterung habe ich diesem Flag-Kommando eine Doppelfunktion\nzugewiesen:\n\n                               A C *\n\nDieses Kommando löscht 1. die bbs-interne Flagliste und 2. löscht auch ALLE\nPfade, die sich CD-Server zu diesem Zeitpunkt gemerkt hat. Desweiteren ändert\nCD-Server das aktuelle Directory zu dem Start-Dir aus Sicherheitsgründen. \nDies is sozusagen eine Art von ''Warmstart'' des CD-Servers :)))\n\nUnd als zusätzlicher Bonus ist es jetzt auch möglich, beim Flaggen einen \nPfadnamen mit anzugeben, um Files aus anderen Directories zu leechen, z.B. \n\n                  A README AMINET/BIZ/DBASE/DEMO.LHA\n\nDieser Aufruf macht folgendes, 1. wird das File README aus dem aktuellen\nDirectory in die Flagliste aufgenommen, dann wird beim zweiten File der\nPfad vom Filenamen getrennt, der Pfad CD-Server bekannt gemacht (und damit\nauch der BBS :), und nur noch der Filename der BBS übergeben. Diese Argu-\nmenten-Abfrage funktioniert auch beim Downloaden.\n\nNach zuviel Vorzügen muß es natürlich auch einen Nachteil geben...und das\nsind die Wildcards ! Sollte in einem Pfadnamen ein ''@{b}*@{ub}'' vorkommen, dann wird\ndie BBS dieses File nicht finden (außer natürlich in den Pfaden auf HD!)..\num dieses Problem zu umgehen, sollten bei Abkürzungen immer die @{"TAB-Taste" LINK LINE-EDITOR}\nverwendet werden, da diese Funktion ja automatisch die Pfadnamen erweitert!\n\nACHTUNG: Sollte es während dem Transfer zu einem Lost Carrier kommen, und die\n         BBS ist in der Lage, sich die geflaggten Files zu merken, dann müssen\n         Sie unabhängig davon noch einmal in die ganzen Directories gehen, wo\n         Sie sich die Files geflaggt haben, und jeweils einmal ''A'' + Enter\n         eingeben, damit CD-Server die Pfadnamen wieder erkennt.\n\nFür weitere Infos schauen Sie bitte in das Kapitel @{"MARKIEREN VON FILES" LINK MARK&FLAG} nach.\n@endnode\n\n@node DOWN "AMIEX-KOMMANDO : DOWN/D - DOWNLOADED ALLE GEFLAGGTEN FILES."\n\n@{u}DOWN/D - Downloaden aller geflaggten Files@{uu}\n\nNachdem Sie alle gewünschten Files @{"markiert" LINK FLAG} haben, können Sie mit Hilfe\ndieses Kommandos die Liste der Files downloaden. Da zum Downloaden die \ninternen Funktionen der jeweiligen BBS genommen werden, kann es passieren, \ndaß die BBS plötzlich abbricht und sagt das Sie Ihr Daily Limit überzogen\nhaben! Also achten Sie bitte darauf, das Sie auch wirklich die Anzahl der\nFiles, die Sie geflaggt haben, downloaden können.\n\nWie im Kapitel @{"MARIEREN VON FILES" LINK FLAG} bereits erwähnt wurde, können nach dem\n''D'' - Kommando auch Files (evtl. mit Pfadnamen relativ zum aktuellen Verz.)\nmit angeben werden.\n\nWenn Sie das Download-Kommando eingegeben haben, werden Sie von der BBS\nnoch nach weiteren Filenamen gefragt. Hier können Sie natürlich auch noch\nfiles aus dem Directory, aus dem Sie auch das ''D'' Kommando gestartet haben,\nflaggen, sowie auch Files die in den Normalen Download-Pfaden gefunden werden\nkönnen.\n\nHier dürfen Sie aber keine Pfade mehr mit angeben, da sonst die BBS das\nFlaggen abbricht mit der Meldung:\n\n            YOU DON''T HAVE TO INCLUDE ANY SPECIAL SYMBOLS !\n@endnode\n\n@node CLEAR "KOMMANDO : CLEAR/CLS - LÖSCHT DEN BILDSCHIRM"\n\n@{u} CLEAR / CLS - Löscht den Bildschirm@{uu}\n\nDieses Kommando löscht den Inhalt des Bildschirmes und setzt den Cursor an\ndie linke obere Ecke. Mehr muß man dazu glaub ich nich schreiben :)\n@endnode\n\n@node VER "KOMMANDO : VER - ZEIGT VERSIONSNUMMER VON CD-SERVER AN"\n\n@{u}VER / $ - Zeigt Version-Informationen an@{uu}\n\nWenn Sie dieses Kommando eingeben, erscheint eine Ausgabe der aktuellen\nVersionsnummer vom CD-Server, sowie das Datum der Compilierung.\n\nNatürlich kann man die Versionsnummer des Programms auch mit dem CLI-\nKommando ''VERSION'' erfragen, für weitere Informationen gucken Sie bitte\nin Ihr Amiga-Dos Manual.\n@endnode\n\n@node HELP "KOMMANDO : HELP/?/# - ZEIGT ONLINE-HILFE AN"\n\n@{u}HELP/?/# - Zeigt die Online-Hilfe an@{uu}\n\nWenn Sie mal gerade nicht wissen, wie ein Kommando heißt, bzw. es aufgerufen\nwird, dann geben Sie eine dieser Zeichenfolgen ein, und CD-Server zeigt das\nHelpfile (S:CD-SERVER.HLP) an.\n\nDa die Geschmäcker der Menschen unterschiedlich sind (Gott sei Dank! :), habe\nich das Helpfile auch extern gehalten, so kann sich das jeder Sysop selbst\nzurecht zimmern...\n@endnode\n\n@node INDEX "KOMMANDO : INDEX - SUCHT NACH INDEX-FILE UND ZEIGT ES AN"\n\n@{u}INDEX - Sucht nach dem Index-File und zeigt es ggf. an@{uu}\n\nDa ich mein CD-Rom eigentlich nur für AMINET-CD''s benutze, habe ich fest-\ngestellt, daß bei diesen Aminet-CD''s immer ein INDEX - File in jedem Dir\nzu finden ist, welches eine kurze Übersicht über das aktuelle Directory\nenthält. Wenn nun jemand etwas bestimmtes sucht, isses wohl leichter, dieses\nFile erstmal zu durchsuchen, als sich alle .readme Dateien anzuschauen. Und\ndafür is halt das Index-Kommando da, wenn sich kein Index in einem Directory\nbefindet, erhält man die Meldung : ''NOTHING TO VIEW !'' .\n\nAber wie gesagt, dieses Kommando ist halt hauptsächlich nur für die AMINET-\nCD''s gedacht, die ich persönlich für das beste an PD überhaupt halte !\n@endnode\n\n@node LINE-EDITOR "WIE MAN EFFIZIENT MIT DEM ZEILEN-EDITOR ARBEITET"\n\n@{u}Benutzung des Zeilen-Editors von CD-Server@{uu}\n\nUm den Usern ein Maximum an Komfort zur Verfügung zu stellen, hat Byte-\nAndi und meine Wenigkeit eine Menge Arbeit in die Entwicklung einer Zeilen-\nEingaberoutine gesteckt. Das Ziel war es, so weit wie möglich (und notwendig)\ndie C-Shell Eingabemöglichkeiten zu simulieren, und dieses ist auch zu 98%\ngelungen möchte ich sagen :) ... hier nun eine Liste aller Kommandos :\n\n1) TAB-Taste. Diese Taste ermöglicht die automatische Filenamen-Erweiterung.\n   Nur das Drücken der Taste veranlasst CD-Server, das aktuelle Dir zu\n   scannen und das erste gefundene File anzuzeigen. Sie können z.B. auch\n   ''AMI'' eingeben und dann TAB drücken, sodaß CD-Server evtl. die folgenden\n   Filenamen findet : AMINET/, AMINET.Z, AMINET usw. Desweiteren ist es auch\n   möglich, ganze Pfade abzukürzen, wie z.B. : \n\n   Sie geben CD */*/*/* ein und drücken dann TAB, dann könnte evtl. folgende\n   Ausgabe erscheinen : AMINET/BIZ/DBASE/DEMO.LHA.\n\n   Dieses funktioniert überall auf dem Prompt, und wir dachten uns das das\n   wohl der beste Ersatz für die ''WildCards'' ist...:)\n\n2) Vollständige Zeilen-Editierung, d.h. das Sie überall innerhalb einer\n   Zeile sich mit den CRSR-links/rechts Tasten bewegen können, Zeichen ein-\n   fügen/löschen können, mit CTRL-X die komplette aktuelle Zeile löschen etc.\n   Aber bitte daran denken, daß dieses @{b}NUR@{ub} :) eine Zeilen-Routine ist, mehr \n   als 80 Zeichen sind derzeit nicht gestattet!\n\n3) History-Buffer mit Abkürzungs-Möglichkeiten. Jede eingegebene Zeile wird\n   in einem internen Buffer gespeichert, dieser Buffer ist im Moment auf 20\n   Zeilen begrenzt, registrierte User können dann natürlich diesen ggf. auf\n   höhere Werte setzen...Wenn Sie die CRSR-Hoch/runter Tasten benutzen, dann\n   wird immer die zuletzt/zuerst eingegebene Zeile dargestellt. Dieser Buffer\n   ist auch die Basis für eine weitere nette Funktion : Das Abkürzen von\n   bereits eingegebenen Befehls-Zeilen! Stellen Sie sich vor Sie arbeiten \n   schon eine Weile mit dem CD-Server, und haben ständig das DIR Kommando\n   eingeben, und das wird nu mittlerweile lästig...dann können Sie auch z.B.\n   !di eingeben (!d geht auch!) und dann würde die Eingaberoutine nach einer\n   dementsprechenden Zeichenkette im Buffer suchen (z.B. DIR) und diese dann\n   ausführen...\n\n4) Abkürzungen der Standard-Befehle. Fast alle Befehle lassen sich durch eine\n   Taste abkürzen, z.B. das Kommando HELP -> H !\n\n5) Gesperrte Taste '':''. Diese Taste musste aus Sicherheitsgründen gesperrt\n   werden. Drücken dieser Taste befördert den User direkt in das Start-Dir,\n   das im Icon angegeben wurde...\n@endnode\n\n@node DOWNLOADING "TIPS & TRICKS FÜR DIE DOWNLOADING-GESCHICHTE"\n\n@{u}Download@{uu}\n\nWie sich wohl jeder vorstellen kann, iss es nicht einfach, in die Amiex \nWÄHREND diese läuft neue Devices (und damit auch Pfade) einzutragen und \ndiese der Amiex bekannt zu geben. Daher musste ich ein wenig tricksen :),\num das doch klar zumachen. So kann es z.B. bei Multinode-Systemen passieren,\ndas bei gleichzeitiger Benutzung des CD-Servers von mehreren Usern plötzlich\nFiles mehrere Male gefunden werden, dieses ist jedoch normal und ist einer \nder netten Nebeneffekte des Programms..:)\n\nEin anderer wichtiger Punkt ist die Tatsache, das es @{b}UNMÖGLICH@{ub} ist, mehrere\nFiles @{b}GLEICHEN@{ub} Namens auf einmal zu leechen. Das ist damit begründet, daß\nAmiex solange nach einem file sucht bis es dieses gefunden hat. Danach wird\nnach dem nächsten File gesucht, und hat dieses den gleichen Namen wie das\nFile davor, dann wird dieses geskippt.\n\nSollten Sie doch einmal zwei Files gleichen Namens leechen wollen, dann ver-\nfahren Sie bitte wie folgt:\n\nAngenommen, sie wollen das File INDEX aus Directory CD0:AMINET/ und \nDirectory CD0:AMINET/BIZ/ leechen. Dann gehen Sie zuerst in das Dir \nCD0:AMINET/, leechen das File INDEX. Dann geben Sie ''A C *'' ein, um die \ninterne Pfadliste von CD-Server zu löschen, und wechseln dann in das Dir\nCD0:AMINET/BIZ/ und leechen sich von dort das zweite INDEX-File. Sorry für\ndiese Aktion, aber ich denke mal das der gesamte Komfort von CD-Server diese\nkleinen Restriktionen aufheben sollte oder ? :)))\n\nAls kleiner Bonus sei auch nochmal auf eine Sache hingewiesen, die sonst ja\neigentlich nicht möglich ist, und zwar kann man folgendes eingeben:\n\n              d aminet/biz/dbase/data1.lha readme aminet/index\n\nund CD-Server übergibt der BBS dann nur noch die Filenamen DATA1.LHA, README\nund INDEX, merkt sich jedoch auch gleichzeitig die anderen Pfade und übergibt\ndiese mit beim suchen. Diese Funktion ist identisch mit der @{"Mark Funktion" LINK FLAG}.\n@endnode\n\n@node MARK&FLAG "TIPS & TRICKS FÜR DAS FLAGGEN DER FILES"\n\n@{u}Markieren/Flaggen von Files@{uu}\n\nWie bereits erwähnt, ist die Unterstützung der Wildcards nicht möglich. \nSollte dieser doch angegeben werden, so wird die BBS die files nicht finden,\n@{b}ALSO BITTE NICHT BENUTZEN@{ub}, stattdessen nehmen Sie halt die TAB-Taste für die\nPfadnamen-Erweiterung. Dieses Problem ist bisher für Amiex nicht lösbar (das\nFAME-System hat mittlerweile ein paar spezielle Commands für sowas, und von \ndaher is dieses Problem in einem nächsten Update bereinigt!), da der Server\nder Amiex die Conference-Icons nur einmal beim Start ins Memory liest, und\ndann alle Daten aus dem Speicher holt. Daher reagiert auch Amiex nicht auf\nneu dazugefügte ToolTypes (wie wäre es mit einem Kommando, das die Amiex\nzwingt, das jeweilige Conference-Icon neu einzulesen, ByteMaster ???) !!!\n\nAmiex hat noch einen anderen Nachteil beim Markieren von Files, und zwar ist\ndie Liste der geflaggten Files auf 2048 Bytes (oder mehr) inkl. der Spaces\nbegrenzt! Sollte also Amiex beim Flaggen abbrechen, dann ist meistens der \nString dafür voll, und Sie sollten erstmal ein paar Files leechen,bzw. einige\nFiles aus der Liste löschen. Wenn Sie das FAME-System fahren, dann wird\ndieses Problem nicht auftreten, da FAME ECHTE DYNAMISCHE LISTEN verwendet,\nund von daher nur von Ihrer Hardware begrenzt ist, nicht vom Willen des\nProgrammierers!\n\nWie bereits im Kapitel @{"DOWNLOAD" LINK DOWNLOADING} erwähnt, können Sie auch beim Flaggen von\nFiles einen Pfad mit angeben:\n\n                    A aminet/biz/patch/suxx.lha\n\nund CD-Server flaggt nur noch den Filenamen ''suxx.lha'', behält jedoch den\nPfad im Speicher und übergibt diesen dann auch beim Downloaden der BBS.\n@endnode\n\n@node GREETINGS "DIE ALLSEITS BELIEBTEN GRÜßE :)"\n\n@{u}SieGeL & ByteAndi grüßen:@{uu}\n\nSpy/trSi        - Für die Argument-Parsing & Dirscan-Routinen :)\nsTRIDER/sDC     - Für das echt GEILE @{"FAME" LINK FAME}-System :)) DER SAFT IST MIT DIR!\nARGON/dTL       - Scheisse mit dem PCMCIA-Rom, koof nen neues FileSystem Alda!\ndEATH aNGEL/sDC - Fürs Testen auf @{"FAME" LINK FAME} und überhaupt :)\nBloodRock/SDC   - Da ASM-Posse strikes back..:) \nfUTZi/tRSi      - Willkommen im Club oldae :)\n\n ...uND nATÜRLICH aLLE bETATESTER & rEGISTRIERTE uSER fÜR iHRE uNTERSTÜTZUNG,\n\n  aRTCORE! fÜR iHREN mEGA-gEILEN rEQUEST-sERVICE uND aLLE aNDEREN dIE wIR\n\n        hIER vERGESSEN hABEN zU eRWÄHNEN...fÜHLT eUCH gEGRÜSST ! :)\n\n------------------------------------------------------------------------------\n\n                           @{u}Technical Info@{uu}\n\nMain Code & Idea  : SieGeL/tRSi\nAdditional Coding : ByteAndi/tRSi (EDIT-Routine) & Spy/tRSi (Dir-Scanroutine)\nGFX painted by    : (-rAPID-) fROM dA fAMOUS aRTCORE pOSSE !\n\nCD-Server wurde auf zwei A4000/040 entwickelt und erfolgreich auf folgenden\nSystemen getestet : \n\n A5oo  5MB  68ooo           OS 2.o  Amiex 4.9        - SieGeL\nA12oo  6MB  68o2o+68881 Co. OS 3.o  Amiex 4.7        - ARGON\nA12oo 10MB  68o3o+68882 Co. OS 3.o  Amiex 4.7        - BYSIS\nA2ooo 14MB  68o3o+68882 Co. OS 2.o  @{"FAME" LINK FAME}-System      - dEATH aNGEL\nA3ooo 10MB  68o3o+68882 Co. OS 2.o  Amiex 4.6        - Spy\nA4ooo 14MB  68o3o+68882 Co. OS 3.o  @{"FAME" LINK FAME}-System      - sTRIDER\nA4ooo  6MB  68o4o+68o4o Co. OS 3.o  Amiex 4.9        - ByteAndi\nA4ooo 14MB  68o4o+68o4o Co. OS 3.1  @{"FAME" LINK FAME} & Amiex 4.9 - SieGeL\n\n            @{"(tRSi/X-iNNOVATiON) - wO sINDSE dENN ?" LINK ADDY1}\n@endnode\n\n@NODE PRGLIST "LISTE ALLER MEINER PROGRAMME BIS HEUTE !"\n\n@{u}Programm-Liste@{uu}\n\nUm Ihnen einen Überblick zu geben, was Sie als registrierter User bei mir\nbekommen, hier eine Liste aller meiner bisher geschriebenen Programme :\n\n@{b}Zur Zeit für registrierte User verfügbare Prg.:@{ub}\n\nCD-Server V1.00     - CD-Server für @{"FAME" LINK FAME}/AMIEX\nwORLD-cLOCK V1.18   - Weltzeit-Door für @{"FAME" LINK FAME}/AMIEX\nmEGA-vIEW V2.07     - Bester TXT-Viewer für @{"FAME" LINK FAME}/AMIEX\nlASTCALLERS V0.04   - Lastcaller-Util für @{"FAME" LINK FAME}, faster than SAMILOG!\nsOFT-dEL V1.01      - Schneller Online-Softdel. für @{"FAME" LINK FAME} & AMIEX\nU-sTAT V1.31        - User-Statistik Door, frei konfigurierbar (@{"FAME" LINK FAME} & /X)\nASKII-REQUEST V0.02 - aSKII-Requester Door (nur AMIEX!)\n\n@{b}Noch in Arbeit,bzw. muß überarbeitet werden:@{ub}\n\nO-Page V1.1         - Operator Page mit integrierter Highscore\nIssue-Writer V0.4   - Door um Meinungen zu schreiben, etc. (nur /X!)\noRDER V.02          - Door for Ordering sites, i.e. sell hardware via BBS..\nBBS-VIEW V1.1       - CLI-Util zum Anzeigen von ANSI-Pics, 100% ASM!\nU-Convert V0.2      - Util zum Konvert. von /X user.data -> @{"FAME" LINK FAME} user.data\nBullcreator V1.0    - Highscore-Util für ByteKiller V1.0, wird noch geupdated\n\nIch denke mal, 30,- DM (bzw.$20) ist ja wohl nicht zuviel für diese Programme,\noder etwa doch ? Und natürlich werde ich, soweit es machbar ist, auch alle \nWünsche oder Neuheiten in diese Programme einsetzen...um mit uns in Kontakt\nzu treten, bitte mal in Kapitel @{"CONTACTS" LINK ADDY1} nachsehen.\n@endnode\n\n@node FAME "WAS ZUM TEUFEL IS EIGENTLICH FAME ????"\n\n''Was ist FAME ?'' , werden Sie fragen...FAME ist ein neues BBS-System,welches\nvon Strider (Syndicate) geschrieben wird, und zu 90% kompatibel zu Standard-\nAmiexdoors ist. Natürlich hat es auch einen komplett eigenen Msg-Port mit\nweit über 1000 (!!) Kommandos. Desweiteren ist dieses System komplett von\nder verwendeten Hardware abhängig, was bedeutet, um so mehr RAM, umso mehr\nkann man auch durchdrehen...:)\n\nDie Konfiguration der BBS erfolgt über ein sehr komfortablen SystemEditor,\nwelcher VOLLSTÄNDIG OHNE ICONS die BBS konfiguriert und dabei komplett mit\nder Maus zu bedienen ist. Die Kontrolle der BBS läuft über einen ebenfalls\nkomplett mit der Maus bedienbaren Server (Commodity!).\n\nDadurch das die BBS noch in der Entwicklungs-Phase steckt, ist sie derzeit\nauch noch nicht erhältlich, aber wenn Sie weitere Informationen über dieses\nSystem haben wollen, dann melden Sie sich bei uns und wir geben Ihnen dann\nalle Informationen die Sie brauchen.\n@endnode\n\n@node ADDY1 "(tRSi/X-iNNOVATiON) WHQ & Beta Site"\n\n@{APEN 2}                           hOW tO cONTACT uS : @{aPEN 1}\n\n   _____________  __________               /\\\n  |     __     /__\\__      /___________   /  \\             _____\n  |   ________/    /      /_\\____      \\_//   \\___________|_____|_______\n  |     |  \\      /      /      /      _//     \\    ______________      \\_\n  l_____|   \\___________/______/       \\_______/\\______   \\_    l/       /\n                              \\________/      /____________/____/       /\n                                       _________________       \\_______/\n     ______ /\\____ ____________ _______\\______   ______/\n    /      /_      \\    __    /_\\_____      \\_    |\n  _/      \\/______/   _______/\\      /       /    |    · PUN¡sHMeNT ¡NC. ·\n  \\________\\    _/_____________\\____/  Mo!  /_____|\n                /                  \\_______/\n                                           /\\  ______________  ___________\n     1oo% LeGaL sTUFF oN aM¡Ga^PC         /  \\_\\_______      \\_\\    _____/___\n                                         //   \\       /       /     /       /\n     RUNN¡NG oN a4ooo/4o · V.FasT      _//     \\_____/       /_____________/\n                                       \\________/   \\_______/\n\n TR¡sTaR & ReD seCToR ¡NC. (/X·¡NNoVaT¡oN) WHQ, aRTcORE! GHQ & eTH¡C D¡sT s¡Te\n\n   [> +49-(o)-3o-694-84-7o <]  sYsoP: s¡eGeL/TRs¡  [> +49-(o)-3o-694-sOON! <]\n\n                     @{"> pARALYSIS BBS - dISTRIBUTION sITE <" LINK ADDY2}\n@endnode\n\n@node ADDY2 "(tRSi/X-iNNOVATiON) bETA & dIST SITE"\n       ____                                                                  \n    ___\\  /______________________________________________________________    \n   /   \\\\//                                                              \\   \n  /     \\/ -[ THe BeST eQUiPPeD PuBLIC DoMAIN BoaRD IN BeRLIN ]-          \\  \n /   -[ WiTH 4 GReaT U.S.ROBOTICS V.FAST CLASS MoDeMS WiTH FLaSH-RoMS ]-   \\ \n/                                                                           \\\n\\                        -- -[ SYNDIC/\\TE WHQ ]- --                         /\n \\   _____  _____    _____   _____  __      ___ __  _____   ___ _____      / \n  \\ /  _  \\/  _  \\  /  _  \\ /  _  \\/  |___ /   |  \\/   __)_/ __|   __)_   /  \n   /   |   \\  _   \\/   |  //   _   \\  |   \\\\_____  \\___    \\¯  |___    \\ /   \n  /   _____/  |    \\_ __   \\_  |    \\ |    \\   |    \\|      \\  | |      \\    \n  \\____| \\____|    /___|    /__|    /___   / _______/___    /__|____    /    \n      \\       l___/    l___/   l___/  \\___/___/  [ViC!]\\___/       \\___/     \n       \\                                                             /       \n        \\SYSTeM CHieFS: SPY/TRSi,ARTHuR DeNT,PHaNToM,Cat,JTC,big-rat/        \n         \\                                                         /         \n          \\   1: +49(0) 30 721 6071 USR DuAL STaNDaRD V.34 28.8   /          \n           \\  2: +49(0) 30 721 6072 USR DuAL STaNDaRD V.34 28.8  /           \n            \\ 3: +49(0) 30 721 6073 USR DuAL STaNDaRD V.34 28.8 /            \n             \\4: +49(0) 30 722 6065 USR DuAL STaNDaRD V.34 28.8/             \n              \\                                   /\\          /              \n               \\_________________________________//\\\\________/               \n                                                 /__\\\n\n                        SUPPORTS ONLY PD-/SHAREWARE !\n@endnode\n','\n',char(10)),NULL,'auto-added',60218,9,0,NULL,NULL,'trsi_cd1','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_cds','TRSI-CDS.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-CDS.LHA','CD-SERVER','XIM','CD-SERVER',NULL,'SieGeL','TRSI','\    ____    )  /___/\_| & rED sECTOR ¡NC | .-\___\ | \___\__   /   |  /X-¡NNOVATION   | `---|___|___|______/____|---[ PRESENTS ]---''',replace(' _____________ ___Mo! __.<---[ tRISTAR ]---.\n \    ____    )  /___/\_| & rED sECTOR ¡NC |\n.-\___\ | \___\__   /   |  /X-¡NNOVATION   |\n`---|___|___|______/____|---[ PRESENTS ]---''\n    CD-Server V1.03p by SieGeL & ByteAndi\n.------------------------------------------.\n| FIRST PUBLIC UPDATE,ALL KNOWN BUGS FIXED |\n| NOW WITH MULTIDEVICE- AND ASSIGN-SUPPORT |\n| BETTER FAME-SUPPORT, LONG PATHES WORKING |\n`------------------------------------------''\n A TOOL FROM THE "REAL" (tRSi/X-iNNOVATiON)\n','\n',char(10)),'CD-sERVER_DEUTSCH.guide',replace('@database CD-sERVER V1.03 - Deutsches DataBase\n@author "SieGeL/tRSi"\n@(c) "Copyright © 1995 (tRSi/X-iNNOVATiON)"\n@$VER: CD-SERVER.guide 1.03 (17.08.95)\n\n@index Main\n\n@node Main "CD-Server - BBS Tool geschrieben von SieGeL & ByteAndi (tRSi/X-iNNOVATiON)"\n@{b}                                                                     ______\n .-----------[ TRSI (/X·INNOVATION) ]------------.       _  ________/     /\n | _________________________________       ______`-------\\//  __    \\    /---.\n | \\       _____________     /     /______(______)  _     /    \\     \\  /    |\n |  \\______\\    |    __/   _/\\______       /     | (/)   /     /\\     \\/ Mo! |\n | \\     |      |    \\      \\       |     /      |  ¯   /     / /\\     \\_    |\n | \\\\    l______|_____\\      \\___________/_______|    _/     /_/  \\_____/    |\n `---------------------\\______/-----------------------\\_____/-\\_____/--------''@{ub}\n\n                           iS pROUD tO pRESENT:\n\n@{APEN 2}             CD-Server V1.03 public written by SieGeL & ByteAndi@{APEN 1}\n                                                                          \n                      @{" COPYRIGHT! " LINK COPYRIGHT}     @{"VERTREIBUNG!" LINK DISTRIBUTION}\n                      @{" EINFÜHRUNG " LINK EINFÜHRUNG}     @{"INSTALLATION" LINK INSTALLATION}\n                      @{" BEDIENUNG! " LINK HOW2USE}     @{" -CREDITZ!- " LINK GREETINGS}\n\n Der erste "@{b}ECHTE@{ub}" Server für jedes Amiga-DOS kompatible device,z.B. CD-Rom !\n@endnode\n\n@NODE COPYRIGHT "Copyright-Information für dieses Programm"\n\n     @{u}Copyright@{uu}\n\n   Dieses Programm ist ''FreeWare''.\n\n Es darf frei kopiert und für nicht kommerzielle Zwecke vertrieben werden,\n solange sicher gestellt ist, das kein file (ausser natürlich BBS-Addys)\n zu diesem Archiv dazugepackt oder aus diesem Archiv entnommen wird, und \n das für diese Veröffentlichung nicht mehr Geld, als für die Erstattung des\n Datenträgers/Kopierkosten, notwendig ist, verlangt wird.\n\n Das volle Copyright auf den Programmcode liegt bei dem Author (also meine\n Wenigkeit!) selbst, und ohne meine schriftliche Genehmigung ist es nicht \n erlaubt, dieses Programm kommerziell zu vertreiben.\n\n Diese Version von CD-Server ist die EINZIGSTE, die unter dem Prinzip der\n ''FreeWare'' vertrieben wird, alle anderen Updates (Fehlerbereinigungen etc.)\n sind dann nur noch für registrierte User verfügbar. Wenn Sie registrierter\n User bei mir werden möchten, dann haben Sie eine Registrierungs-Gebühr in\n Höhe von 30.- DM ($20) zu bezahlen.\n\n Diese Registrierungsgebühr ist natürlich nur einmalig zu entrichten, nach\n der Bezahlung erhalten Sie vollen Zugriff auf mein Register-Door und können\n dann frei über ALLE meine Tools verfügen.\n\n Alles weitere können Sie dann mit mir in meiner @{"BBS" LINK ADDY1} besprechen. Einfach\n mal durchcallen und ''SieGeL/tRSi'' eine Mail hinterlassen, ich kläre dann\n alles weitere.\n\n            @{"LISTE ALLER BISHER VON MIR VERFASSTEN PROGRAMME" LINK PRGLIST}\n@endnode\n\n@NODE DISTRIBUTION "Vertreibung von CD-Server"\n\n     @{u}Verbreitung/Vertreibung@{uu}\n\n  Hiermit genehmige ich die Veröffentlichung von diesem Archiv, solange wie\n  nicht mehr Geld, als für die Erstattung der Kopier-kosten etc. notwendig\n  sind, verlangt wird, und solange dieses Archiv nur in seinem Original-\n  zustand vertrieben wird. \n\n  Das Copyright liegt bei dem Author (also mir !) selbst, und ohne meine \n  schriftliche Genehmigung darf dieses Programm nicht kommerziell vertrieben \n  werden.\n@ENDNODE\n\n@node EINFÜHRUNG "Einleitung, oder warum dieses Programm entstanden ist."\n\n@{u}Einleitung@{uu}\n\nVor ein paar Monaten hatten wir die erste Version von dem CD-Server ver-\nöffentlicht, und es hat den Anschein das dieses Tool für Sysops mit CD-Roms\nein nützliches Tool geworden ist...aber wie wir ja alle wissen, ist niemand\nvollkommen, und auch wir haben einige Fehler in der ersten Version gemacht.\n\nNachdem wir die gröbsten Bugs aus der V1.00 entfernt hatten, haben wir uns\ndarauf geeinigt, entgegen der Beschreibung der V1.00 nun doch noch ein\nPublic Update zu releasen, da die V1.00 doch arg heftige Bugs hatte...\n\nNatürlich wurden auch wieder ein paar neue Dinge eingebaut, nun ist es z.B.\nmöglich, Devices & Assigns (!!!) zu verwalten. Um dieses feature zu ver-\nwenden, müssen Sie einfach ein Assign erzeugen, welches auf dem Directory\nzeigt, das Sie auch den Usern zur Verfügung stellen möchten. Dieses Assign\nwird dann im Icon von CD-Server vermerkt, und schon können die User auch\ndieses Assign "besuchen" ...\n\n@{u}Merkmale von CD-Server@{uu}\n\n - Ermöglicht Downloaden/Anzeigen von TXT-files @{b}DIREKT@{ub} von CD-Rom, ohne\n   lästige Kopierei!\n\n - @{b}Komplette C-Shell Bedienung@{ub}, z.B. @{b}TAB@{ub}-Taste für @{b}Pfadnamen-Erweiterung@{ub},\n   das ''@{b}!@{ub}'' Zeichen als Abkürzung von Befehlen im @{b}20-Zeilen Buffer@{ub}, voll-\n   ständige @{b}CRSR-Key@{ub} Simulierung (Hoch/runter für Buffer,links/rechts um\n   in der Zeile hin und her zu laufen) usw...\n\n - Unterstützt auch @{b}UNIX@{ub}-Kommandos, wie z.B. ''@{b}..@{ub}'' für Parent-Dir etc.\n\n - Eingebaute Unterstützung für GUIDE-Dateien, um diese als ANSI-Files\n   umzuwandeln und anzuzeigen\n\n - Benutzt BBS-interne Download- und FlagFile Routinen ohne das man @{b}ALLE@{ub}\n   Pfade in das Icon eintragen muss, daher auch flexibel im CD-Wechsel!\n\n - @{b}Amiex V3.++@{ub} und @{"FAME" LINK FAME} (Final Amiga Mailbox Engine) kompatibel\n\n - Braucht bis auf das Guide2DocProf @{b}KEINE@{ub} weiteren Befehle aus dem C: dir.\n\n - Sau-schnelle Directory-Scan routine mit der selben Ausgabe wie der all-\n   seits bekannte und beliebte Directory Opus :)) \n\n (V1.03)\n\n - Assign-Unterstützung funktioniert 100%-ig.\n\n - Die @{"Registrierte Version" LINK REGVERSION} hat noch mehr Funktionen.... \n\n@{u}Was man alles für den CD-Server braucht@{uu}\n\nBevor Sie dieses Programm installieren, müssen ein paar Bedingungen erfüllt\nsein...zum ersten , haben Sie ein Device (CD0: als Beispiel) oder ein\nDirectory, welches Sie KOMPLETT als Datenträger der BBS zur Verfügung \nstellen können ? \n\nDann ist in der Testphase aufgefallen, das bei Benutzung eines PCMCIA-\nControllers in Verbindung mit einem Mitsumi FX-400 CD-Rom ein Fehler auf-\ngetreten ist beim Anzeigen von Text-files. Dieser Fehler liegt nicht an\nunserer Dummheit (!!!), sondern einzig und allein daran, das dieses \npcmcia.device (oder wie auch immer) den FileInfoBlock von ADOS nicht richtig\nunterstützt, und von daher es zu merkwürdigen Fehlern kommt. Sollte dieses\nbei Ihnen der Fall sein, dann wenden Sie sich bitte an den Author dieses\nDevices, und bitten ihn um ein Update. Soweit es ging werden solche Fehler\ntransparent von CD-Server behandelt, Sie bekommen davon eigentlich nix mit.\n\nDann zu guter letzt iss natürlich klaro, das dieses Tool min. Kickstart V37\noder höher benötigt, aber wer hat schon noch 1.3 ;), und als BBS sollte\nmindestens eine Amiex V3.++ oder höher installiert sein, oder halt die @{"FAME" LINK FAME},\nwobei hier die Version noch nicht wichtig ist..:)\n\n                @{"ZUR INSTALLATION GEHTS HIER LANG :)" LINK INSTALLATION"}\n@endnode\n\n@node INSTALLATION "Wie man CD-Server auf Ihr System installiert."\n@NEXT HOW2USE\n\n@{u}Allgemeine Installation@{uu}\n\nAm besten installieren Sie CD-Server mit Hilfe des beigelegtem Installer-\nSkripts, möchten Sie "per Hand" installieren, sind diese Schritte zu \nbefolgen:\n\n1.Kopieren Sie das Directory ''CD/'' zu Ihrem Doors: Verzeichnis, oder wo immer\n  Sie Ihre BBS-Tools auch aufbewahren.\n\n2.Kopieren Sie das File CD-SERVER.HLP'' nach Ihr S: Directory, dieses File\n  ist die Online-Hilfe von CD-Server.\n\n3.Kopieren Sie das File ''GUIDE2DOCPROF'' nach Ihr C: Directory, dieses File\n  wird zum Umwandeln der AmigaGuides zu ANSI-Files benötigt.\n\n4.Editieren Sie die Tooltypes im Icon ''CD-Server.info'', es werden folgende\n  Tooltypes unterstützt:\n\n  PACKDIR=RAM:      -> Hier können Sie optional ein Directory angeben, \n                       welches dann als temporäres Dir gilt, hierher werden\n                       die umgewandelten Guides geschrieben. Wenn dieses \n                       Tooltype nicht gesetzt ist, wird standardmässig das\n                       T: Directory genommen.\n                           \n  MAX_DEVICES=<NUM> -> Hier legen Sie die maximale Anzahl der zu unter-\n                       stützenden Geräte fest. Fehlt dieses Tooltype, dann\n                       wird von CD-Server automatisch die Anzahl der Geräte\n                       auf 1 gesetzt und als Standard-Gerät wird dann das\n                       Gerät ''CD0:'' genommen.\n\n  DEVICE.<x>=<DEV>  -> Definiert Gerät Nummer <x> als <DEV>, z.B.:\n\n                                 DEVICE.1=CD0:\n                                 DEVICE.2=TREK:\n \n                       Wenn CD-Server nichtmal das ToolType DEVICE.1 findet,\n                       wird als Vorgabe-Gerät ''CD0:'' und als MAX_DEVICES\n                       eins verwendet.\n\n  NAME.<x>=<STRING> -> Hier können Sie für das jeweilige Gerät eine Kurz-\n                       beschreibung angeben, die dann in der Geräteauswahl\n                       angezeigt wird. Wird dieses Tooltype ausgelassen,\n                       zeigt CD-Server als Beschreibung ''N/A!'' an. Die\n                       maximale Länge der Beschreibung darf 60 Zeichen nicht\n                       überschreiten, längere Beschreibungen werden gecuttet.\n                       Beispiele:\n\n                                  NAME.1=AMINET 5 CD\n                                  NAME.2=All about StarTrek: Samples, Pics\n                    \n5.Zu guterletzt müssen Sie CD-Server noch in Ihr BBS-System einbinden. Bitte\n  wählen Sie das System, das bei Ihnen installiert ist : @{"AMIEX" LINK AMIEX_INSTALL} oder @{"FAME" LINK FAME_INSTALL} .\n\n6.Nach einem Reset sollte jetzt CD-Server einsatzbereit sein...\n@endnode\n\n@node AMIEX_INSTALL "CD-Server auf ein Amiex-System installieren."\n@PREV INSTALLATION\n@NEXT INSTALLATION\n\n@{u}Installation für Amiex-Betreiber:@{uu}\n\n1.Erzeugen Sie ein ASSIGN namens ''SERVER:''. Dieses Assign sollte am besten \n  nach T: assigned werden, da T: normalerweise nach RAM:T/ zeigt, und von \n  daher am schnellsten ist. Und keine Panik, ich kopiere keine Files nach \n  ''SERVER:'', CD-Server braucht dieses Assign nur, um mit der AMIEX zu \n  kommunizieren :) \n  Am besten Sie schreiben folgende Zeile in Ihre ''user-startup'' :\n\n                       ASSIGN >NIL: SERVER: T: DEFER\n\n  Wenn Sie CD-Server mit dem Installer installieren, dann wird diese Zeile\n  automatisch in Ihre user-startup eingefügt.\n\n2. Kopieren Sie das Icon ''CD.INFO'' in das Directory ''BBS:COMMANDS/BBSCMD'',\n   und ändern Sie gegebenenfalls den Pfad im Icon zu CD-Server.\n\n3. Editieren Sie alle Conference-Icons, in denen CD-Server laufen soll,\n   und tragen Sie in diese bitte ein neues DLPATH-ToolType ein:\n\n                        DLPATH.(x)=SERVER:\n\n   wobei (x) fuer die nächsthöhere Nummer der DLPATHES im jeweiligen \n   Conference-Icon steht. Angenommen, Sie haben die folgenden Tooltypes in\n   Ihrem AMIGA.INFO Conference-Icon:\n\n                         DLPATH.1=BBS:AMIGA/UPLOAD/\n                         DLPATH.2=DH2:AMIGA/UPLOAD/\n\n   dann tragen Sie für den CD-Server ein :\n\n                         DLPATH.3=SERVER:\n\n   Sie müssen dieses Tooltype in JEDEM Conference-Icon eingeben, in denen auch\n   CD-Server korrekt funktionieren soll...\n\n3. Starten Sie nun Amiex neu, da der Server alle Icons im Speicher behält,\n   und von daher auch nicht auf die Änderungen reagieren kann (Bitte ändern,\n   ByteMaster, das iss ja nu wirklich das letzte...:( ).\n\nDas ist alles für die Installation auf Amiex.\n@endnode\n\n@node FAME_INSTALL "CD-Server auf ein FAME-System installieren."\n@PREV INSTALLATION\n@NEXT INSTALLATION\n\n@{u}Installation für FAME-Betreiber:@{uu}\n\n1. Starten Sie den SystemEditor, gehen Sie in das Menü ''DOORS'', und lesen Sie\n   das File ''CD'' ein, welches diesem Archiv beigefügt ist.\n\n2. Editieren Sie den Pfad zu CD-Server, Accesslevel etc. nach Ihren eigenen\n   Wünschen und speichern Sie es im Directory ''FAME:SETTINGS/DOORS/BBSCMD/''.\n  (Bitte daran denken, das dieses Door als XIM angelegt wird, nicht als FIM!)\n\nDas iss alles für die @{"FAME" LINK FAME}-Installation. Unter @{"FAME" LINK FAME} wird das Assign nicht\nmehr länger benötigt !\n\nNun können Sie bereits den CD-Server antesten...\n@endnode\n\n@node HOW2USE "Übersicht aller Kommandos von CD-Server"\n\n@{u}Kommando-Übersicht@{uu}\n\n  @{b}DOS-KOMMANDOS@{ub}            @{b}AMIEX-KOMMANDOS@{ub}        @{b}ANDERE KOMMANDOS@{ub}\n\n   @{"    CD    " LINK CD}               @{"  FLAG/A/F " LINK FLAG}            @{"   CLEAR   " LINK CLEAR}\n   @{"   .. /   " LINK PARENT}               @{"   DOWN/D  " LINK DOWN}            @{"   VER/$   " LINK VER}\n   @{"   INFO   " LINK INFO}               @{"   VIEW/D  " LINK VIEW}            @{"  HELP/#/? " LINK HELP}\n   @{" LIST/DIR " LINK DIR}               @{"   QUIT/G  " LINK QUIT}            @{"   INDEX   " LINK INDEX}\n   @{"   TYPE   " LINK VIEW}               @{"  ZIPPY/Z  " LINK ZIPPY}            @{"  CHANGE   " LINK CHANGE}\n   @{"  ENDCLI  " LINK QUIT}\n\n@{u}Allgemeine Bedienung@{uu}\n\n @{" ZEILEN-EDITOR " LINK LINE-EDITOR}           @{" DOWNLOADEN " LINK DOWNLOADING}            @{" MARKIEREN " LINK MARK&FLAG}\n@endnode\n\n@node CD "DOS-KOMMANDO : CD - ÄNDERE DIRECTORY"\n\n@{u}CD - Ändere Directory@{uu}\n\nMit diesem Kommando können Sie das aktuelle Directory wechseln, z.B. wenn Sie\nsich im Directory ''CD0:AMINET/'' befinden und Sie möchten in das Directory\n''CD0:AMINET/BIZ/'', dann geben Sie einfach ''CD BIZ/ ein'', und CD-Server \nwechselt zu diesem Directory.\n\nAlle Directories, zu denen Sie wechseln möchten, beziehen sich immer auf das\naktuelle Directory, und sollte CD-Server einmal nicht das Directory wechseln,\ndann ist entweder der Pfadname ein File oder es existiert gar nicht (vom\naktuellen Directory aus gesehen!).\n\nNatürlich müssen Sie nicht jedesmal das CD - Kommando eingeben, einfach nur \ndie Angabe des Pfadnamens reicht ebenfalls aus, um das Dir zu wechseln.\n\n@{u}ACHTUNG:@{uu} Aus Sicherheitsgründen wurde die '':'' Taste deaktiviert, sollte ein\n         User diese Taste drücken, dann wechselt CD-Server automatisch zu dem\n         angegebenen Device (im CD-Server.info).\n\nGucken Sie in das Kapitel @{"LINE-EDITOR" LINK LINE-EDITOR} für weitere Infos über gesperrte\nKommandos/Tasten.\n@endnode\n\n@node PARENT "DOS-KOMMANDO : .. / - GEHE ZUR NÄCHSTHÖHEREN VERZEICHNIS-EBENE"\n\n@{u} .. / - Wechsle zur nächsthöheren Verzeichnisebene@{uu}\n\nMit diesen Kommandos können Sie vom aktuellen Directory aus eine Verzeichnis-\nebene höher gehen. Dies können Sie solange machen, bis Sie zum Hauptver-\nzeichnis des Gerätes/Assigns kommen (z.B. CD0:).\n\nWeitere Informationen über das Wechseln von Dirs können Sie im Kapitel @{"CD" LINK CD}\nlesen.\n@endnode\n\n@node INFO "DOS-KOMMANDO : INFO - GIBT INFO ÜBER VERWENDETES DEVICE AUS."\n\n@{u}INFO - Zeigt Device-Spezifische Informationen an@{uu}\n\nDieses Kommando zeigt die Informationen des Devices an, welches vom CD-Server\nverwendet wird. Beispielsweise sieht die Ausgabe bei mir so aus :\n\nDevice used..: CD0: (AMINET5)                                        \nUnit Number..: 0                                                     \nDisc Status..: Write protected                                       \nR/W Errors...: 0                                                     \nFile-System..: DOS0 (OFS)                                            \n# of Blocks..: 326334                                                \nBytes/Block..: 2048                                                  \nBytes used...: 637 MB                                                \n\nFür weitere Informationen über Devices sehen Sie bitte in Ihrem DOS-Manual\nnach.\n@endnode\n\n@node DIR "DOS-KOMMANDO : DIR - ZEIGT DIRECTORY-INHALT AN."\n\n@{u}LIST / DIR - Zeigt den Inhalt eines Directories an@{uu}\n\nDieses Kommando zeigt Ihnen den Inhalt eines beliebigen Directories an. Geben\nSie keinen Pfadnamen an, dann wird das aktuelle Directory angezeigt. Die \nAusgabe erfolgt genauso wie bei dem bekannten Directory Opus, erst werden\n(natürlich alphabetisch sortiert :) die Dirs angezeigt, danach dann die \nFiles.\n@endnode\n\n@node VIEW "DOS-KOMMANDO : VIEW/V/TYPE - ZEIGT TXT- & GUIDEFILES AN"\n\n@{u}VIEW/V/TYPE - Zeigt TXT- & Amiga-Guide Files an@{uu}\n\nMit diesem Kommando können Sie sich ein beliebiges TXT-File auf dem ver-\nwendeten Datenträger ansehen. Sollte es sich bei dem von Ihnen ausgesuchten\nFile um eine Amiga-Guide Database handeln, und Sie haben das Tool \nGUIDE2DOCPROF von FOX/RMD/ALIENGROUP in das C:-Directory kopiert, dann werden\ndiese Databases umconvertiert und anschliessend als ANSI-File angezeigt.\n\nBenutzer meines mEGA-vIEW''s sollten mit der Bedienung keinerlei Probleme \nhaben, da dies die selbe Routine iss...:)\n\n@{u}ACHTUNG:@{uu} Bitte gucken Sie sich mit diesem Kommando nur TXT- & GUIDE-Files an,\n         bei Binär-Dateien kann es zu merkwürdigen Effekten auf dem Screen\n         kommen! \n@endnode\n\n@node QUIT "DOS-KOMMANDO : ENDCLI/QUIT/Q/G - CD-SERVER BEENDEN."\n\n@{u}ENDCLI/QUIT/Q/G - CD-SERVER BEENDEN@{uu}\n\nMit diesem Kommando beenden Sie CD-Server, die geflaggten Files bleiben jedoch\nerhalten!\n@endnode\n\n@node FLAG "BBS-KOMMANDO : FLAG - MARKIERE FILES FÜR DEN DOWNLOAD."\n\n@{u}FLAG/F/A - Markiere Files zum Downloaden@{uu}\n\nDieses Kommando ist exakt das selbe wie das Flag-Kommando der Amiex (@{"FAME" LINK FAME}\nhat hier mehr zu bieten!) und es unterstützt natürlich auch Multi-Args,z.B.\n\n                       A TEST.LHA TH.LHA LABER.LHA\n\nund die Files ''TEST.LHA'', ''TH.LHA'' & ''LABER.LHA'' werden der Flag-Liste hinzu-\ngefügt (Pfad ist das aktuelle Directory!).\n\nAls spezielle Erweiterung habe ich diesem Flag-Kommando eine Doppelfunktion\nzugewiesen:\n\n                               A C *\n\nDieses Kommando löscht 1. die bbs-interne Flagliste und 2. löscht auch ALLE\nPfade, die sich CD-Server zu diesem Zeitpunkt gemerkt hat. Dieses wird aber\nnur bei der AMIEX gemacht, da die @{"FAME" LINK FAME} dieses Vorgehen nicht benötigt.\nDesweiteren ändert CD-Server das aktuelle Directory zu dem Start-Dir \naus Sicherheitsgründen. \nDies is sozusagen eine Art von ''Warmstart'' des CD-Servers :)))\n\nUnd als zusätzlicher Bonus ist es jetzt auch möglich, beim Flaggen einen \nPfadnamen mit anzugeben, um Files aus anderen Directories zu leechen, z.B. \n\n                  A README AMINET/BIZ/DBASE/DEMO.LHA\n\nDieser Aufruf macht folgendes, 1. wird das File README aus dem aktuellen\nDirectory in die Flagliste aufgenommen, dann wird beim zweiten File der\nPfad vom Filenamen getrennt, der Pfad CD-Server bekannt gemacht (und damit\nauch der AMIEX :), und nur noch der Filename der BBS übergeben. Bei der @{"FAME" LINK FAME}\nwird dieses Vorgehen nicht mehr benötigt, da man dort auch direkt Pfade an-\ngeben kann, daher ist auch das ASSIGN nicht mehr nötig.\nDiese Argumenten-Abfrage funktioniert auch beim Downloaden.\n\n@{u}AMIEX-SYSOPS:@{uu}\n\nNach soviel Vorzügen muß es natürlich auch einen Nachteil geben...und das\nsind die Wildcards ! Sollte in einem Pfadnamen ein ''@{b}*@{ub}'' vorkommen, dann wird\ndie BBS dieses File nicht finden (außer natürlich in den Pfaden auf HD!)..\num dieses Problem zu umgehen, sollten bei Abkürzungen immer die @{"TAB-Taste" LINK LINE-EDITOR}\nverwendet werden, da diese Funktion ja automatisch die Pfadnamen erweitert!\n\n@{u}ACHTUNG:@{uu} Sollte es während dem Transfer zu einem Lost Carrier kommen, und die\n         BBS ist in der Lage, sich die geflaggten Files zu merken, dann müssen\n         Sie unabhängig davon noch einmal in die ganzen Directories gehen, wo\n         Sie sich die Files geflaggt haben, und jeweils einmal ''A'' + Enter\n         eingeben, damit CD-Server die Pfadnamen wieder erkennt.\n\nSollte es trotzdem immer noch Probleme beim Finden der Files finden, dann\nlassen Sie sich @{"registrieren" LINK REGVERSION} und ich gebe Ihnen eine Lösung für dieses\nProblem, auch wenn es nich gerade die eleganteste Art ist...\n\n@{u}FAME-SYSOPS:@{uu}\n\nVergessen Sie alle oben genannten Einschränkungen, nach Absprache mit dem\nAuthor der @{"FAME" LINK FAME} ist es nun möglich, Wildcards zu verwenden, die Geräte zu\nwechseln ohne das die Flaglisten verloren gehen, und sogar das Rausfliegen\nund merken der ''LostCarrierFiles'' läuft perfekt !\n\nFür weitere Infos schauen Sie bitte in das Kapitel @{"MARKIEREN VON FILES" LINK MARK&FLAG} nach.\n@endnode\n\n@node DOWN "AMIEX-KOMMANDO : DOWN/D - DOWNLOADED ALLE GEFLAGGTEN FILES."\n\n@{u}DOWN/D - Downloaden aller geflaggten Files@{uu}\n\nNachdem Sie alle gewünschten Files @{"markiert" LINK FLAG} haben, können Sie mit Hilfe\ndieses Kommandos die Liste der Files downloaden. Da zum Downloaden die \ninternen Funktionen der jeweiligen BBS genommen werden, kann es passieren, \ndaß die BBS plötzlich abbricht und sagt das Sie Ihr Daily Limit überzogen\nhaben! Also achten Sie bitte darauf, das Sie auch wirklich die Anzahl der\nFiles, die Sie geflaggt haben, downloaden können.\n\nWie im Kapitel @{"MARIEREN VON FILES" LINK FLAG} bereits erwähnt wurde, können nach dem\n''D'' - Kommando auch Files (evtl. mit Pfadnamen relativ zum aktuellen Verz.)\nmit angeben werden.\n\nWenn Sie das Download-Kommando eingegeben haben, werden Sie von der BBS\nnoch nach weiteren Filenamen gefragt. Hier können Sie natürlich auch noch\nfiles aus dem Directory, aus dem Sie auch das ''D'' Kommando gestartet haben,\nflaggen, sowie auch Files die in den Normalen Download-Pfaden gefunden werden\nkönnen.\n\nHier dürfen Sie aber keine Pfade mehr mit angeben, da sonst die BBS das\nFlaggen abbricht mit der Meldung:\n\n            YOU DON''T HAVE TO INCLUDE ANY SPECIAL SYMBOLS !\n@endnode\n\n@node ZIPPY "AMIEX-KOMMANDO : ZIPPY SUCHE DATEIEN AUF GERÄTEN ODER IN TEXTEN"\n\n@{u}ZIPPY/Z - Sucht Dateien auf Geräten oder in Textdateien@{uu} (nur reg.Version!)\n\nDieses Kommando erlaubt es Ihnen, nach Dateien auf Geräten,bzw. Directories\nzu suchen oder eine bestimmte Zeichenkette innerhalb einer Textdatei zu\nsuchen. Wenn das Gerätesuchen verwendet wird, kann es je nach verwendetem\nDatenträger zu einigen Minuten Suchzeit kommen, es sollte also besser nach\nMöglichkeit vorher z.B. in einer INDEX Datei nach dem gesuchten Filenamen\ngesucht werden, da diese Methode weitaus schneller und vor allem Geräte-\nschonender ist..:)\n\nBei Verwendung des Textsuchens werden Sie zuerst nach dem zu durchsuchendem\nTextfile gefragt, Sie können hier natürlich auch einen relativen Pfad zum\naktuellen Directory angeben. Existiert dieses File, werden Sie anschliessend\nnach der Suchzeichenkette gefragt. Bitte hier KEINE Patterns verwenden!\nWird diese Zeichenkette gefunden, so springt die Suchfunktion an die Stelle\nim Text und stellt die Zeile, in der die Zeichenkette gefunden wurde, auf\ndem Bildschirm dar. Dabei wird die gesuchte Zeichenkette in Grün hervor-\ngehoben.\n\nWie oben schon erwähnt sollte auf jeden Fall die Textsuche dem Geräte-\nsuchen vorgezogen werden. Sollten Sie jedoch das Gerätesuchen wirklich\neinmal brauchen, dann werden Sie zuerst nach dem zu suchenden Dateinamen\ngefragt. Danach können Sie noch angeben, ob CD-Server rekursiv in allen\nUnter-Directories suchen soll oder die Suche auf das aktuelle Directory\nbeschränken soll. Wird der Dateiname gefunden, werden Sie gefragt, ob Sie\ngleich in das gefundene Directory wechseln wollen oder ob der gefundene\nEintrag nur angezeigt werden soll.\n\n       @{APEN 2}DIESES KOMMANDO IST NUR IN DER REGISTRIERTEN VERSION EINGEBAUT !@{APEN 1}\n@endnode\n\n@node CLEAR "KOMMANDO : CLEAR/CLS - LÖSCHT DEN BILDSCHIRM"\n\n@{u} CLEAR / CLS - Löscht den Bildschirm@{uu}\n\nDieses Kommando löscht den Inhalt des Bildschirmes und setzt den Cursor an\ndie linke obere Ecke. Mehr muß man dazu glaub ich nich schreiben :)\n@endnode\n\n@node VER "KOMMANDO : VER - ZEIGT VERSIONSNUMMER VON CD-SERVER AN"\n\n@{u}VER / $ - Zeigt Version-Informationen an@{uu}\n\nWenn Sie dieses Kommando eingeben, erscheint eine Ausgabe der aktuellen\nVersionsnummer vom CD-Server, sowie das Datum der Compilierung.\n\nNatürlich kann man die Versionsnummer des Programms auch mit dem CLI-\nKommando ''VERSION'' erfragen, für weitere Informationen gucken Sie bitte\nin Ihr Amiga-Dos Manual.\n@endnode\n\n@node HELP "KOMMANDO : HELP/?/# - ZEIGT ONLINE-HILFE AN"\n\n@{u}HELP/?/# - Zeigt die Online-Hilfe an@{uu}\n\nWenn Sie mal gerade nicht wissen, wie ein Kommando heißt, bzw. es aufgerufen\nwird, dann geben Sie eine dieser Zeichenfolgen ein, und CD-Server zeigt das\nHelpfile (S:CD-SERVER.HLP) an.\n\nDa die Geschmäcker der Menschen unterschiedlich sind (Gott sei Dank! :), habe\nich das Helpfile auch extern gehalten, so kann sich das jeder Sysop selbst\nzurecht zimmern...\n@endnode\n\n@node INDEX "KOMMANDO : INDEX - SUCHT NACH INDEX-FILE UND ZEIGT ES AN"\n\n@{u}INDEX - Sucht nach dem Index-File und zeigt es ggf. an@{uu}\n\nDa ich mein CD-Rom eigentlich nur für AMINET-CD''s benutze, habe ich fest-\ngestellt, daß bei diesen Aminet-CD''s immer ein INDEX - File in jedem Dir\nzu finden ist, welches eine kurze Übersicht über das aktuelle Directory\nenthält. Wenn nun jemand etwas bestimmtes sucht, isses wohl leichter, dieses\nFile erstmal zu durchsuchen, als sich alle .readme Dateien anzuschauen. Und\ndafür is halt das Index-Kommando da, wenn sich kein Index in einem Directory\nbefindet, erhält man die Meldung : ''NOTHING TO VIEW !'' .\n\nAber wie gesagt, dieses Kommando ist halt hauptsächlich nur für die AMINET-\nCD''s gedacht, die ich persönlich für das beste an PD überhaupt halte !\n@endnode\n\n@node CHANGE "KOMMANDO : CHANGE - AKTUELLES GERÄT/DIRECTORY ÄNDERN !"\n\n@{u}CHANGE - Ändert aktuelles Gerät/Directory@{uu} (V1.03)\n\nMit diesem Kommando können Sie das aktuelle Gerät, bzw. Directory wechseln.\nBei Verwendung der Amiex werden aus Sicherheitsgründen alle gemerkten Pfade\ngelöscht, wenn Sie also noch geflaggte Files haben, sollten Sie diese vorher\ndownloaden, bevor Sie das CHANGE Kommando benutzen!\n\nBei Verwendung der @{"FAME" LINK FAME} fällt dieses Problem nicht auf, dort bleiben alle\nFlags erhalten, Sie können also ohne Probleme auf ein neues Gerät wechseln,\ndort ein paar Dateien flaggen und dann alle auf einmal downloaden.\n@endnode\n\n@node LINE-EDITOR "WIE MAN EFFIZIENT MIT DEM ZEILEN-EDITOR ARBEITET"\n\n@{u}Benutzung des Zeilen-Editors von CD-Server@{uu}\n\nUm den Usern ein Maximum an Komfort zur Verfügung zu stellen, hat Byte-\nAndi und meine Wenigkeit eine Menge Arbeit in die Entwicklung einer Zeilen-\nEingaberoutine gesteckt. Das Ziel war es, so weit wie möglich (und notwendig)\ndie C-Shell Eingabemöglichkeiten zu simulieren, und dieses ist auch zu 98%\ngelungen möchte ich sagen :) ... hier nun eine Liste aller Kommandos :\n\n1) TAB-Taste. Diese Taste ermöglicht die automatische Filenamen-Erweiterung.\n   Nur das Drücken der Taste veranlasst CD-Server, das aktuelle Dir zu\n   scannen und das erste gefundene File anzuzeigen. Sie können z.B. auch\n   ''AMI'' eingeben und dann TAB drücken, sodaß CD-Server evtl. die folgenden\n   Filenamen findet : AMINET/, AMINET.Z, AMINET usw. Desweiteren ist es auch\n   möglich, ganze Pfade abzukürzen, wie z.B. : \n\n   Sie geben CD */*/*/* ein und drücken dann TAB, dann könnte evtl. folgende\n   Ausgabe erscheinen : AMINET/BIZ/DBASE/DEMO.LHA.\n\n   Dieses funktioniert überall auf dem Prompt, und wir dachten uns das das\n   wohl der beste Ersatz für die ''WildCards'' ist...:)\n\n2) Vollständige Zeilen-Editierung, d.h. das Sie überall innerhalb einer\n   Zeile sich mit den CRSR-links/rechts Tasten bewegen können, Zeichen ein-\n   fügen/löschen können, mit CTRL-X die komplette aktuelle Zeile löschen etc.\n   Aber bitte daran denken, daß dieses @{b}NUR@{ub} :) eine Zeilen-Routine ist, mehr \n   als 80 Zeichen abzüglich des angezeigten Pfadnamens sind derzeit nicht \n   gestattet!\n\n3) History-Buffer mit Abkürzungs-Möglichkeiten. Jede eingegebene Zeile wird\n   in einem internen Buffer gespeichert, dieser Buffer ist im Moment auf 20\n   Zeilen begrenzt, registrierte User können dann natürlich diesen ggf. auf\n   höhere Werte setzen...Wenn Sie die CRSR-Hoch/runter Tasten benutzen, dann\n   wird immer die zuletzt/zuerst eingegebene Zeile dargestellt. Dieser Buffer\n   ist auch die Basis für eine weitere nette Funktion : Das Abkürzen von\n   bereits eingegebenen Befehls-Zeilen! Stellen Sie sich vor Sie arbeiten \n   schon eine Weile mit dem CD-Server, und haben ständig das DIR Kommando\n   eingeben, und das wird nu mittlerweile lästig...dann können Sie auch z.B.\n   !di eingeben (!d geht auch!) und dann würde die Eingaberoutine nach einer\n   dementsprechenden Zeichenkette im Buffer suchen (z.B. DIR) und diese dann\n   ausführen...\n\n4) Abkürzungen der Standard-Befehle. Fast alle Befehle lassen sich durch eine\n   Taste abkürzen, z.B. das Kommando HELP -> H !\n\n5) Gesperrte Taste '':''. Diese Taste musste aus Sicherheitsgründen gesperrt\n   werden. Drücken dieser Taste befördert den User direkt in das Start-Dir,\n   das im Icon angegeben wurde...\n\n@{u}NEW IN V1.03@{uu}\n\n6) Pfadnamen im Prompt werden nun abgeschnitten, wenn sie länger als 30\n   Zeichen sind. In diesem Fall werden nur noch die letzten 27 Zeichen\n   des Pfadnamens angezeigt, am Anfang des Pfadnamens werden dann drei\n   Punkte (...) eingefügt, um anzuzeigen das der Pfadname momentan nicht\n   komplett dargestellt werden kann. Dieses Verfahren erlaubt Ihnen IMMER\n   eine Eingabe von min. 46 Zeichen, unabhängig davon, wie lang der Pfad-\n   name auch ist.\n@endnode\n\n@node DOWNLOADING "TIPS & TRICKS FÜR DIE DOWNLOADING-GESCHICHTE"\n\n@{u}Download@{uu}\n\nWie sich wohl jeder vorstellen kann, iss es nicht einfach, in die Amiex \nWÄHREND diese läuft neue Devices (und damit auch Pfade) einzutragen und \ndiese der Amiex bekannt zu geben. Daher musste ich ein wenig tricksen :),\num das doch klar zumachen. So kann es z.B. bei Multinode-Systemen passieren,\ndas bei gleichzeitiger Benutzung des CD-Servers von mehreren Usern plötzlich\nFiles mehrere Male gefunden werden, dieses ist jedoch normal und ist einer \nder netten Nebeneffekte des Programms..:)\n\nEin anderer wichtiger Punkt ist die Tatsache, das es @{b}UNMÖGLICH@{ub} ist, mehrere\nFiles @{b}GLEICHEN@{ub} Namens auf einmal zu leechen. Das ist damit begründet, daß\nAmiex solange nach einem file sucht bis es dieses gefunden hat. Danach wird\nnach dem nächsten File gesucht, und hat dieses den gleichen Namen wie das\nFile davor, dann wird dieses geskippt.\n\nSollten Sie doch einmal zwei Files gleichen Namens leechen wollen, dann ver-\nfahren Sie bitte wie folgt:\n\nAngenommen, sie wollen das File INDEX aus Directory CD0:AMINET/ und \nDirectory CD0:AMINET/BIZ/ leechen. Dann gehen Sie zuerst in das Dir \nCD0:AMINET/, leechen das File INDEX. Dann geben Sie ''A C *'' ein, um die \ninterne Pfadliste von CD-Server zu löschen, und wechseln dann in das Dir\nCD0:AMINET/BIZ/ und leechen sich von dort das zweite INDEX-File. Sorry für\ndiese Aktion, aber ich denke mal das der gesamte Komfort von CD-Server diese\nkleinen Restriktionen aufheben sollte oder ? :)))\n\nAls kleiner Bonus sei auch nochmal auf eine Sache hingewiesen, die sonst ja\neigentlich nicht möglich ist, und zwar kann man folgendes eingeben:\n\n              d aminet/biz/dbase/data1.lha readme aminet/index\n\nund CD-Server übergibt der BBS dann nur noch die Filenamen DATA1.LHA, README\nund INDEX, merkt sich jedoch auch gleichzeitig die anderen Pfade und übergibt\ndiese mit beim suchen. Diese Funktion ist identisch mit der @{"Mark Funktion" LINK FLAG}.\n\n@{u}ANMERKUNG FÜR FAME-SYSOPS:@{uu}\n\nWas soll ich sagen, @{"FAME" LINK FAME} ist nun in der Lage, dem CD-Server die volle\nKontrolle über die File-Flags zu geben, ohne dieses Assihn benutzen zu\nmüssen. Von daher haben Sie unter @{"FAME" LINK FAME} mit keinerlei Einschränkungen zu\nleben, alles läuft so wie es auch in der BBS geht.\n\nWechseln Sie auf das bessere System...es gibt keine Alternativen mehr !\n@endnode\n\n@node MARK&FLAG "TIPS & TRICKS FÜR DAS FLAGGEN DER FILES"\n\n@{u}Markieren/Flaggen von Files@{uu}\n\n@{u}ANMERKUNGEN FÜR AMIEX-SYSOPS:@{uu}\n\nWie bereits erwähnt, ist die Unterstützung der Wildcards nicht möglich. \nSollte dieser doch angegeben werden, so wird die /X die files nicht finden,\n@{b}ALSO BITTE NICHT BENUTZEN@{ub}, stattdessen nehmen Sie halt die TAB-Taste für die\nPfadnamen-Erweiterung. Dieses Problem ist bisher für Amiex nicht lösbar,da \nder Server der Amiex die Conference-Icons nur einmal beim Start ins Memory \nliest, und dann alle Daten aus dem Speicher holt. Daher reagiert auch Amiex \nnicht auf neu dazugefügte ToolTypes (wie wäre es mit einem Kommando, das \ndie Amiex zwingt, das jeweilige Conference-Icon neu einzulesen, \nByteMaster ???) !!!\n\nAmiex hat noch einen anderen Nachteil beim Markieren von Files, und zwar ist\ndie Liste der geflaggten Files auf 2048 Bytes (oder mehr) inkl. der Spaces\nbegrenzt! Sollte also Amiex beim Flaggen abbrechen, dann ist meistens der \nString dafür voll, und Sie sollten erstmal ein paar Files leechen,bzw. einige\nFiles aus der Liste löschen. Wenn Sie das @{"FAME" LINK FAME}-System fahren, dann wird\ndieses Problem nicht auftreten, da @{"FAME" LINK FAME} ECHTE DYNAMISCHE LISTEN verwendet,\nund von daher nur von Ihrer Hardware begrenzt ist, nicht vom Willen des\nProgrammierers!\n\nWie bereits im Kapitel @{"DOWNLOAD" LINK DOWNLOADING} erwähnt, können Sie auch beim Flaggen von\nFiles einen Pfad mit angeben:\n\n                    A aminet/biz/patch/suxx.lha\n\nund CD-Server flaggt nur noch den Filenamen ''suxx.lha'', behält jedoch den\nPfad im Speicher und übergibt diesen dann auch beim Downloaden der BBS.\n\n@{u}ANMERKUNG FÜR FAME-SYSOPS:@{uu}\n\nKeine Einschränkungen nötig, mit @{"FAME" LINK FAME} läuft ALLES, nur das Sie halt auch\nkomplette Pfadnamen beim Flaggen angeben können..:=)\n@endnode\n\n@node GREETINGS "DIE ALLSEITS BELIEBTEN GRÜßE :)"\n\n@{u}SieGeL & ByteAndi grüßen:@{uu}\n\nSpy/trSi        - For helping us with the Argument-Parsing & the Dirscanning\nDr.Dre!/tRSi    - Berlin roolez!!!!!!!! :()\nsTRIDER/sDC     - For his very cewl @{"FAME" LINK FAME}-System :)) DER SAFT IST MIT DIR!\nARGON           - BW Suxx...\ndEATH aNGEL/sDC - For testing it finally on @{"FAME" LINK FAME} and for being a cewl beta :)\nBloodRock/SDC   - Da ASM-Posse strikes back..:) \nfUTZi/tRSi      - Welcome to our Club :)\n\n ...uND nATÜRLICH aLLE bETATESTER & rEGISTRIERTE uSER fÜR iHRE uNTERSTÜTZUNG,\n\n  aRTCORE! fÜR iHREN mEGA-gEILEN rEQUEST-sERVICE uND aLLE aNDEREN dIE wIR\n\n        hIER vERGESSEN hABEN zU eRWÄHNEN...fÜHLT eUCH gEGRÜSST ! :)\n\n------------------------------------------------------------------------------\n\n                           @{u}Technical Info@{uu}\n\nMain Code & Idea  : SieGeL/tRSi\nAdditional Coding : ByteAndi/tRSi (EDIT-Routine) & Spy/tRSi (Dir-Scanroutine)\nGFX painted by    : (-rAPID-) fROM dA fAMOUS aRTCORE pOSSE !\n\nCD-Server wurde auf zwei A4000/040 entwickelt und erfolgreich auf folgenden\nSystemen getestet : \n\n A5oo  5MB  68ooo           OS 2.o  Amiex 4.9        - SieGeL\nA12oo  6MB  68o2o+68881 Co. OS 3.o  Amiex 4.7        - ARGON\nA12oo 10MB  68o3o+68882 Co. OS 3.o  Amiex 4.7        - BYSIS\nA2ooo 14MB  68o3o+68882 Co. OS 2.o  @{"FAME" LINK FAME}-System      - dEATH aNGEL\nA3ooo 10MB  68o3o+68882 Co. OS 2.o  Amiex 4.6        - Spy\nA4ooo 14MB  68o3o+68882 Co. OS 3.o  @{"FAME" LINK FAME}-System      - sTRIDER\nA4ooo  6MB  68o4o+68o4o Co. OS 3.o  Amiex 4.9        - ByteAndi\nA4ooo 14MB  68o4o+68o4o Co. OS 3.1  @{"FAME" LINK FAME} & Amiex 4.9 - SieGeL\n\n            @{"(tRSi/X-iNNOVATiON) - wO sINDSE dENN ?" LINK ADDY1}\n@endnode\n\n@NODE PRGLIST "LISTE ALLER MEINER PROGRAMME BIS HEUTE !"\n\n@{u}Programm-Liste@{uu}\n\nUm Ihnen einen Überblick zu geben, was Sie als registrierter User bei mir\nbekommen, hier eine Liste aller meiner bisher geschriebenen Programme :\n\n@{b}Zur Zeit für registrierte User verfügbare Prg.:@{ub}\n\nCD-Server V1.03r    - CD-Server für @{"FAME" LINK FAME}/AMIEX\nwORLD-cLOCK V1.18   - Weltzeit-Door für @{"FAME" LINK FAME}/AMIEX\nmEGA-vIEW V2.1      - Bester TXT-Viewer für @{"FAME" LINK FAME}/AMIEX\nlASTCALLERS V0.04   - Lastcaller-Util für @{"FAME" LINK FAME}, faster than SAMILOG!\nsOFT-dEL V1.01      - Schneller Online-Softdel. für @{"FAME" LINK FAME} & AMIEX\nU-sTAT V1.31        - User-Statistik Door, frei konfigurierbar (@{"FAME" LINK FAME} & /X)\nASKII-REQUEST V1.00 - aSKII-Requester Door (AMIEX/@{"FAME" LINK FAME})\npAGE-mASTER v0.73   - Pager-Door für @{"FAME" LINK FAME} mit Highscore-Liste und PW-Option.\nUser-Editor V0.02   - Externer User-Editor für @{"FAME" LINK FAME}, benutzt MUI V2.2++\nmULTI-tOP v0.01     - Multi-BulletinTool für @{"FAME" LINK FAME}, erzeugt 8 Bulletins\nNewFlag v0.01       - Flaggt automatisch alle files der letzten Tage\n\n@{b}Noch in Arbeit,bzw. muß überarbeitet werden:@{ub}\n\noRDER V.02          - VerkaufsTool, um z.B. Hardware über BBS zu verkaufen\nBBS-VIEW V1.13      - CLI-Util zum Anzeigen von ANSI-Pics, 100% ASM!\nU-Convert V0.2      - Util zum Konvert. von /X user.data -> @{"FAME" LINK FAME} user.data\nBullcreator V1.0    - Highscore-Util für ByteKiller V1.0, wird noch geupdated\npAGE-mASTER II      - Amiex Version des pAGE-mASTERS von @{"FAME" LINK FAME}\n\nIch denke mal, 30,- DM (bzw.$20) ist ja wohl nicht zuviel für diese Programme,\noder etwa doch ? Und natürlich werde ich, soweit es machbar ist, auch alle \nWünsche oder Neuheiten in diese Programme einsetzen...um mit uns in Kontakt\nzu treten, bitte mal in Kapitel @{"CONTACTS" LINK ADDY1} nachsehen.\n\n@{u}ANMERKUNG:@{uu}\n\nIch schreibe nebenbei gerade an einer MUI-Version meines mEGA-vIEWS, dieser\nist ein Kommodity, lokalisiert, hat ein AppWindow, arbeitet auf jeden Public\nSchirm usw. Ich brauche für dieses Programm noch BETA-Tester, und es wird\nauch als FreeWare veröffentlicht. Wenn Sie dieses Tool testen möchten, dann\nmelden Sie sich bitte in meiner BBS und dann werden wir das klären...\n\n@endnode\n\n@node FAME "WAS ZUM TEUFEL IS EIGENTLICH FAME ????"\n\n''Was ist FAME ?'' , werden Sie fragen...FAME ist ein neues BBS-System,welches\nvon Strider (Syndicate) geschrieben wird, und zu 90% kompatibel zu Standard-\nAmiexdoors ist. Natürlich hat es auch einen komplett eigenen Msg-Port mit\nweit über 1000 (!!) Kommandos. Desweiteren ist dieses System komplett von\nder verwendeten Hardware abhängig, was bedeutet, um so mehr RAM, umso mehr\nkann man auch durchdrehen...:)\n\nDie Konfiguration der BBS erfolgt über ein sehr komfortablen SystemEditor,\nwelcher VOLLSTÄNDIG OHNE ICONS die BBS konfiguriert und dabei komplett mit\nder Maus zu bedienen ist. Die Kontrolle der BBS läuft über einen ebenfalls\nkomplett mit der Maus bedienbaren Server (Commodity!).\n\nDadurch das die BBS noch in der Entwicklungs-Phase steckt, ist sie derzeit\nauch noch nicht erhältlich, aber wenn Sie weitere Informationen über dieses\nSystem haben wollen, dann melden Sie sich bei uns und wir geben Ihnen dann\nalle Informationen die Sie brauchen.\n@endnode\n\n@node ADDY1 "(tRSi/X-iNNOVATiON) WHQ & Beta Site"\n\nUm mit uns in Kontakt zu treten, schreiben Sie mir entweder über E-Mail:\n\n                     [email removed]\n\noder versuchen Sie unsere Boards anzurufen:\n\n   _____________  __________               /\\\n  |     __     /__\\__      /___________   /  \\             _____\n  |   ________/    /      /_\\____      \\_//   \\___________|_____|_______\n  |     |  \\      /      /      /      _//     \\    ______________      \\_\n  l_____|   \\___________/______/       \\_______/\\______   \\_    l/       /\n                              \\________/      /____________/____/       /\n                                       _________________       \\_______/\n     ______ /\\____ ____________ _______\\______   ______/\n    /      /_      \\    __    /_\\_____      \\_    |\n  _/      \\/______/   _______/\\      /       /    |    · PUN¡sHMeNT ¡NC. ·\n  \\________\\    _/_____________\\____/  Mo!  /_____|\n                /                  \\_______/\n                                           /\\  ______________  ___________\n     1oo% LeGaL sTUFF oN aM¡Ga^PC         /  \\_\\_______      \\_\\    _____/___\n                                         //   \\       /       /     /       /\n     RUNN¡NG oN a4ooo/4o · V.FasT      _//     \\_____/       /_____________/\n                                       \\________/   \\_______/\n\n TR¡sTaR & ReD seCToR ¡NC. (/X·¡NNoVaT¡oN) WHQ, aRTcORE! GHQ & eTH¡C D¡sT s¡Te\n\n   [> +49-(o)-3o-694-84-7o <]  sYsoP: s¡eGeL/TRs¡  [> +49-(o)-3o-694-85-7o! <]\n\n                     @{"> pARALYSIS BBS - dISTRIBUTION sITE <" LINK ADDY2}\n@endnode\n\n@node ADDY2 "(tRSi/X-iNNOVATiON) bETA & dIST SITE"\n       ____                                                                  \n    ___\\  /______________________________________________________________    \n   /   \\\\//                                                              \\   \n  /     \\/ -[ THe BeST eQUiPPeD PuBLIC DoMAIN BoaRD IN BeRLIN ]-          \\  \n /   -[ WiTH 4 GReaT U.S.ROBOTICS V.FAST CLASS MoDeMS WiTH FLaSH-RoMS ]-   \\ \n/                                                                           \\\n\\                        -- -[ SYNDIC/\\TE WHQ ]- --                         /\n \\   _____  _____    _____   _____  __      ___ __  _____   ___ _____      / \n  \\ /  _  \\/  _  \\  /  _  \\ /  _  \\/  |___ /   |  \\/   __)_/ __|   __)_   /  \n   /   |   \\  _   \\/   |  //   _   \\  |   \\\\_____  \\___    \\¯  |___    \\ /   \n  /   _____/  |    \\_ __   \\_  |    \\ |    \\   |    \\|      \\  | |      \\    \n  \\____| \\____|    /___|    /__|    /___   / _______/___    /__|____    /    \n      \\       l___/    l___/   l___/  \\___/___/  [ViC!]\\___/       \\___/     \n       \\                                                             /       \n        \\SYSTeM CHieFS: SPY/TRSi,ARTHuR DeNT,PHaNToM,Cat,JTC,big-rat/        \n         \\                                                         /         \n          \\   1: +49(0) 30 721 6071 USR DuAL STaNDaRD V.34 33.6   /          \n           \\  2: +49(0) 30 721 6072 USR DuAL STaNDaRD V.34 33.6  /           \n            \\ 3: +49(0) 30 721 6073 USR DuAL STaNDaRD V.34 33.6 /            \n             \\4: +49(0) 30 722 6065 USR DuAL STaNDaRD V.34 33.6/             \n              \\                                   /\\          /              \n               \\_________________________________//\\\\________/               \n                                                 /__\\\n\n                        SUPPORTS ONLY PD-/SHAREWARE !\n@endnode\n\n@node REGVERSION "ERWEITERTE REGISTRIERTE VERSION DES CD-SERVERS"\n\n@{u}Zusätze der Registrierten Version des CD-Servers@{uu}\n\nWenn Sie den vollen Support für den CD-Server genießen wollen, dann haben\nSie die Registrierungsgebühr zu bezahlen. Als registrierter User können\nSie mit den folgenden Erweiterungen rechnen:\n\n- Suchfunktionen aktiviert\n- Level-abhängige Geräte/Directories, für Co-Sysops zum C: dir z.B.\n- Interne Pack-Funktionen mit Sysop-einstellbaren Bytebegrenzungen\n- User-konfigurierbarer Dir-Style und andere Optionen (wie Packer etc.)\n\nund natürlich alle Wünsche (soweit realisierbar) für CD-Server oder die\nanderen Programme die @{"HIER" LINK PRGLIST} aufgeführt sind. Es liegt also an Ihnen, die\nWeiterentwicklung der Software zu sichern...\n@endnode\n','\n',char(10)),NULL,'auto-added',76872,11,0,NULL,NULL,'trsi_cds','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_d_s','TRSI-D!S.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-D!S.LHA','DRE!SENT','XIM','DRE!SENT',NULL,'DR.DRE!','TRSI','.::::::: ..........:  ::::::.....  :::::: ::::::::: :::::: ::::: ...... ::::: :::::: .::::::::: :::::: :::::.::::::.::::: ::::::.',replace('.....................    .................\n  .::::::: ..........:  ::::::.....  ::::::\n ::::::::: :::::: ::::: ...... ::::: ::::::\n.::::::::: :::::: :::::.::::::.::::: ::::::.\n<-rS!/aRt-.::::::- /X iNNoVATiON pRESENTs ->\n  dRE!SENt v0.2 [RELEASE 1] DIRStYLE ClONE\n   WRITTEN BY DR.DRE!  TRSI /X-iNNoVATioN\n','\n',char(10)),'DRE!SENT.GUIDE',replace('@DATABASE\n@Remark $VER: VERSION 0.2 [RELEASE 1] (Sep 23 1994 12:37:56)\n@Remark AmigaGuide DataBase for dRE!SENt v0.2\n\n@Node MAIN "dRE!SENt v0.2 - [RELEASE 1] for AMiEXPRESS 3.37 - 4.xx"\n\n                   ._________________  ______        .\n                   l___       /      \\/    _/_______.:\n                     /       /   /  _/\\___      /    :\n                    /_______/-rS!\\_____\\  _____/     |\n                          /_______|     \\/`94/_______|\n                   «««          dR.dRE! oF         »»»\n                   »»» tRISTAr aNd rEd^sECTOr iNc! «««\n                   «««    aMiEXPRESs iNNoVATioN    »»»\n\n                    iS pROUd tO pRESENt: dRE!SENt v0.2\n\n                 @{"             iNtRoDUCtiON!            " LINK Introduction}\n                 @{"             iNStALLATiON!            " LINK Installation}\n                 @{"               tOOLtYPES!             " LINK Tooltypes}\n                 @{"                CREDitS!              " LINK Credits}\n                 @{"         OtHER dRE!dOORS/tOOlS        " LINK Other}\n                 @{"               GREETINGS!             " LINK Greetings}\n                 @{"           tRSi /X-iNNoVATioN         " LINK Innovation}\n                 @{"           REGiStER DRE!DooRS         " LINK Register}\n@ENDNODE\n@NODE Introduction "dRE!SENt iNtRoDUCtiON"\n\n                              ABOUT DRE!SENt\n                            - -------------- -\n\ndRE!SENt v0.2 is a small DirStyle Clone but really faster (Online Updating).\ndRE!SENt is a powerfull XiM Module for AMiEXPRESS written in SAS/C.\n\nMany Times SAL-ONE/tRSi suggest me to code a DirStyle Clone which is\na bit faster as the original, so i choosed a Way without reading the whole\nCallerslog, so i could be faster as Dirstyle.\nI hope you like it...\n\nFeatures: Colors switchable\n          DateLine switchable\n\nAll what you need is any Model of the great AMIGA, OS2.x or higher.\nRegistered (or not) Version of AmiExpress 3.37 - 4.xx.\nAssigned Doors:\nThats all... have Fun with this powerfull Door.\n\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Installation "dRE!SENT iNStALLAtiON"\n\nCopy the complete DRE Directory to your Doors.\nNOTE: Until now all my Doors are placed in this DOORS:DRE/ Directory,\n      so may you need them for other Doors/Utils again.\n\nThen Copy the Sent.Info to your BBS:COMMANDS/BBSCMD/ .\nThe rough Install is done, open now the DOORS:DRE/DRE!ADVERT/DRE!SENT.INFO\nto Edit the @{" ToolTypes " LINK Tooltypes}.\n\nREAD THIS · READ THIS · READ THISREAD THIS · READ THIS · READ THISREAD THIS\n---------------------------------------------------------------------------\n\nNow you have to build in this Door into your MultiDoorStart or Dupechecker.\ndRE!SENt have to run after each Upload.\nYou can build it also in the FastDupe or FastDUplicateChecker, or any other\nDoor which is able to start a Door after the Upload.\n\nYOU MAY ALSO CAN MAKE DRE!SENT RESIDENT.\nADD THIS TO YOUR USER-STARTUP\nRESIDENT SENT DOORS:DRE/DRE!SENT/SENT PURE\n\nDONT FORGET TO CHANGE THIS IN YOUR BBS:COMMANDS/BBSCMD/SENT.INFO\nLOCATION=SENT\nRESIDENT\n\n---------------------------------------------------------------------------\nREAD THIS · READ THIS · READ THISREAD THIS · READ THIS · READ THISREAD THIS\n\nEnjoy it...\n\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Tooltypes "AVAiLAVLE TOOLtYPES"\n\n                        TOOLtYPES FOR DRE!SENt\n                      - ---------------------- -\n\nCOLOURS=(YES/NO)     - SWITCH COLOURS IN SENT LINE ON(YES) OFF(NO)\nDO_DATELINE=(YES/NO) - SWITCH DATLINE IF YOU SET YES THEN DRE!SENT WILL\n                       SEPERATE EACH DAY WITH A NICE DATLINE.\n                       IF YOU CHOOSE NO, HE DO NOTHING BETWEEN THE\n                       DIFFERENT DAYS.\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Credits "Noteable Credits"\n\n                             NOTEABLE CREDITS\n                           - ---------------- -\n\n DRE!SENT v0.2 [RELEASE 1] was written by Dr.Dre!/tRSi /X-iNNoVATioN\n\n                   SUGGESTION OF DRE!SENT - SAL-ONE/tRSi\n\n     The AmigaGuide DataBase was written by Dr.Dre!/tRSi /X-iNNoVATioN\n\n        AMIEXPRESS PROFESSIONAL (C) - LIGHTSPEED TECHNOLOGIES INC.\n\n      MUSICAL SUPPORT: ANTHRAX [·] NIRVANA [·] THERAPY [·] PHILIP BOA\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Other "Other already released DRE!DOORS/TOOLS"\n\n                           OTHER DRE!DOORS/TOOLS\n                         - --------------------- -\n\n NAME                  TYPE   VERSION\n---------------------+------+---------------------------------------------\nDRE!WHO              | XiM  |  V1.1  PUBLIC\nDRE!FRONT            | XiM  |  V1.O  PUBLIC\nCHAT!ACCESS          | XiM  |  v1.2  PUBLIC\nDRE!COMMENT          | XiM  |  V1.3  PRiVATE RELEASE FOR REG. USERS ONLY\nDOORMENU             | XiM  |  v1.o  PUBLIC\nDRE!WALL             | XiM  |  v1.2  PRiVATE RELEASE FOR REG. USERS ONLY\nFAST!DUPE            | XiM  |  v1.11 PRIVATE COOP DR.DRE!^BYTEANDI\nMOST WANTED          | XiM  |  v1.52 PRiVATE RELEASE FOR REG. USERS ONLY\nLHA CHEKKO           | DOS  |  v2.o  PRiVATE RELEASE FOR REG. USERS ONLY\nSPEEDADD (TXT)       | DOS  |  v1.09 PRiVATE RELEASE FOR REG. USERS ONLY\nSPEEDZIP (ZIP)       | DOS  |  v1.o  BETA\nBULL!VIEW            | XiM  |  v1.02 PUPLIC\nDRE!FREE             | XiM  |  v1.ß  PRIVATE RELEASE FOR REG. USERS ONLY\nLAST!JUNKZ           | AiM  |  v1.0  PRIVATE RELEASE FOR REG. USERS ONLY\nPWFAILURE            | XiM  |  v1.1  PUPLIC\nBETA!REPORT          | XiM  |  v0.92 BETATESTER(S) ONLY\nDRE!NODECHECK        | XiM  |  c0.ß  PUBLIC\nCARD DISTRIBUTOR     | XiM  |  v1.oa BETA (PRIVATE^PUBLIC VERSION SOON)\nDRE!SENDLIST         | XiM  |  v1.2  PUBLIC\nNUP^SYSPW COMMNTER   | XiM  |  v1.2  PUBLIC\nNEWUSER SCRIPT       | XiM  |  v1.21 PUBLIC\nGLOBAL USER STATUS   | XiM  |  v1.9  PUBLIC\nSPEEDLIST (USERLIST) | XiM  |  v1.ß  PRIVATE RELEASE FOR REG. USERS ONLY\nDESCRIPTION!SNAP     | AiM  |  v1.o  PUPLIC\nDRE!ADVERTISE        | XiM  |  v2.o  PRIVATE RELEASE FOR REG. USERS ONLY\nDRE!SENt             | XiM  |  v0.2  PRIVATE RELEASE FOR REG. USERS ONLY\n---------------------+------+---------------------------------------------\nTHERE ARE ALSO SOME OLDER (AiM) DOORS AVAILABLE WHERE I CANT REMEMBER\nWHAT WAS IT EXACTLY ... SEARCH ONLY FOR DR.DRE!\nIF YOU LIKE MY DOORS/UTILS AND WANT BE @{" REGISTERED " LINK Register} USER OF IT\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Register "REGISTER DRE!DOORS"\n\n                            REGISTER DRE!DOORS\n                          - ------------------ -\n\nTHE REGISTRATION FEE IS 2O$, SHURE YOU THINK PHEW! A LOT OF MONEY, BUT READ\nWHAT I WILL BET FOR YOUR MONEY.\n\n1. YOU WANNA BE SHURE YOU GET ONLY DOORS WITHOUT ANY BACKDOOR ? OF COURSE\n   THE REGISTERED USER(S) ARE GETTING ONLY PRIVATE VERSIONS, ALL PUBLIC\n   VERSIONS HAVE A TIMELIMIT OR I REMOVE SOME MENU POINTS. ONLY!!! THE REG.\n   USERS HAVE THE FULL VERSION.\n\n2. YOU FOUND A BUG ? -> REPORT HIM TO ME AND YOU GET SOON AS POSSIBLE A\n   FIXED VERSION, NO LONG NEED TO WAIT FOR A NEWER RELEASE VERSION.\n\n3. YOU HAVE SOME GOOD IMPROVEMENTS, TALK WITH ME, AND I WILL SEE IF I CAN\n   REALISE IT.\n\n4. YOU NEED A PRIVATE DOOR ONLY FOR YOUR BBS, I WILL CODE THEM.\n\n5. PRIVATE SUPPORT CONFERENCE IN A FUCKEN FAST TRSI BOARD IN NEDERLAND.\n\n6. ALL DOORS/UTILS ARE INCLUDING YOUR REGISTER STRING.\n\n7. YOU`LL GET ALL LATER VERSIONS OR NEW DOORS FOR THIS PRICE.\n\n                  SIMPLY YOU GET THE BEST SUPPORT AROUND.\n          THINK ABOUT IT AND KEEP THE PROGRAMMERS PROGRAMMING !!!\n\nIF YOU ARE INTERESTED SO CONTACT ME AT ANY TRSI BOARD OR SIMPLY AT THE\n                           TRSI EHQ - BOONDOCKS\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Greetings "GREETINGS"\n\n                            SOME FAST GREETINGS\n                          - ------------------- -\n                               TO THIS DUDES\n\n   [·] MCLOUD/TRSI [·] MARIO [·] ECS [·] SIEGEL [·] BYTEANDI [·] SPY [·]\n    [·] VALSHARE [·] REDSKIN! [·] EMPIRE/MST [·] RICHI/FLT [·] NICK [·]\n    [·] SAL-1/TRSI [·] TRITON [·] VAMPIRE/PDY [·] XTREME [·] BJOERN [·]\n     [·] LINEBACKER [·] BLOODWOLF [·] JUAN/TRSI [·] BLIND GUARDIAN [·]\n                         ... and all i forgot ...\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Innovation "TRSI /X-iNNoVATioN"\n\n\n\n                      TRSI /X-iNNoVATioN MEMBERS ARE:\n                    - ------------------------------- -\n\n\n                               DR.DRE!/TRSI\n                               BYTEANDI/TRSI\n                                SIEGEL/TRSI\n                                 SPY/TRSI\n\n   IF YOU WANNA JOIN US, SO GET IN TOUCH WITH ONE OF THE DUDES ABOUVE...\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n','\n',char(10)),'{"LOCATION":"SENT"}','auto-added',50679,5,0,NULL,NULL,'trsi_d_s','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_dft','TRSI-DFT.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-DFT.LHA',NULL,'XIM','._________________  ______',NULL,'Dr.Dre!','TRSI','l___       /      \/    _/_______.: /       /   /  _/\___      /    : /_______/-rS!\_____\  _____/     |',replace('    ._________________  ______\n    l___       /      \/    _/_______.:\n      /       /   /  _/\___      /    :\n     /_______/-rS!\_____\  _____/     |\n           /_______|     \/`94/_______|\n   drefront v1.o (XiM Module) by Dr.Dre!\nSupporting Quiet Node · 9 & 32 Node Version\n','\n',char(10)),'drefront.guide',replace('@database drefront 1.o 9 & 32 Node Version - © by Dr.Dre!/tRSi\n\nCopyright (C) 1993 by Dr.Dre!/tRSi, Germany\nAll Rights Reserved\n\n@Remark $VER: Version v1.o (Tuesday 25-Jan-94 11:44:48)\nRemark AmigaGuide DataBase for drefront 1.o 9 & 32 Node Version\n\n@node MAIN "drefront 1.o (Tuesday 25-Jan-94 11:44:48) Document for /X"\n\n                   ._________________  ______\n                   l___       /      \/    _/_______.:  \n                     /       /   /  _/\___      /    :\n                    /_______/-rS!\_____\  _____/     |''94  \n                          /_______|     \/   /_______|\n\n       is proud to present: drefront 1.o (Tuesday 25-Jan-94 11:44:48)\n                         @{"     Introduction      " Link no1}\n                         @{"     Requirements      " Link no2}\n                         @{"     Installation      " Link no3}\n                         @{"       Creditz!        " Link no5}\n                         @{"      Greetings!       " Link no6}\n                         @{"     tRSI Boards!      " Link no7}\n@endnode\n@node no1 " Introduction"\n\n                    XIM Module for AmiExpress 2.xx - 3.xx\n\n                  This is a fast and ang fukk`n good looking \n                 Frontend Door for /X with some good Features\n            It supports the Quiet Mode if you have your Node QUIET \n                     so you not shown in the Frontend...\n                             * Example Output: *\n\n                 Nd#        Node-Status         Node-Action\n             ··==================================================··\n                 Nd0   Node is busy...       Uploading Warez \n                 Nd1   Node is busy...       Downloading Warez\n                 Nd2   Your Node...          Logging on...      \n                 Nd3   Node is free for the  next Caller !!! \n             ··==================================================··\n              dre!front v1.o by dr.dre!/trsi xim module for /X 3.x\n\n@endnode\n@node no2 " Requirements"\n\n                You need an Amiga 500/1000/1200/2000/3000/4000\n                          Kickstart 2.0 or higher\n                     Ami Express 2.xx - 3.xx (Registered)\n\n@endnode\n@node no3 " Installation"\n\n                    If you have /X 2.xx - 3.20 so copy the\n                       drefront9.XiM File to your Doors\n                     and the Frontend.Info to your Syscmd\n                   if you have /X 3.30++ running so take the\n              drefront32.XiM Version this is the 32 Node Version !\n\n                 NOTE: The Frontend.Info is configured for the\n                 32 Node Version if you use the 9 Node Version \n                       then you have to change the Icon...\n\nhave Phun...\n@endnode\n@Node no5 " The Creditz!"\n\n                 Copyright (C) 1994 by Dr.Dre!/tRSi, Germany\n                             All Rights Reserved\n\n               The AmigaGuide DataBase written by Dr.Dre!/tRSi\n\n     For more good Doors call my BBS under 49 (0) 2131 275756 & 275634\n                · [ · MARLEYS COFFEE SHOP - tRSi GHQ · ] ·\n\n\n@endnode\n@Node no6 " Greetings"\n\n                   The Greets are going to these Dudes...\n\n ByteAndi/X-Design, Spy/X-Design, Remo/X-Design, X-Treme/TRSI, Saito/TRSI\n    Gandalf/Faith, Silver/Faith, McLoud/TRSI, Irata/TRSI, Triton/Fth\n Skylark/LSD, Nick, Metoner/TRSI, J.Walker/TRSI, Crazy/TRSI, Valshare/TRSI\n    Vicous/LSD, Richi/Flt, Steve/D&R, Amicom, -rS!/TRSi, Empire/Mst, \n        Mr.VAiN, APOLLO, BJoerN/Pdy, Jive/TRSi, Scope/Trsi, SkiN!\n          and simply all tRSi Member an other Doodes I forgot...\n\n@endnode\n@Node no7 " tRSi Boards Worldwide"\n\n                 To Contact me Call any of this Boards...\n\n   obituary.......................World    HQ............+1-310-652-5688\n   biohazard......................Canadian HQ............+1-905-841-0965\n   cauldron.......................German   HQ............++49 Pure Elite\n   marlEys coffEE shop............German   HQ............++49 Pure Elite\n   surburbia......................German   HQ............++49 Pure Elite\n   boondocks......................European HQ............+31-548-040-653\n   final impact...................Swedish  HQ............++46-54-113-486\n   flying spirits.................Swiss    HQ............+41-217-282-524\n   savage amusEmEnt...............Austria  HQ............+43-767-227-743\n   zEnlandia......................Finnish  HQ............+358-088-82-144\n\n@endnode\n','\n',char(10)),NULL,NULL,19812,2,0,NULL,NULL,NULL,'scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_dir','TRSI-DIR.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-DIR.LHA','DirCutter','XIM','DirCutter','2.1',NULL,'TRSI','-------------------------------------------- The ultimate tools for archieving your collected stuff.',replace('DirCutter V2.1 & DirDeleter V1.2\n--------------------------------------------\nThe ultimate tools for archieving your\ncollected stuff.\nDirCutter:  Strips /X-DIR-files in a perfect\n            way, TEST IT OUT !\nDirDeleter: Synchronizes a DIR-file with a\n            directory, TEST IT, TOO !\n--------------------------------------------\nA MUST for all Sysops with megabytes of\n/X-DIR-files! Strip your DIRs NOW !!\n--------------------------------------------\n   TRSI - SpecialToolsDevelopment ©1994\n','\n',char(10)),'DirCutter.DOC.V21.Guide',replace('@DATABASE "DirCutter"\n@WIDTH 77\n@NODE "MAIN" "Welcome to DirCutter Docs"\n@TOC "MAIN"\n\n\n   /*                                                            */\n   /*                                                            */\n   /*            DIRCUTTER V2.1            10.10.94              */\n   /*                                                            */\n   /*    written by KNS/TRSI in order to save a *LOT* of time    */\n   /*                                                            */\n   /*                                                            */\n\n\n          1. @{"What is DirCutter" LINK "whatis"}\n          2. @{"How to install" LINK "install"}\n          3. @{"General features" LINK "config"}\n          4. @{"CLI-Options" LINK "optionen"}\n          5. @{"Last important infos" LINK "lastwords"}\n\n          6. @{"Known bugs" LINK "bugs"}\n          7. @{"THANX" LINK "thanx"}\n          8. @{"Some greetings" LINK "greetings"}\n          9. @{"History" LINK "history"}\n\n@ENDNODE\n\n\n@NODE "whatis" "What is DirCutter ?"\n@TOC "MAIN"\n\nWhy everybody needs DirCutter!\n------------------------------\n\nDirCutter  is a tool, that is able to modify AmiExpress-DIR-files.  If\nyou  collect  the uploaded stuff, you need to keep the DIR-files, too,\nbecause without them you''ll never remember WHAT program is represented\ne.g.  under the name "TRSI-DS1.DMS".\n\nA  DIR  of  one  month can easily grow to 300kB.  A simple calculation\nshows:  12 * 300kB = 3.6MB within ONE year.  Handling these huge files\nis a) difficult, b) awkward and c) HD-space killing !!\n\nSo  I  decided  to  dedicate my first Amiga-C-program to this problem.\nWith  DirCutter  you''re  able  to  modify  the  DIR-files  in  several\ncomfortable ways.  Let''s introduce these fine features:\n\n\n\n\nFEATURES of DirCutter!\n----------------------\n\n* kill the fucking ANSI-paintings\n* strip the DIR down by KEEPING the INTERESTING file-descriptions (!!!)\n* pack the DIR while stripping -> shortest representation of file-desc.\n* kill "Sent by"-lines\n* kill all faked entries\n* kill empty lines\n* kill "spacy"-lines (they content only spaces and appear in front of\n                      a new file-line)\n* kill all lines containing any string that YOU defined !!!\n* kill non-ASCII-chars within description-lines\n* convert the case of the description-text\n\n\nIf you didn''t get the usefulness of these features, don''t worry!  I''ll\nexplain them in detail later.\n\n@ENDNODE\n\n\n@NODE "install" "How to install..."\n@TOC "MAIN"\n\nHOW TO INSTALL\n--------------\n\nI  coded  this proggy under Kick3.0, but I''m sure, that it works under\n2.0  also.  A test under Kick1.3 or lower seems to be useless, because\nevery serious AMIGA-user works with Kick2.0 or higher!!\n\n* Copy  the DirCutter main-program into your C:  directory  or another\n  directory within your PATH.\n\n* Copy the DirCutter.config to ENV: and ENVARC:\n\n* Be  sure, that you''ve got the "RUN" and  the "DELETE" command within\n  your PATH.\n\n* Be sure, that you''ve got a properly installed RAM-Disk.\n\n\nThis was all. Simple, isn''t it ?!?\n\n\n@ENDNODE\n\n\n@NODE "config" "General infos and .config-file"\n@TOC "MAIN"\n\nGeneral features and the DirCutter.config-file\n----------------------------------------------\n\nEverytime  you  modify  a DIR with DirCutter, the following operations\nwill be done:\n\n\n* EVERY empty line will be removed.\n  Who wants to have empty lines in a short, concentrated DIR ?!?\n\n* EVERY  "spacy-line" will be removed.  "Spacy-lines" are empty  lines\n  full  of spaces that appear in front of a new file-line.\n\n* All chars, that are not ASCII(35)-ASCII(125) and not "ä", "Ä", "ü",\n  "Ü", "ö", "Ö" or "ß", will be deleted from the description, even\n  within the text. The affected line will be shortened in this case.\n\n\nif there is NO DirCutter.config:\n\n* EVERY line created with "Bytekiller" will be removed.\n  DirCutter  looks for the "<<Bytekiller"-string and removes the whole\n  line.  (If   some   stupid   guys   write  "<<Bytekiller"  into  the\n  file-description, it may cause troubles!!)\n\n* EVERY line created with "Boss-Nuke" will be removed.\n  DirCutter  looks  for  the  "BoSS-NuKE"-string and removes the whole\n  line.  (If   some   stupid   guys   write   "BoSS-NuKE"   into   the\n  file-description, it may cause troubles!!)\n\n* EVERY line containing a string "[35m", "<<BK" or "m<<<" will be removed.\n\n\nif there IS a DirCutter.config:\n\n* All  lines  containing  the  strings  in  the  .config-file will be\n  removed.\n\n  e.g. the .config-file contains:   " --=="\n                                    "hello" (all WITHOUT quotation\n                                    "BBS"    marks !!!!!!!!!!!    )\n\n  During ''Pass 1'' all lines in the DIR, containing these strings, will\n  be removed !!\n\n  You see, it''s you turn, to choose good strings, that wouldn''t kill\n  wrong lines.\n\n  The .config in this package includes the default-strings. It doesn''t\n  matter  if  you  use DirCutter with or without .config. But I''m very\n  sure, that you''ll use  the .config to strip date-splitting-lines and\n  other crap that may be useful for a BBS, but not for an archiever.\n\n  Please edit the .config with your preferred ASCII-editor.\n\n  !!! IMPORTANT: The stripping is CASE-SENSITIVE !!!\n  If you want to kill all lines with "BBS", you MUSTN''T write\n  bbs, Bbs, BbS or anything else. You HAVE TO write BBS !!!\n\n@ENDNODE\n\n@NODE "optionen" "Options"\n@TOC "MAIN"\n\n OPTIONS\n =======\n\n a) @{"-s" LINK "options"} sensitivity\n b) @{"-c" LINK "optionc"} percentage\n c) @{"-a" LINK "optiona"} algorithm\n d) @{"-p" LINK "optionp"} packing\n e) @{"-f" LINK "optionf"} strip faked files\n f) @{"-l" LINK "optionl"} sent-by-lines\n g) @{"-t" LINK "optiont"} testprintout\n h) @{"-w" LINK "optionw"} case of output-characters\n\n\n If you enter "DirCutter" without any option or filename, you''ll get\n a short summary of all options.\n\n\n@ENDNODE\n\n@NODE "options" "Option ''-s''"\n@TOC "MAIN"\n\nOPTION "-s" (SENSITIVITY)\n-------------------------\n\nThis option changes the sensitivity of ASCII-recognition.  In order to\nkill  the ANSI-paintings, I said:  Only real "text" contains important\ninformation.   ANSI,  separating  lines  or lines with short texts are\nuseless crap for file-archivers.\n\nDefault is 20.\n\nThis  means:   A file-description-line is only kept, if it contains at\nleast   20   real  characters.   "Real  characters"  are:   "abc...z",\n"ABC...Z" and "1234...0" !!\n\nThe number for the new sensitivity MUST be separated from the "-s" !!\n\n\nSome examples:\n____________________________________________________\n\nDirCutter -a 0 -s 10 DIR1\nThe  file  DIR1  is  stripped  with  sensitivity 10.  Some experiments\nshowed:  there are too much crap-lines left.\n____________________________________________________\n\nDirCutter -s 0 DIR1\nStripping with sensitivity 0 will cause a DIR without "Bytekiller" and\n"Boss-NuKe"-lines.   All  other information will be kept.  Perhaps you\nlike to "clean up" your DIR a bit.  If yes, this is YOUR parameter.\n____________________________________________________\n\nDirCutter -a 0 -s 50 DIR1\nIt''s impossible, that there are at least 50 real characters within the\nfile-description-part  of  a line.  --> The resulting DIR will have NO\nfile-descriptions.  Perhaps anybody will find this useful...\n____________________________________________________\n\n\nFeature since V1.4:\n-------------------\n\nIf  no  lines  were  selected,  because  of  too few ASCIIs, DirCutter\nselects  AT  LEAST  ONE  line.   This  will  be the line with the MOST\nASCIIs.   If  you  use  a  sensitivity  bigger  than  45, this special\nselection  will  be  disabled  (because DirCutter recognizes, that you\nwant  something  impossible).  You can see the effect (no description)\ndescribed above.\n\n@ENDNODE\n\n\n@NODE "optionc" "Option ''-c''"\n@TOC "MAIN"\n\nOPTION "-c" (PERCENTAGE)\n------------------------\n\nThis  option  is  an idea of Troglobyte/Darkness.  I thought, that the\nidea  to  select  lines  by  using the percentage of ASCIIs was really\nnice.   DirCutter  will  now  count  the ASCIIs in the description and\ndivide the result through the number of characters in the description.\nThis  means:   lot of ANSI-crap in a line forces low percentage -> the\nprobability,   that  this  line  will  be  selected  decreases.   Some\nexperiments showed, that lot ANSIs and few ASCIIs mean:  uninteresting\nblabla in this line.\n\n\nYou can change the percentage, DirCutter uses in the following way:\n____________________________________________________\n\nDirCutter -c 80 DIR1\nSet percentage to 80%.  Now a line will only be selected, if there are\n>= 80% ASCIIs in the description.\n____________________________________________________\n\n@ENDNODE\n\n\n@NODE "optiona" "Option ''-a''"\n@TOC "MAIN"\n\nOPTION "-a" (ALGORITHM)\n-----------------------\n\nThis feature allows you to combine the select-methods:\n\n-a 0   Select only lines with #ASCIIs >= SENSITIVITY\n\n-a 1   Select only lines with %ASCIIs >= PERCENTAGE\n\n-a 2   SELECT only lines with #ASCIIs >= SENSITIVITY   (DEFAULT)\n                          AND %ASCIIs >= PERCENTAGE    (DEFAULT)\n\n@ENDNODE\n\n@NODE "optionp" "Option ''-p''"\n@TOC "MAIN"\n\nOPTION "-p" (PACKING)\n---------------------\n\nIn  my opinion only a short DIR is a good DIR.  Because of that you''re\nable  to  "pack"  the  main-lines together.  This means, that -- after\nstripping  the  DIR -- all additional lines between two filenames will\nbe removed.\n\nI recommend to activate this option. (Just a personal opinion.)\n\nExample:\n____________________________________________________\n\nDirCutter -p DIR1\nOnly  pure  filename-lines are kept.  In all tests during coding, this\nusage made the finest results.  I LOVE it!\n____________________________________________________\n\n\n\n@ENDNODE\n\n@NODE "optionf" "Option ''-f''"\n@TOC "MAIN"\n\nOPTION "-f" (STRIP FAKED FILES)\n-------------------------------\n\nIf you''re archieving your stuff, there is no need to keep faked files\nwithin your DIR (or is there any ?!?).\nSimply activate this option and all faked files will be left out!\n\nExample:\n--------\n___________________________________________________\n\nDirCutter -f DIR1\nAre you able to find any fakes??\n___________________________________________________\n\nDirCutter -p -f DIR1\nAnd here ?!?\n___________________________________________________\n\nDirCutter -s 50 -f DIR\nAnd now ??\n___________________________________________________\n\n\n@ENDNODE\n\n@NODE "optionl" "Option ''-l''"\n@TOC "MAIN"\n\nOPTION "-l" (Sent-by-lines)\n---------------------------\n\nThe  versions  before  V1.4  recommended  a  special DIR-structure.  I\nthought,  that  the most BBSs have "Sent-by"-lines under each uploaded\nfile.   But  Troglobyte  thinks,  that stripping the last line of each\nfile will cause many people troubles.  I added his suggestion:\n\nFrom now on, you''re able to set the number of lines, killed at the end\nof each file, by yourself !!!\n\nDefault is 1.\n\nIf  a  lot  of your users don''t have a Sent-by-line, set it to 0.  But\nnow it''s possible, that the Sent-by-line of some users will be kept in\nthe cutted DIR.  (Better force all users to use a Sent-by-line !)\n\nIf   you   have   an  own  line  added  into  every  description  PLUS\nSent-by-lines, simply use "-l 2".  The last two lines will be deleted.\n\n@ENDNODE\n\n@NODE "optiont" "Option ''-t''"\n@TOC "MAIN"\n\nOPTION "-t" (TESTPRINT)\n-----------------------\n\nThis option is really useful, if you''re not satisfied with the default\noptions and not able to find better ones :-(\n\nWith  "-t"  activated, there will be no output to disk.  The output is\nmade on the screen.  You should have activated an interlace-screen (or\nany  other  high-resolution screenmode) and use a small font (like XEN\nfrom  MagicWB).   Now  you''re  able  to  see the output without forced\nlinebreaks.\n\nThe meaning of all this confusion:\n\n-Every file is separated with a dot-line (···········).\n\n-The  first  number is the number of ASCIIs in the description of this\n line.\n\n-The  second  number is the percentage of ASCIIs in the description of\n this line.\n\n-Then the complete file-description follows.\n The reversed lines are selected by DirCutter.  These lines will be\n kept, if you don''t use "-t" and there is an output to disk (HD).\n\n\nLet''s say, you''ve typed:\n\nDirCutter -a 0 -s 40 DIR1\n\nOnly  lines  will be selected, where the first number is 40 or higher.\nBut you see, that lines with lower first number are selected!!!\n\nWhat  the hell happened ?!?  Did KNS a bad job ?  Is there a bug, that\nhas to be reported ???\n\nNO!!!!!!!!!!!!!!\n\nI  discovered,  that  too  many files had no descriptions after cuttig\nthem.   Because of that, DirCutter does the following:  if NO line can\nbe  selected according to the chosen parameters, DirCutter selects the\nline   with   the   HIGHEST   number   of   ASCIIs.    I  called  this\n"guarantee-one-line".   All  my  test-cuttings  showed,  that a lot of\nfiles recieve an efficient description!\n\n\n@ENDNODE\n\n@NODE "optionw" "Option ''-w''"\n@TOC "MAIN"\n\nOPTION "-w" (Case of description-text)\n--------------------------------------\n\n\nThis  option allows the selection of the case of the description-text.\nIt''s  default value is "0".  The text will not be affected and stay in\nit''s original upper and lower cased characters.\n\n\n"-w 1" forces DirCutter to make all characters UPPER CASE.\n\n"-w 2" forces DirCutter to make all characters lower case.\n\n\n\n@ENDNODE\n\n\n\n@NODE "lastwords" "Last words and infos..."\n@TOC "MAIN"\n\nSOME LAST (important or not) WORDS\n----------------------------------\n\n-You will see two "Passes" during work. This was made just to inform\n you, that DirCutter is still working. Especially on BIG DIRs you may\n think, that your AMIGA had fucked up.\n\n-After  selecting,  the  description   will be stripped to the minimum\n size:  all  non-ASCII  characters in front of the description AND the\n non-ASCII characters at the back will be stripped without mercy!!\n\n** COMMENT **\n\n Since V2.0 this is changed, because programs with more than one disk\n own descriptions like:\n\n Pagestream 3.0 [1/6]                      Pagestream 3.0 [1/6\n Pagestream 3.0 [2/6]                      Pagestream 3.0 [2/6\n Pagestream 3.0 [3/6]  after stripping:    Pagestream 3.0 [3/6\n Pagestream 3.0 [4/6]                      Pagestream 3.0 [4/6\n Pagestream 3.0 [5/6]                      Pagestream 3.0 [5/6\n Pagestream 3.0 [6/6]                      Pagestream 3.0 [6/6\n\n or\n\n Pagestream 3.0 (1/6)                      Pagestream 3.0 (1/6\n Pagestream 3.0 (2/6)                      Pagestream 3.0 (2/6\n Pagestream 3.0 (3/6)  after stripping:    Pagestream 3.0 (3/6\n Pagestream 3.0 (4/6)                      Pagestream 3.0 (4/6\n Pagestream 3.0 (5/6)                      Pagestream 3.0 (5/6\n Pagestream 3.0 (6/6)                      Pagestream 3.0 (6/6\n\n Since 2.0 right round braces and right cornered braces will NOT be\n stripped any more. (This idea was from MAZ!)\n\n-The resulting DIR will have the filename {name}.CUT.  It is stored in\n the same directory as the source-DIR.\n\n-The  source  DIR is never touched in any way, except reading it.  You\n may test  and  play with DirCutter how much you want:  Your important\n source-data will surrender everything except a HD-crash.\n\n-Some (but few) files will lose their file-description.  Until now the\n only solution for this problem is to edit these cases manually.\n\n-I  put  two  "representative" DIRs  into  the  package. DirCutter was\n designed to  work on these kinds of DIR-style. If your DIR-file has a\n different "style", try to change it, or try to contact me in my local\n boards. PERHAPS I''ll modify DirCutter for your personal needings.\n\n Since V1.9 you''re able to modify the .config by yourself. I think,\n this will give you the ability to solve lots of problems by yourself.\n\n-Play  with  the  included  DIRs  and the CLI-options to find the best\n settings for your own needs.\n\n-A really nice side-effect: MS-DOS-DIRs look VERY strange on the AMIGA.\n DirCutter increases the readability of these DIRs in a fantastic way.\n\n-Since V2.1 the above feature is improved: Only characters, that are\n explained in the chapter @{"GENERAL" LINK "config"}, will survive DirCutters activities.\n All other characters will be stripped, even within the descriptions.\n TIP: Make sure, that you users don''t upload descriptions made with\n mega-silly tools like "C00L-TexT"!! These strange texts will be\n stripped, because no intelligent person wants to own this shit in his\n DIR-archives.\n\n\n@ENDNODE\n\n@NODE "bugs" "Known bugs"\n@TOC "MAIN"\n\nKNOWN BUGS\n----------\n\nIf  there is NO description behind the file-line, some strange effects\nmay  appear.  I don''t want to change this program until my death, so I\ndecided  to  give  you the hint:  BE SURE, THAT YOUR DIRs LOOK LIKE MY\nREPRESENTATIVE DIRs.\n\n\n\n\nBUG REPORTS\n-----------\n\nI''m  very  glad  about every bug report, because I hate buggy programs\n*hi  Microsoft*.   The  experience  showed:   every new DIR causes new\nstrange effects and sometimes nice gurus (since V1.7 removed).  SO:\n\nIf  you  have problems with the DirCutter, don''t kill your neighbours,\ndon''t  get  mad and rape the cat!!  Try to contact me in "The Hidden",\n"Pentagon  Place",  "Bad Taste", "Beerkrug" or in the next life.  I''ll\ntry to fix your probs.\n\n@ENDNODE\n\n@NODE "thanx" "THANX to..."\n@TOC "MAIN"\n\nTHANX!\n======\n\nTroglobyte/DKS	One letter and i have to reprogram the whole DirCutter.\n                Any more suggestions ?!?\n\nMAZ!            Als Betatester immer wieder gern gesehen.\n                Findeste noch Fehler ?!?\n\nGeorge Stark    Deine DIRS sind Schuld an ''ner neuen Version.\n                Jetzt kannste endlich strippen, was Du willst !!\n\n@ENDNODE\n\n@NODE "greetings" "Greetings!"\n@TOC "MAIN"\n\nGREETINGS\n=========\n\nWOW... how long did I have to wait for THIS moment: my personal\ngreetings in my OWN program-documentation!!\n\n\nMcLoud           Hoffentlich normalisiert sich jetzt wieder alles.\nValshare         Möge der PC Dich zur Verzweiflung treiben.\nMario            Sauf nicht soviel.\nECS              Damitte nicht traurig bist: Diese line ist für DICH!\nTSM/Warhead      Legal - illegal - scheißegal.\nByteAndy+Jeannie Jetzt kommen WIR EUCH mal besuchen ;-)\nViola Bros.      Ich warte... immer noch...\nToyo             Scheiß PCs !!!\nMAZ!             Danke für das Design !!\nHoggle           Mit Dir tu ich''s am Liebsten!\nAliex            Mit Dir tu ich''s am Zweitliebsten!\nKai W.           Schick mir mal ''n paar Wattwürmer.\nGeorge Stark     Du wirst Deinen AMIGA vermissen !\nAlfred           Tausch'' den Paintball gegen Diebels. War früher lustiger!\nCarnivore        Ein großer Verlust für den AMIGA !!\nGarfield         Auch Dich wollte ich nicht vergessen.\nZelda            Darf ich Deine schwarzen Lederpöms auch mal sehen ?!?\nGuybrush         Hoffentlich schenkst Du mir nix zum Geburtstag.\nTroglobyte/DKS   No, I won''t forget YOU, the coolest spanish guy around!\n                 The Sangria-Party is OVER !!!!!!!!!!!!!!!!\nThe Special Brothers Gute Idee, Kai ! Du siehst: hier werden Ideen\n                     sofort umgesetzt :-)\n\n...all I have forgotten: please don''t cry! Just call me!!\n\n@ENDNODE\n\n@NODE "history" "History of DirCutter..."\n@TOC "MAIN"\n\nHISTORY\n=======\n\nV1.0		internal version for own purposes\n\nV1.1 (20.04.94)	first release-version for good friends\n                --> working for Cauldron-DIRs\n\nV1.2 (28.04.94) added:\n                - removing of empty lines\n                - removing of "spacy"-lines\n                - removing of Boss-Nuke-lines\n                --> now working for BloodyDecision-DIRs\n\nV1.3 (02.05.94) removing of some strange effects\n\nV1.4 (17.06.94) Totally rewritten source-code.\n                added:\n                - selecting lines with percentage\n                - different select-algorithms\n                - variable number of bottom-lines\n                - testprintout for checking the settings\n                - really consequent stripping of text\n                - now compiled with SAS-C -> fuck ixemul.library !!!\n\nV1.5 (06.07.94) added:\n                - remove " --=="-lines\n                - remove "<<BK"-lines\n                --> now working for SkaraBrae-DIRs\n\nV1.6 (14.07.94) removed a guru-causing bug\n\nV1.7 (17.07.94) removed a division-by-zero-error\n                added:\n                - remove "SkARa"-lines\n                --> now BETTER working for SkaraBrae-DIRs\n\nV1.8 (27.07.94) new Cli-Layout © by MAZ!\n\nV1.9 (29.07.94) added DirCutter.config\n\nV2.0 (13.08.94) Don''t strip ")" and "]" on the right side any more.\n                First official release version.\n\nV2.1 (10.10.94) Doomsday''94 made it possible: no one realized the\n                necessity of this tool. How STOOPID, boyz !!\n                But new ideas were given:\n                added:\n                - stripping of C00L-Text-ASCIIs within the lines\n                - Option ''-w'' for controlling UPPER and lower chars\n                - now support for the VERSION-command !\n\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',77036,5,0,NULL,NULL,'trsi_dir','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_dls','TRSI-DLS.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-DLS.LHA','rexxdoor','XIM','REXXDOOR',NULL,'[-Dr.Dre!/tRSi]','TRSI','/__   \ ,\ /__ _\ ,\ /__    ,\ /_ _ ,\ \_/. ____/\\/._ ___/\\/. ____/\\_/. _/\ //  /\__\/// /  ./ //____ ./\/ //  /\/',replace('  ___/\___   __/\___   __/\___   __/\_  \n /__   \ ,\ /__ _\ ,\ /__    ,\ /_ _ ,\ \n \_/. ____/\\/._ ___/\\/. ____/\\_/. _/\\n  //  /\__\/// /  ./ //____ ./\/ //  /\/\n /___/ /   /__/___/ //______/ / /___/ / \n \___\/    \__\___\/ \______\/NL\___\/  \nDesc. Logo Snap v1.2  by [-Dr.Dre!/tRSi]\n','\n',char(10)),'LogoSnap.Guide',replace('@database Description Logo Snap v1.2 by [-Dr.Dre!/tRSi]\n\nCopyright (C) 1993 by [-Dr.Dre!/tRSi], Germany\nAll Rights Reserved\n\n@Remark $VER: Version v1.1 (Monday 17-Jan-94 13:32:57)\nRemark AmigaGuide DataBase for Description Logo Snap v1.2 by [-Dr.Dre!/tRSi]\n\n@node MAIN "Description Logo Snap v1.2 (Monday 17-Jan-94 13:32:57) Document for /X"\n             ____                        ___                     :\n           ._\  /________________________\_/ ____________________¦_ _\n           |  \/   __ _ _               _\_ /_      _/           |\n           |    _ _\         T.R.S.I      // \_    / \_ _     \\ |\n           | ____________________________//____________________\ |\n       ____| \        ___________      /_____        /______  /  |____\n      /\___\  \      /    .|   _/    _/\    /_______/       \/|  /___/\\n      \/___/   \  __/     ¦|   \      \_\_____     \_        ¦|  \___\/\n           |    \/ /      :|    \      /     /      /        :|  |\n           | \    /________|  _  \    /____________/|_________| _|\n           | \\         _ _  \_   \  /_ \\  _ __ _          _ _/ |\n           | \\\           \_/     \/ \_//       /__ _         \ |\n        _ _|________________\__________/ \__________________ /\ _|H2o!\n           ¦                           /\                   /__\\n is proud to present: Description Logo Snap v1.2 (Monday 17-Jan-94 13:32:57)\n                         @{"     Introduction      " Link no1}\n                         @{"     Requirements      " Link no2}\n                         @{"     Installation      " Link no3}\n                         @{"      Menu Help!       " Link no4}\n                         @{"       Creditz!        " Link no5}\n                         @{"      Greetings!       " Link no6}\n                         @{"     tRSI Boards!      " Link no7}\n@endnode\n@node no1 " Introduction"\n\nThis is a usefull Door to style your Dirlisting much better...\nIf a User have an Major Release but No GroupLogo then he can call the\nDoor and Grab a Description Logo from the Major Group...\nAlso includet now more Logos from one Group allowed with scroll Routine.\nUntil this Versoin you can allow Users with in the cfgfile specifies Level\nTo add own Description Logos and many more...\n\nhave phun with the door...\n[-Dr.Dre!/tRSi]\n\n@endnode\n@node no2 " Requirements"\n\nYou need an Amiga 500/1000/2000/3000 (The Sysops with an A4ooo or A12oo \nshould call my BBS to receive an uncompiled Version)\nKickstart 2.0 or higher\nAmi Express 2.xx - 3.xx (Registered)\nAn running RPStart\nrexxplsextnd.library\nRexxplslib.library\nrexxsyslib.library\nrexxsupport.library\nin your Libs: but they are included\n\nThats all...\n\n@endnode\n@node no3 " Installation"\n\nFirst copy all Libs: (If you dont have them allready) into your libs: Dir\nCopy the Snap.info to your BBS:Commands/bbscmd/\nand make shure you run rpstart in your Startup-Sequence.\nThen create a Directory called LogoSnap in your Doors...\nThere you copy all Files and Dirs from the Archive Directory \nBBS/Doors/LogoSnap/\n\nThere must be in all this Files and Dirs...\n\nLogos              Dir (Dir with all the Logos)\nLogosnap.cfg         8 (The COnfig File)\nLogoSnap.AiM     79176 (The Door self)\nLogoSnap.Guide    6650 (The Guide File)\nLogoSnap.Contain   731 (The Contain FIle with all Logos)\n\nAfter this jump into the Chat.Cfg File and change the Level...\n\n------------------cut here------------------\n100\n253\n------------------cut here------------------\nLine.1=Level to allow a User to add own Logos\nLine.2=Level to allows a User to Edit/Remove Logos\n\nThis is all what you have to do...\n\n@endnode\n@Node no4 " Menu Help"\n\n                            _ ___     __     ___ _\n                            .:::/___ /\_\ ___\:::.\n                               .:::::\/_/:::::. \n                          Description Logo Snap v1.2\n                · [©] All Rights by: Dr.Dre!/tRSi `94 [©] ·\n\n          __              1>...... Snap Group Logo             __\n         /_/\             2>..... Enter Group Logo            /\_\\n         \_\/             3>.... Remove Group Logo            \/_/\n        + :.              4>... Download all Logos             :. +\n          ||              5>.............. Creditz             ||\n          :+              Q>................. Exit             :+\n          o                                                    o\n             _ __ __                                    __ __ _\n    _   _ __ ___ /\_\        Make your Choice:  Exit!  /_/\ ___ __ _   _\n             _ __\/_/                                  \_\/__ _\n\n                    This is the Main menu from the Door\n\n1. Grab Description Logo\n2. Enter own Group Logo(s)\n3. Remove/Edit Logos\n4. Download al Logos as Lha File\n5. View Creditz and some Greetings\nQ. Exit the Door\n@endnode\n@Node no5 " The Creditz!"\n\n              Copyright (C) 1994 by [-Dr.Dre!/tRSi], Germany\n                            All Rights Reserved\n\n             The AmigaGuide DataBase written by [-Dr.Dre!/tRSi]\n\n    For more good Doors call my BBS under 49 (0) 2131 275756 & 275634\n               · [ · MARLEYS COFFEE SHOP - tRSi GHQ · ] ·\n\n      Thanx to Skin! for using some of your great Styles in my Doors!\n\n@endnode\n@Node no6 " Greetings"\n\n                   The Greets are going to this Dudes...\n\n ByteAndi/X-Design, Spy/X-Design, Remo/X-Design, X-Treme/TRSI, Saito/TRSI\n    Gandalf/Faith, Silver/Faith, McLoud/TRSI, Irata/TRSI, Triton/Fth\n Skylark/LSD, Nick, Metoner/TRSI, J.Walker/TRSI, Crazy/TRSI, Valshare/TRSI\n    Vicous/LSD, Richi/Flt, Steve/D&R, Amicom, -rS!, Empire/Mst, Mr.VAiN\n            APOLLO, BJoerN/Pdy, Jive/TRSi, Scope/Trsi, SkiN!\n          and simply all tRSi Member an other Doodes I forgot...\n\n@endnode\n@Node no7 " tRSi Boards Worldwide"\n\n                 To Contact me Call any of this Boards...\n           -==================================================-\n\n   Cauldron.......................German  hq............++49 Pure Elite\n   Marleys Coffee Shop............German  hq............++49 Pure Elite\n   Boondocks......................Europe  hq............+31-548-040-653\n   Final Impact...................Swedish hq............++46-54-113-486\n   Flying Spirits.................Swiss   hq............+41-217-282-524\n   Savage Amusement...............Austia  hq............+43-767-227-743\n   Zenlandia......................Finnish hq............+358-088-82-144\n\n\n           -==================================================-\n@endnode\n','\n',char(10)),NULL,'auto-added',133023,14,0,NULL,NULL,'nvx_rem5','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_dm1','TRSI-DM1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-DM1.LHA',NULL,'XIM','DoorMenu.x',NULL,'Dr.Dre!/tRSi','TRSI','l___       /      \/    _/_______.: /       /   /  _/\___      /    : /_______/-rS!\_____\  _____/     |',replace('    ._________________  ______\n    l___       /      \/    _/_______.:\n      /       /   /  _/\___      /    :\n     /_______/-rS!\_____\  _____/     |\n           /_______|     \/`94/_______|\n   DoorMenu v1.o by Dr.Dre!/tRSi\nAn XiM Module for AmiExpress 2.xx - 3.xx\n','\n',char(10)),'Doormenu.guide',replace('@database DoorMenu v1.o - by Dr.Dre!/TrSi\n\nCopyright (C) 1994 by Dr.Dre!/tRSi Germany\nAll Rights Reserved\n\n@Remark $VER: Version v1.o (Monday 31-Jan-94 14:13:31)\nRemark AmigaGuide DataBase for DoorMenu 1.o\n\n@Node MAIN "DoorMenu v1.o (Monday 31-Jan-94 14:13:31) Dcoument for /X"\n\n                   ._________________  ______\n                   l___       /      \/    _/_______.:  \n                     /       /   /  _/\___      /    :\n                    /_______/-rS!\_____\  _____/     |''94  \n                          /_______|     \/   /_______|\n\n     is proud to present: DoorMenu 1.o, XiM Module for /X 2.xx - 3.xx\n\n                       English Doc     German Doc\n                     @{" Introduction  "Link no1} @{"  Einleitung   "Link nr1}\n                     @{" Requirements  "Link no2} @{" Anforderung   "Link nr2}\n                     @{" Installation  "Link no3} @{" Installation  "Link nr3}\n                     @{"   Copyright   "Link no4} @{"   Copyright   "Link no4}\n                     @{"   Greetings   "Link no5} @{"    Gruesse    "Link no5}\n                     @{"          TRSI Boards          "Link no6}\n@endnode\n@node no1 " Introduction"\n\n     This is a cool Doormenu, it allows you to make 2 Pages Of Doors.\nYou can jump into the Doormenu, view all available Doors, execute one and\njump back to my Doormenu after executing the other Commands.\nNo Sysop Commands are supportet from the Doormenu like 1,2,3,4,5,DS,VS\nand so on...\n\nHave Phun with it...\nDr.Dre!/tRSi                                         @{" Main Menu " Link main}\n@endnode\n@node nr1 " Einleitung"\n\nDooeMenu ist ein externes Program das einem User alle available Commands\nanzeigt... Er kann direkt von meinem DoorMenu aus in eine andere Door \nspringen, nach verlassen der anderen Door springt er automatisch in das \nDoormenu zurueck...\nEs werden keine Sysop Commands supportet, wie 1,2,3,4,5,DS,VS usw.\n\nViel Spass damit...\nDr.Dre!/tRSi                                         @{" Main Menu " Link main}\n@endnode\n@node no2 " Requirements"\n\nU need to run DoorMenu successfull Any Version of AmiExpress.\nKickstart 2.o or higher...\nAnd thats all...\n\n                                                     @{" Main Menu " Link main}\n\n@endnode\n@node nr2 " Anforderungen"\n\nDamit DoorMenu vernuenftig arbeiten kann brauchst irgendeine Version\nvon AmiExpress (2.xx-3.xx)\nKickstart 2.o oder hoeher\nMehr wird nicht benoetigt...\n\n                                                     @{" Main Menu " Link main}\n\n@endnode\n@node no3 " Installation "\n\nCreate a Directory in your Doors: called DoorMenu.\nThere copy the File Doormenu.x - DoorMenu1.txt and DoorMenu2.txt in.\nnow Edit the DoorMenu1.txt and DoorMenu2.txt, build in your Doors like\nmy Example... this are only the txt files which are displayed in the BBS.\nAll Access Levels from the Cmd`s.Info are supportet...\nAfter them copy the Open.Info to your BBS:Commands/BBSCmd/\nNow the DoorMenu is successfull installed...\n\n                                                     @{" Main Menu " Link main}\n@endnode\n@node nr3 " Installation"\n\nCreate eine Directory in den Doors: namens DoorMenu\nDa kopiere folgende Files rein.\n\nDoormenu.x\nDoorMenu1.txt\nDoorMenu2.txt\n\nEditiere nun die Files DoorMenu1.txt und DoorMenu2.txt, dieses sind die\ntexte die von dem Doormenu in der BBS angezeigt werden...\nSeht euch meine beispiel Texte an...\nEs werden all AccessLevel von dem externen Command Icons supportet, also\nist es nicht moeglich ein Command aufzurufen auf das man keinen access hat.\nDanach kopiert das Open.Info in eure BBS:Commands/BBSCmd/\nNun ist alles erfolgreich Installiert...\n\n                                                     @{" Main Menu " Link main}\n@endnode\n@node no4 " Copyright"\n\n\n                 DoorMenu 1.o is written by Dr.Dre! of TRSI\n                         All Rights Reserved ©1994\n\n              The AmigaGuide DataBase written by Dr.Dre!/tRSi\n\n        If you have any Problems with the Checker so contact me at\n                            @{" Marleys Coffee Shop " Link Coffee}\n\n                                                     @{" Main Menu " Link main}\n\n@endnode\n@node no5 " Greetings"\n\n                   The Greets are going to these Dudes...\n\n   ByteAndi/X-Design, Spy/X-Design, Remo/X-Design, X-Treme, Saito/TRSI\n    Gandalf/Faith, Silver/Faith, McLoud/TRSI, Irata/TRSI, Triton/Fth\n Skylark/LSD, Nick, Metoner/TRSI, J.Walker/TRSI, Crazy/TRSI, Valshare/TRSI\n    Vicous/LSD, Richi/Flt, Steve/D&R, Amicom, -rS!/TRSi, Empire/Mst, \n      Mr.VAiN, APOLLO, BJoerN/Pdy, Jive/TRSi, Scope, SkiN!,Mario/TRSI\n          and simply all tRSi Member an other Doodes I forgot...\n\n\n                                                     @{" Main Menu " Link main}\n@endnode\n@node no6 " TRSI Boards Worldwide"\n\n                 To Contact me Call any of this Boards...\n\n   obituary.......................World    HQ............+1-310-652-5688\n   biohazard......................Canadian HQ............+1-905-841-0965\n   cauldron.......................German   HQ............++49 Pure Elite\n   marlEys coffEE shop............German   HQ............++49 Pure Elite\n   MayDay.........................German   HQ............++49 Pure Elite\n   boondocks......................European HQ............+31-548-040-653\n   final impact...................Swedish  HQ............++46-54-113-486\n   flying spirits.................Swiss    HQ............+41-217-282-524\n   savage amusEmEnt...............Austria  HQ............+43-767-227-743\n   zEnlandia......................Finnish  HQ............+358-088-82-144\n\n\n                                                     @{" Main Menu " Link main}\n@endnode\n@node Coffee "Marleys Coffee Shop - TRSI german hQ"\n\n              * tRiStAR & RED sECtOR * gERmAN hEADqUARtER\n                                           _______    ._____\n      _______  ____.______  ______________/   .  /____|    /_______\n      \      \/    |      \/   _  \      /   ___/_    l   /   __  /\n       \           |      \\   /  /_    /_________l____  /\__   \/\n        \    \/____l________\  \____|______|    |_______/________\\n         \____\         /______|                       _______\n                 ____          _______________________/   .  /\n                /  __l_. _____/     __/     __/   .  /   ___/_.\n               /   |   |/     \     _/\     _/   ___/_________|\n              /________|      \\____|  \____|_________|\n                       \_______/         _____    \n                      __________________/     \__________\n Dr.Dre!/tRSi        /   __  /    /    //      \    .   /\n                    /\__   \/         /\_______/    ___/\n  J.Walker/tRSi    /________\   /____/-rS!/aRt/_____|\n                          /____/\n\n                                                     @{" Main Menu " Link main}\n@endnode\n','\n',char(10)),NULL,'auto-added',15827,5,0,NULL,NULL,'trsi_dm1','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_dp','TRSI-DP.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-DP.LHA',NULL,'XIM','/\                  /\________|__',NULL,NULL,'TRSI','______/  \______  /\______/    _____/\ \   _    o _   /_/__     /____   _ /__\Sk¡n \__/     \\__/.   /    /    /   //   o\',replace('       /\                  /\________|__    \n______/  \______  /\______/    _____/\      \n\   _    o _   /_/__     /____   _ /__\Sk¡n \n \__/     \\__/.   /    /    /   //   o\    \n+--/________\//    \   /________ /     \\--+\n: /         /______|\____\     \/\______/  :\n+----- Tristar & Red Sector Presents ------+\n   Dre!_Page v1.1Final - [-Dr.Dre!/tRSi]\n','\n',char(10)),'Dre!_Page.GUIDE',replace('@database Dre!Page 1.1final\n\nCopyright (C) 1993 by [-Dr.Dre!/tRSi], Germany\nAll Rights Reserved\n\n@Remark $VER: Version v2.o (Sunday 16-Jan-94 19:43:22)\nRemark AmigaGuide DataBase for Dre!_Page 1.1final by [-Dr.Dre!/tRSi]\n\n@node MAIN "Dre!Page 1.1final (Dez 15 1993, 11:32:54) AmigaGuide Document for /X"\n             ____                        ___                     :\n           ._\  /________________________\_/ ____________________¦_ _\n           |  \/   __ _ _               _\_ /_      _/           |\n           |    _ _\         T.R.S.I      // \_    / \_ _     \\ |\n           | ____________________________//____________________\ |\n       ____| \        ___________      /_____        /______  /  |____\n      /\___\  \      /    .|   _/    _/\    /_______/       \/|  /___/\\n      \/___/   \  __/     ¦|   \      \_\_____     \_        ¦|  \___\/\n           |    \/ /      :|    \      /     /      /        :|  |\n           | \    /________|  _  \    /____________/|_________| _|\n           | \\         _ _  \_   \  /_ \\  _ __ _          _ _/ |\n           | \\\           \_/     \/ \_//       /__ _         \ |\n        _ _|________________\__________/ \__________________ /\ _|H2o!\n           ¦                           /\                   /__\\n         is proud to present: Dre! Page v1.1 (Jan 16 1994, 20:18:54)\n                         my first Release for tRSi\n                         @{"     Introduction      " Link page1}\n                         @{"     Requirements      " Link page2}\n                         @{"     Installation      " Link page3}\n                         @{"      Greetings!       " Link page4}\n                         @{"       Creditz!        " Link page5}\n                         @{"     FAITH BOARDS!     " Link page6}\n@endnode\n@node page1 "Introduction Dre! Page v1.1"\n\n                         · [ · INTRODUCTION · ] ·\n\nDre! Page is at least one of the best and fastest Pager`s for Ami-Express.\nSome new features are included.\n\nIf you have an A4ooo or A12oo and the Door doesn`t work so Call my BBS under\n49 (0) 2131 275756 or 575634 for an uncompiled and registered Version!\n\nAlso call for some good ideas for another Doors or some Special Private\nDoors for your own BBS.\n\nBut now enjoy this really fine door...\n      \n  [-Dr.Dre!/tRSi]  \n\n@endnode\n@node page2 "Requirements"\n\n                         · [ · REQUIREMENTS · ] ·\n\nAll what you need is any Model of an AMIGA OS2.o or higher!\nAmiExpress 2.xx - 3.xx\n\nThat all...\n@endnode\n@node page3 "INSTALLATION"\n\n                         · [ · INSTALLATION · ] ·\n\nUnpack the Archive TRSI-DP.Lha to your RAM Disk.\nCreate a Directory in your Doors: called Pager.\nThen copy all files from the bbs/doors/Pager/ Directory into your\nDoors:Pager/ Directory.\nThere are 3 txtfiles available...\n\nChatOn.txt  - This Text will be displayed if the Chatflag is ON  !!!\nChatOff.txt - This Text will be displayed if the Chatflag is OFF !!!\nChatno.txt  - This Text will be displayed if a User have paged more\n              then allowed...\n\nA User with Level 100 or lower can Page you only 3 Times...\nIf he try to page further, he will see a nice Text (Chatno.txt) which\nyou can configure yourself...\nAlso he will alltimes see how many Pages are left.\n\nFor Users with Level 100 or higher is it possible to page 10 Times.\n\nThe Pager will alltimes write the Chat Reason into your Callerslog.\nIf no Callerslog exists, the Pager will not create one...\n\n@Endnode\n\n@node page4 "GREETINGS"\n\n                         · [ ·  GREETINGS!  · ] ·\n\n                   The Greets are going to this Dudes...\n\n ByteAndi/X-Design, Spy/X-Design, Remo/X-Design, X-Treme/TRSI, Saito/TRSI\n    Gandalf/Faith, Silver/Faith, McLoud/TRSI, Irata/TRSI, Triton/Fth\n Skylark/LSD, Nick, Metoner/TRSI, J.Walker/TRSI, Crazy/TRSI, Valshare/TRSI\n    Vicous/LSD, Richi/Flt, Steve/D&R, Amicom, -rS!, Empire/Mst, Mr.VAiN\n                APOLLO, BJoerN/Pdy, Jive/TRSi, Scope/Trsi\n          and simply all tRSi Member an other Doodes I forgot...\n\n@endnode\n@node Page5 "CREDITZ"\n\n\n                          · [ ·   CREDITZ   · ] ·\n\n              Copyright (C) 1993 by [-Dr.Dre!/tRSi], Germany\n                            All Rights Reserved\n\n             The AmigaGuide DataBase written by [-Dr.Dre!/tRSi]\n\n    For more good Doors call my BBS under 49 (0) 2131 275756 & 275634\n               · [ · MARLEYS COFFEE SHOP - tRSi GHQ · ] ·\n\n@endnode\n@node page6 "tRSi BOARDS"\n\n                    · [ · tRSi BOARDS WORLDWIDE · ] ·\n\n                  To Contact a Call any of this Boards...\n           -==================================================-\n\n           -==================================================-\n\n@endnode\n','\n',char(10)),NULL,NULL,19161,5,0,NULL,NULL,NULL,'scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_dul','TRSI-DUL.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-DUL.LHA','DayUL','XIM','DayUL','0.71','ROMULUS/TRSI','TRSI','33.6 DigITal-X Prd/NirVana Dist Site! 33.6',replace('DayUL V0.71 by ROMULUS/TRSI\n33.6 DigITal-X Prd/NirVana Dist Site! 33.6\n','\n',char(10)),'DayUL.doc',replace('\n                           ______ ___  ___       ___ __   ___\n                          /     //  /\/  /_     /  // /\ /__/\\n                         /__   //__/ /  // \   /  //_/ /_\__\/\n                         \_/  /\\__\/  //__/\__\  \\_\//  /\\n                         /  / /&f /  / \__\/ //  /\  /  / / ThE\n                        /__/ /   /__/ /   /_//__/ / /__/ / SlEEPiNG\n                        \__\/    \__\/    \_\\__\/  \__\/ GoDS\n                        ->Presents: DayUL V0.71 by ROMULUS/TRSI\n\nWhat is it?\n\nDayUL is a AmiEx Utility and can only be used from CLI or a script file.\nI think the most useful posibility to place it is the script AmiEx execute when a User \ndo a LogOff.\nSo the output will updated everytime when it is useful.\n\nBut if you'' re a Sysop and make a local UL, there won'' t be any change, because \nthere is no AmiEx that run DayUL.\nYou can update your day UL'' s also, using DayUL from the CLI.\nThe parameters(later) are the same than them used in the script.\n\nWhat does it do?\n\nDayUL create a list of every (not all...) file which has been UL on the current day.\nThe output file could be a bulletin or shown after a LogIn, you'' ve to decide how to \nuse it...\n\nFeatures:\n\n- Don'' t count and show fakes\n- Show number and bytes of UL files\n- Is very fast (ca. 15 sec for a size of 1 MB) * read news *\n- Could be append to on other file or create a own file\n- Use the dir file and not the callerslog, so local UL'' s are possibel\n- Could be used differend for every conference, so no PC files are shown in an \n  Amiga-Conf\n- Should work on every Amiga and every version of DOS\n- It works...\n- It only includes 5 Backdoors(joke)\nSince Version 0.7 new:\n- Speeded (ca. 20% Faster, 10 - 12 sec for 1 MB are possibel)\n  (Tested on my A3000/25, Read/Write from/to HD!!!)\n- New Option = UPDATE * read option UPDATE *\n- Internal changes...\nSince Version 0.71 new:\n- Is no more such easy to link backdoor(hope so)\n- Bug fixing\n- Internal changes...\n\n\nUsage:\n\nDayUL <BBS_DIRFILE> <OUTFILE> [APPEND]\n\n\nBBS_DIRFILE:\nThe file to search for the dir entries of the current day\nMight be BBS:DIR1 or whatever you want...\n\n\nOUTFILE:\nThe file you wanna create (or append) as output.\nThat could be BBS:BULLETINS/Bulletin10.txt or what ever you want...\nA typical OUTFILE should look like this, snaped from the MayDay:\n\nep_page1.lha CMX-LUI1.DMS CMX-LUI2.DMS GLORY100.TXT 1200FIX8.LZH CHAT29.LHA\n IBB_ULUD.EXE PSYCHO.TXT AZAP130.LHA OPL1231.LHA RUN68017.LHA UCHSS218.DMS\n    arkham.exe 2400PROT.LZH RIP!.TXT OWS120A.LHA 93WAREZ.TXT CR-RD01.DMS\n\n Status: 18 files, 3165726 Bytes uploaded at Wednesday, 02-03-93 at 20:25:05\n    DayUL V0.4 (c) by ROMULUS written for the MayDay BBS - +49-2241-73047\n\n\nAPPEND:\nAn optional parameter, the default entry is KILL.\nKILL means that DayUL should create a new file, and delete the output file, when it \nallready exists.\nIf APPEND is set, a allready existing file won'' t be deleted and the output from DayUL \nwill be append to the existing file.\nIf no file exist DayUL will create a new file.\n\n\nUPDATE:\nIf you have a text file that won'' t be deleted, but you want to update the\nDayUL output after every LogOff, you can'' t use append, because after every\nLogOff the Upload Statistic will be append after every call...\nSo after two calls the file includes two statistics, after three calls three etc. .\nA posibility is that you'' ve first to delete the file, copy it and than\nexecute DayUL with the option APPEND...\nBut if you set the parameter UPDATE, there will be ONLY one statistic, because\nof DayUL only update the old one...\nYou'' ve NOT to delete or copy the file!!!\nHope ya like it!\n\n\nAt last\n\nHope you know what you'' ve to do.\nIf you don''t I think you'' ve to learn how to use your brain (or I'' ve to learn english)...\nWell, if there are any questions or you want to have a special version for your BBS or\nyou know a bug or you'' re looking for updates or you'' ve an idee what I should \ninclude, contact me at one of the following BBS:\n\nMayDay, Cauldron, Los Endos, Riverside, Skara Brae, Ectoplazm,\nreference-board, Lighthouse or every Board I'' ve access to (ROMULUS)...\n\nThanx to Zig Zag (May Day), McLoud (Cauldron), Accu (Riverside), Gandalf(Los Endos),\nAmicon(Skara Brae) and Speedlock(Lighthouse) for betatesting my tools!\n\n                          ROMULUS/SCOOPEX\n\n\nAnd don'' t forget to call:\n\n      ___   ___   ___   ___  ____   ___  __ __\n     /   \ /   \ /   \ /   \|    \ /   \|  |  |     ___  ____  ___ [V]\n    |  ___|: |__|: |  |: |  |: |  |: |  |  |  |    /. _||o | |/  .\\n   ¯|___  || |__|| |  || |  ||  _/||  __|>   <¯¯¯¯/  / _|| | /  | \\¯¯¯¯\n    |     |: |  |: |  |: |  |: |  |: |  |  |  |   \  \| |:   \  |__/_\n   ==\___/=\___/=\___/=\___/|__|===\___/|__|__|====\____|__|_|\______|==\n   ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n                 -=>» THE BBS WITH THE >4< F`s  <«=-\n          __          __                __                 __\n         /_          /_                /_                 /_\n        /  AST <«»> /  RIENDSHIP <«»> /  AIR RATIOS <«»> /  UN\n\n               -=>» AMIGA - SNES - GENESIS - /X-TOOLS «<=-\n\n              14.4 HST           16.8 HST            16.8 HST\n        +49(0)2241-73047   +49(0)2241-805841   +49(0)2241-79345\n              NODE 1             NODE 2              NODE 3\n\n      ___________    ____________  /¬\     _____     ____________  /¬\\n     /  _  ¬\_  ¬\__/  __   ¬\  ¬\/   \   /    ¬\  _/  __   ¬\  ¬\/   \\n    /   ¬\   ¬\   ¬\   \¬    /        /  /     __\/    \¬    /        /\n   /     /    /    /   /    /\__     /  /      ¬/ \    /    /\__     /\n  /     /    /    /   /    /  /¬    /  /       /  /   /    /  /¬    /\n /     /____/____/   /____/  /     /   \______/  /   /____/  /     /   \n \    /        \____/        \    /-rS!    \____/___/        \    /    \n  \  /                        \  /                            \  /     \n   \/                          \/                              \/\n\none of german fastes...\n\n------------------------------------ CUT HERE ---------------------------------\n\nAfter calling the MayDay call these Boards:\n(Add here!)\n\n','\n',char(10)),NULL,'auto-added',20173,8,0,NULL,NULL,'trsi_dul','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_dw2','TRSI-DW2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-DW2.LHA','dRE!WAll','XIM','dRE!WAll',NULL,'dR.dRE/tRSi','TRSI','_____/___/_____/\___________ .__________   // __________/---------------. |  /   /  / _/\____  \/   /dR.dRE! Of tRSi |',replace('      /\__\n_____/___/_____/\___________\n.__________   // __________/---------------.\n|  /   /  / _/\____  \/   /dR.dRE! Of tRSi |\n| /  //__/   \ ______/  //  /X iNNOVAtiON  |\n|/__ /   \____\/-Mo!/__ /     PRESENtS     |\n`--\/-----------------\/-------------------''\n      dRE!WAll v2.0 (C) bY dR.dRE/tRSi\n fREE CONfiGURAblE WAll, CYClE OUtPUStYlES\n WRitE ANONYM, COlOR CYCliNG, MAkE YOUR OWN\n OUtPUtStYlES, iNStAllER SUPPORt ANd MORE..\n','\n',char(10)),'dRE!WAll.GUidE',replace('@database dRE!WAll\n@$VER: dRE!Wall v2.0\n@author "DR.DRE!/tRSi"\n@(c) "dR.dRE!/tRSi (tRSi /X·iNNOVAtiON)"\n@remark Created with Heddley v1.1 (c) Edd Dumbill 1994\n\n@node "Main" "Inhalt dieses Guidesfiles"\n@{fg highlight}                     /\\__\n               _____/___/_____/\\___________\n               @{fg fill}.@{fg highlight}__________   /@{fg text}/@{fg highlight} __________/@{fg fill}---------------.@{fg highlight}\n               @{fg fill}|@{fg highlight}  /   /  / _/\\____  \\/   /    @{fg text} tRSi  @{fg fill}     |@{fg highlight}\n               @{fg fill}|@{fg highlight} /  @{fg text}/@{fg highlight}/__/   \\ ______/  @{fg text}/@{fg highlight}/       @{fg text}/X@{fg fill}        |@{fg highlight}\n               @{fg fill}|@{fg highlight}/__ /   \\____\\/@{fg fill}-Mo!@{fg highlight}/__ /    @{fg text}iNNOVAtiON!@{fg fill}   |@{fg highlight}\n               @{fg fill}`--@{fg highlight}\\/@{fg fill}-----------------@{fg highlight}\\/@{fg fill}-------------------''@{fg text}\n\n                   @{fg highlight}iS pROUd tO pRESENt @{fg text}: @{fg fill}dRE!WAll v2.0@{fg text}\n\n                   @{" iNtROdUCtiON AbOUt dRE!WAll v2.0 " link "Document_0" 0}\n                   @{"   tHE iNStAll Of dRE!WAll v2.0   " link "Document_1" 0}\n                   @{"   WhAt iS NEW ON dRE!WAll v2.0   " link "Document_2" 0}\n                   @{"  All fUNCtiONS Of dRE!WAll v2.0  " link "Document_3" 0}\n                   @{"       MODiFYAbLE tOOltYPES       " link "Document_4" 0}\n                   @{"              CREditS             " link "Document_5" 0}\n                   @{"             GREEtiNGS            " link "Document_6" 0}\n                   @{"       (tRSi /X·iNNOVAtiON)       " link "Document_7" 0}\n                   @{"        REGiStER dRE!tOOlS        " link "Document_8" 0}\n                   @{"      OthER dRE! tOOlS/dOORS      " link "Document_9" 0}\n\n@endnode\n\n@node "Document_0" "iNtROdUCtiON AbOUt dRE!WAll v2.0"\n\n            Some Informations about the Door and he can really\n            --------------------------------------------------\n\n1) Probably dRE!WAll v2.0 is the fastest and the most powerfull Wall for\n   Amiexpress 4.XX Professinal. dRE!WAll is 100% free configurable.\n   Each Sysop can take influence of the design.\n   Additional dRE!WAll is able to change the design at each call from any\n   User. View @{"fUNCtiONS Of dRE!WAll" link "Document_3" 0}.\n   Also dRE!WAll is able to write from a modifyable Level Anonymous, or\n   you can switch the Colors ON/OFF via a Tooltype, if the Colors are\n   on, then dRE!WAll willl cycle the Colors after writing from every\n   new Wall Line.\n\n   View @{"tOOltYPES" link "Document_4" 0}\n\n   and many more ...\n   have fun with the Door...\n   dR.dRE! of (tRSi /X·iNNOVAtiON)\n\n  This Program is a public Version and can may be freely distributed for\n  non-commercial purposes, as long as all the files in the original\n  archive are present and have not been modified in any way.\n  If you want to register all my Doors/Tools so view @{"REGiStER dRE!tOOlS" link "Document_8" 0}\n\n   If you like a program so please buy it, keep the Programers Programing.\n\n@endnode\n\n@node	"Document_1" "tHE iNStAll Of dRE!WAll v2.0"\n\n                   How to Install dRE!WAll v2.0\n                   ----------------------------\n\nAfter unpacking the Archive TRSI-DW2.LHA, make a double Klick on the\nInstall Icon, and follow the Instructions of the Installer.\n\n(Needs the Commodore Installer (C) by Commodore in any accessbale Path)\n\n\n                   How to Install without the Installer\n                   ------------------------------------\n\nCopy the complete Directory dRE/dRE!WAll to your DOORS:.\nAfter this copy the WAll.iNfO to your BBS:COMMANDS/BBSCMD/ .\nNow view the @{"fUNCtiONS" link "Document_3" 0} and edit the @{"tOOltYPES" link "Document_4" 0}.\n\n@endnode\n\n@node "Document_2" "WhAt iS NEW ON dRE!WAll v2.0"\n\n                              WhAt iS NEW ???\n                              ---------------\n\n1) Changed the READ/WRITE Routine of the DataFile, the new one is much\n   faster, and so dRE!WAll needs no longer the DataFile in the ENV:\n\n2) Full modifyable Design of the Wall. @{"fUNCtiONS" link "Document_3" 0}\n\n3) dRE!WAll is now able to cycle between free defineable Outputstyles.\n   This means at each Call from the BBS the Wall will look different.\n\n4) Highly optimized Code, replaced many SAS/C Commands against other\n   faster DOS Commands.\n\n5) 100% refuse of the Sign > ~ < and the Sign > + < so no hacking about\n   the Wall are possible, and also no carrier droppin if a User entered\n   the the Wall a  "+++" !!!\n\n@endnode\n\n@node	"Document_3" "All fUNCtiONS Of dRE!WAll v2.0"\n\n                    possible functions of dRE!WAll v2.0\n                    -----------------------------------\n\n                   How to influence the Style cycling ?\n\nIn the Directory DOORS:DRE/DRE!WALL/ are 5 for defined Otputstyles,\ncalled dRE!WAll.StYlE.1 - dRE!WAll.StYlE.5, for sure you can use this\n5 Styles, but also you can modify or edit new ones.\nIf you wish to add some new Styles, they must called dRE!WAll.StYlE.X\nNumeric from 1 to X, the next one must called dRE!WAll.StYlE.6, after\nthis you have to change the Numbers of Styles in the DOORS:DRE/DRE!WALL/\nDRE!WALL.iNfO, to change it, change the Tooltype "STYLES=<#>".\nIf you have 5 Styles the Tooltype must be "STYLES=5".\n\n                 How to influence the Write Anonym Option\n\nChange the Tooltype ANONYMOUS=<#> in DOORS:DRE/DRE!WALL/DRE!WALL.iNfO.\nIf you set it to "ANONYMOUS=200", this means each User with Level 200\nor higher are able to add a Line anonym to the Wall.\n(The user will be asked if he wish to write anonym)\n\nNow change the Tooltype "COLORS" in DOORS:DRE/DRE!WALL/DRE!WALL.iNfO,\nif you set this Tooltype the Wall will wor in color modus, if you don`t\nset them the Wall will wor in 2 color modus.\n\nView @{"MODiFYAbLE tOOltYPES" link "Document_4" 0}\n\n@endnode\n\n@node	"Document_4" "MODiFYAbLE tOOltYPES"\n\nSTYLES=<#> : Here you have to write the total Numbers of your Outputstyles\n             defined in DOORS:DRE/DRE!WALL/dRE!WAll.StYlE.1 - X .\n             If you have 11 Styles the Tooltype has to be "STYLES=11".\n\nCOLORS     : This Tooltype is optional. If you set the, dRE!WAll wil work\n             in the Color Modus, if not dRE!WAll only work with 2 Colors.\n\nANONYMOUS=<#> : Here you can specify the Level from wich on a User is able\n                to write Anonym. If you set "ANONYMOUS=200" all User with\n                Level 200 or higher are able to write Anonym.\n                \nHope this wil explain the TOOLTYPES.\n\n@endnode\n\n@node "Document_5" "CREditS"\n\n                           Credits im Überblick\n                           --------------------\n\n      dRE!WAll v2.0 was written by : dR.dRE! Of (tRSi /X·iNNOVAtiON)\n\n    tHE iNStAllER SCRiPt ARE WRittEN bY dR.dRE! Of (tRSi /X·iNNOVAtiON)\n\n    tHE AMiGAGUidEFilES ARE WRittEN bY dR.dRE! Of (tRSi /X·iNNOVAtiON)\n\n             tHE AMiGAGUidEfilE WAS CREAtEd WitH HEddlEY v1.1\n                          (c) bY Edd dUMBill 1994\n\n                  AMiGA APPliCAtiON iNStAllAtiON UtilitY\n                               VERSiON 1.24\n                COPYRiGHt ©1990-1992 COMMODORE-AMiGA, iNC.\n                           All RiGHtS RESERVEd.\n                         dESIGNED ANd dEVElOPEd bY\n                           SYlVAN tECHNiCAl ARtS\n\n@endnode\n\n@node "Document_6" "GREEtiNGS"\n\n                     Greetings to the following dudes:\n                     ---------------------------------\n\nbYTEANdi/tRSi  - Get on Work and kick Ass with your Newfiles...\nSiEGEl/tRSi    - Of coz very cool Weekend heuehe letz do it again very soon.\nSPY/tRSi       - See you in Ferbruar in Berlin.\nDEltA-X/tRSi   - Welcome and stop cracking my Doors ! heuheue!\nMClOUd/tRSi    - Long Time ago we`ve see us ... how about a Meeting\nMARiO/tRSi     - Pardy on! in Denmark ?\nECS/tRSi       - see above\nZOU^ZOU/tRSi   - uehue komm ich nicht drüber wech uehue u know!\nSAL-ONE/tRSi   - Hey, your BBS is still running ? I have to call ya.\nVAMPiRE/tRSi   - Thnx for some Betatesting and the Dissy huehe\n\n            ANd tO All MY REGiStEREd USERS ANd All i fORGOt ...\n\n@endnode\n\n@node "Document_7" "(tRSi /X·iNNOVAtiON)"\n\n                        @{fg fill}(@{fg highlight}tRSi /X·iNNOVAtiON@{fg fill})@{fg text} ARE:\n                        @{fg fill}-------------------------@{fg text}\n\n                               @{fg highlight}dR.dRE!/tRSi\n                               @{fg fill}bYtEANdi/tRSi\n                                @{fg text}SiEGEl/tRSi\n                                 @{fg highlight}SPY/tRSi\n                               @{fg fill}dELtA-X/tRSi@{fg text}\n\n   If you wanna join us, so get in touch with any of the Dudes above...\n\n@endnode\n\n@node "Document_8" "REGiStER dRE!tOOlS"\n\n                            REGISTER DRE!DOORS\n                          - ------------------ -\n\nTHE REGISTRATION FEE IS 2O$ ONLY. IF YOU THINK PHEW! QUITE A LOT OF MONEY,\n                  READ WHAT YOU WILL GET FOR YOUR MONEY.\n\n1. YOU CAN BE SURE THAT YOU`LL GET ONLY DOORS WITHOUT ANY BACKDOOR !!!\n   OF COURSE THE REGISTERED USER(S) WILL GET ONLY PRIVATE VERSIONS \n   ALL PUBLIC VERSIONS HAVE A TIMELIMIT OR I REMOVED SOME MENU OPTIONS\n             ONLY !!! THE REG.USERS WILL GET THE FULL VERSION.\n2. YOU FOUND A BUG ? -> REPORT IT TO ME AND YOU`LL GET A FIXED VERSION SOON \n   NO NEED TO WAIT FOR A LATER RELEASE VERSION.\n3. YOU HAVE SOME GOOD IMPROVEMENTS, TALK TO ME, AND I WILL SEE IF I CAN\n   REALISE IT.\n4. YOU NEED A PRIVATE DOOR ONLY FOR YOUR BBS, I WILL CODE IT !\n5. PRIVATE SUPPORT CONFERENCE IN A FUCKEN FAST TRSI BOARD IN NETHERLAND.\n   NEW DISTRIBUTION SITE IN GERMANY ALSO AVAILABLE.\n6. ALL DOORS/UTILS ARE INCLUDING YOUR REGISTER STRING.\n7. UNTIL NOW ALL DOORS ARE WITH COMMODORE INSTALLER SUPPORT, NO HARD\n   INSTALL ANYMORE !!!\n8. YOU`LL GET ALL LATER VERSIONS OR NEW DOORS FOR THE ABOVE PRICE.\n                  SIMPLY YOU`LL GET THE BEST SUPPORT AROUND.\n              THINK ABOUT AND KEEP THE PROGRAMMERS PROGRAMMING !!!\nIF YOU ARE INTERESTED  CONTACT ME AT ANY TRSI BOARD OR SIMPLY AT THE\n                 tRSi GHQ`S tHE HiDDEN OR SPiRitS Of SOUl\n\n@{fg highlight}OR SEND YOUR MONEY TO THIS ADRESS: B. HOFFMANN\n                                   KAPITELSTRASSE 1\n                                   41460 NEUSS\n                                   GERMANY@{fg text}\n\nSOON AS THE MONEY IS HERE YOUL GET THE FULL PACKAGE OF ALL MY DOORS AND\nTOOLS...\n\nNOTE: I`m no longer Part of the illegal section so i have nothing to hide,\n      so the Cops can do nothing with my Adress, and in addition i already\n      was busted in the begining of this Year.\n\n@endnode\n\n@node "Document_9" "OthER dRE! tOOlS/dOORS"\n\n       All OtHER AlREAdY RElEASES Of dR.dRE! Of (tRSi /X·iNNOVAtiON)\n       -------------------------------------------------------------\n\n NAME                  TYPE   VERSION\n---------------------+------+--------------------------------------------- \nDRE!WHO              | XiM  |  V1.1  PUBLIC \nDRE!FRONT            | XiM  |  V1.O  PUBLIC \nCHAT!ACCESS          | XiM  |  v1.2  PUBLIC \nONLY DOORMENU        | XiM  |  v1.o  PUBLIC \nSPEEDZIP (ZIP)       | DOS  |  v1.o  BETA \nBULL!VIEW            | XiM  |  v1.02 PUPLIC \nLAST!JUNKZ           | AiM  |  v1.0  PRIVATE RELEASE FOR REG. USERS ONLY \nPWFAILURE            | XiM  |  v1.1  PUPLIC \nBETA!REPORT          | XiM  |  v0.92 BETATESTER(S) ONLY\nDRE!NODECHECK        | XiM  |  c0.ß  PUBLIC \nDRE!SENDLIST         | XiM  |  v1.2  PUBLIC \nNUP^SYSPW COMMENTER  | XiM  |  v1.2  PUBLIC \nNEWUSER SCRIPT       | XiM  |  v1.21 PUBLIC\nGLOBAL USER STATUS   | XiM  |  v1.9  PUBLIC \nSPEEDLIST (USERLIST) | XiM  |  v1.ß  PRIVATE RELEASE FOR REG. USERS ONLY\nDESCRIPTION!SNAP     | AiM  |  v1.o  PUPLIC \nFAST!DUPE            | XiM  |  v1.11 PRIVATE COOP DR.DRE!^BYTEANDI\nMOST WANTED          | XiM  |  v1.52 PRiVATE RELEASE FOR REG. USERS ONLY \ndRE!Add (tXt AddER)  | DOS  |  v2.0  PRIVATE RELEASE FOR REG. USERS ONLY \ndRE!CHECk            | DOS  |  v2.3  PRIVATE RELEASE FOR REG. USERS ONLY\ndRE!CARD             | XiM  |  v2.1  BETA (PRIVATE^PUBLIC VERSION SOON)\nDRE!ADVERTISE        | XiM  |  v2.o  PRIVATE RELEASE FOR REG. USERS ONLY \nDRE!SENt             | XiM  |  v0.7  PRIVATE RELEASE FOR REG. USERS ONLY\nDRE!FREE             | XiM  |  v0.3  PRIVATE RELEASE FOR REG. USERS ONLY\nDRE!CHECK            | DOS  |  v2.2  PRIVATE RELEASE FOR REG. USERS ONLY\nDRE!REPORT           | XiM  |  v1.21 PRIVATE & PUBLIC PROTECTED RELEASE\nDRE!COMMENT          | XiM  |  V2.1  PUBLIC & PRiVATE RELEASE FOR REG. USERS\nDRE!WALL             | XiM  |  v2.0  PRiVATE RELEASE FOR REG. USERS ONLY \n---------------------+------+---------------------------------------------\n\nTHERE ARE ALSO SOME OLDER (AiM) DOORS AVAILABLE WICH I CAN`T REMEMBER WHAT\n               IT WAS  EXACTLY ...  JUST SEARCH FOR DR.DRE! \nIF YOU LIKE MY DOORS/UTILS THEN @{"REGISTER" link "Document_9" 0} IT PLEASE.\n                 !!! KEEP THE PROGRAMMERS PROGRAMMING !!!\n\n@endnode\n','\n',char(10)),NULL,'auto-added',32610,8,0,NULL,NULL,'trsi_dw2','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_f20','TRSI-F20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-F20.LHA','FileId','XIM','DMSDescript',NULL,NULL,'TRSI','\___   _______    ¼\/   ___________/ TRiSTaR /     |    /    _/\____   ¼\     |  ReD /      | /X \    \     V     \    | SeCToR',replace('___________________  _______________ _______\n\___   _______    ¼\/   ___________/ TRiSTaR\n  /     |    /    _/\____   ¼\     |  ReD  \n /      | /X \    \     V     \    | SeCToR\n \_____ |____|\____\__________/____|_______\n  \   /_____.__/  /  ______  \/    \___ \__\\n  / .   /  / _/ __/ ___/     /  /  /  / /  /\n /_____/__   /__/_____/__/__/__/__/____/__/\n    ________/the real (tRSi/X-iNNOVATiON) \n                   PRESENTS       \n      FileId V2.0 for /X3.+ and /X 4.+\n','\n',char(10)),'FileID.guide',replace('@database FileID V2.0 unregistered Version by ByteAndi/tRSi\n\n@Remark $VER: English Guide for FileID V2.00 Unregistered (01-14-95)\n@author SieGeL/tRSi\n\n@INDEX Main\n\n@node Main "FileID V2.00 Unregistered Version"\n@toc Main\n\n@{b}         __________   ________     __________ ______                     \n      ___\\__      /___\\__     \\ ___\\__      //_____/   @{ub}   ByteAndi/tRSi@{b}\n____ /     /_____//     /     //     /_____/______ __________________________\n     \\_    \\_    /     /     /_\\____     \\ /     /                      \n sYz  /     /   /   __/   __//     /     //     /    @{ub}(/X-iNNOVATiON) 1995@{b}\n____ /     /__ /    \\     \\ /    _/     //     /_____________________________\n    /_____/   /_____/_____//___________//_____/    \n@{ub}                                                  iS pROUD tO pRESENT :\n\n                         FileID V2.00 Unregistered\n\n                         CONTENTS OF DOCUMENTATION\n\n                       @{"New Features of FileID V2.00" LINK FEATURES}\n                       @{"Installation a. Requirements" LINK INSTALLATION}\n                       @{"         All ToolTypes      " LINK TOOLTYPES}\n                       @{"How to register FileID V2.00" LINK REGISTER}\n                       @{"   The famous Greetings :)  " LINK GREETS}\n\n         Another High Quality Production comin'' from (tRSi/X-iNNOVATiON)\n\n@endnode\n\n@node FEATURES "Overview of all new Features included in FileID V2.00"\n\n@{u}Short Overview of all new Features@{uu}\n\n- Users are able to choose, if FileID should ''drop'' the user after he has\n  completed his upload, so he don''t have to wait before all files are \n  checked.\n\n- FileID V2.00 is able to stay resident in memory (only in the Registered \n  Version!)\n\n- The Size of the Descriptions is now selectable via @{"ToolTypes" LINK TOOLTYPES}\n\n- FileID now uses a Brainfile which allows to remember some strange Descr.\n  containing lame adverts or other shit. With this option, FileID is able\n  to cut such shit out of the Descriptions.\n\n- As second feature, FileID is able to cut ANSI- and CTRL-Codes out of the\n  description and replace them with Spaces, so your File-Listing won''t be\n  destroyed with such nasty chars.\n\n- FileID now uses the FileID.library V2++ written by Bloodrock/SDC to \n  determine the Filetyp, and therefor it''s now impossible to confuse FileID\n  with Files which have not the right extension (i.e. DMS-Archive with .LHA)\n\n- Is able to manage two different Sent-By Lines, maybe different ones for \n  each conference, if the desired ToolType is set.\n\n- New packers could be added simply by specifying the new ToolTypes for\n  the new packer.\n\n- From now on, FileID is able to check the FileName for a Group-Synonym,\n  i.e. the Filename is ''TRSI_SD1.LHA'' or ''TRSI-SD1.LHA'', and no File_ID.DIZ\n  is included in the archive, FileID looks in a special Directory for the\n  TRSI-Logos and if found, shows them to the user to allow him to choose\n  a group-logo for the uploaded file.\n  \n- FileID V2.00 is able to switch off his Outputs, so you got a faster \n  checking.\n\n- The Autosent Program is now integrated in FileID, so you have only one\n  Program for both functions.\n\n...if you want to install it now (highly recommended ! :), take a look to\nthe chapter @{"Installation" LINK INSTALLATION} before using FileID !\n@endnode\n\n@node INSTALLATION "Installation & Requirements needed for FileID"\n\n@{u}Requirements@{uu}\n\n- A500-A4000T with Kickstart V2.++ and a full installed Amiex V3/4++\n\n@{u}NOTE:@{uu} If you are upgrading from a previous version of FileID V2.00, please\n      make sure that you delete everything created by the old FileID, \n      including the Sent.Dats !!!! If you don''t do this, you may become\n      Problems using FileID!!!\n\n@{u}The Installation of FileID V2.00 to your BBS@{uu}\n\n@{b}1.@{ub} Copy the hole FileID/ drawer to your DOORS: drawer. This drawer also\n   include the Logos drawer for the File-Description-Grouplogos. Make sure\n   that you copy FileID only in this Drawer, otherwise FileID V2.00 won''t\n   work !!!!!\n\n@{b}2.@{ub} Copy the Icons Stupid.info, Sent.info and U.info to your BBSCMD-drawer.\n\nThe icons have the following functions:\n\n@{u}Stupid.info@{uu}: This is the ''Brain-File'' of FileID. Enter Stupid in the Amiex,\n             and define the Lines FileID should strip out of descriptions,\n             i.e.: you define as Line : Uploaded\n             and FileID founds : Uploaded by Godfather of Soul, than this\n             Line will be stripped out of the Description.\n\n@{u}Sent.info@{uu}  : With this command the users could define their own Sentby-Lines.\n             Two different methods of using the Sentby-Line are included and\n             switchable via ToolTypes.\n             After entering your private sentbyline, FileID gives you the\n             ability to center your Sentby-Line.\n\n@{u}U.info@{uu}     : This Command works similar to the old method of starting FileID\n             before Uploading. In previous Versions, you have to start\n             FileID with a MCI-Command in your UPLOADMSG.TXT to ask the user\n             if he wants to use FileID for the descriptions. Now, if a user\n             enters U, he will be asked if he wants to use FileID. No need\n             of MCI-Commands anymore. Of course you don''t have to use this\n             option, it''s just another Feature...:)\n\n@{b}3.@{ub} Now copy the Icon Examine.info to your SYSCMD-Drawer. If you already have\n   an Examine-Tool installed, simply count them up in logical order, meaning\n   Examine.info (Dupecheck), Examine1.info (FileID) etc.\n\n   @{u}NOTE:@{uu} This Function is only available from Amiex V4.++ !!!!\n\n   If you using an older Version of amiex which don''t allow to have more \n   than one Examine.Info, kick it out and use FileID instead!\n\nThat''s all for installation....for an complete overview of all ToolType-\nInformations take a look to the Chapter @{"ToolTypes" LINK TOOLTYPES}.\n@endnode\n\n@node TOOLTYPES "All ToolType-Definitions for FileID V2.00"\n\n@{u}All Tooltypes used by FileID V2.00@{uu}\n\nNODE_SENT             - With this Tooltype you define a Sentby-Line which\n                        includes the Nodenummer and the Time the file was \n                        uploaded. Between the Nodenr and the Time the User\n                        could insert his own handle. The Sentby-Line has the\n                        following format:\n\n                           [NODE 11] xxxxxxxxxxxxxxxxxxxxxx [20:21:23]\n\n                        This Sentby-Line is colored until you set the Tool-\n                        type NO_ANSI.\n\nAUTOSENT              - This is the standard Sentby-Line. Here you could all\n                        44 chars for your private Sentby. If a user has no\n                        defined Sentby-Line, a default Line will be used, \n                        which is also colored. The Color could be disabled\n                        by setting the ToolType NO_ANSI.\n\nSENT_PER_CONF         - If this ToolType is set, all users could have \n                        different Sentby-Lines for each conference.\n\nDEFAULT_SENT=<string> - Here you could define an alternate Default-Sentby-\n                        Line which will used by Users, which hasn''t define\n                        their private Sentbyline. Make sure that you only\n                        enter max. 14 Chars for this Tooltype, all chars\n                        over 14 will be cutted ! \n\nNO_ANSI               - Set this ToolType if you want no Colors used.\n\nNO_OUTPUT             - This Option disables the normal Output of FileID.\n                        If set, the user only see that FileID is searching\n                        for an description.\n\nSHOW_LOGOS            - When set, this Option let FileID first check out the\n                        Filename for a known Prefix, and if found, displays\n                        the related Group-Logo(s), i.e. if the filename is\n                        TRSI-BK.LHA, FileID search for TRSI -Logos in\n                        DOORS:FILEID/LOGOS/ ...\n\nDESCRIPTION_ONLY      - If a user chooses Logoff after Upload, and the ul''ed\n                        Files have no FileDescriptions, this Files will be\n                        normally moved to FileListing with a Filedescription\n                        called: UPLOAD WITHOUT FILEID\n\n                        But if you want to have only files online, which\n                        have a FileDescription, set this ToolType and if a\n                        file without Filedescription will be uploaded, this\n                        File will be moved to the Partupload-Directory and\n                        displayed to the user at his next Login !\n\nDEF_TAGLINE=<string>  - if you are bothered of my poor english :), here you\n                        could enter a new Top text, which will be displayed\n                        before showing the File-Description..if you don''t\n                        specify this ToolType, the default String will be \n                        displayed (Don''t write your Tagline here....)\n\nTIME_TO_ASK_ID=<x>    - This Tooltype specifies the Time FileID will wait\n                        before automatically using the found description.\n                        This value is in seconds. If you don''t specify this\n                        option, FileID won''t ask the user and use the \n                        description in every case.\n                        NOTE: This Tooltype overrides the NO_OUTPUT Option,\n                        meaning if you have this Tooltype set, FileID WILL\n                        display his full output!!! \n\nTIME_TO_ASK_SENT=<x>  - This Tooltype specifies the Time FileID will wait\n                        before automatically using the SentBy-Line. This\n                        value is in seconds. If you don''t specify this \n                        option, FileID don''t ask for using the Sentby-Line.\n                        If you specify the ToolType ''NODESENT'', this option\n                        takes no effect !\n                        If you have NO_OUTPUT specified and this Tooltype\n                        set, too, the NO_OUTPUT-Option will be disabled !\n\n\nTXT_TYPE=TXT/DOC...   - Here you could define different Textfile-Extensions.\n                        In the actual Version, FileID.Library is unable to\n                        identify different Text-formats like ANSI,ASCII etc.\n                        To let FileID work correct with those files, specify\n                        here the extensions of the Textfiles (.ans, .nfo),\n                        and FileID takes the settings from the ToolTypes \n                        after identifying the File as Text-File.\n\n\n     @{"For the packer-related Tooltypes press Play on tape please..:)" LINK TOOLTYPES2}\n@endnode\n\n@node TOOLTYPES2 "All packer-related ToolTypes"\n\n@{u}ToolTypes for the Packer-Support@{uu}\n\nTo support the different Packer-/fileformats, there exists some Tooltypes,\nwhich define how FileID should handle those files...the tooltypes have the\nfollowing Format:\n\nLHA_ADD=C:LHA a %P %WFILE_ID.DIZ  <-> For adding an File_ID.DIZ\n\nLHA_EX=C:LHA e %P FILE_ID.DIZ %W  <-> For extracting FILE_ID.DIZ\n\nThe ''%'' commands have the following Meaning:\n\n%F = The FileName\n%P = Path for the Playpen and Filename\n%W = Path for the Workdir\n\nFor every (currently) supported Packer, FileID looks for the following\nToolTypes:\n\n                  @{u}PACKER@{uu}                     @{u}TOOLTYPES@{uu}\n\n                   DMS                    DMS_ADD / DMS_EX\n                   ARJ                    ARJ_ADD / ARJ_EX\n                 UNKNOWNEXE               EXE_ADD / EXE_EX\n                  EXELINK                 EXE_ADD / EXE_EX\n                   ZOO                    ZOO_ADD / ZOO_EX\n                   ZIP                    ZIP_ADD / ZIP_EX\n                   ZOOM                  ZOOM_ADD / ZOOM_EX\n                   LHWARP              LHWARP_ADD / LHWARP_EX\n                 GIFPICTURE               GIF_ADD / GIF_EX\n                   LHASFX                 LHA_ADD / LHA_EX\n                   LHA                    LHA_ADD / LHA_EX\n                   WARP                  WARP_ADD / WARP_EX\n                   ARC                    ARC_ADD / ARC_EX\n                  SHRINK                  SHR_ADD / SHR_EX\n                   TXT                    TXT_ADD / TXT_EX\n\nThis Packertypes will be recognized automatically by FileID. If maybe in the\nFuture comes new Packers which couldn''t be handled by FileID, you always \nhave the possibility to add those filetypes by using the Tooltypes. The only\nchanging is that you have to add the word ''EXTERN_'' before the File-\nextension, i.e.\n\nThe filename is "FIleID.ojx", than you have to enter the following tooltypes\nto allow FileID to handle this filetype correct:\n\n                  EXTERN_OJX_EX=C:OJX e %P FILE_ID.DIZ %W\n                 EXTERN_OJX_ADD=C:OJX a %P FILE_ID.DIZ %W\n\nHope you understand how to install new packers....:)\n@endnode\n\n@node REGISTER "HOW TO REGISTER"\n       ____                                                                  \n    ___\\  /______________________________________________________________    \n   /   \\\//                                                              \\   \n  /     \\/ -[ THe BeST eQUiPPeD PuBLIC DoMAIN BoaRD IN BeRLIN ]-          \\  \n /   -[ WiTH 4 GReaT U.S.ROBOTICS V.FAST CLASS MoDeMS WiTH FLaSH-RoMS ]-  \\ \n/                                                                           \\\n\\                        -- -[ SYNDIC/\\TE WHQ ]- --                         /\n \\   _____  _____    _____   _____  __      ___ __  _____   ___ _____      / \n  \\ /  _  \\/  _  \\  /  _  \\ /  _  \\/  |___ /   |  \\/   __)_/ __|   __)_   /  \n   /   |   \\  _   \\/   |  //   _   \\  |   \\\\_____  \\___    \\¯  |___    \\ /   \n  /   _____/  |    \\_ __   \\_  |    \\ |    \\   |    \\|      \\  | |      \\    \n  \\____| \\____|    /___|    /__|    /___   / _______/___    /__|____    /    \n      \\       l___/    l___/   l___/  \\___/___/  [ViC!]\\___/       \\___/     \n       \\                                                             /       \n        \\SYSTeM CHieFS: SPY/TRSi,ARTHuR DeNT,PHaNToM,Cat,JTC,big-rat/        \n         \\                                                         /         \n          \\   1: +49(0) 30 721 6071 USR DuAL STaNDaRD V.34 28.8   /          \n           \\  2: +49(0) 30 721 6072 USR DuAL STaNDaRD V.34 28.8  /           \n            \\ 3: +49(0) 30 721 6073 USR DuAL STaNDaRD V.34 28.8 /            \n             \\4: +49(0) 30 722 6065 USR DuAL STaNDaRD V.34 28.8/             \n              \\                                   /\\          /              \n               \\_________________________________//\\\\________/               \n                                                 /__\\\n\n                           SUPPORTS ONLY PD-/SHAREWARE !\n\n                          @{"tRSi (/X-iNNOVATiON) MEMBAS" LINK TRSI}\n@endnode\n\n@node GREETS "LAST BUT NOT LEAST : DA GREETINGS......"\n\n@{u}Da famous Greetings@{uu}\n\nSieGeL/tRSi    - 101 :) (best Member in Town)\n~~~~~~~~~~~\nSpy/tRSi       - Haste tolle U-Bahnfahrt gehabt ???\n\nCindy          - Wie war der Zug ?? ;)\n\nDX/tRSi        - Willkommen im Club...\n\nByteAndi/tRSi  - Man ... deine Tools sind einfach geil !\n\ndEATH aNGEL    - SieGeL sacht ich muss...:)\n\n                and of coz to my Beta-Testers\n\n           Generation, Zoldan and Speedlocke...always remember :\n\n\n             ...testing is a honour, making Logos a must ! \n@endnode\n\n\n@node TRSI "ALL MEMBERS FROM (TRSI /X-INNOVATION)"\n\n                   ._________________  ______\n                   l___       /      \\/    _/_______.:  \n                     /       /   /  _/\\___      /    :\n                    /_______/-rS!\\_____\\  _____/     |''95  \n                          /_______|     \\/   /_______|\n                       (/X-iNNOVATiON) Members are:\n                    ----------------------------------\n                       Dr.Dre!/tRSi (/X-iNNOVATiON)\n                       ByteAndi/tRSi (/X-iNNOVATiON)\n                        SieGeL/tRSi (/X-iNNOVATiON)\n                         Spy/tRSi (/X-iNNOVATiON)\n                       Delta-X/tRSi (/X-iNNOVATiON)\n                    ----------------------------------\n \n                           UND IMMER DARAN DENKEN:\n\n    NUR WO (/X-INNOVATION) DRAUF STEHT, IST AUCH (/X-INNOVATION) DRINNE !\n@endnode\n','\n',char(10)),'{"TYPE":"TXT/DOC..."}','auto-added',127794,6,1,'SENT','Doors/FILEID','trsi_f20','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_fg9','TRSI-FG9.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-FG9.LHA',NULL,'XIM','.   : _ __ _____   _____',NULL,NULL,'TRSI','_j   :_ .    _  ¬\ /  _ ¬\__    ·tRIStAr· \.   ./_:_ _:/  _/ \   \\/\/       ·&· j   l   / \/ ! \__/\   \¯¯¯) ·rEd^sEctøR!·',replace('  .   : _ __ _____   _____                  \n _j   :_ .    _  ¬\ /  _ ¬\__    ·tRIStAr·  \n \.   ./_:_ _:/  _/ \   \\/\/       ·&·     \n  j   l   / \/ ! \__/\   \¯¯¯) ·rEd^sEctøR!·\n  \      /   \_·   //Y   / . |              \n   \____/l___j \  /_____/l_: :   ·pReSenT·  \n<---------------\/ctx!-----| :------------->\n:     FronT GuarD v0.9     \_/ /X-SiX DooR :\n: nIcE fRoNt dOoR fOr 10 nOdEs^-^XiM/ASM!! :\n: tImE/dAtE/sYsOp sTaTuS^-^sYsTeMpAsS aVaIl:\n: fUll cOnFiGuRaBlE^-^aUtO nOdE sCaN eTc.! :\n`------------------------------------------''\n','\n',char(10)),'FrontGuard.Doc',replace('\n --[·»«·-[·tRISTAr & rEd^sECTOr iNc.·]-·»«·]::[·»»««·-[---------------------\n\n   .  .           .          .                  .           .      .     .\n   :   ______/\___:______/\_____________ /\_________/\______:_/\__ :   * .\n   .   \________________/  \_______    //  \_____________________/   .   :\n   :  :   _/      .   _/     .   | \  /\__ ______      \_   .    \_    .\n      .  \\`      :   \`     :   |  \/  //      |      ''/   :    ''// : . :\n   *  .   \\  _________\  _______|____ //____________  /_______  //\n      .  . \\/____:_____\/___.________\/________.____\/_____:__\// CONtR0L\n   .  .  .  \/    :     \/   :        \/   :    :    \/     :  \/    .\n   .  .  .        .          .             .    .           .      . .   .\n\n --[·»«·-[·tRISTAr & rEd^sECTOr iNc.·]-·»«·]::[·»»««·-[---------------------\n      \n<------------------------------------------------------------------        \n                                    pReSenTs\n        ------------------------------------------------------------------->\n \n                     Front Guard v0.9 coded by CøRteX/tRS¿\n                    -======================================-\n\n                      ( XiM/ASM Door for fast handle!! )\n\n. [ INTRUDUCTION: ] .\n---------------------\n\n ! Yep .... another faaaaast ASM Door is finished Yet!!!\n   There are a lots of Front Doors but this one is the BEST!!!!\n   \n * At first my Front-Door replace your SystemPassProtection!!!\n   (Remove ya old ONE from the ACP.Info >>>>> more security is given\n   becoz there are to many manipulated /X - releases)\n  \n * If any user didn´t know the Systempass he can leave the Sysop \n   a mail (use CTXComment!!!) and after thiz his CARRIER get DROPED!!!\n   (Kicked out by the BBS!)\n\n * OK...after the user entered the right Systempass, all available\n   ONLINE nodes will be shown (Node, User, Action) \n                    ..... (like the OLD good Front Doors)\n   \n   Well......what do ya mean....GREAT eh???\n\n. [ Requirements: ] . \n---------------------\n  - an  Amiga Model (500+,1200/2000/2500/3000/4000/CDTV/CD³²)\n  - the installed Version of OS\2, OS\3 or higher\n    (Soft- or Hardware Version)\n  - an 68020 proz or higher!!! (for lower proz versions call my BBS)\n  - the installed .INFO Files in the directories.\n  - AmiExpress V2.xx , v3.xx or higher.\n    or SigmaExpress v0.x\n  - Thats all folks....\n\n. [ INSTALLATION ] .\n--------------------\n   Copy the files in the archive to your directories,\n   they are :                                        \n\nfor /X v3.x or higher:\n----------------------                                                  \n   BBS:Commands/SYSCmd/FrontDoor.info\n\n   BBS:Doors/FrontGuard/FrontGuard.XiM\n   BBS:Doors/FrontGuard/FrontGuard.DOC\n   BBS:Doors/FrontGuard/FrontGuard.CFG\n   BBS:Doors/FrontGuard/FrontGuard.DTA\n   BBS:Doors/FrontGuard/FrontGuard.TXT\n   BBS:Doors/FrontGuard/FrontFail.TXT\n\n   LIBS:AEDoor.library ( © Sintax/WOT ) from 23.2.94\n\nfor S!X v0.x or higher:\n----------------------                                                  \n   add thiz line to ya cmds\n   BBS:Commands/SYS.Cmd\n\n   BBS:Doors/FrontGuard/FrontGuard.XiM\n   BBS:Doors/FrontGuard/FrontGuard.DOC\n   BBS:Doors/FrontGuard/FrontGuard.CFG\n   BBS:Doors/FrontGuard/FrontGuard.DTA\n   BBS:Doors/FrontGuard/FrontGuard.TXT\n   BBS:Doors/FrontGuard/FrontFail.TXT\n\n   LIBS:AEDoor.library ( © Sintax/WOT )\n\n\nEXAMPLE 4 THE CONFIG FILE:\n\n.[>>>>--------------Cut-here--------------<<<<].\n;FrontGuard v0.9 by CøRteX/tRSi!\n[-------------------] max. 20 chars\n#\nYES                                    ;Systempass\n3                                      ;Failpasses (0-9)\n2400                                   ;min. logon Baudrate\nyes                                    ;Logontxt & Systempass (y/n)\nyes                                    ;Connect Infoline (y/n)\nn                                      ;automatic node scan (y/n)\n*** pRiVaTe nOdE ***                   ; text for Private nodes\n0+1+2p3-4-5-6-7-8-9-                   ;+ = Node activ\n                                       ;- = Node inactiv\n                                       ;p = Node Private\n                                       ;Never cut this table!!!!!\n##\n\n.[>>>>--------------Cut-here--------------<<<<].\n\n. [ERROR MESSAGES: ] .\n----------------------\n\n  Can''t find CONFIG File!!!\n\n                       Check, if in DOORS:FrontGuard Drawer\n                       this two Configfiles exists!!\n\n                       FrontGuard.CFG\n                       FrontGuard.DTA\n\n\n. [HISTORY: ] .\n---------------\n                     V0.1    -  not released\n                     V0.2    -  Beta version (for 1 Node SystemBoards)\n                     V0.3    -  9 Nodes now available\n                     V0.4    -  BUG removed in NodeStatus\n                     V0.5    -  REAL CONNECT RATE would be show now\n                                and a BUG in Userinfo removed\n                     V0.6    -  PasswordFailCounter and AutoNodeScan\n                                included\n                     V0.7    -  NEW DEZIGN!!!  :) \n                                Node actions could be configurable in\n                                FrontGuard.DTA config file\n                     V0.8    -  New ManualTable (easier handle now)\n                                + Private nodes are available\n                             -  Bug fixed by creating PseudoNodes\n                                (Sometimes strikes if some Nodes were inactiv)\n                             -  some Routines would be optimized!!\n                    V0.9     -  SystemPass prompt is now crypted!\n                             -  Now you can turn off Systempass check\n                                and InfoLine! (look into ConfigFile!!)\n\n. [Other RELEASES] .\n--------------------\n                     Security Guide v0.4\n		     Show Doors v0.4\n                     Upload Detector v0.5\n\n. [ Thx to: ] .\n---------------\n   this BETA Testers:\n                    DjA× (HomeBoyLand)\n		    Sauzer (Ghost City)\n                    Blind Guardian (Trip 2 Nowhere)\n                    Prayer (Savage Amusement)\n                    Siegel/TRSI\n\n. [ Greetings: ] .\n------------------\n          Djax, Stage, Psycho/SIGMA7 - Tekkno - Samir/Prestige - Fanfare\n          Sauzer - PAT -  Pee Wee -  - Steve/D&R - SIGMA SEVEN - HOT KID\n                 Inspector, Poisen, IceTea/ClassiC - Calypso/GOD\n                  Metal Death, Ufo /Leprosy - Kamenski/Paradox !   \n                            - AND ALL TRSI Members -\n  \n. [ Last words: ] .\n-------------------\n\n                            TRSI /X-INNOVATION are:\n \n                   DR.DRE - BYTEANDI - SIEGEL - SPY - CORTEX\n\n               ------------------------------------------------   \n\n                for a registered version of any doors from me\n                              call +43 512 365302!!\n\n --[·»«·-[·tRISTAr & rEd^sECTOr iNc.·]-·»«·]::[·»»««·-[---------------------\n\n                       ________    /\__ /\______/\__ _____\n                       \_     ¬\  /   ¬\)      ¬\   |   ¬/\n          t   __/\__    :   :   \/  Y   \   :   /   :   /    __/\__   a\n          R   \    //   |   |    \  :    \  |  (:      (    \\    /   H\n          S   /_  _\\   |   l    /__|    /  |   \   :   \   //_  _\   q\n          i     \/     /:  _____/   l___/___l___/___j    \     \/     !\n                       \__/                         l____/\n          /\__ _/\__   _/\___    _      /\______/\__   _/\ _______      \n          )  ¬|\   ¬|  \_  ¬|   /¬| |\ /   __  ¬)  ¬| /   \\_    ¬\\n          |   | |   |__ |   |__/  ( ) \___   \_/:   |/  :  \|  -+  \\n          :   | |   | ¬\|   | ¬\   |   \ ¬\    \|   |   |   \   :   \\n          |   | :   l   \   l   \  l    \  \    \   :   l    \  |    \\n          |   | l_______/_______/_______/_______/___l________/__j    /\n          l___j              tRSI - SIG/X\A 7 AHQ          [CTX]l___/\n\n              (  ( ((  + 4 3 -  5 1 2  -  3 6 5 -  3 0 2  )) )  )\n\n                SysOp: CøRteX/tRSi            Co´s: DjaX - FelOn\n          .----------------------------------------------------------.\n          | RuNNiNg oN a1200/33Mhz - 240MB oNlIne StuFF - kEwL aNsIs |\n          |                     S!X POWER BOARD                      |\n          |      >>> aMiGa - mUzAx - /X DooRs - aSm SoUrCeS <<<      |\n          `----------------------------------------------------------''\n                               nO nUp rEqUiReD!!!\n\n--[·»«·-[·tRISTAr & rEd^sECTOr iNc.·]-·»«·]::[·»»««·-[---------------------\n\n\n\n','\n',char(10)),NULL,NULL,19328,5,0,NULL,NULL,NULL,'scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_fus','TRSI-FUS.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-FUS.LHA','rexxdoor','XIM','REXXDOOR',NULL,'[-Dr.Dre!/tRSi]','TRSI','\        ____   \/   _________/   TRiSTAR \/    \/   _  _/\____  \/    \ RED SECTOR! +-/RtX!  \   |   \_   |   \     \----------+',replace(' /\______________  _____________            \n \        ____   \/   _________/   TRiSTAR  \n  \/    \/   _  _/\____  \/    \ RED SECTOR!\n+-/RtX!  \   |   \_   |   \     \----------+\n| \  ____/___|__  /_____  / ____/  pRESENTs|\n+--\/-----------\/------\/\/---------------+\n Funny UserStatus v1.o - by [-Dr.Dre!/tRSi]\n','\n',char(10)),'Status.Guide',replace('@database User Status v1.o by [-Dr.Dre!/tRSi]\n\nCopyright (C) 1993 by [-Dr.Dre!/tRSi], Germany\nAll Rights Reserved\n\n@Remark $VER: Version v1.1 (Monday 17-Jan-94 13:32:57)\nRemark AmigaGuide DataBase for User Status v1.o by [-Dr.Dre!/tRSi]\n\n@node MAIN "User Status v1.o (Monday 17-Jan-94 13:32:57) Document for /X"\n             ____                        ___                     :\n           ._\  /________________________\_/ ____________________¦_ _\n           |  \/   __ _ _               _\_ /_      _/           |\n           |    _ _\         T.R.S.I      // \_    / \_ _     \\ |\n           | ____________________________//____________________\ |\n       ____| \        ___________      /_____        /______  /  |____\n      /\___\  \      /    .|   _/    _/\    /_______/       \/|  /___/\\n      \/___/   \  __/     ¦|   \      \_\_____     \_        ¦|  \___\/\n           |    \/ /      :|    \      /     /      /        :|  |\n           | \    /________|  _  \    /____________/|_________| _|\n           | \\         _ _  \_   \  /_ \\  _ __ _          _ _/ |\n           | \\\           \_/     \/ \_//       /__ _         \ |\n        _ _|________________\__________/ \__________________ /\ _|H2o!\n           ¦                           /\                   /__\\n is proud to present: User Status v1.o (Monday 17-Jan-94 13:32:57)\n                         @{"     Introduction      " Link no1}\n                         @{"     Requirements      " Link no2}\n                         @{"     Installation      " Link no3}\n                         @{"    Example Output     " Link no4}\n                         @{"       Creditz!        " Link no5}\n                         @{"      Greetings!       " Link no6}\n                         @{"     tRSI Boards!      " Link no7}\n@endnode\n@node no1 " Introduction"\n\nThis is a User Information with a new cool Style...\nThnx to SkIN! for using his Ascii Style...\nLook the Example Output\n\nhave phun with the door...\n[-Dr.Dre!/tRSi]\n\n@endnode\n@node no2 " Requirements"\n\nYou need an Amiga 500/1000/2000/3000 (The Sysops with an A4ooo or A12oo \nshould call my BBS to receive an uncompiled Version)\nKickstart 2.0 or higher\nAmi Express 2.xx - 3.xx (Registered)\nAn running RPStart\nrexxplsextnd.library\nRexxplslib.library\nrexxsyslib.library\nrexxsupport.library\nin your Libs: but they are included\n\nThats all...\n\n@endnode\n@node no3 " Installation"\n\nFirst copy all Libs: (If you dont have them allready) into your libs: Dir\nCopy the S.info to your BBS:Commands/bbscmd/\nand make shure you run rpstart in your Startup-Sequence.\nCopy the Status.AiM to your Doors:\nstatus.aim  37972 (The Door Original Size)\n\n@endnode\n@Node no4 " Example Output"\n                    .\n                   +|\n                   _:                                   _ __ __\n                  /\_\                               __/\\__ _ _ _ _\n   .______________\/_/ _______________\_ _           \   ¬//\n   |             /_   _\              /\             /_  _\\  __ _\n   |       Global_Informations        |              ¬ \//¯¯_ _ _\n   |                                  |                 ¬\n   | BBSName : MarleysCoffe           |\n   | Sysop : [-Dr.Dre!/tRSi]          |User Information 1.o by Dr.Dre!/tRSi!\n   | Handle : [-Dr.Dre!/tRSi]         |.___________________________________.\n   | Location : ·· de canabis klan!   ||                                   |\n   | Conference : tRSi!_              || ·User Information 1.o by Dr.Dre!· |\n   | Sysop Available : Not Available  ||                                   |\n   | Time Limit : 583369 Seconds   +------+    Transfer_Informations   _|_ |\n . | Local Time : 01/17/94 / 17:04:07 ||                                |  |\n _\/_______________ __________________|| Ratio     : Disabled · Respect ·  |\n   \               Y                   | Bytes U/L : 704680                |\n                   :                   | Files U/L : 7                     |\n                   |                   | Bytes D/L : 0                     |\n                   o   _ _ __ _        | Files D/L : 0                     |\n                   +_ _ __ __//\__     | Daily Bytes : 0                   |\n                           \\¬  ¬/     |  ___         _  __  _             |\n                _ _ _ __ __//_   \     |___:__________\ /\_\ /_____________|\n                      _ __ _¯\\/¯¯     |   :            \/_/               |\n                              ¬            +             ·\n    Note: In the BBS it lokk many many better as here in amigaguide...\n@endnode\n@Node no5 " The Creditz!"\n\n              Copyright (C) 1994 by [-Dr.Dre!/tRSi], Germany\n                            All Rights Reserved\n\n             The AmigaGuide DataBase written by [-Dr.Dre!/tRSi]\n\n    For more good Doors call my BBS under 49 (0) 2131 275756 & 275634\n               · [ · MARLEYS COFFEE SHOP - tRSi GHQ · ] ·\n\n      Thanx to Skin! for using some of your great Styles in my Doors!\n\n@endnode\n@Node no6 " Greetings"\n\n                   The Greets are going to this Dudes...\n\n ByteAndi/X-Design, Spy/X-Design, Remo/X-Design, X-Treme/TRSI, Saito/TRSI\n    Gandalf/Faith, Silver/Faith, McLoud/TRSI, Irata/TRSI, Triton/Fth\n Skylark/LSD, Nick, Metoner/TRSI, J.Walker/TRSI, Crazy/TRSI, Valshare/TRSI\n    Vicous/LSD, Richi/Flt, Steve/D&R, Amicom, -rS!, Empire/Mst, Mr.VAiN\n            APOLLO, BJoerN/Pdy, Jive/TRSi, Scope/Trsi, SkiN!\n          and simply all tRSi Member an other Doodes I forgot...\n\n@endnode\n@Node no7 " tRSi Boards Worldwide"\n\n                 To Contact me Call any of this Boards...\n           -==================================================-\n\n   Cauldron.......................German  hq............++49 Pure Elite\n   Marleys Coffee Shop............German  hq............++49 Pure Elite\n   Boondocks......................Europe  hq............+31-548-040-653\n   Final Impact...................Swedish hq............++46-54-113-486\n   Flying Spirits.................Swiss   hq............+41-217-282-524\n   Savage Amusement...............Austia  hq............+43-767-227-743\n   Zenlandia......................Finnish hq............+358-088-82-144\n\n\n           -==================================================-\n@endnode\n','\n',char(10)),NULL,'auto-added',101658,8,0,NULL,NULL,'nvx_rem5','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_gsd','TRSI_GSD.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI_GSD.LHA',NULL,'XIM','Status.x',NULL,'Dr.Dre!/TRZ','TRSI','l___       /      \/    _/_______.: /       /   /  _/\___      /    : /X /_______/-rS!\_____\  _____/   INNoVATioN',replace('._________________  ______        .\nl___       /      \/    _/_______.:\n  /       /   /  _/\___      /    : /X\n /_______/-rS!\_____\  _____/   INNoVATioN\n       /_______|     \/`94/_______|\n   Global User Status v1.9 by Dr.Dre!/TRZ\n    Revolutionary new Status Door (XiM)\n','\n',char(10)),'Status.Guide',replace('@database Global User Status v1.9 - by Dr.Dre!/TrSi (/X-iNNoVATioN)\n\nCopyright (C) 1994 by Dr.Dre!/tRSi^zENITh (/X-iNNoVATioN) Germany\nAll Rights Reserved\n\n@Remark $VER: v1.9 (Thursday 31-Mar-94 14:09:59)\nRemark AmigaGuide DataBase for Global User Status v1.9\n\n@Node MAIN "Global User Status v1.9 (Thursday 31-Mar-94 14:09:59) Document for /X"\n\n                   ._________________  ______\n                   l___       /      \/    _/_______.:  \n                     /       /   /  _/\___      /    :\n                    /_______/-rS!\_____\  _____/     |''94  \n                          /_______|     \/   /_______|\n                              (/X-iNNoVATioN)\n                           is proud to present: \n       Global User Status v1.9, XiM Module for AmiExpress 3.xx only\n\n                      @{"         Introductions         "Link Intro}\n                      @{"         Requirements          "Link Requi}\n                      @{"         Installation          "Link Insta}\n                      @{"      available Commands       "Link Comma}\n                      @{"           ToolTypes           "Link Toolt}\n                      @{"     example output(ascii)     "Link Examp}\n                      @{"            Creditz            "Link Credi}\n                      @{"     TRSI (/X-iNNoVATioN)      "Link TRSI}\n                      @{"           Greetings           "Link Greet}\n                      @{"          TRSI Boards          "Link Board}\n                      @{"             EXIT              "QUIT}\n@endnode\n@node Intro "Intoductions"\n\nGlobal User Status v1.9 is a Replacment for the Standart `S` Command\nfrom AmiExpress but it features much mor usefull options, like view\nStatus from other User, available by specified Level.\nBut see ya self....\n\n                             @{" Main Menu "Link MAIN} @{" Exit "QUIT}\n@endnode\n\n@node Requi "Requirements"\n\nAll what you need is:\n                      1. OS2.0 or higher\n                      2. AmiExpress 3.++\nand nothing else.\n\n                             @{" Main Menu "Link MAIN} @{" Exit "QUIT}\n@endnode\n\n@node Insta "Installation"\n\nAt first copy the Status.x in your Doors: or to any other Directory\nin your Doors: or wherever you want, then copy the S.Info to your \nBBS:COMMANDS/BBSCMD/ .\nEdit in the S.Info the ToolType `VIEW_LEVEL=200` about this Tooltype\nyou specify the Level for viewing other Accounts.\nFor all Users with this or a higher level it is now possible to view\naccounts from the other Users.\n\n                             @{" Main Menu "Link MAIN} @{" Exit "QUIT}\n@endnode\n\n@node Comma "available Commands"\n\nIf a User has Access to view other Accounts he will see a prompt Line\nunder the Status.\nHere he can choose between some different commands to viewing other\nUsers.\n1. Number\n~~~~~~~~~\nwith this Command he can jump directly to a specified Acount Number.\nif he enter `123` he will see the Account # 123 and so on...\n\n2. (+/-)\n~~~~~~~~\nhere he can jump one Account forward/backward\n\n3. (S)earch by Name\n~~~~~~~~~~~~~~~~~~~\nHere the User will see a short UserList and can then decide which\nAccount # he will see.\n\nI hope everybody will understand this, simply try it.\n\n                             @{" Main Menu "Link MAIN} @{" Exit "QUIT}\n@endnode\n\n@node Toolt "ToolTypes''\n\nThere is only one ToolType in the BBS:COMMANDS/BBSCMD/S.Info available.\nVIEW_LEVEL=<#>\nthis means all User with a higher or the same Level as you here specified\nare able to view accounts from other Users.\n\n                             @{" Main Menu "Link MAIN} @{" Exit "QUIT}\n@endnode\n\n@node Examp "example Output (ascii only)"\n.-------------------.--------------------------.-----------.----------------.\n| BBS-Name ........ | Coffee·Shop·#2           | Files U/L | 263            |\n| Sysop Name ...... | Dr.Dre!/tRZ              | Bytes U/L | 25533512       |\n| UserName/Handle . | Dr.Dre!/tRZ              | Files D/L | 23             |\n| Location ........ | (/X-iNNoVATioN) Leader   | Bytes D/L | 3784636        |\n| Password ........ | Encrypted                | Dailys .. | 1000000000     |\n| Phone Number .... | DISABLED                 | D/B Used  | 0              |\n| Access Level .... | 255                      | Ratio ... | Disabled       |\n| Access Area ..... | not4you                  | Ratiotype | Bytes only     |\n| Messages Posted . | 29                       | LogonNode | 2              |\n| Times Called .... | 1863                     | Node Baud | 57600          |\n| Last Logon ...... | Thu Mar 31 20:04:56 1994 | User Baud | 14400          |\n| Last Logon Baud . | 14400                    | Device .. | nullmodem.devi |\n| Highest U/L Cps . | 3895                     | D/L Cps . | 1294           |\n|-------------------^------------------.-------^-----------^----------------|\n| Local Time ......................... | Thu Mar 31 14:47:33 1994           |\n| Sysop Available .................... | The Sysop is not around...         |\n| Actual Conference .................. | Beta·Tester                        |\n|--------------------------------------^------------------------------------|\n| Displaying Account from : Dr.Dre!/tRZ                     Account #: 1    |\n|------------------------------------.--------------------------------------|\n| Lowest Account Number : 1          | Highest Account Number : 200         |\n|------------------------------------|--------------------------------------|\n|       Global User Status v1.9      | (c) by Dr.Dre!  TRSi (/X-iNNoVATioN) |\n`------------------------------------^--------------------------------------''\nEnter Account Number (S)earch by Name or (+/-) to view >:\n\n                             @{" Main Menu "Link MAIN} @{" Exit "QUIT}\n@endnode\n\n@node Credi "Creditz"\n\n                         Global User Status v1.9 \n                              was written by:\n                    Dr.Dre!/TRSI^ZenitH (/X-iNNoVATioN)\n\n                Status.x has a original Size of 15492 bytes\n\n                         The AmigaGuide DataBase \n                              was written by:\n                    Dr.Dre!/TRSI^ZenitH (/X-iNNoVATioN)\n\n               The TRSI Logo in the MAINNODE was painted by\n                             redSkin/TRSI/art\n\n\n                             @{" Main Menu "Link MAIN} @{" Exit "QUIT}\n@endnode\n\n@node TRSI "TRSI (/X-iNNoVATioN)"\n\n                   ._________________  ______\n                   l___       /      \/    _/_______.:  \n                     /       /   /  _/\___      /    :\n                    /_______/-rS!\_____\  _____/     |''94  \n                          /_______|     \/   /_______|\n                       (/X-iNNoVATioN) Members are:\n                    ----------------------------------\n                    Dr.Dre!/TRSI^ZenitH (/X-iNNoVATioN)\n                       ByteAndi/TRSI (/X-iNNoVATioN)\n                        Siegel/TRSI (/X-iNNoVATioN)\n                         Spy/TRSI (/X-iNNoVATioN)\n                    ----------------------------------\n               if you wanna join us so get in touch with : \n                   Dr.Dre!/TRSI^ZenitH or ByteAndi/TRSI\n                          in the following BBS`s \n           Marleys Coffee Shop TRSI ^ ZenitH (/X-iNNoVATioN) GHQ\n                     Diabolo TRSI (/X-iNNoVATioN) GHQ\n\n                             @{" Main Menu "Link MAIN} @{" Exit "QUIT}\n@endnode\n\n@ node Greet "Greetings"\n\n                         Greetings to this Guys...\n                         ~~~~~~~~~~~~~~~~~~~~~~~~~\n ByteAndi/TRSI - McLoud/TRSI - J.Walker/TRSI - Sal-One/TRSI - Nick - Xtreme\n   Irata/TRZ - Saito/TRZ - Siegel/TRSI - Spy/TRSI - MARIO/TRZ - RICHI/FLT\nViscous/LSD - Steve/D&R - -rS!/TRSi - Empire/Mst - Scope - BJoerN/Pdy Amicom\n        MetalbasheR! - Skylark/LSD - Samir/TRZ - Rotor/TRZ - RE/X\O\n                             and all i forgot\n\n                             to my BetaTesters\n                             ~~~~~~~~~~~~~~~~~\n      DEXter & lACOSTE! - NiCK - tRITON/PDY - DR. G/4WD - [-AmiCom-]\nMcloud/TRSi - vaLShAre/trsi - XTC! - [-s/\l-1!/tRSi^zENITh] - ByteAndi/MST\n\n         I`m still looking for BetaTesters with MultiNode Systems\n     if you like to be one of them call @{" Marleys Coffee Shop "Link Marleys}\n\n                             @{" Main Menu "Link MAIN} @{" Exit "QUIT}\n@endnode\n\n@node Board " TRSI Boards Worldwide"\n\n\n\n                 To Contact me Call any of this Boards...\n\n   biohazard......................Canadian HQ............+1-905-841-0965\n   cauldron.......................German   HQ............++49 Pure Elite\n   marleys coffee shop............German   HQ............++49 Pure Elite\n   diaboLo........................German   HQ............++49 Pure Elite\n   MayDay.........................German   HQ............++49 Pure Elite\n   boondocks......................European HQ............+31-548-040-653\n   final impact...................Swedish  HQ............++46-54-113-486\n   flying spirits.................Swiss    HQ............+41-217-282-524\n   savage amusement...............Austria  HQ............+43-767-227-743\n   zEnlandia......................Finnish  HQ............+358-088-82-144\n\n                                                     @{" Main Menu " Link main}\n@endnode\n','\n',char(10)),NULL,'auto-added',22434,7,0,NULL,NULL,'trsi_gsd','scan',1780048806);
INSERT INTO door_catalog VALUES('trsi_lck','TRSI-LCK.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-LCK.LHA','Lha`Chekko','XIM','Lha`Chekko',NULL,'Dr.Dre!/tRSI','TRSI','l___       /      \/    _/_______.: /       /   /  _/\___      /    : /_______/-rS!\_____\  _____/     |',replace('    ._________________  ______\n    l___       /      \/    _/_______.:\n      /       /   /  _/\___      /    :\n     /_______/-rS!\_____\  _____/     |\n           /_______|     \/`94/_______|\n      Lha`Chekko 1.o by Dr.Dre!/tRSI\nThis the fastest Lha Checker/Adder/Stripper\n','\n',char(10)),'Lha`Chekko.guide',replace('@database Lha`Chekko v1.o - by Dr.Dre!/TrSi\n\nCopyright (C) 1994 by Dr.Dre!/tRSi Germany\nAll Rights Reserved\n\n@Remark $VER: Version v1.o (Monday 31-Jan-94 14:13:31)\nRemark AmigaGuide DataBase for Lha`Chekko 1.o\n\n@Node MAIN "Lha`Chekko v1.o (Monday 31-Jan-94 14:13:31) Dcoument for /X"\n\n                   ._________________  ______\n                   l___       /      \/    _/_______.:  \n                     /       /   /  _/\___      /    :\n                    /_______/-rS!\_____\  _____/     |''94  \n                          /_______|     \/   /_______|\n\n  is proud to present: Lha`Chekko 1.o, fastest Lha Checker/Adder/Stripper\n\n                     @{" Introduction  "Link no1} @{"  Einleitung   "Link nr1}\n                     @{" Requirements  "Link no2} @{" Anforderung   "Link nr2}\n                     @{" Installation  "Link no3} @{" Installation  "Link nr3}\n                     @{"   Copyright   "Link no4} @{"   Copyright   "Link no4}\n                     @{"   Greetings   "Link no5} @{"    Gruesse    "Link no5}\n                     @{"          TRSI Boards          "Link no6}\n@endnode\n@node no1 " Introduction"\n\nLha`Chekko is the fastest Lha/Lzh/Lza Checker/Adder/Stripper around at\nthe moment...\nHe removes all Adverts from every Lha/Lzh/Lza archive, it is possible to \nadd so many Adverts you like...\nLha`Chekko need to strip/add/check an Lha File with 300kb and 100 Files\nin it only 5 Seconds...\n\nAlso Lha`Chekko works from the CLI/Shell...\n\nHave Phun with it...\nDr.Dre!/tRSi                                         @{" Main Menu " Link main}\n@endnode\n@node nr1 " Einleitung"\n\nLha`Chekko ist wohl der schnellste Lha/Lzh/Lza Checker/Adder/Stripper der\nim moment für AmiExpress erhaltbar ist...\nLha`Chekko removed alle Adverts die vorher in einem cfg File eingegeben \nwerden, er macht es moeglich soviele BBS Adverts zu adden wie man will.\nEr arbeitet auch aus dem CLI/Shell und braucht fuer ein 300kb mit 100 Files\netwa 5 sekunden...\n\nViel Spass damit...\nDr.Dre!/tRSi                                         @{" Main Menu " Link main}\n@endnode\n@node no2 " Requirements"\n\nU need to run Lha`Chekko successfull Any Version of AmiExpress.\nKickstart 2.o or higher...\nAn Lha1.5+ in your C: Directory\nAnd thats all...\n\n                                                     @{" Main Menu " Link main}\n\n@endnode\n@node nr2 " Anforderungen"\n\nDamit Lha`Chekko vernuenftig arbeiten kann brauchst irgendeine Version\nvon AmiExpress (2.xx-3.xx)\nKickstart 2.o oder hoeher\nLha 1.5+ in deinem C: Directory\nMehr wird nicht benoetigt...\n\n                                                     @{" Main Menu " Link main}\n\n@endnode\n@node no3 " Installation "\n\nCopy the File Lha`Chekko in your C: Directory\nCopy the Files Lha.Strip and Lha.Add in your s: Directory\nCopy the Lha.Info, Lzh.Info, Lza.Info, Run.info, Sfx.Info to your \nBBS:Fcheck/ Directory\nAfter this edit the File s:Lha.Add there write down your Adverts with the\nfull path to it...\n\n-------------Cut here---------------\ndh0:Adverts/Add1.txt\ndh1:MyAdd\nansi:Addme.now\n-------------Cut here---------------\n\nand so on, all files are addet to the Archive...\nThen edit the s:Lha.Strip File, here you can write all Files you like to\nStrip from the Archive\n\n-------------Cut here---------------\n*.TXT.DISPLAYME\n#?.TXT.DISPLAYME\n*.DISPLAYME\n#?.DISPLAYME\n-------------Cut here---------------\nand so on Wildcards allowed...\nI have a big Stripfile includet\nIf you running /X 2.xx then build the Checker in as the oldone but\n!!! NOTE !!! The checker needs NO OPTIONS !!!\nThats all..                                          @{" Main Menu " Link main}\n@endnode\n@node nr3 " Installation"\nKopirre das File Lha`Chekko in dein C: Directory\nKopiere die Files Lha.Add, Lha.Strip in dein S: Directory\nKopiere die Icons Lha.Info, Lzh.Info, Lza.Info, Run.info, Sfx.Info\nin dein bbs:fcheck/ Directory...\nDanach lade das File S:Lha.Add in einen Editor, schreibe hier jetzt deine\nAdverts rein mit dem vollen Pfad zu dem Advert.\n-------------Cut here---------------\ndh0:Adverts/Add1.txt\ndh1:MyAdd\nansi:Addme.now\n-------------Cut here---------------\njetzt werden alle File die in dem Lha.Add stehen zu jedem Archive das von\nmeinem Checker gecheckt wird zugeaddet...\nDanach editier das S:Lha.Strip File, hier kannst du alle Advert Namen ein-\ngeben die aus jedem Archive removed werden sollen...\n-------------Cut here---------------\n*.TXT.DISPLAYME\n#?.TXT.DISPLAYME\n*.DISPLAYME\n#?.DISPLAYME\n-------------Cut here---------------\nWildcards sind erlaubt...\nEin grosses Stripfile mit allen gaengigen Advert namen habe ich dem Archive\nbeigelegt...\nWenn du nur /X 2.xx installed hast dann baue den Checker so ein wie die\nanderen auch... aber beachte Lha`Chekko benoetigt KEINE CHECKEROPTIONS !!!\nAlso nur Checker=C:Lha`Chekko usw...\nDas ist alles ...                                    @{" Main Menu " Link main}\n@endnode\n@node no4 " Copyright"\n\n\n                 Lha`Chekko is written by Dr.Dre! of TRSI\n                         All Rights Reserved ©1994\n\n              The AmigaGuide DataBase written by Dr.Dre!/tRSi\n              Lha is Copyright (c) 1991,92 by Stefan Boberg.\n                   AmiEpress is written by Joseph Hodge \n\n        If you have any Problems with the Checker so contact me at\n                            @{" Marleys Coffee Shop " Link Coffee}\n\n                                                     @{" Main Menu " Link main}\n\n@endnode\n@node no5 " Greetings"\n\n                   The Greets are going to these Dudes...\n\n   ByteAndi/X-Design, Spy/X-Design, Remo/X-Design, X-Treme, Saito/TRSI\n    Gandalf/Faith, Silver/Faith, McLoud/TRSI, Irata/TRSI, Triton/Fth\n Skylark/LSD, Nick, Metoner/TRSI, J.Walker/TRSI, Crazy/TRSI, Valshare/TRSI\n    Vicous/LSD, Richi/Flt, Steve/D&R, Amicom, -rS!/TRSi, Empire/Mst, \n      Mr.VAiN, APOLLO, BJoerN/Pdy, Jive/TRSi, Scope, SkiN!,Mario/TRSI\n          and simply all tRSi Member an other Doodes I forgot...\n\n\n                                                     @{" Main Menu " Link main}\n@endnode\n@node no6 " TRSI Boards Worldwide"\n\n                 To Contact me Call any of this Boards...\n\n   obituary.......................World    HQ............+1-310-652-5688\n   biohazard......................Canadian HQ............+1-905-841-0965\n   cauldron.......................German   HQ............++49 Pure Elite\n   marlEys coffEE shop............German   HQ............++49 Pure Elite\n   MayDay.........................German   HQ............++49 Pure Elite\n   boondocks......................European HQ............+31-548-040-653\n   final impact...................Swedish  HQ............++46-54-113-486\n   flying spirits.................Swiss    HQ............+41-217-282-524\n   savage amusEmEnt...............Austria  HQ............+43-767-227-743\n   zEnlandia......................Finnish  HQ............+358-088-82-144\n\n\n                                                     @{" Main Menu " Link main}\n@endnode\n@node Coffee "Marleys Coffee Shop - TRSI german hQ"\n\n              * tRiStAR & RED sECtOR * gERmAN hEADqUARtER\n                                           _______    ._____\n      _______  ____.______  ______________/   .  /____|    /_______\n      \      \/    |      \/   _  \      /   ___/_    l   /   __  /\n       \           |      \\   /  /_    /_________l____  /\__   \/\n        \    \/____l________\  \____|______|    |_______/________\\n         \____\         /______|                       _______\n                 ____          _______________________/   .  /\n                /  __l_. _____/     __/     __/   .  /   ___/_.\n               /   |   |/     \     _/\     _/   ___/_________|\n              /________|      \\____|  \____|_________|\n                       \_______/         _____    \n                      __________________/     \__________\n Dr.Dre!/tRSi        /   __  /    /    //      \    .   /\n                    /\__   \/         /\_______/    ___/\n  J.Walker/tRSi    /________\   /____/-rS!/aRt/_____|\n                          /____/\n\n                                                     @{" Main Menu " Link main}\n@endnode\n','\n',char(10)),NULL,'auto-added',13788,2,0,NULL,NULL,'trsi_lck','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_log','TRSI-LOG.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-LOG.LHA',NULL,'XIM','._________________  ______',NULL,'Dr.Dre!/tRZ','TRSI','l___       /      \/    _/_______.: /       /   /  _/\___      /    : /_______/-rS!\_____\  _____/     |',replace('    ._________________  ______\n    l___       /      \/    _/_______.:\n      /       /   /  _/\___      /    :\n     /_______/-rS!\_____\  _____/     |\n           /_______|     \/`94/_______|\nBest Logoff Door 1.1 for /X by Dr.Dre!/tRZ\n','\n',char(10)),'Logoff.guide',replace('@database Logoff v1.1 - by Dr.Dre!/TrSi\n\nCopyright (C) 1994 by Dr.Dre!/tRSi Germany\nAll Rights Reserved\n\n@Remark $VER: Version v1.1 (WednesDay 23-Feb-94 12:09:42)\nRemark AmigaGuide DataBase for DoorMenu 1.o\n\n@Node MAIN "Logoff v1.1 (Wednesday 23-Fep-94 12:09:42) Dcoument for /X"\n\n                   ._________________  ______\n                   l___       /      \/    _/_______.:  \n                     /       /   /  _/\___      /    :\n                    /_______/-rS!\_____\  _____/     |''94  \n                          /_______|     \/   /_______|\n\n    is proud to present: Logoff Door 1.o, XiM Module for /X 2.xx - 3.xx\n\n                       English Doc     German Doc\n                     @{" Introduction  "Link no1} @{"  Einleitung   "Link nr1}\n                     @{" Requirements  "Link no2} @{" Anforderung   "Link nr2}\n                     @{" Installation  "Link no3} @{" Installation  "Link nr3}\n                     @{"   Copyright   "Link no4} @{"   Copyright   "Link no4}\n                     @{"   Greetings   "Link no5} @{"    Gruesse    "Link no5}\n                     @{"          TRSI Boards          "Link no6}\n@endnode\n@node no1 " Introduction"\n\nThis is a funny Logoff Door with some nic features...\nIf a User Logoff you BBS he can write a Message for the next User.\nIf the next User Logoff`s your BBS he can reply the last Message.\nThe next User can see last to Messages, specified, he see to what the\nLast User have replyed.\nSo you see alltime the Message and the reply to the Message, also \ndisplayed is the User Name, Logon Node and LogoffTime...\nHave Phun with it...\nDr.Dre!/tRSi                                         @{" Main Menu " Link main}\n@endnode\n@node nr1 " Einleitung"\n\nDies ist eine Logoff Door mit einigen guten neuen Sachen...\nWen ein User sich ausloggt ist es moeglich eine one Line Message fuer den\nnaechsten User zu schreiben.\nDer neachste User kann die Message weider replyen usw.\nEs werden immer 2 Messages displayed die vom vorletzten User und die vom\nletzten User der die Mail vom vorletzten replyed hat, also man kann immer\nwer worauf replayed hat.\nZusaetzlich werden displayed User Name, Logon Node und Logoff Time.\n\nViel Spass damit...\nDr.Dre!/tRSi                                         @{" Main Menu " Link main}\n@endnode\n@node no2 " Requirements"\n\nU need to run DoorMenu successfull Any Version of AmiExpress.\nKickstart 2.o or higher...\nAn assigned Env: and assigned envarc:\nAnd thats all...\n\n                                                     @{" Main Menu " Link main}\n\n@endnode\n@node nr2 " Anforderungen"\n\nDamit DoorMenu vernuenftig arbeiten kann brauchst irgendeine Version\nvon AmiExpress (2.xx-3.xx)\nKickstart 2.o oder hoeher\nEin Verzeichnis im Ram: was als Env: assigned ist und ein Verzeichnis\nwas als envarc: assigned ist...\nMehr wird nicht benoetigt...\n\n                                                     @{" Main Menu " Link main}\n\n@endnode\n@node no3 " Installation "\n\nCreate a Directory called Logoff in your Doors:\nCopy the File Logoff.x in it...\nCopy the G.Info to your BBS:Commands/BBSCmd/\nAfter them the Door is successfull installed.\n                                                     @{" Main Menu " Link main}\n@endnode\n@node nr3 " Installation"\n\nKreiert ein Directory namens Logoff in den Doors:\nKopiert das File Logoff.x nach Doors:Logoff/\nKopiert das G.Info in BBS:Commands/BBSCmd/\nDanach ist die Logoff Door fertig Installiert!\n\n                                                     @{" Main Menu " Link main}\n@endnode\n@node no4 " Copyright"\n\n\n                 Logoff 1.1 is written by Dr.Dre! of TRSI\n                         All Rights Reserved ©1994\n\n              Logoff.x has a Original Size from : 20988 bytes\n\n              The AmigaGuide DataBase written by Dr.Dre!/tRSi\n\n        If you have any Problems with the Door so contact me at\n                            @{" Marleys Coffee Shop " Link Coffee}\n\n                                                     @{" Main Menu " Link main}\n\n@endnode\n@node no5 " Greetings"\n\n                   The Greets are going to these Dudes...\n\n   ByteAndi/X-Design, Spy/X-Design, Remo/X-Design, X-Treme, Saito/TRSI\n    Fugitive/DLM, MetalbasheR!, McLoud/TRSI, Irata/TRSI, Triton/Pdy\n Skylark/LSD, Nick, Metoner/TRSI, J.Walker/TRSI, Crazy/TRSI, Valshare/TRSI\n    Vicous/LSD, Richi/Flt, Steve/D&R, Amicom, -rS!/TRSi, Empire/Mst, \n   BJoerN/Pdy, Scope, SkiN!,Mario/TRSI, TCM!/DLM, -runt/TRSI, Prayer/TRSI\n                         Samir/trz, Rotor/trz ...\n          and simply all tRSi Member an other Doodes I forgot...\n\n\n                                                     @{" Main Menu " Link main}\n@endnode\n@node no6 " TRSI Boards Worldwide"\n\n                 To Contact me Call any of this Boards...\n\n   biohazard......................Canadian HQ............+1-905-841-0965\n   cauldron.......................German   HQ............++49 Pure Elite\n   marleys coffee shop............German   HQ............++49 Pure Elite\n   MayDay.........................German   HQ............++49 Pure Elite\n   boondocks......................European HQ............+31-548-040-653\n   final impact...................Swedish  HQ............++46-54-113-486\n   flying spirits.................Swiss    HQ............+41-217-282-524\n   savage amusement...............Austria  HQ............+43-767-227-743\n   zEnlandia......................Finnish  HQ............+358-088-82-144\n\n\n                                                     @{" Main Menu " Link main}\n@endnode\n@node Coffee "Marleys Coffee Shop - TRZ german hQ"\n\n           * tRiStAR & RED sECtOR * zENITh * gERmAN hEADqUARtER\n                                           _______    ._____\n      _______  ____.______  ______________/   .  /____|    /_______\n      \      \/    |      \/   _  \      /   ___/_    l   /   __  /\n       \           |      \\   /  /_    /_________l____  /\__   \/\n        \    \/____l________\  \____|______|    |_______/________\\n         \____\         /______|                       _______\n                 ____          _______________________/   .  /\n                /  __l_. _____/     __/     __/   .  /   ___/_.\n               /   |   |/     \     _/\     _/   ___/_________|\n              /________|      \\____|  \____|_________|\n                       \_______/         _____    \n                      __________________/     \__________\n Dr.Dre!/tRSi        /   __  /    /    //      \    .   /\n                    /\__   \/         /\_______/    ___/\n  J.Walker/tRSi    /________\   /____/-rS!/aRt/_____|\n                          /____/\n\n                                                     @{" Main Menu " Link main}\n@endnode\n','\n',char(10)),NULL,NULL,18401,5,0,NULL,NULL,NULL,'scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_m12','TRSI-M12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-M12.LHA','LZX','XIM','Zip',NULL,NULL,'TRSI','\      _______  \   _______)---------------. :\__/  \|  __/  /___   \|  \ SieGeL/tRSi oF: ¦  /    \  \    \   \   \   \ /X-iNNOVATiON¦',replace('____________________________________________\n\      _______  \   _______)---------------.\n:\__/  \|  __/  /___   \|  \ SieGeL/tRSi oF:\n¦  /    \  \    \   \   \   \ /X-iNNOVATiON¦\n| /______\__\____\______/____\  PRESENTS   |\n)--mRV-------------------------------------(\n|mULTI-cHECK V1.2 - ADDER/sTRIPPER/cHECKER!|\n|                                          |\n|  sUPPORTS LZX, LHA & ZIP, aUTODETECT oF  |\n|  BBS-sYSTEM uSED (FAME aND /X) aND mANY  |\n|      oTHER fEATURES - cHECK iT oUT !     |\n`------------------------------------------''','\n',char(10)),'mULTI-cHECK.guide',replace('@database mULTI-cHECK\n@master EWORK:mULTI-cHECK/mULTI-cHECK_eng.guide\n@$VER: mULTI-cHECK.guide 1.0 (02-03-96)\n@author "SieGeL/tRSi"\n@(c) "Copyright © 1996 (tRSi/X-iNNOVATiON)"\n@wordwrap\n@index HeddleyAutoIndex\n@remark Created with Heddley v1.1 (c) Edd Dumbill 1994\n@remark Heddley Bugs Fixed with FixHeddley 1.2 (c) 1995 by David Zvekic\n\n@node "Main" "mULTI-cHECK - Archive-Checker for FAME & Amiex Systems"\n\n    @{b}:::.@{ub}       ________  _________ ____\n    @{b}::::@{ub}      |  -___ /_(____-----(____)\n    @{b}`::: ...@{ub}  `---'' `---^---------^----^\n     @{b}:::::::''@{ub}                \n    @{b}.::::''      ..@{ub}       .@{fg fill}ami express@{fg text}.       .@{b}presents in 1996@{ub}.\n   @{b}::::::.     `:::::...@{ub}                \n    @{b}`'' :::        ```:::::..@{ub}  .@{fg fill}fame@{fg text}.          .@{b}mULTI-cHECK  v1.2@{ub}.\n       @{b}`:::            ``::::@{ub}\n        @{b}`:::          ..::::''@{ub}    .@{fg fill}tempest@{fg text}.     .@{b}for /X & FAME BBS@{ub}.\n         @{b}`:::.    ..:::::''''@{ub} __ _ _ _ _ ___ _ _ ___ ___  _ ___ _ _\n          @{b}`:::::::::::''''@{ub}   (__) ` | ` | - | / | - (_ _)(_) - | ` |\n            @{b}``::::''''@{ub}       ^--^-''-^-''-^---^---^-''-''`-'' ^-^---^-''-''\n\n                          wRITTEN bY SieGeL/tRSi\n\n                         @{"COPYRIGHT & DISTRIBUTION" link "COPYRIGHT" 0}\n                         @{"INTRODUCTION & FEATURES " link "INTRODUCTION" 0}\n                         @{"INSTALLATION TO YOUR BBS" link "INSTALLATION" 0}\n                         @{"  USAGE AND PARAMETERS  " link "USAGE" 0} \n                         @{"  CREDITS & GREETINGS!  " link "CREDITZ" 0} \n\n         aNOTHER pRODUCT oF tHE "REAL" (tRSi/X-iNNOVATiON) tEAM !\n@endnode\n\n@node "COPYRIGHT" "Copyright Informations for mULTI-cHECK"\n@{b}DISTRIBUTION:@{ub}\n\n Following notice applies to product called "mULTI-cHECK" and everything \n in its original distribution archive.\n\n * Program is published by SieGeL/tRSi under concept of @{"RegisterWare" link "REGISTER" 0}.\n   No warranties are given. I take no responsibility of any possible\n   harm this product could do to your amiga system (not that it would but..).\n\n * You may NOT sell this product without permission from me.\n\n * Program must not be altered in any way.\n\n * Package must always be kept intact when spreading.\n\n * It is OK to include this on CD-ROM & disk collections and distribute\n   it through aminet and other such ftp''s and file nets.\n\n Above mentioned rules apply to mULTI-cHECK and other texts/libraries\n within the original package versions 1.2 and newer unless otherwise stated.\n@endnode\n\n@node "INTRODUCTION" "Some informations about mULTI-cHECK"\n          @{b}INTRODUCTION TO mULTI-cHECK OR WHY ANOTHER FILECHECKER ?@{ub}\n\n Well, the most important thing why I wrote this Tool is the fact that\n currently no other filechecker supports the @{"FAME-System" link "FAME" 0} (which I''m running!)\n and therefor the adding of uploader etc. was not possible...so I decided to\n write my own one, but not only for @{fg fill}LZX@{fg text} (which was the first archiver I''ve\n supported)...I don''t like many thousands of checkertools and therefor this\n mULTI-cHECKER is able to @{fg shine}check/add/strip@{fg text} from @{fg shine}LZX@{fg text}, @{fg shine}LHA@{fg text} and @{fg shine}ZIP@{fg text} archives...\n\n @{u}Other nice functions are:@{uu}\n\n - Supports @{b}LZX@{ub}, @{b}LHA@{ub} & @{b}ZIP@{ub} Archives for @{b}testing/adding/stripping@{ub}...\n\n - Full @{b}argument-driven@{ub}, no external configfile needed!\n\n - Supports @{b}FAME@{ub} & @{b}Amiex@{ub} systems (but not needed to let it work)\n\n - Is able to add @{b}Uploadername@{ub}, -@{b}location@{ub}, @{b}node@{ub}, @{b}date@{ub} & @{b}time@{ub} of upload to\n   the advert being added....\n\n - Supports @{b}stripping via external Textfile@{ub}\n\n - Very small and fast...:)\n\n If you now interested in this checker, simply take a look to the chapter\n @{"Installation" link "INSTALLATION" 0} for further informations...\n@endnode\n\n@node "INSTALLATION" "Installation to your BBS-System of mULTI-cHECK"\n                       @{b}INSTALLATION OF mULTI-cHECK@{ub}\n\n Best way to copy all neccessary files is to use the Installerscript supplied\n with the release archive...if you want to copy it by hand, follow these few\n steps:\n\n @{b}1.@{ub} Copy @{fg shine}mULTI-cHECK@{fg text} to your @{fg fill}c:@{fg text} directory or to any other directory of your\n    choice.\n\n @{b}2.@{ub} Copy the @{fg shine}documentation@{fg text} to your docs-directory or any other directory...\n\n @{b}3.@{ub} Copy the supplied sample files @{"ADVERT.TXT" link "SAMPLE_ADVERT" 0} and @{"STRIPFILE.TXT" link "SAMPLE_STRIPFILE" 0} to a\n    directory of your choice.\n\n Now you have to edit the files @{b}ADVERT.TXT@{ub} and @{b}STRIPFILE.TXT@{ub} to your needs.\n ADVERT.TXT could have some special symbols which are described @{"HERE" link "SAMPLE_ADVERT" 0}. The\n STRIPFILE.TXT should contain all filenames (!), you wish to kill from the\n archive. Please note that it''s on you to write only legal characters into\n this file, as mULTI-cHECK performs @{b}*NO*@{ub} checkings on these names !!! So\n make sure that you don''t use wildcards or other critical filenames inside\n this @{"stripfile" link "SAMPLE_STRIPFILE" 0}, otherwise it could happen that you gain only empty archives\n or other strange things...you''ve been warned!\n\n At least, you have to built in the checker to your BBS-System.\n\n\n                   @{b}--------- BBS-INSTALLATION ---------@{ub}\n\n\n@{u}AMIEX-SYSOPS:@{uu}\n\n Create three icons inside your BBS:FCHECK/ directory called\n\n                            @{fg shine}LZX.INFO@{fg text}\n                            @{fg shine}LHA.INFO@{fg text}\n                            @{fg shine}ZIP.INFO@{fg text}\n\n and edit the Tooltypes like shown below:\n\n  CHECKER = C:mULTI-cHECK\n  OPTIONS = @{"(CLICK HERE FOR OPTIONS)" link "USAGE" 0}\n    STACK = SAME\n PRIORITY = 1\n  ERROR.1 = Archive Corrupt!\n\n Repeat this steps for all three icons (or only the archive-types you want\n to use mULTI-cHECK for)...the Options are described in the @{"Parameters" link "USAGE" 0}-\n chapter, see there for further informations !\n\n Now you are ready with the installation.\n\n\n@{u}FAME-SYSOPS@{uu}:\n\n Start the System-Editor and go to FileCheckers. Now edit the @{b}LHA@{ub} & @{b}ZIP@{ub}\n configurations like shown below:\n\n  CHECKER PATH = C:mULTI-cHECK\n    STACK SIZE = 4096\n      PRIORITY = 1\n       OPTIONS = @{"(CLICK HERE FOR OPTIONS)" link "USAGE" 0}\n       ERROR 1 = Archive Corrupt!\n\n For @{b}LZX@{ub}, you have the create a new configuration with the @{fg shine}NEW@{fg text} button, enter\n LZX as extension, fill in the fields and save this configuration.\n\n Of course you have to switch the checker(s) @{b}ON@{ub} to let it work :)\n\n That''s all for installing it to @{"FAME" link "FAME" 0}, now you are ready to use it. See\n Chapter @{"Parameters" link "USAGE" 0} for further informations about the Options used by\n mULTI-cHECK.\n@endnode\n\n@node "USAGE" "How to use it and list of Parameters"\n                   @{b}LIST OF PARAMETERS USED BY mULTI-cHECK:@{ub}\n\n As mULTI-cHECK is fully commandline-driven, various parameters exists to\n control mULTI-cHECK. The command-template for mULTI-cHECK is:\n\n      @{fg shine}ADVERT/K,BBS-PATH/K,STRIPFILE/K,PACKER/K/A,TYPE/K/A,FILENAME/A@{fg text}\n\n Click @{"HERE" link "USAGE_EXAMPLES" 0} for some examples how to start mULTI-cHECK.\n\n @{u}Explanation of Parameters:@{uu}\n\n mULTI-cHECK uses standard OS 2.0++ Parms and their keywords, so please take\n a look to your AmigaDOS-Manual for further informations about the templates\n of programs etc.\n\n    @{fg shine}@{bg shadow}ADVERT/K@{fg text}@{bg back}  -  Specify here the Filename to the advert which should be\n                 added to the archive...click @{"HERE" link "SAMPLE_ADVERT" 0} for additional infos\n                 about the format of adverts used by mULTI-cHECK.\n\n                 @{b}@{fg fill}I.E.:@{ub}@{fg text} @{fg fill}ADVERT=S:MYADVERT.TXT@{fg text}\n\n                 will add @{fg fill}S:MYADVERT.TXT@{fg text} after parsing it for any special\n                 commands to the archive given as FileName.\n\n                 This Parameter is optional!\n\n  @{fg shine}@{bg shadow}BBS-PATH/K@{fg text}@{bg back}  -  If you are using mULTI-cHECK with a BBS, enter here the\n                 main path to your BBS System, i.e. @{fg fill}BBS-PATH=BBS:@{fg text} or use\n                 @{fg fill}BBS-PATH=FAME:@{fg text} . Please notice that mULTI-cHECK is able to\n                 detect itself which System you are running...if you don''t\n                 specify this Option, but using the Uploader-Name etc.\n                 features inside an advert, mULTI-cHECK will write\n                 @{b}"-+- The SysOp -+- "@{ub} and @{b}"- Local Upload -"@{ub} for the name &\n                 location fields, otherwise all needed informations where\n                 extracted from the online''s user.datas and written to your\n                 advert.\n\n                 This Parameter is optional!\n\n @{fg shine}@{bg shadow}STRIPFILE/K@{fg text}@{bg back}  -  Here you have to enter the path to a ascii-file containing\n                 all filenames you want to strip off the archive, i.e. you\n                 have a file in @{fg fill}S:@{fg text} called @{fg fill}strips@{fg text} containing:\n\n                                @{i}display.me@{ui}\n                                @{i}fuck_it.txt@{ui}\n                                @{i}werbung.txt@{ui}\n\n                 then you enter @{fg fill}STRIPFILE=S:STRIPS@{fg text} and all filenames listed\n                 inside this file where deleted from the archive. Look to\n                 the Chapter @{"Example-Stripfile" link "SAMPLE_STRIPFILE" 0} for further informations.\n\n                 @{u}NOTE:@{uu} If you are stripping from a @{fg shine}@{bg fill}ZIP-Archive@{fg text}@{bg back}, please don''t\n                       wonder about errormessages comming from ZIP, these\n                       errors are normal, as ZIP prints out all filenames,\n                       which couldn''t be found inside the archive to delete\n                       them...dunno know why this behavour exists, I can''t\n                       suppress this warnings and therefor you have to live\n                       with this :(\n\n                 This Parameter is optional!\n\n  @{fg shine}@{bg shadow}PACKER/K/A@{fg text}@{bg back}  -  Here you must enter the path to the checker you want to use.\n                 I''ve tested it with @{b}LHA V1.50@{ub}, @{b}LZX V1.20@{ub} and @{b}Zip V2.0.1@{ub} but\n                 as I only uses standard commands and therefor there should\n                 be no problems when using different versions. To specify\n                 the packer for @{fg fill}LZX@{fg text}, you could write for example:\n\n                                     @{fg fill}PACKER=C:LZX@{fg text}\n\n                 This Parameter is absolutly needed, without it mULTI-cHECK\n                 won''t work!\n\n    @{fg shine}@{bg shadow}TYPE/K/A@{fg text}@{bg back}   - Enter here the type of packer which is used...currently\n                 there exists 3 types:\n\n                                   @{fg shine}LHA LZX ZIP@{fg text}\n\n                 If you want to use @{fg fill}LHA@{fg text}, simply enter @{fg fill}TYPE=LHA@{fg text} and\n                 mULTI-cHECK uses now the @{fg fill}LHA@{fg text} routines for stripping/testing\n                 and adding...\n\n                 This Parameter is absolutly needed, without it mULTI-cHECK\n                 won''t work!\n\n  @{fg shine}@{bg shadow}FILENAME/A@{fg text}@{bg back}   - Here you specify the archive to test/add/strip. If you use\n                 mULTI-cHECK as Filechecker for your BBS, this Parameter will\n                 be filled out from the BBS, and therefor no Keyword is\n                 required to specify it (see @{"examples" link "USAGE_EXAMPLES" 0} below).\n\n                 This Parameter is absolutly needed, without it mULTI-cHECK\n                 won''t work!\n\n                @{"Click here for some examples of mULTI-cHECK" link "USAGE_EXAMPLES" 0}\n@endnode\n\n@node "USAGE_EXAMPLES" "Some examples how to use mULTI-cHECK."\n                  @{b}SOME EXAMPLES HOW TO USE mULTI-cHECK:@{ub}\n\n All examples listed here assuming that you have an advertfile called ADVERT\n found in S: and a stripfile called STRIP found in S:, too.\n\n\n@{b}1)@{ub} @{u}Simplest usage:@{uu}\n\n  mULTI-cHECK PACKER=C:LHA TYPE=LHA RAM:MYARCHIVE.LHA\n\n Will only check archive @{fg fill}RAM:MYARCHIVE.LHA@{fg text} in @{fg fill}LHA@{fg text} mode and uses @{fg fill}C:LHA@{fg text}.\n\n\n@{b}2)@{ub} @{u}With adding of an advert:@{uu}\n\n  mULTI-cHECK ADVERT=S:ADVERT PACKER=C:LZX TYPE=LZX RAM:MYARCHIVE.LZX\n\n Will check archive @{fg fill}RAM:MYARCHIVE.LZX@{fg text} in @{fg fill}LZX@{fg text} mode using @{fg fill}C:LZX@{fg text} and after the\n testing will add the @{fg fill}S:ADVERT@{fg text} file to the archive.\n\n\n@{b}3)@{ub} @{u}Stripping from an archive:@{uu}\n\n mULTI-cHECK STRIPFILE=S:STRIP PACKER=C:ZIP TYPE=ZIP RAM:MSDOS.ZIP\n\n Will check archive @{fg fill}RAM:MSDOS.ZIP@{fg text} in @{fg fill}ZIP@{fg text} mode using @{fg fill}C:ZIP@{fg text} and after testing,\n all filenames listed in @{fg fill}S:STRIP@{fg text} will be stripped off the archive.\n\n\n@{b}4)@{ub} @{u}Now an example with testing/adding/stripping for a BBS-System:@{uu}\n\n mULTI-cHECK ADVERT=S:ADVERT STRIPFILE=S:STRIP BBS-PATH=FAME: PACKER=C:ZIP\n             TYPE=ZIP RAM:MSDOS.ZIP\n\n It''s clear that you have to enter this in only one line, but the space here\n doesn''t allow it to write this example into one line. This example will\n first test @{fg fill}RAM:MSDOS.ZIP@{fg text} in @{fg fill}ZIP@{fg text} mode using @{fg fill}c:ZIP@{fg text}, then strips off all files\n contained in @{fg fill}S:STRIP@{fg text} from the archive and finally adds the advert @{fg fill}S:ADVERT@{fg text}\n to the archive, but filling out the advert first with uploader''s name, \n location etc. extracting this informations out of the BBS-Path @{fg fill}FAME:@{fg text} .\n\n I think that should be enough examples on how to use it for your needs.\n\n For an overview about the @{"StripFile" link "SAMPLE_STRIPFILE" 0} or the @{"Advert" link "SAMPLE_ADVERT" 0} format used by mULTI-cHECK\n please take a look to the according chapters.\n@endnode\n\n@node "SAMPLE_ADVERT" "An example for an Advert used by mULTI-cHECK"\n                 @{b}SPECIAL COMMANDS USED FOR THE ADVERT:@{ub}\n\n As mULTI-cHECK is able to add @{i}Uploader Name@{ui} and @{i}Location@{ui}, @{i}Node-Nr@{ui}, @{i}Date@{ui} and\n @{i}Time@{ui} of the Upload into your advert, some special commands exists to let\n mULTI-cHECK add this items. Here''s a list of a special commands, you have\n to enter them exactly the same way they are written here:\n\n@{b}1) The Uploadername:@{ub} @{fg shine}@{bg fill}-U-S-E-R-H-A-N-D-L-E-@{fg text}@{bg back}\n\n Will be replaced by the name of the Uploader. Max length is 21 chars,\n shorter names are filled with spaces, longer names are cutted. If no\n uploadername could be found, the string "@{fg fill}-+- THE SYSOP -+-@{fg text}" will be added.\n\n@{b}2) The Uploaderlocation:@{ub} @{fg shine}@{bg fill}-U-S-E-R-L-O-C-A-T-I-O-N-@{fg text}@{bg back}\n\n Will be replaced by the Location of the Uploader. Max. length is 25 chars,\n shorter names are filled with spaces, longer names are cutted. If no\n uploaderlocation could be found, the string "@{fg fill}-+- LOCAL UPLOAD -+-@{fg text}" will be\n added.\n\n@{b}3) The Nodenumber:@{ub} @{fg shine}@{bg fill}¹¹@{fg text}@{bg back}\n\n Will be replaced by the Nodenumber from where the upload was done. Max.\n length is 2 chars, the nodenumber will be right-justified written to your\n advert. If no nodenumber could be found, the string "@{fg fill}--@{fg text}" will be written\n as Nodenumber.\n\n@{b}4) Date of check:@{ub} @{fg shine}@{bg fill}@@-@@-@@@{fg text}@{bg back}\n\n Will be replaced by the date the archive was tested. The date is in the\n USA format (@{fg fill}MM-DD-YY@{fg text}) and is always been added.\n\n@{b}5) Time of check:@{ub} @{fg shine}@{bg fill}##:##:##@{fg text}@{bg back}\n\n Will be replaced by the time the archive was tested. The time is in the\n format @{fg fill}HH:MM:SS@{fg text} and is always been added.\n\n\n\n                          @{b}SAMPLE FOR AN ADVERT:@{ub}\n\n@{fg shine}--- CUT HERE ---@{fg text}\n\n        _____ __ __ _____ __ _____.--.__ ________ ___________ __\n __ _ _/  ._ \\_ |  \\_    \\__)     \\_ | _/        \\_ ___/     \\_ l_  _\n   \\ \\\\_  |/  / |  _/ |  _/\\_  l___/ | \\_  |  |  _/ _/\\_  |  _/ _/_ /_\n       |   __/  |  |  |  |  l__   |     |  |  |  |  |  |  |  |  |  |  ||\n       |  |  |  |  |  |  |  |  |  |  |  |  |  |  |  l  |  |  |  l  |  |:\n       l__|  l_____l__|  l__l__   l__|  l__|__|  l__   l__|  l__   |  ||\n          ÷2F÷        `--''     `--''  `--''     `--''  `--''  `--''  `--''\n\n           · (tRSi/X-iNNOVATiON) WHQ & bETA sITE · cONTRA! gHQ ·\n\n         · eTHIC dIST sITE · mATRIX oRDER sITE · fAME sUPPORT BBS ·\n\n                              __ _____ _____\n     A4ooo/o4o aT 4oMHZ      (__)     \\_    |\n                             | \\_  |  _/ l__|           sYSTEM-cHIEFS:\n  14mB rAM/1.6 GB HD-sPACE   |  |  |  |  |__\n                             |  |  |  |  l  |  _     SieGeL/tRSi & aRGON\n       USR v.34 28.8k        l__l__|  l__   | (_)\n                                   `--''  `--''\n\n          ! sUPPORTING pD and sHAREWARE oNLY oN aMIGA aND IBM-PC !\n\n                  cALL #0: +49(0)30 694 84 70 (v.34)\n                       #1: +49(0)30 694 85 70 (v.34)\n\n             UPLOAD DATE: @@-@@-@@  TIME: ##:##:##  ON NODE: ¹¹\n\n    UPLOADER: -U-S-E-R-H-A-N-D-L-E-  LOCATION: -U-S-E-R-L-O-C-A-T-I-O-N-\n\n@{fg shine}--- CUT HERE ---@{fg text}\n@endnode\n\n@node "SAMPLE_STRIPFILE" "An example for a Stripfile used by mULTI-cHECK"\n             @{b}EXPLANATION FOR THE STRIPFILE USED BY mULTI-cHECK:@{ub}\n\n If you want to let mULTI-cHECK automatically remove unused files from the\n archives being tested, you have to create an ASCII-file containing all file-\n names you wish to remove from the archive. mULTI-cHECK takes this file with\n the Parameter @{"STRIPFILE=<PATH_TO_FILE>" link "USAGE" 0} and removes all files from the\n archive wich matches the filenames found inside the stripfile. Please use\n this option with care, as mULTI-cHECK performs @{b}NO@{ub} checkings about the given\n filenames (i.e. Patterns, spaces between names etc.) for the use of speed.\n It''s on you to remove only @{i}LEGAL@{ui} filenames which doesn''t create problems...\n I''ll give @{b}NO@{ub} warranty about any loss data which occures while removing files\n from an archive with @{i}ILLEGAL@{ui} filenames!\n\n\n                       @{b}EXAMPLE FOR THE STRIPFILE:@{ub}\n\n This is an example how a stripfile may look like. Snap this out and save it\n under a filename of your choice. After this, enter STRIPFILE=<YOUR_NAME> as\n parameter for mULTI-cHECK, and all files where removed then.\n\n@{fg shine}--- CUT HERE ---@{fg text}\n\n display.me \n fucker.txt \n "the fastest" \n READ.ME \n "BLA BLA BLA!"\n\n@{fg shine}--- CUT HERE ---@{fg text}\n\n Don''t ask me to built in a learn function for new adverts, I won''t built-in\n such unsafe things, if you want to remove files, @{b}YOU@{ub} have to enter the\n according filenames...I don''t trust doors/checkers, which are able to \n "learn", as this produces at most cases empty archives....:|\n@endnode\n\n@node "CREDITZ" "Credits and the wellknown Greetings"\n                               @{b}THE GREETINGS:@{ub}\n\n                     @{i}SieGeL/tRSi sends his regards to:@{ui}\n\n Strider/tRSi   - Go on with FAME, you have to release it soon !\n BloodRock/tRSi - We must code together the DMS-Part for this checker ;)\n Beatnik/tRSi   - FullEd is the Power !\n Dr.Dre!/tRSi   - The tapes you''ve sended me are very nice :)\n ByteAndi/tRSi  - Don''t hear anything from you, call back mate!!!!!!!!\n Spy/tRSi       - Time to change to FAME...what do you think about it ?\n vAMPIRE/tRSi   - Hope you get everythink worked :) Waiting for the CD''s :)))\n aRGON/pDY      - Call more often, don''t here from you very much in the past\n dEATH aNGEL    - Hope your illness get''s better...best wishes!\n vENOM          - Nice to have english guys here, hope you like FAME :)\n tURBO          - The same to you, got yar in another chat :)\n sCANDIC/dCS    - FFS is the ruling name hehehe\n [oRK!]         - We talk the next days in chat, I promise!\n F. Monteilhet  - For cewl E-Mails and your nice help with translating :)\n\n\n             @{fg shine}...and of course to all my registered users and@{fg text}\n                @{fg shine}everone I''ve forgot to listen here....@{fg text}\n\n\n This is my first release in the mighty year 1996, the release year of a new\n generation of BBS-Systems:\n\n                    @{b}@{fg shine}FAME - Final Amiga MailBox Engine !@{ub}@{fg text}\n\n This checker is dedicated to this System, so go on and change/register now !\n\n   @{b}------------------------------------------------------------------------@{ub}\n\n    @{i}THE ONLY WAY TO MULTITASK ON MS-DOS IS TO RUN IBeM TWICE ON AN AMIGA !@{ui}\n@endnode\n\n@node "REGISTER" "Registration of Tools/Doors"\n@{b}REGISTER DOORS/TOOLS@{ub}\n\n All tools I''ve made in the past are released under the @{b}RegisterWare@{ub} concept.\n This means, that I release all my doors only one time as full working Public\n Versions, all updates/bugfixings are only available for registered Users.\n\n The Registration costs @{b}30.- DM@{ub} (or $20) and has to be paid only @{b}*ONE*@{ub}\n time for @{b}*ALL*@{ub} BBS-doors I have made until now. Of course all new \n doors are included in this registration fee, too.\n\n To become registered user, contact one of the following Boards and leave a\n mail to SieGeL/tRSi about Registration:\n\n @{b}pUNISHMENT iNC:@{ub} +49(0) 30 694 8470 (v.34) - fAME tEST/sUPPORT BBS!\n                 +49(0) 30 694 8570 (v.34)\n\n @{b}Paralysis:@{ub}      +49(0) 30 721 6071 (v.34)\n                 +49(0) 30 721 6072 (v.34)\n                 +49(0) 30 721 6073 (v.34)\n                 +49(0) 30 721 6065 (v.34)\n\n @{b}Spirit of Soul:@{ub} Absolute Private\n\n              @{fg shine}These Boards are supporting only 100% Public Domain.@{fg text}\n\n             You could also use @{b}E-Mail@{ub} or @{b}Compuserve@{ub} to contact me:\n\n                       E-Mail: [email removed]\n\n                   CompuServe: 101601,2654 (Sascha Pfalz)\n@endnode\n\n@node "FAME" "Informations about the FAME-System."\n\n                        @{b}Informations about FAME@{ub}\n\n FAME is at this time still under construction, but because of the fact\n that many people asked for FAME, it will be released until the end\n of february under the concept of shareware and will be available for\n everyone. At the begining not everything will be completly finished and\n because of this not everything you can already configure will work.\n The registered Versions have to work at least some days before they will\n be released for registered Users, but it''s still possible that these\n versions also make problems when using them. But as soon as you''ve\n reported those problems, they will be fixed!\n\n If some of the settings won''t work, it might be a bug but it''s also (more)\n possible that those functions are not implemented yet.\n\n Some of the internal functions are currently untested and it''s possible\n that they produce errors or problems, but please remember the complexity\n of FAME !\n\n If you have questions or problems with FAME, please turn on one of the\n FAME-Developers or ask Strider to solve your problems.\n\n\n@{b}@{u}What should FAME costs ?@{ub}@{uu}\n\n Registered Version:  110 USD / 150 DM\n Betatester Version:  145 USD / 200 DM\n\n\n@{b}@{u}What is included in the FAME-package ?@{ub}@{uu}\n\n Server, SystemEditor, MainPart, FAMEHydra.FIM, FAMEError.FIM\n\n FAME.library FAMEChat.FIM programmed by Bloodrock/tRSi\n\n FAMEFullEd.FIM, FAMEScript.FIM programmed by Beatnik/tRSi\n\n MUI UserEditor, FAMEDoorHelp.FIM, FAMEInfo programmed by SieGeL/tRSi\n\n Also some doors and tools from the FAME-Development-Team are included,\n but this doors are only unregistered Versions and have therefor some\n limitations. The registered Versions of those doors and the Informations\n how to get them are available here in the pUNISHMENT iNC. BBS.\n\n It could happen that some of the doors and tools listed here are currently\n missing because there are currently under development !\n\n\n@{b}@{u}Who creates FAME ?@{ub}@{uu}\n\n@{fg fill}Main programmer:@{fg text}\n\n - David ''Strider'' Wettig (tRSi) [email removed]\n\n@{fg fill}Additional programmer:@{fg text}\n\n - Oliver ''Bloodrock'' Lange (tRSi) [email removed]\n - Ulrich Arne ''Beatnik'' Jansen (tRSi) [email removed]\n - Sascha ''Siegel'' Pfalz (tRSi) [email removed]\n\n@{fg fill}FAME-Development-Team:@{fg text}\n\n - David ''Strider'' Wettig (tRSi) [email removed]\n - Oliver ''Bloodrock'' Lange (tRSi) [email removed]\n - Ulrich Arne ''Beatnik'' Jansen (tRSi) [email removed]\n - Sascha ''Siegel'' Pfalz (tRSi) [email removed]\n - Andreas ''ByteAndi'' Petermann (tRSi)\n - Dirk ''Spy'' Holzkampf (tRSi) [email removed]\n - Bodo ''Dr.Dre!'' Hoffmann (tRSi)\n\n\n@{b}@{u}Disclaimer:@{ub}@{uu}\n\n No warranties are given. We take no responsibility of any possible harm this\n product could do to your AMIGA system (not that it would but..).\n We give also no warranties to any dokuments or doors/tools included with\n FAME.\n You use FAME and all FAME related files at your own risk !\n\n Of course we take no responsibility when someone is using FAME for illegal\n terms.\n @{b}------------------------------------------------------------------[EOF]-----@{ub}\n@endnode\n\n@node HeddleyAutoIndex "Index"\n@remark Index auto-generated by Heddley\nIndex of database mULTI-cHECK\n\nDocuments\n\n@{"An example for a Stripfile used by mULTI-cHECK" link "SAMPLE_STRIPFILE"}\n@{"An example for an Advert used by mULTI-cHECK" link "SAMPLE_ADVERT"}\n@{"Copyright Informations for mULTI-cHECK" link "COPYRIGHT"}\n@{"Credits and the wellknown Greetings" link "CREDITZ"}\n@{"How to use it and list of Parameters" link "USAGE"}\n@{"Informations about the FAME-System." link "FAME"}\n@{"Installation to your BBS-System of mULTI-cHECK" link "INSTALLATION"}\n@{"mULTI-cHECK - Archive-Checker for FAME & Amiex Systems" link "Main"}\n@{"Registration of Tools/Doors" link "REGISTER"}\n@{"Some examples how to use mULTI-cHECK." link "USAGE_EXAMPLES"}\n@{"Some informations about mULTI-cHECK" link "INTRODUCTION"}\n\nButtons\n\n@{"  CREDITS & GREETINGS!  " link "CREDITZ" 0}\n@{"  USAGE AND PARAMETERS  " link "USAGE" 0}\n@{"(CLICK HERE FOR OPTIONS)" link "USAGE" 0}\n@{"Advert" link "SAMPLE_ADVERT" 0}\n@{"ADVERT.TXT" link "SAMPLE_ADVERT" 0}\n@{"Click here for some examples of mULTI-cHECK" link "USAGE_EXAMPLES" 0}\n@{"COPYRIGHT & DISTRIBUTION" link "COPYRIGHT" 0}\n@{"Example-Stripfile" link "SAMPLE_STRIPFILE" 0}\n@{"examples" link "USAGE_EXAMPLES" 0}\n@{"FAME" link "FAME" 0}\n@{"FAME-System" link "FAME" 0}\n@{"HERE" link "SAMPLE_ADVERT" 0}\n@{"HERE" link "USAGE_EXAMPLES" 0}\n@{"Installation" link "INSTALLATION" 0}\n@{"INSTALLATION TO YOUR BBS" link "INSTALLATION" 0}\n@{"INTRODUCTION & FEATURES " link "INTRODUCTION" 0}\n@{"Parameters" link "USAGE" 0}\n@{"RegisterWare" link "REGISTER" 0}\n@{"stripfile" link "SAMPLE_STRIPFILE" 0}\n@{"STRIPFILE.TXT" link "SAMPLE_STRIPFILE" 0}\n@{"STRIPFILE=<PATH_TO_FILE>" link "USAGE" 0}\n@endnode\n','\n',char(10)),'{"STACK":"SAME","PRIORITY":"1","TYPE":"LHA@{fg"}','auto-added',115596,5,0,NULL,NULL,'trsi_m12','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_m16','TRSI-M16.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-M16.LHA','LhA','XIM','LhA',NULL,NULL,'TRSI','\      _______  \   _______)---------------. :\__/  \|  __/  /___   \|  \ SieGeL/tRSi oF: ¦  /    \  \    \   \   \   \ -iNNOVATiONs ¦',replace('____________________________________________\n\      _______  \   _______)---------------.\n:\__/  \|  __/  /___   \|  \ SieGeL/tRSi oF:\n¦  /    \  \    \   \   \   \ -iNNOVATiONs ¦\n| /______\__\____\______/____\  PRESENTS   |\n)--mRV-------------------------------------(\n|mULTI-cHECK V1.6 - ADDER/sTRIPPER/cHECKER!|\n|                                          |\n|sUPPORTS LZX,LHA,ZIP & TXT, aUTODETECT oF |\n|  BBS-sYSTEM uSED (FAME & /X), aDDING oF  |\n|     bINARY dATA tO aRCHIVES eTC. !       |\n`------------------------------------------''','\n',char(10)),'mULTI-cHECK.guide',replace('@database mULTI-cHECK\n@master EWORK:mULTI-cHECK/mULTI-cHECK_eng.guide\n@$VER: mULTI-cHECK.guide 1.6 (05-09-03)\n@author "Sascha ''SieGeL/tRSi'' Pfalz"\n@(c) "Copyright © 1996-2003 by Sascha ''SieGeL/tRSi'' Pfalz"\n@wordwrap\n@index HeddleyAutoIndex\n@remark Created with Heddley v1.1 (c) Edd Dumbill 1994\n@remark Heddley Bugs Fixed with FixHeddley 1.2 (c) 1995 by David Zvekic\n\n@node "Main" "mULTI-cHECK - Archive-Checker for FAME & Amiex Systems"\n\n    @{b}:::.@{ub}       ________  _________ ____\n    @{b}::::@{ub}      |  -___ /_(____-----(____)\n    @{b}`::: ...@{ub}  `---'' `---^---------^----^\n     @{b}:::::::''@{ub}\n    @{b}.::::''      ..@{ub}             __ _ _ _ _ ___ _ _ ___ ___  _ ___ _ _\n   @{b}::::::.     `:::::...@{ub}      (__) ` | ` | - | / | - (_ _)(_) - | ` |\n    @{b}`'' :::        ```:::::..@{ub}  ^--^-''-^-''-^---^---^-''-''`-'' ^-^---^-''-''\n       @{b}`:::            ``::::@{ub}\n        @{b}`:::          ..::::''@{ub}           .@{b}presents in 2003@{ub}.\n         @{b}`:::.    ..:::::''''@{ub}\n          @{b}`:::::::::::''''@{ub}                .@{b}mULTI-cHECK  v1.6@{ub}.\n            @{b}``::::''''@{ub}\n                                       .@{b}for FAME, /X or CLI@{ub}.\n\n\n\n\n\n\n                          wRITTEN bY SieGeL/tRSi\n\n                         @{"COPYRIGHT & DISTRIBUTION" link "COPYRIGHT" 0}\n                         @{"INTRODUCTION & FEATURES " link "INTRODUCTION" 0}\n                         @{"INSTALLATION TO YOUR BBS" link "INSTALLATION" 0}\n                         @{"  USAGE AND PARAMETERS  " link "USAGE" 0}\n                         @{"  CREDITS & GREETINGS!  " link "CREDITZ" 0}\n\n@endnode\n\n@node "COPYRIGHT" "Copyright Informations for mULTI-cHECK"\n@{b}DISTRIBUTION:@{ub}\n\n Following notice applies to product called "mULTI-cHECK" and everything \n in its original distribution archive.\n\n * Program is published by Sascha ''SieGeL/tRSi'' Pfalz under concept of FREEWARE.\n   No warranties are given. I take no responsibility of any possible\n   harm this product could do to your amiga system (not that it would but..).\n\n * You may NOT sell this product without permission from me.\n\n * Program must not be altered in any way.\n\n * Package must always be kept intact when spreading.\n\n * It is OK to include this on CD-ROM & disk collections and distribute\n   it through aminet and other such ftp''s and file nets.\n\n Above mentioned rules apply to mULTI-cHECK and other texts or\n libraries within the original package versions 1.6 and newer unless\n otherwise stated.\n@endnode\n\n@node "INTRODUCTION" "Some informations about mULTI-cHECK"\n          @{b}INTRODUCTION TO mULTI-cHECK OR WHY ANOTHER FILECHECKER ?@{ub}\n\n Wow, almost 6 years have gone since I last updated this tool :) It was a little\n bit hard to get into Amiga-E again, but now the update is finished.\n\n The original statement I''ve written here in 1997 is no longer true, so I decided\n to write a new one. BBS systems are very rare in these days, but it seems to get\n back "to the roots", as many of the old-school members I know from the past days\n are visiting again BBS systems, and so does Digiman with his FAME driven BBS. He''s\n also responsible for this V1.6 update :)\n\n Hope to meet you all again on the AmigaOne Platform, which is my next aimed target!\n\n But now let''s go to the usual program docs stuff:\n\n @{u}Main features of mULTI-cHECK are:@{uu}\n\n - Supports @{b}LZX@{ub}, @{b}LHA@{ub} & @{b}ZIP@{ub} Archives for @{b}testing/adding/stripping@{ub}...\n\n - V1.3+ supports now also @{b}Textfile adding with Header/Tailer !@{ub}\n\n - Full @{b}argument-driven@{ub}, no external configfile needed!\n\n - Supports @{b}FAME@{ub} & @{b}Amiex@{ub} systems (but not needed to let it work)\n\n - Is able to add @{b}Uploadername@{ub}, -@{b}location@{ub}, @{b}node@{ub}, @{b}date@{ub} & @{b}time@{ub} of upload to\n   the advert/header/tailer being added....\n\n - Supports @{b}stripping via external Textfile@{ub}\n\n - Very small and fast...:)\n\n - V1.6+ supports now abbrevations of all arguments and a new mode called NOMODIFY\n   is also added to support binary adverts...\n\n If you now interested in this checker, simply take a look to the chapter\n @{"Installation" link "INSTALLATION" 0} for further informations...\n@endnode\n\n@node "INSTALLATION" "Installation to your BBS-System of mULTI-cHECK"\n                       @{b}INSTALLATION OF mULTI-cHECK@{ub}\n\n Best way to copy all neccessary files is to use the Installerscript supplied\n with the release archive...if you want to copy it by hand, follow these few\n steps:\n\n @{b}1.@{ub} Copy @{fg shine}mULTI-cHECK@{fg text} to your @{fg fill}c:@{fg text} directory or to any other directory of your\n    choice.\n\n @{b}2.@{ub} Copy the @{fg shine}documentation@{fg text} to your docs-directory or any other directory...\n\n @{b}3.@{ub} Copy the supplied sample files @{"ADVERT.TXT" link "SAMPLE_ADVERT" 0} and @{"STRIPFILE.TXT" link "SAMPLE_STRIPFILE" 0} to a\n    directory of your choice. You may also copy @{fg shine}HEADER.TXT@{fg text} and @{fg shine}TAILER.TXT@{fg text} as\n    examples how to use the TextAdding feature!\n\n Now you have to edit the files @{b}ADVERT.TXT@{ub} and @{b}STRIPFILE.TXT@{ub} to your needs.\n ADVERT.TXT could have some special symbols which are described @{"HERE" link "SAMPLE_ADVERT" 0}.\n Also the HEADER.TXT file could contain these symbols, they are exactly the\n same like inside the ADVERT.TXT file. See there for further informations.\n The STRIPFILE.TXT should contain all filenames (!), you wish to kill from \n the archive. Please note that it''s on you to write only legal characters \n into this file, as mULTI-cHECK performs @{b}*NO*@{ub} checkings on these\n names !!! So make sure that you don''t use wildcards or other critical \n filenames inside this @{"stripfile" link "SAMPLE_STRIPFILE" 0}, otherwise it could happen that \n you gain only empty archives or other strange things...you''ve been warned!\n\n At least, you have to built in the checker to your BBS-System.\n\n\n                   @{b}--------- BBS-INSTALLATION ---------@{ub}\n\n\n@{u}AMIEX-SYSOPS:@{uu}\n\n Create four icons inside your BBS:FCHECK/ directory called\n\n                            @{fg shine}LZX.INFO@{fg text}\n                            @{fg shine}LHA.INFO@{fg text}\n                            @{fg shine}ZIP.INFO@{fg text}\n                            @{fg shine}TXT.INFO@{fg text}\n\n and edit the Tooltypes like shown below:\n\n  CHECKER = C:mULTI-cHECK\n  OPTIONS = @{"(CLICK HERE FOR OPTIONS)" link "USAGE" 0}\n    STACK = SAME\n PRIORITY = 1\n  ERROR.1 = Archive Corrupt!\n\n Repeat this steps for all four icons (or only the file-types you want\n to use mULTI-cHECK for)...the Options are described in the @{"Parameters" link "USAGE" 0}-\n chapter, see there for further informations !\n\n Now you are ready with the installation.\n\n\n@{u}FAME-SYSOPS@{uu}:\n\n Start the System-Editor and go to FileCheckers. Now edit the @{b}LHA@{ub}, @{b}ZIP@{ub}\n and TXT configurations like shown below:\n\n  CHECKER PATH = C:mULTI-cHECK\n    STACK SIZE = 4096\n      PRIORITY = 1\n       OPTIONS = @{"(CLICK HERE FOR OPTIONS)" link "USAGE" 0}\n       ERROR 1 = Archive Corrupt!\n\n For @{b}LZX@{ub}, you have the create a new configuration with the @{fg shine}NEW@{fg text} button, enter\n LZX as extension, fill in the fields and save this configuration.\n\n Of course you have to switch the checker(s) to @{b}ON@{ub} to let it work :)\n\n That''s all for installing it to @{"FAME" link "FAME" 0}, now you are ready to use it. See\n Chapter @{"Parameters" link "USAGE" 0} for further informations about the Options used by\n mULTI-cHECK.\n@endnode\n\n@node "USAGE" "How to use it and list of Parameters"\n                   @{b}LIST OF PARAMETERS USED BY mULTI-cHECK:@{ub}\n\n As mULTI-cHECK is fully commandline-driven, various parameters exists to\n control mULTI-cHECK. The command-template for mULTI-cHECK is:\n\n @{fg shine}ADVERT=AD/K,BBS-PATH=BBS/K,STRIPFILE=SF/K,PACKER=P/K,TYPE=T/K/A,TAILER=TA/K,NOMODIFY=NOM/S,FILENAME/A@{fg text}\n\n Click @{"HERE" link "USAGE_EXAMPLES" 0} for some examples how to start mULTI-cHECK.\n\n @{u}Explanation of Parameters:@{uu}\n\n mULTI-cHECK uses standard OS 2.0++ Parms and their keywords, so please take\n a look to your AmigaDOS-Manual for further informations about the templates\n of programs etc.\n\n    @{fg shine}@{bg shadow}ADVERT=AD/K@{fg text}@{bg back}  -  Specify here the Filename to the advert which should be\n                    added to the archive...click @{"HERE" link "SAMPLE_ADVERT" 0} for additional infos\n                    about the format of adverts used by mULTI-cHECK.\n\n                    @{b}@{fg fill}I.E.:@{ub}@{fg text} @{fg fill}ADVERT=S:MYADVERT.TXT@{fg text}\n\n                    will add @{fg fill}S:MYADVERT.TXT@{fg text} after parsing it for any special\n                    commands to the archive given as FileName.\n\n                    When using the Textmode, you have to enter here the path to\n                    the HEADER file which should be added above the original\n                    textfile.\n\n                    This Parameter is optional!\n\n    @{fg shine}@{bg shadow}TAILER=TA/K@{fg text}@{bg back}  -  This Parameter is only required when using mULTI-cHECK in\n                    Textmode. Here you may specify the Tailer file which will\n                    be added below the textfile. In all other modes this\n                    parameter is not required.\n\n @{fg shine}@{bg shadow}BBS-PATH=BBS/K@{fg text}@{bg back}  -  If you are using mULTI-cHECK with a BBS, enter here the\n                    main path to your BBS System, i.e. @{fg fill}BBS-PATH=BBS:@{fg text} or use\n                    @{fg fill}BBS-PATH=FAME:@{fg text} . Please notice that mULTI-cHECK is able to\n                    detect itself which System you are running...if you don''t\n                    specify this Option, but using the Uploader-Name etc.\n                    features inside an advert, mULTI-cHECK will write\n                    @{b}"-+- The SysOp -+- "@{ub} and @{b}"- Local Upload -"@{ub} for the name &\n                    location fields, otherwise all needed informations where\n                    extracted from the online''s user.datas and written to your\n                    advert.\n\n                    This Parameter is optional!\n\n @{fg shine}@{bg shadow}STRIPFILE=SF/K@{fg text}@{bg back}  -  Here you have to enter the path to a ascii-file containing\n                    all filenames you want to strip off the archive, i.e. you\n                    have a file in @{fg fill}S:@{fg text} called @{fg fill}strips@{fg text} containing:\n\n                                @{i}display.me@{ui}\n                                @{i}fuck_it.txt@{ui}\n                                @{i}werbung.txt@{ui}\n\n                    then you enter @{fg fill}STRIPFILE=S:STRIPS@{fg text} and all filenames listed\n                    inside this file where deleted from the archive. Look to\n                    the Chapter @{"Example-Stripfile" link "SAMPLE_STRIPFILE" 0} for further informations.\n\n                    @{u}NOTE:@{uu} If you are stripping from a @{fg shine}@{bg fill}ZIP-Archive@{fg text}@{bg back}, please don''t\n                          wonder about errormessages comming from ZIP, these\n                          errors are normal, as ZIP prints out all filenames,\n                          which couldn''t be found inside the archive to delete\n                          them...dunno know why this behavour exists, I can''t\n                          suppress this warnings and therefor you have to live\n                          with this :(\n\n                    This Parameter is optional!\n\n     @{fg shine}@{bg shadow}PACKER=P/K@{fg text}@{bg back}  -  Here you must enter the path to the checker you want to use.\n                    I''ve tested it with @{b}LHA V1.50@{ub}, @{b}LZX V1.20@{ub} and @{b}Zip V2.0.1@{ub} but\n                    as I only uses standard commands and therefor there should\n                    be no problems when using different versions. To specify\n                    the packer for @{fg fill}LZX@{fg text}, you could write for example:\n\n                                     @{fg fill}PACKER=C:LZX@{fg text}\n\n                    For the Textfile option this parameter is not required and\n                    you may leave it away in Textmode.\n\n     @{fg shine}@{bg shadow}TYPE=T/K/A@{fg text}@{bg back}   - Enter here the type of packer which is used...currently\n                    there exists 3 types:\n\n                                @{fg shine}LHA LZX ZIP TXT@{fg text}\n\n                    If you want to use @{fg fill}LHA@{fg text}, simply enter @{fg fill}TYPE=LHA@{fg text} and\n                    mULTI-cHECK uses now the @{fg fill}LHA@{fg text} routines for stripping/testing\n                    and adding...\n\n                    This Parameter is absolutly needed, without it mULTI-cHECK\n                    won''t work!\n\n @{fg shine}@{bg shadow}NOMODIFY=NOM/S@{fg text}@{bg back}   - If you want to add a picture or any other binary as \n                    advert to an archive please ALWAYS enter this parameter\n                    on the commandline, or your picture/binary/whatever will \n                    be detroyed when added to the archive! That''s because \n                    mULTI-cHECK won''t test the advert filetype for speed reasons \n                    and without this switch it will try to add the upload data \n                    into the binary, which of course destroys your addy :)\n                    So please keep this in mind when trying to add binary data!\n                    (New for V1.6+)\n\n\n\n     @{fg shine}@{bg shadow}FILENAME/A@{fg text}@{bg back}   - Here you specify the archive to test/add/strip. If you use\n                    mULTI-cHECK as Filechecker for your BBS, this Parameter will\n                    be filled out from the BBS, and therefor no Keyword is\n                    required to specify it (see @{"examples" link "USAGE_EXAMPLES" 0} below).\n\n                    This Parameter is absolutly needed, without it mULTI-cHECK\n                    won''t work!\n\n                @{"Click here for some examples of mULTI-cHECK" link "USAGE_EXAMPLES" 0}\n@endnode\n\n@node "USAGE_EXAMPLES" "Some examples how to use mULTI-cHECK."\n                  @{b}SOME EXAMPLES HOW TO USE mULTI-cHECK:@{ub}\n\n All examples listed here assuming that you have an advertfile called ADVERT\n found in S: and a stripfile called STRIP found in S:, too.\n\n\n@{b}1)@{ub} @{u}Simplest usage:@{uu}\n\n  mULTI-cHECK PACKER=C:LHA TYPE=LHA RAM:MYARCHIVE.LHA\n\n Will only check archive @{fg fill}RAM:MYARCHIVE.LHA@{fg text} in @{fg fill}LHA@{fg text} mode and uses @{fg fill}C:LHA@{fg text}.\n\n\n@{b}2)@{ub} @{u}With adding of an advert:@{uu}\n\n  mULTI-cHECK ADVERT=S:ADVERT PACKER=C:LZX TYPE=LZX RAM:MYARCHIVE.LZX\n\n Will check archive @{fg fill}RAM:MYARCHIVE.LZX@{fg text} in @{fg fill}LZX@{fg text} mode using @{fg fill}C:LZX@{fg text} and after the\n testing will add the @{fg fill}S:ADVERT@{fg text} file to the archive.\n\n\n@{b}3)@{ub} @{u}Stripping from an archive:@{uu}\n\n mULTI-cHECK STRIPFILE=S:STRIP PACKER=C:ZIP TYPE=ZIP RAM:MSDOS.ZIP\n\n Will check archive @{fg fill}RAM:MSDOS.ZIP@{fg text} in @{fg fill}ZIP@{fg text} mode using @{fg fill}C:ZIP@{fg text} and after testing,\n all filenames listed in @{fg fill}S:STRIP@{fg text} will be stripped off the archive.\n\n\n@{b}4)@{ub} @{u}Now an example with testing/adding/stripping for a BBS-System:@{uu}\n\n mULTI-cHECK ADVERT=S:ADVERT STRIPFILE=S:STRIP BBS-PATH=FAME: PACKER=C:ZIP\n             TYPE=ZIP RAM:MSDOS.ZIP\n\n\n@{b}5)@{ub} @{u}At least an example for the Textadding feature (V1.3):@{uu}\n\n mULTI-cHECK ADVERT=S:HEADER.TXT TAILER=S:TAILER.TXT BBS-PATH=FAME: TYPE=TXT\n RAM:ASCII.TXT\n\n It''s clear that you have to enter this in only one line, but the space here\n doesn''t allow it to write this example into one line. This example will\n first test @{fg fill}RAM:MSDOS.ZIP@{fg text} in @{fg fill}ZIP@{fg text} mode using @{fg fill}c:ZIP@{fg text}, then strips off all files\n contained in @{fg fill}S:STRIP@{fg text} from the archive and finally adds the advert @{fg fill}S:ADVERT@{fg text}\n to the archive, but filling out the advert first with uploader''s name, \n location etc. extracting this informations out of the BBS-Path @{fg fill}FAME:@{fg text} .\n\n@{b}6)@{ub} @{u}At least an example for the binary adding to archives feature (V1.6):@{uu}\n\n mULTI-cHECK AD=S:advert.jpg BBS=FAME: T=LHA NOM RAM:test.lha\n\n Here you will add the picture "S:advert.jpg" to the LHA archive\n "RAM:test.lha" without trying to modify the advert (NOM switch).\n This example also shows the abbrevations for all parameters passed\n to mULTI-vIEW.\n\n I think that should be enough examples on how to use it for your needs.\n\n For an overview about the @{"StripFile" link "SAMPLE_STRIPFILE" 0} or the @{"Advert" link "SAMPLE_ADVERT" 0} format used by mULTI-cHECK\n please take a look to the according chapters.\n@endnode\n\n@node "SAMPLE_ADVERT" "An example for an Advert used by mULTI-cHECK"\n                 @{b}SPECIAL COMMANDS USED FOR THE ADVERT:@{ub}\n\n As mULTI-cHECK is able to add @{i}Uploader Name@{ui} and @{i}Location@{ui}, @{i}Node-Nr@{ui}, @{i}Date@{ui} and\n @{i}Time@{ui} of the Upload into your advert, some special commands exists to let\n mULTI-cHECK add this items. Here''s a list of a special commands, you have\n to enter them exactly the same way they are written here:\n\n@{b}1) The Uploadername:@{ub} @{fg shine}@{bg fill}-U-S-E-R-H-A-N-D-L-E-@{fg text}@{bg back}\n\n Will be replaced by the name of the Uploader. Max length is 21 chars,\n shorter names are filled with spaces, longer names are cutted. If no\n uploadername could be found, the string "@{fg fill}-+- THE SYSOP -+-@{fg text}" will be added.\n\n@{b}2) The Uploaderlocation:@{ub} @{fg shine}@{bg fill}-U-S-E-R-L-O-C-A-T-I-O-N-@{fg text}@{bg back}\n\n Will be replaced by the Location of the Uploader. Max. length is 25 chars,\n shorter names are filled with spaces, longer names are cutted. If no\n uploaderlocation could be found, the string "@{fg fill}-+- LOCAL UPLOAD -+-@{fg text}" will be\n added.\n\n@{b}3) The Nodenumber:@{ub} @{fg shine}@{bg fill}¹¹@{fg text}@{bg back}\n\n Will be replaced by the Nodenumber from where the upload was done. Max.\n length is 2 chars, the nodenumber will be right-justified written to your\n advert. If no nodenumber could be found, the string "@{fg fill}--@{fg text}" will be written\n as Nodenumber.\n\n@{b}4) Date of check:@{ub} @{fg shine}@{bg fill}@@-@@-@@@{fg text}@{bg back}\n\n Will be replaced by the date the archive was tested. The date is in the\n USA format (@{fg fill}MM-DD-YY@{fg text}) and is always been added.\n\n@{b}5) Time of check:@{ub} @{fg shine}@{bg fill}##:##:##@{fg text}@{bg back}\n\n Will be replaced by the time the archive was tested. The time is in the\n format @{fg fill}HH:MM:SS@{fg text} and is always been added.\n\n\n\n                          @{b}SAMPLE FOR AN ADVERT:@{ub}\n\n@{fg shine}--- CUT HERE ---@{fg text}\n\n        _____ __ __ _____ __ _____.--.__ ________ ___________ __\n __ _ _/  ._ \\_ |  \\_    \\__)     \\_ | _/        \\_ ___/     \\_ l_  _\n   \\ \\\\_  |/  / |  _/ |  _/\\_  l___/ | \\_  |  |  _/ _/\\_  |  _/ _/_ /_\n       |   __/  |  |  |  |  l__   |     |  |  |  |  |  |  |  |  |  |  ||\n       |  |  |  |  |  |  |  |  |  |  |  |  |  |  |  l  |  |  |  l  |  |:\n       l__|  l_____l__|  l__l__   l__|  l__|__|  l__   l__|  l__   |  ||\n          ÷2F÷        `--''     `--''  `--''     `--''  `--''  `--''  `--''\n\n           · (tRSi-iNNOVATiONs) HQ & bETA sITE · fAME sUPPORT BBS ·\n\n                              __ _____ _____\n     A4ooo/o6o aT 5oMHZ      (__)     \\_    |\n                             | \\_  |  _/ l__|           sYSTEM-cHIEFS:\n   66mB rAM/20 GB HD-sPACE   |  |  |  |  |__\n                             |  |  |  |  l  |  _     SieGeL/tRSi & aRGON\n      2 x tELNET oNLY!       l__l__|  l__   | (_)\n                                   `--''  `--''\n\n          ! sUPPORTING pD and sHAREWARE oNLY oN aMIGA, PC & MAC !\n\n           gIVE iT a tRY - cONNECT tO telnet://siegel.dyndns.org\n\n             UPLOAD DATE: @@-@@-@@  TIME: ##:##:##  ON NODE: ¹¹\n\n    UPLOADER: -U-S-E-R-H-A-N-D-L-E-  LOCATION: -U-S-E-R-L-O-C-A-T-I-O-N-\n\n@{fg shine}--- CUT HERE ---@{fg text}\n@endnode\n\n@node "SAMPLE_STRIPFILE" "An example for a Stripfile used by mULTI-cHECK"\n             @{b}EXPLANATION FOR THE STRIPFILE USED BY mULTI-cHECK:@{ub}\n\n If you want to let mULTI-cHECK automatically remove unused files from the\n archives being tested, you have to create an ASCII-file containing all file-\n names you wish to remove from the archive. mULTI-cHECK takes this file with\n the Parameter @{"STRIPFILE=<PATH_TO_FILE>" link "USAGE" 0} and removes all files from the\n archive wich matches the filenames found inside the stripfile. Please use\n this option with care, as mULTI-cHECK performs @{b}NO@{ub} checkings about the given\n filenames (i.e. Patterns, spaces between names etc.) for the use of speed.\n It''s on you to remove only @{i}LEGAL@{ui} filenames which doesn''t create problems...\n I''ll give @{b}NO@{ub} warranty about any loss data which occures while removing files\n from an archive with @{i}ILLEGAL@{ui} filenames!\n\n\n                       @{b}EXAMPLE FOR THE STRIPFILE:@{ub}\n\n This is an example how a stripfile may look like. Snap this out and save it\n under a filename of your choice. After this, enter STRIPFILE=<YOUR_NAME> as\n parameter for mULTI-cHECK, and all files where removed then.\n\n@{fg shine}--- CUT HERE ---@{fg text}\n\n display.me \n fucker.txt \n "the fastest" \n READ.ME \n "BLA BLA BLA!"\n\n@{fg shine}--- CUT HERE ---@{fg text}\n\n Don''t ask me to built in a learn function for new adverts, I won''t built-in\n such unsafe things, if you want to remove files, @{b}YOU@{ub} have to enter the\n according filenames...I don''t trust doors/checkers, which are able to \n "learn", as this produces at most cases empty archives....:|\n@endnode\n\n@node "CREDITZ" "Credits and the wellknown Greetings"\n                               @{b}THE GREETINGS:@{ub}\n\n                     @{i}SieGeL/tRSi sends his regards to:@{ui}\n\n Strider        - FAME is still on Top, too bad that you stopped development  !\n aRGON          - A must-have in all docs :)\n dIGIMAN        - For running FAME forever ;)\n\n\n             @{fg shine}...and of course to all my registered users and@{fg text}\n                @{fg shine}everone I''ve forgot to listen here....@{fg text}\n\n\n                    @{b}@{fg shine}FAME - Final Amiga MailBox Engine !@{ub}@{fg text}\n\n        This checker is dedicated to this System, so go on and change now !\n\n   @{b}------------------------------------------------------------------------@{ub}\n\n    @{i}THE ONLY WAY TO MULTITASK ON MS-DOS IS TO RUN IBeM TWICE ON AN AMIGA !@{ui}\n@endnode\n\n@node "REGISTER" "Registration of Tools/Doors"\n@{b}REGISTER DOORS/TOOLS@{ub}\n\n All tools I''ve made in the past are released under the @{b}RegisterWare@{ub} concept.\n This means, that I release all my doors only one time as full working Public\n Versions, all updates/bugfixings are only available for registered Users.\n\n However, since a couple of years registration is no longer required, as I\n put all my effort in freeware programming. Maybe on the new AmigaOne \n platform there will be some day some kind of tool/utility I will sell, we\n will see...\n\n I will release all my (Classic-) Amiga Software for free, no registration\n is required. But I won''t re-release all my doors at once, I will update\n every door and put it in the public domain. So don''t ask for releasedates,\n just take a look now and then to the Aminet, you will see it there first!\n\n You can also download all my doors by telnetting to the following address:\n\n telnet://siegel.dyndns.org\n\n                   @{b}MEET YOU ON AMIGA-OS 4.x @ PPC :)@{ub}\n\n@endnode\n\n@node "FAME" "Informations about the FAME-System."\n\n                        @{b}Informations about FAME@{ub}\n\n FAME is at this time still under construction, but because of the fact\n that many people asked for FAME, it will be released until the end\n of february under the concept of shareware and will be available for\n everyone. At the begining not everything will be completly finished and\n because of this not everything you can already configure will work.\n The registered Versions have to work at least some days before they will\n be released for registered Users, but it''s still possible that these\n versions also make problems when using them. But as soon as you''ve\n reported those problems, they will be fixed!\n\n If some of the settings won''t work, it might be a bug but it''s also (more)\n possible that those functions are not implemented yet.\n\n Some of the internal functions are currently untested and it''s possible\n that they produce errors or problems, but please remember the complexity\n of FAME !\n\n If you have questions or problems with FAME, please turn on one of the\n FAME-Developers or ask Strider to solve your problems.\n\n\n@{b}@{u}What should FAME costs ?@{ub}@{uu}\n\n NOTHING! F.A.M.E. is for FREE, GO DOWNLOAD IT AT AMINET!\n\n\n@{b}@{u}What is included in the FAME-package ?@{ub}@{uu}\n\n Server, SystemEditor, MainPart, FAMEHydra.FIM, FAMEError.FIM\n\n FAME.library FAMEChat.FIM programmed by Bloodrock\n\n FAMEFullEd.FIM, FAMEScript.FIM programmed by Beatnik\n\n MUI UserEditor, FAMEDoorHelp.FIM, FAMEInfo programmed by SieGeL/tRSi\n\n Also some doors and tools from the FAME-Development-Team are included,\n but this doors are only unregistered Versions and have therefor some\n limitations. The registered Versions of those doors and the Informations\n how to get them are available here in the pUNISHMENT iNC. BBS.\n\n It could happen that some of the doors and tools listed here are currently\n missing because there are currently under development !\n\n\n@{b}@{u}Who creates FAME ?@{ub}@{uu}\n\n@{fg fill}Main programmer:@{fg text}\n\n - David ''Strider'' Wettig  [email removed]\n\n@{fg fill}Additional programmer:@{fg text}\n\n - Oliver ''Bloodrock'' Lange  [email removed]\n - Ulrich Arne ''Beatnik'' Jansen\n - Sascha ''Siegel'' Pfalz (tRSi) [email removed]\n\n@{fg fill}FAME-Development-Team:@{fg text}\n\n - David ''Strider'' Wettig  [email removed]\n - Oliver ''Bloodrock'' Lange  [email removed]\n - Ulrich Arne ''Beatnik'' Jansen\n - Sascha ''Siegel'' Pfalz (tRSi) [email removed]\n - Andreas ''ByteAndi'' Petermann\n - Dirk ''Spy'' Holzkampf\n - Bodo ''Dr.Dre!'' Hoffmann (tRSi)\n\n\n@{b}@{u}Disclaimer:@{ub}@{uu}\n\n No warranties are given. We take no responsibility of any possible harm this\n product could do to your AMIGA system (not that it would but..).\n We give also no warranties to any dokuments or doors/tools included with\n FAME.\n You use FAME and all FAME related files at your own risk !\n\n Of course we take no responsibility when someone is using FAME for illegal\n terms.\n @{b}------------------------------------------------------------------[EOF]-----@{ub}\n@endnode\n\n@node HeddleyAutoIndex "Index"\n@remark Index auto-generated by Heddley\nIndex of database mULTI-cHECK\n\nDocuments\n\n@{"An example for a Stripfile used by mULTI-cHECK" link "SAMPLE_STRIPFILE"}\n@{"An example for an Advert used by mULTI-cHECK" link "SAMPLE_ADVERT"}\n@{"Copyright Informations for mULTI-cHECK" link "COPYRIGHT"}\n@{"Credits and the wellknown Greetings" link "CREDITZ"}\n@{"How to use it and list of Parameters" link "USAGE"}\n@{"Informations about the FAME-System." link "FAME"}\n@{"Installation to your BBS-System of mULTI-cHECK" link "INSTALLATION"}\n@{"mULTI-cHECK - Archive-Checker for FAME & Amiex Systems" link "Main"}\n@{"Registration of Tools/Doors" link "REGISTER"}\n@{"Some examples how to use mULTI-cHECK." link "USAGE_EXAMPLES"}\n@{"Some informations about mULTI-cHECK" link "INTRODUCTION"}\n\nButtons\n\n@{"  CREDITS & GREETINGS!  " link "CREDITZ" 0}\n@{"  USAGE AND PARAMETERS  " link "USAGE" 0}\n@{"(CLICK HERE FOR OPTIONS)" link "USAGE" 0}\n@{"Advert" link "SAMPLE_ADVERT" 0}\n@{"ADVERT.TXT" link "SAMPLE_ADVERT" 0}\n@{"Click here for some examples of mULTI-cHECK" link "USAGE_EXAMPLES" 0}\n@{"COPYRIGHT & DISTRIBUTION" link "COPYRIGHT" 0}\n@{"Example-Stripfile" link "SAMPLE_STRIPFILE" 0}\n@{"examples" link "USAGE_EXAMPLES" 0}\n@{"FAME" link "FAME" 0}\n@{"FAME-System" link "FAME" 0}\n@{"HERE" link "SAMPLE_ADVERT" 0}\n@{"HERE" link "USAGE_EXAMPLES" 0}\n@{"Installation" link "INSTALLATION" 0}\n@{"INSTALLATION TO YOUR BBS" link "INSTALLATION" 0}\n@{"INTRODUCTION & FEATURES " link "INTRODUCTION" 0}\n@{"Parameters" link "USAGE" 0}\n@{"RegisterWare" link "REGISTER" 0}\n@{"stripfile" link "SAMPLE_STRIPFILE" 0}\n@{"STRIPFILE.TXT" link "SAMPLE_STRIPFILE" 0}\n@{"STRIPFILE=<PATH_TO_FILE>" link "USAGE" 0}\n@endnode\n','\n',char(10)),'{"STACK":"SAME","PRIORITY":"1","TYPE":"T/K/A"}','auto-added',158004,3,0,NULL,NULL,'trsi_m16','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_m21','TRSI-M21.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-M21.LHA','mEGA-vIEW','XIM','CheckExe',NULL,'SieGeL/tRSi','TRSI','\     _____ _ ___    _)   ______________) \______\   |  \______\____     /-Mo!   \_ |______¦______| _ ________/_________/',replace('______________________ _________________\n\     _____ _ ___    _)   ______________)\n \______\   |  \______\____     /-Mo!   \_\n     |______¦______| _ ________/_________/\nø-[ TRSI! ]-:--[ /X·INNOVATION ]--[ GIVES]-ø\n.------------------------------------------.\n|  mEGA-vIEW v2.15 pUBLIC bY SieGeL/tRSi   |\n|This is the last Version of the /X Viewer.|\n| I''ve released it because the Development |\n| for this tool is now discarded, because  |\n|  I will only support FAME in the future. |\n`------------------------------------------''\n','\n',char(10)),'MeGa-VIEW.GUIDE',replace('@database mEGA-vIEW V2.15 DoCS\n@author "SieGeL/tRSi"\n@(c) "Copyright © 1994-95 (tRSi/X-iNNOVATiON)"\n@$VER: mEGA-vIEW.guide V2.15 (08-28-98)                                    \n                    \n@index Main\n\n@node Main "mEGa-vIEW V2.15 - /X uTiL WRiTTeN BY SieGeL/tRSi"\n@{b}\n  _______________________________________________                  _______\n |  ___________      _______. ___________ _______|_      _________|_    _/\n |  \\    _____/_____(_______:/   __     /___  ____/_____/_   __    /___ |\n | _/\\_______     /         :   _______/   /  \\__        /  ______/   / |\n | \\ _ __________/__________:_____________/_____/  Mo!  /____________/  |\n |  \\\\ /                                       /_______/          l_____|\n |   \\/  @{ub}SIEGEL/TRSI (/X·INNOVATION) PRESENTS    @{b}|\n |      -------------------------------------    |     @{" INTRODUCTION " Link INTRODUCTION}\n |                                               |     @{"   FEATURES   " Link FEATURES}\n |                                               |     @{" INSTALLATION " Link REQUIREMENTS}\n |              @{ub}··M·E·G·A··V·I·E·W··@{b}             |     @{"   TOOLTYPES  " Link TOOLTYPES}\n |                                               |     @{" REGISTRATION " LINK REGISTER}\n |                  @{ub}V2.15 pUBLIC@{b}                 |     @{"  GREETINGS!  " Link GREETS}\n | \\                                             |     @{"  TO-DO LIST  " LINK TODO}\n | \\\\\                                            |   \n @{b}`-----------------------------------------------''@{ub}\n@endnode\n                                                                             \n@node INTRODUCTION "INTRODUCTION..."\n\nYeah, another update of this famous Viewer reached your BBS...since the last\nrelease in june,1994, many things have changed...some new packers are \nincluded, some routines were rewritten to give you the maximum speed avail-\nable on your machine and of course many bugfixings have been done. To get\nan overview what''s new/changed in this Public Release of my Viewer, take\na look to the @{b}HISTORY-FILE@{ub} included in this archive.\n\nAnother major changing is the fact that mEGA-vIEW and all other programs I\nwill made in the future are declared as @{b}SHAREWARE@{ub}, which means, that you\nhave to pay a registration fee to become the newest versions...this Version\nof mEGA-vIEW is 100% working version without any restrictions, but I don''t\nrelease any update of the viewer in the future, all changings will then\nonly be accessable for @{"Registered Users" LINK REGISTER}...\n@endnode\n\n@node QUICKFEATURES "SHORT OVERVIEW OF THE FEATURES"\n@{u}Features are :@{uu}\n\n - Supports Wildcards (*)\n\n - @{b}Viewing/Downloading@{ub} Files directly from a @{b}LHA/ZIP-Archive@{ub}\n\n - Integrated Sysop-View (editable via @{"Tooltypes" LINK TOOLTYPES})\n\n - Securitycheck for @{"RESTRICTED FILES" LINK RESTRICT}\n\n - Fileidentification via FileID.Library by BloodRock/Syndicate\n\n - New option to @{b}view AmigaGuide® - Databases as ANSI-Files@{ub} \n\n - @{b}DMS/ARJ/EXE/SHRINK/ZOO/ZOOM/WARP/LZX@{ub}-Checker supported\n\n - Don''t break viewing if a character with ascii-value >128 was found...\n\n - Supports ''@{b}NS@{ub}'' to view files NonStop...useful for BBS-Adverts..\n\n - Could @{b}Extract@{ub} and show @{b}FILE_ID.DIZ@{ub} from @{b}EXEcutables@{ub} or @{b}DMS-Archives@{ub}\n\n - Extraoption to choose at which Accesslevel a user could view (and test of\n   coz :-} ), otherwise he could only test files/archives...\n\n - @{b}CRSR-Keys@{ub} used to choose a file for viewing/dl''ing from @{b}LHA/ZIP@{ub}-archives\n\n - @{b}Hexadecimaloutput@{ub} (similar to the DirectoryOpus-Function HEXREAD) for all \n   unknown or not supported Files (i.e. MS-DOS Executables!)\n\n - Is able to show the Tooltypes of Project- ,Tool- & Drawer-Icons\n\nand many other cewl Functions....if ya now interested, then @{"install" LINK REQUIREMENTS} it \nto your /X-System...\n@endnode\n\n@node FEATURES "MAIN FEATURES AND OTHER REASONS TO USE THIS TOOL"\nI don''t believe that you have any problems, coz mEGA-vIEW works similar\nto the original /X viewer, but has some more powerful enhancements, like :\n\n@{u}1.) You could use NS@{uu}\n\nIf you want to view a file Nonstop, that means that mEGA-vIEW don''t prompt\nyou to continue,etc., all you have to do is to enter NS after the Filename,\ni.e.:\n                           @{b}Diabolo.doc NS @{ub}\n\nwill show Diabolo.doc nonstop..or if you enter :\n\n                              @{b}Dia* NS@{ub}\n\nlets mEGA-vIEW search for all patterns matching "DIA*" and then show the \ndesired file nonstop.\nThis works anywhere, you could enter @{b}NS@{ub} after the filename and the selected \nfile will be shown nonstop.\n\n@{u}2.) Using WildCards@{uu}\n\nThis Feature was the main reason why I wrote this Tool ...:) \n\nYou could use wildcards as much as you want it to do so...:) , and in \ndifference to AmieX, you DON''T have to enter three real Chars before\nusing Wildcards, so you could call mEGA-vIEW like:\n \n                       @{b}V S:START*@{ub}\n\n...searches for files in S:, which contains the pattern START*...or \nenter something like this :\n\n                       @{b}V S:SH*LL-ST*ART*P NS@{ub}\n\nwill search for all patterns which matches the pattern and then show the\ndesired file NonStop\n                       @{b}V S:*@{ub}\n\n...shows you ALL files which are found in Drawer S:...this works also for\nthe "normal" viewmode (NO SYSOPVIEW), i.e.\n\n                       @{b}V *@{ub}\n\nshows you @{b}ALL@{ub} files which are found in the current DL-Pathes. Nice eh ?! :)\n\n@{u}3.) Testing Archives@{uu}\n\nIf you select a archive, you have always the choice to @{b}test@{ub} it. If mEGA-vIEW\nrecognize an archive, you were asked to view the @{b}contents/informations@{ub}...\nenter now @{b}''T''@{ub} and the desired archive will be tested...hope you enjoy the\n@{b}realtime testings via PIPE:@{ub} ...:) Don''t get confused if you see four different\nTestmodes by LHA...LHA V1.50r gives you the option to change the output. I''ve\nincluded a randommode which changes the LHA-Output at every call...so don''t\nthink this is a mistake or a Virus or whatever...it''s only my mad brain..:()\n\n@{u}4.) Filerecognizing@{uu}\n\nNow mEGA-vIEW is able to check which filetype you''ve selected by using the\n@{b}FileID.Library@{ub} from BloodRock/Syndicate. It''s no longer possible to confuse\nthe viewer,i.e. Rename a LHA-Archive in xxxxxxxx.DMS and try to view it with\nV1.0...the first Version tries to open it as DMS-archive. In this new Version,\nalso such renamed files will be identified correctly.\n\n@{u}5.) Restricted Files@{uu}\n\nA main changing was the handling of @{"RESTRICTED FILES" LINK RESTRICT}. In V1.0, I only check \nfor Restricted Files defined in ACP. Now mEGA-vIEW checks out the @{"ACP" LINK ACP} Icon and\nif not found, it checks now the FileComments for the Keyword ''@{b}RESTRICTED@{ub}''. If\nfound, it breaks and inform the user that this file is restricted. This works\nalso if you select a file from an archive for viewing/downloading, which is \nmarked as restricted.\n\n@{u}6.) CRSR-Keys@{uu}\n\nIf you select a @{b}LHA/ZIP-archive@{ub} you will see the contents of this archive and\nyou could now use the @{b}CRSR up/down keys@{ub} to select the file you want to view or\ndownload.\n\nAfter finding out that some Terminal-Programs like ''@{b}TERMINUS@{ub}'' on Amiga or\n''@{b}Telemate@{ub}'' on PC have some problems to emulate the CRSR-Keys, I have enhanced\nthe CRSR-Keys to use the keys @{b}8@{ub} & @{b}2@{ub}, too. So if you couldn''t use the CRSR-\nkeys, use @{b}8 for up and 2 for down@{ub} instead.\n\n@{u}NOTE:@{uu} mEGA-vIEW sorts out some filenames which could make problems, i.e. File-\n      Names like @{b}''#?#?#''@{ub} , @{b}''*''@{ub} @{b}''SECOM CITY.DISPLAYME''@{ub} and so on.\n      I sorted out this files otherwise it is possible that the @{b}whole@{ub} (!) \n      archive will be extracted ! So don''t worry if you don''t find the right \n      file. \n      If you want to view such files, @{u}DOWNLOAD THE ARCHIVE AND TAKE A LOOK@{uu} \n      @{u}AT HOME !@{uu}\n\n      Don''t think I''m lame coz I know that''s possible to extract such files, \n      but always remember : It''s a TextViewer not a replacement for the Down-\n      loadcommand ! \n\n@{u}7.) Downloading FROM archives@{uu}\n\nThis option allows users with the correct Accesslevel to @{b}Download@{ub} a file from\na @{b}LHA@{ub} or @{b}ZIP@{ub}-archive. After selecting the desired File via @{b}CRSR-Keys@{ub}, you were\nasked to Download, view normal or view nonstop the file. Of course you could \nforbid the downloading by deactivating the ToolType @{"DL_LEVEL" LINK DLLEVEL}.\nIf you select @{b}D@{ub} for Download mEGA-vIEW checks your ratio (bytes) and \nif you were able to download something, you will receive the selected File \nvia @{b}ZModem@{ub}. If the user has a disabled Ratio no checkings were made.\nThis Option works similar for @{b}LHA and ZIP-Archives@{ub}.\n\n@{u}8.) Hex-Output@{uu}\n\nIf you select a file which couldn''t supported (i.e. MS-DOS Executables or\nSoundmods) mEGA-vIEW first tries to identify the File and then you were asked\nto view this file anyway. If you enter ''@{b}Y@{ub}''es you get an @{b}Hexadecimal-Output@{ub}\nfrom the selected File. If you use DirectoryOpus you should know this output,\ncoz it''s exactly the same output like DOpus'' HEXREAD. I have included this \noption to avoid a destroyed Screen, coz normally you won''t VIEW A SOUNDMODULE \nfor example, and if you do so you will see only garbarge on the screen. But \nunder Hexoutput you could read all printable characters without Screen-\nflashings,Beeps and whatever...of coz the file will be checked for @{"RESTRICTED" LINK RESTRICT} \nbefore displaying.\nIt could happen that the FileID.Library don''t recognize a file correctly, in\nthis case you won''t see the Hex-Output ! mEGA-vIEW show you the file like a \nTextfile and therefor you will get a destroyed Screen....\n@endnode\n                                                                                \n@node REQUIREMENTS "WHAT YOU NEED TO INSTALL mEGA-vIEW"\n@{u}First U need...@{uu}\n\n - any @{b}Amigamodel@{ub} (A500-A4000T) with @{b}Kickstart 2.04++@{ub}\n\n - the installed /X-Software (Tested on /X 3.xx/4.xx ..don''t know if it\n   runs correctly under /X 2.xx...if someone could test it please @{"INFORM" LINK BBSADVERT1}\n   me !)\n\n - @{b}FileID.Library V5++ in LIBS:@{ub}\n\n - To take advantage of the packersupport I recommend to use the following \n   Tools to get the "full power" of mEGA-vIEW:\n\n   For @{b}LHA@{ub} use @{b}LHA V1.50r@{ub} by Stefan Boberg\n   \n   For @{b}DMS@{ub} use @{b}DMS V1.03/V1.11/V1.51/V1.53/V2.04@{ub} by ParCon-Software\n   \n   For @{b}ZIP@{ub} use @{b}UnZip V5.1@{ub} by Info-ZIP (@{u}And only this or higher Version@{uu} , \n                           earlier Versions won''t work correct!!!!)\n\n   For @{b}ARJ@{ub} use @{b}UnARJ V1.15/V2.41@{ub} by Robert K Jung\n\n   For @{b}EXE@{ub} use @{b}Executable Hunk Checker V1.0Beta@{ub} by Shagratt/LSD\n\n   For @{b}GUIDE@{ub} use @{b}Guide2DocProf V0.3@{ub} by fOX/rEMEDY^aSPECT\n\n   For @{b}SHRINK@{ub} use @{b}SHRINK V1.1@{ub} by Matthias Meixner\n\n   @{u}Changings to V2.05:@{uu}\n\n   For @{b}ZOO@{ub} use @{b}ZOO V2.1@{ub} written by Unknown...\n\n   For @{b}ZOOM@{ub} use @{b}ZOOMCHK V.01@{ub} by Carnivore/Beermacht\n\n   For @{b}WARP@{ub} use @{b}WARPCK V1.4@{ub} by Mike Thomas and Doug Keller\n\n   For @{b}LZX@{ub} use @{b}LZX V1.00@{ub} by Data Compression Technologies.\n\n   For @{b}FILE_ID.DIZ-Support@{ub} you need @{b}DMSDESCRIPT/EXEDESCRIPT@{ub} by @{b}Remo/MST@{ub} \n  \n - The Device @{b}PIPE:@{ub} already mounted (Used for testing archives...!)\n\n - Some files to view....:)\n\nTo install mEGA-vIEW, copy @{b}''mEGA-vIEW''@{ub} & @{b}''mEGA-vIEW.info''@{ub} to the directory\nwhere you stored your /X-Tools.\n\n@{u}NOTE:@{uu} Make sure that you place the icon in the same directory like the main\n      program, otherwise mEGA-vIEW couldn''t find it...!\n\nNow copy the icons @{b}''V.INFO''@{ub} and @{b}''VS.INFO''@{ub} to @{b}BBS:COMMANDS/BBSCMD/@{ub}\n\nAfter this, copy all packers from the included @{b}C-Dir@{ub} to your @{b}C-directory@{ub}.\n\nCopy @{b}FileID.Library@{ub} to @{b}LIBS:@{ub}, and if you want to use the @{b}Locale-Feature@{ub} of the\nLibrary, copy the @{b}FileID.catalog@{ub} to your @{b}LOCALE:CATALOGS/DEUTSCH/@{ub} drawer.\n\nNow before using mEGA-vIEW, please take a look to chapter @{"TOOLTYPES" LINK TOOLTYPES} and check\nout the pathes.\n\n@endnode\n\n@node TOOLTYPES "ALL TOOLTYPE-INFORMATIONS FOR mEGA-vIEW V2.05"\n\n                   @{b}All Tooltypes from mEGA-vIEW V2.05 :@{ub}\n\n@{u}1) Definitions for Supported Filetypes@{uu}\n\n   @{"    LHA_PATH    " LINK LHA} - Path for LHA\n   @{"    DMS_PATH    " LINK DMS} - Path for DMS\n   @{"   DMS_FILEID   " LINK DMSID} - Path for DMSDescript (FileID_DIZ from DMS)\n   @{"    ZIP_PATH    " LINK ZIP} - Path for UnZIP       \n   @{"    ARJ_PATH    " LINK ARJ} - Path for UnARJ\n   @{"   SHRINK_PATH  " LINK SHR} - Path for SHRINK\n   @{"    EXE_PATH    " LINK EXE} - Path for CheckExe \n   @{"   EXE_FILEID   " LINK EXEID} - Path for EXEDescript (FileID_DIZ from EXEcutables)\n   @{"   GUIDE_PATH   " LINK GUIDE} - Path for Guide2DocProf (converts GUIDE to ANSI)\n   @{"    ZOO_PATH    " LINK ZOO} - Path for ZOO\n   @{"   ZOOM_PATH    " LINK ZOOM} - Path for ZOOMCHK\n   @{"   WARP_PATH    " LINK WARP} - Path for WARPCK\n   @{"    LZX_PATH    " LINK LZX} - Path for LZX\n\n@{u}2) Other Definitions@{uu}\n                          \n   @{"   TEMP_PATH    " LINK TEMP} - Path for Temporary Files\n   @{"    ACP_PATH    " LINK ACP} - Path to ACP.INFO        \n   @{"   CALLERSLOG   " LINK CALLERSLOG} - Write to CallersLog (YES or NO)\n   @{"   ONLY_CHECK   " LINK ONLYCHECK} - Accesslevel for viewing files\n   @{"    DL_LEVEL    " LINK DLLEVEL} - Accesslevel for Downloading    \n   @{" SYSOPVIEWLEVEL " LINK SYSOPVIEW} - Accesslevel for Sysopview\n\n@endnode\n                                                                            \n@node LHA "SUPPORT OF LHA/LZH-ARCHIVES"\n@{b}                              LHA_PATH=<path>                             \n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you specify the complete path to @{b}LHA@{ub}, i.e. LHA_PATH=C:LHA. If this Tool-\ntype is not set or the path is incorrect, LHA-Support is disabled.\n\nIf you set it correct, users have the ability to @{b}view/download *ONE* file@{ub} \ndirectly from the selected archive. If an user selects a LHA/LZH-archive, he\nwill be asked first to @{b}View@{ub} or @{b}Test@{ub} the desired archive. \nIf the accesslevel defined in @{"ONLY_CHECK" LINK ONLYCHECK} is higher than the user''s access-\nlevel, the viewing is disabled and he could only test archives. \nIf the user selects (@{b}T@{ub})est, mEGA-vIEW tests the archive via LHA.\nDon''t get confused if you see four different LHA-Testoutputs, coz I have re-\nwritten the Testroutine to use all Displaymodes available by LHA V1.50r by \nchoosing it randomly.\n\nIf the user selects Viewing, mEGA-vIEW first loads in the Contentslist of the\ndesired archive and sorts out filenames with special chars or spaces in it,i.e.\nfiles containing ''#?'', ''*'', ''BBS ADVERT.TXT'' etc. won''t be shown in the list.\nSo if you don''t find your favourite BBS-Advert, DOWNLOAD THE WHOLE ARCHIVE AND\nTAKE A LOOK AT HOME! I have to disable this filenames, coz LHA interprets them\nas command to extract the @{b}WHOLE(!)@{ub} archive...After sorting out U get a list of\nthe remaining files inside the archive in alphabetical order. The list will be\nshown in two rows.The file which is actually selected will be shown in white, \nall other files are blue. Press now @{b}CRSR-UP/DOWN@{ub} to walk through the list. In\nthe middle of the list U could see an arrow pointing to the current selected \nfile. This is useful if you have @{b}ANSI-COLORS off@{ub} in Amiex, coz without \ncolors you won''t see which file you have selected, but with this arrow you \nalways know which file is selected. \nThe @{b}CRSR-Keys LEFT/RIGHT@{ub} are not supported coz you don''t need them.\nIf you scroll over the first/last entry in the list you fly back to the last/ \nfirst file in the list. When U found the file you want to take a look to, \npress ''ENTER'' and the selected file will be extracted from the archive.\n\nIt could happen that there are more files inside the archive as could be \ndisplayed at one time on your screen. In this case you are able to switch to\nthe next entries by pressing @{b}Space@{ub}. If all entries fit on your screen, the\n''@{b}SPACE@{ub}'' - Key is disabled. By pressing ''@{b}ESC@{ub}'' you get back to the Fileprompt\nof mEGA-vIEW.\n\nIf the user has an accesslevel higher or equal to the accesslevel defined in\nthe ToolType @{"DL_LEVEL" LINK DLLEVEL}, he could choose between (@{b}D@{ub})ownloading the file, view\nNon(@{b}S@{ub})top, (@{b}Q@{ub})uit to Fileprompt or (@{b}ENTER@{ub}) to view normal. If he choose ''@{b}D@{ub}'' for\nDownloading mEGA-vIEW first checks if the user has enough uploads to download\nsomething. If not, mEGA-vIEW stops and writes a message. Otherwise the user''s\nUp/Downloading-Statistics and the selected file (with Bytesize) will be \ndisplayed. If he/she has a Disabled Ratio, no checkings were made and a small\ncomment were printed after the DailyBytes. \nPressing (@{b}ENTER@{ub}) starts the @{b}ZModem-Transfer@{ub}, (@{b}A@{ub})borts the transfer.\nAfter a successful transfer the Downloadstats from the user where changed and\nwritten to /X. Then mEGA-vIEW jumps back to the fileprompt.\n\nIf the user hasn''t the correct level to Download, he could only choose between \nnormal and Nonstop-View. \n@endnode\n                        \n@node DMS "SUPPORT OF DMS-ARCHIVES"\n@{b}                              DMS_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you specify the complete path to @{b}DMS@{ub}, i.e. DMS_PATH=C:DMS. If this Tool-\ntype is not set or the path is incorrect, DMS-Support is disabled.\n\nIf you set it correct, users have the ability to @{b}view informations@{ub} or to @{b}test@{ub}\nthe desired DMS-archive. If the user wants to test the archive, mEGA-vIEW calls\n@{b}DMS@{ub} with the argument ''TEST'' and redirect the output to PIPE:. From PIPE: it\nwill displayed to the user so that it runs in ''@{b}RealTime@{ub}''...:)\n\nIf the user selects ''@{b}View@{ub}'', he will see the Standard-Informations from DMS\n(mEGA-vIEW calls @{b}DMS@{ub} with the argument @{b}VIEW@{ub} and redirect the output to a file,\nwhich will be displayed). \n\nIf you have set the ToolType @{"DMS_FILEID" LINK DMSID} correct, mEGA-vIEW searches for the\nFiledescription inside the DMS-Archive and if found, you were asked to view it.\nIf you don''t set @{b}DMS_FILEID@{ub}, mEGA-vIEW display only the informations\nfrom the archive and get back to the fileprompt.\n\n@{"Thanx" LINK GREETS} must go to @{b}Re/Y\o/MST@{ub} for the Program @{b}DMSDESCRIPT V1.0@{ub}...\n@endnode\n\n@node DMSID "SUPPORT OF FILE_ID.DIZ IN DMS-ARCHIVES"\n@{b}                            DMS_FILEID=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you define the complete path to @{b}DMSDescript@{ub} written by @{b}Re/Y\o/MsT@{ub}, i.e.\nDMS_FILEID=C:DMSDESCRIPT. If this Tooltype isn''t set mEGA-vIEW wouldn''t \nsearch for @{b}FILE_ID.DIZ@{ub} inside a DMS-archive. If you set this ToolType correct,\nmEGA-vIEW search for a Filedescription inside the archive after displaying\nthe informations and if found, it will be displayed to the user.\n \nBig @{"Thanx" LINK GREETS} must go to @{b}Remo/MST@{ub} for his @{b}DMSDescript@{ub}.\n@endnode\n\n@node ZIP "SUPPORT OF ZIP-ARCHIVES"\n@{b}                              ZIP_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you specify the complete path to @{b}(Un)ZIP@{ub}, i.e. ZIP_PATH=C:UNZIP. If this\nToolType is not set or the path is incorrect, ZIP-Support is disabled.\n\nIf you set it correctly, users have the ability to @{b}view/download@{ub} a file\ndirectly from a @{b}ZIP-Archive@{ub}. The function of this Support is exactly the same\nlike @{b}LHA-Support@{ub}. If a user has an equal or higher accesslevel as defined in\n@{"DL_LEVEL" LINK DLLEVEL}, he could download @{b}*ONE*@{ub} file from the archive, otherwise he could\nonly view it. For detailed information about the options look in Chapter @{"LHA" LINK LHA},\nas this two packers are both uses the same Selection-Routine.\n\n@{u}NOTE:@{uu} Make sure that you only use @{b}UnZIP@{ub} (or ZIP) upto @{b}V5.1@{ub}, coz this is the \n      first Version that allows you to specify an Extractpath for ''Unzipping''.\n      The second major enhancement from @{b}UnZIP@{ub} is the option to create a \n      Contents-List like @{b}LHA@{ub} (only Names), and therefor I could handle ZIP\n      in the same way...\n      If the ZIP-Support won''t work check out your Version from UnZip. I''ve \n      included the correct Version of UnZIP in this package.\n      All Versions lower than the one i''ve included (V5.1) @{u}WON''T WORK WITH@{uu}\n      @{u}mEGA-vIEW !!!!@{uu}\n@endnode\n\n@node ARJ "SUPPORT OF ARJ-ARCHIVES"\n@{b}                              ARJ_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you specify the complete path to @{b}ARJ@{ub}, i.e. ARJ_PATH=C:UNARJ. If this Tool-\ntype is not set or the path is incorrect, ARJ-Support is disabled.\n\nIf you set it correct, users have the ability to @{b}view@{ub} the contents or to @{b}test@{ub} \nthe desired ARJ-archive. If the user wants to test the archive, mEGA-vIEW calls\n@{b}ARJ@{ub} and redirects the Output to PIPE: to show you the testing in ''@{b}RealTime@{ub}''.\n\nIf the user selects ''@{b}VIEW@{ub}'' mEGA-vIEW reads in the contents of the ARJ-archive\nand display it to the user. \n\n@{u}NOTE:@{uu} It''s impossible to extract only one file with @{b}UnARJ V1.15@{ub}, which I used\n      to implement this function. If someone has a newer Version which allows\n      extracting of single files, please send it to me and I will rewrite the\n      code to make it possible to view single files (maybe with Downloading\n      like @{"LHA" LINK LHA} or @{"ZIP" LINK ZIP}). \n\nTo get in Contact with me take a look to chapter @{"ADRESS" LINK BBSADVERT1}...\n@endnode\n\n@node SHR "SUPPORT OF SHRINK-ARCHIVES"\n@{b}                            SHRINK_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you specify the complete path to @{b}SHRINK@{ub}, i.e. SHRINK_PATH=C:SHRINK. If \nthis Tooltype is not set or the path is incorrect, SHRINK-Support is disabled.\n\nIf you set it correct, users have the ability to @{b}view@{ub} the contents or to @{b}test@{ub}\nthe desired SHRINK-archive. If the user wants to test the archive, mEGA-vIEW \ncalls @{b}SHRINK@{ub} and redirects the Output to PIPE: to show you the testing \nin ''RealTime''...:)\n\nIf the user selects ''@{b}VIEW@{ub}'' mEGA-vIEW displays the contents of the selected\nSHRINK-archive via PIPE: .\n\n@{u}NOTE:@{uu} Like @{"UnARJ" LINK ARJ} it''s impossible to extract only one file with @{b}SHRINK V1.1@{ub}, \n      which I used to implement this function. If someone has a newer Version \n      with extracting of single files, please send it to me and I will rewrite \n      the code to make it possible to view single files (maybe with DL''ing\n      like @{"LHA" LINK LHA} or @{"ZIP" LINK ZIP}) from SHRINK-Archives. \n\nTo get in Contact with me take a look to chapter @{"ADRESS" LINK BBSADVERT1}...\n@endnode\n\n@node EXE "SUPPORT OF EXECUTABLES"\n@{b}                              EXE_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you specify the complete path to an @{b}EXEcutable Checker@{ub}, i.e. \nEXE_PATH=C:CHECKEXE. If this Tooltype is not set or the path is incorrect, \nEXE-Support is disabled.\n\nIf you set it correct, users have the ability to @{b}check AmigaDos-Executables@{ub}.\nI use @{b}CheckExe by Shagratt/LSD@{ub}, but you could use every checker which supports\nthe normal DOS-Errorcodes (0,5,10,20). This is important coz if your favourite\nchecker doesn''t return a valid errorcode (i.e. all went okay but Returncode=10)\nyou couldn''t use it with mEGA-vIEW. I''m checking the ReturnCodes before \ncontinueing the program, so make sure that the Returncodes are DOS-compatible.\nAlso your ExeChecker should accept the following Syntax:\n\n                          @{b}CHECKEXE <filename>@{ub}\n\nand make sure that your checker supports redirecting of the output,otherwise\nthere could be problems. I have only the CheckExe-Checker, so I couldn''t test\nit with others...\nIf you plan to use ur own coded checker, make sure that you write your outputs\nto Output(), otherwise the Redirection could make problems...!\n\nIf the selected File is packed,mEGA-vIEW shows you the used packer (if FileID-\nLibrary recognize the packer of coz..). If you set the ToolType @{"EXE_FILEID" LINK EXEID}\ncorrect, mEGA-vIEW searches for the @{b}Filedescription@{ub} inside the Executable after\ndisplaying the Checkerresult and if found asks you to view the description.\nIf you don''t specify the @{b}EXE_FILEID@{ub} ToolType correct, mEGA-vIEW return to the\nfileprompt after showing the Informations from the ExeChecker.\n@endnode\n\n@node EXEID "SUPPORT OF FILE_ID.DIZ IN AMIGA-DOS EXECUTABLES"\n@{b}                            EXE_FILEID=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you define the complete path to @{b}EXEDescript@{ub} written by @{b}Re/Y\o/MsT@{ub}, i.e.\nEXE_FILEID=C:EXEDESCRIPT. If this Tooltype isn''t set mEGA-vIEW wouldn''t \nsearch for @{b}FILE_ID.DIZ@{ub} inside an Executable. If you set this ToolType correct,\nmEGA-vIEW search for a Filedescription inside the executable after testing it.\nIf a description were found it will be displayed to the user. \n \nBig @{"Thanx" LINK GREETS} must go to @{b}Remo/MST@{ub} for his @{b}ExeDescript.@{ub}\n@endnode\n\n@node GUIDE "SUPPORT OF AMIGAGUIDE® - DATABASES"\n@{b}                            GUIDE_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you specify the complete path to @{b}GuideToDoc@{ub} by fOX/rEMEDY^aSPECT, i.e.\nGUIDE_PATH=C:GUIDE2DOCPROF. If this Tooltype is not set or the path is \ninvalid, Guide-Databases were displayed with all special commands used by \nAmigaGuide®.\n\nIf you set it correct, users have the ability to view Guidedatabases like an\nnormal Textfile without the annoying ''@{b}@@{ub}'' , ''@{b}{}@{ub}'' and other commands only used\nby AmigaGuide. To convert the desired Guide into an @{b}ANSI-File@{ub} you need the\nCLI-Tool Guide2DocProf. You could use this Tool to convert any Guide-Database \nto an normal @{b}ASCII/ANSI@{ub} file. The Syntax for this Tool is :\n\n                   @{b}GUIDE2DOCPROF <GUIDE>@{ub}\n\nWere @{b}<GUIDE>@{ub} is the Guide you want to convert. This Tool writes the\nconverted Guide to STDOUT, so if you want to convert i.e. the mEGA-vIEW-Guide\nto an ANSI-file, simply type this in your favourite shell:\n\n        GUIDE2DOCPROF >RAM:VIEWER.DOCS CWORK:DOCS/mEGA-vIEW.GUIDE\n\nThis will convert the Guide ''@{b}CWORK:DOCS/mEGA-vIEW.GUIDE@{ub}'' into an ANSI-File\nwhich will be created in ''@{b}RAM:@{ub}'' as ''@{b}VIEWER.DOCS@{ub}'' .\n\nmEGA-vIEW calls Guide2docProf and redirect the output to a file temporary \nstored in ur @{b}Temp-Dir@{ub} (Could be set via @{"TEMP_PATH" LINK TEMP} ).\n\nAfter displaying the converted ANSI-File will be deleted.\n\n@{u}NOTE:@{uu} As some sysops noted, I have changed this command and replaced the\n      old Program GuideToDoc by @{"ByteAndi/tRSi" LINK TRSIMEMBER} with the new one from fOX. The\n      reason is that ByteAndi''s tool crashes, if the selected Guide is too\n      big...to avoid crashes fOX has written the same program in 100% ASM to\n      give the maximum speed available...so don''t wonder, just enjoy the fast\n      speed of this Tool...\n\nYou could use (of course..:) your own converter, but make sure that your\nconverter returns the correct Errorcodes and supports the same call from\nCLI like Guide2docprof, otherwise it won''t work ! \nSee Chapter @{"CHECKEXE" LINK EXE} for more Informations...\n@endnode\n\n@node ZOO "SUPPORT OF ZOO-ARCHIVES"\n@{b}                             ZOO_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you specify the complete path to the ZOO-Packer, i.e. ZOO_PATH=C:ZOO.\nIf this Tooltype is not present or the path is invalid, Zoo-Archiv-Handling\nis disabled. If this TT is set correct, users have the ability to @{b}view@{ub} the\ncontents of ZOO-archives or to @{b}Test@{ub} the integrity of the desired archive.\n\nI''ve implemented this old packer only for one reason...I saw weeks ago a \nlittle Amiex-Arexx-Door, which includes this packer, and the Author writes\nas Description, that this Door could handle more packers than mEGA-vIEW...:)\nWell,I don''t know what this Author think about mEGA-vIEW, but this fuckin''\naREXX-script was a 5 minute work, and mEGA-vIEW was developed over 2 Years of\nhard work, and i don''t want to see such shit...so I decided to implement this\nold packer, too..\n@endnode\n\n@node ZOOM "SUPPORT OF ZOOM-ARCHIVES"\n@{b}                            ZOOM_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you specify the complete path to the @{b}ZOOMCHK-Program@{ub} written by Carnivore\nfrom BeerMacht, i.e. ZOOM_PATH=C:ZOOMCHK. Don''t use here the original ZOOM-\npacker, as this stupid packer don''t support the testing of archives without\ndisplaying any requesters !!! Always use only the ZOOMCHK program...\n\nIn fact that this packer isn''t much popular, I decided only to support the\ntesting...if my registered Users want more informations, I will implement\nthe ZOOM-Sourcecode (available in good PD-Boards) into mEGA-vIEW, but that\nwas not neccessary yet..\n@endnode\n\n@node WARP "SUPPORT OF WARP-ARCHIVES"\n@{b}                            WARP_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you define the path to WARPCK V1.4,i.e. WARP_PATH=C:WARPCK. Invalid\nPathnames to the checker disables this option...\n\nWARP is a DMS-alike Packer, but has the difference that WARP could pack \nnearly anything, maybe with copyprotections...:) I''ll want to support this\npacker, ''coz i found many archives packed with warp, but don''t know if they\nare ok to download...so with this support everyone is able to check warp-\narchives.\n@endnode\n\n@node LZX "SUPPORT OF THE NEW LZX-ARCHIVES"\n@{b}                            LZX_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you specify the path to LZX V1.00, i.e. LZX_PATH=C:LZX. Invalid Path-\nnames disables the LZX-Support. If set correct, users could @{b}view@{ub} the contents\nor @{b}test@{ub} the archive...\n\nNOTE: This packer is the newest one available on Amiga...it combins very \n      good packrates with a lightning speed, but has a disadvantage in\n      difference to LHA...it doesn''t support yet the handling of recursive\n      extracting of files from an archive...i.e. if you have a archive with\n      the following files:\n\n                           screens/node/SUXX\n                           SUXX\n                           BBS/AMIEX\n\n..lha is able to extract the file SUXX without entering the whole pathname,\nso if I want to extract it, i have to enter only SUXX, not SCREENS/NODE/SUXX,\nand the FIRST file named SUXX will be extracted...but LZX currently doesn''t\nsupport this feature, here you MUST define everytime the whole path...and\ntherefor I have currently only the viewing/testing supported...for my\nRegistered users will come in the near future an update, which allows them\nto simply extract files out of LZX-Archives, no matter if the files are\nin different pathes inside the archive...but again: such features are only \nfor @{b}REGISTERED USERS@{ub}, so if you want to use such features, please @{"REGISTER" LINK REGISTER}!\n@endnode\n\n@node TEMP "DEFINITION FOR A TEMPORARY WORKPATH USED BY mEGA-vIEW"\n@{b}                             TEMP_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you could enter an alternate path for @{b}temporary files@{ub} which are used for\nextracting and converting files. This Tooltype must not be set, coz the \nDefault-Setting is ''@{b}RAM:@{ub}''. If you have not enough free Memory you should set\nit to a valid AmigaDOS-Path, i.e. "TEMP_PATH=DH0:T/" . All packers and other\nTools controlled by mEGA-vIEW uses the path you defined here for extracting,\nconverting or whatever. \n\n@{u}NOTE:@{uu} When you want to use the Ram-Disk as Temppath, always enter ''@{b}RAM:@{ub}'' as\n      path coz the Ram-Disk is a dynamic Drive and therefor RAM: is always\n      @{u}full (0 Bytes free!!)@{uu} . To let it work I have included two checkroutines.\n      The first one checks normal ADOS-Devices like DF0:, HD0: etc. if there \n      is enough space on it. The second one will be activated only if you \n      enter @{b}RAM:@{ub} as path or disable this ToolType. In this case, mEGA-vIEW \n      will check your @{b}FREE MEMORY@{ub} instead of checking the free space on \n      the device. Other devices @{b}WOULDN''T BE@{ub} recognized, so @{b}T:@{ub} will be \n      checked as Device, not for FreeMem !!!!\n@endnode\n\n@node ACP "HOW TO FIND YOUR ACP-ICON TO LET IT WORK CORRECTLY"\n@{b}                              ACP_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you specify the path to your @{b}ACP-Icon@{ub}. Normally, it''s not necessary to\ndefine this ToolType, but some Sysops told me that mEGA-vIEW didn''t find ACP\ncoz they have no Searchpathes defined. If mEGA-vIEW couldn''t find your ACP,\nenter as <path> a valid AmigaDos-Path to your ACP.\n\n@{u}NOTE:@{uu} In difference to the Packer-ToolTypes, you must define the @{b}PATH ONLY!@{ub}\n      Don''t enter here for example BBS:ACP, coz this results in BBS:ACP/ACP !\n      If your ACP will be found in BBS:, enter ACP_PATH=BBS: . I''m using this\n      ToolType coz I have no BBS online and therefor it won''t be started via\n      WBStartup. mEGA-vIEW won''t found ACP without this ToolType, so I define\n      this ToolType with my BBS-Directory (ACP_PATH=BBS:) and all works. \n\nThis Tooltype is disabled by default (closed in Branches () ) and I recommend\nfirst to try it without this ToolType. If mEGA-vIEW reports that ACP couldn''t\nfound define it to the path were ACP could be found and all should work now.\n@endnode\n\n@node CALLERSLOG "ADDING COMMENTS TO CALLERSLOG"\n@{b}                             CALLERSLOG=<YES|NO>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you could choose if mEGA-vIEW should add a comment to the Callerslog when\na user tries to @{b}view/download a Restricted File@{ub}. By default, this Option is\ndisabled. To enable it, set the ToolType to @{b}YES@{ub}, i.e. CALLERSLOG=YES. For more\ninformations about @{b}Restricted Files@{ub} take a look to @{"RESTRICTED FILES" LINK RESTRICT}.\n\n@{u}NOTE:@{uu} If you run a multinodeboard it could happen that Amiex @{b}crashes@{ub} while\n      mEGA-vIEW adds the comment. @{u}This is not a bug from me !!@{uu} So don''t think\n      lame ''bout me when you see a guru while adding the comment. If this \n      happens, @{b}disable@{ub} this option (CALLERSLOG=NO) and you have no problems\n      anymore.\n      I don''t know what AmieX does when two programs want to add a comment\n      but this error should only happen on all AmieX-Versions @{b}<@{ub} 3.20 ... If\n      you have a higher Version from AmieX (of coz ONLY REG. Versions !) and\n      this error occurs, please @{"INFORM" LINK BBSADVERT1} me and i try to inform the Authors of\n      AmieX to fix this problem.\n\n@endnode\n\n@node ONLYCHECK "HOW TO CHOOSE BETWEEN VIEWING & TESTING"\n@{b}                           ONLY_CHECK=<accesslevel>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you define which accesslevel is needed to @{b}View files/archives@{ub}. If you\ndon''t specify this ToolType @{b}NO@{ub} user could view anything. If you set it correct,\ni.e. ONLY_CHECK=50, all users with an accesslevel @{b}>=@{ub} 50 could view files with\nthe full support of all packers. All users with an accesslevel @{b}<@{ub} 50 could only\n@{b}test archives@{ub}, @{b}viewing of textfiles is disabled@{ub}. Don''t need to write more bout\nthis option, I think...\n@endnode\n\n@node DLLEVEL "ACCESSLEVEL TO DOWNLOAD FROM LHA/ZIP-ARCHIVES"\n@{b}                           DL_LEVEL=<accesslevel>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nThis ToolType defines at which accesslevel a user could Download @{b}*ONE*@{ub} File\nfrom a @{b}LHA/ZIP-archive@{ub}. If this ToolType is not set or the user''s accesslevel\nis below the level defined here, the Downloadoption for @{b}LHA/ZIP@{ub} is disabled,\nand the user could only view files. If the user has an accesslevel equal or\nhigher then the one defined here then he could choose if he want to @{b}view@{ub} or\n@{b}download@{ub} a file from @{b}LHA/ZIP@{ub}. \n\n@{u}NOTE:@{uu} If a user has the Accesslevel for @{b}SYSOPVIEW@{ub} but not for Downloading,\n      then the Downloading is disabled, too. @{"SYSOPVIEWLEVEL" LINK SYSOPVIEW} doesn''t overwrite\n      this to avoid Leeching from CoSysOps or other people who wants to abuse\n      such a option.\n\nWhen a user could Download, mEGA-vIEW checks two things before starting the\nDownload. First, mEGA-vIEW checks if the user has already enough Uploadbytes\nto download the selected File. The check is simple but good: mEGA-vIEW take\nthe Bytes uploaded by the user and adds the Bytesize of the file he wants to \nDL. If the result is higher than the uploaded Bytes, mEGA-vIEW stops and \ninform the user that he has ''@{b}Exceeded Bytes Limit@{ub}''. If the user has \nenough Uploadbytes to Download the selected File, mEGA-vIEW checks if the \nuser''s DailyBytesLimit will be high enough to download the file. If both \nchecks are okay, mEGA-vIEW starts the ZModem-Transfer. \n\nIf the User has a disabled Ratio, the checkings were skipped and he could \nDownload a file no matter which Byte-Stats he has...\n\nAfter transfering the File, mEGA-vIEW adds the filelength of the downloaded \nfile to the users Dl-Stats and returns to the Fileprompt.\n@endnode\n\n@node SYSOPVIEW "DEFINITION FOR SYSOPVIEW"\n@{b}                       SYSOPVIEWLEVEL=<accesslevel>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you could define at which level users could view files @{b}outside@{ub} the BBS-\npathes, i.e. the user could enter ''@{b}V DOCS:mEGA-vIEW.GUIDE@{ub}''. This ToolType \noverrides the @{"ONLY_CHECK" LINK ONLYCHECK} access. \n\nOf course all checkings for restricted Files will be made before displaying\nthe selected File to the user. If you don''t specify it @{b}NO@{ub} users could view\nanything outside the regular BBS-Pathes. I have defined this Tooltype to the\naccesslevel of my Cosysops so they could view private files as long as they\nwere not marked as restricted.\n\nTo use the @{b}SYSOPVIEWCOMMAND@{ub} I''ve included an icon called ''@{b}VS@{ub}'' which let''s you\nuse mEGA-vIEW similar to the @{u}original internal SYSOPVIEW-Command@{uu}. This Icon\nis not neccassary to use the @{b}SYSOPVIEW@{ub}, but made things easier for you...:)\n\n@endnode\n\n@node RESTRICT "INFORMATIONS ABOUT RESTRICTED FILES"\n                         @{b}RESTRICTED FILES@{ub}\n\nAmieX has the ability to @{b}protect@{ub} Files against @{b}Downloading/Viewing@{ub} by adding\na FileComment (RESTRICTED) to those files. They are defined in the @{b}ACP-Icon@{ub}\nwith the ToolType @{b}RESTRICT.x=<file>@{ub}. When you start your BBS all Files defined\nas Restricted in ACP were marked as Restricted in the FileComments. If you want\nto protect other files not defined in ACP then add a FileComment to this file\nwith the DosCommand @{b}FileNote@{ub}. Take a look to your Dos-Manual for a detailed \nCommandsyntax.\n\nEverytime a user tries to @{b}view/download@{ub} such files mEGA-vIEW informs the user\nthat this File is restricted and if you have @{"CALLERSLOG=YES" LINK CALLERSLOG} a Comment would be\nadded to your Callerslog with the complete Filename of the File the user tries\nto view.\n\n@endnode\n\n@node GREETS "DA GREETINGSLIST..."\n\n@{b}Greetings fly to...@{ub}\n\nByteAndi/tRSi      - For many help\n\nRemo/MST           - For his great Programs ''EXEDESCRIPT'' & ''DMSDESCRIPT''..\n\nBloodRock/SDC      - Your FileID.Library is the BEST!\n\naRGoN/dTL          - Traden Roolez ne war Oldae ? :)\n\ndEATH aNGEL/sDC    - Cewl testing...you''re the best Betatester..grins..\n\nbYSiS/iNDY         - wELCOME iN tHE mODEM-sCENE...:)\n\neCS/tRSi           - wait for the Guide-Viewing...:) it''s in work...\n\n ...and of coz all BETA-Testers, TRSi & NEON-Members all around the Globe...\n\n@{b}PS: THE ONLY WAY TO MULTITASK ON MS-DOS IS TO RUN IBeM TWICE ON AN AMIGA!@{ub}\n@endnode\n\n@node REGISTER "HOW TO GET REGISTERED USER"\n\n@{u}Registration@{uu}\n\nAs I said before, I declared all my tools as SHAREWARE, meaning that you\nhave to pay a registration fee to become the newest versions available.\n\nThe reason why I declare them as Shareware is simply...take a look to the\nhistory-file, and you could see how many hard work i have done on this\ntool...I don''t believe that anyone will work simply for nothing, and there-\nfor I want money for my work.....\n\nThe Registration fee costs 30,-DM, and of course you have to pay this\nonly once ! After paying, you''ll become access to my Register-Door, allowing\nyou to leech everytime the newest versions...I''ll recommend to pay this,''coz\nI will only release all of my programs one time, all other updates are only\nfor registered Users, including all userwishes and other things, which should\nadded to mEGA-vIEW or other tools comming from me.\n\nTo register yourself, call our @{"WHQ" LINK BBSADVERT1} and leave a mail to SieGeL/tRSi \nthat you want to become registered User...\n\n@endnode\n\n@node TRSIMEMBER "ALL MEMBERS IN (tRSi/X-iNNOVATiON)"\n                           .                                         \n         .\n         :                 :\n - - -- -+- -- -- - -- - - + - --    /·/\n         :                 :        /·/\n         !                 :       /·/\n         ¡       _________/\\______/\\/   ____/\\_________\n         :       \\_  __  _  \\_ ____ \\__/    __________/       .\n         `- -- - --\\_/    \\  /   _/ _/____  \\  \\/free!\\       .\n                   _/      \\/   /    \\_   \\_    \\_     \\_     :\n                   \\_____   \\___\\   __/_____     /  ____/- - -+- - -\n                    \\___\\____/\\__\\__/\\____/\\____/____/_/      !\n                         \\___\\/   \\_\\/    \\/___/____/         ¡\n                           /·/  (/X-iNNOVATiON)   :           :\n                          /·/                     `- -- - -- -''\n                         /·/    ·M·E·M·B·E·R·S·\n\n                    ----------------------------------\n                       ByteAndi (tRSi/X-iNNOVATiON)\n                         SieGeL (tRSi/X-iNNOVATiON)\n                            Spy (tRSi/X-iNNOVATiON)\n                        Dr.Dre! (tRSi/X-iNNOVATiON)\n                    ----------------------------------\n               if you wanna join us so get in touch with\n\n                           one of our members.\n\nIf you want to order a tool, give us Bugreports, hints and tips for this or\nother tools comin'' from (tRSi/X-iNNOVATiON), try to contact us on any TRSI \nBoard Worldwide, or try one of the following (but both 100% LEGAL ONLY!) :\n\n               @{"pUNISHMENT iNC. - WHQ & bETA/rEGISTER sITE" LINK BBSADVERT1}\n\n               @{"   pARALYSIS    - GHQ & bETA/rEGISTER sITE" LINK BBSADVERT2}\n@endnode\n\n@node BBSADVERT1 "HOW TO CONTACT US"\n   _____________  __________               /\\   \n  |     __     /__\\__      /___________   /  \\             _____\n  |   ________/    /      /_\\____      \\_//   \\___________|_____|_______\n  |     |  \\      /      /      /      _//     \\    ______________      \\_\n  l_____|   \\___________/______/       \\_______/\\______   \\_    l/       /\n                              \\________/      /____________/____/       /\n                                       _________________       \\_______/     \n     ______ /\\____ ____________ _______\\______   ______/\n    /      /_      \\    __    /_\\_____      \\_    |\n  _/      \\/______/   _______/\\      /       /    |    · PUN¡sHMeNT ¡NC. ·\n  \\________\\    _/_____________\\____/  Mo!  /_____|\n                /                  \\_______/\n                                           /\\  ______________  ___________   \n     1oo% LeGaL sTUFF oN aM¡Ga^PC         /  \\_\\_______      \\_\\    _____/___\n                                         //   \\       /       /     /       /\n     RUNN¡NG oN a4ooo/6o · V.FasT      _//     \\_____/       /_____________/ \n                                       \\________/   \\_______/             \n                                                                             \n    TR¡sTaR & ReD seCToR ¡NC. (/X·¡NNoVaT¡oN) WoRLD HeaDQUaRTeR              \n                                                                             \n    aND eTH¡C D¡sT s¡Te   [> +49-(o)-3o-614-87-6o <]   sYsoP: s¡eGeL/TRs¡\n@endnode\n\n@node BBSADVERT2 "HOW TO CONTACT US"\n       ____                                                                  \n    ___\\  /______________________________________________________________    \n   /   \\\//                                                              \\   \n  /     \\/ -[ THe BeST eQUiPPeD PuBLIC DoMAIN BoaRD IN BeRLIN ]-          \\  \n /   -[ WiTH 4 GReaT U.S.ROBOTICS V.FAST CLASS MoDeMS WiTH FLaSH-RoMS ]-  \\ \n/                                                                           \\\n\\                        -- -[ SYNDIC/\\TE WHQ ]- --                         /\n \\   _____  _____    _____   _____  __      ___ __  _____   ___ _____      / \n  \\ /  _  \\/  _  \\  /  _  \\ /  _  \\/  |___ /   |  \\/   __)_/ __|   __)_   /  \n   /   |   \\  _   \\/   |  //   _   \\  |   \\\\_____  \\___    \\¯  |___    \\ /   \n  /   _____/  |    \\_ __   \\_  |    \\ |    \\   |    \\|      \\  | |      \\    \n  \\____| \\____|    /___|    /__|    /___   / _______/___    /__|____    /    \n      \\       l___/    l___/   l___/  \\___/___/  [ViC!]\\___/       \\___/     \n       \\                                                             /       \n        \\SYSTeM CHieFS: SPY/TRSi,ARTHuR DeNT,PHaNToM,Cat,JTC,big-rat/        \n         \\                                                         /         \n          \\   1: +49(0) 30 721 6071 USR DuAL STaNDaRD V.34 28.8   /          \n           \\  2: +49(0) 30 721 6072 USR DuAL STaNDaRD V.34 28.8  /           \n            \\ 3: +49(0) 30 721 6073 USR DuAL STaNDaRD V.34 28.8 /            \n             \\4: +49(0) 30 722 6065 USR DuAL STaNDaRD V.34 28.8/             \n              \\                                   /\\          /              \n               \\_________________________________//\\\\________/               \n                                                 /__\\\n\n                           SUPPORTS ONLY PD-/SHAREWARE !\n@endnode\n\n@node TODO "WHAT I PLANNED TO IMPLEMENT IN FUTURE RELEASES"\n\nSome wishes are currently not implemented, coz this features are only for\nregistered Users...\n\n- Better displaying of the contents from LHA/ZIP-archives, incl. date,bytes\n  and other informations.\n\n- Sysopcommands on LHA/ZIP - archives, allowing you to delete/add files.\n\n- Downloading/Viewing more than only one file from an archive.\n\n- Hydra-Support for Downloading\n\n- Viewing of Guides in two ways, ANSI & GUIDE...:)\n\n- maybe sometimes the support of the datatypes.library (WB/Kick 3.0+!)\n\n- special Version for Tempest-BBS-Systems.\n\n- better LZX-Handling like LHA & ZIP (Extracting, Downloading,etc.)\n\n@endnode\n','\n',char(10)),NULL,'auto-added',217098,6,0,NULL,NULL,'trsi_m21','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_m25','TRSI-M25.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-M25.LHA','mEGA-vIEW','XIM','CheckExe',NULL,'SieGeL/tRSi','TRSI','\     _____ _ ___    _)   ______________) \______\   |  \______\____     /-Mo!   \_ |______¦______| _ ________/_________/',replace('______________________ _________________    \n\     _____ _ ___    _)   ______________)   \n \______\   |  \______\____     /-Mo!   \_  \n     |______¦______| _ ________/_________/  \nø-[ TRSI! ]-:--[ /X·INNOVATION ]--[ GIVES]-ø\n.------------------------------------------.\n|  mEGA-vIEW v2.05 pUBLIC bY SieGeL/tRSi   |\n|nOW sUPPORTS LZX-WARP-ZOO-ZOOM & TOOLTYPES|\n|sOME bUGS fIXED, fAASTER tHAN eVERYTHING !|\n|    ! dA bEST /X-vIEWER eVER wRITTEN !    |\n`------------------------------------------''\n','\n',char(10)),'mEGA-vIEW.GUIDE',replace('@database mEGA-vIEW V2.05 DoCS\n@author "SieGeL/tRSi"\n@(c) "Copyright © 1994-95 (tRSi/X-iNNOVATiON)"\n@$VER: mEGA-vIEW.guide V2.05 (06-12-94)                                    \n                    \n@index Main\n\n@node Main "WoRLD-CLoCK V1.18 - /X uTiL WRiTTeN BY SieGeL/tRSi"\n@{b}\n  _______________________________________________                  _______\n |  ___________      _______. ___________ _______|_      _________|_    _/\n |  \\    _____/_____(_______:/   __     /___  ____/_____/_   __    /___ |\n | _/\\_______     /         :   _______/   /  \\__        /  ______/   / |\n | \\ _ __________/__________:_____________/_____/  Mo!  /____________/  |\n |  \\\\ /                                       /_______/          l_____|\n |   \\/  @{ub}SIEGEL/TRSI (/X·INNOVATION) PRESENTS    @{b}|\n |      -------------------------------------    |     @{" INTRODUCTION " Link INTRODUCTION}\n |                                               |     @{"   FEATURES   " Link FEATURES}\n |                                               |     @{" INSTALLATION " Link REQUIREMENTS}\n |              @{ub}··M·E·G·A··V·I·E·W··@{b}             |     @{"   TOOLTYPES  " Link TOOLTYPES}\n |                                               |     @{" REGISTRATION " LINK REGISTER}\n |                  @{ub}V2.05 pUBLIC@{b}                 |     @{"  GREETINGS!  " Link GREETS}\n | \\                                             |     @{"  TO-DO LIST  " LINK TODO}\n | \\\\\                                            |   \n @{b}`-----------------------------------------------''@{ub}\n@endnode\n                                                                             \n@node INTRODUCTION "INTRODUCTION..."\n\nYeah, another update of this famous Viewer reached your BBS...since the last\nrelease in june,1994, many things have changed...some new packers are \nincluded, some routines were rewritten to give you the maximum speed avail-\nable on your machine and of course many bugfixings have been done. To get\nan overview what''s new/changed in this Public Release of my Viewer, take\na look to the @{b}HISTORY-FILE@{ub} included in this archive.\n\nAnother major changing is the fact that mEGA-vIEW and all other programs I\nwill made in the future are declared as @{b}SHAREWARE@{ub}, which means, that you\nhave to pay a registration fee to become the newest versions...this Version\nof mEGA-vIEW is 100% working version without any restrictions, but I don''t\nrelease any update of the viewer in the future, all changings will then\nonly be accessable for @{"Registered Users" LINK REGISTER}...\n@endnode\n\n@node QUICKFEATURES "SHORT OVERVIEW OF THE FEATURES"\n@{u}Features are :@{uu}\n\n - Supports Wildcards (*)\n\n - @{b}Viewing/Downloading@{ub} Files directly from a @{b}LHA/ZIP-Archive@{ub}\n\n - Integrated Sysop-View (editable via @{"Tooltypes" LINK TOOLTYPES})\n\n - Securitycheck for @{"RESTRICTED FILES" LINK RESTRICT}\n\n - Fileidentification via FileID.Library by BloodRock/Syndicate\n\n - New option to @{b}view AmigaGuide® - Databases as ANSI-Files@{ub} \n\n - @{b}DMS/ARJ/EXE/SHRINK/ZOO/ZOOM/WARP/LZX@{ub}-Checker supported\n\n - Don''t break viewing if a character with ascii-value >128 was found...\n\n - Supports ''@{b}NS@{ub}'' to view files NonStop...useful for BBS-Adverts..\n\n - Could @{b}Extract@{ub} and show @{b}FILE_ID.DIZ@{ub} from @{b}EXEcutables@{ub} or @{b}DMS-Archives@{ub}\n\n - Extraoption to choose at which Accesslevel a user could view (and test of\n   coz :-} ), otherwise he could only test files/archives...\n\n - @{b}CRSR-Keys@{ub} used to choose a file for viewing/dl''ing from @{b}LHA/ZIP@{ub}-archives\n\n - @{b}Hexadecimaloutput@{ub} (similar to the DirectoryOpus-Function HEXREAD) for all \n   unknown or not supported Files (i.e. MS-DOS Executables!)\n\n - Is able to show the Tooltypes of Project- ,Tool- & Drawer-Icons\n\nand many other cewl Functions....if ya now interested, then @{"install" LINK REQUIREMENTS} it \nto your /X-System...\n@endnode\n\n@node FEATURES "MAIN FEATURES AND OTHER REASONS TO USE THIS TOOL"\nI don''t believe that you have any problems, coz mEGA-vIEW works similar\nto the original /X viewer, but has some more powerful enhancements, like :\n\n@{u}1.) You could use NS@{uu}\n\nIf you want to view a file Nonstop, that means that mEGA-vIEW don''t prompt\nyou to continue,etc., all you have to do is to enter NS after the Filename,\ni.e.:\n                           @{b}Diabolo.doc NS @{ub}\n\nwill show Diabolo.doc nonstop..or if you enter :\n\n                              @{b}Dia* NS@{ub}\n\nlets mEGA-vIEW search for all patterns matching "DIA*" and then show the \ndesired file nonstop.\nThis works anywhere, you could enter @{b}NS@{ub} after the filename and the selected \nfile will be shown nonstop.\n\n@{u}2.) Using WildCards@{uu}\n\nThis Feature was the main reason why I wrote this Tool ...:) \n\nYou could use wildcards as much as you want it to do so...:) , and in \ndifference to AmieX, you DON''T have to enter three real Chars before\nusing Wildcards, so you could call mEGA-vIEW like:\n \n                       @{b}V S:START*@{ub}\n\n...searches for files in S:, which contains the pattern START*...or \nenter something like this :\n\n                       @{b}V S:SH*LL-ST*ART*P NS@{ub}\n\nwill search for all patterns which matches the pattern and then show the\ndesired file NonStop\n                       @{b}V S:*@{ub}\n\n...shows you ALL files which are found in Drawer S:...this works also for\nthe "normal" viewmode (NO SYSOPVIEW), i.e.\n\n                       @{b}V *@{ub}\n\nshows you @{b}ALL@{ub} files which are found in the current DL-Pathes. Nice eh ?! :)\n\n@{u}3.) Testing Archives@{uu}\n\nIf you select a archive, you have always the choice to @{b}test@{ub} it. If mEGA-vIEW\nrecognize an archive, you were asked to view the @{b}contents/informations@{ub}...\nenter now @{b}''T''@{ub} and the desired archive will be tested...hope you enjoy the\n@{b}realtime testings via PIPE:@{ub} ...:) Don''t get confused if you see four different\nTestmodes by LHA...LHA V1.50r gives you the option to change the output. I''ve\nincluded a randommode which changes the LHA-Output at every call...so don''t\nthink this is a mistake or a Virus or whatever...it''s only my mad brain..:()\n\n@{u}4.) Filerecognizing@{uu}\n\nNow mEGA-vIEW is able to check which filetype you''ve selected by using the\n@{b}FileID.Library@{ub} from BloodRock/Syndicate. It''s no longer possible to confuse\nthe viewer,i.e. Rename a LHA-Archive in xxxxxxxx.DMS and try to view it with\nV1.0...the first Version tries to open it as DMS-archive. In this new Version,\nalso such renamed files will be identified correctly.\n\n@{u}5.) Restricted Files@{uu}\n\nA main changing was the handling of @{"RESTRICTED FILES" LINK RESTRICT}. In V1.0, I only check \nfor Restricted Files defined in ACP. Now mEGA-vIEW checks out the @{"ACP" LINK ACP} Icon and\nif not found, it checks now the FileComments for the Keyword ''@{b}RESTRICTED@{ub}''. If\nfound, it breaks and inform the user that this file is restricted. This works\nalso if you select a file from an archive for viewing/downloading, which is \nmarked as restricted.\n\n@{u}6.) CRSR-Keys@{uu}\n\nIf you select a @{b}LHA/ZIP-archive@{ub} you will see the contents of this archive and\nyou could now use the @{b}CRSR up/down keys@{ub} to select the file you want to view or\ndownload.\n\nAfter finding out that some Terminal-Programs like ''@{b}TERMINUS@{ub}'' on Amiga or\n''@{b}Telemate@{ub}'' on PC have some problems to emulate the CRSR-Keys, I have enhanced\nthe CRSR-Keys to use the keys @{b}8@{ub} & @{b}2@{ub}, too. So if you couldn''t use the CRSR-\nkeys, use @{b}8 for up and 2 for down@{ub} instead.\n\n@{u}NOTE:@{uu} mEGA-vIEW sorts out some filenames which could make problems, i.e. File-\n      Names like @{b}''#?#?#''@{ub} , @{b}''*''@{ub} @{b}''SECOM CITY.DISPLAYME''@{ub} and so on.\n      I sorted out this files otherwise it is possible that the @{b}whole@{ub} (!) \n      archive will be extracted ! So don''t worry if you don''t find the right \n      file. \n      If you want to view such files, @{u}DOWNLOAD THE ARCHIVE AND TAKE A LOOK@{uu} \n      @{u}AT HOME !@{uu}\n\n      Don''t think I''m lame coz I know that''s possible to extract such files, \n      but always remember : It''s a TextViewer not a replacement for the Down-\n      loadcommand ! \n\n@{u}7.) Downloading FROM archives@{uu}\n\nThis option allows users with the correct Accesslevel to @{b}Download@{ub} a file from\na @{b}LHA@{ub} or @{b}ZIP@{ub}-archive. After selecting the desired File via @{b}CRSR-Keys@{ub}, you were\nasked to Download, view normal or view nonstop the file. Of course you could \nforbid the downloading by deactivating the ToolType @{"DL_LEVEL" LINK DLLEVEL}.\nIf you select @{b}D@{ub} for Download mEGA-vIEW checks your ratio (bytes) and \nif you were able to download something, you will receive the selected File \nvia @{b}ZModem@{ub}. If the user has a disabled Ratio no checkings were made.\nThis Option works similar for @{b}LHA and ZIP-Archives@{ub}.\n\n@{u}8.) Hex-Output@{uu}\n\nIf you select a file which couldn''t supported (i.e. MS-DOS Executables or\nSoundmods) mEGA-vIEW first tries to identify the File and then you were asked\nto view this file anyway. If you enter ''@{b}Y@{ub}''es you get an @{b}Hexadecimal-Output@{ub}\nfrom the selected File. If you use DirectoryOpus you should know this output,\ncoz it''s exactly the same output like DOpus'' HEXREAD. I have included this \noption to avoid a destroyed Screen, coz normally you won''t VIEW A SOUNDMODULE \nfor example, and if you do so you will see only garbarge on the screen. But \nunder Hexoutput you could read all printable characters without Screen-\nflashings,Beeps and whatever...of coz the file will be checked for @{"RESTRICTED" LINK RESTRICT} \nbefore displaying.\nIt could happen that the FileID.Library don''t recognize a file correctly, in\nthis case you won''t see the Hex-Output ! mEGA-vIEW show you the file like a \nTextfile and therefor you will get a destroyed Screen....\n@endnode\n                                                                                \n@node REQUIREMENTS "WHAT YOU NEED TO INSTALL mEGA-vIEW"\n@{u}First U need...@{uu}\n\n - any @{b}Amigamodel@{ub} (A500-A4000T) with @{b}Kickstart 2.04++@{ub}\n\n - the installed /X-Software (Tested on /X 3.xx/4.xx ..don''t know if it\n   runs correctly under /X 2.xx...if someone could test it please @{"INFORM" LINK BBSADVERT1}\n   me !)\n\n - @{b}FileID.Library V5++ in LIBS:@{ub}\n\n - To take advantage of the packersupport I recommend to use the following \n   Tools to get the "full power" of mEGA-vIEW:\n\n   For @{b}LHA@{ub} use @{b}LHA V1.50r@{ub} by Stefan Boberg\n   \n   For @{b}DMS@{ub} use @{b}DMS V1.03/V1.11/V1.51/V1.53/V2.04@{ub} by ParCon-Software\n   \n   For @{b}ZIP@{ub} use @{b}UnZip V5.1@{ub} by Info-ZIP (@{u}And only this or higher Version@{uu} , \n                           earlier Versions won''t work correct!!!!)\n\n   For @{b}ARJ@{ub} use @{b}UnARJ V1.15/V2.41@{ub} by Robert K Jung\n\n   For @{b}EXE@{ub} use @{b}Executable Hunk Checker V1.0Beta@{ub} by Shagratt/LSD\n\n   For @{b}GUIDE@{ub} use @{b}Guide2DocProf V0.3@{ub} by fOX/rEMEDY^aSPECT\n\n   For @{b}SHRINK@{ub} use @{b}SHRINK V1.1@{ub} by Matthias Meixner\n\n   @{u}Changings to V2.05:@{uu}\n\n   For @{b}ZOO@{ub} use @{b}ZOO V2.1@{ub} written by Unknown...\n\n   For @{b}ZOOM@{ub} use @{b}ZOOMCHK V.01@{ub} by Carnivore/Beermacht\n\n   For @{b}WARP@{ub} use @{b}WARPCK V1.4@{ub} by Mike Thomas and Doug Keller\n\n   For @{b}LZX@{ub} use @{b}LZX V1.00@{ub} by Data Compression Technologies.\n\n   For @{b}FILE_ID.DIZ-Support@{ub} you need @{b}DMSDESCRIPT/EXEDESCRIPT@{ub} by @{b}Remo/MST@{ub} \n  \n - The Device @{b}PIPE:@{ub} already mounted (Used for testing archives...!)\n\n - Some files to view....:)\n\nTo install mEGA-vIEW, copy @{b}''mEGA-vIEW''@{ub} & @{b}''mEGA-vIEW.info''@{ub} to the directory\nwhere you stored your /X-Tools.\n\n@{u}NOTE:@{uu} Make sure that you place the icon in the same directory like the main\n      program, otherwise mEGA-vIEW couldn''t find it...!\n\nNow copy the icons @{b}''V.INFO''@{ub} and @{b}''VS.INFO''@{ub} to @{b}BBS:COMMANDS/BBSCMD/@{ub}\n\nAfter this, copy all packers from the included @{b}C-Dir@{ub} to your @{b}C-directory@{ub}.\n\nCopy @{b}FileID.Library@{ub} to @{b}LIBS:@{ub}, and if you want to use the @{b}Locale-Feature@{ub} of the\nLibrary, copy the @{b}FileID.catalog@{ub} to your @{b}LOCALE:CATALOGS/DEUTSCH/@{ub} drawer.\n\nNow before using mEGA-vIEW, please take a look to chapter @{"TOOLTYPES" LINK TOOLTYPES} and check\nout the pathes.\n\n@endnode\n\n@node TOOLTYPES "ALL TOOLTYPE-INFORMATIONS FOR mEGA-vIEW V2.05"\n\n                   @{b}All Tooltypes from mEGA-vIEW V2.05 :@{ub}\n\n@{u}1) Definitions for Supported Filetypes@{uu}\n\n   @{"    LHA_PATH    " LINK LHA} - Path for LHA\n   @{"    DMS_PATH    " LINK DMS} - Path for DMS\n   @{"   DMS_FILEID   " LINK DMSID} - Path for DMSDescript (FileID_DIZ from DMS)\n   @{"    ZIP_PATH    " LINK ZIP} - Path for UnZIP       \n   @{"    ARJ_PATH    " LINK ARJ} - Path for UnARJ\n   @{"   SHRINK_PATH  " LINK SHR} - Path for SHRINK\n   @{"    EXE_PATH    " LINK EXE} - Path for CheckExe \n   @{"   EXE_FILEID   " LINK EXEID} - Path for EXEDescript (FileID_DIZ from EXEcutables)\n   @{"   GUIDE_PATH   " LINK GUIDE} - Path for Guide2DocProf (converts GUIDE to ANSI)\n   @{"    ZOO_PATH    " LINK ZOO} - Path for ZOO\n   @{"   ZOOM_PATH    " LINK ZOOM} - Path for ZOOMCHK\n   @{"   WARP_PATH    " LINK WARP} - Path for WARPCK\n   @{"    LZX_PATH    " LINK LZX} - Path for LZX\n\n@{u}2) Other Definitions@{uu}\n                          \n   @{"   TEMP_PATH    " LINK TEMP} - Path for Temporary Files\n   @{"    ACP_PATH    " LINK ACP} - Path to ACP.INFO        \n   @{"   CALLERSLOG   " LINK CALLERSLOG} - Write to CallersLog (YES or NO)\n   @{"   ONLY_CHECK   " LINK ONLYCHECK} - Accesslevel for viewing files\n   @{"    DL_LEVEL    " LINK DLLEVEL} - Accesslevel for Downloading    \n   @{" SYSOPVIEWLEVEL " LINK SYSOPVIEW} - Accesslevel for Sysopview\n\n@endnode\n                                                                            \n@node LHA "SUPPORT OF LHA/LZH-ARCHIVES"\n@{b}                              LHA_PATH=<path>                             \n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you specify the complete path to @{b}LHA@{ub}, i.e. LHA_PATH=C:LHA. If this Tool-\ntype is not set or the path is incorrect, LHA-Support is disabled.\n\nIf you set it correct, users have the ability to @{b}view/download *ONE* file@{ub} \ndirectly from the selected archive. If an user selects a LHA/LZH-archive, he\nwill be asked first to @{b}View@{ub} or @{b}Test@{ub} the desired archive. \nIf the accesslevel defined in @{"ONLY_CHECK" LINK ONLYCHECK} is higher than the user''s access-\nlevel, the viewing is disabled and he could only test archives. \nIf the user selects (@{b}T@{ub})est, mEGA-vIEW tests the archive via LHA.\nDon''t get confused if you see four different LHA-Testoutputs, coz I have re-\nwritten the Testroutine to use all Displaymodes available by LHA V1.50r by \nchoosing it randomly.\n\nIf the user selects Viewing, mEGA-vIEW first loads in the Contentslist of the\ndesired archive and sorts out filenames with special chars or spaces in it,i.e.\nfiles containing ''#?'', ''*'', ''BBS ADVERT.TXT'' etc. won''t be shown in the list.\nSo if you don''t find your favourite BBS-Advert, DOWNLOAD THE WHOLE ARCHIVE AND\nTAKE A LOOK AT HOME! I have to disable this filenames, coz LHA interprets them\nas command to extract the @{b}WHOLE(!)@{ub} archive...After sorting out U get a list of\nthe remaining files inside the archive in alphabetical order. The list will be\nshown in two rows.The file which is actually selected will be shown in white, \nall other files are blue. Press now @{b}CRSR-UP/DOWN@{ub} to walk through the list. In\nthe middle of the list U could see an arrow pointing to the current selected \nfile. This is useful if you have @{b}ANSI-COLORS off@{ub} in Amiex, coz without \ncolors you won''t see which file you have selected, but with this arrow you \nalways know which file is selected. \nThe @{b}CRSR-Keys LEFT/RIGHT@{ub} are not supported coz you don''t need them.\nIf you scroll over the first/last entry in the list you fly back to the last/ \nfirst file in the list. When U found the file you want to take a look to, \npress ''ENTER'' and the selected file will be extracted from the archive.\n\nIt could happen that there are more files inside the archive as could be \ndisplayed at one time on your screen. In this case you are able to switch to\nthe next entries by pressing @{b}Space@{ub}. If all entries fit on your screen, the\n''@{b}SPACE@{ub}'' - Key is disabled. By pressing ''@{b}ESC@{ub}'' you get back to the Fileprompt\nof mEGA-vIEW.\n\nIf the user has an accesslevel higher or equal to the accesslevel defined in\nthe ToolType @{"DL_LEVEL" LINK DLLEVEL}, he could choose between (@{b}D@{ub})ownloading the file, view\nNon(@{b}S@{ub})top, (@{b}Q@{ub})uit to Fileprompt or (@{b}ENTER@{ub}) to view normal. If he choose ''@{b}D@{ub}'' for\nDownloading mEGA-vIEW first checks if the user has enough uploads to download\nsomething. If not, mEGA-vIEW stops and writes a message. Otherwise the user''s\nUp/Downloading-Statistics and the selected file (with Bytesize) will be \ndisplayed. If he/she has a Disabled Ratio, no checkings were made and a small\ncomment were printed after the DailyBytes. \nPressing (@{b}ENTER@{ub}) starts the @{b}ZModem-Transfer@{ub}, (@{b}A@{ub})borts the transfer.\nAfter a successful transfer the Downloadstats from the user where changed and\nwritten to /X. Then mEGA-vIEW jumps back to the fileprompt.\n\nIf the user hasn''t the correct level to Download, he could only choose between \nnormal and Nonstop-View. \n@endnode\n                        \n@node DMS "SUPPORT OF DMS-ARCHIVES"\n@{b}                              DMS_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you specify the complete path to @{b}DMS@{ub}, i.e. DMS_PATH=C:DMS. If this Tool-\ntype is not set or the path is incorrect, DMS-Support is disabled.\n\nIf you set it correct, users have the ability to @{b}view informations@{ub} or to @{b}test@{ub}\nthe desired DMS-archive. If the user wants to test the archive, mEGA-vIEW calls\n@{b}DMS@{ub} with the argument ''TEST'' and redirect the output to PIPE:. From PIPE: it\nwill displayed to the user so that it runs in ''@{b}RealTime@{ub}''...:)\n\nIf the user selects ''@{b}View@{ub}'', he will see the Standard-Informations from DMS\n(mEGA-vIEW calls @{b}DMS@{ub} with the argument @{b}VIEW@{ub} and redirect the output to a file,\nwhich will be displayed). \n\nIf you have set the ToolType @{"DMS_FILEID" LINK DMSID} correct, mEGA-vIEW searches for the\nFiledescription inside the DMS-Archive and if found, you were asked to view it.\nIf you don''t set @{b}DMS_FILEID@{ub}, mEGA-vIEW display only the informations\nfrom the archive and get back to the fileprompt.\n\n@{"Thanx" LINK GREETS} must go to @{b}Re/Y\o/MST@{ub} for the Program @{b}DMSDESCRIPT V1.0@{ub}...\n@endnode\n\n@node DMSID "SUPPORT OF FILE_ID.DIZ IN DMS-ARCHIVES"\n@{b}                            DMS_FILEID=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you define the complete path to @{b}DMSDescript@{ub} written by @{b}Re/Y\o/MsT@{ub}, i.e.\nDMS_FILEID=C:DMSDESCRIPT. If this Tooltype isn''t set mEGA-vIEW wouldn''t \nsearch for @{b}FILE_ID.DIZ@{ub} inside a DMS-archive. If you set this ToolType correct,\nmEGA-vIEW search for a Filedescription inside the archive after displaying\nthe informations and if found, it will be displayed to the user.\n \nBig @{"Thanx" LINK GREETS} must go to @{b}Remo/MST@{ub} for his @{b}DMSDescript@{ub}.\n@endnode\n\n@node ZIP "SUPPORT OF ZIP-ARCHIVES"\n@{b}                              ZIP_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you specify the complete path to @{b}(Un)ZIP@{ub}, i.e. ZIP_PATH=C:UNZIP. If this\nToolType is not set or the path is incorrect, ZIP-Support is disabled.\n\nIf you set it correctly, users have the ability to @{b}view/download@{ub} a file\ndirectly from a @{b}ZIP-Archive@{ub}. The function of this Support is exactly the same\nlike @{b}LHA-Support@{ub}. If a user has an equal or higher accesslevel as defined in\n@{"DL_LEVEL" LINK DLLEVEL}, he could download @{b}*ONE*@{ub} file from the archive, otherwise he could\nonly view it. For detailed information about the options look in Chapter @{"LHA" LINK LHA},\nas this two packers are both uses the same Selection-Routine.\n\n@{u}NOTE:@{uu} Make sure that you only use @{b}UnZIP@{ub} (or ZIP) upto @{b}V5.1@{ub}, coz this is the \n      first Version that allows you to specify an Extractpath for ''Unzipping''.\n      The second major enhancement from @{b}UnZIP@{ub} is the option to create a \n      Contents-List like @{b}LHA@{ub} (only Names), and therefor I could handle ZIP\n      in the same way...\n      If the ZIP-Support won''t work check out your Version from UnZip. I''ve \n      included the correct Version of UnZIP in this package.\n      All Versions lower than the one i''ve included (V5.1) @{u}WON''T WORK WITH@{uu}\n      @{u}mEGA-vIEW !!!!@{uu}\n@endnode\n\n@node ARJ "SUPPORT OF ARJ-ARCHIVES"\n@{b}                              ARJ_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you specify the complete path to @{b}ARJ@{ub}, i.e. ARJ_PATH=C:UNARJ. If this Tool-\ntype is not set or the path is incorrect, ARJ-Support is disabled.\n\nIf you set it correct, users have the ability to @{b}view@{ub} the contents or to @{b}test@{ub} \nthe desired ARJ-archive. If the user wants to test the archive, mEGA-vIEW calls\n@{b}ARJ@{ub} and redirects the Output to PIPE: to show you the testing in ''@{b}RealTime@{ub}''.\n\nIf the user selects ''@{b}VIEW@{ub}'' mEGA-vIEW reads in the contents of the ARJ-archive\nand display it to the user. \n\n@{u}NOTE:@{uu} It''s impossible to extract only one file with @{b}UnARJ V1.15@{ub}, which I used\n      to implement this function. If someone has a newer Version which allows\n      extracting of single files, please send it to me and I will rewrite the\n      code to make it possible to view single files (maybe with Downloading\n      like @{"LHA" LINK LHA} or @{"ZIP" LINK ZIP}). \n\nTo get in Contact with me take a look to chapter @{"ADRESS" LINK BBSADVERT1}...\n@endnode\n\n@node SHR "SUPPORT OF SHRINK-ARCHIVES"\n@{b}                            SHRINK_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you specify the complete path to @{b}SHRINK@{ub}, i.e. SHRINK_PATH=C:SHRINK. If \nthis Tooltype is not set or the path is incorrect, SHRINK-Support is disabled.\n\nIf you set it correct, users have the ability to @{b}view@{ub} the contents or to @{b}test@{ub}\nthe desired SHRINK-archive. If the user wants to test the archive, mEGA-vIEW \ncalls @{b}SHRINK@{ub} and redirects the Output to PIPE: to show you the testing \nin ''RealTime''...:)\n\nIf the user selects ''@{b}VIEW@{ub}'' mEGA-vIEW displays the contents of the selected\nSHRINK-archive via PIPE: .\n\n@{u}NOTE:@{uu} Like @{"UnARJ" LINK ARJ} it''s impossible to extract only one file with @{b}SHRINK V1.1@{ub}, \n      which I used to implement this function. If someone has a newer Version \n      with extracting of single files, please send it to me and I will rewrite \n      the code to make it possible to view single files (maybe with DL''ing\n      like @{"LHA" LINK LHA} or @{"ZIP" LINK ZIP}) from SHRINK-Archives. \n\nTo get in Contact with me take a look to chapter @{"ADRESS" LINK BBSADVERT1}...\n@endnode\n\n@node EXE "SUPPORT OF EXECUTABLES"\n@{b}                              EXE_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you specify the complete path to an @{b}EXEcutable Checker@{ub}, i.e. \nEXE_PATH=C:CHECKEXE. If this Tooltype is not set or the path is incorrect, \nEXE-Support is disabled.\n\nIf you set it correct, users have the ability to @{b}check AmigaDos-Executables@{ub}.\nI use @{b}CheckExe by Shagratt/LSD@{ub}, but you could use every checker which supports\nthe normal DOS-Errorcodes (0,5,10,20). This is important coz if your favourite\nchecker doesn''t return a valid errorcode (i.e. all went okay but Returncode=10)\nyou couldn''t use it with mEGA-vIEW. I''m checking the ReturnCodes before \ncontinueing the program, so make sure that the Returncodes are DOS-compatible.\nAlso your ExeChecker should accept the following Syntax:\n\n                          @{b}CHECKEXE <filename>@{ub}\n\nand make sure that your checker supports redirecting of the output,otherwise\nthere could be problems. I have only the CheckExe-Checker, so I couldn''t test\nit with others...\nIf you plan to use ur own coded checker, make sure that you write your outputs\nto Output(), otherwise the Redirection could make problems...!\n\nIf the selected File is packed,mEGA-vIEW shows you the used packer (if FileID-\nLibrary recognize the packer of coz..). If you set the ToolType @{"EXE_FILEID" LINK EXEID}\ncorrect, mEGA-vIEW searches for the @{b}Filedescription@{ub} inside the Executable after\ndisplaying the Checkerresult and if found asks you to view the description.\nIf you don''t specify the @{b}EXE_FILEID@{ub} ToolType correct, mEGA-vIEW return to the\nfileprompt after showing the Informations from the ExeChecker.\n@endnode\n\n@node EXEID "SUPPORT OF FILE_ID.DIZ IN AMIGA-DOS EXECUTABLES"\n@{b}                            EXE_FILEID=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you define the complete path to @{b}EXEDescript@{ub} written by @{b}Re/Y\o/MsT@{ub}, i.e.\nEXE_FILEID=C:EXEDESCRIPT. If this Tooltype isn''t set mEGA-vIEW wouldn''t \nsearch for @{b}FILE_ID.DIZ@{ub} inside an Executable. If you set this ToolType correct,\nmEGA-vIEW search for a Filedescription inside the executable after testing it.\nIf a description were found it will be displayed to the user. \n \nBig @{"Thanx" LINK GREETS} must go to @{b}Remo/MST@{ub} for his @{b}ExeDescript.@{ub}\n@endnode\n\n@node GUIDE "SUPPORT OF AMIGAGUIDE® - DATABASES"\n@{b}                            GUIDE_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you specify the complete path to @{b}GuideToDoc@{ub} by fOX/rEMEDY^aSPECT, i.e.\nGUIDE_PATH=C:GUIDE2DOCPROF. If this Tooltype is not set or the path is \ninvalid, Guide-Databases were displayed with all special commands used by \nAmigaGuide®.\n\nIf you set it correct, users have the ability to view Guidedatabases like an\nnormal Textfile without the annoying ''@{b}@@{ub}'' , ''@{b}{}@{ub}'' and other commands only used\nby AmigaGuide. To convert the desired Guide into an @{b}ANSI-File@{ub} you need the\nCLI-Tool Guide2DocProf. You could use this Tool to convert any Guide-Database \nto an normal @{b}ASCII/ANSI@{ub} file. The Syntax for this Tool is :\n\n                   @{b}GUIDE2DOCPROF <GUIDE>@{ub}\n\nWere @{b}<GUIDE>@{ub} is the Guide you want to convert. This Tool writes the\nconverted Guide to STDOUT, so if you want to convert i.e. the mEGA-vIEW-Guide\nto an ANSI-file, simply type this in your favourite shell:\n\n        GUIDE2DOCPROF >RAM:VIEWER.DOCS CWORK:DOCS/mEGA-vIEW.GUIDE\n\nThis will convert the Guide ''@{b}CWORK:DOCS/mEGA-vIEW.GUIDE@{ub}'' into an ANSI-File\nwhich will be created in ''@{b}RAM:@{ub}'' as ''@{b}VIEWER.DOCS@{ub}'' .\n\nmEGA-vIEW calls Guide2docProf and redirect the output to a file temporary \nstored in ur @{b}Temp-Dir@{ub} (Could be set via @{"TEMP_PATH" LINK TEMP} ).\n\nAfter displaying the converted ANSI-File will be deleted.\n\n@{u}NOTE:@{uu} As some sysops noted, I have changed this command and replaced the\n      old Program GuideToDoc by @{"ByteAndi/tRSi" LINK TRSIMEMBER} with the new one from fOX. The\n      reason is that ByteAndi''s tool crashes, if the selected Guide is too\n      big...to avoid crashes fOX has written the same program in 100% ASM to\n      give the maximum speed available...so don''t wonder, just enjoy the fast\n      speed of this Tool...\n\nYou could use (of course..:) your own converter, but make sure that your\nconverter returns the correct Errorcodes and supports the same call from\nCLI like Guide2docprof, otherwise it won''t work ! \nSee Chapter @{"CHECKEXE" LINK EXE} for more Informations...\n@endnode\n\n@node ZOO "SUPPORT OF ZOO-ARCHIVES"\n@{b}                             ZOO_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you specify the complete path to the ZOO-Packer, i.e. ZOO_PATH=C:ZOO.\nIf this Tooltype is not present or the path is invalid, Zoo-Archiv-Handling\nis disabled. If this TT is set correct, users have the ability to @{b}view@{ub} the\ncontents of ZOO-archives or to @{b}Test@{ub} the integrity of the desired archive.\n\nI''ve implemented this old packer only for one reason...I saw weeks ago a \nlittle Amiex-Arexx-Door, which includes this packer, and the Author writes\nas Description, that this Door could handle more packers than mEGA-vIEW...:)\nWell,I don''t know what this Author think about mEGA-vIEW, but this fuckin''\naREXX-script was a 5 minute work, and mEGA-vIEW was developed over 2 Years of\nhard work, and i don''t want to see such shit...so I decided to implement this\nold packer, too..\n@endnode\n\n@node ZOOM "SUPPORT OF ZOOM-ARCHIVES"\n@{b}                            ZOOM_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you specify the complete path to the @{b}ZOOMCHK-Program@{ub} written by Carnivore\nfrom BeerMacht, i.e. ZOOM_PATH=C:ZOOMCHK. Don''t use here the original ZOOM-\npacker, as this stupid packer don''t support the testing of archives without\ndisplaying any requesters !!! Always use only the ZOOMCHK program...\n\nIn fact that this packer isn''t much popular, I decided only to support the\ntesting...if my registered Users want more informations, I will implement\nthe ZOOM-Sourcecode (available in good PD-Boards) into mEGA-vIEW, but that\nwas not neccessary yet..\n@endnode\n\n@node WARP "SUPPORT OF WARP-ARCHIVES"\n@{b}                            WARP_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you define the path to WARPCK V1.4,i.e. WARP_PATH=C:WARPCK. Invalid\nPathnames to the checker disables this option...\n\nWARP is a DMS-alike Packer, but has the difference that WARP could pack \nnearly anything, maybe with copyprotections...:) I''ll want to support this\npacker, ''coz i found many archives packed with warp, but don''t know if they\nare ok to download...so with this support everyone is able to check warp-\narchives.\n@endnode\n\n@node LZX "SUPPORT OF THE NEW LZX-ARCHIVES"\n@{b}                            LZX_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you specify the path to LZX V1.00, i.e. LZX_PATH=C:LZX. Invalid Path-\nnames disables the LZX-Support. If set correct, users could @{b}view@{ub} the contents\nor @{b}test@{ub} the archive...\n\nNOTE: This packer is the newest one available on Amiga...it combins very \n      good packrates with a lightning speed, but has a disadvantage in\n      difference to LHA...it doesn''t support yet the handling of recursive\n      extracting of files from an archive...i.e. if you have a archive with\n      the following files:\n\n                           screens/node/SUXX\n                           SUXX\n                           BBS/AMIEX\n\n..lha is able to extract the file SUXX without entering the whole pathname,\nso if I want to extract it, i have to enter only SUXX, not SCREENS/NODE/SUXX,\nand the FIRST file named SUXX will be extracted...but LZX currently doesn''t\nsupport this feature, here you MUST define everytime the whole path...and\ntherefor I have currently only the viewing/testing supported...for my\nRegistered users will come in the near future an update, which allows them\nto simply extract files out of LZX-Archives, no matter if the files are\nin different pathes inside the archive...but again: such features are only \nfor @{b}REGISTERED USERS@{ub}, so if you want to use such features, please @{"REGISTER" LINK REGISTER}!\n@endnode\n\n@node TEMP "DEFINITION FOR A TEMPORARY WORKPATH USED BY mEGA-vIEW"\n@{b}                             TEMP_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you could enter an alternate path for @{b}temporary files@{ub} which are used for\nextracting and converting files. This Tooltype must not be set, coz the \nDefault-Setting is ''@{b}RAM:@{ub}''. If you have not enough free Memory you should set\nit to a valid AmigaDOS-Path, i.e. "TEMP_PATH=DH0:T/" . All packers and other\nTools controlled by mEGA-vIEW uses the path you defined here for extracting,\nconverting or whatever. \n\n@{u}NOTE:@{uu} When you want to use the Ram-Disk as Temppath, always enter ''@{b}RAM:@{ub}'' as\n      path coz the Ram-Disk is a dynamic Drive and therefor RAM: is always\n      @{u}full (0 Bytes free!!)@{uu} . To let it work I have included two checkroutines.\n      The first one checks normal ADOS-Devices like DF0:, HD0: etc. if there \n      is enough space on it. The second one will be activated only if you \n      enter @{b}RAM:@{ub} as path or disable this ToolType. In this case, mEGA-vIEW \n      will check your @{b}FREE MEMORY@{ub} instead of checking the free space on \n      the device. Other devices @{b}WOULDN''T BE@{ub} recognized, so @{b}T:@{ub} will be \n      checked as Device, not for FreeMem !!!!\n@endnode\n\n@node ACP "HOW TO FIND YOUR ACP-ICON TO LET IT WORK CORRECTLY"\n@{b}                              ACP_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you specify the path to your @{b}ACP-Icon@{ub}. Normally, it''s not necessary to\ndefine this ToolType, but some Sysops told me that mEGA-vIEW didn''t find ACP\ncoz they have no Searchpathes defined. If mEGA-vIEW couldn''t find your ACP,\nenter as <path> a valid AmigaDos-Path to your ACP.\n\n@{u}NOTE:@{uu} In difference to the Packer-ToolTypes, you must define the @{b}PATH ONLY!@{ub}\n      Don''t enter here for example BBS:ACP, coz this results in BBS:ACP/ACP !\n      If your ACP will be found in BBS:, enter ACP_PATH=BBS: . I''m using this\n      ToolType coz I have no BBS online and therefor it won''t be started via\n      WBStartup. mEGA-vIEW won''t found ACP without this ToolType, so I define\n      this ToolType with my BBS-Directory (ACP_PATH=BBS:) and all works. \n\nThis Tooltype is disabled by default (closed in Branches () ) and I recommend\nfirst to try it without this ToolType. If mEGA-vIEW reports that ACP couldn''t\nfound define it to the path were ACP could be found and all should work now.\n@endnode\n\n@node CALLERSLOG "ADDING COMMENTS TO CALLERSLOG"\n@{b}                             CALLERSLOG=<YES|NO>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you could choose if mEGA-vIEW should add a comment to the Callerslog when\na user tries to @{b}view/download a Restricted File@{ub}. By default, this Option is\ndisabled. To enable it, set the ToolType to @{b}YES@{ub}, i.e. CALLERSLOG=YES. For more\ninformations about @{b}Restricted Files@{ub} take a look to @{"RESTRICTED FILES" LINK RESTRICT}.\n\n@{u}NOTE:@{uu} If you run a multinodeboard it could happen that Amiex @{b}crashes@{ub} while\n      mEGA-vIEW adds the comment. @{u}This is not a bug from me !!@{uu} So don''t think\n      lame ''bout me when you see a guru while adding the comment. If this \n      happens, @{b}disable@{ub} this option (CALLERSLOG=NO) and you have no problems\n      anymore.\n      I don''t know what AmieX does when two programs want to add a comment\n      but this error should only happen on all AmieX-Versions @{b}<@{ub} 3.20 ... If\n      you have a higher Version from AmieX (of coz ONLY REG. Versions !) and\n      this error occurs, please @{"INFORM" LINK BBSADVERT1} me and i try to inform the Authors of\n      AmieX to fix this problem.\n\n@endnode\n\n@node ONLYCHECK "HOW TO CHOOSE BETWEEN VIEWING & TESTING"\n@{b}                           ONLY_CHECK=<accesslevel>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you define which accesslevel is needed to @{b}View files/archives@{ub}. If you\ndon''t specify this ToolType @{b}NO@{ub} user could view anything. If you set it correct,\ni.e. ONLY_CHECK=50, all users with an accesslevel @{b}>=@{ub} 50 could view files with\nthe full support of all packers. All users with an accesslevel @{b}<@{ub} 50 could only\n@{b}test archives@{ub}, @{b}viewing of textfiles is disabled@{ub}. Don''t need to write more bout\nthis option, I think...\n@endnode\n\n@node DLLEVEL "ACCESSLEVEL TO DOWNLOAD FROM LHA/ZIP-ARCHIVES"\n@{b}                           DL_LEVEL=<accesslevel>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nThis ToolType defines at which accesslevel a user could Download @{b}*ONE*@{ub} File\nfrom a @{b}LHA/ZIP-archive@{ub}. If this ToolType is not set or the user''s accesslevel\nis below the level defined here, the Downloadoption for @{b}LHA/ZIP@{ub} is disabled,\nand the user could only view files. If the user has an accesslevel equal or\nhigher then the one defined here then he could choose if he want to @{b}view@{ub} or\n@{b}download@{ub} a file from @{b}LHA/ZIP@{ub}. \n\n@{u}NOTE:@{uu} If a user has the Accesslevel for @{b}SYSOPVIEW@{ub} but not for Downloading,\n      then the Downloading is disabled, too. @{"SYSOPVIEWLEVEL" LINK SYSOPVIEW} doesn''t overwrite\n      this to avoid Leeching from CoSysOps or other people who wants to abuse\n      such a option.\n\nWhen a user could Download, mEGA-vIEW checks two things before starting the\nDownload. First, mEGA-vIEW checks if the user has already enough Uploadbytes\nto download the selected File. The check is simple but good: mEGA-vIEW take\nthe Bytes uploaded by the user and adds the Bytesize of the file he wants to \nDL. If the result is higher than the uploaded Bytes, mEGA-vIEW stops and \ninform the user that he has ''@{b}Exceeded Bytes Limit@{ub}''. If the user has \nenough Uploadbytes to Download the selected File, mEGA-vIEW checks if the \nuser''s DailyBytesLimit will be high enough to download the file. If both \nchecks are okay, mEGA-vIEW starts the ZModem-Transfer. \n\nIf the User has a disabled Ratio, the checkings were skipped and he could \nDownload a file no matter which Byte-Stats he has...\n\nAfter transfering the File, mEGA-vIEW adds the filelength of the downloaded \nfile to the users Dl-Stats and returns to the Fileprompt.\n@endnode\n\n@node SYSOPVIEW "DEFINITION FOR SYSOPVIEW"\n@{b}                       SYSOPVIEWLEVEL=<accesslevel>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you could define at which level users could view files @{b}outside@{ub} the BBS-\npathes, i.e. the user could enter ''@{b}V DOCS:mEGA-vIEW.GUIDE@{ub}''. This ToolType \noverrides the @{"ONLY_CHECK" LINK ONLYCHECK} access. \n\nOf course all checkings for restricted Files will be made before displaying\nthe selected File to the user. If you don''t specify it @{b}NO@{ub} users could view\nanything outside the regular BBS-Pathes. I have defined this Tooltype to the\naccesslevel of my Cosysops so they could view private files as long as they\nwere not marked as restricted.\n\nTo use the @{b}SYSOPVIEWCOMMAND@{ub} I''ve included an icon called ''@{b}VS@{ub}'' which let''s you\nuse mEGA-vIEW similar to the @{u}original internal SYSOPVIEW-Command@{uu}. This Icon\nis not neccassary to use the @{b}SYSOPVIEW@{ub}, but made things easier for you...:)\n\n@endnode\n\n@node RESTRICT "INFORMATIONS ABOUT RESTRICTED FILES"\n                         @{b}RESTRICTED FILES@{ub}\n\nAmieX has the ability to @{b}protect@{ub} Files against @{b}Downloading/Viewing@{ub} by adding\na FileComment (RESTRICTED) to those files. They are defined in the @{b}ACP-Icon@{ub}\nwith the ToolType @{b}RESTRICT.x=<file>@{ub}. When you start your BBS all Files defined\nas Restricted in ACP were marked as Restricted in the FileComments. If you want\nto protect other files not defined in ACP then add a FileComment to this file\nwith the DosCommand @{b}FileNote@{ub}. Take a look to your Dos-Manual for a detailed \nCommandsyntax.\n\nEverytime a user tries to @{b}view/download@{ub} such files mEGA-vIEW informs the user\nthat this File is restricted and if you have @{"CALLERSLOG=YES" LINK CALLERSLOG} a Comment would be\nadded to your Callerslog with the complete Filename of the File the user tries\nto view.\n\n@endnode\n\n@node GREETS "DA GREETINGSLIST..."\n\n@{b}Greetings fly to...@{ub}\n\nByteAndi/tRSi      - For many help\n\nRemo/MST           - For his great Programs ''EXEDESCRIPT'' & ''DMSDESCRIPT''..\n\nBloodRock/SDC      - Your FileID.Library is the BEST!\n\naRGoN/dTL          - Traden Roolez ne war Oldae ? :)\n\ndEATH aNGEL/sDC    - Cewl testing...you''re the best Betatester..grins..\n\nbYSiS/iNDY         - wELCOME iN tHE mODEM-sCENE...:)\n\neCS/tRSi           - wait for the Guide-Viewing...:) it''s in work...\n\n ...and of coz all BETA-Testers, TRSi & NEON-Members all around the Globe...\n\n@{b}PS: THE ONLY WAY TO MULTITASK ON MS-DOS IS TO RUN IBeM TWICE ON AN AMIGA!@{ub}\n@endnode\n\n@node REGISTER "HOW TO GET REGISTERED USER"\n\n@{u}Registration@{uu}\n\nAs I said before, I declared all my tools as SHAREWARE, meaning that you\nhave to pay a registration fee to become the newest versions available.\n\nThe reason why I declare them as Shareware is simply...take a look to the\nhistory-file, and you could see how many hard work i have done on this\ntool...I don''t believe that anyone will work simply for nothing, and there-\nfor I want money for my work.....\n\nThe Registration fee costs 30,-DM, and of course you have to pay this\nonly once ! After paying, you''ll become access to my Register-Door, allowing\nyou to leech everytime the newest versions...I''ll recommend to pay this,''coz\nI will only release all of my programs one time, all other updates are only\nfor registered Users, including all userwishes and other things, which should\nadded to mEGA-vIEW or other tools comming from me.\n\nTo register yourself, call our @{"WHQ" LINK BBSADVERT1} and leave a mail to SieGeL/tRSi \nthat you want to become registered User...\n\n@endnode\n\n@node TRSIMEMBER "ALL MEMBERS IN (tRSi/X-iNNOVATiON)"\n                           .                                         \n         .\n         :                 :\n - - -- -+- -- -- - -- - - + - --    /·/\n         :                 :        /·/\n         !                 :       /·/\n         ¡       _________/\\______/\\/   ____/\\_________\n         :       \\_  __  _  \\_ ____ \\__/    __________/       .\n         `- -- - --\\_/    \\  /   _/ _/____  \\  \\/free!\\       .\n                   _/      \\/   /    \\_   \\_    \\_     \\_     :\n                   \\_____   \\___\\   __/_____     /  ____/- - -+- - -\n                    \\___\\____/\\__\\__/\\____/\\____/____/_/      !\n                         \\___\\/   \\_\\/    \\/___/____/         ¡\n                           /·/  (/X-iNNOVATiON)   :           :\n                          /·/                     `- -- - -- -''\n                         /·/    ·M·E·M·B·E·R·S·\n\n                    ----------------------------------\n                       ByteAndi (tRSi/X-iNNOVATiON)\n                         SieGeL (tRSi/X-iNNOVATiON)\n                            Spy (tRSi/X-iNNOVATiON)\n                        Dr.Dre! (tRSi/X-iNNOVATiON)\n                    ----------------------------------\n               if you wanna join us so get in touch with\n\n                           one of our members.\n\nIf you want to order a tool, give us Bugreports, hints and tips for this or\nother tools comin'' from (tRSi/X-iNNOVATiON), try to contact us on any TRSI \nBoard Worldwide, or try one of the following (but both 100% LEGAL ONLY!) :\n\n               @{"pUNISHMENT iNC. - WHQ & bETA/rEGISTER sITE" LINK BBSADVERT1}\n\n               @{"   pARALYSIS    - GHQ & bETA/rEGISTER sITE" LINK BBSADVERT2}\n@endnode\n\n@node BBSADVERT1 "HOW TO CONTACT US"\n   _____________  __________               /\\   \n  |     __     /__\\__      /___________   /  \\             _____\n  |   ________/    /      /_\\____      \\_//   \\___________|_____|_______\n  |     |  \\      /      /      /      _//     \\    ______________      \\_\n  l_____|   \\___________/______/       \\_______/\\______   \\_    l/       /\n                              \\________/      /____________/____/       /\n                                       _________________       \\_______/     \n     ______ /\\____ ____________ _______\\______   ______/\n    /      /_      \\    __    /_\\_____      \\_    |\n  _/      \\/______/   _______/\\      /       /    |    · PUN¡sHMeNT ¡NC. ·\n  \\________\\    _/_____________\\____/  Mo!  /_____|\n                /                  \\_______/\n                                           /\\  ______________  ___________   \n     1oo% LeGaL sTUFF oN aM¡Ga^PC         /  \\_\\_______      \\_\\    _____/___\n                                         //   \\       /       /     /       /\n     RUNN¡NG oN a4ooo/4o · V.FasT      _//     \\_____/       /_____________/ \n                                       \\________/   \\_______/             \n                                                                             \n    TR¡sTaR & ReD seCToR ¡NC. (/X·¡NNoVaT¡oN) WoRLD HeaDQUaRTeR              \n                                                                             \n    aND eTH¡C D¡sT s¡Te   [> +49-(o)-3o-694-84-7o <]   sYsoP: s¡eGeL/TRs¡\n@endnode\n\n@node BBSADVERT2 "HOW TO CONTACT US"\n       ____                                                                  \n    ___\\  /______________________________________________________________    \n   /   \\\//                                                              \\   \n  /     \\/ -[ THe BeST eQUiPPeD PuBLIC DoMAIN BoaRD IN BeRLIN ]-          \\  \n /   -[ WiTH 4 GReaT U.S.ROBOTICS V.FAST CLASS MoDeMS WiTH FLaSH-RoMS ]-  \\ \n/                                                                           \\\n\\                        -- -[ SYNDIC/\\TE WHQ ]- --                         /\n \\   _____  _____    _____   _____  __      ___ __  _____   ___ _____      / \n  \\ /  _  \\/  _  \\  /  _  \\ /  _  \\/  |___ /   |  \\/   __)_/ __|   __)_   /  \n   /   |   \\  _   \\/   |  //   _   \\  |   \\\\_____  \\___    \\¯  |___    \\ /   \n  /   _____/  |    \\_ __   \\_  |    \\ |    \\   |    \\|      \\  | |      \\    \n  \\____| \\____|    /___|    /__|    /___   / _______/___    /__|____    /    \n      \\       l___/    l___/   l___/  \\___/___/  [ViC!]\\___/       \\___/     \n       \\                                                             /       \n        \\SYSTeM CHieFS: SPY/TRSi,ARTHuR DeNT,PHaNToM,Cat,JTC,big-rat/        \n         \\                                                         /         \n          \\   1: +49(0) 30 721 6071 USR DuAL STaNDaRD V.34 28.8   /          \n           \\  2: +49(0) 30 721 6072 USR DuAL STaNDaRD V.34 28.8  /           \n            \\ 3: +49(0) 30 721 6073 USR DuAL STaNDaRD V.34 28.8 /            \n             \\4: +49(0) 30 722 6065 USR DuAL STaNDaRD V.34 28.8/             \n              \\                                   /\\          /              \n               \\_________________________________//\\\\________/               \n                                                 /__\\\n\n                           SUPPORTS ONLY PD-/SHAREWARE !\n@endnode\n\n@node TODO "WHAT I PLANNED TO IMPLEMENT IN FUTURE RELEASES"\n\nSome wishes are currently not implemented, coz this features are only for\nregistered Users...\n\n- Better displaying of the contents from LHA/ZIP-archives, incl. date,bytes\n  and other informations.\n\n- Sysopcommands on LHA/ZIP - archives, allowing you to delete/add files.\n\n- Downloading/Viewing more than only one file from an archive.\n\n- Hydra-Support for Downloading\n\n- Viewing of Guides in two ways, ANSI & GUIDE...:)\n\n- maybe sometimes the support of the datatypes.library (WB/Kick 3.0+!)\n\n- special Version for Tempest-BBS-Systems.\n\n- better LZX-Handling like LHA & ZIP (Extracting, Downloading,etc.)\n\n@endnode\n','\n',char(10)),NULL,'auto-added',230895,1,0,NULL,NULL,'trsi_m25','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_mad','TRSI-MAD.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-MAD.LHA','MorphADD','XIM','MorphADD',NULL,'Icarus/TRSi','TRSI','|  |___) (___  : .-- |  |   \ ____) l___________________ |                                      |',replace('_ _____ ___   ___\n    |  |___) (___  :\n.-- |  |   \ ____) l___________________\n|                                      |\n| MorphADD by Icarus/TRSi Version 1.05 |\n| ==================================== |\n| The adder for  TXT,  NFO & DOC files.|\n| Creates  unstrippable  adverts (YES!)|\n| For  all  BBS-systems  or  CLI usage.|\n| Check  this  out  and  be  surprised.|\n`--------------------------------------''\n\n','\n',char(10)),'MorphADD.guide',replace('@database MorphADD.guide\n@master MorphADD.doc\n\n@author Icarus of Tristar & Red Sector Inc.\n@(c) 1996-97 TRSi GmbH\n@remark May only be distrbuted with MorphADD\n\n@$VER: MorphADD.guide 1.05 (24.12.96)\n\n@node Main "MorphADD Version 1.05 AmigaGuide Documentation"\n\n@{b}                                 - INDEX -@{ub}\n\n@{"CHAPTER 1 ................................................. Whats MoprhADD?" link WhatsDC}\n@{"CHAPTER 2 .................................... All special ''Morph-Commands''" link Options}\n@{"CHAPTER 3 .................................................. Morph-Examples" link example}\n@{"CHAPTER 4 ........................................ SYSOPS: How to install??" link Install}\n\n@{"                            About The Author/Greets                        " link Author}\n\n@{b}                 MorphADD Version 1.05 (c) Icarus/TRSi 1996-97 @{ub}\n\n@endnode\n\n\n@node WhatsDC "What is MorphADD?"\nWhat is MorphADD?\n\n@{fg highlight}MorphADD@{fg text} is a new special Advert-Adder for TXT, NFO & DOC-Files...\nWhat is so special about MorphADD? - Well, you can edit your adverts with\nsome special commands to "protect" your adverts against STRIPPING...\nIn fact, every advert looks a little bit different, thats the magic behind\nMorphADD... :)\n\nIt is compatlble with all the BBS-systems out there you even can use it\nfrom CLI.\n\nNow read on, how to edit your adverts to let them morph in the next chapters!\n\nSo long, Icarus/TRSi\n\n@endnode\n\n@node Example "Some examples..."\n\n\nFOR COMMAND ¥R:\n===============\n\nBEFORE:\n-------\n----------------------------------------\n\nCALL THIS BBS TO GET THE NEWEST STUFF...\n\n----------------------------------------\n\nCOMMAND:\n--------\n----------------------------------------\n¥R\nCALL THIS BBS TO GET THE NEWEST STUFF...\n¥R\n----------------------------------------\n\nAFTER (IN THE ADD):\n-------------------\n----------------------------------------\n\n\nCALL THIS BBS TO GET THE NEWEST STUFF...\n\n\n----------------------------------------\n\nOR:\n---\n----------------------------------------\n\nCALL THIS BBS TO GET THE NEWEST STUFF...\n\n\n----------------------------------------\n\n\nFOR COMMAND ¥T...¥\n==================\n\nBEFORE:\n-------\n----------------------------------------\n\nCALL THIS BBS TO GET THE NEWEST STUFF...\n\n----------------------------------------\n\nCOMMAND:\n--------\n----------------------------------------\n\n¥TCALL THIS BBS TO GET THE NEWEST STUFF...¥ <-- DO NOT FORGET TO MAKE THIS!!\n\n----------------------------------------\n\nAFTER (IN THE ADD):\n-------------------\n----------------------------------------\n\ncAll ThIs BbS tO geT tHe NeWEsT sTuff...\n\n----------------------------------------\n\nOR:\n---\n----------------------------------------\n\ncALL tHiS bBS TO gET ThE NEWEsT STuff...\n\n----------------------------------------\n\n\nFOR COMMAND ¥E...¥\n==================\n\nBEFORE:\n-------\n----------------------------------------\n\nCALL THIS BBS TO GET THE NEWEST STUFF...\n\n----------------------------------------\n\nCOMMAND:\n--------\n----------------------------------------\n\n¥ECALL THIS BBS TO GET THE NEWEST STUFF...¥ <-- DO NOT FORGET TO MAKE THIS!!\n\n----------------------------------------\n\nAFTER (IN THE ADD):\n-------------------\n----------------------------------------\n\nÇÆl£ TH¡$ BB$ Tø GET THE NEWEST STµFF...\n\n----------------------------------------\n\nOR:\n---\n----------------------------------------\n\nCA£L TH¡S BBS TO GET THE NEWE$T $TUFF...\n\n----------------------------------------\n\n\nFOR COMMAND ¥S:\n===============\n\nBEFORE:\n-------\n----------------------------------------\n\nCALL THIS BBS TO GET THE NEWEST STUFF...\n\n----------------------------------------\n\nCOMMAND:\n--------\n----------------------------------------\nCALL ¥STHIS ¥SBBS ¥STO ¥SGET ¥STHE ¥SNEWEST STUFF...\n----------------------------------------\n\nAFTER (IN THE ADD):\n-------------------\n----------------------------------------\nCALL  THIS  BBS TO  GET THE  NEWEST STUFF...\n----------------------------------------\n\nOR:\n---\n----------------------------------------\nCALL THIS  BBS TO GET THE  NEWEST STUFF...\n----------------------------------------\n\n\n=======================\nWHAT YOU CAN''T DO!!!!!!\n=======================\n\nIn this version of MorphADD you can''t "mix" the commands...\n\ne.g. ¥E¥T TEST-TEST :))¥\n     ^^\nor:\n\ne.g. ¥E HELLO ¥SGUYS ¥\n              ^^\n\nBut i will fix this immediately... ;)) so no panic...\n\n\n@endnode\n\n@node Options "The magic commands..."\n\nAll the commands begin with the key "¥" (SHIFT+LEFTALT+Z) okay...\n\n\nInsert Return\n=============\n\n¥R = This will insert a RETURN ($A) RANDOMLY...\n\n\nChange UPPER-LOWER-CASE\n=======================\n\n¥T ... ¥ = This will replace the letters between ¥T and ¥ randomly as\n           lower or upper-case...\n\nChange Elite\n============\n\n¥E ... ¥ = This will replace the letters between ¥E and ¥ randmoly as\n           elite-style.. (e.g. replaces o with ø) etc.. the usual stuff!\n\nInsert Space\n============\n\n¥S = This will insert a SPACE ($20) randomly ...\n\n\n\nI know, a little bit confusing... see some examples on chapter 3 :))\n\n@endnode\n\n@node Install "Installation"\n\nTo install this wonderful programm you must do the following...\n\nCopy the main-executable (MoprhADD) into the c:-directory.\nThen copy the files "Morph.front", "Morph.back" & "Morph.user" to the\ns:-directory...\n\nNOW, edit the files you have copied into your s:-directory with your\nfavourite text-editor...\n\nThe file "Moprh.front" is the FRONT-ADVERT...\n\nThe File "Morph.back" is the BACK-ADVERT...\n\nThe File "Morph.user" is your Username.. enter what ya want but only 29\nchars...\n\n\n(SEE THE EXAMPLES, TOO)\n\n@endnode\n\n\n@node Author "The Author"\n\nThe author is @{b} ICARUS OF TRISTAR AND RED SECTOR INC. @{ub}\n\nIf you want to contact me (especially lawyers) just write a nice letter to\nthis nice address:\n\nBruce Dickinson\n22 Acacia Avenue\nLondon - U.K.\n\n\nOr just go to one of the next IronMaiden-Concerts and try to find me\nI have a dragon tatoo on my right arm.. good luck ;))))\n\n\n\nUP THE IRONS...\n\n\nMy Maiden favourites:\n---------------------\n\nLP                    |             TITLE\n\nFame                    Running Free\nFame                    Strange World\nFame                    Iron Maiden\nFame                    Phantom Of The Opera\n\nSomewhere In Time       Caught somewhere in time\nSomewhere In Time       Wasted Years\nSomewhere In Time       Heaven can wait...\nSomewhere In Time       the l. o. t. l. d. r.\n\nNumber Of The Beast     The Prisoner\nNumber Of The Beast     Number Of The Beast\nNumber Of The Beast     22 Acacia Avenue (Charlott the Harlott 2)\nNumber Of The Beast     Hallowed Be Thy Name\n\nPiece of Mind           Where Eagles Dare\nPiece of Mind           Flight of the Icarus\nPiece of Mind           Still Life\nPiece of Mind           Sun and Steel\n\nPowerslave              Aces High\nPowerslave              2 Minutes to Midnight\nPowerslave              Flash Of The Blade\nPowerslave              The Duellists\nPowerslave              Powerslave\n\n7th Son Of A 7th Son    Can I Play With Madness?\n7th Son Of A 7th Son    The Clairvoyant\n7th Son Of A 7th Son    Only The Good Die Young\n7th Son Of A 7th Son    Moonchild\n\nFear of the Dark        Be Quick Or Be Dead\nFear of the Dark        Holy Smoke\n\nThe X-Factor            Sign Of The X\nThe X-Factor            Men On The Edgde\nThe X-Factor            Lord Of The Flies\nThe X-Factor            2 AM\nThe X-Factor            Judgement Of Heaven\n\n\nWasted-Years-Single     Reach Out (Corell)\n                        The Sheriff from HUDDERSFIELD\n                        That Girl\n\n\nGREETINGS ARE GOING TO:\n-----------------------\n\nAll I know...\n\n\n@endnode\n\n','\n',char(10)),NULL,'auto-added',12206,2,0,NULL,NULL,'trsi_mad','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_mc5','TRSI-MC5.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-MC5.LHA','LZX','XIM','Zip',NULL,NULL,'TRSI','\      _______  \   _______)---------------. :\__/  \|  __/  /___   \|  \ SieGeL/tRSi oF: ¦  /    \  \    \   \   \   \ /X-iNNOVATiON¦',replace('____________________________________________\n\      _______  \   _______)---------------.\n:\__/  \|  __/  /___   \|  \ SieGeL/tRSi oF:\n¦  /    \  \    \   \   \   \ /X-iNNOVATiON¦\n| /______\__\____\______/____\  PRESENTS   |\n)--mRV-------------------------------------(\n|mULTI-cHECK V1.5 - ADDER/sTRIPPER/cHECKER!|\n|                                          |\n|sUPPORTS LZX,LHA,ZIP & TXT, aUTODETECT oF |\n|  BBS-sYSTEM uSED (FAME aND /X) aND mANY  |\n|      oTHER fEATURES - cHECK iT oUT !     |\n`------------------------------------------''','\n',char(10)),'mULTI-cHECK.guide',replace('@database mULTI-cHECK\n@master EWORK:mULTI-cHECK/mULTI-cHECK_eng.guide\n@$VER: mULTI-cHECK.guide 1.5 (11-21-96)\n@author "SieGeL/tRSi"\n@(c) "Copyright © 1996-97 (tRSi-iNNOVATiONs)"\n@wordwrap\n@index HeddleyAutoIndex\n@remark Created with Heddley v1.1 (c) Edd Dumbill 1994\n@remark Heddley Bugs Fixed with FixHeddley 1.2 (c) 1995 by David Zvekic\n\n@node "Main" "mULTI-cHECK - Archive-Checker for FAME & Amiex Systems"\n\n    @{b}:::.@{ub}       ________  _________ ____\n    @{b}::::@{ub}      |  -___ /_(____-----(____)\n    @{b}`::: ...@{ub}  `---'' `---^---------^----^\n     @{b}:::::::''@{ub}                \n    @{b}.::::''      ..@{ub}       .@{fg fill}ami express@{fg text}.       .@{b}presents in 1997@{ub}.\n   @{b}::::::.     `:::::...@{ub}\n    @{b}`'' :::        ```:::::..@{ub}  .@{fg fill}fame@{fg text}.          .@{b}mULTI-cHECK  v1.5@{ub}.\n       @{b}`:::            ``::::@{ub}\n        @{b}`:::          ..::::''@{ub}                 .@{b}for FAME & /X BBS@{ub}.\n         @{b}`:::.    ..:::::''''@{ub} __ _ _ _ _ ___ _ _ ___ ___  _ ___ _ _\n          @{b}`:::::::::::''''@{ub}   (__) ` | ` | - | / | - (_ _)(_) - | ` |\n            @{b}``::::''''@{ub}       ^--^-''-^-''-^---^---^-''-''`-'' ^-^---^-''-''\n\n                          wRITTEN bY SieGeL/tRSi\n\n                         @{"COPYRIGHT & DISTRIBUTION" link "COPYRIGHT" 0}\n                         @{"INTRODUCTION & FEATURES " link "INTRODUCTION" 0}\n                         @{"INSTALLATION TO YOUR BBS" link "INSTALLATION" 0}\n                         @{"  USAGE AND PARAMETERS  " link "USAGE" 0}\n                         @{"  CREDITS & GREETINGS!  " link "CREDITZ" 0}\n\n          aNOTHER pRODUCT oF tHE "REAL" (tRSi-iNNOVATiONs) tEAM !\n\n@endnode\n\n@node "COPYRIGHT" "Copyright Informations for mULTI-cHECK"\n@{b}DISTRIBUTION:@{ub}\n\n Following notice applies to product called "mULTI-cHECK" and everything \n in its original distribution archive.\n\n * Program is published by SieGeL/tRSi under concept of @{"RegisterWare" link "REGISTER" 0}.\n   No warranties are given. I take no responsibility of any possible\n   harm this product could do to your amiga system (not that it would but..).\n\n * You may NOT sell this product without permission from me.\n\n * Program must not be altered in any way.\n\n * Package must always be kept intact when spreading.\n\n * It is OK to include this on CD-ROM & disk collections and distribute\n   it through aminet and other such ftp''s and file nets.\n\n Above mentioned rules apply to mULTI-cHECK PUBLIC VERSION and other texts or\n libraries within the original package versions 1.5 and newer unless \n otherwise stated. It''s of course @{b}*NOT*@{ub} allowed to distribute the registered\n Versions in any way !\n@endnode\n\n@node "INTRODUCTION" "Some informations about mULTI-cHECK"\n          @{b}INTRODUCTION TO mULTI-cHECK OR WHY ANOTHER FILECHECKER ?@{ub}\n\n Well, the most important thing why I wrote this Tool is the fact that\n currently no other filechecker supports the @{"FAME-System" link "FAME" 0} (which I''m running!)\n and therefor the adding of uploader etc. was not possible...so I decided to\n write my own one, but not only for @{fg fill}LZX@{fg text} (which was the first archiver I''ve\n supported)...I don''t like many thousands of checkertools and therefor this\n mULTI-cHECKER is able to @{fg shine}check/add/strip@{fg text} from @{fg shine}LZX@{fg text}, @{fg shine}LHA@{fg text} and @{fg shine}ZIP@{fg text} archives,\n also Textfile checking with adding of adverts are possible.\n\n @{u}Other nice functions are:@{uu}\n\n - Supports @{b}LZX@{ub}, @{b}LHA@{ub} & @{b}ZIP@{ub} Archives for @{b}testing/adding/stripping@{ub}...\n\n - V1.3+ supports now also @{b}Textfile adding with Header/Tailer !@{ub}\n\n - Full @{b}argument-driven@{ub}, no external configfile needed!\n\n - Supports @{b}FAME@{ub} & @{b}Amiex@{ub} systems (but not needed to let it work)\n\n - Is able to add @{b}Uploadername@{ub}, -@{b}location@{ub}, @{b}node@{ub}, @{b}date@{ub} & @{b}time@{ub} of upload to\n   the advert/header/tailer being added....\n\n - Supports @{b}stripping via external Textfile@{ub}\n\n - Very small and fast...:)\n\n If you now interested in this checker, simply take a look to the chapter\n @{"Installation" link "INSTALLATION" 0} for further informations...\n@endnode\n\n@node "INSTALLATION" "Installation to your BBS-System of mULTI-cHECK"\n                       @{b}INSTALLATION OF mULTI-cHECK@{ub}\n\n Best way to copy all neccessary files is to use the Installerscript supplied\n with the release archive...if you want to copy it by hand, follow these few\n steps:\n\n @{b}1.@{ub} Copy @{fg shine}mULTI-cHECK@{fg text} to your @{fg fill}c:@{fg text} directory or to any other directory of your\n    choice.\n\n @{b}2.@{ub} Copy the @{fg shine}documentation@{fg text} to your docs-directory or any other directory...\n\n @{b}3.@{ub} Copy the supplied sample files @{"ADVERT.TXT" link "SAMPLE_ADVERT" 0} and @{"STRIPFILE.TXT" link "SAMPLE_STRIPFILE" 0} to a\n    directory of your choice. You may also copy @{fg shine}HEADER.TXT@{fg text} and @{fg shine}TAILER.TXT@{fg text} as\n    examples how to use the TextAdding feature!\n\n Now you have to edit the files @{b}ADVERT.TXT@{ub} and @{b}STRIPFILE.TXT@{ub} to your needs.\n ADVERT.TXT could have some special symbols which are described @{"HERE" link "SAMPLE_ADVERT" 0}.\n Also the HEADER.TXT file could contain these symbols, they are exactly the\n same like inside the ADVERT.TXT file. See there for further informations.\n The STRIPFILE.TXT should contain all filenames (!), you wish to kill from \n the archive. Please note that it''s on you to write only legal characters \n into this file, as mULTI-cHECK performs @{b}*NO*@{ub} checkings on these\n names !!! So make sure that you don''t use wildcards or other critical \n filenames inside this @{"stripfile" link "SAMPLE_STRIPFILE" 0}, otherwise it could happen that \n you gain only empty archives or other strange things...you''ve been warned!\n\n At least, you have to built in the checker to your BBS-System.\n\n\n                   @{b}--------- BBS-INSTALLATION ---------@{ub}\n\n\n@{u}AMIEX-SYSOPS:@{uu}\n\n Create four icons inside your BBS:FCHECK/ directory called\n\n                            @{fg shine}LZX.INFO@{fg text}\n                            @{fg shine}LHA.INFO@{fg text}\n                            @{fg shine}ZIP.INFO@{fg text}\n                            @{fg shine}TXT.INFO@{fg text}\n\n and edit the Tooltypes like shown below:\n\n  CHECKER = C:mULTI-cHECK\n  OPTIONS = @{"(CLICK HERE FOR OPTIONS)" link "USAGE" 0}\n    STACK = SAME\n PRIORITY = 1\n  ERROR.1 = Archive Corrupt!\n\n Repeat this steps for all four icons (or only the file-types you want\n to use mULTI-cHECK for)...the Options are described in the @{"Parameters" link "USAGE" 0}-\n chapter, see there for further informations !\n\n Now you are ready with the installation.\n\n\n@{u}FAME-SYSOPS@{uu}:\n\n Start the System-Editor and go to FileCheckers. Now edit the @{b}LHA@{ub}, @{b}ZIP@{ub}\n and TXT configurations like shown below:\n\n  CHECKER PATH = C:mULTI-cHECK\n    STACK SIZE = 4096\n      PRIORITY = 1\n       OPTIONS = @{"(CLICK HERE FOR OPTIONS)" link "USAGE" 0}\n       ERROR 1 = Archive Corrupt!\n\n For @{b}LZX@{ub}, you have the create a new configuration with the @{fg shine}NEW@{fg text} button, enter\n LZX as extension, fill in the fields and save this configuration.\n\n Of course you have to switch the checker(s) to @{b}ON@{ub} to let it work :)\n\n That''s all for installing it to @{"FAME" link "FAME" 0}, now you are ready to use it. See\n Chapter @{"Parameters" link "USAGE" 0} for further informations about the Options used by\n mULTI-cHECK.\n@endnode\n\n@node "USAGE" "How to use it and list of Parameters"\n                   @{b}LIST OF PARAMETERS USED BY mULTI-cHECK:@{ub}\n\n As mULTI-cHECK is fully commandline-driven, various parameters exists to\n control mULTI-cHECK. The command-template for mULTI-cHECK is:\n\n      @{fg shine}ADVERT/K,BBS-PATH/K,STRIPFILE/K,PACKER/K/A,TYPE/K/A,FILENAME/A@{fg text}\n\n Click @{"HERE" link "USAGE_EXAMPLES" 0} for some examples how to start mULTI-cHECK.\n\n @{u}Explanation of Parameters:@{uu}\n\n mULTI-cHECK uses standard OS 2.0++ Parms and their keywords, so please take\n a look to your AmigaDOS-Manual for further informations about the templates\n of programs etc.\n\n    @{fg shine}@{bg shadow}ADVERT/K@{fg text}@{bg back}  -  Specify here the Filename to the advert which should be\n                 added to the archive...click @{"HERE" link "SAMPLE_ADVERT" 0} for additional infos\n                 about the format of adverts used by mULTI-cHECK.\n\n                 @{b}@{fg fill}I.E.:@{ub}@{fg text} @{fg fill}ADVERT=S:MYADVERT.TXT@{fg text}\n\n                 will add @{fg fill}S:MYADVERT.TXT@{fg text} after parsing it for any special\n                 commands to the archive given as FileName.\n\n                 When using the Textmode, you have to enter here the path to\n                 the HEADER file which should be added above the original\n                 textfile.\n\n                 This Parameter is optional!\n\n    @{fg shine}@{bg shadow}TAILER/K@{fg text}@{bg back}  -  This Parameter is only required when using mULTI-cHECK in\n                 Textmode. Here you may specify the Tailer file which will\n                 be added below the textfile. In all other modes this \n                 parameter is not required.\n\n  @{fg shine}@{bg shadow}BBS-PATH/K@{fg text}@{bg back}  -  If you are using mULTI-cHECK with a BBS, enter here the\n                 main path to your BBS System, i.e. @{fg fill}BBS-PATH=BBS:@{fg text} or use\n                 @{fg fill}BBS-PATH=FAME:@{fg text} . Please notice that mULTI-cHECK is able to\n                 detect itself which System you are running...if you don''t\n                 specify this Option, but using the Uploader-Name etc.\n                 features inside an advert, mULTI-cHECK will write\n                 @{b}"-+- The SysOp -+- "@{ub} and @{b}"- Local Upload -"@{ub} for the name &\n                 location fields, otherwise all needed informations where\n                 extracted from the online''s user.datas and written to your\n                 advert.\n\n                 This Parameter is optional!\n\n @{fg shine}@{bg shadow}STRIPFILE/K@{fg text}@{bg back}  -  Here you have to enter the path to a ascii-file containing\n                 all filenames you want to strip off the archive, i.e. you\n                 have a file in @{fg fill}S:@{fg text} called @{fg fill}strips@{fg text} containing:\n\n                                @{i}display.me@{ui}\n                                @{i}fuck_it.txt@{ui}\n                                @{i}werbung.txt@{ui}\n\n                 then you enter @{fg fill}STRIPFILE=S:STRIPS@{fg text} and all filenames listed\n                 inside this file where deleted from the archive. Look to\n                 the Chapter @{"Example-Stripfile" link "SAMPLE_STRIPFILE" 0} for further informations.\n\n                 @{u}NOTE:@{uu} If you are stripping from a @{fg shine}@{bg fill}ZIP-Archive@{fg text}@{bg back}, please don''t\n                       wonder about errormessages comming from ZIP, these\n                       errors are normal, as ZIP prints out all filenames,\n                       which couldn''t be found inside the archive to delete\n                       them...dunno know why this behavour exists, I can''t\n                       suppress this warnings and therefor you have to live\n                       with this :(\n\n                 This Parameter is optional!\n\n    @{fg shine}@{bg shadow}PACKER/K@{fg text}@{bg back}  -  Here you must enter the path to the checker you want to use.\n                 I''ve tested it with @{b}LHA V1.50@{ub}, @{b}LZX V1.20@{ub} and @{b}Zip V2.0.1@{ub} but\n                 as I only uses standard commands and therefor there should\n                 be no problems when using different versions. To specify\n                 the packer for @{fg fill}LZX@{fg text}, you could write for example:\n\n                                     @{fg fill}PACKER=C:LZX@{fg text}\n\n                 For the Textfile option this parameter is not required and\n                 you may leave it away in Textmode.\n\n    @{fg shine}@{bg shadow}TYPE/K/A@{fg text}@{bg back}   - Enter here the type of packer which is used...currently\n                 there exists 3 types:\n\n                                @{fg shine}LHA LZX ZIP TXT@{fg text}\n\n                 If you want to use @{fg fill}LHA@{fg text}, simply enter @{fg fill}TYPE=LHA@{fg text} and\n                 mULTI-cHECK uses now the @{fg fill}LHA@{fg text} routines for stripping/testing\n                 and adding...\n\n                 This Parameter is absolutly needed, without it mULTI-cHECK\n                 won''t work!\n\n  @{fg shine}@{bg shadow}FILENAME/A@{fg text}@{bg back}   - Here you specify the archive to test/add/strip. If you use\n                 mULTI-cHECK as Filechecker for your BBS, this Parameter will\n                 be filled out from the BBS, and therefor no Keyword is\n                 required to specify it (see @{"examples" link "USAGE_EXAMPLES" 0} below).\n\n                 This Parameter is absolutly needed, without it mULTI-cHECK\n                 won''t work!\n\n                @{"Click here for some examples of mULTI-cHECK" link "USAGE_EXAMPLES" 0}\n@endnode\n\n@node "USAGE_EXAMPLES" "Some examples how to use mULTI-cHECK."\n                  @{b}SOME EXAMPLES HOW TO USE mULTI-cHECK:@{ub}\n\n All examples listed here assuming that you have an advertfile called ADVERT\n found in S: and a stripfile called STRIP found in S:, too.\n\n\n@{b}1)@{ub} @{u}Simplest usage:@{uu}\n\n  mULTI-cHECK PACKER=C:LHA TYPE=LHA RAM:MYARCHIVE.LHA\n\n Will only check archive @{fg fill}RAM:MYARCHIVE.LHA@{fg text} in @{fg fill}LHA@{fg text} mode and uses @{fg fill}C:LHA@{fg text}.\n\n\n@{b}2)@{ub} @{u}With adding of an advert:@{uu}\n\n  mULTI-cHECK ADVERT=S:ADVERT PACKER=C:LZX TYPE=LZX RAM:MYARCHIVE.LZX\n\n Will check archive @{fg fill}RAM:MYARCHIVE.LZX@{fg text} in @{fg fill}LZX@{fg text} mode using @{fg fill}C:LZX@{fg text} and after the\n testing will add the @{fg fill}S:ADVERT@{fg text} file to the archive.\n\n\n@{b}3)@{ub} @{u}Stripping from an archive:@{uu}\n\n mULTI-cHECK STRIPFILE=S:STRIP PACKER=C:ZIP TYPE=ZIP RAM:MSDOS.ZIP\n\n Will check archive @{fg fill}RAM:MSDOS.ZIP@{fg text} in @{fg fill}ZIP@{fg text} mode using @{fg fill}C:ZIP@{fg text} and after testing,\n all filenames listed in @{fg fill}S:STRIP@{fg text} will be stripped off the archive.\n\n\n@{b}4)@{ub} @{u}Now an example with testing/adding/stripping for a BBS-System:@{uu}\n\n mULTI-cHECK ADVERT=S:ADVERT STRIPFILE=S:STRIP BBS-PATH=FAME: PACKER=C:ZIP\n             TYPE=ZIP RAM:MSDOS.ZIP\n\n\n@{b}5)@{ub} @{u}At least an example for the Textadding feature (V1.3):@{uu}\n\n mULTI-cHECK ADVERT=S:HEADER.TXT TAILER=S:TAILER.TXT BBS-PATH=FAME: TYPE=TXT\n RAM:ASCII.TXT\n\n It''s clear that you have to enter this in only one line, but the space here\n doesn''t allow it to write this example into one line. This example will\n first test @{fg fill}RAM:MSDOS.ZIP@{fg text} in @{fg fill}ZIP@{fg text} mode using @{fg fill}c:ZIP@{fg text}, then strips off all files\n contained in @{fg fill}S:STRIP@{fg text} from the archive and finally adds the advert @{fg fill}S:ADVERT@{fg text}\n to the archive, but filling out the advert first with uploader''s name, \n location etc. extracting this informations out of the BBS-Path @{fg fill}FAME:@{fg text} .\n\n I think that should be enough examples on how to use it for your needs.\n\n For an overview about the @{"StripFile" link "SAMPLE_STRIPFILE" 0} or the @{"Advert" link "SAMPLE_ADVERT" 0} format used by mULTI-cHECK\n please take a look to the according chapters.\n@endnode\n\n@node "SAMPLE_ADVERT" "An example for an Advert used by mULTI-cHECK"\n                 @{b}SPECIAL COMMANDS USED FOR THE ADVERT:@{ub}\n\n As mULTI-cHECK is able to add @{i}Uploader Name@{ui} and @{i}Location@{ui}, @{i}Node-Nr@{ui}, @{i}Date@{ui} and\n @{i}Time@{ui} of the Upload into your advert, some special commands exists to let\n mULTI-cHECK add this items. Here''s a list of a special commands, you have\n to enter them exactly the same way they are written here:\n\n@{b}1) The Uploadername:@{ub} @{fg shine}@{bg fill}-U-S-E-R-H-A-N-D-L-E-@{fg text}@{bg back}\n\n Will be replaced by the name of the Uploader. Max length is 21 chars,\n shorter names are filled with spaces, longer names are cutted. If no\n uploadername could be found, the string "@{fg fill}-+- THE SYSOP -+-@{fg text}" will be added.\n\n@{b}2) The Uploaderlocation:@{ub} @{fg shine}@{bg fill}-U-S-E-R-L-O-C-A-T-I-O-N-@{fg text}@{bg back}\n\n Will be replaced by the Location of the Uploader. Max. length is 25 chars,\n shorter names are filled with spaces, longer names are cutted. If no\n uploaderlocation could be found, the string "@{fg fill}-+- LOCAL UPLOAD -+-@{fg text}" will be\n added.\n\n@{b}3) The Nodenumber:@{ub} @{fg shine}@{bg fill}¹¹@{fg text}@{bg back}\n\n Will be replaced by the Nodenumber from where the upload was done. Max.\n length is 2 chars, the nodenumber will be right-justified written to your\n advert. If no nodenumber could be found, the string "@{fg fill}--@{fg text}" will be written\n as Nodenumber.\n\n@{b}4) Date of check:@{ub} @{fg shine}@{bg fill}@@-@@-@@@{fg text}@{bg back}\n\n Will be replaced by the date the archive was tested. The date is in the\n USA format (@{fg fill}MM-DD-YY@{fg text}) and is always been added.\n\n@{b}5) Time of check:@{ub} @{fg shine}@{bg fill}##:##:##@{fg text}@{bg back}\n\n Will be replaced by the time the archive was tested. The time is in the\n format @{fg fill}HH:MM:SS@{fg text} and is always been added.\n\n\n\n                          @{b}SAMPLE FOR AN ADVERT:@{ub}\n\n@{fg shine}--- CUT HERE ---@{fg text}\n\n        _____ __ __ _____ __ _____.--.__ ________ ___________ __\n __ _ _/  ._ \\_ |  \\_    \\__)     \\_ | _/        \\_ ___/     \\_ l_  _\n   \\ \\\\_  |/  / |  _/ |  _/\\_  l___/ | \\_  |  |  _/ _/\\_  |  _/ _/_ /_\n       |   __/  |  |  |  |  l__   |     |  |  |  |  |  |  |  |  |  |  ||\n       |  |  |  |  |  |  |  |  |  |  |  |  |  |  |  l  |  |  |  l  |  |:\n       l__|  l_____l__|  l__l__   l__|  l__|__|  l__   l__|  l__   |  ||\n          ÷2F÷        `--''     `--''  `--''     `--''  `--''  `--''  `--''\n\n           · (tRSi/X-iNNOVATiON) WHQ & bETA sITE · cONTRA! gHQ ·\n\n         · eTHIC dIST sITE · mATRIX oRDER sITE · fAME sUPPORT BBS ·\n\n                              __ _____ _____\n     A4ooo/o4o aT 4oMHZ      (__)     \\_    |\n                             | \\_  |  _/ l__|           sYSTEM-cHIEFS:\n  14mB rAM/1.6 GB HD-sPACE   |  |  |  |  |__\n                             |  |  |  |  l  |  _     SieGeL/tRSi & aRGON\n       USR v.34 28.8k        l__l__|  l__   | (_)\n                                   `--''  `--''\n\n          ! sUPPORTING pD and sHAREWARE oNLY oN aMIGA aND IBM-PC !\n\n                  cALL #0: +49(0)30 694 84 70 (v.34)\n                       #1: +49(0)30 694 85 70 (v.34)\n\n             UPLOAD DATE: @@-@@-@@  TIME: ##:##:##  ON NODE: ¹¹\n\n    UPLOADER: -U-S-E-R-H-A-N-D-L-E-  LOCATION: -U-S-E-R-L-O-C-A-T-I-O-N-\n\n@{fg shine}--- CUT HERE ---@{fg text}\n@endnode\n\n@node "SAMPLE_STRIPFILE" "An example for a Stripfile used by mULTI-cHECK"\n             @{b}EXPLANATION FOR THE STRIPFILE USED BY mULTI-cHECK:@{ub}\n\n If you want to let mULTI-cHECK automatically remove unused files from the\n archives being tested, you have to create an ASCII-file containing all file-\n names you wish to remove from the archive. mULTI-cHECK takes this file with\n the Parameter @{"STRIPFILE=<PATH_TO_FILE>" link "USAGE" 0} and removes all files from the\n archive wich matches the filenames found inside the stripfile. Please use\n this option with care, as mULTI-cHECK performs @{b}NO@{ub} checkings about the given\n filenames (i.e. Patterns, spaces between names etc.) for the use of speed.\n It''s on you to remove only @{i}LEGAL@{ui} filenames which doesn''t create problems...\n I''ll give @{b}NO@{ub} warranty about any loss data which occures while removing files\n from an archive with @{i}ILLEGAL@{ui} filenames!\n\n\n                       @{b}EXAMPLE FOR THE STRIPFILE:@{ub}\n\n This is an example how a stripfile may look like. Snap this out and save it\n under a filename of your choice. After this, enter STRIPFILE=<YOUR_NAME> as\n parameter for mULTI-cHECK, and all files where removed then.\n\n@{fg shine}--- CUT HERE ---@{fg text}\n\n display.me \n fucker.txt \n "the fastest" \n READ.ME \n "BLA BLA BLA!"\n\n@{fg shine}--- CUT HERE ---@{fg text}\n\n Don''t ask me to built in a learn function for new adverts, I won''t built-in\n such unsafe things, if you want to remove files, @{b}YOU@{ub} have to enter the\n according filenames...I don''t trust doors/checkers, which are able to \n "learn", as this produces at most cases empty archives....:|\n@endnode\n\n@node "CREDITZ" "Credits and the wellknown Greetings"\n                               @{b}THE GREETINGS:@{ub}\n\n                     @{i}SieGeL/tRSi sends his regards to:@{ui}\n\n Strider/tRSi   - Let''s go on kick some asses ;)\n BloodRock/tRSi - We must code together the DMS-Part for this checker ;)\n Beatnik/tRSi   - FullEd is the Power !\n Spy/tRSi       - Time to change to FAME...what do you think about it ?\n aRGON/tRSi     - Welcome in our nice group dude ;)\n dEATH aNGEL    - Time to get back online ! ;)\n\n\n             @{fg shine}...and of course to all my registered users and@{fg text}\n                @{fg shine}everone I''ve forgot to listen here....@{fg text}\n\n\n                    @{b}@{fg shine}FAME - Final Amiga MailBox Engine !@{ub}@{fg text}\n\n This checker is dedicated to this System, so go on and change/register now !\n\n   @{b}------------------------------------------------------------------------@{ub}\n\n    @{i}THE ONLY WAY TO MULTITASK ON MS-DOS IS TO RUN IBeM TWICE ON AN AMIGA !@{ui}\n@endnode\n\n@node "REGISTER" "Registration of Tools/Doors"\n@{b}REGISTER DOORS/TOOLS@{ub}\n\n All tools I''ve made in the past are released under the @{b}RegisterWare@{ub} concept.\n This means, that I release all my doors only one time as full working Public\n Versions, all updates/bugfixings are only available for registered Users.\n\n The Registration costs @{b}30.- DM@{ub} (or $20) and has to be paid only @{b}*ONE*@{ub}\n time for @{b}*ALL*@{ub} BBS-doors I have made until now. Of course all new \n doors are included in this registration fee, too.\n\n To become registered user, contact one of the following Boards and leave a\n mail to SieGeL/tRSi about Registration:\n\n @{b}pUNISHMENT iNC:@{ub} +49(0) 30 694 8470 (v.34) - fAME tEST/sUPPORT BBS!\n                 +49(0) 30 694 8570 (v.34+)\n\n @{b}Paralysis:@{ub}      +49(0) 30 721 6071 (v.34+)\n                 +49(0) 30 721 6072 (v.34+)\n\n\n              @{fg shine}These Boards are supporting only 100% Public Domain.@{fg text}\n\n                 You could also use @{b}E-Mail@{ub} to contact me:\n\n                          E-Mail: [email removed]\n\n                          Or visit our homepage:\n\n                          http://www.trsi.de/inno/\n@endnode\n\n@node "FAME" "Informations about the FAME-System."\n\n                        @{b}Informations about FAME@{ub}\n\nFAME is at this time still under construction, but because of the fact\nthat many people asked for FAME, it was released at the end of february \n1996 under the concept of shareware and will be available for everyone. \nAt the begining not everything will be completly finished and because \nof this not everything you can already configure will work.\n\nThe registered Versions have to work at least some days before they will\nbe released for registered Users, but it''s still possible that these \nversions also make problems when using them. But as soon as you''ve\nreported those problems, they will be fixed!\n\nIf some of the settings won''t work, it might be a bug but it''s also (more)\npossible that those functions are not implemented yet.\n\nSome of the internal functions are currently untested and it''s possible\nthat they produce errors or problems, but please remember the complexity\nof FAME !\n\nIf you have questions or problems with FAME, please turn on one of the\nFAME-Developers or ask Strider to solve your problems.\n\n@{b}@{u}What should FAME costs ?@{ub}@{uu}\n\n                            FAME Full version:  99 DM\n                FAME & Doors from SieGeL/tRSi: 120 DM\n                FAME & Doors from dr.Dre/tRSi: 120 DM\n               FAME & Doors from SieGeL & Dre: 140 DM\n\n\n@{b}@{u}What is included in the FAME-package ?@{ub}@{uu}\n\n Server, SystemEditor, MainPart, FAMEHydra.FIM, FAMEError.FIM\n\n FAME.library FAMEChat.FIM programmed by Bloodrock/tRSi\n\n FAMEFullEd.FIM, FAMEScript.FIM programmed by Beatnik/tRSi\n\n MUI UserEditor, FAMEDoorHelp.FIM, FAMEInfo programmed by SieGeL/tRSi\n\n Also some doors and tools from the FAME-Development-Team are included,\n but this doors are only unregistered Versions and have therefor some\n limitations. The registered Versions of those doors and the Informations\n how to get them are available here in the pUNISHMENT iNC. BBS.\n\n It could happen that some of the doors and tools listed here are currently\n missing because there are currently under development !\n\n\n@{b}@{u}Who creates FAME ?@{ub}@{uu}\n\n@{fg fill}Main programmer:@{fg text}\n\n - David ''Strider'' Wettig (tRSi) [email removed]\n\n@{fg fill}Additional programmer:@{fg text}\n\n - Oliver ''Bloodrock'' Lange (tRSi) [email removed]\n - Ulrich Arne ''Beatnik'' Jansen (tRSi) [email removed]\n - Sascha ''Siegel'' Pfalz (tRSi) [email removed]\n\n@{fg fill}FAME-Development-Team:@{fg text}\n\n - David ''Strider'' Wettig (tRSi) [email removed]\n - Oliver ''Bloodrock'' Lange (tRSi) [email removed]\n - Ulrich Arne ''Beatnik'' Jansen (tRSi) [email removed]\n - Sascha ''Siegel'' Pfalz (tRSi) [email removed]\n - Bodo ''Dr.Dre!'' Hoffmann (tRSi) [email removed]\n\n\n@{b}@{u}Disclaimer:@{ub}@{uu}\n\n No warranties are given. We take no responsibility of any possible harm this\n product could do to your AMIGA system (not that it would but..).\n We give also no warranties to any dokuments or doors/tools included with\n FAME.\n You use FAME and all FAME related files at your own risk !\n\n Of course we take no responsibility when someone is using FAME for illegal\n terms.\n @{b}------------------------------------------------------------------[EOF]-----@{ub}\n@endnode\n\n@node HeddleyAutoIndex "Index"\n@remark Index auto-generated by Heddley\nIndex of database mULTI-cHECK\n\nDocuments\n\n@{"An example for a Stripfile used by mULTI-cHECK" link "SAMPLE_STRIPFILE"}\n@{"An example for an Advert used by mULTI-cHECK" link "SAMPLE_ADVERT"}\n@{"Copyright Informations for mULTI-cHECK" link "COPYRIGHT"}\n@{"Credits and the wellknown Greetings" link "CREDITZ"}\n@{"How to use it and list of Parameters" link "USAGE"}\n@{"Informations about the FAME-System." link "FAME"}\n@{"Installation to your BBS-System of mULTI-cHECK" link "INSTALLATION"}\n@{"mULTI-cHECK - Archive-Checker for FAME & Amiex Systems" link "Main"}\n@{"Registration of Tools/Doors" link "REGISTER"}\n@{"Some examples how to use mULTI-cHECK." link "USAGE_EXAMPLES"}\n@{"Some informations about mULTI-cHECK" link "INTRODUCTION"}\n\nButtons\n\n@{"  CREDITS & GREETINGS!  " link "CREDITZ" 0}\n@{"  USAGE AND PARAMETERS  " link "USAGE" 0}\n@{"(CLICK HERE FOR OPTIONS)" link "USAGE" 0}\n@{"Advert" link "SAMPLE_ADVERT" 0}\n@{"ADVERT.TXT" link "SAMPLE_ADVERT" 0}\n@{"Click here for some examples of mULTI-cHECK" link "USAGE_EXAMPLES" 0}\n@{"COPYRIGHT & DISTRIBUTION" link "COPYRIGHT" 0}\n@{"Example-Stripfile" link "SAMPLE_STRIPFILE" 0}\n@{"examples" link "USAGE_EXAMPLES" 0}\n@{"FAME" link "FAME" 0}\n@{"FAME-System" link "FAME" 0}\n@{"HERE" link "SAMPLE_ADVERT" 0}\n@{"HERE" link "USAGE_EXAMPLES" 0}\n@{"Installation" link "INSTALLATION" 0}\n@{"INSTALLATION TO YOUR BBS" link "INSTALLATION" 0}\n@{"INTRODUCTION & FEATURES " link "INTRODUCTION" 0}\n@{"Parameters" link "USAGE" 0}\n@{"RegisterWare" link "REGISTER" 0}\n@{"stripfile" link "SAMPLE_STRIPFILE" 0}\n@{"STRIPFILE.TXT" link "SAMPLE_STRIPFILE" 0}\n@{"STRIPFILE=<PATH_TO_FILE>" link "USAGE" 0}\n@endnode\n','\n',char(10)),'{"STACK":"SAME","PRIORITY":"1","TYPE":"LHA@{fg"}','auto-added',109795,9,0,NULL,NULL,'trsi_mc5','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_mck','TRSI-MCK.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-MCK.LHA','LZX','XIM','Zip',NULL,NULL,'TRSI','\      _______  \   _______)---------------. :\__/  \|  __/  /___   \|  \ SieGeL/tRSi oF: ¦  /    \  \    \   \   \   \ /X-iNNOVATiON¦',replace('____________________________________________\n\      _______  \   _______)---------------.\n:\__/  \|  __/  /___   \|  \ SieGeL/tRSi oF:\n¦  /    \  \    \   \   \   \ /X-iNNOVATiON¦\n| /______\__\____\______/____\  PRESENTS   |\n)--mRV-------------------------------------(\n|mULTI-cHECK V1.2 - ADDER/sTRIPPER/cHECKER!|\n|                                          |\n|  sUPPORTS LZX, LHA & ZIP, aUTODETECT oF  |\n|  BBS-sYSTEM uSED (FAME aND /X) aND mANY  |\n|      oTHER fEATURES - cHECK iT oUT !     |\n`------------------------------------------''','\n',char(10)),'mULTI-cHECK.guide',replace('@database mULTI-cHECK\n@master EWORK:mULTI-cHECK/mULTI-cHECK_eng.guide\n@$VER: mULTI-cHECK.guide 1.0 (02-03-96)\n@author "SieGeL/tRSi"\n@(c) "Copyright © 1996 (tRSi/X-iNNOVATiON)"\n@wordwrap\n@index HeddleyAutoIndex\n@remark Created with Heddley v1.1 (c) Edd Dumbill 1994\n@remark Heddley Bugs Fixed with FixHeddley 1.2 (c) 1995 by David Zvekic\n\n@node "Main" "mULTI-cHECK - Archive-Checker for FAME & Amiex Systems"\n\n    @{b}:::.@{ub}       ________  _________ ____\n    @{b}::::@{ub}      |  -___ /_(____-----(____)\n    @{b}`::: ...@{ub}  `---'' `---^---------^----^\n     @{b}:::::::''@{ub}                \n    @{b}.::::''      ..@{ub}       .@{fg fill}ami express@{fg text}.       .@{b}presents in 1996@{ub}.\n   @{b}::::::.     `:::::...@{ub}                \n    @{b}`'' :::        ```:::::..@{ub}  .@{fg fill}fame@{fg text}.          .@{b}mULTI-cHECK  v1.2@{ub}.\n       @{b}`:::            ``::::@{ub}\n        @{b}`:::          ..::::''@{ub}    .@{fg fill}tempest@{fg text}.     .@{b}for /X & FAME BBS@{ub}.\n         @{b}`:::.    ..:::::''''@{ub} __ _ _ _ _ ___ _ _ ___ ___  _ ___ _ _\n          @{b}`:::::::::::''''@{ub}   (__) ` | ` | - | / | - (_ _)(_) - | ` |\n            @{b}``::::''''@{ub}       ^--^-''-^-''-^---^---^-''-''`-'' ^-^---^-''-''\n\n                          wRITTEN bY SieGeL/tRSi\n\n                         @{"COPYRIGHT & DISTRIBUTION" link "COPYRIGHT" 0}\n                         @{"INTRODUCTION & FEATURES " link "INTRODUCTION" 0}\n                         @{"INSTALLATION TO YOUR BBS" link "INSTALLATION" 0}\n                         @{"  USAGE AND PARAMETERS  " link "USAGE" 0} \n                         @{"  CREDITS & GREETINGS!  " link "CREDITZ" 0} \n\n         aNOTHER pRODUCT oF tHE "REAL" (tRSi/X-iNNOVATiON) tEAM !\n@endnode\n\n@node "COPYRIGHT" "Copyright Informations for mULTI-cHECK"\n@{b}DISTRIBUTION:@{ub}\n\n Following notice applies to product called "mULTI-cHECK" and everything \n in its original distribution archive.\n\n * Program is published by SieGeL/tRSi under concept of @{"RegisterWare" link "REGISTER" 0}.\n   No warranties are given. I take no responsibility of any possible\n   harm this product could do to your amiga system (not that it would but..).\n\n * You may NOT sell this product without permission from me.\n\n * Program must not be altered in any way.\n\n * Package must always be kept intact when spreading.\n\n * It is OK to include this on CD-ROM & disk collections and distribute\n   it through aminet and other such ftp''s and file nets.\n\n Above mentioned rules apply to mULTI-cHECK and other texts/libraries\n within the original package versions 1.2 and newer unless otherwise stated.\n@endnode\n\n@node "INTRODUCTION" "Some informations about mULTI-cHECK"\n          @{b}INTRODUCTION TO mULTI-cHECK OR WHY ANOTHER FILECHECKER ?@{ub}\n\n Well, the most important thing why I wrote this Tool is the fact that\n currently no other filechecker supports the @{"FAME-System" link "FAME" 0} (which I''m running!)\n and therefor the adding of uploader etc. was not possible...so I decided to\n write my own one, but not only for @{fg fill}LZX@{fg text} (which was the first archiver I''ve\n supported)...I don''t like many thousands of checkertools and therefor this\n mULTI-cHECKER is able to @{fg shine}check/add/strip@{fg text} from @{fg shine}LZX@{fg text}, @{fg shine}LHA@{fg text} and @{fg shine}ZIP@{fg text} archives...\n\n @{u}Other nice functions are:@{uu}\n\n - Supports @{b}LZX@{ub}, @{b}LHA@{ub} & @{b}ZIP@{ub} Archives for @{b}testing/adding/stripping@{ub}...\n\n - Full @{b}argument-driven@{ub}, no external configfile needed!\n\n - Supports @{b}FAME@{ub} & @{b}Amiex@{ub} systems (but not needed to let it work)\n\n - Is able to add @{b}Uploadername@{ub}, -@{b}location@{ub}, @{b}node@{ub}, @{b}date@{ub} & @{b}time@{ub} of upload to\n   the advert being added....\n\n - Supports @{b}stripping via external Textfile@{ub}\n\n - Very small and fast...:)\n\n If you now interested in this checker, simply take a look to the chapter\n @{"Installation" link "INSTALLATION" 0} for further informations...\n@endnode\n\n@node "INSTALLATION" "Installation to your BBS-System of mULTI-cHECK"\n                       @{b}INSTALLATION OF mULTI-cHECK@{ub}\n\n Best way to copy all neccessary files is to use the Installerscript supplied\n with the release archive...if you want to copy it by hand, follow these few\n steps:\n\n @{b}1.@{ub} Copy @{fg shine}mULTI-cHECK@{fg text} to your @{fg fill}c:@{fg text} directory or to any other directory of your\n    choice.\n\n @{b}2.@{ub} Copy the @{fg shine}documentation@{fg text} to your docs-directory or any other directory...\n\n @{b}3.@{ub} Copy the supplied sample files @{"ADVERT.TXT" link "SAMPLE_ADVERT" 0} and @{"STRIPFILE.TXT" link "SAMPLE_STRIPFILE" 0} to a\n    directory of your choice.\n\n Now you have to edit the files @{b}ADVERT.TXT@{ub} and @{b}STRIPFILE.TXT@{ub} to your needs.\n ADVERT.TXT could have some special symbols which are described @{"HERE" link "SAMPLE_ADVERT" 0}. The\n STRIPFILE.TXT should contain all filenames (!), you wish to kill from the\n archive. Please note that it''s on you to write only legal characters into\n this file, as mULTI-cHECK performs @{b}*NO*@{ub} checkings on these names !!! So\n make sure that you don''t use wildcards or other critical filenames inside\n this @{"stripfile" link "SAMPLE_STRIPFILE" 0}, otherwise it could happen that you gain only empty archives\n or other strange things...you''ve been warned!\n\n At least, you have to built in the checker to your BBS-System.\n\n\n                   @{b}--------- BBS-INSTALLATION ---------@{ub}\n\n\n@{u}AMIEX-SYSOPS:@{uu}\n\n Create three icons inside your BBS:FCHECK/ directory called\n\n                            @{fg shine}LZX.INFO@{fg text}\n                            @{fg shine}LHA.INFO@{fg text}\n                            @{fg shine}ZIP.INFO@{fg text}\n\n and edit the Tooltypes like shown below:\n\n  CHECKER = C:mULTI-cHECK\n  OPTIONS = @{"(CLICK HERE FOR OPTIONS)" link "USAGE" 0}\n    STACK = SAME\n PRIORITY = 1\n  ERROR.1 = Archive Corrupt!\n\n Repeat this steps for all three icons (or only the archive-types you want\n to use mULTI-cHECK for)...the Options are described in the @{"Parameters" link "USAGE" 0}-\n chapter, see there for further informations !\n\n Now you are ready with the installation.\n\n\n@{u}FAME-SYSOPS@{uu}:\n\n Start the System-Editor and go to FileCheckers. Now edit the @{b}LHA@{ub} & @{b}ZIP@{ub}\n configurations like shown below:\n\n  CHECKER PATH = C:mULTI-cHECK\n    STACK SIZE = 4096\n      PRIORITY = 1\n       OPTIONS = @{"(CLICK HERE FOR OPTIONS)" link "USAGE" 0}\n       ERROR 1 = Archive Corrupt!\n\n For @{b}LZX@{ub}, you have the create a new configuration with the @{fg shine}NEW@{fg text} button, enter\n LZX as extension, fill in the fields and save this configuration.\n\n Of course you have to switch the checker(s) @{b}ON@{ub} to let it work :)\n\n That''s all for installing it to @{"FAME" link "FAME" 0}, now you are ready to use it. See\n Chapter @{"Parameters" link "USAGE" 0} for further informations about the Options used by\n mULTI-cHECK.\n@endnode\n\n@node "USAGE" "How to use it and list of Parameters"\n                   @{b}LIST OF PARAMETERS USED BY mULTI-cHECK:@{ub}\n\n As mULTI-cHECK is fully commandline-driven, various parameters exists to\n control mULTI-cHECK. The command-template for mULTI-cHECK is:\n\n      @{fg shine}ADVERT/K,BBS-PATH/K,STRIPFILE/K,PACKER/K/A,TYPE/K/A,FILENAME/A@{fg text}\n\n Click @{"HERE" link "USAGE_EXAMPLES" 0} for some examples how to start mULTI-cHECK.\n\n @{u}Explanation of Parameters:@{uu}\n\n mULTI-cHECK uses standard OS 2.0++ Parms and their keywords, so please take\n a look to your AmigaDOS-Manual for further informations about the templates\n of programs etc.\n\n    @{fg shine}@{bg shadow}ADVERT/K@{fg text}@{bg back}  -  Specify here the Filename to the advert which should be\n                 added to the archive...click @{"HERE" link "SAMPLE_ADVERT" 0} for additional infos\n                 about the format of adverts used by mULTI-cHECK.\n\n                 @{b}@{fg fill}I.E.:@{ub}@{fg text} @{fg fill}ADVERT=S:MYADVERT.TXT@{fg text}\n\n                 will add @{fg fill}S:MYADVERT.TXT@{fg text} after parsing it for any special\n                 commands to the archive given as FileName.\n\n                 This Parameter is optional!\n\n  @{fg shine}@{bg shadow}BBS-PATH/K@{fg text}@{bg back}  -  If you are using mULTI-cHECK with a BBS, enter here the\n                 main path to your BBS System, i.e. @{fg fill}BBS-PATH=BBS:@{fg text} or use\n                 @{fg fill}BBS-PATH=FAME:@{fg text} . Please notice that mULTI-cHECK is able to\n                 detect itself which System you are running...if you don''t\n                 specify this Option, but using the Uploader-Name etc.\n                 features inside an advert, mULTI-cHECK will write\n                 @{b}"-+- The SysOp -+- "@{ub} and @{b}"- Local Upload -"@{ub} for the name &\n                 location fields, otherwise all needed informations where\n                 extracted from the online''s user.datas and written to your\n                 advert.\n\n                 This Parameter is optional!\n\n @{fg shine}@{bg shadow}STRIPFILE/K@{fg text}@{bg back}  -  Here you have to enter the path to a ascii-file containing\n                 all filenames you want to strip off the archive, i.e. you\n                 have a file in @{fg fill}S:@{fg text} called @{fg fill}strips@{fg text} containing:\n\n                                @{i}display.me@{ui}\n                                @{i}fuck_it.txt@{ui}\n                                @{i}werbung.txt@{ui}\n\n                 then you enter @{fg fill}STRIPFILE=S:STRIPS@{fg text} and all filenames listed\n                 inside this file where deleted from the archive. Look to\n                 the Chapter @{"Example-Stripfile" link "SAMPLE_STRIPFILE" 0} for further informations.\n\n                 @{u}NOTE:@{uu} If you are stripping from a @{fg shine}@{bg fill}ZIP-Archive@{fg text}@{bg back}, please don''t\n                       wonder about errormessages comming from ZIP, these\n                       errors are normal, as ZIP prints out all filenames,\n                       which couldn''t be found inside the archive to delete\n                       them...dunno know why this behavour exists, I can''t\n                       suppress this warnings and therefor you have to live\n                       with this :(\n\n                 This Parameter is optional!\n\n  @{fg shine}@{bg shadow}PACKER/K/A@{fg text}@{bg back}  -  Here you must enter the path to the checker you want to use.\n                 I''ve tested it with @{b}LHA V1.50@{ub}, @{b}LZX V1.20@{ub} and @{b}Zip V2.0.1@{ub} but\n                 as I only uses standard commands and therefor there should\n                 be no problems when using different versions. To specify\n                 the packer for @{fg fill}LZX@{fg text}, you could write for example:\n\n                                     @{fg fill}PACKER=C:LZX@{fg text}\n\n                 This Parameter is absolutly needed, without it mULTI-cHECK\n                 won''t work!\n\n    @{fg shine}@{bg shadow}TYPE/K/A@{fg text}@{bg back}   - Enter here the type of packer which is used...currently\n                 there exists 3 types:\n\n                                   @{fg shine}LHA LZX ZIP@{fg text}\n\n                 If you want to use @{fg fill}LHA@{fg text}, simply enter @{fg fill}TYPE=LHA@{fg text} and\n                 mULTI-cHECK uses now the @{fg fill}LHA@{fg text} routines for stripping/testing\n                 and adding...\n\n                 This Parameter is absolutly needed, without it mULTI-cHECK\n                 won''t work!\n\n  @{fg shine}@{bg shadow}FILENAME/A@{fg text}@{bg back}   - Here you specify the archive to test/add/strip. If you use\n                 mULTI-cHECK as Filechecker for your BBS, this Parameter will\n                 be filled out from the BBS, and therefor no Keyword is\n                 required to specify it (see @{"examples" link "USAGE_EXAMPLES" 0} below).\n\n                 This Parameter is absolutly needed, without it mULTI-cHECK\n                 won''t work!\n\n                @{"Click here for some examples of mULTI-cHECK" link "USAGE_EXAMPLES" 0}\n@endnode\n\n@node "USAGE_EXAMPLES" "Some examples how to use mULTI-cHECK."\n                  @{b}SOME EXAMPLES HOW TO USE mULTI-cHECK:@{ub}\n\n All examples listed here assuming that you have an advertfile called ADVERT\n found in S: and a stripfile called STRIP found in S:, too.\n\n\n@{b}1)@{ub} @{u}Simplest usage:@{uu}\n\n  mULTI-cHECK PACKER=C:LHA TYPE=LHA RAM:MYARCHIVE.LHA\n\n Will only check archive @{fg fill}RAM:MYARCHIVE.LHA@{fg text} in @{fg fill}LHA@{fg text} mode and uses @{fg fill}C:LHA@{fg text}.\n\n\n@{b}2)@{ub} @{u}With adding of an advert:@{uu}\n\n  mULTI-cHECK ADVERT=S:ADVERT PACKER=C:LZX TYPE=LZX RAM:MYARCHIVE.LZX\n\n Will check archive @{fg fill}RAM:MYARCHIVE.LZX@{fg text} in @{fg fill}LZX@{fg text} mode using @{fg fill}C:LZX@{fg text} and after the\n testing will add the @{fg fill}S:ADVERT@{fg text} file to the archive.\n\n\n@{b}3)@{ub} @{u}Stripping from an archive:@{uu}\n\n mULTI-cHECK STRIPFILE=S:STRIP PACKER=C:ZIP TYPE=ZIP RAM:MSDOS.ZIP\n\n Will check archive @{fg fill}RAM:MSDOS.ZIP@{fg text} in @{fg fill}ZIP@{fg text} mode using @{fg fill}C:ZIP@{fg text} and after testing,\n all filenames listed in @{fg fill}S:STRIP@{fg text} will be stripped off the archive.\n\n\n@{b}4)@{ub} @{u}Now an example with testing/adding/stripping for a BBS-System:@{uu}\n\n mULTI-cHECK ADVERT=S:ADVERT STRIPFILE=S:STRIP BBS-PATH=FAME: PACKER=C:ZIP\n             TYPE=ZIP RAM:MSDOS.ZIP\n\n It''s clear that you have to enter this in only one line, but the space here\n doesn''t allow it to write this example into one line. This example will\n first test @{fg fill}RAM:MSDOS.ZIP@{fg text} in @{fg fill}ZIP@{fg text} mode using @{fg fill}c:ZIP@{fg text}, then strips off all files\n contained in @{fg fill}S:STRIP@{fg text} from the archive and finally adds the advert @{fg fill}S:ADVERT@{fg text}\n to the archive, but filling out the advert first with uploader''s name, \n location etc. extracting this informations out of the BBS-Path @{fg fill}FAME:@{fg text} .\n\n I think that should be enough examples on how to use it for your needs.\n\n For an overview about the @{"StripFile" link "SAMPLE_STRIPFILE" 0} or the @{"Advert" link "SAMPLE_ADVERT" 0} format used by mULTI-cHECK\n please take a look to the according chapters.\n@endnode\n\n@node "SAMPLE_ADVERT" "An example for an Advert used by mULTI-cHECK"\n                 @{b}SPECIAL COMMANDS USED FOR THE ADVERT:@{ub}\n\n As mULTI-cHECK is able to add @{i}Uploader Name@{ui} and @{i}Location@{ui}, @{i}Node-Nr@{ui}, @{i}Date@{ui} and\n @{i}Time@{ui} of the Upload into your advert, some special commands exists to let\n mULTI-cHECK add this items. Here''s a list of a special commands, you have\n to enter them exactly the same way they are written here:\n\n@{b}1) The Uploadername:@{ub} @{fg shine}@{bg fill}-U-S-E-R-H-A-N-D-L-E-@{fg text}@{bg back}\n\n Will be replaced by the name of the Uploader. Max length is 21 chars,\n shorter names are filled with spaces, longer names are cutted. If no\n uploadername could be found, the string "@{fg fill}-+- THE SYSOP -+-@{fg text}" will be added.\n\n@{b}2) The Uploaderlocation:@{ub} @{fg shine}@{bg fill}-U-S-E-R-L-O-C-A-T-I-O-N-@{fg text}@{bg back}\n\n Will be replaced by the Location of the Uploader. Max. length is 25 chars,\n shorter names are filled with spaces, longer names are cutted. If no\n uploaderlocation could be found, the string "@{fg fill}-+- LOCAL UPLOAD -+-@{fg text}" will be\n added.\n\n@{b}3) The Nodenumber:@{ub} @{fg shine}@{bg fill}¹¹@{fg text}@{bg back}\n\n Will be replaced by the Nodenumber from where the upload was done. Max.\n length is 2 chars, the nodenumber will be right-justified written to your\n advert. If no nodenumber could be found, the string "@{fg fill}--@{fg text}" will be written\n as Nodenumber.\n\n@{b}4) Date of check:@{ub} @{fg shine}@{bg fill}@@-@@-@@@{fg text}@{bg back}\n\n Will be replaced by the date the archive was tested. The date is in the\n USA format (@{fg fill}MM-DD-YY@{fg text}) and is always been added.\n\n@{b}5) Time of check:@{ub} @{fg shine}@{bg fill}##:##:##@{fg text}@{bg back}\n\n Will be replaced by the time the archive was tested. The time is in the\n format @{fg fill}HH:MM:SS@{fg text} and is always been added.\n\n\n\n                          @{b}SAMPLE FOR AN ADVERT:@{ub}\n\n@{fg shine}--- CUT HERE ---@{fg text}\n\n        _____ __ __ _____ __ _____.--.__ ________ ___________ __\n __ _ _/  ._ \\_ |  \\_    \\__)     \\_ | _/        \\_ ___/     \\_ l_  _\n   \\ \\\\_  |/  / |  _/ |  _/\\_  l___/ | \\_  |  |  _/ _/\\_  |  _/ _/_ /_\n       |   __/  |  |  |  |  l__   |     |  |  |  |  |  |  |  |  |  |  ||\n       |  |  |  |  |  |  |  |  |  |  |  |  |  |  |  l  |  |  |  l  |  |:\n       l__|  l_____l__|  l__l__   l__|  l__|__|  l__   l__|  l__   |  ||\n          ÷2F÷        `--''     `--''  `--''     `--''  `--''  `--''  `--''\n\n           · (tRSi/X-iNNOVATiON) WHQ & bETA sITE · cONTRA! gHQ ·\n\n         · eTHIC dIST sITE · mATRIX oRDER sITE · fAME sUPPORT BBS ·\n\n                              __ _____ _____\n     A4ooo/o4o aT 4oMHZ      (__)     \\_    |\n                             | \\_  |  _/ l__|           sYSTEM-cHIEFS:\n  14mB rAM/1.6 GB HD-sPACE   |  |  |  |  |__\n                             |  |  |  |  l  |  _     SieGeL/tRSi & aRGON\n       USR v.34 28.8k        l__l__|  l__   | (_)\n                                   `--''  `--''\n\n          ! sUPPORTING pD and sHAREWARE oNLY oN aMIGA aND IBM-PC !\n\n                  cALL #0: +49(0)30 694 84 70 (v.34)\n                       #1: +49(0)30 694 85 70 (v.34)\n\n             UPLOAD DATE: @@-@@-@@  TIME: ##:##:##  ON NODE: ¹¹\n\n    UPLOADER: -U-S-E-R-H-A-N-D-L-E-  LOCATION: -U-S-E-R-L-O-C-A-T-I-O-N-\n\n@{fg shine}--- CUT HERE ---@{fg text}\n@endnode\n\n@node "SAMPLE_STRIPFILE" "An example for a Stripfile used by mULTI-cHECK"\n             @{b}EXPLANATION FOR THE STRIPFILE USED BY mULTI-cHECK:@{ub}\n\n If you want to let mULTI-cHECK automatically remove unused files from the\n archives being tested, you have to create an ASCII-file containing all file-\n names you wish to remove from the archive. mULTI-cHECK takes this file with\n the Parameter @{"STRIPFILE=<PATH_TO_FILE>" link "USAGE" 0} and removes all files from the\n archive wich matches the filenames found inside the stripfile. Please use\n this option with care, as mULTI-cHECK performs @{b}NO@{ub} checkings about the given\n filenames (i.e. Patterns, spaces between names etc.) for the use of speed.\n It''s on you to remove only @{i}LEGAL@{ui} filenames which doesn''t create problems...\n I''ll give @{b}NO@{ub} warranty about any loss data which occures while removing files\n from an archive with @{i}ILLEGAL@{ui} filenames!\n\n\n                       @{b}EXAMPLE FOR THE STRIPFILE:@{ub}\n\n This is an example how a stripfile may look like. Snap this out and save it\n under a filename of your choice. After this, enter STRIPFILE=<YOUR_NAME> as\n parameter for mULTI-cHECK, and all files where removed then.\n\n@{fg shine}--- CUT HERE ---@{fg text}\n\n display.me \n fucker.txt \n "the fastest" \n READ.ME \n "BLA BLA BLA!"\n\n@{fg shine}--- CUT HERE ---@{fg text}\n\n Don''t ask me to built in a learn function for new adverts, I won''t built-in\n such unsafe things, if you want to remove files, @{b}YOU@{ub} have to enter the\n according filenames...I don''t trust doors/checkers, which are able to \n "learn", as this produces at most cases empty archives....:|\n@endnode\n\n@node "CREDITZ" "Credits and the wellknown Greetings"\n                               @{b}THE GREETINGS:@{ub}\n\n                     @{i}SieGeL/tRSi sends his regards to:@{ui}\n\n Strider/tRSi   - Go on with FAME, you have to release it soon !\n BloodRock/tRSi - We must code together the DMS-Part for this checker ;)\n Beatnik/tRSi   - FullEd is the Power !\n Dr.Dre!/tRSi   - The tapes you''ve sended me are very nice :)\n ByteAndi/tRSi  - Don''t hear anything from you, call back mate!!!!!!!!\n Spy/tRSi       - Time to change to FAME...what do you think about it ?\n vAMPIRE/tRSi   - Hope you get everythink worked :) Waiting for the CD''s :)))\n aRGON/pDY      - Call more often, don''t here from you very much in the past\n dEATH aNGEL    - Hope your illness get''s better...best wishes!\n vENOM          - Nice to have english guys here, hope you like FAME :)\n tURBO          - The same to you, got yar in another chat :)\n sCANDIC/dCS    - FFS is the ruling name hehehe\n [oRK!]         - We talk the next days in chat, I promise!\n F. Monteilhet  - For cewl E-Mails and your nice help with translating :)\n\n\n             @{fg shine}...and of course to all my registered users and@{fg text}\n                @{fg shine}everone I''ve forgot to listen here....@{fg text}\n\n\n This is my first release in the mighty year 1996, the release year of a new\n generation of BBS-Systems:\n\n                    @{b}@{fg shine}FAME - Final Amiga MailBox Engine !@{ub}@{fg text}\n\n This checker is dedicated to this System, so go on and change/register now !\n\n   @{b}------------------------------------------------------------------------@{ub}\n\n    @{i}THE ONLY WAY TO MULTITASK ON MS-DOS IS TO RUN IBeM TWICE ON AN AMIGA !@{ui}\n@endnode\n\n@node "REGISTER" "Registration of Tools/Doors"\n@{b}REGISTER DOORS/TOOLS@{ub}\n\n All tools I''ve made in the past are released under the @{b}RegisterWare@{ub} concept.\n This means, that I release all my doors only one time as full working Public\n Versions, all updates/bugfixings are only available for registered Users.\n\n The Registration costs @{b}30.- DM@{ub} (or $20) and has to be paid only @{b}*ONE*@{ub}\n time for @{b}*ALL*@{ub} BBS-doors I have made until now. Of course all new \n doors are included in this registration fee, too.\n\n To become registered user, contact one of the following Boards and leave a\n mail to SieGeL/tRSi about Registration:\n\n @{b}pUNISHMENT iNC:@{ub} +49(0) 30 694 8470 (v.34) - fAME tEST/sUPPORT BBS!\n                 +49(0) 30 694 8570 (v.34)\n\n @{b}Paralysis:@{ub}      +49(0) 30 721 6071 (v.34)\n                 +49(0) 30 721 6072 (v.34)\n                 +49(0) 30 721 6073 (v.34)\n                 +49(0) 30 721 6065 (v.34)\n\n @{b}Spirit of Soul:@{ub} Absolute Private\n\n              @{fg shine}These Boards are supporting only 100% Public Domain.@{fg text}\n\n             You could also use @{b}E-Mail@{ub} or @{b}Compuserve@{ub} to contact me:\n\n                       E-Mail: [email removed]\n\n                   CompuServe: 101601,2654 (Sascha Pfalz)\n@endnode\n\n@node "FAME" "Informations about the FAME-System."\n\n                        @{b}Informations about FAME@{ub}\n\n FAME is at this time still under construction, but because of the fact\n that many people asked for FAME, it will be released until the end\n of february under the concept of shareware and will be available for\n everyone. At the begining not everything will be completly finished and\n because of this not everything you can already configure will work.\n The registered Versions have to work at least some days before they will\n be released for registered Users, but it''s still possible that these\n versions also make problems when using them. But as soon as you''ve\n reported those problems, they will be fixed!\n\n If some of the settings won''t work, it might be a bug but it''s also (more)\n possible that those functions are not implemented yet.\n\n Some of the internal functions are currently untested and it''s possible\n that they produce errors or problems, but please remember the complexity\n of FAME !\n\n If you have questions or problems with FAME, please turn on one of the\n FAME-Developers or ask Strider to solve your problems.\n\n\n@{b}@{u}What should FAME costs ?@{ub}@{uu}\n\n Registered Version:  110 USD / 150 DM\n Betatester Version:  145 USD / 200 DM\n\n\n@{b}@{u}What is included in the FAME-package ?@{ub}@{uu}\n\n Server, SystemEditor, MainPart, FAMEHydra.FIM, FAMEError.FIM\n\n FAME.library FAMEChat.FIM programmed by Bloodrock/tRSi\n\n FAMEFullEd.FIM, FAMEScript.FIM programmed by Beatnik/tRSi\n\n MUI UserEditor, FAMEDoorHelp.FIM, FAMEInfo programmed by SieGeL/tRSi\n\n Also some doors and tools from the FAME-Development-Team are included,\n but this doors are only unregistered Versions and have therefor some\n limitations. The registered Versions of those doors and the Informations\n how to get them are available here in the pUNISHMENT iNC. BBS.\n\n It could happen that some of the doors and tools listed here are currently\n missing because there are currently under development !\n\n\n@{b}@{u}Who creates FAME ?@{ub}@{uu}\n\n@{fg fill}Main programmer:@{fg text}\n\n - David ''Strider'' Wettig (tRSi) [email removed]\n\n@{fg fill}Additional programmer:@{fg text}\n\n - Oliver ''Bloodrock'' Lange (tRSi) [email removed]\n - Ulrich Arne ''Beatnik'' Jansen (tRSi) [email removed]\n - Sascha ''Siegel'' Pfalz (tRSi) [email removed]\n\n@{fg fill}FAME-Development-Team:@{fg text}\n\n - David ''Strider'' Wettig (tRSi) [email removed]\n - Oliver ''Bloodrock'' Lange (tRSi) [email removed]\n - Ulrich Arne ''Beatnik'' Jansen (tRSi) [email removed]\n - Sascha ''Siegel'' Pfalz (tRSi) [email removed]\n - Andreas ''ByteAndi'' Petermann (tRSi)\n - Dirk ''Spy'' Holzkampf (tRSi) [email removed]\n - Bodo ''Dr.Dre!'' Hoffmann (tRSi)\n\n\n@{b}@{u}Disclaimer:@{ub}@{uu}\n\n No warranties are given. We take no responsibility of any possible harm this\n product could do to your AMIGA system (not that it would but..).\n We give also no warranties to any dokuments or doors/tools included with\n FAME.\n You use FAME and all FAME related files at your own risk !\n\n Of course we take no responsibility when someone is using FAME for illegal\n terms.\n @{b}------------------------------------------------------------------[EOF]-----@{ub}\n@endnode\n\n@node HeddleyAutoIndex "Index"\n@remark Index auto-generated by Heddley\nIndex of database mULTI-cHECK\n\nDocuments\n\n@{"An example for a Stripfile used by mULTI-cHECK" link "SAMPLE_STRIPFILE"}\n@{"An example for an Advert used by mULTI-cHECK" link "SAMPLE_ADVERT"}\n@{"Copyright Informations for mULTI-cHECK" link "COPYRIGHT"}\n@{"Credits and the wellknown Greetings" link "CREDITZ"}\n@{"How to use it and list of Parameters" link "USAGE"}\n@{"Informations about the FAME-System." link "FAME"}\n@{"Installation to your BBS-System of mULTI-cHECK" link "INSTALLATION"}\n@{"mULTI-cHECK - Archive-Checker for FAME & Amiex Systems" link "Main"}\n@{"Registration of Tools/Doors" link "REGISTER"}\n@{"Some examples how to use mULTI-cHECK." link "USAGE_EXAMPLES"}\n@{"Some informations about mULTI-cHECK" link "INTRODUCTION"}\n\nButtons\n\n@{"  CREDITS & GREETINGS!  " link "CREDITZ" 0}\n@{"  USAGE AND PARAMETERS  " link "USAGE" 0}\n@{"(CLICK HERE FOR OPTIONS)" link "USAGE" 0}\n@{"Advert" link "SAMPLE_ADVERT" 0}\n@{"ADVERT.TXT" link "SAMPLE_ADVERT" 0}\n@{"Click here for some examples of mULTI-cHECK" link "USAGE_EXAMPLES" 0}\n@{"COPYRIGHT & DISTRIBUTION" link "COPYRIGHT" 0}\n@{"Example-Stripfile" link "SAMPLE_STRIPFILE" 0}\n@{"examples" link "USAGE_EXAMPLES" 0}\n@{"FAME" link "FAME" 0}\n@{"FAME-System" link "FAME" 0}\n@{"HERE" link "SAMPLE_ADVERT" 0}\n@{"HERE" link "USAGE_EXAMPLES" 0}\n@{"Installation" link "INSTALLATION" 0}\n@{"INSTALLATION TO YOUR BBS" link "INSTALLATION" 0}\n@{"INTRODUCTION & FEATURES " link "INTRODUCTION" 0}\n@{"Parameters" link "USAGE" 0}\n@{"RegisterWare" link "REGISTER" 0}\n@{"stripfile" link "SAMPLE_STRIPFILE" 0}\n@{"STRIPFILE.TXT" link "SAMPLE_STRIPFILE" 0}\n@{"STRIPFILE=<PATH_TO_FILE>" link "USAGE" 0}\n@endnode\n','\n',char(10)),'{"STACK":"SAME","PRIORITY":"1","TYPE":"LHA@{fg"}','auto-added',129982,6,0,NULL,NULL,'trsi_mck','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_msc','TRSI_MSC.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI_MSC.LHA',NULL,'XIM','Comment.x',NULL,'Dr.Dre!/tRZ','TRSI','l___       /      \/    _/_______.: /       /   /  _/\___      /    : /_______/-rS!\_____\  _____/     |',replace('    ._________________  ______\n    l___       /      \/    _/_______.:\n      /       /   /  _/\___      /    :\n     /_______/-rS!\_____\  _____/     |\n           /_______|     \/`94/_______|\n   MS-Comment v1.2 (XiM) by Dr.Dre!/tRZ\n   ÷Simply the best MultiSysopComment!÷\n','\n',char(10)),'Comment.guide',replace('@database MS-Comment v1.2 - by Dr.Dre!/TrSi\n\nCopyright (C) 1994 by Dr.Dre!/tRSi^zENITh Germany\nAll Rights Reserved\n\n@Remark $VER: Version v1.2 (Saturday 06-Mar-94 19:27:08)\nRemark AmigaGuide DataBase for MS-Comment v1.2\n\n@Node MAIN "MS_Comment v1.2 (Sunday 06-Mar-94 19:27:08) Dcoument for /X"\n\n                   ._________________  ______\n                   l___       /      \/    _/_______.:  \n                     /       /   /  _/\___      /    :\n                    /_______/-rS!\_____\  _____/     |''94  \n                          /_______|     \/   /_______|\n\n                           is proud to present: \n          Multi_Sysop_Comment v1.2, XiM Module for /X 2.xx - 3.xx\n\n                       English Doc     German Doc\n                     @{" Introduction  "Link no1} @{"  Einleitung   "Link nr1}\n                     @{" Requirements  "Link no2} @{" Anforderung   "Link nr2}\n                     @{" Installation  "Link no3} @{" Installation  "Link nr3}\n                     @{"   Copyright   "Link no4} @{"   Copyright   "Link no4}\n                     @{"   Greetings   "Link no5} @{"    Gruesse    "Link no5}\n                     @{"          TRSI Boards          "Link no6}\n@endnode\n@node no1 " Introduction"\n\nMulti Sysop Comment is may simply the Best C Replacment for /X.\nIt is written in fast C as XiM Module.\nThe MS-Comment v1.2 is usefull if you run a BBS with multiple Sysops.\nIt have some nice features and is fuck easy to setup about ToolTypes!\nhave phun with the Door.\nDr.Dre!/tRSi                                         @{" Main Menu " Link main}\n@endnode\n@node nr1 " Einleitung"\n\nMulti Sysop Comment ist einfach der beste Ersatz fuer den Standart C \nCommand in /X, es ist in C geschrieben fuer pure Speed!\nDer MS-Comment v1.2 is sehr nuetlich wenn du eine BBS mit vielen Sysops hast.\nEs bietet einige gute features und ist sehr einfach über Tooltypes zu \nconfigurieren...\n\nDr.Dre!/tRSi                                         @{" Main Menu " Link main}\n@endnode\n@node no2 " Requirements"\n\nOnly what you need is OS2.++ and any Version of AmiExpress (registered)\nand in Doors:Comment/ the Comment.Info Icon.\nNothing more...\n                                                     @{" Main Menu " Link main}\n\n@endnode\n@node nr2 " Anforderungen"\n\nDas einzige was die Door benoetigt ist Kickstart 2.++\nund in Doors:Comment/ das Comment.Info Icon.\n                                                     @{" Main Menu " Link main}\n\n@endnode\n@node no3 " Installation "\n\nCreate a Directory in you Doors: called Comment, there copy the Comment.x\nand the Comment.Info\nThen open the Comment.Info for settin up the ToolTypes.\nThis ToolTypes are available.\nNAME.1=Sysop Name #1  (max. 31 Chrs)\nDESC.1=Description from the Sysop #1  (max. 37 Chrs)\nANSWER.1=Some Bullshit which will displayed by choosin Sysop#1 (max 60 Chrs)\nNAME.2=Sysop Name #1\nDESC.2=Description from the Sysop #1\nANSWER.2=Some Bullshit which will displayed by choosin Sysop #1\nand so on until SYSOP.??? how many you have...\nNOTE!: Start with NAME.1 !!! not NAME.0 this will ignored\nDEFAULT_SYSOP=<#> ;<- here enter the Number from the Default Sysop\n                   this Sysop will be choosed every Time by pressin\n		   Return or a higher Number as available Sysop`s\n		   if you want have NAME.3 as default so write\n                   DEFAULT_SYSOP=3\n                   Look into the included Icon.\n                                                     @{" Main Menu " Link main}\n@endnode\n@node nr3 " Installation"\n\nKreiert eine Directory namens Comment in den DOORS:\nKopiert das Comment.x und das Comment.Info nach DOORS:Comment/\nOeffnet das Comment.Info um die Door zu configurieren.\nMoegliche ToolTypes sind:\nNAME.1=Name des ersten Sysops - (max 31 Zeichen)\nDESC.1=Funktion des ersten Sysops - (max. 37 Zeichen)\nANSWER.1=Answer Zeile wenn der Sysop ausgewaehlt wird. (max 60 Zeichen)\nNAME.2=Name des zweiten Sysops - (max 31 Zeichen)\nDESC.2=Funktion des zweiten Sysops - (max. 37 Zeichen)\nANSWER.2=Answer Zeile wenn der Sysop ausgewaehlt wird. (max 60 Zeichen)\nund soweiter immer hochcounten soviele Sysops ihr wollt btw: habt.\nNOTE!: Started mit NAME.1 !!! NAME.0 wird ignoriert\nDEFAULT_SYSOP=<#> ;hier schreibt die Nummer des Sysops rein der als\n                   Default genommen wird. Dieser Sysop wird immer \n		   gewaehlt wenn return oder ein Sysop gewaehlt wird\n                   der nicht existiert!!! Wenn also NAME.3 als default\n                   genommen werden soll so schreibt DEFAULT_SYSOP=3 \n                   Seht in das beigefuegte Icon.\n                                                     @{" Main Menu " Link main}\n@endnode\n@node no4 " Copyright"\n\n\n           MS-Comment v1.2 is written by Dr.Dre! of TRSI^Zenith\n                         All Rights Reserved ©1994\n\n              Comment.x has a Original Size from : 9908 bytes\n\n          The AmigaGuide DataBase written by Dr.Dre!/tRSi^Zenith\n\n         If you have any Problems with the Door so contact me at \n                         @{" Marleys Coffee Shop " Link Coffee}\n\nI`m still looking for some good BetaTesters, if you are interested and are\nrunning a Multinode System so contact me at @{" Marleys Coffee Shop " Link Coffee}\n\n                                                     @{" Main Menu " Link main}\n\n@endnode\n@node no5 " Greetings"\n\n     Many thnx to all my Beta Testers who helps me to fix all Bugs !!!\n\n                   The Greets are going to these Dudes...\n\n   ByteAndi/X-Design, Spy/X-Design, Remo/X-Design, X-Treme, Saito/TRSI\n    Fugitive/DLM, MetalbasheR!, McLoud/TRSI, Irata/TRSI, Triton/Pdy\n Skylark/LSD, Nick, Metoner/TRSI, J.Walker/TRSI, Crazy/TRSI, Valshare/TRSI\n    Vicous/LSD, Richi/Flt, Steve/D&R, Amicom, -rS!/TRSi, Empire/Mst, \n   BJoerN/Pdy, Scope, SkiN!,Mario/TRSI, TCM!/DLM, -runt/TRSI, Prayer/TRSI\n                         Samir/trz, Rotor/trz ...\n          and simply all tRSi Member an other Doodes I forgot...\n\n\n                                                     @{" Main Menu " Link main}\n@endnode\n@node no6 " TRSI Boards Worldwide"\n\n                 To Contact me Call any of this Boards...\n\n   biohazard......................Canadian HQ............+1-905-841-0965\n   cauldron.......................German   HQ............++49 Pure Elite\n   marleys coffee shop............German   HQ............++49 Pure Elite\n   MayDay.........................German   HQ............++49 Pure Elite\n   boondocks......................European HQ............+31-548-040-653\n   final impact...................Swedish  HQ............++46-54-113-486\n   flying spirits.................Swiss    HQ............+41-217-282-524\n   savage amusement...............Austria  HQ............+43-767-227-743\n   zEnlandia......................Finnish  HQ............+358-088-82-144\n\n\n                                                     @{" Main Menu " Link main}\n@endnode\n@node Coffee "Marleys Coffee Shop - TRZ german hQ"\n\n           * tRiStAR & RED sECtOR * zENITh * gERmAN hEADqUARtER\n                                           _______    ._____\n      _______  ____.______  ______________/   .  /____|    /_______\n      \      \/    |      \/   _  \      /   ___/_    l   /   __  /\n       \           |      \\   /  /_    /_________l____  /\__   \/\n        \    \/____l________\  \____|______|    |_______/________\\n         \____\         /______|                       _______\n                 ____          _______________________/   .  /\n                /  __l_. _____/     __/     __/   .  /   ___/_.\n               /   |   |/     \     _/\     _/   ___/_________|\n              /________|      \\____|  \____|_________|\n                       \_______/         _____    \n                      __________________/     \__________\n Dr.Dre!/tRSi        /   __  /    /    //      \    .   /\n                    /\__   \/         /\_______/    ___/\n  J.Walker/tRSi    /________\   /____/-rS!/aRt/_____|\n                          /____/\n\n                                                     @{" Main Menu " Link main}\n@endnode\n','\n',char(10)),NULL,'auto-added',17686,4,0,NULL,NULL,'trsi_msc','scan',1780048806);
INSERT INTO door_catalog VALUES('trsi_msg','TRSI-MSG.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-MSG.LHA','installer','XIM','MSGEdit',NULL,'dR.dRE!/tRSi','TRSI','___/  __/___________/  ____/_________/     / \__   \     /   _   \_____    /_____/     / /    /    /    /___/    /   /     /_____/',replace('    _____            _______          ______\n___/  __/___________/  ____/_________/     /\n\__   \     /   _   \_____    /_____/     /\n /    /    /    /___/    /   /     /_____/\n \________/____/-pRz\_______/_____/_____/\n--------------------------------------------\nMSGEdit v1.o bY dR.dRE!/tRSi (/X·iNNOVAtiON)\n  fiRSt EXtERNAl MSG EditOR fOR AMiEXPRESS\nUSER dEfiNEAblE FS EditOR, CliPbOARd SUPPORT\nCONf SElECtiNG, AliGN fUNCtiONS, filEIMPORt,\nand and and... SYSOPS MUSt hAVE thiS tool!!!\n','\n',char(10)),'MSGEdit.guide',replace('@database 0036fa50-0\n@master msg:guide/MSGEdit.guide\n@$VER: MSG EDIT v1.0 - First external MsgEd for AmiExpress\n@author "dR.dRE!/tRSi (/X·iNNOVAtiON)"\n@(c) "(c) 1995/7 by dR.dRE!/tRSi - All Rights Reserved"\n@remark Created with Heddley v1.1 (c) Edd Dumbill 1994\n\n@node "Main" "No title"\n\n                           @{b}Message  Editor v1.0@{ub}\n                               @{b}July 24, 1995@{ub}\n\n                      by dR.dRE!/tRSi (/X·iNNOVAtiON)\n \n MSG·EDIT v1.0 © 1995/7 Bodo Hoffmann All Rights Reserved.\n\n @{b}TABLE OF CONTENTS@{ub}\n\n @{"  " link "Install" 0} Installing MSG·Edit\n @{"  " link "Technical" 0} Author & Technical Infos\n @{"  " link "Register" 0} Registering our tools\n @{"  " link "Features" 0} Features of MSG·Edit\n @{"  " link "Preferences" 0} Bugs in MSG·Edit\n @{"  " link "History" 0} History - Previous versions.\n @{"  " link "Greetings" 0} Greetings \n @{"  " link "ToDo" 0} Todo\n\n @{b}HOW TO USE...@{ub}\n\n @{"  " link "MSGEdit" 0} MSG·Edit\n @{"  " link "Document_7" 0} Preferences\n @{"  " link "Editor" 0} Editor\n @{"  " link "EdFunctions" 0} Editor Functions\n @{"  " link "MsgHeader" 0} Msg Header\n\n @{b}THE LEGAL GARBAGE@{ub}\n\n @{"  " link "Credits" 0} Credits & Copright Notes\n @{"  " link "Innovation" 0} tRSi (/X·iNNOVAtiON)\n@endnode\n\n@node "Install" "How to install MSG·Edit v1.o"\n \n @{b}INSTALLATION@{ub}\n \n Double click the "Install" icon to install MSG·Edit.\n  \n The Installation Script will copy the textfield.gadget to your SYS:CLASSES\n Directory and the MSG·Edit Main file to a user chooseable path.\n It will ask you to install the latest version of the reqtools.library\n if you want to skip this part just click no at this point.\n\n At the first you should call MSG·Edit from CLI or by double-clicking the \n Icon then jump to the preferences window and specify the following things.\n\n 1) @{u}BBS Path@{uu}\n    - just choose your BBS Path from the REQ-Tools Requester\n\n 2) @{u}User Data Path@{uu}\n    - specify the Path to your User.Data (double-click it)\n\n 3) @{u}Message Sender@{uu}\n - here you select your handle from the popup-list.\n\n \n Thats all...\n@endnode\n\n@node "Technical" "Infos about the Author and Technical"\n                             @{b}About the Author@{ub}\n                            @{b}and other tid-bits.@{ub}\n \n\n @{b}Program:@{ub}             Message Edit - first external Message Editor for\n                      AmiExpress 4.xx Professional\n @{b}Version:@{ub}             v1.o [UNREGISTERED PUBLIC VERSION]\n @{b}Date:@{ub}                July 24, 1995\n @{b}Coded by:@{ub}            dR.dRE!/tRSi\n @{b}Compiled with:@{ub}       SAS/C 6.55\n @{b}Machine:@{ub}             A2ooo, 68EC030/25, 9MB, AmigaDOS 3.1\n @{b}Required:@{ub}            AmigaDOS 3.o or above, MUI v2.2 or higher,\n                      textfield.gadget in your CLASSES/GADGETS/\n \n @{b}Distribution:@{ub}        \n\n Following notice applies to product called "MSG·Edit" and \n everything in its original distribution archive.\n\n * Program is published by dR.dRE!/tRSi under concept of @{"RegisterWare" link "Register" 0}\n   No warranties are given. I take no responsibility of any possible\n   harm this product could do to your amiga system (not that it would but..).\n   \n * You may NOT sell this product without permission from me.\n\n * Program must not be altered in any way.\n \n * Package must always be kept intact when spreading.\n \n * It is OK to include this on CD-ROM & disk collections and distribute\n   it through aminet and other such ftp''s and file nets.\n\n Above mentioned rules apply to MSG·Edit and other texts/libraries\n within the original package versions 1.0 and newer unless otherwise stated.\n\n @{b}MSG·Edit@{ub} uses MUI 2.3++ - © Copyright 1992/95 Stefan Stuntz \n @{b}MSG·Edit@{ub} uses the textfield.gadget 3.0 Copyright - © 1995 Mark Thomas\n@endnode\n\n@node "Register" "How to get a full working version..."\n\n @{b}REGISTRATION@{ub}\n \n If you like this or any other Tool of tRSi (/X·iNNOVAtiON), so get in \n touch with one of our Members on any of the following Bulletin Board \n Systems.\n \n @{b}Spirits of Soul:@{ub}  Absolute Private\n @{b}Devils Point:@{ub}     Absolute Private\n @{b}Boondocks:@{ub}        Absolute Private\n @{b}Punishment iNC:@{ub}   +49(0) 30 694 847o\n @{b}Paralysis:@{ub}        +49(0) 30 721 6071/72/73/65\n \n @{u}These Boards are supporting only 100% Public Domain.@{uu}\n@endnode\n\n@node "Features" "The features of MSG·Edit v1.o"\n \n @{b}MSG·Edit does the following:@{ub}\n \n o Let you post messages in your /X Bulletin Board System without starting\n   the BBS\n o Message editing with a own full screen editor with 100% word wrapping\n o free selecting of all (active) users of your BBS\n - free selecting of all conferences of your BBS\n o special text formatting (align, center...)\n o 100% clipboard support\n o UNDO functions\n - External file import\n o cut/copy/paste functions\n o Editor online help\n o support of all mailing formats (PUBLIC/PRIVATE/EALL)\n - user defineable Editor style\n o Textdropping in the textfield.gadget\n   (This will automatic insert the dropped text)\n\n @{b}@{u}NOTE:@{ub}@{uu} All functions marked with a (-) are not implemeted in the PUBLIC\n       VERSION if want use the other stuff too,then  you have to @{"register" link "Register" 0}.\n@endnode\n\n@node "Bugs" "known bugs...?"\n \n @{b}BUGS@{ub}\n \n Now know Bugs at the Moment...\n@endnode\n\n@node "History" "further versions of MSG·Edit v1.o"\n \n @{b}HISTORY@{ub}\n \n @{b}v0.90 July 19, 1995@{ub}\n \n - Creating the GUI with MUI-Builder v2.2 by Eric Totel\n - Implemented all the needed code, notifications...\n - Implemented Clipbord support\n - Implemented UNDO support\n \n @{b}v0.95 July 20, 1995@{ub}\n \n - Fixed a Bug in the conference selecting where the message should \n   be posted\n - Added a cycle_gadget for choosing the message status\n - Added a string_gadget in the preferences window for the message sender\n - Implemented the online-help for the Editor (text was taken from the \n   textfield.gadget autodoc)\n - Added another new button to the editor for importing external ASCII-files\n \n @{b}v0.96 July 21, 1995@{ub}\n \n - Added a new Menuitem for the Editor to change the Style\n - Added a new Button to let the cursor blink or not\n - Changed thats the Editor remembers the last entered text, if you open\n   the editor again the old text is still in the text buffer.\n\n @{b}v0.97 July 22, 1995@{ub}\n \n - wrote this AmigaGuide-File\n - Implemeted a new WordWrap routine written by @{b}bYtEANdi/tRSi@{ub}\n   (many thanx babe... it work really fine now...)\n\n @{b}v0.98 July 24, 1995@{ub}\n \n - It seems MSGEdit wont work on another System as my, totally rewritten\n   the Tool, now it should work on any System\n - Addet for the Edit Functions a own window\n - Addet in the Preferences window a PopUp Object to select the Sender\n - Addet a own window for the Message Header to make late changes without\n   trashing the already written text. Now possible to enter a subject.\n - Addet to the Editor Functions to change he Paper, the BackPen and Inkpen\n - Addet to the Editor Functions to align text left or right\n\n @{b}v1.0 July 25, 1995@{ub}\n - Added a DropIcon Hook to the Editor gadget, if you drop a text to the\n   Editor the text will automatic insert.\n - Installer Script fixed\n - Corrected the conference selecting, MSGEdit selected always a wrong\n   Conference.\n - Added a security Requester if no message subject is given.\n - first Public Version\n@endnode\n\n@node "MSGEdit" "The main window"\n \n @{b}The Main Window of MSG·Edit@{ub}\n \n @{u}The User ListView:@{uu}\n  - here you can select the User you want to mail.\n  - just double-click the listview or select normally and press the \n    Edit Message Button to open the FullScreenEditor\n    MSG·Edit will look wich conference is AotuReJoin for the User and\n    trys to post the message to the MSGBase of this Conference.\n \n @{u}The Conference Listview:@{uu}\n  - here you can choose the conference where the Message should be posted.\n    (@{fg shine}NOTE:@{fg text} This version @{b}doesn`t check if the User really has access@{ub} to this\n           conf, so you may should post the message to his autorejoin conf\n           selected by MSG·Edit self.)\n\n @{u}The Edit Message Button:@{uu}\n  - Press this Button to open the Editor of MSG·Edit\n\n @{u}The Read Button:@{uu}\n  - Not functionally in this Version\n \n @{u}The Preferences Button:@{uu}\n  - Press this Button to configure MSG·Edit\n \n @{u}The Quit Button:@{uu}\n  - Here you say good bye to this great Tool...\n@endnode\n\n@node "Preferences" "The Preferences window"\n \n @{b}PREFERENCES@{ub}\n \n @{b}BBS Path PopUp:@{ub}    Select your BBS Location via ASL Requester\n \n @{b}User Data PopUp:@{ub}   Select your User.data via ASL Requester\n \n @{b}Sender PopUp:@{ub}      Select the message sender from listview\n                    (@{fg shine}NOTE:@{fg text} you can doubleclick the user, should be your\n                           handle but it is on you who is the sender)\n\n @{b}Save Prefs:@{ub}        Save the actual prefs to s:msged.cfg\n \n @{b}Use Prefs:@{ub}         User the actual prefs\n \n @{b}Cancel Prefs:@{ub}      trash made prefs changes\n@endnode\n\n@node "Editor" "The MsgEditor"\n  \n @{b}THE FULL SCREEN EDITOR@{ub}\n \n @{u}The Buttons:@{uu}\n \n \n @{u}The textfield gadget:@{uu}\n \n 100% Wordwrap Editor with mouse functions for copy/cut/paste functions,\n moveable via the slider, unlimited lines (MSG·Edit will write up to \n 20000 chars to the Message this is more as Joe Hodge in his implemeted\n Editor allows, so you may not use more than 100 Lines)\n\n @{u}The Buttons:@{uu}\n \n @{b}Save Message:@{ub}   Attemp to save the Textbuffer as mail to the seleceted User\n                 in the selected Conference\n @{b}Abort Message:@{ub}  Aborting the Message\n @{b}Online Help:@{ub}    Small online Help\n @{b}Msg Header:@{ub}     Edit the @{"Message Header" link "MsgHeader" 0} for Subject or late changes for the\n                 Message sender or receiver.\n @{b}Editor Options:@{ub} Opens a Button Window with @{"Editor Options" link "EdFunctions" 0}\n\n @{u}The Menue Items:@{uu}\n \n @{b}Save Message:@{ub}   attemp to save the textbuffer as mail to the seleceted user\n                 in the selected conference\n @{b}Abort Message:@{ub}  aborting the message\n @{b}Mail Header:@{ub}    popUp the @{"message header" link "MsgHeader" 0} window\n @{b}Editor Opts:@{ub}    popUp the @{"Editor Buttonbank" link "EdFunctions" 0}\n @{b}Editor Help:@{ub}    pop the help window\n @{b}Quit:@{ub}           quit message editing\n \n @{b}The Editor menu:@{ub} View @{"Editor Options" link "EdFunctions" 0} for reference\n@endnode\n\n@node "Credits" "Bouquets to all who helped"\n \n @{b}BOUQUETS TO ALL WHO HELPED@{ub}\n \n @{u}MSG·EDIT v1.0@{uu}      Copyright © & distributed 1995/7 Bodo Hoffmann \n                    All Rights Reserved\n \n @{u}MSGEdit.guide@{uu}      Copyright © 1995/7 Bodo Hoffmann  All Rights Reserved\n                    written with Heddley v1.1\n \n @{u}MSGEdit.install@{uu}    Copyright © 1995/7 Bodo Hoffmann  All Rights Reserved\n                    written for using Installer licensed under CBM\n \n @{u}MUI v2.3@{uu}           Copyright © 1992/95 Stefan Stuntz \n                    All Rights Reserved\n \n @{u}MUIBuilder@{uu}         v2.2 Copyright © 1994/95 Eric Totel \n                    All Rights Reserved\n\n @{u}textfield.gagdet@{uu}   v3.o Copyright © 1995 Mark Thomas \n                    All Rights Reserved\n \n @{u}ReqTools.library@{uu}   v38.1266 Copyright © 1995 Nico Francois \n                    All Rights Reserved\n \n @{u}Heddley@{uu}            v1.1 Copyright 1994 Edd Dumbill All Rights Reserved\n \n @{u}AmigaGuide@{uu}         v40.4 (C) Copyright 1991-93 Commodore-Amiga, Inc.\n                    All Rights Reserved\n\n @{u}Installer@{uu}          (C) Copyright 1991-93 Commodore-Amiga, Inc.\n                    All Rights Reserved\n@endnode\n\n@node "Innovation" "tRSi (/X·iNNOVAtiON)"\n\n                        @{b}tRSi (/X·iNNOVAtiON) ARE:@{ub}\n \n                               dR.dRE!/tRSi\n                               bYtEANdi/tRSi\n                                SiEGEl/tRSi\n                                 SPY/tRSi\n                                CORtEX/tRSi\n \n              tRSi (/X·iNNOVAtiON) is a @{b}registered@{ub} Trademark\n \n                    @{u}All Rights Reserved by the Members@{uu}\n@endnode\n\n@node "Greetings" "Some hello`s to..."\n \n @{b}SOME GREETINGS@{ub}\n \n bYtEANdi/tRSi  - Kultiges Meeting letztens nur zu wenig Zeit...\n SiEGEl/tRSi    - Olda was is los mit dir ich hör ja garnix mehr von dir!\n SPY/tRSi       - GOIL... bald komm ich so am 14.8 oder so...\n CORtEX/tRSi    - long time but now you are iNNOVAtiON Member WELCOME !!!\n MARiO/tRSi     - bit confused about ... bla bla you know...\n VAMPiRE/tRSi   - Tempest suxx uheeeu\n SAl-ONE/tRSi   - shit can`t call this time but will try meet you one \n                  time in NL...\n MOGUE          - fine you are back or was it a fake ???\n \n ALl Registerd Users - thanx for all your nerves and trust you invest in\n                       my tools...\n \n @{b}ALL I FORGOT...@{ub}\n@endnode\n\n@node "EdFunctions" "Editor Functions"\n \n @{b}EDITOR FUNCTIONS@{ub}\n \n @{b}Clear editor:@{ub}   Clear textbuffer\n @{b}Import ASCII:@{ub}   Import external ASCII file to editor\n                 (@{fg shine}NOTE:@{fg text} The text should not include @{u}more then 75 chars@{uu} per \n                        line and @{u}not more@{uu} as @{fg shine}50kb@{fg text}, and may @{u}not include@{uu} any\n                        ANSI Codes)\n @{b}Copy -> Clip:@{ub}   Copy to Clipboard (@{fg shine}UNIT 0@{fg text})\n @{b}Cut -> Clip:@{ub}    Cut to Clipboard (@{fg shine}UNIT 0@{fg text})\n @{b}Paste <- Clip:@{ub}  Paste from Clipboard (@{fg shine}UNIT 0@{fg text})\n @{b}Undo changes:@{ub}   Undo last changes\n @{b}Center text:@{ub}    Center the text\n @{b}Align left:@{ub}     Align the text left\n @{b}Align right:@{ub}    Align the text right\n @{b}Cursor blink:@{ub}   Cursor blink on/off\n @{b}Change paper:@{ub}   Allows to change the Textfield Paper -> Ruled Paper\n @{b}Change backpen:@{ub} Allows to change the Textfield background color\n @{b}Change inkpen:@{ub}  Allows to change the inkpen\n @{b}Save options:@{ub}   Save actual options to s:msged.prefs\n @{b}Quit options:@{ub}   Close this window\n \n @{fg shine}NOTE:@{fg text} All Functions you can reach also without opening the window by \n       choosing the options from the @{u}editor window menu@{uu}.\n@endnode\n\n@node "MsgHeader" "Msg Header"\n \n @{b}MESSAGE HEADER@{ub}\n \n @{b}From:@{ub}      the message sender choosable in the preferences window\n            (@{fg shine}NOTE:@{fg text} if no sender is specified, the sender will be\n                   @{u}automatic the first user@{uu} from your user.data\n                   even the Sysop)\n\n @{b}To:@{ub}        the message reeiver chooseable in the User Listview\n            (@{fg shine}NOTE:@{fg text} If no receiver is given the Message will be \n                   @{u}automatic EALL@{uu})\n\n @{b}Subject:@{ub}   here you can enter the subject.\n            (@{fg shine}NOTE:@{fg text} if no subject is given and you`ll try to save the \n                   message @{u}this window will popup@{uu}.)\n\n @{b}Status:@{ub}    select the message stats (Public/Private/EALL)\n@endnode\n\n@node "ToDo" "What is to do ?  "\n \n @{b}WHAT IS TODO@{ub}\n \n - Selecting the Editor colors from a own palette\n \n - Supporting Read Messages with reply function\n \n - another GUI, nothing against MUI but it is a bit slow, so the next \n   version will be a Gadtools based GUI.\n \n - NetMail Support\n \n - Multiple Message sending\n \n - Conference Access checking\n \n @{b}So it is on you, register it or send me a postcard if you like this tool\n and you wish to receive further versions.@{ub}\n@endnode\n\n','\n',char(10)),NULL,'auto-added',131321,1,0,NULL,NULL,'trsi_msg','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_muc','TRSI-MUC.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-MUC.LHA','rexxdoor','XIM','REXXDOOR',NULL,'[-Dr.Dre!/tRSi]','TRSI','\        ____   \/   _________/   TRiSTAR \/    \/   _  _/\____  \/    \ RED SECTOR! +-/RtX!  \   |   \_   |   \     \----------+',replace(' /\______________  _____________\n \        ____   \/   _________/   TRiSTAR\n  \/    \/   _  _/\____  \/    \ RED SECTOR!\n+-/RtX!  \   |   \_   |   \     \----------+\n| \  ____/___|__  /_____  / ____/  pRESENTs|\n+--\/-----------\/------\/\/---------------+\n Multi User Comment v1.2 by [-Dr.Dre!/tRSi]\n','\n',char(10)),'DreCom.Guide',replace('@database DreCom 1.2\n\nCopyright (C) 1993 by [-Dr.Dre!/tRSi], Germany\nAll Rights Reserved\n\n@Remark $VER: Version v1.2 (Monday 17-Jan-94 13:32:57)\nRemark AmigaGuide DataBase for Dre Multi Sysop Comment by [-Dr.Dre!/tRSi]\n\n@node MAIN "DreCOm 1.2 (Monday 17-Jan-94 13:32:57) AmigaGuide Document for /X"\n             ____                        ___                     :\n           ._\  /________________________\_/ ____________________¦_ _\n           |  \/   __ _ _               _\_ /_      _/           |\n           |    _ _\         T.R.S.I      // \_    / \_ _     \\ |\n           | ____________________________//____________________\ |\n       ____| \        ___________      /_____        /______  /  |____\n      /\___\  \      /    .|   _/    _/\    /_______/       \/|  /___/\\n      \/___/   \  __/     ¦|   \      \_\_____     \_        ¦|  \___\/\n           |    \/ /      :|    \      /     /      /        :|  |\n           | \    /________|  _  \    /____________/|_________| _|\n           | \\         _ _  \_   \  /_ \\  _ __ _          _ _/ |\n           | \\\           \_/     \/ \_//       /__ _         \ |\n        _ _|________________\__________/ \__________________ /\ _|H2o!\n           ¦                           /\                   /__\\n is proud to present: Dre Multi Sysop Comment 1.1 (Monday 17-Jan-94 13:32:57)\n\n                         @{"     Introduction      " Link no1}\n                         @{"     Requirements      " Link no2}\n                         @{"     Installation      " Link no3}\n                         @{"       Creditz!        " Link no4}\n                         @{"      Greetings!       " Link no5}\n                         @{"     tRSI Boards!      " Link no6}\n@endnode\n@node no1 " Introduction"\n\nThis is a simply but really goo Multi Sysop Comment with some good features.\nhave phun with the door...\n\n[-Dr.Dre!/tRSi]\n\n@endnode\n@node no2 " Requirements"\n\nYou need an Amiga 500/1000/2000/3000 (The Sysops with an A4ooo or A12oo \nshould call my BBS to receive an uncompiled Version)\nKickstart 2.0 or higher\nAmi Express 2.xx - 3.xx (Registered)\nAn running RPStart\nrexxplsextnd.library\nRexxplslib.library\nrexxsyslib.library\nrexxsupport.library\nin your Libs: but they are included\n\nThats all...\n\n@endnode\n@node no3 " Installation"\n\nFirst copy all Libs: (If you dont have them allready) into your libs: Dir\nCopy the C.info to your BBS:Commands/bbscmd/\nand make shure you run rpstart in your Startup-Sequence.\nThen create a Directory called DreCom in your Doors...\nThere you copy all Files and Dirs from the Archive Directory \nBBS/Doors/DreCom/\n\nThere must be in all this Files and Dirs...\n\nDreCom.AiM (40060 - Original Size) The Door self\nDreCom.Cfg (  255 - original Size) The Config File\n\nAfter this jump into the DreCom.Cfg File and change the name of the Sysops\nExplainment for the COnfig File\n------------------cut here------------------\n[-Dr.Dre!/tRSi]\n#1Sysop Description #1\n#1Sysop Description #2 and so on... how much you want\n#2The Answer if the Sysop is choosen by the User #1\n#2The Answer if the Sysop is choosen by the User #2 and so on...\nName of the next Sysop\n#1Sysop #2 Description #1\n#1Sysop #2 Description #2 and so on... how much you want\n#2The Answer if the Sysop #2 is choosen by the User #1\n#2The Answer if the Sysop #2 is choosen by the User #2 and so on...\n------------------cut here------------------\nand so on make so much how you like...\nThis is all what you have to do...\n\n@endnode\n@Node no4 " The Creditz!"\n\n              Copyright (C) 1994 by [-Dr.Dre!/tRSi], Germany\n                            All Rights Reserved\n\n             The AmigaGuide DataBase written by [-Dr.Dre!/tRSi]\n\n    For more good Doors call my BBS under 49 (0) 2131 275756 & 275634\n               · [ · MARLEYS COFFEE SHOP - tRSi GHQ · ] ·\n\n      Thanx to Skin! for using some of your great Style in my Doors!\n\n@endnode\n@Node no5 " Greetings"\n\n                   The Greets are going to this Dudes...\n\n ByteAndi/X-Design, Spy/X-Design, Remo/X-Design, X-Treme/TRSI, Saito/TRSI\n    Gandalf/Faith, Silver/Faith, McLoud/TRSI, Irata/TRSI, Triton/Fth\n Skylark/LSD, Nick, Metoner/TRSI, J.Walker/TRSI, Crazy/TRSI, Valshare/TRSI\n    Vicous/LSD, Richi/Flt, Steve/D&R, Amicom, -rS!, Empire/Mst, Mr.VAiN\n            APOLLO, BJoerN/Pdy, Jive/TRSi, Scope/Trsi, SkiN!\n          and simply all tRSi Member an other Doodes I forgot...\n\n@endnode\n@Node no6 " tRSi Boards Worldwide"\n\n                 To Contact me Call any of this Boards...\n           -==================================================-\n\n   Cauldron.......................German  hq............++49 Pure Elite\n   Marleys Coffee Shop............German  hq............++49 Pure Elite\n   Boondocks......................Europe  hq............+31-548-040-653\n   Final Impact...................Swedish hq............++46-54-113-486\n   Flying Spirits.................Swiss   hq............+41-217-282-524\n   Savage Amusement...............Austia  hq............+43-767-227-743\n   Zenlandia......................Finnish hq............+358-088-82-144\n\n\n           -==================================================-\n@endnode\n','\n',char(10)),NULL,'auto-added',49946,5,0,NULL,NULL,'nvx_rem5','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_mv2','TRSI-MV2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-MV2.LHA','MeGa-VieW','XIM','CheckExe',NULL,'SieGeL/tRSi','TRSI','l___       /      \/    _/_______.: /       /   /  _/\___      /    : /X /_______/-rS!\_____\  _____/   iNNoVaTioN',replace('._________________  ______        .         \nl___       /      \/    _/_______.:         \n  /       /   /  _/\___      /    : /X      \n /_______/-rS!\_____\  _____/   iNNoVaTioN  \n       /_______|     \/`94/_______|         \n MeGa-VieW V2.0 by SieGeL/tRSi - NoW WiTH   \n LHA/DMS/ZIP/ARJ/EXE/SHRINK/GUIDE-SUPPORT   \n USES FILEID.LIBRARY,WILDCARDS,CRSR-KEYS,   \n DL/TESTING FROM ARCHIVES,HEXOUTPUT,ETC..   \n ----------------------------------------   \n THE BEST TXT-VIEWER EVER WRITTEN FOR /X!   \n','\n',char(10)),'MeGa-VIEW.GUIDE',replace('@database MeGa-VieW V2.0 DoCS\n@author "SieGeL/tRSi"\n@(c) "Copyright © 1994 tRSi (/X-iNNoVaTioN)"\n@$VER: MeGa-VieW.guide V2.0 (06-12-94)                                    \n                    \n@index Main\n                                                                        \n@node Main "MeGa-VieW V2.0 - /X-TEXTVIEWER BY SieGeL/tRSi"\n@{b}                /\\____________________  /\\____________________    \n               /   .      .           \\/              /     _/    \n               \\___|      |_______     \\     |_______/      |     \n                   |      |      /    _/_______     \\|      :     \n                   |      |      \\     \\_     /      \\      |     \n                   |      :______|\\     /____________/      |     \n             -  ---|______|--------\\___/-------------|______|--- -\n @{ub}                     (/X-iNNoVaTioN) iS PRouD To PReSeNT @{b}:\n\n                          MeGa-VieW V2.0 BY SieGeL/tRSi@{ub}\n\n       ···C·O·N·T·E·N·T·S··O·F··T·H·I·S··D·O·C·U·M·E·N·T·A·T·I·O·N···\n       ·                                                            ·\n       ····>@{"     INTRODUCTION     " LINK INTRODUCTION}<·····>@{" ALL FOR INSTALLATION " LINK REQUIREMENTS}<····\n       ·                                                            ·\n       ·                        @{" FEATURES! " LINK FEATURES}                        ·\n       ·                                                            ·\n       ····>@{"      TOOL-TYPES      " LINK TOOLTYPES}<·····>@{"     FINAL SALUTE     " LINK GREETINGS}<····\n       \n                     AmigaGuide® Database WRiTTeN BY @{i}SieGeL/tRSi@{ui}\n@endnode\n                                                                             \n@node INTRODUCTION "INTRODUCTION..."\n\nA few month ago I''ve released V1.0(ß) which had the most powerful functions\never written for a Text-Viewer in /X (I think...:) ). After testing it out\nI found many problems which couldn''t be handled correctly by MST-VieW V1.0ß.\nThe worst thing was the fileidentification which only recognize the files by\nchecking out the filename-extension. So all you have to do is rename a text-\nfile into xxxx.LHA and try to view it...V1.0ß tries to open the Textfile as \nLHAarchive and stops with an errormessage. To avoid such fuckin'' shit I have \nrewritten the code. Now MeGa-VieW V2.0 uses the FileID.Library V5 written by\nBloodRock/Syndicate. This Library identifies over @{u}480 different Fileformats@{uu},\nand I think that''s more than enough for use with /X. I''ve tested it out with \ntons of different Files (PC,MAC,AMIGA!) and I could @{b}NOT@{ub} found any mistakes\nin the Fileidentification. \n\nThe second problem in V1.0ß was the errorchecking & -handling, i.e. if a user\nhas Sysopview-Access and he enters v df0:BLA but there is NO DISK IN DRIVE,a\nRequester appears and asks the sysop to enter any disk in drive. What a fatal\nmistake!!! Now @{b}ALL@{ub} AmigaDOS-Errorrequesters would be disabled. The Error-\nmessages will now be generated by the System, so under Workbench 2.1++ the\nmessages were translated into the Language defined in the preferences.\n\nFor a list of all changes take a look to the file @{b}''MeGa-VieW.HISTORY''@{ub}, which\nis included in this package. To get a complete Overview of all ''old'' and new \nfeatures, take a look to @{"FEATURES" LINK QUICKFEATURES}...if you want to install it immediatly \nto your system first take a look to the @{"REQUIREMENTS" LINK REQUIREMENTS}.\n\n@endnode\n\n@node QUICKFEATURES "SHORT OVERVIEW OF THE FEATURES"\n@{u}Features are :@{uu}\n\n - Supports Wildcards (*)\n\n - @{b}Viewing/Downloading@{ub} Files directly from a @{b}LHA/ZIP-Archive@{ub}\n\n - Integrated Sysop-View (editable via @{"Tooltypes" LINK TOOLTYPES})\n\n - Securitycheck for @{"RESTRICTED FILES" LINK RESTRICT}\n\n - Fileidentification via FileID.Library by BloodRock/Syndicate\n\n - New option to @{b}view AmigaGuide® - Databases as ANSI-Files@{ub} \n\n - @{b}DMS/ARJ/EXE/SHRINK@{ub}-Checker supported\n\n - Don''t break viewing if a character with ascii-value >128 was found...\n\n - Supports ''@{b}NS@{ub}'' to view files NonStop...useful for BBS-Adverts..\n\n - Could @{b}Extract@{ub} and show @{b}FILE_ID.DIZ@{ub} from @{b}EXEcutables@{ub} or @{b}DMS-Archives@{ub}\n\n - Extraoption to choose at which Accesslevel a user could view (and test of\n   coz :-} ), otherwise he could only test files/archives...\n\n - @{b}CRSR-Keys@{ub} used to choose a file for viewing/dl''ing from @{b}LHA/ZIP@{ub}-archives\n\n - @{b}Hexadecimaloutput@{ub} (similar to the DirectoryOpus-Function HEXREAD) for all \n   unknown or not supported Files (i.e. MS-DOS Executables!)\n\nand many other cewl Functions....if ya now interested, then @{"install" LINK REQUIREMENTS} it \nto your /X-System...\n@endnode\n                                                                                \n@node REQUIREMENTS "WHAT YOU NEED TO INSTALL MEGA-VIEW"\n@{u}First U need...@{uu}\n\n - any @{b}Amigamodel@{ub} (A500-A4000T) with @{b}Kickstart 2.04++@{ub}\n\n - the installed /X-Software (Tested only on /X 3.xx..don''t know if it\n   runs correctly under /X 2.xx...if someone could test it please @{"INFORM" LINK ADVERT}\n   me !)\n\n - @{b}FileID.Library V5 in LIBS:@{ub}\n\n - To take advantage of the packersupport I recommend to use the following \n   Tools to get the "full power" of MeGa-VieW:\n\n   For @{b}LHA@{ub} use @{b}LHA V1.50r@{ub} (Earlier Versions should work too!)\n   \n   For @{b}DMS@{ub} use @{b}DMS V1.03/V1.11/V1.51/V1.53/V2.01@{ub}\n   \n   For @{b}ZIP@{ub} use @{b}UnZip V5.1@{ub} (@{u}And only this or higher Version@{uu} ,earlier Versions \n                           won''t work correct!!!!)\n\n   For @{b}ARJ@{ub} use @{b}UnARJ V1.15@{ub} (or maybe newer Versions...i have only this Version)\n\n   For @{b}EXE@{ub} use @{b}Executable Hunk Checker V1.0 Beta by Shagratt/LSD@{ub}\n\n   For @{b}GUIDE@{ub} use @{b}GuideToDoc V1.0@{ub} by @{"ByteAndi/TRSi" LINK TRSIMEMBER} (or higher Versions)\n\n   For @{b}SHRINK@{ub} use @{b}SHRINK V1.1@{ub} by Matthias Meixner\n\n   For @{b}FILE_ID.DIZ-Support@{ub} you need @{b}DMSDESCRIPT/EXEDESCRIPT@{ub} by @{b}Remo/MST@{ub} \n  \n - The Device @{b}PIPE:@{ub} already mounted (Used for testing archives...!)\n\n - Some files to view....:)\n\nTo install MeGa-VieW, copy @{b}''MeGa-VieW''@{ub} & @{b}''MeGa-VieW.info''@{ub} to the directory\nwhere you stored your /X-Tools.\n\n@{u}NOTE:@{uu} Make sure that you place the icon in the same directory like the main\n      program, otherwise MeGa-VieW couldn''t find it...!\n\nNow copy the icons @{b}''V.INFO''@{ub} and @{b}''VS.INFO''@{ub} to @{b}BBS:COMMANDS/BBSCMD/@{ub}\n\nCopy @{b}GuideToDoc@{ub} wherever you want.\n\n@{u}NOTE:@{uu} In difference to V1.0, I''ve included the @{b}''VS''@{ub} icon to let you use the\n      Sysopcommand @{b}''VS''@{ub} by using MeGa-VieW similar to the internal viewers.\n\nThat''s all for installation...now some words about the notable @{"FEATURES" LINK FEATURES} of \nMeGa-VieW...\n@endnode\n                                                                       \n@node FEATURES "MAIN FEATURES AND OTHER REASONS TO USE THIS TOOL"\nI don''t believe that you have any problems, coz MeGa-VieW works similar\nto the original /X viewer, but has some more powerful enhancements, like :\n\n@{u}1.) You could use NS@{uu}\n\nIf you want to view a file Nonstop, that means that MeGa-VieW don''t prompt\nyou to continue,etc., all you have to do is to enter NS after the Filename,\ni.e.:\n                           @{b}Diabolo.doc NS @{ub}\n\nwill show Diabolo.doc nonstop..or if you enter :\n\n                              @{b}Dia* NS@{ub}\n\nlets MeGa-VieW search for all patterns matching "DIA*" and then show the \ndesired file nonstop.\nThis works anywhere, you could enter @{b}NS@{ub} after the filename and the selected \nfile will be shown nonstop.\n\n@{u}2.) Using WildCards@{uu}\n\nThis Feature was the main reason why I wrote this Tool ...:) \n\nYou could use wildcards as much as you want it to do so...:) , and in \ndifference to AmieX, you DON''T have to enter three real Chars before\nusing Wildcards, so you could call MeGa-VieW like:\n \n                       @{b}V S:START*@{ub}\n\n...searches for files in S:, which contains the pattern START*...or \nenter something like this :\n\n                       @{b}V S:SH*LL-ST*ART*P NS@{ub}\n\nwill search for all patterns which matches the pattern and then show the\ndesired file NonStop\n                       @{b}V S:*@{ub}\n\n...shows you ALL files which are found in Drawer S:...this works also for\nthe "normal" viewmode (NO SYSOPVIEW), i.e.\n\n                       @{b}V *@{ub}\n\nshows you @{b}ALL@{ub} files which are found in the current DL-Pathes. Nice eh ?! :)\n\n@{u}3.) Testing Archives@{uu}\n\nIf you select a archive, you have always the choice to @{b}test@{ub} it. If MeGa-VieW\nrecognize an archive, you were asked to view the @{b}contents/informations@{ub}...\nenter now @{b}''T''@{ub} and the desired archive will be tested...hope you enjoy the\n@{b}realtime testings via PIPE:@{ub} ...:) Don''t get confused if you see four different\nTestmodes by LHA...LHA V1.50r gives you the option the change the output. I''ve\nincluded a randommode which changes the LHA-Output at every call...so don''t \nthink this is a mistake or a Virus or whatever...it''s only my mad brain..:()\n\n@{u}4.) Filerecognizing@{uu}\n\nNow MeGa-VieW is able to check which filetype you''ve selected by using the\n@{b}FileID.Library@{ub} from BloodRock/Syndicate. It''s no longer possible to confuse\nthe viewer,i.e. Rename a LHA-Archive in xxxxxxxx.DMS and try to view it with\nV1.0...the first Version tries to open it as DMS-archive. In this new Version,\nalso such renamed files will be identified correctly.\n\n@{u}5.) Restricted Files@{uu}\n\nA main changing was the handling of @{"RESTRICTED FILES" LINK RESTRICT}. In V1.0, I only check \nfor Restricted Files defined in ACP. Now MeGa-VieW checks out the @{"ACP" LINK ACP} Icon and\nif not found, it checks now the FileComments for the Keyword ''@{b}RESTRICTED@{ub}''. If\nfound, it breaks and inform the user that this file is restricted. This works\nalso if you select a file from an archive for viewing/downloading, which is \nmarked as restricted.\n\n@{u}6.) CRSR-Keys@{uu}\n\nI you select a @{b}LHA/ZIP-archive@{ub} you will see the contents of this archive and\nyou could now use the @{b}CRSR up/down keys@{ub} to select the file you want to view or\ndownload.\n\n@{u}NOTE:@{uu} MeGa-VieW sorts out some filenames which could make problems, i.e. File-\n      Names like @{b}''#?#?#''@{ub} , @{b}''*''@{ub} @{b}''SECOM CITY.DISPLAYME''@{ub} and so on.\n      I sorted out this files otherwise it is possible that the @{b}whole@{ub} (!) \n      archive will be extracted ! So don''t worry if you don''t find the right \n      file. \n      If you want to view such files, @{u}DOWNLOAD THE ARCHIVE AND TAKE A LOOK@{uu} \n      @{u}AT HOME !@{uu}\n\n      Don''t think I''m lame coz I know that''s possible to extract such files, \n      but always remember : It''s a TextViewer not a replacement for the Down-\n      loadcommand ! \n\n@{u}7.) Downloading FROM archives@{uu}\n\nThis option allows users with the correct Accesslevel to @{b}Download@{ub} a file from\na @{b}LHA@{ub} or @{b}ZIP@{ub}-archive. After selecting the desired File via @{b}CRSR-Keys@{ub}, you were\nasked to Download, view normal or view nonstop the file. Of course you could \nforbid the downloading by deactivating the ToolType @{"DL_LEVEL" LINK DLLEVEL}.\nIf you select @{b}D@{ub} for Download MeGa-VieW checks your ratio (bytes) and \nif you were able to download something, you will receive the selected File \nvia @{b}ZModem@{ub}. If the user has a disabled Ratio no checkings were made.\nThis Option works similar for @{b}LHA and ZIP-Archives@{ub}.\n\n@{u}8.) Hex-Output@{uu}\n\nIf you select a file which couldn''t supported (i.e. MS-DOS Executables or\nSoundmods) MeGa-VieW first tries to identify the File and then you were asked\nto view this file anyway. If you enter ''@{b}Y@{ub}''es you get an @{b}Hexadecimal-Output@{ub}\nfrom the selected File. If you use DirectoryOpus you should know this output,\ncoz it''s exactly the same output like DOpus'' HEXREAD. I have included this \noption to avoid a destroyed Screen, coz normally you won''t VIEW A SOUNDMODULE \nfor example, and if you do so you will see only garbarge on the screen. But \nunder Hexoutput you could read all printable characters without Screen-\nflashings,Beeps and whatever...of coz the file will be checked for @{"RESTRICTED" LINK RESTRICT} \nbefore displaying.\nIt could happen that the FileID.Library don''t recognize a file correctly, in\nthis case you won''t see the Hex-Output ! MeGa-VieW show you the file like a \nTextfile and therefor you will get a destroyed Screen....\n@endnode\n\n@node TOOLTYPES "ALL TOOLTYPE-INFORMATIONS FOR MeGa-VieW V2.0"\n\n                   @{b}All Tooltypes from MeGa-VieW V2.0 :@{ub}\n\n@{u}1) Definitions for Supported Filetypes@{uu}\n\n   @{"    LHA_PATH    " LINK LHA} - Path for LHA\n   @{"    DMS_PATH    " LINK DMS} - Path for DMS\n   @{"   DMS_FILEID   " LINK DMSID} - Path for DMSDescript (FileID_DIZ from DMS)\n   @{"    ZIP_PATH    " LINK ZIP} - Path for UnZIP       \n   @{"    ARJ_PATH    " LINK ARJ} - Path for UnARJ\n   @{"   SHRINK_PATH  " LINK SHR} - Path for SHRINK\n   @{"    EXE_PATH    " LINK EXE} - Path for CheckExe \n   @{"   EXE_FILEID   " LINK EXEID} - Path for EXEDescript (FileID_DIZ from EXEcutables)\n   @{"   GUIDE_PATH   " LINK GUIDE} - Path for GuideToDoc (converts from GUIDE to ANSI)\n\n@{u}2) Other Definitions@{uu}\n                          \n   @{"   TEMP_PATH    " LINK TEMP} - Path for Temporary Files\n   @{"    ACP_PATH    " LINK ACP} - Path to ACP.INFO        \n   @{"   CALLERSLOG   " LINK CALLERSLOG} - Write to CallersLog (YES or NO)\n   @{"   ONLY_CHECK   " LINK ONLYCHECK} - Accesslevel for viewing files\n   @{"    DL_LEVEL    " LINK DLLEVEL} - Accesslevel for Downloading    \n   @{" SYSOPVIEWLEVEL " LINK SYSOPVIEW} - Accesslevel for Sysopview\n\n@endnode\n                                                                            \n@node LHA "SUPPORT OF LHA/LZH-ARCHIVES"\n@{b}                              LHA_PATH=<path>                             \n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you specify the complete path to @{b}LHA@{ub}, i.e. LHA_PATH=C:LHA. If this Tool-\ntype is not set or the path is incorrect, LHA-Support is disabled.\n\nIf you set it correct, users have the ability to @{b}view/download *ONE* file@{ub} \ndirectly from the selected archive. If an user selects a LHA/LZH-archive, he\nwill be asked first to @{b}View@{ub} or @{b}Test@{ub} the desired archive. \nIf the accesslevel defined in @{"ONLY_CHECK" LINK ONLYCHECK} is higher than the user''s access-\nlevel, the viewing is disabled and he could only test archives. \nIf the user selects (@{b}T@{ub})est, MeGa-VieW tests the archive via LHA.\nDon''t get confused if you see four different LHA-Testoutputs, coz I have re-\nwritten the Testroutine to use all Displaymodes available by LHA V1.50r by \nchoosing it randomly.\n\nIf the user selects Viewing, MeGa-VieW first loads in the Contentslist of the\ndesired archive and sorts out filenames with special chars or spaces in it,i.e.\nfiles containing ''#?'', ''*'', ''BBS ADVERT.TXT'' etc. won''t be shown in the list.\nSo if you don''t find your favourite BBS-Advert, DOWNLOAD THE WHOLE ARCHIVE AND\nTAKE A LOOK AT HOME! I have to disable this filenames, coz LHA interprets them\nas command to extract the @{b}WHOLE(!)@{ub} archive...After sorting out U get a list of\nthe remaining files inside the archive in alphabetical order. The list will be\nshown in two rows.The file which is actually selected will be shown in white, \nall other files are blue. Press now @{b}CRSR-UP/DOWN@{ub} to walk through the list. In\nthe middle of the list U could see an arrow pointing to the current selected \nfile. This is useful if you have @{b}ANSI-COLORS off@{ub} in Amiex, coz without \ncolors you won''t see which file you have selected, but with this arrow you \nalways know which file is selected. \nThe @{b}CRSR-Keys LEFT/RIGHT@{ub} are not supported coz you don''t need them.\nIf you scroll over the first/last entry in the list you fly back to the last/ \nfirst file in the list. When U found the file you want to take a look to, \npress ''ENTER'' and the selected file will be extracted from the archive.\n\nIt could happen that there are more files inside the archive as could be \ndisplayed at one time on your screen. In this case you are able to switch to\nthe next entries by pressing @{b}Space@{ub}. If all entries fit on your screen, the\n''@{b}SPACE@{ub}'' - Key is disabled. By pressing ''@{b}ESC@{ub}'' you get back to the Fileprompt\nof MeGa-VieW.\n\nIf the user has an accesslevel higher or equal to the accesslevel defined in\nthe ToolType @{"DL_LEVEL" LINK DLLEVEL}, he could choose between (@{b}D@{ub})ownloading the file, view\nNon(@{b}S@{ub})top, (@{b}Q@{ub})uit to Fileprompt or (@{b}ENTER@{ub}) to view normal. If he choose ''@{b}D@{ub}'' for\nDownloading MeGa-VieW first checks if the user has enough uploads to download\nsomething. If not, MeGa-VieW stops and writes a message. Otherwise the user''s\nUp/Downloading-Statistics and the selected file (with Bytesize) will be \ndisplayed. If he/she has a Disabled Ratio, no checkings were made and a small\ncomment were printed after the DailyBytes. \nPressing (@{b}ENTER@{ub}) starts the @{b}ZModem-Transfer@{ub}, (@{b}A@{ub})borts the transfer.\nAfter a successful transfer the Downloadstats from the user where changed and\nwritten to /X. Then MeGa-VieW jumps back to the fileprompt.\n\nIf the user hasn''t the correct level to Download, he could only choose between \nnormal and Nonstop-View. \n@endnode\n                        \n@node DMS "SUPPORT OF DMS-ARCHIVES"\n@{b}                              DMS_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you specify the complete path to @{b}DMS@{ub}, i.e. DMS_PATH=C:DMS. If this Tool-\ntype is not set or the path is incorrect, DMS-Support is disabled.\n\nIf you set it correct, users have the ability to @{b}view informations@{ub} or to @{b}test@{ub}\nthe desired DMS-archive. If the user wants to test the archive, MeGa-VieW calls\n@{b}DMS@{ub} with the argument ''TEST'' and redirect the output to PIPE:. From PIPE: it\nwill displayed to the user so that it runs in ''@{b}RealTime@{ub}''...:)\n\nIf the user selects ''@{b}View@{ub}'', he will see the Standard-Informations from DMS\n(MeGa-VieW calls @{b}DMS@{ub} with the argument @{b}VIEW@{ub} and redirect the output to a file,\nwhich will be displayed). \n\nIf you have set the ToolType @{"DMS_FILEID" LINK DMSID} correct, MeGa-VieW searches for the\nFiledescription inside the DMS-Archive and if found, you were asked to view it.\nIf you don''t set @{b}DMS_FILEID@{ub}, MeGa-VieW display only the informations\nfrom the archive and get back to the fileprompt.\n\n@{"Thanx" LINK GREETINGS} must go to @{b}Re/Y\o/MST@{ub} for the Program @{b}DMSDESCRIPT V1.0@{ub}...\n@endnode\n\n@node DMSID "SUPPORT OF FILE_ID.DIZ IN DMS-ARCHIVES"\n@{b}                            DMS_FILEID=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you define the complete path to @{b}DMSDescript@{ub} written by @{b}Re/Y\o/MsT@{ub}, i.e.\nDMS_FILEID=C:DMSDESCRIPT. If this Tooltype isn''t set MeGa-VieW wouldn''t \nsearch for @{b}FILE_ID.DIZ@{ub} inside a DMS-archive. If you set this ToolType correct,\nMeGa-VieW search for a Filedescription inside the archive after displaying\nthe informations and if found, it will be displayed to the user.\n \nBig @{"Thanx" LINK GREETINGS} must go to @{b}Remo/MST@{ub} for his @{b}DMSDescript@{ub}.\n@endnode\n\n@node ZIP "SUPPORT OF ZIP-ARCHIVES"\n@{b}                              ZIP_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you specify the complete path to @{b}(Un)ZIP@{ub}, i.e. ZIP_PATH=C:UNZIP. If this\nToolType is not set or the path is incorrect, ZIP-Support is disabled.\n\nIf you set it correctly, users have the ability to @{b}view/download@{ub} a file\ndirectly from a @{b}ZIP-Archive@{ub}. The function of this Support is exactly the same\nlike @{b}LHA-Support@{ub}. If a user has an equal or higher accesslevel as defined in\n@{"DL_LEVEL" LINK DLLEVEL}, he could download @{b}*ONE*@{ub} file from the archive, otherwise he could\nonly view it. For detailed information about the options look in Chapter @{"LHA" LINK LHA},\nas this two packers are both uses the same Selection-Routine.\n\n@{u}NOTE:@{uu} Make sure that you only use @{b}UnZIP@{ub} (or ZIP) upto @{b}V5.1@{ub}, coz this is the \n      first Version that allows you to specify an Extractpath for ''Unzipping''.\n      The second major enhancement from @{b}UnZIP@{ub} is the option to create a \n      Contents-List like @{b}LHA@{ub} (only Names), and therefor I could handle ZIP\n      in the same way...\n      If the ZIP-Support won''t work check out your Version from UnZip. I''ve \n      included the correct Version of UnZIP in this package.\n      All Versions lower than the one i''ve included (V5.1) @{u}WON''T WORK WITH@{uu}\n      @{u}MEGA-VIEW !!!!@{uu}\n@endnode\n\n@node ARJ "SUPPORT OF ARJ-ARCHIVES"\n@{b}                              ARJ_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you specify the complete path to @{b}ARJ@{ub}, i.e. ARJ_PATH=C:UNARJ. If this Tool-\ntype is not set or the path is incorrect, ARJ-Support is disabled.\n\nIf you set it correct, users have the ability to @{b}view@{ub} the contents or to @{b}test@{ub} \nthe desired ARJ-archive. If the user wants to test the archive, MeGa-VieW calls\n@{b}ARJ@{ub} and redirects the Output to PIPE: to show you the testing in ''@{b}RealTime@{ub}''.\n\nIf the user selects ''@{b}VIEW@{ub}'' MeGa-VieW reads in the contents of the ARJ-archive\nand display it to the user. \n\n@{u}NOTE:@{uu} It''s impossible to extract only one file with @{b}UnARJ V1.15@{ub}, which I used\n      to implement this function. If someone has a newer Version which allows\n      extracting of single files, please send it to me and I will rewrite the\n      code to make it possible to view single files (maybe with Downloading\n      like @{"LHA" LINK LHA} or @{"ZIP" LINK ZIP}). \n\nTo get in Contact with me take a look to chapter @{"ADRESS" LINK ADVERT}...\n@endnode\n\n@node SHR "SUPPORT OF SHRINK-ARCHIVES"\n@{b}                            SHRINK_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you specify the complete path to @{b}SHRINK@{ub}, i.e. SHRINK_PATH=C:SHRINK. If \nthis Tooltype is not set or the path is incorrect, SHRINK-Support is disabled.\n\nIf you set it correct, users have the ability to @{b}view@{ub} the contents or to @{b}test@{ub}\nthe desired SHRINK-archive. If the user wants to test the archive, MeGa-VieW \ncalls @{b}SHRINK@{ub} and redirects the Output to PIPE: to show you the testing \nin ''RealTime''...:)\n\nIf the user selects ''@{b}VIEW@{ub}'' MeGa-VieW displays the contents of the selected\nSHRINK-archive via PIPE: .\n\n@{u}NOTE:@{uu} Like @{"UnARJ" LINK ARJ} it''s impossible to extract only one file with @{b}SHRINK V1.1@{ub}, \n      which I used to implement this function. If someone has a newer Version \n      with extracting of single files, please send it to me and I will rewrite \n      the code to make it possible to view single files (maybe with DL''ing\n      like @{"LHA" LINK LHA} or @{"ZIP" LINK ZIP}) from SHRINK-Archives. \n\nTo get in Contact with me take a look to chapter @{"ADRESS" LINK ADVERT}...\n@endnode\n\n@node EXE "SUPPORT OF EXECUTABLES"\n@{b}                              EXE_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you specify the complete path to an @{b}EXEcutable Checker@{ub}, i.e. \nEXE_PATH=C:CHECKEXE. If this Tooltype is not set or the path is incorrect, \nEXE-Support is disabled.\n\nIf you set it correct, users have the ability to @{b}check AmigaDos-Executables@{ub}.\nI use @{b}CheckExe by Shagratt/LSD@{ub}, but you could use every checker which supports\nthe normal DOS-Errorcodes (0,5,10,20). This is important coz if your favourite\nchecker doesn''t return a valid errorcode (i.e. all went okay but Returncode=10)\nyou couldn''t use it with MeGa-VieW. I''m checking the ReturnCodes before \ncontinueing the program, so make sure that the Returncodes are DOS-compatible.\nAlso your ExeChecker should accept the following Syntax:\n\n                          @{b}CHECKEXE <filename>@{ub}\n\nand make sure that your checker supports redirecting of the output,otherwise\nthere could be problems. I have only the CheckExe-Checker, so I couldn''t test\nit with others...\nIf you plan to use ur own coded checker, make sure that you write your outputs\nto Output(), otherwise the Redirection could make problems...!\n\nIf the selected File is packed,MeGa-VieW shows you the used packer (if FileID-\nLibrary recognize the packer of coz..). If you set the ToolType @{"EXE_FILEID" LINK EXEID}\ncorrect, MeGa-VieW searches for the @{b}Filedescription@{ub} inside the Executable after\ndisplaying the Checkerresult and if found asks you to view the description.\nIf you don''t specify the @{b}EXE_FILEID@{ub} ToolType correct, MeGa-VieW return to the\nfileprompt after showing the Informations from the ExeChecker.\n@endnode\n\n@node EXEID "SUPPORT OF FILE_ID.DIZ IN AMIGA-DOS EXECUTABLES"\n@{b}                            EXE_FILEID=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you define the complete path to @{b}EXEDescript@{ub} written by @{b}Re/Y\o/MsT@{ub}, i.e.\nEXE_FILEID=C:EXEDESCRIPT. If this Tooltype isn''t set MeGa-VieW wouldn''t \nsearch for @{b}FILE_ID.DIZ@{ub} inside an Executable. If you set this ToolType correct,\nMeGa-VieW search for a Filedescription inside the executable after testing it.\nIf a description were found it will be displayed to the user. \n \nBig @{"Thanx" LINK GREETINGS} must go to @{b}Remo/MST@{ub} for his @{b}ExeDescript.@{ub}\n@endnode\n\n@node GUIDE "SUPPORT OF AMIGAGUIDE® - DATABASES"\n@{b}                            GUIDE_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you specify the complete path to @{b}GuideToDoc@{ub} by @{"ByteAndi/tRSi" LINK TRSIMEMBER}, i.e.\nGUIDE_PATH=C:GUIDETODOC. If this Tooltype is not set or the path is incorrect,\nGuide-Databases were displayed with all special commands used by AmigaGuide®.\n\nIf you set it correct, users have the ability to view Guidedatabases like an\nnormal Textfile without the annoying ''@{b}@@{ub}'' , ''@{b}{}@{ub}'' and other commands only used\nby AmigaGuide. To convert the desired Guide into an @{b}ANSI-File@{ub} you need the\nCLI-Tool ''@{b}GUIDETODOC V1.0@{ub}'' written by @{b}ByteAndi/tRSi@{ub}. You could use this Tool to\nconvert any Guide-Database to an normal @{b}ASCII/ANSI@{ub} file. The Syntax for this\nTool is :\n          @{b}GUIDETODOC <GUIDE> <ANSI>@{ub}\n\nWere @{b}<GUIDE>@{ub} is the Guide you want to convert and @{b}<ANSI>@{ub} is a switch which\nlet''s you choose to convert to @{b}ANSI@{ub} or to @{b}plain ASCII@{ub}. For Ansioutput enter\nthe Keyword ANSI after the Filename. The converted Guidefile will be displayed\nto @{b}stdout@{ub}, which is normally the Shell you''ve started the Tool from. To get\nan @{b}ANSI-File@{ub} on disk simply redirect the output to the desired File, i.e. a\nvalid call is : \n\n        GUIDETODOC >RAM:VIEWER.DOCS CWORK:DOCS/MeGa-VieW.GUIDE ANSI\n\nThis will convert the Guide ''@{b}CWORK:DOCS/MeGa-VieW.GUIDE@{ub}'' into an ''@{b}ANSI@{ub}''-File\nwhich will be created in ''@{b}RAM:@{ub}'' as ''@{b}VIEWER.DOCS@{ub}'' .\n\nMeGa-VieW calls GuideToDoc with the @{b}ANSI-Argument@{ub} and redirect the output to\na file temporary stored in ur @{b}Temp-Dir@{ub} (Could be set via @{"TEMP_PATH" LINK TEMP} ).\n\nAfter displaying the converted ANSI-File will be deleted.\n\n@{u}NOTE:@{uu} During the @{b}Big Busts@{ub} in Berlin and Germany @{b}ByteAndi/tRSi@{ub} was not able \n      to complete GuideToDoc...the included Version is only able to convert\n      the most used commands like ''@NODE'' etc...so if a DataBase contains \n      commands to switch to italics or something else this commands will be\n      skipped and not converted...\n\nYou could use (of course..:) your own converter, but make sure that your\nconverter returns the correct Errorcodes ! See Chapter @{"CHECKEXE" LINK EXE} for more\nInformations...\n@endnode\n\n@node TEMP "DEFINITION FOR A TEMPORARY WORKPATH USED BY MeGa-VieW"\n@{b}                             TEMP_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you could enter an alternate path for @{b}temporary files@{ub} which are used for\nextracting and converting files. This Tooltype must not be set, coz the \nDefault-Setting is ''@{b}RAM:@{ub}''. If you have not enough free Memory you should set\nit to a valid AmigaDOS-Path, i.e. "TEMP_PATH=DH0:T/" . All packers and other\nTools controlled by MeGa-VieW uses the path you defined here for extracting,\nconverting or whatever. \n\n@{u}NOTE:@{uu} When you want to use the Ram-Disk as Temppath, always enter ''@{b}RAM:@{ub}'' as\n      path coz the Ram-Disk is a dynamic Drive and therefor RAM: is always\n      @{u}full (0 Bytes free!!)@{uu} . To let it work I have included two checkroutines.\n      The first one checks normal ADOS-Devices like DF0:, HD0: etc. if there \n      is enough space on it. The second one will be activated only if you \n      enter @{b}RAM:@{ub} as path or disable this ToolType. In this case, MeGa-VieW \n      will check your @{b}FREE MEMORY@{ub} instead of checking the free space on \n      the device. Other devices @{b}WOULDN''T BE@{ub} recognized, so @{b}T:@{ub} will be \n      checked as Device, not for FreeMem !!!!\n@endnode\n\n@node ACP "HOW TO FIND YOUR ACP-ICON TO LET IT WORK CORRECTLY"\n@{b}                              ACP_PATH=<path>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you specify the path to your @{b}ACP-Icon@{ub}. Normally, it''s not necessary to\ndefine this ToolType, but some Sysops told me that MeGa-VieW didn''t find ACP\ncoz they have no Searchpathes defined. If MeGa-VieW couldn''t find your ACP,\nenter as <path> a valid AmigaDos-Path to your ACP.\n\n@{u}NOTE:@{uu} In difference to the Packer-ToolTypes, you must define the @{b}PATH ONLY!@{ub}\n      Don''t enter here for example BBS:ACP, coz this results in BBS:ACP/ACP !\n      If your ACP will be found in BBS:, enter ACP_PATH=BBS: . I''m using this\n      ToolType coz I have no BBS online and therefor it won''t be started via\n      WBStartup. MeGa-VieW won''t found ACP without this ToolType, so I define\n      this ToolType with my BBS-Directory (ACP_PATH=BBS:) and all works. \n\nThis Tooltype is disabled by default (closed in Branches () ) and I recommend\nfirst to try it without this ToolType. If MeGa-VieW reports that ACP couldn''t\nfound define it to the path were ACP could be found and all should work now.\n@endnode\n\n@node CALLERSLOG "ADDING COMMENTS TO CALLERSLOG"\n@{b}                             CALLERSLOG=<YES|NO>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you could choose if MeGa-VieW should add a comment to the Callerslog when\na user tries to @{b}view/download a Restricted File@{ub}. By default, this Option is\ndisabled. To enable it, set the ToolType to @{b}YES@{ub}, i.e. CALLERSLOG=YES. For more\ninformations about @{b}Restricted Files@{ub} take a look to @{"RESTRICTED FILES" LINK RESTRICT}.\n\n@{u}NOTE:@{uu} If you run a multinodeboard it could happen that Amiex @{b}crashes@{ub} while\n      MeGa-VieW adds the comment. @{u}This is not a bug from me !!@{uu} So don''t think\n      lame ''bout me when you see a guru while adding the comment. If this \n      happens, @{b}disable@{ub} this option (CALLERSLOG=NO) and you have no problems\n      anymore.\n      I don''t know what AmieX does when two programs want to add a comment\n      but this error should only happen on all AmieX-Versions @{b}<@{ub} 3.20 ... If\n      you have a higher Version from AmieX (of coz ONLY REG. Versions !) and\n      this error occurs, please @{"INFORM" LINK ADVERT} me and i try to inform the Authors of\n      AmieX to fix this problem.\n\n@endnode\n\n@node ONLYCHECK "HOW TO CHOOSE BETWEEN VIEWING & TESTING"\n@{b}                           ONLY_CHECK=<accesslevel>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you define which accesslevel is needed to @{b}View files/archives@{ub}. If you\ndon''t specify this ToolType @{b}NO@{ub} user could view anything. If you set it correct,\ni.e. ONLY_CHECK=50, all users with an accesslevel @{b}>=@{ub} 50 could view files with\nthe full support of all packers. All users with an accesslevel @{b}<@{ub} 50 could only\n@{b}test archives@{ub}, @{b}viewing of textfiles is disabled@{ub}. Don''t need to write more bout\nthis option, I think...\n@endnode\n\n@node DLLEVEL "ACCESSLEVEL TO DOWNLOAD FROM LHA/ZIP-ARCHIVES"\n@{b}                           DL_LEVEL=<accesslevel>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nThis ToolType defines at which accesslevel a user could Download @{b}*ONE*@{ub} File\nfrom a @{b}LHA/ZIP-archive@{ub}. If this ToolType is not set or the user''s accesslevel\nis below the level defined here, the Downloadoption for @{b}LHA/ZIP@{ub} is disabled,\nand the user could only view files. If the user has an accesslevel equal or\nhigher then the one defined here then he could choose if he want to @{b}view@{ub} or\n@{b}download@{ub} a file from @{b}LHA/ZIP@{ub}. \n\n@{u}NOTE:@{uu} If a user has the Accesslevel for @{b}SYSOPVIEW@{ub} but not for Downloading,\n      then the Downloading is disabled, too. @{"SYSOPVIEWLEVEL" LINK SYSOPVIEW} doesn''t overwrite\n      this to avoid Leeching from CoSysOps or other people who wants to abuse\n      such a option.\n\nWhen a user could Download, MeGa-VieW checks two things before starting the\nDownload. First, MeGa-VieW checks if the user has already enough Uploadbytes\nto download the selected File. The check is simple but good: MeGa-VieW take\nthe Bytes uploaded by the user and adds the Bytesize of the file he wants to \nDL. If the result is higher than the uploaded Bytes, MeGa-VieW stops and \ninform the user that he has ''@{b}Exceeded Bytes Limit@{ub}''. If the user has \nenough Uploadbytes to Download the selected File, MeGa-VieW checks if the \nuser''s DailyBytesLimit will be high enough to download the file. If both \nchecks are okay, MeGa-VieW starts the ZModem-Transfer. \n\nIf the User has a disabled Ratio, the checkings were skipped and he could \nDownload a file no matter which Byte-Stats he has...\n\nAfter transfering the File, MeGa-VieW adds the filelength of the downloaded \nfile to the users Dl-Stats and returns to the Fileprompt.\n@endnode\n\n@node SYSOPVIEW "DEFINITION FOR SYSOPVIEW"\n@{b}                       SYSOPVIEWLEVEL=<accesslevel>\n-  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -  -\n@{ub}\nHere you could define at which level users could view files @{b}outside@{ub} the BBS-\npathes, i.e. the user could enter ''@{b}V DOCS:MeGa-VieW.GUIDE@{ub}''. This ToolType \noverrides the @{"ONLY_CHECK" LINK ONLYCHECK} access. \n\nOf course all checkings for restricted Files will be made before displaying\nthe selected File to the user. If you don''t specify it @{b}NO@{ub} users could view\nanything outside the regular BBS-Pathes. I have defined this Tooltype to the\naccesslevel of my Cosysops so they could view private files as long as they\nwere not marked as restricted.\n\nTo use the @{b}SYSOPVIEWCOMMAND@{ub} I''ve included an icon called ''@{b}VS@{ub}'' which let''s you\nuse MeGa-VieW similar to the @{u}original internal SYSOPVIEW-Command@{uu}. This Icon\nis not neccassary to use the @{b}SYSOPVIEW@{ub}, but made things easier for you...:)\n\n@endnode\n\n@node RESTRICT "INFORMATIONS ABOUT RESTRICTED FILES"\n                         @{b}RESTRICTED FILES@{ub}\n\nAmieX has the ability to @{b}protect@{ub} Files against @{b}Downloading/Viewing@{ub} by adding\na FileComment (RESTRICTED) to those files. They are defined in the @{b}ACP-Icon@{ub}\nwith the ToolType @{b}RESTRICT.x=<file>@{ub}. When you start your BBS all Files defined\nas Restricted in ACP were marked as Restricted in the FileComments. If you want\nto protect other files not defined in ACP then add a FileComment to this file\nwith the DosCommand @{b}FileNote@{ub}. Take a look to your Dos-Manual for a detailed \nCommandsyntax.\n\nEverytime a user tries to @{b}view/download@{ub} such files MeGa-VieW informs the user\nthat this File is restricted and if you have @{"CALLERSLOG=YES" LINK CALLERSLOG} a Comment would be\nadded to your Callerslog with the complete Filename of the File the user tries\nto view.\n\n@endnode\n\n@node GREETINGS "DA GREETINGSLIST..."\n\n@{b}Greetings fly to...@{ub}\n\nByteAndi/tRSi      - For many help & writing GuideToDoc...(FUCK BUSTS!)\n\nRemo/MST           - For his great Programs ''EXEDESCRIPT'' & ''DMSDESCRIPT''..\n\nDr.Dre/tRSi        - For checking out this Dox about lame errors...:)\n\nDelta-X/Neon       - Yo Man...wir machen dat schon....:)\n\nRapid/SCL          - Cewl Ascii''s Dude...Go on man...\n\nBloodRock/SDC      - Your FileID.Library is the BEST!\n\naRGoN              - Traden Roolez ne war Oldae ? :)\n\nScorpio/SR         - Cewl ''VOICING'' last time...:) Hope to hear from you...\n\naXe/MYSTiC         - Don''t worry be happy....\n\n''WERNER'' (BROESEL) - Boelkstoff roolez !\n\ndEATH aNGEL        - Cewl testing...you''re one of the best Betatester..grins..\n\n ...and of coz all BETA-Testers, TRSi & NEON-Members all around the Globe...\n\n      ...Special Greetings must go to all busted Sysops & Traders...\n\n@{b}PS: THE ONLY WAY TO MULTITASK ON MS-DOS IS TO RUN IBeM TWICE ON AN AMIGA!@{ub}\n@endnode\n\n@node ADVERT "TO GET IN TOUCH WITH ME TRY THIS BOARD"\n\n@{u}SPECIAL NOTE!@{uu}\n\nWell, normally you will see here a Advert from one of our BetaSites, but the\nGerman Police don''t like BBS'' and so they have busted all our BetaSites...\n\nOnly a few Boards are already online in Berlin and if you want to get in\nTouch with me write a message to ARGON^SIEGEL...i think you will found this\nAccount in wellknown Boards all over the World...\n\nIf you are a german guy or U have the ability to call Germany then try to call\nthis Board...\n\n                      _____________ _______   ______       ________  _________\n _ ___ ____ ________ _\\_   _/     /_\\___   \\__\\_   /____ _/  _____/__\\__     /\n          //       //     _      /     /    /     /    /_\\____     / __/    /_\n         //       //      /     /    _/    /    _/    /     _/    /  \\_____/ /\n  __ ___//_______//______/_____/__________/__________/___________/__________/\n  AMIGA - CONSOLE - PC                              ________   ____________\n                  __________________________     ___\\___    \__\\___       /\n                  \\                    _ __/___ /      /     /    /______/\n  _ __ ____________\\   · nEOn gHQ ·            /     _/     /    _____/\n                    \\                 /\\      /____________/_______/\n  _____________      \\               /  \\  tRSi (/X-iNNoVaTioN) BeTa SiTe\n  \\           /    __________ ______/_   \\_  _________\n   \\    _____/_____\\___     /_\\__    /____/__\\____    \\_ __________ ___ __ _\n    \\   \\____    /   _/  __/   _/    \\_   \\_     /     //         //\n     \\     /    /   _     \\_  _       /    /    /     //  ·Rpd!  //\n      \\________/____\\      /__\\      /____/____/_____//_________//___ __ _\n                     \\    /    \\    /\n  Sysop: Delta-X/Neon \\  /      \\  / Co''s: DBF ARGON^SIEGEL STINGRAY BUSY BEE\n                       \\/        \\/      \n  #1:+49-XXXX-ASK-DX                 #2:+49-XXXX-ASK-DBF\n \n  ...Ask da Elite or a NEON-Member for numbers and NewUser/Systempassword...\n\n@endnode\n\n@node TRSIMEMBER "ALL MEMBERS IN tRSi (/X-INNOVATION)"\n                           .                                         \n         .\n         :                 :\n - - -- -+- -- -- - -- - - + - --    /·/\n         :                 :        /·/\n         !                 :       /·/\n         ¡       _________/\\______/\\/   ____/\\_________\n         :       \\_  __  _  \\_ ____ \\__/    __________/       .\n         `- -- - --\\_/    \\  /   _/ _/____  \\  \\/free!\\       .\n                   _/      \\/   /    \\_   \\_    \\_     \\_     :\n                   \\_____   \\___\\   __/_____     /  ____/- - -+- - -\n                    \\___\\____/\\__\\__/\\____/\\____/____/_/      !\n                         \\___\\/   \\_\\/    \\/___/____/         ¡\n                           /·/  (/X-iNNoVaTioN)   :           :\n                          /·/                     `- -- - -- -''\n                         /·/    ·M·E·M·B·E·R·S·\n\n                    ----------------------------------\n                        Dr.Dre!/tRSi (/X-iNNoVATioN)\n                       ByteAndi/tRSi (/X-iNNoVATioN)\n                         SieGeL/tRSi (/X-iNNoVATioN)\n                            Spy/tRSi (/X-iNNoVATioN)\n                    ----------------------------------\n\n@endnode\n','\n',char(10)),NULL,'auto-added',166699,3,0,NULL,NULL,'trsi_mv2','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_mw','TRSI-MW.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-MW.LHA','message','XIM','message',NULL,'[-Dr.Dre!/tRSi]','TRSI','\        ____   \/   _________/   TRiSTAR \/    \/   _  _/\____  \/    \ RED SECTOR! +-/RtX!  \   |   \_   |   \     \----------+',replace(' /\______________  _____________            \n \        ____   \/   _________/   TRiSTAR  \n  \/    \/   _  _/\____  \/    \ RED SECTOR!\n+-/RtX!  \   |   \_   |   \     \----------+\n| \  ____/___|__  /_____  / ____/  pRESENTs|\n+--\/-----------\/------\/\/---------------+\nMost Wanted Rquest Door - by [-Dr.Dre!/tRSi]\n............................................\n','\n',char(10)),'Want.Guide',replace('@database Most Wanted v1.1 by [-Dr.Dre!/tRSi]\n\nCopyright (C) 1993 by [-Dr.Dre!/tRSi], Germany\nAll Rights Reserved\n\n@Remark $VER: Version v1.1 (Monday 17-Jan-94 13:32:57)\nRemark AmigaGuide DataBase for Most Wanted v1.1 by [-Dr.Dre!/tRSi]\n\n@node MAIN "Most Wanted v1.1 (Monday 17-Jan-94 13:32:57) Document for /X"\n             ____                        ___                     :\n           ._\  /________________________\_/ ____________________¦_ _\n           |  \/   __ _ _               _\_ /_      _/           |\n           |    _ _\         T.R.S.I      // \_    / \_ _     \\ |\n           | ____________________________//____________________\ |\n       ____| \        ___________      /_____        /______  /  |____\n      /\___\  \      /    .|   _/    _/\    /_______/       \/|  /___/\\n      \/___/   \  __/     ¦|   \      \_\_____     \_        ¦|  \___\/\n           |    \/ /      :|    \      /     /      /        :|  |\n           | \    /________|  _  \    /____________/|_________| _|\n           | \\         _ _  \_   \  /_ \\  _ __ _          _ _/ |\n           | \\\           \_/     \/ \_//       /__ _         \ |\n        _ _|________________\__________/ \__________________ /\ _|H2o!\n           ¦                           /\                   /__\\n       is proud to present: Most Wanted v1.1 (Monday 17-Jan-94 13:32:57)\n                         @{"     Introduction      " Link no1}\n                         @{"     Requirements      " Link no2}\n                         @{"     Installation      " Link no3}\n                         @{"      Menu Help!       " Link no4}\n                         @{"       Creditz!        " Link no5}\n                         @{"      Greetings!       " Link no6}\n                         @{"     tRSI Boards!      " Link no7}\n@endnode\n@node no1 " Introduction"\n\nmay this is the best and comformst Request Door alltimes...\n\nhave phun with the door...\n[-Dr.Dre!/tRSi]\n\n@endnode\n@node no2 " Requirements"\n\nYou need an Amiga 500/1000/2000/3000 (The Sysops with an A4ooo or A12oo \nshould call my BBS to receive an uncompiled Version)\nKickstart 2.0 or higher\nAmi Express 2.xx - 3.xx (Registered)\nAn running RPStart\nrexxplsextnd.library\nRexxplslib.library\nrexxsyslib.library\nrexxsupport.library\nin your Libs: but they are included\n\nThats all...\n\n@endnode\n@node no3 " Installation"\n\nFirst copy all Libs: (If you dont have them allready) into your libs: Dir\nCopy the Want.info to your BBS:Commands/bbscmd/\nand make shure you run rpstart in your Startup-Sequence.\nThen create a Directory called Want in your Doors...\nThere you copy all Files and Dirs from the Archive Directory \nBBS/Doors/Want/\n\nThere must be in all this Files and Dirs...\n\nmessage                    10016 (Messagebase Tool)\nwant.Header                  263 (Output header)\nwant.Aim                   68492 (The Door)\nwant.cfg                     233 /The COnfig File)\n\nAfter this jump into the Chat.Cfg File and change the Level...\n\n--------------------Cut here--------------------\nBBS:Request/\nbbs:Request/want.txt\n50\n200\n253\n--------------------Cut here--------------------\n\nLine1= Path to your Request Conference where the Msg''s are posted\nLine2= Path to the Final Output txt\nLine3= Level to make an Valid request\nLine4= Level allows to make the Request Message EALL\n       Levels below are only ALL Messages\nline5= Level allows to remove/edit Requests\n\nLoad your Bull.<lvl>.txt(gr) into your editor an display the OutputFile\nvia an MCI Command like this..\n--------------------Cut here--------------------\n~\n~f ;clear Screen\n~SS_BBS:REQUEST/WANT.TXT <- Note the Space after the Mci Command\n--------------------Cut here--------------------\n\n@endnode\n@Node no4 " Menu Help"\n                            _ ___     __     ___ _\n                                /___ /\_\ ___\\n                               .::::.\/_/.::::.\n\n                      [®] Most Wanted  Request Door [©]\n                      [®]  © by Dr.Dre! - tRSi! `94 [©]\n\n              ._______________________________________________.\n              |                                               |\n              |        1) .........Make Request.......        |\n              |        2) .......Remove Request.......        |\n           --+O---     3) .........Edit Request.......     --+O---\n              |        4) .........View Request.......        |\n              |        Q) ..............Exiting.......        |\n              |                                               |\n              !_______________________________________________!\n                                   __ :\n                                  /\_\:> \n                                  \/_/:\n                                      ·\n\n                    This is the Main menu from the Door\n\n1. Make an Valid Request\n2. Remove old Request(s)\n3. Edit Request File\n4. View Requests\nQ. Exit the Door\n\n@endnode\n@Node no5 " The Creditz!"\n\n              Copyright (C) 1994 by [-Dr.Dre!/tRSi], Germany\n                            All Rights Reserved\n\n             The AmigaGuide DataBase written by [-Dr.Dre!/tRSi]\n\n    For more good Doors call my BBS under 49 (0) 2131 275756 & 275634\n               · [ · MARLEYS COFFEE SHOP - tRSi GHQ · ] ·\n\n      Thanx to Skin! for using some of your great Styles in my Doors!\n\n@endnode\n@Node no6 " Greetings"\n\n                   The Greets are going to this Dudes...\n\n ByteAndi/X-Design, Spy/X-Design, Remo/X-Design, X-Treme/TRSI, Saito/TRSI\n    Gandalf/Faith, Silver/Faith, McLoud/TRSI, Irata/TRSI, Triton/Fth\n Skylark/LSD, Nick, Metoner/TRSI, J.Walker/TRSI, Crazy/TRSI, Valshare/TRSI\n    Vicous/LSD, Richi/Flt, Steve/D&R, Amicom, -rS!, Empire/Mst, Mr.VAiN\n            APOLLO, BJoerN/Pdy, Jive/TRSi, Scope/Trsi, SkiN!\n          and simply all tRSi Member an other Doodes I forgot...\n\n@endnode\n@Node no7 " tRSi Boards Worldwide"\n\n                 To Contact me Call any of this Boards...\n           -==================================================-\n\n   Cauldron.......................German  hq............++49 Pure Elite\n   Marleys Coffee Shop............German  hq............++49 Pure Elite\n   Boondocks......................Europe  hq............+31-548-040-653\n   Final Impact...................Swedish hq............++46-54-113-486\n   Flying Spirits.................Swiss   hq............+41-217-282-524\n   Savage Amusement...............Austia  hq............+43-767-227-743\n   Zenlandia......................Finnish hq............+358-088-82-144\n\n\n           -==================================================-\n@endnode\n','\n',char(10)),NULL,'auto-added',115374,3,0,NULL,NULL,'trsi_mw','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_nus','TRSI-NUS.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-NUS.LHA','rexxdoor','XIM','REXXDOOR',NULL,'[-Dr.Dre!/tRSi]','TRSI','\        ____   \/   _________/   TRiSTAR \/    \/   _  _/\____  \/    \ RED SECTOR! +-/RtX!  \   |   \_   |   \     \----------+',replace(' /\______________  _____________            \n \        ____   \/   _________/   TRiSTAR  \n  \/    \/   _  _/\____  \/    \ RED SECTOR!\n+-/RtX!  \   |   \_   |   \     \----------+\n| \  ____/___|__  /_____  / ____/  pRESENTs|\n+--\/-----------\/------\/\/---------------+\n  New User Server 1.o - by [-Dr.Dre!/tRSi]  \n............................................\n','\n',char(10)),'NupCom.Guide',replace('@database New User Server v1.o by [-Dr.Dre!/tRSi]\n\nCopyright (C) 1993 by [-Dr.Dre!/tRSi], Germany\nAll Rights Reserved\n\n@Remark $VER: Version v1.1 (Monday 17-Jan-94 13:32:57)\nRemark AmigaGuide DataBase for New User Server v1.o by [-Dr.Dre!/tRSi]\n\n@node MAIN "New User Server v1.o (Monday 17-Jan-94 13:32:57) Document for /X"\n             ____                        ___                     :\n           ._\  /________________________\_/ ____________________¦_ _\n           |  \/   __ _ _               _\_ /_      _/           |\n           |    _ _\         T.R.S.I      // \_    / \_ _     \\ |\n           | ____________________________//____________________\ |\n       ____| \        ___________      /_____        /______  /  |____\n      /\___\  \      /    .|   _/    _/\    /_______/       \/|  /___/\\n      \/___/   \  __/     ¦|   \      \_\_____     \_        ¦|  \___\/\n           |    \/ /      :|    \      /     /      /        :|  |\n           | \    /________|  _  \    /____________/|_________| _|\n           | \\         _ _  \_   \  /_ \\  _ __ _          _ _/ |\n           | \\\           \_/     \/ \_//       /__ _         \ |\n        _ _|________________\__________/ \__________________ /\ _|H2o!\n           ¦                           /\                   /__\\n  is proud to present: New User Server v1.o (Monday 17-Jan-94 13:32:57)\n                         @{"     Introduction      " Link no1}\n                         @{"     Requirements      " Link no2}\n                         @{"     Installation      " Link no3}\n                         @{"      Menu Help!       " Link no4}\n                         @{"       Creditz!        " Link no5}\n                         @{"      Greetings!       " Link no6}\n                         @{"     tRSI Boards!      " Link no7}\n@endnode\n@node no1 " Introduction"\n\nThis Door can protect your BBS for undesirable New User Accounts.\nBuild this in and have no dead Accounts in your BBS...\nThis is a 100% Protection for you...\n\nI run this Door since Month successfull, and No Lamer have ever seen\nany Ascii from my BBS...\n\nhave phun with the door...\n[-Dr.Dre!/tRSi]\n\n@endnode\n@node no2 " Requirements"\n\nYou need an Amiga 500/1000/2000/3000 (The Sysops with an A4ooo or A12oo \nshould call my BBS to receive an uncompiled Version)\nKickstart 2.0 or higher\nAmi Express 2.xx - 3.xx (Registered)\nAn running RPStart\nrexxplsextnd.library\nRexxplslib.library\nrexxsyslib.library\nrexxsupport.library\nin your Libs: but they are included\n\nThats all...\n\n@endnode\n@node no3 " Installation"\n\nFirst copy all Libs: (If you dont have them allready) into your libs: Dir\nCopy the Quest.info to your bbs/commands/SysCmd/\nand the NupCom.Info to your BBS:Commands/bbscmd/\nand make shure you run rpstart in your Startup-Sequence.\nThen create a Directory called LogoSnap in your Doors...\nThere you copy all Files and Dirs from the Archive Directory \nBBS/Doors/NupCom/\n\nThere must be in all this Files and Dirs...\n\nUsers                        Dir (Directory for the New Usersanswers)\nValUsers                     Dir (Directory for already Validated Users)\nNup-Comment.AiM            54096 (The New User Script Door)\nNupo.AiM                   96064 (The Nup Comment Server)\nNuPCom.cfg                  1402 (The Script\nName.Access                   16 (Access File for the Server)\nName.no                    empty (Names not accepted in your BBS)\nName.in                    empty (New User Data File)\nName.val                   empty (Conatin File for Validated Users)\nNuPCom.help                  799 (Help File for the NupCom Script)\n\n-----------------------------------------------------------------------\nEdit the Name.Access File in your Editor.\n--------------------Cut Here--------------------\nSysop_Name\nCosysop_Name.1\nCosysop_Name.2\n--------------------Cut Here--------------------\nWrite here the Names down from all Dudes you wish to have Access to the\nNup COm Server...\n-----------------------------------------------------------------------\n\n\n\n-----------------------------------------------------------------------\nEdit the Name.no File in your Editor.\n--------------------Cut Here--------------------\nName.1\nName.2\nName.3\n--------------------Cut Here--------------------\nWrite here all Names down you dont wish to login your BBS as Newuser.\nIf the User comes in, then he will receive a funny message and will kicked\nout your BBS...\n-----------------------------------------------------------------------\n\n-----------------------------------------------------------------------\nNo Edit the Nupcom.cfg\nThis is the NewUser Script... here you can ask the NewUser many stupid\nQuestions and you can decide then about him. let him in or not...\n-----------------------------------------------------------------------\nSymbol Definitions:\n-------------------\n# Display Line only\n* Normal Question\n! Question which must Answered\n-----------------------------------------------------------------------\nExample...\n\n#If you will receive Access here so you have to Answer all Questions !\n^All Lines with this Sign at the first Char want only displayed...\n\n#Enter some Lines about your self...\n!1:\n*2:\n*3:\nThe Line with the "!" at the first Char must be answered by the user...\nNo Accepting from empty Lines or spaces...\nThe Lines with the "*" at the first Char can answered but dont must...\nEasy or not.... \nThere are 2 example scripts includet...\n-----------------------------------------------------------------------\n\nThe load your NewUserpw.txt(gr) into your Editor...\nBuild the Script into the Text with an MCI Command...\n----------------Cut here-----------------\n~\n~f\n\n      This BBS is a PRIVATE SYSTEM. Only private citizens who are not\n involved in government or law enforcement activities are authorized to use\n  it. The users are not authorized to divulge any information gained from\n   this system to any government or law enforcement agency or employee.\n   No person is to violate FCC, copyright, or other lawful regulations.\n All data that is received is assumed within the Public Domain. Should anyone\n    advise us to the contrary, we will investigate and remove materials\n not compatible with these regulations and is our sole extent of liability.\n        Again; access to this system by ANY law enforcement agency\n  (Federal, State, Local or other), software company, telephone company,\n government agency, or anyone affiliated with the above is not allowed. This\n is a private system; the above rules are in place to assure members rights\n   are not violated.  Dove hai trovato questo numero? (MOLTO importante)\n   If you agree to the above rules then you are here on the right Place!\n\n~CC_NUP ;<- Note the Space after th MCI Command\n----------------Cut here-----------------\nThe new user Logon looks now like this Example:\n\n        ATTENTION: This is a totally closed Bulletin Board System.\n        If you wanna Access here, so Answer the following Questions\n        very Accuratly. May then you will receive an Account here !.\n                                da staff...\n\n\n You know the NewUserPassword? (y/N) >: n ( <-'' )\n\n Please enter your Handle >:\n\nIf he enters no then the user have to enter his handle...\nAfter this the Doors checks in the File Name.no is there the name in then\nthe user will disconnected from the BBS with a nice message... hehe\nIf not so then your Script (NupCom.cfg) will executed.\nAfter filling out the Questions the User will disconnected from your BBS.\nAnd you have no dead or unlike Accounts in your User.data.\nYou can free decide if you let the User in or not...\n\nNow you can call from your BBS the Command NupCom and can handle all New\nUsers Answers many easy from the NupCom Server...\n\nThis is all what you have to do...\n\n@endnode\n@Node no4 " Menu Help"\n                            _ ___     __     ___ _\n                                /___ /\_\ ___\\n                               .::::.\/_/.::::.\n\n                      [®]  New·User·Password·Door 1.o [©]\n                      [®]   © by Dr.Dre! - Faith `94  [©]\n\n              ._______________________________________________.\n              |                                               |\n              |        1) ....View New User Answers ..        |\n              |        2) ....Move New User Answers ..        |\n           --+O---     3) .......Resctrict New User ..     --+O---\n              |        4) ...Edit Names not Allowed ..        |\n              |        5) ....View Val. UserAnswers ..        |\n              |        6) .......Delete Answer File ..        |\n              |        Q) ..................Exiting ..        |\n              |                                               |\n              !_______________________________________________!\n                                   __ :\n                                  /\_\:.......\n                                  \/_/:\n                                      ·\n                    This is the Main menu from the Door\n\n1. View New User Answer File\n2. Move New user answer File to validated User Directory...\n3. Restrict User from your BBS (Name.no File)\n4. Edit names.no File\n5. View Answerfile from already Validated Users\n6. Delete Answer File\nQ. Exit the Door\n@endnode\n@Node no5 " The Creditz!"\n\n              Copyright (C) 1994 by [-Dr.Dre!/tRSi], Germany\n                            All Rights Reserved\n\n             The AmigaGuide DataBase written by [-Dr.Dre!/tRSi]\n\n    For more good Doors call my BBS under 49 (0) 2131 275756 & 275634\n               · [ · MARLEYS COFFEE SHOP - tRSi GHQ · ] ·\n\n      Thanx to Skin! for using some of your great Styles in my Doors!\n\n@endnode\n@Node no6 " Greetings"\n\n                   The Greets are going to this Dudes...\n\n ByteAndi/X-Design, Spy/X-Design, Remo/X-Design, X-Treme/TRSI, Saito/TRSI\n    Gandalf/Faith, Silver/Faith, McLoud/TRSI, Irata/TRSI, Triton/Fth\n Skylark/LSD, Nick, Metoner/TRSI, J.Walker/TRSI, Crazy/TRSI, Valshare/TRSI\n    Vicous/LSD, Richi/Flt, Steve/D&R, Amicom, -rS!, Empire/Mst, Mr.VAiN\n            APOLLO, BJoerN/Pdy, Jive/TRSi, Scope/Trsi, SkiN!\n          and simply all tRSi Member an other Doodes I forgot...\n\n@endnode\n@Node no7 " tRSi Boards Worldwide"\n\n                 To Contact me Call any of this Boards...\n           -==================================================-\n\n   Cauldron.......................German  hq............++49 Pure Elite\n   Marleys Coffee Shop............German  hq............++49 Pure Elite\n   Boondocks......................Europe  hq............+31-548-040-653\n   Final Impact...................Swedish hq............++46-54-113-486\n   Flying Spirits.................Swiss   hq............+41-217-282-524\n   Savage Amusement...............Austia  hq............+43-767-227-743\n   Zenlandia......................Finnish hq............+358-088-82-144\n\n\n           -==================================================-\n@endnode\n','\n',char(10)),NULL,'auto-added',138819,6,0,NULL,NULL,'nvx_rem5','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_om2','TRSI-OM2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-OM2.LHA','mOVER','XIM','Fantastic',NULL,NULL,'TRSI','_j   :_ .    _  ¬\ /  _ ¬\__    ·tRIStAr· \.   ./_:_ _:/  _/ \   \\/\/       ·&· j   l   / \/ ! \__/\   \¯¯¯) ·rEd^sEctøR!·',replace('  .   : _ __ _____   _____\n _j   :_ .    _  ¬\ /  _ ¬\__    ·tRIStAr·\n \.   ./_:_ _:/  _/ \   \\/\/       ·&·\n  j   l   / \/ ! \__/\   \¯¯¯) ·rEd^sEctøR!·\n  \      /   \_·   //Y   / . |\n   \____/l___j \  /_____/l_: :   ·pReSenT·\n<---------------\/ctx!-----| :------------->\noFFliNE mOVER v0.2 (uTil)  \_/ (Pseudo REG.)\n(mOVEs Old files fRoM yOUR uPlOAd dIR tO\naNOtHER dIR!) 120% ASM util!! GUIDE iNcl.!!\n«·» tRsi «» tRiStAr^&^rEd^sEcToR «» tRsi «·»\n','\n',char(10)),'mOVER.guide',replace('@DATABASE\n@Remark $VER: OFFliNE-mOVER v0.2 by CøRteX/tRSi (29.12.94)\n@Remark AmigaGuide DataBase for oFFLiNE-mOVER v0.2\n\n@Node MAIN "oFFLiNE-mOVER v0.2 - DOS/MC68020 vERSiON"\n                       .   : _ __ _____   _____\n                    1 _j   :_ .    _  ¬\ /  _ ¬\__   1\n                    9 \.   ./_:_ _:/  _/ \   \\/\/   9\n                    9  j   l   / \/ ! \__/\   \¯¯¯)  9\n                    4  \      /   \_·   //Y   / . |  5\n                        \____/l___j \  /_____/l_: :\n                    <----------------\/ctx!-----| :-->\n                    (            CøRtEX! oF     \_/  (\n                    (   tRISTAr aNd rEd^sECTOr iNc!  (\n                    )         SiX/X · X¡M/aSm        )\n\n      iS pROUd tO pRESENt: OffliNe mOvER v0.2 (DOS/MC68020 vERSiON)\n\n                 @{"      ·*·    iNtRoDUCtiON!   ·*·      " LINK Introduction}\n                 @{"      ·*·    iNStALLATiON!   ·*·      " LINK Installation}\n                 @{"      ·*·     cONFiGfiLE!    ·*·      " LINK Configfile}\n                 @{"      ·*· tROUBlE-shOOtiNGs! ·*·      " LINK Troubles}\n                 @{"      ·*·  oTER dOORs/tOOlS! ·*·      " LINK Other}\n                 @{"      ·*·     GREETiNGS!     ·*·      " LINK Greetings}\n                 @{"      ·*·    REGiStER mE!    ·*·      " LINK Register}\n@ENDNODE\n@NODE Introduction "iNtRoDUCtiON"\n\n                           . [ iNtRoDUCtiON: ] .\n                            - --------------- -\n\noFFLiNE mOVER v0.2 is a !small! usefull tool for all SiX/X sysops!!\nit moves old files from your upload dir to another dir (OfflineDir)\nIf oFFLiNE mOVER can''t find the old OFFLINE dir a new dir will be created!\n\nafter correctly saved dirs ya can move or delete the old files!!\n\nthats it!!\n\n\nmORe fEAtURES:\n              insert "OFFLINE" instead of bytes in ya OFFLINE Dir!\n              ya cAn dUPliCAtE ya old diRs!\n              many error and security checks!!\n              CTRL-C break available!! (only for Open,Move Delete Routines)\n              show load & saved bytes - realtime! :)\n              no AREXX SHIT! pure ASM cOde (120%)\n              no delete, move or copy command needed from workbench!\n\nAll what you need is any Model of the great AMIGA, OS2.x or higher.\nand a MC68020 or higher!! fOr lower vErSion call my BBS!\n\nThats all... have Fun with this powerfull Door.\n\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Installation "iNStALLATiON!"\n\n                           . [ INSTALLATION ] .\n                            - -------------- -\n\nIt doesn''t matter where the files were located!!\n\nI copied it in my C dir and started it like this:\n\nmover s:mover.cfg\n\nRemeber:\nAt first you must edit the @{" Configfile " LINK Configfile} via CED or GOLDED!!\nand config it for yourself!!!.\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Configfile "cONFiGfiLE!"\n\n                      . cONFiGfiLE fOr OffliNE mOvER! .\n                       - --------------------------- -\n\nOfflineMover v0.2  by CøRteX/tRS¿!\n\n#                                       ;Recognize mark\n64                                      ;all files older as 64 days - OFFLINE\nBBS:Confs/Conf1/Dir2                    ;location of your Upload Dir!\nBBSTransfer:Amiga/                      ;Path of your Upload Drawer!!\nBBS:Confs/Conf1/Dir1                    ;Location of your Offline dir (all)\nBBSTransfer:OFFLINE/                    ;Path of your Offline drawer!\n\n\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Troubles "TROUBLE-SHOOTiNGs"\n\n                            . TROUBLE-SHOOTiNG .\n                             - -------------- -\n                                    call\n\n              28.8k!   ________    /\__ /\______/\__ _____   28.8k!\n          t            \_     ¬\  /   ¬\)      ¬\   |   ¬/\n          R   __/\__    :   :   \/  Y   \   :   /   :   /    __/\__   a\n          S   \    //   |   |    \  :    \  |  (:      (    \\    /   H\n          i   /_  _\\   |   l    /__|    /  |   \   :   \   //_  _\   q\n         INC.   \/     /:  _____/   l___/___l___/___j    \     \/     !\n                       \__/                         l____/\n          /\__ _/\__   _/\__     _      /\______/\__   _/\ _______      \n          )  ¬|\_  ¬|  \_  ¬|   /¬| |\ /   __  ¬)  ¬| /   \\_    ¬\\n          |   | |   |__ |   |__/  ( ) \___   \_/:   |/  :  \|  -+  \\n          :   | |   | ¬\|   | ¬\   |   \ ¬\    \|   |   |   \   :   \\n          |   | :   l   \   l   \  l    \  \    \   :   l    \  |    \\n          |   | l_______/_______/_______/_______/___l________/__j    /\n          l___j                  tRSi iNC. aHQ            [ctx!]l___/\n\n               (  ( ((  + 4 3 -  5 1 2  -  3 6 5 - 3 0 2  )) )  )\n\n             SysOp: CøRteX/tRSi          Co´s: DjaX, D`Style and ya?\n          .----------------------------------------------------------.\n          | rUNNiNg oN a1200/33Mhz^-^720MB oNLINe StuFF^-^kEwL aNSIs |\n          |       [^Now with S!X-pReSs 0.X!^-^28.8k pOwER!!!^]       |\n          |        [^aMiGa^-^mUzAx^-^/X DooRs^-^aSm SoUrCeS^]        |\n          `----------------------------------------------------------''\n                             [·nO nUp rEqUiReD!·]\n\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Other "OTHER dOORs/TOOLS"\n\n                          . OTHER dOORs/TOOLS .\n                           - --------------- -\n\n                    XiM     Security Guide       v0.4\n                    XiM     Show Doors           v0.4\n                    XiM     ctx!CoMMeNt          v0.2\n                    XIM     Upload Detector      v0.5\n                    XIM     Front Guard          v1.0\n                    XIM     Turbo Lister         v0.1\n              now!  DOS     Offline Mover        v0.2\n\n\nIF YOU LIKE MY DOORS/UTILS AND WANT BE @{" REGISTERED " LINK Register} USER OF IT\nCALL MY BBS: Dark Illusion ++43-512-365-302!! no NUP! no SYSPASS!\n\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Register "REGISTER ME!"\n\n                             . REGISTER ME! .\n                              - ---------- -\n\nTHE REGISTRATION FEE IS 15$, SHURE YOU THINK PHUU! A LOTS OF MONEY, BUT READ\nWHAT YOU WILL GET FOR YOUR MONEY.\n\n1. THERE ARE A LOTS OF DOOR CODERS BUT ARE YOU SURE THAT YOU GET A DOOR\n   WITHOUT ANY BACKDOORS?? SO I HATE BACKDOORS AND VIRUSES ETC.\n   SO REMEMBER EVERY DOOR FROM ME IS 120% BACKDOOR FREE!!!\n   THE REGISTERED USER(S) ARE GETTING A PRIVATE VERSIONS, ALL PUBLIC\n   VERSIONS HAVE FROM NOW ON SOME OPTIONS REMOVED OR SOME NERVIOUS REGISTER ME\n   STRINGS WITH WAIT LOOPS heehe  ONLY! THE REGISTERED USER HAVE\n   THE FULL VERSION. REMEMBER THIS!!\n\n2. YOU FOUND A BUG ? -> REPORT HIM TO ME AND YOU GET SOON AS POSSIBLE A\n   FIXED VERSION, NO LONG NEED TO WAIT FOR A NEWER RELEASE VERSION.\n\n3. YOU HAVE SOME GOOD IMPROVEMENTS, TALK WITH ME, AND I WILL SEE IF I CAN\n   RELEASE IT.\n\n4. YOU NEED A PRIVATE DOOR ONLY FOR YOUR BBS, I WILL CODE THEM!!\n\n5. PRIVATE SUPPORT CONFERENCE IN MY BBS FOR ALL REGISTERED USERS.\n\n6. ALL DOORS/UTILS ARE INCLUDING YOUR REGISTER STRING.(CODED!)\n\n7. YOU`LL GET ALL LATER VERSIONS OR NEW DOORS FOR THIS PRICE.\n\n                  SIMPLY YOU GET THE BEST SUPPORT AROUND.\n          THINK ABOUT IT AND KEEP THE PROGRAMMERS PROGRAMMING !!!\n\nIF YOU ARE INTERESTED SO CONTACT ME AT ANY TRSI BOARD OR SIMPLY AT THE\n                     TRSI INC. AHQ - DARK ILLUSION!!\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Greetings "GREETINGS"\n\n                          . SOME FAST GREETINGS .\n                           - ----------------- -\n                                  · TO ·\n\n      [*] DJAX [*] MARIO,SIEGEL,BYTEANDI,DR.DRE,SPY,UYANIK!/TRSI [*]\n  [*] INSPECTOR, ICE TEA/CLS [*] AYATOLLAH [*] FELON/HLM [*] CALYPSO [*]\n [*] SAL-1/TRSI [*] SAUZER,PRAYER/R^D [*] BLOODWOLF [*] BLIND GUARDIAN [*]\n   [*] SHADE/tRSI [*] KNACKOSOFT/TRSI [*] CONTROL/TRSI [*] FANFARE [*]\n  [*] DREAM WARRIOR [*] PSYCHO/2KAD [*] ENZO [*] METAL DEATH/LEPROSY [*]\n        [*] ASC [*] IMAGIC [*] PEE WEE [*] YANKEE ROSE/POD/ACC [*]\n\n                       ... and all i forgot ...\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',49931,15,0,NULL,NULL,'trsi_om2','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_pm1','TRSI-PM1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-PM1.LHA',NULL,'XIM','_____ __   /__ ____/    ____',NULL,NULL,'TRSI','in   \         /  / \  /_   /   /tRiStAR \__   /  \  \_/\   \ /   /    & 1995    /   /___j\__/_____//   /    RSi',replace('        _____ __   /__ ____/    ____\n   in   \         /  / \  /_   /   /tRiStAR\n         \__   /  \  \_/\   \ /   /    &\n  1995    /   /___j\__/_____//   /    RSi\n    - ---/___/--/X-sECtiON--/___/--- -\n.-ctx!-------------------------------------.\n| pAY mAil v0.1  [rELEASE vERSiON 16.4.95] |\n| sMAll /X dOOR fOR /X aND SiX in XiM/ASM! |\n|   tO pAY fOR EALL mAilS! gRAp it nOW!!   |\n`------------------------------------------''\n\n','\n',char(10)),'PayMail.Guide',replace('@DATABASE\n@Remark $VER: pAYMAil v0.1 by CøRteX/tRSi (15.04.95)\n@Remark AmigaGuide DataBase for pAYMAil v0.1\n\n@Node MAIN "pAYMAil v0.1 - uNREGiStEREd vERiON"\n                       .   : _ __ _____   _____\n                    1 _j   :_ .    _  ¬\ /  _ ¬\__   1\n                    9 \.   ./_:_ _:/  _/ \   \\/\/   9\n                    9  j   l   / \/ ! \__/\   \¯¯¯)  9\n                    4  \      /   \_·   //Y   / . |  5\n                        \____/l___j \  /_____/l_: :\n                    <----------------\/ctx!-----| :-->\n                    (            CøRtEX! oF     \_/  (\n                    (   tRISTAr aNd rEd^sECTOr iNc!  (\n                    )         SiX/X · X¡M/aSm        )\n\n          iS pROUd tO pRESENt: pAYMAil v0.1 (rElEASE vERSiON)\n\n                 @{"      ·*·    iNtRoDUCtiON!   ·*·      " LINK Introduction}\n                 @{"      ·*·    iNStALLATiON!   ·*·      " LINK Installation}\n                 @{"      ·*·     cONFiGfiLE!    ·*·      " LINK Configfile}\n                 @{"      ·*· tROUBlE-shOOtiNGs! ·*·      " LINK Troubles}\n                 @{"      ·*·  oTER dOORs/tOOlS! ·*·      " LINK Other}\n                 @{"      ·*·     GREETiNGS!     ·*·      " LINK Greetings}\n                 @{"      ·*·    REGiStER mE!    ·*·      " LINK Register}\n@ENDNODE\n@NODE Introduction "iNtRoDUCtiON"\n\n                           . [ iNtRoDUCtiON: ] .\n                            - --------------- -\nI''ve coded this small door, because some lazy guys wanna have access\nto send eall mails!!! so ive coded pAYMAil!! Now all!! users can send there\nEALL mail!! (some users must pay for it! hehe)\n\nlast week ive sawn a similar door from ROYAL!!! let you know that ive coded\nthis door some years ago but it was to small and unimportant to\nrelease it. So i''ve used it for my own!\n\nIt doesn''t matter which acces level this user have, if he can pay,\nhe can write his EALL mail!!!\n\nMention: using no AREXX shit pure ASM code!!\n\nAll what you need is any Model of the great AMIGA, OS2.x or higher.\n\nThats all... have phun with this this little piece of heaven!\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Installation "iNStALLATiON!"\n\n                           . [ INSTALLATION ] .\n                            - -------------- -\n\nCopy the files in the archive to your directories, they are:\n\nLIBS:AEDoor.library ( © Sintax/WOT )  thx!!!\n\nfor /X v2.x or SiX:\n\nadd thiz line to your cmds\nBBS:Commands/BBS.Cmd\n\nBBS:Doors/pAYMAil/pAYMail.Xim\nBBS:Doors/pAYMAil/pAYMail.cfg\nBBS:Doors/pAYMAil/pAYMail.guide\n\nfor /X v3.x or higher:\n\nBBS:Commands/BBSCmd/EALL.info\n\nBBS:Doors/pAYMAil/pAYMail.Xim\nBBS:Doors/pAYMAil/pAYMail.cfg\nBBS:Doors/pAYMAil/pAYMail.guide\n\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Configfile "cONFiGfiLE!"\n\n                      . cONFiGfiLE fOr tURBO liStER! .\n                       - --------------------------- -\n\n---[start of configfile!]---\n\npAYMAil v0.1 by CøRteX/tRS¿!\n\n#\n250000                ;payment for EALL mails!!!\n\n\n-----[End of configfile]-----\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Troubles "TROUBLE-SHOOTiNGs"\n\n                            . TROUBLE-SHOOTiNG .\n                             - -------------- -\n                                    call\n\n              28.8k!   ________    /\__ /\______/\__ _____   28.8k!\n          t            \_     ¬\  /   ¬\)      ¬\   |   ¬/\n          R   __/\__    :   :   \/  Y   \   :   /   :   /    __/\__   a\n          S   \    //   |   |    \  :    \  |  (:      (    \\    /   H\n          i   /_  _\\   |   l    /__|    /  |   \   :   \   //_  _\   q\n                \/     /:  _____/   l___/___l___/___j    \     \/     !\n                       \__/                         l____/\n          /\__ _/\__   _/\__     _      /\______/\__   _/\ _______      \n          )  ¬|\_  ¬|  \_  ¬|   /¬| |\ /   __  ¬)  ¬| /   \\_    ¬\\n          |   | |   |__ |   |__/  ( ) \___   \_/:   |/  :  \|  -+  \\n          :   | |   | ¬\|   | ¬\   |   \ ¬\    \|   |   |   \   :   \\n          |   | :   l   \   l   \  l    \  \    \   :   l    \  |    \\n          |   | l_______/_______/_______/_______/___l________/__j    /\n          l___j                    tRSi  aHQ              [ctx!]l___/\n\n               (  ( ((  + 4 3 -  5 1 2  -  3 6 5 - 3 0 2  )) )  )\n\n             SysOp: CøRteX/tRSi          Co´s: DjaX, D`Style and ya?\n          .----------------------------------------------------------.\n          | rUNNiNg oN a1200/33Mhz^-^720MB oNLINe StuFF^-^kEwL aNSIs |\n          |       [^Now with S!X-pReSs 0.X!^-^28.8k pOwER!!!^]       |\n          |         [^aMiGa^-^mUzAx^-^/X DooRs^-^cONSOlES!^]         |\n          `----------------------------------------------------------''\n                             [·nO nUp rEqUiReD!·]\n\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Other "OTHER dOORs/TOOLS"\n\n                          . OTHER dOORs/TOOLS .\n                           - --------------- -\n\n                    XiM     Security Guide       v0.4\n                    XiM     Show Doors           v0.4\n                    XiM     ctx!CoMMeNt          v0.2\n                    XIM     Upload Detector      v0.5\n                    XIM     Front Guard          v1.0\n                    DOS     Offline Mover        v0.2b\n                    XIM     Turbo Lister         v0.2\n                now XIM     pAY mAil             v0.1\nchanges:\n\nIF YOU LIKE MY DOORS/UTILS AND WANT BE @{" REGISTERED " LINK Register} USER OF IT\nCALL MY BBS: Dark Illusion ++43-512-365-302!! no NUP! no SYSPASS!\n\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Register "REGISTER ME!"\n\n                             . REGISTER ME! .\n                              - ---------- -\n\nTHE REGISTRATION FEE IS 15$, SHURE YOU THINK PHUU! A LOTS OF MONEY, BUT READ\nWHAT YOU WILL GET FOR YOUR MONEY.\n\n1. THERE ARE A LOTS OF DOOR CODERS BUT ARE YOU SURE THAT YOU GET A DOOR\n   WITHOUT ANY BACKDOORS?? SO I HATE BACKDOORS AND VIRUSES ETC.\n   SO REMEMBER EVERY DOOR FROM ME IS 120% BACKDOOR FREE!!!\n   THE REGISTERED USER(S) ARE GETTING A PRIVATE VERSIONS, ALL PUBLIC\n   VERSIONS HAVE FROM NOW ON SOME OPTIONS REMOVED OR SOME NERVIOUS REGISTER ME\n   STRINGS WITH WAIT LOOPS heehe  ONLY! THE REGISTERED USER HAVE\n   THE FULL VERSION. REMEMBER THIS!!\n\n2. YOU FOUND A BUG ? -> REPORT HIM TO ME AND YOU GET SOON AS POSSIBLE A\n   FIXED VERSION, NO LONG NEED TO WAIT FOR A NEWER RELEASE VERSION.\n\n3. YOU HAVE SOME GOOD IMPROVEMENTS, TALK WITH ME, AND I WILL SEE IF I CAN\n   RELEASE IT.\n\n4. YOU NEED A PRIVATE DOOR ONLY FOR YOUR BBS, I WILL CODE THEM!!\n\n5. PRIVATE SUPPORT CONFERENCE IN MY BBS FOR ALL REGISTERED USERS.\n\n6. ALL DOORS/UTILS ARE INCLUDING YOUR REGISTER STRING.(CODED!)\n\n7. YOU`LL GET ALL LATER VERSIONS OR NEW DOORS FOR THIS PRICE.\n\n                  SIMPLY YOU GET THE BEST SUPPORT AROUND.\n          THINK ABOUT IT AND KEEP THE PROGRAMMERS PROGRAMMING !!!\n\nIF YOU ARE INTERESTED SO CONTACT ME AT ANY TRSI BOARD OR SIMPLY AT THE\n                     TRSI INC. AHQ - DARK ILLUSION!!\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Greetings "GREETINGS"\n\n                          . SOME FAST GREETINGS .\n                           - ----------------- -\n                                  · TO ·\n\n           [*] MARIO,SIEGEL,BYTEANDI,DR.DRE,SPY,UYANIK!/TRSI [*]\n   [*] INSPECTOR,ICE TEA/CLS [*] AYATOLLAH [*] FELON/HLM [*] CALYPSO [*]\n [*] EURONYMOUS [*] SAL-1/TRSI [*] DJAX,SAUZER,PRAYER/R^D [*] BLOODWOLF [*]\n    [*] SHADE/tRSI [*] KNACKOSOFT/TRSI [*] CONTROL/TRSI [*] FANFARE [*]\n  [*] DREAM WARRIOR [*] PSYCHO/2KAD [*] ENZO [*] METAL DEATH/LEPROSY [*]\n    [*] D`STYLE [*] KNIGHT FIGHTER [*] TURBO [*] BITART [*] PHANTOM [*]\n\n                      ... and all i have forgotten ...\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n','\n',char(10)),NULL,NULL,12034,5,0,NULL,NULL,NULL,'scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_rep','TRSI-REP.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-REP.LHA','dRE!REPORt','XIM','dRE!REPORt',NULL,NULL,'TRSI','_____/___/_____/\___________ .__________   // __________/---------------. |  /   /  / _/\____  \/   /    dR.dRE!     |',replace('      /\__\n_____/___/_____/\___________\n.__________   // __________/---------------.\n|  /   /  / _/\____  \/   /    dR.dRE!     |\n| /  //__/   \ ______/  //       Of        |\n|/__ /   \____\/-Mo!/__ /  (/X·iNNOVAtiON) |\n`--\/-----------------\/-------------------''\n        bRiNGS yA: dRE!rEPORt v1.21\n SiMPlY tHE bESt bEtAtEStER bUG REPORt dOOR\n fOR /X 4.xx ONlY (XiM + fUll CRSR SUPPORt)\n','\n',char(10)),'dRE!REPORt.GUiDE',replace('@database 00333300-0\n@$VER: dRE!REPORt v1.21\n@author "dR.dRE! (tRSi /X·iNNOVATiON)"\n@(c) "dR.dRE! (tRSi /X·iNNOVATiON)"\n@remark written by dR.dRE!/tRSi\n\n@node "Main" "AMiGAGUiDE DOCUMENt fOR dRE!REPORt v1.21"\n\n                    ._________________  ______        .\n                    l___       /      \\/    _/_______.:\n                     /        /   /  _/\\___      /    :\n                    /________/-rS!\\_____\\  _____/     |\n                           /_______|     \\/`94/_______|\n                    «««          dR.dRE! oF         »»»\n                    »»» tRISTAr aNd rEd^sECTOr iNc! «««\n                    «««    aMiEXPRESs iNNoVATioN    »»»\n    \n                  @{b}@{fg fill}iS pROUd tO pRESENt:  dRE!REPORt v1.21@{ub}@{fg text}\n    \n                       @{"        iNtRoDUCtiON!       " link "Document_0" 0}    \n                       @{"        iNStALLATiON!       " link "Document_1" 0}     \n                       @{"    OtHER dRE!dOORS/tOOlS   " link "Document_3" 0}       \n                       @{"          CREDitS!          " link "Document_4" 0}         \n                       @{"         GREETINGS!         " link "Document_5" 0}          \n                       @{"     tRSi /X-iNNoVATioN     " link "Document_6" 0}            \n                       @{"     REGiStER dRE!dOORS     " link "Document_8" 0}\n@endnode\n\n@node "Document_0" "iNtRoDUCtiON!"\n                            ABOUT dRE!REPORt v1.21\n                          - ---------------------- -\n\nFor shure everybody who codes Doors or Tools knows the shitty Bug Report\nDoor written by ByteMaster.\ndRE!REPORt is the better Answer to this BugReport Door.\n\ndRE!REPORt supports the following features.\n\n1) 3 different Report types, like: - Door/Tool Bug Report\n                                   - Door/Tool Suggestions\n                                   - Door/Tool Changes\n2) For each Conferences dRE!REPORt will create seperate Reports,\n   so you are able to have more than one Beta Conf, may the registered\n   Users have a own Conference, or anything.\n3) Displaying all reports directly from the Door.\n4) Writing/Displaying reverse Mode, so you ever will see the latest.\n   Bugs/Sugs/Changes first, no more longer hunting the whole Report file.\n5) Writing Message directly to the Door/Tool Authors, via Menu.\n6) Full Cursor Support,\n\nHope you enjoy this small powerFull XiM Door for AmiExpress 4.xx only !!!\n\n                dR.dRE! (tRSi /X·iNNOVATiON)\n@endnode\n\n@node "Document_1" "iNStALLATiON!"\n                               iNSTALLATiON\n                             - ------------ -\nCopy the whole Directory DRE!REPORT to DOORS:DRE/\nCopy the REPORT.INFO to BBS:COMMANDS/CONF<X>CMD/\n\nOpen the DOORS:DRE/DRE!REPORT/dRE!REPORt.iNfO and edit the @{"Tooltypes" link "Document_7" 0}\n\nNOTE: THIS IS ONLY A 1 WEEK WORKABLE VERSION, IF YOU WANT A FULL VERSION SO\n      READ @{"REGiStER dRE!dOORS" link "Document_8" 0} !!!\n\nthats all...\n@endnode\n\n@node "Document_3" "OtHER dRE!dOORS/tOOlS"\n\n                           OTHER DRE!DOORS/TOOLS\n                         - --------------------- -\n\n NAME                  TYPE   VERSION\n---------------------+------+--------------------------------------------- \nDRE!WHO              | XiM  |  V1.1  PUBLIC \nDRE!FRONT            | XiM  |  V1.O  PUBLIC \nCHAT!ACCESS          | XiM  |  v1.2  PUBLIC \nDRE!COMMENT          | XiM  |  V1.3  PRiVATE RELEASE FOR REG. USERS\nONLY DOORMENU        | XiM  |  v1.o  PUBLIC \nDRE!WALL             | XiM  |  v1.2  PRiVATE RELEASE FOR REG. USERS ONLY \nFAST!DUPE            | XiM  |  v1.11 PRIVATE COOP DR.DRE!^BYTEANDI\nMOST WANTED          | XiM  |  v1.52 PRiVATE RELEASE FOR REG. USERS ONLY \nLHA CHEKKO           | DOS  |  RENAMED INTO DRE!CHECK SINCE V2.1 \nSPEEDADD(TXT)        | DOS  |  RENAMED INTO DRE!ADD v1.0 REG. ONLY \nSPEEDZIP (ZIP)       | DOS  |  v1.o  BETA \nBULL!VIEW            | XiM  |  v1.02 PUPLIC \nDRE!FREE             | XiM  |  v1.ß  PRIVATE RELEASE FOR REG. USERS ONLY \nLAST!JUNKZ           | AiM  |  v1.0  PRIVATE RELEASE FOR REG. USERS ONLY \nPWFAILURE            | XiM  |  v1.1  PUPLIC \nBETA!REPORT          | XiM  |  v0.92 BETATESTER(S) ONLY\nDRE!NODECHECK        | XiM  |  c0.ß  PUBLIC \ndRE!CARD             | XiM  |  v2.1  BETA (PRIVATE^PUBLIC VERSION SOON)\nDRE!SENDLIST         | XiM  |  v1.2  PUBLIC \nNUP^SYSPW COMMENTER  | XiM  |  v1.2  PUBLIC \nNEWUSER SCRIPT       | XiM  |  v1.21 PUBLIC\nGLOBAL USER STATUS   | XiM  |  v1.9  PUBLIC \nSPEEDLIST (USERLIST) | XiM  |  v1.ß  PRIVATE RELEASE FOR REG. USERS ONLY\nDESCRIPTION!SNAP     | AiM  |  v1.o  PUPLIC \nDRE!ADVERTISE        | XiM  |  v2.o  PRIVATE RELEASE FOR REG. USERS ONLY \nDRE!SENt             | XiM  |  v0.6  PRIVATE RELEASE FOR REG. USERS ONLY\nDRE!FREE             | XiM  |  v0.3  PRIVATE RELEASE FOR REG. USERS ONLY\nDRE!CHECK            | DOS  |  v2.1  PRIVATE RELEASE FOR REG. USERS ONLY\nDRE!REPORT           | XiM  |  v1.21 PRIVATE & PUBLIC PROTECTED RELEASE\n---------------------+------+---------------------------------------------\nTHERE ARE ALSO SOME OLDER (AiM) DOORS AVAILABLE WHERE I CANT REMEMBER WHAT\nWAS IT EXACTLY ... SEARCH ONLY FOR DR.DRE! \nIF YOU LIKE MY DOORS/UTILS THEN REGISTER IT PLEASE.\n!!! KEEP THE PROGRAMMERS PROGRAMMING !!!\n@endnode\n\n@node "Document_4" "CREDitS!"\n\n\n                             NOTEABLE CREDITS\n                           - ---------------- -\n\n   DRE!fREE v0.3 [RELEASE 1] was written by DR.DRE! (tRSi /X-iNNoVATioN)\n\n     The AmigaGuide DataBase was written by DR.DRE! (tRSi /X-iNNoVATioN)\n\n        AMIEXPRESS PROFESSIONAL (C) - LIGHTSPEED TECHNOLOGIES INC.\n\n                             MUSICAL SUPPORT: \n\n      ANTHRAX [·] NIRVANA [·] RAGE AGAINST THE MACHINE [·] BODYCOUNT\n\n\n@endnode\n\n@node "Document_5" "GREETINGS!"\n\n\n                            SOME FAST GREETINGS\n                          - ------------------- -\n                               TO THIS DUDES\n\n              MCLOUD/TRSI  MARIO  ECS  SIEGEL  BYTEANDI  SPY \n             VALSHARE  REDSKIN!  EMPIRE/MST  RICHI/FLT  NICK \n             SAL-1/TRSI  TRITON  VAMPIRE/PDY  XTREME  BJOERN \n             LINEBACKER  BLOODWOLF  JUAN/TRSI  BLIND GUARDIAN\n\n          ... all i forgot and of course all registered Users...\n\n@endnode\n\n@node "Document_6" "tRSi /X-iNNoVATioN"\n\n                   MEMBERS OF (tRSI /X·iNNOVATiON) ARE:\n                 - ------------------------------------ -\n\n                         dR.dRE!/tRSi  -  lEADER\n                        BYTEANDi/tRSi  -  CO-lEADER\n                          SiEGEl/tRSi  -  C/ASM CODER\n                             SPY/tRSi  -  C/CODER\n\n   If you wann join us, so get in touch with one of the doodes abouve...\n\n@endnode\n\n@node "Document_7" "Tooltypes"\n                 All Possible ToolTypes and his Functions:\n                 -----------------------------------------\n\nThere are only 1 Tooltype available.\n\nAUTHOR.1=DR.DRE!/TRSI\nAUTHOR.2=YOUR NAME\nand so on.\n\nHere you should write in all Coders from your BetaTest Conference.\nThis dudes are then able to write Changes and so on...\n@endnode\n\n@node "Document_8" "REGiStER dRE!dOORS"\n\n\n                            REGISTER DRE!DOORS\n                          - ------------------ -\n\nTHE REGISTRATION FEE IS 2O$, SHURE YOU THINK PHEW! A LOT OF MONEY, BUT READ\nWHAT I WILL BET FOR YOUR MONEY.\n\n1. YOU WANNA BE SHURE YOU GET ONLY DOORS WITHOUT ANY BACKDOOR ? OF COURSE\n   THE REGISTERED USER(S) ARE GETTING ONLY PRIVATE VERSIONS, ALL PUBLIC\n   VERSIONS HAVE A TIMELIMIT OR I REMOVE SOME MENU POINTS. ONLY!!! THE REG.\n   USERS HAVE THE FULL VERSION.\n\n2. YOU FOUND A BUG ? -> REPORT HIM TO ME AND YOU GET SOON AS POSSIBLE A\n   FIXED VERSION, NO LONG NEED TO WAIT FOR A NEWER RELEASE VERSION.\n\n3. YOU HAVE SOME GOOD IMPROVEMENTS, TALK WITH ME, AND I WILL SEE IF I CAN\n   REALISE IT.\n\n4. YOU NEED A PRIVATE DOOR ONLY FOR YOUR BBS, I WILL CODE THEM.\n\n5. PRIVATE SUPPORT CONFERENCE IN A FUCKEN FAST TRSI BOARD IN NEDERLAND.\n   NEW DISTRIBUTION SITE IN GERMANY ALSO AVAILABLE.\n\n6. ALL DOORS/UTILS ARE INCLUDING YOUR REGISTER STRING.\n\n7. YOU`LL GET ALL LATER VERSIONS OR NEW DOORS FOR THIS PRICE.\n\n                  SIMPLY YOU GET THE BEST SUPPORT AROUND.\n          THINK ABOUT IT AND KEEP THE PROGRAMMERS PROGRAMMING !!!\n\nIF YOU ARE INTERESTED SO CONTACT ME AT ANY TRSI BOARD OR SIMPLY AT THE\n                            · SPiRiTS Of SOUl ·\n\n@endnode\n\n','\n',char(10)),NULL,'auto-added',19287,3,0,NULL,NULL,'trsi_rep','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_sd','TRSI-SD.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-SD.LHA',NULL,'XIM','_ ___________',NULL,'CøRteX/tRS¿!!','TRSI','___________ ___  \_________/\ \  _   _  /  |/  /    ____/  \  /X rulez! / \_/   |_/  _/   \____  \_____)  ________/',replace('    _ ___________              \n___________ ___  \_________/\  \n\  _   _  /  |/  /    ____/  \  /X rulez! / \n \_/   |_/  _/   \____  \_____)  ________/ \nMb/    |____\_____/  /   \   |  / \n (_____|        (________/---'' / presents:\n \n      ShowDoors v0.1 by CøRteX/tRS¿!!\n           for Ami or S-Express\n','\n',char(10)),'ShowDoors.Doc',replace('\n --[·»«·-[·tRISTAr & rEd^sECTOr iNc.·]-·»«·]::[·»»««·-[---------------------\n\n   .  .           .          .                  .           .      .     .\n   :   ______/\___:______/\_____________ /\_________/\______:_/\__ :   * .\n   .   \________________/  \_______    //  \_____________________/   .   :\n   :  :   _/      .   _/     .   | \  /\__ ______      \_   .    \_    .\n      .  \\`      :   \`     :   |  \/  //      |      ''/   :    ''// : . :\n   *  .   \\  _________\  _______|____ //____________  /_______  //\n      .  . \\/____:_____\/___.________\/________.____\/_____:__\// CONtR0L\n   .  .  .  \/    :     \/   :        \/   :    :    \/     :  \/    .\n   .  .  .        .          .             .    .           .      . .   .\n\n --[·»«·-[·tRISTAr & rEd^sECTOr iNc.·]-·»«·]::[·»»««·-[---------------------\n      \n<------------------------------------------------------------------        \n                                    pReSenTs\n        ------------------------------------------------------------------->\n \n                      ShowDoors v0.1 coded by CøRteX/tRS¿\n                     -===================================-\n\n. [ INTRUDUCTION: ] .\n---------------------\n\n   This is .REALLY. a must for every Boardsystems!! so their users can\n   see what doors they can use!\n   Off course with seperate menus for SYSOPs and normal Users!!!\n\n. [ Requirements: ] . \n---------------------\n\n   All what you need is any Model of an Amiga OS2.0 or higher!\n   AmiExpress 2.xx - 3.xx\n   Thats all folks....\n\n. [ INSTALLATION ] .\n--------------------\n   Copy the files in the archive to your directories,\n   they are :                                        \n                                                  \n   BBS:Doors/ShowDoors/ShowDoors.XiM\n   BBS:Doors/ShowDoors/SysopMenu.txt              \n   BBS:Doors/ShowDoors/UserMenu.txt\n   BBS:Doors/ShowDoors/ShowDoors.txt\n   LIBS:AEDoor.library ( © Sintax/WOT )\n\n\n   All Users under SecLevel=250 will see the UserDoors.txt and of course\n   the Rest (over 250) will see the SysopDoors.txt!\n   thats it..... have fun!!!\n\n. [HISTORY: ] .\n---------------\n                     V0.1    -  First release\n\n. [Other RELEASES] .\n--------------------\n                     Security Guide v0.1\n\n. [ Thx to: ] .\n---------------\n           DJAX/Sigma7 for some rumour Reports and for Beta testing\n\n. [ Greetings: ] .\n------------------\n           Djax - Rico - DreamWarrior - Tekkno - Saito - Samir - McLoud \n         Dr.Dre - Prayer - Lion - PeeWee - Blitter - Steve - RasterBlaster \n                           - AND ALL TRSI Members -\n  \n. [ Last words: ] .\n-------------------\n\n        for a registered version of my doors call +43 512 365302!!\n\n --[·»«·-[·tRISTAr & rEd^sECTOr iNc.·]-·»«·]::[·»»««·-[---------------------\n\n          __________        __ __     ___________    __    /\__\n          \   __    \      /  |  \   |  /  __    \  /  \  //  /\n\ s¡g/X\a  \_/  \_  \\    //     \\  |\/  | //   / //   \//  /    aHQ    /\n:\   7      //  | \  \\  //   :   \\ |  __://   ( // ___/   (           /:\n::\    /\_ //   |  \  \\//  __|_ _ \\:  \___    \\_  \____   \_ _/\    /::\n:::\  /::::\\   |__/   \\   \_ _    \\    |:\\_   /    /\    //::::\  /:::\n::::\/::::::\___________/_____|_______)___|::\_\//____/::\_ //::::::\/::::\n:::::::::::::::::::::::::::::::::::::::::::::::\/::::::::::\/:::::::::::::\n::::::___:::___::::::___:::::__:__:::::_________:::::::::::::__:::__::::::\n\::::|\ /|:|\  |::::|\  |:::/  |  \:::/   __   /:/\:::_/\:::|  \ |  |:::::\n \:::| Y |:| \/|/\::| \/|/\/   :  \\::\\    \//:_\/::/\  \::||  \| ||::::/\n  \::| : |:|   : \\:|   : \\   |   \\::\\   \\:|  /|// \ \\:|:   \ :|:::/ \n   \:| . |:|   .  \\:   .  \\  l    \\:/\    \\:\/ |/ / \ \\:. \   .|::/  \n     |   | |        \        \        // \__   \   |  \_/   \  |\   |[CTX]\n     |__ | |_______ /_______ /________\ :______/___|_______ /__| \  |     \n        Y          Y        Y          \!                  Y      \ |     \n        :          :        :           :    s¡G/X\a 7 aHQ :       \|\n        .    _    _._ ___   :___  ___  ___  ___  ____  ___ .        !\n        : __//_  //// _//   ._// //__ //_   _// // // __// :        :\n        :  //     //__// ø __// //_// __//__// //_// //__  | :      .\n        |                                                · :_.      \n        |                sYsOp: CøRteX/tRS¿              :_:/       :\n        |          cOsYsOpS: FeLoN - DJAX/sIgMa 7         \/        .\n        | ·                                                |        °\n      · :_:· rUnNiNg oN A1200 - 68882/33Mhz with /X v3.X   |\n      :/\_\:        24h a DaY - keWl Ansi Dezigns          |  _/\_\n       \/_/ __ _______________________________________ __  |  \__/\n        |                                                  |  (__)\n        :         aMiGa - /X sUpPoRt - mUzAx - aSm         :    \n    - --+--------------------------------------------------+-- -\n        .                                                  . \n\n--[·»«·-[·tRISTAr & rEd^sECTOr iNc.·]-·»«·]::[·»»««·-[---------------------\n\n\n\n','\n',char(10)),NULL,NULL,5569,2,0,NULL,NULL,NULL,'scan',1780048798);
