INSERT INTO door_catalog VALUES('trsi_sv3','TRSI-SV3.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-SV3.LHA',NULL,'XIM','sUPERViSER.XiM',NULL,NULL,'TRSI','in   \         /  / \  /_   /   /tRiStAR \__   /  \  \_/\   \ /   /    & 1995    /   /___j\__/_____//   /    RSi',replace('        _____ __   /__ ____/    ____\n   in   \         /  / \  /_   /   /tRiStAR\n         \__   /  \  \_/\   \ /   /    &\n  1995    /   /___j\__/_____//   /    RSi\n    - ---/___/--/X-sECtiON--/___/--- -\n.-ctx!-------------------------------------.\n| sUPERViSER v0.3ß  (bEtA pUBliC vERSiON)  |\n| bESt uSERliStER dOOR aVAilAblE fOR SiX/X |\n| wRiTiNG wARN-/dElMAilS,cHANGE rAtiO-bYtES|\n|cHECk lAStlOGiNdAtE and uP/dOWN diffERENtS|\n`------------------------------------------''\n\n','\n',char(10)),'sUPERViSER.GUIDE',replace('@DATABASE\n@Remark $VER: sUPERViSER v0.3 by CøRteX/tRSi (27.04.95)\n@Remark AmigaGuide DataBase for sUPERViSER v0.3\n\n@Node MAIN "sUPERViSER v0.3 - pUBliC vERSiON"\n                        _____ __   /__ ____/    ____\n                   in   \         /  / \  /_   /   /tRiStAR\n    ·: SiX/X :·          \__   /  \  \_/\   \ /   /    &      ·: X¡M/aSM :·\n                  1995    /   /___j\__/_____//   /    RSi\n                    - ---/___/--------[ctx!]/___/--- -\n                                CøRteX! oF\n                       tRiStAR aNd rEd^sECtOR iNC.\n\n          iS pROUd tO pRESENt: sUPERViSER v0.3 (pUBliC vERSiON)\n\n                 @{"      ·*·      cOPYRiGHt!    ·*·      " LINK Copyright}\n                 @{"      ·*·    iNtRoDUCtiON!   ·*·      " LINK Introduction}\n                 @{"      ·*·    iNStALLATiON!   ·*·      " LINK Installation}\n                 @{"      ·*·     cONFiGfiLE!    ·*·      " LINK Configfile}\n                 @{"      ·*· tROUBlE-shOOtiNGs! ·*·      " LINK Troubles}\n                 @{"      ·*·  oTER dOORs/tOOlS! ·*·      " LINK Other}\n                 @{"      ·*·     GREETiNGS!     ·*·      " LINK Greetings}\n                 @{"      ·*·    REGiStER mE!    ·*·      " LINK Register}\n@ENDNODE\n\n@NODE Copyright "cOPYRiGHt!"\n\n                             . [ cOPYRiGHt: ] .\n                              - ------------ -\nThis program is FREEWARE!\n\nIt can be freely copied and distributed for non-commercial purposes,\nprovided that no file is added to or removed from the distribution\narchive and no charge, beside a nominal fee, is requested.\n\nThe whole Copyright is reserved by the Author (myself!), and without\nwritten Permission it''s not allowed to distribute this Program in any\ncomercial way.\n\nThis version is a UNREGISTERED PUBLIC version! If you want to register,\nyou have to pay a @{"registration" LINK register}\n\n\n@{"  MAIN  " LINK MAIN}\n\n@ENDNODE\n\n\n@NODE Introduction "iNtRoDUCtiON"\n\n                           . [ iNtRoDUCtiON: ] .\n                            - --------------- -\n\nYou have seen many Userlist dOORS??? But no dOOR have the features\nand options like sUPERViSER!!\n\nnO AREXX shitt!! - pure ASM coding!!\n\nAll what you need is any Model of the great AMIGA, OS2.x or higher.\nand the AEDoor.library ( © Sintax/WOT )\n\n\n1.OPTION:\n---------\nsUPERViSER shows you all users with there up/downloadbytes, ratios,\nusernumber, warnmail status and last called days !!\nIf a user is lame, because he leech or don''t call often or\nwould be warned example: 3 times, he will be shown in different\ncolours and a prompt will ask you to delete/warn/ratio/ubytes the user!!\n\ndelete feature:\n                delete user (user will be shown in different colour\n                             and warnmail counter will be set to 0)\n           or undelete user (user will be reactivated)\n\nwarn feature:\n               send user a warn or delete mail!!\n               (YOU CAN WRITE YOUR OWN MESSAGES IF YOU WANT.\n                JUST EDIT THE FILES .DEL and .WARN!!!)\n\n               by sending a warn mail the warn counter will be added\n               until 9 (configable) mails. after this, the warnmails\n               will be shown in a different colour!\n               by sending a del mail a X will be printed, in a\n               different colour, instead of the warn number!\n               (this means, that you send him a del mail!)\n\n  not included at version 0.3ß:\n               after ex.14 days, sUPERViSER will print a messy to\n               delete him if he did''nt support you!!!\n\n               warn (.warn) and del (.del) mails can created by yourself!!\n               sUPERViSER insert for:\n                  %n - Username\n                  %m - warned times\n                  %d - delete days\n\nratio feature:\n               change users ratio!!!\n\nubytes feature:\n               reduce users uploadbytes!!\n\n2.OPTION:\n---------\nsUPERViSER show you all warned users!!\nThe features are the same as at the 1. Option!!!\n\n3. OPTION:\n----------\nZIPPY SEARCH allows you to scan a user!!!\nWildcard Pattern Matching Allowed!\n\n4. OPTION: (only for REGISTERED USERS!)\n----------\nSAVE all changes to the USER.DATA AND USER.KEYS!!!\n\n5. OPTION:\n----------\nQuit sUPERViSER!!!\n\n\n\nsUPERViSER was tested on:\n\n                 A1200/20/68882    (CøRteX, about 100 USERS)\n\n\nThats it... have phun with this nice door!\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Installation "iNStALLATiON!"\n\n                           . [ INSTALLATION ] .\n                            - -------------- -\n\nCopy the files in the archive to your directories, they are:\n\nLIBS:AEDoor.library ( © Sintax/WOT )  thx!!!\n\nfor /X v2.x or SiX:\n\nadd thiz line to your cmds\nBBS:Commands/BBS.Cmd\n\nBBS:Doors/sUPERViSER/sUPERViSER.Xim\nBBS:Doors/sUPERViSER/sUPERViSER.cfg\nBBS:Doors/sUPERViSER/sUPERViSER.guide\nBBS:Doors/sUPERViSER/sUPERViSER.del\nBBS:Doors/sUPERViSER/sUPERViSER.warn\nBBS:Doors/sUPERViSER/sUPERViSER.dta (will be created!)\n\nfor /X v3.x or higher:\n\nBBS:Commands/BBSCmd/sv.info\n\nBBS:Doors/sUPERViSER/sUPERViSER.Xim\nBBS:Doors/sUPERViSER/sUPERViSER.cfg\nBBS:Doors/sUPERViSER/sUPERViSER.guide\nBBS:Doors/sUPERViSER/sUPERViSER.del\nBBS:Doors/sUPERViSER/sUPERViSER.warn\nBBS:Doors/sUPERViSER/sUPERViSER.dta (will be created!)\n\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Configfile "cONFiGfiLE!"\n\n\n                       . cONFiGfiLE fOr sUPERViSER! .\n                        - ------------------------ -\n\n---[start of configfile!]---\n\nsUPERViSER v0.3 (c)95 by CøRteX/tRSi\n\n[<------ max. 30 Chars ------>]\n#\n60                            ;days back when user will be shown to warn\n14                            ;days forward when user should be deleted!\n3                             ;times been warned user will be shown to delete\n100000                        ;up and down different when user will be shown in warn status!\nbbs:user.data                 ;full path and name for User.data\nbbs:user.keys                 ;full path and name for User.keys\nNO                            ;put warnmails into ACTUAL conference else\nBBS:CONFS/CONF1/              ;into this fix conference!!\n\n-----[End of configfile]-----\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Troubles "TROUBLE-SHOOTiNGs"\n\n                            . TROUBLE-SHOOTiNG .\n                             - -------------- -\n\n                  ½½½½½½½½   ½½½½½½½  ½½½½½½½½  ½½½½  ½½½½\n                  ½½½½ ½½½½      ½½½½ ½½½½ ½½½½ ½½½½  ½½½½\n          28.8k   ½½½½ ½½½½      ½½½½ ½½½½ ½½½½ ½½½½ ½½½½   ·:cREw:·\n                  ½½½½ ½½½½  ½½½½½½½½ ½½½½½½½½  ½½½½½½½½\n           VFC    ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½    CøRteX\n                  ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½  ½½½½    DjAX\n          pOWER   ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½  ½½½½   D`sTyLE\n                  ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½  ½½½½    lOGiC\n                  ½½½½½½½½   ½½½½½½½½ ½½½½ ½½½½ ½½½½  ½½½½ ctx!\n\n               ^-aMiGA^-^/X dOORz & Utilz^-^cONSOlEz^-^mUZAX-^\n\n               tRSi ·: + 4 3 - 5 1 2 - 3 6 5 - 3 0 2 :·  AHQ!!\n\n    ½½½½ ½½½½      ½½½½      ½½½½ ½½½½   ½½½½½½  ½½½½  ½½½½½½½  ½½½½½½½\n         ½½½½      ½½½½      ½½½½ ½½½½ ½½½½           ½½½½ ½½½½ ½½½½ ½½½½\n    ½½½½ ½½½½      ½½½½      ½½½½ ½½½½ ½½½½½½½½  ½½½½ ½½½½ ½½½½ ½½½½ ½½½½\n    ½½½½ ½½½½      ½½½½      ½½½½ ½½½½      ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½\n    ½½½½ ½½½½      ½½½½      ½½½½ ½½½½      ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½\n    ½½½½ ½½½½      ½½½½      ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½\n    ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½\n    ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½\n    ½½½½  ½½½½½½½   ½½½½½½½   ½½½½½½½  ½½½½½½½½  ½½½½  ½½½½½½½  ½½½½ ½½½½\n\n           A1200/33MhZ^-^SiX v3.x^-^hYdRa tRaNsfErZ^-^720MB oNLiNE\n\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Other "OTHER dOORs/TOOLS"\n\n                          . OTHER dOORs/TOOLS .\n                           - --------------- -\n\n                    XiM     Security Guide       v0.4\n                    XiM     Show Doors           v0.4\n                    XiM     ctx!CoMMeNt          v0.3\n                    XIM     Upload Detector      v0.5\n                    XIM     Front Guard          v1.0\n                    DOS     Offline Mover        v0.3b\n                    XIM     Turbo Lister         v0.3\n                    XIM     pAY mAil             v0.1\n                now XIM     sUPERViSER           v0.4\n\n\nIF YOU LIKE MY DOORS/UTILS AND WANT BE @{" REGISTERED " LINK Register} USER OF IT\nCALL MY BBS: Dark Illusion ++43-512-365-302!! no NUP! no SYSPASS!\n\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Register "REGISTER ME!"\n\n                             . REGISTER ME! .\n                              - ---------- -\n\nTHE REGISTRATION FEE IS 15$, SHURE YOU THINK PHUU! A LOTS OF MONEY, BUT READ\nWHAT YOU WILL GET FOR YOUR MONEY.\n\n1. THERE ARE A LOTS OF DOOR CODERS BUT ARE YOU SURE THAT YOU GET A DOOR\n   WITHOUT ANY BACKDOORS?? SO I HATE BACKDOORS AND VIRUSES ETC.\n   SO REMEMBER EVERY DOOR FROM ME IS 120% BACKDOOR FREE!!!\n   THE REGISTERED USER(S) ARE GETTING A PRIVATE VERSIONS, ALL PUBLIC\n   VERSIONS HAVE FROM NOW ON SOME OPTIONS REMOVED OR SOME NERVIOUS REGISTER ME\n   STRINGS WITH WAIT LOOPS heehe  ONLY! THE REGISTERED USER HAVE\n   THE FULL VERSION. REMEMBER THIS!!\n\n2. YOU FOUND A BUG ? -> REPORT HIM TO ME AND YOU GET SOON AS POSSIBLE A\n   FIXED VERSION, NO LONG NEED TO WAIT FOR A NEWER RELEASE VERSION.\n\n3. YOU HAVE SOME GOOD IMPROVEMENTS, TALK WITH ME, AND I WILL SEE IF I CAN\n   RELEASE IT.\n\n4. YOU NEED A PRIVATE DOOR ONLY FOR YOUR BBS, I WILL CODE THEM!!\n\n5. PRIVATE SUPPORT CONFERENCE IN MY BBS FOR ALL REGISTERED USERS.\n\n6. ALL DOORS/UTILS ARE INCLUDING YOUR REGISTER STRING.(CODED!)\n\n7. YOU`LL GET ALL LATER VERSIONS OR NEW DOORS FOR THIS PRICE.\n\n                  SIMPLY YOU GET THE BEST SUPPORT AROUND.\n          THINK ABOUT IT AND KEEP THE PROGRAMMERS PROGRAMMING !!!\n\nIF YOU ARE INTERESTED SO CONTACT ME AT ANY TRSI BOARD OR SIMPLY AT THE\n                        TRSI AHQ - DARK ILLUSION!!\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Greetings "GREETINGS"\n\n                          . SOME FAST GREETINGS .\n                           - ----------------- -\n                                  · TO ·\n\n             [*] MARIO,SIEGEL,BYTEANDI,DR.DRE,SPY,UYANIK!, [*]\n         [*] ECS,SAL-1,SHADE,SUNJAMMER,KNACKOSOFT,CONTROL/TRSI [*]\n            [*] INSPECTOR,ICE TEA/CLS [*] AUTOPSY,FELON/HLM [*]\n       [*] CALYPSO/GOD [*] DJAX,SAUZER,PRAYER/R^D [*] AYATOLLAH [*]\n         [*] PSYCHO/2KAD [*] ENZO [*] UFO,METAL DEATH/LEPROSY [*]\n               [*] D`STYLE [*] KNIGHT FIGHTER [*] TURBO [*]\n\n                      ... and all i have forgotten ...\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n','\n',char(10)),NULL,'auto-added',17720,7,0,NULL,NULL,'trsi_sv3','scan',1780048798);
INSERT INTO door_catalog VALUES('trsi_sv4','TRSI-SV4.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-SV4.LHA',NULL,'XIM','sUPERViSER.XiM',NULL,NULL,'TRSI','in   \         /  / \  /_   /   /tRiStAR \__   /  \  \_/\   \ /   /    & 1995    /   /___j\__/_____//   /    RSi',replace('        _____ __   /__ ____/    ____\n   in   \         /  / \  /_   /   /tRiStAR\n         \__   /  \  \_/\   \ /   /    &\n  1995    /   /___j\__/_____//   /    RSi\n    - ---/___/--/X-sECtiON--/___/--- -\n.-ctx!-------------------------------------.\n|sUPERViSER v0.4ß (bEtA pUBliC XiM vERSiON)|\n| bESt uSERliStER dOOR aVAilAblE fOR SiX/X |\n| wRiTiNG wARN-/dElMAilS,cHANGE rAtiO-bYtES|\n|aND dElEtE uSERs! MAJOR UPDATE! LEECH IT! |\n`------------------------------------------''\n','\n',char(10)),'sUPERViSER.GUIDE',replace('@DATABASE\n@Remark $VER: sUPERViSER v0.4 by CøRteX/tRSi (29.04.95)\n@Remark AmigaGuide DataBase for sUPERViSER v0.4\n\n@Node MAIN "sUPERViSER v0.4 - MAJOR UPGRADE!"\n                        _____ __   /__ ____/    ____\n                   in   \         /  / \  /_   /   /tRiStAR\n    ·: SiX/X :·          \__   /  \  \_/\   \ /   /    &      ·: X¡M/aSM :·\n                  1995    /   /___j\__/_____//   /    RSi\n                    - ---/___/--------[ctx!]/___/--- -\n                                CøRteX! oF\n                       tRiStAR aNd rEd^sECtOR iNC.\n\n          iS pROUd tO pRESENt: sUPERViSER v0.4 (MAJOR UPGRADE!)\n\n                 @{"      ·*·      cOPYRiGHt!    ·*·      " LINK Copyright}\n                 @{"      ·*·    iNtRoDUCtiON!   ·*·      " LINK Introduction}\n                 @{"      ·*·    iNStALLATiON!   ·*·      " LINK Installation}\n                 @{"      ·*·     cONFiGfiLE!    ·*·      " LINK Configfile}\n                 @{"      ·*· tROUBlE-shOOtiNGs! ·*·      " LINK Troubles}\n                 @{"      ·*·  oTER dOORs/tOOlS! ·*·      " LINK Other}\n                 @{"      ·*·     GREETiNGS!     ·*·      " LINK Greetings}\n                 @{"      ·*·    REGiStER mE!    ·*·      " LINK Register}\n@ENDNODE\n\n@NODE Copyright "cOPYRiGHt!"\n\n                             . [ cOPYRiGHt: ] .\n                              - ------------ -\nThis program is FREEWARE!\n\nIt can be freely copied and distributed for non-commercial purposes,\nprovided that no file is added to or removed from the distribution\narchive and no charge, beside a nominal fee, is requested.\n\nThe whole Copyright is reserved by the Author (myself!), and without\nwritten Permission it''s not allowed to distribute this Program in any\ncomercial way.\n\nThis version is a UNREGISTERED PUBLIC version! If you want to register,\nyou have to pay a @{"registration" LINK register}\n\n\n@{"  MAIN  " LINK MAIN}\n\n@ENDNODE\n\n\n@NODE Introduction "iNtRoDUCtiON"\n\n                           . [ iNtRoDUCtiON: ] .\n                            - --------------- -\n\nYou have seen many Userlist dOORS??? But no dOOR have the features\nand options like sUPERViSER!!\n\nnO AREXX shitt!! - pure ASM coding!!\n\nAll what you need is any Model of the great AMIGA, OS2.x or higher.\nand the AEDoor.library ( © Sintax/WOT )\n\nREAD UPDATE.NFO for changes from v0.3 -> v0.4!!\n\n1.OPTION:\n---------\nsUPERViSER shows you all users with there up/downloadbytes, ratios,\nusernumber, warnmail status and last called days !!\nIf a user is lame, because he leech or don''t call often or\nwould be warned example: 3 times, he will be shown in different\ncolours and a prompt will ask you to delete/warn/ratio/ubytes the user!!\n\ndelete feature:\n                delete user (user will be shown in different colour\n                             and warnmail counter will be set to 0)\n           or undelete user (user will be reactivated)\n\nwarn feature:\n               send user a warn or delete mail!!\n               (YOU CAN WRITE YOUR OWN MESSAGES IF YOU WANT.\n                JUST EDIT THE FILES .DEL and .WARN!!!)\n\n               by sending a warn mail the warn counter will be added\n               until 9 (configable) mails. after this, the warnmails\n               will be shown in a different colour!\n               by sending a del mail a X will be printed, in a\n               different colour, instead of the warn number!\n               (this means, that you send him a del mail!)\n\n  not included at version 0.4:\n               after ex.14 days, sUPERViSER will print a messy to\n               delete him if he did''nt support you!!!\n\n               warn (.warn) and del (.del) mails can created by yourself!!\n               sUPERViSER insert for:\n                  %n - Username\n                  %m - warned times\n                  %d - delete days\n\nratio feature:\n               change users ratio!!!\n\nubytes feature:\n               reduce users uploadbytes!!\n\n2.OPTION:\n---------\nsUPERViSER show you all warned users!!\nThe features are the same as at the 1. Option!!!\n\n3. OPTION:\n----------\nZIPPY SEARCH allows you to scan a user!!!\nWildcard Pattern Matching Allowed!\n\n4. OPTION:  NEW!\n----------\nINFO CORNER gives you some important views over your users!\n(online-/deleted-users and warn-/del-mails!)\n\n5. OPTION: (only for REGISTERED USERS!)\n----------\nSAVE all changes to the USER.DATA AND USER.KEYS!!!\n\n6. OPTION:\n----------\nQuit sUPERViSER!!!\n\n\n\nsUPERViSER was tested by:\n\n  GT-ONE, CAPT.CHURCH, PSYCHO,....\n\nthx pals!!!\n\nThats it... have phun with this nice update!!\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Installation "iNStALLATiON!"\n\n                           . [ INSTALLATION ] .\n                            - -------------- -\n\nCopy the files in the archive to your directories, they are:\n\nLIBS:AEDoor.library ( © Sintax/WOT )  thx!!!\n\nfor /X v2.x or SiX:\n\nadd thiz line to your cmds\nBBS:Commands/BBS.Cmd\n\nBBS:Doors/sUPERViSER/sUPERViSER.Xim\nBBS:Doors/sUPERViSER/sUPERViSER.cfg\nBBS:Doors/sUPERViSER/sUPERViSER.guide\nBBS:Doors/sUPERViSER/sUPERViSER.del\nBBS:Doors/sUPERViSER/sUPERViSER.warn\nBBS:Doors/sUPERViSER/sUPERViSER.dta (will be created!)\n\nfor /X v3.x or higher:\n\nBBS:Commands/BBSCmd/sv.info\n\nBBS:Doors/sUPERViSER/sUPERViSER.Xim\nBBS:Doors/sUPERViSER/sUPERViSER.cfg\nBBS:Doors/sUPERViSER/sUPERViSER.guide\nBBS:Doors/sUPERViSER/sUPERViSER.del\nBBS:Doors/sUPERViSER/sUPERViSER.warn\nBBS:Doors/sUPERViSER/sUPERViSER.dta (will be created!)\n\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Configfile "cONFiGfiLE!"\n\n\n                       . cONFiGfiLE fOr sUPERViSER! .\n                        - ------------------------ -\n\n---[start of configfile!]---\n\nsUPERViSER v0.4 (c)95 by CøRteX/tRSi\n\n[<------ max. 30 Chars ------>]\n#\n60                            ;days back when user will be shown to warn\n14                            ;days forward when sysop should be warned to delete the user!\n4                             ;times been warned when sysop will be warned to write hi a Delmail\n1000000                       ;up and down different when user will be shown to warn!\nyes                           ;all ratio Users wouldn''t be warned by Superviser!\nbbs:user.data                 ;full path and name for User.data\nbbs:user.keys                 ;full path and name for User.keys\nNO                            ;put warnmails into ACTUAL conference else\nBBS:CONFS/CONF1/              ;into this fix conference!!\n\n-----[End of configfile]-----\n\n@{"  MAIN  " LINK MAIN}\n@ENDNODE\n@NODE Troubles "TROUBLE-SHOOTiNGs"\n\n                            . TROUBLE-SHOOTiNG .\n                             - -------------- -\n\n                  ½½½½½½½½   ½½½½½½½  ½½½½½½½½  ½½½½  ½½½½\n                  ½½½½ ½½½½      ½½½½ ½½½½ ½½½½ ½½½½  ½½½½\n          28.8k   ½½½½ ½½½½      ½½½½ ½½½½ ½½½½ ½½½½ ½½½½   ·:cREw:·\n                  ½½½½ ½½½½  ½½½½½½½½ ½½½½½½½½  ½½½½½½½½\n          V34/DS  ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½    CøRteX\n                  ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½ ½½½½  ½½½½    DjAX\n          pOWER   ½½½½ ½½½½