INSERT INTO door_catalog VALUES('trsi_t2f','TRSI-T2F.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI-T2F.LHA','T2F','XIM','LEBKUCHEN.exe.bak',NULL,NULL,'TRSI','. .____.   _______    ._____  \    (((___ . _|    |_  \_____ \_ _|  __/___\         \_ .\_  ___/___|   /  /_\_____     \_________/',replace('                              ______ _\n. .____.   _______    ._____  \    (((___ .\n _|    |_  \_____ \_ _|  __/___\         \_\n.\_  ___/___|   /  /_\_____     \_________/\n. /  \      | _/      |   /      |       |.\n:/____\     l_\       l___\      |     __|:\n+======\____|==\______|bHe=\_____l_____\==+\n|                                         |\n|  tRSi (/F·iNNOvATION) presents in 1997  |\n|   Tempest to FAME User Data converter   |\n|                                         |\n`-----------------------------------------''\n','\n',char(10)),'T2F.readme',replace('Short:    Tempest to FAME UserData-converter (v1.00)\nUploader: [email removed] (Michael ''Zod/Trsi'' A.)\nAuthor:   [email removed] (Michael ''Zod/Trsi'' A.)\nType:     comm/bbs\n\n--- 02-11-97 --- An after-halloween tRSi production in 1997 ---\n\nT2F - Tempest to FAME BBS User Data converter. This tool does convert\neverything important ( i guess ) from Tempest to FAME,\n\nIt also defaults all other FAME user data elements to the original\nFAME default values.\n\nIf you need more to be converted just enhance the T2F.c source code!\n\nFor more informations how to use T2F etc. just start T2F in a shell\nand read the instructions.\n\ntRSi-T2F.lha contends:\n\n - make               9 bytes\n - SCOPTIONS        147 bytes\n - T2F            6.728 bytes\n - T2F.c         20.813 bytes\n - T2F.readme       850 bytes\n\n\nPS: Thanx to chels for some "real" tempest userdata :).\n\n<EOF>\n','\n',char(10)),NULL,'auto-added',17475,1,0,NULL,NULL,'trsi_t2f','scan',1780048798);
