INSERT INTO door_catalog VALUES('trsi_ma','TRSI_MA.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI_MA.LHA',NULL,'XIM','DFITF107',NULL,NULL,'TRSI','MultiAdder V1.00',replace('Ransom - 1-305-247-7605   \nMultiAdder V1.00\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                                                .------''\n             `------------------------------------------------''\n','\n',char(10)),NULL,'auto-added',95526,8,0,NULL,NULL,'trsi_ma','scan',1780048806);
INSERT INTO door_catalog VALUES('trsi_wld','TRSI_WLD.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRSI_WLD.LHA','WORLD-CLOCK','XIM','WORLD-CLOCK',NULL,'SieGeL/tRSi','TRSI','\    ____    )  /___/\_| & rED sECTOR ¡NC | .-\___\ | \___\__   /   |  /X ¡NNOVATION   | )---|___|___|______/____|---[ [RESENTS ]---''',replace(' _____________ ___Mo! __.<---[ tRISTAR ]---.\n \    ____    )  /___/\_| & rED sECTOR ¡NC |\n.-\___\ | \___\__   /   |  /X ¡NNOVATION   |\n)---|___|___|______/____|---[ [RESENTS ]---''\n|\n| wORLD-cLOCK V1.18 wRITTEN bY SieGeL/tRSi\n`------------------------------------------.\n fIXED sOME eNFORCER-hITS, 2 nEW tOOLTYPES,|\n.------------------------------------------''\n|   aDDED nEW dIGITS fROM 2fAST/aRTcORE!\n`------------------------------------------.\n     gET tHE bEST /X-cLOCK eVER wRITTEN <--''\n','\n',char(10)),'WoRLD-CLOCK.GUIDE',replace('@database World-Clock V1.18 by SieGeL/TRSi (/X-iNNoVaTioN) BeRLiN-GeRMaNY\n\n@Remark $VER: V1.18 (Sunday 11-13-1994)\n\n@node Main "WoRLD-CLoCK V1.18 - /X uTiL WRiTTeN BY SieGeL/tRSi"\n@{b}\n  _______________________________________________                  _______\n |  ___________      _______. ___________ _______|_      _________|_    _/\n |  \\    _____/_____(_______:/   __     /___  ____/_____/_   __    /___ |\n | _/\\_______     /         :   _______/   /  \\__        /  ______/   / |\n | \\ _ __________/__________:_____________/_____/  Mo!  /____________/  |\n |  \\\\ /                                       /_______/          l_____|\n |   \\/  @{ub}SIEGEL/TRSI (/X·INNOVATION) PRESENTS    @{b}|\n |      -------------------------------------    |     @{" INTRODUCTION " Link INTRO}\n |                                               |     @{" INSTALLATION " Link INSTALLATION}\n |                                               |     @{"  TOOL-TYPES  " Link TOOLTYPES}\n |            @{ub}··W·O·R·L·D··C·L·O·C·K··@{b}           |     @{"  ARGS IN /X  " Link ARGS}\n |                                               |     @{"DIGIT-EXAMPLES" LINK DIGITS}\n |                  @{ub}V1.18 pUBLIC@{b}                 |     @{"  GREETINGS!  " Link GREETS}\n | \\                                             |\n | \\\\\                                            |   @{u}gRAPHICAL dESIGN bY@{uu}\n @{b}`-----------------------------------------------''@{ub}\n  AMBLIN/dEZiGN / COUNT ZER0/SCL / aXe/MST / -rEDSKIN/aRT / 2fAST/aRTcORE!\n@endnode\n\n@node INTRO "INTRODUCTION"\n\n                              @{u}iNTRODUCTION@{uu}\n\nAehm...in the last public Version (V1.16) I had said that *NO* update of \nthis clock will be ever released in the Future...but then 2fAST from \naRTcORE! had painted a nice charset, so I decided to write another update..:)\n\nDuring the update, I made again some changings in the code, now it''s possible\nto define the Date & Location Line for yourself. Detailed Informations for\nthis could be found in the @{"ToolTypes" LINK TOOLTYPES} - Chapter.\n\nTo get a complete overview what changed take a look to the @{b}History-File@{ub} \nincluded in this archive...let''s go on with @{"Installation" LINK INSTALLATION}...\n@endnode\n\n@node INSTALLATION "INSTALLATION OF WORLD-CLOCK V1.18"\n\n                       @{u}rEQUIREMENTS & iNSTALLATION@{uu}\n\nOf course you need any Amigamodel (500-4000T) with Kickstart V37++ and a full\ninstalled and working Amiex (Should work under /X V2.xx, too).\n\nPut wORLD-cLOCK V1.18 and the icon wherever you want, but I recommend to \ncreate an Directory for wORLD-cLOCK, coz wORLD-cLOCK is now able to save the\nuser-preferences, and they will be saved in the dir wORLD-cLOCK is started\nfrom.\n\n@{u}NOTE:@{uu} In difference to previous versions, wORLD-cLOCK needs @{b}*NO*@{ub} icon anymore\n      to run correctly. So if you don''t copy the icon to the same drawer the \n      clock is stored, wORLD-cLOCK only shows the local time. The times of \n      the other cities couldn''t be displayed, coz you have to define the GMT-\n      Time-Offset in the Icon to let wORLD-cLOCK calculates the other times !\n\nCopy the icon `T.info'' to your BBSCMD/ drawer and change the Location to the\npath where wORLD-cLOCK V1.18 could be found. That''s all. To configure the \nClock to your needs take a look to the @{"Tooltypes" link TOOLTYPES}.\n\n@{u}NOTE:@{uu} Starting from V1.16, every user is able to configure the clock to his \n      own needs, and therefore it''s not neccessary that you configure the\n      clock in the icon. If you configure it in the Tooltypes, this\n      configuration is only the default one which will be overwritten by the\n      user''s config.\n@endnode\n\n@node TOOLTYPES "ALL TOOLTYPES USED BY WORLD-CLOCK V1.18"\n\n                              @{u}tOOLTYPES@{uu}\n\n LOCATION=<string>       = Here you could enter the Location of your city,\n                           i.e. Berlin-Germany. If you don''t want to enter\n                           a Location, put this Tooltype in Branches. The\n                           Clock uses then as location the name of your bbs.\n\n LOCATION_LINE=<string>  = Here you could define your own default-line for\n                           the location from where the time is shown. \n                           Default is :\n                           "tIME sHOWING fROM %L" <-- The %L will be replaced\n                                                      by your Location !!!\n\n                           This will be used if you don''t define this Tool-\n                           type.If you want to specify your own, make sure\n                           that you don''t write too much chars, coz the %L\n                           will always replaced by your Location ! Of course\n                           you don''t have to use the %L command, in this case\n                           only the string you have defined will be printed.\n\nDATE_LINE=<STRING>       = This command allows you to define your own Date-\n                           line...for this option currently exists two \n                           commands:\n\n                           %T  --> Day (i.e. Wednesday)\n                           %D  --> The actual date (i.e. 09-FEB-95)\n\n                           The Defaultsetting for this option is :\n\n                           "actual systemdate is %D (%T)"\n\n                           @{u}NOTE FOR WB 2.1++ USERS:@{uu}\n                           Both commands will be translated to the Language,\n                           you have defined in your SYS:Prefs/Locale Program.\n                           So if you have German as default language, both\n                           commands will be translated in :\n                          \n                           %T = Mittwoch and %D = 09.02.95 \n                           \n GMT=<GMT-Time>          = Here you must define your GMT-Time (GMT=Greenwich-\n                           MeanTime). For Germany, it''s +1. If U don''t define\n                           this Tooltype, the WoRLD-CLoCK wouldn''t be shown,\n                           you only see the time from your board.\n\n LINE_ART=<char>         = If you want to seperate the Clock from the cities,\n                           you could enter here *one* char (i.e. -, +, =) and\n                           this char will be used to create two lines between\n                           the clock and the cities. If you don''t want to \n                           seperate it, put this Tooltype in branches or don''t \n                           define a char for it.\n\n CHARSET=<number>        = I''ve included five different styles for the clock.\n                           Here you could choose which one will be used to\n                           show the time. Only 0,1,2,3 and 4 are allowed as \n                           valid numbers. The numbers are defined as follow:\n\n                           0 = dIGITS fROM Amblin (Default!) \n                           1 = dIGITS fROM Axe\n                           2 = dIGITS fROM Count Zero\n                           3 = dIGITS fROM -redSkin\n                           4 = dIGITS fROM 2fAST/aRTcORE!\n                     \n                           To check out the digits, take a look to @{"DIGITS" Link Digits}.\n\nAll following ToolTypes are the defines for the colors. Valid colornumbers are\n30-37, which represents the ANSI-Colors in /X. I recommend not to use 30, as \nthis color is black and you won''t see very much if you enter it...:)\n\n MAIN_COLOR=<color>      = The color for the Title and the Lines between the\n                           clock and the cities. Default is 33 (yellow).\n\n CITY_COLOR=<color>      = The color for "TIME SHOWING FROM.." and the cities.\n                           Default is 36 (light blue).\n\n DIGITS_COLOR=<color>    = The color for the digits and the citytimes. Default\n                           is 35 (lila).\n\n DATELINE_COLOR=<color>  = The Color for the Dateline ( MM-DD-YY (DAY) ).\n                           Default is 34 (dark blue).\n@endnode\n\n@node ARGS "KNOWN ARGUMENTS GIVEN AT AMIEX-PROMPT"\n\n                             @{u}aRGUMENTS@{uu}\n                             \nYou could start the clock in three different ways...\n\n@{u}1) Normal Start:@{uu} @{b}T@{ub}\nThis is the easiest way to start the clock...the actual time(s) will be shown\nand the clock quits.\n\n@{u}2) Configuration:@{uu} @{b}T E@{ub}\nIf you start the clock in this mode, you get an optionsscreen which allows \nall users to configure their ''own'' clock-style. In Configuration-Mode the \nfollowing options are accessable:\n\n@{b}1@{ub},@{b}2@{ub},@{b}3@{ub},@{b}4@{ub} - Changes the Colors of the clock\n\n   @{b}5@{ub}    - Allows you to change the seperator char\n\n   @{b}6@{ub}    - Select the Digitstyle, available are five different ones. Take a\n          look to @{"DIGITS" Link DIGITS} for some examples.\n\n   @{b}7@{ub}    - Select one of five different Date-Formats.\n\n   @{b}S@{ub}    - Save current settings as default ones and display the clock in the\n          current settings.\n\n   @{b}P@{ub}    - ''Preview'' of current settings..use this if you don''t know how the\n          current settings looks like...:)\n\n   @{b}A@{ub}    - Use current Settings and start wORLD-cLOCK in Animation-Mode.\n\n   @{b}Q@{ub}    - No saving and reset Settings to default.\n\n\n@{u}3) Animation:@{uu} @{b}T A@{ub}\nIn this mode wORLD-cLOCK starts with displaying the time(s), but in \ndifference to the normal mode the Local-System-Time will be updated every\nsecond and the World-Times will be updated every minute. To stop the anim\nsimply press @{b}CTRL-C@{ub} to return to mainprompt.\n@endnode\n\n@node Digits "SOME EXAMPLES FOR THE DIGIT-STYLES"\n\n--------------------------- aMBLiN/DeZiGN -----------------------------------\n\n  .######.  .####   .######. .######. ###   .  ######## .######. ########\n  ###  ###  #####   ##   ### ###  ### ###  .#  ###      ###  ###    .####\n  ###  ###   ####        ###      ### ### .##  ###      ###        .####\n  ### .###   ####   .######    #####  ### ###  #######. #######.   #### \n  ### ####   ####   ###          .### ########     .### ### .###   ####\n  ### ####   ####   ### #### ### ####    ####  ### #### ### ####   ####\n  ### ####   ####   ### #### ### ####    ####  ### #### ### ####  .####.\n  `######'' ######## ######## `######''   ###### `######'' `######''  ######\n                                              \n------------------------------ aXe/MYSTiC -----------------------------------\n\n  .######.  .###### #######. #######. ###  ### ######## .####### #######.\n  ######## .####### ######## ######## ###  ### ######## ######## ########\n  ###  ### ###''####    .####      ### ###  ### ###      ###           ###\n  ### ####     ####  .#####''   ###### ######## #######. #######.   ######\n  **** ***     **** .*****''    ****** `******* ******** ********   ******\n  ***  ***     **** ****''         ***      ***      *** ***  ***      *** \n  ***  ***     **** ******** ********      *** ******** ********      ***  \n  `******''     **** `******* *******''      *** *******'' `******''      ***\n\n-------------------------- CouNT ZeRo/SCaNDaL! ------------------------------\n\n.:::::::. :::::.    :::::.    :::::. ::::      ::::::    .:::::    .::::::::\n:::: ....   ....      ....      .... :::: .... ::::      ::::      :::: ....\n:::: ::::   :::: .:::::::·     ::::· ·:::::::: ::::::::. ::::::::.      ::::\n:::: ::::   :::: :::: .... :::: ::::      :::: .... :::: :::: ::::      ::::\n·:::::::·   :::: ·:::::::: ·:::::::·      :::: ·:::::::· ·:::::::·      ::::\n\n------------------------------ -redSkin/aRT ---------------------------------\n\n .......  .......    .....    .....   ... ...  .....    .....   ....... \n:::: :::    :::::: .....:::     .::: :::: ::: ::::...  ::::....  .::::::\n:::: :::    :::::: :::: ... .... ::: :::: ::: .... ::: :::: :::   ::::::\n:::: :::    :::::: :::: ::: :::: ::: :::: ::: :::: ::: :::: :::   ::::::\n:::: :::    :::::: :::: ::: :::: ::: :::: ::: :::: ::: :::: :::   ::::::\n:::: :::    :::::: :::: ::: :::: ::: ::::.::: :::: ::: :::: :::   ::::::\n:::: :::    :::::: :::: ::: :::: :::      ::: :::: ::: :::: :::   ::::::\n   `-''                `-''      `-''               `-''      `-''\n\n------------------------------ 2fAST/aRTcORE! -------------------------------\n\n  .:   ::::.   ::::. ::: ::: .::::   .::::   ::::. .:::::. .:::::. .:::::.\n  ::   :::::   ::::: ::: ::: :::::   :::::   ::::: ::::::: ::::::: :::::::\n :::     :::     ::: ::: ::: :::     :::       ::: ::: ::: ::: ::: ::: :::\n :::  .:::::   ::::: ::::::: ::::::. ::::::.  .::: `:::::'' ::::::: ::: :::\n ::: ::::::''   ::::: `:::::: `:::::: :::::::  :::: ::::::: `:::::: ::: :::\n ::: :::         :::     :::     ::: ::: :::  :::: ::: :::     ::: ::: :::\n ::: ::::::: :::::::     ::: ::::::: :::::::  :::: :::::::   ::::: :::::::    \n ::: `:::::: ::::::''     ::: ::::::'' `:::::''  :::: `:::::''   :