INSERT INTO door_catalog VALUES('try_eu10','TRY_EU10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRY_EU10.LHA',NULL,'XIM','_________ _    ____________________________',NULL,NULL,'TRY','\      /¬¡¬\::/ __)__   ¬/ _¬\   _  ¬\ ¬| ¬\ :\/  \/  _  \/  __/\/   /  _  \  ____/  ___/ :/    \  !   \  l   \   \  !   \ |::/   |:::',replace('_________ _    ____________________________\n\      /¬¡¬\::/ __)__   ¬/ _¬\   _  ¬\ ¬| ¬\\n:\/  \/  _  \/  __/\/   /  _  \  ____/  ___/\n:/    \  !   \  l   \   \  !   \ |::/   |:::\n:\____/__i___/______/\   \_i___/_|::\___|:::\n<-----> tHERAPy <---->\___/<-> pRESENTs <-->\n<- Extended User Information V 1.0 For /X ->\n','\n',char(10)),'EUInfo.doc',replace(replace('                  ._                                                  ._\n _________________| \_______________________________/\________________| \\n \___    ____/    |  \__     ____________    \______  \________  \    |  \\n    /    \  /     |   \/     ._|__/     |     \    |   \/     |   \____   \\n  _/      \/      _    \     |    \     _    _/    _    \     ____/   |    \\n  \________\______|     \_________/_____|    \_____|     \____|____________/\n               scel______/              l_____/    l______/            \r\n                                                                    \r\n                    PRESENTS : EXTENDEN USER INFORMATION\n     A SMALL DOOR FOR THE AMI-EXPRESS BBS SYSTEM VERSION 2.XX AND 3.XX\n\n                           ---- INSTALLATION ----\n\nTo Install add (for /X 2.xx) this to you BBS.CMD file\n\n--- cut ---\n*S        RM010DOORS:EUInfo/EUInfo.rexx\n--- cut ---\n\nTo install it on 3.xx put the icon included into your BBS.CMD dir...\n\n\n                              ---- NOTICE ----\n\nThis door won''t work properly with conference accounting....\nIf you have conf-accounting it will display the credits for the\ncurrent conference and not totaly...\n\n\n\n\nWell..  Not much to say...  You''ll figure it out anyway....\n\nFinally some greets to : Maddy - Mr Hyde - BSM - Dnss - Risc - Arkel -\n                         Alkaid - Lithium - Toxic - Kickface - Whiz -\n                         Tormentor - Heka - Sledge - Black Beard -\n                         ZoleX - The Messiah - The Undertaker\n                         And all i forgot in this hurry...\n','\r',char(13)),'\n',char(10)),NULL,NULL,6908,5,0,NULL,NULL,NULL,'scan',1780048806);
INSERT INTO door_catalog VALUES('try_lb30','TRY-LB30.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRY-LB30.LHA','Logon','XIM','Install.exe',NULL,NULL,'TRY','\      /¬¡¬\::/ __)__   ¬/ _¬\   _  ¬\ ¬| ¬\ :\/  \/  _  \/  __/\/   /  _  \  ____/  ___/ :/    \  !   \  l   \   \  !   \ |::/   |:::',replace('_________ _    ____________________________ \n\      /¬¡¬\::/ __)__   ¬/ _¬\   _  ¬\ ¬| ¬\\n:\/  \/  _  \/  __/\/   /  _  \  ____/  ___/\n:/    \  !   \  l   \   \  !   \ |::/   |:::\n:\____/__i___/______/\   \_i___/_|::\___|:::\n-dNSs-> tHERAPy <---->\___/<-> pRESENTs <---\nlOGON bATCH v3.o (XiM) Module for AmiExpress\n  Execute a Batch during Login Sequence!\n','\n',char(10)),'lOGON3o.guide',replace('@database lOGON bATCH v3.o\n\nlOGON bATCH v3.o (1oo% ASM) - © 1994 by WHiZ/eNDLESS pIRACY & tHERAPY!\nAll Rights Are Reserved!\n\n@Remark $VER: lOGON bATCH v3.0 (21.01.94)\n\n@node MAIN "lOGON bATCH v3.o Document In AmigaGuide Format"\n\n                _________ _    ____________________________\n                \\      /¬¡¬\\::/ __)__   ¬/ _¬\\   _  ¬\\ ¬| ¬\\\n                :\\/  \\/  _  \\/  __/\\/   /  _  \\  ____/  ___/\n                :/    \\  !   \\  l   \\   \\  !   \\ |::/   |:::\n                :\\____/__i___/______/\\   \\_i___/_|::\\___|:::\n                ::::::::::::::::::::::\\___/:::::::::::::::::\n\n                    proudly presents: lOGON bATCH v3.o\n\n                         @{"     Introduction      " Link Intro}\n                         @{"     Requirements      " Link Require}\n                         @{"     Installation      " Link Install}\n                         @{"     History           " Link History}\n                         @{"     Greetings...      " Link Greetz}\n\n@endnode\n@node Intro " Introduction"\n\nThis very small (1412 Bytes) AmiExpress XiM Door executes a Batch\ncalled "Logon.Batch" in your BBS: Dir. What it does is, it will\nexecute a Batch during the Login Sequence, so your LOGOFF.batch\ncan be reduced to a very small size and safes a lot of time.\nLogon.Batch is executed with the RunBack command in your C: Dir\nso you can have as much Utils as you want!\n\n@endnode\n@node Require " Requirements"\n\nAll you need to run this little Util is:\n\n- An Amiga, no matter which model.\n- Any Ami- or Sigma-Express version!\n- AEDoor.library by SiNTAX/WøT\n- RunBack Command in your C: Dir.\n- Logon.Batch in your BBS: Dir, protected with +s\n\nThats all...\n\n@endnode\n@node Install " Installation"\n\n- If you don''t have the AEDoor.library by SiNTAX/WøT in your LIBS:\n  dir already just copy the version included in this archive to your\n  LIBS: Dir.\n\n- This little Door also requires the RunBack Command in your C: Dir.\n  If you don''t have this command just copy my version included in\n  this archive to your C: Dir.\n\n- This Door is executed via the FrontEnd.info icon. Either copy\n  my FrontEnd.info icon to your BBS:Commands/SYSCmd/ Dir or create\n  a new FrontEnd.info icon with the following Tooltypes:\n\n  LOCATION=DOORS:Logon\n  TYPE=XIM\n  MULTINODE=YES\n  STACK=4096\n  ACCESS=001\n\n- Now create a Batch called BBS:Logon.Batch and protect it with +s\n  for instance: Protect BBS:Logon.Batch +s\n \n                        That''s it folks ...\n\n  This Util has been tested for a couple of weeks now without any\n  crashs or problems at all! Give my Board a Ring and see for yourself!\n\n  Thanks to Joker/ZZC for Beta-Testing!\n  \n  If you should find any Bugs or have any Suggestions, feel free to\n  contact me on PSYCHO TERMiNAL +1(914)682-1975 or via /XNet WHiZ@203001\n\n@endnode\n@Node History "History"\n\n  v1.0 - Internal Release\n  v2.0 - Internal Release, without RunBack Command\n  v3.0 - First Release, added RunBack and optimized code.\n\n@endnode\n@Node Greetz "Greetings"\n\n  JOKER/ZZC - Wie sieht''s aus mit dem Umzug :)? Thanx for ß-Testing!\n  THE CHAMP/XPR - Der Chat-Marathon ruft!\n  Hot Kid! - Nix mehr los in der Hos oder was?\n  THE SiLENCER/TRSI\n  MuMu/AFL - Alles Klar mit Key West?\n  Mr Hyde/TRY - Un grand merçi mec!\n  DNSS/TRY/F^I - Kewl AzKiis! Give me Ring!\n  WARLORD - Fötzchenpower ''94!\n  Freddy Krueger/GOD\n  The Fly/TRY - Pole Position rulez :)!\n  Godhead/QTX - Thanx for the cool logo! Give me Ring!\n  Buster & Fuzz/FLASH - Germania Conf Sysop isn harter Job!\n  Link^H2o/F^I - Nix mehr mit callen oder was?\n  Dalai Lama/GOD - Great PlayPen Mover!\n  EXoCET^ARCLiTe - Coole Logos!\n  SHADOWMAN\n  ALCAPONE\n  (-sLAZeR`) - Lang nix mehr von dir gehört!\n  Schwabenpower/ZZC - Hoffe dein Board kickt bald wieder!\n  Radar\n  Red Alert - Netmail ruhlt!\n  BBC/MoTioN - Danke für deine Hilfe!\n  2-Cool/LSD - Thanx for everything m8!\n  ScE/DTL - When are ya gonna release your Colly?\n  ErNeStO/RDC - Danke für den geilen Support!\n  Foxx''n''Lynxx/ZZC - Willst du immer noch umsteigen?\n\n  and of course to all eNDLESS pIRACY & tHERAPY mEMBERS wORLDWIDE!\n\n@endnode\n','\n',char(10)),'{"LOCATION":"DOORS:Logon","TYPE":"XIM","STACK":"4096","ACCESS":"001"}','auto-added',8206,2,0,NULL,NULL,'try_lb30','scan',1780048806);
INSERT INTO door_catalog VALUES('try_op20','TRY-OP20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRY-OP20.LHA','opage2','XIM','opage2',NULL,'Mr','TRY','\  _  .  |  |  ______  \__   \___    \/ |  | \/   | _|  |   _/ _/ _/  |   |  |   /  |  | /    | \.  |  |  \\   \__.   |  ___/__  __|',replace('______:__.__:__________ _____ _______  /|__.\n\  _  .  |  |  ______  \__   \___    \/ |  |\n \/   | _|  |   _/ _/ _/  |   |  |   /  |  |\n /    | \.  |  |  \\   \__.   |  ___/__  __|\n \  __|__|  |_____/_\    /|   |__|÷e÷/___\  \n+-\/----`---''--------\__/-`---''------------+\n    Operator Page 2.o By Mr Hyde/Therapy    \n+------------------------------------------+\n','\n',char(10)),'mastrb8.txt',replace(replace('STILL GOING STRONG in 2014!\r\n\r\n                ___         ._            _______             ·\r\n   /\  _________)  \________| \___________)__   /_________:__ :________\r\n  /  \/\  __  \    ____ ___/|  \______  \_  / _/___  \_ ____/ ¦__ \___ \\r\n /   /  \ \__  \___  \  |   |   \  _/  __/ /    /\__  \  |¦   | /  \_|  \\r\n/  \/    \_ \   \ !   \_|   !    \_\    \_     /   \   \ ||   |·    /|   \_\r\n\___|     ___\  /__    /l________ /_\    /__  /_____\  / |¦   |    /_|    /\r\n    l____/-A×E\/  \___/_!       \/   \  /   \/       \/__|:   ¦__ /  l___/\r\n       ______            _____        \/      :    ____   ·   : \/\r\n    ___)     \___________)    \__________:___ ¦____)   \__________\r\n    \    _______     _______    \___    ____/ |\_____   \______   \\r\n   /\___   \/        |    _)    \/       ¦    |/    |    \    |    \\r\n _/    !    \        |    \      \_      |    |     !     \   |     \\r\n \______     \___    |_____\      /___   |    ¦            \  |      \_\r\n       \______/ \____!      \    /   \___|    :________     \_|       /\r\n                             \  /        ¦    ·       \______/|      /\r\n   YOUVE HEARD ABOUT IT!      \/         :    ·               l_____/\r\n       \r\n         MASTURBATiON STATiON AMIGA/PC/CONSOLE/ASCII-ANSI/C64        \r\n               Telnet: bbs.masturbationstationbbs.com\r\n\r\n           UPLOAD DATE: 04-24-16  TIME: 05:18:09  ON NODE: 1\r\n\r\n  UPLOADER: Black Beard            LOCATION: mSTATION.servebbs.com    \r\n\r\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',12234,4,0,NULL,NULL,'try_op20','scan',1780048806);
INSERT INTO door_catalog VALUES('try_sb10','TRY-SB10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRY-SB10.LHA',NULL,'XIM','_________ _    ____________________________',NULL,NULL,'TRY','\      /¬¡¬\::/ __)__   ¬/ _¬\   _  ¬\ ¬| ¬\ :\/  \/  _  \/  __/\/   /  _  \  ____/  ___/ :/    \  !   \  l   \   \  !   \ |::/   |:::',replace('_________ _    ____________________________\n\      /¬¡¬\::/ __)__   ¬/ _¬\   _  ¬\ ¬| ¬\\n:\/  \/  _  \/  __/\/   /  _  \  ____/  ___/\n:/    \  !   \  l   \   \  !   \ |::/   |:::\n:\____/__i___/______/\   \_i___/_|::\___|:::\n<-----> tHERAPy <---->\___/<-> pRESENTs <-->\n<SeTTiNGS D-Base V1.0 For /X 2.xx & /X 3.xx>','\n',char(10)),'Setter.Doc',replace('                                            /\                               :\n        ____________________/\  ___________/  \  ______________________\n       /                      \/               \/                      \     :\ndNSs  / :          d o c t o r z    a r e    a f r a i d              : \\n ____/  ¡_  ________   ______________________________  _________  ____¡  \\n \_   ___/__\_     /__ \_   __   \_ ___   _/\_   __  \ \_   __  \ \_  |   \  :\n //   /     //   __   \//   _____// \__    \//   __   \//   _____\//____   \\n/ø    \    /ø    \    /ø    \   /ø    \    /ø    \    /ø    \::::/ø   \    /\\n\__________\______\  /\_________\______\  /\______\  /\______\:::\______  /··\\n \::::::::::\::::::\/··\:::::::::\::::::\/··\::::::\/··\::::::\¯¯¯\:::::\/···/\n  \::::::::::\::::::\··/\:::::::::\::::::\··/\::::::\··/\::::::\   \:::::\··/:\n   ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\/  ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\/  ¯¯¯¯¯¯¯\/  ¯¯¯¯¯¯¯    ¯¯¯¯¯¯\/ :\n                                                                             ¡\n                                                                  ___________!\n                                                                 (___________\n                      --oo00 P R E S E N T S 00oo--\n\n                        --> S E T T E R  V1.0 <--\n                            © 1993 FRaNKy-TRY\n\n\nHow To Contact The Author ?\n----------------------------\n\nSimply call Metal Impact (number below) or send your netmails\nto 2:292/603.8 (Fido)\n\nWhat Does It Do ?\n------------------\n\nWell basically, it just shows you a menu and from it, just select\nyour modem type and tzadaa.. there are those bad-2-get modem settings\nyou were searching for all those years (well, years)...\n\nWhat''s It Good For ?\n---------------------\n\nIt simply is a Modem-Settings Database so you don''t have to waste your\nbulletins to it...\n\nHow To Use It ?\n----------------\n\nJust type ''Setter'' at the main prompt to run it...\nIt''s self-guiding due to stupid (ehe) programming...\n\nHow To Install It ?\n--------------------\n\n/X 3.xx -> Snatch the Icon to your commands dir et voila...\n/X 2.xx -> Just add it into your bbs.cmd file.. I won''t tell you\n           how to do it cos it''s too easy, and almoast everyone\n           has switched to 3.xx by now anyway...\n\nGuess I don''t have 2 say that it belongs in Doors:Setter/ eh ?\n\nHow To Get Updates ?\n---------------------\n\nEASY ! Just call Metal Impact +32-50-393239 and beg for it to the sysop...\nIf you have any settigns that are not included just give this board a\nbuzz too.....\n\n\nHow To Delete It ?\n-------------------\n\nYOU JUST DON''T !!!!!\n\n\nQuick thankyouzz to :\n-=-=-=-=-=-=-=-=-=-=-=-\n\nMaddy         : For testing,main dezign & tips\n                (and let me crash his board 3 times :-) )\nKen           : Also for testing & tips\nKickface      : For The Zyxel & Supra settings\nGuy Devos     : For The Boca settings\nNoel Vroninks : For The Viva settings\nThe Messiah   : For The Zoom settings\n\n\n                   And Call These Therapy Boards Too !!!\n\n    .------------------------------------------------------------------.\n    | WHQ             Death Zone                       +1-714-956-4524 |\n    |                                                  +1-714-956-45o7 |\n    |                                                  +1-714-956-1413 |\n    |                                                                  |\n    | BHQ             Black Krypt                      +32-YOU-KNOW !! |\n    |                                                                  |\n    | EHQ             Deep Tought                      +358-775-1252   |\n    |                                                  +358-PRI-VATE   |\n    |                                                                  |\n    | BHQ             Maniac mansion                   +1-3-707-0753   |\n    |                                                                  |\n    | UKHQ            Northern X-posure                +44-642-788-778 |\n    |                                                                  |\n    | USHQ            Psycho Terminal                  +1-914-682-1975 |\n    |                                                                  |\n    | FHQ             Death Star                       +358-351-5969   |\n    |                                                                  |\n    | US CODER HQ     CD Exchange                     +1-616-669-2363  |\n    `------------------------------------------------------------------''\n','\n',char(10)),NULL,NULL,8416,4,0,NULL,NULL,NULL,'scan',1780048806);
INSERT INTO door_catalog VALUES('try_si20','TRY_SI20.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRY_SI20.LHA',NULL,'XIM','_________ _    ____________________________',NULL,NULL,'TRY','\      /¬¡¬\::/ __)__   ¬/ _¬\   _  ¬\ ¬| ¬\ :\/  \/  _  \/  __/\/   /  _  \  ____/  ___/ :/    \  !   \  l   \   \  !   \ |::/   |:::',replace('_________ _    ____________________________\n\      /¬¡¬\::/ __)__   ¬/ _¬\   _  ¬\ ¬| ¬\\n:\/  \/  _  \/  __/\/   /  _  \  ____/  ___/\n:/    \  !   \  l   \   \  !   \ |::/   |:::\n:\____/__i___/______/\   \_i___/_|::\___|:::\n<-----> tHERAPy <---->\___/<-> pRESENTs <-->\n<Sysop In V 2.0 For Ami-Express 2.xx & 3.xx>\n','\n',char(10)),'SysopIn.Doc',replace('_______ _ ___\n______////   ~×ø¸____ _ _____ _ _\n____/       /\_ _ _  \\\\___//// ~×ø,¸____ _ _ _ _     _     _        _\n__/  _ __  / ________ _______ _ ____ ____ _ ______ _    _ __\n/        \/ ¡        \\_____//// _ /Y\ _ \\\\____//  __///        _\n     _     _|  _  _ _ __________/// | \\\______ _ __/\__ _ __ ___ ___ ____\n            !                       ¦             \[Oo]//// //  //__//___/\\n    «-dNSs--÷-D-o-c-t-o-r-Z---A-r-E-÷-A-f-r-a-¡-D-/_--_\\\\_\\__\\__\\___\/\n  /\________!                       ¦               \/\n_/                   .   ->»«<----« : »---->»«<-                  .\n       _____________/!    _______________________________________/!____ _ _\n       \_      _/\_  ¡___ \_  ____/\_ __  _/\_  _  _/\_  _  _/\_  ¡  _// /\n       /¬  ¡____\/¬ __  ¬\/¬ ____/\/¬ \_  ¬\/¬ __  ¬\/¬ _____\/¬ _____\\n _ _ _/    |   _/   ¬|    \_ ¬l    \_  |    \_ ¬|    \_ ¬|  _/   ¬|\n \ \ \_____!   \_____!     /________/__!     /__!     /__!  \_____!\n                     ¡    /            ¡    /   ¡    /\n_       «--«-«-««««««!   /««««««««««»»»!   /»»»»!   /»»»»»»-»-»--»\n \  ________         i__/         __   i__/     i__/_ _ _ _        _____\n  \/        ¡          ____   __ /  \ __      __ _ _ \\\\\\___ ___/(  _\n    «<-<-<->÷<->->->» / _ __ /  __/\__  \__  _  \\\\\__ \ _  _\ _ __)/ \\n            !__________///      \{××}/     \ \\__________\\\__\\\\  ___/\n  _   _  _ _ _________ _ \__    /_--_\   __/ _ ___   ___ _ _   __\\(__\n                      \\\__ _\__  \/  __/_ _///   \ /   Y          \  \__\n                          ///    \__/    \\\    «<-<-<->÷<->->->»   \___/\n                                                        ¡\n\n                   --==**) PRoViDeS You WiTH (**==--\n\n\n     SYSOP-IN V2.0 By FRaNKy / THeRaPy   © 1994 a PHRaS /X Production\n\nA little door that shows the user if the Sysop is available for chatting...\nIt can save time for long-distance callers and guys in a hurry because you\ndon''t have to find out that the Sysop-Page is turned off by paging the\nsysop... And it can also be added to the logon-sequence wich is always\nin handy....\n\n                         ---- INSTALATION ----\n\nTo use it just put it in BBS:Doors/SysopIn/\nor any other dir you wish to put it...\n\nand add to your BBS.CMD\n\n*SI       RM010Doors:SysopIn/SysopIn.rexx\n          ^^^  ^_______________________________Put the correct path and\n          |||                                  filename over here\n          |||\n          |||__________________________________The acces level needed to\n          ||                                   use the door (I prefer 10)\n          ||\n          ||___________________________________M For Multi-Node usage\n          |\n          |____________________________________R for ARexx\n\nOr copy the icon included into your BBS.CMD directory...\n\nAnd if you want to add it to the logon sequence\nadd to your NodeX/bull.txt:  (X is the Nodenumber)\n--- cut ---\n~CC_SI\n--- cut ---\n\n                           ---- CONFIGURATION ----\n\nIn the .Rexx file you''ll see these lines....\n\nClear  = 1    /* If you want the screen cleared, put a 1 here, else a 0 */\nGender = 1    /* If the sysop is male put a 1 here, if female a 0, if   */\n              /* you''re an alien a 2 please...                          */\nOkay   = 200  /* Put the override chat level here                       */\n\nClear : Clears the screen if you want...\nGender: 1 = Him , 2 = Her , 3 = ET  :­]\nOkay  : The level that has override-chat posibilities\n        (I''ve searched the /X docs for a command that let''s you retrieve\n         it but found nothing, hope this can be fixed soon....)\n\n                             ---- BLA BLA ----\n\nYou can contact the author at : FidoNet  2:292/603.8\n                                AmyNet  39:120/102.8\n                                NLA     14:200/101.8\n\n         Or call Metal Impact : +32 50 393239  (16.8 DHST)\n                                +32 50 393969  (16.8  HST)\n\nFinally some greets to : Maddy - Mr Hyde - BSM - Dnss - Risc - Arkel -\n                         Alkaid - Lithium - Toxic - Kickface - Whiz -\n                         Tormentor - Heka - Sledge - Black Beard -\n                         ZoleX - The Messiah - The Undertaker\n                         And all i forgot in this hurry...\n\n\n','\n',char(10)),NULL,NULL,8502,5,0,NULL,NULL,NULL,'scan',1780048806);
INSERT INTO door_catalog VALUES('try_wt11','TRY_WT11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRY_WT11.LHA','Rawplay','XIM','Rawplay',NULL,NULL,'TRY',NULL,replace('WHo''S THeRe V 1.1 For /X 2.xx & 3.xx\n','\n',char(10)),'WT.Doc',replace('                     .                                            .\n       _____________/!    _______________________________________/!____ _ _\n       \_      _/\_  ¡___ \_  ____/\_ __  _/\_  _  _/\_  _  _/\_  ¡  _// /\n       /¬  ¡____\/¬ __  ¬\/¬ ____/\/¬ \_  ¬\/¬ __  ¬\/¬ _____\/¬ _____\\n _ _ _/    |   _/   ¬|    \_ ¬l    \_  |    \_ ¬|    \_ ¬|  _/   ¬|\n \ \ \_____!   \_____!     /________/__!     /__!     /__!  \_____!\n                     ¡    /            ¡    /   ¡    /\n        «--«-«-««««««!   /««««««««««»»»!   /»»»»!   /»»»»»»-»-»--»\n                     i__/              i__/     i__/\n\n\n                       Brings You : WHOSTHERE V 1.1\n                   -==================================-\n\n   A Small Door For /X 2.xx and 3.xx (Should work Ok on S-Express Too),\n   that plays a selected sample when a user logs in to the bbs...\n   the sample is the users access level so a user with level 100\n   will get Doors:There/Samples/100 as sample to notify the sysop a user\n   with that level has logged in...\n\n\n                            How To Install It ?\n                   -==================================-\n\nFor Ami-Express 3.xx : -Drag the icon WT.Info to your\n                        BBS:Commands/BBS_CMD Directory\n                        and put the dir "WT/" in Doors:\n\nFor Ami-Express 2.xx : -Add this to you BBS.CMD File :\n                        *WT       RM001DOORS:WT/WT.rexx\n\nFor Both Versions... : -Add this to your NodeX/bull.txt:\n                        (X is the nodenumber)\n                        ~CC_WT\n                       -Copy RAWPLAY into your C: Directory\n\n   Then Add/Remove samples as much as you have access-levels.. Every level\n   MUST have it''s sample.. else an error message will be displayed on screen\n   Samples are located in Doors:WT/Samples\n\n   The player used is RawPlay V 1.0 By DICE/TRACKERS (Hope U Don''t Mind)\n\n\n                               Configuration\n                   -==================================-\n\nIn the beginning of the script you will find these lines...\n\nBoss = 1         /* If you want a sample played when the sysop logs on,   */\n                 /* put a 1 here... Else a 0                              */\nClear = 1        /* If you want the screan cleared then put a 1 here...   */\n                 /* Else a 0                                              */\n\nBoss toggles the option that when the sysop does a logon no sample\nwill be played.. when Boss = 1 a sample will be played... any other number\n(but I prefer 0) will disable this feature...\n\nClear toggles the option that the screan will be cleared when the door\nis executed.. Clear = 1 will clear the screen.. any other number won''t..\n\n\n                                To-Do List\n                   -==================================-\n\n-When the option that no sample will be played when the sysop logs on there\n will be a check if the user that logs in is the sysop (done by checking the\n users handle) else a sample will be played after all...\n-Add a list of users that, when they log in, no sample will be played...\n\n\n                           Greets And Hy''s To :\n                   -==================================-\n\n  Maddy - Mr Hyde - Bsm - Dnss - Alkaid - Arkel - Kickface - Lithium - Unix\n             Sledge - Hellborg - And All I Forgot In This Rush...\n\n\n                             Program History\n                   -==================================-\n\n                     V 0.9  -Beta Version                 - No Release\n                     V 1.0  -Checker for C:Rawplay added  - First Release\n                             Added some problem routines\n                     V 1.1  -Changed a weeny bit to the   - Release\n                             screen layout\n                            -Added an option that let''s\n                             you chose if you want a\n                             sample played with a sysop-\n                             logon\n                            -Added Screen-Clear option\n                            -Updated the docs a bit...\n','\n',char(10)),NULL,'auto-added',187659,4,0,NULL,NULL,'try_wt11','scan',1780048806);
INSERT INTO door_catalog VALUES('try_stc1','TRY_STC1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRY_STC1.LHA',NULL,'XIM','_________ _    ____________________________',NULL,NULL,'TRY','\      /¬¡¬\::/ __)__   ¬/ _¬\   _  ¬\ ¬| ¬\ :\/  \/  _  \/  __/\/   /  _  \  ____/  ___/ :/    \  !   \  l   \   \  !   \ |::/   |:::',replace('_________ _    ____________________________\n\      /¬¡¬\::/ __)__   ¬/ _¬\   _  ¬\ ¬| ¬\\n:\/  \/  _  \/  __/\/   /  _  \  ____/  ___/\n:/    \  !   \  l   \   \  !   \ |::/   |:::\n:\____/__i___/______/\   \_i___/_|::\___|:::\n<-----> tHERAPy <---->\___/<-> pRESENTs <-->\n<-STaR TReK CooKie V1.0 For /X 2.xx & 3.xx->','\n',char(10)),'Cookie.Doc',replace(replace('                  ._                                                  ._\r\n _________________| \_______________________________/\________________| \  \r\n \___    ____/    |  \__     ____________    \______  \________  \    |  \ \r\n    /    \  /     |   \/     ._|__/     |     \    |   \/     |   \____   \\r\n  _/      \/      _    \     |    \     _    _/    _    \     ____/   |    \\r\n  \________\______|     \_________/_____|    \_____|     \____|____________/\r\n               scel______/              l_____/    l______/            \r\n                                                                        \r\n                   Presents : Star Trek Cookie Door V 1.0\r\n\n\n      A small door for Ami-Express 2.xx and 3.xx that shows a tagline\n   with a funny saying about Star Trek and Star Trek The Next Generation\n         If you like it, please include it into you logon sequence\n\n   To install it just put all the files in the archive in Doors:STCookie\n       The dirs are already made in the archive but just in case =-)\n\n                            Ami-Express V 2.xx\n                         ------------------------\n\n     Add to your BBS.CMD : "*COOKIE   RM010DOORS:STCookie/Cookie.Rexx"\n                          (Ofcourse without the "")\n\n                            Ami-Express V 3.xx\n                         ------------------------\n              Drag the icon (Cookie.Info) to your BBS.CMD dir\n\n                             Program History\n                         ------------------------\n             V 0.9  Beta Version - No Release (Thank God !)\n             V 1.0  First Release\n\n                       Greets (From FRaNKy) go to :\n                    ----------------------------------\n           MaDDy - Mr Hyde - DnSs - HellBorg - BsM - Alkaid\n             ArkEl - SpadS - SigmatroN - And All I Forgot\n\n\n                   To contact the authors you can call:\n                ------------------------------------------\n\n               WHQ    Dead Zone             +1-714-956-4524\n                                            +1-714-956-45o7\n                                            +1-714-956-1413\n                                            +1-714-PRI-VATE\n\n               EHQ    Metal Impact          +32-50-39.32.39\n                                            +32-50-PRI-VATE\n\n               BHQ    Black Krypt 2         +32-81-22.87.29\n\n               BHQ    Maniac mansion        +32-3-707-07.53\n                                            +32-3-PRI-VATE\n\n               UKHQ   Northern X-posure     +44-  OFF LINE\n\n               USHQ   Psycho Terminal       +1-914-682-1975\n\n               SFHQ   Death Star            +358-0-351-5969\n\n               USHQ   The Styleetron        +1-916-366-0592\n\n','\r',char(13)),'\n',char(10)),NULL,NULL,8563,6,0,NULL,NULL,NULL,'scan',1780048806);
INSERT INTO door_catalog VALUES('try_wt10','TRY_WT10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TRY_WT10.LHA','Rawplay','XIM','Rawplay',NULL,NULL,'TRY','\      /¬¡¬\::/ __)__   ¬/ _¬\   _  ¬\ ¬| ¬\ :\/  \/  _  \/  __/\/   /  _  \  ____/  ___/ :/    \  !   \  l   \   \  !   \ |::/   |:::',replace('_________ _    ____________________________\n\      /¬¡¬\::/ __)__   ¬/ _¬\   _  ¬\ ¬| ¬\\n:\/  \/  _  \/  __/\/   /  _  \  ____/  ___/\n:/    \  !   \  l   \   \  !   \ |::/   |:::\n:\____/__i___/______/\   \_i___/_|::\___|:::\n<-----> tHERAPy <---->\___/<-> pRESENTs <-->\n<-  WHo''S THeRe V 1.0 For /X 2.xx & 3.xx  ->','\n',char(10)),'WT.Doc',replace('                     .                                            .\n       _____________/!    _______________________________________/!____ _ _\n       \_      _/\_  ¡___ \_  ____/\_ __  _/\_  _  _/\_  _  _/\_  ¡  _// /\n       /¬  ¡____\/¬ __  ¬\/¬ ____/\/¬ \_  ¬\/¬ __  ¬\/¬ _____\/¬ _____\\n _ _ _/    |   _/   ¬|    \_ ¬l    \_  |    \_ ¬|    \_ ¬|  _/   ¬|\n \ \ \_____!   \_____!     /________/__!     /__!     /__!  \_____!\n                     ¡    /            ¡    /   ¡    /\n        «--«-«-««««««!   /««««««««««»»»!   /»»»»!   /»»»»»»-»-»--»\n                     i__/              i__/     i__/\n\n\n                       Brings You : WHOSTHERE V 1.0\n                   -==================================-\n\n   A Small Door For /X 2.xx and 3.xx (Should work Ok on S-Express Too),\n   that plays a selected sample when a user loggs in to the bbs...\n   the sample is the users access level so a user with level 100\n   will get Doors:There/Samples/100 as sample to notify the sysop a user\n   with that level has logged in...\n\n\n                            How To Install It ?\n                   -==================================-\n\nFor Ami-Express 3.xx : -Drag the icon There.Info to your\n                        BBS:Commands/BBS_CMD Directory\n                        and put the dir "WT/" in Doors:\n\nFor Ami-Express 2.xx : -Add this to you BBS.CMD File :\n                        *WT       RM001DOORS:WT/WT.rexx\n\nFor Both Versions... : -Add this to your NodeX/bull.txt:\n                        (X is the nodenumber)\n                        ~f\n                        ~CC_WT\n                       -Copy RAWPLAY into your C: Directory\n\n\n   Then Add/Remove samples as much as you have access-levels.. Every level\n   MUST have it''s sample.. else an error message will be displayed on screen\n   Samples are located in Doors:WT/Samples\n\n   The player used is RawPlay V 1.0 By DICE/TRACKERS (Hope U Don''t Mind)\n\n\n                           Greets And Hy''s To :\n                   -==================================-\n\n  Maddy - Mr Hyde - Bsm - Dnss - Alkaid - Arkel - Kickface - Lithium - Unix\n             Sledge - Hellborg - And All I Forgot In This Rush...\n\n\n                             Program History\n                   -==================================-\n\n                     V 0.9  Beta Version                 - No Release\n                     V 1.0  Checker for C:Rawplay added  - First Release\n                            Added some problem routines','\n',char(10)),NULL,'auto-added',187115,4,0,NULL,NULL,'try_wt10','scan',1780048806);
INSERT INTO door_catalog VALUES('ts_ns001','TS-NS001.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TS-NS001.LHA','TaSK-NewScan','XIM','________/\_______________',NULL,'sTc','TS','\ _    /  \   __  /     / \/   / |  \__  \/  |/ / /   /  _   \ l  \  |\ \',replace('[1m[36m         ________/\_______________\n[1m[36m         \ _    /  \   __  /     /\n[1m[36m          \/   / |  \__  \/  |/ /\n[1m[36m          /   /  _   \ l  \  |\ \\n[1m[36m         /___/___|    \____\_____\\n[1m[36m          T A S K|_____\  I N C .[0m\n[1m[33m                pRESENTS:[1m[0m\n[1m[35m     ..: tASK-nEWsCAN v0.01 bY sTc :..\n[1m[32m   fIRST nEWsCAN wITH sCROLL-uP oPTIONS\n[1m[31m   rELEASED AT fRIDAY, 12th aUGUST 1994\n[1m[34m        fOR /X 3.xx aND hIGHER !![1m[0m\n','\n',char(10)),'Task-NewScan.GUIDE',replace('@database Task-NewScan Instructions by aIRwORX\n\n©1994 by SvEN tHE CREAToR [Coder] - aIRwORX [Doc-Writer]\nAll Rights Reserved\n\n@Remark $VER: V0.01 Released at the Friday, the 12th of August 1994\n@Remark AmigaGuide database for the Task-NewScan Instructions\n@node MAIN "Task-NewScan ©1994 by SvEN tHE CREAToR [Coder] - aIRwORX [Doc-Writer]"\n                               /\                 \n            __________________/  \_____________________  _____\n            \                /    \                /   \/    /\n             \   ___        /      \      ____    /         /\n              \    /       /   |    \         \  /         /\n               \  /       /    |     \____.    \/    /    /\n                \/       /     |      \   ¦     \    \    \ \n                /       /              \  `-     \         \\n               /       /       _        \         \         \ \n              /_______/________|         \_________\____/\___\\n                               |          \       \n                               |___________\             nEWsCAN V0.01\n                 Code: SvEN tHE CREAToR   Doc: aIRwORX   \n--==========================================================================--\n           .: Contents of documentation for the TASK-NEWSCAN  :.\n    @{"  SYSTEM-REQUIREMENTS " Link Requirements} @{"     INSTALLATION     " Link Installation} @{"      TOOLTYPES       " Link Tooltypes}\n    @{" WHAT IS TASK-NEWSCAN " Link WhatisT-NS} @{"       GREETINGS      " Link Greetings} @{"  HOW TO CONTACT US   " Link Howtocontact}\n                            @{"  HOW TO REGISTER ME  " Link Register} \n  ¦---------------------------------------------------------------------¦\n  | NOTICE: I`ll will speak the TASK-NEWSCAN as T-NS,`cause i`ve no fun |\n  |                  to write everytime TASK-NEWSCAN.                   |\n  ¦---------------------------------------------------------------------¦\n@endnode\n@node Requirements " System-requirements of Task-NewScan"\n                               \n                           What do you need is:\n\n                              an Amiga Model \n       [ 500 600 1000 1200 2000 2500 3000 4030 4040 5000 CDTV CD³² ]\n               Kickstart 2.xx / 3.xx   Workbench 2.xx / 3.xx\n                        AmiExpress V3.xx / V4.xx\n                             User and uploads\n\n                            @{" Go back to main " Link MAIN}\n\n@endnode                                                                                 \n@node Installation " Installation of Task-NewScan"\n\nExtract the archive [TK-NS001.LHA] and copy them to the right places...\n\nThe Arcive include:  BBS:DOORS/Task-NewScan/Task-NewScan\n                     BBS:COMMANDS/BBSCMD/N.INFO\n                     BBS:COMMANDS/BBSCMD/F.INFO\n                     BBS:COMMANDS/SYSCMD/N.INFO\n\n\n                     @{" Go on to the tooltypes " Link tooltypes}\n@endnode\n@node Tooltypes " Tooltypes of the Task-NewScan"\n\n             Only the N.INFO and the F.INFO needs TOOLTYPES...\n                       Both icons need the same ....\n\n                 LOCATION=Doors:Task-NewScan/Task-NewScan\n                 MULTINODE=YES                           \n                 ACCESS=1                             \n                 TYPE=XIM\n                 NAME=Task-NewScan\n\n               - Be sure, that your DOOR-DIR is assigned ! -\n\n\n                    @{" How to make this door resident ?? " Link resident}\n                            @{" Go back to main " Link MAIN}\n@endnode\n@node resident " How to make task-NewScan RESIDENT ?? "\n\n               You can also make this Task-Scan resident...\n          If you want to make this door resident, then insert the\n              following tooltypes in all icons of this scan:\n   [ BBS:COMMANDS/BBSCMD/N.INFO ,  F.INFO ; BBS:COMMANDS/SYSCMD/N.INFO ]\n\n                 LOCATION=Task-NewScan\n                 RESIDENT\n                 MULTINODE=YES\n                 ACCESS=1\n                 TYPE=XIM\n                 NAME=Task-NewScan\n\n  Protect the TASK-NEWSCAN in our doors with --P-RWED to make it residentable\n         Then go to our user-startup and add the following string:\n\n                 Resident Doors:TASK-NEWSCAN/TASK-NEWSCAN\n\n   Reboot your mashine or just enter the shell and just type in the same\n                          to make it resident !!\n\n                            @{" Go back to main " Link MAIN}\n@endnode\n@node WhatisT-NS " What Is Task-NewScan ??? "\n\n                      Task-NewScan is a product from \n                         @{" SvEN tHE CREAToR " Link ich}\n   it`s a replacement for any NEWFILES...it`s not only a replacement...\n                         this is a NEWFILES...hehe\n\n                  @{" What can I and the users do ??? " Link Usercando}\n@endnode\n@node Usercando " What can the sysop and the users do ??? "\n\n  The extraordinary of this tool is the BACKSCROLLING of the FILELIST...\n  ALL newfiles are able to scroll from the begining to the end...but the \n    Task-NewScan is able to scroll up and down...to jump up and down...\n\n                       @{" How can i test it ??? " Link Howcanitestit}\n@endnode\n@node Howcanitestit " How can i test Task-NewScan ??? "\n\n                           How can i test it ???\n\nhehehe...sipmly question...heavy answer....first...be sure , that you have\n   the right lines of your screen...if you are not sure...check them...\n( Press `W` and then the `5`...and just type the Number , you see at the top)\n\nNow you must log in into our BBS...and start the Task-NewScan ( Start it with\n `N`...if you DON`T KNOW IT )...you see...it`s working..now Task-NewScan \n (I`ll will short it with T-NS) ask for the date...now you can type in the\n                        date for begin scanning....\n\nEx.:                    08-07-94 [ MONTH-DAY-YEAR ]\n\n  OR..you can type in the day to scan back...like -2 for two days back !\n\n  Now T-NS asks for the dir....type in one of our dir...or simply `U` for\n   Upload-Dir....User with a security-Level higher than 200 are allowed\n                     to scan the Hold-Dir with `H` !!\n\nFor the expert User, you can start the T-NS with N -2 or how do you like...\n      You can write the options of the T-NS WITHOUT any direction...\n                  Do you understand ??? No ???? Look....\n______________________________________________________________________________\nfACElESS wORLD #1 [5:/X-tOOLS] Menu (14367 mins. left): N  A   NS      -2\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n     You see...T-NS isn`t specified of the order of the options....you\n       can also put SPACES between the options...the T-NS will scan\n      the uploads to days back in all dirs with nonstop....try it...\n\nNow T-NS starts Scanning...and HOW FAST..gelle ?? now...the first Files will\n     be displayed...now..look at the end of this screen..you see this:\n\nEnter command: C,F,N,S,Q,UP,DN,LF,RG,BS,1-3,7-9,?,CR :      [000%] Flags: None\n\n                     This are the commands of the T-NS\n\n                    @{" T-NS - COMMANDS WHILE FILESCANNING " Link Command-?}\n                    @{" T-NS - OPTIONS WITH THE COMMAND N  " Link Command-N}\n                    @{" T-NS - OPTIONS WITH THE COMMAND F  " Link Command-F}\n\n    IF you or the users need help of the T-NS, then try these Commands:\n\nfACElESS wORLD #1 [5:/X-tOOLS] Menu (14367 mins. left): N HELP\n                   @{" Type this, and you will get THIS help " Link N-HELP}\n\nfACElESS wORLD #1 [5:/X-tOOLS] Menu (14367 mins. left): N ?\n                   @{" Type this, and you will get THAT help " Link N-?}\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n                            Hmmm nice...but...\n                      @{" How can the user flag files ??? " Link Howtoflag}\n@endnode\n@node Howtoflag " How can the user flag files ???  "\n\n               You have asked me...here you get an answer...\n\nThey must press the @{" F " Link ich}[Flag-modus] in the NewScan and then the user see\nwhite-in-blue colored filenames....now they can choose the files with \nthe cursor-keys [up/down]...they can flag the files, if there press SPACE\nat the marked filename. Now the bytes of the files will change into FLAGGED.\nNow the file(s) are flagged.\n\n              With the key `V` you can view into the file....\n\n           @{" Hmmm that`s all ?? hmmm easy..bring me to the main menu " Link Main}\n@{" STOP! One question! I didn`t understand...bring me back to the previous page! " Link Howcanitestit}\n@endnode\n@node Greetings " And here some greetings from us... "\n\n                    And here some greetings from us... \n\n            @{" SvEN tHE CREAToR greets: "Link sTcgreets}       @{" aIRwORX greets: " Link awgreets}\n\n                         @{" Bring me back babe !! " Link Main}\n@endnode\n@node howtocontact " How can you contact us ???? "\n    If you founds some bugs...or if you have new ideas for the T-NS or\n                 an other /X-Tool, then contact me here :\n------------------------------------------------------------------------------\n                            @{" fACElESS wORLD " Link FacelessWorld}\n                          @{" oR cONTACT mE hERE " Link sTccONTACT}\n------------------------------------------------------------------------------\n                     @{" Uaaahhh i won`t contact you !! " Link Main}\n------------------------------------------------------------------------------\n@endnode\n@node Command-N " T-NSCAN OPTIONS WITH THE COMMAND N "\n\n      N................Start T-NS                            \n      N -(x)...........Scans x-days back in the upload-dir          \n      N -(x) A.........Like n -(x)  in all dirs                     \n      N mm-dd-yy U.....Scans from the date-x in the upload-dir      \n      N mm-dd-yy A.....Scans from the date-x in all dir             \n      N S U............Scans uploads since last logon in upload-dir \n      N S A............Scans uploads since last logon in all dirs   \n      N S U NS.........Like N S U with nonstop output [Break with Q]\n      N S A NS.........Like N S A with nonstop output [Break with Q]\n      N T U............Scans today uploads in upload-dir            \n      N T A............Scans today uploads in all dirs              \n      N T U NS.........Like N T U with nonstop output [Break with Q]\n      N T A NS.........Like N T A with nonstop output [Break with Q]\n\n      @{"  That looks good...bring me back...  " Link Howcanitestit}\n@endnode      \n@node Command-F " T-NSCAN OPTIONS WITH THE COMMAND F "\n\n      F................Scans in filelist                            \n      F A..............Scans all filelists                          \n      F A NS...........Like F A with nonstop output [Break with Q]  \n      F U..............Scans in upload-filelist                     \n      F U NS...........Like F U with nonstop output [Break with Q]  \n      F (x)............Scans in filelist x                          \n      F (x) NS.........Like F (x) with nonstop output [Break with Q]\n\n @{"  Hmmm..ok...i`ve understand...now back, please  " Link Howcanitestit}\n@endnode\n@node Command-? " COMMANDS WHILE FILESCANNING AND DESCRIPTION "\n\n C: Clears the screen and scroll forwards\n F: Switch flag-modus on\n N: Output nonstop\n S: Skip current dir\n Q: Quit T-NS\nUP: CURSOR-KEY UP    - Scroll one line up\nDN: CURSOR-KEY DOWN  - Scroll one line down\nLF: CURSOR-KEY LEFT  - clears the screen and goes up...short,\n                       the screen will jump up\nRG: CURSOR-KEY RIGHT - clears the screen and goes down ...short, \n                       the screen will jump down\nBS: BACKSPACE       - the screen will scroll backward....\n 1: Will go to the end of the shown dir\n 2: Scroll one line forward\n 3: clears the screen and goes down\n 7: Will go to the top of the shown dir\n 8: Scroll one line back\n 9: clears the screen and goes up\n ?: short description of the commands\nCR: RETURN/ENTER    - the screen will scroll down....\n\n(004%)       - This tells you, how many percent of the dir was shown !!!\n\nFlags: None  - This tells you, how many files are Flagged !!!\n\n          @{"  yEAH...Bring me back sir...  " Link Howcanitestit}\n@endnode\n@node N-? "fACElESS wORLD #1 [5:/X-tOOLS] Menu (14367 mins. left): N ? "\n--==========================================================================--\n                       sCAN-oPTIONS wITH cOMMAND N:                           \n                                                                              \n      N................sTART nEWsCAN                                          \n      N -(x)...........sCANS x-dAYS bACK iN tHE uPLOAD-dIR                    \n      N -(x) A.........lIKE N -(x)  iN aLL dIRS                               \n      N mm-dd-yy U.....sCANS fROM tHE dATE-x iN tHE uPLOAD-dIR                \n      N mm-dd-yy A.....sCANS fROM tHE dATE-x iN aLL dIRS                      \n      N S U............sCANS uPLOADS sINCE lAST lOGON iN uPLOAD-dIR           \n      N S A............sCANS uPLOADS sINCE lAST lOGON iN aLL dIRS             \n      N S U NS.........lIKE N S U wITH nONSTOP oUTPUT [bREAK wITH Q]          \n      N S A NS.........lIKE N S A wITH nONSTOP oUTPUT [bREAK wITH Q]          \n      N T U............sCANS tODAY uPLOADS iN uPLOAD-dIR                      \n      N T A............sCANS tODAY uPLOADS iN aLL dIRS                        \n      N T U NS.........lIKE N T U wITH nONSTOP oUTPUT [bREAK wITH Q]          \n      N T A NS.........lIKE N T A wITH nONSTOP oUTPUT [bREAK wITH Q]          \n                                                                              \n--==========================================================================--\n                       sCAN-oPTIONS wITH cOMMAND F:                           \n                                                                              \n      F................sCANS iN fILElIST                                      \n      F A..............sCANS aLL fILElISTS                                    \n      F A NS...........lIKE F A wITH nONSTOP oUTPUT [bREAK wITH Q]            \n      F U..............sCANS iN uPLOAD-fILElIST                               \n      F U NS...........lIKE F U wITH nONSTOP oUTPUT [bREAK wITH Q]            \n      F (x)............sCANS iN fILElIST x                                    \n      F (x) NS.........lIKE F (x) wITH nONSTOP oUTPUT [bREAK wITH Q]          \n                                                                              \n         [- N HELP aND F HELP wILL vIEW a mORE dETAILED hELP pAGE -]          \n                                                                              \n--==========================================================================--\n\n                             @{" Back sir " Link Howcanitestit}\n@endnode\n@node N-HELP "fACElESS wORLD #1 [5:/X-tOOLS] Menu (14367 mins. left): N HELP "\n--==========================================================================--\nhOW tO uSE tHIS nEWsCAN:                                                      \n                                                                              \nU cAn tYPE N iN tHE cOMMAND-LINE, tHEN tASK-nEWsCAN aSKS fOR tHE sCAN-dATE !  \nU cAN tYPE tHE dATE [eX. 07-07-94], tHE dAYS tO gO bACK [eX. -2 fOR sCAN      \nuP tO 2 dAYS bACK] oR jUST pRESS rETURN fOR lASTcALL-sCAN !                   \nnOW tASK-nEWsCAN aSKS fOR tHE sCAN-dIR...tYPE hERE 1 fOR dIR 1, 2 fOR dIR 2   \naND sO oN oR sIMPLY U fOR tHE lAST/uPLOAD dIR ! uSERS wITH aN hIGHER lEVEL    \ntHAN 200 aRE aLLOWED tO uSE tHE hOLD-dIR wITH H !                             \n                                                                              \n--==========================================================================--\nhOW tO sTART tASK-nEWsCAN fROM tHE cOMMAND-lINE:                              \n                                                                              \njUST wRITE N [oUR dIR, sCANdATE..oR wHAT dO yOU lIKE]                         \nyOU cAN aLL cOMMANDS wRITE hOW dO yA lIKE:                                    \n                                                                              \n--==========================================================================--\neXAMPLE:                                                                      \n                                                                              \nfACElESS wORLD #2 [5:/X-tOOLS] Menu (14399 mins. left): N U -5                \n                                                                              \n--==========================================================================--\n                                                                              \ntASK-nEWsCAN sCANS 5 dAYS bACK iN tHE uPLOAD-dIR...                           \ntHE sPECIAL eFFECT iS...yOU mUST wRITE iN tHE mOST nEWfILES/sCANS tHE oPTIONS \niN oRDER...lIKE N -3 U ! iN tASK-nEWsCAN, U cAn wRITE , hOW dO yA lIKE...     \nU cAN aLSO pUT mORE tHAN oNE sPACE bETWEEN tHE oPTIONS...lIKE                 \n                                                                              \nfACElESS wORLD #2 [5:/X-tOOLS] Menu (14399 mins. left): N  u  07-07-94   ns   \n                                                                              \ntHIS iS eASY iSN`T iT ???\n--==========================================================================--\n                             @{" That`s it " Link Howcanitestit}\n@endnode\n@node Register " Why must i and how can i register ??? "\n\n                   Why must i and how can i register ???\n\n      Yep...if you like the Task-NewScan, than you MUST register it,\n because the @{" flag " Link ich} option will works Works till 1st Oct. 94 !\n      If you register, you can use ALL options so long as you want !\n         And only YOU can use our registered version...hehehehe...\n   You don`t think it ??? hehe OK register this tool, you get them, and\n                          then try it....hehehehe\n\n                   @{" OK..i will...where can i get it ?? " Link FacelessWorld}\n                             @{" Nope Thanxx !!! " Link Main}\n@endnode\n@node FacelessWorld " cALL oR yOU gET bUSTED !!! hEHEHEHE "\n                                                             /\      /\n  fUCKIN`oN    /¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\ ____/__\____/___\n /X 3.38 rEG. /   [·F·A·C·E·L·E·S·S·]  [·W·O·R·L·D·]   \¯¯¯/¯¯¯¯\¯¯/¯¯¯¯\n_____________________________________________________   \ /      \/__\n\_ __________/___.      __/_ ._________/_ __________/_________.   _\/_\n / _________| / ¬|      ¬\ / |       ¬\ / ---------\          |  \\/\//\n/         ¬| /  |         \  |         \            \cJ!      |aTOMIC zONE\n\_         | \___|        /___         /__          /______________________\n  \________|     |_______/  ¬|________/__|_________/_________/_ __________/\n                       /        ¬\_ /  --------\ /---------¬\ /---------