INSERT INTO door_catalog VALUES('tsk_al01','TSK-AL01.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TSK-AL01.LHA','TaSK-AllScan','XIM','______',NULL,'sTc/tSK','TSK','___________________ __________ ______/     / \______   ______   \\   _____/___  _/   __/ |     /       _/\_______   /  \     \',replace('                                      ______\n___________________ __________ ______/     /\n\______   ______   \\   _____/___  _/   __/\n     |     /       _/\_______   /  \     \\n     | Mo!/________\ _ ________/____\     \_\n     `-----''        \\ /  PRESENTS:  \_____/\n  .-- ---- ------ ---\/- ------ ---- ----.\n  |          TaSK-AllScan v0.01          |\n  )--------------------------------------(\n  | Coded by sTc/tSK  Design by nICo/tSK |\n  `------ --[ HAPPY NEW YEAR!! ]-- ------''\n','\n',char(10)),'TaSK-AllScan.Guide',replace('@DATABASE TaSK-AllScan Documentation\n@AUTHOR SvEN tHE CREAToR/TaSK\n@INDEX Documentation\n\nCopyright © 1995 SvEN tHE CREAToR/TaSK\n\n@REMARK $VER: TaSK-AllScan v0.01 by sTc/TaSK\n@REMARK AmigaGuide database\n\n@NODE Main "TaSK-AllScan - Main"\n\n                                                  _______\n    ________________________ ____________ _______/      /\n    \_______   _______      \\    ______/___   _/    __/\n          |     |/    Mo!   _/\________    /   \      \\n          |     /___________\ _ __________/_____\      \_\n          `-----''            \\ /                \______/\n                              \/\n\n         .dOo TaSK-AllScan v0.01 © 1995 by sTc/TaSK oOb.\n\n                       @{"  Prg Description  " Link PrgDesc}\n                       @{"   Installation    " Link Installation}\n                       @{"      History      " Link History}\n                       @{"     Greetings     " Link Greetings}\n\n@ENDNODE\n\n@NODE PrgDesc "TaSK-AllScan - Prg Description"\n\n  Program Description:\n  ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n  TaSK-AllScan is an all-conference-scan (CS). There are many NewFiles-Doors\n  out BUT most of them don''t have the ability to scan multi-conference-mode.\n  And there is the use of TaSK-AllScan. It gives you the ability to configure\n  the conferences you wanna scan through. Then there will be ''N'' started with\n  the specific arguments in each conf.\n\n@ENDNODE\n\n@NODE Installation "TaSK-AllScan - Installation"\n\n  Simply copy all these files to your BBS:\n  ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n  BBS/ Commands/ BBSCmd/ CS.info\n       Doors/    TaSK/   TaSK-AllScan/ TaSK-AllScan\n                                       TaSK-AllScan.Guide\n\n@ENDNODE\n\n@NODE Greetings "TaSK-AllScan - Greetings"\n\n\n              This is (currently) TaSK:\n              ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n     [aIRWORX - dEATH aNGEL - nICO - sNoW - sTc]\n\n\n  Greetings:\n  ¯¯¯¯¯¯¯¯¯\n  Nico .............................. 11111111111!\n  Celator .................... AmigaE v3.1 - Cewl!\n  Death Angel ................... Sylvester r0oLZ!\n  Airworx ............. It begins WITH the 1-1-95!\n  Snow ........................... ^^^^^^^^^^^^^^!\n  Sabine .................................. Snief! :)\n  Stoeberhai .................. Thank you for xxx!\n  Prophet ..................... Unser Sängerknabe! :)\n  Patrick .................................. OpEL!\n  Mad Doc .......... Geht''s mit der Zeitschaltuhr? :)\n  Exterminator ....................... Hey, warum?\n\n  Short greetings:\n  ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\n  Lector, Dado, Circuit Breaker, cDm, Dragonhunt,\n  Black Demon, Flite, Alf, Hitman, Fox, Diogenes,\n  Nors, Ice, Frank, Rainer, Vicar, Frank Maxwell,\n  Fuzzy Navel,  Goonie, Stoker,  Steel, Rebel MC,\n  Mad Force, Toolittle, Thunder, ...\n\n@ENDNODE\n\n@NODE History "TaSK-AllScan - History"\n\n  History:\n  ¯¯¯¯¯¯¯\n  v0.01   - First release under TaSK\n\n@ENDNODE\n','\n',char(10)),NULL,NULL,64318,11,0,NULL,NULL,'tsk_al01_task_allscan','scan',1780048806);
INSERT INTO door_catalog VALUES('tsk_dc01','TSK-DC01.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TSK-DC01.LHA','TaSK-DupeCheck','XIM','______',NULL,'sTc/tSK','TSK','___________________ __________ ______/     / \______   ______   \\   _____/___  _/   __/ |     /       _/\_______   /  \     \',replace('                                      ______\n___________________ __________ ______/     /\n\______   ______   \\   _____/___  _/   __/\n     |     /       _/\_______   /  \     \\n     | Mo!/________\ _ ________/____\     \_\n     `-----''        \\ /  PRESENTS:  \_____/\n  .-- ---- ------ ---\/- ------ ---- ----.\n  |         TaSK-DupeCheck v0.01         |\n  )--------------------------------------(\n  | Coded by sTc/tSK  Design by nICo/tSK |\n  `------ --[ HAPPY NEW YEAR!! ]-- ------''\n','\n',char(10)),'TaSK-DupeCheck.Guide',replace('@DATABASE TaSK-DupeCheck Documentation\012@AUTHOR SvEN tHE CREAToR/TaSK\012@INDEX Documentation\012\012Copyright © 1995 SvEN tHE CREAToR/TaSK\012\012@REMARK $VER: TaSK-DupeCheck v0.01 by sTc/TaSK\012@REMARK AmigaGuide database\012\012@NODE Main "TaSK-DupeCheck - Main"\012\012                                                  _______\012    ________________________ ____________ _______/      /\012    \_______   _______      \\    ______/___   _/    __/\012          |     |/    Mo!   _/\________    /   \      \\012          |     /___________\ _ __________/_____\      \_\012          `-----''            \\ /                \______/\012                              \/\012\012         .dOo TaSK-DupeCheck v0.01 © 1995 by sTc/TaSK oOb.\012\012                       @{"  Prg Description  " Link PrgDesc}\012                       @{"   Installation    " Link Installation}\012                       @{"     Tooltypes     " Link Tooltypes}\012                       @{"   String files    " Link Stringfiles}\012                       @{"      History      " Link History}\012                       @{"     Greetings     " Link Greetings}\012\012@ENDNODE\012\012@NODE PrgDesc "TaSK-DupeCheck - Prg Description"\012\012  Program Description:\012  ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\012  TaSK-DupeCheck is a double upload checker. That means\012  that it checks if the file which has been uploaded\012  does already exist or not and will move the file to\012  the hold if it does already exist.\012\012@ENDNODE\012\012@NODE Installation "TaSK-DupeCheck - Installation"\012\012  Simply copy all these files to your BBS:\012  ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\012  BBS/ Commands/ SysCmd/ FILECHECK.info\012       Doors/    TaSK/   TaSK-DupeCheck/ TaSK-DupeCheck\012                                         TaSK-DupeCheck.Guide\012                                         TaSK-DupeCheck_Strings\012\012@ENDNODE\012\012@NODE Tooltypes "TaSK-DupeCheck - Tooltypes"\012\012  Tooltypes (''Doors:TaSK/TaSK-DupeCheck/TaSK-DupeCheck.info''):\012  ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\012  PRG.1=Doors:ConfTop/ConfTop020.x    - Programs which will\012  PRG.2=Doors:Streußelschnecke.exe      be started when the\012  PRG.n=...                             file isn''t a double\012                                        upload     (look at\012                                        PRGISCOMMAND)\012  FREEDL.1=TaSK-                      - Begin patterns which\012  FREEDL.2=5D-                          have to match the file\012  FREEDL.n=...                          name for making it\012                                        a free download\012  CHECK_CONFS.2=2 3                   - If you want to check\012  CHECK_CONFS.4=2 3 4                   more than one conf you\012  CHECK_CONFS.n=...                     have to specify the\012                                        confs which should be\012                                        checked instead of\012                                        conf <n>\012  NOUPPERCASE                         - You must use this option\012                                        if NOT all file names in\012                                        your dir files are upper\012                                        case\012  DONOTCHECKULDIRS                    - If you don''t want to\012                                        check the upload paths\012  DONOTCHECKLASTDIR                   - If you don''t want to\012                                        check last dir file\012  PRGISCOMMAND                        - If you wanna start the\012                                        extra programs (PRG...)\012                                        as AmiEx commands instead\012                                        of real disk programs\012                                        (e.g. PRG.1=WHO)\012\012@ENDNODE\012\012@NODE Stringfiles "TaSK-DupeCheck - String files"\012\012  String files:\012  ¯¯¯¯¯¯¯¯¯¯¯¯\012  You have the possibility to specify EVERY output\012  text of TaSK-DupeCheck. The file you have to edit\012  is ''Doors:TaSK/TaSK-DupeCheck/TaSK-DupeCheck_Strings{.<LANGUAGE>}''.\012\012  The line format is the following:\012\012   1) Title text\012   2) Wrong arguments text\012   3) Front text - shown before normal check\012   4) Check file text - shown every time a new dir is checked\012   5) File exists text - shown if file already exists\012   6) File is ok - shown if file doesn''t exist\012   7) No files avail - shown if no files are available\012   8) Check file >LASTDIR< text - shown when the last dir of a conf\012      should be checked but DONOTCHECKLASTDIR is toggled on\012   9) File exists in ul dir text - shown when the file exists in\012      one of the upload dirs\012  10) File is ok >FREE DL< - shown in the way like 6 when the file\012      is a free download\012  11) Private upload text\012  12) Free Download add line (NO SPECIAL CHARS!)\012\012  You can use the following special chars:\012  ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\012  \b                                  - Go to begin of the line\012  \n                                  - Go to next line\012  \\                                  - "\"\012  \e                                  - <ESC>\012  ~S                                  - Check file name\012  ~D                                  - Current dir number\012  ~C                                  - Current conf number\012  ~N                                  - Current conf name\012\012           <=> One example string file is included! <=>\012\012@ENDNODE\012\012@NODE Greetings "TaSK-DupeCheck - Greetings"\012\012\012              This is (currently) TaSK:\012              ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\012     [aIRWORX - dEATH aNGEL - nICO - sNoW - sTc]\012\012\012  Greetings:\012  ¯¯¯¯¯¯¯¯¯\012  Nico .............................. 11111111111!\012  Celator .................... AmigaE v3.1 - Cewl!\012  Death Angel ................... Sylvester r0oLZ!\012  Airworx ............. It begins WITH the 1-1-95!\012  Snow ........................... ^^^^^^^^^^^^^^!\012  Sabine .................................. Snief! :)\012  Stoeberhai .................. Thank you for xxx!\012  Prophet ..................... Unser Sängerknabe! :)\012  Patrick .................................. OpEL!\012  Mad Doc .......... Geht''s mit der Zeitschaltuhr? :)\012  Exterminator ....................... Hey, warum?\012\012  Short greetings:\012  ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\012  Lector, Dado, Circuit Breaker, cDm, Dragonhunt,\012  Black Demon, Flite, Alf, Hitman, Fox, Diogenes,\012  Nors, Ice, Frank, Rainer, Vicar, Frank Maxwell,\012  Fuzzy Navel,  Goonie, Stoker,  Steel, Rebel MC,\012  Mad Force, Toolittle, Thunder, ...\012\012@ENDNODE\012\012@NODE History "TaSK-DupeCheck - History"\012\012  History:\012  ¯¯¯¯¯¯¯\012  v0.01   - First release under TaSK\012\012@ENDNODE\012','\012',char(10)),NULL,NULL,82728,11,0,NULL,NULL,'tsk_dc01_task_dupecheck','scan',1780048806);
INSERT INTO door_catalog VALUES('tsk_rlo3','TSK-RLO3.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TSK-RLO3.LHA','IRLO','XIM','IRLO',NULL,NULL,'TSK','___________________ __________ ______/     / \______   ______   \\   _____/___  _/   __/ |     /       _/\_______   /  \     \',replace('                                      ______\n___________________ __________ ______/     /\n\______   ______   \\   _____/___  _/   __/ \n    |     /       _/\_______   /  \     \  \n    | Mo!/________\ _ ________/____\     \_\n    `-----''        \\ /  PRESENTS:  \_____/\n                    \/\n      /X - DOOR foR /X 4.X and S!X\n          ROUTE LOGOFF V 0.3\n','\n',char(10)),'RLO.DOC',replace('\n    Route Logoff  v0.3  - Idea by Wolverine/task - Coded by Hunk/task\n\n    Da uns nicht bekannt ist ob es irgendein Tool gibt welches Levelabhaengige\n    Logoffbatches starten kann haben wir dieses Tool geschrieben. \n\n    Dieses professionelle System besteht aus zwei Teilen:\n\n    1. IRLO - /X-Door, legt Grundwerte fuer den User fest und\n              setzt Trace-Optionen fuer spaeter Versionen.\n\n    2. RLO - CLI-Tool, wird als Batchverteiler genutzt.\n\n    IRLO wird als normale Door in einem beliebigen Starttext eingebaut und\n    ruft sich dann automatisch auf.\n\n    RLO wird als einziges Tool in die LOGOFF-Batch von /X eingetragen. Die\n    Nodenummer wird mit uebergeben ( z.B. RLO 2 ). Eine Batch mit dem Security\n    Level des Users wird dann ausgefuehrt. Ist keine vorhanden, zaehlt das\n    Tool automatisch in 5er-Schritten herunter.Da wir die ungleichen Levels\n    nicht mitreingenommen haben (da es eh kaum einer nutzt) muesst ihr wenn\n    ihr wollt die batches selber benennen ,die batches werden aber trotzdem \n    abgearbeitet.\n\n    Entpackt das Door und baut es nach der zugehoerigkeit ein:\n \n    ------------------------------------------------------------------------------- \n\n    Doors:RLO/RLO                  CLI-Tool\n    Doors:RLO/IRLO                 /X-Door\n    Doors:RLO/IRLO.info            /X-Door.info                         \n    Doors:RLO/RLO.DOC              DOCFILE\n    Doors:RLO/BAT/                 BATCHDATEIEN IN 5er SCHRITTEN und NODE\n                                   abhaengig\n    BBS:Commands/BBSCMD/IRLO.INFO  INFO\n    BBS:Commands/SYSCMD/IRLO.INFO  INFO\n    \n    -------------------------------------------------------------------------------\n\n    DIE BATCHDATEIEN\n\n    Beispiel:\n\n    050_00.bat \n     |   \  \n     |    NODENUMBER\n     |____ LEVEL DES USERS \n\n    IHR KOENNT NATUERLICH AUCH UNGERADE LEVELS NEHMEN ALLERDINGS ZAEHLT ER\n    DANN NICH RUNTER SONDERN NIMMT DIESEN FESTEN LEVEL \n\n    -------------------------------------------------------------------------------\n\n    Aufruf der Door damit das Door ueberhaupt laueft:\n   \n    z.b.BBS:Screens/NODE0/BULL50.txt\n\n    im Textfile muesste dann stehen:\n   \n    ~\n    ~CC_IRLO\n    ~SP \n  \n    Das Door schreibt dann im RAM:ENV ein File Namens CNX (Node)\n\n    ------------------------------------------------------------------------------\n\n    logoff.batch:\n\n    BBS:Doors/RLO/RLO X (NODE)\n\n    aber nicht vergessen eure alte logoffbatch zu renamen und nach \n    Doors:rlo/bat zu kopieren und fuer jede node extra zu machen (SCRIPT) \n\n    ------------------------------------------------------------------------------\n\n\n    Released for Fun  !!!!!!!!!!!!!\n    \n    \n                                           ______\n     ___________________ __________ ______/     /\n     \______   ______   \\   _____/___  _/   __/ \n         |     /       _/\_______   /  \     \   \n         | Mo!/________\ _ ________/____\     \_ \n         `-----''        \\ /             \_____/ \n                         \/\n\n     Call our Boards :\n\n     Digital Suicide BBS      TASK-WHQ GERMANY +49-30-XXXX 3NDZ\n     Route 66                 TASK-GHQ GERMANY +49-30-XXXX 4NDZ\n     Sporadic Line            TASK-IHQ ITALY   +39-47-XXXX 2NDZ\n     \n     WE ARE SEARCHING FOR BOARDS AND MEMBERS ALL AROUND THE GLOBE \n     \n\n\n','\n',char(10)),NULL,'auto-added',17335,5,0,NULL,NULL,'tsk_rlo3','scan',1780048806);
INSERT INTO door_catalog VALUES('tsl_da12','TSL-DA12.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TSL-DA12.LHA','DateAdd','XIM','DateAdd','1.2','Dux/Tsl','TSL','bugs fixed by Dux/Tsl',replace('   DateAdd v1.2 - \nbugs fixed by Dux/Tsl\n','\n',char(10)),'DateAdd.doc',replace('DateAdd v1.2 - bugs fixed by Dux/Tsl.\n\nCan insert a dateline into a directory. The util should be activated every\nnight at 0.00  - use amicron or cybercron.\nEdit the dateline and dir# you want to be updated in the file\n''DateAdd.cfg'' and place it in ''s:''.\n\nHello''s to all Tsl-members worldwide, especially to : Dusty and bAROCK.\nI really enjoy being in such a kewl crew - see you all in Aars !\n\n                                        Dux of Tsl, 19th of December 1992.\n','\n',char(10)),NULL,'auto-added',9869,4,0,NULL,NULL,'tsl_da12','scan',1780048806);
INSERT INTO door_catalog VALUES('tsn_lc10','TSN-LC10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TSN-LC10.LHA',NULL,'XIM','_______________________________ ____________',NULL,'Lockjammer/TSN','TSN','·____ _ / __  /__  ./  ______/// _______  ./ ::./  //  ___/  / //___  /  ¬\/  /  /  / // |:/__ /_____/__/__/____ /_____\____/__/__/.',replace('_______________________________ ____________\n·____ _ / __  /__  ./  ______/// _______  ./\n::./  //  ___/  / //___  /  ¬\/  /  /  / // \n|:/__ /_____/__/__/____ /_____\____/__/__/. \n+JWL\/---÷pRESENtS÷---\/-----------------÷+ \n     L-Comment v1.0 By Lockjammer/TSN    \n This is a fast comment to sysop door with \n nice design, fast commands and much more!!\n','\n',char(10)),'comment.guide',replace('@Database "LComment v1.0 Documentation"\n@Author "Lockjammer"\n@Node Main "LComment v1.0 Documentation (94-12-20)"\n   __/\________________ __ _ .---------.\n   \ oô /______ __ _         |    .----|--------------------------------.\n   /_\/_\____________ __ _   `----|----''     ·eXCItEMENt fOR aLl·      °|\n .___\/____ ___________________ __|______ ____ ___________________.     |\n |    _   .Y.   ___________   .Y.   _____Y____Y.   ___________   .|     |\n l____|   ||    __/__|    |   ||_____    |    |    |    |    |   ||     |\n .----|   ¦|    |    |    |   ¦|    |   .|    |    |   .|    |   ¦|    :|\n |:.. |   :|_________l____|   :|_________l____l_________l____|   :| ..::| \n `----l____|÷JWL÷---------l____|÷tSN^aSt÷--------------------l____|-----''\n\n                                 PRESENT          \n\n              -=- LComment v1.0 by Lockjammer/Tension! -=- \n\n               @{"    Introduction    " Link "1"}  @{"  Archive Contents  " Link "2"}\n               @{"      Features      " Link "3"}  @{"    Requirements    " Link "4"}\n               @{"    Installation    " Link "5"}  @{"   Configuration    " Link "6"}\n               @{"      History       " Link "7"}  @{"     Contact Me     " Link "8"}\n               @{"      Problems      " Link "0"}  @{"     Greetings      " Link "9"}\n\n@EndNode\n@Node "1" "Introduction to LComment v1.0"\n\nSome info about this release!\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nThis program is FREEWARE and may distributed freely as long as the archive \nis kept intact with all it''s original files. FREEWARE means you don''t have \nto pay a registration fee for the use of this program but you may not \nalter it to your liking. This program may not be sold for commercial \npurposes and may only be distributed freely as stated above. \n\nThis program is copyright ©1994-95 Lockjammer.\n\nIntroduktion to LComment.\n~~~~~~~~~~~~~~~~~~~~~~~~~\nLComment is an AmiExpress door. This door is an replacement for the \noriginal C command. With this door you may give comments to cosysops.. Yee\nit''s an old thing!!! But don''t make that stop you!!! This door is the most \npowerful C replacement out there and it''s faster than that arexx program \nthat you have installed. =) Just look at the door and you will love it!!! \n\n@EndNode\n@Node "2" "Archive Contents of file TSN-LC10.LHA"\n\nThe TSN-LC06.LHA Archive contens the following files.\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n      Filename      |  Size  | Description\n- --  -- -- --  - --+- -  -  +-  - -- - --- -- -- - -  - --  -  - - --  -\nDoors/LComment/     |        |\n Comment.000        |  16512 | LComment version for 68000+.\n Comment.020        |  16508 | LComment version for 68020+.\n Comment.guide      |  13557 | This document file.\n Comment.guide.info |    479 | The info file for the documention.\n Comment.info       |   1394 | Configuration file.\n                    |        |\nCommands/BBSCmd/    |        |\n C.info             ¦   1071 | This is the command icon for /X 3.xx+.\n                    :        ¦\n                    .        :\n                             .\n\n@EndNode\n@Node "3" "Features on this Comment to sysop door."\n\nFeatures.\n~~~~~~~~~\n* You may have up to 20 sysops.. I don''t think that any one have more \nthen 20 sysops. But if some one requires more then 20 leave me a \nmessage and i will fix it..\n\n* You may have one description for every sysop..\n\n* You may have 0 to over 100 sysop says. For more info test the door.\n\n* The comment door will check if the user have the access to write comment\nto sysop.\n\n* Nice design by me!! Logo by JeWeL/TSN^AST!!\n\n* Fast key support.. You may enter ''c 1'' and write a comment to sysop.1...\nand so on!\n\n* You may set the default sysop!!! Just enter the name of your choice as\nsysop.1 and he will be the default sysop.. \n\n* Future support!! =)\n\n@EndNode\n@Node "4" "Requirements on this version"\n\nWhat will i need to make it work???\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nAMIGA:         It works on a A500 and up to A4000! That''s more what you \n              can say about some PC programs =) !!! \n\nAmiExpress:    The door works on /X 3.xx+! But it can work on other \n              versions too!!! \n\nOS:            Yee you need OS2.0+ to make it work...\n\nMemory:        Not much!!!\n\n@EndNode\n@Node "5" "Installaion of LComment"\n\nThe only thing you have to do is...\n\nCreat a directory ''Doors:Lcomment'', and copy the version of your choice \nthere.\n\nComment.000 is for AmiExpress 3.xx+ and 68000+.\nComment.020 is for AmiExpress 3.xx+ and 68020+.\n\nCOPY THE CONFIGURATION FILE TO THIS DIRECTORY. CONFIGURATION FILE IS NAMED\n''Comment.info''.\n\nDon''t forget to copy this doc file to that directory for future needs.\n\nJust install this door as an normal XIM door. \n\n@{"How to install XIM doors!" Link "XIM"}\n\nNow the only thing you have to do is edit the tooltypes in the \nconfiguraion file, ''doors:Lcomment/Comment.info''. \n\n@{"Configuration of LComment" Link "6"} \n\nOk that''s all now your on your way!!!\n\n@EndNode\n@Node "6" "Configuration of LComment"\n\nConfiguration of LComment.\n~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nAll configuration is done in the ''Comment.info'' file. Just change the \ntooltypes.\n\nThe tooltypes are....\n~~~~~~~~~~~~~~~~~~~~~\n\n- ---- - - -  -  - --  - -  -  ---  - - ---  -  --  ---- - -- --- - - -- -\n\nTemplate.....: NAME.<number>=<name string>\nExample......: NAME.1=Lockjammer\n\nThis way you set the names of your sysops!!!\n\nNAME.1 is the default so if you want another sysop to take the default \nmessages just put him as name.1..\n\n- ---- - - -  -  - --  - -  -  ---  - - ---  -  --  ---- - -- --- - - -- -\n\nTemplate.....: DESC.<number>=<description string>\nExample......: DESC.1=I am the coder of this door!\n		\nThis is the description for the sysop...\n\n- ---- - - -  -  - --  - -  -  ---  - - ---  -  --  ---- - -- --- - - -- -\n\nTemplate.....: SAYS<Number of says>.<number>=<says string>\nExample......: SAYS1.1=Yee i this door is great !?\n\nOk this is what will be written just before the users write their comment!\nIf you don''t want any says just skip this and the door will not show \n"name" says: <says string>.\n\n- ---- - - -  -  - --  - -  -  ---  - - ---  -  --  ---- - -- --- - - -- -\n\n@EndNode\n@Node "7" "History"\n\nOk What history. This thing is not old =)\n  \n Lcomment v1.0..... The first release version. (1994-12-20).\n\n Yee i know this is that version. But i said it was no history to talk\nabout!\n\n@EndNode\n@Node "8" "How to contact me"\n\n  If you have any problems or have found any errors with the program or \n anything else i can be reached at the board given below. \n \n The safest place to reach me is @{"NIGHTFALL" Link "Nightfall"}.\n\n You may also reach at @{"5TH DIMENSION" Link "Dimension"} or just any board that i am on .. \n =) Just write a message or some thing like that.\n\n Another board is @{"THE MADHOUSE" Link "MadHouse"} \n or just call any @{"Tension board" Link "Tension"}!!! \n\n@EndNode\n@Node "9" "Personal Greetings"\n \n Greetings and Thanks\n ~~~~~~~~~~~~~~~~~~~~\n\n Aquarius/OTL              - Thanks for some help, m8!!\n\n Chig/TDS                  - It''s working fine??! =) \n \n Christ/DPL                - Want some more mail? eeehh!!\n \n Dansken                   - To large phone bills??\n \n Dixy                      - Have you found a group for ya board?\n 	\n HardHack                  - Here we go!!! =)\n \n JAz                       - Nice to talk with yaa.. \n 	\n Sincenatic/TSN            - Do you like this /X Tool .. \n \n Hawk                      - Is it fun in Boden!! ;)\n\n Waldo/TSN                 - Do you like this door??\n\n Whoosh/OTT^DVS^OTL^CLS    - Thanks for beta testing this door, m8!!!\n \n Wingnut                   - Need some more help m8?\n\n Xerox/ACS                 - Isn''t this a cool door, m8!!!\n\n Some more greetings goes to all other Tension members (Not the UK.) and \nto all i have forgot!!!!\n\n Ok a big thanks goes to you for reading my bad english =)...\n\n@EndNode\n@Node "0" "Problems!!!"\n\nIf any leave me a message and i will help you!!! \n\n@{"How to contact me! If you have any problems..." Link "8"}\n \n@EndNode\n@Node "XIM" "Installaion of XIM doors!"\n\nXIM door installation.\n~~~~~~~~~~~~~~~~~~~~~~\n Copy Commands/BBSCmd/c.info from the archive to your BBSCmd directory as\n<command>.info in this case it''s c.info. Don''t forget to check it''s \ntooltypes are correct.\n\nFor more info see /X documentation!!!\n\nPress this to @{"Go Back" Link "5"}\n\n@EndNode\n@Node "Nightfall" "CALL NIGHTFALL"\n\n                               ¼¼       .¼¼¼     .¼¼¼¼¼         ¼¼¼  ¼¼¼\n                     .¼¼¼¼¼¼¼. ¼¼       ¼¼¼''     ¼¼¼''           `¼¼  `¼¼\n                ¼¼  .¼¼¼''`¼¼¼¼ ¼¼      .¼¼''     .¼¼''  .¼¼¼¼¼¼.¼  ¼¼   ¼¼\n   ¼¼¼:¼¼¼¼¼.      .¼¼''        ¼¼     ¼¼¼¼¼¼   ¼¼¼¼¼¼ ¼¼¼'' `¼¼¼  ¼¼   ¼¼\n   `¼¼¼'' `¼¼¼  .¼¼ ¼¼¼  .¼¼¼¼. ¼¼:¼¼¼. `¼¼''     `¼¼''  ¼¼''   `¼¼  ¼¼   ¼¼\n    ¼¼''   `¼¼  ¼¼'' ¼¼''  ¼¼''`¼¼ ¼¼¼`¼¼¼  ¼¼       ¼¼   ¼¼     ¼¼  ¼¼   ¼¼\n    ¼¼     ¼¼  ¼¼  ¼¼       ¼¼ ¼¼'' `¼¼  ¼¼       ¼¼   ¼¼     ¼¼  ¼¼   ¼¼\n.-- ¼¼ --- ¼¼  ¼¼  ¼¼.----- ¼¼ ¼¼ - ¼¼  ¼¼ ----- ¼¼ - ¼¼ --- ¼¼  ¼¼ - ¼¼ ---.\n| ¬ ¼¼   ¬ ¼¼  ¼¼  ¼¼¼. tS¬.¼¼ ¼¼ ¬ ¼¼  ¼¼     ¬ ¼¼ ¬ ¼¼   ¬ ¼¼  ¼¼ ¬ ¼¼  ¬ |\n|   ¼¼     ¼¼  ¼¼  `¼¼¼.  .¼¼¼ ¼¼   ¼¼  ¼¼. ¼¼   ¼¼   ¼¼.   .¼¼  ¼¼   ¼¼    |\n|   ¼¼     ¼¼  ¼¼   `¼¼¼¼¼¼¼¼'' ¼¼   ¼¼  ¼¼¼.¼¼   ¼¼   ¼¼¼. .¼¼¼. ¼¼.  ¼¼.   |\n`-- ¼¼ --- ¼¼  ¼¼ ----`¼¼¼¼'' - ¼¼ - ¼¼ -`¼¼¼¼''-- ¼¼ --`¼¼¼¼¼¼`¼¼ `¼¼¼ `¼¼¼ -''\n           ¼¼\n      3NÐZ ®¡NGdOWN - oNE oF eU®OPE''S fAStE$t oN aM¡GA! - 3NÐZ ®¡NGdOWN\n   a3k/25MhZ - 9ooMb oNL¡NE - aM¡GA+pC+sNES - /X 4.xx - hUGE /X çONFERENCE\n » dEV¡OUS dEZ¡GNS( )oVER tHE tOP shQ( )oUTLAWS diST.S¡tE( )2ooo Ad pC whQ «\n       nOdE 1: +46 9O 12O369 (14.4kdS) nOdE 2+3: !r¡NGdOWN! (16.8k dS)\n                        nOdE 4: !çOM¡NG sOON! (28.8k)\n\nPress this to @{"Go back" Link "8"}\n\n@EndNode\n@Node "Dimension" "CALL 5TH DIMENSION"\n\n   5TH       /\                                        /\    :__             \n     _______/  \_ __  /\__ _________ _____/\ ________/\  \___|__\__ _____/\  \n    _\____¬\____/   \/  _/_____    /______  \_   _____/___/  _____/______  \_\n   /    /   \_  |  \  / ¬\   _____/.    /    /____  ¬\_   |  |   ¬\_   /    /\n _/    /     /  |   \/    \_ |     |  _/    /   /     /   |  :     / _/    / \n \__________/___|    \_____/_______|__\    /_________/____|_______/__\    /  \n             \________/                \  /                      [JWL]\  /   \n                                        \/                             \/    \n                                                                             \n                       tENSIoN wORLd hEADQUARtERS                            \n                                                                             \n         lEADER: JeWEL/tSN   cOlEADERS: dIzMEM/tSN ^ cYBERIX/pLX             \n                                                                             \n                     sUPPORtS: aMIgA - PC - C64/128                          \n                                                                             \n                         oNLINE aSCII oRDERING!                              \n                                                                             \n                     nODE1: +46-381-17881 - nO nUP!                          \n\nPress this to @{"Go back" Link "8"}\n\n@EndNode\n@Node "MadHouse" "CALL THE MADHOUSE"\n \n   tHE                     ____________        _________\n   ____  /\ ________   ____\_    /  __/________\_      /_________________\n   \_ _\/_ \______ ¬\_/   _     /   _   ¬\_  _  ¬\_   / ¬\_  ___/\__ _  ¬\_\n  /    \/   \_  _/   \    /    /    /     /  /    /  /    /__     / ______/\n /     /     /_/      \_ /    /    /     /  /    /  /    /  /    /  /    \_\n/_____/     /_\________/_____/____/     /_______/_______/___    /___      /\n  CRb/_____/e^D                  /_____/                  /____/  /______/\n \n                 -*-  tENSION sHQ  -*-  rELIGION sHQ  -*-\n\n                        -*-  +46(0)479-20556  -*-    \n\nPress this to @{"Go back" Link "8"}\n\n@EndNode\n@Node "Tension" "Tension boards!!"\n\n                           ._________________.                            \n                           |                 |                            \n                           |                 |                            \n              ______       |               ______                         \n  ___________/     /______________________/     /     __________________  \n  \    _     __   /       /   _   ¬\_   __     /_____/   ___________   ¬\ \n   \   /     /   / ______/__  /    /    /_____/_____/    /    /    /    / \n    \_/     /___/__________/ /    /_____     /     /    /    /    /    /  \n     /     /     /     /    /    /    /     /     /    /    /    /    /   \n    /_____/___________/____/    /__________/_____/_________/____/    /    \n <---------------------JWL/____/ ----------- . -------------tSN/____/ --->\n                           .                 |                            \n                           |    