INSERT INTO door_catalog VALUES('tsn_oeck','TSN-OECK.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TSN-OECK.LHA','lha','XIM','lha',NULL,NULL,'TSN','/ _   ___ _____/\| \_  __Y__Y    Y   \|  | \_|   || ___|__  \  |__ \|  |  : | .  \  | |   || \    / \   | |  \  | _| |  \    |',replace(' ________/\_____ ._______ /\ ____ ___  __.\n/ _   ___ _____/\| \_  __Y__Y    Y   \|  |\n\_|   || ___|__  \  |__ \|  |  : | .  \  |\n  |   || \    / \   | |  \  | _| |  \    |\n  |   ||_____/__|\__|____/__|____|  |\   |\n  |___| TENSi0N! presents in ''94 |__| \__|\n    :                                  :\n    |          OEDiCheck V1.0          |\n    |         -==============-         |\n    :       A NEW AND FASTER LHA       :\n    `-----CHECKER/STRIPPER/ADDER!------''\n','\n',char(10)),'OEDiCheck.doc',replace('\n                                               /\\n    ._____.                          _        /  \\n .__|     |__/\___________ : _ _____/ \__.___/.   \ _______   ____ : _ ___\n ____     ___    _____/   \|    _/ _________//     \_____  \ |    \|    _/\n    |     |/    ____/__  . \    |______    \\______/   |/   \|   . \    |\n    |    :|     \    ./   \     |    |/     \|    |    .     \    \     |\n    |    ||_______  //    |\____|     ______/|____|__________/    |\____|\n+---|_____| ------\_/|____|-----|_____/----------------[SB!]-|____|-------+\n\n\n                            P R E S E N T\n\n                           OEDiCheck V1.0\n\n           - A NEW AND FASTER LHA CHECKER/STRIPPER/ADDER! -\n         ====================================================\n\n\niNTRODUCTiON\n------------\n\nI wrote this door in quite a short space of time as I changed my LHA\nchecker on the BBS and then had major problems, looked through my HUGE /X\nconference (hehehe!) and thought, "Sod this for a laugh, I''ll write a\nreally fast one!". Thus was born OEDiCheck!\n\n\nCREDiTS\n-------\n\ncODiNG - OEDiPUS/TSN^LSD\ndOCS   - OEDiPUS/TSN^LSD\n\n\niNSTALLATiON\n------------\n\nTo Install the door simply unpack the archive to ram and copy the files\ninto their respective directories - nothing could be simpler!  Then edit\nthe strip and add text files as described below to make OEDiCheck the\nFASTEST Lha stripper ever!\n\n\nhOW tO uSE OEDiCheck\n--------------------\n\nEdit the file s:hello to choose which files you want to add to your lha\nfile, and then edit the file s:goodbye to remove files from the lha file.\nThere are two example files provided and you might well want to use the\nstrip file as it is quite a comprehensive one!\n\n\ngREETiNGS\n---------\n\nHellos fly out in no order to:\n\nTANGo/oGN&sPB, ChaRoN, wIT/LsD, FisH/LsD, mANiK/OgN, cOnX, wINTERmUTE,\nDORiE, SiR GiLES/TrD, TaLoN/DlT, BANDiT, ELRiC?/OtT, sTAB/TsN, lOOSE\nmARBLES/LsD, fAT fREDDy, cRYTON/aPC, vIOLATOR/aPC, hOTWiRE/OgN, dAZE/dLC,\nbOB dA gOD/TsN, cIARS, dAFFY dUCK/TsN, aQUafRESh/KrM, bONEiDLE/MxM,\ntONTO/TrD, fROSTY/TrD, AxEn/TsN, SaSHa/OgN, MDR/OtT, DeAdLiGhT, lOoPy!,\nhYdRa/LsD, DeNzIl/LsD, MeNtOr/MgC, GuNdAm/MgC, JiNX, eXiLE, Mars Bar/LsD,\nGrAdIuS/ATX, PaZzA/LsD, TrI×TeR/LSD, mUb/LSD, Ken D/LsD, BiG W/TsN,\ncRUiSe/LsD, ZYGoTE/lSD, dAtA-sTrEaM/SR, AnF!/FEAR, MiC FLAiR/ElTeCh,\nZoNE/NVX, TeCLiS, and ANYONE i''ve unfortunately forgotten!\n\ncONTACT\n-------\n\nIf anyone wants to contact me to request a door or anything like that you\ncan call my BBS - Advert to follow, or indeed mail me on any of these cool\nTension BBSs :\n                                               /\\n    ._____.                          _        /  \\n .__|     |__/\___________ : _ _____/ \__.___/.   \ _______   ____ : _ ___\n ____     ___    _____/   \|    _/ _________//     \_____  \ |    \|    _/\n    |     |/    ____/__  . \    |______    \\______/   |/   \|   . \    |\n    |    :|     \    ./   \     |    |/     \|    |    .     \    \     |\n    |    ||_______  //    |\____|     ______/|____|__________/    |\____|\n+---|_____| ------\_/|____|-----|_____/----------------[SB!]-|____|-------+\n\n                             cAN bE rEACHED aT\n\n                  Entity          +44-81 -FAST! - EHQ\n                  Utopia          +44-202-FAST! - UKHQ\n                  Eternal Slavery +44-892-FAST! - UKHQ\n                  Jurassic Park   313-484-0191  - USHQ\n\n           For joining, mail DAFFY DUCK or AXEN on any TSN BBS.\n\n\nor call.........................\n\n-+=÷=+=÷=+=÷=+=÷=+=÷=+=÷=+=÷=+=÷=+=÷=+=÷=+=÷=+=÷=+=÷=+=÷=+=÷=+=÷=+=÷=+=÷-\n\n   ---+-<«---------------------------»>-=÷=-<« +44·(0)71·737·5466 »>-+---\n                                 __\n    _____   /\__________________/__\_____________\n  - \___·\ / \__ ____\__  \____  \__ ___\_____  ·\-+ -\n      /¬ \Y   /¬ __)_ /¬  !__/  ·\/¬ __)_|  ¬!  _/ sysop..øediPus/lsD&tSn\n     /   __  ·\    ¬·\    |  ·\  /     ¬·\      ·\   cøs..tanGø...CønX...\n    /    ¬|   \\     \\   !   /  \       \\      \\     ..pRiNCiP..ÐeNZil.\n - -\     l____/______/______/_ __\_______/___\   \\- - .bOB dA gOD.PiTCh.\n     \ __/                   _/(_              \__  )   ..sIr GilEs.....\n      Y       _____________ /___/________________/_(______________\n      |   - --\____   ·\ ¬|/ \__  ____\__  \____  \__ ___\_____  ·\--+ -\n      |       _/¬  \___/  !  _/¬  __)_ /¬  !__/  ·\/¬ __)_|  ¬! __/\n      |      / \___  ·\      ·\     ¬·\    |  ·\  /     ¬·\      ·\\n      |     /    ¬!   \\  |   \\      \\   !   /  \       \\      \\\n      | - +-\__________/__l_____)______/______/____\_______/___\   \\-- -\n      |                                                       w¡t___ )\n      |       -= fast amiga warez -=- good /X conference =-         Y\n      !                                                             !\n   - -^-=-^\24Ø mb ønline/^-=-^\24hrs/^-=-^\6mb råm/^-=-^\68o2Ø/^-=-^- -\n\n-+=÷=+=÷=+=÷=+=÷=+=÷=+=÷=+=÷=+=÷=+=÷=+=÷=+=÷=+=÷=+=÷=+=÷=+=÷=+=÷=+=÷=+=÷-\n','\n',char(10)),NULL,'auto-added',73607,12,0,NULL,NULL,'tsn_oeck','scan',1780048806);
INSERT INTO door_catalog VALUES('tsn_sg10','TSN-SG10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TSN-SG10.LHA',NULL,'XIM','<«»«»«»(·eVERYwARE!  ÷  tRSi^aCCESs·)«»«»«»>',NULL,'Lockjammer/TSN','TSN','_______________________________ ____________ ·____ _ / __  /__  ./  ______/// _______  ./ ::./  //  ___/  / //___  /  ¬\/  /  /  / //.',replace('<«»«»«»(·eVERYwARE!  ÷  tRSi^aCCESs·)«»«»«»>\n_______________________________ ____________\n·____ _ / __  /__  ./  ______/// _______  ./\n::./  //  ___/  / //___  /  ¬\/  /  /  / //.\n|:/__ /_____/__/__/____ /_____\____/__/__/:|\n+JWL\/---÷pRESENtS÷---\/------------------÷+\n    SpeedGuard  v1.00 By Lockjammer/TSN\n.------------------------------------------.\n|   This is the door that fixes all the    |\n|   problems with user running on lower    |\n:               baud rates.                :\n<------------(-lIQUID sKY ''95-)------------>\n','\n',char(10)),'SpeedGuard.guide',replace('@Database "SpeedGuard v1.00 Documentation"\n@Author "Lockjammer/Tension"\n@Remark $VER: SpeedGuard v1.00 AmigaGuide doc\n@Node Main "SpeedGuard v1.00 Documentation (95-04-20)"\n_______________________                  _ _________ _________            \n\__._ _   _.__/_______/_____       _______ ________/.         \_____      \n   | \/-   |___________/_ _ \  ___·      (_____     |    §     /  _ \  __.\n   l_______|____________/ \  \/   `._______    \____|_________/   \  \/  |\n                   /_______\______________/_____\          /_______\_____|\n\n                                 PRESENT          \n\n             -=- SpeedGuard v1.00 by Lockjammer/Tension! -=- \n\n               @{"    Introduction    " Link "1"}  @{"  Archive Contents  " Link "2"}\n               @{"      Features      " Link "3"}  @{"    Requirements    " Link "4"}\n               @{"    Installation    " Link "5"}  @{"   Configuration    " Link "6"}\n               @{"      History       " Link "7"}  @{"     Contact Me     " Link "8"}\n               @{"      Problems      " Link "0"}  @{"     Greetings      " Link "9"}\n\n               @{"       JUST SOME INFORMATION TO YOU       " Link "INFO"}\n\n@EndNode\n\n@Node "1" "Introduction to SpeedGuard v1.00"\n\nSome info about this release!\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nThis program is FREEWARE and may distributed freely as long as the archive \nis kept intact with all its original files. FREEWARE means you don''t have \nto pay a registration fee for the use of this program but you may not \nalter it to your liking. This program may not be sold for commercial \npurposes and may only be distributed freely as stated above. \n\nThis program is copyright ©1995 Lockjammer.\n\nIntroduktion to SpeedGuard.\n~~~~~~~~~~~~~~~~~~~~~~~~~~~\nThis door fixes the problem with having users calling at 2400 or any other\nspeed.. But you don''t want to let them dl/ul or just don''t want any other\nperson running at 2400.. You may also have diffrent times that users can \ndo diffrent things.. This is a must for yaa.. Just check it out..  \n\n@EndNode\n\n@Node "2" "Archive Contents of file TSN-SG10.LHA"\n\nThe TSN-SG10.LHA Archive contens the following files.\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n      Filename         |  Size  | Description\n- --  -- -- --  - -- --+- -  -  +- - -- -- - -  - --  -  - - --  -\nDoors/SpeedGuard/      |        |\n SpeedGuard.000        |  13116 | SpeedGuard version for 68000+.\n SpeedGuard.020        |  13116 | SpeedGuard version for 68020+.\n SpeedGuard.guide      |  13701 | This document file.\n SpeedGuard.guide.info |    471 | The info file for the documention.\n SpeedGuard.info       |    619 | Configuration file.\n                       |        |\nCommands/SYSCmd/       |        |\n SG.info               ¦   1051 | This is the command icon for /X 3.xx+.\n                       :        ¦\n                       .        :\n                                .\n\n@EndNode\n\n@Node "3" "Features on this door."\n\nFeatures.\n~~~~~~~~~\n* Diffrent controlls for diffrent time zones.\n\n* Diffrent controlls for special users.\n\n* Skipp check on user with hi access level.\n\n* Show a text file before kicking user out.\n\n* You may controll if the user can Ul, DL or logon.\n\n* And muck much more.. Just check it out\n\n@EndNode\n\n@Node "4" "Requirements on this version"\n\nWhat will i need to make it work???\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nAMIGA:         It works on a A500 and up to A4000! That''s more what you \n              can say about some PC programs =) !!! \n\nAmiExpress:    The door works on /X 3.xx+! But it can work on other \n              versions too!!! (It works with S-Express).\n\nOS:            Yee you need OS2.0+ to make it work...\n\nMemory:        Not much!!!\n\n@EndNode\n\n@Node "5" "Installation of SpeedGuard"\n\nThe only thing you have to do is...\n\nCreat a directory ''Doors:SpeedGuard'', and copy the version of your choice \nthere.\n\nSpeedGuard.000 is for AmiExpress 3.xx+ and 68000+.\nSpeedGuard.020 is for AmiExpress 3.xx+ and 68020+.\n\nCOPY THE CONFIGURATION FILE TO THIS DIRECTORY. CONFIGURATION FILE IS NAMED\n''SpeedGuard.info''.\n\nDon''t forget to copy this doc file to that directory for future needs.\n\nCopy ''SG.info to your SYSCMD directory and check that its tooltype\nLocation i correct.\n\nJust run the door with MCI in the logon.txt.. Every logon.txt should start\nwith the following:\n\n- -- --- -- -- CUT-HERE -- -- --- -- -\n~\n~CC_SG|\n- -- --- -- -- CUT-HERE -- -- --- -- -\n\nNow the only thing you have to do is edit the tooltypes in the \nconfiguraion file, ''doors:SpeedGuard/SpeedGuard.info''. \n\n@{"Configuration of SpeedGuard" Link "6"} \n\nOk that''s all, now your on your way!!!\n\n@EndNode\n\n@Node "6" "Configuration of SpeedGuard"\n\nConfiguration of SpeedGuard.\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nAll configuration is done in the ''SpeedGuard.info'' file. Just change the \ntooltypes.\n\nThe tooltypes are....\n~~~~~~~~~~~~~~~~~~~~~\n\n- ---- - - -  -  - --  - -  -  ---  - - ---  -  --  ---- - -- --- - - -- -\n\nTemplate.....: TEXT=<name and path to file>\nExample......: TEXT=S:KickOut\n\nThis is the file that is going to be shown when the user is kick out from\nthe bbs. If you don''t add this tooltype the program will just kick out the\nuser and not show any text if he is too slow.\n\nIn the example the door would try to display s:kickout.txt(.gr) also \ntakes into account language specifications. This also searches for the\naccess level patterns, ie: S:KICKOUT10.txt.gr, S:KICKOUT100.txt.gr...\n\n- ---- - - -  -  - --  - -  -  ---  - - ---  -  --  ---- - -- --- - - -- -\n\nTemplate.....: BAUD=<Lowest baud rate>\nExample......: BAUD=14400\nDefault......: BAUD=9600\n		\nThis is the lowest baud rate the program is going to let throw with no \ncheck...\n\n- ---- - - -  -  - --  - -  -  ---  - - ---  -  --  ---- - -- --- - - -- -\n\nTemplate.....: ACC_LEVEL=<Access level>\nExample......: ACC_LEVEL=250\n\nIf you have the same or higher access level the program will let you \nthrow. If you don''t add this tooltype the program will check every user\nthat is not running at the correct baud rate or higher.\n\n- ---- - - -  -  - --  - -  -  ---  - - ---  -  --  ---- - -- --- - - -- -\n\nTemplate.....: TIMEG.<Pos>=<From>-<To>\nExample......: TIMEG.1=1700-1300\n\nThe general time that the door will do things. You may also give periods\nthat starts before 0000 and ends after 2359 example.. timeg.1=2200-0100\nand so on...\n\n- ---- - - -  -  - --  - -  -  ---  - - ---  -  --  ---- - -- --- - - -- -\n\nTemplate.....: DOG.<Pos>=<What to do>\nExample......: DOG.2=XX_\nDefault......: DOG.<Pos>=XXX\n\nThis is what the door will do when the time is right.. \n\nDoG.1=XXX\n      |\nDO LOGIN.    This makes it posseble for the user to login.\n\nDoG.1=XXX\n       |\nDO UPLOAD.   This makes it posseble for the user to upload.\n\nDoG.1=XXX\n        |\nDO DOWNLOAD. This makes it posseble for the user to download.\n\nIf you don''t want the user to do one or all of the things above just put\na _ instead of X...\n\n- ---- - - -  -  - --  - -  -  ---  - - ---  -  --  ---- - -- --- - - -- -\n\nTemplate.....: NAME.<Pos>=<User name>\nExample......: NAME.1=Lockjammer\n\nYou may set give special users diffrent "times" and "do" things.. \nI hope you got that..\n\n- ---- - - -  -  - --  - -  -  ---  - - ---  -  --  ---- - -- --- - - -- -\n\nTemplate.....: TIME<>.<Pos>=<From>-<To>\nExample......: TIME1.1=1200-1500\n\nThis is the special user time.. For more info se timeg...\n\n- ---- - - -  -  - --  - -  -  ---  - - ---  -  --  ---- - -- --- - - -- -\n\nTemplate.....: DO<>.<Pos>=<What to do>\nExample......: DO1.1=X__\nDefault......: DO<>.<Pos>=XXX\n\nThis is the special user do.. For more info se DoG...\n\n- ---- - - -  -  - --  - -  -  ---  - - ---  -  --  ---- - -- --- - - -- -\n\n@EndNode\n\n@Node "7" "History"\n\nv0.60 Beta-test version.. No bugs, Nothing to fix..\nv1.00 Release version.\n\n@EndNode\n\n@Node "8" "How to contact me"\n\n  If you have any problems or have found any errors with the program or \n anything else i can be reached at the board given below. \n \n The safest place to reach me is @{"NIGHTFALL" Link "Nightfall"}.\n    _.____.      _______   _______   _______   _   _______   _______\n     ¡.  _¡__ _._\___  /_._\___ _/_._\   __/_./¬\._\_ ___/_._\___ _/_._\n     ||  ___/__¡   ___/  ¡    |    ¡  \___   ¡   \    /    |    |    ¡   \n     |:   \    |   \     |    |    |    /    |    \   \    |    |    |   \n     |_________|_________|____|____|_________|_____\_______|____|____|\n    <==»=>>========== B O A R D S   I N   S W E D E N ===[JWL]==<<=«==>\n\n NAME          .      . DIAL                . MODEM   . SYSOP \n- ---  -- - - -+- -- -+- -- --- - --- - -- -+-- - -- -+- - --  - --  -  -\nTHE LAST INN   | SHQ  | N1  +46-410-30063   | 28.8    | ARAGORN\n               |      | N2  +46-410-30520   ¦ 28.8    |\nCUCKOO''S NEST  ¦ SHQ  |     +46-60-178386   : 28.8    ¦ AMON\n               :      ¦                     .         :\n               .      :                               .\n                      .\n\n@EndNode\n\n@Node "9" "Personal Greetings"\n \n Greetings and Thanks\n ~~~~~~~~~~~~~~~~~~~~\n\n Aquarius/OTL              - Hope you like this one. \n \n Amon/TSN^MST              - Thanks for the beta-testing!!\n\n Aragorn/TSN^3AD           - Thanks for the beta-testing!!\n\n Chig/TDS                  - Don''t loose your head =)\n\n Christ/DPL                - Leave me a line.. Will yaa...\n\n Daffy Duck/TSN            - Get back soon!! =)\n\n Dalamar/LED               - WORKING ON THAT DOOR FOR YAA..\n\n Dansken                   - How is your board going ??\n\n HardHack                  - You need a new watch...\n\n Hydra/LSD^TSN             - Hope to chat with ya some time.\n\n JAz                       - Nice to talk with you..\n\n Kid Curry/INV             - Don''t you want to rejoin TSN =).. \n\n Nike/CRZ^DLT              - Waiting for another door from you =)..\n\n Sincenatic/TSN            - Do you like this door.. I will call you..\n\n Whoosh/OTT^DVS^OTL        - Lets go and party!!!! =)\n\n Xerox/ACS                 - Another door.. Hope you like this..\n\n Some more greetings goes to all other Tension members and to all i have\nforgot!!!!\n\n@EndNode\n\n@Node "0" "Problems!!!"\n\nIf any, leave me a message and i will help you!!! \n\n@{"How to contact me! If you have any problems..." Link "8"}\n \n@EndNode\n\n@Node "Nightfall" "CALL NIGHTFALL"\n\n                               ¼¼       .¼¼¼     .¼¼¼¼¼         ¼¼¼  ¼¼¼\n                     .¼¼¼¼¼¼¼. ¼¼       ¼¼¼''     ¼¼¼''           `¼¼  `¼¼\n                ¼¼  .¼¼¼''`¼¼¼¼ ¼¼      .¼¼''     .¼¼''  .¼¼¼¼¼¼.¼  ¼¼   ¼¼\n   ¼¼¼:¼¼¼¼¼.      .¼¼''        ¼¼     ¼¼¼¼¼¼   ¼¼¼¼¼¼ ¼¼¼'' `¼¼¼  ¼¼   ¼¼\n   `¼¼¼'' `¼¼¼  .¼¼ ¼¼¼  .¼¼¼¼. ¼¼:¼¼¼. `¼¼''     `¼¼''  ¼¼''   `¼¼  ¼¼   ¼¼\n    ¼¼''   `¼¼  ¼¼'' ¼¼''  ¼¼''`¼¼ ¼¼¼`¼¼¼  ¼¼       ¼¼   ¼¼     ¼¼  ¼¼   ¼¼\n    ¼¼     ¼¼  ¼¼  ¼¼       ¼¼ ¼¼'' `¼¼  ¼¼       ¼¼   ¼¼    