INSERT INTO door_catalog VALUES('tsn_sstp','TSN-SSTP.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TSN-SSTP.LHA','SStrip','XIM','SStrip',NULL,'HYDRA/TSN','TSN','/ _   ___ _____/\| \_  __Y__Y    Y   \|  | \_|   || ___|__  \  |__ \|  |  : | .  \  | |   || \    / \   | |  \  | _| |  \    |',replace(' ________/\_____ ._______ /\ ____ ___  __.\n/ _   ___ _____/\| \_  __Y__Y    Y   \|  |\n\_|   || ___|__  \  |__ \|  |  : | .  \  |\n  |   || \    / \   | |  \  | _| |  \    |\n  |   ||_____/__|\__|____/__|____|  |\   |\n  |___| TENSi0N! presents in ''94 |__| \__|\n   :                                    :\n   |   Simple Strip! By HYDRA/TSN       |\n   |                                    |\n   |a small util to strip lines of text |\n   | from other text files!  KKKKOOOOLL |\n   `------------------------------------''\n','\n',char(10)),'SStrip.doc',replace('\n                   Simple Strip! (C) 1994 Hydra/Tension!\n\n\nOh Kewl!  Another stripper program you''re thinking (NOT!)\n\nWell, this one''s different!  it''s SIMPLE! :-)  (Hence the name!)\n\nall this program does is take one text file and remove certain lines from in\nand writing the output to another file,  the lines it removes are specified\nin another text file (you may have upto 1000 lines), each line being on a\nseperate line,  be careful that you don''t have a blank line anywhere in the\nfile tho :-)\n\n\nAnywayz, that''s it really!  Nothing special but it''s still usefull to me!\n\nI personally use it for removing the line that says\n\n"UNREGISTERED, PLEASE REGISTER THIS PROGRAM"\n\nfrom the output file of a certain bulletin maker! :-) Giggle!\n\n\n\n\nRight ?  Think you could do better than this ?  Well, Do it then!   This aint\nmeant to be the be all off strippers, but it''s nice''n''handy!\n\nIf you have any other cool ideas for programs that you want me to write then\ndrop me a line on any Tension or LSD BBS in the UK!','\n',char(10)),NULL,'auto-added',17066,1,0,NULL,NULL,'tsn_sstp','scan',1780048813);
