INSERT INTO door_catalog VALUES('ttn_ss10','TTN-SS10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TTN-SS10.LHA',NULL,'XIM','.oOOo..oOOo.oO[ACD] [HAD] [IT]Oo.oOOo..oOOo.',NULL,NULL,'TTN','______/\_________ _____ |___  (__)  __/_  |     | presents another |  |  |  |  _  |  |  | kewl release for',replace('.oOOo..oOOo.oO[ACD] [HAD] [IT]Oo.oOOo..oOOo.\n ______/\_________ _____\n|___  (__)  __/_  |     | presents another\n   |  |  |  |  _  |  |  | kewl release for\n   |  |  |  |  |  |__|  | da amiga in 1995\n   `--^--^--^--^--''  `--'' :.:.:.:.:.:.:.:.\n-------------- /X Doors Section ----------\nNew Replacement S Door.........\nAdd Oneliner TO The Next Callers..........\n+ All THe Other Bits    Released: 14-03-95\n.oOOo..oOOo.oO[ACD] [HAD] [IT]Oo.oOOo..oOOo.\n','\n',char(10)),'SStAtuS.guide',replace('@database " Pink Floyd & Purple Motion "\n@Node MAIN "Super Stats"\n\n\n\n\n\n        @{" Purpose      ? " link "menu"}\n                         @{" Installation ? " link "menu2"}\n  SUPER STATS V1.00 ''95                   @{" Requirements ? " link "menu3"}\n                         @{" Credits      ? " link "menu4"}\n        @{" Support      ? " link "menu5"}\n                             \n                              \n@endnode\n\n@node "menu" "What does it do?"\n@toc "menu"\n\n\n                           =WHAT DOES IT DO???=\n\n     This small Util is an ''S'' replacement for your /X3.+/4.+ Versions\n\n          Boring Just as any Other ''S'' replacement EXCEPT this one\n\n                      Has A One Liner To The Next User\n\n            Will also keep a log of who wrote what and when \n           ----------------------------------------------------\n\n\n                 It is very simple but unbelievably Coo| !\n\n\n                            @{" BACK TO MAIN MENU? " link "MAIN"}\n\n@endnode\n\n@node "menu2" "Installation"\n@toc "menu"\n\n\n                            ../INSTALLATION\..\n\n          Nice Question ! Just Copy all files to your directories\n                                and go ...\n\n\n      IF YOU DONT GET THE INSTALLATION JUST *CLOSE* YOUR BBS!DUMMASS!\n\n@endnode\n\n@node "menu3" "What does it require?"\n@toc "menu"\n\n\n                     =WHAT ABOUT THE REQUIREMENTS???=\n\n                       AMIGA 5oo-4ooo (68ooo-68o4o)\n\n     AMIEXRESS V3/4X+ (C)LIGHTSPEED 94 / S-EXPRESS0.xx (C) SIGMA SEVEN\n\n\n      This Program will run On *ANY* Machine!Execpt PeeCee Clowns :)\n\n\n@endnode\n\n@node "menu4" "Credits!"\n@toc "menu"\n\n                               =THE CREdZ!=\n\n                        Coding - Pink Floyd  TTN/INO\n                        Coding - Purple Motion  TTN\n\n\n                            CygnusEd - ASDG Inc\n                          Rexx - C=Commodore Inc\n                         Amiexpress - Joseph Hodge\n                      RpStart - Dineen Edwards Group\n\n                 Squeaky,Lazzer,Exile,The Pro-File,Sir Snooze\n                     Pixie,Sarge,Hustler,Numark,Demons\n                         Jb,Cyanide,Tronic,Pascal.\n      \n                     And anybods i forgot to mention\n\n\n                            @{" BACK TO MAIN MENU? " link "MAIN"}\n\n@endnode\n@node "menu5" "Support"\n@toc "menu"\n\nINSERT INTO door_catalog VALUES('tt_muc10','TT_MUC10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TT_MUC10.LHA',NULL,'XIM','Install.exe',NULL,NULL,'TT','\      |  / |  ______/\_ _\  ___/ __  \ + :\/ |   _/  |  \_  \/  / / \  __)  _) / : :/  :  _\   |  / \  \ /  \  \   \  \  \ :',replace('_______.______________________________   \n\      |  / |  ______/\_ _\  ___/ __  \ +\n:\/ |   _/  |  \_  \/  / / \  __)  _) / :\n:/  :  _\   |  / \  \ /  \  \   \  \  \ :\n:\__|__|_\____/  /\__/|___  /____\ |\  \:\n+----(teChNo-)\_/(-LogYs!)\/----|__|/__/+\n| /X-Section presents:                  |\n|        ==>MUI-CHAT V1.0<==            |\n|   allows You to have more than one    |\n|local sYSOP tO cHAT wITH !!! lEECH nOW!|\n+---------------------------------------+\n','\n',char(10)),'MUICHAT.Guide',replace('@database "tHUNDER tECHNOLOGY - MUI-CHAT V1.0"\n@AUTHOR "fOX/TT"                  \n@(C) "fOX/TT"                   \n@Ver$ "tHUNDER tECHNOLOGY - MUI-CHAT V1.0 (16-04-94)   \n@HEIGHT 30\n@Node MAIN "MUI-CHAT"\n\n_____________  ____     __   ___  :   _:________________________________\n\           /_|    :___|  \ |   \ :   \         _______    /____       /\n \\ _   _  /  |   :|   |  \\|   \\:    \____    \ /   /___/   _/      /\n  \/     \/   :   :|   |    |     \_   :    \   \\   ___/_|   \______/\n   |.    |    _    |   |    |   \      :     \   \\_      /    .    \\n   |:    :    |    |   :    |    \     :    _/     /     /|    |     \_\n   :     :____|    |________|    |\____:__________/_____/ |    |______/\n   |_____|    |    :        :____:                        |____|\n____________  :    :           .                  .          ______.\n\          /_______________:   :__  :   : ___ :   :  ___ ____\___  |___\n \  _  _ //______   /    / |   :  \ :   |/   \|  :| /   \       /  |   \\n  \/    \/ /    /__/  __/  |   |  \\:   | \  \\  :|/ \  \\   __/\\ :  //\n   |:   | //   __/__ /__   :  .|    \_  :  \   \_ |   \   \  \_  \_   /\n   |    ://        /   /   _  :|  \     : _/    / |/\_/   /  /    /  (\n   :    :         /    \_  |   |   \    :______/    \\___/_______/   |\n   :    |________/______/__|   |   |\___:     |______/          |    :\n        :                  |___|___:                                 :\n                       \n                       MUI-CHAT V1.0 by FOX/TT\n\n                       @{"  Disclaimer  " link "Disc"}\n                       @{" Requirements " link "Req"} \n                       @{" Installation " link "Inst"}\n                       @{" Future Plans " link "Plans"}\n                       @{"  Greetings   " link "Greet"}\n\n\n@endnode\n\n@node "Req" "Requirements"\n@toc "Req"\n\n       Any Amiga (500,600,1000,1200,2000,3000,4000,4000T,5000(?)....\n                  Installed S-Express, /X 2.xx or 3.xx\n                         An installed AREXX\n\n\n                            @{" BACK TO MAIN MENU? " link "MAIN"}\n\n@endnode\n@node "Inst" "Installation - PeiTSch dEN SueSs-Op V0.8743874"\n@toc "Inst"\n\nJust copy the files\n                     @{"STARTCHAT1.txt" link "Chat1"}  \n                     @{"STARTCHAT2.txt" link "Chat2"}   \n                     @{"STARTCHAT3.txt" link "Chat3"}\n\n                   to DOORS:MUICHAT/\n-------------------------------------------------------\n/X 2.xx or S-Express:\n\nEdit Your SYS.CMD and snap in the following:\n\n*CST      RM255DOORS:MUICHAT/MUICHAT.REXX\n-------------------------------------------------------\n/X 3.xx\n\ngo and fizzle with your bloody icons!\n-------------------------------------------------------\nthen edit your BBS:NODEx/STARTCHAT.TXT\n       or your BBS:BBSTEXTS/STARTCHAT.TXT\n\ninsert the following line at the start of this text:\n\n~CST\n\n                            @{" BACK TO MAIN MENU? " link "MAIN"}\n\n@endnode\n@node "Disc" "---> What it does: <---"\n@toc "Disc"\n\nIf somebody tries to page you, you`ll be able to answer his chat-request\nby simply pressing F1 .... (like ever before)\n\nthen, the BBS will display the BBS:NODEx/STARTCHAT.TXT (also nothing new)\n\nIn this moment, it will start the MUI-CHAT door via MCI-command (the ~)!\n\nAt this moment, the sysop on the console sees a menu where he can choose\nwhich startchat.txt (in DOORS:MUICHAT/) he wants to be displayed!\n\nSo... you can choose up to free different startchat.txt`s NOW!\n\nI wrote this tool, cause my girlfriend often wants to chat, and was always\nabused on my name standing at the top ....\n\n\n\n@{" Wow !" link "MAIN"}\n@endnode\n@node "Chat1" "STARTCHAT1.txt"\n@toc "Chat1"\n\n      This Text will be displayed if You do press "1" or CR\n      so this should be the default-sysop-text\n\n@{" Hummhumm " link "Inst"}                       \n@endnode\n@node "Chat2" "STARTCHAT1.txt"\n@toc "Chat2"\n\n              This text will be displayed if Your press "2"\n             \n          good for girlfriends, or Your Cosysop sitting beside You!\n\n@{" Yarp ! " link "Inst"}                       \n@endnode\n@node "Chat3" "STARTCHAT3.txt"                     \n@toc "Chat3"                                             \n\n              This text will be displayed if Your press "3"\n              \n              cause i don`t know, how much girlfriends you have =8-)\n                                            \n@{" Hehehe ! " link "Inst"}                                 \n@endnode\n@node "Plans" "Future plans"                             \n@toc "Plans"                                               \n                \n- I want to integrate the reqtools some day, cause of those OPWIN users!\n\n@{" Woobeegreat! " link "Inst"}                                \n@endnode\n@node "Greet" "---> Greetings <---"\n@toc "Greet"\n\ngreetings fly to:\n\n                   aLL TT-mEMBERS\n                   aLL mOTION-MEMBERS\n\n                   and to the rest of this fuckin` world!\n\n     \n                  \n\n                            @{" RiGHT ! " link "MAIN"}\n@endnode\n','\n',char(10)),NULL,'auto-added',5415,2,0,NULL,NULL,'tt_muc10','scan',1780048813);
INSERT INTO door_catalog VALUES('tul','TUL.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TUL.LHA','tul','XIM','tul',NULL,NULL,NULL,NULL,replace('- T U L - Today''s Uploads\n','\n',char(10)),'tul.doc',replace('\n    - T U L - Today''s Uploads\n   ~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n This little tool will show the uploads of today.\n\n Usage : TUL Path_UDLOG Path_OutputFile\n\n e.g.:   TUL BBS:NODE0/UDLOG RAM:UPLOADS.TXT\n\nsigned Gizmo/AFL\n\n','\n',char(10)),NULL,'auto-added',15740,4,0,NULL,NULL,'tul','scan',1780048813);
INSERT INTO door_catalog VALUES('turboz','TURBOZ.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TURBOZ.LHA','TurboZ','XIM','TurboZ',NULL,'Mack',NULL,'68000 Code by The Controller and NZO A Dual Crew-Shining Production',replace('Turbo Zippy by Mack Lifeguard\n68000 Code by The Controller and NZO\nA Dual Crew-Shining Production\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 20:40:21  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',10569,2,0,NULL,NULL,'dcs_tz1r','scan',1780048813);
INSERT INTO door_catalog VALUES('tvk_dc1','TVK-DC1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TVK-DC1.LHA','converter','XIM','converter',NULL,'HiFLY^TTT+','TVK','____  __\_  \__. /\__\   \___ ______ _______ \   \/   /_ /  |/   /_\  /  _\   _  \_  ___/ \      / \/\  /   /   \/\  / \__/___/__  \',replace('        ____         ____                   \n____  __\_  \__. /\__\   \___ ______ _______\n\   \/   /_ /  |/   /_\  /  _\   _  \_  ___/\n \      / \/\  /   /   \/\  / \__/___/__  \ \n  \    /    /  _   \     / /   /\_   \ /   \\n   \__/|___/|___\   \___/_/   /______/_____/\n        Presents \___\   /____\  /___/SyK!  \n+PROFESSIONAL DUPECHECKER V1.o By HiFLY^TTT+\n| Test over 10000 files in less than 1 sec |\n|        Features many cool options        |\n+---------( RELEASED ON WATERDEEP )--------+\n','\n',char(10)),'dupecheck.doc.guide',replace('@database Professional Dupechecker By HiFLY / The ViKiNGS\n\nCopyright (C) 1994 HiFLY / The ViKiNGS\nAll Rights Reserved\n\n@remark $VER: Professional DupeChecker V1.o (Mar 05 1994, 00:00:00)\n@remark AmigaGuide for Professional DupeChecker V1.o by HiFLY \n\n@Width 72\n\n@Node Main "The Vikings presents professional dupechecker by HiFLY^TTT"\n@Next Introduction\n                      .\n     __.       . __.   :   . __.     __.     __.\n   ./  |___.   :/  |___¦   :/  l___./  l__ ./  l__\n T ¦   |  ¬¦   |   |  ¬|   |   _   |   _ ¬\¦   _ ¬\::::.. .   .  .\n   |   !   |   ¦   |   |   ¦   !   |   ¦   ¦   ¦   |<\>--- ----- -  ---</>\n H |   |   |   |   ¯  _|   |   |   |   |   |   |   |\n   |   |   |   !   _  \_   !   |   |  _!___¦   l___| PRESENTS  \n E |   |   |   |   |   :   |   |   ¦  \__  |____   |\n   ¦   |   ¦   ¦   |   ¦   ¦   ¦   |   ¦   |   |   | PROFESS¡ONAL \n   :   |   |   |   |   |   |   |   |   |   |   |   | dUPECHECKER V1.o\n   |   |   |   ¦   |   |   |   |   |   |   |   |   | \n   |   |   ¦   |   |   ¦   |   |   |   |   |   |   | COdEd BY HiFLY^TTT   \n   ¦   |   ·   !   |   |   ¦   |   |   !   |   !   |\n   |       |   |   |   |   |   |   |       ¦       |</>------- ---- - -<\>\n   `-------''   ¦---^---¦   :---^---^-------^-------''sN!::··  · ·  ·  ·\n\n        @{"[÷]     Introduction     [÷]" Link Introduction}       @{"[÷]     Requirements     [÷]" Link Requirements}\n        @{"[÷]     Installation     [÷]" Link Install}       @{"[÷]      Greetings!      [÷]" Link Greetings}\n        @{"[÷]     The V¡K¡NGS!     [÷]" Link members}       @{"[÷]     Beta-sites!      [÷]" Link Beta}\n        @{"[÷]      Error list      [÷]" Link error}       @{"[÷]       History        [÷]" Link History} \n@EndNode\n\n@Node Introduction "Introduction"\n@Next Requirements\n@Prev Main\n@Toc Main\n+-( Introduction )---------------------------------------------------------+\n\n This door makes a dupecheck so that no old files can be uploaded again. \n  \n                  Not special advanced but useful.\n\n+--------------------------------------------------------------------------+\n@EndNode\n\n@Node Requirements "Requirements"\n@Next Install\n@Prev Introduction\n@Toc Main\n+-( Requirements )--------------------------------------------------------+\n\n        The following is needed to run professional dupechecker :\n\n     <> A fully installed amiexpress v3.20+\n        NOTE: This may work on the 2.xx series but haven''t been tested.\n  \n     <> A amiga-model (A500/A600/A1200/A2000/A3000/A4000)\n        With kickstart 2.04+\n \n     <> A fully installed and running workbench.\n \n        This utility is hard tested on :\n \n     <> A1200 68020 14mhz With 2 Meg Ram\n     <> A1200 68020 28mhz With 6 Meg Ram\n     <> A2000 68040 33mhz With 6 Meg Ram\n     <> A3000 68030 25mhz With 8 Meg Ram\n\n+-------------------------------------------------------------------------+\n@EndNode\n\n@Node Install "Installation"\n@Next Greetings\n@Prev Requirements\n@Toc Main\n+-( Installation )--------------------------------------------------------+\n\n            Copy the files suppled with this package. \n		Into "DOORS:HiFLY^TTT/DUPECHECK/"\n                    Use the suppled icon.\n\nICON STUFF:\n\nDOOR:HIFLY^TTT/DUPECHECK/DUPECHECK.INFO\n\nadd like this:\n\nRECOMMENDED OPTION			COMMENT\n==================			=======\n\nMEM_SIZE=XXXXX			; The size that you would like to use to \n				; speed up the scan. If you don''t have \n				; the memory, it will run on 5000 bytes. \n				; Public memory. Test what size is best\n				; on your system. If you have a fast hard-\n				; drive have little memory.\n\nMEM_TYPE=XXXXX			; This is the option where you can select \n				; memory type.\n				; FAST is Fast-Memory\n				; CHIP is Chip-Memory\n				; PUBLIC is Public-Memory\n				; Recommended PUBLIC unless you have alot \n				; of free FastMem\n\nTOP_TEXT=XXXX			; Show a text file before the dupecheck\n				; should be placed in "HIFLY^TTT/DUPECHECK/"\n				; Name max 16 letters\n\nEND_TEXT=XXXX			; Show a text file after the dupecheck if\n				; it passes the test.\n				; should be placed in "HIFLY^TTT/DUPECHECK/"\n				; Name max 16 letters\n\nCLEAR_SCREEN			; Clear screen before scaning\n\nDELETE_DUP			; Delete duplicate file.\n\nMAIL_SYSOP			; Mail the sysop to let him know that the \n				; file where a duplicate.\n\nFRONT_DOOR			; Run a door before checking for duplicates.\n				; Place the icon called "FRONTDOOR" in \n				; "BBS:COMMANDS/SYSCMD/"\n\nNEXT_DOOR			; Run 10 doors after checking for duplicates.\n				; Place the icon called "NEXTDOOR0" to \n				; "NEXTDOOR9" in "BBS:COMMANDS/SYSCMD/"\n				; NEXTDOOR0 will run first.\n				; To be able to have this option you must\n				; have selected NDOORS.\n				; Will only run if the file is not a \n				; duplicate.\n\nNDOORS=X                        ; How many doors you want to run after \n                                ; the check if it not failed. max = 9  \n                                ; The door must be named "NEXTDOORx"\n                                ; located in "BBS:COMMANDS/SYSCMD/"\n                                ; the "x" stands for the number of the door\n\nSKIP_ACCESS=XXX			; Lowest access level for skiping dupelicate\n				; check.\n\n\n\n	   Run the converter suppled with this package\n\nMAKE SURE YOU HAVE AEDOOR.LIBRARY IN LIBS: OR ELSE THIS SKIT WILL GURU!!!\n\n	If You Don''t Know How, Quit The Board-Running Scene.\n\n+-------------------------------------------------------------------------+\n@EndNode\n\n@Node Greetings "Greetings"\n@Next MEMBERS\n@Prev Install\n@Toc Main\n+-( Greetings )-----------------------------------------------------------+\n\nPRINCIP/INSANE  	SNIPER/INSANE		VEGAS/OUTLAWS\nSWERX/FODA		OMNIBUZ/REBELS		LOGIC/REBELS\nSCUMBAG/INSANE		ANDROID/TALENT		SHANE/INSANE\nREMO/MYSTIC		CYBERPUNK/M12		BISCROK/OUTLAWS\nBOBO/MYSTIC		BIGWIG/INSANE		FIREFOX/INANE\nTWINS/PHENOMENA		CRUGER/SKID ROW		MR.COKE/SUNSHINE\nAGAMEMON/M22		ZEPHYR/VIKINGS		NERO/PARADOX/VIKINGS\nEZCO/??                 TANGO/DUPLO		AQUARIUS/OUTLAWS\nCROCODILE/PARADOX       LEATHERMAN/2ooo AD	WARHAMMER/ALPHA FLIGHT\nDALAMAR/LED             BOROMIR/TRSI/2ooo AD	\n\n  And to all ViKiNGS mebers and to some that we forgotten...\n\n+-------------------------------------------------------------------------+\n@endnode\n\n@Node members "Current Members Of The V¡k¡ngs"\n@Next beta\n@Prev Greetings\n@Toc Main\n+-( Current Members Of The V¡K¡NGS )--------------------------------------+\n\n	SWEDEN:\n        -----------------------------------------------------\n	SHARK   	-	World Organizor,Sysop,Trainer\n	WAVEFRONT	-	World Organizor,Trader\n	ZEPHYR		-	Trader,Ascii	\n	CRUZ		-	Trader,Ascii\n	NERO		-	Sysop\n	TTT	   	-	/X-Coder, Sysop, Trader\n	HIFLY   	-	/X-Coder, Sysop, Trader\n        -----------------------------------------------------\n	DANMARK:\n	-----------------------------------------------------\n	D-SIYA		-	Trader,Cracker\n        -----------------------------------------------------\n	HOLLAND:\n        -----------------------------------------------------\n	DEATHNIGHT	-	Trader,Sysop\n        +---------------------------------------------------+\n\n	+-( Our Current Boards )----------------------------+\n	SWEDEN  :\n        -----------------------------------------------------\n	PALLADIUM #1	  +46-2-PRI-VAT-E	16k8	WHQ\n	PALLADIUM #2	  +46-2-PRI-VAT-E	16k8	WHQ\n       	PROPHETS HOLD #1  +46-4-PRI-VAT-E	14k4	SHQ\n	PROPHETS HOLD #2  +46-4-PRI-VAT-E	14k4	SHQ\n	PROPHETS HOLD #3  +46-4-PRI-VAT-E	14k4	SHQ\n	WATERDEEP #1      +46-8-540-869-28	21k6	SHQ\n	WATERDEEP #2      +46-8-540-613-85 	28k8	SHQ\n        -----------------------------------------------------\n	USA     :\n        -----------------------------------------------------\n	CHAOTIC ENTITY #1 +1-PRI-VAT-E	                USHQ\n	CHAOTIC ENTITY #2 +1-PRI-VAT-E	                USHQ\n	CHAOTIC ENTITY #3 +1-PRI-VAT-E	                USHQ\n	CHAOTIC ENTITY #4 +1-PRI-VAT-E	                USHQ\n        -----------------------------------------------------\n	HOLLAND :\n        -----------------------------------------------------\n	WORLD OF ELITE #1 +31-PRI-VAT-E		        EHQ\n	WORLD OF ELITE #2 +31-PRI-VAT-E			EHQ\n	WORLD OF ELITE #3 +31-PRI-VAT-E			EHQ\n\n+-------------------------------------------------------------------------+\n@endnode\n@Node beta "Beta-Sites"\n@Next error\n@Prev members\n@Toc Main\n+-( Beta-Sites )----------------------------------------------------------+\n\n	We are looking for more beta sites!! So if you are intrested\n	Call OUR board in sthlm Sweden and talk to HiFLY^TTT\n\n        Current beta-site:\n \n     <> WATERDEEP          +46-(0)8-540-869-28	[2ndz]\n     <> VIOLATOR           +46-(0)4-761-665-6	[1ndz]\n     <> SEPENT HILL        +46-(0)8-580-345-48	[2ndz]\n     <> THE REPTILE''S HOLE +46-(0)2-801-410-1   [2ndz]\n\n+-------------------------------------------------------------------------+\n@endnode\n\n@Node error "Error list"\n@Prev beta\n@Next history\n@Toc Main\n+-( Error-List )----------------------------------------------------------+\n\nSome error ??? check why. \n\n The complete error list\n+-----------------------+\n##      Comment\n--      -------\n#1	Couldn''t open Icon.Library\n#2	Make sure to create "Doors:HiFLY^TTT/DUPECHECK/DUPECHECK.INFO"\n#3	Make sure to run the converter again. A HiFLY^TTT.DUPE is missing.\n#4	Couldn''t open source file\n#5	Couldn''t open mailstats file\n#6	Couldn''t open headerfile\n#7	Couldn''t lock msgbase\n#8	Not enough memory\n#9.x	Couldn''t lock "BBS:COMMANDS/SYSCMD/NEXTDOORx.INFO"\n\n+-------------------------------------------------------------------------+\n@endnode\n@Node history "History"\n@Prev error\n@Next main\n@Toc Main\n+-( History )-------------------------------------------------------------+\n\nThe history of this door\n\n\nV1.o First release version\n                                - Include\n                                  -------\n                                  * Mem-type selection option\n                                  * Mem-location selection option\n                                  * Top-text file option\n                                  * End-text file option\n                                  * Clearscreen option\n                                  * Delete duplicate option\n                                  * MailSysop option\n                                  * Front-door option\n                                  * Next-door option\n                                  * Sysop skip option\n\n+-------------------------------------------------------------------------+\n@endnode\n','\n',char(10)),'{"TYPE":"XXXXX","ACCESS":"XXX"}','auto-added',18573,1,0,NULL,NULL,'tvk_dc1','scan',1780048813);
INSERT INTO door_catalog VALUES('tvk_di1','TVK-DI1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TVK-DI1.LHA','dateit','XIM','dateit',NULL,'HiFLY^TTT','TVK','____  __\_  \__. /\__\   \___ ______ _______ \   \/   /_ /  |/   /_\  /  _\   _  \_  ___/ \      / \/\  /   /   \/\  / \__/___/__  \',replace('        ____         ____                   \n____  __\_  \__. /\__\   \___ ______ _______\n\   \/   /_ /  |/   /_\  /  _\   _  \_  ___/\n \      / \/\  /   /   \/\  / \__/___/__  \ \n  \    /    /  _   \     / /   /\_   \ /   \\n   \__/|___/|___\   \___/_/   /______/_____/\n        Presents \___\   /____\  /___/SyK!  \n+-( PROFESSIONAL DATEIT v1.o By HiFLY^TTT )+\n| The most configurable Dizdater available |\n|        Features many cool options        |\n+---------( RELEASED ON WATERDEEP )--------+\n','\n',char(10)),'dateit.doc.guide',replace('@database Professional DateIt By HiFLY / The ViKiNGS\n\nCopyright (C) 1994 HiFLY / The ViKiNGS\nAll Rights Reserved\n\n@remark $VER: Professional Dateit V1.o (Mar 05 1994, 00:00:00)\n@remark AmigaGuide for Professional Dateit V1.o by HiFLY \n\n@Width 72\n\n@Node Main "The ViKiNGS Presents Professional DateIt By HiFLY^TTT"\n@Next Introduction\n                      .\n     __.       . __.   :   . __.     __.     __.\n   ./  |___.   :/  |___¦   :/  l___./  l__ ./  l__\n T ¦   |  ¬¦   |   |  ¬|   |   _   |   _ ¬\¦   _ ¬\::::.. .   .  .\n   |   !   |   ¦   |   |   ¦   !   |   ¦   ¦   ¦   |<\>--- ----- -  ---</>\n H |   |   |   |   ¯  _|   |   |   |   |   |   |   |\n   |   |   |   !   _  \_   !   |   |  _!___¦   l___| PRESENTS  \n E |   |   |   |   |   :   |   |   ¦  \__  |____   |\n   ¦   |   ¦   ¦   |   ¦   ¦   ¦   |   ¦   |   |   | PROFESS¡ONAL \n   :   |   |   |   |   |   |   |   |   |   |   |   | DateIt V1.o\n   |   |   |   ¦   |   |   |   |   |   |   |   |   | \n   |   |   ¦   |   |   ¦   |   |   |   |   |   |   | COdEd BY HiFLY^TTT   \n   ¦   |   ·   !   |   |   ¦   |   |   !   |   !   |\n   |       |   |   |   |   |   |   |       ¦       |</>------- ---- - -<\>\n   `-------''   ¦---^---¦   :---^---^-------^-------''sN!::··  · ·  ·  ·\n\n        @{"[÷]     Introduction     [÷]" Link Introduction}       @{"[÷]     Requirements     [÷]" Link Requirements}\n        @{"[÷]     Installation     [÷]" Link Install}       @{"[÷]      Greetings!      [÷]" Link Greetings}\n        @{"[÷]     The V¡K¡NGS!     [÷]" Link members}       @{"[÷]      Betasites!      [÷]" Link Beta}\n        @{"[÷]      Error list      [÷]" Link error}       @{"[÷]       History        [÷]" Link History} \n@EndNode\n\n@Node Introduction "Introduction"\n@Next Requirements\n@Prev Main\n@Toc Main\n\n+-( Introduction )---------------------------------------------------------+\n	\n This door makes a line after the user tag-line in the file-list with \n diffrent infos. \n  \n                  Not Special Advanced But Useful.\n\n+--------------------------------------------------------------------------+\n\n@EndNode\n\n@Node Requirements "Requirements"\n@Next Install\n@Prev Introduction\n@Toc Main\n\n+-( Requirements )--------------------------------------------------------+\n\n        The following is needed to run professional dateit :\n\n     <> A fully installed amiexpress v3.20+\n        NOTE: This may work on the 2.xx series but haven''t been tested.\n  \n     <> A amiga-model (A500/A600/A1200/A2000/A3000/A4000)\n        With kickstart 2.04+\n \n     <> A fully installed and running workbench.\n \n        This utility is hard tested on :\n \n     <> A1200 68020 14mhz With 2 Meg Ram\n     <> A1200 68020 28mhz With 6 Meg Ram\n     <> A2000 68040 33mhz With 6 Meg Ram\n     <> A3000 68030 25mhz With 8 Meg Ram\n\n+-------------------------------------------------------------------------+\n@EndNode\n\n@Node Install "Installation"\n@Next Greetings\n@Prev Requirements\n@Toc Main\n\n+-( Installation )--------------------------------------------------------+\n\n            Copy The Files Suppled With This Package. \n		Into "DOORS:HiFLY^TTT/DUPECHECK/"\n                    Use The Suppled Icon.\n\nICON STUFF:\n\nDOOR:HIFLY^TTT/DATEIT/DATEIT.INFO.\n\nadd like this:\n\nRECOMMENDED OPTION			COMMENT\n==================			=======\n\nDESIGN=XXXX			; You can select diffrent design\n				; there is 5 diffrent that is shown \n				; below or you can select RAND\n				; and the computer will randomise\n				; from the lines below 1-5 on every\n				; file that have been uploaded.\n\nCLEAR_SCREEN			; Clears the screen before starting main\n				; door, that means after FRONT_DOOR\n\nDESIGN\n======\n\n1		"-[TiME:19.35 - Nø:0 - Dæ:Sun/30/Oct - 1994]- "\n\n2		" ]-« NoDE [0] »« 19:43 »« 30 Of Oct 1994 »-[ "\n\n3		"- * - 30 oF Oct - * - Nø:0 - * - 19:33 - * - "\n\n4		"  _/\_NoDE [0]_/\_19.32_/\_TiMe [19.32]_/\_  "\n\n5		"-( Sun [] 30 [] Oct [] 1994 )-( ON NODE 0 )- "\n\n\nMAKE SURE YOU HAVE AEDOOR.LIBRARY IN LIBS: OR ELSE THIS SKIT WILL GURU!!!\n\n	If You Don''t Know How, Quit The Board-Running Scene.\n\n+-------------------------------------------------------------------------+\n\n@EndNode\n\n@Node Greetings "Greetings"\n@Next MEMBERS\n@Prev Install\n@Toc Main\n\n+-( Greetings )-----------------------------------------------------------+\n\nPRINCIP/INSANE  	VEGAS/OUTLAWS\nSWERX/FODA		OMNIBUZ/REBELS		LOGIC/REBELS\nSCUMBAG/INSANE		ANDROID/TALENT		SHANE/INSANE\nREMO/MYSTIC		CYBERPUNK/M12		BISCROK/OUTLAWS\nBOBO/MYSTIC		BIGWIG/INSANE		FIREFOX/INSANE\nTWINS/PHENOMENA		CRUGER/SKID ROW		MR.COKE/SUNSHINE\nAGAMEMON/M22		EZCO/??			TANGO/DUPLO\nAQUARIUS/OUTLAWS	LEATHERMAN/2ooo AD	WARHAMMER/ALPHA FLIGHT\nDALAMAR/LED 		BOROMIR/TRSI/2ooo AD	CROCODILE/PDX/FLT\nZEPHYR/VIKINGS 		NERO/PDX/TVK		SNIPER/INSANE\nDEMAX/DELIGHT\n\n  And to all ViKiNGS mebers and to some that we forgotten...\n\n+-------------------------------------------------------------------------+\n\n@endnode\n\n@Node members "Current Members Of The V¡k¡ngs"\n@Next beta\n@Prev Greetings\n@Toc Main\n\n+-( Current Members Of The V¡K¡NGS )--------------------------------------+\n\n	SWEDEN:\n        -----------------------------------------------------\n	SHARK   	-	World Organizor,Sysop,Trainer\n	WAVEFRONT	-	World Organizor,Trader\n	ZEPHYR		-	Trader,Ascii	\n	CRUZ		-	Trader,Ascii\n	NERO		-	Sysop\n	TTT	   	-	/X-Coder, Sysop, Trader\n	HIFLY   	-	/X-Coder, Sysop, Trader\n        -----------------------------------------------------\n	DANMARK:\n	-----------------------------------------------------\n	D-SIYA		-	Trader,Cracker\n        -----------------------------------------------------\n	HOLLAND:\n        -----------------------------------------------------\n	DEATHNIGHT	-	Trader,Sysop\n        +---------------------------------------------------+\n\n	+-( Our Current Boards )----------------------------+\n	SWEDEN  :\n        -----------------------------------------------------\n	PALLADIUM #1	  +46-2-PRI-VAT-E	16k8	WHQ\n	PALLADIUM #2	  +46-2-PRI-VAT-E	16k8	WHQ\n       	PROPHETS HOLD #1  +46-4-PRI-VAT-E	14k4	SHQ\n	PROPHETS HOLD #2  +46-4-PRI-VAT-E	14k4	SHQ\n	PROPHETS HOLD #3  +46-4-PRI-VAT-E	14k4	SHQ\n	WATERDEEP #1      +46-8-540-869-28	21k6	SHQ\n	WATERDEEP #2      +46-8-540-613-85 	28k8	SHQ\n        -----------------------------------------------------\n	USA     :\n        -----------------------------------------------------\n	CHAOTIC ENTITY #1 +1-PRI-VAT-E	                USHQ\n	CHAOTIC ENTITY #2 +1-PRI-VAT-E	                USHQ\n	CHAOTIC ENTITY #3 +1-PRI-VAT-E	                USHQ\n	CHAOTIC ENTITY #4 +1-PRI-VAT-E	                USHQ\n        -----------------------------------------------------\n	HOLLAND :\n        -----------------------------------------------------\n	WORLD OF ELITE #1 +31-PRI-VAT-E		        EHQ\n	WORLD OF ELITE #2 +31-PRI-VAT-E			EHQ\n	WORLD OF ELITE #3 +31-PRI-VAT-E			EHQ\n\n+-------------------------------------------------------------------------+\n\n@endnode\n@Node beta "Beta-Sites"\n@Prev members\n@Toc Main\n\n+-( Beta-Sites )----------------------------------------------------------+\n\n	We are looking for more beta sites!! So if you are intrested\n	Call OUR board in sthlm Sweden and talk to HiFLY^TTT\n\n        Current Beta-Site:\n \n     <> WaterDeep BBS      +46-(0)8-540-869-28	[2ndz]\n     <> VIOLATOR	   +46-(0)4-761-665-6	[1ndz]\n     <> SEPENT HILL	   +46-(0)8-580-345-48	[2ndz]\n     <> THE REPTILE''S HOLE +46-(0)2-801-410-1   [2ndz]\n\n+-------------------------------------------------------------------------+\n\n@endnode\n@Node error "Error list"\n@Prev beta\n@Next history\n@Toc Main\n+-( Error-List )----------------------------------------------------------+\n\nSome error ??? check why. \n\n The complete error list\n+-----------------------+\n##      Comment\n--      -------\n#1	Couldn''t open Icon.Library\n#2	Make sure to create "Doors:HiFLY^TTT/DATEIT/DATEIT.INFO"\n\n+-------------------------------------------------------------------------+\n@endnode\n@Node history "History"\n@Prev error\n@Next main\n@Toc Main\n+-( History )-------------------------------------------------------------+\n\nThe history of this door\n\n\nV1.o First release version\n                                - Include\n                                  -------\n                                  * Clearscreen option\n                                  * Five diffrent designs option\n\n+-------------------------------------------------------------------------+\n@endnode','\n',char(10)),NULL,'auto-added',19291,10,0,NULL,NULL,'tvk_di1','scan',1780048813);
INSERT INTO door_catalog VALUES('tvk_lc1','TVK-LC1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TVK-LC1.LHA','LhaChecker','XIM','LhaChecker',NULL,'HiFLY^TTT+','TVK','____  __\_  \__. /\__\   \___ ______ _______ \   \/   /_ /  |/   /_\  /  _\   _  \_  ___/ \      / \/\  /   /   \/\  / \__/___/__  \',replace('        ____         ____                   \n____  __\_  \__. /\__\   \___ ______ _______\n\   \/   /_ /  |/   /_\  /  _\   _  \_  ___/\n \      / \/\  /   /   \/\  / \__/___/__  \ \n  \    /    /  _   \     / /   /\_   \ /   \\n   \__/|___/|___\   \___/_/   /______/_____/\n        Presents \___\   /____\  /___/SyK!  \n+PROFESSIONAL LHA-CHECKER v1.o By HiFLY^TTT+\n|  The most configurable checker available |\n|        Features many cool options        |\n+---------( RELEASED ON WATERDEEP )--------+\n','\n',char(10)),'LhaChecker.doc',replace('                       .\n     __.       . __.   :   . __.     __.     __.\n   ./  |___.   :/  |___¦   :/  l___./  l__ ./  l__\n T ¦   |  ¬¦   |   |  ¬|   |   _   |   _ ¬\¦   _ ¬\::::.. .   .  .\n   |   !   |   ¦   |   |   ¦   !   |   ¦   ¦   ¦   |<\>--- ----- -  ---</>\n H |   |   |   |   ¯  _|   |   |   |   |   |   |   |\n   |   |   |   !   _  \_   !   |   |  _!___¦   l___| PRESENTS  \n E |   |   |   |   |   :   |   |   ¦  \__  |____   |\n   ¦   |   ¦   ¦   |   ¦   ¦   ¦   |   ¦   |   |   | PROFESS¡ONAL \n   :   |   |   |   |   |   |   |   |   |   |   |   | LhaChecker v1.o\n   |   |   |   ¦   |   |   |   |   |   |   |   |   | \n   |   |   ¦   |   |   ¦   |   |   |   |   |   |   | COdEd BY HiFLY^TTT   \n   ¦   |   ·   !   |   |   ¦   |   |   !   |   !   |\n   |       |   |   |   |   |   |   |       ¦       |</>------- ---- - -<\>\n   `-------''   ¦---^---¦   :---^---^-------^-------''sN!::··  · ·  ·  ·\n\n	\nAgain another professional utility from HiFLY^TTT / ThE ViKiNGS.\n\nOk, how many LhaCheckers is there availble today? I''d say about 50-100?\nSo what the heck have we made yet another one? Simple, it''s not just fast\nit''s very safe and configurable. How many times haven''t you seen this when\na 4.5mb lha file have been uploaded "Volume RAM DISK is full" ???\n\nWell, as I said, our LhaChecker is configurable, you may set the WORK\ndirectory to SYS: or whatever you like.\n\nProfessional LhaChecker can also show the File_Id, very nice to have\nwhen you''re working in Shell, and you may also add a Line into the File_id\nfor BBS Commercial usage or whatever.\n\nADDING, CHECKING and REMOVING can each be turned ON/OFF.\n\nAnd a new feature is that it can execute another script before executing\nitself. Total support for Illegal Stripper etc...\n\n\nLhaChecker.info:\n\nADD=YES/NO\n\nSTRIP=YES/NO\n\nCHECK=YES/NO\n\nWORK=DH0:\n\nSCRIPT=bbs:scripts/ISTRIP.batch\n\nSHOW_FILEID=YES/NO\n\nFILEID_ADD=  [- This File Was First On wATERDEEP -]\n\n\n\nSoon to come:		Random choosed ADDYS to insert.\n			It will make them very hard to strip and your\n			commercial will spread like never before.\n\n			Ability to strip commercial in File ID''s.\n\n			Select files to check via ASL requesters.\n','\n',char(10)),NULL,'auto-added',20110,10,0,NULL,NULL,'tvk_lc1','scan',1780048813);
INSERT INTO door_catalog VALUES('tw12','TW12.LZH','~/Code/amiexpress_doors/Archives/AmiExpress/TW12.LZH',NULL,'XIM','TradeWars',NULL,NULL,NULL,NULL,replace('TradeWars\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 20:40:18  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,NULL,35386,2,0,NULL,NULL,NULL,'scan',1780048813);
INSERT INTO door_catalog VALUES('twc326','TWC326.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TWC326.LHA','TWC','XIM','TWC',NULL,NULL,NULL,NULL,replace('TWC III is ShareWare\n','\n',char(10)),'TWC.guide',replace('@database TWC.guide\012@master "TWC.guide"\012@author "Lutz Vieweg"\012@(c) "Copyright © 1993 Lutz Vieweg"\012@$VER: TWC.guide 1.1\012\012@node Main "TWC ]I[  - the ultimate bidirectional transfer tool"\012\012          #########  ###       ###    ######\012          #########  ###       ###   ########\012            ###     ###  ###  ###  ###    ###\012            ###     ###  ###  ###  ###        \012           ###     ###  ###  ###  ###           ]I[\012           ###     ###  ###  ###  ###         \012          ###     ###  ###  ###  ###    ###\012          ###     #############   ########\012         ###      ###########     ######   by Lutz Vieweg\012\012                  -*- MANUAL -*-\012\012Topics of this manual:\012----------------------\012\012 @{"What is TWC?" link Whatis} And why use it?\012 @{"Requirements" link Require} - what you need to run TWC\012\012 @{"Quickstart" link Quickstart} - a short guide to your first transfer\012\012 @{"Reference" link Details} with detailed information on any function\012  Invocation from @{"CLI" link CLI}\012  Invocation from @{"Workbench" link WB}\012  @{"Project" link Proj}  menu/gadget/ARexx functions\012  @{"Function" link Func} menu/gadget/ARexx functions\012  @{"Setup" link SetupScreen} details\012   @{"Screen" link SetupScreen} setup\012   @{"Serial" link SetupSerial}-device setup\012   @{"Modem" link SetupModem} setup\012   @{"Files" link SetupFile} setup\012   @{"Protocol" link SetupProtocol} setup\012   @{"Process" link SetupProcess} setup\012   @{"Notification" link SetupNotification} setup\012   @{"Audio" link SetupAudio} setup\012   @{"Misc" link SetupMisc} setup\012  @{"ARexx" link ARexx} specific commands\012\012 @{"Problems" link Problems} and possible solutions\012\012 @{"Copyright" link Copyright} and how to register TWC\012 @{"Credits" link Credits} to helpful people\012\012 @{"Programmers" link Pgm} info\012 \012 @{"Version" link Version} history\012\012 @{"Future" link Future} extensions, just wanna-be''s\012\012IMPORTANT NOTE TO ALL WHO HAVE BEEN USING TWC 2.06 BEFORE:\012TWC III is not just another version of TWC, it''s a complete\012rewrite. Not much is the same as before. TWC III is incompatible\012to versions < 3.\012\012@endnode\012\012@node Whatis "What is TWC???"\012\012If you''ve got a modem, you''ll sometimes want to exchange data with\012others using it. You can do this with many tools, but they all have\012their drawbacks. TWC hasn''t. :)\012\012Most other communication software is designed for calling "Bulletin-\012Board-Systems", this is not what TWC has been made for. TWC is\012meant to be the ultimate utility when you want to call another\012TWC-user, just to exchange some data and chat with him...\012\012A short list of features TWC provides (don''t mind if you don''t\012understand some of theese, you can benefit from them without knowing)\012\012- Extreme reliability and system-friendlyness\012- Full bidirektional transfer of files, chat-text (and soon even more),\012  can save you up to 50% time and phone-bill\012- High transfer rates, performs well on bad lines, where other protocols\012  sucks with permanent resends\012- Low CPU-time usage even at high transfer-rates, example: Bidirectional\012  transfer at 2200+2200=4400cps on an A3000 takes approx. 11% CPU time\012- Comfortable, font-sensitive GUI\012- Multi-threaded program structure, asynchronus GUI, disk I/O etc...\012\012@endnode\012\012@node Require "Requirements - what you need to enjoy TWC"\012\012To run TWC you''ll need the following things:\012\012- An Amiga running KS 2.04 or newer\012\012- A modem featuring at least one real ''Full Duplex'' transmission standard.\012  If you don''t know whether your modem fits, just try it - most modern\012  modems are suitable.\012  \012  Some bidirectional modulation schemes are:\012  \012  V.22, V.22bis, Bell 212A, Bell 103, V.21, V.32,\012  V.32bis, V.32terbo, V.fast\012  \012  The following modulation methods are definitely _not_ advisable to\012  be used with TWC:\012  \012  V.23, USR HST, Telebit PEP, Telebit PEP+\012  \012  If you''ve got a modem which normally uses one of theese,\012  make sure to switch to a suitable modulation method with\012  your initialisation command.\012  \012- Your modem has to be connected to your computer with a so-called\012  "7-Wire" cable. That means, RTS/CTS handshake has to be possible.\012  The "carrier detect" (CD) wire has also to be connected.\012  Modern high-speed modems are connected with such cables in general.\012\012@endnode\012\012@node Quickstart "Quickstart - how to make your first connection"\012\012Little things have to be done to enjoy your first connection\012with TWC. If you''ve got a partner on the phone, who also\012has a copy of TWC, you might try a real transfer. If you\012want to test out TWC alone, you can also do that, just read on.\012\012Start TWC - now. Invokation can be done either by clicking\012on the TWC-Icon at the Workbench, or you may start TWC from\012a CLI or shell by simply typing "TWC" in the directory where\012you have it. If you start TWC from a CLI, and your stack is\012too small, a requester will appear and tell you how to\012change this. You can give TWC filenames as parameters\012either by passing them through the command-line or by\012starting TWC with other Icons selected from WorkBench,\012they''ll be put into the "files-to-send" list on startup.\012\012The first time you start it, TWC will open a 640*256 Hires\012screen, with 4 windows on it (the windows may overlap). If\012you''ve got a hardware that supports larger screens than 640*256,\012the first thing you should is: Browse through the "Setup" menu,\012find the submenu "Screen" and use the commands "Screen Width"\012and "Screen Height" there to adjust the size. Another menu-\012command, "Display ID" allows you to change the mode of the\012screen TWC will open, here are some usual values for this ID:\012\0120x8000 open an ordinary Hires screen\0120x8020 open a  super-Hires screen\0120x8004 open an interlaced Hires screen\0120x8024 open an interlased super-Hires screen\012\012(For more information on further display-id''s refer to the\012 C= include-file "graphics/displayinfo.h")\012\012All TWC screen-settings apply only at invocation time,\012so you should leave TWC now by clicking the "Quit" Gadget,\012and starting it again. Whenever you leave TWC, it will\012write its settings back to disk, by default to a file\012called "TWC_setup" in the same directory where TWC is.\012So make sure TWC can write to this directory.\012\012... click @{"next page" link Setup}\012\012@endnode\012\012@node Setup "Visit the setup-menu"\012\012Once you''re satisfied with the screen, you may arrange the windows\012at it as you like. Two of them are resizeable - to take advantage\012from larger screens...\012\012Remember, all the changes you make are stored in the setup-file\012when you leave TWC.\012\012Now visit the setup-menu again, and call each of its commands\012one after each other. If you don''t know what a certain value\012is good for, just leave it as it was by default. There are a\012few values where it''s likely you will want to make a change:\012\012Modem/ATA-like command: If you''ve got a modem with the german\012  "BTZ" you may have bad luck: Some of them are unable to\012  switch from voice to data mode online, so you''ll have\012  to config your modem to answer an incoming call automatically,\012  please refer to the modem''s manual\012\012Modem/ATD-like command: Some modems are dropping the line\012  soon when you give an ATD command... a solution may be\012  using ATX0D instead, but please read your modem''s manual\012  on this topic when in doubt...\012\012Serial/Baudrate: Adjust this value for your modem. Most modern\012  modems support fixed baudrates, 2400, 9600, 19200, 38400 etc. -\012  the default value here is 19200 which is suitable for the\012  majority of modems nowadays, but you may need to change this,\012  for example, if you''ve got only a lousy 2400bps modem...\012  please refer to the manual of your modem.\012\012You may also want to change the default paths for incoming\012and outgoing files, but all the other settings are not that\012important by now.\012\012... click @{"next page" link Connect}\012\012@endnode\012\012@node Connect "Now establish the connection"\012\012When you''ve gone through the little setup, you may now\012actually make your first connection. When you''ve got\012a partner on the phone-line, he should have started\012and setup TWC, too. One of yours should now press the "ATA"-\012Gadget, the other one the "ATD"-Gadget. There should\012come some strange beeping noise from your modems, then,\012and a text like "JUNK> CONNECT 14400" or similar should\012soon appear in the status-window. If not, read the chapter\012"Problems".\012\012If you don''t have a partner on the phone to test TWC,\012you may test it all alone. Use the "Modem/Chat" radio\012buttons to switch to "Modem" mode. Give your modem\012the command to enter "loopback-test-mode", this command\012is "AT&T1" at many modems. The modem should then connect\012with itself, and everything you send will be mirrored back\012to you. This way, you can transfer data to yourself...\012\012Once the connection is established, you can start sending\012your partner what you like. Make sure the "Modem/Chat"\012radio-buttons indicate "Chat". Just type something on\012the keyboard. The text you type should appear in the string\012requester at the "Connect-Panel". When you hit the RETURN-\012key, the text in the requester is send to your partner.\012A copy is also shown in your "Chat History". Messages\012from your partner are preceded with a "> " and also shown\012in the "Chat History".\012\012Once you''ve chatted enough, try a file transfer. Just click\012the "Add" Gadget in the "TWC Transfer Panel", a file requester\012will appear and you can select one or more files to be send.\012After you''ve made your choice, the files you selected will\012be listed in the "TWC Transfer Panel". The transfer of those\012files to your partner does not immedietly start. It actually\012starts when you click the "START" Gadget. Once you''ve\012started the transfer, it will continue until the connection\012is closed, or you hit the "ABORT Sending" Gadget. To abort\012a transfer that comes from your partner, you may click "ABORT\012Reception".\012\012If you start a file transfer with TWC, and the receiver has\012already a file of that name, which is shorter than your''s,\012TWC will assume you want to resume a former interrupted\012transfer. \012\012Now try the feature that''s the main difference between TWC\012and other communication software: You may continue to chat\012while you exchange files with your partner, you may select\012more files to be send, and file transmission goes in both\012directions at the same time which effectively doubles\012the transfer-rate.\012\012... click @{"next page" link Funny}\012\012@endnode\012\012@Node Funny "More funny features available"\012\012Here are  additional functions you may use when you''re connected:\012\012Connect Panel / Hang Up: Hitting this button drops the DTR\012  outlet of your serial port, causing the modem to go on-hook.\012  If you modem does not hang up when you click this Gadget,\012  please make a change in your modems configuration, refer\012  to your modem''s manual for more information on the DTR-behaviour.\012\012Connect Panel / Ring Other: If your partner does something\012  in the background while you''re transferring files, and\012  you want him to listen, click the "Ring Other" Gadget.\012  The TWC-screen on his computer will then get into front,\012  and a "display-beep" announces your call for attention.\012\012... click @{"next page" link Quit}\012\012@endnode\012\012@node Quit "How to get rid of TWC"\012\012Assumed the inpropable case you want to leave TWC, you''ve the\012choice how to do this: The normal way is clicking the "Quit"\012Gadget or the close-Gadget of the "Connect Panel". Everything\012is smoothly abandoned, then. A more brutal way to leave TWC\012is sending it a BREAK signal, for example by pressing CTRL-C\012in the shell or CLI where you started TWC. Well, there should\012be little reason to do it the unusual way.\012\012Remember, unless you''ve registered TWC, TWC will automatically\012quit after approx. 20 minutes.\012\012@endnode\012\012@node Details "Detailed function reference"\012\012The following pages will describe the functions and\012Options of TWC in a more detailed manner. Gadgets, menus\012and related ARexx commands are explained together, if they\012serve a (nearly) identical function.\012\012@endnode\012\012@node CLI "Options when invoking TWC from a CLI or shell"\012\012If you start TWC from the CLI or a shell, you may pass parameters\012to it (all parameters are optional):\012\012TWC [-s <setup-file-name>] [-o <name> <value>] [-x <address>] [-r]\012    [<filename(s)>] \012\012<xxx> are placeholders. The options are:\012\012-s <setup-file-name>\012  You can supply the name of the setup-file TWC should use here. This file\012  may exists or not. TWC will store the setup under the name of the last-read\012  setup-file when exiting.\012\012-o <name> <value>\012  Defines a setup-entry, for a more detailed description see @{"ARexx" link ARexx}\012  command SETUP. You can supply as much -o parameters as you like\012\012-r\012  Tells TWC to startup, but not to allocate a communication port. This may\012  be a good idea if you want to use TWC as an external protocol driver.\012\012-x <address>\012  Allows you to start TWC with an already opened serial port. This may be of\012  interest only to programmers. <address> has to be a pointer to a initialised\012  struct IOExtSer, in decimal or hex (e.g. 49152 or 0xc000)\012\012  IMPORTANT: Don''t use or modify your IOExtSer while TWC uses it.\012             The function "HANGUP" will have no effect when TWC uses an\012             external IOExtSer structure. \012             All serial settings will have no influence when TWC uses an\012             external IOExtSer structure. \012\012<filename(s)>\012  You may pass as much filenames to TWC via the command line as you like, they\012  will appear in the to-send-list.\012\012@endnod\012\012@node WB "Starting TWC from the Workbench"\012\012Just double-click the TWC-icon to start it.\012\012You may also click the TWC icon once, click on other icons once, and\012then on a last icon twice. This will start TWC with the later clicked\012icons in the files-to-send list.\012\012@endnode\012\012@node Proj "Gadget-, menu- and ARexx-functions"\012\012ARexx commands are case-insensitive, parameters are not. <xxx> is a\012placeholder for a parameter supplied with an ARexx command, xxx gives\012a short description of the parameter.\012\012----------------------------------------------------------------------\012Menu  : Project / About TWC\012Gadget: -\012ARexx : -\012\012Displays a short text telling you about the version and the author\012of the TWC you are currently running.\012----------------------------------------------------------------------\012Menu  : Project / Load Setup\012Gadget: -\012ARexx : LOADSETUP <filename>\012\012Resets the current settings to the default-values, then tries to load\012a new setup-file. When TWC exits, and any changes have been made to\012the setup, the setup is written back to the file where it has been\012loaded from.\012\012Note: The setup file TWC uses is human-readable and "human-editable" -\012      you can load it with any text editor and edit it, if you like.\012----------------------------------------------------------------------\012Menu  : Project / Save Setup\012Gadget: -\012ARexx : SAVESETUP <filename>\012\012Stores the current setup into the file you specified. TWC will store\012the setup again under the same name when any changes are made until\012exit.\012----------------------------------------------------------------------\012Menu  : Project / Quit\012Gadget: Quit\012ARexx : QUIT\012\012Exits the program. Of course, all files currently open are closed etc,\012but if transfers are in progress when you quit the program, your\012partners TWC may keep trying to send or receive data, so it''s a good\012idea to end the transfers before you quit.\012----------------------------------------------------------------------\012@endnode\012\012@node Func "Gadget-, menu- and ARexx-functions"\012----------------------------------------------------------------------\012Menu  : Function / Originate (ATD)\012Gadget: ATD\012ARexx : ATD\012\012Sends a command to your modem causing it to go off hook and listen\012to carrier tones from the remote modem. When a connection could be\012established, the modem will answer with a message like "CONNECT 14440"\012or similar, and you''ll then be able to send and receive data to/from\012the remote modem btw. your partner on the other end of the line.\012The command that is send to your modem can be configured with the\012@{"Setup / Modem / ATD-like command" link SetupModem} menu item.\012----------------------------------------------------------------------\012Menu  : Function / Answer (ATA)\012Gadget: ATA\012ARexx : ATA\012\012Sends a command to your modem causing it to go off hook and send\012carrier tones to the phone-line. When a connection could be\012established, the modem will answer with a message like "CONNECT 14440"\012or similar, and you''ll then be able to send and receive data to/from\012the remote modem btw. your partner on the other end of the line.\012The command that is send to your modem can be configured with the\012@{"Setup / Modem / ATA-like command" link SetupModem} menu item.\012\012IMPORTANT:\012- To make a connection, one of the modems on the line has to\012  act as "originator", the other as "answerer". In most cases,\012  it doesn''t matter which is which, but there won''t be any\012  connection if both modems try to originate or answer a call\012- Establishing the connection can take some time, up to 20 seconds.\012  While the modems are trying to connect, strange noise is coming\012  from their speakers. This is entirely normal. Please don''t send\012  any data to the modem while it is trying to connect, it would\012  instantly give up the try.\012----------------------------------------------------------------------\012Menu  : Function / Dial Number\012Gadget: Dial\012ARexx : DIAL <number>\012\012Sends a command to your modem causing it to dial the specified number\012and establish a connection, then some data is sent to the remote\012to identify the caller as TWC. This feature is sort of useless when\012communicating with a human partner, it is meant for future support\012of BBS''es that allow users to login in with TWC.\012The command that preceeds the number to make your modem dial can be\012configured with the @{"Setup / Modem / ATA-like command" link SetupModem} menu item.\012----------------------------------------------------------------------\012Menu  : Function / Hang Up\012Gadget: Hang Up\012ARexx : HANGUP\012\012Closes the connection to the remote modem, the modem will go on hook,\012and all transfers currently in progress will be aborted.\012\012IMPORTANT:\012- Your modem has to close the connection "when DTR drops" - this\012  is a feature available with any modem, but for any reason, your\012  modem might be configured not to do so. If your modem does not\012  go on hook when you initiate a hang up, you should consult your\012  modems manual and adjust the modem initialisation command according\012  to it.\012----------------------------------------------------------------------\012Menu  : Function / Ring other\012Gadget: Ring\012ARexx : RING\012\012Sends a very small data-packet to your partner causing his TWC to\012notify your request for attention.  This is by default done by\012bringing the TWC screen to the front and flashing its background\012color.\012----------------------------------------------------------------------\012Menu  : Function / Add File\012Gadget: Add File\012ARexx : ADDFILE <filename>\012\012Adds a filename to the list of files to be send (which is displayed\012in the window called "transfer panel"). If a connection is established\012and another file has already been sent, TWC will instantly begin the\012transmission. Otherwise, it will remain in the list until the \012transfer is started and all preceding files have been transmitted.\012----------------------------------------------------------------------\012Menu  : Function / Start Transmission\012Gadget: START\012ARexx : START\012\012Starts the transmission of the files in the "to-send"-list. This\012is only possible if a connection is already established. Once\012the transfer is started, all files in the list are transferred\012one after each other until the list is empty. \012----------------------------------------------------------------------\012Menu  : Function / Protocol Status\012Gadget: -\012ARexx : PROTOCOLSTATUS\012\012Diplays some information on the current protocol status in the status\012window.  This is sort of uninteresting to the ordinary user, but it\012might help me to locate a bug if any problems are occuring at\012the transfer...\012----------------------------------------------------------------------\012Menu  : Function / Abort Reception\012Gadget: Reception (below the text "ABORT")\012ARexx : ABORTREC\012\012When your TWC is receiving a file, and you apply this function, the\012sender will be asked to stop the transmission. In general, the sender\012should abort transfer to your TWC then within a few seconds, but if,\012for any reason, the sender does not stop sending, you may apply\012the Abort Reception function a second time, then the reception\012will end immediately, without waiting for sender.\012----------------------------------------------------------------------\012Menu  : Function / Abort Sending\012Gadget: Sending (below the text "ABORT")\012ARexx : ABORTSEND\012\012Stops the transmission of the file your TWC currently sends.\012----------------------------------------------------------------------\012Menu  : Function / Send File as Chat\012Gadget: -\012ARexx : -\012\012Sends the contents of a file to your partners TWC as if you typed\012it into the input line. This feature may sometimes be useful when\012you want to send your partner e.g. the listing of a directory,\012a short readme or alike. The filesize is limited to 10kB.\012----------------------------------------------------------------------\012Menu  : Functions / Send Sound File\012Gadget: -\012ARexx : SENDSOUNDFILE <filename>\012\012Sends the contents of an 8SVX (IFF) sound-file to your partners TWC,\012there it will be played back if sound is enabled. This function is -\012apart from its testing purposes - just a little joke. The sound is\012treated the same way as if it where actually coming from a sampler.\012The same online compression/decompression is applied as it is to\012"voice chat".\012\012IMPORTANT:\012- If the sample rate of your sound divided by the compression factor\012  is higher than the CPS-rate your modems achieve, the sound will\012  be played back with nasty "gaps". See @{"Setup / Sound" link SetupSound} for details.\012----------------------------------------------------------------------\012@endnode\012\012@node SetupScreen "Gadget-, menu- and ARexx-functions"\012\012Note: The placeholder <x|y> means "x or y"\012      Example: <"YES"|"NO"> means provide "YES" or "NO"\012               as parameter\012\012Note: When supplied as parameters, "YES", "Y", "ON" and\012      "NO", "N", "OFF" (all case-insensitive) are synonyms. \012\012----------------------------------------------------------------------\012Menu  : Setup / Screen / Open on PubScreen\012Gadget: -\012ARexx : SETUP "open_GUI_on_public_screen" <"YES"|"NO">\012\012Decides whether TWC should open its GUI on a "public screen"\012rather than on a custom screen.\012\012IMPORTANT:\012- All screen-settings take effect only on startup, quit and\012  restart TWC to apply them.\012----------------------------------------------------------------------\012Menu  : Setup / Screen / PubScreen Name\012Gadget: -\012ARexx : SETUP "public_screen_name" "<name>"\012\012Defines the name of the public screen TWC should open its GUI upon,\012when this is enabled. The default name is "Workbench", that is the\012screen where the workbench, shells etc. resides.\012\012IMPORTANT:\012- All screen-settings take effect only on startup, quit and\012  restart TWC to apply them.\012----------------------------------------------------------------------\012Menu  : Setup / Screen / Screen Width\012Gadget: -\012ARexx : SETUP "screen_width" "<number of pixels>"\012\012Defines the width of the custom screen TWC should open its GUI upon,\012when this is enabled. The default width is -1, this means: The\012standard width that is defined within the preferences tool.\012\012IMPORTANT:\012- All screen-settings take effect only on startup, quit and\012  restart TWC to apply them.\012----------------------------------------------------------------------\012Menu  : Setup / Screen / Screen Height\012Gadget: -\012ARexx : SETUP "screen_height" "<number of pixels>"\012\012Defines the height of the custom screen TWC should open its GUI upon,\012when this is enabled. The default height is -1, this means: The\012standard height that is defined within the preferences tool.\012\012IMPORTANT:\012- All screen-settings take effect only on startup, quit and\012  restart TWC to apply them.\012----------------------------------------------------------------------\012Menu  : Setup / Screen / Display ID\012Gadget: -\012ARexx : SETUP "screen_display_id" "<display id>"\012\012Defines the mode of the custom screen TWC should open its GUI upon,\012when this is enabled. The ID''s possible values may not be known\012to you, here are some examples:\012\0120x8000 open an ordinary Hires screen\0120x8020 open a  super-Hires screen\0120x8004 open an interlaced Hires screen\0120x8024 open an interlased super-Hires screen\012\012I know it is not very comfortable to choose the screen mode\012this way, but KS 2.04 does not know any standard screen-mode\012requester. There may be a requester in future releases of TWC...\012\012IMPORTANT:\012- All screen-settings take effect only on startup, quit and\012  restart TWC to apply them.\012----------------------------------------------------------------------\012@endnode\012\012@node SetupSerial "Gadget-, menu- and ARexx-functions"\012\012----------------------------------------------------------------------\012Menu  : Setup / Serial / Baudrate\012Gadget: -\012ARexx : SETUP "serial_device_baud_rate" "<baudrate>"\012\012Sets the baudrate from your computer to your modem. With all modern\012modems, this baudrate has not to be the same as the rate between\012your modem and the remote modem. Older modems may require the same\012baudrate between the modem and the computer as they use to the\012remote modem.\012Choosing the optimal baudrate to your modem is one of the more easy\012things:  The higher, the better.  When you encounter trouble, lower\012the baudrate.  On 68000-driven Amigas you won''t be able to achieve\012more than 19200 baud to your modem unless you use a non-standard\012serial-device such as the "BaudBandit.device", see below.  On faster\012Amigas, the baudrate should normally be the highest one your modem\012supports. Please consult your modems manual to check for the baudrates\012your modem supports, often used values are: 2400, 9600, 19200, 38400,\01257600, 115200 etc..\012----------------------------------------------------------------------\012Menu  : Setup / Serial / Device\012Gadget: -\012ARexx : SETUP "name_of_serial_device" "<device name>"\012\012Defines the name of the device TWC should open as communication\012channel.  The standard device that drives the Amiga''s serial port is\012called "serial.device" and should reside in your devs:  directory.\012You may use any device with TWC that acts similar to the\012"serial.device".  By now, the only important alternative I know is the\012"BaudBandit.device", which may enable users of slow Amigas to use\012baudrates > 19200.  On faster Amigas, the original "serial.device"\012seems to be the better choice.\012----------------------------------------------------------------------\012Menu  : Setup / Serial / Unit\012Gadget: -\012ARexx : SETUP "serial-device_unit_number" "<unit nr>"\012\012Defines the unit TWC should open the device with. This is important to\012users with multi-serial cards only, if you don''t have such, leave this\012value 0.\012----------------------------------------------------------------------\012Menu  : Setup / Serial / Flags\012Gadget: -\012ARexx : SETUP "serial-device_flags" "<flags>"\012\012Defines the flags TWC should open the device with. If you don''t know\012what this value could be good for, please leave it as it is.\012Advanced Amiga users may for any reason wish to make changes here,\012but don''t expect TWC to run perfectly without flow control...\012----------------------------------------------------------------------\012Menu  : Setup / Serial / Buffer Size\012Gadget: -\012ARexx : SETUP "serial-device_read_buffer" "<buffersize>"\012\012Defines the size of the buffer the serial device provides for incoming\012data. 32768 seems to be a sufficient size, don''t make the buffer too\012small, higher values won''t hurt.\012----------------------------------------------------------------------\012@endnode\012\012@node SetupModem "Gadget-, menu- and ARexx-functions"\012----------------------------------------------------------------------\012Menu  : Setup / Modem / ATA-like command\012Gadget: -\012ARexx : SETUP "ATA-like_modem_command" "<command>"\012\012Defines the command string to be send to your modem when using the\012"ATA"-function. This is, by default, the string "ATA\r\n", the\012"\r" stands for "carriage return", the "\n" for "newline". If you''ve\012got any trouble with the default setting, refer to your modems manual\012for further information, topic "answering calls".\012----------------------------------------------------------------------\012Menu  : Setup / Modem / ATD-like command\012Gadget: -\012ARexx : SETUP "ATD-like_modem_command" "<command>"\012\012Defines the command string to be send to your modem when using the\012"ATD"-function. This is, by default, the string "ATX0D\r\n". If you''ve\012got any trouble with the default setting, refer to your modems manual\012for further information, topic "originating calls".\012----------------------------------------------------------------------\012Menu  : Setup / Modem / Dial command\012Gadget: -\012ARexx : SETUP !!!\012\012Defines the command that should precede the number you supply to the\012dial function. This is, by default, the string "ATD". If you''ve\012got any trouble with the default setting, refer to your modems manual\012for further information, topic "dialing out".\012----------------------------------------------------------------------\012Menu  : Setup / Modem / Initial command\012Gadget: -\012ARexx : SETUP "modem_initialisation_command" "<command>"\012\012Defines the command that should be send to your modem whenever the\012serial device is opened. This is, by default, the string "AT\r\n",\012a command, that does nothing but tell the modem to answer with "OK".\012You might want to insert something meaningful here, to configure\012your modem to work best with TWC. One example: If you''ve got an\012US Robotics Courier Dual Standard modem, you should insert\012"ATB0\r\n" here. Refer to your modems manual for further information.\012----------------------------------------------------------------------\012@endnode\012\012@node SetupFile "Gadget-, menu- and ARexx-functions"\012----------------------------------------------------------------------\012Menu  : Setup / Files / Incoming path\012Gadget: -\012ARexx : SETUP "path_for_incoming_files" "<pathname>"\012\012Defines the directory path where to put incoming files at.\012\012IMPORTANT:\012- If you use this function from ARexx, please make sure your path\012  name ends with a "/" or ":"\012----------------------------------------------------------------------\012Menu  : Setup / Files / Outgoing path\012Gadget: -\012ARexx : SETUP "path_for_outgoing_files" "<pathname>"\012\012Defines the pathname that occurs in the file-requester the first time\012you use it. Of course you may send files from any other directory.\012----------------------------------------------------------------------\012Menu  : Setup / Files / Bump filenames\012Gadget: -\012ARexx : SETUP "bump_filenames" "<YES|NO>"\012\012Decides whether or not the names of incoming files should be modified\012when there already is a file with the original name. The modification\012is only done if the file that exists is the same length or longer than\012the incoming file. The modification applied is just the addition of\012a suffix, a point with a number following it. Example: original file\012"foobar" exists, bumping is enabled. The incoming file will then have\012the name "foobar.2". If "foobar" and "foobar.2" exists, the incoming\012file will be named "foobar.3" etc.\012----------------------------------------------------------------------\012Menu  : Setup / Files / Keep partial files\012Gadget: -\012ARexx : SETUP "keep_partial_files" "<YES|NO>"\012\012Decides whether or not to keep files that have been received\012incomplete. If disabled, this option will cause deletion of incomplete\012files, but this makes resuming of an aborted transfer impossible.\012----------------------------------------------------------------------\012Menu  : Setup / Files / Write buffer size\012Gadget: -\012ARexx : SETUP "file_write_buffer_size" "<buffersize>"\012\012Defines the size of the buffer that is used to hold the data until\012it is stored into a file. This does NOT mean that data is lost when\012more has been received than could be written to the file. Incoming\012data is buffered as necessary, maybe until the whole memory is filled.\012This value only says: "Don''t write incoming data immediately to the\012file, instead collect it until you received xxx bytes of data, then\012write the buffer to the file". This is done for efficiency reasons,\012storing small amounts of data is mostly a waste of time.\012----------------------------------------------------------------------\012@endnode\012\012@node SetupProtocol "Gadget-, menu- and ARexx-functions"\012\012Menu  : Setup / Protocol / Max. Packet Size\012Gadget: -\012ARexx : SETUP "maximum_packet_size" "<max bytes per packet>"\012\012Tells TWC how many data-bytes should be bundled in one data-packet.\012Values higher than 1016 are not possible, and not sensible, I think.\012Large blocks results in greater delays for the chat-lines you send,\012small blocks result in more protocol overhead, and therefore lower\012transfer-rates.  It''s a question of taste what you prefer.  When\012you''ve got to use a slow 2400bps modem, you should use a smaller\012packet size than 1016.  When your communication channel is often\012disturbed, smaller packets may increase the transfer-rate by\012decreasing the amount of data that has to be resend after an error.\012Most modern modems do error-correction by themselves, so this is not a\012point.\012----------------------------------------------------------------------\012Menu  : Setup / Protocol / Resend Timeout\012Gadget: -\012ARexx : SETUP "seconds_until_packet_resend" "<seconds>"\012\012TWC is not as stupid as many other protocols that need the data to\012come in the correct order, packet by packet.  Those protocols suffer\012from corrupted data heavily, the data rate dramatically decreases.\012Not so with TWC.  TWC takes the incoming data-packets regardless of\012their order.  Corrupted data-packets are resend at any later time, TWC\012stores all the packets internally until it has the opportunity to\012write sequential data to the incoming file.  There are situations,\012where the receiver is unable to order a corrupted data-packet again,\012for example, because the negative acknolegdment got corrupted itself.\012This case is handled by a timeout the sender triggers when a\012data-packet hasn''t been acknolegded for a certain period of time.\012That doesn''t mean the sender gets in panic, then...  the unacknolegded\012data-packet is just transferred again.  You can adjust the described\012timeout to fit your situation.  A larger timeout may result in a\012larger internal array of unacknolegded packets, and in more time-waste\012when there are unacknolegded packets at the end of a transfer.  A\012smaller timeout may result in unneccessary resends of data under bad\012circumstances, when the line is jammed.  Experiment with this value,\012if you like.\012----------------------------------------------------------------------\012Menu  : Setup / Protocol / Hangup Timeout\012Gadget: -\012ARexx : SETUP "seconds_until_auto_hangup" "<seconds>"\012\012One should be able to start a file-transmission and then leave the\012computer without having to worry about huge phonebills.  So I\012implemented a timer that causes the connection to be closed when there\012has been no valid packet been transmitted for a certain period of time\012(data-packets do not count, because they are resend automatically, but\012data-acknolegdements count...).\012----------------------------------------------------------------------\012@endnode\012\012@node SetupProcess "Gadget-, menu- and ARexx-functions"\012\012----------------------------------------------------------------------\012Menu  : Setup / Process / GUI Priority\012Gadget: -\012ARexx : SETUP "priority_of_GUI_process" "<priority>"\012\012Defines the priority of the GUI-process.  0 is the default, you may\012have your reasons to change this.  GUI Priority should generally be\012lower than serial and disk I/O priority.\012----------------------------------------------------------------------\012Menu  : Setup / Process / Serial I/O Priority\012Gadget: -\012ARexx : SETUP "priority_of_serial_I/O_process" "<priority>"\012\012Defines the priority of the process that handles all the serial in/out\012operations.  This priority should generally be higher then disk I/O\012and GUI priority\012----------------------------------------------------------------------\012Menu  : Setup / Process / Disk I/O Priority\012Gadget: -\012ARexx : SETUP "priority_of_disk_I/O_process" "<priority>"\012\012Defines the priority of the process that reads/write outgoing/incoming\012files. This priority should generally be higher then GUI priority and\012lower than the serial I/O priority. \012----------------------------------------------------------------------\012Menu  : Setup / Process / Audio Play Priority\012Gadget: -\012ARexx : SETUP "priority_of_audio_play_process" "<priority>"\012\012Defines the priority of the process that decompresses and plays\012incoming sound packets. It''s a matter of taste whether to give\012a higher priority to the audio replay process or the serial I/O\012process, the default priority is 2 here. \012----------------------------------------------------------------------\012Menu  : Setup / Process / Audio Sample Priority\012Gadget: -\012ARexx : SETUP "priority_of_audio_sample_process" "<priority>"\012\012Defines the priority of the process that samples and compresses the\012sound. This process needs a high priority to make sure the computer\012listens when you speak...\012----------------------------------------------------------------------\012@endnode\012\012@node SetupNotification "Gadget-, menu- and ARexx-functions"\012\012----------------------------------------------------------------------\012Menu  : Setup / Notification / On new chat\012Gadget: -\012ARexx : SETUP "on_new_chat_screen_to_front" "<YES|NO>"\012\012Decides whether or not you want the TWC screen to become the frontmost\012when new chat texts arrive.\012----------------------------------------------------------------------\012Menu  : Setup / Notification / On end of transfer\012Gadget: -\012ARexx : SETUP "on_end_of_transfer_screen_to_front" "<YES|NO>"\012\012Decides whether or not you want the TWC screen to become the frontmost\012when all selected files have been transferred.\012----------------------------------------------------------------------\012Menu  : Setup / Notification / Warnings until beep\012Gadget: -\012ARexx : SETUP "warnings_until_display_beep" "<number>"\012\012Defines the number of warnings to occur before notification.  A\012warning doesn''t mean that the transfer fails.  It just reports\012something that would better not be.  Errors cause the screen to be\012"beeped", and you can tell TWC to beep the screen also when a certain\012amount of warning were displayed.  Just a matter of taste.\012\012----------------------------------------------------------------------\012Menu  : Setup / Notification / Verbosity level\012Gadget: -\012ARexx : SETUP "verbosity_level" "<number>"\012\012People with little knowledge are often confused by detailed technical\012descriptions of what''s going on.  If you don''t want to see detailed\012reports of each and any thing that happenes, lower this value.  If you\012are curious, and need to know what extra-ordinary things happen,\012increase this value.  Sensible values range from 0 to 20.\012----------------------------------------------------------------------\012@endnode\012\012@node SetupAudio "Gadget-, menu- and ARexx-functions"\012\012IMPORTANT: Sound support is not completely implemented in the\012           current version, you may transfer IFF-8SVX-files, but\012           the main feature, the sampler support, is not ready.\012           Hold on for the next release...\012\012----------------------------------------------------------------------\012Menu  : Setup / Audio / Sound Enable\012Gadget: -\012ARexx : SETUP "sound_enable" "<YES|NO>"\012\012Decides whether or not incoming sound should be replayed on your\012Amiga. If you disable sound, incoming sound packets will simply\012be ignored.\012----------------------------------------------------------------------\012Menu  : Setup / Audio / { No Compression, ADPCM-2, ADPCM-4 }\012Gadget: -\012ARexx : SETUP "sound_compression_method" "<0|2|4>"\012\012Selects the sound compression method to be used. Without compression,\012the sample-rate you can transmit over the communication channel is\012limited to the CPS-rate you get when transferring files, e.g. about\0121600 samples/sec on a V.32bis link. As you may imagine, such a low\012sample rate is no good for understandable speech. TWC can compress\012and decompress sound-data "on the fly", thus making higher sample\012rates possible. The default sound-compression is ADPCM-2, this\012one compresses 4 bytes of sound samples into 1 byte, allowing for\012sample-rates up to 6400 Hz on a V.32bis link. Sound compression\012is "lossy", but will surely sound better than uncompressed sound\012on the lower rate. If you''ve got a very fast connection (e.g. an\012ISDN device, or a NULL-modem cable), you may disable sound-\012compression, this saves you some CPU-time.\012----------------------------------------------------------------------\012Menu  : Setup / Audio / Sample Rate\012Gadget: -\012ARexx : SETUP "audio_sample_rate" "<samples_per_second>"\012\012Defines the number of sound samples to take per second. The higher\012this rate, the better the sound quality will be, but the sample rate\012is limited by the speed of the connection (see above). The default\012value here is 6000, allowing permanent transmission of understandable\012speech over a V.32bis connection. If you choose a too high sample rate\012your partner will hear nasty "gaps" in the replay of the sound.\012The sample rate does not affect IFF-8SVX-files that are transferred.\012----------------------------------------------------------------------\012Menu  : Setup / Audio / Sample Rate\012Gadget: -\012ARexx : SETUP "audio_sample_rate" "<samples_per_second>"\012\012Defines the number of sound samples to take per second. The higher\012this rate, the better the sound quality will be, but the sample rate\012is limited by the speed of the connection (see above). The default\012value here is 6000, allowing permanent transmission of understandable\012speech over a V.32bis connection. If you choose a too high sample rate\012your partner will hear nasty "gaps" in the replay of the sound.\012The sample rate does not affect IFF-8SVX-files that are transferred.\012----------------------------------------------------------------------\012Menu  : Setup / Audio / Sample HotKey\012Gadget: -\012ARexx : SETUP "sample_hotkey" "<key description>"\012\012Defines the hotkey that enables sampling. With TWC, you should be able\012to talk to your partner _while_ files are transferred. As you may\012imagine, it would be a huge waste of transmission bandwidth if TWC\012would permanently sample and transmit sound data. To obey this, the\012sample hotkey works like the send-switch on a radio set. As long\012as you hold down the hotkey, the sound-sample is taken. If the\012hotkey is released, no sampling is done. For a description of\012the parameter <key description> see @{"Key Descriptions" link KeyDesc}.\012The default sample hotkey is "F9".\012----------------------------------------------------------------------\012@endnode\012\012@node SetupMisc "Gadget-, menu- and ARexx-functions"\012\012----------------------------------------------------------------------\012Menu  : Setup / Misc / Encryption key\012Gadget: -\012ARexx : SETUP "encryption_key" "<text>"\012\012Defines the encryption key.  If you supply no encryption key,\012encryption is disabled.  Phone lines are not safe.  It''s sort of easy\012for other people to spy on your communication, and you may not want\012them to do so.  Whether you need to keep your data secret or you''re\012just a little paranoid doesn''t matter, this option allows you to make\012TWC scramble all the data it transfers.  Your partner has to set\012exactly the same encryption key to enable TWC to unscramble your data.\012Of course it''s nonsense to tell your partner the encryption key on the\012phone that might be spyed...  :)\012Data scrambling needs some extra CPU time.\012\012IMPORTANT: Don''t change the encryption key while a transfer is in\012           progress. If you experiment with encryption, remember\012           to disable it next time if necessary.\012----------------------------------------------------------------------\012Menu  : Setup / Misc / Display average CPS\012Gadget: -\012ARexx : SETUP "show_average_instead_of_actual_CPS" "<YES|NO>"\012\012Switches display between average and "actual" CPS (chars per second)\012rates.  By default, the CPS displays in the "File Transfer Panel" are\012integrating over time.  This results in a relative stable CPS display,\012that does not react heavily on temporary changes of the transfer-rate.\012You can also have TWC to always compute an "actual" CPS-rate, based on\012the time the last data-packed needed for transfer.  This "actual"\012value is nonsense for the sending-rate when your modem uses\012packet-oriented protocols such as LAPM, V42 or MNP internally, because\012the speed depends then on the fill-state of the modems buffer.\012----------------------------------------------------------------------\012Menu  : Setup / Misc / Echo Your Chat\012Gadget: -\012ARexx : SETUP "echo_your_chatlines" "<YES|NO>"\012\012Decides whether or not TWC displays the chatlines you send to your\012partner in the chat-history. This feature is especially useful if\012you want to control TWC via ARexx, and you need to evaluate the\012incoming chat lines. By disabling the echo, you can make sure that\012only the chat lines coming from the remote TWC are received by\012the ARexx command @{"GETCHATLINE" link ARexx}.\012----------------------------------------------------------------------\012Menu  : Setup / Misc / ScreenToFront hotkey\012Gadget: -\012ARexx : SETUP "screen_to_front_hotkey" "<key description>"\012\012Defines the hotkey that brings the TWC screen to front temporarily.\012As long as you hold down this key, the TWC screen stays in front, so\012you can watch its contents, click a gadget on it etc.  This is\012especially useful if you''re doing something on another screen and just\012want to take a short look at what TWC''s doing.  For a description of\012the parameter <key description> see @{"Key Descriptions" link\012KeyDesc}.  The default screen-to-front hotkey is "F10".\012----------------------------------------------------------------------\012Menu  : Setup / Misc / Serial Number\012Gadget: -\012ARexx : SETUP "ü" "<serial number>"\012\012This is where to enter the serial number you get when you register\012TWC.  The default value here is 0, causing TWC to display a requester\012telling you about the ShareWare status on startup.  If you don''t want\012to see this requester anymore, enter any non-0-number here.  But as\012long as this number is not a valid serial number, TWC will quit\012automatically after approx.  20 minutes.  For detailed information on\012the ShareWare-status of TWC and how to register, see @{"Copyright" link Copyright}.\012----------------------------------------------------------------------\012\012@endnode\012\012@node KeyDesc "Format of key descriptions"\012\012Some functions of TWC needs key-descriptions. Here are some examples\012which show how to create such a description:\012\012Description     Meaning\012--------------------------------------------------------------------\012x               The key ''x''\012SHIFT a         The key ''a'' while SHIFT is hold down\012LSHIFT b        The key ''b'' while the left SHIFT key is hold down\012RSHIFT c        The key ''c'' while the right SHIFT key is hold down\012ALT d           Now make a guess!\012LALT e          ...\012RALT f\012AMIGA g\012LAMIGA h\012RAMIGA i\012CAPSLOCK j\012CTRL k\012NUMPAD 9        The key ''9'' on the numeric pad.\012CAPS l\012BACKSPACE\012COMMA\012CURSOR_DOWN\012CURSOR_LEFT\012CURSOR_RIGHT\012CURSOR_UP\012DEL\012ENTER\012ESC\012F1\012F2\012..\012F10\012HELP\012RETURN\012SPACE\012TAB\012\012SHIFT CTRL o   Combinations are also possible!\012\012I hope theese examples are explaination enough...\012\012@endnode\012\012@node ARexx "ARexx specific commands"\012\012The ARexx-port of TWC has the name "TWC.x" where x is a number incremented\012by any newly started TWC. So the first TWC started has the ARexx-port "TWC.1".\012\012IMPORTANT: Unlike many other programs, TWC has an asynchronus ARexx interface.\012           This means: The ARexx commands generally return immediately, but\012           the execution may happen somewhat later. The reason should be\012           obvious: One could not react on incoming data whilst waiting for\012           some other data to went out and vice versa, many other situations\012           are alike. If not mentioned otherwise, assume any command to\012           return immediatly.\012\012If an ARexx command fails, an error message can be found in a variable called\012"<portname>.LASTERROR", for the first started TWC e.g. "TWC.1.LASTERROR".\012\012Results from ARexx functions are returned in a variable called "RESULT"\012if you enabled results with the command "options results" (see ARexx guide).\012\012Many ARexx functions are already explained above, the following is a list\012of functions not available from the user interface:\012\012\012----------------------------------------------------------------------\012GETSTATUSLINE\012\012Returns the oldest status-line the status-history contains, and\012removes this line from the history. The history-buffering is necessary\012to enable you to get any status-line without missing one.\012----------------------------------------------------------------------\012GETCHATLINE\012\012Returns the oldest chat-line the chat-history contains, and\012removes this line from the history. The history-buffering is necessary\012to enable you to get any chat-line without missing one.\012If you want to get only chat-lines that came from the remote TWC,\012refer to @{"Setup / Misc" link SetupMisc} / Echo your chat.\012----------------------------------------------------------------------\012SENDMODEM <text>\012\012Sends a text to the modem, just as if it where entered by the user\012while the "Modem" radio-button is selected.\012A carriage-return + newline is automatically added to your text.\012----------------------------------------------------------------------\012SENDCHAT <text>\012\012Sends a chat-text to the remote TWC, just as if it where entered by\012the user while the "Chat" radio-button is selected.\012----------------------------------------------------------------------\012CLEARFILES\012\012Removes all files from the to-send-list. The names of the files in the\012list are returned, delimited by spaces, and enclosed in double-quotes.\012----------------------------------------------------------------------\012SETUP <entry-name> <value>\012\012Allows you to define any setup-value. Each entry in the setup has a\012name and a value. Just take a look at the TWC_setup file for possible\012names.\012\012IMPORTANT: If you supply an non-existing entry name, a new entry is\012           created (and stored within the setup-file). This is done\012           for forward/backward compatibility. Please avoid to add\012           nonsense-entries to the setup.\012----------------------------------------------------------------------\012READSETUP <entry-name>\012\012Allows you to read any setup-value.  Each entry in the setup has a\012name and a value, the value to the entry supplied is returned by this\012function.  Just take a look at the TWC_setup file for possible names.\012IMPORTANT: If you supply an non-existing entry name, a new entry is\012           created (and stored within the setup-file). This is done\012           for forward/backward compatibility. Please avoid to add\012           nonsense-entries to the setup.\012----------------------------------------------------------------------\012REOPENSERIAL\012\012If the user changes the serial settings with the GUI, the port is\012automatically reopened. This does not happen if you change the serial\012parameters from ARexx. You have to call this function to reopen\012the serial port from ARexx.\012----------------------------------------------------------------------\012RELEASESERPORT\012\012Tells TWC to release the serial port. The port is reopened by the\012REOPENSERIAL command. Many TWC functions cannot be executed while\012the serial port is released.\012\012IMPORTANT: Remember that even this command works asynchronusly,\012           make sure that the serial port is actually released\012           before trying to open it from somewhere else.\012----------------------------------------------------------------------\012WAIT\012\012This function does _not_ return immediatly. It allows you to put your\012ARexx program in a waiting state (consuming no CPU time) until\012one of a set of events happen. Events that cause WAIT to return are:\012\012- New status- or chat-line output \012- TWC got an ARexx command (maybe from another process)\012- TWC quits\012----------------------------------------------------------------------\012EXTERNALPORT <address>\012\012Defines the address of an already initialised struct IOExtSer TWC\012should use instead of a self-opened device. The address has to be\012a decimal- or hex-number (e.g. 49152 or 0xc000).\012\012IMPORTANT: Don''t use or modify your IOExtSer while TWC uses it.\012           The function "HANGUP" will have no effect when TWC uses an\012           external IOExtSer structure. \012           All serial settings will have no influence when TWC uses an\012           external IOExtSer structure. \012           EXTERNALPORT will take effect with the next REOPENSERIAL\012           \012Note: If you want to use TWC as an external protocol driver, you may\012      make it this way:\012 \012      - start TWC in the background with the -r flag (released port)\012      - when you want to transmit files, use EXTERNALPORT and\012        REOPENSERIAL to prepare TWC for action\012      - use all the other ARexx commands to do the actual transfer\012      - use RELEASESERPORT to detach TWC from your structure\012----------------------------------------------------------------------\012\012@endnode\012\012@node Problems "Problems - ask Murphy, why."\012\012This chapter will grow with the feed-back I get from you\012and all the other TWC users. Questions unasked cannot be\012answered...\012\012A few hints that may help you:\012\012- You start the file transfer, but it doesn''t start immediatly,\012  but after the first resend of the file-header. This may result\012  from either a buggy serial.device or some ugly modems. I don''t\012  have a clue how to work around this, yet... \012\012- If "HangUp" doesn''t work, take a look at your modem''s\012  configuration. Your modem should hangup when DTR is dropped.\012\012- If you use an A500 and BaudBandit.device, watch out for trouble.\012  This thing is not that dependable. Try to use a lower baud-rate,\012  if neccessary. BaudBandit 1.4 seems to work fine.\012\012- If you use a ZyXEL Modem, don''t use the 5.00e ROM-version along\012  with V.42bis compression.\012\012- If you use an USR dual standard modem, make sure you have a V.32bis\012  connection. To one-way-only users HST and V.32bis seem to be\012  of the same speed, but THEY AREN''T. Use ATB0 to enable V.32bis\012\012- If you use a Telebit Modem, don''t use PEP modulation. Use\012  V.32 or even better V.32bis instead.\012\012- Don''t panic when your V.32bis modems retrain... bad line\012  conditions can cause transfer interruptions up to 20 seconds,\012  especcially with buggy modem-software (such as the early\012  versions of the Rockwell-Chipset used in Supra, Twincom,\012  Yoriko and others)\012\012- If you''re transmitting over really bad lines (such as the\012  german BundesPest Telekotz often provides), and your\012  average cps-rate drops below the value (physical bps rate)/10\012  you may try to switch off the error-correction (V42, MNP4)\012  of your modem. This may sound weired, but TWC''s error correction\012  is smarter than the one used in most modems, and you may\012  gain higher rates... (USR Modems: AT&M0)\012\012- The greater your modem''s buffer is, the longer chat-packets\012  will be delayed - please remember this... as I''m unable\012  to change this...\012\012If you''ve got other problems or solutions, please send\012a report to my UseNet address [email removed]\012\012@endnode\012\012@node Copyright "Copyright and how to register TWC III"\012\012TWC III has been written by Lutz Vieweg. ©1993, all rights reserved.\012\012The TWC executable and documentation is freely distributable,\012the serial-number you get when you register is NOT. Remember\012this serial-number will be stored in the setup-file, so don''t\012give anyone a copy of yours.\012\012TWC comes without any warranty at all, use at your own risk.\012\012To register your TWC and get an individual serial-number send\012me a letter with US$ 15 in _cash_ + $3 for postage if I can''t send\012you the serial-number via email (UseNet). You may also send me\012DM 20,- (+ 1DM for postage) if you''re living in germany.\012\012Once you enter your valid serial-number in the setup menu, TWC\012won''t quit after approx. 20 minutes anymore...\012\012Send your registrations, feed-back, ovations etc. to:\012\012Lutz Vieweg\012Eduard-Rüppell-Straße 12\01260320 Frankfurt am Main\012GERMANY\012\012UseNet:  [email removed]\012\012Remember: A bug that''s not reported cannot be fixed.\012\012\012(The following does not apply to anyone except to some\012 guys that are having weired and childish discussions\012 on the german UseNet, so don''t mind if you cannot read it)\012\012DISCLAIMER: Hiermit sei es ausdrücklich gestattet diese\012----------  Software zu all jenen Dingen zu gebrauchen,\012            die kleinkarierte Dogmatiker ihren potentiellen\012            Kunden verbieten wollen, also beispielsweise\012            die Übertragung der Wasserstoffbombenkonstruk-\012            tionsunterlagen an Killer-Mutanten vom Mars oder\012            der Verkauf an Arme, die der kostenfreien\012            Beschaffungsmöglichkeiten von ShareWare unkundig\012            sind.\012            \012            Ungeachtet dessen möge derjenige zu Staub zerfallen,\012            welcher seine Seriennummer weitergibt...\012\012@endnode\012\012@node Credits "Credits to some helpful people"\012\012I want to thank the following people for supporting me while\012TWC was programmed:\012\012van den Baard, Jan\012   for "GadToolsBox" which was used to design the GUI\012\012Friedl, Henning\012   for valuable programming hints\012\012Rohrdrommel, Michael\012   for endless testing sessions on his antique A500 :)\012\012Wild, Markus\012   for the marvellous Amiga-implementation of GNU C++\012   (though I used my own, independent library and startup-code, not\012    the GNU-stuff)\012\012... and of course anyone who reported bugs or registered!\012\012@endnode\012\012@node Pgm "Infos for programmers"\012\012I''d really like to see other programs, especially BBS-softare, to\012support TWC not only as another transfer protocol, but a advanced\012and more comfortable way to exchange data. Many people asked me\012why I haven''t built TWC into a XPR library. This is not possible\012with the current standard, and I fear this won''t change.\012If you like to use TWC from external software, and you miss\012something necessary in TWC that would enable you to do so, please\012ask me. You can reach me via email in UseNet under\012\012 [email removed]\012\012Good luck,\012\012Lutz Vieweg\012\012@endnode\012\012@node Version "Version history"\012\0123.26\012          When the connection was suddenly interrupted, TWC often\012           refused to receive new data for a while, after the\012           connection has been established again. This resulted\012           from a missing buffer-flush. Fixed\012          TWC is now compiled with GNU C++ 2.5.7\012\0123.25\012          Ooops, in release 3.24 multi-select wasn''t possible. Fixed..\012          TWC is now compiled with GNU C++ 2.5.3\012\0123.24\012          When started from Workbench without any other\012           icons selected, an empty entry in the to-send\012           list was generated. Fixed.\012\0123.23\012          I don''t know why the hell the OS does not scroll\012           autoscroll screens when "SA_OVERSCAN" isn''t set,\012           but now it''s fixed...\012          Notification on end of transfer is now only done\012           then the files-to-send list is empty.\012          Changed the width-calculation for the chat- and\012           status-windows, now characters shouldn''t be\012           "eaten" anymore...\012\0123.22\012          Some older versions of commodities.library are\012           buggy - this lead to crashes when hotkeys where\012           used. Applied a workaround.\012          For the same reason I had to change the default \012           hotkey-descriptions. Some older versions of\012           commodities.library do not understand "NUMPAD".\012           New defaults are F10 and F9\012\0123.21\012          Default screen-mode changed to interlace\012          The default screen-to-front hotkey description\012           was invalid, changed to NUMPAD /\012          Some people don''t like to read what is written\012           in gadgets, so they asked me to arrange the\012           OK and CANCEL gadgets in the requesters in a\012           specific order. Done: OK is now left, CANCEL right.\012\0123.20\012          Many changes, improved GUI, first sound-support\012           routines, bug-fixes, better guide, ARexx-Port,\012           ability to use externally opened devices etc.,\012           too much changes for a detailed description\012           here. Please take a look at the whole guide...\012\012          Sound support and dial-function not ready, yet.\012\012(changed version numbering back to the old style X.YZ, this is\012 less misunderstandable)\012\012101       Cosmetic corrections, functions now available\012          via menues and command-keys\012\012100       First public release. How long will it take\012          until the first bug is found the beta-tests\012          did not show?\012\012@endnode\012\012@node Future "Ideas for possible future extensions of TWC"\012\012- Sound-support and the dial-function will be completed\012- Less linguisitc mistakes in the documentation (english is\012  not my native language).\012- Improved BBS-software Interface\012- Video-support (this is meant seriously)\012- remote command exectution \012- maybe a screen-mode requester... :)\012\012@endnode\012\012','\012',char(10)),NULL,'auto-added',139630,5,0,NULL,NULL,'twc326','scan',1780048813);
INSERT INTO door_catalog VALUES('txt','TXT.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TXT.LHA',NULL,'XIM','test',NULL,NULL,NULL,NULL,replace('test\n','\n',char(10)),'PTL-WALK.TXT',replace('    .                                                                    .\n      .                                                          ______.\n       _  [- cOCAINE PC  DHQ -]     [-MYTH DiSTRiBUTiON SiTE!-]  \   __|\n      \/---------------------------------------------------------·--\/|\n      ¦  Bermuda Holland - a4OOO/40 - 1400MB - /X 4.xx - FAST!    _   ¦\n      |----·-----------------------------------------------------\/---:\n      l_____\                                     _____.              ·\n    ._______    ______.  _____________          __\__  |    .______  /\\n   _|_ ____/__./  ___ |_._ _____  /\_ \ __ ___./    /  |____|__ __/_/__\\n   ___\\____  \_ / ___| |_\\  ___/ | \ \\// _/_    /   |  ____//__ __  \\\n    |      /   ////     |   \      |  \ \/ /  /   /_   |  \     / /  \  \\\n    l_________//·/______|___/\___ _l___\  /__/l________|_______/ /____\___\\n                                        \/             ______.\n    .   _______     _____ ._______ _______     /\    __\____ |    .______\n       __ ____/___./    .\|      /       /  __/__\ ./ ___  / |____|__ __/_\n    _ ___\\____ _ \_     \\.    /___    /___     \\|    / /  |  ____//___\n       |    /      /       |  _/   /  _/   /____  \\   / ·   |  \     /\n       l___/\_____/________|______/_______//____\___\_/______|_______/gZ!\n    \n             -----»> AMiGA - SNES - PC - REQUEST!- PSX - <«-----\n                   [CDROM SONY CDU-76S RP 4SPEED ''SCSI] \n   [-sYSOP!-][-tRIANGLE/mYTH!]^[-sTAFF!-][-CRACK/CoCaInE][DEVIL''S EYE/CoCaInE]\n            --------------------------------------------------------\n            [ NODE1: +31-365-341-347  Us RoBoTiCS COURIER V34 [33K6]\n            -------------------------------------------------------\n            [ NODE2: +31-365-347-943  Us RoBoTiCS COURIER V34 [33K6]\n            --------------------------------------------------------\n            [ NODE3  +31-36?????????  zYxEl 19k200  INVITED        ]\n            --------------------------------------------------------\n            [ NODE4  +31-36?????????  ISDN MASTER 64K JULY/96      ]\n            --------------------------------------------------------\n                      -^(· FastAdd v1.1 by nIKE ''94! ·)^-\nå\n\n    ________ __/\            ________ __/\\n    \___    Y __/ |\__/\____ \___    Y __/___:__________     ____ __ _ _\n      | \/: :\\__ | \_____  \/\| \/: :\\|Y   |   ______/    /   /\\n      |   !  //  \:  \  _  /\_/|   !  //|   ||¡  ___/___   /___/_ \ __\n      |:  |__/    |   \  \_   \|   |__/ |!   l/\ |     /   \   \  /\n      !|  | \     ! _  \___|  /!   |    |:  _  \\    //     \___\/__ _\n      l___; /____ l_\   \  l__\l___;    l____\   \___/\n      ---------------\\//---------------------\\//---\n                      \/  >> pURPLE tURTLE <<  \/\n   _ _ __ ____    _______________               /\_________/\\n         /\   \   \  ____  ___  /   |\__/\____  \_____  ____/___:__________\n     __ / _\___\  / / \  \/ / \ \__ | \_____  \/\  \  \/ / |Y   |   ______/\n        \  /   /  \ \ /  /  \ / /  \:  \  _  /\_/  /  /  \ |   ||¡  ___/___\n     _ __\/___/    \//   \   \\/    |  \\  \_   \ /   \  \\|!   l/\ |     /\n                    //   /    \     ! _  \___|  //    /    |:  _  \\    //\n                    \_________/____ l_\   \  l__\\_________l____\   \___/\n                    -------------------\\//---------------÷mAxx÷-\\//---\n                                        \/                        \/\n\n                             >> PReSeNTS <<\n\n          .-----------------------------------------------------.\n          |       More Information about Project WALKER         |\n          |-------------------------+---------------------------|\n          | Nr.Disks: 0             | Protection : None         |\n          |-------------------------+---------------------------|\n          | Supplied By: TFX        | CracKed by : Nobody. DoH! |\n          |-------------------------+---------------------------|\n          |                Product Description                  |\n          |               ~~~~~~~~~~~~~~~~~~~~~                 |\n          | While I was surfing around in the world wide web    |\n          | I found this nice, KREWL, ALL EXPLAING, WEB site    |\n          | About the NEW Amiga ''Walker''.... This together with |\n          | the ATFAQ from 2 days ago, should be enough info    |\n          | to show that Amiga is back for the future, and is   |\n          | ready to KICK some serieus PC BUTTS !!!             |\n          `-----------------------------------------------------''\n\n----------- - -- - ------ -- -------- -------- -- ------ - -- - -----------\n                             .--------------.\n                             |Project Walker|\n                           --+--------------+--   \n                       /\    |              |    /\\n                      /  \   :Specifications:   /  \\n                      \  /   :              :   \  /\n   CPU                 \/                        \/\n\n - 68EC030 40Mhz (Proto 25Mhz while custom chip ''Tony'' a PLA/GAL'')\n - Space for FPU. \n - Could be socket or FPU as standard in production unit.\n\n\n   SUPPORT\n\n - Real time clock as standard\n - Hard drive as standard (size depending on market when manufactured)\n - CD (Quad Speed) as standard\n - Billed as 1MB CHIP RAM + 4MB of FAST as standard. Likely to be 2+4.\n\n\n   ASSORTED\n\n - PCB currently 6 layers but expected to reduce to 4 and footprint\n   to be reduced noticably. \n - Rectangular optimised PCM layout is far cheaper to product.\n - Return to dial in-line socketted 8520 CIAs even at greater cost.\n - PCMCIA in prototype but expected to be dropped for production unit.\n\n\n   EXPANSION\n\n - Standard multicontroller PC style IO chip. \n   Exact model undecided since they are largely similar to include in\n   the design and program.\n - Features; EPP Parallel port, High speed serial port, E-IDE port used\n   for CD-ROM and hard drives, Floppy controller. (see *)\n\n\n * Floppy Controller is obviously capable of full speed (not half spin)\n   HD floppy disk access but this provides a delima in how to support\n   existing hardware illegal DD floppy access. Some sort of electronic\n   switching is being considered as well as a physical switch/cable\n   relocation to move between the new controller and the standard Paula\n   based interface. A change in the HD Amiga floppy architecture is also\n   planned.\n\n\n   OS\n\n - Currently V43.1, KS 3.2 will move to a set of 1MB chips which while\n   AT aren''t sure if it will be provided by THEMSELVES as an retro\n   upgrade for existing machines (A3K/A4K and A1200 can take 1MB ROMs\n   apparently) they are open to a 3rd party deal at the least.\n - Contains mainly bug-fixes and small enhancements like the removal\n   of the 2GB limit from FFS.\n - CDFS revamped and bug-fixed to function with Scala etc and obviously\n   the new E-IDE interface.\n\n\n   SLOTS\n\n - There''s one slot located dead center in the motherboard.  \n   However it''s split into two sections so that it may house 2 cards if\n   needs be.\n - The exact details on the signals and purpose of each half weren''t\n   finalised or available but basically one can surmise that one is a\n   CPU slot and the other a video slot. Signals will be duplicated so\n   that different cards could function.\n\n * Amiga Technologies WILL MARKET THEIR OWN PPC UPGRADE! Though it was\n   developed in conjuncton with Phase 5, AT will provide the upgrade\n   which will contain a new OS on-board and such forth. PPC603 based.\n\n - If it''s not obvious, it''s possible in theory to plug in a GFX board\n   in the video half and a 680x0 based accelerator in the CPU half. It''s\n   not clear if the PPC card will need both or just the CPU slot.\n - Another major application could be to make a Zorro and/or PCI break\n   out board from this slot. No, there are NO Zorro or PCI slots as\n   standard though the physical nature of the slot is PCI style.\n - An additional small ''IO'' slot is being considered. 3rd party simple\n   hardware projects such as a networking facility, extra serial ports\n   or a sampler could be used with this as well as home made projects\n   conceivably. This isn''t decided, just considered at this time.\n\n\n   CASE\n\n - Yes it''s a vacuum cleaner. :-) Seriously the only way to describe it\n   is with a picture and I''m sure they''ll turn up soon. Interesting\n   AT say that the hood could be raised by spacers and such forth to make\n   more room internally for a bus board for cards etc.\n\n\n   TIMEFRAME\n\n - AT say that the design will be finalised in the Summer ready for\n   production. It''s not decided of Solectron will be the manufacturers.\n - The production unit should be available in the ''Fall'' for the Christmas\n   Season.\n\n\n   NOTES/AUTHOR\n\n - I''m the techical staff writer for CU Amiga Magazine. This information\n   is important enough to release publically immediately though more\n   details, details (very) pictures and interviews with the AT design\n   team will feature in the next issue. <sorry for the plug>\n\n\n   FINAL\n - The name ''Walker'' is not the production name!  Therefore we call it\n   Project Walker. The name is undecided and Amiga Technologies have\n   decided to run a competition for the name of the unit! \n - This competition will be run through our magazine. Both by writing in\n   to the standard address and E-mailing [email removed]\n - Just state your name in the body of the mail. \n - That''s all that''s required, if you win I''ll be in touch via E-mail to\n   sort out the prize/s.\n\n * Prizes; 1st Amiga Surf Pack, 2nd Amiga Magic Pack.\n\n\n   AFTERWORD\n\n - I don''t know about you but I dig this machine from the bottom of my\n   heart. It''s made me feel better about the future of the Amiga. It''s\n   a step in what I believed was the right direction.\n\n\n                              Three cheers for AT! \nLater,\n     _ ___\n/\/\(-) |  - CU Amiga Magazine ([email removed])\n\nP.S.: Hottest news of all...:\n\n                  DAVE HAYNIE SAYS F*CK OFF TO SCALA AND \n           IS MOVING TO GERMANY TO WORK WITH AMIGA TECHNOLOGIES\n\n----------- - -- - ------ -- -------- -------- -- ------ - -- - -----------\n@BEGIN_FILE_ID.DIZ   ____________________________  _____\n.--|  _  \  |  |  ___|  _  \  |--|  ./-+---.\n:  |  ___/_____|__|  |  ___/_____|_____|   :\n|  :  !___  |________|__|  ___|  _____  96 |\n:        |  |  |  |  ___|  |  |--|  ./-.   :\n`--rETi--|__|_____|__|--|__|_____|_____|---''\n \n               P r e s e n t s\n \n       Latest info on project ''WALKER''\n@END_FILE_ID.DIZ\n\n    .                                                                    .\n      .                                                          ______.\n       _  [- cOCAINE PC  DHQ -]     [-MYTH DiSTRiBUTiON SiTE!-]  \   __|\n      \/---------------------------------------------------------·--\/|\n      ¦  Bermuda Holland - a4OOO/40 - 1400MB - /X 4.xx - FAST!    _   ¦\n      |----·-----------------------------------------------------\/---:\n      l_____\                                     _____.              ·\n    ._______    ______.  _____________          __\__  |    .______  /\\n   _|_ ____/__./  ___ |_._ _____  /\_ \ __ ___./    /  |____|__ __/_/__\\n   ___\\____  \_ / ___| |_\\  ___/ | \ \\// _/_    /   |  ____//__ __  \\\n    |      /   ////     |   \      |  \ \/ /  /   /_   |  \     / /  \  \\\n    l_________//·/______|___/\___ _l___\  /__/l________|_______/ /____\___\\n                                        \/             ______.\n    .   _______     _____ ._______ _______     /\    __\____ |    .______\n       __ ____/___./    .\|      /       /  __/__\ ./ ___  / |____|__ __/_\n    _ ___\\____ _ \_     \\.    /___    /___     \\|    / /  |  ____//___\n       |    /      /       |  _/   /  _/   /____  \\   / ·   |  \     /\n       l___/\_____/________|______/_______//____\___\_/______|_______/gZ!\n    \n             -----»> AMiGA - SNES - PC - REQUEST!- PSX - <«-----\n                   [CDROM SONY CDU-76S RP 4SPEED ''SCSI] \n   [-sYSOP!-][-tRIANGLE/mYTH!]^[-sTAFF!-][-CRACK/CoCaInE][DEVIL''S EYE/CoCaInE]\n            --------------------------------------------------------\n            [ NODE1: +31-365-341-347  Us RoBoTiCS COURIER V34 [33K6]\n            -------------------------------------------------------\n            [ NODE2: +31-365-347-943  Us RoBoTiCS COURIER V34 [33K6]\n            --------------------------------------------------------\n            [ NODE3  +31-36?????????  zYxEl 19k200  INVITED        ]\n            --------------------------------------------------------\n            [ NODE4  +31-36?????????  ISDN MASTER 64K JULY/96      ]\n            --------------------------------------------------------\n                      -^(· FastAdd v1.1 by nIKE ''94! ·)^-\n','\n',char(10)),NULL,NULL,218749,11,0,NULL,NULL,NULL,'scan',1780048813);
INSERT INTO door_catalog VALUES('txtad10r','TXTAD10R.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TXTAD10R.LHA','TEXTAdder','XIM','TEXTAdder','1.0',NULL,NULL,NULL,replace('TEXTAdder V1.0r\n','\n',char(10)),'TEXTAdder.DOC',replace('****************************************************************************\n                             TEXTAdder V1.0r\n****************************************************************************\nReleased: 08/11/92\ndone by : GOOSEMAN/ANALOG\n\nArchive Contents:\n\nTEXTAdder	   (  1868 Bytes)       : Executable\nTEXTAdder.DOC                           : Documentation\nTXT                                     : Sample Checkfile (-> BBS:FCHECK)\n\nShort Description:\n\nWill add a given Textfile in Front of another. Although this prog does \nnothing new, it allows to freely choose the Textfile to be added and it\nis quite short.\n\nSyntax:\n\nTEXTAdder [-TXTFILE] [TXTFILE]\n\n-TXTFILE : Textfile which will be added in Front of [TXTFILE]\n           NOTE THE "-" IN FRONT OF IT.\nTXTFILE  : Textfile to be processed.\n\nHints:\n\n- Just copy the given TXT Checkfile into your BBS:FCHECK and change the\n  name of the file you''d like added to the Textfiles uploaded on your BBS.\n\n- Copy it under several Names (CAP,DOC,DOX,...) in your BBS:FCHECK Dir\n\nDisclaimer:\n\nThis program has been tested only on 68000 Machine. It SHOULD run without\ntrouble on any other processor type (20er,30er). I cannot be held responsib-\nle for any physical damage this program may do to any of your hardware.\n\nBUG-Reports / Errors / Money:\n\nSend all of the above to:\n\n                   GOOSEMAN, P.O. Box 33, CH-9204 Andwil\n\nor call my BBS:\n\n                    PROTON DREAMS at +(41) 71 850-612\n\nor for a voice chat:\n\n                      GOOSEMAN at +(41) 71 850-176\n','\n',char(10)),NULL,'auto-added',4092,4,0,NULL,NULL,'txtad10r','scan',1780048813);
INSERT INTO door_catalog VALUES('txtadd33','TXTADD33.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TXTADD33.LHA','TxtAdder','XIM','TxtAdder',NULL,'tANGo',NULL,'¦  _/    \\_\\\\-------+      |     | |  \     _\_ __________¦___ __¦_____¦__ |___\__ /   \\___________  \\_______   \',replace('  .    ____ __ _ _       .------.     .\n  ¦  _/    \\_\\\\-------+      |     |\n  |  \     _\_ __________¦___ __¦_____¦__\n  |___\__ /   \\___________  \\_______   \\n_/  ____//     \     \ ___/   \ |    /    \_\n\   \____\____  \_   / \______/ |___       /\n \    /---yuk\______/    \_ __ _|_  \_____/\n  \  /              \_____//_////-----+\n  ¦\/ pRESENTs:          ¦      |     |\n  |                      `------''     |\n  |      tXt-aDDEr v3.3 bY tANGo      |\n  `-----------------------------------''\n','\n',char(10)),'TxtAdder.doc',replace('\n                        TxtAdder V3.3 - by Tango/DPL''94\n\n[-----------------------------------------------------------------------------]\n\nThe history of TxtAdder V3.3\n\nThis TxtAdder is available to you for one simple reason! About half a year ago\nMarwin/Defiance asked me to do a TxtAdder for him. I made a quick one in pascal\nthat finaly was able to add one logo at front, at back or both at front and\nback. Marwin gave me a few hints how to make the program better, but I was too\nlazy to finnish it! :( The some months ago I learned C and after some weeks\nMarwin asked me once again to finnish my TxtAdder. Therefor I rewrote it in C\nand added a few cool options. First of all you''re able to add the current date\nto the textfile uploaded. "What''s so fucking special about that!?" I here you\nall scream, but! This is not the only feature! This txtadder in fact has a\nfeature wich I''ve never seen! It can add unlimited numbers of adds to the file.\nBut, more about that in the rest of the doc. At last I just want to say a _BIG_\nhello to Marwin, who''s one of my best friend on the scene!\n\n[-----------------------------------------------------------------------------]\n\nNormal documentation!\n\nFirst of all I just want to warn you a little. The errorchecking routines in\nthis program are not what they could be. If something happens it just exits\nsilently. It should not leave any files open or so, but try not to mess around\nwith the special files it creates!\n\nThe configfile, named "TxtAdder.cnf" shold look as follows! Remember, it will\n_NOT_ work with comments! The name of the configfile is "S:TxtAdder.cfg"\n(not changable, sorry!)\n\n-----< cut >----------\n1S:Board1.add\n3S:Board2.add\n-----< cut >----------\n^     ^\n|     |\n|     `----> This is the path and name of the file to add!\n|\n`----------> This tells the adder where to add the logo, 1 = FRONT, 2 = BOTH\n             and 3 = END.\n\nIn all textfiles exept the sourcefile the textadder will check for the string\n$DATE_STR (case sensetive) and will enter todays date over it. So, if you put\nthe string in a file you add the date will be exchanged with the string. Simple\neh!? I have included some sample files wich will work if you want to check the\nadder out.\n\n[-----------------------------------------------------------------------------]\n\nThe greets!\n\n   MARWIN         - Thanx for all the encouragement!\n   KRU5TY         - Thanx for the coolest ASCII-style ever!\n   MELONE         - One of my best friends and cool trader!\n   D0UBLE         - You Norweigan squit! ;)\n   MIKE           - Get to know this guy! He''s cool and very friendly!\n   THE BIG BYTE   - Thanx for all the help with my 030''s!\n\nTo everybody else - Call my board and upload some if ya like this util! The \n                    name and numba is:  ToTAL iNFERNo +46-42-234164!\n','\n',char(10)),NULL,'auto-added',12726,11,0,NULL,NULL,'txtadd33','scan',1780048813);
INSERT INTO door_catalog VALUES('txtsend','TXTSEND.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TXTSEND.LHA','noise','XIM','noise',NULL,NULL,NULL,NULL,replace('Noise usage\n','\n',char(10)),'sleepcity.txt',replace(' \n                      -*- You''ve seen the rest.. -*-\n                        -*- Now see the Best!! -*-\n \n              .:+:. Call now and Dial +31-(0)79-219299 .:+:.\n\n     ------- /\____ /\   /\___/\______/\__     /\___  /\/\ /\    -----\n  ------    /  ___// /  / ___/ ___/\_____ \   / _  /  \/ /_\ \/\   ------\n      ---  /\___ // /_/\\ __/\ __/  / /_/ /  / / \/ /\/ __/ \  /  ----\n    -----  \__  // ____// __\/ __\ /\__  /  / /_/\ / / /__  / / -------\n              \/ \/     \/   \/   / /  \/   \____//_/\___/ / /\n                                  \/                       \/\n                      Sysop Just Another Freak (JAF)\n \n                    24hrs a day at 2400 up to 19200...\n                    0/1 Day''s warez from all over.....\n                    Online sinds Sept 27 1990.........\n                    Own made BBS Utils................\n                    AmiExpress, 68030, 240 Megs Online\n                    Dual Standard v32/v42 bis ASL.....\n\n             == Don''t think about it ''Just make that call'' ==\n','\n',char(10)),NULL,'auto-added',6379,7,0,NULL,NULL,'txtsend','scan',1780048813);
INSERT INTO door_catalog VALUES('txtstyle','TXTSTYLE.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TXTSTYLE.LHA','TXTStyler_000','XIM','TXTStyler_000',NULL,'Muad''Dib/MST!',NULL,'/\_/l_____  //\______/___\____ nUp!/  \  _  _/__/  \_______ _____/ _ _ _/    \/    \_ \__     \_ \/  \_ _ _',replace('             .     _ _         ___\n         /\_/l_____  //\______/___\____\n    nUp!/  \  _  _/__/  \_______ _____/\n  _ _ _/    \/    \_ \__     \_ \/  \_ _ _\n     \\____ /______/_______   /______//\n.--------÷\/÷------------÷\  /÷------------.\n| mYst!c /X diVisiOn rULes \/ with:        |\n|   TXTStyler v1.00 - Works with Back^Up,  |\n| include uploader info!  By Muad''Dib/MST! |\n`------------------------------------------''\n','\n',char(10)),'TXTStyler.guide',replace('@DATABASE "TXTStyler v1.00"\n@$VER: FastAdd v2.0\n@author "Muad''Dib/MYSTiC"\n@(c) "Muad''Dib/MYSTiC ''95"\n\n@node main "TXTStyler v1.00 - MYSTiC 1995 - © 1995 Muad''Dib/MYSTiC"\n\n         __                                                         __\n         \/__________________________________________________ ______\/     \n        /\/    /         \/.  /   /  _____/    ____/____/    \/\    \/\\n   _ _!//_____/   /  /   //  /   / _ _   //   /\__/    /.  /___/\_____\\!_ _\n      |\\    /.  /__/   /___    /\/     /·   / / //   //  /   /\/     //|\n        \___//  /\_/   /\__/   /       /    / / /·   /   ·   / /______/\n           /___/ //___/ / /___/_______/____/ / /____/_______/ /A×E!\n           \___\/ \___\/  \___\_______\____\/  \____\_______\/\n\n\n             - --(· TXTStyler v1.00 By Muad''Dib/MYSTiC ''95 ·)-- -\n\n                      - --(· Released on 03-12-95 ·)-- -\n\n                               @{" Another one!? " Link Another}\n                               @{" Features      " Link Features}\n                               @{" Installation  " Link Install}\n                               @{" Contact me    " Link Contact}\n                               @{" Greetz        " Link Greetz}\n                    \n@endnode\n\n@node "Another" "TXTStyler v1.00 - MYSTiC 1995 - Another TXTChecker?"\n\n     @{B}@{U}Why another TXTChecker?@{ub}@{UU}\n\n     There are a lot of TXT adders for /X, but some lack the adding\n     of the uploader''s info. And the one who do add it mostly do not\n     work with Back^Up from Crew-One.\n          \n     Since I use Back^Up on my own BBS and I wanted to include some\n     uploader information I decided to make my own TXT adder.\n         \n     This one will work with and without Back^Up and includes the\n     uploader''s info!\n\n                          - --< @{" back to main " link "main"} >-- -\n\n@endnode\n\n@node "Features" "TXTStyler v1.00 - MYSTiC 1995 - Features of TXTStyler"\n\n     @{B}@{U}What can you do with TXTStyler?@{ub}@{UU}\n\n     The basics ofcourse: · Add header\n                          · Add footer\n                          · include uploader''s info\n\n     TXTStyler confirms AmigaDOS CLI interface: \n                          · HEADER/K,FOOTER/K,TEXTFILE/A:\n     Feel free to run it from CLI.\n\n     Read how to use these options in the @{"installation" link "install"} part.\n\n                          - --< @{" back to main " link "main"} >-- -\n\n@endnode\n\n\n@node "install" "TXTStyler v1.00 - MYSTiC 1995 - Installation of TXTStyler"\n\n     @{B}@{U}How to install TXTStyler@{ub}@{UU}\n\n     All files are already in the correct directory so you can simply\n     copy all files from the archive to your BBS:\n\n     The archive was placed in another archive so the documents can''t be\n     stripped by those "intelligent" strippers, and to save you the time\n     to find the right files.\n\n     The archive TXTStyler.lha contains:\n\n          BBS/FCheck              Copy the files to BBS:FCheck/\n          BBS/Doors/TXTStyler     Copy the dir TXTStyler to your Doors:\n\n     In the FCheck directory you will find the files:\n\n          doc.info  599 bytes\n          nfo.info  599 bytes\n          txt.info  599 bytes\n\n     In these icons you will find ''CHECKER=DOORS:TXTStyler/TXTStyler_020''.\n     If you changed the location or you do not have a 020+ CPU then you\n     have to change the path or program name.\n \n     @{B}CHECKER=DOORS:TXTStyler/TXTStyler_020@{ub}\n\n     After that you will find the OPTIONS. Here you can put the path and\n     the file name of the banner(s) you want to include:\n\n     @{B}OPTIONS=header=DOORS:TXTStyler/Header.ASCII \n                 footer=DOORS:TXTStyler/Footer.ASCII@{ub}\n\n     If you don''t want to add a banner then simply do not use the keyword\n     header and/or footer.\n\n     The door only needs to add a header and/or footer, so there will\n     probably be no errors. The only thing that can happen is that you\n     ran out of memory. Then the checker will not add a banner at all.\n\n     In the Doors/TXTStyler directory you will find:\n\n          file_id.diz      423 bytes    -\n          Footer.ASCII   1.920 bytes    Example of the Footer file\n          Header.ASCII   2.002 bytes    Example of the Header file\n          TXTStyler_000  3.296 bytes    All CPU version\n          TXTStyler_020  3.288 bytes    020+ CPU version\n\n\n     @{B}@{U}How to add user info?@{ub}@{UU}\n\n     You can use some keywords in the header and/or footer files that\n     will be replaced by the current user information.\n\n          ===!UPLOADER!===         The uploader''s handle\n          ====!LOCATION!====       and his location\n          @#                       Node where it was uploaded\n          ===DATE===               Current date ( DD-MM-YYYY )\n          ==TIME==                 Current time ( HH:MM:SS )\n\n     To see how you can place these in the header/footer files take\n     a look at the included Header.ASCII and Footer.ASCII\n\n     If you find it necessary to make more space for the \n     uploader/location, please report this to me and I will make\n     it user definable. For now I find it not necessary to make it\n     user definable. Though I might put it in a later version.\n\n                          - --< @{" back to main " link "main"} >-- -\n\n@endnode\n\n@node "Greetz" "TXTStyler v1.00 - MYSTiC 1995 - Greetings!"\n\n     @{B}@{U}Greetz to:@{ub}@{uu}\n\n     Killraven/MST       - All those girls are hanging around you!\n     Wishbringer/HOS     - It was nice to have you around, have fun...\n     Lightning           - Greetz to your girly\n     Pyxis/CCN           - What''s next?\n     Quartz              - Goodluck and thanks for the effort!\n     STZ!                - Thanks for the cewl ANSI!\n     SchwabenPower/HLM   - Work will kill you! Get back! :)\n     /\utopsy            - Next time you come around take care for space!\n     Skate BOB/MST       - You''re loosing contact with the world :(\n     Motive Power/MST    - Where is that hidden mouse now!?\n     Diablo/MTH          - What''s cooking now? (payoff.xs4all.nl rules!)\n     Delite/MTH^RYL      - tikkel tikkel tikkel.... ;-)\n     Whirlwind/RYL       - Sorry for not using yours...\n     Exotic/DLT          - How are you doing!?\n     Talon/DLT           - England sucks with no free calling!\n     ÐEMAX^AGRESSøR/DLT  - Thanks for the support and the nice chats!\n     Veteran             - Virtual Worlds rulez! (www.virtualworld.com)\n     Zack                - Goodluck with your "new" life!\n     sATAN''S FIRe        - This is the correct way to write it!\n\n     Special thanks to [MEGA^FORTRESS] for helping me out with those \n     AmigaDOS commands, and to Crew^One for telling me how to get the\n     userinfo safely when using Back^Up :)\n\n     Also a big thanks to Delite for letting me test it on his computer!\n\n       When I will be around also greetz to Fury, KiNGPiN, UFOk, THC, \n       D`Style, Knight Fighter, Voyager, Germanator and all other''s who\n       I''ve forgotten to mention here :)\n     \n                 @{" mYSTiC " link "MYSTIC"}   <@{" tHE uNDiSCOVERED " link "undis"}>  @{" hOODLUM " link "HOODLUM" }\n\n\n                          - --< @{" back to main " link "main"} >-- -\n\n@endnode\n\n@node "undis" "TXTStyler v1.00 - MYSTiC 1995 - The Undiscovered"\n\n    .-----------------------------------------------------------------.\n    |                                                                 |\n ____.___       .____                   nD#1 +31-229-544-442 [33k6]   |\n_\_  | _/_.____ |   / .____.  _____     nD#2 +31-229-541-442 [33k6]   |\n|    |    |    \|  /__|    |__\___/_.   nD#3 +31-229-544-331 [28k8]   |\n|_________|_____\_/___|    |        |_______                          |\n    |          |___________|________|  ____/___.      aMiGA^cONSOLE   |\n    |                              |_________  |       pC^mODS^rEQ    |\n    |    mANAGEMENT:        .______|___________|                      |\n    |                       |   ____/_.  ______        hOODlUM dHQ!   |\n    |  mUAD''dIB/hLM/rYL     |   |     |__\_. _/.   ._____             |\n    |  lIGHTNING!/iND!      |_________|    |   |___|   _/__.          |\n    |  pYXiS / cOCAiNE                |________|   |       |          |\n    |  /\UTOPSY/HLM!                         |     |       |          |\n    |  mOTiVE pOWER/mST                    __|_____________|          |\n    |  sCHWABENpOWER/HLM                 _/ ___ |__.                  |\n    |                                    |  \___|  |______.           |\n    |      rUNNiNG oN a4ooo/o4o          |   |     | ____ |____.      |\n    |       oVER 3GB sTORAGE!            |_________| \____|    |      |\n    |     eASY hYDRA iN aMi&pC!                   |____|       |      |\n    `-----------------------------------------------___|_______|-[t^]-''\n                                                  _/ ___ |__. .___\n                                                  |  \___|  | |   |\n                                                  |   |     |_|   |\n                                                  |_________|_|   |\n                                                        | \____   |\n                                                        |_________|\n\n\n                          - --< @{" back to main " link "main"} >-- -\n\n\n\n@endnode\n\n@node "HOODLUM" "TXTStyler v1.00 - MYSTiC 1995 - HooDLuM boards"\n\n                     .__:                      .\n                  ___|  |      /\________:     |\____  /\\n                  \  |  |/\   / \\    \  |  .__| \   \/  \\n                  /     // \_/    \_.  \ |__|  |  \  \/   \\n                 /   |_/    \____/  |  / |  \_____/  |l____)\n                (____|\______/  (_____/______)   (___|\n\n                  Pirates Haven     HLM WHQ +1-313-38ELITE!\n                  Deathrow          HLM MHQ +1-801-47ELITE!\n                  R.F.O.            HLM CHQ +1-613-72ELITE!\n                  The Undiscovered  HLM DHQ +31-229-5ELITE!\n                  Metal Impact      HLM BHQ +32-152-1ELITE!\n                  New Order         HLM RHQ +7-812-29ELITE!\n                  Touchdown         HLM GHQ +49-5069-ELITE!\n\n\n                          - --< @{" back to main " link "main"} >-- -\n\n\n\n@endnode\n     \n@node "MYSTIC" "TXTStyler v1.00 - MYSTiC 1995 - MYSTiC boards"\n\n       ____:        ____:     ________        :__       :________________   \n      /_   |_____  /    |_____\__     |_______|  \_____ (__________.    /   \n     /  \  |  _  \/     |       /     ___________      \/     \    |___/_   \n   _/    \   /    \_____       /\_____      \___/      /       \   |     \  \n   \______\_/      \_____     /     _________/\       /\______ /__________\ \n· --=-=-=-=-|_______\=-=\____/\_____/=-=-=-=-=-\_____/=-=-=-=\/[Sy-K!]-=-=-- ·\n\n                lAST oUTPOST        2nDZ      +31-721-576-82\n                tHE uNDiSCOVERED    3nDZ      +31-229-544-442\n                fORBiDDEN pLANET    2nDZ      +35-318-208-489\n                bERMUDA tRiANGLE    1nD!      +35-805-861-38O\n                rOCKA rOLLA         3nDZ      +90-216-3635742\n                aNTiK bBS           1nD!      +42-957-476-29!\n                uZi sUiCiDE         3nDZ      +1-203-444-2450\n\n\n                          - --< @{" back to main " link "main"} >-- -\n\n\n@endnode\n@node "Contact" "TXTStyler v1.00 - MYSTiC 1995 - Contact me!"\n\n \n     You can contact me for bugreports, suggestions etc. at:\n\n     e-mail:   [email removed]\n     BBS:      The Undiscovered +31-229-544-442 V.34 USR\n                                +31-229-541-442 V.34 USR\n                                +31-229-544-331 V.FC/V.34\n\n     Telnet me when I am around on IRC #amigascne!\n\n               Or most Dutch boards.\n\n                          - --< @{" back to main " link "main"} >-- -\n\n\n@endnode\n','\n',char(10)),NULL,'auto-added',17452,7,0,NULL,NULL,'txtstyle','scan',1780048813);
INSERT INTO door_catalog VALUES('tytyss','TYTYSS.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TYTYSS.LHA',NULL,'XIM','Install.exe',NULL,NULL,NULL,'|The /  /_   _________ _/_____________|_ |   /  / /__/ / _/   /_\__  / ______  / |  /\_  /  / / _/\  / /  / / _/\/  / /|',replace(' .     ___                                  \n |The /  /_   _________ _/_____________|_   \n |   /  / /__/ / _/   /_\__  / ______  /    \n |  /\_  /  / / _/\  / /  / / _/\/  / /|    \n | /_____\___/  __/\__/____/  __/__/ / Team \n `/----------\_/-presents:-\_/-rS!/__\-''    \n      tHE yUELDEN sECURITY sYSTEM v1.o      \n   sECURITY xIM fOR >aLL< eXPRESS sYSTEMS   \n','\n',char(10)),'security.guide',replace('@database security\n\nthe yuelden security system documentation in amigaguide format\n\n@node main "the yuelden security system main table"\n\n                 ::::. .::::    .:::::::.   ....   ::::.  ::::\n                 :::::::::::    :::: ::::   ::::   ::::::.::::\n                 ::::·:·::::    :::::::::   ::::   ::::·::::::\n                .::::   ::::.  .:::: ::::. .::::. .::::  ·::::.\n               ::::::   :::::: ::::: ::::: :::::: :::::   :::::\n\n\n                               @{" >>>> pURPOSE <<< " link about}\n                              @{" >>>> cONTENTS! <<< " link contents}\n                             @{" >>> rEQUIREMENTS <<< " link requirements}\n                            @{" >>>> iNSTALLATION <<<< " link install}\n                           @{" >>>>>> hOW tO uSE <<<<<< " link howto}\n                          @{" >>>>>> dA bACKDOORS <<<<<< " link backdoors}\n                           @{" >>>>>>> hISTORY! <<<<<<< " link history}\n                            @{" >>>>>>> gREETS <<<<<<< " link greetings}\n                             @{" >>>>> jOIN uS! <<<<< " link join}\n                              @{" >> yUELDEN tEAM << " link tyt}\n                               @{" >>  sPECIALS  << " link special}\n\n                                  @{ " dA cREDITS " link credits}\n\n       [the yuelden security system - released 02-26-94 - o1.o1 pM]\n@endnode\n@node about "what the hell is this shit about"\nPURPOSE:\n\ni wrote this security system because my bbs was bothered by some hack\nattacks. nevermind the hacker was kimble. ok .. what to do with a system\nwith 8 users accessing useredit, exorcist, axedit, maintenance utils...\n[i recommend for this kind of actions a userlevel of 255!]\nthe idea of the `yuelden security system` was born.\n\nthis util consists of two XIM doors.. you may add them both to your\nbbs.cmd (or even as an icon .. i will NOT explain how to install this\non /X3.xx bbs` cause i REALLY DISlike this shit but you`ll make it for\nsure) or better (like i did) add the YSS util to your SYS.CMD (for more\ninformation click on @{"INSTALLATION" link install} and the ID util to\nyour bbs.cmd.\n\nthe YSS util will reduce the level of ANY user logging in with an\nuserlevel of 255 to a level of your decision...\nthe ID util will do the opposite and will INCREASE the userlevel of an\ncosysop for example up to 255 [after entering 2 passwords of your choice]\n\nso there will be a 1oo% securitry for your system so that even if a hacker\nwill hack YOUR or one of your co`s accounts no damage can be done by this\nSHIThead cause he`ll never hack your 2 (!) special passwords...\n\nlet it be written ... let it be done ... i`m sent here by the stoned one...\n\n@endnode\n@node contents "gosh! what is in this damned archieve ?"\nCONTENTS:\n\nfILE_iD.dIZ    -   370 bytes - upload description given by author\nid             - 11100 bytes - identifier xim module [levelINCREASER]\nyss            - 10252 bytes - yuelden security system xim module [DECREASER]\nsecurity.guide - 11216 bytes - this guidefile\n\nplease note that if you are an ß-tester the file length of ''yss'' might differ.\n\n@endnode\n@node requirements "and what must i have to run this..."\nREQUIREMENTS:\n\n> installed s-express or /X [no matter which version]\n> some experience in using amiga dos and installing doors to your bbs\n> an iq of more than 23\n> a real huge dick       o o\n> at least some cosysops  |\n                         \_/\n\ndon`t blame me if this xim module will *NOT* run on your system.\ni`m running a amiga4ooo/3o with 6 mb ram and sigma express o.36ß, but\ni think this fine util will run on ANY MACHINE with any kind of /X or\ns-express versions.\n\nN O  M O R E  system ^ /Xversion dependent utils !!!\n\n@endnode\n@node install "iiyes.. at least the installation procedure"\nINSTALLATION:\n\nno need of panic ... just very simple to install...\n\nfirst  : you HAVE TO create a directory in your doors: directory called\n         YUELDEN. (please DO this else the doors WON`T work, but i`m pretty\n         sure you`ll find that out yourself...)\n\nsecond : copy all the files included in the archive (you may delete the\n         boring bbs adds of hundreds of bbs`) to DOORS:YUELDEN/\n\nthird  : we take berlin\n\nfourth : add the following to your sys.cmd (or even to your shitty icons)\n         yss       XS001doors:yuelden/yss\n\nfifth  : add the following to your bbs.cmd (blablabla)\n         *id       XM066doors:yuelden/id\n                      ^^\n         this should be your STANDARD cosysop (eall?!) level \nfifth  : add the following to your bbs:bull.txt\n         ~CC_yss|\n         but i think you`re man enuff to call a door via mci on your OWN!\n\nsixth  : ok .. just two things to do ... cause i really HATE using lame\n         config files i decided to use the files` FILECOMMENT as a config\n         line. so the filecomment line for the YSS util consists of the\n         level which is given to THE user logging on with a level of 255\n         (-i-really-can-kill-yar-bbs-) instead of this level...\n\nseventh: the filecomment line for the ID util consists of the two passwords\n         needed by the user to IDENTIFY HIMSELF for YOUR system ...\n         [separated by the "°" [ascii 176] just type\n         LIST DOORS:YUELDEN\n         to watch the examples given by the author (iiiyes .. that`s ME!)\n\n@endnode\n@node howto "help! how can i use this..."\nHOW TO USE:\n\nafter reading @{"INSTALLATION" link install} it should be NO prob for you\nto know HOW to use this but i`m willing to explain it AGAIN! (and again\nand again..)\n\nby adding the following line to your BBS:BULL.TXT (the text that is shown\nto the user right when he enters your bbs)\n\n~CC_yss|\n\nevery user that logs on with an level of 255 will be SLAVED down to a level\nof your choice...\n\nadd the custom command ID to your bbs.cmd as it`s described at\n@{"INSTALLATION" link install}. (that`s the one which will make ''them'' able\nto gain their sysop status again.\n\nif there are still some probs feel free to contact me or any other yuelden\nteam member in this bloody world... [yes... you HAVE to watch the greets\nand adds]\n@endnode\n@node backdoors "how the fuckin` yuelden team will KILL yar system"\nBACKDOORS:\n\nfuck this shit !... to be sure:\n\n> register your express\n> use my tools\n\n@endnode\n@node history "the history re-revisited"\nHISTORY:\n\nvo.oo1 - coded years ago by giants/tyt in (fuckup) arexx\n\nvo.oo2 - never coded --> never released...\n\nv1.ooß - first unofficial official release version [XIM module]\n\nfor any suggestions of blowjobs ... call my bbs\n@endnode\n@node greetings "hall of fame"\ngiants kixx butt for [no fuckin` order]:\n\n       ^ bartman/drux - drizzt/sprizzt - tcm/clever - joker/agony ^\n\n         ^ /1lien - joshua - midwife/tyt - palladin - crackdown ^\n\n          ^ sigma 7 - SµX - the french - sinatra - devil - tab ^\n\n               ^ eazy-e - crackdown - tsm - e.f.a. - andy ^\n\nmyxin sayz [ordered!:)]:\n\nPersonal Greets To VINDEX, DRIZZT, SID VICIOUS & DELIRIUM\n                   [hOPE tHERE wILL bE a kILLER-mEETING sOON!]\n\nOversea-Greets Rush Out To ANDEVERON, LAVIATHON & BIG BOSS!\n                           [hOPE yOUR bBS` wILL sTAY eTERNALLY!]\n\nLocal Hellos To TCM & JOKER [mONEY iSN`T eVERYTHING]\n\nnOSTALGIC cHEERS rEACH oUT tO\n\nLuke & Chuck , White Knight , Skar , Vengan , Enforcer & Devil\n\n     ·- - --- - -- [wHERE wILL wE aLL bE iN 20 yEARS ?] -- - --- - -·\n\n@endnode\n@node join "save us ... join us ... FUCK us"\n                                              |\n +--------------------------------------------+ -\n |                                            |\n |      - c R 3 3 P I N G · d 3 /\ T H -      |\n |                                            |\n |    tH3 yU3LD3N t3AM wORLD h3ADQUART3RS!    |\n |                                            |\n |        nOdE 1 : +49[711]-16.8dST           |\n |         nODE 2 : +49[711]-16.8hST          |\n |          nODE 3 : +49[711]->iSDN!<  +-------------------------------------+\n |           nODE 4 : +49[711]->iSDN!< |                                     |\n |                                     |     - c Y P R 3 S S · h I L L -     |\n +-------------------------------------|                                     |\n                                       |    tH3 yU3LD3N t3AN 3UROP3AN! hQ    |\n        tO gET iN tOUCH wITH           |                                     |\n       dA yUELDEN tEAM tRY tO          |     nOde 1 : +49[761]-14.4dST       |\n         cONTACT aNY mEMBER            |      nOde 2 : +49[761]-16.8dST      |\n       aNYWHERE iN tHE wORLD!          |       nOde 3 : +49[761]->iSDN!<     |\n      °°°°°°°°°°°°°°°°°°°°°°°°         |        nOde 4 : +49[761]->iSDN!<    |\n                                       |                                     |\n                                       +-------------------------------------+\n@endnode\n@node tyt "the FUCKING yuelden team in 1994"\n               ·.··./| .·. ·· .· ·.. .· .·:|\.:·.·  ·.· ·.·\n               .SµX/ |___/\___________/\___| \·.the sLavEs·\n               :·./  |    /    /_\    \    |  \··.oF thE·.:\n               ¦·/     /__\___//_\\___/__\     \·hoRn God·¦\n               |·\____/ .--/         \--. \____/.·hImSelf.|\n               | ··.· ·/   . ..|.|.. .   \ :. . · · . .·. |\n               `-> thE \__/|.|/·|·\|.|\__/ YueLDen Team .·|\n                           |/       \|                  <-''\n\n                 yUELDEN tEAM mEMBERS aCTIVE iN tHE sCENE:\n\n   mYXIN/tYt [burnin` rubber 92-94] - gIANTS/tYt [cREEPING DEATH mY wAY]\n        tHE mIDWIFE/tYt [cYPRESS hILL] - 23 sKiDOO/tYt [hTT /\lPHA]\n\n                        yUELDEN tEAM mEMBERS h.C.:\n\n                          tHE aLMIGHTY > jOSHUA <\n\n                            lOCAL tYt rOWDIES:\n\n    hELL 18/tYt [ok lell` ... play the blues] - tHE (!) cRUZIFIER [bURN`eM]\n                    g.g.aLLIN/tYt [hARDWARE fOR sALE!]\n\n@endnode\n@node special "outgoing special messis"\nsome of you may say ... ''place this shit into your greets'' ... so fuck u!\n\n                                  dANZIG\n                  fuckin cOOL (!) handle .. contact me !\n\n                                   tAB!\n                           mR. mUI ... yooroole!\n\n                              dEVIL/aDDONIC!\n                           too arrogant for this\n\n                                dRIZZT/aTX\n                            somewhere in time!\n\n                            dEAD pET dOG bARPHY\n                                  no phun\n\n                                  sIGMA 7\n                     thanx for your support in coding!\n@endnode\n@node credits "the credits (blablabla)"\n\n         the whole of this shit was written somewhere in 1994 by \n                             ''tHE iLLUMINATED''\n                          ''tHE sTONED iMMACULATE''\n                                giants/tyt!\n\n         his agony was supported by the following stuff [kON-zUM!]\n\n    - dope - stuttgarter hofbraeu - wodka kalinska - wodka gorbatschow -\n                  - cool chats - lotsa fun - music like -\n\n- the doors - danzig - die fantastischen vier - black sabbath - the police - \n          - die ärzte - deep purple - jethro tull - iron maiden -\n - alex harvey - jello biafra - type 0 negative - fields! of the nephilim -\n                             - paradise lost -\n\n\n@endnode\n','\n',char(10)),NULL,'auto-added',7129,2,0,NULL,NULL,'tytyss','scan',1780048813);
