INSERT INTO door_catalog VALUES('tzz_wa10','TZZ-WA10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TZZ-WA10.LHA',NULL,'XIM','________________',NULL,NULL,'TZZ','|____  ___|__   /______ /   \    / //\     / ...//   \\\///    \  //',replace('  ________________\n |____  ___|__   /______     \n    /   \    / //\     /\n...//   \\\///    \  //\n: /_______\/_______\ /.rED.\n:               //  /\    :\n:  pRESENTs A  //    \\   :\n: nEW aIM dOOR/________\  :\n:  tHE cOOlEST wALL eVER! :\n`-------------------------''\n[ M-E ]·-·-·-·-·-·-·-·-·-·-·-·-·-·-·-[ M-E ]\n','\n',char(10)),'wally.doc',replace('     ___    ___ __     __   __  ___  ___   ______  __  __  _______\n     \  \/\/  //  \   |  | |  | \  \/  /  |      ||  /\  ||  ____/\n      \  /\  // -- \  |  |\|  |\ \_  _/   !___ __||      ||  _)\n       \    //      \ |    \    \ |  |      /  \  |      ||   \            \n        \__//___\/___\|_____\____\|__|     /____\ |__\/__||____\           \n\n               cODE =>tHE FUGITIVE/TzZ  ART =>rED.R/tZZ                     \n_______      _______  ____      ____      ____     ______   ____  ____     \n\      \    /      / /    \    |   |     |   |     \    |   \   \/   /     \n \\     \/\/     // // -- \\   ||  |/\   ||  |/\    \_  |    \\    //       \n  \\            // //      \\  ||  !  \  ||  !  \    || | _  //    \\       \n   \____________/ /____\/____\ |_______\ |_______\   |__||_|/___\/___\\n\n               Wally The Wall 1.0 © 1995/TzZ   Documantaion\n             -------------------------------------------------\nINDEX:\n\n                                  A.Why?\n\n                                B.CopyRight\n\n                              C.Installation\n\n                                  D.Usage\n\n                              E.ReGiStrAtion\n\n                                F.Grettings\n\n\n\n\nWhy?\n¯¯¯¯\nWhy Not? It''s Pretty cool I ThinK!\n\n\n\n\nCopyRight --->©\n¯¯¯¯¯¯¯¯¯\nAll rights are reserved to The Nuzzels® ©1995 It should only be spread in it''s\norginal package or with our permision...\nCoDE:The Fugitive\nArT:Red.R\n\nInstallation:\n¯¯¯¯¯¯¯¯¯¯¯¯¯\nAny /X sysop should be able to do It!\nJust Copy Da Dam Thing But If That''s To Complicated follow the instruktions \nbellow:----------.\n                 ! \n.----------------· \n!\n·->Simple Just Do LIke This:\n\nNewWally.rexx ----> doors:tZZ/Wally/ \nwall.info --------> BBS:CoMMaNDS/BBSCMD/\nwall.data --------> doors:tZZ/Wally/\nWally.Doc --------> Hmm You Figure!\n\nThen If Da Dam Thing Don''t Start Check this things:\n\nTrouble shooting:---> Make Sure RexxMastIs Running---->Still Doesn''t work??---.\n                                                                              :\n.-Now What It still Doesn''t Work<-----Make Sure RX IS rEsIdEnt<---------------·\n:\n·-->Hmm have you assigned Rexx: to sys:rexxc??--------->It Don''t Work---.\n      									:\n.--Have Ya Tampered With The Arex File????????<-------------------------·\n:\n·----->It Works but Only Loading Data Comes Up?-------------------------.\n									:\n.--Hmm Well than it''s the data file that''s wacco just delete it!<-------·\n:\n·----Any Other bugs contact The fUgItive\nUsage:\n¯¯¯¯¯¯\nIf YA InstAllEd It Right Just Write wall or put it in a qute text with ~CC_WALL\nAnd If Ya can''t do that sell yahr computer!!!!\n\n\nReGiStRaTiOn!\n¯¯¯¯¯¯¯¯¯¯¯¯¯\nIsn''t That Silly?\nWell if ya wan''t yahr own design just upload 15 Meggs ore moreon one of the\nthe nuzzels HQ''s and i will (The Fugitive) will do sum minor editation of the \ncode for yahr own design you can get yahr own ascii door name etc...\n\nGrettings?!#\n¯¯¯¯¯¯¯¯¯¯¯¯\nGrettings Goes To in No SpeCial Order:\n\nTiNy			<---	For Being A Good Party PaL\nKeRmIt			<---	For Sup(orting) me with boze\nGuLLeFjuN		<---	For BeIng A Nut Case\nHoBGoBlin		<---	?????\nGaJaN			<---	One Of The CoolEst In the ScEne\nWunderBaum		<---	Wake Up!\nBullFrog		<---	Where the hell Are Yo?\nLacoste			<---	AnNa Says HI!\nFire Bug		<---	I miss You hehe:)\nCrowley Triumph		<---	Were Would sweden be With Out Yahr Board\nFenriz			<---	I hope Ya Like The Doors I wrote For ya!\nDrr			<---	I CaN''t Compile in the cfg file in this one:)\nStone			<---	ThanX for Da AscII\nZCANDALER		<---	FoR Da Great ElIte List\nKid Curry		<---	FoR All Those Nice messages\nCucky			<---	For HelPing Us With the Modems\nSeawolf                 <---    fOR the GrATe asCii and aNSI! \nReX                     <---    lIKE tHE niCE pUMPING oN b-H!\nMiTaC			<--- 	FoR HavEngS thOse Nice Cd-RoMs\nZoRRo			<---	How''s The KoRvS? (ThAnX 4 tEsTing Da DooR)\nHaMlEt			<---	tHaNx fOr TeStInG dA DooR & HelPinG red.r \n				with the modem... \n\nAnd Alot More But I''m To Tired Now (03:57:06 PiP)\n\n\np.S rINGDOWN tHE tZZ bOARDS d.S\n                    ________________________________________\n                    \::::···       _  _  _   _  ___  ···:::/ \n                     \::       /\ (_ (_ (/_ |-''  |      ::/               :\n __|__________________\__________________________________/________________|___\n   |      ...                                                        ..   |\n   |     :  : ®®®®®®®® ®®®®®®®® ®®®®®®®® ®®®®®®®® ®®®®®®®® ®®®®®®®® :  :  !\n   | ....:  : ®®®®®®®® ®®®®®®®® ®®®®®®®® ®®®®®®®® ®®®®®®®® ®®®®®®®® :  :..:\n   !:       : ®®®¬¬®®® ®®®¬¬¬¬¬ ®®®¬¬¬¬¬ ®®®¬¬¬¬¬ ®®®¬¬®®® ®®®¬¬¬¬¬ :     :\n   ::       : ®®®®®®®® ®®®      ®®®      ®®®®®®   ®®®®®®®® ®®®      :     :\n   |:       : ®®®®®®®® ®®®      ®®®      ®®®      ®®®®®®®® ®®®      :     :\n   |:       : ®®®¬¬®®® ®®®®®®®® ®®®®®®®® ®®®®®®®® ®®®      ®®®      :     :\n   !:       : ®®®  ®®® ®®®®®®®® ®®®®®®®® ®®®®®®®® ®®®      ®®®      :     :\n   ::       :.......................................................:     |\n   |:                          __________________                         |\n   |`--> +46 (0)523-660501     \     tZZeHQ     /       ArT GfX by...     |\n___|____________________________\ Will ReOpen  / _________________________|____\n   |                             \  Late Sep  /                      stone|\n   | cREW. The FugitivE           \   1995   /                            :\n   :       ReD.r                   \        /                             :\n   :                                \:....:/                              :\n   ·.................................\::::/...............................· \n                                      \::/  \n                                       \/\n   _____    _____________________________\n  |   _ |  |     ||     ||   _ |\   !   /  _ oN: +46-(0)523-661019 _\n  |  ___l_ |  !  ||  !  ||   __l_\_ ·  /   `-----------------------'' \n  ||      ||| :  ||| :  |||      |||  |    \n  ||  --  |||    |||    |||  --  |||  |·rED·····························:\n  |_______||_____||_____||_______||___|                                 :\n        :                __    __ _________________  ______  ____  ____ : \n        :  cALL aND     |  |  |  ||      ||        ||    _ |_|  |  |  | :\n        :               |  |--|  ||  --  |l____ ___||    \__/|  !--!  | :\n        :   eNJOY!      ||       |||     |   /  \   ||    __ ||       | :\n        :···············||       |||     |  //   \  ||   / | ||       |·:\n        :               |___\/___||__\/__| /______\ |______| |___\/___|	:\n  ......:....								:\n  :     :       - Amiga - Pc - Nice Sysop - Kewl Board - 0-2 -		:\n  :     :								:\n  :                          _ sYSOP:rED.R/tZZ _   			:\n  :      								:\n  :   | kREW: mETAL wARRIOR - sEAWOLF - rEX - mR.BiGSHOT - tHE fUGITIVE :\n  :                          						:\n  :                       ..............................................:\n  :  .....                :\n  :..:...:                :\n     :....................:\n','\n',char(10)),NULL,NULL,9466,5,0,NULL,NULL,NULL,'scan',1780048813);
INSERT INTO door_catalog VALUES('tzz_wa96','TZZ-WA96.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/TZZ-WA96.LHA',NULL,'XIM','_______ ___',NULL,NULL,'TZZ','!_ __|! | _/.:Finally it''s here the:. .----. /  \   | )_::new version of Wally!:::|T  N| \  /_|_|___|_________________________|H  U|',replace(' _______ ___                          \n!_ __|! | _/.:Finally it''s here the:. .----.\n /  \   | )_::new version of Wally!:::|T  N|\n \  /_|_|___|_________________________|H  U|\n |\/\  | | |     /    /   /  | _     /|E  Z:\n | _ \ | : |\__ /\__ /  \/|  |/ \_ \/ |   Z!\n | \   |   | / /\_/ /\_ /\|  |\  \  \ |9  E.\n l__\__|___|/____/____/___\____\____/ |6  L:\n<=============================[rED!]=>|   S·\n.-------------------------------------''    :\n! 0% LAME 100% FASTER 200% COOL... Wally96 !\n`------------------------------------------''\n','\n',char(10)),'wally96.guide',replace('@database Wally.96\n@author "The Fugitive"\n@(c) "Copyright © 1996 The Nuzzels, Inc."\n@$VER: Wally 96 Guide 30/01/96)\n@node Main "Wally 96 Main Guide Screen"\n@{b}@{fg <shine}      @{b} @{u}c0DE [ THE fUGITIVE ] dESIGN [ RED.R ] [ tHE nUZZELS 96 ]@{uu}@{bb}\n\n                                                           \n                             @{"What Does It Do?" link Does}          \n                                                           \n                             @{"  Installation  " link Install}          \n                                                           \n                             @{"Copyright Notes!" link Copy}          \n                             \n                             @{"     USAGE!     " link Copy}                              \n                                                         \n                                                           \n           This is the full UNREGISTRATED version but who would\n                                                           \n            register an door that isn''t crippled in any way...?\n                                                           \n                      Well Free Doors To The Public!!\n                                                           \n.-------------------------------------------------------------------------->\n|      @{"Press Here To Come To The Great Gretting List" link GREET}\n`-------------------------------------------------------------------------->\n@endnode\n@node Does "What Does It Do?"\n@{b}@{u}What Does The Wall Offer?@{bb}@{uu}\n\n* Extremly Nice Output 10 Line Wall\n* User Can Be Private\n* Sysops See''s Who He Is Even When He Is Private :)\n* Sysops can FAKE handles Hehe:)\n* Sysops See''s Who He Is Even When Another Sysop Fakes Handle hehe:)\n* User Can Define Wich Color His Text Line Should Be\n* If User Don''t Write Any Thing At The "TEXT >:" Promt It Won''t Be Saved\n* Extremly Fast For Being Coded In Arexx\n* 100% Compatibel With Both S!X & /X\n* 5% IBM Compatibel\n* 100% TZZ PRODUCTION!!!\n@endnode\n@node Install "Installation!!!"\n@{b}@{u}INSTALLATION@{bb}@{uu}\n\n1.Make Sure RX Is Resident\n2.Make Sure YA Assigned REXX: SYS:REXXC\n3.Copy The Wall To DOORS:TZZ/WALLY96/\n4.Copy The Icons To BBS:COMMANDS/BBSCMD  OR S!X Add This Line To "BBS.CMD"...\n\nWALL      RM020doors:TZZ/WALLY96/wally96.rex\n\n5.Don''t Worry About The Data Files The Door Makes Em iT Self\n6.Run IT Like Hell Hehe\n@endnode\n@node Copy "Copyright Notes!!!"\n@{b}@{u}COPYRIGHT Notes!@{bb}@{uu}\n\nThis Wall Is Allrights Reserved To:The Nuzzels©, tHE fUGITIVE/tZZ, rED.R/tZZ\n\n\nBugs Reports To:\n\nEMAIL:[email removed] (tHE fUGITIVE)\n\n@{"Accept BBS     " link ACCEPT}     +46 523 660501          tZZ wORLD hEADQUARTERS\n@{"The Booby Hatch" link BOOBY}     +46 523 661019          tZZ sWEDISH hEADQUARTERS\n@endnode\n@node GREET "Greetings!!!"\nGrettings!\n@{b}@{fg <shine}\nFrom The Fugitive:\n\nGoes In No Special Order\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nKid Curry                 I''ll Write Ya:)\nStone & DRR               Hope Were Going To The Gathering Now\nGajan                     Mayby Well Trade ZIP-DISCS SomeDay\nRecall                    Ones A IHS MEBER:|\nDixy                      ~N Everywere\nWired                     Hope Ya Change BBS system\nLacoste                   Anna & Anna Thinks Yahr Qute Hmm Donno Why:)\nCrowley Triumph           Aren''t Ya Gonna Start One More Node:)\nBullfrog                  Lost In Cyberspace?\nFireBug                   Jävla Homofil hehe:)\nHobgoblin                 Hope Yahr Happy With Yahr New A1200 hehe\nZCANDLER                  For yahr Nice BOARD&LIST\nWunderbaum                Thanx for deleting me PK hehe\nChucky                    For Helping Me With My Stupid Modems hehe\nMitac                     For Helping My Neighbour with his stupid WIN95\nZorro                     Hows the hourses\nNow i''m to tired to go on if i missed anny please tell me an i''ll include\nyou in my next list hehe...\n\n\nFrom Red.R:\n\nGoes In No Special Order\n¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯\nGajan                     For you''r nice board & Disabled!\nUtopia                    For you''r nice prices..\nLacoste                   For some nice chats...\nCrowley Triumph           Leeching Bastard!\nFireBug                   Thanks for nothing!\nZcandler                  For my board add!\nChucky                    Hay! Modem fuck up, lets talk with Chucky!\nBullfrog                  For beeing an user who don''t upload!\nMetal Warrior             UPLOAD bastard! \nZorro                     For selling the shop and buy some horses...\nWunderbaum                Why are you here?\nKid Curry                 For a nice board to call..\nHamlet                    Some help and friendship..\nSeawolf                   Long time lo si..!\nReX                       Buy a real computer this time..\nDrastic                   For some art...\n\nAnd also thankx to all i have forgot...\n\n@endnode\n@node USE "Usage!!!"\nUSAGE?\n¯¯¯¯¯¯\nWell It aint that hard!!!\n\nBut if yahr stupid this is the way it is...\n\nUSER:\n\nGive A Line To The Gods [Y/N]?       <--IS THE FIRST LINE THE USER GETS\n\nThen he/she gets to chose color...\n\nTEXT >:                              <--HERE HE WRITES THE TEXT\n\nDo you wan''t to be Private [Y/N]?    <--HERE USER CAN BE PRIVATE BUT YOU WILL\n                                        STILL SEE WHO WROTE IT\n                                        \nSYSOP:\n\nIS THE SAM EXEPT THIS PROMPT:\n\nDo you wan''t to be Private [Y/N/F]?  <--F YOU SAY WHAT DOES THE F STAND FOR\n                                        WELL THIS IS COOL HERE YOU CAN FAKE\n                                        THE WROTEBY HANDLE...   SYSOPS CAN\n                                        STILL SE WHO WROTE IT...\n                                        \n@endnode\n@node ACCEPT "ACCEPT"\n     ....\n   .::::::.           wERE tHE lAME sTILL aRE lAME...\n  .::: S:::._______________________________________________________\n .::: T  :::|  .      · |        ·  |  ·  __  . |   · __ .  |  ·  |______\n ::: O  :::·|     |     |  ·  |    .|     _____/|  .        |          ·|\n :::.R :::· |:  . |¯¯¯¯¯|:    |¯¯¯¯¯|:    | .  ·|:   .    · |:  . |¯¯¯¯¯|\n ·:::M:::·  |::.       ·|::.   ·    |::.        |::.  |¯¯¯¯¯|::.      · |\n  ·:::::.   ¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯¯     ¯¯¯¯¯¯¯¯¯¯¯¯¯\n  .::··::.                  sYSOP tHE fUGITIVE\n ·:·    ·:·          AMIGA · PEZE · NILECITY · CD-ROM\n                          nUMBA:+46 (o)523-66o5o1\n\n                                   @{"BACK" link COPY}\n\n@endnode\n\n@node BOOBY "The Booby Hatch"\n\n                                   @{"BACK" link COPY}\n\n\n@endnode\n','\n',char(10)),NULL,NULL,9894,4,0,NULL,NULL,NULL,'scan',1780048813);
INSERT INTO door_catalog VALUES('t_enigma','T_ENIGMA.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/T_ENIGMA.LHA',NULL,'XIM','TIME.REXX','1.0',NULL,NULL,NULL,replace('TIME MANIA v1.0\n','\n',char(10)),'TIME_DOC.TXT',replace('\n                      TIME MANIA v1.0 BY ZAWRAN/INDEPENDENT\n                      ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n			     ReLeAsE dAtE: 08-22-93\n\n- WhAt U gEt WiTh ThIs PaCkAgE:\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n  NaMe                        SiZe  DeScRiPtIoN\n\n  TIME/TIME.CONFIG..........    23  ThE cOnFiG fIlE.\n  TIME/TIME_DOC.TXT ........  2199  DoCuMeNtAtIoN fIlE (dIz OnE).\n  TIME/TIME_HEADER.TXT .....   605  ThE hEaDer ThAt CaN bE sHoWn BeFoRe TIME\n  TIME/TIME.REXX ........... 52288  ThE mAiN rExX pRoGrAm ScRiPt.\n  TIME/TIME_RANDOM.TXT .....   390  RaNdOm SeNtEnCeS fOr ThE uSeR.\n\n  If AnY oF tHe FiLeS aRe Of AnOtHeR sIzE tHaN sHoWn AbOvE, tHeN cAlL mE aT\n  tHe NuMbEr ShOwN aT tHe BoTtOm Of ThIs DoCfIlE tO gEt A nEw CoPy.\n\n\n- WhAt ThIs PaCkAgE cAn Do 4 u ?:\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n  1)    It CaN sHoW a HeAdEr BeFoRe It StArTs.\n\n  2)	It CaN wRiTe A rAnDoM sEnTeNcE tO tHe UsErS bEfOrE tHe TiMe.\n\n\n- WhAt ThIs PaCkAgE nEeDs In OrDeR 2 wOrK:\n  ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n  AlL tHe UsUaL rExX lIbS aNd ThE RPStart sHoUlD bE rUnNiNg.\n\n\n- HoW tO iNsTaLl ThIs DoOr:\n  ~~~~~~~~~~~~~~~~~~~~~~~~~\n\n  1. CrEaTe A dIr CaLlEd: TIME In ThE dOoRs CaTaLoGuE.\n\n  2. CoPy AlL tHe FiLeS iNto ThAt CaTaLoGuE.\n\n  3. CuT tHiS lInE aNd PuT iT iN yA bBs.CmD fIlE.\n\n------------- cut here -------------\n*T        RM001DOORS:TIME/TIME.REXX\n------------- cut here -------------\n\n  4. EdIt ThE TIME.CONFIG fIlE 2 yA nEeDs.\n\n     ThErE mUsT bE 2 lInEs AnD tHeY mUsT cOmE iN tHe FoLlOwInG oRdEr:\n\n     HEADER_ON\n     ONELINER_ON\n\n     ThE mEaNiNg Of ThE lInEs ShOuLd Be ObViOuS.\n\n     If U wAnT 2 tUrN sOmE oF tHe OpTiOnS oFf, ThEn U sHoUlD jUsT cHaNgE tHe\n     WorD "ON" 2 "OFF".\n\n  5. CoPy ThE fIlE "TIME.CONFIG" 2 tHe S: DiR.\n\n  6. U aRe NoW rEaDy 2 Go!\n\n-----------------------------------------------------------------------------\n\n	If U hAvE aNyThInG u WaNt To TeLl Me, ThEn CaLl ThIs NuMbEr:\n\n			ENIGMA   +45 9734 2324\n\n\n		OtHeR pRoDuCtIoNs MaDe By ZaWrAn/InDePeNdEnT\n		~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n				WALL MANIA v1.0\n				PAGE MANIA v1.0\n				TIME MANIA v1.0\n				DOOR MANIA v1.0\n\n-----------------------------------------------------------------------------\n','\n',char(10)),NULL,'auto-added',26356,7,0,NULL,NULL,'t_enigma','scan',1780048813);
INSERT INTO door_catalog VALUES('u4_pent','U4-PENT.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/U4-PENT.LHA','PENTIUM','XIM','...      __ _    /\ __________      ...',NULL,NULL,'U4',':::::    /  l¬\  / //  ___/   ¬\    ::::: :::::   /   |  \/ //__ _¦__  |  \   ::::: ·:::·  /    ¡  / /__||    ¬\ .   \  ·:::·',replace('  ...      __ _    /\ __________      ...  \n :::::    /  l¬\  / //  ___/   ¬\    ::::: \n :::::   /   |  \/ //__ _¦__  |  \   ::::: \n ·:::·  /    ¡  / /__||    ¬\ .   \  ·:::· \n  ·:·   \_______\____ |_____/_|___/   ·:·  \n   ·     ===========|_|===========     ·   \n               [ PRESENTS ]\n   THE PENTIUM JOKING /X COOKIE DOOR\n        BASED ON A TRUE STORY!\n','\n',char(10)),'PENTIUM.DOC',replace('\n                     The pentium BUG\n \nWell dear people WE HAVE FINALY -PROOVEN- that the intel range\nof CISC processors is worth slighly less than a fart!\n\nSince the intel PENTIUM is full of bugs its not strange that\n-WE- the MotorolA LOVING people make jokes about the tiny\nPENTIUM peocessor!!!!\n\n            THIS IS THE DOOR THAT JOKES!!!\n\nInstallation:\n\nCopy all the thingies in the right dirs..\nif you don''t know how to do this ...\nthen go buy that PENTIUM thingie!!\n\nThis door should be used in your bull20 or any MCI script but\nthat is not nescesary.\n\nThis is a XIM door .. it''s a hell of a lot faster than some\nof the COOKIE doors i''v seen around made in arexx!!\n\nIf you have any more jokes about PENTIUMS or you want to\ncontact me .. please do.. i''m on :\n\nSUICIDAL TENDENCY                       +3250427306\n\nYour LOYAL servant 				U4EA\n\nGreeetinks go to:\n\n/Y\ike Tho/Y\pson,Cockroach,Delirium,Kickface,JILL,Nymph,HE-MAN\nand all the others i''v forgotten!\n','\n',char(10)),NULL,NULL,10762,1,0,NULL,NULL,'u4_pent_pentium','scan',1780048813);
INSERT INTO door_catalog VALUES('ucon05','UCON05.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/UCON05.LHA','UConvert','XIM','Relyscully.exe',NULL,'SieGeL',NULL,'\    ____    )  /___/\_| & rED sECTOR ¡NC.| .-\___\ | \___\__   /   |  /F-iNNOVATiON   | `---|___|___|______/____|---[ PRESENTS ]---''',replace(' _____________ ___Mo! __.<---[ tRISTAR ]---.\n \    ____    )  /___/\_| & rED sECTOR ¡NC.|\n.-\___\ | \___\__   /   |  /F-iNNOVATiON   |\n`---|___|___|______/____|---[ PRESENTS ]---''\n\n  USER-CONVERTER Vo.5 bY SieGeL & sTRIDER!\n ------------------------------------------\n  THIS TOOL CONVERTS THE AMIEX USER-DATAS\n TO THE FAME-FORMAT. NOW ALL FAME SPECIFIC\n          FEATURES ARE SUPPORTED !\n ------------------------------------------\n','\n',char(10)),'UConvert.doc',replace('\n         UCONVERT V0.5 by SieGeL aND sTRIDER oF (tRSi/F-iNNOVATiON)\n         ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nIf you are running currently the Amiex System but you want to change to the\nFAME System, one of the main problems are the user.datas, because normally\nyou have to delete them or you must convert every user of your BBS to FAME\nby hand...this could become a hard job when you have about 300 users like I\nhave in my BBS. UConvert is the right solution for this problem, as it is\nable to convert all your Amiex User.datas into the FAME format and also copy\nall neccessary settings, too, so the users won''t notice that their accounts\nhave been moved (except that FAME has a lot more features no other BBS has),\nbecause all Byte- and Filesettings, conference-accesses, level-settings,\ncalls etc. are copied to the FAME-Format. UConvert will set all deleted\nusers from your Amiex user.datas as Inactive, so they won''t be deleted\nwhen a Newuser enters the FAME!\n\nNOTE: Amiex has a hard-core method to save the passwords of the users! The\n      passwords will be crypted with an one-way algorithm, meaning that\n      Amiex itself won''t be able to decrypt the Password after saving it\n      to the user.datas!! Because of this, UConvert will normally write as\n      password for all converted users the name of the user. But we have\n      managed it to solve this problem, too!! Before switching to FAME,\n      built the AutoPW door into your Amiex System as Syscommand ''S'', best\n      way is to install it about one month before switching to FAME. This\n      door is able to collect the Passwords from all users and store them\n      in a seperate file. This file will then be readen and used by UConvert\n      to fill in the passwords!!! See AutoPW.doc for further informations\n      about this door.\n\nNew for V0.5:\n~~~~~~~~~~~~~\nSome people had reported some mistakes during the Usage of UConvert...well\nStrider and I have searched about three hours for any mistakes but found \nNOTHING strange! We have now set up additional features of FAME to Ask\nstate or simply switched them on. If you still have problems with this\nprogram, please contact SieGeL/tRSi under [email removed] or call\nmy BBS and leave me a *FULL DETAILED BUG-REPORT WHAT IS WRONG DURING THE\nCONVERTING OF YOUR USER.DATAS* !!! \nOtherwise I won''t be able to fix anything !\n\n                                  Usage:\n                                  ~~~~~~\n\nFirst make sure that no users are online when converting the user.datas,\nbecause that may cause trouble during the convert process!\n\nStart UConvert with the following arguments:\n\n        UConvert <AMIEX_USER_DATA_PATH> <PATH_TO_CREATE_NEW_DATAS>\n\n                         i.e.: UConvert BBS: RAM:\n\nThis will search for ''BBS:user.data'', ''BBS:user.keys'' and ''BBS:user.misc''\nand convert all three datafiles to the FAME-datafiles ''RAM:user.data'' and\n''RAM:user.keys''. UConvert first checks the amount of users stored in your\nAmiex user.datas and will then convert all users.\nAfter it has been finished with the converting you will be asked if you have\nthe AutoPW door from ByteAndi/tRSi installed (See NOTE above for more\ninformations why this door is required). If you haven''t installed it, enter\n''N'' at the prompt and UConvert will exit silently. You have to check then\nthe password of every user in the converted user.datas, because UConvert is\nonly able to write as Password the User''s name if you don''t have used AutoPW\nbefore convert the user.datas. Don''t blame me for this, Amiex itself won''t\nbe able to decrypt it''s own (!) passwords after crypting/saving them.\n\nBut if you have installed AutoPW and most of your users have entered their\nPassword, answer with ''Y'' at the prompt and UConvert will now check out the\ndatabase AutoPW creates in BBS:user.pw and write all found passwords in the\naccording user.datas. During this procedure, UConvert prints out all users\nincluding their slotnumbers for whom UConvert has found a password.\nUsers which haven''t written their Password included in the AutoPW database\nwill be set to inactive state automatically, but *ONLY* when using AutoPW\nand the AutoPW collector has collected from ALL your users !! If not, the\nusers which aren''t included won''t be touched from UConvert!\n\nAfter finishing, you will now be able to use the converted user.datas\ntogether with FAME ! Simply copy them to the place you''ve defined in the\nSystemEditor of FAME, and everything works fine. You should also mail an\nEALL for your users describing that you''ve changed to FAME and that they\nshould re-configure their settings to use the full power of FAME.\n\nHave fun with your FAME-System,\n\n           Sascha "SieGeL" Pfalz - Leader of (tRSi/F-iNNOVATiON)\n\n               David "Strider" Wettig of (tRSi/F-iNNOVATiON)\n','\n',char(10)),NULL,'auto-added',17760,4,0,NULL,NULL,'ucon05','scan',1780048813);
INSERT INTO door_catalog VALUES('uconv04','UCONV04.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/UCONV04.LHA','UConvert','XIM','LE-win5-96.exe',NULL,'SieGeL',NULL,'\_ __ __ _ ____ \ (__\\ | )\__/,   SUPPORT & DEVELOPMENT --------------------------------------------',replace('___                                 05-05-96\n\_ __ __ _ ____\n\ (__\\ | )\__/,   SUPPORT & DEVELOPMENT\n--------------------------------------------\n    AMIEX TO FAME USER-CONVERTER V0.4!\n--------------------------------------------\n This archive contains the latest UConvert\n  tool for converting /X User.Data to the\n           FAME user.data format.\n--------------------------------------------\n  Written by SieGeL of (tRSi/F-iNNOVATiON)\n--------------------------------------------\n','\n',char(10)),'lOSeNDOS.guide',replace('                   \n                     __  _ __  /\__ _  _ __/\  __ _  __\n                    _\/___   \/              \/   ___\/_\n              ......\/\  /........................\  /\/......\n             :         \/                          \/         :\n             :      .___             .___         .___        :\n             :   _ _|   \      ______|   \  ______|   \       :\n             :   \\\__   7___  \______   /  \__   ____/       :\n             :      /.   |   \__/.  l/   \___/_____   \__ _   :\n             :     /::.  |    _/::.       _/::.  l/    _///   :\n             :     \___________\___________\____________\     :\n             :___        .___        .___        .___         :___\n     _ ______|   \ ______|   \ ______|   \ ______|   \  ______|   \\n     \\\__   ____/ \______   / \______   / \______   /  \__   ____/\n        /.   ___|___/.   |   \__/.  _|   \__/.  l/   \___/_____   \__ _\n       /::.  l/   _/::.  |    _/::. \___  _/::.       _/::.  l/    _///\n       \_ _________\_____|_____\___________\___________\___________ \\n         Y   :                                                :[nM$]Y\n      .------''                                                `------.\n      :eXON/rIOT^jORMAS · gHANDY/gODS · rAHIEM/eSSENCE · cELIC/rEKTUM: \n      `------.                                                .------''\n             `------------------------------------------------''\n','\n',char(10)),NULL,'auto-added',14837,5,0,NULL,NULL,'uconv04','scan',1780048813);
INSERT INTO door_catalog VALUES('uconv05','UCONV05.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/UCONV05.LHA','UConvert','XIM','UConvert',NULL,'SieGeL',NULL,'\    ____    )  /___/\_| & rED sECTOR ¡NC.| .-\___\ | \___\__   /   |  /F-iNNOVATiON   | `---|___|___|______/____|---[ PRESENTS ]---''',replace(' _____________ ___Mo! __.<---[ tRISTAR ]---.\n \    ____    )  /___/\_| & rED sECTOR ¡NC.|\n.-\___\ | \___\__   /   |  /F-iNNOVATiON   |\n`---|___|___|______/____|---[ PRESENTS ]---''\n\n  USER-CONVERTER Vo.5 bY SieGeL & sTRIDER!\n ------------------------------------------\n  THIS TOOL CONVERTS THE AMIEX USER-DATAS\n TO THE FAME-FORMAT. NOW ALL FAME SPECIFIC\n          FEATURES ARE SUPPORTED !\n ------------------------------------------\n','\n',char(10)),'UConvert.doc',replace('\n         UCONVERT V0.5 by SieGeL aND sTRIDER oF (tRSi/F-iNNOVATiON)\n         ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nIf you are running currently the Amiex System but you want to change to the\nFAME System, one of the main problems are the user.datas, because normally\nyou have to delete them or you must convert every user of your BBS to FAME\nby hand...this could become a hard job when you have about 300 users like I\nhave in my BBS. UConvert is the right solution for this problem, as it is\nable to convert all your Amiex User.datas into the FAME format and also copy\nall neccessary settings, too, so the users won''t notice that their accounts\nhave been moved (except that FAME has a lot more features no other BBS has),\nbecause all Byte- and Filesettings, conference-accesses, level-settings,\ncalls etc. are copied to the FAME-Format. UConvert will set all deleted\nusers from your Amiex user.datas as Inactive, so they won''t be deleted\nwhen a Newuser enters the FAME!\n\nNOTE: Amiex has a hard-core method to save the passwords of the users! The\n      passwords will be crypted with an one-way algorithm, meaning that\n      Amiex itself won''t be able to decrypt the Password after saving it\n      to the user.datas!! Because of this, UConvert will normally write as\n      password for all converted users the name of the user. But we have\n      managed it to solve this problem, too!! Before switching to FAME,\n      built the AutoPW door into your Amiex System as Syscommand ''S'', best\n      way is to install it about one month before switching to FAME. This\n      door is able to collect the Passwords from all users and store them\n      in a seperate file. This file will then be readen and used by UConvert\n      to fill in the passwords!!! See AutoPW.doc for further informations\n      about this door.\n\nNew for V0.5:\n~~~~~~~~~~~~~\nSome people had reported some mistakes during the Usage of UConvert...well\nStrider and I have searched about three hours for any mistakes but found \nNOTHING strange! We have now set up additional features of FAME to Ask\nstate or simply switched them on. If you still have problems with this\nprogram, please contact SieGeL/tRSi under [email removed] or call\nmy BBS and leave me a *FULL DETAILED BUG-REPORT WHAT IS WRONG DURING THE\nCONVERTING OF YOUR USER.DATAS* !!! \nOtherwise I won''t be able to fix anything !\n\n                                  Usage:\n                                  ~~~~~~\n\nFirst make sure that no users are online when converting the user.datas,\nbecause that may cause trouble during the convert process!\n\nStart UConvert with the following arguments:\n\n        UConvert <AMIEX_USER_DATA_PATH> <PATH_TO_CREATE_NEW_DATAS>\n\n                         i.e.: UConvert BBS: RAM:\n\nThis will search for ''BBS:user.data'', ''BBS:user.keys'' and ''BBS:user.misc''\nand convert all three datafiles to the FAME-datafiles ''RAM:user.data'' and\n''RAM:user.keys''. UConvert first checks the amount of users stored in your\nAmiex user.datas and will then convert all users.\nAfter it has been finished with the converting you will be asked if you have\nthe AutoPW door from ByteAndi/tRSi installed (See NOTE above for more\ninformations why this door is required). If you haven''t installed it, enter\n''N'' at the prompt and UConvert will exit silently. You have to check then\nthe password of every user in the converted user.datas, because UConvert is\nonly able to write as Password the User''s name if you don''t have used AutoPW\nbefore convert the user.datas. Don''t blame me for this, Amiex itself won''t\nbe able to decrypt it''s own (!) passwords after crypting/saving them.\n\nBut if you have installed AutoPW and most of your users have entered their\nPassword, answer with ''Y'' at the prompt and UConvert will now check out the\ndatabase AutoPW creates in BBS:user.pw and write all found passwords in the\naccording user.datas. During this procedure, UConvert prints out all users\nincluding their slotnumbers for whom UConvert has found a password.\nUsers which haven''t written their Password included in the AutoPW database\nwill be set to inactive state automatically, but *ONLY* when using AutoPW\nand the AutoPW collector has collected from ALL your users !! If not, the\nusers which aren''t included won''t be touched from UConvert!\n\nAfter finishing, you will now be able to use the converted user.datas\ntogether with FAME ! Simply copy them to the place you''ve defined in the\nSystemEditor of FAME, and everything works fine. You should also mail an\nEALL for your users describing that you''ve changed to FAME and that they\nshould re-configure their settings to use the full power of FAME.\n\nHave fun with your FAME-System,\n\n           Sascha "SieGeL" Pfalz - Leader of (tRSi/F-iNNOVATiON)\n\n               David "Strider" Wettig of (tRSi/F-iNNOVATiON)\n','\n',char(10)),NULL,'auto-added',12923,1,0,NULL,NULL,'uconv05','scan',1780048813);
INSERT INTO door_catalog VALUES('uconvert','UCONVERT.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/UCONVERT.LHA','UConvert','XIM','UConvert',NULL,'SieGeL',NULL,'\_ __ __ _ ____ \ (__\\ | )\__/,   SUPPORT & DEVELOPMENT --------------------------------------------',replace('___                                 05-05-96\n\_ __ __ _ ____\n\ (__\\ | )\__/,   SUPPORT & DEVELOPMENT\n--------------------------------------------\n    AMIEX TO FAME USER-CONVERTER V0.4!\n--------------------------------------------\n This archive contains the latest UConvert\n  tool for converting /X User.Data to the\n           FAME user.data format.\n--------------------------------------------\n  Written by SieGeL of (tRSi/F-iNNOVATiON)\n--------------------------------------------\n','\n',char(10)),'UConvert.doc',replace('\n                UCONVERT V0.4 by SieGeL (tRSi/F-iNNOVATiON)\n                ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nIf you are running currently the Amiex System but you want to change to the\nFAME System, one of the main problems are the user.datas, because normally\nyou have to delete them or you must convert every user of your BBS to FAME\nby hand...this could become a hard job when you have about 300 users like I\nhave in my BBS. UConvert is the right solution for this problem, as it is\nable to convert all your Amiex User.datas into the FAME format and also copy\nall neccessary settings, too, so the users won''t notice that their accounts\nhave been moved (except that FAME has a lot more features no other BBS has),\nbecause all Byte- and Filesettings, conference-accesses, level-settings,\ncalls etc. are copied to the FAME-Format. UConvert will set all deleted\nusers from your Amiex user.datas as Inactive, so they won''t be deleted\nwhen a Newuser enters the FAME!\n\nNOTE: Amiex has a hard-core method to save the passwords of the users! The\n      passwords will be crypted with an one-way algorithm, meaning that\n      Amiex itself won''t be able to decrypt the Password after saving it\n      to the user.datas!! Because of this, UConvert will normally write as\n      password for all converted users the name of the user. But we have\n      managed it to solve this problem, too!! Before switching to FAME,\n      built the AutoPW door into your Amiex System as Syscommand ''S'', best\n      way is to install it about one month before switching to FAME. This\n      door is able to collect the Passwords from all users and store them\n      in a seperate file. This file will then be readen and used by UConvert\n      to fill in the passwords!!! See AutoPW.doc for further informations\n      about this door.\n\n                                  Usage:\n                                  ~~~~~~\n\nFirst make sure that no users are online when converting the user.datas,\nbecause that may cause trouble during the convert process!\n\nStart UConvert with the following arguments:\n\n        UConvert <AMIEX_USER_DATA_PATH> <PATH_TO_CREATE_NEW_DATAS>\n\n                         i.e.: UConvert BBS: RAM:\n\nThis will search for ''BBS:user.data'', ''BBS:user.keys'' and ''BBS:user.misc'' \nand convert all three datafiles to the FAME-datafiles ''RAM:user.data'' and\n''RAM:user.keys''. UConvert first checks the amount of users stored in your\nAmiex user.datas and will then convert all users.\nAfter it has been finished with the converting you will be asked if you have\nthe AutoPW door from ByteAndi/tRSi installed (See NOTE above for more\ninformations why this door is required). If you haven''t installed it, enter\n''N'' at the prompt and UConvert will exit silently. You have to check then\nthe password of every user in the converted user.datas, because UConvert is\nonly able to write as Password the User''s name if you don''t have used AutoPW\nbefore convert the user.datas. Don''t blame me for this, Amiex itself won''t\nbe able to decrypt it''s own (!) passwords after crypting/saving them.\n\nBut if you have installed AutoPW and most of your users have entered their\nPassword, answer with ''Y'' at the prompt and UConvert will now check out the\ndatabase AutoPW creates in BBS:user.pw and write all found passwords in the\naccording user.datas. During this procedure, UConvert prints out all users\nincluding their slotnumbers for whom UConvert has found a password.\nUsers which haven''t written their Password included in the AutoPW database\nwill be set to inactive state automatically, but *ONLY* when using AutoPW\nand the AutoPW collector has collected from ALL your users !! If not, the\nusers which aren''t included won''t be touched from UConvert!\n\nAfter finishing, you will now be able to use the converted user.datas\ntogether with FAME ! Simply copy them to the place you''ve defined in the\nSystemEditor of FAME, and everything works fine. You should also mail an\nEALL for your users describing that you''ve changed to FAME and that they\nshould re-configure their settings to use the full power of FAME.\n\nHave fun with your FAME-System,\n\n              Sascha "SieGeL" Pfalz of (tRSi/F-/X-iNNOVATiON)\n\n','\n',char(10)),NULL,'auto-added',10622,1,0,NULL,NULL,'uconvert','scan',1780048813);
INSERT INTO door_catalog VALUES('ula_fgt1','ULA-FGT1.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ULA-FGT1.LHA','fg-internode','XIM','fg-internode',NULL,'Pilot','ULA','|   \  /  |___  / _  \  UNLIMITeD ARTS +:/¯¯|    \/   |   \/  _   \+:+:+:+:+:+:+:+ /   |     \   |    \  |    \ /T\-DIVISIoN',replace('      ___    __       ____\n     |   \  /  |___  / _  \  UNLIMITeD ARTS\n+:/¯¯|    \/   |   \/  _   \+:+:+:+:+:+:+:+\n /   |     \   |    \  |    \ /T\-DIVISIoN\n+\____     /_____   /__|    /+:+:+:+:+:+:+:\n     \____/     \__/   l___/    presents\n[   FG-Tools  -    Written Okt-14-1994    ]\n[  (c)Copyright by Pilot & Orbit of ULA   ] \n[ Cool pack of many tools with new Dizign ]\n[ WHo,Internode,Nodestat,TopWeekUploader, ]\n[ and many more... Leech and have fun !   ]\n[      68000 & 68030 Codes included!      ]','\n',char(10)),'File.guide',replace('[0m[0 pINSERT INTO door_catalog VALUES('ula_fs10','ULA-FS10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ULA-FS10.LHA','AmigaGuide','XIM','AmigaGuide',NULL,'VICaR/ULA]','ULA','|   \  /  |___  / _  \  UNLIMITeD ARTS +:/¯¯|    \/   |   \/  _   \+:+:+:+:+:+:+:+ /   |     \   |    \  |    \ /T\-DIVISIoN',replace('      ___    __       ____\n     |   \  /  |___  / _  \  UNLIMITeD ARTS\n+:/¯¯|    \/   |   \/  _   \+:+:+:+:+:+:+:+\n /   |     \   |    \  |    \ /T\-DIVISIoN\n+\____     /_____   /__|    /+:+:+:+:+:+:+:\n     \____/     \__/   l___/    presents\n           [FRONT STATUS V1.0 ] \n    [Written Okt-07-1994 by VICaR/ULA] \n','\n',char(10)),'uLa-FrontStat10Eng.guide',replace('@database FrontStat.doc\nCopyright (c) 1994 by VICaR/ULA\n@Remark $VER: (oKToBeR-07-1994)\n@Remark AmigaGuide DataBase "FrontStat" DoCuMeNTaTioN\n@node MAIN "uLa-Front_Status V1.0 (c) Copyright 1994 by VICaR/ULA"\n      ___   ____ __   ___      ____  __ ___   ____ ________/\_______  ______\n  ___|   \ /    |  \ /   |___ / ___|/  Y   \ / ___| __  __   \  ____)/  _   \\n /   |    \   _ |   \    |   \¯¯   |        \¯¯   |__/   |___/  __)_/   |    \\n/    |     \  |      \   |    \    |   _     \    | /    | /    |    \_ |     \\n\_____     /__|      /_____   /____|___|     /____| \____| \_____     /____   /\n-*-*-\____/*-*l_____/-*-*\___/*-*-*-*-*l____/-*-*-*-*-*-*-*-*-*-\____/-*-\___/-\n                      ______   ______  ________/\______                \n                     /  _   \ /  _   \/ __  __   \  ___)_          \n                    /   _    \   |   /\__/   |___/__     \ \n                   /    |     \ __   ¯\_/    |/   |       \ \n                   \____|     /__|     /\____|\_______    /\n                   -*-*-l____/-*-l____/-*-*-*-*-*-*-*\___/-\n \n                             aRe PRouD To PReSeNT: \n\n            Front Status Version 1.0 (c)Copyright 1994 BY VICaR/uLA\n \n                       CONTENS OF THIS DOCUMENTATION\n                   -*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-                 \n\n     @{" INTORDUCTION " LINK N1}   @{" INSTALLATION " LINK N2}   @{" CONFIG FILE! " LINK N3}   @{"  GREETINGS!  " LINK N4}\n@endnode\n\n@node N1 "FRONTSTATUS INTRODUCTION"\n\n                                INTRODUCTION \n                               -*-*-*-*-*-*-\n\nWhat i need to use the Front Status?\n\n1. An Amiga (500/1200/2000/3000/4000) of course ! ;)\n2. Kickstart 2.xx or higher. (Testet on: A2000 and A1200)\n3. Tempest Version 3.xx. (Testet on: V3.24 Beta from the Oktober-03-1994)   \n\nWhat is the FrontStatus?\n \nThe Front Status is like a Who-Util. But he shows the status of all Nodes \nright after the Connect. So the FrontStatus shows wich Nodes are busy or\nfree and the Phonenumbers of all Nodes.\n\nHave fun with this Util......\n\n                                            VICaR of @{"UNLiMiTeD ARTS" LINK ULA}\n@endnode\n\n@node N2 "INSTALLATION"\n\n                                INSTALLATION! \n                               -*-*-*-*-*-*-*-\n\nTo install the FrontStatus you must copy the Files uLa-FrontStatus10\nand uLa-FrontStatus10.cfg in your Tempest MODULES Dir.\n\n!! ATTENTION !!\n\nThe Files uLa-FrontStatus10 and uLa-FrontStatus10.cfg must be located \nin your MODULES Dir !!!\n\nNow there are several possibilities to call the FrontStatus. I think \nto start it directly after the ConnectMessage is the best way.\nTo do that you must copy the both Text-PostConnect Files in your\nTempest TEXT Dir. Inside this the FrontStatus will be call with  \nthe command:  ~TD(bbs:modules/ula-FrontStatus10)\nIf you want a screenclear above the FrontStatus you must write a ~CLS \nabove the last command.\nSo you can write to the Text-PostConnect File following:\n\n~CLS\n~TD(bbs:Modules/uLa-FrontStat10)\n\nOf course you can call the FrontStatus with an optional command,\nbut i think this way is not the best.\n\n@endnode\n\n@node N3 "THE CONFIG FILE"\n\n                                CONFIG DATEI! \n                               -*-*-*-*-*-*-*-\n\n\nIn the uLa-FrontStat10.cfg File you can write your Phone Numbers\nof the several Nodes. The Number-Stirng can max. be 17 chars long.\nThe Cfg-File can look like this:\n\n01: +xx (x)xx xxxxxxx\n02: +xx (x)xx xxxxxxx\n03: +xx (x)xx xxxxxxx\n04: -+:LoCaL NoDe!:+-\n\n\n---------------------------------------- \n^^^ ^^^^^^^^^^^^^^^^^\n\ /       \ / \n |         |\n |         |____ Phone Nummer of the Node\n |\n |\n |______Node Nr.  \n\nI think the rest is clear.....\n\n@endnode\n\n@node N4 "GREETINGS !"\n\n                              GREETINGS!! \n                             -*-*-*-*-*-*-\n\nMany Greetings to all ULA-Members an FaTE GaTE-Sysops !!!\n\nAlso big greetings to:\n\nM.Bockert             Thanx for the best BBS Programm of the World !!\n\nPilot & Orbit         Very cool Tempest Utils !!!!!\n\nCasa Nova             Cool BBS and Arexx Utils !!!\n\nSPy/tRSi              Very cool /X-Tools and the Best Public Domain\n                      Board i know (with 97 Calls a day) !!! \n\n\n             //\n  Thanx to \X/ Amiga For Being The Best Computer Ever made ...\n\n@endnode\n\n@node ULA "UNLiMiTeD ARTS INFORMATION"\n\n\n            +-----------------------------------------------+\n            :        ___    __       ____                   :\n            :       |   \  /  |___  / _  \  UNLIMITeD ARTS  :\n            : :+:/¯¯|    \/   |   \/  _   \+:+:+:+:+:+:+:+: :\n            :   /   |     \   |    \  |    \ /T\-DIVISIoN   :\n            : :+\____     /_____   /__|    /+:+:+:+:+:+:+:+ :\n            :       \____/     \__/   l___/                 :\n            :                                               :\n            : UNLiMiTeD ARTS MEMBERS ARE:                   :\n            :                                               :\n            :        VICaR - PILoT - RaTMaN - TiFFy         :\n            :                                               :\n            :  WE ARE EVER SEARCHING FOR COOL PROGRAMMERS   :\n            :                TO JOIN US!!!                  :\n            :                                               :\n            : FOR JOINING:                                  :\n            : CONTACT -VICaR/ULA- oN THe @{"-FaTE GaTE BBS-" LINK FG}    :\n            :                     Or THe @{"-PaRaLYSiS BBS-" LINK Para}    :\n            +-----------------------------------------------+\n\n@endnode\n\n@node Para "CALL THE PARALYSIS FOR CONTACT VICaR/ULA"\n -*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-\n              ..:THe RuLING PuBLIC DoMAIN BoaRD IN BeRLIN:..\n\n                     -- -[ SYNDIC/\TE WHQ ]- --\n    _____  _____    _____   _____  __      ___ __  _____   ___ _____\n   /  _  \/  _  \  /  _  \ /  _  \/  |___ /   |  \/   __)_/ __|   __)_\n  /   |   \  _   \/   |  //   _   \  |   \\_____  \___    \¯  |___    \\n /   _____/  |    \_ __   \_  |    \ |    \   |    \|      \  | |      \\n \____| \____|    /___|    /__|    /___   / _______/___    /__|____    /\n             l___/    l___/   l___/  \___/___/  [ViC!]\___/       \___/\n\n             SYSTeM CHieFS: SPY/TRSi & ARTHuR DeNT & PHaNToM\n\n          D  NoDE 1: +49(0)30 721 6071 USR 28.8 V.FaST CLaSS  D\n          I  NoDE 2: +49(0)30 721 6072 USR 28.8 V.FaST CLaSS  I\n          A  NoDE 3: +49(0)30 721 6073 USR 28.8 V.FaST CLaSS  A\n          L  NoDE 4: +49(0)30 722 6065 USR 28.8 V.FaST CLaSS  L\n\n        --[oNLY PuBLIC DoMAIN SoFTWaRE FoR aMIGa,iBM,MaC & C64]--\n\n -*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-\n\n@endnode\n\n@node FG "CALL FATE FATE NOW"\n\n\n            ______ ______  ________/\  ______\n     ______/ _____)  _   \/  __  __  \/  ____)________________________\n          /  ___)/   _    \___/   |__/   __)__\n   ______/    | /    |     \ /    | /    |    \_________________________\n         \____| \____|     / \____| \______   /\n                     l____/             \____/\n\n                        ______     ______  ________/\  ______\n   ____________________/  ____)_  /  _   \/  __  __  \/  ____)__________\n                      /  (___   \/   _    \___/   |__/   __)__\n     ________________/     |     \   |     \ /    | /    |    \_______\n                     \_______    /___|     / \____| \______   /\n                           \____/    l____/             \____/\n\n\n    RuNNING oN TeMPEST V 3.24 - aMIGa 2000/030 - MoRE THaN 1 GiG oNLiNE\n     6 NoDES - ISDN RuLEZ ! - aMIGa, CoNSoLE & PC SoFT - BuT PRIVaTE !\n\n@endnode\n','\n',char(10)),NULL,'auto-added',55583,1,0,NULL,NULL,'ula_fs10','scan',1780048813);
INSERT INTO door_catalog VALUES('ula_us10','ULA-US10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/ULA-US10.LHA','AmigaGuide','XIM','AmigaGuide',NULL,'VICaR','ULA','|   \  /  |___  / _  \  UNLIMITeD ARTS +:/¯¯|    \/   |   \/  _   \+:+:+:+:+:+:+:+ /   |     \   |    \  |    \ /T\-DIVISIoN',replace('      ___    __       ____\n     |   \  /  |___  / _  \  UNLIMITeD ARTS\n+:/¯¯|    \/   |   \/  _   \+:+:+:+:+:+:+:+\n /   |     \   |    \  |    \ /T\-DIVISIoN\n+\____     /_____   /__|    /+:+:+:+:+:+:+:\n     \____/     \__/   l___/    presents\n[ USER STATUS V1.0 -  Written Okt-09-1994 ]\n[ (c)Copyright by VICaR of UNLiMiTED ARTS ] \n[ Cool UserStatus Module for Tempest 3.xx ]','\n',char(10)),'uLa-UserStat10Eng.guide',replace('@database UserStat.doc\nCopyright (c) 1994 by VICaR/ULA\n@Remark $VER: (oKToBeR-07-1994)\n@Remark AmigaGuide DataBase "UserStat" DoCuMeNTaTioN\n@node MAIN "uLa-User_Status V1.0 (c) Copyright 1994 by VICaR/ULA"\n      ___   ____ __   ___      ____  __ ___   ____ ________/\_______  ______\n  ___|   \ /    |  \ /   |___ / ___|/  Y   \ / ___| __  __   \  ____)/  _   \\n /   |    \   _ |   \    |   \¯¯   |        \¯¯   |__/   |___/  __)_/   |    \\n/    |     \  |      \   |    \    |   _     \    | /    | /    |    \_ |     \\n\_____     /__|      /_____   /____|___|     /____| \____| \_____     /____   /\n-*-*-\____/*-*l_____/-*-*\___/*-*-*-*-*l____/-*-*-*-*-*-*-*-*-*-\____/-*-\___/-\n                      ______   ______  ________/\______                \n                     /  _   \ /  _   \/ __  __   \  ___)_          \n                    /   _    \   |   /\__/   |___/__     \ \n                   /    |     \ __   ¯\_/    |/   |       \ \n                   \____|     /__|     /\____|\_______    /\n                   -*-*-l____/-*-l____/-*-*-*-*-*-*-*\___/-\n \n                             aRe PRouD To PReSeNT: \n\n            User Status Version 1.0 (c)Copyright 1994 BY VICaR/uLA\n \n                       CONTENS OF THIS DOCUMENTATION\n                   -*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-                 \n\n            @{" INTORDUCTION " LINK N1}   @{" INSTALLATION " LINK N2}   @{"  GREETINGS!  " LINK N3}\n@endnode\n\n@node N1 "USERSTATUS INTRODUCTION"\n\n                                INTRODUCTION \n                               -*-*-*-*-*-*-\n\nWhat i need to use the User Status?\n\n1. An Amiga (500/1200/2000/3000/4000) of course ! ;)\n2. Kickstart 2.xx or higher. (Testet on: A2000 and A1200)\n3. Tempest Version 3.xx. (Testet on: V3.24 Beta from the Oktober-05-1994)   \n\nWhat is the UserStatus?\n \nThe UserStatus is a Tool, witch gives the User detailed informations\nlike his uploaded and downloaded Files & Bytes or his total Calls or\nSecurity level.\n\nHave fun with this Util......\n\n                                            VICaR of @{"UNLiMiTeD ARTS" LINK ULA}\n@endnode\n\n@node N2 "INSTALLATION"\n\n                                INSTALLATION! \n                               -*-*-*-*-*-*-*-\nTo install the UserStatus you must copy the File uLA-UserStat10.mod \nin your Tempest MODULES Dir.\n\nNow you must enter this in your Optinals i.e. in the Files MsgMenu.opt\nor FileMenu.opt:\n\n[*,*,*,*,*]  = s|MODULE|ula-Userstat10.mod\n\nIf you want more informations about this Entry look in your Tempest\nDocumentation !!\n\nIf now the User press "s" his User Status will be displayed..Have fun..\n\n@endnode\n\n@node N3 "GREETINGS !"\n\n                              GREETINGS!! \n                             -*-*-*-*-*-*-\n\nMany Greetings to all ULA-Members an FaTE GaTE-Sysops !!!\n\nAlso big greetings to:\n\nM.Bockert             Thanx for the best BBS Programm of the World !!\n\nOrbit                 Very cool Tempest Utils !!!!!\n\nPilot                 Thanx for helping me an the cool ideas !\n\nTronics               Cool Ansi Painting !!!\n\nCasa Nova             Cool BBS and Arexx Utils !!!\n\nSPy/tRSi              Very cool /X-Tools and one of the Best Public \n                      Domain Board i know (with 97 Calls a day) !!! \n\nGurumaker             For Beta-Testing my Tools !!!\n\n             //\n  Thanx to \X/ Amiga For Being The Best Computer Ever made ...\n\n@endnode\n\n@node ULA "UNLiMiTeD ARTS INFORMATION"\n\n\n            +-----------------------------------------------+\n            :        ___    __       ____                   :\n            :       |   \  /  |___  / _  \  UNLIMITeD ARTS  :\n            : :+:/¯¯|    \/   |   \/  _   \+:+:+:+:+:+:+:+: :\n            :   /   |     \   |    \  |    \ /T\-DIVISIoN   :\n            : :+\____     /_____   /__|    /+:+:+:+:+:+:+:+ :\n            :       \____/     \__/   l___/                 :\n            :                                               :\n            : UNLiMiTeD ARTS MEMBERS ARE:                   :\n            :                                               :\n            :        VICaR - PILoT - RaTMaN - TiFFy         :\n            :                                               :\n            :  WE ARE EVER SEARCHING FOR COOL PROGRAMMERS   :\n            :                TO JOIN US!!!                  :\n            :                                               :\n            : FOR JOINING:                                  :\n            : CONTACT -VICaR/ULA- oN THe @{"-FaTE GaTE BBS-" LINK FG}    :\n            :                     Or THe @{"-PaRaLYSiS BBS-" LINK Para}    :\n            +-----------------------------------------------+\n\n@endnode\n\n@node Para "CALL THE PARALYSIS FOR CONTACT VICaR/ULA"\n -*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-\n              ..:THe RuLING PuBLIC DoMAIN BoaRD IN BeRLIN:..\n\n                     -- -[ SYNDIC/\TE WHQ ]- --\n    _____  _____    _____   _____  __      ___ __  _____   ___ _____\n   /  _  \/  _  \  /  _  \ /  _  \/  |___ /   |  \/   __)_/ __|   __)_\n  /   |   \  _   \/   |  //   _   \  |   \\_____  \___    \¯  |___    \\n /   _____/  |    \_ __   \_  |    \ |    \   |    \|      \  | |      \\n \____| \____|    /___|    /__|    /___   / _______/___    /__|____    /\n             l___/    l___/   l___/  \___/___/  [ViC!]\___/       \___/\n\n             SYSTeM CHieFS: SPY/TRSi & ARTHuR DeNT & PHaNToM\n\n          D  NoDE 1: +49(0)30 721 6071 USR 28.8 V.FaST CLaSS  D\n          I  NoDE 2: +49(0)30 721 6072 USR 28.8 V.FaST CLaSS  I\n          A  NoDE 3: +49(0)30 721 6073 USR 28.8 V.FaST CLaSS  A\n          L  NoDE 4: +49(0)30 722 6065 USR 28.8 V.FaST CLaSS  L\n\n        --[oNLY PuBLIC DoMAIN SoFTWaRE FoR aMIGa,iBM,MaC & C64]--\n\n -*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-*-\n\n@endnode\n\n@node FG "CALL FATE FATE NOW"\n\n\n            ______ ______  ________/\  ______\n     ______/ _____)  _   \/  __  __  \/  ____)________________________\n          /  ___)/   _    \___/   |__/   __)__\n   ______/    | /    |     \ /    | /    |    \_________________________\n         \____| \____|     / \____| \______   /\n                     l____/             \____/\n\n                        ______     ______  ________/\  ______\n   ____________________/  ____)_  /  _   \/  __  __  \/  ____)__________\n                      /  (___   \/   _    \___/   |__/   __)__\n     ________________/     |     \   |     \ /    | /    |    \_______\n                     \_______    /___|     / \____| \______   /\n                           \____/    l____/             \____/\n\n\n    RuNNING oN TeMPEST V 3.24 - aMIGa 2000/030 - MoRE THaN 1 GiG oNLiNE\n     6 NoDES - ISDN RuLEZ ! - aMIGa, CoNSoLE & PC SoFT - BuT PRIVaTE !\n\n@endnode\n','\n',char(10)),NULL,'auto-added',77660,8,0,NULL,NULL,'ula_us10','scan',1780048813);
