INSERT INTO door_catalog VALUES('vsn_mc10','VSN-MC10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/VSN-MC10.LHA',NULL,'XIM','________  ___       __    ______',NULL,'linus/vsn![-]','VSN','___\      /./ __).__. /. \ ._\     \. \   \    / |____ |  |/ |_ \|  \     | .\  /   /  |     |  |  |/  \_  \    |.',replace('      ________  ___       __    ______\n   ___\      /./ __).__. /. \ ._\     \.\n   \   \    / |____ |  |/ |_ \|  \     | \n   .\  /   /  |     |  |  |/  \_  \    |.\n   ::\____/|__|_____|__|_______/___\   |:\n   |·::::::::·--> PreSenTs <--·::Li!\__|:\n   `-> music-chatter for /T\ <--·:::::::·\n  [-]a new chatdoor coded by linus/vsn![-]\n     [-] Pages sysop with a module! [-] \n     [-] V1.0 coded by Linus/vsn''95 [-] \n','\n',char(10)),'MuCha.Guide',replace('@database 0009cf60-0\n@master HeddleyCreation\n@$VER: 1.0\n@remark Created with Heddley v1.1 (c) Edd Dumbill 1994\n\n@node "Main" "No title"\n                      \n              .·· ·   °   ·  · · .        .             ________________ _ _\n    _________·__________._________·.____.:::____  ._____\:·     _______// / \\n  \\\:·      T      \   | ________)|:·  |::/:·  \ |:·    \        |\n    \\__     |      /  .|_________ |    |:/   _  \|    \  \      .| .\n       \          //   :|         .|   .|/   |/   \     \  \     :| .\n        \        //|____|         ||____|    |     \_    \  \    :| :\n         \_______/ (____)__________|____)___________/_____\_______| :\n               .    .  . .::..:::::.... . . .· Li! ·.  . . .  .. ...:.. .  .\n                         ·::::::::::::.. .  .                       ·\n                           ·:··:::::·   ·                           ·\n                            ·   ·::·\n            pReSentS aNotHer /T\emPesT-DooR coDed bY lInus/vsn\n\n                                  cAlleD\n                                   _\n                          /X\uSiC (_HattEr v1.o!\n\n \n                           Click @{"hEre" link "Main2" 0} fOr dOcs!\n@endnode\n\n@node "Main2" "hEre"\n                     tHe Doc! ;) i Hate wRiTinG dOcS! \n\n\n\n\n\n                               @{"(X)" link "Intro" 0}  IntroDucIng\n                               @{"(X)" link "Rrequier" 0}  reQuiermEnts\n                               @{"(X)" link "Install" 0}  InStall\n                               @{"(X)" link "cFG!" 0}  tHe CFG fIle!\n                               @{"(X)" link "bugs" 0}  knOwn BuGS\n                               @{"(X)" link "History" 0}  hIstoRy\n                               @{"(X)" link "greet" 0}  GrEEtIngS\n\n\n\n\n          ...doch das chaos ist der koenig der das land regiert!\n                                                      \n                                      (die fantastischen vier/4. Dimension!)\n@endnode\n\n@node "Intro" "(X)"\n\n\n                 what tHe fuCk dOes Music-Chatter DO?!?!?\n\n\n Easy to Explain.. ;)) it PageS thE sYsop wIth onE of his FavOrit Modules\n                          SelEcted By tHe UsER!!\n\nMuCha Uses a ExTernal pLayer Which muSt Have a Option fOr plAying a moD iN\n      A tAsk and One To Stop PLayIng! mOre aBouT thIs cLick @{"Here" link "Install" 0}! ;)\n\n\n\n\n\n\n...denn nur ich weiss was ich bin was ich bin und nicht schizophren!\n\n                                        (die fantastischen vier/4. Dimension)\n@endnode\n\n@node "Rrequier" "(X)"\n\n                               rEquiErmenTS:\n\n\n\n                   yOu need AREXX (a running RexxMast!)\n\n                 a PlaYer Like APLAYER V1.30+ (not loWer!)\n\n                            sum COOOL moDS! ;))\n\n                          RunnNig Tempest! V3.29+\n\n                  RexxSupport.Library is Requiered, too!\n\n\n\n\n...die musik ist aus, und ist immernoch da\n\n                                 (die fantastischen vier/4. Dimension)\n@endnode\n\n@node "Install" "(X)"\n                               inStall!! ;)\n\n\n           Copy thE MuCha10.rexx file into a Drawer you Like! ;)\n\n             Create at your Doors-Path a drawer called LI-CFGS\n  I Put all CFG-Files of the Following tools in This Drawer! So there is \n             NO stupid CFG-File Searching for My Tool anyMore!\n\nBE sure that this Drawer Exists!! Otherwise MuCha gives you a Errormessi ;)\n\n\n\n       NOW edit your Optional/GLOBALMENU.OPT File and Add this Line:\n\n         [*,*,*,*,*]   = O      |REXX  |{yOur Path!!}/MuCha10.rexx\n\n\n                  SO, now you have to EDIT your @{"CFG" link "cFG!" 0} file!\n@endnode\n\n@node "cFG!" "(X)"\n                            now thE "mainpart"\n\n\nThe ConfigFile looks so:\n\nC:Aplayer CX_POPUP=NO QUIT St-00:Modules/mod.test   Test!\nSt-00:modules/mod.ubbaubaa  Ubba!\n\n1st Line: C:Aplayer 	  The Name of The Player you USE! WITH ALL PATHS!!\n\n2nd Line: CX_POPUP=NO\n          The Startoption for the Player! BE sure the Player HAS one! DON`T\n          Use A player WHich reTurns Messages to The WB or somewhere else!\n          IT WILL CRASH YOUR TEMPEST!! (YOu have to reboot! ;()\n          (CX_POPUP=NO is Used by APLAYER this is an EXAMPLE!!)\n\n3rd Line: QUIT\n          The Stopflag For the PLAYER!! Same as StartFlag! No Messages and \n          so on!\n          (QUIT is Used By APLAYER!! this is an EXAMPLE!!)  \n\n4th Line: St-00:Modules/mod.test   Test\n          The First Module! First ''WORD'': the Compleste Path and modname!\n          Second ''WORD'' The ModName for the User!! (ONLY ONE WORD NO SPACES!)\n\n5th Line....Nth Line \n          Mods mods Mods mods! ;)) But remember: Mor than 10 crashes the Out-\n          put of the program! But 5 is enough! ;)\n\n\nSOME HINTS:\n\nUse the Aplayer V1.30+ for best compatibility! I hasn`t Add this player to\nthis archieve! But it is REALLY the best! ;) And be sure, that you have enough\nChipMem to play a mod! Best is, you TEST the MuCha at your local node! ;) I\nhope you enjoy this tool!! ;)\n@endnode\n\n@node "bugs" "(X)"\n\n                                known bugs!\n\n\n- If the computer runs out of memory, the Programs hangup the system!!\n  I don`t know how to fix it!\n  - If the Player returns Messages to the system, IT Hangsup TOOO!! ;(\n@endnode\n\n@node "History" "(X)"\nno history yet! First release!\n@endnode\n\n@node "greet" "(X)"\n\n\n                          Greeeeeetinnnnxxx!! ;)\n\n\n\n                                    TO:\n\n   GENERATOR/VSN/PGS/TCE, MAD/TAI, SUGGS, TROUBLE, SHODAN/IA, STEVE/SHT\n                         AND ALL VISON MEMBERS!!!\n@endnode\n\n','\n',char(10)),NULL,NULL,20336,12,0,NULL,NULL,NULL,'scan',1780048821);
INSERT INTO door_catalog VALUES('vsn_mdz','VSN-MDZ.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/VSN-MDZ.LHA','MagicDiz','XIM','MagicDiz',NULL,'icarus/vsn','VSN','|    /________________________________\   g| |  __.     __.   .___   __.  ____   ____. ®| | _\ |___ _\_|_  | _/_ _\_|_ \  /_ _\__ |_m|',replace(' _____          -[ vISiOn ]-          _____.\n|    /________________________________\   g|\n|  __.     __.   .___   __.  ____   ____. ®|\n| _\ |___ _\_|_  | _/_ _\_|_ \  /_ _\__ |_m|\n|_\  |  /_    /__l__ /_    /_ || /_   /  /_|\n|\_______/_____/______/_____/_____/__/____/|\n|                                          |\n|             MagicDiz v2.05               |\n| Dizzer that handles IFF,GIF,JPG,TXT,NFO  |\n| files... coded by icarus/vsn             |\n| Use it in you Boards, Filelist-makers !! |\n`------------------------------------------''\n','\n',char(10)),'MagicDiz.doc',replace(' \n \n                              /\\n                              /\\n                              /\\n                       /\    //\\\n                ____  /  \  /   \\  ________________ ________\n               |¯  ¬\/    \/      \/¯   _____/¯    ¬|_      ¬\_\n  .---------   |    \/     \       \    \__ ¬\       /   |____/\n  |.-- -       |    ||      \       \         \     /    |¯  ¬\\. ------.\n  ||          ||____||_______\_______\________/____/__________//     --.|\n  |:          `--- - - -ic!                                            ||\n  |                         .-_____                                    :|\n  |                          \\   ¬|                                    |\n  |                       _____\   |_____ ________                      |\n  |                      /¯        |    ¬|_____  ¬\_       -------------''\n  `------ - - --      .//   |      |      /¯    ___/___-.\n                       \\__________|_____/\___________//\n \n                             >>> VERSION 2.05 <<<\n \n \n                            1. What is MagicDiz ?\n                            2. Who to use.\n                            3. Freeware! README !!!\n                            4. Author+Greets.\n\n1. What is MagicDiz ?\n---------------------\n\nMagicDiz is a FILE_ID.DIZ dizzer for TXT, NFO, IFF/ILBM, GIF, JPG\nfiles... You can use it to Add File_ids, View File_ids, Extract File_ids,\nDelete File_ids.\n\nIt`s the first correctly running dizzer for Amiga which can handle this\nfile-types !!!\n\n\n2. Who to Use.\n--------------\n\nIt`s very simple.\n\n   Extract File_ids:\n   -----------------\n   To extract file_ids you must enter the following commandline:\n\n   MagicDiz e dh0:bin/VSN-YEP!.JPG dh0:VSN-File_id.diz\n            ^ ^                    ^\n            | |                    `--(Name+Path of the extracted Id!)\n            | `--(File to extract from, IFF,GIF,TXT,NFO,JPG!)\n            `--(Option, NOT case sensitive!)\n\n   Add File_ids:\n   -------------\n   To add file_ids you must enter the following commandline:\n\n   MagicDiz a dh0:bin/VSN-YEP!.TXT dh0:New_file_id.diz\n            ^ ^                    ^\n            | |                    `--(Name of the Id to be added!)\n            | `--(File to add the File_id!)\n            `--(Option, NOT case sensitive!)\n\n   View File_ids:\n   --------------\n   To view file_ids you must enter the following commandline:\n\n   MagicDiz v dh0:bin/VSN-YEP!.GIF\n            ^ ^\n            | |\n            | `--(File from which you want to see the File_id!)\n            `--(Option, NOT case sensitive!)\n\n   Delete File_ids:\n   ----------------\n   To delete file_ids you must enter the following commandline:\n\n   MagicDiz d dh0:bin/VSN-YEP!.IFF\n            ^ ^\n            | |\n            | `--(File from which you want to delete the File_id!)\n            `--(Option, NOT case sensitive!)\n\n\n3. Freeware! README !!!\n-----------------------\n\nMagicDiz is freeware, that means that you can use it in you own\nproductions ( you should do it 8-) ) and to spread it everywhere!!!\n\nUse it in your Boards, File_id-listmakers ... and so on !!!\n\nBut please let this file in its original state!\n\n\n4. Author+Greetz:\n-----------------\n\nMagicDiz was coded by iCARUS of viSiOn 1995!\nSorry, but cos of my many cracks you won`t get my address hehe... ohhno!\n\nLook out for more versions of MagicDiz!!!\n\n \n                               iCARUS GREETS:\n \n                Evil Chuck ........................ [iNDEP.]\n                Tiger 1 ........................... [iNDEP.]\n                NRG ............................... [iNDEP.]\n                Wrathchild ........................ [viSiON]\n                Wendigo ........................... [mOTiON]\n                BBC ............................... [mOTiON]\n                Cat ........................... [tAN^viSiON]\n                Arrogance ......................... [iNDEP.]\n                Jash .............................. [iNDEP.]\n                Blacky ............................ [iNDEP.]\n                Thorax ............................ [iNDEP.]\n                Zombie ................[pOWER cRACKiNG bOYS]\n                Garbor ................[pOWER cRACKiNG bOYS]\n                Garfield ..............[pOWER cRACKiNG bOYS]\n                Creep ............................. [iNDEP.]\n                FireFox ........................... [iNDEP.]\n                Grizzly ........................... [iNDEP.]\n                Ringo Starr ................... [ex-Classic]\n                Tanith ............................ [hECTiC]\n                Slac ............................ [dECiSiON]\n                Flake ............................... [TRSi]\n                PBA ....................... [ex-Spreadpoint]\n                Mozart ......................... [Guardians]\n                MetalWarrior ................... [Guardians]\n                Max ............................ [StarLight]\n                Death ........................ [Human^Waste]\n                Morgoth ........................ [StarLight]\n                Skillion ............... [ex-Endless Piracy]\n                Cathrin ........................ [StarLight]\n\n\n                            ALL VISION MEMBERS !!\n','\n',char(10)),NULL,'auto-added',12809,3,0,NULL,NULL,'vsn_mdz','scan',1780048821);
INSERT INTO door_catalog VALUES('vtl_acc2','VTL-ACC2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/VTL-ACC2.LHA','SysCm','XIM','SysCm',NULL,NULL,'VTL','::                                        :: ::      Delusion of Virtual Presents      :: ::                                        ::',replace('[35mQUALITY[34m::::::::::::::::::::::::::::::::::::.\n::                                        ::\n::      [35mDelusion of Virtual Presents      [34m::\n::                                        ::\n::     [32moO+  ACCOUNT EDITOR V2.00  +Oo     [34m::\n::                                        :''\n::    [0mWorks on /X2.37 /X3.10 /X3.37!      [34m:.\n::                                        ::\n:: [36mCredit Ed, Pw Fail, UserList, Warnings [34m::\n:: [36m Questionary, Quest View, MessageBase  [34m::\n.: [36mSecurityChecker, Calculator, AccountED [34m::\n::                                        ::\n`::::::::::::::::::::::::::::::::::::[35mQUALITY[0m\nNo1 >-<->-<   di\/inE uKhQ   >-<->-< No1\n/-/ horizontially disproportionate.../-/\n','\n',char(10)),'AccED.Guide',replace('@database AccountED.Guide\n@font "topaz.font" 8\n\n@node Main "Main Menu, Account ED AmigaGuide Doc V1.01"\n\n                 »» From The Worlds No.1 /X Door Makers ««\n@{b}\n\n             :::      :::          ::.                    :::\n             :::  ::: ... :.::::. .:::: :::  ::. .:::.::: :::\n             :::  ::: ::: :::  ::  :::  :::  ::: ::''  ::: :::\n             :::.:::'' ::: :::      :::  :::  ::: ::.  ::: :::\n             `::::''   `:: :::      `::: `::::`:'' `:::''::: `::::\n@{ub}\n\n  Account ED V2.00 AmigaGuide Documentation By Delusion And Jens Eriksson!\n                 Spelling And Error Correction By Ace Caze.\n\n\n   @{" 1. Disclaimer, Copyrights      " LINK "Disclaimer, Copyrights"}    @{" 6. Hints To Gain High Security " LINK "Hints To Gain Higher Security"}\n   @{" 2. Introduction, Preface       " LINK "Introduction, Preface"}    @{" 7. Other Delusion Productions  " LINK "Other Delusion Productions"}\n   @{" 3. Features                    " LINK "Features"}    @{" 8. Greetings                   " LINK "Greetings"}\n   @{" 4. Installation on /X 2.10+    " LINK "Installation 2.10+ .."}    @{" 9. Final Words ..              " LINK "Final words .."}\n   @{" 5. Installation on /X 3.00+    " LINK "Installation 3.00+ .."}    @{"10. History                     " LINK "Account ED Package Histories"}\n\n\n@{b}   © Copyright Delusion of Virtual 1992, 1993, 1994. All rights reserved.@{ub}\n@endnode\n\n@node "Disclaimer, Copyrights"\n\n	@{b}Disclaimer, Copyrights@{ub}\n\n	The author, Delusion takes no responsibilities what so ever for\n	the functionality of this program and the purpose for which\n	it should be used. Delusion takes no responsibilities for damage\n	that this program may cause and it''s your responsibility to make\n	a backup of your critical files before testing that this program\n	fully works in your environment.\n\n	This program and it''s accompanying files may only be spread in\n	it''s original form. It may not be spread without all files\n	included because it could then do damage to your system. You may\n	not sell this program or take a fee to copy it. It may not be\n	included in any PD Package without written permission from the\n	author. It may however be included in Joseph Hodge''s @{"AmiExpress" LINK "AmiExpress"}\n	package without written permission. The source may not be changed\n	and spread and you may definitely not rip routines from it.\n\n	@{b}This piece of software is shareware. If you use it, then you should\n	send some money to "Postgiro" PG-620 89 92-5. @{ub}You should write\n	your Handle/Group/Board Name/Phone Number on the form.\n\n	@{b}You could also send it by mail to:@{ub} Delusion of Virtual\n				           Vretv.4\n				           73232 Arboga\n				           Sweden\n\n	I would also like to recieve a postcard from your town if you use\n	this software, or something that you''ve made by yourself (like music,\n	graphics or your own coding) :)\n\n	@{i}This entire package is © Copyright Delusion of Virtual\n	1992, 1993, 1994. All rights are reserved. This agreement may\n	be changed without notification.@{ui}\n\n	Finally I hope you really will enjoy this program which will help\n	you a lot as a hardworking sysop, count on that! :)\n\n	Delusion, Sweden 8 April 1994\n\n	@{" Thanks to my Beta Testers " LINK "Beta Testers"}\n@endnode\n\n@node "About Account ED"\n\n	@{b}About the Account ED Package@{ub}\n\n        Account ED V2.00 is © Copyright Delusion of Virtual 1992, 1993, 1994.\n        All rights are reserved. These programs may not be sold by any person,\n        living or dead. A program worth using is worth spreading.\n\n        For new updates call: GANG BANG +46(0)554-12133 Virtual WHQ\n\n        Remember that these programs are not Public Domain, for more info\n        read the complete @{"Disclaimer" LINK "Disclaimer, Copyrights"} Text.\n\n	Account ED has been developed on an Amiga 3000. It has then been\n	running on an A500 BBS. It has been very optimized to run fast\n	even on an A500, but runs extremely fast on any A3000.\n@endnode\n\n@node "AmiExpress"\n\n	@{b}/X AmiExpress@{ub}\n\n        AmiExpress and it''s accompanying files are copyright Joseph Hodge\n        and LightSpeed Technologies. © Copyright 1992-1994.\n\n	AmiExpress was released for the first time 1988 by Mike Thomas!\n\n        Version 2.35 and 3.0 are freeware, but may not be modified in\n        anyway without renaming the software.\n\n	I hope that Mr Hodge will take more time for designing /X in\n	the feature and lower the registration fee which is atronomical!\n@endnode\n\n@node "About ARexx"\n\n	@{b}About ARexx@{ub}\n\n	ARexx is the Amiga version of the Rexx script language.\n\n	ARexx is a commercial product and NOT Public Domain or Shareware.\n	It is a part of the AmigaOS Release 2 Upgrade Kit (and also\n	included in all newer AmigaOS Releases) but can also be purchased\n	from an Amiga dealer.\n\n	ARexx © Copyright 1987 William S. Hawes, Wishful Thinking\n	Development Corp. All rights reserved.\n@endnode\n\n@node "Introduction, Preface"\n\n	@{b}Introduction, Preface@{ub}\n    \n	Finally I''ve rewritten this 6 months old documentation and given\n	it a new look that should be far more easier to read and get some\n	hints from. This is revision V2.00 of the Account ED Package and\n	you might have to take a closer look at some upgraded facilities\n	that is not compatible with V1.05 - V1.03, but here we go from\n	the beginning so hang on ..\n\n	@{"Account Editor" LINK "About Account ED"} (Short name AccED) is a so called @{"ARexx" LINK "About ARexx"} Door for\n	the /X 2.35+ and /X 3.00+ package and will interfere as an AIM\n	(Arexx Interface Module). It will automatically detect which\n	version you are running on and make the appropriate changes!\n\n	If you use this door you can make the security on your board\n	even higher with the high security features of this editor and\n	accompanying doors. All these door is made out of a need which\n	I got when I''ve been running my board! I hope they will fit yours.\n\n	It''s basically a replacement account editor for the old built in\n	and it is really a big difference using this editor compared to\n	the built in. Your life as a sysop will be much easier and looking\n	at users accounts will be more fun. You will also get more control\n	over your users and your system.\n\n	The source is not compiled and should be rather easy for an ARexx\n	programmer to take a look at, which you also should do if you\n	want to be sure there is no backdoors provided with the source\n	from one in the row of people who got it before you. To be sure\n	wether there is a backdoor or not you should call my friend, Chucky''s\n        board called GANG BANG which is the official distribution site for\n	my doors and my /X Echo Mail package which is soon available for a\n	nominal fee. His board will serve as distribution site until I open\n	my board again for the public! I''m right now doing a major update\n	on the Echo Mail program so it can approximately be delivered first\n	in late spring 1994. ßeta versions will be available sooner.\n\n@endnode\n\n@node "Features"\n\n	@{b}Features of the Account Ed Package Doors@{ub}\n\n	@{i}The Main Program@{ui}	@{i}The Accessory Doors@{ui}\n\n	@{" Account ED    " LINK "Features of Account ED"}		@{" F6 Editor        " LINK "Features of F6 Account Editor"}\n				@{" Quest            " LINK "Features of Quest"}\n				@{" Quest View       " LINK "Features of Quest View"}\n				@{" Password Fail    " LINK "Features of Password Fail"}\n				@{" Security Checker " LINK "Features of Security Checker"}\n\n	Note that these features are the most important, there exists\n	many more than these features!\n\n	To get MOST out of this package you should install ALL the above\n	doors, however a minimum installation is possible with only\n	Account ED and Quest. This will of course not give you all benefits!\n\n@endnode\n\n@node "Features of Security Checker"\n\n	@{b}Security Level Checker@{ub}\n\n	A litle tool which will help you against lamers who you by mistacke\n	and/or has given a too high security level to sysop download something\n	and then that lamer logs on and try to hack your board with 255 in\n	security level.\n\n	This tool will check all users who logs on and if they have a higher\n	security level than the one you have specified in the AccEd.Presets\n	file and they are not in the list of sysops you have in the AccEd.Preset\n	file their security level will drop to the security level you have\n	specified in the AccEd.Preset file.\n\n	Their activity will also be logged in the AccEd.Log file, so you\n	later on can see how tries to hack your board!\n\n	This is an example from the log file output:\n\n	04-08-94 Hack  Kalle Hackson         Too high security level (255) (15:06:19)\n\n@endnode\n\n@node "Features of F6 Account Editor"\n\n	@{b}Features of F6 Account Editor@{ub}\n\n	This @{"Account Editor" LINK "About Account ED"} replaces the built in which appears when\n	you press the F6 key inside AmiExpress. However it will for\n	some reason not replace the account editor which appears when\n	you are not logged on and presses F6. This is not the editors\n	fault, it is caused by @{"AmiExpress" LINK "AmiExpress"}.\n\n	In the SYSCmd directory or file I name the door Accounts, but\n	if there is a name which lets you replace the editor which\n	appears when you''re not logged on just enter F6 Edit as the\n	door there too, it should work fine in both cases.\n\n	F6 @{"Account Editor" LINK "About Account ED"} is exactly the same as Account ED, but VERY\n	simplified with only the most common functions which you will\n	need when a user is on-line. If you need more powerful functions\n	use the real Account ED door instead! This door is only useful\n	for upgrading users access and fix creds for them while they''re\n	on-line!\n\n@endnode\n\n@node "Features of Quest View"\n\n	@{b}Features of Quest View@{ub}\n\n	Quest View is simple a program for your users to peek at each\n	others questionnaires. The sysop can decide which questions the\n	user won''t be shown and the user himself can decide if he should\n	let the other users see this or not show his quest at all:\n\n	Name\n	Address\n	Phonenumber\n\n	These three items will of course only be available if the sysop\n	has put these three questions in the questionary sheet.\n\n	If the user wanted his personal info Public, Private or Secret\n	will be	stored in the Account/QuestApp/X.Dat file where X is\n	the users slot number.\n\n	After displaying the users questionary, Quest View will also\n	display some status about the user:\n\n	Uploads/Downloads Bytes & Files\n	UL/DL Ratio\n	Number of Calls\n	Number of written Messages\n	BaudRate\n	Last Time On-line\n	Overall user performance ratio (Account ED Package Specific)\n\n	This will give a clear picture of the user and could be useful\n	for other sysops checking up a user who gave references to your\n	board!!!\n\n@endnode\n\n@node "Features of Quest"\n\n	@{b}Features of Quest@{ub}\n\n	Quest lets you skip your Script14400 files and the Answers file\n	which gives many sysops a hard headache.. I think you know\n	what I mean when you''ve got 4 new users and then you should\n	update them, phew what a boring job.. Load your answers file\n	into CED and then go to the bottom of a 200kb large file!\n\n	@{" In conjunction with Account ED " LINK "QuestED"}\n	@{" Questionary Sheet              " LINK "Sheet"}\n	@{" Letter                         " LINK "QuestLetter"}\n	@{" Questioning old users          " LINK "OldQuest"}\n	@{" Force answers                  " LINK "Force"}\n	@{" Automatic Access               " LINK "Auto Access"}\n	@{" Space saving                   " LINK "Space"}\n	@{" Safety backups                 " LINK "Backups"}\n\n@endnode\n\n@node "QuestED"\n\n	When running Account ED & Quest, which are the perfect couple..\n	You get access to some notable features.\n\n	Quest lets your users answer to all questions you prefer and\n	then stores their answers separately in the Account/QuestApp\n	directory. If you then want to look at any applications you just\n	search for that user in the @{"Account Editor" LINK "About Account ED"} and then press the / key\n	and you will then immediately have that users application on your\n	screen. If it concerns new user you just use the Scan for New Users\n	function in the Account Editor and you will both see the users\n	account and the questionary!! That''s what I call powerful!\n	You can even print the users questionary if you like to!\n\n	All questions are of course configurable and you will in the\n	future be able to both look at the users account and then\n	also see some information displayed from the questionary!\n\n@endnode\n\n@node "Sheet"\n\n	Quest has a questionary sheet in which you almost can program\n	which sort of actions that should be taken.\n\n	You could for instance tell that this question asks for the\n	name of the user and then Account ED and Quest View could make\n	use of it! You can enter lines that won''t be asked if you have\n	long questions and much more!\n\n	For more information take a look in the installation chapter\n	for the @{"Questionary Sheet" LINK "ConfigQuest"}!\n\n@endnode\n\n@node "QuestLetter"\n\n	After the user has answered all the questions he will be forced\n	to enter a presentation letter to the sysop or cosysop. The\n	person who will receive the letter is configurable.\n\n@endnode\n\n@node "OldQuest"\n\n	Suppose that you have installed quest and haven''t been running\n	it before, you now regret it and thinks that it would have\n	been nice to view all your users questionnaires within the\n	Account Editor, as you can do with Quest!\n\n	The solution is to setup Quest as an MCI command in one of\n	your login bulletins which all users can view.\n\n	Just add this to the top of the bulletin: ~CC_QUEST\n\n	This will invoke Quest every time this bulletin is shown, Quest\n	then knows if a user has answered his questionary and Quest\n	will only be started the first time the user gets the bulletin.\n\n@endnode\n\n@node "Force"\n\n	Quest has a built in feature which forces the user to not leave\n	any line blank. It could also be configured to kickout the user\n	if he just presses return 5 times!\n\n	All this features is of course configurable.\n\n@endnode\n\n@node "Auto Access"\n\n	If you are a busy sysop you know that it''s not much use of you\n	looking for the users questionary and then giving them some lame\n	access until you see that the user uploads. It would be much easier\n	if the questionary program automatically gave the user lamer access\n	if he just answers all questions!\n\n	Quest checks if the user is neglecting the questions and if he don''t\n	the user will the access specified in the first preset! All presets\n	are located in the AccEd.Presets file (together will all configs)\n\n@endnode\n\n@node "Space"\n\n	Using Quest will save space on your harddrive because it only\n	saves the answers and not the questions, which you already have\n	in your questionary sheet.\n\n	Quest takes the questions from your sheet and the answers from\n	the users application and then displays it on your screen. This\n	method gives you some extra features said in @{"Questionary Sheet" LINK "Sheet"}\n	feature!\n\n@endnode\n\n@node "Backups"\n\n	Once I got a virus on my Harddrive which wrote FUCK all over my\n	harddrives block, so almost every file got a fuck within it!\n\n	My user datas got totally (litterarily) FUCKED UP and my users\n	wanted their credits back, they didn''t have an account and so on!\n	I didn''t know their password (strange ehh?) and therefor it was\n	impossible for me to do anything, but to delete the data files!\n\n	The phone number and name and such thing however was left in my\n	300 applications files, but without passwords...\n\n	I therefor have put in a feature which posts the new users password\n	in his questionary for use if an emergency situation would occur.\n\n	But it would be a rather hardtime login on 300 users manually\n	so Quest ALSO save the new users DATA and KEYS into one file\n	which is called Slotnumber.DAT, for example 1.DAT. The *.Dat file\n	also has got some flags for the user, if he want''s to show his\n	address and name to other users and such things.\n\n	Account ED is then capable of loading in a backup of a users\n	account anytime inside the @{"Account Editor" LINK "About Account ED"}, by pressing the SHIFT-B\n	key! Every time you save a users account this .DAT file is also\n	updated to keep it as fresh as possible for you!\n\n	Could also be useful if you manage to fuckup a users account\n	and wants the old account back!\n\n@endnode\n\n@node "Features of Password Fail"\n\n	@{b}Features of Password Fail@{ub}\n\n	Password Fail is a simple util which lets your users answers some\n	short questions, write a letter to sysop and operate the sysop if\n	the users fails to enter the correct password when logging on\n	your system.\n\n	@{" Questioning " LINK "Questioning"}\n	@{" Letter      " LINK "Letter"}\n	@{" Operate     " LINK "Operate"}\n	@{" Log Files   " LINK "Logging"}\n\n@endnode\n\n@node "Questioning"\n\n	When a user fails to enter his password three times, Pw Fail will\n	be envoked and let your user answer some basic questions.\n\n	Name\n	Address\n	Security Code\n	Phone Number\n\n	The password the user thought he had\n	The new desired password\n@endnode\n\n@node "Letter"\n\n	After filling out the basic questions, the user will have to write\n	a letter to the sysop, with some presentation and tell something\n	that makes the sysop certain that this is the real user.\n\n	Together with the letter, PW Fail will post the questionary\n	and the three password which the user tried to log on with.\n	There will also be some additional information posted with the\n	letter which PW Fail could find out.\n\n	The letter will be posted to you or one of your cosysops, depending\n	on which name you have written as the receiver in the config file.\n@endnode\n\n@node "Operate"\n\n	After the user has filled out the letter, PW Fail gives him a chance\n	to operate the sysop before dropping the carrier!\n@endnode\n\n@node "Logging"\n\n	PW Fail will log all persons who fails with their passwords in\n	a log file which is called PFail.log and is located in the Account/\n	directory..\n\n	If you have some users who frequently forget their passwords it''s\n	easy to see in the log file, and it only gives a clear picture if\n	someone is trying to hack your board. A hacker who tries to cover\n	his tracks, may also not be aware of this log file, which could\n	give you some hint of who hacked your board, if someone does it!\n\n\n	Example:\n\n	Delusion       05-08-93 17:52:15 PW: (vf44kllk) (vf43fdfg) (vd£2fggg)\n	Delusion       05-08-93 17:55:47 PW: (v7dj32kl) (vfs3w456) (vd113454)\n\n\n	Here it''s easy to see what users have tried, even if you have a\n	callerslog cutter, all users mistyped passwords will be preserved\n	and you can easy see a pattern if someone tries to hack your board!\n\n	Maybe I''ll make a TOP PASSWORD forgetters util which can be used\n	together with this logfile later on :)\n\n@endnode\n\n@node "Features of Account ED"\n\n	@{b}Features of Account ED@{ub}\n\n	Account ED is designed with high security in mind and I think my\n	door is the first one that can lock out a user at a specific time\n	period, ie between 24.00 and 08.00 in the morning if you think\n	that no one should access the @{"Account Editor" LINK "About Account ED"} then. Below this text\n	follows most of the features available in Account ED. Enjoy!\n\n\n            @{" New features            " LINK "NewFeatures"}   @{" Print account           " LINK "PrintAccount"}\n            @{" Name checking           " LINK "NameCheck"}   @{" Print questionnaires     " LINK "PrintQuest"}\n            @{" Password checking       " LINK "PasswordCheck"}   @{" Quest compatibillity    " LINK "QuestCompatible"}\n            @{" Restrict commands       " LINK "RestrictCommands"}   @{" Messagebase cleaner     " LINK "MsgBaseCleaner"}\n            @{" Conference Access       " LINK "ConferenceAccess"}   @{" Lock users passwords    " LINK "LockPassword"}\n            @{" Userlist tool           " LINK "UserlistTool"}   @{" Security conference     " LINK "SecurityConference"}\n            @{" Write warning note      " LINK "WarningNote"}   @{" Built in calculator     " LINK "Calculator"}\n            @{" Credit Maintenance      " LINK "Credit"}   @{" Compatibility!!         " LINK "Compatibility"}\n            @{" Credited Users List     " LINK "CreditList"}   @{" Activity reports        " LINK "LogFiles"}\n\n\n	These are more features than many doors together can''t provide you\n	with, so you''d better consider to take a closer look or you''ll\n	have to regret it! :)\n\n	Note! AccountED will autodetect which /X version you are running\n	      and reconfigure itself for your version! (2 programs in 1)\n@endnode\n\n@node "CreditList"\n\n	@{b}Credit UserList Creator@{ub}\n\n	For AmiExpress users 3.37 and over you can use the built in Credit\n	UserList Creator. This will enable you to see the total amount of\n	money paid to your BBS and the total amount of money paid the last\n	time to your board.\n\n	This is how the output could look:\n\n	1 Delusion    oo Virtual oo 255 240338912 567 31 Mar 94 06 Nov 94 1234\n\n	Slot            Security Level  Downloads  |    Start      End    Total\n                                                   |                      Paid\n                                           Paid Last\n\n	This will give you a pretty clear overview of your credited users!\n\n@endnode\n\n@node "Credit"\n\n	@{b}Credit Maintenance Editor@{ub}\n\n	From version 3.37 of AmiExpress there is a Credit Maintenance Editor\n	included in the internal Account Editor. This one is 100% compatible,\n	but has the same advantages as the AccountED like calculator and\n	wordprocessor-like editing capabilities!\n\n	For you with older versions of AmiExpress this feature will disappear\n	because crediting will only be useful if your system supports it!\n\n	What is crediting? Crediting keeps track on how much a user has paid\n	for Free Download in a certain period and also removes the Free DL\n	after that period. It also keep track on the total amount of money\n	that user has paid to the system!\n\n	NOTE! Account ED''s credit util will create a CreditLog file which\n	      is NOT compatible with the built in (which doesn''t affect\n	      anything), but it''s MUCH MORE easier to read and doesn''t\n	      look like shit when you want to look at it (like the built in)!\n@endnode\n\n@node "Compatibility"\n\n	@{b}Account ED''s enormous Compatibility@{ub}\n\n	This is the most compatible door of this class I know. It will work\n	on the following configurations:\n\n	AmiExpress 2.0 and higher\n	AmiExpress 3.0 and higher\n\n	and even AmiExpress 3.37 and higher\n\n	These versions really differs in the way of handling the user data.\n	Version 2.0 to 3.0 does only have 9 conferences and you mark them\n	with a X or _ depending on what access you give them.\n\n	Version 3.0 to 3.36 has a scrambled password for each user and also\n	uses unlimited conferences and therefore has got a name instead\n	of X and _:s, these show what conferences the user got access to.\n\n	Somewhere between version 3.20 and 3.37 Chat limit time and Chat\n	used time was added to the user data. Of course this has been added\n	to Account ED too, and it only works from 3.20 and higher!\n\n	Credit Maintenance util was introduced in AmiExpress 3.37 and\n	to keep compatibility I included one in Account ED too. This\n	utility can''t be used by other /X versions.\n\n	NOTE! If you have an older /X you won''t notice all new features\n	      because they are hidden for you. If you upgrade your /X\n	      you can immediately take advantage of them :)\n\n@endnode\n\n@node "NameCheck"\n\n	@{b}User Name Checking@{ub}\n\n	It checks if a person got the right name from a list of\n	persons allowed to use the @{"Account Editor" LINK "About Account ED"}. This works in the same\n	way as Maltese Falcons Remote Shell and Sysop Download utils.\n@endnode\n\n@node "PasswordCheck"\n\n	@{b}User Password Checking@{ub}\n\n	This function is configurable so if you don''t want it, it won''t\n	ask for a password. Some want it so it''s the only reason why it\n	exists. If you enter a password instead of the blanks in the\n	AccED.Preset file it will ask for the password. The letters you\n	type will be replaced with *''s!\n@endnode\n\n@node "LogFiles"\n\n	@{b}Activity Reports@{ub}\n\n	Every entry in the user data that someone who is in Account ED\n	look at will be reported and logged in a special Account ED log\n	file. It will also add comments if someone read or wrote an account\n	and if you print an account.\n@endnode\n\n@node "PrintAccount"\n\n	@{b}Print User Account@{ub}\n\n	Yes, you could actually print an account to your printer using the\n	printer settings from your Amiga DOS.\n	This feature is really my favorite, if you are going to delete a\n	user you could easily print the users account before selecting\n	delete and store it somewhere for no special reason ..\n@endnode\n\n@node "PrintQuest"\n\n	@{b}Print User Questionary@{ub}\n\n	Printing a questionary works exactly the same as printing an\n	account, thus you got to have the Quest Package too (available\n	at INSANiTY, if your local boards can''t provide you)\n@endnode\n\n@node "RestrictCommands"\n\n	@{b}Restrict Certain Commands@{ub}\n\n	You can lock certain functions in the @{"Account Editor" LINK "About Account ED"} for your\n	cosysops so they only could use the 6 pre defined presets, no\n	I''m joking .. 6 presets, NO! the 9 pre defined presets with a\n	comment which you can write so the cosysop knows what each preset\n	stands for and for which users they are meant. Nice ehh!?\n@endnode\n\n@node "ConferenceAccess"\n\n	@{b}Give/Remove Conference Accesses@{ub}\n\n	Like the MCP (Master Control Program) by Bryce, you can give and\n	take access for a conference for all your users, so if you close\n	a conference you easily can delete all users access to it or if\n	you simply have started a new area. But.. wouldn''t it be nice to\n	go a little bit further and include one more nice feature into that\n	powerful command? Yes! You can define between which two access\n	levels a user must be so you could give/take access from users who\n	only has got the security level 30 to 40 i.e..\n@endnode\n\n@node "UserlistTool"\n\n	@{b}Full UserList Tool@{ub}\n\n	The need for a powerful and fast userlist creator has now been\n	fulfilled. This userlist creator can create any userlist you\n	want and also save it as a file.\n\n	- Do you want a plain userlist with all user who has security level\n	  200 to 255, no problem.\n\n	- Do you want a userlist with all users who has uploaded 2 megabytes\n	  and downloaded maximum 30 megabytes and has got access to\n	  conference 4 ??? NO PROBLEM\n\n	- What about a look over the ul/dl stats for all users with disabled?\n\n	- Perhaps all members to a certain area..\n\n	- Or what about.. All users that has security level 50 to 80, has\n	  uploaded minimum 10 mb and maximum 50 mb, has downloaded min 30 mb\n	  and max 100 mb and also has got access to area 6! Can your userlist\n	  maker do THAT? Well I doubt that anyway..\n\n	There are no limits in this *VERY* sophisticated userlist tool\n	which handles all of the above and more with just one routine!\n\n	All this comes with a very nice ANSI output and some stats about\n	how many percent of the users you''ve listed and so on..\n@endnode\n\n@node "NewFeatures"\n\n	@{b}The New Features@{ub}\n\n	Back to the main @{"Account Editor" LINK "About Account ED"} there are some major line ups if\n	you compare to the built in editor. First of all the design is\n	made to be easy to overview and fast to get some particular\n	information about one user. The built in one was so messy that I\n	had a hard time to understand my own account with the download /\n	upload cps and location put like a joke on the screen. This is\n	should be easy to read and each function has got new letters\n	because the old ones was worn out and not well placed. I hope\n	you''ll soon learn the new keys!\n@endnode\n\n@node "HelpPage"\n\n	@{b}Help Page@{ub}\n\n	The help page inside the @{"Account Editor" LINK "About Account ED"} is for easy access to\n	the most common functions inside the editor. You simple press\n	a key and you can view it at the same time as the account is on\n	the same page so you easily could compare and so on.\n@endnode\n\n@node "QuestCompatible"\n\n	@{b}Quest Comatibillity@{ub}\n\n	If you have used my Questionary Door called Quest (last version\n	V1.09) this program is fully compatible with Quest. Anytime when\n	you are reading a persons account you could press a key and get\n	that users questionary on your screen. Very useful if you upgrade\n	first time users.. I think you remember yourself loading a text-\n	editor with your Answers file and trying to upgrade that poor\n	users account, but how did your cosysops manage!? I guess that\n	they didn''t and the security with new users failed on your board!\n@endnode\n\n@node "WarningNote"\n\n	@{b}Give User a Warning Note@{ub}\n\n	Ever wanted a function that writes a letter very fast to your\n	users and saying that they should upload and shows the users\n	stats with uploaded/download bytes & file, calls and messages?\n	Well it''s built in into Account ED!\n\n	You don''t have to write a single line, just press a key..\n@endnode\n\n@node "MsgBaseCleaner"\n\n	@{b}Message Base Cleaner Tool@{ub}\n\n	A thing that can make your nerves pop up is when you have\n	to delete old received messages from users who has not choosen\n	delete then they''ve replied letters and all those EALL messages\n	that your new users hate.. Account ED has a built in function\n	which scans your msgbase and deletes old mail and asks what\n	you want to do with the EALL messages!!\n@endnode\n\n@node "LockPassword"\n\n	@{b}Show/Remove User Password@{ub}\n\n	You can give a special access level for viewing the passwords\n	of all accounts, if you do not have this security level Account ED\n	will prompt Not Displayed as a password. You can choose if the\n	password default should be shown to the ones with the security\n	level or they have to press a special key combination for the\n	password to appear. Useful if you have some friends beside you!\n@endnode\n\n@node "SecurityConference"\n\n	@{b}High Security Conference@{ub}\n\n	What about security for your groups conference then? Well as this\n	program has been around a while I''ve thought of that too, so you\n	could specify a conference to which no one could give access!\n	This means that your cosysop can not give himself access to your\n	groups member area!!\n@endnode\n\n@node "Calculator"\n\n	@{b}Full Built-in Calculator@{ub}\n\n	Ok I see that you are beginning to understand why I developed\n	this new @{"Account Editor" LINK "About Account ED"}, so I will now give you only one more\n	reason to use it. If you sometimes have an upload competition on\n	your board you know how annoying it is to give that poor winner\n	his rewarded upload credits, it usually means that you have\n	to run down the stairs to get a pocket calculator and then\n	enter his new upload bytes. But you could stop doing that\n	already today if you use this account editor with built in\n	calculator which can add and sub from a users account. You just\n	choose the field you want to change and use the upper case of\n	the letter instead and you will be asked if you want to sub or\n	add and how many bytes. This works for all fields that has got\n	to do with upload, download and limits.\n@endnode\n\n@node "FieldEditor"\n\n	@{b}The New Field Editor@{ub}\n\n	Oh, sorry I forgot to tell you one thing. In the /X account editor\n	when you choose i.e. to change the users uploaded creds it clears\n	that field and you have to try to remember what there was standing.\n	My @{"Account Editor" LINK "About Account ED"} will not remove anything it works just like\n	any professional editor like Cygnus ED. You write something and\n	the text before your cursor will move to the right. If you use\n	backspace the text to the light of the cursor will move to the left!\n	The field that you may use for that specific item in the editor\n	is also highlighted in blue, to give you a better overview!\n\n	Of course the text that stood there before will be there until you\n	use your DEL or BACKSPACE key to remove it.\n@endnode\n\n@node "Installation 2.10+ .."\n\n	@{b}Installation on a based /X 2.10+ System ..@{ub}\n\n	@{" File installation          " LINK "Install2.10+"}\n	@{" Info about the Preset file " LINK "Preset Info!"}\n	@{" Preset file configuration  " LINK "Presets2.10+"}\n	@{" Questionary configuration  " LINK "ConfigQuest"}\n	@{" Upgrade notes              " LINK "Upgrade"}\n\n	It''s recommended to make a backup of you critical files before\n	running this door if you want to be 100% sure so it doesn''t damage\n	anything. The door has worked in most environments, but the\n	developers of @{"AmiExpress" LINK "AmiExpress"} rapidly changes their data file\n	structures and that may cause failure on your system.\n\n	Backup this:\n\n	BBS:User.Data\n	BBS:User.Keys\n\n	BBS:Conf{x}/MsgBase/HeadFile\n	BBS:Conf{x}/MsgBase/MailStats\n\n	These are the only files that the Account ED Package touches!\n@endnode\n\n@node "Installation 3.00+ .."\n\n	@{b}Installation on a based /X 3.00+ System ..@{ub}\n\n	@{" File installation          " LINK "Install3.00+"}\n	@{" Info about the Preset file " LINK "Preset Info!"}\n	@{" Preset file configuration  " LINK "Presets3.00+"}\n	@{" Questionary configuration  " LINK "ConfigQuest"}\n	@{" Upgrade notes              " LINK "Upgrade"}\n\n	It''s recommended to make a backup of you critical files before\n	running this door if you want to be 100% sure so it doesn''t damage\n	anything. The door has worked in most environments, but the\n	developers of @{"AmiExpress" LINK "AmiExpress"} rapidly changes their data file\n	structures and that may cause failure on your system.\n\n	Backup this:\n\n	BBS:User.Data\n	BBS:User.Keys\n\n	BBS:Conf{x}/MsgBase/HeadFile\n	BBS:Conf{x}/MsgBase/MailStats\n\n	These are the only files that the Account ED Package touches!\n@endnode\n\n@node "Preset Info!"\n\n	@{b}Information About The Preset File@{ub}\n\n	The preset file is the most important file for Account ED.\n	Without it shouldn''t work. It''s also important that\n	you update your preset file at the same time as you update\n	your Account ED Version.\n\n	The preset file consist of many configurations for:\n\n	Account ED	- The Account Editor\n	F6 Editor	- Same as Account ED, but for online use\n	Quest		- New User Questionary Program\n	Quest View	- Questionary Viewer for Users\n	Password Fail	- If a user has forgotten the password\n\n	You do only have to configure the settings for the programs\n	you have installed. All other data will be ignored by AccED.\n\n	For a hacker the AccEd.Preset file should be of high priority\n	so should restrict that file in every door you have and in\n	your Acp.StartUp file.\n@endnode\n\n@node "Upgrade"\n\n	@{b}Upgrading from older versions of Account ED@{ub}\n\n	You have to completely rewrite you AccED.Preset file if you\n	are upgrading from < V1.03. Upgrading from V1.04-1.05 will only\n	require slightly adjustments.\n\n	Previous user must note that there should be 3 new directories inside\n	the Account/ directory called: QuestApp, QuestDel and QuestQst.\n	if you are previous running Quest and has got it in the\n	Doors:Arexx/Quest/ dir you should move your questions from the answers\n	dir to the QuestApp dir in the Account directory. Otherwise Account ED\n	can''t read the questionaries! (More info in the Quest doc file)\n\n	The questionary files for Quest has been changed!! You now has to add\n	one more item before every question. Before it stood ~NQuestion, now\n	it should stand ~N!Question the ! character marks if the question\n	should be showed, when a user uses the Quest View program to look\n	up a user, in this way a sysop can protect some of the secret info\n	that he doesn''t want the other users to know about each others!\n\n	In previous preset files (V1.03) the computer list was in this form:\n	Amiga 500¬Amiga 1000¬ and so on, now it should stand in descending\n	order in the column which says computers.\n\n	Under the names with the persons who has got access to Account\n	(Delusion Fox ''N'' Philix D-Zire) is all the configuration datas for\n        both Quest and Account ED, all values who has got to do with Quest is\n	explained separately in the Quest Doc.\n@endnode\n\n@node "ConfigQuest"\n\n	@{b}Configuration of the Questionary Sheet@{ub}\n\n	Old users of Quest should also read this, it''s completely different!\n\n	As you may be familiar to the MCI commands inside /X I''ve created\n	something that looks the same, but in a reverse mode if you could\n	say so. Before every question you can give these command:\n\n	~	- Just question that question\n	        - Nothing, means it''s a comment and will only be displayed\n	~N	- It tells Account ED that the users real name is asked\n	~A	- Tells that it''s the users address being asked, note that\n		  you can use this command unlimited times in your quest\n	~C	- Tells that you are asking for the users country\n	~V	- Tells that you are asking for the users Voice Phone Number\n	~D	- Tells that you are asking for the users Data  Phone Number\n	~S	- Tells that you are asking for the users Sex & Age\n	~P	- Tells that you are asking for the users Social Security Code\n	~U	- Tells that you are asking for what the users does with his\n		  computer and such things.\n	~W	- Tells that you are asking for from where he got you phone #\n	~R	- Tells that this is a question with the reasons why you should\n		  let that user in. You can use this command unlimited times\n		  to give the users more than one line to answer on!\n	~E	- Just like the ~A and ~R command, but this is for the users\n		  presentation.\n\n	~ !	- The ! command means that this question won''t be displayed\n		  then a user is looking at another users questionary with\n		  the Quest View program. This is useful if the sysop doesn''t\n		  want to share all information in the questionnaires with\n		  the users!!\n\n	Example:\n\n	~N!What is your name ? :\n\n	This asks the user of his name, and other users can not look at his\n	name through the Quest View program, of course is it viewable for the\n	sysop and cosysops!\n\n	~  What do you think about Coca Cola ? :\n\n	This just asks the question!\n\n	   --------- Personal Info -----------\n\n	This will just display this text! Note the 3 Spaces before the actual\n	text starts! This is the command for displaying a text!\n\n	For your comfort n example questionary has been included. The quest\n	is originally designed by The Silencer / TRSI, but slightly remade\n	by Delusion and of course improved!\n\n	Anyway you now might wonder why you should tell the Questionary program\n	what you intend to ask and such things, well it''s very simple!\n	In coming versions of Account ED it should be possible to both get\n	the users Account and the most essential information from the questionary\n	on the screen at the same time, like the users name and social security\n	code. I have NOT coded that feature in Account ED yet, but it will\n	very soon come. So here is your chance to be one step ahead :) so you\n	will have it working as soon as the new Account ED arrives.\n\n	However Quest View make use of these letter combinations to keep track\n	on what to display or not. A user could choose to not show his addy\n	and phone number to other users, and therefor Quest View need to know\n	what is the name and so on.\n\n	In older versions of Quest you could choose to save the users answers\n	with questions and answers or answers alone. Because of the above said\n	new features the questions and answers format doesn''t work so therefor\n	that function has been removed and you can only save the answers alone.\n\n	Account ED still supports both formats so you can view older\n	questionaries, but you have to the ~X commands to your old questionaries\n	if you have some in your Doors:Arexx/Quest/Questions directory and copy\n	them into the Doors:Arexx/Account/QuestQST dir. As you may have guessed\n	the function with displaying info in Account Ed will not work on old\n	questionnaires which is in the form Questions - Answers. I will maybe\n	fix a converter util for that.\n\n	Note that all commands has to be three chars, if you only have a ~ on\n	a question it should look like "~  " and if you have a two chars command\n	it should look like "~N " and for the three character command you should\n	write "~N!".\n\n	In otherwords this means that all questions should start on column 4\n	and in column 1, 2 and 3 there should be the commands!\n@endnode\n\n@node "Presets2.10+"\n\n  @{"Comment" LINK "Comment"}         @{"SecL" LINK "SecL"} @{"RaT" LINK "RaT"}@{"RaF" LINK "RaF"} @{"Aut" LINK "Aut"} @{"Bytelimit" LINK "Bytelimit"} @{"ConfAccess" LINK "ConfAccess2.10+"} @{"TimeLim" LINK "TimeLim"}  @{"Computers" LINK "Computer List"}\n@{"7" LINK "NumberofPresets"}-------------------------------------------------------------@{"2.00" LINK "VersionNumber"}-------------------\n| Lamer          | 5   | 1 | 2 | 1 | 100000   | X________ | 1200  | Amiga 500        |\n| PD User        | 20  | 1 | 3 | 2 | 500000   | X_X__X_X_ | 3600  | Amiga 500+       |\n| Elite User     | 30  | 1 | 3 | 4 | 2500000  | X_XX_X_X_ | 3600  | Amiga 600        |\n| Elite Trader   | 40  | 1 | 3 | 7 | 5000000  | X_X__XXX_ | 4800  | Amiga 1000       |\n| Virtual Member | 50  | 1 | 0 | 4 | 10000000 | X_XXXX_X_ | 7200  | Amiga 1200       |\n| Virtual Member | 50  | 1 | 0 | 7 | 10000000 | X_X_XXXX_ | 7200  | Amiga 2000       |\n| Proud CoSysop  | 230 | 0 | 0 | 7 | 10000000 | X_XX_XXXX | 14400 | Amiga 3000       |\n|                |     |   |   |   |          |           |       | Amiga 4000       |\n|                |     |   |   |   |          |           |       | PC Com 286       |\n@{"2359" LINK "Time Zones"}----------------------------------------------------------@{"0730" LINK "Time Zones"} PC Com 386       |\n| @{"Delusion Fox N Philix D-Zire                                   " LINK "Users Allowed"} | PC Com 486       |\n------------------------------------------------------------------- PC Com 586       |\n| @{"UserData Path   " LINK "UserData Path"} | BBS:User.Data     | @{"Enable Seclevel " LINK "Enable Seclevel"} |  255 | Atari 1040       |\n| @{"UserKeys Path   " LINK "UserKeys Path"} | BBS:User.Keys     | @{"ChangeAcc Seclev" LINK "ChangeAcc Seclev"} |  255 | Other            |\n| @{"Write Note Path " LINK "Write Note Path"} | BBS:Conf-7/       | @{"MsgBaseClean Sec" LINK "MsgBaseClean Sec"} |  255 |                  |\n| @{"AccED Password  " LINK "AccED Password"} | Transworld        | @{"See Users Pass  " LINK "See Users Pass"} |  255 |                  |\n| @{"DeleteQuest Pass" LINK "DeleteQuest Pass"} | Bobolink          | @{"Show Users Pass " LINK "Show Users Pass"} |  Off |                  |\n| @{"Recieve App Mail" LINK "NewUser Letter"} | Delusion          | @{"Print Account   " LINK "Print Account"} |   On |                  |\n| @{"AccountED Colour" LINK "AccountED Colour"} | [0m              | @{"Edit own Account" LINK "Edit own Account"} |   On |                  |\n| @{"Members Conf    " LINK "Members Conf 2.10+"} | 5                 | @{"Search New Users" LINK "Search New Users"} |  300 |                  |\n| @{"Credit Account  " LINK "Credit Account"} |                   | @{"Log Status AccED" LINK "Log Status AccED"} |    4 |------------------|\n| @{"Security Check  " LINK "Security Check"} | 230               | @{"Kickout After X " LINK "Kickout After X"} |    5 | @{"Amiga Ansi      " LINK "Ansi Types"} |\n| @{"Set Security Lev" LINK "Set Security"} | 30                | @{"Questionary     " LINK "Questionary"} |    4 | @{"IBM Ansi        " LINK "Ansi Types"} |\n| @{"Reserved 1      " LINK "Reserved"} |                   | @{"Auto UL Amount  " LINK "Auto UL Amount"} |    4 | @{"Macintosh Ansi  " LINK "Ansi Types"} |\n| @{"Path NewUserConf" LINK "Path NewUserConf"} | BBS:Conf-1/       | @{"AutoAccess Quest" LINK "AutoAccess Quest"} |   No | @{"                " LINK "Ansi Types"} |\n| @{"Rec PW Fail Mail" LINK "Password Fail"} | Fox ''N'' Philix    | @{"MustEnter No Ret" LINK "Must Enter No Return"} |  Yes | @{"                " LINK "Ansi Types"} |\n--------------------------------------------------------------------------------------\n\nThis is how it could look. Do not snap this one, use the supplied\none in this archive called AmiEx2.0/AccED.Presets. Please note that everything\nis position dependant, all configuration parameters must stand between\na | and a | so it could look like this |         BBS:User.Data | or\n| BBS:User.Data.          | it doesn''t matter.\n\n@endnode\n\n@node "Presets3.00+"\n\n  @{"Comment" LINK "Comment"}         @{"SecL" LINK "SecL"} @{"RaT" LINK "RaT"}@{"RaF" LINK "RaF"} @{"Aut" LINK "Aut"} @{"Bytelimit" LINK "Bytelimit"} @{"ConfAccess" LINK "ConfAccess3.00+"} @{"TimeLim" LINK "TimeLim"}  @{"Computers" LINK "Computer List"}\n@{"7" LINK "NumberofPresets"}-------------------------------------------------------------@{"2.00" LINK "VersionNumber"}-------------------\n| Lamer          | 5   | 1 | 2 | 1 | 100000   | Lamer     | 1200  | Amiga 500        |\n| PD User        | 20  | 1 | 3 | 2 | 500000   | Party     | 3600  | Amiga 500+       |\n| Elite User     | 30  | 1 | 3 | 4 | 2500000  | AmiEx     | 3600  | Amiga 600        |\n| Elite Trader   | 40  | 1 | 3 | 7 | 5000000  | AmiEx     | 4800  | Amiga 1000       |\n| Virtual Member | 50  | 1 | 0 | 4 | 10000000 | Member    | 7200  | Amiga 1200       |\n| Virtual Member | 50  | 1 | 0 | 7 | 10000000 | Member    | 7200  | Amiga 2000       |\n| Proud CoSysop  | 230 | 0 | 0 | 7 | 10000000 | Cosysop   | 14400 | Amiga 3000       |\n|                |     |   |   |   |          |           |       | Amiga 4000       |\n|                |     |   |   |   |          |           |       | PC Com 286       |\n@{"2359" LINK "Time Zones"}----------------------------------------------------------@{"0730" LINK "Time Zones"} PC Com 386       |\n| @{"Delusion Fox N Philix D-Zire                                   " LINK "Users Allowed"} | PC Com 486       |\n------------------------------------------------------------------- PC Com 586       |\n| @{"UserData Path   " LINK "UserData Path"} | BBS:User.Data     | @{"Enable Seclevel " LINK "Enable Seclevel"} |  255 | Atari 1040       |\n| @{"UserKeys Path   " LINK "UserKeys Path"} | BBS:User.Keys     | @{"ChangeAcc Seclev" LINK "ChangeAcc Seclev"} |  255 | Other            |\n| @{"Write Note Path " LINK "Write Note Path"} | BBS:Conf-7/       | @{"MsgBaseClean Sec" LINK "MsgBaseClean Sec"} |  255 |                  |\n| @{"AccED Password  " LINK "AccED Password"} | Transworld        | @{"See Users Pass  " LINK "See Users Pass"} |  255 |                  |\n| @{"DeleteQuest Pass" LINK "DeleteQuest Pass"} | Bobolink          | @{"Show Users Pass " LINK "Show Users Pass"} |  Off |                  |\n| @{"Recieve App Mail" LINK "NewUser Letter"} | Delusion          | @{"Print Account   " LINK "Print Account"} |   On |                  |\n| @{"AccountED Colour" LINK "AccountED Colour"} | [0m              | @{"Edit own Account" LINK "Edit own Account"} |   On |                  |\n| @{"Members Conf    " LINK "Members Conf 3.00+"} | Member            | @{"Search New Users" LINK "Search New Users"} |  300 |                  |\n| @{"Credit Account  " LINK "Credit Account"} | 255               | @{"Log Status AccED" LINK "Log Status AccED"} |    4 |------------------|\n| @{"Security Check  " LINK "Security Check"} | 230               | @{"Kickout After X " LINK "Kickout After X"} |    5 | @{"Amiga Ansi      " LINK "Ansi Types"} |\n| @{"Set Security Lev" LINK "Set Security"} | 30                | @{"Questionary     " LINK "Questionary"} |    4 | @{"IBM Ansi        " LINK "Ansi Types"} |\n| @{"Reserved 1      " LINK "Reserved"} |                   | @{"Auto UL Amount  " LINK "Auto UL Amount"} |    4 | @{"Macintosh Ansi  " LINK "Ansi Types"} |\n| @{"Path NewUserConf" LINK "Path NewUserConf"} | BBS:Conf-1/       | @{"AutoAccess Quest" LINK "AutoAccess Quest"} |   No | @{"                " LINK "Ansi Types"} |\n| @{"Rec PW Fail Mail" LINK "Password Fail"} | Fox ''N'' Philix    | @{"MustEnter No Ret" LINK "Must Enter No Return"} |  Yes | @{"                " LINK "Ansi Types"} |\n--------------------------------------------------------------------------------------\n\nThis is how it could look. Do not snap this one, use the supplied\none in this archive called AmiEx3.0/AccED.Presets. Please note that everything\nis position dependant, all configuration parameters must stand between\na | and a | so it could look like this |         BBS:User.Data | or\n| BBS:User.Data.          | it doesn''t matter.\n@endnode\n\n@node "Install2.10+"\n\n	@{b}File installation@{ub}\n\n	Add the AmiEx2.0/BBS.Cmd file and AmiEx2.0/SYS.Cmd file to your\n	Cmd files in your BBS:Commands directory\n\n	@{b}OR:@{ub}\n\n	Snap the following row to your BBS:Commands/BBS.Cmd file:\n\n	@{b}*1        Rm230Doors:Arexx/Account/AccED.rexx@{ub}\n	@{b}QUEST     Rm005Doors:Arexx/Account/Quest.Rexx@{ub}\n	@{b}QV        Rm005Doors:Arexx/Account/QView.rexx@{ub}\n	@{b}SECHK     Rm005Doors:Arexx/Account/SeChk.rexx@{ub}\n\n	Snap the following row to your BBS:Commands/SYS.Cmd file:\n\n	@{b}*PWFAIL   Rm005Doors:Arexx/Account/PFail.rexx@{ub}\n	@{b}*ACCOUNTS Rm255Doors:Arexx/Account/F6-Ed.rexx@{ub}\n\n	This will let all users with security level 230 and higher access\n	use the @{"Account Editor" LINK "About Account ED"} if their names are in the allowed user list.\n\n	You should now copy the AccEd.Presets file from the Account/AmiEx2.0\n	directory to your Account/ directory.\n\n	When you have managed to do that it would be time to move the\n	Account ED package to your Doors:Arexx/ path, which is the path\n	all my doors requires so you better not put it elsewhere.\n\n	After doing that you should edit the AccED.Presets file which\n	shall contain your personal presets and comments for all these doors.\n\n	@{b}** Note for QUEST **@{ub}\n\n	If you are going to use Quest for your new users you should then\n	use the MCI commands to envoke Quest and I recommend that you first\n	in your BBS:Node(x)/Joined.txt file adds this line:\n\n	~CC_QUEST\n\n	Which will automatically start quest when a user has given his\n	phone number and so on!\n\n	NOTE! If you already have a MCI command installed you can add as\n	      many you want if you stack them like this:\n\n	      ~CC_QUEST ~CC_WALL ~CC_SENT \n\n	      You only have to leave a blank space at the end!\n\n	@{b}** Note for SECURITY CHECKER **@{ub}\n\n	Like Quest this door should be launched as a MCI command and if\n	you''re gonna use quest I suggest that you put these two in the\n	same bulletin.\n\n	~CC_SECHK ~CC_SECHK \n\n	This will launch both doors! Security checker should be placed\n	in the first bulletin which appear after the user has logged on\n	so this util can check if that user got to high security level\n	and isn''t a sysop and then drop the users access, before viewing\n	any other bulletins, which may be sysop only bulletins!\n@endnode\n\n@node "Install3.00+"\n\n	@{b}File installation@{ub}\n\n	Copy Account/AmiEx3.0/1.info		to BBS:Commands/BBScmd/\n	Copy Account/AmiEx3.0/Quest.info	to BBS:Commands/BBScmd/\n	Copy Account/AmiEx3.0/Qv.info		to BBS:Commands/BBScmd/\n	Copy Account/AmiEx3.0/SeChk.info	to BBS:Commands/BBScmd/\n\n	Copy Account/AmiEx3.0/PwFail.info	to BBS:Commands/SYScmd/\n	Copy Account/AmiEx3.0/Accounts.info	to BBS:Commands/SYScmd/\n\n	@{b}OR:@{ub}\n\n	Change any .info to the appropriate "ICON ToolType Info", example:\n\n	@{b}ACCESS=230\n	LOCATION=DOORS:ARexx/Account/AccED.rexx\n	MULTINODE=YES\n	PRIORITY=0\n	STACK=50000\n	TYPE=AIM@{ub}\n\n	This will let all users with security level 230 and higher access\n	use the @{"Account Editor" LINK "About Account ED"} if their names are in the allowed user list.\n\n	You should now copy the AccEd.Presets file from the Account/AmiEx3.0\n	directory to your Account/ directory.\n\n	When you have managed to do that it would be time to move the\n	Account ED package to your Doors:Arexx/ path, which is the path\n	all my doors requires so you better not put it elsewhere.\n\n	After doing that you should edit the AccED.Presets file which\n	shall contain your personal presets and comments for all these doors.\n\n	@{b}** Note for QUEST **@{ub}\n\n	If you are going to use Quest for your new users you should then\n	use the MCI commands to invoke Quest and I recommend that you first\n	in your BBS:Node(x)/Joined.txt file adds this line:\n\n	~CC_QUEST\n\n	Which will automatically start quest when a user has given his\n	phone number and so on!\n\n	NOTE! If you already have a MCI command installed you can add as\n	      many you want if you stack them like this:\n\n	      ~CC_QUEST ~CC_WALL ~CC_SENT \n\n	      You only have to leave a blank space at the end!\n\n	@{b}** Note for SECURITY CHECKER **@{ub}\n\n	Like Quest this door should be launched as a MCI command and if\n	you''re gonna use quest I suggest that you put these two in the\n	same bulletin.\n\n	~CC_SECHK ~CC_SECHK \n\n	This will launch both doors! Security checker should be placed\n	in the first bulletin which appear after the user has logged on\n	so this util can check if that user got to high security level\n	and isn''t a sysop and then drop the users access, before viewing\n	any other bulletins, which may be sysop only bulletins!\n@endnode\n\n@node "Security Check"\n\n	@{b}Security Checker Access Level@{ub}\n\n	This is only for you who has decided to install Security Checker.\n\n	The level asked here is the access level you have for you and\n	your cosysops and that you don''t wan''t a normal user to have.\n\n	If a user got this security level, then will Security Checker\n	see if that user is in the @{"list of your sysops" LINK "Users Allowed"} which you have\n	specified in the AccEd.Preset file. If not the users security\n	level will be dropped to @{"Set Security Level" LINK "Set Security"}!\n\n	This will protect user who by mistacke has got a too high security\n	level, for example when downloading with DS and when you forget\n	to change back the security level of that user!\n@endnode\n\n@node "Set Security"\n\n	@{b}Set Security Level@{ub}\n\n	This is only for you who has decided to install Security Checker.\n\n	This is the level a user with a @{"too high security level" LINK "Security Check"} will\n	get when he/she logs on and are not listed in the @{"sysop names" LINK "Users Allowed"} \n	list in AccEd.Presets!\n@endnode\n\n@node "Credit Account"\n\n	@{b}Credit Maintenance Access Level@{ub}\n\n	This is for AmiExpress V3.37 and higher, otherwise leave it blank!\n\n	Here you can specify which security level that is required for \n	using the Credit Maintenance Util.\n\n	If you don''t want your cosysops changing your pay users credits\n	I would suggest setting this level at 255!\n@endnode\n\n@node "Reserved"\n\n	@{b}Reserved 1@{ub}\n\n	This field is for future enhanchements made to the package\n	and should be left with just spaces for future compatibility\n@endnode\n\n@node "Auto UL Amount"\n\n	@{b}Automatic Upload Amount@{ub}\n\n	This is a feature which is for Quest only, you can decide how\n	much your new users must upload and this value will be printed\n	in a message right after the user has filled out the questionary.\n@endnode\n\n@node "Edit own Account"\n\n	@{b}Edit your own Account@{ub}\n\n	This option lets you specify if you should be able to edit your\n	own account, while you''re using the Account Editor.\n\n	If this option is on for instance your cosysops could change their\n	own accounts. If it''s OFF no one can edit their own accounts and\n	makes it a bit more tricky for hackers.\n\n	NOTE! This means that you either couldn''t change your account to\n	      prevent hackers who call your board from changing the sysops\n	      account. If you then want to change your account you have\n	      to use the online F6 account editor.\n@endnode\n\n@node "NumberofPresets"\n\n	@{b}Number of Presets@{ub}\n\n        This is the number of presets you have filled out. Do not set this\n        to a higher value than you''ve actually entered. That will result\n        in strange behavior in the @{"Account Editor" LINK "About Account ED"}.\n@endnode\n\n@node "VersionNumber"\n\n	@{b}Preset file Version Number@{ub}\n\n	V2.00 is the version number of the Preset File,\n	that means that it will not work with older versions of Account ED\n@endnode\n\n@node "UserData Path"\n\n	@{b}UserData Path@{ub}\n\n	The path on your harddrive where your userdata is located\n@endnode\n\n@node "UserKeys Path"\n\n	@{b}UserKeys Path@{ub}\n\n	The path on your harddrive where your userkeys is located\n@endnode\n\n@node "Write Note Path"\n\n	@{b}Write Warning Note Path@{ub}\n\n	This is the path to the conference where you want the warning\n	notes made in Account ED to come. This should be a path to any\n	of your conferences\n\n	NOTE! If it''s a path to a directory it has to end with a /\n	      this is so you could specify an assign instead like Conf1:\n\n	A correct path could look like this:\n\n	BBS:Conf-1/\n\n	or\n\n	Conf1:\n@endnode\n\n@node "AccED Password"\n\n	@{b}AccountED System Password@{ub}\n\n	If you want to enter a password to use Account ED you should\n	enter a password here, if this line is empty Account ED won''t\n	ask you for a password\n@endnode\n\n@node "DeleteQuest Pass"\n\n	@{b}Delete Questionary Password@{ub}\n\n	This is the password a user has to enter if he want to delete\n	a users questionary (application)\n@endnode\n\n@node "AccountED Colour\n\n	@{b}AccountED Editor Colour@{ub}\n\n	This is the colour in which all data in the AccED will be\n	displayed in\n@endnode\n\n@node "Log Status AccED"\n\n	@{b}Log Status AccED@{ub}\n\n	Maybe you don''t want to log every action taken in Account ED,\n	then you should change the Log variable. Here is what the\n	different numbers means:\n\n	1, Log only when an account is read\n	2, Log only when an account is saved\n	3, Log both read and save\n	4, Log both read and save, but not then sysop does it!\n	0, Log nothing\n@endnode\n\n@node "Enable Seclevel"\n\n	@{b}Enable Full Account Editing Security Level@{ub}\n\n	This is the security level a user has got to have to change\n	anything in a users account than the name, location and\n	autorejoin conference. A user with lower status than the\n	enable status can however use the nine presets, which is the\n	meaning that the user should use instead. I recommend that you\n	lower your cosysops security level to 230 and keep yours at 255.\n	They can not logon your password because a user can not look at\n	the slot number 1 and they can not give anyone higher security\n	level than they self got, so a cosysop with 230 can not give\n	himself security level 255 and play sysop which is the case with\n	the built in @{"Account Editor" LINK "About Account ED"}!\n@endnode\n\n@node "ChangeAcc Seclev"\n\n	@{b}Change Conference Access Security Level@{ub}\n\n	This is the access level a user has got to have if he want to\n	give or take access from all users for a certain conference.\n	I explained that command in the features so read more about it there!\n@endnode\n\n@node "MsgBaseClean Sec"\n\n	@{b}MessageBase Cleaner Security Level@{ub}\n\n	The access level required to use the built in message base\n	cleaner, to delete old received mail\n@endnode\n\n@node "See Users Pass"\n\n	@{b}See Users Passwords@{ub}\n\n	If you do not have this access level or higher you won''t be able\n	to see different users passwords when using the @{"Account Editor" LINK "About Account ED"}.\n	Have you sometime asked yourself the question, why should my\n	cosysop see other users passwords, then he just should upgrade\n	users accounts!?\n@endnode\n\n@node "Show Users Pass"\n\n	@{b}Show Users Passwords@{ub}\n\n	This option works like this.. If a user has got the requested\n	security level entered at SeePass the user will then be able to\n	see another users password, but if this option is turned Off your\n	user has to push Shift+C to see the password and edit it. If he\n	doesn''t there will only stand Not Displayed. If you have choosed\n	to let your cosysops view the users passwords, buchoosent don''t want\n	them to see them by default you should choose Off, if you always\n	want to see the password you should choose On and the passwords\n	will be displayed if you have SeePass security level.\n@endnode\n\n@node "Print Account"\n\n	@{b}Print Account@{ub}\n\n	If you do not own a printer you should definitely chose Off as\n	a printer option, or if you don''t want anyone to print an account.\n@endnode\n\n@node "Search New Users"\n\n	@{b}Search Start For New Users@{ub}\n\n	This one is made to increase the speed when searching for new users.\n	If you know that you will never get a new user with the slot number\n	under 300, then choose 300 and the @{"Account Editor" LINK "About Account ED"} will start to\n	search for new users beginning at the slot number 300!\n@endnode\n\n@node "Members Conf 2.10+"\n\n	@{b}Members Conference Lock (Secret conf)@{ub}\n\n	As my board is Virtual European HeadQuarter and main board for\n	all our coming productions and so on in our special member area,\n	I found it very annoying with cosysops giving them selves access\n	to that conference just of curiosity. That problem has now been\n	eliminated with this feature letting the sysop specify a\n	conference where no one can give themselves access too. The only\n	way to give a user access to conference is to use the built in\n	/X editor on the F6 key when someone is currently online!\n@endnode\n\n@node "Members Conf 3.00+"\n\n	@{b}Members Conference Lock (Secret conf)@{ub}\n\n	As my board is Virtual European HeadQuarter and main board for\n	all our coming productions and so on in our special member area,\n	I found it very annoying with cosysops giving them selves access\n	to that conference just of curiosity. That problem has now been\n	eliminated with this feature letting the sysop specify an\n	access level (like Member) which no one can give themselves access\n	too. The only way to give a user access to that access level is\n	to use the built in /X editor on the F6 key when someone is\n	currently online!\n@endnode\n\n@node "Questionary"\n\n	@{b}Questionary@{ub}\n\n        Questionary determines which questionary your new users actually\n        have to answer, so you could have multiple old questionaries.\n        Every time you make a new questionary you have to give it a new number\n        and enter the new number here.\n@endnode\n\n@node "Kickout After X"\n\n	@{b}Kick Out After X@{ub}\n\n	Kickout is a very nice functions which nicely drops the modem carrier\n	when a users presses return one or several times, which you actually\n	can change with this function. The higher number you enter the more\n	times your new user can press return.\n\n	NOTE! If you are gonna use this function you have to turn off the\n	@{"Must-Enter-No-Ret" LINK "Must Enter No Return"} function which disables the users ability to\n	press return.\n@endnode\n\n@node "NewUser Letter"\n\n	@{b}Reciever of Newuser Mail@{ub}\n\n        When a user has entered all questions properly he has got to write a\n        letter to a responsible person on your board. That person''s name is\n        what you enter here. If you want all new user mail addressed to\n        yourself you simple enter your name there.\n@endnode\n\n@node "Password Fail"\n\n	@{b}Reciever of Password Failure Mail@{ub}\n\n	If a user fails to enter the password correct after 3 retries\n	the PWFail door will be invoked and the user will be forced\n	to write a letter to the persons described here.\n@endnode\n\n@node "Must Enter No Return"\n\n	@{b}Must Enter No Return@{ub}\n\n	Must Enter Not Return disables the users ability to press return\n	on a specific question in the questionary. This means in practice that\n	user can''t just enter blanks on any answers, then there will pop up\n	a little text which says that the user must reenter the question.\n@endnode\n\n@node "Users Allowed"\n\n	@{b}Users Allowed To Use Account ED@{ub}\n\n	The names must be enter in one row and between the pipes at each\n	end of the row i.e. | Delusion |. The characters entered here must\n	be exactly equal to the users real name. Remember that both capital\n	and small letters are counted as two different characters!\n@endnode\n\n@node "Computer List"\n\n	@{b}Computer List@{ub}\n\n	These computer should be equal to the list which you have in\n	BBS:Node(X)/ComputerList, to match your users choice of computer.\n@endnode\n\n@node "Time Zones"\n\n	@{b}Time Zones@{ub}\n\n	2359 and 0730 are the time zones when no one is allowed to enter\n	the @{"Account Editor" LINK "About Account ED"}. 2359 (23:59:00) is the time from when it''s not\n	permitted to use the Account ED and 0730 (07:30:00) is the time at\n	the day then you may start to use Account ED again! This is a\n	unique functions which I think Account ED was first with..\n@endnode\n\n\n@node "Path NewUserConf"\n\n	@{b}Path to your Newuser Conference@{ub}\n\n	Here you should enter the full path to your newusers conference.\n	You should / at the end of path if it''s to a directory like:\n\n	BBS:Conf-4/\n\n	If it''s to an assign or device you just enter Conf4: or DH1:\n\n	Password Fail and Quest uses this path for their messages.\n\n@endnode\n\n@node "AutoAccess Quest"\n\n	@{b}Automatically Give User Access@{ub}\n\n	If this functions is turn on (YES) then Quest will automatically\n	give every user the access of Preset 1. This means that if a\n	user has entered all the questions quest could automatically\n	do the new user upgrading for you.\n\n	However it is adviceable that you then turn the @{"Kickout After X " LINK "Kickout After X"}\n	function on so a user just can''t enter crap. Also turn of the\n	@{"MustEnter No Ret" LINK "Must Enter No Return"} function.\n@endnode\n\n@node "Comment"\n\n	@{b}Sysop defined comment of Preset@{ub}\n\n        Comment is the description which will be shown to your cosysop\n        when he presses one of the preset buttons (1-9). This won''t affect\n        any of the users status. It''s only a help for you cosysops.\n@endnode\n\n@node "SecL"\n\n	@{b}Security Level@{ub}\n\n        SecL is the security level a user will get if he gets that preset\n@endnode\n\n@node "RaT"\n\n	@{b}Type of Ratio@{ub}\n\n        RaT is the type of ratio a user will get!\n\n        0 = Disabled         (Unlimited downloads)\n        1 = Bytes & Files    (Are counted)\n        2 = Files Only       (Are counted)\n@endnode\n\n@node "RaF"\n\n	@{b}File/Byte ratio@{ub}\n\n        Rat is the upload to download ratio. 2 means that a user gotta\n        upload one file to download two files.\n@endnode\n\n@node "Aut"\n\n	@{b}Autorejoin Conference@{ub}\n\n        Aut is the conference in which the user will autorejoin\n@endnode\n\n@node "ByteLimit"\n\n	@{b}Download Byte Limit@{ub}\n\n        ByteLimit is the maximum bytes a user may download/a day\n@endnode\n\n@node "ConfAccess2.10+"\n\n	@{b}Conference Access@{ub}\n\n        ConfAccess (/X 2.39) is a pair of X:s and which tells to which\n        conferences a user has got access. X means access and _ means\n        not access. You only have nine conferences so you can only have\n        nine X or _:s.\n@endnode\n\n@node "ConfAccess3.00+"\n\n	@{b}Conference Access@{ub}\n\n        ConfAccess (/X 3.00) is a name of a status which you have configured\n        with you Icons. For example it could be NewUser or Elite, any name\n        that is configured in your icons file is OK. This will then give\n        that user access to all conferences described within that access\n        level. For further info consult your @{"AmiExpress" LINK "AmiExpress"} Documentation.\n@endnode\n\n@node "TimeLim"\n\n	@{Daily Time Limit@{ub}\n\n        TimeLim is the number of seconds a user may be online/a day.\n@endnode\n\n@node "ANSI Types"\n\n	In AmiExpress 3.0 and higher there is a possibility to choose\n	a different type of ANSI than the normal Amiga ANSI, therefor\n	this function is implemented.\n\n	In tooltypes in /X 3.0 you can configure what your different\n	kind of ANSI should be called. Enter the same name here as\n	you have there. I have given you only 2 spaces for this\n	because I thought that it will do and therefor I don''t have\n	to redo my config file.. :)\n\n	For AmiExpress 2.0 users just let the default names stand\n	there as in the AmiEx2.0/AccEd.Presets file! All your users\n	has got Amiga ANSI choosen!\n@endnode\n\n@node "Hints To Gain Higher Security"\n\n	@{b}Hints To Gain Higher Security@{ub}\n\n	To gain the full achievement in security improvement of this door\n	you should take the following steps.\n\n	@{b}1.@{ub} Restrict all files related to this package in your Acp.Startup.\n	   Of course not the log files, but all other files.\n	   If you use Maltes''es Remote shell you should restrict them there\n	   on all subjects.\n\n	@{b}2.@{ub} Newer give your cosysop or any other user on the board the same\n	   security level as you. Preferable is 255 for the sysop and 230\n	   for your cosysops. If you then lock some vital functions inside\n	   Account ED for persons with lower security level than 255 they\n	   could newer gain access to them by any means. This means in\n	   practise that no one could give themselves higher access than\n	   they got which is one important feature of Account ED\n\n	@{b}3.@{ub} You should lock one conference or conference name (AmiEx 3.1)\n	   with the supplied option in the Preset File if you perhaps has\n	   got a secret area to which you only want to give access. It\n	   could perhaps be your groups member areas. If you have a cosysop\n	   from another group it wouldn''t be nice if he gave himself access!\n\n	@{b}4.@{ub} If you do not want people editing account then you are asleep\n	   you should enter the Time Zones on which it is allowed to use\n	   the @{"Account Editor" LINK "About Account ED"}. I''ve set them to 2359 to 0730 which means\n	   you could only enter the account editor between 07:31 to 23:58\n\n	@{b}5.@{ub} Isn''t that enough? Well then you could define a password that\n	   must be entered each time you start the Account Editor. You\n	   can find this in the Preset File!\n\n	@{b}6.@{ub} Do you feel insecure about what your sysop does to your\n	   users accounts? Then you should use the feature which logs\n	   every action that is taken. If an account is read or written\n	   who''s account and so on. There are 4 levels of login option\n	   which of course is configurable in the Preset File..\n\n	@{b}7.@{ub} Your cosysops doesn''t need to see other users passwords so why\n	   don''t you just turn off that function for all users with lower\n	   security level than 255. This will cause the Account Editor\n	   to display "Not Displayed" in the account instead of the users\n	   real password. This goes for the questionaries that it showed\n	   with the / key (then you''re editing the users account)\n\n	@{b}8.@{ub} Problem with your friends looking over your shoulder when you\n	   edit your users accounts (yes the passwords are displayed, when\n	   you the master uses it) so what could you do? You could disable\n	   the feature which automatically displays a users password if\n	   you have the view password status so you have to press a key to\n	   toggle the users password. Configure this in the Preset File.\n\n	@{b}9.@{ub} If you just want to disable some of the tools that comes with\n	   the Account Editor you could just set the security level for\n	   those function high. You can give passwords for deleting users\n	   questionaries and so on.\n\n       @{b}10.@{ub} You should put your User.Data and Keys in another path than BBS:\n\n	   Account ED could read it from any path you desire. Just enter\n	   your path in the Preset File. This is to prevent you from lame\n	   programmers BBS viruses. You can change the location in the\n	   @{"AmiExpress" LINK "AmiExpress"} Acp.Startup too.\n\n	   I hope this will help you some and I can only which you luck! :)\n\n@endnode\n\n@node "Greetings"\n\n	@{b}Greetings@{ub}\n\n	@{i}My regards has to go to the following people in no order.@{ui}\n\n	Norad of Unicorn		»» You''re the best man\n	D-Zire of Doodles		»» Thanx for all things m8\n	Empire of Submission		»» Rip my routines !? :)\n	Ice of Doodles			»» Get your board running again, please\n	Kid Curry of Classic		»» The beta tester of AccED for /X 3.0\n	Fox ''N'' Philix of Quartex	»» For being my cool cosysops\n	Pennywise of Quartex		»» When do you call me again !?\n	Jac of Doodles			»» You finaly found a group :)\n	Arvid Tuba of Hardcore Design	»» Hope to see ya at a party (SÄPO !?)\n	AmigaSpirit			»» This man is the coolest party dude!\n	Chucky of Virtual		»» Trouble with the Police lately?\n	It of Justice			»» Thanx for comments and calling me!\n	Ace Caze of Obscene		»» You are the laziest person I know!\n\n	A little request to the @{"/X Development Team" LINK "AmiExpress"}.. Could you possibly\n	make a routine so you could define a door that should be used instead\n	of the built in Name, Password, Phone number routines in the Sys.Cmd?\n\n	Note to all.. I''ve closed my board for a while, while I''m finishing\n	the last year of my studies. My board will probably be up and running\n	for the public this summer. For now it''s only open for my friends!\n        More info will follow. I will NOT stop developing doors so hopefully\n	there will come some new later on!\n@endnode\n\n@node "Final words .."\n\n	@{b}Final words ..@{ub}\n\n	This util has been developed and updated under a very long period.\n	The first version was made for /X 1.1x so you could imagine.\n	During this time period since July 1992 I''ve coded more and more\n	utilities for this package and even integrated several doors like\n	Quest, which was a stand-alone door before. This has given the sysop\n	more and more power with these tools and today it covers a wide\n	range of sysop applications. I''m therefore very proud to give you\n	this package which is the result of many hours of hard work.\n\n	Later in 1994 I will start with the hard work to translate these\n	doors to the C language, to improve the speed some. However\n	because these doors are extremely well coded in ARexx, there won''t\n	be such a big speed improvement. I will start with the smaller doors\n	of this package and finally take the most complex door, Account ED.\n\n	I hope you will get very much use of these utils and that they\n	will give you some more spare time!\n\n	If I get the chance I hope to have a chat with you at a party,\n	maybe at the Party IV !? (In Denmark) !!!\n\n	I would be grateful if you called GANG BANG and came with complaints,\n	ideas or whatever you may come up with, on all my doors!\n\n	This program is @{"Copyright" LINK "Disclaimer, Copyrights"} Delusion of Virtual and may not be sold in\n	any form or made profitable on without the permission of the author.\n\n	May the force be with you,\n\n	Yours, Delusion of Virtual, Friday 8 April 1994\n\n	@{" Thanks to my Beta Testers " LINK "Beta Testers"}\n \n                                                        @{b}A DLS Dezign Prod 94''@{ub}\n@endnode\n\n@node "Beta Testers"\n\n	@{b}Can be reached at my beta testers boards:@{ub}\n\n	Gang Bang	+46(0)554-12133    Chucky of Virtual    DS 21.6k\n			+46(0)554-Private  Chucky of Virtual    DS 16.8k\n\n	Dragons Lair	+46(0)16-147118    Ace Caze of Obscene  DS 16.8k\n\n	Stage Dive	+46(0)16-128047    Nurgle of Obscene	DS 16.8k\n\n	Aces High	+46(0)410-44886    Norad of Unicorn	DS 16.8k\n			+46(0)410-46577    Norad of Unicorn	DS 21.6k\n			+46(0)410-46358    Norad of Unicorn	DS 21.6k\n\n	I want to thank my beta testers Ace Caze, Norad, Chucky, Nurgle and\n	Kid Curry who has done a great job so please call their boards!\n\n	Without their patience and their support & ideas this door wouldn''t\n	have reached you, and if it had you probably would have thrown it\n	away becouse of all bugs!\n\n	Special thanks to Ace Case who spelled checked this entire document\n	and let me use the account editor by myself on his board!\n\n	If you wan''t to become a beta tester, call one of the above boards\n	and write a message to me! :)\n@endnode\n\n@node "Other Delusion Productions"\n\n	@{b}These are some other doors that I''ve made ..@{ub}\n\n	MailServer (DNET) ....... Complete Echo Mail Program better than FIDO\n	MailScan (DNET) ......... Scans for new mail on logons\n	Quest ................... New user questionary door\n	Quest View .............. Lets users view the Quest Questionaries\n	Password Fail ........... Let''s user write a msg at password failure\n	Security Checker ........ Checks if a user got to high security\n	Sysop Uploader .......... More advanced /X built in\n	File Comment ............ Like a faker utility\n	Virtual Vote ............ Very versatile voting door\n	Connect ................. Emulates another /X board on your board\n	Node Activities ......... A fast and tiny who door\n	News mag ................ Let''s you have a magazine online\n	Log Viewer .............. Let''s you view all logfiles from my doors\n	Config Ed ............... Config file editor for remote usage\n	Virtual Chart ........... Complement door to Vote for charts\n	LastCallers Util ........ A stunning lastcallers util with cool design\n	WeekTop Util ............ A WeekTop Chart util, the best available\n	DirXShifter ............. Makes your filelists more interesting\n	DirXCleaner ............. Cleans up your old files both on hd and dir\n	ECC Book ................ Booking door for our ECC Party this summer\n	Members ................. A register program for your group members\n@endnode\n\n@node "Account ED Package Histories"\n\n	History for all programs included in the Account ED Package\n\n	@{" Account ED       History " LINK "Account ED History"}\n	@{" F6 Editor        History " LINK "F6 Editor History"}\n	@{" Quest            History " LINK "Quest History"}\n	@{" Quest View       History " LINK "Quest View History"}\n	@{" Password Fail    History " LINK "Password Fail History"}\n	@{" Security Checker History " LINK "Security Checker History"}\n@endnode\n\n@node "Account ED History"\n\n	@{b}@{u}Account ED © Delusion of Virtual 1992, 1993, 1994@{ub}@{uu}\n\n	@{i}Virtual Account ED, History@{ui}\n\n @{b}08-28-92 V1.00@{ub}\n\n      ° First version & Release version. Everything is new features\n	so I won''t tell you them again, just take a closer look at the doc\n\n @{b}09-04-92 V1.01@{ub}\n\n      ° VERY NASTY BUG found, when you saved an account where you had\n	changed the users name, the user couldn''t log in to the BBS because\n	AmiEx couldn''t find the name! Fixed!! Puuh, sorry guys! I forgot to\n	save the new name in the user.keys file! The new routine also cleans\n	up the user keys file :)\n      ° Bug fixed with the New Users Scan... I changed some things just\n	before I released the first version and a bug slipped thru, but it\n	now even works greater!!\n      ° You can now specify a conf that no one can give access to i.e. a conf\n	for only the members in your group or so!\n      ° It now writes a line in the CallersLog file:\n	Account Editing... SecLevel: 255 (AccED) Where seclevel is the\n	security level of the person who account edited!\n      ° You can view the log file within the program with the command LOG\n      ° Many opening and closing with the user data file was removed to\n	increase speed while accessing the hard drive, therefor Do not\n	read/write the user data with another program when using Account ED!\n      ° Finally: Take a look at the doc file for more info how to set the NEW\n	CONFIG PARAMETERS provided in this new version! All external files\n	are STILL compatible backwards :)\n\n @{b}03-27-93 V1.03@{ub} @{i}Major Update for /X 2.35+@{ui}\n\n      ° The program is now fixed for @{"AmiExpress" LINK "AmiExpress"} 2.30+\n      ° Fixed bug then a board had more than 255 users my util freaked out\n      ° Added in extra security checks so you now must have all users who\n        should have access to account ed in a list\n      ° Added in so the sysop can specify a time period when no one is\n        allowed to use account ed, like between 24.00 and 08.00 for instance\n      ° Added in compatibility with Virtual Quest (Questionary Door Helper)\n        so you now only have to push a button to get the users answers while\n        you are account editing that particular user!\n      ° Added in an extra help page inside the @{"Account Editor" LINK "About Account ED"} for all commands\n      ° Added in the new functions like users baud rate, top cps ul/dl i.e.\n      ° Added in so you can give each preset a description so your cosysop\n        knows which preset to give to different users!\n      ° Code optimized and the preset file is NOT compatible backwards!\n\n @{b}04-05-93 V1.04@{ub} @{i}DeZign@{ui}\n\n      ° The layout of the account editor improved a redesigned\n      ° Due to the sillyness of the /X standard of keys for different\n	functions inside the account editor I have remapped the keyboard\n	functions to be more easy to overview and so on\n      ° Added the computerlist to the preset file for faster program start\n      ° Added in one more option to each preset, Autorejoin conference!\n	this functions is placed in the 5:th row from the left. Please\n	look in the manual for more information.\n      ° Documentation rewritten and freshened up a bit, hope you''ll like it!\n      ° Added in built in calculator which will help you adding bytes or\n	subtracting bytes from a users account. It works on everything\n	that has got with the users upload, downloads to do. These are\n	the mathematic chars it can handle, +, -, * and / .. Try it!\n      ° Finally I''ve managed to retain the information with the last on date\n	so now you can see then a user was last on\n      ° Adding a new feature giving a rating on all users you browse through\n	I''m not really sure yet if this rating is a fair one, haven''t tested\n	it yet on so much users, but as far as I can see I think it''s pretty\n	fair. It gives a user a rating number depending on how much he\n	has uploaded, downloaded, written and called. If a user has a negative\n	number I really think you should talk with that user!\n      ° You can now press TAB when you have searched for a user and want\n	to continue searching. This goes for the New Users commands as well!\n      ° You can now press SPACE to reload a users account if you have\n	changed something wrong in the account!\n      ° Added in so you could choose a security level for seeing users\n	passwords when browsing through the accounts. If you sets this to 255\n	it means that only the sysop will see different users passwords, but\n	the cosysops could see all other information about a users!\n      ° Added in so you have to push a special button for showing a users\n	password so no one beside you will see it by mistake! This function\n	is toogled, so you can set the default, on / off. Press SHIFT+C\n	to toggle a password. You can''t edit a password when not displayed!\n	This idea originally came from Excelsior of Virtual! Thanx m8!\n      ° Password option added to access AccED, wanted by It of Cryptoburners\n\n @{b}05-01-93 V1.05@{ub} @{i}OptimiZe made at the Gathering II in Norway@{ui}\n\n      ° Search for name routine fastened up around 500% I think,\n	it should now be equal to the built in or even faster!\n      ° Built in message writer to inactive users with a little warning\n	note which says that the user shall upload if he don''t want to\n	get deleted. Just press W and the @{"Account Editor" LINK "About Account ED"} will write a msg\n	to the user you are account editing!\n      ° Printer output routine improved and is now faster\n      ° Whole new routine installed, Messagebase cleaner which deletes all\n	your old mail which users have received. Finally there is a util that\n	does that and this one also remembers which the last message you\n	deleted was!\n      ° You can now define in which colour the info in the account editor\n	will be printed with, in the preset file.\n      ° You can now delete a users questionary when you are editing the\n	users account. It has password support so your cosysops don''t\n	mess up anything :) Inside the editor is the command D\n      ° Rebuilt the Presets file again, but this time I''ve included all\n	parameters for both Quest & Account ED which has been inside the\n	source before and made it a lot easier to change in! Please\n	consult the doc file to see how to upgrade your old Preset file\n      ° Help page significantly improved, this time with all commands\n      ° Built in the last command that now makes this door 100% Quest\n	compatible, so from now on all sysop commands in Quest has been\n	removed. Quest will from now on be shipped with Account ED in a new\n	special Account ED Edition.\n      ° A little bug has been reported in version 1.04 of Account ED, then\n	you saved a new users account several times. It has been fixed\n	without my knowledge due to the new Search for User routines\n      ° Give/Take conference access routine partly rewritten\n      ° And as always code optimized, this versions source length is even\n	shorter than the previous one and has got much more powerful commands\n	that''s what I call an update!\n\n @{b}09-01-93 V1.06@{ub} @{i}My dreams come true@{ui} Never released!\n\n      ° Made it 100% /X 3.1 Compatible so it now works on both /X 2.39\n	and /X 3.1. The programs can decide your version and redesign\n	the program functions to work on your version. Many functions\n	remade to suit the new 2.39/3.1 system. You have to change some\n	things in your AccED.Preset file if you have changed to /X 3.1\n	since you last used Account ED. They are well explained in the\n	doc file for this program\n      ° The manual is now rewritten into the AmigaGuide Format which\n	allows you to fast gather the required information. The master\n	behind this stunning conversion is Jens Eriksson\n      ° Redesigned and improved the status window, every action is now\n	displayed and commented\n      ° Remade the UserInfo Tool so it now has got a new style (TBar),\n	has more flexibility and more feature than before. You can now\n	get whatever information you want. (Top uploaders etc)\n      ° Remade the Give Conference Access Tool so it now works faster\n	and has more features\n      ° Optimized the date calculation routine to only 2 lines (8 before)\n      ° Added in the ability to edit user total calls\n      ° Added in the ability to edit user total messages written\n      ° Fixed a new input routine for the @{"Account Editor" LINK "About Account ED"} which is faster\n	and easier to use.\n      ° Implemented the new feature from Quest which lets you load the\n	backup of the users account and save it as the old.\n      ° Account ED always makes a backup when it saves an account, which\n	you later on can load into the old account slot if something goes\n	wrong (the new function above)\n      ° The Last Date On bug fixed, it will now never stand Unknown, sorry\n	should have fixed this bug before!\n      ° The routines to load an account optimized and slightly fastened\n      ° New, Newuser search routine, which should work.. Please let me\n	know if it doesn''t work again.. Phew!\n      ° Bug with the built in Calculator if you just pressed return or\n	entered a wrong value, before it would not give you the old upload\n	credits back, it now does\n      ° Fixed bug with the security level option inside the @{"Account Editor" LINK "About Account ED"}\n      ° Remade the load account routine so it works faster\n      ° Remade the save account routine so it works faster\n      ° Fixed bug in the search for a user routine so it now works 100%\n	and you can search on a user''s last name too\n      ° The program was so optimized so I saved 100 lines of 630 so the\n	program only takes 529 lines now!!!\n\n @{b}04-08-94 V2.00@{ub} @{i}Touch Down!@{ui}\n\n      ° Finally this program has landed, every single bug which occurred on\n	AmiExpress 3.9 and later has been fixed. I got the opportunity to\n	install /X 3.9 and fully test the program!\n      ° Cygnus ED like edit function in the Account Editor implemented,\n	however I could have made it even better if I only could have read\n	if a arrow key has been pressed. I would be very happy if someone\n	who knows how to do it could tell me and the editor will be even\n	better than today.\n      ° The editor now tells how long field you may edit with replacing\n	the background colour with blue!\n      ° Compatibility with the new Quest, questionary format implemented\n      ° Check for users upload/download ratio implemented in the userlist\n	which now gives you every possible way of getting the information\n	you could possible want.\n      ° The users language / ASCII choice is now displayed in the editor\n      ° Last date on routine optimized again..\n      ° Bug in the delete routine for Questionaries was fixed!\n      ° Bug in the search routine, due to a new feature fixed!\n      ° Bug in the access tool fixed, which didn''t affect the last user\n      ° Added in new functions in the editor for Chat Limit and Used Chat Time\n      ° Added in so you could see what status the user has decided for his\n	questionary (when using / in Account ED)\n      ° Fixed a great bug in the text editor inside Account ED which\n	didn''t work when you did pressed a certain key combination\n      ° You now can enjoy all the new pause functions in the Account ED\n	package, they are added everywhere you could find more than one\n	page of text and it uses your default Number of Lines / Screen\n      ° Credit Maintenance Util added, which give almost a second editor\n	to the package. This editor has been added to match the new\n	AmiExpress 3.37 and lets you keep track of your pay users!\n      ° Credit UserList Util added to give you a quick overview of all your\n	credited users and the total amount of money they''ve paid to your\n	board. Works only on /X3.37 and over!\n      ° Amiga guide and distribution files of the package enhanced and\n	all documentation for the other doors in this package stuffed\n	together with the Account ED Docs, this will hopefully make\n	your installation procedure faster!\n\n	Please note that this release is both for V1.06 and V2.00\n	because the new design in V1.06 was never released!\n@endnode\n\n@node "F6 Editor History"\n\n	@{b}@{u}F6 Editor © Delusion of Virtual 1992, 1993, 1994@{ub}@{uu}\n\n	@{i}F6 Account Editor, History@{ui}\n\n @{b}04-07-94 V1.01@{ub} @{i}First released in Account ED Package V2.00@{ui}\n\n      ° First released version. This door is a stripped down version of\n	Account ED, so any updates made their will sooner or later come\n	into this door too! This version is 100% the same as AccED V2.0\n      ° If run when someone is not currently online it will launch the\n	normal ''1'' account editor instead!\n\n	NOTE! Many of the security functions has been removed and password\n	      checks, and such things too. I thought that there wasn''t any\n	      need for the sysop to protect him from himself.. By doing this\n	      I''ve decreased the execution time for the door, now it''s only\n	      180 lines (compared to 700 in Account ED) !!\n@endnode\n\n@node "Security Checker History"\n\n	@{b}@{u}Security Checker © Delusion of Virtual 1994@{ub}@{uu}\n\n	@{i}Security Checker, History@{ui}\n\n @{b}04-08-94 V1.00@{ub}\n\n      ° First released version. Got the idee from The Silencer Door, but\n	thought it would be smart if such a util followed with the\n	Account ED Package, without extra configuration!\n@endnode\n\n@node "Quest History"\n\n	@{b}@{u}Quest, Questionary Helper © Delusion of Virtual 1992, 1993, 1994@{ub}@{uu}\n\n	@{i}Virtual Quest, History@{ui}\n\n @{b}06-07-92 V1.00@{ub}\n\n      ° Were never officially released due to the lack of functions\n\n @{b}06-08-92 V1.02@{ub}\n\n      ° The first released version! The most of the functions I had planned\n	were Implemented but I will add some more in the next version!\n\n @{b}06-09-92 V1.03@{ub}\n\n      ° A User can now read his old application, a separate security status\n	for that was added in the config file, a bug was fixed! When a user\n	had chosen that his answers was NOT correct he was added as a new\n	user for every time he took No.. And it was the same with the log\n	file but it''s fixed now! A bug found then a user was in Quest and\n	of some reason got loss off carrier he would be among the new users\n	but his answer file would not exist and the program would then crash!\n	The program now checks if the file exists before trying to open it!\n\n @{b}06-19-92 V1.06@{ub}\n\n      ° Fixed the bug with the questionary! It now works as it was explained\n	in the manual.. Fixed bug when the program showed an application.\n\n      ° Fixed bug when a user took ? in the sysop menus 2.. It wouldn''t dir\n	all users only about half of them..\n\n      ° Added an extra option in the config file from which the sysop now can\n	terrorize the user if the user don''t answer all the questions.. The prg\n	will whenever a user just presses return and doesn''t write anything\n	write a text that says that the user must enter the questions and then\n	will the program ask the questions again! Very useful against lazy\n	users.. hehe\n\n      ° Added & Fixed so then the user had answered all the questions he/she\n	must either press Y or N to continue, before if you pressed return\n	it only meant the same as a N and some of my users didn''t like that..\n\n      ° Added in a new sysop command! You can now DELETE a users applications\n	i.e. if you think the users hasn''t answered it seriously or something\n	like that! You also must enter a password to do so which you can\n	change in the config file!\n\n @{b}04-07-92 V1.07@{ub}\n\n      ° The users name is now fully displayed even if it consists of spaces\n	this has been a nasty bug all the time but I didn''t know how to fix\n	it until now..\n\n      ° If you list all the applications it will know display it two & two\n	it was a bit hard to read before, it took all day..\n\n      ° File note will now append the whole name but if it consists of spaces\n	it will replace each space with a ''-''..\n\n      ° The routine to read applications who was saved with the answers only\n	was optimized and works much faster!\n\n      ° All menus and texts has been optimized and you will see a large\n	speed improvement in the program!!!\n\n      ° Some minor bugs was fixed but you will probably not notice any\n	difference at all.\n\n      ° Different questionarys at the same time added! I.e. if you have used\n	the function save answers only and you want to change your questionary\n	you will doubtless get into some serious trouble.. You either have to\n	change all your application by yourself (huu) or use this new version\n	of Quest which keeps track on from which questionary the answers came!\n	If you have old applications quest will simple enough take it for\n	granted that they where questioned by questions.1! If you now want\n	a new questionary just create a new one and name it questions.2 and\n	put it in the same dir as questions.1, then you only has got to change\n	the default questionary in the config file to 2! (The variable\n	Questionary in the file Quest.CFG)\n\n @{b}07-10-92 V1.08@{ub}\n\n      ° The delete password is now not displayed on the screen when you\n	write it in, there will only be * displayed instead of each char!\n\n      ° A bunch of bugs fixed & the list all applications routine was\n	optimized again and is now even faster...\n\n      ° Added in so Quest will write a line in the callerslog if anyone\n	deletes the new users log or a users application and of course in\n	colour!\n\n @{b}08-11-92 V1.09@{ub}\n\n      ° You can now search for an application with the users name instead\n	of only the slot number.\n\n      ° The listening routine for all users has been redone and is now\n	much faster. It gets it''s info from the log file nowadays.\n\n      ° All external Dos commands where changed to use internal functions\n	that are built in the Rexxsyslib.library, thus the FileNote command\n	are still loaded from CLI so please have patience with that.\n\n      ° Many bugs where changed and some unnecessary crap was removed from\n	the source! This time it shall WORK!\n\n      ° This version is only an appetizer for version V1.10 with built in\n	account ed! So please hold on..\n\n @{b}05-01-93 V1.10@{ub} @{i}Major Update for /X 2.35+@{ui}\n\n      ° Finally the time for an update has come and it has been worth waiting\n	for. What have happened is that all sysop commands has been built in\n	to Account ED instead for more efficient and faster user updates.\n	Therefor has that code been removed from Quest, and the remaining\n	code has been optimized and sometime rewritten. Here are the new\n	features!\n      ° Added in MCI like commands that will show certain info from the\n	questionary in the users account (using Account ED) in coming versions\n	of Account ED, this feature is only built in Quest today, but soon\n	in Account ED too more info in the Doc file.\n      ° All configuration values now are loaded from Account Ed''s preset file\n	AccEd.Presets\n      ° Built in automatic user upgrader so your user can automatically gain\n	access after answering the questions. They will get the first preset\n	into the AccEd.Presets file if this function is turned on.\n      ° Forces all new users to write a letter to sysop about themselves thru\n	a built in mail program\n      ° Automatically hangs up after the user answered all questions and\n	written the letter to sysop if not AutoAccess is on\n      ° Gives the user a opportunity to operate sysop before it hangs up\n      ° Drops carrier if a user press a defined number of returns\n      ° Prompts that the user must answer all questions if a user press return\n	and ask the question again (it''s configurable)\n      ° Automatically deletes the questionary which may exists on the new\n	users slot number and moves the one deleted questionary to the QuestDel\n	directory and renames it to the users name who answered it so there\n	will never be a problem if you forgets to delete a users questionary\n	you''ve deleted!\n      ° Old users who answers the questions will not be thrown out and\n	doesn''t have to write a letter to sysop. Useful if you want all\n	your old users to answer you questions with quest instead\n      ° Code optimized and almost rewritten\n\n	V1.10 Fix (Released separately)\n\n      ° Bug with the message from new user to sysop fixed, I didn''t find it\n	then I tested the program because it only shows then someone actually\n	is calling as a new user. But now it works great! (You have to change\n	in your AccEd.Preset file, more info on that in preset config text)\n\n @{b}04-08-94 V1.12@{ub} @{i}Made for Account ED Package V2.00@{ui}\n\n      ° With the release of Quest View I needed to do some changes to this\n	door as well. First of all it now reads the questionary in the new\n	standard and it asks if a user wants his questionary private or not\n      ° The *.DAT files has been 20 bytes larger to cover some of the extra\n	bits needed to indicate if a user wants his questionary private or\n	not, it has also 19 free bytes for future enhancements!\n      ° Error in the letter handling fixed to work also on /X 3.0+\n      ° There were a little bug which didn''t save the last line of the users\n	questionary.. It has now been corrected!\n      ° Bug fix in the routine for removing old questionaries, when a new\n	user logs into an old users slot number\n      ° Quest is now able to detect the difference between a deleted\n	account and a new user who logs in, so if you already has answered\n	the questions and runs quest again, you won''t have to answer the\n	questions again. This is useful if you have Quest as a MCI command\n	in a login bulletin which all users sees, this will force all users\n	who hasn''t answered the questionary to do so!\n      ° Quest is now fixed to work with the new Preset file for V2.00\n      ° You now can choose if your questionary should be secret for other\n	users on the board!\n@endnode\n\n@node "Quest View History"\n\n	@{b}@{u}Quest View © Delusion of Virtual 1993, 1994@{ub}@{uu}\n\n	@{i}Quest View, History@{ui}\n\n @{b}04-08-93 V1.00@{ub}\n\n      ° First version made. I got the idea when I called a PC Board, where\n	you could look up other users information and I thought, hey maybe\n	I should use the information stored in the questionaries for this\n	and here the util is. I hope your users will like it!\n\n      ° Added in the feature to also display some info from the user data\n	about the users (Asked by Chucky of Virtual)\n@endnode\n\n@node "Password Fail History"\n\n	@{b}@{u}PW Fail, Password Fail © Delusion of Virtual 1992, 1993, 1994@{ub}@{uu}\n\n	@{i}PW Fail, History@{ui}\n\n @{b}05-08-93 V1.00@{ub}\n\n      ° First version created due to the lack of good PW Fail doors in\n	my /X conference.. There maybe is some that''s better than my\n	out there, but never mind! :)\n\n @{b}11-25-93 V1.01@{ub} @{i}First released in Account ED Package V2.00@{ui}\n\n      ° Some smaller bugs corrected\n      ° Error in the letter handling fixed to work also on /X 3.0+\n@endnode\n','\n',char(10)),'{"ACCESS":"230","LOCATION":"DOORS:ARexx/Account/AccED.rexx","PRIORITY":"0","STACK":"50000","TYPE":"AIM@{ub}"}','auto-added',79376,2,0,NULL,NULL,'vtl_acc2','scan',1780048821);
INSERT INTO door_catalog VALUES('vtl_dirx','VTL-DIRX.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/VTL-DIRX.LHA',NULL,'XIM','DIRXCLEANER.EXE',NULL,'examining','VTL','It will do this by examining the dir<x> file and check if all file''s in it exist.. If not it will write ''DELETED'' as a size comment!',replace('This util will clean up your dir<x> file!\nIt will do this by examining the dir<x> file\nand check if all file''s in it exist.. If not\nit will write ''DELETED'' as a size comment!\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 20:39:16  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',35991,3,0,NULL,NULL,'vtl_dirx','scan',1780048821);
INSERT INTO door_catalog VALUES('vtl_dw10','VTL-DW10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/VTL-DW10.LHA','DirWorx','XIM','DirWorx',NULL,NULL,'VTL','| » /X Doors For Da'' New Generation In C « | +------------------------------------------+ |                                          |',replace('.------------------------------------------.\n| » /X Doors For Da'' New Generation In C « |\n+------------------------------------------+\n|                                          |\n|      Delusion of Virtual Presents:       |\n|                                          |\n|          +:+ DirWorX V1.00 +:+           |\n|                                          |\n| FileList Utility Which Marks Out Deleted |\n| Files (Checks Your HD). Quality assured! |\n|                                          |\n+------------------------------------------+\n| »» Coding in C -> Delusion of Virtual «« |\n`------------------------------------------''\n','\n',char(10)),'DirWorx.Doc',replace('\n                 »» From The Worlds No.1 /X Door Makers ««\n\n         °        °        °   °      °    °       °   °   °    °\n      °    ° __°   __° __° ______ °_  __° __ °__° ______° __ °     °\n   °    °   /~~\° /~~\/~~\/~~ _~~\/~\/~~\/~~\/~~\/~~ _~~\/~~\ 94'' °   °\n      °  ° /   / /   /   /  ¬\/  / _____/  _/\  /  /\/  /  _/ °   °\n     °    /\  /\/   /\  /   \  _/  _/  /   /   /      _/\  /_  ° °   °\n   °   °  \_ ¬ /   /  _/\  //  /  /  °/  _/   /   /\  /  _/  \°    °\n      °    \__  __/___/\__/ \_/\_/ °  \____/\/\__/___/_  ____/ © DLS\n   °  "  " """\/"""""""""" ° """" °  ° """"    """"""""\/"""""" "  "  °\n      °    °    °       °      °      °    °     °       ° °    °  °\n        °    °     °  °     °      °      °   °     °     °   °\n	   V·i·r·t·u·a·l P·r·e·s·e·n·t·s D·i·r·W·o·r·x V·1·.·0·0\n\n                                 Starring\n\n                     Delusion of Virtual as Programmer\n\n  /\  __________________/\/\_________________/\___________ _  _  _   _    _\n /  \/\n	Introduction, Preface\n\n	DirWorx will check your filelists and compare if the files in\n	the list are present on your harddrive. If not it will replace\n	the byte information about the file with DELETED. Simple ehh?\n\n	Are you one of these lazy sysops which thinks it really sucks\n	to go through your filelist and mark all files deleted? Well\n	this door written in C will both do it fast and cool..?\n\n	It will also save a log file which tells who runned the dir\n	command and how much files & bytes which was removed.\n\n	NOTE This door won''t delete any of you files on your HD just\n	     put deleted in front of the files in your filelist IF\n	     they DO NOT EXIST on your harddrive :)\n\n	Ofcourse can you choose which directory and a startdate :)\n\n	NOTE! It is strongly recommended that you set this door to\n	      a low security level so most users are able to run it\n	      this way users could update your filelistnings incase\n	      you''ve forgotten it! (The door is completly harmless\n	      so their is no risc in letting them us it!)\n\n  /\  __________________/\/\_________________/\___________ _  _  _   _    _\n /  \/\n	Thanks!\n\n	My thanks this time has to go to:\n\n	Nurgle and Ace Caze of Obscene for supporting and betatesting\n	this door!\n\n	Stage Dive	 +46(0)16-128047 Nurgle / Obscene\n	Dragons Lair	 +46(0)16-147118 Ace Caze / Obscene\n\n  /\  __________________/\/\_________________/\___________ _  _  _   _    _\n /  \/\n	Instalation ..\n\n	Very easy this time hehe.. Just copy DirWorx + DirWorx.info +\n	this docfile! to any place on your harddrive..\n\n	Copy the BBSCmd/Dir.info to your BBSCmd directory and you\n	are ready to go..\n\n	Wait you say.. where can I configure? Hahaha, there is no\n	configuration! DirWorx reads everything it needs from your\n	AmiExpress Icons..\n\n  /\  __________________/\/\_________________/\___________ _  _  _   _    _\n /  \/\n	History\n\n	06-14-94 V1.00\n\n	First version... (Made for my own needs :)\n\n  /\  __________________/\/\_________________/\___________ _  _  _   _    _\n /  \/\n	Greetings\n\n	My regards has to go to the folowing people in no order.\n\n	Chucky of Virtual		»» Like your board!\n	Kid Curry of Classic		»» Could use your support again!\n	Norad of Unicorn		»» Who has hotter opinions than you :)\n	Fox & Philix of Quartex		»» For being my cool cosysops\n	Rioter of Equinox		»» Busy lately or what? Call me up!\n	It of Justice			»» Thanx for comments and calling me!\n	Cre8or of X-Trade		»» Hope this version fixes your prob.!\n\n  /\  __________________/\/\_________________/\___________ _  _  _   _    _\n /  \/\n	Final words\n\n	News! Right now I''m really busy making utils for you so hold on\n	      for these goodies, programmed in C! Available SOON :)\n\n		MasterStripper V1.00	<- The BEST LHA-Stripper available\n					   nukes over 800 adds from your\n					   archives (99% of the adds)\n		Sysop Comment V2.01	<- The ultimate comment door! :)\n		DataCollector V1.00	<- Grabs all data about your users\n					   it can get and stores it in a file\n		ConfMembers V1.00	<- Shows all users who has got access\n					   to a conf, optionaly asks for a\n					   conference password!\n		ChatTimeFix V1.00	<- Fixes the problem with the users\n					   chat time!\n		Caller Status V1.00	<- Displays extended userinformation\n					   with the DataCollectors Data File\n		LastCallers V2.00	<- Now in C and uses the DataCollectors\n					   data file! Available with 10 different\n					   designs and look! (Completly)\n		Quest V3.00		<- Now in C and icon configed\n		Access Watch V3.00	<- Now in C and with more features\n		Node Activities V3.00	<- The ultimate FrontEND door (& Who)\n		Account Editor V3.00	<- Soon comming, coding right now! :)\n					   replacement for the ARexx version!\n\n		^^^ These doors are almost finished ^^^\n\n	To come:\n\n		PassWordFail V3.00	<- C replacement of Arexx V2.00\n		QuestView V3.00		<- C replacement of Arexx V2.00\n		WeekTop Devotion V2.00	<- Update in C of the LAC Version\n		MonthTop Devotion V1.00	<- New door for the DataCollector\n		TopBoard V1.00		<- Show various info & records\n		Vote V2.00		<- Update of the very old DivVote!\n\n	This program is Copyright Delusion of Virtual and may not be sold in\n	any form or made profitable on without the permission of the author.\n\n	Yours, Delusion of Virtual, Tuesday 14 June 1994\n \n        Can be reached at, INSANiTY +46(0)589-10780!, DualStandard\n\n			^^^ Invited only ^^^\n\n	Post your regular calls at:\n\n	DRAGONS LAiR +46(0)016-147118, DualStandard, Sysop: Ace Caze / OBS\n\n  /\  __________________/\/\_________________/\___________ _  _  _   _    _\n /  \/                                                   A DLS Dezign Prod 94''\n','\n',char(10)),NULL,'auto-added',19530,6,0,NULL,NULL,'vtl_dw10','scan',1780048821);
INSERT INTO door_catalog VALUES('vtl_ms11','VTL-MS11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/VTL-MS11.LHA','MasterStripper','XIM','MasterStripper',NULL,NULL,'VTL','| THE LOGO WAR HAS BEGUN, PROTECT YOURSELF | +------------------------------------------+ |                                          |',replace('.------------------------------------------.\n| THE LOGO WAR HAS BEGUN, PROTECT YOURSELF |\n+------------------------------------------+\n|                                          |\n|  ViRTUAL Presents The Best LHA Stripper  |\n|                                          |\n|      +:+ MASTER STRIPPER V1.01 +:+       |\n|                                          |\n| Removes 99% of all BBS Adds (Strips 900) |\n|  Why settle for less? Quality assured!!  |\n|                                          |\n+------------------------------------------+\n| »» Coding in C -> Delusion of Virtual «« |\n`------------------------------------------''\n','\n',char(10)),'MasterStripper.Doc',replace('\n                 »» From The Worlds No.1 /X Door Makers ««\n\n         °        °        °   °      °    °       °   °   °    °\n      °    ° __°   __° __° ______ °_  __° __ °__° ______° __ °     °\n   °    °   /~~\° /~~\/~~\/~~ _~~\/~\/~~\/~~\/~~\/~~ _~~\/~~\ 94'' °   °\n      °  ° /   / /   /   /  ¬\/  / _____/  _/\  /  /\/  /  _/ °   °\n     °    /\  /\/   /\  /   \  _/  _/  /   /   /      _/\  /_  ° °   °\n   °   °  \_ ¬ /   /  _/\  //  /  /  °/  _/   /   /\  /  _/  \°    °\n      °    \__  __/___/\__/ \_/\_/ °  \____/\/\__/___/_  ____/ © DLS\n   °  "  " """\/"""""""""" ° """" °  ° """"    """"""""\/"""""" "  "  °\n      °    °    °       °      °      °    °     °       ° °    °  °\n        °    °     °  °     °      °      °   °     °     °   °\n     V·i·r·t·u·a·l P·r·e·s·e·n·t·s M·a·s·t·e·r·S·t·r·i·p·p·e·r V·1·.·0·1\n\n                                 Starring\n\n                     Delusion of Virtual as Programmer\n\n  /\  __________________/\/\_________________/\___________ _  _  _   _    _\n /  \/\n	Introduction, Preface\n\n	Well here is another stripper, I thought it was very annoying\n	that you as a user had to see all the files in the LHA archive\n	while it was being tested.. I remember the Magic WorkBench\n	package with 200 files or more which filled several screens\n	with file checking information, I had enough!\n\n	This LHA stripper doesn''t show any file information, more than\n	that the file is OK. It also shows how many bytes was saved\n	due to the banner stripping. It''s very fast and small, fully\n	coded in SAS C 6.5!\n\n	If you feel that it doesn''t strip as fast as your old one\n	it may be the new strip file which follows with this util!\n	The strip file is packed with 800 different adds + several\n	wildcards. Only the wildcards will remove most of your adds\n	so if you want more speed, remove all adds that doens''t have\n	a wilcard in the name (Wildcards = #, #?, *) and you will\n	see the full speed of this util!\n\n  /\  __________________/\/\_________________/\___________ _  _  _   _    _\n /  \/\n\n	Thanks!\n\n	My best regards has to go to the people who believed in this\n	product and tested it. In the beginning there where some\n	problems but together we have solved them :)\n\n	Thanks, Norad and Ace Caze + all your users!\n\n	Call their boards:\n\n	Aces High Node 1 +46(0)410-44886 Norad / Unicorn\n	Aces High Node 2 +46(0)410-46577 Norad / Unicorn\n	Aces High Node 3 +46(0)410-46358 Norad / Unicorn\n\n	Dragons Lair	 +46(0)16-147118 Ace Caze / Obscene\n\n  /\  __________________/\/\_________________/\___________ _  _  _   _    _\n /  \/\n	Instalation ..\n\n	Copy the files in the FCheck directory to your BBS:FCheck dir.\n	Copy the MasterStripper to your BBS:Utils directory, or anywhere if\n	you change the location in the BBS:FCheck icons tooltypes!\n	Copy the S/Lha.strip file to your S:Directory. This is a standard\n	file strip file for LHA and you may use / add your old files\n	to this file for even more banners removed.\n\n	If you by some stupied reason would like to have some adds\n	of yours added to the files you just create a directory with\n	all the files you wanna add and change in the FCheck tooltypes\n	Options=Directory_Path and tell the location of your addy dir and\n	all adds in the specified directory will be added! :)\n\n	NOTE! This util works very well in CLI and in DiskMaster / Opus.\n	      I use it inside DiskMaster in the meny and only have to\n	      mark a file and choose strip and MasterStripper does the\n	      work for me.. (Really nice to get rid of all adds before\n	      unpacking some LHA archive..)\n\n  /\  __________________/\/\_________________/\___________ _  _  _   _    _\n /  \/\n	Extra utilities!\n\n	There are two extra utilities supplied, which are coded in ARexx:\n\n	AddAddy.rexx	  <- For use withing DirOpus/DiskMaster/MTool\n	CompareStrip.rexx <- If you have an previous StripFile you wanna\n			     keep, this tool checks which adds that isn''t\n			     present and adds your new to a file called:\n			     S:Lha.Strip.more (You can when manually add them\n			     to the original S:Lha.Strip) This is so you\n			     won''t add adds that are already wildcarded\n			     in my strip file like: *.nfo *.displayme and\n			     so on..\n\n	How to run them: Just write RX CompareStrip.rexx\n\n	NOTE! Don''t take these tools TOO serious.. hehe\n\n	The AddAddy file is usefull if you unpack an archive which you\n	have stripped and finds out that there was 2 adds that my stripper\n	didn''t nuke.. Mark them and choose AddAddy and my program will\n	save the adds to the S:Lha.Strip.more file! When you can add\n	them to the S:Lha.Strip file and send the Lha.Strip.More to me! :)\n	Preferable to Dragons Lair and I will release a new Strip File\n	as soon as I get about 20 new adds! The LOGO WAR HAS BEGUN! H0H0\n\n  /\  __________________/\/\_________________/\___________ _  _  _   _    _\n /  \/\n	History\n\n	05-14-94 V1.00 (Not Released only for Beta Testing!)\n\n	First version... Made in apx 4 hours!\n\n	06-14-94 V1.01\n\n	REALLY debugged version.. It has now been running on 3 boards\n	for 1 months time and has managed well. Several "bugs" in\n	the strip file has been removed and the program has worked\n	well on over 2000 LHA archives!\n\n  /\  __________________/\/\_________________/\___________ _  _  _   _    _\n /  \/\n	Greetins\n\n	My regards has to go to the folowing people in no order.\n\n	Chucky of Virtual		»» Like your board!\n	Kid Curry of Classic		»» Could use your support again!\n	Norad of Unicorn		»» Who has hotter opinions than you :)\n	Fox & Philix of Quartex		»» For being my cool cosysops\n	Rioter of Equinox		»» Busy lately or what? Call me up!\n	It of Justice			»» Thanx for comments and calling me!\n	Cre8or of X-Trade		»» Hope this version fixes your prob.!\n\n  /\  __________________/\/\_________________/\___________ _  _  _   _    _\n /  \/\n	Final words\n\n	News! Right now I''m really busy making utils for you so hold on\n	      for these goodies, programmed in C! Available SOON :)\n\n		Sysop Comment V2.01	<- The ultimate comment door! :)\n		DirWorx V1.00		<- Checks if your files really are\n					   online, if not deletes them !\n		DataCollector V1.00	<- Grabs all data about your users\n					   it can get and stores it in a file\n		ConfMembers V1.00	<- Shows all users who has got access\n					   to a conf, optionaly asks for a\n					   conference password!\n		ChatTimeFix V1.00	<- Fixes the problem with the users\n					   chat time!\n		Caller Status V1.00	<- Displays extended userinformation\n					   with the DataCollectors Data File\n		LastCallers V2.00	<- Now in C and uses the DataCollectors\n					   data file! Available with 10 different\n					   designs and look! (Completly)\n		Quest V3.00		<- Now in C and icon configed\n		Access Watch V3.00	<- Now in C and with more features\n		Node Activities V3.00	<- The ultimate FrontEND door (& Who)\n		Account Editor V3.00	<- Soon comming, coding right now! :)\n					   replacement for the ARexx version!\n\n		^^^ These doors are almost finished ^^^\n\n	To come:\n\n		PassWordFail V3.00	<- C replacement of Arexx V2.00\n		QuestView V3.00		<- C replacement of Arexx V2.00\n		WeekTop Devotion V2.00	<- Update in C of the LAC Version\n		MonthTop Devotion V1.00	<- New door for the DataCollector\n		TopBoard V1.00		<- Show various info & records\n		Vote V2.00		<- Update of the very old DivVote!\n\n	This program is Copyright Delusion of Virtual and may not be sold in\n	any form or made profitable on without the permission of the author.\n\n	Yours, Delusion of Virtual, Tuesday 14 June 1994\n \n        Can be reached at, INSANiTY +46(0)589-10780!, DualStandard\n\n			^^^ Invited only ^^^\n\n	Post your regular calls at:\n\n	DRAGONS LAiR +46(0)016-147118, DualStandard, Sysop: Ace Caze / OBS\n\n  /\  __________________/\/\_________________/\___________ _  _  _   _    _\n /  \/                                                   A DLS Dezign Prod 94''\n','\n',char(10)),NULL,'auto-added',22742,1,0,NULL,NULL,'vtl_ms11','scan',1780048821);
INSERT INTO door_catalog VALUES('vtl_nw11','VTL-NW11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/VTL-NW11.LHA',NULL,'XIM','NewsWriter',NULL,NULL,'VTL',NULL,NULL,NULL,NULL,NULL,'auto-added',27062,0,0,NULL,NULL,'vtl_nw11','scan',1780048821);
INSERT INTO door_catalog VALUES('vtl_sc21','VTL-SC21.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/VTL-SC21.LHA','SysCm','XIM','SysCm',NULL,NULL,'VTL','| » /X Doors For Da'' New Generation In C « | +------------------------------------------+ |                                          |',replace('.------------------------------------------.\n| » /X Doors For Da'' New Generation In C « |\n+------------------------------------------+\n|                                          |\n|      Delusion of Virtual Presents:       |\n|                                          |\n|       +:+ SYSOP COMMENT V2.01 +:+        |\n|                                          |\n|     Fastest Comment Door Around With     |\n|  Fast Commands Option? Quality assured!  |\n|                                          |\n+------------------------------------------+\n| »» Coding in C -> Delusion of Virtual «« |\n`------------------------------------------''\n','\n',char(10)),'SysCm.Doc',replace('\n                 »» From The Worlds No.1 /X Door Makers ««\n\n         °        °        °   °      °    °       °   °   °    °\n      °    ° __°   __° __° ______ °_  __° __ °__° ______° __ °     °\n   °    °   /~~\° /~~\/~~\/~~ _~~\/~\/~~\/~~\/~~\/~~ _~~\/~~\ 94'' °   °\n      °  ° /   / /   /   /  ¬\/  / _____/  _/\  /  /\/  /  _/ °   °\n     °    /\  /\/   /\  /   \  _/  _/  /   /   /      _/\  /_  ° °   °\n   °   °  \_ ¬ /   /  _/\  //  /  /  °/  _/   /   /\  /  _/  \°    °\n      °    \__  __/___/\__/ \_/\_/ °  \____/\/\__/___/_  ____/ © DLS\n   °  "  " """\/"""""""""" ° """" °  ° """"    """"""""\/"""""" "  "  °\n      °    °    °       °      °      °    °     °       ° °    °  °\n        °    °     °  °     °      °      °   °     °     °   °\n        V·i·r·t·u·a·l P·r·e·s·e·n·t·s S·y·s·C·o·m·m·e·n·t V·2·.·0·1\n\n                                 Starring\n\n                     Delusion of Virtual as Programmer\n\n  /\  __________________/\/\_________________/\___________ _  _  _   _    _\n /  \/\n	Introduction, Preface\n\n	This lame door was actually written because I thought it was\n	so easy to write so why use one from another person on my board!?\n	So I used most of my energy on the design and I hope you like it :)\n\n  /\  __________________/\/\_________________/\___________ _  _  _   _    _\n /  \/\n	What will SysComment do for you?\n\n	It will simple let your users choose who they wan''t to give the\n	comment then they''ve choosed the ''C'' command inside /X!\n\n	New feature in the 2.01 version is that you could give it fast\n	commands like C 1 (for sysop) and C 2 (for cosysop). This idea\n	comes from Fatal / Obscene, thanks :)\n\n  /\  __________________/\/\_________________/\___________ _  _  _   _    _\n /  \/\n	Instalation ..\n\n	Snap the following row to your BBS:Commands/BBS.Cmd file:\n\n	*C        Xm020Doors:SysCm\n\n	For 3.x users.. Duplicate any bbscmd icon, change the path to\n	the door in tooltypes and set it to an XIM Door.\n\n	You could just put this door in any directory you like it\n	doesn''t matter, but you need the SysCm.CFG in the same directory!\n\n	Now it''s time to edit the SysCm.CFG file. Use any editor you like,\n	Cygnus Ed for example. Just change the names and comments to\n	your desired ones, it should be rather easy!\n\n	REMEMBER everything is position dependent, that means that you\n	         can''t use more space than there is in the CFG file that\n		 I sent with this package between the | | characters.\n\n	Copy the AEDoor.library to your libs: directory! (if you don''t\n	already have it! :)\n\n  /\  __________________/\/\_________________/\___________ _  _  _   _    _\n /  \/\n	History\n\n	05-09-93 V1.00\n\n	The first version created and I doubt that there will be further\n	versions :)\n\n	05-29-93 V1.01\n\n	How lucky you are, there came a new version.. I can only say that\n	this one is a bit faster for the user to execute and uses less\n	lines..\n\n	12-14-93 V2.00\n\n	Now the door is coded in C for even faster execution time.\n	Configuration file added.\n\n	06-14-94 V2.01\n\n	The door has now the abillity to accept fast commands like C 3.\n\n  /\  __________________/\/\_________________/\___________ _  _  _   _    _\n /  \/\n	Greetins\n\n	My regards has to go to the folowing people in no order.\n\n	Chucky of Virtual		»» Like your board!\n	Kid Curry of Classic		»» Could use your support again!\n	Norad of Unicorn		»» Who has hotter opinions than you :)\n	Fox & Philix of Quartex		»» For being my cool cosysops\n	Rioter of Equinox		»» Busy lately or what? Call me up!\n	It of Justice			»» Thanx for comments and calling me!\n	Cre8or of X-Trade		»» Hope this version fixes your prob.!\n\n  /\  __________________/\/\_________________/\___________ _  _  _   _    _\n /  \/\n	Final words\n\n	News! Right now I''m really busy making utils for you so hold on\n	      for these goodies, programmed in C! Available SOON :)\n\n		MasterStripper V1.00	<- Strips FUCKING adds 800 or more\n		DirWorx V1.00		<- Checks if your files really are\n					   online, if not deletes them !\n		DataCollector V1.00	<- Grabs all data about your users\n					   it can get and stores it in a file\n		ConfMembers V1.00	<- Shows all users who has got access\n					   to a conf, optionaly asks for a\n					   conference password!\n		ChatTimeFix V1.00	<- Fixes the problem with the users\n					   chat time!\n		Caller Status V1.00	<- Displays extended userinformation\n					   with the DataCollectors Data File\n		LastCallers V2.00	<- Now in C and uses the DataCollectors\n					   data file! Available with 10 different\n					   designs and look! (Completly)\n		Quest V3.00		<- Now in C and icon configed\n		Access Watch V3.00	<- Now in C and with more features\n		Node Activities V3.00	<- The ultimate FrontEND door (& Who)\n		Account Editor V3.00	<- Soon comming, coding right now! :)\n					   replacement for the ARexx version!\n\n		^^^ These doors are almost finished ^^^\n\n	To come:\n\n		PassWordFail V3.00	<- C replacement of Arexx V2.00\n		QuestView V3.00		<- C replacement of Arexx V2.00\n		WeekTop Devotion V2.00	<- Update in C of the LAC Version\n		MonthTop Devotion V1.00	<- New door for the DataCollector\n		TopBoard V1.00		<- Show various info & records\n		Vote V2.00		<- Update of the very old DivVote!\n\n	This program is Copyright Delusion of Virtual and may not be sold in\n	any form or made profitable on without the permission of the author.\n\n	Yours, Delusion of Virtual, Tuesday 14 June 1994\n \n        Can be reached at, INSANiTY +46(0)589-10780!, DualStandard\n\n			^^^ Invited only ^^^\n\n	Post your regular calls at:\n\n	DRAGONS LAiR +46(0)016-147118, DualStandard, Sysop: Ace Caze / OBS\n\n  /\  __________________/\/\_________________/\___________ _  _  _   _    _\n /  \/                                                   A DLS Dezign Prod 94''\n','\n',char(10)),NULL,'auto-added',26587,9,0,NULL,NULL,'vtl_sc21','scan',1780048821);
