INSERT INTO door_catalog VALUES('wbsta23','WBSTA23.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/WBSTA23.LHA',NULL,'XIM','LE-win5-96.exe','2.3','Disable/Enable',NULL,'Expands WBStartup capabilities. Disable/Enable program[s] in your Wbstartup directory! PERFECT utility if you''re running',replace('WBstartup Plus V2.3\n   \n      Expands WBStartup capabilities.\n \nDisable/Enable program[s] in your Wbstartup\ndirectory! PERFECT utility if you''re running\n/X i.e and don''t want it to startup for the\nmoment!\n','\n',char(10)),'wbstartup+.guide',replace('@database WBStartup+.guide\n@$VER: WBStartup+.guide 2.3 (3.10.95)\n@author "John Hughes"\n@(c) "1995"\n@index Index\n\n@node "Main" "WBStartup+"\n\n\n                            @{b}WBStartup+@{ub}\n                         October 3, 1995\n\n\n                         by: John Hughes\n                 [email removed]\n\n    WBStartup+ © 1995 John Hughes.  All Rights Reserved.@{ub}\n\n\n\n  @{" Installing/Updating  " link "INSTALL" 0}   How to install or update WBStartup+.\n  @{" Author & Tech        " link "AUTHOR" 0}   About the author and compiler.\n  @{" PostcardWare         " link "CONTRIBUTIONS" 0}   This is Postcardware.\n  @{" Features             " link "SYNOPSIS" 0}   What WBStartup+ does.\n  @{" L:WBStart-Handler    " link "WBSTARTHANDLER" 0}   L:WBStart-Handler info\n  @{" Bugs                 " link "BUGS" 0}   Bugs in WBStartup+.\n  @{" Where to get Updates " link "AVAILABILITY" 0}   Places to get newer versions\n  @{" History              " link "HISTORY" 0}   Previous versions.\n\n\n  @{b}How to use:@{ub}\n\n  @{" WBStartup+           " link "WBSTARTUP" 0}\n  @{" WBStartup+Prefs      " link "WBSTARTUPPREFS" 0}\n\n  @{" Changing execution order " link "EXECUTEORDER" 0}\n@endnode\n\n@node "INSTALL" "Installation Instructions"\n\n\n  @{b}INSTALLATION:@{ub}\n\n\n  @{fg shine}Double click the "Install" icon to install WBStartup+ for the first time\n  or to upgrade from a previous version.@{fg text}\n\n  The installation script makes 2 directories,\n  "WBStartup (Enabled)" and "WBStartup (Disabled)".\n  "WBStartup (Enabled)" holds all the programs that\n  you want to run at startup, and the other holds\n  all your disabled startup programs (ie, ones\n  that you don''t want to run at startup).\n  Everything in your SYS:WBStartup directory is\n  moved to the "WBStartup (Enabled)" directory.\n  The WBStartup+ program is copied to your\n  SYS:WBStartup directory.\n  The WBStartup+Prefs program is copied to your\n  SYS:Prefs directory.\n@endnode\n\n@node "AUTHOR" "Author & Tech"\n\n                             @{b}About the author\n                            and other tid-bits.@{ub}\n\n\n  Program:        WBStartup+\n  Version:        2.3\n  Date:           October 3, 1995\n  Coded by:       John Hughes\n  Email:          [email removed]\n  WWW:            http://rhf.bradley.edu/~jhughes/\n  Compiled with:  SAS/C 6.55\n  Machine:        A4000 68EC030/25  AmigaDOS 3.1\n  Required:       AmigaDOS 2.0 or above\n                  The preferences program requires AmigaDos 3.0 or above.\n\n\n  @{" Send me a postcard " link "CONTRIBUTIONS" 0}\n\n  Distribution:   WBStartup+ is Postcardware.\n                  As long as all of the archive stays intact and\n                  unmodified, WBStartup+ may be distributed\n                  anywhere.\n\n  I have released:   PointerEyes 4.1 -  Very configurable eyes that watch your\n                                        mouse pointer. Any size, and # of colors.\n                                        aminet:util/wb/PointerEyes4.1.lha\n\n                     WBMakeLink   -  Menu in WB tools menu which makes links\n                                     to files and drawers, and makes an icon\n                                     for them.\n                                     aminet:util/wb/WBMakeLink.lha\n\n  Unreleased:        A raytracer for Amiga Dos 3.x, but is designed to be portable.\n@endnode\n\n@node "CONTRIBUTIONS" "Contributions"\n\n                                @{b}Postcardware@{ub}\n\n\n  WBStartup+ is @{i}Post Cardware@{ui}.\n\n  If you use WBStartup+, please send me a post card of your\n  country or city.\n\n  Of course I will take any type of donations.  :)\n\n  @{i}Send to:@{ui}\n\n    John Hughes\n    901 Highview Rd.\n    East Peoria, IL 61611 USA\n\n\n  @{i}And even if you don''t use WBStartup+, or don''t like it, please\n  send me EMail telling me why.  Thanks.  :)@{ui}\n\n\n  I receive a very large amount of email from all over the world from\n  WBStartup+ users who have requests, bug reports, etc.  But I have\n  received very few postcards compared to email.  If you use WBStartup+,\n  please send me a postcard... It is a very cheap way to show your\n  appreciation for the product.\n\n  Special thanks go out to all the Europeans who have send me postcards.\n  This is because out of all the postcards I have received, I have only\n  one from the USA, which is rediculous considering I live in Illinois, USA!\n@endnode\n\n@node "SYNOPSIS" "Synopsis"\n\n  @{b}WBStartup+ does the following:@{ub}\n\n  o  Easy to use GUI preferences program for OS3.x.\n  o  Lets you choose the order in which the startup programs run.\n  o  Lets you enable and disable the running of each program quickly.\n  o  Allows you to have access to Workbench while all of your\n     startup programs are being loaded.\n  o  Can be disabled at startup by holding left shift key down.\n  o  Progress window shows the icon of the program that is being loaded,\n     and a progress bar with userdefine window background.\n@endnode\n\n@node "WBSTARTHANDLER" "WBStart-Handler Info"\n\n  @{b}WBStartup-Handler@{ub}\n\n    The WBStart-Handler is a handler written by Stefan Becker.\n\n    The full archive can be found on Aminet:util/cli/WBStart1_4.lha\n@endnode\n\n@node "BUGS" "Bugs"\n\n                        @{b}Bugs@{ub}\n\n\n  Thanks go out to all those who reported bugs to me.\n\n\n  I haven''t found any bugs yet, however no program is bug free.\n  Please keep me informed of any bugs that you find.\n  E-Mail:  [email removed]\n@endnode\n\n@node "AVAILABILITY" "Where to get Updates"\n\n\n  @{b}Locations to find Updates@{ub}\n\n\n  All WBStartup updates are first posted to Aminet at:\n\n    ftp://ftp.wustl.edu/~aminet/util/boot/WBStartupPlus.lha\n\n    Versions 1.0 to 2.0 were put in /util/wb, sorry for the change.\n\n  Updates are also available at my web site:\n\n    http://rhf.bradley.edu/~jhughes/\n@endnode\n\n@node "HISTORY" "History"\n\n                                  @{b}History@{ub}\n\n\n\nV1.0  June 26, 1995\n\n  First release.\n  Thanks go to David Swasbrook for showing me an example of how to use GTLV_CallBack.\n\nV1.1  July 16, 1995\n\n  Corrected a "July" to "June" in the docs.\n  I accidentally asked to money in the "About" menu in the prefs program,\n  all I want is a postcard.\n  Added MWB icons for the enabled and disabled directories.\n  Fixed the install script so that no files are deleted, making it much safer.\n  Minor changes in the documentation.\n  Added Title node to Prefs program''s listview.\n  You can now change the loading priority of each startup program within\n    the prefs program.\n  Fixed menus so they are the right colors.\n\nV1.2  July 17, 1995\n\n  Bug Fix:  You could change the priority of title nodes.\n  You can now get the WB info requester for any of the programs in the\n    listview gadget of the Prefs program from a pulldown menu.\n\nV1.3  July 18, 1995\n\n  Now runs programs without icons. Sorry about that :(\n  Bug Fix: Forgot to reply to a message in the Prefs program.\n  Forgot to free up some memory in the Prefs program.\n\nV1.4  July 19, 1995\n\n  Prefs program now lists programs without icons, and no longer displays subdirectories.\n\nV1.5  July 25, 1995\n\n  Bug Fix:  Font was not being shown if it wasn''t already loaded.\n  WBStartup+ Prefs now uses the screen font for it''s text.\n  Added DELAY as a tooltype for WBStartup+.\n  WBStartup+ Prefs is completely font adaptive.\n  Bug Fix:  It was possible to free gadgets more than once it all of them were not created.\n\nV1.6  August 6, 1995\n\n  Selected entries in the listview are now shaded differently.\n  Added where to get l:wbstart-handler in the docs.\n  The list can be alphabetized from "Alphabetize list" in the "Edit" menu.\n  Added "ALPHABETIZE" as a tooltype.  If the tooltypes exists, then the\n    list of programs will be alphabetized.\n  Now recognizes STARTPRI as the priority tooltype to conform more to OS3.x.\n    STARTUPPRI is still recognized, but obsolete, so if both STARTPRI and\n    STARTUPPRI are present, STARTUPPRI is ignored.\n  Changed the priority integer gadget to a slider gadget.\n\nV1.7  August 15, 1995\n\n  WBStartup+Prefs window is now resizeable.\n  WBStartup+Prefs window now opens larger, depending on the visible screen size\n    and the number of lines in the listview gadget.\n  Can switch between Alphabetical sorting and Priority sorting via a menu.\n  If the list is sorted by priority, an edited priority will be moved into the\n    correct location in the list.\n  Fixed a couple font adaptive miscalculations.\n\nV2.0  August 26, 1995\n\n  Programs can now be assigned to groups, making quick changes in the preferences\n    program quicker.\n  Holding the Left Shift key down during boot time, causes WBStartup+ to be disabled.\n  MAJOR BUG FIX:  Programs without icons (projects) were not being recognized.\n  Added several Group management menu items.\n  Added Select All, None, Toggle menu items.\n  WBStartup+ will not run any program with the name of "WBStartup+", that way if\n    you have the WBStartup+ program in the enabled directory, it will not run\n    recursively forever.\n  The alphabetic ordering in WBStartup+Prefs is now case insensitive using Locale.\n  Prefs window opening width is smarter.\n  Changed the look of the WBStartup+Prefs icon to look like the standard MWB prefs icons.\n\nV2.1  September 24, 1995\n\n  Now uses Memory Pooling instead of AllocVec().\n  Fixed potential bug in a list structure when alphabetizing.\n  Received permission to include L:WBStart-Handler in this archive.\n  Archive has moved to Aminet:util/boot\n  Removed accidental FreePool() when "Delete Group" was done, and there were no groups.\n  Enforcer Hit removed: forgot to initialize glist=NULL before CreateContext().\n  Did I release V2.0 WBStartup+Prefs with a missing tail parenthesis in two path tooltypes? Sorry.\n  A requester now appears when you quit without saving, and there was a group modification.\n  WBStartup+ now has an optional Progress Indicator when it runs, which can have a user defined background.\n  Changed the name of drawer icon images, so they don''t have parenthises in them, that way\n    they can be archived with lzx.  They are copyied by the installer script and given their\n    proper default names with parenthises.\n  Included a WBStartup+ version for OS2.x and OS3.x\n  Updated installer script to recognize OS2.x and OS3.x\n\nV2.2  September 27, 1995\n\n  Removed bug causing possible crash when disabling the PROGRESSWINDOW tooltype.\n\nV2.3  October 3, 1995\n\n  The WBStartup+Prefs window is now a WB AppWindow, so ou can drop icons into it\n    and a requester appears asking you if you want to copy or move the files to\n    the enabled or disabled directory.\n  Was allocating pathname size, and deallocating filename size.\n  Possible program crash removed due to another forgotten glist=NULL.\n  Add "..." to some menu items.\n\n@endnode\n\n@node "WBSTARTUP" "How to use WBStartup+"\n\n                      @{b}How to use WBStartup+@{ub}\n\n\n  @{b}@{u}Tooltypes@{ub}@{uu}\n\n       @{" ENABLEDPATH " link "ENABLEDPATH" 0}\n       @{" DISABLEDPATH " link "DISABLEDPATH" 0}\n       @{" DELAY " link "DELAY" 0}\n       @{" PROGRESSWINDOW " link "PROGRESSWINDOW" 0}\n        BACKGROUNDPIC        @{i}(for OS3.x only)@{ui}" link "BACKGROUNDPIC" 0}       (for OS3.x only)\n\n\n  @{b}@{u}Disabling WBStartup+@{ub}@{uu}\n\n    Hold down the Left-Shift key during boot time.\n\n  @{" Changing execution order " link "EXECUTEORDER" 0}\n@endnode\n\n@node "WBSTARTUPPREFS" "How to use WBStartup+Prefs"\n\n                   @{b}How to use WBStartup+Prefs@{ub}\n\n\n  The Prefs program allows you to choose which program to run at startup,\n  and in which order to run them.\n\n  @{b}@{u}Tooltypes@{ub}@{uu}\n\n       @{" ENABLEDPATH " link "ENABLEDPATH" 0}    Must be the same as that of @{" WBStartup+ " link "WBSTARTUP" 0}\n       @{" DISABLEDPATH " link "DISABLEDPATH" 0}   Must be the same as that of @{" WBStartup+ " link "WBSTARTUP" 0}\n       @{" ALPHABETIZE " link "ALPHABETIZE" 0}\n\n\n  @{b}@{u}App Window@{ub}@{uu}\n\n    You can easily copy or move files into the enabled or disabled directory\n    by simply dropping icons into the window from workbench.\n\n    A window will appear asking you if you want to copy or move the files, and\n    whether to put the files in the Enabled or Disabled directory.\n\n  @{b}@{u}The Listview Gadget@{ub}@{uu}\n\n    Each item in the list that has a checkmark will be run at startup.\n    To toggle the checkmark, just click the left mouse button on the checkbox.\n\n    To change the startup priority of a program, click in that area of the\n    listview, set the slider gadget to the desired priority and close the window.\n\n    To bring up the Workbench icon information window for one of the programs\n    listed in the listview gadget, select the program name, and then select\n    "Icon Window" from the "Edit" pulldown menu.\n\n  @{b}@{u}Creating Groups@{ub}@{uu}\n\n    Set the checkmarks in the listview to your desired settings.\n    Choose "Create Group" from the "Edit" menu.\n    Type the name that you want to call the group and press enter.\n    You now have a new group.\n    @{i}You MUST save the settings, or the new group will be forgotten.@{ui}\n    @{i}A requester will be appear to allow you to save any group modifications on quiting.@{ui}\n\n  @{b}@{u}Selecting a Group@{ub}@{uu}\n\n    Choose "Group" from the "Select" menu.\n    Select the name of the group you want to use from the list and select\n      "Ok".  (Double clicking works too)\n\n  @{b}@{u}Other Gadgets@{ub}@{uu}\n\n    Select "Save" to save the settings.\n    Select "Cancel" to exit the program without making any changes.\n\n  Select the "Restore" menu to restore the setting to what they were\n    when WBStartup+Prefs was run.\n@endnode\n\n@node "EXECUTEORDER" "Changing execution order"\n\n    @{b}How to change the order in which the startup programs are run.@{ub}\n\n\n  Use the @{" WBStartup+Prefs " link "WBSTARTUPPREFS" 0} program.\n\n  OR\n\n  You may add the tooltype STARTPRI to any of the startup programs icons.\n\n  The values can be 127 to -128, where 127 has the highest priority and would\n  be run first.\n  Programs without this tooltype are considered to have a priority of -128.\n\n  For instance, I gave MagicCopper :  STARTPRI = 127 since I want that\n  ugly plain looking screen to go away as soon as possible.\n  And I gave ToolManager :  STARTPRI = 120 so it will load second, and I will\n  have access to all my hotkeys quicker.\n@endnode\n\n@node "TOOLTYPES" "Tooltypes"\n\n  @{b}Tooltypes@{ub}\n\n    Choose the program:\n\n      @{" WBStartup+      " link "WBSTARTUP" 0}\n      @{" WBStartup+Prefs " link "WBSTARTUPPREFS" 0}\n@endnode\n\n@node "ENABLEDPATH" "Tooltype:  ENABLEDPATH"\n@{b}ENABLEDPATH=@{ub}\n\n    Set ENABLEDPATH to the directory where the programs are that you want\n    to run at startup (boot time).\n\n    Default:\n\n      ENABLEDPATH=SYS:WBStartup/WBStartup (Enabled)\n@endnode\n\n@node "DISABLEDPATH" "Tooltype:  DISABLEDPATH"\n@{b}DISABLEDPATH=@{ub}\n\n    Set DISABLEDPATH to the directory where programs that should not be\n    run at startup are.  This is like a storage directory.\n\n    Default:\n\n      DISABLEDPATH=SYS:WBStartup/WBStartup (Disabled)\n@endnode\n\n@node "DELAY" "Tooltype:  DELAY"\n@{b}DELAY=@{ub}\n\n    Set DELAY to the number of 1/50ths of a second to wait between\n    executing programs.  So a value of 50 would wait 1 second.  This was\n    requested by someone with a slow hard drive.\n\n    Default:\n\n      DELAY=0\n@endnode\n\n@node "PROGRESSWINDOW" "Tooltype:  PROGRESSWINDOW "\n@{b}PROGRESSWINDOW@{ub}\n\n    This allows you to disable the progress window.\n\n    This tooltype has NO values, it either exists or it doesn''t.\n\n    To disable the progress window, simple place parenthesis\n    around the tooltype name.\n\n    Examples:\n\n      PROGRESSWINDOW        The progress window will be shown\n      (PROGRESSWINDOW)      No progress window will be shown\n\n    Default:\n\n      PROGRESSWINDOW\n@endnode\n\n@node "BACKGROUNDPIC" "Tooltype:  BACKGROUNDPIC"\n@{b}BACKGROUNDPIC=@{ub}\n\n    @{i}For OS3.x only.@{ui}\n\n    This allows you to choose what the progress window''s background\n    picture.  The datatypes.library is used, so you may use any\n    picture format for which you have the corresponding datatype,\n    ie. jpeg, gif, ilbm, tiff, targa, pict, pcx, bmp, etc.  Although\n    since some datatypes are slow, I recommend using ilbm pictures.\n\n    Values:\n\n      NONE               No picture is used.\n      SCREEN             The default Workbench Screen picture is used.\n      WINDOWS            The default Workbench Window/Drawer picture is used.\n      WORKBENCH          The default Workbench Root (non-backdrop) picture is used.\n      @{i}filename@{ui}           Type the pathname and filename of any picture you want.\n\n    Default:\n\n      BACKGROUNDPIC=WINDOWS\n\n    Example:\n\n      BACKGROUNDPIC=sys:pictures/favoritepic.iff\n@endnode\n\n@node "ALPHABETIZE" "Tooltype:  ALPHABETIZE"\n@{b}ALPHABETIZE@{ub}\n\n    If this tooltype exists, the list of programs will be in alphabetical\n    order, otherwise it will be in order by priority.\n\n    Examples:\n\n      ALPHABETIZE        The list will be alphabetized from A to Z.\n      (ALPHABETIZE)      The list will be ordered by priority.\n@endnode\n\n@node "Index" "Index"\nIndex of database WBStartup+.guide\n\nDocuments\n\n@{"Author & Tech" link "AUTHOR" 0}\n@{"Bugs" link "BUGS" 0}\n@{"Changing execution order" link "EXECUTEORDER" 0}\n@{"Contributions" link "CONTRIBUTIONS" 0}\n@{"History" link "HISTORY" 0}\n@{"How to use WBStartup+" link "WBSTARTUP" 0}\n@{"How to use WBStartup+Prefs" link "WBSTARTUPPREFS" 0}\n@{"Installation Instructions" link "INSTALL" 0}\n@{"Synopsis" link "SYNOPSIS" 0}\n@{"Tooltype:  ENABLEDPATH" link "ENABLEDPATH" 0}\n@{"Tooltype:  BACKGROUNDPIC" link "BACKGROUNDPIC" 0}\n@{"Tooltype:  ALPHABETIZE" link "ALPHABETIZE" 0}\n@{"Tooltype:  DELAY" link "DELAY" 0}\n@{"Tooltype:  DISABLEDPATH" link "DISABLEDPATH" 0}\n@{"Tooltype:  PROGRESSWINDOW " link "PROGRESSWINDOW" 0}\n@{"Tooltypes" link "TOOLTYPES" 0}\n@{"WBStart-Handler Info" link "WBSTARTHANDLER" 0}\n@{"WBStartup+" link "Main" 0}\n@{"Where to get Updates" link "AVAILABILITY" 0}\n\nButtons\n\n@{" ALPHABETIZE " link "ALPHABETIZE" 0}\n@{" Author & Tech        " link "AUTHOR" 0}\n@{" Bugs                 " link "BUGS" 0}\n@{" Changing execution order " link "EXECUTEORDER" 0}\n@{" DELAY " link "DELAY" 0}\n@{" DISABLEDPATH " link "DISABLEDPATH" 0}\n@{" ENABLEDPATH " link "ENABLEDPATH" 0}\n@{" Features             " link "SYNOPSIS" 0}\n@{" History              " alink "HISTORY" 0}\n@{" Installing/Updating  " link "INSTALL" 0}\n@{" L:WBStart-Handler    " link "WBSTARTHANDLER" 0}\n@{" PostcardWare         " link "CONTRIBUTIONS" 0}\n@{" PROGRESSWINDOW " link "PROGRESSWINDOW" 0}\n@{" Send me a postcard " link "CONTRIBUTIONS" 0}\n@{" WBStartup+ " link "WBSTARTUP" 0}\n@{" WBStartup+      " link "WBSTARTUP" 0}\n@{" WBStartup+           " link "WBSTARTUP" 0}\n@{" WBStartup+Prefs " link "WBSTARTUPPREFS" 0}\n@{" WBStartup+Prefs      " link "WBSTARTUPPREFS" 0}\n@{" Where to get Updates " link "AVAILABILITY" 0}\n@endnode\n','\n',char(10)),NULL,'auto-added',48119,5,0,NULL,NULL,'wbsta23','scan',1780048830);
INSERT INTO door_catalog VALUES('wclock11','WCLOCK11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/WCLOCK11.LHA','WORLD-CLOCK','XIM','WORLD-CLOCK',NULL,'SieGeL/TRSi',NULL,'/__   \ ¬\ /__ _\ ¬\ /__    ¬\ /_ _ ¬\ \_/. ____/\\/._ ___/\\/. ____/\\_/. _/\ //  /\__\/// /  ./ //____ ./\/ //  /\/',replace('   ___/\___   __/\___   __/\___   __/\_\n  /__   \ ¬\ /__ _\ ¬\ /__    ¬\ /_ _ ¬\\n  \_/. ____/\\/._ ___/\\/. ____/\\_/. _/\\n   //  /\__\/// /  ./ //____ ./\/ //  /\/\n  /___/ /   /__/___/ //______/ / /___/ /\n  \___\/    \__\___\/ \______\/NL\___\/\n     WoRLD-CLoCK V1.1 BY SieGeL/TRSi\nFull configurable & Three different DiGiTS  \n','\n',char(10)),'WoRLD-CLOCK.GUIDE',replace('@database World-Clock V1.1 by SieGeL/TRSi (/X-iNNoVaTioN) BeRLiN-GeRMaNY\n\n@Remark $VER: V1.1 (Friday 04-01-1994)\n\n@node Main "WoRLD-CLoCK V1.1 - /X uTiL WRiTTeN BY SieGeL/TRSi"\n\n                    ._________________  ______\n                    l___       /      \/    _/_______.:  \n                      /       /   /  _/\___      /    :\n                     /_______/-rS!\_____\  _____/     |''94  \n                           /_______|     \/   /_______|\n                               (/X-iNNoVATioN)\n \n                             iS PRouD To PReSeNT: \n\n                               WoRLD-CLoCK V1.1\n \n CoDiNG BY SieGeL/TRSi - GFX BY AMBLIN/DeZiGN, CouNT ZeR0/SCL aND aXe/MST\n--------------------------------------------------------------------------\n                             @{" INTRODUCTION " Link intro}\n                             @{" INSTALLATION " Link installation}\n                             @{"  TOOL-TYPES  " Link tooltypes}\n                             @{"  GREETINGS!  " Link greets}\n@endnode\n\n@node intro "iNTRoDuCTioN"\n\n                              iNTRoDuCTioN\n                              ~~~~~~~~~~~~\nWell after releasing V1.0 it''s seems that nobody use S-Watch anymore. It''s \nnice to see so many boards using my Clock, so I decide to write an update.\nIn this new version you could choose between three different Charsets for \nthe clock and all colors could be changed. Hope you like it...:)\n\nIf you have any suggestions, bugreports, hints & tips for this or other tools\ncoming from @{"TRSi(/X-iNNoVaTioN)" link trsimember}, feel free to contact us and we will change\nit to your needs.\n\n@endnode\n\n@node installation "iNSTaLLaTioN oF WoRLD-CLoCK V1.1"\n\n                       ReQuiReMeNTS & iNSTaLLaTioN\n                       ~~~~~~~~~~~~~~~~~~~~~~~~~~~\nOf course you need any Amigamodel (500-4000T) with Kickstart V37++ and a full\ninstalled and working Amiex (Should work under /X V2.xx, too).\n\nPut WoRLD-CLoCK V1.1 and the icon wherever you want (Make sure that the icon\nis in the same drawer like WoRLD-CLoCK, otherwise the tool won''t work!).\n\nCopy the icon `T.info'' to your BBSCMD/ drawer and change the Location to the\npath where WoRLD-CLoCK V1.1 could be found. That''s all. To configure the Clock\nto your needs take a look to the @{"Tooltypes" link tooltypes}.\n\n@endnode\n\n@node tooltypes "aLL TooLTYPeS uSeD BY WoRLD-CLoCK V1.1"\n\n                                TooLTYPeS\n                                ~~~~~~~~~\n\n LOCATION=<string>       = Here you could enter the Location of your city,\n                           i.e. Berlin-Germany. If you don''t want to enter\n                           a Location, put this Tooltype in Branches. The\n                           Clock writes then as Location the name of your BBS.\n                           \n GMT=<GMT-Time>          = Here you must define your GMT-Time (GMT=Greenwich-\n                           MeanTime). For Germany, it''s +1. If you don''t define\n                           this Tooltype, the WoRLD-CLoCK wouldn''t be shown,\n                           you only see the time from your board.\n\n LINE_ART=<char>         = If you want to seperate the Clock from the cities,\n                           you could enter here *one* char (i.e. -, +, =) and\n                           this char will be used to create two lines between\n                           the clock and the cities. If you don''t want to \n                           seperate it, put this Tooltype in branches or don''t \n                           define a char for it.\n\n CHARSET=<number>        = I''ve included three different styles for the clock.\n                           Here you could choose which one will be used to\n                           show the time. Only 0,1 and 2 are allowed as valid\n                           numbers. The numbers are defined as follow:\n\n                           0 = Digits from Amblin (Default!) \n                           1 = Digits from Axe\n                           2 = Digits from Count Zero\n                     \n                           To check out the digits, take a look to @{"Digits" Link Digits}.\n\nAll following ToolTypes are the defines for the colors. Valid colornumbers are\n30-37, which represents the ANSI-Colors in /X. I recommend not to use 30, as \nthis color is black and you won''t see very much if you enter it...:)\n\n MAIN_COLOR=<color>      = This is the color for the Title and the Lines between\n                           the clock and the cities. Default is 33 (yellow).\n\n CITY_COLOR=<color>      = The color for "TIME SHOWING FROM.." and the cities.\n                           Default is 36 (light blue).\n\n DIGITS_COLOR=<color>    = The color for the digits and the citytimes. Default\n                           is 35 (lila).\n\n DATELINE_COLOR=<color>  = The Color for the Dateline (Sunday, March 27th...).\n                           Default is 34 (dark blue).\n\n\n\n@endnode\n\n@node Digits "SoMe eXaMPLeS FoR THe DiGiTS"\n\n--------------------------- aMBLiN/DeZiGN -----------------------------------\n\n  .######.  .####   .######. .######. ###   .  ######## .######. ########\n  ###  ###  #####   ##   ### ###  ### ###  .#  ###      ###  ###    .####\n  ###  ###   ####        ###      ### ### .##  ###      ###        .####\n  ### .###   ####   .######    #####  ### ###  #######. #######.   #### \n  ### ####   ####   ###          .### ########     .### ### .###   ####\n  ### ####   ####   ### #### ### ####    ####  ### #### ### ####   ####\n  ### ####   ####   ### #### ### ####    ####  ### #### ### ####  .####.\n  `######'' ######## ######## `######''   ###### `######'' `######''  ######\n                                              \n------------------------------ aXe/MYSTiC -----------------------------------\n\n  .######.  .###### #######. #######. ###  ### ######## .####### #######.\n  ######## .####### ######## ######## ###  ### ######## ######## ########\n  ###  ### ###''####    .####      ### ###  ### ###      ###           ###\n  ### ####     ####  .#####''   ###### ######## #######. #######.   ######\n  **** ***     **** .*****''    ****** `******* ******** ********   ******\n  ***  ***     **** ****''         ***      ***      *** ***  ***      *** \n  ***  ***     **** ******** ********      *** ******** ********      ***  \n  `******''     **** `******* *******''      *** *******'' `******''      ***\n\n-------------------------- CouNT ZeRo/SCaNDaL! ------------------------------\n\n.:::::::. :::::.    :::::.    :::::. ::::      ::::::    .:::::    .::::::::\n:::: ....   ....      ....      .... :::: .... ::::      ::::      :::: ....\n:::: ::::   :::: .:::::::·     ::::· ·:::::::: ::::::::. ::::::::.      ::::\n:::: ::::   :::: :::: .... :::: ::::      :::: .... :::: :::: ::::      ::::\n·:::::::·   :::: ·:::::::: ·:::::::·      :::: ·:::::::· ·:::::::·      ::::\n\n@endnode\n\n@node Greets "GReeTiNGS FLY To THe FoLLoWiNG PeoPLe..."\n\naMBLiN/DeZiGN  - THX for the fast work. Personally my favourite digits...:)\n\naXe/MYSTiC     - CeWL digits Dude. But now @{"TRSI" link trsimember} roolez..it''s the best group!\n\nCount Zero/SCL - Jo Man..lame party (Ramses&Paso) but nice digits..Big tHX!\n\nByteAndi/TRSi  - Thx for helping and testing\n\nSpy/TRSi       - Next few days U get yar "BLUBLUB"...hehehe..c ya ..\n\nDr.Dre/TRSi    - Keep on Codin'' man...we beat them all!!! :)\n\naRGoN/MST+2kAD - Fuckin'' TKR...hope to get it back as fast as possible !\n\nand of course all TRSI-Member and our Betatesters....\n\n@endnode\n\n@node TRSIMEMBER "TRSI (/X-iNNoVATioN)"\n\n                   ._________________  ______\n                   l___       /      \/    _/_______.:  \n                     /       /   /  _/\___      /    :\n                    /_______/-rS!\_____\  _____/     |''94  \n                          /_______|     \/   /_______|\n                       (/X-iNNoVATioN) Members are:\n                    ----------------------------------\n                    Dr.Dre!/TRSI^ZenitH (/X-iNNoVATioN)\n                       ByteAndi/TRSI (/X-iNNoVATioN)\n                        SieGeL/TRSI (/X-iNNoVATioN)\n                         Spy/TRSI (/X-iNNoVATioN)\n                    ----------------------------------\n               if you wanna join us so get in touch with : \n                   Dr.Dre!/TRSI^ZenitH or ByteAndi/TRSI\n                          in the following BBS`s \n           Marleys Coffee Shop TRSI ^ ZenitH (/X-iNNoVATioN) GHQ\n                     Diabolo TRSI (/X-iNNoVATioN) GHQ\n\n@endnode\n','\n',char(10)),'{"LOCATION":"<string>"}','auto-added',15689,4,0,NULL,NULL,'trsi_wld','scan',1780048830);
INSERT INTO door_catalog VALUES('weektop','WEEKTOP.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/WEEKTOP.LHA','WEEKTOP','XIM','WEEKTOP','1.00','AirWolf',NULL,NULL,replace('WEEK-TOP  TOOL V1.00 - By AirWolf\n','\n',char(10)),'WEEKTOP.DOC',replace('\n                ------------------------------------------\n                >>> DOCUMENTS FOR WEEK-TOP  TOOL V1.00 <<<\n                ------------------------------------------\n\n                         Released at 20-Jan-1992\n\n\n   Have you ever wanted to know who''s the best uploader in the certain\n   period of time in your BBS? Or how about the worst leacher? At that\n   time when I was thinking about things like those above, in fact I\n   had never seen such an utility which was able to do things I wanted\n   it to do. Why shouldn''t we code a tool which is able to do that...\n   For me one day sounded too short period of time and one month too long, \n   so we didn''t use either of them. But one week would be best period\n   of time to make an utilitity for such a purpose. So, here we''re now,\n   you''re reading doc''s for Week-Top tool which is made for Ami-Express\n   BBS. Hopefully you find this tool as useful as I have found it.\n\n\n   Features:\n   ---------\n\n o Three different screen formats:\n   a) Top Uploaders   [name,location,files,bytes,calls]\n   b) Top Downloaders [name,location,files,bytes,calls]\n   c) Both            [name,files,bytes,calls]\n o Possibility to set number of uploaders/downloaders that are\n   wanted to be shown [1-20].\n o Possibility to set byte-limit (eg. 2000000 bytes) instead of\n   amount of users. Note: only limits greater than 1000 are \n   allowed!\n o Shows exact time when the screen was updated last list\n   [Date-Month-Year,time,number of week (1-53)]\n o Ability to calculate generally stats for current week.\n   [Files ul''ed/dl''ed, Bytes ul''ed dl''ed] \n o Does automatically both .TXT and .TXT.GR files so you don''t\n   need to use ''noansi'' for striping ansi-condes out for .TXT\n   version.\n o Ability to post result of the previous week to all users as\n   an message (Both ALL and EALL are possible). In addition,\n   if wanted, it saves the result of previous week also to\n   a specified file.\n o Week-Top uses user.data file(s) instead of callerslog.\n   Therefore it doesn''t count fake uploads at all! \n o It doesn''t notify user no.1 (SysOp) as an uploader at all.\n o Due to Week-Top has coded with assebler language it''s very \n   fast, unlike those tools that are coded with Basic or C.\n o Week-Top uses as less your valueable memory as possible, it\n   allocated memory exactly what is needed. For example if you\n   have got 100 users Week-Top requires only 34 kb''s of mem.\n   Week-Top doesn''t require larger stack sizes; normal AmigaDOS\n   stack size (2000 bytes) is enough.\n o Week-Top should work perfectly with all Amiga models, because\n   code is very system friendly. No-one is perfect - so if any\n   errors or bugs occur, please inform us and we promise to\n   do our best to fix them. At least Week-Top has worked without any\n   problems on my machine combination (68000 / 7.14MHz + 3megs\n   of RAM)\n\n \n   Some Notes:\n   -----------\n \n   To be sure all options will work properply, your Amiga''s clock\n   must be set to the correct time and Week-Top would be executed\n   after each call on your BBS. The esieast way to do this is  to \n   include Week-Top to your BBS''s logoff script.\n\n   Please Note! Because user.data.old and user.data.pre files are \n   heavily related to user.data you are not allowed to use ANY kind\n   of tool that might cut slices from your original user.data !\n\n	Note!	When you execute WeekTop very first time any result files\n	-----	won''t be created except ''user.data.old'' and ''user.data.pre''\n		because any REAL results aren''t available!\n\n	Note2!	When you''ve defined display mode as BYTES and BOTH mode is	\n	------	active and there''s for example only one (1) person who\n		has reached the required byte size on UPLOADERS side and\n		three (3) persons who have reached the required byte size\n		on DOWNLOADERS side then on UPLOADERS side two blank pos-\n		itions will showed as « NO CHANGE » and the bytes, files\n		and calls amounts will be NULL (0)!\n\n   Config-file:\n   ------------\n\n   You must have file called "WeekTop.Config" on your S: directory,\n   otherwise Week-Top won''t work at all... Okey, Here''s the stuctrure\n   for WeekTop.Config. Description should tell you everything what is\n   needed, but if you still have some problems, take a look at those\n   three example config-files which you may find in the same LHA package\n   as you found this document file.\n\n   Remember that if line is blank Week-Top won''t handle that option!\n   But lines 1,2,3,5 and 6 must be properly set !\n\nLine Function                      Discrition\n-------------------------------------------------------------------------------\n1. | Uploaderd/Downloaders/Both  | Wanted Week-Top mode. \n2. | Amount/Bytes	         | Limit system.\n3. | 5/2000000                   | Data line for above, if Amount was selected\n   |                             | only 5 best will be shown. In case Bytes\n   |                             | 2 megs would be the limit to get\n   |                             | into rankings list (Max 20 best!).\n4. | Totals                      | Totals line will be created.\n5. | BBS:		         | Path for user.data and user.data.old/.pre.\n6. | BBS:Elite/Bulletins/Bull3   | Full path and file name for the destination\n   |                             | file. Note: No .txt & .txt.gr needed, bcoz\n   |                             | Week-Top does ''em itself.\n7. | ALL/EALL                    | Message type, if you want to post the result\n   |                             | of the previous week as an message to all\n   |                             | users on your bbs.\n8. | BBS:Elite/msgbase/          | Full path for message-base where you want to\n   |                             | write your message.\n9. | BBS:Elite/Bulletins/Bull3   | Full path and file name for the result-file\n   |                             | of the privious week.\n-------------------------------------------------------------------------------\n\nExample config :\n----------------\n\nBoth		   ; Both Uploaders and Downloaders should be showed.\nBytes		   ; Byte mode wanted.\n2000000		   ; Only those who have UL''t or DL''t 2000000 bytes get on my list!\nNototals	   ; I don''t wan''t any totals !\nEall		   ; Message type = EALL.\nBBS:    	   ; Path for user.data.\nDH2:AMIGA/BULL10   ; Result file (Note! Both .txt and .txt.gr files will be created!)\nBBS:NODE0/MSGBASE  ; Path for Message Base of this Node.\nDH2:AMIGA/BULLETINS/BULL4 ; Previous week''s results !\n\n   Usage:\n   ------\n\n   In Shell (DOS) you get usage by writing "WeekTop ?"\n   and it looks like this:\n \n   WeekTOP V0.99 coded by Airwolf in 13-01-1992.\n   Idea by zEbRa of SCX.\n   Usage: WeekTOP [U/D/B]\n   Where: U = Uploaders\n          D = Downloaders\n          B = Both\n   And don''t forget file ''S:WEEKTOP.CONFIG''.\n   For updates call ->> The Zoo +358-73-122428 <<-   \n\n   So you''re capable of specifing some options in the command line, but\n   config file is still needed. Note: if you''ve selected different options\n   on the config-file than you selected on the command line mode, Week-Top\n   will prefer using command-line mode. This is useable if you need to view\n   eg. both top uploaders and downloaders instead of top uploaders, therefore\n   there''s no need to change config-file at all. If you specify any of theese\n   three options (U,D,B) in command line, Week-Top''s result file will be put \n   to your current output window (If any available!) and in this mode Week-Top\n   doesn''t change the data of your current destination files. Therefore it''s\n   safe to execute Week-Top from CLI with various option. This "hand" mode is\n   very useful for example in situation where you want to see the top \n   leachers of the week without disturbing your current configuration file.\n   This output file is always ansi colored (.txt.gr) file.\n\n\n   History:\n   --------\n\n   V0.90a   Rather simple simple version of Week-Top.\n            (coded by J.Nevalainen)\n   V0.90b   New grid like ansi screen , also some other improvements.\n            (coded by J.Nevalainen)\n   V1.00    Some bug fixes like: in case user''s name was longer than the space\n            reserved for it, that line on the screen looked weird. \n            (coded by J.Nevalainen)\n   V1.00a   Code size reduced from over 100 kb''s to 9 kb''s little code size\n            reducing done by Airwolf.\n\n   A new generation...\n\n   V0.99    Wholy coded by Airwolf.\n               \n   V1.00    First Public release version...\n            Escpecially thanks to Ranger / SCX for testing this program!\n            Also thanks to all other testers...\n\n   Credits:\n   --------\n\n   All honour for coding ... AirWolf.\n   Ideas and documents ..... Zebra.\n\n   If you have got any ideas to improve Week-Top feel free to call\n   The Zoo (+358-73-122428). Also bug-reports are welcome (please\n   specify your machine combination that would help us a lot)\n\n\n','\n',char(10)),'{"TYPE":"EALL."}','auto-added',9636,4,0,NULL,NULL,'weektop','scan',1780048830);
INSERT INTO door_catalog VALUES('who','WHO.LZH','~/Code/amiexpress_doors/Archives/AmiExpress/WHO.LZH','WHO','XIM','WHO',NULL,'Joe',NULL,'above by Joe Hodge.',replace('Who - A Utility Door for AmiExpress 1.1u or \nabove by Joe Hodge.\n','\n',char(10)),'WHO.DOC',replace('=============================================================================\n      Who - A Utility Door for AmiExpress 1.1u or above by Joe Hodge\n\n  To get your copy of AmiExpress 1.1u or above call Bulldog''s Friends BBS\n                    (318) 793-4141 - HST Dual Standard\n          $50 for first time buyers - $20 for updating from 1.1t\n=============================================================================\n\n\nSetUp:\n\n  1. Assign DOORS: to a directory of your choice, make a directory called\n     Who in the DOORS: directory.\n\n     Example\n\n     Makedir BBS:Confname/Doors         <-- This only needs to be done once!\n     Makedir BBS:Confname/Doors/Who     <-- This only needs to be done once!\n     Assign DOORS: BBS:Confname/Doors   <-- This has to be done ALL THE TIME\n\n     NOTE: You may wish to put the doors: assignment in your startup-sequence\n           or your user-startup or perhaps your BBS startup file.\n\n\n  2. Copy Who to Doors:Who/\n\n\n  3. Create a directory called BBS:Commands ONLY if you wish to make this\n     voting booth a global door (Accessible from any conference and to new\n     users! BE CAREFUL WITH THIS!)\n\n\n  4. Create an ASCII file called CustomCommands in either the BBS:Commands\n     directory (for global use) or in a conference directory (for conf use)\n\n     The CustomCommands file tell the BBS where to find the door and how to\n     invoke it.  THIS IS A FORMATTED ASCII FILE AND THE DOOR TYPE AND PATH\n     MUST BE EXACTLY SHOW (STARTS AT POSITION 11!)\n\n     12345678901234567890 <------ This is for your reference, do not put it\n                          <------ in the customcommands file.\n     WHO       X100DOORS:WHO/Who\n\n     \_/       |\_/\_______/ \__/\n      |        | |     |      |     \n      |        | |     |      Actual porgram to run\n      |        | |     |          \n      |        | |     Path for door program\n      |        | |\n      |        | Security Access Level\n      |        |\n      |        Type of Door (See AmiExpress doc file for more on this)\n      |\n      Command to Enter Door\n\n     *** Sorry for the poor graphic, but I''m not an artist! :-(   ***\n\n     This tells the BBS that you wish to use the key word ''WHO'' to enter\n     the door, which is located in DOORS:WHO, and to run WHO.\n\n\nWhen a user enters WHO from the menu he will get the following results..\n\n    Node # -  User Online               Location of User\n\n\nDocs by Freddy Krueger\nEdited by ByteMaster\n\n<EOF>\n','\n',char(10)),NULL,'auto-added',9883,3,0,NULL,NULL,'terawho','scan',1780048830);
INSERT INTO door_catalog VALUES('whof043','WHOF043.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/WHOF043.LHA','WhoF','XIM','WhoF',NULL,NULL,NULL,NULL,replace('XXXX....\n','\n',char(10)),'WhoF.doc',replace('\n              Whof v0.43 (Door + AmigaDOS Port) for AmiExpress\n              ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n                Author : SPOCK / TRSI ([email removed])\n            Door Requirements : AmigaDOS2.0 & AmiExpress 2.(33?)\n\n\n                                  Purpose\n                                  ~~~~~~~\n  Display  uploaders  & downloaders  of  chosen  file,  but  can  be  easily\nconfigured to show anything you want.  (Anything that somebody has done with\nsome file, which can be found from logs)\n\n                          Preferences : WhoF.prefs\n                          ~~~~~~~~~~~~~~~~~~~~~~~~\nPrefs file should be in the same directory as the prg.\n\nTitle1-6\n~~~~~~~~\nDefines  the  output format.  More information in prefs file.  With commands\n''$INTERNAL''  & ''$EXTERNAL''  User  may choose output format.  Internal format\nshows only uploaders and looks like following...\n\n(Zen.dms  ) (03-26-92) (20:32:54) (Node 1) (SPOCK) (TRISTAR & RED SECTOR)\n\nActions\n~~~~~~~\nDefines  what  actions  done with file will be showed.  You may add these as\nmany as you wish (doesn''t really slow down searching).\n\nMaxNameSize & MaxLocationSize\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\nCrops string for nicer output.  Should be 1-30.\n\nLogType\n~~~~~~~\nDefines log type (Udlog or Callerslog).\n\nNodeMask\n~~~~~~~~\nWhoF loads logs from nodes marked with ''X''s.\n\n                                WhoF History\n                                ~~~~~~~~~~~~\nWhoF v0.31 -> v0.43\n~~~~~~~~~~~~~~~~~~~\n*NEW* : 4-5 times faster search routine.\n*NEW* : Loads logfiles only when it needs them.\n*NEW* : Small change in whof.prefs, ''UseCallersLog'' replaced with ''LogType''.\n*FIX* : Exits if cannot load all logfiles in nodefilter. Earlier WhoF didn''t\n	care how many logfiles it could load, it just searched from logs it\n	could load.\n\nWhof v0.3 -> v0.31\n~~~~~~~~~~~~~~~~~~\n*FIX* : Carrier Lost Bug Fixed\n\nWhof v0.2 -> v0.3\n~~~~~~~~~~~~~~~~~\n*NEW* : ANSI Colors, Defineable LogType, Keywords (DATE) (TIME), $INTERNAL\n*FIX* : Starts to search only if file is online in that conference.\n','\n',char(10)),NULL,'auto-added',19224,3,0,NULL,NULL,'whof043','scan',1780048830);
INSERT INTO door_catalog VALUES('wiz_fcl2','WIZ_FCL2.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/WIZ_FCL2.LHA','LaSTcaLLeRs','XIM','LaSTcaLLeRs','2.0','WIZARD!','WIZ',NULL,replace('LAST CALLERS V2.0 -FASTCALL TOOL- BY WIZARD!\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 20:38:43  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',9358,4,0,NULL,NULL,'wiz_fcl2','scan',1780048830);
INSERT INTO door_catalog VALUES('wiz_last','WIZ_LAST.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/WIZ_LAST.LHA','LASTCALLERS','XIM','LASTCALLERS',NULL,'WIZARD/RLD','WIZ',NULL,replace('LAST CALLERS - FASTCALL TOOL - BY WIZARD/RLD\n','\n',char(10)),'BBS.TXT',replace('                   /\    __/\             ___________         ______/\\n          /\  /\  /  \  /   /\ _____/\   /           \ /\    /    __  \\n         /  \/  \ \   \/   / //   ___ \  \           //  \  /   _/\_\_/\n        /        \ \      / //   /___\/___\  /\ /\  //    \/   /\\/\n       /   \  /   \ \    / / \__________  \\/ / \ \//      \  /_/_/\\n      /    /\/\    \ \   \//\_\________/   \\/   \//\      /     /  \\n      \___/ /\/\___/\ \___/    _____        /     \\ \____/\________/\n       \__\/    \__\/  \__\___/\___/\______/\_____/ \/___/\/_______/\n                           \__\/   \/_____/\/____/\n      _________      ____                   ____       _____     _______\n     /         \    /    \    /\_          /    \     /     \   /   __  \\n    /  \ __ __  \  /      \  /   \        /      \   /  /\  /  /   /_ \_/\\n    \  //  \ /  / /   /)   \/\    \      /    \   \ /  // \/  /   __/\ \\/\n     \//    \ _/ /   ____   \ \   /   /\/     _)   \\  \    /\\   \_\//\\n      /\    /   /    \__/    \ \  \__/  \          /\\  \__/  \\   \_/  \\n      \ \__/   /\____/ /\____/\ \_______/\___/\___/ / \_______/\\_______/\\n       \/_/    \/___/  \/___/  \/______/\/__/  \__\/   \______\/ \______\/\n\n                           -+- CALL the MySt¡c NuMber -+-\n\n    .::::::::.                     500 MB HD Space\n  :::::::::::::..        MaGiCaL NeT / CoM-NeT / Local NEtS\n    :::::::::::::::::  19.2 Zy×eL CoNNect  &  SOON NODE 2-TKR\n     ...::::::::::..                                            .....\n    ::::::::::::::::::        0-2 DaYz oLd StUFF SuPPort       ::::::....\n     .:::::::::::::.          UlTiMaTe aSSeMbleR SuPPort        ::::::::\n                                                               :::::::....\n                   SySteM oPeRaTors - W¡ZaRd - G-L¡Ght - CrUsH  ..:::::::....\n\n                       NødE #0:   +49 (0)421 827436    /  192oO ZyXEL\n                       NødE #1:     Soon available     /  144Oo TkR\n\n\n                                AMIGA & PC WAREZ AVAILABLE\n','\n',char(10)),NULL,'auto-added',4795,3,0,NULL,NULL,'wiz_last','scan',1780048830);
INSERT INTO door_catalog VALUES('wl7a','WL7A.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/WL7A.LHA','wildlist','XIM','wildlist',NULL,NULL,NULL,'/   /_/   /_ \  _/__ __ \ /   / /   /  \      /  / /__ ___    _____ \________/___/_____//___/  //  /uNr/  __/',replace('   ____  ____ _ ____ _____\n  /   /_/   /_ \  _/__ __ \\n /   / /   /  \      /  / /__ ___    _____\n \________/___/_____//___/  //  /uNr/  __/\n   /___  ____/      /      //  /____\  \\n    /    /  /______/______//______/_____\\n   /____/\n  WiLD LiST v0.7a - public beta release\n  /X 3.xx XIM door Kick >2.x required\nOutput yer filelists to an AmigaGuide, IBM,\nAMIGA ASCII file \n','\n',char(10)),'wildlist.guide',replace('@database WiLDist.guide\n\n@node MAIN "WiLDLiST v0.7 DoX (c) 01/94  WiLD THiNG/Mannassas"\n\n                       [---> Mannassas & FeaR <---]                           \n                              presents the\n     ____  ____  ___ __ _______ _____________________   _____________\n    /    /\    \/   \  :       \        /     :      : /    /       /\n   //           \___/  :___     \   ___/ ____ : ____ :/    /___    /____\n   \            /   \      \ /  /    /:       :      :        /   /    /\n    \____/\____/\___/______/___/____/ :_______:______:_______/________/\n                                 SeRieS\n   ====================================================================\n                              WiLD LiST v0.7\n                     (c) 01/94 by WiLD THiNG/Mannassas\n   ====================================================================\n              @{" Introduction        " link "introduction"} @{" Greetings         " link "greets"}\n              @{" Installation        " link "installation"} @{" Contact           " link "contact"}\n              @{" Other WiLDTooLS     " link "tools"} @{" History           " link "history"}\n              @{" Future Improvements " link "future"} @{" Problems & Bugs   " link "probs"}\n@endnode\n\n@node probs\n                        Problems which could occur:\n \nThere aren''t currently no known bugs, but if you should find one @{"contact" link "contact"} \nme pleeze.\n\nIf the AEDoor.library is missing the door will pop up an recoverable alert,\nafter that the node will lock up and you have to reboot your system.\n\nIf there''s not enuff memory and you have lots of it, then your mem could be\ntoo fragmented, so just reboot, you might kick off somebody, but who cares.\nWiLDLiST  itself  doesn''t  need  too  much  memory, but the handling of the\nfilelist may take about three times the size of the filelist and the packer\nwill need some mem too.\n\nIf you are using sum auto disk cruncher/decrucher, there could be sum probs\ncoz WL is using MatchFirst & MatchNext.\n\nAnother thing is your amount of dir files, the limit WL will process is 99,\nif  there''s  somebody who''s got more @{"call me" link "contact"} and you''ll get a version which\nwill be able to process more :-)\n\n@endnode\n\n\n@node introduction\n\nSo  WiLD  LIST  puts  all  dir-files  from all conferences the user has got\naccess TO one file AND packs it AND THEN sends it TO him.  I wonder why all\nthe file list download doors I have seen from other people always did it so\nstupidly and just packed them from one conference and always in hundreds of\ndir files.\n\nYou  can  choose in the options menu which packer you want to use and which\ntext  format  you''d  like, there are Amiga ASCII, IBM ASCII and Amiga Guide\nformat.   In  the  Amiga  guide  format  WiLD  List  will create a Table of\ncontents  according  to  the conferences which have been selected.  Default\ntext format is AmigaGuide and default packer is 1.\n\n                                           [---> WiLD THiNG/Mannassas <---]\n\n\nPS:Isn''t there anybody who wants to write those stupid docs for my doors ??\nOnce heard that only bad coders write good docs, so one day I''ll maybe be a\ngood one, coz my docs are already now cruel :-)\n\n@endnode\n@node future\n                 -======================================-\n                           Future Improvements\n                 -======================================-\n                       Some things still left to do:\n\n· date & time add\n· additional info to each dir\n· add icon to guide file\n· make a new user settings save option\n· hire somebody as doc writer, coz it''s so boring\n\n@endnode\n\n@node history\n                 -======================================-\n                               H I S T O R Y\n                 -======================================-\n\nv0.1  - rel 26-Jan-94   - first ßeta release\n        ca. 07:00\nv0.2  - rel 26-Jan-94   - packs the list now, adds your logo to\n        ca. 23:00         the list\n\nv0.3  - rel 27-Jan-94   - fixed that bug with the wrong conferences\n                          and spent some hours at this stupid doc,\n                          fixed a bug: forgot to free the mem after a\n                          pattern matching :-(\n\nv0.4  - only beta rel.  - added some error handling routines, escpecially\n                          that nice requester if the aedoor.library was\n                          missing,lost carrier handling, memory checking\n                          and file not found messages\n                        - conferences are now sorted by number\n                        - multi conference selection\n                        - conf names and locations are taken from\n                          confconfig tooltypes\n\nv0.5  - only beta rel.  - the old cfg is now the logo that''ll be added\n                        - some bugfixes, that occured due to removing the\n                          old config file\n                        - configuration via tooltypes\n                        - choice of packer\n                        - bbsname option\n                        - textconversion to IBM text (pure assembler)\n\nv0.6  - only beta rel.  - door action is shown(thx to Empire)\n                        - dir number is shown in filelist\n                        - did some hours of code optimization\n                        - changed the concept a bit\n                        - added amigaguide text format\n                        - new option: pack only upload dir(default now)\n                        - improved design a little bit\n                        - added version string\n\nv0.7    -               - again optimized code a bit\n                        - new tooltype: TPATH, let''s you define the path\n                          for the temporary file\n                        - new tooltype: BUFFER - defines buffer size for\n                          copy\n\n@endnode\n\n@node installation\n                 -======================================-\n                               Installation:\n                 -======================================-\n        You will need /X v3.x and Kick > 2.x and the AEDoor.Library\n           So far tested on A2ooo/68o3o, A12oo, A5oo, A5oo/68o3o\n\n            ×X××X××X××X××X××X××X××X××X××X××X××X××X××X××X××X××X×\n            ×X×  This door may NOT be used at any ZK board  ×X×\n            ×X××X××X××X××X××X××X××X××X××X××X××X××X××X××X××X××X×\n\nAll  you  need to install thiz great door is to copy the files to the right\ndirs and edit the wildlist.cfg according to yer needs, it''s da logo that''ll\nbe  added  at  the  top  of  da  filelist,  by  the  way,  it  MUST  be  in\ndoors:wildtools/wildlist/ :-)\n\nConfigure the Tooltypes in Doors:WiLDTooLS/WiLDLiST/WiLDLiST.info to your\nneeds:\n\nNPACKER\nThe number of packers\n\nPNAME.x \nName of packer x\n\nPADD.x\nCommand needed to move file TO the archive\n\nBBSNAME\nThe  name of your BBS, WL uses you bbsname as filename for the filelist, so\nif  your normal BBS-name contains any spaces or slashes or is longer than 8\nchars,  then put here some shortcut for your bbs or whatever name you like,\nif it''s longer than 8 chars the rest will be cut.\n\nTPATH\nThis  is the path for your temp-file, if you gotta lot''s of RAM you can put\nthis  into  t:   or ram:  otherwise choose a path on your HD (floppy drives\nare NOT recommended, but I hope nobody thought of it)\ne.g:\ndh1:\ndh1:t/\nImportant is that it must end with a colon (:) or a slash(/).\n\n\nBUFFER\nThis defines the buffer size in bytes for the copying of the dir files, the\nbigger the faster ofcoz.\n\n\nExample:\n--------\nNPACKER=2               \nPNAME.1=LhA             \nPADD.1=c:lha m          \nPNAME.2=ZiP\nPADD.2=c:ZIP -m\nBBSNAME=Dixie\nTPATH=t:\nBUFFER=100000\n\nPacker one is default.\n\n@endnode\n\n                                           \n@node greets\n                 -======================================-\n                           Special thanx for ...\n                 -======================================-\n\nEmpire/Mystic   : well you see, finally got away from that arexx stuff, and\n                  removed the old config and you can select the confs you\n                  want\nByteAndi/MST    : for da kewl stuff, ich hab ne liste mit einigen vielen\n                  bugs und Vorschlaegenn fuer Dich :-)\nGollum          : Thx for da reeeeeaall fast text converison proc\nZiPPER/Yodel    : THX for all\nZielu/Mad Elks  : thx for yer loooooooooong bug reports\nuNReaL/FeaR     : ...all the KeWL ASCII''s\nEasy Rider/MST  : ...beta-testing & fast ''distribution''\n                  and yer beta-testing\nWouter van Oortmerssen : ... Amiga E compiler, it''s the BEST\nSiNTAX/WøT      : ...your examples in E and your AEDoor.library\nBig C & Amiga   : ... the best toy for bored programmers ;-)\n\n                  \n\n\n                 -======================================-\n                       Greetings go to(in no order)\n                 -======================================-\n\n                      all Ex-Mannassas & FeaR members\nTic.,   R19,  Dragon/Motion,  Vince,  Andy/Motion,  Sunset,  Donald/Motion,\nVince,The  Generat, Wild Child/Taurus,EaZy-E/Taurus(ruf mal an, hab was mit\nDir zu schwätze), CatEye/Taurus, Artie/Taurus and all others who want to be\ngreeted...\n\nLogic           : hey yer checkers  are da best \nRage against ZK : Go on like this\n\n                 -======================================-\n                              Fuckings go to\n                 -======================================-\nPolish telecom (TPSA): fucked up assholes\nall you stupid lamers here that even can''t do a simple file description\nZonder Lamando       : fuck yerself ye bloody nazis\n\n\n@endnode\n\n@node contact\n                *** For any improvement or bug reports ***\n             *** write to WiLD THiNG at one of these boards ***\n\n\nCRaZY WoRLD  SySoP: JaRRi                    ++48-2-6636797\nDiXiE        SySoP: WiLD THiNG               ++48-71-575825\nLiFe         SySoP: RaBoCoST                 ++48-22-118628\nMamba        SySoP: Easy Rider               ++48-22-367443\n\n@endnode\n\n@node tools\n                          LooK ouT FoR THe oTHeR \n      ____  ____  ___ __ _______ _____________________   _____________\n     /    /\    \/   \  :       \        /     :      : /    /       /\n    //           \___/  :___     \   ___/ ____ : ____ :/    /___    /____\n    \            /   \      \ /  /    /:       :      :        /   /    /\n     \____/\____/\___/______/___/____/ :_______:______:_______/________/\n\n\n[----- NAME ------|------ DESCRIPTION -------|------- FEATURES ---------------]\n WiLDRead v0.13   | file/archive/log viewer  | text search\n                  | AIM door                 | file/arc info\n                  |                          | next/prev. page\n                  |                          | page selection\n[-----------------|--------------------------|--------------------------------]\n WiLDNeW v0.4     | new user questionaire    | multilanguage\n                  | AIM door                 | baud checking for questions\n                  |                          | multiple answers\n                  |                          | text comments (internal ed)\n                  |                          | sysop review of new users\n[-----------------|--------------------------|--------------------------------]\n WiLDBull v0.2    | global bulletins         | scroll bar selection\n                  | AIM door                 | all bulls in one dir\n[-----------------|--------------------------|--------------------------------]\n WiLDMenu v0.1    | multi level menus        | all menus in one file\n                  | AIM door                 |\n[-----------------|--------------------------|--------------------------------]\n WiLDKick v0.1    | unwanted users kick out  | show  msg to user & hang up\n                  | AIM door                 |\n[-----------------|--------------------------|--------------------------------]\n WiLDVote v0.9    | vote door                | configurable user add/delete\n                  | AIM door                 | of topics and itemz\n                  |                          | download of result file\n                  |                          | result output with graph bars\n[-----------------|--------------------------|--------------------------------]\n WiLDLiST v0.7    | file LIST dl             | download all filelists from\n                  | XIM door                 | conferences the user has \n                  |                          |  access TO in one file\n[-----------------|--------------------------|--------------------------------]\n\n@endnode\n','\n',char(10)),NULL,'auto-added',20131,5,0,NULL,NULL,'man_wl03','scan',1780048830);
INSERT INTO door_catalog VALUES('wlast000','WLAST000.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/WLAST000.LHA','wlast4','XIM','wlast4','0.4',NULL,NULL,NULL,replace('WiLD Last v0.4 beta  - severe bugs fixed\n','\n',char(10)),'reference-board.txt',replace(replace('              W h e r e   t h e   w a r e z   c o m e   f r o m\r\n                                               __                /\_____:\r\n__/\__________________________________________|  \______________/  \    |__\r\n\_   ___________  _______ ________  \__   ___ |   _______  _______  \_  l  \\r\n__\____  \    _l   \    |  \     |___/     |  !    \   _l   \   _| __/\____ \_\r\n\_____    \___\     \___|   \___ !   \__   |_____   \__\     \__\    \____   /\r\n -mNT\_____/---\_____/--l____/-\______/\   |----\____/--\_____/--\____/--\__/\r\n                                        \__|\r\n\r\n- -- --> F A i R L i G H T   S W E D i S H   H E A D Q U A R T E R S <-- -- -\r\n\r\n           reference-board is back 2017 after more than 20 years in coma!\r\n\r\n                        Running on AmiExpress TelNet\r\n\r\n                    Connect to: reference-board.zapto.org:1541\r\n\r\n                    or: www.brysk.se/reference-board/index.htm\r\n               \n              UPLOAD DATE: 01-04-18  TIME: 20:38:42  ON NODE: 0\n','\r',char(13)),'\n',char(10)),NULL,'auto-added',7333,2,0,NULL,NULL,'wlast000','scan',1780048830);
INSERT INTO door_catalog VALUES('wnuke06','WNUKE06.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/WNUKE06.LHA','wnuke','XIM','wnuke',NULL,NULL,NULL,'/   /_/   /_ \  _/__ __ \ WiLD THiNG''s /   / /   /  \      /  / /__ ___    _____ \________/___/_____//___/  //  /uNr/  __/',replace('   ____  ____ _ ____ _____\n  /   /_/   /_ \  _/__ __ \ WiLD THiNG''s\n /   / /   /  \      /  / /__ ___    _____\n \________/___/_____//___/  //  /uNr/  __/\n   /___  ____/      /      //  /____\  \\n    /    /  /______/______//______/_____\\n   /____/\n\n          WiLD Nuke v0.6 BETA\n         A Nuker for LogicBBS\n','\n',char(10)),'wnuke.doc',replace('\n   ____  ____ _ ____ _____\n  /   /_/   /_ \  _/__ __ \ WiLD THiNG''s	WiLDNuKe v0.6\n /   / /   /  \      /  / /__ ___    _____\n \________/___/_____//___/  //  /uNr/  __/	a LoGIC BBS Door\n   /___  ____/      /      //  /____\  \\n    /    /  /______/______//______/_____\\n   /____/\n\n      - -- --- ---- -----=[ D I S C L A I M E R ]----- ---- --- -- -\n\nWiLDNuke is copyrighted by WiLD THiNG^yODEl.  You may copy it around as You\nlike,  as  long as no files are removed from the archive.  BUT You may only\nuse it if You are a registered user of LogicBBS.  LogicBBS is (c) by Parcon\nSoftware  and  is NO FREEWARE, if You don''t have registered yet, go out and\ndo it.\n\n\n    - -- --- ---- -----=[ I N T R O D U C T I O N ]=----- ---- --- -- -\n\nWelcome  to  WiLDNuke,  it''s  a  nuker  for  LogicBBS.   The program is not\nfinished, yet.  Have a look at FUTURE below.\n\nAs it''s not yet finished you be careful with a few things: \n- Files will only be processed correctly, if the filenames are UPPERCASE.\n- Strange things will happen if there is no description, SKIP THE FILE\n- DO  NOT  NUKE ONLINE USERS, wait till they have logged off, otherwise they\n  won''t receive the credits\n\nHave a look at FUTURE, there are some more things to be fixed.\n\n    - -- --- ---- -----=[ R E Q U I R E M E N T S ]----- ---- --- -- -\n- Any Amiga\n- wildtools.library v1.0 (included)\n- LogicBBS of course\n- Kickstart v2.x\n- some mem, at least 50k + the size of the filelist\n\n\n\n    - -- --- ---- -----=[ I N S T A L L A T I O N ]----- ---- --- -- -\n\nInstall WNuke as normal XiM Door, U know how, if not READ THE DOCS.\n\nCreate a directory doors:WiLDTools/WiLDNUke\n\ncopy  the  files  GIVEN.TXT and TAKEN.TXT there, and edit them if You don''t\nlike the design. See below for description.\n\n           - -- --- ---- -----=[ U S A G E ]----- ---- --- -- -\n\nWiLDNuke  can  be  started  from command line with the filenames as options\ndivided by spaces or from AquaScan.\n\ne.g.: NUKE YDL-WW06.LHA YDL-WN13.LHA\n\nAfter  starting  You  will be prompted to enter more files, push enter when\nYou are finished.\n\n .--------------------------------------------------------------------------.\n : File   : YDL-WW08.TXT   Size :   23254   Uploader : WiLD THiNG           :\n :                                          Uploads  :    587/     22547822 :\n :                                          Downloads:      1/         1234 :\n :                                          Ratiotype: 1        Ratio :   3 :\n >--------------------------------------------------------------------------<\n : [S] Size Comment : DELETED   [D] Delete : Yes   [R] Credits :    5       :\n : [C]      Comment : What the fuck is this ????                            :\n : [N]  Next File               [K]  Skip File     [Q] Quit                 :\n : [V] View description         [A]  Do All Files                           :\n `--------------------------------------------------------------------------''\n\nIn  the  upper  part  the  data  for  the  current  file  is  displayed and\ninformation about the uploader (if found of course).\n\nThe keys:\n\n [S]	- enter the comment which will replace the SIZE of the file\n [D]	- Delete file Yes/No\n [R]	- Give/take how many times credits, eg 5 will give 5* creds, -5 will\n		  take 5* creds\n [C]	- Comment to place below the filedescription\n [N]	- Process file with the entered options and go to next\n [K]	- Don''t change file and go to next\n [Q]	- Quit WiLDNuke without doing any changes\n [V]	- Show description of file\n [A]	- Process all files with the options entered, BE CAREFULL with this,\n		  it won''t stop until all files have been processed\n\nThe files GIVEN.TXT and TAKEN.TXT:\n\nThese files MUST be located in doors:wildtools/wildnuke/\n\nThese  are  the message texts for files that have been nuked, GIVEN.TXT for\nfiles where bytes have been given and TAKEN vice versa.\n\nThe following keywords will be replaced with the correct values:\n\n%uploader 		name of the uploader\n%nuker			name of the user who nuked the file\n%bytesbefore 	number of bytes before the nuking\n%filename		name of the file that has been nuked\n%credits		credits\n%size			size of the nuked file\n%nuked			amount of bytes that have been given/taken\n%bytes			bytes after the nuking\n%comment		the comment that was entered for the file\n\nall  byte  numbers are formatted with "," for better readability (eg 2,256)\nand with a FIXED length of 10.\n\nMessages  are  written  to  the  CURRENT conference, all of them are System\nMessages  (cannot  be replied), AutoDelete, Private and NotifySender.  Thou\nthe last one hasn''t been implemented yet.\n\n         - -- --- ---- -----=[ H I S T O R Y ]----- ---- --- -- -\n\n 0.2	28-04-95		- creates dummy files instead of deleting\n\n 0.3	17-09-95		- description finding implemented\n					- fixed: WNUKE would exit if upload wasn''t found\n\n 0.4	17-09-95		- now writes descriptions\n		18-09-95		- improvements arg parsing, filechecking\n\n 0.5	18-09-95		- nicer output, minor bug fixes\n					- creds given or taken is added to the filelist\n					- makes use of wildtools.library v1.0\n					- checks if file hasn''t already been nuked, this has\n					  to be improved, thou (checks only size)\n\n 0.6	18-09-95		- filelists are now written correctly\n					- writing of file-lists is much faster\n					- Do all files option added\n					- writes messages to users about given/taken creds\n\n\n\n          - -- --- ---- -----=[ F U T U R E ]----- ---- --- -- -\n\nSome things are still left to do:\n\n- adding of the uploader to the file''s comment for faster finding\n- a faker for "mortal" users\n- a configuration\n- multiple-line comments\n- improvements in the searching (case insensitive, UPPERCASE filenames NOW)\n- a full screen diz-ed will round up the whole thing\n\n - -- --- ---- -----=[ A C K N O L E D G E M E N T S ]----- ---- --- -- -\n\nByteAndi/TRSi:	I can''t deny that I have taken a few ideas from his ByteKiller\nMichael Pendec:	Without Logic this wouldn''t have been possible ;)\n\n     - -- --- ---- -----=[ B E T A  T E S T I N G ]----- ---- --- -- -\n\n                        WiLDNuke has been tested by\n\n  SYSOPNAME		BOARD	COMP. PROC.	RAM	  KICK VER	LOGIC VER\n-----------------------------------------------------------------------------\n WiLD THiNG		Dixie	a2ooo 68030	7MB  	 Kick 3.0 	LogicBBS b14\n SPOONMAN		Russia	a12oo 68020		  Kick 3.0 	LogicBBS b14\n\nIf  WiLD  NUke  runs  on  Your system without problems drop me a note which\nsystem You are using (see CONTACT).\n\n       - -- --- ---- -----=[ T E C H N I C A L ]----- ---- --- -- -\n\nWiLDNUke  and  the  wildtools.library have been written using AmigaE v3.2a.\nIt makes use of the Amiga E Modules for LogicBBS created by ME.\n\nThe source for WN is 12k big in ca 370 lines.\n\nDIR-FILES : only the changed part is being written (Seek())\n\nwildtools.library  :  has been written by ME, it contains the routines used\nby  almost  every  WiLDTool.   Most  of them are for string handling, e.g.:\nCenterStr(),   Word(),  Words()  etc  etc,  if  You''d  like  to  have  more\ninformation, drop me a mail (see CONTACT).\n\n         - -- --- ---- -----=[ C O N T A C T ]----- ---- --- -- -\n\nCall  my board :  Dixie +48-71-575825 or leave me a mail at CONSCIUOS DREAM\n(Logic DKQH)\n\nIf You want to use all the beta-wildtools CALL me, don''t forget Your system\nconfiguration  etc and You will receive a key-file which will unlock all of\nthem.\n','\n',char(10)),NULL,'auto-added',17849,6,0,NULL,NULL,'wnuke06','scan',1780048830);
INSERT INTO door_catalog VALUES('woa_fr10','WOA-FR10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/WOA-FR10.LHA','RPSTaRT','XIM','RPSTaRT',NULL,NULL,'WOA','__ _ _ _ ____ _ ____ _ ______ _ ______ /   /\ ____/_    . . \        \ ___ __ /___/  \\     \   ¡ ¡  \_ __|_  \',replace('  )-[*]<---[ wARRIORS oF aRT! ]--->[*]-(\n__ _ _ _ ____ _ ____ _ ______ _ ______\n        /   /\ ____/_    . . \        \\n___ __ /___/  \\     \   ¡ ¡  \_ __|_  \\n       \   \  / \     \  ! !   / \____  \\n __ __ _\___\/  /\     \ _____/____l_____\\n     _ ___ _____/\______\    -gD/wOA     \n\nWOA - /X - iNSPiRATiON hits ya with a ...\nnew, faast, smart and goodlooking FRONTDOOR\n','\n',char(10)),'WOA-FRONT.guide',replace('@DATABASE "WOA-FRONT 1.0"\n@$VER: WOA-Front 1.0\n@author "Gravedancer/woa"\n@(c) "gRAVEDANCER/WOA -95"\n@remark WARRIORS OF ART - /X - iNSPiRATiON\n\n@NODE MAIN "WOA-FRONT 1.0 / WARRIORS OF ART - /X - iNSPiRATiON"\n                                       __________\n:_________/_________________/\_________\___     /\_______\n¦    ____/___.________     /  ________    /    /   _____/____:__ _\n¦    \__     |      _/   _/   \_    \    /    /   ___/       ¦\n¦______|     |______\     \____|     \_______/_______________¦__ _ \n       |     |-Mo!   \_____/   l______/aC!                   :\n   ____|____ | /\__________________ ________     /\_______________________\n _/   _____/ |/  _____________     \_   ___/____/_  _________.______     /\n \    \|     |   \_    \    l/      /   \        / ___/      ¦    _/   _/\n  \__________l____|     \___/      /____________/____________¦____\     \_\n                  l______/ \______/                          ·     \_____/\n\n\n                                 @{"What is it? " Link 0.}\n                                 @{"Installation" Link 1.}\n                                 @{"Contact me! " Link 2.}\n                                 @{"Greetz      " Link 3.}\n                                 @{"The Future  " Link 4.}\n@endnode\n\n@node "0." "WOA-FRONT 1.0 / WARRIORS OF ART - /X - iNSPiRATiON"\n\n@{B} @{U}What is WOA-FRONT?@{ub}@{UU}\n\nWOA-Front is yet another faast, goodlooking and intelligent /X - frontdoor\n\nthis frontdoor is able to show ANY ascii/ansi text/animation before it outputs\nthe node stats ... \n\n@endnode\n\n@node "1." "WOA-FRONT 1.0 / WARRIORS OF ART - /X - iNSPiRATiON"\n\n@{B} @{U}Installation@{ub}@{UU}\n\nto install this nice tool, just copy the FRONTEND.info to your syscmd-dir and\nall in doors to DOORS: \n\nremember to copy all from c to c: and all from libs to libs: and don''t forget\nto launch rpstart in your user-startup ...\n\nthat''s all ...\n\n@{B} @{U}HEADER@{ub}@{UU}\n\nthe text to be shown is called header and can be found in doors:woa-front/\nif you want no headertext simply make an empty file ... i added an sample\nheader text with only an screen clear code ...\n\n@{B} @{U}IMPORTANT@{ub}@{UU}\n\nplease take note that the headertext must begin with an screen clear ...\n(this is done by pressing "Ctrl"+L)\n\n@endnode\n\n@node "2." "WOA-FRONT 1.0 / WARRIORS OF ART - /X - iNSPiRATiON"\n\ncontact gravedancer on the cosmic circus bbs ...\n\n                                     /\\n    /\________________________ _____/ \\__/\_______\n   /        /  .. \ ,________ Y ___/   \\         /\n  /  ______/   ¡¡  \ ____ \  \_/   \____/  ______/\n_/  /       \  !!   \_  /  \_ 7     /   | /       \\n\____________\_______/______/_l____/    ¦__________\\n                  -gD/woa          ¦    :\n                                   :    ¦\n                           /\______l    l________/\_______________________\n                          /        /    ¦ ___   /      /     /___. ,_____/\n                         /  ______/     : __/ _/ _____/__  _/    | ____ \\n                       _/  /       \    ¦ \   \  \       \ \     |    /  \_\n                       \____________\   l__\___\__________\______|________/\n                                 __ ____|\n\n@endnode\n\n@node "3." "WOA-FRONT 1.0 / WARRIORS OF ART - /X - iNSPiRATiON"\n\n          gENERATION/nTR^iLS^pDY ÷ dAN/nTR ÷ mICK/bP! ÷ mAGNETIC\n       hOMEBOY/iNDYPENDENT ÷ -sLIME/bP^mYTH ÷ mOGUE/sCOOPEX^aRT-cORE\n       dJ mELLOWNOISE/iNFECT ÷ dONALD/sHOOT ÷ tHE cROW/aVT/aRT-cORE!\n                    pRAYER/rAVE-dESIGN ÷ 2fAST/aRT-cORE\n\n@endnode\n\n@node "4." "WOA-FRONT 1.0 / WARRIORS OF ART - /X - iNSPiRATiON"\n\ni''d like to integrate something like a multi-style interface like it is used\nfor instance in noc-who - and add some nice bonus features ... hehehehe ...\n\n@endnode\n','\n',char(10)),NULL,'auto-added',47522,7,0,NULL,NULL,'woa_fr10','scan',1780048830);
INSERT INTO door_catalog VALUES('woa_tc11','WOA-TC11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/WOA-TC11.LHA','RPSTaRT','XIM','RPSTaRT',NULL,NULL,'WOA','__ _ _ _ ____ _ ____ _ ______ _ ______ /   /\ ____/_    . . \        \ ___ __ /___/  \\     \   ¡ ¡  \_ __|_  \',replace('  )-[*]<---[ wARRIORS oF aRT! ]--->[*]-(\n__ _ _ _ ____ _ ____ _ ______ _ ______\n        /   /\ ____/_    . . \        \\n___ __ /___/  \\     \   ¡ ¡  \_ __|_  \\n       \   \  / \     \  ! !   / \____  \\n __ __ _\___\/  /\     \ _____/____l_____\\n     _ ___ _____/\______\    -gD/wOA     \n\nWOA - /X - iNSPiRATiON hits ya with a ...\n update for the WOA-transferchecker [v1.1]  \n','\n',char(10)),'WOA-TRANSFER.guide',replace('@DATABASE "WOA-TRANSFER 1.1"\n@$VER: WOA-TRANSFER 1.1\n@author "Gravedancer/woa"\n@(c) "gRAVEDANCER/WOA -95"\n@remark WARRIORS OF ART - /X - iNSPiRATiON\n\n@NODE MAIN "WOA-TRANSFER 1.1 / WARRIORS OF ART - /X - iNSPiRATiON"\n                                       __________\n:_________/_________________/\_________\___     /\_______\n¦    ____/___.________     /  ________    /    /   _____/____:__ _\n¦    \__     |      _/   _/   \_    \    /    /   ___/       ¦\n¦______|     |______\     \____|     \_______/_______________¦__ _ \n       |     |-Mo!   \_____/   l______/aC!                   :\n   ____|____ | /\__________________ ________     /\_______________________\n _/   _____/ |/  _____________     \_   ___/____/_  _________.______     /\n \    \|     |   \_    \    l/      /   \        / ___/      ¦    _/   _/\n  \__________l____|     \___/      /____________/____________¦____\     \_\n                  l______/ \______/                          ·     \_____/\n\n\n                                 @{"What is it? " Link 0.}\n                                 @{"Installation" Link 1.}\n                                 @{"Contact me! " Link 2.}\n                                 @{"Greetz      " Link 3.}\n                                 @{"The Future  " Link 4.}\n@endnode\n\n@node "0." "WOA-TRANSFER 1.1 / WARRIORS OF ART - /X - iNSPiRATiON"\n\n@{B} @{U}What is WOA-TRANSFER?@{ub}@{UU}\n\nthis is another transferchecker utilitiy ...\n\n@{B} @{U}History:@{ub}@{UU}\n\nVersion 1.o - initial release\n\nVersion 1.1 - (this release) - added comments\n\n@endnode\n\n@node "1." "WOA-TRANSFER 1.1 / WARRIORS OF ART - /X - iNSPiRATiON"\n\n@{B} @{U}Installation@{ub}@{UU}\n\njust copy all from bbscmd to your bbscmd directory and all from doors: to\nyour doors: dir ...\n\nremember to copy all from c to c: and all from libs to libs: and don''t forget\nto launch rpstart in your user-startup ...\n\nthat''s all ...\n\n@endnode\n\n@node "2." "WOA-TRANSFER 1.1 / WARRIORS OF ART - /X - iNSPiRATiON"\n\ncontact gravedancer on the cosmic circus bbs ...\n\n                                      /\\n  ________ _____  _____________ _____/ \\  ________\n__\      /_\ .. \_\ ,____  /__ Y ___/   \\_\      /\n _______/    ¡¡  \_ ___  \/   \_/   \____/ ______/\n \       \   !!   /   /   \_   7     /   | \      \\n_ ________\______/_________/___l____/____l_________\  -gD/woa\n\n                            _______/\  _________ _______ ______ ___________\n                          __\     / \\_\____   /_\     /_\    /___. ,_____/\n                           ______/   \\  __/ _/ ______/     _/    | ____ \\n                           \      \___/  \   \  \      \    \     |    /  \_\n                        _ _________\  |___\___\_________\_________|________/\n                               __ ____l\n\n@endnode\n\n@node "3." "WOA-TRANSFER 1.1 / WARRIORS OF ART - /X - iNSPiRATiON"\n\n          gENERATION/nTR^iLS^pDY ÷ dAN/nTR ÷ mICK/bP! ÷ mAGNETIC\n       hOMEBOY/iNDYPENDENT ÷ -sLIME/bP^mYTH ÷ mOGUE/sCOOPEX^aRT-cORE\n       dJ mELLOWNOISE/iNFECT ÷ dONALD/sHOOT ÷ tHE cROW/aVT/aRT-cORE!\n                    pRAYER/rAVE-dESIGN ÷ 2fAST/aRT-cORE\n\n@endnode\n\n@node "4." "WOA-TRANSFER 1.1 / WARRIORS OF ART - /X - iNSPiRATiON"\n\ni dont know, but i hope to find some good ideas ... see ya in the phuture !\n\n@endnode\n','\n',char(10)),NULL,'auto-added',48648,8,0,NULL,NULL,'woa_tc11','scan',1780048830);
INSERT INTO door_catalog VALUES('world_cl','WORLD-CL.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/WORLD-CL.LHA','WORLD-CLOCK','XIM','WORLD-CLOCK',NULL,'SieGeL/tRSi','WORLD','\    ____    )  /___/\_| & rED sECTOR ¡NC | .-\___\ | \___\__   /   |  /X ¡NNOVATION   | )---|___|___|______/____|---[ [RESENTS ]---''',replace(' _____________ ___Mo! __.<---[ tRISTAR ]---.\n \    ____    )  /___/\_| & rED sECTOR ¡NC |\n.-\___\ | \___\__   /   |  /X ¡NNOVATION   |\n)---|___|___|______/____|---[ [RESENTS ]---''\n|\n| wORLD-cLOCK V1.18 wRITTEN bY SieGeL/tRSi\n`------------------------------------------.\n fIXED sOME eNFORCER-hITS, 2 nEW tOOLTYPES,|\n.------------------------------------------''\n|   aDDED nEW dIGITS fROM 2fAST/aRTcORE!\n`------------------------------------------.\n     gET tHE bEST /X-cLOCK eVER wRITTEN <--''\n','\n',char(10)),'WoRLD-CLOCK.GUIDE',replace('@database World-Clock V1.18 by SieGeL/TRSi (/X-iNNoVaTioN) BeRLiN-GeRMaNY\n\n@Remark $VER: V1.18 (Sunday 11-13-1994)\n\n@node Main "WoRLD-CLoCK V1.18 - /X uTiL WRiTTeN BY SieGeL/tRSi"\n@{b}\n  _______________________________________________                  _______\n |  ___________      _______. ___________ _______|_      _________|_    _/\n |  \\    _____/_____(_______:/   __     /___  ____/_____/_   __    /___ |\n | _/\\_______     /         :   _______/   /  \\__        /  ______/   / |\n | \\ _ __________/__________:_____________/_____/  Mo!  /____________/  |\n |  \\\\ /                                       /_______/          l_____|\n |   \\/  @{ub}SIEGEL/TRSI (/X·INNOVATION) PRESENTS    @{b}|\n |      -------------------------------------    |     @{" INTRODUCTION " Link INTRO}\n |                                               |     @{" INSTALLATION " Link INSTALLATION}\n |                                               |     @{"  TOOL-TYPES  " Link TOOLTYPES}\n |            @{ub}··W·O·R·L·D··C·L·O·C·K··@{b}           |     @{"  ARGS IN /X  " Link ARGS}\n |                                               |     @{"DIGIT-EXAMPLES" LINK DIGITS}\n |                  @{ub}V1.18 pUBLIC@{b}                 |     @{"  GREETINGS!  " Link GREETS}\n | \\                                             |\n | \\\\\                                            |   @{u}gRAPHICAL dESIGN bY@{uu}\n @{b}`-----------------------------------------------''@{ub}\n  AMBLIN/dEZiGN / COUNT ZER0/SCL / aXe/MST / -rEDSKIN/aRT / 2fAST/aRTcORE!\n@endnode\n\n@node INTRO "INTRODUCTION"\n\n                              @{u}iNTRODUCTION@{uu}\n\nAehm...in the last public Version (V1.16) I had said that *NO* update of \nthis clock will be ever released in the Future...but then 2fAST from \naRTcORE! had painted a nice charset, so I decided to write another update..:)\n\nDuring the update, I made again some changings in the code, now it''s possible\nto define the Date & Location Line for yourself. Detailed Informations for\nthis could be found in the @{"ToolTypes" LINK TOOLTYPES} - Chapter.\n\nTo get a complete overview what changed take a look to the @{b}History-File@{ub} \nincluded in this archive...let''s go on with @{"Installation" LINK INSTALLATION}...\n@endnode\n\n@node INSTALLATION "INSTALLATION OF WORLD-CLOCK V1.18"\n\n                       @{u}rEQUIREMENTS & iNSTALLATION@{uu}\n\nOf course you need any Amigamodel (500-4000T) with Kickstart V37++ and a full\ninstalled and working Amiex (Should work under /X V2.xx, too).\n\nPut wORLD-cLOCK V1.18 and the icon wherever you want, but I recommend to \ncreate an Directory for wORLD-cLOCK, coz wORLD-cLOCK is now able to save the\nuser-preferences, and they will be saved in the dir wORLD-cLOCK is started\nfrom.\n\n@{u}NOTE:@{uu} In difference to previous versions, wORLD-cLOCK needs @{b}*NO*@{ub} icon anymore\n      to run correctly. So if you don''t copy the icon to the same drawer the \n      clock is stored, wORLD-cLOCK only shows the local time. The times of \n      the other cities couldn''t be displayed, coz you have to define the GMT-\n      Time-Offset in the Icon to let wORLD-cLOCK calculates the other times !\n\nCopy the icon `T.info'' to your BBSCMD/ drawer and change the Location to the\npath where wORLD-cLOCK V1.18 could be found. That''s all. To configure the \nClock to your needs take a look to the @{"Tooltypes" link TOOLTYPES}.\n\n@{u}NOTE:@{uu} Starting from V1.16, every user is able to configure the clock to his \n      own needs, and therefore it''s not neccessary that you configure the\n      clock in the icon. If you configure it in the Tooltypes, this\n      configuration is only the default one which will be overwritten by the\n      user''s config.\n@endnode\n\n@node TOOLTYPES "ALL TOOLTYPES USED BY WORLD-CLOCK V1.18"\n\n                              @{u}tOOLTYPES@{uu}\n\n LOCATION=<string>       = Here you could enter the Location of your city,\n                           i.e. Berlin-Germany. If you don''t want to enter\n                           a Location, put this Tooltype in Branches. The\n                           Clock uses then as location the name of your bbs.\n\n LOCATION_LINE=<string>  = Here you could define your own default-line for\n                           the location from where the time is shown. \n                           Default is :\n                           "tIME sHOWING fROM %L" <-- The %L will be replaced\n                                                      by your Location !!!\n\n                           This will be used if you don''t define this Tool-\n                           type.If you want to specify your own, make sure\n                           that you don''t write too much chars, coz the %L\n                           will always replaced by your Location ! Of course\n                           you don''t have to use the %L command, in this case\n                           only the string you have defined will be printed.\n\nDATE_LINE=<STRING>       = This command allows you to define your own Date-\n                           line...for this option currently exists two \n                           commands:\n\n                           %T  --> Day (i.e. Wednesday)\n                           %D  --> The actual date (i.e. 09-FEB-95)\n\n                           The Defaultsetting for this option is :\n\n                           "actual systemdate is %D (%T)"\n\n                           @{u}NOTE FOR WB 2.1++ USERS:@{uu}\n                           Both commands will be translated to the Language,\n                           you have defined in your SYS:Prefs/Locale Program.\n                           So if you have German as default language, both\n                           commands will be translated in :\n                          \n                           %T = Mittwoch and %D = 09.02.95 \n                           \n GMT=<GMT-Time>          = Here you must define your GMT-Time (GMT=Greenwich-\n                           MeanTime). For Germany, it''s +1. If U don''t define\n                           this Tooltype, the WoRLD-CLoCK wouldn''t be shown,\n                           you only see the time from your board.\n\n LINE_ART=<char>         = If you want to seperate the Clock from the cities,\n                           you could enter here *one* char (i.e. -, +, =) and\n                           this char will be used to create two lines between\n                           the clock and the cities. If you don''t want to \n                           seperate it, put this Tooltype in branches or don''t \n                           define a char for it.\n\n CHARSET=<number>        = I''ve included five different styles for the clock.\n                           Here you could choose which one will be used to\n                           show the time. Only 0,1,2,3 and 4 are allowed as \n                           valid numbers. The numbers are defined as follow:\n\n                           0 = dIGITS fROM Amblin (Default!) \n                           1 = dIGITS fROM Axe\n                           2 = dIGITS fROM Count Zero\n                           3 = dIGITS fROM -redSkin\n                           4 = dIGITS fROM 2fAST/aRTcORE!\n                     \n                           To check out the digits, take a look to @{"DIGITS" Link Digits}.\n\nAll following ToolTypes are the defines for the colors. Valid colornumbers are\n30-37, which represents the ANSI-Colors in /X. I recommend not to use 30, as \nthis color is black and you won''t see very much if you enter it...:)\n\n MAIN_COLOR=<color>      = The color for the Title and the Lines between the\n                           clock and the cities. Default is 33 (yellow).\n\n CITY_COLOR=<color>      = The color for "TIME SHOWING FROM.." and the cities.\n                           Default is 36 (light blue).\n\n DIGITS_COLOR=<color>    = The color for the digits and the citytimes. Default\n                           is 35 (lila).\n\n DATELINE_COLOR=<color>  = The Color for the Dateline ( MM-DD-YY (DAY) ).\n                           Default is 34 (dark blue).\n@endnode\n\n@node ARGS "KNOWN ARGUMENTS GIVEN AT AMIEX-PROMPT"\n\n                             @{u}aRGUMENTS@{uu}\n                             \nYou could start the clock in three different ways...\n\n@{u}1) Normal Start:@{uu} @{b}T@{ub}\nThis is the easiest way to start the clock...the actual time(s) will be shown\nand the clock quits.\n\n@{u}2) Configuration:@{uu} @{b}T E@{ub}\nIf you start the clock in this mode, you get an optionsscreen which allows \nall users to configure their ''own'' clock-style. In Configuration-Mode the \nfollowing options are accessable:\n\n@{b}1@{ub},@{b}2@{ub},@{b}3@{ub},@{b}4@{ub} - Changes the Colors of the clock\n\n   @{b}5@{ub}    - Allows you to change the seperator char\n\n   @{b}6@{ub}    - Select the Digitstyle, available are five different ones. Take a\n          look to @{"DIGITS" Link DIGITS} for some examples.\n\n   @{b}7@{ub}    - Select one of five different Date-Formats.\n\n   @{b}S@{ub}    - Save current settings as default ones and display the clock in the\n          current settings.\n\n   @{b}P@{ub}    - ''Preview'' of current settings..use this if you don''t know how the\n          current settings looks like...:)\n\n   @{b}A@{ub}    - Use current Settings and start wORLD-cLOCK in Animation-Mode.\n\n   @{b}Q@{ub}    - No saving and reset Settings to default.\n\n\n@{u}3) Animation:@{uu} @{b}T A@{ub}\nIn this mode wORLD-cLOCK starts with displaying the time(s), but in \ndifference to the normal mode the Local-System-Time will be updated every\nsecond and the World-Times will be updated every minute. To stop the anim\nsimply press @{b}CTRL-C@{ub} to return to mainprompt.\n@endnode\n\n@node Digits "SOME EXAMPLES FOR THE DIGIT-STYLES"\n\n--------------------------- aMBLiN/DeZiGN -----------------------------------\n\n  .######.  .####   .######. .######. ###   .  ######## .######. ########\n  ###  ###  #####   ##   ### ###  ### ###  .#  ###      ###  ###    .####\n  ###  ###   ####        ###      ### ### .##  ###      ###        .####\n  ### .###   ####   .######    #####  ### ###  #######. #######.   #### \n  ### ####   ####   ###          .### ########     .### ### .###   ####\n  ### ####   ####   ### #### ### ####    ####  ### #### ### ####   ####\n  ### ####   ####   ### #### ### ####    ####  ### #### ### ####  .####.\n  `######'' ######## ######## `######''   ###### `######'' `######''  ######\n                                              \n------------------------------ aXe/MYSTiC -----------------------------------\n\n  .######.  .###### #######. #######. ###  ### ######## .####### #######.\n  ######## .####### ######## ######## ###  ### ######## ######## ########\n  ###  ### ###''####    .####      ### ###  ### ###      ###           ###\n  ### ####     ####  .#####''   ###### ######## #######. #######.   ######\n  **** ***     **** .*****''    ****** `******* ******** ********   ******\n  ***  ***     **** ****''         ***      ***      *** ***  ***      *** \n  ***  ***     **** ******** ********      *** ******** ********      ***  \n  `******''     **** `******* *******''      *** *******'' `******''      ***\n\n-------------------------- CouNT ZeRo/SCaNDaL! ------------------------------\n\n.:::::::. :::::.    :::::.    :::::. ::::      ::::::    .:::::    .::::::::\n:::: ....   ....      ....      .... :::: .... ::::      ::::      :::: ....\n:::: ::::   :::: .:::::::·     ::::· ·:::::::: ::::::::. ::::::::.      ::::\n:::: ::::   :::: :::: .... :::: ::::      :::: .... :::: :::: ::::      ::::\n·:::::::·   :::: ·:::::::: ·:::::::·      :::: ·:::::::· ·:::::::·      ::::\n\n------------------------------ -redSkin/aRT ---------------------------------\n\n .......  .......    .....    .....   ... ...  .....    .....   ....... \n:::: :::    :::::: .....:::     .::: :::: ::: ::::...  ::::....  .::::::\n:::: :::    :::::: :::: ... .... ::: :::: ::: .... ::: :::: :::   ::::::\n:::: :::    :::::: :::: ::: :::: ::: :::: ::: :::: ::: :::: :::   ::::::\n:::: :::    :::::: :::: ::: :::: ::: :::: ::: :::: ::: :::: :::   ::::::\n:::: :::    :::::: :::: ::: :::: ::: ::::.::: :::: ::: :::: :::   ::::::\n:::: :::    :::::: :::: ::: :::: :::      ::: :::: ::: :::: :::   ::::::\n   `-''                `-''      `-''               `-''      `-''\n\n------------------------------ 2fAST/aRTcORE! -------------------------------\n\n  .:   ::::.   ::::. ::: ::: .::::   .::::   ::::. .:::::. .:::::. .:::::.\n  ::   :::::   ::::: ::: ::: :::::   :::::   ::::: ::::::: ::::::: :::::::\n :::     :::     ::: ::: ::: :::     :::       ::: ::: ::: ::: ::: ::: :::\n :::  .:::::   ::::: ::::::: ::::::. ::::::.  .::: `:::::'' ::::::: ::: :::\n ::: ::::::''   ::::: `:::::: `:::::: :::::::  :::: ::::::: `:::::: ::: :::\n ::: :::         :::     :::     ::: ::: :::  :::: ::: :::     ::: ::: :::\n ::: ::::::: :::::::     ::: ::::::: :::::::  :::: :::::::   ::::: :::::::    \n ::: `:::::: ::::::''     ::: ::::::'' `:::::''  :::: `:::::''   ::::'' `:::::''   \n\n@endnode\n\n@node GREETS ".....THE AMAZING GREETINGS......"\n\n@{u}fAST gREETINGS fLY tO :@{uu}\n\naMBLiN/DeZiGN   - THX for the fast work. Personally my favourite digits...:)\naXe/MYSTiC      - CeWL digits Dude. Hope to see yar one time again..\nCount Zero/SCL  - Great paintings dude..should i write sTYLEz ? :)\n-redSkin/aRT    - Very cewl digits, hope to get a BBSTitle from U soon..:)\n2fAST/aRTcORE!  - For the many pictures you''ve painted 4 me..thx dude..\nByteAndi/tRSi   - Thx for givin me ur routine..:)\naRGoN/dTL       - THX 4 support and testing on my @{"BBS" Link BBSADVERT}..\ndEATH aNGEL/SDC - You''re my best Beta-Tester !! \n\n         and of course all tRSi-mEMBAS and all my users on my @{"BBS" Link BBSADVERT}\n\n-----------------------------------------------------------------------------\nMusical Support: dEATH, sADE, pINK fLOYD, jEAN-mICHEL jARRE\n\nTechnical Supp.: A4000/040 (T-REX pOWER rOOLEZ :), Ced V3.5, SAS-C V6.51\n-----------------------------------------------------------------------------\n@endnode\n\n@node TRSIMEMBER "TRSI (/X-iNNOVATiON)"\n\n                   ._________________  ______\n                   l___       /      \\/    _/_______.:  \n                     /       /   /  _/\\___      /    :\n                    /_______/-rS!\\_____\\  _____/     |''95\n                          /_______|     \\/   /_______|\n                       (/X-iNNOVATiON) Members are:\n                    ----------------------------------\n                                 ByteAndi \n                                  SieGeL  \n                                    Spy    \n                                  Delta-X  \n                                  Dr.Dre!\n                    ----------------------------------\n               if you wanna join us so get in touch with\n\n                           one of our members.\n\nIf you want to order a tool, give us Bugreports, hints and tips for this or\nother tools comin'' from (tRSi/X-iNNOV