INSERT INTO door_catalog VALUES('wot_ad14','WOT-AD14.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/WOT-AD14.LHA','MultiDoorShutdown','XIM','Install.exe',NULL,NULL,'WOT','// / / \/_ \// /  /  \_ \// / //____ \ // / // // _//\// /-OF-/ // / //\  \/ / \.__/\_//\ \__/\_/    / /\.__//\___/ /RD',replace('   _/\/\_  __  _  _/\  ___  _/\/\o_____\n  // / / \/_ \// /  /  \_ \// / //____ \\n // / // // _//\// /-OF-/ // / //\  \/ /\n \.__/\_//\ \__/\_/    / /\.__//\___/ /RD\n-  -- --- -\/»Presents«\/------ --- \/ -- -\n   Ami Express SHARED Door Library V1.14\n-- - - -- - -- -- -- --- - -- -- -- -- - -- \nIncludes examples to use it from: Amiga E,\nAssembler and SAS/C V6! A *MUST* for Sysops\n& Coders!  »»» UPDATE: MultiDoor BUG Fixed!\n- -- -- --- -- - -- - - - -- - -  -- - - --\n','\n',char(10)),'AEDoor.doc',replace('TABLE OF CONTENTS\n\nAEDoor.library/CreateComm\nAEDoor.library/DeleteComm\nAEDoor.library/SendCmd\nAEDoor.library/SendStrCmd\nAEDoor.library/SendDataCmd\nAEDoor.library/SendStrDataCmd\nAEDoor.library/GetData\nAEDoor.library/GetString\nAEDoor.library/Prompt\nAEDoor.library/WriteStr\nAEDoor.library/ShowGFile\nAEDoor.library/ShowFile\nAEDoor.library/SetDT\nAEDoor.library/GetDT\nAEDoor.library/GetStr\nAEDoor.library/CopyStr\nAEDoor.library/HotKey\nAEDoor.library/PreCreateComm\nAEDoor.library/PostDeleteComm\nINSERT INTO door_catalog VALUES('wot_ad22','WOT_AD22.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/WOT_AD22.LHA','MultiDoorShutdown','XIM','MultiDoorShutdown',NULL,NULL,'WOT','\__     /       /    \____    ____/ /     /\      /    |   \      \ /             /     |    \      \  Mb',replace('    /\_______/       /_______________/\\n    \__     /       /    \____    ____/\n     /     /\      /    |   \      \   \n    /             /     |    \      \  Mb\n   /       /\____/\__________/       \\n   \______/  » Presents: «  |________/\n   Ami/S-Express SHARED Door Library V2.2\n-- - - -- - -- -- -- --- - -- -- -- -- - -- \nExamples in: Amiga E, Assembler, SAS/C V6\nand HSPascal! A *MUST* for Sysops & Coders!\n»» UPD: 32 Node comp, HSPascal Support, +++\n- -- -- --- --[ RELEASE DATE: 25-FEB-94 ]--\n','\n',char(10)),'AEDoor.doc',replace('TABLE OF CONTENTS\n\nAEDoor.library/CreateComm\nAEDoor.library/DeleteComm\nAEDoor.library/SendCmd\nAEDoor.library/SendStrCmd\nAEDoor.library/SendDataCmd\nAEDoor.library/SendStrDataCmd\nAEDoor.library/GetData\nAEDoor.library/GetString\nAEDoor.library/Prompt\nAEDoor.library/WriteStr\nAEDoor.library/ShowGFile\nAEDoor.library/ShowFile\nAEDoor.library/SetDT\nAEDoor.library/GetDT\nAEDoor.library/GetStr\nAEDoor.library/CopyStr\nAEDoor.library/HotKey\nAEDoor.library/PreCreateComm\nAEDoor.library/PostDeleteComm\nINSERT INTO door_catalog VALUES('wot_aed','WOT-AED.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/WOT-AED.LHA',NULL,'XIM','AEDoor.library',NULL,NULL,'WOT','Code your own doors in /X /X developers pack!!! ------------------------------------------',replace('------------------------------------------\nCode your own doors in /X\n/X developers pack!!!\n------------------------------------------\n','\n',char(10)),'AEDoor.doc',replace('TABLE OF CONTENTS\n\nAEDoor.library/CreateComm\nAEDoor.library/DeleteComm\nAEDoor.library/SendCmd\nAEDoor.library/SendStrCmd\nAEDoor.library/SendDataCmd\nAEDoor.library/SendStrDataCmd\nAEDoor.library/GetData\nAEDoor.library/GetString\nAEDoor.library/Prompt\nAEDoor.library/WriteStr\nAEDoor.library/ShowGFile\nAEDoor.library/ShowFile\nAEDoor.library/SetDT\nAEDoor.library/GetDT\nAEDoor.library/GetStr\nAEDoor.library/CopyStr\nAEDoor.library/HotKey\nINSERT INTO door_catalog VALUES('wot_atag','WOT-ATAG.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/WOT-ATAG.LHA','AutoTag','XIM','AutoTag',NULL,NULL,'WOT','// / / \/_ \// /  /  \_ \// / //____ \ // / // // _//\// /-OF-/ // / //\  \/ / \.__/\_//\ \__/\_/    / /\.__//\___/ /RD',replace('   _/\/\_  __  _  _/\  ___  _/\/\o_____\n  // / / \/_ \// /  /  \_ \// / //____ \\n // / // // _//\// /-OF-/ // / //\  \/ /\n \.__/\_//\ \__/\_/    / /\.__//\___/ /RD\n-  -- --- -\/»Presents«\/------ --- \/ -- -\nAutoTag  V1.0 - An /X AutoSent Clone, which\nuses  the  AEDoor.Library  so  that you can\nstill  use  other  AEDoorLib  doors  in the\nFILECHECK icon, like the FAST Dupe Checker!\n- -- -- - -- -- - -- - - - -- - - -- - - --\n','\n',char(10)),'AutoTag.DOC',replace('\n                            TAG LINE Adder V1.0\n                               AutoTag V1.0\n\n                                    by\n\n                                SiNTAX/WøT\n\n\n1. What it does\n~~~~~~~~~~~~~~~\n\nThis is just a replacement package for the AutoSent door written by\nByteAndi/MST. It does exactly the same thing, even uses the same file format\nso that you don''t need to convert all the AutoSent data files.\n\nSo why did I make it then? Well I couldn''t install ByteAndi''s SENT door, since\nmy FILECHECK icon was already taken by my DUPLICATE Checker. So I just made an\nautosent myself using the AEDoor library''s Multi Door feature. This means you\ncan now have AND the FAST DUPLICATE Checker AND this AutoTag door installed in\nthe same FILECHECK icon.\n\n\n2. How to use it with another door\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\nThe first requirement is that both doors use the AEDoor.library (V1.14!!!!!)\nThen make a little script file like this:\n\n\n------------------[CUT HERE]---------------\n.key node\n.bra {\n.ket }\n\nDOORS:MultiDoorStart {node}		;This creates the multi door environment\nDOORS:FILEID/Sent {node}\nDOORS:DupeCheck/Dupe.X {node}		;THiS is an example, replace this one\n					;with any other door using the AEDoorLib\nDOORS:MultiDoorShutdown {node}	;This shut''s down the multi door environment\n------------------[CUT HERE]---------------\n\n\nPut the filename of this script in the LOCATION= tooltype of the FILECHECK\nicon, and don''t forget to set the script bit on this file\n(PROTECT <filename> +S) Use XIM as DOORTYPE and NOT SIM as you would normally\ndo for a script file!\n\n\nATTENTION!!! Be sure you use V1.14 of the library!!! The multi door support of\n             V1.13 was bugged!\n\n\n\n3. How to use it\n~~~~~~~~~~~~~~~~\n\nJust type SENT at the bbs main prompt and then enter your TAG line, from now\non the bbs will add this line to your descriptions! You can change the tag\nline any time by re-issuing the SENT command.\n\n\n\n\n=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-\n16.8oo                  THIS FILE WAS LEECHED FROM                    16.8oo\n\n                          -=* S I N  C I T Y *=-\n\n                        » WoRLD øf TwiST EµRØ HQ «\n\n            HOT WAREZ/eXTeNSiVE HPA AREA/AE UTILS/ON-LINE GAMES\n\nCALL NOW: ++32-(0)3-8252274 ... 16.8 COURIER HST DUAL STANDARD (ASL/V.42BIS)\n-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=\n\n','\n',char(10)),'{"LOCATION":"tooltype"}','auto-added',10336,2,0,NULL,NULL,'wot_atag','scan',1780048830);
INSERT INTO door_catalog VALUES('wot_dp11','WOT-DP11.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/WOT-DP11.LHA','Installer','XIM','DupePrep',NULL,'SiNTAX/WøT','WOT','// / / \/_ \// /  /  \_ \// / //____ \ // / // // _//\// /-OF-/ // / //\  \/ / \.__/\_//\ \__/\_/    / /\.__//\___/ /RD',replace('   _/\/\_  __  _  _/\  ___  _/\/\o_____\n  // / / \/_ \// /  /  \_ \// / //____ \\n // / // // _//\// /-OF-/ // / //\  \/ /\n \.__/\_//\ \__/\_/    / /\.__//\___/ /RD\n-  -- --- -\/»Presents«\/------ --- \/ -- -\n FAST Duplicate Checker V1.1 by SiNTAX/WøT\n-- - - -- - -- -- -- --- - -- -- -- -- - --\nUPDATE: Memory Problem fixed (didn''t free \n        all it''s memory, so you lost 11Kb\n        each time it was run)\n- -- -- --- -- - -- - - - -- - -  -- - - --\n','\n',char(10)),'Dupe.DOC',replace('\n                             Duplicate Checker\n\n                                    by\n\n                          SiNTAX/WøT in 1993/1994.\n\n\n0. Update V1.0->V1.1 info\n~~~~~~~~~~~~~~~~~~~~~~~~~\n\nIf you already have V1.0 running, then all you need to do is to copy the\nDupe.X file in drawer Commands/DupeCheck to your DOORS:DupeCheck dir.\n\n\n1. Info\n~~~~~~~\n\nThis is an Ami Express FILECHECK door (100% assembler), which will check if\nthe uploaded file(s) have already been uploaded once to your board. This\nfeature was present in Ami Express V2.x but was removed for unknown reasons\nfrom the V3 series. Not that I ever used it, since it was not that fast on my\n7.14Mhz machine.\nThese days there is a door available (written by SiGMA SEVEN!) to take care\nof the duplicate checking, but it is still a bit too slow for my machine.\nSo I took my best shot and here is the result... A duplicate file checker\nthat on average needs less than 0.1 seconds to check out a file!!! BUT...\nas always there is a slight drawback, and that is DiskSpace. This duplicate\ncheck needs on average 4 bytes of diskspace for ever file, in these 4 bytes\ninformation concerning the file is saved so that the checker will be very\nfast in determining whether a file is a duplicate or not. It only needs to\ndo a complete dir scan in some (rare) cases.\n\n\nNOTE: don''t be alarmed when you see a ''dupe.resource'' when using XOper or a\n      similar utility. The duplicate checker starts this resource and uses it\n      to avoid problems with multi node systems\n\n\n\n2. Installing\n~~~~~~~~~~~~~\n\nInstalling the checker is pretty easy (I hope), just add the FILECHECK icon\nto your BBS:Commands/SysCmd directory. Then copy the dir in the Commands\ndirectory to your DOORS: directory... VOILA, you are now done with the HARD\nwork.\nNext step is adding the duplicate check to the desired conferences (this\nchecker can be disabled for some conferences, as you can see, another + !)\nAll you have to do is start the installer script (use ''startscript'' from\nshell, installer should be in the command search path.. e.g. in C: ) and then\nfollow the guidelines. The script will scan your BBS: directory for conference\nsubdir''s, it will then present you with a list of selectable conferences to\nadd the dupe check to. Just select the one you want and the script will do the\nrest for you!!\n\nSome notes about the installer script...\n\n1> It needs the SORT & DELETE command in your C: dir\n2> the T: dir should be assigned to a storage device with enough space to\n   hold your DIRx files 2x in it... so on most systems the RAM: will suffice\n3> the ENV: should be assigned (all /X boards have this, since /X uses the\n   ENV: for storing information about what the user is doing)\n4> The script needs some cli utils, which you should have copied to your\n   DOORS: directory, together with the door itself (don''t deleted these utils\n   after installing, cuz you may need them again!)\n\n\nAnd last, but certainly not least: DON''T forget to copy the AEDoor.library to\nyour LIBS: directory, else the checker will not work (in fact, it will most\nlikely crash your computer!!!!)\n\n\n3. Additional info & known bugs\n~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~\n\n* There isn''t really a bug in the duplicate checker, but more in the way it is\n  implemented. Ami Express ONLY starts the FILECHECK door when somebody ul''ed\n  a file with a 3 character extension. So this means that if somebody uploads\n  a file without extension that it isn''t checked.. nuttin'' I can do about this\n* Pay attention when putting files on your own board, be sure to use the local\n  upload function!!! If you don''t then the files will not be added to the dupe\n  database, meaning Duplicate Check will not know if it was on the board \n  before. Now if you were to forget to do it this way, then just start the\n  installer script again.. this will rebuild the database from scratch again\n  (including your new files)\n\n\n4. History\n~~~~~~~~~~\n\n**  Release 0.1\n**	Internal version. And ßeta-Testing\n**\n**  Release 0.2\n**	Changed ANSI CSI code to $1b,''['' instead of $9b which didn''t work\n**	with the /X ansi filter.\n**\n**  Release 0.3\n**	The program can now be made resident! The door is now fully written\n**	in PC-relative reentrant code. One drawback to this is that the door\n**	has to allocate memory for it''s data section, so when your system is\n**	low on memory, it can occure that this memory allocation fails. The\n**	program will then go to sleep for 1/50th second and retry the memory\n**	allocation, until it succeeds... However if your system is already\n**	that low on memory that it can''t allocate these few extra bits, then\n**	I''m sure something else will mess up your system before my door can!\n**\n**  Release 0.4\n**	File description lines with types ''D'' and ''F'' are now also taken as\n**	valid lines. So position 13 maybe be one of these [''P'',''D'',''F'',''N'']\n**	This is done to support PSEUDO-Ops OffLineChecker & the many faker\n**	doors available these days.\n**\n**  Release 0.5\n**	Aligned most subroutines on long-word boundaries to make all 68020+\n**	users happy  => less (slow) memory access\n**\n**  Release 1.0\n**	First public release.\n**\n**  Release 1.1\n**	BUG FIX: looks like I forgot to write some code when making the proggy\n**		 reentrant! I simply forgot to free up the allocated memory :(\n**		 As a result, you lost approx. 11336 bytes each time the door\n**		 was run!!!\n**\n\n\n5. Some words\n~~~~~~~~~~~~~\n\nThe output & ANSI styling was taken from the SiGMA SEVEN! duplicate checker,\nso.. credit where credit belongs... Thanks man, and sorry for not asking you\nfirst :-)\n\nCredits:\n\nDuplicate Check: SiNTAX/WøT\nOutput & ANSI Styling: SiGMA SEVEN!\nAEDoor Library: SiNTAX/WøT\n\nßeta testing:\n   KICKFACE - Phantom BBS  (2 node system, A3000 - 68030)\n            - Also tested it on his A4000/040\n   SiNTAX   - Sin City BBS (1 node system, A2000 - 68000)\n\n\nAnd ofcourse Joseph Hodge for his work on Ami Express!\n\n','\n',char(10)),NULL,'auto-added',71815,5,0,NULL,NULL,'wot_dp11','scan',1780048830);
INSERT INTO door_catalog VALUES('wrpser10','WRPSER10.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/WRPSER10.LHA','WarpSearch','XIM','WarpSearch',NULL,'Dres',NULL,'|  _________________           __          | |  \________________|)____.---''--`---.____ | |               ||    \----.________.----/ |',replace('.------------------------------------------.\n|  _________________           __          |\n|  \________________|)____.---''--`---.____ |\n|               ||    \----.________.----/ |\n| /X WarpSearch ||     / /    `--''         |\n|    V1.0     __||____/ /_    by Dres      |\n|            |___         \   & Crayor     |\n|                `--------''                |\n|This is the /X version of our boyer-moore |\n|  double buffered async I/O search code.  |\n|  It`s a "z" door that unifies all known  |\n|   speedup concepts of the AMiGA system.  |\n|On 040/060 the bottleneck is our baracuda |\n| fast-scsi2 drive 7MB/s. Go on Warp now!  |\n|The search routine is 100% pure assembler.|\n`------------------------------------------''\n[01-04-96]«diGiTAL^HAREm»[fTP&33.6k]-[14:12]\n','\n',char(10)),'WarpSearch.doc',replace('WarpSearch V1.0\n\nIntroduction\n------------\nThis is the AmiExpress version of WarpSearch.\nIt uses the boyer-moore search algorithm implemented in assembler code.\nThis algorithm is the fastest available.\n\nFeatures\n--------\nV1.0:\n-pattern matching\n-double buffered asynchonous I/O\n-backwards/forwards counting of filelists\n-highlightning\n\nInstallation\n------------\nCopy "z.info" to "bbs:commands/bbscmd/".\nChange LOCATION to your full path of the WarpSearch executable.\n\nUsage\n-----\nz <pattern> <filelist#> <+/->\n\nExample usage: "z foo" (searches from ul dir down for "foo").\nWildcards in pattern are allowed, like "z foo*bar" or "z bm_zearch*V1.0*"\nUse "z foo*bar 2 +" to search from dir2 upwards. Default is downwards search.\nThe pattern must match an expression in one line.\nPatterns are not case sensitive. Only "*" is accepted as a wildcard and no other\nconstructions like "#?","?" , which noone needs anyway in this application.\n\nInfo\n----\nThe complete filedescription including filename etc. is searched through.\nWe, the authors, think that this magic code is the fastest search routine ever\nmade for an /X like filelist, because the 100% assembler boyer-moore search\nroutine with pattern matching and highlightning is optimized for cpu cycles by\nhand, some magic is done for splitted filedescriptions, asychronous I/O.\nWe concidered speedup concepts for every line of code.\nOn our system the bottleneck is the Fast-SCSI-II Baracuda drive with a\nFast-SCSI-II CyberSCSI Controller that does 7MB/s, and the code is 3 times\nfaster if the filelist is in RAM with 50MB/s burst.\n\nThe maximum length of a description line allowed is 1000 chars. Since /X\nallows 80 chars/line as maximum we think this is no bug. If a line is longer\nthan 1000 chars enforcer hits may occur. A check for line length would slow\ndown the code significantly. That`s why we don`t do it.\n\nFor those who are interested, a short explanation of what "double buffered\nasync I/O" means:\nDue to the coolness of the Amiga, SCSI is the most accepted standard on this\nplatform (..well if we dont consider 4000 desktops..). SCSI has the ability\nto transfer data per DMA, thus meaning without using the processor. This is were\nasync I/O comes in. A program using double buffered async I/O lets the File-\nSystem first fill up one buffer, then sends the request to fill up the second\nbuffer, and while the HD is busy transfering data to the 2nd buffer the processor\nis free to do its work on the first one. As you can imagine this technique\ndramatically speeds up the whole process.\n\nIf you are keen on a shell version, just ask.\n\nSend your suggestions or bug reports to [email removed].\n\nGreetz\n------\nSome hellos to the following guys:\n\n"Ibo"  - with his always busy or down BBS, so that we weren`t able to abuse\n         his BBS for beta testing ;)\nHijack - thx for the cool name of this door m8. (yep! "WarpSearch" actually was\n         his idea)\nSCSI   - for his help on using iwan.device\nAmok   - for the address of Mr.F\nSTC    - for the competition of coding the fastest search code for /X filelists\nHydra  - for his try to code a better /X (hbbs)\nDave Haynie\n       - for answering my email on the Surfer Package\n\nRevision History\n----------------\nV1.0 - first public release\n','\n',char(10)),NULL,'auto-added',13328,1,0,NULL,NULL,'wrpser10','scan',1780048830);
INSERT INTO door_catalog VALUES('ws_ae27','WS-AE27.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/WS-AE27.LHA',NULL,'XIM','dA-fONK.exe',NULL,'Dres','WS','|  _________________           __          | |  \________________|)____.---''--`---.____ | |               ||    \----.________.----/ |',replace('.------------------------------------------.\n|  _________________           __          |\n|  \________________|)____.---''--`---.____ |\n|               ||    \----.________.----/ |\n| /X WarpSearch ||     / /    `--''         |\n|    V2.7     __||____/ /_    by Dres      |\n|            |___         \   & Crayor     |\n|                `--------''                |\n| Fastest zippy door for an /X filelist.   |\n| This is an AmiExpress BBS door.          |\n|                                          |\n`------------------------------------------''\n','\n',char(10)),'WarpSearch.doc',replace('WarpSearch_BBS V2.7 Documentation\n\n\nIntroduction\n------------\nThis is the AmiExpress version of WarpSearch.\nIt uses the boyer-moore search algorithm implemented in assembler code.\nThis algorithm is the fastest available.\n\n\nRevision History\n----------------\nFeatures\n--------\nV1.0:\n-pattern matching\n-asynchonous I/O\n-backwards/forwards counting of filelists\n-highlightning\n\nV2.0:\n-now real reverse search (search code / buffer loading / dir counting)\n-residentable\n-DMA optimized\n-prompts always behind complete descriptions\n-simple flagging, also "f file1.lha f file2.lha"\n-ndirs file is used to be s-express compatible if no ndirs tooltype exists\n-colors for the description output\n-configurable via tooltypes (of the WarpSearch executable) or WarpSearch.config file\n tooltypes override file config\n\nV2.1:\n-bugfixed V2.0\n If there were escape codes in the text of a file description the line was\n repeated in an infinite loop but you were able to quit the program at the\n prompt. No memory trashes or similar occured. This is fixed now. A harmless\n byte read from adress 0 in the shell version was wiped out too.\n \nV2.3:\n-added prompts if no args at start specified in bbs version\n-speedup due to asm code improvement and faster resource allocations (unbelieveable but true)\n-wildcard problem fixed\n-help rewritten\n\nV2.5\n-tag mode with scrolling\n-rewritten parse routine\n-some little fixes\n\nV2.7\n-changed date to amigadate\n-faster code due to optimized initialisation of load buffers\n-more error checking\n\nInstallation\n------------\nCopy "z.info" to "bbs:commands/bbscmd/".\nChange LOCATION to your full path of the WarpSearch executable.\nAdjust configuration if you like.\n\n\nUsage\n-----\n\nV2.5 introduces standard amiga command line parsing\n\nThis way you can search for spaces. z " scoopex" a -\n(enclose the pattern with " if the pattern includes blanks)\n\nIf you want to search for a pattern including " you have to use an asterix\n(*) char to override the special meanings of ".\n\nYou can check how your pattern was parsed if you look at the last line of the\nsearch process:\nDisplayed 7 descriptions that match the pattern  ".\n\nIn this example line " *"" was parsed to (space").\n\nYou have to add an asterix char (*) if you want to search for a pattern that\nlooks like a command line switch, like "-", so you have to write\n\nz *- a -  (or z -* a -)\n\ninstead of\n\nz - a -\n\nto search in all dirs reverse for the pattern "-".\n\n\nYou can write the command line in any order; e.g.\n\nz *- a -\n\nand\n\nz a - *-\n\nand\n\nz - a *-\n\nand so on are equal.\n\nNote, the above command line lets you search for all files new to old.\n\n\nSwitches are the templates with the /S appended.\n\nz /M,a=all/S,u=uldir/S,-=reverse/S,r=reverse/S,ns=nonstop/S,?=help/S\n\nbackwards compatible to /X z door:\n\nExample usage:\n"z foo"      (searches in upload dir for "foo" forwards).\n"z foo r"    (searches in upload dir reverse).\n\n"z foo 3 r"  (searches in dir3 reverse).\n"z foo a"    (searches from dir1 up for "foo").\n\n"z foo a -"  (searches from upload dir down for "foo" and searches reverse).\n"z foo 2"    (searches in dir2 only for "foo").\n\nWildcards in pattern are allowed, like "z foo*bar" or "z warp*V1.0*"\nUse "z foo*bar 2 +" to search from dir2 upwards. Default is downwards search.\nThe pattern must match an expression in one line.\nPatterns are not case sensitive. Only "*" is accepted as a wildcard and no\nother constructions like "#?","?" , which noone needs anyway in this application.\n\nUse "z ?" for short help.\n\nKnown Bugs\n----------\nIn V2.5 FLAG_COLOR tooltype must be exactly 5 chars long.\n\nInfo\n----\nDue to the boyer-moore algorithm the longer the pattern (w/o wildcards)\nthe shorter the search time.\n\nThe complete filedescription including filename etc. is searched through.\nWe, the authors, think that this magic code is the fastest search routine ever\nmade for an /X like filelist, because the 100% assembler boyer-moore search\nroutine with pattern matching and highlightning is optimized for cpu cycles by\nhand, some magic is done for splitted filedescriptions, asychronous I/O\noptimized even for 68040. (cache flushing problem)\n\nOn our system the bottleneck is the Fast-SCSI-II Baracuda drive with a\nFast-SCSI-II CyberSCSI Controller that does 7MB/s, and the code is 3 times\nfaster if the filelist is in RAM with 50MB/s burst.\n\nThe maximum length of a description line allowed is 1000 chars. Since /X\nallows 80 chars/line as maximum we think this is no bug. If a line is longer\nthan 1000 chars enforcer hits may occur. A check for line length would slow\ndown the code significantly. That`s why we don`t do it.\n\nFor those who are interested, a short explanation of what "double buffered\nasync I/O" means:\nDue to the coolness of the Amiga, SCSI is the most accepted standard on this\nplatform (..well if we dont consider 4000 desktops..). SCSI has the ability\nto transfer data per DMA, thus meaning without using the processor. This is\nwere async I/O comes in. A program using double buffered async I/O lets the\nfilesystem first fill up one buffer, then sends the request to fill up the\nsecond buffer, and while the HD is busy transfering data to the 2nd buffer the\nprocessor is free to do its work on the first one. As you can imagine this\ntechnique dramatically speeds up the whole process.\n\nShell version now included.\n\nA pseudo door that calls the door to be debugged is now developed. This way you\ncan use SAS/C`s debugger cpr easily. If you need it just ask.\n\nSend your suggestions or bug reports to [email removed] or\[email removed].\n\nReverse search is quite slow, because the seeking in the filelist (which is\neven asynchronous) takes 87% of the execution time on Crayor`s system (060&\nCyberScsi). Use a cache program like DynamiCache V1.02 by Christopher A. Wolf\nwith big memory values to make reverse search as fast as forwards search.\n\nMaybe a scsi RAID system could be a good solution for reverse searching too,\nif you have one please contact Crayor!\n\nFor the Amiga a "mini raid system" for 2 equal drives is available. If you have\nthis please contact Crayor. It seems to be software transparent and looks like\njust one scsi drive as I was told. This should almost double average transfer\nspeeds.\n\nMemory Requirements\n-------------------\nApprox. 2*blocksize*100 bytes which is about 100k for load buffers plus 20k\nfor print buffer plus code size\n(blocksize is usually 512 bytes)\n\nAmiExpress3.38 needs approx. 200k to run it.\n\nFor the screen buffer for tag mode add some k. They are needed even if you\ndon`t use tag mode.\n\nCurrently the last 150 screen lines are buffered for tag mode.\n\nGreetz\n------\nSome hellos to the following guys:\n\n"Ibo"  - with his always busy or down BBS, so that we weren`t able to abuse\n         his BBS for beta testing ;)\n         Thx for reporting a little bug.\n\nHijack - thx for the cool name of this door m8. (yep! "WarpSearch" actually was\n         his idea)\n\nSCSI   - for his help on using iwan.device and other help\n\nAmok   - for the address of Mr.F\n\nSTC    - for the competition of coding the fastest search code for /X filelists\n\nHydra  - for still developing hbbs\n\nDave Haynie\n       - for answering my several emails\n\nThe Baron (Mats N.)\n       - for reporting the (minor!?) esc-code bug in V2.0 that leeded to V2.1\n\nshadower (M. R. T.)\n       - for some good suggestions for V2.1\n\nTed    - for the Warp animation!\n\n\nLooking for good beta testers!\n\nCheck the aminet for the MUI and shell versions in /comm/amiex !!\n','\n',char(10)),NULL,'auto-added',79530,5,0,NULL,NULL,'ws_ae27','scan',1780048830);
INSERT INTO door_catalog VALUES('ws_ae271','WS-AE271.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/WS-AE271.LHA',NULL,'XIM','WarpSearch_ae.000',NULL,'Dres','WS','|  _________________           __          | |  \________________|)____.---''--`---.____ | |               ||    \----.________.----/ |',replace('.------------------------------------------.\n|  _________________           __          |\n|  \________________|)____.---''--`---.____ |\n|               ||    \----.________.----/ |\n| /X WarpSearch ||     / /    `--''         |\n|    V2.7.1   __||____/ /_    by Dres      |\n|      BBS   |___         \   & Crayor     |\n|                `--------''                |\n| Fastest zippy door for /X ,aminet and    |\n| compatible filelists.                    |\n|                                          |\n`------------------------------------------''\n','\n',char(10)),'WarpSearch_ae.doc',replace('WarpSearch_BBS V2.7 Documentation\n\n\nIntroduction\n------------\nThis is the AmiExpress version of WarpSearch.\nIt uses the boyer-moore search algorithm implemented in assembler code.\nThis algorithm is the fastest available.\n\n\nRevision History\n----------------\nFeatures\n--------\nV1.0:\n-pattern matching\n-asynchonous I/O\n-backwards/forwards counting of filelists\n-highlightning\n\nV2.0:\n-now real reverse search (search code / buffer loading / dir counting)\n-residentable\n-DMA optimized\n-prompts always behind complete descriptions\n-simple flagging, also "f file1.lha f file2.lha"\n-ndirs file is used to be s-express compatible if no ndirs tooltype exists\n-colors for the description output\n-configurable via tooltypes (of the WarpSearch executable) or WarpSearch.config file\n tooltypes override file config\n\nV2.1:\n-bugfixed V2.0\n If there were escape codes in the text of a file description the line was\n repeated in an infinite loop but you were able to quit the program at the\n prompt. No memory trashes or similar occured. This is fixed now. A harmless\n byte read from adress 0 in the shell version was wiped out too.\n \nV2.3:\n-added prompts if no args at start specified in bbs version\n-speedup due to asm code improvement and faster resource allocations (unbelieveable but true)\n-wildcard problem fixed\n-help rewritten\n\nV2.5\n-tag mode with scrolling\n-rewritten parse routine\n-some little fixes\n\nV2.7\n-changed date to amigadate\n-faster code due to optimized initialisation of load buffers\n-more error checking\n\nV2.7.1\n-bugfix for 36 nodes (only 10 nodes were supported before)\n\nInstallation\n------------\nCopy "z.info" to "bbs:commands/bbscmd/".\nChange LOCATION to your full path of the WarpSearch executable.\nAdjust configuration if you like.\n\n\nUsage\n-----\n\nV2.5 introduces standard amiga command line parsing\n\nThis way you can search for spaces. z " scoopex" a -\n(enclose the pattern with " if the pattern includes blanks)\n\nIf you want to search for a pattern including " you have to use an asterix\n(*) char to override the special meanings of ".\n\nYou can check how your pattern was parsed if you look at the last line of the\nsearch process:\nDisplayed 7 descriptions that match the pattern  ".\n\nIn this example line " *"" was parsed to (space").\n\nYou have to add an asterix char (*) if you want to search for a pattern that\nlooks like a command line switch, like "-", so you have to write\n\nz *- a -  (or z -* a -)\n\ninstead of\n\nz - a -\n\nto search in all dirs reverse for the pattern "-".\n\n\nYou can write the command line in any order; e.g.\n\nz *- a -\n\nand\n\nz a - *-\n\nand\n\nz - a *-\n\nand so on are equal.\n\nNote, the above command line lets you search for all files new to old.\n\n\nSwitches are the templates with the /S appended.\n\nz /M,a=all/S,u=uldir/S,-=reverse/S,r=reverse/S,ns=nonstop/S,?=help/S\n\nbackwards compatible to /X z door:\n\nExample usage:\n"z foo"      (searches in upload dir for "foo" forwards).\n"z foo r"    (searches in upload dir reverse).\n\n"z foo 3 r"  (searches in dir3 reverse).\n"z foo a"    (searches from dir1 up for "foo").\n\n"z foo a -"  (searches from upload dir down for "foo" and searches reverse).\n"z foo 2"    (searches in dir2 only for "foo").\n\nWildcards in pattern are allowed, like "z foo*bar" or "z warp*V1.0*"\nUse "z foo*bar 2 +" to search from dir2 upwards. Default is downwards search.\nThe pattern must match an expression in one line.\nPatterns are not case sensitive. Only "*" is accepted as a wildcard and no\nother constructions like "#?","?" , which noone needs anyway in this application.\n\nUse "z ?" for short help.\n\nKnown Bugs\n----------\nIn V2.5 FLAG_COLOR tooltype must be exactly 5 chars long.\n\nInfo\n----\nDue to the boyer-moore algorithm the longer the pattern (w/o wildcards)\nthe shorter the search time.\n\nThe complete filedescription including filename etc. is searched through.\nWe, the authors, think that this magic code is the fastest search routine ever\nmade for an /X like filelist, because the 100% assembler boyer-moore search\nroutine with pattern matching and highlightning is optimized for cpu cycles by\nhand, some magic is done for splitted filedescriptions, asychronous I/O\noptimized even for 68040. (cache flushing problem)\n\nOn our system the bottleneck is the Fast-SCSI-II Baracuda drive with a\nFast-SCSI-II CyberSCSI Controller that does 7MB/s, and the code is 3 times\nfaster if the filelist is in RAM with 50MB/s burst.\n\nThe maximum length of a description line allowed is 1000 chars. Since /X\nallows 80 chars/line as maximum we think this is no bug. If a line is longer\nthan 1000 chars enforcer hits may occur. A check for line length would slow\ndown the code significantly. That`s why we don`t do it.\n\nFor those who are interested, a short explanation of what "double buffered\nasync I/O" means:\nDue to the coolness of the Amiga, SCSI is the most accepted standard on this\nplatform (..well if we dont consider 4000 desktops..). SCSI has the ability\nto transfer data per DMA, thus meaning without using the processor. This is\nwere async I/O comes in. A program using double buffered async I/O lets the\nfilesystem first fill up one buffer, then sends the request to fill up the\nsecond buffer, and while the HD is busy transfering data to the 2nd buffer the\nprocessor is free to do its work on the first one. As you can imagine this\ntechnique dramatically speeds up the whole process.\n\nShell version now included.\n\nA pseudo door that calls the door to be debugged is now developed. This way you\ncan use SAS/C`s debugger cpr easily. If you need it just ask.\n\nSend your suggestions or bug reports to [email removed] or\[email removed].\n\nReverse search is quite slow, because the seeking in the filelist (which is\neven asynchronous) takes 87% of the execution time on Crayor`s system (060&\nCyberScsi). Use a cache program like DynamiCache V1.02 by Christopher A. Wolf\nwith big memory values to make reverse search as fast as forwards search.\n\nMaybe a scsi RAID system could be a good solution for reverse searching too,\nif you have one please contact Crayor!\n\nFor the Amiga a "mini raid system" for 2 equal drives is available. If you have\nthis please contact Crayor. It seems to be software transparent and looks like\njust one scsi drive as I was told. This should almost double average transfer\nspeeds.\n\nMemory Requirements\n-------------------\nApprox. 2*blocksize*100 bytes which is about 100k for load buffers plus 20k\nfor print buffer plus code size\n(blocksize is usually 512 bytes)\n\nAmiExpress3.38 needs approx. 200k to run it.\n\nFor the screen buffer for tag mode add some k. They are needed even if you\ndon`t use tag mode.\n\nCurrently the last 150 screen lines are buffered for tag mode.\n\nGreetz\n------\nSome hellos to the following guys:\n\n"Ibo"  - with his always busy or down BBS, so that we weren`t able to abuse\n         his BBS for beta testing ;)\n         Thx for reporting a little bug.\n\nHijack - thx for the cool name of this door m8. (yep! "WarpSearch" actually was\n         his idea)\n\nSCSI   - for his help on using iwan.device and other help\n\nAmok   - for the address of Mr.F\n\nSTC    - for the competition of coding the fastest search code for /X filelists\n\nHydra  - for still developing hbbs\n\nDave Haynie\n       - for answering my several emails\n\nThe Baron (Mats N.)\n       - for reporting the (minor!?) esc-code bug in V2.0 that leeded to V2.1\n\nshadower (M. R. T.)\n       - for some good suggestions for V2.1\n\nTed    - for the Warp animation!\n\n\nLooking for good beta testers!\n\nCheck the aminet for the MUI and shell versions in /comm/amiex !!\n','\n',char(10)),NULL,'auto-added',74179,1,0,NULL,NULL,'ws_ae271','scan',1780048830);
INSERT INTO door_catalog VALUES('ws_ae272','WS-AE272.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/WS-AE272.LHA',NULL,'XIM','WarpS_ae.000',NULL,'Dres','WS','|  _________________           __          | |  \________________|)____.---''--`---.____ | |               ||    \----.________.----/ |',replace('.------------------------------------------.\n|  _________________           __          |\n|  \________________|)____.---''--`---.____ |\n|               ||    \----.________.----/ |\n| /X WarpSearch ||     / /    `--''         |\n|    V2.7.2   __||____/ /_    by Dres      |\n|      BBS   |___         \   & Crayor     |\n|                `--------''                |\n| Fastest zippy door for /X ,aminet and    |\n| all compatible filelists.                |\n|                                          |\n`------------------------------------------''\n','\n',char(10)),'WarpS_ae.guide',replace('@database 0a2e98f8-0\n@master HeddleyCreation\n@$VER: 1.0\n@remark Created with Heddley v1.1 (c) Edd Dumbill 1994\n\n@node "Main" "WarpSearch Documentation"\nWarpSearch_BBS V2.7.2 Documentation\n\n\n    Contents\n\n    @{"Introduction" link "Introduction" 0}\n    @{"Revision History" link "Revision History" 0}\n    @{"Features" link "Revision History" 0}\n    @{"Installation" link "Installation" 0}\n    @{"Usage" link "Usage" 0}\n    @{"Known Bugs" link "Known Bugs" 0}\n    @{"General Infos" link "Info" 0}\n    @{"Memory Requirements" link "Memory Requirements" 0}\n    @{"Greetings" link "Greetz" 0}\n@endnode\n\n@node "Introduction" "Introduction"\nIntroduction\n------------\nThis is the AmiExpress version of WarpSearch.\nIt uses the boyer-moore search algorithm implemented in assembler code.\nThis algorithm is the fastest available.\n@endnode\n\n@node "Revision History" "Revision History"\n\nRevision History\n----------------\nFeatures\n--------\nV1.0:\n-pattern matching\n-asynchonous I/O\n-backwards/forwards counting of filelists\n-highlightning\n\nV2.0:\n-now real reverse search (search code / buffer loading / dir counting)\n-residentable\n-DMA optimized\n-prompts always behind complete descriptions\n-simple flagging, also "f file1.lha f file2.lha"\n-ndirs file is used to be s-express compatible if no ndirs tooltype exists\n-colors for the description output\n-configurable via tooltypes (of the WarpSearch executable) or WarpSearch.config file\n tooltypes override file config\n\nV2.1:\n-bugfixed V2.0\n If there were escape codes in the text of a file description the line was\n repeated in an infinite loop but you were able to quit the program at the\n prompt. No memory trashes or similar occured. This is fixed now. A harmless\n byte read from adress 0 in the shell version was wiped out too.\n \nV2.3:\n-added prompts if no args at start specified in bbs version\n-speedup due to asm code improvement and faster resource allocations (unbelieveable but true)\n-wildcard problem fixed\n-help rewritten\n\nV2.5\n-tag mode with scrolling\n-rewritten parse routine\n-some little fixes\n\nV2.7\n-changed date to amigadate\n-faster code due to optimized initialisation of load buffers\n-more error checking\n\nV2.7.1\n-bugfix for 36 nodes (only 10 nodes were supported before)\n\nV2.7.2\n- for each filelist the optimal buffer sizes are calculated now\n  and by this only one lock per filelist is used\n- exit procedures changed to remove a bug with outstanding packets\n\n@endnode\n\n\n@node "Installation" "Installation"\n\nInstallation\n------------\nCopy "z.info" to "bbs:commands/bbscmd/".\nChange LOCATION to your full path of the WarpSearch executable.\nAdjust configuration if you like.\n\n@endnode\n\n@node "Usage" "Usage"\n\nUsage\n-----\n\nV2.5 introduces standard amiga command line parsing\n\nThis way you can search for spaces. z " scoopex" a -\n(enclose the pattern with " if the pattern includes blanks)\n\nIf you want to search for a pattern including " you have to use an asterix\n(*) char to override the special meanings of ".\n\nYou can check how your pattern was parsed if you look at the last line of the\nsearch process:\nDisplayed 7 descriptions that match the pattern  ".\n\nIn this example line " *"" was parsed to (space").\n\nYou have to add an asterix char (*) if you want to search for a pattern that\nlooks like a command line switch, like "-", so you have to write\n\nz *- a -  (or z -* a -)\n\ninstead of\n\nz - a -\n\nto search in all dirs reverse for the pattern "-".\n\n\nYou can write the command line in any order; e.g.\n\nz *- a -\n\nand\n\nz a - *-\n\nand\n\nz - a *-\n\nand so on are equal.\n\nNote, the above command line lets you search for all files new to old.\n\n\nSwitches are the templates with the /S appended.\n\nz /M,a=all/S,u=uldir/S,-=reverse/S,r=reverse/S,ns=nonstop/S,?=help/S\n\nbackwards compatible to /X z door:\n\nExample usage:\n"z foo"      (searches in upload dir for "foo" forwards).\n"z foo r"    (searches in upload dir reverse).\n\n"z foo 3 r"  (searches in dir3 reverse).\n"z foo a"    (searches from dir1 up for "foo").\n\n"z foo a -"  (searches from upload dir down for "foo" and searches reverse).\n"z foo 2"    (searches in dir2 only for "foo").\n\nWildcards in pattern are allowed, like "z foo*bar" or "z warp*V1.0*"\nUse "z foo*bar 2 +" to search from dir2 upwards. Default is downwards search.\nThe pattern must match an expression in one line.\nPatterns are not case sensitive. Only "*" is accepted as a wildcard and no\nother constructions like "#?","?" , which noone needs anyway in this application.\n\nUse "z ?" for short help.\n\n@endnode\n\n@node "Known Bugs" "Known Bugs"\n\nKnown Bugs\n----------\nIn V2.5 FLAG_COLOR tooltype must be exactly 5 chars long.\n\n@endnode\n\n@node "Info" "Info"\n\nInfo\n----\nDue to the boyer-moore algorithm the longer the pattern (w/o wildcards)\nthe shorter the search time.\n\nThe complete filedescription including filename etc. is searched through.\nWe, the authors, think that this magic code is the fastest search routine ever\nmade for an /X like filelist, because the 100% assembler boyer-moore search\nroutine with pattern matching and highlightning is optimized for cpu cycles by\nhand, some magic is done for splitted filedescriptions, asychronous I/O\noptimized even for 68040. (cache flushing problem)\n\nOn our system the bottleneck is the Fast-SCSI-II Baracuda drive with a\nFast-SCSI-II CyberSCSI Controller that does 7MB/s, and the code is 3 times\nfaster if the filelist is in RAM with 50MB/s burst.\n\nThe maximum length of a description line allowed is 1000 chars. Since /X\nallows 80 chars/line as maximum we think this is no bug. If a line is longer\nthan 1000 chars enforcer hits may occur. A check for line length would slow\ndown the code significantly. That`s why we don`t do it.\n\nFor those who are interested, a short explanation of what "double buffered\nasync I/O" means:\nDue to the coolness of the Amiga, SCSI is the most accepted standard on this\nplatform (..well if we dont consider 4000 desktops..). SCSI has the ability\nto transfer data per DMA, thus meaning without using the processor. This is\nwere async I/O comes in. A program using double buffered async I/O lets the\nfilesystem first fill up one buffer, then sends the request to fill up the\nsecond buffer, and while the HD is busy transfering data to the 2nd buffer the\nprocessor is free to do its work on the first one. As you can imagine this\ntechnique dramatically speeds up the whole process.\n\nSend your suggestions or bug reports to [email removed] or\[email removed].\n\nReverse search is quite slow, because the seeking in the filelist (which is\neven asynchronous) takes 87% of the execution time on Crayor`s system (060&\nCyberScsi). Use a cache program like DynamiCache V1.02 by Christopher A. Wolf\nwith big memory values to make reverse search as fast as forwards search.\n\nMaybe a scsi RAID system could be a good solution for reverse searching too,\nif you have one please contact Crayor!\n\nFor the Amiga a "mini raid system" for 2 equal drives is available. If you have\nthis please contact Crayor. It seems to be software transparent and looks like\njust one scsi drive as I was told. This should almost double average transfer\nspeeds.\n\n@endnode\n\n@node "Memory Requirements" "Memory Requirements"\n\nMemory Requirements\n-------------------\nApprox. 2*blocksize*100 bytes which is about 100k for load buffers plus 20k\nfor print buffer plus code size\n(blocksize is usually 512 bytes)\n\nAmiExpress3.38 needs approx. 200k to run it.\n\nFor the screen buffer for tag mode add some k. They are needed even if you\ndon`t use tag mode.\n\nCurrently the last 150 screen lines are buffered for tag mode.\n\n@endnode\n\n@node "Greetz" "Greetz"\n\nGreetz\n------\nSome hellos to the following guys:\n\n"Ibo"  - with his always busy or down BBS, so that we weren`t able to abuse\n         his BBS for beta testing ;)\n         Thx for reporting a little bug.\n\nHijack - thx for the cool name of this door m8. (yep! "WarpSearch" actually was\n         his idea)\n\nSCSI   - for his help on using iwan.device and other help\n\nAmok   - for the address of Mr.F\n\nSTC    - for the competition of coding the fastest search code for /X filelists\n\nHydra  - for still developing hbbs\n\nDave Haynie\n       - for answering my several emails\n\nThe Baron (Mats N.)\n       - for reporting the (minor!?) esc-code bug in V2.0 that leeded to V2.1\n\nshadower (M. R. T.)\n       - for some good suggestions for V2.1\n\nTed    - for the Warp animation!\n\n@endnode\n\n','\n',char(10)),NULL,'auto-added',58353,3,0,NULL,NULL,'ws_ae272','scan',1780048830);
