INSERT INTO door_catalog VALUES('ws_mui40','WS-MUI40.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/WS-MUI40.LHA',NULL,'XIM','WarpS_MUI.060',NULL,'Dres','WS','|  _________________           __          | |  \________________|)____.---''--`---.____ | |               ||    \----.________.----/ |',replace('.------------------------------------------.\n|  _________________           __          |\n|  \________________|)____.---''--`---.____ |\n|               ||    \----.________.----/ |\n| /X WarpSearch ||     / /    `--''         |\n|     V4.0    __||____/ /_    by Dres      |\n|      MUI   |___         \   & Crayor     |\n|                `--------''                |\n| Fastest zippy door for /X ,aminet and    |\n| all compatible filelists.                |\n| This is a real MUI application !         |\n|                                          |\n`------------------------------------------''\n','\n',char(10)),'mastrb8.txt',replace(replace('STILL GOING STRONG in 2014!\r\n\r\n                ___         ._            _______             ·\r\n   /\  _________)  \________| \___________)__   /_________:__ :________\r\n  /  \/\  __  \    ____ ___/|  \______  \_  / _/___  \_ ____/ ¦__ \___ \\r\n /   /  \ \__  \___  \  |   |   \  _/  __/ /    /\__  \  |¦   | /  \_|  \\r\n/  \/    \_ \   \ !   \_|   !    \_\    \_     /   \   \ ||   |·    /|   \_\r\n\___|     ___\  /__    /l________ /_\    /__  /_____\  / |¦   |    /_|    /\r\n    l____/-A×E\/  \___/_!       \/   \  /   \/       \/__|:   ¦__ /  l___/\r\n       ______            _____        \/      :    ____   ·   : \/\r\n    ___)     \___________)    \__________:___ ¦____)   \__________\r\n    \    _______     _______    \___    ____/ |\_____   \______   \\r\n   /\___   \/        |    _)    \/       ¦    |/    |    \    |    \\r\n _/    !    \        |    \      \_      |    |     !     \   |     \\r\n \______     \___    |_____\      /___   |    ¦            \  |      \_\r\n       \______/ \____!      \    /   \___|   