INSERT INTO door_catalog VALUES('xcall100','XCALL100.LHA','~/Code/amiexpress_doors/Archives/AmiExpress/XCALL100.LHA',NULL,'XIM','XCaller - The best and most efficient','1.00',NULL,NULL,'last caller bulletin generating program around.  Coded in ''C'', this program is extremely fast and well designed.  Output',replace('XCaller v1.00 - The best and most efficient\nlast caller bulletin generating program\naround.  Coded in ''C'', this program is\nextremely fast and well designed.  Output\nis geared towards 16 colour users but looks\ngood for 8 colour users as well - none of\nthat stupid orange.  Dload and view the\nYou won''t regret it.\n','\n',char(10)),'rots.txt',replace('                                C A L L       \n                               ~~~~~~~~~\n                                 N O W\n                                ~~~~~~~                \n  ___________ ________ _____________________________________ ________\n__\           \__      \_       \_______  \__      \__       \__     \__\n\               /       /  |      /    /    /   \____/         / \___  /\n \_____   _____/ ______/        _/  __/   _/   _____/   ______/\___  \/\n   _/       |        \     |    |         |    \   |        \         \\n   \________|____|    \____l____|_________|________|____|    \________/MC\n                 l_____\                                l_____\\n  sYS0p : CaPslOCKman/R^D  c0SyS : bLaDe/PSI - pRayEr/trsI \n  ____ ___ ________________________ __________________\n__\   |   |   \__         \_        \_     \________  \__   4.nodEs.\n\     |   |     /   |      /         /      /      /    / +49-ASK-FOR!\n \    |   |   _/    |    _/   ______/      /__  __/   _/   RunninG oN\n \\   l   l   |     |    |        \       /   |       | A3000/33MHZ/14MB\n   \__________|__________|____|    \__________|_______| /X4.xx/ 1.4 GIG`S                              l_____\\n  \n      RAVE^DESIGN-EHQ   MDMA-DIST-SIDE`  PGS-GHQ  CLOSED-USER-SYSTEM\n \n       << AMIGA/ ADULTS/ ASCII/ /X-T